INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (12163,'The Evil Below') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','The Evil Below',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12164,'Час ворга','Время пришло, $n. Аругал должен умереть.$B$BСобери несколько верных товарищей и отправляйся на Остров Кровавой Луны. Ты найдешь его на востоке, недалеко от побережья.$B$BМы нанесем стремительный удар. Возьми на себя лейтенантов Аругала, а я присоединюсь к тебе, когда дело дойдет до битвы с главарем.','Мы хорошенько потрепали его, $N. Жаль, не удалось с ним покончить.$B$BВпрочем, теперь мы можем вздохнуть свободно – он не осмелится больше сунуть сюда свой нос.','Рада видеть тебя, $N.','Вернитесь к Саше в Торговую лавку Белой Сосны, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Час ворга',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Время пришло, $n. Аругал должен умереть.$B$BСобери несколько верных товарищей и отправляйся на Остров Кровавой Луны. Ты найдешь его на востоке, недалеко от побережья.$B$BМы нанесем стремительный удар. Возьми на себя лейтенантов Аругала, а я присоединюсь к тебе, когда дело дойдет до битвы с главарем.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мы хорошенько потрепали его, $N. Жаль, не удалось с ним покончить.$B$BВпрочем, теперь мы можем вздохнуть свободно – он не осмелится больше сунуть сюда свой нос.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Рада видеть тебя, $N.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Саше в Торговую лавку Белой Сосны, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12165,'Коварный план','Геолог Рокар решил нам помочь и разработал план, как обернуть изобретения железных дворфов против их самих. $B$BНадо признать, от нашего нового лучшего друга все-таки есть какая-то польза. В одном он точно прав – нас слишком мало, чтобы действовать открыто. $B$BИди в Дун Аргол, в заснеженный край на юго-востоке, и захвати чертежи их боевых големов, которые носят с собой железные кователи рун. Доставь чертежи Рокару – пусть приступает к осуществлению своего плана.','Принесите полный комплект чертежей боевого голема геологу Рокару в Лагерь Уанква.','Ты... ты принес чертежи?','Вернитесь к геологу Рокару в лагерь Уанква, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Коварный план',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Геолог Рокар решил нам помочь и разработал план, как обернуть изобретения железных дворфов против их самих. $B$BНадо признать, от нашего нового лучшего друга все-таки есть какая-то польза. В одном он точно прав – нас слишком мало, чтобы действовать открыто. $B$BИди в Дун Аргол, в заснеженный край на юго-востоке, и захвати чертежи их боевых големов, которые носят с собой железные кователи рун. Доставь чертежи Рокару – пусть приступает к осуществлению своего плана.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите полный комплект чертежей боевого голема геологу Рокару в Лагерь Уанква.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты... ты принес чертежи?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к геологу Рокару в лагерь Уанква, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12166,'Жидкое пламя Элуны','По просьбе стража-смотрителя Джоди Песни Луны из Покоя Звезд воспользуйтесь жидким пламенем Элуны для очищения трупов 6 гнилостных маралов и 6 бешеных гризли.','Мы сделали для существ, обитающих на этой земле, все, что могли. А теперь мы должны предпринять решительные действия против тех, кто причинил все это!','Жаль, что мы не можем исцелить медведей и лосей, ставших жертвами присутствия Плети.$B$BПо крайней мере, мы можем предотвратить дальнейшее распространение заразы.','Вернитесь к стражу-смотрителю Джоди Песне Луны в Покой Звезд, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жидкое пламя Элуны',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По просьбе стража-смотрителя Джоди Песни Луны из Покоя Звезд воспользуйтесь жидким пламенем Элуны для очищения трупов 6 гнилостных маралов и 6 бешеных гризли.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мы сделали для существ, обитающих на этой земле, все, что могли. А теперь мы должны предпринять решительные действия против тех, кто причинил все это!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Жаль, что мы не можем исцелить медведей и лосей, ставших жертвами присутствия Плети.$B$BПо крайней мере, мы можем предотвратить дальнейшее распространение заразы.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к стражу-смотрителю Джоди Песне Луны в Покой Звезд, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12167,'Убить сектантов','Ануб\'арские сектанты виновны, пусть и косвенно, в эпидемии среди животных. Мы обязаны положить этому конец!$b$bПары, исходящие от костюмов сектантов, впитываются во все, что только есть поблизости, загрязняя и отравляя землю и воду!$b$bСтупай на север, в деревню Ледяной Пыли, и перебей их. Принеси те их костюмы, что останутся целы после битвы – я позабочусь о том, чтобы ликвидировать их должным образом.','Соберите 5 рабочих костюмов сектантов по просьбе стража-смотрителя Джоди Песни Луны из Покоя Звезд.','Сектанты – это язва на лике творения!','Вернитесь к стражу-смотрителю Джоди Песне Луны в Покой Звезд, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Убить сектантов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ануб\'арские сектанты виновны, пусть и косвенно, в эпидемии среди животных. Мы обязаны положить этому конец!$b$bПары, исходящие от костюмов сектантов, впитываются во все, что только есть поблизости, загрязняя и отравляя землю и воду!$b$bСтупай на север, в деревню Ледяной Пыли, и перебей их. Принеси те их костюмы, что останутся целы после битвы – я позабочусь о том, чтобы ликвидировать их должным образом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 5 рабочих костюмов сектантов по просьбе стража-смотрителя Джоди Песни Луны из Покоя Звезд.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Сектанты – это язва на лике творения!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к стражу-смотрителю Джоди Песне Луны в Покой Звезд, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (12168,'Памятный дар Зангуса','Надпись на обратной стороне памятного дара гласит:$B$B"Моему любимому ученику. Если продолжишь делать успехи – я научу тебя невообразимым чудесам.$B$BА если нет – я тебя уничтожу!$B$BВсегда твой,$B$BВерховный сектант Зангус"$B$BНесомненно, стража-смотрителя из Покоя Звезд это заинтересует.','Принесите памятный дар Зангуса стражу-смотрителю Джоди Песни Луны в Покой Звезд.','Итак, лидер сектантов раскрыл себя. У нас есть его имя.$B$BТщеславие и гордыня станут причинами его падения!','Вернитесь к стражу-смотрителю Джоди Песне Луны в Покой Звезд, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Памятный дар Зангуса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Надпись на обратной стороне памятного дара гласит:$B$B"Моему любимому ученику. Если продолжишь делать успехи – я научу тебя невообразимым чудесам.$B$BА если нет – я тебя уничтожу!$B$BВсегда твой,$B$BВерховный сектант Зангус"$B$BНесомненно, стража-смотрителя из Покоя Звезд это заинтересует.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите памятный дар Зангуса стражу-смотрителю Джоди Песни Луны в Покой Звезд.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Итак, лидер сектантов раскрыл себя. У нас есть его имя.$B$BТщеславие и гордыня станут причинами его падения!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к стражу-смотрителю Джоди Песне Луны в Покой Звезд, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12169,'Верховный сектант','Мне и раньше грезился Зангус, но без контекста, открытого тобой, я не знала, что все это значило. Ты $gвнес:внесла; ясность в видение, которым богиня одарила меня, и теперь я знаю, что его можно найти в Провале Наржуна к северу отсюда.$B$BТы знаешь свою цель, $n. Если можно положить конец страданиям этой земли, верховный сектант должен умереть!','По заданию Стража-смотрителя Джоди Песни Луны из Покоя Звезд убейте верховного сектанта Зангуса.','Я чувствую, что верховный сектант Зангус еще жив.$B$BЧто-то не так, $N? Возможно, тебе сначала нужно отдохнуть?','Вернитесь к стражу-смотрителю Джоди Песне Луны в Покой Звезд, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Верховный сектант',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне и раньше грезился Зангус, но без контекста, открытого тобой, я не знала, что все это значило. Ты $gвнес:внесла; ясность в видение, которым богиня одарила меня, и теперь я знаю, что его можно найти в Провале Наржуна к северу отсюда.$B$BТы знаешь свою цель, $n. Если можно положить конец страданиям этой земли, верховный сектант должен умереть!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По заданию Стража-смотрителя Джоди Песни Луны из Покоя Звезд убейте верховного сектанта Зангуса.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я чувствую, что верховный сектант Зангус еще жив.$B$BЧто-то не так, $N? Возможно, тебе сначала нужно отдохнуть?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к стражу-смотрителю Джоди Песне Луны в Покой Звезд, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (12170,'Схватка в Черноречье','Капитан налетчиков Кронн просит вас убить 10 представителей или игроков Альянса на Лесопилке Черноречья.','Вернитесь к капитану налетчиков Кронну в Седые холмы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Схватка в Черноречье',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Капитан налетчиков Кронн просит вас убить 10 представителей или игроков Альянса на Лесопилке Черноречья.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану налетчиков Кронну в Седые холмы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (12171,'О предателях и предательстве','Думаю, этот список следует доставить главнокомандующему Халфорду Змеевержцу! Он командует 7-м легионом, стоящим в крепости Стражей Зимы на восточной границе Драконьего Погоста.$b$bЕсли кто-то из предателей, упомянутых в этом списке, находится в крепости Стражей Зимы... это может привести к катастрофе!$b$bСкорее, $n! Покажи этот документ Палене Серебряное Облако здесь, в Покое Звезд, и объясни, куда и зачем ты направляешься. Она даст тебе самого быстрого из своих гиппогрифов!','Покажите депешу Альянса Палене Серебряное Облако в Покое Звезд.','Вернитесь к Палене Серебряное Облако в Покой Звезд, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','О предателях и предательстве',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Думаю, этот список следует доставить главнокомандующему Халфорду Змеевержцу! Он командует 7-м легионом, стоящим в крепости Стражей Зимы на восточной границе Драконьего Погоста.$b$bЕсли кто-то из предателей, упомянутых в этом списке, находится в крепости Стражей Зимы... это может привести к катастрофе!$b$bСкорее, $n! Покажи этот документ Палене Серебряное Облако здесь, в Покое Звезд, и объясни, куда и зачем ты направляешься. Она даст тебе самого быстрого из своих гиппогрифов!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Покажите депешу Альянса Палене Серебряное Облако в Покое Звезд.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Палене Серебряное Облако в Покой Звезд, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12172,'Настройка на Даларан','Добро пожаловать, маг.$B$BДо сих пор тебе, должно быть, интересно где же находится Даларан и как туда попасть. Я помогу тебе.$B$BНо прежде чем я научу тебя телепортироваться в наш великий город, тебе нужно настроиться на силовые линии Нордскола.$B$BВозьми этот кристалл настройки и используй его в провале под волноловом у Садов Лунного Покоя к западу отсюда. Тогда ты будешь $gготов:готова; выучить нужное заклинание.','По заданию проекции верховного мага Модеры в Покое Звезд настройтесь на силовые линии Нордскола.','Отлично. Если ты $Gготов:готова;, то и я тоже.','Ты $Gготов:готова;? Ты не $Gдолжен:должна; лгать, $N.$B$BЕсли ты не подготовишься должным образом и я научу тебя заклинанию, твое заклинание в первый раз будет последним в твоей жизни!','Вернитесь к проекции верховного мага Модеры в Покой Звезд, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Настройка на Даларан',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Добро пожаловать, маг.$B$BДо сих пор тебе, должно быть, интересно где же находится Даларан и как туда попасть. Я помогу тебе.$B$BНо прежде чем я научу тебя телепортироваться в наш великий город, тебе нужно настроиться на силовые линии Нордскола.$B$BВозьми этот кристалл настройки и используй его в провале под волноловом у Садов Лунного Покоя к западу отсюда. Тогда ты будешь $gготов:готова; выучить нужное заклинание.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По заданию проекции верховного мага Модеры в Покое Звезд настройтесь на силовые линии Нордскола.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично. Если ты $Gготов:готова;, то и я тоже.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gготов:готова;? Ты не $Gдолжен:должна; лгать, $N.$B$BЕсли ты не подготовишься должным образом и я научу тебя заклинанию, твое заклинание в первый раз будет последним в твоей жизни!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к проекции верховного мага Модеры в Покой Звезд, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (12173,'Настройка на Даларан','Приветствую тебя, маг.$B$BДолжно быть, тебе интересно, где же находится Даларан и как туда попасть. Я помогу тебе, если сумеешь пройти простенький тест.$B$BПрежде чем я научу тебя телепортироваться в наш великий город, тебе нужно настроиться на силовые линии Нордскола. Иначе ты просто умрешь в процессе перемещения!$B$BВозьми этот кристалл настройки и используй его в провале под волноловом у Садов Лунного Покоя к юго-западу отсюда. Тогда ты будешь $gготов:готова; узнать то, чему я могу тебя научить.','По заданию проекции верховного мага Этаса Похитителя Солнца в Молоте Агмара настройтесь на силовые линии Нордскола.','Вернитесь к проекции верховного мага Этаса Похитителя Солнца в Молот Агмара, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Настройка на Даларан',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приветствую тебя, маг.$B$BДолжно быть, тебе интересно, где же находится Даларан и как туда попасть. Я помогу тебе, если сумеешь пройти простенький тест.$B$BПрежде чем я научу тебя телепортироваться в наш великий город, тебе нужно настроиться на силовые линии Нордскола. Иначе ты просто умрешь в процессе перемещения!$B$BВозьми этот кристалл настройки и используй его в провале под волноловом у Садов Лунного Покоя к юго-западу отсюда. Тогда ты будешь $gготов:готова; узнать то, чему я могу тебя научить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По заданию проекции верховного мага Этаса Похитителя Солнца в Молоте Агмара настройтесь на силовые линии Нордскола.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к проекции верховного мага Этаса Похитителя Солнца в Молот Агмара, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (12174,'Главнокомандующий Халфорд Змеевержец','<Палена возвращает вам послание.>$B$BМетель доставит тебя к Стражам Зимы. Можешь поверить, это будет самый быстрый полет в твоей жизни. Отправляйся прямо сейчас!','Доставьте депешу Альянса главнокомандующему Халфорду Змеевержцу в крепость Стражей Зимы в восточной части Драконьего Погоста.','<Прочитав послание, главнокомандующий сминает его в руке.>$B$BТы знаешь, где теперь все те люди, что перечислены в этом списке? Вон, посмотри – там, у главных ворот. Это они там свисают с арок.$B$BПриманка для вурдалаков…','Вернитесь к главнокомандующему Халфорду Змеевержцу в Крепость Стражей Зимы, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Главнокомандующий Халфорд Змеевержец',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Палена возвращает вам послание.>$B$BМетель доставит тебя к Стражам Зимы. Можешь поверить, это будет самый быстрый полет в твоей жизни. Отправляйся прямо сейчас!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте депешу Альянса главнокомандующему Халфорду Змеевержцу в крепость Стражей Зимы в восточной части Драконьего Погоста.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Прочитав послание, главнокомандующий сминает его в руке.>$B$BТы знаешь, где теперь все те люди, что перечислены в этом списке? Вон, посмотри – там, у главных ворот. Это они там свисают с арок.$B$BПриманка для вурдалаков…',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к главнокомандующему Халфорду Змеевержцу в Крепость Стражей Зимы, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12175,'Серые шкуры воргов','Я тебе вот что скажу, $gдружище:подруга;: паршивая это работенка – заниматься обмундированием для солдат Орды!$B$BА тут еще эта волчица, Завоевательница Кренна, кнутом подгоняет. Вынь да положь ей полный комплект обмундирования к концу недели – иначе сбросит меня в яму к медведям.$B$BПомоги мне – а я уж в долгу не останусь. Мне нужны шкуры серо-дымчатых охотников.$B$BИх легко найти на севере, где они гоняются за оленями. Учти, я тебе хорошо заплачу!','Шкуры у тебя, подруга ?','Вернитесь к торговцу шкурами Джун\'ику в Крепость Завоевателей, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Серые шкуры воргов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я тебе вот что скажу, $gдружище:подруга;: паршивая это работенка – заниматься обмундированием для солдат Орды!$B$BА тут еще эта волчица, Завоевательница Кренна, кнутом подгоняет. Вынь да положь ей полный комплект обмундирования к концу недели – иначе сбросит меня в яму к медведям.$B$BПомоги мне – а я уж в долгу не останусь. Мне нужны шкуры серо-дымчатых охотников.$B$BИх легко найти на севере, где они гоняются за оленями. Учти, я тебе хорошо заплачу!',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Шкуры у тебя, подруга ?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к торговцу шкурами Джун\'ику в Крепость Завоевателей, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (12176,'Мелкая подмена','Кренна хочет сменить обмундирование нашего войска и пошить новое из шкур воргов – а наших запасов, естественно, не хватит, чтобы одеть всю армию. Хоть ты лопни, не наберется у нас столько шкур!$B$BТощие они, эти ворги, и меха с них – кот наплакал. Но у меня есть идея! Могу и с тобой поделиться – если обещаешь держать язык за зубами.$B$BК востоку от Волдруна живут медведи гризли, жирные как огры. Их огромные шкуры мы могли бы пустить в дело!$B$BДавай, $gбратишка:сестренка;, принимайся за дело. Кренна ждать не любит.','Торговец шкурами Джун\'ик просит вас принести ему 6 шкур медведей гризли.','Я у тебя в долгу, дорогуша. Вот, держи свою долю.','Вернитесь к торговцу шкурами Джун\'ику в Крепость Завоевателей, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мелкая подмена',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кренна хочет сменить обмундирование нашего войска и пошить новое из шкур воргов – а наших запасов, естественно, не хватит, чтобы одеть всю армию. Хоть ты лопни, не наберется у нас столько шкур!$B$BТощие они, эти ворги, и меха с них – кот наплакал. Но у меня есть идея! Могу и с тобой поделиться – если обещаешь держать язык за зубами.$B$BК востоку от Волдруна живут медведи гризли, жирные как огры. Их огромные шкуры мы могли бы пустить в дело!$B$BДавай, $gбратишка:сестренка;, принимайся за дело. Кренна ждать не любит.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Торговец шкурами Джун\'ик просит вас принести ему 6 шкур медведей гризли.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я у тебя в долгу, дорогуша. Вот, держи свою долю.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к торговцу шкурами Джун\'ику в Крепость Завоевателей, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (12177,'Уловка Джун\'ика','Ой... кажется, у нас возникла проблема. Эти шкуры... они коричневого цвета! $B$BДумай, думай, голова...$B$BВо, придумал! Серый цвет – это помесь белого и черного, верно? Тащи сюда уголь и муку! Я их перемешаю и посыплю шкуры этой пудрой. Никто и не заметит!$B$BТак... уголь продают кузнецы, а муку можно достать у поставщика.','Вернитесь к торговцу шкурами Джун\'ику в Крепость Завоевателей, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уловка Джун\'ика',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ой... кажется, у нас возникла проблема. Эти шкуры... они коричневого цвета! $B$BДумай, думай, голова...$B$BВо, придумал! Серый цвет – это помесь белого и черного, верно? Тащи сюда уголь и муку! Я их перемешаю и посыплю шкуры этой пудрой. Никто и не заметит!$B$BТак... уголь продают кузнецы, а муку можно достать у поставщика.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к торговцу шкурами Джун\'ику в Крепость Завоевателей, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12178,'Сверток для Кренны','Вот, $gдружище:подруга;. Давай-ка отнесем эти шкуры Кренне и посмотрим, как она отреагирует.$B$BОчень надеюсь, что она ничего не заметит.','Ты хоть знаешь, с кем разговариваешь?','Вернитесь к завоевательнице Кренне в Крепость Завоевателей, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сверток для Кренны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот, $gдружище:подруга;. Давай-ка отнесем эти шкуры Кренне и посмотрим, как она отреагирует.$B$BОчень надеюсь, что она ничего не заметит.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты хоть знаешь, с кем разговариваешь?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к завоевательнице Кренне в Крепость Завоевателей, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (12179,'Specialization 1 [PH]','DESCRIPTION: Complete this quest for Specialization 1.','LOG: Complete this quest for Specialization 1.','Вернитесь к Джонатану Лекрафту.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Specialization 1 [PH]',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','DESCRIPTION: Complete this quest for Specialization 1.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','LOG: Complete this quest for Specialization 1.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джонатану Лекрафту.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12180,'Пленные геологи','Регар послал в Дун Аргол отряд старателей, поручив им поиски артефактов и информации о происхождении сего поселения. Правда, они не ожидали обнаружить, что Дун Аргол до сих пор обитаем.$B$BТеперь железные дворфы держат их пленниками, пешками в грядущей войне. У нас нет людей, которых мы могли бы послать им на помощь, а Регар витает в облаках, мечтая о победе над железными дворфами без посторонней помощи.$B$BВся надежда на тебя, $n. Ключи от клеток могут быть у любого железного дворфа или его прислужника.','Освободите геолога Ганна, геолога Торгана и геолога Варана, после чего вернитесь к горному пехотинцу Килиану в Лагерь горняков.','Ты $Gнашел:нашла; пропавших без вести геологов?','Вернитесь к горному пехотинцу Килиану в Лагерь горняков, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пленные геологи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Регар послал в Дун Аргол отряд старателей, поручив им поиски артефактов и информации о происхождении сего поселения. Правда, они не ожидали обнаружить, что Дун Аргол до сих пор обитаем.$B$BТеперь железные дворфы держат их пленниками, пешками в грядущей войне. У нас нет людей, которых мы могли бы послать им на помощь, а Регар витает в облаках, мечтая о победе над железными дворфами без посторонней помощи.$B$BВся надежда на тебя, $n. Ключи от клеток могут быть у любого железного дворфа или его прислужника.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Освободите геолога Ганна, геолога Торгана и геолога Варана, после чего вернитесь к горному пехотинцу Килиану в Лагерь горняков.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gнашел:нашла; пропавших без вести геологов?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к горному пехотинцу Килиану в Лагерь горняков, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12181,'Имя для заразы','Сколько дней, сколько бессонных ночей... Знаешь ли ты, как давно мы приступили к работе над этой проклятой чумой? Нас преследовали неудачи, но мы наконец одержали победу! Смотри! Я еще даже не придумал название для этой гнили... Точно! ГНИЛЬ! Эта гниль разрушит само представление о нетленности бытия!$B$B<Харрис протягивает вам склянку.>$B$BБеги к Тобиасу, дрессировщику нетопырей. Покажи ему этот образец – пусть он немедленно отправит тебя в Ядозлобь.','Покажите образец гнили Тобиасу Саркхоффу в Новом Агамонде.','Э... все понятно, можешь не показывать мне образец. Я тебе верю.','Доставка смертельно ядовитого газа в Ядозлобь? Это ко мне!','Вернитесь к Тобиасу Саркхоффу в Новый Агамонд, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Имя для заразы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сколько дней, сколько бессонных ночей... Знаешь ли ты, как давно мы приступили к работе над этой проклятой чумой? Нас преследовали неудачи, но мы наконец одержали победу! Смотри! Я еще даже не придумал название для этой гнили... Точно! ГНИЛЬ! Эта гниль разрушит само представление о нетленности бытия!$B$B<Харрис протягивает вам склянку.>$B$BБеги к Тобиасу, дрессировщику нетопырей. Покажи ему этот образец – пусть он немедленно отправит тебя в Ядозлобь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Покажите образец гнили Тобиасу Саркхоффу в Новом Агамонде.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Э... все понятно, можешь не показывать мне образец. Я тебе верю.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Доставка смертельно ядовитого газа в Ядозлобь? Это ко мне!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тобиасу Саркхоффу в Новый Агамонд, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12182,'В Ядозлобь!','Вот, я оставил для тебя специального нетопыря. Он самый быстрый и ловкий из всех, что у меня есть! Доставит тебя прямо в Ядозлобь – глазом моргнуть не успеешь.$B$BА там просто передай этот флакон главному распространителю чумы Миддлтону.','Передайте образец гнили Главному распространителю чумы Миддлтону, который живет в Ядозлоби на востоке Драконьего Погоста.','О, превосходно! Ты только посмотри – прямо за горой, на северо-востоке, ползет целая армия Плети! С нее-то мы и начнем испытания.','Ты посыльный?','Вернитесь к главному распространителю чумы Миддлтону в Драконий Погост.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В Ядозлобь!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот, я оставил для тебя специального нетопыря. Он самый быстрый и ловкий из всех, что у меня есть! Доставит тебя прямо в Ядозлобь – глазом моргнуть не успеешь.$B$BА там просто передай этот флакон главному распространителю чумы Миддлтону.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Передайте образец гнили Главному распространителю чумы Миддлтону, который живет в Ядозлоби на востоке Драконьего Погоста.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, превосходно! Ты только посмотри – прямо за горой, на северо-востоке, ползет целая армия Плети! С нее-то мы и начнем испытания.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты посыльный?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к главному распространителю чумы Миддлтону в Драконий Погост.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (12183,'Часть маскировки','Если геолог Варана права, и с Локеном общаются только некоторые высокопоставленные дворфы, то я могу поспорить, что в их число входят надзиратели.$B$BНам придется послать тебя на разведку под прикрытием, для чего надо раздобыть для тебя подходящую униформу. $B$BЗатем я постараюсь придумать, как загримировать тебя под одного из железных дворфов.$B$BВ общем, отправляйся в Дун Аргол, убей одного из надзирателей и принеси мне его униформу. Учти, зальешь ее кровью – будешь отстирывать $gсам:сама;!','Принесите униформу надзирателя горному пехотинцу Килиану в Лагерь горняков.','<Килиан забирает у вас униформу.>$B$BСойдет. Извини, у меня нет времени вышивать на ней твое имя. Зато когда я закончу работать над твоим гримом, никто не отличит тебя от настоящего надзирателя!','Вернитесь к горному пехотинцу Килиану в Лагерь горняков, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Часть маскировки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если геолог Варана права, и с Локеном общаются только некоторые высокопоставленные дворфы, то я могу поспорить, что в их число входят надзиратели.$B$BНам придется послать тебя на разведку под прикрытием, для чего надо раздобыть для тебя подходящую униформу. $B$BЗатем я постараюсь придумать, как загримировать тебя под одного из железных дворфов.$B$BВ общем, отправляйся в Дун Аргол, убей одного из надзирателей и принеси мне его униформу. Учти, зальешь ее кровью – будешь отстирывать $gсам:сама;!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите униформу надзирателя горному пехотинцу Килиану в Лагерь горняков.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Килиан забирает у вас униформу.>$B$BСойдет. Извини, у меня нет времени вышивать на ней твое имя. Зато когда я закончу работать над твоим гримом, никто не отличит тебя от настоящего надзирателя!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к горному пехотинцу Килиану в Лагерь горняков, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (12184,'Улыбайтесь, вас снимают!','Отлично! У нас есть униформа, и не хватает только немного дополнительной информации, чтобы сделать маскировку идеальной.$B$BЯ тут вспомнил, что Регар привез с собой фотокамеру – отснять результаты исследований, но мы найдем для нее другое применение. Возьми ее с собой в Дун Аргол и сделай несколько снимков железных дворфов.$B$BКонечно, твои модели вряд ли обрадуются такой популярности, так что тебе придется их немного... утихомирить. И не забудь вернуть мне камеру со снимками!','С помощью камеры Килиана сделайте снимки 8 железных дворфов в Дун Арголе, после чего вернитесь к горному пехотинцу Килиану в Лагерь горняков.','Прекрасные фотографии! С их помощью мы с легкостью замаскируем тебя под железного дворфа. Никто и не догадается!','Вернитесь к горному пехотинцу Килиану в Лагерь горняков, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Улыбайтесь, вас снимают!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Отлично! У нас есть униформа, и не хватает только немного дополнительной информации, чтобы сделать маскировку идеальной.$B$BЯ тут вспомнил, что Регар привез с собой фотокамеру – отснять результаты исследований, но мы найдем для нее другое применение. Возьми ее с собой в Дун Аргол и сделай несколько снимков железных дворфов.$B$BКонечно, твои модели вряд ли обрадуются такой популярности, так что тебе придется их немного... утихомирить. И не забудь вернуть мне камеру со снимками!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','С помощью камеры Килиана сделайте снимки 8 железных дворфов в Дун Арголе, после чего вернитесь к горному пехотинцу Килиану в Лагерь горняков.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасные фотографии! С их помощью мы с легкостью замаскируем тебя под железного дворфа. Никто и не догадается!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к горному пехотинцу Килиану в Лагерь горняков, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12185,'Лучшая маскировка для Локена','С помощью этих изображений я смог сделать отличный набор для маскировки. $gДружище:Подруга;, из тебя получится отличный железный дворф!$B$BВот, возьми этот сверток в Дун Аргол, замаскируйся и отправляйся к самому восточному зданию на центральном ярусе.$B$BТам ты увидишь пьедестал, с помощью которого главы кланов и надзиратели получают указания от Локена. Прикоснись к нему и запомни все, что услышишь.','Неужто Локен не преувеличивает? Каменные и железные дети титанов сражаются за власть в древнем городе Ульдуаре? Это безумие, $N, и оно может уничтожить наш единственный шанс узнать тайну происхождения расы дворфов!','Маскировка сработала?','Вернитесь к горному пехотинцу Килиану в Лагерь горняков, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лучшая маскировка для Локена',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','С помощью этих изображений я смог сделать отличный набор для маскировки. $gДружище:Подруга;, из тебя получится отличный железный дворф!$B$BВот, возьми этот сверток в Дун Аргол, замаскируйся и отправляйся к самому восточному зданию на центральном ярусе.$B$BТам ты увидишь пьедестал, с помощью которого главы кланов и надзиратели получают указания от Локена. Прикоснись к нему и запомни все, что услышишь.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Неужто Локен не преувеличивает? Каменные и железные дети титанов сражаются за власть в древнем городе Ульдуаре? Это безумие, $N, и оно может уничтожить наш единственный шанс узнать тайну происхождения расы дворфов!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Маскировка сработала?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к горному пехотинцу Килиану в Лагерь горняков, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (12186,'УКАЗАТЕЛЬ: Победитель') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','УКАЗАТЕЛЬ: Победитель',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (12187,'УКАЗАТЕЛЬ: Участник') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','УКАЗАТЕЛЬ: Участник',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12188,'Гниль Отрекшихся и вы: как не заразиться самим','Знать во всех подробностях о том, как действует гниль, тебе, пожалуй, ни к чему. Главное, свое дело она делает. Мне удалось вывести инертный штамм гнили.$b$b<Миддлтон открывает пробирку и вдыхает ее содержимое.>$b$bКак видишь, мое тело практически не пострадало. Но если теперь смешать это с нужным реактивом, все мы обратимся в бесформенные лужи слизи.$b$bНа побережье к югу отсюда находятся жалкие призраки древних солдат Альянса. Перебей их и принеси мне эктоплазменный осадок.','Принесите главному распространителю чумы Миддлтону из Ядозлоби в Драконьем Погосте 10 образцов эктоплазменного осадка.','Осадок необходим для изготовления реактива, который активирует штамм!','Вернитесь к главному распространителю чумы Миддлтону в Ядозлобь, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гниль Отрекшихся и вы: как не заразиться самим',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Знать во всех подробностях о том, как действует гниль, тебе, пожалуй, ни к чему. Главное, свое дело она делает. Мне удалось вывести инертный штамм гнили.$b$b<Миддлтон открывает пробирку и вдыхает ее содержимое.>$b$bКак видишь, мое тело практически не пострадало. Но если теперь смешать это с нужным реактивом, все мы обратимся в бесформенные лужи слизи.$b$bНа побережье к югу отсюда находятся жалкие призраки древних солдат Альянса. Перебей их и принеси мне эктоплазменный осадок.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите главному распространителю чумы Миддлтону из Ядозлоби в Драконьем Погосте 10 образцов эктоплазменного осадка.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Осадок необходим для изготовления реактива, который активирует штамм!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к главному распространителю чумы Миддлтону в Ядозлобь, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (12189,'Меня окружают идиоты!','Груз из Нового Агамонда должен был прибыть в Ядозлобь на прошлой неделе, а потом его должны были передать мне после простейших полевых испытаний. Это последнее, чего недостает Орде для победы.$b$b<Синтар вздыхает.>$B$BКак же тяжко жить, когда кругом одни идиоты!$b$bОтправляйся в Ядозлобь, что близ восточных границ Драконьего Погоста. Отыщи этого шута Миддлтона и напомни ему, что я жду свой груз!','Отправляйтесь в Ядозлобь в Драконьем Погосте и поговорите с главным распространителем чумы Миддлтоном.','У нас тут, знаете ли, небольшая проблемка. Все, кто пытался иметь дело с этой заразой, испарились на месте. Мы работаем над тем, чтобы несколько изменить формулу. Ну, чтобы она не убивала на месте любого, кто взглянул на нее краем глаза. Но есть и хорошие новости. Мне, кажется, удалось получить нужный состав!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Меня окружают идиоты!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Груз из Нового Агамонда должен был прибыть в Ядозлобь на прошлой неделе, а потом его должны были передать мне после простейших полевых испытаний. Это последнее, чего недостает Орде для победы.$b$b<Синтар вздыхает.>$B$BКак же тяжко жить, когда кругом одни идиоты!$b$bОтправляйся в Ядозлобь, что близ восточных границ Драконьего Погоста. Отыщи этого шута Миддлтона и напомни ему, что я жду свой груз!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Ядозлобь в Драконьем Погосте и поговорите с главным распространителем чумы Миддлтоном.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','У нас тут, знаете ли, небольшая проблемка. Все, кто пытался иметь дело с этой заразой, испарились на месте. Мы работаем над тем, чтобы несколько изменить формулу. Ну, чтобы она не убивала на месте любого, кто взглянул на нее краем глаза. Но есть и хорошие новости. Мне, кажется, удалось получить нужный состав!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12190,'Поздоровайся с моим маленьким другом','У Харкора челюсть отвалится, когда он увидит такие отборные продукты! Осталось только решить вопрос с доставкой.$b$bОн разбил лагерь на восточном краю леса, рядом с проклятыми руинами Дракил\'джин, так что добраться до него проще простого. Ну что, отнесешь ему ингредиенты – или предпочитаешь помочь мне с бальзамировкой трупов?','Пригмон просит вас отнести ингредиенты для Харкора в Лагерь Харкора.','Чего тебе?','Разыщите Харкора в Лагере Харкора, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поздоровайся с моим маленьким другом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У Харкора челюсть отвалится, когда он увидит такие отборные продукты! Осталось только решить вопрос с доставкой.$b$bОн разбил лагерь на восточном краю леса, рядом с проклятыми руинами Дракил\'джин, так что добраться до него проще простого. Ну что, отнесешь ему ингредиенты – или предпочитаешь помочь мне с бальзамировкой трупов?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Пригмон просит вас отнести ингредиенты для Харкора в Лагерь Харкора.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Чего тебе?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Разыщите Харкора в Лагере Харкора, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (12191,'Пей до дна!','Ха... Крепкий С.С.М.... Хмм... Кто бы мог подумать?$B$BТо есть ура, ты $Gпопал:попала;! Рука у тебя тверда, по крайне мере, лагерь защитишь. Теперь, думаю, ты вполне $Gготов:готова; надавать парням из клана Черного Железа, если эти дворфы еще осмелятся сунуть сюда свой нос!','Вернитесь к Биззлю Эхпрокачуну в Дуротар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пей до дна!',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ха... Крепкий С.С.М.... Хмм... Кто бы мог подумать?$B$BТо есть ура, ты $Gпопал:попала;! Рука у тебя тверда, по крайне мере, лагерь защитишь. Теперь, думаю, ты вполне $Gготов:готова; надавать парням из клана Черного Железа, если эти дворфы еще осмелятся сунуть сюда свой нос!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Биззлю Эхпрокачуну в Дуротар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (12192,'Однажды, напившись в...','Нам удалось на время остановить клан Черного Железа, но они вернулись и жаждут мести! Они то и дело выныривают невесть откуда, выпивают наше пиво и убегают в "Угрюмого обжору". Первым делом нам надо защитить наш лагерь, если мы сохраним наш бочонок – это будет победа!','Поговорите с Биззлем Эхпрокачуном в лагере Хмельного фестиваля.','Значит, даже немалое количество выпитого пива не помешало тебе расстроить зловещие планы клана Черного железа? Вот это действительно в духе Хмельного фестиваля! Полагаю, ты $Gзаслужил:заслужила; призовые жетоны.$B$BСпасибо за помощь, $N. Веселого тебе Хмельного фестиваля!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Однажды, напившись в...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нам удалось на время остановить клан Черного Железа, но они вернулись и жаждут мести! Они то и дело выныривают невесть откуда, выпивают наше пиво и убегают в "Угрюмого обжору". Первым делом нам надо защитить наш лагерь, если мы сохраним наш бочонок – это будет победа!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Биззлем Эхпрокачуном в лагере Хмельного фестиваля.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Значит, даже немалое количество выпитого пива не помешало тебе расстроить зловещие планы клана Черного железа? Вот это действительно в духе Хмельного фестиваля! Полагаю, ты $Gзаслужил:заслужила; призовые жетоны.$B$BСпасибо за помощь, $N. Веселого тебе Хмельного фестиваля!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12193,'А не будет ли сувенирчика в нынешнем году?','Главное на Хмельном фестивале – не гонки на баранах, а выпивка! Улучи минутку и отдай свой купон Белби Быстросмен. Она стоит за поляной, на которой проходит Хмельной фестиваль. Если ты ее не увидишь, не беспокойся, она-то тебя всяко заметит.$b$bВ общем, отдай ей свой купон, и получишь бесплатную праздничную кружку. Кроме того, именно Белби занимается прочей праздничной торговлей.','Отоварьте свой купон на праздничную кружку у Белби Быстросмен в лагере Хмельного фестиваля.','Аххх, всего лишь за бесплатным пивом... Может, ты просто стесняешься? Ладно-ладно, вот тебе бесплатная кружечка.$b$bЧао, увидимся. Ты ведь захочешь отоварить и другие праздничные жетоны... Помни, я вся твоя...$b$bИли его... $b$bМожет, его...','Что такое, $gкрасавчик:крошка;? Ты ко мне по делу?','Вернитесь к Белби Быстросмен в Дун Морог.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','А не будет ли сувенирчика в нынешнем году?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Главное на Хмельном фестивале – не гонки на баранах, а выпивка! Улучи минутку и отдай свой купон Белби Быстросмен. Она стоит за поляной, на которой проходит Хмельной фестиваль. Если ты ее не увидишь, не беспокойся, она-то тебя всяко заметит.$b$bВ общем, отдай ей свой купон, и получишь бесплатную праздничную кружку. Кроме того, именно Белби занимается прочей праздничной торговлей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отоварьте свой купон на праздничную кружку у Белби Быстросмен в лагере Хмельного фестиваля.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Аххх, всего лишь за бесплатным пивом... Может, ты просто стесняешься? Ладно-ладно, вот тебе бесплатная кружечка.$b$bЧао, увидимся. Ты ведь захочешь отоварить и другие праздничные жетоны... Помни, я вся твоя...$b$bИли его... $b$bМожет, его...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что такое, $gкрасавчик:крошка;? Ты ко мне по делу?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Белби Быстросмен в Дун Морог.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12194,'А не будет ли сувенирчика в нынешнем году?','Мы не только поим всех подряд, но и дарим пивные кружки! Красивые, памятные кружки, полученные совершенно законным образом! Вот тебе купон на такую кружку.$b$bПоговори с Бликсом рядом с лагерем Хмельного фестиваля. Он довольно странный тип, тем более, что очки эти никогда не снимает. Он и отоварит твой купон. Он же занимается прочей праздничной торговлей.','Отоварьте свой купон на праздничную кружку у Бликса Чиништукса в лагере Хмельного фестиваля.','Аххх, всего лишь за бесплатным пивом... Может, ты просто стесняешься? Ладно-ладно, вот тебе бесплатная кружечка.$b$bЧао, увидимся. Ты ведь захочешь отоварить и другие праздничные жетоны... Помни, я вся твоя...$b$bИли его... $b$bМожет, его...','Что такое, $gкрасавчик:крошка;? Ты ко мне по делу?','Вернитесь к Бликсу Чиништуксу в Дуротар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','А не будет ли сувенирчика в нынешнем году?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы не только поим всех подряд, но и дарим пивные кружки! Красивые, памятные кружки, полученные совершенно законным образом! Вот тебе купон на такую кружку.$b$bПоговори с Бликсом рядом с лагерем Хмельного фестиваля. Он довольно странный тип, тем более, что очки эти никогда не снимает. Он и отоварит твой купон. Он же занимается прочей праздничной торговлей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отоварьте свой купон на праздничную кружку у Бликса Чиништукса в лагере Хмельного фестиваля.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Аххх, всего лишь за бесплатным пивом... Может, ты просто стесняешься? Ладно-ладно, вот тебе бесплатная кружечка.$b$bЧао, увидимся. Ты ведь захочешь отоварить и другие праздничные жетоны... Помни, я вся твоя...$b$bИли его... $b$bМожет, его...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что такое, $gкрасавчик:крошка;? Ты ко мне по делу?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бликсу Чиништуксу в Дуротар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12195,'Незваный гость','Недавно наши охотники вернулись с вылазки с необычной добычей.$B$BОни наткнулись на раненого дворфа, бежавшего из крепости железных дворфов Дун Аргол. Возможно, он мог бы предоставить нам ценную информацию о нашем старом противнике, но пока что он не в состоянии говорить из-за сильной лихорадки.$B$BЯ слышал, что для изготовления лекарств отлично подходят рога серебристых оленей, которые бродят по ближайшему лесу. Если ты принесешь мне достаточное количество рогов, я позабочусь о том, чтобы разговорить нашего дорогого гостя.','Принесите 5 рогов взрослых оленей Тормаку Бывалому из Лагеря Уанква.','Да, эти рога вполне сгодятся для настойки. Посмотрим, поможет ли она.','Ты принес рога?','Вернитесь к Тормаку Бывалому в лагерь Уанква, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Незваный гость',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Недавно наши охотники вернулись с вылазки с необычной добычей.$B$BОни наткнулись на раненого дворфа, бежавшего из крепости железных дворфов Дун Аргол. Возможно, он мог бы предоставить нам ценную информацию о нашем старом противнике, но пока что он не в состоянии говорить из-за сильной лихорадки.$B$BЯ слышал, что для изготовления лекарств отлично подходят рога серебристых оленей, которые бродят по ближайшему лесу. Если ты принесешь мне достаточное количество рогов, я позабочусь о том, чтобы разговорить нашего дорогого гостя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 5 рогов взрослых оленей Тормаку Бывалому из Лагеря Уанква.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, эти рога вполне сгодятся для настойки. Посмотрим, поможет ли она.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты принес рога?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тормаку Бывалому в лагерь Уанква, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12196,'С самого начала','У нас слишком мало времени, чтобы самим браться за ковку. Литейные мастерские в Дун Арголе работают день и ночь, и пока мы выкуем детали для одного конструкта, они соберут десять таких же големов из готовых запчастей. $B$BТы $gдолжен:должна; вернуться обратно и раздобыть детали, упомянутые в этих чертежах.$B$BДолжно быть, они валяются повсюду вокруг зданий, где работают железные кователи рун. $B$BПоторопись, $n. Кажется, Тормак только и ищет предлога для того, чтобы выполнить свою угрозу!','Принесите 8 частей боевого голема геологу Рокару в Лагерь Уанква.','Т-ты ведь несешь мне запчасти, правда?','Вернитесь к геологу Рокару в лагерь Уанква, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','С самого начала',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У нас слишком мало времени, чтобы самим браться за ковку. Литейные мастерские в Дун Арголе работают день и ночь, и пока мы выкуем детали для одного конструкта, они соберут десять таких же големов из готовых запчастей. $B$BТы $gдолжен:должна; вернуться обратно и раздобыть детали, упомянутые в этих чертежах.$B$BДолжно быть, они валяются повсюду вокруг зданий, где работают железные кователи рун. $B$BПоторопись, $n. Кажется, Тормак только и ищет предлога для того, чтобы выполнить свою угрозу!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 8 частей боевого голема геологу Рокару в Лагерь Уанква.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Т-ты ведь несешь мне запчасти, правда?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к геологу Рокару в лагерь Уанква, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12197,'Нам нужна энергия','Итак, я полностью закончил сборку оболочки голема, но Тормаку этого мало. Он просто не понимает, что механизм не заработает сам по себе, по его велению! Чтобы включить его, нам понадобятся батареи.$B$BВ Дун Арголе созданием зарядных ячеек занимаются два дворфа – рунический кузнец Дурар и рунический кузнец Каторн.$B$BЧтобы наш голем заработал, в него надо установить две энергобатареи.$B$BНайди этих рунических кузнецов. Их мастерские должны быть в самом центре Дун Аргола.','Принесите энергобатареи Дурара и Каторна Геологу Рокару в Лагерь Уанква.','Ты нашел энергобатареи?','Вернитесь к геологу Рокару в лагерь Уанква, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нам нужна энергия',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Итак, я полностью закончил сборку оболочки голема, но Тормаку этого мало. Он просто не понимает, что механизм не заработает сам по себе, по его велению! Чтобы включить его, нам понадобятся батареи.$B$BВ Дун Арголе созданием зарядных ячеек занимаются два дворфа – рунический кузнец Дурар и рунический кузнец Каторн.$B$BЧтобы наш голем заработал, в него надо установить две энергобатареи.$B$BНайди этих рунических кузнецов. Их мастерские должны быть в самом центре Дун Аргола.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите энергобатареи Дурара и Каторна Геологу Рокару в Лагерь Уанква.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты нашел энергобатареи?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к геологу Рокару в лагерь Уанква, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (12198,'... а может быть, и нет','Энергобатарея голема практически разряжена. Ее заряда хватит для питания двигателя, но на оборонные системы можно не рассчитывать.$B$BК счастью, периметр Дун Аргола патрулируют грозовые караульные – от них мы сможем подзарядить батарею.$B$BПодведи голема поближе, и он впитает энергию после смерти часового.','Подзарядите вашего Боевого голема от десяти грозовых караульных и вернитесь к геологу Рокару в Лагерь Уанква.','Вернитесь к геологу Рокару в лагерь Уанква, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','... а может быть, и нет',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Энергобатарея голема практически разряжена. Ее заряда хватит для питания двигателя, но на оборонные системы можно не рассчитывать.$B$BК счастью, периметр Дун Аргола патрулируют грозовые караульные – от них мы сможем подзарядить батарею.$B$BПодведи голема поближе, и он впитает энергию после смерти часового.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Подзарядите вашего Боевого голема от десяти грозовых караульных и вернитесь к геологу Рокару в Лагерь Уанква.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к геологу Рокару в лагерь Уанква, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12199,'Свержение железного тана','Теперь, когда голем полностью заряжен, мы сможем свергнуть предводителя Дун Аргола с его помощью.$B$BПока я шпионил за таном Гневным Топором, я заметил, что его повсюду сопровождает личный голем-телохранитель.$B$BЗовут это чудовище Наковальня, но он не так неуязвим, как кажется. Один электромагнитный импульс может разрушить его изнутри и отключить защитную функцию. Возьми нашего голема и активируй его в периметре Дун Аргола.$B$BТы найдешь тана на вершине главного завода, где он инспектирует производство.','Воспользовавшись особой функцией вашего Боевого голема, убейте железного тана Гневного Топора, после чего вернитесь к Тормаку Бывалому в Лагерь Уанква.','Значит, геолог сдержал слово? Это хорошо. Я уж было начал сомневаться в целесообразности его работы.\n\nЖаль, но больше он нам не пригодится.','Пожалуйста, скажи мне, что все получилось...','Вернитесь к Тормаку Бывалому в лагерь Уанква, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Свержение железного тана',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда голем полностью заряжен, мы сможем свергнуть предводителя Дун Аргола с его помощью.$B$BПока я шпионил за таном Гневным Топором, я заметил, что его повсюду сопровождает личный голем-телохранитель.$B$BЗовут это чудовище Наковальня, но он не так неуязвим, как кажется. Один электромагнитный импульс может разрушить его изнутри и отключить защитную функцию. Возьми нашего голема и активируй его в периметре Дун Аргола.$B$BТы найдешь тана на вершине главного завода, где он инспектирует производство.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользовавшись особой функцией вашего Боевого голема, убейте железного тана Гневного Топора, после чего вернитесь к Тормаку Бывалому в Лагерь Уанква.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Значит, геолог сдержал слово? Это хорошо. Я уж было начал сомневаться в целесообразности его работы.\n\nЖаль, но больше он нам не пригодится.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Пожалуйста, скажи мне, что все получилось...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тормаку Бывалому в лагерь Уанква, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12200,'Слезы изумрудного дракона','Теперь, когда инертный образец чумного состава завершен и у нас имеется активирующее его вещество, остается лишь найти подходящее вместилище для этих компонентов.$B$BК юго-западу отсюда, на берегах в центре Драконьего Погоста, находится Изумрудное святилище драконов. Внутри святилища ты найдешь затвердевшие остатки слез зеленого дракона. Я не знаю всей истории, но, видимо, перед смертью они немало плачут. Иди $gсам:сама; посмотри.$B$BОтправляйся в Изумрудное святилище драконов и принеси оттуда слезы.','Принесите 8 слез изумрудного дракона главному распространителю чумы Миддлтону в Ядозлобь в Драконьем Погосте.','Нам повезло, что рядом с нами есть место, в котором в избытке слезы изумрудных драконов. Иначе мне пришлось бы посылать тебя за ними в Фералас.','Вернитесь к главному распространителю чумы Миддлтону в Ядозлобь, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Слезы изумрудного дракона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда инертный образец чумного состава завершен и у нас имеется активирующее его вещество, остается лишь найти подходящее вместилище для этих компонентов.$B$BК юго-западу отсюда, на берегах в центре Драконьего Погоста, находится Изумрудное святилище драконов. Внутри святилища ты найдешь затвердевшие остатки слез зеленого дракона. Я не знаю всей истории, но, видимо, перед смертью они немало плачут. Иди $gсам:сама; посмотри.$B$BОтправляйся в Изумрудное святилище драконов и принеси оттуда слезы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 8 слез изумрудного дракона главному распространителю чумы Миддлтону в Ядозлобь в Драконьем Погосте.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Нам повезло, что рядом с нами есть место, в котором в избытке слезы изумрудных драконов. Иначе мне пришлось бы посылать тебя за ними в Фералас.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к главному распространителю чумы Миддлтону в Ядозлобь, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (12201,'Тень надзирателя','Принесите униформу надзирателя Разведчику Вор\'такху в Лагерь Уанква.','Отлично, эта униформа нам очень пригодится. Но нам понадобится еще кое-какой грим. Иначе даже эти тупоголовые железные дворфы узнают в тебе переодетого шпиона.','Вернитесь к разведчику Вор\'такху в лагерь Уанква, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тень надзирателя',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите униформу надзирателя Разведчику Вор\'такху в Лагерь Уанква.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, эта униформа нам очень пригодится. Но нам понадобится еще кое-какой грим. Иначе даже эти тупоголовые железные дворфы узнают в тебе переодетого шпиона.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к разведчику Вор\'такху в лагерь Уанква, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (12202,'Улыбайтесь, вас снимают!','Теперь нам осталось только сделать тебя $gпохожим:похожей; на железных дворфов.$B$BХорошо бы иметь перед собой образец, с которого мы будем копировать их мерзкие рожи.$B$BЯ тут вспомнил, что однажды охотничий отряд Тормака наткнулся на заблудившегося геолога и отобрал у него фотокамеру в качестве трофея. Пожалуй, теперь она нам пригодится.$B$BВозьми ее с собой в Дун Аргол, убей несколько железных дворфов и запечатлей их физиономии. Как сделаешь достаточное количество фотографий, возвращайся ко мне.','С помощью камеры Рокара сделайте снимки 8 железных дворфов в Дун Арголе, после чего вернитесь к Разведчик Вор\'такху в Лагерь Уанква.','То, что надо! Во имя Гарроша, ну и мерзкие рожи!','Вернитесь к разведчику Вор\'такху в лагерь Уанква, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Улыбайтесь, вас снимают!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь нам осталось только сделать тебя $gпохожим:похожей; на железных дворфов.$B$BХорошо бы иметь перед собой образец, с которого мы будем копировать их мерзкие рожи.$B$BЯ тут вспомнил, что однажды охотничий отряд Тормака наткнулся на заблудившегося геолога и отобрал у него фотокамеру в качестве трофея. Пожалуй, теперь она нам пригодится.$B$BВозьми ее с собой в Дун Аргол, убей несколько железных дворфов и запечатлей их физиономии. Как сделаешь достаточное количество фотографий, возвращайся ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','С помощью камеры Рокара сделайте снимки 8 железных дворфов в Дун Арголе, после чего вернитесь к Разведчик Вор\'такху в Лагерь Уанква.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','То, что надо! Во имя Гарроша, ну и мерзкие рожи!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к разведчику Вор\'такху в лагерь Уанква, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12203,'Приказы Локена','Вот, я собрал все, что надо для того, чтобы замаскировать тебя под надзирателя. Знаю, выглядит мерзко, но ты уж постарайся сдержать свои эмоции, когда будешь напяливать эту гадость. Ну, ты понимаешь – надо, чтобы в тебе никто не усомнился.$B$BДержи маскировочный набор и отправляйся на юго-восток, к Дун Арголу. Там переоденься и иди к самому восточному зданию в центральной части города.$B$BТам ты увидишь пьедестал, где надзиратели получают указания от Локена. Прикоснись к пьедесталу и запомни все, что услышишь.','Что ты $Gузнал:узнала; о Локене?','Вернитесь к разведчику Вор\'такху в лагерь Уанква, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приказы Локена',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот, я собрал все, что надо для того, чтобы замаскировать тебя под надзирателя. Знаю, выглядит мерзко, но ты уж постарайся сдержать свои эмоции, когда будешь напяливать эту гадость. Ну, ты понимаешь – надо, чтобы в тебе никто не усомнился.$B$BДержи маскировочный набор и отправляйся на юго-восток, к Дун Арголу. Там переоденься и иди к самому восточному зданию в центральной части города.$B$BТам ты увидишь пьедестал, где надзиратели получают указания от Локена. Прикоснись к пьедесталу и запомни все, что услышишь.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что ты $Gузнал:узнала; о Локене?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к разведчику Вор\'такху в лагерь Уанква, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12204,'Во имя Локена','Железные дворфы были и остаются нашими самыми организованными и жестокими конкурентами за влаcть в Нордсколе. Куда бы мы не сунулись, они всюду преследуют нас с именем Локена на устах.$B$BМы должны узнать, кто такой этот Локен и чего он добивается.$B$BК северо-востоку отсюда есть Торговая лавка Красного леса, в которой торгует человек по имени Хью Гласс. А на востоке, среди Руины Тетиса, обитает каменный великан Гаврок. Эти двое могут рассказать тебе кое-что полезное о Локене.','Поговорите с Хью Глассом и Гавроком о Локене, после чего передайте полученные сведения разведчику Вор\'такху из лагеря Уанква.','Значит, он руководит военной кампанией железных дворфов? Мы должны узнать, что они замышляют!','Что тебе удалось обнаружить?','Вернитесь к разведчику Вор\'такху в лагерь Уанква, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Во имя Локена',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Железные дворфы были и остаются нашими самыми организованными и жестокими конкурентами за влаcть в Нордсколе. Куда бы мы не сунулись, они всюду преследуют нас с именем Локена на устах.$B$BМы должны узнать, кто такой этот Локен и чего он добивается.$B$BК северо-востоку отсюда есть Торговая лавка Красного леса, в которой торгует человек по имени Хью Гласс. А на востоке, среди Руины Тетиса, обитает каменный великан Гаврок. Эти двое могут рассказать тебе кое-что полезное о Локене.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Хью Глассом и Гавроком о Локене, после чего передайте полученные сведения разведчику Вор\'такху из лагеря Уанква.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Значит, он руководит военной кампанией железных дворфов? Мы должны узнать, что они замышляют!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что тебе удалось обнаружить?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к разведчику Вор\'такху в лагерь Уанква, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12205,'Приказом верховного палача Роса все члены незаконной организации, известной как Алый Натиск, подлежат немедленной казни на месте!$b$bПощады не давать никому. Тем, кто участвует в этом деле, следует иметь в виду, что любой, попавший в плен к людям, будет убит, или того хуже.$b$bКак сказал верховный палач, "Пусть белый снег станет красным от их крови!"','Убейте 20 членов Алого Натиска и доложите об этом верховному палачу Росу из Ядозлоби.','Очень удачно вы подвернулись. А то я уж боялся, что придется самому идти коней добывать!','Вернитесь к верховному палачу Росу в Ядозлобь, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приказом верховного палача Роса все члены незаконной организации, известной как Алый Натиск, подлежат немедленной казни на месте!$b$bПощады не давать никому. Тем, кто участвует в этом деле, следует иметь в виду, что любой, попавший в плен к людям, будет убит, или того хуже.$b$bКак сказал верховный палач, "Пусть белый снег станет красным от их крови!"',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 20 членов Алого Натиска и доложите об этом верховному палачу Росу из Ядозлоби.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Очень удачно вы подвернулись. А то я уж боялся, что придется самому идти коней добывать!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному палачу Росу в Ядозлобь, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12206,'Испорченные последние ритуалы','Ты $gчитал:читала; доску объявлений? Что думает верховный палач?$B$B<Вики оглядывается и продолжает на пониженных тонах.>$B$BМы же не можем позволить, чтобы этих идиотов из Алого Натиска подняли их жрецы или, что еще хуже, чтобы они были подняты как воины Плети, правда?$B$BНет, я полностью с тобой согласна, мы просто должны что-то сделать с телами.$B$BИ у меня есть то, что нужно. Возьми этот настой порчи, что мы только что изготовили, и опробуй его на пленнике, сидящем в клетке – здесь, рядом.$B$BНикаких заморочек – никакого возвращения врагов.','По просьбе аптекаря Вики Левин из Ядозлоби испробуйте настой порчи на узнике Алого Натиска.','Ну что там, готово?\n\nЭй, я ж забыла тебе сказать, чтобы ты по возможности на себя не пролил этого добра! Гадкое зелье, пятна потом не выведешь, не говоря уж о том, сколько времени придется залечивать язвы и раны от отваливающихся кусков плоти.','Вернитесь к Аптекарю Вики Левин в Ядозлобь, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Испорченные последние ритуалы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gчитал:читала; доску объявлений? Что думает верховный палач?$B$B<Вики оглядывается и продолжает на пониженных тонах.>$B$BМы же не можем позволить, чтобы этих идиотов из Алого Натиска подняли их жрецы или, что еще хуже, чтобы они были подняты как воины Плети, правда?$B$BНет, я полностью с тобой согласна, мы просто должны что-то сделать с телами.$B$BИ у меня есть то, что нужно. Возьми этот настой порчи, что мы только что изготовили, и опробуй его на пленнике, сидящем в клетке – здесь, рядом.$B$BНикаких заморочек – никакого возвращения врагов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По просьбе аптекаря Вики Левин из Ядозлоби испробуйте настой порчи на узнике Алого Натиска.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что там, готово?\n\nЭй, я ж забыла тебе сказать, чтобы ты по возможности на себя не пролил этого добра! Гадкое зелье, пятна потом не выведешь, не говоря уж о том, сколько времени придется залечивать язвы и раны от отваливающихся кусков плоти.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аптекарю Вики Левин в Ядозлобь, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (12207,'Падение Фордрассила','Давным-давно некие могущественные друиды посадили мировое древо на северо-востоке.$B$BИмя ему было Фордрассил. По неведомой причине те же самые друиды решили уничтожить его, когда оно выросло.$B$BИ вот, с тех пор, как мы прибыли сюда, я слышу плач земли. Она стонет, ибо ядовитая слизь разъедает ее в тех местах, где упали обломки великого древа. $B$BПрошу тебя, принеси мне образцы этой слизи, и я попытаюсь исцелить землю.','Вернитесь к заклинательнице ветра Серый Рог в Крепость Завоевателей, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Падение Фордрассила',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Давным-давно некие могущественные друиды посадили мировое древо на северо-востоке.$B$BИмя ему было Фордрассил. По неведомой причине те же самые друиды решили уничтожить его, когда оно выросло.$B$BИ вот, с тех пор, как мы прибыли сюда, я слышу плач земли. Она стонет, ибо ядовитая слизь разъедает ее в тех местах, где упали обломки великого древа. $B$BПрошу тебя, принеси мне образцы этой слизи, и я попытаюсь исцелить землю.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к заклинательнице ветра Серый Рог в Крепость Завоевателей, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (12208,'Удачи в охоте за троллями!','Никчемные твари!$b$bНеужели нельзя было договориться по-хорошему? Мы протянули им руку мира! Им оставалось только предоставить нам безопасный проход через Драк\'Тарон – и мы бы оставили их в покое. $b$bНо нет, эти заносчивые ледяные тролли решили, что они хотят войны. Теперь мы сотрем их с лица земли и захватим их драгоценную крепость!$b$bМы уже наняли банду головорезов, которые будут поставлять нам захваченных троллей для допроса. Поговори с Самиром, если ты тоже не хочешь оставаться в стороне. Его легко найти на северо-западе отсюда, к югу от Зеб\'Халека.','Сержант Туркин отправил вас к Самиру в Гранитные ключи.','Тоже хочешь поохотиться за ледяными троллями?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Удачи в охоте за троллями!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Никчемные твари!$b$bНеужели нельзя было договориться по-хорошему? Мы протянули им руку мира! Им оставалось только предоставить нам безопасный проход через Драк\'Тарон – и мы бы оставили их в покое. $b$bНо нет, эти заносчивые ледяные тролли решили, что они хотят войны. Теперь мы сотрем их с лица земли и захватим их драгоценную крепость!$b$bМы уже наняли банду головорезов, которые будут поставлять нам захваченных троллей для допроса. Поговори с Самиром, если ты тоже не хочешь оставаться в стороне. Его легко найти на северо-западе отсюда, к югу от Зеб\'Халека.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сержант Туркин отправил вас к Самиру в Гранитные ключи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тоже хочешь поохотиться за ледяными троллями?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (12209,'Кража материальных ценностей','Ах, да, свежее мясо прибыло. Хочешь проявить себя, салага?$B$BВоины Алого Натиска – самого фанатичного и расистского крыла Алого ордена – у нас уже под самым носом, к югу. Если мы хотим с ними сразиться, нам понадобится больше доспехов и оружия, чем я сумею раздобыть за столь короткое время.$B$BПочему бы нам не позаимствовать их вооружение?$B$BЯ бы даже сказал, почему бы ТЕБЕ его не позаимствовать?','По заданию интенданта Бартлетта из Ядозлоби похитьте 8 доспехов Алого Натиска и 8 единиц оружия Алого Натиска.','Вернитесь к интенданту Бартлетту в Ядозлобь, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кража материальных ценностей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ах, да, свежее мясо прибыло. Хочешь проявить себя, салага?$B$BВоины Алого Натиска – самого фанатичного и расистского крыла Алого ордена – у нас уже под самым носом, к югу. Если мы хотим с ними сразиться, нам понадобится больше доспехов и оружия, чем я сумею раздобыть за столь короткое время.$B$BПочему бы нам не позаимствовать их вооружение?$B$BЯ бы даже сказал, почему бы ТЕБЕ его не позаимствовать?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По заданию интенданта Бартлетта из Ядозлоби похитьте 8 доспехов Алого Натиска и 8 единиц оружия Алого Натиска.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к интенданту Бартлетту в Ядозлобь, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (12210,'Сезон охоты на троллей!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сезон охоты на троллей!',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12211,'Не дадим им подняться!','Я просто не понимаю. Этот настой должен был сработать!$B$BНу, нечего теперь об этом беспокоиться.$B$B<По какой-то причине аптекарь вовсе не выглядит сильно расстроенной.>$B$BХотя он по каким-то причинам не подействовал на этих, из Натиска, мы все же должны сделать так, чтобы их жрецы не смогли поднять трупы.$B$BУ меня есть другая идея – идея, против которой у трупов нет никакой защиты.$B$B$n, возьми мою клетку с крысами и выпусти их на любые тела Алого Натиска, на какие наткнешься в Новом Дольном Очаге. Я морила голодом этих тварей, так что они должны оказаться весьма прожорливыми!','По заданию аптекаря Вики Левин из Ядозлоби воспользуйтесь ее клеткой с крысами в Новом Дольном Очаге, чтобы ободрать дочиста 15 тел, принадлежащих Алому Натиску.','Очень удачно вы подвернулись. А то я уж боялся, что придется самому идти коней добывать!','Вернитесь к Аптекарю Вики Левин в Ядозлобь, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Не дадим им подняться!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я просто не понимаю. Этот настой должен был сработать!$B$BНу, нечего теперь об этом беспокоиться.$B$B<По какой-то причине аптекарь вовсе не выглядит сильно расстроенной.>$B$BХотя он по каким-то причинам не подействовал на этих, из Натиска, мы все же должны сделать так, чтобы их жрецы не смогли поднять трупы.$B$BУ меня есть другая идея – идея, против которой у трупов нет никакой защиты.$B$B$n, возьми мою клетку с крысами и выпусти их на любые тела Алого Натиска, на какие наткнешься в Новом Дольном Очаге. Я морила голодом этих тварей, так что они должны оказаться весьма прожорливыми!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По заданию аптекаря Вики Левин из Ядозлоби воспользуйтесь ее клеткой с крысами в Новом Дольном Очаге, чтобы ободрать дочиста 15 тел, принадлежащих Алому Натиску.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Очень удачно вы подвернулись. А то я уж боялся, что придется самому идти коней добывать!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аптекарю Вики Левин в Ядозлобь, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (12212,'Пополнение запасов','Доброго тебе дня, |3-6($c).$b$bВон тот славный лейтенант утверждает, что набег Орды на наши склады практически оставил нас без продовольствия.$b$bМы, конечно, заставим этих мерзавцев пожалеть о содеянном, но сначала нам надо восполнить наши запасы. Мои люди трудятся не покладая рук, без твоей помощи нам не обойтись.$b$bПолагаю, тебе не составит труда добыть немного оленины – в этих краях полно диких оленей. Удачной охоты!','Какие отборные куски мяса!','Вернитесь к искусному резчику по дереву Андерхолу в Приют Янтарной Сосны, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пополнение запасов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Доброго тебе дня, |3-6($c).$b$bВон тот славный лейтенант утверждает, что набег Орды на наши склады практически оставил нас без продовольствия.$b$bМы, конечно, заставим этих мерзавцев пожалеть о содеянном, но сначала нам надо восполнить наши запасы. Мои люди трудятся не покладая рук, без твоей помощи нам не обойтись.$b$bПолагаю, тебе не составит труда добыть немного оленины – в этих краях полно диких оленей. Удачной охоты!',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Какие отборные куски мяса!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к искусному резчику по дереву Андерхолу в Приют Янтарной Сосны, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (12213,'Подземная тьма','Что-то страшное случилось с этим деревом, Фордрассилом. После того как друиды уничтожили мировое древо, его обломки пустили корни глубоко в землю.$B$BЯ хочу, чтобы ты $gразыскал:разыскала; три части великого ствола, упавших далеко на севере-востоке, и $gуглубился:углубилась; как можно дальше под землю.$B$BКак только ты окажешься на месте, воспользуйся этим шаром, чтобы замерить выброс энергии. Возможно, наши исследования прольют свет на тайну уничтожения мирового древа.','Вернитесь к заклинательнице ветра Серый Рог в Крепость Завоевателей, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подземная тьма',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что-то страшное случилось с этим деревом, Фордрассилом. После того как друиды уничтожили мировое древо, его обломки пустили корни глубоко в землю.$B$BЯ хочу, чтобы ты $gразыскал:разыскала; три части великого ствола, упавших далеко на севере-востоке, и $gуглубился:углубилась; как можно дальше под землю.$B$BКак только ты окажешься на месте, воспользуйся этим шаром, чтобы замерить выброс энергии. Возможно, наши исследования прольют свет на тайну уничтожения мирового древа.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к заклинательнице ветра Серый Рог в Крепость Завоевателей, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12214,'Новые кони','Украдите 3 боевых коней Алого Натиска и доставьте их Ханзелу Бауэру в Ядозлобь. Передайте Ханзелу поводья из рук в руки.','Не правда ли, лучше бы они разрешили бы мне как-то использовать распространителей чумы?.. Может быть, зарядить их чем-нибудь гадким, чтобы разрушить баллисты.\n\nНо нет, они говорят, что разрушители чумы – только для специальных миссий.\n\nНу и ладно!','Вернитесь к Ханзелу Бауеру в Ядозлобь, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новые кони',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Украдите 3 боевых коней Алого Натиска и доставьте их Ханзелу Бауэру в Ядозлобь. Передайте Ханзелу поводья из рук в руки.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Не правда ли, лучше бы они разрешили бы мне как-то использовать распространителей чумы?.. Может быть, зарядить их чем-нибудь гадким, чтобы разрушить баллисты.\n\nНо нет, они говорят, что разрушители чумы – только для специальных миссий.\n\nНу и ладно!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ханзелу Бауеру в Ядозлобь, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12215,'Мы или они!','Вот только этого нам еще не хватало...$b$bНынешний кризис продовольствия поставил нас в такое тяжелое положение, что мы вынуждены бороться за каждый кусок мяса с местными воргами. Ситуация ухудшается с каждым днем, и я боюсь, что скоро мы просто истребим всю дичь в округе. $b$bОтправляйся в лес, |3-6($r), и убей всех воргов, которые попадутся тебе на пути. Мои разведчики видели целую стаю на другом берегу реки к западу отсюда.','Полагаю, еще несколькими воргами меньше в этих лесах?','Вернитесь к искусному резчику по дереву Андерхолу в Приют Янтарной Сосны, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мы или они!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот только этого нам еще не хватало...$b$bНынешний кризис продовольствия поставил нас в такое тяжелое положение, что мы вынуждены бороться за каждый кусок мяса с местными воргами. Ситуация ухудшается с каждым днем, и я боюсь, что скоро мы просто истребим всю дичь в округе. $b$bОтправляйся в лес, |3-6($r), и убей всех воргов, которые попадутся тебе на пути. Мои разведчики видели целую стаю на другом берегу реки к западу отсюда.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Полагаю, еще несколькими воргами меньше в этих лесах?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к искусному резчику по дереву Андерхолу в Приют Янтарной Сосны, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (12216,'Бери самое нежное!','Хотя мы еще не достигли поставленной цели, наш упорный труд уже начал приносить плоды. Увы, теперь стало очевидно, что местных оленей не хватит, чтобы обеспечить пропитанием всех жителей. $b$bБоюсь, нам придется обратить внимание на более опасную добычу – медведей гризли. В Седых холмах они водятся в изобилии, питаясь рыбой из многочисленных ручьев.$b$bУдачи тебе!','Вернитесь к искусному резчику по дереву Андерхолу в Приют Янтарной Сосны, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бери самое нежное!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хотя мы еще не достигли поставленной цели, наш упорный труд уже начал приносить плоды. Увы, теперь стало очевидно, что местных оленей не хватит, чтобы обеспечить пропитанием всех жителей. $b$bБоюсь, нам придется обратить внимание на более опасную добычу – медведей гризли. В Седых холмах они водятся в изобилии, питаясь рыбой из многочисленных ручьев.$b$bУдачи тебе!',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к искусному резчику по дереву Андерхолу в Приют Янтарной Сосны, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12217,'Орлиный взгляд','Итак, $n, теперь мы знаем, каким образом Орде удается выслеживать наши склады с продовольствием. $b$bОни магическим образом привязывают свой дух к зрению ничего не подозревающих орлов, которые кружат над верхушками деревьев. С их помощью они безнаказанно шпионят за каждым нашим шагом.$b$bПо приказу лейтенанта мы должны уничтожить этих величественных птиц, попавших под влияние наших врагов.','Андерхол из Приюта Янтарной Сосны просит вас убить 5 императорских орлов и доложить ему о выполнении задания.','Знаю, это было нелегко. Но теперь мы можем вздохнуть спокойно – враги больше не смогут шпионить за нами.','Ты выполнила свою задачу, $C?','Вернитесь к искусному резчику по дереву Андерхолу в Приют Янтарной Сосны, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Орлиный взгляд',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Итак, $n, теперь мы знаем, каким образом Орде удается выслеживать наши склады с продовольствием. $b$bОни магическим образом привязывают свой дух к зрению ничего не подозревающих орлов, которые кружат над верхушками деревьев. С их помощью они безнаказанно шпионят за каждым нашим шагом.$b$bПо приказу лейтенанта мы должны уничтожить этих величественных птиц, попавших под влияние наших врагов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Андерхол из Приюта Янтарной Сосны просит вас убить 5 императорских орлов и доложить ему о выполнении задания.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Знаю, это было нелегко. Но теперь мы можем вздохнуть спокойно – враги больше не смогут шпионить за нами.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты выполнила свою задачу, $C?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к искусному резчику по дереву Андерхолу в Приют Янтарной Сосны, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (12218,'Добрые вести не ждут на месте','Прежде чем я смогу отправить тебя к доктору Злобениусу с хорошими новостями, тебе придется еще провести обычное полевое испытание, но с некоторыми изменениями.$b$bИз останков старой крепости Стражей Зимы по-прежнему прут проголодавшиеся покойники. Выезжай на машине из восточных ворот и направляйся на северо-восток, через перевал Возмездия, пока не доберешься до двух башен на юго-восточной окраине крепости. Метни чумную бомбу в нежить, которая там кишит. И доложи мне о результатах!','Меня, конечно, бесит, что мы невольно помогаем Альянсу, но тем не менее полевые испытания прошли успешно! Тебя ждет Молот Агмара!','Вернитесь к главному распространителю чумы Миддлтону в Ядозлобь, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Добрые вести не ждут на месте',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прежде чем я смогу отправить тебя к доктору Злобениусу с хорошими новостями, тебе придется еще провести обычное полевое испытание, но с некоторыми изменениями.$b$bИз останков старой крепости Стражей Зимы по-прежнему прут проголодавшиеся покойники. Выезжай на машине из восточных ворот и направляйся на северо-восток, через перевал Возмездия, пока не доберешься до двух башен на юго-восточной окраине крепости. Метни чумную бомбу в нежить, которая там кишит. И доложи мне о результатах!',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Меня, конечно, бесит, что мы невольно помогаем Альянсу, но тем не менее полевые испытания прошли успешно! Тебя ждет Молот Агмара!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к главному распространителю чумы Миддлтону в Ядозлобь, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (12219,'Обломки мирового древа','Давным-давно мои предки посадили дерево в самом сердце Седых холмов.$B$BБудущее мировое древо было названо Фордрассил.$B$BОднако когда дерево выросло, по неведомым мне причинам его решили уничтожить. Гигантский ствол раскололся на три обломка, которые упали далеко на севере.$B$BНо в том месте, где они коснулись земли, из-под обломков начала распространяться омерзительная слизь, заражая все вокруг. Пожалуйста, принеси мне несколько образцов этой заразы, чтобы я смогла найти способ излечить землю.','Иерофант Тайрин из Приюта Янтарной Сосны просит вас найти Ветви Фордрассила, Сердце Фордрассила или Слезы Фордрассила и принести ей 6 образцов слизи энтропических слизнюков.','Вернитесь к иерофанту Тайрин в Приют Янтарной Сосны, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обломки мирового древа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Давным-давно мои предки посадили дерево в самом сердце Седых холмов.$B$BБудущее мировое древо было названо Фордрассил.$B$BОднако когда дерево выросло, по неведомым мне причинам его решили уничтожить. Гигантский ствол раскололся на три обломка, которые упали далеко на севере.$B$BНо в том месте, где они коснулись земли, из-под обломков начала распространяться омерзительная слизь, заражая все вокруг. Пожалуйста, принеси мне несколько образцов этой заразы, чтобы я смогла найти способ излечить землю.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Иерофант Тайрин из Приюта Янтарной Сосны просит вас найти Ветви Фордрассила, Сердце Фордрассила или Слезы Фордрассила и принести ей 6 образцов слизи энтропических слизнюков.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к иерофанту Тайрин в Приют Янтарной Сосны, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12220,'Темное влияние','Когда Фордрассил был уничтожен, его обломки пустили корни глубоко в землю.$B$BЯ хочу, чтобы ты $gразыскал:разыскала; три части великого ствола, упавших далеко на севере, и $gуглубился:углубилась; как можно дальше под землю.$B$BКак только ты окажешься на месте, воспользуйся этим шаром, чтобы определить выброс энергии в этом месте. Если мы хотим исцелить землю, нам прежде всего надо выяснить, что привело к гибели мирового древа.','Иерофант Тайрин из Приюта Янтарной Сосны просит вас отыскать Сердце Фордрассила, Слезы Фордрассила и Ветви Фордрассила, углубиться под землю и воспользоваться Геомантской сферой для измерения уровня энергии.','Сила, заключенная в этом шаре... она огромна...$B$BВся земля вокруг обломков Фордрассила пропитана темной энергией. Мы должны узнать больше об этом явлении!','Ты сделал то, о чем я тебя просил, $N?','Вернитесь к иерофанту Тайрин в Приют Янтарной Сосны, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Темное влияние',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда Фордрассил был уничтожен, его обломки пустили корни глубоко в землю.$B$BЯ хочу, чтобы ты $gразыскал:разыскала; три части великого ствола, упавших далеко на севере, и $gуглубился:углубилась; как можно дальше под землю.$B$BКак только ты окажешься на месте, воспользуйся этим шаром, чтобы определить выброс энергии в этом месте. Если мы хотим исцелить землю, нам прежде всего надо выяснить, что привело к гибели мирового древа.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Иерофант Тайрин из Приюта Янтарной Сосны просит вас отыскать Сердце Фордрассила, Слезы Фордрассила и Ветви Фордрассила, углубиться под землю и воспользоваться Геомантской сферой для измерения уровня энергии.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сила, заключенная в этом шаре... она огромна...$B$BВся земля вокруг обломков Фордрассила пропитана темной энергией. Мы должны узнать больше об этом явлении!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты сделал то, о чем я тебя просил, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к иерофанту Тайрин в Приют Янтарной Сосны, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12221,'Гниль Отрекшихся','Я подготовил пакет, который нужно доставить доктору Синтару Злобениусу в Молот Агмара. Содержимое этого пакета составляет окончательный образец гнили вместе с инструкциями по изготовлению и образцами реагентов.$B$BМолот Агмара находится в западной части Драконьего Погоста. Как увидишь черные зубчатые металлические орочьи здания, – это и есть Молот Агмара.','Доставьте образец гнили Отрекшихся доктору Синтару Злобениусу в Молот Агмара.','Что ж, пора как никогда!','Вернитесь к доктору Синтару Злобениусу в Молот Агмара, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гниль Отрекшихся',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я подготовил пакет, который нужно доставить доктору Синтару Злобениусу в Молот Агмара. Содержимое этого пакета составляет окончательный образец гнили вместе с инструкциями по изготовлению и образцами реагентов.$B$BМолот Агмара находится в западной части Драконьего Погоста. Как увидишь черные зубчатые металлические орочьи здания, – это и есть Молот Агмара.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте образец гнили Отрекшихся доктору Синтару Злобениусу в Молот Агмара.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что ж, пора как никогда!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к доктору Синтару Злобениусу в Молот Агмара, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (12222,'Тайны прядильщиц пламени','Пока мы пытаемся дать отпор Орде, клан Укротителей драконов вербует новую армию в деревне Волдрун, которая находится у побережья на юге.$B$BСамые могущественные воины в этой деревне носят огнепрочные талисманы, которые дают им власть над могущественными протодраконами. Нам бы подчинить себе этих драконов – и можно было бы не опасаться угрозы, исходящей из Волдруна!$B$BА создают эти магические талисманы огневязы из клана Укротителей драконов. Убей их и принеси мне амулеты!','Принесите 3 огнепрочных талисмана плотнику Дрейку в Приют Янтарной Сосны.','Вернитесь к плотнику Дрейку в Приют Янтарной Сосны, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тайны прядильщиц пламени',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пока мы пытаемся дать отпор Орде, клан Укротителей драконов вербует новую армию в деревне Волдрун, которая находится у побережья на юге.$B$BСамые могущественные воины в этой деревне носят огнепрочные талисманы, которые дают им власть над могущественными протодраконами. Нам бы подчинить себе этих драконов – и можно было бы не опасаться угрозы, исходящей из Волдруна!$B$BА создают эти магические талисманы огневязы из клана Укротителей драконов. Убей их и принеси мне амулеты!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 3 огнепрочных талисмана плотнику Дрейку в Приют Янтарной Сосны.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к плотнику Дрейку в Приют Янтарной Сосны, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12223,'Ослабление врага','Наши разведчики докладывают, что врайкулы опять проявляют бурную активность в южной деревне Волдрун. Тан Торвальд Эрикксон и его шавки готовятся к войне. А пока большинство наших людей разбираются с подлыми засадами ордынцев, Приют Янтарной Сосны не сможет оказать сопротивления захватчикам!$B$BОтправляйся на южное побережье, в Волдрун, и покажи этим Укротителям драконов, что нас лучше обходить стороной.$B$BУбей всех хускерлов, которые встретятся тебе на пути. Пусть они дважды подумают, стоит ли с нами связываться.','Убейте 12 хускерлов из клана Укротителей драконов и вернитесь к плотнику Дрейку в Приют Янтарной Сосны.','Дело сделано?','Вернитесь к плотнику Дрейку в Приют Янтарной Сосны, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ослабление врага',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наши разведчики докладывают, что врайкулы опять проявляют бурную активность в южной деревне Волдрун. Тан Торвальд Эрикксон и его шавки готовятся к войне. А пока большинство наших людей разбираются с подлыми засадами ордынцев, Приют Янтарной Сосны не сможет оказать сопротивления захватчикам!$B$BОтправляйся на южное побережье, в Волдрун, и покажи этим Укротителям драконов, что нас лучше обходить стороной.$B$BУбей всех хускерлов, которые встретятся тебе на пути. Пусть они дважды подумают, стоит ли с нами связываться.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 хускерлов из клана Укротителей драконов и вернитесь к плотнику Дрейку в Приют Янтарной Сосны.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Дело сделано?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к плотнику Дрейку в Приют Янтарной Сосны, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) VALUES (12224,'Должен ли я дать приказ своим силам прорываться к Молоту Агмара?\n\nИли тебе удалось убить верховного генерала?') ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Должен ли я дать приказ своим силам прорываться к Молоту Агмара?\n\nИли тебе удалось убить верховного генерала?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (12225,'М-м-м... Янтарные желуди!','Вы чувствуете аппетитный запах сочных орехов, доносящийся из корзинки с семенами, и ваш желудок протестующе урчит.$b$bВидимо, какая-то добрая душа оставила здесь эти семена для подкрепления уставших путников. Вы с благодарностью съедаете оставшиеся орешки.$b$bВкус у этих семян еще лучше, чем запах! Теперь вы непременно хотите узнать, где можно достать еще больше этого лакомства.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','М-м-м... Янтарные желуди!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы чувствуете аппетитный запах сочных орехов, доносящийся из корзинки с семенами, и ваш желудок протестующе урчит.$b$bВидимо, какая-то добрая душа оставила здесь эти семена для подкрепления уставших путников. Вы с благодарностью съедаете оставшиеся орешки.$b$bВкус у этих семян еще лучше, чем запах! Теперь вы непременно хотите узнать, где можно достать еще больше этого лакомства.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12226,'Ух, пронесло!','Надо действовать быстро, |3-6($r)! Нельзя допустить, чтобы эти драгоценные семена полностью разложились. Мы должны извлечь их, и немедленно!$b$bСкорее, принеси мне несколько стеблей чернокорня – он растет на берегу реки к западу отсюда – и я сделаю тебе эффективное слабительное.$b$bНу что ты стоишь столбом, беги! В конце концов, ты $gсам виноват:сама виновата;...','Андерхол из Приюта Янтарной Сосны просит вас принести ему 5 стеблей чернокорня.','Да, эти стебли вполне сгодятся...$B$B<Андерхол ловко скручивает стебли, выжимая вязкий сок в маленькую бутылочку.>$B$BВот так! А теперь – за дело!','Неужели так сложно найти чернокорень?','Вернитесь к искусному резчику по дереву Андерхолу в Приют Янтарной Сосны, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ух, пронесло!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Надо действовать быстро, |3-6($r)! Нельзя допустить, чтобы эти драгоценные семена полностью разложились. Мы должны извлечь их, и немедленно!$b$bСкорее, принеси мне несколько стеблей чернокорня – он растет на берегу реки к западу отсюда – и я сделаю тебе эффективное слабительное.$b$bНу что ты стоишь столбом, беги! В конце концов, ты $gсам виноват:сама виновата;...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Андерхол из Приюта Янтарной Сосны просит вас принести ему 5 стеблей чернокорня.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, эти стебли вполне сгодятся...$B$B<Андерхол ловко скручивает стебли, выжимая вязкий сок в маленькую бутылочку.>$B$BВот так! А теперь – за дело!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Неужели так сложно найти чернокорень?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к искусному резчику по дереву Андерхолу в Приют Янтарной Сосны, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (12227,'За дело!','Держи слабительное, |3-6($r).$b$bУчти – оно срабатывает мгновенно, так что сначала отыщи отхожее место и запрись там покрепче.$b$bВсе, иди за желудями!','Андерхол из Приюта Янтарной Сосны просит вас взять слабительную настойку Андерхола и воспользоваться ближайшим туалетом, чтобы извлечь частично переваренные янтарные желуди.','Вернитесь к искусному резчику по дереву Андерхолу в Приют Янтарной Сосны, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','За дело!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Держи слабительное, |3-6($r).$b$bУчти – оно срабатывает мгновенно, так что сначала отыщи отхожее место и запрись там покрепче.$b$bВсе, иди за желудями!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Андерхол из Приюта Янтарной Сосны просит вас взять слабительную настойку Андерхола и воспользоваться ближайшим туалетом, чтобы извлечь частично переваренные янтарные желуди.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к искусному резчику по дереву Андерхолу в Приют Янтарной Сосны, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (12228,'Возвращение магии [PH]') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение магии [PH]',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (12229,'Возможная связь','Не так давно мы отправили на восток экспедицию, которую растерзали бешеные фурболги. Единственный выживший рассказал, что видел странную темную жидкость, вытекавшую из тела убитого нападавшего.$B$BМногие тысячи лет фурболги жили в мире друг с другом и с окружающими. Мне кажется, что их агрессивность как-то связана с этой темной жидкостью и со зловещей силой, которую мы обнаружили ранее.$B$BПожалуйста, принеси мне несколько образцов крови фурболгов. Ты найдешь их в Святилище Красного Клыка и Святилище Кровавого Сердца, которые находятся на востоке.','Эта кровь заражена тем же веществом, что и слизь. Не нравится мне все это...','Вернитесь к заклинательнице ветра Серый Рог в Крепость Завоевателей, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возможная связь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не так давно мы отправили на восток экспедицию, которую растерзали бешеные фурболги. Единственный выживший рассказал, что видел странную темную жидкость, вытекавшую из тела убитого нападавшего.$B$BМногие тысячи лет фурболги жили в мире друг с другом и с окружающими. Мне кажется, что их агрессивность как-то связана с этой темной жидкостью и со зловещей силой, которую мы обнаружили ранее.$B$BПожалуйста, принеси мне несколько образцов крови фурболгов. Ты найдешь их в Святилище Красного Клыка и Святилище Кровавого Сердца, которые находятся на востоке.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Эта кровь заражена тем же веществом, что и слизь. Не нравится мне все это...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к заклинательнице ветра Серый Рог в Крепость Завоевателей, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (12230,'Кража у осадных мастеров','По поручению Стража смерти Молдера из Ядозлоби раздобудьте 6 осадных бомб.','Вернитесь к стражу смерти Молдеру в Ядозлобь, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кража у осадных мастеров',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По поручению Стража смерти Молдера из Ядозлоби раздобудьте 6 осадных бомб.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к стражу смерти Молдеру в Ядозлобь, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`completedtext_loc8`) VALUES (12231,'Возможно, фурболгов Седых холмов затронула та же скверна, что заразила Фордрассил. Иначе я не могу объяснить, почему после стольких лет мира они оказались вовлечены в страшную, братоубийственную войну.$B$BНа востоке отсюда есть тщательно охраняемые святилища, которые стали домом отпрыскам Урсока.$B$BОстается лишь уповать на то, что порча не возымела действие на наследников бога, Кодиан и Орсонна.$B$BРазыщи их и выслушай, что они могут нам поведать.','Вернитесь к заклинательнице ветра Серый Рог в Крепость Завоевателей, что в Седых холмах.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Возможно, фурболгов Седых холмов затронула та же скверна, что заразила Фордрассил. Иначе я не могу объяснить, почему после стольких лет мира они оказались вовлечены в страшную, братоубийственную войну.$B$BНа востоке отсюда есть тщательно охраняемые святилища, которые стали домом отпрыскам Урсока.$B$BОстается лишь уповать на то, что порча не возымела действие на наследников бога, Кодиан и Орсонна.$B$BРазыщи их и выслушай, что они могут нам поведать.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к заклинательнице ветра Серый Рог в Крепость Завоевателей, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12232,'Бомбардировка баллист','Наконец-то у нас появился шанс ударить по их осадным машинам! Не облажайся!$B$BШучу.$B$BОтчасти.$B$B$C, ты $gдолжен:должна; уничтожить баллисты Нового Дольного Очага с помощью этих бомб.$B$BМы покажем Королевскому фармацевтическому обществу, как это делалось в старые добрые времена! Никаких замысловатостей, никаких сложных рецептов!','По заданию Стража смерти Молдера из Ядозлоби уничтожьте 5 баллист Нового Дольного Очага с помощью осадных бомб.','Когда-нибудь я стану главой Стражей смерти!\n\nКогда-нибудь...','Вернитесь к стражу смерти Молдеру в Ядозлобь, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бомбардировка баллист',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наконец-то у нас появился шанс ударить по их осадным машинам! Не облажайся!$B$BШучу.$B$BОтчасти.$B$B$C, ты $gдолжен:должна; уничтожить баллисты Нового Дольного Очага с помощью этих бомб.$B$BМы покажем Королевскому фармацевтическому обществу, как это делалось в старые добрые времена! Никаких замысловатостей, никаких сложных рецептов!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По заданию Стража смерти Молдера из Ядозлоби уничтожьте 5 баллист Нового Дольного Очага с помощью осадных бомб.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Когда-нибудь я стану главой Стражей смерти!\n\nКогда-нибудь...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к стражу смерти Молдеру в Ядозлобь, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (12233,'[Depricated]Высадить семена','Нет, нет... Оставь их себе.$b$bТы же не думаешь, что я заберу из после всего, что ты с ними $gсделал:сделала;?$b$bСлушай; вот что мы теперь должны предпринять...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[Depricated]Высадить семена',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нет, нет... Оставь их себе.$b$bТы же не думаешь, что я заберу из после всего, что ты с ними $gсделал:сделала;?$b$bСлушай; вот что мы теперь должны предпринять...',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (12234,'Надо знать','Мне нужно знать, что замышляют в Новом Дольном Очаге.$b$bУкради их сегодняшние приказы, чтобы я могла это выяснить.$b$bСтупай на юг и осмотри аббатство, казармы и побережье – найди их текущие планы действий!$b$bЕсли вдруг заблудишься, казармы – это такое здоровенное здание рядом с кузницей.','Украдите текущие приказы Алого Натиска в аббатстве, в казармах и на побережье по просьбе главы шпионов Репайн из Ядозлоби.','Вернитесь к главе шпионов Репайн в Ядозлобь, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Надо знать',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне нужно знать, что замышляют в Новом Дольном Очаге.$b$bУкради их сегодняшние приказы, чтобы я могла это выяснить.$b$bСтупай на юг и осмотри аббатство, казармы и побережье – найди их текущие планы действий!$b$bЕсли вдруг заблудишься, казармы – это такое здоровенное здание рядом с кузницей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Украдите текущие приказы Алого Натиска в аббатстве, в казармах и на побережье по просьбе главы шпионов Репайн из Ядозлоби.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к главе шпионов Репайн в Ядозлобь, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (12235,'Наксрамас и падение крепости Стражей Зимы','Лорд Фордрагон возглавил сокрушительную атаку на Артаса у Врат Гнева. За это Артас направил против нас Наксрамас. В то время как Кел\'Тузад скрывается в парящей цитадели, его военачальник, Тельзан, осаждает крепость Стражей Зимы. Нижняя часть поселения уже потеряна, и надежда вызволить выживших тает с каждой минутой.$b$bДействовать нужно быстро! Срочно обратись к командиру грифонов Урику на грифоньей площадке! Он поможет тебе быстро добраться до места.$b$bСтупай!','Поговорите с командиром грифонов Уриком на грифоньей площадке в крепости Стражей Зимы.','<Урик указывает на грифона.>$B$BДоводилось ли тебе летать на этих животных? Впрочем, это проще простого. Садись и говори ему, куда лететь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наксрамас и падение крепости Стражей Зимы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Лорд Фордрагон возглавил сокрушительную атаку на Артаса у Врат Гнева. За это Артас направил против нас Наксрамас. В то время как Кел\'Тузад скрывается в парящей цитадели, его военачальник, Тельзан, осаждает крепость Стражей Зимы. Нижняя часть поселения уже потеряна, и надежда вызволить выживших тает с каждой минутой.$b$bДействовать нужно быстро! Срочно обратись к командиру грифонов Урику на грифоньей площадке! Он поможет тебе быстро добраться до места.$b$bСтупай!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с командиром грифонов Уриком на грифоньей площадке в крепости Стражей Зимы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Урик указывает на грифона.>$B$BДоводилось ли тебе летать на этих животных? Впрочем, это проще простого. Садись и говори ему, куда лететь.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`completedtext_loc8`) VALUES (12236,'Время пришло, $n. Возьми этот пепел и принеси его фурболгу, о котором упоминала Кодиан. Если он отправился на поиски Урсока, то его следы должны привести тебя к логову на севере Седой Пасти.$B$BУвы, ты не справишься без его помощи. $gОдному:Одной; тебе никогда не одолеть Урсока.$B$BКак только вы одержите победу над Урсоком, воспользуйся этим пеплом, чтобы очистить его дух. Даже если его физическое тело будет уничтожено, душа должна быть спасена.','Вернитесь к заклинательнице ветра Серый Рог в Крепость Завоевателей, что в Седых холмах.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Время пришло, $n. Возьми этот пепел и принеси его фурболгу, о котором упоминала Кодиан. Если он отправился на поиски Урсока, то его следы должны привести тебя к логову на севере Седой Пасти.$B$BУвы, ты не справишься без его помощи. $gОдному:Одной; тебе никогда не одолеть Урсока.$B$BКак только вы одержите победу над Урсоком, воспользуйся этим пеплом, чтобы очистить его дух. Даже если его физическое тело будет уничтожено, душа должна быть спасена.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к заклинательнице ветра Серый Рог в Крепость Завоевателей, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (12239,'Шпион в Новом Дольном Очаге','В рядах Алого Натиска у меня есть шпионка. Мне нужно, чтобы ты $gпередал:передала; ей дневное задание, чтобы она могла спланировать следующую фазу нашей атаки.$B$BОна откликается на имя агента Скулли и находится там под личиной кладбищенского смотрителя Алого Натиска.$B$BВот это задание, отнеси ей и сделай то, о чем она попросит. Кладбище находится рядом с аббатством.','Доставьте текущие приказы Алого Натиска агенту Скулли в Новый Дольный Очаг.','Вернитесь к агенту Скулли в Драконьи пустоши, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Шпион в Новом Дольном Очаге',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В рядах Алого Натиска у меня есть шпионка. Мне нужно, чтобы ты $gпередал:передала; ей дневное задание, чтобы она могла спланировать следующую фазу нашей атаки.$B$BОна откликается на имя агента Скулли и находится там под личиной кладбищенского смотрителя Алого Натиска.$B$BВот это задание, отнеси ей и сделай то, о чем она попросит. Кладбище находится рядом с аббатством.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте текущие приказы Алого Натиска агенту Скулли в Новый Дольный Очаг.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к агенту Скулли в Драконьи пустоши, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12240,'Цель и средства','Моя сестра, живущая на родине, в Бастионе, прислала мне с последним кораблем несколько бочонков с термитами. Думаю, они пригодятся для того, что я от тебя хочу.$b$bНам очень мешает лесопилка в Новом Дольном Очаге, но до сих пор мы никак не могли пробраться внутрь, чтобы выманить их десятника.$b$bДумаю, что если натравить этих термитов на его драгоценные доски и бревна, он уж точно прибежит как миленький!$b$bНу что, |3-6($c), возьмешься его ликвидировать?','Используйте термитов семейки Левин, чтобы выманить штейгера Калейки и убить его по просьбе аптекаря Вики Левин из Ядозлоби.','Не тяни, не то их планы успеют измениться, и придется начинать все заново.\n\nНе теряй времени!','Вернитесь к Аптекарю Вики Левин в Ядозлобь, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Цель и средства',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Моя сестра, живущая на родине, в Бастионе, прислала мне с последним кораблем несколько бочонков с термитами. Думаю, они пригодятся для того, что я от тебя хочу.$b$bНам очень мешает лесопилка в Новом Дольном Очаге, но до сих пор мы никак не могли пробраться внутрь, чтобы выманить их десятника.$b$bДумаю, что если натравить этих термитов на его драгоценные доски и бревна, он уж точно прибежит как миленький!$b$bНу что, |3-6($c), возьмешься его ликвидировать?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте термитов семейки Левин, чтобы выманить штейгера Калейки и убить его по просьбе аптекаря Вики Левин из Ядозлоби.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Не тяни, не то их планы успеют измениться, и придется начинать все заново.\n\nНе теряй времени!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аптекарю Вики Левин в Ядозлобь, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (12241,'Уничтожить саженец','Увы, $n, нам придется вмешаться в работу фурболгов. Я понимаю их благие намерения, но не могу допустить, чтобы заражение распространялось.$B$BЭтот саженец – источник зла, и потому он должен быть уничтожен. Возьми этот факел, подожги им зараженный саженец, и принеси мне пепел. $B$BОчищенный огнем, он поможет нам побороть скверну. С помощью этого пепла ты изгонишь злые силы из Урсока.','Вернитесь к заклинательнице ветра Серый Рог в Крепость Завоевателей, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уничтожить саженец',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Увы, $n, нам придется вмешаться в работу фурболгов. Я понимаю их благие намерения, но не могу допустить, чтобы заражение распространялось.$B$BЭтот саженец – источник зла, и потому он должен быть уничтожен. Возьми этот факел, подожги им зараженный саженец, и принеси мне пепел. $B$BОчищенный огнем, он поможет нам побороть скверну. С помощью этого пепла ты изгонишь злые силы из Урсока.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к заклинательнице ветра Серый Рог в Крепость Завоевателей, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (12242,'Семена Фордрассила','Мы должны убедиться в том, что Фордрассил никогда не вырастет вновь. Я боюсь, что фурболги уже посадили его семя. $B$BОтправляйся в Седую Пасть, что в самом сердце Седых холмов, и собери все семена, которые сможешь найти. Я постараюсь их уничтожить.','Вернитесь к заклинательнице ветра Серый Рог в Крепость Завоевателей, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Семена Фордрассила',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы должны убедиться в том, что Фордрассил никогда не вырастет вновь. Я боюсь, что фурболги уже посадили его семя. $B$BОтправляйся в Седую Пасть, что в самом сердце Седых холмов, и собери все семена, которые сможешь найти. Я постараюсь их уничтожить.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к заклинательнице ветра Серый Рог в Крепость Завоевателей, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (12243,'Огонь над водами','У меня есть для тебя еще одно задание.$B$BМне удалось переработать кое-что из настоя порчи в мою знаменитую на весь мир огненную воду. Я хочу, чтобы ты $gвзял:взяла; ее и $gподжег:подожгла; паруса "Глупости грешника"!$B$BИспользуй воду прямо из дока. Когда паруса вспыхнут, матросы будут сильно заняты, разбираясь с ними, а ты пока проскользнешь в нижнее помещение и добудешь бумаги капитана.$B$BКорабль найдешь в Стоянке рыцарей, ниже и к югу от Нового Дольного Очага. Капитанская каюта расположена на первой нижней палубе, под лестницей.','По заданию аптекаря Вики Левин из Ядозлоби воспользуйтесь Пылающей водой аптекаря, чтобы поджечь паруса "Глупости Грешника".$B$BПока матросы будут заняты тушением пожара, спуститесь вниз и раздобудьте у капитана лоцию капитана Шели.','Вернитесь к Аптекарю Вики Левин в Ядозлобь, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Огонь над водами',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У меня есть для тебя еще одно задание.$B$BМне удалось переработать кое-что из настоя порчи в мою знаменитую на весь мир огненную воду. Я хочу, чтобы ты $gвзял:взяла; ее и $gподжег:подожгла; паруса "Глупости грешника"!$B$BИспользуй воду прямо из дока. Когда паруса вспыхнут, матросы будут сильно заняты, разбираясь с ними, а ты пока проскользнешь в нижнее помещение и добудешь бумаги капитана.$B$BКорабль найдешь в Стоянке рыцарей, ниже и к югу от Нового Дольного Очага. Капитанская каюта расположена на первой нижней палубе, под лестницей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По заданию аптекаря Вики Левин из Ядозлоби воспользуйтесь Пылающей водой аптекаря, чтобы поджечь паруса "Глупости Грешника".$B$BПока матросы будут заняты тушением пожара, спуститесь вниз и раздобудьте у капитана лоцию капитана Шели.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аптекарю Вики Левин в Ядозлобь, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12244,'Починка крошшеров','<Синипус насвистывает.>$B$BАх, ты мой красавец! Сейчас мы тебя починим, будешь лучше прежнего!$B$BА тебе что, делать нечего? Иди к Гордуну, пусть он тебя отправит в Бухту торговцев. Им точно не помешает твоя помощь.$B$BТы еще здесь? На тебе ключи, заведи отремонтированного крошшера. Посмотрим, на что способны эти малышки.','Нет времени болтать. Эти крошшеры могут склонить чашу весов в пользу альянса!','Вернитесь к Синипусу на Лесозаготовки Синего Неба, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Починка крошшеров',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Синипус насвистывает.>$B$BАх, ты мой красавец! Сейчас мы тебя починим, будешь лучше прежнего!$B$BА тебе что, делать нечего? Иди к Гордуну, пусть он тебя отправит в Бухту торговцев. Им точно не помешает твоя помощь.$B$BТы еще здесь? На тебе ключи, заведи отремонтированного крошшера. Посмотрим, на что способны эти малышки.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Нет времени болтать. Эти крошшеры могут склонить чашу весов в пользу альянса!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Синипусу на Лесозаготовки Синего Неба, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12245,'Никакой пощады пленникам','Не правда ли, лучше бы они разрешили бы мне как-то использовать распространителей чумы?.. Может быть, зарядить их чем-нибудь гадким, чтобы разрушить баллисты.\n\nНо нет, они говорят, что разрушители чумы – только для специальных миссий.\n\nНу и ладно!','Вернитесь к верховному палачу Росу в Ядозлобь, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Никакой пощады пленникам',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Не правда ли, лучше бы они разрешили бы мне как-то использовать распространителей чумы?.. Может быть, зарядить их чем-нибудь гадким, чтобы разрушить баллисты.\n\nНо нет, они говорят, что разрушители чумы – только для специальных миссий.\n\nНу и ладно!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному палачу Росу в Ядозлобь, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (12246,'Возможная связь','Живущие на востоке фурболги более дикие и агрессивные, чем те, с которыми тебе уже приходилось встречаться. Нашим отрядам случалось сталкиваться с этими тварями, и каждый раз немногочисленные выжившие рассказывали о темной вязкой жидкости, сочившейся из трупов поверженных фурболгов. $B$BВозможно, это как-то связано с порчей, обнаруженной нами на останках Фордрассила. $B$BПожалуйста, принеси мне несколько образцов крови фурболгов. Ты найдешь их в Святилище Красного Клыка и Святилище Кровавого Сердца, которые находятся на востоке.','Иерофант Тайрин из Приюта Янтарной Сосны просит вас принести 8 образцов безумных фурболгов, обитающих в Святилище Кровавого Сердца и Святилище Красного Клыка.','Эта кровь заражена тем же веществом, что и слизь. Не нравится мне все это...','Вернитесь к иерофанту Тайрин в Приют Янтарной Сосны, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возможная связь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Живущие на востоке фурболги более дикие и агрессивные, чем те, с которыми тебе уже приходилось встречаться. Нашим отрядам случалось сталкиваться с этими тварями, и каждый раз немногочисленные выжившие рассказывали о темной вязкой жидкости, сочившейся из трупов поверженных фурболгов. $B$BВозможно, это как-то связано с порчей, обнаруженной нами на останках Фордрассила. $B$BПожалуйста, принеси мне несколько образцов крови фурболгов. Ты найдешь их в Святилище Красного Клыка и Святилище Кровавого Сердца, которые находятся на востоке.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Иерофант Тайрин из Приюта Янтарной Сосны просит вас принести 8 образцов безумных фурболгов, обитающих в Святилище Кровавого Сердца и Святилище Красного Клыка.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Эта кровь заражена тем же веществом, что и слизь. Не нравится мне все это...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к иерофанту Тайрин в Приют Янтарной Сосны, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12247,'Дети Урсока','Иерофант Тайрин из Приюта Янтарной Сосны просит вас разыскать Орсонна в Святилище Красного Клыка и Кодиан в Святилище Кровавого Сердца.','Дети Урсока мудры. Их слова объясняют все то, что я не могла понять.','Вы уже $Gговорил:говорила; с Орсонном и Кодианом?','Вернитесь к иерофанту Тайрин в Приют Янтарной Сосны, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дети Урсока',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Иерофант Тайрин из Приюта Янтарной Сосны просит вас разыскать Орсонна в Святилище Красного Клыка и Кодиан в Святилище Кровавого Сердца.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Дети Урсока мудры. Их слова объясняют все то, что я не могла понять.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы уже $Gговорил:говорила; с Орсонном и Кодианом?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к иерофанту Тайрин в Приют Янтарной Сосны, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (12248,'Саженец Фордрассила','У древних друидов были веские причины уничтожить Фордрассил. Мы не можем позволить фурболгам возродить его!$B$BПроблема в том, что спасение духа Урсока зависит от магии, содержащейся в саженце мирового древа.$B$BВозьми этот факел и сожги саженец, произрастающий в центре Седой Пасти, в старой кадке Фордрассила.$B$BПринеси мне пепел, оставшийся после сожжения дерева. Я надеюсь, что огонь очистит его от скверны, и мы сможем воспользоваться его магией для исцеления духа Урсока.','Иерофант Тайрин из Приюта Янтарной Сосны просит вас взять зеленый факел и сжечь саженец Фордрассила. Принесите ей пепел Фордрассила.','Какое счастье! Магия Фордрассила все еще жива. Возможно, мы еще сможем подарить надежду Урсоку.','Вернитесь к иерофанту Тайрин в Приют Янтарной Сосны, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Саженец Фордрассила',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У древних друидов были веские причины уничтожить Фордрассил. Мы не можем позволить фурболгам возродить его!$B$BПроблема в том, что спасение духа Урсока зависит от магии, содержащейся в саженце мирового древа.$B$BВозьми этот факел и сожги саженец, произрастающий в центре Седой Пасти, в старой кадке Фордрассила.$B$BПринеси мне пепел, оставшийся после сожжения дерева. Я надеюсь, что огонь очистит его от скверны, и мы сможем воспользоваться его магией для исцеления духа Урсока.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Иерофант Тайрин из Приюта Янтарной Сосны просит вас взять зеленый факел и сжечь саженец Фордрассила. Принесите ей пепел Фордрассила.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Какое счастье! Магия Фордрассила все еще жива. Возможно, мы еще сможем подарить надежду Урсоку.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к иерофанту Тайрин в Приют Янтарной Сосны, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12249,'Время пришло, $n. Возьми этот пепел и принеси его фурболгу, о котором упоминала Кодиан. Если он отправился на поиски Урсока, то его следы должны привести тебя к логову на севере Седой Пасти.$B$BУвы, ты не справишься без его помощи. $gОдному:Одной; тебе никогда не одолеть Урсока.$B$BКак только вы одержите победу над Урсоком, воспользуйся этим пеплом, чтобы очистить его дух. Надеюсь, все наши труды были не напрасны...','Иерофант Тайрин из Приюта Янтарной Сосны просит вас найти Тура Яролапа возле Логова Урcока и победить Урсока с его помощью. Когда Урсок падет, осыпьте его тело очищенным пеплом Фордрассила.','<Девушка-друид выглядит бледной, и ее взгляд устремлен куда-то мимо вас. Вы замечаете, что она оставила вам сверток в благодарность за ваши труды.>','Ты $Gвернулся:вернулась;? У тебя получилось?','Вернитесь к иерофанту Тайрин в Приют Янтарной Сосны, что в Седых холмах.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Время пришло, $n. Возьми этот пепел и принеси его фурболгу, о котором упоминала Кодиан. Если он отправился на поиски Урсока, то его следы должны привести тебя к логову на севере Седой Пасти.$B$BУвы, ты не справишься без его помощи. $gОдному:Одной; тебе никогда не одолеть Урсока.$B$BКак только вы одержите победу над Урсоком, воспользуйся этим пеплом, чтобы очистить его дух. Надеюсь, все наши труды были не напрасны...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Иерофант Тайрин из Приюта Янтарной Сосны просит вас найти Тура Яролапа возле Логова Урcока и победить Урсока с его помощью. Когда Урсок падет, осыпьте его тело очищенным пеплом Фордрассила.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Девушка-друид выглядит бледной, и ее взгляд устремлен куда-то мимо вас. Вы замечаете, что она оставила вам сверток в благодарность за ваши труды.>',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gвернулся:вернулась;? У тебя получилось?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к иерофанту Тайрин в Приют Янтарной Сосны, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (12250,'Семена Фордрассила','Мы должны убедиться в том, что Фордрассил никогда не вырастет вновь. Я боюсь, что фурболги уже посадили его семя. $B$BОтправляйся в Седую Пасть, что в самом сердце Седых холмов, и собери все семена, которые сможешь найти. Я постараюсь их уничтожить.','Иерофант Тайрин из Приюта Янтарной Сосны просит вас отправиться в Седую Пасть и принести ей 8 семян Фордрассила.','Вернитесь к иерофанту Тайрин в Приют Янтарной Сосны, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Семена Фордрассила',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы должны убедиться в том, что Фордрассил никогда не вырастет вновь. Я боюсь, что фурболги уже посадили его семя. $B$BОтправляйся в Седую Пасть, что в самом сердце Седых холмов, и собери все семена, которые сможешь найти. Я постараюсь их уничтожить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Иерофант Тайрин из Приюта Янтарной Сосны просит вас отправиться в Седую Пасть и принести ей 8 семян Фордрассила.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к иерофанту Тайрин в Приют Янтарной Сосны, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (12251,'Возвращение к верховному главнокомандующему','Вернись скорее к верховному главнокомандующему Халфорду Змеевержцу, $n. Скажи ему, что твоя миссия выполнена и что немногие оставшиеся в живых жители деревни вернулись к работе.','Поговорите с верховным главнокомандующим Халфордом Змеевержцем в крепости Стражей Зимы на Драконьем Погосте.','<Халфорд отдает вам честь.>$B$BВсе жители вернулись к работе? Так быстро! Молодцом, солдат! Мы вновь отстроим и укрепим этот городок – глазом моргнуть не успеешь! И вскоре будет готово подкрепление, чтобы помочь лорду Фордрагону у Врат Гнева.$B$BЯ, конечно, забегаю вперед, на самом деле, еще многое нужно сделать, прежде чем мы сможем даже начать думать о том, чтобы послать тебя на помощь Болвару.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение к верховному главнокомандующему',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вернись скорее к верховному главнокомандующему Халфорду Змеевержцу, $n. Скажи ему, что твоя миссия выполнена и что немногие оставшиеся в живых жители деревни вернулись к работе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с верховным главнокомандующим Халфордом Змеевержцем в крепости Стражей Зимы на Драконьем Погосте.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Халфорд отдает вам честь.>$B$BВсе жители вернулись к работе? Так быстро! Молодцом, солдат! Мы вновь отстроим и укрепим этот городок – глазом моргнуть не успеешь! И вскоре будет готово подкрепление, чтобы помочь лорду Фордрагону у Врат Гнева.$B$BЯ, конечно, забегаю вперед, на самом деле, еще многое нужно сделать, прежде чем мы сможем даже начать думать о том, чтобы послать тебя на помощь Болвару.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (12252,'Истязание истязателя','Вернитесь к верховному палачу Росу в Ядозлобь, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Истязание истязателя',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному палачу Росу в Ядозлобь, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12253,'Спасение с городской площади','Эта дорога ведет на городскую площадь крепости Стражей Зимы. Некогда там кипела жизнь, теперь же это зона боевых действий, кишащая злобными упырями, жаждущими мести всему живому.$b$bА в зданиях, окружающих площадь, заперты деревенские жители. Их надо спасти! Понимаю, $n, я прошу очень многого, но ты – единственный солдат, без которого я могу обойтись. Освободи наших людей. Ступай на площадь, войди в эти дома. Убивай всех, кто попытается тебе помешать! Если выживешь, возвращайся ко мне.','Спасите 6 пойманных жителей крепости Стражей Зимы по просьбе главнокомандующего Халфорда Змеевержца из крепости Стражей Зимы в Драконьем Погосте.','Ты $Gспас:спасла; наших сельских жителей, попавших в ловушку?','Вернитесь к главнокомандующему Халфорду Змеевержцу в Крепость Стражей Зимы, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спасение с городской площади',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эта дорога ведет на городскую площадь крепости Стражей Зимы. Некогда там кипела жизнь, теперь же это зона боевых действий, кишащая злобными упырями, жаждущими мести всему живому.$b$bА в зданиях, окружающих площадь, заперты деревенские жители. Их надо спасти! Понимаю, $n, я прошу очень многого, но ты – единственный солдат, без которого я могу обойтись. Освободи наших людей. Ступай на площадь, войди в эти дома. Убивай всех, кто попытается тебе помешать! Если выживешь, возвращайся ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Спасите 6 пойманных жителей крепости Стражей Зимы по просьбе главнокомандующего Халфорда Змеевержца из крепости Стражей Зимы в Драконьем Погосте.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gспас:спасла; наших сельских жителей, попавших в ловушку?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к главнокомандующему Халфорду Змеевержцу в Крепость Стражей Зимы, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12254,'Без молитвы – никак','Эти планы показывают, что грядет нечто неотвратимое.$B$BНо сначала нужно разобраться с той странной защитой, которая есть у сил Алого Натиска. Если Ядозлобь хочет разобраться с ним раз и навсегда, мы должны выяснить, кто стоит за всем этим, и уничтожить его.$B$BЯ заметила, что епископ в часовне на дальней стороне Нового Дольного Очага, что напротив мельницы, дал свое благословение войскам. Убей его и забери его молитвенник.$B$BМожет быть, это даст нам ключ к разгадке.','По заданию агента Скулли из Нового Дольного Очага раздобудьте молитвенник епископа Стрита.','Ты добыл молитвенник епископа? Обнаружил ли ты в нем что-то необычное?','Вернитесь к агенту Скулли в Новый Дольный Очаг, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Без молитвы – никак',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти планы показывают, что грядет нечто неотвратимое.$B$BНо сначала нужно разобраться с той странной защитой, которая есть у сил Алого Натиска. Если Ядозлобь хочет разобраться с ним раз и навсегда, мы должны выяснить, кто стоит за всем этим, и уничтожить его.$B$BЯ заметила, что епископ в часовне на дальней стороне Нового Дольного Очага, что напротив мельницы, дал свое благословение войскам. Убей его и забери его молитвенник.$B$BМожет быть, это даст нам ключ к разгадке.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По заданию агента Скулли из Нового Дольного Очага раздобудьте молитвенник епископа Стрита.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты добыл молитвенник епископа? Обнаружил ли ты в нем что-то необычное?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к агенту Скулли в Новый Дольный Очаг, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12255,'Тан Волдруна','Теперь, когда мы захватили огнепрочные талисманы и ослабили оборону Волдруна, настало время бросить вызов самому предводителю врайкулов, тану Торвальду Эрикксону.$B$BЕго любимое верховое животное – дикий протодракон по кличке Огнедышащий. Его держат закованным в цепи на западе Волдруна, но тебе не составит труда подчинить его себе с помощью талисманов и обратить его против хозяина. $B$BПриручи Огнедышащего и обыщи верхушки всех башен Волдруна. Тан должен скрываться где-то там.','Одержите победу над таном Торвальдом Эрикксоном с помощью Огнедышащего и доложите об успехе плотнику Дрейку из Приюта Янтарной Сосны.','Вы $Gодолел:одолела; Тана? Мы не можем оставить его у власти.','Вернитесь к плотнику Дрейку в Приют Янтарной Сосны, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тан Волдруна',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда мы захватили огнепрочные талисманы и ослабили оборону Волдруна, настало время бросить вызов самому предводителю врайкулов, тану Торвальду Эрикксону.$B$BЕго любимое верховое животное – дикий протодракон по кличке Огнедышащий. Его держат закованным в цепи на западе Волдруна, но тебе не составит труда подчинить его себе с помощью талисманов и обратить его против хозяина. $B$BПриручи Огнедышащего и обыщи верхушки всех башен Волдруна. Тан должен скрываться где-то там.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Одержите победу над таном Торвальдом Эрикксоном с помощью Огнедышащего и доложите об успехе плотнику Дрейку из Приюта Янтарной Сосны.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы $Gодолел:одолела; Тана? Мы не можем оставить его у власти.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к плотнику Дрейку в Приют Янтарной Сосны, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (12256,'Тайны огневязов','Пока мы пытаемся дать отпор трусливым захватчикам из Альянса, клан Укротителей драконов вербует новую армию в деревне Волдрун, которая находится у побережья на юге. Врайкулы – серьезные противники, и мне хотелось бы уничтожить их прежде, чем они решат выступить против нас.$B$BСамые могущественные воины в этой деревне носят огнепрочные талисманы, которые дают им власть над могущественными протодраконами. Эти талисманы создают прядильщицы пламени из клана Укротителей драконов. Убей их и принеси мне амулеты!','Протодраконы подчиняются только владельцам талисманов. Теперь судьба тана решена!','Вернитесь к сержанту Назгриму в Крепость Завоевателей, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тайны огневязов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пока мы пытаемся дать отпор трусливым захватчикам из Альянса, клан Укротителей драконов вербует новую армию в деревне Волдрун, которая находится у побережья на юге. Врайкулы – серьезные противники, и мне хотелось бы уничтожить их прежде, чем они решат выступить против нас.$B$BСамые могущественные воины в этой деревне носят огнепрочные талисманы, которые дают им власть над могущественными протодраконами. Эти талисманы создают прядильщицы пламени из клана Укротителей драконов. Убей их и принеси мне амулеты!',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Протодраконы подчиняются только владельцам талисманов. Теперь судьба тана решена!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к сержанту Назгриму в Крепость Завоевателей, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12257,'Демонстрация силы','Во врайкульской деревне Волдрун полным ходом идут приготовления к войне. Хотя местный тан не может выставить против нас большую армию, мы все равно не можем чувствовать себя в безопасности.$B$BНельзя дать им возможность напасть, когда мы к этому будем не готовы, поэтому я предлагаю самим сделать первый шаг. Если ты – истинный представитель Орды, ты с радостью ухватишься за возможность продемонстрировать свою силу.$B$BУбей всех хускерлов, которые встретятся тебе на пути. Пусть они дважды подумают, стоит ли связываться с Ордой!','Дело сделано?','Вернитесь к сержанту Назгриму в Крепость Завоевателей, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Демонстрация силы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Во врайкульской деревне Волдрун полным ходом идут приготовления к войне. Хотя местный тан не может выставить против нас большую армию, мы все равно не можем чувствовать себя в безопасности.$B$BНельзя дать им возможность напасть, когда мы к этому будем не готовы, поэтому я предлагаю самим сделать первый шаг. Если ты – истинный представитель Орды, ты с радостью ухватишься за возможность продемонстрировать свою силу.$B$BУбей всех хускерлов, которые встретятся тебе на пути. Пусть они дважды подумают, стоит ли связываться с Ордой!',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Дело сделано?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к сержанту Назгриму в Крепость Завоевателей, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12258,'Судьба погибших','По городской площади, куда ведет эта дорога, бродят жители крепости, превращенные в нежить! Наш собственный склеп превратился в источник все новых воинов Плети! Это наши бывшие собратья, да, но не надо их щадить, $n. Когда-то все они были смертными, способными мыслить и сострадать, теперь же это лишь гнусная нежить, у которой одна цель: уничтожить нас!$b$bСтупай на городскую площадь и отправь мстительных упырей к их создателю. Пусть упокоятся в мире.','Убейте 15 мстительных упырей по приказу командира Линоры Порыв Ветра в крепости Стражей Зимы в Драконьем Погосте.','Быть может, теперь они смогут упокоиться в мире, и души их свободно поднимутся навстречу Свету.$B$BЯ же буду молиться за лорда Фордрагона и наших воинов у Врат Гнева. Мы здесь должны выстоять, хотя бы затем, чтобы позволить им выиграть время и одолеть Короля-лича. Крепость Стражей Зимы не должна пасть!','Избавь их от страданий, $N.','Вернитесь к командиру Линоре Порыв Ветра в Крепость Стражей Зимы, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Судьба погибших',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','По городской площади, куда ведет эта дорога, бродят жители крепости, превращенные в нежить! Наш собственный склеп превратился в источник все новых воинов Плети! Это наши бывшие собратья, да, но не надо их щадить, $n. Когда-то все они были смертными, способными мыслить и сострадать, теперь же это лишь гнусная нежить, у которой одна цель: уничтожить нас!$b$bСтупай на городскую площадь и отправь мстительных упырей к их создателю. Пусть упокоятся в мире.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 15 мстительных упырей по приказу командира Линоры Порыв Ветра в крепости Стражей Зимы в Драконьем Погосте.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Быть может, теперь они смогут упокоиться в мире, и души их свободно поднимутся навстречу Свету.$B$BЯ же буду молиться за лорда Фордрагона и наших воинов у Врат Гнева. Мы здесь должны выстоять, хотя бы затем, чтобы позволить им выиграть время и одолеть Короля-лича. Крепость Стражей Зимы не должна пасть!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Избавь их от страданий, $N.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру Линоре Порыв Ветра в Крепость Стражей Зимы, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12259,'Тан Волдруна','Теперь, когда мы захватили огнепрочные талисманы и ослабили оборону Волдруна, настало время бросить вызов самому предводителю врайкулов, тану Торвальду Эрикксону.$B$BЕго любимое верховое животное – дикий протодракон по кличке Огнедышащий. Его держат закованным в цепи на западе Волдруна, но тебе не составит труда подчинить его себе с помощью талисманов и обратить его против хозяина. $B$BПриручи Огнедышащего и обыщи верхушки всех башен Волдруна. Тан должен скрываться где-то там.','Ты $Gодолел:одолела; Тана? Нельзя допустить, чтобы он остался во главе клана.','Вернитесь к сержанту Назгриму в Крепость Завоевателей, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тан Волдруна',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда мы захватили огнепрочные талисманы и ослабили оборону Волдруна, настало время бросить вызов самому предводителю врайкулов, тану Торвальду Эрикксону.$B$BЕго любимое верховое животное – дикий протодракон по кличке Огнедышащий. Его держат закованным в цепи на западе Волдруна, но тебе не составит труда подчинить его себе с помощью талисманов и обратить его против хозяина. $B$BПриручи Огнедышащего и обыщи верхушки всех башен Волдруна. Тан должен скрываться где-то там.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gодолел:одолела; Тана? Нельзя допустить, чтобы он остался во главе клана.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к сержанту Назгриму в Крепость Завоевателей, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12260,'Полное несходство','Ты, должно быть, удивляешься, как мне удается поддерживать эту личину? Я пользуюсь волшебным зеркальцем, которое мне одолжила госпожа шпионов.$B$BСилы в нем не так уж много, но я думаю, что на нас обоих хватит. Вот, возьми. Я хочу, чтобы ты $gиспользовал:использовала; его, чтобы замаскироваться под одного из жрецов-воронов Алого Натиска.$B$BДавай быстрее... я понятия не имею, сколько продержится маскарад, пока зеркальце у тебя.$B$BПомни, что идеальная маскировка проявится не сразу, так что не особо рассчитывай не нее, пока у меня не появится возможность тебе помочь.','По заданию агента Скулли из Нового Дольного Очага похитьте образ жреца-ворона Алого Натиска. После этого верните Волшебное зеркало банши агенту Скалли.','Что такое? Скажи, надеюсь, ты не разбил зеркальце?!','Вернитесь к агенту Скулли в Новый Дольный Очаг, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Полное несходство',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты, должно быть, удивляешься, как мне удается поддерживать эту личину? Я пользуюсь волшебным зеркальцем, которое мне одолжила госпожа шпионов.$B$BСилы в нем не так уж много, но я думаю, что на нас обоих хватит. Вот, возьми. Я хочу, чтобы ты $gиспользовал:использовала; его, чтобы замаскироваться под одного из жрецов-воронов Алого Натиска.$B$BДавай быстрее... я понятия не имею, сколько продержится маскарад, пока зеркальце у тебя.$B$BПомни, что идеальная маскировка проявится не сразу, так что не особо рассчитывай не нее, пока у меня не появится возможность тебе помочь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По заданию агента Скулли из Нового Дольного Очага похитьте образ жреца-ворона Алого Натиска. После этого верните Волшебное зеркало банши агенту Скалли.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что такое? Скажи, надеюсь, ты не разбил зеркальце?!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к агенту Скулли в Новый Дольный Очаг, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12261,'Отрезать пути к отступлению','Они вытягивают силу из костей моих мертвых собратьев...$B$BУ меня нет никакой симпатии к Культу, но я удивлен их дерзостью. К ним не будет снисхождения... впрочем, я никогда и не был снисходительным.$B$BСделай так, чтобы им некуда было бежать, когда начнется бойня. Установи тотем уничтожения в конце тропы, ведущей из святилища... где дорогу начинает заносить снегом. Защищай его, пока он не зарядится полностью.','Поместите тотем уничтожения в конце тропы, ведущей из Обсидианового святилища драконов, там, где дорогу начинает заносить снегом. Защищайте его до полной зарядки, затем вернитесь к Серинару.','Отлично. Когда они в страхе побегут, тотем будет тут как тут, чтобы сказать им последнее "прощай".','Ты $Gразместил:разместила; палату?','Вернитесь к Серинару в Пасть Нелтариона, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отрезать пути к отступлению',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Они вытягивают силу из костей моих мертвых собратьев...$B$BУ меня нет никакой симпатии к Культу, но я удивлен их дерзостью. К ним не будет снисхождения... впрочем, я никогда и не был снисходительным.$B$BСделай так, чтобы им некуда было бежать, когда начнется бойня. Установи тотем уничтожения в конце тропы, ведущей из святилища... где дорогу начинает заносить снегом. Защищай его, пока он не зарядится полностью.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поместите тотем уничтожения в конце тропы, ведущей из Обсидианового святилища драконов, там, где дорогу начинает заносить снегом. Защищайте его до полной зарядки, затем вернитесь к Серинару.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично. Когда они в страхе побегут, тотем будет тут как тут, чтобы сказать им последнее "прощай".',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gразместил:разместила; палату?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Серинару в Пасть Нелтариона, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12262,'Без надежды на спасение','Мы никого не пощадим.$B$BТам, за нашими стенами, презренные некролиты и их скелеты-прислужники оскверняют мою землю своим присутствием на ней. Убей их всех до единого.','Убейте 6 некролитов Пылающих Глубин и 10 тлеющих скелетов за пределами Обсидианового святилища драконов, после этого вернитесь к Серинару.','Они умоляли тебя пощадить их никчемные жизни? Слабаки…','Я вижу кровь на твоих руках... Значит, дело сделано?','Вернитесь к Серинару в Пасть Нелтариона, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Без надежды на спасение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы никого не пощадим.$B$BТам, за нашими стенами, презренные некролиты и их скелеты-прислужники оскверняют мою землю своим присутствием на ней. Убей их всех до единого.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 6 некролитов Пылающих Глубин и 10 тлеющих скелетов за пределами Обсидианового святилища драконов, после этого вернитесь к Серинару.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Они умоляли тебя пощадить их никчемные жизни? Слабаки…',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я вижу кровь на твоих руках... Значит, дело сделано?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Серинару в Пасть Нелтариона, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (12263,'С наилучшими намерениями','Культ Проклятых явился сюда не просто для того, чтобы вытягивать энергию из тел мертвых драконов. Думаю, я догадываюсь, что они замыслили, но мне нужно, чтобы ты $gподтвердил:подтвердила; мою правоту.$B$BЯ придам тебе обличье вот этого мертвого некролита. Доберись до конца пещеры и выясни, зачем они здесь, в этом священном месте. А я буду смотреть твоими глазами.$B$BБудь осторожнее, $n: если тебе нанесут хоть какой-то урон, это разобьет хрупкую иллюзию.','Дождитесь, пока Серинар замаскирует вас под некролита Пылающих Глубин, потом проникните в глубь Пасти Нелтариона, чтобы узнать, что там делает Культ Проклятых. Вернитесь к Серинару и расскажите о том, что они замышляют.','Мы – черные драконы. Тысячи лет мы сеяли разрушение в землях Азерота. Этот жалкий Культ Проклятых все же поклоняется смерти – что ж, мы будем рады им помочь!','Я устал от этой эпидемии.','Обнаружить зал воскрешения магмазмеев','Вернитесь к Серинару в Пасть Нелтариона, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','С наилучшими намерениями',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Культ Проклятых явился сюда не просто для того, чтобы вытягивать энергию из тел мертвых драконов. Думаю, я догадываюсь, что они замыслили, но мне нужно, чтобы ты $gподтвердил:подтвердила; мою правоту.$B$BЯ придам тебе обличье вот этого мертвого некролита. Доберись до конца пещеры и выясни, зачем они здесь, в этом священном месте. А я буду смотреть твоими глазами.$B$BБудь осторожнее, $n: если тебе нанесут хоть какой-то урон, это разобьет хрупкую иллюзию.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Дождитесь, пока Серинар замаскирует вас под некролита Пылающих Глубин, потом проникните в глубь Пасти Нелтариона, чтобы узнать, что там делает Культ Проклятых. Вернитесь к Серинару и расскажите о том, что они замышляют.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мы – черные драконы. Тысячи лет мы сеяли разрушение в землях Азерота. Этот жалкий Культ Проклятых все же поклоняется смерти – что ж, мы будем рады им помочь!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я устал от этой эпидемии.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Обнаружить зал воскрешения магмазмеев',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Серинару в Пасть Нелтариона, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12264,'Разборка с Проклятыми','Пещера наверху буквально кишит злодеями Культа. С такими созданиями можно разобраться только одним способом... и ты знаешь, каким.','Убейте 3 некромантов Пылающих Глубин, 6 тлеющих созданий и 6 тлеющих упырей в Пасти Нелтариона, а затем возвращайтесь к Серинару.','Слышать их вопли... Видеть, как последнее биение жизни исчезает из их жалких тел... вдохновляет, не правда ли?$B$BСмакую каждый момент!..','Я не могу не задаться вопросом, достаточно ли они наивны, чтобы думать, что я выдержу это, или они просто склонны к самоубийству.','Вернитесь к Серинару в Пасть Нелтариона, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разборка с Проклятыми',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пещера наверху буквально кишит злодеями Культа. С такими созданиями можно разобраться только одним способом... и ты знаешь, каким.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 3 некромантов Пылающих Глубин, 6 тлеющих созданий и 6 тлеющих упырей в Пасти Нелтариона, а затем возвращайтесь к Серинару.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Слышать их вопли... Видеть, как последнее биение жизни исчезает из их жалких тел... вдохновляет, не правда ли?$B$BСмакую каждый момент!..',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я не могу не задаться вопросом, достаточно ли они наивны, чтобы думать, что я выдержу это, или они просто склонны к самоубийству.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Серинару в Пасть Нелтариона, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12265,'Осквернение осквернителей','Я чувствую крупное средоточие магии в рунах, обнаруженных при исследовании пещеры. У нас нет времени на сложные магические ритуалы... порою самое грубое решение является и самым эффективным.$B$BУничтожь руны. Разрушь их и сделай так, чтобы последователи Культа никогда не получили доступа к заключенной в них мощи.','Найдите и уничтожьте 8 некромантских рун, выявленных на дне Пасти Нелтариона. Выполнив это, возвращайтесь к Серинару.','Хорошо. Но это еще не все.','Власть растрачивается на слабых и бесполезных.$B$BПокажи мне существо, достойное жизни и магии, которыми они были одарены и тогда, возможно, мы сможем поговорить о растрате, прежде чем погасить их присутствие.$B$BНе волнуйся, я жду.','Вернитесь к Серинару в Пасть Нелтариона, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Осквернение осквернителей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я чувствую крупное средоточие магии в рунах, обнаруженных при исследовании пещеры. У нас нет времени на сложные магические ритуалы... порою самое грубое решение является и самым эффективным.$B$BУничтожь руны. Разрушь их и сделай так, чтобы последователи Культа никогда не получили доступа к заключенной в них мощи.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите и уничтожьте 8 некромантских рун, выявленных на дне Пасти Нелтариона. Выполнив это, возвращайтесь к Серинару.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо. Но это еще не все.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Власть растрачивается на слабых и бесполезных.$B$BПокажи мне существо, достойное жизни и магии, которыми они были одарены и тогда, возможно, мы сможем поговорить о растрате, прежде чем погасить их присутствие.$B$BНе волнуйся, я жду.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Серинару в Пасть Нелтариона, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (12266,'Рассказ о разрушении','Отправляйтесь обратно в Драконий Покой и расскажите Нэлис, что задание Серинара выполнено.','А, это ты.$B$BЯ надеялась, что Серинар просто вернется, когда задание будет выполнено. А он, видно, в очередной раз отвлекся, погнавшись за какой-нибудь жертвой. Он рискует пропустить славную заварушку!$B$BТы что, еще здесь? Я с тобой закончила.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рассказ о разрушении',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь обратно в Драконий Покой и расскажите Нэлис, что задание Серинара выполнено.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, это ты.$B$BЯ надеялась, что Серинар просто вернется, когда задание будет выполнено. А он, видно, в очередной раз отвлекся, погнавшись за какой-нибудь жертвой. Он рискует пропустить славную заварушку!$B$BТы что, еще здесь? Я с тобой закончила.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12267,'Пламя Нелтариона','Теперь, когда ряды сектантов поредели и сил у них поубавилось, самое время нанести удар по источнику заразы.$b$bРотин Гниющий в глубине пещеры воскрешает черных драконов в облике магмазмеев. Проберись в чертог Призыва и очисти оставшиеся кости – единственным способом, который не позволит их больше использовать: пламенем!$b$bКонечно, как только Ротин обнаружит, что кости горят, он тут же явится сам, так что тебе придется уничтожить и его тоже.$b$bЭтот магический сосуд поможет тебе выполнить задачу.','Используйте пламя Нелтариона, чтобы очистить область призыва в глубине Пасти Нелтариона. После того как привлечете внимание Ротина Гниющего, убейте его, затем вернитесь к Серинару у входа в пещеру.','Ты довольно эффективный инструмент, $C. Благодарим тебя за участие в этой чистке.','Вернитесь к Серинару в Пасть Нелтариона, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пламя Нелтариона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда ряды сектантов поредели и сил у них поубавилось, самое время нанести удар по источнику заразы.$b$bРотин Гниющий в глубине пещеры воскрешает черных драконов в облике магмазмеев. Проберись в чертог Призыва и очисти оставшиеся кости – единственным способом, который не позволит их больше использовать: пламенем!$b$bКонечно, как только Ротин обнаружит, что кости горят, он тут же явится сам, так что тебе придется уничтожить и его тоже.$b$bЭтот магический сосуд поможет тебе выполнить задачу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте пламя Нелтариона, чтобы очистить область призыва в глубине Пасти Нелтариона. После того как привлечете внимание Ротина Гниющего, убейте его, затем вернитесь к Серинару у входа в пещеру.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты довольно эффективный инструмент, $C. Благодарим тебя за участие в этой чистке.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Серинару в Пасть Нелтариона, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12268,'Запчасти','Фу! Ну и мешанина!$b$bНет, гоблинам все-таки далеко до нас в области механики. Вот, ты только посмотри! Удивительно, что эта штуковина вообще работает.$b$bСлушай, может, ты мне слегка пособишь? Чтобы довести это устройство до ума, мне надо будет заменить несколько колесиков, шестеренок и пружин. Найти их не составит труда – они в изобилии валяются вокруг лесопилки.','Сгодится. Ну-ка, подкрутим здесь...$B$BВсе готово! Еще один крошшер готов к бою. Спасибо, $N.','Что, уже тащишь запчасти?','Вернитесь к Трубкочисту на Лесозаготовки Синего Неба, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Запчасти',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Фу! Ну и мешанина!$b$bНет, гоблинам все-таки далеко до нас в области механики. Вот, ты только посмотри! Удивительно, что эта штуковина вообще работает.$b$bСлушай, может, ты мне слегка пособишь? Чтобы довести это устройство до ума, мне надо будет заменить несколько колесиков, шестеренок и пружин. Найти их не составит труда – они в изобилии валяются вокруг лесопилки.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сгодится. Ну-ка, подкрутим здесь...$B$BВсе готово! Еще один крошшер готов к бою. Спасибо, $N.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что, уже тащишь запчасти?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Трубкочисту на Лесозаготовки Синего Неба, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12269,'Только не c нашего рудника!','По поручению верховного лорде Леорика фон Цельдига из крепости Стражей Зимы на Драконьем Погосте добудьте 10 удостоверений шахтера Стражей Зимы.','<Леорик берет у вас удостоверения.>$B$BЯ отнесу это нашему регистратору и принесу печальные вести семьям погибших горняков.$B$BСделать предстоит еще очень многое, если мы хотим добиться успеха здесь и, в конечном счете, у Врат Гнева. Лорд Фордрагон рассчитывает на нас.','Тебе удалось раздобыть их удостоверения?','Вернитесь к верховному лорду Леорику фон Цельдигу в Крепость Стражей Зимы, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Только не c нашего рудника!',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По поручению верховного лорде Леорика фон Цельдига из крепости Стражей Зимы на Драконьем Погосте добудьте 10 удостоверений шахтера Стражей Зимы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Леорик берет у вас удостоверения.>$B$BЯ отнесу это нашему регистратору и принесу печальные вести семьям погибших горняков.$B$BСделать предстоит еще очень многое, если мы хотим добиться успеха здесь и, в конечном счете, у Врат Гнева. Лорд Фордрагон рассчитывает на нас.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось раздобыть их удостоверения?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному лорду Леорику фон Цельдигу в Крепость Стражей Зимы, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12270,'Искрошить Альянс','$GДоставил:Доставила; мне крошшеры, $C?','Вернитесь к Грекку на Лесозаготовки Синего Неба, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Искрошить Альянс',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$GДоставил:Доставила; мне крошшеры, $C?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Грекку на Лесозаготовки Синего Неба, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12271,'Жезл принуждения','Отнесите жезл истязателя верховному палачу Росу в Ядозлобь.','Ты забрал жезл у их истязателя?','Вернитесь к верховному палачу Росу в Ядозлобь, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жезл принуждения',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите жезл истязателя верховному палачу Росу в Ядозлобь.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты забрал жезл у их истязателя?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному палачу Росу в Ядозлобь, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12272,'Кровоточащая руда','По поручению осадного инженера Полувспыха из крепости Стражей Зимы на Драконьем Погосте добудьте 10 образцов странной руды на руднике Стражей Зимы.','Тебе удалось добыть образцы той странной руды?','Вернитесь к осадному инженеру Полувспыху в Крепость Стражей Зимы, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кровоточащая руда',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По поручению осадного инженера Полувспыха из крепости Стражей Зимы на Драконьем Погосте добудьте 10 образцов странной руды на руднике Стражей Зимы.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось добыть образцы той странной руды?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к осадному инженеру Полувспыху в Крепость Стражей Зимы, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12273,'Отречение','Пришло время окончательно деморализовать силы Алого Натиска!$B$BЯ хочу, чтобы ты $gвзял:взяла; жезл и $gвоздействовал:воздействовала; им на четырех его лидеров. Командир Джордан находится в казарамах наверху, главный канонир Зирхат – на юго-восточном склоне, ведет наблюдение за берегом, кузнец Гудман – в кузнице, а смотритель стойл Мерсер – в конюшнях.$B$BВоздействуй на них жезлом принуждения, сосредоточься на том, чтобы заставить их отречься от Алого Натиска, а затем убей!','По заданию верховного палача Роса из Ядозлоби воздействуйте жезлом принуждения на командира Джордана, главного канонира Зирхата, кузнеца Гудмана и смотрителя стойл Мерсера.$B$BКогда они подпадут под влияние жезла, убейте каждого из них, вырвав у них перед смертью признание об отречении от Алого Натиска.','Что ж?!','Вернитесь к верховному палачу Росу в Ядозлобь, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отречение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пришло время окончательно деморализовать силы Алого Натиска!$B$BЯ хочу, чтобы ты $gвзял:взяла; жезл и $gвоздействовал:воздействовала; им на четырех его лидеров. Командир Джордан находится в казарамах наверху, главный канонир Зирхат – на юго-восточном склоне, ведет наблюдение за берегом, кузнец Гудман – в кузнице, а смотритель стойл Мерсер – в конюшнях.$B$BВоздействуй на них жезлом принуждения, сосредоточься на том, чтобы заставить их отречься от Алого Натиска, а затем убей!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По заданию верховного палача Роса из Ядозлоби воздействуйте жезлом принуждения на командира Джордана, главного канонира Зирхата, кузнеца Гудмана и смотрителя стойл Мерсера.$B$BКогда они подпадут под влияние жезла, убейте каждого из них, вырвав у них перед смертью признание об отречении от Алого Натиска.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что ж?!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному палачу Росу в Ядозлобь, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12274,'Греховное падение','Нам нужны сведения, которые можно получить у верховного настоятеля. Теперь, когда у нас есть облик жреца-ворона, думаю, у тебя получится потолковать с ним.$b$bУвы, нужно будет еще как-то разлучить его с его телохранителями, иначе ты от него ничего не добьешься.$b$b<Агент некоторое время размышляет, опершись на лопату.>$b$bВо, придумала! Прими этот облик, поднимись на башню аббатства и позвони в колокол. Телохранители настоятеля бросятся наружу, а ты сможешь спуститься и поговорить с ним.','Позвоните в колокол аббатства, затем поговорите с верховным настоятелем по просьбе агента Скулли из Нового Дольного Очага.','Ну как? Удалось тебе с ним поговорить?','Вернитесь к агенту Скулли в Новый Дольный Очаг, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Греховное падение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нам нужны сведения, которые можно получить у верховного настоятеля. Теперь, когда у нас есть облик жреца-ворона, думаю, у тебя получится потолковать с ним.$b$bУвы, нужно будет еще как-то разлучить его с его телохранителями, иначе ты от него ничего не добьешься.$b$b<Агент некоторое время размышляет, опершись на лопату.>$b$bВо, придумала! Прими этот облик, поднимись на башню аббатства и позвони в колокол. Телохранители настоятеля бросятся наружу, а ты сможешь спуститься и поговорить с ним.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Позвоните в колокол аббатства, затем поговорите с верховным настоятелем по просьбе агента Скулли из Нового Дольного Очага.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как? Удалось тебе с ним поговорить?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к агенту Скулли в Новый Дольный Очаг, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (12275,'Демогном','Полувспых недавно потребовал у моей группы специалиста, которого можно было бы отправить на разведку на рудник Стражей Зимы. Я отправил к нему Слинкина, своего подрывника. Я-то думал, что он сможет закрыть эту проклятую яму, после того как выполнит поручение Полувспыха, обеспечив нам таким образом еще одну победу над Плетью.$b$bНо вот прошел уже целый день, а Слинкина до сих пор нет! Мне нужен ответ! Поговори с осадным инженером Полувспыхом и отыщи моего пропавшего агента!','Поговорите с осадным инженером Полувспыхом в крепости Стражей Зимы в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Демогном',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Полувспых недавно потребовал у моей группы специалиста, которого можно было бы отправить на разведку на рудник Стражей Зимы. Я отправил к нему Слинкина, своего подрывника. Я-то думал, что он сможет закрыть эту проклятую яму, после того как выполнит поручение Полувспыха, обеспечив нам таким образом еще одну победу над Плетью.$b$bНо вот прошел уже целый день, а Слинкина до сих пор нет! Мне нужен ответ! Поговори с осадным инженером Полувспыхом и отыщи моего пропавшего агента!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с осадным инженером Полувспыхом в крепости Стражей Зимы в Драконьем Погосте.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (12276,'В поисках Слинкина','Я не получал вестей от Слинкина и не знаю, какая судьба его постигла, однако же, возможно, могу помочь его отыскать.$b$b<Полувспых протягивает вам маленькую заводную игрушку.>$b$bЭто тебе не игрушка, наш новый друг. Это мое последнее изобретение! Эта машинка предназначена для того, чтобы отыскивать потерянное. Ситуация, конечно, неблагоприятная, однако эта машинка – твой единственный шанс найти Слинкина.$b$bКогда будешь $gготов:готова; приступить к поискам, поставь робота на землю рядом со мной.','Отыщите Слинкина Демогнома в руднике Стражей Зимы. Используйте самонаводящегося робота Полувспыха, если вам нужна будет помощь в поисках рудника.','<В окостеневшей руке Слинкина зажата записка.>$B$BМеня загнали в тупик. Пока прячусь, но они знают, что я тут. Скоро меня найдут.$B$BШахтеры трудятся не покладая рук, добывая странную руду, на которой работают боевые машины Плети. Очень много болтают. Языка смерти я не понимаю, однако же некоторые, самые распространенные слова и фразы различать научился. Слово "Йогг-Сарон" произносится с большим презрением, и обычно сопровождается раскатами хохота. Руду они называют "саронит". Что бы это значило?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В поисках Слинкина',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я не получал вестей от Слинкина и не знаю, какая судьба его постигла, однако же, возможно, могу помочь его отыскать.$b$b<Полувспых протягивает вам маленькую заводную игрушку.>$b$bЭто тебе не игрушка, наш новый друг. Это мое последнее изобретение! Эта машинка предназначена для того, чтобы отыскивать потерянное. Ситуация, конечно, неблагоприятная, однако эта машинка – твой единственный шанс найти Слинкина.$b$bКогда будешь $gготов:готова; приступить к поискам, поставь робота на землю рядом со мной.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщите Слинкина Демогнома в руднике Стражей Зимы. Используйте самонаводящегося робота Полувспыха, если вам нужна будет помощь в поисках рудника.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<В окостеневшей руке Слинкина зажата записка.>$B$BМеня загнали в тупик. Пока прячусь, но они знают, что я тут. Скоро меня найдут.$B$BШахтеры трудятся не покладая рук, добывая странную руду, на которой работают боевые машины Плети. Очень много болтают. Языка смерти я не понимаю, однако же некоторые, самые распространенные слова и фразы различать научился. Слово "Йогг-Сарон" произносится с большим презрением, и обычно сопровождается раскатами хохота. Руду они называют "саронит". Что бы это значило?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12277,'Ничего не оставлять на волю случая','Если в твоем сердце есть добро, и твоя совесть чиста, читай дальше.$b$bВ этом руднике, неподалеку от помоста штейгера, спрятан внушительный запас динамита. Ступай туда, возьми несколько пачек взрывчатки и проберись ко входу в рудник. Оказавшись там, установи взрывчатку и взорви вход. Не забудь проделать это и с верхним, и с нижним входами в рудник Стражей Зимы!$b$bНичего не оставляй на волю случая. Тут обитает зло, нельзя допустить, чтобы оно выбралось наружу! Да хранит тебя Свет.','Добудьте бомбу Стражей Зимы и используйте ее, чтобы взорвать верхний и нижний стволы рудника Стражей Зимы. Выполнив задачу, вернитесь к осадному инженеру Полувспыху в крепость Стражей Зимы в Драконьем Погосте.','<Полувспых кивает.>$B$BОн был хорошим гномом, одним из наших лучших. Слинкина будет не хватать.','Вернитесь к осадному инженеру Полувспыху в Крепость Стражей Зимы, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ничего не оставлять на волю случая',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если в твоем сердце есть добро, и твоя совесть чиста, читай дальше.$b$bВ этом руднике, неподалеку от помоста штейгера, спрятан внушительный запас динамита. Ступай туда, возьми несколько пачек взрывчатки и проберись ко входу в рудник. Оказавшись там, установи взрывчатку и взорви вход. Не забудь проделать это и с верхним, и с нижним входами в рудник Стражей Зимы!$b$bНичего не оставляй на волю случая. Тут обитает зло, нельзя допустить, чтобы оно выбралось наружу! Да хранит тебя Свет.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте бомбу Стражей Зимы и используйте ее, чтобы взорвать верхний и нижний стволы рудника Стражей Зимы. Выполнив задачу, вернитесь к осадному инженеру Полувспыху в крепость Стражей Зимы в Драконьем Погосте.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Полувспых кивает.>$B$BОн был хорошим гномом, одним из наших лучших. Слинкина будет не хватать.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к осадному инженеру Полувспыху в Крепость Стражей Зимы, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12278,'Клуб "Пиво месяца"','Думаю, тебе понравится быть членом нашего клуба "Лучший пивовар месяца". Ведь это означает, что у тебя всегда будет самое лучшее и свежее пиво.$b$bЗаполни членскую карточку "Лучшего пивовара месяца" и отнеси ее Ларкину Громовару в таверну "Горючий камень" в Стальгорне.','Отнесите членскую карточку "Лучшего пивовара месяца" Ларкину Громовару в таверну "Горючий камень" в Стальгорне.','Отлично, все бумаги в порядке. Добро пожаловать в клуб, $N. $B$BТеперь ты будешь получать от нас посылки каждый месяц. Если тебе понравятся наши образцы пива – приходи к нам, и мы продадим тебе еще.','Заполнены ли у вас бланки для участия в программе?','Вернитесь к Ларкину Громовару в Дун Морог.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Клуб "Пиво месяца"',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Думаю, тебе понравится быть членом нашего клуба "Лучший пивовар месяца". Ведь это означает, что у тебя всегда будет самое лучшее и свежее пиво.$b$bЗаполни членскую карточку "Лучшего пивовара месяца" и отнеси ее Ларкину Громовару в таверну "Горючий камень" в Стальгорне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите членскую карточку "Лучшего пивовара месяца" Ларкину Громовару в таверну "Горючий камень" в Стальгорне.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, все бумаги в порядке. Добро пожаловать в клуб, $N. $B$BТеперь ты будешь получать от нас посылки каждый месяц. Если тебе понравятся наши образцы пива – приходи к нам, и мы продадим тебе еще.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Заполнены ли у вас бланки для участия в программе?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ларкину Громовару в Дун Морог.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12279,'Медвежий аппетит','Наконец-то ты вернулся, Лимпи! Я уж боялся, что мы с Гризельдой останемся одни.$B$BЯ тут приготовил нам обед, но Гризельде вряд ли понравится моя стряпня.$B$BОна предпочитает рыбку, которая водится вдоль Побережья Восточного Ветра на востоке. Я этих рыб сам на дух не переношу, но она у нас настоящий гурман. Поймай ей шесть больших рыбин, и она будет счастлива.$B$BНу давай, беги же! Не стоит заставлять нашу девочку ждать!','Принесите 6 северных лососей Хью Глассу в Торговую лавку Красного леса.','Эй! Да ты не Хромоногий Джо!','Если не поторопишься, будешь сам бурчать у нее в желудке!','Вернитесь к Хью Глассу в торговую лавку Красного леса, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Медвежий аппетит',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наконец-то ты вернулся, Лимпи! Я уж боялся, что мы с Гризельдой останемся одни.$B$BЯ тут приготовил нам обед, но Гризельде вряд ли понравится моя стряпня.$B$BОна предпочитает рыбку, которая водится вдоль Побережья Восточного Ветра на востоке. Я этих рыб сам на дух не переношу, но она у нас настоящий гурман. Поймай ей шесть больших рыбин, и она будет счастлива.$B$BНу давай, беги же! Не стоит заставлять нашу девочку ждать!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 6 северных лососей Хью Глассу в Торговую лавку Красного леса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Эй! Да ты не Хромоногий Джо!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если не поторопишься, будешь сам бурчать у нее в желудке!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хью Глассу в торговую лавку Красного леса, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12280,'Починки','Двадцать крошшеров к завтрашнему утру!$b$bЧто за светлая голова составляет эти графики? Могу поспорить, он даже близко не подходил к этим консервным банкам... $b$bМ-да... если я хочу уложиться в график, мне понадобится помощь. Если протянешь мне руку – отсыплю тебе кое-что из моей доли! $gСогласен:Согласна;?$b$bМне нужны колеса, шестеренки и пружины – они тут валяются повсюду.','Спасибо, $N. Этого мне хватит – во всяком случае, до завтра...$B$BА вот и обещанные деньги.','Что, уже тащишь запчасти?','Вернитесь к Лурцу на Лесозаготовки Синего Неба, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Починки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Двадцать крошшеров к завтрашнему утру!$b$bЧто за светлая голова составляет эти графики? Могу поспорить, он даже близко не подходил к этим консервным банкам... $b$bМ-да... если я хочу уложиться в график, мне понадобится помощь. Если протянешь мне руку – отсыплю тебе кое-что из моей доли! $gСогласен:Согласна;?$b$bМне нужны колеса, шестеренки и пружины – они тут валяются повсюду.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо, $N. Этого мне хватит – во всяком случае, до завтра...$B$BА вот и обещанные деньги.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что, уже тащишь запчасти?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лурцу на Лесозаготовки Синего Неба, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (12281,'Понимание военной машины Плети','Мы должны утешаться тем фактом, что смерть Слинкина, хотя и трагическая, послужила высшему благу. Его открытие, вкупе с твоими героическими деяниями в шахте и образцами, которые ты $gвернул:вернула;, делает нас на шаг ближе к пониманию военной машины Плети.$B$BДоставь этот пакет главнокомандующему Халфорду Змеевержцу. В нем – образец этой странной руды и результаты моих исследований.','Доставьте амуницию Полувспыха главнокомандующему Халфорду Змеевержцу в крепость Стражей Зимы.','Вернитесь к главнокомандующему Халфорду Змеевержцу в Крепость Стражей Зимы, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Понимание военной машины Плети',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы должны утешаться тем фактом, что смерть Слинкина, хотя и трагическая, послужила высшему благу. Его открытие, вкупе с твоими героическими деяниями в шахте и образцами, которые ты $gвернул:вернула;, делает нас на шаг ближе к пониманию военной машины Плети.$B$BДоставь этот пакет главнокомандующему Халфорду Змеевержцу. В нем – образец этой странной руды и результаты моих исследований.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте амуницию Полувспыха главнокомандующему Халфорду Змеевержцу в крепость Стражей Зимы.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к главнокомандующему Халфорду Змеевержцу в Крепость Стражей Зимы, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12282,'Отпечатки былого','Эта земля наполнена воспоминаниями о былом, $n. По всему Нордсколу отдаются немым эхом взывающие ко мне голоса.$b$bНа всем, чего коснулся Артас, он оставил жуткие отпечатки. Там, где он прошел, остаются лишь смерть и увядание. Вот почему так важно тщательно изучать историю, чтобы знать врага в лицо. Быть может, рано или поздно из глубины веков всплывут забытые истины, которые пригодятся нам в настоящем.$b$bДля начала, $n, добудь из ратуши мой гадальный шар. Выйдя из башни, ступай налево, и выйдешь на городскую площадь.','Принесите Зелигу Иллюзорному из крепости Стражей Зимы в Драконьем Погосте его гадальный шар.','Удалось тебе найти мой шар?','Вернитесь к Зелигу Иллюзорному в Крепость Стражей Зимы, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отпечатки былого',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эта земля наполнена воспоминаниями о былом, $n. По всему Нордсколу отдаются немым эхом взывающие ко мне голоса.$b$bНа всем, чего коснулся Артас, он оставил жуткие отпечатки. Там, где он прошел, остаются лишь смерть и увядание. Вот почему так важно тщательно изучать историю, чтобы знать врага в лицо. Быть может, рано или поздно из глубины веков всплывут забытые истины, которые пригодятся нам в настоящем.$b$bДля начала, $n, добудь из ратуши мой гадальный шар. Выйдя из башни, ступай налево, и выйдешь на городскую площадь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Зелигу Иллюзорному из крепости Стражей Зимы в Драконьем Погосте его гадальный шар.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось тебе найти мой шар?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Зелигу Иллюзорному в Крепость Стражей Зимы, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (12283,'Правду не скроешь','Нужно выяснить, что здесь происходит. Нам нужен дневник генерала!$b$bЯ почти уверена, что ты найдешь дневник на ее ночном столике на втором этаже ее дома. Этот дом находится рядом с церковью, напротив стойл и лесопилки.$b$bКак добудешь дневник, отнеси его в Ядозлобь, верховному палачу.$b$bДелать это придется по старинке: сила зеркала иссякла, мне самой едва хватит!$b$b<Агент ухмыляется.>','Добудьте дневник верховного генерала Аббендис по просьбе агента Скулли и передайте этот дневник верховному палачу Росу в Ядозлоби.','Провались оно все! Нет бы принести мне хорошие новости!','Вернитесь к верховному палачу Росу в Ядозлобь, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Правду не скроешь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нужно выяснить, что здесь происходит. Нам нужен дневник генерала!$b$bЯ почти уверена, что ты найдешь дневник на ее ночном столике на втором этаже ее дома. Этот дом находится рядом с церковью, напротив стойл и лесопилки.$b$bКак добудешь дневник, отнеси его в Ядозлобь, верховному палачу.$b$bДелать это придется по старинке: сила зеркала иссякла, мне самой едва хватит!$b$b<Агент ухмыляется.>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте дневник верховного генерала Аббендис по просьбе агента Скулли и передайте этот дневник верховному палачу Росу в Ядозлоби.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Провались оно все! Нет бы принести мне хорошие новости!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному палачу Росу в Ядозлобь, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12284,'Преследуй по пятам','Командир Баргок приказал вам убить 15 представителей или игроков Альянса на Лесозаготовках Синего Неба.','Это кровь Альянса на твоем оружии, $R?','Вернитесь к командиру Баргку на Лесозаготовки Синего Неба, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Преследуй по пятам',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Командир Баргок приказал вам убить 15 представителей или игроков Альянса на Лесозаготовках Синего Неба.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Это кровь Альянса на твоем оружии, $R?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру Баргку на Лесозаготовки Синего Неба, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (12286,'Кулек конфет','Кульки с конфетами можно найти в любой таверне. Ну – чего стоишь? Хватай конфетку!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кулек конфет',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Кульки с конфетами можно найти в любой таверне. Ну – чего стоишь? Хватай конфетку!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (12287,'Орик Чистосердечный и Забытое взморье','Я смотрел на сферу и видел путь, которым тебе должно пройти, $n.$B$BМного лет назад ужасное злодеяние было совершено на берегах Драконьего Погоста. Что тебе надлежит сделать – то покрыто тьмой, но я уверен, что твоя судьба – на юге, среди руин Забытого взморья.$B$BОтправляйся по дороге на юго-восток через разоренную городскую площадь. Следуй этим путем, пока не доберешься до Рассветного края. Там встретишь моего старого друга по имени Орик Чистосердечный. Он будет ждать тебя.','Ищите помощи у Орика Чистосердечного в Рассветном краю на Драконьем Погосте.','Зелиг сообщил, что ты придешь, друг мой.$B$BЯ Орик Чистосердечный, паладин Серебряного Авангарда. Жрица, что стоит напротив меня на другой стороне костра – Тильда Даратан. Мы здесь по заданию Серебряного Авангарда – присланы успокоить несчастные проклятые души, пытающиеся сбежать из крепости Стражей Зимы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Орик Чистосердечный и Забытое взморье',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я смотрел на сферу и видел путь, которым тебе должно пройти, $n.$B$BМного лет назад ужасное злодеяние было совершено на берегах Драконьего Погоста. Что тебе надлежит сделать – то покрыто тьмой, но я уверен, что твоя судьба – на юге, среди руин Забытого взморья.$B$BОтправляйся по дороге на юго-восток через разоренную городскую площадь. Следуй этим путем, пока не доберешься до Рассветного края. Там встретишь моего старого друга по имени Орик Чистосердечный. Он будет ждать тебя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Ищите помощи у Орика Чистосердечного в Рассветном краю на Драконьем Погосте.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Зелиг сообщил, что ты придешь, друг мой.$B$BЯ Орик Чистосердечный, паладин Серебряного Авангарда. Жрица, что стоит напротив меня на другой стороне костра – Тильда Даратан. Мы здесь по заданию Серебряного Авангарда – присланы успокоить несчастные проклятые души, пытающиеся сбежать из крепости Стражей Зимы.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12288,'В военном лазарете','Эй, |3-6($c)! Пожалуйста, помоги нам!$b$bМы понесли тяжелые потери. Столько раненых... одной мне никогда не исцелить всех их. А если наши солдаты не встанут на ноги, нам придется сдавать позиции и уходить из Седых холмов!$b$bВот, возьми этот бинт и приступай к перевязке раненых на поле боя.$b$bПоторопись, $n, иначе они умрут!!!','Спасибо, $Gдорогой:дорогая; $N!$B$BБлагодаря тебе мы сможем продержаться еще один день. Может быть, для нас еще есть надежда выжить...','Ты уже $Gисцелил:исцелила; наших раненых, $N?','Вернитесь к Аумане на Лесозаготовки Синего Неба, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В военном лазарете',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эй, |3-6($c)! Пожалуйста, помоги нам!$b$bМы понесли тяжелые потери. Столько раненых... одной мне никогда не исцелить всех их. А если наши солдаты не встанут на ноги, нам придется сдавать позиции и уходить из Седых холмов!$b$bВот, возьми этот бинт и приступай к перевязке раненых на поле боя.$b$bПоторопись, $n, иначе они умрут!!!',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо, $Gдорогой:дорогая; $N!$B$BБлагодаря тебе мы сможем продержаться еще один день. Может быть, для нас еще есть надежда выжить...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты уже $Gисцелил:исцелила; наших раненых, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аумане на Лесозаготовки Синего Неба, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12289,'Нападем, пока враг слаб!','Прекрасно, $N.$B$BТы $Gвыиграл:выиграла; для нас немного времени – вряд ли больше, чем один день, но Альянс благодарен тебе за каждую минуту передышки.','Как идет бой, $N?','Вернитесь к сержанту Хартсману на Лесозаготовки Синего Неба, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нападем, пока враг слаб!',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно, $N.$B$BТы $Gвыиграл:выиграла; для нас немного времени – вряд ли больше, чем один день, но Альянс благодарен тебе за каждую минуту передышки.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как идет бой, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к сержанту Хартсману на Лесозаготовки Синего Неба, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12290,'Эликсир из темноплевела','На побережье бродят духи проклятых. В жизни то были отважные и благородные воины Альянса, но в смерти их настигло проклятие – они прикованы к этому миру до конца времен. Чтобы их освободить, нужно узнать, что их так терзает!$b$bК юго-востоку отсюда, на зловещей Возвышенности, растет редкая травка, именуемая темноплевелом. Из этого темноплевела я могу приготовить эликсир, который позволит тебе на время войти в мир забытых душ. Ступай, набери этой травы.','Добудьте на Зловещей возвышенности 5 экземпляров темноплевела по просьбе Орика Чистосердечного из Рассветного края в Драконьем Погосте.','Удалось ли тебе набрать темноплевела?','Вернитесь к Орику Чистосердечному в Рассветный край, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Эликсир из темноплевела',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На побережье бродят духи проклятых. В жизни то были отважные и благородные воины Альянса, но в смерти их настигло проклятие – они прикованы к этому миру до конца времен. Чтобы их освободить, нужно узнать, что их так терзает!$b$bК юго-востоку отсюда, на зловещей Возвышенности, растет редкая травка, именуемая темноплевелом. Из этого темноплевела я могу приготовить эликсир, который позволит тебе на время войти в мир забытых душ. Ступай, набери этой травы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте на Зловещей возвышенности 5 экземпляров темноплевела по просьбе Орика Чистосердечного из Рассветного края в Драконьем Погосте.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось ли тебе набрать темноплевела?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Орику Чистосердечному в Рассветный край, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12291,'Забытая повесть','Яды, содержащиеся в эликсире из темноплевела, заставят тебя потерять сознание. Темноплевел оказывает столь мощное воздействие, что даже твой дух будет обманут. Это позволит тебе на время вступить в мир мертвых.$b$bСделавшись духом, поговори с призрачными обитателями Забытого взморья. Узнай, отчего они так страдают, и возвращайся ко мне.$b$bПомни, $n: некогда эти духи были солдатами Альянса! Держись с ними почтительно, как то подобает их достоинству!$b$bНу, вот тебе эликсир, ступай на юг, на Забытое взморье.','Выслушайте повесть о бедствиях забытого крестьянина, забытого ружейника, забытого рыцаря и забытого пехотинца по просьбе Орика Чистосердечного из Рассветного края в Драконьем Погосте.','У меня достаточно болотной травы, чтобы сделать больше эликсиров, $N.','Вернитесь к Орику Чистосердечному в Рассветный край, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Забытая повесть',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Яды, содержащиеся в эликсире из темноплевела, заставят тебя потерять сознание. Темноплевел оказывает столь мощное воздействие, что даже твой дух будет обманут. Это позволит тебе на время вступить в мир мертвых.$b$bСделавшись духом, поговори с призрачными обитателями Забытого взморья. Узнай, отчего они так страдают, и возвращайся ко мне.$b$bПомни, $n: некогда эти духи были солдатами Альянса! Держись с ними почтительно, как то подобает их достоинству!$b$bНу, вот тебе эликсир, ступай на юг, на Забытое взморье.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выслушайте повесть о бедствиях забытого крестьянина, забытого ружейника, забытого рыцаря и забытого пехотинца по просьбе Орика Чистосердечного из Рассветного края в Драконьем Погосте.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У меня достаточно болотной травы, чтобы сделать больше эликсиров, $N.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Орику Чистосердечному в Рассветный край, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (12292,'Помощь местных жителей','Лейтенант Думонт из Приюта Янтарной Сосны поручил вам добраться до Торговой лавки Вечнозеленого леса и забрать кедровый сундук.','Вернитесь к лейтенанту Думонту в Приют Янтарной Сосны, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Помощь местных жителей',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Лейтенант Думонт из Приюта Янтарной Сосны поручил вам добраться до Торговой лавки Вечнозеленого леса и забрать кедровый сундук.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лейтенанту Думонту в Приют Янтарной Сосны, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12293,'Дело сделано','Теперь у нас есть то, что нужно звероловам. Осталось только подписать с ними договор о сотрудничестве! $B$BОтнеси ящик зверолову по имени Иван на Заставу Тополиной рощи, что к северу отсюда.$B$BЕсли наши предположения верны, местные звероловы с радостью присоединятся к королевской армии.','Отнесите кедровый сундук Ивану на Заставу Тополиной рощи.','Это для нас?','Вернитесь к Ивану на Заставу Тополиной рощи, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дело сделано',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь у нас есть то, что нужно звероловам. Осталось только подписать с ними договор о сотрудничестве! $B$BОтнеси ящик зверолову по имени Иван на Заставу Тополиной рощи, что к северу отсюда.$B$BЕсли наши предположения верны, местные звероловы с радостью присоединятся к королевской армии.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите кедровый сундук Ивану на Заставу Тополиной рощи.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Это для нас?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ивану на Заставу Тополиной рощи, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (12294,'Заключение договора','Рад слышать, что твои люди выполнили свою часть сделки. $B$BСкажи Думонту, что мы тоже сдержим слово.','Вернитесь к лейтенанту Думонту в Приют Янтарной Сосны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Заключение договора',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Рад слышать, что твои люди выполнили свою часть сделки. $B$BСкажи Думонту, что мы тоже сдержим слово.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь к лейтенанту Думонту в Приют Янтарной Сосны.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (12295,'Урок дипломатии','Мы уже давно пытались договориться со звероловами, но они отказывались идти нам навстречу. Однако теперь, когда у нас есть их дурацкий ящик, дело должно сдвинуться с мертвой точки.$B$BХорошие новости для наших послов в Среброречье! Неделю назад мы отправили туда Дюкаля, и ему даже удалось добиться некоторого прогресса, судя по его последнему донесению.$B$BСтупай в Среброречье и помоги ему заключить договор. Город находится прямо по дороге на северо-запад.','Поговорите с военным атташе Дюкалем в Среброречье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Урок дипломатии',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы уже давно пытались договориться со звероловами, но они отказывались идти нам навстречу. Однако теперь, когда у нас есть их дурацкий ящик, дело должно сдвинуться с мертвой точки.$B$BХорошие новости для наших послов в Среброречье! Неделю назад мы отправили туда Дюкаля, и ему даже удалось добиться некоторого прогресса, судя по его последнему донесению.$B$BСтупай в Среброречье и помоги ему заключить договор. Город находится прямо по дороге на северо-запад.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с военным атташе Дюкалем в Среброречье.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (12296,'На грани жизни и смерти','Какая страшная битва...$b$bЯ побывала во многих сражениях, |3-6($c), но эта резня была самой жестокой из всех. Наши стычки с Ордой стали еще более ожесточенными. Идет война за право оставаться здесь, в Нордсколе – война не на жизнь, а на смерть.$b$bЕсли мы хотим продержаться здесь еще хотя бы день, нам надо перевязать раненых. Их здесь слишком много... мне не справиться одной.$b$bВот, я подготовила специальные бинты. Возьми их, если хочешь помочь мне исцелить наших бойцов.','Отлично!$B$BБлагодаря тебе Альянс продержится еще один день.$B$BСпасибо тебе, $Gдруг:подруга;.','Вернитесь к Реанне на Лесозаготовки Синего Неба, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На грани жизни и смерти',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Какая страшная битва...$b$bЯ побывала во многих сражениях, |3-6($c), но эта резня была самой жестокой из всех. Наши стычки с Ордой стали еще более ожесточенными. Идет война за право оставаться здесь, в Нордсколе – война не на жизнь, а на смерть.$b$bЕсли мы хотим продержаться здесь еще хотя бы день, нам надо перевязать раненых. Их здесь слишком много... мне не справиться одной.$b$bВот, я подготовила специальные бинты. Возьми их, если хочешь помочь мне исцелить наших бойцов.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично!$B$BБлагодаря тебе Альянс продержится еще один день.$B$BСпасибо тебе, $Gдруг:подруга;.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Реанне на Лесозаготовки Синего Неба, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12297,'О предателях и предательстве','Этот список необходимо доставить главнокомандующему Халфорду Змеевержцу. Он командует седьмым легионом, расположенным в Крепости Стражей Зимы на восточной границе Драконьего Погоста.$B$BЕсли кто-нибудь из предателей, упомянутых в этом списке, умудрился втереться к нему в доверие... последствия могут быть необратимыми.$B$BТоропись, $n. Покажи этот документ Гриру Рудомолоту в Крепости Западной Стражи и объясни всю важность твоего поручения. Тогда он посадит тебя на самого быстрого грифона, знающего путь в Крепость Стражей Зимы!','Капитан Адамс попросил вас показать депешу Альянса Гриру Рудомолоту из Крепости Западной Стражи.','<Грир читает депешу поверх очков, время от времени бросая на вас заинтересованные взгляды.>$B$BБудет тебе самый стремительный грифон! Эту информацию нужно немедленно передать главнокомандующему Змеевержцу!','Здравствуй, |3-6($C).','Вернитесь к Гриру Рудомолоту в Ревущий фьорд.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','О предателях и предательстве',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этот список необходимо доставить главнокомандующему Халфорду Змеевержцу. Он командует седьмым легионом, расположенным в Крепости Стражей Зимы на восточной границе Драконьего Погоста.$B$BЕсли кто-нибудь из предателей, упомянутых в этом списке, умудрился втереться к нему в доверие... последствия могут быть необратимыми.$B$BТоропись, $n. Покажи этот документ Гриру Рудомолоту в Крепости Западной Стражи и объясни всю важность твоего поручения. Тогда он посадит тебя на самого быстрого грифона, знающего путь в Крепость Стражей Зимы!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Капитан Адамс попросил вас показать депешу Альянса Гриру Рудомолоту из Крепости Западной Стражи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Грир читает депешу поверх очков, время от времени бросая на вас заинтересованные взгляды.>$B$BБудет тебе самый стремительный грифон! Эту информацию нужно немедленно передать главнокомандующему Змеевержцу!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Здравствуй, |3-6($C).',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гриру Рудомолоту в Ревущий фьорд.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12298,'Главнокомандующий Халфорд Змеевержец','<Грир отдает вам депешу.>$B$BНебесная Песня отвезет тебя в Крепость Стражей Зимы, $n. Могу поспорить, ты еще никогда не $gлетал:летала; на таком быстром грифоне. Вперед!','Отвезите депешу Альянса главнокомандующему Халфорду Змеевержцу в Крепость Стражей Зимы, которая находится на востоке Драконьего Погоста.','<Главнокомандующий дочитывает депешу и раздраженно комкает ее.>$B$BТы знаешь, где сейчас эти люди, упомянутые в списке? Вон они, рядом с главными воротами, болтаются на виселице.$B$BПриманка для упырей...','Что у тебя, солдат?','Вернитесь к главнокомандующему Халфорду Змеевержцу в Крепость Стражей Зимы, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Главнокомандующий Халфорд Змеевержец',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Грир отдает вам депешу.>$B$BНебесная Песня отвезет тебя в Крепость Стражей Зимы, $n. Могу поспорить, ты еще никогда не $gлетал:летала; на таком быстром грифоне. Вперед!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отвезите депешу Альянса главнокомандующему Халфорду Змеевержцу в Крепость Стражей Зимы, которая находится на востоке Драконьего Погоста.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Главнокомандующий дочитывает депешу и раздраженно комкает ее.>$B$BТы знаешь, где сейчас эти люди, упомянутые в списке? Вон они, рядом с главными воротами, болтаются на виселице.$B$BПриманка для упырей...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что у тебя, солдат?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к главнокомандующему Халфорду Змеевержцу в Крепость Стражей Зимы, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12299,'Северное гостеприимство','Ты уже $Gзакончил:закончила; с этими ордынскими кретинами?','Вернитесь к Сергею в Среброречье, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Северное гостеприимство',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты уже $Gзакончил:закончила; с этими ордынскими кретинами?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сергею в Среброречье, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12300,'Испытание смелости','Ладно, дружок. Пару раз ты нас действительно $gвыручил:выручила;, но это еще не показатель смелости. $B$BВ наших краях нельзя стать настоящим охотником, не почувствовав себя в шкуре жертвы.$B$B<Сергей вытаскивает из ножен свой охотничий нож и протягивает его вам.>$B$BПредводителя проклятых орков, нападающих на наш город, зовут Костехват. Его легко найти в лагере на северо-западе.$B$BДа, ты меня правильно $gпонял:поняла;: я поручаю тебе освежевать этого мерзавца.','Найдите часового Костехвата к северо-западу от Среброречья и пройдите испытание смелости.','Люди в Сильвербруке... они не те, кем кажутся.','Вернитесь к пленному зверолову на Холмы Среброречья, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Испытание смелости',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ладно, дружок. Пару раз ты нас действительно $gвыручил:выручила;, но это еще не показатель смелости. $B$BВ наших краях нельзя стать настоящим охотником, не почувствовав себя в шкуре жертвы.$B$B<Сергей вытаскивает из ножен свой охотничий нож и протягивает его вам.>$B$BПредводителя проклятых орков, нападающих на наш город, зовут Костехват. Его легко найти в лагере на северо-западе.$B$BДа, ты меня правильно $gпонял:поняла;: я поручаю тебе освежевать этого мерзавца.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите часового Костехвата к северо-западу от Среброречья и пройдите испытание смелости.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Люди в Сильвербруке... они не те, кем кажутся.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к пленному зверолову на Холмы Среброречья, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (12301,'Правда вернет нам свободу','Зелиг дал мне эту хрустальную сферу много лет назад, особо проинструктировав касательно ее использования. В течение пяти лет – чувствовал ли я гнев, беспокойство или печаль из-за событий, происходивших здесь – я должен был сосредотачивать свои мысли на этой сфере.$B$BТеперь я понимаю, почему Зелиг отдал этот кристалл мне.$B$BОтнеси мою хрустальную сферу на Забытое взморье. Найди развалины моей старой базы в верхней части побережья и помести сферу в центре поселения. Пусть обитающие там увидят мир через призму моего сердца и моей души.','По просьбе Орика Чистосердечного из Рассветного края, что на Драконьем Погосте, задействуйте хрустальную сферу Орика в развалинах, расположенных на Забытом взморье, для освобождения обитающих там Забытых.','Забытые освобождены','Вернитесь к Орику Чистосердечному в Рассветный край, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Правда вернет нам свободу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Зелиг дал мне эту хрустальную сферу много лет назад, особо проинструктировав касательно ее использования. В течение пяти лет – чувствовал ли я гнев, беспокойство или печаль из-за событий, происходивших здесь – я должен был сосредотачивать свои мысли на этой сфере.$B$BТеперь я понимаю, почему Зелиг отдал этот кристалл мне.$B$BОтнеси мою хрустальную сферу на Забытое взморье. Найди развалины моей старой базы в верхней части побережья и помести сферу в центре поселения. Пусть обитающие там увидят мир через призму моего сердца и моей души.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По просьбе Орика Чистосердечного из Рассветного края, что на Драконьем Погосте, задействуйте хрустальную сферу Орика в развалинах, расположенных на Забытом взморье, для освобождения обитающих там Забытых.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Забытые освобождены',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Орику Чистосердечному в Рассветный край, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (12302,'Предупреждение','Спасибо за помощь, $n. Меня зовут Саша. Послушай, мне очень надо выбраться отсюда.$B$BЛюди, которые послали тебя сюда... мои товарищи... с ними что-то произошло. Они изменились... Они хотят... сделать тебя $gодним:одной; из них.$B$BЭто испытание – всего лишь начало...$B$BДойди до северо-запада Среброречья, и ты увидишь все собственными глазами.$B$BУдачи... и помни – никому нельзя доверять!','Дойдите до северо-западного края Среброречья.','Кто здесь? Ты хочешь меня убить?$B$BНе надо! Пожалуйста, не трогай меня!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Предупреждение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Спасибо за помощь, $n. Меня зовут Саша. Послушай, мне очень надо выбраться отсюда.$B$BЛюди, которые послали тебя сюда... мои товарищи... с ними что-то произошло. Они изменились... Они хотят... сделать тебя $gодним:одной; из них.$B$BЭто испытание – всего лишь начало...$B$BДойди до северо-запада Среброречья, и ты увидишь все собственными глазами.$B$BУдачи... и помни – никому нельзя доверять!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Дойдите до северо-западного края Среброречья.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Кто здесь? Ты хочешь меня убить?$B$BНе надо! Пожалуйста, не трогай меня!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12303,'Финансовое обеспечение военных нужд','По заданию интенданта Бартлетта из Ядозлоби добудьте 6 сундучков с забытыми сокровищами.','Ну, и на сколько сокровищ Альянса тебе удалось наложить свою руку?','Вернитесь к интенданту Бартлетту в Ядозлобь, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Финансовое обеспечение военных нужд',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По заданию интенданта Бартлетта из Ядозлоби добудьте 6 сундучков с забытыми сокровищами.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, и на сколько сокровищ Альянса тебе удалось наложить свою руку?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к интенданту Бартлетту в Ядозлобь, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (12304,'Недвижимость на взморье','Ядозлоби пора расширить свое влияние!$B$BВ свое время мы разберемся с Алым Натиском, ну, а пока я хочу, чтобы ты $gотправился:отправилась; в место, называемое Забытым взморьем. У тех мест – огромный потенциал, а $gвидел:видела; бы ты, какой там ландшафт!..$B$BК сожалению, там полным-полно людских призраков, членов экипажей затонувших кораблей и прочих, еще не осознавших, что они уже умерли.$B$BРасчисти берег и прибрежные воды – и, быть может, мы с тобой вскоре уже сможем говорить о постройке там новой, миленькой, уютной усыпальницы.','По поручению наблюдателя Хансена, находящегося к северу от Забытого взморья убейте 20 призраков Забытого взморья.','Вернитесь к геодезисту Хансену на Забытое взморье, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Недвижимость на взморье',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ядозлоби пора расширить свое влияние!$B$BВ свое время мы разберемся с Алым Натиском, ну, а пока я хочу, чтобы ты $gотправился:отправилась; в место, называемое Забытым взморьем. У тех мест – огромный потенциал, а $gвидел:видела; бы ты, какой там ландшафт!..$B$BК сожалению, там полным-полно людских призраков, членов экипажей затонувших кораблей и прочих, еще не осознавших, что они уже умерли.$B$BРасчисти берег и прибрежные воды – и, быть может, мы с тобой вскоре уже сможем говорить о постройке там новой, миленькой, уютной усыпальницы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По поручению наблюдателя Хансена, находящегося к северу от Забытого взморья убейте 20 призраков Забытого взморья.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к геодезисту Хансену на Забытое взморье, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (12305,'Прощальные мысли','Ты $gоказал:оказала; честь и мне, и памяти сотен ветеранов Альянса, $n. Зелиг поступил мудро, прислав тебя сюда. Пожалуйста, вернись к нему и передай ему мою благодарность. Он будет рад услышать о том, что произошло на Забытом взморье.$b$bЯ, в отличие от Зелига, не наделен пророческим даром, но уверен, что тебя, друг, ждет великая судьба.$b$bПрощай!','Вернитесь к Зелигу Иллюзорному в крепость Стражей Зимы в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прощальные мысли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gоказал:оказала; честь и мне, и памяти сотен ветеранов Альянса, $n. Зелиг поступил мудро, прислав тебя сюда. Пожалуйста, вернись к нему и передай ему мою благодарность. Он будет рад услышать о том, что произошло на Забытом взморье.$b$bЯ, в отличие от Зелига, не наделен пророческим даром, но уверен, что тебя, друг, ждет великая судьба.$b$bПрощай!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь к Зелигу Иллюзорному в крепость Стражей Зимы в Драконьем Погосте.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12306,'Клуб "Пиво месяца"','Чем нас больше – тем лучше, $n. Вступив в клуб "Пиво месяца", ты сможешь дегустировать самые выдающиеся сорта пива.$b$bЗаполни членскую карточку клуба "Пиво месяца" и отнеси ее Рай\'ме в Оргриммар.','Отнесите заполненную членскую карточку клуба "Пиво месяца" Рай\'ме в Оргриммар.','А, хочешь к нам присоединиться? Тебе у нас понравится, $N. Члены нашего клуба получают все самое лучшее.$B$BВ начале каждого месяца мы будем посылать тебе образцы пива. Если оно тебе понравится – приходи сюда, и мы нальем тебе еще!','Ты $Gзаполнил:заполнила; членскую карточку?','Вернитесь к Рай\'ме в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Клуб "Пиво месяца"',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чем нас больше – тем лучше, $n. Вступив в клуб "Пиво месяца", ты сможешь дегустировать самые выдающиеся сорта пива.$b$bЗаполни членскую карточку клуба "Пиво месяца" и отнеси ее Рай\'ме в Оргриммар.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите заполненную членскую карточку клуба "Пиво месяца" Рай\'ме в Оргриммар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, хочешь к нам присоединиться? Тебе у нас понравится, $N. Члены нашего клуба получают все самое лучшее.$B$BВ начале каждого месяца мы будем посылать тебе образцы пива. Если оно тебе понравится – приходи сюда, и мы нальем тебе еще!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gзаполнил:заполнила; членскую карточку?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Рай\'ме в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12307,'Аконитовый корень','$gСлышал:Слышала; когда-нибудь про волчий борец? Мерзкая трава... из-за нее гибнет половина наших посевов.$B$BМы пололи сорняки всю прошлую неделю, но оставшиеся корни опять дали всходы!$B$BДумаешь, это все чепуха? Учти: если волчий борец опять заколосится, произойдет... нечто ужасное! Так что если увидишь этот сорняк возле деревни – выдерни его немедленно, и ты окажешь нам очень большую услугу!','Катя из Среброречья просит вас выдернуть восемь аконитовых кореньев.','Да, $C?','Вернитесь к Кате в Среброречье, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Аконитовый корень',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$gСлышал:Слышала; когда-нибудь про волчий борец? Мерзкая трава... из-за нее гибнет половина наших посевов.$B$BМы пололи сорняки всю прошлую неделю, но оставшиеся корни опять дали всходы!$B$BДумаешь, это все чепуха? Учти: если волчий борец опять заколосится, произойдет... нечто ужасное! Так что если увидишь этот сорняк возле деревни – выдерни его немедленно, и ты окажешь нам очень большую услугу!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Катя из Среброречья просит вас выдернуть восемь аконитовых кореньев.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да, $C?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кате в Среброречье, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12308,'Побег из Среброречья','Откройте деревянную клетку и помогите освобожденному разведчику Альянса сбежать из Среброречья. Когда вы доберетесь до Приюта Янтарной Сосны, доложите лейтенанту Думонту обо всем, что вы видели.','Ты $Gвернулся:вернулась;. Я волновался за тебя, $N.','Вернитесь к лейтенанту Думонту в Приют Янтарной Сосны, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Побег из Среброречья',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Откройте деревянную клетку и помогите освобожденному разведчику Альянса сбежать из Среброречья. Когда вы доберетесь до Приюта Янтарной Сосны, доложите лейтенанту Думонту обо всем, что вы видели.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gвернулся:вернулась;. Я волновался за тебя, $N.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лейтенанту Думонту в Приют Янтарной Сосны, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (12309,'Найти Дюркона!','После того как Плеть пробила южную стену, я приказал кавалеристу Дюркону разведать городской склеп. И вот буквально только что мне передали его доклад.$b$bДонимающая нас нежить лезет из двух мест: из развалин крепости Стражей Зимы, где теперь плодятся воины Плети, и из нашего же собственного городского склепа! Плеть под шумок сумела поселить там своего некролорда!$b$bДюркон просит подмоги. Отыщи его и помоги ему, $n. Склеп находится на западном краю городской площади.','Отыщите кавалериста Дюркона в склепе Стражей Зимы в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Найти Дюркона!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','После того как Плеть пробила южную стену, я приказал кавалеристу Дюркону разведать городской склеп. И вот буквально только что мне передали его доклад.$b$bДонимающая нас нежить лезет из двух мест: из развалин крепости Стражей Зимы, где теперь плодятся воины Плети, и из нашего же собственного городского склепа! Плеть под шумок сумела поселить там своего некролорда!$b$bДюркон просит подмоги. Отыщи его и помоги ему, $n. Склеп находится на западном краю городской площади.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщите кавалериста Дюркона в склепе Стражей Зимы в Драконьем Погосте.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12310,'Мгновенный ответ','Наша реакция должна быть незамедлительной. Сокрушительной. Мы должны проучить этих мерзавцев раз и навсегда.$B$BНаши разведчики засекли местонахождение выживших звероловов Среброречья... тех, кому удалось спастись от пожара. Сейчас они прячутся вдоль юго-восточной дороги... видимо, пытаются заманить нас в ловушку.$B$BОтправляйся на Заставу на опушке и разберись с ними. Судя по донесениям, их предводителя зовут Владек... сделай так, чтобы я больше ничего о нем не слышал.','Лейтенант Думонт отправил вас к Заставе на опушке убить Владека и 7 охотников Среброречья.','Как жаль, что звероловы оказались... немного не теми, кем мы их себе представляли. Нам бы не помешали хорошие бойцы.$B$BПокойтесь с миром, мерзавцы.','Готово, $N?','Вернитесь к лейтенанту Думонту в Приют Янтарной Сосны, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мгновенный ответ',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наша реакция должна быть незамедлительной. Сокрушительной. Мы должны проучить этих мерзавцев раз и навсегда.$B$BНаши разведчики засекли местонахождение выживших звероловов Среброречья... тех, кому удалось спастись от пожара. Сейчас они прячутся вдоль юго-восточной дороги... видимо, пытаются заманить нас в ловушку.$B$BОтправляйся на Заставу на опушке и разберись с ними. Судя по донесениям, их предводителя зовут Владек... сделай так, чтобы я больше ничего о нем не слышал.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Лейтенант Думонт отправил вас к Заставе на опушке убить Владека и 7 охотников Среброречья.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Как жаль, что звероловы оказались... немного не теми, кем мы их себе представляли. Нам бы не помешали хорошие бойцы.$B$BПокойтесь с миром, мерзавцы.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Готово, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лейтенанту Думонту в Приют Янтарной Сосны, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12311,'Подземная обитель некролорда','Упрятанные за холодные каменные стены этого склепа покоятся останки благородных и знаменитых личностей, нашедших свою смерть в Нордсколе. В самой глубине усыпальницы обитает некролорд, поднимающий тела умерших в качестве слуг Плети.$B$BТебе нужно прорваться вглубь склепа Стражей Зимы и убить некролорда Амариона. Только так можно остановить зло, идущее изнутри!$B$BИ еще, $n: внимательно осмотри помещение, где найдешь Амариона – там может храниться важная информация.','По заданию кавалериста Дюркона из крепости Стражей Зимы убейте некролорда Амариона.','Теперь если бы мы смогли остановить атаки армии Плети на крепость извне, то у нас появилась бы возможность послать помощь лорду Фордрагону к Вратам Гнева.','Амарион мертв?','Вернитесь к кавалеристу Дюркону в Склеп Стражей Зимы, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подземная обитель некролорда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Упрятанные за холодные каменные стены этого склепа покоятся останки благородных и знаменитых личностей, нашедших свою смерть в Нордсколе. В самой глубине усыпальницы обитает некролорд, поднимающий тела умерших в качестве слуг Плети.$B$BТебе нужно прорваться вглубь склепа Стражей Зимы и убить некролорда Амариона. Только так можно остановить зло, идущее изнутри!$B$BИ еще, $n: внимательно осмотри помещение, где найдешь Амариона – там может храниться важная информация.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По заданию кавалериста Дюркона из крепости Стражей Зимы убейте некролорда Амариона.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь если бы мы смогли остановить атаки армии Плети на крепость извне, то у нас появилась бы возможность послать помощь лорду Фордрагону к Вратам Гнева.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Амарион мертв?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к кавалеристу Дюркону в Склеп Стражей Зимы, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12312,'Тайны Плети','Вся эта обтянутая плотью книга испещрена коряво нацарапанными, будто вырезанными клинком, странными символами и изображениями. Вы и понятия не имеете, что здесь написано, но совершенно уверены, что это очень важно.$B$BОтнесите том кавалеристу Дюркону, стоящему на страже наверху склепа Стражей Зимы.','Отнесите сшитый плотью фолиант кавалеристу Дюркону, находящемуся в крепости Стражей Зимы на Драконьем Погосте.','Какая бы информация ни содержалась в этой книге, она, должно быть, очень важна! Когда ты выбегал из склепа, я слышал, как вслед тебе неслись вопли и завывания!$B$BНужно сообщить обо всем главнокомандующему!','Фолиант Плети?','Вернитесь к кавалеристу Дюркону в Склеп Стражей Зимы, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тайны Плети',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вся эта обтянутая плотью книга испещрена коряво нацарапанными, будто вырезанными клинком, странными символами и изображениями. Вы и понятия не имеете, что здесь написано, но совершенно уверены, что это очень важно.$B$BОтнесите том кавалеристу Дюркону, стоящему на страже наверху склепа Стражей Зимы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите сшитый плотью фолиант кавалеристу Дюркону, находящемуся в крепости Стражей Зимы на Драконьем Погосте.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Какая бы информация ни содержалась в этой книге, она, должно быть, очень важна! Когда ты выбегал из склепа, я слышал, как вслед тебе неслись вопли и завывания!$B$BНужно сообщить обо всем главнокомандующему!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Фолиант Плети?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к кавалеристу Дюркону в Склеп Стражей Зимы, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`) VALUES (12313,'Спасай Хмельной фестиваль! Поговори со шпионом Хмельного фестиваля в "Угрюмом обжоре", что в Глубинах Черной горы.','Поговорите со шпионом Хмельного фестиваля в "Угрюмом обжоре", что в Глубинах Черной горы.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Спасай Хмельной фестиваль! Поговори со шпионом Хмельного фестиваля в "Угрюмом обжоре", что в Глубинах Черной горы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите со шпионом Хмельного фестиваля в "Угрюмом обжоре", что в Глубинах Черной горы.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12314,'Покончить с капитаном Зорной!','Ты $Gубил:убила; капитана Зорну?','Вернитесь к барону Фриману в Бухту торговцев, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Покончить с капитаном Зорной!',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gубил:убила; капитана Зорну?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к барону Фриману в Бухту торговцев, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12315,'Покончить с капитаном Брайтвотером!','Наши солдаты постоянно сталкиваются с отрядами подкрепления Альянса. Такое ощущение, будто их предводитель предугадывает каждый наш шаг!$B$BНастало время покончить с капитаном Брайтвотером. Он командует войсками с борта флагмана Альянса, пришвартованного на дальнем конце бухты.$B$BПобедить его будет нелегко, $n. Возьми с собой несколько проверенных друзей – или хотя бы воспользуйся ключом от одного из отремонтированных крошшеров. Мне все равно, каким образом умрет Брайтвотер – но я больше не хочу слышать его имя в списках живых!','Ты $Gустранил:устранила; вражеского капитана?','Вернитесь к генералу Хазгару в Бухту торговцев, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Покончить с капитаном Брайтвотером!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наши солдаты постоянно сталкиваются с отрядами подкрепления Альянса. Такое ощущение, будто их предводитель предугадывает каждый наш шаг!$B$BНастало время покончить с капитаном Брайтвотером. Он командует войсками с борта флагмана Альянса, пришвартованного на дальнем конце бухты.$B$BПобедить его будет нелегко, $n. Возьми с собой несколько проверенных друзей – или хотя бы воспользуйся ключом от одного из отремонтированных крошшеров. Мне все равно, каким образом умрет Брайтвотер – но я больше не хочу слышать его имя в списках живых!',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gустранил:устранила; вражеского капитана?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к генералу Хазгару в Бухту торговцев, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12316,'Припрем их к стенке!','Есть что сообщить?','Вернитесь к лейтенанту Стюарту в Бухту торговцев, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Припрем их к стенке!',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Есть что сообщить?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лейтенанту Стюарту в Бухту торговцев, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12317,'Припрем их к стенке','Ты $Gвыполнил:выполнила; заказ?','Вернитесь к центуриону Каггруму в Бухту торговцев, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Припрем их к стенке',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gвыполнил:выполнила; заказ?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к центуриону Каггруму в Бухту торговцев, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (12318,'Спасем Хмельной фестиваль!','Поговорите со шпионом Хмельного фестиваля в трактире "Угрюмый обжора" в Глубинах Черной горы.','Ты из лагеря Хмельного фестиваля? Ну наконец-то! Хмельной фестиваль еще можно спасти.\n\n$n мы должны остановить Корена Худовара! Нельзя допустить, чтобы наш священный праздник был сорван. Мы должны совершить возлияния пивным богам!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спасем Хмельной фестиваль!',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите со шпионом Хмельного фестиваля в трактире "Угрюмый обжора" в Глубинах Черной горы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты из лагеря Хмельного фестиваля? Ну наконец-то! Хмельной фестиваль еще можно спасти.\n\n$n мы должны остановить Корена Худовара! Нельзя допустить, чтобы наш священный праздник был сорван. Мы должны совершить возлияния пивным богам!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12319,'Тайна книги','Что же это может быть, $n? Проклятый лич явно наложил на тебя не просто обычное проклятие!$b$b<Дюркон листает зловещие страницы.>$b$bЯ даже не знаю, правильно ли я держу эту книгу. Однако необходимо выяснить, какие важные сведения в ней содержатся!$b$b<Дюркон возвращает вам книгу.>$b$bГлавнокомандующий должен знать, что делать. Отнеси сшитый плотью фолиант к нему и расскажи ему о том, что произошло.','Отнесите сшитый плотью фолиант главнокомандующему Халфорду Змеевержцу в крепость Стражей Зимы в Драконьем Погосте.','Некролорда больше нет в живых?','Вернитесь к главнокомандующему Халфорду Змеевержцу в Крепость Стражей Зимы, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тайна книги',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что же это может быть, $n? Проклятый лич явно наложил на тебя не просто обычное проклятие!$b$b<Дюркон листает зловещие страницы.>$b$bЯ даже не знаю, правильно ли я держу эту книгу. Однако необходимо выяснить, какие важные сведения в ней содержатся!$b$b<Дюркон возвращает вам книгу.>$b$bГлавнокомандующий должен знать, что делать. Отнеси сшитый плотью фолиант к нему и расскажи ему о том, что произошло.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите сшитый плотью фолиант главнокомандующему Халфорду Змеевержцу в крепость Стражей Зимы в Драконьем Погосте.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Некролорда больше нет в живых?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к главнокомандующему Халфорду Змеевержцу в Крепость Стражей Зимы, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (12320,'Язык Смерти','Возьми эту книгу и иди по дороге, ведущей к казармам. Как войдешь в казармы, спустись по лестнице, ведущей в тюрьму. В тюрьме ты найдешь инквизитора Халларда и нашего мэра, Годфри. Полагаю, именно Годфри и окажется недостающей деталью головоломки, и именно Халлард – тот человек, который сумеет ее собрать.$b$bСтупай!','Отнесите сшитый плотью фолиант инквизитору Халларду в тюрьме крепости Стражей Зимы.','Быть может, Годфри и расскажет нам то, что ему известно об этой книге, если у него будут на то серьезные основания.$B$B<Халлард оборачивается к мэру Годфри.>$B$BНе правда ли, а, мэр?','Вернитесь к инквизитору Халларду в Крепость Стражей Зимы, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Язык Смерти',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Возьми эту книгу и иди по дороге, ведущей к казармам. Как войдешь в казармы, спустись по лестнице, ведущей в тюрьму. В тюрьме ты найдешь инквизитора Халларда и нашего мэра, Годфри. Полагаю, именно Годфри и окажется недостающей деталью головоломки, и именно Халлард – тот человек, который сумеет ее собрать.$b$bСтупай!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите сшитый плотью фолиант инквизитору Халларду в тюрьме крепости Стражей Зимы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Быть может, Годфри и расскажет нам то, что ему известно об этой книге, если у него будут на то серьезные основания.$B$B<Халлард оборачивается к мэру Годфри.>$B$BНе правда ли, а, мэр?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к инквизитору Халларду в Крепость Стражей Зимы, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (12321,'Праведная проповедь','Годфри Хорошер, некогда человек праведный и мэр Стражей Зимы, теперь принадлежит Плети. Его трансформация из человека в неумирающего вурдалака шла медленно и в течение длительного времени. Теперь он слышит зов Короля-лича и живет только для того, чтобы служить своему господину.$B$BНо, как и любой представитель Плети, Годфри знает язык смерти и, если его правильно мотивировать, расскажет об этом фолианте то, что нам нужно.$B$BКогда услышишь то, что надлежит услышать, возвращайся к главнокомандующему на линию фронта. А я здесь приберу, по необходимости.','Дождитесь, пока инквизитор Халлард закончит свою праведную проповедь, и возвращайтесь к главнокомандующему Халфорду Змеевержцу в крепость Стражей Зимы на Драконьем Погосте с добытой информацией.','Мы должны были знать об этой проклятой усыпальнице. Это же нелепо! Герцога Августа Крушителя Врагов и Амбо Кэша нужно послать на передовую, готовить наше следующее нападение.$B$BКогда шахты будут расчищены, я пошлю тебя к Крушителю Врагов, чтобы мы могли начать нападение на наксрамасские силы Плети!$B$BИнформация, которую тебе удалось собрать за это время, будет отправлена лорду Фордрагону к Вратам Гнева на крыльях нашего самого быстрого грифона!','Праведная проповедь прослушана','Вернитесь к главнокомандующему Халфорду Змеевержцу в Крепость Стражей Зимы, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Праведная проповедь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Годфри Хорошер, некогда человек праведный и мэр Стражей Зимы, теперь принадлежит Плети. Его трансформация из человека в неумирающего вурдалака шла медленно и в течение длительного времени. Теперь он слышит зов Короля-лича и живет только для того, чтобы служить своему господину.$B$BНо, как и любой представитель Плети, Годфри знает язык смерти и, если его правильно мотивировать, расскажет об этом фолианте то, что нам нужно.$B$BКогда услышишь то, что надлежит услышать, возвращайся к главнокомандующему на линию фронта. А я здесь приберу, по необходимости.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Дождитесь, пока инквизитор Халлард закончит свою праведную проповедь, и возвращайтесь к главнокомандующему Халфорду Змеевержцу в крепость Стражей Зимы на Драконьем Погосте с добытой информацией.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мы должны были знать об этой проклятой усыпальнице. Это же нелепо! Герцога Августа Крушителя Врагов и Амбо Кэша нужно послать на передовую, готовить наше следующее нападение.$B$BКогда шахты будут расчищены, я пошлю тебя к Крушителю Врагов, чтобы мы могли начать нападение на наксрамасские силы Плети!$B$BИнформация, которую тебе удалось собрать за это время, будет отправлена лорду Фордрагону к Вратам Гнева на крыльях нашего самого быстрого грифона!',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Праведная проповедь прослушана',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к главнокомандующему Халфорду Змеевержцу в Крепость Стражей Зимы, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12323,'Выкурить трусов','Прекрасно, солдат! Теперь наши люди могут сосредоточиться на войне с Ордой.','Ты уже $Gвыкурил:выкурила; последнего паразита Торговой компании?','Вернитесь к сержанту Дауни в Бухту торговцев, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Выкурить трусов',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно, солдат! Теперь наши люди могут сосредоточиться на войне с Ордой.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты уже $Gвыкурил:выкурила; последнего паразита Торговой компании?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к сержанту Дауни в Бухту торговцев, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12324,'Выкурить трусов','Генерал будет рад узнать, как ловко мы расправились с Торговой Компанией. Теперь нас ничто не будет отвлекать от войны с Альянсом.','Ты уже $Gвыкурил:выкурила; последнего паразита Торговой компании?','Вернитесь к каменному стражу Тотему Ярости в Бухту торговцев, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Выкурить трусов',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Генерал будет рад узнать, как ловко мы расправились с Торговой Компанией. Теперь нас ничто не будет отвлекать от войны с Альянсом.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты уже $Gвыкурил:выкурила; последнего паразита Торговой компании?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к каменному стражу Тотему Ярости в Бухту торговцев, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (12325,'Заброс на вражескую территорию','Поговорите с командиром грифонов Уриком, чтобы организовать полет на заставу Торсона на Драконьем Погосте. Когда прибудете на заставу, доложитесь герцогу Августу Крушителю Врагов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Заброс на вражескую территорию',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с командиром грифонов Уриком, чтобы организовать полет на заставу Торсона на Драконьем Погосте. Когда прибудете на заставу, доложитесь герцогу Августу Крушителю Врагов.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12326,'Паровой сюрприз','Кэш. Амбо Кэш. И все удовольствие твое.','Поговорите с Амбо Кэшем в Усыпальнице Стражей Зимы, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Паровой сюрприз',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Кэш. Амбо Кэш. И все удовольствие твое.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Амбо Кэшем в Усыпальнице Стражей Зимы, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`endtext_loc8`) VALUES (12327,'Внетелесные ощущения','А, ты ищешь знаний о прошлом. Это признак мудрости, |3-6($r).$B$BОбычно меня просят предсказать будущее, но дожившие до моих седин понимают, что мудрость прошлого гораздо более полезна, нежели туманные видения грядущего. $B$BВыпей это снадобье и загляни в мой хрустальный шар. Посмотрим, что откроется тебе в его глубинах.','Выпейте зелье из легчайшей пыльцы возле хрустального шара Рууны и узрите видение из прошлого.','Да, $N?','Видение из прошлого') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Внетелесные ощущения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А, ты ищешь знаний о прошлом. Это признак мудрости, |3-6($r).$B$BОбычно меня просят предсказать будущее, но дожившие до моих седин понимают, что мудрость прошлого гораздо более полезна, нежели туманные видения грядущего. $B$BВыпей это снадобье и загляни в мой хрустальный шар. Посмотрим, что откроется тебе в его глубинах.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выпейте зелье из легчайшей пыльцы возле хрустального шара Рууны и узрите видение из прошлого.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да, $N?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Видение из прошлого',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (12328,'Просьба Рууны','Я не возьму с тебя деньги за мои услуги, ибо чувствую, что ты действуешь во имя общего блага, и многое будет зависеть от того, что ты сегодня узнаешь.$B$BНо я попрошу тебя принести один важный компонент для зелья – легчайшую пыльцу папоротниковых мотыльков, которые водятся на северо-востоке отсюда. Принеси пыльцу, и я помогу тебе перенестись в то время и место, где произошли интересующие тебя события.','Рууна Слепая просит вас принести ей четыре горсти легчайшей пыльцы.','Отлично! Это то, что надо.$B$BТеперь осталось только закончить приготовление зелья.','Вернитесь к Рууне Слепой в Лагерь Рууны, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Просьба Рууны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я не возьму с тебя деньги за мои услуги, ибо чувствую, что ты действуешь во имя общего блага, и многое будет зависеть от того, что ты сегодня узнаешь.$B$BНо я попрошу тебя принести один важный компонент для зелья – легчайшую пыльцу папоротниковых мотыльков, которые водятся на северо-востоке отсюда. Принеси пыльцу, и я помогу тебе перенестись в то время и место, где произошли интересующие тебя события.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Рууна Слепая просит вас принести ей четыре горсти легчайшей пыльцы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! Это то, что надо.$B$BТеперь осталось только закончить приготовление зелья.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Рууне Слепой в Лагерь Рууны, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (12329,'Судьба и совпадения','Поговорите с Сашей в Торговой лавке Белой Сосны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Судьба и совпадения',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Сашей в Торговой лавке Белой Сосны.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`) VALUES (12330,'Слабое место Анатолия','Моя сестра где-то неподалеку, а этот мерзавец не хочет признаваться, где они ее прячут.$B$BКажется, собственная судьба ему безразлична, но у меня есть кое-какие планы. Когда-то я была знакома с женой Анатолия, Татьяной – она работала на конюшне.$B$BВозьми этот дротик с транквилизатором, оглуши женщину и притащи сюда. Только не убивай ее – она нам понадобится, чтобы разговорить Анатолия.$B$BОбещаю, как только мы найдем мою сестру, я помогу тебе расправиться с человеком, который стоит за всем этим.','Мы... едва не опоздали.$B$BНадо спасти Аню. Вперед!','Рада видеть тебя $Gцелым:целой;.','Татьяна доставлена на место') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Слабое место Анатолия',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Моя сестра где-то неподалеку, а этот мерзавец не хочет признаваться, где они ее прячут.$B$BКажется, собственная судьба ему безразлична, но у меня есть кое-какие планы. Когда-то я была знакома с женой Анатолия, Татьяной – она работала на конюшне.$B$BВозьми этот дротик с транквилизатором, оглуши женщину и притащи сюда. Только не убивай ее – она нам понадобится, чтобы разговорить Анатолия.$B$BОбещаю, как только мы найдем мою сестру, я помогу тебе расправиться с человеком, который стоит за всем этим.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мы... едва не опоздали.$B$BНадо спасти Аню. Вперед!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Рада видеть тебя $Gцелым:целой;.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Татьяна доставлена на место',`endtext_loc8`);
