INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12372,'Оборона Храма Драконьего Покоя','Воодушевленные избытком магической энергии, текущей сейчас через Лазуритовое святилище драконов, синие драконы осмелились напасть на сам храм Драконьего Покоя!$B$BЯ хочу, чтобы ты $gполетел:полетела; на одном из наших защитников в самую гущу битвы, убивая их драконов, больших и малых, и атакуя выбросы энергий силовых линий в самом святилище с целью его дестабилизации.$B$BЗащитники Драконьего Покоя находятся снаружи, на восточной и западной террасах. Поговори с кем-нибудь из них, чтобы полететь на битву.$B$BБез твоей помощи, $n, нас ждет поражение.','Невероятно! Позволь мне сказать, что я не устаю поражаться, на что способны вы, представители молодых рас.$B$BМы в долгу перед тобой. Вернешься ли ты завтра, чтобы продолжить помогать нам?','Как продвигается бой? Мы их отталкиваем?','Вернитесь к лорду Афрасастразу в Храм Драконьего Покоя, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оборона Храма Драконьего Покоя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Воодушевленные избытком магической энергии, текущей сейчас через Лазуритовое святилище драконов, синие драконы осмелились напасть на сам храм Драконьего Покоя!$B$BЯ хочу, чтобы ты $gполетел:полетела; на одном из наших защитников в самую гущу битвы, убивая их драконов, больших и малых, и атакуя выбросы энергий силовых линий в самом святилище с целью его дестабилизации.$B$BЗащитники Драконьего Покоя находятся снаружи, на восточной и западной террасах. Поговори с кем-нибудь из них, чтобы полететь на битву.$B$BБез твоей помощи, $n, нас ждет поражение.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Невероятно! Позволь мне сказать, что я не устаю поражаться, на что способны вы, представители молодых рас.$B$BМы в долгу перед тобой. Вернешься ли ты завтра, чтобы продолжить помогать нам?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как продвигается бой? Мы их отталкиваем?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лорду Афрасастразу в Храм Драконьего Покоя, что в Драконьем Погосте.',`completedtext_loc8`);
