INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (12411,'Спасение сестры','Прошу тебя, $n! Я знаю, что ты собираешься убить Аругала. Клянусь могилой своего отца, я помогу тебе осуществить задуманное.$B$BНо... Я не могу бросить Аню среди этих дикарей. Она еще так молода и невинна!$B$BПомоги мне спасти сестру, и я буду сражаться с тобой бок о бок против Аругала.$B$BЯ знаю, где находится логово, о котором говорил Анатолий. Оно с другой стороны холма. Надо действовать без промедления, мы должны освободить мою сестру.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спасение сестры',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прошу тебя, $n! Я знаю, что ты собираешься убить Аругала. Клянусь могилой своего отца, я помогу тебе осуществить задуманное.$B$BНо... Я не могу бросить Аню среди этих дикарей. Она еще так молода и невинна!$B$BПомоги мне спасти сестру, и я буду сражаться с тобой бок о бок против Аругала.$B$BЯ знаю, где находится логово, о котором говорил Анатолий. Оно с другой стороны холма. Надо действовать без промедления, мы должны освободить мою сестру.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12412,'Друг моего врага','Я хочу, чтобы ты $gвдолбил:вдолбила; в свою пустую голову хотя бы одну истину: Альянс никогда не закрепится в Седых холмах.$B$BЗдесь слишком много источников руды, дерева и прочих полезных ресурсов – и потому мы не можем сдать им ни одного стратегического рубежа.$B$BДо сих пор удача была на нашей стороне... но вскоре ход битвы может измениться в пользу нашего врага.$B$BМы узнали, что к силам Альянса могут присоединиться местные зверобои. Убей их прежде, чем они заключат союз с нашим врагом.','Ты $Gвыполнил:выполнила; свою задачу? Если нет, то что ты тут делаешь?','Вернитесь к завоевательнице Кренне в Крепость Завоевателей, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Друг моего врага',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я хочу, чтобы ты $gвдолбил:вдолбила; в свою пустую голову хотя бы одну истину: Альянс никогда не закрепится в Седых холмах.$B$BЗдесь слишком много источников руды, дерева и прочих полезных ресурсов – и потому мы не можем сдать им ни одного стратегического рубежа.$B$BДо сих пор удача была на нашей стороне... но вскоре ход битвы может измениться в пользу нашего врага.$B$BМы узнали, что к силам Альянса могут присоединиться местные зверобои. Убей их прежде, чем они заключат союз с нашим врагом.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gвыполнил:выполнила; свою задачу? Если нет, то что ты тут делаешь?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к завоевательнице Кренне в Крепость Завоевателей, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12413,'Нападение на Среброречье','Несколько часов назад эти звероловы были всего лишь простыми крестьянами, способными разве что пополнить ряды Альянса.$B$BТеперь же они превратились в нечто... иное. А мне не нравится то, что я не могу объяснить. Отправляйся на север Седых холмов, найди их столицу, Среброречье, и помоги моим людям стереть этих бродяг с лица земли.','Удалось ли тебе выполнить задачу, $N?','Вернитесь к завоевательнице Кренне в Крепость Завоевателей, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нападение на Среброречье',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Несколько часов назад эти звероловы были всего лишь простыми крестьянами, способными разве что пополнить ряды Альянса.$B$BТеперь же они превратились в нечто... иное. А мне не нравится то, что я не могу объяснить. Отправляйся на север Седых холмов, найди их столицу, Среброречье, и помоги моим людям стереть этих бродяг с лица земли.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось ли тебе выполнить задачу, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к завоевательнице Кренне в Крепость Завоевателей, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12414,'Лошадки для лагеря','Ух ты! Какие выносливые лошадки! Да, капитан будет очень доволен нашими успехами.','У тебя есть все необходимые нам мустанги?','Вернитесь к оруженосцу Перси в Лагерь дружины Западного Края, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лошадки для лагеря',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ух ты! Какие выносливые лошадки! Да, капитан будет очень доволен нашими успехами.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У тебя есть все необходимые нам мустанги?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к оруженосцу Перси в Лагерь дружины Западного Края, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12415,'Пугалка для коней','Обратите в бегство 15 мустангов нагорья и вернитесь к Соулоку Штормовой Ярости в Лагерь Уанква.','Ты... ты принес чертежи?','Вернитесь к Соулоку Штормовой Ярости в Лагерь Уанква, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пугалка для коней',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обратите в бегство 15 мустангов нагорья и вернитесь к Соулоку Штормовой Ярости в Лагерь Уанква.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты... ты принес чертежи?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Соулоку Штормовой Ярости в Лагерь Уанква, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12416,'Горячая битва','Армия Плети заполонила святилище. Его хранительница, Далия Благословение Солнца, пропала. Красные змеи, павшие при защите святилища, теперь окружают нас, приняв форму жутких скелетов тлеющих змеев. Опасная ситуация, |3-6($r).$B$BГруппу тебе подобных, пытающуюся поуменьшить поток воинов Плети из святилища, возглавляет капитан Искандар.$B$BПриди к нему на помощь... но, пожалуйста, оставайся позади его бойцов. Поток воинов Плети бесконечен, а мне вовсе не хочется потерять тебя в одном из этих ущелий.','Помогите капитану Искандару удержать каньоны, приняв участие в смерти 12 хладных атакующих вурдалаков, 8 хладных атакующих упырей и 1 хладного атакующего поганища.$B$BКогда это будет выполнено, возвращайтесь к Церистразу.','Неприятная работа, я знаю – и от всего сердца благодарю тебя за ее выполнение.$B$BПлети нельзя позволить продвинуться ни на йоту ближе к Драконьему Покою, иначе мы неизбежно его потеряем.','Я рад, что ты все еще с нами, $R.','Вернитесь к Церистразу в Драконьи пустоши, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Горячая битва',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Армия Плети заполонила святилище. Его хранительница, Далия Благословение Солнца, пропала. Красные змеи, павшие при защите святилища, теперь окружают нас, приняв форму жутких скелетов тлеющих змеев. Опасная ситуация, |3-6($r).$B$BГруппу тебе подобных, пытающуюся поуменьшить поток воинов Плети из святилища, возглавляет капитан Искандар.$B$BПриди к нему на помощь... но, пожалуйста, оставайся позади его бойцов. Поток воинов Плети бесконечен, а мне вовсе не хочется потерять тебя в одном из этих ущелий.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Помогите капитану Искандару удержать каньоны, приняв участие в смерти 12 хладных атакующих вурдалаков, 8 хладных атакующих упырей и 1 хладного атакующего поганища.$B$BКогда это будет выполнено, возвращайтесь к Церистразу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Неприятная работа, я знаю – и от всего сердца благодарю тебя за ее выполнение.$B$BПлети нельзя позволить продвинуться ни на йоту ближе к Драконьему Покою, иначе мы неизбежно его потеряем.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я рад, что ты все еще с нами, $R.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Церистразу в Драконьи пустоши, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12417,'Погребение','Есть еще одно дело, требующее внимания. Мои собратья гибнут в битве, и если мы не поторопимся, они лишь пополнят ряды тлеющих змеев.$B$BОтправляйся в святилище через один из проходов к югу или к северу... Там, должно быть, плотность сил Плети не так велика.$B$BПоищи в святилище рубиновые желуди, упавшие с дерева, и посади их рядом с телами моих павших соплеменников. Они положат начало новой жизни... а это – честь для любого из нас.','Отправляйтесь в Рубиновое святилище драконов через любой из южных или северных проходов и поищите рубиновые желуди. С помощью рубиновых желудей предайте тела павших красных драконов земле. По выполнении задания вернитесь к Церистразу.','Я начал беспокоиться, что Плеть в святилище забрала тебя. Хорошо, что ты еще $Gжив:жива;.','Вернитесь к Церистразу в Драконьи пустоши, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Погребение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Есть еще одно дело, требующее внимания. Мои собратья гибнут в битве, и если мы не поторопимся, они лишь пополнят ряды тлеющих змеев.$B$BОтправляйся в святилище через один из проходов к югу или к северу... Там, должно быть, плотность сил Плети не так велика.$B$BПоищи в святилище рубиновые желуди, упавшие с дерева, и посади их рядом с телами моих павших соплеменников. Они положат начало новой жизни... а это – честь для любого из нас.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Рубиновое святилище драконов через любой из южных или северных проходов и поищите рубиновые желуди. С помощью рубиновых желудей предайте тела павших красных драконов земле. По выполнении задания вернитесь к Церистразу.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я начал беспокоиться, что Плеть в святилище забрала тебя. Хорошо, что ты еще $Gжив:жива;.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Церистразу в Драконьи пустоши, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12418,'Через огненные поля','У меня есть для тебя последнее задание, |3-6($r)... дело, которое должно повернуть ход сражения в нашу пользу.$B$BВозвращайся в святилище и убей некромантов, раздувающих горнило этой бойни. Когда они будут мертвы, нам, должно быть, удастся отбросить их силы и в результате отвоевать святилище.$B$BМне также нужно, чтобы ты $gотыскал:отыскала; источник осквернения под святилищем и $gуничтожил:уничтожила; его.$B$BЯ знаю, что уже и так потребовал от тебя слишком многого, но если ты выполнишь и эту мою просьбу, мы одержим победу в этой битве.','Отправляйтесь в Рубиновое святилище драконов через любой из северных или южных проходов, затем убейте 6 хладных некромантов и уничтожьте источник осквернения, находящийся под святилищем. По выполнении задания вернитесь к Церистразу.','Ты вернулись! Ты делаешь то, что я просил?','Вернитесь к Церистразу в Драконьи пустоши, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Через огненные поля',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У меня есть для тебя последнее задание, |3-6($r)... дело, которое должно повернуть ход сражения в нашу пользу.$B$BВозвращайся в святилище и убей некромантов, раздувающих горнило этой бойни. Когда они будут мертвы, нам, должно быть, удастся отбросить их силы и в результате отвоевать святилище.$B$BМне также нужно, чтобы ты $gотыскал:отыскала; источник осквернения под святилищем и $gуничтожил:уничтожила; его.$B$BЯ знаю, что уже и так потребовал от тебя слишком многого, но если ты выполнишь и эту мою просьбу, мы одержим победу в этой битве.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Рубиновое святилище драконов через любой из северных или южных проходов, затем убейте 6 хладных некромантов и уничтожьте источник осквернения, находящийся под святилищем. По выполнении задания вернитесь к Церистразу.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты вернулись! Ты делаешь то, что я просил?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Церистразу в Драконьи пустоши, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (12419,'Судьба Рубинового святилища драконов','Вы берете в руки брошь и замечаете, что ее слабое сияние становится чуть ярче.$B$BКрас, конечно, захочет узнать о судьбе Далии. Отнесите брошь ему в Драконий Покой.','Принесите рубиновую брошь Далии Благословения Солнца Красу в чертог правящего Совета в Драконий Покой и расскажите ему о судьбе Далии.','Далию захватила Плеть? Печальный день для всех нас...$B$BЯ займусь поисками нового хранителя, когда святилище вновь станет нашим. Спасибо тебе за труды... Рубиновое святилище – священное для нас место, и твои свершения не будут забыты.$B$BПриятно знать, что есть еще такие герои, как ты, я призову тебя в один прекрасный день. А пока он не наступил – пусть странствия укрепляют твою душу и тело.','Вернитесь к Красу в Храм Драконьего Покоя, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Судьба Рубинового святилища драконов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы берете в руки брошь и замечаете, что ее слабое сияние становится чуть ярче.$B$BКрас, конечно, захочет узнать о судьбе Далии. Отнесите брошь ему в Драконий Покой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите рубиновую брошь Далии Благословения Солнца Красу в чертог правящего Совета в Драконий Покой и расскажите ему о судьбе Далии.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Далию захватила Плеть? Печальный день для всех нас...$B$BЯ займусь поисками нового хранителя, когда святилище вновь станет нашим. Спасибо тебе за труды... Рубиновое святилище – священное для нас место, и твои свершения не будут забыты.$B$BПриятно знать, что есть еще такие герои, как ты, я призову тебя в один прекрасный день. А пока он не наступил – пусть странствия укрепляют твою душу и тело.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Красу в Храм Драконьего Покоя, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12420,'Клуб "Пиво месяца"','Думаю, тебе понравится быть членом нашего клуба "Лучший пивовар месяца". Ведь это означает, что у тебя всегда будет самое лучшее и свежее пиво.$b$bЗаполни членскую карточку "Лучшего пивовара месяца" и отнеси ее Ларкину Громовару в таверну "Горючий камень" в Стальгорне.','Отнесите членскую карточку "Лучшего пивовара месяца" Ларкину Громовару в таверну "Горючий камень" в Стальгорне.','Ты $gзаполнил:заполнила; членскую карточку?','Вернитесь к Ларкину Громовару в Дун Морог.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Клуб "Пиво месяца"',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Думаю, тебе понравится быть членом нашего клуба "Лучший пивовар месяца". Ведь это означает, что у тебя всегда будет самое лучшее и свежее пиво.$b$bЗаполни членскую карточку "Лучшего пивовара месяца" и отнеси ее Ларкину Громовару в таверну "Горючий камень" в Стальгорне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите членскую карточку "Лучшего пивовара месяца" Ларкину Громовару в таверну "Горючий камень" в Стальгорне.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $gзаполнил:заполнила; членскую карточку?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ларкину Громовару в Дун Морог.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12421,'Клуб "Пиво месяца"','Чем нас больше – тем лучше, $n. Вступив в клуб "Пиво месяца", ты сможешь дегустировать самые выдающиеся сорта пива.$b$bЗаполни членскую карточку клуба "Пиво месяца" и отнеси ее Рай\'ме в Оргриммар.','Отнесите заполненную членскую карточку клуба "Пиво месяца" Рай\'ме в Оргриммар.','А, хочешь к нам присоединиться? Тебе у нас понравится, $N. Члены нашего клуба получают все самое лучшее.$B$BВ начале каждого месяца мы будем посылать тебе образцы пива. Если оно тебе понравится – приходи сюда, и мы нальем тебе еще!','Ты $Gзаполнил:заполнила; членскую карточку?','Вернитесь к Рай\'ме в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Клуб "Пиво месяца"',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чем нас больше – тем лучше, $n. Вступив в клуб "Пиво месяца", ты сможешь дегустировать самые выдающиеся сорта пива.$b$bЗаполни членскую карточку клуба "Пиво месяца" и отнеси ее Рай\'ме в Оргриммар.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите заполненную членскую карточку клуба "Пиво месяца" Рай\'ме в Оргриммар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, хочешь к нам присоединиться? Тебе у нас понравится, $N. Члены нашего клуба получают все самое лучшее.$B$BВ начале каждого месяца мы будем посылать тебе образцы пива. Если оно тебе понравится – приходи сюда, и мы нальем тебе еще!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gзаполнил:заполнила; членскую карточку?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Рай\'ме в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (12422,'Расчетливая доброта','Слушай внимательно, $n. Ты $gдолжен:должна; действовать быстро и решительно.$B$BОдин из сержантов Кренны захватил зверолова-изгнанника из Среброречья. Обычно они казнят пленников до заката солнца.$B$BМы не можем это допустить! Видишь ли, эта пленница похожа по описанию на старшую дочь Михаила, знакомую тебе по этому дневнику. $B$BЕсли мы отпустим ее и проследим, куда она пойдет, то сможем обнаружить местонахождение главаря звероловов. Вот, отнеси ей эту бумагу.','Отнесите приказ о помиловании пленному зверолову в Холмы Среброречья.','Вы меня отпускаете? Правда? Слушай, я не хочу неприятностей... эти чудовища убили моего отца и похитили сестру. Честно говоря, у меня сейчас совсем другие заботы.','Вернитесь к пленному зверолову на Холмы Среброречья, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Расчетливая доброта',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слушай внимательно, $n. Ты $gдолжен:должна; действовать быстро и решительно.$B$BОдин из сержантов Кренны захватил зверолова-изгнанника из Среброречья. Обычно они казнят пленников до заката солнца.$B$BМы не можем это допустить! Видишь ли, эта пленница похожа по описанию на старшую дочь Михаила, знакомую тебе по этому дневнику. $B$BЕсли мы отпустим ее и проследим, куда она пойдет, то сможем обнаружить местонахождение главаря звероловов. Вот, отнеси ей эту бумагу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите приказ о помиловании пленному зверолову в Холмы Среброречья.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы меня отпускаете? Правда? Слушай, я не хочу неприятностей... эти чудовища убили моего отца и похитили сестру. Честно говоря, у меня сейчас совсем другие заботы.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к пленному зверолову на Холмы Среброречья, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12423,'Дневник Михаила','Насколько вы можете понять, этот дневник некогда вел житель Среброречья по имени Михаил.$B$BОн написан на неизвестном вам диалекте всеобщего человеческого языка. Вы думаете, что эти записи могут заинтересовать Завоевательницу Кренну.','Что это у тебя в руках?','Вернитесь к завоевательнице Кренне в Крепость Завоевателей, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дневник Михаила',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Насколько вы можете понять, этот дневник некогда вел житель Среброречья по имени Михаил.$B$BОн написан на неизвестном вам диалекте всеобщего человеческого языка. Вы думаете, что эти записи могут заинтересовать Завоевательницу Кренну.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что это у тебя в руках?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к завоевательнице Кренне в Крепость Завоевателей, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12424,'Горгонна','Эта книга написана на собачьем языке мерзких людишек. Ее надо сжечь, и немедленно.$B$BОтдай ее Горгонне и не трать больше мое драгоценное время на всякие гадости.','Ты хочешь мне что-то показать?','Поговорите с Горгонной в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Горгонна',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эта книга написана на собачьем языке мерзких людишек. Ее надо сжечь, и немедленно.$B$BОтдай ее Горгонне и не трать больше мое драгоценное время на всякие гадости.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты хочешь мне что-то показать?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Горгонной в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (12425,'Рууна Слепая','Не нравится мне эта ситуация со звероловами.$B$BЕсли они не на стороне Альянса – значит, возможно, они помогают Плети. А это не приведет ни к чему хорошему.$B$BНо наши предыдущие усилия увенчались успехом. Мы засекли, как наша бывшая пленница встречалась с некой предсказательницей.$B$BК сожалению, потом мы потеряли след беглянки, но я уверена, что она могла бы привести нас к их предводителю. Найди Рууну Слепую и вытяни из нее все, что сможешь.','Поговорите с Рууной Слепой из Лагеря Рууны, что находится рядом с Перевалом Фордрассил.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рууна Слепая',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не нравится мне эта ситуация со звероловами.$B$BЕсли они не на стороне Альянса – значит, возможно, они помогают Плети. А это не приведет ни к чему хорошему.$B$BНо наши предыдущие усилия увенчались успехом. Мы засекли, как наша бывшая пленница встречалась с некой предсказательницей.$B$BК сожалению, потом мы потеряли след беглянки, но я уверена, что она могла бы привести нас к их предводителю. Найди Рууну Слепую и вытяни из нее все, что сможешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Рууной Слепой из Лагеря Рууны, что находится рядом с Перевалом Фордрассил.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (12426,'ИСКЛЮЧЕНО') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','ИСКЛЮЧЕНО',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`endtext_loc8`) VALUES (12427,'Бойцовская яма: медвежьи бои!','Ах, так ты тоже хочешь помахать кулаками? Честно говоря, Кренна запретила своим профессиональным гладиаторам участвовать в боях на арене. Но ты, $gдружок:подруга; – птица вольная, и потому чисто теоретически под этот запрет не попадаешь.$B$BЗдорово я придумал, верно?$B$BВ общем, если ты $gнастроен:настроена; решительно, можешь начать с какого-нибудь слабенького противника. Попробуй для начала одолеть медведя! Я, пожалуй, даже разрешу тебе привести с собой парочку друзей на подмогу.','Одержите победу над Железной Шкурой в Бойцовской яме и вернитесь к букмекеру Вел\'джену за наградой.','Это не конец, друг!','Железная Шкура побежден') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бойцовская яма: медвежьи бои!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ах, так ты тоже хочешь помахать кулаками? Честно говоря, Кренна запретила своим профессиональным гладиаторам участвовать в боях на арене. Но ты, $gдружок:подруга; – птица вольная, и потому чисто теоретически под этот запрет не попадаешь.$B$BЗдорово я придумал, верно?$B$BВ общем, если ты $gнастроен:настроена; решительно, можешь начать с какого-нибудь слабенького противника. Попробуй для начала одолеть медведя! Я, пожалуй, даже разрешу тебе привести с собой парочку друзей на подмогу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Одержите победу над Железной Шкурой в Бойцовской яме и вернитесь к букмекеру Вел\'джену за наградой.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Это не конец, друг!',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Железная Шкура побежден',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`) VALUES (12428,'Бойцовская яма: битва с бешеным фурболгом','Молодец, неплохо сражаешься!$B$BА убить фурболга тебе по зубам? Как насчет того, чтобы сразиться с одним из громадных бешеных фурболгов Нордскола?$B$BПрекрасно, прекрасно. Собирай свою команду и отправляйся на арену. Давай устроим для них настоящее шоу... Может быть, нам даже удастся немного заработать на этом представлении!','Одержите победу над Торггом Громовым Тотемом в Бойцовской яме, после чего поговорите с букмекером Вел\'дженом.','Какой тонкий расчет, дружище! Учитывая, сколько ставок было сделано против тебя, мы можем праздновать победу!','Торгг Громовой Тотем побежден') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бойцовская яма: битва с бешеным фурболгом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Молодец, неплохо сражаешься!$B$BА убить фурболга тебе по зубам? Как насчет того, чтобы сразиться с одним из громадных бешеных фурболгов Нордскола?$B$BПрекрасно, прекрасно. Собирай свою команду и отправляйся на арену. Давай устроим для них настоящее шоу... Может быть, нам даже удастся немного заработать на этом представлении!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Одержите победу над Торггом Громовым Тотемом в Бойцовской яме, после чего поговорите с букмекером Вел\'дженом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Какой тонкий расчет, дружище! Учитывая, сколько ставок было сделано против тебя, мы можем праздновать победу!',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Торгг Громовой Тотем побежден',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`) VALUES (12429,'Бойцовская яма: кровь и железо','Наконец-то у нас $gпоявился настоящий боец:появилась настоящая воительница;! Зрителям уже порядком надоело смотреть на вялых пленников и голодных зверей.$B$BЛадно, ближе к делу. Твой следующий противник – настоящий железный голем из глубин Тор Модана... Как ты думаешь, тебе по плечу с ним справиться?','Одержите победу над Кроворжавом в Бойцовской яме и вернитесь к букмекеру Вел\'джену за наградой.','Эта металлическая бочка едва тебя не задавила! Честное слово, у меня чуть сердце из груди не выскочило!','Кроворжав побежден') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бойцовская яма: кровь и железо',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наконец-то у нас $gпоявился настоящий боец:появилась настоящая воительница;! Зрителям уже порядком надоело смотреть на вялых пленников и голодных зверей.$B$BЛадно, ближе к делу. Твой следующий противник – настоящий железный голем из глубин Тор Модана... Как ты думаешь, тебе по плечу с ним справиться?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Одержите победу над Кроворжавом в Бойцовской яме и вернитесь к букмекеру Вел\'джену за наградой.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Эта металлическая бочка едва тебя не задавила! Честное слово, у меня чуть сердце из груди не выскочило!',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Кроворжав побежден',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`) VALUES (12430,'Бойцовская яма: смерть близка','Скажу тебе напрямик, детка: твой следующий соперник – убийца.$B$BВ прямом смысле этого слова.$B$BНа прошлой неделе его должны были казнить, но он задушил палача одной левой рукой. После этого солдаты Кренны разрешили мне забрать его на арену.$B$BТак что если ты откажешься от боя – не стану тебя упрекать.','Одержите победу над Хоргренном Страшным Расколом в Бойцовской яме и вернитесь к букмекеру Вел\'джену за наградой.','Хоргренн Страшный Раскол побежден') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бойцовская яма: смерть близка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Скажу тебе напрямик, детка: твой следующий соперник – убийца.$B$BВ прямом смысле этого слова.$B$BНа прошлой неделе его должны были казнить, но он задушил палача одной левой рукой. После этого солдаты Кренны разрешили мне забрать его на арену.$B$BТак что если ты откажешься от боя – не стану тебя упрекать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Одержите победу над Хоргренном Страшным Расколом в Бойцовской яме и вернитесь к букмекеру Вел\'джену за наградой.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Хоргренн Страшный Раскол побежден',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (12431,'Бойцовская яма: последняя битва','Похоже, ты действительно $gразозлил:разозлила; Кренну. Она заключила пари с Горгонной, и теперь вызывает тебя на ринг. $B$BХодят слухи, что это будет смертельная битва! Что ж, тем хуже для тебя, и тем лучше для нашего бизнеса. $B$BВ общем, от судьбы не убежишь... так что не медли. Отправляйся на ринг и покончи с ней.','Одержите победу над Кренной в Бойцовской яме.','Кренна побеждена','Поговорите с Горгонной в Бойцовской яме, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бойцовская яма: последняя битва',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Похоже, ты действительно $gразозлил:разозлила; Кренну. Она заключила пари с Горгонной, и теперь вызывает тебя на ринг. $B$BХодят слухи, что это будет смертельная битва! Что ж, тем хуже для тебя, и тем лучше для нашего бизнеса. $B$BВ общем, от судьбы не убежишь... так что не медли. Отправляйся на ринг и покончи с ней.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Одержите победу над Кренной в Бойцовской яме.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Кренна побеждена',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Горгонной в Бойцовской яме, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12432,'Верхом на красной ракете','Эй, ты, |3-6($r)! Тащи сюда свою ленивую задницу!$b$bАльянс приготовил груз пиломатериалов для отправки. Он сейчас хранится на их корабле к северо-востоку отсюда. Поскольку мы не можем украсть эти дровишки, нам остается только одно – сжечь все их припасы!$b$bУ гоблина на пристани есть отличные торпеды, а топливо для них хранится на гоблинском корабле, пришвартованном к северу отсюда.$b$bЗалей чуток топлива в торпеду и направь ее прямо к грузовому кораблю.$b$b$gСвободен:Свободна;!','Ха-ха! Хорошо прокатился |3-6($R)?$B$BЕсли уж мы не сможем наложить лапу на дровишки – то они не достанутся никому!$B$BИ когда уже эти жалкиe псы Альянса осознают свое ничтожество перед могущественной Ордой?','Были ли сожжены пиломатериалы Альянса, $C?','Вернитесь к генералу Горлоку в Бухту торговцев, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Верхом на красной ракете',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эй, ты, |3-6($r)! Тащи сюда свою ленивую задницу!$b$bАльянс приготовил груз пиломатериалов для отправки. Он сейчас хранится на их корабле к северо-востоку отсюда. Поскольку мы не можем украсть эти дровишки, нам остается только одно – сжечь все их припасы!$b$bУ гоблина на пристани есть отличные торпеды, а топливо для них хранится на гоблинском корабле, пришвартованном к северу отсюда.$b$bЗалей чуток топлива в торпеду и направь ее прямо к грузовому кораблю.$b$b$gСвободен:Свободна;!',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ха-ха! Хорошо прокатился |3-6($R)?$B$BЕсли уж мы не сможем наложить лапу на дровишки – то они не достанутся никому!$B$BИ когда уже эти жалкиe псы Альянса осознают свое ничтожество перед могущественной Ордой?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Были ли сожжены пиломатериалы Альянса, $C?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к генералу Горлоку в Бухту торговцев, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (12433,'В поисках растворителя','О, да! То, что надо! Эта штука поможет мне сэкономить усилия. \n\nВот, подруга, возьми пару звонких монет за труды. Кстати, если тебе попадется в руки еще одна канистра с топливом – кати ее сюда!','Вернитесь к Гуртору в Бухту торговцев, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В поисках растворителя',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, да! То, что надо! Эта штука поможет мне сэкономить усилия. \n\nВот, подруга, возьми пару звонких монет за труды. Кстати, если тебе попадется в руки еще одна канистра с топливом – кати ее сюда!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гуртору в Бухту торговцев, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (12434,'Растворитель всегда пригодится!','Вернитесь к Гуртору в Седые холмы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Растворитель всегда пригодится!',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гуртору в Седые холмы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (12436,'Прибавка к зарплате','Вернитесь к поставщику Лоркрану в Крепость Завоевателей, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прибавка к зарплате',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к поставщику Лоркрану в Крепость Завоевателей, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12437,'Верхом на красной ракете','Слушай, $n: исход этой битвы зависит как от численного, так и от тактического превосходства над противником. $b$bЯ хочу поручить тебе задание, которое может изменить ход событий в пользу Альянса. У нас появилась возможность нанести сокрушительный удар, но удобный момент не будет длиться вечно. $b$bВ конце этого причала есть торпеды, с помощью которых мы могли бы потопить грузовой корабль Орды, стоящий на якоре к северо-западу отсюда.$b$bДобудь немного топлива с гоблинского корабля, который пришвартован на севере, и направь одну из торпед прямо на их грузовоз!','Надеюсь, грузовой корабль Орды уже охвачен пламенем, $N?','Вернитесь к командиру Хоузеру в Бухту торговцев, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Верхом на красной ракете',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слушай, $n: исход этой битвы зависит как от численного, так и от тактического превосходства над противником. $b$bЯ хочу поручить тебе задание, которое может изменить ход событий в пользу Альянса. У нас появилась возможность нанести сокрушительный удар, но удобный момент не будет длиться вечно. $b$bВ конце этого причала есть торпеды, с помощью которых мы могли бы потопить грузовой корабль Орды, стоящий на якоре к северо-западу отсюда.$b$bДобудь немного топлива с гоблинского корабля, который пришвартован на севере, и направь одну из торпед прямо на их грузовоз!',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Надеюсь, грузовой корабль Орды уже охвачен пламенем, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру Хоузеру в Бухту торговцев, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (12439,'Проблемы на западе','Появилась новая сила, угрожающая разрушить все, над чем мы трудились, $n. Тебе придется отправиться на запад, в Покой Звезд. Верховный маг Модера чувствует сильное возмущение силовых линий нашего мира, которое следует немедленно ликвидировать!$b$bОтправляйся прямо сейчас, $n! Поговори с Родни Веллсом на грифоньей площадке и объясни ему, зачем тебе нужно в Покой Звезд. Он даст тебе самого быстрого из своих грифонов. Прибудешь на место – поговори с верховным магом Модерой.','Поговорите с Родни Веллсом в крепости Стражей Зимы, чтобы отправиться в Покой Звезд в западном Драконьем Погосте.','Нет, друг, еще одного Раскола нам не надо! Я сделаю все, что в моих силах, чтобы помочь тебе в твоей миссии…') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Проблемы на западе',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Появилась новая сила, угрожающая разрушить все, над чем мы трудились, $n. Тебе придется отправиться на запад, в Покой Звезд. Верховный маг Модера чувствует сильное возмущение силовых линий нашего мира, которое следует немедленно ликвидировать!$b$bОтправляйся прямо сейчас, $n! Поговори с Родни Веллсом на грифоньей площадке и объясни ему, зачем тебе нужно в Покой Звезд. Он даст тебе самого быстрого из своих грифонов. Прибудешь на место – поговори с верховным магом Модерой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Родни Веллсом в крепости Стражей Зимы, чтобы отправиться в Покой Звезд в западном Драконьем Погосте.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Нет, друг, еще одного Раскола нам не надо! Я сделаю все, что в моих силах, чтобы помочь тебе в твоей миссии…',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (12440,'В Покой Звезд!','Когда будешь $gготов:готова;, я посажу тебя на своего самого быстрого грифона, который отнесет тебя в Покой Звезд. Когда будешь там, найди верховного мага Модеру и поговори с ней.','Поговорите с проекцией верховного мага Модеры в Покое Звезд в западной части Драконьего Погоста.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В Покой Звезд!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда будешь $gготов:готова;, я посажу тебя на своего самого быстрого грифона, который отнесет тебя в Покой Звезд. Когда будешь там, найди верховного мага Модеру и поговори с ней.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с проекцией верховного мага Модеры в Покое Звезд в западной части Драконьего Погоста.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12443,'В поисках растворителя','О, да! То, что надо! Эта штука поможет мне сэкономить усилия.$B$BВот, $Gдружище:подруга;, возьми пару звонких монет за труды. Кстати, если тебе попадется в руки еще одна канистра с топливом – кати ее сюда!','Ты несешь мне элемент 115, $N?','Вернитесь к Барблфинку в Бухту торговцев, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В поисках растворителя',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, да! То, что надо! Эта штука поможет мне сэкономить усилия.$B$BВот, $Gдружище:подруга;, возьми пару звонких монет за труды. Кстати, если тебе попадется в руки еще одна канистра с топливом – кати ее сюда!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты несешь мне элемент 115, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Барблфинку в Бухту торговцев, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12444,'Резня в Черноречье','Капитан разведчиков Картер просит вас убить 10 представителей или игроков Орды на Лесопилке Черноречья.','Как продвигается охота?','Вернитесь к капитану разведчиков Картеру в Седые холмы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Резня в Черноречье',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Капитан разведчиков Картер просит вас убить 10 представителей или игроков Орды на Лесопилке Черноречья.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как продвигается охота?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану разведчиков Картеру в Седые холмы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (12446,'Растворитель всегда пригодится!','Вернитесь к Барблфинку в Бухту торговцев, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Растворитель всегда пригодится!',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Барблфинку в Бухту торговцев, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (12447,'Обсидиановое святилище драконов','Армия Плети идет. Кориалстраз взывает к своим союзникам в тщетной попытке спасти свое Рубиновое святилище, но, похоже, добрая воля красных драконов не распространяется на защиту святилищ других драконов.$B$BТы $gудивлен:удивлена;? А я ничуть.$B$BЗдесь есть и другие представители моего крыла – те, кто остался вычищать из нашего обсидианового святилища вредителей-нежить, что заполонили его. Все, что тебе нужно, чтобы доказать, что ты благороднее и праведнее самой Алекстразы, – это прогуляться до святилища и пару раз взмахнуть там мечом, или что там у тебя?$B$BХоть какое-то развлечение.','Отправляйтесь в Обсидиановое святилище драконов к северо-западу от Драконьего Покоя, совсем рядом с Вратами Гнева. Найдите в святилище Серинара и предложите ему свою помощь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обсидиановое святилище драконов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Армия Плети идет. Кориалстраз взывает к своим союзникам в тщетной попытке спасти свое Рубиновое святилище, но, похоже, добрая воля красных драконов не распространяется на защиту святилищ других драконов.$B$BТы $gудивлен:удивлена;? А я ничуть.$B$BЗдесь есть и другие представители моего крыла – те, кто остался вычищать из нашего обсидианового святилища вредителей-нежить, что заполонили его. Все, что тебе нужно, чтобы доказать, что ты благороднее и праведнее самой Алекстразы, – это прогуляться до святилища и пару раз взмахнуть там мечом, или что там у тебя?$B$BХоть какое-то развлечение.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Обсидиановое святилище драконов к северо-западу от Драконьего Покоя, совсем рядом с Вратами Гнева. Найдите в святилище Серинара и предложите ему свою помощь.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12448,'Горячая битва','Армия Плети заполонила святилище. Его хранительница, Далия Благословение Солнца, пропала. Красные змеи, павшие при защите святилища, теперь окружают нас, приняв форму жутких скелетов тлеющих змеев. Опасная ситуация, |3-6($r).$B$BГруппу тебе подобных, пытающуюся поуменьшить поток воинов Плети из святилища, возглавляет капитан Дрейзен.$B$BПриди к нему на помощь... но, пожалуйста, оставайся позади его бойцов. Поток воинов Плети бесконечен, а мне вовсе не хочется потерять тебя в одном из этих ущелий.','Помогите капитану Дрейзену удержать каньоны, приняв участие в смерти 12 хладных атакующих вурдалаков, 8 хладных атакующих упырей и 1 хладного атакующего поганища.$B$BКогда это будет выполнено, возвращайтесь к Варгастразу.','Я рад, что ты по прежнему с нами, |3-6($R).','Вернитесь к Варгастразу в Драконий Погост.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Горячая битва',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Армия Плети заполонила святилище. Его хранительница, Далия Благословение Солнца, пропала. Красные змеи, павшие при защите святилища, теперь окружают нас, приняв форму жутких скелетов тлеющих змеев. Опасная ситуация, |3-6($r).$B$BГруппу тебе подобных, пытающуюся поуменьшить поток воинов Плети из святилища, возглавляет капитан Дрейзен.$B$BПриди к нему на помощь... но, пожалуйста, оставайся позади его бойцов. Поток воинов Плети бесконечен, а мне вовсе не хочется потерять тебя в одном из этих ущелий.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Помогите капитану Дрейзену удержать каньоны, приняв участие в смерти 12 хладных атакующих вурдалаков, 8 хладных атакующих упырей и 1 хладного атакующего поганища.$B$BКогда это будет выполнено, возвращайтесь к Варгастразу.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я рад, что ты по прежнему с нами, |3-6($R).',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Варгастразу в Драконий Погост.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12449,'Погребение','Есть еще одно дело, требующее внимания. Мои собратья гибнут в битве, и если мы не поторопимся, они лишь пополнят ряды тлеющих змеев.$B$BОтправляйся в святилище через проход на юге... Там, должно быть, плотность сил Плети не так велика.$B$BПоищи в святилище рубиновые желуди, упавшие с дерева, и посади их рядом с телами моих павших соплеменников. Они положат начало новой жизни... а это – честь для любого из нас.','Отправляйтесь в Рубиновое святилище драконов через южный проход и поищите там рубиновые желуди. С помощью рубиновых желудей предайте тела павших красных драконов земле. По выполнении задания вернитесь к Варгастразу.','Я уж начал беспокоиться, что силы Плети, обосновавшиеся в святилище, покончили с тобой. Хорошо, что ты еще жив.','Вернитесь к Варгастразу в Драконий Погост.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Погребение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Есть еще одно дело, требующее внимания. Мои собратья гибнут в битве, и если мы не поторопимся, они лишь пополнят ряды тлеющих змеев.$B$BОтправляйся в святилище через проход на юге... Там, должно быть, плотность сил Плети не так велика.$B$BПоищи в святилище рубиновые желуди, упавшие с дерева, и посади их рядом с телами моих павших соплеменников. Они положат начало новой жизни... а это – честь для любого из нас.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Рубиновое святилище драконов через южный проход и поищите там рубиновые желуди. С помощью рубиновых желудей предайте тела павших красных драконов земле. По выполнении задания вернитесь к Варгастразу.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я уж начал беспокоиться, что силы Плети, обосновавшиеся в святилище, покончили с тобой. Хорошо, что ты еще жив.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Варгастразу в Драконий Погост.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12450,'Через огненные поля','У меня есть для тебя последнее задание, |3-6($r)... дело, которое должно повернуть ход сражения в нашу пользу.$B$BВозвращайся в святилище и убей некромантов, раздувающих горнило этой бойни. Когда они будут мертвы, нам, должно быть, удастся отбросить их силы и в результате отвоевать святилище.$B$BМне также нужно, чтобы ты $gотыскал:отыскала; источник осквернения под святилищем и $gуничтожил:уничтожила; его.$B$BЯ знаю, что уже и так потребовал от тебя слишком многого, но если ты выполнишь и эту мою просьбу, мы одержим победу в этой битве.','Отправляйтесь в Рубиновое святилище драконов через южный проход, затем убейте 6 хладных некромантов и уничтожьте источник осквернения, находящийся под святилищем. По выполнении задания вернитесь к Варгастразу.','Ты вернулся! То, о чем я просил тебя, выполнено?','Вернитесь к Варгастразу в Драконий Погост.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Через огненные поля',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У меня есть для тебя последнее задание, |3-6($r)... дело, которое должно повернуть ход сражения в нашу пользу.$B$BВозвращайся в святилище и убей некромантов, раздувающих горнило этой бойни. Когда они будут мертвы, нам, должно быть, удастся отбросить их силы и в результате отвоевать святилище.$B$BМне также нужно, чтобы ты $gотыскал:отыскала; источник осквернения под святилищем и $gуничтожил:уничтожила; его.$B$BЯ знаю, что уже и так потребовал от тебя слишком многого, но если ты выполнишь и эту мою просьбу, мы одержим победу в этой битве.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Рубиновое святилище драконов через южный проход, затем убейте 6 хладных некромантов и уничтожьте источник осквернения, находящийся под святилищем. По выполнении задания вернитесь к Варгастразу.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты вернулся! То, о чем я просил тебя, выполнено?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Варгастразу в Драконий Погост.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (12451,'Вперед, в Лагерь Уанква','Поговорите с разведчиком Вор\'такхом в Лагере Уанква.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вперед, в Лагерь Уанква',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с разведчиком Вор\'такхом в Лагере Уанква.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (12452,'zzOLD Судьба рубинового святилища драконов','Принесите Церистразу рубиновую брошь Далии и расскажите ему о ее судьбе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','zzOLD Судьба рубинового святилища драконов',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Церистразу рубиновую брошь Далии и расскажите ему о ее судьбе.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12453,'Взгляд с высоты','Меня попросили оказать помощь в борьбе против Альянса. В данный момент наши силы примерно равны, но мы постоянно ищем способ переломить ситуацию в нашу пользу.$B$BНапример, императорские орлы, кружащие над горами на востоке, могли бы стать отличными разведчиками. Возьми это серебряное перо. С помощью него можно объединить мое зрение с глазами птиц. $B$BПредставляешь, насколько велико будет наше преимущество, если мы сможем свысока следить за всеми перемещениями противника?','Заклинательница ветра Серый Рог просит вас коснуться серебряным пером шести императорских орлов в Седых холмах.','Ты сделал то, о чем я тебя просил, $N?','Вернитесь к заклинательнице ветра Серый Рог в Крепость Завоевателей, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Взгляд с высоты',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Меня попросили оказать помощь в борьбе против Альянса. В данный момент наши силы примерно равны, но мы постоянно ищем способ переломить ситуацию в нашу пользу.$B$BНапример, императорские орлы, кружащие над горами на востоке, могли бы стать отличными разведчиками. Возьми это серебряное перо. С помощью него можно объединить мое зрение с глазами птиц. $B$BПредставляешь, насколько велико будет наше преимущество, если мы сможем свысока следить за всеми перемещениями противника?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заклинательница ветра Серый Рог просит вас коснуться серебряным пером шести императорских орлов в Седых холмах.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты сделал то, о чем я тебя просил, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к заклинательнице ветра Серый Рог в Крепость Завоевателей, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12454,'Жизненный цикл','Изера спит в Изумрудном Сне, наблюдая и за Сном, и за Азеротом. Но во Сне поселилось ужасное зло, и я боюсь, что оно имеет влияние и на Изеру.$B$BНедавно я попросила ее о помощи в борьбе против сил Плети, поднимающих ледяных змеев в других драконьих святилищах. Она не поняла меня...$B$BВместо этого она велела защитникам нашего святилища расценивать других драконов, не зеленых, как врагов.$B$BМне нужно, чтобы ты $gубил:убила; несколько когтемахов. В святилище должен быть восстановлен баланс.','По просьбе Нишеры Хранительницы Садов из изумрудного святилища драконов убейте 5 изумрудных небесных когтей.','Чем раньше удастся разобраться с изумрудными небесными когтями, тем скорее Изумрудное святилище драконов можно будет вернуть в его естественный баланс.','Вернитесь к Нишере Хранительнице Садов в Изумрудное святилище драконов, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жизненный цикл',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Изера спит в Изумрудном Сне, наблюдая и за Сном, и за Азеротом. Но во Сне поселилось ужасное зло, и я боюсь, что оно имеет влияние и на Изеру.$B$BНедавно я попросила ее о помощи в борьбе против сил Плети, поднимающих ледяных змеев в других драконьих святилищах. Она не поняла меня...$B$BВместо этого она велела защитникам нашего святилища расценивать других драконов, не зеленых, как врагов.$B$BМне нужно, чтобы ты $gубил:убила; несколько когтемахов. В святилище должен быть восстановлен баланс.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По просьбе Нишеры Хранительницы Садов из изумрудного святилища драконов убейте 5 изумрудных небесных когтей.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Чем раньше удастся разобраться с изумрудными небесными когтями, тем скорее Изумрудное святилище драконов можно будет вернуть в его естественный баланс.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Нишере Хранительнице Садов в Изумрудное святилище драконов, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (12455,'Унесенные ветром','По поручению Амбо Кэша из усыпальницы Стражей Зимы соберите 8 ящиков снаряжения Стражей Зимы.','Как раз вовремя! Кое-кто из моих ребят немного погорячился – они решили полезть в склепы, что к востоку и к западу от нас. Нечего и говорить, эти безмозглые гули одолели их числом. Нужно спасти тех, кто остался в живых!','Вернитесь к Амбо Кэшу в Усыпальницу Стражей Зимы, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Унесенные ветром',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По поручению Амбо Кэша из усыпальницы Стражей Зимы соберите 8 ящиков снаряжения Стражей Зимы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Как раз вовремя! Кое-кто из моих ребят немного погорячился – они решили полезть в склепы, что к востоку и к западу от нас. Нечего и говорить, эти безмозглые гули одолели их числом. Нужно спасти тех, кто остался в живых!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Амбо Кэшу в Усыпальницу Стражей Зимы, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12457,'Ты и пушка','Мы установили скорострельные пушки и баррикады к востоку и к западу отсюда. Наши раненые прячутся в обеих комнатах и изо всех сил стараются не привлекать внимания вурдалаков.$b$bТеперь, когда у нас есть боеприпасы, я прошу тебя встать к одной из пушек и проложить с ее помощью путь для наших солдат! Оказавшись у пушки, вызови солдата, который прячется в укрытии, и прикрой его огнем, чтобы не подпускать к нему воинов Плети!$b$bВперед!','Спасите 8 раненых солдат 7-го легиона по просьбе Амбо Кэша из усыпальницы Стражей Зимы в Драконьем Погосте.','Ты $Gспас:спасла; наших раненых солдат?','Вернитесь к Амбо Кэшу в Усыпальницу Стражей Зимы, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ты и пушка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы установили скорострельные пушки и баррикады к востоку и к западу отсюда. Наши раненые прячутся в обеих комнатах и изо всех сил стараются не привлекать внимания вурдалаков.$b$bТеперь, когда у нас есть боеприпасы, я прошу тебя встать к одной из пушек и проложить с ее помощью путь для наших солдат! Оказавшись у пушки, вызови солдата, который прячется в укрытии, и прикрой его огнем, чтобы не подпускать к нему воинов Плети!$b$bВперед!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Спасите 8 раненых солдат 7-го легиона по просьбе Амбо Кэша из усыпальницы Стражей Зимы в Драконьем Погосте.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gспас:спасла; наших раненых солдат?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Амбо Кэшу в Усыпальницу Стражей Зимы, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12458,'Семена плеточника','Нам нужно больше оружия для борьбы с Плетью! Помочь могут естественные свойства Изумрудного святилища драконов, которое находится на юго-востоке.$b$bЛюбое неживое существо, кроме освобожденных Сильваной, вступившее в драконье святилище, рассыпается в прах.$b$bЯ хочу проверить одну гипотезу, и ты мне в этом поможешь, $gюный:юная:r; |3-6($r). Ступай в Изумрудное драконье святилище и добудь там семена изумрудного плеточника.','Принесите 3 семени плеточника лорду Итару на вершине храма Драконьего Покоя.','И сколько семян тебе пока что удалось раздобыть?','Вернитесь к лорду Итару в Храм Драконьего Покоя, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Семена плеточника',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нам нужно больше оружия для борьбы с Плетью! Помочь могут естественные свойства Изумрудного святилища драконов, которое находится на юго-востоке.$b$bЛюбое неживое существо, кроме освобожденных Сильваной, вступившее в драконье святилище, рассыпается в прах.$b$bЯ хочу проверить одну гипотезу, и ты мне в этом поможешь, $gюный:юная:r; |3-6($r). Ступай в Изумрудное драконье святилище и добудь там семена изумрудного плеточника.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 3 семени плеточника лорду Итару на вершине храма Драконьего Покоя.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','И сколько семян тебе пока что удалось раздобыть?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лорду Итару в Храм Драконьего Покоя, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12459,'Что создает, то может и разрушать','Уничтожьте ослабленного оживленного ледяного змея, ослабленного Турджида Зловещего и ослабленного наблюдателя Убийственного Взгляда по просьбе лорда Итара, который находится на вершине храма Драконьего Покоя.','Надеюсь, ты с добрыми вестями, малявка?','Вернитесь к лорду Итару в Храм Драконьего Покоя, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Что создает, то может и разрушать',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте ослабленного оживленного ледяного змея, ослабленного Турджида Зловещего и ослабленного наблюдателя Убийственного Взгляда по просьбе лорда Итара, который находится на вершине храма Драконьего Покоя.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Надеюсь, ты с добрыми вестями, малявка?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лорду Итару в Храм Драконьего Покоя, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (12460,'Прибытие в Рубиновое святилище драконов','Ты нам $gнужен:нужна; в Рубиновом святилище драконов.$b$bДраконов осаждают со всех сторон: тут и синие драконы, и Плеть... Им приходится не легче, чем нам. Похоже, дела плохи. Но зато это предоставляет нам редкую возможность заключить ценный союз.$b$bЯ собрала отряд, чтобы отправить его на помощь красным драконам. Если в тебе живет боевой дух, иди к Церистразу и помогай ему во всем. Его можно найти на уступе к востоку от Рубинового святилища.','Явитесь к Церистразу на уступе к востоку от Рубинового святилища драконов, к западу от Драконьего Покоя.','Тебя прислала посол Лориэль?$B$BЕсли тебе доведется беседовать с ней снова, передай, что мы очень ценим ее помощь. Нам приходится вести войну на несколько фронтов сразу…') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прибытие в Рубиновое святилище драконов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты нам $gнужен:нужна; в Рубиновом святилище драконов.$b$bДраконов осаждают со всех сторон: тут и синие драконы, и Плеть... Им приходится не легче, чем нам. Похоже, дела плохи. Но зато это предоставляет нам редкую возможность заключить ценный союз.$b$bЯ собрала отряд, чтобы отправить его на помощь красным драконам. Если в тебе живет боевой дух, иди к Церистразу и помогай ему во всем. Его можно найти на уступе к востоку от Рубинового святилища.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Явитесь к Церистразу на уступе к востоку от Рубинового святилища драконов, к западу от Драконьего Покоя.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебя прислала посол Лориэль?$B$BЕсли тебе доведется беседовать с ней снова, передай, что мы очень ценим ее помощь. Нам приходится вести войну на несколько фронтов сразу…',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (12461,'Прибытие в Рубиновое святилище драконов','Ты отбываешь в Рубиновое святилище драконов. Это не обсуждается.$B$BДраконы находятся со всех сторон в окружении синих драконов и сил Плети... так что они не в лучшем положении, чем мы. Не так уж часто нам выпадает возможность самим искупить прегрешения наших предков.$B$BЯ поручил одному из полков помочь красным драконам сражаться с силами Плети в Рубиновом святилище. Присоединяйся к ним и размозжи воинов Плети подошвами своих сапог!$B$BЗа Орду!','Явитесь к Варгастразу на хребте у Рубинового святилища драконов, к востоку от Молота Агмара.','Да, |3-6($R)? Чем могу служить?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прибытие в Рубиновое святилище драконов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты отбываешь в Рубиновое святилище драконов. Это не обсуждается.$B$BДраконы находятся со всех сторон в окружении синих драконов и сил Плети... так что они не в лучшем положении, чем мы. Не так уж часто нам выпадает возможность самим искупить прегрешения наших предков.$B$BЯ поручил одному из полков помочь красным драконам сражаться с силами Плети в Рубиновом святилище. Присоединяйся к ним и размозжи воинов Плети подошвами своих сапог!$B$BЗа Орду!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Явитесь к Варгастразу на хребте у Рубинового святилища драконов, к востоку от Молота Агмара.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да, |3-6($R)? Чем могу служить?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12462,'Кирпичик за кирпичиком','Спустись по этой лестнице – и вот они, врата проклятия: воины Плети повсюду, насколько глаз хватает, и их толпа становится все плотнее, с каждой секундой. Скудные сведения, которые нам удалось добыть, указывают, что два некролорда Плети со страшной скоростью опустошают первые два склепа там, внизу. Прежде чем мы вломимся в нижнюю палату, к Тель\'зану, нам нужно позаботиться об этих двух болванах и их дружках из Наксрамаса.$B$BСпустись в усыпальницу и уничтожь некролордов, а также наксрамасских грозных стражей и теней.','По заданию Йорда "Бедствия" Снегоборода, находящегося у усыпальницы Стражей Зимы, убейте некролордов Кс\'авиуса и Гора, а также 15 наксрамасских воинов Плети.','Это даст Амбо немного времени, чтобы все разложить по полочкам.','Ты $Gотломил:отломила; себе кусок?','Вернитесь к Йорду "Бедствию" Снегобороду в Усыпальницу Стражей Зимы, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кирпичик за кирпичиком',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Спустись по этой лестнице – и вот они, врата проклятия: воины Плети повсюду, насколько глаз хватает, и их толпа становится все плотнее, с каждой секундой. Скудные сведения, которые нам удалось добыть, указывают, что два некролорда Плети со страшной скоростью опустошают первые два склепа там, внизу. Прежде чем мы вломимся в нижнюю палату, к Тель\'зану, нам нужно позаботиться об этих двух болванах и их дружках из Наксрамаса.$B$BСпустись в усыпальницу и уничтожь некролордов, а также наксрамасских грозных стражей и теней.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По заданию Йорда "Бедствия" Снегоборода, находящегося у усыпальницы Стражей Зимы, убейте некролордов Кс\'авиуса и Гора, а также 15 наксрамасских воинов Плети.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это даст Амбо немного времени, чтобы все разложить по полочкам.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gотломил:отломила; себе кусок?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Йорду "Бедствию" Снегобороду в Усыпальницу Стражей Зимы, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (12463,'Жаднобород должен быть найден!','Ходят слухи о прорытом Плетью туннеле, соединяющем бальзамировочные палаты с большими склепами, ныне разрытыми Тель\'заном и его приспешниками. Я недавно послал своего лучшего лазутчика, Жадноборода, в поисках ответов на свои вопросы, но пока еще не получил от него известий. Если бы я был человеком азартным, побился бы об заклад, что он уже на том свете.$B$BЯ хочу, чтобы ты $gспустился:спустилась; по этой лестнице, $gнаправился:направилась; прямиком в бальзамировочную палату и $gпоискал:поискала; Жадноборода. Живой или мертвый – он даст ответы.','По просьбе Амбо Кэша у усыпальницы Стражей Зимы найдите Жадноборода.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жаднобород должен быть найден!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ходят слухи о прорытом Плетью туннеле, соединяющем бальзамировочные палаты с большими склепами, ныне разрытыми Тель\'заном и его приспешниками. Я недавно послал своего лучшего лазутчика, Жадноборода, в поисках ответов на свои вопросы, но пока еще не получил от него известий. Если бы я был человеком азартным, побился бы об заклад, что он уже на том свете.$B$BЯ хочу, чтобы ты $gспустился:спустилась; по этой лестнице, $gнаправился:направилась; прямиком в бальзамировочную палату и $gпоискал:поискала; Жадноборода. Живой или мертвый – он даст ответы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По просьбе Амбо Кэша у усыпальницы Стражей Зимы найдите Жадноборода.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12465,'Дневник Жадноборода','Что бы ни было написано на остальных страницах дневника Жадноборода, нужно этот дневник разыскать. Поищите в палатах на другой стороне тоннеля тех, кто напал на Жадноборода. Должно быть, они-то и разодрали его дневник!$B$BЕсли найдете недостающие страницы, принесите их Амбо Кэшу ко входу в усыпальницу Стражей Зимы.','Найдите недостающие страницы дневника Жадноборода: страницу 4, страницу 5, страницу 6 и страницу 7. Отнесите их Амбо Кэшу, ожидающему рядом с усыпальницей Стражей Зимы на Драконьем Погосте.','<Амбо читает найденные вами страницы дневника.>$B$BЕсть хорошие новости, но есть и плохие. Какую рассказать первой?$B$BДа ну вот еще, зачем тебе выбор? Итак, хорошая новость в том, что если мы сможем добыть филактерию Тель\'зана, то сможем уничтожить его. Плохая – в том, что филактерия эта находится на ледяном змее весьма внушительных размеров.','Да уж, победителем я себя определенно не чувствую...','Вернитесь к Амбо Кэшу в Усыпальницу Стражей Зимы, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дневник Жадноборода',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что бы ни было написано на остальных страницах дневника Жадноборода, нужно этот дневник разыскать. Поищите в палатах на другой стороне тоннеля тех, кто напал на Жадноборода. Должно быть, они-то и разодрали его дневник!$B$BЕсли найдете недостающие страницы, принесите их Амбо Кэшу ко входу в усыпальницу Стражей Зимы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите недостающие страницы дневника Жадноборода: страницу 4, страницу 5, страницу 6 и страницу 7. Отнесите их Амбо Кэшу, ожидающему рядом с усыпальницей Стражей Зимы на Драконьем Погосте.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Амбо читает найденные вами страницы дневника.>$B$BЕсть хорошие новости, но есть и плохие. Какую рассказать первой?$B$BДа ну вот еще, зачем тебе выбор? Итак, хорошая новость в том, что если мы сможем добыть филактерию Тель\'зана, то сможем уничтожить его. Плохая – в том, что филактерия эта находится на ледяном змее весьма внушительных размеров.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да уж, победителем я себя определенно не чувствую...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Амбо Кэшу в Усыпальницу Стражей Зимы, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (12466,'Погоня за Ледяной Бурей: Передовая 7-го легиона','Тебе нужно отыскать Передовую 7-го легиона в северном Драконьем Погосте. Вернись в крепость Стражей Зимы и выйди из города через северные ворота. Ступай на север, пока не дойдешь до дороги. Поверни налево и иди по дороге до тех пор, пока не дойдешь до линии снегов. Иди дальше на запад, пока не выйдешь на Путь Титанов. Ступай на север, и он выведет тебя прямо на передовую 7-го легиона.$b$bКак придешь туда, поговори с командиром легиона Тиралионом. Он ждет тебя.$b$bПриятно было познакомиться, $n. Прощай!','Явитесь к командиру легиона Тиралиону на Передовой 7-го легиона в центральном Драконьем Погосте.','Теперь ты понимаешь, почему этот край зовется Драконьими пустошами. Повсюду, куда ни глянь, валяются кости.$B$BМы завалили, наверное, с десяток или больше ледяных змеев, но им конца не видно. У Плети хватит запасов еще на десять тысяч таких змеев, когда костей вокруг сколько угодно.$B$B<Тиралион прочищает горло.>$B$BВпрочем, не буду донимать тебя скучными подробностями. Змея, который тебе нужен, можно увидеть отсюда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Погоня за Ледяной Бурей: Передовая 7-го легиона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе нужно отыскать Передовую 7-го легиона в северном Драконьем Погосте. Вернись в крепость Стражей Зимы и выйди из города через северные ворота. Ступай на север, пока не дойдешь до дороги. Поверни налево и иди по дороге до тех пор, пока не дойдешь до линии снегов. Иди дальше на запад, пока не выйдешь на Путь Титанов. Ступай на север, и он выведет тебя прямо на передовую 7-го легиона.$b$bКак придешь туда, поговори с командиром легиона Тиралионом. Он ждет тебя.$b$bПриятно было познакомиться, $n. Прощай!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Явитесь к командиру легиона Тиралиону на Передовой 7-го легиона в центральном Драконьем Погосте.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь ты понимаешь, почему этот край зовется Драконьими пустошами. Повсюду, куда ни глянь, валяются кости.$B$BМы завалили, наверное, с десяток или больше ледяных змеев, но им конца не видно. У Плети хватит запасов еще на десять тысяч таких змеев, когда костей вокруг сколько угодно.$B$B<Тиралион прочищает горло.>$B$BВпрочем, не буду донимать тебя скучными подробностями. Змея, который тебе нужен, можно увидеть отсюда.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12467,'Охота на Ледяную Бурю: филактерия Тель\'зана','Твой ледяной змей там.$B$B<Тиралион указывает на запад.>$B$BИ он очень большой!$B$BКогда ты будешь $gготов:готова; к бою, иди, поговори с "Приманкой для драконов". Он "приведет" змея. Когда Ледяная Буря будет достаточно близко, мы прикуем ее к земле и прикончим! Надеюсь, с твоей помощью, мы сумеем победить змея и добыть тебе эту филактерию.$B$BКогда она будет у тебя, возвращайся в крепость Стражей Зимы к главнокомандующему Халфорду Змеевержцу. Он ведет подготовку к последнему столкновению с Тель\'заном.','Добудьте с тела Ледяной Бури филактерию Тель\'зана и отнесите ее главнокомандующему Халфорду Змеевержцу в крепость Стражей Зимы.','Мы из-за этого чудовища, Тель\'зана, столько хороших солдат потеряли!.. Хотел бы я видеть своими глазами, как ты разобьешь эту филактерию у него на глазах и покончишь с ним.','Тебе удалось достать филактерию Тель\'зана?','Вернитесь к главнокомандующему Халфорду Змеевержцу в Крепость Стражей Зимы, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота на Ледяную Бурю: филактерия Тель\'зана',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Твой ледяной змей там.$B$B<Тиралион указывает на запад.>$B$BИ он очень большой!$B$BКогда ты будешь $gготов:готова; к бою, иди, поговори с "Приманкой для драконов". Он "приведет" змея. Когда Ледяная Буря будет достаточно близко, мы прикуем ее к земле и прикончим! Надеюсь, с твоей помощью, мы сумеем победить змея и добыть тебе эту филактерию.$B$BКогда она будет у тебя, возвращайся в крепость Стражей Зимы к главнокомандующему Халфорду Змеевержцу. Он ведет подготовку к последнему столкновению с Тель\'заном.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте с тела Ледяной Бури филактерию Тель\'зана и отнесите ее главнокомандующему Халфорду Змеевержцу в крепость Стражей Зимы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мы из-за этого чудовища, Тель\'зана, столько хороших солдат потеряли!.. Хотел бы я видеть своими глазами, как ты разобьешь эту филактерию у него на глазах и покончишь с ним.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось достать филактерию Тель\'зана?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к главнокомандующему Халфорду Змеевержцу в Крепость Стражей Зимы, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (12468,'Поручение Завоевательницы','Орда – это могущественная боевая машина, в которой ты всего лишь мелкая шестеренка. $B$BЯ обеспечиваю топливо для этой машины. Если моя работа будет недостаточно эффективной, это скажется на всех нас.$B$BЛесозаготовки, руда, вода... нам нужны все эти ресурсы – равно как и Альянсу.$B$BНо прежде, чем мы выступим против этих ничтожных людишек, нам надо установить полный и безоговорочный контроль над западными территориями. $B$BПоговори с сержантом Назгримом – ему было поручено истребить врайкулов в Волдруне. Возможно, если ты хорошо проявишь себя на этой работе, мы решим доверить тебе более ответственные задания.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поручение Завоевательницы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Орда – это могущественная боевая машина, в которой ты всего лишь мелкая шестеренка. $B$BЯ обеспечиваю топливо для этой машины. Если моя работа будет недостаточно эффективной, это скажется на всех нас.$B$BЛесозаготовки, руда, вода... нам нужны все эти ресурсы – равно как и Альянсу.$B$BНо прежде, чем мы выступим против этих ничтожных людишек, нам надо установить полный и безоговорочный контроль над западными территориями. $B$BПоговори с сержантом Назгримом – ему было поручено истребить врайкулов в Волдруне. Возможно, если ты хорошо проявишь себя на этой работе, мы решим доверить тебе более ответственные задания.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (12469,'Вернуть отправителю','При ближайшем рассмотрении выяснилось, что гоблин, очевидно, вез через пустоши груз взрывчатки. Судя по торчащим из снега перьям гарпии, до места бедолага не добрался.$b$bПо-видимому, он вез взрывчатку к Вратам Гнева откуда-то с востока. Разумнее всего будет вернуться вдоль гряды обратно на восток и сообщить отправителю о судьбе его гонца.','Ступайте на восток вдоль гряды и доставьте груз взрывчатки Зинку в Лагерь Соплозабилось в северном Драконьем Погосте.','Вернитесь к Зинку в Морозные выси, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вернуть отправителю',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','При ближайшем рассмотрении выяснилось, что гоблин, очевидно, вез через пустоши груз взрывчатки. Судя по торчащим из снега перьям гарпии, до места бедолага не добрался.$b$bПо-видимому, он вез взрывчатку к Вратам Гнева откуда-то с востока. Разумнее всего будет вернуться вдоль гряды обратно на восток и сообщить отправителю о судьбе его гонца.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Ступайте на восток вдоль гряды и доставьте груз взрывчатки Зинку в Лагерь Соплозабилось в северном Драконьем Погосте.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Зинку в Морозные выси, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (12470,'Тайна бесконечности','Временная буря в бронзовом святилище драконов на северо-востоке не позволяет бессмертным войти в него.$B$BВнутри драконы Бесконечности ведут бой с защитниками святилища за контроль над ним. Мы должны использовать эту возможность для получения информации.$B$BТы же не $gбессмертный:бессмертная;. Ты можешь проникнуть в святилище и задействовать там песочные часы Вечности. Защищай часы достаточно долго – и вожак драконов Бесконечности раскроет себя.$B$BБудь осторожнее: драконы Бесконечности обязательно попытаются остановить тебя!','Отправляйтесь в бронзовое святилище драконов. Когда проникнете в святилище, поставьте на землю песочные часы Вечности.$B$BЗащищайте часы, пока они идут, а потом возвращайтесь к Хроми на вершину храма Драконьего покоя и передайте ей полученную вами информацию.','Какие новости ты $Gпринес:принесла;? Что случилось в Бронзовом святилище драконов?$B$BТы $Gузнал:уназала; кто является лидером драконов Бесконечности?','Песочные часы Вечности защищены','Вернитесь к Хроми в Храм Драконьего Покоя, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тайна бесконечности',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Временная буря в бронзовом святилище драконов на северо-востоке не позволяет бессмертным войти в него.$B$BВнутри драконы Бесконечности ведут бой с защитниками святилища за контроль над ним. Мы должны использовать эту возможность для получения информации.$B$BТы же не $gбессмертный:бессмертная;. Ты можешь проникнуть в святилище и задействовать там песочные часы Вечности. Защищай часы достаточно долго – и вожак драконов Бесконечности раскроет себя.$B$BБудь осторожнее: драконы Бесконечности обязательно попытаются остановить тебя!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в бронзовое святилище драконов. Когда проникнете в святилище, поставьте на землю песочные часы Вечности.$B$BЗащищайте часы, пока они идут, а потом возвращайтесь к Хроми на вершину храма Драконьего покоя и передайте ей полученную вами информацию.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Какие новости ты $Gпринес:принесла;? Что случилось в Бронзовом святилище драконов?$B$BТы $Gузнал:уназала; кто является лидером драконов Бесконечности?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Песочные часы Вечности защищены',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хроми в Храм Драконьего Покоя, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (12471,'Жестокость квалдиров','Благодарю тебя за спасение, $n! Эти квалдиры просто звери!$b$bОни заставляли нас сражаться с другими узниками. Милосерднее было бы просто убить нас всех!$b$bЮный Карук все еще жив, я видел, как он появился. Скажи ему, что его отец сражался до конца!','Расскажите Каруку о пленном узнике-клыкарре.','Удалось ли тебе одолеть Геймела, |3-6($C)?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жестокость квалдиров',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Благодарю тебя за спасение, $n! Эти квалдиры просто звери!$b$bОни заставляли нас сражаться с другими узниками. Милосерднее было бы просто убить нас всех!$b$bЮный Карук все еще жив, я видел, как он появился. Скажи ему, что его отец сражался до конца!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Расскажите Каруку о пленном узнике-клыкарре.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось ли тебе одолеть Геймела, |3-6($C)?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (12472,'Шаг к победе','Благодаря твоим подвигам лорд Фордрагон смог дать приказ о полномасштабном наступлении на Тель\'зана. Седьмой легион пробился в Чертог призыва в усыпальнице и обнаружил нечто похожее на врата в преисподнюю. Теперь дело за тобой.$B$BВозьми филактерию и доложись командиру легиона Йорику в усыпальнице Стражей Зимы.$B$BТам, у стен крепости, есть туннель, прокопанный воинами Плети, так что ты сможешь быстро добраться до Йорика. Иди же, $n! Принеси нам победу!','Отнесите филактерию Тель\'зана командиру легиона Йорику в усыпальницу Стражей Зимы в Драконьем Погосте.','Вернитесь к командиру легионе Йорику на Поля Падальщиков, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Шаг к победе',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Благодаря твоим подвигам лорд Фордрагон смог дать приказ о полномасштабном наступлении на Тель\'зана. Седьмой легион пробился в Чертог призыва в усыпальнице и обнаружил нечто похожее на врата в преисподнюю. Теперь дело за тобой.$B$BВозьми филактерию и доложись командиру легиона Йорику в усыпальнице Стражей Зимы.$B$BТам, у стен крепости, есть туннель, прокопанный воинами Плети, так что ты сможешь быстро добраться до Йорика. Иди же, $n! Принеси нам победу!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите филактерию Тель\'зана командиру легиона Йорику в усыпальницу Стражей Зимы в Драконьем Погосте.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру легионе Йорику на Поля Падальщиков, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (12473,'Конец и начало','У каждой хорошей истории есть свое начало и свое окончание, $n. Хотя твоя история еще далека от завершения, будь я проклят, если она недостойна уже сейчас стать легендой! Неважно, что случится с нами, когда все это закончится, о том, что тебе удалось сделать у Стражей Зимы, будут вспоминать и рассказывать еще долгие годы.$B$BА теперь, $gмой храбрый союзник:моя отважная союзница;, когда будешь $gготов:готова;, я воспользуюсь филактерией, чтобы вытащить Тель\'зана из его укрытия.$B$BЕсли нам будет сопутствовать успех, доложи о победе главнокомандующему Халфорду Змеевержцу в крепость Стражей Зимы.','Сразите Тель\'зана Мраконосца и доложите об этом главнокомандующему Халфорду Змеебою из крепости Стражей Зимы на Драконьем Погосте.','Тель\'зан Мраконосец сражен','Вернитесь к главнокомандующему Халфорду Змеевержцу в Крепость Стражей Зимы, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Конец и начало',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У каждой хорошей истории есть свое начало и свое окончание, $n. Хотя твоя история еще далека от завершения, будь я проклят, если она недостойна уже сейчас стать легендой! Неважно, что случится с нами, когда все это закончится, о том, что тебе удалось сделать у Стражей Зимы, будут вспоминать и рассказывать еще долгие годы.$B$BА теперь, $gмой храбрый союзник:моя отважная союзница;, когда будешь $gготов:готова;, я воспользуюсь филактерией, чтобы вытащить Тель\'зана из его укрытия.$B$BЕсли нам будет сопутствовать успех, доложи о победе главнокомандующему Халфорду Змеевержцу в крепость Стражей Зимы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сразите Тель\'зана Мраконосца и доложите об этом главнокомандующему Халфорду Змеебою из крепости Стражей Зимы на Драконьем Погосте.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Тель\'зан Мраконосец сражен',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к главнокомандующему Халфорду Змеевержцу в Крепость Стражей Зимы, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (12474,'За крепость Фордрагона!','Теперь, когда военная машина Наксрамаса застопорилась, тебе пришло время помочь нашим воинам в Ангратаре, у Врат Гнева. У подножия горы в северном Драконьем Погосте расположена наша база, крепость Фордрагона. Лорд Фордрагон ждет тебя! Ступай туда, $n!$b$bВыйди из города через северные ворота, ступай на север, потом на северо-запад, и придешь, куда нужно.$b$bДа хранит тебя Свет!','Отправляйтесь в крепость Фордрагона в Драконьем Погосте и поговорите с верховным лордом Болваром Фордрагоном.','Эта награда дается лишь тем, кто делает все мыслимое и немыслимое на службе Альянсу. Я могу по пальцам пересчитать случаи, когда мне доводилось ее вручать, и никто не заслуживал ее более тебя, $N! Поздравляю!$B$BА теперь давай взглянем на Врата Гнева. Знакомое зрелище, не правда ли? Еще бы. Эти ворота сделаны из того самого странного материала, который ты $Gобнаружил:обнаружила; в руднике Стражей Зимы. Ничего, мы еще найдем слабое место этой руды! А пока...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','За крепость Фордрагона!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда военная машина Наксрамаса застопорилась, тебе пришло время помочь нашим воинам в Ангратаре, у Врат Гнева. У подножия горы в северном Драконьем Погосте расположена наша база, крепость Фордрагона. Лорд Фордрагон ждет тебя! Ступай туда, $n!$b$bВыйди из города через северные ворота, ступай на север, потом на северо-запад, и придешь, куда нужно.$b$bДа хранит тебя Свет!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в крепость Фордрагона в Драконьем Погосте и поговорите с верховным лордом Болваром Фордрагоном.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Эта награда дается лишь тем, кто делает все мыслимое и немыслимое на службе Альянсу. Я могу по пальцам пересчитать случаи, когда мне доводилось ее вручать, и никто не заслуживал ее более тебя, $N! Поздравляю!$B$BА теперь давай взглянем на Врата Гнева. Знакомое зрелище, не правда ли? Еще бы. Эти ворота сделаны из того самого странного материала, который ты $Gобнаружил:обнаружила; в руднике Стражей Зимы. Ничего, мы еще найдем слабое место этой руды! А пока...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12475,'Какие тайны они скрывают?','После предательства на Забытом взморье принц Артас вместе с Мурадином пустился на поиски Ледяной Скорби. Быть может, пещера, где был найден этот печально знаменитый меч, где-то поблизости? И какие тайны она скрывает? Шар не может дать ответов на эти вопросы, и все же кое- что я могу разглядеть.$b$bК северо-востоку от крепости Стражей Зимы находится застава, выстроенная Алым Натиском. Где-то там хранится карта. Шар подсказывает мне, что эта карта нам бы очень пригодилась.$b$bДобудь ее!','Добудьте карту Натиска по просьбе Зелига Иллюзорного из крепости Стражей Зимы в Драконьем Погосте и вернитесь с ней к Зелигу.','Пещера? Возможно ли такое? Но других вариантов быть не может!','Ну что, удалось тебе найти карту Натиска?','Вернитесь к Зелигу Иллюзорному в Крепость Стражей Зимы, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Какие тайны они скрывают?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','После предательства на Забытом взморье принц Артас вместе с Мурадином пустился на поиски Ледяной Скорби. Быть может, пещера, где был найден этот печально знаменитый меч, где-то поблизости? И какие тайны она скрывает? Шар не может дать ответов на эти вопросы, и все же кое- что я могу разглядеть.$b$bК северо-востоку от крепости Стражей Зимы находится застава, выстроенная Алым Натиском. Где-то там хранится карта. Шар подсказывает мне, что эта карта нам бы очень пригодилась.$b$bДобудь ее!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте карту Натиска по просьбе Зелига Иллюзорного из крепости Стражей Зимы в Драконьем Погосте и вернитесь с ней к Зелигу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Пещера? Возможно ли такое? Но других вариантов быть не может!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, удалось тебе найти карту Натиска?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Зелигу Иллюзорному в Крепость Стражей Зимы, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12476,'Возвращение Алого ордена?','К северо-востоку от крепости Стражей Зимы находится новый лагерь, возведенный Алым орденом – а точнее, Алым Натиском, как они себя теперь называют. Мы пока не знаем, зачем они явились в Нордскол, но они, несомненно, не менее опасны, чем были прежде. Только вчера Алый Натиск убил двенадцать наших солдат! Пора их проучить, $n.$b$bСтупай в лагерь Алого Натиска и задай им жару!','Убейте 20 воинов Алого Натиска в лагере Алого Натиска по приказу командира Линоры Порыв Ветра.','Надеюсь, теперь до них дойдет. Есть надежда, что суровый урок заставит их задуматься над тем, что они делают.','Очисти базовый лагерь Натиска, $N.','Вернитесь к командиру Линоре Порыв Ветра в Крепость Стражей Зимы, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение Алого ордена?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','К северо-востоку от крепости Стражей Зимы находится новый лагерь, возведенный Алым орденом – а точнее, Алым Натиском, как они себя теперь называют. Мы пока не знаем, зачем они явились в Нордскол, но они, несомненно, не менее опасны, чем были прежде. Только вчера Алый Натиск убил двенадцать наших солдат! Пора их проучить, $n.$b$bСтупай в лагерь Алого Натиска и задай им жару!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 20 воинов Алого Натиска в лагере Алого Натиска по приказу командира Линоры Порыв Ветра.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Надеюсь, теперь до них дойдет. Есть надежда, что суровый урок заставит их задуматься над тем, что они делают.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Очисти базовый лагерь Натиска, $N.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру Линоре Порыв Ветра в Крепость Стражей Зимы, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12477,'Путь искупления','Знаешь, что такое "Путь искупления"? Похоже, это дневник, в котором изложены пророческие откровения Аббендис, верховного генерала Алого Натиска. Там, помимо всяческой чепухи, упомянуты все цели и задачи приверженцев Алого Натиска.$b$bПроберись в лагерь Натиска, к северо-востоку от крепости Стражей Зимы, и добудь у одного из солдат Натиска копию "Пути искупления".','Принесите копию "Пути искупления" главнокомандующему Халфорду Змеевержцу из крепости Стражей Зимы в Драконьем Погосте.','Ну что, удалось тебе найти копию дневника?','Вернитесь к главнокомандующему Халфорду Змеевержцу в Крепость Стражей Зимы, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путь искупления',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Знаешь, что такое "Путь искупления"? Похоже, это дневник, в котором изложены пророческие откровения Аббендис, верховного генерала Алого Натиска. Там, помимо всяческой чепухи, упомянуты все цели и задачи приверженцев Алого Натиска.$b$bПроберись в лагерь Натиска, к северо-востоку от крепости Стражей Зимы, и добудь у одного из солдат Натиска копию "Пути искупления".',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите копию "Пути искупления" главнокомандующему Халфорду Змеевержцу из крепости Стражей Зимы в Драконьем Погосте.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, удалось тебе найти копию дневника?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к главнокомандующему Халфорду Змеевержцу в Крепость Стражей Зимы, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12478,'Пещера Ледяной Скорби','Они окрестили ее пещерой Ледяной Скорби. Не знаю, к чему она Алому Натиску, но, судя по всему, окрестности пещеры надежно охраняются. И тем не менее, нам нужно действовать!$b$bВозьми этот гадальный шар и ступай на север от города, а потом – на северо-запад, в сторону заставы Алого ордена. Проберись в пещеру и пробейся вглубь, на самое дно. Там пусти в ход шар. Потом вернись и расскажи, что тебе удастся обнаружить.','Используйте гадальный шар Зелига на дне пещеры Ледяной Скорби по просьбе Зелига Иллюзорного из крепости Стражей Зимы в Драконьем Погосте. Откройте тайны былого!','Мурадин жив? Возможно ли такое? Я тотчас сообщу об этом королю Бронзобороду!$B$BМне нужно воспользоваться шаром. Где-то должна быть какая-то еще информация!','Ты $Gискал:искала; пещеру Ледяной Скорби?','Вернитесь к Зелигу Иллюзорному в Крепость Стражей Зимы, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пещера Ледяной Скорби',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Они окрестили ее пещерой Ледяной Скорби. Не знаю, к чему она Алому Натиску, но, судя по всему, окрестности пещеры надежно охраняются. И тем не менее, нам нужно действовать!$b$bВозьми этот гадальный шар и ступай на север от города, а потом – на северо-запад, в сторону заставы Алого ордена. Проберись в пещеру и пробейся вглубь, на самое дно. Там пусти в ход шар. Потом вернись и расскажи, что тебе удастся обнаружить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте гадальный шар Зелига на дне пещеры Ледяной Скорби по просьбе Зелига Иллюзорного из крепости Стражей Зимы в Драконьем Погосте. Откройте тайны былого!',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мурадин жив? Возможно ли такое? Я тотчас сообщу об этом королю Бронзобороду!$B$BМне нужно воспользоваться шаром. Где-то должна быть какая-то еще информация!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gискал:искала; пещеру Ледяной Скорби?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Зелигу Иллюзорному в Крепость Стражей Зимы, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`) VALUES (12479,'Welcome to the Wrath of the Lich King Friends and Family Alpha. Use the portals next to me to begin your journey into Northrend.$B$BYou can choose to report to the Alliance recruiter in Valiance Keep in Borean Tundra or you can go to Valgarde in Howling Fjord.','Speak to the Alliance Recruiter inside Valiance Keep in Borean Tundra or the one at Vengeance Landing in Howling Fjord.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Welcome to the Wrath of the Lich King Friends and Family Alpha. Use the portals next to me to begin your journey into Northrend.$B$BYou can choose to report to the Alliance recruiter in Valiance Keep in Borean Tundra or you can go to Valgarde in Howling Fjord.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Speak to the Alliance Recruiter inside Valiance Keep in Borean Tundra or the one at Vengeance Landing in Howling Fjord.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`) VALUES (12480,'Welcome to the Wrath of the Lich King Friends and Family Alpha. Use the portals next to me to begin your journey into Northrend.$B$BYou can choose to report to the Horde recruiter in Warsong Hold in Borean Tundra or you can go to Vengeance Landing in Howling Fjord.','Speak to the Horde Recruiter inside Warsong Hold in Borean Tundra or Vengeance Landing in Howling Fjord.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Welcome to the Wrath of the Lich King Friends and Family Alpha. Use the portals next to me to begin your journey into Northrend.$B$BYou can choose to report to the Horde recruiter in Warsong Hold in Borean Tundra or you can go to Vengeance Landing in Howling Fjord.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Speak to the Horde Recruiter inside Warsong Hold in Borean Tundra or Vengeance Landing in Howling Fjord.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12481,'Оскорбительное поражение','Эти врайкулы – хитрые твари. К счастью, у меня еще есть парочка трюков в рукаве.$B$BИх предводитель, Бьорн, отличается очень вспыльчивым нравом. Мы тут разобрали кое-какие слова из их языка и составили фразу, которая, по идее, может считаться оскорбительной. Там говорится что-то про его маму и крупный рогатый скот... честно говоря, мы и сами до конца не поняли. $B$BВот, зачитай ему текст с этой бумажки, а когда он бросится за тобой – приведи его прямо к нам. А мы уж постараемся, чтобы он не выбрался отсюда живым.','Молодец! Этот болван даже не понял, что произошло.','Работа наемного убийцы – далеко не такая увлекательная, какой ее изображают в романах.','Вернитесь к Лиделлу на Засаду Лиделла, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оскорбительное поражение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти врайкулы – хитрые твари. К счастью, у меня еще есть парочка трюков в рукаве.$B$BИх предводитель, Бьорн, отличается очень вспыльчивым нравом. Мы тут разобрали кое-какие слова из их языка и составили фразу, которая, по идее, может считаться оскорбительной. Там говорится что-то про его маму и крупный рогатый скот... честно говоря, мы и сами до конца не поняли. $B$BВот, зачитай ему текст с этой бумажки, а когда он бросится за тобой – приведи его прямо к нам. А мы уж постараемся, чтобы он не выбрался отсюда живым.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Молодец! Этот болван даже не понял, что произошло.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Работа наемного убийцы – далеко не такая увлекательная, какой ее изображают в романах.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лиделлу на Засаду Лиделла, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (12482,'Атака на Ниффлвар','Мы ожидаем прибытия подкрепления из Лагеря Возмездия, чтобы осадить Ниффлвар. Но если мы приступим к зачистке прямо сейчас, это даст нам огромное преимущество перед Альянсом.$B$B','Капитан следопытов Арейел просит вас отправиться в Ниффлвар и убить 5 воинов из клана Укротителей драконов, 4 руномантов из клана Укротителей драконов и 4 гончих-охотников из клана Укротителей драконов.','Вернитесь к капитану следопытов Арейел на Заставу Призрачного Клинка, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Атака на Ниффлвар',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы ожидаем прибытия подкрепления из Лагеря Возмездия, чтобы осадить Ниффлвар. Но если мы приступим к зачистке прямо сейчас, это даст нам огромное преимущество перед Альянсом.$B$B',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Капитан следопытов Арейел просит вас отправиться в Ниффлвар и убить 5 воинов из клана Укротителей драконов, 4 руномантов из клана Укротителей драконов и 4 гончих-охотников из клана Укротителей драконов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану следопытов Арейел на Заставу Призрачного Клинка, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (12483,'Похлебка из мерцающих грибов','Слушай, раз уж ты здесь... может, поможешь старине Пригмону? Есть у меня дружок, который умеет готовить изумительную мясную похлебку – ты, небось, даже и не $gпробовал:пробовала; ничего подобного.$b$bПравда, ему для этого нужны кое-какие ингредиенты, которые можно найти среди руин на юго-западе и в северном лагере. $b$bНе хочешь нам помочь?','Пригмон из Гранитных ключей просит вас собрать 5 мерцающих снежных грибов и 5 глаз ледяных змеев из руин Драк\'Зина и 5 сладокорней из Зеб\'Халака.','Ох, мамочка, неужели я скоро отведаю похлебки из снежных грибов?','Вернитесь к Пригмону на Гранитные ключи, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Похлебка из мерцающих грибов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слушай, раз уж ты здесь... может, поможешь старине Пригмону? Есть у меня дружок, который умеет готовить изумительную мясную похлебку – ты, небось, даже и не $gпробовал:пробовала; ничего подобного.$b$bПравда, ему для этого нужны кое-какие ингредиенты, которые можно найти среди руин на юго-западе и в северном лагере. $b$bНе хочешь нам помочь?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Пригмон из Гранитных ключей просит вас собрать 5 мерцающих снежных грибов и 5 глаз ледяных змеев из руин Драк\'Зина и 5 сладокорней из Зеб\'Халака.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ох, мамочка, неужели я скоро отведаю похлебки из снежных грибов?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Пригмону на Гранитные ключи, что в Седых холмах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12484,'Шашлык из Плети','Фух.$b$bСердце кровью обливается при виде этих несчастных троллей, но спина моя болит еще сильней.$b$bДружок, помоги старому Пригмону, оттащи один из трупов Маку.$b$bЕсли мы их не сожжем в ближайшее время – придется сражаться с ними снова!','Пригмон из Гранитных ключей просит вас отнести мумифицированный труп тролля Маку Фирсену и бросить его в огонь.','Все принес, подруга ?','Вернитесь к Маку Фирсену на Гранитные ключи, что в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Шашлык из Плети',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Фух.$b$bСердце кровью обливается при виде этих несчастных троллей, но спина моя болит еще сильней.$b$bДружок, помоги старому Пригмону, оттащи один из трупов Маку.$b$bЕсли мы их не сожжем в ближайшее время – придется сражаться с ними снова!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Пригмон из Гранитных ключей просит вас отнести мумифицированный труп тролля Маку Фирсену и бросить его в огонь.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Все принес, подруга ?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Маку Фирсену на Гранитные ключи, что в Седых холмах.',`completedtext_loc8`);
