INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (12486,'Быстро, на заставу Бор\'горока!','Поговорите с говорящей с духами Рычеклык на заставе Бор\'горока.','Тебе удалось собрать нужные мне данные, |3-6($C)?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Быстро, на заставу Бор\'горока!',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с говорящей с духами Рычеклык на заставе Бор\'горока.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось собрать нужные мне данные, |3-6($C)?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (12487,'В крепости Завоевателей держи ухо востро!','Явитесь к завоевательнице Кренне в крепости Завоевателей в Седых холмах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В крепости Завоевателей держи ухо востро!',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Явитесь к завоевательнице Кренне в крепости Завоевателей в Седых холмах.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (12488,'Запрос от верховного палача','Хорошо, что я перехватил этот запрос от верховного палача Роса раньше, чем он попал к командиру Агмару. О чем Рос только думает?$B$B<Сержант вскрывает письмо, которое он держит в руках.>$B$B$C, иди узнай, чего там хочет верховный палач.$B$BСледуй по дороге на восток, затем иди через Драконьи Пустоши. Найдешь тропинку, ведущую из пустошей на юго-востока. Город Отрекшихся, Ядозлобь, окажется перед тобой на южном склоне горы.','Поговорите с верховным палачом Росом в Ядозлоби, что в Драконьем Погосте.','Тебе удалось покончить с этой угрозой?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Запрос от верховного палача',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хорошо, что я перехватил этот запрос от верховного палача Роса раньше, чем он попал к командиру Агмару. О чем Рос только думает?$B$B<Сержант вскрывает письмо, которое он держит в руках.>$B$B$C, иди узнай, чего там хочет верховный палач.$B$BСледуй по дороге на восток, затем иди через Драконьи Пустоши. Найдешь тропинку, ведущую из пустошей на юго-востока. Город Отрекшихся, Ядозлобь, окажется перед тобой на южном склоне горы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с верховным палачом Росом в Ядозлоби, что в Драконьем Погосте.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось покончить с этой угрозой?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (12489,'Идите по тропе на запад, пока не дойдете до лагеря, о котором говорил Монти.','Ха! Нечасто встречаешь в джунглях незнакомцев!$B$BТебя прислали эти прислужники друидов, чтобы "остановить меня и то зло, которое я несу?" Ну, удачи в этом нелегком деле!$B$B<Хеминг от души смеется и поглаживает свое ружье.>$B$BДа ладно, я ничего такого и не думал! Если хочешь, присоединяйся к нашей охотничьей компании – конечно, после того, как мы разберемся с этими шелудивыми псами из Торговой Компании. Их тут кругом навалом.') ON DUPLICATE KEY UPDATE `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Идите по тропе на запад, пока не дойдете до лагеря, о котором говорил Монти.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ха! Нечасто встречаешь в джунглях незнакомцев!$B$BТебя прислали эти прислужники друидов, чтобы "остановить меня и то зло, которое я несу?" Ну, удачи в этом нелегком деле!$B$B<Хеминг от души смеется и поглаживает свое ружье.>$B$BДа ладно, я ничего такого и не думал! Если хочешь, присоединяйся к нашей охотничьей компании – конечно, после того, как мы разберемся с этими шелудивыми псами из Торговой Компании. Их тут кругом навалом.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (12490,'Месть Вихьи','Теперь у нас общий враг, |3-6($r)! Мой народ истребили эти квалдиры... мой город почти разрушен! Пришло время мести!$b$bЯ помогла тебе – перебей же жестоких чудовищ, оскверняющих Терзающий Бич! Тебя ждет достойная награда, |3-6($c).','Убейте 6 скадирских моряков, 3 скадирских ткачей туманов и 2 скадирских заклинателей рун по просьбе Вихьи из Святилища Чешуи.','Вернитесь к Вихье в Святилище Чешуи, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Месть Вихьи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь у нас общий враг, |3-6($r)! Мой народ истребили эти квалдиры... мой город почти разрушен! Пришло время мести!$b$bЯ помогла тебе – перебей же жестоких чудовищ, оскверняющих Терзающий Бич! Тебя ждет достойная награда, |3-6($c).',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 6 скадирских моряков, 3 скадирских ткачей туманов и 2 скадирских заклинателей рун по просьбе Вихьи из Святилища Чешуи.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Вихье в Святилище Чешуи, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12491,'Худое варево Худовара','Даже после смерти Корен Худовар не выпустил из рук маленькую фляжку, прижатую к животу. Должно быть, в ней хранится знаменитое худое варево!','Отнесите худое варево Худовара Ипфелькоферу Железному Бочонку в лагерь Хмельного фестиваля возле Стальгорна.','Так это и есть варево Корена Худовара? То самое пиво, которое он хотел во что бы то ни стало выставить на Хмельном фестивале? Ну, наши правила не позволяют принять эту заявку, но из уважения к павшему пивовару я, пожалуй, сделаю глоточек...','Что за грустное лицо? Что-то случилось?','Вернитесь к Ипфелькоферу Железному Бочонку в Дун Морог.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Худое варево Худовара',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Даже после смерти Корен Худовар не выпустил из рук маленькую фляжку, прижатую к животу. Должно быть, в ней хранится знаменитое худое варево!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите худое варево Худовара Ипфелькоферу Железному Бочонку в лагерь Хмельного фестиваля возле Стальгорна.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так это и есть варево Корена Худовара? То самое пиво, которое он хотел во что бы то ни стало выставить на Хмельном фестивале? Ну, наши правила не позволяют принять эту заявку, но из уважения к павшему пивовару я, пожалуй, сделаю глоточек...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что за грустное лицо? Что-то случилось?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ипфелькоферу Железному Бочонку в Дун Морог.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (12492,'Худое варево Худовара','Даже после смерти Корен Худовар не выпустил из рук маленькую фляжку, прижатую к животу. Должно быть, в ней хранится знаменитое худое варево!','Отнесите худое варево Худовара Слухарю Жмухли в лагерь Хмельного фестиваля возле Оргриммара.','Значит, Худовар все-таки сварил свое пиво. Как жаль, что за это он поплатился жизнью...$B$BА, впрочем... Чем не повод выпить?','Вернитесь к Слухарю Жмухли в Дуротар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Худое варево Худовара',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Даже после смерти Корен Худовар не выпустил из рук маленькую фляжку, прижатую к животу. Должно быть, в ней хранится знаменитое худое варево!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите худое варево Худовара Слухарю Жмухли в лагерь Хмельного фестиваля возле Оргриммара.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Значит, Худовар все-таки сварил свое пиво. Как жаль, что за это он поплатился жизнью...$B$BА, впрочем... Чем не повод выпить?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Слухарю Жмухли в Дуротар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (12493,'Тест PvP','Kill me some guys from the other side! Those guys suck! I need to test something, so let\'s just repeat this over and over again. I need to test something, so let\'s just repeat this over and over again. I need to test something, so let\'s just repeat this over and over again. I need to test something, so let\'s just repeat this over and over again. I need to test something, so let\'s just repeat this over and over again. I need to test something, so let\'s just repeat this over and over again.','Убейте 10 противников.','Вернитесь к Test PvP Questgiver на ферму, что в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тест PvP',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Kill me some guys from the other side! Those guys suck! I need to test something, so let\'s just repeat this over and over again. I need to test something, so let\'s just repeat this over and over again. I need to test something, so let\'s just repeat this over and over again. I need to test something, so let\'s just repeat this over and over again. I need to test something, so let\'s just repeat this over and over again. I need to test something, so let\'s just repeat this over and over again.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 противников.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Test PvP Questgiver на ферму, что в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (12494,'УКАЗАТЕЛЬ: приглашение на тренировки по верховой езде (20)') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','УКАЗАТЕЛЬ: приглашение на тренировки по верховой езде (20)',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (12495,'Аудиенция у королевы драконов','Наша атака на Ангратар заставила Плеть поколебаться, но отступать они не торопятся. Они высылают на поле битвы своих ледяных змеев, так что подступиться к самим воротам невозможно. Нужно прекратить нападения ледяных змеев. Но прежде чем осквернить кости древних драконов, нужно испросить дозволения их королевы.$b$bОтправляйся на юго-восток, в храм Драконьего Покоя, и отыщи королеву Алекстразу. Расскажи ей о том, что мы вынуждены сделать, и попроси ее совета.$b$bСтупай, $n!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Аудиенция у королевы драконов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наша атака на Ангратар заставила Плеть поколебаться, но отступать они не торопятся. Они высылают на поле битвы своих ледяных змеев, так что подступиться к самим воротам невозможно. Нужно прекратить нападения ледяных змеев. Но прежде чем осквернить кости древних драконов, нужно испросить дозволения их королевы.$b$bОтправляйся на юго-восток, в храм Драконьего Покоя, и отыщи королеву Алекстразу. Расскажи ей о том, что мы вынуждены сделать, и попроси ее совета.$b$bСтупай, $n!',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`) VALUES (12496,'Аудиенция у королевы драконов','Хотя я знаю, что ты горишь желанием уничтожить армию Плети, противостоящую нам у Врат Гнева, сначала нам надо разобраться с угрозой, висящей в небе. До того, как мы остановим непрекращающиеся налеты ледяных змеев, мы не сможем двигаться дальше.$B$BНо прежде чем мы вторгнемся в умирающие земли драконов, мы должны получить разрешение на это. Отправляйся же в священные залы драконьего племени: в храм Драконьего Покоя. Там найди королеву Алекстразу.$B$BЕзжай сейчас же, $n! На юго-восток, к Драконьему Покою!','Должен ли я дать приказ своим силам прорываться к Молоту Агмара?\n\nИли тебе удалось убить верховного генерала?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Аудиенция у королевы драконов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хотя я знаю, что ты горишь желанием уничтожить армию Плети, противостоящую нам у Врат Гнева, сначала нам надо разобраться с угрозой, висящей в небе. До того, как мы остановим непрекращающиеся налеты ледяных змеев, мы не сможем двигаться дальше.$B$BНо прежде чем мы вторгнемся в умирающие земли драконов, мы должны получить разрешение на это. Отправляйся же в священные залы драконьего племени: в храм Драконьего Покоя. Там найди королеву Алекстразу.$B$BЕзжай сейчас же, $n! На юго-восток, к Драконьему Покою!',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Должен ли я дать приказ своим силам прорываться к Молоту Агмара?\n\nИли тебе удалось убить верховного генерала?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (12497,'Галакронд и армия Плети','На вершине Пагубного Серпантина на плечах воссозданного повелителя штормовых великанов Тиасси восседает верховный некролорд Плети Антиок. Оттуда он командует легионами нежити, работающими день и ночь над выкапыванием тяжеленных костей Галакронда. Если им удастся поднять Галакронда, все твои усилия пойдут прахом.$B$BВ то время как я не могу вызвать полномасштабную ярость красных драконов, чтобы помочь тебе в этом деле, я дам тебе свое благословение. Иди же и поговори с моей управительницей Торастразой.','Поговорите с Торастразой в храме Драконьего Покоя на Драконьем Погосте.','Храбрость смертных не перестает поражать меня. Смерть хватает тебя за горло ледяной хваткой, а в ответ ты бросаешь вызов ее притязаниям! За это вас так любят… и так ненавидят.$B$BХотя красные драконы ведут войну с Малигосом, есть кое-что, в чем мы можем помочь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Галакронд и армия Плети',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На вершине Пагубного Серпантина на плечах воссозданного повелителя штормовых великанов Тиасси восседает верховный некролорд Плети Антиок. Оттуда он командует легионами нежити, работающими день и ночь над выкапыванием тяжеленных костей Галакронда. Если им удастся поднять Галакронда, все твои усилия пойдут прахом.$B$BВ то время как я не могу вызвать полномасштабную ярость красных драконов, чтобы помочь тебе в этом деле, я дам тебе свое благословение. Иди же и поговори с моей управительницей Торастразой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Торастразой в храме Драконьего Покоя на Драконьем Погосте.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Храбрость смертных не перестает поражать меня. Смерть хватает тебя за горло ледяной хваткой, а в ответ ты бросаешь вызов ее притязаниям! За это вас так любят… и так ненавидят.$B$BХотя красные драконы ведут войну с Малигосом, есть кое-что, в чем мы можем помочь.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12498,'На рубиновых крыльях','Используй этот маяк, чтобы послать сигнал покорителю из Драконьего Покоя. Заберись к нему на спину и лети на север, к Покою Галакронда. Когда будешь там, прикажи дракону уничтожить мусорщиков Плети, пытающихся извлечь из земли Галакронда. Очистив эту область, лети к Пагубному Серпантину, что над Покоем Галакронда, чтобы уничтожить верховного некролорда Антиока и добыть косу, которую он использует для контроля над змеями.$B$BСделай это и возвращайся к королеве Алекстразе за подобающей $gтакому герою:такой героине; наградой!$B$B$n, опасайся гниющих штормовых великанов, бродящих по этой местности!','Уничтожь силы Плети у Покоя Галакронда, пока не стало слишком поздно!','Вернитесь к Алекстразе Хранительнице Жизни в Храм Драконьего Покоя, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На рубиновых крыльях',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Используй этот маяк, чтобы послать сигнал покорителю из Драконьего Покоя. Заберись к нему на спину и лети на север, к Покою Галакронда. Когда будешь там, прикажи дракону уничтожить мусорщиков Плети, пытающихся извлечь из земли Галакронда. Очистив эту область, лети к Пагубному Серпантину, что над Покоем Галакронда, чтобы уничтожить верховного некролорда Антиока и добыть косу, которую он использует для контроля над змеями.$B$BСделай это и возвращайся к королеве Алекстразе за подобающей $gтакому герою:такой героине; наградой!$B$B$n, опасайся гниющих штормовых великанов, бродящих по этой местности!',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Уничтожь силы Плети у Покоя Галакронда, пока не стало слишком поздно!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Алекстразе Хранительнице Жизни в Храм Драконьего Покоя, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (12499,'Возвращение в Ангратар','Теперь, когда Антиок убит, а коса находится в наших руках, нападения ледяных змеев на ваши силы в Ангратаре замедлятся. Змеев, что остались еще на Драконьем Погосте, выследят и уничтожат, а их кости возвратят в землю.$B$BПришло время твоей решающей битвы, $n. Возвращайся в крепость Фордрагона и расскажи обо всем верховному лорду Фордрагону.','Поговорите с верховным лордом Болваром Фордрагоном в крепости Фордрагона и расскажите ему о своей победе над силами Плети.','Знай же: все, что было тобою совершено, вело к этому моменту. Без твоих усилий с нами было бы покончено. А теперь встань в караул. Я отправляюсь на поле битвы, чтобы покончить со всем этим!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение в Ангратар',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда Антиок убит, а коса находится в наших руках, нападения ледяных змеев на ваши силы в Ангратаре замедлятся. Змеев, что остались еще на Драконьем Погосте, выследят и уничтожат, а их кости возвратят в землю.$B$BПришло время твоей решающей битвы, $n. Возвращайся в крепость Фордрагона и расскажи обо всем верховному лорду Фордрагону.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с верховным лордом Болваром Фордрагоном в крепости Фордрагона и расскажите ему о своей победе над силами Плети.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Знай же: все, что было тобою совершено, вело к этому моменту. Без твоих усилий с нами было бы покончено. А теперь встань в караул. Я отправляюсь на поле битвы, чтобы покончить со всем этим!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12501,'Тролльский дозор','Расчехляй оружие, |3-6($r). Пора отправляться в дозор!$b$bУ меня под командованием четыре заставы, и они должны оставаться под нашим контролем. Слушай приказ: обойди все четыре и предложи свою помощь тамошним командирам.$b$bНачни с капитана Брендона на юго-востоке отсюда. Когда все закончишь, он направит тебя на следующую заставу.$b$bКогда обойдешь все четыре заставы и окажешь там необходимую помощь, возвращайся ко мне. И помни, чем быстрее исполнишь работу, тем выше будет награда – так что поторопись. Время – деньги!$b$bВсе, выполняй!','Обойдите четыре заставы Серебряного Авангарда, выполните приказы капитанов и возвратитесь к командиру Кунцу на Серебряную заставу с докладом.$b$bЗаставы капитана Брендона и капитана Руперта расположены в Драк\'Сотре, к юго-востоку, застава капитана Гронделя – в Драк\'Агале, прямо на восток, а застава алхимика Финкльштейна – в Хеб\'Валоке, к северу.','Какие новости из наших постов, |3-6($R)?','Вернитесь к командиру Кунцу на Серебряную заставу, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тролльский дозор',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Расчехляй оружие, |3-6($r). Пора отправляться в дозор!$b$bУ меня под командованием четыре заставы, и они должны оставаться под нашим контролем. Слушай приказ: обойди все четыре и предложи свою помощь тамошним командирам.$b$bНачни с капитана Брендона на юго-востоке отсюда. Когда все закончишь, он направит тебя на следующую заставу.$b$bКогда обойдешь все четыре заставы и окажешь там необходимую помощь, возвращайся ко мне. И помни, чем быстрее исполнишь работу, тем выше будет награда – так что поторопись. Время – деньги!$b$bВсе, выполняй!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обойдите четыре заставы Серебряного Авангарда, выполните приказы капитанов и возвратитесь к командиру Кунцу на Серебряную заставу с докладом.$b$bЗаставы капитана Брендона и капитана Руперта расположены в Драк\'Сотре, к юго-востоку, застава капитана Гронделя – в Драк\'Агале, прямо на восток, а застава алхимика Финкльштейна – в Хеб\'Валоке, к северу.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Какие новости из наших постов, |3-6($R)?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру Кунцу на Серебряную заставу, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (12502,'Тролльский дозор: выше знамена!','Слушай, |3-6($c). Это Серебряный Авангард. Наши солдаты будут сражаться до конца и готовы терпеть многие трудности и лишения.$b$bОднако мы понесли очень большие потери, и уже много месяцев нашим воинам не удается как следует выспаться. Все это подрывает их боевой дух, хотя вслух об этом не говорится.$b$bМожет быть, это не так уж и много, но когда наши солдаты видят свое боевое знамя, реющее над полем сражения, это их воодушевляет. Возьми эти знамена и расставь их на пьедесталах в Драк\'Сотре.','По поручению капитана Брендона расставьте знамена Серебряного Авангарда на пьедесталах Драккари в Драк\'Сотре.','Спасибо, друг.\n\nЗнамя – это всего лишь символ, но на поле боя этот символ творит чудеса.\n\nТеперь отправляйся к капитану Руперту. Его пост – у стены, на северо-востоке отсюда.','Вернитесь к капитану Брендону в Драк\'Сотру, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тролльский дозор: выше знамена!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слушай, |3-6($c). Это Серебряный Авангард. Наши солдаты будут сражаться до конца и готовы терпеть многие трудности и лишения.$b$bОднако мы понесли очень большие потери, и уже много месяцев нашим воинам не удается как следует выспаться. Все это подрывает их боевой дух, хотя вслух об этом не говорится.$b$bМожет быть, это не так уж и много, но когда наши солдаты видят свое боевое знамя, реющее над полем сражения, это их воодушевляет. Возьми эти знамена и расставь их на пьедесталах в Драк\'Сотре.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По поручению капитана Брендона расставьте знамена Серебряного Авангарда на пьедесталах Драккари в Драк\'Сотре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо, друг.\n\nЗнамя – это всего лишь символ, но на поле боя этот символ творит чудеса.\n\nТеперь отправляйся к капитану Руперту. Его пост – у стены, на северо-востоке отсюда.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Брендону в Драк\'Сотру, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12503,'Защита заставы','Несмотря на наши значительные успехи в нижней трети Зул\'Драка, нам все равно тяжело сдерживать натиск Плети. Такова жизнь в этом студеном аду.$B$BМоим людям необходима хотя бы какая-то передышка. Если хочешь, можешь им помочь.$B$BТам внизу, во внутреннем дворе, битва в самом разгаре. Иди туда и убей столько приспешников Плети, сколько сможешь, |3-6($c).','По поручению командира Фальштава убейте 10 приспешников Плети во внутреннем дворе Серебряной заставы.','Мы благодарны тебе за помощь. Если бы не ты, мы бы не сумели сдержать натиск нежити.','Может быть, ты $Gмог:могла; бы уничтожить еще несколько?','Вернитесь к командиру Фальштаву на Серебряную заставу, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Защита заставы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Несмотря на наши значительные успехи в нижней трети Зул\'Драка, нам все равно тяжело сдерживать натиск Плети. Такова жизнь в этом студеном аду.$B$BМоим людям необходима хотя бы какая-то передышка. Если хочешь, можешь им помочь.$B$BТам внизу, во внутреннем дворе, битва в самом разгаре. Иди туда и убей столько приспешников Плети, сколько сможешь, |3-6($c).',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По поручению командира Фальштава убейте 10 приспешников Плети во внутреннем дворе Серебряной заставы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мы благодарны тебе за помощь. Если бы не ты, мы бы не сумели сдержать натиск нежити.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Может быть, ты $Gмог:могла; бы уничтожить еще несколько?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру Фальштаву на Серебряную заставу, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12504,'Серебряный Авангард, уходим!','<Сержант быстро просматривает бумаги с приказами, которые вы ему передали, и хмурится.>$B$BСлушай, $gприятель:красавица;, я бы с радостью взял и ушел из этого мрачного места, но ты посмотри, что тут творится. Все мои люди сражаются.$B$BСлушай, раз уж ты все равно здесь, может, сделаешь мне одолжение – войдешь туда и соберешь всех моих солдат?$B$BСкажи, что сержант дал приказ, чтобы все немедленно собрались здесь. Если кто-то нуждается в помощи, помоги им.','Поговорите с 10 солдатами Серебряного Авангарда и скажите им, чтобы они немедленно возвращались к сержанту Метателю Молота к алтарю Шшератуса.','Ну, ладно. Мы соберем остальных и вернемся на заставу.$B$BХотя жалко, что нам приходится уходить так скоро. Мы здесь явно еще не закончили, и, если по правде, у меня нехорошее предчувствие, что этот пророк у алтаря – потенциальный источник немалых бед.','Мне нужно больше, чтобы отчитаться.','Вернитесь к сержанту Метателю Молота к алтарю Шшератуса, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Серебряный Авангард, уходим!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Сержант быстро просматривает бумаги с приказами, которые вы ему передали, и хмурится.>$B$BСлушай, $gприятель:красавица;, я бы с радостью взял и ушел из этого мрачного места, но ты посмотри, что тут творится. Все мои люди сражаются.$B$BСлушай, раз уж ты все равно здесь, может, сделаешь мне одолжение – войдешь туда и соберешь всех моих солдат?$B$BСкажи, что сержант дал приказ, чтобы все немедленно собрались здесь. Если кто-то нуждается в помощи, помоги им.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с 10 солдатами Серебряного Авангарда и скажите им, чтобы они немедленно возвращались к сержанту Метателю Молота к алтарю Шшератуса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну, ладно. Мы соберем остальных и вернемся на заставу.$B$BХотя жалко, что нам приходится уходить так скоро. Мы здесь явно еще не закончили, и, если по правде, у меня нехорошее предчувствие, что этот пророк у алтаря – потенциальный источник немалых бед.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мне нужно больше, чтобы отчитаться.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к сержанту Метателю Молота к алтарю Шшератуса, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12505,'Новый приказ для сержанта Метателя Молота','$C, ты здесь, чтобы нам помогать, правильно? У меня новый приказ для нашего войска, которое сейчас дислоцировано у алтаря Драккари к северу отсюда.$B$BЕго невозможно не заметить. Иди все время прямо по этой дороге и придешь, куда нужно. Найти сержанта Метателя Молота тоже труда не составит.','По поручению командира Кунца доставьте приказ о передислокации сержанту Метателю Молота к алтарю Шшератуса.','В чем дело?','Вернитесь к сержанту Метателю Молота в Хладный разлом, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новый приказ для сержанта Метателя Молота',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$C, ты здесь, чтобы нам помогать, правильно? У меня новый приказ для нашего войска, которое сейчас дислоцировано у алтаря Драккари к северу отсюда.$B$BЕго невозможно не заметить. Иди все время прямо по этой дороге и придешь, куда нужно. Найти сержанта Метателя Молота тоже труда не составит.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По поручению командира Кунца доставьте приказ о передислокации сержанту Метателю Молота к алтарю Шшератуса.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','В чем дело?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к сержанту Метателю Молота в Хладный разлом, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (12506,'Волнения у алтаря Шшератуса','У алтаря бога-змея сейчас неспокойно.$B$BПрисутствие Плети ослабило землю, |3-6($r). Что, в свою очередь, ослабило богов дикой природы.$B$BНам известно, что Драккари этим воспользовались, и теперь творят страшные вещи с богами.$B$BМне нужна достоверная информация. Иди на север, к алтарю Шшератуса. Зайди с заднего входа и попытайся проникнуть в главное святилище. Смотри, слушай, запоминай, а потом возвращайся ко мне с донесением.$B$BИ самое главное, постарайся не попадаться на глаза пророку!','Что ты $Gвидел:видела;, $R?','Храм у алтаря Шшератуса исследован.','Вернитесь к мастеру проклятий Убунго на Серебряную заставу, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Волнения у алтаря Шшератуса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У алтаря бога-змея сейчас неспокойно.$B$BПрисутствие Плети ослабило землю, |3-6($r). Что, в свою очередь, ослабило богов дикой природы.$B$BНам известно, что Драккари этим воспользовались, и теперь творят страшные вещи с богами.$B$BМне нужна достоверная информация. Иди на север, к алтарю Шшератуса. Зайди с заднего входа и попытайся проникнуть в главное святилище. Смотри, слушай, запоминай, а потом возвращайся ко мне с донесением.$B$BИ самое главное, постарайся не попадаться на глаза пророку!',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что ты $Gвидел:видела;, $R?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Храм у алтаря Шшератуса исследован.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру проклятий Убунго на Серебряную заставу, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (12507,'Странная настойка','Вернитесь к мастеру проклятий Убунго на Мертвые поля, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Странная настойка',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру проклятий Убунго на Мертвые поля, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12508,'Зачистка территории','Я случайно подслушала, о чем вы говорили с сержантом. Но это не отменяет работы, которую надо доделать здесь.$B$BСможешь помочь нам прикончить хотя бы нескольких из приверженцев Шшератуса?','По поручению капрала Маги у алтаря Шшератуса убейте 10 приверженцев Шшератуса – воителей Шшератуса, жрецов Шшератуса или факиров драккари.','Как насчет убийства еще нескольких?','Вернитесь к капралу Маге к алтарю Шшератуса, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зачистка территории',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я случайно подслушала, о чем вы говорили с сержантом. Но это не отменяет работы, которую надо доделать здесь.$B$BСможешь помочь нам прикончить хотя бы нескольких из приверженцев Шшератуса?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По поручению капрала Маги у алтаря Шшератуса убейте 10 приверженцев Шшератуса – воителей Шшератуса, жрецов Шшератуса или факиров драккари.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как насчет убийства еще нескольких?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капралу Маге к алтарю Шшератуса, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (12509,'Тролльский дозор: сила духа','А вот, наконец, и дозорный!$b$bСразу введу тебя в курс дела, |3-6($r). В этой кампании мы потеряли многих доблестных воинов, так что нам спешно пришлось набирать новичков.$b$bПоследняя битва была жестокой, и, как оказалось, многие из новобранцев были просто не готовы сражаться с таким сильным противником. У нас впереди еще много сражений, и мне нужно, чтобы мои солдаты были готовы немедленно выполнить любой приказ.$b$bБольше всего на свете я ненавижу трусость. Может быть, ты сумеешь помочь новобранцам найти в себе мужество воевать дальше.','По поручению капитана Руперта из Драк\'Сотры поднимите боевой дух рекрутов Серебряного ордена.','Ты замечательно справился, $C. И как раз очень вовремя. Мне пришло донесение, что противник готовит контратаку.\n\nТебе пора идти дальше. Следующий форт – на северо-востоке, рядом с Колизеем. Капитан Грондель будет ждать тебя там.','Вернитесь к капитану Руперту в Драк\'Сотру, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тролльский дозор: сила духа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А вот, наконец, и дозорный!$b$bСразу введу тебя в курс дела, |3-6($r). В этой кампании мы потеряли многих доблестных воинов, так что нам спешно пришлось набирать новичков.$b$bПоследняя битва была жестокой, и, как оказалось, многие из новобранцев были просто не готовы сражаться с таким сильным противником. У нас впереди еще много сражений, и мне нужно, чтобы мои солдаты были готовы немедленно выполнить любой приказ.$b$bБольше всего на свете я ненавижу трусость. Может быть, ты сумеешь помочь новобранцам найти в себе мужество воевать дальше.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По поручению капитана Руперта из Драк\'Сотры поднимите боевой дух рекрутов Серебряного ордена.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты замечательно справился, $C. И как раз очень вовремя. Мне пришло донесение, что противник готовит контратаку.\n\nТебе пора идти дальше. Следующий форт – на северо-востоке, рядом с Колизеем. Капитан Грондель будет ждать тебя там.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Руперту в Драк\'Сотру, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12510,'Совершенные элементальные флюиды','Замечательно. Если добавить их в настойку, флюиды ослабят ее действие, не уничтожив саму ее полностью.$B$BДа, и еще кое-что...','Где совершенные элементальные флюиды?','Вернитесь к мастеру проклятий Убунго на Серебряную заставу, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Совершенные элементальные флюиды',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Замечательно. Если добавить их в настойку, флюиды ослабят ее действие, не уничтожив саму ее полностью.$B$BДа, и еще кое-что...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Где совершенные элементальные флюиды?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру проклятий Убунго на Серебряную заставу, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (12511,'У холмов есть не только глаза') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','У холмов есть не только глаза',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12512,'Спасти всех','Ну, наконец-то. Я уж думал, что нам никого не пришлют.$b$bСлушай, |3-6($r). Нужна помощь. Нам пришлось отступать, Плеть выбила нас из Драк\'Сотры. Никто не знает, откуда они появились...$b$bУ нас сейчас каждый солдат на счету, а лучшие из лучших еще не вернулись из боя.$b$bИди на развалины, где сражение уже закончилось, разыщи наших раненых, перевяжи им раны и приведи сюда ко мне.$B$BПрочеши всю Драк\'Сотру и найди их! Далеко они уйти не могли...','Разыщите рыцаря Ламуфа, рыцаря Джонатана и рыцаря Жозефину. Перевяжите их раны бинтами и проводите к доктору Роджерсу в Драк\'Сотру.','Ты $Gспас:спасла; наших ветеранов, $N?','Вернитесь к Доктору Роджерсу в Драк\'Сотру, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спасти всех',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну, наконец-то. Я уж думал, что нам никого не пришлют.$b$bСлушай, |3-6($r). Нужна помощь. Нам пришлось отступать, Плеть выбила нас из Драк\'Сотры. Никто не знает, откуда они появились...$b$bУ нас сейчас каждый солдат на счету, а лучшие из лучших еще не вернулись из боя.$b$bИди на развалины, где сражение уже закончилось, разыщи наших раненых, перевяжи им раны и приведи сюда ко мне.$B$BПрочеши всю Драк\'Сотру и найди их! Далеко они уйти не могли...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите рыцаря Ламуфа, рыцаря Джонатана и рыцаря Жозефину. Перевяжите их раны бинтами и проводите к доктору Роджерсу в Драк\'Сотру.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gспас:спасла; наших ветеранов, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Доктору Роджерсу в Драк\'Сотру, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12513,'Милая шляпка...','Тебе нравится моя шляпа? Да, она и впрямь необычная. Настоящий антиквариат... теперь уже никто и не помнит, как шить такие головные уборы.$B$BЭх, когда я был молод и горяч, я обещал отдать ее тому, кто сможет одолеть меня в битве. Многие пытались выиграть эту шляпу... но, как видишь, она все еще на мне. $B$BУвы, времена эти давно в прошлом. Старый я стал; пью да рыбачу, но больше уже не дерусь.','Сам того не желая, Дон Карлос сподвиг вас сразиться с ним молодым в Старом Хилсбраде. Принесите ему шляпу Дона Карлоса в доказательство вашей победы. Он будет ждать вас в Танарисе.','Моя ... моя шляпа! Так что ... это $Gбыл:была; ты. Я так и думал. Старые шрамы болели, когда вы приближались, но ... такие молодые! Вы совсем не изменились!$B$BНу ... теперь ты знаешь мой секрет. Я был избит ... один раз. Вот: возьми эту шляпу взамен моей. Вы более чем заработали это.','В те дни я был непобедим... горд и справедлив. Ни один претендент никогда не выиграл эту прекрасную шляпу...','Вернитесь к Дону Карлосу в Танарис.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Милая шляпка...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе нравится моя шляпа? Да, она и впрямь необычная. Настоящий антиквариат... теперь уже никто и не помнит, как шить такие головные уборы.$B$BЭх, когда я был молод и горяч, я обещал отдать ее тому, кто сможет одолеть меня в битве. Многие пытались выиграть эту шляпу... но, как видишь, она все еще на мне. $B$BУвы, времена эти давно в прошлом. Старый я стал; пью да рыбачу, но больше уже не дерусь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сам того не желая, Дон Карлос сподвиг вас сразиться с ним молодым в Старом Хилсбраде. Принесите ему шляпу Дона Карлоса в доказательство вашей победы. Он будет ждать вас в Танарисе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Моя ... моя шляпа! Так что ... это $Gбыл:была; ты. Я так и думал. Старые шрамы болели, когда вы приближались, но ... такие молодые! Вы совсем не изменились!$B$BНу ... теперь ты знаешь мой секрет. Я был избит ... один раз. Вот: возьми эту шляпу взамен моей. Вы более чем заработали это.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','В те дни я был непобедим... горд и справедлив. Ни один претендент никогда не выиграл эту прекрасную шляпу...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дону Карлосу в Танарис.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (12514,'Грибная добавка','Теперь нам нужно придумать, как испортить настойку. Нужна особая добавка, чтобы, когда пророк выпьет смесь, его сила иссякла.$B$BВ Драк\'Агале, что на востоке отсюда, произрастает один грибочек... местные называют его гриб-дурман. Думаю, это именно то, что нам нужно.$B$BПринеси мне побольше этих грибов. Мы подмешаем их в настойку, и у каждого, кто его выпьет, помутится разум.','<Мастер проклятий одобрительно кивает.>$B$BДавай сюда эти грибы, я смешаю их с напитком и элементальными флюидами.','Вернитесь к мастеру проклятий Убунго на Серебряную заставу, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Грибная добавка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь нам нужно придумать, как испортить настойку. Нужна особая добавка, чтобы, когда пророк выпьет смесь, его сила иссякла.$B$BВ Драк\'Агале, что на востоке отсюда, произрастает один грибочек... местные называют его гриб-дурман. Думаю, это именно то, что нам нужно.$B$BПринеси мне побольше этих грибов. Мы подмешаем их в настойку, и у каждого, кто его выпьет, помутится разум.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Мастер проклятий одобрительно кивает.>$B$BДавай сюда эти грибы, я смешаю их с напитком и элементальными флюидами.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру проклятий Убунго на Серебряную заставу, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12515,'Милая шляпка...','Тебе нравится моя шляпа? Да, она и впрямь необычная. Настоящий антиквариат... теперь уже никто и не помнит, как шить такие головные уборы.$B$BЭх, когда я был молод и горяч, я обещал отдать ее тому, кто сможет одолеть меня в битве. Многие пытались выиграть эту шляпу... но, как видишь, она все еще на мне. $B$BУвы, времена эти давно в прошлом. Старый я стал; пью да рыбачу, но больше уже не дерусь.','Сам того не желая, Дон Карлос сподвиг вас сразиться с ним молодым в Старом Хилсбраде. Принесите ему шляпу Дона Карлоса в доказательство вашей победы. Он будет ждать вас в Танарисе.','Моя ... моя шляпа! Так что ... это $Gбыл:была; ты. Я так и думал. Старые шрамы болели, когда вы приближались, но ... такие молодые! Вы совсем не изменились!$B$BНу ... теперь ты знаешь мой секрет. Я был избит ... один раз. Вот: возьми эту шляпу взамен моей. Вы более чем заработали это.','Ах, когда-то я был непобедим... и горжусь этим. Никому не удалось выиграть у меня это великолепную шляпу.','Вернитесь к Дону Карлосу в Танарис.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Милая шляпка...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе нравится моя шляпа? Да, она и впрямь необычная. Настоящий антиквариат... теперь уже никто и не помнит, как шить такие головные уборы.$B$BЭх, когда я был молод и горяч, я обещал отдать ее тому, кто сможет одолеть меня в битве. Многие пытались выиграть эту шляпу... но, как видишь, она все еще на мне. $B$BУвы, времена эти давно в прошлом. Старый я стал; пью да рыбачу, но больше уже не дерусь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сам того не желая, Дон Карлос сподвиг вас сразиться с ним молодым в Старом Хилсбраде. Принесите ему шляпу Дона Карлоса в доказательство вашей победы. Он будет ждать вас в Танарисе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Моя ... моя шляпа! Так что ... это $Gбыл:была; ты. Я так и думал. Старые шрамы болели, когда вы приближались, но ... такие молодые! Вы совсем не изменились!$B$BНу ... теперь ты знаешь мой секрет. Я был избит ... один раз. Вот: возьми эту шляпу взамен моей. Вы более чем заработали это.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ах, когда-то я был непобедим... и горжусь этим. Никому не удалось выиграть у меня это великолепную шляпу.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дону Карлосу в Танарис.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12516,'Хорошенького понемножку','Вот, я изменил состав напитка. Теперь, когда пророк его выпьет, он не только утратит часть своей силы, но еще и слегка помутится рассудком под воздействием гриба.$B$BВо всяком случае, теоретически.$B$BКак заставить его выпить зелье? Да просто швырни ему фляжку. Он перехватит ее и выпьет с присущей ему самонадеянностью.$B$BУбей его, |3-6($c), иначе для Серебряного Авангарда все закончится очень печально и страшно.','Все кончено?$B$BСработало ли измененное моджо?$B$BТы $Gотомстил:отомстила; Шшератусу, убив его пророка?','Вернитесь к мастеру проклятий Убунго на Серебряную заставу, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хорошенького понемножку',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот, я изменил состав напитка. Теперь, когда пророк его выпьет, он не только утратит часть своей силы, но еще и слегка помутится рассудком под воздействием гриба.$B$BВо всяком случае, теоретически.$B$BКак заставить его выпить зелье? Да просто швырни ему фляжку. Он перехватит ее и выпьет с присущей ему самонадеянностью.$B$BУбей его, |3-6($c), иначе для Серебряного Авангарда все закончится очень печально и страшно.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Все кончено?$B$BСработало ли измененное моджо?$B$BТы $Gотомстил:отомстила; Шшератусу, убив его пророка?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру проклятий Убунго на Серебряную заставу, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (12517,'Карты Новолуния: колода Разбойников','Теперь, когда вы собрали все карты колоды Разбойников, вы видите, как сверху появляется еще одна карта. На ней нарисован предсказатель, который глядит прямо на вас, независимо от того, под каким углом вы смотрите на изображение.$b$bВы чувствуете, что с помощью этой карты можно кого-то призвать.','Призовите предсказателя судьбы с Ярмарки Новолуния и отдайте ему колоду Разбойников.','Вернитесь к предсказательнице ярмарки Новолуния.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Карты Новолуния: колода Разбойников',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда вы собрали все карты колоды Разбойников, вы видите, как сверху появляется еще одна карта. На ней нарисован предсказатель, который глядит прямо на вас, независимо от того, под каким углом вы смотрите на изображение.$b$bВы чувствуете, что с помощью этой карты можно кого-то призвать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Призовите предсказателя судьбы с Ярмарки Новолуния и отдайте ему колоду Разбойников.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к предсказательнице ярмарки Новолуния.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (12518,'Карты Новолуния: колода Магов','Теперь, когда вы собрали все карты колоды Магов, вы видите, как сверху появляется еще одна карта. На ней нарисован предсказатель, который глядит прямо на вас, независимо от того, под каким углом вы смотрите на изображение.$b$bВы чувствуете, что с помощью этой карты можно кого-то призвать.','Призовите предсказателя судьбы с Ярмарки Новолуния и отдайте ему колоду Магов.','Вернитесь к предсказательнице ярмарки Новолуния.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Карты Новолуния: колода Магов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда вы собрали все карты колоды Магов, вы видите, как сверху появляется еще одна карта. На ней нарисован предсказатель, который глядит прямо на вас, независимо от того, под каким углом вы смотрите на изображение.$b$bВы чувствуете, что с помощью этой карты можно кого-то призвать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Призовите предсказателя судьбы с Ярмарки Новолуния и отдайте ему колоду Магов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к предсказательнице ярмарки Новолуния.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12519,'Тролльский дозор: сбор медальонов','Посмотри на меня, |3-6($r). Я похож на кого-то, у кого есть время строчить донесения?$b$bЯ тут убиваюсь, защищаю наш пост от паршивой Плети, а меня еще пытаются загрузить идиотской бумажной работой!$b$b<Вздыхает.> Хотя что толку роптать? Все равно ведь придется писать донесение начальству, сколько было убито троллей в последнем бою. Начальство требует – надо делать.$b$bНе желаешь помочь? Иди собери все медальоны с убитых троллей, какие сумеешь найти. Сколько их будет, столько мы и запишем.','Принесите капитану Гронделю к Колизею в Драк\'Агале 7 медальонов Драккари, снятых с убитых троллей Драккари.','Вот и славно!\n\nТы мне очень помог, сэкономил мне кучу времени. Большое спасибо. Я обязательно упомяну о твоей верной службе, когда буду писать донесение.\n\nА теперь отправляйся на запад, к Финкльштейну. Он уже наверняка тебя ждет.','Ты $Gпринес:принесла; мне медальоны, |3-6($R)?','Вернитесь к капитану Гронделю в Амфитеатр Страданий, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тролльский дозор: сбор медальонов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Посмотри на меня, |3-6($r). Я похож на кого-то, у кого есть время строчить донесения?$b$bЯ тут убиваюсь, защищаю наш пост от паршивой Плети, а меня еще пытаются загрузить идиотской бумажной работой!$b$b<Вздыхает.> Хотя что толку роптать? Все равно ведь придется писать донесение начальству, сколько было убито троллей в последнем бою. Начальство требует – надо делать.$b$bНе желаешь помочь? Иди собери все медальоны с убитых троллей, какие сумеешь найти. Сколько их будет, столько мы и запишем.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите капитану Гронделю к Колизею в Драк\'Агале 7 медальонов Драккари, снятых с убитых троллей Драккари.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот и славно!\n\nТы мне очень помог, сэкономил мне кучу времени. Большое спасибо. Я обязательно упомяну о твоей верной службе, когда буду писать донесение.\n\nА теперь отправляйся на запад, к Финкльштейну. Он уже наверняка тебя ждет.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gпринес:принесла; мне медальоны, |3-6($R)?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Гронделю в Амфитеатр Страданий, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (12520,'Охота на люторогов: проверка','Ничто не остановит старину Хеминга, если он решил поохотиться на самых крупных зверей низины Шолазар. В джунглях к северо-западу от лагеря водятся груборогие лютороги. Если ты, $gпарень:подружка;, отважишься встретиться с люторогом лицом к лицу, это докажет, что ты и вправду можешь участвовать в экспедиции.','Убейте 15 груборогих люторогов и вернитесь в лагерь Эрнестуэя к Хемингу Эрнестуэю.','Вернитесь к Хемингу Эрнестуэю в Лагерь Эрнестуэя, что в Низине Шолазар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота на люторогов: проверка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ничто не остановит старину Хеминга, если он решил поохотиться на самых крупных зверей низины Шолазар. В джунглях к северо-западу от лагеря водятся груборогие лютороги. Если ты, $gпарень:подружка;, отважишься встретиться с люторогом лицом к лицу, это докажет, что ты и вправду можешь участвовать в экспедиции.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 15 груборогих люторогов и вернитесь в лагерь Эрнестуэя к Хемингу Эрнестуэю.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хемингу Эрнестуэю в Лагерь Эрнестуэя, что в Низине Шолазар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (12521,'Куда запропастился Хеминг Эрнестуэй?','Ну да, Хеминг здесь. Он в своем лагере: отправляйся на запад к реке, и скоро его увидишь. И заклинаю тебя именем света, друг, пусть он пришлет кого-нибудь, чтобы вытащить меня отсюда!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Куда запропастился Хеминг Эрнестуэй?',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну да, Хеминг здесь. Он в своем лагере: отправляйся на запад к реке, и скоро его увидишь. И заклинаю тебя именем света, друг, пусть он пришлет кого-нибудь, чтобы вытащить меня отсюда!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12522,'Нужен двигатель – найдем двигатель!','Веслекс Вездеключ из лагеря Эрнестуэя просит вас принести ему мотор для ветролета.','Сюда… сюда его ставь… Осторожнее! Если этот расколотишь, у нас будут серьезные проблемы! А теперь посмотрим, что я могу сделать…','Ну как, удалось раздобыть двигатель? Я только что узнал: верховный маг, который финансировал экспедицию, начинает нервничать...','Вернитесь к Веслексу Вездеключу в Лагерь Эрнестуэя, что в Низине Шолазар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нужен двигатель – найдем двигатель!',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Веслекс Вездеключ из лагеря Эрнестуэя просит вас принести ему мотор для ветролета.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сюда… сюда его ставь… Осторожнее! Если этот расколотишь, у нас будут серьезные проблемы! А теперь посмотрим, что я могу сделать…',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как, удалось раздобыть двигатель? Я только что узнал: верховный маг, который финансировал экспедицию, начинает нервничать...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Веслексу Вездеключу в Лагерь Эрнестуэя, что в Низине Шолазар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12523,'Есть детали? – Тащи сюда!','Думаю, немного работы – и этого вполне хватит. Бедный мой ветролет, он скоро станет больше похож на крошшер Торговой Компании… Бедненький мой, придется подождать, пока мы не доберемся до Даларана – уж там-то я приведу тебя в порядок, как положено…','Ну как, детали есть?','Вернитесь к Веслексу Вездеключу в Лагерь Эрнестуэя, что в Низине Шолазар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Есть детали? – Тащи сюда!',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Думаю, немного работы – и этого вполне хватит. Бедный мой ветролет, он скоро станет больше похож на крошшер Торговой Компании… Бедненький мой, придется подождать, пока мы не доберемся до Даларана – уж там-то я приведу тебя в порядок, как положено…',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как, детали есть?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Веслексу Вездеключу в Лагерь Эрнестуэя, что в Низине Шолазар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12524,'Это приостановит деятельность Компании; но я боюсь, что они пришлют сюда новых рабочих. Попробуем закончить все наши дела здесь как можно скорее.','Тебе удалось объяснить этим мерзавцам, что с нами не шутят?','Вернитесь к Дебаар в Лагерь Эрнестуэя, что в Низине Шолазар.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это приостановит деятельность Компании; но я боюсь, что они пришлют сюда новых рабочих. Попробуем закончить все наши дела здесь как можно скорее.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось объяснить этим мерзавцам, что с нами не шутят?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дебаар в Лагерь Эрнестуэя, что в Низине Шолазар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (12525,'Сотри ухмылку с его лица','Убейте штейгера Хитрохмыла и его телохранителя Мясного Пирога, а затем вернитесь к Дебаар в лагерь Эрнестуэя.','Вернитесь к Дебаар в Лагерь Эрнестуэя, что в Низине Шолазар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сотри ухмылку с его лица',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте штейгера Хитрохмыла и его телохранителя Мясного Пирога, а затем вернитесь к Дебаар в лагерь Эрнестуэя.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дебаар в Лагерь Эрнестуэя, что в Низине Шолазар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (12526,'Охота на люторогов: погоня','Что ж, значит, решено. Нам надо найти этого местного мудреца и поговорить с ним. Правда, навряд ли он с готовностью предоставит свои услуги...$B$BМне говорили, он живет неподалеку от Скелета Нозронна – это на юге, на том берегу реки. Разыщи его, представься и спроси, что он потребует за то, чтобы помочь нам разыскать этого патриарха люторогов.','Поговорите с Оракулом Су-рамом у Скелета Нозронна.','Что привело тебя к обители Су-рама?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота на люторогов: погоня',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что ж, значит, решено. Нам надо найти этого местного мудреца и поговорить с ним. Правда, навряд ли он с готовностью предоставит свои услуги...$B$BМне говорили, он живет неподалеку от Скелета Нозронна – это на юге, на том берегу реки. Разыщи его, представься и спроси, что он потребует за то, чтобы помочь нам разыскать этого патриарха люторогов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Оракулом Су-рамом у Скелета Нозронна.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что привело тебя к обители Су-рама?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (12527,'Прожорливые твари','Мой хозяин, Финкльштейн, сейчас в святилище у Хеб\'Валока, что на северо-западе от дороги к алтарю Шшератуса. Он готовит сыворотку правды, и для этого ему понадобились кристаллы василиска.$B$BК счастью для нас, на востоке от Драк\'Агала как раз водятся василиски.$B$BНалови зул\'дракских крыс и скорми их этим тварям. После пяти крыс василиски становятся сытыми, мирными и послушными – тогда у них можно спокойно забрать кристаллы.$B$BНе убивай василисков – иначе ты не соберешь ни одного целого кристалла.','Принесите 5 кристаллов василиска алхимику Финкльштейну в святилище в Хеб\'Валоке.','Вернитесь к алхимику Финкльштейну в святилище у Хеб\'Валока.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прожорливые твари',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мой хозяин, Финкльштейн, сейчас в святилище у Хеб\'Валока, что на северо-западе от дороги к алтарю Шшератуса. Он готовит сыворотку правды, и для этого ему понадобились кристаллы василиска.$B$BК счастью для нас, на востоке от Драк\'Агала как раз водятся василиски.$B$BНалови зул\'дракских крыс и скорми их этим тварям. После пяти крыс василиски становятся сытыми, мирными и послушными – тогда у них можно спокойно забрать кристаллы.$B$BНе убивай василисков – иначе ты не соберешь ни одного целого кристалла.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 5 кристаллов василиска алхимику Финкльштейну в святилище в Хеб\'Валоке.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к алхимику Финкльштейну в святилище у Хеб\'Валока.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (12528,'Подыграть несложно','Найдите верховного шамана Ракжака на холме Бешеного Сердца и скажите, что вы – его новый "раб".') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подыграть несложно',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите верховного шамана Ракжака на холме Бешеного Сердца и скажите, что вы – его новый "раб".',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12529,'Раб охотника на обезьян','Думаешь, ты такой великий охотник, да? Ты не из племени Бешеного Сердца, ты ничего не смыслишь в охоте. $B$BГорегек – великий охотник на обезьян. Он может убить столько, что когтей не хватит сосчитать. $B$BПойдешь с Горегеком, будешь охотиться на барабанчей на востоке. Ты – $gраб:рабыня;, |3-6($r). Горегек говорит, ты делаешь.','Убейте 8 покорных барабанчей и 6 лютых барабанчей по просьбе верховного шамана Ракжака, живущего на холме Бешеного Сердца.$B$BЕсли вы потеряете кандалы Горегека, поговорите со старейшиной Харкеком на холме Бешеного Сердца.','Ты до сих пор $Gживой:живая;? И барабанчи тебя не задрали?$B$BНаверное, они сейчас просто сыты.','Вернитесь к верховному шаману Ракжаку на Холм Бешеного Сердца, что в Низине Шолазар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Раб охотника на обезьян',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Думаешь, ты такой великий охотник, да? Ты не из племени Бешеного Сердца, ты ничего не смыслишь в охоте. $B$BГорегек – великий охотник на обезьян. Он может убить столько, что когтей не хватит сосчитать. $B$BПойдешь с Горегеком, будешь охотиться на барабанчей на востоке. Ты – $gраб:рабыня;, |3-6($r). Горегек говорит, ты делаешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 покорных барабанчей и 6 лютых барабанчей по просьбе верховного шамана Ракжака, живущего на холме Бешеного Сердца.$B$BЕсли вы потеряете кандалы Горегека, поговорите со старейшиной Харкеком на холме Бешеного Сердца.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты до сих пор $Gживой:живая;? И барабанчи тебя не задрали?$B$BНаверное, они сейчас просто сыты.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному шаману Ракжаку на Холм Бешеного Сердца, что в Низине Шолазар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12530,'Вопли барабанчат','Слушай, $gраб:рабыня;!$B$BРакжак хочет, чтобы я присмотрел за тобой, пока буду охотиться на барабанчей. Но я сегодня щедр: я позволю и тебе убить нескольких, только не путайся под ногами у Горегека!$B$BРакжак еще не знает: Горегек выследил их большую и злобную мамашу. Мы идем к логову барабанчей: слегка потыкаем в барабанчат, и ты увидишь, она мигом примчится! $B$B<Горегек радостно потирает руки.>','Горегек дал вам прут для барабанчат: если потыкать их этим прутом, то на их крики из укрытия появится предводительница стаи барабанчей. Убейте предводительницу стаи и расскажите об этом верховному шаману Ракжаку на холме Бешеного Сердца.$B$BЕсли вы потеряете кандалы Горегека, поговорите со старейшиной Харкеком на холме Бешеного Сердца.','Что тебе $Gраб:рабыня;?','Вернитесь к верховному шаману Ракжаку на Холм Бешеного Сердца, что в Низине Шолазар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вопли барабанчат',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слушай, $gраб:рабыня;!$B$BРакжак хочет, чтобы я присмотрел за тобой, пока буду охотиться на барабанчей. Но я сегодня щедр: я позволю и тебе убить нескольких, только не путайся под ногами у Горегека!$B$BРакжак еще не знает: Горегек выследил их большую и злобную мамашу. Мы идем к логову барабанчей: слегка потыкаем в барабанчат, и ты увидишь, она мигом примчится! $B$B<Горегек радостно потирает руки.>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Горегек дал вам прут для барабанчат: если потыкать их этим прутом, то на их крики из укрытия появится предводительница стаи барабанчей. Убейте предводительницу стаи и расскажите об этом верховному шаману Ракжаку на холме Бешеного Сердца.$B$BЕсли вы потеряете кандалы Горегека, поговорите со старейшиной Харкеком на холме Бешеного Сердца.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что тебе $Gраб:рабыня;?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному шаману Ракжаку на Холм Бешеного Сердца, что в Низине Шолазар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (12531,'Подземная угроза','Разыщите Серфекса под песками южной реки и принесите его коготь верховному шаману Ракжаку на холм Бешеного Сердца.$B$BЕсли вы потеряете кусок мела Дажика, поговорите со Старейшиной Харкеком на холме Бешеного Сердца.','Вернитесь к верховному шаману Ракжаку на Холм Бешеного Сердца, что в Низине Шолазар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подземная угроза',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите Серфекса под песками южной реки и принесите его коготь верховному шаману Ракжаку на холм Бешеного Сердца.$B$BЕсли вы потеряете кусок мела Дажика, поговорите со Старейшиной Харкеком на холме Бешеного Сердца.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному шаману Ракжаку на Холм Бешеного Сердца, что в Низине Шолазар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12532,'Побег из курятника','Глупый Горегек вломился в курятник и выпустил на волю всех куриц!$B$BОни там, за холмом. Верни нам наших куриц!$B$B<Старейшина Харкек отсылает вас прочь>','Поймайте 12 сбежавших куриц для старейшины Харкека.$B$BЕсли вы потеряете кусок мела Дажика, поговорите со старейшиной Харкеком на холме Бешеного Сердца.','Ты ловишь куриц?','Вернитесь к старейшине Харкеку на Холм Бешеного Сердца, что в Низине Шолазар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Побег из курятника',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Глупый Горегек вломился в курятник и выпустил на волю всех куриц!$B$BОни там, за холмом. Верни нам наших куриц!$B$B<Старейшина Харкек отсылает вас прочь>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поймайте 12 сбежавших куриц для старейшины Харкека.$B$BЕсли вы потеряете кусок мела Дажика, поговорите со старейшиной Харкеком на холме Бешеного Сердца.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты ловишь куриц?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старейшине Харкеку на Холм Бешеного Сердца, что в Низине Шолазар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12533,'Ученик охотника на ос','Убейте 6 ос Сапфирного Улья и 9 рабочих Сапфирного улья для шамана Ракжака, живущего на холме Бешеного Сердца.$B$BЕсли вы потеряете кусок мела Дажика, поговорите со старейшиной Харкеком на холме Бешеного Сердца.','Теперь ты умеешь охотиться?','Вернитесь к верховному шаману Ракжаку на Холм Бешеного Сердца, что в Низине Шолазар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ученик охотника на ос',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 6 ос Сапфирного Улья и 9 рабочих Сапфирного улья для шамана Ракжака, живущего на холме Бешеного Сердца.$B$BЕсли вы потеряете кусок мела Дажика, поговорите со старейшиной Харкеком на холме Бешеного Сердца.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Теперь ты умеешь охотиться?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному шаману Ракжаку на Холм Бешеного Сердца, что в Низине Шолазар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12534,'Матка Сапфирового Улья','Принесите жало матки Сапфирного Улья верховному шаману Ракжаку, обитающему на холме Бешеного Сердца.$B$BЕсли вы потеряете кусок мела Дажика, поговорите со старейшиной Харкеком на холме Бешеного Сердца.','От тебя воняет осами.','Вернитесь к верховному шаману Ракжаку на Холм Бешеного Сердца, что в Низине Шолазар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Матка Сапфирового Улья',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите жало матки Сапфирного Улья верховному шаману Ракжаку, обитающему на холме Бешеного Сердца.$B$BЕсли вы потеряете кусок мела Дажика, поговорите со старейшиной Харкеком на холме Бешеного Сердца.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','От тебя воняет осами.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному шаману Ракжаку на Холм Бешеного Сердца, что в Низине Шолазар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (12535,'Кристаллы силы','Верховный шаман Ракжак с холма Бешеного Сердца хочет, чтобы вы принесли ему 8 кристаллов Небесного Пути.','Вернитесь к верховному шаману Ракжаку на Холм Бешеного Сердца, что в Низине Шолазар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кристаллы силы',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верховный шаман Ракжак с холма Бешеного Сердца хочет, чтобы вы принесли ему 8 кристаллов Небесного Пути.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному шаману Ракжаку на Холм Бешеного Сердца, что в Низине Шолазар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (12536,'Трудная поездка','Оседлайте пойманного кроколиска и отправляйтесь к убежищу Шепота Тумана; затем обратитесь к Зепику за дальнейшими указаниями.$B$BЕсли вы потеряете охотничий рог Зепика, поговорите со старейшиной Харкеком на холме Бешеного Сердца.','Зепику говорят, что ты хороший охотник, потому что ты не Бешеное Сердце.','Отправляйтесь к убежищу Шепота Тумана.','Поговорите с Зепиком Охотником на Горлоков. Если Зепика нет рядом, его можно позвать, используя охотничий рог Зепика.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Трудная поездка',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Оседлайте пойманного кроколиска и отправляйтесь к убежищу Шепота Тумана; затем обратитесь к Зепику за дальнейшими указаниями.$B$BЕсли вы потеряете охотничий рог Зепика, поговорите со старейшиной Харкеком на холме Бешеного Сердца.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Зепику говорят, что ты хороший охотник, потому что ты не Бешеное Сердце.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Отправляйтесь к убежищу Шепота Тумана.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Зепиком Охотником на Горлоков. Если Зепика нет рядом, его можно позвать, используя охотничий рог Зепика.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (12537,'Молния все-таки бьет в то же место','Так вот, эти кристаллические штуки...$B$BДлинноязыкие их используют, чтобы давать силу алтарям дождя. Зепик не знает, как это работает, зато Зепик знает, что если взять не те кристаллы, облака и дождь сойдут с ума!$B$BЗепик пытался пробраться к одному из алтарей, но все пошло не так. Зато если пойти вдвоем, должно получиться!$B$BНадо взять кристаллы, поставить их на большую штуку вроде каменной колонны, а потом разбить их, чтобы выпустить силу. Зепик точно не знает, что тогда случится, поэтому Зепик первым не пойдет.','Зепик хочет, чтобы вы разрушили кристаллы Небесного Пути перед алтарем Шепота Тумана.$B$BЕсли вы потеряете охотничий рог Зепика, поговорите со старейшиной Харкеком на холме Бешеного Сердца.','Зепик думает, с партнером такое получается лучше. Для того, кто не из племени Бешенного Сердца, ты $Gсилен:сильна;.','Диверсия в святилище Шепота Тумана','Поговорите с Зепиком Охотником на Горлоков. Если Зепика нет рядом, его можно позвать, используя охотничий рог Зепика.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Молния все-таки бьет в то же место',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Так вот, эти кристаллические штуки...$B$BДлинноязыкие их используют, чтобы давать силу алтарям дождя. Зепик не знает, как это работает, зато Зепик знает, что если взять не те кристаллы, облака и дождь сойдут с ума!$B$BЗепик пытался пробраться к одному из алтарей, но все пошло не так. Зато если пойти вдвоем, должно получиться!$B$BНадо взять кристаллы, поставить их на большую штуку вроде каменной колонны, а потом разбить их, чтобы выпустить силу. Зепик точно не знает, что тогда случится, поэтому Зепик первым не пойдет.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Зепик хочет, чтобы вы разрушили кристаллы Небесного Пути перед алтарем Шепота Тумана.$B$BЕсли вы потеряете охотничий рог Зепика, поговорите со старейшиной Харкеком на холме Бешеного Сердца.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Зепик думает, с партнером такое получается лучше. Для того, кто не из племени Бешенного Сердца, ты $Gсилен:сильна;.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Диверсия в святилище Шепота Тумана',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Зепиком Охотником на Горлоков. Если Зепика нет рядом, его можно позвать, используя охотничий рог Зепика.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12538,'Шептуны не станут слушать','Хуже барабанчей – только осы! Не знаю более надоедливых тварей. Вот длинноязыкие – это да, отличная добыча!$B$BПока мы возимся с алтарями дождя, всегда убиваем десяток-другой длинноязыких-шептунов. После этого у них отшибает хотение лезть в деревню.$B$B<Зепик кивает каким-то своим мыслям.>','Зепик хочет, чтобы вы убили 12 горлоков Шепота Тумана.$B$BЕсли вы потеряете охотничий рог Зепика, поговорите со старейшиной Харкеком на холме Бешеного Сердца.','Мы - самые лучшие охотники!','Поговорите с Зепиком Охотником на Горлоков. Если Зепика нет рядом, его можно позвать, используя охотничий рог Зепика.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Шептуны не станут слушать',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хуже барабанчей – только осы! Не знаю более надоедливых тварей. Вот длинноязыкие – это да, отличная добыча!$B$BПока мы возимся с алтарями дождя, всегда убиваем десяток-другой длинноязыких-шептунов. После этого у них отшибает хотение лезть в деревню.$B$B<Зепик кивает каким-то своим мыслям.>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Зепик хочет, чтобы вы убили 12 горлоков Шепота Тумана.$B$BЕсли вы потеряете охотничий рог Зепика, поговорите со старейшиной Харкеком на холме Бешеного Сердца.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мы - самые лучшие охотники!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Зепиком Охотником на Горлоков. Если Зепика нет рядом, его можно позвать, используя охотничий рог Зепика.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (12539,'Вместе весело шагать','Найдите дорогу к холму Бешеного Сердца и поговорите с верховным шаманом Ракжаком.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вместе весело шагать',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите дорогу к холму Бешеного Сердца и поговорите с верховным шаманом Ракжаком.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (12540,'Исполнение приказа','Что ж, $gпарень:подружка;, у Ракжака есть для тебя очень, очень важное дело. Следопыт выследил к северу отсюда у реки раненого длинноязыкого. Иди и поймай его.$B$BНе бери охотника в этот раз, охотник его захочет убивать. А я хочу спрятать его у себя. Я буду тыкать в него, а он будет говорить мне разные вещи.$B$BТеперь иди и притащи мне длинноязыкого.','Найдите раненого оракула Гласа Дождя по просьбе верховного шамана Ракжака с холма Бешеного Сердца.','Не убивай меня! Не надо! Мы только искали рыбу. Мы не хотим умирать.','Поговорите с раненым оракулом к северу от Холма Бешеного Сердца, что в Низине Шолазар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Исполнение приказа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что ж, $gпарень:подружка;, у Ракжака есть для тебя очень, очень важное дело. Следопыт выследил к северу отсюда у реки раненого длинноязыкого. Иди и поймай его.$B$BНе бери охотника в этот раз, охотник его захочет убивать. А я хочу спрятать его у себя. Я буду тыкать в него, а он будет говорить мне разные вещи.$B$BТеперь иди и притащи мне длинноязыкого.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите раненого оракула Гласа Дождя по просьбе верховного шамана Ракжака с холма Бешеного Сердца.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Не убивай меня! Не надо! Мы только искали рыбу. Мы не хотим умирать.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с раненым оракулом к северу от Холма Бешеного Сердца, что в Низине Шолазар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (12541,'Тролльский дозор: в подмастерья к алхимику','Ага, ты, должно быть, обещанный нам патрульный. Ты как раз вовремя. Мне срочно нужен помощник.$b$bМы захватили лазутчика Драккари, и нам надо его допросить. Но сначала нужно приготовить сыворотку правды, и вот тут мне понадобится твоя помощь.$b$bПриготовление сыворотки – процесс кропотливый, он требует точных расчетов, безошибочной интуиции и способности к импровизации на каждом этапе.$b$bКогда будешь $gготов:готова;, дай мне знать, |3-6($r). И помни: самое главное – точный расчет времени!','Помогите алхимику Финкльштейну в Хеб\'Валоке в приготовлении сыворотки правды.$b$bКогда вы будете готовы приступить к работе, скажите об этом алхимику и выполняйте все его указания.','Вернитесь к алхимику Финкльштейну в Хеб\'Валок, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тролльский дозор: в подмастерья к алхимику',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ага, ты, должно быть, обещанный нам патрульный. Ты как раз вовремя. Мне срочно нужен помощник.$b$bМы захватили лазутчика Драккари, и нам надо его допросить. Но сначала нужно приготовить сыворотку правды, и вот тут мне понадобится твоя помощь.$b$bПриготовление сыворотки – процесс кропотливый, он требует точных расчетов, безошибочной интуиции и способности к импровизации на каждом этапе.$b$bКогда будешь $gготов:готова;, дай мне знать, |3-6($r). И помни: самое главное – точный расчет времени!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Помогите алхимику Финкльштейну в Хеб\'Валоке в приготовлении сыворотки правды.$b$bКогда вы будете готовы приступить к работе, скажите об этом алхимику и выполняйте все его указания.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к алхимику Финкльштейну в Хеб\'Валок, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (12542,'Зов Ордена','$C! Орден Серебряного Авангарда ищет закаленных солдат, которые готовы забыть о своих разногласиях и объединиться в борьбе против воинства Короля-лича. Хочешь ли ты встать в наши ряды?$b$bЕсли тебя это интересует, отправляйся на север, в Опору Света, и поговори с рыцарем Валусом.$b$bОпора Света находится среди развалин разоренного тролльского города Джинта\'калара, на границе с Зул\'Драком.$b$bПрощай!','Явитесь к рыцарю Валусу в Опоре Света в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зов Ордена',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$C! Орден Серебряного Авангарда ищет закаленных солдат, которые готовы забыть о своих разногласиях и объединиться в борьбе против воинства Короля-лича. Хочешь ли ты встать в наши ряды?$b$bЕсли тебя это интересует, отправляйся на север, в Опору Света, и поговори с рыцарем Валусом.$b$bОпора Света находится среди развалин разоренного тролльского города Джинта\'калара, на границе с Зул\'Драком.$b$bПрощай!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Явитесь к рыцарю Валусу в Опоре Света в Драконьем Погосте.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (12543,'Подношение Су-раму','Мы не знаем тебя, $gчужестранец:чужестранка;, но мы знаем, что ты что-то ищешь. Мы будем говорить со Скелетом Нозронна, но сперва тебе следует доставить нам подношения. Нам нужны зубы императорской кобры, чтобы завершить ожерелье нашего оракула.$B$BОтправляйся на северо-восток отсюда, к диким мангровым зарослям, разыщи там кобр и принеси самые лучшие зубы. Тогда мы сделаем так, что кости заговорят с тобой.','Принесите оракулу Су-раму, живущему возле Скелета Нозронна, 5 целых зубов кобры.','Вернитесь к оракулу Су-раму в Низину Шолазар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подношение Су-раму',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы не знаем тебя, $gчужестранец:чужестранка;, но мы знаем, что ты что-то ищешь. Мы будем говорить со Скелетом Нозронна, но сперва тебе следует доставить нам подношения. Нам нужны зубы императорской кобры, чтобы завершить ожерелье нашего оракула.$B$BОтправляйся на северо-восток отсюда, к диким мангровым зарослям, разыщи там кобр и принеси самые лучшие зубы. Тогда мы сделаем так, что кости заговорят с тобой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите оракулу Су-раму, живущему возле Скелета Нозронна, 5 целых зубов кобры.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к оракулу Су-раму в Низину Шолазар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12544,'Скелет Нозронна','Используйте фимиам Су-рама возле скелета Нозронна, а затем вернитесь к Хемингу Эрнестуэю в его лагерь и расскажите о том, что узнали.','Удалось тебе добыть мясо?','Вернитесь к Хемингу Эрнестуэю в Лагерь Эрнестуэя, что в Низине Шолазар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Скелет Нозронна',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте фимиам Су-рама возле скелета Нозронна, а затем вернитесь к Хемингу Эрнестуэю в его лагерь и расскажите о том, что узнали.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось тебе добыть мясо?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хемингу Эрнестуэю в Лагерь Эрнестуэя, что в Низине Шолазар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12545,'Очищение Джинта\'калара','Мы отбили этот древний храм драккари у целой толпы вторгнувшихся воинов Плети. Не более чем в ста шагах от того места, где мы стоим, расположен разрушенный город Джинта\'калар. Некроманты Плети бегают в исступлении, обращая оставшихся в живых троллей драккари в слуг Короля-лича.$B$BДля Света теперь все они потеряны. Всех их придется уничтожить.$B$B<Валус сурово смотрит на вас.>$B$BВсех до единого.','По заданию рыцаря Валуса из Опоры Света на Драконьем Погосте убейте 15 джинта\'каларских воинов Плети.','Уничтожь силы Плети у Покоя Галакронда, пока не стало слишком поздно!','Вернитесь к рыцарю Валусу в Опору Света, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Очищение Джинта\'калара',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы отбили этот древний храм драккари у целой толпы вторгнувшихся воинов Плети. Не более чем в ста шагах от того места, где мы стоим, расположен разрушенный город Джинта\'калар. Некроманты Плети бегают в исступлении, обращая оставшихся в живых троллей драккари в слуг Короля-лича.$B$BДля Света теперь все они потеряны. Всех их придется уничтожить.$B$B<Валус сурово смотрит на вас.>$B$BВсех до единого.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По заданию рыцаря Валуса из Опоры Света на Драконьем Погосте убейте 15 джинта\'каларских воинов Плети.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Уничтожь силы Плети у Покоя Галакронда, пока не стало слишком поздно!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к рыцарю Валусу в Опору Света, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12546,'Отмщение','Время настало, $n. В Этимидиане заключена вся разрушительная мощь титанов, и мне больно выпускать его на свободу в своих владениях.$B$BОднако особого выбора нет. Враги принудили меня к решительным действиям; ярость титанов принесет очищение этой земле!','Те, кто угрожает жизни... Были уничтожены?','Вернитесь к Аватаре Фрейи к водопадам Гласа Дождя, что в низине Шолазар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отмщение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Время настало, $n. В Этимидиане заключена вся разрушительная мощь титанов, и мне больно выпускать его на свободу в своих владениях.$B$BОднако особого выбора нет. Враги принудили меня к решительным действиям; ярость титанов принесет очищение этой земле!',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Те, кто угрожает жизни... Были уничтожены?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аватаре Фрейи к водопадам Гласа Дождя, что в низине Шолазар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12547,'Руна пробуждения','Это колоссальное создание неподвижно, как статуя. На его груди вы замечаете выемку в виде руны, но самой ее нигде нет.$B$BВозможно, пропавшая руна отыщется где-нибудь неподалеку?','Найдите руну "Омега" на Террасе Создателя и принесите ее к Этимидиану.','<Выемка в виде руны на груди Этимидиана, кажется, излучает некую силу.>','Вернитесь к Этимидиану в Кратер Ун\'Горо.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Руна пробуждения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это колоссальное создание неподвижно, как статуя. На его груди вы замечаете выемку в виде руны, но самой ее нигде нет.$B$BВозможно, пропавшая руна отыщется где-нибудь неподалеку?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите руну "Омега" на Террасе Создателя и принесите ее к Этимидиану.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Выемка в виде руны на груди Этимидиана, кажется, излучает некую силу.>',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Этимидиану в Кратер Ун\'Горо.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (12548,'Этимидиан','Время пришло, $n. Впервые за семь веков Связующая спираль заработала. Используй ее, чтобы отправиться на поиски нашей последней надежды.$B$BПокончим с теми, кто хочет, чтобы тень смерти скрыла эти чистые земли. Пора освободить Этимидиана.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Этимидиан',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Время пришло, $n. Впервые за семь веков Связующая спираль заработала. Используй ее, чтобы отправиться на поиски нашей последней надежды.$B$BПокончим с теми, кто хочет, чтобы тень смерти скрыла эти чистые земли. Пора освободить Этимидиана.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12549,'Охота на терропардов: стать хищником','Если тебе уже приходилось охотиться с Хемингом, ты знаешь, что он испытывал свое охотничье искусство на многих больших кошках; однако терропарды Шолазара – это совсем другое дело. Они способны одолеть добычу гораздо больших размеров, чем любая другая кошка. Тот, кто сможет победить и убить такого хищника, по праву будет зваться настоящим охотником!$B$BЕсли хочешь доказать, что ты $gдостоин:достойна; этого высокого титула, проверь себя: отправляйся охотиться на терропардов. Они обитают в чащах вокруг лагеря, а еще к югу вдоль реки.','Убейте 15 терропардов и возвращайтесь в лагерь Эрнестуэя к Баку Кантвеллу.','Удалось ли тебе поохотиться на терропардов?','Вернитесь к Баку Кантвеллу в Лагерь Эрнестуэя, что в Низине Шолазар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота на терропардов: стать хищником',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если тебе уже приходилось охотиться с Хемингом, ты знаешь, что он испытывал свое охотничье искусство на многих больших кошках; однако терропарды Шолазара – это совсем другое дело. Они способны одолеть добычу гораздо больших размеров, чем любая другая кошка. Тот, кто сможет победить и убить такого хищника, по праву будет зваться настоящим охотником!$B$BЕсли хочешь доказать, что ты $gдостоин:достойна; этого высокого титула, проверь себя: отправляйся охотиться на терропардов. Они обитают в чащах вокруг лагеря, а еще к югу вдоль реки.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 15 терропардов и возвращайтесь в лагерь Эрнестуэя к Баку Кантвеллу.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось ли тебе поохотиться на терропардов?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Баку Кантвеллу в Лагерь Эрнестуэя, что в Низине Шолазар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12550,'Охота на терропардов: по следу зверя','Я слышал, среди местных жителей ходят легенды об огромном терропарде, которого называют Шанго. Не знаю, существует ли этот Шанго или нет – из-за ран я не в силах покинуть лагерь.$B$BЕсли хочешь проверить свои способности следопыта, попробуй узнать правду о Шанго. Дебаар говорит, что она недавно видела какие-то большие следы. Отправляйся на север к озеру Горьких Волн и осмотри его южный берег. Может, тебе они тоже встретятся.','Бак Кантвелл из лагеря Эрнестуэя хочет, чтобы вы выявили 3 следа Шанго среди следов терропардов у озера Горьких Волн.','<Бак выслушивает рассказ о том, что вам удалось обнаружить.>$B$BПохоже, тебе удалось разыскать доказательства существования Шанго. Мне кажется, я знаю, где нам его найти...','Как твои успехи в искусстве следопыта?','Вернитесь к Баку Кантвеллу в Лагерь Эрнестуэя, что в Низине Шолазар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота на терропардов: по следу зверя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я слышал, среди местных жителей ходят легенды об огромном терропарде, которого называют Шанго. Не знаю, существует ли этот Шанго или нет – из-за ран я не в силах покинуть лагерь.$B$BЕсли хочешь проверить свои способности следопыта, попробуй узнать правду о Шанго. Дебаар говорит, что она недавно видела какие-то большие следы. Отправляйся на север к озеру Горьких Волн и осмотри его южный берег. Может, тебе они тоже встретятся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Бак Кантвелл из лагеря Эрнестуэя хочет, чтобы вы выявили 3 следа Шанго среди следов терропардов у озера Горьких Волн.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Бак выслушивает рассказ о том, что вам удалось обнаружить.>$B$BПохоже, тебе удалось разыскать доказательства существования Шанго. Мне кажется, я знаю, где нам его найти...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как твои успехи в искусстве следопыта?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Баку Кантвеллу в Лагерь Эрнестуэя, что в Низине Шолазар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12551,'Охота на кроколисков: испытание','Я тебя предупреждаю: о катастрофе – ни слова! Я уже об этом наслушалась от остальных в экспедиции! Хватит с меня!$B$BЕсли ты хочешь научиться нелегкому искусству охоты, начни с мангровых кроколисков. Они живут вдоль реки на юге и в мангровых зарослях на востоке. Докажи, что ты можешь с ними справиться, и тогда мы с тобой поговорим.','Убейте 15 мангровых кроколисков и вернитесь к Дебаар в лагерь Эрнестуэя.','Ну как, удалось кого-нибудь убить?','Вернитесь к Дебаар в Лагерь Эрнестуэя, что в Низине Шолазар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота на кроколисков: испытание',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я тебя предупреждаю: о катастрофе – ни слова! Я уже об этом наслушалась от остальных в экспедиции! Хватит с меня!$B$BЕсли ты хочешь научиться нелегкому искусству охоты, начни с мангровых кроколисков. Они живут вдоль реки на юге и в мангровых зарослях на востоке. Докажи, что ты можешь с ними справиться, и тогда мы с тобой поговорим.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 15 мангровых кроколисков и вернитесь к Дебаар в лагерь Эрнестуэя.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как, удалось кого-нибудь убить?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дебаар в Лагерь Эрнестуэя, что в Низине Шолазар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12552,'Смерть некромагам!','Когда тролли обрушили Колрамас, он рухнул совсем рядом с нами, на юго-востоке. К несчастью, далеко не все выродки Плети, находившиеся внутри, были уничтожены при падении.$B$BСейчас они воскрешают наших людей из мертвых и обращают их против нас!$B$BНадо с этим покончить! Позаботься о том, чтобы их некромаги нашли свою смерть! Надеюсь, мы понимаем друг друга?','По поручению сержанта Осколка Луны в Драк\'Сотре убейте 8 некромагов Хат\'ар.','Прядильные органы должны быть целыми, без изъянов, и тогда я смогу сделать из них устройство, которое может тебе пригодиться.','Вернитесь к сержанту Осколку Луны в Драк\'Сотру, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Смерть некромагам!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда тролли обрушили Колрамас, он рухнул совсем рядом с нами, на юго-востоке. К несчастью, далеко не все выродки Плети, находившиеся внутри, были уничтожены при падении.$B$BСейчас они воскрешают наших людей из мертвых и обращают их против нас!$B$BНадо с этим покончить! Позаботься о том, чтобы их некромаги нашли свою смерть! Надеюсь, мы понимаем друг друга?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По поручению сержанта Осколка Луны в Драк\'Сотре убейте 8 некромагов Хат\'ар.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Прядильные органы должны быть целыми, без изъянов, и тогда я смогу сделать из них устройство, которое может тебе пригодиться.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к сержанту Осколку Луны в Драк\'Сотру, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12553,'Прядильные органы','Вот почему мне всегда достается самая тяжелая работа?!$B$BПриспешники Плети построили в Колрамасе сеятели чумы, и они подбираются к нам. Это очень опасно. Я даже не буду тебе говорить, что может случиться, если они направятся в нашу сторону!$B$BУ меня есть идея, как их сбивать, но для ее воплощения мне нужно... в общем, одна небольшая деталь, скажем так, от их собственных творений.$B$BСобиратели Хат\'ар прядут очень прочную паутину, которую мы можем использовать для своих целей. Принеси мне их прядильные органы.','Принесите специалисту Зубоколесу в Драк\'Сотру 5 целых прядильных органов.','Прядильные органы должны быть целыми, без изъянов, и тогда я смогу сделать из них устройство, которое может тебе пригодиться.','Вернитесь к специалисту Зубоколесу в Драк\'Сотру, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прядильные органы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот почему мне всегда достается самая тяжелая работа?!$B$BПриспешники Плети построили в Колрамасе сеятели чумы, и они подбираются к нам. Это очень опасно. Я даже не буду тебе говорить, что может случиться, если они направятся в нашу сторону!$B$BУ меня есть идея, как их сбивать, но для ее воплощения мне нужно... в общем, одна небольшая деталь, скажем так, от их собственных творений.$B$BСобиратели Хат\'ар прядут очень прочную паутину, которую мы можем использовать для своих целей. Принеси мне их прядильные органы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите специалисту Зубоколесу в Драк\'Сотру 5 целых прядильных органов.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Прядильные органы должны быть целыми, без изъянов, и тогда я смогу сделать из них устройство, которое может тебе пригодиться.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к специалисту Зубоколесу в Драк\'Сотру, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12555,'Оплетающие сети','Ну вот! Одна катапульта-сетемет готова, так что можешь сбивать этих сеятелей чумы.$B$BПросто целься и стреляй. Сети должны нейтрализовать заклинания, поднимающие их в воздух, так что они просто рухнут на землю, как это случилось с Колрамасом.$B$BЭто даже как-то поэтично... мне нравится!','По поручению специалиста Зубоколеса из Драк\'Сотры сбейте 5 сеятелей чумы с помощью катапульты-сетемета.','Жду не дождусь, когда можно будет насадить его голову на копье. Посмотрим , сможет ли он ожить после этого!','Вернитесь к специалисту Зубоколесу в Драк\'Сотру, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оплетающие сети',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну вот! Одна катапульта-сетемет готова, так что можешь сбивать этих сеятелей чумы.$B$BПросто целься и стреляй. Сети должны нейтрализовать заклинания, поднимающие их в воздух, так что они просто рухнут на землю, как это случилось с Колрамасом.$B$BЭто даже как-то поэтично... мне нравится!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По поручению специалиста Зубоколеса из Драк\'Сотры сбейте 5 сеятелей чумы с помощью катапульты-сетемета.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Жду не дождусь, когда можно будет насадить его голову на копье. Посмотрим , сможет ли он ожить после этого!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к специалисту Зубоколесу в Драк\'Сотру, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12556,'Охота на люторогов: смертельный удар','Теперь, когда мы знаем, где найти Фаранна, осталось только выйти на бой против этого великого люторога. Ответь мне, $n: $gготов:готова; ли ты прикончить его? Конечно, слухи многое преувеличивают; но я уверен, что сила Фаранна действительно огромна.$B$BЕсли решишься сразиться с этим люторогом, отправляйся на север: там, за Колонной Солнечного Благословения, на северо-восточном берегу Неспокойного озера ты найдешь Фаранна. Может быть, он даже до Мерцающей колонны дошел. Принеси мне его рог: это будет доказательством того, что люторог мертв.','Принесите рог Фаранна Хемингу Эрнестуэю в его лагерь.','Надеюсь, Фаранн мертв?','Вернитесь к Хемингу Эрнестуэю в Лагерь Эрнестуэя, что в Низине Шолазар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота на люторогов: смертельный удар',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда мы знаем, где найти Фаранна, осталось только выйти на бой против этого великого люторога. Ответь мне, $n: $gготов:готова; ли ты прикончить его? Конечно, слухи многое преувеличивают; но я уверен, что сила Фаранна действительно огромна.$B$BЕсли решишься сразиться с этим люторогом, отправляйся на север: там, за Колонной Солнечного Благословения, на северо-восточном берегу Неспокойного озера ты найдешь Фаранна. Может быть, он даже до Мерцающей колонны дошел. Принеси мне его рог: это будет доказательством того, что люторог мертв.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите рог Фаранна Хемингу Эрнестуэю в его лагерь.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Надеюсь, Фаранн мертв?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хемингу Эрнестуэю в Лагерь Эрнестуэя, что в Низине Шолазар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (12557,'Лабораторная работа','Как я понимаю, ты хочешь, чтобы я взял тебя в $gученики:ученицы;.$b$bПохвальное стремление, очень похвальное... $b$bЕсли когда-нибудь я соглашусь, я должен быть уверен, что ты сумеешь сориентироваться в моей лаборатории. У меня тут хранятся различные ингредиенты. И в больших, и в малых количествах.$b$bДавай проверим тебя, |3-6($c). Найди грязную болотную личинку, иссохшее крыло нетопыря, янтарный желудь и замерзшую змеиную слизь.$b$bЕсли найдешь, я серьезно подумаю над твоей просьбой.','Отыщите в лаборатории Финкльштейна грязную болотную личинку, иссохшее крыло нетопыря, янтарный желудь и замерзшую змеиную слизь.','Вернитесь к алхимику Финкльштейну в Хеб\'Валок, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лабораторная работа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как я понимаю, ты хочешь, чтобы я взял тебя в $gученики:ученицы;.$b$bПохвальное стремление, очень похвальное... $b$bЕсли когда-нибудь я соглашусь, я должен быть уверен, что ты сумеешь сориентироваться в моей лаборатории. У меня тут хранятся различные ингредиенты. И в больших, и в малых количествах.$b$bДавай проверим тебя, |3-6($c). Найди грязную болотную личинку, иссохшее крыло нетопыря, янтарный желудь и замерзшую змеиную слизь.$b$bЕсли найдешь, я серьезно подумаю над твоей просьбой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщите в лаборатории Финкльштейна грязную болотную личинку, иссохшее крыло нетопыря, янтарный желудь и замерзшую змеиную слизь.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к алхимику Финкльштейну в Хеб\'Валок, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12558,'Охота на терропардов: прыжок','Шанго ждет, $n. Если ты $gпреуспел:преуспела; в искусстве следопыта, он не узнает, что ты ведешь на него охоту – а это преимущество.$B$BГоворят, что он более силен, свиреп и велик, чем любой другой терропард. Отправляйся на север, к западному берегу озера Горьких Волн; там, подле водопадов, питающих озеро, ты найдешь Шанго и сразишься с ним. Если добьешься успеха, принеси мне его шкуру.','Принесите шкуру Шанго Баку Кантвеллу в лагерь Эрнестуэя.','Удалось тебе одолеть Шанго?','Вернитесь к Баку Кантвеллу в Лагерь Эрнестуэя, что в Низине Шолазар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота на терропардов: прыжок',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Шанго ждет, $n. Если ты $gпреуспел:преуспела; в искусстве следопыта, он не узнает, что ты ведешь на него охоту – а это преимущество.$B$BГоворят, что он более силен, свиреп и велик, чем любой другой терропард. Отправляйся на север, к западному берегу озера Горьких Волн; там, подле водопадов, питающих озеро, ты найдешь Шанго и сразишься с ним. Если добьешься успеха, принеси мне его шкуру.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите шкуру Шанго Баку Кантвеллу в лагерь Эрнестуэя.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось тебе одолеть Шанго?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Баку Кантвеллу в Лагерь Эрнестуэя, что в Низине Шолазар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12559,'Включение Связующей спирали: Обитель Творцов','Итак, время пришло. Пора активировать Связующую спираль.$B$BПервый переключатель можно отыскать в Обители Творцов в западной части низины. $B$BНо берегись, $n. Титаны использовали Обитель для наблюдения за своими созданиями. Многие из их каменных творений все еще охраняют это место.','Аватара Фрейи с водопадов Гласа Дождя хочет, чтобы вы отправились в Обитель Творцов и воспользовались активационным переключателем "гамма".','Ты $Gвернулся:вернулась;, $Gмалыш:малышка;. Я начал беспокоиться о твоем благополучии.','Вернитесь к Аватаре Фрейи к водопадам Гласа Дождя, что в низине Шолазар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Включение Связующей спирали: Обитель Творцов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Итак, время пришло. Пора активировать Связующую спираль.$B$BПервый переключатель можно отыскать в Обители Творцов в западной части низины. $B$BНо берегись, $n. Титаны использовали Обитель для наблюдения за своими созданиями. Многие из их каменных творений все еще охраняют это место.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Аватара Фрейи с водопадов Гласа Дождя хочет, чтобы вы отправились в Обитель Творцов и воспользовались активационным переключателем "гамма".',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gвернулся:вернулась;, $Gмалыш:малышка;. Я начал беспокоиться о твоем благополучии.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аватаре Фрейи к водопадам Гласа Дождя, что в низине Шолазар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (12560,'Охота на кроколисков: план','Мангровые кроколиски умеют подолгу таиться в засаде: тут у них есть чему поучиться. Так что давай-ка придумаем для тебя подходящую маскировку. Возьмем травы, растущие по песчаным берегам реки и у озера.$B$BЛучше всего для этой цели подойдет песчаный папоротник. Он растет на песках возле разлома Морского Потока на юге, у озера Горьких Волн и водопада Горьких Волн на севере, а также за мангровыми зарослями на востоке, у озера Слияние рек.','Принесите 5 листьев песочного папоротника Дебаар в лагерь Эрнестуэя.','<Дебаар забирает у вас листья папоротника и начинает заворачивать вас в них.>$B$BДа, это должно сработать... Стой тихо! Сейчас ты станешь в точности как кустик папоротника.','Вернитесь к Дебаар в Лагерь Эрнестуэя, что в Низине Шолазар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота на кроколисков: план',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мангровые кроколиски умеют подолгу таиться в засаде: тут у них есть чему поучиться. Так что давай-ка придумаем для тебя подходящую маскировку. Возьмем травы, растущие по песчаным берегам реки и у озера.$B$BЛучше всего для этой цели подойдет песчаный папоротник. Он растет на песках возле разлома Морского Потока на юге, у озера Горьких Волн и водопада Горьких Волн на севере, а также за мангровыми зарослями на востоке, у озера Слияние рек.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 5 листьев песочного папоротника Дебаар в лагерь Эрнестуэя.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Дебаар забирает у вас листья папоротника и начинает заворачивать вас в них.>$B$BДа, это должно сработать... Стой тихо! Сейчас ты станешь в точности как кустик папоротника.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дебаар в Лагерь Эрнестуэя, что в Низине Шолазар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12561,'Вопрос доверия','Такого не должно было случиться. Силы смерти атакуют колыбель жизни!$B$BЕсли ты здесь не для того, чтобы уничтожить прислужников Короля-лича, тогда уходи. Не отвлекай меня от моих обязанностей. Не гневи меня.','Завоюйте доверие Фрейи: уничтожьте 6 чумных трупов и 10 острокостных опустошителей в Затерянных землях.','Не трать мое время, смертный. Создания титанов нужно защищать!','Вернитесь к Аватаре Фрейи к водопадам Гласа Дождя, что в низине Шолазар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вопрос доверия',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Такого не должно было случиться. Силы смерти атакуют колыбель жизни!$B$BЕсли ты здесь не для того, чтобы уничтожить прислужников Короля-лича, тогда уходи. Не отвлекай меня от моих обязанностей. Не гневи меня.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Завоюйте доверие Фрейи: уничтожьте 6 чумных трупов и 10 острокостных опустошителей в Затерянных землях.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Не трать мое время, смертный. Создания титанов нужно защищать!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аватаре Фрейи к водопадам Гласа Дождя, что в низине Шолазар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12562,'Элементали не для Драккари','По данным нашей разведки, как только на полях Драк\'Сотры появились эти элементали воды, шаманы Драккари сразу спустились с верхних ярусов Зул\'Драка, чтобы взять их под контроль.$B$BЭто крайне тревожные известия, $gгосподин:госпожа;. Нельзя допустить, чтобы они получили в свое распоряжение элементалей воды.$B$BКомандир приказал перебить всех водопрядов Драккари. Отправляйтесь на юг, как только будете готовы.','По заданию младшего лейтенанта Джакса из Серебряной заставы убейте 10 водопрядов Драккари.','Если я могу посоветовать, ты можешь позаботиться еще о нескольких из этих связующих для воды Драккари.','Вернитесь к младшему лейтенанту Джаксу на Серебряную заставу, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Элементали не для Драккари',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','По данным нашей разведки, как только на полях Драк\'Сотры появились эти элементали воды, шаманы Драккари сразу спустились с верхних ярусов Зул\'Драка, чтобы взять их под контроль.$B$BЭто крайне тревожные известия, $gгосподин:госпожа;. Нельзя допустить, чтобы они получили в свое распоряжение элементалей воды.$B$BКомандир приказал перебить всех водопрядов Драккари. Отправляйтесь на юг, как только будете готовы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По заданию младшего лейтенанта Джакса из Серебряной заставы убейте 10 водопрядов Драккари.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если я могу посоветовать, ты можешь позаботиться еще о нескольких из этих связующих для воды Драккари.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к младшему лейтенанту Джаксу на Серебряную заставу, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12563,'Тролльский дозор','Расчехляй оружие, |3-6($r). Пора отправляться в дозор!$b$bУ меня под командованием четыре заставы, и они должны оставаться под нашим контролем. Слушай приказ: обойди все четыре и предложи свою помощь тамошним командирам.$b$bНачни с капитана Брендона на юго-востоке отсюда. Когда все закончишь, он направит тебя на следующую заставу.$b$bКогда обойдешь все четыре заставы и окажешь там необходимую помощь, возвращайся ко мне. И помни, чем быстрее исполнишь работу, тем выше будет награда – так что поторопись. Время – деньги!$b$bВсе, выполняй!','Обойдите четыре заставы Серебряного Авангарда, выполните приказы капитанов и возвратитесь к командиру Кунцу на Серебряную заставу с докладом.$b$bЗаставы капитана Брендона и капитана Руперта расположены в Драк\'Сотре, застава капитана Гронделя – в Драк\'Агале, а застава алхимика Финкльштейна – в Хеб\'Валоке.','Какие новости из наших постов, |3-6($R)?','Вернитесь к командиру Кунцу на Серебряную заставу, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тролльский дозор',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Расчехляй оружие, |3-6($r). Пора отправляться в дозор!$b$bУ меня под командованием четыре заставы, и они должны оставаться под нашим контролем. Слушай приказ: обойди все четыре и предложи свою помощь тамошним командирам.$b$bНачни с капитана Брендона на юго-востоке отсюда. Когда все закончишь, он направит тебя на следующую заставу.$b$bКогда обойдешь все четыре заставы и окажешь там необходимую помощь, возвращайся ко мне. И помни, чем быстрее исполнишь работу, тем выше будет награда – так что поторопись. Время – деньги!$b$bВсе, выполняй!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обойдите четыре заставы Серебряного Авангарда, выполните приказы капитанов и возвратитесь к командиру Кунцу на Серебряную заставу с докладом.$b$bЗаставы капитана Брендона и капитана Руперта расположены в Драк\'Сотре, застава капитана Гронделя – в Драк\'Агале, а застава алхимика Финкльштейна – в Хеб\'Валоке.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Какие новости из наших постов, |3-6($R)?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру Кунцу на Серебряную заставу, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12564,'Тролльский дозор: обезболивающее снадобье','Да, мои люди крепки и выносливы, но они все-таки смертные.$b$bРаны и боль выводят их из строя. Такова суровая правда жизни.$b$bНо, к счастью, один из наших алхимиков придумал целебную мазь, которая почти полностью снимает боль.$b$bВ рецепт этой мази входит экстракт из особого мака, который тролли выращивают на полях неподалеку отсюда, на западе. Иди на поля Драк\'Сотры и собери эти маки, чтобы у нас был хороший запас сырья для целебного снадобья.','Соберите 5 распустившихся водяных маков на полях Драк\'Сотры для капитана Брендона из Драк\'Сотры.','Ты $Gсобрал:собрала; водяные маки, $N?','Вернитесь к капитану Брендону в Драк\'Сотру, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тролльский дозор: обезболивающее снадобье',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Да, мои люди крепки и выносливы, но они все-таки смертные.$b$bРаны и боль выводят их из строя. Такова суровая правда жизни.$b$bНо, к счастью, один из наших алхимиков придумал целебную мазь, которая почти полностью снимает боль.$b$bВ рецепт этой мази входит экстракт из особого мака, который тролли выращивают на полях неподалеку отсюда, на западе. Иди на поля Драк\'Сотры и собери эти маки, чтобы у нас был хороший запас сырья для целебного снадобья.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 5 распустившихся водяных маков на полях Драк\'Сотры для капитана Брендона из Драк\'Сотры.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gсобрал:собрала; водяные маки, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Брендону в Драк\'Сотру, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12565,'Благословение Зим\'Абвы','Мне радостно видеть, с каким рвением ваш Серебряный Авангард разбирается с Плетью, |3-6($r). Я хочу вам помочь.$B$BРаньше тролли драккари из этого когда-то великого города регулярно приносили жертвы своим богам, но сейчас они уже не почитают богов так, как прежде.$B$BЕсли сделать богам щедрое подношение, в ответ боги одарят тебя своей милостью.$B$BИзваяние Зим\'Абвы находится прямо на юго-западе. Зим\'Абва с радостью примет в дар от тебя артефакты Драккари – в знак того, что ты защищаешь Зул\'Драк.','<Если бы Зим\'Абва мог шевелить губами, они бы сложились в зловещую усмешку.>','<Зим\'Абва смотрит на север и юг непроницаемым взглядом.>','Отнесите подношения Драккари к изваянию Зим\'Абвы, что на юго-западе от Серебряной заставы, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Благословение Зим\'Абвы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне радостно видеть, с каким рвением ваш Серебряный Авангард разбирается с Плетью, |3-6($r). Я хочу вам помочь.$B$BРаньше тролли драккари из этого когда-то великого города регулярно приносили жертвы своим богам, но сейчас они уже не почитают богов так, как прежде.$B$BЕсли сделать богам щедрое подношение, в ответ боги одарят тебя своей милостью.$B$BИзваяние Зим\'Абвы находится прямо на юго-западе. Зим\'Абва с радостью примет в дар от тебя артефакты Драккари – в знак того, что ты защищаешь Зул\'Драк.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Если бы Зим\'Абва мог шевелить губами, они бы сложились в зловещую усмешку.>',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Зим\'Абва смотрит на север и юг непроницаемым взглядом.>',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите подношения Драккари к изваянию Зим\'Абвы, что на юго-западе от Серебряной заставы, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) VALUES (12566,'Холмистая поляна стала воплощением кошмаров. Я никогда не могла представить себе, что наша земля может превратиться в нечто столь ужасающее.') ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Холмистая поляна стала воплощением кошмаров. Я никогда не могла представить себе, что наша земля может превратиться в нечто столь ужасающее.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12567,'Благословение Зим\'Абвы','<Вы чувствуете, что Зим\'Абва доволен. И в то же время вы знаете, что Зим\'Абва хочет еще подношений!>','<Застывший каменный взгляд Зим\'Абвы проникает вам в душу.>$B$B<Зим\'Абва доволен, но хочет, чтобы вы оказали ему еще больше почета и уважения в виде подношений Драккари.>$B$B<И тогда он вас вознаградит.>','Вернитесь в Зим\'Абву в Зул\'Драк.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Благословение Зим\'Абвы',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Вы чувствуете, что Зим\'Абва доволен. И в то же время вы знаете, что Зим\'Абва хочет еще подношений!>',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Застывший каменный взгляд Зим\'Абвы проникает вам в душу.>$B$B<Зим\'Абва доволен, но хочет, чтобы вы оказали ему еще больше почета и уважения в виде подношений Драккари.>$B$B<И тогда он вас вознаградит.>',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь в Зим\'Абву в Зул\'Драк.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (12568,'Тролльский дозор: смертельная усталость','Поверь мне, |3-6($r). Я знаю...$b$bДаже меня, Отрекшегося, уже начинает подташнивать от запаха горелой плоти. Как бы там ни было, наш святой долг – проследить за тем, чтобы наши собратья не стали приспешниками Плети.$b$bПолей этой жидкостью тела наших павших товарищей, чтобы нам не пришлось встретиться с ними на поле боя уже как с врагами.','По поручению капитана Руперта полейте 5 павших пехотинцев Серебряного Авангарда в Драк\'Сотре маслом для сожжения.','Вернитесь к капитану Руперту в Драк\'Сотру, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тролльский дозор: смертельная усталость',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Поверь мне, |3-6($r). Я знаю...$b$bДаже меня, Отрекшегося, уже начинает подташнивать от запаха горелой плоти. Как бы там ни было, наш святой долг – проследить за тем, чтобы наши собратья не стали приспешниками Плети.$b$bПолей этой жидкостью тела наших павших товарищей, чтобы нам не пришлось встретиться с ними на поле боя уже как с врагами.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По поручению капитана Руперта полейте 5 павших пехотинцев Серебряного Авангарда в Драк\'Сотре маслом для сожжения.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Руперту в Драк\'Сотру, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12569,'Охота на кроколисков: засада','Самый большой кроколиск в долине, прозванный Прогрызателем за умение выбираться из ловушек, любит греться на солнце на отмелях Слияния рек. Это такое большое озеро в центре долины, к востоку от нашего лагеря.$B$BЯ хочу, чтобы ты $gнадел:надела; камуфляж, который я для тебя приготовила, и $gустроил:устроила; засаду на западном берегу Слияния рек. Если тебе удастся прикончить Прогрызателя – в чем я лично сомневаюсь, – принеси мне его челюсть.','Принесите челюсть Прогрызателя Дебаар в лагерь Эрнестуэя.','Ну что, сработал наш план?','Вернитесь к Дебаар в Лагерь Эрнестуэя, что в Низине Шолазар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота на кроколисков: засада',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Самый большой кроколиск в долине, прозванный Прогрызателем за умение выбираться из ловушек, любит греться на солнце на отмелях Слияния рек. Это такое большое озеро в центре долины, к востоку от нашего лагеря.$B$BЯ хочу, чтобы ты $gнадел:надела; камуфляж, который я для тебя приготовила, и $gустроил:устроила; засаду на западном берегу Слияния рек. Если тебе удастся прикончить Прогрызателя – в чем я лично сомневаюсь, – принеси мне его челюсть.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите челюсть Прогрызателя Дебаар в лагерь Эрнестуэя.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, сработал наш план?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дебаар в Лагерь Эрнестуэя, что в Низине Шолазар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`) VALUES (12570,'Счастливое непонимание','Прости, прости! Не хотел втянуть тебя в неприятности!$B$B<Раненый Оракул долго смотрит на вас остановившимся взглядом.>$B$BТы меня спасаешь! Мы благодарим тебя. Теперь мы вернемся в деревню. Ты тоже идешь... ты можешь остаться с нами. Волосатые бывают очень злы...$B$BСкажи мне, когда соберешься идти, хорошо?','Отведите раненого оракула в Прибежище Гласа Дождя и поговорите с верховным оракулом Су-сэем.','Ты помогаешь нам? Тогда мы рады тебе, сухая шкура.','Кто ты? от тебя пахнет волосатыми...','Отведите раненого Оракула в Прибежище Гласа Дождя') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Счастливое непонимание',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прости, прости! Не хотел втянуть тебя в неприятности!$B$B<Раненый Оракул долго смотрит на вас остановившимся взглядом.>$B$BТы меня спасаешь! Мы благодарим тебя. Теперь мы вернемся в деревню. Ты тоже идешь... ты можешь остаться с нами. Волосатые бывают очень злы...$B$BСкажи мне, когда соберешься идти, хорошо?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отведите раненого оракула в Прибежище Гласа Дождя и поговорите с верховным оракулом Су-сэем.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты помогаешь нам? Тогда мы рады тебе, сухая шкура.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Кто ты? от тебя пахнет волосатыми...',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Отведите раненого Оракула в Прибежище Гласа Дождя',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12571,'Большая Скверная Змея должна уйти','Мы пришли сюда задолго до волосатых, и не покинем это место – место великой святости.$B$BМожет, в твоем сердце живет только добро, но все же мы отправим с тобой Лафу. Мы ни в чем не можем быть уверены, пойми нас.$B$BЭти змеи все время пытаются пожрать наших детенышей. Вы с Лафу должны остановить их, понимаешь? Особенно ту большую змею, что живет у северо-восточного водопада.','Верховный оракул Су-сэй из Прибежища Гласа Дождя просит вас убить Ядоклыка и 10 императорских кобр.$B$BЕсли потеряете мешок с жуками Лафу, поговорите с верховным оракулом Су-сэем в прибежище Гласа Дождя.','<Верховный оракул Су-сей смотрит словно бы сквозь вас.>','Вернитесь к верховному оракулу Су-сэю в Прибежище Гласа Дождя, что в Низине Шолазар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Большая Скверная Змея должна уйти',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы пришли сюда задолго до волосатых, и не покинем это место – место великой святости.$B$BМожет, в твоем сердце живет только добро, но все же мы отправим с тобой Лафу. Мы ни в чем не можем быть уверены, пойми нас.$B$BЭти змеи все время пытаются пожрать наших детенышей. Вы с Лафу должны остановить их, понимаешь? Особенно ту большую змею, что живет у северо-восточного водопада.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верховный оракул Су-сэй из Прибежища Гласа Дождя просит вас убить Ядоклыка и 10 императорских кобр.$B$BЕсли потеряете мешок с жуками Лафу, поговорите с верховным оракулом Су-сэем в прибежище Гласа Дождя.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Верховный оракул Су-сей смотрит словно бы сквозь вас.>',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному оракулу Су-сэю в Прибежище Гласа Дождя, что в Низине Шолазар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12572,'Боги любят блестящие штучки','Су-сэй говорит, мы идем с тобой. Ты только веди себя хорошо, ладно?$B$BО-о, о-о! Мы знаем! Су-сэй будет рад, если мы принесем больше подношений в святилище! Нам не придется идти далеко, возле деревни всегда можно что-то откопать... Присмотрись, и увидишь блеск в грязи!$B$BИдем! Идем! Подношения в святилище!..','Соберите 6 драгоценных блестяшек, которые выкопает Лафу, и принесите их верховному оракулу Су-сэю в прибежище Гласа Дождя.$B$BЕсли потеряете мешок с жуками Лафу, поговорите с верховным оракулом Су-сэем в прибежище Гласа Дождя.','Приветствую тебя, сухая шкура. Ну как, поладили с Лафу?','Вернитесь к верховному оракулу Су-сэю в Прибежище Гласа Дождя, что в Низине Шолазар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Боги любят блестящие штучки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Су-сэй говорит, мы идем с тобой. Ты только веди себя хорошо, ладно?$B$BО-о, о-о! Мы знаем! Су-сэй будет рад, если мы принесем больше подношений в святилище! Нам не придется идти далеко, возле деревни всегда можно что-то откопать... Присмотрись, и увидишь блеск в грязи!$B$BИдем! Идем! Подношения в святилище!..',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 6 драгоценных блестяшек, которые выкопает Лафу, и принесите их верховному оракулу Су-сэю в прибежище Гласа Дождя.$B$BЕсли потеряете мешок с жуками Лафу, поговорите с верховным оракулом Су-сэем в прибежище Гласа Дождя.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Приветствую тебя, сухая шкура. Ну как, поладили с Лафу?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному оракулу Су-сэю в Прибежище Гласа Дождя, что в Низине Шолазар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`endtext_loc8`) VALUES (12573,'Заключение мира','У нас отличная мысль. Волосатые были твоими друзьями, может быть, они тебя слушать.$B$BМы хотим вот что: передай предложение мира шаману Векжику. Он там, на юго-западе, где река становится водопадом. Скажи волосатым: войны не хотим. Скажи: хотим дружбу.$B$BТы $gхороший:хорошая:r; |3-6($r). Мы верим, что ты все сделаешь правильно.','Верховный оракул Су-сэй из Прибежища Гласа Дождя хочет, чтобы вы пошли к шаману Векжику и предложили ему мир. Вернитесь к Су-сэю с ответом.$B$BЕсли потеряете мешок с жуками Лафу, поговорите с верховным оракулом Су-сэем в прибежище Гласа Дождя.','Волосатые решили играть честно?','Донесите до шамана Векжика предложение мира.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Заключение мира',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У нас отличная мысль. Волосатые были твоими друзьями, может быть, они тебя слушать.$B$BМы хотим вот что: передай предложение мира шаману Векжику. Он там, на юго-западе, где река становится водопадом. Скажи волосатым: войны не хотим. Скажи: хотим дружбу.$B$BТы $gхороший:хорошая:r; |3-6($r). Мы верим, что ты все сделаешь правильно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верховный оракул Су-сэй из Прибежища Гласа Дождя хочет, чтобы вы пошли к шаману Векжику и предложили ему мир. Вернитесь к Су-сэю с ответом.$B$BЕсли потеряете мешок с жуками Лафу, поговорите с верховным оракулом Су-сэем в прибежище Гласа Дождя.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Волосатые решили играть честно?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Донесите до шамана Векжика предложение мира.',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (12574,'Так скоро?','<Верховный оракул Су-сэй некоторое время смотрит на ваш лоб, а потом начинает говорить.>$B$BСу-ган просит помощи. Мы думаем, что их, возможно, снова атаковали волосатые.$B$BМы посылаем на помощь тебя и Джалута... идите вдоль западной реки, пока не доберетесь до убежища Шепота Тумана. Сделайте то, что вам скажет Су-ган... если волосатые будут злы, бейте их по носу: они этого не любят.$B$B<Верховный оракул Су-сэй замолкает и смотрит на ваш лоб до тех пор, пока вы не уходите.>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Так скоро?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Верховный оракул Су-сэй некоторое время смотрит на ваш лоб, а потом начинает говорить.>$B$BСу-ган просит помощи. Мы думаем, что их, возможно, снова атаковали волосатые.$B$BМы посылаем на помощь тебя и Джалута... идите вдоль западной реки, пока не доберетесь до убежища Шепота Тумана. Сделайте то, что вам скажет Су-ган... если волосатые будут злы, бейте их по носу: они этого не любят.$B$B<Верховный оракул Су-сэй замолкает и смотрит на ваш лоб до тех пор, пока вы не уходите.>',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (12575,'Потерянное сокровище Шепота Тумана','Так вот эти волосатые приходят и разбивают синие кристаллы у великого камня тумана! Много-много дождя, молнии, вреда... Синий – неправильный кристалл для великого камня тумана! Невежественные волосатые...$B$BПосле молнии, волосатые похитили большое сокровище, что мы нашли в море-озере. Нам нужно вернуть сокровище назад, дать его великому камню тумана! Камень тумана сердит после того, что сделали волосатые!$B$BОдин, кто взял сокровище, его зовут Тартер... нет, Тиктак... нет, нет... Тартек! Да, точно – Тартек! Он пошел к этому их лагерю, на север. Верни нам сокровище!','Вернитесь к призывателю туманов Су-гану в Убежище Шепота Тумана, что в Низине Шолазар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Потерянное сокровище Шепота Тумана',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Так вот эти волосатые приходят и разбивают синие кристаллы у великого камня тумана! Много-много дождя, молнии, вреда... Синий – неправильный кристалл для великого камня тумана! Невежественные волосатые...$B$BПосле молнии, волосатые похитили большое сокровище, что мы нашли в море-озере. Нам нужно вернуть сокровище назад, дать его великому камню тумана! Камень тумана сердит после того, что сделали волосатые!$B$BОдин, кто взял сокровище, его зовут Тартер... нет, Тиктак... нет, нет... Тартек! Да, точно – Тартек! Он пошел к этому их лагерю, на север. Верни нам сокровище!',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к призывателю туманов Су-гану в Убежище Шепота Тумана, что в Низине Шолазар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12576,'Тяжелая рука','С тех самых пор, когда волосатые появились тут, мы пытались быть добры с ними, но они платят нам злом за добро.$B$BМы привыкли к тому, что они глупы – вреда от них не много. Но теперь они вредят нашим святилищам. Это плохо. Святилищам нельзя причинять вред. Великие камни здесь с давних времен; с тех самых пор, когда Великие создали нас.$B$BМы не знаем, что делать, если великому камню Тумана причинят вред. Отправляйся в лагерь волосатых на севере... пусть они остановятся, пусть не возвращаются больше!','Они всегда сражаются! Мы не хотим сражаться, но должны защищать свои святыни.','Вернитесь к призывателю туманов Су-гану в Убежище Шепота Тумана, что в Низине Шолазар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тяжелая рука',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','С тех самых пор, когда волосатые появились тут, мы пытались быть добры с ними, но они платят нам злом за добро.$B$BМы привыкли к тому, что они глупы – вреда от них не много. Но теперь они вредят нашим святилищам. Это плохо. Святилищам нельзя причинять вред. Великие камни здесь с давних времен; с тех самых пор, когда Великие создали нас.$B$BМы не знаем, что делать, если великому камню Тумана причинят вред. Отправляйся в лагерь волосатых на севере... пусть они остановятся, пусть не возвращаются больше!',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Они всегда сражаются! Мы не хотим сражаться, но должны защищать свои святыни.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к призывателю туманов Су-гану в Убежище Шепота Тумана, что в Низине Шолазар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (12577,'Пора домой!','Ты $gхороший, сухокожий:хорошая, сухокожая;. Народ Шепота Тумана в безопасности, лохматые больше нас не беспокоят.$B$BИди в прибежище Гласа Дождя и скажи Су-сэю, что ты $gсправился:справилась;.','Возвращайтесь в прибежище Гласа Дождя.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пора домой!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gхороший, сухокожий:хорошая, сухокожая;. Народ Шепота Тумана в безопасности, лохматые больше нас не беспокоят.$B$BИди в прибежище Гласа Дождя и скажи Су-сэю, что ты $gсправился:справилась;.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возвращайтесь в прибежище Гласа Дождя.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (12578,'Разгневанный горлок','Не думал, что ты появишься вовремя – но, видно, я ошибся. Пошлю Мульда к мохобродам – нужно им врезать за то, что эти глупые не пришли смотреть на святилище. Их деревня на востоке, вверх по хребту, к северо-востоку от разрушенной колонны.$B$BТы иди с Мульдом! Мульд очень умный... ты его слушай.','Отправляйтесь в деревню Мохобродов и поговорите с Мульдом.$B$BЕсли вы потеряете резиновый мячик Мульда, поговорите с верховным оракулом Су-сэем в прибежище Гласа Дождя.','Отправляйтесь в деревню Мохобродов.','Поговорите с Мульдом. Если Мульда нет рядом, воспользуйтесь резиновым мячиком Мульда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разгневанный горлок',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не думал, что ты появишься вовремя – но, видно, я ошибся. Пошлю Мульда к мохобродам – нужно им врезать за то, что эти глупые не пришли смотреть на святилище. Их деревня на востоке, вверх по хребту, к северо-востоку от разрушенной колонны.$B$BТы иди с Мульдом! Мульд очень умный... ты его слушай.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в деревню Мохобродов и поговорите с Мульдом.$B$BЕсли вы потеряете резиновый мячик Мульда, поговорите с верховным оракулом Су-сэем в прибежище Гласа Дождя.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Отправляйтесь в деревню Мохобродов.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Мульдом. Если Мульда нет рядом, воспользуйтесь резиновым мячиком Мульда.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12579,'Жизненная Сила для мохобродов','Я всегда подозревал, что колонны являются причиной того, какая погода стоит в долине; я также всегда думал, что именно они хранят нас от нежити. И, похоже, получил подтверждение...$B$BНе так давно я услышал взрыв: тогда обрушилась колонна Жизненной Силы. Почти мгновенно изменилась погода: начался снег, которого мы прежде никогда не видели.$B$BК великому камню Мха тогда принесли кристаллы жизненной силы, и снег прекратился. Быть может, если сейчас мы сделаем то же самое, это поможет прогнать нежить.','Мульд хочет, чтобы вы собрали 10 осколков Жизненной Силы, но при этом держались подальше от пещеры внутри самой колонны.$B$BЕсли вы потеряете резиновый мячик Мульда, поговорите с верховным оракулом Су-сэем в прибежище Гласа Дождя.','Мохоброды были хорошим народом... они не заслужили этого.','Поговорите с Мульдом. Если Мульда нет рядом, воспользуйтесь резиновым мячиком Мульда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жизненная Сила для мохобродов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я всегда подозревал, что колонны являются причиной того, какая погода стоит в долине; я также всегда думал, что именно они хранят нас от нежити. И, похоже, получил подтверждение...$B$BНе так давно я услышал взрыв: тогда обрушилась колонна Жизненной Силы. Почти мгновенно изменилась погода: начался снег, которого мы прежде никогда не видели.$B$BК великому камню Мха тогда принесли кристаллы жизненной силы, и снег прекратился. Быть может, если сейчас мы сделаем то же самое, это поможет прогнать нежить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Мульд хочет, чтобы вы собрали 10 осколков Жизненной Силы, но при этом держались подальше от пещеры внутри самой колонны.$B$BЕсли вы потеряете резиновый мячик Мульда, поговорите с верховным оракулом Су-сэем в прибежище Гласа Дождя.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мохоброды были хорошим народом... они не заслужили этого.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Мульдом. Если Мульда нет рядом, воспользуйтесь резиновым мячиком Мульда.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12580,'Спаситель мохобродов','Возможно, еще не все мохоброды погибли... они не заслужили того, чтобы их перебили, как животных.$B$BМы отомстим за это подлое убийство – и, может быть, еще успеем кого-нибудь спасти.','Мульд хочет, чтобы вы спасли 6 мохобродов-жертв из деревни Мохобродов, хотя некоторые из них, возможно, уже мертвы.$B$BЕсли вы потеряете резиновый мячик Мульда, поговорите с верховным оракулом Су-сэем в прибежище Гласа Дождя.','Я рад, что хотя бы нескольких удалось спасти. Если повезет, они сумеют добраться до прибежища Гласа Дождя.','Хотел бы я раньше знать, как важны колоны и камни... быть может, я сумел бы предотвратить это.','Поговорите с Мульдом. Если Мульда нет рядом, воспользуйтесь резиновым мячиком Мульда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спаситель мохобродов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Возможно, еще не все мохоброды погибли... они не заслужили того, чтобы их перебили, как животных.$B$BМы отомстим за это подлое убийство – и, может быть, еще успеем кого-нибудь спасти.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Мульд хочет, чтобы вы спасли 6 мохобродов-жертв из деревни Мохобродов, хотя некоторые из них, возможно, уже мертвы.$B$BЕсли вы потеряете резиновый мячик Мульда, поговорите с верховным оракулом Су-сэем в прибежище Гласа Дождя.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я рад, что хотя бы нескольких удалось спасти. Если повезет, они сумеют добраться до прибежища Гласа Дождя.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Хотел бы я раньше знать, как важны колоны и камни... быть может, я сумел бы предотвратить это.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Мульдом. Если Мульда нет рядом, воспользуйтесь резиновым мячиком Мульда.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (12582,'Защитник племени Бешеного Сердца','В отличие от остальных, я знаю, что ты не $Gпредатель:предательница;. Мы охотились вместе... Я знаю тебя лучше, чем любой из них. Спасибо за спасение.$B$BМожет, это прозвучит забавно... Я не особый поклонник длинноязыких... Но даже мне немножко жаль, что длинноязыкие вот так умирают... они хорошо сражаются и заслуживают честной борьбы.$B$BХочешь снова стать $Gдругом:подругой; племени Бешеного Сердца? Думаю, я мог бы убедить их, что ты $Gспас:спасла; меня и хорошо все $Gсделал:сделала; с длинноязыкими. Но я не хочу из-за тебя выглядеть дураком. Так ты $Gуверен:уверена;, что больше не хочешь с ними общаться?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Защитник племени Бешеного Сердца',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','В отличие от остальных, я знаю, что ты не $Gпредатель:предательница;. Мы охотились вместе... Я знаю тебя лучше, чем любой из них. Спасибо за спасение.$B$BМожет, это прозвучит забавно... Я не особый поклонник длинноязыких... Но даже мне немножко жаль, что длинноязыкие вот так умирают... они хорошо сражаются и заслуживают честной борьбы.$B$BХочешь снова стать $Gдругом:подругой; племени Бешеного Сердца? Думаю, я мог бы убедить их, что ты $Gспас:спасла; меня и хорошо все $Gсделал:сделала; с длинноязыкими. Но я не хочу из-за тебя выглядеть дураком. Так ты $Gуверен:уверена;, что больше не хочешь с ними общаться?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12583,'Разбившийся сеятель','Я знаю, что один из сеятелей чумы разбился где-то в Драк\'Сотре к западу отсюда.$B$BПопытайся его разыскать. Я использую части, оставшиеся от него, для создания устройства, которое будет сбивать сеятели с неба!','Соберите детали сеятеля чумы для специалиста Зубоколеса в Драк\'Сотре.','Ты принес то, о чем я тебя попросила?','Вернитесь к специалисту Зубоколесу в Драк\'Сотру, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разбившийся сеятель',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я знаю, что один из сеятелей чумы разбился где-то в Драк\'Сотре к западу отсюда.$B$BПопытайся его разыскать. Я использую части, оставшиеся от него, для создания устройства, которое будет сбивать сеятели с неба!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите детали сеятеля чумы для специалиста Зубоколеса в Драк\'Сотре.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты принес то, о чем я тебя попросила?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к специалисту Зубоколесу в Драк\'Сотру, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (12584,'Зло в чистом виде','Мы знаем, что в Колрамасе, некрополе на юго-востоке, был немалый запас руды, известной как саронит.$B$BМои разведчики говорят, что большая часть саронита так и осталась там после того, как некрополь разрушили тролли.$B$BЭйтригг и его товарищи с Серебряной заставы хотят получить образцы руды, чтобы как следует ее изучить.$B$BОтправляйся к павшему некрополю и собери образцы саронита.','По указанию капитана Руперта соберите 10 кусков саронита и отнесите их Эйтриггу на Серебряную заставу.','Вернитесь к Эйтриггу на Серебряную заставу, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зло в чистом виде',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы знаем, что в Колрамасе, некрополе на юго-востоке, был немалый запас руды, известной как саронит.$B$BМои разведчики говорят, что большая часть саронита так и осталась там после того, как некрополь разрушили тролли.$B$BЭйтригг и его товарищи с Серебряной заставы хотят получить образцы руды, чтобы как следует ее изучить.$B$BОтправляйся к павшему некрополю и собери образцы саронита.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По указанию капитана Руперта соберите 10 кусков саронита и отнесите их Эйтриггу на Серебряную заставу.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Эйтриггу на Серебряную заставу, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12585,'Тролльский дозор: животворящее тепло','Да уж, приятного в этом мало, но долг есть долг.$b$bУже несколько дней мои солдаты отважно сражаются, стоя по колено в холодной воде. Они – храбрые воины, но они все-таки не железные.$b$bИм нужно обсохнуть, согреться, воспрянуть духом. А для этого нужен костер.$b$bЭта часть города вся затоплена, но у мертвых корней колючника есть свойство отталкивать влагу, они всегда остаются сухими.$b$bСобери нам дров для костра, и мы будем очень тебе благодарны.','Принесите капитану Гронделю в Драк\'Агал 20 кусков древесины высохшего колючника.','Ты $Gсобрал:собрала; нам дрова для костра, |3-6($R)?','Вернитесь к капитану Гронделю в Драк\'Агал, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тролльский дозор: животворящее тепло',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Да уж, приятного в этом мало, но долг есть долг.$b$bУже несколько дней мои солдаты отважно сражаются, стоя по колено в холодной воде. Они – храбрые воины, но они все-таки не железные.$b$bИм нужно обсохнуть, согреться, воспрянуть духом. А для этого нужен костер.$b$bЭта часть города вся затоплена, но у мертвых корней колючника есть свойство отталкивать влагу, они всегда остаются сухими.$b$bСобери нам дров для костра, и мы будем очень тебе благодарны.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите капитану Гронделю в Драк\'Агал 20 кусков древесины высохшего колючника.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gсобрал:собрала; нам дрова для костра, |3-6($R)?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Гронделю в Драк\'Агал, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (12586,'В поисках крупной дичи','Well, $n, you\'ve been an enormous asset to the expedition so far. Debaar, Buck, and I couldn\'t have have assembled such an amazing collection of trophies without you.$B$BBut, I hear there are even fiercer monsters in other parts of the basin. I\'ve sent a search party up north to get an idea of what other beasts await us.$B$BI\'d like you to meet up with them and see what they\'ve found. Head north, beyond Bittertide Lake and search for the encampment.','Talk to <x> at <x>.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В поисках крупной дичи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Well, $n, you\'ve been an enormous asset to the expedition so far. Debaar, Buck, and I couldn\'t have have assembled such an amazing collection of trophies without you.$B$BBut, I hear there are even fiercer monsters in other parts of the basin. I\'ve sent a search party up north to get an idea of what other beasts await us.$B$BI\'d like you to meet up with them and see what they\'ve found. Head north, beyond Bittertide Lake and search for the encampment.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Talk to <x> at <x>.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (12587,'Тролльский дозор','Расчехляй оружие, |3-6($r). Пора отправляться в дозор!$b$bУ меня под командованием четыре заставы, и они должны оставаться под нашим контролем. Слушай приказ: обойди все четыре и предложи свою помощь тамошним командирам.$b$bНачни с капитана Брендона на юго-востоке отсюда. Когда все закончишь, он направит тебя на следующую заставу.$b$bКогда обойдешь все четыре заставы и окажешь там необходимую помощь, возвращайся ко мне. И помни, чем быстрее исполнишь работу, тем выше будет награда – так что поторопись. Время – деньги!$b$bВсе, выполняй!','Обойдите четыре заставы Серебряного Авангарда, выполните приказы капитанов и возвратитесь к командиру Кунцу на Серебряную заставу с докладом.$b$bЗаставы капитана Брендона и капитана Руперта расположены в Драк\'Сотре, к юго-востоку, застава капитана Гронделя – в Драк\'Агале, прямо на восток, а застава алхимика Финкльштейна – в Хеб\'Валоке, к северу.','Вернитесь к командиру Кунцу на Серебряную заставу, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тролльский дозор',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Расчехляй оружие, |3-6($r). Пора отправляться в дозор!$b$bУ меня под командованием четыре заставы, и они должны оставаться под нашим контролем. Слушай приказ: обойди все четыре и предложи свою помощь тамошним командирам.$b$bНачни с капитана Брендона на юго-востоке отсюда. Когда все закончишь, он направит тебя на следующую заставу.$b$bКогда обойдешь все четыре заставы и окажешь там необходимую помощь, возвращайся ко мне. И помни, чем быстрее исполнишь работу, тем выше будет награда – так что поторопись. Время – деньги!$b$bВсе, выполняй!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обойдите четыре заставы Серебряного Авангарда, выполните приказы капитанов и возвратитесь к командиру Кунцу на Серебряную заставу с докладом.$b$bЗаставы капитана Брендона и капитана Руперта расположены в Драк\'Сотре, к юго-востоку, застава капитана Гронделя – в Драк\'Агале, прямо на восток, а застава алхимика Финкльштейна – в Хеб\'Валоке, к северу.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру Кунцу на Серебряную заставу, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12588,'Тролльский дозор: будем копать','Во время последнего наступления мы нашли древнюю карту сокровищ. Если верить этой карте, то где-то рядом зарыт настоящий клад – бесценные тролльские артефакты.$b$bМоим воинам есть чем заняться, тем более теперь, когда мы зажаты между молотом и наковальней – между Драккари и Плетью. Так что поиском сокровищ придется заняться тебе.$b$bВозьми эту лопату и раскопай кучи земли к юго-западу отсюда. Когда отыщешь сокровища, возвращайся ко мне.','По поручению капитана Брана из Драк\'Сотры возьмите стальной заступ, раскопайте курганы древних троллей неподалеку и отыщите реликвию Драккари.','Ну что, |3-6($R)?\n\nЧто ты там раскопал?','Вернитесь к капитану Брендону в Драк\'Сотру, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тролльский дозор: будем копать',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Во время последнего наступления мы нашли древнюю карту сокровищ. Если верить этой карте, то где-то рядом зарыт настоящий клад – бесценные тролльские артефакты.$b$bМоим воинам есть чем заняться, тем более теперь, когда мы зажаты между молотом и наковальней – между Драккари и Плетью. Так что поиском сокровищ придется заняться тебе.$b$bВозьми эту лопату и раскопай кучи земли к юго-западу отсюда. Когда отыщешь сокровища, возвращайся ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По поручению капитана Брана из Драк\'Сотры возьмите стальной заступ, раскопайте курганы древних троллей неподалеку и отыщите реликвию Драккари.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, |3-6($R)?\n\nЧто ты там раскопал?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Брендону в Драк\'Сотру, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (12589,'Ничего опасного','Итак, ты думаешь, что умеешь стрелять?$B$BЧто ж, давай проверим твои умения. Начнем с чего-нибудь не слишком крупного и агрессивного. И помни: если не собираешься стрелять, то и не целься!$B$BА теперь, если ты $gготов:готова;, прицелься в яблоко на голове Везучего Вильгельма, и стреляй!','Выстрелите из винтовки РЖР в яблоко на голове Везучего Вильгельма, а потом поговорите с Дростаном.','Стреляешь ты неплохо, но тебе нужна практика. Как ты посмотришь на то, чтобы заключить небольшое пари?','Вернитесь к Дростану в Лагерь Эрнестуэя, что в Низине Шолазар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ничего опасного',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Итак, ты думаешь, что умеешь стрелять?$B$BЧто ж, давай проверим твои умения. Начнем с чего-нибудь не слишком крупного и агрессивного. И помни: если не собираешься стрелять, то и не целься!$B$BА теперь, если ты $gготов:готова;, прицелься в яблоко на голове Везучего Вильгельма, и стреляй!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выстрелите из винтовки РЖР в яблоко на голове Везучего Вильгельма, а потом поговорите с Дростаном.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Стреляешь ты неплохо, но тебе нужна практика. Как ты посмотришь на то, чтобы заключить небольшое пари?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дростану в Лагерь Эрнестуэя, что в Низине Шолазар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (12590,'Blahblah[PH]') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Blahblah[PH]',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (12591,'Тролльский дозор: подрывные работы','Умно...$b$bМы-то были уверены, что у нас все под контролем, а они сделали подкоп, прошли прямо под нами и захватили святилище!$b$bИ теперь мы оказались зажаты между двумя нерубианскими армиями, и с каждой минутой наше положение становится все отчаяннее и отчаяннее.$b$bНаша первоочередная задача – помешать этим двум армиями соединиться. Надо отрезать их друг от друга и засыпать тоннели.$b$bВозьми эти гранаты и сбрось их в кратеры наших врагов на северо-западе отсюда.','По поручению капитана Руперта из Драк\'Сотры взорвите 5 нерубианских кратеров с помощью фугасных гранат.','Вернитесь к капитану Руперту в Драк\'Сотру, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тролльский дозор: подрывные работы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Умно...$b$bМы-то были уверены, что у нас все под контролем, а они сделали подкоп, прошли прямо под нами и захватили святилище!$b$bИ теперь мы оказались зажаты между двумя нерубианскими армиями, и с каждой минутой наше положение становится все отчаяннее и отчаяннее.$b$bНаша первоочередная задача – помешать этим двум армиями соединиться. Надо отрезать их друг от друга и засыпать тоннели.$b$bВозьми эти гранаты и сбрось их в кратеры наших врагов на северо-западе отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По поручению капитана Руперта из Драк\'Сотры взорвите 5 нерубианских кратеров с помощью фугасных гранат.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Руперту в Драк\'Сотру, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12592,'Вызов великого охотника','Итак, у тебя есть охотничий инстинкт. Стреляешь ты тоже неплохо, и Хеминг тебя не выгнал – а это значит, он возьмет тебя на охоту.$B$BА вот как насчет того, чтобы устроить соревнование? Только ты и я.$B$BХеминг и его приятели пригласят тебя на охоту, а мы подсчитаем, кто из нас сколько добудет. Только дело это небыстрое: придется убить много разных зверей... Удачи тебе!','Убейте 60 животных, помогая Хемингу и его друзьям на охоте. Когда покончите с этим, возвращайтесь к Дростану в лагерь Эрнестуэя, чтобы сравнить ваши результаты.','Ну что, посчитаем?','Вернитесь к Дростану в Лагерь Эрнестуэя, что в Низине Шолазар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вызов великого охотника',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Итак, у тебя есть охотничий инстинкт. Стреляешь ты тоже неплохо, и Хеминг тебя не выгнал – а это значит, он возьмет тебя на охоту.$B$BА вот как насчет того, чтобы устроить соревнование? Только ты и я.$B$BХеминг и его приятели пригласят тебя на охоту, а мы подсчитаем, кто из нас сколько добудет. Только дело это небыстрое: придется убить много разных зверей... Удачи тебе!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 60 животных, помогая Хемингу и его друзьям на охоте. Когда покончите с этим, возвращайтесь к Дростану в лагерь Эрнестуэя, чтобы сравнить ваши результаты.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, посчитаем?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дростану в Лагерь Эрнестуэя, что в Низине Шолазар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (12593,'На службе Короля-лича','Все, что составляет мою сущность: злость, безжалостность, отмщение – я вкладываю в тебя, достойнейший рыцарь. Я даровал тебе бессмертие, ибо тебе суждено стать вестником новой, темной эры Плети.$B$BУзри же земли, лежащие перед тобой. Видишь ли ты, как Алый орден тщетно пытается разрушить созданное нами? Видишь батальоны Последней Надежды, бросающие вызов войскам Плети в Чумных землях? Все они должны поплатиться за свое упрямство. $B$BТы станешь моим возмездием, и страшен будет удел тех, кто станет у тебя на пути. Иди же и взгляни в лицо своей судьбе, мой рыцарь смерти.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На службе Короля-лича',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Все, что составляет мою сущность: злость, безжалостность, отмщение – я вкладываю в тебя, достойнейший рыцарь. Я даровал тебе бессмертие, ибо тебе суждено стать вестником новой, темной эры Плети.$B$BУзри же земли, лежащие перед тобой. Видишь ли ты, как Алый орден тщетно пытается разрушить созданное нами? Видишь батальоны Последней Надежды, бросающие вызов войскам Плети в Чумных землях? Все они должны поплатиться за свое упрямство. $B$BТы станешь моим возмездием, и страшен будет удел тех, кто станет у тебя на пути. Иди же и взгляни в лицо своей судьбе, мой рыцарь смерти.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12594,'Тролльский дозор: зачистка местности','Из всех постов мне дали именно этот, самый поганый.$b$bВся местность затоплена грязной вонючей водой, а теперь здесь еще поселились какие-то вонючие болотные духи!$b$bЯ не знаю, что они собой представляют и что им здесь нужно, и, если честно, мне это по барабану. Для меня важно одно – они отравляют мой сектор! Мы здесь воюем, а как можно нормально вести боевые действия, когда все поле боя кишит этими грязными тварями?!$b$bТак что иди, |3-6($c), и не возвращайся, пока не убьешь хотя бы полдюжины этих гадов.','По поручению капитана Гронделя убейте 7 мшистых буянов в Драк\'Агале.','Ты уверен, |3-6($R)?\n\nЛично мне кажется, что их стало больше, чем было раньше.','Ну, как? Ты очистил мой сектор от этих болотных уродов, |3-6($C)?','Вернитесь к капитану Гронделю в Амфитеатр Страданий, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тролльский дозор: зачистка местности',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Из всех постов мне дали именно этот, самый поганый.$b$bВся местность затоплена грязной вонючей водой, а теперь здесь еще поселились какие-то вонючие болотные духи!$b$bЯ не знаю, что они собой представляют и что им здесь нужно, и, если честно, мне это по барабану. Для меня важно одно – они отравляют мой сектор! Мы здесь воюем, а как можно нормально вести боевые действия, когда все поле боя кишит этими грязными тварями?!$b$bТак что иди, |3-6($c), и не возвращайся, пока не убьешь хотя бы полдюжины этих гадов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По поручению капитана Гронделя убейте 7 мшистых буянов в Драк\'Агале.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты уверен, |3-6($R)?\n\nЛично мне кажется, что их стало больше, чем было раньше.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, как? Ты очистил мой сектор от этих болотных уродов, |3-6($C)?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Гронделю в Амфитеатр Страданий, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (12595,'В поисках крупной дичи','Что ж, $n, тебе удалось подтвердить свое искусство охотника в выслеживании всех видов дичи: люторогов, кошек и кроколисков. Для многих этого хватило бы с лихвой – но не для таких, как я. Истинному охотнику нужны иные испытания. $B$BДориан Гроза Драконов разбил лагерь на севере, за озером Горьких Волн. До него дошли слухи о гигантских доисторических драконах. Ты только представь себе, какая это добыча! А какая слава! Давай-ка, навести Дориана и узнай – может, ему уже повезло.','А, так, значит, старина Хеминг еще не забыл про меня? Думаю, он захочет поучаствовать в охоте – конечно, после того, как мы сделаем за него всю грязную работу. Ну, беспокоиться нечего: тут полно всяких драконов, так что Хеминг останется доволен!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В поисках крупной дичи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что ж, $n, тебе удалось подтвердить свое искусство охотника в выслеживании всех видов дичи: люторогов, кошек и кроколисков. Для многих этого хватило бы с лихвой – но не для таких, как я. Истинному охотнику нужны иные испытания. $B$BДориан Гроза Драконов разбил лагерь на севере, за озером Горьких Волн. До него дошли слухи о гигантских доисторических драконах. Ты только представь себе, какая это добыча! А какая слава! Давай-ка, навести Дориана и узнай – может, ему уже повезло.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, так, значит, старина Хеминг еще не забыл про меня? Думаю, он захочет поучаствовать в охоте – конечно, после того, как мы сделаем за него всю грязную работу. Ну, беспокоиться нечего: тут полно всяких драконов, так что Хеминг останется доволен!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12596,'Па\'трулль','Добро пожаловать на Серебряную заставу, $gновобранец:барышня;. Я – командир Кунц, но ты можешь называть меня просто "Ваше превосходительство".$b$bИ не думай, что тут у тебя будет вольница, и ты сможешь шляться по вверенной мне территории, берясь за любую работу, которая тебе подойдет, и ни перед кем не отчитываться.$b$bОбо всем, что ты делаешь, будешь докладывать лично мне – и готовься беспрекословно выполнять все мои приказы. Понятно?$b$bПерво-наперво ты познакомишься с моими людьми. И с районом, который нам поручили зачистить.$b$bОбойди всех моих капитанов и сделай все, что они тебе скажут. Когда закончишь обход, возвращайся ко мне с докладом.','Обойдите четыре заставы Серебряного Авангарда, выполните приказы капитанов и возвратитесь к командиру Кунцу на Серебряную заставу с докладом.$b$bЗаставы капитана Брендона и капитана Руперта расположены в Драк\'Сотре, к юго-востоку, застава капитана Гронделя – в Драк\'Агале, прямо на восток, а застава алхимика Финкльштейна – в Хеб\'Валоке, к северу.','Ты $Gвстречался:встречалась; с каждым из моих капитанов, $R?','Вернитесь к командиру Кунцу на Серебряную заставу, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Па\'трулль',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Добро пожаловать на Серебряную заставу, $gновобранец:барышня;. Я – командир Кунц, но ты можешь называть меня просто "Ваше превосходительство".$b$bИ не думай, что тут у тебя будет вольница, и ты сможешь шляться по вверенной мне территории, берясь за любую работу, которая тебе подойдет, и ни перед кем не отчитываться.$b$bОбо всем, что ты делаешь, будешь докладывать лично мне – и готовься беспрекословно выполнять все мои приказы. Понятно?$b$bПерво-наперво ты познакомишься с моими людьми. И с районом, который нам поручили зачистить.$b$bОбойди всех моих капитанов и сделай все, что они тебе скажут. Когда закончишь обход, возвращайся ко мне с докладом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обойдите четыре заставы Серебряного Авангарда, выполните приказы капитанов и возвратитесь к командиру Кунцу на Серебряную заставу с докладом.$b$bЗаставы капитана Брендона и капитана Руперта расположены в Драк\'Сотре, к юго-востоку, застава капитана Гронделя – в Драк\'Агале, прямо на восток, а застава алхимика Финкльштейна – в Хеб\'Валоке, к северу.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gвстречался:встречалась; с каждым из моих капитанов, $R?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру Кунцу на Серебряную заставу, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (12597,'Обезболивающее снадобье','Да, мои люди крепки и выносливы, но они все-таки смертные.$b$bРаны и боль выводят их из строя. Такова суровая правда жизни.$b$bНо к счастью, один из наших алхимиков придумал целебную мазь, которая почти полностью снимает боль.$b$bВ рецепт этой мази входит экстракт из особого мака, который тролли выращивают на полях неподалеку отсюда, на западе. Иди на поля Драк\'Сотры и собери эти маки, чтобы у нас был хороший запас сырья для целебного снадобья.','Соберите 5 распустившихся водяных маков на полях Драк\'Сотры для капитана Брендона из Драк\'Сотры.','Вернитесь к капитану Брендону в Драк\'Сотру, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обезболивающее снадобье',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Да, мои люди крепки и выносливы, но они все-таки смертные.$b$bРаны и боль выводят их из строя. Такова суровая правда жизни.$b$bНо к счастью, один из наших алхимиков придумал целебную мазь, которая почти полностью снимает боль.$b$bВ рецепт этой мази входит экстракт из особого мака, который тролли выращивают на полях неподалеку отсюда, на западе. Иди на поля Драк\'Сотры и собери эти маки, чтобы у нас был хороший запас сырья для целебного снадобья.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 5 распустившихся водяных маков на полях Драк\'Сотры для капитана Брендона из Драк\'Сотры.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Брендону в Драк\'Сотру, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12598,'Подрывные работы','Умно...$b$bМы-то были уверены, что у нас все под контролем, а они сделали подкоп, прошли прямо под нами и захватили святилище!$b$bИ теперь мы оказались зажаты между двумя нерубскими армиями, и с каждой минутой наше положение становится все отчаяннее и отчаяннее.$b$bНаша первоочередная задача – помешать этим двум армиям получить подкрепление. Надо засыпать тоннели.$b$bВозьми эти гранаты и сбрось их в кратеры наших врагов на северо-западе отсюда.','По заданию капитана Руперта из Драк\'Сотры обрушьте 5 нерубских тоннелей с помощью фугасных гранат.','Ты $Gзапечатал:запечатала; нерубские туннели, $N?','Вернитесь к капитану Руперту в Драк\'Сотру, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подрывные работы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Умно...$b$bМы-то были уверены, что у нас все под контролем, а они сделали подкоп, прошли прямо под нами и захватили святилище!$b$bИ теперь мы оказались зажаты между двумя нерубскими армиями, и с каждой минутой наше положение становится все отчаяннее и отчаяннее.$b$bНаша первоочередная задача – помешать этим двум армиям получить подкрепление. Надо засыпать тоннели.$b$bВозьми эти гранаты и сбрось их в кратеры наших врагов на северо-западе отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По заданию капитана Руперта из Драк\'Сотры обрушьте 5 нерубских тоннелей с помощью фугасных гранат.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gзапечатал:запечатала; нерубские туннели, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Руперту в Драк\'Сотру, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (12599,'Животворящее тепло','Да уж, приятного в этом мало, но долг есть долг.$b$bУже несколько дней мои солдаты отважно сражаются, стоя по колено в холодной воде. Они – храбрые воины, но они все-таки не железные.$b$bИм нужно обсохнуть, согреться, воспрянуть духом. А для этого нужен костер.$b$bЭта часть города вся затоплена, но у мертвых корней колючника есть свойство отталкивать влагу, они всегда остаются сухими.$b$bСобери нам дров для костра, и мы будем очень тебе благодарны.','Принесите капитану Гронделю в Драк\'Агал 20 кусков древесины высохшего колючника.','Вернитесь к капитану Гронделю в Драк\'Агал, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Животворящее тепло',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Да уж, приятного в этом мало, но долг есть долг.$b$bУже несколько дней мои солдаты отважно сражаются, стоя по колено в холодной воде. Они – храбрые воины, но они все-таки не железные.$b$bИм нужно обсохнуть, согреться, воспрянуть духом. А для этого нужен костер.$b$bЭта часть города вся затоплена, но у мертвых корней колючника есть свойство отталкивать влагу, они всегда остаются сухими.$b$bСобери нам дров для костра, и мы будем очень тебе благодарны.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите капитану Гронделю в Драк\'Агал 20 кусков древесины высохшего колючника.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Гронделю в Драк\'Агал, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (12600,'Рекламный код Upper Deck – Верховой медведь') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рекламный код Upper Deck – Верховой медведь',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (12601,'В подмастерья к алхимику','Ага, ты, должно быть, обещанный нам патрульный. И очень вовремя, приятель – вообще-то, я не ждал, что ко мне пришлют барышню, но все равно... ты пришла очень вовремя. Мне срочно нужен помощник.$b$bМы захватили лазутчика Драккари, и нам надо его допросить. Но сначала нужно приготовить сыворотку правды, и вот тут мне понадобится твоя помощь.$b$bПриготовление сыворотки – процесс кропотливый, он требует точных расчетов, безошибочной интуиции и способности к импровизации на каждом этапе.$b$bКогда будешь $gготов:готова;, дай мне знать, |3-6($r). И помни: самое главное – точный расчет времени!','Помогите алхимику Финкльштейну в Хеб\'валоке в приготовлении сыворотки правды.$b$bКогда вы будете готовы приступить к работе, скажите об этом алхимику и выполняйте все его указания.','Вернитесь к алхимику Финкльштейну в Реликварий Боли, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В подмастерья к алхимику',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ага, ты, должно быть, обещанный нам патрульный. И очень вовремя, приятель – вообще-то, я не ждал, что ко мне пришлют барышню, но все равно... ты пришла очень вовремя. Мне срочно нужен помощник.$b$bМы захватили лазутчика Драккари, и нам надо его допросить. Но сначала нужно приготовить сыворотку правды, и вот тут мне понадобится твоя помощь.$b$bПриготовление сыворотки – процесс кропотливый, он требует точных расчетов, безошибочной интуиции и способности к импровизации на каждом этапе.$b$bКогда будешь $gготов:готова;, дай мне знать, |3-6($r). И помни: самое главное – точный расчет времени!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Помогите алхимику Финкльштейну в Хеб\'валоке в приготовлении сыворотки правды.$b$bКогда вы будете готовы приступить к работе, скажите об этом алхимику и выполняйте все его указания.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к алхимику Финкльштейну в Реликварий Боли, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (12602,'В подмастерья к алхимику','Ага, ты, должно быть, обещанный нам патрульный. $gИ очень вовремя, приятель:Вообще-то я не ждал, что ко мне пришлют барышню, но все равно... ты пришла очень вовремя;. Мне срочно нужен помощник.$b$bМы захватили лазутчика Драккари, и нам надо его допросить. Но сначала нужно приготовить сыворотку правды, и вот тут мне понадобится твоя помощь.$b$bПриготовление сыворотки – процесс кропотливый, он требует точных расчетов, безошибочной интуиции и способности к импровизации на каждом этапе.$b$bКогда будешь $gготов:готова;, дай мне знать, |3-6($r). И помни: самое главное – точный расчет времени!','Помогите алхимику Финкльштейну в Хеб\'Валоке в приготовлении сыворотки правды.$b$bКогда вы будете готовы приступить к работе, скажите об этом алхимику и выполняйте все его указания.','Вернитесь к алхимику Финкльштейну в Реликварий Боли, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В подмастерья к алхимику',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ага, ты, должно быть, обещанный нам патрульный. $gИ очень вовремя, приятель:Вообще-то я не ждал, что ко мне пришлют барышню, но все равно... ты пришла очень вовремя;. Мне срочно нужен помощник.$b$bМы захватили лазутчика Драккари, и нам надо его допросить. Но сначала нужно приготовить сыворотку правды, и вот тут мне понадобится твоя помощь.$b$bПриготовление сыворотки – процесс кропотливый, он требует точных расчетов, безошибочной интуиции и способности к импровизации на каждом этапе.$b$bКогда будешь $gготов:готова;, дай мне знать, |3-6($r). И помни: самое главное – точный расчет времени!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Помогите алхимику Финкльштейну в Хеб\'Валоке в приготовлении сыворотки правды.$b$bКогда вы будете готовы приступить к работе, скажите об этом алхимику и выполняйте все его указания.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к алхимику Финкльштейну в Реликварий Боли, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12603,'Время точить когти','Доисторические драконы обитают в большинстве земель на севере и востоке; даже на таком расстоянии я ощущаю жар их дыхания. Но прежде, чем мы бросим вызов самым могущественным из них, нам следует испытать свои способности на менее опасных противниках.$B$BОднако не следует расслабляться: любой из них способен сожрать человека целиком. После того как убийство драконов станет для тебя обычным делом, возвращайся сюда: я скажу, каким будет следующий шаг.','Убейте 6 доисторических драконов, а затем поговорите с Дорианом Грозой Драконов в форпосте Дориана.','В твоих словах я слышу уверенность в себе. Что ж, это очень хорошо, приобретенный опыт поможет тебе в битве с Праматерью драконов.','Тебе удалось опробовать свои навыки в деле?','Вернитесь к Дориану Грозе Драконов на Форпост Дориана, что в Низине Шолазар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Время точить когти',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Доисторические драконы обитают в большинстве земель на севере и востоке; даже на таком расстоянии я ощущаю жар их дыхания. Но прежде, чем мы бросим вызов самым могущественным из них, нам следует испытать свои способности на менее опасных противниках.$B$BОднако не следует расслабляться: любой из них способен сожрать человека целиком. После того как убийство драконов станет для тебя обычным делом, возвращайся сюда: я скажу, каким будет следующий шаг.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 6 доисторических драконов, а затем поговорите с Дорианом Грозой Драконов в форпосте Дориана.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','В твоих словах я слышу уверенность в себе. Что ж, это очень хорошо, приобретенный опыт поможет тебе в битве с Праматерью драконов.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось опробовать свои навыки в деле?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дориану Грозе Драконов на Форпост Дориана, что в Низине Шолазар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (12604,'Поздравляем!','Ты $Gпоказал:показала; отличное время в этом дозоре. Похоже, ты все-таки можешь быть нам полезным.$B$BКак и было обещано, вот тебе вознаграждение за труды.$B$BПродолжай в том же духе, $N.$B$BСвободен.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поздравляем!',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты $Gпоказал:показала; отличное время в этом дозоре. Похоже, ты все-таки можешь быть нам полезным.$B$BКак и было обещано, вот тебе вознаграждение за труды.$B$BПродолжай в том же духе, $N.$B$BСвободен.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12605,'Подготовка ловушки','Не думаю, что мы сумеем привлечь внимание Праматери Сливины, если будем прыгать и размахивать руками как идиоты; но если мы будем умны, то сможем заставить ее выйти на бой. А заодно заготовим немного, м-м, корма для моего небольшого проекта.$B$B<Дориан бросает взгляд на Любопытсона.>$B$BНо пока что об этом не стоит беспокоиться. Найди яйца доисторических драконов к востоку и северо-востоку от нашего лагеря. Яйца нужно разбить, а дракончиков притащить сюда. Как только Праматерь узнает, что мы сделали, ей придется встретиться с нами.','Принесите Дориану Грозе Драконов 6 доисторических дракончиков в форпост Дориана.','Ну как, удалось найти хорошую наживку, чтобы привлечь внимание Праматери?','Вернитесь к Дориану Грозе Драконов на Форпост Дориана, что в Низине Шолазар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подготовка ловушки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не думаю, что мы сумеем привлечь внимание Праматери Сливины, если будем прыгать и размахивать руками как идиоты; но если мы будем умны, то сможем заставить ее выйти на бой. А заодно заготовим немного, м-м, корма для моего небольшого проекта.$B$B<Дориан бросает взгляд на Любопытсона.>$B$BНо пока что об этом не стоит беспокоиться. Найди яйца доисторических драконов к востоку и северо-востоку от нашего лагеря. Яйца нужно разбить, а дракончиков притащить сюда. Как только Праматерь узнает, что мы сделали, ей придется встретиться с нами.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Дориану Грозе Драконов 6 доисторических дракончиков в форпост Дориана.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как, удалось найти хорошую наживку, чтобы привлечь внимание Праматери?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дориану Грозе Драконов на Форпост Дориана, что в Низине Шолазар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12606,'В коконах','Теперь, когда тоннели засыпаны, нам нужно подумать о том, как спасти наших товарищей, попавших в плен к неприятелю.$b$bЕсли нам повезет, то вполне может статься, что некоторые наши солдаты еще живы и относительно здоровы внутри нерубских коконов.$b$bОсвободи их, |3-6($c), пока не поздно!','Вскройте нерубские коконы в Драк\'Сотре и вернитесь к капитану Руперту в Драк\'Сотру, освободив 3 взятых в плен пехотинцев.','Прядильные органы должны быть целыми, без изъянов, и тогда я смогу сделать из них устройство, которое может тебе пригодиться.','Вернитесь к капитану Руперту в Драк\'Сотру, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В коконах',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда тоннели засыпаны, нам нужно подумать о том, как спасти наших товарищей, попавших в плен к неприятелю.$b$bЕсли нам повезет, то вполне может статься, что некоторые наши солдаты еще живы и относительно здоровы внутри нерубских коконов.$b$bОсвободи их, |3-6($c), пока не поздно!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вскройте нерубские коконы в Драк\'Сотре и вернитесь к капитану Руперту в Драк\'Сотру, освободив 3 взятых в плен пехотинцев.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Прядильные органы должны быть целыми, без изъянов, и тогда я смогу сделать из них устройство, которое может тебе пригодиться.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Руперту в Драк\'Сотру, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (12607,'Поимка мамонта','Дориан решил, что прежде, чем отправиться на бой с Праматерью Сливиной, вам с Хемингом было бы неплохо научиться действовать сообща, оседлав мамонта.$B$BВокруг лагеря полно этих зверюг. Возьми уздечку и набрось ее на твердобивневого мамонта. Выбирай самочек. Самцы слишком опасны и терпеть не могут упряжи. Когда найдешь подходящего мамонта, веди его сюда.','Приведите Любопытсону в форпост Дориана твердобивневого мамонта.','Прекрасно! Единственное, что нам теперь нужно – добыть для Хеминга стремянку…','Вернитесь к Любопытсону на Форпост Дориана, что в Низине Шолазар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поимка мамонта',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Дориан решил, что прежде, чем отправиться на бой с Праматерью Сливиной, вам с Хемингом было бы неплохо научиться действовать сообща, оседлав мамонта.$B$BВокруг лагеря полно этих зверюг. Возьми уздечку и набрось ее на твердобивневого мамонта. Выбирай самочек. Самцы слишком опасны и терпеть не могут упряжи. Когда найдешь подходящего мамонта, веди его сюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Приведите Любопытсону в форпост Дориана твердобивневого мамонта.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно! Единственное, что нам теперь нужно – добыть для Хеминга стремянку…',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Любопытсону на Форпост Дориана, что в Низине Шолазар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (12608,'Вторжение сектантов','Поговорите с Аватарой Фрейи у водопадов Гласа Дождя.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вторжение сектантов',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Аватарой Фрейи у водопадов Гласа Дождя.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (12609,'Пополнение запасов','Слушай, |3-6($c). Я понимаю, что прошу слишком многого...$b$bДостать свежую паучью лимфу очень непросто, даже в этих зараженных краях. Но Финкльштейн говорит, что ему нужно ни много ни мало, а целый чан, причем чем скорее, тем лучше.$b$bМои люди сейчас собирают ему реагенты, и они просто не справятся с новым приказом алхимика вовремя. Им нужна помощь.$b$bКогда будешь в Зул\'Драке, смотри внимательно по сторонам: может, где и увидишь пауков-капканщиков. Принеси мне всю лимфу, которую сумеешь добыть.','Соберите 7 унций свежей паучьей лимфы от пауков-капканщиков в Зул\'Драке для капитана Арната из Хеб\'Валока.','Вернитесь к капитану Арнату в Хеб\'Валок, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пополнение запасов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слушай, |3-6($c). Я понимаю, что прошу слишком многого...$b$bДостать свежую паучью лимфу очень непросто, даже в этих зараженных краях. Но Финкльштейн говорит, что ему нужно ни много ни мало, а целый чан, причем чем скорее, тем лучше.$b$bМои люди сейчас собирают ему реагенты, и они просто не справятся с новым приказом алхимика вовремя. Им нужна помощь.$b$bКогда будешь в Зул\'Драке, смотри внимательно по сторонам: может, где и увидишь пауков-капканщиков. Принеси мне всю лимфу, которую сумеешь добыть.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 7 унций свежей паучьей лимфы от пауков-капканщиков в Зул\'Драке для капитана Арната из Хеб\'Валока.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Арнату в Хеб\'Валок, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12610,'Подрезанные крылышки','С тех пор как у нас появился Финкльштейн, я только и делаю, что собираю различные ингредиенты для его экспериментов и снадобий.$b$bЯ выполняю приказы, потому что таков долг солдата, но я все-таки воин и ветеран многих битв. Мое место – на передовой, мое дело – сражаться с врагом.$b$bПомоги мне, |3-6($r). Собери за меня крылья летучих мышей, чтобы я мог поскорее заняться настоящим делом.','Соберите 7 безукоризненных крыльев нетопырей в Зул\'Драке для капитана Арната из Хеб\'Валока.','Ты собрал крылья летучих мышей для Финкльштейна?','Вернитесь к капитану Арнату в Хеб\'Валок, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подрезанные крылышки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','С тех пор как у нас появился Финкльштейн, я только и делаю, что собираю различные ингредиенты для его экспериментов и снадобий.$b$bЯ выполняю приказы, потому что таков долг солдата, но я все-таки воин и ветеран многих битв. Мое место – на передовой, мое дело – сражаться с врагом.$b$bПомоги мне, |3-6($r). Собери за меня крылья летучих мышей, чтобы я мог поскорее заняться настоящим делом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 7 безукоризненных крыльев нетопырей в Зул\'Драке для капитана Арната из Хеб\'Валока.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты собрал крылья летучих мышей для Финкльштейна?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Арнату в Хеб\'Валок, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12611,'Семикратное воздаяние','Посланники Короля-лича сделали глупость, ступив в эти земли, где правит Жизнь. Все зло, которое они совершат, вернется к ним семикратно.$B$BЧудовище, ответственное за порчу, причиненную этой земле, носит имя Талгран Сеятель Гнили: ты сможешь найти его к северу отсюда. Возьми этот оберег и воспользуйся им, чтобы зло обратилось само против себя. Покажи войску Плети, что сила Жизни побеждает все!','Аватара Фрейи хочет, чтобы вы победили Талграна Сеятеля Гнили при помощи Оберега Фрейи, отразив его проклятия и обратив их против него.','Готово, $N?','Вернитесь к Аватаре Фрейи к водопадам Гласа Дождя, что в низине Шолазар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Семикратное воздаяние',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Посланники Короля-лича сделали глупость, ступив в эти земли, где правит Жизнь. Все зло, которое они совершат, вернется к ним семикратно.$B$BЧудовище, ответственное за порчу, причиненную этой земле, носит имя Талгран Сеятель Гнили: ты сможешь найти его к северу отсюда. Возьми этот оберег и воспользуйся им, чтобы зло обратилось само против себя. Покажи войску Плети, что сила Жизни побеждает все!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Аватара Фрейи хочет, чтобы вы победили Талграна Сеятеля Гнили при помощи Оберега Фрейи, отразив его проклятия и обратив их против него.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Готово, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аватаре Фрейи к водопадам Гласа Дождя, что в низине Шолазар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (12612,'Разрушенная колонна','Здесь титаны создавали самых разнообразных живых существ, и жизнь расцветала, не зная пределов.$B$BПять колонн, усыпанных кристаллами, окружают долину и источают чистую жизненную силу. Войско Плети не могло бы проникнуть сюда; но, к несчастью, одна из колонн была уничтожена.$B$BОтправляйся к колонне Жизненной Силы: возможно, ты сумеешь узнать, что произошло. Никто из нежити не мог приблизиться к ней: ищи живых врагов. Ты отыщешь то, что осталось от колонны, к югу от этого места.','Отправляйтесь к колонне Жизненной Силы и попытайтесь понять, как она была разрушена.','<Тело сильно обожжено. Поблизости вы находите то, что осталось от бочонков с порохом.>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разрушенная колонна',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Здесь титаны создавали самых разнообразных живых существ, и жизнь расцветала, не зная пределов.$B$BПять колонн, усыпанных кристаллами, окружают долину и источают чистую жизненную силу. Войско Плети не могло бы проникнуть сюда; но, к несчастью, одна из колонн была уничтожена.$B$BОтправляйся к колонне Жизненной Силы: возможно, ты сумеешь узнать, что произошло. Никто из нежити не мог приблизиться к ней: ищи живых врагов. Ты отыщешь то, что осталось от колонны, к югу от этого места.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь к колонне Жизненной Силы и попытайтесь понять, как она была разрушена.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Тело сильно обожжено. Поблизости вы находите то, что осталось от бочонков с порохом.>',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (12613,'Включение Связующей спирали: Дозор Творцов','Теперь мы не можем остановиться, |3-6($r). Первый переключатель сработал, остался еще один.$B$BТитаны создали другой наблюдательный пункт, чтобы следить за своими творениями. Ты найдешь его высоко в горах на востоке.$B$BЗадействуй активационный переключатель "тета", и Связующая спираль заработает.','Вернитесь к Аватаре Фрейи к водопадам Гласа Дождя, что в низине Шолазар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Включение Связующей спирали: Дозор Творцов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь мы не можем остановиться, |3-6($r). Первый переключатель сработал, остался еще один.$B$BТитаны создали другой наблюдательный пункт, чтобы следить за своими творениями. Ты найдешь его высоко в горах на востоке.$B$BЗадействуй активационный переключатель "тета", и Связующая спираль заработает.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аватаре Фрейи к водопадам Гласа Дождя, что в низине Шолазар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12614,'Материнский гнев','Праматерь Сливина наверняка в ярости: сейчас это настоящий вихрь клыков, шипов и когтей. Ты $gпохитил:похитила; ее детенышей, а это ни одной матери не придется по нраву.$B$BТо есть, конечно, яйца – это не совсем детеныши, но, видать, сами драконы придерживаются другого мнения.$B$BОна в ярости и отчаянье: именно такую добычу и любит Хеминг. Думаю, вы с Хемингом, да еще и на этом мамонте, станете для нее достойными противниками.$B$BПраматерь можно найти на северной границе Дикой чащи. Помни: она жаждет мести!','Убейте Праматерь Сливину и возвращайтесь к Дориану Грозе Драконов в форпост Дориана.','Я приготовил целую речь к твоему возвращению, но старик и сам хочет сказать тебе пару слов.','Что ж, ты $Gжив:жива;. Как поживаешь?','Вернитесь к Дориану Грозе Драконов на Форпост Дориана, что в Низине Шолазар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Материнский гнев',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Праматерь Сливина наверняка в ярости: сейчас это настоящий вихрь клыков, шипов и когтей. Ты $gпохитил:похитила; ее детенышей, а это ни одной матери не придется по нраву.$B$BТо есть, конечно, яйца – это не совсем детеныши, но, видать, сами драконы придерживаются другого мнения.$B$BОна в ярости и отчаянье: именно такую добычу и любит Хеминг. Думаю, вы с Хемингом, да еще и на этом мамонте, станете для нее достойными противниками.$B$BПраматерь можно найти на северной границе Дикой чащи. Помни: она жаждет мести!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Праматерь Сливину и возвращайтесь к Дориану Грозе Драконов в форпост Дориана.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я приготовил целую речь к твоему возвращению, но старик и сам хочет сказать тебе пару слов.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что ж, ты $Gжив:жива;. Как поживаешь?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дориану Грозе Драконов на Форпост Дориана, что в Низине Шолазар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12615,'Благословение Зим\'Торги','По поручению знахаря Кхуфу принесите 10 подношений Драккари к изваянию Зим\'Торги.','<Мысли Зим\'Торги проникают к вам в голову и сливаются с вашими мыслями. Она чувствует, что вы принесли ей дары, и остается довольной.>$B$B<Она дает вам понять, что подношение принято и вас ждет подобающая награда.>','<Вы чувствуете, что Мать Изобилия смотрит на вас. Ей любопытно, зачем такой |3-6($R) как вы, пришел к ней.>','Отнесите подношения Драккари к изваянию Зим\'Торги, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Благословение Зим\'Торги',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По поручению знахаря Кхуфу принесите 10 подношений Драккари к изваянию Зим\'Торги.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Мысли Зим\'Торги проникают к вам в голову и сливаются с вашими мыслями. Она чувствует, что вы принесли ей дары, и остается довольной.>$B$B<Она дает вам понять, что подношение принято и вас ждет подобающая награда.>',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Вы чувствуете, что Мать Изобилия смотрит на вас. Ей любопытно, зачем такой |3-6($R) как вы, пришел к ней.>',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите подношения Драккари к изваянию Зим\'Торги, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12616,'Тайная комната','Опытный искатель приключений! То, что нам надо.$b$bСреди членов Кирин-Тора, охраняющих башню Медива, ходят слухи, что в Каражане что-то нечисто. Мол, появилась там некая новая сила, что не имеет отношения ни к Стражу, ни к Легиону. Насколько им удалось выяснить, в этом замешан эльфийский принц по имени Тенрис Мутная Кровь, который без сомнения служит Плети.$b$bИди, друг мой, обыщи его комнату и возвращайся с любой информацией.','Посланник Серебряного Рассвета просит вас обыскать комнату Тенриса Мутная Кровь, которая находится среди комнат слуг в Каражане.','Информацию, которую ты сообщаешь действительно ужасна. Мы можем только надеяться, что миссия была остановлена ​​до того как противник не узнал о наших силах.$B$BСпасибо, $N. Береги себя в эти темные времена.','Что тебе удалось узнать?','Вернитесь к посланнику из ордена Серебряного Рассвета.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тайная комната',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Опытный искатель приключений! То, что нам надо.$b$bСреди членов Кирин-Тора, охраняющих башню Медива, ходят слухи, что в Каражане что-то нечисто. Мол, появилась там некая новая сила, что не имеет отношения ни к Стражу, ни к Легиону. Насколько им удалось выяснить, в этом замешан эльфийский принц по имени Тенрис Мутная Кровь, который без сомнения служит Плети.$b$bИди, друг мой, обыщи его комнату и возвращайся с любой информацией.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Посланник Серебряного Рассвета просит вас обыскать комнату Тенриса Мутная Кровь, которая находится среди комнат слуг в Каражане.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Информацию, которую ты сообщаешь действительно ужасна. Мы можем только надеяться, что миссия была остановлена ​​до того как противник не узнал о наших силах.$B$BСпасибо, $N. Береги себя в эти темные времена.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что тебе удалось узнать?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к посланнику из ордена Серебряного Рассвета.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12617,'Уничтожение захватчиков','Я – воплощение одного из аспектов Фрейи, дочери титанов. Я – Хранительница Жизни; меня оставили здесь, чтобы охранять долину от войск Плети.$B$BЯ никогда не думала, что Король-лич найдет живых слуг, готовых выполнить его задание.$B$BЯ могла бы и сама сокрушить этих сектантов, однако только я стою между этой долиной и воинством Плети... Иди же, $n. Стань орудием моего гнева, покарай тех, кто так бесстыдно вторгся в долину!','Аватара Фрейи, стоящая у водопадов Гласа Дождя, попросила вас отправиться в лагерь Руки Смерти на северо-западе и убить 8 секретных агентов сектантов.','Я чувствую, что ты говоришь правду. Пришедшие были уничтожены… но, боюсь, уже слишком поздно.','Ты $Gуничтожил:уничтожила; нарушителей, $N?','Вернитесь к Аватаре Фрейи к водопадам Гласа Дождя, что в низине Шолазар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уничтожение захватчиков',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я – воплощение одного из аспектов Фрейи, дочери титанов. Я – Хранительница Жизни; меня оставили здесь, чтобы охранять долину от войск Плети.$B$BЯ никогда не думала, что Король-лич найдет живых слуг, готовых выполнить его задание.$B$BЯ могла бы и сама сокрушить этих сектантов, однако только я стою между этой долиной и воинством Плети... Иди же, $n. Стань орудием моего гнева, покарай тех, кто так бесстыдно вторгся в долину!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Аватара Фрейи, стоящая у водопадов Гласа Дождя, попросила вас отправиться в лагерь Руки Смерти на северо-западе и убить 8 секретных агентов сектантов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я чувствую, что ты говоришь правду. Пришедшие были уничтожены… но, боюсь, уже слишком поздно.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gуничтожил:уничтожила; нарушителей, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аватаре Фрейи к водопадам Гласа Дождя, что в низине Шолазар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12618,'Благословение Зим\'Торги','<Мать Изобилия лучится счастьем. Благословение получено.>','<Зим\'Торга бесстрастно смотрит на вас. Она надеется, что вы преподнесете ей еще больше даров Драккари в знак уважения.>','Вернитесь в Зим\'Торгу в Зул\'Драк.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Благословение Зим\'Торги',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Мать Изобилия лучится счастьем. Благословение получено.>',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Зим\'Торга бесстрастно смотрит на вас. Она надеется, что вы преподнесете ей еще больше даров Драккари в знак уважения.>',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь в Зим\'Торгу в Зул\'Драк.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12619,'Украшенный рунический меч','Единственный и самый важный инструмент рыцаря смерти – это рунический меч. Именно с его помощью ты подчинишь себе магию льда, крови и нечестивости. Рунический меч – это сосуд, вмещающий силы рун рыцаря смерти.$B$BДа, рыцарь, настал твой час обрести собственный клинок. Осмотри оружейные стойки на этом этаже и найди затупившийся в боях меч, после чего отнеси его к ближайшей кузне рун и перекуй в рунический.','Обыщите оружейные стойки в Черном оплоте, найдите затупившийся в боях меч и перекуйте его в рунический меч в рунной кузне.$B$BПринесите готовый клинок инструктору Разувию в Черный оплот.','Рунический меч – это продолжение твоей руки. Рыцарь смерти – ничто без своего клинка.','Вернитесь к инструктору Разувию в Сердце Акеруса, что в Черном оплоте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Украшенный рунический меч',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Единственный и самый важный инструмент рыцаря смерти – это рунический меч. Именно с его помощью ты подчинишь себе магию льда, крови и нечестивости. Рунический меч – это сосуд, вмещающий силы рун рыцаря смерти.$B$BДа, рыцарь, настал твой час обрести собственный клинок. Осмотри оружейные стойки на этом этаже и найди затупившийся в боях меч, после чего отнеси его к ближайшей кузне рун и перекуй в рунический.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обыщите оружейные стойки в Черном оплоте, найдите затупившийся в боях меч и перекуйте его в рунический меч в рунной кузне.$B$BПринесите готовый клинок инструктору Разувию в Черный оплот.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Рунический меч – это продолжение твоей руки. Рыцарь смерти – ничто без своего клинка.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к инструктору Разувию в Сердце Акеруса, что в Черном оплоте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12620,'Гнев Хранительницы Жизни','Мы действовали слишком медленно, $n. Проклятые сектанты добрались до Мерцающей колонны и готовятся уничтожить ее. Я чувствую их присутствие.$B$BУ нас мало времени. Протруби в этот рог на вершине Мерцающей колонны, чтобы направить мою энергию в кристаллы.$B$BМы покажем этим фанатикам, что не стоит связываться с творениями титанов.','Аватара Фрейи у водопадов Гласа Дождя хочет, чтобы вы протрубили в Рог Фрейи на вершине Мерцающей колонны.','Впечатляюще. Для смертного существа ты действительно сильный союзник.$B$BНо наших усилий, похоже, было недостаточно. Войско Плети продолжает двигаться вперед.','Ты $Gпозаботился:позаботилась; о культистах, $N?','Вернитесь к Аватаре Фрейи к водопадам Гласа Дождя, что в низине Шолазар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гнев Хранительницы Жизни',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы действовали слишком медленно, $n. Проклятые сектанты добрались до Мерцающей колонны и готовятся уничтожить ее. Я чувствую их присутствие.$B$BУ нас мало времени. Протруби в этот рог на вершине Мерцающей колонны, чтобы направить мою энергию в кристаллы.$B$BМы покажем этим фанатикам, что не стоит связываться с творениями титанов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Аватара Фрейи у водопадов Гласа Дождя хочет, чтобы вы протрубили в Рог Фрейи на вершине Мерцающей колонны.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Впечатляюще. Для смертного существа ты действительно сильный союзник.$B$BНо наших усилий, похоже, было недостаточно. Войско Плети продолжает двигаться вперед.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gпозаботился:позаботилась; о культистах, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аватаре Фрейи к водопадам Гласа Дождя, что в низине Шолазар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12621,'Договор Фрейи','Мы разобрались с сектантами, однако вторжение Плети так и не удалось остановить. Положение становится отчаянным, $n.$B$BЕсть одно последнее средство. Но прежде чем я открою тебе его, я должна быть уверена, что тебе можно доверять.','Выслушайте то, что вам расскажет Аватара Фрейи.','Пути назад нет. Если согласишься помочь мне, это нужно делать без сомнений и колебаний.','У нас мало времени. Плеть готовится к последнему рывку.','Вернитесь к Аватаре Фрейи к водопадам Гласа Дождя, что в низине Шолазар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Договор Фрейи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы разобрались с сектантами, однако вторжение Плети так и не удалось остановить. Положение становится отчаянным, $n.$B$BЕсть одно последнее средство. Но прежде чем я открою тебе его, я должна быть уверена, что тебе можно доверять.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выслушайте то, что вам расскажет Аватара Фрейи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Пути назад нет. Если согласишься помочь мне, это нужно делать без сомнений и колебаний.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У нас мало времени. Плеть готовится к последнему рывку.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аватаре Фрейи к водопадам Гласа Дождя, что в низине Шолазар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12622,'Вожди у Джин\'Алаи','Знаешь, чего Ауне думать? $B$BМного троллей Драккари собрались у бассейна Джин\'Алаи, на юго-западе. Нам надо выманивать их вождей, и Ауне уже знает, как.$B$BТы ходишь туда, убиваешь всех троллей. Когда прикончишь много троллей, их вожди выйдут сами.$B$BИ, когда они появятся у своих тотемов, ты отберешь все сокровища у Кутубе\'сы, Гаванила и Чуло Безумного.','По поручению охотника за скальпами Ауне из Зим\'торги заберите сокровища у Кутубе\'сы, Гаванила и Чуло Безумного.','Вот это по-нашему, |3-6($R)!$B$BА это что за конфетки? Они нам зачем?$B$BАуне думать, что ты можешь их забирать себе!','|3-6($C), наверное, вернулся к Ауне, потому что |3-6($C) принес все сокровища.','Вернитесь к охотнику за скальпами Ауне в Зим\'Торгу, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вожди у Джин\'Алаи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Знаешь, чего Ауне думать? $B$BМного троллей Драккари собрались у бассейна Джин\'Алаи, на юго-западе. Нам надо выманивать их вождей, и Ауне уже знает, как.$B$BТы ходишь туда, убиваешь всех троллей. Когда прикончишь много троллей, их вожди выйдут сами.$B$BИ, когда они появятся у своих тотемов, ты отберешь все сокровища у Кутубе\'сы, Гаванила и Чуло Безумного.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По поручению охотника за скальпами Ауне из Зим\'торги заберите сокровища у Кутубе\'сы, Гаванила и Чуло Безумного.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот это по-нашему, |3-6($R)!$B$BА это что за конфетки? Они нам зачем?$B$BАуне думать, что ты можешь их забирать себе!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','|3-6($C), наверное, вернулся к Ауне, потому что |3-6($C) принес все сокровища.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к охотнику за скальпами Ауне в Зим\'Торгу, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (12623,'К знахарю','Нам, зандаларам, нужна твоя помощь, $n. Мы должны положить конец тем бесчинствам, которые Драккари творят со своими богами!$B$BНа северо-востоке, на великих ступенях, что ведут на следующий ярус Зул\'Драка, располагается Зим\'Торга – дом еще одного из богов, где пребывает его изваяние, и убежище, которое мы так отчаянно пытаемся защитить.$B$BЯ хочу, чтобы ты $gотправился:отправилась; туда и $gпоговорил:поговорила; со знахарем Кхуфу. И будь $gосторожен:осторожна;. Драккари совершают набеги на эти края беспрестанно.','Поговорите со знахарем Кхуфу в Зим\'Торге.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','К знахарю',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нам, зандаларам, нужна твоя помощь, $n. Мы должны положить конец тем бесчинствам, которые Драккари творят со своими богами!$B$BНа северо-востоке, на великих ступенях, что ведут на следующий ярус Зул\'Драка, располагается Зим\'Торга – дом еще одного из богов, где пребывает его изваяние, и убежище, которое мы так отчаянно пытаемся защитить.$B$BЯ хочу, чтобы ты $gотправился:отправилась; туда и $gпоговорил:поговорила; со знахарем Кхуфу. И будь $gосторожен:осторожна;. Драккари совершают набеги на эти края беспрестанно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите со знахарем Кхуфу в Зим\'Торге.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (12624,'Оно может быть где угодно!','Вернитесь к Чаду в Лагерь Эрнестуэя, что в Низине Шолазар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оно может быть где угодно!',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Чаду в Лагерь Эрнестуэя, что в Низине Шолазар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (12625,'Власть над Акерусом','Перед тобой Акерус, великая цитадель смерти! Ничто на земле не может с ней сравниться. Даже могучему Наксрамасу не устоять перед силами Черного оплота.$B$BХотя я чувствую смятение в твоих мыслях, у нас нет ни секунды на промедление. Ты $gдолжен:должна; собраться и взять власть над Акерусом в свои руки, ибо я уже слышу первые звуки боевых горнов.$B$BНа этом этаже со всех сторон есть лестницы, ведущие на верхний этаж, где располагаются наши войска. Найди там главного кузнеца крепости Корвия и потребуй у него отчет о состоянии дел. Таланор ждет нашего доклада.','Найдите главного кузнеца крепости Корвия на войсковом этаже Черного оплота.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Власть над Акерусом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Перед тобой Акерус, великая цитадель смерти! Ничто на земле не может с ней сравниться. Даже могучему Наксрамасу не устоять перед силами Черного оплота.$B$BХотя я чувствую смятение в твоих мыслях, у нас нет ни секунды на промедление. Ты $gдолжен:должна; собраться и взять власть над Акерусом в свои руки, ибо я уже слышу первые звуки боевых горнов.$B$BНа этом этаже со всех сторон есть лестницы, ведущие на верхний этаж, где располагаются наши войска. Найди там главного кузнеца крепости Корвия и потребуй у него отчет о состоянии дел. Таланор ждет нашего доклада.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите главного кузнеца крепости Корвия на войсковом этаже Черного оплота.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (12626,'Батальон Проклятых','<Корвий отдает вам честь.>$B$BНаши запасы оружия, брони и амуниции практически полны. Мы готовы к войне!$B$B<Корвий сворачивает в рулон толстый лист пергамента.>$B$BС другой стороны этажа, на юго-западе располагаются офицерские казармы. Возьми этот доклад и отнеси его Таланору, командиру батальона Проклятых.','Доставьте доклад Корвия Командиру сил Плети Таланору, находящемуся в офицерских казармах Черного оплота.','Вернитесь к командиру силу Плети Таланору в Чумные земли: Анклав Алого ордена.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Батальон Проклятых',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Корвий отдает вам честь.>$B$BНаши запасы оружия, брони и амуниции практически полны. Мы готовы к войне!$B$B<Корвий сворачивает в рулон толстый лист пергамента.>$B$BС другой стороны этажа, на юго-западе располагаются офицерские казармы. Возьми этот доклад и отнеси его Таланору, командиру батальона Проклятых.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте доклад Корвия Командиру сил Плети Таланору, находящемуся в офицерских казармах Черного оплота.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру силу Плети Таланору в Чумные земли: Анклав Алого ордена.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12627,'Прорыв в Джин\'Алаи','Я пытался поговорить с богами. Однако целители у бассейна Джин\'Алаи проводят ритуалы, которые препятствуют моим попыткам связаться с богами.$B$BНам надо развеять их чары. Это действительно очень важно. Я уверен, что где-то там, на юго-западе, ты найдешь котлы, которые они используют для своей магии.$B$BОпрокинь все котлы, чтобы помешать ритуалам, которые не дают мне говорить с богами.','По поручению знахаря Кхуфу из Зим\'Торги опрокиньте Синий котел, Зеленый котел, Фиолетовый котел и Красный котел.','Да, я уже чувствую разницу. Спасибо.$B$BПосмотрим, получится ли установить связь с богами теперь.','Я все еще не могу связаться. Ритуал знахари все еще не нарушен.$B$BПожалуйста, вернитесь туда и потревожь каждый из их котлов.','Вернитесь к знахарю Кхуфу в Зим\'Торгу, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прорыв в Джин\'Алаи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я пытался поговорить с богами. Однако целители у бассейна Джин\'Алаи проводят ритуалы, которые препятствуют моим попыткам связаться с богами.$B$BНам надо развеять их чары. Это действительно очень важно. Я уверен, что где-то там, на юго-западе, ты найдешь котлы, которые они используют для своей магии.$B$BОпрокинь все котлы, чтобы помешать ритуалам, которые не дают мне говорить с богами.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По поручению знахаря Кхуфу из Зим\'Торги опрокиньте Синий котел, Зеленый котел, Фиолетовый котел и Красный котел.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, я уже чувствую разницу. Спасибо.$B$BПосмотрим, получится ли установить связь с богами теперь.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я все еще не могу связаться. Ритуал знахари все еще не нарушен.$B$BПожалуйста, вернитесь туда и потревожь каждый из их котлов.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к знахарю Кхуфу в Зим\'Торгу, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (12628,'Разговор с Хар\'коа','Боги говорили с нами, $n. Теперь мы знаем, что тебе нужно сделать.$B$BИди к алтарю Хар\'коа к юго-востоку отсюда и поговори с богиней снежных леопардов.','Поговорите с Хар\'коа у алтаря Хар\'коа.','Слушай внимательно, малютка-|3-6($R). У нас мало времени, и дважды я повторять не буду.','Драккари сами себя истребляют, но будет жаль, если будет утеряна и история их империи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разговор с Хар\'коа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Боги говорили с нами, $n. Теперь мы знаем, что тебе нужно сделать.$B$BИди к алтарю Хар\'коа к юго-востоку отсюда и поговори с богиней снежных леопардов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Хар\'коа у алтаря Хар\'коа.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Слушай внимательно, малютка-|3-6($R). У нас мало времени, и дважды я повторять не буду.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Драккари сами себя истребляют, но будет жаль, если будет утеряна и история их империи.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (12629,'Можно убежать, но нельзя скрыться','Когда Плеть видит цель, она не остановится ни перед чем на пути к этой цели.$b$bМы обречены на бессмысленное существование ходячих трупов...$b$b<Стефан кривит губы в жестокой усмешке.>$b$b... если мы не сумеем обратить их стремления против них самих.$b$bЯ все объясню, но позже. Сейчас мне нужно подготовить одно достаточно сложное заклинание, для которого мне понадобятся определенные материальные компоненты.$b$bИди на восток, за Реликварий Агонии. Убей поганищ, собери слюну вурдалаков, которых там встретишь, и принеси мне их останки.','Вернитесь к Стефану Ваду на Черную заставу, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Можно убежать, но нельзя скрыться',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда Плеть видит цель, она не остановится ни перед чем на пути к этой цели.$b$bМы обречены на бессмысленное существование ходячих трупов...$b$b<Стефан кривит губы в жестокой усмешке.>$b$b... если мы не сумеем обратить их стремления против них самих.$b$bЯ все объясню, но позже. Сейчас мне нужно подготовить одно достаточно сложное заклинание, для которого мне понадобятся определенные материальные компоненты.$b$bИди на восток, за Реликварий Агонии. Убей поганищ, собери слюну вурдалаков, которых там встретишь, и принеси мне их останки.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Стефану Ваду на Черную заставу, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12630,'Насса надо как следует пнуть','Прежде чем ты познакомишься с Нассом, ты $gдолжен:должна; кое-что уяснить.$b$bОн принял токсическую дозу гнили, в результате чего ослеп, оглох и практически утратил чувствительность.$b$bНо все не так плохо. Сейчас у него стойкий иммунитет к этой гадости, и поэтому он идеально подходит для выполнения определенных работ – вроде той, что я собираюсь тебе поручить.$b$bТут поблизости много троллей Плети, и нам хотелось бы изучить, как на них действует гниль. Для этого нам нужны образцы их волос. Возьми с собой Насса и этот сапог. Когда убьешь тролля, пни Насса как следует, и он поймет, что надо выдрать у тролля прядь волос.','С помощью Насса соберите образцы волос 10 иссохших троллей для Стефана с Черной заставы.$b$bЕсли вы потеряете Насса, возвращайтесь к Стефану.','Как там сапог, $R?','Вернитесь к Стефану Ваду на Черную заставу, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Насса надо как следует пнуть',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прежде чем ты познакомишься с Нассом, ты $gдолжен:должна; кое-что уяснить.$b$bОн принял токсическую дозу гнили, в результате чего ослеп, оглох и практически утратил чувствительность.$b$bНо все не так плохо. Сейчас у него стойкий иммунитет к этой гадости, и поэтому он идеально подходит для выполнения определенных работ – вроде той, что я собираюсь тебе поручить.$b$bТут поблизости много троллей Плети, и нам хотелось бы изучить, как на них действует гниль. Для этого нам нужны образцы их волос. Возьми с собой Насса и этот сапог. Когда убьешь тролля, пни Насса как следует, и он поймет, что надо выдрать у тролля прядь волос.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','С помощью Насса соберите образцы волос 10 иссохших троллей для Стефана с Черной заставы.$b$bЕсли вы потеряете Насса, возвращайтесь к Стефану.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как там сапог, $R?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Стефану Ваду на Черную заставу, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (12631,'Приглашение','Вырезанное из кости и вымоченное в крови, это колье покрыто замысловатым узором.$b$bГлядя на этот узор, ты теряешь себя и подчиняешься зову зловещей силы – силы, которая требует, чтобы ты $gнадел:надела; его на себя. Однако ты можешь противиться этой силе, а значит, сумеешь отнести колье на Черную заставу.$b$bЕсли кто-то и сможет найти этому объяснение, то только рыцарь смерти...','Отнесите колье нежизни Стефану на Черную заставу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приглашение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вырезанное из кости и вымоченное в крови, это колье покрыто замысловатым узором.$b$bГлядя на этот узор, ты теряешь себя и подчиняешься зову зловещей силы – силы, которая требует, чтобы ты $gнадел:надела; его на себя. Однако ты можешь противиться этой силе, а значит, сумеешь отнести колье на Черную заставу.$b$bЕсли кто-то и сможет найти этому объяснение, то только рыцарь смерти...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите колье нежизни Стефану на Черную заставу.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12632,'Первым делом – мои дети','Меня покорят последней из всех богов, а это значит, что первым делом мы должны попытаться освободить остальных. Связанная колдовством своих покорителей, я не могу прозревать их судьбу.$B$BЯ попрошу тебя об одолжении. Драккари уже обратили мои чары против меня. Они превратили моих детей в безобразных уродов.$B$BВозьми мой ус. Убей моих измученных детей, и магия моего уса освободит их от кошмара и возродит к жизни.','Используйте удивительные свойства уса Хар\'коа для того, чтобы освободить и воскресить ее детей. Когда все будет сделано, вернитесь к Хар\'коа. Она ждет вас у алтаря.','У меня есть еще дети, которых ты должен освободить от мучений!','Вернитесь к Хар\'коа к алтарю Хар\'коа, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Первым делом – мои дети',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Меня покорят последней из всех богов, а это значит, что первым делом мы должны попытаться освободить остальных. Связанная колдовством своих покорителей, я не могу прозревать их судьбу.$B$BЯ попрошу тебя об одолжении. Драккари уже обратили мои чары против меня. Они превратили моих детей в безобразных уродов.$B$BВозьми мой ус. Убей моих измученных детей, и магия моего уса освободит их от кошмара и возродит к жизни.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте удивительные свойства уса Хар\'коа для того, чтобы освободить и воскресить ее детей. Когда все будет сделано, вернитесь к Хар\'коа. Она ждет вас у алтаря.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У меня есть еще дети, которых ты должен освободить от мучений!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хар\'коа к алтарю Хар\'коа, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (12633,'Зов тьмы','Вырезанное из кости и вымоченное в крови, это колье покрыто замысловатым узором.$b$bГлядя на этот узор, вы теряете себя и подчиняетесь зову зловещей силы – силы, которая требует, чтобы вы надели колье. Однако вы можете противиться этой силе, а значит, сумеете донести колье до Черной заставы.$b$bЕсли кто-то и сможет найти объяснение произошедшему, то только рыцарь смерти...','Отнесите змеевидное колье Стефану на Черную заставу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зов тьмы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вырезанное из кости и вымоченное в крови, это колье покрыто замысловатым узором.$b$bГлядя на этот узор, вы теряете себя и подчиняетесь зову зловещей силы – силы, которая требует, чтобы вы надели колье. Однако вы можете противиться этой силе, а значит, сумеете донести колье до Черной заставы.$b$bЕсли кто-то и сможет найти объяснение произошедшему, то только рыцарь смерти...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите змеевидное колье Стефану на Черную заставу.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12634,'Кому ликер, кому лимонад','На этот раз судьба подкинула мне полную тележку лимонов! Когда корабль выбросило на берег, все бочки с моей лучшей выпивкой разбились! У нас осталось всего несколько бутылок рома, а на тридцать участников экспедиции этого не хватит!$B$BНам нужно кое-что приготовить, причем поскорее!$B$BВ диких мангровых зарослях полно деревьев со спелыми фруктами, но мне до них не дотянуться. Посмотри, может, там есть какие-нибудь лианы, которые помогут стряхнуть фрукты с ветвей. Словом, тащи все, что удастся собрать.','Принесите Мрачнобуху Громовару в лагерь Эрнестуэя 1 апельсин, 2 грозди бананов и 1 папайю.','Удалось тебе собрать хоть немного фруктов с этих проклятых колючих деревьев?','Вернитесь к Мрачнобуху Громовару в Лагерь Эрнестуэя, что в Низине Шолазар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кому ликер, кому лимонад',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На этот раз судьба подкинула мне полную тележку лимонов! Когда корабль выбросило на берег, все бочки с моей лучшей выпивкой разбились! У нас осталось всего несколько бутылок рома, а на тридцать участников экспедиции этого не хватит!$B$BНам нужно кое-что приготовить, причем поскорее!$B$BВ диких мангровых зарослях полно деревьев со спелыми фруктами, но мне до них не дотянуться. Посмотри, может, там есть какие-нибудь лианы, которые помогут стряхнуть фрукты с ветвей. Словом, тащи все, что удастся собрать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Мрачнобуху Громовару в лагерь Эрнестуэя 1 апельсин, 2 грозди бананов и 1 папайю.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось тебе собрать хоть немного фруктов с этих проклятых колючих деревьев?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мрачнобуху Громовару в Лагерь Эрнестуэя, что в Низине Шолазар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12635,'Реликвии богини','Я слышал, ты собираешься к Хар\'коа. Удачи!$B$BМожет быть, соберешь для меня ее реликвии? Мне нужно немного, и тебе не придется идти далеко – всего лишь немного пройти на юго-восток.$B$BЧто скажешь?','Драккари сами себя истребляют, но будет жаль, если будет утеряна и история их империи.','Вернитесь к летописцу То\'кини в Зим\'Торгу, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Реликвии богини',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я слышал, ты собираешься к Хар\'коа. Удачи!$B$BМожет быть, соберешь для меня ее реликвии? Мне нужно немного, и тебе не придется идти далеко – всего лишь немного пройти на юго-восток.$B$BЧто скажешь?',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Драккари сами себя истребляют, но будет жаль, если будет утеряна и история их империи.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к летописцу То\'кини в Зим\'Торгу, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (12636,'Око Акеруса','Осмотрись – это Акерус, великая цитадель смерти! Ничто на земле не может с ней сравниться. Даже могучий Наксрамас не смог бы устоять против Черного оплота. А над некрополем виднеется тень всевидящего ока Акеруса. С его помощью наш повелитель может узреть то, что находится за гранью досягаемости, на территориях врагов. То, что видит око, видит и Король-лич. Теперь же настал твой час заглянуть в его глубины! Король-лич призывает тебя к себе, $n.$B$BИди же, и да продлятся твои страдания, $gбрат:сестра;...','Предстаньте перед Королем-личом в Черном оплоте.','Рунический меч – это продолжение твоей руки. $C – ничто без своего клинка.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Око Акеруса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Осмотрись – это Акерус, великая цитадель смерти! Ничто на земле не может с ней сравниться. Даже могучий Наксрамас не смог бы устоять против Черного оплота. А над некрополем виднеется тень всевидящего ока Акеруса. С его помощью наш повелитель может узреть то, что находится за гранью досягаемости, на территориях врагов. То, что видит око, видит и Король-лич. Теперь же настал твой час заглянуть в его глубины! Король-лич призывает тебя к себе, $n.$B$BИди же, и да продлятся твои страдания, $gбрат:сестра;...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Предстаньте перед Королем-личом в Черном оплоте.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Рунический меч – это продолжение твоей руки. $C – ничто без своего клинка.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12637,'Счастливое избавление','Ты $gпоступил:поступила; мудро, не надев это колье, |3-6($r). Или тебе просто повезло.$b$bКак бы там ни было, ты $gполучил:получила; его не случайно. Кто-то выбрал тебя. Кто-то или что-то... $b$bОтдай это колье Датуре Кровавой Розе. Пусть она продемонстрирует, какой страшной судьбы ты так счастливо $gизбежал:избежала;.','Отдайте колье нежизни Датуре Кровавой Розе.','Да, |3-6($r)?','Вернитесь к Стефану Ваду на Черную заставу, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Счастливое избавление',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gпоступил:поступила; мудро, не надев это колье, |3-6($r). Или тебе просто повезло.$b$bКак бы там ни было, ты $gполучил:получила; его не случайно. Кто-то выбрал тебя. Кто-то или что-то... $b$bОтдай это колье Датуре Кровавой Розе. Пусть она продемонстрирует, какой страшной судьбы ты так счастливо $gизбежал:избежала;.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отдайте колье нежизни Датуре Кровавой Розе.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да, |3-6($r)?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Стефану Ваду на Черную заставу, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12638,'На волосок от смерти','Ты $gпоступил:поступила; мудро, не надев это колье, |3-6($r). Или тебе просто повезло.$b$bКак бы там ни было, ты $gполучил:получила; его не случайно. Кто-то выбрал тебя. Кто-то или что-то... $b$bОтдай это колье Кровавой Розе. Пусть она продемонстрирует, какой кошмарной судьбы ты так счастливо $gизбежал:избежала;.','По предложению Стефана с Черной заставы отнесите змеевидное колье Датуре Кровавой Розе.','Теперь ты знаешь, какая судьба тебе грозила.$B$BКак я уже говорил, это все – не случайность. Изготовление подобного устройства – дело достаточно сложное, а значит, его создавали для какой-то конкретной цели. То есть, именно для тебя.$B$BТак что все очень просто: силы Плети хотят тебя заполучить... Что делать будем?','Да, $R?','Вернитесь к Стефану Ваду на Черную заставу, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На волосок от смерти',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gпоступил:поступила; мудро, не надев это колье, |3-6($r). Или тебе просто повезло.$b$bКак бы там ни было, ты $gполучил:получила; его не случайно. Кто-то выбрал тебя. Кто-то или что-то... $b$bОтдай это колье Кровавой Розе. Пусть она продемонстрирует, какой кошмарной судьбы ты так счастливо $gизбежал:избежала;.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По предложению Стефана с Черной заставы отнесите змеевидное колье Датуре Кровавой Розе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь ты знаешь, какая судьба тебе грозила.$B$BКак я уже говорил, это все – не случайность. Изготовление подобного устройства – дело достаточно сложное, а значит, его создавали для какой-то конкретной цели. То есть, именно для тебя.$B$BТак что все очень просто: силы Плети хотят тебя заполучить... Что делать будем?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да, $R?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Стефану Ваду на Черную заставу, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (12639,'Застывшая земля','Мы захватили этих элементалей неподалеку, и теперь у меня много защитников. Но чтобы они смогли выстоять против врагов, им надо придать много сил, на что уходит немало энергии.$B$BУ элементалей застывшей земли в Драк\'Мабве, к северо-западу отсюда, есть то, что мне нужно, чтобы поддерживать нашу защиту. Мне нужна их субстанция.','Принесите укротителю стихий Дагоде в Зим\'Торге 7 порций субстанции ледяной земли.','Вернитесь к укротителю стихий Дагоде в Зим\'Торгу, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Застывшая земля',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы захватили этих элементалей неподалеку, и теперь у меня много защитников. Но чтобы они смогли выстоять против врагов, им надо придать много сил, на что уходит немало энергии.$B$BУ элементалей застывшей земли в Драк\'Мабве, к северо-западу отсюда, есть то, что мне нужно, чтобы поддерживать нашу защиту. Мне нужна их субстанция.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите укротителю стихий Дагоде в Зим\'Торге 7 порций субстанции ледяной земли.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к укротителю стихий Дагоде в Зим\'Торгу, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12640,'Закрытие порталов','Дагода отправит тебя на северо-запад, в Драк\'Мабву, собирать всякое разное, нужное для ее защитников.$B$BКогда будешь там, Ауне хочет, чтоб ты $gуничтожил:уничтожила; порталы, сквозь которые вылезают все эти элементали. Меньше всего нам охота, чтоб они атаковали нас!$B$BТолько будь $gосторожен:осторожна;, когда будешь пытаться закрыть порталы: элементали застывшей земли сразу полезут со страшной силой, и их будет много.','По поручению охотника за скальпами Ауне из Зим\'торги закройте 7 порталов элементалей.','Ауне надеется очень-очень, что Дагода успеть получить всех защитников, сколько ей нужно. Теперь порталы закрыты, и больше она ничего не получит.','Надеюсь, ты принес мне достаточно субстанции. Атаки из района озер Джин\'Алаи сделались более яростными после того, что ты там у них натворил.','Вернитесь к охотнику за скальпами Ауне в Зим\'Торгу, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Закрытие порталов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Дагода отправит тебя на северо-запад, в Драк\'Мабву, собирать всякое разное, нужное для ее защитников.$B$BКогда будешь там, Ауне хочет, чтоб ты $gуничтожил:уничтожила; порталы, сквозь которые вылезают все эти элементали. Меньше всего нам охота, чтоб они атаковали нас!$B$BТолько будь $gосторожен:осторожна;, когда будешь пытаться закрыть порталы: элементали застывшей земли сразу полезут со страшной силой, и их будет много.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По поручению охотника за скальпами Ауне из Зим\'торги закройте 7 порталов элементалей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ауне надеется очень-очень, что Дагода успеть получить всех защитников, сколько ей нужно. Теперь порталы закрыты, и больше она ничего не получит.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Надеюсь, ты принес мне достаточно субстанции. Атаки из района озер Джин\'Алаи сделались более яростными после того, что ты там у них натворил.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к охотнику за скальпами Ауне в Зим\'Торгу, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12641,'Смерть подбирается с высоты','Око Акеруса возвышается над этой платформой. С его помощью ты вызовешь зонд и рассмотришь в деталях укрепления Алого ордена в Новом Авалоне, и благодаря особым способностям Ока сделать это проще простого.$B$BС помощью функции поглощения информации тебе нужно проанализировать кузню, ратушу, крепость и часовню. Механизмы управления Оком находятся по обе стороны этой платформы. Не теряй времени, $n.$B$BЭта земля будет принадлежать Плети, ибо того желает Король-лич!','Король-лич приказал вам заглянуть в Око Акеруса, чтобы осмотреть Крепость Алого ордена, Кузню Нового Авалона, Ратушу Нового Авалона и Часовню Багрового Пламени.$B$BДля этого воспользуйтесь механизмом управления Оком Акеруса.','Нашу победу над Алым орденом воспоют в легендах.','Вернитесь к Королю-личу в Черный оплот.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Смерть подбирается с высоты',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Око Акеруса возвышается над этой платформой. С его помощью ты вызовешь зонд и рассмотришь в деталях укрепления Алого ордена в Новом Авалоне, и благодаря особым способностям Ока сделать это проще простого.$B$BС помощью функции поглощения информации тебе нужно проанализировать кузню, ратушу, крепость и часовню. Механизмы управления Оком находятся по обе стороны этой платформы. Не теряй времени, $n.$B$BЭта земля будет принадлежать Плети, ибо того желает Король-лич!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Король-лич приказал вам заглянуть в Око Акеруса, чтобы осмотреть Крепость Алого ордена, Кузню Нового Авалона, Ратушу Нового Авалона и Часовню Багрового Пламени.$B$BДля этого воспользуйтесь механизмом управления Оком Акеруса.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Нашу победу над Алым орденом воспоют в легендах.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Королю-личу в Черный оплот.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (12642,'Дух Рунока','Мне что-то подсказывает, что у Рунока совсем мало времени.$B$BЯ доподлинно знаю, что дух бога белых медведей уже отделился от его ослабевшего тела. Тебе придется общаться с духом.$B$BЕго алтарь находится на северо-западе, за Драк\'Мабвой.','Поговорите с духом Рунока у алтаря Рунока.','Я едва держусь. Тебе надо действовать быстро, иначе все будет потеряно.','Драккари невозможно понять умом. Это племя изуверов и дикарей для которых нет ничего святого.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дух Рунока',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне что-то подсказывает, что у Рунока совсем мало времени.$B$BЯ доподлинно знаю, что дух бога белых медведей уже отделился от его ослабевшего тела. Тебе придется общаться с духом.$B$BЕго алтарь находится на северо-западе, за Драк\'Мабвой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с духом Рунока у алтаря Рунока.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я едва держусь. Тебе надо действовать быстро, иначе все будет потеряно.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Драккари невозможно понять умом. Это племя изуверов и дикарей для которых нет ничего святого.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (12643,'Серебряная отделка','Когда Плеть видит цель, она не остановится ни перед чем на пути к этой цели.$b$bМы обречены на бессмысленное существование ходячих трупов...$b$b<Стефан кривит губы в жестокой усмешке.>$b$b... если мы не сумеем обратить их стремления против них самих.$b$bЯ все объясню, но позже. Сейчас мне нужно подготовить одно достаточно сложное заклинание, для которого мне понадобятся определенные материальные компоненты.$b$bИди на восток, в край по ту сторону Реликвария Агонии. Убей вурдалаков и поганищ, которых там встретишь, и принеси мне их останки.','Вернитесь к Стефану Ваду на Черную заставу, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Серебряная отделка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда Плеть видит цель, она не остановится ни перед чем на пути к этой цели.$b$bМы обречены на бессмысленное существование ходячих трупов...$b$b<Стефан кривит губы в жестокой усмешке.>$b$b... если мы не сумеем обратить их стремления против них самих.$b$bЯ все объясню, но позже. Сейчас мне нужно подготовить одно достаточно сложное заклинание, для которого мне понадобятся определенные материальные компоненты.$b$bИди на восток, в край по ту сторону Реликвария Агонии. Убей вурдалаков и поганищ, которых там встретишь, и принеси мне их останки.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Стефану Ваду на Черную заставу, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12644,'Выпивка – дело тонкое...','Теперь, когда у нас есть сырье, я велю моему помощнику подготовить перегонный куб. Он проследит за процессом, но я хочу, чтобы ты все это $gконтролировал:контролировала;. Ты, может, считаешь, что мы бросаем в куб все разом, и оставляем его без присмотра? Так вот, это не так.$B$BИнгредиенты нужно добавлять в строго определенное время; к тому же, нужно регулировать температуру и давление. На то, чтобы принять решение, есть не более 10 секунд. Когда будешь $gготов:готова; приступить к дистилляции, поговори с "Поддатым" Макманусом.','Завершите процесс дистилляции и принесите пунш "Зов джунглей" Мрачнобуха Громовара в лагерь Эрнестуэя.','<Мрачнобух встряхивает бочонок.>$B$BТут, конечно, что-то есть, но вот вопрос на миллион золотых: можно ли это пить? Погоди, не уходи: возможно, тебе придется выяснить, хорош ли результат...','Ну, что у вас получилось?','Вернитесь к Мрачнобуху Громовару в Лагерь Эрнестуэя, что в Низине Шолазар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Выпивка – дело тонкое...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда у нас есть сырье, я велю моему помощнику подготовить перегонный куб. Он проследит за процессом, но я хочу, чтобы ты все это $gконтролировал:контролировала;. Ты, может, считаешь, что мы бросаем в куб все разом, и оставляем его без присмотра? Так вот, это не так.$B$BИнгредиенты нужно добавлять в строго определенное время; к тому же, нужно регулировать температуру и давление. На то, чтобы принять решение, есть не более 10 секунд. Когда будешь $gготов:готова; приступить к дистилляции, поговори с "Поддатым" Макманусом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Завершите процесс дистилляции и принесите пунш "Зов джунглей" Мрачнобуха Громовара в лагерь Эрнестуэя.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Мрачнобух встряхивает бочонок.>$B$BТут, конечно, что-то есть, но вот вопрос на миллион золотых: можно ли это пить? Погоди, не уходи: возможно, тебе придется выяснить, хорош ли результат...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, что у вас получилось?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мрачнобуху Громовару в Лагерь Эрнестуэя, что в Низине Шолазар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (12645,'Дегустация','Настал момент истины!$B$B<Мрачнобух хихикает.>$B$BВсегда хотел это сказать. Обычно я новую выпивку выставляю на каком-нибудь банкете, но в джунглях банкета не устроишь.$B$BТак что давай-ка ты отнесешь кое-кому из моих дорогих друзей новый напиток на пробу, а потом расскажешь, что они насчет него думают. Дай-ка подумать... меня совершенно точно интересует мнение Хеминга Эрнестуэя и Гадриуса Гарлоу. Они тут, в лагере. А еще сходи в лагерь у озера, что в центре долины, и предложи немного на пробу Тамаре Шестеркрут.','Предложите Хемингу Эрнестуэю, Гадриусу Гарлоу и Тамаре Шестеркрут попробовать пунш "Зов джунглей", а затем вернитесь к Мрачнобуху Громовару в лагерь Эрнестуэя.','Вернитесь к Мрачнобуху Громовару в Лагерь Эрнестуэя, что в Низине Шолазар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дегустация',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Настал момент истины!$B$B<Мрачнобух хихикает.>$B$BВсегда хотел это сказать. Обычно я новую выпивку выставляю на каком-нибудь банкете, но в джунглях банкета не устроишь.$B$BТак что давай-ка ты отнесешь кое-кому из моих дорогих друзей новый напиток на пробу, а потом расскажешь, что они насчет него думают. Дай-ка подумать... меня совершенно точно интересует мнение Хеминга Эрнестуэя и Гадриуса Гарлоу. Они тут, в лагере. А еще сходи в лагерь у озера, что в центре долины, и предложи немного на пробу Тамаре Шестеркрут.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Предложите Хемингу Эрнестуэю, Гадриусу Гарлоу и Тамаре Шестеркрут попробовать пунш "Зов джунглей", а затем вернитесь к Мрачнобуху Громовару в лагерь Эрнестуэя.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мрачнобуху Громовару в Лагерь Эрнестуэя, что в Низине Шолазар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12646,'Пророк мой – враг мой','Мой пророк слишком поспешно вобрал в себя всю мою силу – и не выдержал напряжения. Он покончил с собой. Последствия этого поступка хорошо видны у кратера, заполненного водой, к югу отсюда в Драк\'Мабве.$B$BМои бывшие жрецы уже воскресили его, чтобы он смог закончить свою работу. Они снова вливают в него мою силу, и уже очень скоро он должен проснуться.$B$BТебе надо его уничтожить и принести мне настой, пока не поздно.','Принесите духу Рунока настой бога белых медведей.','У тебя получилось!\n\nНо у меня есть еще одно поручение для тебя.','Быстрее, |3-6($R), ты принес мне настой?','Вернитесь к духу Рунока на алтарь Рунока, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пророк мой – враг мой',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мой пророк слишком поспешно вобрал в себя всю мою силу – и не выдержал напряжения. Он покончил с собой. Последствия этого поступка хорошо видны у кратера, заполненного водой, к югу отсюда в Драк\'Мабве.$B$BМои бывшие жрецы уже воскресили его, чтобы он смог закончить свою работу. Они снова вливают в него мою силу, и уже очень скоро он должен проснуться.$B$BТебе надо его уничтожить и принести мне настой, пока не поздно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите духу Рунока настой бога белых медведей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','У тебя получилось!\n\nНо у меня есть еще одно поручение для тебя.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Быстрее, |3-6($R), ты принес мне настой?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к духу Рунока на алтарь Рунока, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (12647,'Конец мучениям','Мое тело уже невозможно восстановить, $n. Настанет час, и они призовут нового пророка, который закончит то, что начали его предшественники.$B$BЯ отдам тебе всю силу, которая осталась во мне. У мучителя, который находится в храме у алтаря, есть фимиам, способный пробудить мое тело и сделать его уязвимым.$B$BВозьми фимиам и сделай мне одолжение: добей меня и положи конец моим мучениям.$B$BЯ заранее прошу прощения, если буду сопротивляться. Даже во мне воля к жизни сильна и неистребима.','Используйте фимиам мучителя, чтобы пробудить тело Рунока. Сила, которой вас наделил дух, поможет вам убить Рунока.$B$BЕсли по каким-то причинам аура амулета будет рассеяна, возвращайтесь к духу Рунока, чтобы возобновить эффект.','Вернитесь к духу Рунока на алтарь Рунока, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Конец мучениям',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мое тело уже невозможно восстановить, $n. Настанет час, и они призовут нового пророка, который закончит то, что начали его предшественники.$B$BЯ отдам тебе всю силу, которая осталась во мне. У мучителя, который находится в храме у алтаря, есть фимиам, способный пробудить мое тело и сделать его уязвимым.$B$BВозьми фимиам и сделай мне одолжение: добей меня и положи конец моим мучениям.$B$BЯ заранее прошу прощения, если буду сопротивляться. Даже во мне воля к жизни сильна и неистребима.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте фимиам мучителя, чтобы пробудить тело Рунока. Сила, которой вас наделил дух, поможет вам убить Рунока.$B$BЕсли по каким-то причинам аура амулета будет рассеяна, возвращайтесь к духу Рунока, чтобы возобновить эффект.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к духу Рунока на алтарь Рунока, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (12648,'Маскировка','Используйте заколдованное колье, чтобы замаскироваться под воина Плети.$b$bПребывая в личине воина Плети, купите для Стефана с Черной заставы горькую плазму у Гнилехряща.$b$bЕсли вы потеряете свое заколдованное колье, возвращайтесь к Стефану на Черную заставу, и он даст вам другое.','И как впечатления от жизни под властью Плети?$B$BПоверь мне на слово, все не совсем так, как о том говорят...','Вернитесь к Стефану Ваду на Черную заставу, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Маскировка',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте заколдованное колье, чтобы замаскироваться под воина Плети.$b$bПребывая в личине воина Плети, купите для Стефана с Черной заставы горькую плазму у Гнилехряща.$b$bЕсли вы потеряете свое заколдованное колье, возвращайтесь к Стефану на Черную заставу, и он даст вам другое.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','И как впечатления от жизни под властью Плети?$B$BПоверь мне на слово, все не совсем так, как о том говорят...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Стефану Ваду на Черную заставу, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (12649,'Переодевание','Используйте Заколдованное колье, чтобы замаскироваться под воина Плети.$b$bПребывая в личине воина Плети, купите горькую плазму у Гнилехряща.$b$bЕсли вы потеряете свое заколдованное колье, возвращайтесь к Стефану на Черную заставу, и он даст вам другое.','Вернитесь к Стефану Ваду на Черную заставу, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Переодевание',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте Заколдованное колье, чтобы замаскироваться под воина Плети.$b$bПребывая в личине воина Плети, купите горькую плазму у Гнилехряща.$b$bЕсли вы потеряете свое заколдованное колье, возвращайтесь к Стефану на Черную заставу, и он даст вам другое.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Стефану Ваду на Черную заставу, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12650,'Разграбленное святилище','Тут неподалеку есть еще один алтарь, откуда нужно спасти важные артефакты.$B$BГоворят, что Драккари у алтаря Рунока на северо-западе, по ту сторону разоренной тундры Драк\'Мабвы, уже разграбили свое собственное святилище.$B$B$C, мне бы очень хотелось, чтобы ты $gспас:спасла; эти священные артефакты, дабы они не попали в недостойные руки.','Принесите летописцу То\'кини в Зим\'Торгу 7 артефактов Рунока.','Драккари невозможно понять умом. Это племя изуверов и дикарей для которых нет ничего святого.','Вернитесь к летописцу То\'кини в Зим\'Торгу, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разграбленное святилище',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тут неподалеку есть еще один алтарь, откуда нужно спасти важные артефакты.$B$BГоворят, что Драккари у алтаря Рунока на северо-западе, по ту сторону разоренной тундры Драк\'Мабвы, уже разграбили свое собственное святилище.$B$B$C, мне бы очень хотелось, чтобы ты $gспас:спасла; эти священные артефакты, дабы они не попали в недостойные руки.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите летописцу То\'кини в Зим\'Торгу 7 артефактов Рунока.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Драккари невозможно понять умом. Это племя изуверов и дикарей для которых нет ничего святого.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к летописцу То\'кини в Зим\'Торгу, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (12651,'Лагерь у озера','Поговорите с Тамарой Шестеркрут в лагере у озера.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лагерь у озера',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Тамарой Шестеркрут в лагере у озера.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12652,'Преющие вурдалаки проголодались','Подь сюды! Эй, я к тебе обращаюсь!$b$bПора, значит, кормить вурдалаков.$b$bСегодня у них будет пир, чаша мозгов и кишок... ням-ням, вкуснятина.$b$bТут ничего сложного нет: подходишь к вурдалачику, ставишь перед ним чашку. И все, считай, подружились.$b$bХочешь дружить с вурдалаком? Ха-ха-ха!','По поручению Гнилехряща из Реликвария Агонии возьмите чашу мозгов и кишок и накормите 10 преющих вурдалаков.','Ням-ням!','Вурдалаки покормлены?','Вернитесь к Гнилехрящу в Реликварий Агонии, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Преющие вурдалаки проголодались',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Подь сюды! Эй, я к тебе обращаюсь!$b$bПора, значит, кормить вурдалаков.$b$bСегодня у них будет пир, чаша мозгов и кишок... ням-ням, вкуснятина.$b$bТут ничего сложного нет: подходишь к вурдалачику, ставишь перед ним чашку. И все, считай, подружились.$b$bХочешь дружить с вурдалаком? Ха-ха-ха!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По поручению Гнилехряща из Реликвария Агонии возьмите чашу мозгов и кишок и накормите 10 преющих вурдалаков.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ням-ням!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вурдалаки покормлены?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гнилехрящу в Реликварий Агонии, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (12653,'Назад к Хар\'коа','Тебе пора возвращаться к богине снежных леопардов. Мне что-то подсказывает, что у нее есть для тебя еще одно поручение.$B$BИ передай ей: что бы ни случилось, мы – вечны!','Поговорите с Хар\'коа у алтаря Хар\'коа.','<Зим\'Торга бесстрастно смотрит на вас. Она надеется, что, может быть, вы хотите преподнести ей еще больше даров Драккари в знак уважения.>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Назад к Хар\'коа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе пора возвращаться к богине снежных леопардов. Мне что-то подсказывает, что у нее есть для тебя еще одно поручение.$B$BИ передай ей: что бы ни случилось, мы – вечны!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Хар\'коа у алтаря Хар\'коа.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Зим\'Торга бесстрастно смотрит на вас. Она надеется, что, может быть, вы хотите преподнести ей еще больше даров Драккари в знак уважения.>',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12654,'Охотник на полставки','Когда Хеминг попросил меня сопровождать Марвина, я надеялась, что не буду все время заниматься ремонтом ветролетов и обустройством лагеря. $B$BЯ хотела убить одного злобного льва по прозвищу Острокол. Говорят, он обосновался к югу от лагеря – в том месте, где дикие мангровые заросли подходят к Колонне Небесного Пути с северной стороны. Если ты сумеешь найти эту тварь, может, принесешь мне его останки? Если слухи не врут, это будет такой трофей, которому и сам Эрнестуэй позавидует!','Доставьте останки Острокола Тамаре Шестеркрут в лагерь у озера.','Тебе удалось! Теперь мне только остается сделать трофей. Сохранить его внешний вид будет непросто... чтобы при этом Хеминг не высмеял приложенные мной усилия.','Тебе удалось разыскать Острокола?','Вернитесь к Тамаре Шестеркрут в Лагерь у озера, что в Низине Шолазар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охотник на полставки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда Хеминг попросил меня сопровождать Марвина, я надеялась, что не буду все время заниматься ремонтом ветролетов и обустройством лагеря. $B$BЯ хотела убить одного злобного льва по прозвищу Острокол. Говорят, он обосновался к югу от лагеря – в том месте, где дикие мангровые заросли подходят к Колонне Небесного Пути с северной стороны. Если ты сумеешь найти эту тварь, может, принесешь мне его останки? Если слухи не врут, это будет такой трофей, которому и сам Эрнестуэй позавидует!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте останки Острокола Тамаре Шестеркрут в лагерь у озера.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебе удалось! Теперь мне только остается сделать трофей. Сохранить его внешний вид будет непросто... чтобы при этом Хеминг не высмеял приложенные мной усилия.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось разыскать Острокола?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тамаре Шестеркрут в Лагерь у озера, что в Низине Шолазар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12655,'Благословение Зим\'Рука','Есть еще один бог Зул\'Драка, о котором ныне забыли.$B$BИзваяние Зим\'Рука находится прямо на севере. Известный под именем "Мудрый", Зим\'Рук славен еще и тем, как ревностно он защищает свои владения. Он создал стражей, которые убивают или калечат любого, кому не хватает ума и хитрости проскользнуть мимо них незамеченным.$B$BПроберись к Зим\'Руку так, чтобы стражи тебя не заметили, одари его подношениями Драккари и получи его благословение.','По поручению знахаря Кхуфу принесите 10 подношений Драккари к изваянию Зим\'Рука.','<Вы чувствуете, что Зим\'Рук вам не доверяет. Он пытается вызвать одного из своих стражей.>','Отнесите подношения Драккари к изваянию Зим\'Рука, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Благословение Зим\'Рука',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Есть еще один бог Зул\'Драка, о котором ныне забыли.$B$BИзваяние Зим\'Рука находится прямо на севере. Известный под именем "Мудрый", Зим\'Рук славен еще и тем, как ревностно он защищает свои владения. Он создал стражей, которые убивают или калечат любого, кому не хватает ума и хитрости проскользнуть мимо них незамеченным.$B$BПроберись к Зим\'Руку так, чтобы стражи тебя не заметили, одари его подношениями Драккари и получи его благословение.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По поручению знахаря Кхуфу принесите 10 подношений Драккари к изваянию Зим\'Рука.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Вы чувствуете, что Зим\'Рук вам не доверяет. Он пытается вызвать одного из своих стражей.>',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите подношения Драккари к изваянию Зим\'Рука, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12656,'Благословение Зим\'Рука','<Зим\'Рук посылает вам мысленный образ, как один из его стражей наступает на вас ногой и расплющивает в лепешку. Вероятно, вам стоит попробовать умилостивить Зим\'Рука и принести ему еще больше даров.>','<Зим\'Рук поражен и в то же время разочарован, что вам вновь удалось обмануть его стражей. Во всяком случае, на этот раз.>$B$B<Принесите ему подношение, и он снова одарит вас своим благословением.>','Вернитесь в Зим\'Рук в Зул\'Драк.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Благословение Зим\'Рука',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Зим\'Рук посылает вам мысленный образ, как один из его стражей наступает на вас ногой и расплющивает в лепешку. Вероятно, вам стоит попробовать умилостивить Зим\'Рука и принести ему еще больше даров.>',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Зим\'Рук поражен и в то же время разочарован, что вам вновь удалось обмануть его стражей. Во всяком случае, на этот раз.>$B$B<Принесите ему подношение, и он снова одарит вас своим благословением.>',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь в Зим\'Рук в Зул\'Драк.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (12657,'Мощь Плети','Слушай меня, рыцарь смерти, ибо мои слова развяжут великую войну. Я вынес свой приговор: смерть. Всем. И каждому. Никто более не посмеет бросать вызов Плети, не понеся должного наказания.$B$BТы верно $gпослужил:послужила; мне, выполнив первое поручение, и теперь я ожидаю от тебя не меньшего усердия. Передай мой приказ верховному лорду Могрейну на командный пост Акеруса. Скажи ему, что мы начинаем наступление.$B$BА когда Алый орден падет, мы покончим с Серебряным Рассветом.','Король-лич приказал вам передать его распоряжения верховному лорду Дариону Могрейну в Черный оплот.$B$BЧтобы попасть на командный пост, воспользуйтесь мерцающим телепортом позади Короля-лича.','Рунический меч – это продолжение твоей руки. $C – ничто без своего клинка.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мощь Плети',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слушай меня, рыцарь смерти, ибо мои слова развяжут великую войну. Я вынес свой приговор: смерть. Всем. И каждому. Никто более не посмеет бросать вызов Плети, не понеся должного наказания.$B$BТы верно $gпослужил:послужила; мне, выполнив первое поручение, и теперь я ожидаю от тебя не меньшего усердия. Передай мой приказ верховному лорду Могрейну на командный пост Акеруса. Скажи ему, что мы начинаем наступление.$B$BА когда Алый орден падет, мы покончим с Серебряным Рассветом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Король-лич приказал вам передать его распоряжения верховному лорду Дариону Могрейну в Черный оплот.$B$BЧтобы попасть на командный пост, воспользуйтесь мерцающим телепортом позади Короля-лича.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Рунический меч – это продолжение твоей руки. $C – ничто без своего клинка.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12658,'Моя ручная птица Рух','Дориан отдает мне дракончиков, которых ему удается поймать, чтобы я дрессировал и кормил их; но тут мне как-то вдруг пришло в голову, что я тоже хочу завести домашнего любимца.$B$BНет-нет, молодой дракончик не пойдет: мне не нужен любимец, который может руку откусить!$B$BНо к востоку от нашего лагеря, в Полях Костей, за теми землями, где живут драконы, обитает множество рухов-кровокрылов. Взрослого руха приручить невозможно, но если бы ты $gпринес:принесла; мне яйца, я мог бы воспитывать птенцов с того момента, как они вылупятся...','Принесите Любопытсону в форпост Дориана 7 яиц руха.','О, как это чудесно! Мне уже надоели белки-роботы и цыплята: это не лучшая компания. И как замечательно иметь домашнего зверька, которому не нужно смазывать суставы машинным маслом!','Тебе удалось раздобыть яйца?','Вернитесь к Любопытсону на Форпост Дориана, что в Низине Шолазар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Моя ручная птица Рух',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Дориан отдает мне дракончиков, которых ему удается поймать, чтобы я дрессировал и кормил их; но тут мне как-то вдруг пришло в голову, что я тоже хочу завести домашнего любимца.$B$BНет-нет, молодой дракончик не пойдет: мне не нужен любимец, который может руку откусить!$B$BНо к востоку от нашего лагеря, в Полях Костей, за теми землями, где живут драконы, обитает множество рухов-кровокрылов. Взрослого руха приручить невозможно, но если бы ты $gпринес:принесла; мне яйца, я мог бы воспитывать птенцов с того момента, как они вылупятся...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Любопытсону в форпост Дориана 7 яиц руха.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, как это чудесно! Мне уже надоели белки-роботы и цыплята: это не лучшая компания. И как замечательно иметь домашнего зверька, которому не нужно смазывать суставы машинным маслом!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось раздобыть яйца?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Любопытсону на Форпост Дориана, что в Низине Шолазар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12659,'Скальпы!','Самое время, $gдружище:подруга;, снять парочку скальпов! $B$BТролли в Хеб\'Драккар, что к северо-востоку, вполне подойдут. А то они вечно на нас нападают с этими своими дубинами, так что сами, считай, напросились!$B$BАуне даже даст тебе свой нож, чтобы было сподручнее.','По поручению Ауне из Зим\'торги возьмите нож Ауне и снимите скальпы с 10 хеб\'драккарских троллей.$B$BНе забывайте, сначала троллей следует обыскать.','Что? Ты уже все?\n\nНадеюсь, ты задал хорошую трепку этим пакостным ледяным троллям?','Вернитесь к охотнику за скальпами Ауне в Зим\'Торгу, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Скальпы!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Самое время, $gдружище:подруга;, снять парочку скальпов! $B$BТролли в Хеб\'Драккар, что к северо-востоку, вполне подойдут. А то они вечно на нас нападают с этими своими дубинами, так что сами, считай, напросились!$B$BАуне даже даст тебе свой нож, чтобы было сподручнее.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По поручению Ауне из Зим\'торги возьмите нож Ауне и снимите скальпы с 10 хеб\'драккарских троллей.$B$BНе забывайте, сначала троллей следует обыскать.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что? Ты уже все?\n\nНадеюсь, ты задал хорошую трепку этим пакостным ледяным троллям?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к охотнику за скальпами Ауне в Зим\'Торгу, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12660,'Орудия разрушения','Прислужники Короля-лича посмели принести орудия разрушения в мои владения. Я не потерплю этого.$B$BОтправляйся в их лагерь на северо-западе и уничтожь все, что они могут использовать против нас. Мы не позволим слугам Плети осквернить эту священную землю!','По поручению Аватары Фрейи отправляйтесь в лагерь Руки Смерти на северо-запад и уничтожьте 4 единицы нестабильной взрывчатки.','Готово, $N?','Вернитесь к Аватаре Фрейи к водопадам Гласа Дождя, что в низине Шолазар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Орудия разрушения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прислужники Короля-лича посмели принести орудия разрушения в мои владения. Я не потерплю этого.$B$BОтправляйся в их лагерь на северо-западе и уничтожь все, что они могут использовать против нас. Мы не позволим слугам Плети осквернить эту священную землю!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По поручению Аватары Фрейи отправляйтесь в лагерь Руки Смерти на северо-запад и уничтожьте 4 единицы нестабильной взрывчатки.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Готово, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аватаре Фрейи к водопадам Гласа Дождя, что в низине Шолазар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12661,'На разведку в Волтар','Должно быть, ты уже $gдогадался:догадалась;, в чем состоит мой план.$b$bПлеть проявляет к тебе интерес, и мы этим воспользуемся. Ты будешь нашим лазутчиком в стане врага. Я понимаю, что это похоже на смертный приговор, но если мы будем сидеть сложа руки, то ты умрешь в любом случае.$b$bИди на северо-восток к Реликварию Боли и встань на платформу, надев маскировку. Когда ты проникнешь в Волтар, тебе нужно будет втереться в доверие к командиру Плети.$b$bКогда все будет готово, протруби в этот рог, и я прилечу к тебе, чтобы выслушать твой отчет.','По поручению Стефана используйте заколдованное колье, чтобы пробраться в Волтар. Там вы должны делать все, о чем вас попросит предводитель сил Плети.$b$bЕсли вы потеряете Заколдованное колье, возвращайтесь к Стефану на Черную заставу, и он даст вам другое.','Ты $Gзаслужил:заслужила; доверие их командира, $N?','Вернитесь к Стефану Ваду на Черную заставу, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На разведку в Волтар',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Должно быть, ты уже $gдогадался:догадалась;, в чем состоит мой план.$b$bПлеть проявляет к тебе интерес, и мы этим воспользуемся. Ты будешь нашим лазутчиком в стане врага. Я понимаю, что это похоже на смертный приговор, но если мы будем сидеть сложа руки, то ты умрешь в любом случае.$b$bИди на северо-восток к Реликварию Боли и встань на платформу, надев маскировку. Когда ты проникнешь в Волтар, тебе нужно будет втереться в доверие к командиру Плети.$b$bКогда все будет готово, протруби в этот рог, и я прилечу к тебе, чтобы выслушать твой отчет.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По поручению Стефана используйте заколдованное колье, чтобы пробраться в Волтар. Там вы должны делать все, о чем вас попросит предводитель сил Плети.$b$bЕсли вы потеряете Заколдованное колье, возвращайтесь к Стефану на Черную заставу, и он даст вам другое.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gзаслужил:заслужила; доверие их командира, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Стефану Ваду на Черную заставу, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12662,'Смерть Хеб\'Джина','<Дагода смотрит на Ауне и вздыхает.>$B$BТы действительно хочешь идти в Хеб\'Драккар к тамошним троллям? Охота за скальпами – это, конечно же, замечательно. Но этого мало. Тебе нужно убить их вождя, Хеб\'Джина.$B$BПроблема в том, что он сейчас наверху, в гнездовье нетопырей, собирает войска.$B$BУдарь в его барабан, и он наверняка слетит вниз. И вот тогда ты его и убьешь.$B$BВозьми эту сеть, которую мы отобрали у одного из его охотников за головами. Набрось эту сеть на его нетопыря, когда он приземлится. И тогда тебе не придется сражаться с ними обоими.','По заданию укротителя стихий Дагоды из Зим\'Торги убейте Хеб\'Джина.','Что? Ты уже все?\n\nНадеюсь, ты задал хорошую трепку этим пакостным ледяным троллям?','Вернитесь к укротителю стихий Дагоде в Зим\'Торгу, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Смерть Хеб\'Джина',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Дагода смотрит на Ауне и вздыхает.>$B$BТы действительно хочешь идти в Хеб\'Драккар к тамошним троллям? Охота за скальпами – это, конечно же, замечательно. Но этого мало. Тебе нужно убить их вождя, Хеб\'Джина.$B$BПроблема в том, что он сейчас наверху, в гнездовье нетопырей, собирает войска.$B$BУдарь в его барабан, и он наверняка слетит вниз. И вот тогда ты его и убьешь.$B$BВозьми эту сеть, которую мы отобрали у одного из его охотников за головами. Набрось эту сеть на его нетопыря, когда он приземлится. И тогда тебе не придется сражаться с ними обоими.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По заданию укротителя стихий Дагоды из Зим\'Торги убейте Хеб\'Джина.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что? Ты уже все?\n\nНадеюсь, ты задал хорошую трепку этим пакостным ледяным троллям?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к укротителю стихий Дагоде в Зим\'Торгу, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12663,'Воссоединение','$n!$b$bСтало быть, ты $gполучил:получила; мой подарочек! А ну, поворотись, дай-ка я на тебя погляжу... да, я прямо тобой горжусь.$b$bМы прошли долгий путь вместе, а теперь вместе будем служить Королю-личу.$b$bДержись меня, $gдруг:подруга;, и мы замутим великие дела. Да, великие дела... но сначала нам надо, типа, ввести тебя в курс всего. С тех пор как мы виделись в последний раз, тут у нас многое изменилось!$b$bИди к Кровомесу, обговори с ним детали похода в Зул\'Драк. А потом я тебе расскажу что да как. Ну, типа, все, что тебе надо знать.','По заданию Дракуру из Волтара поговорите с Кровомесом и отправляйтесь в Зул\'Драк.','Ты и я, гунна, возьмем Гундрака, дружище.','Вернитесь к властителю Дракуру в Волтар, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Воссоединение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n!$b$bСтало быть, ты $gполучил:получила; мой подарочек! А ну, поворотись, дай-ка я на тебя погляжу... да, я прямо тобой горжусь.$b$bМы прошли долгий путь вместе, а теперь вместе будем служить Королю-личу.$b$bДержись меня, $gдруг:подруга;, и мы замутим великие дела. Да, великие дела... но сначала нам надо, типа, ввести тебя в курс всего. С тех пор как мы виделись в последний раз, тут у нас многое изменилось!$b$bИди к Кровомесу, обговори с ним детали похода в Зул\'Драк. А потом я тебе расскажу что да как. Ну, типа, все, что тебе надо знать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По заданию Дракуру из Волтара поговорите с Кровомесом и отправляйтесь в Зул\'Драк.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты и я, гунна, возьмем Гундрака, дружище.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к властителю Дракуру в Волтар, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12664,'Темный горизонт','Ага, еще $gодин проситель ответил:одна просительница ответила; на зов Короля-лича.$b$b<Дракуру обнюхивает вас.>$b$b$gНовообращенный:Новообращенная;, да? От тебя все еще сильно воняет жизнью!$b$bМногие приходят выпрашивать милостей у Короля-лича. Если хочешь возвыситься над этим стадом, докажи, что $gдостоин:достойна; обладать истинной силой.$b$bОглядывая Зул\'Драк, я сразу почувствовал, что у тебя неплохой потенциал. Вот я, стало быть, и отправил тебе приглашение.$b$bА что будет дальше, зависит только от тебя...$b$bСтупай к Кровомесу, обговори с ним детали похода в Зул\'Драк. У меня для тебя будет, типа, работенка, а там уж посмотрим, чего ты стоишь.','По заданию Дракуру из Волтара поговорите с Кровомесом и отправляйтесь в Зул\'Драк.','Теперь ты знаешь, с чем нам придется столкнуться.$B$BСпускайся туда, изучи территорию, постарайся смешаться со своими собратьями. И готовься...$B$BУже очень скоро для тебя будет, типа, работа.','Ты уже $Gпобывал:побывала; на поле битвы, дружище?','Вернитесь к властителю Дракуру в Волтар, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Темный горизонт',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ага, еще $gодин проситель ответил:одна просительница ответила; на зов Короля-лича.$b$b<Дракуру обнюхивает вас.>$b$b$gНовообращенный:Новообращенная;, да? От тебя все еще сильно воняет жизнью!$b$bМногие приходят выпрашивать милостей у Короля-лича. Если хочешь возвыситься над этим стадом, докажи, что $gдостоин:достойна; обладать истинной силой.$b$bОглядывая Зул\'Драк, я сразу почувствовал, что у тебя неплохой потенциал. Вот я, стало быть, и отправил тебе приглашение.$b$bА что будет дальше, зависит только от тебя...$b$bСтупай к Кровомесу, обговори с ним детали похода в Зул\'Драк. У меня для тебя будет, типа, работенка, а там уж посмотрим, чего ты стоишь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По заданию Дракуру из Волтара поговорите с Кровомесом и отправляйтесь в Зул\'Драк.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь ты знаешь, с чем нам придется столкнуться.$B$BСпускайся туда, изучи территорию, постарайся смешаться со своими собратьями. И готовься...$B$BУже очень скоро для тебя будет, типа, работа.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты уже $Gпобывал:побывала; на поле битвы, дружище?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к властителю Дракуру в Волтар, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (12665,'Дурное предчувствие','Что-то случилось с Кетц\'лун, богиней крылатых змеев. Не знаю, что именно – не могу это почувствовать, – знаю только, что ее алтарь захватили могучие, сильные существа.$B$BНемедленно отправляйся туда. Ты поедешь верхом на одном из моих котят, спасенных тобою. Действуйте быстро и скрытно и узнайте, что стало с Кетц\'лун.$B$BПотом мой отпрыск доставит тебя обратно.$B$BКогда будешь $gготов:готова;, дай мне знать, и я позову одного из своих котят.','Узнайте, что случилось с Кетц\'лун. Хар\'коа даст вам в помощь одного из своих детей, чтобы незаметно пробраться к алтарю Кетц\'лун.$B$BКогда все выясните, возвращайтесь обратно к Хар\'коа – она ждет вас у своего алтаря.','Кажется, задержка, $N?','Судьба Кетц\'Лун выяснена.','Вернитесь к Хар\'коа к алтарю Хар\'коа, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дурное предчувствие',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что-то случилось с Кетц\'лун, богиней крылатых змеев. Не знаю, что именно – не могу это почувствовать, – знаю только, что ее алтарь захватили могучие, сильные существа.$B$BНемедленно отправляйся туда. Ты поедешь верхом на одном из моих котят, спасенных тобою. Действуйте быстро и скрытно и узнайте, что стало с Кетц\'лун.$B$BПотом мой отпрыск доставит тебя обратно.$B$BКогда будешь $gготов:готова;, дай мне знать, и я позову одного из своих котят.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Узнайте, что случилось с Кетц\'лун. Хар\'коа даст вам в помощь одного из своих детей, чтобы незаметно пробраться к алтарю Кетц\'лун.$B$BКогда все выясните, возвращайтесь обратно к Хар\'коа – она ждет вас у своего алтаря.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Кажется, задержка, $N?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Судьба Кетц\'Лун выяснена.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хар\'коа к алтарю Хар\'коа, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12666,'Путешествие в Нижний мир','Может быть, Кетц\'лун и мертва, но я чувствую, что ее дух задержался в Нижнем мире у алтаря. Тебе нужно проникнуть туда. Сейчас мы подумаем, как это сделать.$B$BК счастью для нас, тут полно бывших последователей, которым уже не нужны их священные украшения. Скорее всего, мои усмирители и Когти носят их до сих пор.$B$BПринеси мне украшения, и я использую их энергию, чтобы перенести тебя в Нижний мир к Кетц\'лун.','Соберите 8 священных украшений и принесите их Хар\'коа к алтарю Хар\'коа.','<Богиня снежных леопардов смотрит на священные символы, которые вы принесли, и ее взгляд наполняется печалью.>$B$BБыло время, когда они что-то значили. Ладно, посмотрим, сумеем ли мы найти им более достойное применение.','Я не думала, что до этого дойдет. Драккари и вправду потеряны для нас.','Вернитесь к Хар\'коа к алтарю Хар\'коа, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путешествие в Нижний мир',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Может быть, Кетц\'лун и мертва, но я чувствую, что ее дух задержался в Нижнем мире у алтаря. Тебе нужно проникнуть туда. Сейчас мы подумаем, как это сделать.$B$BК счастью для нас, тут полно бывших последователей, которым уже не нужны их священные украшения. Скорее всего, мои усмирители и Когти носят их до сих пор.$B$BПринеси мне украшения, и я использую их энергию, чтобы перенести тебя в Нижний мир к Кетц\'лун.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 священных украшений и принесите их Хар\'коа к алтарю Хар\'коа.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Богиня снежных леопардов смотрит на священные символы, которые вы принесли, и ее взгляд наполняется печалью.>$B$BБыло время, когда они что-то значили. Ладно, посмотрим, сумеем ли мы найти им более достойное применение.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я не думала, что до этого дойдет. Драккари и вправду потеряны для нас.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хар\'коа к алтарю Хар\'коа, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (12667,'Поиски богини крылатых змеев','Ты $gподготовлен:подготовлена; неплохо, но у меня нет уверенности, что ты действительно $gготов:готова; к тому, что тебя ждет.$B$BКогда ты снова пойдешь к алтарю Кетц\'лун, тебе придется войти в царство мертвых. Если судить по тому, что я знаю, это будет не самый приятный опыт.$B$BПусть тебя не смущает то, что ты там увидишь. Ни на что не отвлекайся – просто иди к алтарю и разыщи дух Кетц\'лун.','Разыщите дух Кетц\'лун у алтаря Кетц\'лун.','|3-6($C), жалкий червяк. Скажи, что помешает мне уничтожить тебя на месте?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поиски богини крылатых змеев',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gподготовлен:подготовлена; неплохо, но у меня нет уверенности, что ты действительно $gготов:готова; к тому, что тебя ждет.$B$BКогда ты снова пойдешь к алтарю Кетц\'лун, тебе придется войти в царство мертвых. Если судить по тому, что я знаю, это будет не самый приятный опыт.$B$BПусть тебя не смущает то, что ты там увидишь. Ни на что не отвлекайся – просто иди к алтарю и разыщи дух Кетц\'лун.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите дух Кетц\'лун у алтаря Кетц\'лун.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','|3-6($C), жалкий червяк. Скажи, что помешает мне уничтожить тебя на месте?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12668,'Задел для мести','Для моих любимых верховных жрецов у меня приготовлено кое-что особенное. Но сначала я должна тебя испытать, чтобы знать, чего ты стоишь. Мне нужен хороший задел для мести, и ты этим займешься.$B$BТы ведь хочешь жить, да?$B$BКак ты $gсам уже видел:сама уже видела;, моим приверженцам нравится здесь, но их время уже пришло – время платить по последним счетам.$B$BСделай мне маленькое одолжение, $n. Замани их поближе к моим Темным купелям и убей.$B$BОни очень вкусные, так что их жертва не пропадет втуне, можешь не сомневаться.','Убейте 12 троллей из числа служителей Кетц\'лун или помешанных на змеях берсерков рядом с Темными купелями.$B$BПотом вернитесь к Кетц\'лун, которая будет ждать вас у алтаря.','Бесподобно. Быть может, ты все же на что-то годишься.','Почему ты возвращаешься, если твоя задача еще не выполнена? Разве ты не понимаешь, что я могу уничтожить тебя одной лишь мыслью?$B$BИди, маленький $R. Выполни то, что я тебе приказал!','Вернитесь к духу Кетц\'лун на алтарь Кетц\'лун, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Задел для мести',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Для моих любимых верховных жрецов у меня приготовлено кое-что особенное. Но сначала я должна тебя испытать, чтобы знать, чего ты стоишь. Мне нужен хороший задел для мести, и ты этим займешься.$B$BТы ведь хочешь жить, да?$B$BКак ты $gсам уже видел:сама уже видела;, моим приверженцам нравится здесь, но их время уже пришло – время платить по последним счетам.$B$BСделай мне маленькое одолжение, $n. Замани их поближе к моим Темным купелям и убей.$B$BОни очень вкусные, так что их жертва не пропадет втуне, можешь не сомневаться.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 троллей из числа служителей Кетц\'лун или помешанных на змеях берсерков рядом с Темными купелями.$B$BПотом вернитесь к Кетц\'лун, которая будет ждать вас у алтаря.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Бесподобно. Быть может, ты все же на что-то годишься.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Почему ты возвращаешься, если твоя задача еще не выполнена? Разве ты не понимаешь, что я могу уничтожить тебя одной лишь мыслью?$B$BИди, маленький $R. Выполни то, что я тебе приказал!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к духу Кетц\'лун на алтарь Кетц\'лун, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12669,'Пока все идет на удивление паршиво','Добытые тобой сведения согласуются с тем, что мы уже знаем. Тебе надо как следует изучить Дракуру и втереться к нему в доверие.$b$bВозвращайся к нему и делай все, что он скажет. Постарайся, как следует, $n. Он должен поверить в искренность твоих намерений. От того, как ты сыграешь свою роль, зависит наше будущее.$b$bНа этот раз у тебя будет еще одно, дополнительное задание: как только представится возможность, подлей эту присадку в их чумные котлы. Она нейтрализует отравляющий реактив, так что их снадобье сделается бесполезным.','По поручению Стефана с Черной заставы вернитесь к Дракуру и выполняйте его приказы.$b$bКогда вернетесь в Реликварий Боли, вылейте растворитель в 5 котлов Плети.$b$bЕсли вы потеряете свое заколдованное колье, возвращайтесь к Стефану на Черную заставу, и он даст вам другое.','Пожалуйста, $N, скажи мне, что ты не $Gраскрыл:раскрыла; свое прикрытие...','Вернитесь к Стефану Ваду на Черную заставу, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пока все идет на удивление паршиво',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Добытые тобой сведения согласуются с тем, что мы уже знаем. Тебе надо как следует изучить Дракуру и втереться к нему в доверие.$b$bВозвращайся к нему и делай все, что он скажет. Постарайся, как следует, $n. Он должен поверить в искренность твоих намерений. От того, как ты сыграешь свою роль, зависит наше будущее.$b$bНа этот раз у тебя будет еще одно, дополнительное задание: как только представится возможность, подлей эту присадку в их чумные котлы. Она нейтрализует отравляющий реактив, так что их снадобье сделается бесполезным.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По поручению Стефана с Черной заставы вернитесь к Дракуру и выполняйте его приказы.$b$bКогда вернетесь в Реликварий Боли, вылейте растворитель в 5 котлов Плети.$b$bЕсли вы потеряете свое заколдованное колье, возвращайтесь к Стефану на Черную заставу, и он даст вам другое.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Пожалуйста, $N, скажи мне, что ты не $Gраскрыл:раскрыла; свое прикрытие...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Стефану Ваду на Черную заставу, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (12670,'Жатва Алых','Разлом Смерти – наш оплот под Акерусом и плацдарм, с которого начнется наступление на Алый орден. Сейчас ты возьмешь грифона из стойл, находящихся по обе стороны платформы, и отправишься туда с докладом к принцу Валанару. Служи ему верой и правдой – и тогда, возможно, ты доживешь до того дня, когда все эти земли падут перед нами.','Доложите о своем прибытии в Разлом Смерти принцу Валанару.','Рунический меч – это продолжение твоей руки. $C – ничто без своего клинка.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жатва Алых',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Разлом Смерти – наш оплот под Акерусом и плацдарм, с которого начнется наступление на Алый орден. Сейчас ты возьмешь грифона из стойл, находящихся по обе стороны платформы, и отправишься туда с докладом к принцу Валанару. Служи ему верой и правдой – и тогда, возможно, ты доживешь до того дня, когда все эти земли падут перед нами.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доложите о своем прибытии в Разлом Смерти принцу Валанару.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Рунический меч – это продолжение твоей руки. $C – ничто без своего клинка.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`) VALUES (12671,'Разведывательный полет','Думаю, пришло время запускать моторы и взлетать. Профессор меня просит выяснить, что это за странное погодное явление приближается к нам с северо-востока.$B$BНо штука в том, что мне понадобится второй пилот: места-то неисследованные... Короче, тролля с два я туда один полечу, ясно?$B$BНу, что ты на это скажешь, $gкрутой парень:красотка;? Может, чему полезному научишься. А уж если сумеешь справиться с северными ветрами, тогда вообще летай, куда хочешь!','Помогите пилоту Вику совершить разведывательный полет.','Разведывательный полет') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разведывательный полет',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Думаю, пришло время запускать моторы и взлетать. Профессор меня просит выяснить, что это за странное погодное явление приближается к нам с северо-востока.$B$BНо штука в том, что мне понадобится второй пилот: места-то неисследованные... Короче, тролля с два я туда один полечу, ясно?$B$BНу, что ты на это скажешь, $gкрутой парень:красотка;? Может, чему полезному научишься. А уж если сумеешь справиться с северными ветрами, тогда вообще летай, куда хочешь!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Помогите пилоту Вику совершить разведывательный полет.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Разведывательный полет',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12672,'Подготовка к мести','Я дам тебе шанс уцелеть.$B$BФрагменты силы, которая питает мое проклятие, рассеяны вокруг алтаря. Я хочу, чтобы ты $gсобрал и принес:собрала и принесла; их сюда. Не так много, чтобы снять проклятие, и все же достаточно для того, чтобы я смогла отомстить своему пророку.$B$BИди, $gничтожный:ничтожная;. Выполни мой приказ, пока я настроена подарить тебе жизнь. А то я могу и передумать.','Соберите 10 потусторонних энергетических фрагментов и вернитесь к алтарю Кетц\'лун.','Да, этого будет достаточно. Хотя теперь они вряд ли понадобятся.$B$BВпрочем, было забавно смотреть, как ты носишься по округе, выполняя мое повеление.','Жаль, что Хар\'коа не прислала тебя ко мне раньше. Хотя мы с ней никогда не ладили.$B$BВполне вероятно, что она специально тебя придержала, чтобы то, что случилось, успело случиться.','Вернитесь к духу Кетц\'лун на алтарь Кетц\'лун, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подготовка к мести',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я дам тебе шанс уцелеть.$B$BФрагменты силы, которая питает мое проклятие, рассеяны вокруг алтаря. Я хочу, чтобы ты $gсобрал и принес:собрала и принесла; их сюда. Не так много, чтобы снять проклятие, и все же достаточно для того, чтобы я смогла отомстить своему пророку.$B$BИди, $gничтожный:ничтожная;. Выполни мой приказ, пока я настроена подарить тебе жизнь. А то я могу и передумать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 потусторонних энергетических фрагментов и вернитесь к алтарю Кетц\'лун.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, этого будет достаточно. Хотя теперь они вряд ли понадобятся.$B$BВпрочем, было забавно смотреть, как ты носишься по округе, выполняя мое повеление.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Жаль, что Хар\'коа не прислала тебя ко мне раньше. Хотя мы с ней никогда не ладили.$B$BВполне вероятно, что она специально тебя придержала, чтобы то, что случилось, успело случиться.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к духу Кетц\'лун на алтарь Кетц\'лун, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (12673,'Сбор кристаллов','Если хочешь стать, типа, $gдостойным:достойной; даров Короля-лича, тебе надо бы научиться, как быть великим вождем – чтобы те, кто тебе подчиняются, тебя уважали! А то!$b$bУ меня как раз есть для тебя работенка, $gдружище:подруга;, так сказать, для пущего усовершенствования командных навыков...$b$bСейчас я обучаю своих упырят, чтобы они собирали кристаллы гнили, но они на удивление тупы и ленивы. В общем, бери их себе в подчинение.$b$bВот тебе скипетр, типа, орудие внушения и вразумления. Твоя задача – заставить этих ленивцев работать. Веди их вниз, и пусть они собирают кристаллы!','Командир Дракуру в Волтарасе хочет, чтобы вы взяли скипетр внушения и с его помощью заставили гнилостных упырей собрать 7 кристаллов гнили.','Вернитесь к властителю Дракуру в Волтар, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сбор кристаллов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если хочешь стать, типа, $gдостойным:достойной; даров Короля-лича, тебе надо бы научиться, как быть великим вождем – чтобы те, кто тебе подчиняются, тебя уважали! А то!$b$bУ меня как раз есть для тебя работенка, $gдружище:подруга;, так сказать, для пущего усовершенствования командных навыков...$b$bСейчас я обучаю своих упырят, чтобы они собирали кристаллы гнили, но они на удивление тупы и ленивы. В общем, бери их себе в подчинение.$b$bВот тебе скипетр, типа, орудие внушения и вразумления. Твоя задача – заставить этих ленивцев работать. Веди их вниз, и пусть они собирают кристаллы!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Командир Дракуру в Волтарасе хочет, чтобы вы взяли скипетр внушения и с его помощью заставили гнилостных упырей собрать 7 кристаллов гнили.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к властителю Дракуру в Волтар, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12674,'Вся ярость преисподней','Ну что же, пора наказать моих верховных жрецов: Му\'фуну, Туа-Туа и Хавинни. Ты найдешь их вблизи алтаря.$B$BВозьми этот проклинающий жезл. Я зарядила его своей яростью и мощью. Это сильное оружие.$B$BУбей всех троих. А об остальном позаботится наложенное мной проклятие.$B$B<Кетц\'лун ехидно улыбается.>$B$BЕсли ты это сделаешь, может быть, я позволю тебе уйти. Если не сделаешь, ты умрешь.','По поручению духа Кетц\'Лун воздействуйте проклинаающим жезлом Кетц\'лун на верховного жреца Му\'фуну, верховную жрицу Туа-Туа и верховного жреца Хавинни. После этого вы должны их убить.','<Ужасный дух издает хриплый смех, от которого кровь стынет в жилах.>$B$BОни получили по заслугам. И я позабочусь о том, чтобы все повторялось для них... вновь и вновь, вновь и вновь...','ТЫ ДУМАЕШЬ, ЧТО Я ДУРАК?$B$BОНИ НЕ МЕРТВЫ!','Вернитесь к духу Кетц\'лун на алтарь Кетц\'лун, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вся ярость преисподней',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну что же, пора наказать моих верховных жрецов: Му\'фуну, Туа-Туа и Хавинни. Ты найдешь их вблизи алтаря.$B$BВозьми этот проклинающий жезл. Я зарядила его своей яростью и мощью. Это сильное оружие.$B$BУбей всех троих. А об остальном позаботится наложенное мной проклятие.$B$B<Кетц\'лун ехидно улыбается.>$B$BЕсли ты это сделаешь, может быть, я позволю тебе уйти. Если не сделаешь, ты умрешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По поручению духа Кетц\'Лун воздействуйте проклинаающим жезлом Кетц\'лун на верховного жреца Му\'фуну, верховную жрицу Туа-Туа и верховного жреца Хавинни. После этого вы должны их убить.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Ужасный дух издает хриплый смех, от которого кровь стынет в жилах.>$B$BОни получили по заслугам. И я позабочусь о том, чтобы все повторялось для них... вновь и вновь, вновь и вновь...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','ТЫ ДУМАЕШЬ, ЧТО Я ДУРАК?$B$BОНИ НЕ МЕРТВЫ!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к духу Кетц\'лун на алтарь Кетц\'лун, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12675,'И последнее...','У меня почти все готово, чтобы отомстить моему пророку, но мне нужно еще одно... самое главное. Фрагменты силы, которые ты $gсобрал:собрала;, нужно соединить с порцией духа живого бога. Тебе придется пойти к Хар\'коа и попросить, чтобы она дала тебе часть своего духа.$B$BКогда вернешься сюда, не иди в Нижний мир. Иди в материальный мир моего алтаря. Мои дети и стражи не тронут тебя, и ты спокойно пройдешь к моему пророку.','Отнесите Хар\'коа потусторонние энергетические фрагменты и попросите ее зарядить их частичкой ее духа. Вы найдете ее у алтаря Хар\'коа.','Часть моего духа?$B$B<Богиня снежных леопардов молчит, размышляя над вашей просьбой.>$B$BЭтот дар дорого тебе обойдется – тем более, если учесть, что он нужен для мести, а я сама сильно ослаблена действиями моих покорителей.$B$BИ все же я, кажется, знаю способ, как это сделать.','Ты $Gвернулся:вернулась;, $N.','Вернитесь к Хар\'коа к алтарю Хар\'коа, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','И последнее...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У меня почти все готово, чтобы отомстить моему пророку, но мне нужно еще одно... самое главное. Фрагменты силы, которые ты $gсобрал:собрала;, нужно соединить с порцией духа живого бога. Тебе придется пойти к Хар\'коа и попросить, чтобы она дала тебе часть своего духа.$B$BКогда вернешься сюда, не иди в Нижний мир. Иди в материальный мир моего алтаря. Мои дети и стражи не тронут тебя, и ты спокойно пройдешь к моему пророку.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите Хар\'коа потусторонние энергетические фрагменты и попросите ее зарядить их частичкой ее духа. Вы найдете ее у алтаря Хар\'коа.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Часть моего духа?$B$B<Богиня снежных леопардов молчит, размышляя над вашей просьбой.>$B$BЭтот дар дорого тебе обойдется – тем более, если учесть, что он нужен для мести, а я сама сильно ослаблена действиями моих покорителей.$B$BИ все же я, кажется, знаю способ, как это сделать.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gвернулся:вернулась;, $N.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хар\'коа к алтарю Хар\'коа, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12676,'Диверсия','Пока мы пытаемся разобраться с предназначением этих кристаллов, нам нужно, чтобы ты $gвернулся:вернулась; в Волтар к Дракуру.$b$bВыполняй все его поручения. Пусть он видит, как ты стараешься. И тогда, может быть, он решит, что тебе можно довериться, и посвятит тебя в свои планы. Нам нужно знать, что он задумал.$b$bИ у тебя будет еще одно задание. Повозки Плети Дракуру представляют серьезную опасность. Их следует уничтожить. $b$bПроберись к повозкам, активируй эти заряды и немедленно уходи, чтобы тебя не накрыло взрывной волной!','По поручению Стефана с Черной заставы продолжайте выполнять поручения Дракуру.$b$bКроме того, активируйте заряды взрывчатки, чтобы уничтожить 5 повозок Плети в Реликварии Боли.$b$bЕсли вы потеряете свое заколдованное колье, возвращайтесь к Стефану на Черную заставу, и он даст вам другое.','Тебе удалось уничтожить эти повозки Плети?','Вернитесь к Стефану Ваду на Черную заставу, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Диверсия',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пока мы пытаемся разобраться с предназначением этих кристаллов, нам нужно, чтобы ты $gвернулся:вернулась; в Волтар к Дракуру.$b$bВыполняй все его поручения. Пусть он видит, как ты стараешься. И тогда, может быть, он решит, что тебе можно довериться, и посвятит тебя в свои планы. Нам нужно знать, что он задумал.$b$bИ у тебя будет еще одно задание. Повозки Плети Дракуру представляют серьезную опасность. Их следует уничтожить. $b$bПроберись к повозкам, активируй эти заряды и немедленно уходи, чтобы тебя не накрыло взрывной волной!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По поручению Стефана с Черной заставы продолжайте выполнять поручения Дракуру.$b$bКроме того, активируйте заряды взрывчатки, чтобы уничтожить 5 повозок Плети в Реликварии Боли.$b$bЕсли вы потеряете свое заколдованное колье, возвращайтесь к Стефану на Черную заставу, и он даст вам другое.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось уничтожить эти повозки Плети?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Стефану Ваду на Черную заставу, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (12677,'Опасные материалы','Кристаллы гнили?! Что он там затевает, этот мерзавец Дракуру?$b$bВполне очевидно, что он работает над каким-то действительно важным проектом. Продолжай служить ему "верой и правдой", и когда он узнает тебя получше, может быть, он посвятит тебя в свои планы.$b$bА нам надо бы посмотреть, что это за кристаллы.$b$bКогда будешь в Волтаре, постарайся как-нибудь незаметно добыть образцы кристаллов.$b$bНо будь $gосторожен:осторожна;! Соприкосновение с этими кристаллами может нарушить твою маскировку.','По поручению Стефана с Черной заставы вернитесь в Волтар и продолжайте выполнять поручения Дракуру. Также вам нужно украсть 5 добытых кристаллов гнили.$b$bЕсли вы потеряете свое заколдованное колье, возвращайтесь к Стефану на Черную заставу, и он даст вам другое.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Опасные материалы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кристаллы гнили?! Что он там затевает, этот мерзавец Дракуру?$b$bВполне очевидно, что он работает над каким-то действительно важным проектом. Продолжай служить ему "верой и правдой", и когда он узнает тебя получше, может быть, он посвятит тебя в свои планы.$b$bА нам надо бы посмотреть, что это за кристаллы.$b$bКогда будешь в Волтаре, постарайся как-нибудь незаметно добыть образцы кристаллов.$b$bНо будь $gосторожен:осторожна;! Соприкосновение с этими кристаллами может нарушить твою маскировку.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По поручению Стефана с Черной заставы вернитесь в Волтар и продолжайте выполнять поручения Дракуру. Также вам нужно украсть 5 добытых кристаллов гнили.$b$bЕсли вы потеряете свое заколдованное колье, возвращайтесь к Стефану на Черную заставу, и он даст вам другое.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12678,'Когда Хаос правит бал, Страдание заказывает музыку','Они сейчас стоят у стен Разлома Смерти, тщетно пытаясь сдержать наш натиск, чтобы выиграть время для спасения лошадей, рудников, лесопилок и рабочих.$B$BНа их примере я преподам тебе первый урок военного искусства Плети: битвы выигрываются СТРАХОМ!$B$BОтправляйся к их передовым отрядам, осадившим нас на юге, и убей крестоносцев Алого ордена. Их тела мы используем для создания собственной армии.$B$BНапоследок расправься с убегающими крестьянами. Мертвыми солдатами уже никого не напугать, но смерть безвинных людей посеет страх.','Принц Валанар из Разлома Смерти приказал вам убить 10 крестоносцев Алого ордена или 10 крестьян из Алого ордена и 10 граждан Тихоземья.','Это лишь увертюра, рыцарь смерти. Наш марш смерти начнется с уничтожения их авангарда.','Вернитесь к принцу Валанару в Разлом Смерти, что в Чумных землях: Анклав Алого ордена.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Когда Хаос правит бал, Страдание заказывает музыку',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Они сейчас стоят у стен Разлома Смерти, тщетно пытаясь сдержать наш натиск, чтобы выиграть время для спасения лошадей, рудников, лесопилок и рабочих.$B$BНа их примере я преподам тебе первый урок военного искусства Плети: битвы выигрываются СТРАХОМ!$B$BОтправляйся к их передовым отрядам, осадившим нас на юге, и убей крестоносцев Алого ордена. Их тела мы используем для создания собственной армии.$B$BНапоследок расправься с убегающими крестьянами. Мертвыми солдатами уже никого не напугать, но смерть безвинных людей посеет страх.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принц Валанар из Разлома Смерти приказал вам убить 10 крестоносцев Алого ордена или 10 крестьян из Алого ордена и 10 граждан Тихоземья.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Это лишь увертюра, рыцарь смерти. Наш марш смерти начнется с уничтожения их авангарда.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к принцу Валанару в Разлом Смерти, что в Чумных землях: Анклав Алого ордена.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12679,'Сегодня мы ужинаем в Тихоземье','Затмители небес – это безмозглые големы, созданные с одной целью – убивать! Им приказано уничтожать всех мужчин и женщин, пытающихся спастись бегством из Тихоземья. Нельзя допустить, чтобы эти трусы нашли прибежище в Новом Авалоне и снова взялись за оружие!$B$BОднако у нас возникла одна небольшая проблема. Затмители вооружены саронитовыми стрелами, наносящими наибольший урон, а саронит – это очень редкий металл, который добывают только в Нордсколе, так что его запасы весьма и весьма ограничены. Принеси мне использованные стрелы, и я вознагражу тебя со всей щедростью.','Оритос Затмитель Небес из Разлома Смерти просит вас принести ему 15 саронитовых стрел.','Судя по траекториям выстрелов, земля возле южной фермы Тихоземья должна быть буквально усыпана использованными стрелами.','Вернитесь к Оритосу Затмителю Небес в Разлом Смерти, что в Чумных землях: Анклав Алого ордена.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сегодня мы ужинаем в Тихоземье',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Затмители небес – это безмозглые големы, созданные с одной целью – убивать! Им приказано уничтожать всех мужчин и женщин, пытающихся спастись бегством из Тихоземья. Нельзя допустить, чтобы эти трусы нашли прибежище в Новом Авалоне и снова взялись за оружие!$B$BОднако у нас возникла одна небольшая проблема. Затмители вооружены саронитовыми стрелами, наносящими наибольший урон, а саронит – это очень редкий металл, который добывают только в Нордсколе, так что его запасы весьма и весьма ограничены. Принеси мне использованные стрелы, и я вознагражу тебя со всей щедростью.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Оритос Затмитель Небес из Разлома Смерти просит вас принести ему 15 саронитовых стрел.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Судя по траекториям выстрелов, земля возле южной фермы Тихоземья должна быть буквально усыпана использованными стрелами.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Оритосу Затмителю Небес в Разлом Смерти, что в Чумных землях: Анклав Алого ордена.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12680,'Великий угонщик','Как удачно, что в двух шагах от этого аванпоста есть конюшня ордена! Хотя они тщательно охраняют своих лошадей, такому одаренному молодому рыцарю смерти не составит труда сломить их сопротивление и забрать то, что принадлежит нам по праву!$B$BКак только уведешь лошадь из Тихоземских стойл, приведи ее ко мне, и я постараюсь превратить ее в черного боевого коня-скелета, достойного того, чтобы носить на себе рыцаря смерти.$B$BЗапомни, $n: не пойман – не вор! И остерегайся их бешеного конюшенного, Китрика!','Саланар Всадник предложил вам украсть лошадь из Тихоземских стойл и привести ее в Разлом Смерти.','А теперь тебя ждет настоящее испытание. Сможешь ли ты укротить необъезженного скакуна и силой взять то, чего желаешь больше всего на свете?','Ты же не собираешься вечно ходить пешком?','Вернитесь к Саланару Всаднику в Разлом Смерти, что в Чумных землях: Анклав Алого ордена.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Великий угонщик',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как удачно, что в двух шагах от этого аванпоста есть конюшня ордена! Хотя они тщательно охраняют своих лошадей, такому одаренному молодому рыцарю смерти не составит труда сломить их сопротивление и забрать то, что принадлежит нам по праву!$B$BКак только уведешь лошадь из Тихоземских стойл, приведи ее ко мне, и я постараюсь превратить ее в черного боевого коня-скелета, достойного того, чтобы носить на себе рыцаря смерти.$B$BЗапомни, $n: не пойман – не вор! И остерегайся их бешеного конюшенного, Китрика!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Саланар Всадник предложил вам украсть лошадь из Тихоземских стойл и привести ее в Разлом Смерти.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А теперь тебя ждет настоящее испытание. Сможешь ли ты укротить необъезженного скакуна и силой взять то, чего желаешь больше всего на свете?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты же не собираешься вечно ходить пешком?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Саланару Всаднику в Разлом Смерти, что в Чумных землях: Анклав Алого ордена.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12681,'Агент по реагентам','Верховный маг Пентарус из Даларана ждет, когда мы вернемся к нему с коллекцией разнообразных талисманов и реагентов. Говорят, местным особенно нравятся части тел животных, и больше всего – изогнутые когти птицы рух.$B$BНе знаю, верить или нет этим слухам, но попробовать можно.$B$BРухи живут на востоке, на Полях Костей; там они питаются трупами мамонтов. Ты же поможешь мне добыть когти для верховного мага, правда?','Принесите в форпост Дориана 5 изогнутых когтей руха и отдайте Колвину Норрингтону.','<Колвин с удовольствием смотрит на принесенные когти.>$B$BЗдесь даже больше, чем нужно. У горлоков есть пословица: чем закрученнее коготь, тем больше в нем силы. Я уверен, верховный маг не зря потратился на эту экспедицию.','Ну как, удалось тебе найти когти?','Вернитесь к Колвину Норрингтону на Форпост Дориана, что в Низине Шолазар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Агент по реагентам',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Верховный маг Пентарус из Даларана ждет, когда мы вернемся к нему с коллекцией разнообразных талисманов и реагентов. Говорят, местным особенно нравятся части тел животных, и больше всего – изогнутые когти птицы рух.$B$BНе знаю, верить или нет этим слухам, но попробовать можно.$B$BРухи живут на востоке, на Полях Костей; там они питаются трупами мамонтов. Ты же поможешь мне добыть когти для верховного мага, правда?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите в форпост Дориана 5 изогнутых когтей руха и отдайте Колвину Норрингтону.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Колвин с удовольствием смотрит на принесенные когти.>$B$BЗдесь даже больше, чем нужно. У горлоков есть пословица: чем закрученнее коготь, тем больше в нем силы. Я уверен, верховный маг не зря потратился на эту экспедицию.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как, удалось тебе найти когти?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Колвину Норрингтону на Форпост Дориана, что в Низине Шолазар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (12682,'Неразведанная территория (DEPRECATED)','Не все мы в этой экспедиции здесь для того, чтобы гоняться за крупной и уникальной дичью. Кое у кого действительно серьезная работа.$B$BСамо существование этого места будоражит мозг – тропический рай в самом сердце Нордскола. Я не был бы достоит своего имени ученого, если бы не попытался понять это место.$B$BВозьми эти') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Неразведанная территория (DEPRECATED)',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не все мы в этой экспедиции здесь для того, чтобы гоняться за крупной и уникальной дичью. Кое у кого действительно серьезная работа.$B$BСамо существование этого места будоражит мозг – тропический рай в самом сердце Нордскола. Я не был бы достоит своего имени ученого, если бы не попытался понять это место.$B$BВозьми эти',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12683,'Жгучее желание помочь','Во всей долине не сыскать более едкого материала, чем слюна гидры Горьких Волн. У меня есть специальные контейнеры, предназначенные именно для таких образцов. Верховному магу Пентарусу они нужны для исследований. И все, что мне нужно сейчас – это отважный, м-м... собиратель.$B$BТы выглядишь $gзакаленным и отважным:закаленной и отважной:c; |3-4($c). Может, тебе захочется подзаработать, а заодно приблизить час победы Даларана?$B$BТебе нужно всего-навсего прихватить этот резервуар с собой к озеру Горьких Волн, которое расположено к юго-западу отсюда. Разыщи гидр и с помощью контейнера собери слюну, которой они будут в тебя плеваться.','Колвин Норрингтон из форпоста Дориана хочет, чтобы вы принесли 5 образцов слюны гидры и убили 5 гидр Горьких Волн.','Великолепно! Вот твоя оплата, как договаривались. И прими маленький совет: если ощущение жжения не пройдет, возможно, тебе помогут горячие ванны.','Надеюсь, образцы у тебя?','Вернитесь к Колвину Норрингтону на Форпост Дориана, что в Низине Шолазар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жгучее желание помочь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Во всей долине не сыскать более едкого материала, чем слюна гидры Горьких Волн. У меня есть специальные контейнеры, предназначенные именно для таких образцов. Верховному магу Пентарусу они нужны для исследований. И все, что мне нужно сейчас – это отважный, м-м... собиратель.$B$BТы выглядишь $gзакаленным и отважным:закаленной и отважной:c; |3-4($c). Может, тебе захочется подзаработать, а заодно приблизить час победы Даларана?$B$BТебе нужно всего-навсего прихватить этот резервуар с собой к озеру Горьких Волн, которое расположено к юго-западу отсюда. Разыщи гидр и с помощью контейнера собери слюну, которой они будут в тебя плеваться.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Колвин Норрингтон из форпоста Дориана хочет, чтобы вы принесли 5 образцов слюны гидры и убили 5 гидр Горьких Волн.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Великолепно! Вот твоя оплата, как договаривались. И прими маленький совет: если ощущение жжения не пройдет, возможно, тебе помогут горячие ванны.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Надеюсь, образцы у тебя?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Колвину Норрингтону на Форпост Дориана, что в Низине Шолазар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12684,'Кровь мертвого бога','Мам\'тот, бог мамонтов, уничтожил себя, а вместе с собой – и изрядную часть своего храма, чтобы тролли не получили себе его силу.$B$BЯ принесу в жертву часть своей души, но чтобы все получилось, как надо, мне понадобится одна вещь.$B$BПосле смерти Мам\'тота остался гигантский кратер к северо-востоку отсюда, прямо на север от алтаря Кетц\'лун. В этом кратере его кровь до сих пор жива.$B$BПринеси ее мне.','Соберите 7 колб крови Мам\'тота и принесите их Хар\'коа к алтарю Хар\'коа.','Хорошо. Теперь посмотрим, получится или нет...','Жаль, что мы не можем вернуть Мам\'тота к жизни.$B$BНо мы можем почтить его память и продолжить борьбу против Драккари, чтобы его жертва была не напрасной.','Вернитесь к Хар\'коа к алтарю Хар\'коа, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кровь мертвого бога',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мам\'тот, бог мамонтов, уничтожил себя, а вместе с собой – и изрядную часть своего храма, чтобы тролли не получили себе его силу.$B$BЯ принесу в жертву часть своей души, но чтобы все получилось, как надо, мне понадобится одна вещь.$B$BПосле смерти Мам\'тота остался гигантский кратер к северо-востоку отсюда, прямо на север от алтаря Кетц\'лун. В этом кратере его кровь до сих пор жива.$B$BПринеси ее мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 7 колб крови Мам\'тота и принесите их Хар\'коа к алтарю Хар\'коа.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо. Теперь посмотрим, получится или нет...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Жаль, что мы не можем вернуть Мам\'тота к жизни.$B$BНо мы можем почтить его память и продолжить борьбу против Драккари, чтобы его жертва была не напрасной.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хар\'коа к алтарю Хар\'коа, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12685,'Что посеешь, то и пожнешь','Вот к чему все и пришло... к мести.$B$B<Хар\'коа вздыхает.>$B$BВозьми этот набор для обряда и выполни необходимый ритуал над телом Кетц\'лун на ее алтаре. Если все получится так, как надо, ее дух вернется в материальный мир, где она сможет вернуть силу, отобрав ее у пророка.$B$BА дальше действовать будешь ты, $n. Когда пророк обессилет, тебе нужно будет его убить.','Убейте истощенного пророка Кетц\'лун и доложите об исполнении знахарю Кхуфу из Зим\'Торги.','Что возвращает тебя ко мне, $N?','Вернитесь к знахарю Кхуфу в Зим\'Торгу, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Что посеешь, то и пожнешь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот к чему все и пришло... к мести.$B$B<Хар\'коа вздыхает.>$B$BВозьми этот набор для обряда и выполни необходимый ритуал над телом Кетц\'лун на ее алтаре. Если все получится так, как надо, ее дух вернется в материальный мир, где она сможет вернуть силу, отобрав ее у пророка.$B$BА дальше действовать будешь ты, $n. Когда пророк обессилет, тебе нужно будет его убить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте истощенного пророка Кетц\'лун и доложите об исполнении знахарю Кхуфу из Зим\'Торги.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что возвращает тебя ко мне, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к знахарю Кхуфу в Зим\'Торгу, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (12686,'Терпение лопнуло','Невежество – вот источник всех бед и напастей! Не терплю недоумков, $gдружище:подруга;! Вся моя партия гнили – коту под хвост!$b$bЭтот кретин, Дармук! Он отвечает за то, чтобы приглядывать за гнилью. Он подвел меня, $gдруг:подруга;!$b$bПусть это послужит тебе уроком, $n. Скудоумие и неумение справляться с порученным делом – это та еще зараза. Если что-то такое подцепишь, надо сразу его убивать! Пока оно не убило тебя!$b$bВозьми этот скипетр. Он делает моих троллей Плети еще сильнее. Используй их для того, чтобы прикончить Дармука. Он шныряет, должно быть, где-то к югу отсюда, внизу.$b$bПусть это, типа, послужит примером для всех, $gдружище:подруга;. Не подведи Дракуру!','По поручению Дракуру из Волтара отправляйтесь в Реликварий Боли и примените скипетр Дозволенности к одному из слуг Дракуру. Потом с помощью этого слуги убейте Дармука.','Вернитесь к властителю Дракуру в Волтар, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Терпение лопнуло',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Невежество – вот источник всех бед и напастей! Не терплю недоумков, $gдружище:подруга;! Вся моя партия гнили – коту под хвост!$b$bЭтот кретин, Дармук! Он отвечает за то, чтобы приглядывать за гнилью. Он подвел меня, $gдруг:подруга;!$b$bПусть это послужит тебе уроком, $n. Скудоумие и неумение справляться с порученным делом – это та еще зараза. Если что-то такое подцепишь, надо сразу его убивать! Пока оно не убило тебя!$b$bВозьми этот скипетр. Он делает моих троллей Плети еще сильнее. Используй их для того, чтобы прикончить Дармука. Он шныряет, должно быть, где-то к югу отсюда, внизу.$b$bПусть это, типа, послужит примером для всех, $gдружище:подруга;. Не подведи Дракуру!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По поручению Дракуру из Волтара отправляйтесь в Реликварий Боли и примените скипетр Дозволенности к одному из слуг Дракуру. Потом с помощью этого слуги убейте Дармука.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к властителю Дракуру в Волтар, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (12687,'Путь в Долину Теней','Я отвел украденную тобой лошадь в Долину Теней. Именно там мои верные наездники оборвут его смертную жизнь и воскресят как коня смерти. Хватит ли тебе смелости $gсамому:самой; забрать его из Долины Теней?$B$BЕсли пожелаешь, я отправлю тебя в загробный мир. Как только окажешься на месте, найди темных всадников на полях к югу отсюда. Чтобы получить полную власть над своим конем, убей наездника, забери его скакуна и приведи обратно в Разлом Смерти. Вызови меня, если тебе улыбнется удача.','Саланар Всадник из Разлома Смерти предложил вам убить темного всадника Акеруса и забрать его скакуна.$B$BЕсли вам удастся совершить это, вернитесь в Разлом Смерти на коне и вызовите Саланара.','Конь смерти знает только язык силы, рыцарь!','Испытание Всадника пройдено','Вернитесь к Саланару Всаднику в Разлом Смерти, что в Чумных землях: Анклав Алого ордена.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путь в Долину Теней',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я отвел украденную тобой лошадь в Долину Теней. Именно там мои верные наездники оборвут его смертную жизнь и воскресят как коня смерти. Хватит ли тебе смелости $gсамому:самой; забрать его из Долины Теней?$B$BЕсли пожелаешь, я отправлю тебя в загробный мир. Как только окажешься на месте, найди темных всадников на полях к югу отсюда. Чтобы получить полную власть над своим конем, убей наездника, забери его скакуна и приведи обратно в Разлом Смерти. Вызови меня, если тебе улыбнется удача.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Саланар Всадник из Разлома Смерти предложил вам убить темного всадника Акеруса и забрать его скакуна.$B$BЕсли вам удастся совершить это, вернитесь в Разлом Смерти на коне и вызовите Саланара.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Конь смерти знает только язык силы, рыцарь!',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Испытание Всадника пройдено',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Саланару Всаднику в Разлом Смерти, что в Чумных землях: Анклав Алого ордена.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`) VALUES (12688,'Проектирование аварии','Варвары-гоблины и их прислужники решили, что эта колонна и кристаллы принадлежат им. Я пришла сюда, чтобы собрать и изучить образцы кристаллов, но гоблины не только не дали мне сделать этого – они еще и не дали мне вернуться в лагерь!$B$BЕсли ты поможешь мне выбраться отсюда, мы еще сумеем хорошенько проучить мерзавцев!','Помогите инженеру Хелис сбежать из Раскопа Хитрохмыла, а затем поговорите с Хемингом Эрнестуэем в лагере Эрнестуэя.','Спасибо за освобождение Хелис и за ее безопасное возвращение. Мы все беспокоились, когда она не вернулась со своей охоты за кристаллами.','Проводите инженера Хелис из Раскопа Хитрохмыла.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Проектирование аварии',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Варвары-гоблины и их прислужники решили, что эта колонна и кристаллы принадлежат им. Я пришла сюда, чтобы собрать и изучить образцы кристаллов, но гоблины не только не дали мне сделать этого – они еще и не дали мне вернуться в лагерь!$B$BЕсли ты поможешь мне выбраться отсюда, мы еще сумеем хорошенько проучить мерзавцев!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Помогите инженеру Хелис сбежать из Раскопа Хитрохмыла, а затем поговорите с Хемингом Эрнестуэем в лагере Эрнестуэя.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо за освобождение Хелис и за ее безопасное возвращение. Мы все беспокоились, когда она не вернулась со своей охоты за кристаллами.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Проводите инженера Хелис из Раскопа Хитрохмыла.',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (12689,'Длань Оракулов','Здорово! Слушай, я так рад тебя видеть!$B$BЯ знал, что мы друзья, я знал это! Ты хороший друг. Не только для нас:для всех Оракулов. Спасибо, ты $Gспас:спасла; всех нас!$B$BА здорово ты $Gврезал:врезала; тому волосатому! Я видел! Неживой сказал. что был твоим другом? Жаль, я не знал. Значит, ты больше не с волосатыми, ты теперь друг Оракулов?$B$BТолько подумай хорошенько - ты правда больше не хочешь дружить с волосатыми?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Длань Оракулов',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Здорово! Слушай, я так рад тебя видеть!$B$BЯ знал, что мы друзья, я знал это! Ты хороший друг. Не только для нас:для всех Оракулов. Спасибо, ты $Gспас:спасла; всех нас!$B$BА здорово ты $Gврезал:врезала; тому волосатому! Я видел! Неживой сказал. что был твоим другом? Жаль, я не знал. Значит, ты больше не с волосатыми, ты теперь друг Оракулов?$B$BТолько подумай хорошенько - ты правда больше не хочешь дружить с волосатыми?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (12690,'Нам это на руку','Пора выступать на Гундрак, $gдружище:подруга;. Пора выпускать тебя на троллей!$b$bОни пробили нашу стену на севере и собрали там целую армию.$b$bХа-ха-ха!$b$bНам это на руку! Мы захватим вождей, а остальных попросту перебьем! Таков, типа, мой суперский план... $b$bВозьми этот скипетр и принимай командование над моими поганищами. Веди их на армию Драккари. Перебейте их всех! То-то будет потеха! А как только появятся вожди, мой любимец Глинокрыл схватит их и принесет мне сюда.','По поручению Дракуру из Волтара с помощью скипетра властности получите контроль над раздувшимися поганищами. С их помощью у Хладного разлома убейте 60 дробителей черепов Драккари, чтобы выманить 3 вождей племени.$b$bВожди появятся, когда будет убито достаточно дробителей черепов.','Отлично, дружище! Мы это сделали!$B$BВожди уже в клетках, а мои поганища под твоим предводительством, типа, задали жару этим уродам.$B$BЭто надо отметить, дружище!','Вернитесь к властителю Дракуру в Волтар, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нам это на руку',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пора выступать на Гундрак, $gдружище:подруга;. Пора выпускать тебя на троллей!$b$bОни пробили нашу стену на севере и собрали там целую армию.$b$bХа-ха-ха!$b$bНам это на руку! Мы захватим вождей, а остальных попросту перебьем! Таков, типа, мой суперский план... $b$bВозьми этот скипетр и принимай командование над моими поганищами. Веди их на армию Драккари. Перебейте их всех! То-то будет потеха! А как только появятся вожди, мой любимец Глинокрыл схватит их и принесет мне сюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По поручению Дракуру из Волтара с помощью скипетра властности получите контроль над раздувшимися поганищами. С их помощью у Хладного разлома убейте 60 дробителей черепов Драккари, чтобы выманить 3 вождей племени.$b$bВожди появятся, когда будет убито достаточно дробителей черепов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, дружище! Мы это сделали!$B$BВожди уже в клетках, а мои поганища под твоим предводительством, типа, задали жару этим уродам.$B$BЭто надо отметить, дружище!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к властителю Дракуру в Волтар, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12691,'Старинный сундук','Похоже, этот каменный сундук заперт на ключ. Осталось всего ничего: вставить нужный ключ в каменную скважину...$B$BВозможно, ключ найдется у одного из стражей, находящихся поблизости?','Добудьте у стражей Шолазара огромный каменный ключ и старинный откройте сундук, который вы нашли в Дозоре Творцов.','Огромный каменный ключ поворачивается со скрежетом, крышка сундука открывается, и вашим глазам предстают сокровища.','Каменный сундук не отпирается.','Вернитесь к старинному сундуку к Дозору Творцов, что в Низине Шолазар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Старинный сундук',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Похоже, этот каменный сундук заперт на ключ. Осталось всего ничего: вставить нужный ключ в каменную скважину...$B$BВозможно, ключ найдется у одного из стражей, находящихся поблизости?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте у стражей Шолазара огромный каменный ключ и старинный откройте сундук, который вы нашли в Дозоре Творцов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Огромный каменный ключ поворачивается со скрежетом, крышка сундука открывается, и вашим глазам предстают сокровища.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Каменный сундук не отпирается.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старинному сундуку к Дозору Творцов, что в Низине Шолазар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (12692,'Возвращение охотника на личей','Ладно, я возвращаюсь на холм Бешеного Сердца. Я всем расскажу, что ты $gсделал:сделала; для волчеров и для Зепика. Кто думает, что ты не великий охотник, тот дурак.$B$BИди на холм и поговори со Старейшиной Харкеком... я расскажу ему, что ты не $gпредатель:предательница; племени Бешеного Сердца.$B$BПрими мою благодарность, охотник на личей.','Вернитесь на холм Бешеного Сердца и поговорите со старейшиной Харкеком.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение охотника на личей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ладно, я возвращаюсь на холм Бешеного Сердца. Я всем расскажу, что ты $gсделал:сделала; для волчеров и для Зепика. Кто думает, что ты не великий охотник, тот дурак.$B$BИди на холм и поговори со Старейшиной Харкеком... я расскажу ему, что ты не $gпредатель:предательница; племени Бешеного Сердца.$B$BПрими мою благодарность, охотник на личей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь на холм Бешеного Сердца и поговорите со старейшиной Харкеком.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (12693,'Отслеживатель выбора фракции волчеров') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отслеживатель выбора фракции волчеров',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (12694,'Отслеживатель выбора фракции оракулов') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отслеживатель выбора фракции оракулов',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (12695,'Возвращение сухой шкуры','Ой-ой, наверное, Су-сэй о нас тревожится! Может, вернешься в город и скажешь ему, что все в порядке? Да-да, иди, поговори с Су-сэем.$B$BКак только заберу у дохлого лича светящийся шар, встречусь с тобой в городе! Иди-иди! Еще увидимся!','Вернитесь в прибежище Гласа Дождя и поговорите с верховным оракулом Су-сэем.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение сухой шкуры',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ой-ой, наверное, Су-сэй о нас тревожится! Может, вернешься в город и скажешь ему, что все в порядке? Да-да, иди, поговори с Су-сэем.$B$BКак только заберу у дохлого лича светящийся шар, встречусь с тобой в городе! Иди-иди! Еще увидимся!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь в прибежище Гласа Дождя и поговорите с верховным оракулом Су-сэем.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (12696,'Воздушная разведка','Хорошо, что ты $gпомог:помогла; Весу с этим ветролетом. Теперь-то все работает как надо.$B$BЕсли хочешь и дальше помогать нам, у меня есть одно дельце. С северо-востока движется какой-то резкий циклон. У меня есть пилот, который готов его изучить, но ему нужен помощник.$B$BЕсли считаешь, что ты к этому $gготов:готова;, можешь лететь к озерному лагерю. А Вику скажи, что это я тебя послала.','Профессор Кальверт хочет, чтобы вы полетели в лагерь у озера и там поговорили с пилотом Виком.','Это профессор послала тебя сюда? Хорошо.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Воздушная разведка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хорошо, что ты $gпомог:помогла; Весу с этим ветролетом. Теперь-то все работает как надо.$B$BЕсли хочешь и дальше помогать нам, у меня есть одно дельце. С северо-востока движется какой-то резкий циклон. У меня есть пилот, который готов его изучить, но ему нужен помощник.$B$BЕсли считаешь, что ты к этому $gготов:готова;, можешь лететь к озерному лагерю. А Вику скажи, что это я тебя послала.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Профессор Кальверт хочет, чтобы вы полетели в лагерь у озера и там поговорили с пилотом Виком.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это профессор послала тебя сюда? Хорошо.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (12697,'Готик Жнец','Хаос воцарился на этих землях, $n! Орден пребывает в растерянности. Они отправили все войска Нового Авалона на защиту Заставы Света, которая находится к востоку отсюда. Таким образом они отчаянно пытаются опустошить Тихоземскую шахту и погрузить все добытые ресурсы на фрегаты, стоящие на якоре вдоль всего побережья.$B$BТебе не хочется слегка вмешаться в их планы? Недавно нас почтил своим присутствием сам Готик Жнец, великий некромант на службе Короля-лича. Он привез с собой небольшой подарок, который следует незамедлительно вручить Алому ордену. Отыщи его; он ждет твоего появления.','Поговорите с Готиком Жнецом в Разломе Смерти.','Судя по траекториям выстрелов, земля возле южной фермы Тихоземья должна быть буквально усыпана использованными стрелами.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Готик Жнец',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хаос воцарился на этих землях, $n! Орден пребывает в растерянности. Они отправили все войска Нового Авалона на защиту Заставы Света, которая находится к востоку отсюда. Таким образом они отчаянно пытаются опустошить Тихоземскую шахту и погрузить все добытые ресурсы на фрегаты, стоящие на якоре вдоль всего побережья.$B$BТебе не хочется слегка вмешаться в их планы? Недавно нас почтил своим присутствием сам Готик Жнец, великий некромант на службе Короля-лича. Он привез с собой небольшой подарок, который следует незамедлительно вручить Алому ордену. Отыщи его; он ждет твоего появления.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Готиком Жнецом в Разломе Смерти.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Судя по траекториям выстрелов, земля возле южной фермы Тихоземья должна быть буквально усыпана использованными стрелами.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12698,'Подарок с подвохом','Я прибыл из самого ледяного сердца Наксрамаса, чтобы поглотить души и развеять тела наших кровных врагов.$B$BИнструмент, который я хочу доверить тебе – это переносной распространитель чумы. Отнеси его на восток, в Тихоземские шахты, и включи его, когда шахтеры из Алого ордена будут работать внутри. Когда все шахтеры обратятся в вурдалаков, возвращайся ко мне с собственной маленькой армией. А я пока освобожу для них место в моем вакуумном очистителе душ!','Готик Жнец из Разлома Смерти передал вам Дар Жнеца, с помощью которого вам надо обратить 5 шахтеров из Алого ордена в вурдалаков. Выполнив это поручение, верните прибор Жнецу.','Теперь они поймут, что на рудниках больше небезопасно, и постараются как можно быстрее убраться оттуда, забывая об осторожности!','Да, совсем забыл – прибор не всегда обращает людей в вурдалаков. Иногда они становятся разъяренными духами, одержимыми желанием убить тебя.','Вернитесь к Готику Жнецу в Разлом Смерти, что в Чумных землях: Анклав Алого ордена.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подарок с подвохом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я прибыл из самого ледяного сердца Наксрамаса, чтобы поглотить души и развеять тела наших кровных врагов.$B$BИнструмент, который я хочу доверить тебе – это переносной распространитель чумы. Отнеси его на восток, в Тихоземские шахты, и включи его, когда шахтеры из Алого ордена будут работать внутри. Когда все шахтеры обратятся в вурдалаков, возвращайся ко мне с собственной маленькой армией. А я пока освобожу для них место в моем вакуумном очистителе душ!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Готик Жнец из Разлома Смерти передал вам Дар Жнеца, с помощью которого вам надо обратить 5 шахтеров из Алого ордена в вурдалаков. Выполнив это поручение, верните прибор Жнецу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь они поймут, что на рудниках больше небезопасно, и постараются как можно быстрее убраться оттуда, забывая об осторожности!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да, совсем забыл – прибор не всегда обращает людей в вурдалаков. Иногда они становятся разъяренными духами, одержимыми желанием убить тебя.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Готику Жнецу в Разлом Смерти, что в Чумных землях: Анклав Алого ордена.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (12699,'Неловкое положение','Прежде чем мы двинемся в путь, нужно разрешить одну небольшую проблему. Видишь ли, я никак не могу найти ключи от своего ветролета. $B$BЯ уже везде их искал... Вот только что в озеро не нырял. Может, ты сумеешь мне помочь?$B$BЯ тебе даже свой кислородный баллон отдам! Правда, он почти пустой, но ненадолго его все-таки хватит...','Поищите ключи Вика в Слиянии рек.','Вернитесь к пилоту Вику в Лагерь у озера, что в Низине Шолазар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Неловкое положение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прежде чем мы двинемся в путь, нужно разрешить одну небольшую проблему. Видишь ли, я никак не могу найти ключи от своего ветролета. $B$BЯ уже везде их искал... Вот только что в озеро не нырял. Может, ты сумеешь мне помочь?$B$BЯ тебе даже свой кислородный баллон отдам! Правда, он почти пустой, но ненадолго его все-таки хватит...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поищите ключи Вика в Слиянии рек.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к пилоту Вику в Лагерь у озера, что в Низине Шолазар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (12700,'Момент для атаки','Только силы Алого ордена из Нового Авалона и с Заставы Света смеют бросать нам вызов! Настало время расправиться с их флотом на Заставе.$B$BДиверсия на руднике повергла в хаос их войска. Сейчас они отчаянно пытаются расчистить путь к своим кораблям.$B$BМедлить нельзя! Принц Валанар не упустит этого шанса раз и навсегда покончить с флотом Алого ордена. Немедленно отправляйся к нему!','Поговорите с принцем Валанаром в Разломе Смерти.','Да, совсем забыл – прибор не всегда обращает людей в вурдалаков. Иногда они становятся разъяренными духами, одержимыми желанием убить тебя.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Момент для атаки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Только силы Алого ордена из Нового Авалона и с Заставы Света смеют бросать нам вызов! Настало время расправиться с их флотом на Заставе.$B$BДиверсия на руднике повергла в хаос их войска. Сейчас они отчаянно пытаются расчистить путь к своим кораблям.$B$BМедлить нельзя! Принц Валанар не упустит этого шанса раз и навсегда покончить с флотом Алого ордена. Немедленно отправляйся к нему!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с принцем Валанаром в Разломе Смерти.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да, совсем забыл – прибор не всегда обращает людей в вурдалаков. Иногда они становятся разъяренными духами, одержимыми желанием убить тебя.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12701,'Побоище у Заставы Света','В спешке люди ордена совершили одну роковую ошибку: они не стали проверять вагонетки.$B$BМы должны воспользоваться этой оплошностью. Возвращайся на восток, в Тихоземскую шахту, и найди вагонетку, оставленную моими прислужниками возле флигеля. Заберись в нее, и какой-нибудь шахтер с ветерком доставит тебя в тыл врага.$B$BКак только ты окажешься на борту одного из фрегатов, воспользуйся их пушками и перебей всех до единого!$B$BКогда выполнишь это поручение, позови грифона Плети, и он принесет тебя обратно.','Принц Валанар из Разлома Смерти приказал вам убить 100 защитников из Алого ордена.','Рыцарь смерти не ведает страха!','Вернитесь к принцу Валанару в Разлом Смерти, что в Чумных землях: Анклав Алого ордена.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Побоище у Заставы Света',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В спешке люди ордена совершили одну роковую ошибку: они не стали проверять вагонетки.$B$BМы должны воспользоваться этой оплошностью. Возвращайся на восток, в Тихоземскую шахту, и найди вагонетку, оставленную моими прислужниками возле флигеля. Заберись в нее, и какой-нибудь шахтер с ветерком доставит тебя в тыл врага.$B$BКак только ты окажешься на борту одного из фрегатов, воспользуйся их пушками и перебей всех до единого!$B$BКогда выполнишь это поручение, позови грифона Плети, и он принесет тебя обратно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принц Валанар из Разлома Смерти приказал вам убить 100 защитников из Алого ордена.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Рыцарь смерти не ведает страха!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к принцу Валанару в Разлом Смерти, что в Чумных землях: Анклав Алого ордена.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12702,'Куриная вечеринка','Бьюсь об заклад, никогда не догадаешься, что опять случилось!$B$BНет, это не связано с Горегеком и курами.$B$BЛадно, я вру. Из-за Горегека все куры опять разбежались. Глупый Горегек, бурчащее брюхо. $B$BДай мне знать, если тебе понадобится помощь охотников... они все где-то поблизости.','Поймайте 12 сбежавших кур для старейшины Харкека с холма Бешеного Сердца.','Обычно куры далеко не убегают... конечно, если их осы не съедят. Может, в следующий раз нам стоит оставить их на улице...','Вернитесь к старейшине Харкеку на Холм Бешеного Сердца, что в Низине Шолазар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Куриная вечеринка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Бьюсь об заклад, никогда не догадаешься, что опять случилось!$B$BНет, это не связано с Горегеком и курами.$B$BЛадно, я вру. Из-за Горегека все куры опять разбежались. Глупый Горегек, бурчащее брюхо. $B$BДай мне знать, если тебе понадобится помощь охотников... они все где-то поблизости.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поймайте 12 сбежавших кур для старейшины Харкека с холма Бешеного Сердца.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Обычно куры далеко не убегают... конечно, если их осы не съедят. Может, в следующий раз нам стоит оставить их на улице...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старейшине Харкеку на Холм Бешеного Сердца, что в Низине Шолазар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12703,'Буйство Картака','Что, ты и есть великий охотник на личей? Хорошо, что в бою у племени Бешеного Сердца будет такой союзник. Может, У тебя достаточно сил, чтобы призвать самого Картака.$B$BБольшая битва на юго-западе, в Форте Картака. Иди, убивай сверкающих длинноязыких, пока не наберешь достаточно крови Оракулов. Принеси кровь к алтарю в форте Картака и позови Картака на пир.$B$BЕсли Картак решит, что ты $gдостоин:достойна;, он возьмет твое тело... могущество Картака поможет убить много длинноязыких, очень много.$B$BИди, охотник, иди и убивай!','Принесите чистый образчик Крови Оракула к алтарю Картака, чтобы призвать Картака. Используя его силу, уничтожьте 50 горлоков из племени Заиндевелых по просьбе шамана Джакжека в форте Картака.','Много большеязыких - и всех можно убить! Весело, верно?','Вернитесь к шаману Якжеку в Форт Картака, что в Низине Шолазар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Буйство Картака',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что, ты и есть великий охотник на личей? Хорошо, что в бою у племени Бешеного Сердца будет такой союзник. Может, У тебя достаточно сил, чтобы призвать самого Картака.$B$BБольшая битва на юго-западе, в Форте Картака. Иди, убивай сверкающих длинноязыких, пока не наберешь достаточно крови Оракулов. Принеси кровь к алтарю в форте Картака и позови Картака на пир.$B$BЕсли Картак решит, что ты $gдостоин:достойна;, он возьмет твое тело... могущество Картака поможет убить много длинноязыких, очень много.$B$BИди, охотник, иди и убивай!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите чистый образчик Крови Оракула к алтарю Картака, чтобы призвать Картака. Используя его силу, уничтожьте 50 горлоков из племени Заиндевелых по просьбе шамана Джакжека в форте Картака.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Много большеязыких - и всех можно убить! Весело, верно?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к шаману Якжеку в Форт Картака, что в Низине Шолазар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12704,'Умиротворение Великого камня дождя','С тех пор, как на мохобродов напали, я беспокоюсь: может быть, мы плохо относимся к Великому камню дождя... Может быть, мы слишком жадные. Мы должны жертвовать больше сокровищ!$B$BТебе в прошлый раз хорошо удалось найти блестящие штучки... Может быть, поищешь таких еще вокруг деревни? Тебе, может быть, понадобится кто-нибудь из наших добрых соплеменников в помощь? Скажи только, кто.','По просьбе верховного оракула Су-сэя из прибежища Гласа Дождя выберите себе спутника и с его помощью выкопайте 6 сверкающих сокровищ.$B$BОбязательно поговорите с верховным оракулом Су-сэем в прибежище Гласа Дождя, чтобы заручиться поддержкой кто-то из ваших прежних спутников.','Блестящих штучек всегда мало... Великий камень дождя добр к нам, мы должны быть добры к Великому камню дождя.','Вернитесь к верховному оракулу Су-сэю в Прибежище Гласа Дождя, что в Низине Шолазар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Умиротворение Великого камня дождя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','С тех пор, как на мохобродов напали, я беспокоюсь: может быть, мы плохо относимся к Великому камню дождя... Может быть, мы слишком жадные. Мы должны жертвовать больше сокровищ!$B$BТебе в прошлый раз хорошо удалось найти блестящие штучки... Может быть, поищешь таких еще вокруг деревни? Тебе, может быть, понадобится кто-нибудь из наших добрых соплеменников в помощь? Скажи только, кто.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По просьбе верховного оракула Су-сэя из прибежища Гласа Дождя выберите себе спутника и с его помощью выкопайте 6 сверкающих сокровищ.$B$BОбязательно поговорите с верховным оракулом Су-сэем в прибежище Гласа Дождя, чтобы заручиться поддержкой кто-то из ваших прежних спутников.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Блестящих штучек всегда мало... Великий камень дождя добр к нам, мы должны быть добры к Великому камню дождя.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному оракулу Су-сэю в Прибежище Гласа Дождя, что в Низине Шолазар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12705,'Волосатые напали на Заиндевелых... Мы должны сражаться, или они нападут и на других оракулов тоже.$B$BТы $gбыл:была; нам хорошим другом – так что, может, мы окажем тебе особую честь. Великие давно-давно оставили защитника для святилищ... Он до сих пор здесь, но он не узнает, что что-то не так, до тех пор, пока это не коснется святилищ.$B$BУ волосатых там, внизу, есть плохие кристаллы, чтобы делать проблемы... принеси большой кристалл в святилище молний, чтобы Су-холу знал, что нужна помощь.$B$BНе пугайся, если Су-холу возьмет твое тело... он очень сильный, он тебя охранит.','Блестящих штучек всегда мало... Великий камень дождя добр к нам, мы должны быть добры к Великому камню дождя.','Поговорите с призывателем Су-метом в Заиндевелой гавани, что в Низине Шолазар.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Волосатые напали на Заиндевелых... Мы должны сражаться, или они нападут и на других оракулов тоже.$B$BТы $gбыл:была; нам хорошим другом – так что, может, мы окажем тебе особую честь. Великие давно-давно оставили защитника для святилищ... Он до сих пор здесь, но он не узнает, что что-то не так, до тех пор, пока это не коснется святилищ.$B$BУ волосатых там, внизу, есть плохие кристаллы, чтобы делать проблемы... принеси большой кристалл в святилище молний, чтобы Су-холу знал, что нужна помощь.$B$BНе пугайся, если Су-холу возьмет твое тело... он очень сильный, он тебя охранит.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Блестящих штучек всегда мало... Великий камень дождя добр к нам, мы должны быть добры к Великому камню дождя.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с призывателем Су-метом в Заиндевелой гавани, что в Низине Шолазар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (12706,'Победа у Разлома Смерти','<Принц Валанар протягивает вам запечатанный свиток.>$B$BЭто полный отчет о нашей победе у Разлома Смерти. Я поручаю тебе доставить его верховному лорду Могрейну в Акерус. Я включил в доклад описание твоих героических действий, заслуживающих награды из рук самого Могрейна.$B$BИди же!','Вернитесь к верховному лорду Дариону Могрейну в Черный оплот.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Победа у Разлома Смерти',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Принц Валанар протягивает вам запечатанный свиток.>$B$BЭто полный отчет о нашей победе у Разлома Смерти. Я поручаю тебе доставить его верховному лорду Могрейну в Акерус. Я включил в доклад описание твоих героических действий, заслуживающих награды из рук самого Могрейна.$B$BИди же!',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному лорду Дариону Могрейну в Черный оплот.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12707,'Яростное правосудие','Ауне слышать, что ты собираться идти к кратеру Мам\'тота, $gдружище:подруга;. Дети Мам\'тота беснуются в ярости и требуют правосудия!$B$BИди по этой дороге на северо-восток, на следующий ярус Зул\'Драка. Справа увидишь руины – то, что еще оставаться теперь от алтаря Мам\'тота.$B$BКогда доберешься туда, ты потрясать этим вот медальоном Мам\'тота перед глазами у одного из разъяренных мамонтов. Он успокаиваться на время, и ты заберешься к нему на спину.$B$BСкачи на нем и затаптывай всех послушников мертвого Мам\'тота, которых найдешь!','По поручению Ауне из Зим\'торги используйте медальон Мам\'тота, чтобы успокоить одного из разъяренных мамонтов и забраться к нему на спину. Затем затопчите насмерть 12 послушников Мам\'тота.','Что? Вы уже сделали?$B$B Вы применили правосудие на тех мохнатых жалких ледяных троллях?','Вернитесь к охотнику за скальпами Ауне в Зим\'Торгу, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Яростное правосудие',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ауне слышать, что ты собираться идти к кратеру Мам\'тота, $gдружище:подруга;. Дети Мам\'тота беснуются в ярости и требуют правосудия!$B$BИди по этой дороге на северо-восток, на следующий ярус Зул\'Драка. Справа увидишь руины – то, что еще оставаться теперь от алтаря Мам\'тота.$B$BКогда доберешься туда, ты потрясать этим вот медальоном Мам\'тота перед глазами у одного из разъяренных мамонтов. Он успокаиваться на время, и ты заберешься к нему на спину.$B$BСкачи на нем и затаптывай всех послушников мертвого Мам\'тота, которых найдешь!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По поручению Ауне из Зим\'торги используйте медальон Мам\'тота, чтобы успокоить одного из разъяренных мамонтов и забраться к нему на спину. Затем затопчите насмерть 12 послушников Мам\'тота.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что? Вы уже сделали?$B$B Вы применили правосудие на тех мохнатых жалких ледяных троллях?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к охотнику за скальпами Ауне в Зим\'Торгу, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12708,'Неужели ты не мог рассмотреть всех заколдованных воинов Тики так быстро?','Вернитесь к укротителю стихий Дагоде в Зим\'Торгу, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Неужели ты не мог рассмотреть всех заколдованных воинов Тики так быстро?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к укротителю стихий Дагоде в Зим\'Торгу, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12709,'Проклятые тайники','Принесите летописцу То\'кини в Зим\'Торгу 12 трофеев из крепости Зол\'Маза.','Достаточно взглянуть на все это!$b$b Смотрите сюда, $n. Этот восстановленный вами кусок наглядно иллюстрирует, что Драккари стало известно об ослаблении земли, причиненной присутствием Плети.$b$b Военачальник был вынужден воспользоваться возможностью, представленной этим. Он толкнул пророков, чтобы убивать своих богов, с тем чтобы контролировать власть и бороться против сил Короля Мертвых.$b$b B любом случае они были обречены. Они непреднамеренно выбрали быть орудием своего собственного разрушения!','Возможно, вы носите трофеи в вашей сумке даже сейчас, когда мы говорим?','Вернитесь к летописцу То\'кини в Зим\'Торгу, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Проклятые тайники',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите летописцу То\'кини в Зим\'Торгу 12 трофеев из крепости Зол\'Маза.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Достаточно взглянуть на все это!$b$b Смотрите сюда, $n. Этот восстановленный вами кусок наглядно иллюстрирует, что Драккари стало известно об ослаблении земли, причиненной присутствием Плети.$b$b Военачальник был вынужден воспользоваться возможностью, представленной этим. Он толкнул пророков, чтобы убивать своих богов, с тем чтобы контролировать власть и бороться против сил Короля Мертвых.$b$b B любом случае они были обречены. Они непреднамеренно выбрали быть орудием своего собственного разрушения!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Возможно, вы носите трофеи в вашей сумке даже сейчас, когда мы говорим?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к летописцу То\'кини в Зим\'Торгу, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12710,'Открытая тайна','Отлично справляешься, $n.$b$bЯ всегда знал: у меня нюх на таланты! А то! Теперь, стало быть, понимаешь, почему Король-лич меня выделяет... $b$bЯ так думаю, уже можно раскрыть тебе мой великолепный план, $gдружище:подруга;.$b$bСейчас ты поймешь, как мы прорвемся через полчища троллей драккари, чтоб занять свое место в великом дворце Гундрака. Место наше по праву! А то!$b$bВозьми этот скипетр, $gдружище:подруга;. Типа как в знак доверия. С ним ты сможешь проникнуть в мой верхний зал и поглядеть-подивиться на наше тайное оружие.','Телепортируйтесь в верхний зал Дракуру в Волтаре.','Ты $Gходил:ходила; смотреть мои творения, $N?','Вернитесь к властителю Дракуру в Волтар, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Открытая тайна',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Отлично справляешься, $n.$b$bЯ всегда знал: у меня нюх на таланты! А то! Теперь, стало быть, понимаешь, почему Король-лич меня выделяет... $b$bЯ так думаю, уже можно раскрыть тебе мой великолепный план, $gдружище:подруга;.$b$bСейчас ты поймешь, как мы прорвемся через полчища троллей драккари, чтоб занять свое место в великом дворце Гундрака. Место наше по праву! А то!$b$bВозьми этот скипетр, $gдружище:подруга;. Типа как в знак доверия. С ним ты сможешь проникнуть в мой верхний зал и поглядеть-подивиться на наше тайное оружие.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Телепортируйтесь в верхний зал Дракуру в Волтаре.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gходил:ходила; смотреть мои творения, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к властителю Дракуру в Волтар, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (12711,'Забытые письма','Сверху на почтовом ящике лежит пачка писем и свитков, накарябанных неразборчивым почерком. Какой хлам...$B$BМожет быть, внутри ящика найдется что-то полезное?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Забытые письма',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сверху на почтовом ящике лежит пачка писем и свитков, накарябанных неразборчивым почерком. Какой хлам...$B$BМожет быть, внутри ящика найдется что-то полезное?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (12712,'Ключ полководца Зол\'Маза','$n, нам нужен ключ, чтобы отомкнуть оковы бога-люторога Акали. Его приготовили на убой, так что нам надо поторопиться.$B$BКлюч – у полководца Драккари, Зол\'Маза. Он наслышан о твоих подвигах, и поэтому скрылся вместе с семьей в их фамильной крепости к северо-востоку отсюда.$B$BТвой враг силен, ты не справишься с ним в одиночку. Чтобы вызвать полководца на поединок у ворот его фамильного гнезда, тебе потребуется помощь, и ты получишь ее, если объединишь амулет рода, меч и магическую формулу его домочадцев.','Раздобудьте ключ полководца Зол\'Маза для Хар\'коа из Зим\'Торги.','Вернитесь к Хар\'коа в Зим\'Торгу, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ключ полководца Зол\'Маза',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, нам нужен ключ, чтобы отомкнуть оковы бога-люторога Акали. Его приготовили на убой, так что нам надо поторопиться.$B$BКлюч – у полководца Драккари, Зол\'Маза. Он наслышан о твоих подвигах, и поэтому скрылся вместе с семьей в их фамильной крепости к северо-востоку отсюда.$B$BТвой враг силен, ты не справишься с ним в одиночку. Чтобы вызвать полководца на поединок у ворот его фамильного гнезда, тебе потребуется помощь, и ты получишь ее, если объединишь амулет рода, меч и магическую формулу его домочадцев.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте ключ полководца Зол\'Маза для Хар\'коа из Зим\'Торги.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хар\'коа в Зим\'Торгу, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (12713,'Предательство','Пора заканчивать с этим фарсом, $n.$b$bИнформация, которую ты добываешь, она, безусловно, ценна, но нам нужно убрать Дракуру, пока он не завершил свой проект и не выпустил в мир всех своих жутких чудовищ.$b$bМы модифицировали твой скипетр. В нужный момент ты подчинишь себе гнилокровных троллей Дракуру и натравишь их на него. Это – единственная возможность его уничтожить.$b$bУдачи!','По поручению Стефана с Черной заставы убейте Дракуру.$b$bЕсли вы потеряете заколдованное колье, возвращайтесь к Стефану на Черную заставу, и он даст вам другое.','Стало быть, с этим мы разобрались.$B$BНам еще многое надо сделать, но теперь нам будет проще – благодаря тебе.$B$BПрими это в знак благодарности. И еще раз спасибо.','Вернитесь к Стефану Ваду на Черную заставу, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Предательство',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пора заканчивать с этим фарсом, $n.$b$bИнформация, которую ты добываешь, она, безусловно, ценна, но нам нужно убрать Дракуру, пока он не завершил свой проект и не выпустил в мир всех своих жутких чудовищ.$b$bМы модифицировали твой скипетр. В нужный момент ты подчинишь себе гнилокровных троллей Дракуру и натравишь их на него. Это – единственная возможность его уничтожить.$b$bУдачи!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По поручению Стефана с Черной заставы убейте Дракуру.$b$bЕсли вы потеряете заколдованное колье, возвращайтесь к Стефану на Черную заставу, и он даст вам другое.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Стало быть, с этим мы разобрались.$B$BНам еще многое надо сделать, но теперь нам будет проще – благодаря тебе.$B$BПрими это в знак благодарности. И еще раз спасибо.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Стефану Ваду на Черную заставу, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (12714,'Воля Короля-лича','Нас движет вперед воля Короля-лича – кому, как не рыцарю смерти знать об этом. Все наше существование неразрывно связано с его повелением. Должно быть, ты уже $gчувствовал:чувствовала;, как в разговоре с тобой он с легкостью проникает в твои мысли...$B$BСлышишь ли ты сейчас его голос? Нет... должно быть, ты еще не $gготов:готова; к этому.$B$B<Могрейн закрывает глаза и кивает незримому собеседнику.>$B$BДа, мой повелитель. Все будет сделано.$B$B$n, тебе следует вернуться в Разлом Смерти и отчитаться перед принцем Валанаром. Приказ Короля-лича!','Возвращайтесь в Разлом Смерти и обратитесь к принцу Валанару.','Не думал, что ты вернешься живым с поля битвы, $c. Возможно, я тебя недооценил.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Воля Короля-лича',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нас движет вперед воля Короля-лича – кому, как не рыцарю смерти знать об этом. Все наше существование неразрывно связано с его повелением. Должно быть, ты уже $gчувствовал:чувствовала;, как в разговоре с тобой он с легкостью проникает в твои мысли...$B$BСлышишь ли ты сейчас его голос? Нет... должно быть, ты еще не $gготов:готова; к этому.$B$B<Могрейн закрывает глаза и кивает незримому собеседнику.>$B$BДа, мой повелитель. Все будет сделано.$B$B$n, тебе следует вернуться в Разлом Смерти и отчитаться перед принцем Валанаром. Приказ Короля-лича!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возвращайтесь в Разлом Смерти и обратитесь к принцу Валанару.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Не думал, что ты вернешься живым с поля битвы, $c. Возможно, я тебя недооценил.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (12715,'Склеп Воспоминаний','Мы начали осаду ворот последнего бастиона Алого ордена. В этот самый момент, когда вурдалаки разделываются с авангардом войск крепости, наши рабочие возводят передовое укрепление Плети – Склеп Воспоминаний.$B$BОтправляйся на юг, к склепу, граничащему с Новым Авалоном, и найди там моего дорогого брата, принца Келесета.$B$BЯ предупредил его о твоем прибытии.$B$BГотовься, $n, ибо тебе предстоит познать второй урок военного искусства плети: становление власти!$B$BВперед, рыцарь смерти!','Найдите принца Келесета в Склепе Воспоминаний.','Приветствую тебя, рыцарь смерти. Я – принц крови Келесет, правитель юго-восточных пределов Нордскола. Король-лич пожелал воспользоваться моими силами, чтобы покончить с жалким сопротивлением смертных, и я счастлив подчиниться воле моего господина. В конце концов, кто бы отказался насладиться страданиями бесчисленных тысяч душ?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Склеп Воспоминаний',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы начали осаду ворот последнего бастиона Алого ордена. В этот самый момент, когда вурдалаки разделываются с авангардом войск крепости, наши рабочие возводят передовое укрепление Плети – Склеп Воспоминаний.$B$BОтправляйся на юг, к склепу, граничащему с Новым Авалоном, и найди там моего дорогого брата, принца Келесета.$B$BЯ предупредил его о твоем прибытии.$B$BГотовься, $n, ибо тебе предстоит познать второй урок военного искусства плети: становление власти!$B$BВперед, рыцарь смерти!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите принца Келесета в Склепе Воспоминаний.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Приветствую тебя, рыцарь смерти. Я – принц крови Келесет, правитель юго-восточных пределов Нордскола. Король-лич пожелал воспользоваться моими силами, чтобы покончить с жалким сопротивлением смертных, и я счастлив подчиниться воле моего господина. В конце концов, кто бы отказался насладиться страданиями бесчисленных тысяч душ?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (12716,'Просьба распространителя чумы','Смотри сюда, тыквенная твоя голова! Ты видишь, что тут чего-то не хватает? Конечно, не видишь, куда тебе! У тебя и при жизни мозгов не было – что уж говорить о послесмертии.$B$B<Нот тяжело вздыхает.>$B$BМне приказали сделать чумной котел, и ты мне в этом поможешь.$B$BПрямо за вратами Нового Авалона есть таверна. Найди там и укради пустой котел. Затем найди кузницу неподалеку от ворот и стащи оттуда железную цепь. Добавь к перечню 10 черепов рыцарей Света и принеси все это мне. Надеюсь, мне не надо объяснять тебе, откуда взять черепа?','Нот Чумной попросил вас принести ему пустой котел, железную цепь и 10 черепов рыцарей Света.','Отлично! Сейчас я все сделаю...','Вернитесь к Ноту Чумному на Тихоземскую лесопилку, что в Чумных землях: Анклав Алого ордена.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Просьба распространителя чумы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Смотри сюда, тыквенная твоя голова! Ты видишь, что тут чего-то не хватает? Конечно, не видишь, куда тебе! У тебя и при жизни мозгов не было – что уж говорить о послесмертии.$B$B<Нот тяжело вздыхает.>$B$BМне приказали сделать чумной котел, и ты мне в этом поможешь.$B$BПрямо за вратами Нового Авалона есть таверна. Найди там и укради пустой котел. Затем найди кузницу неподалеку от ворот и стащи оттуда железную цепь. Добавь к перечню 10 черепов рыцарей Света и принеси все это мне. Надеюсь, мне не надо объяснять тебе, откуда взять черепа?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Нот Чумной попросил вас принести ему пустой котел, железную цепь и 10 черепов рыцарей Света.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! Сейчас я все сделаю...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ноту Чумному на Тихоземскую лесопилку, что в Чумных землях: Анклав Алого ордена.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12717,'Особое пойло Нота','Скоро мы напоим из этого чумного котелка всю землю!$B$BА теперь, рыцарь смерти, я преподам тебе небольшой урок по обращению с чумными котлами. Пары, поднимающиеся над этим варевом, смертельны для любого живого существа – но не для посвященного Плети. Как и любое создание Плети, он питается смертью и крепчает с каждой поглощенной порцией.$B$BВозьми эти черепа рыцарей Света и брось их в варево. Могу поспорить, тебе это понравится!','Положите груду рыцарских черепов в чумной котел.','Варево в чумном котле лениво булькает.','Разыщите чумной котел на Тихоземских фермах, что в Анклаве Алого ордена Чумных земель.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Особое пойло Нота',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Скоро мы напоим из этого чумного котелка всю землю!$B$BА теперь, рыцарь смерти, я преподам тебе небольшой урок по обращению с чумными котлами. Пары, поднимающиеся над этим варевом, смертельны для любого живого существа – но не для посвященного Плети. Как и любое создание Плети, он питается смертью и крепчает с каждой поглощенной порцией.$B$BВозьми эти черепа рыцарей Света и брось их в варево. Могу поспорить, тебе это понравится!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Положите груду рыцарских черепов в чумной котел.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Варево в чумном котле лениво булькает.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Разыщите чумной котел на Тихоземских фермах, что в Анклаве Алого ордена Чумных земель.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (12718,'Черепа для пойла','Вернитесь к чумному котлу в Анклав Алого ордена Чумных земель.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Черепа для пойла',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к чумному котлу в Анклав Алого ордена Чумных земель.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12719,'Некуда бежать и негде спрятаться','Меня устроит только полное уничтожение, $n. Несколько сотен безмозглых вурдалаков не смогут сокрушить врата Нового Авалона. Мы должны проникнуть во внутреннее святилище и уничтожить главу города. Мы дадим им понять, что от Плети нельзя укрыться за толщиной стен!$B$BПроберись в Ратушу Нового Авалона, которая находится к юго-западу отсюда, и убей мэра города. После этого обыщи здание и принеси мне учетную книгу Нового Авалона.','Принц Келесет из Склепа Воспоминаний приказал вам убить мэра Квимби и принести учетную книгу Нового Авалона.','Спасения нет!','Вернитесь к принцу Келесету в Склеп Воспоминаний, что в Чумных землях: Анклав Алого ордена.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Некуда бежать и негде спрятаться',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Меня устроит только полное уничтожение, $n. Несколько сотен безмозглых вурдалаков не смогут сокрушить врата Нового Авалона. Мы должны проникнуть во внутреннее святилище и уничтожить главу города. Мы дадим им понять, что от Плети нельзя укрыться за толщиной стен!$B$BПроберись в Ратушу Нового Авалона, которая находится к юго-западу отсюда, и убей мэра города. После этого обыщи здание и принеси мне учетную книгу Нового Авалона.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принц Келесет из Склепа Воспоминаний приказал вам убить мэра Квимби и принести учетную книгу Нового Авалона.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Спасения нет!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к принцу Келесету в Склеп Воспоминаний, что в Чумных землях: Анклав Алого ордена.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (12720,'Как завоевывать друзей и оказывать влияние на врагов','Путешествуя по миру, я сделал несколько важных открытий. Например, знаешь ли ты, что с помощью лести и подкупа можно вытянуть все тайны, скрытые в душе смертного? К счастью, у меня под рукой всегда есть подобные дары.$B$B<Келесет вынимает какой-то предмет из богато украшенной шкатулки.>$B$BВот мои лучшие "доводы", которые могут развязать язык любого смертного. Возьми их с собой на поле боя и предъяви солдатам Нового Авалона. Пусть они расскажут нам все про этот "Багровый Рассвет".','Принц Келесет из Склепа Воспоминаний приказал вам узнать всю правду про "Багровый Рассвет."$B$BДостаньте доводы Келесета из узорной шкатулки и "разговорите" с их помощью рыцарей Алого ордена.','Приведи мои доводы рыцарям Алого ордена. Рано или поздно кто-нибудь из них... поддастся на убеждения.','Вы узнали, что такое "Багровый Рассвет"','Вернитесь к принцу Келесету в Склеп Воспоминаний, что в Чумных землях: Анклав Алого ордена.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Как завоевывать друзей и оказывать влияние на врагов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Путешествуя по миру, я сделал несколько важных открытий. Например, знаешь ли ты, что с помощью лести и подкупа можно вытянуть все тайны, скрытые в душе смертного? К счастью, у меня под рукой всегда есть подобные дары.$B$B<Келесет вынимает какой-то предмет из богато украшенной шкатулки.>$B$BВот мои лучшие "доводы", которые могут развязать язык любого смертного. Возьми их с собой на поле боя и предъяви солдатам Нового Авалона. Пусть они расскажут нам все про этот "Багровый Рассвет".',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принц Келесет из Склепа Воспоминаний приказал вам узнать всю правду про "Багровый Рассвет."$B$BДостаньте доводы Келесета из узорной шкатулки и "разговорите" с их помощью рыцарей Алого ордена.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Приведи мои доводы рыцарям Алого ордена. Рано или поздно кто-нибудь из них... поддастся на убеждения.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Вы узнали, что такое "Багровый Рассвет"',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к принцу Келесету в Склеп Воспоминаний, что в Чумных землях: Анклав Алого ордена.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (12721,'Буйство','$n, времени уже не осталось. Мы должны забрать ключ и освободить Акали.$B$BЕго держат во внутреннем дворе перед входом в Гундрак, столицу Зул\'Драка. Цепи Акали держатся на четырех замках. Открой все замки и освободи бога-носорога.$B$BГундрак кишит ледяными троллями. И все же я думаю, что ты сможешь проскользнуть мимо них $gнезамеченным:незамеченной;. Главное – будь $gосторожен:осторожна;!$B$BКогда сделаешь все, что нужно, пожалуйста, сообщи об этом знахарю.','По поручению Хар\'коа из Зим\'Торги освободите Акали и сообщите об этом знахарю Кхуфу в Зим\'Торге.','Нет!$B$BЕще один бог уничтожен, и его сила похищена. Теперь пророк Акали угрожает нам напрямую.$B$BКогда он придет, он придет за Хар\'коа. Нельзя допустить, чтобы он забрал и ее силу тоже.$B$BНам надо вновь вопросить богов, $N. Они подскажут, что надо делать.','Что случилось?','Акали освобожден от оков.','Вернитесь к знахарю Кхуфу в Зим\'Торгу, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Буйство',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, времени уже не осталось. Мы должны забрать ключ и освободить Акали.$B$BЕго держат во внутреннем дворе перед входом в Гундрак, столицу Зул\'Драка. Цепи Акали держатся на четырех замках. Открой все замки и освободи бога-носорога.$B$BГундрак кишит ледяными троллями. И все же я думаю, что ты сможешь проскользнуть мимо них $gнезамеченным:незамеченной;. Главное – будь $gосторожен:осторожна;!$B$BКогда сделаешь все, что нужно, пожалуйста, сообщи об этом знахарю.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По поручению Хар\'коа из Зим\'Торги освободите Акали и сообщите об этом знахарю Кхуфу в Зим\'Торге.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Нет!$B$BЕще один бог уничтожен, и его сила похищена. Теперь пророк Акали угрожает нам напрямую.$B$BКогда он придет, он придет за Хар\'коа. Нельзя допустить, чтобы он забрал и ее силу тоже.$B$BНам надо вновь вопросить богов, $N. Они подскажут, что надо делать.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что случилось?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Акали освобожден от оков.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к знахарю Кхуфу в Зим\'Торгу, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12722,'Овцы на бойне','Большинство людей спасаются бегством, стоит только тени некрополя пасть на их город. Но Алый орден не таков!$B$BДолжен признаться, война с орденом доставляет мне огромное удовольствие. За прошедшие годы наши стычки привели к нескольким величайшим трагедиям в человеческой истории, но они, как видно, никогда не начнут учиться на собственных ошибках.$B$BМы просто не можем отказать им в праве вновь послужить Королю-личу! Отправляйся в Новый Авалон и утоли их жажду смерти. Не щади никого!','Барон Ривендер из Склепа Воспоминаний приказал вам убить 10 солдат Алого ордена и 15 жителей Нового Авалона.','Как овцы на бойне...','Вернитесь к барону Ривендеру в Склеп Воспоминаний, что в Чумных землях: Анклав Алого ордена.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Овцы на бойне',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Большинство людей спасаются бегством, стоит только тени некрополя пасть на их город. Но Алый орден не таков!$B$BДолжен признаться, война с орденом доставляет мне огромное удовольствие. За прошедшие годы наши стычки привели к нескольким величайшим трагедиям в человеческой истории, но они, как видно, никогда не начнут учиться на собственных ошибках.$B$BМы просто не можем отказать им в праве вновь послужить Королю-личу! Отправляйся в Новый Авалон и утоли их жажду смерти. Не щади никого!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Барон Ривендер из Склепа Воспоминаний приказал вам убить 10 солдат Алого ордена и 15 жителей Нового Авалона.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как овцы на бойне...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к барону Ривендеру в Склеп Воспоминаний, что в Чумных землях: Анклав Алого ордена.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (12723,'За Алым фронтом','Я отправил Орбаза, Тассариана и Кольтиру на поиски курьера. Они разбили лагерь за линией фронта, в Таверне Алого ордена, расположенной на юге Нового Авалона. Эта таверна хорошо скрыта от посторонних глаз между двумя садами неподалеку от Часовни Багрового Пламени. Найди ее и доложи о своем прибытии Орбазу Кровопорчу. Пусть он введет тебя в курс дела.','Найдите Орбаза Кровопорча в Таверне Алого ордена в Новом Авалоне.','Чумной котел булькает и расплескивает вокруг свое ядовитое содержимое, от которого поднимаются пары зеленоватого газа.\n\nЕсть ли у тебя еще несколько черепов рыцарей Света, чтобы добавить их в чумное варево?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','За Алым фронтом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я отправил Орбаза, Тассариана и Кольтиру на поиски курьера. Они разбили лагерь за линией фронта, в Таверне Алого ордена, расположенной на юге Нового Авалона. Эта таверна хорошо скрыта от посторонних глаз между двумя садами неподалеку от Часовни Багрового Пламени. Найди ее и доложи о своем прибытии Орбазу Кровопорчу. Пусть он введет тебя в курс дела.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Орбаза Кровопорча в Таверне Алого ордена в Новом Авалоне.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Чумной котел булькает и расплескивает вокруг свое ядовитое содержимое, от которого поднимаются пары зеленоватого газа.\n\nЕсть ли у тебя еще несколько черепов рыцарей Света, чтобы добавить их в чумное варево?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12724,'Путь истинного рыцаря','Мы понятия не имеем, где и когда должен появиться их проклятый курьер. Эти жалкие людишки тоже ничем не могут нам помочь.$B$B<Орбаз брезгливо указывает на трупы рыцарей Алого ордена, распростершиеся на полу.>$B$BВпрочем, мне все же удалось вытянуть кое-что из последнего слизняка. Оказалось, они хранят расписание патрулей в Крепости Алого ордена. Я поручаю тебе вломиться в крепость и достать этот документ. $B$BИщи самое большое здание в Новом Авалоне, который находится на северо-востоке.','Орбаз Кровопорч из Таверны Алого ордена в Новом Авалоне приказал вам украсть расписание патрулей Нового Авалона из Крепости Алого ордена.','Обыщи всю крепость! Расписание хранится где-то там!','Вернитесь к Орбазу Кровопорчу в Таверну Алого ордена, что в Чумных землях: Анклав Алого ордена.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путь истинного рыцаря',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы понятия не имеем, где и когда должен появиться их проклятый курьер. Эти жалкие людишки тоже ничем не могут нам помочь.$B$B<Орбаз брезгливо указывает на трупы рыцарей Алого ордена, распростершиеся на полу.>$B$BВпрочем, мне все же удалось вытянуть кое-что из последнего слизняка. Оказалось, они хранят расписание патрулей в Крепости Алого ордена. Я поручаю тебе вломиться в крепость и достать этот документ. $B$BИщи самое большое здание в Новом Авалоне, который находится на северо-востоке.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Орбаз Кровопорч из Таверны Алого ордена в Новом Авалоне приказал вам украсть расписание патрулей Нового Авалона из Крепости Алого ордена.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Обыщи всю крепость! Расписание хранится где-то там!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Орбазу Кровопорчу в Таверну Алого ордена, что в Чумных землях: Анклав Алого ордена.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (12725,'Братья по смерти','Прорваться сквозь оборону Алого ордена было нелегко. Мы понесли серьезные потери, среди которых был один из наших лучших рыцарей смерти, Кольтира Ткач Смерти. Не знаю, жив он или мертв, но мы должны его найти.$B$BВ последний раз я видел его в цепях, пленником Крепости Алого ордена, которая находится на северо-востоке. Разбери это место на кучу камней, рыцарь смерти, но найди Кольтиру!','Найдите Кольтиру Ткача Смерти в Крепости Алого ордена.','Чумной котел булькает и расплескивает вокруг свое ядовитое содержимое, от которого поднимаются пары зеленоватого газа.\n\nЕсть ли у тебя еще несколько черепов рыцарей Света, чтобы добавить их в чумное варево?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Братья по смерти',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прорваться сквозь оборону Алого ордена было нелегко. Мы понесли серьезные потери, среди которых был один из наших лучших рыцарей смерти, Кольтира Ткач Смерти. Не знаю, жив он или мертв, но мы должны его найти.$B$BВ последний раз я видел его в цепях, пленником Крепости Алого ордена, которая находится на северо-востоке. Разбери это место на кучу камней, рыцарь смерти, но найди Кольтиру!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Кольтиру Ткача Смерти в Крепости Алого ордена.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Чумной котел булькает и расплескивает вокруг свое ядовитое содержимое, от которого поднимаются пары зеленоватого газа.\n\nЕсть ли у тебя еще несколько черепов рыцарей Света, чтобы добавить их в чумное варево?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12726,'Песнь ветра и воды','Слушаешь голос шторма? О да, здесь, на уступе Ваятеля Бурь можно услышать древнюю песнь – песнь Ветра и Воды...$B$BВеликая буря поглощает детей штормов и тайфунов. Возьми этот барабан, сыграй его песню... песню Хайфуна.$B$BПомоги ему насытиться ветром и водой, чтобы буря продолжалась.','Блестящих штучек всегда мало... Великий камень дождя добр к нам, мы должны быть добры к Великому камню дождя.','Вернитесь к оракулу Су-ни в Прибежище Гласа Дождя, что в Низине Шолазар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Песнь ветра и воды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слушаешь голос шторма? О да, здесь, на уступе Ваятеля Бурь можно услышать древнюю песнь – песнь Ветра и Воды...$B$BВеликая буря поглощает детей штормов и тайфунов. Возьми этот барабан, сыграй его песню... песню Хайфуна.$B$BПомоги ему насытиться ветром и водой, чтобы буря продолжалась.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Блестящих штучек всегда мало... Великий камень дождя добр к нам, мы должны быть добры к Великому камню дождя.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к оракулу Су-ни в Прибежище Гласа Дождя, что в Низине Шолазар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12727,'Кровавый побег','Я слышу вой сирен – скоро сюда прибудет верховный инквизитор и его послушники. Мои раны слишком тяжелы, но я все же постараюсь помочь тебе, чем смогу.$B$BУбей верховного инквизитора и его приспешников. Отруби ему голову и принеси ее Тассариану. Пусть этот акт отмщения прольется бальзамом на его ожесточенную душу. $B$BИ еще, $n... Если тебе удастся выжить и добраться до Тассариана, передай ему, что Алый орден казнит своих пленных в часовне. Возможно, он отправит тебя туда, чтобы ты $gсмог:смогла; проявить себя еще раз.','Убейте верховного инквизитора Валрота и отнесите его голову Тассариану в таверну Алого ордена в Новом Авалоне.','Какие новости от Кольтиры?','Вернитесь к Тассариану в Таверну Алого ордена, что в Чумных землях: Анклав Алого ордена.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кровавый побег',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я слышу вой сирен – скоро сюда прибудет верховный инквизитор и его послушники. Мои раны слишком тяжелы, но я все же постараюсь помочь тебе, чем смогу.$B$BУбей верховного инквизитора и его приспешников. Отруби ему голову и принеси ее Тассариану. Пусть этот акт отмщения прольется бальзамом на его ожесточенную душу. $B$BИ еще, $n... Если тебе удастся выжить и добраться до Тассариана, передай ему, что Алый орден казнит своих пленных в часовне. Возможно, он отправит тебя туда, чтобы ты $gсмог:смогла; проявить себя еще раз.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте верховного инквизитора Валрота и отнесите его голову Тассариану в таверну Алого ордена в Новом Авалоне.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Какие новости от Кольтиры?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тассариану в Таверну Алого ордена, что в Чумных землях: Анклав Алого ордена.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12728,'Наблюдения за расселиной: пещера Зимних Плавников','Мне нужно собрать воедино мои заметки и подготовить выступление для моих коллег в Даларане.$B$BПока я займусь этим, я должен попросить тебя посетить пещеру Зимних Плавников на севере отсюда. Тебе нужно будет воспользоваться тайнометром, стоя у устья пещеры.$B$BВозвращайся ко мне, как только соберешь данные. Без них моя документация будет неполной.','По просьбе библиотекаря Гаррена с Янтарной гряды воспользуйтесь тайнометром у пещер Зимних Плавников.','Ну что, |3-6($C), дело сделано? Клаксимус мертв?','Вернитесь к библиотекарю Гаррену на Янтарную гряду, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наблюдения за расселиной: пещера Зимних Плавников',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне нужно собрать воедино мои заметки и подготовить выступление для моих коллег в Даларане.$B$BПока я займусь этим, я должен попросить тебя посетить пещеру Зимних Плавников на севере отсюда. Тебе нужно будет воспользоваться тайнометром, стоя у устья пещеры.$B$BВозвращайся ко мне, как только соберешь данные. Без них моя документация будет неполной.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По просьбе библиотекаря Гаррена с Янтарной гряды воспользуйтесь тайнометром у пещер Зимних Плавников.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, |3-6($C), дело сделано? Клаксимус мертв?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к библиотекарю Гаррену на Янтарную гряду, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12732,'Сила озаренной крови','Однажды Реджек станет могучим воином. Кровь и небесный огонь сделают Реджека сильным. Скоро увидишь.$B$BРеджек даст тебе фиал, а ты пойдешь далеко на запад, на самую вершину Колонны Солнечного Благословления. Наполни фиал водой.$B$BПотом иди к северному краю долины: там есть гряда к северу от Полей Костей. Там найдешь матриарха кровокрылов, убьешь ее и наберешь ее крови.$B$BСмешай кровь с водой, принеси Реджеку. Реджек выпьет, станет сильным.','Принесите фиал озаренной крови матриарха Реджеку на холм Бешеного Сердца.','У тебя подарок для Реджека?','Вернитесь к Реджеку на Холм Бешеного Сердца, что в Низине Шолазар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сила озаренной крови',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Однажды Реджек станет могучим воином. Кровь и небесный огонь сделают Реджека сильным. Скоро увидишь.$B$BРеджек даст тебе фиал, а ты пойдешь далеко на запад, на самую вершину Колонны Солнечного Благословления. Наполни фиал водой.$B$BПотом иди к северному краю долины: там есть гряда к северу от Полей Костей. Там найдешь матриарха кровокрылов, убьешь ее и наберешь ее крови.$B$BСмешай кровь с водой, принеси Реджеку. Реджек выпьет, станет сильным.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите фиал озаренной крови матриарха Реджеку на холм Бешеного Сердца.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У тебя подарок для Реджека?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Реджеку на Холм Бешеного Сердца, что в Низине Шолазар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12733,'Вызов смерти','Олрун Зовущая Битву приказала вам выиграть 5 дуэлей с другими рыцарями смерти.$B$BВыберите себе противников среди посвященных рыцарей смерти или других игроков.','Победа приносит славу, рыцарь смерти! Ты заслуживаешь похвалы самого Короля-лича!','Ты $gпрошел:прошла; испытание?','Вернитесь к Олрун Зовущей Битву в Разлом Смерти, что в Чумных землях: Анклав Алого ордена.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вызов смерти',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Олрун Зовущая Битву приказала вам выиграть 5 дуэлей с другими рыцарями смерти.$B$BВыберите себе противников среди посвященных рыцарей смерти или других игроков.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Победа приносит славу, рыцарь смерти! Ты заслуживаешь похвалы самого Короля-лича!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $gпрошел:прошла; испытание?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Олрун Зовущей Битву в Разлом Смерти, что в Чумных землях: Анклав Алого ордена.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12734,'Реджек: первая кровь','Омойте меч Реджека в крови осы Сапфирного улья, лютого барабанча и трех воинов или оракулов Шепота Тумана. Вернитесь на холм Бешеного Сердца к Реджеку.','Реджек видит пятна крови врагов на своем мече. Теперь у Реджека есть могучее оружие, и сам он станет могучим воином!','Меч Реджека омыт в крови врагов, да?','Вернитесь к Реджеку на Холм Бешеного Сердца, что в Низине Шолазар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Реджек: первая кровь',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Омойте меч Реджека в крови осы Сапфирного улья, лютого барабанча и трех воинов или оракулов Шепота Тумана. Вернитесь на холм Бешеного Сердца к Реджеку.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Реджек видит пятна крови врагов на своем мече. Теперь у Реджека есть могучее оружие, и сам он станет могучим воином!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Меч Реджека омыт в крови врагов, да?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Реджеку на Холм Бешеного Сердца, что в Низине Шолазар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12735,'Очищающая песня','Земля низины Шолазар чиста. Колонны защищали эту низину многие века.$B$BВоды не столь чисты, ибо текут из-за пределов Шолазара... из океанов, озер и рек. Иногда вода приносит с собой недобрых духов; ее необходимо очистить.$B$BВозьми эти колокола – пусть они прозвенят подле озера Горьких Волн, у реки Ледяных Оков и у Слияния рек. Тогда злой дух разгневается... и ты убьешь его.','Су-ни из прибежища Гласа Дождя хочет, чтобы вы прозвонили в колокола Очищения возле озера Горьких Волн, у реки Ледяных Оков и у Слияния рек, а затем убили злых духов, отравляющих эти воды.','Блестящих штучек всегда мало... Великий камень дождя добр к нам, мы должны быть добры к Великому камню дождя.','Вернитесь к оракулу Су-ни в Прибежище Гласа Дождя, что в Низине Шолазар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Очищающая песня',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Земля низины Шолазар чиста. Колонны защищали эту низину многие века.$B$BВоды не столь чисты, ибо текут из-за пределов Шолазара... из океанов, озер и рек. Иногда вода приносит с собой недобрых духов; ее необходимо очистить.$B$BВозьми эти колокола – пусть они прозвенят подле озера Горьких Волн, у реки Ледяных Оков и у Слияния рек. Тогда злой дух разгневается... и ты убьешь его.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Су-ни из прибежища Гласа Дождя хочет, чтобы вы прозвонили в колокола Очищения возле озера Горьких Волн, у реки Ледяных Оков и у Слияния рек, а затем убили злых духов, отравляющих эти воды.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Блестящих штучек всегда мало... Великий камень дождя добр к нам, мы должны быть добры к Великому камню дождя.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к оракулу Су-ни в Прибежище Гласа Дождя, что в Низине Шолазар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12736,'Кристальное сияние разума','Само собой, ты не умнее горлока! Ты же всего-навсего |3-6($r).$B$BНо и для тебя еще есть надежда! Докажи, что можешь учиться. Может, кристаллы сделают тебя $gумным:умной;, как они делают умными нас.$B$BЯ научу тебя песне, которая очистит твой разум. Ты сыграешь песню перед кристаллами, а кристаллы сделают тебя умнее... не $gтаким умным:такой умной;, как горлоки, конечно, но лучше, чем сейчас. Колонна Жизненной Силы разрушена, но остальные колонны все еще стоят!','Вот видишь? Ты уже становишься умнее. Ну, если уж не умнее, то счастливее наверняка!','Хорошо, что ты здесь и помогаешь нам. Это был долгий бой.','Вернитесь к оракулу Су-ни в Прибежище Гласа Дождя, что в Низине Шолазар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кристальное сияние разума',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Само собой, ты не умнее горлока! Ты же всего-навсего |3-6($r).$B$BНо и для тебя еще есть надежда! Докажи, что можешь учиться. Может, кристаллы сделают тебя $gумным:умной;, как они делают умными нас.$B$BЯ научу тебя песне, которая очистит твой разум. Ты сыграешь песню перед кристаллами, а кристаллы сделают тебя умнее... не $gтаким умным:такой умной;, как горлоки, конечно, но лучше, чем сейчас. Колонна Жизненной Силы разрушена, но остальные колонны все еще стоят!',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот видишь? Ты уже становишься умнее. Ну, если уж не умнее, то счастливее наверняка!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Хорошо, что ты здесь и помогаешь нам. Это был долгий бой.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к оракулу Су-ни в Прибежище Гласа Дождя, что в Низине Шолазар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12737,'Песнь Плодородия','Буря – разрушительная сила. Буря валит деревья и затапливает дома. $B$BНо буря может нести и силу жизни, если только знать верную песню. На уступе Ваятеля Бурь, что над Обителью Творцов, можно найти небольшие кучки грязи. Эта грязь плодородна и хранит в себе семена, способные дать могучие всходы. Нужно только подобрать правильную песню.$B$BВозьми этот рог и сыграй для них.','Оракул Су-ни из прибежища Гласа Дождя хочет, чтобы вы отправились на уступ Ваятеля Бурь, что к северо-западу от Обители Творцов, и сыграли на Роге Плодородия возле 8 кучек влажной плодородной грязи.','Хорошо, что ты здесь и помогаешь нам. Это был долгий бой.','Вернитесь к оракулу Су-ни в Прибежище Гласа Дождя, что в Низине Шолазар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Песнь Плодородия',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Буря – разрушительная сила. Буря валит деревья и затапливает дома. $B$BНо буря может нести и силу жизни, если только знать верную песню. На уступе Ваятеля Бурь, что над Обителью Творцов, можно найти небольшие кучки грязи. Эта грязь плодородна и хранит в себе семена, способные дать могучие всходы. Нужно только подобрать правильную песню.$B$BВозьми этот рог и сыграй для них.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Оракул Су-ни из прибежища Гласа Дождя хочет, чтобы вы отправились на уступ Ваятеля Бурь, что к северо-западу от Обители Творцов, и сыграли на Роге Плодородия возле 8 кучек влажной плодородной грязи.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Хорошо, что ты здесь и помогаешь нам. Это был долгий бой.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к оракулу Су-ни в Прибежище Гласа Дождя, что в Низине Шолазар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (12738,'Мольбы об отмщении','Мольбы об отмщении должны быть услышаны, $n. Командор Чумопал и его отряд рыцарей смерти сейчас направляется к Часовне Багрового Пламени, намереваясь стереть ее с лица земли и освободить наших пленных.$B$BЕсли поторопишься, ты все еще можешь их нагнать. Часовня находится к западу от этого места.','Найдите командора Чумопала в Часовне Багрового Пламени.','Какие новости от Кольтиры?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мольбы об отмщении',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мольбы об отмщении должны быть услышаны, $n. Командор Чумопал и его отряд рыцарей смерти сейчас направляется к Часовне Багрового Пламени, намереваясь стереть ее с лица земли и освободить наших пленных.$B$BЕсли поторопишься, ты все еще можешь их нагнать. Часовня находится к западу от этого места.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите командора Чумопала в Часовне Багрового Пламени.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Какие новости от Кольтиры?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12739,'Приятный сюрприз','Расчищая путь к темницам часовни, мы не ожидали найти там ничего удивительного. Но нас ждал приятный сюрприз! Похоже, орден не терял времени зря – тюремные камеры буквально битком набиты узниками из Серебряного Рассвета. Большинство из них были уже мертвы к тому времени, как мы их обнаружили, но некоторые все еще цепляются за свои жалкие жизни.$B$BЯ как раз собирался отправиться туда и казнить оставшихся пленников, но теперь с гордостью могу поручить тебе эту почетную миссию. Есть там один весьма мерзкий таурен, которого тебе будет особенно приятно предать смерти.','Командор Чумопал в Часовне Багрового Пламени поручил вам казнить Малара Храброга, узника из Серебряного Рассвета, заключенного в темнице.','Ну, как ощущения?','Вернитесь к командору Чумопалу в Часовню Багрового Пламени, что в Чумных землях: Анклав Алого ордена.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приятный сюрприз',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Расчищая путь к темницам часовни, мы не ожидали найти там ничего удивительного. Но нас ждал приятный сюрприз! Похоже, орден не терял времени зря – тюремные камеры буквально битком набиты узниками из Серебряного Рассвета. Большинство из них были уже мертвы к тому времени, как мы их обнаружили, но некоторые все еще цепляются за свои жалкие жизни.$B$BЯ как раз собирался отправиться туда и казнить оставшихся пленников, но теперь с гордостью могу поручить тебе эту почетную миссию. Есть там один весьма мерзкий таурен, которого тебе будет особенно приятно предать смерти.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Командор Чумопал в Часовне Багрового Пламени поручил вам казнить Малара Храброга, узника из Серебряного Рассвета, заключенного в темнице.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, как ощущения?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командору Чумопалу в Часовню Багрового Пламени, что в Чумных землях: Анклав Алого ордена.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12740,'Парашюты для Серебряного Авангарда','Эти чудовища с неба убивают моих людей! Падение с большой высоты – это страшная смерть.$B$B$C, тебе нужно передать им эти парашюты! По крайней мере, тогда у них будет хотя бы какой-то шанс выжить.','По поручению командира Фальштава на Серебряной заставе передайте парашюты 10 серебряным рыцарям или щитоносцам Серебряного Авангарда во внутреннем дворе.','Если ты снова здесь и говоришь со мной, почему я все еще вижу, как мои люди падают насмерть?','Вернитесь к командиру Фальштаву на Серебряную заставу, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Парашюты для Серебряного Авангарда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти чудовища с неба убивают моих людей! Падение с большой высоты – это страшная смерть.$B$B$C, тебе нужно передать им эти парашюты! По крайней мере, тогда у них будет хотя бы какой-то шанс выжить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По поручению командира Фальштава на Серебряной заставе передайте парашюты 10 серебряным рыцарям или щитоносцам Серебряного Авангарда во внутреннем дворе.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если ты снова здесь и говоришь со мной, почему я все еще вижу, как мои люди падают насмерть?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру Фальштаву на Серебряную заставу, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (12741,'Сила бури','Глупые длинноязыкие! Думают, если они станут петь облакам, это даст им силу. Реджек покажет длинноязыким, как обрести силу!$B$BДалеко-далеко на северо-западе есть большое ровное поле, которое длинноязыкие называют "уступ Ваятеля Бурь". Реджек уверен: туда можно добраться, только если летать, как птица.$B$BНа этом уступе – так слышал Реджек – обитают могучие духи воды и ветра. Убей их, забери их силу и принеси в храм длинноязыких – они называют его "Святилищем бурь". Как только ты обретешь абсолютную силу, Реджек будет ждать твоего возвращения.','Соберите 3 субстанции грозы и 3 субстанции бури и отнесите их в Святилище бурь. Вернитесь на холм Бешеного Сердца к Реджеку и принесите ему истинную силу бури.','Теперь Реджек покажет трусливым длинноязыким, как нужно использовать силу стихий!','Вернитесь к Реджеку на Холм Бешеного Сердца, что в Низине Шолазар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сила бури',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Глупые длинноязыкие! Думают, если они станут петь облакам, это даст им силу. Реджек покажет длинноязыким, как обрести силу!$B$BДалеко-далеко на северо-западе есть большое ровное поле, которое длинноязыкие называют "уступ Ваятеля Бурь". Реджек уверен: туда можно добраться, только если летать, как птица.$B$BНа этом уступе – так слышал Реджек – обитают могучие духи воды и ветра. Убей их, забери их силу и принеси в храм длинноязыких – они называют его "Святилищем бурь". Как только ты обретешь абсолютную силу, Реджек будет ждать твоего возвращения.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 3 субстанции грозы и 3 субстанции бури и отнесите их в Святилище бурь. Вернитесь на холм Бешеного Сердца к Реджеку и принесите ему истинную силу бури.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь Реджек покажет трусливым длинноязыким, как нужно использовать силу стихий!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Реджеку на Холм Бешеного Сердца, что в Низине Шолазар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12742,'Приятный сюрприз','Расчищая путь к темницам часовни, мы не ожидали найти там ничего удивительного. Однако нас ждал приятный сюрприз! Похоже, орден не терял времени зря – тюремные камеры буквально битком набиты узниками из Серебряного Рассвета. Большинство из них были уже мертвы к тому времени, как мы их обнаружили, но некоторые все еще цепляются за свои жалкие жизни.$B$BЯ как раз собирался отправиться туда и казнить оставшихся пленников, но теперь с гордостью могу поручить тебе эту почетную миссию. Есть там один весьма мерзкий человек, которого тебе будет особенно приятно предать смерти.','Командор Чумопал в Часовне Багрового Пламени поручил вам казнить Эллен Станбридж, узницу из Серебряного Рассвета, заключенную в темнице.','Ну, как ощущения?','Вернитесь к командору Чумопалу в Часовню Багрового Пламени, что в Чумных землях: Анклав Алого ордена.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приятный сюрприз',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Расчищая путь к темницам часовни, мы не ожидали найти там ничего удивительного. Однако нас ждал приятный сюрприз! Похоже, орден не терял времени зря – тюремные камеры буквально битком набиты узниками из Серебряного Рассвета. Большинство из них были уже мертвы к тому времени, как мы их обнаружили, но некоторые все еще цепляются за свои жалкие жизни.$B$BЯ как раз собирался отправиться туда и казнить оставшихся пленников, но теперь с гордостью могу поручить тебе эту почетную миссию. Есть там один весьма мерзкий человек, которого тебе будет особенно приятно предать смерти.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Командор Чумопал в Часовне Багрового Пламени поручил вам казнить Эллен Станбридж, узницу из Серебряного Рассвета, заключенную в темнице.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, как ощущения?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командору Чумопалу в Часовню Багрового Пламени, что в Чумных землях: Анклав Алого ордена.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12743,'Приятный сюрприз','Расчищая путь к темницам часовни, мы не ожидали найти там ничего удивительного. Но нас ждал приятный сюрприз! Похоже, орден не терял времени зря – тюремные камеры буквально битком набиты узниками из Серебряного Рассвета. Большинство из них были уже мертвы к тому времени, как мы их обнаружили, но некоторые все еще цепляются за свои жалкие жизни.$B$BЯ как раз собирался отправиться туда и казнить оставшихся пленников, но теперь с гордостью могу поручить тебе эту почетную миссию. Есть там один весьма мерзкий ночной эльф, которого тебе будет особенно приятно предать смерти.','Командор Чумопал в Часовне Багрового Пламени поручил вам казнить Язмину Окенторн, узника из Серебряного Рассвета, заключенного в темнице.','Не правда ли, приятно осознавать, что ты больше не на их стороне, $n. Ты – $gодин:одна; из нас. Солдат Плети, отныне и навсегда...','Ну, как ощущения?','Вернитесь к командору Чумопалу в Часовню Багрового Пламени, что в Анклаве Алого ордена в Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приятный сюрприз',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Расчищая путь к темницам часовни, мы не ожидали найти там ничего удивительного. Но нас ждал приятный сюрприз! Похоже, орден не терял времени зря – тюремные камеры буквально битком набиты узниками из Серебряного Рассвета. Большинство из них были уже мертвы к тому времени, как мы их обнаружили, но некоторые все еще цепляются за свои жалкие жизни.$B$BЯ как раз собирался отправиться туда и казнить оставшихся пленников, но теперь с гордостью могу поручить тебе эту почетную миссию. Есть там один весьма мерзкий ночной эльф, которого тебе будет особенно приятно предать смерти.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='