INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12747,'Приятный сюрприз','Расчищая путь к темницам часовни, мы не ожидали найти там ничего удивительного. Но нас ждал приятный сюрприз! Похоже, орден не терял времени зря – тюремные камеры буквально битком набиты узниками из Серебряного Рассвета. Большинство из них были уже мертвы к тому времени, как мы их обнаружили, но некоторые все еще цепляются за свои жалкие жизни.$B$BЯ как раз собирался отправиться туда и казнить оставшихся пленников, но теперь с гордостью могу поручить тебе эту почетную миссию. Есть там один весьма мерзкий эльф крови, которого тебе будет особенно приятно предать смерти.','Командор Чумопал в Часовне Багрового Пламени поручил вам казнить леди Эонис, узника из Серебряного Рассвета, заключенного в темнице.','Ну, как ощущения?','Вернитесь к командору Чумопалу в Часовню Багрового Пламени, что в Чумных землях: Анклав Алого ордена.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приятный сюрприз',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Расчищая путь к темницам часовни, мы не ожидали найти там ничего удивительного. Но нас ждал приятный сюрприз! Похоже, орден не терял времени зря – тюремные камеры буквально битком набиты узниками из Серебряного Рассвета. Большинство из них были уже мертвы к тому времени, как мы их обнаружили, но некоторые все еще цепляются за свои жалкие жизни.$B$BЯ как раз собирался отправиться туда и казнить оставшихся пленников, но теперь с гордостью могу поручить тебе эту почетную миссию. Есть там один весьма мерзкий эльф крови, которого тебе будет особенно приятно предать смерти.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Командор Чумопал в Часовне Багрового Пламени поручил вам казнить леди Эонис, узника из Серебряного Рассвета, заключенного в темнице.',`objectives_loc8`), `request