INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12748,'Приятный сюрприз','Расчищая путь к темницам часовни, мы не ожидали найти там ничего удивительного. Но нас ждал приятный сюрприз! Похоже, орден не терял времени зря – тюремные камеры буквально битком набиты узниками из Серебряного Рассвета. Большинство из них были уже мертвы к тому времени, как мы их обнаружили, но некоторые все еще цепляются за свои жалкие жизни.$B$BЯ как раз собирался отправиться туда и казнить оставшихся пленников, но теперь с гордостью могу поручить тебе эту почетную миссию. Есть там один весьма мерзкий орк, которого тебе будет особенно приятно предать смерти.','Командор Чумопал в Часовне Багрового Пламени поручил вам казнить Кага Сталезуба, узника из Серебряного Рассвета, заключенного в темнице.','Ну, как ощущения?','Вернитесь к командору Чумопалу в Часовню Багрового Пламени, что в Чумных землях: Анклав Алого ордена.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приятный сюрприз',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Расчищая путь к темницам часовни, мы не ожидали найти там ничего удивительного. Но нас ждал приятный сюрприз! Похоже, орден не терял времени зря – тюремные камеры буквально битком набиты узниками из Серебряного Рассвета. Большинство из них были уже мертвы к тому времени, как мы их обнаружили, но некоторые все еще цепляются за свои жалкие жизни.$B$BЯ как раз собирался отправиться туда и казнить оставшихся пленников, но теперь с гордостью могу поручить тебе эту почетную миссию. Есть там один весьма мерзкий орк, которого тебе будет особенно приятно предать смерти.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Командор Чумопал в Часовне Багрового Пламени поручил вам казнить Кага Сталезуба, узника из Серебряного Рассвета, заключенного в темнице.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, как ощущения?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командору Чумопалу в Часовню Багрового Пламени, что в Чумных землях: Анклав Алого ордена.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12749,'Приятный сюрприз','Расчищая путь к темницам часовни, мы не ожидали найти там ничего удивительного. Но нас ждал приятный сюрприз! Похоже, орден не терял времени зря – тюремные камеры буквально битком набиты узниками из Серебряного Рассвета. Большинство из них были уже мертвы к тому времени, как мы их обнаружили, но некоторые все еще цепляются за свои жалкие жизни.$B$BЯ как раз собирался отправиться туда и казнить оставшихся пленников, но теперь с гордостью могу поручить тебе эту почетную миссию. Есть там один весьма мерзкий тролль, которого тебе будет особенно приятно предать смерти.','Командор Чумопал в Часовне Багрового Пламени поручил вам казнить Игги Темноклыка, узника из Серебряного Рассвета, заключенного в темнице.','Не правда ли, приятно осознавать, что ты больше не на их стороне, $n. Ты – $gодин:одна; из нас. Солдат Плети, отныне и навсегда...','Ну, как ощущения?','Вернитесь к командору Чумопалу в Часовню Багрового Пламени, что в Чумных землях: Анклав Алого ордена.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приятный сюрприз',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Расчищая путь к темницам часовни, мы не ожидали найти там ничего удивительного. Но нас ждал приятный сюрприз! Похоже, орден не терял времени зря – тюремные камеры буквально битком набиты узниками из Серебряного Рассвета. Большинство из них были уже мертвы к тому времени, как мы их обнаружили, но некоторые все еще цепляются за свои жалкие жизни.$B$BЯ как раз собирался отправиться туда и казнить оставшихся пленников, но теперь с гордостью могу поручить тебе эту почетную миссию. Есть там один весьма мерзкий тролль, которого тебе будет особенно приятно предать смерти.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Командор Чумопал в Часовне Багрового Пламени поручил вам казнить Игги Темноклыка, узника из Серебряного Рассвета, заключенного в темнице.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Не правда ли, приятно осознавать, что ты больше не на их стороне, $n. Ты – $gодин:одна; из нас. Солдат Плети, отныне и навсегда...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, как ощущения?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командору Чумопалу в Часовню Багрового Пламени, что в Чумных землях: Анклав Алого ордена.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12750,'Приятный сюрприз','Расчищая путь к темницам часовни, мы не ожидали найти там ничего удивительного. Но нас ждал приятный сюрприз! Похоже, орден не терял времени зря – тюремные камеры буквально битком набиты узниками из Серебряного Рассвета. Большинство из них были уже мертвы к тому времени, как мы их обнаружили, но некоторые все еще цепляются за свои жалкие жизни.$B$BЯ как раз собирался отправиться туда и казнить оставшихся пленников, но теперь с гордостью могу поручить тебе эту почетную миссию. Есть там один весьма мерзкий Отрекшийся, которого тебе будет особенно приятно предать смерти.','Командор Чумопал в Часовне Багрового Пламени поручил вам казнить Антуана Брэка, узника из Серебряного Рассвета, заключенного в темнице.','Не правда ли, приятно осознавать, что ты больше не на их стороне, $n. Ты – $gодин:одна; из нас. Солдат Плети, отныне и навсегда...','Ну, как ощущения?','Вернитесь к командору Чумопалу в Часовню Багрового Пламени, что в Чумных землях: Анклав Алого ордена.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приятный сюрприз',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Расчищая путь к темницам часовни, мы не ожидали найти там ничего удивительного. Но нас ждал приятный сюрприз! Похоже, орден не терял времени зря – тюремные камеры буквально битком набиты узниками из Серебряного Рассвета. Большинство из них были уже мертвы к тому времени, как мы их обнаружили, но некоторые все еще цепляются за свои жалкие жизни.$B$BЯ как раз собирался отправиться туда и казнить оставшихся пленников, но теперь с гордостью могу поручить тебе эту почетную миссию. Есть там один весьма мерзкий Отрекшийся, которого тебе будет особенно приятно предать смерти.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Командор Чумопал в Часовне Багрового Пламени поручил вам казнить Антуана Брэка, узника из Серебряного Рассвета, заключенного в темнице.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Не правда ли, приятно осознавать, что ты больше не на их стороне, $n. Ты – $gодин:одна; из нас. Солдат Плети, отныне и навсегда...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, как ощущения?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командору Чумопалу в Часовню Багрового Пламени, что в Чумных землях: Анклав Алого ордена.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (12751,'Возвращение домой','Возвращайся к Тассариану в Таверну Алого ордена и сообщи ему, что мы отомстили за Кольтиру. Через несколько часов от Часовни Багрового Пламени останется только кучка пепла.$B$BТы – хладнокровное чудовище, $n. Я горжусь тобой, $gбрат:сестра;.','Возвращайтесь к Тассариану в Таверну Алого ордена, что в Новом Авалоне, и сообщите ему о вашей победе.','И снова Плеть празднует победу! Нет спасения псам Алого ордена. Смерть их близка...','Ну, как ощущения?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение домой',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Возвращайся к Тассариану в Таверну Алого ордена и сообщи ему, что мы отомстили за Кольтиру. Через несколько часов от Часовни Багрового Пламени останется только кучка пепла.$B$BТы – хладнокровное чудовище, $n. Я горжусь тобой, $gбрат:сестра;.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возвращайтесь к Тассариану в Таверну Алого ордена, что в Новом Авалоне, и сообщите ему о вашей победе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','И снова Плеть празднует победу! Нет спасения псам Алого ордена. Смерть их близка...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, как ощущения?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (12752,'Отчаянный поиск','Настал час, $n, когда Король-лич решил перейти в наступление. У нас есть лишь один шанс оттеснить его назад к его ледяному трону, и для этого Орда и Альянс должны встать плечом к плечу. Ради этого в Шаттрате, на Террасе Света, был заключен новый союз.$B$BВ этой битве против Короля-лича нам понадобится любая помощь. Отправляйся в новый аптекарский лагерь в Террасе Света и разыщи верховного аптекаря Гнилесса. Он возглавляет исследования по поиску вакцины против новой чумы, и лишь на него возложены все наши надежды.$B$BПоторопись, $n, ибо каждая секунда промедления может стоить нам еще одной унесенной жизни.','Поговорите с верховным аптекарем Гнилессом в новом аптекарском лагере на Террасе Света в Шаттрате.','Приветствую, $Gбрат:сестра;. Возможно, ты $Gпришел:пришла; от имени Серебряного Рассвета, но ты здесь не для этого - ты здесь, чтобы помочь своему народу заслужить уважение, которого так справедливо заслуживаете. Любой, покинувший нас, согласился бы, что цель оправдывает средства и наши исследования в области лечения чумы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отчаянный поиск',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Настал час, $n, когда Король-лич решил перейти в наступление. У нас есть лишь один шанс оттеснить его назад к его ледяному трону, и для этого Орда и Альянс должны встать плечом к плечу. Ради этого в Шаттрате, на Террасе Света, был заключен новый союз.$B$BВ этой битве против Короля-лича нам понадобится любая помощь. Отправляйся в новый аптекарский лагерь в Террасе Света и разыщи верховного аптекаря Гнилесса. Он возглавляет исследования по поиску вакцины против новой чумы, и лишь на него возложены все наши надежды.$B$BПоторопись, $n, ибо каждая секунда промедления может стоить нам еще одной унесенной жизни.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с верховным аптекарем Гнилессом в новом аптекарском лагере на Террасе Света в Шаттрате.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Приветствую, $Gбрат:сестра;. Возможно, ты $Gпришел:пришла; от имени Серебряного Рассвета, но ты здесь не для этого - ты здесь, чтобы помочь своему народу заслужить уважение, которого так справедливо заслуживаете. Любой, покинувший нас, согласился бы, что цель оправдывает средства и наши исследования в области лечения чумы.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (12753,'Вынужденный союз','$gОтважный:Отважная; $n, Король-лич выступил против всех нас, наслав чуму и проклятие на Орду и Альянс. Лишь объединив усилия, сможем мы выстоять против этого нашествия.$B$BПоэтому в Шаттрате, на Террасе Света, был заключен новый союз. Я прошу и твоей помощи в войне против Короля-лича. Отправляйся в новый лагерь Альянса на Террасе Света и поговори с епископом Лазарил.$B$BДоброго тебе пути, $n.','Поговорите с епископом Лазарил в новом лагере Альянса на Террасе Света в Шаттрате.','$GБрат:сестра; $R, я горжусь тем, что поддерживаю тебя в дни нужды. Благослови тебя и пусть союз между $R и человеком продлится тысячу лет.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вынужденный союз',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$gОтважный:Отважная; $n, Король-лич выступил против всех нас, наслав чуму и проклятие на Орду и Альянс. Лишь объединив усилия, сможем мы выстоять против этого нашествия.$B$BПоэтому в Шаттрате, на Террасе Света, был заключен новый союз. Я прошу и твоей помощи в войне против Короля-лича. Отправляйся в новый лагерь Альянса на Террасе Света и поговори с епископом Лазарил.$B$BДоброго тебе пути, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с епископом Лазарил в новом лагере Альянса на Террасе Света в Шаттрате.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','$GБрат:сестра; $R, я горжусь тем, что поддерживаю тебя в дни нужды. Благослови тебя и пусть союз между $R и человеком продлится тысячу лет.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12754,'Засада в укреплении','Пока ты $gбыл занят:была занята; сжиганием церквей и истреблением паразитов, я разработал план дальнейших действий.$B$BСудя по расписанию, курьер Алого ордена должен через час пройти мимо Дозорного укрепления Алого ордена. Дорога вдоль укрепления пролегает по открытой местности, кишащей рыцарями Света. Воспользуйся этой маскировкой, чтобы спрятаться в самом укреплении, и жди там, пока не покажется курьер Алого ордена. Как только он приблизится, убей его и забери все, что при нем будет, включая одежду!$B$BУкрепление находится на востоке в двухстах шагах от этого места.','Орбаз Кровопорч из Таверны Алого ордена в Новом Авалоне приказал вам убить курьера Алого ордена и забрать его пожитки и депешу.','<Орбаз читает депешу.>$B$BТак значит, армии Дольного Очага и Тирисфальских лугов направляются прямо к нам в руки!$B$B<Орбаз ухмыляется.>$B$BОтлично, переходим ко второй части нашего плана. Ты лично доставишь это донесение верховному генералу Аббендис. Для этого-то тебе и пригодятся эти шмотки...','Если упустишь курьера – я с тебя лично голову сниму. И сделаю это с превеликим удовольствием.$B$BЧего стоишь, беги!','Вернитесь к Орбазу Кровопорчу в Таверну Алого ордена, что в Чумных землях: Анклав Алого ордена.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Засада в укреплении',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пока ты $gбыл занят:была занята; сжиганием церквей и истреблением паразитов, я разработал план дальнейших действий.$B$BСудя по расписанию, курьер Алого ордена должен через час пройти мимо Дозорного укрепления Алого ордена. Дорога вдоль укрепления пролегает по открытой местности, кишащей рыцарями Света. Воспользуйся этой маскировкой, чтобы спрятаться в самом укреплении, и жди там, пока не покажется курьер Алого ордена. Как только он приблизится, убей его и забери все, что при нем будет, включая одежду!$B$BУкрепление находится на востоке в двухстах шагах от этого места.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Орбаз Кровопорч из Таверны Алого ордена в Новом Авалоне приказал вам убить курьера Алого ордена и забрать его пожитки и депешу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Орбаз читает депешу.>$B$BТак значит, армии Дольного Очага и Тирисфальских лугов направляются прямо к нам в руки!$B$B<Орбаз ухмыляется.>$B$BОтлично, переходим ко второй части нашего плана. Ты лично доставишь это донесение верховному генералу Аббендис. Для этого-то тебе и пригодятся эти шмотки...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если упустишь курьера – я с тебя лично голову сниму. И сделаю это с превеликим удовольствием.$B$BЧего стоишь, беги!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Орбазу Кровопорчу в Таверну Алого ордена, что в Чумных землях: Анклав Алого ордена.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12755,'Встреча с судьбой','Это сообщение должно попасть в руки Аббендис. Не стоит вызывать ненужные подозрения – пусть считает, что все идет по плану.$B$BТы облачишься в одежды курьера Алого ордена, а мы придадим тебе его облик с помощью черной магии.$B$BАббендис сейчас находится в Королевской гавани, что к юго-востоку от Дозорного укрепления Алого ордена. Отнеси это послание и постарайся вытянуть из нее как можно больше информации. Надеюсь, она поведает нам о "Багровом Рассвете".','Орбаз Кровопорч приказал вам доставить депешу курьера Алого ордена верховному генералу Аббендис в Королевскую гавань.','<Верховный генерал Аббендис читает депешу.>$B$BПроклятие! Войска Дольного Очага и Тирисфальских лугов нельзя было посылать в Новый Авалон! Плеть разгромит их еще на подходе!','Где ты пропадаешь? Тебя ждали два часа назад. Мы уже собирались послать курьера к главнокомандующему.','Вернитесь к верховному генералу Аббендис в Королевскую гавань, что в Чумных землях: Анклав Алого ордена.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Встреча с судьбой',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это сообщение должно попасть в руки Аббендис. Не стоит вызывать ненужные подозрения – пусть считает, что все идет по плану.$B$BТы облачишься в одежды курьера Алого ордена, а мы придадим тебе его облик с помощью черной магии.$B$BАббендис сейчас находится в Королевской гавани, что к юго-востоку от Дозорного укрепления Алого ордена. Отнеси это послание и постарайся вытянуть из нее как можно больше информации. Надеюсь, она поведает нам о "Багровом Рассвете".',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Орбаз Кровопорч приказал вам доставить депешу курьера Алого ордена верховному генералу Аббендис в Королевскую гавань.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Верховный генерал Аббендис читает депешу.>$B$BПроклятие! Войска Дольного Очага и Тирисфальских лугов нельзя было посылать в Новый Авалон! Плеть разгромит их еще на подходе!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Где ты пропадаешь? Тебя ждали два часа назад. Мы уже собирались послать курьера к главнокомандующему.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному генералу Аббендис в Королевскую гавань, что в Чумных землях: Анклав Алого ордена.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12756,'Алый Натиск','Отнесите Путь Искупления Орбазу Кровопорчу в Таверну Алого ордена в Новом Авалоне.','<Орбаз листает журнал.>$B$BКакая чепуха! Так вот что значит "Багровый Рассвет!"$B$BОни плывут прямо в лапы смерти! Впрочем, сейчас мы должны сосредоточиться на устранении идущих к нам армий.','<Орбаз хохочет.>$B$BЭто еще что? Детская раскраска?','Вернитесь к Орбазу Кровопорчу в Таверну Алого ордена, что в Чумных землях: Анклав Алого ордена.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Алый Натиск',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите Путь Искупления Орбазу Кровопорчу в Таверну Алого ордена в Новом Авалоне.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Орбаз листает журнал.>$B$BКакая чепуха! Так вот что значит "Багровый Рассвет!"$B$BОни плывут прямо в лапы смерти! Впрочем, сейчас мы должны сосредоточиться на устранении идущих к нам армий.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Орбаз хохочет.>$B$BЭто еще что? Детская раскраска?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Орбазу Кровопорчу в Таверну Алого ордена, что в Чумных землях: Анклав Алого ордена.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12757,'Теплый прием для армий Алого ордена','Мы должны подготовиться и достойно встретить армии захватчиков. Ты, $n, лично сообщишь эти сведения верховному лорду Могрейну! Я открою для тебя портал в Акерус. Войди в него, и он отправит тебя в нужное место.$B$BЗаодно отдай верховному лорду дневник Аббендис. Думаю, он почерпнет из него немало полезных сведений.','Что?','Вернитесь к верховному лорду Дариону Могрейну в Черный оплот.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Теплый прием для армий Алого ордена',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы должны подготовиться и достойно встретить армии захватчиков. Ты, $n, лично сообщишь эти сведения верховному лорду Могрейну! Я открою для тебя портал в Акерус. Войди в него, и он отправит тебя в нужное место.$B$BЗаодно отдай верховному лорду дневник Аббендис. Думаю, он почерпнет из него немало полезных сведений.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному лорду Дариону Могрейну в Черный оплот.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12758,'Шлем героя','Реджек видит, что удача на твоей стороне! А теперь Реджек наденет новый шлем…','Где новый шлем для Реджека?','Вернитесь к Реджеку на Холм Бешеного Сердца, что в Низине Шолазар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Шлем героя',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Реджек видит, что удача на твоей стороне! А теперь Реджек наденет новый шлем…',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Где новый шлем для Реджека?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Реджеку на Холм Бешеного Сердца, что в Низине Шолазар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12759,'Орудия войны','Зепик говорит – может, ты лучший охотник горлоков, которого он встречал... кроме Зепика. На юго-западе идет большой бой: иди туда и помоги.$B$BЗепик держит самые страшные и опасные ловушки в форте Картака... сказал Векгару, что их можно пустить в ход в бою, так что ты тоже можешь их взять. Иди, бери любые ловушки, какие хочешь. Убей много длинноязыких!$B$BОчень много длинноязыких!','Раздобудьте несколько ловушек Зепика из форта Картака. Используя ловушки, убейте 50 горлоков из племени Заиндевелых, а затем вернитесь к шаману Якжеку в форт Картака.','Ты управляешься с этими ловушками почти так же хорошо, как Зепик!','Немного грязно! Но все равно так весело.','Вернитесь к шаману Якжеку в Форт Картака, что в Низине Шолазар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Орудия войны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Зепик говорит – может, ты лучший охотник горлоков, которого он встречал... кроме Зепика. На юго-западе идет большой бой: иди туда и помоги.$B$BЗепик держит самые страшные и опасные ловушки в форте Картака... сказал Векгару, что их можно пустить в ход в бою, так что ты тоже можешь их взять. Иди, бери любые ловушки, какие хочешь. Убей много длинноязыких!$B$BОчень много длинноязыких!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте несколько ловушек Зепика из форта Картака. Используя ловушки, убейте 50 горлоков из племени Заиндевелых, а затем вернитесь к шаману Якжеку в форт Картака.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты управляешься с этими ловушками почти так же хорошо, как Зепик!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Немного грязно! Но все равно так весело.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к шаману Якжеку в Форт Картака, что в Низине Шолазар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12760,'Тайная сила племени Бешеного Сердца','Воспользовавшись силой секретного напитка племени Бешеного Сердца, перебейте 30 горлоков из племени Заиндевелых у форта Картака.','А ты боец что надо... Приходи, еще посражаешься! Хорошего боя много не бывает!','Вектар научил тебя нашему суперсекрету, да? Только самые сильные из Бешеного Сердца знают этот секрет.','Вернитесь к шаману Якжеку в Форт Картака, что в Низине Шолазар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тайная сила племени Бешеного Сердца',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользовавшись силой секретного напитка племени Бешеного Сердца, перебейте 30 горлоков из племени Заиндевелых у форта Картака.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А ты боец что надо... Приходи, еще посражаешься! Хорошего боя много не бывает!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вектар научил тебя нашему суперсекрету, да? Только самые сильные из Бешеного Сердца знают этот секрет.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к шаману Якжеку в Форт Картака, что в Низине Шолазар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12761,'Власть над кристаллами','Волосатые все еще нападают на Заиндевелых... мы думаем, что, возможно, они не остановятся, если мы их не остановим. Но у нас есть тайное оружие...Мы послали его Су-мету: с его помощью он сумеет защитить всех Оракулов.$B$BЭто тайное оружие создали сами Великие... а сияющие кристаллы для него можно найти в священных храмах Великих. Будь очень $gосторожен:осторожна;... не разбей их.$B$BКристаллы в сундуке возле святилища в Заиндевелой гавани, далеко на юго-западе. Потом ты поможешь Су-мету использовать кристаллы, чтобы одолеть волосатых.','Очень могущественно. Люди-щенки не знают о силе Великих. Тупые щенячьи человечки.','Поговорите с призывателем Су-метом в Заиндевелой гавани, что в Низине Шолазар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Власть над кристаллами',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Волосатые все еще нападают на Заиндевелых... мы думаем, что, возможно, они не остановятся, если мы их не остановим. Но у нас есть тайное оружие...Мы послали его Су-мету: с его помощью он сумеет защитить всех Оракулов.$B$BЭто тайное оружие создали сами Великие... а сияющие кристаллы для него можно найти в священных храмах Великих. Будь очень $gосторожен:осторожна;... не разбей их.$B$BКристаллы в сундуке возле святилища в Заиндевелой гавани, далеко на юго-западе. Потом ты поможешь Су-мету использовать кристаллы, чтобы одолеть волосатых.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Очень могущественно. Люди-щенки не знают о силе Великих. Тупые щенячьи человечки.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с призывателем Су-метом в Заиндевелой гавани, что в Низине Шолазар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12762,'Могущество Великих','Мы должны что-то сделать. Надо остановить волосатых, нападающих на Заиндевелую гавань. Джалут принес мне особенный кристалл, который он нашел в Слиянии рек... такой мы видели лишь однажды.$B$BСейчас у кристалла нет силы, но она вернется, если только поднести его к разрушенной колонне Жизненной Силы. Когда кристалл обретет силу, иди в Заиндевелую гавань на юго-западе: пусть кристалл даст тебе великую мощь!$B$BТогда ты сумеешь справиться с волосатыми.','Хорошо, что ты здесь и помогаешь нам. Это был долгий бой.','Поговорите с призывателем Су-метом в Заиндевелой гавани, что в Низине Шолазар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Могущество Великих',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы должны что-то сделать. Надо остановить волосатых, нападающих на Заиндевелую гавань. Джалут принес мне особенный кристалл, который он нашел в Слиянии рек... такой мы видели лишь однажды.$B$BСейчас у кристалла нет силы, но она вернется, если только поднести его к разрушенной колонне Жизненной Силы. Когда кристалл обретет силу, иди в Заиндевелую гавань на юго-западе: пусть кристалл даст тебе великую мощь!$B$BТогда ты сумеешь справиться с волосатыми.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Хорошо, что ты здесь и помогаешь нам. Это был долгий бой.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с призывателем Су-метом в Заиндевелой гавани, что в Низине Шолазар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (12763,'Смена приоритетов','Разведчик Вор\'такх просит вас отправиться в Зул\'Драк и разыскать сержанта Рианну в Разломе Света.$b$bВам укажет дорогу Макки Зимний Ветер, находящаяся в лагере Уанква.','Во имя Света!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Смена приоритетов',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разведчик Вор\'такх просит вас отправиться в Зул\'Драк и разыскать сержанта Рианну в Разломе Света.$b$bВам укажет дорогу Макки Зимний Ветер, находящаяся в лагере Уанква.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Во имя Света!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (12765,'Кунгалуш') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кунгалуш',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (12766,'Разговор с послом','<Дракон в облике эльфа берет ваше рекомендательное письмо, изучает его в течение пары секунд, а затем прячет себе в рукав.>$B$BПохоже, все в порядке. Но если не возражаешь, я попросил бы тебя поговорить с вашей посланницей здесь, в храме.$B$BУ нее есть к тебе какое-то важное дело, с которым нужно разобраться раньше, чем мы отправим тебя к королеве.$B$B<Он похлопывает по письму, скрытому в рукаве.>$B$BОно будет ждать тебя в целости и сохранности.','Поговорите с Лориэль Верный Клинок в храме Драконьего Покоя.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разговор с послом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Дракон в облике эльфа берет ваше рекомендательное письмо, изучает его в течение пары секунд, а затем прячет себе в рукав.>$B$BПохоже, все в порядке. Но если не возражаешь, я попросил бы тебя поговорить с вашей посланницей здесь, в храме.$B$BУ нее есть к тебе какое-то важное дело, с которым нужно разобраться раньше, чем мы отправим тебя к королеве.$B$B<Он похлопывает по письму, скрытому в рукаве.>$B$BОно будет ждать тебя в целости и сохранности.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Лориэль Верный Клинок в храме Драконьего Покоя.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (12767,'Разговор с послом','<Дракон в облике эльфа берет ваше рекомендательное письмо, изучает его в течение пары секунд, а затем прячет себе в рукав.>$B$BПохоже, все в порядке. Но если не возражаешь, я попросил бы тебя поговорить с вашим послом здесь, в храме.$B$BУ него есть к тебе какое-то важное дело, с которым нужно разобраться раньше, чем мы отправим тебя к королеве.$B$B<Он похлопывает по письму, скрытому в рукаве.>$B$BОно будет ждать тебя в целости и сохранности.','Поговорите с Голлуком Каменным Кулаком в храме Драконьего Покоя.','Да, |3-6($R)? Чем могу служить?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разговор с послом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Дракон в облике эльфа берет ваше рекомендательное письмо, изучает его в течение пары секунд, а затем прячет себе в рукав.>$B$BПохоже, все в порядке. Но если не возражаешь, я попросил бы тебя поговорить с вашим послом здесь, в храме.$B$BУ него есть к тебе какое-то важное дело, с которым нужно разобраться раньше, чем мы отправим тебя к королеве.$B$B<Он похлопывает по письму, скрытому в рукаве.>$B$BОно будет ждать тебя в целости и сохранности.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Голлуком Каменным Кулаком в храме Драконьего Покоя.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да, |3-6($R)? Чем могу служить?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (12768,'Распорядитель храма Драконьего Покоя','Ты $gдоказал:доказала;, что тебе можно доверить все и даже больше.$B$BВозвращайся в храм Драконьего Покоя, $n, и снова поговори с его распорядителем, Тариолстразом.','Поговорите с Тариолстразом в храме Драконьего Покоя.','Уже $Gвернулся:вернулась;, $N?$B$BЦеристраз сообщил о тебе заранее. Спасибо за то, что ты $Gсовершил:совершила; в Рубиновом святилище.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Распорядитель храма Драконьего Покоя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gдоказал:доказала;, что тебе можно доверить все и даже больше.$B$BВозвращайся в храм Драконьего Покоя, $n, и снова поговори с его распорядителем, Тариолстразом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Тариолстразом в храме Драконьего Покоя.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Уже $Gвернулся:вернулась;, $N?$B$BЦеристраз сообщил о тебе заранее. Спасибо за то, что ты $Gсовершил:совершила; в Рубиновом святилище.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (12769,'Распорядитель храма Драконьего Покоя','Ты $gдоказал:доказала;, что тебе можно доверить все и даже больше.$B$BВозвращайся в храм Драконьего Покоя, $n, и снова поговори с его распорядителем, Тариолстразом.','Поговорите с Тариолстразом в храме Драконьего Покоя.','Ты вернулся! То, о чем я просил тебя, выполнено?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Распорядитель храма Драконьего Покоя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gдоказал:доказала;, что тебе можно доверить все и даже больше.$B$BВозвращайся в храм Драконьего Покоя, $n, и снова поговори с его распорядителем, Тариолстразом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Тариолстразом в храме Драконьего Покоя.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты вернулся! То, о чем я просил тебя, выполнено?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (12770,'Перераспределение','Слушай внимательно, |3-6($c)!$b$bЗдесь твоя служба подошла к концу. Нет, нам все еще очень нужны умелые |3-7($c), но сейчас твоя помощь нужна на севере. По сравнению с тем, что там происходит, наши проблемы кажутся ничтожными. $b$bОказалось, что Плеть не теряла времени зря, и сейчас ее армия штурмует Зул\'Драк. Если эта твердыня падет, то погребет под собою всех нас.$b$bЗакончи все свои дела и немедленно отправляйся в Разлом Света. Самуэль поможет тебе добраться до места.$b$bВольно!','Гриан Камнегрив отправил вас к сержанту Рианне в Разлом Света, находящийся в Зул\'Драке.$b$bОбратитесь к Самуэлю Клирбуку, и он доставит вас на место.','Во имя Света!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Перераспределение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слушай внимательно, |3-6($c)!$b$bЗдесь твоя служба подошла к концу. Нет, нам все еще очень нужны умелые |3-7($c), но сейчас твоя помощь нужна на севере. По сравнению с тем, что там происходит, наши проблемы кажутся ничтожными. $b$bОказалось, что Плеть не теряла времени зря, и сейчас ее армия штурмует Зул\'Драк. Если эта твердыня падет, то погребет под собою всех нас.$b$bЗакончи все свои дела и немедленно отправляйся в Разлом Света. Самуэль поможет тебе добраться до места.$b$bВольно!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Гриан Камнегрив отправил вас к сержанту Рианне в Разлом Света, находящийся в Зул\'Драке.$b$bОбратитесь к Самуэлю Клирбуку, и он доставит вас на место.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Во имя Света!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12771,'Стальгорн','Наши молитвы услышаны! Сосредоточив Свет наару Шаттрата, воззвав к благословению просветленных, мы создали священные артефакты великой силы, которые послужат нам в войне против Короля-лича.$B$BВозьми эту святыню, $n. Охраняй ее как зеницу ока и доставь в Стальгорн в целости и сохранности. Я знаю, что Магни Бронзобороду не терпится выступить в Нордскол, и с помощью этого артефакта он быстрее достигнет цели.','Епископ Лазарил просит вас отнести заряженный Светом артефакт королю Магни Бронзобороду в Стальгорн.','Клянусь моей бородой! Это может соперничать с флотом наших летательных аппаратов! Я отдам его своим военным жрецам, и мы разработаем план, как отправить эти мерзкие некрополи обратно в Нордскол...!$B$BО, брат мой Мурадин, ты должен жить! Клянусь честью Бронзобородов, я найду тебя!','Привет, $N. Более крепкого $R я никогда не видел! Испытания Запределья сделали тебя крепче, $Gбрат:сестра;.','Вернитесь к королю Магни Бронзобороду в Дун Морог.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Стальгорн',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наши молитвы услышаны! Сосредоточив Свет наару Шаттрата, воззвав к благословению просветленных, мы создали священные артефакты великой силы, которые послужат нам в войне против Короля-лича.$B$BВозьми эту святыню, $n. Охраняй ее как зеницу ока и доставь в Стальгорн в целости и сохранности. Я знаю, что Магни Бронзобороду не терпится выступить в Нордскол, и с помощью этого артефакта он быстрее достигнет цели.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Епископ Лазарил просит вас отнести заряженный Светом артефакт королю Магни Бронзобороду в Стальгорн.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Клянусь моей бородой! Это может соперничать с флотом наших летательных аппаратов! Я отдам его своим военным жрецам, и мы разработаем план, как отправить эти мерзкие некрополи обратно в Нордскол...!$B$BО, брат мой Мурадин, ты должен жить! Клянусь честью Бронзобородов, я найду тебя!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Привет, $N. Более крепкого $R я никогда не видел! Испытания Запределья сделали тебя крепче, $Gбрат:сестра;.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к королю Магни Бронзобороду в Дун Морог.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (12772,'Вынужденный союз','$gОтважный:Отважная; $n, Король-лич выступил против всех нас, наслав чуму и проклятие на Орду и Альянс. Лишь объединив усилия, мы сможем выстоять против этого нашествия.$B$BПоэтому в Шаттрате, на Террасе Света, был заключен новый союз. Я прошу и твоей помощи в войне против Короля-лича. Отправляйся в новый лагерь Альянса на Террасе Света и поговори с епископом Лазарил.$B$BДоброго тебе пути, $n.','Поговорите с епископом Лазарил в новом лагере Альянса на Террасе Света в Шаттрате.','$N, достопочтенный $R, добро пожаловать. Пусть Свет сияет на тебе и пусть твоя мудрость хранит нашу землю в эти трудные времена.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вынужденный союз',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$gОтважный:Отважная; $n, Король-лич выступил против всех нас, наслав чуму и проклятие на Орду и Альянс. Лишь объединив усилия, мы сможем выстоять против этого нашествия.$B$BПоэтому в Шаттрате, на Террасе Света, был заключен новый союз. Я прошу и твоей помощи в войне против Короля-лича. Отправляйся в новый лагерь Альянса на Террасе Света и поговори с епископом Лазарил.$B$BДоброго тебе пути, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с епископом Лазарил в новом лагере Альянса на Террасе Света в Шаттрате.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','$N, достопочтенный $R, добро пожаловать. Пусть Свет сияет на тебе и пусть твоя мудрость хранит нашу землю в эти трудные времена.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12773,'Дарнас','Наши молитвы услышаны! Сосредоточив Свет наару Шаттрата, воззвав к благословению просветленных, мы создали священные артефакты великой силы, которые послужат нам в войне против Короля-лича.$B$BВозьми эту святыню, $n. Охраняй ее как зеницу ока и доставь в Дарнас в целости и сохранности. Я знаю, что Тиранда Шелест Ветра и ее жрецы смогут разумно распорядиться этой силой в борьбе против презренных порождений Плети.','Епископ Лазарил просит вас отнести заряженный Светом артефакт Тиранде Шелест Ветра в Дарнас.','Что это? Какой дар! Они словили такой Свет в этот артефакт, он сияет почти как луна! Наши жрецы направят эту силу против наших врагов и вторжение Короля-лича обязательно потерпит неудачу. Спасибо, $N. Наше мировое древо будет в безопасности.','$N, $Gсын:дочь; $Gмой:моя;. Мы снова втянуты в конфликт, который может разрушить все, что мы знаем. Хорошо, если твои таланты вложат свои силы в защиту этого мирового дерева.','Вернитесь к Тиранде Шелест Ветра в Храмовые сады, что в Дарнасе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дарнас',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наши молитвы услышаны! Сосредоточив Свет наару Шаттрата, воззвав к благословению просветленных, мы создали священные артефакты великой силы, которые послужат нам в войне против Короля-лича.$B$BВозьми эту святыню, $n. Охраняй ее как зеницу ока и доставь в Дарнас в целости и сохранности. Я знаю, что Тиранда Шелест Ветра и ее жрецы смогут разумно распорядиться этой силой в борьбе против презренных порождений Плети.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Епископ Лазарил просит вас отнести заряженный Светом артефакт Тиранде Шелест Ветра в Дарнас.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что это? Какой дар! Они словили такой Свет в этот артефакт, он сияет почти как луна! Наши жрецы направят эту силу против наших врагов и вторжение Короля-лича обязательно потерпит неудачу. Спасибо, $N. Наше мировое древо будет в безопасности.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$N, $Gсын:дочь; $Gмой:моя;. Мы снова втянуты в конфликт, который может разрушить все, что мы знаем. Хорошо, если твои таланты вложат свои силы в защиту этого мирового дерева.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тиранде Шелест Ветра в Храмовые сады, что в Дарнасе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12774,'Штормград','Наши молитвы услышаны! Сосредоточив Свет наару Шаттрата, воззвав к благословению просветленных, мы создали священные артефакты великой силы, которые послужат нам в войне против Короля-лича.$B$BВозьми эту святыню, $n. Охраняй ее как зеницу ока и доставь в Штормград в целости и сохранности. Не сомневаюсь, что новообретенный король найдет применение этому оружию.','Итак, святой народ Шаттрата создал то, что обещал! Оглядываясь в прошлое, можно было спасти столько жрецов и паладинов, не посылая их воевать с Плетью. Этим святым оружием мы сможем дать отпор проклятому Королю-личу и его приспешникам!$B$BХвалю Вас, $Gлорд:леди; $N.','$N, рад тебя видеть. Твои сила и навыки - это благо в это время невзгод.','Вернитесь к королю Вариану Ринну в Элвиннский лес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Штормград',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наши молитвы услышаны! Сосредоточив Свет наару Шаттрата, воззвав к благословению просветленных, мы создали священные артефакты великой силы, которые послужат нам в войне против Короля-лича.$B$BВозьми эту святыню, $n. Охраняй ее как зеницу ока и доставь в Штормград в целости и сохранности. Не сомневаюсь, что новообретенный король найдет применение этому оружию.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Итак, святой народ Шаттрата создал то, что обещал! Оглядываясь в прошлое, можно было спасти столько жрецов и паладинов, не посылая их воевать с Плетью. Этим святым оружием мы сможем дать отпор проклятому Королю-личу и его приспешникам!$B$BХвалю Вас, $Gлорд:леди; $N.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$N, рад тебя видеть. Твои сила и навыки - это благо в это время невзгод.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к королю Вариану Ринну в Элвиннский лес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (12775,'Вынужденный союз','$gОтважный:Отважная; $n, Король-лич выступил против всех нас, наслав чуму и проклятие на Орду и Альянс. Лишь объединив усилия, сможем мы выстоять против этого нашествия.$B$BПоэтому в Шаттрате, на Террасе Света, был заключен новый союз. Я прошу и твоей помощи в войне против Короля-лича. Отправляйся в новый лагерь Альянса на Террасе Света и поговори с епископом Лазарил.$B$BДоброго тебе пути, $n.','Поговорите с епископом Лазарил в новом лагере Альянса на Террасе Света в Шаттрате.','$GБрат:Сестра;, мы снова призваны сражаться с Плетью. Хорошо, что ты здесь с твоей силой и силой Света мы еще можем победить.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вынужденный союз',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$gОтважный:Отважная; $n, Король-лич выступил против всех нас, наслав чуму и проклятие на Орду и Альянс. Лишь объединив усилия, сможем мы выстоять против этого нашествия.$B$BПоэтому в Шаттрате, на Террасе Света, был заключен новый союз. Я прошу и твоей помощи в войне против Короля-лича. Отправляйся в новый лагерь Альянса на Террасе Света и поговори с епископом Лазарил.$B$BДоброго тебе пути, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с епископом Лазарил в новом лагере Альянса на Террасе Света в Шаттрате.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','$GБрат:Сестра;, мы снова призваны сражаться с Плетью. Хорошо, что ты здесь с твоей силой и силой Света мы еще можем победить.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12776,'Экзодар','Епископ Лазарил просит вас отнести заряженный Светом артефакт Велену в Экзодар.','Ах, я вижу, как сила наару проникает внутрь как будто там находится Свет. С помощью этого оружия можно нести добро.','$GМой:Моя; $Gсын:дочь;, земли людей и орков хорошо с тобой обращались. Такая сила сейчас набухает в тебе ...','Вернитесь к пророку Велену.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Экзодар',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Епископ Лазарил просит вас отнести заряженный Светом артефакт Велену в Экзодар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ах, я вижу, как сила наару проникает внутрь как будто там находится Свет. С помощью этого оружия можно нести добро.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$GМой:Моя; $Gсын:дочь;, земли людей и орков хорошо с тобой обращались. Такая сила сейчас набухает в тебе ...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к пророку Велену.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (12777,'Вынужденный союз','$gОтважный:Отважная; $n, Король-лич выступил против всех нас, наслав чуму и проклятие на Орду и Альянс. Лишь объединив усилия двух противостоящих друг другу сторон, мы сможем выстоять против этого нашествия.$B$BПоэтому в Шаттрате, на Террасе Света, был заключен новый союз. Я прошу и твоей помощи в войне против Короля-лича. Отправляйся в новый лагерь Альянса на Террасе Света и поговори с епископом Лазарил.$B$BДоброго тебе пути, $n.','Поговорите с епископом Лазарил в новом лагере Альянса на Террасе Света в Шаттрате.','Мое сердце наполнилось Светом, когда ты, благородный $R, пришел нам на помощь. Будь здоров, добрый $C!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вынужденный союз',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$gОтважный:Отважная; $n, Король-лич выступил против всех нас, наслав чуму и проклятие на Орду и Альянс. Лишь объединив усилия двух противостоящих друг другу сторон, мы сможем выстоять против этого нашествия.$B$BПоэтому в Шаттрате, на Террасе Света, был заключен новый союз. Я прошу и твоей помощи в войне против Короля-лича. Отправляйся в новый лагерь Альянса на Террасе Света и поговори с епископом Лазарил.$B$BДоброго тебе пути, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с епископом Лазарил в новом лагере Альянса на Террасе Света в Шаттрате.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мое сердце наполнилось Светом, когда ты, благородный $R, пришел нам на помощь. Будь здоров, добрый $C!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (12778,'Конец Алого ордена','Мышеловка захлопнулась, рыцарь смерти. Армии Дольного Очага и Тирисфальских лесов прибыли как раз вовремя, чтобы узреть падение своего аванпоста! Если они решат повернуть назад, мы ударим им в спину. $B$B<Могрейн качает головой.>$B$BУвы, у них не осталось выбора, кроме как принять свою смерть!$B$BВ этот самый момент они готовятся к свой последней битве.$B$BКороль-лич ожидает твоего возвращения, защитник. Он взирает на нас с высоты Разлома Смерти.','Найдите Короля-лича в Разломе Смерти.','Что?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Конец Алого ордена',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мышеловка захлопнулась, рыцарь смерти. Армии Дольного Очага и Тирисфальских лесов прибыли как раз вовремя, чтобы узреть падение своего аванпоста! Если они решат повернуть назад, мы ударим им в спину. $B$B<Могрейн качает головой.>$B$BУвы, у них не осталось выбора, кроме как принять свою смерть!$B$BВ этот самый момент они готовятся к свой последней битве.$B$BКороль-лич ожидает твоего возвращения, защитник. Он взирает на нас с высоты Разлома Смерти.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Короля-лича в Разломе Смерти.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12779,'Конец всему...','На твоих руках кровь бесчисленных жертв, но твое черное сердце все еще не насытилось их страданиями. Оно никогда не утолит эту жажду, $n.$B$B<Король-лич умолкает.>$B$BНо всему на свете приходит конец, рыцарь смерти. Армии Алого ордена собираются на последнюю битву против нас. Им нет спасения, пути назад отрезаны, и потому они будут сражаться с невиданной яростью.$B$BВозьми этот рог и призови одного из моих змеев. На его спине ты поведешь в бой наши войска, и рев его ознаменует конец Алого ордена.','Король-лич приказал вам покончить с Алым орденом.$B$BВозьмите рог ледяного наследия и призовите ледяного покорителя, с помощью которого вам надо будет убить 150 солдат из Алого ордена и уничтожить 10 баллист Алого ордена. Постарайтесь не попасть под обстрел и вовремя уходите с линии огня!','Убей их всех...','Вернитесь к Королю-личу в Разлом Смерти, что в Чумных землях: Анклав Алого ордена.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Конец всему...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На твоих руках кровь бесчисленных жертв, но твое черное сердце все еще не насытилось их страданиями. Оно никогда не утолит эту жажду, $n.$B$B<Король-лич умолкает.>$B$BНо всему на свете приходит конец, рыцарь смерти. Армии Алого ордена собираются на последнюю битву против нас. Им нет спасения, пути назад отрезаны, и потому они будут сражаться с невиданной яростью.$B$BВозьми этот рог и призови одного из моих змеев. На его спине ты поведешь в бой наши войска, и рев его ознаменует конец Алого ордена.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Король-лич приказал вам покончить с Алым орденом.$B$BВозьмите рог ледяного наследия и призовите ледяного покорителя, с помощью которого вам надо будет убить 150 солдат из Алого ордена и уничтожить 10 баллист Алого ордена. Постарайтесь не попасть под обстрел и вовремя уходите с линии огня!',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Убей их всех...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Королю-личу в Разлом Смерти, что в Чумных землях: Анклав Алого ордена.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (12780,'ИСПОРЧЕНО>>Враг наших врагов','Вообще-то, мы не особенно жалуем рыцарей смерти, но сейчас мы не в том положении, чтобы быть слишком разборчивыми в выборе союзников.$b$bМы зажаты между силами Плети и свирепыми Драккари, причем и те, и другие пытаются нас уничтожить, чтобы пробиться друг к другу.$b$bИди на запад – на Черную заставу. Поговори со Стефаном и спроси, не нужна ли ему твоя помощь.','По поручению сержанта Рианны из Разлома Света поговорите со Стефаном на Черной заставе и предложите ему свою помощь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','ИСПОРЧЕНО>>Враг наших врагов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вообще-то, мы не особенно жалуем рыцарей смерти, но сейчас мы не в том положении, чтобы быть слишком разборчивыми в выборе союзников.$b$bМы зажаты между силами Плети и свирепыми Драккари, причем и те, и другие пытаются нас уничтожить, чтобы пробиться друг к другу.$b$bИди на запад – на Черную заставу. Поговори со Стефаном и спроси, не нужна ли ему твоя помощь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По поручению сержанта Рианны из Разлома Света поговорите со Стефаном на Черной заставе и предложите ему свою помощь.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12781,'Добро пожаловать!','Добро пожаловать в World of Warcraft!$B$BВы приобрели коллекционное издание World of Warcraft и получаете в качестве благодарности этот подарочный сертификат. Отнесите его Банши Сиокси в Черный Оплот и получите подарок: маленького компаньона, который будет сопровождать вас на пути к приключениям и славе.$B$BЕще раз большое спасибо – и приятного пребывания в World of Warcraft!','Отнесите подарочный сертификат Черного оплота в Черный оплот и отдайте его Банши Сиокси.','Мы приветствуем вас в мире Азерота и предлагаем вам один из этих уникальных подарков.','Я вижу у тебя есть специальный ваучер. Отдай его мне и я предложу тебе что-нибудь взамен.','Вернитесь к банши Сиокси.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Добро пожаловать!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Добро пожаловать в World of Warcraft!$B$BВы приобрели коллекционное издание World of Warcraft и получаете в качестве благодарности этот подарочный сертификат. Отнесите его Банши Сиокси в Черный Оплот и получите подарок: маленького компаньона, который будет сопровождать вас на пути к приключениям и славе.$B$BЕще раз большое спасибо – и приятного пребывания в World of Warcraft!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите подарочный сертификат Черного оплота в Черный оплот и отдайте его Банши Сиокси.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мы приветствуем вас в мире Азерота и предлагаем вам один из этих уникальных подарков.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я вижу у тебя есть специальный ваучер. Отдай его мне и я предложу тебе что-нибудь взамен.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к банши Сиокси.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (12782,'Отчаянный поиск','Настал час, $n, когда Король-лич решил перейти в наступление. У нас есть лишь один шанс оттеснить его назад к его ледяному трону, и для этого Орда и Альянс должны встать плечом к плечу. Ради этого в Шаттрате, на Террасе Света, был заключен новый союз.$B$BВ этой битве против Короля-лича нам понадобится любая помощь. Отправляйся в новый аптекарский лагерь в Террасе Света и разыщи верховного аптекаря Гнилесса. Он возглавляет исследования по поиску вакцины против новой чумы, и лишь на него возложены все наши надежды.$B$BПоторопись, $n, ибо каждая секунда промедления может стоить нам еще одной унесенной жизни.','Поговорите с верховным аптекарем Гнилессом в новом аптекарском лагере на Террасе Света в Шаттрате.','Какой ты прекрасный образец. Нам предстоит провести много экспериментов и наша конюшня волонтеров почти разорена. Итак, эльф, как следует из самопровозглашенного названия вашей расы... У вас есть лишняя кровь? Свежая кровь действительно приветствуется...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отчаянный поиск',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Настал час, $n, когда Король-лич решил перейти в наступление. У нас есть лишь один шанс оттеснить его назад к его ледяному трону, и для этого Орда и Альянс должны встать плечом к плечу. Ради этого в Шаттрате, на Террасе Света, был заключен новый союз.$B$BВ этой битве против Короля-лича нам понадобится любая помощь. Отправляйся в новый аптекарский лагерь в Террасе Света и разыщи верховного аптекаря Гнилесса. Он возглавляет исследования по поиску вакцины против новой чумы, и лишь на него возложены все наши надежды.$B$BПоторопись, $n, ибо каждая секунда промедления может стоить нам еще одной унесенной жизни.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с верховным аптекарем Гнилессом в новом аптекарском лагере на Террасе Света в Шаттрате.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Какой ты прекрасный образец. Нам предстоит провести много экспериментов и наша конюшня волонтеров почти разорена. Итак, эльф, как следует из самопровозглашенного названия вашей расы... У вас есть лишняя кровь? Свежая кровь действительно приветствуется...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (12783,'Отчаянный поиск','Настал час, $n, когда Король-лич решил перейти в наступление. У нас есть лишь один шанс оттеснить его назад к его ледяному трону, и для этого Орда и Альянс должны встать плечом к плечу. Ради этого в Шаттрате, на Террасе Света, был заключен новый союз.$B$BВ этой битве против Короля-лича нам понадобится любая помощь. Отправляйся в новый аптекарский лагерь в Террасе Света и разыщи верховного аптекаря Гнилесса. Он возглавляет исследования по поиску вакцины против новой чумы, и лишь на него возложены все наши надежды.$B$BПоторопись, $n, ибо каждая секунда промедления может стоить нам еще одной унесенной жизни.','Поговорите с верховным аптекарем Гнилессом в новом аптекарском лагере на Террасе Света в Шаттрате.','Какой ты прекрасный, крепкий образец. Нам предстоит провести много экспериментов, и наша конюшня волонтеров почти разорена. Свежая кровь действительно приветствуется, и ярость в вашей крови может подпитывать часы исследований.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отчаянный поиск',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Настал час, $n, когда Король-лич решил перейти в наступление. У нас есть лишь один шанс оттеснить его назад к его ледяному трону, и для этого Орда и Альянс должны встать плечом к плечу. Ради этого в Шаттрате, на Террасе Света, был заключен новый союз.$B$BВ этой битве против Короля-лича нам понадобится любая помощь. Отправляйся в новый аптекарский лагерь в Террасе Света и разыщи верховного аптекаря Гнилесса. Он возглавляет исследования по поиску вакцины против новой чумы, и лишь на него возложены все наши надежды.$B$BПоторопись, $n, ибо каждая секунда промедления может стоить нам еще одной унесенной жизни.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с верховным аптекарем Гнилессом в новом аптекарском лагере на Террасе Света в Шаттрате.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Какой ты прекрасный, крепкий образец. Нам предстоит провести много экспериментов, и наша конюшня волонтеров почти разорена. Свежая кровь действительно приветствуется, и ярость в вашей крови может подпитывать часы исследований.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (12784,'Отчаянный поиск','Настал час, $n, когда Король-лич решил перейти в наступление. У нас есть лишь один шанс оттеснить его назад к его ледяному трону, и для этого Орда и Альянс должны встать плечом к плечу. Ради этого в Шаттрате, на Террасе Света, был заключен новый союз.$B$BВ этой битве против Короля-лича нам понадобится любая помощь. Отправляйся в новый аптекарский лагерь в Террасе Света и разыщи верховного аптекаря Гнилесса. Он возглавляет исследования по поиску вакцины против новой чумы, и лишь на него возложены все наши надежды.$B$BПоторопись, $n, ибо каждая секунда промедления может стоить нам еще одной унесенной жизни.','Поговорите с верховным аптекарем Гнилессом в новом аптекарском лагере на Террасе Света в Шаттрате.','Какой ты прекрасный, крепкий образец. Нам предстоит провести много экспериментов, и наша конюшня волонтеров почти разорена. Свежая кровь действительно приветствуется, и я уверен, что у кого-то из вашего статуса кровь есть...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отчаянный поиск',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Настал час, $n, когда Король-лич решил перейти в наступление. У нас есть лишь один шанс оттеснить его назад к его ледяному трону, и для этого Орда и Альянс должны встать плечом к плечу. Ради этого в Шаттрате, на Террасе Света, был заключен новый союз.$B$BВ этой битве против Короля-лича нам понадобится любая помощь. Отправляйся в новый аптекарский лагерь в Террасе Света и разыщи верховного аптекаря Гнилесса. Он возглавляет исследования по поиску вакцины против новой чумы, и лишь на него возложены все наши надежды.$B$BПоторопись, $n, ибо каждая секунда промедления может стоить нам еще одной унесенной жизни.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с верховным аптекарем Гнилессом в новом аптекарском лагере на Террасе Света в Шаттрате.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Какой ты прекрасный, крепкий образец. Нам предстоит провести много экспериментов, и наша конюшня волонтеров почти разорена. Свежая кровь действительно приветствуется, и я уверен, что у кого-то из вашего статуса кровь есть...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12785,'Оргриммар','Мы сделали великое открытие! Благодаря подопытным зомби мы вывели исследование природы чумы на совершенно новый уровень, и наш труд наконец-то дал первые, восхитительно червивые плоды!$B$BОтнеси этот ящик в Оргриммар. Внутри его находится голова, зараженная трупной чумой, и кое-что еще – первый образец нашей античумы. Две этих заразы схлестнутся в мозгу зомби, и результат этого скрещения даст нам ключ к изобретению вакцины.$B$BОтдай ящик моему помощнику, аптекарю Карлову. Ты найдешь его в доме вождя Тралла в Оргриммаре.','Верховный аптекарь Гнилесс просит вас отнести разрываемый на части мозг аптекарю Карлову в Оргриммаре.','Ах, очень хорошо. Болезни, которые несет эта сгнившая голова, смертельны, но мы не должны избегать опасности или того, что нам неприятно. Когда-нибудь, $N, ты узнаешь, что проклятие - это путь к спасению…','Добро пожаловать в Оргриммар, $N. Великий аптекарь Гнилресс передал тебе известие... у тебя инфицированный мозг?','Вернитесь к аптекарю Карлову в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оргриммар',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы сделали великое открытие! Благодаря подопытным зомби мы вывели исследование природы чумы на совершенно новый уровень, и наш труд наконец-то дал первые, восхитительно червивые плоды!$B$BОтнеси этот ящик в Оргриммар. Внутри его находится голова, зараженная трупной чумой, и кое-что еще – первый образец нашей античумы. Две этих заразы схлестнутся в мозгу зомби, и результат этого скрещения даст нам ключ к изобретению вакцины.$B$BОтдай ящик моему помощнику, аптекарю Карлову. Ты найдешь его в доме вождя Тралла в Оргриммаре.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верховный аптекарь Гнилесс просит вас отнести разрываемый на части мозг аптекарю Карлову в Оргриммаре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ах, очень хорошо. Болезни, которые несет эта сгнившая голова, смертельны, но мы не должны избегать опасности или того, что нам неприятно. Когда-нибудь, $N, ты узнаешь, что проклятие - это путь к спасению…',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Добро пожаловать в Оргриммар, $N. Великий аптекарь Гнилресс передал тебе известие... у тебя инфицированный мозг?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к аптекарю Карлову в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (12786,'Громовой Утес','Мы сделали великое открытие! Благодаря подопытным зомби мы вывели исследование природы чумы на совершенно новый уровень, и наш труд наконец-то дал первые, восхитительно червивые плоды!$B$BОтнеси этот ящик в Громовой Утес. Внутри его находится голова, зараженная трупной чумой, и кое-что еще – первый образец нашей прото-чумы. Две этих заразы схлестнутся в мозгу зомби, и результат этого скрещения даст нам ключ к изобретению вакцины.$B$BОтдай ящик моему помощнику, аптекарю Чейни. Ты найдешь его в доме Магаты Зловещий Тотем в Громовом Утесе.','Верховный аптекарь Гнилесс просит вас отнести разрываемый на части мозг аптекарю Чейни в Громовой Утес.','Вернитесь к аптекарю Чейни в Громовой Утес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Громовой Утес',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы сделали великое открытие! Благодаря подопытным зомби мы вывели исследование природы чумы на совершенно новый уровень, и наш труд наконец-то дал первые, восхитительно червивые плоды!$B$BОтнеси этот ящик в Громовой Утес. Внутри его находится голова, зараженная трупной чумой, и кое-что еще – первый образец нашей прото-чумы. Две этих заразы схлестнутся в мозгу зомби, и результат этого скрещения даст нам ключ к изобретению вакцины.$B$BОтдай ящик моему помощнику, аптекарю Чейни. Ты найдешь его в доме Магаты Зловещий Тотем в Громовом Утесе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верховный аптекарь Гнилесс просит вас отнести разрываемый на части мозг аптекарю Чейни в Громовой Утес.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к аптекарю Чейни в Громовой Утес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12787,'Подгород','Ах, какой прекрасный образец. Болезни - болезни - танцующие в твоём мозгу должны предлагать тебе такие возвышенные видения. Мы проведем долгие ночи в разговоре, ты и я, и я буду отбирать у тебя твои мысли, медленно извлекая мозги из твоего черепа.$B$BНе бойся, $Gмалец:малышка;. Знания, полученные в результате твоей жертвы, будут удивительными. Ты подарок отверженным, ты вознесешь новую эру уважения к нам среди народов этого мира. Твое место в нашей истории гарантировано...','Приветствую, $N. Ты из Шаттрата? У тебя есть инструкции от великого аптекаря Гнилесса?','Вернитесь к опытному аптекарю Фаранеллу на озеро Лордамер, что в Альтеракских горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подгород',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ах, какой прекрасный образец. Болезни - болезни - танцующие в твоём мозгу должны предлагать тебе такие возвышенные видения. Мы проведем долгие ночи в разговоре, ты и я, и я буду отбирать у тебя твои мысли, медленно извлекая мозги из твоего черепа.$B$BНе бойся, $Gмалец:малышка;. Знания, полученные в результате твоей жертвы, будут удивительными. Ты подарок отверженным, ты вознесешь новую эру уважения к нам среди народов этого мира. Твое место в нашей истории гарантировано...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Приветствую, $N. Ты из Шаттрата? У тебя есть инструкции от великого аптекаря Гнилесса?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к опытному аптекарю Фаранеллу на озеро Лордамер, что в Альтеракских горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12788,'Луносвет','Мы сделали великое открытие! Благодаря подопытным зомби мы вывели исследование природы чумы на совершенно новый уровень, и наш труд наконец-то дал первые, восхитительно червивые плоды!$B$BОтнеси этот ящик в Луносвет. Внутри его находится голова, зараженная трупной чумой, и кое-что еще – первый образец нашей античумы. Две этих заразы схлестнутся в мозгу зомби, и результат этого скрещения даст нам ключ к изобретению вакцины.$B$BОтдай ящик моему помощнику, аптекарю Тепеш. Ты найдешь ее в доме Лор\'темара Терона в Луносвете.','Верховный аптекарь Гнилесс просит вас отнести разрываемый на части мозг аптекарю Тепеш в Луносвет.','Ах, очень хорошо. Болезни, которые несет эта сгнившая голова, смертельны, но мы не должны избегать опасности или того, что нам неприятно. Когда-нибудь, $N, ты узнаешь, что проклятие - это путь к спасению…','Добро пожаловать в Луносвет, $N. Великий аптекарь Гнилресс передал тебе известие... у тебя инфицированный мозг?','Вернитесь к аптекарю Тепешу в Луносвет.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Луносвет',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы сделали великое открытие! Благодаря подопытным зомби мы вывели исследование природы чумы на совершенно новый уровень, и наш труд наконец-то дал первые, восхитительно червивые плоды!$B$BОтнеси этот ящик в Луносвет. Внутри его находится голова, зараженная трупной чумой, и кое-что еще – первый образец нашей античумы. Две этих заразы схлестнутся в мозгу зомби, и результат этого скрещения даст нам ключ к изобретению вакцины.$B$BОтдай ящик моему помощнику, аптекарю Тепеш. Ты найдешь ее в доме Лор\'темара Терона в Луносвете.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верховный аптекарь Гнилесс просит вас отнести разрываемый на части мозг аптекарю Тепеш в Луносвет.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ах, очень хорошо. Болезни, которые несет эта сгнившая голова, смертельны, но мы не должны избегать опасности или того, что нам неприятно. Когда-нибудь, $N, ты узнаешь, что проклятие - это путь к спасению…',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Добро пожаловать в Луносвет, $N. Великий аптекарь Гнилресс передал тебе известие... у тебя инфицированный мозг?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к аптекарю Тепешу в Луносвет.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (12789,'В Разлом!','Готовься, |3-6($c). Я отправляю тебя в Разлом Света, что к северо-востоку отсюда.$B$BЯ получил сообщение, что силы Плети из кожи вон лезут, чтобы захватить Зул\'Драк.$B$B<Валус не мигая смотрит вам прямо в глаза.>$B$BЭтого нельзя допустить.$B$BТы $gдолжен:должна; помочь в уничтожении сил Плети. Этого требует Свет.$B$B$GСвободен:Свободна;.','По распоряжению рыцаря Валуса из Опоры Света доложите о своем прибытии сержанту Рианне из Разлома Света в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В Разлом!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Готовься, |3-6($c). Я отправляю тебя в Разлом Света, что к северо-востоку отсюда.$B$BЯ получил сообщение, что силы Плети из кожи вон лезут, чтобы захватить Зул\'Драк.$B$B<Валус не мигая смотрит вам прямо в глаза.>$B$BЭтого нельзя допустить.$B$BТы $gдолжен:должна; помочь в уничтожении сил Плети. Этого требует Свет.$B$B$GСвободен:Свободна;.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По распоряжению рыцаря Валуса из Опоры Света доложите о своем прибытии сержанту Рианне из Разлома Света в Зул\'Драке.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12790,'Как уйти и вернуться: магический путь','На всякий случай, если ты вдруг не знаешь... ты можешь использовать этот кристалл на платформе у меня за спиной, чтобы телепортироваться на Аметистовую заставу в лесу Хрустальной Песни у Даларана.$B$BТочно так же ты можешь использовать кристалл на развалинах, чтобы вернуться в комнату, расположенную прямо надо мной.$B$BМне бы очень хотелось, чтобы ты $gотправился:отправилась; в путь немедленно.','Воспользуйтесь кристаллом телепортации на Аметистовую заставу у Даларана и кристаллом телепортации в Даларан по просьбе верховного мага Селиндры из Даларана.','Я чувствую, что ты еще не $Gпроверил:проверила; оба кристалла телепорта.$B$BВсе хорошо, не торопись.','Вернитесь к верховному магу Селиндре к Аметистовым вратам, что в Даларане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Как уйти и вернуться: магический путь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На всякий случай, если ты вдруг не знаешь... ты можешь использовать этот кристалл на платформе у меня за спиной, чтобы телепортироваться на Аметистовую заставу в лесу Хрустальной Песни у Даларана.$B$BТочно так же ты можешь использовать кристалл на развалинах, чтобы вернуться в комнату, расположенную прямо надо мной.$B$BМне бы очень хотелось, чтобы ты $gотправился:отправилась; в путь немедленно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь кристаллом телепортации на Аметистовую заставу у Даларана и кристаллом телепортации в Даларан по просьбе верховного мага Селиндры из Даларана.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я чувствую, что ты еще не $Gпроверил:проверила; оба кристалла телепорта.$B$BВсе хорошо, не торопись.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному магу Селиндре к Аметистовым вратам, что в Даларане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (12791,'Магическое королевство Даларан','Здравствуй, $n! Ты еще не $gслышал:слышала; о том, что Кирин-Тор перенес наш славный город сюда, в Нордскол?$B$BИстинная правда; Даларан больше не найти на берегах озера Лордамер. Теперь он волшебным образом парит над лесом Хрустальной Песни.$B$BПожалуй, ты уже $gготов:готова; совершить путешествие в наш город. Обратись ко мне, и я прочитаю заклинание телепортации.$B$BКак прибудешь на место, найди верховного мага Селиндру и передай ей мой перстень в знак того, что ты $gприбыл:прибыла; по моему поручению.','Отнесите кирин-торский перстень верховному магу Селиндре к Аметистовым Вратам Даларана.','Поговорите с верховным магом Селиндрой у Аметистовых врат, что в Даларане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Магическое королевство Даларан',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Здравствуй, $n! Ты еще не $gслышал:слышала; о том, что Кирин-Тор перенес наш славный город сюда, в Нордскол?$B$BИстинная правда; Даларан больше не найти на берегах озера Лордамер. Теперь он волшебным образом парит над лесом Хрустальной Песни.$B$BПожалуй, ты уже $gготов:готова; совершить путешествие в наш город. Обратись ко мне, и я прочитаю заклинание телепортации.$B$BКак прибудешь на место, найди верховного мага Селиндру и передай ей мой перстень в знак того, что ты $gприбыл:прибыла; по моему поручению.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите кирин-торский перстень верховному магу Селиндре к Аметистовым Вратам Даларана.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с верховным магом Селиндрой у Аметистовых врат, что в Даларане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (12792,'Первым делом','Слушай, |3-6($r)!$b$bУ нас тут повсюду – один сплошной кризис. Куда ни глянь – нашим людям везде нужна помощь.$b$b<Кунц смотрит вам прямо в глаза.>$b$bНо конкретно на данный момент больше всех в помощи нуждается Рианна. Силы Плети заняли территорию между нами, и Рианна с ее отрядом оказалась отрезанной.$b$bРазлом Света, который удерживает Рианна, находится прямо на юго-западе отсюда.','По поручению командира Кунца помогите сержанту Рианне в Разломе Света.','Значит, мое донесение дошло до Кунца.$B$BЯ рада, что он жив-здоров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Первым делом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слушай, |3-6($r)!$b$bУ нас тут повсюду – один сплошной кризис. Куда ни глянь – нашим людям везде нужна помощь.$b$b<Кунц смотрит вам прямо в глаза.>$b$bНо конкретно на данный момент больше всех в помощи нуждается Рианна. Силы Плети заняли территорию между нами, и Рианна с ее отрядом оказалась отрезанной.$b$bРазлом Света, который удерживает Рианна, находится прямо на юго-западе отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По поручению командира Кунца помогите сержанту Рианне в Разломе Света.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Значит, мое донесение дошло до Кунца.$B$BЯ рада, что он жив-здоров.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (12793,'Дым на горизонте','Слышишь, |3-6($r)?$b$bГрохот битвы далеко-далеко на западе слышен даже здесь, даже сквозь грохот нашей собственной битвы.$b$bСуществует реальная угроза, что силы Плети прорвут линию обороны тех, кто называет себя солдатами Серебряного Авангарда. Мы не должны этого допустить!$b$bИди в Разлом Света и помоги тем, кто сражается там. Поговори с Маакой, он обеспечит тебе безопасное путешествие.','По поручению Кхуфу из Зим\'Торги переговорите с сержантом Рианной в Разломе Света.$b$bМаака обеспечит вам безопасное путешествие.','Во имя Света!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дым на горизонте',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слышишь, |3-6($r)?$b$bГрохот битвы далеко-далеко на западе слышен даже здесь, даже сквозь грохот нашей собственной битвы.$b$bСуществует реальная угроза, что силы Плети прорвут линию обороны тех, кто называет себя солдатами Серебряного Авангарда. Мы не должны этого допустить!$b$bИди в Разлом Света и помоги тем, кто сражается там. Поговори с Маакой, он обеспечит тебе безопасное путешествие.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По поручению Кхуфу из Зим\'Торги переговорите с сержантом Рианной в Разломе Света.$b$bМаака обеспечит вам безопасное путешествие.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Во имя Света!',`offerrewardtext_loc8`);
