INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (12795,'На помощь заставе','Буквально пару секунд назад я заметила сигнальную вспышку над восточными лесами.$b$bЭто может означать только одно: у рыцарей Серебряной заставы что-то случилось, и явно что-то не очень приятное.$b$bЯ не могу бросить пост и уйти, |3-6($r), а ты можешь. При первой удобной возможности отправляйся туда, к командиру Фальштаву, и помоги им, чем сможешь.','По поручению Датуры Кровавой Розы поговорите с командиром Фальштавом на Серебряной заставе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На помощь заставе',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Буквально пару секунд назад я заметила сигнальную вспышку над восточными лесами.$b$bЭто может означать только одно: у рыцарей Серебряной заставы что-то случилось, и явно что-то не очень приятное.$b$bЯ не могу бросить пост и уйти, |3-6($r), а ты можешь. При первой удобной возможности отправляйся туда, к командиру Фальштаву, и помоги им, чем сможешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По поручению Датуры Кровавой Розы поговорите с командиром Фальштавом на Серебряной заставе.',`objectives_loc8`);
