INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (12797,'Назад по Связующей спирали','Вернитесь к Аватаре Фрейи к водопадам Гласа Дождя, что в низине Шолазар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Назад по Связующей спирали',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аватаре Фрейи к водопадам Гласа Дождя, что в низине Шолазар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12798,'Карты Новолуния: колода Мечей','Теперь, когда вы собрали все карты колоды Мечей, вы видите, как сверху появляется еще одна карта. На ней нарисован предсказатель, который глядит прямо на вас, независимо от того, под каким углом вы смотрите на изображение.$b$bВы чувствуете, что с помощью этой карты можно кого-то призвать.','Призовите предсказателя судьбы с Ярмарки Новолуния и отдайте ему колоду Мечей.','Гляжу, тебе удалось собрать всю колоду Мечей... Любопытно...','Вернитесь к предсказательнице ярмарки Новолуния.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Карты Новолуния: колода Мечей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда вы собрали все карты колоды Мечей, вы видите, как сверху появляется еще одна карта. На ней нарисован предсказатель, который глядит прямо на вас, независимо от того, под каким углом вы смотрите на изображение.$b$bВы чувствуете, что с помощью этой карты можно кого-то призвать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Призовите предсказателя судьбы с Ярмарки Новолуния и отдайте ему колоду Мечей.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Гляжу, тебе удалось собрать всю колоду Мечей... Любопытно...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к предсказательнице ярмарки Новолуния.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (12799,'Сбор эктоплазмы','Говорили, что мы должны радоваться тому, что он придет именно к нам. Мол, он такой весь из себя замечательный, с ним так приятно общаться... $b$bВпрочем, выбора у меня все равно не было. Финкльштейн – лучший алхимик Ордена. Наверное, я должен гордиться тем, что он выбрал мою заставу в качестве места для своей лаборатории. Но как только он тут появился, я только и делаю, что собираю всякие алхимические ингредиенты.$b$bМожет быть, |3-6($r), ты мне поможешь? К югу отсюда лежат озера, где обитают духи древних троллей. Собери их эктоплазму и принеси ее мне.','Соберите 5 колб древней эктоплазмы от заблудших духов Драккари на озерах Жа\'Джина для капитана Арната из Хеб\'Валока.','Вернитесь к капитану Арнату в Хеб\'Валок, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сбор эктоплазмы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Говорили, что мы должны радоваться тому, что он придет именно к нам. Мол, он такой весь из себя замечательный, с ним так приятно общаться... $b$bВпрочем, выбора у меня все равно не было. Финкльштейн – лучший алхимик Ордена. Наверное, я должен гордиться тем, что он выбрал мою заставу в качестве места для своей лаборатории. Но как только он тут появился, я только и делаю, что собираю всякие алхимические ингредиенты.$b$bМожет быть, |3-6($r), ты мне поможешь? К югу отсюда лежат озера, где обитают духи древних троллей. Собери их эктоплазму и принеси ее мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 5 колб древней эктоплазмы от заблудших духов Драккари на озерах Жа\'Джина для капитана Арната из Хеб\'Валока.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Арнату в Хеб\'Валок, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (12800,'Приказ Короля-лича','Найдите Командира Плети Таланора у лесопилки Бровача.','Верховный лорд и его верные рыцари смерти готовы нанести удар! Скоро мы опустошим это место.','Что?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приказ Короля-лича',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Командира Плети Таланора у лесопилки Бровача.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Верховный лорд и его верные рыцари смерти готовы нанести удар! Скоро мы опустошим это место.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12801,'Сияние Рассвета','Разбейте войска Серебряного Рассвета и найдите Сияние рассвета.$B$BЕсли вам удастся выжить, доложите о своей победе верховному лорду Дариону Могрейну.','<Верховный лорд Могрейн кивает.>','Поговорите с верховным лордом Дарионом Могрейном в Часовне Последней Надежды, что в Чумных землях: Анклав Алого ордена.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сияние Рассвета',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разбейте войска Серебряного Рассвета и найдите Сияние рассвета.$B$BЕсли вам удастся выжить, доложите о своей победе верховному лорду Дариону Могрейну.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Верховный лорд Могрейн кивает.>',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с верховным лордом Дарионом Могрейном в Часовне Последней Надежды, что в Чумных землях: Анклав Алого ордена.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (12802,'Мое сердце – в твоих руках','<Голос Дракуру проникает в ваш разум>$b$bЭй, $gдруг:подруга;! Какая потрясающая штука – этот глаз пророков! Я слежу за тобой с его помощью! Вижу, сердце уже у тебя в руках? Неплохо...$b$bДавай, неси его на мой пьедестал в Перевале Драк\'атала, что на востоке.$b$bТебе снова придется выпить мой эликсир!$b$bНа этот раз, подмешай в него немного настоя безнадеги!','Дракуру просит вас принести Сердце древних на его пьедестал в Перевале Драк\'атала.$b$bНо сначала вам надо будет собрать 5 настоев безнадеги – иначе эликсир не сработает.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мое сердце – в твоих руках',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Голос Дракуру проникает в ваш разум>$b$bЭй, $gдруг:подруга;! Какая потрясающая штука – этот глаз пророков! Я слежу за тобой с его помощью! Вижу, сердце уже у тебя в руках? Неплохо...$b$bДавай, неси его на мой пьедестал в Перевале Драк\'атала, что на востоке.$b$bТебе снова придется выпить мой эликсир!$b$bНа этот раз, подмешай в него немного настоя безнадеги!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Дракуру просит вас принести Сердце древних на его пьедестал в Перевале Драк\'атала.$b$bНо сначала вам надо будет собрать 5 настоев безнадеги – иначе эликсир не сработает.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (12803,'Сила природы','Я не слишком уверен в том, что именно я видел, летя на северо-восток, но выглядело это как огромная женщина, легко расправляющаяся с силами Плети.$B$BЯ слыхал, как профессор говорила что-то о каком-то "Хранителе Жизни", которого – или которую – титаны назначили приглядывать за Шолазаром. Я, конечно, не спец по истории титанов, но, судя по всему, она как раз подходит.$B$BЗнаю я и то, что если армия Плети перейдет границу между Затерянными землями и остальным Шолазаром, наша экспедиция, считай, мертва. Что скажешь – может, пойдешь поищешь ее и предложишь ей руку помощи?','Отправляйтесь на Увядшую поляну, расположенную между водопадами Гласа Дождя и Затерянными землями и найдите Аватару Фрейи.','Ты не принадлежишь этой земле. Но и Плети ты тоже не принадлежишь.$B$BЧто же мне делать с тобой?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сила природы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я не слишком уверен в том, что именно я видел, летя на северо-восток, но выглядело это как огромная женщина, легко расправляющаяся с силами Плети.$B$BЯ слыхал, как профессор говорила что-то о каком-то "Хранителе Жизни", которого – или которую – титаны назначили приглядывать за Шолазаром. Я, конечно, не спец по истории титанов, но, судя по всему, она как раз подходит.$B$BЗнаю я и то, что если армия Плети перейдет границу между Затерянными землями и остальным Шолазаром, наша экспедиция, считай, мертва. Что скажешь – может, пойдешь поищешь ее и предложишь ей руку помощи?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь на Увядшую поляну, расположенную между водопадами Гласа Дождя и Затерянными землями и найдите Аватару Фрейи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты не принадлежишь этой земле. Но и Плети ты тоже не принадлежишь.$B$BЧто же мне делать с тобой?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12804,'Стейк, достойный охотника','Иногда нет ничего хуже, чем целый лагерь охотников. Они все настолько заняты добычей, что не заботятся о еде, и все, что я получаю – жесткое и жилистое мясо... Навряд ли тебе хотелось бы получить такую пищу после целого дня, проведенного на охоте, верно?$B$BПо счастью, неподалеку отсюда можно добыть прекрасное мясо, нежное и сочное. К югу от лагеря, на том берегу реки обитают длинношеие травояды. Для наших голодных усталых охотников они стали бы отличной едой. Принеси мне лучшие куски мяса, и мы устроим нашим товарищам настоящий пир!','Принесите Коргу Тесаку в лагерь Эрнестуэя 5 стейков из длинношеего травояда.','Удалось тебе добыть мясо?','Вернитесь к Коргу Тесаку в Лагерь Эрнестуэя, что в Низине Шолазар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Стейк, достойный охотника',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Иногда нет ничего хуже, чем целый лагерь охотников. Они все настолько заняты добычей, что не заботятся о еде, и все, что я получаю – жесткое и жилистое мясо... Навряд ли тебе хотелось бы получить такую пищу после целого дня, проведенного на охоте, верно?$B$BПо счастью, неподалеку отсюда можно добыть прекрасное мясо, нежное и сочное. К югу от лагеря, на том берегу реки обитают длинношеие травояды. Для наших голодных усталых охотников они стали бы отличной едой. Принеси мне лучшие куски мяса, и мы устроим нашим товарищам настоящий пир!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Коргу Тесаку в лагерь Эрнестуэя 5 стейков из длинношеего травояда.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось тебе добыть мясо?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Коргу Тесаку в Лагерь Эрнестуэя, что в Низине Шолазар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12805,'Сохранение жизненной силы','Колонна жизненной силы обрушилась и спровоцировала подъем глубинных слоев грунта к поверхности.$B$BЭлементали, бродящие у одного из осколков колонны, носят в себе ту жизненную силу, что наполняла колонну энергией. Я не допущу, чтобы эта энергия пропала просто так, ведь осталось всего четыре колонны.$B$BОтправляйся к Одинокому осколку на юго-восток и поищи элементалей жизненной силы.$B$BИспользуй самоцвет жизненной силы на их останках, чтобы собрать пульсирующую в них энергию. Она нужна нам, чтобы залечить раны этой земли, когда испытания будут позади.','По просьбе Фрейи отправляйтесь к Одинокому осколку на юго-восток и примените самоцвет жизненной силы к 8 уничтоженным элементалям жизненной силы.','Ты $Gвосстановил:восстановила; энергию элементалей, $N?','Вернитесь к Аватаре Фрейи к водопадам Гласа Дождя, что в низине Шолазар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сохранение жизненной силы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Колонна жизненной силы обрушилась и спровоцировала подъем глубинных слоев грунта к поверхности.$B$BЭлементали, бродящие у одного из осколков колонны, носят в себе ту жизненную силу, что наполняла колонну энергией. Я не допущу, чтобы эта энергия пропала просто так, ведь осталось всего четыре колонны.$B$BОтправляйся к Одинокому осколку на юго-восток и поищи элементалей жизненной силы.$B$BИспользуй самоцвет жизненной силы на их останках, чтобы собрать пульсирующую в них энергию. Она нужна нам, чтобы залечить раны этой земли, когда испытания будут позади.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По просьбе Фрейи отправляйтесь к Одинокому осколку на юго-восток и примените самоцвет жизненной силы к 8 уничтоженным элементалям жизненной силы.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gвосстановил:восстановила; энергию элементалей, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аватаре Фрейи к водопадам Гласа Дождя, что в низине Шолазар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (12806,'На Уступ Смерти со всех ног!','Кто-то считает, что наша основная задача – это не война с Королем-личом, а полное уничтожение Алого Натиска. С моей точки зрения, это та еще глупость. Но кто я такой, чтобы судить о подобных делах?$B$BДалеко на юго-запад отсюда находится Уступ Смерти – большая скала, возвышающаяся над морем среди других скал. Там ты найдешь лорда-командира Арета, который лично командует уничтожением Натиска.$B$B<Барон прочищает горло.>$B$BСтупай к нему побыстрее. Он спрашивал о тебе лично.','Отправляйтесь к лорду-командиру Арету на Уступ Смерти, что в Ледяной Короне.','Ну, наконец-то! Барон Раздор, я вижу, не особо спешил отправить тебя ко мне.$B$BНадо было давно отрубить ему голову! Вернее, этот пустой котелок у него на плечах!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На Уступ Смерти со всех ног!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кто-то считает, что наша основная задача – это не война с Королем-личом, а полное уничтожение Алого Натиска. С моей точки зрения, это та еще глупость. Но кто я такой, чтобы судить о подобных делах?$B$BДалеко на юго-запад отсюда находится Уступ Смерти – большая скала, возвышающаяся над морем среди других скал. Там ты найдешь лорда-командира Арета, который лично командует уничтожением Натиска.$B$B<Барон прочищает горло.>$B$BСтупай к нему побыстрее. Он спрашивал о тебе лично.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь к лорду-командиру Арету на Уступ Смерти, что в Ледяной Короне.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну, наконец-то! Барон Раздор, я вижу, не особо спешил отправить тебя ко мне.$B$BНадо было давно отрубить ему голову! Вернее, этот пустой котелок у него на плечах!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (12807,'Немного истории...','Нам еще многое предстоит сделать, но сначала, я думаю, нужно вспомнить немного истории.$B$BУ нас, рыцарей смерти, в прошлом было много неприятностей с нашими Алыми друзьями, которые сейчас так неосмотрительно расположились со всеми удобствами в бухте под нами, на западе.$B$BКогда приготовишься выслушать мою историю, приходи, и я все расскажу.','Выслушайте рассказ лорда-командира Арета на Уступе Смерти.','История лорда-командира Арета выслушана.','Поговорите с лордом-командиром Аретом на Уступе Смерти, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Немного истории...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нам еще многое предстоит сделать, но сначала, я думаю, нужно вспомнить немного истории.$B$BУ нас, рыцарей смерти, в прошлом было много неприятностей с нашими Алыми друзьями, которые сейчас так неосмотрительно расположились со всеми удобствами в бухте под нами, на западе.$B$BКогда приготовишься выслушать мою историю, приходи, и я все расскажу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выслушайте рассказ лорда-командира Арета на Уступе Смерти.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','История лорда-командира Арета выслушана.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с лордом-командиром Аретом на Уступе Смерти, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (12808,'Вынужденный союз','$gОтважный:Отважная; $n, Король-лич выступил против всех нас, наслав чуму и проклятие на Орду и Альянс. Лишь объединив усилия, сможем мы выстоять против этого нашествия.$B$BПоэтому в Шаттрате, на Террасе Света, был заключен новый союз. Я прошу и твоей помощи в войне против Короля-лича. Отправляйся в новый лагерь Альянса на Террасе Света и поговори с епископом Лазарил.$B$BДоброго тебе пути, $n.','Поговорите с епископом Лазарил в новом лагере Альянса на Террасе Света в Шаттрате.','$GБрат:сестра; $R, я горжусь тем, что поддерживаю тебя в дни нужды. Благослови тебя и пусть умные глаза вашей расы помогут найти путь к нашему спасению...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вынужденный союз',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$gОтважный:Отважная; $n, Король-лич выступил против всех нас, наслав чуму и проклятие на Орду и Альянс. Лишь объединив усилия, сможем мы выстоять против этого нашествия.$B$BПоэтому в Шаттрате, на Террасе Света, был заключен новый союз. Я прошу и твоей помощи в войне против Короля-лича. Отправляйся в новый лагерь Альянса на Террасе Света и поговори с епископом Лазарил.$B$BДоброго тебе пути, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с епископом Лазарил в новом лагере Альянса на Террасе Света в Шаттрате.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','$GБрат:сестра; $R, я горжусь тем, что поддерживаю тебя в дни нужды. Благослови тебя и пусть умные глаза вашей расы помогут найти путь к нашему спасению...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12809,'Стальгорн','Наши молитвы услышаны! Сосредоточив Свет наару Шаттрата, воззвав к благословению просветленных, мы создали священные артефакты великой силы, которые послужат нам в войне против Короля-лича.$B$BВозьми эту святыню, $n. Охраняй ее как зеницу ока и доставь в Стальгорн в целости и сохранности. Главный механик Меггакрут будет счастлив пустить этот артефакт в дело.','Епископ Лазарил просит вас отнести заряженный Светом артефакт главному механику Меггакруту в Стальгорн.','Невообразимо безупречно! Это устройство накапливает световую энергию на уровнях, превосходящих любые известные источники! О, от возможных приложений у меня дрожат усы и скручиваются пальцы ног. Хо-хо! Гено-актуатор с анти-ночным фотодисперсным действием, который я мог бы построить, превратит сумерки в рассвет! Плеть не узнает, что их поразило. Мы уничтожим их всех одним движением рычага!','Привет, $N! Посмотри на себя! Я вижу, ты $Gвырос:выросла; ровно на одну целую семьдесят три микромилиметра с тех пор, как я в последний раз видел тебя. Я уверен, что воздух Запределья подействовал на тебя.','Вернитесь к главному механику Меггакруту в Город Механиков Стальгорна.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Стальгорн',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наши молитвы услышаны! Сосредоточив Свет наару Шаттрата, воззвав к благословению просветленных, мы создали священные артефакты великой силы, которые послужат нам в войне против Короля-лича.$B$BВозьми эту святыню, $n. Охраняй ее как зеницу ока и доставь в Стальгорн в целости и сохранности. Главный механик Меггакрут будет счастлив пустить этот артефакт в дело.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Епископ Лазарил просит вас отнести заряженный Светом артефакт главному механику Меггакруту в Стальгорн.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Невообразимо безупречно! Это устройство накапливает световую энергию на уровнях, превосходящих любые известные источники! О, от возможных приложений у меня дрожат усы и скручиваются пальцы ног. Хо-хо! Гено-актуатор с анти-ночным фотодисперсным действием, который я мог бы построить, превратит сумерки в рассвет! Плеть не узнает, что их поразило. Мы уничтожим их всех одним движением рычага!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Привет, $N! Посмотри на себя! Я вижу, ты $Gвырос:выросла; ровно на одну целую семьдесят три микромилиметра с тех пор, как я в последний раз видел тебя. Я уверен, что воздух Запределья подействовал на тебя.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к главному механику Меггакруту в Город Механиков Стальгорна.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12810,'Кровавая вода','Соберите кровь 10 прожорливых акул в бурдюк для крови и принесите его лорду-командиру Арету на Уступ Смерти.','Отлично сработано. Ты пока немного обсохни, а потом мы продолжим.','Это не гламурная работа, но это необходимо.$B$BТеперь почему мы разговариваем,прежде чем ты $Gзакончил:закончила;, $C?','Вернитесь к лорду-командиру Арету на Уступ Смерти, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кровавая вода',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите кровь 10 прожорливых акул в бурдюк для крови и принесите его лорду-командиру Арету на Уступ Смерти.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично сработано. Ты пока немного обсохни, а потом мы продолжим.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Это не гламурная работа, но это необходимо.$B$BТеперь почему мы разговариваем,прежде чем ты $Gзакончил:закончила;, $C?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лорду-командиру Арету на Уступ Смерти, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (12811,'Отчаянный поиск','Настал час, $n, когда Король-лич решил перейти в наступление. У нас есть лишь один шанс оттеснить его назад к его ледяному трону, и для этого Орда и Альянс должны встать плечом к плечу. Ради этого в Шаттрате, на Террасе Света, был заключен новый союз.$B$BВ этой битве против Короля-лича нам понадобится любая помощь. Отправляйся в новый аптекарский лагерь в Террасе Света и разыщи верховного аптекаря Гнилесса. Он возглавляет исследования по поиску вакцины против новой чумы, и лишь на него возложены все наши надежды.$B$BПоторопись, $n, ибо каждая секунда промедления может стоить нам еще одной унесенной жизни.','Поговорите с верховным аптекарем Гнилессом в новом аптекарском лагере на Террасе Света в Шаттрате.','Какой ты прекрасный, крепкий образец. Нам предстоит провести много экспериментов, и наша конюшня волонтеров почти разорена. Свежая кровь действительно приветствуется, и ярость в твоей крови может подпитывать часы исследований.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отчаянный поиск',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Настал час, $n, когда Король-лич решил перейти в наступление. У нас есть лишь один шанс оттеснить его назад к его ледяному трону, и для этого Орда и Альянс должны встать плечом к плечу. Ради этого в Шаттрате, на Террасе Света, был заключен новый союз.$B$BВ этой битве против Короля-лича нам понадобится любая помощь. Отправляйся в новый аптекарский лагерь в Террасе Света и разыщи верховного аптекаря Гнилесса. Он возглавляет исследования по поиску вакцины против новой чумы, и лишь на него возложены все наши надежды.$B$BПоторопись, $n, ибо каждая секунда промедления может стоить нам еще одной унесенной жизни.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с верховным аптекарем Гнилессом в новом аптекарском лагере на Террасе Света в Шаттрате.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Какой ты прекрасный, крепкий образец. Нам предстоит провести много экспериментов, и наша конюшня волонтеров почти разорена. Свежая кровь действительно приветствуется, и ярость в твоей крови может подпитывать часы исследований.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12812,'Оргриммар','Мы сделали великое открытие! Благодаря подопытным зомби мы вывели исследование природы чумы на совершенно новый уровень, и наш труд наконец-то дал первые, восхитительно червивые плоды!$B$BОтнеси этот ящик в Оргриммар. Внутри его находится голова, зараженная трупной чумой, и кое-что еще – первый образец нашей античумы. Две этих заразы схлестнутся в мозгу зомби, и результат этого скрещения даст нам ключ к изобретению вакцины.$B$BОтдай ящик моему помощнику, аптекарю Карлову. Ты найдешь его в доме вождя Тралла в Оргриммаре.','Верховный аптекарь Гнилесс просит вас отнести разрываемый на части мозг аптекарю Карлову в Оргриммар.','Ах, очень хорошо. Болезни, которые несет эта сгнившая голова, смертельны, но мы не должны избегать опасности или того, что нам неприятно. Когда-нибудь, $N, ты узнаешь, что проклятие - это путь к спасению…','Приветствую, $N. Ты из Шаттрата? У тебя есть инструкции от великого аптекаря Гнилесса?','Вернитесь к аптекарю Карлову в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оргриммар',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы сделали великое открытие! Благодаря подопытным зомби мы вывели исследование природы чумы на совершенно новый уровень, и наш труд наконец-то дал первые, восхитительно червивые плоды!$B$BОтнеси этот ящик в Оргриммар. Внутри его находится голова, зараженная трупной чумой, и кое-что еще – первый образец нашей античумы. Две этих заразы схлестнутся в мозгу зомби, и результат этого скрещения даст нам ключ к изобретению вакцины.$B$BОтдай ящик моему помощнику, аптекарю Карлову. Ты найдешь его в доме вождя Тралла в Оргриммаре.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верховный аптекарь Гнилесс просит вас отнести разрываемый на части мозг аптекарю Карлову в Оргриммар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ах, очень хорошо. Болезни, которые несет эта сгнившая голова, смертельны, но мы не должны избегать опасности или того, что нам неприятно. Когда-нибудь, $N, ты узнаешь, что проклятие - это путь к спасению…',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Приветствую, $N. Ты из Шаттрата? У тебя есть инструкции от великого аптекаря Гнилесса?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к аптекарю Карлову в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12813,'Из праха восстаньте!','Какой он добрый... какой благородный... наш лорд-командир. Весь такой солнечный, ясный, как летний день, а в моем сердце – лишь черная ненависть.$B$BМне мало просто лишить их жизни... я хочу их унизить... смешать их с грязью!$B$BЧто может быть хуже и гаже, чем быть превращенным в то, что тебе ненавистно?! Посвятить всю свою жизнь искоренению скверны, а под конец в нее же и превратиться!$B$BЭто печально и страшно.$B$BОтнеси эту настойку на запад, в бухту Алого Натиска. Окропи ею тела мертвых и посмотри, что будет. Только не суйся в собор.','Возьмите настойку Темной Целительницы, которую дала вам Сетаал Темная Целительница на Уступе Смерти, и окропите тела любых 10 бойцов Алого Натиска, которых найдете.','Неужели ты ещё не $Gзакончил:закончила;','Вернитесь к Сетаал Темной Целительнице на Уступ Смерти, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Из праха восстаньте!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Какой он добрый... какой благородный... наш лорд-командир. Весь такой солнечный, ясный, как летний день, а в моем сердце – лишь черная ненависть.$B$BМне мало просто лишить их жизни... я хочу их унизить... смешать их с грязью!$B$BЧто может быть хуже и гаже, чем быть превращенным в то, что тебе ненавистно?! Посвятить всю свою жизнь искоренению скверны, а под конец в нее же и превратиться!$B$BЭто печально и страшно.$B$BОтнеси эту настойку на запад, в бухту Алого Натиска. Окропи ею тела мертвых и посмотри, что будет. Только не суйся в собор.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возьмите настойку Темной Целительницы, которую дала вам Сетаал Темная Целительница на Уступе Смерти, и окропите тела любых 10 бойцов Алого Натиска, которых найдете.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Неужели ты ещё не $Gзакончил:закончила;',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сетаал Темной Целительнице на Уступ Смерти, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12814,'Потребность в грифоне','А что, это было бы здорово: забрать у них одного из грифонов и использовать против них же! Отправляйся в бухту Алого Натиска и добудь одного грифона. Скажем так, вырви поводья из мертвых рук его всадника.$B$BКогда вернешься сюда, отведи грифона к Узо Призывателю Смерти. Он позаботится о его надлежащей трансформации и даст тебе дальнейшие указания.','Отведите грифона Алого Натиска к Узо Призывателю Смерти на Уступ Смерти.','Что так долго? Где грифон?','Вернитесь к Узо Призывателю Смерти на Уступ Смерти, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Потребность в грифоне',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А что, это было бы здорово: забрать у них одного из грифонов и использовать против них же! Отправляйся в бухту Алого Натиска и добудь одного грифона. Скажем так, вырви поводья из мертвых рук его всадника.$B$BКогда вернешься сюда, отведи грифона к Узо Призывателю Смерти. Он позаботится о его надлежащей трансформации и даст тебе дальнейшие указания.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отведите грифона Алого Натиска к Узо Призывателю Смерти на Уступ Смерти.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что так долго? Где грифон?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Узо Призывателю Смерти на Уступ Смерти, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12815,'Закрытое воздушное пространство','Теперь, когда у тебя есть свой костяной грифон, ты будешь летать туда каждый день. Очисти небо над бухтой Алого Натиска.$B$BСкажу тебе прямо: мне все равно, как ты это сделаешь. Но сдается мне, если ты избавишь нас от общества наездников, то тебе будет проще, гораздо проще.$B$BК тому же, твой костяной грифон, он, знаешь ли, много чего умеет. И эти умения тебе пригодятся.','Что-то ты быстро $Gвернулся:вернулась;. Я знаю, что все еще вижу, как из Натиска все еще летают там!','Вернитесь к Узо Призывателю Смерти на Уступ Смерти, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Закрытое воздушное пространство',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда у тебя есть свой костяной грифон, ты будешь летать туда каждый день. Очисти небо над бухтой Алого Натиска.$B$BСкажу тебе прямо: мне все равно, как ты это сделаешь. Но сдается мне, если ты избавишь нас от общества наездников, то тебе будет проще, гораздо проще.$B$BК тому же, твой костяной грифон, он, знаешь ли, много чего умеет. И эти умения тебе пригодятся.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что-то ты быстро $Gвернулся:вернулась;. Я знаю, что все еще вижу, как из Натиска все еще летают там!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Узо Призывателю Смерти на Уступ Смерти, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (12816,'Нападение Плети на Луносвет','Армия нежити Короля-лича уже стоит у наших ворот. Мы не должны оставаться в стороне! Долг каждого солдата – защищать Луносвет от проклятых захватчиков до последней капли крови!$b $bВидишь эти странные рунические круги вокруг лагеря? Они пропитаны той же энергией, что окружает нежить и Некрополь. Ты $gдолжен:должна; выяснить, что они обозначают. Подойди к ним поближе, очисть местность от мерзких созданий Плети и приступай к исследованиям. И не забудь – я достойно вознагражу тебя за результаты, равно как и за доказательства твоей победы над Плетью. Иди же, не медли!','Соберите три тусклых Некротических камня Плети, которые носит при себе нежить, откружившая Луносвет, и исследуйте светящиеся рунические круги вблизи лагеря Плети.','Хм. Судя по тому, что ты мне $Gсказал:сказала;, голоса в кругах ... они,наверно, используються для какого-то рода общения. Я вздрагиваюсь при мысли о том, с какими неестественными умами контактирует такая магия. Как бы то ни было, ты кажешься здоровым. Серебряный Рассвет ценит твою службу.','Ты уже $Gрасследовал:расследовала; вторжение? Нет времени бездельничать!','Осмотреть круг','Вернитесь к лейтенанту Джулеку в Леса Вечной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нападение Плети на Луносвет',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Армия нежити Короля-лича уже стоит у наших ворот. Мы не должны оставаться в стороне! Долг каждого солдата – защищать Луносвет от проклятых захватчиков до последней капли крови!$b $bВидишь эти странные рунические круги вокруг лагеря? Они пропитаны той же энергией, что окружает нежить и Некрополь. Ты $gдолжен:должна; выяснить, что они обозначают. Подойди к ним поближе, очисть местность от мерзких созданий Плети и приступай к исследованиям. И не забудь – я достойно вознагражу тебя за результаты, равно как и за доказательства твоей победы над Плетью. Иди же, не медли!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите три тусклых Некротических камня Плети, которые носит при себе нежить, откружившая Луносвет, и исследуйте светящиеся рунические круги вблизи лагеря Плети.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хм. Судя по тому, что ты мне $Gсказал:сказала;, голоса в кругах ... они,наверно, используються для какого-то рода общения. Я вздрагиваюсь при мысли о том, с какими неестественными умами контактирует такая магия. Как бы то ни было, ты кажешься здоровым. Серебряный Рассвет ценит твою службу.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты уже $Gрасследовал:расследовала; вторжение? Нет времени бездельничать!',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Осмотреть круг',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лейтенанту Джулеку в Леса Вечной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (12817,'Нападение Плети на Экзодар','Армия нежити Короля-лича уже стоит у наших ворот. Мы не должны оставаться в стороне! Долг каждого солдата – защищать Экзодар от проклятых захватчиков до последней капли крови!$b $bВидишь эти странные рунические круги вокруг лагеря? Они пропитаны той же энергией, что окружает нежить и Некрополь. Ты $gдолжен:должна; выяснить, что они обозначают. Подойди к ним поближе, очисть местность от мерзких созданий Плети и приступай к исследованиям. И не забудь – я достойно вознагражу тебя за результаты, равно как и за доказательства твоей победы над Плетью. Иди же, не медли!','Соберите три тусклых некротических камня созданий Плети, бродящих вокруг Экзодара, и изучите светящиеся рунические круги вокруг лагеря, после чего вернитесь к лейтенанту Крегору.','Хм. Судя по тому, что ты мне $Gсказал:сказала;, голоса в кругах ... они,наверно, используються для какого-то рода общения. Я вздрагиваюсь при мысли о том, с какими неестественными умами контактирует такая магия. Как бы то ни было, ты кажешься здоровым. Серебряный Рассвет ценит твою службу.','Ты уже $Gрасследовал:расследовала; вторжение? Нет времени бездельничать!','Осмотреть круг','Вернитесь к лейтенанту Крегору в Экзодар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нападение Плети на Экзодар',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Армия нежити Короля-лича уже стоит у наших ворот. Мы не должны оставаться в стороне! Долг каждого солдата – защищать Экзодар от проклятых захватчиков до последней капли крови!$b $bВидишь эти странные рунические круги вокруг лагеря? Они пропитаны той же энергией, что окружает нежить и Некрополь. Ты $gдолжен:должна; выяснить, что они обозначают. Подойди к ним поближе, очисть местность от мерзких созданий Плети и приступай к исследованиям. И не забудь – я достойно вознагражу тебя за результаты, равно как и за доказательства твоей победы над Плетью. Иди же, не медли!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите три тусклых некротических камня созданий Плети, бродящих вокруг Экзодара, и изучите светящиеся рунические круги вокруг лагеря, после чего вернитесь к лейтенанту Крегору.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хм. Судя по тому, что ты мне $Gсказал:сказала;, голоса в кругах ... они,наверно, используються для какого-то рода общения. Я вздрагиваюсь при мысли о том, с какими неестественными умами контактирует такая магия. Как бы то ни было, ты кажешься здоровым. Серебряный Рассвет ценит твою службу.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты уже $Gрасследовал:расследовала; вторжение? Нет времени бездельничать!',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Осмотреть круг',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лейтенанту Крегору в Экзодар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (12818,'Сбор деталей','Принесите Глуму Свечекруту в К-3 10 деталей из обугленных обломков.','Вернитесь к Глуму Свечекруту в К-3, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сбор деталей',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Глуму Свечекруту в К-3 10 деталей из обугленных обломков.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Глуму Свечекруту в К-3, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (12819,'Плевое дело','Вот черт! Где мои инструменты? Они же вот только что были здесь.$B$BО! Наверное, я их забыл на минном поле к западу отсюда. М-да, приятного мало... Слушай, я буду очень тебе благодарен, если ты их заберешь. Только ты там осторожнее! Смотри под ноги! Там везде мины. Тебе нужно будет пройти в точности там же, где проходил я.$B$BДа, и еще одно... не пытайся добраться туда по воздуху. Не знаю, что на меня нашло, но я установил пушки, которые палят по всему, что летает. И они, как ты понимаешь, не разбираются, кто там летит и зачем.','По поручению Глума Свечекрута из К-3 принесите инструменты Свечекрута с минного поля.','Ха-ха! Да, это они! Большое спасибо. Надеюсь, ты там не сильно упарился, пробираясь по минному полю.','Вернитесь к Глуму Свечекруту в К-3, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Плевое дело',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот черт! Где мои инструменты? Они же вот только что были здесь.$B$BО! Наверное, я их забыл на минном поле к западу отсюда. М-да, приятного мало... Слушай, я буду очень тебе благодарен, если ты их заберешь. Только ты там осторожнее! Смотри под ноги! Там везде мины. Тебе нужно будет пройти в точности там же, где проходил я.$B$BДа, и еще одно... не пытайся добраться туда по воздуху. Не знаю, что на меня нашло, но я установил пушки, которые палят по всему, что летает. И они, как ты понимаешь, не разбираются, кто там летит и зачем.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По поручению Глума Свечекрута из К-3 принесите инструменты Свечекрута с минного поля.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ха-ха! Да, это они! Большое спасибо. Надеюсь, ты там не сильно упарился, пробираясь по минному полю.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Глуму Свечекруту в К-3, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12820,'Осторожное прикосновение','Я целую вечность ждала эти мины! Ну, как минимум, несколько дней. Чего он так долго?!$B$BТут, понимаешь, какое дело... тут поблизости бродит свирепая банда магнатавров – ну, знаешь, такие... огромные, волосатые, страшные, как смертный грех, и, похоже, они собираются захватить К-3!$B$BТолько у них ничего не получится.$B$BМы построили несколько защитных сооружений на северо-востоке отсюда. Но вот незадача: у наших лазерных пушек очень слабые источники питания. Вот тут-то нам и пригодятся мины! Отправляйся туда и задай жару этим уродам!','Не слышу взрывов.','Вернитесь к Рикет в К-3, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Осторожное прикосновение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я целую вечность ждала эти мины! Ну, как минимум, несколько дней. Чего он так долго?!$B$BТут, понимаешь, какое дело... тут поблизости бродит свирепая банда магнатавров – ну, знаешь, такие... огромные, волосатые, страшные, как смертный грех, и, похоже, они собираются захватить К-3!$B$BТолько у них ничего не получится.$B$BМы построили несколько защитных сооружений на северо-востоке отсюда. Но вот незадача: у наших лазерных пушек очень слабые источники питания. Вот тут-то нам и пригодятся мины! Отправляйся туда и задай жару этим уродам!',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Не слышу взрывов.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Рикет в К-3, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`objectives_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (12821,'По поручению Рикет из К-3 разыщите батарею для телепортера и с ее помощью активируйте площадку телепортера у Подъема Гарма.','Даже магнатавру должно быть понятно, что с гоблинами лучше не связываться.','Телепортер Гарма активирован','Вернитесь к Рикет в К-3, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По поручению Рикет из К-3 разыщите батарею для телепортера и с ее помощью активируйте площадку телепортера у Подъема Гарма.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Даже магнатавру должно быть понятно, что с гоблинами лучше не связываться.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Телепортер Гарма активирован',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Рикет в К-3, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12822,'Средство для устрашения','Теперь, когда у нас открыт телепорт, мой план усложнился... его воплощение потребует безукоризненной точности во всем. И нам еще надо собрать провиант! И набрать новых солдат! Работы явно не на одну неделю!$B$BВ общем так, $gмалыш:девочка;, проходи через телепорт и задай жару этим уродам! Наши саперы тебя прикроют... им все равно будет некуда отступать.','По заданию Рикет из К-3 убейте 6 дозорных Гарма и 8 приверженцев с Холмов Снежной Слепоты.','Ха-ха! Теперь эти скоты будут знать, как отнимать у нас время! Отныне и впредь зеленая кожа будет наводить страх и ужас на всех магнатавров!','Где еда? Гости прибудут с минуты на минуту!','Вернитесь к Рикет в К-3, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Средство для устрашения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда у нас открыт телепорт, мой план усложнился... его воплощение потребует безукоризненной точности во всем. И нам еще надо собрать провиант! И набрать новых солдат! Работы явно не на одну неделю!$B$BВ общем так, $gмалыш:девочка;, проходи через телепорт и задай жару этим уродам! Наши саперы тебя прикроют... им все равно будет некуда отступать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По заданию Рикет из К-3 убейте 6 дозорных Гарма и 8 приверженцев с Холмов Снежной Слепоты.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ха-ха! Теперь эти скоты будут знать, как отнимать у нас время! Отныне и впредь зеленая кожа будет наводить страх и ужас на всех магнатавров!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Где еда? Гости прибудут с минуты на минуту!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Рикет в К-3, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (12823,'Безупречный план','Ну, здравствуй! Как я понимаю, ты хочешь присоединиться к нашему отряду?$B$BУ меня для тебя есть задание... мы собираемся обрушить на них всю пещеру! В самом дальнем конце пещеры располагается алтарь Хладонутра. Тебе нужно к нему подобраться и положить где-нибудь рядом этот надежно перевязанный сверток со взрывчаткой.$B$BКогда положишь заряд, убедись, что Хладонутр его схватил, а потом сразу беги на выход! Неизвестно, сколько продержатся своды пещеры, когда оно там рванет!','Джино у Подъема Гарма просит вас положить надежно перевязанный сверток со взрывчаткой у алтаря Хладонутра, убить Тормара Хладонутра и выбраться из пещеры до того, как она обрушится.','Вернитесь к Джино на Подъем Гарма, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Безупречный план',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну, здравствуй! Как я понимаю, ты хочешь присоединиться к нашему отряду?$B$BУ меня для тебя есть задание... мы собираемся обрушить на них всю пещеру! В самом дальнем конце пещеры располагается алтарь Хладонутра. Тебе нужно к нему подобраться и положить где-нибудь рядом этот надежно перевязанный сверток со взрывчаткой.$B$BКогда положишь заряд, убедись, что Хладонутр его схватил, а потом сразу беги на выход! Неизвестно, сколько продержатся своды пещеры, когда оно там рванет!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Джино у Подъема Гарма просит вас положить надежно перевязанный сверток со взрывчаткой у алтаря Хладонутра, убить Тормара Хладонутра и выбраться из пещеры до того, как она обрушится.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джино на Подъем Гарма, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (12824,'Выдающийся подрывник','А ты быстро бегаешь, $gприятель:подруга;! Спасибо за помощь со взрывами... Я давно ждал возможности испытать свои изобретения в деле!$B$BИди скажи Рикет, что теперь магнатавров опасаться не приходится: мои саперы этих гадов повычистят!$B$BИ еще раз спасибо!','Возвращайтесь к Рикет в К-3.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Выдающийся подрывник',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А ты быстро бегаешь, $gприятель:подруга;! Спасибо за помощь со взрывами... Я давно ждал возможности испытать свои изобретения в деле!$B$BИди скажи Рикет, что теперь магнатавров опасаться не приходится: мои саперы этих гадов повычистят!$B$BИ еще раз спасибо!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возвращайтесь к Рикет в К-3.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (12825,'Выражение благодарности','[PLACEHOLDER] Используйте мини-самолет с камикадзе на вождя гноллов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Выражение благодарности',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','[PLACEHOLDER] Используйте мини-самолет с камикадзе на вождя гноллов.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12826,'Почти безопасны','Красота!$B$BНет, не ты, а мои новые мины. Я – гений, да! Истинный гений. Ничто не сравнится с моим интеллектом.$B$BТак о чем мы с тобой говорили? А, да! О моих новых минах! Новая, усовершенствованная модель... готовая к испытанию в деле. Рикет будет довольна.$B$BСлушай, будь $gхорошим мальчиком:хорошей девочкой;, отнеси эти мины Рикет, хорошо? Это будет поистине эпическое путешествие... Только ты с ней осторожнее. Она, конечно, хорошая, но малость с приветом.','Отнесите усовершенствованные противопехотные мины Глума Рикет в К-3.','Симпатичные взрывные устройства. Правда, они милые?','Глум доделал свои мины? Отлично.','Вернитесь к Рикет в К-3, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Почти безопасны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Красота!$B$BНет, не ты, а мои новые мины. Я – гений, да! Истинный гений. Ничто не сравнится с моим интеллектом.$B$BТак о чем мы с тобой говорили? А, да! О моих новых минах! Новая, усовершенствованная модель... готовая к испытанию в деле. Рикет будет довольна.$B$BСлушай, будь $gхорошим мальчиком:хорошей девочкой;, отнеси эти мины Рикет, хорошо? Это будет поистине эпическое путешествие... Только ты с ней осторожнее. Она, конечно, хорошая, но малость с приветом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите усовершенствованные противопехотные мины Глума Рикет в К-3.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Симпатичные взрывные устройства. Правда, они милые?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Глум доделал свои мины? Отлично.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Рикет в К-3, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12827,'Пополнение запасов провизии','Эй, ты! Ты что, $gновенький:новенькая;? Не хочешь помочь Рикет?$B$BУ нас тут возникла одна неожиданная проблема... нехватка продовольствия. Да, я все понимаю... о пополнении запасов надо заботиться заранее, но тут, понимаешь, какое дело... Мы с нашей саперной командой как-то вот не рассчитывали застрять здесь надолго. Да и народу у нас прибавляется постоянно. Похоже, старый добрый К-3 становится весьма популярным местом.$B$BКак решить эту проблему? К западу отсюда есть несколько лагерей гноллов... так вот, у них с продовольствием все в порядке. Не возьмешься стащить у них провиант?','По заданию Рикет из К-3 стащите 16 сухих пайков гноллов из ближайшего лагеря свирепых гноллов холмов.','Надеюсь, они не очень на нас обидятся. Мы же не обижаемся, когда они роются в нашем мусоре.','Ну что, как успехи? А то у меня уже в животе урчит...','Вернитесь к Рикет в К-3, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пополнение запасов провизии',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эй, ты! Ты что, $gновенький:новенькая;? Не хочешь помочь Рикет?$B$BУ нас тут возникла одна неожиданная проблема... нехватка продовольствия. Да, я все понимаю... о пополнении запасов надо заботиться заранее, но тут, понимаешь, какое дело... Мы с нашей саперной командой как-то вот не рассчитывали застрять здесь надолго. Да и народу у нас прибавляется постоянно. Похоже, старый добрый К-3 становится весьма популярным местом.$B$BКак решить эту проблему? К западу отсюда есть несколько лагерей гноллов... так вот, у них с продовольствием все в порядке. Не возьмешься стащить у них провиант?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По заданию Рикет из К-3 стащите 16 сухих пайков гноллов из ближайшего лагеря свирепых гноллов холмов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Надеюсь, они не очень на нас обидятся. Мы же не обижаемся, когда они роются в нашем мусоре.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, как успехи? А то у меня уже в животе урчит...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Рикет в К-3, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (12828,'Полет вдохновения','Фу! Ну и гадость! Может, для гноллов оно и вкусное, но нашим нужно что-нибудь более... съедобное.$B$BЛадно, попробуем подойти творчески...$B$BТора установила взрывной распределитель к северу от города... это неподалеку от входа в большую пещеру, ты его сразу увидишь. Эти штуки, как я понимаю, нужны для каких-то горнодобывающих работ, но у меня есть идея! Возьми бомбу из распределителя и грохни мамонта. Они обитают на западе. Возьми мясо и принеси его нам.','По просьбе Рикет из К-3 возьмите УРВР, убейте мамонта и принесите в К-3 8 больших кусков мяса мамонта.','Вернитесь к Рикет в К-3, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Полет вдохновения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Фу! Ну и гадость! Может, для гноллов оно и вкусное, но нашим нужно что-нибудь более... съедобное.$B$BЛадно, попробуем подойти творчески...$B$BТора установила взрывной распределитель к северу от города... это неподалеку от входа в большую пещеру, ты его сразу увидишь. Эти штуки, как я понимаю, нужны для каких-то горнодобывающих работ, но у меня есть идея! Возьми бомбу из распределителя и грохни мамонта. Они обитают на западе. Возьми мясо и принеси его нам.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По просьбе Рикет из К-3 возьмите УРВР, убейте мамонта и принесите в К-3 8 больших кусков мяса мамонта.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Рикет в К-3, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12829,'Перед тем, как входить','Привет! Меня зовут Тора. Я возглавляю горные работы здесь, на К-3... ну, или буду возглавлять в ближайшее время!$B$BЭта пещера так и кишит всякими ползучими гадами. Думаю, нам бы надо избавиться от пауков перед тем, как туда вселяться... А ты как считаешь?','По заданию Торы Громыхалы у пещеры Хрустальной Паутины убейте 12 пауков в этой пещере.','Будь $Gосторожен:осторожна; возле дозатора! Эти вещи опасны.','Вернитесь к Торе Громыхале в Пещеру Хрустальной Паутины, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Перед тем, как входить',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Привет! Меня зовут Тора. Я возглавляю горные работы здесь, на К-3... ну, или буду возглавлять в ближайшее время!$B$BЭта пещера так и кишит всякими ползучими гадами. Думаю, нам бы надо избавиться от пауков перед тем, как туда вселяться... А ты как считаешь?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По заданию Торы Громыхалы у пещеры Хрустальной Паутины убейте 12 пауков в этой пещере.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Будь $Gосторожен:осторожна; возле дозатора! Эти вещи опасны.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Торе Громыхале в Пещеру Хрустальной Паутины, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (12830,'Изъятие руды','Мы идем дальше!$B$BКогда мы только пришли, здесь было несколько снобольдов... но их шахтерские работы, похоже, шли не особенно успешно. Несчастные случаи, травмы на производстве... Так что мы быстро отбили шахту.$B$BЯ послала туда нескольких рудокопов, чтобы они принесли мне образцы руды, которые можно использовать для точной настройки наших машин, но они до сих пор не вернулись.$B$BМожет быть, сходишь туда и принесешь мне образцы руды? Наверняка они есть у снобольдов, хотя я очень надеюсь, что большинство из них мы перебили.','По просьбе Тор Громыхалы у пещеры Хрустальной Паутины соберите 5 образцов нечистой саронитовой руды.','Вернитесь к Торе Громыхале в Пещеру Хрустальной Паутины, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Изъятие руды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы идем дальше!$B$BКогда мы только пришли, здесь было несколько снобольдов... но их шахтерские работы, похоже, шли не особенно успешно. Несчастные случаи, травмы на производстве... Так что мы быстро отбили шахту.$B$BЯ послала туда нескольких рудокопов, чтобы они принесли мне образцы руды, которые можно использовать для точной настройки наших машин, но они до сих пор не вернулись.$B$BМожет быть, сходишь туда и принесешь мне образцы руды? Наверняка они есть у снобольдов, хотя я очень надеюсь, что большинство из них мы перебили.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По просьбе Тор Громыхалы у пещеры Хрустальной Паутины соберите 5 образцов нечистой саронитовой руды.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Торе Громыхале в Пещеру Хрустальной Паутины, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12831,'Ядовитый укус','Ой... у меня все внутренности раздирает так, будто там в животе – пропеллер.$B$BИдти я, наверное, смогу, но после того, как меня укусила та пакость в глубине пещеры, мне как-то нехорошо... Эта тварь была больше других пауков... и с яркой раскраской.$B$BРикет, может быть, и сумеет приготовить противоядие, но для этого ей понадобится ядовитая железа той твари, которая меня укусила. Может, найдешь эту пакость?$B$BА я пока поиграю с пауками в мертвого гоблина и, будем надеяться, они оставят меня в покое.','Принесите раненому гоблину-рудокопу в пещере Хрустальной Паутины ядовитую железу ледяного ползуна.','Вот спасибо... Надеюсь, Рикет сможет сделать мне противоядие. А теперь уходим отсюда! Скорее!','<Раненый гоблин-рудокоп корчится от боли.>','Вернитесь к раненому гоблину-рудокопу в Пещеру Хрустальной Паутины, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ядовитый укус',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ой... у меня все внутренности раздирает так, будто там в животе – пропеллер.$B$BИдти я, наверное, смогу, но после того, как меня укусила та пакость в глубине пещеры, мне как-то нехорошо... Эта тварь была больше других пауков... и с яркой раскраской.$B$BРикет, может быть, и сумеет приготовить противоядие, но для этого ей понадобится ядовитая железа той твари, которая меня укусила. Может, найдешь эту пакость?$B$BА я пока поиграю с пауками в мертвого гоблина и, будем надеяться, они оставят меня в покое.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите раненому гоблину-рудокопу в пещере Хрустальной Паутины ядовитую железу ледяного ползуна.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот спасибо... Надеюсь, Рикет сможет сделать мне противоядие. А теперь уходим отсюда! Скорее!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Раненый гоблин-рудокоп корчится от боли.>',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к раненому гоблину-рудокопу в Пещеру Хрустальной Паутины, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`endtext_loc8`) VALUES (12832,'Побег','Вот спасибо! А мне уже стало страшно, что пойду на закуску какому-нибудь пауку. Впрочем, что это я болтаю? Надо скорее смываться из этого мрачного места!$B$BКогда будешь $gготов:готова; идти, сразу свисти... и пойдем уже, а?','Проводите раненого гоблина-рудокопа из пещеры Хрустальной Паутины в К-3, а потом поговорите с Рикет.','Я так считаю, что в пещере все прошло хорошо?','Проводите раненого гоблина-рудокопа в К-3.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Побег',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот спасибо! А мне уже стало страшно, что пойду на закуску какому-нибудь пауку. Впрочем, что это я болтаю? Надо скорее смываться из этого мрачного места!$B$BКогда будешь $gготов:готова; идти, сразу свисти... и пойдем уже, а?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проводите раненого гоблина-рудокопа из пещеры Хрустальной Паутины в К-3, а потом поговорите с Рикет.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я так считаю, что в пещере все прошло хорошо?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Проводите раненого гоблина-рудокопа в К-3.',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12833,'Излишки','Привет еще раз! Что, не захотелось сбежать, как это сделали все остальные? Ну, так ты просто лапочка, да? Я уж начала было думать, что от меня дурно пахнет или еще что!$B$BНам не помешала бы еще кое-какая помощь, а у тебя как раз есть необходимый опыт. Помнишь тех магнатавров? Ну, тут такое дело – пещера-то не полностью обвалилась... кое-кто там все-таки остался. И для Джино этих "кое-кого" многовато, понимаешь?$B$BК счастью, Глум мин наделал – мало не покажется. Ну, ты же понимаешь?..','Бум! Ха-ха!','Вернитесь к Рикет в К-3, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Излишки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Привет еще раз! Что, не захотелось сбежать, как это сделали все остальные? Ну, так ты просто лапочка, да? Я уж начала было думать, что от меня дурно пахнет или еще что!$B$BНам не помешала бы еще кое-какая помощь, а у тебя как раз есть необходимый опыт. Помнишь тех магнатавров? Ну, тут такое дело – пещера-то не полностью обвалилась... кое-кто там все-таки остался. И для Джино этих "кое-кого" многовато, понимаешь?$B$BК счастью, Глум мин наделал – мало не покажется. Ну, ты же понимаешь?..',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Бум! Ха-ха!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Рикет в К-3, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (12834,'Ни дождь, ни снег, ни катастрофа','[PLACEHOLDER] Испытайте всепогодный бомбардировщик на великане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ни дождь, ни снег, ни катастрофа',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','[PLACEHOLDER] Испытайте всепогодный бомбардировщик на великане.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (12835,'Все взрослые','[PLACEHOLDER] Испытайте взрослого йормунгара на великане.','Вернитесь к ...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Все взрослые',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','[PLACEHOLDER] Испытайте взрослого йормунгара на великане.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ...',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12836,'Выражение благодарности','Я знаю работку как раз для ретивого новичка! У нас тут проблема с гноллами возникла... можно сказать, все вокруг просто кишит этими мерзкими тварями. Их все больше и больше, теперь они уже вообще у нас на пороге, таскают наши запчасти! Просто ужас.$B$BВсем от начала и до конца заправляет их самонадеянный вожак, Кривошерст. Вот, кстати, насчет "конца"... нанеси-ка ему визит в лагерь – далеко на западе, в холмах Снежной Слепоты.$B$BИ когда я говорю "нанеси ему визит" – я говорю это вместо "жестоко убей его". Дошло? Вперед!','По заданию Рикет из К-3 убейте Кривошерста.','Ну что, как успехи? А то у меня уже в животе урчит...','Вернитесь к Рикет в К-3, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Выражение благодарности',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я знаю работку как раз для ретивого новичка! У нас тут проблема с гноллами возникла... можно сказать, все вокруг просто кишит этими мерзкими тварями. Их все больше и больше, теперь они уже вообще у нас на пороге, таскают наши запчасти! Просто ужас.$B$BВсем от начала и до конца заправляет их самонадеянный вожак, Кривошерст. Вот, кстати, насчет "конца"... нанеси-ка ему визит в лагерь – далеко на западе, в холмах Снежной Слепоты.$B$BИ когда я говорю "нанеси ему визит" – я говорю это вместо "жестоко убей его". Дошло? Вперед!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По заданию Рикет из К-3 убейте Кривошерста.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, как успехи? А то у меня уже в животе урчит...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Рикет в К-3, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (12837,'У Тор есть все, что надо','[PLACEHOLDER] Явиться к Тор.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','У Тор есть все, что надо',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','[PLACEHOLDER] Явиться к Тор.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (12838,'Сбор информации','Мне нужно знать, что затевает Алый Натиск. И ты мне в этом поможешь.$B$BЛети в бухту Алого Натиска и обыщи их багажные сундуки. Ищи бумаги и документы. Сундуки будут заперты, так что тебе надо будет добыть ключи у бойцов Алого Натиска. Добыть любой ценой!','Соберите 5 донесений разведки Алого Натиска по заданию Аурока Мрачного Проклятия с Уступа Смерти.','Вернитесь к Аурку Мрачному Проклятию на Уступ Смерти, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сбор информации',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне нужно знать, что затевает Алый Натиск. И ты мне в этом поможешь.$B$BЛети в бухту Алого Натиска и обыщи их багажные сундуки. Ищи бумаги и документы. Сундуки будут заперты, так что тебе надо будет добыть ключи у бойцов Алого Натиска. Добыть любой ценой!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 5 донесений разведки Алого Натиска по заданию Аурока Мрачного Проклятия с Уступа Смерти.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аурку Мрачному Проклятию на Уступ Смерти, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12839,'Грандиозные планы верховного адмирала','На первый взгляд эта записка мало чем отличается от остальных разведданных, но при внимательном прочтении становится ясно, что здесь содержатся действительно важные сведения.$B$BСудя по этому письму, верховный адмирал Вествинд находится где-то на острове, в тайном укрытии. Он говорит о великих и славных днях, которые наступят уже совсем скоро, когда воины Алого Натиска сокрушат Короля-лича, а потом и весь мир, и в Азероте наконец установится порядок.$B$BНадо показать это письмо лорду-командиру!','Отнесите письмо верховного адмирала лорду-командиру Аретy на Уступ Смерти.','Данные по Алому Натиску надо доставить Ауроку Мрачному Проклятию.$B$B<Лорд-командир выразительно смотрит на вас, давая понять, что вы можете идти.>','Вернитесь к лорду-командиру Арету на Уступ Смерти, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Грандиозные планы верховного адмирала',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На первый взгляд эта записка мало чем отличается от остальных разведданных, но при внимательном прочтении становится ясно, что здесь содержатся действительно важные сведения.$B$BСудя по этому письму, верховный адмирал Вествинд находится где-то на острове, в тайном укрытии. Он говорит о великих и славных днях, которые наступят уже совсем скоро, когда воины Алого Натиска сокрушат Короля-лича, а потом и весь мир, и в Азероте наконец установится порядок.$B$BНадо показать это письмо лорду-командиру!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите письмо верховного адмирала лорду-командиру Аретy на Уступ Смерти.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Данные по Алому Натиску надо доставить Ауроку Мрачному Проклятию.$B$B<Лорд-командир выразительно смотрит на вас, давая понять, что вы можете идти.>',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лорду-командиру Арету на Уступ Смерти, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12840,'Совершенно секретно','Если кто-то и знает, где сейчас адмирал, так это его капитаны на судах в бухте Алого Натиска.$B$B<Лорд-командир потирает руки.>$B$BЕсли память меня не подводит, их зовут Вельсингтон и Хартфорд. Выбей из них информацию, а потом убей обоих.$B$BМне нужно знать, где верховный адмирал!','Выбейте информацию из капитанов Вельсингтона и Хартфорда, убейте обоих и возвращайтесь к лорду-командиру Арету на Уступ Смерти.','Где капитан Вельсингтон?','Вернитесь к лорду-командиру Арету на Уступ Смерти, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Совершенно секретно',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если кто-то и знает, где сейчас адмирал, так это его капитаны на судах в бухте Алого Натиска.$B$B<Лорд-командир потирает руки.>$B$BЕсли память меня не подводит, их зовут Вельсингтон и Хартфорд. Выбей из них информацию, а потом убей обоих.$B$BМне нужно знать, где верховный адмирал!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выбейте информацию из капитанов Вельсингтона и Хартфорда, убейте обоих и возвращайтесь к лорду-командиру Арету на Уступ Смерти.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Где капитан Вельсингтон?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лорду-командиру Арету на Уступ Смерти, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (12841,'Сделка с Каргой','По просьбе Лок\'лиры Карги принесите ей в Заброшенный рудник руны Ирквинн, отобрав их у надзирательницы Сиры.','У меня не было твердой уверенности, что ты вернешься. Мне страшно даже представить, что могло бы со мной приключиться, если бы я тут осталась еще на какое-то время.','Вернитесь к Лок\'лире Карге в Заброшенный рудник, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сделка с Каргой',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По просьбе Лок\'лиры Карги принесите ей в Заброшенный рудник руны Ирквинн, отобрав их у надзирательницы Сиры.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','У меня не было твердой уверенности, что ты вернешься. Мне страшно даже представить, что могло бы со мной приключиться, если бы я тут осталась еще на какое-то время.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лок\'лире Карге в Заброшенный рудник, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`endtext_loc8`) VALUES (12842,'Ковка рун: подготовка к битве','Запомни, рыцарь смерти: кузня рун – это инструмент Плети. Найти его можно только в Акерусе, Наксрамасе и в самом сердце Ледяной Короны! Только с помощью рунической кузницы можно наносить гравировку на твое оружие.$B$BНе забывай покрывать рунами любой клинок, которым ты владеешь. Рыцарь смерти должен быть готов к любым опасностям, которые встретятся ему на пути!','На оружие нанесены руны') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ковка рун: подготовка к битве',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Запомни, рыцарь смерти: кузня рун – это инструмент Плети. Найти его можно только в Акерусе, Наксрамасе и в самом сердце Ледяной Короны! Только с помощью рунической кузницы можно наносить гравировку на твое оружие.$B$BНе забывай покрывать рунами любой клинок, которым ты владеешь. Рыцарь смерти должен быть готов к любым опасностям, которые встретятся ему на пути!',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','На оружие нанесены руны',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12843,'Они забрали наших мужчин!','Нам нужна твоя помощь! Мы как раз направлялись в горы, чтобы установить башню-передатчик, но по дороге на нас напали...$B$BВроде бы врайкулы, только кожа у них была голубая и как будто заиндевевшая... и среди них не было ни одного мужчины. Одни женщины! Они забрали всех наших мужчин, а нас, женщин, отпустили. Пожалуйста, $n! У нас есть подозрение, что их держат в Сифрельдаре – деревне, расположенной прямо над К-3.','По просьбе Гретхен Искрошип отправляйтесь в деревню Сифрельдар и спасите 5 плененных гоблинов.','У тебя получилось! Наши мальчики вернулись!','Где еда? Гости прибудут с минуты на минуту!','Вернитесь к Гретхен Искрошип в К-3, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Они забрали наших мужчин!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нам нужна твоя помощь! Мы как раз направлялись в горы, чтобы установить башню-передатчик, но по дороге на нас напали...$B$BВроде бы врайкулы, только кожа у них была голубая и как будто заиндевевшая... и среди них не было ни одного мужчины. Одни женщины! Они забрали всех наших мужчин, а нас, женщин, отпустили. Пожалуйста, $n! У нас есть подозрение, что их держат в Сифрельдаре – деревне, расположенной прямо над К-3.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По просьбе Гретхен Искрошип отправляйтесь в деревню Сифрельдар и спасите 5 плененных гоблинов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','У тебя получилось! Наши мальчики вернулись!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Где еда? Гости прибудут с минуты на минуту!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гретхен Искрошип в К-3, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (12844,'Вернуть оборудование','Пожалуйста, $n, помоги нам. Когда хильды забрали наших мужчин, они забрали и все оборудование. Разумеется, самое главное, это спасти наших ребят, но, если ты вдруг случайно увидишь что-нибудь из нашего оборудования, постарайся забрать его и вернуть нам.$B$BИх деревня находится прямо над нами, на севере.','По просьбе Гретхен Искрошип принесите ей 8 предметов из снаряжения К-3, которые вы найдете в деревне Сифрельдар к северу от K-3.','Вернитесь к Гретхен Искрошип в К-3, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вернуть оборудование',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пожалуйста, $n, помоги нам. Когда хильды забрали наших мужчин, они забрали и все оборудование. Разумеется, самое главное, это спасти наших ребят, но, если ты вдруг случайно увидишь что-нибудь из нашего оборудования, постарайся забрать его и вернуть нам.$B$BИх деревня находится прямо над нами, на севере.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По просьбе Гретхен Искрошип принесите ей 8 предметов из снаряжения К-3, которые вы найдете в деревне Сифрельдар к северу от K-3.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гретхен Искрошип в К-3, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (12845,'Даларанский кристалл телепортации: флаг') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Даларанский кристалл телепортации: флаг',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (12846,'Найти всех до единого...','Все наши ребята вернулись... благодаря тебе, $n! Все... кроме одного.$B$BМой брат Зив не вернулся. Похоже, у них там какой-то рудник есть, где они держат пленников и заставляют их работать. Иди туда и попытайся что-нибудь разузнать.','Разыщите вход в Заброшенный рудник на севере деревни Сифрельдар и попробуйте выяснить, где может быть Зив Искрошип.','Уже вернулась, сестренка?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Найти всех до единого...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Все наши ребята вернулись... благодаря тебе, $n! Все... кроме одного.$B$BМой брат Зив не вернулся. Похоже, у них там какой-то рудник есть, где они держат пленников и заставляют их работать. Иди туда и попытайся что-нибудь разузнать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите вход в Заброшенный рудник на севере деревни Сифрельдар и попробуйте выяснить, где может быть Зив Искрошип.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Уже вернулась, сестренка?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12847,'Второй шанс','Я слышал, что у них в соборе есть какой-то архиепископ, но я не знал, что это воскрешенный и повышенный в чине Ландгрен! У Багрового собора всего один вход, он же выход, и его хорошо охраняют, так что $gодин:одна; ты не справишься.$B$BМы по-прежнему не знаем, где верховный адмирал, но на этот раз мы будем действовать наверняка!$B$BВозьми это устройство. Оно откроет врата, чтобы я мог пройти к вам туда, когда ты убьешь архиепископа.$B$BЯ подчиню себе его дух и заставлю его отвечать на мои вопросы! Мы найдем верховного адмирала Вествинда!','Убейте архиепископа Ландгрена и откройте Врата Арета рядом с трупом. Поговорите с лордом-командиром Аретом, когда тот закончит допрашивать дух архиепископа в Багровом соборе.','Да?','Вернитесь к лорду-командиру Арету на Уступ Смерти, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Второй шанс',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я слышал, что у них в соборе есть какой-то архиепископ, но я не знал, что это воскрешенный и повышенный в чине Ландгрен! У Багрового собора всего один вход, он же выход, и его хорошо охраняют, так что $gодин:одна; ты не справишься.$B$BМы по-прежнему не знаем, где верховный адмирал, но на этот раз мы будем действовать наверняка!$B$BВозьми это устройство. Оно откроет врата, чтобы я мог пройти к вам туда, когда ты убьешь архиепископа.$B$BЯ подчиню себе его дух и заставлю его отвечать на мои вопросы! Мы найдем верховного адмирала Вествинда!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте архиепископа Ландгрена и откройте Врата Арета рядом с трупом. Поговорите с лордом-командиром Аретом, когда тот закончит допрашивать дух архиепископа в Багровом соборе.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лорду-командиру Арету на Уступ Смерти, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (12848,'Вечный голод','Инструктор Разувий из Черного оплота приказал вам освободить недостойного ученика и хладнокровно убить его!$B$BВыжить должен только один!','Вернитесь к инструктору Разувию в Сердце Акеруса, что в Черном оплоте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вечный голод',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Инструктор Разувий из Черного оплота приказал вам освободить недостойного ученика и хладнокровно убить его!$B$BВыжить должен только один!',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к инструктору Разувию в Сердце Акеруса, что в Черном оплоте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (12849,'Сила крови, льда и нечестивости','В Зале Властности тебя ждут учителя школ крови, льда и нечестивости, которые могут обучить тебя этим темным искусствам.$B$BЯ, Лорд Торваль - глава школы крови, леди Алистра занимается нечестивыми практиками, а архилич Амал\'тазад безраздельно правит в школе льда.$B$BПриходи сюда почаще, ибо в этих знаниях заключена великая сила.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сила крови, льда и нечестивости',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','В Зале Властности тебя ждут учителя школ крови, льда и нечестивости, которые могут обучить тебя этим темным искусствам.$B$BЯ, Лорд Торваль - глава школы крови, леди Алистра занимается нечестивыми практиками, а архилич Амал\'тазад безраздельно правит в школе льда.$B$BПриходи сюда почаще, ибо в этих знаниях заключена великая сила.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (12850,'Командир сил Плети Таланор','Командир сил Плети Таланор ожидает тебя на балконе к юго-востоку отсюда. Доложи ему о прибытии и потребуй предоставить грифона Плети, знающего дорогу в Разлом Смерти.$B$BПринц Валанар будет ждать тебя внизу.$B$BДа продлятся твои страдания, $gбрат:сестра;!','Найдите командира сил Плети Таланора на балконе первого этажа Черного оплота.','Война началась, рыцарь смерти! Я немедленно прикажу подать для тебя самого быстрокрылого грифона, который отвезет тебя в Разлом Смерти. Хаос, смерть, разрушение! Ты станешь их глашатаем!','Рунический меч – это продолжение твоей руки. $C – ничто без своего клинка.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Командир сил Плети Таланор',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Командир сил Плети Таланор ожидает тебя на балконе к юго-востоку отсюда. Доложи ему о прибытии и потребуй предоставить грифона Плети, знающего дорогу в Разлом Смерти.$B$BПринц Валанар будет ждать тебя внизу.$B$BДа продлятся твои страдания, $gбрат:сестра;!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите командира сил Плети Таланора на балконе первого этажа Черного оплота.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Война началась, рыцарь смерти! Я немедленно прикажу подать для тебя самого быстрокрылого грифона, который отвезет тебя в Разлом Смерти. Хаос, смерть, разрушение! Ты станешь их глашатаем!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Рунический меч – это продолжение твоей руки. $C – ничто без своего клинка.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (12851,'Сейчас мы тебя испытаем, женщина!$b$bСейчас мы проверим, что там у тебя в груди – сердце сопливой швеи или сердце королевы воинов!$b$bОдно настоящее сражение – и мы узнаем ответ...$b$bТы можешь врать своей матери, своим сестрам и даже себе, но войне не соврешь. Она всегда вскроет твою истинную природу.$b$bКогда будешь готова – садись на Ледоклыка и мчись в бой. И пусть твои стрелы обрушатся градом смерти на головы наших врагов.','По заданию Бриджаны из деревни Бруннхильдар оседлайте Ледоклыка и застрелите 7 снежных воргов и 15 снежных великанов в долине Древней Зимы.','Вернитесь к Бриджане в Долину Древних Зим, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сейчас мы тебя испытаем, женщина!$b$bСейчас мы проверим, что там у тебя в груди – сердце сопливой швеи или сердце королевы воинов!$b$bОдно настоящее сражение – и мы узнаем ответ...$b$bТы можешь врать своей матери, своим сестрам и даже себе, но войне не соврешь. Она всегда вскроет твою истинную природу.$b$bКогда будешь готова – садись на Ледоклыка и мчись в бой. И пусть твои стрелы обрушатся градом смерти на головы наших врагов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По заданию Бриджаны из деревни Бруннхильдар оседлайте Ледоклыка и застрелите 7 снежных воргов и 15 снежных великанов в долине Древней Зимы.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бриджане в Долину Древних Зим, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (12852,'Поиски адмирала','Когда на верховного генерала Аббендис напали в Новом Дольном Очаге, Вествинд сбежал, укрывшись в полностью непроницаемой защитной магической сфере.$B$BЯ хорошо разбираюсь в рассеивании магии.$B$BВозьми вот это и используй против него в Скрытой пещере, когда он активирует магическую сферу. Жалко, меня там не будет. Хотелось бы мне посмотреть на его лицо, когда ты проделаешь этот фокус.$B$BРазделайся же с ним.','Убейте верховного адмирала Вествинда, а потом возвращайтесь к лорду-командиру Арету на Уступ Смерти.','Мал\'Ганис?!\n\n<Лорд-командир громко смеется.>\n\nДемоны вновь приютили этих недоумков, но теперь они уничтожены!\n\nНадеюсь, мой доблестный $C не откажется тут задержаться и помочь нам прикончить всех остальных? Может, какая-то из этих вещиц будет достаточным поводом, чтобы остаться?','Вернитесь к лорду-командиру Арету на Уступ Смерти, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поиски адмирала',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда на верховного генерала Аббендис напали в Новом Дольном Очаге, Вествинд сбежал, укрывшись в полностью непроницаемой защитной магической сфере.$B$BЯ хорошо разбираюсь в рассеивании магии.$B$BВозьми вот это и используй против него в Скрытой пещере, когда он активирует магическую сферу. Жалко, меня там не будет. Хотелось бы мне посмотреть на его лицо, когда ты проделаешь этот фокус.$B$BРазделайся же с ним.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте верховного адмирала Вествинда, а потом возвращайтесь к лорду-командиру Арету на Уступ Смерти.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мал\'Ганис?!\n\n<Лорд-командир громко смеется.>\n\nДемоны вновь приютили этих недоумков, но теперь они уничтожены!\n\nНадеюсь, мой доблестный $C не откажется тут задержаться и помочь нам прикончить всех остальных? Может, какая-то из этих вещиц будет достаточным поводом, чтобы остаться?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лорду-командиру Арету на Уступ Смерти, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (12853,'Поторопить события','Эй, дружище!$B$BЛюбишь фейерверки и взрывы? Конечно, любишь! Так вот, я знаю одно интересное местечко, которое тебе непременно придется по вкусу. Там, в К-3, разрабатывают самые лучшие взрывчатые вещества, с помощью которых можно поднять на воздух что угодно! Заманчиво, а? Не пропусти все на свете, отправляйся туда прямо сейчас и поговори с Глумом Свечекрутом!$B$BНеобходимые разъяснения: для участия в эксперименте необходимо выполнить некоторые подготовительные работы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поторопить события',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эй, дружище!$B$BЛюбишь фейерверки и взрывы? Конечно, любишь! Так вот, я знаю одно интересное местечко, которое тебе непременно придется по вкусу. Там, в К-3, разрабатывают самые лучшие взрывчатые вещества, с помощью которых можно поднять на воздух что угодно! Заманчиво, а? Не пропусти все на свете, отправляйся туда прямо сейчас и поговори с Глумом Свечекрутом!$B$BНеобходимые разъяснения: для участия в эксперименте необходимо выполнить некоторые подготовительные работы.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (12854,'По следам Бранна','После того как мы обнаружили журнал Бранна в Седых холмах, нам удалось с ним связаться всего один раз. В штаб-квартиру Лиги исследователей в Стальгорне подбросили таинственную записку. От кого – непонятно. Там было сказано, что нам нужно встретиться с Бранном в его лагере и помочь ему в его поисках.$B$BНасколько я понимаю, его лагерь находится к северо-востоку отсюда, на том берегу реки Дыхания Бора, у подножия каких-то развалин подле Пути Титанов.','Заберите завернутую в мешковину записку из лагеря Бранна и возвращайтесь к археологу Андорину в Ледяную крепость.','<Археолог Андорин смотрит на вас выжидательно.>$B$BПредполагалось, что ты вернешься с Бранном, а не с каким-то клочком бумаги. Что вообще происходит?','Вернитесь к археологу Андорину в Ледяную крепость, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','По следам Бранна',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','После того как мы обнаружили журнал Бранна в Седых холмах, нам удалось с ним связаться всего один раз. В штаб-квартиру Лиги исследователей в Стальгорне подбросили таинственную записку. От кого – непонятно. Там было сказано, что нам нужно встретиться с Бранном в его лагере и помочь ему в его поисках.$B$BНасколько я понимаю, его лагерь находится к северо-востоку отсюда, на том берегу реки Дыхания Бора, у подножия каких-то развалин подле Пути Титанов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заберите завернутую в мешковину записку из лагеря Бранна и возвращайтесь к археологу Андорину в Ледяную крепость.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Археолог Андорин смотрит на вас выжидательно.>$B$BПредполагалось, что ты вернешься с Бранном, а не с каким-то клочком бумаги. Что вообще происходит?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к археологу Андорину в Ледяную крепость, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12855,'Найти преступника','Судя по намекам в записке Бранна, вместе с ней он должен был спрятать что-то еще. Может быть, сверток... или что-то похожее. Ты $gуверен:уверена;, что там больше ничего не было?$B$BЛадно, вот что мы сделаем. Возьми одну из северных гончих. У них острый нюх, и Зиморожденные используют их в качестве ищеек. Отведи ее в разрушенный лагерь, и пусть она возьмет след Бранна.$B$BС ее помощью ты найдешь пропавшие вещи, а если повезет – то и самого Бранна тоже.','Используйте ошейник северной гончей в Заброшенном лагере, чтобы выследить тех, кто забрал вещи Бранна. Когда вы их разыщете, включите переговорное устройство и свяжитесь с теми, с кем получится связаться.','Кто ты?','Воспользуйтесь переговорным устройством и поговорите с тем, с кем получится связаться.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Найти преступника',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Судя по намекам в записке Бранна, вместе с ней он должен был спрятать что-то еще. Может быть, сверток... или что-то похожее. Ты $gуверен:уверена;, что там больше ничего не было?$B$BЛадно, вот что мы сделаем. Возьми одну из северных гончих. У них острый нюх, и Зиморожденные используют их в качестве ищеек. Отведи ее в разрушенный лагерь, и пусть она возьмет след Бранна.$B$BС ее помощью ты найдешь пропавшие вещи, а если повезет – то и самого Бранна тоже.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте ошейник северной гончей в Заброшенном лагере, чтобы выследить тех, кто забрал вещи Бранна. Когда вы их разыщете, включите переговорное устройство и свяжитесь с теми, с кем получится связаться.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Кто ты?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Воспользуйтесь переговорным устройством и поговорите с тем, с кем получится связаться.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (12856,'Холодные сердца','Умереть в яростной битве с оружием в руках – это почетная и славная смерть. Умереть замороженной в глыбе льда под непрестанные насмешки врагов – это стыд и бесчестье.$b$bЛети в Дун Ниффелем, что к востоку от Долины Древних Зим, и освободи пленных протодраконов. Вместе с ними вы сумеете освободить наших сестер из ледяной тюрьмы и вернуть их домой.$b$bНо остерегайся дубинок великанов, если не хочешь оказаться в числе замороженных пленниц.','Освободите 3 пленных протодраконов и спасите 9 пленных бруннхильдарок.','Вернитесь к Бриджане в Долину Древних Зим, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Холодные сердца',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Умереть в яростной битве с оружием в руках – это почетная и славная смерть. Умереть замороженной в глыбе льда под непрестанные насмешки врагов – это стыд и бесчестье.$b$bЛети в Дун Ниффелем, что к востоку от Долины Древних Зим, и освободи пленных протодраконов. Вместе с ними вы сумеете освободить наших сестер из ледяной тюрьмы и вернуть их домой.$b$bНо остерегайся дубинок великанов, если не хочешь оказаться в числе замороженных пленниц.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Освободите 3 пленных протодраконов и спасите 9 пленных бруннхильдарок.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бриджане в Долину Древних Зим, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (12858,'Кусочки головоломки','Слава Свету, что кто-то все-таки получил мое сообщение. Теперь, когда мне уже не угрожает опасность от железных дворфов, у меня есть одно дело, и мне нужна твоя помощь. Мне нужно собрать краеугольный камень Норганнона, охраняющий доступ к архивам Ульдуара. Титаны разделили его на две части и спрятали их в разных местах.$B$BОдна из частей, оболочка, хранится в Библиотеке Изобретателя на северном побережье, к югу от самого Ульдуара. Первым делом тебе надо будет собрать фрагменты диска доступа – отобрать их у стражей библиотеки.','Соберите 6 фрагментов диска изобретателя и сложите из них диск изобретателя.','Замечательно! Теперь с помощью этого диска мы сможем открыть хранилище изобретателя.','Воспользуйтесь переговорным устройством Бранна для связи с Бранном Бронзобородом.$B$BЕсли вы потеряете переговорное устройство, возьмите новое у археолога Андорина в Ледяной крепости.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кусочки головоломки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слава Свету, что кто-то все-таки получил мое сообщение. Теперь, когда мне уже не угрожает опасность от железных дворфов, у меня есть одно дело, и мне нужна твоя помощь. Мне нужно собрать краеугольный камень Норганнона, охраняющий доступ к архивам Ульдуара. Титаны разделили его на две части и спрятали их в разных местах.$B$BОдна из частей, оболочка, хранится в Библиотеке Изобретателя на северном побережье, к югу от самого Ульдуара. Первым делом тебе надо будет собрать фрагменты диска доступа – отобрать их у стражей библиотеки.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 6 фрагментов диска изобретателя и сложите из них диск изобретателя.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Замечательно! Теперь с помощью этого диска мы сможем открыть хранилище изобретателя.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Воспользуйтесь переговорным устройством Бранна для связи с Бранном Бронзобородом.$B$BЕсли вы потеряете переговорное устройство, возьмите новое у археолога Андорина в Ледяной крепости.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12859,'Негасимый огонь','Тролли нападали на логово Яростного Когтя и выгоняли всех волчеров! А теперь – еще хуже. Тролли жгут нашу деревню! Совсем-совсем плохо. Вождь просил Моки, главного шамана Яростного Когтя, изучать их огонь. И вот что удивляет! Огонь по-прежнему жарок и может жечь и сжигать.$B$BПомоги волчерам погасить огонь. У Моки есть для тебя особый огнетушитель. Возьми его и потуши пожары в логове Яростного Когтя на юго-востоке. Иногда так бывает, что одна струя не потушит огонь – надо много. Но в огнетушителе вода есть всегда! Магия Яростного Когтя очень сильная, да!','Используйте огнетушитель Яростного Когтя, чтобы потушить 15 пожаров в логове Яростного Когтя по просьбе старого шамана Моки в Разломе Света в Зул\'Драке.','Хм, пожары потушены?','Вернитесь к старому шаману Моки в Разлом Света, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Негасимый огонь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тролли нападали на логово Яростного Когтя и выгоняли всех волчеров! А теперь – еще хуже. Тролли жгут нашу деревню! Совсем-совсем плохо. Вождь просил Моки, главного шамана Яростного Когтя, изучать их огонь. И вот что удивляет! Огонь по-прежнему жарок и может жечь и сжигать.$B$BПомоги волчерам погасить огонь. У Моки есть для тебя особый огнетушитель. Возьми его и потуши пожары в логове Яростного Когтя на юго-востоке. Иногда так бывает, что одна струя не потушит огонь – надо много. Но в огнетушителе вода есть всегда! Магия Яростного Когтя очень сильная, да!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте огнетушитель Яростного Когтя, чтобы потушить 15 пожаров в логове Яростного Когтя по просьбе старого шамана Моки в Разломе Света в Зул\'Драке.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Хм, пожары потушены?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старому шаману Моки в Разлом Света, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12860,'Сбор информации','Этот диск, который ты $gсобрал:собрала;... он пустой! Наверное, Хранитель Мимир, который построил эту библиотеку, спрятал всю информацию в другом месте. Осмотри Библиотеку Изобретателя, там нигде нет банков данных?$B$BМожет, диск предназначен для них... Попробуй использовать его на каком-нибудь из банков данных. Может быть, он считывает и записывает информацию с этих устройств. Попробуй сделать, как я сказал, а потом свяжись со мной и расскажи, как успехи. А я тем временем попробую разыскать вторую половину ключа от архива.','Воспользуйтесь диском изобретателя, чтобы считать 7 фрагментов секретных данных из банков данных.','<Бранн смотрит на диск, который вы ему показываете.>$B$BА как я отсюда пойму, записано там что-нибудь или нет?! Опиши мне подробно, что было..$B$B<Вы подробно описываете процесс поиска и считывания данных.>$B$BЗначит, там все работает? Надо отдать должное Хранителю Мимиру. Он – настоящий мастер своего дела, чего, по всей видимости, нельзя сказать об остальных хранителях...','Ну, что там с диском? Тебе удалось считать информацию?','Воспользуйтесь переговорным устройством Бранна для связи с Бранном Бронзобородом.$B$BЕсли вы потеряете переговорное устройство, возьмите новое у археолога Андорина в Ледяной крепости.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сбор информации',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этот диск, который ты $gсобрал:собрала;... он пустой! Наверное, Хранитель Мимир, который построил эту библиотеку, спрятал всю информацию в другом месте. Осмотри Библиотеку Изобретателя, там нигде нет банков данных?$B$BМожет, диск предназначен для них... Попробуй использовать его на каком-нибудь из банков данных. Может быть, он считывает и записывает информацию с этих устройств. Попробуй сделать, как я сказал, а потом свяжись со мной и расскажи, как успехи. А я тем временем попробую разыскать вторую половину ключа от архива.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь диском изобретателя, чтобы считать 7 фрагментов секретных данных из банков данных.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Бранн смотрит на диск, который вы ему показываете.>$B$BА как я отсюда пойму, записано там что-нибудь или нет?! Опиши мне подробно, что было..$B$B<Вы подробно описываете процесс поиска и считывания данных.>$B$BЗначит, там все работает? Надо отдать должное Хранителю Мимиру. Он – настоящий мастер своего дела, чего, по всей видимости, нельзя сказать об остальных хранителях...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, что там с диском? Тебе удалось считать информацию?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Воспользуйтесь переговорным устройством Бранна для связи с Бранном Бронзобородом.$B$BЕсли вы потеряете переговорное устройство, возьмите новое у археолога Андорина в Ледяной крепости.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12861,'Плохие тролли','Дракуру... Знаешь, кто этот тролль? Я думаю, этот Дракуру, он вождь плохих троллей. Они называют себя троллями Дракуру – вот я и смекнул, что к чему. Теперь понимаешь, почему я – вождь племени Яростного Когтя. Самый умный из всех волчеров!$B$BНо я с тобой говорю о другом. Плохие тролли пришли и прогнали племя из логова. Волчеры, которые не убежали, пойманы и сейчас в плену в деревне. Ты пойдешь в логово Яростного Когтя, это на юго-востоке, и освободишь пленных волчеров. Чтобы добыть отпиратель замка, надо убить плохого тролля. Отпирателей надо много – убивай много троллей.','Ты спасаешь Коготь Ярости?','Вернитесь к вождю Яростного Когтя в Разлом Света, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Плохие тролли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Дракуру... Знаешь, кто этот тролль? Я думаю, этот Дракуру, он вождь плохих троллей. Они называют себя троллями Дракуру – вот я и смекнул, что к чему. Теперь понимаешь, почему я – вождь племени Яростного Когтя. Самый умный из всех волчеров!$B$BНо я с тобой говорю о другом. Плохие тролли пришли и прогнали племя из логова. Волчеры, которые не убежали, пойманы и сейчас в плену в деревне. Ты пойдешь в логово Яростного Когтя, это на юго-востоке, и освободишь пленных волчеров. Чтобы добыть отпиратель замка, надо убить плохого тролля. Отпирателей надо много – убивай много троллей.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты спасаешь Коготь Ярости?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к вождю Яростного Когтя в Разлом Света, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (12862,'Когда остается единственный выход...','Что-то я сомневаюсь, что нам удастся закрепиться в этих горах.$B$BПоверь мне, я не из тех, кто легко сдается... но, когда ты зажат между замерзшими машинами, злобными врайкульскими бабами, какими-то непонятными существами, жаждущими стать драконами, и еще добрым десятком других воинственных тварей, это как-то не способствует оптимистическому настрою.$B$BНо ты все же не падай духом! Если мы не можем там закрепиться, это еще не значит, что мы не можем доставить тебя туда... поездка в один конец – это вовсе не сложно, когда привыкаешь.$B$B<Рикет указывает на ракеты неподалеку.>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Когда остается единственный выход...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что-то я сомневаюсь, что нам удастся закрепиться в этих горах.$B$BПоверь мне, я не из тех, кто легко сдается... но, когда ты зажат между замерзшими машинами, злобными врайкульскими бабами, какими-то непонятными существами, жаждущими стать драконами, и еще добрым десятком других воинственных тварей, это как-то не способствует оптимистическому настрою.$B$BНо ты все же не падай духом! Если мы не можем там закрепиться, это еще не значит, что мы не можем доставить тебя туда... поездка в один конец – это вовсе не сложно, когда привыкаешь.$B$B<Рикет указывает на ракеты неподалеку.>',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12863,'Большое спасибо','Вот спасибо, что ты $Gпришел, малыш:пришла, милая;.$B$BСудя по твоим удивленным глазам и дрожащим рукам, ты тут $gновенький:новенькая;. Я угадал? Тогда тебе надо скорее познакомиться с нашими великодушными хозяевами!$B$BУ нас тут образовался запас лишних медикаментов... то есть они никогда не лишние, но у нас их действительно избыток. Отнеси этот ящик Глорталу и спроси, не нужна ли ему помощь. А то не хотелось бы, чтобы они думали, будто мы им не благодарны за столь теплый прием.','Отнесите ящик с медикаментами Глорталу Жесткобороду из Ледяной крепости.','Медикаменты? Спасибо! Хотя, честно сказать, я не знаю, зачем нам столько, но они наверняка пригодятся.$B$BРад с тобой познакомиться... В последнее время гости к нам ходят редко, и новый товарищ – это всегда очень здорово!','Привет.','Вернитесь к Глорталу Жесткобороду в Ледяную крепость, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Большое спасибо',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот спасибо, что ты $Gпришел, малыш:пришла, милая;.$B$BСудя по твоим удивленным глазам и дрожащим рукам, ты тут $gновенький:новенькая;. Я угадал? Тогда тебе надо скорее познакомиться с нашими великодушными хозяевами!$B$BУ нас тут образовался запас лишних медикаментов... то есть они никогда не лишние, но у нас их действительно избыток. Отнеси этот ящик Глорталу и спроси, не нужна ли ему помощь. А то не хотелось бы, чтобы они думали, будто мы им не благодарны за столь теплый прием.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите ящик с медикаментами Глорталу Жесткобороду из Ледяной крепости.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Медикаменты? Спасибо! Хотя, честно сказать, я не знаю, зачем нам столько, но они наверняка пригодятся.$B$BРад с тобой познакомиться... В последнее время гости к нам ходят редко, и новый товарищ – это всегда очень здорово!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Привет.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Глорталу Жесткобороду в Ледяную крепость, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`) VALUES (12864,'Пропавшие разведчики','Раз уж ты здесь, надо этим воспользоваться.$B$BНаши разведчики уже давно должны были вернуться, но их все нет и нет... Эти горы – суровое место, и хотя эти ребята – настоящие мастера своего дела, я все равно беспокоюсь... $B$BИди на восток... в долину Дыхания Бора, к водопаду Бора... они ушли в том направлении. Если ты их найдешь, если найдешь хоть какие-то указания на то, где они могут быть, сразу же возвращайся сюда и докладывай мне. У нас тут немало врагов... и если наши ребята нуждаются в помощи, то чем быстрее мы об этом узнаем, тем лучше.','Обыщите долину Дыхания Бора и водопад Бора и попробуйте разыскать пропавших разведчиков из клана Зиморожденных.','Найти пропавших разведчиков') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пропавшие разведчики',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Раз уж ты здесь, надо этим воспользоваться.$B$BНаши разведчики уже давно должны были вернуться, но их все нет и нет... Эти горы – суровое место, и хотя эти ребята – настоящие мастера своего дела, я все равно беспокоюсь... $B$BИди на восток... в долину Дыхания Бора, к водопаду Бора... они ушли в том направлении. Если ты их найдешь, если найдешь хоть какие-то указания на то, где они могут быть, сразу же возвращайся сюда и докладывай мне. У нас тут немало врагов... и если наши ребята нуждаются в помощи, то чем быстрее мы об этом узнаем, тем лучше.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обыщите долину Дыхания Бора и водопад Бора и попробуйте разыскать пропавших разведчиков из клана Зиморожденных.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Найти пропавших разведчиков',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12865,'Верные друзья','Новые люди! Свежая кровь! Очень рад познакомиться! У меня есть для тебя работа.$B$BНа северо-востоке отсюда лежит Подножие... суровый край, да... но мне донесли, что там видели целое стадо люторогов. Наши птицы очень уважают мясо люторогов, но сейчас стало опасно ходить на охоту – повсюду гнездовья протодраконов, житья от них нет!$B$BНе в службу, а в дружбу... постарайся добыть мяса для наших птичек и накорми их как следует, ладно?','По поручению Фьюрлина Ледоброва из Ледяной крепости добудьте 8 кусков свежего мяса люторога и покормите грозовестников, обитающих прямо над городом.','Эти птицы были лояльны к нам в течение длительного времени...','Вернитесь к Фьюрлину Ледоброву в Ледяную крепость, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Верные друзья',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Новые люди! Свежая кровь! Очень рад познакомиться! У меня есть для тебя работа.$B$BНа северо-востоке отсюда лежит Подножие... суровый край, да... но мне донесли, что там видели целое стадо люторогов. Наши птицы очень уважают мясо люторогов, но сейчас стало опасно ходить на охоту – повсюду гнездовья протодраконов, житья от них нет!$B$BНе в службу, а в дружбу... постарайся добыть мяса для наших птичек и накорми их как следует, ладно?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По поручению Фьюрлина Ледоброва из Ледяной крепости добудьте 8 кусков свежего мяса люторога и покормите грозовестников, обитающих прямо над городом.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Эти птицы были лояльны к нам в течение длительного времени...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фьюрлину Ледоброву в Ледяную крепость, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12866,'Сопротивление агрессорам','Проклятые гарпии. Мы уже столько раз задавали им трепку... и после каждого раза они какое-то время сидели тихо. Я думал, что после последнего раза они больше к нам не полезут.$B$BНо нет.$B$BНичему эти твари не учатся... но если их будет мало, они вряд ли станут нападать. Отправляйся в долины на севере и востоке и постарайся прикончить побольше гарпий.','По заданию Глортала Жесткоборода из Ледяной крепости убейте 8 крикуний и 8 ведьм из стаи Ледяного Пера.','Да, это грязная работа, я знаю, и мы очень тебе благодарны. Кстати, что за имя там разведчик упоминал... Сирана?','Стойкие твари... Думаю никогда не покажется, что мы избавимся от них. Они размножаются как кролики.','Вернитесь к Глорталу Жесткобороду в Ледяную крепость, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сопротивление агрессорам',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Проклятые гарпии. Мы уже столько раз задавали им трепку... и после каждого раза они какое-то время сидели тихо. Я думал, что после последнего раза они больше к нам не полезут.$B$BНо нет.$B$BНичему эти твари не учатся... но если их будет мало, они вряд ли станут нападать. Отправляйся в долины на севере и востоке и постарайся прикончить побольше гарпий.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По заданию Глортала Жесткоборода из Ледяной крепости убейте 8 крикуний и 8 ведьм из стаи Ледяного Пера.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, это грязная работа, я знаю, и мы очень тебе благодарны. Кстати, что за имя там разведчик упоминал... Сирана?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Стойкие твари... Думаю никогда не покажется, что мы избавимся от них. Они размножаются как кролики.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Глорталу Жесткобороду в Ледяную крепость, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12867,'Похитители птенцов','Принесите Фьюрлину Ледоброву из Ледяной крепости 15 яиц грозовестников.','Когда мы решим эту проблемы, орлы снова будут свободно парить в небе над нами.','Вернитесь к Фьюрлину Ледоброву в Ледяную крепость, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Похитители птенцов',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Фьюрлину Ледоброву из Ледяной крепости 15 яиц грозовестников.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Когда мы решим эту проблемы, орлы снова будут свободно парить в небе над нами.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фьюрлину Ледоброву в Ледяную крепость, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12868,'Источник всех бед','Похоже, эта бесноватая Сирана Ледяной Вопль подстрекает всех гарпий. Я так думаю, если избавиться от нее, они перестанут на нас нападать. Один из наших странников бурь сказал, что заметил ее у вершины прямо к северо-западу отсюда. Разыщи эту мегеру и покончи с ней. Невозможно больше терпеть.','По просьбе Глортала Жесткоборода убейте Сирану Ледяной Вопль.','Значит, все сделано. Большое спасибо.$B$BЯ разговаривал с Фьюрлином – он сказал, что его отряд возьмется за приструнение гарпий. Главное – задать им хорошую трепку, и им вряд ли уже хватит смелости нападать. Я знаю, работенка была не из приятных – вот, держи это в знак моей благодарности.','Здесь слишком холодно, и тут обычные вредители... гарпии. Повезло нам.','Вернитесь к Глорталу Жесткобороду в Ледяную крепость, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Источник всех бед',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Похоже, эта бесноватая Сирана Ледяной Вопль подстрекает всех гарпий. Я так думаю, если избавиться от нее, они перестанут на нас нападать. Один из наших странников бурь сказал, что заметил ее у вершины прямо к северо-западу отсюда. Разыщи эту мегеру и покончи с ней. Невозможно больше терпеть.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По просьбе Глортала Жесткоборода убейте Сирану Ледяной Вопль.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Значит, все сделано. Большое спасибо.$B$BЯ разговаривал с Фьюрлином – он сказал, что его отряд возьмется за приструнение гарпий. Главное – задать им хорошую трепку, и им вряд ли уже хватит смелости нападать. Я знаю, работенка была не из приятных – вот, держи это в знак моей благодарности.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Здесь слишком холодно, и тут обычные вредители... гарпии. Повезло нам.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Глорталу Жесткобороду в Ледяную крепость, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12869,'Все слишком далеко зашло','Ты ведь $gбыл:была; там вместе с Локеном, да? Железные дворфы захватили Веранус, мать всех протодраконов. Разумеется, драконы этому не рады... они встревожены и потому агрессивны.$B$BНу, все и покатилось, как снежный ком... они захватили территорию, исконную территорию грозовестников... Ты знаешь, на чьей мы стороне... они всегда были нашими верными союзниками, и мы не можем их бросить. Поэтому мы отправляемся к Подножию, чтобы оказать им поддержку. $B$BКороль Грозовое Сердце оставил мне свой молот – возьми его и используй, как должно. Но потом непременно верни его мне.','Мне что-то не верится, что драконы так быстро отступятся. Если можешь, задержись тут до завтра. Наверняка нам понадобится твоя помощь.','Все грозит выйти из-под контроля...','Вернитесь к Фьюрлину Ледоброву в Ледяную крепость, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Все слишком далеко зашло',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты ведь $gбыл:была; там вместе с Локеном, да? Железные дворфы захватили Веранус, мать всех протодраконов. Разумеется, драконы этому не рады... они встревожены и потому агрессивны.$B$BНу, все и покатилось, как снежный ком... они захватили территорию, исконную территорию грозовестников... Ты знаешь, на чьей мы стороне... они всегда были нашими верными союзниками, и мы не можем их бросить. Поэтому мы отправляемся к Подножию, чтобы оказать им поддержку. $B$BКороль Грозовое Сердце оставил мне свой молот – возьми его и используй, как должно. Но потом непременно верни его мне.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мне что-то не верится, что драконы так быстро отступятся. Если можешь, задержись тут до завтра. Наверняка нам понадобится твоя помощь.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Все грозит выйти из-под контроля...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фьюрлину Ледоброву в Ледяную крепость, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12870,'Древние реликвии','Ха, здорово!$B$BПрежде, чем ты отправишься на опасные приключения, вершить великие дела, могу ли я попросить тебя о маленьком одолжении, $gпаренек:деточка;?$B$BВ этих горах полным-полно драгоценных реликвий и всяких побрякушек... Для Лиги эти места – просто кладезь! Я был бы тебе очень признателен, если бы ты $gтащил:тащила; все ценное, на что наткнешься, ко мне. Я тебя даже элем угощу, за труды! Поверь мне, $gпарень:девчушка; – сделка классная, не пожалеешь!','Принесите Рорку Остробороду в Ледяную крепость 10 реликвий Ульдуара.','Удалось найти для меня те реликвии, про которые я говорил тебе?','Вернитесь к Рорку Остробороду в Ледяную крепость, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Древние реликвии',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ха, здорово!$B$BПрежде, чем ты отправишься на опасные приключения, вершить великие дела, могу ли я попросить тебя о маленьком одолжении, $gпаренек:деточка;?$B$BВ этих горах полным-полно драгоценных реликвий и всяких побрякушек... Для Лиги эти места – просто кладезь! Я был бы тебе очень признателен, если бы ты $gтащил:тащила; все ценное, на что наткнешься, ко мне. Я тебя даже элем угощу, за труды! Поверь мне, $gпарень:девчушка; – сделка классная, не пожалеешь!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Рорку Остробороду в Ледяную крепость 10 реликвий Ульдуара.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось найти для меня те реликвии, про которые я говорил тебе?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Рорку Остробороду в Ледяную крепость, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12871,'Помощь Лиги исследователей','Интересно. Что-то я не вижу ни одного блокирующего механизма на этой оболочке, что дает все основания предположить, что для того, чтобы собрать краеугольный камень, недостаточно просто найти недостающий кусок и соединить их друг с другом.$B$BОтнеси оболочку руководителю экспедиции Лагнусу в Ледяную крепость. Может быть, он разберется, каким должно быть ядро, если судить по оболочке, и, может быть, даже сумеет уговорить снежных дворфов, чтобы они помогли нам его найти.$B$BА я пока попытаюсь придумать, как соединить обе части. Когда получим какие-то результаты, тогда и поговорим.','Отнесите оболочку Норганнона Лагнусу в Ледяную крепость.','Привет!','Вернитесь к Лагнусу в Ледяную крепость, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Помощь Лиги исследователей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Интересно. Что-то я не вижу ни одного блокирующего механизма на этой оболочке, что дает все основания предположить, что для того, чтобы собрать краеугольный камень, недостаточно просто найти недостающий кусок и соединить их друг с другом.$B$BОтнеси оболочку руководителю экспедиции Лагнусу в Ледяную крепость. Может быть, он разберется, каким должно быть ядро, если судить по оболочке, и, может быть, даже сумеет уговорить снежных дворфов, чтобы они помогли нам его найти.$B$BА я пока попытаюсь придумать, как соединить обе части. Когда получим какие-то результаты, тогда и поговорим.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите оболочку Норганнона Лагнусу в Ледяную крепость.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Привет!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лагнусу в Ледяную крепость, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12872,'Оболочка Норганнона','Идет зарядка диска изобретателя.$B$BДиск заряжен.$B$BЗагрузка аварийного протокола.$B$BАварийный протокол загружен. Пожалуйста, воспользуйтесь диском для активации охранника оболочки Норганнона, архивариуса Мехатона. Оболочка будет предоставлена вам после стандартной проверки личности.$B$BЖелаем вам приятного тысячелетия.','Заберите оболочку Норганнона у архивариуса Мехатона.','Да, это она! Первая половина краеугольного камня Норганнона. Отлично, $N. Когда я вернусь в Стальгорн, то позабочусь о том, чтобы тебя сделали почетным членом Лиги исследователей!','Да не стой ты столбом! Покажи мне оболочку!','Воспользуйтесь переговорным устройством Бранна для связи с Бранном Бронзобородом.$B$BЕсли вы потеряете переговорное устройство, возьмите новое у археолога Андорина в Ледяной крепости.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оболочка Норганнона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Идет зарядка диска изобретателя.$B$BДиск заряжен.$B$BЗагрузка аварийного протокола.$B$BАварийный протокол загружен. Пожалуйста, воспользуйтесь диском для активации охранника оболочки Норганнона, архивариуса Мехатона. Оболочка будет предоставлена вам после стандартной проверки личности.$B$BЖелаем вам приятного тысячелетия.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заберите оболочку Норганнона у архивариуса Мехатона.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, это она! Первая половина краеугольного камня Норганнона. Отлично, $N. Когда я вернусь в Стальгорн, то позабочусь о том, чтобы тебя сделали почетным членом Лиги исследователей!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да не стой ты столбом! Покажи мне оболочку!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Воспользуйтесь переговорным устройством Бранна для связи с Бранном Бронзобородом.$B$BЕсли вы потеряете переговорное устройство, возьмите новое у археолога Андорина в Ледяной крепости.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (12873,'Король Зиморожденных','Определенно... я хорошо представляю, как должно выглядеть ядро. Если кто-то из Зиморожденных видел его хоть раз, он узнает его по описанию.$B$BУ нас мало времени, так что давай сразу к делу. Иди к королю Грозовому Сердцу и проси его о помощи... он наверняка знает кого-то, кто поможет нам разыскать ядро. И будь с ним $gучтив и обходителен:учтива и обходительна; – он весьма уважаемый правитель.','Поговорите с Йоргом Грозовым Сердцем в Ледяной крепости.','Ядро Норганнона? В первый раз слышу. Но, кажется, я знаю, кто сумеет тебе помочь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Король Зиморожденных',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Определенно... я хорошо представляю, как должно выглядеть ядро. Если кто-то из Зиморожденных видел его хоть раз, он узнает его по описанию.$B$BУ нас мало времени, так что давай сразу к делу. Иди к королю Грозовому Сердцу и проси его о помощи... он наверняка знает кого-то, кто поможет нам разыскать ядро. И будь с ним $gучтив и обходителен:учтива и обходительна; – он весьма уважаемый правитель.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Йоргом Грозовым Сердцем в Ледяной крепости.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ядро Норганнона? В первый раз слышу. Но, кажется, я знаю, кто сумеет тебе помочь.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12874,'Рвение Зиморожденного','Я-то с радостью дам убежище путникам – накормлю, напою, все как надо. Но свои дела вы уж как-то решайте сами, я не стану принуждать своих людей заниматься чужими делами, да.$B$BВот, что я тебе скажу... мои люди – хорошие воины, настоящие воины. Когда юный Зиморожденный становится мужчиной, он доказывает свое мужество в битве. Чтобы, значит, все видели, что он настоящий мужчина, вот так.$B$BПокажи, что ты так же $gотважен, силен и свиреп:отважна, сильна и свирепа;, как наши воины – и тогда, может быть, мои люди тебе помогут. Поговори с Фьюрлином вон там, у скалы, и он назначит тебе испытание.','По указанию Йорга Грозового Сердца из Ледяной Крепости поговорите с Фьюрлином Ледобровом, который организует вам поездку и назначит для вас испытание.','Ты $Gвернулся:вернулась; ко мне. Ты $Gвернулся:вернулась; с победой?','Вернитесь к Йоргу Грозовому Сердцу в Ледяную крепость, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рвение Зиморожденного',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я-то с радостью дам убежище путникам – накормлю, напою, все как надо. Но свои дела вы уж как-то решайте сами, я не стану принуждать своих людей заниматься чужими делами, да.$B$BВот, что я тебе скажу... мои люди – хорошие воины, настоящие воины. Когда юный Зиморожденный становится мужчиной, он доказывает свое мужество в битве. Чтобы, значит, все видели, что он настоящий мужчина, вот так.$B$BПокажи, что ты так же $gотважен, силен и свиреп:отважна, сильна и свирепа;, как наши воины – и тогда, может быть, мои люди тебе помогут. Поговори с Фьюрлином вон там, у скалы, и он назначит тебе испытание.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По указанию Йорга Грозового Сердца из Ледяной Крепости поговорите с Фьюрлином Ледобровом, который организует вам поездку и назначит для вас испытание.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gвернулся:вернулась; ко мне. Ты $Gвернулся:вернулась; с победой?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Йоргу Грозовому Сердцу в Ледяную крепость, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (12875,'Опытный проводник','Я не знаю, где спрятано это ядро, но я обещался помочь и сдержу свое слово.$B$BВ пещере к северу отсюда живет отшельник по имени Дром Ледохват... это внизу, в долине. Сами мы отошли от традиций титанов, тем более что их почти и не осталось... но Дром верен древним обычаям: он присматривает за их наиболее ценными строениями и частенько беседует с часовым Кретеем.$B$BИди к нему в пещеру... скажи ему, что ты от меня, и он, стало быть, тебе поможет.','Разыщите Дрома Ледохвата.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Опытный проводник',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я не знаю, где спрятано это ядро, но я обещался помочь и сдержу свое слово.$B$BВ пещере к северу отсюда живет отшельник по имени Дром Ледохват... это внизу, в долине. Сами мы отошли от традиций титанов, тем более что их почти и не осталось... но Дром верен древним обычаям: он присматривает за их наиболее ценными строениями и частенько беседует с часовым Кретеем.$B$BИди к нему в пещеру... скажи ему, что ты от меня, и он, стало быть, тебе поможет.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите Дрома Ледохвата.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12876,'Нежеланные гости','Наши разведчики заметили железных дворфов в долине к северу отсюда. Я слышал, король Грозовое Сердце послал тебя навестить Дрома и, честно говоря, немного беспокоюсь из-за них.$B$BЕсли ты увидишь железных дворфов, когда туда направишься, задай им как следует от меня, идет? Я думаю, они точно не знают, где мы и как сюда добраться, и я предпочел бы, чтобы так оно и было впредь.','По просьбе Фьюрлина Ледоброва убейте 10 погромщиков из клана Закаленных Бурей.','Разведчики были правы? Там были гномы?','Вернитесь к Фьюрлину Ледоброву в Ледяную крепость, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нежеланные гости',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наши разведчики заметили железных дворфов в долине к северу отсюда. Я слышал, король Грозовое Сердце послал тебя навестить Дрома и, честно говоря, немного беспокоюсь из-за них.$B$BЕсли ты увидишь железных дворфов, когда туда направишься, задай им как следует от меня, идет? Я думаю, они точно не знают, где мы и как сюда добраться, и я предпочел бы, чтобы так оно и было впредь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По просьбе Фьюрлина Ледоброва убейте 10 погромщиков из клана Закаленных Бурей.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Разведчики были правы? Там были гномы?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фьюрлину Ледоброву в Ледяную крепость, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (12877,'Одинокий часовой','Я так и не нашел ядро... но я часто беседовал с часовым Кретеем и по его оговоркам понял, что он что-то знает. Ты найдешь Кретея в горах на востоке, в Подножии, где он наблюдает за Машиной Творцов. Вполне вероятно, что ядро находится где-то там, но тебе придется убедить Кретея помочь тебе в поисках.$B$BТам повсюду рыщут железные дворфы, явно что-то ищут... может быть, даже и ядро. Они забрали мое кольцо. Разыщи их предводителя, забери у него кольцо и покажи его Кретею, чтобы он убедился, что тебя прислал я.','Заберите у наблюдателя железных дворфов перстень-печатку Ледохвата и покажите его Кретею в Подножии.','Кольцо Дрома? Как я понимаю, дела у него идут неважно, раз уж он не смог представить тебя лично. Это печально. Дром – благороднейший из дворфов, хотя и чересчур любопытный.$B$BКак я понимаю, у тебя ко мне дело?','Вернитесь к Кретею в Подножие, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Одинокий часовой',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я так и не нашел ядро... но я часто беседовал с часовым Кретеем и по его оговоркам понял, что он что-то знает. Ты найдешь Кретея в горах на востоке, в Подножии, где он наблюдает за Машиной Творцов. Вполне вероятно, что ядро находится где-то там, но тебе придется убедить Кретея помочь тебе в поисках.$B$BТам повсюду рыщут железные дворфы, явно что-то ищут... может быть, даже и ядро. Они забрали мое кольцо. Разыщи их предводителя, забери у него кольцо и покажи его Кретею, чтобы он убедился, что тебя прислал я.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заберите у наблюдателя железных дворфов перстень-печатку Ледохвата и покажите его Кретею в Подножии.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Кольцо Дрома? Как я понимаю, дела у него идут неважно, раз уж он не смог представить тебя лично. Это печально. Дром – благороднейший из дворфов, хотя и чересчур любопытный.$B$BКак я понимаю, у тебя ко мне дело?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кретею в Подножие, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (12878,'Спрятанная реликвия','Пока тебя не было, мне довелось пообщаться с дворфом по имени Бранн Бронзобород. Он сказал мне, что ищет краеугольный камень, и намерения у него, как я понял, самые благие. Думаю, что камень-ключ именно для этого дворфа и был изготовлен.$B$BЯдро Норганнона спрятано в Стылом склепе на юго-востоке отсюда. Его охраняют древние существа, сделанные изо льда, и они не обрадуются твоему приходу. Забери краеугольный камень, и да пребудет с тобой удача, |3-6($r).','Найдите ядро Норганнона, руководствуясь информацией, которую дал Кретей в Подножии.','<Сундук открывается, и из него вырывается заплесневелый запах – запах седой старины. На дне сундука лежит ядро Норганнона, совершенно целехонькое.>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спрятанная реликвия',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пока тебя не было, мне довелось пообщаться с дворфом по имени Бранн Бронзобород. Он сказал мне, что ищет краеугольный камень, и намерения у него, как я понял, самые благие. Думаю, что камень-ключ именно для этого дворфа и был изготовлен.$B$BЯдро Норганнона спрятано в Стылом склепе на юго-востоке отсюда. Его охраняют древние существа, сделанные изо льда, и они не обрадуются твоему приходу. Забери краеугольный камень, и да пребудет с тобой удача, |3-6($r).',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите ядро Норганнона, руководствуясь информацией, которую дал Кретей в Подножии.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Сундук открывается, и из него вырывается заплесневелый запах – запах седой старины. На дне сундука лежит ядро Норганнона, совершенно целехонькое.>',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (12879,'Ярость короля Зиморожденных','<Вы достаете ядро из сундука, и внезапно слышите тяжелые шаги в коридоре. Также до вас доносится едва различимый грохот битвы, идущей где-то вдалеке.>','Отнесите ядро Норганнона Кретею в Подножие.','Кто-то использует Кузню Воли для создания этого войска... В Ульдуаре стало небезопасно.$B$BХорошо, что тебе удалось опередить этих поганищ и забрать ядро первым.','Вернитесь к Кретею в Подножие, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ярость короля Зиморожденных',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Вы достаете ядро из сундука, и внезапно слышите тяжелые шаги в коридоре. Также до вас доносится едва различимый грохот битвы, идущей где-то вдалеке.>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите ядро Норганнона Кретею в Подножие.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Кто-то использует Кузню Воли для создания этого войска... В Ульдуаре стало небезопасно.$B$BХорошо, что тебе удалось опередить этих поганищ и забрать ядро первым.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кретею в Подножие, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (12880,'Главный исследователь','Для того чтобы собрать краеугольный камень, нам понадобятся узы Норганнона, устройство, которое находится в Машине Творцов, в большой шахте неподалеку отсюда. Бранн уже должен быть там, со второй половиной камня-ключа. Я сказал ему, чтобы он использовал это устройство. Он ждет тебя.$B$BЯ постараюсь сдержать железных дворфов, чтобы дать вам время. Но я сомневаюсь, что смогу их удерживать долго. Скоро король Грозовое Сердце со своими людьми снова возьмется за оборону Ледяной Крепости. Так что поторопись, |3-6($r).','Отнесите ядро Норганнона Бранну Бронзобороду к Машине Творцов.','Вернитесь к Бранну Бронзобороду в Машину Творцов, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Главный исследователь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Для того чтобы собрать краеугольный камень, нам понадобятся узы Норганнона, устройство, которое находится в Машине Творцов, в большой шахте неподалеку отсюда. Бранн уже должен быть там, со второй половиной камня-ключа. Я сказал ему, чтобы он использовал это устройство. Он ждет тебя.$B$BЯ постараюсь сдержать железных дворфов, чтобы дать вам время. Но я сомневаюсь, что смогу их удерживать долго. Скоро король Грозовое Сердце со своими людьми снова возьмется за оборону Ледяной Крепости. Так что поторопись, |3-6($r).',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите ядро Норганнона Бранну Бронзобороду к Машине Творцов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бранну Бронзобороду в Машину Творцов, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (12881,'Братья Бронзобороды') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Братья Бронзобороды',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12882,'Древние реликвии','Добро пожаловать на гряду.$B$BУ меня есть к тебе одна простая просьба, прежде чем ты отправишься в свое запланированное грандиозное путешествие. По этим горам разбросаны реликвии и сокровища древнего Ульдуара. Большинство из них, скорее всего, попали в руки представителей различных разумных рас.$B$BПринеси мне то, что тебе удастся найти, и я щедро вознагражу тебя. Может, я даже дам тебе отведать какого-нибудь из своих многочисленных и отменных напитков!','Отнесите 10 реликвий Ульдуара Олуту Пивобрюху на место крушения Гром\'арша.','О, эти отлично подойдут! Весьма признателен! Не хочешь горло прополоскать после тяжких трудов?','Тебе удалось обнаружить реликвии, о которых я говорил?','Вернитесь к Олуту Пивобрюху на место крушения Гром\'арша, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Древние реликвии',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Добро пожаловать на гряду.$B$BУ меня есть к тебе одна простая просьба, прежде чем ты отправишься в свое запланированное грандиозное путешествие. По этим горам разбросаны реликвии и сокровища древнего Ульдуара. Большинство из них, скорее всего, попали в руки представителей различных разумных рас.$B$BПринеси мне то, что тебе удастся найти, и я щедро вознагражу тебя. Может, я даже дам тебе отведать какого-нибудь из своих многочисленных и отменных напитков!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите 10 реликвий Ульдуара Олуту Пивобрюху на место крушения Гром\'арша.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, эти отлично подойдут! Весьма признателен! Не хочешь горло прополоскать после тяжких трудов?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось обнаружить реликвии, о которых я говорил?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Олуту Пивобрюху на место крушения Гром\'арша, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12883,'Приказы Дракуру','Говоришь, Дракуру? Да, я слышал это имя...','Вернитесь к главе рыцарей Лантинге в Разлом Света, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приказы Дракуру',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Говоришь, Дракуру? Да, я слышал это имя...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к главе рыцарей Лантинге в Разлом Света, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (12884,'Черная застава','Отнесите приказы Дракуру Стефану Ваду на Черную Заставу в Зул\'Драке.','Поговорите с Стефаном Ваду на Черной заставе, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Черная застава',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите приказы Дракуру Стефану Ваду на Черную Заставу в Зул\'Драке.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Стефаном Ваду на Черной заставе, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (12885,'Изгнанники Ульдуара','Значит, ты знаешь Бранна Бронзоборода? Это наш самый верный союзник из всех, кто создан из плоти и крови. Мы с ним как братья в нашей общей борьбе против Локена и его приспешников, в борьбе за Ульдуар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Изгнанники Ульдуара',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Значит, ты знаешь Бранна Бронзоборода? Это наш самый верный союзник из всех, кто создан из плоти и крови. Мы с ним как братья в нашей общей борьбе против Локена и его приспешников, в борьбе за Ульдуар.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12886,'Драконобойца','Ну, вот. Ты прошла почти все испытания Круга хильд... осталось только одно, последнее...$B$BДраконобойца – это последнее, самое трудное испытание силы духа и воинской доблести хильд. У тебя будет только твой верховой дракон, гарпун и твое собственное мужество, и тебе нужно будет сразиться в нескольких поединках с нашими сестрами, лучшими из воительниц.$B$BБорьба будет жестокой. Не давай никому пощады и не жди ее ни от кого.','Воспользуйтесь хильдским гарпуном, чтобы победить 10 наездниц на драконе Круга хильд в Храме Штормов.','Сиф... это ты?','Прочь!','Запустите хильдский гарпун в украшение на колонне, чтобы закончить испытание драконобойцы. Вернитесь к Ториму в Храм Штормов, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Драконобойца',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну, вот. Ты прошла почти все испытания Круга хильд... осталось только одно, последнее...$B$BДраконобойца – это последнее, самое трудное испытание силы духа и воинской доблести хильд. У тебя будет только твой верховой дракон, гарпун и твое собственное мужество, и тебе нужно будет сразиться в нескольких поединках с нашими сестрами, лучшими из воительниц.$B$BБорьба будет жестокой. Не давай никому пощады и не жди ее ни от кого.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь хильдским гарпуном, чтобы победить 10 наездниц на драконе Круга хильд в Храме Штормов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сиф... это ты?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Прочь!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Запустите хильдский гарпун в украшение на колонне, чтобы закончить испытание драконобойцы. Вернитесь к Ториму в Храм Штормов, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12887,'Непростая работа','Рыцари Черного Клинка хотят захватить базу Плети, известную как Мрачный Cвод, на северо-западе отсюда. У меня есть доверенный человек в их отряде, и он просит помощи.$B$BПерво-наперво следует "ослепить" Короля-лича. У него есть Глаз – аппарат для наблюдения, который парит в небе над шпилями свода.$B$BНаши дворфы собрали одно устройство, которое можно использовать против него. Когда Глаз будет уничтожен, разыщи барона Раздора на территории свода. Он притворяется, что по-прежнему послушен воле Короля-лича.','Уничтожьте Глаз и переговорите с бароном Раздором в Мрачном Своде.','Теперь у нас, может быть, и получится что-то сделать. Только не обольщайся. Король-лич по-прежнему "наблюдает" за нами через приспешников Плети.$B$BСобственно, поэтому тебя и прислали сюда.','Окуляр все еще стоит! Тассариан был дураком, если доверял тебе.$B$BНе возвращайся пока он не будет уничтожен. Моя позиция не должна быть скомпрометирована!','Вернитесь к барону Раздору в Мрачный Свод, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Непростая работа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Рыцари Черного Клинка хотят захватить базу Плети, известную как Мрачный Cвод, на северо-западе отсюда. У меня есть доверенный человек в их отряде, и он просит помощи.$B$BПерво-наперво следует "ослепить" Короля-лича. У него есть Глаз – аппарат для наблюдения, который парит в небе над шпилями свода.$B$BНаши дворфы собрали одно устройство, которое можно использовать против него. Когда Глаз будет уничтожен, разыщи барона Раздора на территории свода. Он притворяется, что по-прежнему послушен воле Короля-лича.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте Глаз и переговорите с бароном Раздором в Мрачном Своде.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь у нас, может быть, и получится что-то сделать. Только не обольщайся. Король-лич по-прежнему "наблюдает" за нами через приспешников Плети.$B$BСобственно, поэтому тебя и прислали сюда.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Окуляр все еще стоит! Тассариан был дураком, если доверял тебе.$B$BНе возвращайся пока он не будет уничтожен. Моя позиция не должна быть скомпрометирована!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к барону Раздору в Мрачный Свод, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12888,'УБЕР-И','Эта карта дает доступ к пульту управления хламоботом под названием УБЕР-И, чтобы осуществлять техническую поддержку и при необходимости перепрограммировать команды, отдаваемые машине.$B$BУБЕР-И, насколько известно, находится в здании Библиотеки Изобретателя. На карте представлен список сломанных комплектующих хламобота и нерабочих систем. Если заменить необходимые детали, агрегат можно отремонтировать и привести в рабочее состояние.','Принесите в Библиотеку Изобретателя карту доступа к УБЕР-И, 4 пригоршни кобальтовых болтов и 5 перегруженных конденсаторов и попробуйте починить УБЕР-И.','<Сверяясь с картой доступа, вы принимаетесь за ремонт. Когда вы заканчиваете с ремонтом, вы закрываете панель доступа и включаете питание.>','<Вы открываете панель доступа УБЕР-И.>','Вернитесь к Убер-И в Библиотеку Изобретателя, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','УБЕР-И',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эта карта дает доступ к пульту управления хламоботом под названием УБЕР-И, чтобы осуществлять техническую поддержку и при необходимости перепрограммировать команды, отдаваемые машине.$B$BУБЕР-И, насколько известно, находится в здании Библиотеки Изобретателя. На карте представлен список сломанных комплектующих хламобота и нерабочих систем. Если заменить необходимые детали, агрегат можно отремонтировать и привести в рабочее состояние.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите в Библиотеку Изобретателя карту доступа к УБЕР-И, 4 пригоршни кобальтовых болтов и 5 перегруженных конденсаторов и попробуйте починить УБЕР-И.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Сверяясь с картой доступа, вы принимаетесь за ремонт. Когда вы заканчиваете с ремонтом, вы закрываете панель доступа и включаете питание.>',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Вы открываете панель доступа УБЕР-И.>',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Убер-И в Библиотеку Изобретателя, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (12889,'Панель управления прототипом','Наименование: УБЕР-И.$B$BРаспоряжение: поддерживать работоспособность панелей управления и баз данных Библиотеки Изобретателя в отсутствие Хранителя Мимира.$B$BВремя, прошедшее с последнего цикла технического обслуживания: 489 дней.$B$BСтатус данных о проектируемой схеме: неизвестен.$B$BТекущая задача: ремонт панели управления прототипом.','Попробуйте разобраться с панелью управления прототипом в Библиотеке Изобретателя.','Вы рассматриваете дисплей на панели управления прототипом. Похоже, что как минимум одна схема Мимира "пережила" затяжной перерыв между циклами технического обслуживания. По диаграммам и инструкциям, представленным в файле схемы, вы без труда сконструируете механогнома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Панель управления прототипом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наименование: УБЕР-И.$B$BРаспоряжение: поддерживать работоспособность панелей управления и баз данных Библиотеки Изобретателя в отсутствие Хранителя Мимира.$B$BВремя, прошедшее с последнего цикла технического обслуживания: 489 дней.$B$BСтатус данных о проектируемой схеме: неизвестен.$B$BТекущая задача: ремонт панели управления прототипом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Попробуйте разобраться с панелью управления прототипом в Библиотеке Изобретателя.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы рассматриваете дисплей на панели управления прототипом. Похоже, что как минимум одна схема Мимира "пережила" затяжной перерыв между циклами технического обслуживания. По диаграммам и инструкциям, представленным в файле схемы, вы без труда сконструируете механогнома.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (12890,'Если размер имеет значение...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Если размер имеет значение...',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12891,'Воплощение идеи','Когда я прислуживал... э... состоял на службе у Короля-лича, мы часто использовали устройство под названием скипетр повеления, чтобы держать в узде шибко умных рабов Плети.$B$BЕсли ты мне поможешь, я сделаю тебе точно такой же скипетр.$B$BМожно сказать, что тебе повезло. Все необходимые компоненты у нас под рукой: скипетр сектанта, крюк поганища, веревка упыря и вдоволь эссенций Плети.$B$BЭто будет нетрудно, |3-6($c).','Принесите скипетр сектанта, крюк поганища, веревку упыря и 5 эссенций Плети барону Раздору в Мрачный Свод.','Быстрее, давай их сюда и отойди подальше, чтобы мне не мешать!$B$BПалка, крючок и веревка – их назначение, когда они вместе, вполне очевидно. Надо лишь пропитать их эссенциями, и тогда у нас будет очень полезное устройство.$B$BВещь, самая обыкновенная с виду, однако необыкновенная в употреблении!','Когда ты соберешь все необходимые компоненты, я смогу сделать скипетр повеления, только с некоторыми изменениями, потребными для наших целей, и мы перейдем к исполнению нашего плана.','Вернитесь к барону Раздору в Мрачный Свод, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Воплощение идеи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда я прислуживал... э... состоял на службе у Короля-лича, мы часто использовали устройство под названием скипетр повеления, чтобы держать в узде шибко умных рабов Плети.$B$BЕсли ты мне поможешь, я сделаю тебе точно такой же скипетр.$B$BМожно сказать, что тебе повезло. Все необходимые компоненты у нас под рукой: скипетр сектанта, крюк поганища, веревка упыря и вдоволь эссенций Плети.$B$BЭто будет нетрудно, |3-6($c).',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите скипетр сектанта, крюк поганища, веревку упыря и 5 эссенций Плети барону Раздору в Мрачный Свод.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Быстрее, давай их сюда и отойди подальше, чтобы мне не мешать!$B$BПалка, крючок и веревка – их назначение, когда они вместе, вполне очевидно. Надо лишь пропитать их эссенциями, и тогда у нас будет очень полезное устройство.$B$BВещь, самая обыкновенная с виду, однако необыкновенная в употреблении!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Когда ты соберешь все необходимые компоненты, я смогу сделать скипетр повеления, только с некоторыми изменениями, потребными для наших целей, и мы перейдем к исполнению нашего плана.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к барону Раздору в Мрачный Свод, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12892,'Непростая работа','Рыцари Черного Клинка хотят захватить базу Плети, известную как Мрачный Cвод, на северо-западе отсюда. У меня есть доверенный человек в их отряде, и он просит помощи.$B$BПерво-наперво следует "ослепить" Короля-лича. У него есть Глаз – аппарат для наблюдения, который парит в небе над шпилями свода.$B$BНаши гоблины собрали одно устройство, которое можно использовать против него. Когда Глаз будет уничтожен, разыщи барона Раздора на территории свода. Он притворяется, что по-прежнему послушен воле Короля-лича.','Уничтожьте Глаз и переговорите с бароном Раздором в Мрачном Своде.','Окуляр все еще стоит! Колтира был дураком, если доверял тебе.$B$BНе возвращайся пока он не будет уничтожен. Моя позиция не должна быть скомпрометирована!','Вернитесь к барону Раздору в Мрачный Свод, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Непростая работа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Рыцари Черного Клинка хотят захватить базу Плети, известную как Мрачный Cвод, на северо-западе отсюда. У меня есть доверенный человек в их отряде, и он просит помощи.$B$BПерво-наперво следует "ослепить" Короля-лича. У него есть Глаз – аппарат для наблюдения, который парит в небе над шпилями свода.$B$BНаши гоблины собрали одно устройство, которое можно использовать против него. Когда Глаз будет уничтожен, разыщи барона Раздора на территории свода. Он притворяется, что по-прежнему послушен воле Короля-лича.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте Глаз и переговорите с бароном Раздором в Мрачном Своде.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Окуляр все еще стоит! Колтира был дураком, если доверял тебе.$B$BНе возвращайся пока он не будет уничтожен. Моя позиция не должна быть скомпрометирована!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к барону Раздору в Мрачный Свод, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12893,'Освобождение разума','Злоб, леди Найтсвуд и Прыгун могут стать мощным оружием в борьбе против Короля-лича, если освободить их от его влияния. А для этого у нас есть скипетр повеления.$B$BТы найдешь их на балконах к востоку и западу от склепа, а также на среднем ярусе склепа над нами. Скипетром нужно подействовать на всех троих.$B$BЛети. Нам надо переманить их на свою сторону!','Подействуйте скипетром повеления на тела Злоба, леди Найтсвуд и Прыгуна, а потом возвращайтесь к барону Раздору в Мрачный Свод.','Эти трое нам пригодятся, когда мы наконец захватим склеп.$B$BКстати, о склепе...','Ты еще не $Gпревратил:превратила; их. Не оскорбляй мой интеллект, $C!','Вернитесь к барону Раздору в Мрачный Свод, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Освобождение разума',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Злоб, леди Найтсвуд и Прыгун могут стать мощным оружием в борьбе против Короля-лича, если освободить их от его влияния. А для этого у нас есть скипетр повеления.$B$BТы найдешь их на балконах к востоку и западу от склепа, а также на среднем ярусе склепа над нами. Скипетром нужно подействовать на всех троих.$B$BЛети. Нам надо переманить их на свою сторону!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Подействуйте скипетром повеления на тела Злоба, леди Найтсвуд и Прыгуна, а потом возвращайтесь к барону Раздору в Мрачный Свод.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Эти трое нам пригодятся, когда мы наконец захватим склеп.$B$BКстати, о склепе...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты еще не $Gпревратил:превратила; их. Не оскорбляй мой интеллект, $C!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к барону Раздору в Мрачный Свод, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (12894,'Передовой лагерь рыцарей','Рыцарь Даргат, рыцарь Маккеллар, инженер Рид и близнецы Герк и Бурр, отправились на Мертвые поля, чтобы разбить лагерь на передовой. В их последнем донесении сказано, что они благополучно разбили лагерь на границе Мертвых полей, к северо-западу отсюда.$B$BВ свете того, что нам стало известно о Дракуру и принце Навариусе, думаю, нам нужно срочно послать кого-нибудь в Передовой лагерь рыцарей.$B$BСобирай вещи, $n. Ты выходишь немедленно!','Разыщите рыцаря Маккеллара в Передовом лагере рыцарей в Зул\'Драке.','Все было отлично, пока нас не атаковали воины Плети. Они захватили Даргата, Герка и Бурра и уничтожили наше средство передвижения. Угадай, кто был их предводителем?$B$B<Маккеллар кивает.>$B$BНавариус...$B$BПохоже, весь этот край превратился в одну большую фабрику для сил Плети. И мы находимся посреди открытой разработки сырья для этой проклятой армии нежити!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Передовой лагерь рыцарей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Рыцарь Даргат, рыцарь Маккеллар, инженер Рид и близнецы Герк и Бурр, отправились на Мертвые поля, чтобы разбить лагерь на передовой. В их последнем донесении сказано, что они благополучно разбили лагерь на границе Мертвых полей, к северо-западу отсюда.$B$BВ свете того, что нам стало известно о Дракуру и принце Навариусе, думаю, нам нужно срочно послать кого-нибудь в Передовой лагерь рыцарей.$B$BСобирай вещи, $n. Ты выходишь немедленно!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите рыцаря Маккеллара в Передовом лагере рыцарей в Зул\'Драке.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Все было отлично, пока нас не атаковали воины Плети. Они захватили Даргата, Герка и Бурра и уничтожили наше средство передвижения. Угадай, кто был их предводителем?$B$B<Маккеллар кивает.>$B$BНавариус...$B$BПохоже, весь этот край превратился в одну большую фабрику для сил Плети. И мы находимся посреди открытой разработки сырья для этой проклятой армии нежити!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (12895,'Пропавший Бронзобород','Заберите завернутую в мешковину записку из лагеря Бранна и возвращайтесь к Боктару Кровавому Безумию на место крушения Гром\'арша.','Вернитесь к Боктару Кровавому Безумию на место крушения Гром\'арша, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пропавший Бронзобород',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заберите завернутую в мешковину записку из лагеря Бранна и возвращайтесь к Боктару Кровавому Безумию на место крушения Гром\'арша.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Боктару Кровавому Безумию на место крушения Гром\'арша, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12896,'Последний аргумент','Рыцарей смерти, таких, как генерал Погибель Света, держат на слишком коротком поводке, и убедить их пойти против воли Короля-лича практически невозможно. Разве что представится исключительный случай.$B$BГенерал почти не выходит из Свода – следит за изготовлением нового оружия. Но если ты опрокинешь одну из его оружейных стоек в кузнице, тогда он точно придет, можешь не сомневаться. Я пошлю тебе в помощь Злоба, леди Найтсвуд и Прыгуна.$B$BМрачный Свод должен стать нашим, но для этого нам необходимо ликвидировать генерала Погибель Света!','Убейте генерала Погибель Света и доложите об исполнении Тассариану на борту "Усмирителя небес".','Генерал Погибель Света уничтожен, и его войско разбито? Мрачный Свод взят?','Я спрашиваю тебя, $N, зачем нам опять говорить, если генерал еще жив?','Вернитесь к Тассариану на "Усмиритель небес", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Последний аргумент',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Рыцарей смерти, таких, как генерал Погибель Света, держат на слишком коротком поводке, и убедить их пойти против воли Короля-лича практически невозможно. Разве что представится исключительный случай.$B$BГенерал почти не выходит из Свода – следит за изготовлением нового оружия. Но если ты опрокинешь одну из его оружейных стоек в кузнице, тогда он точно придет, можешь не сомневаться. Я пошлю тебе в помощь Злоба, леди Найтсвуд и Прыгуна.$B$BМрачный Свод должен стать нашим, но для этого нам необходимо ликвидировать генерала Погибель Света!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте генерала Погибель Света и доложите об исполнении Тассариану на борту "Усмирителя небес".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Генерал Погибель Света уничтожен, и его войско разбито? Мрачный Свод взят?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я спрашиваю тебя, $N, зачем нам опять говорить, если генерал еще жив?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тассариану на "Усмиритель небес", что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (12897,'Последний аргумент','Рыцарей смерти, таких, как генерал Погибель Света, держат на слишком коротком поводке, и убедить их пойти против воли Короля-лича практически невозможно. Разве что представится исключительный случай.$B$BГенерал почти не выходит из Свода – следит за изготовлением нового оружия. Но если ты опрокинешь одну из его оружейных стоек в кузнице, тогда он точно придет, можешь не сомневаться. Я пошлю тебе в помощь Злоба, леди Найтсвуд и Прыгуна.$B$BМрачный Свод должен стать нашим, но для этого нам необходимо ликвидировать генерала Погибель Света!','Убейте генерала Погибель Света и доложите об исполнении Кольтире Ткачу Смерти на борту "Молота Оргрима".','Вернитесь к Кольтире Ткачу Смерти на "Молот Оргрима", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Последний аргумент',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Рыцарей смерти, таких, как генерал Погибель Света, держат на слишком коротком поводке, и убедить их пойти против воли Короля-лича практически невозможно. Разве что представится исключительный случай.$B$BГенерал почти не выходит из Свода – следит за изготовлением нового оружия. Но если ты опрокинешь одну из его оружейных стоек в кузнице, тогда он точно придет, можешь не сомневаться. Я пошлю тебе в помощь Злоба, леди Найтсвуд и Прыгуна.$B$BМрачный Свод должен стать нашим, но для этого нам необходимо ликвидировать генерала Погибель Света!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте генерала Погибель Света и доложите об исполнении Кольтире Ткачу Смерти на борту "Молота Оргрима".',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кольтире Ткачу Смерти на "Молот Оргрима", что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (12898,'Мрачный Свод','Как я понимаю, ты замечательно $gсправился:справилась;. И при этом еще $gпривлек:привлекла; трех очень нужных союзников на сторону рыцарей Черного Клинка.$B$B<Тассариан смотрит куда-то за горизонт.>$B$BТебе надо скорее возвращаться обратно. Барон Раздор и другие рыцари смерти сейчас сражаются с силами Плети, чтобы удержать Мрачный свод.$B$BЯ думаю, им понадобится твоя помощь.','Поговорите с бароном Раздором в Мрачном Своде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мрачный Свод',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как я понимаю, ты замечательно $gсправился:справилась;. И при этом еще $gпривлек:привлекла; трех очень нужных союзников на сторону рыцарей Черного Клинка.$B$B<Тассариан смотрит куда-то за горизонт.>$B$BТебе надо скорее возвращаться обратно. Барон Раздор и другие рыцари смерти сейчас сражаются с силами Плети, чтобы удержать Мрачный свод.$B$BЯ думаю, им понадобится твоя помощь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с бароном Раздором в Мрачном Своде.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (12899,'Мрачный Свод','Как я понимаю, ты замечательно $gсправился:справилась;. И при этом еще $gпривлек:привлекла; трех очень нужных союзников на сторону рыцарей Черного Клинка.$B$B<Кольтира смотрит на карту на полу.>$B$BТебе надо скорее возвращаться обратно. Барон Раздор и другие рыцари смерти сейчас сражаются с силами Плети, чтобы удержать Мрачный Свод.$B$BЯ думаю, им понадобится твоя помощь.','Поговорите с бароном Раздором в Мрачном Своде.','Ты молодец, что вернулся. Как видишь, у нас тут на счету каждый боец.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мрачный Свод',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как я понимаю, ты замечательно $gсправился:справилась;. И при этом еще $gпривлек:привлекла; трех очень нужных союзников на сторону рыцарей Черного Клинка.$B$B<Кольтира смотрит на карту на полу.>$B$BТебе надо скорее возвращаться обратно. Барон Раздор и другие рыцари смерти сейчас сражаются с силами Плети, чтобы удержать Мрачный Свод.$B$BЯ думаю, им понадобится твоя помощь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с бароном Раздором в Мрачном Своде.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты молодец, что вернулся. Как видишь, у нас тут на счету каждый боец.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12900,'Изготовление сбруи','Так ты хочешь ездить верхом? Ну, что же... пока что ты проявляешь себя достойно, и вполне можно дать тебе шанс испытать себя и в этом деле.$B$BЗначит, тебе нужна сбруя.$B$BВ горах на юге водятся йети. У них крепкая шкура как раз подходящей толщины. Принеси мне их шкуры, мы изготовим тебе упряжь, и ты сможешь попробовать научиться ездить на медведях.','По заданию Астрид Бьорнриттар из деревни Бруннхильдар раздобудьте 3 шкуры ледогривых йети.','Да, эти сгодятся. Я тебе в два счета сбрую сделаю!','Ты уже добыла шкуры? Ты найдешь йети внизу, в горах.','Вернитесь к Астрид Бьорнриттар в деревню Бруннхильдар, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Изготовление сбруи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Так ты хочешь ездить верхом? Ну, что же... пока что ты проявляешь себя достойно, и вполне можно дать тебе шанс испытать себя и в этом деле.$B$BЗначит, тебе нужна сбруя.$B$BВ горах на юге водятся йети. У них крепкая шкура как раз подходящей толщины. Принеси мне их шкуры, мы изготовим тебе упряжь, и ты сможешь попробовать научиться ездить на медведях.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По заданию Астрид Бьорнриттар из деревни Бруннхильдар раздобудьте 3 шкуры ледогривых йети.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, эти сгодятся. Я тебе в два счета сбрую сделаю!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты уже добыла шкуры? Ты найдешь йети внизу, в горах.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Астрид Бьорнриттар в деревню Бруннхильдар, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (12901,'Что-то из ничего','Принца Навариуса надо остановить. Нельзя допустить, чтобы Плеть и дальше использовала эти земли как фабрику зомби. Но если мы не сможем запустить танк, шансов у нас нет. Нужны запчасти.$B$BК северо-западу отсюда есть одно место, Тупик Трыма. У армии Плети там что-то вроде перевалочной базы. По всей базе разбросаны обломки металла. Собери их и принеси мне, а уж я попытаюсь найти им применение.','Это просто негодный металлолом?! Проклятье! Железо Плети нам не подходит. Что будем делать?','Вернитесь к инженеру Риду в Передовой лагерь рыцарей, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Что-то из ничего',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Принца Навариуса надо остановить. Нельзя допустить, чтобы Плеть и дальше использовала эти земли как фабрику зомби. Но если мы не сможем запустить танк, шансов у нас нет. Нужны запчасти.$B$BК северо-западу отсюда есть одно место, Тупик Трыма. У армии Плети там что-то вроде перевалочной базы. По всей базе разбросаны обломки металла. Собери их и принеси мне, а уж я попытаюсь найти им применение.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это просто негодный металлолом?! Проклятье! Железо Плети нам не подходит. Что будем делать?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к инженеру Риду в Передовой лагерь рыцарей, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (12902,'Кто за этим стоит?','Бедняги! Они единственные, кто уцелели.$B$BПо словам их предводителя, тролли Драккари и волчеры Яростного Когтя были союзниками на протяжении нескольких тысячелетий. Они жили здесь с давних времен бок о бок с троллями и даже не знали, что происходит в окружающем мире – в мире, который постоянно меняется. Для волчеров Яростного Когтя тролль – всегда тролль, и когда тролли напали на их логово, это стало для них неприятным сюрпризом. Они просто не ждали такого предательства.$B$BНам хотелось бы знать, кто за этим стоит. Кто натравил троллей на волчеров? Иди в их деревню, $n, – она на юго-востоке отсюда – и попытайся найти ответ.','Обыщите логово Яростного Когтя и попытайтесь узнать, кто был зачинщиком атаки на волчеров Яростного Когтя.','Вы подходите к странному алтарю, над которым парит в воздухе какой-то свиток. Наверное, это именно то, что искал глава рыцарей Лантинга!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кто за этим стоит?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Бедняги! Они единственные, кто уцелели.$B$BПо словам их предводителя, тролли Драккари и волчеры Яростного Когтя были союзниками на протяжении нескольких тысячелетий. Они жили здесь с давних времен бок о бок с троллями и даже не знали, что происходит в окружающем мире – в мире, который постоянно меняется. Для волчеров Яростного Когтя тролль – всегда тролль, и когда тролли напали на их логово, это стало для них неприятным сюрпризом. Они просто не ждали такого предательства.$B$BНам хотелось бы знать, кто за этим стоит. Кто натравил троллей на волчеров? Иди в их деревню, $n, – она на юго-востоке отсюда – и попытайся найти ответ.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обыщите логово Яростного Когтя и попытайтесь узнать, кто был зачинщиком атаки на волчеров Яростного Когтя.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы подходите к странному алтарю, над которым парит в воздухе какой-то свиток. Наверное, это именно то, что искал глава рыцарей Лантинга!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (12903,'Для того и нужны друзья...','На нас напал принц Навариус и не менее дюжины воинов Плети. Я приказал Даргату и близнецам оставаться в танке, но они не послушались. Даргат посмотрел мне в глаза и сказал: "Если кто-нибудь не выйдет из этого танка, мы все погибнем". Потом он велел Риду вырубить двигатель и пошел в атаку. Я в жизни не видел такого героизма.$B$BЯ слышал, как принц отдает команды своим чудовищам. Насколько я понял, они направились к Тупику Трыма, на северо-запад. Нужно спасти наших друзей. Ты нам поможешь?','Разыщите рыцаря Даргата, Герка и Бурра по просьбе рыцаря Маккеллара из Передового лагеря рыцарей.','Эти трое пожертвовали собой, и их великая жертва не будет забыта. Их смерть не будет напрасной. Мы победим!','Вернитесь к рыцарю Маккеллару в Передовой лагерь рыцарей, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Для того и нужны друзья...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На нас напал принц Навариус и не менее дюжины воинов Плети. Я приказал Даргату и близнецам оставаться в танке, но они не послушались. Даргат посмотрел мне в глаза и сказал: "Если кто-нибудь не выйдет из этого танка, мы все погибнем". Потом он велел Риду вырубить двигатель и пошел в атаку. Я в жизни не видел такого героизма.$B$BЯ слышал, как принц отдает команды своим чудовищам. Насколько я понял, они направились к Тупику Трыма, на северо-запад. Нужно спасти наших друзей. Ты нам поможешь?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите рыцаря Даргата, Герка и Бурра по просьбе рыцаря Маккеллара из Передового лагеря рыцарей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Эти трое пожертвовали собой, и их великая жертва не будет забыта. Их смерть не будет напрасной. Мы победим!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к рыцарю Маккеллару в Передовой лагерь рыцарей, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12904,'Орудие мести','Они... Они убили моего брата.$B$B<Герк с трудом сдерживает слезы.>$B$BЗабили его, словно зверя. А теперь его тело лежит на столе на другом конце лагеря... и над ним будут ставить какие-то жуткие эксперименты. И Даргат тоже мертв. Паладин героически сражался на древних развалинах, что на северо-востоке, но вождь варгулов, Алгар, оказался сильнее.$B$BОстался лишь я, я один, и меня тоже скоро не станет. Я... я уже превращаюсь.$B$BЕсли Свет не дал мне возможности отомстить, может, ты станешь орудием мести, |3-6($c). Убей их всех.','Ты делаешь миру одолжение, друг. Этих монстров нужно остановить!','Вернитесь к Герку в Тупик Трыма, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Орудие мести',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Они... Они убили моего брата.$B$B<Герк с трудом сдерживает слезы.>$B$BЗабили его, словно зверя. А теперь его тело лежит на столе на другом конце лагеря... и над ним будут ставить какие-то жуткие эксперименты. И Даргат тоже мертв. Паладин героически сражался на древних развалинах, что на северо-востоке, но вождь варгулов, Алгар, оказался сильнее.$B$BОстался лишь я, я один, и меня тоже скоро не станет. Я... я уже превращаюсь.$B$BЕсли Свет не дал мне возможности отомстить, может, ты станешь орудием мести, |3-6($c). Убей их всех.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты делаешь миру одолжение, друг. Этих монстров нужно остановить!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Герку в Тупик Трыма, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (12905,'Милдред Жестокая','Значит, мы договорились, $n. Ты меня освободишь, а я помогу тебе разыскать твоего зеленого друга.$B$BХильда, которая управляет шахтой, зовется Милдред Жестокая – и на то есть причины.$B$BСкажи ей, что тебя прислали ей в помощь. Делай все, что она говорит, пока не завоюешь ее доверие и она не отдаст тебе ключи от моих кандалов.','Поговорите с Милдред Жестокой в Заброшенном руднике.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Милдред Жестокая',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Значит, мы договорились, $n. Ты меня освободишь, а я помогу тебе разыскать твоего зеленого друга.$B$BХильда, которая управляет шахтой, зовется Милдред Жестокая – и на то есть причины.$B$BСкажи ей, что тебя прислали ей в помощь. Делай все, что она говорит, пока не завоюешь ее доверие и она не отдаст тебе ключи от моих кандалов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Милдред Жестокой в Заброшенном руднике.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (12906,'Дисциплинирование','Для начала я дам тебе очень простое задание. Мужчины-врайкулы, которые работают на наших рудниках, работают на нас против воли, исключительно из страха перед нашими клинками.$B$BНо иной раз случается, что кто-то из них забывает о том, кто здесь главный. Разыщи всех забывшихся врайкулов и поставь их на место.$B$BВозьми этот вразумляющий жезл. Не надо их убивать. Надо просто сделать им очень больно. Обычно этого бывает достаточно... хотя и не всегда.','По заданию Милдред Жестокой из Заброшенного рудника накажите 6 обессиленных врайкулов с помощью вразумляющего жезла.','Для новенькой – очень даже неплохо. У меня есть еще одно поручение для тебя.','Вернитесь к Милдред Жестокой в Заброшенный рудник, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дисциплинирование',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Для начала я дам тебе очень простое задание. Мужчины-врайкулы, которые работают на наших рудниках, работают на нас против воли, исключительно из страха перед нашими клинками.$B$BНо иной раз случается, что кто-то из них забывает о том, кто здесь главный. Разыщи всех забывшихся врайкулов и поставь их на место.$B$BВозьми этот вразумляющий жезл. Не надо их убивать. Надо просто сделать им очень больно. Обычно этого бывает достаточно... хотя и не всегда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По заданию Милдред Жестокой из Заброшенного рудника накажите 6 обессиленных врайкулов с помощью вразумляющего жезла.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Для новенькой – очень даже неплохо. У меня есть еще одно поручение для тебя.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Милдред Жестокой в Заброшенный рудник, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (12907,'Нужны показательные примеры','На каждое действие существует противодействие, сестра. Вот и сейчас ходят слухи, что среди мужчин назревает мятеж...$B$BНам известно, кто подстрекатель. Бородатая свинья по имени Гархал. Убей его... и постарайся, чтобы мужчины при этом присутствовали. Пусть это послужит хорошим уроком для всех остальных. Нарушения субординации мы не потерпим!','По заданию Милдред Жестокой из Заброшенного рудника убейте Гархала.','Если у меня поначалу и были какие-то сомнения насчет твоей верности, то теперь они все рассеялись. Я думаю, тебе можно доверять. Еще немного – и ты пойдешь на повышение.','Вернитесь к Милдред Жестокой в Заброшенный рудник, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нужны показательные примеры',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На каждое действие существует противодействие, сестра. Вот и сейчас ходят слухи, что среди мужчин назревает мятеж...$B$BНам известно, кто подстрекатель. Бородатая свинья по имени Гархал. Убей его... и постарайся, чтобы мужчины при этом присутствовали. Пусть это послужит хорошим уроком для всех остальных. Нарушения субординации мы не потерпим!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По заданию Милдред Жестокой из Заброшенного рудника убейте Гархала.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Если у меня поначалу и были какие-то сомнения насчет твоей верности, то теперь они все рассеялись. Я думаю, тебе можно доверять. Еще немного – и ты пойдешь на повышение.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Милдред Жестокой в Заброшенный рудник, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12908,'Наглая пленница','Ты не знаешь жалости. Полезное свойство в наших краях.$B$BУ меня есть еще одно задание для тебя. Одна из пленных врайкулов доставляет мне больше хлопот, чем ожидалось.$B$BОна имела наглость заявить, что у нее есть право участвовать в Круге хильд – нашем священном соревновании в силе и воинской доблести.$B$BВот ключ от ее кандалов. Только не мучай ее – она все-таки женщина, пусть даже и не из наших.','Отнесите ключ Милдред Лок\'лире Карге в Заброшенный рудник.','Я знала, что ты вернешься! Сними с меня эти оковы, и я помогу тебе найти гоблина.','Наконец-то.','Вернитесь к Лок\'лире Карге на Террасу Снежной Слепоты, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наглая пленница',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты не знаешь жалости. Полезное свойство в наших краях.$B$BУ меня есть еще одно задание для тебя. Одна из пленных врайкулов доставляет мне больше хлопот, чем ожидалось.$B$BОна имела наглость заявить, что у нее есть право участвовать в Круге хильд – нашем священном соревновании в силе и воинской доблести.$B$BВот ключ от ее кандалов. Только не мучай ее – она все-таки женщина, пусть даже и не из наших.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите ключ Милдред Лок\'лире Карге в Заброшенный рудник.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я знала, что ты вернешься! Сними с меня эти оковы, и я помогу тебе найти гоблина.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Наконец-то.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лок\'лире Карге на Террасу Снежной Слепоты, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (12909,'Острый нюх','Для того чтобы выследить Бранна, нам нужно животное с острым нюхом и умением брать след. Охотничий пес – это было бы идеально, но на дирижабле их не было. Однако я, кажется, знаю, кто нам может помочь.$B$BПосле аварии я послал Калииси на восточный склон горы, чтобы она добыла нам провизию. Ее кошка, Ледокус, превосходно выслеживает добычу в снегу. Скажи Калииси, что ей придется на время расстаться со своей верной напарницей. Она может охотиться и в одиночку, а у нас нет никакого другого способа выследить Бранна Бронзоборода.','Поговорите с Калииси у подножья горы, на востоке от места крушения Гром\'арша.','Стало быть, Боктар подрядил Ледокуса на задание? Очень надеюсь, что это действительно важное дело. Забирать у охотника его зверя, пусть даже на время, для этого нужны очень веские причины!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Острый нюх',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Для того чтобы выследить Бранна, нам нужно животное с острым нюхом и умением брать след. Охотничий пес – это было бы идеально, но на дирижабле их не было. Однако я, кажется, знаю, кто нам может помочь.$B$BПосле аварии я послал Калииси на восточный склон горы, чтобы она добыла нам провизию. Ее кошка, Ледокус, превосходно выслеживает добычу в снегу. Скажи Калииси, что ей придется на время расстаться со своей верной напарницей. Она может охотиться и в одиночку, а у нас нет никакого другого способа выследить Бранна Бронзоборода.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Калииси у подножья горы, на востоке от места крушения Гром\'арша.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Стало быть, Боктар подрядил Ледокуса на задание? Очень надеюсь, что это действительно важное дело. Забирать у охотника его зверя, пусть даже на время, для этого нужны очень веские причины!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12910,'Найти преступника','Ладно, пусть в этот раз будет так, как хочет Боктар, но теперь он мой должник, и я потребую с него компенсацию. Что ты так смотришь? Да, Боктар у нас главный, но никто не смеет указывать охотнику, что ему делать.$B$B"Убери эту зверюгу, – это он так говорит. – И сделай что-нибудь, чтобы она прекратила выть."$B$BА когда ему вдруг нужна помощь, так Ледокус сразу самый разумный и ловкий! В следующий раз, когда он начнет на него ругаться, Ледокус его точно укусит. Ты не волнуйся, он тебе выследит хоть черта лысого. Но когда вы найдете тех, кто тебе нужен, разбирайся с ними $gсам:сама; – с железными дворфами, или с Бранном, или кого ты там ищешь.','Оседлайте Ледокуса и поезжайте на юг, взяв след по записке Бранна. Когда вам удастся заполучить переговорное устройство, свяжитесь с его помощью с Бранном Бронзобородом.','<Вы активируете переговорное устройство, и на нем появляется проекция дворфа. Это может быть только Бранн Бронзобород и никто иной.>\n\n<Судя по его лицу, Бранн совсем не ожидал вас увидеть. Он принимается бешено жестикулировать.>','Кто... Кто ты?','Воспользуйтесь переговорным устройством Бранна для связи с Бранном Бронзобородом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Найти преступника',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ладно, пусть в этот раз будет так, как хочет Боктар, но теперь он мой должник, и я потребую с него компенсацию. Что ты так смотришь? Да, Боктар у нас главный, но никто не смеет указывать охотнику, что ему делать.$B$B"Убери эту зверюгу, – это он так говорит. – И сделай что-нибудь, чтобы она прекратила выть."$B$BА когда ему вдруг нужна помощь, так Ледокус сразу самый разумный и ловкий! В следующий раз, когда он начнет на него ругаться, Ледокус его точно укусит. Ты не волнуйся, он тебе выследит хоть черта лысого. Но когда вы найдете тех, кто тебе нужен, разбирайся с ними $gсам:сама; – с железными дворфами, или с Бранном, или кого ты там ищешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Оседлайте Ледокуса и поезжайте на юг, взяв след по записке Бранна. Когда вам удастся заполучить переговорное устройство, свяжитесь с его помощью с Бранном Бронзобородом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Вы активируете переговорное устройство, и на нем появляется проекция дворфа. Это может быть только Бранн Бронзобород и никто иной.>\n\n<Судя по его лицу, Бранн совсем не ожидал вас увидеть. Он принимается бешено жестикулировать.>',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Кто... Кто ты?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Воспользуйтесь переговорным устройством Бранна для связи с Бранном Бронзобородом.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (12911,'Kill Credit Test','/wave at me and I\'ll assign \'kill credit to player\' to you.','/wave at Kill Credit Test','Вернитесь к Kill Credit Test.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Kill Credit Test',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','/wave at me and I\'ll assign \'kill credit to player\' to you.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','/wave at Kill Credit Test',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Kill Credit Test.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (12912,'Приближение великой бури','Ты не $gтакой:такая;, как все остальные, $gмалыш:малышка;. От тебя не несет древней смертью. Наверное, тебе можно доверять.$B$BЯ – Гимер, король штормовых великанов. Сюда меня заманил мой брат Тиасси, который теперь стал нежитью-прислужником Короля-лича. Когда я понял, что его крик о помощи был уловкой, чтобы заманить меня в ловушку, было уже слишком поздно. Теперь я – пленник Плети, и, боюсь, меня ждет та же печальная участь, что постигла многих штормовых великанов.$B$BПридумай способ, как мне выйти из этой клетки, и я помогу тебе. Сделаю все, что в моих силах.','Придумайте способ, как освободить из клетки Гимера, короля штормовых великанов. Поговорите с инженером Ридом в Передовом лагере рыцарей.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приближение великой бури',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты не $gтакой:такая;, как все остальные, $gмалыш:малышка;. От тебя не несет древней смертью. Наверное, тебе можно доверять.$B$BЯ – Гимер, король штормовых великанов. Сюда меня заманил мой брат Тиасси, который теперь стал нежитью-прислужником Короля-лича. Когда я понял, что его крик о помощи был уловкой, чтобы заманить меня в ловушку, было уже слишком поздно. Теперь я – пленник Плети, и, боюсь, меня ждет та же печальная участь, что постигла многих штормовых великанов.$B$BПридумай способ, как мне выйти из этой клетки, и я помогу тебе. Сделаю все, что в моих силах.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Придумайте способ, как освободить из клетки Гимера, короля штормовых великанов. Поговорите с инженером Ридом в Передовом лагере рыцарей.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (12913,'Говори по-орочьи!','<Бранн принимается бешено жестикулировать и говорить на своем родном языке.>$B$BРук МогОт ред а могот та эфт Трос-гарЕ Халдир.$B$BХа гор рук хаз та ке рук хрим эфт трос-ам-ха рук кост-ум хавар го кост.$B$BА модосс хире рук бергум эфт трос-ам-ха га элф Халдир ке лох Тон ве ло гефрунон та митта.$B$BГар Рук дагУм лох ангор-маги та хар рук!$B$B<Вы понимаете, что ничего не понимаете. Быть может, шаман Мотеха Дитя Ветра, на месте крушения Гром\'арша сможет как-то решить эту проблему.>','Отправляйтесь на место крушения Гром\'арша и узнайте, не сможет ли Мотеха Дитя Ветра вам помочь.','Барток совсем не обрадуется, что ты не сумел найти Бранна, но ты хотя бы вернулся не с пустыми руками. Давай посмотрим, что можно сделать по поводу этой дворфской тарабарщины.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Говори по-орочьи!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Бранн принимается бешено жестикулировать и говорить на своем родном языке.>$B$BРук МогОт ред а могот та эфт Трос-гарЕ Халдир.$B$BХа гор рук хаз та ке рук хрим эфт трос-ам-ха рук кост-ум хавар го кост.$B$BА модосс хире рук бергум эфт трос-ам-ха га элф Халдир ке лох Тон ве ло гефрунон та митта.$B$BГар Рук дагУм лох ангор-маги та хар рук!$B$B<Вы понимаете, что ничего не понимаете. Быть может, шаман Мотеха Дитя Ветра, на месте крушения Гром\'арша сможет как-то решить эту проблему.>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь на место крушения Гром\'арша и узнайте, не сможет ли Мотеха Дитя Ветра вам помочь.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Барток совсем не обрадуется, что ты не сумел найти Бранна, но ты хотя бы вернулся не с пустыми руками. Давай посмотрим, что можно сделать по поводу этой дворфской тарабарщины.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12914,'Спасение Гимера','Говоришь, его держат в запертой клетке высотой в 100 метров?$B$BЕсли мои расчеты верны, мы можем, как минимум, расшатать петли на двери, а остальное великан доломает сам.$B$BНо для того, чтобы все получилось, мне понадобятся пластификаторы и стабилизаторы.$B$BВ качестве пластификатора отлично пойдет субстанция банши. Ее можно добыть у банши на Мертвых полях, что на северо-востоке отсюда. Стабилизатор можно найти у землегневов, это на юго-западе, у Черной Заставы.$B$BОтправляйся немедленно!','Без пластификаторов и стабилизаторов я не смогу изготовить взрывчатку, чтобы освободить твоего друга из плена.','Вернитесь к инженеру Риду в Передовой лагерь рыцарей, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спасение Гимера',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Говоришь, его держат в запертой клетке высотой в 100 метров?$B$BЕсли мои расчеты верны, мы можем, как минимум, расшатать петли на двери, а остальное великан доломает сам.$B$BНо для того, чтобы все получилось, мне понадобятся пластификаторы и стабилизаторы.$B$BВ качестве пластификатора отлично пойдет субстанция банши. Ее можно добыть у банши на Мертвых полях, что на северо-востоке отсюда. Стабилизатор можно найти у землегневов, это на юго-западе, у Черной Заставы.$B$BОтправляйся немедленно!',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Без пластификаторов и стабилизаторов я не смогу изготовить взрывчатку, чтобы освободить твоего друга из плена.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к инженеру Риду в Передовой лагерь рыцарей, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12915,'Возобновление старых связей','Если я собираюсь отвоевать Храм Творцов у моего брата, мне нужно помириться с прежними союзниками.$b$bМожет быть, если мы уничтожим общего врага, это будет уже большой шаг в восстановлению дружбы со снежными великанами.$b$bФьорн осадил Дун Ниффелем со своей армией железных великанов. Мы должны уничтожить его у Наковальни Фьорна, что к востоку отсюда, и ослабить его войско, чтобы Сыны Ходира смогли вырваться из осады.$b$bВозьми этот амулет, $n. Используй его, чтобы вызвать себе на подмогу моих воинов земли. Когда сделаешь все, что нужно, возвращайся ко мне.','По заданию Торима из Храма Штормов убейте Фьорна и 5 железных великанов из клана Закаленных Бурей у Наковальни Фьорна к востоку от Дун Ниффелема. Чтобы вызвать на подмогу воинов земли, воспользуйтесь оберегом земли Торима. Чтобы его задействовать, нужен гранитный валун из Наковальни Фьорна.','Поверхность наковальни раскалена в противовес ледяному воздуху.','Вернитесь к Ториму в Храм Штормов, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возобновление старых связей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если я собираюсь отвоевать Храм Творцов у моего брата, мне нужно помириться с прежними союзниками.$b$bМожет быть, если мы уничтожим общего врага, это будет уже большой шаг в восстановлению дружбы со снежными великанами.$b$bФьорн осадил Дун Ниффелем со своей армией железных великанов. Мы должны уничтожить его у Наковальни Фьорна, что к востоку отсюда, и ослабить его войско, чтобы Сыны Ходира смогли вырваться из осады.$b$bВозьми этот амулет, $n. Используй его, чтобы вызвать себе на подмогу моих воинов земли. Когда сделаешь все, что нужно, возвращайся ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По заданию Торима из Храма Штормов убейте Фьорна и 5 железных великанов из клана Закаленных Бурей у Наковальни Фьорна к востоку от Дун Ниффелема. Чтобы вызвать на подмогу воинов земли, воспользуйтесь оберегом земли Торима. Чтобы его задействовать, нужен гранитный валун из Наковальни Фьорна.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Поверхность наковальни раскалена в противовес ледяному воздуху.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ториму в Храм Штормов, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12916,'Наша единственная надежда','Я дам тебе сефорий – крайне неустойчивое взрывчатое вещество с уникальными свойствами. Оно очень мягкое и пластичное, и его можно замазать в петли и трещины клетки, чтобы причинить максимальный ущерб.$B$BВозвращайся к своему другу и освободи его с помощью огромного сефориевого заряда.$B$BБудем надеяться, что он сдержит слово и выполнит свои обязательства по договору. Он – наша единственная надежда.','Я - великан своего слова, малыш.','Вернитесь к Гимеру в Тупик Трыма, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наша единственная надежда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я дам тебе сефорий – крайне неустойчивое взрывчатое вещество с уникальными свойствами. Оно очень мягкое и пластичное, и его можно замазать в петли и трещины клетки, чтобы причинить максимальный ущерб.$B$BВозвращайся к своему другу и освободи его с помощью огромного сефориевого заряда.$B$BБудем надеяться, что он сдержит слово и выполнит свои обязательства по договору. Он – наша единственная надежда.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я - великан своего слова, малыш.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гимеру в Тупик Трыма, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12917,'Поймай голос ветра!..','В общем-то, нам и не стоило надеяться найти Бранна так быстро. Не с нашим везением... Но если мы сможем понять, что говорит Бранн, тогда, может быть, у тебя получится уговорить его рассказать, где он прячется.$B$BСила ветра в этих горах велика, и это может оказаться для нас преимуществом. Знающий шаман способен расслышать в шуме ветра звуки всех языков, существующих в мире.$B$BНа северо-западе, на Снежных равнинах, обитают странники бурь – существа, сотканные из ветра. Завладей их голосами и принеси их мне.','Поймайте 5 голосов ветра, Мотеха Дитя Ветра на месте крушения Гром\'арша ждет, чтобы вы их принесли.','Должно быть, тебе удастся связаться с дворфом сейчас. Спроси Боктара, что ему от тебя нужно. И не будем терять времени. У нас его и так мало.','Ты $Gпоймал:поймала; голоса ветра?','Вернитесь к Мотехе на место крушения Гром\'арша, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поймай голос ветра!..',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В общем-то, нам и не стоило надеяться найти Бранна так быстро. Не с нашим везением... Но если мы сможем понять, что говорит Бранн, тогда, может быть, у тебя получится уговорить его рассказать, где он прячется.$B$BСила ветра в этих горах велика, и это может оказаться для нас преимуществом. Знающий шаман способен расслышать в шуме ветра звуки всех языков, существующих в мире.$B$BНа северо-западе, на Снежных равнинах, обитают странники бурь – существа, сотканные из ветра. Завладей их голосами и принеси их мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поймайте 5 голосов ветра, Мотеха Дитя Ветра на месте крушения Гром\'арша ждет, чтобы вы их принесли.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Должно быть, тебе удастся связаться с дворфом сейчас. Спроси Боктара, что ему от тебя нужно. И не будем терять времени. У нас его и так мало.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gпоймал:поймала; голоса ветра?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мотехе на место крушения Гром\'арша, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12918,'Огранка камней','Боги, тут холоднее, чем в пасти ледяного змея! Мало того, что покупатели не торопятся заказывать у меня побрякушки – так еще и запасы драгоценных камней практически иссякли! Знаешь, если бы ты $gпринес:принесла; мне несколько необработанных камней, я бы взамен научил тебя искусству огранки! Тогда ты сможешь получать идеальные камни с улучшенными характеристиками, обрабатывая драгоценные камни Нордскола высокого качества.','Принесите два огромных цитрина, два темных нефрита и два сумрачных кристалла Унгуло в Валгард.','Они идеально подходят для пополнения моих запасов. Я не только научу тебя искусству безупречной огранки драгоценных камней, но и вырежу один из этих драгоценных камней в идеальную форму, которую ты можешь получить в качестве награды.','Ты $Gсамый:самая; $Gщедрый:щедрая;. Меньшее, что я могу сделать, это научить тебя навыкам огранки драгоценных камней.','Вернитесь к Унгуло в Валгард, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Огранка камней',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Боги, тут холоднее, чем в пасти ледяного змея! Мало того, что покупатели не торопятся заказывать у меня побрякушки – так еще и запасы драгоценных камней практически иссякли! Знаешь, если бы ты $gпринес:принесла; мне несколько необработанных камней, я бы взамен научил тебя искусству огранки! Тогда ты сможешь получать идеальные камни с улучшенными характеристиками, обрабатывая драгоценные камни Нордскола высокого качества.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите два огромных цитрина, два темных нефрита и два сумрачных кристалла Унгуло в Валгард.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Они идеально подходят для пополнения моих запасов. Я не только научу тебя искусству безупречной огранки драгоценных камней, но и вырежу один из этих драгоценных камней в идеальную форму, которую ты можешь получить в качестве награды.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gсамый:самая; $Gщедрый:щедрая;. Меньшее, что я могу сделать, это научить тебя навыкам огранки драгоценных камней.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Унгуло в Валгард, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12919,'Месть короля Бурь','Король-лич уничтожил моих людей. Теперь силы Плети используют тела штормовых великанов, чтобы делать из них безмозглых мясистых великанов или, еще того хуже, чудовищ, сшитых из разных кусков, наподобие Трыма.$B$BЯ не остановлюсь ни перед чем, лишь бы стереть этих мерзавцев с лица земли. Мне нужна твоя помощь. Вместе мы уничтожим воинство Плети, угрожающее Зул\'Драку.$B$BМы перебьем их всех: Навариуса, Алгара и Трыма!$B$BКогда будешь $gготов:готова;, дай мне знать, и мы начнем истреблять этих гадов.','Когда будете готовы к битве, скажите об этом Гимеру.$B$BСидя на голове у Гимера, уничтожьте 100 воинов Плети и убейте Алгара Избранного, Трыма и принца Навариуса. В случае успешного исхода доложите об этом серебряному рыцарю Маккеллару из передового лагеря рыцарей.','Что происходит? Наши враги мертвы?','Вернитесь к рыцарю Маккеллару в Передовой лагерь рыцарей, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Месть короля Бурь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Король-лич уничтожил моих людей. Теперь силы Плети используют тела штормовых великанов, чтобы делать из них безмозглых мясистых великанов или, еще того хуже, чудовищ, сшитых из разных кусков, наподобие Трыма.$B$BЯ не остановлюсь ни перед чем, лишь бы стереть этих мерзавцев с лица земли. Мне нужна твоя помощь. Вместе мы уничтожим воинство Плети, угрожающее Зул\'Драку.$B$BМы перебьем их всех: Навариуса, Алгара и Трыма!$B$BКогда будешь $gготов:готова;, дай мне знать, и мы начнем истреблять этих гадов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Когда будете готовы к битве, скажите об этом Гимеру.$B$BСидя на голове у Гимера, уничтожьте 100 воинов Плети и убейте Алгара Избранного, Трыма и принца Навариуса. В случае успешного исхода доложите об этом серебряному рыцарю Маккеллару из передового лагеря рыцарей.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что происходит? Наши враги мертвы?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к рыцарю Маккеллару в Передовой лагерь рыцарей, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (12920,'Вдогонку за Бранном','Чего ты ждешь? Языковой барьер успешно преодолен, за что спасибо Мотехе. Свяжись с Бранном Бронзобородом и попытайся узнать, где он прячется и что он задумал.$B$BМожет быть, нам еще удастся хоть что-то спасти.','Используйте переговорное устройство Бранна, чтобы связаться с Бранном Бронзобородом. Потом доложите о результатах Боктару Кровавому Безумию, который ждет вас на месте крушения Гром\'арша.$B$BЕсли вы потеряете переговорное устройство Бранна, вам поможет Мотеха Дитя Ветра на месте крушения Гром\'арша.','<Боктар слушает ваш пересказ разговора с Бранном.>\n\nДворф сказал правду. План Вор\'такха – это совсем не похоже на методы Орды. Если Бранн Бронзобород знает способ, как остановить этих железных дворфов и их покровителя, мы, безусловно, ему поможем.','Вернитесь к Боктару Кровавому Безумию на место крушения Гром\'арша, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вдогонку за Бранном',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чего ты ждешь? Языковой барьер успешно преодолен, за что спасибо Мотехе. Свяжись с Бранном Бронзобородом и попытайся узнать, где он прячется и что он задумал.$B$BМожет быть, нам еще удастся хоть что-то спасти.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте переговорное устройство Бранна, чтобы связаться с Бранном Бронзобородом. Потом доложите о результатах Боктару Кровавому Безумию, который ждет вас на месте крушения Гром\'арша.$B$BЕсли вы потеряете переговорное устройство Бранна, вам поможет Мотеха Дитя Ветра на месте крушения Гром\'арша.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Боктар слушает ваш пересказ разговора с Бранном.>\n\nДворф сказал правду. План Вор\'такха – это совсем не похоже на методы Орды. Если Бранн Бронзобород знает способ, как остановить этих железных дворфов и их покровителя, мы, безусловно, ему поможем.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Боктару Кровавому Безумию на место крушения Гром\'арша, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (12921,'Смена декораций','Замечательно. В восточной части рудника есть выход к деревне Бруннхильдар. Иди туда, и там я тебя встречу.$B$BНикто не должен заподозрить, что ты мне помогаешь, и поэтому нас не должны видеть вместе. Я изменю облик с помощью магии. Не волнуйся, |3-6($r), мы найдем твоего друга.','Поговорите с Лок\'лирой Каргой в деревне Бруннхильдар.','Наконец-то.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Смена декораций',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Замечательно. В восточной части рудника есть выход к деревне Бруннхильдар. Иди туда, и там я тебя встречу.$B$BНикто не должен заподозрить, что ты мне помогаешь, и поэтому нас не должны видеть вместе. Я изменю облик с помощью магии. Не волнуйся, |3-6($r), мы найдем твоего друга.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Лок\'лирой Каргой в деревне Бруннхильдар.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Наконец-то.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (12922,'Очищающее пламя','Соберите 10 гневных искр с пылающих загробников на Промерзшем озере и с их помощью разожгите огонь в Наковальне Фьорна.','Вернитесь к наковальне Фьорна в Дун Ниффелем, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Очищающее пламя',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 гневных искр с пылающих загробников на Промерзшем озере и с их помощью разожгите огонь в Наковальне Фьорна.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к наковальне Фьорна в Дун Ниффелем, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (12924,'Возобновление союза','<Торим улыбается – в первый раз за все время вашего знакомства.>$b$bЭто похоже на перст судьбы.$b$bЗнаешь, что ты $gнашел:нашла;? Это то, что осталось от моих доспехов, которые я давным-давно выбросил в припадке отчаяния и оставил на волю стихий.$b$bЛишь Сыны Ходира способны перековать эти доспехи, поскольку это они их создали.$b$bМожет быть, того, что ты $gсделал:сделала;, будет достаточно, чтобы они перестали меня ненавидеть. Разыщи их короля, Йоккума, если он еще жив, и обратись к нему с просьбой о содействии. Надеюсь, тебе удастся завоевать его расположение.','Отправляйтесь в Дун Ниффелем и попросите короля Йоккума разрешить воссоздать доспех Торима. Выполнив поручение Йоккума, поговорите с Ньормельдом в Дун Ниффелеме.','Вернитесь к Ньормельду в Дун Ниффелем, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возобновление союза',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Торим улыбается – в первый раз за все время вашего знакомства.>$b$bЭто похоже на перст судьбы.$b$bЗнаешь, что ты $gнашел:нашла;? Это то, что осталось от моих доспехов, которые я давным-давно выбросил в припадке отчаяния и оставил на волю стихий.$b$bЛишь Сыны Ходира способны перековать эти доспехи, поскольку это они их создали.$b$bМожет быть, того, что ты $gсделал:сделала;, будет достаточно, чтобы они перестали меня ненавидеть. Разыщи их короля, Йоккума, если он еще жив, и обратись к нему с просьбой о содействии. Надеюсь, тебе удастся завоевать его расположение.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Дун Ниффелем и попросите короля Йоккума разрешить воссоздать доспех Торима. Выполнив поручение Йоккума, поговорите с Ньормельдом в Дун Ниффелеме.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ньормельду в Дун Ниффелем, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12925,'Верность традициям','Король-лич трижды посылал к нам своих эмиссаров. Всех троих расчленили на месте.$B$BНаши сестры в Валькирионе в отличие от нас не хранят верность традициям. Они купились на посулы сил Плети. И теперь, вместо того чтобы отлавливать диких драконов, они их выращивают из гнили и скверны, которые тащат с собой силы Плети.$B$BРаздобудь флаконы масла льда, которые носят с собой хильды Валькириона, и с помощью масла заморозь все пораженные гнилью яйца, которые сумеешь найти. Ходят слухи, что яйца хранятся в вонючем пруду, заполненном гнилью.','По заданию Тиры Квиншал из деревни Бруннхильдар отправляйтесь в Валькирион и добудьте у валькирионских претенденток флаконы масла льда. Используйте их, чтобы уничтожить 30 зачумленных яиц протодраконов.','Большое спасибо. Нельзя допускать, чтобы кто-то поганил священные традиции наших доблестных предков.','Ты нашла лагерь Бронзоборода?','Вернитесь к Тире Квиншал в деревню Бруннхильдар, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Верность традициям',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Король-лич трижды посылал к нам своих эмиссаров. Всех троих расчленили на месте.$B$BНаши сестры в Валькирионе в отличие от нас не хранят верность традициям. Они купились на посулы сил Плети. И теперь, вместо того чтобы отлавливать диких драконов, они их выращивают из гнили и скверны, которые тащат с собой силы Плети.$B$BРаздобудь флаконы масла льда, которые носят с собой хильды Валькириона, и с помощью масла заморозь все пораженные гнилью яйца, которые сумеешь найти. Ходят слухи, что яйца хранятся в вонючем пруду, заполненном гнилью.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По заданию Тиры Квиншал из деревни Бруннхильдар отправляйтесь в Валькирион и добудьте у валькирионских претенденток флаконы масла льда. Используйте их, чтобы уничтожить 30 зачумленных яиц протодраконов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Большое спасибо. Нельзя допускать, чтобы кто-то поганил священные традиции наших доблестных предков.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты нашла лагерь Бронзоборода?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тире Квиншал в деревню Бруннхильдар, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12926,'Кусочки головоломки','Железные дворфы и их свирепые создания объявили войну всем существам из камня, которых Бранн называет земельниками, и их союзникам-великанам. Свяжись с Бранном и узнай, не нужна ли ему твоя помощь. И самое главное – помни: все, что мы от него узнаем, может стать хорошим подспорьем в нашей борьбе против железных дворфов и их хозяина.','Воспользуйтесь переговорным устройством Бранна, чтобы связаться с Бранном Бронзобородом и выяснить, что делать дальше.','Как ты быстро! Похвально, похвально... Теперь, когда у нас есть целый диск, нам надо понять, как с его помощью можно открыть первую половину ключа от архива.','Ты $Gсобрал:собрала>;диск?','Воспользуйтесь переговорным устройством Бранна для связи с Бранном Бронзобородом.$B$BЕсли вы потеряете переговорное устройство, возьмите новое у Мотеха Дитя Ветра на месте крушения Гром\'арша.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кусочки головоломки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Железные дворфы и их свирепые создания объявили войну всем существам из камня, которых Бранн называет земельниками, и их союзникам-великанам. Свяжись с Бранном и узнай, не нужна ли ему твоя помощь. И самое главное – помни: все, что мы от него узнаем, может стать хорошим подспорьем в нашей борьбе против железных дворфов и их хозяина.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь переговорным устройством Бранна, чтобы связаться с Бранном Бронзобородом и выяснить, что делать дальше.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Как ты быстро! Похвально, похвально... Теперь, когда у нас есть целый диск, нам надо понять, как с его помощью можно открыть первую половину ключа от архива.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gсобрал:собрала>;диск?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Воспользуйтесь переговорным устройством Бранна для связи с Бранном Бронзобородом.$B$BЕсли вы потеряете переговорное устройство, возьмите новое у Мотеха Дитя Ветра на месте крушения Гром\'арша.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12927,'Сбор информации','Этот диск, который ты $gсобрал:собрала;... он пустой! Наверное, Хранитель Мимир, который построил эту библиотеку, спрятал всю информацию в другом месте. Осмотри Библиотеку Изобретателя, там нигде нет банков данных?$B$BМожет, диск предназначен для них... Попробуй использовать его на каком-нибудь из банков данных. Может быть, он считывает и записывает информацию с этих устройств. Попробуй сделать, как я сказал, а потом свяжись со мной и расскажи, как успехи. А я тем временем попробую разыскать вторую половину ключа от архива.','Воспользуйтесь диском изобретателя, чтобы считать 7 фрагментов секретных данных из банков данных.','<Бранн смотрит на диск, который вы ему показываете.>\n\nА как я отсюда пойму, записано там что-нибудь или нет?! Опиши мне подробно, что было...\n\n<Вы подробно описываете процесс поиска и считывания данных.>\n\nЗначит, там все работает? Надо отдать должное Хранителю Мимиру. Он – настоящий мастер своего дела.','Ну, что там с диском? Тебе удалось считать информацию?','Воспользуйтесь переговорным устройством Бранна для связи с Бранном Бронзобородом.$B$BЕсли вы потеряете переговорное устройство, возьмите новое у Мотеха Дитя Ветра на месте крушения Гром\'арша.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сбор информации',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этот диск, который ты $gсобрал:собрала;... он пустой! Наверное, Хранитель Мимир, который построил эту библиотеку, спрятал всю информацию в другом месте. Осмотри Библиотеку Изобретателя, там нигде нет банков данных?$B$BМожет, диск предназначен для них... Попробуй использовать его на каком-нибудь из банков данных. Может быть, он считывает и записывает информацию с этих устройств. Попробуй сделать, как я сказал, а потом свяжись со мной и расскажи, как успехи. А я тем временем попробую разыскать вторую половину ключа от архива.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь диском изобретателя, чтобы считать 7 фрагментов секретных данных из банков данных.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Бранн смотрит на диск, который вы ему показываете.>\n\nА как я отсюда пойму, записано там что-нибудь или нет?! Опиши мне подробно, что было...\n\n<Вы подробно описываете процесс поиска и считывания данных.>\n\nЗначит, там все работает? Надо отдать должное Хранителю Мимиру. Он – настоящий мастер своего дела.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, что там с диском? Тебе удалось считать информацию?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Воспользуйтесь переговорным устройством Бранна для связи с Бранном Бронзобородом.$B$BЕсли вы потеряете переговорное устройство, возьмите новое у Мотеха Дитя Ветра на месте крушения Гром\'арша.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12928,'Оболочка Норганнона','Идет зарядка диска изобретателя.$B$BДиск заряжен.$B$BЗагрузка аварийного протокола.$B$BАварийный протокол загружен. Пожалуйста, воспользуйтесь диском для активации охранника оболочки Норганнона, архивариуса Мехатона. Оболочка будет предоставлена вам после проверки личности.$B$BЖелаем приятного тысячелетия.','Заберите оболочку Норганнона у архивариуса Мехатона.','Ты $Gнашел:нашла; оболочку Норганнона?','Воспользуйтесь переговорным устройством Бранна для связи с Бранном Бронзобородом.$B$BЕсли вы потеряете переговорное устройство, возьмите новое у Мотеха Дитя Ветра на месте крушения Гром\'арша.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оболочка Норганнона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Идет зарядка диска изобретателя.$B$BДиск заряжен.$B$BЗагрузка аварийного протокола.$B$BАварийный протокол загружен. Пожалуйста, воспользуйтесь диском для активации охранника оболочки Норганнона, архивариуса Мехатона. Оболочка будет предоставлена вам после проверки личности.$B$BЖелаем приятного тысячелетия.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заберите оболочку Норганнона у архивариуса Мехатона.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gнашел:нашла; оболочку Норганнона?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Воспользуйтесь переговорным устройством Бранна для связи с Бранном Бронзобородом.$B$BЕсли вы потеряете переговорное устройство, возьмите новое у Мотеха Дитя Ветра на месте крушения Гром\'арша.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (12929,'Земельники Ульдуара','Значит, ты знаешь Бранна Бронзоборода? Это наш самый верный союзник из всех, кто создан из плоти и крови. Мы с ним – как братья в нашей общей борьбе против Локена и его приспешников, в борьбе за Ульдуар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Земельники Ульдуара',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Значит, ты знаешь Бранна Бронзоборода? Это наш самый верный союзник из всех, кто создан из плоти и крови. Мы с ним – как братья в нашей общей борьбе против Локена и его приспешников, в борьбе за Ульдуар.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12930,'Горсть редкой земли','Кажется, целая вечность прошла с тех пор, когда эти молоты били о камень, а не о железо. После того как нас изгнали из Ульдуара, самые слабые из нас погибли, а самые сильные из мастеров возродились уже в качестве воинов.$B$BНо в непрестанных сражениях с железными дворфами гибнут даже сильнейшие.$B$BМы не можем помочь нашим раненым – у нас почти не осталось зачарованной земли. Раньше мы добывали ее в скалах на северо-западе, но сейчас мы не можем пойти туда, потому что нам надо сражаться здесь. Ты нам поможешь?','Ты $Gпринес:принесла; землю?','Вернитесь к Глыбоскалу Камнетесу в Приют Глыбоскала, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Горсть редкой земли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кажется, целая вечность прошла с тех пор, когда эти молоты били о камень, а не о железо. После того как нас изгнали из Ульдуара, самые слабые из нас погибли, а самые сильные из мастеров возродились уже в качестве воинов.$B$BНо в непрестанных сражениях с железными дворфами гибнут даже сильнейшие.$B$BМы не можем помочь нашим раненым – у нас почти не осталось зачарованной земли. Раньше мы добывали ее в скалах на северо-западе, но сейчас мы не можем пойти туда, потому что нам надо сражаться здесь. Ты нам поможешь?',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gпринес:принесла; землю?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Глыбоскалу Камнетесу в Приют Глыбоскала, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12931,'Контратака','Защитники приюта делают все, чтобы сдержать натиск железных дворфов, но те все равно нас теснят. Мои люди, конечно, крепки и выносливы, но они все-таки не железные. Если к нам не придет подкрепление, мы не выстоим. Они нас просто задавят числом.$B$BПоможешь нам защитить убежище? Надо как-то поднять боевой дух моим воинам и дать им возможность собраться с силами, чтобы пойти в контратаку.$B$BУбей столько дворфов из клана Закаленных Бурей и их созданий, сколько сумеешь найти за пределами приюта.','Твои подвиги, безусловно, подняли боевой дух моих воинов. Теперь они будут сражаться с удвоенным рвением.','Как идет сражение?','Вернитесь к Глыбоскалу Камнетесу в Приют Глыбоскала, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Контратака',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Защитники приюта делают все, чтобы сдержать натиск железных дворфов, но те все равно нас теснят. Мои люди, конечно, крепки и выносливы, но они все-таки не железные. Если к нам не придет подкрепление, мы не выстоим. Они нас просто задавят числом.$B$BПоможешь нам защитить убежище? Надо как-то поднять боевой дух моим воинам и дать им возможность собраться с силами, чтобы пойти в контратаку.$B$BУбей столько дворфов из клана Закаленных Бурей и их созданий, сколько сумеешь найти за пределами приюта.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Твои подвиги, безусловно, подняли боевой дух моих воинов. Теперь они будут сражаться с удвоенным рвением.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как идет сражение?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Глыбоскалу Камнетесу в Приют Глыбоскала, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (12932,'Амфитеатр Страданий: Иггдрас!','Вот что я тебе скажу, $gприятель:красавица;: это тебе не равнины Награнда. Здешние тролли даже грязнее, чем огры. Но я всегда там, где золото, да! Так что добро пожаловать в Зул\'Драк, $gдружище:подруга;.$B$BТы тут $gновенький, еще не освоился:новенькая, еще не освоилась;, но я тебя быстро введу в курс дела. Я – владелец бойцовского клуба. Этот отважный тролль рядом со мной – Водин, мой телохранитель. Ты – инструмент для развлечения зрителей. Когда захочешь подраться, дай мне знать, и я организую поединок.$B$BЕсли ты чувствуешь, что $gготов:готова;, и у тебя есть с собой пара-тройка друзей, можно устроить все прямо сейчас. Ну, что скажешь?','Выйдите на арену в Амфитеатре Страданий и победите Иггдраса! Потом вернитесь к троллю-прислужнику Водину и получите награду.','Иггдрас побежден','Вернитесь к троллю-прислужнику Водину в Амфитеатр Страданий, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Амфитеатр Страданий: Иггдрас!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот что я тебе скажу, $gприятель:красавица;: это тебе не равнины Награнда. Здешние тролли даже грязнее, чем огры. Но я всегда там, где золото, да! Так что добро пожаловать в Зул\'Драк, $gдружище:подруга;.$B$BТы тут $gновенький, еще не освоился:новенькая, еще не освоилась;, но я тебя быстро введу в курс дела. Я – владелец бойцовского клуба. Этот отважный тролль рядом со мной – Водин, мой телохранитель. Ты – инструмент для развлечения зрителей. Когда захочешь подраться, дай мне знать, и я организую поединок.$B$BЕсли ты чувствуешь, что $gготов:готова;, и у тебя есть с собой пара-тройка друзей, можно устроить все прямо сейчас. Ну, что скажешь?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выйдите на арену в Амфитеатре Страданий и победите Иггдраса! Потом вернитесь к троллю-прислужнику Водину и получите награду.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Иггдрас побежден',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к троллю-прислужнику Водину в Амфитеатр Страданий, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (12933,'Амфитеатр Страданий: магнатавр!','Следующий бой обещает быть жестким, $gдружище:подруга;. Как я понимаю, какому-то магнатавру из Драконьего Погоста пришла охота подраться. Тебе приходилось сражаться с подобными противниками? Скажу только одно: целься повыше!$B$BКогда будешь $gготов:готова;, дай мне знать, и мы сразу начнем.','Выйдите на арену в Амфитеатре Страданий и победите Смрадоборода! Потом вернитесь к троллю-прислужнику Водину и получите награду.','Ух ты! Когда я впервые увидел Смрадоборода, я подумал, тебе конец! Но ты молодец!','Награда – по окончании боя, приятель.','Смрадобород побежден','Вернитесь к троллю-прислужнику Водину в Амфитеатр Страданий, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Амфитеатр Страданий: магнатавр!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Следующий бой обещает быть жестким, $gдружище:подруга;. Как я понимаю, какому-то магнатавру из Драконьего Погоста пришла охота подраться. Тебе приходилось сражаться с подобными противниками? Скажу только одно: целься повыше!$B$BКогда будешь $gготов:готова;, дай мне знать, и мы сразу начнем.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выйдите на арену в Амфитеатре Страданий и победите Смрадоборода! Потом вернитесь к троллю-прислужнику Водину и получите награду.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ух ты! Когда я впервые увидел Смрадоборода, я подумал, тебе конец! Но ты молодец!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Награда – по окончании боя, приятель.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Смрадобород побежден',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к троллю-прислужнику Водину в Амфитеатр Страданий, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (12934,'Амфитеатр Страданий: существо из другого мира!','Скажу тебе правду, $gдружище:красавица;. В этом бою у тебя будет соперник, который вряд ли тебе по силам. Существо из Обители стихий! Я даже не знаю, что выйдет сейчас на арену!$B$BЕсли считаешь, что справишься, тогда выходи драться и всыпь ему по первое число!','Выйдите на арену в Амфитеатре Страданий и победите повелителя элементалей! Потом вернитесь к троллю-прислужнику Водину и получите награду.','Невероятно! Когда он вышел, я думал, что весь Амфитеатр взорвется! Но ты был явно сильнее!','Награда – по окончании боя, приятель.','Повелитель элементалей побежден','Вернитесь к троллю-прислужнику Водину в Амфитеатр Страданий, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Амфитеатр Страданий: существо из другого мира!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Скажу тебе правду, $gдружище:красавица;. В этом бою у тебя будет соперник, который вряд ли тебе по силам. Существо из Обители стихий! Я даже не знаю, что выйдет сейчас на арену!$B$BЕсли считаешь, что справишься, тогда выходи драться и всыпь ему по первое число!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выйдите на арену в Амфитеатре Страданий и победите повелителя элементалей! Потом вернитесь к троллю-прислужнику Водину и получите награду.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Невероятно! Когда он вышел, я думал, что весь Амфитеатр взорвется! Но ты был явно сильнее!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Награда – по окончании боя, приятель.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Повелитель элементалей побежден',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к троллю-прислужнику Водину в Амфитеатр Страданий, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (12935,'Амфитеатр Страданий: Клыкаррмагеддон!','Твой следующий соперник явился из темного и нехорошего места. Это тьма потустороннего мира. Терзаемый голодом, он будет стремиться к победе любой ценой! Будь $gосторожен:осторожна;! Говорят, он сражается с йети просто ради разминки!$B$BКогда будешь $gготов:готова;, мы начнем.','Выйдите на арену в Амфитеатре Страданий и победите Ориноко Клыколома! Потом вернитесь к троллю-прислужнику Водину и получите награду.','Награда – по окончании боя, приятель.','Ориноко Клыколом побежден','Вернитесь к троллю-прислужнику Водину в Амфитеатр Страданий, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Амфитеатр Страданий: Клыкаррмагеддон!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Твой следующий соперник явился из темного и нехорошего места. Это тьма потустороннего мира. Терзаемый голодом, он будет стремиться к победе любой ценой! Будь $gосторожен:осторожна;! Говорят, он сражается с йети просто ради разминки!$B$BКогда будешь $gготов:готова;, мы начнем.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выйдите на арену в Амфитеатре Страданий и победите Ориноко Клыколома! Потом вернитесь к троллю-прислужнику Водину и получите награду.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Награда – по окончании боя, приятель.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Ориноко Клыколом побежден',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к троллю-прислужнику Водину в Амфитеатр Страданий, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (12936,'Амфитеатр Страданий: Коррак Кровопуск!','Ты не поверишь, $gприятель:красавица;. В следующем поединке твоим соперником будет сам Коррак Кровопуск! Похоже, тролли Драккари решили сыграть по-крупному! Я тебя сразу предупреждаю: он пил настойку звериного бога. Он хороший боец и настроен на то, чтобы вбить тебя в землю.$B$BТы $gготов:готова; с ним сразиться?','Выйдите на арену в Амфитеатре Страданий и победите Коррака Кровопуска! Потом вернитесь к троллю-прислужнику Водину и получите награду.','Награда – по окончании боя, приятель.','Коррак Кровопуск побежден','Вернитесь к троллю-прислужнику Водину в Амфитеатр Страданий, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Амфитеатр Страданий: Коррак Кровопуск!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты не поверишь, $gприятель:красавица;. В следующем поединке твоим соперником будет сам Коррак Кровопуск! Похоже, тролли Драккари решили сыграть по-крупному! Я тебя сразу предупреждаю: он пил настойку звериного бога. Он хороший боец и настроен на то, чтобы вбить тебя в землю.$B$BТы $gготов:готова; с ним сразиться?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выйдите на арену в Амфитеатре Страданий и победите Коррака Кровопуска! Потом вернитесь к троллю-прислужнику Водину и получите награду.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Награда – по окончании боя, приятель.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Коррак Кровопуск побежден',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к троллю-прислужнику Водину в Амфитеатр Страданий, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12937,'Исцеление раненых','Защитники приюта сражаются храбро, но с натиском железных дворфов они не справляются.$B$BС помощью земли, что ты $gсобрал:собрала;, я смогу сделать повязки, которые помогут исцелить раны некоторых бойцов. Чем больше защитников мы сможем перевязать и поднять на ноги, тем дольше тут продержимся.$B$BВозьми эти земляные примочки и с их помощью исцели раны защитников, павших у приюта. Подними столько бойцов, сколько сможешь, $n. Нам не нужно бессмысленных потерь.','Воины, которых ты исцелил, вновь встанут в строй, и мы сможем сдерживать натиск врага еще какое-то время. Но, если мы хотим победить железных дворфов, нам надо придумать, как ударить в них с тыла.','Тебе удалось поднять на ноги раненых защитников?','Вернитесь к Глыбоскалу Камнетесу в Приют Глыбоскала, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Исцеление раненых',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Защитники приюта сражаются храбро, но с натиском железных дворфов они не справляются.$B$BС помощью земли, что ты $gсобрал:собрала;, я смогу сделать повязки, которые помогут исцелить раны некоторых бойцов. Чем больше защитников мы сможем перевязать и поднять на ноги, тем дольше тут продержимся.$B$BВозьми эти земляные примочки и с их помощью исцели раны защитников, павших у приюта. Подними столько бойцов, сколько сможешь, $n. Нам не нужно бессмысленных потерь.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Воины, которых ты исцелил, вновь встанут в строй, и мы сможем сдерживать натиск врага еще какое-то время. Но, если мы хотим победить железных дворфов, нам надо придумать, как ударить в них с тыла.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось поднять на ноги раненых защитников?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Глыбоскалу Камнетесу в Приют Глыбоскала, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (12938,'Герцог','Нам нужна твоя помощь, $n. Мы еле-еле удерживаем Мрачный Свод. Как ты понимаешь, мы изрядно разозлили Короля-лича.$B$B<Барон фыркает.>$B$BПоговори с герцогом Ланкралом. Сейчас он здесь главный. Ты найдешь его в здании склепа.$B$BНе заставляй его ждать.','Поговорите с герцогом Ланкралом в Мрачном Своде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Герцог',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нам нужна твоя помощь, $n. Мы еле-еле удерживаем Мрачный Свод. Как ты понимаешь, мы изрядно разозлили Короля-лича.$B$B<Барон фыркает.>$B$BПоговори с герцогом Ланкралом. Сейчас он здесь главный. Ты найдешь его в здании склепа.$B$BНе заставляй его ждать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с герцогом Ланкралом в Мрачном Своде.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12939,'Вызов чести','Наша первая операция пройдет на Диком уступе. Это такое место в Йотунхейме, сразу за горной грядой на западе.$B$BНа этой гряде солдаты врайкулов совершенствуются в боевых искусствах и проводят тренировочные поединки под руководством лучших воинов тана.$B$BВозьми это знамя и вызови на поединок нескольких воинов-врайкулов. Покажи им "скромные" приемчики, которыми владеет $gлюбой:любая:r; |3-6($r). Это их деморализует!$B$B<Герцог усмехается, его черные гнилые зубы тускло поблескивают в сумрачном освещении склепа.>','Может, вернешься туда и победишь ещё пару-тройку врайкулов?','Вернитесь к герцогу Ланкралу в Мрачный Свод, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вызов чести',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наша первая операция пройдет на Диком уступе. Это такое место в Йотунхейме, сразу за горной грядой на западе.$B$BНа этой гряде солдаты врайкулов совершенствуются в боевых искусствах и проводят тренировочные поединки под руководством лучших воинов тана.$B$BВозьми это знамя и вызови на поединок нескольких воинов-врайкулов. Покажи им "скромные" приемчики, которыми владеет $gлюбой:любая:r; |3-6($r). Это их деморализует!$B$B<Герцог усмехается, его черные гнилые зубы тускло поблескивают в сумрачном освещении склепа.>',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Может, вернешься туда и победишь ещё пару-тройку врайкулов?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к герцогу Ланкралу в Мрачный Свод, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (12940,'Кулек конфет','Кульки с конфетами можно найти в любой таверне. Ну – чего стоишь? Хватай конфетку!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кулек конфет',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Кульки с конфетами можно найти в любой таверне. Ну – чего стоишь? Хватай конфетку!',`offerrewardtext_loc8`);
