INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12942,'Черные крылья','Предательницы. Мы, хильды, всегда их недолюбливали!$B$BДавно пора наказать обитательниц Валькириона. Мы сохранили верность Ториму, а они стали комнатными собачонками Короля-лича!$B$BПринявшие дар Короля зовутся валь\'кирами. Они парят на оперенных крыльях, подобно гарпиям.$B$BВалькирион расположен на северо-западе, за Храмом Штормов. Отправляйся туда и убей этих крылатых волчиц, сестра. Убей всех, кого сможешь. А потом возвращайся сюда и получишь хорошее вознаграждение.','По заданию Ивы Мстительной из деревни Бруннхильдар отправляйтесь в Валькирион и убейте 12 рождающихся валь\'кир.','Ты нашла лагерь Бронзоборода?','Вернитесь к Иве Мстительной в деревню Бруннхильдар, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Черные крылья',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Предательницы. Мы, хильды, всегда их недолюбливали!$B$BДавно пора наказать обитательниц Валькириона. Мы сохранили верность Ториму, а они стали комнатными собачонками Короля-лича!$B$BПринявшие дар Короля зовутся валь\'кирами. Они парят на оперенных крыльях, подобно гарпиям.$B$BВалькирион расположен на северо-западе, за Храмом Штормов. Отправляйся туда и убей этих крылатых волчиц, сестра. Убей всех, кого сможешь. А потом возвращайся сюда и получишь хорошее вознаграждение.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По заданию Ивы Мстительной из деревни Бруннхильдар отправляйтесь в Валькирион и убейте 12 рождающихся валь\'кир.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты нашла лагерь Бронзоборода?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Иве Мстительной в деревню Бруннхильдар, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12943,'Указ Мрачного Свода','Тан Уфранг Могущественный засел в своем зале с видом на Дикий уступ. Я неплохо его изучил. Тан – терпеливый врайкул, неплохой стратег и воин. Насколько я его знаю, он постарается выбрать наиболее благоприятное время, поскольку не склонен переоценивать свои возможности в грядущей битве.$B$BОн нужен мне мертвым!$B$BЯ составил декрет. Зачитай его тану.$B$B<Герцог усмехается.>$B$BЭто заставит его... ну, как минимум, занервничать.','Зачитайте указ Мрачного Свода, составленный герцогом Ланкралом, тану Уфрангу Могущественному, после чего убейте Уфранга.','<Герцог Ланкрал одобрительно кивает, выслушав ваш доклад об успешном выполнении задания.>$B$BМы сражаемся с врагом, который во всех отношениях больше нас: и по численности, и по росту. Чтобы победить в этой битве, мы должны их обхитрить. Взять умом, а не силой!$B$BТеперь Уфранг мертв, и это дает нам преимущество в Йотунхейме. А преимуществом надо пользоваться!','Моя разведка доносит, что Уфранг еще жив.$B$BТы что, не умеешь читать, $R','Вернитесь к герцогу Ланкралу в Мрачный Свод, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Указ Мрачного Свода',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тан Уфранг Могущественный засел в своем зале с видом на Дикий уступ. Я неплохо его изучил. Тан – терпеливый врайкул, неплохой стратег и воин. Насколько я его знаю, он постарается выбрать наиболее благоприятное время, поскольку не склонен переоценивать свои возможности в грядущей битве.$B$BОн нужен мне мертвым!$B$BЯ составил декрет. Зачитай его тану.$B$B<Герцог усмехается.>$B$BЭто заставит его... ну, как минимум, занервничать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Зачитайте указ Мрачного Свода, составленный герцогом Ланкралом, тану Уфрангу Могущественному, после чего убейте Уфранга.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Герцог Ланкрал одобрительно кивает, выслушав ваш доклад об успешном выполнении задания.>$B$BМы сражаемся с врагом, который во всех отношениях больше нас: и по численности, и по росту. Чтобы победить в этой битве, мы должны их обхитрить. Взять умом, а не силой!$B$BТеперь Уфранг мертв, и это дает нам преимущество в Йотунхейме. А преимуществом надо пользоваться!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Моя разведка доносит, что Уфранг еще жив.$B$BТы что, не умеешь читать, $R',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к герцогу Ланкралу в Мрачный Свод, что в Ледяной Короне.',`completedtext_loc8`);
