INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (12948,'Чемпион Амфитеатра Страданий','Все, $gдруг мой:красавица;, это будет последний бой! Самый последний – и самый трудный. Твой соперник – чемпион среди врайкулов из степей Ледяной Короны, и он жаждет крови! Если сумеешь его победить, ты станешь безоговорочным чемпионом Амфитеатра Страданий! Мы с тобой разбогатеем на этой схватке!$B$BКогда будешь $gготов:готова;, дай мне знать, и мы сразу начнем.','Выйдите на арену в Амфитеатре Страданий и победите Владофа Мясника! Потом возвращайтесь к троллю-прислужнику Водину и получите награду.','Награда – по окончании боя, приятель.','Владоф Мясник побежден','Вернитесь к троллю-прислужнику Водину в Амфитеатр Страданий, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чемпион Амфитеатра Страданий',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Все, $gдруг мой:красавица;, это будет последний бой! Самый последний – и самый трудный. Твой соперник – чемпион среди врайкулов из степей Ледяной Короны, и он жаждет крови! Если сумеешь его победить, ты станешь безоговорочным чемпионом Амфитеатра Страданий! Мы с тобой разбогатеем на этой схватке!$B$BКогда будешь $gготов:готова;, дай мне знать, и мы сразу начнем.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выйдите на арену в Амфитеатре Страданий и победите Владофа Мясника! Потом возвращайтесь к троллю-прислужнику Водину и получите награду.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Награда – по окончании боя, приятель.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Владоф Мясник побежден',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к троллю-прислужнику Водину в Амфитеатр Страданий, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12949,'Ключ от кандалов','$C, ключ от моих кандалов висит на шее у инструктора Хрегера там, снаружи.$B$BМожет быть, ты сумеешь добыть этот ключ путем отделения его головы от соответствующей шеи?','Добудьте ключ от цепей Вэлена и отдайте его Вэлену Разоблаченному в Зале Уфранга.','Ключ у тебя?','Вернитесь к Вэлену Разоблаченному в Мрачный Свод, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ключ от кандалов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$C, ключ от моих кандалов висит на шее у инструктора Хрегера там, снаружи.$B$BМожет быть, ты сумеешь добыть этот ключ путем отделения его головы от соответствующей шеи?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте ключ от цепей Вэлена и отдайте его Вэлену Разоблаченному в Зале Уфранга.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ключ у тебя?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Вэлену Разоблаченному в Мрачный Свод, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (12950,'Кулек конфет','Кульки с конфетами можно найти в любой таверне. Ну – чего стоишь? Хватай конфетку!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кулек конфет',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Кульки с конфетами можно найти в любой таверне. Ну – чего стоишь? Хватай конфетку!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (12951,'Известия для барона','Самое важное, что ты сейчас сможешь сделать – это вернуться в Мрачный Свод и сообщить барону Раздору, что у меня ничего не вышло.$B$BВидишь ли, я был не единственным пленником этих дьявольских врайкулов. Они захватили весь мой отряд рыцарей смерти.$B$BЯ должен был догадаться... должен был заметить ловушку... но к чему теперь плакать о пролитом молоке?!$B$BУходи, пока они не схватили и тебя тоже! Увидимся в Своде.','Поговорите с бароном Раздором в Мрачном Своде.','Что?! Мы не можем позволить себе потерять даже одного рыцаря смерти, не говоря уж о целом отряде!!!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Известия для барона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Самое важное, что ты сейчас сможешь сделать – это вернуться в Мрачный Свод и сообщить барону Раздору, что у меня ничего не вышло.$B$BВидишь ли, я был не единственным пленником этих дьявольских врайкулов. Они захватили весь мой отряд рыцарей смерти.$B$BЯ должен был догадаться... должен был заметить ловушку... но к чему теперь плакать о пролитом молоке?!$B$BУходи, пока они не схватили и тебя тоже! Увидимся в Своде.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с бароном Раздором в Мрачном Своде.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что?! Мы не можем позволить себе потерять даже одного рыцаря смерти, не говоря уж о целом отряде!!!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12952,'Огранка камней','Мой талант пропадает зря в этом проклятом месте! Столько лет я учился искусству огранки камней – и вот, теперь у меня совершенно нет материалов! Послушай, не $gмог:могла; бы ты принести мне несколько камней в обмен на кое-какие секреты мастерства? Я мог бы поведать тебе, как получать идеальные камни с улучшенными характеристиками, обрабатывая драгоценные камни Нордскола высокого качества.','Принесите два огромных цитрина, два темных нефрита и два сумрачных кристалла Картеру Тиффенсу в Лагерь Возмездия.','Это нужно будет сделать. Я могу научить тебя искусству безупречной огранки, а также доказать свои навыки.','Я научу тебя навыкам огранки драгоценных камней.','Вернитесь к Картеру Тиффенсу в Лагерь Возмездия, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Огранка камней',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мой талант пропадает зря в этом проклятом месте! Столько лет я учился искусству огранки камней – и вот, теперь у меня совершенно нет материалов! Послушай, не $gмог:могла; бы ты принести мне несколько камней в обмен на кое-какие секреты мастерства? Я мог бы поведать тебе, как получать идеальные камни с улучшенными характеристиками, обрабатывая драгоценные камни Нордскола высокого качества.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите два огромных цитрина, два темных нефрита и два сумрачных кристалла Картеру Тиффенсу в Лагерь Возмездия.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это нужно будет сделать. Я могу научить тебя искусству безупречной огранки, а также доказать свои навыки.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я научу тебя навыкам огранки драгоценных камней.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Картеру Тиффенсу в Лагерь Возмездия, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12953,'Гори, Валькирион, гори','Вот тебе ящик с зажигательными гарпунами. Там, снаружи, стоят гарпунные пушки и стога сена.$B$BМожет быть, Ива оценит твои старания и щедро тебя наградит.','С помощью валькирионских гарпунных пушек подожгите 6 валькирионских стогов сена.','Вот это мне нравится! Да, у этих предательниц теперь новый хозяин, но они никогда не забудут прощальный подарок своих сестер.','Ты нашла лагерь Бронзоборода?','Вернитесь к Иве Мстительной в деревню Бруннхильдар, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гори, Валькирион, гори',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот тебе ящик с зажигательными гарпунами. Там, снаружи, стоят гарпунные пушки и стога сена.$B$BМожет быть, Ива оценит твои старания и щедро тебя наградит.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','С помощью валькирионских гарпунных пушек подожгите 6 валькирионских стогов сена.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот это мне нравится! Да, у этих предательниц теперь новый хозяин, но они никогда не забудут прощальный подарок своих сестер.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты нашла лагерь Бронзоборода?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Иве Мстительной в деревню Бруннхильдар, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (12954,'Амфитеатр Страданий: Иггдрас!','А я все думал, когда ж ты придешь, $n! $GЧемпион:Чемпионка; Кольца Крови вновь на арене! Народ валом повалит, можешь не сомневаться! Мы разбогатеем, $gдружище:подруга;! ОЗОЛОТИМСЯ!$B$BЯ тебе вот что скажу: весь Зул\'Драк – это такое большое отхожее место для ледяных троллей. Но кого это волнует, верно? Мы с тобой просто делаем деньги!$B$BТы знаешь правила, $n. Когда будешь $gготов:готова;, дай мне знать, и мы сразу начнем. Устроим им представление!','Выйдите на арену в Амфитеатре Страданий и победите Иггдраса! Потом вернитесь к троллю-прислужнику Водину и получите награду.','Слушай, а я тебя знаю! Разговоры о твоей блестящей победе в Кольце Крови не умолкали в течение нескольких месяцев! Жалко, что ты не явился на следующий чемпионат, чтобы подтвердить свое звание чемпиона! Хотя, может, оно и правильно. Как говорится, как нажито, так и прожито. По крайней мере, ты до сих пор жив.','Никаких выплат, пока бой не закончен, $Gдружище:подруга;.','Иггдрас побежден','Вернитесь к троллю-прислужнику Водину в Амфитеатр Страданий, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Амфитеатр Страданий: Иггдрас!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А я все думал, когда ж ты придешь, $n! $GЧемпион:Чемпионка; Кольца Крови вновь на арене! Народ валом повалит, можешь не сомневаться! Мы разбогатеем, $gдружище:подруга;! ОЗОЛОТИМСЯ!$B$BЯ тебе вот что скажу: весь Зул\'Драк – это такое большое отхожее место для ледяных троллей. Но кого это волнует, верно? Мы с тобой просто делаем деньги!$B$BТы знаешь правила, $n. Когда будешь $gготов:готова;, дай мне знать, и мы сразу начнем. Устроим им представление!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выйдите на арену в Амфитеатре Страданий и победите Иггдраса! Потом вернитесь к троллю-прислужнику Водину и получите награду.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Слушай, а я тебя знаю! Разговоры о твоей блестящей победе в Кольце Крови не умолкали в течение нескольких месяцев! Жалко, что ты не явился на следующий чемпионат, чтобы подтвердить свое звание чемпиона! Хотя, может, оно и правильно. Как говорится, как нажито, так и прожито. По крайней мере, ты до сих пор жив.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Никаких выплат, пока бой не закончен, $Gдружище:подруга;.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Иггдрас побежден',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к троллю-прислужнику Водину в Амфитеатр Страданий, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12955,'Унижение соперников','Кх-кх...$B$B<Прыгун откашливается, прочищая горло.>$B$BПрошу прощения. Иногда я не очень понятно изъясняюсь. Ну, ты знаешь, как это бывает.$B$BЯ просто хотел убедиться, что ты помнишь, что надо делать, когда придешь на Дикий уступ в горах на западе отсюда, а именно: вызвать на поединок, побить и тем самым унизить в глазах врайкулов их лучших бойцов.$B$BОсобенно это касается Сигрид Дитя Льда, Ефрема Верного, Тинки Свистопляс и Ону\'Зуна.','Вызовите на дуэль и победите Сигрид Дитя Льда, Ефрема Верного, Ону\'Зуна и Тинки Свистопляс по поручению Прыгуна из Мрачного Свода.','Ты еще здесь?$B$BИди и побей их.','Вернитесь к Прыгуну в Мрачный Свод, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Унижение соперников',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кх-кх...$B$B<Прыгун откашливается, прочищая горло.>$B$BПрошу прощения. Иногда я не очень понятно изъясняюсь. Ну, ты знаешь, как это бывает.$B$BЯ просто хотел убедиться, что ты помнишь, что надо делать, когда придешь на Дикий уступ в горах на западе отсюда, а именно: вызвать на поединок, побить и тем самым унизить в глазах врайкулов их лучших бойцов.$B$BОсобенно это касается Сигрид Дитя Льда, Ефрема Верного, Тинки Свистопляс и Ону\'Зуна.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вызовите на дуэль и победите Сигрид Дитя Льда, Ефрема Верного, Ону\'Зуна и Тинки Свистопляс по поручению Прыгуна из Мрачного Свода.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты еще здесь?$B$BИди и побей их.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Прыгуну в Мрачный Свод, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12956,'Лучик надежды','Это явно не просто обычный кусок металла.$b$bВ отличие от обыкновенной руды эта – твердая, но не ломкая, удивительно легкая и вдобавок еще светится собственным светом.$b$bТорим непременно заинтересуется вашей находкой.','Отнесите очищенный светящийся металл Ториму в Храм Штормов.','Угрюмое лицо Торима озаряется радостью, когда он понимает, что именно вы ему принесли.','Что это там у тебя?','Вернитесь к Ториму в Храм Штормов, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лучик надежды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это явно не просто обычный кусок металла.$b$bВ отличие от обыкновенной руды эта – твердая, но не ломкая, удивительно легкая и вдобавок еще светится собственным светом.$b$bТорим непременно заинтересуется вашей находкой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите очищенный светящийся металл Ториму в Храм Штормов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Угрюмое лицо Торима озаряется радостью, когда он понимает, что именно вы ему принесли.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что это там у тебя?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ториму в Храм Штормов, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12957,'Рабы Закаленных Бурей','На юго-западе, в западной части Снежных равнин, у железных дворфов есть шахта. Они свозят туда пленных механогномов, слуг Хранителя Мимира, и заставляют их добывать руду.$B$BЯ не знаю, откуда взялись эти механогномы и что они стали бы делать, если бы обрели свободу, но, может быть, они станут нашими союзниками и смогут нам чем-то помочь.$B$BОтправляйся на Замерзший рудник, $n, и освободи пленников. И спроси, может быть, они станут сражаться бок о бок с нами против тирании железных дворфов.','Я надеялся, что большинство освобожденных пленников все-таки согласится присоединиться к нам, но я не могу их винить. Хороший союзник – это союзник по доброй воле, и мы очень тебе благодарны за помощь.','Ты $Gосвободил:освободила; рабов?','Вернитесь к Глыбоскалу Камнетесу в Приют Глыбоскала, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рабы Закаленных Бурей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На юго-западе, в западной части Снежных равнин, у железных дворфов есть шахта. Они свозят туда пленных механогномов, слуг Хранителя Мимира, и заставляют их добывать руду.$B$BЯ не знаю, откуда взялись эти механогномы и что они стали бы делать, если бы обрели свободу, но, может быть, они станут нашими союзниками и смогут нам чем-то помочь.$B$BОтправляйся на Замерзший рудник, $n, и освободи пленников. И спроси, может быть, они станут сражаться бок о бок с нами против тирании железных дворфов.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я надеялся, что большинство освобожденных пленников все-таки согласится присоединиться к нам, но я не могу их винить. Хороший союзник – это союзник по доброй воле, и мы очень тебе благодарны за помощь.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gосвободил:освободила; рабов?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Глыбоскалу Камнетесу в Приют Глыбоскала, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (12958,'Одна богатая торговая компания заказала мне коллекцию амулетов из кровавого нефрита для продажи в Нижней Шахте. Если ты принесешь мне амулет, получишь в награду значок даларанского ювелира.','Создайте амулет из кровавого нефрита, объединив амулет врайкулов, темный нефрит и кровавый камень, после чего принесите его Тимоти Джонсу в Даларан. Амулет врайкулов можно добыть с любого врайкула в Нордсколе.','Вот тебе значок даларанского ювелира, как и было обещано. Приходи завтра. Наверняка мне понадобится что-то еще!','Вернитесь к Тимоти Джонсу в ювелирный магазин Картье и компании, что в Даларане.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Одна богатая торговая компания заказала мне коллекцию амулетов из кровавого нефрита для продажи в Нижней Шахте. Если ты принесешь мне амулет, получишь в награду значок даларанского ювелира.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Создайте амулет из кровавого нефрита, объединив амулет врайкулов, темный нефрит и кровавый камень, после чего принесите его Тимоти Джонсу в Даларан. Амулет врайкулов можно добыть с любого врайкула в Нордсколе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот тебе значок даларанского ювелира, как и было обещано. Приходи завтра. Наверняка мне понадобится что-то еще!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тимоти Джонсу в ювелирный магазин Картье и компании, что в Даларане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (12959,'Заказ от торговой компании: блестящая статуэтка из бивня','Одна богатая торговая компания заказала мне коллекцию блестящих статуэток из бивня для продажи в Нижней Шахте. Если ты принесешь мне такую статуэтку, получишь в награду значок даларанского ювелира.','Создайте блестящую статуэтку из бивня, объединив кальцедоний, сумрачный кристалл и северный бивень, и принесите ее Тимоти Джонсу в Даларан.$B$BДля того чтобы раздобыть северный бивень, вам нужно будет убить любого черпорога или мамонта в Нордсколе.','Вот тебе значок даларанского ювелира, как и было обещано. Приходи завтра. Наверняка мне понадобится что-то еще!','Вернитесь к Тимоти Джонсу в ювелирный магазин Картье и компании, что в Даларане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Заказ от торговой компании: блестящая статуэтка из бивня',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Одна богатая торговая компания заказала мне коллекцию блестящих статуэток из бивня для продажи в Нижней Шахте. Если ты принесешь мне такую статуэтку, получишь в награду значок даларанского ювелира.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Создайте блестящую статуэтку из бивня, объединив кальцедоний, сумрачный кристалл и северный бивень, и принесите ее Тимоти Джонсу в Даларан.$B$BДля того чтобы раздобыть северный бивень, вам нужно будет убить любого черпорога или мамонта в Нордсколе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот тебе значок даларанского ювелира, как и было обещано. Приходи завтра. Наверняка мне понадобится что-то еще!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тимоти Джонсу в ювелирный магазин Картье и компании, что в Д