INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (12962,'Заказ от торговой компании: Реликвия из сияющей брони','Одна богатая торговая компания заказала мне коллекцию реликвий из сияющей брони для продажи в Нижней Шахте. Если ты принесешь мне реликвию, получишь в награду значок даларанского ювелира.','Создайте реликвию Сияющей брони из осколка элементальной брони, кровавого камня и огромного цитрина и принесите ее Тимоти Джонсу в Даларан. Осколок элементальной брони можно добыть у любого элементаля-загробника в Нордсколе.','Вот тебе значок даларанского ювелира, как и было обещано. Приходи завтра. Наверняка мне понадобится что-то еще!','Вернитесь к Тимоти Джонсу в ювелирный магазин Картье и компании, что в Даларане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Заказ от торговой компании: Реликвия из сияющей брони',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Одна богатая торговая компания заказала мне коллекцию реликвий из сияющей брони для продажи в Нижней Шахте. Если ты принесешь мне реликвию, получишь в награду значок даларанского ювелира.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Создайте реликвию Сияющей брони из осколка элементальной брони, кровавого камня и огромного цитрина и принесите ее Тимоти Джонсу в Даларан. Осколок элементальной брони можно добыть у любого элементаля-загробника в Нордсколе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот тебе значок даларанского ювелира, как и было обещано. Приходи завтра. Наверняка мне понадобится что-то еще!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тимоти Джонсу в ювелирный магазин Картье и компании, что в Даларане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (12963,'Заказ от торговой компании: реликвия Восходящего Солнца','Одна богатая торговая компания заказала мне коллекцию реликвий Восходящего Солнца для продажи в Нижней Шахте. Если ты принесешь мне реликвию, получишь в награду значок даларанского ювелира.','Создайте реликвию Восходящего Солнца из реликвии Плети, солнечного хрусталя и сумрачного кристалла и принесите ее Тимоти Джонсу в Даларан. Реликвию Плети можно добыть у любого последователя Плети в Нордсколе.','Вот тебе значок даларанского ювелира, как и было обещано. Приходи завтра. Наверняка мне понадобится что-то еще!','Вернитесь к Тимоти Джонсу в ювелирный магазин Картье и компании, что в Даларане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Заказ от торговой компании: реликвия Восходящего Солнца',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Одна богатая торговая компания заказала мне коллекцию реликвий Восходящего Солнца для продажи в Нижней Шахте. Если ты принесешь мне реликвию, получишь в награду значок даларанского ювелира.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Создайте реликвию Восходящего Солнца из реликвии Плети, солнечного хрусталя и сумрачного кристалла и принесите ее Тимоти Джонсу в Даларан. Реликвию Плети можно добыть у любого последователя Плети в Нордсколе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот тебе значок даларанского ювелира, как и было обещано. Приходи завтра. Наверняка мне понадобится что-то еще!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тимоти Джонсу в ювелирный магазин Картье и компании, что в Даларане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (12964,'Темная руда','В Застывшей шахте, в юго-западной части Снежных равнин, у железных дворфов из клана Закаленных Бурей есть рудник, где работают их рабы.$B$BЭто достаточно далеко отсюда, и мы не смогли выяснить, что именно там происходит, но мои разведчики сообщают, что там вроде бы добывают какую-то темную руду тошнотворного вида.','Вернитесь к Глыбоскалу Камнетесу в Приют Глыбоскала, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Темная руда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В Застывшей шахте, в юго-западной части Снежных равнин, у железных дворфов из клана Закаленных Бурей есть рудник, где работают их рабы.$B$BЭто достаточно далеко отсюда, и мы не смогли выяснить, что именно там происходит, но мои разведчики сообщают, что там вроде бы добывают какую-то темную руду тошнотворного вида.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Глыбоскалу Камнетесу в Приют Глыбоскала, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12965,'Дары Локена','Предводителя железных дворфов из клана Закаленных Бурей зовут руновидец Валдуран. Говорят, что его хозяин, Хранитель Локен, захвативший Ульдуар, передал Валдурану очень мощные артефакты Титанов.$B$BЭтим, наверное, и объясняется сила и ярость свирепых воинов клана Закаленных Бурей.$B$BОбиталище Валдурана – Нидавелир – находится на юго-западе, по ту сторону Снежных равнин. Отправляйся туда, $n, и попытайся нейтрализовать его силу. Уничтожь дары Локена и помоги нам лишить силы его последователей.','Это правда? Вальдуран обладает мощными реликвиями титанов? Ты $Gуничтожил:уничтожила; их?','Вернитесь к Глыбоскалу Камнетесу в Приют Глыбоскала, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дары Локена',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Предводителя железных дворфов из клана Закаленных Бурей зовут руновидец Валдуран. Говорят, что его хозяин, Хранитель Локен, захвативший Ульдуар, передал Валдурану очень мощные артефакты Титанов.$B$BЭтим, наверное, и объясняется сила и ярость свирепых воинов клана Закаленных Бурей.$B$BОбиталище Валдурана – Нидавелир – находится на юго-западе, по ту сторону Снежных равнин. Отправляйся туда, $n, и попытайся нейтрализовать его силу. Уничтожь дары Локена и помоги нам лишить силы его последователей.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Это правда? Вальдуран обладает мощными реликвиями титанов? Ты $Gуничтожил:уничтожила; их?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Глыбоскалу Камнетесу в Приют Глыбоскала, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (12966,'Мимо него не пройдешь','<Йоккум внимательно выслушивает вашу просьбу, потом долго молчит, обдумывая ответ.>$b$bЗначит, это тебя мы должны благодарить за избавление от Фьорна?$b$bДа, это правда, ты $gпомог:помогла; нам в трудную минуту, но нам еще предстоит потрудиться, чтобы восстановить отношения с Торимом.$b$bЯ позволю Ньормельду заново перековать те доспехи, которые мы подарили Повелителю Бурь давным-давно. Считай это вознаграждением за избавление от Фьорна.$b$bНьормельд сейчас занимается восстановлением наковальни Фьорна. Там ты его и найдешь.','По поручению короля Йоккума из Дун Ниффелема разыщите Ньормельда у Наковальни Фьорна.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мимо него не пройдешь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Йоккум внимательно выслушивает вашу просьбу, потом долго молчит, обдумывая ответ.>$b$bЗначит, это тебя мы должны благодарить за избавление от Фьорна?$b$bДа, это правда, ты $gпомог:помогла; нам в трудную минуту, но нам еще предстоит потрудиться, чтобы восстановить отношения с Торимом.$b$bЯ позволю Ньормельду заново перековать те доспехи, которые мы подарили Повелителю Бурь давным-давно. Считай это вознаграждением за избавление от Фьорна.$b$bНьормельд сейчас занимается восстановлением наковальни Фьорна. Там ты его и найдешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По поручению короля Йоккума из Дун Ниффелема разыщите Ньормельда у Наковальни Фьорна.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12967,'Сражение со стихиями','По поручению Ньормельда отправляйтесь к наковальне Фьорна вместе с Храппи и помогите ему убить 10 пылающих загробников.','Ты молодец, $R. Я непременно скажу королю о твоем славном деянии.\n\nНаковальня уже почти остыла. Увидимся в Дун Ниффелеме!','Удалось ли тебе привести Снорри к очередной победе, $C?','Вернитесь к Ньормельду в Наковальню Фьорна, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сражение со стихиями',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По поручению Ньормельда отправляйтесь к наковальне Фьорна вместе с Храппи и помогите ему убить 10 пылающих загробников.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты молодец, $R. Я непременно скажу королю о твоем славном деянии.\n\nНаковальня уже почти остыла. Увидимся в Дун Ниффелеме!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось ли тебе привести Снорри к очередной победе, $C?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ньормельду в Наковальню Фьорна, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12968,'Безрассудство Юльды','Ты нашла лагерь Бронзоборода?','Вернитесь к Иве Мстительной в деревню Бруннхильдар, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Безрассудство Юльды',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты нашла лагерь Бронзоборода?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Иве Мстительной в деревню Бруннхильдар, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12969,'Это твой гоблин?','Думаю, это тот мелкий зеленокожий, которого ты ищешь. На твоем месте я бы поспешила вмешаться, пока эта хильда не разорвала его на части.$B$BКруг хильд в самом разгаре, так что все вызовы должны быть приняты. Ничто не должно помешать тебе занять место этого гоблина.','Бросьте вызов Агнете Тирсдоттар, чтобы спасти Зива Искрошипа. Добившись успеха, возвращайтесь к Лок\'лире Карге из деревни Бруннхильдар.','Хорошая работа. Похоже, наша сделка принесла удовлетворение обеим сторонам.','Ты наказала этих предательниц?','Вернитесь к Лок\'лире Карге в деревню Бруннхильдар, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Это твой гоблин?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Думаю, это тот мелкий зеленокожий, которого ты ищешь. На твоем месте я бы поспешила вмешаться, пока эта хильда не разорвала его на части.$B$BКруг хильд в самом разгаре, так что все вызовы должны быть приняты. Ничто не должно помешать тебе занять место этого гоблина.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Бросьте вызов Агнете Тирсдоттар, чтобы спасти Зива Искрошипа. Добившись успеха, возвращайтесь к Лок\'лире Карге из деревни Бруннхильдар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошая работа. Похоже, наша сделка принесла удовлетворение обеим сторонам.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты наказала этих предательниц?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лок\'лире Карге в деревню Бруннхильдар, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12970,'Круг хильд','Не знаю, может, это прошло для тебя незамеченным, но, сразив свою первую хильду в рукопашном бою, тебе довелось вступить в Круг хильд – серьезное состязание между хильдами за право властвовать с благословения Торима.$B$BКруг хильд – причина моего содержания в неволе. Я хотела принять участие в состязаниях, но была для этого слишком стара и вряд ли могла бы биться на равных с кем-то из хильд.$B$BУ меня есть к тебе одно предложение, выслушай меня, если это тебе интересно.','Выслушайте предложение Лок\'лиры Карги.','Договорились. Ты примешь участие в состязаниях Круга хильд и с моей помощью восстановишь великого Торима на его законном месте.','Тише-тише, а то мы можем вызвать подозрения...','Вернитесь к Лок\'лире Карге в деревню Бруннхильдар, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Круг хильд',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не знаю, может, это прошло для тебя незамеченным, но, сразив свою первую хильду в рукопашном бою, тебе довелось вступить в Круг хильд – серьезное состязание между хильдами за право властвовать с благословения Торима.$B$BКруг хильд – причина моего содержания в неволе. Я хотела принять участие в состязаниях, но была для этого слишком стара и вряд ли могла бы биться на равных с кем-то из хильд.$B$BУ меня есть к тебе одно предложение, выслушай меня, если это тебе интересно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выслушайте предложение Лок\'лиры Карги.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Договорились. Ты примешь участие в состязаниях Круга хильд и с моей помощью восстановишь великого Торима на его законном месте.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тише-тише, а то мы можем вызвать подозрения...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лок\'лире Карге в деревню Бруннхильдар, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (12971,'Вызов принят','Начнем. Хорошие новости – в том, что после победы над Агнеттой тебе достается место в следующем круге состязаний.$B$BПлохие новости – в том, что все твои новые соперницы тоже победили кого-то в первом круге. Так что легких побед не жди.','Сразите 6 дуэлянтов-победителей по заданию Лок\'лиры Карги из деревни Бруннхильдар.','Вернитесь к Лок\'лире Карге в деревню Бруннхильдар, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вызов принят',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Начнем. Хорошие новости – в том, что после победы над Агнеттой тебе достается место в следующем круге состязаний.$B$BПлохие новости – в том, что все твои новые соперницы тоже победили кого-то в первом круге. Так что легких побед не жди.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сразите 6 дуэлянтов-победителей по заданию Лок\'лиры Карги из деревни Бруннхильдар.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лок\'лире Карге в деревню Бруннхильдар, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (12972,'Тебе понадобится медведь','В первых раундах Круга хильд тебе сопутствовал успех. Чтобы продвинуться дальше, тебе понадобится собственный боевой медведь.$B$BК сожалению, хильды их просто так не раздают. Тебе придется выйти $gпобедителем:победительницей; из настоящего сражения, а не гладиаторского боя.$B$BБруннхильдарские хильды жестоко враждуют с Сынами Ходира, бывшими союзниками Торима. Поговори с Бриджаной неподалеку от деревни – быть может, есть способ помочь им и одновременно проявить себя должным образом.','Поговорите с Бриджаной неподалеку от деревни Бруннхильдар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тебе понадобится медведь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В первых раундах Круга хильд тебе сопутствовал успех. Чтобы продвинуться дальше, тебе понадобится собственный боевой медведь.$B$BК сожалению, хильды их просто так не раздают. Тебе придется выйти $gпобедителем:победительницей; из настоящего сражения, а не гладиаторского боя.$B$BБруннхильдарские хильды жестоко враждуют с Сынами Ходира, бывшими союзниками Торима. Поговори с Бриджаной неподалеку от деревни – быть может, есть способ помочь им и одновременно проявить себя должным образом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Бриджаной неподалеку от деревни Бруннхильдар.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`endtext_loc8`) VALUES (12973,'Братья Бронзобороды','Вот оно! Наконец-то у нас есть краеугольный камень... Какая красота! Я немало попутешествовал по миру, но эта вещь снова приводит меня в восторг. Хотя сейчас явно не время застывать в эстетическом ступоре, восхищаться и ахать я буду потом, а сейчас надо скорее выбираться отсюда!$B$BЗабирайся в мой ветролет и прикрывай нас от железных дворфов!','Прикрывайте Бранна и ветролет, пока не доберетесь до Ледяной крепости.','Тысяч извинений, $Gмой:моя; $Gмальчик:девочка;! Я был полностью захвачен моментом и совершенно не заметил тебя...','Сопроводить Бранна Бронзоборода в Ледяную крепость.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Братья Бронзобороды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот оно! Наконец-то у нас есть краеугольный камень... Какая красота! Я немало попутешествовал по миру, но эта вещь снова приводит меня в восторг. Хотя сейчас явно не время застывать в эстетическом ступоре, восхищаться и ахать я буду потом, а сейчас надо скорее выбираться отсюда!$B$BЗабирайся в мой ветролет и прикрывай нас от железных дворфов!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Прикрывайте Бранна и ветролет, пока не доберетесь до Ледяной крепости.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тысяч извинений, $Gмой:моя; $Gмальчик:девочка;! Я был полностью захвачен моментом и совершенно не заметил тебя...',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Сопроводить Бранна Бронзоборода в Ледяную крепость.',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (12974,'Призыв бойцовского клуба','Пф-ф, разве это бой?! Это просто парочка неумех, скачущих вокруг знамени.$B$BХочешь узнать, что такое настоящий бой? Потому что, если вдруг есть у тебя такое желание, я тебе подскажу одно место, где все по-серьезному.$B$B$gСлышал:Слышала; когда-нибудь о Гаргтоке и Водине – гоблине и тролле, которые держат Кольцо Крови в Запределье? Так вот, они сейчас здесь, в Нордсколе. Хотят открыть новый бойцовский клуб в Зул\'Драке. Если тебе интересно, иди в Зул\'Драк, на восток от леса Хрустальной Песни. Найдешь их на большой арене, в самом центре. Скажи, что тебя прислал Ловкий Викерс!','Разыщите Гаргтокa в Амфитеатре Страданий в Зул\'Драке.','Тебя прислал Ловкий Викерс?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Призыв бойцовского клуба',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пф-ф, разве это бой?! Это просто парочка неумех, скачущих вокруг знамени.$B$BХочешь узнать, что такое настоящий бой? Потому что, если вдруг есть у тебя такое желание, я тебе подскажу одно место, где все по-серьезному.$B$B$gСлышал:Слышала; когда-нибудь о Гаргтоке и Водине – гоблине и тролле, которые держат Кольцо Крови в Запределье? Так вот, они сейчас здесь, в Нордсколе. Хотят открыть новый бойцовский клуб в Зул\'Драке. Если тебе интересно, иди в Зул\'Драк, на восток от леса Хрустальной Песни. Найдешь их на большой арене, в самом центре. Скажи, что тебя прислал Ловкий Викерс!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите Гаргтокa в Амфитеатре Страданий в Зул\'Драке.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебя прислал Ловкий Викерс?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (12975,'Мемориал','Торим наверняка рассказал тебе о трагических событиях, которые нас разделили.$b$bДело было в Громовержье, к северо-востоку отсюда. Замерзшие окаменелости до сих пор служат напоминанием о том черном дне – как и духи погибших, обитающие в этом месте.$b$bЕсли мы собираемся помириться с Торимом и простить его за дела тех давних дней, надо как-то то очистить Громовержье... Быть может, возвести мемориал в память о павших в знак того, что мы всей душой хотим мира.$b$bОтправляйся туда, |3-6($r), и собери фрагменты рога Ходира, который разбили в тот день.','По заданию короля Йоккума из Дун Ниффелема соберите 8 фрагментов рога в Громовержье.','Вернитесь к Королю Йоккуму в Дун Ниффелем, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мемориал',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Торим наверняка рассказал тебе о трагических событиях, которые нас разделили.$b$bДело было в Громовержье, к северо-востоку отсюда. Замерзшие окаменелости до сих пор служат напоминанием о том черном дне – как и духи погибших, обитающие в этом месте.$b$bЕсли мы собираемся помириться с Торимом и простить его за дела тех давних дней, надо как-то то очистить Громовержье... Быть может, возвести мемориал в память о павших в знак того, что мы всей душой хотим мира.$b$bОтправляйся туда, |3-6($r), и собери фрагменты рога Ходира, который разбили в тот день.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По заданию короля Йоккума из Дун Ниффелема соберите 8 фрагментов рога в Громовержье.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Королю Йоккуму в Дун Ниффелем, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12976,'Памятник павшим','Отнеси эти фрагменты Ньормельду. Он использует куски этой священной реликвии для постройки могучего монумента.$b$bПусть он уймет боль в сердцах и излечит обиды и раны моего народа.$b$bПусть он станет ознаменованием новой эры, когда мы вновь будем сражаться на стороне Торима.$b$bИди, |3-6($c). Ньормельд ждет тебя.','По поручению короля Йоккума отнесите фрагменты рога Ходира Ньормельду в Дун Ниффелем.','<На глаза Ньормельда наворачиваются слезы, когда он высыпает на наковальню содержимое мешка.>\n\nРог Ходира...\n\nСвященный дар моему народу, который мы получили из рук самого Ходира, $R!\n\nКогда в следующий раз ты придешь в нашу крепость, ты увидишь плоды своих трудов.\n\nПрощай.','Ты $Gпринес:принесла; мне фрагменты рога Ходира, $R?','Вернитесь к Ньормельду в Дун Ниффелем, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Памятник павшим',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Отнеси эти фрагменты Ньормельду. Он использует куски этой священной реликвии для постройки могучего монумента.$b$bПусть он уймет боль в сердцах и излечит обиды и раны моего народа.$b$bПусть он станет ознаменованием новой эры, когда мы вновь будем сражаться на стороне Торима.$b$bИди, |3-6($c). Ньормельд ждет тебя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По поручению короля Йоккума отнесите фрагменты рога Ходира Ньормельду в Дун Ниффелем.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<На глаза Ньормельда наворачиваются слезы, когда он высыпает на наковальню содержимое мешка.>\n\nРог Ходира...\n\nСвященный дар моему народу, который мы получили из рук самого Ходира, $R!\n\nКогда в следующий раз ты придешь в нашу крепость, ты увидишь плоды своих трудов.\n\nПрощай.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gпринес:принесла; мне фрагменты рога Ходира, $R?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ньормельду в Дун Ниффелем, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12977,'Вы сослужили хорошую службу великанам Дун Ниффелема. Без вашей помощи они бы никогда не построили этот монумент.$b$bВы молча смотрите на монумент и осмысляете все его значение. Ваше сердце переполняется чувствами... а в голове появляются мысли и образы... вы чувствуете, как некая неодолимая сила побуждает вас к действию.$b$bПотом это ощущение проходит и вы понимаете, что надо делать. Беспокойные духи Громовержья должны упокоиться с миром.$b$bКогда вы отходите от монумента, вы вдруг обнаруживаете у себя в руках эфирный рог.','Убейте 5 ниффелемских прародителей и 5 неупокоенных дворфов из клана Зиморожденных в Громовержье.','Сильные порывы ветра кружатся вокруг рога, вызывая его звук эхом по всем окружающим горам.','Вернитесь к рогу Ходира в Дун Ниффелем, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы сослужили хорошую службу великанам Дун Ниффелема. Без вашей помощи они бы никогда не построили этот монумент.$b$bВы молча смотрите на монумент и осмысляете все его значение. Ваше сердце переполняется чувствами... а в голове появляются мысли и образы... вы чувствуете, как некая неодолимая сила побуждает вас к действию.$b$bПотом это ощущение проходит и вы понимаете, что надо делать. Беспокойные духи Громовержья должны упокоиться с миром.$b$bКогда вы отходите от монумента, вы вдруг обнаруживаете у себя в руках эфирный рог.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 5 ниффелемских прародителей и 5 неупокоенных дворфов из клана Зиморожденных в Громовержье.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Сильные порывы ветра кружатся вокруг рога, вызывая его звук эхом по всем окружающим горам.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к рогу Ходира в Дун Ниффелем, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12978,'Навстречу буре','Я, как и Глыбоскал, когда-то служил хранителям и был мастеровым в Ульдуаре, но после предательства Локена я обратил свой молот против наших новых недругов.$B$BКогда есть возможность, я собираю отряд, мы отправляемся на Нидавелир, чтобы помочь нашим защитникам. Однако долго им не продержаться.$B$BТы $gпоказал себя храбрым солдатом и верным союзником:умеешь сражаться и показала себя верной союзницей;. Может быть, ты возьмешь наше знамя и поведешь наши отряды на Нидавелир, крепость железных дворфов на юго-западе отсюда, на той стороне Снежных равнин?','Ты $Gвзял:взяла; молот в Нидавелире?','Вернитесь к Брюору Железорубу в Приют Глыбоскала, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Навстречу буре',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я, как и Глыбоскал, когда-то служил хранителям и был мастеровым в Ульдуаре, но после предательства Локена я обратил свой молот против наших новых недругов.$B$BКогда есть возможность, я собираю отряд, мы отправляемся на Нидавелир, чтобы помочь нашим защитникам. Однако долго им не продержаться.$B$BТы $gпоказал себя храбрым солдатом и верным союзником:умеешь сражаться и показала себя верной союзницей;. Может быть, ты возьмешь наше знамя и поведешь наши отряды на Нидавелир, крепость железных дворфов на юго-западе отсюда, на той стороне Снежных равнин?',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gвзял:взяла; молот в Нидавелире?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Брюору Железорубу в Приют Глыбоскала, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12979,'Доспехи тьмы','Этот темная пластина гораздо толще и крупнее остальных доспехов голема. Быстрый осмотр трупа голема дает все основания предположить, что это дополнительная укрепленная пластина, которую навинтили поверх обычного доспеха.$B$BЗачем железные дворфы добавили эту явно лишнюю деталь к броне своих боевых големов?$B$BМожет быть, Брюор Железоруб сможет ответить на этот вопрос, если вы принесете и покажете ему эти пластины боевых големов клана Закаленных Бурей.','Что это там у тебя?','Поговорите с Брюором Железорубом в Приюте Глыбоскала, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Доспехи тьмы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этот темная пластина гораздо толще и крупнее остальных доспехов голема. Быстрый осмотр трупа голема дает все основания предположить, что это дополнительная укрепленная пластина, которую навинтили поверх обычного доспеха.$B$BЗачем железные дворфы добавили эту явно лишнюю деталь к броне своих боевых големов?$B$BМожет быть, Брюор Железоруб сможет ответить на этот вопрос, если вы принесете и покажете ему эти пластины боевых големов клана Закаленных Бурей.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что это там у тебя?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Брюором Железорубом в Приюте Глыбоскала, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (12980,'Секрет доспехов','Какая-то странная латная пластина... Надо узнать о ней как можно больше. Вполне вероятно, что это одно из изделий Валдурана.$B$BОн положил много усилий для добычи, очистки и обработки такого металла.$B$BНа востоке отсюда, на северном склоне горы, есть Мастерская Мимира. Она давно не работает, но если нам повезет, может быть, там остался кто-нибудь из мастеров. Отнеси эту латную пластину туда и постарайся узнать о ней как можно больше.','Вернитесь к Брюору Железорубу в Приют Глыбоскала, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Секрет доспехов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Какая-то странная латная пластина... Надо узнать о ней как можно больше. Вполне вероятно, что это одно из изделий Валдурана.$B$BОн положил много усилий для добычи, очистки и обработки такого металла.$B$BНа востоке отсюда, на северном склоне горы, есть Мастерская Мимира. Она давно не работает, но если нам повезет, может быть, там остался кто-нибудь из мастеров. Отнеси эту латную пластину туда и постарайся узнать о ней как можно больше.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Брюору Железорубу в Приют Глыбоскала, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12981,'Жар и холод','Глядя на наковальню, вы вспоминаете свои недавние деяния – и особенно те, в результате которых вы сейчас принесли сюда этот артефакт.$b$bВы вдруг понимаете, что нужно сделать еще кое-что. Вся земля на востоке усыпана дымящимися обломками – осколками снарядов, оставшихся после боев.$b$bЕсли получится их остудить и собрать, у снежных великанов будет хороший запас металла, да и очистить район от "сувениров" войны – это тоже хорошее дело.','Идите к Промерзшему озеру, убейте хрупких загробников, обитающих в тех краях, и с помощью субстанции Льда остудите дымящиеся осколки у наковальни Фьорна. Потом соберите 6 кусков застывшего железа и вернитесь к наковальне Фьорна в Дун Ниффелем.','Яркое синее сияние окружает наковальню.','Вернитесь к наковальне Фьорна в Дун Ниффелем, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жар и холод',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Глядя на наковальню, вы вспоминаете свои недавние деяния – и особенно те, в результате которых вы сейчас принесли сюда этот артефакт.$b$bВы вдруг понимаете, что нужно сделать еще кое-что. Вся земля на востоке усыпана дымящимися обломками – осколками снарядов, оставшихся после боев.$b$bЕсли получится их остудить и собрать, у снежных великанов будет хороший запас металла, да и очистить район от "сувениров" войны – это тоже хорошее дело.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Идите к Промерзшему озеру, убейте хрупких загробников, обитающих в тех краях, и с помощью субстанции Льда остудите дымящиеся осколки у наковальни Фьорна. Потом соберите 6 кусков застывшего железа и вернитесь к наковальне Фьорна в Дун Ниффелем.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Яркое синее сияние окружает наковальню.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к наковальне Фьорна в Дун Ниффелем, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12982,'Пленники из ордена Черного Клинка','Теперь, когда я вернулся, барон наверняка захочет, чтобы я вновь собрал свой отряд. Армия Короля-лича уже скоро прорвется сюда, и мы не сможем их остановить без моих рыцарей смерти.$B$BТы ведь поможешь мне, $n?$B$BОтправляйся в Йотунхейм и освободи моих людей из этих проклятых клеток.$B$BСломай эти чертовы замки, в выборе средств ты $Gсвободен:свободна;. У врайкулов должны быть ключи...$B$BВ общем, делай что хочешь, но освободи моих людей!','Освободите 8 пленных рыцарей Черного Клинка по просьбе Вэлена Разоблаченного из Мрачного Свода. Пленников держат в клетках в районе Йотунхейма.','Еще не все мои рыцари смерти свободны! Их было больше.','Вернитесь к Вэлену Разоблаченному в Мрачный Свод, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пленники из ордена Черного Клинка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда я вернулся, барон наверняка захочет, чтобы я вновь собрал свой отряд. Армия Короля-лича уже скоро прорвется сюда, и мы не сможем их остановить без моих рыцарей смерти.$B$BТы ведь поможешь мне, $n?$B$BОтправляйся в Йотунхейм и освободи моих людей из этих проклятых клеток.$B$BСломай эти чертовы замки, в выборе средств ты $Gсвободен:свободна;. У врайкулов должны быть ключи...$B$BВ общем, делай что хочешь, но освободи моих людей!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Освободите 8 пленных рыцарей Черного Клинка по просьбе Вэлена Разоблаченного из Мрачного Свода. Пленников держат в клетках в районе Йотунхейма.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Еще не все мои рыцари смерти свободны! Их было больше.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Вэлену Разоблаченному в Мрачный Свод, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12983,'Последняя из рода','Сколько я себя помню, самых лучших медведей мы всегда получали из пещеры зимней спячки на востоке.$B$BНо похоже, теперь все закончилось. Пещеру захватили ненасытные йормунгары, которые истребили всех диких медведей.$B$BНо если ты сумеешь найти уцелевшую медведицу-матриарха, она – гарантирую – будет драться лучше любого медведя, выросшего в неволе.$B$BВозьми с собой в пещеру эту упряжь, и спаси уцелевшую медведицу-матриарха. Удачи тебе.','Ты $Gнашел:нашла; матриарха?','Вернитесь к Астрид Бьорнриттар в деревню Бруннхильдар, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Последняя из рода',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сколько я себя помню, самых лучших медведей мы всегда получали из пещеры зимней спячки на востоке.$B$BНо похоже, теперь все закончилось. Пещеру захватили ненасытные йормунгары, которые истребили всех диких медведей.$B$BНо если ты сумеешь найти уцелевшую медведицу-матриарха, она – гарантирую – будет драться лучше любого медведя, выросшего в неволе.$B$BВозьми с собой в пещеру эту упряжь, и спаси уцелевшую медведицу-матриарха. Удачи тебе.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gнашел:нашла; матриарха?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Астрид Бьорнриттар в деревню Бруннхильдар, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12984,'Валдуран Дитя Бури','У нас нет выбора, $n. То, что ты $gузнал:узнала; в Мастерской Мимира, означает только одно: нам надо опередить Валдурана, пока он не собрал свое новое оружие.$B$BПрямо сейчас защитники убежища сражаются, чтобы выиграть время и дать нам возможность разобраться с Валдураном.$B$BИди в Нидавелир, это к юго-западу отсюда, по ту сторону Снежных равнин, разыщи Валдурана и попытайся его устранить. Но тебе не придется сражаться с ним в одиночку. Возьми с собой этот боевой рог и протруби в него, когда будешь $gготов:готова; сразиться с предводителем наших врагов. Мы с Брюором тебе поможем.','С Вальдураном нужно разобраться до того, как убежище падет.','Вернитесь к Глыбоскалу Камнетесу в Приют Глыбоскала, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Валдуран Дитя Бури',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У нас нет выбора, $n. То, что ты $gузнал:узнала; в Мастерской Мимира, означает только одно: нам надо опередить Валдурана, пока он не собрал свое новое оружие.$B$BПрямо сейчас защитники убежища сражаются, чтобы выиграть время и дать нам возможность разобраться с Валдураном.$B$BИди в Нидавелир, это к юго-западу отсюда, по ту сторону Снежных равнин, разыщи Валдурана и попытайся его устранить. Но тебе не придется сражаться с ним в одиночку. Возьми с собой этот боевой рог и протруби в него, когда будешь $gготов:готова; сразиться с предводителем наших врагов. Мы с Брюором тебе поможем.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','С Вальдураном нужно разобраться до того, как убежище падет.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Глыбоскалу Камнетесу в Приют Глыбоскала, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12985,'Ковка шлема','Здравствуй, |3-6($r).$b$bУ меня есть работа, и король Йоккум считает, что ты вполне можешь с ней справиться – если, конечно, тебе все еще хочется заслужить уважение моего народа.$b$bЯ придумал, как можно воссоздать еще один артефакт, который принесет нашей крепости благословение и покровительство Ходира. У меня есть почти все, чтобы приступить к восстановлению. Осталось только добыть глаза наших павших врагов$b$bВозьми кирку и принеси мне глаза мертвых железных великанов, которые остались на поле боя.','По заданию Ньормельда в Дун Ниффелеме возьмите кирку с алмазным наконечником, вырвите с ее помощью глаза у мертвых железных великанов у Промерзшего озера и принесите ему 8 глаз Закаленных Бурей.','Вот, почти все готово.\n\nКогда я его соберу, в Дун Ниффелеме трижды подумают прежде, чем на нас нападать.','Ты $Gпринес:принесла; то, о чем я тебя просил, $R?','Вернитесь к Ньормельду в Дун Ниффелем, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ковка шлема',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Здравствуй, |3-6($r).$b$bУ меня есть работа, и король Йоккум считает, что ты вполне можешь с ней справиться – если, конечно, тебе все еще хочется заслужить уважение моего народа.$b$bЯ придумал, как можно воссоздать еще один артефакт, который принесет нашей крепости благословение и покровительство Ходира. У меня есть почти все, чтобы приступить к восстановлению. Осталось только добыть глаза наших павших врагов$b$bВозьми кирку и принеси мне глаза мертвых железных великанов, которые остались на поле боя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По заданию Ньормельда в Дун Ниффелеме возьмите кирку с алмазным наконечником, вырвите с ее помощью глаза у мертвых железных великанов у Промерзшего озера и принесите ему 8 глаз Закаленных Бурей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот, почти все готово.\n\nКогда я его соберу, в Дун Ниффелеме трижды подумают прежде, чем на нас нападать.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gпринес:принесла; то, о чем я тебя просил, $R?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ньормельду в Дун Ниффелем, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12986,'Судьба титанов','Ядра Норганнона здесь нет. Я не знаю, зачем ты его ищешь, |3-6($r), и знаешь ли ты истинное назначение этой вещи.$B$BМожет быть, я помогу тебе в поисках ядра, но сначала ты помоги мне. Недавно мне довелось узнать о наблюдателе Ториме. Его власть оспаривают, а его судьба остается неопределенной. Это меня беспокоит, поскольку я ничего не знаю о других наблюдателях. Воспользуйся этим банком данных, чтобы исследовать их храмы на северо-востоке, и поделись со мной информацией.','По заданию Кретея из Подножия посетите Храм Изобретений, Храм Зимы, Храм Жизни и Храм Порядка. Используйте банк данных для изучения каждого из них.','Ты $Gвернулся:вернулась; с знанием, что я ищу, $R?','Вернитесь к Кретею в Подножие, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Судьба титанов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ядра Норганнона здесь нет. Я не знаю, зачем ты его ищешь, |3-6($r), и знаешь ли ты истинное назначение этой вещи.$B$BМожет быть, я помогу тебе в поисках ядра, но сначала ты помоги мне. Недавно мне довелось узнать о наблюдателе Ториме. Его власть оспаривают, а его судьба остается неопределенной. Это меня беспокоит, поскольку я ничего не знаю о других наблюдателях. Воспользуйся этим банком данных, чтобы исследовать их храмы на северо-востоке, и поделись со мной информацией.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По заданию Кретея из Подножия посетите Храм Изобретений, Храм Зимы, Храм Жизни и Храм Порядка. Используйте банк данных для изучения каждого из них.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gвернулся:вернулась; с знанием, что я ищу, $R?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кретею в Подножие, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12987,'Шлем Ходира','Шлем уже выкован.$b$bМы оценили твои усилия, $gмалыш:невеличка;. Хотя еще многое предстоит сделать, мы, Сыны Ходира, благодарны тебе за помощь.$b$bВ знак благодарности ты получишь почетную возможность представить шлем Ходира нашему королю и нашим собратьям.$b$bЛети к острию этого ледяного шипа и прочитай моим людям текст скрижали.$b$bНикогда еще Сыны Ходира не оказывали чужаку такой чести, |3-6($c)!','Летите к острию ледяного шипа в северной части Дун Ниффелема и прочитайте народу Ньормельда текст со скрижалей Утверждения.','<Ньормельд смотрит на шлем Ходира, заметно растроганный.>\n\nХорошо, $малыш:невеличка:r; $R.\n\nХорошо...','$GУстановил:Установила; ли ты Шлем Ходира, $R.','Вернитесь к Ньормельду в Дун Ниффелем, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Шлем Ходира',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Шлем уже выкован.$b$bМы оценили твои усилия, $gмалыш:невеличка;. Хотя еще многое предстоит сделать, мы, Сыны Ходира, благодарны тебе за помощь.$b$bВ знак благодарности ты получишь почетную возможность представить шлем Ходира нашему королю и нашим собратьям.$b$bЛети к острию этого ледяного шипа и прочитай моим людям текст скрижали.$b$bНикогда еще Сыны Ходира не оказывали чужаку такой чести, |3-6($c)!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Летите к острию ледяного шипа в северной части Дун Ниффелема и прочитайте народу Ньормельда текст со скрижалей Утверждения.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Ньормельд смотрит на шлем Ходира, заметно растроганный.>\n\nХорошо, $малыш:невеличка:r; $R.\n\nХорошо...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$GУстановил:Установила; ли ты Шлем Ходира, $R.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ньормельду в Дун Ниффелем, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12988,'Штормовые кузни','Я изрядно сглупил. Я был уверен, что проект Валурана в Колыбели Нарвира, большой строительной площадке на юге, есть не более чем причудливый памятник жестокости "Хранителя" Локена.$B$BТеперь мы знаем правду: это оружие, которое они собираются применить против нас и наших союзников. $n, нельзя допустить, чтобы они завершили изготовление железного колосса. Против него наш приют не устоит.$B$BОтправляйся в Колыбель Нарвира, разыщи штормовые кузни, которые используют умельцы из клана Закаленных Бурей, и уничтожь их.','Отлично сработано! Это, конечно, не остановит железных дворфов, но на восстановление кузниц у них уйдет время. И это время будет работать на нас.','Удалось помешать им?','Вернитесь к Глыбоскалу Камнетесу в Приют Глыбоскала, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Штормовые кузни',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я изрядно сглупил. Я был уверен, что проект Валурана в Колыбели Нарвира, большой строительной площадке на юге, есть не более чем причудливый памятник жестокости "Хранителя" Локена.$B$BТеперь мы знаем правду: это оружие, которое они собираются применить против нас и наших союзников. $n, нельзя допустить, чтобы они завершили изготовление железного колосса. Против него наш приют не устоит.$B$BОтправляйся в Колыбель Нарвира, разыщи штормовые кузни, которые используют умельцы из клана Закаленных Бурей, и уничтожь их.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично сработано! Это, конечно, не остановит железных дворфов, но на восстановление кузниц у них уйдет время. И это время будет работать на нас.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось помешать им?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Глыбоскалу Камнетесу в Приют Глыбоскала, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12989,'Нашествие тьмы','Эти ползучие гады йормунгары захватили почти всю пещеру зимней спячки. Отвратительные создания... отродья Локена, подлого брата Торима.$B$BМы – слуги Торима, и обязаны убивать эту пакость везде, где она нам попадется. Пещеру найдешь на востоке, за деревней.','По заданию Астрид Бьорнриттар убейте 8 прожорливых йормунгаров в пещере зимней спячки на востоке от деревни Бруннхильдар.','Йормунгары – мерзопакостные создания. Их истребление – благое дело.','Как все прошло с йети?','Вернитесь к Астрид Бьорнриттар в деревню Бруннхильдар, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нашествие тьмы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти ползучие гады йормунгары захватили почти всю пещеру зимней спячки. Отвратительные создания... отродья Локена, подлого брата Торима.$B$BМы – слуги Торима, и обязаны убивать эту пакость везде, где она нам попадется. Пещеру найдешь на востоке, за деревней.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По заданию Астрид Бьорнриттар убейте 8 прожорливых йормунгаров в пещере зимней спячки на востоке от деревни Бруннхильдар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Йормунгары – мерзопакостные создания. Их истребление – благое дело.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как все прошло с йети?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Астрид Бьорнриттар в деревню Бруннхильдар, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (12990,'Червоточина','Принеси мне материалы – и я научу тебя обращаться с генератором червоточин.','Принесите Джону Лекрафту нужные ему материалы – и вы не только останетесь в живых, но и узнаете новое заклинание.','Вернитесь к Джонатану Лекрафту на Остров Дизайнера.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Червоточина',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Принеси мне материалы – и я научу тебя обращаться с генератором червоточин.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Джону Лекрафту нужные ему материалы – и вы не только останетесь в живых, но и узнаете новое заклинание.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джонатану Лекрафту на Остров Дизайнера.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12991,'Удар по больному месту','Было время, когда я бы не стал никого посылать с поручением, которое выполнил ты, но после достаточно тесного общения с железными дворфами я уже не питаю к ним теплых чувств. Главное, нам удалось помешать врагу, а значит, мы выиграли себе время.','Ты $Gуничтожил:уничтожила; силу железного колосса?','Вернитесь к Брюору Железорубу в Приют Глыбоскала, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Удар по больному месту',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Было время, когда я бы не стал никого посылать с поручением, которое выполнил ты, но после достаточно тесного общения с железными дворфами я уже не питаю к ним теплых чувств. Главное, нам удалось помешать врагу, а значит, мы выиграли себе время.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gуничтожил:уничтожила; силу железного колосса?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Брюору Железорубу в Приют Глыбоскала, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12992,'Истребление врайкулов','Врайкулов в Йотунхейме надо давить и давить!$B$B$n, займись истреблением этих гадов!','Убейте 15 врайкулов в районе Йотунхейма по заданию Злоба из Мрачного Свода.','$N, ты $Gсамый:самая; $Gлучший:лучшая; |3-6($R)!','Врайкулов не $Gубил:убила;!','Вернитесь к Злобу в Мрачный Свод, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Истребление врайкулов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Врайкулов в Йотунхейме надо давить и давить!$B$B$n, займись истреблением этих гадов!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 15 врайкулов в районе Йотунхейма по заданию Злоба из Мрачного Свода.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','$N, ты $Gсамый:самая; $Gлучший:лучшая; |3-6($R)!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Врайкулов не $Gубил:убила;!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Злобу в Мрачный Свод, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (12993,'Колоссальная опасность','Ты хорошо $gпотрудился:потрудилась;, чтобы помешать им закончить железного колосса, но, боюсь, это только придало Закаленным Бурей решимости, и теперь они будут работать вдвойне активнее, чтобы скорее закончить оружие.$B$BУже сейчас они завозят туда новых рабочих, и надсмотрщики выжимают из них все силы. И теперь я уже не уверен, что мы сможем помешать привести колосса в действие. В таком случае, нужно знать, что нам грозит. Вернись на юг, в Колыбель Нарвира, и найди документы, в которых описаны наступательные и оборонительные характеристики колосса. Они должны лежать где-то у палаток и кузниц на нижнем уровне.','Вернитесь к Глыбоскалу Камнетесу в Приют Глыбоскала, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Колоссальная опасность',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты хорошо $gпотрудился:потрудилась;, чтобы помешать им закончить железного колосса, но, боюсь, это только придало Закаленным Бурей решимости, и теперь они будут работать вдвойне активнее, чтобы скорее закончить оружие.$B$BУже сейчас они завозят туда новых рабочих, и надсмотрщики выжимают из них все силы. И теперь я уже не уверен, что мы сможем помешать привести колосса в действие. В таком случае, нужно знать, что нам грозит. Вернись на юг, в Колыбель Нарвира, и найди документы, в которых описаны наступательные и оборонительные характеристики колосса. Они должны лежать где-то у палаток и кузниц на нижнем уровне.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Глыбоскалу Камнетесу в Приют Глыбоскала, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12994,'Контрразведчик','Убейте 3 Секретных агентов клана Закаленных Бурей в долине Древних Зим.$b$bС помощью клыка астрального ворга призовите призрачного ледяного ворга, который поможет вам обнаружить скрывающихся врагов. По выполнении задания вернитесь к повелительнице логова ледяных воргов в Дун Ниффелем.','Когда вы надеваете цепь обратно на шею повелительнице логова, она облизывает вам лицо, выражая тем самым свою благодарность.','Призрачный ледяной ворг с любопытством смотрит на вас.','Вернитесь к Повелительнице логова ледяных воргов в Дун Ниффелем, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Контрразведчик',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 3 Секретных агентов клана Закаленных Бурей в долине Древних Зим.$b$bС помощью клыка астрального ворга призовите призрачного ледяного ворга, который поможет вам обнаружить скрывающихся врагов. По выполнении задания вернитесь к повелительнице логова ледяных воргов в Дун Ниффелем.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Когда вы надеваете цепь обратно на шею повелительнице логова, она облизывает вам лицо, выражая тем самым свою благодарность.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Призрачный ледяной ворг с любопытством смотрит на вас.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Повелительнице логова ледяных воргов в Дун Ниффелем, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12995,'Наша метка','Атака на врайкулов Йотунхейма должна проходить сразу на нескольких уровнях. Грубая сила – это, конечно, неплохо, но я все-таки предпочитаю работать мозгами.$B$BВрайкулов нужно деморализовать, и ты нам в этом поможешь.$B$BМои люди изготовили несколько знамен. Возьми их и воткни рядом с телами павших врайкулов.$B$BПусть эти знамена служат им постоянным напоминанием, что есть и более неотвратимая кара, нежели гнев Короля-лича.','По заданию барона Раздора из Мрачного Свода воткните 15 знамен Черного Клинка рядом с телами мертвых врайкулов в районе Йотунхейма.','$N, не думаю, что ты $Gзакончил:закончила;.','Вернитесь к барону Раздору в Мрачный Свод, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наша метка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Атака на врайкулов Йотунхейма должна проходить сразу на нескольких уровнях. Грубая сила – это, конечно, неплохо, но я все-таки предпочитаю работать мозгами.$B$BВрайкулов нужно деморализовать, и ты нам в этом поможешь.$B$BМои люди изготовили несколько знамен. Возьми их и воткни рядом с телами павших врайкулов.$B$BПусть эти знамена служат им постоянным напоминанием, что есть и более неотвратимая кара, нежели гнев Короля-лича.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По заданию барона Раздора из Мрачного Свода воткните 15 знамен Черного Клинка рядом с телами мертвых врайкулов в районе Йотунхейма.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$N, не думаю, что ты $Gзакончил:закончила;.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к барону Раздору в Мрачный Свод, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12996,'Тренировочный заезд','Тебе улыбнулась удача, сестра. Такой могучей медведицы мы не видели уже много лет.$B$BНо как бы ни был хорош медведь, самое главное – это уметь на нем ездить.$B$BДумаю, для начала ты потренируешься на Киргарааке. Это самый крупный из всех йети, которых нам удавалось поймать, так что будь осторожна. И если почувствуешь, что не справляешься, то не бойся уйти... мы не зря держим его в цепях.','Воспользуйтесь поводьями матриарха ледочревов, чтобы сразиться с Киргарааком, как вам велела Астрид Бьорнриттар из деревни Бруннхильдар.','Ты нашла лагерь Бронзоборода?','Вернитесь к Астрид Бьорнриттар в деревню Бруннхильдар, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тренировочный заезд',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе улыбнулась удача, сестра. Такой могучей медведицы мы не видели уже много лет.$B$BНо как бы ни был хорош медведь, самое главное – это уметь на нем ездить.$B$BДумаю, для начала ты потренируешься на Киргарааке. Это самый крупный из всех йети, которых нам удавалось поймать, так что будь осторожна. И если почувствуешь, что не справляешься, то не бойся уйти... мы не зря держим его в цепях.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь поводьями матриарха ледочревов, чтобы сразиться с Киргарааком, как вам велела Астрид Бьорнриттар из деревни Бруннхильдар.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты нашла лагерь Бронзоборода?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Астрид Бьорнриттар в деревню Бруннхильдар, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12997,'В Яму!','Победить скованного противника – это одно, а биться с другими наездниками на медведях на равных – совсем другое.$B$BТы уже многому научилась. Отправляйся в Яму Клыка и используй полученные тобой знания для победы. Удачи, сестра.$B$BВ случае успеха тебя ждет слава.','Отправляйтесь в Яму Клыка, воспользуйтесь поводьями матриарха ледочревов и победите 6 боевых медведей Круга хильд по заданию Астрид Бьорнриттар из деревни Бруннхильдар.','Ты уничтожила зараженные яйца?','Вернитесь к Астрид Бьорнриттар в деревню Бруннхильдар, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В Яму!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Победить скованного противника – это одно, а биться с другими наездниками на медведях на равных – совсем другое.$B$BТы уже многому научилась. Отправляйся в Яму Клыка и используй полученные тобой знания для победы. Удачи, сестра.$B$BВ случае успеха тебя ждет слава.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Яму Клыка, воспользуйтесь поводьями матриарха ледочревов и победите 6 боевых медведей Круга хильд по заданию Астрид Бьорнриттар из деревни Бруннхильдар.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты уничтожила зараженные яйца?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Астрид Бьорнриттар в деревню Бруннхильдар, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12998,'Сердце бури','Судя по документам, захваченным тобой в Колыбели Нарвира, железный колосс почти закончен, не хватает только последнего ключевого компонента – Сердца бури.$B$BБез него мощь оружия железного колосса будет намного слабее, чем предусмотрено проектом. Если мы спасем Сердце от надзирателя Нарвира, у нас появится шанс уничтожить колосса!$B$BВ примечании к документам сказано, что Сердце находится в Ульдисе, обители титанов далеко на юге. Вход туда расположен на южном склоне высокой горы над рекой Дыхания Бора.','Если Сердце попадет в руки Нарвира, колосс обретет свою полную силу! У нас не останется выбора, нам придется сражаться.','Скажи мне, что сердце не попало в руки врага.','Вернитесь к Глыбоскалу Камнетесу в Приют Глыбоскала, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сердце бури',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Судя по документам, захваченным тобой в Колыбели Нарвира, железный колосс почти закончен, не хватает только последнего ключевого компонента – Сердца бури.$B$BБез него мощь оружия железного колосса будет намного слабее, чем предусмотрено проектом. Если мы спасем Сердце от надзирателя Нарвира, у нас появится шанс уничтожить колосса!$B$BВ примечании к документам сказано, что Сердце находится в Ульдисе, обители титанов далеко на юге. Вход туда расположен на южном склоне высокой горы над рекой Дыхания Бора.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Если Сердце попадет в руки Нарвира, колосс обретет свою полную силу! У нас не останется выбора, нам придется сражаться.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Скажи мне, что сердце не попало в руки врага.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Глыбоскалу Камнетесу в Приют Глыбоскала, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (12999,'Костяная ведьма','Ты же наверняка помнишь леди Найтсвуд, да? Она тебя помнит. Эта та самая одинокая и очень злая банши, которую ты "$gспас:спасла;", когда $gвырвал:вырвала; и меня со Злобом из-под власти Короля-лича.$B$BЛеди отправилась в Йотунхейм и вселилась в их костяную ведьму. Таким образом она собирается сеять смуту среди врайкулов – так сказать, изнутри.$B$BОна просила, чтобы ты ее $gразыскал:разыскала; в пещере на южной стороне деревни Ньорндар на юго-западе Йотунхейма.','Поговорите с костяной ведьмой в пещере в деревне Ньорндар.','$N, ты $Gпришел:пришла;.$B$BЯ уже слышала о твоих достижениях на Диком уступе. Это хорошо. Я рада, что ты $Gсогласился:согласилась; помочь с истреблением этих врайкулов в Йотунхейме.$B$B<Губы костяной ведьмы кривятся в усмешке, но через силу, как будто она борется с волей леди Найтсвуд.>$B$BМы с тобой славно повеселимся!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Костяная ведьма',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты же наверняка помнишь леди Найтсвуд, да? Она тебя помнит. Эта та самая одинокая и очень злая банши, которую ты "$gспас:спасла;", когда $gвырвал:вырвала; и меня со Злобом из-под власти Короля-лича.$B$BЛеди отправилась в Йотунхейм и вселилась в их костяную ведьму. Таким образом она собирается сеять смуту среди врайкулов – так сказать, изнутри.$B$BОна просила, чтобы ты ее $gразыскал:разыскала; в пещере на южной стороне деревни Ньорндар на юго-западе Йотунхейма.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с костяной ведьмой в пещере в деревне Ньорндар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','$N, ты $Gпришел:пришла;.$B$BЯ уже слышала о твоих достижениях на Диком уступе. Это хорошо. Я рада, что ты $Gсогласился:согласилась; помочь с истреблением этих врайкулов в Йотунхейме.$B$B<Губы костяной ведьмы кривятся в усмешке, но через силу, как будто она борется с волей леди Найтсвуд.>$B$BМы с тобой славно повеселимся!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13000,'Чрезвычайные меры','Здесь, в горах, просто зверский холод. Еще день или два, и у нас закончатся все дрова.$B$BВ пещере к востоку отсюда мы заметили воргов. Найди пещеру и добудь их шкуры. Вроде бы мелочь, но вполне может так получиться, что именно этот мех не даст нам замерзнуть до смерти.$B$BВорги охотятся стаями, поэтому я дам тебе сигнальную ракету. Она поможет выиграть время, если силы окажутся неравными.','Отправляйтесь в Логово Гиморака на востоке и добудьте 6 шкур воргов по просьбе кровостража Лорги.','Вернитесь к кровостражу Лорге на место крушения Гром\'арша, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чрезвычайные меры',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Здесь, в горах, просто зверский холод. Еще день или два, и у нас закончатся все дрова.$B$BВ пещере к востоку отсюда мы заметили воргов. Найди пещеру и добудь их шкуры. Вроде бы мелочь, но вполне может так получиться, что именно этот мех не даст нам замерзнуть до смерти.$B$BВорги охотятся стаями, поэтому я дам тебе сигнальную ракету. Она поможет выиграть время, если силы окажутся неравными.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Логово Гиморака на востоке и добудьте 6 шкур воргов по просьбе кровостража Лорги.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к кровостражу Лорге на место крушения Гром\'арша, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13001,'Время пришло, $gмаленький:маленькая:c; |3-6($c). Этот день был предсказан по звездам.$b$bМне было видение от всемогущего Ходира. Он открыл мне секрет изготовления великой реликвии, копья Ходира.$b$bИ его надо сделать! Мы погибнем, если не сможем заполучить этот дар.$b$bКак верный слуга клана, я прошу тебя помочь мне в этом священном деле.$b$bОтправляйся в пещеру зимней спячки и набери осколков Вечного льда, а потом добудь шкуры мамонтов, что обитают вблизи пещеры.','Добудьте 3 осколка Вечного льда в пещере зимней спячки и 3 шкуры спокойных мамонтов в долине Древних Зим и отнесите все сказителю Рандвиру в Дун Ниффелем.','Отойди в сторонку, $R, и смотри, как сбывается пророчество!','Ты $Gсобрал:собрала; материалы для копья, |3-6($R)?','Вернитесь к сказителю Рандвиру в Дун Ниффелем, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Время пришло, $gмаленький:маленькая:c; |3-6($c). Этот день был предсказан по звездам.$b$bМне было видение от всемогущего Ходира. Он открыл мне секрет изготовления великой реликвии, копья Ходира.$b$bИ его надо сделать! Мы погибнем, если не сможем заполучить этот дар.$b$bКак верный слуга клана, я прошу тебя помочь мне в этом священном деле.$b$bОтправляйся в пещеру зимней спячки и набери осколков Вечного льда, а потом добудь шкуры мамонтов, что обитают вблизи пещеры.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 3 осколка Вечного льда в пещере зимней спячки и 3 шкуры спокойных мамонтов в долине Древних Зим и отнесите все сказителю Рандвиру в Дун Ниффелем.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отойди в сторонку, $R, и смотри, как сбывается пророчество!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gсобрал:собрала; материалы для копья, |3-6($R)?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к сказителю Рандвиру в Дун Ниффелем, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13002,'Огранка камней','Добро пожаловать в морозилку, $gдружок:подружка;. Хотя тут не слишком тепло, меня греет моя профессия – огранка камней. Не хватает только материалов!$B$BТы бы $gнашел:нашла; для меня парочку блестяшек – а я бы взамен научил тебя искусству огранки! Тогда ты сможешь получать идеальные камни с улучшенными характеристиками, обрабатывая драгоценные камни Нордскола высокого качества.','Принесите два огромных цитрина, два темных нефрита и два сумрачных кристалла Геба\'ли в Крепость Песни Войны.','Да будь идеальным, дружище. Вот тебе искусство совершенства в огранке драгоценных камней.','Это то, что я искал. Давай я тебя научу искусству огранки.','Вернитесь к Геба\'ли в Крепость Песни Войны, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Огранка камней',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Добро пожаловать в морозилку, $gдружок:подружка;. Хотя тут не слишком тепло, меня греет моя профессия – огранка камней. Не хватает только материалов!$B$BТы бы $gнашел:нашла; для меня парочку блестяшек – а я бы взамен научил тебя искусству огранки! Тогда ты сможешь получать идеальные камни с улучшенными характеристиками, обрабатывая драгоценные камни Нордскола высокого качества.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите два огромных цитрина, два темных нефрита и два сумрачных кристалла Геба\'ли в Крепость Песни Войны.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да будь идеальным, дружище. Вот тебе искусство совершенства в огранке драгоценных камней.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Это то, что я искал. Давай я тебя научу искусству огранки.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Геба\'ли в Крепость Песни Войны, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13003,'Копье Ходира – символ великой воинской чести и мощи.$b$bВ присутствии этой реликвии в каждом, кто входит в Дун Ниффелем, загорается неутолимая жажда славы. И действительно: вы уже ощущаете неодолимую потребность испытать себя в битве.$B$BВсматриваясь в горизонт, вы замечаете летающего неподалеку дикого змея.$B$BИтак, решено. Из вас двоих только один доживет до рассвета...','С помощью копья Ходира загарпуньте дикого змея в долине Древних Зим и сразитесь с ним не на жизнь, а на смерть.','Вернитесь к копью Ходира в Дун Ниффелем, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Копье Ходира – символ великой воинской чести и мощи.$b$bВ присутствии этой реликвии в каждом, кто входит в Дун Ниффелем, загорается неутолимая жажда славы. И действительно: вы уже ощущаете неодолимую потребность испытать себя в битве.$B$BВсматриваясь в горизонт, вы замечаете летающего неподалеку дикого змея.$B$BИтак, решено. Из вас двоих только один доживет до рассвета...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','С помощью копья Ходира загарпуньте дикого змея в долине Древних Зим и сразитесь с ним не на жизнь, а на смерть.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к копью Ходира в Дун Ниффелем, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13004,'Огранка камней','Идет война, и каждый из нас должен внести свой вклад в победу! Я, например, занимаюсь огранкой камней, ибо мне под силу не просто обработать обычный камень, но и превратить его в идеальный. Знаешь, если бы ты $gпринес:принесла; мне несколько необработанных камней, я бы взамен научил тебя искусству огранки! Тогда ты сможешь получать идеальные камни с улучшенными характеристиками, обрабатывая драгоценные камни Нордскола высокого качества.','Принесите два огромных цитрина, два темных нефрита и два сумрачных кристалла Алестосу в Крепость Отваги.','Спасибо. Я научу тебя совершенству огранки драгоценных камней и кроме того дам тебе идеальный камень, который я огранил.','Твое пожертвование очень ценно. Давай я тебя научу искусству огранки.','Вернитесь к Алестосу в Крепость Отваги, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Огранка камней',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Идет война, и каждый из нас должен внести свой вклад в победу! Я, например, занимаюсь огранкой камней, ибо мне под силу не просто обработать обычный камень, но и превратить его в идеальный. Знаешь, если бы ты $gпринес:принесла; мне несколько необработанных камней, я бы взамен научил тебя искусству огранки! Тогда ты сможешь получать идеальные камни с улучшенными характеристиками, обрабатывая драгоценные камни Нордскола высокого качества.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите два огромных цитрина, два темных нефрита и два сумрачных кристалла Алестосу в Крепость Отваги.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо. Я научу тебя совершенству огранки драгоценных камней и кроме того дам тебе идеальный камень, который я огранил.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Твое пожертвование очень ценно. Давай я тебя научу искусству огранки.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Алестосу в Крепость Отваги, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13005,'Клятва детей земли','Годами я пренебрегал своим долгом, предаваясь печали и горечи поражения.$B$BА вот мои храбрые земельники оказались покрепче! Они не нарушили свою клятву – ценой своих жизней защищать это место.$B$BДаже сейчас они храбро и самоотверженно сопротивляются тлетворному воздействию железных дворфов, выжидая момент, чтобы переломить ситуацию.$B$BИ этот момент настал. Мы должны сплотить остатки земельников и привести их к славной победе. Звуки рога Вершин призовут их выйти на битву и помогут разгромить неприятеля и отвоевать Террасу Творцов.','Используйте рог Вершин, чтобы призвать земельников на битву с железными дворфами и убить 20 железных дворфов и 7 железных часовых по просьбе Торима с Террасы Творцов.','Неплохое начало. Но войска моего брата быстро перегруппируются и пойдут в контратаку. Нам нужна окончательная победа.','Привет, $N. Какие новости $Gпринес:принесла;?','Вернитесь к Ториму на Террасу Творцов, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Клятва детей земли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Годами я пренебрегал своим долгом, предаваясь печали и горечи поражения.$B$BА вот мои храбрые земельники оказались покрепче! Они не нарушили свою клятву – ценой своих жизней защищать это место.$B$BДаже сейчас они храбро и самоотверженно сопротивляются тлетворному воздействию железных дворфов, выжидая момент, чтобы переломить ситуацию.$B$BИ этот момент настал. Мы должны сплотить остатки земельников и привести их к славной победе. Звуки рога Вершин призовут их выйти на битву и помогут разгромить неприятеля и отвоевать Террасу Творцов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте рог Вершин, чтобы призвать земельников на битву с железными дворфами и убить 20 железных дворфов и 7 железных часовых по просьбе Торима с Террасы Творцов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Неплохое начало. Но войска моего брата быстро перегруппируются и пойдут в контратаку. Нам нужна окончательная победа.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Привет, $N. Какие новости $Gпринес:принесла;?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ториму на Террасу Творцов, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13006,'Вы подходите ближе и видите, что мороз уже оказал свое пагубное воздействие на поверхность шлема. Пока это лишь тонкий слой инея, но уже совсем скоро он превратится в толстую корку льда.$B$BЧтобы ваши усилия не пропали втуне, вы решаете осмотреть местность и попытаться найти решение этой проблемы.$B$BВы отходите на пару шагов и вдруг замечаете, как сверкнули глазницы шлема. В тот же миг в ваших мыслях возникает образ пещеры зимней спячки.','Идите в пещеру зимней спячки, что к западу от Дун Ниффелема, и соберите 5 сгустков вязкого масла злобных масленышей. Потом возвращайтесь в Дун Ниффелем и натрите маслом шлем Ходира.','Иней сгущается на шлеме буквально у вас на глазах, и по краям уже начинают формироваться сосульки...','Вернитесь к шлему Ходира в Дун Ниффелем, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы подходите ближе и видите, что мороз уже оказал свое пагубное воздействие на поверхность шлема. Пока это лишь тонкий слой инея, но уже совсем скоро он превратится в толстую корку льда.$B$BЧтобы ваши усилия не пропали втуне, вы решаете осмотреть местность и попытаться найти решение этой проблемы.$B$BВы отходите на пару шагов и вдруг замечаете, как сверкнули глазницы шлема. В тот же миг в ваших мыслях возникает образ пещеры зимней спячки.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Идите в пещеру зимней спячки, что к западу от Дун Ниффелема, и соберите 5 сгустков вязкого масла злобных масленышей. Потом возвращайтесь в Дун Ниффелем и натрите маслом шлем Ходира.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Иней сгущается на шлеме буквально у вас на глазах, и по краям уже начинают формироваться сосульки...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к шлему Ходира в Дун Ниффелем, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13007,'Железный колосс','Нам не удалось помешать им построить железного колосса, $n, а это значит, что у нас не осталось иного выхода, кроме как драться с этим чудовищем.$B$BУ этого колосса есть единственное слабое место, и Вруор придумал план, как на него надавить.$B$BКакой бы толстой ни была броня, кислота йормунгаров разъедает железо. Ими можно управлять при помощи сфер. Возьми одного йормунгара и отправляйся на северный край Снежных равнин. Прочеши всю равнину, найди колосса и сделай так, чтобы твой йормунгар дыхнул на него своим кислотным дыханием. Если тебе нужна помощь в укрощении этих существ, поговори с одним из дрессировщиков.','Мы сделали это, мы справились! И Приют цел, и Закаленные Бурей разбиты! Надо предупредить Бранна, прежде чем Локен опомнится и наберет новое войско. Мы должны закрепить сегодняшнюю победу, а для этого надо отправиться в Ульдуар и окончательно разгромить Локена!','Ты $Gпобедил:победила; железного колосса?','Вернитесь к Глыбоскалу Камнетесу в Приют Глыбоскала, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Железный колосс',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нам не удалось помешать им построить железного колосса, $n, а это значит, что у нас не осталось иного выхода, кроме как драться с этим чудовищем.$B$BУ этого колосса есть единственное слабое место, и Вруор придумал план, как на него надавить.$B$BКакой бы толстой ни была броня, кислота йормунгаров разъедает железо. Ими можно управлять при помощи сфер. Возьми одного йормунгара и отправляйся на северный край Снежных равнин. Прочеши всю равнину, найди колосса и сделай так, чтобы твой йормунгар дыхнул на него своим кислотным дыханием. Если тебе нужна помощь в укрощении этих существ, поговори с одним из дрессировщиков.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мы сделали это, мы справились! И Приют цел, и Закаленные Бурей разбиты! Надо предупредить Бранна, прежде чем Локен опомнится и наберет новое войско. Мы должны закрепить сегодняшнюю победу, а для этого надо отправиться в Ульдуар и окончательно разгромить Локена!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gпобедил:победила; железного колосса?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Глыбоскалу Камнетесу в Приют Глыбоскала, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13008,'Тактика Плети','Неожиданность была нашим главным козырем! Подрывники хорошо потрудились. Мы пробили тоннель в горе и ворвались в Плетхольм. Защитники лагеря отчаянно сопротивлялись, и у них было численное преимущество. Мы отступили обратно в долину и вели непрестанный артиллерийский огонь по преследователям. Какое-то время нам удавалось их сдерживать, а потом... эти чудовища стали использовать наших рыцарей, как живые щиты. Нам пришлось прекратить огонь, чтобы не стрелять по своим.$B$BОсвободи наших рыцарей, которых держат на поле за базой, |3-6($c)!','Ты $Gосвободил:освободила; опутанных рыцарей?','Вернитесь к командиру рыцарей Энтари в Оплот Серебряного Авангарда, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тактика Плети',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Неожиданность была нашим главным козырем! Подрывники хорошо потрудились. Мы пробили тоннель в горе и ворвались в Плетхольм. Защитники лагеря отчаянно сопротивлялись, и у них было численное преимущество. Мы отступили обратно в долину и вели непрестанный артиллерийский огонь по преследователям. Какое-то время нам удавалось их сдерживать, а потом... эти чудовища стали использовать наших рыцарей, как живые щиты. Нам пришлось прекратить огонь, чтобы не стрелять по своим.$B$BОсвободи наших рыцарей, которых держат на поле за базой, |3-6($c)!',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gосвободил:освободила; опутанных рыцарей?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру рыцарей Энтари в Оплот Серебряного Авангарда, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13009,'Новое начало','Еще неизвестно, сможет ли мой народ позабыть все обиды и вспомнить о том, что когда-то мы с Торимом были соратниками и друзьями.$b$bПусть эти доспехи хотя бы напоминают ему о тех днях, когда мы с честью сражались плечом к плечу, непобедимые.','Отнесите перекованные доспехи Торима в Храм Штормов по просьбе Ньормельда.','<Получив от вас перекованные доспехи, Торим поражен их великолепием.>\n\nТвои успехи бесспорны, $R, но нам предстоит еще многое сделать.','Ну, что, |3-6($C)? Как успехи?','Вернитесь к Ториму в Храм Штормов, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новое начало',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Еще неизвестно, сможет ли мой народ позабыть все обиды и вспомнить о том, что когда-то мы с Торимом были соратниками и друзьями.$b$bПусть эти доспехи хотя бы напоминают ему о тех днях, когда мы с честью сражались плечом к плечу, непобедимые.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите перекованные доспехи Торима в Храм Штормов по просьбе Ньормельда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Получив от вас перекованные доспехи, Торим поражен их великолепием.>\n\nТвои успехи бесспорны, $R, но нам предстоит еще многое сделать.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, что, |3-6($C)? Как успехи?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ториму в Храм Штормов, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13010,'Кролмир, Молот Бурь','Остался всего один шаг до того, как я верну свой дом на Террасе Творцов.$B$BНужно найти Кролмир.$B$BВ тот злосчастный день я швырнул его о землю со всей силой и яростью, на которые был способен. Последовал страшный взрыв.$B$BДолгие годы я считал его утраченным, но теперь мне хотелось бы удостовериться...$B$BВозвращайся к королю Йоккуму и попробуй выяснить – вдруг он что-то знает о судьбе моего молота.','Поговорите с королем Йоккумом в Дун Ниффелеме и попробуйте выяснить, что ему известно о Кролмире, принадлежавшем Ториму.','Ты $Gубил:убила; Йормуттара?','Вернитесь к Ториму в Храм Штормов, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кролмир, Молот Бурь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Остался всего один шаг до того, как я верну свой дом на Террасе Творцов.$B$BНужно найти Кролмир.$B$BВ тот злосчастный день я швырнул его о землю со всей силой и яростью, на которые был способен. Последовал страшный взрыв.$B$BДолгие годы я считал его утраченным, но теперь мне хотелось бы удостовериться...$B$BВозвращайся к королю Йоккуму и попробуй выяснить – вдруг он что-то знает о судьбе моего молота.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с королем Йоккумом в Дун Ниффелеме и попробуйте выяснить, что ему известно о Кролмире, принадлежавшем Ториму.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gубил:убила; Йормуттара?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ториму в Храм Штормов, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13011,'Стало быть, дело сделано.\n\nМы слышали вопли Жормуттар. Они разносились по всей долине.\n\nТы сослужил нам хорошую службу, $R.','Рад снова тебя видеть, $N.','Вернитесь к Королю Йоккуму в Дун Ниффелем, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Стало быть, дело сделано.\n\nМы слышали вопли Жормуттар. Они разносились по всей долине.\n\nТы сослужил нам хорошую службу, $R.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Рад снова тебя видеть, $N.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Королю Йоккуму в Дун Ниффелем, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (13012,'Предок Сардис','Приятно знать, что народ этих земель все еще отдает дань уважения древним расам. Всего хорошего, $n. Прими этот знак...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Предок Сардис',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Приятно знать, что народ этих земель все еще отдает дань уважения древним расам. Всего хорошего, $n. Прими этот знак...',`offerrewardtext_loc8`);
