INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13034,'Наблюдатель и герой','Еще в самом начале своего путешествия в Нордскол я посетил Борейскую тундру и там впервые в жизни увидел таунка. Укротитель ветра Бара рассказал мне о Штормовом Копыте и его битве против Северного Ветра, древнего врага его народа.$B$BЯ отправился к Грозовой гряде, чтобы побольше узнать об этом герое, но вот что странно... в Тунка\'ло о нем даже не слышали.$B$BВозможно, какая-то информация есть в исторических документах в этом лагере? Разыщи и прочти свитки, что хранятся в лагере – а потом перескажи мне все, что удастся узнать.','По просьбе Ксанатавра из лагеря Тунка\'ло прочитайте Первый, Второй и Третий свитки.','Как интересно… Это совсем не похоже на историю, которую мне рассказал укротитель ветра Бара.','Ты $Gузнал:узнала;, что написано в исторических документах лагеря Тунка\'ло?','Вернитесь к Ксанатавру в лагерь Тунка’ло, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наблюдатель и герой',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Еще в самом начале своего путешествия в Нордскол я посетил Борейскую тундру и там впервые в жизни увидел таунка. Укротитель ветра Бара рассказал мне о Штормовом Копыте и его битве против Северного Ветра, древнего врага его народа.$B$BЯ отправился к Грозовой гряде, чтобы побольше узнать об этом герое, но вот что странно... в Тунка\'ло о нем даже не слышали.$B$BВозможно, какая-то информация есть в исторических документах в этом лагере? Разыщи и прочти свитки, что хранятся в лагере – а потом перескажи мне все, что удастся узнать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По просьбе Ксанатавра из лагеря Тунка\'ло прочитайте Первый, Второй и Третий свитки.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Как интересно… Это совсем не похоже на историю, которую мне рассказал укротитель ветра Бара.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gузнал:узнала;, что написано в исторических документах лагеря Тунка\'ло?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ксанатавру в лагерь Тунка’ло, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13035,'Прислужники Локена','Мой брат отправил на штурм Террасы Творцов отборные войска: легион железных дворфов и своих лучших командиров.$B$BВоспользуйся рогом Вершин, чтобы призвать земельников себе на помощь и победить прислужников Локена.$b$bВеликана Айзенфауста ты найдешь на севере, в Зале Творца. Остальные засели в глубине Террасы Творцов, за лестницей, ведущей на северо-запад.','Убейте Айзенфауста в Зале Творца, а также Халефнира Дитя Ветра и Даррона Рунокова на Террасе Творцов по просьбе Торима.','Один за другим, все прислужники моего брата повержены. Уже совсем скоро мятеж Локена будет подавлен.','Рад снова тебя видеть, $N.','Вернитесь к Ториму на Террасу Творцов, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прислужники Локена',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мой брат отправил на штурм Террасы Творцов отборные войска: легион железных дворфов и своих лучших командиров.$B$BВоспользуйся рогом Вершин, чтобы призвать земельников себе на помощь и победить прислужников Локена.$b$bВеликана Айзенфауста ты найдешь на севере, в Зале Творца. Остальные засели в глубине Террасы Творцов, за лестницей, ведущей на северо-запад.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Айзенфауста в Зале Творца, а также Халефнира Дитя Ветра и Даррона Рунокова на Террасе Творцов по просьбе Торима.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Один за другим, все прислужники моего брата повержены. Уже совсем скоро мятеж Локена будет подавлен.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Рад снова тебя видеть, $N.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ториму на Террасу Творцов, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13036,'Великая миссия','Наш путь к спасению был долог и труден, |3-6($c). Для того чтобы добраться сюда, нам пришлось много сражаться – на всех континентах, во всех мирах! И теперь нам предстоит выполнить самую главную миссию: победить Короля-лича и Плеть.$B$BНо, увы, мы одиноки в своей борьбе. Орда и Альянс нам не помогут – у них своя собственная война. Однако мы не должны падать духом! Мы будем сражаться до конца! А иначе зачем вообще сражаться?$B$BТы будешь нашим союзником? Твоя отвага и сила могут нам пригодиться, |3-6($c)! Мой командир, Энтари, ждет тебя у себя на заставе.','Поговорите с командиром рыцарей Энтари в Оплоте Серебряного Авангарда в Ледяной Короне.','Там, где были бессильны Орда и Альянс, Серебряный Авангард добился успеха, но не смог долго удерживать преимущество. Наш прорыв на Ледяную Корону получил мощный отпор.$B$BОтветный удар Короля-лича последовал незамедлительно, и удар был жестоким. И теперь нам пришлось занять оборонительную позицию.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Великая миссия',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наш путь к спасению был долог и труден, |3-6($c). Для того чтобы добраться сюда, нам пришлось много сражаться – на всех континентах, во всех мирах! И теперь нам предстоит выполнить самую главную миссию: победить Короля-лича и Плеть.$B$BНо, увы, мы одиноки в своей борьбе. Орда и Альянс нам не помогут – у них своя собственная война. Однако мы не должны падать духом! Мы будем сражаться до конца! А иначе зачем вообще сражаться?$B$BТы будешь нашим союзником? Твоя отвага и сила могут нам пригодиться, |3-6($c)! Мой командир, Энтари, ждет тебя у себя на заставе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с командиром рыцарей Энтари в Оплоте Серебряного Авангарда в Ледяной Короне.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Там, где были бессильны Орда и Альянс, Серебряный Авангард добился успеха, но не смог долго удерживать преимущество. Наш прорыв на Ледяную Корону получил мощный отпор.$B$BОтветный удар Короля-лича последовал незамедлительно, и удар был жестоким. И теперь нам пришлось занять оборонительную позицию.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (13037,'Воспоминания о Штормовом Копыте','Когда бронзовые драконы подарили мне бессмертие и наставили на путь наблюдателя, Ноздорму вручил мне Молот Знаний.$B$BОтклик молота на твои находки означает, что время здесь искажено, и наш долг – восстановить подлинную линию времени.$B$BА для этого нам надо ее найти. Отправляйся на северо-запад, в Ледяные глубины, где находится древнее захоронение воинов Тунка\'ло. Разыщи дух вождя Быстрое Копье, брата Штормового Копыта. Попроси его вспомнить о битве его брата с Северным Ветром.','Поговорите с вождем Быстрое Копье в Ледяных Глубинах и возвращайтесь к Ксанатавру в лагерь Тунка\'ло.','Даже вождь начинает терять память? Прошлое переиначивается прямо у нас на глазах, и если нам не удастся узнать, кто за этим стоит, все наследие Штормового Копыта будет утрачено навсегда!','Вернитесь к Ксанатавру в лагерь Тунка’ло, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Воспоминания о Штормовом Копыте',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда бронзовые драконы подарили мне бессмертие и наставили на путь наблюдателя, Ноздорму вручил мне Молот Знаний.$B$BОтклик молота на твои находки означает, что время здесь искажено, и наш долг – восстановить подлинную линию времени.$B$BА для этого нам надо ее найти. Отправляйся на северо-запад, в Ледяные глубины, где находится древнее захоронение воинов Тунка\'ло. Разыщи дух вождя Быстрое Копье, брата Штормового Копыта. Попроси его вспомнить о битве его брата с Северным Ветром.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с вождем Быстрое Копье в Ледяных Глубинах и возвращайтесь к Ксанатавру в лагерь Тунка\'ло.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Даже вождь начинает терять память? Прошлое переиначивается прямо у нас на глазах, и если нам не удастся узнать, кто за этим стоит, все наследие Штормового Копыта будет утрачено навсегда!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ксанатавру в лагерь Тунка’ло, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13038,'Искажения времени','Эта гробница, захоронение воинов Тунка\'ло, всегда считалась священным местом, свободным от террора стихий.$B$BОднако некая странная сила проникла в Ледяные Глубины – сила, которая нарушает покой духов павших и как будто стирает мне память.$B$BКак будто кто-то пытается переиначить историю и убрать из нее наши деяния и воспоминания.$B$BПри жизни этот тотем служил символом моей власти. Сейчас это последнее связующее звено между мною и этим миром. Возьми его и сделай так, чтобы духи павших упокоились с миром, а потом верни его в лагерь Тунка\'ло.','Закройте 4 расселины в Ледяных глубинах с помощью тотема вождя, а затем отправляйтесь в лагерь Тунка\'ло и отдайте тотем Ксанатавру.','Дух вождя велел тебе принести это мне?\n\n<Ксанатавр внимательно рассматривает тотем.>\n\nАга, кажется, я понимаю, в чем дело. Когда он сказал, чтобы ты воспользовался тотемом, чтобы закрыть расселины в Глубинах, он дал нам подсказку к разгадке того, что происходит с линией времени. Мудрый вождь, этот Быстрое Копыто. Даже в посмертии он заботится о своих сородичах.','Что ты $Gпринес:принесла; из гробницы?','Вернитесь к Ксанатавру в лагерь Тунка’ло, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Искажения времени',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эта гробница, захоронение воинов Тунка\'ло, всегда считалась священным местом, свободным от террора стихий.$B$BОднако некая странная сила проникла в Ледяные Глубины – сила, которая нарушает покой духов павших и как будто стирает мне память.$B$BКак будто кто-то пытается переиначить историю и убрать из нее наши деяния и воспоминания.$B$BПри жизни этот тотем служил символом моей власти. Сейчас это последнее связующее звено между мною и этим миром. Возьми его и сделай так, чтобы духи павших упокоились с миром, а потом верни его в лагерь Тунка\'ло.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Закройте 4 расселины в Ледяных глубинах с помощью тотема вождя, а затем отправляйтесь в лагерь Тунка\'ло и отдайте тотем Ксанатавру.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Дух вождя велел тебе принести это мне?\n\n<Ксанатавр внимательно рассматривает тотем.>\n\nАга, кажется, я понимаю, в чем дело. Когда он сказал, чтобы ты воспользовался тотемом, чтобы закрыть расселины в Глубинах, он дал нам подсказку к разгадке того, что происходит с линией времени. Мудрый вождь, этот Быстрое Копыто. Даже в посмертии он заботится о своих сородичах.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что ты $Gпринес:принесла; из гробницы?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ксанатавру в лагерь Тунка’ло, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13039,'Оборона аванпоста','Мы уже не справляемся, $gдруг:милая леди;. Когда они пробили брешь, шлюзы открылись. Плеть валит сюда бесконечным потоком.$B$BНам не хватает людей. И мы рады любому, кто способен сражаться и согласен помочь нам сдержать поток зла. Вставай в строй, $gдружище:воительница;, и убивай этих чудовищ. Чем больше, тем лучше!','Сколько же их там?! Мы перебили их столько, что хватит на десяток погостов, а они все идут и идут. Как-то мне это не нравится.','Не сдавайтесь, $N!','Вернитесь к командиру рыцарей Далфорсу в Оплот Серебряного Авангарда, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оборона аванпоста',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы уже не справляемся, $gдруг:милая леди;. Когда они пробили брешь, шлюзы открылись. Плеть валит сюда бесконечным потоком.$B$BНам не хватает людей. И мы рады любому, кто способен сражаться и согласен помочь нам сдержать поток зла. Вставай в строй, $gдружище:воительница;, и убивай этих чудовищ. Чем больше, тем лучше!',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сколько же их там?! Мы перебили их столько, что хватит на десяток погостов, а они все идут и идут. Как-то мне это не нравится.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Не сдавайтесь, $N!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру рыцарей Далфорсу в Оплот Серебряного Авангарда, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13040,'Исцеление неисцелимого','У нас с каждым днем прибавляется раненых, у всех – сильное отравление. Причем с таким ядом мы раньше не сталкивались. Я не знаю, что там за пакость в ядовитых железах у нерубов; известно только, что их яд смертелен и не поддается никаким целительным снадобьям. Пока что нам удавалось только замедлить процесс общего отравления. Но нам нужно найти противоядие!$B$BИди на северо-запад, в долину рядом с аванпостом, и убей десятка полтора нерубов Забытых глубин. Вырежи их ядовитые железы и принеси мне.','Принесите 10 ядовитых желез душителей Забытых глубин отцу Густаву в Оплот Серебряного Авангарда в Ледяной Короне.','Вернитесь к отцу Густаву в Оплот Серебряного Авангарда, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Исцеление неисцелимого',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У нас с каждым днем прибавляется раненых, у всех – сильное отравление. Причем с таким ядом мы раньше не сталкивались. Я не знаю, что там за пакость в ядовитых железах у нерубов; известно только, что их яд смертелен и не поддается никаким целительным снадобьям. Пока что нам удавалось только замедлить процесс общего отравления. Но нам нужно найти противоядие!$B$BИди на северо-запад, в долину рядом с аванпостом, и убей десятка полтора нерубов Забытых глубин. Вырежи их ядовитые железы и принеси мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 ядовитых желез душителей Забытых глубин отцу Густаву в Оплот Серебряного Авангарда в Ледяной Короне.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к отцу Густаву в Оплот Серебряного Авангарда, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (13041,'Недостающий камень','Как удачно, что ты $gзашел:зашла;! Груз блестящих статуэток из бивня уже отправляется в Нижнюю Шахту, а мне, как назло, не хватает кальцедония – закончить глаз у последней статуэтки. Принеси мне кальцедоний, и я дам тебе еще один значок даларанского ювелира.','Принесите кусок кальцедония Тимоти Джонсу в Даларан.','Вот тебе значок даларанского ювелира, как и было обещано. У меня постоянно бывают большие заказы, так что ты время от времени заходи – мне может понадобиться твоя помощь.','Вернитесь к Тимоти Джонсу в ювелирный магазин Картье и компании, что в Даларане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Недостающий камень',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как удачно, что ты $gзашел:зашла;! Груз блестящих статуэток из бивня уже отправляется в Нижнюю Шахту, а мне, как назло, не хватает кальцедония – закончить глаз у последней статуэтки. Принеси мне кальцедоний, и я дам тебе еще один значок даларанского ювелира.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите кусок кальцедония Тимоти Джонсу в Даларан.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот тебе значок даларанского ювелира, как и было обещано. У меня постоянно бывают большие заказы, так что ты время от времени заходи – мне может понадобиться твоя помощь.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тимоти Джонсу в ювелирный магазин Картье и компании, что в Даларане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13042,'В недрах Глубинных чертогов','В недрах Глубинных чертогов на северо-востоке сумасшедший ученый по имени доктор Ужас творит всякие бесчинства, вполне соответствующие его имени.$B$BКороль-лич дал ему разрешение ставить эксперименты над варгулами – врайкулами, которые погибли в сражении, но их сочли недостойными, воскресили и поставили под знамена Плети.$B$BМы должны его остановить, но гадание не раскрыло мне его точного местонахождения. Однако мы знаем, что у него есть ученик.$B$BВыбей нужную нам информацию из этого ученика, а потом как-нибудь тихо избавься от тела.','По поручению костяной ведьмы из деревни Ньорндар выбейте информацию из ученика Остеркилгра: узнайте, где находится доктор Ужас.$B$BПотом убейте ученика.','Ты не $Gзакончил:закончила; то, о чем я тебя просил.$B$BУходи и не возвращайся, пока не сделаешь это, или я буду очень сердит.','Вернитесь к костяной ведьме в деревню Ньорндар, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В недрах Глубинных чертогов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В недрах Глубинных чертогов на северо-востоке сумасшедший ученый по имени доктор Ужас творит всякие бесчинства, вполне соответствующие его имени.$B$BКороль-лич дал ему разрешение ставить эксперименты над варгулами – врайкулами, которые погибли в сражении, но их сочли недостойными, воскресили и поставили под знамена Плети.$B$BМы должны его остановить, но гадание не раскрыло мне его точного местонахождения. Однако мы знаем, что у него есть ученик.$B$BВыбей нужную нам информацию из этого ученика, а потом как-нибудь тихо избавься от тела.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По поручению костяной ведьмы из деревни Ньорндар выбейте информацию из ученика Остеркилгра: узнайте, где находится доктор Ужас.$B$BПотом убейте ученика.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты не $Gзакончил:закончила; то, о чем я тебя просил.$B$BУходи и не возвращайся, пока не сделаешь это, или я буду очень сердит.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к костяной ведьме в деревню Ньорндар, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13043,'Когда сумма больше слагаемых','Вы открываете книгу и видите очень подробные и четкие иллюстрации, отражающие процесс создания того, что доктор называет "совершенным оружием"!$B$BОчевидный прототип, Нергельд, внушительный мясистый великан, неподвижно стоит в дальнем конце Зала Ужасов.$B$BЕсли будет создана целая армия подобных "конструкций", это действительно будет конец. Существует единственный способ это предотвратить: убить доктора Ужаса!$B$BМожет быть, доктор выйдет к вам, если вы попытаетесь взять контроль над его творением?','Заберитесь в Нергельда и возьмите над ним контроль. Защищайте его от обитателей Зала Ужасов, пока не покажется доктор Ужас.$B$BИспользуйте Нергельда, чтобы убить доктора, а потом возвращайтесь в деревню Ньорндар, в пещеру к костяной ведьме.','Тебе удалось сорвать планы доктора!$B$B<Ведьма, одержимая банши, улыбается и ласково треплет тебя по плечу.>$B$BНеплохой щелчок по носу Короля-лича, но можно придумать и кое-что получше.','Ты $Gвернул:вернула; фолиант доктора, но не $Gприкончил:прикончила;?$B$BВернись туда и убей его, пока не стало слишком поздно!','Вернитесь к костяной ведьме в деревню Ньорндар, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Когда сумма больше слагаемых',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы открываете книгу и видите очень подробные и четкие иллюстрации, отражающие процесс создания того, что доктор называет "совершенным оружием"!$B$BОчевидный прототип, Нергельд, внушительный мясистый великан, неподвижно стоит в дальнем конце Зала Ужасов.$B$BЕсли будет создана целая армия подобных "конструкций", это действительно будет конец. Существует единственный способ это предотвратить: убить доктора Ужаса!$B$BМожет быть, доктор выйдет к вам, если вы попытаетесь взять контроль над его творением?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заберитесь в Нергельда и возьмите над ним контроль. Защищайте его от обитателей Зала Ужасов, пока не покажется доктор Ужас.$B$BИспользуйте Нергельда, чтобы убить доктора, а потом возвращайтесь в деревню Ньорндар, в пещеру к костяной ведьме.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебе удалось сорвать планы доктора!$B$B<Ведьма, одержимая банши, улыбается и ласково треплет тебя по плечу.>$B$BНеплохой щелчок по носу Короля-лича, но можно придумать и кое-что получше.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gвернул:вернула; фолиант доктора, но не $Gприкончил:прикончила;?$B$BВернись туда и убей его, пока не стало слишком поздно!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к костяной ведьме в деревню Ньорндар, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13044,'Пропавшие без вести','На той стороне Долины Эха, что к западу отсюда, за Проломом, расположилась первая застава Плети в Ледяной Короне – Плетхольм. Мы организовали вылазку на заставу и перебили немало чудовищ Плети, но затем нас отбросили назад. Нескольких солдат недосчитались – они пропали без вести.$B$BЕсли наши товарищи еще живы, их необходимо спасти! Ступай по этой тропе на юго-восток и найди Пенумбриуса. Он – союзник бронзовых драконов и попечитель протодраконов. Он поможет тебе.','Поговорите с Пенумбриусом в Оплоте Серебряного Авангарда в Ледяной Короне.','<Пенумбриус важно кивает.>$B$BМои сородичи помогут тебе. Вместе мы сокрушим Короля-лича и его легионы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пропавшие без вести',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На той стороне Долины Эха, что к западу отсюда, за Проломом, расположилась первая застава Плети в Ледяной Короне – Плетхольм. Мы организовали вылазку на заставу и перебили немало чудовищ Плети, но затем нас отбросили назад. Нескольких солдат недосчитались – они пропали без вести.$B$BЕсли наши товарищи еще живы, их необходимо спасти! Ступай по этой тропе на юго-восток и найди Пенумбриуса. Он – союзник бронзовых драконов и попечитель протодраконов. Он поможет тебе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Пенумбриусом в Оплоте Серебряного Авангарда в Ледяной Короне.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Пенумбриус важно кивает.>$B$BМои сородичи помогут тебе. Вместе мы сокрушим Короля-лича и его легионы.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13045,'В чащобу','Мы будем помогать тебе всеми силами, $n. Протодраконы полетят по Пролому в Плетхольм. Спаси всех рыцарей Серебряного Авангарда, которых встретишь. Доставь их в лазарет в самом центре Оплота Серебряного Авангарда.$B$BВозьми небесного когтя Серебряного Авангарда в палатке за моей спиной и ступай!$B$BПлетхольм расположен на северо-западе, по ту сторону Долины Эха, в большом Проломе.','Вытащите из Плетхольма 3 плененных рыцарей Серебряного Авангарда и доставьте их в лазарет в центре Оплота Серебряного Авангарда. После этого поговорите с верховным лордом Тирионом Фордрингом.','С каждой минутой их шансы выжить тают...','Вернитесь к верховному лорду Тириону Фордрингу в Оплот Серебряного Авангарда, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В чащобу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы будем помогать тебе всеми силами, $n. Протодраконы полетят по Пролому в Плетхольм. Спаси всех рыцарей Серебряного Авангарда, которых встретишь. Доставь их в лазарет в самом центре Оплота Серебряного Авангарда.$B$BВозьми небесного когтя Серебряного Авангарда в палатке за моей спиной и ступай!$B$BПлетхольм расположен на северо-западе, по ту сторону Долины Эха, в большом Проломе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вытащите из Плетхольма 3 плененных рыцарей Серебряного Авангарда и доставьте их в лазарет в центре Оплота Серебряного Авангарда. После этого поговорите с верховным лордом Тирионом Фордрингом.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','С каждой минутой их шансы выжить тают...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному лорду Тириону Фордрингу в Оплот Серебряного Авангарда, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (13046,'Муки Арнгрима','Голод Арнгрима вошел в легенды.$b$bДаже после смерти его лик искажен гримасой ненасытного голода. При одном только взгляде на это лицо у вас начинает бурчать в желудке.$b$bГоворят, что за всю свою жизнь он никогда не наедался досыта, а ведь он ел все подряд. Вы поневоле задумались: а есть ли способ накормить старого короля?$b$bКак только у вас возникает эта мысль, один из огромных замерзших зубов Арнгрима выпадает у него изо рта и, отскочив от его бороды, падает вам на ладонь.','Вы должны накормить Арнгрима пятью бесплотными йормунгарами и вернуться к замерзшему изображению Арнгрима в Дун Ниффелем.$B$BИдите в долину Древних Зим и воспользуйтесь зубом Арнгрима, чтобы воздействовать на блуждающих йормунгаров. Когда они развоплотятся, сражайтесь с ними, пока они не ослабнут.','Вы укрепляете зуб в десне Арнгрима, и у вас складывается впечатление, что муки голода старого короля ослабли… на какое-то время.','Вернитесь к Арнгриму Ненасытному в Дун Ниффелем, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Муки Арнгрима',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Голод Арнгрима вошел в легенды.$b$bДаже после смерти его лик искажен гримасой ненасытного голода. При одном только взгляде на это лицо у вас начинает бурчать в желудке.$b$bГоворят, что за всю свою жизнь он никогда не наедался досыта, а ведь он ел все подряд. Вы поневоле задумались: а есть ли способ накормить старого короля?$b$bКак только у вас возникает эта мысль, один из огромных замерзших зубов Арнгрима выпадает у него изо рта и, отскочив от его бороды, падает вам на ладонь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вы должны накормить Арнгрима пятью бесплотными йормунгарами и вернуться к замерзшему изображению Арнгрима в Дун Ниффелем.$B$BИдите в долину Древних Зим и воспользуйтесь зубом Арнгрима, чтобы воздействовать на блуждающих йормунгаров. Когда они развоплотятся, сражайтесь с ними, пока они не ослабнут.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы укрепляете зуб в десне Арнгрима, и у вас складывается впечатление, что муки голода старого короля ослабли… на какое-то время.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Арнгриму Ненасытному в Дун Ниффелем, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`endtext_loc8`) VALUES (13047,'Расплата','Локен убил мою жену и настроил против меня моих учеников, а меня против них. Он отнял у меня самое дорогое, но сегодня... все изменится.$b$bСегодня мы вернем себе наши святые земли. Сегодня... Локен умрет.$b$bВстретимся у храма Мудрости, что к юго-западу от Ульдуара. Так или иначе, я положу этому конец.$b$bМне нужен только свидетель, тебе не нужно мне помогать – это дело личное.$b$bКогда все закончится, ты пойдешь к Йоккуму, королю снежных великанов, и расскажешь о том, что было. Он – добрый друг. Он поймет, что делать.','Встретьтесь с Торимом у храма Мудрости. Потом отправляйтесь к Йоккуму в Дун Ниффелем и расскажите ему об исходе сражения.','Ах, $N! Рад видеть тебя, малышка.','Станьте свидетелем сражения') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Расплата',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Локен убил мою жену и настроил против меня моих учеников, а меня против них. Он отнял у меня самое дорогое, но сегодня... все изменится.$b$bСегодня мы вернем себе наши святые земли. Сегодня... Локен умрет.$b$bВстретимся у храма Мудрости, что к юго-западу от Ульдуара. Так или иначе, я положу этому конец.$b$bМне нужен только свидетель, тебе не нужно мне помогать – это дело личное.$b$bКогда все закончится, ты пойдешь к Йоккуму, королю снежных великанов, и расскажешь о том, что было. Он – добрый друг. Он поймет, что делать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Встретьтесь с Торимом у храма Мудрости. Потом отправляйтесь к Йоккуму в Дун Ниффелем и расскажите ему об исходе сражения.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ах, $N! Рад видеть тебя, малышка.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Станьте свидетелем сражения',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13048,'Откуда время пошло не туда','Молот Знаний может помочь нам исправить поврежденную линию времени, но для этого нам надо найти тот момент в прошлом, откуда время пошло не туда. В противном случае у нас ничего не получится.$B$BСудя по тому, что рассказал вождь Быстрое Копье, и по твоим находкам в Ледяных глубинах, можно с уверенностью предположить, что искажение произошло более-менее одновременно со смертью Штормового Копыта.$B$BОтправляйся на север, в Воющую пещеру, и обойди древние захоронения, разоренные приспешниками Северного Ветра. Молот Знаний среагирует на подлинные предметы из эры Штормового Копыта и сам настроится на истинное время.','Разыщите реликвии таунка и настройте Молот Знаний на истинное время Штормового Копыта. Когда он настроится на 6 реликвий из времени Штормового Копыта, возвращайтесь к Ксанатавру в лагерь Тунка\'ло.','<Ксанатавр забирает у вас Молот Знаний.>\n\nМы наконец "засекли" время Штормового Копыта в истинной истории. Теперь мы сможем исправить искаженную линию времени.','Ты $Gнастроил:настроила; Молот Знаний на время Штормового Копыта?','Вернитесь к Ксанатавру в лагерь Тунка’ло, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Откуда время пошло не туда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Молот Знаний может помочь нам исправить поврежденную линию времени, но для этого нам надо найти тот момент в прошлом, откуда время пошло не туда. В противном случае у нас ничего не получится.$B$BСудя по тому, что рассказал вождь Быстрое Копье, и по твоим находкам в Ледяных глубинах, можно с уверенностью предположить, что искажение произошло более-менее одновременно со смертью Штормового Копыта.$B$BОтправляйся на север, в Воющую пещеру, и обойди древние захоронения, разоренные приспешниками Северного Ветра. Молот Знаний среагирует на подлинные предметы из эры Штормового Копыта и сам настроится на истинное время.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите реликвии таунка и настройте Молот Знаний на истинное время Штормового Копыта. Когда он настроится на 6 реликвий из времени Штормового Копыта, возвращайтесь к Ксанатавру в лагерь Тунка\'ло.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Ксанатавр забирает у вас Молот Знаний.>\n\nМы наконец "засекли" время Штормового Копыта в истинной истории. Теперь мы сможем исправить искаженную линию времени.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gнастроил:настроила; Молот Знаний на время Штормового Копыта?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ксанатавру в лагерь Тунка’ло, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13049,'Доспехи героя','Похоже, не все исторические документы были испорчены вмешательством в ход времени. Мои помощники смогли разыскать записи, отражающие события подлинной линии времени.$B$BТам написано, что Штормовое Копыто был похоронен со всеми почестями среди деревенских старейшин, на нижнем ярусе Воющей пещеры.$B$BБольшинство захоронений в тех местах уже разграблено войсками Северного Ветра. Им удалось захватить несколько поистине бесценных реликвий. Отправляйся на север, в Воющую пещеру, и попытайся забрать у потомков бури копье и доспехи Штормового Копыта.','Добудьте копье и кольчугу Штормового Копыта и верните их Ксанатавру в лагерь Тунка\'ло.','Нашлись ли доспехи и оружие Штормового Копыта?','Вернитесь к Ксанатавру в лагерь Тунка’ло, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Доспехи героя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Похоже, не все исторические документы были испорчены вмешательством в ход времени. Мои помощники смогли разыскать записи, отражающие события подлинной линии времени.$B$BТам написано, что Штормовое Копыто был похоронен со всеми почестями среди деревенских старейшин, на нижнем ярусе Воющей пещеры.$B$BБольшинство захоронений в тех местах уже разграблено войсками Северного Ветра. Им удалось захватить несколько поистине бесценных реликвий. Отправляйся на север, в Воющую пещеру, и попытайся забрать у потомков бури копье и доспехи Штормового Копыта.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте копье и кольчугу Штормового Копыта и верните их Ксанатавру в лагерь Тунка\'ло.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Нашлись ли доспехи и оружие Штормового Копыта?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ксанатавру в лагерь Тунка’ло, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13050,'Веранус','Если я собираюсь атаковать армию брата, мне нужно придумать, как к ней подобраться.$B$BКогда-то у меня была самка ездового дракона, но я отпустил ее на волю. Веранус была просто великолепна. Истинная предводительница своей стаи – в которую она и вернулась.$B$BНайти ее будет непросто... и все же, я думаю, есть один способ. Она остается в своем старом пустом гнезде – исключительно из гордости. Веранус – праматерь лишь номинально, поскольку давно миновала тот возраст, когда драконы способны к размножению.$B$BПринеси мне яйца из других гнезд, расположенных вблизи Бруннхильдарской деревни. У меня есть одна мысль...','Раздобудьте 5 маленьких яиц протодракона в горах рядом с деревней Бруннхильдар и принесите их Ториму в Храм Штормов.','Ты $Gдобыл:добыла; яйца, $N?','Вернитесь к Ториму в Храм Штормов, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Веранус',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если я собираюсь атаковать армию брата, мне нужно придумать, как к ней подобраться.$B$BКогда-то у меня была самка ездового дракона, но я отпустил ее на волю. Веранус была просто великолепна. Истинная предводительница своей стаи – в которую она и вернулась.$B$BНайти ее будет непросто... и все же, я думаю, есть один способ. Она остается в своем старом пустом гнезде – исключительно из гордости. Веранус – праматерь лишь номинально, поскольку давно миновала тот возраст, когда драконы способны к размножению.$B$BПринеси мне яйца из других гнезд, расположенных вблизи Бруннхильдарской деревни. У меня есть одна мысль...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте 5 маленьких яиц протодракона в горах рядом с деревней Бруннхильдар и принесите их Ториму в Храм Штормов.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gдобыл:добыла; яйца, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ториму в Храм Штормов, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13051,'Нарушение границ','У Веранус есть гордость. Я не знаю другого такого зверя, у которого было бы столько гордости. Она все еще удерживает свое старое гнездо и отгоняет от него молодых протодраконов.$B$BВозьми собранные тобой яйца и помести их в гнездо. Ты найдешь его на вершине невысокой скалы, прямо на юго-восток отсюда.$B$BЯ смогу взять ее под контроль, прежде чем она тебя растерзает. Ну, я надеюсь...','Отнесите похищенные яйца протодракона в гнездо праматери и возвращайтесь к Ториму в Храм Штормов.','Вернитесь к Ториму в Храм Штормов, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нарушение границ',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У Веранус есть гордость. Я не знаю другого такого зверя, у которого было бы столько гордости. Она все еще удерживает свое старое гнездо и отгоняет от него молодых протодраконов.$B$BВозьми собранные тобой яйца и помести их в гнездо. Ты найдешь его на вершине невысокой скалы, прямо на юго-восток отсюда.$B$BЯ смогу взять ее под контроль, прежде чем она тебя растерзает. Ну, я надеюсь...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите похищенные яйца протодракона в гнездо праматери и возвращайтесь к Ториму в Храм Штормов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ториму в Храм Штормов, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (13052,'Воздушная разведка','Ты хорошо $gпомог:помогла; Уэсу с починкой и возвращением в строй этого ветролета.$B$BЕсли хочешь и дальше помогать нам, то знай: на нас с северо-запада надвигается необычный атмосферный фронт. У меня есть пилот, но, боюсь, по такой погоде ему нужен напарник.$B$BЕсли ты считаешь, что сможешь справиться, отправляйся в Лагерь у озера. Скажи Вику, что ты от меня.','Отправляйтесь в Лагерь у озера по просьбе профессора Кальверт и поговорите там с пилотом Виком.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Воздушная разведка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты хорошо $gпомог:помогла; Уэсу с починкой и возвращением в строй этого ветролета.$B$BЕсли хочешь и дальше помогать нам, то знай: на нас с северо-запада надвигается необычный атмосферный фронт. У меня есть пилот, но, боюсь, по такой погоде ему нужен напарник.$B$BЕсли ты считаешь, что сможешь справиться, отправляйся в Лагерь у озера. Скажи Вику, что ты от меня.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Лагерь у озера по просьбе профессора Кальверт и поговорите там с пилотом Виком.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`) VALUES (13053,'В поисках уцелевших','Гретхен Искрошип хочет использовать мой ветролет, чтобы разыскать уцелевших людей из ее экспедиции. Она считает, что их держат в плену в деревне на севере.$B$BПроблема в том, что у меня нет второго пилота. Если ты согласишься лететь со мной, я обучу тебя паре приемов.$B$BЧто скажешь, $n? По рукам?','Помогите Заку Шестеркруту совершить испытательный полет.','Испытательный полет','Вернитесь к "Честному" Максу к Водопаду Бора, что в Грозовой Гряде.','Испытательный полет') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В поисках уцелевших',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Гретхен Искрошип хочет использовать мой ветролет, чтобы разыскать уцелевших людей из ее экспедиции. Она считает, что их держат в плену в деревне на севере.$B$BПроблема в том, что у меня нет второго пилота. Если ты согласишься лететь со мной, я обучу тебя паре приемов.$B$BЧто скажешь, $n? По рукам?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Помогите Заку Шестеркруту совершить испытательный полет.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Испытательный полет',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к "Честному" Максу к Водопаду Бора, что в Грозовой Гряде.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Испытательный полет',`questgivertextwindow_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13054,'Пропавший следопыт','Я не могу со спокойной совестью отправить тебя в пещеру воргов, не предупредив об опасности. Тот, кто пошел туда до тебя, не вернулся.$B$BМы уже приготовились к самому худшему, но оказалось, что он еще жив. Если ты поможешь ему вернуться, мы будем очень тебе благодарны. У нас осталось очень немного охотников, а следопыт Вал\'зиж – один из лучших.','Разыщите следопыта Вал\'зижа в логове Гиморака, на юго-востоке от места крушения Гром\'арша.','Очень больно… похоже, что долго я не протяну.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пропавший следопыт',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я не могу со спокойной совестью отправить тебя в пещеру воргов, не предупредив об опасности. Тот, кто пошел туда до тебя, не вернулся.$B$BМы уже приготовились к самому худшему, но оказалось, что он еще жив. Если ты поможешь ему вернуться, мы будем очень тебе благодарны. У нас осталось очень немного охотников, а следопыт Вал\'зиж – один из лучших.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите следопыта Вал\'зижа в логове Гиморака, на юго-востоке от места крушения Гром\'арша.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Очень больно… похоже, что долго я не протяну.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (13055,'Лекарство из пещер','Как приятно увидеть доброжелательное лицо. Кто знает, может быть, это в последний раз.$B$BЯ уже почти выбрался, и тут меня укусил йормунгар. А они ядовиты. Все мое тело уже немеет, я чувствую.$B$BМне нужно противоядие, а для этого надо добыть ядовитую железу у кого-то из этих тварей. И еще мне понадобятся пещерные грибы, чтобы замедлить действие яда... грибы растут здесь...$B$BПожалуйста, поторопись. У меня мало времени.','Добудьте 1 ядовитую железу йормунгара и 8 пещерных грибов и доставьте следопыту Вал\'зижу в Логово Гиморака.','Спасибо, друг. Теперь я смогу продержаться еще один день.','Вернитесь к следопыту Вал\'зижу в Логово Гиморака, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лекарство из пещер',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как приятно увидеть доброжелательное лицо. Кто знает, может быть, это в последний раз.$B$BЯ уже почти выбрался, и тут меня укусил йормунгар. А они ядовиты. Все мое тело уже немеет, я чувствую.$B$BМне нужно противоядие, а для этого надо добыть ядовитую железу у кого-то из этих тварей. И еще мне понадобятся пещерные грибы, чтобы замедлить действие яда... грибы растут здесь...$B$BПожалуйста, поторопись. У меня мало времени.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 1 ядовитую железу йормунгара и 8 пещерных грибов и доставьте следопыту Вал\'зижу в Логово Гиморака.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо, друг. Теперь я смогу продержаться еще один день.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к следопыту Вал\'зижу в Логово Гиморака, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (13056,'Всегда найдется время для мести','Теперь мне должно стать полегче. Думаю, как-нибудь справлюсь. И все же, $n, я попрошу тебя об одной услуге.$B$BНикто из этих червей не смог бы меня одолеть, если бы подлейший из воргов не убил моего крылатого змея, Хиишу.$B$BОбо мне можешь не беспокоиться. Мне станет легче, когда этот мерзавец ворг сдохнет. Ты найдешь его в глубине пещеры.','Убейте Гиморака в пещере Ледяного Воя по просьбе следопыта Вал\'зижа.','Мне уже лучше, честное слово. Не знаю, то ли подействовало противоядие, то ли меня греет мысль, что этот мерзкий ворг получил по заслугам.','Вернитесь к следопыту Вал\'зижу в Логово Гиморака, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Всегда найдется время для мести',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь мне должно стать полегче. Думаю, как-нибудь справлюсь. И все же, $n, я попрошу тебя об одной услуге.$B$BНикто из этих червей не смог бы меня одолеть, если бы подлейший из воргов не убил моего крылатого змея, Хиишу.$B$BОбо мне можешь не беспокоиться. Мне станет легче, когда этот мерзавец ворг сдохнет. Ты найдешь его в глубине пещеры.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Гиморака в пещере Ледяного Воя по просьбе следопыта Вал\'зижа.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мне уже лучше, честное слово. Не знаю, то ли подействовало противоядие, то ли меня греет мысль, что этот мерзкий ворг получил по заслугам.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к следопыту Вал\'зижу в Логово Гиморака, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (13057,'Терраса Творцов','Время пришло, $n. Я готов к встрече с Локеном. Мы отправимся на Террасу Творцов и дадим бой армиям моего брата. Этот дурак пожалеет, что связался со мной.','Разыщите Торима на юго-восточном конце Террасы Творцов, к северо-западу от Дун Ниффелема.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Терраса Творцов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Время пришло, $n. Я готов к встрече с Локеном. Мы отправимся на Террасу Творцов и дадим бой армиям моего брата. Этот дурак пожалеет, что связался со мной.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите Торима на юго-восточном конце Террасы Творцов, к северо-западу от Дун Ниффелема.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13058,'Чтобы ветер переменился','Теперь у нас есть все необходимое, чтобы исправить все то, что испортил Северный Ветер и его приспешники. Ты $gнастроил:настроила; Молот Знаний на время и личность Штормового Копыта.$B$BСнова возьми молот и отправляйся к Храму Жизни, на равнины к северо-западу. Воспользуйся молотом, чтобы принять облик Штормового Копыта. Потом иди к Северному Ветру под личиной Штормового Копыта, но помни, что в той линии времени, которую нужно восстановить, Штормовое Копыто должен умереть, когда Северный Ветер ослабеет.$B$BТы используешь этот шанс и при помощи рога неистовства стихий уничтожишь Северного Ветра.','Используйте Молот Знаний, чтобы вернуться в прошлое и сразиться с Северным Ветром под личиной Штормового Копыта. Когда Штормовое Копыто падет, возьмите рог неистовства стихий и прикончите Северного Ветра, а затем возвращайтесь к Ксанатавру в лагерь Тунка\'ло.','Твой сегодняшний подвиг не даст Штормовому Копыту и его славным деяниям сгинуть в безвестности. Твое имя тоже навечно войдет в историю Азерота. Я все запомню и опишу твои подвиги, дабы они сохранились в веках!','Ну что, получилось? Истинная линия времени восстановлена?','Вернитесь к Ксанатавру в лагерь Тунка’ло, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чтобы ветер переменился',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь у нас есть все необходимое, чтобы исправить все то, что испортил Северный Ветер и его приспешники. Ты $gнастроил:настроила; Молот Знаний на время и личность Штормового Копыта.$B$BСнова возьми молот и отправляйся к Храму Жизни, на равнины к северо-западу. Воспользуйся молотом, чтобы принять облик Штормового Копыта. Потом иди к Северному Ветру под личиной Штормового Копыта, но помни, что в той линии времени, которую нужно восстановить, Штормовое Копыто должен умереть, когда Северный Ветер ослабеет.$B$BТы используешь этот шанс и при помощи рога неистовства стихий уничтожишь Северного Ветра.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте Молот Знаний, чтобы вернуться в прошлое и сразиться с Северным Ветром под личиной Штормового Копыта. Когда Штормовое Копыто падет, возьмите рог неистовства стихий и прикончите Северного Ветра, а затем возвращайтесь к Ксанатавру в лагерь Тунка\'ло.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Твой сегодняшний подвиг не даст Штормовому Копыту и его славным деяниям сгинуть в безвестности. Твое имя тоже навечно войдет в историю Азерота. Я все запомню и опишу твои подвиги, дабы они сохранились в веках!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, получилось? Истинная линия времени восстановлена?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ксанатавру в лагерь Тунка’ло, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13059,'Месть за варгулов','Бросьте меч в Круге Страдания, вызовите на бой и убейте тана Иллскара по просьбе Бетода Фейгра из Глубинных чертогов.','Я чувствую, что ты еще не $Gсразил:сразила; Тана Иллскара. Что остановило твою руку?','Вернитесь к Бетоду Фейгру в Глубинные чертоги, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Месть за варгулов',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Бросьте меч в Круге Страдания, вызовите на бой и убейте тана Иллскара по просьбе Бетода Фейгра из Глубинных чертогов.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я чувствую, что ты еще не $Gсразил:сразила; Тана Иллскара. Что остановило твою руку?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бетоду Фейгру в Глубинные чертоги, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (13060,'Когда остается единственный выход...','Что-то я сомневаюсь, что нам удастся закрепиться в этих горах.$B$BПоверь мне, я не из тех, кто легко сдается... но, когда ты зажат между замерзшими машинами, злобными врайкульскими бабами, какими-то непонятными существами, жаждущими стать драконами, и еще добрым десятком других воинственных тварей, это как-то не способствует оптимистическому настрою.$B$BНо ты все же не падай духом! Если мы не можем там закрепиться, это еще не значит, что мы не можем доставить тебя туда... поездка в один конец – это вовсе не сложно, когда привыкаешь.$B$B<Рикет указывает на ракеты неподалеку.>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Когда остается единственный выход...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что-то я сомневаюсь, что нам удастся закрепиться в этих горах.$B$BПоверь мне, я не из тех, кто легко сдается... но, когда ты зажат между замерзшими машинами, злобными врайкульскими бабами, какими-то непонятными существами, жаждущими стать драконами, и еще добрым десятком других воинственных тварей, это как-то не способствует оптимистическому настрою.$B$BНо ты все же не падай духом! Если мы не можем там закрепиться, это еще не значит, что мы не можем доставить тебя туда... поездка в один конец – это вовсе не сложно, когда привыкаешь.$B$B<Рикет указывает на ракеты неподалеку.>',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (13061,'Победа или смерть','Ну вот, время пришло. Я позабочусь о твоей медведице, сейчас она тебе не понадобится. Теперь тебе предстоит сразиться с великим Драконобойцей.$B$BПопрощайся с друзьями, приведи в порядок дела, ибо ты либо вернешься с победой... либо не вернешься вообще.','Поговорите с Лок\'лирой Каргой в деревне Бруннхильдар.','Ты неплохо справляешься. Честно сказать, я не думала, что ты сумеешь добиться столь выдающегося положения среди хильд за такое короткое время.','Ты уничтожила зараженные яйца?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Победа или смерть',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну вот, время пришло. Я позабочусь о твоей медведице, сейчас она тебе не понадобится. Теперь тебе предстоит сразиться с великим Драконобойцей.$B$BПопрощайся с друзьями, приведи в порядок дела, ибо ты либо вернешься с победой... либо не вернешься вообще.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Лок\'лирой Каргой в деревне Бруннхильдар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты неплохо справляешься. Честно сказать, я не думала, что ты сумеешь добиться столь выдающегося положения среди хильд за такое короткое время.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты уничтожила зараженные яйца?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (13062,'Прощальный подарок Лок\'лиры','Твоя помощь неоценима, $n. Теперь пришло время для настоящего испытания. Тебе понадобится все твое мастерство, мужество и немного везения.$B$B<Лок\'лира прикрепляет к вашим волосам тонкую прядь волос.>$B$BУ тебя все получится. Должно получиться. Поговори с Греттой Судьей. Она скажет тебе, что делать.','Поговорите с Греттой Судьей в деревне Бруннхильдар.','Ты готова, сестра? Помни: назад пути нет.','Ты уничтожила зараженные яйца?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прощальный подарок Лок\'лиры',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Твоя помощь неоценима, $n. Теперь пришло время для настоящего испытания. Тебе понадобится все твое мастерство, мужество и немного везения.$B$B<Лок\'лира прикрепляет к вашим волосам тонкую прядь волос.>$B$BУ тебя все получится. Должно получиться. Поговори с Греттой Судьей. Она скажет тебе, что делать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Греттой Судьей в деревне Бруннхильдар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты готова, сестра? Помни: назад пути нет.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты уничтожила зараженные яйца?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (13063,'Посмотрим, чего ты стоишь','Сестра, ты добилась успеха там, где многих постигла неудача. Остается лишь выяснить, что тебе помогло: твоя сила и доблесть или простое везение.$b$bВозвращайся в деревню и разыщи там Астрид Бьорнриттар. Расскажи ей о своих достижениях. Только я тебя сразу предупреждаю: на нее нелегко произвести впечатление.','По просьбе Бриджаны отправляйтесь в деревню Бруннхильдар и поговорите с Астрид Бьорнриттар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Посмотрим, чего ты стоишь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сестра, ты добилась успеха там, где многих постигла неудача. Остается лишь выяснить, что тебе помогло: твоя сила и доблесть или простое везение.$b$bВозвращайся в деревню и разыщи там Астрид Бьорнриттар. Расскажи ей о своих достижениях. Только я тебя сразу предупреждаю: на нее нелегко произвести впечатление.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По просьбе Бриджаны отправляйтесь в деревню Бруннхильдар и поговорите с Астрид Бьорнриттар.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13064,'Соперничество братьев','Сиф? Это ты? Правда, ты?$b$bНет? $r? Но на мгновение мне показалось...$b$bВсе, хватит! Видения, в которых являлась мне моя Сиф, они терзали меня слишком долго! Пора отомстить за нее и почтить ее память, как должно.$b$bМой брат заплатит за все!','Выслушайте историю Торима.','Слушай меня, |3-6($R).','Вернитесь к Ториму в Храм Штормов, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Соперничество братьев',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сиф? Это ты? Правда, ты?$b$bНет? $r? Но на мгновение мне показалось...$b$bВсе, хватит! Видения, в которых являлась мне моя Сиф, они терзали меня слишком долго! Пора отомстить за нее и почтить ее память, как должно.$b$bМой брат заплатит за все!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выслушайте историю Торима.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Слушай меня, |3-6($R).',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ториму в Храм Штормов, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (13065,'Предок Оханзи','Приятно знать, что народ этих земель все еще отдает дань уважения древним расам. Всего хорошего, $n. Прими этот знак...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Предок Оханзи',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Приятно знать, что народ этих земель все еще отдает дань уважения древним расам. Всего хорошего, $n. Прими этот знак...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (13066,'Предок Яруак','Приятно знать, что народ этих земель все еще отдает дань уважения древним расам. Всего хорошего, $n. Прими этот знак...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Предок Яруак',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Приятно знать, что народ этих земель все еще отдает дань уважения древним расам. Всего хорошего, $n. Прими этот знак...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (13067,'Предок Чоган\'гада','Приятно знать, что народ этих земель все еще отдает дань уважения древним расам. Всего хорошего, $n. Прими этот знак...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Предок Чоган\'гада',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Приятно знать, что народ этих земель все еще отдает дань уважения древним расам. Всего хорошего, $n. Прими этот знак...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13068,'Отважный герой','Вероятно, ты $gслышал:слышала; о доблестных подвигах нашего пропавшего героя?$B$BРыцарь Бриденбрад сражался с силами Плети на Прорванном фронте, и тут на союзников напало войско нежити. Многие солдаты союзных войск навечно остались на поле боя, но Бриденбрад уцелел и спас больше дюжины воинов – вытащил их из этой мясорубки, одного за другим.$B$BТак вот, |3-6($c), после этого он не вернулся. В последний раз его видели, когда он направлялся на северо-восток, в сторону Молчаливого Бдения. Найди его и приведи ко мне, и я воздам ему почести, подобающие доблестному герою.','Отправляйтесь в северо-восточную часть Ледяной Короны, разыщите героя, рыцаря Бриденбрада, в Молчаливом Бдении и приведите его к верховному лорду Тириону Фордрингу на Вершину Рыцарей. Возле его стоянки обычно горит костер, заметный с воздуха.','Не подходи! Берегись! Я заражен! И не хочу, чтобы эта зараза коснулась тебя или кого-то еще!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отважный герой',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вероятно, ты $gслышал:слышала; о доблестных подвигах нашего пропавшего героя?$B$BРыцарь Бриденбрад сражался с силами Плети на Прорванном фронте, и тут на союзников напало войско нежити. Многие солдаты союзных войск навечно остались на поле боя, но Бриденбрад уцелел и спас больше дюжины воинов – вытащил их из этой мясорубки, одного за другим.$B$BТак вот, |3-6($c), после этого он не вернулся. В последний раз его видели, когда он направлялся на северо-восток, в сторону Молчаливого Бдения. Найди его и приведи ко мне, и я воздам ему почести, подобающие доблестному герою.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в северо-восточную часть Ледяной Короны, разыщите героя, рыцаря Бриденбрада, в Молчаливом Бдении и приведите его к верховному лорду Тириону Фордрингу на Вершину Рыцарей. Возле его стоянки обычно горит костер, заметный с воздуха.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Не подходи! Берегись! Я заражен! И не хочу, чтобы эта зараза коснулась тебя или кого-то еще!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13069,'Пристрели их','Йотунхейм славится надежной воздушной обороной – это наездники на протодраконах и гарпунные пушки. Особенно много их возле наиболее уязвимых частей города: на севере и на западе.$B$BТак давай используем их оборону против них же!$B$B<Прыгун буравит вас своим единственным глазом и издает маниакальный смешок.>$B$BЗавладей гарпунной пушкой на любой из платформ, висящих над скалами на юго-западе, и уничтожь протодраконов и их наездников. Пристрели их!','По заданию Прыгуна из Мрачного Свода сбейте с помощью йотунхеймского скорострельного гарпуна 15 йотунхеймских протодраконов и их наездников.','Тск, тск... ты сегодня еще не $Gсбил:сбила; свою часть протодраконов!','Вернитесь к Прыгуну в Мрачный Свод, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пристрели их',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Йотунхейм славится надежной воздушной обороной – это наездники на протодраконах и гарпунные пушки. Особенно много их возле наиболее уязвимых частей города: на севере и на западе.$B$BТак давай используем их оборону против них же!$B$B<Прыгун буравит вас своим единственным глазом и издает маниакальный смешок.>$B$BЗавладей гарпунной пушкой на любой из платформ, висящих над скалами на юго-западе, и уничтожь протодраконов и их наездников. Пристрели их!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По заданию Прыгуна из Мрачного Свода сбейте с помощью йотунхеймского скорострельного гарпуна 15 йотунхеймских протодраконов и их наездников.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тск, тск... ты сегодня еще не $Gсбил:сбила; свою часть протодраконов!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Прыгуну в Мрачный Свод, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (13070,'Приближение холодного фронта','С запада веет холодом смерти, и холод этот грозится заморозить наши сердца и души и отдать их под власть темного властелина этих снежных пустошей. Но мы не сдаемся! Мы будем сражаться!$B$BПодготовка уже началась. Поговори с осадным мастером Феззиком у главных ворот, и он объяснит тебе твое задание.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приближение холодного фронта',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','С запада веет холодом смерти, и холод этот грозится заморозить наши сердца и души и отдать их под власть темного властелина этих снежных пустошей. Но мы не сдаемся! Мы будем сражаться!$B$BПодготовка уже началась. Поговори с осадным мастером Феззиком у главных ворот, и он объяснит тебе твое задание.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13071,'Злоб любит огонь!','Злоб любит огонь! Злоб любит протодраконов!$B$B<Поганище радостно хлопает в ладоши.>$B$B$GМалыш:Малышка; $n, ступай в Йотунхейм и укради симпатичного протодракончика в деревне Ньорндар. Заставь протодракончика поджечь с десяток построек в Йотунхейме. Чтобы красиво горело красивым огнем!','По просьбе Злоба из Мрачного Свода украдите ньорндарского протодракона и заставьте его поджечь 8 построек врайкулов в Йотунхейме.$B$BЦитадель Балагарда, в силу своей природы, гореть не может.','Что?Не вижу большого огня!!!$B$B$N, вернитись и сделай больше огня!','Вернитесь к Злобу в Мрачный Свод, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Злоб любит огонь!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Злоб любит огонь! Злоб любит протодраконов!$B$B<Поганище радостно хлопает в ладоши.>$B$B$GМалыш:Малышка; $n, ступай в Йотунхейм и укради симпатичного протодракончика в деревне Ньорндар. Заставь протодракончика поджечь с десяток построек в Йотунхейме. Чтобы красиво горело красивым огнем!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По просьбе Злоба из Мрачного Свода украдите ньорндарского протодракона и заставьте его поджечь 8 построек врайкулов в Йотунхейме.$B$BЦитадель Балагарда, в силу своей природы, гореть не может.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что?Не вижу большого огня!!!$B$B$N, вернитись и сделай больше огня!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Злобу в Мрачный Свод, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (13072,'Горькая участь героя','Я знаю, зачем ты $gпришел:пришла;... Тебя прислали за мной... только вернуться я не смогу. Я заражен чумой нежити, |3-6($c), и не хочу, чтобы эта зараза коснулась кого-то еще. Нет, я никуда не пойду.$B$BСмерти я не боюсь. Но я знаю, во что превращусь после смерти, и мне ненавистна сама мысль о том, что мне волей-неволей придется служить этому подлому предателю Артасу.$B$BОставь меня... и позаботься о том, чтобы меня не искали. Ты сослужишь мне плохую службу, если, желая спасти меня, ты невольно разнесешь эту заразу.','Расскажите о том, что случилось с рыцарем Бриденбрадом, верховному лорду Тириону Фордрингу на Вершине Рыцарей.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Горькая участь героя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я знаю, зачем ты $gпришел:пришла;... Тебя прислали за мной... только вернуться я не смогу. Я заражен чумой нежити, |3-6($c), и не хочу, чтобы эта зараза коснулась кого-то еще. Нет, я никуда не пойду.$B$BСмерти я не боюсь. Но я знаю, во что превращусь после смерти, и мне ненавистна сама мысль о том, что мне волей-неволей придется служить этому подлому предателю Артасу.$B$BОставь меня... и позаботься о том, чтобы меня не искали. Ты сослужишь мне плохую службу, если, желая спасти меня, ты невольно разнесешь эту заразу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Расскажите о том, что случилось с рыцарем Бриденбрадом, верховному лорду Тириону Фордрингу на Вершине Рыцарей.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (13073,'Благосклонность хранителя','В мире есть те, кто обладает неограниченной силой: силой Жизни, силой Света, силой Воскрешения. Бриденбрад – не просто обычный человек... Его доблесть и отвага удивительны. Нам остается только надеяться, что кто-то сможет спасти героя от участи худшей, чем смерть.$B$BОтправляйся к верховному друиду Лилиандре в Оплот Серебряного Авангарда. Попроси ее провести тебя к Лунной поляне и обратись за помощью к хранителю Ремулу.','По просьбе верховного лорда Тириона Фордринга с Вершины Рыцарей поговорите с верховным друидом Лилиандрой и доберитесь до хранителя Ремула на Лунной поляне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Благосклонность хранителя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В мире есть те, кто обладает неограниченной силой: силой Жизни, силой Света, силой Воскрешения. Бриденбрад – не просто обычный человек... Его доблесть и отвага удивительны. Нам остается только надеяться, что кто-то сможет спасти героя от участи худшей, чем смерть.$B$BОтправляйся к верховному друиду Лилиандре в Оплот Серебряного Авангарда. Попроси ее провести тебя к Лунной поляне и обратись за помощью к хранителю Ремулу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По просьбе верховного лорда Тириона Фордринга с Вершины Рыцарей поговорите с верховным друидом Лилиандрой и доберитесь до хранителя Ремула на Лунной поляне.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13074,'Нам нужны желуди, обладающие мощной восстанавливающей магией, а они есть только в Изумрудном Сне. Многое на этой священной поляне тесно связано со Сном, в том числе и мое святилище.$B$BЯ отправлю тебя в Сон, и ты добудешь там такие желуди. Но будь $gготов:готова; ко всему, |3-6($c): такой способ погружения в Сон очень опасен, и вполне возможно, ты окажешься в самом настоящем кошмаре.$B$BДобудь желуди как можно быстрее. Чтобы вернуться в реальный мир, тебе надо будет покинуть святилище – или же просто ущипнуть себя и проснуться.','По заданию хранителя Ремула с Лунной поляны погрузитесь в Изумрудный Сон и добудьте 3 изумрудных желудя.$B$BЧтобы пробудиться, покиньте святилище Ремула или ущипните себя.','Вернитесь к хранителю Ремулу в Святилище Ремула, что на Лунной поляне.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нам нужны желуди, обладающие мощной восстанавливающей магией, а они есть только в Изумрудном Сне. Многое на этой священной поляне тесно связано со Сном, в том числе и мое святилище.$B$BЯ отправлю тебя в Сон, и ты добудешь там такие желуди. Но будь $gготов:готова; ко всему, |3-6($c): такой способ погружения в Сон очень опасен, и вполне возможно, ты окажешься в самом настоящем кошмаре.$B$BДобудь желуди как можно быстрее. Чтобы вернуться в реальный мир, тебе надо будет покинуть святилище – или же просто ущипнуть себя и проснуться.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По заданию хранителя Ремула с Лунной поляны погрузитесь в Изумрудный Сон и добудьте 3 изумрудных желудя.$B$BЧтобы пробудиться, покиньте святилище Ремула или ущипните себя.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к хранителю Ремулу в Святилище Ремула, что на Лунной поляне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13075,'Дар Ремула','Я открою портал. Он приведет тебя обратно к друиду, который отправил тебя сюда. Желаю удачи тебе и особенно – твоему рыцарю. Надеюсь, этот желудь очистит твоего рыцаря от скверны и спасет его от печальной судьбы зараженных.$B$BПрощай, |3-6($r).','Отнесите изумрудный желудь рыцарю Бриденбраду в Молчаливое Бдение, что в Ледяной Короне.','Вернитесь к рыцарю Бриденбраду в Молчаливое Бдение, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дар Ремула',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я открою портал. Он приведет тебя обратно к друиду, который отправил тебя сюда. Желаю удачи тебе и особенно – твоему рыцарю. Надеюсь, этот желудь очистит твоего рыцаря от скверны и спасет его от печальной судьбы зараженных.$B$BПрощай, |3-6($r).',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите изумрудный желудь рыцарю Бриденбраду в Молчаливое Бдение, что в Ледяной Короне.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к рыцарю Бриденбраду в Молчаливое Бдение, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13076,'Время еще есть','Я чувствую себя как будто бы обновленным. Но чума не отступила до конца. Но невелика печаль! Я так благодарен тебе, ведь мы совсем незнакомы, а ты $gпроделал:проделала; ради меня такой путь. Ты $gподарил:подарила; мне несколько драгоценных часов жизни, когда я не буду заражать остальных, как это делает мерзкая нежить.$b$BСпасибо тебе, |3-6($c). И передай, пожалуйста, мою благодарность Тириону. Скажи ему, что помочь ему было для меня настоящей честью.','Возвращайтесь к верховному лорду Тириону Фордрингу на Вершину Рыцарей и сообщите ему о том, каким действием обладают изумрудные желуди.','Жаль, что ничего не получилось. Однако беспокоиться не стоит, я знаю и других желающих помочь нам.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Время еще есть',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я чувствую себя как будто бы обновленным. Но чума не отступила до конца. Но невелика печаль! Я так благодарен тебе, ведь мы совсем незнакомы, а ты $gпроделал:проделала; ради меня такой путь. Ты $gподарил:подарила; мне несколько драгоценных часов жизни, когда я не буду заражать остальных, как это делает мерзкая нежить.$b$BСпасибо тебе, |3-6($c). И передай, пожалуйста, мою благодарность Тириону. Скажи ему, что помочь ему было для меня настоящей честью.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возвращайтесь к верховному лорду Тириону Фордрингу на Вершину Рыцарей и сообщите ему о том, каким действием обладают изумрудные желуди.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Жаль, что ничего не получилось. Однако беспокоиться не стоит, я знаю и других желающих помочь нам.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (13077,'Прикосновение Аспекта','Королева драконов Алекстраза всегда обладала способностями к магии. Своим огнем она умеет выжигать нежить и создавать новую жизнь. Кто знает, может, она и Бриденбраду поможет.$B$BАлекстраза живет в храме Драконьего Покоя, что в Драконьем Погосте. Отправляйся к ней и передай мою нижайшую просьбу о помощи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прикосновение Аспекта',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Королева драконов Алекстраза всегда обладала способностями к магии. Своим огнем она умеет выжигать нежить и создавать новую жизнь. Кто знает, может, она и Бриденбраду поможет.$B$BАлекстраза живет в храме Драконьего Покоя, что в Драконьем Погосте. Отправляйся к ней и передай мою нижайшую просьбу о помощи.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13078,'Слезы Далии','В эти темные времена я не брошу поборника Света в беде.$B$BНам нужно что-то, наделенное святой силой: что-то, что даст нам надежду на спасение твоего Бриденбрада... Останки верного, преданного существа, павшего жертвой той же угрозы.$B$BОтправляйся к священной земле, окружающей Рубиновое святилище драконов. Когда Рубиновые хранители воспламенят землю под ногами нежити, ты увидишь, как зарождается и тянется к свету новая жизнь. Среди ростков будут и слезы Далии – принеси их мне.','С помощью слез Далии и древней магии я сотворю крупицу надежды для твоего великого рыцаря.','О, милая Далия, как мне тебя не хватает!','Вернитесь к Алекстразе Хранительнице Жизни в Храм Драконьего Покоя, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Слезы Далии',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В эти темные времена я не брошу поборника Света в беде.$B$BНам нужно что-то, наделенное святой силой: что-то, что даст нам надежду на спасение твоего Бриденбрада... Останки верного, преданного существа, павшего жертвой той же угрозы.$B$BОтправляйся к священной земле, окружающей Рубиновое святилище драконов. Когда Рубиновые хранители воспламенят землю под ногами нежити, ты увидишь, как зарождается и тянется к свету новая жизнь. Среди ростков будут и слезы Далии – принеси их мне.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','С помощью слез Далии и древней магии я сотворю крупицу надежды для твоего великого рыцаря.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','О, милая Далия, как мне тебя не хватает!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Алекстразе Хранительнице Жизни в Храм Драконьего Покоя, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13079,'Дар Алекстразы','Ты $gдолжен:должна; понимать, $gюный:юная:r; |3-6($r), что моей власти достаточно, чтобы очистить тело во имя новой жизни... но изгнать из него чуму нежити так, чтобы не повредить само тело – это выше моих сил.$B$BЕсли все обстоит так, как ты говоришь, и этот Бриденбрад и вправду столь доблестный рыцарь и верный поборник Света, может быть, он и выдержит обряд очищения, но я не могу ничего обещать. Вот, возьми это, и прими мое благословение.','Отнесите Дыхание Алекстразы рыцарю Бриденбраду в Молчаливое Бдение, что в Ледяной Короне.','Вернитесь к рыцарю Бриденбраду в Молчаливое Бдение, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дар Алекстразы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gдолжен:должна; понимать, $gюный:юная:r; |3-6($r), что моей власти достаточно, чтобы очистить тело во имя новой жизни... но изгнать из него чуму нежити так, чтобы не повредить само тело – это выше моих сил.$B$BЕсли все обстоит так, как ты говоришь, и этот Бриденбрад и вправду столь доблестный рыцарь и верный поборник Света, может быть, он и выдержит обряд очищения, но я не могу ничего обещать. Вот, возьми это, и прими мое благословение.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите Дыхание Алекстразы рыцарю Бриденбраду в Молчаливое Бдение, что в Ледяной Короне.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к рыцарю Бриденбраду в Молчаливое Бдение, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13080,'Надежда жива','<Бриденбрад машет вам рукой, одновременно пытаясь отдышаться.>$B$BКак я и ожидал, было очень больно, но я буквально почувствовал, как порча уходит из моего тела. Но чуму так легко не изгонишь.$B$BСпасибо тебе за все, |3-6($c). Твоя самоотверженность заставила меня поверить, что в мире еще есть много хорошего и надежда жива. Я могу уйти, не боясь, что в мое отсутствие тьма возобладает над светом.$B$BА теперь иди. Иди и ни о чем не жалей.','Вернитесь к верховному лорду Тириону Фордрингу на Вершину Рыцарей. Расскажите ему о действии Дыхания Алекстразы.','Чума Плети – страшный враг. По словам Алекстразы, есть надежда, что Бриденбрад избежит участи нежити – в случае, если нам не удастся спасти его жизнь. Но я не хочу сдаваться так легко.$B$BЕсть еще один способ, который я хотел бы опробовать. Вероятно, одно существо способно предотвратить то, чего мы так боимся.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Надежда жива',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Бриденбрад машет вам рукой, одновременно пытаясь отдышаться.>$B$BКак я и ожидал, было очень больно, но я буквально почувствовал, как порча уходит из моего тела. Но чуму так легко не изгонишь.$B$BСпасибо тебе за все, |3-6($c). Твоя самоотверженность заставила меня поверить, что в мире еще есть много хорошего и надежда жива. Я могу уйти, не боясь, что в мое отсутствие тьма возобладает над светом.$B$BА теперь иди. Иди и ни о чем не жалей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь к верховному лорду Тириону Фордрингу на Вершину Рыцарей. Расскажите ему о действии Дыхания Алекстразы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Чума Плети – страшный враг. По словам Алекстразы, есть надежда, что Бриденбрад избежит участи нежити – в случае, если нам не удастся спасти его жизнь. Но я не хочу сдаваться так легко.$B$BЕсть еще один способ, который я хотел бы опробовать. Вероятно, одно существо способно предотвратить то, чего мы так боимся.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (13081,'Завещание наару','Мы очень благодарны за все, что ты для нас $gсделал:сделала;, $n. У меня есть к тебе последняя просьба... Последняя надежда для паладина, достойного большего, чем мы можем дать.$B$BОтправляйся в Шаттрат и поговори с А\'далом из народа наару. Он всегда был поборником Света и преданным другом паладинов. Расскажи ему историю Бриденбрада и попроси о помощи.$B$BЯ даже передать не могу, насколько это важно. Боюсь, если ты не поторопишься, ничто уже не спасет нашего рыцаря.','Попросите о помощи А\'дала из Шаттрата, который находится в лесу Тероккар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Завещание наару',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы очень благодарны за все, что ты для нас $gсделал:сделала;, $n. У меня есть к тебе последняя просьба... Последняя надежда для паладина, достойного большего, чем мы можем дать.$B$BОтправляйся в Шаттрат и поговори с А\'далом из народа наару. Он всегда был поборником Света и преданным другом паладинов. Расскажи ему историю Бриденбрада и попроси о помощи.$B$BЯ даже передать не могу, насколько это важно. Боюсь, если ты не поторопишься, ничто уже не спасет нашего рыцаря.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Попросите о помощи А\'дала из Шаттрата, который находится в лесу Тероккар.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (13082,'Дар А\'дала','Рад тебя видеть, $n. Я знаю, что случилось с рыцарем Бриденбрадом. И как ты $gпытался:пыталась; его спасти, тоже знаю. Видно, отвага Бриденбрада передалась и тебе, а это уже само по себе чудо.$B$BСвет помогает тем, кто ему верен. Я благословлю Бриденбрада, и ему больше не будет угрожать участь нежити. Тебя же я перенесу обратно, в Даларан, чтобы ты $gсмог:смогла; его найти. И помни: я всегда с тобой.','Вернитесь к рыцарю Бриденбраду в Молчаливое Бдение, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дар А\'дала',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Рад тебя видеть, $n. Я знаю, что случилось с рыцарем Бриденбрадом. И как ты $gпытался:пыталась; его спасти, тоже знаю. Видно, отвага Бриденбрада передалась и тебе, а это уже само по себе чудо.$B$BСвет помогает тем, кто ему верен. Я благословлю Бриденбрада, и ему больше не будет угрожать участь нежити. Тебя же я перенесу обратно, в Даларан, чтобы ты $gсмог:смогла; его найти. И помни: я всегда с тобой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь к рыцарю Бриденбраду в Молчаливое Бдение, что в Ледяной Короне.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13083,'Свет во тьме','<Накидка рыцаря Бриденбрада лежит на дне сундука и легонько колышется от ветра, проникшего внутрь.>$B$BТирион наверняка захочет получить эту последнюю реликвию, оставшуюся от великого рыцаря.','Отнесите плащ рыцаря Бриденбрада верховному лорду Тириону Фордрингу на Вершину Рыцарей.','Он ушел, да? Его больше нет? Я почувствовал, как из этого мира исчез кусочек света, и в мире стало темнее...','Вернитесь к верховному лорду Тириону Фордрингу на Вершину Рыцарей, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Свет во тьме',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Накидка рыцаря Бриденбрада лежит на дне сундука и легонько колышется от ветра, проникшего внутрь.>$B$BТирион наверняка захочет получить эту последнюю реликвию, оставшуюся от великого рыцаря.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите плащ рыцаря Бриденбрада верховному лорду Тириону Фордрингу на Вершину Рыцарей.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Он ушел, да? Его больше нет? Я почувствовал, как из этого мира исчез кусочек света, и в мире стало темнее...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному лорду Тириону Фордрингу на Вершину Рыцарей, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13084,'Психологическая атака','Нам удалось подорвать боевой дух врайкулов, $n, и надо бы продолжать в том же духе.$B$BЯ хочу, чтобы ты каждый день $gездил:ездила; в Йотунхейм и $gпредавал:предавала; огню их знамена. Может быть, это и примитивный подход, но каждый день видеть пожары на своей территории – это деморализует похлеще, чем силовые методы воздействия.$B$BКак бы то ни было... хуже не будет!','Сожгите 10 знамен врайкулов по поручению герцога Ланкрала из Мрачного Свода.','У тебя еще много работы.','Вернитесь к герцогу Ланкралу в Мрачный Свод, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Психологическая атака',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нам удалось подорвать боевой дух врайкулов, $n, и надо бы продолжать в том же духе.$B$BЯ хочу, чтобы ты каждый день $gездил:ездила; в Йотунхейм и $gпредавал:предавала; огню их знамена. Может быть, это и примитивный подход, но каждый день видеть пожары на своей территории – это деморализует похлеще, чем силовые методы воздействия.$B$BКак бы то ни было... хуже не будет!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сожгите 10 знамен врайкулов по поручению герцога Ланкрала из Мрачного Свода.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У тебя еще много работы.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к герцогу Ланкралу в Мрачный Свод, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (13085,'Возвращение Вэлена','Я только видел, как этот глупец Вэлен Разоблаченный прокрался в склеп.$B$BТы уж позаботься, чтобы он осознал свои ошибки и вернул мне моих рыцарей смерти.','Поговорите с Вэленом Разоблаченным в Мрачном Своде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение Вэлена',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я только видел, как этот глупец Вэлен Разоблаченный прокрался в склеп.$B$BТы уж позаботься, чтобы он осознал свои ошибки и вернул мне моих рыцарей смерти.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Вэленом Разоблаченным в Мрачном Своде.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13086,'Последний рубеж','Я знаю, как укрепить оборону Оплота, |3-6($c)! На верхушке каждой из четырех башен находится откатная пушка Серебряного Авангарда, освященная самим отцом Густавом. Ты полетишь на одну из этих башен и с помощью пушки будешь уничтожать штурмующие Оплот силы Плети.$B$BНо помни: на осаду башен наверняка пошлют ледяных змеев. Их надо сбить прямо в воздухе! Если змеи разрушат стены и башни, нам конец.','Крики умирающих будут преследовать меня всегда! Помоги им!','Вернитесь к осадному мастеру Феззику в Оплот Серебряного Авангарда, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Последний рубеж',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я знаю, как укрепить оборону Оплота, |3-6($c)! На верхушке каждой из четырех башен находится откатная пушка Серебряного Авангарда, освященная самим отцом Густавом. Ты полетишь на одну из этих башен и с помощью пушки будешь уничтожать штурмующие Оплот силы Плети.$B$BНо помни: на осаду башен наверняка пошлют ледяных змеев. Их надо сбить прямо в воздухе! Если змеи разрушат стены и башни, нам конец.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Крики умирающих будут преследовать меня всегда! Помоги им!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к осадному мастеру Феззику в Оплот Серебряного Авангарда, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13087,'Кулинария севера','Ну и что ты тут $gзабыл:забыла;? Где мой обед? Я скоро с ГОЛОДУ сдохну! Принеси мне хотя бы охлажденного мяса, чтобы я сварил похлебку! Принесешь – дам тебе рецепт, будешь $gсам:сама; себе еду варить. БЫСТРЕЕ, НЕСИ МНЕ МЯСО!','Принесите четыре куска охлажденного мяса зверей Нордскола Брому Выпивастеру в Валгард.','Ура, мясо! Держи рецепт – а я займусь готовкой!','ГДЕ МОЕ МЯСО?!','Вернитесь к Брому Выпивастеру в Валгард, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кулинария севера',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну и что ты тут $gзабыл:забыла;? Где мой обед? Я скоро с ГОЛОДУ сдохну! Принеси мне хотя бы охлажденного мяса, чтобы я сварил похлебку! Принесешь – дам тебе рецепт, будешь $gсам:сама; себе еду варить. БЫСТРЕЕ, НЕСИ МНЕ МЯСО!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите четыре куска охлажденного мяса зверей Нордскола Брому Выпивастеру в Валгард.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ура, мясо! Держи рецепт – а я займусь готовкой!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','ГДЕ МОЕ МЯСО?!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Брому Выпивастеру в Валгард, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13088,'Кулинария севера','Как много новобранцев – и всех их надо хорошенько накормить! Если ты принесешь мне немного охлажденного мяса, я сделаю им мясную похлебку, а ты получишь рецепт.','Наконец-то мы накормим всех новобранцев! Держи, вот твой рецепт.','Эти парни хотят видеть мясо у себя в похлебке!','Вернитесь к Роллику Маккрилу в Крепость Отваги, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кулинария севера',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как много новобранцев – и всех их надо хорошенько накормить! Если ты принесешь мне немного охлажденного мяса, я сделаю им мясную похлебку, а ты получишь рецепт.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Наконец-то мы накормим всех новобранцев! Держи, вот твой рецепт.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Эти парни хотят видеть мясо у себя в похлебке!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Роллику Маккрилу в Крепость Отваги, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13089,'Кулинария севера','Что может быть лучше согревающей мясной похлебки? Принеси мне немного охлажденного мяса проклятых тварей, что бродят по этому краю, и я научу тебя, как делать мою похлебку.','Принесите четыре куска охлажденного мяса зверей Нордскола Томасу Количио в Лагерь Возмездия.','Сейчас мы быстренько превратим это мясо в похлебку...','Похлебка ждет тебя...','Вернитесь к Томасу Количио в Лагерь Возмездия, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кулинария севера',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что может быть лучше согревающей мясной похлебки? Принеси мне немного охлажденного мяса проклятых тварей, что бродят по этому краю, и я научу тебя, как делать мою похлебку.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите четыре куска охлажденного мяса зверей Нордскола Томасу Количио в Лагерь Возмездия.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сейчас мы быстренько превратим это мясо в похлебку...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Похлебка ждет тебя...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Томасу Количио в Лагерь Возмездия, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13090,'Кулинария севера','Воинам армии Песни Войны нужна горячая пища. Если ты принесешь мне немного охлажденного мяса люторогов и прочих зверей, я сделаю им мясную похлебку, а ты получишь рецепт.','Принесите четыре куска охлажденного мяса зверей Нордскола Орну Хрупкое Копыто в Крепость Песни Войны. Охлажденное мясо можно достать только убивая зверей, обитающих на континенте Нордскол.','Прими мою благодарность.','Будет мясо – будет и похлебка.','Вернитесь к Орну Хрупкому Копыту в Крепость Песни Войны, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кулинария севера',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Воинам армии Песни Войны нужна горячая пища. Если ты принесешь мне немного охлажденного мяса люторогов и прочих зверей, я сделаю им мясную похлебку, а ты получишь рецепт.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите четыре куска охлажденного мяса зверей Нордскола Орну Хрупкое Копыто в Крепость Песни Войны. Охлажденное мясо можно достать только убивая зверей, обитающих на континенте Нордскол.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прими мою благодарность.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Будет мясо – будет и похлебка.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Орну Хрупкому Копыту в Крепость Песни Войны, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13091,'Нелегко быть водным ужасом','Ворота шлюза за стенами моей пещеры так и кишат элементалями, которых врайкульским магам еще только предстоит укротить. Я научу тебя одной хитрости, которая позволит тебе ненадолго подчинять себе этих существ, и ты сможешь всерьез ударить по Йотунхейму.$B$B<Одержимая банши ведьма чертит что-то в воздухе и прикладывает вам ко лбу большой палец.>$B$BИди и открой ворота шлюза! Водный ужас выскочит оттуда и ты, завладев им, сможешь уничтожить всех врагов!','Никогда мне не доводилось видеть такого ужаса в глазах врайкула. Они и впрямь считают себя самыми сильными на свете.$B$BПридется нам показать им, как глубоко они ошибаются.','Гадание на костях показывает, что мое задание до сих пор не выполнено.','Вернитесь к костяной ведьме в деревню Ньорндар, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нелегко быть водным ужасом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ворота шлюза за стенами моей пещеры так и кишат элементалями, которых врайкульским магам еще только предстоит укротить. Я научу тебя одной хитрости, которая позволит тебе ненадолго подчинять себе этих существ, и ты сможешь всерьез ударить по Йотунхейму.$B$B<Одержимая банши ведьма чертит что-то в воздухе и прикладывает вам ко лбу большой палец.>$B$BИди и открой ворота шлюза! Водный ужас выскочит оттуда и ты, завладев им, сможешь уничтожить всех врагов!',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Никогда мне не доводилось видеть такого ужаса в глазах врайкула. Они и впрямь считают себя самыми сильными на свете.$B$BПридется нам показать им, как глубоко они ошибаются.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Гадание на костях показывает, что мое задание до сих пор не выполнено.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к костяной ведьме в деревню Ньорндар, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13092,'Гадание по костям','Завладев этим созданием, я получила доступ ко всей ее силе и знаниям. Это действительно очень удачно. Будучи костяной ведьмой и прорицательницей по рунам, она владеет искусством бросать кости и тем самым определять чью-то судьбу.$B$B<Костяная ведьма усмехается.>$B$BНам с тобой повезло, что я могу повлиять на ее предсказания своей властью.$B$BПринеси мне кости врайкулов, которых ты $gубил:убила; здесь в Йотунхейме, я их брошу и дам тебе шанс $gсамому:самой; определить свою собственную судьбу.','Принесите 15 костей врайкулов костяной ведьме в деревню Ньорндар.','Меня поражает, что эти создания когда-то имели еще и какую-то власть над миром. С такой примитивной магией!','Вернитесь к костяной ведьме в деревню Ньорндар, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гадание по костям',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Завладев этим созданием, я получила доступ ко всей ее силе и знаниям. Это действительно очень удачно. Будучи костяной ведьмой и прорицательницей по рунам, она владеет искусством бросать кости и тем самым определять чью-то судьбу.$B$B<Костяная ведьма усмехается.>$B$BНам с тобой повезло, что я могу повлиять на ее предсказания своей властью.$B$BПринеси мне кости врайкулов, которых ты $gубил:убила; здесь в Йотунхейме, я их брошу и дам тебе шанс $gсамому:самой; определить свою собственную судьбу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 15 костей врайкулов костяной ведьме в деревню Ньорндар.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Меня поражает, что эти создания когда-то имели еще и какую-то власть над миром. С такой примитивной магией!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к костяной ведьме в деревню Ньорндар, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13093,'Гадание по костям','Выбери свою судьбу, $N.','Принеси мне побольше костей врайкулов, и мы сделаем так, что судьба будет к тебе благосклонна.','Вернитесь к костяной ведьме в Ледяную Корону.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гадание по костям',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Выбери свою судьбу, $N.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Принеси мне побольше костей врайкулов, и мы сделаем так, что судьба будет к тебе благосклонна.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к костяной ведьме в Ледяную Корону.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13096,'Гал\'дара заплатит за все','Ты $gвидел:видела;?$b$bЯ в жизни не видел такого кошмара! Великий Акали убит у меня на глазах... Это было ужасно...$b$bЯ поклялся не лезть в это дело. Моя задача – наблюдать. Но всему есть предел! Гал\'дара не должен уйти безнаказанным! Он заплатит за все!$b$bИди в Гундрак и разыщи там Гал\'дара. Смерть Акали требует отмщения. И ты станешь орудием мести. Возвращайся ко мне, когда все будет сделано.','Ты это сделал?! Гал\'дара уничтожен? Негодяй получил по заслугам!\n\nВот, прими это в награду за свои старания.','Смерть Акали была отомщена, $R?','Вернитесь к Тол\'мару в Дубра\'джин, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гал\'дара заплатит за все',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gвидел:видела;?$b$bЯ в жизни не видел такого кошмара! Великий Акали убит у меня на глазах... Это было ужасно...$b$bЯ поклялся не лезть в это дело. Моя задача – наблюдать. Но всему есть предел! Гал\'дара не должен уйти безнаказанным! Он заплатит за все!$b$bИди в Гундрак и разыщи там Гал\'дара. Смерть Акали требует отмщения. И ты станешь орудием мести. Возвращайся ко мне, когда все будет сделано.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты это сделал?! Гал\'дара уничтожен? Негодяй получил по заслугам!\n\nВот, прими это в награду за свои старания.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Смерть Акали была отомщена, $R?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тол\'мару в Дубра\'джин, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (13097,'Неоконченное дело','Да, это правда: пророк Акали больше не потревожит этот мир, – однако нам предстоит еще многое сделать.$b$bБольшую часть крови Акали принял другой, и именно он представляет угрозу.$b$bВот что, $n, отправляйся в Дубра\'джин, что на севере от Гундрака, и поговори с Тол\'маром. Он подскажет, что делать дальше.','Поговорите с Тол\'маром в Дубра\'джине по просьбе Хар\'коа.','Слушай, дружище. Работенка тебе предстоит не из легких!','Мне бы хотелось тебе помочь, но я могу дать тебе только теплое напутствие и сердечную поддержку.\n\nНе торопись, подготовься, как следует, и выступай, когда будешь готов. Только прошу, не затягивай слишком долго, потому что иначе пророк сам нагрянет сюда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Неоконченное дело',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Да, это правда: пророк Акали больше не потревожит этот мир, – однако нам предстоит еще многое сделать.$b$bБольшую часть крови Акали принял другой, и именно он представляет угрозу.$b$bВот что, $n, отправляйся в Дубра\'джин, что на севере от Гундрака, и поговори с Тол\'маром. Он подскажет, что делать дальше.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Тол\'маром в Дубра\'джине по просьбе Хар\'коа.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Слушай, дружище. Работенка тебе предстоит не из легких!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мне бы хотелось тебе помочь, но я могу дать тебе только теплое напутствие и сердечную поддержку.\n\nНе торопись, подготовься, как следует, и выступай, когда будешь готов. Только прошу, не затягивай слишком долго, потому что иначе пророк сам нагрянет сюда.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13098,'Для наших потомков','Гундрак обречен.$b$bИстория повторяется у нас на глазах. Когда тролли выступают против своих же богов, конец известен. И он непременно настанет. Это лишь вопрос времени...$b$bНо если мы составим правдивую летопись всех событий, может быть, нам удастся предостеречь будущие поколения, чтобы они не пошли по тому же гибельному пути.$b$bЕсли тебе хватит смелости, отправляйся в Гундрак и разыщи исторические доказательства, которые дадут нам ответ на вопрос, что стало причиной падения империи Драккари.','Отправляйтесь в Гундрак и заберите оттуда 6 табличек с летописью Драккари по поручению летописца Ба\'Кини из Дубра\'джина.','<Ба\'Кини быстро просматривает таблички и вновь обращается к вам.>\n\nДа, это подлинники, |3-6($R). Помещу их в свою коллекцию, на подобающее им место.\n\nМожет, нам все-таки удастся вразумить если не современников, то хотя бы потомков.','Ты нашел таблички с летописью Драккари?','Вернитесь к летописцу Ба\'кини в Дубра\'джин, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Для наших потомков',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Гундрак обречен.$b$bИстория повторяется у нас на глазах. Когда тролли выступают против своих же богов, конец известен. И он непременно настанет. Это лишь вопрос времени...$b$bНо если мы составим правдивую летопись всех событий, может быть, нам удастся предостеречь будущие поколения, чтобы они не пошли по тому же гибельному пути.$b$bЕсли тебе хватит смелости, отправляйся в Гундрак и разыщи исторические доказательства, которые дадут нам ответ на вопрос, что стало причиной падения империи Драккари.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Гундрак и заберите оттуда 6 табличек с летописью Драккари по поручению летописца Ба\'Кини из Дубра\'джина.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Ба\'Кини быстро просматривает таблички и вновь обращается к вам.>\n\nДа, это подлинники, |3-6($R). Помещу их в свою коллекцию, на подобающее им место.\n\nМожет, нам все-таки удастся вразумить если не современников, то хотя бы потомков.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты нашел таблички с летописью Драккари?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к летописцу Ба\'кини в Дубра\'джин, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13099,'Просто проверка','Понимаешь, какое дело... со стороны Гундрака постоянно доносится какой-то зловещий грохот. В последнее время – все громче и чаще.$b$bОдна моя давняя ученица ведет наблюдения на посту, расположенном к западу от Гундрака. Может быть, найдешь время, заглянешь к ней и проверишь, все ли у нее в порядке?','Поговорите с Ба\'Кини в Дубра\'джине по просьбе То\'кини.','Давняя ученица? Ха!$B$BЕсли под долгим временем я подразумеваю всю мою жизнь, то я полагаю, это будет более точным высказыванием.$B$BТо\'кини был моим трусливым отцом - слишком боялся занять позицию так близко к Гундраку... поэтому он послал меня.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Просто проверка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Понимаешь, какое дело... со стороны Гундрака постоянно доносится какой-то зловещий грохот. В последнее время – все громче и чаще.$b$bОдна моя давняя ученица ведет наблюдения на посту, расположенном к западу от Гундрака. Может быть, найдешь время, заглянешь к ней и проверишь, все ли у нее в порядке?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Ба\'Кини в Дубра\'джине по просьбе То\'кини.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Давняя ученица? Ха!$B$BЕсли под долгим временем я подразумеваю всю мою жизнь, то я полагаю, это будет более точным высказыванием.$B$BТо\'кини был моим трусливым отцом - слишком боялся занять позицию так близко к Гундраку... поэтому он послал меня.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (13100,'Мясной рулет в странногрибном соусе','Запеките 4 странных гриба из Стоков Даларана и 2 куска охлажденного мяса в форме для мясного рулета и отнесите готовое блюдо Ортону Беннету в лавку "Диковины и редкости" на площадь Руноплета в Даларане.','Выглядит аппетитно! Спасибо!','Поговорите с Ортоном Беннетом в "Диковинах и редкостях", что в Даларане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мясной рулет в странногрибном соусе',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Запеките 4 странных гриба из Стоков Даларана и 2 куска охлажденного мяса в форме для мясного рулета и отнесите готовое блюдо Ортону Беннету в лавку "Диковины и редкости" на площадь Руноплета в Даларане.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Выглядит аппетитно! Спасибо!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Ортоном Беннетом в "Диковинах и редкостях", что в Даларане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13101,'Сбор в Приюте фокусника','Арилль Лазурный Взгляд из "Приюта фокусника" ожидает наплыва гостей, ему предстоит приготовить море угощений, чтобы хватило на всех, и очень быстро! $B$BПринеси-ка мне северной похлебки и кувшин с вином из сырной лавки "Еще по сто", она находится прямо в центре Даларана. Хозяин лавки как раз задолжал мне винишко. Оно должно быть где-то там, у него в магазине.$B$BОтнеси вино и мясо Ариллю.','Приготовьте 4 порции северной похлебки, возьмите кувшин с вином из сырной лавки в Даларане и отнесите все Ариллю Лазурному Взгляду в "Приют фокусника" на площади Руноплета.','О, да тут на всех с лихвой хватит! Думаю, гости будут довольны.','Где же еда? Я жду гостей! Они должны прибыть с минуты на минуту!','Поговорите с Ариллем Лазурным Взглядом в Приюте фокусника, что в Даларане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сбор в Приюте фокусника',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Арилль Лазурный Взгляд из "Приюта фокусника" ожидает наплыва гостей, ему предстоит приготовить море угощений, чтобы хватило на всех, и очень быстро! $B$BПринеси-ка мне северной похлебки и кувшин с вином из сырной лавки "Еще по сто", она находится прямо в центре Даларана. Хозяин лавки как раз задолжал мне винишко. Оно должно быть где-то там, у него в магазине.$B$BОтнеси вино и мясо Ариллю.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Приготовьте 4 порции северной похлебки, возьмите кувшин с вином из сырной лавки в Даларане и отнесите все Ариллю Лазурному Взгляду в "Приют фокусника" на площади Руноплета.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, да тут на всех с лихвой хватит! Думаю, гости будут довольны.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Где же еда? Я жду гостей! Они должны прибыть с минуты на минуту!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Ариллем Лазурным Взглядом в Приюте фокусника, что в Даларане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13102,'Рагу для завсегдатаев Стоков','Его съедят в две секунды! Большое спасибо!','Мои постояльцы голодны! Мне срочно нужно рагу.','Поговорите с Аджаем Грином в "Ведьме и вороне", что в Клоаке Даларана.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рагу для завсегдатаев Стоков',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Его съедят в две секунды! Большое спасибо!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мои постояльцы голодны! Мне срочно нужно рагу.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Аджаем Грином в "Ведьме и вороне", что в Клоаке Даларана.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (13104,'И снова в Пролом','Аванпост укреплен, и ему ничто не угрожает. Мы отбили Долину Эха и уничтожили стены из паутины, закрывавшие вход в Пролом. Пришло время двинуться на Плетхольм и закрепиться в Ледяной Короне. Линия фронта сдвигается!$B$BЯ попросил черного хранителя помочь нам со штурмом Плетхольма. Он много знает о Плети, и эти знания нам пригодятся.$B$BИди к нему. Ты найдешь его в палатке у входа в Пролом, к северо-западу отсюда.','Отправляйтесь в распоряжение черного хранителя в Долине Эха, рядом с Проломом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','И снова в Пролом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Аванпост укреплен, и ему ничто не угрожает. Мы отбили Долину Эха и уничтожили стены из паутины, закрывавшие вход в Пролом. Пришло время двинуться на Плетхольм и закрепиться в Ледяной Короне. Линия фронта сдвигается!$B$BЯ попросил черного хранителя помочь нам со штурмом Плетхольма. Он много знает о Плети, и эти знания нам пригодятся.$B$BИди к нему. Ты найдешь его в палатке у входа в Пролом, к северо-западу отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в распоряжение черного хранителя в Долине Эха, рядом с Проломом.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (13105,'И снова в Пролом','Аванпост укреплен, и ему ничто не угрожает. Мы отбили Долину Эха и уничтожили стены из паутины, закрывавшие вход в Пролом. Пришло время двинуться на Плетхольм и закрепиться в Ледяной Короне. Линия фронта сдвигается!$B$BЯ попросил черного хранителя помочь нам со штурмом Плетхольма. Он много знает о Плети, и эти знания нам пригодятся.$B$BИди к нему. Ты найдешь его в палатке у входа в Пролом, к северо-западу отсюда.','Поговорите с черным хранителем в Долине Эха у входа в Пролом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','И снова в Пролом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Аванпост укреплен, и ему ничто не угрожает. Мы отбили Долину Эха и уничтожили стены из паутины, закрывавшие вход в Пролом. Пришло время двинуться на Плетхольм и закрепиться в Ледяной Короне. Линия фронта сдвигается!$B$BЯ попросил черного хранителя помочь нам со штурмом Плетхольма. Он много знает о Плети, и эти знания нам пригодятся.$B$BИди к нему. Ты найдешь его в палатке у входа в Пролом, к северо-западу отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с черным хранителем в Долине Эха у входа в Пролом.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13106,'Черный дозор','На Мясопилке Плети создаются поганища и мясистые великаны. Если нам удастся закрыть Мясопилку, то Король-лич останется без значительной части армии.$B$BЯ послал туда темную всадницу Арли. Ее штаб, Черный дозор, расположен на горном хребте, к западу от Корп\'Ретара, прямо над Мясопилкой. Я слышал, что Серебряный Авангард собирается послать туда кого-то еще, но темная всадница точно знает, что делать. Найди Арли и помоги ей.','Поговорите с темной всадницей Арли в Черном дозоре, что в Ледяной Короне.','Хорошо. Я рада любой помощи. От Серебряного Авангарда приехал Олакин. Но меньше слов – больше дела. Надо оставить армию Плети без подкрепления.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Черный дозор',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На Мясопилке Плети создаются поганища и мясистые великаны. Если нам удастся закрыть Мясопилку, то Король-лич останется без значительной части армии.$B$BЯ послал туда темную всадницу Арли. Ее штаб, Черный дозор, расположен на горном хребте, к западу от Корп\'Ретара, прямо над Мясопилкой. Я слышал, что Серебряный Авангард собирается послать туда кого-то еще, но темная всадница точно знает, что делать. Найди Арли и помоги ей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с темной всадницей Арли в Черном дозоре, что в Ледяной Короне.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо. Я рада любой помощи. От Серебряного Авангарда приехал Олакин. Но меньше слов – больше дела. Надо оставить армию Плети без подкрепления.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (13107,'Сосиски с горчицей!','Верховный маг Пентарус любит смотреть битбол и сейчас собирается на матч, но ему нужно взять с собой что-нибудь перекусить.$B$BТебе нужно собрать ему корзинку для пикника. Положишь туда 4 сосиски из мяса люторога и 4 побега полевой горчицы, она растет прямо в городе, на зеленых участках.$B$BСобранную корзинку надо отдать верховному магу, чтобы у него было чем перекусить, пока он будет смотреть игру.','Заполните пустую корзинку для пикника. Положите туда 4 сосиски из мяса люторога, которые вы приготовите сами, и 4 побега полевой горчицы, которая растет на зеленых участках в черте Даларана.$B$BОтнесите корзинку для пикника верховному магу Пентарусу на площадку Краса в Даларане.','Замечательно! Надеюсь, "Даларанские крушители" сегодня вырвутся вперед!','Поговорите с верховным магом Пентарусом на Площадке Краса, что в Даларане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сосиски с горчицей!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Верховный маг Пентарус любит смотреть битбол и сейчас собирается на матч, но ему нужно взять с собой что-нибудь перекусить.$B$BТебе нужно собрать ему корзинку для пикника. Положишь туда 4 сосиски из мяса люторога и 4 побега полевой горчицы, она растет прямо в городе, на зеленых участках.$B$BСобранную корзинку надо отдать верховному магу, чтобы у него было чем перекусить, пока он будет смотреть игру.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заполните пустую корзинку для пикника. Положите туда 4 сосиски из мяса люторога, которые вы приготовите сами, и 4 побега полевой горчицы, которая растет на зеленых участках в черте Даларана.$B$BОтнесите корзинку для пикника верховному магу Пентарусу на площадку Краса в Даларане.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Замечательно! Надеюсь, "Даларанские крушители" сегодня вырвутся вперед!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с верховным магом Пентарусом на Площадке Краса, что в Даларане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13108,'Любой ценой!','Так или иначе, Локен падет.$b$bДаже если мне лично придется поотрывать ему руки и ноги, он заплатит сполна за свои отвратительные деяния.$b$bЕсли встретишь его раньше меня, честь и слава победителя Локена достанутся тебе.$b$bПринеси мне его лживый язык – и заслужишь мою благодарность и благословение.','Отправляйтесь в Чертоги Молний и убейте Локена. Потом возвращайтесь к королю Йоккуму в Дун Ниффелем и отдайте ему язык Локена.','Этот подлый червь мертв?\n\nТы принес великое благо моему народу, $R.\n\nПрими этот дар в награду за доблесть и верность.','Локен принял правосудие?','Вернитесь к Королю Йоккуму в Дун Ниффелем, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Любой ценой!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Так или иначе, Локен падет.$b$bДаже если мне лично придется поотрывать ему руки и ноги, он заплатит сполна за свои отвратительные деяния.$b$bЕсли встретишь его раньше меня, честь и слава победителя Локена достанутся тебе.$b$bПринеси мне его лживый язык – и заслужишь мою благодарность и благословение.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Чертоги Молний и убейте Локена. Потом возвращайтесь к королю Йоккуму в Дун Ниффелем и отдайте ему язык Локена.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Этот подлый червь мертв?\n\nТы принес великое благо моему народу, $R.\n\nПрими этот дар в награду за доблесть и верность.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Локен принял правосудие?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Королю Йоккуму в Дун Ниффелем, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13109,'Диаметральные противоположности','Я скажу прямо, $gмалыш:невеличка:r; |3-6($r). С тех пор, как у нас порвались узы дружбы с Торимом, что-то в нас изменилось... Мы уже не те, что прежде.$b$bКак вождь и правитель, я желаю лишь одного: чтобы мой народ не таил зла на Торима, чтобы их сердца исцелились, и наша дружба с Повелителем Бурь была восстановлена. Твоя победа над Фьорном стала первым шагом на этом пути. Теперь надо сделать следующий шаг...И ты вновь нам поможешь.$b$bВолхан из Чертогов Молний – это враг посильнее Фьорна. И он намного опаснее, потому что он не успокоится, пока не уничтожит нас – или пока не погибнет сам.','Отправляйтесь в Чертоги Молний и убейте Волхана по поручению короля Йоккума из Дун Ниффелема.','Волхан больше не будет тревожить сон моего народа.\n\nПродолжай в том же духе, малыш $R. Со временем, я уверен, мой народ сумеет простить Торима.','Волхан потушен, маленький $R?','Вернитесь к Королю Йоккуму в Дун Ниффелем, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Диаметральные противоположности',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я скажу прямо, $gмалыш:невеличка:r; |3-6($r). С тех пор, как у нас порвались узы дружбы с Торимом, что-то в нас изменилось... Мы уже не те, что прежде.$b$bКак вождь и правитель, я желаю лишь одного: чтобы мой народ не таил зла на Торима, чтобы их сердца исцелились, и наша дружба с Повелителем Бурь была восстановлена. Твоя победа над Фьорном стала первым шагом на этом пути. Теперь надо сделать следующий шаг...И ты вновь нам поможешь.$b$bВолхан из Чертогов Молний – это враг посильнее Фьорна. И он намного опаснее, потому что он не успокоится, пока не уничтожит нас – или пока не погибнет сам.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Чертоги Молний и убейте Волхана по поручению короля Йоккума из Дун Ниффелема.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Волхан больше не будет тревожить сон моего народа.\n\nПродолжай в том же духе, малыш $R. Со временем, я уверен, мой народ сумеет простить Торима.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Волхан потушен, маленький $R?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Королю Йоккуму в Дун Ниффелем, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13110,'Неупокоенные','Далеко не все наши солдаты вернулись из Плетхольма. Многие были убиты и после смерти превращены в чудовищные подобия самих себя. Так поступает Плеть. Души этих бойцов не могут обрести покой. Мы должны помочь им.$B$BОтправляйся через Пролом в Плетхольм и уничтожь оживленных рыцарей. Окропи кости этой святой водой, и их души наконец обретут покой.','По поручению отца Густава из Долины Эха в Ледяной Короне окропите кости 10 оживленных рыцарей святой водой, чтобы освободить наконец их неупокоенные души.','Это мрачная задача, $N, но она должна быть сделана.','Вернитесь к отцу Густаву в Долину Эха, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Неупокоенные',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Далеко не все наши солдаты вернулись из Плетхольма. Многие были убиты и после смерти превращены в чудовищные подобия самих себя. Так поступает Плеть. Души этих бойцов не могут обрести покой. Мы должны помочь им.$B$BОтправляйся через Пролом в Плетхольм и уничтожь оживленных рыцарей. Окропи кости этой святой водой, и их души наконец обретут покой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По поручению отца Густава из Долины Эха в Ледяной Короне окропите кости 10 оживленных рыцарей святой водой, чтобы освободить наконец их неупокоенные души.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Это мрачная задача, $N, но она должна быть сделана.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к отцу Густаву в Долину Эха, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13111,'Единственный в своем роде','Слушай сюда.$b$bНа первый взгляд, вроде обычная история: тролли выпустили в мир запретные силы, уничтожив своих же богов, которым должны поклоняться.$b$bТак-то оно так, но эти драккари – случай особый. Если все, что я слышала, правда, то в Гундраке сооружают какого-то особенного голема – говорят, что таких еще не было!$b$bТы же $gискал:искала; приключений, да? Вот и давай отправляйся в Гундрак и принеси мне кусок этого самого голема – на предмет изучения.','Отправляйтесь в Гундрак, добудьте обломок колосса Драккари и отнесите его летописцу Ба\'Кини в Дубра\'джин.','Да, это именно то, что нужно!\n\nВот, это тебе – награда за труды.','Ты принес то, о чем я тебя просила?','Вернитесь к летописцу Ба\'кини в Дубра\'джин, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Единственный в своем роде',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слушай сюда.$b$bНа первый взгляд, вроде обычная история: тролли выпустили в мир запретные силы, уничтожив своих же богов, которым должны поклоняться.$b$bТак-то оно так, но эти драккари – случай особый. Если все, что я слышала, правда, то в Гундраке сооружают какого-то особенного голема – говорят, что таких еще не было!$b$bТы же $gискал:искала; приключений, да? Вот и давай отправляйся в Гундрак и принеси мне кусок этого самого голема – на предмет изучения.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Гундрак, добудьте обломок колосса Драккари и отнесите его летописцу Ба\'Кини в Дубра\'джин.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, это именно то, что нужно!\n\nВот, это тебе – награда за труды.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты принес то, о чем я тебя просила?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к летописцу Ба\'кини в Дубра\'джин, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (13112,'Мясной рулет в странногрибном соусе','Сварите 4 странных гриба из Стоков Даларана и 2 куска охлажденного мяса, чтобы получить мясной рулет, и отнесите готовое блюдо Ортону Беннету в лавку "Диковины и редкости" на площадь Руноплета в Даларане.','Это мясо от Авило? А ты можешь поклясться, что там нет гномов?','Поговорите с Ортоном Беннетом в "Диковинах и редкостях", что в Даларане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мясной рулет в странногрибном соусе',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сварите 4 странных гриба из Стоков Даларана и 2 куска охлажденного мяса, чтобы получить мясной рулет, и отнесите готовое блюдо Ортону Беннету в лавку "Диковины и редкости" на площадь Руноплета в Даларане.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это мясо от Авило? А ты можешь поклясться, что там нет гномов?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Ортоном Беннетом в "Диковинах и редкостях", что в Даларане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (13113,'Сбор в Приюте фокусника','Прикинь: в Орде приняли закон, запрещающий каннибализм... это кто же такое придумал, хотелось бы знать! И как мне теперь выполнять все заказы?! Это ж я так разорюсь... Впрочем, давай сразу к делу.$B$BАрилль Лазурный Взгляд в "Приюте фокусника" скоро принимает у себя гостей. Им надо обеспечить кормежку. Короче, иди в сырную лавку в центре Даларана и возьми там кувшин с вином. И еще ему нужна северная похлебка.$B$BШевелись, Арилль ждет!','Приготовьте 4 порции северной похлебки, возьмите кувшин с вином из сырной лавки в Даларане и отнесите все Ариллю Лазурному Взгляду в "Приют фокусника" на площади Руноплета.','Думаю, гости будут довольны. Только не говори им, что я заказывал еду у Авило.','Поговорите с Ариллем Лазурным Взглядом в Приюте фокусника, что в Даларане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сбор в Приюте фокусника',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прикинь: в Орде приняли закон, запрещающий каннибализм... это кто же такое придумал, хотелось бы знать! И как мне теперь выполнять все заказы?! Это ж я так разорюсь... Впрочем, давай сразу к делу.$B$BАрилль Лазурный Взгляд в "Приюте фокусника" скоро принимает у себя гостей. Им надо обеспечить кормежку. Короче, иди в сырную лавку в центре Даларана и возьми там кувшин с вином. И еще ему нужна северная похлебка.$B$BШевелись, Арилль ждет!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Приготовьте 4 порции северной похлебки, возьмите кувшин с вином из сырной лавки в Даларане и отнесите все Ариллю Лазурному Взгляду в "Приют фокусника" на площади Руноплета.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Думаю, гости будут довольны. Только не говори им, что я заказывал еду у Авило.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Ариллем Лазурным Взглядом в Приюте фокусника, что в Даларане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13114,'Рагу для завсегдатаев Стоков','С виду вроде бы аппетитно. Спасибо за помощь.','Только чтобы на этот раз в рагу не было никаких гномов!','Поговорите с Аджаем Грином в "Ведьме и вороне", что в Клоаке Даларана.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рагу для завсегдатаев Стоков',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','С виду вроде бы аппетитно. Спасибо за помощь.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Только чтобы на этот раз в рагу не было никаких гномов!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Аджаем Грином в "Ведьме и вороне", что в Клоаке Даларана.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13116,'Сосиски с горчицей!','Верховный маг Пентарус обожает смотреть свой дурацкий битбол, закусывая в это время чем-нибудь вкусненьким.$B$BТебе нужно собрать ему корзинку для пикника. Положишь туда 4 сосиски из мяса люторога и 4 побега полевой горчицы, она растет прямо в городе, на зеленых участках.$B$BВ общем, обеспечь верховного мага сосисками с горчицей.','Заполните пустую корзинку для пикника. Положите туда 4 сосиски из мяса люторога, которые вы приготовите сами, и 4 побега полевой горчицы, которая растет на зеленых участках в черте Даларана.$B$BОтнесите корзинку для пикника верховному магу Пентарусу на площадку Краса в Даларане.','Замечательно! Надеюсь, "Даларанские крушители" сегодня вырвутся вперед!','Только смотри, чтобы сосиски были на 100% из люторожьего мяса, без всяких там добавочных субпродуктов типа гномов!','Поговорите с верховным магом Пентарусом на Площадке Краса, что в Даларане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сосиски с горчицей!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Верховный маг Пентарус обожает смотреть свой дурацкий битбол, закусывая в это время чем-нибудь вкусненьким.$B$BТебе нужно собрать ему корзинку для пикника. Положишь туда 4 сосиски из мяса люторога и 4 побега полевой горчицы, она растет прямо в городе, на зеленых участках.$B$BВ общем, обеспечь верховного мага сосисками с горчицей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заполните пустую корзинку для пикника. Положите туда 4 сосиски из мяса люторога, которые вы приготовите сами, и 4 побега полевой горчицы, которая растет на зеленых участках в черте Даларана.$B$BОтнесите корзинку для пикника верховному магу Пентарусу на площадку Краса в Даларане.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Замечательно! Надеюсь, "Даларанские крушители" сегодня вырвутся вперед!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Только смотри, чтобы сосиски были на 100% из люторожьего мяса, без всяких там добавочных субпродуктов типа гномов!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с верховным магом Пентарусом на Площадке Краса, что в Даларане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13117,'Откуда они берутся?','Слуги Короля-лича не знают усталости. Они трудятся день и ночь: собирают поганищ и мясных великанов в лабораториях в Мясопилке. Они создают их десятками! $B$BНо им этого мало. К ним туда постоянно прибывают скелетные создания, чтобы ускорить темп работ.$B$BЕсли мы не узнаем, откуда они появляются, и как они умудряются работать так быстро, они сотворят столько чудовищ, что те просто задавят нас числом. Отправляйся на юго-восток и попробуй узнать, откуда берутся эти скелеты.','Проведите разведку у алтаря призыва в восточной части Мясопилки и возвращайтесь с докладом к темной всаднице Арли, которая ждет вас в Черном дозоре.','Ты $Gузнал:узнала; откуда берутся эти скелеты?','Вернитесь к темной всаднице Арли в Черный дозор, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Откуда они берутся?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слуги Короля-лича не знают усталости. Они трудятся день и ночь: собирают поганищ и мясных великанов в лабораториях в Мясопилке. Они создают их десятками! $B$BНо им этого мало. К ним туда постоянно прибывают скелетные создания, чтобы ускорить темп работ.$B$BЕсли мы не узнаем, откуда они появляются, и как они умудряются работать так быстро, они сотворят столько чудовищ, что те просто задавят нас числом. Отправляйся на юго-восток и попробуй узнать, откуда берутся эти скелеты.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проведите разведку у алтаря призыва в восточной части Мясопилки и возвращайтесь с докладом к темной всаднице Арли, которая ждет вас в Черном дозоре.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gузнал:узнала; откуда берутся эти скелеты?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к темной всаднице Арли в Черный дозор, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13118,'Очищение Плетхольма','Силы Плети, отправленные на штурм Оплота Серебряного Авангарда, были отброшены. Теперь они, что называется, рвут и мечут. Все узники, находящиеся в Плетхольме, будут казнены и после смерти превращены в слуг Короля-лича.$B$BСеребряный Авангард наверняка обратится к тебе с просьбой достойно проводить этих бойцов. Я же не могу просить тебя об этом. Если мы хотим победить, то должны уничтожить Плеть на корню.$B$BОтправляйся через Пролом на северо-запад, в Плетхольм, уничтожая всех и вся на своем пути.','По заданию черного хранителя из Долины Эха в Ледяной Короне уничтожьте 3 верховных жрецов Забытых глубин, 3 королей Забытых глубин и 8 оживленных рыцарей.','Не трать время, $N.','Вернитесь к черному хранителю в Долину Эха, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Очищение Плетхольма',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Силы Плети, отправленные на штурм Оплота Серебряного Авангарда, были отброшены. Теперь они, что называется, рвут и мечут. Все узники, находящиеся в Плетхольме, будут казнены и после смерти превращены в слуг Короля-лича.$B$BСеребряный Авангард наверняка обратится к тебе с просьбой достойно проводить этих бойцов. Я же не могу просить тебя об этом. Если мы хотим победить, то должны уничтожить Плеть на корню.$B$BОтправляйся через Пролом на северо-запад, в Плетхольм, уничтожая всех и вся на своем пути.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По заданию черного хранителя из Долины Эха в Ледяной Короне уничтожьте 3 верховных жрецов Забытых глубин, 3 королей Забытых глубин и 8 оживленных рыцарей.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Не трать время, $N.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к черному хранителю в Долину Эха, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13119,'Разрушение алтарей','Значит, у этих алтарей они вызывают своих рабочих и воинов?$B$BИми мы и займемся в первую очередь. У мастера призыва должен быть посох для активации портала. Если убить главного призывателя и забрать его посох, с его помощью можно устроить перегрузку портала Призыва и разрушить соответствующий алтарь.$B$BУничтожь все четыре алтаря, и когда все будет сделано, возвращайся ко мне.','Убейте главного призывателя Зарода и используйте его посох призыва, чтобы уничтожить первый, второй, третий и четвертый алтари призыва. Когда все будет сделано, возвращайтесь к темной всаднице Арли в Черный дозор.','Тебе удалось уничтожить алтари призыва?','Вернитесь к темной всаднице Арли в Черный дозор, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разрушение алтарей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Значит, у этих алтарей они вызывают своих рабочих и воинов?$B$BИми мы и займемся в первую очередь. У мастера призыва должен быть посох для активации портала. Если убить главного призывателя и забрать его посох, с его помощью можно устроить перегрузку портала Призыва и разрушить соответствующий алтарь.$B$BУничтожь все четыре алтаря, и когда все будет сделано, возвращайся ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте главного призывателя Зарода и используйте его посох призыва, чтобы уничтожить первый, второй, третий и четвертый алтари призыва. Когда все будет сделано, возвращайтесь к темной всаднице Арли в Черный дозор.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось уничтожить алтари призыва?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к темной всаднице Арли в Черный дозор, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13120,'Взгляд смерти','Мясопилка – это крупномасштабный проект, и нам будет трудно уследить за всем, что у них происходит. Но у меня есть план.$B$B<Из складок плаща Арли достает шар и показывает его вам.>$B$BЭто сфера взгляда смерти. С ее помощью мы можем следить за действиями Плети, чтобы знать, где лучше нанести удар.$B$BРазмести такие сферы у трех наиболее важных объектов: у лаборатории поганищ и лаборатории мясистых великанов на юго-западе, а также рядом с огромным зеленым котлом далеко на западе.','Разместите сферу взгляда смерти на стойке у лаборатории поганищ, стойке у лаборатории мясистых великанов и стойке в окрестностях котла. Когда все будет готово, возвращайтесь к темной всаднице Арли в Черный дозор.','Ты $Gразместил:разместила; сферы?','Вернитесь к темной всаднице Арли в Черный дозор, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Взгляд смерти',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мясопилка – это крупномасштабный проект, и нам будет трудно уследить за всем, что у них происходит. Но у меня есть план.$B$B<Из складок плаща Арли достает шар и показывает его вам.>$B$BЭто сфера взгляда смерти. С ее помощью мы можем следить за действиями Плети, чтобы знать, где лучше нанести удар.$B$BРазмести такие сферы у трех наиболее важных объектов: у лаборатории поганищ и лаборатории мясистых великанов на юго-западе, а также рядом с огромным зеленым котлом далеко на западе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разместите сферу взгляда смерти на стойке у лаборатории поганищ, стойке у лаборатории мясистых великанов и стойке в окрестностях котла. Когда все будет готово, возвращайтесь к темной всаднице Арли в Черный дозор.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gразместил:разместила; сферы?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к темной всаднице Арли в Черный дозор, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13121,'Чужими глазами','Если мы хотим победить, то должны ударить по Королю-личу его же оружием.$B$BНа горе, находящейся к юго-западу отсюда, стоит крепость Кул\'галар. В ней живут йотунхеймские оракулы, которые подчиняются своему хозяину и следят за всеми с помощью Ока Короля-лича.$B$BВот это-то Око тебе и надо добыть. Увидеть, что происходит в цитадели Ледяной Короны, с его помощью не удастся, зато мы сможем узнать что-то важное о нашем противнике, чтобы затем принять верное решение.','По просьбе костяной ведьмы из деревни Ньорндар добудьте информацию о противнике с помощью Ока Короля-лича.','Отлично! Слухи не врут: Искальдер – действительно лучший воин-врайкул из всех когда-либо живших. Сама Вардмадра собирается его судить!$B$BДавай поторопимся, пока они не добрались до древнего героя первыми.','Тебе не удалось ничего узнать?! Так-то ты благодаришь меня за помощь тебе и рыцарям Черного Клинка?$B$BИди и без нужных мне сведений не возвращайся!','Вернитесь к костяной ведьме в деревню Ньорндар, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чужими глазами',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если мы хотим победить, то должны ударить по Королю-личу его же оружием.$B$BНа горе, находящейся к юго-западу отсюда, стоит крепость Кул\'галар. В ней живут йотунхеймские оракулы, которые подчиняются своему хозяину и следят за всеми с помощью Ока Короля-лича.$B$BВот это-то Око тебе и надо добыть. Увидеть, что происходит в цитадели Ледяной Короны, с его помощью не удастся, зато мы сможем узнать что-то важное о нашем противнике, чтобы затем принять верное решение.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По просьбе костяной ведьмы из деревни Ньорндар добудьте информацию о противнике с помощью Ока Короля-лича.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! Слухи не врут: Искальдер – действительно лучший воин-врайкул из всех когда-либо живших. Сама Вардмадра собирается его судить!$B$BДавай поторопимся, пока они не добрались до древнего героя первыми.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе не удалось ничего узнать?! Так-то ты благодаришь меня за помощь тебе и рыцарям Черного Клинка?$B$BИди и без нужных мне сведений не возвращайся!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к костяной ведьме в деревню Ньорндар, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13122,'Камень Плети','Камень Плети дается каждому солдату Плети при рождении или после создания. Он дает им дополнительную силу, а их правителями – возможность наблюдать за тем, где находится и что делает каждый из солдат.$B$BЕсли у меня будет достаточное количество таких камней, то, возможно, я смогу отслеживать перемещение сил Плети внутри Ледяной Короны.$B$BУничтожая воинов Плети в Плетхольме, не забывай забирать у них камни. Когда их наберется достаточно, возвращайся ко мне.','Принесите черному хранителю из Долины Эха в Ледяной Короне 15 камней Плети.','Так, давай-ка посмотрим, что можно сделать с этими камнями.','Камни Плети помогут нам отслеживать перемещения сил противника.','Вернитесь к черному хранителю в Долину Эха, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Камень Плети',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Камень Плети дается каждому солдату Плети при рождении или после создания. Он дает им дополнительную силу, а их правителями – возможность наблюдать за тем, где находится и что делает каждый из солдат.$B$BЕсли у меня будет достаточное количество таких камней, то, возможно, я смогу отслеживать перемещение сил Плети внутри Ледяной Короны.$B$BУничтожая воинов Плети в Плетхольме, не забывай забирать у них камни. Когда их наберется достаточно, возвращайся ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите черному хранителю из Долины Эха в Ледяной Короне 15 камней Плети.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так, давай-ка посмотрим, что можно сделать с этими камнями.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Камни Плети помогут нам отслеживать перемещения сил противника.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к черному хранителю в Долину Эха, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (13123,'WotLK Collector\'s Edition: - DEM - E - FLAG') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','WotLK Collector\'s Edition: - DEM - E - FLAG',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13125,'Чистое небо','Если мы хотим освободить эти земли от сил Плети, надо уничтожить хозяев Плетхольма.$B$BСалнаракс Резчик Плоти руководит храмом на первом ярусе Плетхольма. Неподалеку от него, в башне духов на втором ярусе, располагается верховный жрец Ят\'амон. А король подземелий Талонокс находится в Яме чудовищ, это на верхней дороге.$B$BВсе трое очень опасны. Будь $gосторожен:осторожна; и, если понадобится помощь, труби в этот рог. Рыцари смерти Акеруса не оставят тебя в беде.','По заданию черного хранителя из Долины Эха в Ледяной Короне убейте Салнаракса Резчика, короля подземелий Талонокса и верховного жреца Ят\'амона.','Покончи с ними, $N!','Вернитесь к черному хранителю в Долину Эха, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чистое небо',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если мы хотим освободить эти земли от сил Плети, надо уничтожить хозяев Плетхольма.$B$BСалнаракс Резчик Плоти руководит храмом на первом ярусе Плетхольма. Неподалеку от него, в башне духов на втором ярусе, располагается верховный жрец Ят\'амон. А король подземелий Талонокс находится в Яме чудовищ, это на верхней дороге.$B$BВсе трое очень опасны. Будь $gосторожен:осторожна; и, если понадобится помощь, труби в этот рог. Рыцари смерти Акеруса не оставят тебя в беде.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По заданию черного хранителя из Долины Эха в Ледяной Короне убейте Салнаракса Резчика, короля подземелий Талонокса и верховного жреца Ят\'амона.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Покончи с ними, $N!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к черному хранителю в Долину Эха, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13130,'Первый камень','Сейчас Плетхольм – мерзкая яма, кишащая порождениями мрака. Но однажды он станет славной и гордой твердыней. Верховный лорд Фордринг сказал, что назовет ее "Крепость Справедливости".$B$BУвы, строительство даже такой великолепной крепости, как цитадель Ледяной Короны, пришлось начинать когда-то с одного-единственного камня. Вот и нам нужен такой камень.$B$BОтправляйся в лес Хрустальной Песни, который лежит к югу отсюда. На востоке этого леса найди Дикую чащу. В ней собери с земли хрустальную древесину, а в руинах Шандарала найди старую эльфийскую кладку.','По заданию архитектора ордена Силаса из Долины Эха добудьте 10 бревен хрустальной древесины и 10 обломков древней эльфийской кладки.','Вернитесь к архитектору ордена Силас в Долину Эха, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Первый камень',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сейчас Плетхольм – мерзкая яма, кишащая порождениями мрака. Но однажды он станет славной и гордой твердыней. Верховный лорд Фордринг сказал, что назовет ее "Крепость Справедливости".$B$BУвы, строительство даже такой великолепной крепости, как цитадель Ледяной Короны, пришлось начинать когда-то с одного-единственного камня. Вот и нам нужен такой камень.$B$BОтправляйся в лес Хрустальной Песни, который лежит к югу отсюда. На востоке этого леса найди Дикую чащу. В ней собери с земли хрустальную древесину, а в руинах Шандарала найди старую эльфийскую кладку.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По заданию архитектора ордена Силаса из Долины Эха добудьте 10 бревен хрустальной древесины и 10 обломков древней эльфийской кладки.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к архитектору ордена Силас в Долину Эха, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13133,'Поиски древнего героя','$n, немедленно отправляйся на юго-запад, в Залы Предков!$B$BТам ты найдешь спящих мьординов. Разбуди их и разыщи Искальдера. Потом используй этот амулет и приведи Искальдера ко мне.$B$BСтупай прямо сейчас. Нельзя терять ни минуты!','Приведите Искальдера к костяной ведьме в деревню Ньорндар.','Вернитесь к костяной ведьме в деревню Ньорндар, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поиски древнего героя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, немедленно отправляйся на юго-запад, в Залы Предков!$B$BТам ты найдешь спящих мьординов. Разбуди их и разыщи Искальдера. Потом используй этот амулет и приведи Искальдера ко мне.$B$BСтупай прямо сейчас. Нельзя терять ни минуты!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Приведите Искальдера к костяной ведьме в деревню Ньорндар.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к костяной ведьме в деревню Ньорндар, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13134,'Пролитая кровь','Плеть не может создавать своих мясистых чудовищ без крови и бальзамирующей жидкости, которая консервирует части тел и дает им возможность функционировать. Если лишить их этого сырья, армия Плети скоро начнет разваливаться на части – в буквальном смысле слова, – и мы с легкостью уничтожим их поганые творения.$B$BВ лабораториях, где они создают своих мясистых великанов и поганищ, ты найдешь чаны с бальзамирующей жидкостью и громадные шары, заполненные кровью. Уничтожь их, а если кто-то попытается тебе помешать – убей его на месте!','Уничтожьте 5 чанов с бальзамировочным составом и 5 кровавых сфер по просьбе темной всадницы Арли из Черного дозора.','Все сделано, как я просила?','Вернитесь к темной всаднице Арли в Черный дозор, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пролитая кровь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Плеть не может создавать своих мясистых чудовищ без крови и бальзамирующей жидкости, которая консервирует части тел и дает им возможность функционировать. Если лишить их этого сырья, армия Плети скоро начнет разваливаться на части – в буквальном смысле слова, – и мы с легкостью уничтожим их поганые творения.$B$BВ лабораториях, где они создают своих мясистых великанов и поганищ, ты найдешь чаны с бальзамирующей жидкостью и громадные шары, заполненные кровью. Уничтожь их, а если кто-то попытается тебе помешать – убей его на месте!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 5 чанов с бальзамировочным составом и 5 кровавых сфер по просьбе темной всадницы Арли из Черного дозора.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Все сделано, как я просила?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к темной всаднице Арли в Черный дозор, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (13135,'Кристаллы энергии','На юго-востоке отсюда, на восточных окраинах леса Хрустальной Песни, есть место, известное как Дикая чаща. В этой чаще живут самые разные существа, непохожие друг на друга. Но у них есть одно общее свойство: они все обладают магической энергией. В каждом из них заключен кристаллический источник чистой энергии. Ее там столько, что, если она по какой-то причине дестабилизируется, может произойти такой мощный выброс, что мы все погибнем!$B$BОтправляйся в Дикую чащу, убей нескольких тамошних обитателей и забери у них кристаллы энергии. Нам нужно топливо, а им нужно умереть. Это называется "взаимовыгодный обмен".','Принесите 8 источников кристаллизованной энергии инженеру ордена Шпицпатрику в Долину Эха в Ледяной Короне.','Замечательно. Теперь мы быстро раскочегарим наш бомбардировщик!','Вернитесь к инженеру ордена Шпицпатрику в Долину Эха, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кристаллы энергии',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На юго-востоке отсюда, на восточных окраинах леса Хрустальной Песни, есть место, известное как Дикая чаща. В этой чаще живут самые разные существа, непохожие друг на друга. Но у них есть одно общее свойство: они все обладают магической энергией. В каждом из них заключен кристаллический источник чистой энергии. Ее там столько, что, если она по какой-то причине дестабилизируется, может произойти такой мощный выброс, что мы все погибнем!$B$BОтправляйся в Дикую чащу, убей нескольких тамошних обитателей и забери у них кристаллы энергии. Нам нужно топливо, а им нужно умереть. Это называется "взаимовыгодный обмен".',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 8 источников кристаллизованной энергии инженеру ордена Шпицпатрику в Долину Эха в Ледяной Короне.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Замечательно. Теперь мы быстро раскочегарим наш бомбардировщик!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к инженеру ордена Шпицпатрику в Долину Эха, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13136,'Зазубренные осколки','Вы вынимаете из тела вурдалака обломок какого-то темного ломкого металла. Обломок по краям зазубренный и неровный, что дает основания предположить, что либо его выковал неумелый мастеровой, либо это кусок, отломившийся от какого-то большого клинка.$B$BВы вспоминаете, что вы извлекали похожие куски из тел других вурдалаков в Мясопилке, – и задаетесь вопросом, зачем создатели этих тварей помещают в них куски металла. Может быть, рыцарь Олакин Сайнрит сумеет ответить на этот вопрос, если вы принесете ему еще несколько похожих железяк.','Принесите 10 зазубренных осколков рыцарю Олакину Сайнриту в Черный дозор.','Это что за мерзость?','Вернитесь к рыцарю Олакину Сайнриту в Черный дозор, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зазубренные осколки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы вынимаете из тела вурдалака обломок какого-то темного ломкого металла. Обломок по краям зазубренный и неровный, что дает основания предположить, что либо его выковал неумелый мастеровой, либо это кусок, отломившийся от какого-то большого клинка.$B$BВы вспоминаете, что вы извлекали похожие куски из тел других вурдалаков в Мясопилке, – и задаетесь вопросом, зачем создатели этих тварей помещают в них куски металла. Может быть, рыцарь Олакин Сайнрит сумеет ответить на этот вопрос, если вы принесете ему еще несколько похожих железяк.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 зазубренных осколков рыцарю Олакину Сайнриту в Черный дозор.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Это что за мерзость?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к рыцарю Олакину Сайнриту в Черный дозор, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13137,'Не совсем честный бой','Одержите победу над Искальдером на вершине Боевого Шрама по поручению костяной ведьмы из деревни Ньорндар.','Я спрятала Вардмадру в надежном месте. Пусть подождет в безопасности, пока мы готовим окончательное отмщение!','Тебе все еще нужно победить древнего героя!','Вернитесь к костяной ведьме в деревню Ньорндар, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Не совсем честный бой',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Одержите победу над Искальдером на вершине Боевого Шрама по поручению костяной ведьмы из деревни Ньорндар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я спрятала Вардмадру в надежном месте. Пусть подождет в безопасности, пока мы готовим окончательное отмщение!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе все еще нужно победить древнего героя!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к костяной ведьме в деревню Ньорндар, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13138,'Непонятный металл','Переплавьте мешок зазубренных осколков в одной из кузней Маликрисса. Потом возвращайтесь в Черный дозор и отдайте выплавленный слиток металла рыцарю Олакину Сайнриту.','У тебя получилось расплавить куски металла?','Вернитесь к рыцарю Олакину Сайнриту в Черный дозор, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Непонятный металл',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Переплавьте мешок зазубренных осколков в одной из кузней Маликрисса. Потом возвращайтесь в Черный дозор и отдайте выплавленный слиток металла рыцарю Олакину Сайнриту.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У тебя получилось расплавить куски металла?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к рыцарю Олакину Сайнриту в Черный дозор, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13139,'Ледяное сердце Нордскола','Сайлас и Шпицпатрик ушли добывать материалы и топливо, необходимые для того, чтобы начать строительство Крепости Справедливости. Благодаря тебе и рыцарям Черного Клинка, численность приспешников Плети в Плетхольме существенно сократилась, и все их лейтенанты убиты.$B$BЯ уже выбрал место, где мы приступим к работам, но сначала ты $gдолжен:должна; доставить мое донесение верховному лорду Тириону Фордрингу. Мы отправимся в Ледяную Корону по его приказу.','Доставьте донесение отца Густава верховному лорду Тириону Фордрингу в Оплот Серебряного Авангарда в Ледяной Короне.','Вернитесь к верховному лорду Тириону Фордрингу в Оплот Серебряного Авангарда, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ледяное сердце Нордскола',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сайлас и Шпицпатрик ушли добывать материалы и топливо, необходимые для того, чтобы начать строительство Крепости Справедливости. Благодаря тебе и рыцарям Черного Клинка, численность приспешников Плети в Плетхольме существенно сократилась, и все их лейтенанты убиты.$B$BЯ уже выбрал место, где мы приступим к работам, но сначала ты $gдолжен:должна; доставить мое донесение верховному лорду Тириону Фордрингу. Мы отправимся в Ледяную Корону по его приказу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте донесение отца Густава верховному лорду Тириону Фордрингу в Оплот Серебряного Авангарда в Ледяной Короне.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному лорду Тириону Фордрингу в Оплот Серебряного Авангарда, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13140,'Руноковы Маликрисса','Принесите рыцарю Олакину из Черного дозора 5 рунических саронитовых пластин.','Пластины практически идеально совпадают с найденными осколками. Должно быть, они используют их, чтобы получать еще более сильных вурдалаков. Плеть пойдет на все ради победы. И это еще один повод поскорее уничтожить это отвратительное место!','Тебе удалось добыть саронитовые пластины?','Вернитесь к рыцарю Олакину Сайнриту в Черный дозор, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Руноковы Маликрисса',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите рыцарю Олакину из Черного дозора 5 рунических саронитовых пластин.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Пластины практически идеально совпадают с найденными осколками. Должно быть, они используют их, чтобы получать еще более сильных вурдалаков. Плеть пойдет на все ради победы. И это еще один повод поскорее уничтожить это отвратительное место!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось добыть саронитовые пластины?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к рыцарю Олакину Сайнриту в Черный дозор, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (13141,'Битва за Вершину Рыцарей','<Верховный лорд Фордринг держит в руках знамя Серебряного Авангарда.>$B$BЭто не просто знамя, $n. Оно несет на себе благословение и потому способно очищать большие пространства зараженной порчей земли.$B$BОтнеси штандарт через Пролом на северо-запад, в место, которое эти мерзавцы из Плети в насмешку назвали Вершиной Рыцарей. Установи его там, где свалены в кучу черепа наших павших соратников и защити Вершину Рыцарей от нападения. Когда земля будет очищена, возвращайся к отцу Густаву.$B$BПоторопись, $n. И пусть твое сердце не знает страха!','Отправляйтесь на Вершину Рыцарей и установите благословенное знамя Авангарда на груде рыцарских черепов. Защищайте знамя от солдат Плети, пока земля на Вершине Рыцарей не очистится от порчи. Затем возвращайтесь к отцу Густаву в Долину Эха в Ледяной Короне.','Битва за Вершину Рыцарей','Вернитесь к отцу Густаву в Долину Эха, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Битва за Вершину Рыцарей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Верховный лорд Фордринг держит в руках знамя Серебряного Авангарда.>$B$BЭто не просто знамя, $n. Оно несет на себе благословение и потому способно очищать большие пространства зараженной порчей земли.$B$BОтнеси штандарт через Пролом на северо-запад, в место, которое эти мерзавцы из Плети в насмешку назвали Вершиной Рыцарей. Установи его там, где свалены в кучу черепа наших павших соратников и защити Вершину Рыцарей от нападения. Когда земля будет очищена, возвращайся к отцу Густаву.$B$BПоторопись, $n. И пусть твое сердце не знает страха!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь на Вершину Рыцарей и установите благословенное знамя Авангарда на груде рыцарских черепов. Защищайте знамя от солдат Плети, пока земля на Вершине Рыцарей не очистится от порчи. Затем возвращайтесь к отцу Густаву в Долину Эха в Ледяной Короне.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Битва за Вершину Рыцарей',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к отцу Густаву в Долину Эха, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13142,'Месть банши','Пришло время, $n, тебе и твоим друзьям встретиться лицом к лицу с хозяином цитадели Балагарда, владыкой Йотунхейма, верховным таном Балагардом.$B$BНа вершине крепости, расположенной в юго-западной части Йотунхейма, есть рог. Дунь в него, и твой вызов будет услышан.$B$BБалагарду не останется ничего другого, кроме как выйти с тобой на поединок. А я... прости, но вместо меня пойдет Вардмадра.$B$B<Одержимая банши ведьма издает душераздирающий смех.>','Отомстите за костяную ведьму из деревни Ньорндар, бросив вызов верховному тану Балагарду и победив его.','Верховный тан Балагард все еще жив. Ты что, не $Gнашел:нашла; крепость?','Вернитесь к костяной ведьме в деревню Ньорндар, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Месть банши',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пришло время, $n, тебе и твоим друзьям встретиться лицом к лицу с хозяином цитадели Балагарда, владыкой Йотунхейма, верховным таном Балагардом.$B$BНа вершине крепости, расположенной в юго-западной части Йотунхейма, есть рог. Дунь в него, и твой вызов будет услышан.$B$BБалагарду не останется ничего другого, кроме как выйти с тобой на поединок. А я... прости, но вместо меня пойдет Вардмадра.$B$B<Одержимая банши ведьма издает душераздирающий смех.>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отомстите за костяную ведьму из деревни Ньорндар, бросив вызов верховному тану Балагарду и победив его.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Верховный тан Балагард все еще жив. Ты что, не $Gнашел:нашла; крепость?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к костяной ведьме в деревню Ньорндар, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13143,'Новобранец','Начнем с самого главного. Я видел несколько гибких ловцов на крепостных стенах к востоку от нас. До того, как наши пути с Артасом разошлись, они служили мне и были отменными разведчиками... хотя для этого приходилось использовать глаз власти.$B$BСлетай туда, найди кого-нибудь из ловцов, задай ему трепку, а потом покажи эту печать Черного Клинка, и тогда он покорится тебе и будет слушаться беспрекословно. Ловец узнает печать, можешь не сомневаться. Отведи его на вершину скалы к северо-востоку отсюда, и он сам найдет дорогу ко мне.','Приведите укрощенного гибкого ловца на вершину скалы к северо-востоку от Высоты Страдания по указанию Верета Хитрого с Высоты Страдания.','Я уверен, что у новых хозяев им тоже приходится несладко, но эти твари никогда не забудут уроки, которые мы высекли на их шкурах. Они будут бояться этих знаков до скончания веков, пока их род не исчезнет с этой земли.','Вернитесь к Верету Хитрому на Высоту Страдания, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новобранец',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Начнем с самого главного. Я видел несколько гибких ловцов на крепостных стенах к востоку от нас. До того, как наши пути с Артасом разошлись, они служили мне и были отменными разведчиками... хотя для этого приходилось использовать глаз власти.$B$BСлетай туда, найди кого-нибудь из ловцов, задай ему трепку, а потом покажи эту печать Черного Клинка, и тогда он покорится тебе и будет слушаться беспрекословно. Ловец узнает печать, можешь не сомневаться. Отведи его на вершину скалы к северо-востоку отсюда, и он сам найдет дорогу ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Приведите укрощенного гибкого ловца на вершину скалы к северо-востоку от Высоты Страдания по указанию Верета Хитрого с Высоты Страдания.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я уверен, что у новых хозяев им тоже приходится несладко, но эти твари никогда не забудут уроки, которые мы высекли на их шкурах. Они будут бояться этих знаков до скончания веков, пока их род не исчезнет с этой земли.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Верету Хитрому на Высоту Страдания, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13144,'Одним скелетом – двух воинов Плети!','В лаборатории поганищ в Мясопилке уже завершились работы сразу над несколькими созданиями. Пока что их держат прикованными к колоннам по периметру лаборатории, но если мы срочно не примем меры, эти создания выйдут на марш с армией Короля-лича.$B$BЦепкие руки, что тянутся из груд костей, разбросанных по всей Мясопилке – это руки скелетов, наделенных магической силой огня. Разыщи несколько этих скелетов, освободи их и приведи к завершенным поганищам. А потом отойди чуть в сторонку и наслаждайся спектаклем!','Уничтожьте 3 прикованных поганищ с помощью горящих скелетов по поручению темной всадницы Арли из Черного дозора.','Замечательно. Что может быть лучше, чем проснуться с утра пораньше и вдохнуть запах поджаренной прогнившей плоти! Это запах победы над Плетью.','Ты их уничтожил?','Вернитесь к темной всаднице Арли в Черный дозор, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Одним скелетом – двух воинов Плети!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В лаборатории поганищ в Мясопилке уже завершились работы сразу над несколькими созданиями. Пока что их держат прикованными к колоннам по периметру лаборатории, но если мы срочно не примем меры, эти создания выйдут на марш с армией Короля-лича.$B$BЦепкие руки, что тянутся из груд костей, разбросанных по всей Мясопилке – это руки скелетов, наделенных магической силой огня. Разыщи несколько этих скелетов, освободи их и приведи к завершенным поганищам. А потом отойди чуть в сторонку и наслаждайся спектаклем!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 3 прикованных поганищ с помощью горящих скелетов по поручению темной всадницы Арли из Черного дозора.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Замечательно. Что может быть лучше, чем проснуться с утра пораньше и вдохнуть запах поджаренной прогнившей плоти! Это запах победы над Плетью.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты их уничтожил?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к темной всаднице Арли в Черный дозор, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13145,'Зловещая крепость','Нам нужно понять, с чем нам придется столкнуться.$B$BРазведай местность, управляя гибким ловцом с помощью глаза власти. Есть несколько мест, которые мне показались особенно подозрительными, удели им особое внимание: дозорное укрепление на северо-востоке, цеха на юго-востоке, большая кузница ближе к центру и площадка для совершения обрядов на юго-западе.$B$BЛовец – отличный прыгун, и не боится глубоких провалов. Это тебе пригодится, чтобы преодолевать крепостные стены.','Используйте гибкого ловца для разведки в Маликриссе по поручению Верета Хитрого с Высоты Страдания.','Полет может быть немного более изящным, но мы не сможем подобраться так близко, не будучи обнаруженными.','Вернитесь к Верету Хитрому на Высоту Страдания, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зловещая крепость',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нам нужно понять, с чем нам придется столкнуться.$B$BРазведай местность, управляя гибким ловцом с помощью глаза власти. Есть несколько мест, которые мне показались особенно подозрительными, удели им особое внимание: дозорное укрепление на северо-востоке, цеха на юго-востоке, большая кузница ближе к центру и площадка для совершения обрядов на юго-западе.$B$BЛовец – отличный прыгун, и не боится глубоких провалов. Это тебе пригодится, чтобы преодолевать крепостные стены.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте гибкого ловца для разведки в Маликриссе по поручению Верета Хитрого с Высоты Страдания.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Полет может быть немного более изящным, но мы не сможем подобраться так близко, не будучи обнаруженными.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Верету Хитрому на Высоту Страдания, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13146,'Предсказуемые и тупые','Используйте железную цепь гибкого ловца, чтобы подтащить бомбы Плети к 4 неповоротливым страшилищам внутри Маликрисса.','Они даже не сообразили тебя схватить? Я же говорил, что они предсказуемые и тупые.','Они даже не видели, как это происходит?','Вернитесь к Верету Хитрому на Высоту Страдания, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Предсказуемые и тупые',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте железную цепь гибкого ловца, чтобы подтащить бомбы Плети к 4 неповоротливым страшилищам внутри Маликрисса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Они даже не сообразили тебя схватить? Я же говорил, что они предсказуемые и тупые.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Они даже не видели, как это происходит?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Верету Хитрому на Высоту Страдания, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13147,'Сваха','А правда, зачем жертвовать своими солдатами, если эти ребята и так друг друга с радостью ухлопают?','Предсказуемые хамы.','Вернитесь к Верету Хитрому на Высоту Страдания, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сваха',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А правда, зачем жертвовать своими солдатами, если эти ребята и так друг друга с радостью ухлопают?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Предсказуемые хамы.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Верету Хитрому на Высоту Страдания, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13148,'Починка ожерелья','На этом сломанном ожерелье выгравирована надпись, которая гласит: "Собственность Тимоти Джонса – Ювелирные изделия, Картье и Ко. – Торговый район – Даларан".$B$BВозможно, вам следует починить его и вернуть владельцу.','Почините ожерелье с помощью одного камешка кальцедония и верните его Тимоти Джонсу в его ювелирную мастерскую в Торговую палату волшебников Даларана.','Что привело тебя сюда?','Вернитесь к Тимоти Джонсу в ювелирный магазин Картье и компании, что в Даларане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Починка ожерелья',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На этом сломанном ожерелье выгравирована надпись, которая гласит: "Собственность Тимоти Джонса – Ювелирные изделия, Картье и Ко. – Торговый район – Даларан".$B$BВозможно, вам следует починить его и вернуть владельцу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Почините ожерелье с помощью одного камешка кальцедония и верните его Тимоти Джонсу в его ювелирную мастерскую в Торговую палату волшебников Даларана.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что привело тебя сюда?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тимоти Джонсу в ювелирный магазин Картье и компании, что в Даларане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13152,'Визит к доктору','Стало быть, эти деятели в Святилище воскрешения решили оснащать вурдалаков осколками саронита? Надо им помешать, пока они не применили этих вурдалаков против наших войск.$B$BРазыщи вход в Святилище воскрешения – это где-то в Мясопилке, рядом с лабораторией мясистых великанов. "Отец-предводитель" вурдалаков, доктор Сабнок, держит там самое грозное и опасное из всех своих созданий, Заплатня. Освободи Заплатня от цепей и помоги ему отомстить доктору за все. Пусть творение само расправляется со своим творцом!','По указанию темной всадницы Арли из Черного дозора отправляйтесь в Святилище воскрешения, разрушьте металлическую стойку, к которой прикован Заплатень, и помогите ему отомстить доктору Сабноку.','Ты $Gразвязал:развязала; против него создание доктора?','Вернитесь к темной всаднице Арли в Черный дозор, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Визит к доктору',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Стало быть, эти деятели в Святилище воскрешения решили оснащать вурдалаков осколками саронита? Надо им помешать, пока они не применили этих вурдалаков против наших войск.$B$BРазыщи вход в Святилище воскрешения – это где-то в Мясопилке, рядом с лабораторией мясистых великанов. "Отец-предводитель" вурдалаков, доктор Сабнок, держит там самое грозное и опасное из всех своих созданий, Заплатня. Освободи Заплатня от цепей и помоги ему отомстить доктору за все. Пусть творение само расправляется со своим творцом!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По указанию темной всадницы Арли из Черного дозора отправляйтесь в Святилище воскрешения, разрушьте металлическую стойку, к которой прикован Заплатень, и помогите ему отомстить доктору Сабноку.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gразвязал:развязала; против него создание доктора?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к темной всаднице Арли в Черный дозор, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13153,'Охрана для воинов','$n, рада тебя видеть. Пока в битве наступило затишье, мы должны торопиться и пополнить наши запасы. Проведенные мной исследования показывают, что доспехи солдат, недавно убитых у Ледопадов, накапливают невероятное количество энергии. Орда тоже собирает доспехи в этой области.$B$BОтправляйся к Ледопадам и уничтожь всех бойцов Орды, каких сможешь там обнаружить. Принеси мне их укрепленные доспехи.$B$BЕсли ты не встретишь там никого из Орды, может, наткнешься на доспехи какого-нибудь искателя приключений, сраженного элементалями.','Принесите 10 комплектов прочных доспехов Орды из Ледопадов по приказу колдуньи Кайланы из крепости Ледяных Оков.','Ну как, получилось достать доспехи?','Вернитесь к колдунье Кайлане на Озеро Ледяных Оков.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охрана для воинов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, рада тебя видеть. Пока в битве наступило затишье, мы должны торопиться и пополнить наши запасы. Проведенные мной исследования показывают, что доспехи солдат, недавно убитых у Ледопадов, накапливают невероятное количество энергии. Орда тоже собирает доспехи в этой области.$B$BОтправляйся к Ледопадам и уничтожь всех бойцов Орды, каких сможешь там обнаружить. Принеси мне их укрепленные доспехи.$B$BЕсли ты не встретишь там никого из Орды, может, наткнешься на доспехи какого-нибудь искателя приключений, сраженного элементалями.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 комплектов прочных доспехов Орды из Ледопадов по приказу колдуньи Кайланы из крепости Ледяных Оков.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как, получилось достать доспехи?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к колдунье Кайлане на Озеро Ледяных Оков.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13154,'Кости и стрелы','По просьбе лучника Рендольфа из крепости Ледяных Оков отнимите 10 колчанов со стрелами из драконьих костей у игроков Орды в лесу Теней.','Как прошла охота на кости? До меня доходили слухи, что место это облюбовали духи, но у меня никак ноги не доходят сходить посмотреть на них самому.','Вернитесь к лучнику Рендольфу на Озеро Ледяных Оков.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кости и стрелы',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По просьбе лучника Рендольфа из крепости Ледяных Оков отнимите 10 колчанов со стрелами из драконьих костей у игроков Орды в лесу Теней.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как прошла охота на кости? До меня доходили слухи, что место это облюбовали духи, но у меня никак ноги не доходят сходить посмотреть на них самому.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лучнику Рендольфу на Озеро Ледяных Оков.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13155,'Верет Хитрый','До меня уже доходили слухи про Маликрисс и про то, что Артас учредил новый орден рыцарей смерти, но я думал, что это так... баловство... чтобы заполнить пустое место. Но судя по этим цифрам, он нацелился на что-то большее.$B$BНе так давно мы отправили в Маликрисс нашего лучшего разведчика – Верета Хитрого. Ты найдешь его на Высоте Страдания, к западу от Маликрисса, во Дворе Костей.$B$BПостарайся проникнуть туда незаметно, не привлекая излишнего внимания.','Разыщите Верета Хитрого на Высоте Страдания в Ледяной Короне.','Зловещая Крепость... лишнее подтверждение тому, как сильно Артас не любит проигрывать. Ладно, всадим клинок поглубже.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Верет Хитрый',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','До меня уже доходили слухи про Маликрисс и про то, что Артас учредил новый орден рыцарей смерти, но я думал, что это так... баловство... чтобы заполнить пустое место. Но судя по этим цифрам, он нацелился на что-то большее.$B$BНе так давно мы отправили в Маликрисс нашего лучшего разведчика – Верета Хитрого. Ты найдешь его на Высоте Страдания, к западу от Маликрисса, во Дворе Костей.$B$BПостарайся проникнуть туда незаметно, не привлекая излишнего внимания.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите Верета Хитрого на Высоте Страдания в Ледяной Короне.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Зловещая Крепость... лишнее подтверждение тому, как сильно Артас не любит проигрывать. Ладно, всадим клинок поглубже.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13156,'Редкое растение','Отберите по просьбе анахорета Тессы из крепости Ледяных Оков 10 сумок Орды с травами у ордынских игроков в степях Жизни.','Отлично! Это поможет защитить наших бойцов от простуды.','Я надеюсь, ты случайно не $Gтронул:тронула; ни одного корнехлеста? Ох, ну и досталось от них рядовому Доану на прошлой неделе!','Вернитесь к анахорету Тессе на Озеро Ледяных Оков.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Редкое растение',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отберите по просьбе анахорета Тессы из крепости Ледяных Оков 10 сумок Орды с травами у ордынских игроков в степях Жизни.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! Это поможет защитить наших бойцов от простуды.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я надеюсь, ты случайно не $Gтронул:тронула; ни одного корнехлеста? Ох, ну и досталось от них рядовому Доану на прошлой неделе!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к анахорету Тессе на Озеро Ледяных Оков.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (13157,'Вершина Рыцарей','Тебе есть чем гордиться. Ты $gпомог:помогла; нам упрочить положение Серебряного Авангарда в стенах Ледяной Короны, $n. Но теперь Король-лич со своими погаными приспешниками угрожает Вершине Рыцарей напрямую.$B$BВерховный лорд Фордринг и уцелевшие рыцари ждут тебя на Вершине Рыцарей. Тебе нужно снова пройти через Пролом и разыскать верховного лорда Фордринга.','Разыщите верховного лорда Тириона Фордринга на Вершине Рыцарей в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вершина Рыцарей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе есть чем гордиться. Ты $gпомог:помогла; нам упрочить положение Серебряного Авангарда в стенах Ледяной Короны, $n. Но теперь Король-лич со своими погаными приспешниками угрожает Вершине Рыцарей напрямую.$B$BВерховный лорд Фордринг и уцелевшие рыцари ждут тебя на Вершине Рыцарей. Тебе нужно снова пройти через Пролом и разыскать верховного лорда Фордринга.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите верховного лорда Тириона Фордринга на Вершине Рыцарей в Ледяной Короне.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13158,'Главное – скрытность','Послушай меня, |3-6($r).$b$bЯ только что узнал, что в Аметистовой крепости произошел один инцидент. Оказывается, синие драконы планируют масштабную атаку на Даларан!$b$bМне нужно, чтобы ты немедленно $gотправился:отправилась; в тюрьму и $gпоговорил:поговорила; с тюремщиком Альтурасом. Он посвятит тебя в детали.$b$bЭто еще не все. Я хочу, чтобы ты $gдействовал:действовала; очень осторожно. Незачем попусту тревожить жителей Даларана, особенно, если этой тревоги можно избежать. Я понятно выразился?$b$bОтлично. А теперь ступай!','Отправляйтесь в Аметистовую крепость в Даларане и поговорите с тюремщиком Альтурасом по поручению Ронина.','Ни минуты больше.$B$BТы готов защитить Даларан, $C?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Главное – скрытность',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Послушай меня, |3-6($r).$b$bЯ только что узнал, что в Аметистовой крепости произошел один инцидент. Оказывается, синие драконы планируют масштабную атаку на Даларан!$b$bМне нужно, чтобы ты немедленно $gотправился:отправилась; в тюрьму и $gпоговорил:поговорила; с тюремщиком Альтурасом. Он посвятит тебя в детали.$b$bЭто еще не все. Я хочу, чтобы ты $gдействовал:действовала; очень осторожно. Незачем попусту тревожить жителей Даларана, особенно, если этой тревоги можно избежать. Я понятно выразился?$b$bОтлично. А теперь ступай!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Аметистовую крепость в Даларане и поговорите с тюремщиком Альтурасом по поручению Ронина.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ни минуты больше.$B$BТы готов защитить Даларан, $C?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13159,'Сдерживание','Вот ключ от тюрьмы.$b$bМы станем здесь в качестве последней линии обороны в том случае, если вы не сможете сдержать силы нападающих.$b$bТоропись, |3-6($r). Времени мало. Те несколько воинов, что я оставил внутри, не продержатся долго.$b$bОбязательно поговори с лейтенантом Синклари. Она даст вам доступ к системе защиты тюрьмы.$b$bЯ буду ждать твоего доклада о том, что силы нападающих были успешно истреблены.','Проникните по заданию тюремщика Альтураса в Аметистовую крепость и покончите с атакующими силами синих драконов. Вернитесь к нему с докладом, когда Синигоса будет повержена.','Хвала тебе, $Gгерой:героиня;!$B$BЯ перешлю эту новость Ронину.$B$BДаларан спасен – и все благодаря твоей храбрости.','Это конец? Ты $Gсмог:смогла; выдержать нападение?','Вернитесь к тюремщику Альтурасу в Аметистовую крепость, что в Даларане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сдерживание',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот ключ от тюрьмы.$b$bМы станем здесь в качестве последней линии обороны в том случае, если вы не сможете сдержать силы нападающих.$b$bТоропись, |3-6($r). Времени мало. Те несколько воинов, что я оставил внутри, не продержатся долго.$b$bОбязательно поговори с лейтенантом Синклари. Она даст вам доступ к системе защиты тюрьмы.$b$bЯ буду ждать твоего доклада о том, что силы нападающих были успешно истреблены.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проникните по заданию тюремщика Альтураса в Аметистовую крепость и покончите с атакующими силами синих драконов. Вернитесь к нему с докладом, когда Синигоса будет повержена.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хвала тебе, $Gгерой:героиня;!$B$BЯ перешлю эту новость Ронину.$B$BДаларан спасен – и все благодаря твоей храбрости.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Это конец? Ты $Gсмог:смогла; выдержать нападение?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к тюремщику Альтурасу в Аметистовую крепость, что в Даларане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13160,'Сногсшибательное зрелище','Из горгулий получаются замечательные разведчики, к тому же они могут наносить смертоносные удары с воздуха. Но у них есть очевидные слабые стороны. Большинству горгулий приходится подолгу отдыхать, накапливая энергию для дальнейших полетов. В такие периоды они остаются неподвижными, как камень.$B$BЧерез око, которым ты пользуешься, я увидел на восточной и южной стенах десятки караульных ледошкуров. Ловец поможет тебе добраться до них, а ты уничтожишь их во сне.','По поручению Верета Хитрого с Высоты Страдания с помощью гибкого ловца поднимитесь к караульным ледошкурам и убейте 12 из них.','Пока ледошкуры спят, можно их не боятся.','Слишком легко.','Вернитесь к Верету Хитрому на Высоту Страдания, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сногсшибательное зрелище',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Из горгулий получаются замечательные разведчики, к тому же они могут наносить смертоносные удары с воздуха. Но у них есть очевидные слабые стороны. Большинству горгулий приходится подолгу отдыхать, накапливая энергию для дальнейших полетов. В такие периоды они остаются неподвижными, как камень.$B$BЧерез око, которым ты пользуешься, я увидел на восточной и южной стенах десятки караульных ледошкуров. Ловец поможет тебе добраться до них, а ты уничтожишь их во сне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По поручению Верета Хитрого с Высоты Страдания с помощью гибкого ловца поднимитесь к караульным ледошкурам и убейте 12 из них.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Пока ледошкуры спят, можно их не боятся.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Слишком легко.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Верету Хитрому на Высоту Страдания, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13161,'Всадник Нечестивости','Пришло время рубить ему головы, этому зверю.$B$BЯ довольно долго служил вместе с Рокиром. Он овладел нечестивыми искусствами лучше, чем подавляющее большинство остальных рыцарей смерти, которых я знал. И, подобно всем рыцарям смерти, он не знает жалости. Не надейся, что он будет легким противником.$B$BКогда Рокир сражается на своей территории, его могущество возрастает. Увы, выбора у нас нет; однако постарайся остаться на ногах и не поддаться натиску нежити – тогда, быть может, тебе удастся победить. $B$BДействуй быстро и ловко, |3-6($c), и не забывай: Рокир хитер и жесток.','Убейте Рокира, всадника Нечестивости, по поручению Верета Хитрого с Высоты Страдания.','Без Рокира мир станет лучше, можешь мне поверить.','Это сделано?','Вернитесь к Верету Хитрому на Высоту Страдания, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Всадник Нечестивости',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пришло время рубить ему головы, этому зверю.$B$BЯ довольно долго служил вместе с Рокиром. Он овладел нечестивыми искусствами лучше, чем подавляющее большинство остальных рыцарей смерти, которых я знал. И, подобно всем рыцарям смерти, он не знает жалости. Не надейся, что он будет легким противником.$B$BКогда Рокир сражается на своей территории, его могущество возрастает. Увы, выбора у нас нет; однако постарайся остаться на ногах и не поддаться натиску нежити – тогда, быть может, тебе удастся победить. $B$BДействуй быстро и ловко, |3-6($c), и не забывай: Рокир хитер и жесток.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Рокира, всадника Нечестивости, по поручению Верета Хитрого с Высоты Страдания.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Без Рокира мир станет лучше, можешь мне поверить.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Это сделано?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Верету Хитрому на Высоту Страдания, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13162,'Всадник Льда','Сапф... Сапф, она хоть и женщина, но среди рыцарей смерти ей нет равных. Она очарует тебя медоточивыми речами, и ты поклянешься чем угодно, что в ее сердце нет зла, а потом она просто пронзит тебя чем-нибудь острым, по-прежнему улыбаясь своей лучезарной улыбкой. Не дай ей себя обмануть.$B$BНе сомневаюсь, у тебя хватит сил одолеть Сапф; но помни – излишняя самоуверенность может тебя погубить. Сила Сапф в том, что она обманывает своих будущих жертв, притворяясь слабой, а затем обрушивает на них всю мощь ледяных атак. $B$BНе расслабляйся. Повторяю: стоит недооценить ее силы, и ты погибнешь.','Убейте Сапф, всадника Льда, по поручению Верета Хитрого с Высоты Страдания.','Честно признаюсь, мне будет слегка не хватать ее смеха... и этой улыбки, которой она улыбалась всегда перед тем, как кого-то убить. Зато теперь мне уже не придется все время оглядываться, ожидая удара в спину. Так что, наверное, грех жаловаться...','Мы избавились от нее?','Вернитесь к Верету Хитрому на Высоту Страдания, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Всадник Льда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сапф... Сапф, она хоть и женщина, но среди рыцарей смерти ей нет равных. Она очарует тебя медоточивыми речами, и ты поклянешься чем угодно, что в ее сердце нет зла, а потом она просто пронзит тебя чем-нибудь острым, по-прежнему улыбаясь своей лучезарной улыбкой. Не дай ей себя обмануть.$B$BНе сомневаюсь, у тебя хватит сил одолеть Сапф; но помни – излишняя самоуверенность может тебя погубить. Сила Сапф в том, что она обманывает своих будущих жертв, притворяясь слабой, а затем обрушивает на них всю мощь ледяных атак. $B$BНе расслабляйся. Повторяю: стоит недооценить ее силы, и ты погибнешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Сапф, всадника Льда, по поручению Верета Хитрого с Высоты Страдания.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Честно признаюсь, мне будет слегка не хватать ее смеха... и этой улыбки, которой она улыбалась всегда перед тем, как кого-то убить. Зато теперь мне уже не придется все время оглядываться, ожидая удара в спину. Так что, наверное, грех жаловаться...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мы избавились от нее?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Верету Хитрому на Высоту Страдания, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13163,'Всадник Крови','Насколько мне известно, Бэлок – один из немногих врайкулов, которым удалось сделать карьеру. В основном, благодаря своей крайней жестокости, нежели сколько-нибудь выдающимся заслугам. Если он будет повержен, а еще лучше – мертв, то у тебя станет на одного противника меньше. А это, знаешь ли, не так плохо.$B$BКогда ты вступишь с ним в бой, старайся не приближаться к нему и держаться в стороне от своих спутников. Он воспользуется любой возможностью, чтобы лишить тебя жизненной силы: постарайся не допустить этого.$B$BЯ верю в тебя. Надеюсь, ты принесешь мне вести о его смерти.','Убейте Бэлока, всадника Крови, по поручению Верета Хитрого с Высоты Страдания.','Значит, его больше нет? Очень рад это слышать.','Он умер?','Вернитесь к Верету Хитрому на Высоту Страдания, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Всадник Крови',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Насколько мне известно, Бэлок – один из немногих врайкулов, которым удалось сделать карьеру. В основном, благодаря своей крайней жестокости, нежели сколько-нибудь выдающимся заслугам. Если он будет повержен, а еще лучше – мертв, то у тебя станет на одного противника меньше. А это, знаешь ли, не так плохо.$B$BКогда ты вступишь с ним в бой, старайся не приближаться к нему и держаться в стороне от своих спутников. Он воспользуется любой возможностью, чтобы лишить тебя жизненной силы: постарайся не допустить этого.$B$BЯ верю в тебя. Надеюсь, ты принесешь мне вести о его смерти.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Бэлока, всадника Крови, по поручению Верета Хитрого с Высоты Страдания.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Значит, его больше нет? Очень рад это слышать.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Он умер?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Верету Хитрому на Высоту Страдания, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13164,'Судьба Кровопорча','Теперь, когда всадники воинства Страдания мертвы, пришло время разделаться с их предводителем – Орбазом Кровопорчем.$B$BПока тебя не было, нас нагнал Могрейн. Он нашел место, где прячется Орбаз. Под цитаделью Ледяной Короны располагается глубокая шахта – там ты и найдешь Орбаза, прямо у входа.$B$BНесколько лучших воинов Черного Клинка уже отправились к шахте, так что возьми кого-нибудь себе в помощь и присоединяйся к нашим. Пусть Кровопорч умрет!','Убейте Орбаза Кровопорча по поручению Верета с Высоты Страдания.','Стало быть, дело сделано? И Могрейн тоже был там? Как я понимаю, у него были какие-то свои счеты с Орбазом, так что не удивительно, что он тоже хотел поучаствовать в уничтожении старого врага.\n\nТы сослужил нам хорошую службу, $R, и получишь достойную награду. Прими благодарность рыцарей Черного Клинка.','Освободились ли мы наконец от того, чего хочет Артас?','Вернитесь к Верету Хитрому на Высоту Страдания, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Судьба Кровопорча',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда всадники воинства Страдания мертвы, пришло время разделаться с их предводителем – Орбазом Кровопорчем.$B$BПока тебя не было, нас нагнал Могрейн. Он нашел место, где прячется Орбаз. Под цитаделью Ледяной Короны располагается глубокая шахта – там ты и найдешь Орбаза, прямо у входа.$B$BНесколько лучших воинов Черного Клинка уже отправились к шахте, так что возьми кого-нибудь себе в помощь и присоединяйся к нашим. Пусть Кровопорч умрет!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Орбаза Кровопорча по поручению Верета с Высоты Страдания.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Стало быть, дело сделано? И Могрейн тоже был там? Как я понимаю, у него были какие-то свои счеты с Орбазом, так что не удивительно, что он тоже хотел поучаствовать в уничтожении старого врага.\n\nТы сослужил нам хорошую службу, $R, и получишь достойную награду. Прими благодарность рыцарей Черного Клинка.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Освободились ли мы наконец от того, чего хочет Артас?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Верету Хитрому на Высоту Страдания, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (13165,'Возвращение в Акерус','Король-лич вернулся в Нордскол, раненный Испепелителем, но остатки его армий все еще блокируют второй этаж крепости.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение в Акерус',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Король-лич вернулся в Нордскол, раненный Испепелителем, но остатки его армий все еще блокируют второй этаж крепости.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13166,'Битва за Черный оплот','Убейте 10 солдат Плети и помогите одолеть Лоскутика, после чего вернитесь к верховному лорду Дариону Могрейну.','Акерус будет наш!','Вернитесь к верховному лорду Дариону Могрейну в Черный оплот.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Битва за Черный оплот',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 солдат Плети и помогите одолеть Лоскутика, после чего вернитесь к верховному лорду Дариону Могрейну.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Акерус будет наш!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному лорду Дариону Могрейну в Черный оплот.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13167,'Смерть королю-предателю!','Ануб\'арак, король-предатель, обитает в некогда славном подземном королевстве Азжол-Неруб.$b$bСовершив свое предательство, он превратил нашу родину в тот жалкий край, по которому мы сейчас ступаем. Он правит армией нерубов-нежити, которые, как и их лидер, поклялись в верности Королю-личу.$b$bПокончи с правлением короля-предателя, |3-6($c). Ты окажешь величайшую услугу обоим нашим народам.$b$bЕсли ты добьешься успеха там, где все прочие потерпели поражение, принеси мне панцирь Ануб\'арака.','Одержите победу над Ануб\'араком из Азжол-Неруба и принесите Киликсу Разрушителю в Провал Наржуна разбитый панцирь Ануб\'арака.','<Глаза Киликса начинают светиться, когда он смотрит на панцирь.>\n\nС ним ПОКОНЧЕНО!\n\n$R! Твое имя будет высечено на страницах истории нашего народа.\n\nЯ пред тобой в долгу…','С ним покончено, |3-6($C)? Король-предатель встретил свой неизбежный конец?','Вернитесь к Киликсу Разрушителю в Провал Наржуна, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Смерть королю-предателю!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ануб\'арак, король-предатель, обитает в некогда славном подземном королевстве Азжол-Неруб.$b$bСовершив свое предательство, он превратил нашу родину в тот жалкий край, по которому мы сейчас ступаем. Он правит армией нерубов-нежити, которые, как и их лидер, поклялись в верности Королю-личу.$b$bПокончи с правлением короля-предателя, |3-6($c). Ты окажешь величайшую услугу обоим нашим народам.$b$bЕсли ты добьешься успеха там, где все прочие потерпели поражение, принеси мне панцирь Ануб\'арака.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Одержите победу над Ануб\'араком из Азжол-Неруба и принесите Киликсу Разрушителю в Провал Наржуна разбитый панцирь Ануб\'арака.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Глаза Киликса начинают светиться, когда он смотрит на панцирь.>\n\nС ним ПОКОНЧЕНО!\n\n$R! Твое имя будет высечено на страницах истории нашего народа.\n\nЯ пред тобой в долгу…',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','С ним покончено, |3-6($C)? Король-предатель встретил свой неизбежный конец?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Киликсу Разрушителю в Провал Наржуна, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (13168,'Простой урок','Смотри-ка... Это глаза власти. Служители Культа делают все, чтобы сохранить эти предметы. Но думаю, у них будет мало шансов, когда мы нападем на них прямо у них дома.$B$BГлаза власти позволяют управлять нежитью. Как ты понимаешь, было бы здорово получить контроль над всеми этими неуклюжими вурдалаками и скелетами.$B$BХочешь попробовать? Используй глаз власти, чтобы управлять пойманным духом.','По заданию Керитоза Кровавого Клинка из Мрачного Свода возьмите под свой контроль пойманного эйдолонского наблюдателя, используя глаз власти.','Варианты уловок, доступных нам, очевидны. Это будут очень полезные инструменты.','Возьмите под свой контроль эйдолонского наблюдателя.','Вернитесь к Керитозу Кровавому Клинку в Мрачный Свод, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Простой урок',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Смотри-ка... Это глаза власти. Служители Культа делают все, чтобы сохранить эти предметы. Но думаю, у них будет мало шансов, когда мы нападем на них прямо у них дома.$B$BГлаза власти позволяют управлять нежитью. Как ты понимаешь, было бы здорово получить контроль над всеми этими неуклюжими вурдалаками и скелетами.$B$BХочешь попробовать? Используй глаз власти, чтобы управлять пойманным духом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По заданию Керитоза Кровавого Клинка из Мрачного Свода возьмите под свой контроль пойманного эйдолонского наблюдателя, используя глаз власти.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Варианты уловок, доступных нам, очевидны. Это будут очень полезные инструменты.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Возьмите под свой контроль эйдолонского наблюдателя.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Керитозу Кровавому Клинку в Мрачный Свод, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13169,'Лучший друг нежити','Нежить, заправляющая добычей саронита на юго-западе отсюда, морит голодом местных чумных псов, чтобы они были еще злее. Подкрадись к ним, используя маскировку, и покорми нескольких псов. Я уверен, что они либо тут же оставят тебя в покое, либо вовсе решат присоединиться к тому, кто дал им еду.$B$BТолько пока не накормишь их, близко не подходи: твоя маскировка не обманет их чутье.','По просьбе Керитоза Кровавого Клинка из Мрачного Свода накормите с помощью эйдолонского наблюдателя 18 проголодавшихся чумных псов.','Сморило их, да?','Не нужно быть расточительным - эти гончие будут служить тем, кто будет их кормить.','Вернитесь к Керитозу Кровавому Клинку в Мрачный Свод, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лучший друг нежити',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нежить, заправляющая добычей саронита на юго-западе отсюда, морит голодом местных чумных псов, чтобы они были еще злее. Подкрадись к ним, используя маскировку, и покорми нескольких псов. Я уверен, что они либо тут же оставят тебя в покое, либо вовсе решат присоединиться к тому, кто дал им еду.$B$BТолько пока не накормишь их, близко не подходи: твоя маскировка не обманет их чутье.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По просьбе Керитоза Кровавого Клинка из Мрачного Свода накормите с помощью эйдолонского наблюдателя 18 проголодавшихся чумных псов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сморило их, да?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Не нужно быть расточительным - эти гончие будут служить тем, кто будет их кормить.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Керитозу Кровавому Клинку в Мрачный Свод, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13170,'Честь – удел слабых','Вурдалаки, вообще-то, достаточно хрупкие и нежные существа, и дозорные на юго-западных разработках саронита – не исключение. Использовав одну из теней, ты без труда сможешь пробраться туда и бесшумно убрать дозорных одного за другим.$B$BПрикончи как можно больше дозорных. Время у тебя будет, но не много... нужно, чтобы к нашей атаке их ряды поредели как следует.','Убейте 20 неутомимых дозорных по поручению Керитоза Кровавого Клинка из Мрачного Свода.','Трудно искать то, что не видно.','Вернитесь к Керитозу Кровавому Клинку в Мрачный Свод, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Честь – удел слабых',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вурдалаки, вообще-то, достаточно хрупкие и нежные существа, и дозорные на юго-западных разработках саронита – не исключение. Использовав одну из теней, ты без труда сможешь пробраться туда и бесшумно убрать дозорных одного за другим.$B$BПрикончи как можно больше дозорных. Время у тебя будет, но не много... нужно, чтобы к нашей атаке их ряды поредели как следует.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 20 неутомимых дозорных по поручению Керитоза Кровавого Клинка из Мрачного Свода.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Трудно искать то, что не видно.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Керитозу Кровавому Клинку в Мрачный Свод, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13171,'Откуда придет удар','Больше всего меня беспокоит саронитовый карьер на юго-западе отсюда. Там добывают такое невероятное количество руды, что я не представляю даже, что они собираются из нее делать. Но узнать это не так просто. Начнем с того, что ослабим их оборону.$B$BЯ заметил, что по всей базе разбросаны какие-то кристаллы. Думаю, они как раз служат для охраны. Ну, примерно, как зиккураты. Найди несколько таких кристаллов и уничтожь их с помощью эйдолонского наблюдателя.','По заданию Керитоза Кровавого Клинка из Мрачного Свода уничтожьте 10 сдерживающих кристаллов Плети.','$GУничтожал:Уничтожила; кристаллы? Я не хочу, чтобы они оказались неприятным сюрпризом для моих грифонов.','Вернитесь к Керитозу Кровавому Клинку в Мрачный Свод, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Откуда придет удар',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Больше всего меня беспокоит саронитовый карьер на юго-западе отсюда. Там добывают такое невероятное количество руды, что я не представляю даже, что они собираются из нее делать. Но узнать это не так просто. Начнем с того, что ослабим их оборону.$B$BЯ заметил, что по всей базе разбросаны какие-то кристаллы. Думаю, они как раз служат для охраны. Ну, примерно, как зиккураты. Найди несколько таких кристаллов и уничтожь их с помощью эйдолонского наблюдателя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По заданию Керитоза Кровавого Клинка из Мрачного Свода уничтожьте 10 сдерживающих кристаллов Плети.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$GУничтожал:Уничтожила; кристаллы? Я не хочу, чтобы они оказались неприятным сюрпризом для моих грифонов.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Керитозу Кровавому Клинку в Мрачный Свод, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13172,'Семена Хаоса','Полезная вещь, не правда ли? Тебе отлично удалось ослабить их оборону, |3-6($c). Теперь мы можем отправить в наступление основные силы.$B$BПлан прост: мы уничтожаем все, что движется, прорываемся вовнутрь и, пользуясь всеобщим замешательством, похищаем нужную информацию.$B$BСкажешь, когда будешь $gготов:готова;. Я дам тебе грифона-скелета.','По указанию Керитоза Кровавого Клинка из Мрачного Свода уничтожьте 80 солдат нежити в Саронитовом карьере. Попросите у него грифона-скелета.','Да там защита – одно название. Проще не бывает.','Повеселись, а?','Вернитесь к Керитозу Кровавому Клинку в Мрачный Свод, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Семена Хаоса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Полезная вещь, не правда ли? Тебе отлично удалось ослабить их оборону, |3-6($c). Теперь мы можем отправить в наступление основные силы.$B$BПлан прост: мы уничтожаем все, что движется, прорываемся вовнутрь и, пользуясь всеобщим замешательством, похищаем нужную информацию.$B$BСкажешь, когда будешь $gготов:готова;. Я дам тебе грифона-скелета.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По указанию Керитоза Кровавого Клинка из Мрачного Свода уничтожьте 80 солдат нежити в Саронитовом карьере. Попросите у него грифона-скелета.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да там защита – одно название. Проще не бывает.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Повеселись, а?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Керитозу Кровавому Клинку в Мрачный Свод, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (13173,'Под шумок','Нам удалось прибрать к рукам довольно много рабочих. Они отлично подойдут.$b$bЯ прошу тебя использовать глаз, чтобы привести одного из этих рабочих обратно в карьер. Сейчас, когда в лагере суматоха и неразбериха, они ни за что не отличат тебя от любого другого рабочего из тех, что разбежались во время нападения.$b$bНайди главного и приступай к работе. Если повезет, мы быстро выясним, куда они отправляют саронит. Я буду наблюдать за тобой через глаз.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Под шумок',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нам удалось прибрать к рукам довольно много рабочих. Они отлично подойдут.$b$bЯ прошу тебя использовать глаз, чтобы привести одного из этих рабочих обратно в карьер. Сейчас, когда в лагере суматоха и неразбериха, они ни за что не отличат тебя от любого другого рабочего из тех, что разбежались во время нападения.$b$bНайди главного и приступай к работе. Если повезет, мы быстро выясним, куда они отправляют саронит. Я буду наблюдать за тобой через глаз.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13174,'Под шумок','Помешать осуществлению их проектов – это лишь часть нашего плана. Еще одна важная задача: выяснить, куда они отправляют столько саронита. Мы уже знаем несколько пунктов назначения, но его добывают в таких количествах, что вывод напрашивается сам собой: где-то ведутся работы над каким-то масштабным проектом.$B$BОтправляйся в карьер и попробуй добыть хоть какие-то сведения. Принеси мне все бумаги, какие найдешь. Если полетишь туда на грифоне, то можешь спешиться, как только покончишь с грязной работой.','Принесите документ из Саронитового карьера, гроссбух Саронитового карьера, карту Саронитового карьера и расписание работ в Саронитовом карьере Керитозу Кровавому Клинку в Мрачный Свод.','Вернитесь к Керитозу Кровавому Клинку в Мрачный Свод, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Под шумок',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Помешать осуществлению их проектов – это лишь часть нашего плана. Еще одна важная задача: выяснить, куда они отправляют столько саронита. Мы уже знаем несколько пунктов назначения, но его добывают в таких количествах, что вывод напрашивается сам собой: где-то ведутся работы над каким-то масштабным проектом.$B$BОтправляйся в карьер и попробуй добыть хоть какие-то сведения. Принеси мне все бумаги, какие найдешь. Если полетишь туда на грифоне, то можешь спешиться, как только покончишь с грязной работой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите документ из Саронитового карьера, гроссбух Саронитового карьера, карту Саронитового карьера и расписание работ в Саронитовом карьере Керитозу Кровавому Клинку в Мрачный Свод.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Керитозу Кровавому Клинку в Мрачный Свод, что в Ледяной Короне.',`completedtext_loc8`);
