INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13177,'Беспощадным пощады не будет','Добро пожаловать в крепость Ледяных Оков, $n. Твое задание будет очень простым. Одержи победу над десятью представителями Орды. А теперь ступай! Принеси победу Альянсу!','Ну что, ты $Gсправился:справилась; с поручением?','Вернитесь к командиру Заннету на Озеро Ледяных Оков.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Беспощадным пощады не будет',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Добро пожаловать в крепость Ледяных Оков, $n. Твое задание будет очень простым. Одержи победу над десятью представителями Орды. А теперь ступай! Принеси победу Альянсу!',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, ты $Gсправился:справилась; с поручением?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру Заннету на Озеро Ледяных Оков.',`completedtext_loc8`);
