INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13182,'И не забудь про яйца!','По всему Азжол-Нерубу порабощенные Плетью нерубы заботятся о яйцах, из которых вскоре должно появиться на свет их потомство, пополнив их и без того огромную армию.$b$bСкверно получится, если мы уничтожим наводнившую пещеры нежить, а эти скверные яйца останутся дозревать. Тогда новые орды займут место павших.$b$bЕсли ты направишься в ту область, что когда-то была известна как Азжол-Неруб, обязательно избавь наш древний дом ото всех яиц Плети, что встретятся тебе на пути.','Проникните в Азжол-Неруб по просьбе Киликса Разрушителя из Провала Наржуна и уничтожьте 6 нерубских яиц Плети.','Меня глубоко печалит нынешнее положение вещей. Если бы только мы могли восстановить былое величие нашей империи…','Удалось ли тебе избавить наш дом от яиц?','Вернитесь к Киликсу Разрушителю в Провал Наржуна, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','И не забудь про яйца!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','По всему Азжол-Нерубу порабощенные Плетью нерубы заботятся о яйцах, из которых вскоре должно появиться на свет их потомство, пополнив их и без того огромную армию.$b$bСкверно получится, если мы уничтожим наводнившую пещеры нежить, а эти скверные яйца останутся дозревать. Тогда новые орды займут место павших.$b$bЕсли ты направишься в ту область, что когда-то была известна как Азжол-Неруб, обязательно избавь наш древний дом ото всех яиц Плети, что встретятся тебе на пути.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проникните в Азжол-Неруб по просьбе Киликса Разрушителя из Провала Наржуна и уничтожьте 6 нерубских яиц Плети.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Меня глубоко печалит нынешнее положение вещей. Если бы только мы могли восстановить былое величие нашей империи…',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось ли тебе избавить наш дом от яиц?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Киликсу Разрушителю в Провал Наржуна, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`requestitemstext_loc8`) VALUES (13183,'Хотя Дардош весьма успешно справляется с уничтожением наших врагов, более важным для нас является контроль над крепостью Ледяных Оков. Сделай все, что потребуется, чтобы она принадлежала нам. Не думай, что союзники сделают за тебя всю грязную работу. Если к концу битвы не станешь рекрутом хотя бы второго уровня, можешь не возвращаться.','Надеюсь, ты $Gвернулся:вернулась; с победой?') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хотя Дардош весьма успешно справляется с уничтожением наших врагов, более важным для нас является контроль над крепостью Ледяных Оков. Сделай все, что потребуется, чтобы она принадлежала нам. Не думай, что союзники сделают за тебя всю грязную работу. Если к концу битвы не станешь рекрутом хотя бы второго уровня, можешь не возвращаться.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Надеюсь, ты $Gвернулся:вернулась; с победой?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (13184,'Больше нет нужды') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Больше нет нужды',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13185,'Остановка осады','Я слышать их! Альянс скоро прийти. Уничтожь три осадных машины Альянса и возвращайся к Мурпу.','Уничтожьте 3 осадных машины Альянса по приказу лейтенанта Мурпа из крепости Ледяных Оков.','Хорошая работа. Жаль, Мурпа рядом с тобой не было, он бы помог.','Ты нашла еще Вечную мерзлоту, невеличка |3-6($R?','Вернитесь к лейтенанту Мурпу на Озеро Ледяных Оков.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Остановка осады',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я слышать их! Альянс скоро прийти. Уничтожь три осадных машины Альянса и возвращайся к Мурпу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 3 осадных машины Альянса по приказу лейтенанта Мурпа из крепости Ледяных Оков.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошая работа. Жаль, Мурпа рядом с тобой не было, он бы помог.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты нашла еще Вечную мерзлоту, невеличка |3-6($R?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лейтенанту Мурпу на Озеро Ледяных Оков.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13186,'Остановка осады','Рано или поздно крепость будет осаждена силами Орды. Уничтожь три их осадных машины и возвращайся ко мне.','Уничтожьте по приказу главного подрывника Легосо из крепости Ледяных Оков 3 осадных машины Орды.','Отлично. Это должно существенно ослабить их атаку.','Нет времени на болтовню, перейдем сразу к делу: ты $Gуничтожил:уничтожила; их осадные машины?','Вернитесь к главному подрывнику Легосо на Озеро Ледяных Оков.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Остановка осады',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Рано или поздно крепость будет осаждена силами Орды. Уничтожь три их осадных машины и возвращайся ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте по приказу главного подрывника Легосо из крепости Ледяных Оков 3 осадных машины Орды.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично. Это должно существенно ослабить их атаку.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Нет времени на болтовню, перейдем сразу к делу: ты $Gуничтожил:уничтожила; их осадные машины?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к главному подрывнику Легосо на Озеро Ледяных Оков.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13188,'Шаги короля','<Вариан задумчиво смотрит вдаль.>$B$BВоистину, это весточка от старого друга... Кровь и честь!$B$B<Вариан вновь смотрит прямо на вас.>$B$BЕсли бы не это письмо – лежать бы тебе с перерезанным горлом. Благодари за свое спасение одного из величайших паладинов нашего времени!$B$BМы... мы будем сражаться вместе с твоим орденом против Плети. Против Короля-лича.$B$BИ ВО СЛАВУ АЛЬЯНСА!','Говори, ибо сейчас ты умрешь.','Вернитесь к королю Вариану Ринну в Штормград.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Шаги короля',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Вариан задумчиво смотрит вдаль.>$B$BВоистину, это весточка от старого друга... Кровь и честь!$B$B<Вариан вновь смотрит прямо на вас.>$B$BЕсли бы не это письмо – лежать бы тебе с перерезанным горлом. Благодари за свое спасение одного из величайших паладинов нашего времени!$B$BМы... мы будем сражаться вместе с твоим орденом против Плети. Против Короля-лича.$B$BИ ВО СЛАВУ АЛЬЯНСА!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Говори, ибо сейчас ты умрешь.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к королю Вариану Ринну в Штормград.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13189,'Интересный поворот событий!','Вернитесь к Траллу в Оргриммар.') ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Интересный поворот событий!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Траллу в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13190,'Все хорошо в свое время','Ан\'кахет, откуда мы пришли...$b$bОднажды, я верю, мы победим смерть и тьму, что окутали нашу древнюю родину. Чтобы это свершилось, у меня есть план, как ослабить защиту наших врагов.$b$bИх драгоценнейшие наблюдатели должны быть сожжены!$b$bСобери их трупы и сложи на жаровню в глубине этого города. Запах их горящих останков наполнит воздух, напоминая наших врагам об их слабости.$b$bНе забывай, |3-6($c)! У них тела нежити – они весьма недолговечны и разрушаются очень быстро.','Заполучите труп наблюдателя Ан\'кахара по поручению Киликса Разрушителя из Провала Наржуна и поместите его на ан\'кахетскую жаровню в Ан\'кахете.$b$bЭто задание может быть выполнено только в героическом режиме.','Спасибо, $C. Сегодня вы нанесли удар неживым.','Удалось ли тебе сжечь труп наблюдателя, $R?','Вернитесь к Киликсу Разрушителю в Провал Наржуна, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Все хорошо в свое время',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ан\'кахет, откуда мы пришли...$b$bОднажды, я верю, мы победим смерть и тьму, что окутали нашу древнюю родину. Чтобы это свершилось, у меня есть план, как ослабить защиту наших врагов.$b$bИх драгоценнейшие наблюдатели должны быть сожжены!$b$bСобери их трупы и сложи на жаровню в глубине этого города. Запах их горящих останков наполнит воздух, напоминая наших врагам об их слабости.$b$bНе забывай, |3-6($c)! У них тела нежити – они весьма недолговечны и разрушаются очень быстро.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заполучите труп наблюдателя Ан\'кахара по поручению Киликса Разрушителя из Провала Наржуна и поместите его на ан\'кахетскую жаровню в Ан\'кахете.$b$bЭто задание может быть выполнено только в героическом режиме.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо, $C. Сегодня вы нанесли удар неживым.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось ли тебе сжечь труп наблюдателя, $R?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Киликсу Разрушителю в Провал Наржуна, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13191,'Горючее для разрушителей','Соберите 10 неугасимых угольков с тел воинов Альянса в Огненной котловине по приказу осадного кузнеца Могучее Копыто из крепости Ледяных Оков.','Отлично! Это поможет нам победить Альянс в грядущих битвах','Ну как? Получилось ли у тебя найти угли, или Альянс побил тебя, и ты $Gсбежал:сбежала; $Gвесь:вся; в слезах?','Вернитесь к осадному кузнецу Могучему Копыту на Озеро Ледяных Оков.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Горючее для разрушителей',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 неугасимых угольков с тел воинов Альянса в Огненной котловине по приказу осадного кузнеца Могучее Копыто из крепости Ледяных Оков.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! Это поможет нам победить Альянс в грядущих битвах',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как? Получилось ли у тебя найти угли, или Альянс побил тебя, и ты $Gсбежал:сбежала; $Gвесь:вся; в слезах?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к осадному кузнецу Могучему Копыту на Озеро Ледяных Оков.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13192,'Охрана стен','Отправляйтесь к Ледопадам и заполучи 10 зачарованных доспехов Альянса по просьбе мастера худу Фу\'джина из крепости Ледяных Оков.','Ох, да, да, да вещи, мон!','Ты $Gпринес:принесла; доспехи?','Вернитесь к мастеру худу Фу\'джину на Озеро Ледяных Оков.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охрана стен',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь к Ледопадам и заполучи 10 зачарованных доспехов Альянса по просьбе мастера худу Фу\'джина из крепости Ледяных Оков.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ох, да, да, да вещи, мон!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gпринес:принесла; доспехи?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру худу Фу\'джину на Озеро Ледяных Оков.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13193,'Кости и стрелы','Раздобудьте 10 колчанов со стрелами из драконьих костей у игроков Альянса в лесу Теней по просьбе лейтенанта Виерона Огненного Пера из крепости Ледяных Оков.','Похоже, мне предстоит еще одна ночка заточки костей для наконечников. И чего мне не сиделось в Луносвете, как моему брату?','Я не ждал тебя так рано. Ох, а я-то надеялся хоть немного отдохнуть.','Вернитесь к Виерону Огненному Перу на Озеро Ледяных Оков.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кости и стрелы',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте 10 колчанов со стрелами из драконьих костей у игроков Альянса в лесу Теней по просьбе лейтенанта Виерона Огненного Пера из крепости Ледяных Оков.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Похоже, мне предстоит еще одна ночка заточки костей для наконечников. И чего мне не сиделось в Луносвете, как моему брату?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я не ждал тебя так рано. Ох, а я-то надеялся хоть немного отдохнуть.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Виерону Огненному Перу на Озеро Ледяных Оков.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13194,'Целительные розы','Отнимите 10 сумок с травами у игроков Альянса в степи Жизни по просьбе идолопоклонника Мулфорта.','Спасибо тебе, это поможет нам быстрее залечить раны наших солдат.','Удалось ли тебе отыскать травы? Число больных и раненых растет с каждым часом.','Вернитесь к шаману стихий Мулфорт на Озеро Ледяных Оков.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Целительные розы',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнимите 10 сумок с травами у игроков Альянса в степи Жизни по просьбе идолопоклонника Мулфорта.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо тебе, это поможет нам быстрее залечить раны наших солдат.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось ли тебе отыскать травы? Число больных и раненых растет с каждым часом.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к шаману стихий Мулфорт на Озеро Ледяных Оков.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (13195,'Редкое растение','Принесите анахорету Тессе 10 сумок Орды с травами из степей Жизни.','Отлично! Это поможет защитить наших бойцов от простуды.','Вернитесь к анахорету Тессе на Озеро Ледяных Оков.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Редкое растение',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите анахорету Тессе 10 сумок Орды с травами из степей Жизни.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! Это поможет защитить наших бойцов от простуды.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к анахорету Тессе на Озеро Ледяных Оков.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13196,'Кости и стрелы','По просьбе лучника Рендольфа из крепости Ледяных Оков отыщите 10 колчанов со стрелами из драконьих костей у игроков Орды в лесу Теней.','Как прошла охота на кости? До меня доходили слухи, что место это облюбовали духи, но у меня никак ноги не доходят сходить посмотреть на них самому.','Вернитесь к лучнику Рендольфу на Озеро Ледяных Оков.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кости и стрелы',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По просьбе лучника Рендольфа из крепости Ледяных Оков отыщите 10 колчанов со стрелами из драконьих костей у игроков Орды в лесу Теней.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как прошла охота на кости? До меня доходили слухи, что место это облюбовали духи, но у меня никак ноги не доходят сходить посмотреть на них самому.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лучнику Рендольфу на Озеро Ледяных Оков.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13197,'Горючее для разрушителей','Прекрасно! Этих дровишек хватит, чтобы костер войны не угасал еще долго.','Ну как? Получилось ли у тебя найти угли, или Орда побила тебя, и ты $Gсбежал:сбежала; $Gвесь:вся; в слезах?','Вернитесь к осадному кузнецу Крепкохвату на Озеро Ледяных Оков.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Горючее для разрушителей',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно! Этих дровишек хватит, чтобы костер войны не угасал еще долго.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как? Получилось ли у тебя найти угли, или Орда побила тебя, и ты $Gсбежал:сбежала; $Gвесь:вся; в слезах?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к осадному кузнецу Крепкохвату на Озеро Ледяных Оков.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13198,'Охрана для воинов','$n, рад тебя видеть. Мы должны подготовиться к следующей атаке на крепость. Проведенные мной исследования показывают, что доспехи солдат, недавно убитых у Ледопадов, накапливают невероятное количество энергии. Орда тоже собирает доспехи в этой области.$B$BОтправляйся к Ледопадам и уничтожь всех ордынцев, каких только обнаружишь. Принеси мне их укрепленные доспехи.$B$BЕсли ты не встретишь там никого из Орды, может, наткнешься на доспехи какого-нибудь искателя приключений, сраженного элементалями.','Ну как, получилось достать доспехи?','Вернитесь к колдунье Кайлане на Озеро Ледяных Оков.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охрана для воинов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, рад тебя видеть. Мы должны подготовиться к следующей атаке на крепость. Проведенные мной исследования показывают, что доспехи солдат, недавно убитых у Ледопадов, накапливают невероятное количество энергии. Орда тоже собирает доспехи в этой области.$B$BОтправляйся к Ледопадам и уничтожь всех ордынцев, каких только обнаружишь. Принеси мне их укрепленные доспехи.$B$BЕсли ты не встретишь там никого из Орды, может, наткнешься на доспехи какого-нибудь искателя приключений, сраженного элементалями.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как, получилось достать доспехи?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к колдунье Кайлане на Озеро Ледяных Оков.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13199,'Кости и стрелы','Раздобудьте 10 колчанов со стрелами из драконьих костей у игроков Альянса в лесу Теней по просьбе лейтенанта Виерона Огненного Пера из крепости Ледяных Оков.','Похоже, мне предстоит еще одна ночка заточки костей для наконечников. И чего мне не сиделось в Луносвете, как моему брату?','Я не ждал тебя так рано. Ох, а я-то надеялся хоть немного отдохнуть.','Вернитесь к Виерону Огненному Перу на Озеро Ледяных Оков.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кости и стрелы',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте 10 колчанов со стрелами из драконьих костей у игроков Альянса в лесу Теней по просьбе лейтенанта Виерона Огненного Пера из крепости Ледяных Оков.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Похоже, мне предстоит еще одна ночка заточки костей для наконечников. И чего мне не сиделось в Луносвете, как моему брату?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я не ждал тебя так рано. Ох, а я-то надеялся хоть немного отдохнуть.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Виерону Огненному Перу на Озеро Ледяных Оков.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13200,'Горючее для разрушителей','Соберите 10 неугасимых угольков с тел воинов Альянса в Огненной котловине по приказу осадного кузнеца Могучее Копыто из крепости Ледяных Оков.','Отлично! Это поможет нам победить Альянс в грядущих битвах.','Ну как? Получилось ли у тебя найти угли, или Альянс побил тебя, и ты $Gсбежал:сбежала; $Gвесь:вся; в слезах?','Вернитесь к осадному кузнецу Могучему Копыту на Озеро Ледяных Оков.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Горючее для разрушителей',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 неугасимых угольков с тел воинов Альянса в Огненной котловине по приказу осадного кузнеца Могучее Копыто из крепости Ледяных Оков.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! Это поможет нам победить Альянс в грядущих битвах.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как? Получилось ли у тебя найти угли, или Альянс побил тебя, и ты $Gсбежал:сбежала; $Gвесь:вся; в слезах?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к осадному кузнецу Могучему Копыту на Озеро Ледяных Оков.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13201,'Целительные розы','Отыщите 10 сумок Альянса с травами в степи Жизни по просьбе идолопоклонника Мулфорта.','Спасибо тебе, это поможет нам быстрее залечить раны наших солдат.','Удалось ли тебе отыскать травы? Число больных и раненых растет с каждым часом.','Вернитесь к шаману стихий Мулфорт на Озеро Ледяных Оков.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Целительные розы',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщите 10 сумок Альянса с травами в степи Жизни по просьбе идолопоклонника Мулфорта.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо тебе, это поможет нам быстрее залечить раны наших солдат.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось ли тебе отыскать травы? Число больных и раненых растет с каждым часом.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к шаману стихий Мулфорт на Озеро Ледяных Оков.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13202,'Заколдованные стены','Ох, да, да, да вещи, мон!','Ты $Gпринес:принесла; доспехи?','Вернитесь к мастеру худу Фу\'джину на Озеро Ледяных Оков.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Заколдованные стены',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ох, да, да, да вещи, мон!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gпринес:принесла; доспехи?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру худу Фу\'джину на Озеро Ледяных Оков.',`completedtext_loc8`);
