INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13204,'Странные грибочки','Бесформенный кусок похожей на гриб плесени отваливается от особенно вонючего, покрытого слизью куска плоти пещерного зверя. Пока вы осматриваете отвалившийся кусок, вас просто передергивает от этого невыносимого смрада.$b$bВы удивляетесь про себя – неужели эту штуковину нерубы находят аппетитной? Положив липкую субстанцию к себе в сумку, вы собираетесь это выяснить...','Соберите 6 кусков диковинной плесени с диких пещерных зверей в Ан\'кахете и принесите их Киликсу Разрушителю в Провал Наржуна.','Ты хоть представляешь, что таскал с собой, $C?$B$BУ пещерных зверей, которых вы добывали, нет традиционного метода выделения своих отходов. Вы можете вымыть руки... ПОТОМУ ЧТО ЭТО ДЕРЬМО!','Что это за творение?!','Вернитесь к Киликсу Разрушителю в Провал Наржуна, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Странные грибочки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Бесформенный кусок похожей на гриб плесени отваливается от особенно вонючего, покрытого слизью куска плоти пещерного зверя. Пока вы осматриваете отвалившийся кусок, вас просто передергивает от этого невыносимого смрада.$b$bВы удивляетесь про себя – неужели эту штуковину нерубы находят аппетитной? Положив липкую субстанцию к себе в сумку, вы собираетесь это выяснить...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 6 кусков диковинной плесени с диких пещерных зверей в Ан\'кахете и принесите их Киликсу Разрушителю в Провал Наржуна.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты хоть представляешь, что таскал с собой, $C?$B$BУ пещерных зверей, которых вы добывали, нет традиционного метода выделения своих отходов. Вы можете вымыть руки... ПОТОМУ ЧТО ЭТО ДЕРЬМО!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что это за творение?!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Киликсу Разрушителю в Провал Наржуна, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13205,'Разоружение','Поверь мне на слово, $gдружище:подруга;: с врайкульскими топорами лучше близко не знакомиться!$b$bУ меня самого есть парочка шрамов от их клинков – отлично сбалансированных, чудовищно острых и совершенно смертоносных.$b$bДавай-ка, проникни в их крепость и стащи кое-что из врайкульского арсенала. Может быть, нам удастся разобраться, как они куют такое оружие. А может быть, и нет.$b$bВ любом случае – чем меньше у них топоров, тем лучше для нас.','Защитник Мордун поручил вам проникнуть в Крепость Утгард и украсть 5 образцов врайкульского оружия.','<Мордун свистит.>$B$BТы просто взглянешь на них? Невероятно.','Ты $Gукрал:украла; оружие врайкулов?','Вернитесь к защитнику Мордуну в Деревню Драконьего Черепа, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разоружение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Поверь мне на слово, $gдружище:подруга;: с врайкульскими топорами лучше близко не знакомиться!$b$bУ меня самого есть парочка шрамов от их клинков – отлично сбалансированных, чудовищно острых и совершенно смертоносных.$b$bДавай-ка, проникни в их крепость и стащи кое-что из врайкульского арсенала. Может быть, нам удастся разобраться, как они куют такое оружие. А может быть, и нет.$b$bВ любом случае – чем меньше у них топоров, тем лучше для нас.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Защитник Мордун поручил вам проникнуть в Крепость Утгард и украсть 5 образцов врайкульского оружия.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Мордун свистит.>$B$BТы просто взглянешь на них? Невероятно.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gукрал:украла; оружие врайкулов?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к защитнику Мордуну в Деревню Драконьего Черепа, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (13210,'Blizzard Account: - DEM - E - FLAG') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Blizzard Account: - DEM - E - FLAG',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13211,'Сила очищающего огня','Плеть использует против нас наших же павших солдат, превращая их в вурдалаков и скелетов или расчленяя их тела и собирая из разных частей поганищ. Мы должны положить этому конец!$B$BНаши солдаты пали, защищая тех, кто остался в живых, и наш долг – избавить их после смерти от столь ужасной участи. К тому же, нам не хотелось бы, чтобы они служили подкреплением вражеским войскам на поле боя. Возьми этот факел с собой, когда пойдешь на Мясопилку, и сожги все трупы, которые найдешь в Святилище воскрешения или в лаборатории поганищ.','Рыцарь Олакин Сайнрит из Черного дозора просит сжечь 7 гноящихся трупов с помощью факела Олакина.','Ты $Gизбавился:избавилась; от тел убитых солдатами Плети?','Вернитесь к рыцарю Олакину Сайнриту в Черный дозор, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сила очищающего огня',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Плеть использует против нас наших же павших солдат, превращая их в вурдалаков и скелетов или расчленяя их тела и собирая из разных частей поганищ. Мы должны положить этому конец!$B$BНаши солдаты пали, защищая тех, кто остался в живых, и наш долг – избавить их после смерти от столь ужасной участи. К тому же, нам не хотелось бы, чтобы они служили подкреплением вражеским войскам на поле боя. Возьми этот факел с собой, когда пойдешь на Мясопилку, и сожги все трупы, которые найдешь в Святилище воскрешения или в лаборатории поганищ.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Рыцарь Олакин Сайнрит из Черного дозора просит сжечь 7 гноящихся трупов с помощью факела Олакина.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gизбавился:избавилась; от тел убитых солдатами Плети?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к рыцарю Олакину Сайнриту в Черный дозор, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (13212,'Части тела','Враги захватили рыцаря Олакина, и Серебряный Авангард лишился командующего как раз перед самой атакой на Мясопилку. Для меня-то все рыцари одинаковы, но сами они так не думают.$B$BМне не хотелось бы тратить на это время, но выбора у меня нет. Нашего благородного рыцаря, наверное, уже давно разрубили на мелкие кусочки, чтобы соорудить из них поганищ. Отправляйся в Мясопилку, перебей этих чудовищ, которые сражаются с нашими войсками, и верни части тела Олакина.','Принесите туловище Олакина, ноги Олакина, левую руку Олакина и правую руку Олакина темной всаднице Арли в Черный дозор.','Думаю, "возвращение" рыцаря – это хорошая новость, но, честно сказать, сомневаюсь, что его товарищи имели в виду именно это, когда говорили о том, что его надо вернуть. Ладно, посмотрим, что можно сделать, чтобы поставить его на ноги и завершить нашу миссию.','Вернитесь к темной всаднице Арли в Черный дозор, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Части тела',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Враги захватили рыцаря Олакина, и Серебряный Авангард лишился командующего как раз перед самой атакой на Мясопилку. Для меня-то все рыцари одинаковы, но сами они так не думают.$B$BМне не хотелось бы тратить на это время, но выбора у меня нет. Нашего благородного рыцаря, наверное, уже давно разрубили на мелкие кусочки, чтобы соорудить из них поганищ. Отправляйся в Мясопилку, перебей этих чудовищ, которые сражаются с нашими войсками, и верни части тела Олакина.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите туловище Олакина, ноги Олакина, левую руку Олакина и правую руку Олакина темной всаднице Арли в Черный дозор.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Думаю, "возвращение" рыцаря – это хорошая новость, но, честно сказать, сомневаюсь, что его товарищи имели в виду именно это, когда говорили о том, что его надо вернуть. Ладно, посмотрим, что можно сделать, чтобы поставить его на ноги и завершить нашу миссию.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к темной всаднице Арли в Черный дозор, что в Ледяной Короне.',`completedtext_loc8`);
