INSERT INTO `locales_quest` (`id`,`details_loc8`,`endtext_loc8`) VALUES (13216,'Твоя давняя соперница, Сигрид Дитя Льда, вернулась. Может, помнишь, как она уступила тебе в дуэли на Диком уступе?$B$BНеважно. Главное, что она это помнит. Она жаждет реванша.$B$BЛично я считаю, что это хорошая возможность еще раз себя показать.$B$BВ общем, решать тебе, $n. Хочешь снова встретиться с Сигрид?','Сигрид Дитя Льда побеждена.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Твоя давняя соперница, Сигрид Дитя Льда, вернулась. Может, помнишь, как она уступила тебе в дуэли на Диком уступе?$B$BНеважно. Главное, что она это помнит. Она жаждет реванша.$B$BЛично я считаю, что это хорошая возможность еще раз себя показать.$B$BВ общем, решать тебе, $n. Хочешь снова встретиться с Сигрид?',`details_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Сигрид Дитя Льда побеждена.',`endtext_loc8`);
