INSERT INTO `locales_quest` (`id`,`details_loc8`,`endtext_loc8`) VALUES (13218,'Йотунхеймский врайкул заметил твои старания, $n. Сам тан Банахогг заинтересовался тобой и захотел стать твоим следующим противником.$B$BЕсли тебе показалось, что ты едва $gодолел:одолела; Резчика-по-живому, можешь отправляться домой и забудь о битве с таном. Прозвище тана – Смертельный Удар, и я думаю, ты догадываешься, за что он его получил.$B$BТы принимаешь вызов тана?','Тан Банахогг побежден.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Йотунхеймский врайкул заметил твои старания, $n. Сам тан Банахогг заинтересовался тобой и захотел стать твоим следующим противником.$B$BЕсли тебе показалось, что ты едва $gодолел:одолела; Резчика-по-живому, можешь отправляться домой и забудь о битве с таном. Прозвище тана – Смертельный Удар, и я думаю, ты догадываешься, за что он его получил.$B$BТы принимаешь вызов тана?',`details_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Тан Банахогг побежден.',`endtext_loc8`);
