INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13220,'Воскрешение Олакина','У нас не слишком много времени на то, чтобы собрать Олакина. К счастью, Плеть приготовила отличное место, где ты сможешь провернуть эту операцию.$B$BРядом с Мясопилкой находится Святилище воскрешения. Поищи там катушку ниток и хирургический скальпель. Затем положи останки Олакина на большую плиту, находящуюся в центре святилища, и приступай к работе.','Найдите катушку ниток и хирургический скальпель, отнесите их в Святилище воскрешения к останкам Олакина и попытайтесь воскресить рыцаря. Затем вернитесь к темной всаднице Арли в Черный дозор.','Олакину крупно повезло. Никто еще не спасался из лап Плети, никто. В следующий раз ни отвага, ни крепкие нитки его не спасут. Надеюсь, он будет помнить об этом.','Ты $Gвоскресил:воскресила; нашего храброго крестоносца?','Вернитесь к темной всаднице Арли в Черный дозор, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Воскрешение Олакина',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У нас не слишком много времени на то, чтобы собрать Олакина. К счастью, Плеть приготовила отличное место, где ты сможешь провернуть эту операцию.$B$BРядом с Мясопилкой находится Святилище воскрешения. Поищи там катушку ниток и хирургический скальпель. Затем положи останки Олакина на большую плиту, находящуюся в центре святилища, и приступай к работе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите катушку ниток и хирургический скальпель, отнесите их в Святилище воскрешения к останкам Олакина и попытайтесь воскресить рыцаря. Затем вернитесь к темной всаднице Арли в Черный дозор.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Олакину крупно повезло. Никто еще не спасался из лап Плети, никто. В следующий раз ни отвага, ни крепкие нитки его не спасут. Надеюсь, он будет помнить об этом.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gвоскресил:воскресила; нашего храброго крестоносца?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к темной всаднице Арли в Черный дозор, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (13221,'Я еще жив!','Свет ко мне милостив. Я до сих пор не погиб в этом ожившем кошмаре, но если мне не удастся отсюда выбраться, приспешники Плети убьют меня, раздерут мое тело на части и используют их для своих "работ".$B$BВ одиночку мне не справиться, но с твоей помощью, дитя мое, я надеюсь спастись и повоевать еще с силами Плети.$B$BПоможешь мне выбраться, пока мясники Плети меня не нашли?','Проводите отца Камароса в безопасное место, а затем доложите обо всем Абсалану Благочестивому на борту "Усмирителя небес".','Слава Свету! Мы уже думали, что отец Камарос умер, или того хуже. Твоя смелость и самоотверженность очень помогли Серебряному Авангарду. Прими нашу благодарность.','Доставить отца Камароса в безопасное место.','Поговорите с Абсаланом Благочестивым на "Усмирителе небес", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Я еще жив!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Свет ко мне милостив. Я до сих пор не погиб в этом ожившем кошмаре, но если мне не удастся отсюда выбраться, приспешники Плети убьют меня, раздерут мое тело на части и используют их для своих "работ".$B$BВ одиночку мне не справиться, но с твоей помощью, дитя мое, я надеюсь спастись и повоевать еще с силами Плети.$B$BПоможешь мне выбраться, пока мясники Плети меня не нашли?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проводите отца Камароса в безопасное место, а затем доложите обо всем Абсалану Благочестивому на борту "Усмирителя небес".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Слава Свету! Мы уже думали, что отец Камарос умер, или того хуже. Твоя смелость и самоотверженность очень помогли Серебряному Авангарду. Прими нашу благодарность.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Доставить отца Камароса в безопасное место.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Абсаланом Благочестивым на "Усмирителе небес", что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13222,'Защита осадных машин','По приказу главного подрывника Легосо из крепости Ледяных Оков защитите осадную машину или управляйте ею, пока она не уничтожит три строения.$B$BОсадные машины могут изготавливать игроки в звании "рядовой" и выше в гоблинских мастерских.','Вернитесь к главному подрывнику Легосо на Озеро Ледяных Оков.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Защита осадных машин',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По приказу главного подрывника Легосо из крепости Ледяных Оков защитите осадную машину или управляйте ею, пока она не уничтожит три строения.$B$BОсадные машины могут изготавливать игроки в звании "рядовой" и выше в гоблинских мастерских.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к главному подрывнику Легосо на Озеро Ледяных Оков.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13223,'Защита осадных машин','Отличная работа. Жаль, Мурпа рядом не было, он бы тебе помог.','Как продвигается защита осадных машин?','Вернитесь к лейтенанту Мурпу на Озеро Ледяных Оков.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Защита осадных машин',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличная работа. Жаль, Мурпа рядом не было, он бы тебе помог.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как продвигается защита осадных машин?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лейтенанту Мурпу на Озеро Ледяных Оков.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (13224,'Молот Оргрима','Солдаты Серебряного Авангарда унесли мое истерзанное тело с поля боя на Прорванном фронте. Это была великая битва, |3-6($r). Мой топор пел, захлебываясь кровью подонков из рядов Альянса и Плети.$B$BДолго мне не протянуть, но это будет достойная смерть. Я попрошу тебя передать кое-что от меня.$B$BНаш летательный аппарат под названием "Молот Оргрима" может подняться так высоко, что силам Плети его не достать. Он где-то между Морд\'ретаром и Алдур\'таром.$B$B<Хорк тщетно пытается по-военному отдать честь.>$B$BЛети как можно выше и старайся избегать джаггернаута Альянса под названием "Усмиритель небес". Скажи Корму... скажи ему, что я умер... в бою... в бою за Орду.','Найдите покорителя небес Корма Черного Шрама. Он находится на борту "Молота Оргрима", летающего над Ледяной Короной.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Молот Оргрима',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Солдаты Серебряного Авангарда унесли мое истерзанное тело с поля боя на Прорванном фронте. Это была великая битва, |3-6($r). Мой топор пел, захлебываясь кровью подонков из рядов Альянса и Плети.$B$BДолго мне не протянуть, но это будет достойная смерть. Я попрошу тебя передать кое-что от меня.$B$BНаш летательный аппарат под названием "Молот Оргрима" может подняться так высоко, что силам Плети его не достать. Он где-то между Морд\'ретаром и Алдур\'таром.$B$B<Хорк тщетно пытается по-военному отдать честь.>$B$BЛети как можно выше и старайся избегать джаггернаута Альянса под названием "Усмиритель небес". Скажи Корму... скажи ему, что я умер... в бою... в бою за Орду.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите покорителя небес Корма Черного Шрама. Он находится на борту "Молота Оргрима", летающего над Ледяной Короной.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13225,'Мы завязли по уши, сражаясь с силами Плети и Орды. От воплей умирающих солдат звенело в ушах. Это была жестокая, беспощадная битва!$B$BВ какой-то момент тело отказалось меня слушаться. Я упал, и меня подобрали рыцари Серебряного Авангарда. Они вынесли меня с Прорванного фронта и доставили сюда. Едва ли я выживу. Ты исполнишь волю умирающего солдата, |3-6($r)? "Усмиритель небес" летает высоко над Ледяной Короной. Там ты и найдешь нашего командира старшего капитана Бартлетта. Скажи ему, что я умер, сражаясь за Альянс.','Найдите старшего капитана Джастина Бартлетта. Он находится на борту "Усмирителя небес", патрулирующего Ледяную Корону.','<Капитан Бартлетт отдает честь.>$B$BОн был чертовски бравым солдатом. Будь проклята Орда и будь проклята Плеть!') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы завязли по уши, сражаясь с силами Плети и Орды. От воплей умирающих солдат звенело в ушах. Это была жестокая, беспощадная битва!$B$BВ какой-то момент тело отказалось меня слушаться. Я упал, и меня подобрали рыцари Серебряного Авангарда. Они вынесли меня с Прорванного фронта и доставили сюда. Едва ли я выживу. Ты исполнишь волю умирающего солдата, |3-6($r)? "Усмиритель небес" летает высоко над Ледяной Короной. Там ты и найдешь нашего командира старшего капитана Бартлетта. Скажи ему, что я умер, сражаясь за Альянс.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите старшего капитана Джастина Бартлетта. Он находится на борту "Усмирителя небес", патрулирующего Ледяную Корону.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Капитан Бартлетт отдает честь.>$B$BОн был чертовски бравым солдатом. Будь проклята Орда и будь проклята Плеть!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13226,'И пришел Судный День!','Мы не можем одолеть короля-лича порознь. Если мы не объединимся, то поражения не миновать!$B$BУслышь мой призыв, $gбрат:сестра;! Серебряный Авангард примет любую помощь! Сам верховный лорд Тирион Фордринг ждет тебя на Серебряном аванпосте! Отправляйся в юго-восточную часть Ледяной Короны, там ты и найдешь лорда Фордринга и солдат Серебряного Авангарда.$B$BНе медли, |3-6($c), ибо Судный День настает!','Отправляйтесь к верховному лорду Тириону Фордрингу в Оплот Серебряного Авангарда в Ледяной Короне.','Мои верные рыцари послужили мне на славу. Похоже, они нашли мне настоящего героя!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','И пришел Судный День!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы не можем одолеть короля-лича порознь. Если мы не объединимся, то поражения не миновать!$B$BУслышь мой призыв, $gбрат:сестра;! Серебряный Авангард примет любую помощь! Сам верховный лорд Тирион Фордринг ждет тебя на Серебряном аванпосте! Отправляйся в юго-восточную часть Ледяной Короны, там ты и найдешь лорда Фордринга и солдат Серебряного Авангарда.$B$BНе медли, |3-6($c), ибо Судный День настает!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь к верховному лорду Тириону Фордрингу в Оплот Серебряного Авангарда в Ледяной Короне.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мои верные рыцари послужили мне на славу. Похоже, они нашли мне настоящего героя!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13227,'И пришел Судный День!','Мы не можем одолеть короля-лича порознь. Если мы не объединимся, то поражения не миновать!$B$BУслышь мой призыв, $gбрат:сестра;! Серебряный Авангард примет любую помощь! Сам верховный лорд Тирион Фордринг ждет тебя на Серебряном аванпосте! Отправляйся в юго-восточную часть Ледяной Короны, там ты и найдешь лорда Фордринга и солдат Серебряного Авангарда.$B$BНе медли, |3-6($c), ибо Судный День настает!','Отправляйтесь к верховному лорду Тириону Фордрингу в Оплот Серебряного Авангарда в Ледяной Короне.','Мои верные рыцари послужили мне на славу. Похоже, они нашли мне настоящего героя!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','И пришел Судный День!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы не можем одолеть короля-лича порознь. Если мы не объединимся, то поражения не миновать!$B$BУслышь мой призыв, $gбрат:сестра;! Серебряный Авангард примет любую помощь! Сам верховный лорд Тирион Фордринг ждет тебя на Серебряном аванпосте! Отправляйся в юго-восточную часть Ледяной Короны, там ты и найдешь лорда Фордринга и солдат Серебряного Авангарда.$B$BНе медли, |3-6($c), ибо Судный День настает!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь к верховному лорду Тириону Фордрингу в Оплот Серебряного Авангарда в Ледяной Короне.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мои верные рыцари послужили мне на славу. Похоже, они нашли мне настоящего героя!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13228,'Прорванный фронт','Бой? Какой еще бой?! Эти полки производили разведку!$b$bА что там было про Альянс? Ты вообще $gуверен:уверена;, что он что-то говорил об Альянсе?$b$bПослушай-ка, $n! Мне надо знать, что происходит, причем прямо СЕЙЧАС!$b$bИди и без ответов не возвращайся. Прочеши поля боя – найди выживших, найди следы, хоть что-то найди!','По заданию Корма Черного Шрама с "Молота Оргрима" отправляйтесь к Прорванному фронту и, поговорив с умирающим берсерком, узнайте, что там произошло.','Ну, $N?$B$BУ тебя есть новая информация для меня?','Вернитесь к покорителю небес Корму Черному Шраму на "Молот Оргрима", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прорванный фронт',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Бой? Какой еще бой?! Эти полки производили разведку!$b$bА что там было про Альянс? Ты вообще $gуверен:уверена;, что он что-то говорил об Альянсе?$b$bПослушай-ка, $n! Мне надо знать, что происходит, причем прямо СЕЙЧАС!$b$bИди и без ответов не возвращайся. Прочеши поля боя – найди выживших, найди следы, хоть что-то найди!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По заданию Корма Черного Шрама с "Молота Оргрима" отправляйтесь к Прорванному фронту и, поговорив с умирающим берсерком, узнайте, что там произошло.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, $N?$B$BУ тебя есть новая информация для меня?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к покорителю небес Корму Черному Шраму на "Молот Оргрима", что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (13229,'Я еще жив!','Проводите отца Камароса в безопасное место, а затем доложите обо всем брату Кельтану на борту "Молота Оргрима".','Ты все $Gсделал:сделала; правильно. Мы боялись, что отец Камарос погиб. Твоя храбрость станет примером для всех, кто сражается с силами Плети.','Проводить отца Камароса в безопасное место','Поговорите с братом Келтаном на "Молоте Оргрима", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Я еще жив!',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проводите отца Камароса в безопасное место, а затем доложите обо всем брату Кельтану на борту "Молота Оргрима".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты все $Gсделал:сделала; правильно. Мы боялись, что отец Камарос погиб. Твоя храбрость станет примером для всех, кто сражается с силами Плети.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Проводить отца Камароса в безопасное место',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с братом Келтаном на "Молоте Оргрима", что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13230,'Отомсти за меня!','Я слышу их, $gбрат:сестра;...$b$bСтоны раненых воинов Альянса... как будто они насмехаются надо мной...$b$bЗакончи то, что мы начали, |3-6($c). Беспощадно, не зная жалости... никто не должен остаться в живых.$b$bРади... Орды...','Добейте 5 умирающих солдат у Прорванного фронта по просьбе умирающего берсерка. Об исполнении доложите покорителю небес Корму Черному Шраму на борту "Молота Оргрима".','Рад встрече, |3-6($C). Я знал, что ты все равно вернешься, несмотря на мое предупреждение, но ты хотя бы $послушал:послушала; меня и не стала подвергать риску кого-то еще. Что не может не радовать.\n\nПочему ты вернулась ко мне?','Вернитесь к покорителю небес Корму Черному Шраму на "Молот Оргрима", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отомсти за меня!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я слышу их, $gбрат:сестра;...$b$bСтоны раненых воинов Альянса... как будто они насмехаются надо мной...$b$bЗакончи то, что мы начали, |3-6($c). Беспощадно, не зная жалости... никто не должен остаться в живых.$b$bРади... Орды...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добейте 5 умирающих солдат у Прорванного фронта по просьбе умирающего берсерка. Об исполнении доложите покорителю небес Корму Черному Шраму на борту "Молота Оргрима".',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Рад встрече, |3-6($C). Я знал, что ты все равно вернешься, несмотря на мое предупреждение, но ты хотя бы $послушал:послушала; меня и не стала подвергать риску кого-то еще. Что не может не радовать.\n\nПочему ты вернулась ко мне?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к покорителю небес Корму Черному Шраму на "Молот Оргрима", что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13231,'Прорванный фронт','Что?! Нееет! Только не это!$B$BМы же как только ни изощрялись, чтобы сохранить операцию в тайне! Как в Орде про нее узнали?! Ресурсы... живая сила... все пропало? Немыслимо!$B$BВсе наши планы здесь, в Ледяной Короне, основывались на том, что мы захватим ворота раньше Орды. Нужно срочно перегруппироваться и готовить новый штурм.$B$BОтправляйся на поле боя и разыщи уцелевших. Расспроси их, как все было. Возможно, эта трагедия нас кое-чему научит.$B$BИ приготовься к войне на два фронта, $n...','Отправляйтесь на Прорванный фронт и расспросите умирающего солдата, после чего возвращайтесь к старшему капитану Джастину Бартлетту на борт "Усмирителя небес".','Ну, $N?$B$BЧто ты $Gузнал:узнала;?','Вернитесь к старшему капитану Джастину Бартлетту на "Усмиритель небес", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прорванный фронт',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что?! Нееет! Только не это!$B$BМы же как только ни изощрялись, чтобы сохранить операцию в тайне! Как в Орде про нее узнали?! Ресурсы... живая сила... все пропало? Немыслимо!$B$BВсе наши планы здесь, в Ледяной Короне, основывались на том, что мы захватим ворота раньше Орды. Нужно срочно перегруппироваться и готовить новый штурм.$B$BОтправляйся на поле боя и разыщи уцелевших. Расспроси их, как все было. Возможно, эта трагедия нас кое-чему научит.$B$BИ приготовься к войне на два фронта, $n...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь на Прорванный фронт и расспросите умирающего солдата, после чего возвращайтесь к старшему капитану Джастину Бартлетту на борт "Усмирителя небес".',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, $N?$B$BЧто ты $Gузнал:узнала;?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старшему капитану Джастину Бартлетту на "Усмиритель небес", что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13232,'Прикончи меня!','Они смеются над нами... даже умирая, они смеются... $b$bПрошу тебя, $gбрат:милая;... Не допусти, чтобы их издевательский смех стал последним, что я слышу в жизни... $b$bПрикончи меня... избавь от мучений... отправь меня... к Свету.$b$bРазыщи моих умирающих товарищей... добей и их тоже... из милосердия.$b$bЧтобы никто из нас не достался Плети!$b$bПрошу тебя...','По просьбе умирающего солдата добейте 5 умирающих солдат у Прорванного фронта и доложите об исполнении старшему капитану Джастину Бартлетту на борту "Усмирителя небес".','Что это, $C?','Вернитесь к старшему капитану Джастину Бартлетту на "Усмиритель небес", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прикончи меня!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Они смеются над нами... даже умирая, они смеются... $b$bПрошу тебя, $gбрат:милая;... Не допусти, чтобы их издевательский смех стал последним, что я слышу в жизни... $b$bПрикончи меня... избавь от мучений... отправь меня... к Свету.$b$bРазыщи моих умирающих товарищей... добей и их тоже... из милосердия.$b$bЧтобы никто из нас не достался Плети!$b$bПрошу тебя...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По просьбе умирающего солдата добейте 5 умирающих солдат у Прорванного фронта и доложите об исполнении старшему капитану Джастину Бартлетту на борту "Усмирителя небес".',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что это, $C?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старшему капитану Джастину Бартлетту на "Усмиритель небес", что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13233,'Пощады не будет!','Я говорил серьезно, это не было приступом гнева.$b$bСнова и снова Орда выказывает свое пренебрежение ко всему, что для нас дорого и свято. За преступления против Света они должны заплатить своей жизнью!$b$bВсе они.$b$bТолько представь, насколько светлее станет мир без этих мерзавцев, $n. Насколько легче будет жить нашим потомкам и как глубоко они будут чтить нашу память, зная, что именно нам они обязаны своим спокойствием и счастьем.$b$bА теперь иди, и пусть мечты станут реальностью!','По заданию старшего капитана Джастина Бартлетта с борта "Усмирителя Небес" убейте 15 игроков, сражающихся на стороне Орды в Ледяной Короне.','Превосходно, $N.$B$BУвидишь врага – догони его и расплатись с ним за все!','Я верю, что ты $Gзапятнал:запятнала; снег кровью наших врагов, $N.','Вернитесь к старшему капитану Джастину Бартлетту на "Усмиритель небес", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пощады не будет!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я говорил серьезно, это не было приступом гнева.$b$bСнова и снова Орда выказывает свое пренебрежение ко всему, что для нас дорого и свято. За преступления против Света они должны заплатить своей жизнью!$b$bВсе они.$b$bТолько представь, насколько светлее станет мир без этих мерзавцев, $n. Насколько легче будет жить нашим потомкам и как глубоко они будут чтить нашу память, зная, что именно нам они обязаны своим спокойствием и счастьем.$b$bА теперь иди, и пусть мечты станут реальностью!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По заданию старшего капитана Джастина Бартлетта с борта "Усмирителя Небес" убейте 15 игроков, сражающихся на стороне Орды в Ледяной Короне.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Превосходно, $N.$B$BУвидишь врага – догони его и расплатись с ним за все!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я верю, что ты $Gзапятнал:запятнала; снег кровью наших врагов, $N.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старшему капитану Джастину Бартлетту на "Усмиритель небес", что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13234,'Они заплатят!','Время пришло!$b$bМы слишком долго терпели этих самодовольных болванов из Альянса! Слишком долго мы сдерживали свое желание очистить мир от отчаявшихся и слабых.$b$bИ теперь мы положим конец нашему унижению! Мы им покажем, что значит страх! Мы принесем честь и славу Орде!$b$bЗдесь, в Ледяной Короне, мы разобьем Альянс!$b$bСтупай, |3-6($c). Выслеживай их. Сломи. Отними у них волю к жизни!','Убейте 15 игроков Альянса в Ледяной Короне по поручению покорителя небес Корма Черного Шрама.','Молодец, |3-6($C).\n\nОчень скоро Альянс будет дрожать от страха при одном только упоминании твоего имени, а в Орде будут славить тебя, как бесстрашную воительницу!','Итак, |3-6($R)?\n\nКаковы твои выводы?','Вернитесь к покорителю небес Корму Черному Шраму на "Молот Оргрима", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Они заплатят!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Время пришло!$b$bМы слишком долго терпели этих самодовольных болванов из Альянса! Слишком долго мы сдерживали свое желание очистить мир от отчаявшихся и слабых.$b$bИ теперь мы положим конец нашему унижению! Мы им покажем, что значит страх! Мы принесем честь и славу Орде!$b$bЗдесь, в Ледяной Короне, мы разобьем Альянс!$b$bСтупай, |3-6($c). Выслеживай их. Сломи. Отними у них волю к жизни!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 15 игроков Альянса в Ледяной Короне по поручению покорителя небес Корма Черного Шрама.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Молодец, |3-6($C).\n\nОчень скоро Альянс будет дрожать от страха при одном только упоминании твоего имени, а в Орде будут славить тебя, как бесстрашную воительницу!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Итак, |3-6($R)?\n\nКаковы твои выводы?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к покорителю небес Корму Черному Шраму на "Молот Оргрима", что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13235,'Победитель мясистого великана','Теперь, когда мы уничтожили этого мясистого великана, Король-лич поймет, что остальные его войска тоже не неуязвимы. Говорят, что Король-лич не знает, что значит страх, но с твоей помощью мы напомним ему, что это такое.','Ты $Gприкончил:прикончила; великана?','Вернитесь к темной всаднице Арли в Черный дозор, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Победитель мясистого великана',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь, когда мы уничтожили этого мясистого великана, Король-лич поймет, что остальные его войска тоже не неуязвимы. Говорят, что Король-лич не знает, что значит страх, но с твоей помощью мы напомним ему, что это такое.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gприкончил:прикончила; великана?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к темной всаднице Арли в Черный дозор, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13236,'Войско проклятых','Может, ты считаешь себя очень $gсильным:сильной;, раз $gсмог:смогла; победить нежить?$B$BА ты знаешь, скольких трудов стоило их создание?$B$BЯ видел, как принц лично создавал солдат нежити. Если хочешь, могу и тебе показать.','По заданию Матиаса Нетлера из Лагеря сопротивления первого легиона создайте армию из 100 вурдалаков-прислужников.','Ты $Gвидел:видела;, $N?','Вернитесь к Матиасу Нетлеру в Долину Потерянной Надежды, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Войско проклятых',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Может, ты считаешь себя очень $gсильным:сильной;, раз $gсмог:смогла; победить нежить?$B$BА ты знаешь, скольких трудов стоило их создание?$B$BЯ видел, как принц лично создавал солдат нежити. Если хочешь, могу и тебе показать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По заданию Матиаса Нетлера из Лагеря сопротивления первого легиона создайте армию из 100 вурдалаков-прислужников.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gвидел:видела;, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Матиасу Нетлеру в Долину Потерянной Надежды, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13237,'Тычки и тумаки','Пока ваш командир отвлекся на врагов из Альянса, мы можем сосредоточиться на основных противниках: Короле-личе и его прислужниках.$b$bЕсли мы еще надеемся взять цитадель, надо, чтобы твои люди контролировали каждые ворота.$b$bТак, будем действовать постепенно. Для начала вернись на поля боя и прорви оборону врага. Узнай, какие у них есть слабые стороны.$b$bЯ жду твоего доклада, |3-6($c).','По поручению Кольтиры Ткача Смерти, находящегося на борту "Молота Оргрима", вы должны отправиться на Прорванный фронт и уничтожить 5 неповоротливых поганищ, 5 злокозненных некромантов и 5 адептов Тьмы.','Правда-правда, $C?\n\nТебе нечего мне рассказать? Совсем?\n\n<Кольтира замечает ошметки поганищ, прилипшие к вашей одежде, и начинает улыбаться.>\n\nПозволю себе тебе не поверить...','Ну, $R?$B$BЧто ты $Gузнал:узнала;?','Вернитесь к Кольтире Ткачу Смерти на "Молот Оргрима", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тычки и тумаки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пока ваш командир отвлекся на врагов из Альянса, мы можем сосредоточиться на основных противниках: Короле-личе и его прислужниках.$b$bЕсли мы еще надеемся взять цитадель, надо, чтобы твои люди контролировали каждые ворота.$b$bТак, будем действовать постепенно. Для начала вернись на поля боя и прорви оборону врага. Узнай, какие у них есть слабые стороны.$b$bЯ жду твоего доклада, |3-6($c).',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По поручению Кольтиры Ткача Смерти, находящегося на борту "Молота Оргрима", вы должны отправиться на Прорванный фронт и уничтожить 5 неповоротливых поганищ, 5 злокозненных некромантов и 5 адептов Тьмы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Правда-правда, $C?\n\nТебе нечего мне рассказать? Совсем?\n\n<Кольтира замечает ошметки поганищ, прилипшие к вашей одежде, и начинает улыбаться.>\n\nПозволю себе тебе не поверить...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, $R?$B$BЧто ты $Gузнал:узнала;?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кольтире Ткачу Смерти на "Молот Оргрима", что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (13238,'Какая-то полезная штука','Поговорите с главным инженером Меднопалом на борту "Молота Оргрима" по поручению покорителя небес Корма Черного Шрама.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Какая-то полезная штука',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с главным инженером Меднопалом на борту "Молота Оргрима" по поручению покорителя небес Корма Черного Шрама.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13239,'Непостоянство','Даже не знаю, с чего начать... ну, ты, наверное, знаешь, что будучи главным инженером этого корабля, я имею неограниченный доступ ко всем данным разведки – да, это правда, и меня очень заинтересовали эти ледяные змеи, которых ты $gвидел:видела; на юге. Кажется, я придумал, как нам их изничтожить... но мне понадобится твоя помощь. Сооруди манекен из доспехов, обрызгай его этим раствором и сразу беги в укрытие!$b$b...Эй, ты еще здесь, |3-6($r)?','Отправляйтесь к Прорванному фронту и воспользуйтесь летучим маслом Меднопала, чтобы привлечь 3 ледяных небесных когтей.$b$bДля того чтобы использовать масло, соберите на поле сражения груду костей, брошенный шлем и брошенный доспех.','Ничего себе! Даже отсюда мне было видно, как они загорелись! В общем, эксперимент удался. Я отмечаю очередной успех и начинаю разливать раствор по бутылкам – в плане подготовки к вторжению. Скорее всего, нам понадобится провести еще несколько испытаний. И мы их проведем! Ну, то есть, если тебе интересно...','Получилось, $C?','Вернитесь к главному инженеру Меднопалу на "Молот Оргрима", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Непостоянство',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Даже не знаю, с чего начать... ну, ты, наверное, знаешь, что будучи главным инженером этого корабля, я имею неограниченный доступ ко всем данным разведки – да, это правда, и меня очень заинтересовали эти ледяные змеи, которых ты $gвидел:видела; на юге. Кажется, я придумал, как нам их изничтожить... но мне понадобится твоя помощь. Сооруди манекен из доспехов, обрызгай его этим раствором и сразу беги в укрытие!$b$b...Эй, ты еще здесь, |3-6($r)?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь к Прорванному фронту и воспользуйтесь летучим маслом Меднопала, чтобы привлечь 3 ледяных небесных когтей.$b$bДля того чтобы использовать масло, соберите на поле сражения груду костей, брошенный шлем и брошенный доспех.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ничего себе! Даже отсюда мне было видно, как они загорелись! В общем, эксперимент удался. Я отмечаю очередной успех и начинаю разливать раствор по бутылкам – в плане подготовки к вторжению. Скорее всего, нам понадобится провести еще несколько испытаний. И мы их проведем! Ну, то есть, если тебе интересно...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Получилось, $C?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к главному инженеру Меднопалу на "Молот Оргрима", что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13240,'Времиар превидит встречу с центрифужными созданиями!','Ты $gдолжен:должна; отправиться в Окулус, дрейфующий над Хладаррой, $n.$B$BУ меня было видение, в котором ты уничтожаешь находящихся там центрифужных созданий. Уверяю тебя, если ты не нападешь $gпервым:первой; на эти магические создания, они уничтожат тебя и твоих друзей.$B$BТаким мне явилось будущее – и ты $gдолжен:должна; прислушаться к моему предчувствию.','Исполните волю верховного мага Времиара, обитающего в Даларане, которого посетило видение, где вы уничтожаете 10 центрифужных созданий.','<Архимаг кивает, даже не сказав ни слова.>$B$BЯ знаю. Вы уничтожили конструкции, как я и предполагал, и затем смогли продолжить бой с Варосом Заоблачным.$B$BОтлично, $N!','Я чувствую ,что тебе ещё предстоит уничтожить все конструкции.','Вернитесь к верховному магу Времиару в Лес Хрустальной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Времиар превидит встречу с центрифужными созданиями!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gдолжен:должна; отправиться в Окулус, дрейфующий над Хладаррой, $n.$B$BУ меня было видение, в котором ты уничтожаешь находящихся там центрифужных созданий. Уверяю тебя, если ты не нападешь $gпервым:первой; на эти магические создания, они уничтожат тебя и твоих друзей.$B$BТаким мне явилось будущее – и ты $gдолжен:должна; прислушаться к моему предчувствию.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Исполните волю верховного мага Времиара, обитающего в Даларане, которого посетило видение, где вы уничтожаете 10 центрифужных созданий.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Архимаг кивает, даже не сказав ни слова.>$B$BЯ знаю. Вы уничтожили конструкции, как я и предполагал, и затем смогли продолжить бой с Варосом Заоблачным.$B$BОтлично, $N!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я чувствую ,что тебе ещё предстоит уничтожить все конструкции.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному магу Времиару в Лес Хрустальной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13241,'Времиар превидит встречу имирьярскими берсерками!','Могучие воины короля Имирона в ближайшем будущем встанут на твоем пути к успеху! $B$BТебе следует отправиться в крепость, известную как Вершина Утгард, находящуюся в глубине лесов Ревущего фьорда. Трудно описать, насколько важная задача стоит перед тобой и твоими друзьями. Вы должны уничтожить имирьярских берсерков, вершащих там злые дела.$B$BЕсли вас постигнет неудача, смерть станет вашим наказанием, $n!','Уничтожьте по заданию верховного мага Времиара, обитающего в Даларане, 7 имирьярских берсерков.','<Архимаг прижимает пальцы к вискам и концентрируется.>$B$BБерсерки еще не убиты. Обрати внимание на мое предупреждение, $N. Ты $Gдолжен:должна; сделать это!','Вернитесь к верховному магу Времиару в Лес Хрустальной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Времиар превидит встречу имирьярскими берсерками!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Могучие воины короля Имирона в ближайшем будущем встанут на твоем пути к успеху! $B$BТебе следует отправиться в крепость, известную как Вершина Утгард, находящуюся в глубине лесов Ревущего фьорда. Трудно описать, насколько важная задача стоит перед тобой и твоими друзьями. Вы должны уничтожить имирьярских берсерков, вершащих там злые дела.$B$BЕсли вас постигнет неудача, смерть станет вашим наказанием, $n!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте по заданию верховного мага Времиара, обитающего в Даларане, 7 имирьярских берсерков.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Архимаг прижимает пальцы к вискам и концентрируется.>$B$BБерсерки еще не убиты. Обрати внимание на мое предупреждение, $N. Ты $Gдолжен:должна; сделать это!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному магу Времиару в Лес Хрустальной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13242,'Шевеление Тьмы','Тьма зашевелилась, $n. Произошло трагическое событие, которое никто, кроме Вневременного, не мог предвидеть. Скоро твой народ охватит злоба и ненависть. Приближается война.$B$BКрасные драконы сделали все, что было в их силах. Теперь все зависит от смертных рас Азерота.$B$BУвы, твое путешествие начинается со страданий. Сегодня отец потерял свое дитя. Тебе предстоит стать вестником, приносящим скорбные новости. Собери вооружение Саурфанга и отнеси его Саурфангу-старшему.','Соберите на поле боя боевые доспехи Саурфанга и верните их верховному правителю Саурфангу в крепость Песни Войны, что в Борейской тундре.','<Гримаса боли искажает лицо Саурфанга.>\n\nМое сердце…моя сила...','Вернитесь к верховному правителю Саурфангу в Крепость Песни Войны, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Шевеление Тьмы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тьма зашевелилась, $n. Произошло трагическое событие, которое никто, кроме Вневременного, не мог предвидеть. Скоро твой народ охватит злоба и ненависть. Приближается война.$B$BКрасные драконы сделали все, что было в их силах. Теперь все зависит от смертных рас Азерота.$B$BУвы, твое путешествие начинается со страданий. Сегодня отец потерял свое дитя. Тебе предстоит стать вестником, приносящим скорбные новости. Собери вооружение Саурфанга и отнеси его Саурфангу-старшему.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите на поле боя боевые доспехи Саурфанга и верните их верховному правителю Саурфангу в крепость Песни Войны, что в Борейской тундре.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Гримаса боли искажает лицо Саурфанга.>\n\nМое сердце…моя сила...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному правителю Саурфангу в Крепость Песни Войны, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13243,'Времиар превидит встречу с посланницами из рода Бесконечности!','Драконы бесконечности угрожают существованию самого времени. Если ты не помешаешь им, ход времени будет искривлен!$B$BТы $gдолжен:должна; отправиться в Пещеры Времени и переместиться в прошлое, в период, известный нам как Очищение Стратхольма.$B$BУ меня начинает раскалываться голова даже от попыток просмотреть все вариации прошлого, но я точно знаю, как жизненно важно тебе уничтожить посланниц из рода Бесконечности.$B$BЛишь когда они будут убиты, истинное прошлое будет сохранено, а настоящее и будущее никогда больше не подвергнутся угрозе изменения!','Верховный маг Времиар из Даларана предчувствует, что вам необходимо убить 4 посланниц из рода Бесконечности.','Мы должны использовать ошибку Мал\'Ганиса. Не каждый день мы получаем такой шанс.\n\nЕсли мы сможем изучить этот артефакт, может быть, мы лучше станем понимать натрезимов!','Вернитесь к верховному магу Времиару в Лес Хрустальной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Времиар превидит встречу с посланницами из рода Бесконечности!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Драконы бесконечности угрожают существованию самого времени. Если ты не помешаешь им, ход времени будет искривлен!$B$BТы $gдолжен:должна; отправиться в Пещеры Времени и переместиться в прошлое, в период, известный нам как Очищение Стратхольма.$B$BУ меня начинает раскалываться голова даже от попыток просмотреть все вариации прошлого, но я точно знаю, как жизненно важно тебе уничтожить посланниц из рода Бесконечности.$B$BЛишь когда они будут убиты, истинное прошлое будет сохранено, а настоящее и будущее никогда больше не подвергнутся угрозе изменения!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верховный маг Времиар из Даларана предчувствует, что вам необходимо убить 4 посланниц из рода Бесконечности.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мы должны использовать ошибку Мал\'Ганиса. Не каждый день мы получаем такой шанс.\n\nЕсли мы сможем изучить этот артефакт, может быть, мы лучше станем понимать натрезимов!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному магу Времиару в Лес Хрустальной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13244,'Времиар превидит встречу с титановыми воинами!','Опасность нависла над всем Азеротом. Безумный бог Локен действительно в силах уничтожить все живое!$B$BВ Земной сторожевой башне, что в Чертогах Молний, лучшие титановые воины пытаются исполнить смертоносную волю Локена, грозящую погубить неисчислимое количество жизней.$B$BЯ видел будущее, $n. Ты станешь $gтем:той;, кто не допустит, чтобы это произошло!','Убейте 7 титановых воинов, дабы предсказанное верховным магом Времиаром из Даларана сбылось.','Мы все у тебя в долгу, $N.$B$BЕсли я в чем-то уверен, так это в том, что ты не $Gподвел:подвела; нас и не подведешь в будущем!','Даже я не могу понять, почему мы стоим здесь и говорим, когда тебе еще предстоит устранить угрозу титановых авангардов.','Вернитесь к верховному магу Времиару в Лес Хрустальной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Времиар превидит встречу с титановыми воинами!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Опасность нависла над всем Азеротом. Безумный бог Локен действительно в силах уничтожить все живое!$B$BВ Земной сторожевой башне, что в Чертогах Молний, лучшие титановые воины пытаются исполнить смертоносную волю Локена, грозящую погубить неисчислимое количество жизней.$B$BЯ видел будущее, $n. Ты станешь $gтем:той;, кто не допустит, чтобы это произошло!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 7 титановых воинов, дабы предсказанное верховным магом Времиаром из Даларана сбылось.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мы все у тебя в долгу, $N.$B$BЕсли я в чем-то уверен, так это в том, что ты не $Gподвел:подвела; нас и не подведешь в будущем!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Даже я не могу понять, почему мы стоим здесь и говорим, когда тебе еще предстоит устранить угрозу титановых авангардов.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному магу Времиару в Лес Хрустальной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13245,'Победный трофей: Ингвар Расхититель','Я хочу, чтобы ты $gсобрал:собрала; группу и $gотправился:отправилась; в крепость Утгард. Там тебе предстоит найти и уничтожить Ингвара Расхитителя – прежде, чем он поведет свои войска врайкулов в атаку на ближайшие города Альянса и Орды.$B$BМне потребуется его секира в качестве доказательства того, что с ним покончено. Дело не в том, что я тебе не доверяю. Просто разумно было бы на моем месте убедиться в том, что дело сделано.','Принесите секиру Расхитителя верховному магу Лан\'далоку, обитающему в Даларане.$B$BЭто задание выполняется в героическом режиме.','Хорошо. Прислони секиру к стене.\n\nЯ уверен, что Валгард и Лагерь Возмездия сегодня будут спать более спокойно, зная, что с этим злодеем благодаря тебе наконец-то покончено.','У тебя есть топор? Ингвар мертв?','Вернитесь к верховному магу Лан\'далоку в Опустевшие леса, что в Лесу Хрустальной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Победный трофей: Ингвар Расхититель',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я хочу, чтобы ты $gсобрал:собрала; группу и $gотправился:отправилась; в крепость Утгард. Там тебе предстоит найти и уничтожить Ингвара Расхитителя – прежде, чем он поведет свои войска врайкулов в атаку на ближайшие города Альянса и Орды.$B$BМне потребуется его секира в качестве доказательства того, что с ним покончено. Дело не в том, что я тебе не доверяю. Просто разумно было бы на моем месте убедиться в том, что дело сделано.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите секиру Расхитителя верховному магу Лан\'далоку, обитающему в Даларане.$B$BЭто задание выполняется в героическом режиме.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо. Прислони секиру к стене.\n\nЯ уверен, что Валгард и Лагерь Возмездия сегодня будут спать более спокойно, зная, что с этим злодеем благодаря тебе наконец-то покончено.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У тебя есть топор? Ингвар мертв?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному магу Лан\'далоку в Опустевшие леса, что в Лесу Хрустальной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13246,'Победный трофей: Керистраза','Известна ли тебе история Керистразы?$B$BКак она помогла убить Сарагосу, супругу Малигоса? Как затем он завладел Керистразой и заморозил ее в глыбе льда?$B$BМы узнали, что он использовал свою магию, чтобы сломить ее волю. Это свело ее с ума.$B$B$n, ты $gдолжен:должна; отправиться в Нексус, что в Хладарре, и уничтожить ее, прежде, чем она окончательно обезумеет.$B$BЭто печалит меня, но я настаиваю, чтобы ты $gпринес:принесла; мне ее сердце в качестве доказательства того, что ее больше нет.','Принесите в Даларан по заданию кровавого верховного мага Лан\'далока разбитое сердце Керистразы.$B$BЭто задание выполняется в героическом режиме.','Увы, это было необходимо.\n\nОрден Кирин-Тор не мог позволить столь видной представительнице красных драконов пасть жертвой нашего величайшего врага. Если бы Малигос начал использовать ее в Войне Нексуса, настал бы конец всему.\n\nНо я горюю о том, что не могли мы спасти ее.','Если бы нам был известен способ, как исцелить ее, мы бы не просили тебя ее убить.\n\nНо мы знаем, насколько сильна стала власть Малигоса над магией. После его манипуляций с силовыми линиями Азерота он стал непревзойденным мастером тайной магии.','Вернитесь к верховному магу Лан\'далоку в Опустевшие леса, что в Лесу Хрустальной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Победный трофей: Керистраза',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Известна ли тебе история Керистразы?$B$BКак она помогла убить Сарагосу, супругу Малигоса? Как затем он завладел Керистразой и заморозил ее в глыбе льда?$B$BМы узнали, что он использовал свою магию, чтобы сломить ее волю. Это свело ее с ума.$B$B$n, ты $gдолжен:должна; отправиться в Нексус, что в Хладарре, и уничтожить ее, прежде, чем она окончательно обезумеет.$B$BЭто печалит меня, но я настаиваю, чтобы ты $gпринес:принесла; мне ее сердце в качестве доказательства того, что ее больше нет.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите в Даларан по заданию кровавого верховного мага Лан\'далока разбитое сердце Керистразы.$B$BЭто задание выполняется в героическом режиме.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Увы, это было необходимо.\n\nОрден Кирин-Тор не мог позволить столь видной представительнице красных драконов пасть жертвой нашего величайшего врага. Если бы Малигос начал использовать ее в Войне Нексуса, настал бы конец всему.\n\nНо я горюю о том, что не могли мы спасти ее.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если бы нам был известен способ, как исцелить ее, мы бы не просили тебя ее убить.\n\nНо мы знаем, насколько сильна стала власть Малигоса над магией. После его манипуляций с силовыми линиями Азерота он стал непревзойденным мастером тайной магии.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному магу Лан\'далоку в Опустевшие леса, что в Лесу Хрустальной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13247,'Победный трофей: хранитель энергии Эрегос','Война Нексуса продолжает бушевать, $n, и нам нужно что-то предпринять, чтобы изменить ход событий! Хочешь ли ты отправиться в сердце битвы?$B$BХранитель энергии Эрегос охраняет канал, по которому Малигос выкачивает магию из силовых линий Азерота. Если мы сможем уничтожить его, это нанесет сильный удар по нашему врагу.$B$BПожалуйста, принеси мне одно из его устройств для настройки силовых линий, чтобы мы смогли изучить его.','Принесите устройство для настройки силовых линий верховному магу Лан\'далоку в Даларан.$B$BЭто задание выполняется в героическом режиме.','Спасибо, $N. Изучение этого устройства должно дать нам понимание того, как Малигос управляет силовыми линиями.$B$BЕсли мы сможем найти его слабое место, мы сможем использовать это и переломить ход событий.','Мне не нужно напоминать тебе, что Малигос пытается остановить использование всей магии в мире и что стая синих драконов убивает любого, кто знает, как им владеть.','Вернитесь к верховному магу Лан\'далоку в Опустевшие леса, что в Лесу Хрустальной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Победный трофей: хранитель энергии Эрегос',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Война Нексуса продолжает бушевать, $n, и нам нужно что-то предпринять, чтобы изменить ход событий! Хочешь ли ты отправиться в сердце битвы?$B$BХранитель энергии Эрегос охраняет канал, по которому Малигос выкачивает магию из силовых линий Азерота. Если мы сможем уничтожить его, это нанесет сильный удар по нашему врагу.$B$BПожалуйста, принеси мне одно из его устройств для настройки силовых линий, чтобы мы смогли изучить его.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите устройство для настройки силовых линий верховному магу Лан\'далоку в Даларан.$B$BЭто задание выполняется в героическом режиме.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо, $N. Изучение этого устройства должно дать нам понимание того, как Малигос управляет силовыми линиями.$B$BЕсли мы сможем найти его слабое место, мы сможем использовать это и переломить ход событий.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мне не нужно напоминать тебе, что Малигос пытается остановить использование всей магии в мире и что стая синих драконов убивает любого, кто знает, как им владеть.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному магу Лан\'далоку в Опустевшие леса, что в Лесу Хрустальной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13248,'Победный трофей: король Имирон','Король Имирон с вершины Утгарда пребывает в милости у Короля-лича. Одной этой причины было бы достаточно для того, чтобы покончить с ним.$B$BНо если он протрубит в рог и созовет всех вождей племен, подобных имирьярам и мьординам, врайкулы станут силой куда более мощной, чем прочие армии Плети!$B$BТы, $n, $gдолжен:должна; сделать так, чтобы этого никогда не произошло. Принеси мне медальон с его шеи, чтобы я знал, что Имирон больше не представляет для нас угрозы.','Принесите медальон Усопшей королевы верховному магу Лан\'далоку в Даларан.$B$BЭто задание выполняется в героическом режиме.','<Верховный маг хмуро кивает вам, когда вы передаете ему достаточно большой образец ювелирного искусства.>\n\nЧто сделано, то сделано. Эти врайкулы – такой благородный народ. Как жаль, что Король-лич столь глубоко вонзил в них свои смертоносные крючья.','Нельзя позволить Имирону повести за собой народ врайкулов. Если он вернется в Ледяную Корону с победой, велика вероятность того, что все будет потеряно.','Вернитесь к верховному магу Лан\'далоку в Опустевшие леса, что в Лесу Хрустальной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Победный трофей: король Имирон',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Король Имирон с вершины Утгарда пребывает в милости у Короля-лича. Одной этой причины было бы достаточно для того, чтобы покончить с ним.$B$BНо если он протрубит в рог и созовет всех вождей племен, подобных имирьярам и мьординам, врайкулы станут силой куда более мощной, чем прочие армии Плети!$B$BТы, $n, $gдолжен:должна; сделать так, чтобы этого никогда не произошло. Принеси мне медальон с его шеи, чтобы я знал, что Имирон больше не представляет для нас угрозы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите медальон Усопшей королевы верховному магу Лан\'далоку в Даларан.$B$BЭто задание выполняется в героическом режиме.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Верховный маг хмуро кивает вам, когда вы передаете ему достаточно большой образец ювелирного искусства.>\n\nЧто сделано, то сделано. Эти врайкулы – такой благородный народ. Как жаль, что Король-лич столь глубоко вонзил в них свои смертоносные крючья.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Нельзя позволить Имирону повести за собой народ врайкулов. Если он вернется в Ледяную Корону с победой, велика вероятность того, что все будет потеряно.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному магу Лан\'далоку в Опустевшие леса, что в Лесу Хрустальной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13249,'Победный трофей: пророк Тарон\'джа','Крепость Драк\'Тарон когда-то была гордым бастионом Драккари. Теперь это лишь перевалочный пункт для Короля-лича, пытающегося сокрушить Зул\'Драк и завладеть силой тролльих богов.$B$BНо если бы мы уничтожили здешнего предводителя, пророка Тарон\'джа, возможно, мы смогли бы остановить поступления все новых отрядов подкрепления для Плети из числа троллей. По крайней мере, это избавит Серебряный Авангард в Зул\'Драке хотя бы от одной из проблем.$B$BВозвращайся ко мне с его амулетом в качестве доказательства того, что пророк уничтожен.','Принесите верховному магу Лан\'далоку в Даларан заколдованный амулет пророка.$B$BЭто задание выполняется в героическом режиме.','Если удача будет сопутствовать нам, теперь, обезглавленная, крепость Драк\'Тарон перестанет отвлекать нас от главной проблемы в этой области – от борьбы с Плетью.\n\n<Верховный маг переводит взгляд на амулет, который он держит в руке.>\n\nЭто к лучшему, что амулет потерял свою колдовскую силу. Теперь мне не придется размышлять ни о том, как его использовать, ни о том, вправе ли я вообще это делать.','Повержен ли пророк? С тобой ли у тебя амулет?','Вернитесь к верховному магу Лан\'далоку в Опустевшие леса, что в Лесу Хрустальной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Победный трофей: пророк Тарон\'джа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Крепость Драк\'Тарон когда-то была гордым бастионом Драккари. Теперь это лишь перевалочный пункт для Короля-лича, пытающегося сокрушить Зул\'Драк и завладеть силой тролльих богов.$B$BНо если бы мы уничтожили здешнего предводителя, пророка Тарон\'джа, возможно, мы смогли бы остановить поступления все новых отрядов подкрепления для Плети из числа троллей. По крайней мере, это избавит Серебряный Авангард в Зул\'Драке хотя бы от одной из проблем.$B$BВозвращайся ко мне с его амулетом в качестве доказательства того, что пророк уничтожен.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите верховному магу Лан\'далоку в Даларан заколдованный амулет пророка.$B$BЭто задание выполняется в героическом режиме.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Если удача будет сопутствовать нам, теперь, обезглавленная, крепость Драк\'Тарон перестанет отвлекать нас от главной проблемы в этой области – от борьбы с Плетью.\n\n<Верховный маг переводит взгляд на амулет, который он держит в руке.>\n\nЭто к лучшему, что амулет потерял свою колдовскую силу. Теперь мне не придется размышлять ни о том, как его использовать, ни о том, вправе ли я вообще это делать.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Повержен ли пророк? С тобой ли у тебя амулет?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному магу Лан\'далоку в Опустевшие леса, что в Лесу Хрустальной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13250,'Победный трофей: Гал\'дара','Драккарские пророки Зул\'Драка совершили немыслимое: они уничтожили большинство своих богов и завладели их силой! Самый могущественный и опасный среди них – это верховный пророк Акали, Гал\'дара.$B$BУединившийся в недрах Гундрака Гал\'дара впитал в себя практически всю колдовскую силу убитого Акали и теперь хочет извергнуться из города вместе со своими последователями в окружающий мир. Если мы не убьем его сейчас, нас захлестнет море безумной и невообразимой силы!$B$BБыстрее, $n, принеси мне то, что осталось от колдовской силы Акали.','Принесите верховному магу Лан\'далоку в Даларан остатки колдунства Акали.$B$BЭто задание выполняется в героическом режиме.','Спасибо, $N. Я позабочусь о том, чтобы сущность бога охранялась, пока ее не передадут племени Зандалар.$B$BВозможно, они смогут найти способ объединить силы Акали?','У тебя есть моджо?$B$BМне прискорбно наблюдать за гибелью еще одной великой нации троллей.$B$BЯ могу только думать, что если бы не вмешательство Короля-лича, тролли не смогли бы чувствовать вескую необходимость обратиться к своим богам и украсть их...','Вернитесь к верховному магу Лан\'далоку в Опустевшие леса, что в Лесу Хрустальной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Победный трофей: Гал\'дара',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Драккарские пророки Зул\'Драка совершили немыслимое: они уничтожили большинство своих богов и завладели их силой! Самый могущественный и опасный среди них – это верховный пророк Акали, Гал\'дара.$B$BУединившийся в недрах Гундрака Гал\'дара впитал в себя практически всю колдовскую силу убитого Акали и теперь хочет извергнуться из города вместе со своими последователями в окружающий мир. Если мы не убьем его сейчас, нас захлестнет море безумной и невообразимой силы!$B$BБыстрее, $n, принеси мне то, что осталось от колдовской силы Акали.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите верховному магу Лан\'далоку в Даларан остатки колдунства Акали.$B$BЭто задание выполняется в героическом режиме.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо, $N. Я позабочусь о том, чтобы сущность бога охранялась, пока ее не передадут племени Зандалар.$B$BВозможно, они смогут найти способ объединить силы Акали?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У тебя есть моджо?$B$BМне прискорбно наблюдать за гибелью еще одной великой нации троллей.$B$BЯ могу только думать, что если бы не вмешательство Короля-лича, тролли не смогли бы чувствовать вескую необходимость обратиться к своим богам и украсть их...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному магу Лан\'далоку в Опустевшие леса, что в Лесу Хрустальной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13251,'Победный трофей: Мал\'Ганис','$n, один друг из числа бронзовых драконов снабдил меня кое-какой информацией, и мы должны ею воспользоваться.$B$BЗагадочные создания Пылающего Легиона, называемые Повелителями ужаса, известны как раса Натрезим. Немногое мы знаем об их родном мире, и то – одни лишь слухи.$B$BНо известно, что Мал\'Ганис в своем прошлом совершил фатальную ошибку: он потерял артефакт из своего родного мира!$B$BЧерез Пещеры Времени ты $gдолжен:должна; отправиться назад в прошлое, в период, известный нам как Очищение Стратхольма. Отыщи и принеси мне тот артефакт.','Принесите артефакт из родного мира натрезимов верховному магу Лан\'далоку в Даларан.$B$BЭто задание выполняется в героическом режиме.','Поразительно! Я никогда не видел ничего подобного. Я прослежу за тем, чтобы он попал в надежные руки в Аметистовой цитадели.\n$Если бы только тебе было позволено изменять ход истории... Возможно, если бы мы смогли уберечь Артаса от… нет, если думать об этом, можно сойти с ума.\n\nКонечно же, Хранители Времени понимают в этом больше, чем простые смертные.','Мы должны использовать ошибку Мал\'Ганиса. Не каждый день мы получаем такой шанс.\n\nЕсли мы сможем изучить этот артефакт, может быть, мы лучше станем понимать натрезимов!','Вернитесь к верховному магу Лан\'далоку в Опустевшие леса, что в Лесу Хрустальной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Победный трофей: Мал\'Ганис',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, один друг из числа бронзовых драконов снабдил меня кое-какой информацией, и мы должны ею воспользоваться.$B$BЗагадочные создания Пылающего Легиона, называемые Повелителями ужаса, известны как раса Натрезим. Немногое мы знаем об их родном мире, и то – одни лишь слухи.$B$BНо известно, что Мал\'Ганис в своем прошлом совершил фатальную ошибку: он потерял артефакт из своего родного мира!$B$BЧерез Пещеры Времени ты $gдолжен:должна; отправиться назад в прошлое, в период, известный нам как Очищение Стратхольма. Отыщи и принеси мне тот артефакт.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите артефакт из родного мира натрезимов верховному магу Лан\'далоку в Даларан.$B$BЭто задание выполняется в героическом режиме.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Поразительно! Я никогда не видел ничего подобного. Я прослежу за тем, чтобы он попал в надежные руки в Аметистовой цитадели.\n$Если бы только тебе было позволено изменять ход истории... Возможно, если бы мы смогли уберечь Артаса от… нет, если думать об этом, можно сойти с ума.\n\nКонечно же, Хранители Времени понимают в этом больше, чем простые смертные.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мы должны использовать ошибку Мал\'Ганиса. Не каждый день мы получаем такой шанс.\n\nЕсли мы сможем изучить этот артефакт, может быть, мы лучше станем понимать натрезимов!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному магу Лан\'далоку в Опустевшие леса, что в Лесу Хрустальной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13252,'Победный трофей: Сьоннир Литейщик','Немногое известно о том состоянии, что известно как Проклятие Плоти. Однако в Чертогах Камня хранится кое-какая информация.$B$BСьоннир Литейщик, похоже, знает многое об этом проклятии. Нам достоверно известно, что у него есть диск титанов, содержащий ответ на многие наши вопросы.$B$BПринеси мне этот диск, $n, чтобы мы смогли его изучить.','Принесите верховному магу Лан\'далоку в Даларан диск о Проклятии Плоти.$B$BЭто задание выполняется в героическом режиме.','Разве технология Титанов не поразительна? Информация содержится вот на этом диске!\n\nЯ лишь смею надеяться, что мы сможем найти способ извлечь ее оттуда.','У тебя есть диск?','Вернитесь к верховному магу Лан\'далоку в Опустевшие леса, что в Лесу Хрустальной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Победный трофей: Сьоннир Литейщик',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Немногое известно о том состоянии, что известно как Проклятие Плоти. Однако в Чертогах Камня хранится кое-какая информация.$B$BСьоннир Литейщик, похоже, знает многое об этом проклятии. Нам достоверно известно, что у него есть диск титанов, содержащий ответ на многие наши вопросы.$B$BПринеси мне этот диск, $n, чтобы мы смогли его изучить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите верховному магу Лан\'далоку в Даларан диск о Проклятии Плоти.$B$BЭто задание выполняется в героическом режиме.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Разве технология Титанов не поразительна? Информация содержится вот на этом диске!\n\nЯ лишь смею надеяться, что мы сможем найти способ извлечь ее оттуда.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У тебя есть диск?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному магу Лан\'далоку в Опустевшие леса, что в Лесу Хрустальной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13253,'Победный трофей: Локен','Локен, затаившийся в Чертогах Молний, жаждет положить конец всему нашем миру. Нужно ли мне еще что-то говорить, $n?$B$BОн восседает там, слушая безумные нашептывания древнего бога, запертого в глубинах под Нордсколом. Ты и твои друзья должны отправиться на Грозовую Гряду немедленно!$B$BБросьте вызов Локену в Земной сторожевой башне и остановите его, пока еще не слишком поздно! Принесите мне его рубиновое кольцо, и я пойму, что мы снова в безопасности.','Принесите верховному магу Лан\'далоку в Даларан божественное рубиновое кольцо.$B$BЭто задание выполняется в героическом режиме.','<Верховный маг Лан\'далок вздыхает с облегчением.>$B$BЧестно говоря, я боялся, что с тобой случилось что-то плохое. Трудно сидеть сложа руки, пока другие, такие как ты, занимаются вопросами жизни и смерти, которые, казалось бы, ежедневно возникают в нашем мире.$B$BТеперь, что мы будем делать с этим гигантским кольцом?','Мы снова разговариваем, $N. Означает ли это, что мы в безопасности от безумия Локена или мы всё же обречены?','Вернитесь к верховному магу Лан\'далоку в Опустевшие леса, что в Лесу Хрустальной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Победный трофей: Локен',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Локен, затаившийся в Чертогах Молний, жаждет положить конец всему нашем миру. Нужно ли мне еще что-то говорить, $n?$B$BОн восседает там, слушая безумные нашептывания древнего бога, запертого в глубинах под Нордсколом. Ты и твои друзья должны отправиться на Грозовую Гряду немедленно!$B$BБросьте вызов Локену в Земной сторожевой башне и остановите его, пока еще не слишком поздно! Принесите мне его рубиновое кольцо, и я пойму, что мы снова в безопасности.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите верховному магу Лан\'далоку в Даларан божественное рубиновое кольцо.$B$BЭто задание выполняется в героическом режиме.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Верховный маг Лан\'далок вздыхает с облегчением.>$B$BЧестно говоря, я боялся, что с тобой случилось что-то плохое. Трудно сидеть сложа руки, пока другие, такие как ты, занимаются вопросами жизни и смерти, которые, казалось бы, ежедневно возникают в нашем мире.$B$BТеперь, что мы будем делать с этим гигантским кольцом?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мы снова разговариваем, $N. Означает ли это, что мы в безопасности от безумия Локена или мы всё же обречены?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному магу Лан\'далоку в Опустевшие леса, что в Лесу Хрустальной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13254,'Победный трофей: Ануб\'арак','Порабощенные Плетью нерубы – просто чума для наших армий.$B$BСейчас, дрейфуя над миром, мы пребываем в относительной безопасности, но стоит нам спуститься на землю, как мы начинаем думать лишь о том, что нерубы могут выбраться из глубин Азжол-Неруба и напасть на нас.$B$BХорошо было бы посеять среди них панику. Убей их бывшего короля, ныне – мажордома Короля-лича, владыку склепа Ануб\'арака.$B$BПожалуйста, принеси мне его корону... все равно он ее больше не носит.','Принесите бесполезную корону Ануб\'арака верховному магу Лан\'далоку из Даларана.$B$BЭто задание выполняется в героическом режиме.','С какими ужасами ты, должно быть, $Gстолкнулся:столкнулась;, путешествуя по Верхнему городу.$B$B<Лан\'далок смотрит на потускневшую корону, сжимаемую вами в кулаке.>$B$BМожет, нам стоит отложить это для их нового короля, когда нерубиане решат короновать его?','Я рад, что в Азжол-Неруб спускаешься ты, а не я.$B$BЯ не люблю находиться под землей.','Вернитесь к верховному магу Лан\'далоку в Опустевшие леса, что в Лесу Хрустальной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Победный трофей: Ануб\'арак',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Порабощенные Плетью нерубы – просто чума для наших армий.$B$BСейчас, дрейфуя над миром, мы пребываем в относительной безопасности, но стоит нам спуститься на землю, как мы начинаем думать лишь о том, что нерубы могут выбраться из глубин Азжол-Неруба и напасть на нас.$B$BХорошо было бы посеять среди них панику. Убей их бывшего короля, ныне – мажордома Короля-лича, владыку склепа Ануб\'арака.$B$BПожалуйста, принеси мне его корону... все равно он ее больше не носит.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите бесполезную корону Ануб\'арака верховному магу Лан\'далоку из Даларана.$B$BЭто задание выполняется в героическом режиме.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','С какими ужасами ты, должно быть, $Gстолкнулся:столкнулась;, путешествуя по Верхнему городу.$B$B<Лан\'далок смотрит на потускневшую корону, сжимаемую вами в кулаке.>$B$BМожет, нам стоит отложить это для их нового короля, когда нерубиане решат короновать его?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я рад, что в Азжол-Неруб спускаешься ты, а не я.$B$BЯ не люблю находиться под землей.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному магу Лан\'далоку в Опустевшие леса, что в Лесу Хрустальной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13255,'Победный трофей: глашатай Волаж','Нерубы Ан\'кахета копали слишком глубоко, пытаясь сбежать от наступающих армий Плети. Они подобрались слишком близко к Древнему богу, влачащему свое существование в глубинах под Нордсколом.$B$BОбнаружив их присутствие, древний бог натравил на них своих безумных созданий, и нерубы попали между вошедшими в поговорку молотом и наковальней.$B$BЛидер сил Древнего бога – глашатай Волаж – одно из кошмарных созданий, известных под именем Безликих. Покончи с ним и принеси мне его усохший мозг.$B$BНо, пожалуйста, постарайся $gсам:сама; не сойти с ума.','Принесите верховному магу Лан\'далоку в Даларан усохший мозг безликого.$B$BЭто задание выполняется в героическом режиме.','<Архимаг настороженно смотрит на мозг.>$B$BТеперь, когда я думаю об этом, я не совсем уверен, безопасно ли находиться так близко к этой штуке. Ты говоришь, что он еще жив?$B$B<Он качает головой.>$B$BУ нас есть место для таких вещей в цитадели. Я прослежу, чтобы один из моих учеников сразу отнес его туда.','$N? Ты все ещё в здравом уме?','Вернитесь к верховному магу Лан\'далоку в Опустевшие леса, что в Лесу Хрустальной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Победный трофей: глашатай Волаж',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нерубы Ан\'кахета копали слишком глубоко, пытаясь сбежать от наступающих армий Плети. Они подобрались слишком близко к Древнему богу, влачащему свое существование в глубинах под Нордсколом.$B$BОбнаружив их присутствие, древний бог натравил на них своих безумных созданий, и нерубы попали между вошедшими в поговорку молотом и наковальней.$B$BЛидер сил Древнего бога – глашатай Волаж – одно из кошмарных созданий, известных под именем Безликих. Покончи с ним и принеси мне его усохший мозг.$B$BНо, пожалуйста, постарайся $gсам:сама; не сойти с ума.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите верховному магу Лан\'далоку в Даларан усохший мозг безликого.$B$BЭто задание выполняется в героическом режиме.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Архимаг настороженно смотрит на мозг.>$B$BТеперь, когда я думаю об этом, я не совсем уверен, безопасно ли находиться так близко к этой штуке. Ты говоришь, что он еще жив?$B$B<Он качает головой.>$B$BУ нас есть место для таких вещей в цитадели. Я прослежу, чтобы один из моих учеников сразу отнес его туда.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$N? Ты все ещё в здравом уме?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному магу Лан\'далоку в Опустевшие леса, что в Лесу Хрустальной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13256,'Победный трофей: Синигоса','На нас напали! Синие драконы телепортировались в Аметистовую крепость и теперь планируют вторгнуться оттуда в Даларан!$B$BДо нас уже доходили слухи о заключенных, которые были – якобы случайно – освобождены ими. Я не удивлюсь, если они специально выпускают некоторых из них на волю.$B$B$n, не $gмог:могла; бы ты как можно быстрее сколотить команду и отправиться туда? Их силы ведет в бой Синигоса. Принеси мне ее голову!','Принесите верховному магу Лан\'далоку в Даларан голову Синигосы.$B$BЭто задание выполняется в героическом режиме.','Если хорошенько подумать, зачем бы я телепортировался в тюрьму, чтобы потом пытаться из нее выбраться? Это же самое охраняемое здание в городе.\n\nМне кажется, эти синие совсем сошли с ума!','Вернитесь к верховному магу Лан\'далоку в Опустевшие леса, что в Лесу Хрустальной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Победный трофей: Синигоса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На нас напали! Синие драконы телепортировались в Аметистовую крепость и теперь планируют вторгнуться оттуда в Даларан!$B$BДо нас уже доходили слухи о заключенных, которые были – якобы случайно – освобождены ими. Я не удивлюсь, если они специально выпускают некоторых из них на волю.$B$B$n, не $gмог:могла; бы ты как можно быстрее сколотить команду и отправиться туда? Их силы ведет в бой Синигоса. Принеси мне ее голову!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите верховному магу Лан\'далоку в Даларан голову Синигосы.$B$BЭто задание выполняется в героическом режиме.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если хорошенько подумать, зачем бы я телепортировался в тюрьму, чтобы потом пытаться из нее выбраться? Это же самое охраняемое здание в городе.\n\nМне кажется, эти синие совсем сошли с ума!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному магу Лан\'далоку в Опустевшие леса, что в Лесу Хрустальной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13257,'Глашатай войны','Вождь нуждается в тебе, $gвоин:воительница;. Оргриммар на военном положении. Торговля, оказание услуг – все теперь свернуто, когда вождь готовится к неизбежному конфликту.$B$BЯ не могу сказать тебе больше – во всяком случае, не сейчас. И не здесь.$B$BВождь приказывает всем самым сильным воинам направиться к нему на доклад в его тронную залу. Ступай, $n! Воспользуйся этим порталом, чтобы вернуться в Оргриммар и встретиться с Траллом.','Доложите о своем прибытии Траллу, который находится в крепости Громмаш в Оргриммаре.','Повелитель демонов Вариматас и главный аптекарь Отрекшихся Гнилесс – вот кто несет ответственность за это предательство.\n\n<Тралл кивает.>\n\nДа, тот самый Гнилесс, который нашел лекарство против недавней вспышки чумы.\n\nТе, кто не приняли их сторону, были убиты или изгнаны из нашего мира. Во время переворота чуть не погибла Сильвана.\n\nОрда потеряла Подгород. Оргриммар будет принимать беженцев-Отрекшихся у себя, пока не будет найдено решение этой проблемы. До тех пор мы находимся на военном положении.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Глашатай войны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вождь нуждается в тебе, $gвоин:воительница;. Оргриммар на военном положении. Торговля, оказание услуг – все теперь свернуто, когда вождь готовится к неизбежному конфликту.$B$BЯ не могу сказать тебе больше – во всяком случае, не сейчас. И не здесь.$B$BВождь приказывает всем самым сильным воинам направиться к нему на доклад в его тронную залу. Ступай, $n! Воспользуйся этим порталом, чтобы вернуться в Оргриммар и встретиться с Траллом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доложите о своем прибытии Траллу, который находится в крепости Громмаш в Оргриммаре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Повелитель демонов Вариматас и главный аптекарь Отрекшихся Гнилесс – вот кто несет ответственность за это предательство.\n\n<Тралл кивает.>\n\nДа, тот самый Гнилесс, который нашел лекарство против недавней вспышки чумы.\n\nТе, кто не приняли их сторону, были убиты или изгнаны из нашего мира. Во время переворота чуть не погибла Сильвана.\n\nОрда потеряла Подгород. Оргриммар будет принимать беженцев-Отрекшихся у себя, пока не будет найдено решение этой проблемы. До тех пор мы находимся на военном положении.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (13258,'Замечательная возможность') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Замечательная возможность',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (13259,'Закрепить преимущество','У нас почти все готово, чтобы причинить ощутимый ущерб этому тепленькому местечку, но надо все сделать с умом.$B$BНам удалось раздобыть очень мощные саронитовые бомбы, изготовленные мастерами Плети. Но прежде чем мы их взорвем, нужно зачистить территорию.$B$BВремени мало, нам надо успеть, пока Плеть не прислала сюда подкрепление.$B$BПомоги моим солдатам, а потом возвращайся сюда, и мы устроим фейерверк.','Вернитесь к сержанту Крегге в Цитадель Ледяной Короны, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Закрепить преимущество',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У нас почти все готово, чтобы причинить ощутимый ущерб этому тепленькому местечку, но надо все сделать с умом.$B$BНам удалось раздобыть очень мощные саронитовые бомбы, изготовленные мастерами Плети. Но прежде чем мы их взорвем, нужно зачистить территорию.$B$BВремени мало, нам надо успеть, пока Плеть не прислала сюда подкрепление.$B$BПомоги моим солдатам, а потом возвращайся сюда, и мы устроим фейерверк.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к сержанту Крегге в Цитадель Ледяной Короны, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13260,'Уж кто бы говорил!','Сражаясь против Альянса, мы не должны забывать и о Плети.$b$bВ ближайшие недели мы еще не сможем начать наступление, но это не значит, что мы не должны изучить оборону противника.$b$bЯ попросил прикрепленного к нашему войску рыцаря смерти дать тебе пару советов. Ведь если подумать, то кто может знать этого врага лучше, чем рыцари смерти?$b$bПозволь представить тебе: Кольтира Ткач Смерти.','По заданию покорителя небес Корма поговорите с Кольтирой Ткачом Смерти на борту "Молота Оргрима".','<Кольтира осматривает вас с ног до головы.>\n\nНадеюсь, ты справишься. Иначе тебе же хуже будет, $C.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уж кто бы говорил!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сражаясь против Альянса, мы не должны забывать и о Плети.$b$bВ ближайшие недели мы еще не сможем начать наступление, но это не значит, что мы не должны изучить оборону противника.$b$bЯ попросил прикрепленного к нашему войску рыцаря смерти дать тебе пару советов. Ведь если подумать, то кто может знать этого врага лучше, чем рыцари смерти?$b$bПозволь представить тебе: Кольтира Ткач Смерти.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По заданию покорителя небес Корма поговорите с Кольтирой Ткачом Смерти на борту "Молота Оргрима".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Кольтира осматривает вас с ног до головы.>\n\nНадеюсь, ты справишься. Иначе тебе же хуже будет, $C.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13261,'Непостоянство','Ух ты! Получилось! То есть я ни капельки не сомневался в своей сверхъестественной гениальности и мастерстве, я просто не был уверен, какова будет мощность взрыва – в общем, я рад, что ты не $gподпалил себе брови:подпалила себе реснички;. А теперь давай-ка покажем старине Корму, как ты подрываешь этих змеев. Он впечатлится и повысит меня до... э... кто там идет после главного инженера? В общем, бери еще пачку этой убойной штуковины и возвращайся на передовую, а я пойду приведу Корма...$b$bНу, чего ты стоишь? Вперед!','Отправляйтесь к Прорванному фронту и воспользуйтесь летучим маслом Меднопала, чтобы привлечь 3 ледяных небесных когтей.$b$bДля того чтобы использовать масло, соберите на поле сражения груду костей, брошенный шлем и брошенную броню.','Зря старались!\n\nСперва Корм был занят, а когда я все-таки вытащил его наверх – ну, чтобы он посмотрел, – ты уже все закончила. Он обозлился, окрысился на меня и сказал, чтобы я не попадался ему на глаза, ну, как минимум, до завтра...\n\nТак что приходи завтра, и мы попробуем еще раз!','Ну что, |3-6($R), ты поджарила этих змеев?','Вернитесь к главному инженеру Меднопалу на "Молот Оргрима", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Непостоянство',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ух ты! Получилось! То есть я ни капельки не сомневался в своей сверхъестественной гениальности и мастерстве, я просто не был уверен, какова будет мощность взрыва – в общем, я рад, что ты не $gподпалил себе брови:подпалила себе реснички;. А теперь давай-ка покажем старине Корму, как ты подрываешь этих змеев. Он впечатлится и повысит меня до... э... кто там идет после главного инженера? В общем, бери еще пачку этой убойной штуковины и возвращайся на передовую, а я пойду приведу Корма...$b$bНу, чего ты стоишь? Вперед!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь к Прорванному фронту и воспользуйтесь летучим маслом Меднопала, чтобы привлечь 3 ледяных небесных когтей.$b$bДля того чтобы использовать масло, соберите на поле сражения груду костей, брошенный шлем и брошенную броню.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Зря старались!\n\nСперва Корм был занят, а когда я все-таки вытащил его наверх – ну, чтобы он посмотрел, – ты уже все закончила. Он обозлился, окрысился на меня и сказал, чтобы я не попадался ему на глаза, ну, как минимум, до завтра...\n\nТак что приходи завтра, и мы попробуем еще раз!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, |3-6($R), ты поджарила этих змеев?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к главному инженеру Меднопалу на "Молот Оргрима", что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13262,'Мощный взрыв','Кажется, ситуация вышла из-под контроля уже настолько, что дальше некуда. Вот что мы сделаем, $n.$B$BМне нужно, чтобы кто-то поджег фитиль от этих бомб. И, похоже, это будешь ты.','Идите к ближайшему штабелю саронитовых бомб и подожгите фитиль.','С виду вроде бы мощные бомбы. Как минимум, они должны повредить окрестные здания.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мощный взрыв',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кажется, ситуация вышла из-под контроля уже настолько, что дальше некуда. Вот что мы сделаем, $n.$B$BМне нужно, чтобы кто-то поджег фитиль от этих бомб. И, похоже, это будешь ты.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Идите к ближайшему штабелю саронитовых бомб и подожгите фитиль.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','С виду вроде бы мощные бомбы. Как минимум, они должны повредить окрестные здания.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13263,'Фитиль короток!','Вы поджигаете фитиль и с удивлением замечаете, что он горит гораздо быстрее, чем вы ожидали.$B$BБомбы вот-вот взорвутся, и ваш единственный шанс на спасение – это спрятаться в яме и надеяться, что вас не накроет взрывом.','Ищите следы и подсказки, независимо от того, куда вас занесет взрывной волной.','Пульсирующий предмет, покрытый толстой коркой льда, таинственно мерцает под водой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Фитиль короток!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы поджигаете фитиль и с удивлением замечаете, что он горит гораздо быстрее, чем вы ожидали.$B$BБомбы вот-вот взорвутся, и ваш единственный шанс на спасение – это спрятаться в яме и надеяться, что вас не накроет взрывом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Ищите следы и подсказки, независимо от того, куда вас занесет взрывной волной.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Пульсирующий предмет, покрытый толстой коркой льда, таинственно мерцает под водой.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13264,'Как все погано!','По заданию Кольтиры Ткача Смерти с "Молота Оргрима", используя набор для оживления, воскресите поганище и с его помощью уничтожьте 15 ледяных вурдалаков, 15 агрессивных упырей и 15 восставших солдат Альянса.','Да, $C?','Вернитесь к Кольтире Ткачу Смерти на "Молот Оргрима", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Как все погано!',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По заданию Кольтиры Ткача Смерти с "Молота Оргрима", используя набор для оживления, воскресите поганище и с его помощью уничтожьте 15 ледяных вурдалаков, 15 агрессивных упырей и 15 восставших солдат Альянса.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да, $C?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кольтире Ткачу Смерти на "Молот Оргрима", что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (13265,'Сбор ткани','Получи пару лишних кусочков ткани и сшей из них нечто сногсшибательное!','Многие северяне-гуманоиды носят одежду, которая легко может быть обращена в материал, если знать пару хитростей.$B$BЗа сущие копейки я могу научить тебя, как распарывать их одежду так, чтобы нарезать немного дополнительной ткани.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сбор ткани',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Получи пару лишних кусочков ткани и сшей из них нечто сногсшибательное!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Многие северяне-гуманоиды носят одежду, которая легко может быть обращена в материал, если знать пару хитростей.$B$BЗа сущие копейки я могу научить тебя, как распарывать их одежду так, чтобы нарезать немного дополнительной ткани.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (13266,'Жизнь без сожалений','В день, когда за мной придет моя смерть, я хотел бы сказать, что жизнь прошла не зря. Те, кто станут оплакивать мою гибель, будут знать, что я был вождем, который принимал решения на благо своего народа.$B$BНо предательство Вариматаса и Гнилесса...Все, над чем мы работали, пошло прахом.$B$B<Тралл тяжело вздыхает.>$B$BПравосудие должно свершиться.$B$BПорталы, ведущие в Подгород, будут немедленно открыты. Вол\'джин будет ждать тебя. Вскоре я присоединюсь к тебе. Вместе мы сделаем то, что нужно сделать, $n.','Воспользуйтесь порталом в Подгород, расположенном в крепости Громмаш, и доложите о своем прибытии Вол\'джину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жизнь без сожалений',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В день, когда за мной придет моя смерть, я хотел бы сказать, что жизнь прошла не зря. Те, кто станут оплакивать мою гибель, будут знать, что я был вождем, который принимал решения на благо своего народа.$B$BНо предательство Вариматаса и Гнилесса...Все, над чем мы работали, пошло прахом.$B$B<Тралл тяжело вздыхает.>$B$BПравосудие должно свершиться.$B$BПорталы, ведущие в Подгород, будут немедленно открыты. Вол\'джин будет ждать тебя. Вскоре я присоединюсь к тебе. Вместе мы сделаем то, что нужно сделать, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь порталом в Подгород, расположенном в крепости Громмаш, и доложите о своем прибытии Вол\'джину.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (13267,'Битва за Подгород','Весь Подгород под контролем Вариматаса. Наши солдаты находятся в боевой готовности, ожидая от вождя приказа идти в атаку.$B$BПомоги Орде отвоевать Подгород и встань в один ряд с нашими самыми великими воинами! Если останешься в живых, доложись Траллу.$B$BДай вождю знать, когда будешь $gготов:готова; вступить в бой.','Помогите Траллу и Сильване вернуть Орде контроль над Подгородом.$B$BВ случае успеха отрапортуйте об этом Траллу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Битва за Подгород',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Весь Подгород под контролем Вариматаса. Наши солдаты находятся в боевой готовности, ожидая от вождя приказа идти в атаку.$B$BПомоги Орде отвоевать Подгород и встань в один ряд с нашими самыми великими воинами! Если останешься в живых, доложись Траллу.$B$BДай вождю знать, когда будешь $gготов:готова; вступить в бой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Помогите Траллу и Сильване вернуть Орде контроль над Подгородом.$B$BВ случае успеха отрапортуйте об этом Траллу.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (13268,'Сбор ткани','Получи пару лишних кусочков ткани и сшей из них нечто сногсшибательное!','Ладный пошив твоей одежды подсказывает мне, что ты и $Gсам:сама; $Gспособный:способная; $Gпортной:портная; и без труда усвоишь мой урок.$B$BМногие северяне-гуманоиды носят одежду, которая легко может быть обращена в материал, если знать пару хитростей.$B$BЗа сущие копейки я могу научить тебя, как распарывать их одежду так, чтобы нарезать немного дополнительной ткани.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сбор ткани',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Получи пару лишних кусочков ткани и сшей из них нечто сногсшибательное!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ладный пошив твоей одежды подсказывает мне, что ты и $Gсам:сама; $Gспособный:способная; $Gпортной:портная; и без труда усвоишь мой урок.$B$BМногие северяне-гуманоиды носят одежду, которая легко может быть обращена в материал, если знать пару хитростей.$B$BЗа сущие копейки я могу научить тебя, как распарывать их одежду так, чтобы нарезать немного дополнительной ткани.',`requestitemstext_loc8`);
