INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13271,'Голос во тьме','Этот предмет – вовсе не кристалл: скорее, он похож на некий орган, заключенный в ледяную оболочку. $B$BКогда вы касаетесь его, вашу руку обжигает невыносимая боль, словно бы от раны, хотя на руке не остается ни следа.$B$BИ вдруг вы слышите голос маленького мальчика. $B$B"Тебе не стоило этого делать..."','Идите на голос в Забытые Глубины – Наз\'анак.','Я видел, как он избавился от этой штуковины. Бросил ее прямо здесь.$B$BСказал, ему она больше не пригодится. Сказал, она забирает у него силы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Голос во тьме',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этот предмет – вовсе не кристалл: скорее, он похож на некий орган, заключенный в ледяную оболочку. $B$BКогда вы касаетесь его, вашу руку обжигает невыносимая боль, словно бы от раны, хотя на руке не остается ни следа.$B$BИ вдруг вы слышите голос маленького мальчика. $B$B"Тебе не стоило этого делать..."',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Идите на голос в Забытые Глубины – Наз\'анак.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я видел, как он избавился от этой штуковины. Бросил ее прямо здесь.$B$BСказал, ему она больше не пригодится. Сказал, она забирает у него силы.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`) VALUES (13272,'Сбор ткани','Многие северяне-гуманоиды носят одежду, которая легко может быть обращена в материал, если знать пару хитростей.$B$BЗа сущие копейки я могу научить тебя, как распарывать их одежду так, чтобы нарезать немного дополнительной ткани.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сбор ткани',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Многие северяне-гуманоиды носят одежду, которая легко может быть обращена в материал, если знать пару хитростей.$B$BЗа сущие копейки я могу научить тебя, как распарывать их одежду так, чтобы нарезать немного дополнительной ткани.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13273,'В поисках ядра','Теперь, когда оболочка Норганнона у нас в руках, осталось найти вторую половину ключа от архива. По счастью, Лига исследователей немало потрудилась, разыскивая следы ядра Норганнона.$b$bДалеко к юго-востоку от Библиотеки Изобретателя, на склонах к северу от Дун Ниффелема, находится лагерь, который носит мое имя. В этом лагере живут представители Лиги исследователей, которые занимаются поисками второй половины ключа. Принеси мне их карты и записи, и мы сумеем найти то, что ищем.','Найдите записи геолога Хроны и записи геолога Сорена в главном лагере Бранна.','Ну что, где записи?','Воспользуйтесь переговорным устройством Бранна для связи с Бранном Бронзобородом.$B$BЕсли вы потеряете переговорное устройство, возьмите новое у Мотеха Дитя Ветра на месте крушения Гром\'арша.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В поисках ядра',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда оболочка Норганнона у нас в руках, осталось найти вторую половину ключа от архива. По счастью, Лига исследователей немало потрудилась, разыскивая следы ядра Норганнона.$b$bДалеко к юго-востоку от Библиотеки Изобретателя, на склонах к северу от Дун Ниффелема, находится лагерь, который носит мое имя. В этом лагере живут представители Лиги исследователей, которые занимаются поисками второй половины ключа. Принеси мне их карты и записи, и мы сумеем найти то, что ищем.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите записи геолога Хроны и записи геолога Сорена в главном лагере Бранна.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, где записи?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Воспользуйтесь переговорным устройством Бранна для связи с Бранном Бронзобородом.$B$BЕсли вы потеряете переговорное устройство, возьмите новое у Мотеха Дитя Ветра на месте крушения Гром\'арша.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13274,'Хранитель ядра','В записках геолога Сорена сказано, что ядро Норганнона хранится у одного из созданий Мимира, стража по имени Атан.$b$bСорен говорит, что подземелье, где обитает Атан, в наше время зовется "Сделка Локена".$b$bЛокен. Любопытно, не правда ли? О нем упоминали земельники.$b$bГоворят, это подземелье находится к юго-западу от разрушенного лагеря Лиги изобретателей, круглый вход в подземелье расположен на склоне горы со стороны долины Древних Зим.$b$bОтыщи этого Атана и отбери у него ядро. Но, думаю, без боя он его не отдаст...','Добудьте ядро Норганнона.','Да, вот оно! Ключ практически у нас в руках! Осталось только выяснить, как соединить оболочку и ядро. Давай посмотрим, что говорится об этом у Сорена…','Ну что, прав был геолог Сорен? Удалось ли тебе отыскать ядро Норганнона?','Воспользуйтесь переговорным устройством Бранна для связи с Бранном Бронзобородом.$B$BЕсли вы потеряете переговорное устройство, возьмите новое у Мотеха Дитя Ветра на месте крушения Гром\'арша.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хранитель ядра',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В записках геолога Сорена сказано, что ядро Норганнона хранится у одного из созданий Мимира, стража по имени Атан.$b$bСорен говорит, что подземелье, где обитает Атан, в наше время зовется "Сделка Локена".$b$bЛокен. Любопытно, не правда ли? О нем упоминали земельники.$b$bГоворят, это подземелье находится к юго-западу от разрушенного лагеря Лиги изобретателей, круглый вход в подземелье расположен на склоне горы со стороны долины Древних Зим.$b$bОтыщи этого Атана и отбери у него ядро. Но, думаю, без боя он его не отдаст...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте ядро Норганнона.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, вот оно! Ключ практически у нас в руках! Осталось только выяснить, как соединить оболочку и ядро. Давай посмотрим, что говорится об этом у Сорена…',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, прав был геолог Сорен? Удалось ли тебе отыскать ядро Норганнона?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Воспользуйтесь переговорным устройством Бранна для связи с Бранном Бронзобородом.$B$BЕсли вы потеряете переговорное устройство, возьмите новое у Мотеха Дитя Ветра на месте крушения Гром\'арша.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13275,'Пора прятаться!','Не стоило тебе трогать эту штуку! Теперь он непременно явится искать тебя.$b$bИ он тебя найдет. Если только ты не сумеешь от него спрятаться.$b$bХочешь выжить – принеси мне кровь безликих!','Добудьте 3 образца крови безликих по совету Матиаса Нетлера.','Ну что, где кровь?','Вернитесь к Матиасу Нетлеру в Наз\'анак: Забытые глубины, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пора прятаться!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не стоило тебе трогать эту штуку! Теперь он непременно явится искать тебя.$b$bИ он тебя найдет. Если только ты не сумеешь от него спрятаться.$b$bХочешь выжить – принеси мне кровь безликих!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 3 образца крови безликих по совету Матиаса Нетлера.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, где кровь?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Матиасу Нетлеру в Наз\'анак: Забытые глубины, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13276,'Как все погано!','Ты знаешь, что делать, |3-6($c).$b$bВозьми этот набор и используй внутренности поганищ, чтобы создать свое собственное, а потом прикажи ему атаковать вражеские силы у врат.$b$bТебе стоит отработать эту тактику к тому времени, как мы пойдем на штурм врат.','Используйте набор для оживления, чтобы воскресить поганище и убить с его помощью 15 ледяных вурдалаков, 15 агрессивных упырей и 15 восставших солдат Альянса по просьбе Кольтиры Ткача Смерти с "Молота Оргрима".','Я вижу, ты все лучше управляешься с поганищами!$B$BПри должном усердии с твоей стороны Орда, глядишь, скоро возьмет врата.','Да, $C?','Вернитесь к Кольтире Ткачу Смерти на "Молот Оргрима", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Как все погано!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты знаешь, что делать, |3-6($c).$b$bВозьми этот набор и используй внутренности поганищ, чтобы создать свое собственное, а потом прикажи ему атаковать вражеские силы у врат.$b$bТебе стоит отработать эту тактику к тому времени, как мы пойдем на штурм врат.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте набор для оживления, чтобы воскресить поганище и убить с его помощью 15 ледяных вурдалаков, 15 агрессивных упырей и 15 восставших солдат Альянса по просьбе Кольтиры Ткача Смерти с "Молота Оргрима".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я вижу, ты все лучше управляешься с поганищами!$B$BПри должном усердии с твоей стороны Орда, глядишь, скоро возьмет врата.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да, $C?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кольтире Ткачу Смерти на "Молот Оргрима", что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13277,'Борьба с великанами','Конечно, очень важно разгромить Плеть на поле битвы, но все-таки не следует пренебрегать и самими воротами.$b$bМясистые великаны, что обороняют укрепления, могут швырять массивные валуны и куски льда, нанося катастрофический урон вражеской пехоте.$b$bСоберись с силами и уничтожь этих великанов. Нам надо знать, насколько они сильны, чтобы предвидеть, с чем предстоит иметь дело.$b$bДа, и кстати, принеси мне их позвоночники. Если память мне не изменяет, с ними можно проделать одну любопытную штуку... Тебя я, конечно, тоже этому научу.','Принесите Кольтире Ткачу Смерти на борт "Молота Оргрима" 5 гноящихся позвоночников пустулезных ужасов из Морд\'ретара.','Вернитесь к Кольтире Ткачу Смерти на "Молот Оргрима", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Борьба с великанами',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Конечно, очень важно разгромить Плеть на поле битвы, но все-таки не следует пренебрегать и самими воротами.$b$bМясистые великаны, что обороняют укрепления, могут швырять массивные валуны и куски льда, нанося катастрофический урон вражеской пехоте.$b$bСоберись с силами и уничтожь этих великанов. Нам надо знать, насколько они сильны, чтобы предвидеть, с чем предстоит иметь дело.$b$bДа, и кстати, принеси мне их позвоночники. Если память мне не изменяет, с ними можно проделать одну любопытную штуку... Тебя я, конечно, тоже этому научу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Кольтире Ткачу Смерти на борт "Молота Оргрима" 5 гноящихся позвоночников пустулезных ужасов из Морд\'ретара.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кольтире Ткачу Смерти на "Молот Оргрима", что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13278,'Корпой Оскверненный','$C, до меня дошли известия о том, что у Врат Смерти появился новый могучий зомби.$b$bМы не можем сидеть сложа руки, когда нам угрожает такой серьезный противник. Любые сведения о нем, какие тебе удастся раздобыть, – лучше, чем ничего.$b$bСтупай в западное караульное помещение у врат и найди это существо. Сразись с ним и отыщи брешь в его защите, которой мы могли бы воспользоваться.','Убейте Корпоя Оскверненного из Морд\'ретара по просьбе Кольтиры Ткача Смерти с "Молота Оргрима".','Отлично, $C!\n\nБыть может, проведя исследования, мы сумеем выяснить, как они изготовляют подобных созданий.','Тебе удалось найти зомби, $C?','Вернитесь к Кольтире Ткачу Смерти на "Молот Оргрима", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Корпой Оскверненный',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$C, до меня дошли известия о том, что у Врат Смерти появился новый могучий зомби.$b$bМы не можем сидеть сложа руки, когда нам угрожает такой серьезный противник. Любые сведения о нем, какие тебе удастся раздобыть, – лучше, чем ничего.$b$bСтупай в западное караульное помещение у врат и найди это существо. Сразись с ним и отыщи брешь в его защите, которой мы могли бы воспользоваться.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Корпоя Оскверненного из Морд\'ретара по просьбе Кольтиры Ткача Смерти с "Молота Оргрима".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, $C!\n\nБыть может, проведя исследования, мы сумеем выяснить, как они изготовляют подобных созданий.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось найти зомби, $C?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кольтире Ткачу Смерти на "Молот Оргрима", что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13279,'Основы химии','<Кольтира берет гноящиеся позвоночники и сливает из них жидкость во фляжку.>$B$BМалоизвестное свойство мясистых великанов...$B$BИх спинномозговая жидкость взаимодействует с чумой весьма любопытным образом: на выходе получается очень едкая кислота.$B$BЕсли разлить ее вниз с укреплений, войскам, что внизу, это не понравится, но зато жертвы уже не встанут и не пополнят собой ряды противника.$b$bВылей содержимое этой фляги в один из чумных котлов в западном караульном помещении Врат Смерти.','Вылейте пустулезную спинномозговую жидкость в чумной котел в Морд\'ретаре по просьбе Кольтиры Ткача Смерти с борта "Молота Оргрима".','Отличная работа, $C!\n\nКогда наши войска двинутся на штурм цитадели, у нас будет готовый план по взятию врат смерти…','Тебе удалось нейтрализовать чуму, $C?','Вернитесь к Кольтире Ткачу Смерти на "Молот Оргрима", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Основы химии',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Кольтира берет гноящиеся позвоночники и сливает из них жидкость во фляжку.>$B$BМалоизвестное свойство мясистых великанов...$B$BИх спинномозговая жидкость взаимодействует с чумой весьма любопытным образом: на выходе получается очень едкая кислота.$B$BЕсли разлить ее вниз с укреплений, войскам, что внизу, это не понравится, но зато жертвы уже не встанут и не пополнят собой ряды противника.$b$bВылей содержимое этой фляги в один из чумных котлов в западном караульном помещении Врат Смерти.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вылейте пустулезную спинномозговую жидкость в чумной котел в Морд\'ретаре по просьбе Кольтиры Ткача Смерти с борта "Молота Оргрима".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличная работа, $C!\n\nКогда наши войска двинутся на штурм цитадели, у нас будет готовый план по взятию врат смерти…',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось нейтрализовать чуму, $C?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кольтире Ткачу Смерти на "Молот Оргрима", что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13280,'Царь горы','Короче, $n, мне надо, чтобы ты $gзагнал:загнала; мой прыгобот на са-амую макушку вон той горы на северо-западе, ясно?$b$bЭтот тупой и самодовольный Бубух Громбабах сейчас работает над своим собственным ботом, и, боюсь, он его почти доделал. Короче, мы договорились о соревновании, кто сумеет стать царем горы!$b$bКак доберешься наверх, воткни наш боевой штандарт в груду костей, чтобы все видели, что Альянс сильнее всех, а я – лучший изобретатель!','Используйте прыгобот Зуботески, чтобы установить боевой штандарт Альянса в груде черепов на вершине горы, по просьбе Фраззл Зуботески.','Погоди секунду... ты ещё не $Gустановил:установила; наш боевой штандарт!$B$BЧего ждешь?','Вернитесь к Фраззл Зуботеске в Имирхейм, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Царь горы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Короче, $n, мне надо, чтобы ты $gзагнал:загнала; мой прыгобот на са-амую макушку вон той горы на северо-западе, ясно?$b$bЭтот тупой и самодовольный Бубух Громбабах сейчас работает над своим собственным ботом, и, боюсь, он его почти доделал. Короче, мы договорились о соревновании, кто сумеет стать царем горы!$b$bКак доберешься наверх, воткни наш боевой штандарт в груду костей, чтобы все видели, что Альянс сильнее всех, а я – лучший изобретатель!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте прыгобот Зуботески, чтобы установить боевой штандарт Альянса в груде черепов на вершине горы, по просьбе Фраззл Зуботески.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Погоди секунду... ты ещё не $Gустановил:установила; наш боевой штандарт!$B$BЧего ждешь?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фраззл Зуботеске в Имирхейм, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13281,'Избавление от чумы','Теперь ты управишься и без моей помощи, |3-6($r). Ты уже знаешь, как нейтрализовать вражеские чумные котлы.$b$bИди к Вратам Смерти, прибей пару-тройку мясистых великанов, набери жидкости из их хребтов и вылей ее в котлы, чтобы испортить всю партию этого чумного варева.$b$bБудем разить врага в самое сердце. Это очень важное задание, и его нужно выполнить любой ценой. Трудно сказать, сколько у тебя будет времени, но постарайся охватить побольше котлов.$b$bВеликанов и чумные котлы ты найдешь в Морд\'ретаре.','По приказу Кольтиры Ткача Смерти с "Молота Оргрима" отправляйтесь в Морд\'ретар и нейтрализуйте содержимое чумного котла с помощью пустулезной спинномозговой жидкости.$b$bПустулезная спинномозговая жидкость изготовляется из позвоночника великана. Его можно получить, убивая пустулезных ужасов.','Вот и славно. Еще одним котлом меньше. Когда начнется сражение, в счет пойдет каждый котел.$B$BТвой командир будет доволен.','Приветствую, $C.','Вернитесь к Кольтире Ткачу Смерти на "Молот Оргрима", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Избавление от чумы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь ты управишься и без моей помощи, |3-6($r). Ты уже знаешь, как нейтрализовать вражеские чумные котлы.$b$bИди к Вратам Смерти, прибей пару-тройку мясистых великанов, набери жидкости из их хребтов и вылей ее в котлы, чтобы испортить всю партию этого чумного варева.$b$bБудем разить врага в самое сердце. Это очень важное задание, и его нужно выполнить любой ценой. Трудно сказать, сколько у тебя будет времени, но постарайся охватить побольше котлов.$b$bВеликанов и чумные котлы ты найдешь в Морд\'ретаре.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По приказу Кольтиры Ткача Смерти с "Молота Оргрима" отправляйтесь в Морд\'ретар и нейтрализуйте содержимое чумного котла с помощью пустулезной спинномозговой жидкости.$b$bПустулезная спинномозговая жидкость изготовляется из позвоночника великана. Его можно получить, убивая пустулезных ужасов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот и славно. Еще одним котлом меньше. Когда начнется сражение, в счет пойдет каждый котел.$B$BТвой командир будет доволен.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Приветствую, $C.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кольтире Ткачу Смерти на "Молот Оргрима", что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (13282,'Возвращение на поверхность','Теперь уходи. У меня за спиной есть портал – выходи через него на поверхность.$b$bМы еще встретимся. Он ведь будет тебя искать.$b$bИ найдет, рано или поздно.','Вернитесь к Кольтире Ткачу Смерти на борт "Молота Оргрима".') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение на поверхность',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь уходи. У меня за спиной есть портал – выходи через него на поверхность.$b$bМы еще встретимся. Он ведь будет тебя искать.$b$bИ найдет, рано или поздно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь к Кольтире Ткачу Смерти на борт "Молота Оргрима".',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13283,'Царь горы','Короче, $n, мне надо, чтобы ты $gзагнал:загнала; мой прыгобот на вершину вон той горы на юго-востоке, ясно?$b$bЭта их девчонка, самодовольная Фраззл Зуботеска, уверена, будто ее бот круче моего. Ха! Короче, у нас тут соревнование, кто сумеет стать царем горы!$b$bКак доберешься наверх, воткни наш боевой штандарт в груду костей, чтобы все видели, что Орда сильнее всех, а я – лучший изобретатель!','Используйте прыгобот Громбабаха, чтобы установить боевой штандарт Орды в груде черепов на вершине горы, по просьбе Бубуха Громбабаха.','Чего ты ждешь? У нас есть машины и боеприпасы... нам нужны только отважные канониры, чтобы применить их в деле.','Вернитесь к Бубуху Громбабаху в Имирхейм, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Царь горы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Короче, $n, мне надо, чтобы ты $gзагнал:загнала; мой прыгобот на вершину вон той горы на юго-востоке, ясно?$b$bЭта их девчонка, самодовольная Фраззл Зуботеска, уверена, будто ее бот круче моего. Ха! Короче, у нас тут соревнование, кто сумеет стать царем горы!$b$bКак доберешься наверх, воткни наш боевой штандарт в груду костей, чтобы все видели, что Орда сильнее всех, а я – лучший изобретатель!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте прыгобот Громбабаха, чтобы установить боевой штандарт Орды в груде черепов на вершине горы, по просьбе Бубуха Громбабаха.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Чего ты ждешь? У нас есть машины и боеприпасы... нам нужны только отважные канониры, чтобы применить их в деле.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бубуху Громбабаху в Имирхейм, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13284,'Атака пехоты','Приветствую тебя, |3-6($c).$B$BНаши войска несколько раз пытались взять Имирхейм штурмом, но врайкулы оказались куда более серьезным противником, чем все, кто прежде встречался нам. Не раз наши люди попадали в засады: мы потеряли многих и многих... $B$BЕсли ты $gготов: готова; взяться за это дело и провести моих бойцов к вратам Имирхейма, мы щедро и с радостью вознаградим тебя за помощь. Мы намерены разбить лагерь у ворот и там дождаться подкрепления.','Сопроводите войска "Усмирителя небес" к вратам Имирхейма. Выполнив задание, вернитесь на край ледника к востоку от Имирхейма к военачальнику Купу за наградой.','Вы благополучно достигли Имирхейма?','Вернитесь к командиру наземных войск Купу в Долину Потерянной Надежды, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Атака пехоты',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приветствую тебя, |3-6($c).$B$BНаши войска несколько раз пытались взять Имирхейм штурмом, но врайкулы оказались куда более серьезным противником, чем все, кто прежде встречался нам. Не раз наши люди попадали в засады: мы потеряли многих и многих... $B$BЕсли ты $gготов: готова; взяться за это дело и провести моих бойцов к вратам Имирхейма, мы щедро и с радостью вознаградим тебя за помощь. Мы намерены разбить лагерь у ворот и там дождаться подкрепления.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сопроводите войска "Усмирителя небес" к вратам Имирхейма. Выполнив задание, вернитесь на край ледника к востоку от Имирхейма к военачальнику Купу за наградой.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы благополучно достигли Имирхейма?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру наземных войск Купу в Долину Потерянной Надежды, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (13285,'Изготовление краеугольного камня','Ага! Значит, Храм Изобретений, трон самого Хранителя Мимира! Ну разумеется: где же еще следует соединять две части ключа, как не там?$b$bСогласно записям геолога, Храм Изобретений – одна из самых высоких точек с западной стороны Террасы Творцов. Короче, он должен быть примерно на восток от места крушения Гром\'арша.$b$bВстретимся с тобой у храма и соединим части ключа.','Встретьтесь с Бранном Бронзобородом в Храме Изобретений и помогите Бранну сложить вместе оболочку Норганнона и ядро Норганнона. После этого вернитесь к Боктару Кровавому Безумию на место крушения Гром\'арша.','<Вы рассказываете Боктару, как помогли Бранну отыскать части краеугольного камня и соединить их. Боктар одобрительно кивает.>\n\nДа, возможно, Бранн – тот самый союзник, который нужен нам, чтобы выяснить, что же на самом деле происходит в Ульдуаре. Правильно мы сделали, что помогли ему. Против этого Локена и его прихвостней, железных дворфов, никакая помощь не будет лишней.','Вернитесь к Боктару Кровавому Безумию на место крушения Гром\'арша, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Изготовление краеугольного камня',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ага! Значит, Храм Изобретений, трон самого Хранителя Мимира! Ну разумеется: где же еще следует соединять две части ключа, как не там?$b$bСогласно записям геолога, Храм Изобретений – одна из самых высоких точек с западной стороны Террасы Творцов. Короче, он должен быть примерно на восток от места крушения Гром\'арша.$b$bВстретимся с тобой у храма и соединим части ключа.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Встретьтесь с Бранном Бронзобородом в Храме Изобретений и помогите Бранну сложить вместе оболочку Норганнона и ядро Норганнона. После этого вернитесь к Боктару Кровавому Безумию на место крушения Гром\'арша.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Вы рассказываете Боктару, как помогли Бранну отыскать части краеугольного камня и соединить их. Боктар одобрительно кивает.>\n\nДа, возможно, Бранн – тот самый союзник, который нужен нам, чтобы выяснить, что же на самом деле происходит в Ульдуаре. Правильно мы сделали, что помогли ему. Против этого Локена и его прихвостней, железных дворфов, никакая помощь не будет лишней.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Боктару Кровавому Безумию на место крушения Гром\'арша, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13286,'Хоть какая-нибудь помощь!','Тяжкие времена настали, |3-6($c)...$b$bКак ни неприятно это признавать, я готов принять помощь от кого угодно, даже от нашего рыцаря смерти.$b$bСтупай к Тассариану и спроси, не согласится ли он помочь нам разработать тактику борьбы с Плетью, которая могла бы обеспечить победу.$b$bМы забрались слишком далеко... мы не можем потерпеть поражение!','Поговорите с Тассарианом по просьбе старшего капитана Джастина Бартлетта на борту "Усмирителя небес".','Капитан Бартлетт поступил мудро, прислав тебя ко мне.$B$BСам он слишком поглощен противостоянием с Ордой, но кому-то нужно полностью сосредоточиться на нашей главной миссии: взятии цитадели Ледяной Короны!$B$BКто же сумеет дать тебе лучший совет, как не бывший слуга Короля-лича?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хоть какая-нибудь помощь!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тяжкие времена настали, |3-6($c)...$b$bКак ни неприятно это признавать, я готов принять помощь от кого угодно, даже от нашего рыцаря смерти.$b$bСтупай к Тассариану и спроси, не согласится ли он помочь нам разработать тактику борьбы с Плетью, которая могла бы обеспечить победу.$b$bМы забрались слишком далеко... мы не можем потерпеть поражение!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Тассарианом по просьбе старшего капитана Джастина Бартлетта на борту "Усмирителя небес".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Капитан Бартлетт поступил мудро, прислав тебя ко мне.$B$BСам он слишком поглощен противостоянием с Ордой, но кому-то нужно полностью сосредоточиться на нашей главной миссии: взятии цитадели Ледяной Короны!$B$BКто же сумеет дать тебе лучший совет, как не бывший слуга Короля-лича?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13287,'Тычки и тумаки','Тебе, при твоем богатом опыте, несомненно, известно, что лучший способ побольше разузнать о противнике – это сойтись с ним в бою.$b$bТы, несомненно, жаждешь обрести славу, взяв цитадель Ледяной Короны, но это невозможно сделать, пока не будут взяты все ворота Короля-лича. И для начала тебе следует сосредоточить свои усилия на первых из них...$b$bВозвращайся на Прорванный фронт. Вступи в бой с врагом. Отыщи в обороне противника брешь, которой мы могли бы воспользоваться, и возвращайся ко мне с подробным отчетом.','Убейте 5 неповоротливых поганищ, 5 злокозненных некромантов и 5 адептов Тьмы по просьбе Тассариана, находящегося на борту "Усмирителя небес", боевого корабля Альянса.','Ты $Gвернулся:вернулась;, $C...$B$BНе о чем сообщить?','Вернитесь к Тассариану на "Усмиритель небес", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тычки и тумаки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе, при твоем богатом опыте, несомненно, известно, что лучший способ побольше разузнать о противнике – это сойтись с ним в бою.$b$bТы, несомненно, жаждешь обрести славу, взяв цитадель Ледяной Короны, но это невозможно сделать, пока не будут взяты все ворота Короля-лича. И для начала тебе следует сосредоточить свои усилия на первых из них...$b$bВозвращайся на Прорванный фронт. Вступи в бой с врагом. Отыщи в обороне противника брешь, которой мы могли бы воспользоваться, и возвращайся ко мне с подробным отчетом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 5 неповоротливых поганищ, 5 злокозненных некромантов и 5 адептов Тьмы по просьбе Тассариана, находящегося на борту "Усмирителя небес", боевого корабля Альянса.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gвернулся:вернулась;, $C...$B$BНе о чем сообщить?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тассариану на "Усмиритель небес", что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13288,'Как все погано!','Используйте набор для оживления, чтобы воскресить поганище и убить с его помощью 15 ледяных вурдалаков, 15 агрессивных упырей и 15 восставших солдат Альянса по просьбе Тассариана с "Усмирителя Небес".','Так, $R?$B$Bтвои поганища оказались эффективными?','Вернитесь к Тассариану на "Усмиритель небес", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Как все погано!',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте набор для оживления, чтобы воскресить поганище и убить с его помощью 15 ледяных вурдалаков, 15 агрессивных упырей и 15 восставших солдат Альянса по просьбе Тассариана с "Усмирителя Небес".',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Так, $R?$B$Bтвои поганища оказались эффективными?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тассариану на "Усмиритель небес", что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13289,'Как все погано!','Ты знаешь, что делать, |3-6($c).$b$bВозьми этот набор и используй внутренности поганищ, чтобы создать свое собственное, а потом прикажи ему атаковать вражеские силы у врат.$b$bТебе стоит отработать эту тактику к тому времени, как мы пойдем на штурм врат.','Используйте набор для оживления, чтобы воскресить поганище и убить с его помощью 15 ледяных вурдалаков, 15 агрессивных упырей и 15 восставших солдат Альянса по просьбе Тассариана с "Усмирителя небес".','Я вижу, ты все лучше управляешься с поганищами!$B$BПри должном усердии с твоей стороны Альянс, глядишь, скоро возьмет врата.','Да, $C?','Вернитесь к Тассариану на "Усмиритель небес", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Как все погано!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты знаешь, что делать, |3-6($c).$b$bВозьми этот набор и используй внутренности поганищ, чтобы создать свое собственное, а потом прикажи ему атаковать вражеские силы у врат.$b$bТебе стоит отработать эту тактику к тому времени, как мы пойдем на штурм врат.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте набор для оживления, чтобы воскресить поганище и убить с его помощью 15 ледяных вурдалаков, 15 агрессивных упырей и 15 восставших солдат Альянса по просьбе Тассариана с "Усмирителя небес".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я вижу, ты все лучше управляешься с поганищами!$B$BПри должном усердии с твоей стороны Альянс, глядишь, скоро возьмет врата.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да, $C?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тассариану на "Усмиритель небес", что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (13290,'Немного внимания','Главный инженер Болтоключ за время службы на "Рассекателе туч" проявил себя как совершенно незаменимый специалист. Если бы не его изобретательность, нас бы давно размазало тонким слоем по всему леднику.$b$bНо проблема в том, что он считает нужным делиться со мной любым своим открытием или изобретением, хотя я в этом практически ничего не понимаю.$b$bА сейчас мне и подавно не до того: все мои мысли заняты врагами. Я не могу допустить, чтобы меня отвлекали!$b$bПожалуйста, сходи к нему вместо меня, $n. И, если он попросит у тебя помощи, помоги ему, чем сумеешь. Он сейчас внизу, в трюме.','Поговорите с главным инженером Болтоключом на борту "Усмирителя небес" по просьбе старшего капитана Джастина Бартлетта.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Немного внимания',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Главный инженер Болтоключ за время службы на "Рассекателе туч" проявил себя как совершенно незаменимый специалист. Если бы не его изобретательность, нас бы давно размазало тонким слоем по всему леднику.$b$bНо проблема в том, что он считает нужным делиться со мной любым своим открытием или изобретением, хотя я в этом практически ничего не понимаю.$b$bА сейчас мне и подавно не до того: все мои мысли заняты врагами. Я не могу допустить, чтобы меня отвлекали!$b$bПожалуйста, сходи к нему вместо меня, $n. И, если он попросит у тебя помощи, помоги ему, чем сумеешь. Он сейчас внизу, в трюме.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с главным инженером Болтоключом на борту "Усмирителя небес" по просьбе старшего капитана Джастина Бартлетта.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13291,'Заимствованная технология','Понял, все понял! Шеф сейчас слишком занят, ему не до меня. Что ж, тем хуже для него!$b$bСлушай, мне тут удалось... э-э... позаимствовать у противника запас некоего раствора. Я, конечно, терпеть не могу возиться с примитивными гоблинскими технологиями, но в данном случае я готов сделать исключение.$b$bВозьми этот образец. Проведи для меня несколько испытаний – чисто чтобы убедиться, что это действительно полезная штука, – а я тем временем попытаюсь выяснить состав вещества, чтобы получить возможность его воспроизвести.$b$bСтупай на фронт и собери то, что может послужить приманкой, потом используй масло.','Используйте краденый раствор на Прорванном фронте по просьбе главного инженера Болтоключа на борту "Усмирителя небес".$b$bДля этого вам понадобится брошенный шлем, брошенная броня и груда костей. Все это можно найти на Прорванном фронте.','Отличные новости!$B$BА мне удалось изготовить такой раствор самому. Хотя это, конечно, не особо крупное достижение.$B$BВряд ли я доживу до того дня, когда тупоголовые гоблины сумеют сварить какое-то снадобье, которое гном не сможет воспроизвести одной левой, с закрытыми глазами!','Ну как дела, $R?','Вернитесь к главному инженеру Болтоключу на "Усмиритель небес", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Заимствованная технология',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Понял, все понял! Шеф сейчас слишком занят, ему не до меня. Что ж, тем хуже для него!$b$bСлушай, мне тут удалось... э-э... позаимствовать у противника запас некоего раствора. Я, конечно, терпеть не могу возиться с примитивными гоблинскими технологиями, но в данном случае я готов сделать исключение.$b$bВозьми этот образец. Проведи для меня несколько испытаний – чисто чтобы убедиться, что это действительно полезная штука, – а я тем временем попытаюсь выяснить состав вещества, чтобы получить возможность его воспроизвести.$b$bСтупай на фронт и собери то, что может послужить приманкой, потом используй масло.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте краденый раствор на Прорванном фронте по просьбе главного инженера Болтоключа на борту "Усмирителя небес".$b$bДля этого вам понадобится брошенный шлем, брошенная броня и груда костей. Все это можно найти на Прорванном фронте.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличные новости!$B$BА мне удалось изготовить такой раствор самому. Хотя это, конечно, не особо крупное достижение.$B$BВряд ли я доживу до того дня, когда тупоголовые гоблины сумеют сварить какое-то снадобье, которое гном не сможет воспроизвести одной левой, с закрытыми глазами!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как дела, $R?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к главному инженеру Болтоключу на "Усмиритель небес", что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13292,'Решение проблемы','А, да-да. С возвращением. Лишняя практика никогда не повредит, ведь так?$B$BА вот и оно, решение проблемы этих мерзких ледяных змеев.$B$BПрореди их ряды, |3-6($r). Чем больше этих монстров погибнет сейчас, тем меньше останется, чтобы противостоять нам во время штурма цитадели.$B$BВот, возьми этот раствор и используй по назначению. А что не используешь, принеси обратно.','Используйте краденый раствор на Прорванном фронте по просьбе главного инженера Болтоключа на борту "Усмирителя небес".$b$bДля этого вам понадобится брошенный шлем, брошенная броня и груда костей. Все это можно найти на Прорванном фронте.','Молодец! Просто молодчина! Ты превращаешься в настоящего истребителя змеев!$B$BВозвращайся, когда будешь готов еще разок проредить их ряды.','Да, друг?','Вернитесь к главному инженеру Болтоключу на "Усмиритель небес", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Решение проблемы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А, да-да. С возвращением. Лишняя практика никогда не повредит, ведь так?$B$BА вот и оно, решение проблемы этих мерзких ледяных змеев.$B$BПрореди их ряды, |3-6($r). Чем больше этих монстров погибнет сейчас, тем меньше останется, чтобы противостоять нам во время штурма цитадели.$B$BВот, возьми этот раствор и используй по назначению. А что не используешь, принеси обратно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте краденый раствор на Прорванном фронте по просьбе главного инженера Болтоключа на борту "Усмирителя небес".$b$bДля этого вам понадобится брошенный шлем, брошенная броня и груда костей. Все это можно найти на Прорванном фронте.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Молодец! Просто молодчина! Ты превращаешься в настоящего истребителя змеев!$B$BВозвращайся, когда будешь готов еще разок проредить их ряды.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да, друг?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к главному инженеру Болтоключу на "Усмиритель небес", что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13293,'В Имирхейм!','Тебе нужно спуститься в Имирхейм, большой поселок ледяных врайкулов посреди Ледяной Короны.$b$bТам, на западной окраине поселка, находится наш парень, Бубух Громбабах. Он представляет армию Песни Войны в состязании с Альянсом. Проверяют, чей прыгобот лучше, наш или ихний.$b$bСмотри, $n, не подведи нас! На карту поставлена профессиональная честь гоблинских изобретателей! Кроме того, все наши ребята на тебя рассчитывают.$b$bИ, опять же, мы поставили деньги на то, что ты сумеешь отпинать этих трусов!','Поговорите с Бубухом Громбабахом в Имирхейме.','Ох, как же я рад тебя видеть? Тебя старшой прислал из Молота?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В Имирхейм!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе нужно спуститься в Имирхейм, большой поселок ледяных врайкулов посреди Ледяной Короны.$b$bТам, на западной окраине поселка, находится наш парень, Бубух Громбабах. Он представляет армию Песни Войны в состязании с Альянсом. Проверяют, чей прыгобот лучше, наш или ихний.$b$bСмотри, $n, не подведи нас! На карту поставлена профессиональная честь гоблинских изобретателей! Кроме того, все наши ребята на тебя рассчитывают.$b$bИ, опять же, мы поставили деньги на то, что ты сумеешь отпинать этих трусов!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Бубухом Громбабахом в Имирхейме.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ох, как же я рад тебя видеть? Тебя старшой прислал из Молота?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13294,'Борьба с великанами','Конечно, очень важно разгромить Плеть на поле битвы, но все-таки не следует пренебрегать и самими воротами.$b$bМясистые великаны, что обороняют укрепления, могут швырять массивные валуны и куски льда, нанося разрушительный урон вражеской пехоте.$b$bСоберись с силами и уничтожь этих великанов. Нам надо знать, насколько они сильны, чтобы предвидеть, с чем предстоит иметь дело.$b$bДа, и кстати, принеси мне их позвоночники. Если память мне не изменяет, с ними можно проделать одну любопытную штуку... Тебя я, конечно, тоже этому научу.','Принесите Тассариану с "Усмирителя небес" 5 позвоночников пустулезных ужасов из Морд\'ретара.','Великолепно. Похоже, это именно то, что надо.$B$BВсегда следует по возможности бить врага его же оружием...','Ну что, |3-6($R), удалось ли тебе одолеть великанов?','Вернитесь к Тассариану на "Усмиритель небес", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Борьба с великанами',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Конечно, очень важно разгромить Плеть на поле битвы, но все-таки не следует пренебрегать и самими воротами.$b$bМясистые великаны, что обороняют укрепления, могут швырять массивные валуны и куски льда, нанося разрушительный урон вражеской пехоте.$b$bСоберись с силами и уничтожь этих великанов. Нам надо знать, насколько они сильны, чтобы предвидеть, с чем предстоит иметь дело.$b$bДа, и кстати, принеси мне их позвоночники. Если память мне не изменяет, с ними можно проделать одну любопытную штуку... Тебя я, конечно, тоже этому научу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Тассариану с "Усмирителя небес" 5 позвоночников пустулезных ужасов из Морд\'ретара.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Великолепно. Похоже, это именно то, что надо.$B$BВсегда следует по возможности бить врага его же оружием...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, |3-6($R), удалось ли тебе одолеть великанов?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тассариану на "Усмиритель небес", что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13295,'Основы химии','<Тассариан берет гноящиеся позвоночники и сливает из них жидкость во фляжку.>$B$BМалоизвестное свойство мясистых великанов...$B$BИх спинномозговая жидкость взаимодействует с чумой весьма любопытным образом: на выходе получается очень едкая кислота.$B$BЕсли разлить ее вниз с укреплений, войскам, что внизу, это не понравится, но зато жертвы уже не встанут и не пополнят собой ряды противника.$b$bВылей содержимое этой фляги в один из чумных котлов в западном караульном помещении Врат Смерти.','Вылейте пустулезную спинномозговую жидкость в чумной котел в Морд\'ретаре по просьбе Тассариана на борту "Усмирителя небес".','Прекрасно, |3-6($C)!$B$BКогда наши войска двинутся на штурм цитадели, у нас будет готовый план по взятию Врат Смерти...','Тебе удалось нейтрализовать чуму, $C?','Вернитесь к Тассариану на "Усмиритель небес", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Основы химии',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Тассариан берет гноящиеся позвоночники и сливает из них жидкость во фляжку.>$B$BМалоизвестное свойство мясистых великанов...$B$BИх спинномозговая жидкость взаимодействует с чумой весьма любопытным образом: на выходе получается очень едкая кислота.$B$BЕсли разлить ее вниз с укреплений, войскам, что внизу, это не понравится, но зато жертвы уже не встанут и не пополнят собой ряды противника.$b$bВылей содержимое этой фляги в один из чумных котлов в западном караульном помещении Врат Смерти.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вылейте пустулезную спинномозговую жидкость в чумной котел в Морд\'ретаре по просьбе Тассариана на борту "Усмирителя небес".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно, |3-6($C)!$B$BКогда наши войска двинутся на штурм цитадели, у нас будет готовый план по взятию Врат Смерти...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось нейтрализовать чуму, $C?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тассариану на "Усмиритель небес", что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13296,'В Имирхейм!','Тебе нужно спуститься в Имирхейм, большой поселок ледяных врайкулов посреди Ледяной Короны.$b$bТам, на южной окраине поселка, находится Фраззл Зуботеска. Она представляет Экспедицию Отважных в состязании с этими ордынскими уродами. Проверяют, чей прыгобот лучше, наш или ихний.$b$bСмотри, $n, не подведи нас! На карту поставлена профессиональная честь гномских изобретателей! Кроме того, все наши ребята на тебя рассчитывают.$b$bИ, опять же, мы поставили деньги на то, что ты сумеешь отпинать этих трусов!','Поговорите с Фраззл Зуботеской в Имирхейме.','А, тебя прислал наш главный с "Усмирителя небес"? Очень мило с его стороны!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В Имирхейм!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе нужно спуститься в Имирхейм, большой поселок ледяных врайкулов посреди Ледяной Короны.$b$bТам, на южной окраине поселка, находится Фраззл Зуботеска. Она представляет Экспедицию Отважных в состязании с этими ордынскими уродами. Проверяют, чей прыгобот лучше, наш или ихний.$b$bСмотри, $n, не подведи нас! На карту поставлена профессиональная честь гномских изобретателей! Кроме того, все наши ребята на тебя рассчитывают.$b$bИ, опять же, мы поставили деньги на то, что ты сумеешь отпинать этих трусов!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Фраззл Зуботеской в Имирхейме.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, тебя прислал наш главный с "Усмирителя небес"? Очень мило с его стороны!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13297,'Избавление от чумы','По приказу Тассариана с "Усмирителя небес" отправляйтесь в Морд\'ретар и нейтрализуйте содержимое чумного котла с помощью пустулезной спинномозговой жидкости.$b$bПустулезная спинномозговая жидкость изготовляется из позвоночника великана. Его можно получить, убивая пустулезных ужасов.','Что ж, можно не опасаться еще одного чумного котла в тот час, когда начнется битва.$B$BПолагаю, твой командир будет доволен.','Приветствую, $C.','Вернитесь к Тассариану на "Усмиритель небес", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Избавление от чумы',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По приказу Тассариана с "Усмирителя небес" отправляйтесь в Морд\'ретар и нейтрализуйте содержимое чумного котла с помощью пустулезной спинномозговой жидкости.$b$bПустулезная спинномозговая жидкость изготовляется из позвоночника великана. Его можно получить, убивая пустулезных ужасов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что ж, можно не опасаться еще одного чумного котла в тот час, когда начнется битва.$B$BПолагаю, твой командир будет доволен.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Приветствую, $C.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тассариану на "Усмиритель небес", что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13298,'Корпой Оскверненный','$C, до меня дошли известия о том, что у Врат Смерти появился новый могучий зомби.$b$bМы не можем сидеть сложа руки, когда нам угрожает такой серьезный противник. Любые сведения о нем, какие тебе удастся раздобыть, – лучше, чем ничего.$b$bСтупай в западное караульное помещение у врат и найди это существо. Сразись с ним и отыщи брешь в его защите, которой мы могли бы воспользоваться.','Убейте Корпоя Оскверненного из Морд\'ретара по просьбе Тассариана с "Усмирителя небес".','Отлично, |3-6($C)!$B$BБыть может, проведя исследования, мы сумеем выяснить, как они изготовляют подобных созданий.','Тебе удалось найти зомби, $C?','Вернитесь к Тассариану на "Усмиритель небес", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Корпой Оскверненный',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$C, до меня дошли известия о том, что у Врат Смерти появился новый могучий зомби.$b$bМы не можем сидеть сложа руки, когда нам угрожает такой серьезный противник. Любые сведения о нем, какие тебе удастся раздобыть, – лучше, чем ничего.$b$bСтупай в западное караульное помещение у врат и найди это существо. Сразись с ним и отыщи брешь в его защите, которой мы могли бы воспользоваться.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Корпоя Оскверненного из Морд\'ретара по просьбе Тассариана с "Усмирителя небес".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, |3-6($C)!$B$BБыть может, проведя исследования, мы сумеем выяснить, как они изготовляют подобных созданий.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось найти зомби, $C?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тассариану на "Усмиритель небес", что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13300,'Рабы саронитовых шахт','Наш народ был порабощен и отправлен на саронитовые шахты Имирхейма, оплота врайкулов в центре Ледяной Короны. Король-лич заставляет рабов день и ночь добывать эту проклятую руду. $B$BЯ обещал верховному лорду Фордрингу, что мы поможем этим беднягам выбраться из рудников; именно этим мы и займемся. $B$BУвы, мне было приказано оставаться на этом корабле – как посланнику к Экспедиции Отважных. Может быть, вместо меня рабов спасешь ты, $n?','Абсалан Благочестивый, находящийся на борту "Усмирителя небес", просит вас освободить 10 рабов из саронитовых шахт.','Я не получал сообщений о том, что наши люди возвращаются в Серебряный Авангард.$B$BТы $Gуверен:уверена;, что $Gбыл:была; в Имирхейме, чтобы освободить их?','Вернитесь к Абсалану Благочестивому на "Усмиритель небес", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рабы саронитовых шахт',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наш народ был порабощен и отправлен на саронитовые шахты Имирхейма, оплота врайкулов в центре Ледяной Короны. Король-лич заставляет рабов день и ночь добывать эту проклятую руду. $B$BЯ обещал верховному лорду Фордрингу, что мы поможем этим беднягам выбраться из рудников; именно этим мы и займемся. $B$BУвы, мне было приказано оставаться на этом корабле – как посланнику к Экспедиции Отважных. Может быть, вместо меня рабов спасешь ты, $n?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Абсалан Благочестивый, находящийся на борту "Усмирителя небес", просит вас освободить 10 рабов из саронитовых шахт.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я не получал сообщений о том, что наши люди возвращаются в Серебряный Авангард.$B$BТы $Gуверен:уверена;, что $Gбыл:была; в Имирхейме, чтобы освободить их?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Абсалану Благочестивому на "Усмиритель небес", что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13301,'Атака пехоты','Приветствую тебя, |3-6($c).$B$BНаши войска несколько раз пытались взять Имирхейм штурмом, но врайкулы оказались куда более серьезным противником, чем все, кто прежде встречался нам. Не раз наши люди попадали в засады: мы потеряли многих и многих... $B$BЕсли ты $gготов: готова; взяться за это дело и провести моих бойцов к вратам Имирхейма, мы щедро и с радостью вознаградим тебя за помощь. Мы намерены разбить лагерь у ворот и там дождаться подкрепления.','Сопроводите кор\'кронские войска к вратам Имирхейма. Выполнив задание, вернитесь на край ледника к северу от Имирхейма к командиру наземных войск Ксутье за наградой.','Чего ты ждешь? У нас есть машины и боеприпасы... нам нужны только отважные канониры, чтобы применить их в деле.','Вернитесь к командиру наземных войск Ксутье в Зону бомбардировки, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Атака пехоты',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приветствую тебя, |3-6($c).$B$BНаши войска несколько раз пытались взять Имирхейм штурмом, но врайкулы оказались куда более серьезным противником, чем все, кто прежде встречался нам. Не раз наши люди попадали в засады: мы потеряли многих и многих... $B$BЕсли ты $gготов: готова; взяться за это дело и провести моих бойцов к вратам Имирхейма, мы щедро и с радостью вознаградим тебя за помощь. Мы намерены разбить лагерь у ворот и там дождаться подкрепления.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сопроводите кор\'кронские войска к вратам Имирхейма. Выполнив задание, вернитесь на край ледника к северу от Имирхейма к командиру наземных войск Ксутье за наградой.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Чего ты ждешь? У нас есть машины и боеприпасы... нам нужны только отважные канониры, чтобы применить их в деле.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру наземных войск Ксутье в Зону бомбардировки, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13302,'Рабы саронитовых шахт','Наш народ был порабощен и отправлен на саронитовые шахты Имирхейма, оплота врайкулов в центре Ледяной Короны. Король-лич заставляет рабов день и ночь добывать эту проклятую руду. $B$BЯ обещал верховному лорду Фордрингу, что мы поможем этим беднягам выбраться из рудников; именно этим мы и займемся. $B$BК сожалению, мне было приказано оставаться на этом корабле – как посланнику к армии Песни Войны. Может быть, вместо меня рабов спасешь ты, $n?','Брат Келтан, находящийся на борту "Молота Оргрима", просит вас освободить 10 рабов из саронитовых шахт.','Я не получал сообщений о том, что наши люди возвращаются в Серебряный Авангард.$B$BТы $Gуверен:уверена;, что $Gбыл:была; в Имирхейме, чтобы освободить их?','Вернитесь к брату Келтану на "Молот Оргрима", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рабы саронитовых шахт',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наш народ был порабощен и отправлен на саронитовые шахты Имирхейма, оплота врайкулов в центре Ледяной Короны. Король-лич заставляет рабов день и ночь добывать эту проклятую руду. $B$BЯ обещал верховному лорду Фордрингу, что мы поможем этим беднягам выбраться из рудников; именно этим мы и займемся. $B$BК сожалению, мне было приказано оставаться на этом корабле – как посланнику к армии Песни Войны. Может быть, вместо меня рабов спасешь ты, $n?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Брат Келтан, находящийся на борту "Молота Оргрима", просит вас освободить 10 рабов из саронитовых шахт.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я не получал сообщений о том, что наши люди возвращаются в Серебряный Авангард.$B$BТы $Gуверен:уверена;, что $Gбыл:была; в Имирхейме, чтобы освободить их?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к брату Келтану на "Молот Оргрима", что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13304,'Ремонт в полевых условиях','Мы атакуем, и Плеть отступает, $n. Надо воспользоваться моментом и закрепить наш успех.$B$BЭта долина под нами... кстати сказать, стратегически важный объект... открыта для всех. В юго-восточном конце долины Потерянной Надежды мы обнаружили разобранный разрушитель. Мы полагаем, что он в рабочем состоянии, но, безусловно, нуждается в ремонте.$B$BЕсли сумеешь забрать недостающие детали у этих падальщиков из Плети, у тебя должно получиться запустить разрушитель. Даже один разрушитель в рабочем состоянии может нанести ощутимый ущерб пехоте противника.','Кольтира Ткач Смерти с "Молота Оргрима" хочет, чтобы вы отобрали 5 деталей разрушителя у мусорных упырей в долине Потерянной Надежды и отнесли их к сломанному разрушителю.','Этот разрушитель знавал лучшие дни, но основной механизм вроде бы не поврежден. Во всяком случае, он поддается ремонту. Деталей, которые ты принес, должно быть достаточно, чтобы запустить его вновь. Он будет работать... пусть и недолго.','Разрушитель сильно пострадал.','Вернитесь к сломанному разрушителю в Долину Потерянной Надежды, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ремонт в полевых условиях',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы атакуем, и Плеть отступает, $n. Надо воспользоваться моментом и закрепить наш успех.$B$BЭта долина под нами... кстати сказать, стратегически важный объект... открыта для всех. В юго-восточном конце долины Потерянной Надежды мы обнаружили разобранный разрушитель. Мы полагаем, что он в рабочем состоянии, но, безусловно, нуждается в ремонте.$B$BЕсли сумеешь забрать недостающие детали у этих падальщиков из Плети, у тебя должно получиться запустить разрушитель. Даже один разрушитель в рабочем состоянии может нанести ощутимый ущерб пехоте противника.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Кольтира Ткач Смерти с "Молота Оргрима" хочет, чтобы вы отобрали 5 деталей разрушителя у мусорных упырей в долине Потерянной Надежды и отнесли их к сломанному разрушителю.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Этот разрушитель знавал лучшие дни, но основной механизм вроде бы не поврежден. Во всяком случае, он поддается ремонту. Деталей, которые ты принес, должно быть достаточно, чтобы запустить его вновь. Он будет работать... пусть и недолго.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Разрушитель сильно пострадал.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к сломанному разрушителю в Долину Потерянной Надежды, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13305,'Все к худшему','Зачем тебе эта машина? С Плетью воевать? Машинами Плеть не одолеешь.$b$bТы можешь уничтожить сотни... да что там, даже тысячи воинов Плети! Но саму Плеть тебе не победить.$b$bКогда наиграешься вдоволь, ступай на север. Я встречусь с тобой возле заброшенного военного лагеря. И там я покажу тебе кое-что, чтобы ты $gпонял:поняла;, с чем имеешь дело.','Используйте отремонтированный разрушитель, чтобы уничтожить 150 изгнивших вурдалаков, 20 ледотленных волхвов и 2 костяных великана в долине Потерянной Надежды. Выполнив эту задачу, поговорите с Матиасом Нетлером в лагере сопротивления первого легиона.','Ты $Gзакончил:закончила; играть боевыми машинами?','Вернитесь к Матиасу Нетлеру в Долину Потерянной Надежды, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Все к худшему',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Зачем тебе эта машина? С Плетью воевать? Машинами Плеть не одолеешь.$b$bТы можешь уничтожить сотни... да что там, даже тысячи воинов Плети! Но саму Плеть тебе не победить.$b$bКогда наиграешься вдоволь, ступай на север. Я встречусь с тобой возле заброшенного военного лагеря. И там я покажу тебе кое-что, чтобы ты $gпонял:поняла;, с чем имеешь дело.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте отремонтированный разрушитель, чтобы уничтожить 150 изгнивших вурдалаков, 20 ледотленных волхвов и 2 костяных великана в долине Потерянной Надежды. Выполнив эту задачу, поговорите с Матиасом Нетлером в лагере сопротивления первого легиона.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gзакончил:закончила; играть боевыми машинами?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Матиасу Нетлеру в Долину Потерянной Надежды, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13306,'Строим баррикады!','Когда наши войска продвинутся за Алдур\'тар, они окажутся уязвимы для атак с Железного вала и большого ледника под ним.$b$bДля строительства нормальных укреплений у нас нет ни времени, ни материалов, однако мы можем возвести хотя бы баррикады, чтобы защитить наших бойцов от обстрела и сдержать атаки Плети.$b$bОтправляйся с этим набором для строительства баррикад в долину Павших Героев, к западу от Алдур\'тара. Отыщи установленные мной метки и сооруди на их месте баррикады.','Постройте 8 баррикад с помощью комплекта для возведения баррикад по просьбе Кольтиры Ткача Смерти, находящегося на борту "Молота Оргрима".','Ты $Gпостроил:построила; эти баррикады?','Вернитесь к Кольтире Ткачу Смерти на "Молот Оргрима", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Строим баррикады!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда наши войска продвинутся за Алдур\'тар, они окажутся уязвимы для атак с Железного вала и большого ледника под ним.$b$bДля строительства нормальных укреплений у нас нет ни времени, ни материалов, однако мы можем возвести хотя бы баррикады, чтобы защитить наших бойцов от обстрела и сдержать атаки Плети.$b$bОтправляйся с этим набором для строительства баррикад в долину Павших Героев, к западу от Алдур\'тара. Отыщи установленные мной метки и сооруди на их месте баррикады.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Постройте 8 баррикад с помощью комплекта для возведения баррикад по просьбе Кольтиры Ткача Смерти, находящегося на борту "Молота Оргрима".',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gпостроил:построила; эти баррикады?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кольтире Ткачу Смерти на "Молот Оргрима", что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13307,'Окровавленные знамена','В долине Павших Героев и на леднике Ледяной Короны, к западу от Алдур\'тара, Плеть пытается использовать против нас убитых. Слуги Плети пробудили мертвецов, спавших в долине, и наделили их невероятной силой и яростью. Источниками этой силы являются знамена, которые хранят у себя предводители Плети в районе ледника. Убей этих знаменосцев, и павшие герои, которых они возглавляют, лишатся своей сверхъестественной силы.$b$bИменно тебе выпало избавить нас от этого препятствия и расчистить путь нашим основным силам.','Убейте 5 знаменосцев Плети, 5 обратителей Плети и 20 обращенных героев по просьбе Кольтиры Ткача Смерти, который находится на борту "Молота Оргрима".','Ты $Gубил:убила; знаменосцев и $Gпресек:присекла; их попытки использовать павших против нас?','Вернитесь к Кольтире Ткачу Смерти на "Молот Оргрима", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Окровавленные знамена',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В долине Павших Героев и на леднике Ледяной Короны, к западу от Алдур\'тара, Плеть пытается использовать против нас убитых. Слуги Плети пробудили мертвецов, спавших в долине, и наделили их невероятной силой и яростью. Источниками этой силы являются знамена, которые хранят у себя предводители Плети в районе ледника. Убей этих знаменосцев, и павшие герои, которых они возглавляют, лишатся своей сверхъестественной силы.$b$bИменно тебе выпало избавить нас от этого препятствия и расчистить путь нашим основным силам.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 5 знаменосцев Плети, 5 обратителей Плети и 20 обращенных героев по просьбе Кольтиры Ткача Смерти, который находится на борту "Молота Оргрима".',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gубил:убила; знаменосцев и $Gпресек:присекла; их попытки использовать павших против нас?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кольтире Ткачу Смерти на "Молот Оргрима", что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13308,'Игры разума','Добудьте ключ штейгера от оков темного проповедника Р\'кхема в Саронитовых шахтах.','Сослужи мне эту службу – и получишь щедрую награду.$B$B<Темный проповедник проецирует в ваше сознание умиротворяющие вибрации покоя.>$B$BОсвободи меня! Даю слово, ты не пожалеешь.','Вернитесь к темному проповеднику Р\'кхему в Саронитовые шахты, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Игры разума',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте ключ штейгера от оков темного проповедника Р\'кхема в Саронитовых шахтах.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Сослужи мне эту службу – и получишь щедрую награду.$B$B<Темный проповедник проецирует в ваше сознание умиротворяющие вибрации покоя.>$B$BОсвободи меня! Даю слово, ты не пожалеешь.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к темному проповеднику Р\'кхему в Саронитовые шахты, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13309,'Воздушный десант','У меня есть несколько ребят, подготовленных к заброске в Имирхейм. Мне нужно, чтобы десант был сброшен, и все прошло благополучно.$B$BУ врайкулов, обороняющих крепость, есть какие-то хитрые автоматические копьеметы. Они лупят по нашим самолетам и не дают им приблизиться. Наши инженеры установили на транспортном самолете подавительную пушку для нейтрализации этих копьеметов – просто дай пару залпов, и дым собьет их с прицела, а заодно и заблокирует механизмы.$B$BВ общем, пали из пушки и позаботься о том, чтобы все мои парни десантировались благополучно.','По приказу командира Купа, который расположился на склоне ледника к востоку от Имирхейма, воспользуйтесь подавительной пушкой "Усмирителя небес". Обеспечьте прикрытие для транспортного самолета, пока тот будет высаживать десант.','Отлично, ты молодец. Побольше бы нам таких воинов! Кстати, приходи завтра – может быть, для тебя будет новое задание.','Ты $Gзатащил:затащила; моих мальчиков внутрь?','Вернитесь к командиру наземных войск Купу в Долину Потерянной Надежды, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Воздушный десант',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У меня есть несколько ребят, подготовленных к заброске в Имирхейм. Мне нужно, чтобы десант был сброшен, и все прошло благополучно.$B$BУ врайкулов, обороняющих крепость, есть какие-то хитрые автоматические копьеметы. Они лупят по нашим самолетам и не дают им приблизиться. Наши инженеры установили на транспортном самолете подавительную пушку для нейтрализации этих копьеметов – просто дай пару залпов, и дым собьет их с прицела, а заодно и заблокирует механизмы.$B$BВ общем, пали из пушки и позаботься о том, чтобы все мои парни десантировались благополучно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По приказу командира Купа, который расположился на склоне ледника к востоку от Имирхейма, воспользуйтесь подавительной пушкой "Усмирителя небес". Обеспечьте прикрытие для транспортного самолета, пока тот будет высаживать десант.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, ты молодец. Побольше бы нам таких воинов! Кстати, приходи завтра – может быть, для тебя будет новое задание.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gзатащил:затащила; моих мальчиков внутрь?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру наземных войск Купу в Долину Потерянной Надежды, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13310,'Воздушный десант','Ну, ладно, мелочь пузатая, есть у меня для тебя кое-какая работенка. Должна же быть от тебя какая-то польза, верно?$B$BДесант наших лучших разведчиков готов к заброске в Имирхейм. Тамошние врайкулы вооружены автоматическими копьеметами, которые разносят наш транспорт в клочья, но у нас очень толковые инженеры на "Молоте Оргрима", они создали блокиратор огня.$B$BТы будешь нашим канониром. Дашь несколько залпов по их копьеметам, чтобы создать им плохую видимость и заблокировать их механизмы. Твоя задача: сделать так, чтобы десант был сброшен благополучно, и чтобы наш транспортный аппарат вернулся на базу в целости и сохранности.','Командир наземных войск Ксутья на краю ледника возле Имирхейма приказал вам использовать кор\'кронскую заградительную пушку, чтобы обеспечить прикрытие для кор\'кронского транспортника, так чтобы десант был сброшен, а транспортный самолет остался целым.','Выходит, ты хоть на что-то годишься. Хвалю. Молодец.','Чего ты ждешь? У нас есть машины и боеприпасы... нам нужны только отважные канониры, чтобы применить их в деле.','Вернитесь к командиру наземных войск Ксутье в Зону бомбардировки, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Воздушный десант',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну, ладно, мелочь пузатая, есть у меня для тебя кое-какая работенка. Должна же быть от тебя какая-то польза, верно?$B$BДесант наших лучших разведчиков готов к заброске в Имирхейм. Тамошние врайкулы вооружены автоматическими копьеметами, которые разносят наш транспорт в клочья, но у нас очень толковые инженеры на "Молоте Оргрима", они создали блокиратор огня.$B$BТы будешь нашим канониром. Дашь несколько залпов по их копьеметам, чтобы создать им плохую видимость и заблокировать их механизмы. Твоя задача: сделать так, чтобы десант был сброшен благополучно, и чтобы наш транспортный аппарат вернулся на базу в целости и сохранности.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Командир наземных войск Ксутья на краю ледника возле Имирхейма приказал вам использовать кор\'кронскую заградительную пушку, чтобы обеспечить прикрытие для кор\'кронского транспортника, так чтобы десант был сброшен, а транспортный самолет остался целым.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Выходит, ты хоть на что-то годишься. Хвалю. Молодец.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Чего ты ждешь? У нас есть машины и боеприпасы... нам нужны только отважные канониры, чтобы применить их в деле.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру наземных войск Ксутье в Зону бомбардировки, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13311,'Карты Новолуния: колода Демонов','Теперь, когда вы собрали все карты колоды Демонов, вы видите, как сверху появляется еще одна карта. На ней нарисован предсказатель, который глядит прямо на вас, независимо от того, под каким углом вы смотрите на изображение.$b$bВы чувствуете, что с помощью этой карты можно кого-то призвать.','Призовите предсказателя судьбы с Ярмарки Новолуния и отдайте ему колоду Демонов.','Знай же, что карты таро пользуются большой популярностью на ярмарке Новолуния, так что если тебе удастся собрать еще одну колоду – не стесняйся, обращайся к нам. Среди нас много успешных торговцев, так что без награды ты не останешься.','Я вижу, что вам удалось собрать колоду Демонов! Поздравляем!','Вернитесь к предсказательнице ярмарки Новолуния.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Карты Новолуния: колода Демонов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда вы собрали все карты колоды Демонов, вы видите, как сверху появляется еще одна карта. На ней нарисован предсказатель, который глядит прямо на вас, независимо от того, под каким углом вы смотрите на изображение.$b$bВы чувствуете, что с помощью этой карты можно кого-то призвать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Призовите предсказателя судьбы с Ярмарки Новолуния и отдайте ему колоду Демонов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Знай же, что карты таро пользуются большой популярностью на ярмарке Новолуния, так что если тебе удастся собрать еще одну колоду – не стесняйся, обращайся к нам. Среди нас много успешных торговцев, так что без награды ты не останешься.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я вижу, что вам удалось собрать колоду Демонов! Поздравляем!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к предсказательнице ярмарки Новолуния.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13312,'Железный вал','Железный вал возвышается над долиной Павших Героев, к западу от Алдур\'тара. Он окружает почти всю долину. Мы не сможем продвинуться дальше, пока не возьмем этот вал. Но там засел Гримкор Злобный и его приверженцы Культа Проклятых.$B$BЕсли ты одолеешь Гримкора, наши войска смогут взять эти стены. Возьми эту руну искажения. Ее мощь, высвобожденная в непосредственной близости от сферы Гримкора, в конце вала, обязательно привлечет внимание некроманта.','Убейте Гримкора Злобного и возвращайтесь к Кольтире Ткачу Смерти на "Молот Оргрима".','Ты $Gвыполнил:выполнила; свою миссию?','Вернитесь к Кольтире Ткачу Смерти на "Молот Оргрима", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Железный вал',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Железный вал возвышается над долиной Павших Героев, к западу от Алдур\'тара. Он окружает почти всю долину. Мы не сможем продвинуться дальше, пока не возьмем этот вал. Но там засел Гримкор Злобный и его приверженцы Культа Проклятых.$B$BЕсли ты одолеешь Гримкора, наши войска смогут взять эти стены. Возьми эту руну искажения. Ее мощь, высвобожденная в непосредственной близости от сферы Гримкора, в конце вала, обязательно привлечет внимание некроманта.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Гримкора Злобного и возвращайтесь к Кольтире Ткачу Смерти на "Молот Оргрима".',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gвыполнил:выполнила; свою миссию?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кольтире Ткачу Смерти на "Молот Оргрима", что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (13313,'Ослепить соглядатаев!','Альянсу каким-то образом удалось запустить целую эскадрилью разведывательных машин, и теперь они кружат над долиной Павших Героев и ледником Ледяной Короны, к западу от Алдур\'тара.$b$bМы такого допустить не можем! Главный инженер Меднопал снабдил меня превосходным оружием как раз для такого случая: он называет эту штуку ЗГ-3. Он уверяет, что эта штука способна сбивать ветролеты Альянса с одного выстрела! Ступай и испытай ее в деле.','С помощью ЗГ-3 уничтожьте 6 разведывательных истребителей "Усмирителя небес", потом вернитесь к покорителю небес Корму Черному Шраму на борт "Молота Оргрима".','Хорошо. Чем меньше крыс из Альянса стоит у нас на пути, тем лучше. Мы им покажем, что такое настоящие воины!','Вернитесь к покорителю небес Корму Черному Шраму на "Молот Оргрима", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ослепить соглядатаев!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Альянсу каким-то образом удалось запустить целую эскадрилью разведывательных машин, и теперь они кружат над долиной Павших Героев и ледником Ледяной Короны, к западу от Алдур\'тара.$b$bМы такого допустить не можем! Главный инженер Меднопал снабдил меня превосходным оружием как раз для такого случая: он называет эту штуку ЗГ-3. Он уверяет, что эта штука способна сбивать ветролеты Альянса с одного выстрела! Ступай и испытай ее в деле.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','С помощью ЗГ-3 уничтожьте 6 разведывательных истребителей "Усмирителя небес", потом вернитесь к покорителю небес Корму Черному Шраму на борт "Молота Оргрима".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо. Чем меньше крыс из Альянса стоит у нас на пути, тем лучше. Мы им покажем, что такое настоящие воины!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к покорителю небес Корму Черному Шраму на "Молот Оргрима", что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13314,'Перехватить донесения','Орда что-то затевает, и мне это не нравится! После того, что они вытворяли на Прорванном фронте, стало ясно, что они способны на все – и нам следует их остановить.$b$bНебо над ледником Ледяной Короны, к западу от Алдур\'тара и Железного вала, кишит их разведчиками. Всадники на дракондорах переносят депеши и донесения. Используй этот стреломет, когда понадобится убить разведчиков с "Молота Оргрима". Пожалуй, будет лучше, если ты тоже будешь летать...','Заберите 6 донесений для "Молота Оргрима" у разведчиков с "Молота Оргрима" и отдайте их старшему капитану Джастину Бартлетту на борту "Усмирителя небес".','Хорошо все-таки иметь под рукой такого компетентного исполнителя! Будь у нас целое войско таких, как ты, $N, мы бы показали Орде, на что мы способны! Эти перехваченные депеши помогут нам одержать верх в предстоящей битве. Эти мерзавцы у нас еще попляшут!','Удалось ли тебе перехватить их донесения?','Вернитесь к старшему капитану Джастину Бартлетту на "Усмиритель небес", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Перехватить донесения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Орда что-то затевает, и мне это не нравится! После того, что они вытворяли на Прорванном фронте, стало ясно, что они способны на все – и нам следует их остановить.$b$bНебо над ледником Ледяной Короны, к западу от Алдур\'тара и Железного вала, кишит их разведчиками. Всадники на дракондорах переносят депеши и донесения. Используй этот стреломет, когда понадобится убить разведчиков с "Молота Оргрима". Пожалуй, будет лучше, если ты тоже будешь летать...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заберите 6 донесений для "Молота Оргрима" у разведчиков с "Молота Оргрима" и отдайте их старшему капитану Джастину Бартлетту на борту "Усмирителя небес".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо все-таки иметь под рукой такого компетентного исполнителя! Будь у нас целое войско таких, как ты, $N, мы бы показали Орде, на что мы способны! Эти перехваченные депеши помогут нам одержать верх в предстоящей битве. Эти мерзавцы у нас еще попляшут!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось ли тебе перехватить их донесения?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старшему капитану Джастину Бартлетту на "Усмиритель небес", что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13315,'Предварительная разведка','Дело движется. Мы разработали тактику, которая должна помочь нам взять Врата Смерти под контроль. Конечно, потери будут, и немалые, но в конце концов мы должны победить – особенно если Орда, с которой ты так жаждешь сразиться, нам не помешает.$b$bСледующей нашей целью станут Врата Горя. Слетай туда, ознакомься с местностью, посмотри, с чем предстоит иметь дело.$b$bА когда вернешься, я дам тебе новое поручение.','Слетайте к Вратам Горя и ознакомьтесь с южной, центральной, северной и северо-западной частями Врат по просьбе Тассариана с "Усмирителя небес".','Отлично, отлично, |3-6($C)!$B$BТеперь, когда ты своими глазами $Gвидел:видела;, с чем приходится иметь дело, пора браться за работу...','Ты $Gразведал:разведала; врата запустения, $C?','Вернитесь к Тассариану на "Усмиритель небес", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Предварительная разведка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Дело движется. Мы разработали тактику, которая должна помочь нам взять Врата Смерти под контроль. Конечно, потери будут, и немалые, но в конце концов мы должны победить – особенно если Орда, с которой ты так жаждешь сразиться, нам не помешает.$b$bСледующей нашей целью станут Врата Горя. Слетай туда, ознакомься с местностью, посмотри, с чем предстоит иметь дело.$b$bА когда вернешься, я дам тебе новое поручение.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Слетайте к Вратам Горя и ознакомьтесь с южной, центральной, северной и северо-западной частями Врат по просьбе Тассариана с "Усмирителя небес".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, отлично, |3-6($C)!$B$BТеперь, когда ты своими глазами $Gвидел:видела;, с чем приходится иметь дело, пора браться за работу...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gразведал:разведала; врата запустения, $C?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тассариану на "Усмиритель небес", что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13316,'Стражи Корп\'ретара','Корп\'ретар, именуемый также Вратами Ужаса, – это последнее препятствие между нами и цитаделью Ледяной Короны. Он расположен к югу от Железного вала, за ледником и Пожарищем. Переход будет долгим и трудным. Пока мы туда доберемся, наши солдаты выбьются из сил.$B$BНужно ослабить вражескую оборону, иначе мы все поляжем под этими стенами.$B$BУкрепления обороняют самые яростные и преданные солдаты Короля-лича. Сделай все возможное, чтобы их уничтожить – будем надеяться, этого будет достаточно.','Убейте 5 провозвестников ужаса и 5 стражей Корп\'ретара по приказу Кольтиры Ткача Смерти с "Молота Оргрима".','Надеюсь, твой успех в Корп\'ретаре принесет нам удачу и станет залогом победы в будущей битве. Король-лич не будет спокойно сидеть и смотреть, как мы подступаем к воротам его твердыни.','Ты $Gискалечил:искалечила; защитников Корп\'ретара?','Вернитесь к Кольтире Ткачу Смерти на "Молот Оргрима", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Стражи Корп\'ретара',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Корп\'ретар, именуемый также Вратами Ужаса, – это последнее препятствие между нами и цитаделью Ледяной Короны. Он расположен к югу от Железного вала, за ледником и Пожарищем. Переход будет долгим и трудным. Пока мы туда доберемся, наши солдаты выбьются из сил.$B$BНужно ослабить вражескую оборону, иначе мы все поляжем под этими стенами.$B$BУкрепления обороняют самые яростные и преданные солдаты Короля-лича. Сделай все возможное, чтобы их уничтожить – будем надеяться, этого будет достаточно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 5 провозвестников ужаса и 5 стражей Корп\'ретара по приказу Кольтиры Ткача Смерти с "Молота Оргрима".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Надеюсь, твой успех в Корп\'ретаре принесет нам удачу и станет залогом победы в будущей битве. Король-лич не будет спокойно сидеть и смотреть, как мы подступаем к воротам его твердыни.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gискалечил:искалечила; защитников Корп\'ретара?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кольтире Ткачу Смерти на "Молот Оргрима", что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (13317,'----') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','----',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13318,'Перетащить и опустить','Так значит, Врата Горя обороняет Культ Проклятых? Неудивительно.$b$bЛадно, пора позабавиться. Ты говоришь, у южной части Врат тренируют новых сектантов? У каждого из них должен быть особый предмет, его выдают всем посвященным – сфера иллюзии.$b$bЭти артефакты используются для того, чтобы маскировать приверженцев секты и позволять им беспрепятственно проходить всюду, где надо, смешиваясь с толпой врагов.$b$bУбивай этих безумцев, пока не добудешь несколько таких сфер, а потом используй их против поработителей.','Отберите сферы иллюзии у озлобленных посвященных в Алдур\'таре и используйте их против 3 темных поработителей по просьбе Тассариана, который находится на борту "Усмирителя небес".','Не правда ли, эффективное оружие – в соответствующих обстоятельствах, конечно?$B$BЭтот трюк никогда не устаревает…','Да, $R?','Вернитесь к Тассариану на "Усмиритель небес", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Перетащить и опустить',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Так значит, Врата Горя обороняет Культ Проклятых? Неудивительно.$b$bЛадно, пора позабавиться. Ты говоришь, у южной части Врат тренируют новых сектантов? У каждого из них должен быть особый предмет, его выдают всем посвященным – сфера иллюзии.$b$bЭти артефакты используются для того, чтобы маскировать приверженцев секты и позволять им беспрепятственно проходить всюду, где надо, смешиваясь с толпой врагов.$b$bУбивай этих безумцев, пока не добудешь несколько таких сфер, а потом используй их против поработителей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отберите сферы иллюзии у озлобленных посвященных в Алдур\'таре и используйте их против 3 темных поработителей по просьбе Тассариана, который находится на борту "Усмирителя небес".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Не правда ли, эффективное оружие – в соответствующих обстоятельствах, конечно?$B$BЭтот трюк никогда не устаревает…',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да, $R?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тассариану на "Усмиритель небес", что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13319,'Вершина иерархии','Судя по твоему докладу и по тому, что мне известно о культе, в каждом их лагере имеется надзиратель, который всем и заправляет.$b$bРазумеется, уничтожение всех этих предводителей остановит сектантов лишь ненадолго, но все-таки на время выведет их из игры. На данный момент это вполне актуальная задача.$b$bОтыщи этих надзирателей и расправься с ними. Потом возвращайся ко мне.','Отправляйтесь в Алдур\'тар и убейте надзирателя Фэдриса, надзирателя Саврина, надзирателя Веража и надзирателя Джакона про просьбе Тассариана с "Усмирителя небес".','Прекрасно, |3-6($R). Но почивать на лаврах рановато! На место этих надзирателей скоро встанут новые...','Да, $C?','Вернитесь к Тассариану на "Усмиритель небес", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вершина иерархии',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Судя по твоему докладу и по тому, что мне известно о культе, в каждом их лагере имеется надзиратель, который всем и заправляет.$b$bРазумеется, уничтожение всех этих предводителей остановит сектантов лишь ненадолго, но все-таки на время выведет их из игры. На данный момент это вполне актуальная задача.$b$bОтыщи этих надзирателей и расправься с ними. Потом возвращайся ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Алдур\'тар и убейте надзирателя Фэдриса, надзирателя Саврина, надзирателя Веража и надзирателя Джакона про просьбе Тассариана с "Усмирителя небес".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно, |3-6($R). Но почивать на лаврах рановато! На место этих надзирателей скоро встанут новые...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да, $C?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тассариану на "Усмиритель небес", что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13320,'Невоспроизводимый компонент','Я даже отсюда ощущаю запах, исходящий от их котлов – но нет, это не чумное зелье... $B$BПриверженцев культа заставляют пить смесь, лишающую их воли и навеки обращающую в рабов Короля-лича. $B$BНекоторые говорят, что одним из ингредиентов этого зелья является душа подвергшегося пыткам и безжалостно убитого существа, однако мне никогда не удавалось заполучить подобный компонент... $B$BНаполни эту флягу образцами зелья из трех котлов, находящихся к северо-западу от ворот, и отнеси главному инженеру Болтоключу.','Тассариан с корабля "Усмиритель небес" хочет, чтобы вы наполнили трехчастную флягу изо всех 3 котлов служителей культа в Алдур\'таре, а затем отнесли ее главному инженеру Болтоключу.','<Болтоключ выливает содержимое фляги в свой анализатор жидкостей.>$B$BА здесь мы имеем неудачную попытку получить гомогенную жидкость...','Ну-ка, |3-6($R), что тут у тебя?','Вернитесь к главному инженеру Болтоключу на "Усмиритель небес", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Невоспроизводимый компонент',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я даже отсюда ощущаю запах, исходящий от их котлов – но нет, это не чумное зелье... $B$BПриверженцев культа заставляют пить смесь, лишающую их воли и навеки обращающую в рабов Короля-лича. $B$BНекоторые говорят, что одним из ингредиентов этого зелья является душа подвергшегося пыткам и безжалостно убитого существа, однако мне никогда не удавалось заполучить подобный компонент... $B$BНаполни эту флягу образцами зелья из трех котлов, находящихся к северо-западу от ворот, и отнеси главному инженеру Болтоключу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Тассариан с корабля "Усмиритель небес" хочет, чтобы вы наполнили трехчастную флягу изо всех 3 котлов служителей культа в Алдур\'таре, а затем отнесли ее главному инженеру Болтоключу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Болтоключ выливает содержимое фляги в свой анализатор жидкостей.>$B$BА здесь мы имеем неудачную попытку получить гомогенную жидкость...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну-ка, |3-6($R), что тут у тебя?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к главному инженеру Болтоключу на "Усмиритель небес", что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13321,'Все переиграть','Это должно подействовать!$b$bЗначит, эти мерзавцы ищут чужие души, чтобы бросить их в свою безумную похлебку? Ничего, мы им подсобим!$b$bНа-ка, глотни малость! Не тревожься, оно очень сильно разбавлено... ну, по крайней мере, я почти уверен, что оно не окажет никакого эффекта, кроме того, что ты сможешь обнаруживать сущности поверженных сектантов.$b$bКогда соберешь их побольше, швырни корчащуюся массу искаженных душ в любой из их котлов.$b$bПоглядим, как им понравится собственное лекарство!','Бросьте корчащуюся массу в котел в Алдур\'таре по просьбе главного инженера Болтоключа с "Усмирителя небес".','Ур-ра!$B$BТо-то же! Будут знать!','Что ж, $C?$B$BУ нас меньше сектантов, о которых нужно беспокоиться?','Вернитесь к главному инженеру Болтоключу на "Усмиритель небес", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Все переиграть',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это должно подействовать!$b$bЗначит, эти мерзавцы ищут чужие души, чтобы бросить их в свою безумную похлебку? Ничего, мы им подсобим!$b$bНа-ка, глотни малость! Не тревожься, оно очень сильно разбавлено... ну, по крайней мере, я почти уверен, что оно не окажет никакого эффекта, кроме того, что ты сможешь обнаруживать сущности поверженных сектантов.$b$bКогда соберешь их побольше, швырни корчащуюся массу искаженных душ в любой из их котлов.$b$bПоглядим, как им понравится собственное лекарство!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Бросьте корчащуюся массу в котел в Алдур\'таре по просьбе главного инженера Болтоключа с "Усмирителя небес".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ур-ра!$B$BТо-то же! Будут знать!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что ж, $C?$B$BУ нас меньше сектантов, о которых нужно беспокоиться?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к главному инженеру Болтоключу на "Усмиритель небес", что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13322,'Все переиграть','Значит, эти мерзавцы ищут чужие души, чтобы бросить их в свою безумную похлебку? Ничего, мы им подсобим!$b$bНа-ка, глотни малость! Не тревожься, оно очень сильно разбавлено... ну, по крайней мере, я почти уверен, что оно не окажет никакого эффекта, кроме того, что ты сможешь обнаруживать сущности поверженных сектантов.$b$bКогда соберешь их побольше, швырни корчащуюся массу искаженных душ в любой из их котлов.$b$bПоглядим, как им понравится собственное лекарство!','Выпейте разбавленное снадобье сектантов по просьбе главного инженера Болтоключа с "Усмирителя небес", затем убивайте любых сектантов, каких встретите в Алдур\'таре, и забирайте их оскверненные сущности. После смешайте 10 сущностей, чтобы получить корчащуюся массу, и бросьте ее в любой из котлов сектантов.','Ур-ра!$B$BТо-то же! Будут знать!','Что ж, $C?$B$BУ нас меньше сектантов, о которых нужно беспокоиться?','Вернитесь к главному инженеру Болтоключу на "Усмиритель небес", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Все переиграть',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Значит, эти мерзавцы ищут чужие души, чтобы бросить их в свою безумную похлебку? Ничего, мы им подсобим!$b$bНа-ка, глотни малость! Не тревожься, оно очень сильно разбавлено... ну, по крайней мере, я почти уверен, что оно не окажет никакого эффекта, кроме того, что ты сможешь обнаруживать сущности поверженных сектантов.$b$bКогда соберешь их побольше, швырни корчащуюся массу искаженных душ в любой из их котлов.$b$bПоглядим, как им понравится собственное лекарство!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выпейте разбавленное снадобье сектантов по просьбе главного инженера Болтоключа с "Усмирителя небес", затем убивайте любых сектантов, каких встретите в Алдур\'таре, и забирайте их оскверненные сущности. После смешайте 10 сущностей, чтобы получить корчащуюся массу, и бросьте ее в любой из котлов сектантов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ур-ра!$B$BТо-то же! Будут знать!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что ж, $C?$B$BУ нас меньше сектантов, о которых нужно беспокоиться?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к главному инженеру Болтоключу на "Усмиритель небес", что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13323,'Перетащить и опустить','Что-то эти посвященные опять расплодились! Ты знаешь, что следует делать...$b$bУ южной части врат тренируют новых сектантов. У каждого из них должен быть особый предмет, его выдают всем посвященным – сфера иллюзии.$b$bЭти артефакты используются для того, чтобы маскировать приверженцев секты и позволять им беспрепятственно проходить всюду, где надо, смешиваясь с толпой врагов.$b$bУбивай этих безумцев, пока не добудешь несколько таких сфер, а потом используй сферы против поработителей.','Отберите сферы иллюзии у озлобленных посвященных в Алдур\'таре и используйте их против 3 темных поработителей по просьбе Тассариана, который находится на борту "Усмирителя небес".','Не правда ли, эффективное оружие – в соответствующих обстоятельствах, конечно?$B$BЭтот трюк никогда не устаревает…','Да, $R?','Вернитесь к Тассариану на "Усмиритель небес", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Перетащить и опустить',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что-то эти посвященные опять расплодились! Ты знаешь, что следует делать...$b$bУ южной части врат тренируют новых сектантов. У каждого из них должен быть особый предмет, его выдают всем посвященным – сфера иллюзии.$b$bЭти артефакты используются для того, чтобы маскировать приверженцев секты и позволять им беспрепятственно проходить всюду, где надо, смешиваясь с толпой врагов.$b$bУбивай этих безумцев, пока не добудешь несколько таких сфер, а потом используй сферы против поработителей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отберите сферы иллюзии у озлобленных посвященных в Алдур\'таре и используйте их против 3 темных поработителей по просьбе Тассариана, который находится на борту "Усмирителя небес".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Не правда ли, эффективное оружие – в соответствующих обстоятельствах, конечно?$B$BЭтот трюк никогда не устаревает…',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да, $R?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тассариану на "Усмиритель небес", что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13328,'Вдребезги','Слуги Короля-лича установили три кристалла: Ужаса, Отчаяния и Страдания, – на крепостных стенах Корп\'ретара. Если наши войска подойдут к стенам Корп\'ретара, король обрушит на нас мощь этого грозного оружия.$B$BЗаработав на полную мощность, кристаллы наполнят сознание наших бойцов болью и страхом. И тогда Плеть играючи расправится с ними.$B$BНайди эти кристаллы, разбей их и принеси мне их осколки. Нельзя допустить, чтобы Король-лич применил против нас это оружие!','Принесите Кольтире Ткачу Смерти на "Молот Оргрима" осколки кристалла Ужаса, кристалла Отчаяния и кристалла Страдания.','Тебе удалось разбить новое оружие Короля-лича?','Вернитесь к Кольтире Ткачу Смерти на "Молот Оргрима", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вдребезги',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слуги Короля-лича установили три кристалла: Ужаса, Отчаяния и Страдания, – на крепостных стенах Корп\'ретара. Если наши войска подойдут к стенам Корп\'ретара, король обрушит на нас мощь этого грозного оружия.$B$BЗаработав на полную мощность, кристаллы наполнят сознание наших бойцов болью и страхом. И тогда Плеть играючи расправится с ними.$B$BНайди эти кристаллы, разбей их и принеси мне их осколки. Нельзя допустить, чтобы Король-лич применил против нас это оружие!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Кольтире Ткачу Смерти на "Молот Оргрима" осколки кристалла Ужаса, кристалла Отчаяния и кристалла Страдания.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось разбить новое оружие Короля-лича?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кольтире Ткачу Смерти на "Молот Оргрима", что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13329,'Пред Вратами Ужаса','Войско Короля-лича выстроилось для защиты цитадели у Пожарища близ Корп\'ретара, южнее Железного вала.$B$BЛегион скелетов-разорителей под командованием рыцарей смерти перекрыл дорогу. Даже если мы уничтожим эту нежить, боюсь, Плеть просто оживит их и снова нашлет на нас.$B$BУ меня есть план, как этому помешать, но я не знаю, сработает он или нет... Возьми этот раствор и попробуй полить им останки скелетов-разорителей, чтобы растворить их.','Растворите останки 6 скелетов-разорителей летучей кислотой по заданию Кольтиры Ткача Смерти с "Молота Оргрима".','Вернитесь к Кольтире Ткачу Смерти на "Молот Оргрима", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пред Вратами Ужаса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Войско Короля-лича выстроилось для защиты цитадели у Пожарища близ Корп\'ретара, южнее Железного вала.$B$BЛегион скелетов-разорителей под командованием рыцарей смерти перекрыл дорогу. Даже если мы уничтожим эту нежить, боюсь, Плеть просто оживит их и снова нашлет на нас.$B$BУ меня есть план, как этому помешать, но я не знаю, сработает он или нет... Возьми этот раствор и попробуй полить им останки скелетов-разорителей, чтобы растворить их.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Растворите останки 6 скелетов-разорителей летучей кислотой по заданию Кольтиры Ткача Смерти с "Молота Оргрима".',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кольтире Ткачу Смерти на "Молот Оргрима", что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13330,'Кровь избранных','Врайкулы, сумевшие добиться благоволения Короля-лича, называют себя имирьярами. Они живут в городе, расположенном в центре Ледяной Короны. Прежде чем атаковать цитадель Ледяной Короны, нам нужно как следует подготовиться. Прежде всего, необходимо извести так называемых "избранных" Короля-лича.$b$bСтупай в их город, Имирхейм, и истреби их в их собственном гнезде. Пусть никто не сомневается, чье войско сильнее!','Убейте 20 врайкулов в Имирхейме по просьбе завоевателя Давоса Рихта с "Молота Оргрима".','Ага, значит, не так уж они непобедимы! Король-лич получит то, что ему причитается.','Ты $Gсделал:сделала; то, о чем я тебя просил?','Вернитесь к завоевателю Давосу Риоту на "Молот Оргрима", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кровь избранных',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Врайкулы, сумевшие добиться благоволения Короля-лича, называют себя имирьярами. Они живут в городе, расположенном в центре Ледяной Короны. Прежде чем атаковать цитадель Ледяной Короны, нам нужно как следует подготовиться. Прежде всего, необходимо извести так называемых "избранных" Короля-лича.$b$bСтупай в их город, Имирхейм, и истреби их в их собственном гнезде. Пусть никто не сомневается, чье войско сильнее!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 20 врайкулов в Имирхейме по просьбе завоевателя Давоса Рихта с "Молота Оргрима".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ага, значит, не так уж они непобедимы! Король-лич получит то, что ему причитается.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gсделал:сделала; то, о чем я тебя просил?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к завоевателю Давосу Риоту на "Молот Оргрима", что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (13331,'Ослепление Альянса','Альянсовцы, конечно, упрямы, этого у них не отнимешь, однако для того, чтобы нас остановить, потребуется нечто большее! Вот, возьми с собой ЗГ-3 и снова перестреляй бойцов-разведчиков с "Усмирителя небес"!$B$bВряд ли нам удастся вбить в их твердолобые башки побольше ума, но, по крайней мере, мы можем постараться: боеприпасов у нас хватит! Ты увидишь их бойцов, они кружат над долиной Павших героев, к западу от Алдур\'тара. Не возвращайся, пока не разгромишь их!','С помощью ЗГ-3 уничтожьте 6 разведывательных истребителей "Усмирителя небес", потом вернитесь к покорителю небес Корму Черному Шраму на борт "Молота Оргрима".','Прекрасно! Теперь Орда обеспечила себе превосходство, по крайней мере, до тех пор, пока эти альянсовские хмыри не решатся сунуться сюда снова.','Вернитесь к покорителю небес Корму Черному Шраму на "Молот Оргрима", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ослепление Альянса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Альянсовцы, конечно, упрямы, этого у них не отнимешь, однако для того, чтобы нас остановить, потребуется нечто большее! Вот, возьми с собой ЗГ-3 и снова перестреляй бойцов-разведчиков с "Усмирителя небес"!$B$bВряд ли нам удастся вбить в их твердолобые башки побольше ума, но, по крайней мере, мы можем постараться: боеприпасов у нас хватит! Ты увидишь их бойцов, они кружат над долиной Павших героев, к западу от Алдур\'тара. Не возвращайся, пока не разгромишь их!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','С помощью ЗГ-3 уничтожьте 6 разведывательных истребителей "Усмирителя небес", потом вернитесь к покорителю небес Корму Черному Шраму на борт "Молота Оргрима".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно! Теперь Орда обеспечила себе превосходство, по крайней мере, до тех пор, пока эти альянсовские хмыри не решатся сунуться сюда снова.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к покорителю небес Корму Черному Шраму на "Молот Оргрима", что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13332,'Строим баррикады!','Когда наши войска продвинутся за Алдур\'тар, они окажутся уязвимы для атак с Железного вала и большого ледника под ним.$b$bДля строительства нормальных укреплений у нас нет ни времени, ни материалов, однако мы можем возвести хотя бы баррикады, чтобы защитить наших бойцов от обстрела и сдержать атаки Плети.$b$bОтправляйся с этим набором для строительства баррикад в долину Павших Героев, к западу от Алдур\'тара. Отыщи установленные мной метки и сооруди на их месте баррикады.','Постройте 8 баррикад с помощью комплекта для возведения баррикад по просьбе Тассариана с "Усмирителя небес".','<Тассариан кивает.>$B$BХорошо. Конечно, баррикады – слабая защита, но все же это лучше, чем ничего. Но врата по-прежнему неприступны – разумеется, если командиры Плети знают свое дело. Нужно захватить как можно большую часть прилегающей территории.','Ты $Gпостроил:построила; эти баррикады?','Вернитесь к Тассариану на "Усмиритель небес", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Строим баррикады!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда наши войска продвинутся за Алдур\'тар, они окажутся уязвимы для атак с Железного вала и большого ледника под ним.$b$bДля строительства нормальных укреплений у нас нет ни времени, ни материалов, однако мы можем возвести хотя бы баррикады, чтобы защитить наших бойцов от обстрела и сдержать атаки Плети.$b$bОтправляйся с этим набором для строительства баррикад в долину Павших Героев, к западу от Алдур\'тара. Отыщи установленные мной метки и сооруди на их месте баррикады.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Постройте 8 баррикад с помощью комплекта для возведения баррикад по просьбе Тассариана с "Усмирителя небес".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Тассариан кивает.>$B$BХорошо. Конечно, баррикады – слабая защита, но все же это лучше, чем ничего. Но врата по-прежнему неприступны – разумеется, если командиры Плети знают свое дело. Нужно захватить как можно большую часть прилегающей территории.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gпостроил:построила; эти баррикады?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тассариану на "Усмиритель небес", что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13333,'Перехват донесений','Несмотря на все наши усилия, Орда продолжает засылать разведчиков на территорию ледника Ледяной Короны, к западу от Железного вала и Алдур\'тара.$B$BНельзя допустить, чтобы ордынцы стали хозяином положения благодаря этой разведывательной операции. Так что бери ружье, стреляющее дротиками, и перебей всех разведчиков с "Молота Оргрима", не щади никого! Все донесения, которые будут при них, неси мне.$B$BОрда хорошо потрудилась, а мы, так сказать, пожнем все плоды их трудов. Главное – вовремя подсуетиться.','Заберите 6 донесений для "Молота Оргрима" у разведчиков с "Молота Оргрима", и отдайте их старшему капитану Джастину Бартлетту на борту "Усмирителя небес".','<Старший капитан забирает у вас донесения.>$B$BДа, это именно то, что нужно. Даже Орде хватает ума понять, что на армию Плети нельзя наступать вслепую. Теперь у нас есть информация, и мы сможем как следует подготовиться.','Удалось ли тебе перехватить их донесения?','Вернитесь к старшему капитану Джастину Бартлетту на "Усмиритель небес", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Перехват донесений',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Несмотря на все наши усилия, Орда продолжает засылать разведчиков на территорию ледника Ледяной Короны, к западу от Железного вала и Алдур\'тара.$B$BНельзя допустить, чтобы ордынцы стали хозяином положения благодаря этой разведывательной операции. Так что бери ружье, стреляющее дротиками, и перебей всех разведчиков с "Молота Оргрима", не щади никого! Все донесения, которые будут при них, неси мне.$B$BОрда хорошо потрудилась, а мы, так сказать, пожнем все плоды их трудов. Главное – вовремя подсуетиться.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заберите 6 донесений для "Молота Оргрима" у разведчиков с "Молота Оргрима", и отдайте их старшему капитану Джастину Бартлетту на борту "Усмирителя небес".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Старший капитан забирает у вас донесения.>$B$BДа, это именно то, что нужно. Даже Орде хватает ума понять, что на армию Плети нельзя наступать вслепую. Теперь у нас есть информация, и мы сможем как следует подготовиться.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось ли тебе перехватить их донесения?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старшему капитану Джастину Бартлетту на "Усмиритель небес", что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13334,'Окровавленные знамена','В долине Павших Героев и на леднике Ледяной Короны, к западу от Алдур\'тара, Плеть пытается использовать против нас убитых. Слуги Плети пробудили мертвецов, спавших в долине, и наделили их невероятной силой и яростью. Источниками этой силы являются знамена, которые хранят у себя предводители Плети в районе ледника. Убей этих знаменосцев, и павшие герои, которых они возглавляют, лишатся своей сверхъестественной силы.$b$bИменно тебе выпало избавить нас от этого препятствия и расчистить путь нашим основным силам.','Убейте 5 знаменосцев Плети, 5 обратителей Плети и 20 обращенных героев по просьбе Тассариана, который находится на борту "Усмирителя небес".','Так значит, знаменосцы Плети и их прихвостни истреблены? Отлично! Продолжим укреплять наши позиции…','Ты $Gубрал:убрала; знаменосцев Плети и их приспешников? Хорошо. Наши приготовления должны продолжаться.','Вернитесь к Тассариану на "Усмиритель небес", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Окровавленные знамена',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В долине Павших Героев и на леднике Ледяной Короны, к западу от Алдур\'тара, Плеть пытается использовать против нас убитых. Слуги Плети пробудили мертвецов, спавших в долине, и наделили их невероятной силой и яростью. Источниками этой силы являются знамена, которые хранят у себя предводители Плети в районе ледника. Убей этих знаменосцев, и павшие герои, которых они возглавляют, лишатся своей сверхъестественной силы.$b$bИменно тебе выпало избавить нас от этого препятствия и расчистить путь нашим основным силам.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 5 знаменосцев Плети, 5 обратителей Плети и 20 обращенных героев по просьбе Тассариана, который находится на борту "Усмирителя небес".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так значит, знаменосцы Плети и их прихвостни истреблены? Отлично! Продолжим укреплять наши позиции…',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gубрал:убрала; знаменосцев Плети и их приспешников? Хорошо. Наши приготовления должны продолжаться.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тассариану на "Усмиритель небес", что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13335,'Пред Вратами Ужаса','Войско Короля-лича выстроилось для защиты цитадели у Пожарища близ Корп\'ретара, южнее Железного вала.$B$BЛегион скелетов-разорителей под командованием рыцарей смерти перекрыл дорогу. Даже если мы уничтожим эту нежить, боюсь, Плеть просто их восстановит и снова нашлет на нас.$B$BУ меня есть план, как этому помешать, но я не знаю, сработает он или нет... Возьми этот раствор и попробуй полить им останки скелетов-разорителей, чтобы растворить их.','Растворите трупы 6 скелетов-разорителей летучей кислотой по заданию Тассариана с "Усмирителя небес".','<Тассариан слушает ваш рассказ об успешном испытании состава.>$B$BТо есть кислота их растворяет? Отлично. Она очень нам пригодится, когда начнется массированное наступление на войско нежити.','Ты $Gпроверил:проверила; решение на риверах?','Вернитесь к Тассариану на "Усмиритель небес", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пред Вратами Ужаса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Войско Короля-лича выстроилось для защиты цитадели у Пожарища близ Корп\'ретара, южнее Железного вала.$B$BЛегион скелетов-разорителей под командованием рыцарей смерти перекрыл дорогу. Даже если мы уничтожим эту нежить, боюсь, Плеть просто их восстановит и снова нашлет на нас.$B$BУ меня есть план, как этому помешать, но я не знаю, сработает он или нет... Возьми этот раствор и попробуй полить им останки скелетов-разорителей, чтобы растворить их.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Растворите трупы 6 скелетов-разорителей летучей кислотой по заданию Тассариана с "Усмирителя небес".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Тассариан слушает ваш рассказ об успешном испытании состава.>$B$BТо есть кислота их растворяет? Отлично. Она очень нам пригодится, когда начнется массированное наступление на войско нежити.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gпроверил:проверила; решение на риверах?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тассариану на "Усмиритель небес", что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (13336,'Кровь избранных','Врайкулы, сумевшие добиться благоволения Короля-лича, называют себя имирьярами. Они живут в городе, расположенном в центре Ледяной Короны. Прежде чем атаковать цитадель Ледяной Короны, нам нужно как следует подготовиться. Прежде всего, необходимо извести так называемых "избранных" Короля-лича.$b$bСтупай в их город, Имирхейм, и истреби имирьяров в их собственном гнезде. Пусть все знают, чье войско сильнее!','Убейте 20 врайкулов в Имирхейме по просьбе рыцаря-капитана Дроша с "Усмирителя небес".','Король-предатель умрет. Вне всяких сомнений.','Вернитесь к рыцарю-капитану Дрошу на "Усмиритель небес", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кровь избранных',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Врайкулы, сумевшие добиться благоволения Короля-лича, называют себя имирьярами. Они живут в городе, расположенном в центре Ледяной Короны. Прежде чем атаковать цитадель Ледяной Короны, нам нужно как следует подготовиться. Прежде всего, необходимо извести так называемых "избранных" Короля-лича.$b$bСтупай в их город, Имирхейм, и истреби имирьяров в их собственном гнезде. Пусть все знают, чье войско сильнее!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 20 врайкулов в Имирхейме по просьбе рыцаря-капитана Дроша с "Усмирителя небес".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Король-предатель умрет. Вне всяких сомнений.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к рыцарю-капитану Дрошу на "Усмиритель небес", что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13337,'Железный вал','Железный вал возвышается над долиной Павших Героев, к западу от Алдур\'тара. Он окружает почти всю долину. Мы не сможем продвинуться дальше, пока не возьмем этот вал. Но там засел Гримкор Злобный и его приверженцы Культа Проклятых.$B$BЕсли ты одолеешь Гримкора, наши войска смогут взять эти стены. Возьми эту руну искажения. Ее мощь, высвобожденная в непосредственной близости от сферы Гримкора, в конце вала, обязательно привлечет внимание некроманта.','Убейте Гримкора Злобного и возвращайтесь к Тассариану на "Усмиритель небес".','Итак, Гримкор пал от твоей руки? Прекрасно. Теперь, когда он не стоит у нас на пути, наши шансы на то, чтобы взять и удержать вал, изрядно повысились.','Ты $Gвыполнил:выполнила; свою миссию?','Вернитесь к Тассариану на "Усмиритель небес", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Железный вал',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Железный вал возвышается над долиной Павших Героев, к западу от Алдур\'тара. Он окружает почти всю долину. Мы не сможем продвинуться дальше, пока не возьмем этот вал. Но там засел Гримкор Злобный и его приверженцы Культа Проклятых.$B$BЕсли ты одолеешь Гримкора, наши войска смогут взять эти стены. Возьми эту руну искажения. Ее мощь, высвобожденная в непосредственной близости от сферы Гримкора, в конце вала, обязательно привлечет внимание некроманта.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Гримкора Злобного и возвращайтесь к Тассариану на "Усмиритель небес".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Итак, Гримкор пал от твоей руки? Прекрасно. Теперь, когда он не стоит у нас на пути, наши шансы на то, чтобы взять и удержать вал, изрядно повысились.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gвыполнил:выполнила; свою миссию?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тассариану на "Усмиритель небес", что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (13338,'Стражи Корп\'ретара','Корп\'ретар, именуемый также Вратами Ужаса, – это последнее препятствие между нами и цитаделью Ледяной Короны. Он расположен к югу от Железного вала, за ледником и Пожарищем. Переход будет долгим и трудным. Пока мы туда доберемся, наши солдаты выбьются из сил.$B$BНужно ослабить вражескую оборону, иначе мы все поляжем под этими стенами.$B$BУкрепления обороняют самые яростные и преданные солдаты Короля-лича. Сделай все возможное, чтобы их уничтожить – будем надеяться, этого будет достаточно.','Убейте 5 провозвестников ужаса и 5 стражей Корп\'ретара по приказу Тассариана с "Усмирителя небес".','Надеюсь, твой успех в Корп\'ретаре принесет нам удачу и станет залогом победы в будущей битве. Король-лич не будет спокойно сидеть и смотреть, как мы подступаем к воротам его твердыни.','Вернитесь к Тассариану на "Усмиритель небес", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Стражи Корп\'ретара',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Корп\'ретар, именуемый также Вратами Ужаса, – это последнее препятствие между нами и цитаделью Ледяной Короны. Он расположен к югу от Железного вала, за ледником и Пожарищем. Переход будет долгим и трудным. Пока мы туда доберемся, наши солдаты выбьются из сил.$B$BНужно ослабить вражескую оборону, иначе мы все поляжем под этими стенами.$B$BУкрепления обороняют самые яростные и преданные солдаты Короля-лича. Сделай все возможное, чтобы их уничтожить – будем надеяться, этого будет достаточно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 5 провозвестников ужаса и 5 стражей Корп\'ретара по приказу Тассариана с "Усмирителя небес".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Надеюсь, твой успех в Корп\'ретаре принесет нам удачу и станет залогом победы в будущей битве. Король-лич не будет спокойно сидеть и смотреть, как мы подступаем к воротам его твердыни.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тассариану на "Усмиритель небес", что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13339,'Вдребезги','Слуги Короля-лича установили три кристалла: Ужаса, Отчаяния и Страдания, – на крепостных стенах Корп\'ретара. Если наши войска подойдут к стенам Корп\'ретара, король обрушит на нас мощь этого грозного оружия.$B$BЗаработав на полную мощность, кристаллы наполнят сознание наших бойцов болью и страхом. И тогда Плеть играючи расправится с ними.$B$BНайди эти кристаллы, разбей их и принеси мне их осколки. Нельзя допустить, чтобы Король-лич применил против нас это оружие!','Принесите Тассариану на "Усмиритель небес" осколки кристалла Ужаса, кристалла Отчаяния и кристалла Страдания.','<Тассариан забирает у вас осколки кристаллов и говорит тихим голосом.>$B$BЯ их помню...$B$BЭто оружие просто скосило бы наших людей. Ты $Gсделал:сделала; большое дело, устранив эту угрозу.','Тебе удалось разбить новое оружие Короля-лича?','Вернитесь к Тассариану на "Усмиритель небес", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вдребезги',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слуги Короля-лича установили три кристалла: Ужаса, Отчаяния и Страдания, – на крепостных стенах Корп\'ретара. Если наши войска подойдут к стенам Корп\'ретара, король обрушит на нас мощь этого грозного оружия.$B$BЗаработав на полную мощность, кристаллы наполнят сознание наших бойцов болью и страхом. И тогда Плеть играючи расправится с ними.$B$BНайди эти кристаллы, разбей их и принеси мне их осколки. Нельзя допустить, чтобы Король-лич применил против нас это оружие!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Тассариану на "Усмиритель небес" осколки кристалла Ужаса, кристалла Отчаяния и кристалла Страдания.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Тассариан забирает у вас осколки кристаллов и говорит тихим голосом.>$B$BЯ их помню...$B$BЭто оружие просто скосило бы наших людей. Ты $Gсделал:сделала; большое дело, устранив эту угрозу.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось разбить новое оружие Короля-лича?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тассариану на "Усмиритель небес", что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (13340,'Помощь в нападении','Нам нужны бойцы для нападения на Имирхейм!$b$bЛюбой воин, у которого есть хоть капля мозгов, скажет тебе, что врайкулы – отчаянные бойцы и голыми руками их не возьмешь. А уж имирьяры – тем более! Понятно, отчего Король-лич счел достойными именно их.$b$bРаспоряжение по осаде отдает командир наземных войск Ксутья. Сам город находится в центре Ледяной Короны. Войска Ксутьи стоят на краю ледника, к северу от города.','Явитесь к командиру наземных войск Ксутье на краю ледника к северу от Имирхейма.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Помощь в нападении',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нам нужны бойцы для нападения на Имирхейм!$b$bЛюбой воин, у которого есть хоть капля мозгов, скажет тебе, что врайкулы – отчаянные бойцы и голыми руками их не возьмешь. А уж имирьяры – тем более! Понятно, отчего Король-лич счел достойными именно их.$b$bРаспоряжение по осаде отдает командир наземных войск Ксутья. Сам город находится в центре Ледяной Короны. Войска Ксутьи стоят на краю ледника, к северу от города.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Явитесь к командиру наземных войск Ксутье на краю ледника к северу от Имирхейма.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13341,'Помощь в нападении','Нам нужны бойцы для нападения на Имирхейм!$b$bЛюбой воин, у которого есть хоть капля мозгов, скажет тебе, что врайкулы – отчаянные бойцы, и голыми руками их не возьмешь. А уж имирьяры – тем более! Понятно, отчего Король-лич счел достойными именно их.$b$bОсадой командует военачальник Куп. Сам город находится в центре Ледяной Короны. Войска Купа стоят на краю ледника, к северу от города.','Явитесь к военачальнику Купу на краю ледника к северу от Имирхейма.','Добро пожаловать в ад, солдат.$B$BМои бойцы атакуют ворота с этой позиции, а кроме того, у нас есть несколько транспортных самолетов и мы забрасываем в город диверсантов. Лишние воины ни там, ни там не помешают. У меня такое ощущение, что наша осада затянется надолго.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Помощь в нападении',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нам нужны бойцы для нападения на Имирхейм!$b$bЛюбой воин, у которого есть хоть капля мозгов, скажет тебе, что врайкулы – отчаянные бойцы, и голыми руками их не возьмешь. А уж имирьяры – тем более! Понятно, отчего Король-лич счел достойными именно их.$b$bОсадой командует военачальник Куп. Сам город находится в центре Ледяной Короны. Войска Купа стоят на краю ледника, к северу от города.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Явитесь к военачальнику Купу на краю ледника к северу от Имирхейма.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Добро пожаловать в ад, солдат.$B$BМои бойцы атакуют ворота с этой позиции, а кроме того, у нас есть несколько транспортных самолетов и мы забрасываем в город диверсантов. Лишние воины ни там, ни там не помешают. У меня такое ощущение, что наша осада затянется надолго.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13342,'Ненастоящий шпион','Что ж, $gдружище:барышня;, настало время нам обзавестись шпионом.$b$bНет, не настоящим шпионом, но для наших целей он подойдет.$b$bВ северной части Алдур\'тара сектанты, призыватели Бездны, порабощают демонов. Используй этот жезл, чтобы вытянуть темную сущность из трупов порабощенных слуг, а затем используй их камень призыва, чтобы создать нашего маленького шпиона.$b$bПока этого посланца не обнаружат, он будет нашими глазами и ушами. Он проберется повсюду и будет неприметно наблюдать за врагом.','Соберите 5 темных сущностей и вызовите темного посланника в Алдур\'таре по просьбе Тассариана, который находится на борту "Усмирителя небес".','Прекрасно, |3-6($C)!$B$BНаш посланец уже успел раздобыть кое-какую ценную информацию.','Да, $C?','Вернитесь к Тассариану на "Усмиритель небес", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ненастоящий шпион',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что ж, $gдружище:барышня;, настало время нам обзавестись шпионом.$b$bНет, не настоящим шпионом, но для наших целей он подойдет.$b$bВ северной части Алдур\'тара сектанты, призыватели Бездны, порабощают демонов. Используй этот жезл, чтобы вытянуть темную сущность из трупов порабощенных слуг, а затем используй их камень призыва, чтобы создать нашего маленького шпиона.$b$bПока этого посланца не обнаружат, он будет нашими глазами и ушами. Он проберется повсюду и будет неприметно наблюдать за врагом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 5 темных сущностей и вызовите темного посланника в Алдур\'таре по просьбе Тассариана, который находится на борту "Усмирителя небес".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно, |3-6($C)!$B$BНаш посланец уже успел раздобыть кое-какую ценную информацию.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да, $C?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тассариану на "Усмиритель небес", что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (13343,'Тайна бесконечности, мания преследования','Ах, снова ты! Или мы только что беседовали?$b$b<Хроми размышляет над причудами времени.>$b$bКак бы то ни было, за тобой охотятся драконы Бесконечности! Точнее, не совсем за тобой, а за той прошлой версией тебя, что обороняла песочные часы Вечности. Помнишь, да?$b$bАга, значит, тогда это $gбыл:была; все же ты, и теперь это снова ты. Постой, это все неважно! Важно то, что тебе следует вернуться в Бронзовое святилище драконов, чтобы защищать себя и песочные часы от атак драконов Бесконечности! Иначе ты исчезнешь из истории.','Хроми на вершине храма Драконьего Покоя просит вас снова отправиться в Бронзовое святилище драконов.$b$bОказавшись в святилище, установите песочные часы Вечности и помогите Себе-в-Прошлом защитить их от атак драконов Бесконечности.','<Хроми странно смотрит на вас.>$B$BЯ знаю вас? Я ощущаю вокруг вас ауру, как если бы само ваше существование изменялось. Либо это, либо вы застряли во временной петле.$B$BКакой бы ни была причина, вам лучше исправить это быстро, иначе вы не просуществуете очень долго!','Песочные часы Вечности спасены от драконов Бесконечности.','Вернитесь к Хроми в Храм Драконьего Покоя, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тайна бесконечности, мания преследования',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ах, снова ты! Или мы только что беседовали?$b$b<Хроми размышляет над причудами времени.>$b$bКак бы то ни было, за тобой охотятся драконы Бесконечности! Точнее, не совсем за тобой, а за той прошлой версией тебя, что обороняла песочные часы Вечности. Помнишь, да?$b$bАга, значит, тогда это $gбыл:была; все же ты, и теперь это снова ты. Постой, это все неважно! Важно то, что тебе следует вернуться в Бронзовое святилище драконов, чтобы защищать себя и песочные часы от атак драконов Бесконечности! Иначе ты исчезнешь из истории.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Хроми на вершине храма Драконьего Покоя просит вас снова отправиться в Бронзовое святилище драконов.$b$bОказавшись в святилище, установите песочные часы Вечности и помогите Себе-в-Прошлом защитить их от атак драконов Бесконечности.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Хроми странно смотрит на вас.>$B$BЯ знаю вас? Я ощущаю вокруг вас ауру, как если бы само ваше существование изменялось. Либо это, либо вы застряли во временной петле.$B$BКакой бы ни была причина, вам лучше исправить это быстро, иначе вы не просуществуете очень долго!',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Песочные часы Вечности спасены от драконов Бесконечности.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хроми в Храм Драконьего Покоя, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13344,'Ненастоящий шпион','Сектанты отловили последнего отправленного тобой посланца, |3-6($r).$b$bКонечно, он успел доставить нам немало ценных сведений, и все же нам необходимо продолжать следить за каждым их шагом.$b$bИспользуй этот жезл, чтобы вытянуть темную сущность из трупов порабощенных слуг, а затем используй их камень призыва, чтобы создать еще одного шпиона.$b$bПока этого посланца не обнаружат, он будет нашими глазами и ушами. Он проберется повсюду и будет неприметно наблюдать за врагом.','Соберите 5 темных сущностей и вызовите темного посланника в Алдур\'таре по просьбе Тассариана, который находится на борту "Усмирителя небес".','Отлично, $Gдруг:подруга; $Gмой:моя;!$B$BПосланец уже продолжает работу…','Да, $C?','Вернитесь к Тассариану на "Усмиритель небес", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ненастоящий шпион',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сектанты отловили последнего отправленного тобой посланца, |3-6($r).$b$bКонечно, он успел доставить нам немало ценных сведений, и все же нам необходимо продолжать следить за каждым их шагом.$b$bИспользуй этот жезл, чтобы вытянуть темную сущность из трупов порабощенных слуг, а затем используй их камень призыва, чтобы создать еще одного шпиона.$b$bПока этого посланца не обнаружат, он будет нашими глазами и ушами. Он проберется повсюду и будет неприметно наблюдать за врагом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 5 темных сущностей и вызовите темного посланника в Алдур\'таре по просьбе Тассариана, который находится на борту "Усмирителя небес".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, $Gдруг:подруга; $Gмой:моя;!$B$BПосланец уже продолжает работу…',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да, $C?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тассариану на "Усмиритель небес", что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13345,'Слишком мало сведений','Культ Проклятых известен тем, что вечно строит грандиозные планы, которые никогда не исполняются. Но на этот раз явно вышло иначе...$b$bБыть может, это близкое соседство с Королем-личом на них так повлияло. Как бы то ни было, они держатся увереннее, чем обычно. Необходимо выяснить, что питает их отвагу, а затем найти способ усмирить их!$b$bПодозреваю, что все дело в их ученых. Узнай, что они затевают, и доложи мне во всех подробностях.','Да, это весьма тревожные известия...','Ну что, |3-6($R), удалось ли выяснить, чем заняты их ученые?','Вернитесь к Тассариану на "Усмиритель небес", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Слишком мало сведений',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Культ Проклятых известен тем, что вечно строит грандиозные планы, которые никогда не исполняются. Но на этот раз явно вышло иначе...$b$bБыть может, это близкое соседство с Королем-личом на них так повлияло. Как бы то ни было, они держатся увереннее, чем обычно. Необходимо выяснить, что питает их отвагу, а затем найти способ усмирить их!$b$bПодозреваю, что все дело в их ученых. Узнай, что они затевают, и доложи мне во всех подробностях.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, это весьма тревожные известия...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, |3-6($R), удалось ли выяснить, чем заняты их ученые?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тассариану на "Усмиритель небес", что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13346,'Пусть злодеи не ведают покоя','Эти глупцы и впрямь обнаружили нечто, что может представлять серьезную угрозу для наших планов!$b$bПредводитель их секты, Алумет, совершил ритуальное самоубийство, и теперь его прихвостни передают его душе свою силу...$b$bЕсли оставить его в покое, их усилиями он скоро превратится в опасного противника!$b$bСобери его сердце, череп, скипетр и одеяние, а потом воздействуй на его останки кристаллом.$b$bТоропись, |3-6($r)! Уничтожь его, пока он не стал слишком могуществен!','Убейте Алумета Перерожденного в Алдур\'таре по просьбе Тассариана, который находится на борту "Усмирителя небес".','Алумет потерпел сокрушительное поражение, но дух его еще здесь, я чувствую это…','Ну что, друг? $GБыл:Была; ли ты $Gуспешен:успешна; против Алумета?','Вернитесь к Тассариану на "Усмиритель небес", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пусть злодеи не ведают покоя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти глупцы и впрямь обнаружили нечто, что может представлять серьезную угрозу для наших планов!$b$bПредводитель их секты, Алумет, совершил ритуальное самоубийство, и теперь его прихвостни передают его душе свою силу...$b$bЕсли оставить его в покое, их усилиями он скоро превратится в опасного противника!$b$bСобери его сердце, череп, скипетр и одеяние, а потом воздействуй на его останки кристаллом.$b$bТоропись, |3-6($r)! Уничтожь его, пока он не стал слишком могуществен!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Алумета Перерожденного в Алдур\'таре по просьбе Тассариана, который находится на борту "Усмирителя небес".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Алумет потерпел сокрушительное поражение, но дух его еще здесь, я чувствую это…',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, друг? $GБыл:Была; ли ты $Gуспешен:успешна; против Алумета?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тассариану на "Усмиритель небес", что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13347,'Восставший из праха','Судьба от рождения начертана огненными письменами в наших душах. Падение Болвара – это трагедия, но оно было неизбежно. $B$BВсе, что ты можешь сделать ныне, $n – это почтить своего героя. Найди на поле боя щит Болвара и возврати его королю. Когда будешь отдавать шит Вариану, скажи ему так: "Не все потеряно. Из праха падшего восстанет сила, которая объединит народы и очистит этот мир от скверны."$B$BОн не должен терять веру. Теперь иди, $n. Твоему народу нужен герой. Им $gнужен:нужна; ты.','Найдите щит Фордрагона на поле боя при Ангратаре, Вратах Гнева. Отнесите щит в крепость Штормграда и вручите королю Вариану Ринну.','Королева Драконов права, $N. Еще не все потеряно. Я буду силой, которая восстанет из пепла, и я очищу зло Орды от этого мира. Смерть наших братьев и сестер не будет напрасной.','<Король Ринн смахивает слезу.>$B$B<Король Ринн кивает.>$B$BЭто моя вина.','Вернитесь к королю Вариану Ринну в крепость Штормграда, что в Штормграде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Восставший из праха',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Судьба от рождения начертана огненными письменами в наших душах. Падение Болвара – это трагедия, но оно было неизбежно. $B$BВсе, что ты можешь сделать ныне, $n – это почтить своего героя. Найди на поле боя щит Болвара и возврати его королю. Когда будешь отдавать шит Вариану, скажи ему так: "Не все потеряно. Из праха падшего восстанет сила, которая объединит народы и очистит этот мир от скверны."$B$BОн не должен терять веру. Теперь иди, $n. Твоему народу нужен герой. Им $gнужен:нужна; ты.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите щит Фордрагона на поле боя при Ангратаре, Вратах Гнева. Отнесите щит в крепость Штормграда и вручите королю Вариану Ринну.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Королева Драконов права, $N. Еще не все потеряно. Я буду силой, которая восстанет из пепла, и я очищу зло Орды от этого мира. Смерть наших братьев и сестер не будет напрасной.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Король Ринн смахивает слезу.>$B$B<Король Ринн кивает.>$B$BЭто моя вина.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к королю Вариану Ринну в крепость Штормграда, что в Штормграде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (13348,'Тщета','Теперь понимаешь? Посылая своих бойцов на войну с полчищами принца, вы только пополняете их ряды.$b$bВпрочем, я и не рассчитывал, что ты поймешь... думаю, с тобой будет то же, что и с другими. Возвращайся лучше к тому, кто тебя прислал. Думаю, о тебе тревожатся...','Возвращайтесь к Кольтире Ткачу Смерти на борт "Молота Оргрима".') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тщета',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь понимаешь? Посылая своих бойцов на войну с полчищами принца, вы только пополняете их ряды.$b$bВпрочем, я и не рассчитывал, что ты поймешь... думаю, с тобой будет то же, что и с другими. Возвращайся лучше к тому, кто тебя прислал. Думаю, о тебе тревожатся...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возвращайтесь к Кольтире Ткачу Смерти на борт "Молота Оргрима".',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13349,'Колыбель ледяных драконов','Привет, $N.','Вернитесь к Кольтире Ткачу Смерти на "Молот Оргрима", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Колыбель ледяных драконов',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Привет, $N.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кольтире Ткачу Смерти на "Молот Оргрима", что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13350,'Пусть злодеи не ведают покоя','А, это Алумет... Снова набирает силу. Я это чую. Снова его прихвостни передают магию его душе.$b$bЕсли оставить его в покое, их усилиями он скоро превратится в опасного противника!$b$bВозвращайся в его зал в северной части Алдур\'тара. Собери его сердце, череп, скипетр и одеяние, а потом воздействуй на его останки кристаллом.$b$bТоропись, |3-6($r)! Уничтожь его, пока он не стал слишком могуществен!','Убейте Алумета Перерожденного в Алдур\'таре по просьбе Тассариана, который находится на борту "Усмирителя небес".','Алумет потерпел сокрушительное поражение, но дух его еще здесь, я чувствую это…','Ну что, друг? $GБыл:Была; ли ты $Gуспешен:успешна; против Алумета?','Вернитесь к Тассариану на "Усмиритель небес", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пусть злодеи не ведают покоя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А, это Алумет... Снова набирает силу. Я это чую. Снова его прихвостни передают магию его душе.$b$bЕсли оставить его в покое, их усилиями он скоро превратится в опасного противника!$b$bВозвращайся в его зал в северной части Алдур\'тара. Собери его сердце, череп, скипетр и одеяние, а потом воздействуй на его останки кристаллом.$b$bТоропись, |3-6($r)! Уничтожь его, пока он не стал слишком могуществен!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Алумета Перерожденного в Алдур\'таре по просьбе Тассариана, который находится на борту "Усмирителя небес".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Алумет потерпел сокрушительное поражение, но дух его еще здесь, я чувствую это…',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, друг? $GБыл:Была; ли ты $Gуспешен:успешна; против Алумета?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тассариану на "Усмиритель небес", что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13351,'Предварительная разведка','Дело движется. Мы разработали тактику, которая должна помочь нам взять Врата Смерти под контроль. Конечно, потери будут, и немалые, но в конце концов мы должны победить – особенно если Альянс нам не помешает.$b$bСледующей нашей целью станет Алдур\'тар, Врата Горя. Слетай туда, ознакомься с местностью, посмотри, с чем предстоит иметь дело.$b$bА когда вернешься, я дам тебе новое поручение.','Слетайте к Вратам Горя и ознакомьтесь с южной, центральной, северной и северо-западной частями Врат по просьбе Кольтиры с "Молота Оргрима".','Отлично, отлично, $C!\n\nТеперь, когда ты своими глазами видел, с чем приходится иметь дело, пора браться за работу…','Ты $Gразведал:разведала; врата запустения, $C?','Вернитесь к Кольтире Ткачу Смерти на "Молот Оргрима", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Предварительная разведка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Дело движется. Мы разработали тактику, которая должна помочь нам взять Врата Смерти под контроль. Конечно, потери будут, и немалые, но в конце концов мы должны победить – особенно если Альянс нам не помешает.$b$bСледующей нашей целью станет Алдур\'тар, Врата Горя. Слетай туда, ознакомься с местностью, посмотри, с чем предстоит иметь дело.$b$bА когда вернешься, я дам тебе новое поручение.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Слетайте к Вратам Горя и ознакомьтесь с южной, центральной, северной и северо-западной частями Врат по просьбе Кольтиры с "Молота Оргрима".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, отлично, $C!\n\nТеперь, когда ты своими глазами видел, с чем приходится иметь дело, пора браться за работу…',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gразведал:разведала; врата запустения, $C?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кольтире Ткачу Смерти на "Молот Оргрима", что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13352,'Перетащить и опустить','Так значит, Врата Горя обороняет Культ Проклятых? Неудивительно.$b$bЛадно, пора позабавиться. Ты говоришь, у южной части Врат тренируют новых сектантов? У каждого из них должен быть особый предмет, его выдают всем посвященным – сфера иллюзии.$b$bЭти артефакты используются для того, чтобы маскировать приверженцев секты и позволять им беспрепятственно проходить всюду, где надо, смешиваясь с толпой врагов.$b$bУбивай этих безумцев, пока не добудешь несколько таких сфер, а потом используй их против поработителей.','Отберите сферы иллюзии у озлобленных посвященных в Алдур\'таре и используйте их против 3 темных поработителей по просьбе Кольтиры, который находится на борту "Молота Оргрима".','Да, $R?','Вернитесь к Кольтире Ткачу Смерти на "Молот Оргрима", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Перетащить и опустить',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Так значит, Врата Горя обороняет Культ Проклятых? Неудивительно.$b$bЛадно, пора позабавиться. Ты говоришь, у южной части Врат тренируют новых сектантов? У каждого из них должен быть особый предмет, его выдают всем посвященным – сфера иллюзии.$b$bЭти артефакты используются для того, чтобы маскировать приверженцев секты и позволять им беспрепятственно проходить всюду, где надо, смешиваясь с толпой врагов.$b$bУбивай этих безумцев, пока не добудешь несколько таких сфер, а потом используй их против поработителей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отберите сферы иллюзии у озлобленных посвященных в Алдур\'таре и используйте их против 3 темных поработителей по просьбе Кольтиры, который находится на борту "Молота Оргрима".',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да, $R?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кольтире Ткачу Смерти на "Молот Оргрима", что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13353,'Перетащить и опустить','Что-то эти посвященные опять расплодились! Ты знаешь, что следует делать...$b$bУ южной части врат тренируют новых сектантов. У каждого из них должен быть особый предмет, его выдают всем посвященным – сфера иллюзии.$b$bЭти артефакты используются для того, чтобы маскировать приверженцев секты и позволять им беспрепятственно проходить всюду, где надо, смешиваясь с толпой врагов.$b$bУбивай этих безумцев, пока не добудешь несколько таких сфер, а потом используй сферы против поработителей.','Отберите сферы иллюзии у озлобленных посвященных в Алдур\'таре и используйте их против 3 темных поработителей по просьбе Кольтиры, который находится на борту "Молота Оргрима".','Не правда ли, эффективное оружие – в соответствующих обстоятельствах, конечно?$B$BЭтот трюк никогда не устаревает...','Да, $R?','Вернитесь к Кольтире Ткачу Смерти на "Молот Оргрима", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Перетащить и опустить',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что-то эти посвященные опять расплодились! Ты знаешь, что следует делать...$b$bУ южной части врат тренируют новых сектантов. У каждого из них должен быть особый предмет, его выдают всем посвященным – сфера иллюзии.$b$bЭти артефакты используются для того, чтобы маскировать приверженцев секты и позволять им беспрепятственно проходить всюду, где надо, смешиваясь с толпой врагов.$b$bУбивай этих безумцев, пока не добудешь несколько таких сфер, а потом используй сферы против поработителей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отберите сферы иллюзии у озлобленных посвященных в Алдур\'таре и используйте их против 3 темных поработителей по просьбе Кольтиры, который находится на борту "Молота Оргрима".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Не правда ли, эффективное оружие – в соответствующих обстоятельствах, конечно?$B$BЭтот трюк никогда не устаревает...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да, $R?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кольтире Ткачу Смерти на "Молот Оргрима", что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13354,'Вершина иерархии','Судя по твоему докладу и по тому, что мне известно о культе, в каждом их лагере имеется надзиратель, который всем и заправляет.$b$bРазумеется, уничтожение всех этих предводителей остановит сектантов лишь ненадолго, но все-таки на время выведет их из игры. На данный момент это вполне актуальная задача.$b$bОтыщи этих надзирателей и расправься с ними. Потом возвращайся ко мне.','Отправляйтесь в Алдур\'тар и убейте надзирателя Фэдриса, надзирателя Саврина, надзирателя Веража и надзирателя Джакона про просьбе Кольтиры с "Молота Оргрима".','Отличная работа, $R. Но почивать на лаврах рановато! На место этих надзирателей скоро встанут новые…','Да, $R?','Вернитесь к Кольтире Ткачу Смерти на "Молот Оргрима", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вершина иерархии',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Судя по твоему докладу и по тому, что мне известно о культе, в каждом их лагере имеется надзиратель, который всем и заправляет.$b$bРазумеется, уничтожение всех этих предводителей остановит сектантов лишь ненадолго, но все-таки на время выведет их из игры. На данный момент это вполне актуальная задача.$b$bОтыщи этих надзирателей и расправься с ними. Потом возвращайся ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Алдур\'тар и убейте надзирателя Фэдриса, надзирателя Саврина, надзирателя Веража и надзирателя Джакона про просьбе Кольтиры с "Молота Оргрима".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличная работа, $R. Но почивать на лаврах рановато! На место этих надзирателей скоро встанут новые…',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да, $R?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кольтире Ткачу Смерти на "Молот Оргрима", что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13355,'Невоспроизводимый компонент','Я даже отсюда ощущаю запах, исходящий от их котлов – но нет, это не чумное зелье... $B$BПриверженцев культа заставляют пить смесь, лишающую их воли и навеки обращающую в рабов Короля-лича. $B$BНекоторые говорят, что одним из ингредиентов этого зелья является душа подвергшегося пыткам и безжалостно убитого существа, однако мне никогда не удавалось заполучить подобный компонент...$B$BНаполни эту флягу образцами зелья из трех котлов, находящихся к северо-западу от ворот, и отнеси главному инженеру Меднопалу.','Кольтира с корабля "Молот Оргрима" хочет, чтобы вы наполнили секционную флягу изо всех 3 котлов служителей культа в Алдур\'таре, а затем отнесли ее главному инженеру Меднопалу.','<Меднопал выливает содержимое фляги в свой анализатор жидкостей.>\n\nО! Я знаю нужное вещество!','Ну-ка, |3-6($R), что тут у тебя?','Вернитесь к главному инженеру Меднопалу на "Молот Оргрима", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Невоспроизводимый компонент',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я даже отсюда ощущаю запах, исходящий от их котлов – но нет, это не чумное зелье... $B$BПриверженцев культа заставляют пить смесь, лишающую их воли и навеки обращающую в рабов Короля-лича. $B$BНекоторые говорят, что одним из ингредиентов этого зелья является душа подвергшегося пыткам и безжалостно убитого существа, однако мне никогда не удавалось заполучить подобный компонент...$B$BНаполни эту флягу образцами зелья из трех котлов, находящихся к северо-западу от ворот, и отнеси главному инженеру Меднопалу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Кольтира с корабля "Молот Оргрима" хочет, чтобы вы наполнили секционную флягу изо всех 3 котлов служителей культа в Алдур\'таре, а затем отнесли ее главному инженеру Меднопалу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Меднопал выливает содержимое фляги в свой анализатор жидкостей.>\n\nО! Я знаю нужное вещество!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну-ка, |3-6($R), что тут у тебя?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к главному инженеру Меднопалу на "Молот Оргрима", что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13356,'Все переиграть','Это должно подействовать!$b$bЗначит, эти мерзавцы ищут чужие души, чтобы бросить их в свою безумную похлебку? Ничего, мы им подсобим!$b$bНа-ка, глотни малость! Не тревожься, оно очень сильно разбавлено... ну, по крайней мере, я почти уверен, что оно не окажет никакого эффекта, кроме того, что ты сможешь обнаруживать сущности оскверненного духа поверженных сектантов.$b$bКогда соберешь их побольше, швырни корчащуюся массу искаженных душ в любой из их котлов.$b$bПоглядим, как им понравится собственное лекарство!','Бросьте корчащуюся массу в котел в Алдур\'таре по просьбе главного инженера Меднопала с "Молота Оргрима".','Вернитесь к главному инженеру Меднопалу на "Молот Оргрима", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Все переиграть',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это должно подействовать!$b$bЗначит, эти мерзавцы ищут чужие души, чтобы бросить их в свою безумную похлебку? Ничего, мы им подсобим!$b$bНа-ка, глотни малость! Не тревожься, оно очень сильно разбавлено... ну, по крайней мере, я почти уверен, что оно не окажет никакого эффекта, кроме того, что ты сможешь обнаруживать сущности оскверненного духа поверженных сектантов.$b$bКогда соберешь их побольше, швырни корчащуюся массу искаженных душ в любой из их котлов.$b$bПоглядим, как им понравится собственное лекарство!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Бросьте корчащуюся массу в котел в Алдур\'таре по просьбе главного инженера Меднопала с "Молота Оргрима".',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к главному инженеру Меднопалу на "Молот Оргрима", что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13357,'Все переиграть','Значит, эти мерзавцы ищут чужие души, чтобы бросить их в свою безумную похлебку? Ничего, мы им подсобим!$b$bНа-ка, глотни малость! Не тревожься, оно очень сильно разбавлено... ну, по крайней мере, я почти уверен, что оно не окажет никакого эффекта, кроме того, что ты сможешь обнаруживать сущности поверженных сектантов.$b$bКогда соберешь их побольше, швырни корчащуюся массу искаженных душ в любой из их котлов.$b$bПоглядим, как им понравится собственное лекарство!','Бросьте корчащуюся массу в котел в Алдур\'таре по просьбе главного инженера Меднопала с "Молота Оргрима".','Ур-ра!$B$BТо-то же! Будут знать!','Хорошо? Как все вышло?','Вернитесь к главному инженеру Меднопалу на "Молот Оргрима", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Все переиграть',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Значит, эти мерзавцы ищут чужие души, чтобы бросить их в свою безумную похлебку? Ничего, мы им подсобим!$b$bНа-ка, глотни малость! Не тревожься, оно очень сильно разбавлено... ну, по крайней мере, я почти уверен, что оно не окажет никакого эффекта, кроме того, что ты сможешь обнаруживать сущности поверженных сектантов.$b$bКогда соберешь их побольше, швырни корчащуюся массу искаженных душ в любой из их котлов.$b$bПоглядим, как им понравится собственное лекарство!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Бросьте корчащуюся массу в котел в Алдур\'таре по просьбе главного инженера Меднопала с "Молота Оргрима".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ур-ра!$B$BТо-то же! Будут знать!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Хорошо? Как все вышло?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к главному инженеру Меднопалу на "Молот Оргрима", что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13358,'Ненастоящий шпион','Что ж, $gдружище:барышня;, настало время нам обзавестись шпионом.$b$bНет, не настоящим шпионом, но для наших целей он подойдет.$b$bВ северной части Алдур\'тара сектанты, призыватели Бездны, порабощают демонов. Используй этот жезл, чтобы вытянуть темную сущность из трупов порабощенных слуг, а затем используй их камень призыва, чтобы создать нашего маленького шпиона.$b$bПока этого посланца не обнаружат, он будет нашими глазами и ушами. Он проберется повсюду и будет неприметно наблюдать за врагом.','Соберите 5 темных сущностей и вызовите темного посланника в Алдур\'таре по просьбе Кольтиры, который находится на борту "Молота Оргрима".','Отличная работа, $C!\n\nНаш посланец уже успел раздобыть кое-какую ценную информацию.','Да, $C?','Вернитесь к Кольтире Ткачу Смерти на "Молот Оргрима", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ненастоящий шпион',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что ж, $gдружище:барышня;, настало время нам обзавестись шпионом.$b$bНет, не настоящим шпионом, но для наших целей он подойдет.$b$bВ северной части Алдур\'тара сектанты, призыватели Бездны, порабощают демонов. Используй этот жезл, чтобы вытянуть темную сущность из трупов порабощенных слуг, а затем используй их камень призыва, чтобы создать нашего маленького шпиона.$b$bПока этого посланца не обнаружат, он будет нашими глазами и ушами. Он проберется повсюду и будет неприметно наблюдать за врагом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 5 темных сущностей и вызовите темного посланника в Алдур\'таре по просьбе Кольтиры, который находится на борту "Молота Оргрима".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличная работа, $C!\n\nНаш посланец уже успел раздобыть кое-какую ценную информацию.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да, $C?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кольтире Ткачу Смерти на "Молот Оргрима", что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13359,'Место гибели драконов','Тут погиб целый выводок синих драконов. И вот теперь слуги принца воскрешают их, одного за другим.$b$bСамого могучего воскресил он сам. Принеси мне пыли костей молодых драконов, и я покажу тебе, как он это сделал.','Добудьте в Каньоне Гибели Синдрагосы 6 горстей пыли из костей дракончиков по приказу Матиаса Нетлера.','Даже могучие змеи были вынуждены подчиниться его зову. Неужели простой смертный вроде тебя может надеяться устоять?','Где пыль, $N?','Вернитесь к Матиасу Нетлеру в Каньон Гибели Синдрагосы, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Место гибели драконов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тут погиб целый выводок синих драконов. И вот теперь слуги принца воскрешают их, одного за другим.$b$bСамого могучего воскресил он сам. Принеси мне пыли костей молодых драконов, и я покажу тебе, как он это сделал.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте в Каньоне Гибели Синдрагосы 6 горстей пыли из костей дракончиков по приказу Матиаса Нетлера.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Даже могучие змеи были вынуждены подчиниться его зову. Неужели простой смертный вроде тебя может надеяться устоять?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Где пыль, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Матиасу Нетлеру в Каньон Гибели Синдрагосы, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13360,'Время ответов','Я вижу, у тебя много вопросов, $n. Ты – $gединственный:единственная;, кто может видеть меня, ибо $gкоснулся:коснулась; некоего предмета, принадлежавшего ему... Ты помнишь?$B$BТы не знаешь, что это? Нет-нет, я не могу просто так рассказать тебе... Он разгневается сверх всякой меры, а ведь ныне он не принц, но король!$B$BВстретимся во Дворе Костей, к северу от цитадели Ледяной Короны: там ты $gсам:сама; все увидишь.','Поговорите с Матиасом Нетлером во Дворе Костей.','Ах, вот и ты! Я уже начал сомневаться, придешь ты или нет...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Время ответов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я вижу, у тебя много вопросов, $n. Ты – $gединственный:единственная;, кто может видеть меня, ибо $gкоснулся:коснулась; некоего предмета, принадлежавшего ему... Ты помнишь?$B$BТы не знаешь, что это? Нет-нет, я не могу просто так рассказать тебе... Он разгневается сверх всякой меры, а ведь ныне он не принц, но король!$B$BВстретимся во Дворе Костей, к северу от цитадели Ледяной Короны: там ты $gсам:сама; все увидишь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Матиасом Нетлером во Дворе Костей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ах, вот и ты! Я уже начал сомневаться, придешь ты или нет...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13361,'Охотник и принц','До того как стать королем, принц сражался во многих битвах... Но лишь в одной ему грозила смерть. $B$BБитва свершилась здесь, на этом месте. Позволь мне показать, что случилось, и ты все поймешь.$B$BНайди залитый кровью камень и осмотри его. Тогда тебе откроется прошлое.','Матиас Нетлер со Двора Костей хочет, чтобы вы нашли Окровавленный камень и увидели, что случилось с принцем.','Ты $Gвидел:видела;, $N?','Вернитесь к Матиасу Нетлеру во Двор Костей, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охотник и принц',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','До того как стать королем, принц сражался во многих битвах... Но лишь в одной ему грозила смерть. $B$BБитва свершилась здесь, на этом месте. Позволь мне показать, что случилось, и ты все поймешь.$B$BНайди залитый кровью камень и осмотри его. Тогда тебе откроется прошлое.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Матиас Нетлер со Двора Костей хочет, чтобы вы нашли Окровавленный камень и увидели, что случилось с принцем.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gвидел:видела;, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Матиасу Нетлеру во Двор Костей, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13362,'Знание – тяжкая ноша','Теперь ты знаешь, что тебе предстоит, $n. Противник, которому неведомы ни боль, ни муки совести, ни человеческие чувства... Противник, который готов на все, чтобы добиться своего. $B$BЕдинственная слабость нынешнего короля в том, что его сердце все еще существует; и теперь король знает, что ты $gнашел:нашла; его. $B$BЕсли хочешь вернуться и найти сердце, лучше возьми кого-нибудь в помощь – его хорошо охраняют...','Вернитесь к Кольтире на борт "Молота Оргрима".','Призрак мальчика… Сердце Артаса… Погоди-погоди. У меня голова идет кругом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Знание – тяжкая ноша',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь ты знаешь, что тебе предстоит, $n. Противник, которому неведомы ни боль, ни муки совести, ни человеческие чувства... Противник, который готов на все, чтобы добиться своего. $B$BЕдинственная слабость нынешнего короля в том, что его сердце все еще существует; и теперь король знает, что ты $gнашел:нашла; его. $B$BЕсли хочешь вернуться и найти сердце, лучше возьми кого-нибудь в помощь – его хорошо охраняют...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь к Кольтире на борт "Молота Оргрима".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Призрак мальчика… Сердце Артаса… Погоди-погоди. У меня голова идет кругом.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (13363,'Помощь Серебряного Авангарда','Среди рыцарей смерти ходят слухи о тех событиях, о которых ты говоришь. Я всегда думал, что в этой истории есть... более глубокий смысл.$b$bНадо предупредить остальных, но это нужно сделать тихо. Если Король-лич хоть что-нибудь заподозрит, он тут же переправит Сердце в другое место. А подобного случая более не представится.$b$bКульт Проклятых уже проникал и в Орду, и в Альянс. Черный Клинок действует по соседству с Плетью...$b$bНадо связаться с Тирионом Фордрингом и его Серебряным Авангардом.','Поговорите с верховным лордом Тирионом Фордрингом на Вершине Рыцарей.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Помощь Серебряного Авангарда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Среди рыцарей смерти ходят слухи о тех событиях, о которых ты говоришь. Я всегда думал, что в этой истории есть... более глубокий смысл.$b$bНадо предупредить остальных, но это нужно сделать тихо. Если Король-лич хоть что-нибудь заподозрит, он тут же переправит Сердце в другое место. А подобного случая более не представится.$b$bКульт Проклятых уже проникал и в Орду, и в Альянс. Черный Клинок действует по соседству с Плетью...$b$bНадо связаться с Тирионом Фордрингом и его Серебряным Авангардом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с верховным лордом Тирионом Фордрингом на Вершине Рыцарей.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13364,'Уловка Тириона','Этим утром разведчики сообщили мне, что из цитадели Ледяной Короны к Собору Тьмы движется процессия последователей Культа Проклятых, и что они несут некий артефакт. $B$BА теперь мне стало известно, что этим сокровищем может быть само сердце Артаса... Сердце, хранящее последние крупицы человеческого, еще оставшиеся в нем! $B$BЭто знак свыше. Пока подобный предмет существует, остается надежда, что Артас Менетил вновь сможет стать человеком!$B$BВстретимся у входа в собор. И не забудь прихватить капюшон сектанта-послушника: никто не должен узнать нас.','Тирион Фордринг с Вершины Рыцарей хочет, чтобы вы достали и надели капюшон сектанта-послушника, а затем встретились с ним у входа в Собор Тьмы, к северо-западу от цитадели Ледяной Короны.','Да пребудет с тобой свет, $N.','Вернитесь к верховному лорду Тириону Фордрингу на Вершину Рыцарей, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уловка Тириона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этим утром разведчики сообщили мне, что из цитадели Ледяной Короны к Собору Тьмы движется процессия последователей Культа Проклятых, и что они несут некий артефакт. $B$BА теперь мне стало известно, что этим сокровищем может быть само сердце Артаса... Сердце, хранящее последние крупицы человеческого, еще оставшиеся в нем! $B$BЭто знак свыше. Пока подобный предмет существует, остается надежда, что Артас Менетил вновь сможет стать человеком!$B$BВстретимся у входа в собор. И не забудь прихватить капюшон сектанта-послушника: никто не должен узнать нас.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Тирион Фордринг с Вершины Рыцарей хочет, чтобы вы достали и надели капюшон сектанта-послушника, а затем встретились с ним у входа в Собор Тьмы, к северо-западу от цитадели Ледяной Короны.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да пребудет с тобой свет, $N.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному лорду Тириону Фордрингу на Вершину Рыцарей, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13365,'Ненастоящий шпион','Сектанты отловили последнего отправленного тобой посланника, |3-6($r).$b$bКонечно, он успел доставить нам немало ценных сведений, и все же нам необходимо продолжать следить за каждым их шагом.$b$bИспользуй этот жезл, чтобы вытянуть темную сущность из трупов порабощенных слуг, а затем используй их камень призыва, чтобы создать нового шпиона.$b$bПока этого посланника не обнаружат, он будет нашими глазами и ушами. Он проберется повсюду и будет неприметно наблюдать за врагом.','Соберите 5 темных сущностей и вызовите темного посланника в Алдур\'таре по просьбе Кольтиры, который находится на борту "Молота Оргрима".','Отлично, $Gдруг:подруга; $Gмой:моя;!$B$BПосланец уже продолжает работу…','Да, $C?','Вернитесь к Кольтире Ткачу Смерти на "Молот Оргрима", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ненастоящий шпион',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сектанты отловили последнего отправленного тобой посланника, |3-6($r).$b$bКонечно, он успел доставить нам немало ценных сведений, и все же нам необходимо продолжать следить за каждым их шагом.$b$bИспользуй этот жезл, чтобы вытянуть темную сущность из трупов порабощенных слуг, а затем используй их камень призыва, чтобы создать нового шпиона.$b$bПока этого посланника не обнаружат, он будет нашими глазами и ушами. Он проберется повсюду и будет неприметно наблюдать за врагом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 5 темных сущностей и вызовите темного посланника в Алдур\'таре по просьбе Кольтиры, который находится на борту "Молота Оргрима".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, $Gдруг:подруга; $Gмой:моя;!$B$BПосланец уже продолжает работу…',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да, $C?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кольтире Ткачу Смерти на "Молот Оргрима", что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13366,'Слишком мало сведений','Культ Проклятых известен тем, что вечно строит грандиозные планы, которые никогда не исполняются. Но на этот раз явно вышло иначе...$b$bБыть может, это близкое соседство с Королем-личом на них так повлияло. Как бы то ни было, они держатся увереннее, чем обычно. Необходимо выяснить, что питает их отвагу, а затем найти способ усмирить их!$b$bПодозреваю, что все дело в их ученых. Узнай, что они затевают, и доложи мне во всех подробностях.','Да, это весьма тревожные известия…','Ну что, |3-6($R), удалось ли выяснить, чем заняты их ученые?','Вернитесь к Кольтире Ткачу Смерти на "Молот Оргрима", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Слишком мало сведений',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Культ Проклятых известен тем, что вечно строит грандиозные планы, которые никогда не исполняются. Но на этот раз явно вышло иначе...$b$bБыть может, это близкое соседство с Королем-личом на них так повлияло. Как бы то ни было, они держатся увереннее, чем обычно. Необходимо выяснить, что питает их отвагу, а затем найти способ усмирить их!$b$bПодозреваю, что все дело в их ученых. Узнай, что они затевают, и доложи мне во всех подробностях.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, это весьма тревожные известия…',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, |3-6($R), удалось ли выяснить, чем заняты их ученые?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кольтире Ткачу Смерти на "Молот Оргрима", что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13367,'Пусть злодеи не ведают покоя','Эти глупцы и впрямь обнаружили нечто, что может представлять серьезную угрозу для наших планов!$b$bПредводитель их секты, Алумет, совершил ритуальное самоубийство, и теперь его прихвостни передают его душе свою силу...$b$bЕсли оставить его в покое, их усилиями он скоро превратится в опасного противника!$b$bСобери его сердце, череп, скипетр и одеяние, а потом воздействуй на его останки кристаллом.$b$bТоропись, |3-6($r)! Уничтожь его, пока он не стал слишком силен!','Убейте Алумета Перерожденного в Алдур\'таре по просьбе Кольтиры Ткача Смерти, который находится на борту "Молота Оргрима".','Алумет потерпел сокрушительное поражение, но дух его еще здесь, я чувствую это…','Ну что, $R? Удалось ли тебе остановить Алумета?','Вернитесь к Кольтире Ткачу Смерти на "Молот Оргрима", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пусть злодеи не ведают покоя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти глупцы и впрямь обнаружили нечто, что может представлять серьезную угрозу для наших планов!$b$bПредводитель их секты, Алумет, совершил ритуальное самоубийство, и теперь его прихвостни передают его душе свою силу...$b$bЕсли оставить его в покое, их усилиями он скоро превратится в опасного противника!$b$bСобери его сердце, череп, скипетр и одеяние, а потом воздействуй на его останки кристаллом.$b$bТоропись, |3-6($r)! Уничтожь его, пока он не стал слишком силен!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Алумета Перерожденного в Алдур\'таре по просьбе Кольтиры Ткача Смерти, который находится на борту "Молота Оргрима".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Алумет потерпел сокрушительное поражение, но дух его еще здесь, я чувствую это…',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, $R? Удалось ли тебе остановить Алумета?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кольтире Ткачу Смерти на "Молот Оргрима", что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13368,'Пусть злодеи не ведают покоя','А, это Алумет... Снова набирает силу. Я это чую. Снова его прихвостни передают магию его душе.$b$bЕсли оставить его в покое, их усилиями он скоро превратится в опасного противника!$b$bВозвращайся в его зал в северной части Алдур\'тара. Собери его сердце, череп, скипетр и одеяние, а потом воздействуй на его останки кристаллом.$b$bТоропись, |3-6($r)! Уничтожь его, пока он не стал слишком могуществен!','Убейте Алумета Перерожденного в Алдур\'таре по просьбе Кольтиры Ткача Смерти, который находится на борту "Молота Оргрима".','Алумет потерпел сокрушительное поражение, но дух его еще здесь, я чувствую это…','Ну что, друг? $GБыл:Была; ли ты $Gуспешен:успешна; против Алумета?','Вернитесь к Кольтире Ткачу Смерти на "Молот Оргрима", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пусть злодеи не ведают покоя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А, это Алумет... Снова набирает силу. Я это чую. Снова его прихвостни передают магию его душе.$b$bЕсли оставить его в покое, их усилиями он скоро превратится в опасного противника!$b$bВозвращайся в его зал в северной части Алдур\'тара. Собери его сердце, череп, скипетр и одеяние, а потом воздействуй на его останки кристаллом.$b$bТоропись, |3-6($r)! Уничтожь его, пока он не стал слишком могуществен!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Алумета Перерожденного в Алдур\'таре по просьбе Кольтиры Ткача Смерти, который находится на борту "Молота Оргрима".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Алумет потерпел сокрушительное поражение, но дух его еще здесь, я чувствую это…',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, друг? $GБыл:Была; ли ты $Gуспешен:успешна; против Алумета?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кольтире Ткачу Смерти на "Молот Оргрима", что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13369,'Против воли рока','По просьбе леди Праудмур я позволю ей отправиться в Оргриммар с посольством, дабы говорить с военачальником Орды Траллом. Ты будешь сопровождать и оберегать ее в пути. По возвращении я хочу узнать вести из Оргриммара.$B$BКогда будешь $gготов: готова;, поговори с Джайной.','Сопроводите леди Джайну Праудмур в Калимдор в Оргриммар. Поговорите с военачальником Орды Траллом.','Орда не хочет войны, $R. Слушай...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Против воли рока',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','По просьбе леди Праудмур я позволю ей отправиться в Оргриммар с посольством, дабы говорить с военачальником Орды Траллом. Ты будешь сопровождать и оберегать ее в пути. По возвращении я хочу узнать вести из Оргриммара.$B$BКогда будешь $gготов: готова;, поговори с Джайной.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сопроводите леди Джайну Праудмур в Калимдор в Оргриммар. Поговорите с военачальником Орды Траллом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Орда не хочет войны, $R. Слушай...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13370,'Королевский ход','Ваш воитель, Болвар, погиб, защищая весь наш мир. Орда опечалена гибелью такого героя, однако Орда не в ответе за трусливое нападение Гнилесса у врат Гнева. Мы тоже потеряли немало героев из-за его предательства. $b$bПередай вашему королю, что мы сделаем все, что в наших силах, чтобы призвать к ответу виновников этого злобного деяния. Мы также сделаем все возможно, дабы избежать конфликта с Альянсом. Однако если на нас нападут, мы будем защищаться без колебаний.','Воспользуйтесь порталом в крепости Громмаш, чтобы вернуться в крепость Штормграда и передать послание Тралла королю Вариану Ринну.','Они потеряли Подгород? Тогда настало время нанести удар. Мы сами разберемся с Гнилессом и отвоюем Руины Лордерона для Альянса!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Королевский ход',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ваш воитель, Болвар, погиб, защищая весь наш мир. Орда опечалена гибелью такого героя, однако Орда не в ответе за трусливое нападение Гнилесса у врат Гнева. Мы тоже потеряли немало героев из-за его предательства. $b$bПередай вашему королю, что мы сделаем все, что в наших силах, чтобы призвать к ответу виновников этого злобного деяния. Мы также сделаем все возможно, дабы избежать конфликта с Альянсом. Однако если на нас нападут, мы будем защищаться без колебаний.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь порталом в крепости Громмаш, чтобы вернуться в крепость Штормграда и передать послание Тралла королю Вариану Ринну.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Они потеряли Подгород? Тогда настало время нанести удар. Мы сами разберемся с Гнилессом и отвоюем Руины Лордерона для Альянса!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13371,'В ожидании дальнейших распоряжений','Когда ты $gушел:ушла; в Оргриммар, я послал в Подгород Бролла и Валиру. Сейчас они расположились рядом с канализационным коллектором у входа в развалины и ждут дальнейших указаний.$B$BЛеди Праудмур откроет портал для наших войск прямо на подступах к Подгороду. Иди туда и разыщи Бролла. Мы с Джайной подтянемся чуть позже, но уже очень скоро.','Воспользуйтесь порталом в крепости Штормграда и телепортируйтесь в Подгород. Когда прибудете на место, разыщите Бролла Медвежью Шкуру.','Кто ты? Вариан сказал, что пошлет героя.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В ожидании дальнейших распоряжений',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда ты $gушел:ушла; в Оргриммар, я послал в Подгород Бролла и Валиру. Сейчас они расположились рядом с канализационным коллектором у входа в развалины и ждут дальнейших указаний.$B$BЛеди Праудмур откроет портал для наших войск прямо на подступах к Подгороду. Иди туда и разыщи Бролла. Мы с Джайной подтянемся чуть позже, но уже очень скоро.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь порталом в крепости Штормграда и телепортируйтесь в Подгород. Когда прибудете на место, разыщите Бролла Медвежью Шкуру.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Кто ты? Вариан сказал, что пошлет героя.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (13372,'Ключ к Радужному Средоточию','Эти ключи принадлежат самым древним из синих драконов. Только им доверял их владыка, Малигос.$B$BПохоже, настал переломный момент, которого мы ждали, чтобы нанести удар по Аспекту Магии!$B$B<Королева драконов внимательно разглядывает вас.>$B$BТы не сможешь самостоятельно использовать ключ для доступа к Радужному Средоточию, но я могу наделить тебя толикой моей силы; этого хватит, чтобы немного приоткрыть Средоточие.$B$BМалигос это сразу заметит и не замедлит явиться, чтобы обрушить свой гнев на того, кто дерзнул подступиться к Средоточию!','Вернитесь к Алекстразе Хранительнице Жизни в Драконьи пустоши, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ключ к Радужному Средоточию',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Эти ключи принадлежат самым древним из синих драконов. Только им доверял их владыка, Малигос.$B$BПохоже, настал переломный момент, которого мы ждали, чтобы нанести удар по Аспекту Магии!$B$B<Королева драконов внимательно разглядывает вас.>$B$BТы не сможешь самостоятельно использовать ключ для доступа к Радужному Средоточию, но я могу наделить тебя толикой моей силы; этого хватит, чтобы немного приоткрыть Средоточие.$B$BМалигос это сразу заметит и не замедлит явиться, чтобы обрушить свой гнев на того, кто дерзнул подступиться к Средоточию!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Алекстразе Хранительнице Жизни в Драконьи пустоши, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13373,'Последнее слово техники','Я установила инфразеленые излучатели на захваченные бомбардировщики. Они действуют как щиты и защитят тебя в первом боевом вылете на вражескую территорию. Поговори с Риззи Храпокруткой, возьми бомбардировщик и лети в Зону бомбардировки!$B$BУ тебя будет полный боекомплект: бомбы, ракеты и щиты. Следи за тем, чтобы щиты не разряжались, и уничтожай наземные войска Плети, расположившиеся в Зоне бомбардировки. Потом возвращайся сюда. У тебя будет новое задание.','Уничтожьте 40 пехотинцев из зоны бомбардировки, 8 капитанов из зоны бомбардировки и 15 горгулий-душительниц по заданию инженера-экспериментатора Теззлы.','Ага, у тебя получилось! И как тебе бомбардировщик? Надеюсь, ты с ним сроднился, потому что тебе предстоит новый боевой вылет... и на этот раз все будет гораздо серьезнее...','Ты не $Gдостиг:достигла; своей целевой квоты, $N. Бомбардировщиками слишком сложно управлять?','Вернитесь к инженеру-экспериментатору Теззле в Алдур\'тар: Врата Горя, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Последнее слово техники',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я установила инфразеленые излучатели на захваченные бомбардировщики. Они действуют как щиты и защитят тебя в первом боевом вылете на вражескую территорию. Поговори с Риззи Храпокруткой, возьми бомбардировщик и лети в Зону бомбардировки!$B$BУ тебя будет полный боекомплект: бомбы, ракеты и щиты. Следи за тем, чтобы щиты не разряжались, и уничтожай наземные войска Плети, расположившиеся в Зоне бомбардировки. Потом возвращайся сюда. У тебя будет новое задание.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 40 пехотинцев из зоны бомбардировки, 8 капитанов из зоны бомбардировки и 15 горгулий-душительниц по заданию инженера-экспериментатора Теззлы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ага, у тебя получилось! И как тебе бомбардировщик? Надеюсь, ты с ним сроднился, потому что тебе предстоит новый боевой вылет... и на этот раз все будет гораздо серьезнее...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты не $Gдостиг:достигла; своей целевой квоты, $N. Бомбардировщиками слишком сложно управлять?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к инженеру-экспериментатору Теззле в Алдур\'тар: Врата Горя, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (13374,'Боевое задание','$n, такие задания мы даем только самым лучшим пилотам: проникнуть вглубь вражеской территории, практически безо всякой защиты, не считая энергетических щитов инфразеленого излучения.$B$BВозьми у Риззи еще один бомбардировщик и лети в долину Потерянной Надежды. На этот раз целей будет гораздо больше: как на земле, так и в воздухе. Так что смотри в оба и следи за тем, чтобы щиты не разрядились!$B$BУдачи!','Уничтожьте пехотинцев из зоны бомбардировки, боевые машины Плети, горгулий-душительниц и часовых ледяных драконов по заданию инженера-экспериментатора Теззлы.','Ты $Gсделал:сделала; это, ты $Gсделал:сделала; это! Ты $Gотличный:отличная; $Gстрелок:охотница;, и ты хвалишь мою инфра-зеленую технологию, как смазку на гидрокарбонате!','Вернитесь к инженеру-экспериментатору Теззле в Зону бомбардировки, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Боевое задание',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, такие задания мы даем только самым лучшим пилотам: проникнуть вглубь вражеской территории, практически безо всякой защиты, не считая энергетических щитов инфразеленого излучения.$B$BВозьми у Риззи еще один бомбардировщик и лети в долину Потерянной Надежды. На этот раз целей будет гораздо больше: как на земле, так и в воздухе. Так что смотри в оба и следи за тем, чтобы щиты не разрядились!$B$BУдачи!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте пехотинцев из зоны бомбардировки, боевые машины Плети, горгулий-душительниц и часовых ледяных драконов по заданию инженера-экспериментатора Теззлы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты $Gсделал:сделала; это, ты $Gсделал:сделала; это! Ты $Gотличный:отличная; $Gстрелок:охотница;, и ты хвалишь мою инфра-зеленую технологию, как смазку на гидрокарбонате!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к инженеру-экспериментатору Теззле в Зону бомбардировки, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (13375,'Ключ к Радужному Средоточию (героический режим)','Эти ключи принадлежат самым древним из синих драконов. Только им доверял их владыка, Малигос.$B$BПохоже, настал переломный момент, которого мы ждали, чтобы нанести удар по Аспекту Магии!$B$B<Королева драконов внимательно разглядывает вас.>$B$BТы не сможешь самостоятельно использовать ключ для доступа к Радужному Средоточию, но я могу наделить тебя толикой моей силы; этого хватит, чтобы немного приоткрыть Средоточие.$B$BМалигос это сразу заметит и не замедлит явиться, чтобы обрушить свой гнев на того, кто дерзнул подступиться к Средоточию!','Вернитесь к Алекстразе Хранительнице Жизни в Драконьи пустоши, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ключ к Радужному Средоточию (героический режим)',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Эти ключи принадлежат самым древним из синих драконов. Только им доверял их владыка, Малигос.$B$BПохоже, настал переломный момент, которого мы ждали, чтобы нанести удар по Аспекту Магии!$B$B<Королева драконов внимательно разглядывает вас.>$B$BТы не сможешь самостоятельно использовать ключ для доступа к Радужному Средоточию, но я могу наделить тебя толикой моей силы; этого хватит, чтобы немного приоткрыть Средоточие.$B$BМалигос это сразу заметит и не замедлит явиться, чтобы обрушить свой гнев на того, кто дерзнул подступиться к Средоточию!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Алекстразе Хранительнице Жизни в Драконьи пустоши, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13376,'Война продолжается','Война продолжается, $n. К счастью, у нас есть хороший запас бомб и ракет! Самое время испытать наш инфразеленый бомбардировщик и разорвать этих мерзавцев из Плети на мелкие плеточки!','Уничтожьте 50 пехотинцев из зоны бомбардировки, 12 боевых машин Плети, 20 горгулий-душительниц и 12 часовых ледяных драконов по заданию инженера-экспериментатора Теззлы.','Чего ты ждешь? У нас есть машины и боеприпасы... нам нужны только отважные канониры, чтобы применить их в деле.','Вернитесь к инженеру-экспериментатору Теззле в Алдур\'тар: Врата Горя, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Война продолжается',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Война продолжается, $n. К счастью, у нас есть хороший запас бомб и ракет! Самое время испытать наш инфразеленый бомбардировщик и разорвать этих мерзавцев из Плети на мелкие плеточки!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 50 пехотинцев из зоны бомбардировки, 12 боевых машин Плети, 20 горгулий-душительниц и 12 часовых ледяных драконов по заданию инженера-экспериментатора Теззлы.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Чего ты ждешь? У нас есть машины и боеприпасы... нам нужны только отважные канониры, чтобы применить их в деле.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к инженеру-экспериментатору Теззле в Алдур\'тар: Врата Горя, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`) VALUES (13377,'Битва за Подгород','Глубоко в недрах Подгорода прячется убийца, ответственный за гибель Болвара и наших отважных солдат у Врат Гнева.$b$bВариан привел сюда с собой всю мощь Альянса, чтобы взять город. Присоединись к нему и к леди Праудмур в охоте на ассасина! Это позволит тебе стать $gодним:одной; из первых героев Альянса!$b$bКогда будешь $gготов:готова;, поговори с королем Варианом Ринном.','Помогите королю Вариану Ринну и леди Джайне Праудмур покарать верховного аптекаря Гнилесса! Если вам это удастся, явитесь к королю Вариану Ринну.','Слишком долго Орда оставалась без внимания. Мы позволили их территориям процветать и в обмен на нашу щедрость они замыслили и запланировали нашу гибель.$B$BМир? Бесполезно... Это ни к чему не привело. Мы потеряли некоторых из наших величайших героев из-за «мира». Посмотрим, что принесет битва...$B$BВернитесь в Нордскол, $N. Покори его ради своего короля - ЗА АЛЬЯНС!','Помочь королю Вариану Ринну','Вернитесь к королю Вариану Ринну в крепость Штормграда, что в Штормграде.','Помочь королю Вариану Ринну') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Битва за Подгород',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Глубоко в недрах Подгорода прячется убийца, ответственный за гибель Болвара и наших отважных солдат у Врат Гнева.$b$bВариан привел сюда с собой всю мощь Альянса, чтобы взять город. Присоединись к нему и к леди Праудмур в охоте на ассасина! Это позволит тебе стать $gодним:одной; из первых героев Альянса!$b$bКогда будешь $gготов:готова;, поговори с королем Варианом Ринном.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Помогите королю Вариану Ринну и леди Джайне Праудмур покарать верховного аптекаря Гнилесса! Если вам это удастся, явитесь к королю Вариану Ринну.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Слишком долго Орда оставалась без внимания. Мы позволили их территориям процветать и в обмен на нашу щедрость они замыслили и запланировали нашу гибель.$B$BМир? Бесполезно... Это ни к чему не привело. Мы потеряли некоторых из наших величайших героев из-за «мира». Посмотрим, что принесет битва...$B$BВернитесь в Нордскол, $N. Покори его ради своего короля - ЗА АЛЬЯНС!',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Помочь королю Вариану Ринну',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к королю Вариану Ринну в крепость Штормграда, что в Штормграде.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Помочь королю Вариану Ринну',`questgivertextwindow_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (13378,'Главный инженер Меднопал','Поговорите с главным инженером Меднопалом','Поговорите с главным инженером Меднопалом') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Главный инженер Меднопал',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Поговорите с главным инженером Меднопалом',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с главным инженером Меднопалом',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13379,'Зеленые технологии','Надо тебя познакомить с Теззлой. Да, точно! Она научилась использовать новое волновое излучение – инфразеленое – и с его помощью ей удалось подобраться поближе к армии Плети! Достаточно близко, чтобы сбрасывать на них бомбы!$B$BЯ наделю тебя способностью видеть в инфразеленом диапазоне, чтобы разыскать ее над Алдур\'таром, Вратами Горя. Отправляйся немедленно... насколько я знаю, у нее всегда найдется работа для отважных героев, которые не прочь повзрывать то да се! Особенно прислужников Плети!$B$BИ еще $n, Альянс украл нашу технологию, и у него есть собственный невидимый аэропорт неподалеку. Избегай строений со знаменами Альянса!','Поговорите с инженером-экспериментатором Теззлой.','Да, да! Ты нашел меня! И очень вовремя!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зеленые технологии',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Надо тебя познакомить с Теззлой. Да, точно! Она научилась использовать новое волновое излучение – инфразеленое – и с его помощью ей удалось подобраться поближе к армии Плети! Достаточно близко, чтобы сбрасывать на них бомбы!$B$BЯ наделю тебя способностью видеть в инфразеленом диапазоне, чтобы разыскать ее над Алдур\'таром, Вратами Горя. Отправляйся немедленно... насколько я знаю, у нее всегда найдется работа для отважных героев, которые не прочь повзрывать то да се! Особенно прислужников Плети!$B$BИ еще $n, Альянс украл нашу технологию, и у него есть собственный невидимый аэропорт неподалеку. Избегай строений со знаменами Альянса!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с инженером-экспериментатором Теззлой.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, да! Ты нашел меня! И очень вовремя!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13380,'Возглавить нападение','Технология инфразеленого излучения позволяет нам оставаться "невидимыми" прямо под носом у Плети! Больше того, мы установили инфразеленые излучатели на специально сконструированные бомбардировщики... но вовсе не для того, чтобы скрыть эти машины от глаз врага, нет! Мы используем излучение как щит!$B$BСтупай туда, где стоит Карен Нет, попроси бомбардировщик. Лети в Зону бомбардировки... используй щиты и пушку для защиты, а бомбометы – понятное дело, для бомбометания. В общем, потренируйся, а потом возвращайся ко мне. Я дам тебе новое задание, которое будет уже посерьезнее!','Убейте 40 пехотинцев из зоны бомбардировки, 8 капитанов из зоны бомбардировки и 15 горгулий-душительниц по заданию Кибли Киллогерца.','Отсюда я слышал взрывы, $N. Как сработали щиты? Они сохранили твой бомбардировщик?$B$BНадеюсь, они это сделали, потому что теперь у меня для тебя больше миссий.','$N, бомбардировщики сложно использовать, но ты $Gдолжен:должна; справиться с ними, если мы хотим победить в борьбе с Плетью.','Вернитесь к Кибли Киллогерцу в Алдур\'тар: Врата Горя, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возглавить нападение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Технология инфразеленого излучения позволяет нам оставаться "невидимыми" прямо под носом у Плети! Больше того, мы установили инфразеленые излучатели на специально сконструированные бомбардировщики... но вовсе не для того, чтобы скрыть эти машины от глаз врага, нет! Мы используем излучение как щит!$B$BСтупай туда, где стоит Карен Нет, попроси бомбардировщик. Лети в Зону бомбардировки... используй щиты и пушку для защиты, а бомбометы – понятное дело, для бомбометания. В общем, потренируйся, а потом возвращайся ко мне. Я дам тебе новое задание, которое будет уже посерьезнее!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 40 пехотинцев из зоны бомбардировки, 8 капитанов из зоны бомбардировки и 15 горгулий-душительниц по заданию Кибли Киллогерца.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отсюда я слышал взрывы, $N. Как сработали щиты? Они сохранили твой бомбардировщик?$B$BНадеюсь, они это сделали, потому что теперь у меня для тебя больше миссий.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$N, бомбардировщики сложно использовать, но ты $Gдолжен:должна; справиться с ними, если мы хотим победить в борьбе с Плетью.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кибли Киллогерцу в Алдур\'тар: Врата Горя, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (13381,'Боевой вылет','Надевай свои счастливые носки, $n, и читай все любимые молитвы. Твое следующее задание – это будет уже настоящее испытание находчивости, и смекалки, и силы духа. Прямо как нежданный визит обожаемой $gтещи:свекрови;, хе-хе!$B$BПусть Карен Но даст тебе еще один бомбардировщик. Лети за Зону бомбардировки, к долине Потерянной Надежды. На этот раз целей будет гораздо больше: как на земле, так и в воздухе. В общем, чтоб тебе долететь и туда и обратно, и боеприпасы не кончились, и заряд у щитов не иссяк. Встретимся после боя, $n!','Уничтожьте пехотинцев из зоны бомбардировки, боевые машины Плети, горгулий-душительниц и часовых ледяных драконов по заданию Кибли Киллогерца.','Ты $Gвернулся:вернулась;! И все в одном куске! У тебя есть настоящие навыки, $N. Вы играли много рук и глаз координации игр, как ребенок? Это видно...','Вернитесь к Кибли Киллогерцу в Алдур\'тар: Врата Горя, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Боевой вылет',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Надевай свои счастливые носки, $n, и читай все любимые молитвы. Твое следующее задание – это будет уже настоящее испытание находчивости, и смекалки, и силы духа. Прямо как нежданный визит обожаемой $gтещи:свекрови;, хе-хе!$B$BПусть Карен Но даст тебе еще один бомбардировщик. Лети за Зону бомбардировки, к долине Потерянной Надежды. На этот раз целей будет гораздо больше: как на земле, так и в воздухе. В общем, чтоб тебе долететь и туда и обратно, и боеприпасы не кончились, и заряд у щитов не иссяк. Встретимся после боя, $n!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте пехотинцев из зоны бомбардировки, боевые машины Плети, горгулий-душительниц и часовых ледяных драконов по заданию Кибли Киллогерца.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты $Gвернулся:вернулась;! И все в одном куске! У тебя есть настоящие навыки, $N. Вы играли много рук и глаз координации игр, как ребенок? Это видно...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кибли Киллогерцу в Алдур\'тар: Врата Горя, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13382,'Килотонны смерти','Бой продолжается! Для тебя есть задание дальнего действия. Цель – бомбардировка Долины Потерянной Надежды. Когда будешь $gготов:готова;, пусть Карен даст тебе бомбардировщик. Сбрось все ракеты и бомбы на головы этих уродов Плети!','Уничтожьте 50 пехотинцев из зоны бомбардировки, 12 боевых машин Плети, 20 горгулий-душительниц и 12 часовых ледяных драконов по заданию Кибли Киллогерца.','С возвращением, $N. Как прошел бой? Захватывающе? А пока отдохни. Но возвращайся, когда у тебя будут новые задания.$B$BЗа Альянс!','Держись, $N. Сама по себе воздушная битва не выиграет!','Вернитесь к Кибли Киллогерцу в Алдур\'тар: Врата Горя, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Килотонны смерти',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Бой продолжается! Для тебя есть задание дальнего действия. Цель – бомбардировка Долины Потерянной Надежды. Когда будешь $gготов:готова;, пусть Карен даст тебе бомбардировщик. Сбрось все ракеты и бомбы на головы этих уродов Плети!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 50 пехотинцев из зоны бомбардировки, 12 боевых машин Плети, 20 горгулий-душительниц и 12 часовых ледяных драконов по заданию Кибли Киллогерца.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','С возвращением, $N. Как прошел бой? Захватывающе? А пока отдохни. Но возвращайся, когда у тебя будут новые задания.$B$BЗа Альянс!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Держись, $N. Сама по себе воздушная битва не выиграет!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кибли Киллогерцу в Алдур\'тар: Врата Горя, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13383,'Киллогерц','Гоблинам удалось открыть новую форму энергии. Они называют ее инфразеленым излучением, и это действительно зеленое золото с технологической точки зрения. Они, ясное дело, те еще психопаты, но мозги у них есть, и иногда они даже работают. Стыдно признаться, но мы выкрали их технологию. Однако я с гордостью заявляю, что мы ее усовершенствовали!$B$BРазыщи Кибли Киллогерца. Он у нас главный по разработкам инфразеленого излучения. Его база находится в маленьком секретном аэропорту Альянса над Алдур\'таром, Вратами Горя. Я дам тебе прибор инфразеленого видения, чтобы ты $gсмог:смогла; найти аэропорт.','Разыщите Кибли Киллогерца на базе в скрытом аэропорту Альянса над Алдур\'таром, Вратами Горя, по приказу главного инженера Болтоключа.','Да, да, да! Тысячу раз привет!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Киллогерц',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Гоблинам удалось открыть новую форму энергии. Они называют ее инфразеленым излучением, и это действительно зеленое золото с технологической точки зрения. Они, ясное дело, те еще психопаты, но мозги у них есть, и иногда они даже работают. Стыдно признаться, но мы выкрали их технологию. Однако я с гордостью заявляю, что мы ее усовершенствовали!$B$BРазыщи Кибли Киллогерца. Он у нас главный по разработкам инфразеленого излучения. Его база находится в маленьком секретном аэропорту Альянса над Алдур\'таром, Вратами Горя. Я дам тебе прибор инфразеленого видения, чтобы ты $gсмог:смогла; найти аэропорт.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите Кибли Киллогерца на базе в скрытом аэропорту Альянса над Алдур\'таром, Вратами Горя, по приказу главного инженера Болтоключа.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, да, да! Тысячу раз привет!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13384,'Правосудие в Оке Вечности','Теперь, когда у тебя есть доступ к Радужному Средоточию, нужно использовать его в деле.$B$BКак бы мне ни хотелось, чтобы Малигос снова стал одним из нас, я понимаю, что это уже невозможно. Слишком многое поставлено на карту, и другие драконьи Аспекты решили, что Хранитель Магии должен умереть.$B$B<Крас произносит эти слова с дрожью в голосе.>$B$B$n, отправляйся к Оку Вечности, убей Малигоса и возвращайся сюда с Сердцем Магии.','Принесите Сердце Магии Красу на вершине храма Драконьего Покоя в Драконьем Погосте.$B$BЭто задание предназначено для обычного уровня сложности и представляет собой версию Ока Вечности для 10 игроков.','Сегодняшний день принес скорбную весть, и не только для драконов, но и для всех обитателей Азерота. Мы потеряли одного из самых старых и мудрых друзей. Магия осталась без хранителя.$B$BБудем надеяться, $N, что это было правильное решение. Буря на горизонте все еще набирает силу, а мы лишились одного из самых могущественных защитников.','Лишь Малигос обладает Сердцем Магии. Это самое ценное, что у него есть.','Вернитесь к Красу в Храм Драконьего Покоя, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Правосудие в Оке Вечности',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда у тебя есть доступ к Радужному Средоточию, нужно использовать его в деле.$B$BКак бы мне ни хотелось, чтобы Малигос снова стал одним из нас, я понимаю, что это уже невозможно. Слишком многое поставлено на карту, и другие драконьи Аспекты решили, что Хранитель Магии должен умереть.$B$B<Крас произносит эти слова с дрожью в голосе.>$B$B$n, отправляйся к Оку Вечности, убей Малигоса и возвращайся сюда с Сердцем Магии.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Сердце Магии Красу на вершине храма Драконьего Покоя в Драконьем Погосте.$B$BЭто задание предназначено для обычного уровня сложности и представляет собой версию Ока Вечности для 10 игроков.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сегодняшний день принес скорбную весть, и не только для драконов, но и для всех обитателей Азерота. Мы потеряли одного из самых старых и мудрых друзей. Магия осталась без хранителя.$B$BБудем надеяться, $N, что это было правильное решение. Буря на горизонте все еще набирает силу, а мы лишились одного из самых могущественных защитников.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Лишь Малигос обладает Сердцем Магии. Это самое ценное, что у него есть.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Красу в Храм Драконьего Покоя, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13385,'Героическое правосудие в Оке Вечности','Теперь, когда у тебя есть доступ к Радужному Средоточию, нужно использовать его в деле.$B$BКак бы мне ни хотелось, чтобы Малигос снова стал одним из нас, я понимаю, что это уже невозможно. Слишком многое поставлено на карту, и другие драконьи Аспекты решили, что Хранитель Магии должен умереть.$B$B<Крас произносит эти слова с дрожью в голосе.>$B$B$n, отправляйся к Оку Вечности, убей Малигоса и возвращайся сюда с Сердцем Магии.','Принесите Сердце Магии Красу на вершине храма Драконьего Покоя в Драконьем Погосте.$B$BЭто задание предназначено для героического уровня сложности и представляет собой версию Ока Вечности для 25 игроков.','Сегодняшний день принес скорбную весть, и не только для драконов, но и для всех обитателей Азерота. Мы потеряли одного из самых старых и мудрых друзей. Магия осталась без хранителя.$B$BБудем надеяться, $N, что это было правильное решение. Буря на горизонте все еще набирает силу, а мы лишились одного из самых могущественных защитников.','Лишь Малигос обладает Сердцем Магии. Это самое ценное, что у него есть.','Вернитесь к Красу в Храм Драконьего Покоя, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Героическое правосудие в Оке Вечности',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда у тебя есть доступ к Радужному Средоточию, нужно использовать его в деле.$B$BКак бы мне ни хотелось, чтобы Малигос снова стал одним из нас, я понимаю, что это уже невозможно. Слишком многое поставлено на карту, и другие драконьи Аспекты решили, что Хранитель Магии должен умереть.$B$B<Крас произносит эти слова с дрожью в голосе.>$B$B$n, отправляйся к Оку Вечности, убей Малигоса и возвращайся сюда с Сердцем Магии.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Сердце Магии Красу на вершине храма Драконьего Покоя в Драконьем Погосте.$B$BЭто задание предназначено для героического уровня сложности и представляет собой версию Ока Вечности для 25 игроков.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сегодняшний день принес скорбную весть, и не только для драконов, но и для всех обитателей Азерота. Мы потеряли одного из самых старых и мудрых друзей. Магия осталась без хранителя.$B$BБудем надеяться, $N, что это было правильное решение. Буря на горизонте все еще набирает силу, а мы лишились одного из самых могущественных защитников.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Лишь Малигос обладает Сердцем Магии. Это самое ценное, что у него есть.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Красу в Храм Драконьего Покоя, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (13386,'Разведка провала','Поговорите с капитаном Кендаллом под цитаделью Ледяной Короны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разведка провала',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с капитаном Кендаллом под цитаделью Ледяной Короны.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13387,'Круговая оборона','Саронитовые бомбы уже заложены, $n. Однако воспользоваться ими мы сможем только один раз. Надо использовать эту возможность максимально эффективно.$b$bЧтобы благополучно их взорвать, нужно хотя бы на время обеспечить себе контроль над этой территорией. Надо постараться уменьшить численность воинов Плети.','Капитан Кендалл у цитадели Ледяной Короны просит вас убить 10 неповоротливых громад.','Да, Тассариан не обманул меня, ты и впрямь молодец. Комар носу не подточит!','За Альянс!','Вернитесь к капитану Кендаллу в Цитадель Ледяной Короны, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Круговая оборона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Саронитовые бомбы уже заложены, $n. Однако воспользоваться ими мы сможем только один раз. Надо использовать эту возможность максимально эффективно.$b$bЧтобы благополучно их взорвать, нужно хотя бы на время обеспечить себе контроль над этой территорией. Надо постараться уменьшить численность воинов Плети.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Капитан Кендалл у цитадели Ледяной Короны просит вас убить 10 неповоротливых громад.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, Тассариан не обманул меня, ты и впрямь молодец. Комар носу не подточит!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','За Альянс!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Кендаллу в Цитадель Ледяной Короны, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13388,'Поджигай!','Все идет отлично. Можно браться за дело.$b$bБомбы заложены у самой ямы. Я начинаю эвакуировать наших.','Капитан Кендалл под стенами цитадели Ледяной Короны просит вас отправиться к ближайшему штабелю саронитовых бомб и поджечь фитиль.','Похоже, эти бомбы довольно мощные. Они должны как минимум повредить стену.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поджигай!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Все идет отлично. Можно браться за дело.$b$bБомбы заложены у самой ямы. Я начинаю эвакуировать наших.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Капитан Кендалл под стенами цитадели Ледяной Короны просит вас отправиться к ближайшему штабелю саронитовых бомб и поджечь фитиль.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Похоже, эти бомбы довольно мощные. Они должны как минимум повредить стену.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13389,'Фитиль короток!','Не успев поджечь фитиль, вы обнаруживаете, что он сгорает куда быстрее, чем вы рассчитывали!$b$bБомбы вот-вот рванут. Ваш единственный шанс на спасение – броситься в провал и надеяться, что там не слишком глубоко.','Там, куда вы падаете, вас ждет кое-что интересное!','Этот пульсирующий предмет закован в толстый слой льда. Он странно мерцает из-под воды.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Фитиль короток!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не успев поджечь фитиль, вы обнаруживаете, что он сгорает куда быстрее, чем вы рассчитывали!$b$bБомбы вот-вот рванут. Ваш единственный шанс на спасение – броситься в провал и надеяться, что там не слишком глубоко.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Там, куда вы падаете, вас ждет кое-что интересное!',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Этот пульсирующий предмет закован в толстый слой льда. Он странно мерцает из-под воды.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13390,'Голос во тьме','Нет, это не кристалл, это какой-то замороженный орган...$b$bВы прикасаетесь к нему – и руку пронзает немыслимая боль. Такое ощущение, будто руку отрубили напрочь. Но никаких ран на ней не заметно...$b$bПытаясь собраться с мыслями, вы вдруг слышите где-то рядом мальчишеский голос.$b$b"Не стоило тебе этого делать, ой, не стоило!"','Выясните, откуда доносится голос, который вы услышали в Наз\'анаке, Забытых глубинах.','Я видел, как он от него избавился, прикинь? Он швырнул его прямо сюда, вниз!$B$BСказал, что больше оно ему не понадобится. Сказал, оно делает его слабым.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Голос во тьме',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нет, это не кристалл, это какой-то замороженный орган...$b$bВы прикасаетесь к нему – и руку пронзает немыслимая боль. Такое ощущение, будто руку отрубили напрочь. Но никаких ран на ней не заметно...$b$bПытаясь собраться с мыслями, вы вдруг слышите где-то рядом мальчишеский голос.$b$b"Не стоило тебе этого делать, ой, не стоило!"',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выясните, откуда доносится голос, который вы услышали в Наз\'анаке, Забытых глубинах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я видел, как он от него избавился, прикинь? Он швырнул его прямо сюда, вниз!$B$BСказал, что больше оно ему не понадобится. Сказал, оно делает его слабым.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13391,'Пора прятаться!','Не стоило тебе трогать эту штуку! Теперь он непременно явится искать тебя.$b$bИ он тебя найдет. Если только ты не сумеешь от него спрятаться.$b$bХочешь выжить – принеси мне кровь безликих!','Добудьте 3 образца крови безликих по совету Матиаса Нетлера.','И чего ты ждешь? Натрись ею!$B$BБыстрей! А то он тебя увидит!','Ну что, где кровь?','Вернитесь к Матиасу Нетлеру в Наз\'анак: Забытые глубины, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пора прятаться!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не стоило тебе трогать эту штуку! Теперь он непременно явится искать тебя.$b$bИ он тебя найдет. Если только ты не сумеешь от него спрятаться.$b$bХочешь выжить – принеси мне кровь безликих!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 3 образца крови безликих по совету Матиаса Нетлера.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','И чего ты ждешь? Натрись ею!$B$BБыстрей! А то он тебя увидит!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, где кровь?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Матиасу Нетлеру в Наз\'анак: Забытые глубины, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (13392,'Возвращение на поверхность','Теперь уходи. У меня за спиной есть портал – выходи через него на поверхность.$b$bМы еще встретимся. Он ведь будет тебя искать.$b$bИ найдет, рано или поздно.','Вернитесь к Тассариану на борт "Усмирителя небес".') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение на поверхность',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь уходи. У меня за спиной есть портал – выходи через него на поверхность.$b$bМы еще встретимся. Он ведь будет тебя искать.$b$bИ найдет, рано или поздно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь к Тассариану на борт "Усмирителя небес".',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13393,'Ремонт в полевых условиях','Хорошо. Но победу праздновать пока рановато. Нужно закрепить и развить успех, которого мы добились с помощью взрывов.$b$bМы заметили на поле боя вполне еще рабочую ордынскую катапульту класса "разрушитель". Но ее разбирают на части упыри.$b$bЕсли бы тебе удалось восстановить катапульту, мы могли бы нанести войскам Плети в долине куда более серьезный урон.$b$bДа, конечно, я понимаю, мертвяки превосходят нас по численности, но я в тебя верю!','Отберите у упырей-мародеров 5 деталей разрушителя и отнесите их к сломанной катапульте в долине Потерянной Надежды по просьбе Тассариана на борту "Усмирителя небес".','Конечно, этот разрушитель знавал и лучшие дни, но основной механизм вроде бы не поврежден. Во всяком случае, он поддается ремонту. Добытых тобой деталей должно быть достаточно, чтобы он снова заработал... хотя бы ненадолго.','Разрушитель сильно пострадал.','Вернитесь к сломанному разрушителю в Долину Потерянной Надежды, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ремонт в полевых условиях',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хорошо. Но победу праздновать пока рановато. Нужно закрепить и развить успех, которого мы добились с помощью взрывов.$b$bМы заметили на поле боя вполне еще рабочую ордынскую катапульту класса "разрушитель". Но ее разбирают на части упыри.$b$bЕсли бы тебе удалось восстановить катапульту, мы могли бы нанести войскам Плети в долине куда более серьезный урон.$b$bДа, конечно, я понимаю, мертвяки превосходят нас по численности, но я в тебя верю!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отберите у упырей-мародеров 5 деталей разрушителя и отнесите их к сломанной катапульте в долине Потерянной Надежды по просьбе Тассариана на борту "Усмирителя небес".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Конечно, этот разрушитель знавал и лучшие дни, но основной механизм вроде бы не поврежден. Во всяком случае, он поддается ремонту. Добытых тобой деталей должно быть достаточно, чтобы он снова заработал... хотя бы ненадолго.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Разрушитель сильно пострадал.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к сломанному разрушителю в Долину Потерянной Надежды, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13394,'Все к худшему','Зачем тебе эта машина? С Плетью воевать? Машинами Плеть не одолеешь.$b$bТы можешь уничтожить сотни... да что там, даже тысячи воинов Плети! Но саму Плеть тебе не победить.$b$bКогда наиграешься вдоволь, ступай на север. Я встречусь с тобой возле заброшенного военного лагеря. И там я покажу тебе кое-что, чтобы ты $gпонял:поняла;, с чем имеешь дело.','Используйте отремонтированный разрушитель, чтобы уничтожить 150 изгнивших вурдалаков, 20 ледотленных волхвов и 2 костяных великана в долине Потерянной Надежды. Выполнив эту задачу, поговорите с Матиасом Нетлером в лагере сопротивления первого легиона.','Видишь? Ты можешь убивать их сколько угодно, но на место каждого убитого встанет из земли другой, новый.$B$BТы не понимаешь, с чем сражаешься, $N. Разреши, я тебе покажу.','Ты $Gзакончил:закончила; играть боевыми машинами?','Вернитесь к Матиасу Нетлеру в Долину Потерянной Надежды, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Все к худшему',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Зачем тебе эта машина? С Плетью воевать? Машинами Плеть не одолеешь.$b$bТы можешь уничтожить сотни... да что там, даже тысячи воинов Плети! Но саму Плеть тебе не победить.$b$bКогда наиграешься вдоволь, ступай на север. Я встречусь с тобой возле заброшенного военного лагеря. И там я покажу тебе кое-что, чтобы ты $gпонял:поняла;, с чем имеешь дело.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте отремонтированный разрушитель, чтобы уничтожить 150 изгнивших вурдалаков, 20 ледотленных волхвов и 2 костяных великана в долине Потерянной Надежды. Выполнив эту задачу, поговорите с Матиасом Нетлером в лагере сопротивления первого легиона.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Видишь? Ты можешь убивать их сколько угодно, но на место каждого убитого встанет из земли другой, новый.$B$BТы не понимаешь, с чем сражаешься, $N. Разреши, я тебе покажу.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gзакончил:закончила; играть боевыми машинами?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Матиасу Нетлеру в Долину Потерянной Надежды, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13395,'Войско проклятых','Ты, наверное, гордишься своим могуществом: ну как же, ты громишь эту нежить, давишь кости мертвяков своей машиной...$b$bНо это все пустяки по сравнению с тем могуществом, которое потребовалось, чтобы их создать!$b$bЯ видел, как принц это делал. И могу показать, как это было... если хочешь, конечно.','Оживите 100 вурдалаков-прислужников по просьбе Матиаса Нетлера в лагере сопротивления первого легиона.','Подлинное могущество принца было не в том, чтобы создавать армии из трупов – это-то как раз было легко.$B$BА вот убивать своих собственных солдат, с которыми он прошел немало битв… подлинное могущество принца состояло в том, чтобы поступать так, как велят обстоятельства.','Ты $Gвидел:видела;, $N?','Вернитесь к Матиасу Нетлеру в Долину Потерянной Надежды, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Войско проклятых',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты, наверное, гордишься своим могуществом: ну как же, ты громишь эту нежить, давишь кости мертвяков своей машиной...$b$bНо это все пустяки по сравнению с тем могуществом, которое потребовалось, чтобы их создать!$b$bЯ видел, как принц это делал. И могу показать, как это было... если хочешь, конечно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Оживите 100 вурдалаков-прислужников по просьбе Матиаса Нетлера в лагере сопротивления первого легиона.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Подлинное могущество принца было не в том, чтобы создавать армии из трупов – это-то как раз было легко.$B$BА вот убивать своих собственных солдат, с которыми он прошел немало битв… подлинное могущество принца состояло в том, чтобы поступать так, как велят обстоятельства.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gвидел:видела;, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Матиасу Нетлеру в Долину Потерянной Надежды, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13396,'Тщета','Теперь понимаешь? Посылая своих бойцов на войну с полчищами принца, вы только пополняете их ряды.$b$bВпрочем, я и не рассчитывал, что ты поймешь... думаю, с тобой будет то же, что и с другими. Возвращайся лучше к тому, кто тебя прислал. Думаю, о тебе тревожатся...','Вернитесь к Тассариану на борт "Усмирителя небес".','Отличный бой, $N! Все воинство Плети было не в силах тебе противостоять...$B$BС тобой все в порядке? У тебя такой вид, будто ты $Gувидел:увидела; привидение. Хотя, вообще-то, в здешних краях это не такая уж редкость...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тщета',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь понимаешь? Посылая своих бойцов на войну с полчищами принца, вы только пополняете их ряды.$b$bВпрочем, я и не рассчитывал, что ты поймешь... думаю, с тобой будет то же, что и с другими. Возвращайся лучше к тому, кто тебя прислал. Думаю, о тебе тревожатся...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь к Тассариану на борт "Усмирителя небес".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличный бой, $N! Все воинство Плети было не в силах тебе противостоять...$B$BС тобой все в порядке? У тебя такой вид, будто ты $Gувидел:увидела; привидение. Хотя, вообще-то, в здешних краях это не такая уж редкость...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13397,'Каньон Гибели Синдрагосы','Ты настоящий герой, $n. Видишь ли, когда я даю одному из своих солдат поручение, шансы, что он действительно его выполнит, примерно пятьдесят на пятьдесят. А шансов на то, что он вернется живым, и того меньше.$b$bНо ты другое дело! На тебя всегда можно положиться. Ты работаешь, как гномские часы!$b$bЭто я к чему: вот тебе еще одно дело. Каньон Гибели Синдрагосы находится к востоку от долины. Сектанты развили там слишком бурную деятельность. Они создают ледяных змеев – и не только. Ступай и разберись с ними!$b$bНенавижу сектантов.','Неплохо сработано, $N. По сравнению с тобой все мы бездельники!','$N, ты $Gвернулся:вернулась;!','Вернитесь к Тассариану на "Усмиритель небес", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Каньон Гибели Синдрагосы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты настоящий герой, $n. Видишь ли, когда я даю одному из своих солдат поручение, шансы, что он действительно его выполнит, примерно пятьдесят на пятьдесят. А шансов на то, что он вернется живым, и того меньше.$b$bНо ты другое дело! На тебя всегда можно положиться. Ты работаешь, как гномские часы!$b$bЭто я к чему: вот тебе еще одно дело. Каньон Гибели Синдрагосы находится к востоку от долины. Сектанты развили там слишком бурную деятельность. Они создают ледяных змеев – и не только. Ступай и разберись с ними!$b$bНенавижу сектантов.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Неплохо сработано, $N. По сравнению с тобой все мы бездельники!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$N, ты $Gвернулся:вернулась;!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тассариану на "Усмиритель небес", что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13398,'Место гибели драконов','Тут погиб целый выводок синих драконов. И вот теперь его слуги воскрешают их, одного за другим.$b$bСамого могучего воскресил он сам. Принеси мне пыли костей молодых драконов, и я покажу тебе, как он это сделал.','Добудьте в Каньоне Гибели Синдрагосы 6 горстей пыли из костей дракончиков по приказу Матиаса Нетлера.','Даже могучие змеи были вынуждены подчиниться его зову. Неужели $Gпростой:простая; $Gсмертный:смертная; вроде тебя может надеяться устоять?','Где пыль, $N?','Вернитесь к Матиасу Нетлеру в Каньон Гибели Синдрагосы, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Место гибели драконов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тут погиб целый выводок синих драконов. И вот теперь его слуги воскрешают их, одного за другим.$b$bСамого могучего воскресил он сам. Принеси мне пыли костей молодых драконов, и я покажу тебе, как он это сделал.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте в Каньоне Гибели Синдрагосы 6 горстей пыли из костей дракончиков по приказу Матиаса Нетлера.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Даже могучие змеи были вынуждены подчиниться его зову. Неужели $Gпростой:простая; $Gсмертный:смертная; вроде тебя может надеяться устоять?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Где пыль, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Матиасу Нетлеру в Каньон Гибели Синдрагосы, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13399,'Время ответов','Я вижу, у тебя много вопросов, $n. Ты – $gединственный:единственная;, кто может видеть меня, ибо $gкоснулся:коснулась; некоего предмета, принадлежавшего ему... Ты помнишь?$B$BТы не знаешь, что это? Нет-нет, я не могу просто так рассказать тебе... Он разгневается сверх всякой меры, а ведь ныне он не принц, но король!$B$BВстретимся во Дворе Костей, к северу от цитадели Ледяной Короны: там ты $gсам:сама; все увидишь.','Поговорите с Матиасом Нетлером во Дворе Костей.','Ах, вот и ты! Я уже начал сомневаться, придешь ты или нет...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Время ответов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я вижу, у тебя много вопросов, $n. Ты – $gединственный:единственная;, кто может видеть меня, ибо $gкоснулся:коснулась; некоего предмета, принадлежавшего ему... Ты помнишь?$B$BТы не знаешь, что это? Нет-нет, я не могу просто так рассказать тебе... Он разгневается сверх всякой меры, а ведь ныне он не принц, но король!$B$BВстретимся во Дворе Костей, к северу от цитадели Ледяной Короны: там ты $gсам:сама; все увидишь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Матиасом Нетлером во Дворе Костей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ах, вот и ты! Я уже начал сомневаться, придешь ты или нет...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13400,'Охотник и принц','До того как стать королем, принц сражался во многих битвах... Но лишь в одной ему грозила смерть. $B$BБитва свершилась здесь, на этом месте. Позволь мне показать, что случилось, и ты все поймешь.$B$BНайди залитый кровью камень и осмотри его. Тогда тебе откроется прошлое.','Матиас Нетлер со Двора Костей хочет, чтобы вы нашли Окровавленный камень и увидели, что случилось с принцем.','После этого боя принц осознал: его сдерживает то, что он все еще человек... Он по-прежнему чувствует, его можно ранить, и у него живое сердце.$B$BСтав королем, он в первую очередь решил избавиться от сердца и бросил его в глубокую яму на том самом месте, где мы впервые встретились с тобой. Ты, $N, $Gстал:стала; $Gпервым:первой;, кто коснулся его сердца за все это время.','Ты $Gвидел:видела;, $N?','Вернитесь к Матиасу Нетлеру во Двор Костей, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охотник и принц',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','До того как стать королем, принц сражался во многих битвах... Но лишь в одной ему грозила смерть. $B$BБитва свершилась здесь, на этом месте. Позволь мне показать, что случилось, и ты все поймешь.$B$BНайди залитый кровью камень и осмотри его. Тогда тебе откроется прошлое.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Матиас Нетлер со Двора Костей хочет, чтобы вы нашли Окровавленный камень и увидели, что случилось с принцем.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','После этого боя принц осознал: его сдерживает то, что он все еще человек... Он по-прежнему чувствует, его можно ранить, и у него живое сердце.$B$BСтав королем, он в первую очередь решил избавиться от сердца и бросил его в глубокую яму на том самом месте, где мы впервые встретились с тобой. Ты, $N, $Gстал:стала; $Gпервым:первой;, кто коснулся его сердца за все это время.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gвидел:видела;, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Матиасу Нетлеру во Двор Костей, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13401,'Знание – тяжкая ноша','Теперь ты знаешь, что тебе предстоит, $n. Противник, которому неведомы ни боль, ни муки совести, ни человеческие чувства... Противник, который готов на все, чтобы добиться своего. $B$BЕдинственная слабость нынешнего короля в том, что его сердце все еще существует; и теперь король знает, что ты $gнашел:нашла; его. $B$BЕсли хочешь вернуться и найти сердце, лучше возьми кого-нибудь в помощь – его хорошо охраняют...','Вернитесь к Тассариану на борт "Усмирителя небес".','Погоди, погоди, $N. Почему бы тебе не начать снова – и с самого начала?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Знание – тяжкая ноша',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь ты знаешь, что тебе предстоит, $n. Противник, которому неведомы ни боль, ни муки совести, ни человеческие чувства... Противник, который готов на все, чтобы добиться своего. $B$BЕдинственная слабость нынешнего короля в том, что его сердце все еще существует; и теперь король знает, что ты $gнашел:нашла; его. $B$BЕсли хочешь вернуться и найти сердце, лучше возьми кого-нибудь в помощь – его хорошо охраняют...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь к Тассариану на борт "Усмирителя небес".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Погоди, погоди, $N. Почему бы тебе не начать снова – и с самого начала?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13402,'Помощь Тириона','Я не в первый раз слышу рассказ об Артасе и его сердце... Правда, мне всегда казалось, что это выдуманная история. $B$BЧто ж, нам следует действовать по обстоятельствам. К сожалению, делать это придется в тайне. $B$BШпионы Артаса повсюду, и если он узнает о наших планах, мы все погибнем. $B$BНужно сообщить обо всем Серебряному Авангарду. Сам Тирион лично отбирал паладинов для этого ордена. Если и остались еще те, кто свободен от губительного влияния служителей культа, то это они.','Поговорите с верховным лордом Тирионом Фордрингом на Вершине Рыцарей.','Мне тяжело слышать эти слова, $N. Если бы их произнес кто-то другой, я бы, наверное, счел его безумным...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Помощь Тириона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я не в первый раз слышу рассказ об Артасе и его сердце... Правда, мне всегда казалось, что это выдуманная история. $B$BЧто ж, нам следует действовать по обстоятельствам. К сожалению, делать это придется в тайне. $B$BШпионы Артаса повсюду, и если он узнает о наших планах, мы все погибнем. $B$BНужно сообщить обо всем Серебряному Авангарду. Сам Тирион лично отбирал паладинов для этого ордена. Если и остались еще те, кто свободен от губительного влияния служителей культа, то это они.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с верховным лордом Тирионом Фордрингом на Вершине Рыцарей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мне тяжело слышать эти слова, $N. Если бы их произнес кто-то другой, я бы, наверное, счел его безумным...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13403,'Уловка Тириона','Этим утром разведчики сообщили мне, что из цитадели Ледяной Короны к Собору Тьмы движется процессия последователей Культа Проклятых, и что они несут некий артефакт. $B$BА теперь мне стало известно, что этим сокровищем может быть само сердце Артаса... Сердце, хранящее последние крупицы человечности, еще оставшиеся в нем! $B$BЭто знак свыше. Пока подобный предмет существует, остается надежда, что Артас Менетил вновь сможет стать человеком!$B$BВстретимся у входа в собор. И не забудь прихватить капюшон сектанта-послушника: никто не должен узнать нас.','Тирион Фордринг с Вершины Рыцарей хочет, чтобы вы достали и надели капюшон сектанта-послушника, а затем встретились с ним у входа в Собор Тьмы, к северо-западу от цитадели Ледяной Короны.','То, что произошло с нами, нельзя считать поражением, $N... О нет, напротив!$B$BТы $Gдал:дала; мне возможность заглянуть в глубины этого сердца и узнать то, что узнать было необходимо. Артаса Менетила больше нет: есть только Король-лич.','Да пребудет с тобой свет, $N.','Вернитесь к верховному лорду Тириону Фордрингу на Вершину Рыцарей, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уловка Тириона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этим утром разведчики сообщили мне, что из цитадели Ледяной Короны к Собору Тьмы движется процессия последователей Культа Проклятых, и что они несут некий артефакт. $B$BА теперь мне стало известно, что этим сокровищем может быть само сердце Артаса... Сердце, хранящее последние крупицы человечности, еще оставшиеся в нем! $B$BЭто знак свыше. Пока подобный предмет существует, остается надежда, что Артас Менетил вновь сможет стать человеком!$B$BВстретимся у входа в собор. И не забудь прихватить капюшон сектанта-послушника: никто не должен узнать нас.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Тирион Фордринг с Вершины Рыцарей хочет, чтобы вы достали и надели капюшон сектанта-послушника, а затем встретились с ним у входа в Собор Тьмы, к северо-западу от цитадели Ледяной Короны.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','То, что произошло с нами, нельзя считать поражением, $N... О нет, напротив!$B$BТы $Gдал:дала; мне возможность заглянуть в глубины этого сердца и узнать то, что узнать было необходимо. Артаса Менетила больше нет: есть только Король-лич.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да пребудет с тобой свет, $N.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному лорду Тириону Фордрингу на Вершину Рыцарей, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13404,'Войска статического разряда: Зона бомбардировки','Это будет задание ближнего действия. Цель – Зона бомбардировки. Для разминки. $GГотов:Ты готова;?','Убейте 50 пехотинцев из зоны бомбардировки, 10 капитанов из зоны бомбардировки и 20 горгулий-душительниц по заданию Кибли Киллогерца.','С возвращением, $N. Короткая миссия, но бодрящая, да? А пока отдохни. Но возвращайся, когда у тебя будут новые заказы.','Держись, $N. Сама по себе воздушная битва не выиграет!','Вернитесь к Кибли Киллогерцу в Алдур\'тар: Врата Горя, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Войска статического разряда: Зона бомбардировки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это будет задание ближнего действия. Цель – Зона бомбардировки. Для разминки. $GГотов:Ты готова;?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 50 пехотинцев из зоны бомбардировки, 10 капитанов из зоны бомбардировки и 20 горгулий-душительниц по заданию Кибли Киллогерца.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','С возвращением, $N. Короткая миссия, но бодрящая, да? А пока отдохни. Но возвращайся, когда у тебя будут новые заказы.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Держись, $N. Сама по себе воздушная битва не выиграет!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кибли Киллогерцу в Алдур\'тар: Врата Горя, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (13405,'Призыв к оружию: Берег Древних','Здесь, в Нордсколе, мы сражаемся не только с армиями Короля-лича, но и с силами Орды.$B$BНедавно на Береге Древних была найдена могущественная реликвия титанов. Мы, дворфы, уже многие годы оберегаем подобные артефакты, и потому считаем себя законными хранителями этой святыни.$B$BНо Орда разработала план по извлечению реликвии из руин титанов. Несомненно, они намереваются использовать ее в качестве оружия против нас, и потому наш долг – остановить их, пока еще не поздно.','Выиграйте битву на поле боя Берега Древних и вернитесь к бригадному генералу Альянса в любую из столиц Альянса, на Озеро Ледяных Оков, в Даларан или в Шаттрат.','Победа на Береге Древних','Вернитесь к бригадному генералу Альянса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Призыв к оружию: Берег Древних',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Здесь, в Нордсколе, мы сражаемся не только с армиями Короля-лича, но и с силами Орды.$B$BНедавно на Береге Древних была найдена могущественная реликвия титанов. Мы, дворфы, уже многие годы оберегаем подобные артефакты, и потому считаем себя законными хранителями этой святыни.$B$BНо Орда разработала план по извлечению реликвии из руин титанов. Несомненно, они намереваются использовать ее в качестве оружия против нас, и потому наш долг – остановить их, пока еще не поздно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выиграйте битву на поле боя Берега Древних и вернитесь к бригадному генералу Альянса в любую из столиц Альянса, на Озеро Ледяных Оков, в Даларан или в Шаттрат.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Победа на Береге Древних',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к бригадному генералу Альянса.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13406,'Новое излучение. Зона бомбардировки','Ну что, ты $gготов:готова; размяться и слегка побомбить врагов? Ну, тогда хорошо. У тебя есть задание, а у нас – бомбы.','Уничтожьте 50 пехотинцев из зоны бомбардировки, 10 капитанов из зоны бомбардировки и 20 горгулий-душительниц по заданию инженера-экспериментатора Теззлы.','Да, у тебя получилось! Даже здесь было слышно, как их разлетающиеся запчасти бьются о скалы. Ты молодец. В ближайшее время получишь новое задание...','Вы не достигли своей целевой квоты, $N. Выходи и взрывай все!','Вернитесь к инженеру-экспериментатору Теззле в Алдур\'тар: Врата Горя, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новое излучение. Зона бомбардировки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну что, ты $gготов:готова; размяться и слегка побомбить врагов? Ну, тогда хорошо. У тебя есть задание, а у нас – бомбы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 50 пехотинцев из зоны бомбардировки, 10 капитанов из зоны бомбардировки и 20 горгулий-душительниц по заданию инженера-экспериментатора Теззлы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, у тебя получилось! Даже здесь было слышно, как их разлетающиеся запчасти бьются о скалы. Ты молодец. В ближайшее время получишь новое задание...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы не достигли своей целевой квоты, $N. Выходи и взрывай все!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к инженеру-экспериментатору Теззле в Алдур\'тар: Врата Горя, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (13407,'Призыв к оружию: Берег Древних','Война с Плетью в Нордсколе – это еще не повод давать послабление Альянсу!$B$BЭти проклятые дворфы из Лиги исследователей откопали какую-то могущественную реликвию титанов. Мы не можем допустить, чтобы она попала в руки Альянса!$B$BИди, $n, и уничтожь наших врагов. Пусть они поймут, что им нигде от нас не скрыться.','Выиграйте битву на поле боя Берега Древних и вернитесь к ордынскому вестнику войны в любую из столиц Орды, на Озеро Ледяных Оков, в Даларан или в Шаттрат.','Победа на Береге Древних','Вернитесь к ордынскому вестнику войны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Призыв к оружию: Берег Древних',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Война с Плетью в Нордсколе – это еще не повод давать послабление Альянсу!$B$BЭти проклятые дворфы из Лиги исследователей откопали какую-то могущественную реликвию титанов. Мы не можем допустить, чтобы она попала в руки Альянса!$B$BИди, $n, и уничтожь наших врагов. Пусть они поймут, что им нигде от нас не скрыться.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выиграйте битву на поле боя Берега Древних и вернитесь к ордынскому вестнику войны в любую из столиц Орды, на Озеро Ледяных Оков, в Даларан или в Шаттрат.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Победа на Береге Древних',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ордынскому вестнику войны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13408,'Штурмовые укрепления','Ты славно $gпотрудился:потрудилась;, $n. Благодаря твоим ратным подвигам мы еще долго продержимся на Полуострове Адского Пламени!','$n, возвращайся ко мне, когда захватишь все три форта!','Вернитесь к прапорщику Трейси Праудвелл в Оплот Чести, что на Полуострове Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Штурмовые укрепления',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты славно $gпотрудился:потрудилась;, $n. Благодаря твоим ратным подвигам мы еще долго продержимся на Полуострове Адского Пламени!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$n, возвращайся ко мне, когда захватишь все три форта!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к прапорщику Трейси Праудвелл в Оплот Чести, что на Полуострове Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13409,'Штурмовые укрепления','Захватите Обзорную площадку, Ристалище и Изрезанный холм, и возвращайтесь в Траллмар к Черноглазке Зову Войны.','Возвращайся, когда все укрепления будут захвачены!','Вернитесь к Черноглазке Зов Войны в Траллмар, что на Полуострове Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Штурмовые укрепления',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Захватите Обзорную площадку, Ристалище и Изрезанный холм, и возвращайтесь в Траллмар к Черноглазке Зову Войны.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Возвращайся, когда все укрепления будут захвачены!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Черноглазке Зов Войны в Траллмар, что на Полуострове Адского Пламени.',`completedtext_loc8`);
