INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13411,'Штурмовые укрепления','Захватите Обзорную площадку, Ристалище и Изрезанный холм, и возвращайтесь в Траллмар к Черноглазке Зову Войны.','Вернитесь к Черноглазке Зов Войны в Траллмар, что на Полуострове Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Штурмовые укрепления',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Захватите Обзорную площадку, Ристалище и Изрезанный холм, и возвращайтесь в Траллмар к Черноглазке Зову Войны.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Черноглазке Зов Войны в Траллмар, что на Полуострове Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13412,'Корастраза','Привет тебе, |3-6($c). Я могу попросить тебя об услуге?$B$BУ красного дракона Релораза, командующего нашим аванпостом, есть сестра, Корастраза. Против его воли она поднялась в одно из верхних колец Нексуса, чтобы увидеть фантастически могущественных синих драконов.$B$BОн, конечно, не подает виду, но его беспокоит судьба сестры, и ему будет приятно узнать, что с ней ничего не случилось.$b$bПожалуйста, разыщи ее. И попроси ее на время забыть о гордости и послать весточку брату.','Поговорите с Корастразой в Хладарре по просьбе библиотекаря Серры.','Тебе не кажется, $R, что смертным негоже влезать в личные дела драконов?\n\nНу ладно, с моей стороны было бы несправедливо держать брата в неведении. Можешь передать своему невежливому другу, который так любит вмешиваться в чужие дела, что я буду держать брата в курсе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Корастраза',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Привет тебе, |3-6($c). Я могу попросить тебя об услуге?$B$BУ красного дракона Релораза, командующего нашим аванпостом, есть сестра, Корастраза. Против его воли она поднялась в одно из верхних колец Нексуса, чтобы увидеть фантастически могущественных синих драконов.$B$BОн, конечно, не подает виду, но его беспокоит судьба сестры, и ему будет приятно узнать, что с ней ничего не случилось.$b$bПожалуйста, разыщи ее. И попроси ее на время забыть о гордости и послать весточку брату.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Корастразой в Хладарре по просьбе библиотекаря Серры.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебе не кажется, $R, что смертным негоже влезать в личные дела драконов?\n\nНу ладно, с моей стороны было бы несправедливо держать брата в неведении. Можешь передать своему невежливому другу, который так любит вмешиваться в чужие дела, что я буду держать брата в курсе.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (13413,'Асы, ввысь!','Ты настолько $gотважен и дерзок, смертный:дерзка и отважна, смертная;, что не боишься приблизиться к логову Малигоса? Или ты просто не знаешь, чем это грозит? Ладно, скоро мы это узнаем...$b$bЯ давно тренирую красных драконов. Моя задача: изучить врага и обучить моих питомцев такой тактике боя, которая будет наиболее эффективной, когда придет время сразиться с повелителем синих драконов.$b$bЯ хочу посмотреть тебя в деле – понять, на что ты $gспособен:способна;. И поэтому я разрешаю тебе взять одного из моих питомцев и вылететь на боевое задание.$b$bТебе стоит лишь попросить – и мои драконы в твоем распоряжении.','Возьмите дракона Корастразы из верхнего кольца Нексуса в Хладарре и убейте 5 чешуеклятов-гвардейцев.','Мой дракон говорит мне, что если ты потренируешься, из тебя выйдет хороший боец.\n\nНу что же. Ради победы над Малигосом я разрешу тебе тренироваться с моими питомцами, но только в свободное время.\n\nПодготовься как следует, $R, он – свирепый и беспощадный противник.','Вернитесь к Корастразе в Нексус, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Асы, ввысь!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты настолько $gотважен и дерзок, смертный:дерзка и отважна, смертная;, что не боишься приблизиться к логову Малигоса? Или ты просто не знаешь, чем это грозит? Ладно, скоро мы это узнаем...$b$bЯ давно тренирую красных драконов. Моя задача: изучить врага и обучить моих питомцев такой тактике боя, которая будет наиболее эффективной, когда придет время сразиться с повелителем синих драконов.$b$bЯ хочу посмотреть тебя в деле – понять, на что ты $gспособен:способна;. И поэтому я разрешаю тебе взять одного из моих питомцев и вылететь на боевое задание.$b$bТебе стоит лишь попросить – и мои драконы в твоем распоряжении.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возьмите дракона Корастразы из верхнего кольца Нексуса в Хладарре и убейте 5 чешуеклятов-гвардейцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мой дракон говорит мне, что если ты потренируешься, из тебя выйдет хороший боец.\n\nНу что же. Ради победы над Малигосом я разрешу тебе тренироваться с моими питомцами, но только в свободное время.\n\nПодготовься как следует, $R, он – свирепый и беспощадный противник.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Корастразе в Нексус, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13414,'Асы, ввысь!','Мы снова встретились, |3-6($r). Надо признаться, я уже начинаю к тебе привыкать.$b$bВерно ли я понимаю, что ты $gпришел:пришла; тренироваться, чтобы отточить свои навыки воздушного боя?$b$bМои питомцы всегда готовы сеять панику и разрушения в стане врага.$b$bТебе стоит лишь попросить – и они в твоем распоряжении.','Возьмите дракона Корастразы из верхнего кольца Нексуса в Хладарре и убейте 5 чешуеклятов-гвардейцев.','Да, $R?','Вернитесь к Корастразе в Нексус, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Асы, ввысь!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы снова встретились, |3-6($r). Надо признаться, я уже начинаю к тебе привыкать.$b$bВерно ли я понимаю, что ты $gпришел:пришла; тренироваться, чтобы отточить свои навыки воздушного боя?$b$bМои питомцы всегда готовы сеять панику и разрушения в стане врага.$b$bТебе стоит лишь попросить – и они в твоем распоряжении.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возьмите дракона Корастразы из верхнего кольца Нексуса в Хладарре и убейте 5 чешуеклятов-гвардейцев.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да, $R?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Корастразе в Нексус, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13415,'Пульт в библиотеке','Мы знаем, где оболочка Норганнона, $n. Возьми диск изобретателя и иди в библиотеку. Там должен быть пульт, который нужно активировать с помощью этого диска. Я так думаю, Мимир спрятал там не только оболочку. Вполне вероятно, что там есть запас схем, которого инженерам Стальгорна хватит на несколько лет бесперебойной работы!$B$BВ любом случае, воспользуйся диском, чтобы добраться до оболочки. Будем надеяться, что фантазия Мимира на этом иссякла, и новые препятствия не предвидятся.','Активируйте пульт в Библиотеке Изобретателя с помощью диска изобретателя.','<Вы вставляете диск в предназначенную для него панель. На пульте внезапно включаются лампочки и вы слышите механический голос.>$B$BПодлинность диска изобретателя удостоверена. С возвращением, хранитель Мимир.','На пульте есть специальная панель, которая, кажется, предназначена как раз для диска изобретателя.','Вернитесь к пульту управления Библиотеки Изобретателя в Подножии у Грозовой Гряды.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пульт в библиотеке',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы знаем, где оболочка Норганнона, $n. Возьми диск изобретателя и иди в библиотеку. Там должен быть пульт, который нужно активировать с помощью этого диска. Я так думаю, Мимир спрятал там не только оболочку. Вполне вероятно, что там есть запас схем, которого инженерам Стальгорна хватит на несколько лет бесперебойной работы!$B$BВ любом случае, воспользуйся диском, чтобы добраться до оболочки. Будем надеяться, что фантазия Мимира на этом иссякла, и новые препятствия не предвидятся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Активируйте пульт в Библиотеке Изобретателя с помощью диска изобретателя.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Вы вставляете диск в предназначенную для него панель. На пульте внезапно включаются лампочки и вы слышите механический голос.>$B$BПодлинность диска изобретателя удостоверена. С возвращением, хранитель Мимир.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','На пульте есть специальная панель, которая, кажется, предназначена как раз для диска изобретателя.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к пульту управления Библиотеки Изобретателя в Подножии у Грозовой Гряды.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13416,'Пульт в библиотеке','Мы знаем, где оболочка Норганнона, $n. Возьми диск изобретателя и иди в библиотеку. Там должен быть пульт, который нужно активировать с помощью этого диска. Я так думаю, Мимир спрятал там не только оболочку. Вполне вероятно, что там есть запас схем, которого инженерам Стальгорна хватит на несколько лет бесперебойной работы!$B$BВ любом случае, воспользуйся диском, чтобы активировать пульт. Будем надеяться, что фантазия Мимира на этом иссякла, и новые препятствия не предвидятся.','Активируйте пульт в Библиотеке Изобретателя с помощью диска изобретателя.','<Вы вставляете диск в предназначенную для него панель. На пульте внезапно включаются лампочки и механический голос произносит:>\n\nПодлинность диска изобретателя удостоверена. С возвращением, хранитель Мимир.','На пульте есть специальная панель, которая, кажется, предназначена как раз для диска изобретателя.','Вернитесь к пульту управления Библиотеки Изобретателя в Грозовую Гряду.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пульт в библиотеке',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы знаем, где оболочка Норганнона, $n. Возьми диск изобретателя и иди в библиотеку. Там должен быть пульт, который нужно активировать с помощью этого диска. Я так думаю, Мимир спрятал там не только оболочку. Вполне вероятно, что там есть запас схем, которого инженерам Стальгорна хватит на несколько лет бесперебойной работы!$B$BВ любом случае, воспользуйся диском, чтобы активировать пульт. Будем надеяться, что фантазия Мимира на этом иссякла, и новые препятствия не предвидятся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Активируйте пульт в Библиотеке Изобретателя с помощью диска изобретателя.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Вы вставляете диск в предназначенную для него панель. На пульте внезапно включаются лампочки и механический голос произносит:>\n\nПодлинность диска изобретателя удостоверена. С возвращением, хранитель Мимир.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','На пульте есть специальная панель, которая, кажется, предназначена как раз для диска изобретателя.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к пульту управления Библиотеки Изобретателя в Грозовую Гряду.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`) VALUES (13417,'Братья Бронзобороды','Вот оно! Наконец-то у нас есть краеугольный камень... Какая красота! Я немало попутешествовал по миру, но эта вещь снова приводит меня в восторг. Хотя сейчас явно не время застывать в эстетическом ступоре, восхищаться и ахать я буду потом, а сейчас надо скорее выбираться отсюда!$B$BЗабирайся в мой ветролет и прикрывай нас от железных дворфов!','Прикрывайте Бранна Бронзоборода и его ветролет, пока не доберетесь до Ледяной крепости.','Король Грозовое Сердце искренне благодарит за воссоединение с братьями. Похоже, сейчас он собирается свести счеты - возможно, вы снова встретитесь с ним на пороге Артаса.','Сопровождение Бранна Бронзоборода в Ледяную Крепость.','Вернитесь к Велогу Ледяному Воплю в Ледяную крепость, что в Грозовой Гряде.','Сопровождение Бранна Бронзоборода в Ледяную Крепость.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Братья Бронзобороды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот оно! Наконец-то у нас есть краеугольный камень... Какая красота! Я немало попутешествовал по миру, но эта вещь снова приводит меня в восторг. Хотя сейчас явно не время застывать в эстетическом ступоре, восхищаться и ахать я буду потом, а сейчас надо скорее выбираться отсюда!$B$BЗабирайся в мой ветролет и прикрывай нас от железных дворфов!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Прикрывайте Бранна Бронзоборода и его ветролет, пока не доберетесь до Ледяной крепости.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Король Грозовое Сердце искренне благодарит за воссоединение с братьями. Похоже, сейчас он собирается свести счеты - возможно, вы снова встретитесь с ним на пороге Артаса.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Сопровождение Бранна Бронзоборода в Ледяную Крепость.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Велогу Ледяному Воплю в Ледяную крепость, что в Грозовой Гряде.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Сопровождение Бранна Бронзоборода в Ледяную Крепость.',`questgivertextwindow_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13418,'Подготовка к войне','Эй, ты!$B$BДа, я к тебе обращаюсь. С виду ты, вроде, $gнеглупый парень:неглупая барышня;. А нам тут, в Ледяной Короне, нужны адекватные кадры. И чем больше, тем лучше!$B$BТы, наверное, $gслышал:слышала;, что нам не удалось захватить ледник с земли, но пусть тебя это не слишком тревожит. Сейчас мы готовим новую атаку. Мы ударим по ним с нашего нового боевого корабля, который построен с помощью самых продвинутых технологий во всем Азероте. Против нашего "Усмирителя небес" не выстоять никому: ни Орде, ни Артасу.$B$BДай мне знать, когда будешь $gготов:готова; отправиться в путь.','Поговорите с офицером ван Россемом, который переправит вас на борт "Усмирителя небес" в Ледяной Короне, а потом побеседуйте со старшим капитаном Джастином Бартлеттом.','Добро пожаловать на "Усмиритель небес".$B$BЗдесь мы готовимся к атаке на Артаса. Как говорится, хорошая подготовка – залог успеха. Нам предстоит еще многое сделать, но прежде чем приступать к основной части, мы должны позаботиться о том, чтобы Серебряный Авангард получил необходимое подкрепление – когда придет время, нам понадобится их помощь.$B$BИди на верхнюю палубу и поговори с Абсаланом Благочестивым.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подготовка к войне',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эй, ты!$B$BДа, я к тебе обращаюсь. С виду ты, вроде, $gнеглупый парень:неглупая барышня;. А нам тут, в Ледяной Короне, нужны адекватные кадры. И чем больше, тем лучше!$B$BТы, наверное, $gслышал:слышала;, что нам не удалось захватить ледник с земли, но пусть тебя это не слишком тревожит. Сейчас мы готовим новую атаку. Мы ударим по ним с нашего нового боевого корабля, который построен с помощью самых продвинутых технологий во всем Азероте. Против нашего "Усмирителя небес" не выстоять никому: ни Орде, ни Артасу.$B$BДай мне знать, когда будешь $gготов:готова; отправиться в путь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с офицером ван Россемом, который переправит вас на борт "Усмирителя небес" в Ледяной Короне, а потом побеседуйте со старшим капитаном Джастином Бартлеттом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Добро пожаловать на "Усмиритель небес".$B$BЗдесь мы готовимся к атаке на Артаса. Как говорится, хорошая подготовка – залог успеха. Нам предстоит еще многое сделать, но прежде чем приступать к основной части, мы должны позаботиться о том, чтобы Серебряный Авангард получил необходимое подкрепление – когда придет время, нам понадобится их помощь.$B$BИди на верхнюю палубу и поговори с Абсаланом Благочестивым.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (13419,'Подготовка к войне','Эй, ты!$B$BДа, я к тебе обращаюсь. С виду ты, вроде, $gнеглупый парень:неглупая барышня;. А нам тут, в Ледяной Короне, нужны адекватные кадры. И чем больше, тем лучше!$B$BЭти мерзавцы из Альянса вошли в Ледяную Корону раньше нас, рванули без подготовки и получили именно то, что вполне заслужили из-за своего нетерпения. А мы не спешили. Мы подготовились как следует и уже очень скоро пойдем в атаку. Мы ударим по ним с нашего нового боевого корабля, который построен с помощью самых продвинутых технологий во всем Азероте. Против нашего "Молота Оргрима" не выстоять никому: ни Альянсу, ни Артасу.$B$BДай мне знать, когда будешь $gготов:готова; отправиться в путь и оказать нам посильную помощь.','Поговорите с покорителем небес Клумом, который переправит вас на борт "Молота Оргрима" в Ледяной Короне, а потом побеседуйте с покорителем небес Кормом Черным Шрамом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подготовка к войне',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эй, ты!$B$BДа, я к тебе обращаюсь. С виду ты, вроде, $gнеглупый парень:неглупая барышня;. А нам тут, в Ледяной Короне, нужны адекватные кадры. И чем больше, тем лучше!$B$BЭти мерзавцы из Альянса вошли в Ледяную Корону раньше нас, рванули без подготовки и получили именно то, что вполне заслужили из-за своего нетерпения. А мы не спешили. Мы подготовились как следует и уже очень скоро пойдем в атаку. Мы ударим по ним с нашего нового боевого корабля, который построен с помощью самых продвинутых технологий во всем Азероте. Против нашего "Молота Оргрима" не выстоять никому: ни Альянсу, ни Артасу.$B$BДай мне знать, когда будешь $gготов:готова; отправиться в путь и оказать нам посильную помощь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с покорителем небес Клумом, который переправит вас на борт "Молота Оргрима" в Ледяной Короне, а потом побеседуйте с покорителем небес Кормом Черным Шрамом.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13420,'Вечный лед','Этот кусок льда подвергся очень сильному давлению и воздействию природной магии – где-то на большой глубине. В результате получился лед, который никогда не тает.$B$BМало что понимая в таких вещах, вы решаете отнести образец этого странного льда в Дун Ниффелем. Наверняка там есть кто-то, кто знает, что это такое.','Возвращайтесь в Дун Ниффелем и расспросите Кальдера насчет осколка Вечного льда.','<Кальдер поднимает Вечную мерзлоту к свету. В его глазах искрятся отражения сверкающего льда.>\n\nАаа, Вечная мерзлота... Символ духа нашего народа...\n\nКогда-то здесь было много Вечной мерзлоты. Но за прошедшие века йормунгары поглотили почти все. Теперь это большая редкость, которая ценится выше золота среди моего народа.\n\nУ меня к тебе просьба: пока будешь в здешних краях, ты посматривай по сторонам – если найдешь еще Вечную мерзлоту, принеси ее мне. А я найду, чем тебя отблагодарить.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вечный лед',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этот кусок льда подвергся очень сильному давлению и воздействию природной магии – где-то на большой глубине. В результате получился лед, который никогда не тает.$B$BМало что понимая в таких вещах, вы решаете отнести образец этого странного льда в Дун Ниффелем. Наверняка там есть кто-то, кто знает, что это такое.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возвращайтесь в Дун Ниффелем и расспросите Кальдера насчет осколка Вечного льда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Кальдер поднимает Вечную мерзлоту к свету. В его глазах искрятся отражения сверкающего льда.>\n\nАаа, Вечная мерзлота... Символ духа нашего народа...\n\nКогда-то здесь было много Вечной мерзлоты. Но за прошедшие века йормунгары поглотили почти все. Теперь это большая редкость, которая ценится выше золота среди моего народа.\n\nУ меня к тебе просьба: пока будешь в здешних краях, ты посматривай по сторонам – если найдешь еще Вечную мерзлоту, принеси ее мне. А я найду, чем тебя отблагодарить.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (13421,'Больше Вечного льда!','Вернитесь к Калдеру в Дун Ниффелем, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Больше Вечного льда!',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Калдеру в Дун Ниффелем, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13422,'Поучить уму-разуму','Ты преуспела там, где другие потерпели поражение. Но почивать на лаврах еще рано.$b$bПокажи остальным, что такое настоящие сила и преданность!$b$bНепокорные врайкулы из Заброшенного рудника снова нуждаются во вразумлении. Покажи им, сестра, каково это – не повиноваться нам!','Накажите 6 обессиленных врайкулов из Заброшенного рудника с помощью вразумляющего жезла по заданию Гретты Судьи из деревни Бруннхильдар.','Ты снова подаешь всем пример. Мы рассчитываем на тебя, сестра!','Привет, $Gбрат:сестра;.','Вернитесь к Гретте Судье в деревню Бруннхильдар, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поучить уму-разуму',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты преуспела там, где другие потерпели поражение. Но почивать на лаврах еще рано.$b$bПокажи остальным, что такое настоящие сила и преданность!$b$bНепокорные врайкулы из Заброшенного рудника снова нуждаются во вразумлении. Покажи им, сестра, каково это – не повиноваться нам!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Накажите 6 обессиленных врайкулов из Заброшенного рудника с помощью вразумляющего жезла по заданию Гретты Судьи из деревни Бруннхильдар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты снова подаешь всем пример. Мы рассчитываем на тебя, сестра!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Привет, $Gбрат:сестра;.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гретте Судье в деревню Бруннхильдар, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13423,'Подтверждение победы','Все восхищены тобой, сестра. Но не теряй бдительности: любая из сестер, жаждущая славы, может попытаться отобрать у тебя титул королевы хильд!$b$bПокажи этим бездарностям, на что ты способна!','Одержите победу над 6 дуэлянтами-победителями по заданию Гретты Судьи из деревни Бруннхильдар.','Ты снова показала себя самой достойной. Твое присутствие делает нам честь!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подтверждение победы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Все восхищены тобой, сестра. Но не теряй бдительности: любая из сестер, жаждущая славы, может попытаться отобрать у тебя титул королевы хильд!$b$bПокажи этим бездарностям, на что ты способна!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Одержите победу над 6 дуэлянтами-победителями по заданию Гретты Судьи из деревни Бруннхильдар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты снова показала себя самой достойной. Твое присутствие делает нам честь!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13424,'Обратно в Яму Клыка','Чтобы оставаться в форме, нужно ежедневно соревноваться с другими хильдами!$b$bОтправляйся обратно в Яму Клыка и покажи всем, на что ты способна. Для них будет честью проиграть в поединке с тобой.','Отправляйтесь в Яму Клыка, воспользуйтесь поводьями матриарха ледочревов и победите 6 боевых медведей Круга хильд по заданию Гретты Судьи из деревни Бруннхильдар.','Ты снова доказала свою доблесть. Сестры не утратили уважения к тебе!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обратно в Яму Клыка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чтобы оставаться в форме, нужно ежедневно соревноваться с другими хильдами!$b$bОтправляйся обратно в Яму Клыка и покажи всем, на что ты способна. Для них будет честью проиграть в поединке с тобой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Яму Клыка, воспользуйтесь поводьями матриарха ледочревов и победите 6 боевых медведей Круга хильд по заданию Гретты Судьи из деревни Бруннхильдар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты снова доказала свою доблесть. Сестры не утратили уважения к тебе!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13425,'Смерть гнусным тварям!','Доказать свою доблесть среди равных недостаточно, дорогая сестра. Нам ведь нужно еще и сражаться с врагами!$b$bПредательницы из Валькириона по-прежнему издеваются над нашими благородными традициями, выращивая зараженных протодраконов.$b$bВозьми масло льда, которое они используют, и заморозь эти гнусные яйца.','По заданию Гретты Судьи из деревни Бруннхильдар отправляйтесь в Валькирион и добудьте у валькирионских претенденток флаконы масла льда. Используйте флаконы масла льда, чтобы уничтожить 30 зачумленных яиц протодраконов.','Героиня в одном – героиня во всем! Мы благодарим тебя, сестра.','Ты $Gуничтожил:уничтожила; зараженные яйца?','Вернитесь к Гретте Судье в деревню Бруннхильдар, что в Грозовой Гряде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Смерть гнусным тварям!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Доказать свою доблесть среди равных недостаточно, дорогая сестра. Нам ведь нужно еще и сражаться с врагами!$b$bПредательницы из Валькириона по-прежнему издеваются над нашими благородными традициями, выращивая зараженных протодраконов.$b$bВозьми масло льда, которое они используют, и заморозь эти гнусные яйца.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По заданию Гретты Судьи из деревни Бруннхильдар отправляйтесь в Валькирион и добудьте у валькирионских претенденток флаконы масла льда. Используйте флаконы масла льда, чтобы уничтожить 30 зачумленных яиц протодраконов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Героиня в одном – героиня во всем! Мы благодарим тебя, сестра.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gуничтожил:уничтожила; зараженные яйца?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гретте Судье в деревню Бруннхильдар, что в Грозовой Гряде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13426,'Ксанатавр, Свидетель','Поговорите с Ксанатавром в лагере Тунка\'ло.','Так Боктар получил мое послание? Это отличная новость. Я сомневался, что гонец, который должен был ее доставить, до кого-нибудь доберется.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ксанатавр, Свидетель',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Ксанатавром в лагере Тунка\'ло.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так Боктар получил мое послание? Это отличная новость. Я сомневался, что гонец, который должен был ее доставить, до кого-нибудь доберется.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (13427,'Призыв к оружию: Альтеракская долина','Беда битвы на несколько фронтов, $gпарень:подруга;, в том, что приходится рассредотачивать силы, и в результате мы рискуем потерять все!$B$BНам каждый день требуется подкрепление. Сегодня войскам в Альтеракской долине требуются отважные бойцы.$B$BСтупай прямо сейчас, $n, и помоги стражам Грозовой Вершины. Мы не можем допустить, чтобы клан Северного Волка ушел без возмездия после всего того зла, что они причинили нашим собратьям!','Победите на поле боя Альтеракской долины и вернитесь к бригадному генералу Альянса в любую из столиц Альянса, на Озеро Ледяных Оков, в Даларан или в Шаттрат.','Победа в Альтеракской долине','Вернитесь к бригадному генералу Альянса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Призыв к оружию: Альтеракская долина',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Беда битвы на несколько фронтов, $gпарень:подруга;, в том, что приходится рассредотачивать силы, и в результате мы рискуем потерять все!$B$BНам каждый день требуется подкрепление. Сегодня войскам в Альтеракской долине требуются отважные бойцы.$B$BСтупай прямо сейчас, $n, и помоги стражам Грозовой Вершины. Мы не можем допустить, чтобы клан Северного Волка ушел без возмездия после всего того зла, что они причинили нашим собратьям!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите на поле боя Альтеракской долины и вернитесь к бригадному генералу Альянса в любую из столиц Альянса, на Озеро Ледяных Оков, в Даларан или в Шаттрат.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Победа в Альтеракской долине',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к бригадному генералу Альянса.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (13428,'Нет высшей чести, чем изгнать захватчиков с земель Орды! Мы ныне славим твою великую отвагу в помощи нашим войскам!') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Нет высшей чести, чем изгнать захватчиков с земель Орды! Мы ныне славим твою великую отвагу в помощи нашим войскам!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (13429,'Отвлекающий маневр','<Кси\'ри излучает пульсирующее сияние, отдавая приказания войскам Алдоров и Провидцев. Армия Кси\'ри готова отбросить силы Иллидана и тем самым отвлечь их, чтобы Акама мог проникнуть в храм. Наару ждет вашего сигнала, чтобы начать атаку.>','Убедитесь, что Акама и Майев вошли в Черный храм в долине Призрачной Луны после того, как войска Кси\'ри совершат отвлекающий маневр.','<Кси\'ри излучает волны энергии, и вы чувствуете, как в ваших руках возникает некий предмет. Это медальон, который вы отдали А\'далу от имени Акамы – его сила многократно увеличена магией наару. Ша\'тар доверили вам медальон Карабора, а вместе с ним и возможность войти в Черный храм.>','Помогите Акаме и Майев войти в Черный храм.','Вернитесь к Ксири на Руины Баа\'ри, что в Долине Призрачной Луны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отвлекающий маневр',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Кси\'ри излучает пульсирующее сияние, отдавая приказания войскам Алдоров и Провидцев. Армия Кси\'ри готова отбросить силы Иллидана и тем самым отвлечь их, чтобы Акама мог проникнуть в храм. Наару ждет вашего сигнала, чтобы начать атаку.>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убедитесь, что Акама и Майев вошли в Черный храм в долине Призрачной Луны после того, как войска Кси\'ри совершат отвлекающий маневр.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Кси\'ри излучает волны энергии, и вы чувствуете, как в ваших руках возникает некий предмет. Это медальон, который вы отдали А\'далу от имени Акамы – его сила многократно увеличена магией наару. Ша\'тар доверили вам медальон Карабора, а вместе с ним и возможность войти в Черный храм.>',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Помогите Акаме и Майев войти в Черный храм.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ксири на Руины Баа\'ри, что в Долине Призрачной Луны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13430,'Испытание наару: Магтеридон','По заданию А\'дала из Шаттрата убейте Магтеридона.','Вернитесь к А\'далу в Нижний Город, что в Шаттрате.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Испытание наару: Магтеридон',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По заданию А\'дала из Шаттрата убейте Магтеридона.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к А\'далу в Нижний Город, что в Шаттрате.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13431,'Дубина Кардеша','Для создания оружия мне необходимы печатки стихий. Принеси мне их!$B$BПечатку земли ты найдешь в логове Груула Драконобоя в Острогорье.$B$BПечатка огня – это сердце существа, именуемого Ночной Погибелью. Это легендарное чудовище по слухам обитает в священных залах пророка Медива.$B$BПоторопись!','Принесите печатки земли и огня Скартису Еретику в Узилище (героический уровень сложности) в Резервуар Кривого Клыка.','Наконец-то!$B$BЯ не забыл о нашем соглашении, $Gсмертный:смертная;. Теперь вы тоже сможете войти в логово Леди Вайши. Оставь меня! Мне нужно многое спланировать.','С исправленной дубиной я вырвусь из своих оков и вернусь в Змеиное святилище, чтобы отомстить Вайш и ее приспешникам!','Вернитесь к Скартису Еретику в Узилище.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дубина Кардеша',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Для создания оружия мне необходимы печатки стихий. Принеси мне их!$B$BПечатку земли ты найдешь в логове Груула Драконобоя в Острогорье.$B$BПечатка огня – это сердце существа, именуемого Ночной Погибелью. Это легендарное чудовище по слухам обитает в священных залах пророка Медива.$B$BПоторопись!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите печатки земли и огня Скартису Еретику в Узилище (героический уровень сложности) в Резервуар Кривого Клыка.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Наконец-то!$B$BЯ не забыл о нашем соглашении, $Gсмертный:смертная;. Теперь вы тоже сможете войти в логово Леди Вайши. Оставь меня! Мне нужно многое спланировать.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','С исправленной дубиной я вырвусь из своих оков и вернусь в Змеиное святилище, чтобы отомстить Вайш и ее приспешникам!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Скартису Еретику в Узилище.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13432,'Сосуды Вечности','Иллидан наполнил семь сосудов из Источника Вечности. Три из них он вылил в озеро на горе Хиджал и создал второй Источник. Долгое время считалось, что остальные четыре сосуда были утрачены.$B$BНо после того как открылся Темный портал, мы узнали, что Иллидан отдал по одному сосуду своим лейтенантам Кел\'тасу и Вайш. Найди эти сосуды и принеси нам. Без них мы не можем открыть временные проходы к событиям, так или иначе связанным с горой Хиджал, – ни к недавним, ни к древним. Мы должны позаботиться о том, чтобы ничто не смогло изменить исход битвы за Хиджал.','Даже в одной капле воды из Источника Вечности заключены невероятные силы.$B$BТеперь я могу прозревать время и видеть все, что когда-либо происходило на Хиджале... Создание второго Источника Вечности, пленение Иллидана, заклятие Мирового Древа и... О, да! Битва за Хиджал!$B$BМы должны поспешить, иначе эта линия времени будет разрушена.','Я знаю, что прошу невозможного, но все равно верю в тебя. Сейчас судьба мира – в твоих руках.','Вернитесь к Соридорми в Танарис.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сосуды Вечности',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Иллидан наполнил семь сосудов из Источника Вечности. Три из них он вылил в озеро на горе Хиджал и создал второй Источник. Долгое время считалось, что остальные четыре сосуда были утрачены.$B$BНо после того как открылся Темный портал, мы узнали, что Иллидан отдал по одному сосуду своим лейтенантам Кел\'тасу и Вайш. Найди эти сосуды и принеси нам. Без них мы не можем открыть временные проходы к событиям, так или иначе связанным с горой Хиджал, – ни к недавним, ни к древним. Мы должны позаботиться о том, чтобы ничто не смогло изменить исход битвы за Хиджал.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Даже в одной капле воды из Источника Вечности заключены невероятные силы.$B$BТеперь я могу прозревать время и видеть все, что когда-либо происходило на Хиджале... Создание второго Источника Вечности, пленение Иллидана, заклятие Мирового Древа и... О, да! Битва за Хиджал!$B$BМы должны поспешить, иначе эта линия времени будет разрушена.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я знаю, что прошу невозможного, но все равно верю в тебя. Сейчас судьба мира – в твоих руках.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Соридорми в Танарис.',`completedtext_loc8`);
