INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (13475,'Великая честь','Вернитесь к ордынскому вестнику войны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Великая честь',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ордынскому вестнику войны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13476,'Великая честь','Нет выше чести, чем биться с Альянсом во имя Орды! Лучшие же наши воины – те немногие, которым довелось сразиться на ВСЕХ полях битвы. Отдельные стычки не помогут нам одолеть врага. Лишь тщательно спланировав наступление, мы сломим проклятый Альянс.$b$bСтупай же и вступи в схватку с Альянсом на всех фронтах. За честь! За Орду!','Принесите почетные знаки каждого поля боя ордынскому вестнику войны в любую столицу Орды или в Шаттрат.','На твою долю выпали непростые испытание, но ты не лишился мужества и сила тебя не покинула. Знаки победы – пустое. Не по ним судят о твоей доблести. Выше голову, $N. Сегодня тебе подобает смотреть на других свысока, ведь ты настоящий герой!','Арати до сих пор пропитан кровью великих воинов, и по Альтераку до сих пор слышен звон стали. Не тратьте мое время зря, если не несете новости с фронта!','Вернитесь к ордынскому вестнику войны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Великая честь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нет выше чести, чем биться с Альянсом во имя Орды! Лучшие же наши воины – те немногие, которым довелось сразиться на ВСЕХ полях битвы. Отдельные стычки не помогут нам одолеть врага. Лишь тщательно спланировав наступление, мы сломим проклятый Альянс.$b$bСтупай же и вступи в схватку с Альянсом на всех фронтах. За честь! За Орду!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите почетные знаки каждого поля боя ордынскому вестнику войны в любую столицу Орды или в Шаттрат.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','На твою долю выпали непростые испытание, но ты не лишился мужества и сила тебя не покинула. Знаки победы – пустое. Не по ним судят о твоей доблести. Выше голову, $N. Сегодня тебе подобает смотреть на других свысока, ведь ты настоящий герой!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Арати до сих пор пропитан кровью великих воинов, и по Альтераку до сих пор слышен звон стали. Не тратьте мое время зря, если не несете новости с фронта!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ордынскому вестнику войны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (13477,'В едином порыве','Вернитесь к бригадному генералу Альянса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В едином порыве',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к бригадному генералу Альянса.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13478,'В едином порыве','В войне против Орды решающей может оказаться любая битва, $gсынок:дочка;.$B$BПобеда на одном фронте позволит захватить ресурсы, которые помогут победить и на другом. И с точностью до наоборот – любая проигранная битва может дать нашим врагам преимущество в другой.$b$bАльянсу не хватает бойцов, которые бы хорошенько поняли это... бойцов, закаленных в битвах! Отправляйся сражаться с Ордой, а когда побываешь на всех полях битвы, возвращайся ко мне.','Принесите почетные знаки каждого поля боя бригадному генералу Альянса в любую столицу Альянса или в Шаттрат.','Ты не $Gразочаровал:разочаровала; меня, $N! И ты $Gполучил:получила; большее, чем просто медали и отличия. Ты $Gполучил:получила; бесценный опыт и $Gзакалил:закалила; свой дух.$B$BХорошо сделано, |3-6($C). Ты настоящий герой Альянса!','Какие вести из дальних стран?','Вернитесь к бригадному генералу Альянса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В едином порыве',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В войне против Орды решающей может оказаться любая битва, $gсынок:дочка;.$B$BПобеда на одном фронте позволит захватить ресурсы, которые помогут победить и на другом. И с точностью до наоборот – любая проигранная битва может дать нашим врагам преимущество в другой.$b$bАльянсу не хватает бойцов, которые бы хорошенько поняли это... бойцов, закаленных в битвах! Отправляйся сражаться с Ордой, а когда побываешь на всех полях битвы, возвращайся ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите почетные знаки каждого поля боя бригадному генералу Альянса в любую столицу Альянса или в Шаттрат.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты не $Gразочаровал:разочаровала; меня, $N! И ты $Gполучил:получила; большее, чем просто медали и отличия. Ты $Gполучил:получила; бесценный опыт и $Gзакалил:закалила; свой дух.$B$BХорошо сделано, |3-6($C). Ты настоящий герой Альянса!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Какие вести из дальних стран?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к бригадному генералу Альянса.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13479,'Большая охота за яйцами','Ах, Сад чудес, праздник весны и жизни! Надеюсь, тебе понравилось собирать яйца, $Gдруг:дорогая;, потому что мне как раз $Gнужен проворный помощник:нужна проворная помощница;.$B$BЯ не знаю, какую магию использовали при создании этих яиц, а друиды играют со мной в молчанку. Будешь разбивать яйца – сохрани для меня осколки скорлупы. Содержимое яиц можешь оставить себе, мне же понадобятся только скорлупки.','Принесите весеннему сборщику 20 осколков раскрашенной яичной скорлупы.','Прекрасно, большое спасибо! В будущем мне могут понадобиться еще образцы, имей в виду.','Где же скорлупа?','Вернитесь к весеннему сборщику.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Большая охота за яйцами',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ах, Сад чудес, праздник весны и жизни! Надеюсь, тебе понравилось собирать яйца, $Gдруг:дорогая;, потому что мне как раз $Gнужен проворный помощник:нужна проворная помощница;.$B$BЯ не знаю, какую магию использовали при создании этих яиц, а друиды играют со мной в молчанку. Будешь разбивать яйца – сохрани для меня осколки скорлупы. Содержимое яиц можешь оставить себе, мне же понадобятся только скорлупки.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите весеннему сборщику 20 осколков раскрашенной яичной скорлупы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно, большое спасибо! В будущем мне могут понадобиться еще образцы, имей в виду.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Где же скорлупа?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к весеннему сборщику.',`completedtext_loc8`);
