INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (13481,'Валим отсюда!','Проводите отца Камароса в безопасное место и доложите об этом брату Кельтану на борту "Молота Оргрима".','Ты все сделал правильно. Мы боялись, что отец Камарос погиб. Твоя храбрость станет примером для всех, кто сражается с силами Плети.','Проводить отца Камароса в безопасное место','Поговорите с братом Келтаном на "Молоте Оргрима", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Валим отсюда!',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проводите отца Камароса в безопасное место и доложите об этом брату Кельтану на борту "Молота Оргрима".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты все сделал правильно. Мы боялись, что отец Камарос погиб. Твоя храбрость станет примером для всех, кто сражается с силами Плети.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Проводить отца Камароса в безопасное место',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с братом Келтаном на "Молоте Оргрима", что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (13482,'Валим отсюда!','Проводите отца Камароса в безопасное место, а затем сообщите об этом Абсалану Благочестивому на борту "Усмирителя небес".','Слава Свету! Мы уже думали, что отец Камарос умер, или того хуже. Твоя смелость и самоотверженность очень помогли Серебряному Авангарду. Прими нашу благодарность.','Проводить отца Камароса в безопасное место','Поговорите с Абсаланом Благочестивым на "Усмирителе небес", что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Валим отсюда!',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проводите отца Камароса в безопасное место, а затем сообщите об этом Абсалану Благочестивому на борту "Усмирителя небес".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Слава Свету! Мы уже думали, что отец Камарос умер, или того хуже. Твоя смелость и самоотверженность очень помогли Серебряному Авангарду. Прими нашу благодарность.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Проводить отца Камароса в безопасное место',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Абсаланом Благочестивым на "Усмирителе небес", что в Ледяной Короне.',`completedtext_loc8`);
