INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13484,'Весенние собиратели','Если тебе не сидится на месте, то поищи магов в поселениях рядом со столицами – в Златоземье, Караносе, Доланааре и на Лазурной заставе. Им нужна помощь в каких-то исследованиях, и они нанимают большое количество охотников за яйцами. Больше сказать не могу, подробности узнаешь у магов.','Поговорите с весенним собирателем в Златоземье, Караносе, Доланааре или на Лазурной заставе.','Да-да, у меня как раз есть для тебя задание...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Весенние собиратели',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если тебе не сидится на месте, то поищи магов в поселениях рядом со столицами – в Златоземье, Караносе, Доланааре и на Лазурной заставе. Им нужна помощь в каких-то исследованиях, и они нанимают большое количество охотников за яйцами. Больше сказать не могу, подробности узнаешь у магов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с весенним собирателем в Златоземье, Караносе, Доланааре или на Лазурной заставе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да-да, у меня как раз есть для тебя задание...',`offerrewardtext_loc8`);
