INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (13501,'Кулек конфет','Кульки с конфетами можно найти в любой таверне. Ну – чего стоишь? Хватай конфетку!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кулек конфет',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Кульки с конфетами можно найти в любой таверне. Ну – чего стоишь? Хватай конфетку!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13502,'Что вам надо? Шоколада!','Вот – возьми эту корзину для яиц и ступай искать раскрашенные яйца. Возвращайся, когда наберешь десять праздничных шоколадных яиц.','Соберите 10 праздничных шоколадных яиц и отдайте их продавцу Сада чудес вместе с позаимствованной корзиной для яиц.','$GМолодчина:Умница;! Нет-нет, оставь корзину себе.$B$BЕсли найдешь еще шоколадные яйца, можешь обменять их у меня на что-нибудь полезное.','Ты $Gпринес:принесла; десять шоколадных яиц?','Вернитесь к продавцу Сада чудес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Что вам надо? Шоколада!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот – возьми эту корзину для яиц и ступай искать раскрашенные яйца. Возвращайся, когда наберешь десять праздничных шоколадных яиц.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 праздничных шоколадных яиц и отдайте их продавцу Сада чудес вместе с позаимствованной корзиной для яиц.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','$GМолодчина:Умница;! Нет-нет, оставь корзину себе.$B$BЕсли найдешь еще шоколадные яйца, можешь обменять их у меня на что-нибудь полезное.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gпринес:принесла; десять шоколадных яиц?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к продавцу Сада чудес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13503,'Что вам надо? Шоколада!','Вот – возьми эту корзину для яиц и ступай искать раскрашенные яйца. Возвращайся, когда наберешь десять праздничных шоколадных яиц.','Соберите 10 праздничных шоколадных яиц и отдайте их торговцу Сада чудес вместе с позаимствованной корзиной для яиц.','$GМолодчина:Умница;! Нет-нет, оставь корзину себе.$B$BЕсли найдешь еще шоколадные яйца, можешь обменять их у меня на что-нибудь полезное.','Ты $Gпринес:принесла; десять шоколадных яиц?','Вернитесь к торговцу Сада чудес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Что вам надо? Шоколада!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот – возьми эту корзину для яиц и ступай искать раскрашенные яйца. Возвращайся, когда наберешь десять праздничных шоколадных яиц.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 праздничных шоколадных яиц и отдайте их торговцу Сада чудес вместе с позаимствованной корзиной для яиц.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','$GМолодчина:Умница;! Нет-нет, оставь корзину себе.$B$BЕсли найдешь еще шоколадные яйца, можешь обменять их у меня на что-нибудь полезное.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gпринес:принесла; десять шоколадных яиц?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к торговцу Сада чудес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13504,'Тролли из племени Пронзающего Копья рыскают по руинам, что остались на севере и северо-востоке отсюда, но наши разведчики не обнаружили никаких значимых находок на месте раскопов. Возможно, эти тролли просто таскают боеприпасы для войска?$B$BЯсно одно: чем меньше рабочих рук будет у троллей, тем сложнее им будет вести войну против нас. Этим мы и займемся – уменьшением их количества. Ты с нами?','Убейте 10 работников из племени Пронзающего Копья.','Вернитесь к часовому Тише Лунный Клинок, находящейся на Руинах Матистры.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тролли из племени Пронзающего Копья рыскают по руинам, что остались на севере и северо-востоке отсюда, но наши разведчики не обнаружили никаких значимых находок на месте раскопов. Возможно, эти тролли просто таскают боеприпасы для войска?$B$BЯсно одно: чем меньше рабочих рук будет у троллей, тем сложнее им будет вести войну против нас. Этим мы и займемся – уменьшением их количества. Ты с нами?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 работников из племени Пронзающего Копья.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к часовому Тише Лунный Клинок, находящейся на Руинах Матистры.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13505,'Оставшиеся высокорожденные','Здесь, на Темных берегах, есть еще много подобных руин, но на многих из них обитают неупокоенные призраки высокорожденных. Из уважения к духам мы старались обходить эти руины стороной, но в свете угрозы троллей пора отбросить предрассудки и заняться поиском артефактов. $B$BТак что пока ты будешь помогать часовым, внимательно смотри под ноги и собирай все ценности, которые тебе попадутся. Я хочу сохранить их для будущих поколений.','Добудьте 8 реликвий высокорожденных.','Отлично! Спасибо тебе большое. Мы уже потеряли слишком много – не хотелось бы, чтобы в пламени войны сгорели и эти культурные ценности.','Удалось ли тебе найти хотя бы несколько артефактов?','Вернитесь к Балтулу Удару Тени, находящемуся на Руинах Матистры.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оставшиеся высокорожденные',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Здесь, на Темных берегах, есть еще много подобных руин, но на многих из них обитают неупокоенные призраки высокорожденных. Из уважения к духам мы старались обходить эти руины стороной, но в свете угрозы троллей пора отбросить предрассудки и заняться поиском артефактов. $B$BТак что пока ты будешь помогать часовым, внимательно смотри под ноги и собирай все ценности, которые тебе попадутся. Я хочу сохранить их для будущих поколений.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 8 реликвий высокорожденных.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! Спасибо тебе большое. Мы уже потеряли слишком много – не хотелось бы, чтобы в пламени войны сгорели и эти культурные ценности.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось ли тебе найти хотя бы несколько артефактов?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Балтулу Удару Тени, находящемуся на Руинах Матистры.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (13506,'Причины для волнения','Похоже, это приказы, выданные надзирателям от их начальника из Боевого лагеря Пронзающего Копья. Большая часть информации не содержит стратегически важных данных, но несколько строк привлекают ваше внимание.$B$BТам сказано:"Мы захватили еще одного ночного эльфа, который шпионил за нами. Ее доставили в лагерь для допроса с применением пыток. Берегитесь, вокруг вас могут находиться и другие следопыты. Нельзя допустить, чтобы цель нашей операции была раскрыта."$B$BЭту информацию надо незамедлительно доставить лейтенанту.','Еще одного? Значит, у них в плену находится несколько моих людей, и я не оставлю их в беде. Мы должны действовать быстро.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Причины для волнения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Похоже, это приказы, выданные надзирателям от их начальника из Боевого лагеря Пронзающего Копья. Большая часть информации не содержит стратегически важных данных, но несколько строк привлекают ваше внимание.$B$BТам сказано:"Мы захватили еще одного ночного эльфа, который шпионил за нами. Ее доставили в лагерь для допроса с применением пыток. Берегитесь, вокруг вас могут находиться и другие следопыты. Нельзя допустить, чтобы цель нашей операции была раскрыта."$B$BЭту информацию надо незамедлительно доставить лейтенанту.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Еще одного? Значит, у них в плену находится несколько моих людей, и я не оставлю их в беде. Мы должны действовать быстро.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (13507,'Отрицание силы','К северу отсюда племя Пронзающего Копья разбило военный лагерь, где они сооружают свои катапульты. По последним разведданным, его охраняют не только мистики племени, но также орки и таурены. $B$BБестолку гадать, что может означать их присутствие – лучше пойди и перебей их всех до того, как они снова нападут на наших часовых.','Превосходная работа. Одной угрозой меньше... Мы будем продолжать в том же духе, пока они еще ничего не заподозрили.','Вернитесь к часовому Тише Лунный Клинок, находящейся на Руинах Матистры.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отрицание силы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','К северу отсюда племя Пронзающего Копья разбило военный лагерь, где они сооружают свои катапульты. По последним разведданным, его охраняют не только мистики племени, но также орки и таурены. $B$BБестолку гадать, что может означать их присутствие – лучше пойди и перебей их всех до того, как они снова нападут на наших часовых.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Превосходная работа. Одной угрозой меньше... Мы будем продолжать в том же духе, пока они еще ничего не заподозрили.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к часовому Тише Лунный Клинок, находящейся на Руинах Матистры.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (13508,'Мгновенный ответ','Связь с одной из моих разведчиц прервалась несколько дней назад. Мы полагали, что она погибла, но похоже, ее захватили тролли. Они утверждают, что у них два заложника... но я даже не представляю, кто второй пленник. Может быть, это Аландариан Песня Ночи? Она отправилась туда вопреки моим предостережениям...$B$BВ любом случае, я практически уверена, что пленников держат в боевом лагере Пронзающего Копья на севере отсюда. Если сможешь, найди их и освободи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мгновенный ответ',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Связь с одной из моих разведчиц прервалась несколько дней назад. Мы полагали, что она погибла, но похоже, ее захватили тролли. Они утверждают, что у них два заложника... но я даже не представляю, кто второй пленник. Может быть, это Аландариан Песня Ночи? Она отправилась туда вопреки моим предостережениям...$B$BВ любом случае, я практически уверена, что пленников держат в боевом лагере Пронзающего Копья на севере отсюда. Если сможешь, найди их и освободи.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (13510,'Своевременное прибытие','Как я рада тебя видеть! Признаться, я не надеялась пережить то, что сотворили с Аландариан... так что безмерно благодарна за спасение.$B$BЯ видела предводителя троллей прямо перед собой, и у меня был шанс нанести смертельный удар – но он оказался защищен некоей магической броней. Мы должны сообщить об этом Морре, чтобы она учла это во время нападения. Но для начала хорошо бы выбраться отсюда живыми и невредимыми.$B$BПомоги мне добраться до пристани, и я отправлюсь в Лор\'данел водным путем. А ты тогда сможешь вернуться к Морре и предупредить ее.','Сопроводите часового Айнашу в безопасное место.','Сопроводите часового Айнашу в порт.','Вернитесь к Морре Звездный Ветер, находящейся на Руинах Матистры.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Своевременное прибытие',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как я рада тебя видеть! Признаться, я не надеялась пережить то, что сотворили с Аландариан... так что безмерно благодарна за спасение.$B$BЯ видела предводителя троллей прямо перед собой, и у меня был шанс нанести смертельный удар – но он оказался защищен некоей магической броней. Мы должны сообщить об этом Морре, чтобы она учла это во время нападения. Но для начала хорошо бы выбраться отсюда живыми и невредимыми.$B$BПомоги мне добраться до пристани, и я отправлюсь в Лор\'данел водным путем. А ты тогда сможешь вернуться к Морре и предупредить ее.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сопроводите часового Айнашу в безопасное место.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Сопроводите часового Айнашу в порт.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Морре Звездный Ветер, находящейся на Руинах Матистры.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (13511,'Последняя просьба','Тебя Морра прислала? Ах, почему я ее не послушала... но кто бы мог подумать, что троллей надо воспринимать всерьез?$B$B<Аландариан грустно усмехается.>$B$BВпрочем, для меня все уже кончено. Теперь мы смертные... и должны смотреть в лицо судьбе. У меня было время подумать об этом. $B$BУ меня есть только одна просьба... убей палача, который сделал это со мной. Они называли его Рит\'ко... и он сейчас где-то там, мучает остальных заключенных.$B$B<Аландариан с трудом улыбается, но вскоре лицо ее искажает гримаса боли, и она, корчась, падает на пол.>','Убейте Рит\'ко, мучителя из племени Пронзающего Копья.','Значит, Аландариан умерла. Это печальные новости, хотя я и чувствовала, что этим все кончится. Проклятые дикари не ведают жалости к пленным – но и от нас они не дождутся пощады.','Вернитесь к лейтенанту Морре Звездный Ветер, находящейся на Руинах Матистры.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Последняя просьба',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебя Морра прислала? Ах, почему я ее не послушала... но кто бы мог подумать, что троллей надо воспринимать всерьез?$B$B<Аландариан грустно усмехается.>$B$BВпрочем, для меня все уже кончено. Теперь мы смертные... и должны смотреть в лицо судьбе. У меня было время подумать об этом. $B$BУ меня есть только одна просьба... убей палача, который сделал это со мной. Они называли его Рит\'ко... и он сейчас где-то там, мучает остальных заключенных.$B$B<Аландариан с трудом улыбается, но вскоре лицо ее искажает гримаса боли, и она, корчась, падает на пол.>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Рит\'ко, мучителя из племени Пронзающего Копья.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Значит, Аландариан умерла. Это печальные новости, хотя я и чувствовала, что этим все кончится. Проклятые дикари не ведают жалости к пленным – но и от нас они не дождутся пощады.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лейтенанту Морре Звездный Ветер, находящейся на Руинах Матистры.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (13512,'Предупредительный удар','Мало отсечь голову гидры, если на ее месте тут же вырастет другая. Если мы просто убьем их предводителя, кто знает, не попытается ли один из его помощников занять освободившийся трон. Сейчас они ничего не боятся, и потому ты сможешь расправиться с ними в одиночку.$B$BВозьми это дриадское копье и убей их всех: яд на острие парализует их магические способности. Мои разведчики докладывают, что одного из помощников видели в подводных палатах на востоке руин, а других – у развалин башни на юго-западе.','Убейте Шейю Вьющую Грозы и Лорента Громовой Зов.','Надо же, ты талантлив не по годам! Прекрасно, но главная битва еще ждет нас впереди.','Вернитесь к лейтенанту Морре Звездному Ветру в руины Матистры.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Предупредительный удар',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мало отсечь голову гидры, если на ее месте тут же вырастет другая. Если мы просто убьем их предводителя, кто знает, не попытается ли один из его помощников занять освободившийся трон. Сейчас они ничего не боятся, и потому ты сможешь расправиться с ними в одиночку.$B$BВозьми это дриадское копье и убей их всех: яд на острие парализует их магические способности. Мои разведчики докладывают, что одного из помощников видели в подводных палатах на востоке руин, а других – у развалин башни на юго-западе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Шейю Вьющую Грозы и Лорента Громовой Зов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Надо же, ты талантлив не по годам! Прекрасно, но главная битва еще ждет нас впереди.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лейтенанту Морре Звездному Ветру в руины Матистры.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (13513,'На грани','Я уже работаю над устройством, которое может разрушить их идолы защиты. Думаю, если объединить их магию и волшебство друидов, мы сможем прорвать заслон.$B$BТебе надо найти их шаманов, которые бродят к востоку и юго-востоку отсюда, и добыть несколько амулетов. Я обработаю эти предметы и заколдую стрелу, которую надо будет доставить Сандрии Закат Луны.','Добудьте 6 амулетов племени Пронзающего Копья.','Да, эти вполне подойдут. Я подготовлю их для отправки Сандрии, а тебе надо будет как можно скорее отправиться в путь.','Вернитесь к Балтулу Удару Тени, находящемуся на Руинах Матистры.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На грани',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я уже работаю над устройством, которое может разрушить их идолы защиты. Думаю, если объединить их магию и волшебство друидов, мы сможем прорвать заслон.$B$BТебе надо найти их шаманов, которые бродят к востоку и юго-востоку отсюда, и добыть несколько амулетов. Я обработаю эти предметы и заколдую стрелу, которую надо будет доставить Сандрии Закат Луны.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 6 амулетов племени Пронзающего Копья.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, эти вполне подойдут. Я подготовлю их для отправки Сандрии, а тебе надо будет как можно скорее отправиться в путь.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Балтулу Удару Тени, находящемуся на Руинах Матистры.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (13514,'Гнев Древних','Хочешь присоединиться к ударной группе? А, тебе нужна Сандрия Закат Луны... Она планирует нападение на вожака племени Пронзающего Копья. Ты найдешь ее в пещере по ту сторону долины.$B$BСлушай, пока ты здесь, помоги нам разобраться с остатками племени. Присоединяйся к нашим мстительным заступникам и убедись, что в этом проклятом племени не осталось ни одного целого здания и ни одного живого тролля. Нельзя допустить, чтобы они вернулись в самый неподходящий момент и принялись мстить!','Как нам повезло, что ты сражаешься на нашей стороне!$B$BК сожалению, разведданные об их предводителе еще не поступили. Не забудь поговорить с Сандрией перед отъездом – она ждет тебя в пещере на окраине долины.','Вернитесь к Керлониану Вечному Сумраку в Долину Пронзающего Копья.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гнев Древних',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хочешь присоединиться к ударной группе? А, тебе нужна Сандрия Закат Луны... Она планирует нападение на вожака племени Пронзающего Копья. Ты найдешь ее в пещере по ту сторону долины.$B$BСлушай, пока ты здесь, помоги нам разобраться с остатками племени. Присоединяйся к нашим мстительным заступникам и убедись, что в этом проклятом племени не осталось ни одного целого здания и ни одного живого тролля. Нельзя допустить, чтобы они вернулись в самый неподходящий момент и принялись мстить!',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Как нам повезло, что ты сражаешься на нашей стороне!$B$BК сожалению, разведданные об их предводителе еще не поступили. Не забудь поговорить с Сандрией перед отъездом – она ждет тебя в пещере на окраине долины.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Керлониану Вечному Сумраку в Долину Пронзающего Копья.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertargetname_loc8`) VALUES (13515,'Покончить с угрозой','Прямо перед нами – их предводитель с охраной. Со стражниками разберутся мои часовые; мы ждали только этой стрелы, чтобы решить судьбу главаря.$B$BДай мне знать, когда ты будешь $gготов:готова; к атаке. Как только часовые ринутся в бой, я расколю стрелой щит предводителя, и мы вместе одержим над ним верх. Пусть рука твоя будет тверда, ибо только так мы устраним угрозу, нависшую над нашими землями.$B$BНе медли, все ждут только тебя!','Поговорите с охотницей Сандрией Закат Луны, чтобы она отдала приказ к наступлению, и помогите ей убить Джор\'кила Убийцу Душ.','Это была великая битва, но победой в ней мы обязаны тебе.$B$BНечасто нашим врагам приходилось терпеть столь сокрушительное поражение, но мне все еще кажется, что за нападением Пронзающего Копья стоит что-то большее. Мой тебе совет, обыщи тело вождя прежде, чем покинешь это место.','Вернитесь к Сандрии Закат Луны в Долине Пронзающего Копья.','Джор\'кил Убийца Душ') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Покончить с угрозой',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прямо перед нами – их предводитель с охраной. Со стражниками разберутся мои часовые; мы ждали только этой стрелы, чтобы решить судьбу главаря.$B$BДай мне знать, когда ты будешь $gготов:готова; к атаке. Как только часовые ринутся в бой, я расколю стрелой щит предводителя, и мы вместе одержим над ним верх. Пусть рука твоя будет тверда, ибо только так мы устраним угрозу, нависшую над нашими землями.$B$BНе медли, все ждут только тебя!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с охотницей Сандрией Закат Луны, чтобы она отдала приказ к наступлению, и помогите ей убить Джор\'кила Убийцу Душ.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это была великая битва, но победой в ней мы обязаны тебе.$B$BНечасто нашим врагам приходилось терпеть столь сокрушительное поражение, но мне все еще кажется, что за нападением Пронзающего Копья стоит что-то большее. Мой тебе совет, обыщи тело вождя прежде, чем покинешь это место.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сандрии Закат Луны в Долине Пронзающего Копья.',`completedtext_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Джор\'кил Убийца Душ',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13518,'Последняя группа беженцев','Увы, Лайрд не успел добраться до безопасного места.$B$BПоследняя группа ночных эльфов из Аубердина отправилась пару часов назад. Они до последнего прятались в своих разрушенных домах, ожидая спасения, но в итоге им все же пришлось бежать. Боюсь, многие из них разделили судьбу Лайрда.$B$BНо все же, я прошу тебя отправиться на западную часть побережья и поискать выживших. Мы обязательно пришлем за ними часовых на гиппогрифах, но сначала надо определить, о каком количестве беженцев идет речь. Поторопись, каждая секунда промедления может стоить им жизни!','Найдите всех выживших беженцев из Аубердина.','Вернитесь к жрице Дентарии в Лор\'данел.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Последняя группа беженцев',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Увы, Лайрд не успел добраться до безопасного места.$B$BПоследняя группа ночных эльфов из Аубердина отправилась пару часов назад. Они до последнего прятались в своих разрушенных домах, ожидая спасения, но в итоге им все же пришлось бежать. Боюсь, многие из них разделили судьбу Лайрда.$B$BНо все же, я прошу тебя отправиться на западную часть побережья и поискать выживших. Мы обязательно пришлем за ними часовых на гиппогрифах, но сначала надо определить, о каком количестве беженцев идет речь. Поторопись, каждая секунда промедления может стоить им жизни!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите всех выживших беженцев из Аубердина.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к жрице Дентарии в Лор\'данел.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (13519,'Культ Сумеречного Молота','Служители культа Сумеречного Молота разбили лагерь на юго-западе отсюда и собирают армию элементалей воды, чтобы напасть на Лор\'данел.$B$BИх повелитель, Верховный сектант Азеринн, заключил союз с жестокими древними богами, и те даровали его последователям власть над стихиями. Иди и разберись с ними, пока еще не слишком поздно.$B$BКатаклизм поверг духов стихий в смятение, но если наши враги соберут достаточно большую армию, то нам не устоять перед ними.','Убейте верховного сектанта Азеринна и 10 фанатиков культа Сумеречного Молота в лагере Сумеречного Молота.','Вернитесь к часовому Лендре в Лор\'данел, что на Темных берегах.','Его смерть имеет огромное значение для нас.','Верховный сектант Азеринн') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Культ Сумеречного Молота',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Служители культа Сумеречного Молота разбили лагерь на юго-западе отсюда и собирают армию элементалей воды, чтобы напасть на Лор\'данел.$B$BИх повелитель, Верховный сектант Азеринн, заключил союз с жестокими древними богами, и те даровали его последователям власть над стихиями. Иди и разберись с ними, пока еще не слишком поздно.$B$BКатаклизм поверг духов стихий в смятение, но если наши враги соберут достаточно большую армию, то нам не устоять перед ними.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте верховного сектанта Азеринна и 10 фанатиков культа Сумеречного Молота в лагере Сумеречного Молота.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к часовому Лендре в Лор\'данел, что на Темных берегах.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Его смерть имеет огромное значение для нас.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Верховный сектант Азеринн',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (13520,'Дар морей','Я рада снова видеть тебя. Благодаря тебе наши родные и близкие смогли вернуться домой, но я тешу себя надеждой, что ты и дальше будешь помогать нашему делу.$B$BЭтого мужчину зовут Лайрд, и он один из многих воинов, которые получили тяжелые ранения в битве с элементалями на побережье. Я делаю все, что могу для того, чтобы спасти ему жизнь, но яд духов стихий проникает все глубже в его тело, ослабляя действие лекарственных средств. Есть одна мазь, которая могла бы помочь в таком случае, но для ее изготовления мне понадобятся мышцы моллюсков, обитающих на побережье. Ты можешь их достать?','Соберите 16 затвердевших мышц моллюска.','Да, эти моллюски вполне сгодятся. Спасибо большое!$B$BПожалуйста, загляни к нам попозже – многие воины хотели бы лично отблагодарить тебя за спасение.','Вернитесь к жрице Серендии в Лор\'данел.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дар морей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я рада снова видеть тебя. Благодаря тебе наши родные и близкие смогли вернуться домой, но я тешу себя надеждой, что ты и дальше будешь помогать нашему делу.$B$BЭтого мужчину зовут Лайрд, и он один из многих воинов, которые получили тяжелые ранения в битве с элементалями на побережье. Я делаю все, что могу для того, чтобы спасти ему жизнь, но яд духов стихий проникает все глубже в его тело, ослабляя действие лекарственных средств. Есть одна мазь, которая могла бы помочь в таком случае, но для ее изготовления мне понадобятся мышцы моллюсков, обитающих на побережье. Ты можешь их достать?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 16 затвердевших мышц моллюска.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, эти моллюски вполне сгодятся. Спасибо большое!$B$BПожалуйста, загляни к нам попозже – многие воины хотели бы лично отблагодарить тебя за спасение.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к жрице Серендии в Лор\'данел.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13521,'Жужжалка 413','Здравствуй!$B$BЯ помощник Тарнариуна, и мы с ним пытаемся выяснить, что заразило диких животных в этой местности. Для этого я установил по всему периметру некие машины, которые способны анализировать ткани живых существ на предмет источника порчи. Если ты поможешь мне добыть образцы, мы сможем приступить к исследованиям.$B$BПервая машина называется Жужжалка 413, и я установил ее на пляже к востоку от города. принеси к ней для анализа плоть зараженных прибрежных крабов.','Соберите 4 куска мяса зараженного прибрежного краба и отнесите их к Жужжалке 413 для анализа.','<Аппарат громко трещит, и через статистические помехи с трудом прорывается голос Бацбаха.>$B$BПрекрасно! Надеюсь, тебе не пришлось перебить их всех. Мы не собираемся устроить геноцид, нам надо просто установить источник разложения! Я немедленно приступлю к анализу.','<Жужжалка 413 выжидательно гудит.>','Отнесите образцы Жужжалке 413 в Туманный Предел.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жужжалка 413',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Здравствуй!$B$BЯ помощник Тарнариуна, и мы с ним пытаемся выяснить, что заразило диких животных в этой местности. Для этого я установил по всему периметру некие машины, которые способны анализировать ткани живых существ на предмет источника порчи. Если ты поможешь мне добыть образцы, мы сможем приступить к исследованиям.$B$BПервая машина называется Жужжалка 413, и я установил ее на пляже к востоку от города. принеси к ней для анализа плоть зараженных прибрежных крабов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 4 куска мяса зараженного прибрежного краба и отнесите их к Жужжалке 413 для анализа.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Аппарат громко трещит, и через статистические помехи с трудом прорывается голос Бацбаха.>$B$BПрекрасно! Надеюсь, тебе не пришлось перебить их всех. Мы не собираемся устроить геноцид, нам надо просто установить источник разложения! Я немедленно приступлю к анализу.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Жужжалка 413 выжидательно гудит.>',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите образцы Жужжалке 413 в Туманный Предел.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (13522,'Угроза из воды','Не все выжившие добрались до лагеря – некоторые из них все еще пытаются обогнуть побережье. Только недавно я получила сообщение, что они собираются прибыть сюда в течение следующего часа. Ах, почему они не предупредили меня заранее?$B$BВсе побережье к западу отсюда кишит коварными потоками, маленькими, но злобными духами воды. Мы должны уничтожить их, иначе никто из пострадавших не доберется до Лор\'данела. Нельзя медлить ни минуты!','Убейте 8 коварных потоков.','Твоя помощь бесценна для нас. После того как Катаклизм прокатился по этим землям, духи стихий как с цепи сорвались. Если мы не уберем их с нашего пути, то никогда не отвоюем Аубердин.','Вернитесь к стрелку Глинде Нал\'шии в Лор\'данел.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Угроза из воды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не все выжившие добрались до лагеря – некоторые из них все еще пытаются обогнуть побережье. Только недавно я получила сообщение, что они собираются прибыть сюда в течение следующего часа. Ах, почему они не предупредили меня заранее?$B$BВсе побережье к западу отсюда кишит коварными потоками, маленькими, но злобными духами воды. Мы должны уничтожить их, иначе никто из пострадавших не доберется до Лор\'данела. Нельзя медлить ни минуты!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 коварных потоков.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Твоя помощь бесценна для нас. После того как Катаклизм прокатился по этим землям, духи стихий как с цепи сорвались. Если мы не уберем их с нашего пути, то никогда не отвоюем Аубердин.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к стрелку Глинде Нал\'шии в Лор\'данел.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13523,'Власть над приливами','Не беспокойся обо мне. Раны мои глубоки, и смерть не заставит себя ждать.$B$BТеперь все в твоих руках... ты $gдолжен:должна; остановить служителей культа Сумеречного Молота.$B$BДревние боги, которым они поклоняются, даровали им власть над неугомонными духами воды... но сила эта не слишком велика. Позволь духу Элуны проникнуть через этот шар, когда победишь элементалей.$b$bВоспользуйся силой Элуны, чтобы навеки успокоить духов.','Прикоснитесь Сферой Элуны к останкам 6 разъяренных духов волны.','Вернитесь к жрице луны Тарилл в лагерь Сумеречного Молота.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Власть над приливами',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не беспокойся обо мне. Раны мои глубоки, и смерть не заставит себя ждать.$B$BТеперь все в твоих руках... ты $gдолжен:должна; остановить служителей культа Сумеречного Молота.$B$BДревние боги, которым они поклоняются, даровали им власть над неугомонными духами воды... но сила эта не слишком велика. Позволь духу Элуны проникнуть через этот шар, когда победишь элементалей.$b$bВоспользуйся силой Элуны, чтобы навеки успокоить духов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Прикоснитесь Сферой Элуны к останкам 6 разъяренных духов волны.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к жрице луны Тарилл в лагерь Сумеречного Молота.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13524,'Побег из Среброречья','Ты... ты не $gодин:одна; из них? Быстрее! Освободи меня!$B$BНам нужно немедленно отправляться в Приют Янтарной Сосны! Как только лейтенант Думонт узнает, кто эти люди на самом деле, он камня на камне не оставит от этого города!','Откройте деревянную клетку и помогите освобожденному разведчику Альянса сбежать из Среброречья. Доложитесь лейтенанту Думонту по прибытии в Приют Янтарной Сосны.','Вернитесь к лейтенанту Думонту в Седые холмы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Побег из Среброречья',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты... ты не $gодин:одна; из них? Быстрее! Освободи меня!$B$BНам нужно немедленно отправляться в Приют Янтарной Сосны! Как только лейтенант Думонт узнает, кто эти люди на самом деле, он камня на камне не оставит от этого города!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Откройте деревянную клетку и помогите освобожденному разведчику Альянса сбежать из Среброречья. Доложитесь лейтенанту Думонту по прибытии в Приют Янтарной Сосны.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лейтенанту Думонту в Седые холмы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (13525,'Что случилось с фурболгами Чернолесья?','Поговорите со старейшиной Бролгом в логове Чернолесья.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Что случилось с фурболгами Чернолесья?',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите со старейшиной Бролгом в логове Чернолесья.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13526,'Медвежья лапка','Мерзкие сатиры, обитатели Оскверненного леса, начали распространять свою заразу здесь, на Темных берегах. Эта порча убивает нашу родную землю и оскверняет всех живых существ. Не избежал этой участи и мой народ...$B$BНашей магии не хватит на то, чтобы привести в чувство тех, кто пал жертвой заразы. Но в этих краях растет одна травка, медвежья лапа, которая снимает жар и придает сил больному. С ее помощью мы сможем разрушить злые чары сатиров. Как хорошо, что ее можно найти повсюду вокруг деревни!','Принесите 8 пучков медвежьей лапы старейшине Бролгу в логово Чернолесья.','Эти стебли такие вялые и пожухшие... Видимо, порча уже перекинулась на лесные растения.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Медвежья лапка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мерзкие сатиры, обитатели Оскверненного леса, начали распространять свою заразу здесь, на Темных берегах. Эта порча убивает нашу родную землю и оскверняет всех живых существ. Не избежал этой участи и мой народ...$B$BНашей магии не хватит на то, чтобы привести в чувство тех, кто пал жертвой заразы. Но в этих краях растет одна травка, медвежья лапа, которая снимает жар и придает сил больному. С ее помощью мы сможем разрушить злые чары сатиров. Как хорошо, что ее можно найти повсюду вокруг деревни!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 8 пучков медвежьей лапы старейшине Бролгу в логово Чернолесья.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Эти стебли такие вялые и пожухшие... Видимо, порча уже перекинулась на лесные растения.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (13527,'Никакого вкуса','<Машина некоторое время издает гудящие звуки, через которые прорывается голос Бацбаха.>$B$BЛюбопытно! Источник этой порчи находится где-то извне – что меня не удивляет – но похоже, в данном случае они съели что-то тухлое. Возможно, закусили каким-нибудь большим млекопитающим типа медведя.$B$BОбыщи берег, там должны были остаться его кости. Полагаю, имеет смысл поискать на востоке отсюда, на внешней стороне пляжа. Побыстрее возвращайся с образцами!','Принесите образец разложившейся медвежьей плоти на восток к Жужжалке 413.','Да, это похоже на то, чем они питаются. Дай-ка мне взглянуть поближе...','Вернитесь к Бацбаху Кривошипу в Лор\'данел.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Никакого вкуса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Машина некоторое время издает гудящие звуки, через которые прорывается голос Бацбаха.>$B$BЛюбопытно! Источник этой порчи находится где-то извне – что меня не удивляет – но похоже, в данном случае они съели что-то тухлое. Возможно, закусили каким-нибудь большим млекопитающим типа медведя.$B$BОбыщи берег, там должны были остаться его кости. Полагаю, имеет смысл поискать на востоке отсюда, на внешней стороне пляжа. Побыстрее возвращайся с образцами!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите образец разложившейся медвежьей плоти на восток к Жужжалке 413.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, это похоже на то, чем они питаются. Дай-ка мне взглянуть поближе...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бацбаху Кривошипу в Лор\'данел.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13528,'Жужжалка 723','Я обнаружил еще несколько заразившихся существ. К счастью, можно точно сказать, что крабы подцепили эту дрянь от медведей – а это означает, что источник заражения только один. Мы должны сконцентрировать наше внимание на этих косолапых.$B$BПослушай, у меня есть для тебя одно неприятное, но очень важное поручение. К востоку от водопадов я спрятал Жужжалку 723: отнеси ей для анализа свежие внутренности медведей. Как только результат будет готов, мы решим, что делать дальше.','Соберите 6 образцов внутренностей зараженных колючешерстных медведей и принесите их к Жужжалке 723 для анализа.','<Среди помех пробивается искаженный голос Бацбаха.>$B$BРезультаты скоро будут готовы. Еще минутка – и мы узнаем, что случилось с этими медведями.','<Жужжалка 723 выжидательно гудит.>','Отнесите образцы Жужжалке 723 у водопада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жужжалка 723',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я обнаружил еще несколько заразившихся существ. К счастью, можно точно сказать, что крабы подцепили эту дрянь от медведей – а это означает, что источник заражения только один. Мы должны сконцентрировать наше внимание на этих косолапых.$B$BПослушай, у меня есть для тебя одно неприятное, но очень важное поручение. К востоку от водопадов я спрятал Жужжалку 723: отнеси ей для анализа свежие внутренности медведей. Как только результат будет готов, мы решим, что делать дальше.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 6 образцов внутренностей зараженных колючешерстных медведей и принесите их к Жужжалке 723 для анализа.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Среди помех пробивается искаженный голос Бацбаха.>$B$BРезультаты скоро будут готовы. Еще минутка – и мы узнаем, что случилось с этими медведями.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Жужжалка 723 выжидательно гудит.>',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите образцы Жужжалке 723 у водопада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (13529,'Источник разложения','Уф! Я бежал со всех ног, как только получил сообщение от Бацбаха. Я знаю, кто стоит за всем этим! Зенн Грязное Копыто!$B$BОн явился из Тельдрассила, где его поймали за использованием некоей извращенной формы магии. Подобные практики не приветствуются среди моего народа, но похоже, на этот раз он зашел еще дальше – возможно, из мести.$B$BМы слишком часто прощали Зенна, и на этот раз он должен поплатиться жизнью за преступления против природы. Убей его, уничтожь всех его прислужников и возвращайся в Лор\'данел.','Убейте Зенна Грязное Копыто и 8 коварных греллей в Скалистой пещере.','Значит, дело сделано. Спасибо тебе. Я лишь надеюсь, что с его смертью природа обретет долгожданный покой.','Вернитесь к Тарнариуну Исцелителю Деревьев в Лор\'данел.','Терпение и прощение имеют предел. Зенн же перешел всякие рамки.','Зенн Грязное Копыто') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Источник разложения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Уф! Я бежал со всех ног, как только получил сообщение от Бацбаха. Я знаю, кто стоит за всем этим! Зенн Грязное Копыто!$B$BОн явился из Тельдрассила, где его поймали за использованием некоей извращенной формы магии. Подобные практики не приветствуются среди моего народа, но похоже, на этот раз он зашел еще дальше – возможно, из мести.$B$BМы слишком часто прощали Зенна, и на этот раз он должен поплатиться жизнью за преступления против природы. Убей его, уничтожь всех его прислужников и возвращайся в Лор\'данел.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Зенна Грязное Копыто и 8 коварных греллей в Скалистой пещере.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Значит, дело сделано. Спасибо тебе. Я лишь надеюсь, что с его смертью природа обретет долгожданный покой.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тарнариуну Исцелителю Деревьев в Лор\'данел.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Терпение и прощение имеют предел. Зенн же перешел всякие рамки.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Зенн Грязное Копыто',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13537,'Любовь к окуням','Все эти поездки и строительства меня ужасно измотали... мне срочно надо что-нибудь перекусить! Знаешь, о чем я сейчас думаю? О вкусной, ароматной рыбе!$B$BНа Темных берегах издавна ловили морских окуней. Если ты принесешь мне несколько штук, то не пожалеешь потраченного времени!','Похоже, у тебя талант рыболова! Мой желудок говорит тебе "спасибо". $B$BПослушай, эта удочка пригодится тебе больше, чем мне. Оставь ее у себя.','<Вы слышите, как живот Джонатана урчит при вашем приближении.>$B$BДа-да, он говорит за меня!','Вернитесь к Джонатану Стаатсу в Лор\'данел.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Любовь к окуням',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Все эти поездки и строительства меня ужасно измотали... мне срочно надо что-нибудь перекусить! Знаешь, о чем я сейчас думаю? О вкусной, ароматной рыбе!$B$BНа Темных берегах издавна ловили морских окуней. Если ты принесешь мне несколько штук, то не пожалеешь потраченного времени!',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Похоже, у тебя талант рыболова! Мой желудок говорит тебе "спасибо". $B$BПослушай, эта удочка пригодится тебе больше, чем мне. Оставь ее у себя.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Вы слышите, как живот Джонатана урчит при вашем приближении.>$B$BДа-да, он говорит за меня!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джонатану Стаатсу в Лор\'данел.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13538,'Южный саботаж','Я слышал этот взрыв! Неплохо сработано! Мы уже приступили к перенаправлению энергии в реликвию титанов, чтобы наделить наши войска суперсилой.','Какие новости с юга?','Вернитесь к офицеру-стратегу Абрамису на Озеро Ледяных Оков.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Южный саботаж',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я слышал этот взрыв! Неплохо сработано! Мы уже приступили к перенаправлению энергии в реликвию титанов, чтобы наделить наши войска суперсилой.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Какие новости с юга?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к офицеру-стратегу Абрамису на Озеро Ледяных Оков.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13539,'Свержение башен','Уничтожьте башню Темного Взора, башню Огненного Дозора или башню Клинка Зимы, затем вернитесь к офицеру-стратегу Килрату.','Чтобы убивать врагов, наших воинов нужно рассердить. Они должны знать, что после победы над врагом, награда не заставит себя ждать. Надеюсь это достойная плата за твою службу Орде.','Сильнее моего отвращения к чернокнижникам - только отвращение к нежити. Однако иногда они могут пригодиться.','Вернитесь к офицеру-стратегу Килрату на Озеро Ледяных Оков.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Свержение башен',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте башню Темного Взора, башню Огненного Дозора или башню Клинка Зимы, затем вернитесь к офицеру-стратегу Килрату.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Чтобы убивать врагов, наших воинов нужно рассердить. Они должны знать, что после победы над врагом, награда не заставит себя ждать. Надеюсь это достойная плата за твою службу Орде.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Сильнее моего отвращения к чернокнижникам - только отвращение к нежити. Однако иногда они могут пригодиться.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к офицеру-стратегу Килрату на Озеро Ледяных Оков.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13542,'Против ветра','Если мы планируем когда-нибудь отвоевать руины Аубердина у последователей Сумеречного Молота, нам надо раз и навсегда разобраться с призванными ими элементалями.$B$BТут-то нам и понадобится твоя помощь.$B$BСлушай, никто и не ожидает, что ты в одиночку освободишь город, но пока мы тут зализываем раны, ты можешь расчистить нам дорогу.$B$BЧтобы окончательно уничтожить бесноватые циклоны, отправляйся на запад, убей элементалей, сними с них наручи и положи в лунный колодец. Если ты уничтожишь наручи, они больше не смогут возродиться.','Воспользуйтесь лунным колодцем в руинах Аубердина, чтобы уничтожить 8 наручей бесноватого циклона.','Вернитесь к часовому Селарине в Аубердинский лагерь беженцев, что на Темных берегах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Против ветра',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если мы планируем когда-нибудь отвоевать руины Аубердина у последователей Сумеречного Молота, нам надо раз и навсегда разобраться с призванными ими элементалями.$B$BТут-то нам и понадобится твоя помощь.$B$BСлушай, никто и не ожидает, что ты в одиночку освободишь город, но пока мы тут зализываем раны, ты можешь расчистить нам дорогу.$B$BЧтобы окончательно уничтожить бесноватые циклоны, отправляйся на запад, убей элементалей, сними с них наручи и положи в лунный колодец. Если ты уничтожишь наручи, они больше не смогут возродиться.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь лунным колодцем в руинах Аубердина, чтобы уничтожить 8 наручей бесноватого циклона.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к часовому Селарине в Аубердинский лагерь беженцев, что на Темных берегах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (13543,'Три молота','Вернитесь к Корвину Восходу Луны в Аубердинский лагерь беженцев на Темных берегах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Три молота',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Корвину Восходу Луны в Аубердинский лагерь беженцев на Темных берегах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13544,'Благословение медведя','Чтобы использовать медвежью лапку для очищения зараженных, надо вплести в пучок трав еще кое-какие ингредиенты и благословить талисман. К северу от деревни бродит долгоног по имени Быстроног: именно его перья годятся для завершения талисмана.$B$BПринеси перья долгонога и пучок медвежьих лапок к древней статуе медведя, которая стоит среди руин в Роще Древних. Это на севере от того места, где бродит Быстроног.$B$BКогда найдешь святилище, свяжи вместе перья и стебли травы. Пусть дух медведя благословит этот букет.','Старейшина Бролг из логова Чернолесья попросил вас принести ему пучок благословенных трав.','<Старейшина Бролг принимает у вас из рук благословенный пучок и внимательно его осматривает. >$B$BЭто именно то, что надо! Теперь, когда дух медведя благоволит нам, у моих братьев появилась надежда на спасение.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Благословение медведя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чтобы использовать медвежью лапку для очищения зараженных, надо вплести в пучок трав еще кое-какие ингредиенты и благословить талисман. К северу от деревни бродит долгоног по имени Быстроног: именно его перья годятся для завершения талисмана.$B$BПринеси перья долгонога и пучок медвежьих лапок к древней статуе медведя, которая стоит среди руин в Роще Древних. Это на севере от того места, где бродит Быстроног.$B$BКогда найдешь святилище, свяжи вместе перья и стебли травы. Пусть дух медведя благословит этот букет.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Старейшина Бролг из логова Чернолесья попросил вас принести ему пучок благословенных трав.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Старейшина Бролг принимает у вас из рук благословенный пучок и внимательно его осматривает. >$B$BЭто именно то, что надо! Теперь, когда дух медведя благоволит нам, у моих братьев появилась надежда на спасение.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (13545,'Очищение оскверненных','Теперь, когда у тебя есть священные травы и благословение великого медведя, ты сможешь очистить от скверны моих братьев. Порча, охватившая весь Оскверненный лес, свела их с ума, и теперь они нападают на всех, кто осмелится приблизиться. Приготовьcя к тому, что они будут преследовать и тебя, пока ты не уничтожишь духов зла, которые в них вселились.$B$BОсвободи племя Чернолесья от оков безумия и возвращайся назад.','Старейшина Бролг просит вас воспользоваться пучком благословенных трав, чтобы очистить 7 фурболгов Чернолесья, после чего убейте духов осквернения, сводивших их с ума.','Ты хорошо справилась. Мой народ постепенно начал освобождаться от оков безумия, но все будет напрасно, если мы не уничтожим источник порчи.','Вернитесь к старейшине Бролгу в Чернолесье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Очищение оскверненных',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда у тебя есть священные травы и благословение великого медведя, ты сможешь очистить от скверны моих братьев. Порча, охватившая весь Оскверненный лес, свела их с ума, и теперь они нападают на всех, кто осмелится приблизиться. Приготовьcя к тому, что они будут преследовать и тебя, пока ты не уничтожишь духов зла, которые в них вселились.$B$BОсвободи племя Чернолесья от оков безумия и возвращайся назад.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Старейшина Бролг просит вас воспользоваться пучком благословенных трав, чтобы очистить 7 фурболгов Чернолесья, после чего убейте духов осквернения, сводивших их с ума.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты хорошо справилась. Мой народ постепенно начал освобождаться от оков безумия, но все будет напрасно, если мы не уничтожим источник порчи.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старейшине Бролгу в Чернолесье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (13546,'Осквернитель','Сатиры из племени Нефритового Пламени проникли на Темные берега и теперь оскверняют все, к чему прикасаются их нечестивые лапы – землю, воду и даже живых существ. Ты ведь уже $gвидел:видела;, что делает порча с моим народом и нашим домом. Если мы не сможем дать отпор сатирам, эта участь постигнет каждого из нас.$B$BШаракс Осквернитель, сатир, ответственный за все беды Чернолесья, скрывается в пещере на востоке отсюда. Убей его, $n, освободи эту землю от его зловещего присутствия. Мы должны показать сатирам, что не собираемся сдаваться на их милость!','Старейшина Бролг из логова Чернолесья просит вас убить Шаракса Осквернителя.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Осквернитель',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сатиры из племени Нефритового Пламени проникли на Темные берега и теперь оскверняют все, к чему прикасаются их нечестивые лапы – землю, воду и даже живых существ. Ты ведь уже $gвидел:видела;, что делает порча с моим народом и нашим домом. Если мы не сможем дать отпор сатирам, эта участь постигнет каждого из нас.$B$BШаракс Осквернитель, сатир, ответственный за все беды Чернолесья, скрывается в пещере на востоке отсюда. Убей его, $n, освободи эту землю от его зловещего присутствия. Мы должны показать сатирам, что не собираемся сдаваться на их милость!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Старейшина Бролг из логова Чернолесья просит вас убить Шаракса Осквернителя.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (13547,'Отделение душ','Твои друзья из лагеря беженцев не знают о том, какую угрозу представляет культ Сумеречного Молота для всего мира.$B$BНо прежде, чем ты сможешь разобраться с ними, мы должны получить помощь от мертвецов Аубердина.$B$BОбыщи руины города и найди тела Тандриса Ветропряда, Элиссы Звездный Ветер, Тальдана и Кайлаис Лунное Перо. Отдели их души от тел и возвращайся ко мне.','Отделите души Тандриса Ветропряда, Элиссы Звездный Ветер, Тальдана и Кайлаис Лунное Перо.','Так много смерти и боли... Стоит ли сомневаться, что будет еще хуже?$B$BВсе, что я хочу – следовать дальше своим путем, который приведет меня в объятия богини.$B$BНо сначала давай посмотрим, сможем ли мы предотвратить дальнейшее распространение порчи и разложения.','Вернитесь к Айльде на Руины Аубердина на Темных берегах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отделение душ',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Твои друзья из лагеря беженцев не знают о том, какую угрозу представляет культ Сумеречного Молота для всего мира.$B$BНо прежде, чем ты сможешь разобраться с ними, мы должны получить помощь от мертвецов Аубердина.$B$BОбыщи руины города и найди тела Тандриса Ветропряда, Элиссы Звездный Ветер, Тальдана и Кайлаис Лунное Перо. Отдели их души от тел и возвращайся ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отделите души Тандриса Ветропряда, Элиссы Звездный Ветер, Тальдана и Кайлаис Лунное Перо.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так много смерти и боли... Стоит ли сомневаться, что будет еще хуже?$B$BВсе, что я хочу – следовать дальше своим путем, который приведет меня в объятия богини.$B$BНо сначала давай посмотрим, сможем ли мы предотвратить дальнейшее распространение порчи и разложения.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Айльде на Руины Аубердина на Темных берегах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (13548,'Кулек конфет','Кульки с конфетами можно найти в любой таверне. Ну – чего стоишь? Хватай конфетку!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кулек конфет',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Кульки с конфетами можно найти в любой таверне. Ну – чего стоишь? Хватай конфетку!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13549,'Хвост трубой','Помимо артефактов Драккари, меня также интересует животный мир Зул\'Драка. Мне бы очень хотелось привезти в Зандалар некоторые образцы местной фауны. У меня уже есть самцы леопарда и ледолапого медведя, но теперь мне нужно несколько самочек!$B$BК великому сожалению, мой ловчий внезапно скончался. Может быть, ты подменишь его?$B$BПожалуйста, возьми это ружье, оно стреляет усыпляющими дротиками. Усыпи зверя и загляни ему под хвост. Запомни – меня интересуют самки. Леопарды и медведи водятся возле алтарей Рунока, Кетц\'лун и Хар\'коа.','По просьбе летописца То\'кини из Зим\'Торги усыпляйте из воздушного ружья То\'кини северных леопардов и ледолапых медведей. Возвращайтесь к нему, поймав по три самки каждого вида.','Что случилось?','Вернитесь к летописцу То\'кини в Зим\'Торгу, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хвост трубой',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Помимо артефактов Драккари, меня также интересует животный мир Зул\'Драка. Мне бы очень хотелось привезти в Зандалар некоторые образцы местной фауны. У меня уже есть самцы леопарда и ледолапого медведя, но теперь мне нужно несколько самочек!$B$BК великому сожалению, мой ловчий внезапно скончался. Может быть, ты подменишь его?$B$BПожалуйста, возьми это ружье, оно стреляет усыпляющими дротиками. Усыпи зверя и загляни ему под хвост. Запомни – меня интересуют самки. Леопарды и медведи водятся возле алтарей Рунока, Кетц\'лун и Хар\'коа.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По просьбе летописца То\'кини из Зим\'Торги усыпляйте из воздушного ружья То\'кини северных леопардов и ледолапых медведей. Возвращайтесь к нему, поймав по три самки каждого вида.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что случилось?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к летописцу То\'кини в Зим\'Торгу, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (13554,'Излечение во тьме','<Машина издает нечленораздельные звуки, после которых вы наконец-то снова слышите голос Бацбаха.>$B$BСумеречники! Теперь оно взялось за сумеречников! Эти мелкие негодники лезут из пещеры под восточной скалой. Ее легко найти, если следовать по тропинке на северо-восток и искать углубление под водопадом.$B$BТо ли эти сумеречники чем-то отравились, то ли кто-то специально опрыскал их ядом – в любом случае, мы должны выяснить, что это такое!','Добудьте 6 образцов зараженной лимфы существ из Скалистой пещеры.','Этого вполне хватит! Спасибо тебе огромное! Я немедленно займусь изготовлением лекарства.','Вернитесь к Бацбаху Кривошипу в Лор\'данел.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Излечение во тьме',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Машина издает нечленораздельные звуки, после которых вы наконец-то снова слышите голос Бацбаха.>$B$BСумеречники! Теперь оно взялось за сумеречников! Эти мелкие негодники лезут из пещеры под восточной скалой. Ее легко найти, если следовать по тропинке на северо-восток и искать углубление под водопадом.$B$BТо ли эти сумеречники чем-то отравились, то ли кто-то специально опрыскал их ядом – в любом случае, мы должны выяснить, что это такое!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 6 образцов зараженной лимфы существ из Скалистой пещеры.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Этого вполне хватит! Спасибо тебе огромное! Я немедленно займусь изготовлением лекарства.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бацбаху Кривошипу в Лор\'данел.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13556,'Яйца для Дубра\'джина','Как дела, $gпацан:деваха;? Думаешь, ты сможешь мне помочь? Ба\'Кини понадобится много яиц ящера для жертвоприношений Дубра\'джину.$B$BЕсли бы не ритуалы, нас давно бы уже поработили драккари! Дубра\'джин помогает нам!$B$BСобери яйца ящеров под деревьями здесь, в Гундраке. Иногда ящеры носят их с собой, чтобы держать их в тепле.','Соберите 12 яиц ящера Гундрака по заданию Га\'ваны из Дубра\'джина.','Кто бы мог подумать, что великому Дубра\'джину будет нужно столько яиц! Интересно, что он будет с ними делать?','Вернитесь к Га\'ване в Дубра\'джин, что в Зул\'Драке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Яйца для Дубра\'джина',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как дела, $gпацан:деваха;? Думаешь, ты сможешь мне помочь? Ба\'Кини понадобится много яиц ящера для жертвоприношений Дубра\'джину.$B$BЕсли бы не ритуалы, нас давно бы уже поработили драккари! Дубра\'джин помогает нам!$B$BСобери яйца ящеров под деревьями здесь, в Гундраке. Иногда ящеры носят их с собой, чтобы держать их в тепле.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 12 яиц ящера Гундрака по заданию Га\'ваны из Дубра\'джина.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Кто бы мог подумать, что великому Дубра\'джину будет нужно столько яиц! Интересно, что он будет с ними делать?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Га\'ване в Дубра\'джин, что в Зул\'Драке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (13557,'Неожиданная удача','Похоже, это ключ от клеток с животными, которые встречаются по всей Скалистой пещере. Танариун несомненно оценит, если вы проявите инициативу и освободите нескольких незараженных сумеречников и колючешерстных медведей.','Освободите 8 незараженных колючешерстных медведей или незараженных сумеречников из клеток в Скалистой пещере.','Я рад слышать, что тебе удалось освободить несколько выживших животных. Если нам повезет, мы отыщем противоядие и спасем остальных.','Поговорите с Тарнариуном Исцелителем Деревьев в Лор\'данеле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Неожиданная удача',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Похоже, это ключ от клеток с животными, которые встречаются по всей Скалистой пещере. Танариун несомненно оценит, если вы проявите инициативу и освободите нескольких незараженных сумеречников и колючешерстных медведей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Освободите 8 незараженных колючешерстных медведей или незараженных сумеречников из клеток в Скалистой пещере.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я рад слышать, что тебе удалось освободить несколько выживших животных. Если нам повезет, мы отыщем противоядие и спасем остальных.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Тарнариуном Исцелителем Деревьев в Лор\'данеле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (13558,'Призывая гром','Воспользуйтесь ритуальной сферой Эфериона, чтобы добыть сущность Эфериона.','Айльда? И другие духи с руин Аубердина?$B$B<Друид раздумывает над тем, что вы ему рассказали.>$B$BЯ помню их всех... Печаль переполняет мое сердце, но отныне они обрели покой в объятиях богини, а значит – все было к лучшему.$B$BАнде\'торас-этиль, да уменьшатся твои невзгоды.','Вернитесь к Корвину Восходу Луны в Аубердинский лагерь беженцев на Темных берегах.','Достань его сущность!','Эферион') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Призывая гром',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь ритуальной сферой Эфериона, чтобы добыть сущность Эфериона.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Айльда? И другие духи с руин Аубердина?$B$B<Друид раздумывает над тем, что вы ему рассказали.>$B$BЯ помню их всех... Печаль переполняет мое сердце, но отныне они обрели покой в объятиях богини, а значит – все было к лучшему.$B$BАнде\'торас-этиль, да уменьшатся твои невзгоды.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Корвину Восходу Луны в Аубердинский лагерь беженцев на Темных берегах.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Достань его сущность!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Эферион',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13559,'Подношение Ходиру','Сыны Ходира принимают твое подношение, кроха. Ты не перестаешь доказывать свою ценность как нашего союзника.','Простые подношения не были достойны Ходира, когда он еще обретался среди снежных великанов.$B$BИ пусть с нами его уже нет, мы никогда не оставим традицию подношения даров и всегда будем почитать его силу и мудрость. Ты поддерживаешь наши традиции, и это о многом говорит, крохотный |3-6($C).','Вернитесь к Лиллехоффу в Зул\'Драк.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подношение Ходиру',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сыны Ходира принимают твое подношение, кроха. Ты не перестаешь доказывать свою ценность как нашего союзника.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Простые подношения не были достойны Ходира, когда он еще обретался среди снежных великанов.$B$BИ пусть с нами его уже нет, мы никогда не оставим традицию подношения даров и всегда будем почитать его силу и мудрость. Ты поддерживаешь наши традиции, и это о многом говорит, крохотный |3-6($C).',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лиллехоффу в Зул\'Драк.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (13560,'Океан не столь глубок','О, а ты не робкого десятка, как я погляжу!$B$BСлушай, тут на побережье полно разбившихся кораблей – какие-то совсем новые, какие-то уже давно тиной поросли. Представляешь, сколько там должно быть всяких сокровищ среди обломков? Я вот все думаю – негоже им гнить на берегу, пора найти им другое применение, но моим планам мешает поселение чрезвычайно воинственных мурлоков. Сколько бы я не посылал туда искателей приключений – ни один не вернулся.$B$BДа не пугайся ты так, я с тех пор усвоил урок и не собираюсь отправлять тебя на верную гибель. Тебе надо будет сплавать на север и разыскать моего дружка Гари. Он расскажет тебе, какой у нас есть план. Правда, все просто?','Горбольд Сталерук из Лор\'данела просит вас поговорить с Гари и получить у него дальнейшие указания.','Значит, приманка сработала так, как и было задумано? Вот здорово! А про сокровища не беспокойся – мы с Гари позаботимся о них в ближайшее время.$B$BЧестно говоря, я боялся, что он вышвырнет меня из города, если я угроблю еще одного лихого искателя приключений.','Вернитесь к Горбольду Сталеруку в Лор\'данел.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Океан не столь глубок',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','О, а ты не робкого десятка, как я погляжу!$B$BСлушай, тут на побережье полно разбившихся кораблей – какие-то совсем новые, какие-то уже давно тиной поросли. Представляешь, сколько там должно быть всяких сокровищ среди обломков? Я вот все думаю – негоже им гнить на берегу, пора найти им другое применение, но моим планам мешает поселение чрезвычайно воинственных мурлоков. Сколько бы я не посылал туда искателей приключений – ни один не вернулся.$B$BДа не пугайся ты так, я с тех пор усвоил урок и не собираюсь отправлять тебя на верную гибель. Тебе надо будет сплавать на север и разыскать моего дружка Гари. Он расскажет тебе, какой у нас есть план. Правда, все просто?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Горбольд Сталерук из Лор\'данела просит вас поговорить с Гари и получить у него дальнейшие указания.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Значит, приманка сработала так, как и было задумано? Вот здорово! А про сокровища не беспокойся – мы с Гари позаботимся о них в ближайшее время.$B$BЧестно говоря, я боялся, что он вышвырнет меня из города, если я угроблю еще одного лихого искателя приключений.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Горбольду Сталеруку в Лор\'данел.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13561,'Утешение для высокорожденного','Я прибыла на руины Башал\'Аран, чтобы даровать покой мятущимся душам высокорожденных, но с каждым ударом меча решимость моя слабеет. Если ты можешь помочь мне в этом нелегком деле, благодарность моя не будет иметь границ.','Убейте 6 проклятых высокорожденных и 6 терзаемых высокорожденных.','Вернитесь к Арии Осенний Свет, находящейся на дороге за Башал\'Араном.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Утешение для высокорожденного',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я прибыла на руины Башал\'Аран, чтобы даровать покой мятущимся душам высокорожденных, но с каждым ударом меча решимость моя слабеет. Если ты можешь помочь мне в этом нелегком деле, благодарность моя не будет иметь границ.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 6 проклятых высокорожденных и 6 терзаемых высокорожденных.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Арии Осенний Свет, находящейся на дороге за Башал\'Араном.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`) VALUES (13562,'Последние огни Башал\'Арана','Настало время остановиться и задуматься о нашей жизни. Отныне мы смертные, как бы нам ни хотелось обратного, и мы заслуживаем нового места в этом мире.$B$BЕсли следовать по дороге на юг, можно увидеть руины Башал\'Арана, города, где некогда жили наши предки. Теперь там обитают лишь их проклятые души. Если мы хотим обрести спасение, нельзя позволить им страдать еще дольше. Настало время погасить последние огни Башал\'Арана.','Погасите последний огонь Башал\'Арана.','Прими мою благодарность. Для нас настало время забыть о прошлом и начать смотреть в будущее.','Погасите последние огни Башал\'Арана.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Последние огни Башал\'Арана',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Настало время остановиться и задуматься о нашей жизни. Отныне мы смертные, как бы нам ни хотелось обратного, и мы заслуживаем нового места в этом мире.$B$BЕсли следовать по дороге на юг, можно увидеть руины Башал\'Арана, города, где некогда жили наши предки. Теперь там обитают лишь их проклятые души. Если мы хотим обрести спасение, нельзя позволить им страдать еще дольше. Настало время погасить последние огни Башал\'Арана.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Погасите последний огонь Башал\'Арана.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прими мою благодарность. Для нас настало время забыть о прошлом и начать смотреть в будущее.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Погасите последние огни Башал\'Арана.',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (13563,'Вечная любовь','Освободите душу Анайи Вестницы Зари и добудьте ее подвеску.','Отнесите подвеску Анайи Кириллиану Белому Когтю в Лор\'данел.','Некоторым очень сложно просто отпустить любимого.','Анайя Вестница Зари') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вечная любовь',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Освободите душу Анайи Вестницы Зари и добудьте ее подвеску.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите подвеску Анайи Кириллиану Белому Когтю в Лор\'данел.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Некоторым очень сложно просто отпустить любимого.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Анайя Вестница Зари',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`) VALUES (13564,'Пропавший спутник','Пожалуйста, помоги мне... видишь же, я едва могу подняться на ноги.$B$BМой единственный друг, медведь по имени Лютый Коготь, оставил меня. Я сам отослал его вперед, чтобы предупредить часовых о нашем прибытии из Аубердина, но он так и не вернулся. Я чувствовал, что что-то может пойти не так во время бегства из города... но мне не представился шанс предотвратить беду. $B$BЕсли Лютый Коготь был ранен, он мог отправиться только в одно место – в Увядающую рощу на севере Аубердина. Иди по дороге на юг, и ты непременно его отыщешь. Приведи его назад целым и невредимым... у меня нет друга ближе, чем он.','Найдите Лютого Когтя.','Найдите Лютого Когтя.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пропавший спутник',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пожалуйста, помоги мне... видишь же, я едва могу подняться на ноги.$B$BМой единственный друг, медведь по имени Лютый Коготь, оставил меня. Я сам отослал его вперед, чтобы предупредить часовых о нашем прибытии из Аубердина, но он так и не вернулся. Я чувствовал, что что-то может пойти не так во время бегства из города... но мне не представился шанс предотвратить беду. $B$BЕсли Лютый Коготь был ранен, он мог отправиться только в одно место – в Увядающую рощу на севере Аубердина. Иди по дороге на юг, и ты непременно его отыщешь. Приведи его назад целым и невредимым... у меня нет друга ближе, чем он.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Лютого Когтя.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Найдите Лютого Когтя.',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (13565,'Уничтожить дважды','Не в наших правилах мириться с бессмысленной жестокостью, хотя сейчас настали такие времена, когда уклонение от битвы может принести больше вреда. Я, разумеется, говорю о нагах.$B$BКогда эта земля пошатнулась, на востоке отсюда появились над поверхностью руины древнего дворца. Когда-то в нем обитали верные приспешники королевы Азшары, и теперь их потомки вернулись на это место в поисках чего-то важного.$B$BВозьми этот окаменелый корень: с его помощью ты сможешь призвать на помощь иссохших энтов. Пусть твоя армия уничтожит наг и их предводителя.','Воспользуйтесь окаменелым корнем, чтобы поднять из небытия 6 иссхоших энтов, и убейте предводительницу наг Леди Жаниру.','Спасибо тебе, друг. Мы должны готовиться к их возвращению.','Вернитесь к Серафин в Увядающую рощу.','Наги ищут что-то ценное в руинах Темных берегов, но они злоупотребили гостеприимством ночных эльфов и теперь поплатятся за это.','Леди Жанира') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уничтожить дважды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не в наших правилах мириться с бессмысленной жестокостью, хотя сейчас настали такие времена, когда уклонение от битвы может принести больше вреда. Я, разумеется, говорю о нагах.$B$BКогда эта земля пошатнулась, на востоке отсюда появились над поверхностью руины древнего дворца. Когда-то в нем обитали верные приспешники королевы Азшары, и теперь их потомки вернулись на это место в поисках чего-то важного.$B$BВозьми этот окаменелый корень: с его помощью ты сможешь призвать на помощь иссохших энтов. Пусть твоя армия уничтожит наг и их предводителя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь окаменелым корнем, чтобы поднять из небытия 6 иссхоших энтов, и убейте предводительницу наг Леди Жаниру.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо тебе, друг. Мы должны готовиться к их возвращению.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Серафин в Увядающую рощу.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Наги ищут что-то ценное в руинах Темных берегов, но они злоупотребили гостеприимством ночных эльфов и теперь поплатятся за это.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Леди Жанира',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (13566,'Ингредиенты для ритуала','Пока мы заботимся о Лютом когте, я хочу, чтобы ты тихо-спокойно $gпособирал:пособирала; кое-какие элементы дикой природы для проведения ритуала.$B$BВо-первых, мне потребуются усы лунопардов, обитающих на западе: подкрадись к спящему зверю, выдерни несколько волосков и беги прочь.$B$BЗатем тебе надо будет добыть шерсть оленихи – да смотри, не перепутай с оленем!$B$BИ наконец, мне нужен мех медведей, что рыбачат на северо-востоке. Дождись, когда им в лапы попадется рыба, выдерни клочок меха и убегай, пока они не нашли себе еду получше.$B$BНо прошу тебя, не убивай ни одно живое существо!','Добудьте 3 уса лунопарда, 3 клочка шерсти пятнистой оленихи и 3 клочка меха колючешерстного медведя.','То, что надо! Это были последние ингредиенты, необходимые для проведения ритуала. Подожди, сейчас я тебе все объясню – только смешаю их воедино.','Вернитесь к хранителю Каритию в Увядающую рощу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ингредиенты для ритуала',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пока мы заботимся о Лютом когте, я хочу, чтобы ты тихо-спокойно $gпособирал:пособирала; кое-какие элементы дикой природы для проведения ритуала.$B$BВо-первых, мне потребуются усы лунопардов, обитающих на западе: подкрадись к спящему зверю, выдерни несколько волосков и беги прочь.$B$BЗатем тебе надо будет добыть шерсть оленихи – да смотри, не перепутай с оленем!$B$BИ наконец, мне нужен мех медведей, что рыбачат на северо-востоке. Дождись, когда им в лапы попадется рыба, выдерни клочок меха и убегай, пока они не нашли себе еду получше.$B$BНо прошу тебя, не убивай ни одно живое существо!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 3 уса лунопарда, 3 клочка шерсти пятнистой оленихи и 3 клочка меха колючешерстного медведя.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','То, что надо! Это были последние ингредиенты, необходимые для проведения ритуала. Подожди, сейчас я тебе все объясню – только смешаю их воедино.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к хранителю Каритию в Увядающую рощу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (13569,'Ритуальное грозовое облако','Пока Лютый Коготь отдыхает, я буду сторожить его сон. Очень скоро он вернется к нам, но до тех пор тебе придется выполнить еще одно мое поручение. Надеюсь, ты тоже сочтешь эту миссию почетной.$B$BВокруг нас обитают великие духи дикой природы, которые ждут и надеются, что кто-то сможет помочь им остановить разрушение. Даже сейчас они присутствуют при нашем разговоре, и теперь я могу помочь тебе увидеть их. Поговори с этими духами, выбери одного из них и получи его благословение.','Вдохните эссенцию перед хранителем Каритием и примите благословение одного из великих духов: оленя, колючешерстного медведя или лунопарда.$B$BУчтите, что вы можете получить благословение только одного духа.','Итак, дело сделано. Ты получил благословение духа великого зверя, и я теперь могу завершить для тебя ритуал. Стой спокойно и не двигайся.','Получите благословение великого духа животного.','Вернитесь к хранителю Каритию в Увядающую рощу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ритуальное грозовое облако',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пока Лютый Коготь отдыхает, я буду сторожить его сон. Очень скоро он вернется к нам, но до тех пор тебе придется выполнить еще одно мое поручение. Надеюсь, ты тоже сочтешь эту миссию почетной.$B$BВокруг нас обитают великие духи дикой природы, которые ждут и надеются, что кто-то сможет помочь им остановить разрушение. Даже сейчас они присутствуют при нашем разговоре, и теперь я могу помочь тебе увидеть их. Поговори с этими духами, выбери одного из них и получи его благословение.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вдохните эссенцию перед хранителем Каритием и примите благословение одного из великих духов: оленя, колючешерстного медведя или лунопарда.$B$BУчтите, что вы можете получить благословение только одного духа.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Итак, дело сделано. Ты получил благословение духа великого зверя, и я теперь могу завершить для тебя ритуал. Стой спокойно и не двигайся.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Получите благословение великого духа животного.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к хранителю Каритию в Увядающую рощу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (13570,'Воспоминания об Аубердине') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Воспоминания об Аубердине',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (13571,'Бюро находок Флетчера','Вы чувствуете, как сквозь кислый запах немытого тела пробивается знакомый аромат! Похоже, этот некогда могучий искатель приключений знает толк в кунгалуше.$B$BВсматриваясь в пленника сквозь прутья решетки, вы едва различаете строки рецепта, нацарапанные у него на руке...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бюро находок Флетчера',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы чувствуете, как сквозь кислый запах немытого тела пробивается знакомый аромат! Похоже, этот некогда могучий искатель приключений знает толк в кунгалуше.$B$BВсматриваясь в пленника сквозь прутья решетки, вы едва различаете строки рецепта, нацарапанные у него на руке...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13572,'Жаровни Нефритового Пламени','Сатиры Оскверненного леса стали распространять свою заразу на наших землях. Они послали Шаракса Осквернителя в рощу, которую мы, племена Чернолесья, зовем своим домом.$B$BЭто существо не только отравляет почву, растения и живых существ, но также вкапывает жаровни Нефритового Пламени вокруг всей деревни, чтобы подчинить себе жителей. Чтобы остановить его, недостаточно просто уничтожить жаровни... но старейшина Бролг утверждает, что это может помочь освободить разум наших братьев.','Грен Деримех из логова Чернолесья просит вас уничтожить 8 жаровен Нефритового Пламени.','Вернитесь к Грену Деримеху в Чернолесье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жаровни Нефритового Пламени',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сатиры Оскверненного леса стали распространять свою заразу на наших землях. Они послали Шаракса Осквернителя в рощу, которую мы, племена Чернолесья, зовем своим домом.$B$BЭто существо не только отравляет почву, растения и живых существ, но также вкапывает жаровни Нефритового Пламени вокруг всей деревни, чтобы подчинить себе жителей. Чтобы остановить его, недостаточно просто уничтожить жаровни... но старейшина Бролг утверждает, что это может помочь освободить разум наших братьев.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Грен Деримех из логова Чернолесья просит вас уничтожить 8 жаровен Нефритового Пламени.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Грену Деримеху в Чернолесье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (13573,'Возвращение Малфуриона','Найдите Малфуриона Ярость Бури в Оке Урагана, что к юго-востоку от лагеря беженцев на Темных берегах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение Малфуриона',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Малфуриона Ярость Бури в Оке Урагана, что к юго-востоку от лагеря беженцев на Темных берегах.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (13574,'Peering Into the Vortex (DEPRECATED)','Нельзя тратить ни минуты, |3-6($r)! Стоит мне на мгновение потерять концентрацию, и все Темные Берега рухнут в океан. На то, чтобы удержать землю на месте, уходят все мои силы, так что слушай меня очень внимательно.$B$BВон к тому гиппогрифу привязан магический шар. Направь птицу к вершине вихря и воспользуйся шаром, чтобы заключить в нем частицу окружающей его силы. Только заклинаю тебя, поторопись! Не знаю, на сколько еще меня хватит...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Peering Into the Vortex (DEPRECATED)',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нельзя тратить ни минуты, |3-6($r)! Стоит мне на мгновение потерять концентрацию, и все Темные Берега рухнут в океан. На то, чтобы удержать землю на месте, уходят все мои силы, так что слушай меня очень внимательно.$B$BВон к тому гиппогрифу привязан магический шар. Направь птицу к вершине вихря и воспользуйся шаром, чтобы заключить в нем частицу окружающей его силы. Только заклинаю тебя, поторопись! Не знаю, на сколько еще меня хватит...',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13575,'Эта земля в их крови','Если мы хотим привести в равновесие силы природы, нам потребуется вся помощь, которую мы только можем получить. Я хочу обратиться к фурболгам Чернолесья, которые издавна жили на этой земле.$B$BИх старейшина, шаман Карелап, имеет великую власть над стихиями, и его поддержка была бы неоценимой, если только тебе удастся привлечь его на нашу сторону.','Поговорите со старейшиной Карелапом в Лагере Чернолесья к юго-западу от Ока урагана.','Я очень уважаю великого Малфуриона, но не могу оставить свой народ в беде. Возможно, мы сможем как-то помочь друг другу?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Эта земля в их крови',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если мы хотим привести в равновесие силы природы, нам потребуется вся помощь, которую мы только можем получить. Я хочу обратиться к фурболгам Чернолесья, которые издавна жили на этой земле.$B$BИх старейшина, шаман Карелап, имеет великую власть над стихиями, и его поддержка была бы неоценимой, если только тебе удастся привлечь его на нашу сторону.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите со старейшиной Карелапом в Лагере Чернолесья к юго-западу от Ока урагана.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я очень уважаю великого Малфуриона, но не могу оставить свой народ в беде. Возможно, мы сможем как-то помочь друг другу?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13576,'Взаимная помощь','Сейчас, когда большинство наших братьев ступили на путь безумия или пали жертвой порчи, нам ничего не остается, кроме как откликнуться на твой призыв, |3-6($r). Можешь рассчитывать на нашу помощь... если, конечно, взамен ты поможешь нашему племени.$B$BКак видишь, мои люди не могут справиться с элементалями огня. Уничтожь их и воспользуйся этим тотемом, чтобы развеять пепельные останки.$B$BПусть возвращаются туда, откуда пришли... и неважно, хотят они этого или нет.','Воспользуйтесь успокаивающим тотемом, чтобы поглотить останки 8 вольных духов огня.','Вернитесь к старейшине Карелапу в Лагерь Чернолесья, что на Темных берегах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Взаимная помощь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сейчас, когда большинство наших братьев ступили на путь безумия или пали жертвой порчи, нам ничего не остается, кроме как откликнуться на твой призыв, |3-6($r). Можешь рассчитывать на нашу помощь... если, конечно, взамен ты поможешь нашему племени.$B$BКак видишь, мои люди не могут справиться с элементалями огня. Уничтожь их и воспользуйся этим тотемом, чтобы развеять пепельные останки.$B$BПусть возвращаются туда, откуда пришли... и неважно, хотят они этого или нет.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь успокаивающим тотемом, чтобы поглотить останки 8 вольных духов огня.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старейшине Карелапу в Лагерь Чернолесья, что на Темных берегах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (13577,'Последний совух','Весь облик существа выражает безысходную печаль. Оно смотрит куда-то поверх вас и, кажется, даже не замечает вашего приближения.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Последний совух',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Весь облик существа выражает безысходную печаль. Оно смотрит куда-то поверх вас и, кажется, даже не замечает вашего приближения.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13578,'Прощание с Аруном','<Зверь грустно ухает, поворачиваясь к вам лицом.>$B$BАрум – последний из племени...$B$BДругим не обрести покоя, пока не зажжен погребальный костер. Принеси Аруму перья других... даруй им покой.$B$BТогда Арум поможет тебе.','Добудьте 8 перьев убитых совухов.','Вернитесь к Аруму в Осененную луной берлогу, что на Темных берегах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прощание с Аруном',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Зверь грустно ухает, поворачиваясь к вам лицом.>$B$BАрум – последний из племени...$B$BДругим не обрести покоя, пока не зажжен погребальный костер. Принеси Аруму перья других... даруй им покой.$B$BТогда Арум поможет тебе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 8 перьев убитых совухов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аруму в Осененную луной берлогу, что на Темных берегах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13579,'Защитник Амет\'Арана','Ничто не исцелит землю быстрее, чем жизненная сила ее обитателей. Нам, ночным эльфам, повезло иметь таких союзников, которые не только живут в этих местах, но и являются их частью.$B$BК югу отсюда обитает древо войны, известное под именем Селенн. Давным-давно ему было поручено охранять руины Амет\'Арана. Разыщи его и попроси о помощи.','Поговорите с Селенном на руинах Амет\'Арана.','Если великому Малфуриону понадобилась моя помощь, то долг мой – откликнуться на его зов. Но я не могу оставить эти руины без защиты...$B$BМожет быть, ты поможешь мне исполнить обе мои обязанности?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Защитник Амет\'Арана',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ничто не исцелит землю быстрее, чем жизненная сила ее обитателей. Нам, ночным эльфам, повезло иметь таких союзников, которые не только живут в этих местах, но и являются их частью.$B$BК югу отсюда обитает древо войны, известное под именем Селенн. Давным-давно ему было поручено охранять руины Амет\'Арана. Разыщи его и попроси о помощи.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Селенном на руинах Амет\'Арана.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Если великому Малфуриону понадобилась моя помощь, то долг мой – откликнуться на его зов. Но я не могу оставить эти руины без защиты...$B$BМожет быть, ты поможешь мне исполнить обе мои обязанности?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (13580,'Успокоение стихий','Вернитесь к старейшине Карелапу в Лагерь Чернолесья, что на Темных берегах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Успокоение стихий',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старейшине Карелапу в Лагерь Чернолесья, что на Темных берегах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (13581,'Дар Чернолесья','Хотя результат твоих действий появится не сразу, я знаю, что рано или поздно гнев стихий утихнет, и мой народ сможет дожить до новой битвы.$B$BВы с Малфурионом можете рассчитывать на мою помощь.','Вернитесь к Малфуриону Ярость Бури в Око Урагана.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дар Чернолесья',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хотя результат твоих действий появится не сразу, я знаю, что рано или поздно гнев стихий утихнет, и мой народ сможет дожить до новой битвы.$B$BВы с Малфурионом можете рассчитывать на мою помощь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь к Малфуриону Ярость Бури в Око Урагана.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13582,'Огонь Элуны','Для совершения ритуала нам нужно особенное пламя – пламя Элуны.$B$BК востоку отсюда бродит неприкаянный дух Хору. Хору хранит факел Элуны. Принеси пламя сюда, помоги упокоить духов.$B$BАрум благодарен будет.','Добудьте факел Элуны у Хору Хранителя пламени.','<Арум испускает долгий, протяжный вой.>$B$BНаконец-то мои родичи обретут покой.','Факел у тебя?','Вернитесь к Аруму в Осененную луной берлогу, что на Темных берегах') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Огонь Элуны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Для совершения ритуала нам нужно особенное пламя – пламя Элуны.$B$BК востоку отсюда бродит неприкаянный дух Хору. Хору хранит факел Элуны. Принеси пламя сюда, помоги упокоить духов.$B$BАрум благодарен будет.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте факел Элуны у Хору Хранителя пламени.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Арум испускает долгий, протяжный вой.>$B$BНаконец-то мои родичи обретут покой.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Факел у тебя?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аруму в Осененную луной берлогу, что на Темных берегах',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13583,'Клятва совуха','Дикие совухи следуют пути Элуны. Арум в долгу у тебя.$B$BАрум поможет тебе. Возвращайся к Малфуриону, я скоро присоединюсь к вам.','Вернитесь к Малфуриону Ярость Бури в Око Урагана.','Некогда совухи были хранителями этой земли. Хорошо, что они не забыли обычаи предков.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Клятва совуха',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Дикие совухи следуют пути Элуны. Арум в долгу у тебя.$B$BАрум поможет тебе. Возвращайся к Малфуриону, я скоро присоединюсь к вам.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь к Малфуриону Ярость Бури в Око Урагана.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Некогда совухи были хранителями этой земли. Хорошо, что они не забыли обычаи предков.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (13584,'Колыбельная для Земли','Если я сейчас оставлю пост, это будет прямым нарушением моих обязанностей. Слишком много духов стихий еще бродят по этим руинам...$B$BДавай сначала разберемся с элементалями, а потом посмотрим, чем можно помочь Малфуриону. Что скажешь, $gмалыш:малышка;?','Убейте 8 разъяренных элементалей земли.','Теперь мне все ясно, Арэль. Духи стихий не успокоятся, пока Малфурион не восстановит природный баланс. В таком случае мой долг – помочь ему.','Вернитесь к Селенну на Руины Амет\'Арана на Темных берегах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Колыбельная для Земли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если я сейчас оставлю пост, это будет прямым нарушением моих обязанностей. Слишком много духов стихий еще бродят по этим руинам...$B$BДавай сначала разберемся с элементалями, а потом посмотрим, чем можно помочь Малфуриону. Что скажешь, $gмалыш:малышка;?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 разъяренных элементалей земли.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь мне все ясно, Арэль. Духи стихий не успокоятся, пока Малфурион не восстановит природный баланс. В таком случае мой долг – помочь ему.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Селенну на Руины Амет\'Арана на Темных берегах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (13585,'Клятва защитника','Сначала я должен исполнить свой долг в этом месте. Пожалуйста, скажи Малфуриону, что я присоединюсь к нему, как только смогу.$B$BУдачи тебе, $n. Удачи всем нам.','Поговорите с Малфурионом Яростью Бури в Оке Урагана, что на Темных берегах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Клятва защитника',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сначала я должен исполнить свой долг в этом месте. Пожалуйста, скажи Малфуриону, что я присоединюсь к нему, как только смогу.$B$BУдачи тебе, $n. Удачи всем нам.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Малфурионом Яростью Бури в Оке Урагана, что на Темных берегах.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13586,'Изумрудный Сон','Похоже, наших усилий по предотвращению дальнейшего разрушения земли оказалось недостаточно. Боюсь, нам придется прибегнуть к помощи из потустороннего мира.$B$BСектанты культа Сумеречного Молота открыли проход в населенный кошмарами мир Изумрудного Сна; там они держат в плену зеленого дракона Тессеру.$B$BОтправляйся в портал кошмаров и освободи ее. Она станет нам могущественным союзником.','Пройдите сквозь портал кошмаров в Пещеру землекрушителя и поговорите с Тессерой.','Малфурион призывает меня? Да... я слышу его голос сквозь пелену сна...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Изумрудный Сон',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Похоже, наших усилий по предотвращению дальнейшего разрушения земли оказалось недостаточно. Боюсь, нам придется прибегнуть к помощи из потустороннего мира.$B$BСектанты культа Сумеречного Молота открыли проход в населенный кошмарами мир Изумрудного Сна; там они держат в плену зеленого дракона Тессеру.$B$BОтправляйся в портал кошмаров и освободи ее. Она станет нам могущественным союзником.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Пройдите сквозь портал кошмаров в Пещеру землекрушителя и поговорите с Тессерой.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Малфурион призывает меня? Да... я слышу его голос сквозь пелену сна...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13587,'Ходячий кошмар','Добудьте изумрудный свиток у стража кошмара в Пещере землекрушителя.','Вернитесь к Тессере в Пещеру землекрушителя, что на Темных берегах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ходячий кошмар',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте изумрудный свиток у стража кошмара в Пещере землекрушителя.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тессере в Пещеру землекрушителя, что на Темных берегах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13588,'Око бурь','Небеса над вихрем патрулируют всадники Сумеречного Молота, и я боюсь, что их магия не дает нам укротить разрушительные силы катаклизма.$B$BПусть Тессера поднимет тебя в воздух, чтобы ты $gсмог:смогла; уничтожить всадников и портал, откуда они явились.','Оседлайте Тессеру и убейте 12 наездников из культа Сумеречного Молота, а также уничтожьте сумеречный портал.','Вернитесь к Малфуриону Ярости Бури в Око Урагана, что на Темных берегах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Око бурь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Небеса над вихрем патрулируют всадники Сумеречного Молота, и я боюсь, что их магия не дает нам укротить разрушительные силы катаклизма.$B$BПусть Тессера поднимет тебя в воздух, чтобы ты $gсмог:смогла; уничтожить всадников и портал, откуда они явились.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Оседлайте Тессеру и убейте 12 наездников из культа Сумеречного Молота, а также уничтожьте сумеречный портал.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Малфуриону Ярости Бури в Око Урагана, что на Темных берегах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13589,'Захватчики из племени Пронзающего Копья','Кажется, будто сама земля и все стихии ополчились на нас! Можно подумать, нам было мало этих проблем – так еще и тролли с северо-запада встали на тропу войны. Не знаю, что на них нашло и чего они добиваются, но они уже напали на нескольких разведчиков и осадили служителей культа в Башне Алталакса.$B$BМы послали наших лучших часовых устранить эту угрозу, но им наверняка понадобится помощь. Их отряд можно найти на северо-востоке, возле руин.','Разыщите лейтенанта Морру Звездный Ветер на руинах Матистры.','Это Глинда тебя прислала? Спасибо ей, лишняя пара рук нам пригодится.$B$BЯ разрабатываю первоначальный план нападения на их войско, но ты пока можешь предложить свою помощь Тише и Балтулу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Захватчики из племени Пронзающего Копья',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кажется, будто сама земля и все стихии ополчились на нас! Можно подумать, нам было мало этих проблем – так еще и тролли с северо-запада встали на тропу войны. Не знаю, что на них нашло и чего они добиваются, но они уже напали на нескольких разведчиков и осадили служителей культа в Башне Алталакса.$B$BМы послали наших лучших часовых устранить эту угрозу, но им наверняка понадобится помощь. Их отряд можно найти на северо-востоке, возле руин.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите лейтенанта Морру Звездный Ветер на руинах Матистры.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это Глинда тебя прислала? Спасибо ей, лишняя пара рук нам пригодится.$B$BЯ разрабатываю первоначальный план нападения на их войско, но ты пока можешь предложить свою помощь Тише и Балтулу.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (13590,'Передовая','Их силы на исходе, припасы уничтожены, а помощники командира мертвы. Настало время нанести удар в самое сердце их поселения и уничтожить предводителя. Я все еще не понимаю, что вызвало такую агрессию с их стороны, но возможно мы найдем ответы в их лагере.$B$BВозьми стрелу, которую подготовил Балтул, и присоединись к отряду охотницы Сандрии Закат Луны в долине Пронзающего Копья. Советую тебе поехать на одном из наших ночных саблезубов – дороги нынче небезопасны.','Приятно познакомиться! До меня дошли слухи о той неоценимой помощи, которую ты оказала в борьбе с троллями. Надо сказать, я впечатлена. Но последняя битва еще ждет впереди – надеюсь, ты к ней готова.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Передовая',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Их силы на исходе, припасы уничтожены, а помощники командира мертвы. Настало время нанести удар в самое сердце их поселения и уничтожить предводителя. Я все еще не понимаю, что вызвало такую агрессию с их стороны, но возможно мы найдем ответы в их лагере.$B$BВозьми стрелу, которую подготовил Балтул, и присоединись к отряду охотницы Сандрии Закат Луны в долине Пронзающего Копья. Советую тебе поехать на одном из наших ночных саблезубов – дороги нынче небезопасны.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Приятно познакомиться! До меня дошли слухи о той неоценимой помощи, которую ты оказала в борьбе с троллями. Надо сказать, я впечатлена. Но последняя битва еще ждет впереди – надеюсь, ты к ней готова.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (13591,'Странные совпадения') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Странные совпадения',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13592,'Теория и практика','Турнир – это возможность помериться силой с другими героями, но стоит помнить и о том, что главный враг – Плеть – не дремлет. Ты оттачиваешь мастерство в поединках с товарищами, но тебе столь же необходимо совершенствоваться в битвах с неприятелем.$B$BОтправляйся на юго-запад Долины павших героев, что к северу от Корп\'ретара – там приспешники Плети поднимают из небытия павших героев и обращают их против нас. Окажи честь нашим союзникам и упокой этих слуг Плети, тем самым подготовившись к настоящей битве.','Убейте 10 обращенных героев по заданию сэра Маркуса Барлоу из Павильона Серебряного союза на Ристалище Серебряного турнира.','Ты испытал себя в бою против Плети?','Вернитесь к сэру Маркусу Барлоу на Ристалище Серебряного турнира в Ледяную Корону.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Теория и практика',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Турнир – это возможность помериться силой с другими героями, но стоит помнить и о том, что главный враг – Плеть – не дремлет. Ты оттачиваешь мастерство в поединках с товарищами, но тебе столь же необходимо совершенствоваться в битвах с неприятелем.$B$BОтправляйся на юго-запад Долины павших героев, что к северу от Корп\'ретара – там приспешники Плети поднимают из небытия павших героев и обращают их против нас. Окажи честь нашим союзникам и упокой этих слуг Плети, тем самым подготовившись к настоящей битве.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 обращенных героев по заданию сэра Маркуса Барлоу из Павильона Серебряного союза на Ристалище Серебряного турнира.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты испытал себя в бою против Плети?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к сэру Маркусу Барлоу на Ристалище Серебряного турнира в Ледяную Корону.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13593,'Искатель славы из Штормграда','Приветствую тебя, чемпион. Я наслышан о твоих достижениях! Буду рад включить тебя в число участников делегации Штормграда, если ты желаешь к нам присоединиться.$B$BТы будешь тренироваться и совершенствоваться как прежде, но звание чемпиона Штормграда позволит тебе выступать под нашим флагом.','Если вы хотите стать искателем славы Штормграда, поговорите еще раз с маршалом Якобом Алерием в Павильоне Серебряного союза.','Добро пожаловать, $N. Штормград рад принять тебя в ряды своих воинов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Искатель славы из Штормграда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приветствую тебя, чемпион. Я наслышан о твоих достижениях! Буду рад включить тебя в число участников делегации Штормграда, если ты желаешь к нам присоединиться.$B$BТы будешь тренироваться и совершенствоваться как прежде, но звание чемпиона Штормграда позволит тебе выступать под нашим флагом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Если вы хотите стать искателем славы Штормграда, поговорите еще раз с маршалом Якобом Алерием в Павильоне Серебряного союза.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Добро пожаловать, $N. Штормград рад принять тебя в ряды своих воинов.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (13594,'Не забывайте про Орду','Конечно, от Эвенара и других учеников будет мало толку в бою, чего не скажешь о тебе. Давно пора преподать урок ордынским мерзавцам, которые бродят по дороге к востоку от Убежища Батрана.$B$BИх новый вождь, Гаррош Адский Крик, явно задумал что-то недоброе. Так что, покажешь им, где раки зимуют?$B$BЧестное слово, я бы пошла вместе с тобой, но моя задача – защищать учеников Орендила, поэтому я останусь на месте.','Убейте 10 ордынцев в Убежище Батрана.','<Какое-то время часовой с одобрением смотрит на вас.>$B$BЕще одна работа выполнена с блеском! Если бы на нашей стороне сражались только такие искатели приключений, как ты, мы бы мигом разделались с Ордой!','Вернитесь к часовому Шейле в Укрытие Орендила, что в Ясеневом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Не забывайте про Орду',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Конечно, от Эвенара и других учеников будет мало толку в бою, чего не скажешь о тебе. Давно пора преподать урок ордынским мерзавцам, которые бродят по дороге к востоку от Убежища Батрана.$B$BИх новый вождь, Гаррош Адский Крик, явно задумал что-то недоброе. Так что, покажешь им, где раки зимуют?$B$BЧестное слово, я бы пошла вместе с тобой, но моя задача – защищать учеников Орендила, поэтому я останусь на месте.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 ордынцев в Убежище Батрана.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Какое-то время часовой с одобрением смотрит на вас.>$B$BЕще одна работа выполнена с блеском! Если бы на нашей стороне сражались только такие искатели приключений, как ты, мы бы мигом разделались с Ордой!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к часовому Шейле в Укрытие Орендила, что в Ясеневом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13595,'Ни пряди волос','Эти твари, называющие себя ордынцами... они срезали меня в самом расцвете сил, и теперь добывают мои волосы для своих зловещих планов.$B$BТы $Gдолжен:должна; положить этому конец, $gмаленький:маленькая:r; |3-6($r)!$B$BЯ слышал, как их травники говорили о некоем буйном огне, стоящем на их столах. Если ты сможешь выкрасть бутылку огня и сжечь этим бесовским зельем мой труп, они не получат больше ни пряди моих волос!$B$BЯ уже мертв, так что могу заплатить столь невысокую цену за возможность остановить моих мучителей.','Бросьте бутыль буйного огня на тело Батрана и сожгите его.','Вернитесь к Батрану в его Убежище Батрана, что в Ясеневом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ни пряди волос',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти твари, называющие себя ордынцами... они срезали меня в самом расцвете сил, и теперь добывают мои волосы для своих зловещих планов.$B$BТы $Gдолжен:должна; положить этому конец, $gмаленький:маленькая:r; |3-6($r)!$B$BЯ слышал, как их травники говорили о некоем буйном огне, стоящем на их столах. Если ты сможешь выкрасть бутылку огня и сжечь этим бесовским зельем мой труп, они не получат больше ни пряди моих волос!$B$BЯ уже мертв, так что могу заплатить столь невысокую цену за возможность остановить моих мучителей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Бросьте бутыль буйного огня на тело Батрана и сожгите его.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Батрану в его Убежище Батрана, что в Ясеневом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13596,'Планы Сумеречного Молота','Мы не знаем, какую цель преследуют последователи культа Сумеречного Молота на юго-западе, но я боюсь, что они осмелятся напасть на Лор\'данел – а то и совершить что-нибудь похуже.$B$BПослушай, отправляйся в лагерь Сумеречного Молота и раздобудь их военные планы. И поторопись, ради всего святого – возможно, у нас осталось не так уж много времени.','Добудьте 6 планов Сумеречного Молота из их лагеря.','Вернитесь к часовому Лендре в Лор\'данел, что на Темных берегах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Планы Сумеречного Молота',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы не знаем, какую цель преследуют последователи культа Сумеречного Молота на юго-западе, но я боюсь, что они осмелятся напасть на Лор\'данел – а то и совершить что-нибудь похуже.$B$BПослушай, отправляйся в лагерь Сумеречного Молота и раздобудь их военные планы. И поторопись, ради всего святого – возможно, у нас осталось не так уж много времени.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 6 планов Сумеречного Молота из их лагеря.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к часовому Лендре в Лор\'данел, что на Темных берегах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13598,'Горькое лекарство','Разыщите 6 дымных поганок.','Прими мою благодарность, малыш. С помощью этой мази Лютый Коготь гораздо быстрее встанет на ноги.','Лютый Коготь – великий воин. Не завидую я этим браконьерам, напавшим на него.','Вернитесь к хранителю Каритию в Увядающую рощу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Горькое лекарство',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите 6 дымных поганок.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прими мою благодарность, малыш. С помощью этой мази Лютый Коготь гораздо быстрее встанет на ноги.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Лютый Коготь – великий воин. Не завидую я этим браконьерам, напавшим на него.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к хранителю Каритию в Увядающую рощу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13599,'Возвращение Лютого Когтя','Итак, все ингредиенты собраны, благословение получено. Теперь тебе будет значительно проще путешествовать по этим дорогам.$B$BЧто же до Лютого Когтя, то он полностью оправился от ран и устремился в Лор\'данел прежде, чем я смог его остановить. Полагаю, это значит, что и тебе пора отправиться в путь.$B$BМне было очень приятно познакомиться с тобой. Передавай привет Волкору и Лютому Когтю.','Вернитесь к Волкору и Лютому Когтю в Лор\'данел.','Ты вернулся! Рада видеть тебя снова. Полагаю, это тебя нам стоит благодарить за спасение Лютого Когтя?$B$BУвы, у меня для тебя плохие новости. Мне не удалось нейтрализовать яд, и их состояние резко ухудшилось... Гершалла умерла вскоре после твоего ухода, а Волкор... Волкор чуть-чуть тебя не дождался.$B$BНо он успел узнать о возвращении Лютого Когтя, так что он умер с улыбкой на устах. Прости, что я не смогла ему помочь.$B$BА сейчас извини меня – я все еще не теряю надежды спасти Шалдин.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение Лютого Когтя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Итак, все ингредиенты собраны, благословение получено. Теперь тебе будет значительно проще путешествовать по этим дорогам.$B$BЧто же до Лютого Когтя, то он полностью оправился от ран и устремился в Лор\'данел прежде, чем я смог его остановить. Полагаю, это значит, что и тебе пора отправиться в путь.$B$BМне было очень приятно познакомиться с тобой. Передавай привет Волкору и Лютому Когтю.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь к Волкору и Лютому Когтю в Лор\'данел.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты вернулся! Рада видеть тебя снова. Полагаю, это тебя нам стоит благодарить за спасение Лютого Когтя?$B$BУвы, у меня для тебя плохие новости. Мне не удалось нейтрализовать яд, и их состояние резко ухудшилось... Гершалла умерла вскоре после твоего ухода, а Волкор... Волкор чуть-чуть тебя не дождался.$B$BНо он успел узнать о возвращении Лютого Когтя, так что он умер с улыбкой на устах. Прости, что я не смогла ему помочь.$B$BА сейчас извини меня – я все еще не теряю надежды спасти Шалдин.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (13600,'Достойное оружие','Что за невезение!$B$BМой турнирный клинок куда-то делся, а сражение должно состояться сегодня днем!$B$BОдин бард рассказал мне, что некая дева дарит путникам ценные вещицы в обмен на букетик зимних гиацинтов. Эти цветы растут только на льду, идущем вниз по реке от Железной плотины, на северо-западе от границы между Ледяной Короной и лесом Хрустальной Песни. Собери цветы и отнеси их к озеру Драк\'Мар, оно расположено в северо-восточной части Драконьего Погоста, почти на границе с Зул\'Драком и Седыми холмами. И попроси у девы хороший клинок.','Принесите меч Драк\'Мара маршалу Якобу Алерию в Павильон Серебряного союза на Ристалище Серебряного турнира.','<Маршал принимает у вас меч Драк\'мара.>$B$BПрекрасное оружие, отлично сбалансировано... этот клинок сослужит мне добрую службу в следующем поединке.','Вернитесь к маршалу Якобу Алерию на Ристалище Серебряного турнира в Ледяную Корону.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Достойное оружие',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что за невезение!$B$BМой турнирный клинок куда-то делся, а сражение должно состояться сегодня днем!$B$BОдин бард рассказал мне, что некая дева дарит путникам ценные вещицы в обмен на букетик зимних гиацинтов. Эти цветы растут только на льду, идущем вниз по реке от Железной плотины, на северо-западе от границы между Ледяной Короной и лесом Хрустальной Песни. Собери цветы и отнеси их к озеру Драк\'Мар, оно расположено в северо-восточной части Драконьего Погоста, почти на границе с Зул\'Драком и Седыми холмами. И попроси у девы хороший клинок.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите меч Драк\'Мара маршалу Якобу Алерию в Павильон Серебряного союза на Ристалище Серебряного турнира.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Маршал принимает у вас меч Драк\'мара.>$B$BПрекрасное оружие, отлично сбалансировано... этот клинок сослужит мне добрую службу в следующем поединке.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к маршалу Якобу Алерию на Ристалище Серебряного турнира в Ледяную Корону.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (13601,'На помощь беженцам','Во имя Элуны! Люди, которых мы считали погибшими при нападении на старый Аубердин, смогли избежать смерти и укрылись в лагере за руинами города.$B$BНо последователи культа Сумеречного Молота узнали, где они прячутся, и намереваются разделаться с выжившими. Нам повезло, что твоя атака отвлекла их от этого замысла.$B$BПожалуйста, как можно скорее разыщи жрицу Алинию в Лагере беженцев. Его точное местоположение – на востоке от старого Аубердина и далеко на юге отсюда.','Часовой Лендра из Лор\'данела просит вас поговорить с жрицей Алинией в Лагере беженцев.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На помощь беженцам',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Во имя Элуны! Люди, которых мы считали погибшими при нападении на старый Аубердин, смогли избежать смерти и укрылись в лагере за руинами города.$B$BНо последователи культа Сумеречного Молота узнали, где они прячутся, и намереваются разделаться с выжившими. Нам повезло, что твоя атака отвлекла их от этого замысла.$B$BПожалуйста, как можно скорее разыщи жрицу Алинию в Лагере беженцев. Его точное местоположение – на востоке от старого Аубердина и далеко на юге отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Часовой Лендра из Лор\'данела просит вас поговорить с жрицей Алинией в Лагере беженцев.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13602,'Наги Зорамского взморья','Зло обитает на западном побережье, $n.$B$BДавным-давно на Зорамском взморье стоял проклятый город Зорам, павший во время Раскола мира, и руины его поглотило море. Так он был потерян для ночных эльфов, и мало кто помнит о его существовании.$B$BТеперь наги вернулись, и мы не знаем, зачем они пришли. Но причины не столь важны; важно то, что надо сделать – убить этих демонов и сбросить их тела в пучину, из которой они вышли!','Убейте 15 наг из клана Зловещего Хвоста на Зорамском взморье.','Вернитесь к Шиндрелл Огненный Всполох в лагерь у Непроглядной Пучины, что в Ясеневом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наги Зорамского взморья',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Зло обитает на западном побережье, $n.$B$BДавным-давно на Зорамском взморье стоял проклятый город Зорам, павший во время Раскола мира, и руины его поглотило море. Так он был потерян для ночных эльфов, и мало кто помнит о его существовании.$B$BТеперь наги вернулись, и мы не знаем, зачем они пришли. Но причины не столь важны; важно то, что надо сделать – убить этих демонов и сбросить их тела в пучину, из которой они вышли!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 15 наг из клана Зловещего Хвоста на Зорамском взморье.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Шиндрелл Огненный Всполох в лагерь у Непроглядной Пучины, что в Ясеневом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (13603,'Клинок, достойный чемпиона','Честно выкованные клинки нынче не в моде. Все мои соперники обзавелись заколдованными мечами, где мне с ними тягаться. Однако не все еще потеряно.$B$BДревняя легенда рассказывает о девушке, живущей в Седых холмах, у которой есть замечательный волшебный меч... Но вот незадача, ее превратили в лягушку, чтобы никто не смог заполучить этот клинок. Теперь она живет среди лягушек на Ясеневом озере, что к востоку от Ясеневой заставы. Говорят, что чары может развеять только поцелуй. Только не забудь воспользоваться этим бальзамом для губ – иначе покроешься бородавками.','Вернитесь к маршалу Якобу Алерию на Ристалище Серебряного турнира в Ледяную Корону.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Клинок, достойный чемпиона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Честно выкованные клинки нынче не в моде. Все мои соперники обзавелись заколдованными мечами, где мне с ними тягаться. Однако не все еще потеряно.$B$BДревняя легенда рассказывает о девушке, живущей в Седых холмах, у которой есть замечательный волшебный меч... Но вот незадача, ее превратили в лягушку, чтобы никто не смог заполучить этот клинок. Теперь она живет среди лягушек на Ясеневом озере, что к востоку от Ясеневой заставы. Говорят, что чары может развеять только поцелуй. Только не забудь воспользоваться этим бальзамом для губ – иначе покроешься бородавками.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к маршалу Якобу Алерию на Ристалище Серебряного турнира в Ледяную Корону.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13604,'Диск доступа к Архиву','Платиновый диск правильной формы выглядит совершенно новым – на нем нет ни единой царапины. По краю его выгравирована руническая надпись: "АРХИВ".$B$BДолжно быть, в глубинах Ульдуара есть устройство, с помощью которого можно прочитать этот диск.','Отнесите диск доступа к Архиву к панели управления Архивом в Ульдуаре.','Платиновый диск идеально подходит к гнезду на панели. Он начинает вращаться, белые лучи считывают с него какую-то информацию.','Гнездо приемника открывается, а панель управления жужжит и вибрирует.','Вернитесь к панели управления Архивом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Диск доступа к Архиву',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Платиновый диск правильной формы выглядит совершенно новым – на нем нет ни единой царапины. По краю его выгравирована руническая надпись: "АРХИВ".$B$BДолжно быть, в глубинах Ульдуара есть устройство, с помощью которого можно прочитать этот диск.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите диск доступа к Архиву к панели управления Архивом в Ульдуаре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Платиновый диск идеально подходит к гнезду на панели. Он начинает вращаться, белые лучи считывают с него какую-то информацию.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Гнездо приемника открывается, а панель управления жужжит и вибрирует.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к панели управления Архивом.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (13605,'Последний выживший','Земля содрогнулась... и все почернело у меня перед глазами. Я очнулась уже здесь, закованной в цепи, и вокруг было полно духов воздуха!$B$BЧто же произошло, хотелось бы мне знать? Надеюсь, эти мерзавцы-сектанты Сумеречного Молота не тронули моих друзей!$B$BА ты, |3-6($c), не стой столбом, возьми какой-нибудь ломик и разбей эту проклятую цепь. Вместе мы сможем добраться до лагеря беженцев.','Сопроводите археолога Холли в безопасное место.','Археолог Холли в безопасности.','Поговорите с Элизой Сталерукой в Аубердинском лагере беженцев, что на Темных берегах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Последний выживший',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Земля содрогнулась... и все почернело у меня перед глазами. Я очнулась уже здесь, закованной в цепи, и вокруг было полно духов воздуха!$B$BЧто же произошло, хотелось бы мне знать? Надеюсь, эти мерзавцы-сектанты Сумеречного Молота не тронули моих друзей!$B$BА ты, |3-6($c), не стой столбом, возьми какой-нибудь ломик и разбей эту проклятую цепь. Вместе мы сможем добраться до лагеря беженцев.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сопроводите археолога Холли в безопасное место.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Археолог Холли в безопасности.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Элизой Сталерукой в Аубердинском лагере беженцев, что на Темных берегах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13606,'Печать Фрейи','Добудьте печать Фрейи по заданию геолога Дорена.$B$BЗа дополнительными сведениями обратитесь к панели управления Архивом.','$GМолодчина:Умница;, $N! Мы уже на шаг ближе к спасению Азерота!','Ты $Gдобыл:добыла; печать Фрейи, $N?','Вернитесь к геологу Дорену в Ульдуар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Печать Фрейи',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте печать Фрейи по заданию геолога Дорена.$B$BЗа дополнительными сведениями обратитесь к панели управления Архивом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','$GМолодчина:Умница;, $N! Мы уже на шаг ближе к спасению Азерота!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gдобыл:добыла; печать Фрейи, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к геологу Дорену в Ульдуар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (13607,'Священный планетарий','Слушай внимательно! На кону – судьба всего Азерота.$B$BТолько одно спасет нас – нужно найти Священный планетарий и помешать этому Алгалону отправить сообщение его повелителям-титанам.$B$BОтыщи Священный планетарий и возвращайся со всеми данными, которые сможешь там собрать. Может быть, мы успеем подготовиться к прибытию Алгалона.','Найдите Священный планетарий по заданию геолога Дорена из Архива в Ульдуаре.','Закрыт? Так я и думал!$B$BДавай-ка посмотрим, что расскажет нам эта куча металлолома...','Вход в Священный планетарий найден','Вернитесь к геологу Дорену в Ульдуар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Священный планетарий',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слушай внимательно! На кону – судьба всего Азерота.$B$BТолько одно спасет нас – нужно найти Священный планетарий и помешать этому Алгалону отправить сообщение его повелителям-титанам.$B$BОтыщи Священный планетарий и возвращайся со всеми данными, которые сможешь там собрать. Может быть, мы успеем подготовиться к прибытию Алгалона.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Священный планетарий по заданию геолога Дорена из Архива в Ульдуаре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Закрыт? Так я и думал!$B$BДавай-ка посмотрим, что расскажет нам эта куча металлолома...',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Вход в Священный планетарий найден',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к геологу Дорену в Ульдуар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`) VALUES (13608,'На прогулку','Привет, |3-6($c)! Что-то я тебя раньше не видела. Ты здесь недавно?$B$BРассказать тебе, что тут у нас происходит, или ты хочешь увидеть все своими глазами? Одна из часовых скоро вылетает на разведку. Лети вместе с ней, я настаиваю. А на обратном пути принесешь мне ее доклад.$B$BОкликни меня, как будешь $Gготов:готова; лететь.','Стрелок Глинда Нал\'Шия из Лор\'данела поручила вам присоединиться к разведывательной миссии. Поговорите с ней, когда будете готовы к вылету.','Разведывательная миссия завершена.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На прогулку',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Привет, |3-6($c)! Что-то я тебя раньше не видела. Ты здесь недавно?$B$BРассказать тебе, что тут у нас происходит, или ты хочешь увидеть все своими глазами? Одна из часовых скоро вылетает на разведку. Лети вместе с ней, я настаиваю. А на обратном пути принесешь мне ее доклад.$B$BОкликни меня, как будешь $Gготов:готова; лететь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Стрелок Глинда Нал\'Шия из Лор\'данела поручила вам присоединиться к разведывательной миссии. Поговорите с ней, когда будете готовы к вылету.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Разведывательная миссия завершена.',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13609,'Печать Ходира','Печать Ходира будет нелегко раздобыть. Во-первых, тебе придется одолеть самого Ходира. А во-вторых, одолеть его нужно до того, как он уничтожит сундук с печатью!$B$BВоспользуйся панелью управления Архивом, чтобы получить дополнительные сведения. Эта премудрая штуковина стоит всех библиотек мира!','Добудьте печать Ходира по заданию геолога Дорена.$B$BЗа дополнительными сведениями обратитесь к панели управления Архивом.','Потрясающе! Не знаю, как ты это $Gсделал:сделала;, но тебе это удалось!','Ну что, $N, где печать?','Вернитесь к геологу Дорену в Ульдуар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Печать Ходира',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Печать Ходира будет нелегко раздобыть. Во-первых, тебе придется одолеть самого Ходира. А во-вторых, одолеть его нужно до того, как он уничтожит сундук с печатью!$B$BВоспользуйся панелью управления Архивом, чтобы получить дополнительные сведения. Эта премудрая штуковина стоит всех библиотек мира!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте печать Ходира по заданию геолога Дорена.$B$BЗа дополнительными сведениями обратитесь к панели управления Архивом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Потрясающе! Не знаю, как ты это $Gсделал:сделала;, но тебе это удалось!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, $N, где печать?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к геологу Дорену в Ульдуар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13610,'Печать Торима','Торим не в себе, $n. Он во власти темных сил.$B$BТемная сущность приняла обличье его погибшей жены, Сиф.$B$BНельзя позволить иллюзии свести его с ума. Если это случится, то мы никогда не сможем найти печать Торима!$B$BВразуми его, и побыстрее.$B$BКак обычно, за подробностями этой жуткой истории можешь обратиться к панели управления Архивом... но они вряд ли тебе понравятся.','Добудьте печать Торима по заданию геолога Дорена.$B$BЗа дополнительными сведениями обратитесь к панели управления Архивом.','Ты не прекращаешь удивлять меня, $N.$B$BДавай выпьем по кружечке после того, как все это закончится!','Итак, $N... Ты заполучил это?','Вернитесь к геологу Дорену в Ульдуар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Печать Торима',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Торим не в себе, $n. Он во власти темных сил.$B$BТемная сущность приняла обличье его погибшей жены, Сиф.$B$BНельзя позволить иллюзии свести его с ума. Если это случится, то мы никогда не сможем найти печать Торима!$B$BВразуми его, и побыстрее.$B$BКак обычно, за подробностями этой жуткой истории можешь обратиться к панели управления Архивом... но они вряд ли тебе понравятся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте печать Торима по заданию геолога Дорена.$B$BЗа дополнительными сведениями обратитесь к панели управления Архивом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты не прекращаешь удивлять меня, $N.$B$BДавай выпьем по кружечке после того, как все это закончится!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Итак, $N... Ты заполучил это?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к геологу Дорену в Ульдуар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13611,'Печать Мимирона','Мимирон хитер – в его комнате установлен какой-то механизм самоуничтожения.$B$BЕсли хочешь получить его печать, тебе придется победить его до того, как механизм завершит свой цикл. Если тебе нужно больше информации – воспользуйся панелью управления Архивом.','Добудьте печать Мимирона по заданию геолога Дорена.$B$BЗа дополнительными сведениями обратитесь к панели управления Архивом.','Надо отдать тебе должное, $N. Шансы у нас неважные, но я чувствую себя гораздо увереннее с тех пор, как ты сражаешься на моей стороне.','Ну что, $N, где печать?','Вернитесь к геологу Дорену в Ульдуар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Печать Мимирона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мимирон хитер – в его комнате установлен какой-то механизм самоуничтожения.$B$BЕсли хочешь получить его печать, тебе придется победить его до того, как механизм завершит свой цикл. Если тебе нужно больше информации – воспользуйся панелью управления Архивом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте печать Мимирона по заданию геолога Дорена.$B$BЗа дополнительными сведениями обратитесь к панели управления Архивом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Надо отдать тебе должное, $N. Шансы у нас неважные, но я чувствую себя гораздо увереннее с тех пор, как ты сражаешься на моей стороне.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, $N, где печать?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к геологу Дорену в Ульдуар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13612,'Защита лагеря Мор\'Шан','Лок\'тар, |3-6($r).$b$bНаконец-то мы перешли в наступление, и вскоре весь Ясеневый лес окажется во власти Орды.$b$bКак мы и ожидали, переход к агрессии заставил противника испытывать нашу защиту на каждом рубеже.$b$bНо здесь, в лагере Мор\'шан, их атака захлебнулась. Мы продолжим зажимать их в тиски, но я предвижу, что они окажут жестокое сопротивление.$b$bЯ поручаю тебе, |3-6($c), провести разведку и обнаружить всех выживших ночных эльфов. Надо устранить их прежде, чем они подготовят новое нападение!','Кадрак с заставы Мор\'шан поручил вам убить 5 застрельщиков Ясеневого леса и 5 стрелков Ясеневого леса.','Поговорите с Кадраком на заставе Мор\'шан,.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Защита лагеря Мор\'Шан',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Лок\'тар, |3-6($r).$b$bНаконец-то мы перешли в наступление, и вскоре весь Ясеневый лес окажется во власти Орды.$b$bКак мы и ожидали, переход к агрессии заставил противника испытывать нашу защиту на каждом рубеже.$b$bНо здесь, в лагере Мор\'шан, их атака захлебнулась. Мы продолжим зажимать их в тиски, но я предвижу, что они окажут жестокое сопротивление.$b$bЯ поручаю тебе, |3-6($c), провести разведку и обнаружить всех выживших ночных эльфов. Надо устранить их прежде, чем они подготовят новое нападение!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Кадрак с заставы Мор\'шан поручил вам убить 5 застрельщиков Ясеневого леса и 5 стрелков Ясеневого леса.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Кадраком на заставе Мор\'шан,.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13613,'Спасение павших','Наши войска отважно сражаются, |3-6($c).$b$bНо на поле битвы осталось много раненых, которые не могут вернуться в лагерь.$b$bЯ создала целебную мазь, которая придаст сил пострадавшим и поможет им добраться до бастиона, где им окажут помощь. Прошу тебя, передай этот бальзам тем, кто в нем нуждается.','Исцелите врачебным зельем 5 раненых защитников заставы Мор\'шан.','Поговорите с Диной на заставе Мор\'шан.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спасение павших',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наши войска отважно сражаются, |3-6($c).$b$bНо на поле битвы осталось много раненых, которые не могут вернуться в лагерь.$b$bЯ создала целебную мазь, которая придаст сил пострадавшим и поможет им добраться до бастиона, где им окажут помощь. Прошу тебя, передай этот бальзам тем, кто в нем нуждается.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Исцелите врачебным зельем 5 раненых защитников заставы Мор\'шан.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Диной на заставе Мор\'шан.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13614,'Алгалон','Ты $gсправился:справилась;, $n. Теперь возьми печати, отнеси их к панели управления Архивом и попытайся получить доступ к Священному планетарию.$B$BПоторопись, $gдруг:подруга; – дорога каждая секунда.','Принесите печати хранителей к панели управления Архивом в Ульдуаре.','Ожидайте подтверждения.$B$BДоступ в Священный планетарий разрешен. Пожалуйста, возьмите ключ.','Яркие лучи панели периодически освещают стеклянную поверхность, как будто ожидают ввода данных.','Вернитесь к панели управления Архивом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Алгалон',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gсправился:справилась;, $n. Теперь возьми печати, отнеси их к панели управления Архивом и попытайся получить доступ к Священному планетарию.$B$BПоторопись, $gдруг:подруга; – дорога каждая секунда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите печати хранителей к панели управления Архивом в Ульдуаре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ожидайте подтверждения.$B$BДоступ в Священный планетарий разрешен. Пожалуйста, возьмите ключ.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Яркие лучи панели периодически освещают стеклянную поверхность, как будто ожидают ввода данных.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к панели управления Архивом.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (13615,'Пустой колчан','Труун с заставы Мор\'шан поручил вам собрать 10 исправных стрел вокруг Зеркала Небес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пустой колчан',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Труун с заставы Мор\'шан поручил вам собрать 10 исправных стрел вокруг Зеркала Небес.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13616,'Клинок Зимы','Маршал Якоб Алерий из Павильона Серебряного союза на Ристалище Серебряного турнира просит вас принести Клинок Зимы.','Ну как? Получилось добыть меч?','Вернитесь к маршалу Якобу Алерию на Ристалище Серебряного турнира в Ледяную Корону.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Клинок Зимы',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Маршал Якоб Алерий из Павильона Серебряного союза на Ристалище Серебряного турнира просит вас принести Клинок Зимы.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как? Получилось добыть меч?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к маршалу Якобу Алерию на Ристалище Серебряного турнира в Ледяную Корону.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (13617,'К западу от Пучины','$n, у меня есть друг, который мог бы найти применение твоим талантам. Его зовут Тален, и он вроде как археолог. Недавно его вниманием завладел поднявшийся со дна морского древний город Зорам и его сокровища.$B$BЕсли хочешь помочь моему другу, ищи его в лагере у Непроглядной Пучины, что на западе вдоль этой дороги.','Поговорите с Таленом в лагере у Непроглядной Пучины в Ясеневом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','К западу от Пучины',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, у меня есть друг, который мог бы найти применение твоим талантам. Его зовут Тален, и он вроде как археолог. Недавно его вниманием завладел поднявшийся со дна морского древний город Зорам и его сокровища.$B$BЕсли хочешь помочь моему другу, ищи его в лагере у Непроглядной Пучины, что на западе вдоль этой дороги.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Таленом в лагере у Непроглядной Пучины в Ясеневом лесу.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (13618,'Найти Гората!','Горат – один из лучших наемных убийц Орды. Одно его имя вселяет страх в сердца отважных героев Альянса, ибо многие уже пали от его руки.$b$bОн самый надежный и преданный наш союзник, который до последнего времени мог похвастаться исключительной пунктуальностью.$b$bЯ чувствую, что с ним что-то случилось. Я бы сам занялся этим делом, но мое присутствие здесь необходимо. У меня нет другого выбора, кроме как обратиться к тебе за помощью.$b$bПоследним заданием Гората было найти и уничтожить эльфа, ответственного за нападение на бастионы.$b$bОн должен быть где-то в районе Зеркала Небес.$b$bНайди его!','Кадрак с заставы Мор\'шан попросил вас обойти Зеркало Небес в поисках Гората.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Найти Гората!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Горат – один из лучших наемных убийц Орды. Одно его имя вселяет страх в сердца отважных героев Альянса, ибо многие уже пали от его руки.$b$bОн самый надежный и преданный наш союзник, который до последнего времени мог похвастаться исключительной пунктуальностью.$b$bЯ чувствую, что с ним что-то случилось. Я бы сам занялся этим делом, но мое присутствие здесь необходимо. У меня нет другого выбора, кроме как обратиться к тебе за помощью.$b$bПоследним заданием Гората было найти и уничтожить эльфа, ответственного за нападение на бастионы.$b$bОн должен быть где-то в районе Зеркала Небес.$b$bНайди его!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Кадрак с заставы Мор\'шан попросил вас обойти Зеркало Небес в поисках Гората.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13619,'Последний отчет','<Горат пытается приподняться, и тут же заходится тяжелым кашлем.>$b$bЯ попал... в засаду...$b$bМы... возвращались в бастион... все... погибли...$b$bИх предводитель... мы нашли его...$b$b<Морщась от боли, Горат наполняет пузырек своей кровью, струящейся из раны.>$b$bМои люди... должны быть отомщены... Отнеси это... Кадраку...$b$bОн знает, что делать...$b$b<Горат испускает последний вздох.>','Горат попросил вас отнести пузырек с его кровью Кадраку на заставу Мор\'шан.','<Кадрак внимательно выслушивает последние слова Гората.>$B$BИменно этого я и боялся. Надеюсь, когда-нибудь он сможет упокоиться с миром.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Последний отчет',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Горат пытается приподняться, и тут же заходится тяжелым кашлем.>$b$bЯ попал... в засаду...$b$bМы... возвращались в бастион... все... погибли...$b$bИх предводитель... мы нашли его...$b$b<Морщась от боли, Горат наполняет пузырек своей кровью, струящейся из раны.>$b$bМои люди... должны быть отомщены... Отнеси это... Кадраку...$b$bОн знает, что делать...$b$b<Горат испускает последний вздох.>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Горат попросил вас отнести пузырек с его кровью Кадраку на заставу Мор\'шан.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Кадрак внимательно выслушивает последние слова Гората.>$B$BИменно этого я и боялся. Надеюсь, когда-нибудь он сможет упокоиться с миром.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (13620,'Наконец-то, к Дине!','Орда не знала более преданного союзника, чем Горат. Он ни разу не подводил нас, и даже смерть не может помешать ему выполнить задание.$b$bОн не зря попросил тебя принести этот флакон. Его следует немедленно доставить Дине, дочери нашего почтенного шамана – и поверь мне, она гораздо более могущественная, чем кажется. Поторопись, пока еще не поздно!','Кадрак просит вас отнести пузырек с кровью Гората Дине на заставу Мор\'шан.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наконец-то, к Дине!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Орда не знала более преданного союзника, чем Горат. Он ни разу не подводил нас, и даже смерть не может помешать ему выполнить задание.$b$bОн не зря попросил тебя принести этот флакон. Его следует немедленно доставить Дине, дочери нашего почтенного шамана – и поверь мне, она гораздо более могущественная, чем кажется. Поторопись, пока еще не поздно!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Кадрак просит вас отнести пузырек с кровью Гората Дине на заставу Мор\'шан.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13621,'Месть Гората','Удача сопутствует нам сегодня, |3-6($r).$b$bКровь Гората оказалась достаточно свежей для проведения особого ритуала, суть которого я постигла еще в детстве.$b$bПриготовься, |3-6($c).$b$bТебе предстоит пролить эту зачарованную кровь на тело Гората, чтобы призвать его неупокоенный дух обратно. Выслушай его внимательно и сделай все, о чем он тебя попросит, после чего возвращайся сюда, к Кадраку.$b$bИ да хранят тебя стихии, $gдруг:подруга;.','Окропите тело Гората его густой кровью и убейте капитана Элендилада.','Поговорите с Кадраком в лагере Мор\'шан.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Месть Гората',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Удача сопутствует нам сегодня, |3-6($r).$b$bКровь Гората оказалась достаточно свежей для проведения особого ритуала, суть которого я постигла еще в детстве.$b$bПриготовься, |3-6($c).$b$bТебе предстоит пролить эту зачарованную кровь на тело Гората, чтобы призвать его неупокоенный дух обратно. Выслушай его внимательно и сделай все, о чем он тебя попросит, после чего возвращайся сюда, к Кадраку.$b$bИ да хранят тебя стихии, $gдруг:подруга;.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Окропите тело Гората его густой кровью и убейте капитана Элендилада.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Кадраком в лагере Мор\'шан.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13622,'Древняя история','Из кусочков вам удается сложить прекрасный боевой молот. Сразу заметно, что к созданию молота приложили руку титаны.$B$BПанель управления в Архиве наверняка содержит немало интересных сведений об этом оружии.','Принесите расколотый Вал\'анир к панели управления в Архив Ульдуара.','Идет анализ фрагментов... пожалуйста, подождите.','Ожидание ввода.','Вернитесь к панели управления Архивом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Древняя история',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Из кусочков вам удается сложить прекрасный боевой молот. Сразу заметно, что к созданию молота приложили руку титаны.$B$BПанель управления в Архиве наверняка содержит немало интересных сведений об этом оружии.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите расколотый Вал\'анир к панели управления в Архив Ульдуара.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Идет анализ фрагментов... пожалуйста, подождите.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ожидание ввода.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к панели управления Архивом.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (13623,'Посылка для Орендила','Быстрее, $n. Я положу Батранов волос в сумку, а тебе нужно будет доставить ее моему наставнику, Орендилу Широколисту. Ты найдешь его на Заставе Мейстры, если пойдешь по левой дороге на юг.$B$BНо будь $gосторожен:осторожна; – к нам доходили слухи о том, что застава находится под осадой Орды!','Доставьте мешочек с Батрановым волосом Орендилу Широколисту на заставу Мейстры, что в Ясеневом лесу.','Значит, Эвенар достиг цели. Впрочем, чего уж там – это твоя заслуга.$B$BНе знаю даже, как тебя отблагодарить. Увы, но нам еще многое придется сделать прежде, чем эти листья вновь обретут целебные свойства.','Учитывая все обстоятельства, надо обладать недюжинной смелостью, чтобы явиться сюда.$B$BТак что привело тебя, незнакомец?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Посылка для Орендила',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Быстрее, $n. Я положу Батранов волос в сумку, а тебе нужно будет доставить ее моему наставнику, Орендилу Широколисту. Ты найдешь его на Заставе Мейстры, если пойдешь по левой дороге на юг.$B$BНо будь $gосторожен:осторожна; – к нам доходили слухи о том, что застава находится под осадой Орды!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте мешочек с Батрановым волосом Орендилу Широколисту на заставу Мейстры, что в Ясеневом лесу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Значит, Эвенар достиг цели. Впрочем, чего уж там – это твоя заслуга.$B$BНе знаю даже, как тебя отблагодарить. Увы, но нам еще многое придется сделать прежде, чем эти листья вновь обретут целебные свойства.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Учитывая все обстоятельства, надо обладать недюжинной смелостью, чтобы явиться сюда.$B$BТак что привело тебя, незнакомец?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (13624,'Отряд под твоим командованием','Вернитесь к часовому Ойнее на заставу Мейстры, что в Ясеневом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отряд под твоим командованием',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к часовому Ойнее на заставу Мейстры, что в Ясеневом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13625,'Большая тренировка','Большая часть состязаний турнира требует от участников мастерства в управлении верховым животным. Чтобы познакомить тебя с этим видом поединков, мы разместили тренировочные манекены в северной части Ристалища турнира.$B$BЗайди в стойла на севере площадки, рядом с главной ареной, вооружись копьем и оседлай кель\'дорайского скакуна. Познакомься со всеми доступными приемами и используй новые знания в тренировке. Для освоения новых приемов можешь использовать все три вида манекенов.','Как проходит конная боевая практика?','Вернитесь к разведчице Шалиндрия на Ристалище Серебряного турнира в Ледяную Корону.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Большая тренировка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Большая часть состязаний турнира требует от участников мастерства в управлении верховым животным. Чтобы познакомить тебя с этим видом поединков, мы разместили тренировочные манекены в северной части Ристалища турнира.$B$BЗайди в стойла на севере площадки, рядом с главной ареной, вооружись копьем и оседлай кель\'дорайского скакуна. Познакомься со всеми доступными приемами и используй новые знания в тренировке. Для освоения новых приемов можешь использовать все три вида манекенов.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как проходит конная боевая практика?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к разведчице Шалиндрия на Ристалище Серебряного турнира в Ледяную Корону.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13626,'Последние почести','Добудьте священный молот Фиро и молитвенник Очистителя.','Наши потери невосполнимы.','Вернитесь к часовому Ойнее на заставу Мейстры, что в Ясеневом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Последние почести',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте священный молот Фиро и молитвенник Очистителя.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Наши потери невосполнимы.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к часовому Ойнее на заставу Мейстры, что в Ясеневом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13627,'Откуда дровишки?','Эй, иди сюда!.. Да не так близко, нас могут увидеть!$B$BДля постройки Колизея нужно гораздо больше дерева, чем я предполагал, а заказывать еще одну партию из Седых холмов я не стану ни за какие коврижки. В общем, слушай: на западной границе леса Хрустальной Песни, у Великого древа, растут молодые дубы.$B$BИх древесина как нельзя лучше подходит для строительства и возведения лесов. Возьми этот топор, повали несколько дубов Хрустальной Песни и принеси мне доски. Только смотри, не попадись никому на глаза!','Принесите 12 грубо обтесанных досок Беззлу Рвизасову на Ристалище Серебряного турнира.','Все отличные доски, и цена тоже правильная! Даже лучше, тех Серебряного Авангарда, палки-в-грязи никогда не будет знать. Они получат свой драгоценный Колизей, а я - премию за досрочное завершение строительства. Теперь это беспроигрышный вариант, если я когда-либо видел его.','Вы получили "товар", о котором мы говорили?','Вернитесь к Беззлу Рвизасову на Ристалище Серебряного турнира в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Откуда дровишки?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эй, иди сюда!.. Да не так близко, нас могут увидеть!$B$BДля постройки Колизея нужно гораздо больше дерева, чем я предполагал, а заказывать еще одну партию из Седых холмов я не стану ни за какие коврижки. В общем, слушай: на западной границе леса Хрустальной Песни, у Великого древа, растут молодые дубы.$B$BИх древесина как нельзя лучше подходит для строительства и возведения лесов. Возьми этот топор, повали несколько дубов Хрустальной Песни и принеси мне доски. Только смотри, не попадись никому на глаза!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 12 грубо обтесанных досок Беззлу Рвизасову на Ристалище Серебряного турнира.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Все отличные доски, и цена тоже правильная! Даже лучше, тех Серебряного Авангарда, палки-в-грязи никогда не будет знать. Они получат свой драгоценный Колизей, а я - премию за досрочное завершение строительства. Теперь это беспроигрышный вариант, если я когда-либо видел его.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы получили "товар", о котором мы говорили?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Беззлу Рвизасову на Ристалище Серебряного турнира в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13628,'Кадрак только что получил новый приказ для наших отрядов – мы должны начать атаку на Ясеневый лес!$b$bЯ совершенно не готов перейти в наступление, да и боеприпасы из Оргриммара все еще не поступили. Придется импровизировать...$b$bЗнаешь, мне могла бы пригодиться твоя помощь, |3-6($c).$b$bПоговори с Кадраком – пусть он выдаст тебе Жестокого Бивня. Этот кодо знает дорогу к рабочему лагерю Песни Войны. Как только прибудешь на место, найди Горку и попроси ее нагрузить зверя свежими бревнами.','Труун поручил вам оседлать Жестокого Бивня и отправиться в рабочий лагерь Песни Войны.$b$bЧтобы получить поводья для управления Жестоким Бивнем, поговорите с Кадраком.','Поговорите с Горкой в рабочем лагере Песни Войны, что в Ясеневом лесу.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кадрак только что получил новый приказ для наших отрядов – мы должны начать атаку на Ясеневый лес!$b$bЯ совершенно не готов перейти в наступление, да и боеприпасы из Оргриммара все еще не поступили. Придется импровизировать...$b$bЗнаешь, мне могла бы пригодиться твоя помощь, |3-6($c).$b$bПоговори с Кадраком – пусть он выдаст тебе Жестокого Бивня. Этот кодо знает дорогу к рабочему лагерю Песни Войны. Как только прибудешь на место, найди Горку и попроси ее нагрузить зверя свежими бревнами.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Труун поручил вам оседлать Жестокого Бивня и отправиться в рабочий лагерь Песни Войны.$b$bЧтобы получить поводья для управления Жестоким Бивнем, поговорите с Кадраком.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Горкой в рабочем лагере Песни Войны, что в Ясеневом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13629,'Вал\'анир, молот древних королей','С помощью панели управления Архивом вы узнаете способ воссоединения расколотого Вал\'анира: надо поместить его внутрь физической формы существа, известного как Йогг-Сарон.$B$BЭто звучит довольно опасно, но ради артефакта такой силы можно пойти на риск.','Бросьте расколотый Вал\'анир в пасть Йогг-Сарона во время "Оглушающего рева" и победите его, чтобы получить перекованный молот древних королей.$B$BЭто задание можно пройти только в героическом режиме и только в том случае, если хотя бы один из хранителей Ульдуара не помогает вам.','Целостность объекта подтверждена. Ожидайте удаления твердого осадка.','Ожидание ввода.','Вернитесь к панели управления Архивом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вал\'анир, молот древних королей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','С помощью панели управления Архивом вы узнаете способ воссоединения расколотого Вал\'анира: надо поместить его внутрь физической формы существа, известного как Йогг-Сарон.$B$BЭто звучит довольно опасно, но ради артефакта такой силы можно пойти на риск.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Бросьте расколотый Вал\'анир в пасть Йогг-Сарона во время "Оглушающего рева" и победите его, чтобы получить перекованный молот древних королей.$B$BЭто задание можно пройти только в героическом режиме и только в том случае, если хотя бы один из хранителей Ульдуара не помогает вам.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Целостность объекта подтверждена. Ожидайте удаления твердого осадка.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ожидание ввода.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к панели управления Архивом.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13630,'Главная причина','Эти фурболги спустились с гор и захватили Руины Ордил\'Арана на севере. Полагаю, их привлекла находка мертвых служителей культа – три лунных камня.$B$BЛиладрис Лунная Река, несомненно, посоветует тебе не церемониться с фурболгами, и я не стану с ней спорить, но прежде всего надо отправиться в руины и отключить эти лунные камни.','Отключите синий, зеленый и красный лунные камни.','Вернитесь к жрице луны Мейстры на заставу Мейстры, что в Ясеневом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Главная причина',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти фурболги спустились с гор и захватили Руины Ордил\'Арана на севере. Полагаю, их привлекла находка мертвых служителей культа – три лунных камня.$B$BЛиладрис Лунная Река, несомненно, посоветует тебе не церемониться с фурболгами, и я не стану с ней спорить, но прежде всего надо отправиться в руины и отключить эти лунные камни.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отключите синий, зеленый и красный лунные камни.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к жрице луны Мейстры на заставу Мейстры, что в Ясеневом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13631,'Все хорошо, что хорошо кончается','Мы должны поторопиться, $n – надо передать код отклика из Даларана как можно скорее.$B$BОтнеси его Ронину, я встречу тебя там.','Доставьте код отклика "Альфа" Ронину в Даларан.','Наконец-то ты здесь. Надеюсь, это сработает.','Ты $gготов:готова;, $n?','Вернитесь к Ронину в Лес Хрустальной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Все хорошо, что хорошо кончается',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы должны поторопиться, $n – надо передать код отклика из Даларана как можно скорее.$B$BОтнеси его Ронину, я встречу тебя там.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте код отклика "Альфа" Ронину в Даларан.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Наконец-то ты здесь. Надеюсь, это сработает.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $gготов:готова;, $n?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ронину в Лес Хрустальной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13632,'Служба в арьергарде','У лунной жрицы есть план, как остановить нашествие фурболгов с высокогорья. Правда, меня больше беспокоят те звери, что уже захватили руины – многие из них собираются в опасной близости от заставы.$B$BПонимаю, это неприятное поручение, но я вынуждена просить тебя отправиться к северу, к Руинам Ордил\'Арана, и уничтожить фурболгов. Иначе мы не сможем сражаться на двух фронтах!$B$BЗаранее благодарю тебя, |3-6($c).','Убейте 10 фурболгов на руинах Ордил\'Арана.','Вернитесь к Лиладрис Лунной Реке на заставу Мейстры, что в Ясеневом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Служба в арьергарде',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У лунной жрицы есть план, как остановить нашествие фурболгов с высокогорья. Правда, меня больше беспокоят те звери, что уже захватили руины – многие из них собираются в опасной близости от заставы.$B$BПонимаю, это неприятное поручение, но я вынуждена просить тебя отправиться к северу, к Руинам Ордил\'Арана, и уничтожить фурболгов. Иначе мы не сможем сражаться на двух фронтах!$B$BЗаранее благодарю тебя, |3-6($c).',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 фурболгов на руинах Ордил\'Арана.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лиладрис Лунной Реке на заставу Мейстры, что в Ясеневом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13633,'Узнайте правду о Черном рыцаре и поделитесь информацией с рыцарем Райдаллой на Ристалище Серебряного турнира.','Значит, история рыцаря – это сплошной обман? Крайне подозрительная ситуация. Это бесчестно, а может стать и смертельно опасным в худшем случае. Но мы не сможем предъявить ему обвинения, пока у нас не будет доказательств.$B$BПостарайся не вызывать у него подозрений, $N. Если мы хотим продолжить расследование, надо делать это втайне.','Тебе удалось найти что-то, что могло бы подтвердить историю Черного рыцаря?','Вернитесь к рыцарю Райдалле на Ристалище Серебряного турнира, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Узнайте правду о Черном рыцаре и поделитесь информацией с рыцарем Райдаллой на Ристалище Серебряного турнира.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Значит, история рыцаря – это сплошной обман? Крайне подозрительная ситуация. Это бесчестно, а может стать и смертельно опасным в худшем случае. Но мы не сможем предъявить ему обвинения, пока у нас не будет доказательств.$B$BПостарайся не вызывать у него подозрений, $N. Если мы хотим продолжить расследование, надо делать это втайне.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось найти что-то, что могло бы подтвердить историю Черного рыцаря?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к рыцарю Райдалле на Ристалище Серебряного турнира, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13634,'Черный рыцарь из Серебряного бора?','Не сомневаюсь, до тебя уже дошли тревожные слухи об участнике турнира, которого остальные называют Черным рыцарем. Говорят, будто каждый, кому выпал жребий стать его противником в следующем бою, внезапно умирает.$B$BКонечно, мы не можем ничего утверждать, но было бы неплохо проверить все, что нам известно про этого рыцаря.$B$BПо его словам, он прибыл с Поля Валгана, что в Серебряном Бору. Это маленькая ферма на западном берегу озера Лордамер. Съезди на эту ферму, чтобы подтвердить или опровергнуть его слова.','Узнайте правду о Черном рыцаре и поделитесь информацией с рыцарем Райдаллой на Ристалище Серебряного турнира.','Значит, история рыцаря – это сплошной обман? Крайне подозрительная ситуация. Это бесчестно, а может стать и смертельно опасным в худшем случае. Но мы не сможем предъявить ему обвинения, пока у нас не будет доказательств.$B$BПостарайся не вызывать у него подозрений, $N. Если мы хотим продолжить расследование, надо делать это втайне.','Тебе удалось найти что-то, что могло бы подтвердить историю Черного рыцаря?','Вернитесь к рыцарю Райдалле на Ристалище Серебряного турнира, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Черный рыцарь из Серебряного бора?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не сомневаюсь, до тебя уже дошли тревожные слухи об участнике турнира, которого остальные называют Черным рыцарем. Говорят, будто каждый, кому выпал жребий стать его противником в следующем бою, внезапно умирает.$B$BКонечно, мы не можем ничего утверждать, но было бы неплохо проверить все, что нам известно про этого рыцаря.$B$BПо его словам, он прибыл с Поля Валгана, что в Серебряном Бору. Это маленькая ферма на западном берегу озера Лордамер. Съезди на эту ферму, чтобы подтвердить или опровергнуть его слова.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Узнайте правду о Черном рыцаре и поделитесь информацией с рыцарем Райдаллой на Ристалище Серебряного турнира.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Значит, история рыцаря – это сплошной обман? Крайне подозрительная ситуация. Это бесчестно, а может стать и смертельно опасным в худшем случае. Но мы не сможем предъявить ему обвинения, пока у нас не будет доказательств.$B$BПостарайся не вызывать у него подозрений, $N. Если мы хотим продолжить расследование, надо делать это втайне.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось найти что-то, что могло бы подтвердить историю Черного рыцаря?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к рыцарю Райдалле на Ристалище Серебряного турнира, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (13635,'Отчет Южных врат','Нам нужно отправить отчет о состоянии дел горным пехотинцам в Долину Королей.$b$bРаз уж ты все равно туда направляешься, не захватишь ли заодно и его? Воспользуйся туннелем к востоку отсюда, а потом обратись к стражникам. Передай отчет лично в руки капитану Ругельфассу.','Доставьте отчет пилота Большенога капитану Ругельфассу в Долину Королей.','Отчет Южных врат? Прекрасно! Я уже некоторое время жду новостей оттуда.$B$BТроггов на холмах становится все больше, боюсь, заставы первыми почувствуют на себе их агрессию.','Что заставило тебя проделать такой путь?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отчет Южных врат',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нам нужно отправить отчет о состоянии дел горным пехотинцам в Долину Королей.$b$bРаз уж ты все равно туда направляешься, не захватишь ли заодно и его? Воспользуйся туннелем к востоку отсюда, а потом обратись к стражникам. Передай отчет лично в руки капитану Ругельфассу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте отчет пилота Большенога капитану Ругельфассу в Долину Королей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отчет Южных врат? Прекрасно! Я уже некоторое время жду новостей оттуда.$B$BТроггов на холмах становится все больше, боюсь, заставы первыми почувствуют на себе их агрессию.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что заставило тебя проделать такой путь?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13636,'Заказы для Грозовой Вершины','У меня есть кое-какие заказы для горного пехотинца Грозовой Вершины с заставы на станции Альгаз. Если тебя не затруднит отнести их ему, то отправляйся по дороге, которая ведет на северо-запад, так ты точно не пропустишь главный бункер.$b$bА если ты поможешь ему выполнить заказы, то мы будем рады наградить тебя за это.','Доставьте заказы для Грозовой Вершины горному пехотинцу Грозовой Вершине на станцию Альгаз.','Заказы! Посмотрим, что тут у нас… ха! Он хочет, чтобы я разобрался с нашествием крысолюдей. Мы как раз этим и занимаемся.$B$BПоможешь?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Заказы для Грозовой Вершины',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У меня есть кое-какие заказы для горного пехотинца Грозовой Вершины с заставы на станции Альгаз. Если тебя не затруднит отнести их ему, то отправляйся по дороге, которая ведет на северо-запад, так ты точно не пропустишь главный бункер.$b$bА если ты поможешь ему выполнить заказы, то мы будем рады наградить тебя за это.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте заказы для Грозовой Вершины горному пехотинцу Грозовой Вершине на станцию Альгаз.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Заказы! Посмотрим, что тут у нас… ха! Он хочет, чтобы я разобрался с нашествием крысолюдей. Мы как раз этим и занимаемся.$B$BПоможешь?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (13637,'Доставка барана','Горные пехотинцы с заставы у Южных врат попросили прислать баранов для их патрулей. Не думаю, что у нас есть много лишних баранов, но благодаря тебе мы можем послать им одного.$b$bНе доставишь ли ты его рядовому из Павшего Молота? Когда будешь $gготов:готова; отправиться, дай мне знать.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Доставка барана',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Горные пехотинцы с заставы у Южных врат попросили прислать баранов для их патрулей. Не думаю, что у нас есть много лишних баранов, но благодаря тебе мы можем послать им одного.$b$bНе доставишь ли ты его рядовому из Павшего Молота? Когда будешь $gготов:готова; отправиться, дай мне знать.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (13638,'Плененный горный пехотинец','В бою ты $gпоказал:показала; себя как нельзя лучше. Теперь я хочу попросить тебя кое о чем более срочном.$b$bОдин из моих горных пехотинцев, Булыжный Карьер, был захвачен троггами в южных горах. Ну, то есть не то чтобы захвачен, скорее он сдался добровольно, но результат от этого не меняется. Я думаю, таким образом он пытался изнутри выяснить, кто является их предводителем.$b$bЯ хочу, чтобы ты $gосвободил:освободила; его. Скорее всего они держат его возле одной из своих верхних пещер глубоко в горах.','Капитан Ругельфасс в Телсамаре просит вас отыскать горного пехотинца Булыжного Карьера.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Плененный горный пехотинец',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В бою ты $gпоказал:показала; себя как нельзя лучше. Теперь я хочу попросить тебя кое о чем более срочном.$b$bОдин из моих горных пехотинцев, Булыжный Карьер, был захвачен троггами в южных горах. Ну, то есть не то чтобы захвачен, скорее он сдался добровольно, но результат от этого не меняется. Я думаю, таким образом он пытался изнутри выяснить, кто является их предводителем.$b$bЯ хочу, чтобы ты $gосвободил:освободила; его. Скорее всего они держат его возле одной из своих верхних пещер глубоко в горах.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Капитан Ругельфасс в Телсамаре просит вас отыскать горного пехотинца Булыжного Карьера.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`) VALUES (13639,'Снабжение экспедиции','Сталекрут ведет раскопки на юго-востоке и ему требуется изрядное количество взрывчатки, которую присылает Лига. Хальдар, Миран и Сайан уже отправились с последней партией груза, но, возможно, им не помещает помощь.$b$bВряд ли они ушли далеко, с их-то силенками. С такими тяжелыми бочками не пойдешь быстро.$b$bОни отправились к раскопкам обычной дорогой, из города на юг, а дальше вдоль берега озера Лок. Догони их и помоги им, хорошо?','Найдите Хальдара, Мирана и Сайана.','Хмм, если бы все проблемы были только в засадах Черного Железа, поставкам бы ничего не грозило!$B$BНо Сайан… Я никогда не подозревал, что он один из их сторонников. Мы работали вместе почти целый год… может быть, я чего-то не заметил?$B$BЛадно, я подумаю об этом позже.','Найдите Хальдара, Мирана и Сайана') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Снабжение экспедиции',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сталекрут ведет раскопки на юго-востоке и ему требуется изрядное количество взрывчатки, которую присылает Лига. Хальдар, Миран и Сайан уже отправились с последней партией груза, но, возможно, им не помещает помощь.$b$bВряд ли они ушли далеко, с их-то силенками. С такими тяжелыми бочками не пойдешь быстро.$b$bОни отправились к раскопкам обычной дорогой, из города на юг, а дальше вдоль берега озера Лок. Догони их и помоги им, хорошо?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Хальдара, Мирана и Сайана.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хмм, если бы все проблемы были только в засадах Черного Железа, поставкам бы ничего не грозило!$B$BНо Сайан… Я никогда не подозревал, что он один из их сторонников. Мы работали вместе почти целый год… может быть, я чего-то не заметил?$B$BЛадно, я подумаю об этом позже.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Найдите Хальдара, Мирана и Сайана',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13640,'Руководящий состав','Что, Трууну дровишки понадобились? В любой другой день я бы сгрузила ему пачку бревен без лишних вопросов, но только не сегодня.$b$bИз-за этих проклятых эльфов рубка леса стала опасным занятием, и мои наемные рабочие отказываются рисковать своей шкурой.$b$bТак что если тебе нужно дерево – иди и заставь их работать.$b$bДа, и охраняй их по пути – я не могу больше терять сотрудников!','Заставьте работать несобранных батраков и соберите 5 вязанок свежесрубленного леса.','Вернитесь к Горке в рабочий лагерь Песни Войны, что в Ясеневом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Руководящий состав',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что, Трууну дровишки понадобились? В любой другой день я бы сгрузила ему пачку бревен без лишних вопросов, но только не сегодня.$b$bИз-за этих проклятых эльфов рубка леса стала опасным занятием, и мои наемные рабочие отказываются рисковать своей шкурой.$b$bТак что если тебе нужно дерево – иди и заставь их работать.$b$bДа, и охраняй их по пути – я не могу больше терять сотрудников!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заставьте работать несобранных батраков и соберите 5 вязанок свежесрубленного леса.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Горке в рабочий лагерь Песни Войны, что в Ясеневом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (13641,'Кристалл провидца','Принесите кристалл провидца рыцарю Райдалле в Серебряный павильон на Ристалище Серебряного турнира.','Да, этот кристалл подойдет. Осталось только зарядить его силой Света, чтобы он смог отличить правду от лжи.','Вернитесь к рыцарю Райдалле на Ристалище Серебряного турнира, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кристалл провидца',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите кристалл провидца рыцарю Райдалле в Серебряный павильон на Ристалище Серебряного турнира.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, этот кристалл подойдет. Осталось только зарядить его силой Света, чтобы он смог отличить правду от лжи.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к рыцарю Райдалле на Ристалище Серебряного турнира, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13642,'Свет Элуны','Зелье еще не готово – прежде, чем давать его больной девочке, оно должно быть благословлено Светом Элуны.$B$BЯ знаю одно место, к западу от Озера Фалатим, где лунные лучи день и ночь касаются земли. Прошу тебя, $n, ради Релары – возьми это лекарство и окуни его в свет Элуны.$B$BБереги себя – говорят, в окрестностях озера творятся странные вещи. Дороги туда более не безопасны.','Создайте Омытое светом зелье.','Тяжело было достать Свет Элуны из озера Фалатим?','Вернитесь к Орендилу Широколисту на заставу Мейстры, что в Ясеневом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Свет Элуны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Зелье еще не готово – прежде, чем давать его больной девочке, оно должно быть благословлено Светом Элуны.$B$BЯ знаю одно место, к западу от Озера Фалатим, где лунные лучи день и ночь касаются земли. Прошу тебя, $n, ради Релары – возьми это лекарство и окуни его в свет Элуны.$B$BБереги себя – говорят, в окрестностях озера творятся странные вещи. Дороги туда более не безопасны.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Создайте Омытое светом зелье.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тяжело было достать Свет Элуны из озера Фалатим?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Орендилу Широколисту на заставу Мейстры, что в Ясеневом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13643,'История погибших','Этот кристалл откроет нам правду о том, как погибли три участника турнира. Отнеси его на кладбище на востоке Ристалища к могилам сэра Венделла Балфура, Лориена Блеска Солнца и Коналла Железной Хватки.$B$BЕсли три этих доблестных мужа действительно были убиты, мы должны будем найти доказательства причастности Черного рыцаря до того, как он совершит очередное преступление. Внимательно изучи то, что покажет тебе кристалл, ибо мы должны быть абсолютно уверены, что эти смерти не были случайными.','Воспользуйтесь кристаллом провидца перед могилами сэра Венделла Балфура, Лориена Блеска Солнца и Коналла Железной Хватки, узнайте причину их гибели и доложите рыцарю Райдалле из Серебряного павильона.','Значит, Лориен Блеск Солнца был отравлен, а сэр Венделл сгорел заживо? Какая ужасная смерть постигла этих доблестных мужей. Один лишь Коналл погиб, сраженный мечом – но не в честном поединке, а от руки предателя.$B$BИ все трое должны были сражаться с Черным рыцарем на турнире. Это не может быть совпадением! Осталось доказать, что он причастен к их смерти.','Посещали ли вы могилы убитых?','Вернитесь к рыцарю Райдалле на Ристалище Серебряного турнира, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','История погибших',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этот кристалл откроет нам правду о том, как погибли три участника турнира. Отнеси его на кладбище на востоке Ристалища к могилам сэра Венделла Балфура, Лориена Блеска Солнца и Коналла Железной Хватки.$B$BЕсли три этих доблестных мужа действительно были убиты, мы должны будем найти доказательства причастности Черного рыцаря до того, как он совершит очередное преступление. Внимательно изучи то, что покажет тебе кристалл, ибо мы должны быть абсолютно уверены, что эти смерти не были случайными.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь кристаллом провидца перед могилами сэра Венделла Балфура, Лориена Блеска Солнца и Коналла Железной Хватки, узнайте причину их гибели и доложите рыцарю Райдалле из Серебряного павильона.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Значит, Лориен Блеск Солнца был отравлен, а сэр Венделл сгорел заживо? Какая ужасная смерть постигла этих доблестных мужей. Один лишь Коналл погиб, сраженный мечом – но не в честном поединке, а от руки предателя.$B$BИ все трое должны были сражаться с Черным рыцарем на турнире. Это не может быть совпадением! Осталось доказать, что он причастен к их смерти.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Посещали ли вы могилы убитых?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к рыцарю Райдалле на Ристалище Серебряного турнира, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (13644,'Тот, кто был воскрешен','Когда я почувствовал, как эти... сущности... поднимаются из-под земли, я прибыл, чтобы отправить их обратно раз и навсегда. Здесь я нашел тело твоего друга и отнес его так далеко, как только смог. Увы, на полпути я подвернул копыто, и на том закончились мои попытки удержать распространение этих ужасных щупалец.$B$BНо я знаю, кто управляет этими отростками и глазами. Он называет себя предвестник Афотик – уверен, ты слышал его завывания, доносящиеся с юга.$B$BУвы, мне не дотянуться до него своей магией, но если тебе удастся подобраться к нему поближе... Не знаю только, хватит ли у тебя смелости.','Убейте предвестника Афотика.','Вернитесь к Хранителю Мудрое Сердце на озеро Фалатим, что в Ясеневом лесу.','Верни эту злобную тварь туда, откуда она вылезла.','Предвестник Афотик') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тот, кто был воскрешен',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда я почувствовал, как эти... сущности... поднимаются из-под земли, я прибыл, чтобы отправить их обратно раз и навсегда. Здесь я нашел тело твоего друга и отнес его так далеко, как только смог. Увы, на полпути я подвернул копыто, и на том закончились мои попытки удержать распространение этих ужасных щупалец.$B$BНо я знаю, кто управляет этими отростками и глазами. Он называет себя предвестник Афотик – уверен, ты слышал его завывания, доносящиеся с юга.$B$BУвы, мне не дотянуться до него своей магией, но если тебе удастся подобраться к нему поближе... Не знаю только, хватит ли у тебя смелости.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте предвестника Афотика.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хранителю Мудрое Сердце на озеро Фалатим, что в Ясеневом лесу.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Верни эту злобную тварь туда, откуда она вылезла.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Предвестник Афотик',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (13645,'К Раэне Волкопас','Пожалуйста, передай этот самоцвет из рук в руки Раэне Волкопас. По моим сведениям, она все еще находится в Астранааре на юго-востоке.$B$BГоворят, дорога туда все еще безопасна, поэтому я не предвижу никаких трудностей с доставкой. Но если тебя интересует более быстрый путь, обратись к часовому Аване, и она с радостью одолжит тебе одного из верховых ночных саблезубов.$B$BКакой бы способ передвижения ты ни $gпредпочел:предпочла;, желаю тебе доброго пути, $n. Надеюсь, мы еще встретимся.','Отнесите светящийся самоцвет Раэне Волкопас в Астранаар, что в Ясеневом лесу.','Я Раэна Волкопас. А ты кто такой?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','К Раэне Волкопас',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пожалуйста, передай этот самоцвет из рук в руки Раэне Волкопас. По моим сведениям, она все еще находится в Астранааре на юго-востоке.$B$BГоворят, дорога туда все еще безопасна, поэтому я не предвижу никаких трудностей с доставкой. Но если тебя интересует более быстрый путь, обратись к часовому Аване, и она с радостью одолжит тебе одного из верховых ночных саблезубов.$B$BКакой бы способ передвижения ты ни $gпредпочел:предпочла;, желаю тебе доброго пути, $n. Надеюсь, мы еще встретимся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите светящийся самоцвет Раэне Волкопас в Астранаар, что в Ясеневом лесу.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я Раэна Волкопас. А ты кто такой?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (13646,'Связь с Астранааром','Твоя помощь неоценима для нас, $n. Не будь тебя, нас бы уже стерли с лица земли.$B$BСамое малое, что я могу для тебя сделать взамен – предложить одного из моих ночных саблезубов, которые знают дорогу в Астранаар – наверх и на северо-восток. Не сомневаюсь, там тебя ждут очень важные и неотложные дела.$B$BНо я была бы тебе очень благодарна, если бы ты по прибытии $gразыскал:разыскала; мою сестру, часового Луару, и $gсообщил:сообщила; ей, что со мной все в порядке.$B$BСкажи мне, когда будешь $gготов:готова; отправляться в путь.','Поговорите с часовым Луарой в Астранааре, что в Ясеневом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Связь с Астранааром',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Твоя помощь неоценима для нас, $n. Не будь тебя, нас бы уже стерли с лица земли.$B$BСамое малое, что я могу для тебя сделать взамен – предложить одного из моих ночных саблезубов, которые знают дорогу в Астранаар – наверх и на северо-восток. Не сомневаюсь, там тебя ждут очень важные и неотложные дела.$B$BНо я была бы тебе очень благодарна, если бы ты по прибытии $gразыскал:разыскала; мою сестру, часового Луару, и $gсообщил:сообщила; ей, что со мной все в порядке.$B$BСкажи мне, когда будешь $gготов:готова; отправляться в путь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с часовым Луарой в Астранааре, что в Ясеневом лесу.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13647,'Присоединение к охоте','У тебя определенно дух воина.$b$bЗнаешь, в приюте к востоку отсюда, в холмах, живут охотники – тебе бы не помешали такие союзники. Почему бы тебе не навестить их и не узнать, нет ли у них какой-то работы, которая бы тебя заинтересовала?','Поговорите с Мареком Железносердом в Приюте Странников.','Здорово, подруга! Ты от горных пехотинцев? Думаю, у нас найдется работа как раз по тебе. Добро пожаловать в Приют Странников!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Присоединение к охоте',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У тебя определенно дух воина.$b$bЗнаешь, в приюте к востоку отсюда, в холмах, живут охотники – тебе бы не помешали такие союзники. Почему бы тебе не навестить их и не узнать, нет ли у них какой-то работы, которая бы тебя заинтересовала?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Мареком Железносердом в Приюте Странников.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Здорово, подруга! Ты от горных пехотинцев? Думаю, у нас найдется работа как раз по тебе. Добро пожаловать в Приют Странников!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (13648,'РАЗЫСКИВАЕТСЯ: шпион Черного Железа','Убейте Горика Пивохлеба.','Вернитесь к мировому судье Тупоносу в Телсамар, что в Лок Модане.','Найди и убей этого идиота!','Горик Пивохлеб') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','РАЗЫСКИВАЕТСЯ: шпион Черного Железа',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Горика Пивохлеба.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мировому судье Тупоносу в Телсамар, что в Лок Модане.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Найди и убей этого идиота!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Горик Пивохлеб',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13649,'Веселая проверка Джастина','Эй! Похоже, с выпивкой ты обращаться умеешь. А вот с пивной кружкой? $b$bЭти дворфы из клана Черного Железа опять вернулись! Мстить хотят и праздник нам порушить! Легче всего их отогнать, если запустить в них пивной кружкой, но сначала посмотрим-ка, попадешь ли ты в чучелко – С.С.М.?$b$bЭто просто – хлебни бесплатного пивка, только встань сначала лицом к С.С.М. Попади в цель пять раз, тогда поговорим.','Попадите кружкой с бесплатным пивом в С.С.М. 5 раз, затем поговорите с Бокси Болтокрутом.','Return to [PH] Justin\'s Test NPC.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Веселая проверка Джастина',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эй! Похоже, с выпивкой ты обращаться умеешь. А вот с пивной кружкой? $b$bЭти дворфы из клана Черного Железа опять вернулись! Мстить хотят и праздник нам порушить! Легче всего их отогнать, если запустить в них пивной кружкой, но сначала посмотрим-ка, попадешь ли ты в чучелко – С.С.М.?$b$bЭто просто – хлебни бесплатного пивка, только встань сначала лицом к С.С.М. Попади в цель пять раз, тогда поговорим.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Попадите кружкой с бесплатным пивом в С.С.М. 5 раз, затем поговорите с Бокси Болтокрутом.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Return to [PH] Justin\'s Test NPC.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (13650,'Руки прочь от имущества!','Мы нашли в этом месте поразительные артефакты. Сложно убедиться в их подлинности, но они могут обладать большой исторической ценностью.$b$bК сожалению, когда трогги заняли эту территорию, мы лишились доступа к трем наиболее ценным. Я боюсь, что в наше отсутствие трогги либо украли их, либо испортили.$b$bЕсли будешь на раскопках, постарайся найти опрокинутого великана, нарядную женщину и разбитую скрижаль и убедись, что с ними все в порядке.','Проверьте состояние следующих артефактов: опрокинутого великана, нарядной женщины и разбитой скрижали.','Уф! Гора с плеч… Я опасался, что все они уничтожены. Спасибо за то, что проверила.','Вернитесь к геологу Сталекруту на раскопки Сталекрута, что в Лок Модане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Руки прочь от имущества!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы нашли в этом месте поразительные артефакты. Сложно убедиться в их подлинности, но они могут обладать большой исторической ценностью.$b$bК сожалению, когда трогги заняли эту территорию, мы лишились доступа к трем наиболее ценным. Я боюсь, что в наше отсутствие трогги либо украли их, либо испортили.$b$bЕсли будешь на раскопках, постарайся найти опрокинутого великана, нарядную женщину и разбитую скрижаль и убедись, что с ними все в порядке.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проверьте состояние следующих артефактов: опрокинутого великана, нарядной женщины и разбитой скрижали.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Уф! Гора с плеч… Я опасался, что все они уничтожены. Спасибо за то, что проверила.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к геологу Сталекруту на раскопки Сталекрута, что в Лок Модане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13651,'Надо немного смазки','Горка из рабочего лагеря Песни Войны просит вас собрать 5 порций слизи в Ясеневом лесу.','Тебе удалось собрать жир?','Поговорите с Горкой в рабочем лагере Песни Войны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Надо немного смазки',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Горка из рабочего лагеря Песни Войны просит вас собрать 5 порций слизи в Ясеневом лесу.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось собрать жир?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Горкой в рабочем лагере Песни Войны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (13652,'Защита Каменной Плотины','Мы очень ценим твою помощь. Через некоторое время мы восстановим контроль над раскопками, и я очень рад слышать, что в результате этого захвата мы не лишились всей своей работы.$b$bМы уже достаточно злоупотребили твоим временем. Но у меня есть друг, который тоже будет рад твоей помощи, если бы будешь так $gдобр:добра; ее оказать. Отправляйся на дальнюю оконечность озера Лок, там ты найдешь Каменную Плотину. Разыщи там главного инженера Плотиннера VII.','Найдите главного инженера Плотиннера VII на Каменной Плотине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Защита Каменной Плотины',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы очень ценим твою помощь. Через некоторое время мы восстановим контроль над раскопками, и я очень рад слышать, что в результате этого захвата мы не лишились всей своей работы.$b$bМы уже достаточно злоупотребили твоим временем. Но у меня есть друг, который тоже будет рад твоей помощи, если бы будешь так $gдобр:добра; ее оказать. Отправляйся на дальнюю оконечность озера Лок, там ты найдешь Каменную Плотину. Разыщи там главного инженера Плотиннера VII.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите главного инженера Плотиннера VII на Каменной Плотине.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (13653,'Кризис на заставе','Горка просит вас сопроводить ее к заставе Мор\'шан и отчитаться перед Кадраком.$b$bОкликните ее, когда вы будете готовы отправиться в путь.','Горка...$B$BНа войне не обойтись без потерь. Но ее беззаветное служение Орде не будет забыто.$B$BИ ее жертва не должна стать напрасной!','Встретьтесь с Кадраком на заставе Мор\'шан.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кризис на заставе',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Горка просит вас сопроводить ее к заставе Мор\'шан и отчитаться перед Кадраком.$b$bОкликните ее, когда вы будете готовы отправиться в путь.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Горка...$B$BНа войне не обойтись без потерь. Но ее беззаветное служение Орде не будет забыто.$B$BИ ее жертва не должна стать напрасной!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Встретьтесь с Кадраком на заставе Мор\'шан.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13654,'Странный оруженосец','Добудьте большую бедренную кость дровосека-скелета и оглушите Малорика. Обыщите его и доложите обо всем рыцарю Райдалле из Серебряного павильона на Ристалище Серебряного турнира.','<Рыцарь Райдалла с отвращением изучает содержимое сумки.>$B$BЗдесь все улики, $N: яд, которым был отравлен Лориен, набор ножей, факелы и масло. Не могу представить, зачем оруженосцу могли потребоваться эти предметы, если только он не выполнял приказ своего рыцаря. Мы нашли убийцу, $N, но по чьему приказанию он действовал?','Тебе удалось узнать что-нибудь об этом странном оруженосце?','Вернитесь к рыцарю Райдалле на Ристалище Серебряного турнира, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Странный оруженосец',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте большую бедренную кость дровосека-скелета и оглушите Малорика. Обыщите его и доложите обо всем рыцарю Райдалле из Серебряного павильона на Ристалище Серебряного турнира.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Рыцарь Райдалла с отвращением изучает содержимое сумки.>$B$BЗдесь все улики, $N: яд, которым был отравлен Лориен, набор ножей, факелы и масло. Не могу представить, зачем оруженосцу могли потребоваться эти предметы, если только он не выполнял приказ своего рыцаря. Мы нашли убийцу, $N, но по чьему приказанию он действовал?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось узнать что-нибудь об этом странном оруженосце?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к рыцарю Райдалле на Ристалище Серебряного турнира, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (13655,'Документ Лиги исследователей (2 из 6)','Документ написан на гербовой бумаге Лиги исследователей, в нем перечислены места возможных раскопок в Лок Модане. Пятна копоти свидетельствуют о том, что документ, скорее всего, был украден местными шпионами из клана Черного Железа.$b$bВы вспоминаете, что в здании Лиги исследователей в Телсамаре упоминали о пропавших документах.','Верните документ Лиги исследователей Торрену Квадратной Челюсти в Телсамар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Документ Лиги исследователей (2 из 6)',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Документ написан на гербовой бумаге Лиги исследователей, в нем перечислены места возможных раскопок в Лок Модане. Пятна копоти свидетельствуют о том, что документ, скорее всего, был украден местными шпионами из клана Черного Железа.$b$bВы вспоминаете, что в здании Лиги исследователей в Телсамаре упоминали о пропавших документах.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните документ Лиги исследователей Торрену Квадратной Челюсти в Телсамар.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (13656,'Документ Лиги исследователей (1 из 6)','Документ написан на гербовой бумаге Лиги исследователей и содержит обширную информацию о существах, обитающих в Лок Модане. Пятна копоти свидетельствуют о том, что документ, скорее всего, был украден местными шпионами из клана Черного Железа.$b$bВы вспоминаете, что в здании Лиги исследователей в Телсамаре упоминали о пропавших документах.','Верните документ Лиги исследователей Торрену Квадратной Челюсти в Телсамар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Документ Лиги исследователей (1 из 6)',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Документ написан на гербовой бумаге Лиги исследователей и содержит обширную информацию о существах, обитающих в Лок Модане. Пятна копоти свидетельствуют о том, что документ, скорее всего, был украден местными шпионами из клана Черного Железа.$b$bВы вспоминаете, что в здании Лиги исследователей в Телсамаре упоминали о пропавших документах.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните документ Лиги исследователей Торрену Квадратной Челюсти в Телсамар.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13657,'Документ Лиги исследователей (3 из 6)','Документ написан на гербовой бумаге Лиги исследователей и содержит исторические записи обо всех примечательных местах Лок Модана. Пятна копоти свидетельствуют о том, что документ, скорее всего, был украден местными шпионами из клана Черного Железа.$b$bВы вспоминаете, что в здании Лиги исследователей в Телсамаре говорили о пропавших документах.','Верните документ Лиги исследователей Торрену Квадратной Челюсти в Телсамар.','Наши исторические записи! Мысль о том, что эти негодяи из Черного Железа копались в нашем прошлом, вызывает у меня тошноту.$B$BМы очень благодарны тебе за то, что ты вернула нам пропажу. Мы бы хотели вознаградить тебя за это.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Документ Лиги исследователей (3 из 6)',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Документ написан на гербовой бумаге Лиги исследователей и содержит исторические записи обо всех примечательных местах Лок Модана. Пятна копоти свидетельствуют о том, что документ, скорее всего, был украден местными шпионами из клана Черного Железа.$b$bВы вспоминаете, что в здании Лиги исследователей в Телсамаре говорили о пропавших документах.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните документ Лиги исследователей Торрену Квадратной Челюсти в Телсамар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Наши исторические записи! Мысль о том, что эти негодяи из Черного Железа копались в нашем прошлом, вызывает у меня тошноту.$B$BМы очень благодарны тебе за то, что ты вернула нам пропажу. Мы бы хотели вознаградить тебя за это.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13658,'Документ Лиги исследователей (4 из 6)','Документ написан на гербовой бумаге Лиги исследователей, в нем перечислены транспортные пути, которыми пользуется Лига для доступа в Лок Модан. Пятна копоти свидетельствуют о том, что документ, скорее всего, был украден местными шпионами из клана Черного Железа.$b$bВы вспоминаете, что в здании Лиги исследователей в Телсамаре говорили о пропавших документах.','Верните документ Лиги исследователей Торрену Квадратной Челюсти в Телсамар.','Фу, поверить не могу, что им в руки попала информация о наших транспортных путях!$B$BСпасибо, что вернула нам этот документ, пока они не успели принести нам большого вреда! Возможно, ты уберегла нас от больших проблем. Пожалуйста, возьми пару монет за твои труды.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Документ Лиги исследователей (4 из 6)',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Документ написан на гербовой бумаге Лиги исследователей, в нем перечислены транспортные пути, которыми пользуется Лига для доступа в Лок Модан. Пятна копоти свидетельствуют о том, что документ, скорее всего, был украден местными шпионами из клана Черного Железа.$b$bВы вспоминаете, что в здании Лиги исследователей в Телсамаре говорили о пропавших документах.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните документ Лиги исследователей Торрену Квадратной Челюсти в Телсамар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Фу, поверить не могу, что им в руки попала информация о наших транспортных путях!$B$BСпасибо, что вернула нам этот документ, пока они не успели принести нам большого вреда! Возможно, ты уберегла нас от больших проблем. Пожалуйста, возьми пару монет за твои труды.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13659,'Документ Лиги исследователей (6 из 6)','Документ написан на гербовой бумаге Лиги исследователей, в нем перечислены оценки различных угроз в Лок Модане. Пятна копоти свидетельствуют о том, что документ, скорее всего, был украден местными шпионами из клана Черного Железа.$b$bВы вспоминаете, что в здании Лиги исследователей в Телсамаре упоминали о пропавших документах.','Верните документ Лиги исследователей Торрену Квадратной Челюсти в Телсамар.','Ха! Надеюсь, им было приятно узнать о том, насколько низко мы оцениваем исходящую от них угрозу! Надо признать, что этот документ устарел, но не стал от этого менее забавным.$B$BКонечно, мы в любом случае наградим тебя за его возвращение – мы очень ценим твою помощь!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Документ Лиги исследователей (6 из 6)',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Документ написан на гербовой бумаге Лиги исследователей, в нем перечислены оценки различных угроз в Лок Модане. Пятна копоти свидетельствуют о том, что документ, скорее всего, был украден местными шпионами из клана Черного Железа.$b$bВы вспоминаете, что в здании Лиги исследователей в Телсамаре упоминали о пропавших документах.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните документ Лиги исследователей Торрену Квадратной Челюсти в Телсамар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ха! Надеюсь, им было приятно узнать о том, насколько низко мы оцениваем исходящую от них угрозу! Надо признать, что этот документ устарел, но не стал от этого менее забавным.$B$BКонечно, мы в любом случае наградим тебя за его возвращение – мы очень ценим твою помощь!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13660,'Документ Лиги исследователей (5 из 6)','Документ написан на гербовой бумаге Лиги исследователей, он содержит полный список артефактов, найденных рабочими Сталекрута на юго-востоке Лок Модана. Пятна копоти свидетельствуют о том, что документ, скорее всего, был украден местными шпионами из клана Черного Железа.$b$bВы вспоминаете, что в здании Лиги исследователей в Телсамаре упоминали о пропавших документах.','Верните документ Лиги исследователей Торрену Квадратной Челюсти в Телсамар.','Наши записи об артефактах! Я всерьез опасался, что клан Черного Железа может попытаться украсть наши артефакты, обладая этой информацией.$B$BСпасибо, что вернул нам этот документ. Вот, возьми эти деньги в знак нашей благодарности.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Документ Лиги исследователей (5 из 6)',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Документ написан на гербовой бумаге Лиги исследователей, он содержит полный список артефактов, найденных рабочими Сталекрута на юго-востоке Лок Модана. Пятна копоти свидетельствуют о том, что документ, скорее всего, был украден местными шпионами из клана Черного Железа.$b$bВы вспоминаете, что в здании Лиги исследователей в Телсамаре упоминали о пропавших документах.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните документ Лиги исследователей Торрену Квадратной Челюсти в Телсамар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Наши записи об артефактах! Я всерьез опасался, что клан Черного Железа может попытаться украсть наши артефакты, обладая этой информацией.$B$BСпасибо, что вернул нам этот документ. Вот, возьми эти деньги в знак нашей благодарности.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (13661,'Сердечная признательность','Ты $gнашел:нашла; все документы! Мы не знаем, как и благодарить тебя за помощь... мысль о том, что клан Черного Железа сможет воспользоваться этой информацией, приводила нас в отчаяние. Приятно знать, что еще некоторое время они будут атаковать вслепую.$b$bВ благодарность за все твои свершения мы ходим сделать тебе подарок. Артефакт... один из тех, что мы нашли на раскопках. Вся Лига исследователей признательна тебе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сердечная признательность',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gнашел:нашла; все документы! Мы не знаем, как и благодарить тебя за помощь... мысль о том, что клан Черного Железа сможет воспользоваться этой информацией, приводила нас в отчаяние. Приятно знать, что еще некоторое время они будут атаковать вслепую.$b$bВ благодарность за все твои свершения мы ходим сделать тебе подарок. Артефакт... один из тех, что мы нашли на раскопках. Вся Лига исследователей признательна тебе.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13662,'Завоевать благосклонность','Так, давай сюда окалину!','Ты быстро продвигаешься по служебной лестнице в Братстве, $R. Ты начинаешь в самом деле завоевывать нашу благосклонность.$B$BЕсли хочешь заслужить еще большее уважение, слушай внимательно.$B$BМы хотим повысить качество нашего огненного плавня путем добавления в него окалины черного железа. Окалину можно добыть в Глубинах Черной горы.$B$BПринеси мне как можно больше!','Вернитесь к мастеру-кузнецу Закалону в Тлеющее ущелье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Завоевать благосклонность',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так, давай сюда окалину!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты быстро продвигаешься по служебной лестнице в Братстве, $R. Ты начинаешь в самом деле завоевывать нашу благосклонность.$B$BЕсли хочешь заслужить еще большее уважение, слушай внимательно.$B$BМы хотим повысить качество нашего огненного плавня путем добавления в него окалины черного железа. Окалину можно добыть в Глубинах Черной горы.$B$BПринеси мне как можно больше!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру-кузнецу Закалону в Тлеющее ущелье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (13663,'Приказы для Черного рыцаря','Мы должны выяснить, кто послал Черного рыцаря на турнир, и чего именно добивался его хозяин, убивая наших участников.$B$BСовет Кирин-Тора оказал нам содействие в расследовании этого дела.$B$BОни предоставили нам эту волшебную уздечку. Отнеси ее к палатке Черного рыцаря, что на восточном краю Ристалища, с ее помощью приручи его грифона. Магия уздечки заставит грифона отнести тебя к жилищу хозяина рыцаря. Обыщи это место и возвращайся ко мне.','Воспользуйтесь волшебной уздечкой, чтобы подчинить грифона Черного рыцаря и попасть к дому его хозяина. Как только вы попадете на место, найдите украденное приглашение на турнир и приказы для Черного рыцаря, после чего отнесите их рыцарю Райдалле в Серебряный павильон на Ристалище Серебряного Турнира.','<Рыцарь Райдалла бледнеет, читая приказы.>$B$BЭто может означать только одно: Черный рыцарь – член Культа Проклятых! Его послал Артас, чтобы сорвать проведение турнира.$B$BНо он уже проявил себя как могучий воин, и тебе потребуется все твое искусство, чтобы одолеть его. Возвращайся, когда получишь звание чемпиона, и мы постараемся найти способ избавиться от этой угрозы.','Вернитесь к рыцарю Райдалле на Ристалище Серебряного турнира, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приказы для Черного рыцаря',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы должны выяснить, кто послал Черного рыцаря на турнир, и чего именно добивался его хозяин, убивая наших участников.$B$BСовет Кирин-Тора оказал нам содействие в расследовании этого дела.$B$BОни предоставили нам эту волшебную уздечку. Отнеси ее к палатке Черного рыцаря, что на восточном краю Ристалища, с ее помощью приручи его грифона. Магия уздечки заставит грифона отнести тебя к жилищу хозяина рыцаря. Обыщи это место и возвращайся ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь волшебной уздечкой, чтобы подчинить грифона Черного рыцаря и попасть к дому его хозяина. Как только вы попадете на место, найдите украденное приглашение на турнир и приказы для Черного рыцаря, после чего отнесите их рыцарю Райдалле в Серебряный павильон на Ристалище Серебряного Турнира.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Рыцарь Райдалла бледнеет, читая приказы.>$B$BЭто может означать только одно: Черный рыцарь – член Культа Проклятых! Его послал Артас, чтобы сорвать проведение турнира.$B$BНо он уже проявил себя как могучий воин, и тебе потребуется все твое искусство, чтобы одолеть его. Возвращайся, когда получишь звание чемпиона, и мы постараемся найти способ избавиться от этой угрозы.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к рыцарю Райдалле на Ристалище Серебряного турнира, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (13664,'Падение Черного рыцаря','Мы должны положить конец зловещим планам Черного рыцаря и показать всем противникам, что мы не потерпим хладнокровного убийства наших лучших воинов!$B$BБрось вызов Черному рыцарю и одолей его в бою, $n.$B$BДля этой битвы я одолжу тебе моего боевого скакуна Серебряного Рассвета, который стоит в стойлах.$B$BПоговори с оруженосцем Кейвином на южной стороне Ристалища. Он вызовет Черного рыцаря на бой, и тебе останется лишь заставить того заплатить за преступления.','Одержите победу над Черным рыцарем, после чего поговорите с рыцарем Райдаллой в Серебряном павильоне на Ристалище Серебряного турнира.','После смерти Черного рыцаря турниру больше ничто не угрожает. Теперь чемпионы Орды и Альянса смогут проявить себя в состязаниях и подготовиться к тому дню, когда Артас и его приспешники будут повержены навсегда.$B$BЯ благодарю тебя от лица всего Серебряного Авангарда и тех, кто откликнулся на его призыв.','Вернитесь к рыцарю Райдалле на Ристалище Серебряного турнира, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Падение Черного рыцаря',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы должны положить конец зловещим планам Черного рыцаря и показать всем противникам, что мы не потерпим хладнокровного убийства наших лучших воинов!$B$BБрось вызов Черному рыцарю и одолей его в бою, $n.$B$BДля этой битвы я одолжу тебе моего боевого скакуна Серебряного Рассвета, который стоит в стойлах.$B$BПоговори с оруженосцем Кейвином на южной стороне Ристалища. Он вызовет Черного рыцаря на бой, и тебе останется лишь заставить того заплатить за преступления.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Одержите победу над Черным рыцарем, после чего поговорите с рыцарем Райдаллой в Серебряном павильоне на Ристалище Серебряного турнира.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','После смерти Черного рыцаря турниру больше ничто не угрожает. Теперь чемпионы Орды и Альянса смогут проявить себя в состязаниях и подготовиться к тому дню, когда Артас и его приспешники будут повержены навсегда.$B$BЯ благодарю тебя от лица всего Серебряного Авангарда и тех, кто откликнулся на его призыв.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к рыцарю Райдалле на Ристалище Серебряного турнира, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (13665,'Великая битва','Великая битва – одно из самых важных соревнований турнира. Люди Штормграда превозносят своих рыцарей и надеются на нашу победу. Лучший способ усовершенствовать свои навыки боя – бросить вызов искателям славы, представляющим другие столицы Альянса.$B$BПослушай моего совета – иди в стойла за павильоном, оседлай штормградского скакуна и брось вызов искателям славы. Ты найдешь их прямо за этой палаткой на Арене искателей славы Альянса.','Вернитесь к капитану Джозефу Холли на Ристалище Серебряного турнира в Ледяную Корону.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Великая битва',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Великая битва – одно из самых важных соревнований турнира. Люди Штормграда превозносят своих рыцарей и надеются на нашу победу. Лучший способ усовершенствовать свои навыки боя – бросить вызов искателям славы, представляющим другие столицы Альянса.$B$BПослушай моего совета – иди в стойла за павильоном, оседлай штормградского скакуна и брось вызов искателям славы. Ты найдешь их прямо за этой палаткой на Арене искателей славы Альянса.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Джозефу Холли на Ристалище Серебряного турнира в Ледяную Корону.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (13666,'Клинок, достойный чемпиона','Некоторые бойцы полагают, что древнее оружие, выкованное в Нордсколе, может принести удачу в состязании. Я же согласился помочь им в поисках этих легендарных клинков.$B$BЕсть одна древняя легенда о деве из Ясеневого озера, которая охраняет могущественный клинок. Говорят, будто страшное проклятие превратило ее в лягушку, чтобы никто больше не смог коснуться этого меча. Теперь она живет среди прудовых лягушек на берегу Ясеневого озера, что к востоку от Ясеневой заставы... И только поцелуй любви, дарованный от чистого сердца, может разрушить злые чары. Только не забудь воспользоваться этим бальзамом для губ – иначе покроешься бородавками.','Вернитесь к чародею Таэлису на Ристалище Серебряного турнира в Ледяную Корону.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Клинок, достойный чемпиона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Некоторые бойцы полагают, что древнее оружие, выкованное в Нордсколе, может принести удачу в состязании. Я же согласился помочь им в поисках этих легендарных клинков.$B$BЕсть одна древняя легенда о деве из Ясеневого озера, которая охраняет могущественный клинок. Говорят, будто страшное проклятие превратило ее в лягушку, чтобы никто больше не смог коснуться этого меча. Теперь она живет среди прудовых лягушек на берегу Ясеневого озера, что к востоку от Ясеневой заставы... И только поцелуй любви, дарованный от чистого сердца, может разрушить злые чары. Только не забудь воспользоваться этим бальзамом для губ – иначе покроешься бородавками.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к чародею Таэлису на Ристалище Серебряного турнира в Ледяную Корону.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (13667,'Серебряный Турнир','Значит, в старых сказках есть доля правды? Во всяком случае, меч действительно прекрасный! Молодец, $N. Как же повезет тому чемпиону, которому в бою послужит этот клинок!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Серебряный Турнир',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Значит, в старых сказках есть доля правды? Во всяком случае, меч действительно прекрасный! Молодец, $N. Как же повезет тому чемпиону, которому в бою послужит этот клинок!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13668,'Серебряный Турнир','Мы пригласили тебя сюда для того, чтобы испытать твою ловкость и отвагу в поединках с теми, кто противостоит Плети день за днем. До сих пор мы сражались под разными знаменами, но теперь настал день, когда все герои должны скрестить мечи и проверить свою готовность перед битвой с нашим общим врагом.$B$BМагистр Эдиен Солнечная Низина является представителем Похитителей Солнца на турнире. Он внесет твое имя в списки и займется начальной подготовкой. Ищи его в огромном шатре Орды в юго-восточной части Ристалища.','Чтобы принять участие в турнире, поговорите с магистром Эдиеном Солнечной Низиной в шатре Орды на Ристалище Серебряного турнира, он внесет ваше имя в списки.','Я внес твое имя в списки, Летианиу. Теперь ты можешь тренироваться как и другие претенденты на участие в турнире и оттачивать навыки верхового поединка. Докажи, что ты $Gдостоин:достойна; – и сможешь участвовать в соревнованиях низкого ранга, защищая честь своей столицы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Серебряный Турнир',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы пригласили тебя сюда для того, чтобы испытать твою ловкость и отвагу в поединках с теми, кто противостоит Плети день за днем. До сих пор мы сражались под разными знаменами, но теперь настал день, когда все герои должны скрестить мечи и проверить свою готовность перед битвой с нашим общим врагом.$B$BМагистр Эдиен Солнечная Низина является представителем Похитителей Солнца на турнире. Он внесет твое имя в списки и займется начальной подготовкой. Ищи его в огромном шатре Орды в юго-восточной части Ристалища.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Чтобы принять участие в турнире, поговорите с магистром Эдиеном Солнечной Низиной в шатре Орды на Ристалище Серебряного турнира, он внесет ваше имя в списки.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я внес твое имя в списки, Летианиу. Теперь ты можешь тренироваться как и другие претенденты на участие в турнире и оттачивать навыки верхового поединка. Докажи, что ты $Gдостоин:достойна; – и сможешь участвовать в соревнованиях низкого ранга, защищая честь своей столицы.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13669,'Достойное оружие','Похоже, нашим чемпионам понравились древние мечи, выкованные в Нордсколе.$B$BДо меня дошли слухи, что некая дева дарит путникам ценные вещицы в обмен на букетик зимних гиацинтов. Эти цветы растут только на льду, идущем вниз по реке от Железной плотины, на северо-западе от границы между Ледяной Короной и лесом Хрустальной Песни. Собери цветы и отнеси их к озеру Драк\'Мар, оно расположено в северо-восточной части Драконьего Погоста, почти на границе с Зул\'Драком и Седыми холмами. Посмотрим, одарит ли тебя дева достойным клинком.','Это на самом деле потрясающий клинок – острый и отлично сбалансированный. Теперь я понимаю, почему эти мечи так ценятся среди чемпионов Альянса.','Так барды говорят правду? Меч действительно существует?','Вернитесь к чародею Таэлису на Ристалище Серебряного турнира в Ледяную Корону.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Достойное оружие',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Похоже, нашим чемпионам понравились древние мечи, выкованные в Нордсколе.$B$BДо меня дошли слухи, что некая дева дарит путникам ценные вещицы в обмен на букетик зимних гиацинтов. Эти цветы растут только на льду, идущем вниз по реке от Железной плотины, на северо-западе от границы между Ледяной Короной и лесом Хрустальной Песни. Собери цветы и отнеси их к озеру Драк\'Мар, оно расположено в северо-восточной части Драконьего Погоста, почти на границе с Зул\'Драком и Седыми холмами. Посмотрим, одарит ли тебя дева достойным клинком.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это на самом деле потрясающий клинок – острый и отлично сбалансированный. Теперь я понимаю, почему эти мечи так ценятся среди чемпионов Альянса.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Так барды говорят правду? Меч действительно существует?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к чародею Таэлису на Ристалище Серебряного турнира в Ледяную Корону.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13670,'Клинок Зимы','Искатель славы не обманул – это прекрасный клинок. И откуда он только узнал про него? Неважно; он сослужит добрую службу новому владельцу. Будет справедливо, если он достанется абсолютному чемпиону Стальгорна.','Ну как? Получилось добыть меч?','Вернитесь к чародею Таэлису на Ристалище Серебряного турнира в Ледяную Корону.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Клинок Зимы',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Искатель славы не обманул – это прекрасный клинок. И откуда он только узнал про него? Неважно; он сослужит добрую службу новому владельцу. Будет справедливо, если он достанется абсолютному чемпиону Стальгорна.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как? Получилось добыть меч?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к чародею Таэлису на Ристалище Серебряного турнира в Ледяную Корону.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13671,'Тренировка на поле боя','Турнир – это возможность похвалиться своей силой перед другими героями, но стоит помнить и о том, что главный враг – Плеть – не дремлет. Ты оттачиваешь мастерство в поединках с товарищами, но тебе столь же необходимо совершенствоваться в битвах с неприятелем. Продемонстрируй свою отвагу, сразившись с Плетью – и ты заслужишь право участвовать в турнире. $B$BОтправляйся в Ледяную Корону и убей несколько приспешников Плети. Но не пересекай границы Зоны бомбардировки – тебе не удастся справиться со столь многочисленным противником.','Убейте 8 воинов Плети в Ледяной Короне по заданию Аварета Молниеносного Удара из Павильона Серебряного союза на Ристалище Серебряного турнира. Вы можете найти их в любой области Ледяной Короны, за исключением зоны бомбардировки.','Ты испытал себя в бою против Плети?','Вернитесь к Аварету Молниеносному Удару в Ледяную Корону.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тренировка на поле боя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Турнир – это возможность похвалиться своей силой перед другими героями, но стоит помнить и о том, что главный враг – Плеть – не дремлет. Ты оттачиваешь мастерство в поединках с товарищами, но тебе столь же необходимо совершенствоваться в битвах с неприятелем. Продемонстрируй свою отвагу, сразившись с Плетью – и ты заслужишь право участвовать в турнире. $B$BОтправляйся в Ледяную Корону и убей несколько приспешников Плети. Но не пересекай границы Зоны бомбардировки – тебе не удастся справиться со столь многочисленным противником.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 воинов Плети в Ледяной Короне по заданию Аварета Молниеносного Удара из Павильона Серебряного союза на Ристалище Серебряного турнира. Вы можете найти их в любой области Ледяной Короны, за исключением зоны бомбардировки.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты испытал себя в бою против Плети?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аварету Молниеносному Удару в Ледяную Корону.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13672,'Подготовка к испытанию','Закончив тренировки, ты получишь возможность пройти испытания претендентов, которые определят твой уровень ведения верхового боя и покажут, стоит ли тебе искать славы. Если ты успешно выдержишь этот экзамен, то сможешь присоединиться к делегации твоего города в качестве искателя славы.$B$BВозвращайся ко мне, когда будешь $gготов:готова; к испытаниям.','Хорошо, я дам необходимые распоряжения.','Ты хочешь пройти испытание претендентов?','Вернитесь к чародею Таэлису на Ристалище Серебряного турнира в Ледяную Корону.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подготовка к испытанию',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Закончив тренировки, ты получишь возможность пройти испытания претендентов, которые определят твой уровень ведения верхового боя и покажут, стоит ли тебе искать славы. Если ты успешно выдержишь этот экзамен, то сможешь присоединиться к делегации твоего города в качестве искателя славы.$B$BВозвращайся ко мне, когда будешь $gготов:готова; к испытаниям.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо, я дам необходимые распоряжения.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты хочешь пройти испытание претендентов?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к чародею Таэлису на Ристалище Серебряного турнира в Ледяную Корону.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (13673,'Клинок, достойный чемпиона','Некоторые бойцы полагают, что древнее оружие, выкованное в Нордсколе, может принести удачу в состязании. Я же согласился помочь им в поисках этих легендарных клинков.$B$BЕсть одна древняя легенда о деве из Седых холмов, которая охраняет могущественный клинок. Говорят, будто страшное проклятие превратило ее в лягушку, чтобы никто больше не смог коснуться этого меча. Теперь она живет среди прудовых лягушек на берегу Ясеневого озера, что к востоку от Ясеневой заставы... И только поцелуй любви, дарованный от чистого сердца, может разрушить злые чары. Только не забудь воспользоваться этим бальзамом для губ – иначе покроешься бородавками.','Вернитесь к магистру Эдиену Солнечной Низине на Ристалище Серебряного турнира, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Клинок, достойный чемпиона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Некоторые бойцы полагают, что древнее оружие, выкованное в Нордсколе, может принести удачу в состязании. Я же согласился помочь им в поисках этих легендарных клинков.$B$BЕсть одна древняя легенда о деве из Седых холмов, которая охраняет могущественный клинок. Говорят, будто страшное проклятие превратило ее в лягушку, чтобы никто больше не смог коснуться этого меча. Теперь она живет среди прудовых лягушек на берегу Ясеневого озера, что к востоку от Ясеневой заставы... И только поцелуй любви, дарованный от чистого сердца, может разрушить злые чары. Только не забудь воспользоваться этим бальзамом для губ – иначе покроешься бородавками.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к магистру Эдиену Солнечной Низине на Ристалище Серебряного турнира, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13674,'Достойное оружие','Похоже, нашим чемпионам понравились древние мечи, выкованные в Нордсколе.$B$BДо меня дошли слухи, что некая дева дарит путникам ценные вещицы в обмен на букетик зимних гиацинтов. Эти цветы растут только на льду, идущем вниз по реке от Железной плотины, на северо-западе от границы между Ледяной Короной и лесом Хрустальной Песни. Собери цветы и отнеси их к озеру Драк\'Мар, оно расположено в северо-восточной части Драконьего Погоста, почти на границе с Зул\'Драком и Седыми холмами. Посмотрим, одарит ли тебя дева достойным клинком.','Принесите меч Драк\'Мара магистру Эдиену Солнечной Низине в Павильон Похитителей Солнца на Ристалище Серебряного турнира.','Это на самом деле потрясающий клинок – острый и отлично сбалансированный. Теперь я понимаю, почему эти мечи так ценятся среди чемпионов Альянса.','Так барды говорят правду? Меч действительно существует?','Вернитесь к магистру Эдиену Солнечной Низине на Ристалище Серебряного турнира, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Достойное оружие',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Похоже, нашим чемпионам понравились древние мечи, выкованные в Нордсколе.$B$BДо меня дошли слухи, что некая дева дарит путникам ценные вещицы в обмен на букетик зимних гиацинтов. Эти цветы растут только на льду, идущем вниз по реке от Железной плотины, на северо-западе от границы между Ледяной Короной и лесом Хрустальной Песни. Собери цветы и отнеси их к озеру Драк\'Мар, оно расположено в северо-восточной части Драконьего Погоста, почти на границе с Зул\'Драком и Седыми холмами. Посмотрим, одарит ли тебя дева достойным клинком.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите меч Драк\'Мара магистру Эдиену Солнечной Низине в Павильон Похитителей Солнца на Ристалище Серебряного турнира.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это на самом деле потрясающий клинок – острый и отлично сбалансированный. Теперь я понимаю, почему эти мечи так ценятся среди чемпионов Альянса.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Так барды говорят правду? Меч действительно существует?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к магистру Эдиену Солнечной Низине на Ристалище Серебряного турнира, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13675,'Клинок Зимы','Магистр Эдиен Солнечная Низина из Павильона Похитителей Солнца на Ристалище Серебряного турнира просит вас принести Клинок Зимы.','Искатель славы не обманул – это прекрасный клинок. И откуда он только узнал про него? Неважно, он сослужит добрую службу новому владельцу. Будет справедливо, если он достанется абсолютному чемпиону Оргриммара.','Ну как? Получилось добыть меч?','Вернитесь к магистру Эдиену Солнечной Низине на Ристалище Серебряного турнира, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Клинок Зимы',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Магистр Эдиен Солнечная Низина из Павильона Похитителей Солнца на Ристалище Серебряного турнира просит вас принести Клинок Зимы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Искатель славы не обманул – это прекрасный клинок. И откуда он только узнал про него? Неважно, он сослужит добрую службу новому владельцу. Будет справедливо, если он достанется абсолютному чемпиону Оргриммара.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как? Получилось добыть меч?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к магистру Эдиену Солнечной Низине на Ристалище Серебряного турнира, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13676,'Тренировка на поле боя','Турнир – это возможность похвалиться своей силой перед другими героями, но стоит помнить и о том, что главный враг – Плеть – не дремлет. Ты оттачиваешь мастерство в поединках с товарищами, но тебе столь же необходимо совершенствоваться в битвах с неприятелем. Продемонстрируй свою отвагу, сразившись с Плетью – и ты заслужишь право участвовать в турнире. $B$BОтправляйся в Ледяную Корону и убей несколько приспешников Плети. Но не пересекай границы Зоны бомбардировки – тебе не удастся справиться со столь многочисленным противником.','Убейте 8 воинов Плети в Ледяной Короне по заданию Амариэля Верного Солнцу из Павильона Похитителей Солнца на Ристалище Серебряного турнира. Вы можете найти их в любой области Ледяной Короны, за исключением зоны бомбардировки.','Вернитесь к Амариэлю Верному Солнцу на Ристалище Серебряного турнира, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тренировка на поле боя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Турнир – это возможность похвалиться своей силой перед другими героями, но стоит помнить и о том, что главный враг – Плеть – не дремлет. Ты оттачиваешь мастерство в поединках с товарищами, но тебе столь же необходимо совершенствоваться в битвах с неприятелем. Продемонстрируй свою отвагу, сразившись с Плетью – и ты заслужишь право участвовать в турнире. $B$BОтправляйся в Ледяную Корону и убей несколько приспешников Плети. Но не пересекай границы Зоны бомбардировки – тебе не удастся справиться со столь многочисленным противником.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 воинов Плети в Ледяной Короне по заданию Амариэля Верного Солнцу из Павильона Похитителей Солнца на Ристалище Серебряного турнира. Вы можете найти их в любой области Ледяной Короны, за исключением зоны бомбардировки.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Амариэлю Верному Солнцу на Ристалище Серебряного турнира, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (13677,'Большая тренировка','Большая часть состязаний турнира требует от участников мастерства в управлении верховым животным. Чтобы познакомить тебя с этим видом поединков, мы разместили тренировочные манекены в северной части Ристалища турнира.$B$BЗайди в стойла на севере площадки, рядом с главной ареной, вооружись копьем и оседлай крылобега Похитителей Солнца. Познакомься со всеми доступными приемами и используй новые знания в тренировке. Для освоения новых приемов можешь использовать все три вида манекенов.','Вернитесь к Галатии Сияющий Рассвет на Ристалище Серебряного турнира, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Большая тренировка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Большая часть состязаний турнира требует от участников мастерства в управлении верховым животным. Чтобы познакомить тебя с этим видом поединков, мы разместили тренировочные манекены в северной части Ристалища турнира.$B$BЗайди в стойла на севере площадки, рядом с главной ареной, вооружись копьем и оседлай крылобега Похитителей Солнца. Познакомься со всеми доступными приемами и используй новые знания в тренировке. Для освоения новых приемов можешь использовать все три вида манекенов.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Галатии Сияющий Рассвет на Ристалище Серебряного турнира, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13678,'Подготовка к испытанию','Закончив тренировки, ты получишь возможность пройти испытания претендентов, которые определят твой уровень ведения верхового боя и покажут, стоит ли тебе искать славы. Если ты успешно выдержишь этот экзамен, то сможешь присоединиться к делегации твоего города в качестве искателя славы.$B$BВозвращайся ко мне, когда будешь $gготов:готова; к испытаниям.','Чтобы продемонстрировать свою готовность пройти испытание претендентов, отдайте 15 печатей претендента магистру Эдиену Солнечной Низине из Павильона Похитителей Солнца на Ристалище Серебряного турнира.','Ты $Gпоказал:показала; свою силу в бою, $N, и твой пример вдохновит других претендентов, желающих сражаться под знаменами Альянса.','Ты хочешь пройти испытание претендентов?','Вернитесь к магистру Эдиену Солнечной Низине на Ристалище Серебряного турнира, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подготовка к испытанию',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Закончив тренировки, ты получишь возможность пройти испытания претендентов, которые определят твой уровень ведения верхового боя и покажут, стоит ли тебе искать славы. Если ты успешно выдержишь этот экзамен, то сможешь присоединиться к делегации твоего города в качестве искателя славы.$B$BВозвращайся ко мне, когда будешь $gготов:готова; к испытаниям.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Чтобы продемонстрировать свою готовность пройти испытание претендентов, отдайте 15 печатей претендента магистру Эдиену Солнечной Низине из Павильона Похитителей Солнца на Ристалище Серебряного турнира.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты $Gпоказал:показала; свою силу в бою, $N, и твой пример вдохновит других претендентов, желающих сражаться под знаменами Альянса.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты хочешь пройти испытание претендентов?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к магистру Эдиену Солнечной Низине на Ристалище Серебряного турнира, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13679,'Испытание претендента','Ты очень $gприлежно занимался:прилежно занималась; на тренировках, $n, и теперь пришло время проверить твои навыки верхового поединка в бою против опытного противника.$B$BНа Арене претендентов в северной части Ристалища тебя ждет мальчик – оруженосец Давид. Он проверит твою готовность к сражению и вызовет того, с кем тебе предстоит сразиться.$B$BУдачи, $n. Да не споткнется твой конь, и да будет крепкой твоя рука.','Мои поздравления, $N. Все испытания пройдены и ты полностью заслуживаешь право носить титул искателя славы.','Вы столкнулись со своим вызовом?','Вернитесь к чародею Таэлису на Ристалище Серебряного турнира в Ледяную Корону.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Испытание претендента',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты очень $gприлежно занимался:прилежно занималась; на тренировках, $n, и теперь пришло время проверить твои навыки верхового поединка в бою против опытного противника.$B$BНа Арене претендентов в северной части Ристалища тебя ждет мальчик – оруженосец Давид. Он проверит твою готовность к сражению и вызовет того, с кем тебе предстоит сразиться.$B$BУдачи, $n. Да не споткнется твой конь, и да будет крепкой твоя рука.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мои поздравления, $N. Все испытания пройдены и ты полностью заслуживаешь право носить титул искателя славы.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы столкнулись со своим вызовом?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к чародею Таэлису на Ристалище Серебряного турнира в Ледяную Корону.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13680,'Испытание претендента','Ты очень $gприлежно занимался:прилежно занималась; на тренировках, $n, и теперь пришло время проверить твои навыки верхового поединка в бою против опытного противника.$B$BВооружись копьем и оседлай крылобега Похитителей Солнца.$B$BНа Арене претендентов в северной части Ристалища тебя ждет мальчик – оруженосец Давид. Он проверит твою готовность к сражению и вызовет того, с кем тебе предстоит сразиться.$B$BУдачи, $n. Да не споткнется твой конь, и да будет крепкой твоя рука.','Поговорите с оруженосцем Давидом, чтобы вызвать на поединок вашего противника. Как только вы победите искателя славы Серебряного Авангарда, вернитесь к магистру Эдиену Солнечной Низине в Павильон Похитителей Солнца на Ристалище Серебряного Турнира.','Мои поздравления, $N. Все испытания пройдены и ты полностью заслуживаешь право носить титул искателя славы.','Вы столкнулись со своим вызовом?','Вернитесь к магистру Эдиену Солнечной Низине на Ристалище Серебряного турнира, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Испытание претендента',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты очень $gприлежно занимался:прилежно занималась; на тренировках, $n, и теперь пришло время проверить твои навыки верхового поединка в бою против опытного противника.$B$BВооружись копьем и оседлай крылобега Похитителей Солнца.$B$BНа Арене претендентов в северной части Ристалища тебя ждет мальчик – оруженосец Давид. Он проверит твою готовность к сражению и вызовет того, с кем тебе предстоит сразиться.$B$BУдачи, $n. Да не споткнется твой конь, и да будет крепкой твоя рука.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с оруженосцем Давидом, чтобы вызвать на поединок вашего противника. Как только вы победите искателя славы Серебряного Авангарда, вернитесь к магистру Эдиену Солнечной Низине в Павильон Похитителей Солнца на Ристалище Серебряного Турнира.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мои поздравления, $N. Все испытания пройдены и ты полностью заслуживаешь право носить титул искателя славы.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы столкнулись со своим вызовом?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к магистру Эдиену Солнечной Низине на Ристалище Серебряного турнира, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13681,'Обломки стен Ульдуара','Принесите 15 небольших камней Боззлу Рвизасову на Ристалище Серебряного турнира.','Эти должны подойти. Только не болтай этим крестоносцам о том, откуда ты их $Gвзял:взяла;. Я уверен, что они расстроятся. Но, эй, это не похоже на то, что титаны вернулись за ними. Это честная игра, говорю я. Хорошая работа, $N.','Ты достал этот камень?','Вернитесь к Боззлу Рвизасову на Ристалище Серебряного турнира в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обломки стен Ульдуара',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 15 небольших камней Боззлу Рвизасову на Ристалище Серебряного турнира.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Эти должны подойти. Только не болтай этим крестоносцам о том, откуда ты их $Gвзял:взяла;. Я уверен, что они расстроятся. Но, эй, это не похоже на то, что титаны вернулись за ними. Это честная игра, говорю я. Хорошая работа, $N.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты достал этот камень?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Боззлу Рвизасову на Ристалище Серебряного турнира в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13682,'Атака с воздуха','После того как тебе удалось обнаружить лазутчика Культа Проклятых, верховный лорд Тирион Фордринг приказал удвоить охрану. Он не верит, что их остановит поражение Черного рыцаря.$B$BВскоре после этого наши воздушные разведчики видели Ледяную Пасть – змея, который возглавляет отряд наемников Культа. Его видели на юго-западе, между Железным валом и Алдур\'таром.','Эдрик Чистый из Серебряного павильона на Ристалище Серебряного турнира просит вас уничтожить Ледяную Пасть и 3 бомбистов-сектантов.','Вы одержали победили отряд сектантов Культа Проклятых?','Вернитесь к Эдрику Чистому на Ристалище Серебряного турнира в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Атака с воздуха',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','После того как тебе удалось обнаружить лазутчика Культа Проклятых, верховный лорд Тирион Фордринг приказал удвоить охрану. Он не верит, что их остановит поражение Черного рыцаря.$B$BВскоре после этого наши воздушные разведчики видели Ледяную Пасть – змея, который возглавляет отряд наемников Культа. Его видели на юго-западе, между Железным валом и Алдур\'таром.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Эдрик Чистый из Серебряного павильона на Ристалище Серебряного турнира просит вас уничтожить Ледяную Пасть и 3 бомбистов-сектантов.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы одержали победили отряд сектантов Культа Проклятых?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Эдрику Чистому на Ристалище Серебряного турнира в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13683,'Прервать ритуалы','Я случайно услышал слова Иллианы и таким образом узнал об ее утрате. Понимаю, она хочет отомстить. Но если она избрала тебя своим орудием, возможно, ты заодно согласишься оказать нам услугу?$B$BНе сомневаюсь, тебе уже встречались сатиры Сатирнаара и Ксавиана. Эти существа проводят зловещие ритуалы, и у меня есть все основания полагать, что с их помощью они превращают захваченных ночных эльфов в себе подобных. Мы, дренеи, не можем смириться с проявлениями магии скверны.$B$BПрошу тебя, когда отправишься туда, уничтожь их ритуальные самоцветы!','Уничтожьте 8 ритуальных самоцветов.','Вернитесь к анахорету Буурку в Лесную Песнь, что в Ясеневом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прервать ритуалы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я случайно услышал слова Иллианы и таким образом узнал об ее утрате. Понимаю, она хочет отомстить. Но если она избрала тебя своим орудием, возможно, ты заодно согласишься оказать нам услугу?$B$BНе сомневаюсь, тебе уже встречались сатиры Сатирнаара и Ксавиана. Эти существа проводят зловещие ритуалы, и у меня есть все основания полагать, что с их помощью они превращают захваченных ночных эльфов в себе подобных. Мы, дренеи, не можем смириться с проявлениями магии скверны.$B$BПрошу тебя, когда отправишься туда, уничтожь их ритуальные самоцветы!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 8 ритуальных самоцветов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к анахорету Буурку в Лесную Песнь, что в Ясеневом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13684,'Искатель славы из Штормграда','Ты достойно $gсражался:сражалась; под знаменами Штормграда, $n. Теперь тебе следует предстать перед маршалом Якобом Алерием. Это глава делегации Штормграда и его абсолютный чемпион. Он включит тебя в состав участников соревнования, будет наблюдать за твоими тренировками и испытывать на прочность.$B$BДля меня было честью работать с тобой, $n. Удачи тебе на состязаниях!','Если вы хотите стать искателем славы Штормграда, поговорите с маршалом Якобом Алерием на Ристалище Серебряного турнира.','Добро пожаловать в делегацию Штормграда, $N. Мы очень рады, что ты будешь тренироваться и соревноваться вместе с нами.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Искатель славы из Штормграда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты достойно $gсражался:сражалась; под знаменами Штормграда, $n. Теперь тебе следует предстать перед маршалом Якобом Алерием. Это глава делегации Штормграда и его абсолютный чемпион. Он включит тебя в состав участников соревнования, будет наблюдать за твоими тренировками и испытывать на прочность.$B$BДля меня было честью работать с тобой, $n. Удачи тебе на состязаниях!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Если вы хотите стать искателем славы Штормграда, поговорите с маршалом Якобом Алерием на Ристалище Серебряного турнира.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Добро пожаловать в делегацию Штормграда, $N. Мы очень рады, что ты будешь тренироваться и соревноваться вместе с нами.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13685,'Искатель славы из Стальгорна','Ты достойно $gсражался:сражалась; под знаменами Стальгорна, $n. Теперь тебе следует предстать перед Ланой Твердомолот. Это глава делегации Стальгорна и его абсолютный чемпион. Она включит тебя в состав участников соревнования, будет наблюдать за твоими тренировками и испытывать на прочность.$B$BДля меня было честью работать с тобой, $n. Удачи тебе на состязаниях!','Если вы хотите стать искателем славы Стальгорна, поговорите с Ланой Твердомолот на Ристалище Серебряного турнира.','Добро пожаловать в делегацию. В Стальгорн нужны конкуренты, как вы, чтобы одержать победу в турнире.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Искатель славы из Стальгорна',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты достойно $gсражался:сражалась; под знаменами Стальгорна, $n. Теперь тебе следует предстать перед Ланой Твердомолот. Это глава делегации Стальгорна и его абсолютный чемпион. Она включит тебя в состав участников соревнования, будет наблюдать за твоими тренировками и испытывать на прочность.$B$BДля меня было честью работать с тобой, $n. Удачи тебе на состязаниях!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Если вы хотите стать искателем славы Стальгорна, поговорите с Ланой Твердомолот на Ристалище Серебряного турнира.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Добро пожаловать в делегацию. В Стальгорн нужны конкуренты, как вы, чтобы одержать победу в турнире.',`offerrewardtext_loc8`);
