INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (13687,'Horde Tournament Eligibility Marker') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Horde Tournament Eligibility Marker',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13688,'Искатель славы из Гномрегана','Ты достойно $gсражался:сражалась; под знаменами Гномрегана, $n. Теперь тебе следует предстать перед Амброзом Искрокрутом. Это глава делегации Гномрегана и его абсолютный чемпион. Он включит тебя в состав участников соревнования, будет наблюдать за твоими тренировками и испытывать на прочность.$B$BДля меня было честью работать с тобой, $n. Удачи тебе на состязаниях!','Если вы хотите стать искателем славы Гномрегана, поговорите с Амброзом Искрокрутом на Ристалище Серебряного турнира.','Добро пожаловать, искатель славы Анакриптория! Делегация Гномрегана рада приветствовать тебя в своих рядах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Искатель славы из Гномрегана',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты достойно $gсражался:сражалась; под знаменами Гномрегана, $n. Теперь тебе следует предстать перед Амброзом Искрокрутом. Это глава делегации Гномрегана и его абсолютный чемпион. Он включит тебя в состав участников соревнования, будет наблюдать за твоими тренировками и испытывать на прочность.$B$BДля меня было честью работать с тобой, $n. Удачи тебе на состязаниях!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Если вы хотите стать искателем славы Гномрегана, поговорите с Амброзом Искрокрутом на Ристалище Серебряного турнира.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Добро пожаловать, искатель славы Анакриптория! Делегация Гномрегана рада приветствовать тебя в своих рядах.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13689,'Искатель славы из Дарнаса','Ты достойно $gсражался:сражалась; под знаменами Дарнаса, $n. Теперь тебе следует предстать перед Джейлин Закатной Песней. Это глава делегации Дарнаса и его абсолютный чемпион. Она включит тебя в состав участников соревнования, будет наблюдать за твоими тренировками и испытывать на прочность.$B$BДля меня было честью работать с тобой, $n. Удачи тебе на состязаниях!','Чтобы стать искателем славы Дарнаса, поговорите с Джейлин Закатной Песней на Ристалище Серебряного турнира.','Добро пожаловать в делегацию Дарнаса, $N. Мы очень рады, что ты будешь тренироваться и соревноваться вместе с нами.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Искатель славы из Дарнаса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты достойно $gсражался:сражалась; под знаменами Дарнаса, $n. Теперь тебе следует предстать перед Джейлин Закатной Песней. Это глава делегации Дарнаса и его абсолютный чемпион. Она включит тебя в состав участников соревнования, будет наблюдать за твоими тренировками и испытывать на прочность.$B$BДля меня было честью работать с тобой, $n. Удачи тебе на состязаниях!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Чтобы стать искателем славы Дарнаса, поговорите с Джейлин Закатной Песней на Ристалище Серебряного турнира.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Добро пожаловать в делегацию Дарнаса, $N. Мы очень рады, что ты будешь тренироваться и соревноваться вместе с нами.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13690,'Искатель славы из Экзодара','Ты достойно $gсражался:сражалась; под знаменами Экзодара, $n. Теперь тебе следует предстать перед Колосусом. Это глава делегации Экзодара и его абсолютный чемпион. Он включит тебя в состав участников соревнования, будет наблюдать за твоими тренировками и испытывать на прочность.$B$BДля меня было честью работать с тобой, $n. Удачи тебе на состязаниях!','Если вы хотите стать искателем славы Экзодара, поговорите с Колосусом на Ристалище Серебряного турнира.','В таком случае – добро пожаловать в нашу компанию, искатель славы Хастол. Делегация Экзодара приветствует тебя в своих рядах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Искатель славы из Экзодара',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты достойно $gсражался:сражалась; под знаменами Экзодара, $n. Теперь тебе следует предстать перед Колосусом. Это глава делегации Экзодара и его абсолютный чемпион. Он включит тебя в состав участников соревнования, будет наблюдать за твоими тренировками и испытывать на прочность.$B$BДля меня было честью работать с тобой, $n. Удачи тебе на состязаниях!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Если вы хотите стать искателем славы Экзодара, поговорите с Колосусом на Ристалище Серебряного турнира.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','В таком случае – добро пожаловать в нашу компанию, искатель славы Хастол. Делегация Экзодара приветствует тебя в своих рядах.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13691,'Искатель славы из Оргриммара','Ты достойно $gсражался:сражалась; под знаменами Оргриммара, $n. Теперь тебе следует предстать перед Мокрой Дробителем Черепов. Это глава делегации Оргриммара и его абсолютный чемпион. Он включит тебя в состав участников соревнования, будет наблюдать за твоими тренировками и проверять твои навыки.$B$BДля меня было честью работать с тобой, $n. Удачи тебе на состязаниях!','Если вы хотите стать искателем славы Оргриммара, поговорите с Мокрой Дробителем Черепов на Ристалище Серебряного турнира.','Значит, ты хочешь сражаться за Оргриммар? Если тебе удалось одолеть парочку манекенов – это еще не значит, что ты победишь в турнире, но теперь ты будешь тренироваться вместе с самыми лучшими воинами, что несколько повысит твои шансы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Искатель славы из Оргриммара',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты достойно $gсражался:сражалась; под знаменами Оргриммара, $n. Теперь тебе следует предстать перед Мокрой Дробителем Черепов. Это глава делегации Оргриммара и его абсолютный чемпион. Он включит тебя в состав участников соревнования, будет наблюдать за твоими тренировками и проверять твои навыки.$B$BДля меня было честью работать с тобой, $n. Удачи тебе на состязаниях!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Если вы хотите стать искателем славы Оргриммара, поговорите с Мокрой Дробителем Черепов на Ристалище Серебряного турнира.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Значит, ты хочешь сражаться за Оргриммар? Если тебе удалось одолеть парочку манекенов – это еще не значит, что ты победишь в турнире, но теперь ты будешь тренироваться вместе с самыми лучшими воинами, что несколько повысит твои шансы.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (13692,'Меч из моря','Мой меч канул в глубине моря. Найди его и принеси обратно!','Вернитесь к старине Барло в лес Тероккар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Меч из моря',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мой меч канул в глубине моря. Найди его и принеси обратно!',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старине Барло в лес Тероккар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13693,'Искатель славы из Сен\'джина','Ты достойно $gсражался:сражалась; под знаменами Сен\'джина, $n. Теперь тебе следует предстать перед Зул\'тором, предводителем воинов и абсолютным чемпионом Сен\'джина. Он включит тебя в состав участников соревнования, будет наблюдать за твоими тренировками и испытывать на прочность.$B$BДля меня было честью работать с тобой, $n. Удачи тебе на состязаниях!','Если вы хотите стать искателем славы Сен\'джина, поговорите с Зул\'тором в Павильоне Похитителей Солнца на Ристалище Серебряного Турнира.','Думаешь, ты можешь сражаться под флагами Сен\'джина? Мы это проверим.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Искатель славы из Сен\'джина',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты достойно $gсражался:сражалась; под знаменами Сен\'джина, $n. Теперь тебе следует предстать перед Зул\'тором, предводителем воинов и абсолютным чемпионом Сен\'джина. Он включит тебя в состав участников соревнования, будет наблюдать за твоими тренировками и испытывать на прочность.$B$BДля меня было честью работать с тобой, $n. Удачи тебе на состязаниях!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Если вы хотите стать искателем славы Сен\'джина, поговорите с Зул\'тором в Павильоне Похитителей Солнца на Ристалище Серебряного Турнира.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Думаешь, ты можешь сражаться под флагами Сен\'джина? Мы это проверим.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (13694,'Искатель славы из Громового Утеса','Приветствую тебя от лица всех воинов Громового Утеса! Сражайся с честью под нашими знаменами.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Искатель славы из Громового Утеса',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Приветствую тебя от лица всех воинов Громового Утеса! Сражайся с честью под нашими знаменами.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (13695,'Искатель славы из Подгорода','Добро пожаловать в делегацию Подгорода, $N. Мы очень рады, что ты будешь тренироваться и соревноваться вместе с нами.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Искатель славы из Подгорода',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Добро пожаловать в делегацию Подгорода, $N. Мы очень рады, что ты будешь тренироваться и соревноваться вместе с нами.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13696,'Искатель славы из Луносвета','Ты достойно $gсражался:сражалась; под знаменами Луносвета, $n. Теперь тебе следует предстать перед Эрессеей Певицей Рассвета. Это глава делегации Луносвета и его абсолютный чемпион. Она включит тебя в состав участников соревнования, будет наблюдать за твоими тренировками и испытывать на прочность.$B$BДля меня было честью работать с тобой, $n. Удачи тебе на состязаниях!','Если вы хотите стать искателем славы Луносвета, поговорите с Эрессеей Певицей Рассвета на Ристалище Серебряного турнира.','Значит, ты хочешь сражаться за Луносвет? Отлично. Я добавлю тебя в списки, и ты немедленно сможешь приступить к тренировкам с другими искателями славы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Искатель славы из Луносвета',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты достойно $gсражался:сражалась; под знаменами Луносвета, $n. Теперь тебе следует предстать перед Эрессеей Певицей Рассвета. Это глава делегации Луносвета и его абсолютный чемпион. Она включит тебя в состав участников соревнования, будет наблюдать за твоими тренировками и испытывать на прочность.$B$BДля меня было честью работать с тобой, $n. Удачи тебе на состязаниях!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Если вы хотите стать искателем славы Луносвета, поговорите с Эрессеей Певицей Рассвета на Ристалище Серебряного турнира.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Значит, ты хочешь сражаться за Луносвет? Отлично. Я добавлю тебя в списки, и ты немедленно сможешь приступить к тренировкам с другими искателями славы.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13697,'Путь искателя славы','Во время тренировок тебе еще выпадет шанс испытать свои силы в битве против искателей славы из других столиц. Хотя бои между искателями славы не входят в официальную часть турнира, они могут научить тебя понимать стиль боя и слабые места твоих противников.$B$BИскатели славы – отважные воины, которые сражаются друг с другом ради славы и почета.$B$BПродолжай тренировки, пока не почувствуешь в себе силы победить любого противника, после чего принеси мне выигранные тобой печати.','Принесите 25 печатей искателя славы Мокре Дробителю Черепов в Павильон Похитителей Солнца на Ристалище Серебряного Турнира.','Вернитесь к Мокре Дробителю Черепов на Ристалище Серебряного турнира, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путь искателя славы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Во время тренировок тебе еще выпадет шанс испытать свои силы в битве против искателей славы из других столиц. Хотя бои между искателями славы не входят в официальную часть турнира, они могут научить тебя понимать стиль боя и слабые места твоих противников.$B$BИскатели славы – отважные воины, которые сражаются друг с другом ради славы и почета.$B$BПродолжай тренировки, пока не почувствуешь в себе силы победить любого противника, после чего принеси мне выигранные тобой печати.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 25 печатей искателя славы Мокре Дробителю Черепов в Павильон Похитителей Солнца на Ристалище Серебряного Турнира.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мокре Дробителю Черепов на Ристалище Серебряного турнира, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (13698,'Взрывчатые материалы на борту','Мне не хотелось бы посылать тебя обратно, но если дела действительно обстоят так, как ты говоришь, мы не можем позволить им использовать всю эту взрывчатку!$B$BСоваться туда без прикрытия слишком опасно, но если тебе удастся угнать один из крошшеров, то его броня выдержит даже направленный взрыв.$B$BПосле того как уничтожишь взрывчатку, пригони крошшер сюда. Нет смысла возвращать им такую ценную машину.','Уничтожьте 8 бочонков со взрывчаткой с помощью крошшера клана Песни Войны.','Взрывы были видны даже отсюда! Теперь этим жалким оркам и их прислужникам-гоблинам придется попотеть, если они снова захотят ограбить наши леса.$B$BНе знаю даже, как тебя вознаградить. Как ты думаешь, эта вещь может служить достойной компенсацией за потраченное время?','Вернитесь к часовому Люсьели Шепоту Звезд на лесопилку Песни Войны, что в Ясеневом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Взрывчатые материалы на борту',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне не хотелось бы посылать тебя обратно, но если дела действительно обстоят так, как ты говоришь, мы не можем позволить им использовать всю эту взрывчатку!$B$BСоваться туда без прикрытия слишком опасно, но если тебе удастся угнать один из крошшеров, то его броня выдержит даже направленный взрыв.$B$BПосле того как уничтожишь взрывчатку, пригони крошшер сюда. Нет смысла возвращать им такую ценную машину.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 8 бочонков со взрывчаткой с помощью крошшера клана Песни Войны.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Взрывы были видны даже отсюда! Теперь этим жалким оркам и их прислужникам-гоблинам придется попотеть, если они снова захотят ограбить наши леса.$B$BНе знаю даже, как тебя вознаградить. Как ты думаешь, эта вещь может служить достойной компенсацией за потраченное время?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к часовому Люсьели Шепоту Звезд на лесопилку Песни Войны, что в Ясеневом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (13699,'Испытание искателя славы','Скоро ты будешь $gготов:готова; сразиться в великой битве во имя Штормграда. Если хочешь доказать, что $gдостоин:достойна; представлять наш город на турнире, тебе придется победить чемпиона Серебряного Авангарда.$B$BОтправляйся в стойла за павильоном, возьми копье с любой оружейной стойки и оседлай подходящее верховое животное. Когда приготовишься к битве, поговори с оруженосцем Дэнни на арене искателей славы Серебряного Авангарда, и он вызовет твоего противника.$B$BВозвращайся ко мне после боя, и мы обсудим результаты.','Вернитесь к маршалу Якобу Алерию на Ристалище Серебряного турнира в Ледяную Корону.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Испытание искателя славы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Скоро ты будешь $gготов:готова; сразиться в великой битве во имя Штормграда. Если хочешь доказать, что $gдостоин:достойна; представлять наш город на турнире, тебе придется победить чемпиона Серебряного Авангарда.$B$BОтправляйся в стойла за павильоном, возьми копье с любой оружейной стойки и оседлай подходящее верховое животное. Когда приготовишься к битве, поговори с оруженосцем Дэнни на арене искателей славы Серебряного Авангарда, и он вызовет твоего противника.$B$BВозвращайся ко мне после боя, и мы обсудим результаты.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к маршалу Якобу Алерию на Ристалище Серебряного турнира в Ледяную Корону.',`completedtext_loc8`);
