INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (13701,'Horde Champion Marker') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Horde Champion Marker',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (13702,'Рождение героя','Поздравляю, $n. Ты $gпрошел:прошла; все испытания и $gотточил:отточила; до совершенства различные стили боя. Теперь у меня нет сомнений в том, что ты $gготов:готова; сразиться с лучшими воинами турнира – чемпионами столиц.$B$BНо для того, чтобы соблюсти все формальности, тебе надо будет поговорить с вершительницей правосудия Мариэль Чистосердечной. Иди, она ждет тебя!','Поговорите с вершительницей правосудия Мариэль Чистосердечной на Ристалище Серебряного турнира.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рождение героя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Поздравляю, $n. Ты $gпрошел:прошла; все испытания и $gотточил:отточила; до совершенства различные стили боя. Теперь у меня нет сомнений в том, что ты $gготов:готова; сразиться с лучшими воинами турнира – чемпионами столиц.$B$BНо для того, чтобы соблюсти все формальности, тебе надо будет поговорить с вершительницей правосудия Мариэль Чистосердечной. Иди, она ждет тебя!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с вершительницей правосудия Мариэль Чистосердечной на Ристалище Серебряного турнира.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (13703,'Искатель славы из Стальгорна','Приветствую тебя, чемпион. Слухи о твоей доблести намного опередили тебя. Не желаешь ли к нам присоединиться?$B$BТы будешь тренироваться и совершенствоваться как прежде, но звание чемпиона Стальгорна позволит тебе выступать под нашим флагом.','Если вы хотите стать искателем славы Стальгорна, поговорите еще раз с Ланой Твердомолот в Павильоне Серебряного Союза.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Искатель славы из Стальгорна',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приветствую тебя, чемпион. Слухи о твоей доблести намного опередили тебя. Не желаешь ли к нам присоединиться?$B$BТы будешь тренироваться и совершенствоваться как прежде, но звание чемпиона Стальгорна позволит тебе выступать под нашим флагом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Если вы хотите стать искателем славы Стальгорна, поговорите еще раз с Ланой Твердомолот в Павильоне Серебряного Союза.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13704,'Искатель славы из Гномрегана','Приветствую тебя, чемпион. Слухи о твоей доблести намного опередили тебя. Ты $gмог:могла; бы значительно усилить делегацию Гномрегана!$B$BТы будешь тренироваться и совершенствоваться как прежде, но звание чемпиона Гномрегана позволит тебе выступать под нашим флагом.','Если вы хотите стать искателем славы Гномрегана, поговорите еще раз с Амброзом Искрокрутом в Павильоне Серебряного Союза.','Мы рады приветствовать тебя среди нас, $N. Надеюсь, вскоре мы будем тренироваться бок о бок.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Искатель славы из Гномрегана',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приветствую тебя, чемпион. Слухи о твоей доблести намного опередили тебя. Ты $gмог:могла; бы значительно усилить делегацию Гномрегана!$B$BТы будешь тренироваться и совершенствоваться как прежде, но звание чемпиона Гномрегана позволит тебе выступать под нашим флагом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Если вы хотите стать искателем славы Гномрегана, поговорите еще раз с Амброзом Искрокрутом в Павильоне Серебряного Союза.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мы рады приветствовать тебя среди нас, $N. Надеюсь, вскоре мы будем тренироваться бок о бок.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (13705,'Искатель славы из Экзодара','Приветствую тебя, чемпион. Слухи о твоей доблести намного опередили тебя. Не желаешь к нам присоединиться?$B$BТы будешь тренироваться и совершенствоваться как прежде, но звание чемпиона Экзодара позволит тебе выступать под нашим флагом.','Если вы хотите стать искателем славы Экзодара, поговорите еще раз с Колосусом в Павильоне Серебряного Союза.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Искатель славы из Экзодара',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приветствую тебя, чемпион. Слухи о твоей доблести намного опередили тебя. Не желаешь к нам присоединиться?$B$BТы будешь тренироваться и совершенствоваться как прежде, но звание чемпиона Экзодара позволит тебе выступать под нашим флагом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Если вы хотите стать искателем славы Экзодара, поговорите еще раз с Колосусом в Павильоне Серебряного Союза.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13706,'Искатель славы из Дарнаса','Приветствую тебя, чемпион. Слухи о твоей доблести намного опередили тебя. Буду рада включить тебя в число участников делегации Дарнаса, если ты желаешь к нам присоединиться.$B$BТы будешь тренироваться и совершенствоваться как прежде, но звание чемпиона Дарнаса позволит тебе выступать под нашим флагом.','Если вы хотите стать искателем славы Дарнаса, поговорите еще раз с Джейлин Закатной Песней.','Воины Дарнаса гордятся возможностью сражаться рядом с тобой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Искатель славы из Дарнаса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приветствую тебя, чемпион. Слухи о твоей доблести намного опередили тебя. Буду рада включить тебя в число участников делегации Дарнаса, если ты желаешь к нам присоединиться.$B$BТы будешь тренироваться и совершенствоваться как прежде, но звание чемпиона Дарнаса позволит тебе выступать под нашим флагом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Если вы хотите стать искателем славы Дарнаса, поговорите еще раз с Джейлин Закатной Песней.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Воины Дарнаса гордятся возможностью сражаться рядом с тобой.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13707,'Искатель славы из Оргриммара','Значит, ты уже $gполучил:получила; звание чемпиона? Должно быть, ты $gпроявил:проявила; себя как достойный боец, и я буду рад включить тебя в число участников делегации Оргриммара.$B$BТы будешь тренироваться и совершенствоваться как прежде, но звание чемпиона Оргриммара позволит тебе выступать под нашим флагом.','Если вы хотите стать искателем славы Оргриммара, поговорите еще раз с Мокрой Дробителем Черепов в Павильоне Похитителей Солнца.','Добро пожаловать, $N. Жду не дождусь, когда ты начнешь тренировку с моими воинами.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Искатель славы из Оргриммара',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Значит, ты уже $gполучил:получила; звание чемпиона? Должно быть, ты $gпроявил:проявила; себя как достойный боец, и я буду рад включить тебя в число участников делегации Оргриммара.$B$BТы будешь тренироваться и совершенствоваться как прежде, но звание чемпиона Оргриммара позволит тебе выступать под нашим флагом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Если вы хотите стать искателем славы Оргриммара, поговорите еще раз с Мокрой Дробителем Черепов в Павильоне Похитителей Солнца.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Добро пожаловать, $N. Жду не дождусь, когда ты начнешь тренировку с моими воинами.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (13708,'Искатель славы из Сен\'джина','Приветствую тебя, чемпион. Если желаешь, я могу записать тебя в делегацию Сен\'джина.$B$BТы будешь тренироваться и совершенствоваться как прежде, но звание чемпиона Сен\'джина позволит тебе выступать под нашим флагом.','Если вы хотите стать искателем славы Сен\'джина, поговорите еще раз с Зул\'тором в Павильоне Похитителей Солнца.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Искатель славы из Сен\'джина',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приветствую тебя, чемпион. Если желаешь, я могу записать тебя в делегацию Сен\'джина.$B$BТы будешь тренироваться и совершенствоваться как прежде, но звание чемпиона Сен\'джина позволит тебе выступать под нашим флагом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Если вы хотите стать искателем славы Сен\'джина, поговорите еще раз с Зул\'тором в Павильоне Похитителей Солнца.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (13709,'Искатель славы из Громового Утеса','Приветствую тебя, чемпион. Как абсолютный чемпион Громового Утеса я буду рад включить тебя в число участников нашей делегации.$B$BТы будешь тренироваться и совершенствоваться как прежде, но звание чемпиона Громового Утеса позволит тебе выступать под нашим флагом.','Это честь для нас – приветствовать тебя в составе делегации. Я знаю, что ты принесешь нам победу, $N.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Искатель славы из Громового Утеса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приветствую тебя, чемпион. Как абсолютный чемпион Громового Утеса я буду рад включить тебя в число участников нашей делегации.$B$BТы будешь тренироваться и совершенствоваться как прежде, но звание чемпиона Громового Утеса позволит тебе выступать под нашим флагом.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это честь для нас – приветствовать тебя в составе делегации. Я знаю, что ты принесешь нам победу, $N.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13710,'Искатель славы из Подгорода','Приветствую тебя, чемпион. Твое присутствие значительно усилит делегацию Отрекшихся. Не желаешь ли присоединиться к нам?$B$BТы будешь тренироваться и совершенствоваться как прежде, но звание чемпиона Подгорода позволит тебе выступать под нашим флагом.','Если вы хотите стать искателем славы Подгорода, поговорите еще раз с ловчим смерти Визери в Павильоне Похитителей Солнца.','Мудрый выбор, $N. Мы оба только выиграем от этого решения.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Искатель славы из Подгорода',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приветствую тебя, чемпион. Твое присутствие значительно усилит делегацию Отрекшихся. Не желаешь ли присоединиться к нам?$B$BТы будешь тренироваться и совершенствоваться как прежде, но звание чемпиона Подгорода позволит тебе выступать под нашим флагом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Если вы хотите стать искателем славы Подгорода, поговорите еще раз с ловчим смерти Визери в Павильоне Похитителей Солнца.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мудрый выбор, $N. Мы оба только выиграем от этого решения.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (13711,'Искатель славы из Луносвета','Значит, ты уже $gполучил:получила; звание чемпиона? Должно быть, ты $gпроявил:проявила; себя как достойный боец, и я буду рада включить тебя в число участников делегации Луносвета.$B$BТы будешь тренироваться и совершенствоваться как прежде, но звание чемпиона Луносвета позволит тебе выступать под нашим флагом.','Если вы хотите стать искателем славы Луносвета, поговорите еще раз с Эрессеей Певицей Рассвета в Павильоне Похитителей Солнца.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Искатель славы из Луносвета',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Значит, ты уже $gполучил:получила; звание чемпиона? Должно быть, ты $gпроявил:проявила; себя как достойный боец, и я буду рада включить тебя в число участников делегации Луносвета.$B$BТы будешь тренироваться и совершенствоваться как прежде, но звание чемпиона Луносвета позволит тебе выступать под нашим флагом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Если вы хотите стать искателем славы Луносвета, поговорите еще раз с Эрессеей Певицей Рассвета в Павильоне Похитителей Солнца.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (13712,'Путь к спасению','Поговорите с Кадраком на Заставе Расщепленного Дерева.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путь к спасению',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Кадраком на Заставе Расщепленного Дерева.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (13713,'Испытание искателя славы','Скоро ты будешь $gготов:готова; сразиться в великой битве во имя Стальгорна. Если хочешь доказать, что $gдостоин:достойна; представлять наш город на турнире, тебе придется победить чемпиона Серебряного Авангарда.$B$BОтправляйся в стойла за павильоном, возьми копье с любой оружейной стойки и оседлай подходящее верховое животное. Когда приготовишься к битве, поговори с оруженосцем Дэнни на арене искателей славы Серебряного Авангарда, и он вызовет твоего противника.$B$BВозвращайся ко мне после боя, и мы обсудим результаты.','Вернитесь к Лане Твердомолот на Ристалище Серебряного турнира в Ледяную Корону.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Испытание искателя славы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Скоро ты будешь $gготов:готова; сразиться в великой битве во имя Стальгорна. Если хочешь доказать, что $gдостоин:достойна; представлять наш город на турнире, тебе придется победить чемпиона Серебряного Авангарда.$B$BОтправляйся в стойла за павильоном, возьми копье с любой оружейной стойки и оседлай подходящее верховое животное. Когда приготовишься к битве, поговори с оруженосцем Дэнни на арене искателей славы Серебряного Авангарда, и он вызовет твоего противника.$B$BВозвращайся ко мне после боя, и мы обсудим результаты.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лане Твердомолот на Ристалище Серебряного турнира в Ледяную Корону.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13714,'Путь искателя славы','Во время тренировок тебе еще выпадет шанс испытать свои силы в битве против искателей славы из других столиц. Хотя бои между искателями славы не входят в официальную часть турнира, они могут научить тебя понимать стиль боя и слабые места твоих противников.$B$BИскатели славы – отважные воины, которые сражаются друг с другом ради славы и почета.$B$BПродолжай тренировки, пока не почувствуешь в себе силы победить любого противника, после чего принеси мне выигранные тобой печати.','Принесите 25 печатей искателя славы Лане Твердомолот в Павильон Серебряного союза на Ристалище Серебряного Турнира.','Вернитесь к Лане Твердомолот на Ристалище Серебряного турнира в Ледяную Корону.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путь искателя славы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Во время тренировок тебе еще выпадет шанс испытать свои силы в битве против искателей славы из других столиц. Хотя бои между искателями славы не входят в официальную часть турнира, они могут научить тебя понимать стиль боя и слабые места твоих противников.$B$BИскатели славы – отважные воины, которые сражаются друг с другом ради славы и почета.$B$BПродолжай тренировки, пока не почувствуешь в себе силы победить любого противника, после чего принеси мне выигранные тобой печати.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 25 печатей искателя славы Лане Твердомолот в Павильон Серебряного союза на Ристалище Серебряного Турнира.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лане Твердомолот на Ристалище Серебряного турнира в Ледяную Корону.',`completedtext_loc8`);
