INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13717,'Путь искателя славы','Во время тренировок тебе еще выпадет шанс испытать свои силы в битве против искателей славы из других столиц. Хотя бои между искателями славы не входят в официальную часть турнира, они могут научить тебя понимать стиль боя и слабые места твоих противников.$B$BИскатели славы – отважные воины, которые сражаются друг с другом ради славы и почета.$B$BПродолжай тренировки, пока не почувствуешь в себе силы победить любого противника, после чего принеси мне выигранные тобой печати.','Принесите 25 печатей искателя славы Джейлин Закатной Песне в шатер Альянса на Ристалище Серебряного Турнира.','Вернитесь к Джейлин Закатной Песне на Ристалище Серебряного турнира в Ледяную Корону.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путь искателя славы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Во время тренировок тебе еще выпадет шанс испытать свои силы в битве против искателей славы из других столиц. Хотя бои между искателями славы не входят в официальную часть турнира, они могут научить тебя понимать стиль боя и слабые места твоих противников.$B$BИскатели славы – отважные воины, которые сражаются друг с другом ради славы и почета.$B$BПродолжай тренировки, пока не почувствуешь в себе силы победить любого противника, после чего принеси мне выигранные тобой печати.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 25 печатей искателя славы Джейлин Закатной Песне в шатер Альянса на Ристалище Серебряного Турнира.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джейлин Закатной Песне на Ристалище Серебряного турнира в Ледяную Корону.',`completedtext_loc8`);
