INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (13723,'Испытание искателя славы','Скоро ты будешь $gготов:готова; сразиться в великой битве во имя Гномрегана. Если хочешь доказать, что $gдостоин:достойна; представлять наш город на турнире, тебе придется победить чемпиона Серебряного Авангарда.$B$BОтправляйся в стойла за павильоном, возьми копье с любой оружейной стойки и оседлай подходящее верховое животное. Когда приготовишься к битве, поговори с оруженосцем Дэнни на арене искателей славы Серебряного Авангарда, и он вызовет твоего противника.$B$BВозвращайся ко мне после боя, и мы обсудим результаты.','Вернитесь к Амброзу Искрокруту на Ристалище Серебряного турнира в Ледяную Корону.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Испытание искателя славы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Скоро ты будешь $gготов:готова; сразиться в великой битве во имя Гномрегана. Если хочешь доказать, что $gдостоин:достойна; представлять наш город на турнире, тебе придется победить чемпиона Серебряного Авангарда.$B$BОтправляйся в стойла за павильоном, возьми копье с любой оружейной стойки и оседлай подходящее верховое животное. Когда приготовишься к битве, поговори с оруженосцем Дэнни на арене искателей славы Серебряного Авангарда, и он вызовет твоего противника.$B$BВозвращайся ко мне после боя, и мы обсудим результаты.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Амброзу Искрокруту на Ристалище Серебряного турнира в Ледяную Корону.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13724,'Испытание искателя славы','Скоро ты будешь $gготов:готова; сразиться в великой битве во имя Экзодара. Если хочешь доказать, что $gдостоин:достойна; представлять наш город на турнире, тебе придется победить чемпиона Серебряного Авангарда.$B$BОтправляйся в стойла за павильоном, возьми копье с любой оружейной стойки и оседлай подходящее верховое животное. Когда приготовишься к битве, поговори с оруженосцем Дэнни на арене искателей славы Серебряного Авангарда, и он вызовет твоего противника.$B$BВозвращайся ко мне после боя, и мы обсудим результаты.','Вы победили чемпиона Серебряного Авангарда?','Вернитесь к Колосусу на Ристалище Серебряного турнира в Ледяную Корону.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Испытание искателя славы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Скоро ты будешь $gготов:готова; сразиться в великой битве во имя Экзодара. Если хочешь доказать, что $gдостоин:достойна; представлять наш город на турнире, тебе придется победить чемпиона Серебряного Авангарда.$B$BОтправляйся в стойла за павильоном, возьми копье с любой оружейной стойки и оседлай подходящее верховое животное. Когда приготовишься к битве, поговори с оруженосцем Дэнни на арене искателей славы Серебряного Авангарда, и он вызовет твоего противника.$B$BВозвращайся ко мне после боя, и мы обсудим результаты.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы победили чемпиона Серебряного Авангарда?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Колосусу на Ристалище Серебряного турнира в Ледяную Корону.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13725,'Испытание искателя славы','Скоро ты будешь $gготов:готова; сразиться в великой битве во имя Дарнаса. Если хочешь доказать, что $gдостоин:достойна; представлять наш город на турнире, тебе придется победить чемпиона Серебряного Авангарда.$B$BОтправляйся в стойла за павильоном, возьми копье с любой оружейной стойки и оседлай подходящее верховое животное. Когда приготовишься к битве, поговори с оруженосцем Дэнни на арене искателей славы Серебряного Авангарда, и он вызовет твоего противника.$B$BВозвращайся ко мне после боя, и мы обсудим результаты.','Ты $Gдоказал:доказала;, что $Gдостоин:достоина; титула чемпиона, $N. Теперь ты будешь с оружием наготове защищать честь Дарнаса на самом высоком уровне и носить наш герб на своем флаге.','Вы победили чемпиона Серебряного Авангарда?','Вернитесь к Джейлин Закатной Песне на Ристалище Серебряного турнира в Ледяную Корону.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Испытание искателя славы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Скоро ты будешь $gготов:готова; сразиться в великой битве во имя Дарнаса. Если хочешь доказать, что $gдостоин:достойна; представлять наш город на турнире, тебе придется победить чемпиона Серебряного Авангарда.$B$BОтправляйся в стойла за павильоном, возьми копье с любой оружейной стойки и оседлай подходящее верховое животное. Когда приготовишься к битве, поговори с оруженосцем Дэнни на арене искателей славы Серебряного Авангарда, и он вызовет твоего противника.$B$BВозвращайся ко мне после боя, и мы обсудим результаты.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты $Gдоказал:доказала;, что $Gдостоин:достоина; титула чемпиона, $N. Теперь ты будешь с оружием наготове защищать честь Дарнаса на самом высоком уровне и носить наш герб на своем флаге.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы победили чемпиона Серебряного Авангарда?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джейлин Закатной Песне на Ристалище Серебряного турнира в Ледяную Корону.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13726,'Испытание искателя славы','Скоро ты будешь $gготов:готова; сразиться в великой битве. Если хочешь доказать, что $gдостоин:достойна; этой чести, тебе придется победить чемпиона Серебряного Авангарда.$B$BОтправляйся в стойла за павильоном, возьми копье с любой оружейной стойки и оседлай подходящее верховое животное. Когда приготовишься к битве, поговори с оруженосцем Дэнни на арене искателей славы Серебряного Авангарда, и он вызовет твоего противника.$B$BВозвращайся ко мне после боя, и мы обсудим результаты.','Поговорите с оруженосцем Дэнни, чтобы вызвать на поединок вашего противника. Как только вы победите чемпиона Серебряного Авангарда, вернитесь к Мокре Дробителю Черепов в шатер Орды на Ристалище Серебряного Турнира.$B$BЕсли вы потеряете копье, возьмите другое с любой оружейной стойки рядом со стойлами или в Павильоне Похитителей Солнца.','Ты $Gдоказал:доказала;, что $Gдостоин:достоина; титула чемпиона, $N. Теперь ты будешь с оружием наготове защищать честь Оргриммара на самом высоком уровне и носить наш герб на своем флаге.','Вы победили чемпиона Серебряного Авангарда?','Вернитесь к Мокре Дробителю Черепов на Ристалище Серебряного турнира, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Испытание искателя славы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Скоро ты будешь $gготов:готова; сразиться в великой битве. Если хочешь доказать, что $gдостоин:достойна; этой чести, тебе придется победить чемпиона Серебряного Авангарда.$B$BОтправляйся в стойла за павильоном, возьми копье с любой оружейной стойки и оседлай подходящее верховое животное. Когда приготовишься к битве, поговори с оруженосцем Дэнни на арене искателей славы Серебряного Авангарда, и он вызовет твоего противника.$B$BВозвращайся ко мне после боя, и мы обсудим результаты.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с оруженосцем Дэнни, чтобы вызвать на поединок вашего противника. Как только вы победите чемпиона Серебряного Авангарда, вернитесь к Мокре Дробителю Черепов в шатер Орды на Ристалище Серебряного Турнира.$B$BЕсли вы потеряете копье, возьмите другое с любой оружейной стойки рядом со стойлами или в Павильоне Похитителей Солнца.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты $Gдоказал:доказала;, что $Gдостоин:достоина; титула чемпиона, $N. Теперь ты будешь с оружием наготове защищать честь Оргриммара на самом высоком уровне и носить наш герб на своем флаге.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы победили чемпиона Серебряного Авангарда?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мокре Дробителю Черепов на Ристалище Серебряного турнира, что в Ледяной Короне.',`completedtext_loc8`);
