INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (13730,'Игры с огнем Скверны','<Драака наклоняется к вам и шепчет.>$b$bСлушай... Прежде, чем ты скажешь хоть слово, пойми – я знаю, что связываться с бесовскими силами нехорошо...$b$bНо в данной ситуации... в тяжелые времена приходится принимать трудные решения, |3-6($c).$b$bСкорее всего, всех нас ждет гибель в этом месте. Помирать – так с музыкой, вот что я скажу!$b$bТы $Gсогласен:согласна;?$b$bТогда бери эту канистру и отправляйся на юго-восток, к Холму Демонического Огня. Наполни ее вспышками огня Скверны и возвращайся обратно.$b$bДа, и лучше никому не упоминай об этом деле...','О, да! $B$BЭто проучит паршивых эльфов, даю слово!','Поговорите с Драакой на Заставе Расщепленного Дерева.','Если не сбивать огонь, эта штука жжется. Понимаешь, о чем я?','Драака','Если не сбивать огонь, эта штука жжется. Понимаешь, о чем я?','Драака') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Игры с огнем Скверны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Драака наклоняется к вам и шепчет.>$b$bСлушай... Прежде, чем ты скажешь хоть слово, пойми – я знаю, что связываться с бесовскими силами нехорошо...$b$bНо в данной ситуации... в тяжелые времена приходится принимать трудные решения, |3-6($c).$b$bСкорее всего, всех нас ждет гибель в этом месте. Помирать – так с музыкой, вот что я скажу!$b$bТы $Gсогласен:согласна;?$b$bТогда бери эту канистру и отправляйся на юго-восток, к Холму Демонического Огня. Наполни ее вспышками огня Скверны и возвращайся обратно.$b$bДа, и лучше никому не упоминай об этом деле...',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, да! $B$BЭто проучит паршивых эльфов, даю слово!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Драакой на Заставе Расщепленного Дерева.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Если не сбивать огонь, эта штука жжется. Понимаешь, о чем я?',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Драака',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Если не сбивать огонь, эта штука жжется. Понимаешь, о чем я?',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Драака',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13731,'Испытание искателя славы','Скоро ты будешь $gготов:готова; сразиться в великой битве. Если хочешь доказать, что $gдостоин:достойна; этой чести, тебе придется победить чемпиона Серебряного Авангарда.$B$BОтправляйся в стойла за павильоном, возьми копье с любой оружейной стойки и оседлай подходящее верховое животное. Когда приготовишься к битве, поговори с оруженосцем Дэнни на арене искателей славы Серебряного Авангарда, и он вызовет твоего противника.$B$BВозвращайся ко мне после боя, и мы обсудим результаты.','Поговорите с оруженосцем Дэнни, чтобы вызвать на поединок вашего противника. Как только вы победите чемпиона Серебряного Авангарда, вернитесь к Эрессее Певице Рассвета в шатер Орды на Ристалище Серебряного Турнира.$B$BЕсли вы потеряете копье, возьмите другое с любой оружейной стойки рядом со стойлами или в Павильоне Похитителей Солнца.','Вы победили чемпиона Серебряного Авангарда?','Вернитесь к Эрессее Певице Рассвета на Ристалище Серебряного турнира, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Испытание искателя славы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Скоро ты будешь $gготов:готова; сразиться в великой битве. Если хочешь доказать, что $gдостоин:достойна; этой чести, тебе придется победить чемпиона Серебряного Авангарда.$B$BОтправляйся в стойла за павильоном, возьми копье с любой оружейной стойки и оседлай подходящее верховое животное. Когда приготовишься к битве, поговори с оруженосцем Дэнни на арене искателей славы Серебряного Авангарда, и он вызовет твоего противника.$B$BВозвращайся ко мне после боя, и мы обсудим результаты.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с оруженосцем Дэнни, чтобы вызвать на поединок вашего противника. Как только вы победите чемпиона Серебряного Авангарда, вернитесь к Эрессее Певице Рассвета в шатер Орды на Ристалище Серебряного Турнира.$B$BЕсли вы потеряете копье, возьмите другое с любой оружейной стойки рядом со стойлами или в Павильоне Похитителей Солнца.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы победили чемпиона Серебряного Авангарда?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Эрессее Певице Рассвета на Ристалище Серебряного турнира, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13732,'Рождение героя','Поздравляю, $n. Ты $gпрошел:прошла; все испытания и $gотточил:отточила; до совершенства различные стили боя. Теперь у меня нет сомнений в том, что ты $gготов:готова; сразиться с лучшими воинами турнира – чемпионами столиц.$B$BНо для того, чтобы соблюсти все формальности, тебе надо будет поговорить с вершительницей правосудия Мариэль Чистосердечной. Иди, она ждет тебя!','Поговорите с вершительницей правосудия Мариэль Чистосердечной на Ристалище Серебряного турнира.','Я приветствую тебя как чемпиона турнира, $N. В этом звании ты сможешь принять участие в самых крупных состязаниях. Ты также можешь стать искателем славы другого города и со временем завоевать звание его чемпиона.$B$BВсе чемпионы обязаны пользоваться услугами оруженосцев, и ты, $N, не исключение. Позволь мне порекомендовать тебе надежного помощника в будущих сражениях. Он будет гордо нести флаг столицы, которая избрала тебя своим представителем.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рождение героя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Поздравляю, $n. Ты $gпрошел:прошла; все испытания и $gотточил:отточила; до совершенства различные стили боя. Теперь у меня нет сомнений в том, что ты $gготов:готова; сразиться с лучшими воинами турнира – чемпионами столиц.$B$BНо для того, чтобы соблюсти все формальности, тебе надо будет поговорить с вершительницей правосудия Мариэль Чистосердечной. Иди, она ждет тебя!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с вершительницей правосудия Мариэль Чистосердечной на Ристалище Серебряного турнира.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я приветствую тебя как чемпиона турнира, $N. В этом звании ты сможешь принять участие в самых крупных состязаниях. Ты также можешь стать искателем славы другого города и со временем завоевать звание его чемпиона.$B$BВсе чемпионы обязаны пользоваться услугами оруженосцев, и ты, $N, не исключение. Позволь мне порекомендовать тебе надежного помощника в будущих сражениях. Он будет гордо нести флаг столицы, которая избрала тебя своим представителем.',`offerrewardtext_loc8`);
