INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13740,'Рождение героя','Ты $gзавоевал:завоевала; мое уважение и почет среди братьев по оружию. Ты $gсразил:сразила; всех, кто осмелился бросить тебе вызов, и $gотточил:отточила; до совершенства различные стили боя. Теперь у меня нет сомнений в том, что ты $gготов:готова; выступить против лучших воинов турнира и принести славу Луносвету!$B$BНо для того, чтобы соблюсти все формальности, тебе надо будет поговорить с вершительницей правосудия Мариэль Чистосердечной. Иди, она ждет тебя!','Поговорите с вершительницей правосудия Мариэль Чистосердечной на Ристалище Серебряного турнира.','Я приветствую тебя как чемпиона турнира, $N. В этом звании ты сможешь принять участие в самых крупных состязаниях. Ты также можешь стать искателем славы другого города и со временем завоевать звание его чемпиона.$B$BВсе чемпионы обязаны пользоваться услугами оруженосцев, и ты, $N, не исключение. Позволь мне порекомендовать тебе надежного помощника в будущих сражениях. Он будет гордо нести флаг столицы, которая избрала тебя своим представителем.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рождение героя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gзавоевал:завоевала; мое уважение и почет среди братьев по оружию. Ты $gсразил:сразила; всех, кто осмелился бросить тебе вызов, и $gотточил:отточила; до совершенства различные стили боя. Теперь у меня нет сомнений в том, что ты $gготов:готова; выступить против лучших воинов турнира и принести славу Луносвету!$B$BНо для того, чтобы соблюсти все формальности, тебе надо будет поговорить с вершительницей правосудия Мариэль Чистосердечной. Иди, она ждет тебя!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с вершительницей правосудия Мариэль Чистосердечной на Ристалище Серебряного турнира.',`objectives_loc8`), `offe