INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (13756,'Великая битва','Великая битва – одно из самых важных соревнований турнира. Население Экзодара надеется на нашу победу. Лучший способ усовершенствовать навыки боя – бросить вызов искателям славы, представляющим другие столицы Альянса.$B$BПослушай моего совета – иди в стойла за павильоном, оседлай элекка с острова Лазурной Дымки и брось вызов своим конкурентам. Они ждут тебя на Арене искателей славы из Альянса, прямо за нашей палаткой.','Вернитесь к Рании в Ледяную Корону.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Великая битва',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Великая битва – одно из самых важных соревнований турнира. Население Экзодара надеется на нашу победу. Лучший способ усовершенствовать навыки боя – бросить вызов искателям славы, представляющим другие столицы Альянса.$B$BПослушай моего совета – иди в стойла за павильоном, оседлай элекка с острова Лазурной Дымки и брось вызов своим конкурентам. Они ждут тебя на Арене искателей славы из Альянса, прямо за нашей палаткой.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Рании в Ледяную Корону.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (13757,'Клинок, достойный чемпиона','Даже самым верным и острым клинком не выиграть это состязание. Мои соперники обзавелись заколдованным оружием, что ставит меня в невыгодное положение, но я не отчаиваюсь.$B$BЕсть одна древняя легенда о деве из Седых холмов, которая охраняет могущественный клинок. Говорят, будто страшное проклятие превратило ее в лягушку, чтобы никто больше не смог коснуться этого меча. Теперь она живет среди прудовых лягушек на берегу Ясеневого озера, что к востоку от Ясеневой заставы... И только поцелуй любви, дарованный от чистого сердца, может разрушить злые чары. Только не забудь воспользоваться этим бальзамом для губ – иначе покроешься бородавками.','Вернитесь к Джейлин Закатной Песне на Ристалище Серебряного турнира в Ледяную Корону.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Клинок, достойный чемпиона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Даже самым верным и острым клинком не выиграть это состязание. Мои соперники обзавелись заколдованным оружием, что ставит меня в невыгодное положение, но я не отчаиваюсь.$B$BЕсть одна древняя легенда о деве из Седых холмов, которая охраняет могущественный клинок. Говорят, будто страшное проклятие превратило ее в лягушку, чтобы никто больше не смог коснуться этого меча. Теперь она живет среди прудовых лягушек на берегу Ясеневого озера, что к востоку от Ясеневой заставы... И только поцелуй любви, дарованный от чистого сердца, может разрушить злые чары. Только не забудь воспользоваться этим бальзамом для губ – иначе покроешься бородавками.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джейлин Закатной Песне на Ристалище Серебряного турнира в Ледяную Корону.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13758,'Достойное оружие','Что за невезение!$B$BМой турнирный клинок куда-то делся, а сражение должно состояться сегодня днем!$B$BОдин бард рассказал мне, что некая дева дарит путникам ценные вещицы в обмен на букетик зимних гиацинтов. Эти цветы растут только на льду, идущем вниз по реке от Железной плотины, на северо-западе от границы между Ледяной Короной и лесом Хрустальной Песни. Собери цветы и отнеси их к озеру Драк\'Мар, оно расположено в северо-восточной части Драконьего Погоста, почти на границе с Зул\'Драком и Седыми холмами. И попроси у девы хороший клинок.','Принесите меч Драк\'Мара Джейлин Закатной Песне в шатер Альянса на Ристалище Серебряного турнира.','Так барды говорят правду? Меч действительно существует?','Вернитесь к Джейлин Закатной Песне на Ристалище Серебряного турнира в Ледяную Корону.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Достойное оружие',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что за невезение!$B$BМой турнирный клинок куда-то делся, а сражение должно состояться сегодня днем!$B$BОдин бард рассказал мне, что некая дева дарит путникам ценные вещицы в обмен на букетик зимних гиацинтов. Эти цветы растут только на льду, идущем вниз по реке от Железной плотины, на северо-западе от границы между Ледяной Короной и лесом Хрустальной Песни. Собери цветы и отнеси их к озеру Драк\'Мар, оно расположено в северо-восточной части Драконьего Погоста, почти на границе с Зул\'Драком и Седыми холмами. И попроси у девы хороший клинок.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите меч Драк\'Мара Джейлин Закатной Песне в шатер Альянса на Ристалище Серебряного турнира.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Так барды говорят правду? Меч действительно существует?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джейлин Закатной Песне на Ристалище Серебряного турнира в Ледяную Корону.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13759,'Клинок Зимы','Джейлин Закатная Песня из Павильона Серебряного союза на Ристалище Серебряного турнира просит вас принести ей Клинок Зимы.','Ну как? Получилось добыть меч?','Вернитесь к Джейлин Закатной Песне на Ристалище Серебряного турнира в Ледяную Корону.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Клинок Зимы',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Джейлин Закатная Песня из Павильона Серебряного союза на Ристалище Серебряного турнира просит вас принести ей Клинок Зимы.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как? Получилось добыть меч?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джейлин Закатной Песне на Ристалище Серебряного турнира в Ледяную Корону.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13760,'Теория и практика','Турнир – это возможность помериться силой с другими героями, но стоит помнить и о том, что главный враг – Плеть – не дремлет. Ты оттачиваешь мастерство в поединках с товарищами, но тебе столь же необходимо совершенствоваться в битвах с неприятелем.$B$BОтправляйся на юго-запад Долины павших героев, что к северу от Корп\'ретара – там приспешники Плети поднимают из небытия павших героев и обращают их против нас. Окажи честь нашим союзникам и упокой этих вынужденных слуг Плети, тем самым подготовившись к настоящей битве.','Убейте 10 обращенных героев в Ледяной Короне по заданию Иллестрии Певицы Клинка из Павильона Серебряного союза на Ристалище Серебряного турнира.','Ты испытал себя в бою против Плети?','Вернитесь к Иллестрии Певице Клинка на Ристалище Серебряного турнира в Ледяную Корону.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Теория и практика',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Турнир – это возможность помериться силой с другими героями, но стоит помнить и о том, что главный враг – Плеть – не дремлет. Ты оттачиваешь мастерство в поединках с товарищами, но тебе столь же необходимо совершенствоваться в битвах с неприятелем.$B$BОтправляйся на юго-запад Долины павших героев, что к северу от Корп\'ретара – там приспешники Плети поднимают из небытия павших героев и обращают их против нас. Окажи честь нашим союзникам и упокой этих вынужденных слуг Плети, тем самым подготовившись к настоящей битве.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 обращенных героев в Ледяной Короне по заданию Иллестрии Певицы Клинка из Павильона Серебряного союза на Ристалище Серебряного турнира.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты испытал себя в бою против Плети?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Иллестрии Певице Клинка на Ристалище Серебряного турнира в Ледяную Корону.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (13761,'Великая битва','Великая битва – одно из самых важных соревнований турнира. Люди Дарнаса надеются на нашу победу. Лучший способ усовершенствовать свои навыки боя – бросить вызов искателям славы, представляющим другие столицы Альянса.$B$BОни тренируются на арене прямо за нашей палаткой. Послушай моего совета – иди в стойла за павильоном, оседлай дарнасского туманного саблезуба и брось вызов искателям славы Альянса.','Вернитесь к Айре Устремленной к Звездам в Ледяную Корону.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Великая битва',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Великая битва – одно из самых важных соревнований турнира. Люди Дарнаса надеются на нашу победу. Лучший способ усовершенствовать свои навыки боя – бросить вызов искателям славы, представляющим другие столицы Альянса.$B$BОни тренируются на арене прямо за нашей палаткой. Послушай моего совета – иди в стойла за павильоном, оседлай дарнасского туманного саблезуба и брось вызов искателям славы Альянса.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Айре Устремленной к Звездам в Ледяную Корону.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (13762,'Клинок, достойный чемпиона','Ходят слухи, что чемпионы Альянса отправились на поиски древних клинков для своих бойцов. Нельзя допустить, чтобы они получили столь значительное преимущество!$B$BЕсть одна древняя легенда о деве из Седых холмов, которая охраняет могущественный клинок. Говорят, будто страшное проклятие превратило ее в лягушку, чтобы никто больше не смог коснуться этого меча. Теперь она живет среди прудовых лягушек на берегу Ясеневого озера, что к востоку от Ясеневой заставы... И только поцелуй любви, дарованный от чистого сердца, может разрушить злые чары. Только не забудь воспользоваться этим бальзамом для губ – иначе покроешься бородавками.','Так значит, это не сказки? Какой замечательный клинок! С его помощью я одолею любого заезжего альянсовца!','Вернитесь к Мокре Дробителю Черепов на Ристалище Серебряного турнира, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Клинок, достойный чемпиона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ходят слухи, что чемпионы Альянса отправились на поиски древних клинков для своих бойцов. Нельзя допустить, чтобы они получили столь значительное преимущество!$B$BЕсть одна древняя легенда о деве из Седых холмов, которая охраняет могущественный клинок. Говорят, будто страшное проклятие превратило ее в лягушку, чтобы никто больше не смог коснуться этого меча. Теперь она живет среди прудовых лягушек на берегу Ясеневого озера, что к востоку от Ясеневой заставы... И только поцелуй любви, дарованный от чистого сердца, может разрушить злые чары. Только не забудь воспользоваться этим бальзамом для губ – иначе покроешься бородавками.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так значит, это не сказки? Какой замечательный клинок! С его помощью я одолею любого заезжего альянсовца!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мокре Дробителю Черепов на Ристалище Серебряного турнира, что в Ледяной Короне.',`completedtext_loc8`);
