ext_loc8`='','Так барды говорят правду? Меч действительно существует?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мокре Дробителю Черепов на Ристалище Серебряного турнира, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13764,'Клинок Зимы','Мокра Дробитель Черепов из Павильона Похитителей Солнца на Ристалище Серебряного турнира просит вас принести Клинок Зимы.','Не зря об этом мече слагали легенды. Думаю, кузнецу не стоит потеть над моим старым клинком – Клинок Зимы куда лучше, и отныне я буду сражаться только им. Благодарю тебя, $N.','Ну как? Получилось добыть меч?','Вернитесь к Мокре Дробителю Черепов на Ристалище Серебряного турнира, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Клинок Зимы',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Мокра Дробитель Черепов из Павильона Похитителей Солнца на Ристалище Серебряного турнира просит вас принести Клинок Зимы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Не зря об этом мече слагали легенды. Думаю, кузнецу не стоит потеть над моим старым клинком – Клинок Зимы куда лучше, и отныне я буду сражаться только им. Благодарю тебя, $N.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как? Получилось добыть меч?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мокре Дробителю Черепов на Ристалище Серебряного турнира, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13765,'Теория и практика','Турнир – это возможность помериться силой с другими героями, но стоит помнить и о том, что главный враг – Плеть – не дремлет. Ты оттачиваешь мастерство в поединках с товарищами, но тебе столь же необходимо совершенствоваться в битвах с неприятелем.$B$BОтправляйся на юго-запад Долины павших героев, что к северу от Корп\'ретара – там приспешники Плети поднимают из небытия павших героев и обращают их против нас. Окажи честь нашим союзникам и упокой этих слуг Плети, тем самым подготовившись к настоящей битве.','Убейте 10 обращенных героев в Ледяной Короне по заданию Акиноса из Павильона Похитителей Солнца на Ристалище Серебряного турнира.','Хорошая тренировка – залог успеха. Приятно видеть твои старания.','Хороший тренировочный день никому не повредит. Рад видеть, что ты не $отставал:отставала;.','Вернитесь к Акиносу на Ристалище Серебряного турнира, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Теория и практика',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Турнир – это возможность помериться силой с другими героями, но стоит помнить и о том, что главный враг – Плеть – не дремлет. Ты оттачиваешь мастерство в поединках с товарищами, но тебе столь же необходимо совершенствоваться в битвах с неприятелем.$B$BОтправляйся на юго-запад Долины павших героев, что к северу от Корп\'ретара – там приспешники Плети поднимают из небытия павших героев и обращают их против нас. Окажи честь нашим союзникам и упокой этих слуг Плети, тем самым подготовившись к настоящей битве.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 обращенных героев в Ледяной Короне по заданию Акиноса из Павильона Похитителей Солнца на Ристалище Серебряного турнира.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошая тренировка – залог успеха. Приятно видеть твои старания.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Хороший тренировочный день никому не повредит. Рад видеть, что ты не $отставал:отставала;.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Акиносу на Ристалище Серебряного турнира, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13766,'Именем природы','Земля шепчет мне, что вскоре в наш мир прибудет еще больше демонов – столько, что мы не сможем больше сдерживать их нашествие.$B$BВозьми эту частичку меня и возвращайся к Каньону Гибели Демона и Гряде Гибели Демона, что к югу от Холма Демонического Огня. Направь ветвь на демонические врата и сосредоточься. В этом побеге я заключил частичку жизненной силы леса. Она сможет закрыть проход.','Закройте 10 врат демонов с помощью ветви Кривокрона.','Вернитесь к Кривокрону на лесопилку Песни Войны, что в Ясеневом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Именем природы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Земля шепчет мне, что вскоре в наш мир прибудет еще больше демонов – столько, что мы не сможем больше сдерживать их нашествие.$B$BВозьми эту частичку меня и возвращайся к Каньону Гибели Демона и Гряде Гибели Демона, что к югу от Холма Демонического Огня. Направь ветвь на демонические врата и сосредоточься. В этом побеге я заключил частичку жизненной силы леса. Она сможет закрыть проход.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Закройте 10 врат демонов с помощью ветви Кривокрона.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кривокрону на лесопилку Песни Войны, что в Ясеневом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13767,'Великая битва','Великая битва – одно из самых важных соревнований турнира. Победа достанется нелегко, но я в тебе не сомневаюсь. Продолжай тренировки верхом до тех пор, пока не будешь действовать как одно целое со своим верховым животным. $B$BЯ помогу тебе подготовиться к битве. Иди в стойла за павильоном, оседлай оргриммарского волка и брось вызов искателям славы. Ты найдешь их прямо за этой палаткой на Арене искателей славы Орды.','Принесите три знака искателя славы Море Сестре Воргов в шатер Орды на Ристалище Серебряного турнира.$B$BЕсли вы потеряете копье, возьмите другое с любой оружейной стойки рядом со стойлами или в Павильоне Похитителей Солнца.','Вернитесь к Море Сестре Воргов на Ристалище Серебряного турнира, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Великая битва',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Великая битва – одно из самых важных соревнований турнира. Победа достанется нелегко, но я в тебе не сомневаюсь. Продолжай тренировки верхом до тех пор, пока не будешь действовать как одно целое со своим верховым животным. $B$BЯ помогу тебе подготовиться к битве. Иди в стойла за павильоном, оседлай оргриммарского волка и брось вызов искателям славы. Ты найдешь их прямо за этой палаткой на Арене искателей славы Орды.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите три знака искателя славы Море Сестре Воргов в шатер Орды на Ристалище Серебряного турнира.$B$BЕсли вы потеряете копье, возьмите другое с любой оружейной стойки рядом со стойлами или в Павильоне Похитителей Солнца.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Море Сестре Воргов на Ристалище Серебряного турнира, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (13768,'Клинок, достойный чемпиона','Ходят слухи, что чемпионы Альянса отправились на поиски древних клинков для своих бойцов. Нельзя допустить, чтобы они получили столь значительное преимущество!$B$BЕсть одна древняя легенда о деве из Седых холмов, которая охраняет могущественный клинок. Говорят, будто страшное проклятие превратило ее в лягушку, чтобы никто больше не смог коснуться этого меча. Теперь она живет среди прудовых лягушек на берегу Ясеневого озера, что к востоку от Ясеневой заставы... И только поцелуй любви, дарованный от чистого сердца, может разрушить злые чары. Только не забудь воспользоваться этим бальзамом для губ – иначе покроешься бородавками.','Вернитесь к Зул\'тору на Ристалище Серебряного турнира, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Клинок, достойный чемпиона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ходят слухи, что чемпионы Альянса отправились на поиски древних клинков для своих бойцов. Нельзя допустить, чтобы они получили столь значительное преимущество!$B$BЕсть одна древняя легенда о деве из Седых холмов, которая охраняет могущественный клинок. Говорят, будто страшное проклятие превратило ее в лягушку, чтобы никто больше не смог коснуться этого меча. Теперь она живет среди прудовых лягушек на берегу Ясеневого озера, что к востоку от Ясеневой заставы... И только поцелуй любви, дарованный от чистого сердца, может разрушить злые чары. Только не забудь воспользоваться этим бальзамом для губ – иначе покроешься бородавками.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Зул\'тору на Ристалище Серебряного турнира, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13769,'Достойное оружие','Что за невезение!$B$BМой турнирный клинок куда-то делся, а сражение должно состояться сегодня днем!$B$BОдин бард рассказал мне, что некая дева дарит путникам ценные вещицы в обмен на букетик зимних гиацинтов. Эти цветы растут только на льду, идущем вниз по реке от Железной плотины, на северо-западе от границы между Ледяной Короной и лесом Хрустальной Песни. Собери цветы и отнеси их к озеру Драк\'Мар, оно расположено в северо-восточной части Драконьего Погоста, почти на границе с Зул\'Драком и Седыми холмами. И попроси у девы хороший клинок.','Принесите меч Драк\'Мара Зул\'тору в Павильон Похитителей Солнца на Ристалище Серебряного турнира.','Этот меч поможет мне одолеть соперников. Спасибо тебе, $N.','Так барды говорят правду? Меч действительно существует?','Вернитесь к Зул\'тору на Ристалище Серебряного турнира, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Достойное оружие',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что за невезение!$B$BМой турнирный клинок куда-то делся, а сражение должно состояться сегодня днем!$B$BОдин бард рассказал мне, что некая дева дарит путникам ценные вещицы в обмен на букетик зимних гиацинтов. Эти цветы растут только на льду, идущем вниз по реке от Железной плотины, на северо-западе от границы между Ледяной Короной и лесом Хрустальной Песни. Собери цветы и отнеси их к озеру Драк\'Мар, оно расположено в северо-восточной части Драконьего Погоста, почти на границе с Зул\'Драком и Седыми холмами. И попроси у девы хороший клинок.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите меч Драк\'Мара Зул\'тору в Павильон Похитителей Солнца на Ристалище Серебряного турнира.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Этот меч поможет мне одолеть соперников. Спасибо тебе, $N.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Так барды говорят правду? Меч действительно существует?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Зул\'тору на Ристалище Серебряного турнира, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13770,'Клинок Зимы','Зул\'тор из Павильона Похитителей Солнца на Ристалище Серебряного турнира просит вас принести Клинок Зимы.','Не зря об этом мече слагали легенды. Думаю, кузнецу не стоит потеть над моим старым клинком – Клинок Зимы куда лучше, и отныне я буду сражаться только им. Благодарю тебя, $N.','Ну как? Получилось добыть меч?','Вернитесь к Зул\'тору на Ристалище Серебряного турнира, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Клинок Зимы',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Зул\'тор из Павильона Похитителей Солнца на Ристалище Серебряного турнира просит вас принести Клинок Зимы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Не зря об этом мече слагали легенды. Думаю, кузнецу не стоит потеть над моим старым клинком – Клинок Зимы куда лучше, и отныне я буду сражаться только им. Благодарю тебя, $N.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как? Получилось добыть меч?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Зул\'тору на Ристалище Серебряного турнира, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13771,'Теория и практика','Турнир – это возможность помериться силой с другими героями, но стоит помнить и о том, что главный враг – Плеть – не дремлет. Ты оттачиваешь мастерство в поединках с товарищами, но тебе столь же необходимо совершенствоваться в битвах с неприятелем.$B$BОтправляйся на юго-запад Долины павших героев, что к северу от Корп\'ретара – там приспешники Плети поднимают из небытия павших героев и обращают их против нас. Окажи честь нашим союзникам и упокой этих слуг Плети, тем самым подготовившись к настоящей битве.','Убейте 10 обращенных героев по заданию темного охотника Мезил-Кри из Павильона Похитителей Солнца на Ристалище Серебряного турнира.','Хорошая тренировка – залог успеха. Приятно видеть твои старания.','Хороший тренировочный день никому не повредит. Рад видеть, что ты не $отставал:отставала;.','Вернитесь к темному охотнику Мезил-кри на Ристалище Серебряного турнира, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Теория и практика',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Турнир – это возможность помериться силой с другими героями, но стоит помнить и о том, что главный враг – Плеть – не дремлет. Ты оттачиваешь мастерство в поединках с товарищами, но тебе столь же необходимо совершенствоваться в битвах с неприятелем.$B$BОтправляйся на юго-запад Долины павших героев, что к северу от Корп\'ретара – там приспешники Плети поднимают из небытия павших героев и обращают их против нас. Окажи честь нашим союзникам и упокой этих слуг Плети, тем самым подготовившись к настоящей битве.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 обращенных героев по заданию темного охотника Мезил-Кри из Павильона Похитителей Солнца на Ристалище Серебряного турнира.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошая тренировка – залог успеха. Приятно видеть твои старания.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Хороший тренировочный день никому не повредит. Рад видеть, что ты не $отставал:отставала;.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к темному охотнику Мезил-кри на Ристалище Серебряного турнира, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13772,'Великая битва','Принесите три знака искателя славы Гаджу в шатер Орды на Ристалище Серебряного турнира.$B$BЕсли вы потеряете копье, возьмите другое с любой оружейной стойки рядом со стойлами или в Павильоне Похитителей Солнца.','Вернитесь к Гаджу на Ристалище Серебряного турнира, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Великая битва',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите три знака искателя славы Гаджу в шатер Орды на Ристалище Серебряного турнира.$B$BЕсли вы потеряете копье, возьмите другое с любой оружейной стойки рядом со стойлами или в Павильоне Похитителей Солнца.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гаджу на Ристалище Серебряного турнира, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13773,'Клинок, достойный чемпиона','Ходят слухи, что чемпионы Альянса отправились на поиски древних клинков для своих бойцов. Нельзя допустить, чтобы они получили столь значительное преимущество!$B$BЕсть одна древняя легенда о деве из Седых холмов, которая охраняет могущественный клинок. Говорят, будто страшное проклятие превратило ее в лягушку, чтобы никто больше не смог коснуться этого меча. Теперь она живет среди прудовых лягушек на берегу Ясеневого озера, что к востоку от Ясеневой заставы... И только поцелуй любви, дарованный от чистого сердца, может разрушить злые чары. Только не забудь воспользоваться этим бальзамом для губ – иначе покроешься бородавками.','Так значит, это не сказки? Какой замечательный клинок! С его помощью я одолею любого заезжего альянсовца!','Вам удалось вернуть клинок?','Вернитесь к Руноку Буйногривому на Ристалище Серебряного турнира, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Клинок, достойный чемпиона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ходят слухи, что чемпионы Альянса отправились на поиски древних клинков для своих бойцов. Нельзя допустить, чтобы они получили столь значительное преимущество!$B$BЕсть одна древняя легенда о деве из Седых холмов, которая охраняет могущественный клинок. Говорят, будто страшное проклятие превратило ее в лягушку, чтобы никто больше не смог коснуться этого меча. Теперь она живет среди прудовых лягушек на берегу Ясеневого озера, что к востоку от Ясеневой заставы... И только поцелуй любви, дарованный от чистого сердца, может разрушить злые чары. Только не забудь воспользоваться этим бальзамом для губ – иначе покроешься бородавками.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так значит, это не сказки? Какой замечательный клинок! С его помощью я одолею любого заезжего альянсовца!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вам удалось вернуть клинок?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Руноку Буйногривому на Ристалище Серебряного турнира, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13774,'Достойное оружие','Что за невезение!$B$BМой турнирный клинок куда-то делся, а сражение должно состояться сегодня днем!$B$BОдин бард рассказал мне, что некая дева дарит путникам ценные вещицы в обмен на букетик зимних гиацинтов. Эти цветы растут только на льду, идущем вниз по реке от Железной плотины, на северо-западе от границы между Ледяной Короной и лесом Хрустальной Песни. Собери цветы и отнеси их к озеру Драк\'Мар, оно расположено в северо-восточной части Драконьего Погоста, почти на границе с Зул\'Драком и Седыми холмами. И попроси у девы хороший клинок.','Этот меч поможет мне одолеть соперников. Спасибо тебе, $N.','Так барды говорят правду? Меч действительно существует?','Вернитесь к Руноку Буйногривому на Ристалище Серебряного турнира, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Достойное оружие',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что за невезение!$B$BМой турнирный клинок куда-то делся, а сражение должно состояться сегодня днем!$B$BОдин бард рассказал мне, что некая дева дарит путникам ценные вещицы в обмен на букетик зимних гиацинтов. Эти цветы растут только на льду, идущем вниз по реке от Железной плотины, на северо-западе от границы между Ледяной Короной и лесом Хрустальной Песни. Собери цветы и отнеси их к озеру Драк\'Мар, оно расположено в северо-восточной части Драконьего Погоста, почти на границе с Зул\'Драком и Седыми холмами. И попроси у девы хороший клинок.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Этот меч поможет мне одолеть соперников. Спасибо тебе, $N.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Так барды говорят правду? Меч действительно существует?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Руноку Буйногривому на Ристалище Серебряного турнира, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13775,'Клинок Зимы','Не зря об этом мече слагали легенды. Думаю, кузнецу не стоит потеть над моим старым клинком – Клинок Зимы куда лучше, и отныне я буду сражаться только им. Благодарю тебя, $N.','Ну как? Получилось добыть меч?','Вернитесь к Руноку Буйногривому на Ристалище Серебряного турнира, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Клинок Зимы',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Не зря об этом мече слагали легенды. Думаю, кузнецу не стоит потеть над моим старым клинком – Клинок Зимы куда лучше, и отныне я буду сражаться только им. Благодарю тебя, $N.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как? Получилось добыть меч?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Руноку Буйногривому на Ристалище Серебряного турнира, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13776,'Теория и практика','Турнир – это возможность помериться силой с другими героями, но стоит помнить и о том, что главный враг – Плеть – не дремлет. Ты оттачиваешь мастерство в поединках с товарищами, но тебе столь же необходимо совершенствоваться в битвах с неприятелем.$B$BОтправляйся в область к юго-западу от долины Павших Героев и к северу от Корп\'Ретар. Там Плеть поднимает павших воинов из мертвых и отправляет их на битву с нами. Убей несколько приспешников Плети и готовься к дальнейшим подвигам.','Убейте 10 обращенных героев по заданию Дерна Тотема Ярости из Павильона Похитителей Солнца на Ристалище Серебряного турнира.','Хорошая тренировка – залог успеха. Приятно видеть твои старания.','Хороший тренировочный день никому не повредит. Рад видеть, что ты не $отставал:отставала;.','Вернитесь к Дерну Тотему Ярости на Ристалище Серебряного турнира, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Теория и практика',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Турнир – это возможность помериться силой с другими героями, но стоит помнить и о том, что главный враг – Плеть – не дремлет. Ты оттачиваешь мастерство в поединках с товарищами, но тебе столь же необходимо совершенствоваться в битвах с неприятелем.$B$BОтправляйся в область к юго-западу от долины Павших Героев и к северу от Корп\'Ретар. Там Плеть поднимает павших воинов из мертвых и отправляет их на битву с нами. Убей несколько приспешников Плети и готовься к дальнейшим подвигам.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 обращенных героев по заданию Дерна Тотема Ярости из Павильона Похитителей Солнца на Ристалище Серебряного турнира.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошая тренировка – залог успеха. Приятно видеть твои старания.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Хороший тренировочный день никому не повредит. Рад видеть, что ты не $отставал:отставала;.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дерну Тотему Ярости на Ристалище Серебряного турнира, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13777,'Великая битва','Великая битва – одно из самых важных соревнований турнира. Победа достанется нелегко, но я в тебе уверена. Продолжай тренировки верхом, до тех пор, пока не сможешь действовать как одно целое со своим верховым животным.$B$BЯ помогу тебе подготовиться к битве. Иди в стойла за павильоном, оседлай мулгорского кодо и брось вызов искателям славы. Ты найдешь их прямо за этой палаткой на Арене искателей славы Орды.','Принесите три знака искателя славы Анке Точеное Копыто в шатер Орды на Ристалище Серебряного турнира.$B$BЕсли вы потеряете копье, возьмите другое с любой оружейной стойки рядом со стойлами или в Павильоне Похитителей Солнца.','Ты уже $Gготов:готова; принять участие в великой битве?','Вернитесь к Анке Точеное Копыто на Ристалище Серебряного турнира, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Великая битва',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Великая битва – одно из самых важных соревнований турнира. Победа достанется нелегко, но я в тебе уверена. Продолжай тренировки верхом, до тех пор, пока не сможешь действовать как одно целое со своим верховым животным.$B$BЯ помогу тебе подготовиться к битве. Иди в стойла за павильоном, оседлай мулгорского кодо и брось вызов искателям славы. Ты найдешь их прямо за этой палаткой на Арене искателей славы Орды.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите три знака искателя славы Анке Точеное Копыто в шатер Орды на Ристалище Серебряного турнира.$B$BЕсли вы потеряете копье, возьмите другое с любой оружейной стойки рядом со стойлами или в Павильоне Похитителей Солнца.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты уже $Gготов:готова; принять участие в великой битве?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Анке Точеное Копыто на Ристалище Серебряного турнира, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (13778,'Клинок, достойный чемпиона','Ходят слухи, что чемпионы Альянса отправились на поиски древних клинков для своих бойцов. Нельзя допустить, чтобы они получили столь значительное преимущество!$B$BЕсть одна древняя легенда о деве из Седых холмов, которая охраняет могущественный клинок. Говорят, будто страшное проклятие превратило ее в лягушку, чтобы никто больше не смог коснуться этого меча. Теперь она живет среди прудовых лягушек на берегу Ясеневого озера, что к востоку от Ясеневой заставы... И только поцелуй любви, дарованный от чистого сердца, может разрушить злые чары. Только не забудь воспользоваться этим бальзамом для губ – иначе покроешься бородавками.','Так значит, это не сказки? Какой замечательный клинок! С его помощью я одолею любого заезжего альянсовца!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Клинок, достойный чемпиона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ходят слухи, что чемпионы Альянса отправились на поиски древних клинков для своих бойцов. Нельзя допустить, чтобы они получили столь значительное преимущество!$B$BЕсть одна древняя легенда о деве из Седых холмов, которая охраняет могущественный клинок. Говорят, будто страшное проклятие превратило ее в лягушку, чтобы никто больше не смог коснуться этого меча. Теперь она живет среди прудовых лягушек на берегу Ясеневого озера, что к востоку от Ясеневой заставы... И только поцелуй любви, дарованный от чистого сердца, может разрушить злые чары. Только не забудь воспользоваться этим бальзамом для губ – иначе покроешься бородавками.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так значит, это не сказки? Какой замечательный клинок! С его помощью я одолею любого заезжего альянсовца!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13779,'Достойное оружие','Принесите меч Драк\'Мара ловчему смерти Визери на Ристалище Серебряного турнира.','Так барды говорят правду? Меч действительно существует?','Вернитесь к ловчему смерти Визери на Ристалище Серебряного турнира, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Достойное оружие',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите меч Драк\'Мара ловчему смерти Визери на Ристалище Серебряного турнира.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Так барды говорят правду? Меч действительно существует?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ловчему смерти Визери на Ристалище Серебряного турнира, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13780,'Клинок Зимы','Ловчий смерти Визери из Павильона Похитителей Солнца на Ристалище Серебряного турнира просит вас принести Клинок Зимы.','Ну как? Получилось добыть меч?','Вернитесь к ловчему смерти Визери на Ристалище Серебряного турнира, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Клинок Зимы',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Ловчий смерти Визери из Павильона Похитителей Солнца на Ристалище Серебряного турнира просит вас принести Клинок Зимы.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как? Получилось добыть меч?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ловчему смерти Визери на Ристалище Серебряного турнира, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13781,'Теория и практика','Турнир – это возможность помериться силой с другими героями, но стоит помнить и о том, что главный враг – Плеть – не дремлет. Ты оттачиваешь мастерство в поединках с товарищами, но тебе столь же необходимо совершенствоваться в битвах с неприятелем.$B$BОтправляйся на юго-запад Долины павших героев, что к северу от Корп\'ретара – там приспешники Плети поднимают из небытия павших героев и обращают их против нас. Окажи честь нашим союзникам и упокой этих слуг Плети, тем самым подготовившись к настоящей битве.','Убейте 10 обращенных героев по заданию Сары Чолк из Павильона Похитителей Солнца на Ристалище Серебряного турнира.','Хорошая тренировка – залог успеха. Приятно видеть твои старания.','Хороший тренировочный день никому не повредит. Рад видеть, что ты не $отставал:отставала;.','Вернитесь к Саре Чолк на Ристалище Серебряного турнира, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Теория и практика',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Турнир – это возможность помериться силой с другими героями, но стоит помнить и о том, что главный враг – Плеть – не дремлет. Ты оттачиваешь мастерство в поединках с товарищами, но тебе столь же необходимо совершенствоваться в битвах с неприятелем.$B$BОтправляйся на юго-запад Долины павших героев, что к северу от Корп\'ретара – там приспешники Плети поднимают из небытия павших героев и обращают их против нас. Окажи честь нашим союзникам и упокой этих слуг Плети, тем самым подготовившись к настоящей битве.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 обращенных героев по заданию Сары Чолк из Павильона Похитителей Солнца на Ристалище Серебряного турнира.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошая тренировка – залог успеха. Приятно видеть твои старания.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Хороший тренировочный день никому не повредит. Рад видеть, что ты не $отставал:отставала;.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Саре Чолк на Ристалище Серебряного турнира, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13782,'Великая битва','Великая битва – одно из самых важных соревнований турнира. Победа достанется нелегко, но я в тебе уверен. Продолжай тренировки верхом, до тех пор, пока не сможешь действовать как одно целое со своим верховым животным.$B$BЯ помогу тебе подготовиться к битве. Иди в стойла и оседлай боевого коня Отрекшихся и брось вызов искателям славы. Ты найдешь их прямо за этой палаткой на Арене искателей славы Орды.','Принесите три знака искателя славы дрессировщику Дречу в шатер Орды на Ристалище Серебряного турнира.$B$BЕсли вы потеряете копье, возьмите другое с любой оружейной стойки рядом со стойлами или в Павильоне Похитителей Солнца.','Вернитесь к дрессировщику Дречу на Ристалище Серебряного турнира, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Великая битва',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Великая битва – одно из самых важных соревнований турнира. Победа достанется нелегко, но я в тебе уверен. Продолжай тренировки верхом, до тех пор, пока не сможешь действовать как одно целое со своим верховым животным.$B$BЯ помогу тебе подготовиться к битве. Иди в стойла и оседлай боевого коня Отрекшихся и брось вызов искателям славы. Ты найдешь их прямо за этой палаткой на Арене искателей славы Орды.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите три знака искателя славы дрессировщику Дречу в шатер Орды на Ристалище Серебряного турнира.$B$BЕсли вы потеряете копье, возьмите другое с любой оружейной стойки рядом со стойлами или в Павильоне Похитителей Солнца.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к дрессировщику Дречу на Ристалище Серебряного турнира, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (13783,'Клинок, достойный чемпиона','Ходят слухи, что чемпионы Альянса отправились на поиски древних клинков для своих бойцов. Нельзя допустить, чтобы они получили столь значительное преимущество!$B$BЕсть одна древняя легенда о деве из Седых холмов, которая охраняет могущественный клинок. Говорят, будто страшное проклятие превратило ее в лягушку, чтобы никто больше не смог коснуться этого меча. Теперь она живет среди прудовых лягушек на берегу Ясеневого озера, что к востоку от Ясеневой заставы... И только поцелуй любви, дарованный от чистого сердца, может разрушить злые чары. Только не забудь воспользоваться этим бальзамом для губ – иначе покроешься бородавками.','Так значит, это не сказки? Какой замечательный клинок! С его помощью я одолею любого заезжего альянсовца!','Вернитесь к Эрессее Певице Рассвета на Ристалище Серебряного турнира, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Клинок, достойный чемпиона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ходят слухи, что чемпионы Альянса отправились на поиски древних клинков для своих бойцов. Нельзя допустить, чтобы они получили столь значительное преимущество!$B$BЕсть одна древняя легенда о деве из Седых холмов, которая охраняет могущественный клинок. Говорят, будто страшное проклятие превратило ее в лягушку, чтобы никто больше не смог коснуться этого меча. Теперь она живет среди прудовых лягушек на берегу Ясеневого озера, что к востоку от Ясеневой заставы... И только поцелуй любви, дарованный от чистого сердца, может разрушить злые чары. Только не забудь воспользоваться этим бальзамом для губ – иначе покроешься бородавками.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так значит, это не сказки? Какой замечательный клинок! С его помощью я одолею любого заезжего альянсовца!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Эрессее Певице Рассвета на Ристалище Серебряного турнира, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13784,'Достойное оружие','Что за невезение!$B$BМой турнирный клинок куда-то делся, а сражение должно состояться сегодня днем!$B$BОдин бард рассказал мне, что некая дева дарит путникам ценные вещицы в обмен на букетик зимних гиацинтов. Эти цветы растут только на льду, идущем вниз по реке от Железной плотины, на северо-западе от границы между Ледяной Короной и лесом Хрустальной Песни. Собери цветы и отнеси их к озеру Драк\'Мар, оно расположено в северо-восточной части Драконьего Погоста, почти на границе с Зул\'Драком и Седыми холмами. И попроси у девы хороший клинок. И попроси у девы хороший клинок.','Принесите меч Драк\'Мара Эрессее Певице Рассвета в Павильон Похитителей Солнца на Ристалище Серебряного турнира.','Так барды говорят правду? Меч действительно существует?','Вернитесь к Эрессее Певице Рассвета на Ристалище Серебряного турнира, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Достойное оружие',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что за невезение!$B$BМой турнирный клинок куда-то делся, а сражение должно состояться сегодня днем!$B$BОдин бард рассказал мне, что некая дева дарит путникам ценные вещицы в обмен на букетик зимних гиацинтов. Эти цветы растут только на льду, идущем вниз по реке от Железной плотины, на северо-западе от границы между Ледяной Короной и лесом Хрустальной Песни. Собери цветы и отнеси их к озеру Драк\'Мар, оно расположено в северо-восточной части Драконьего Погоста, почти на границе с Зул\'Драком и Седыми холмами. И попроси у девы хороший клинок. И попроси у девы хороший клинок.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите меч Драк\'Мара Эрессее Певице Рассвета в Павильон Похитителей Солнца на Ристалище Серебряного турнира.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Так барды говорят правду? Меч действительно существует?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Эрессее Певице Рассвета на Ристалище Серебряного турнира, что в Ледяной Короне.',`completedtext_loc8`);
