INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13786,'Теория и практика','Турнир – это возможность помериться силой с другими героями, но стоит помнить и о том, что главный враг – Плеть – не дремлет. Ты оттачиваешь мастерство в поединках с товарищами, но тебе столь же необходимо совершенствоваться в битвах с неприятелем.$B$BОтправляйся на юго-запад Долины павших героев, что к северу от Корп\'ретара – там приспешники Плети поднимают из небытия павших героев и обращают их против нас. Окажи честь нашим союзникам и упокой этих слуг Плети, тем самым подготовившись к настоящей битве.','Убейте 10 обращенных героев по заданию Кетиэля Солнечного Копья из Павильона Похитителей Солнца на Ристалище Серебряного турнира.','Хорошая тренировка – залог успеха. Приятно видеть твои старания.','Хороший тренировочный день никому не повредит. Рад видеть, что ты не $отставал:отставала;.','Вернитесь к Кетиэлю Солнечному Копью на Ристалище Серебряного турнира, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Теория и практика',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Турнир – это возможность помериться силой с другими героями, но стоит помнить и о том, что главный враг – Плеть – не дремлет. Ты оттачиваешь мастерство в поединках с товарищами, но тебе столь же необходимо совершенствоваться в битвах с неприятелем.$B$BОтправляйся на юго-запад Долины павших героев, что к северу от Корп\'ретара – там приспешники Плети поднимают из небытия павших героев и обращают их против нас. Окажи честь нашим союзникам и упокой этих слуг Плети, тем самым подготовившись к настоящей битве.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 обращенных героев по заданию Кетиэля Солнечного Копья из Павильона Похитителей Солнца на Ристалище Серебряного турнира.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошая тренировка – залог успеха. Приятно видеть твои старания.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Хороший тренировочный день никому не повредит. Рад видеть, что ты не $отставал:отставала;.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кетиэлю Солнечному Копью на Ристалище Серебряного турнира, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (13787,'Великая битва','Вернитесь к Анире Турон на Ристалище Серебряного турнира, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Великая битва',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Анире Турон на Ристалище Серебряного турнира, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13788,'Атака с воздуха','После того как тебе удалось обнаружить лазутчика Культа Проклятых, Серебряный Авангард приказал удвоить охрану. Они не верят, что Культ остановит поражение Черного рыцаря.$B$BВскоре после этого наши воздушные разведчики видели Ледяную Пасть – змея, который возглавляет отряд наемников Культа.$B$BТы должен перехватить их до того, как они нападут на нас. Ледяную Пасть видели на юго-западе, между Железным валом и Алдур\'таром.','Крок Гроза Плети с Ристалища Серебряного турнира просит вас уничтожить Ледяную Пасть и 3 бомбистов-сектантов.','Вы одержали победили отряд сектантов Культа Проклятых?','Вернитесь к Кроку Грозе Плети в Ледяную Корону.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Атака с воздуха',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','После того как тебе удалось обнаружить лазутчика Культа Проклятых, Серебряный Авангард приказал удвоить охрану. Они не верят, что Культ остановит поражение Черного рыцаря.$B$BВскоре после этого наши воздушные разведчики видели Ледяную Пасть – змея, который возглавляет отряд наемников Культа.$B$BТы должен перехватить их до того, как они нападут на нас. Ледяную Пасть видели на юго-западе, между Железным валом и Алдур\'таром.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Крок Гроза Плети с Ристалища Серебряного турнира просит вас уничтожить Ледяную Пасть и 3 бомбистов-сектантов.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы одержали победили отряд сектантов Культа Проклятых?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кроку Грозе Плети в Ледяную Корону.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13789,'Битва на вражеской территории','Для постройки Колизея было выбрано очень опасное место, $n. За эти земли, отбитые у Плети, мы заплатили кровью и болью, но враг и сейчас не прекращает атаковать нас бесчисленным войском.Хуже того, эту ненавистную нежить поддерживают приверженцы среди Культа Проклятых.$B$BОтправляйся в Ледяную Корону, и убивай всех служителей культа Проклятых, которые тебе встретятся.','Убейте 15 членов Культа Проклятых в Ледяной Короне по заданию Селлиана Первого Луча из Серебряного павильона на Ристалище Серебряного турнира. Вы можете найти их в любой области Ледяной Короны.','Ты испытал себя в бою против Плети?','Вернитесь к Селлиану Первому Лучу на Ристалище Серебряного турнира в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Битва на вражеской территории',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Для постройки Колизея было выбрано очень опасное место, $n. За эти земли, отбитые у Плети, мы заплатили кровью и болью, но враг и сейчас не прекращает атаковать нас бесчисленным войском.Хуже того, эту ненавистную нежить поддерживают приверженцы среди Культа Проклятых.$B$BОтправляйся в Ледяную Корону, и убивай всех служителей культа Проклятых, которые тебе встретятся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 15 членов Культа Проклятых в Ледяной Короне по заданию Селлиана Первого Луча из Серебряного павильона на Ристалище Серебряного турнира. Вы можете найти их в любой области Ледяной Короны.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты испытал себя в бою против Плети?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Селлиану Первому Лучу на Ристалище Серебряного турнира в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (13790,'На равных с чемпионами','Итак, чемпион, ты $gосвоил:освоила; искусство верхового поединка и $gпрошел:прошла; испытания всех уровней. Теперь настала пора убедиться, что ты можешь одолеть любого противника на турнире.$B$BПродолжай оттачивать приемы боя, узнавай больше о слабых местах своих оппонентов. Чемпионы всех городов тренируются на Арене чемпионов. Отправляйся в стойла, выбери себе ездовое животное и сразись с ними.','Вернитесь к Луури на Ристалище Серебряного турнира в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На равных с чемпионами',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Итак, чемпион, ты $gосвоил:освоила; искусство верхового поединка и $gпрошел:прошла; испытания всех уровней. Теперь настала пора убедиться, что ты можешь одолеть любого противника на турнире.$B$BПродолжай оттачивать приемы боя, узнавай больше о слабых местах своих оппонентов. Чемпионы всех городов тренируются на Арене чемпионов. Отправляйся в стойла, выбери себе ездовое животное и сразись с ними.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Луури на Ристалище Серебряного турнира в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13791,'Битва на вражеской территории','Пока мы тут играем в войну, неплохо было бы вспомнить о том, что нас окружают реальные противники. Серебряный Авангард хочет найти лучших воинов с помощью турнира, но мы можем отыскать их и среди тех, кто вернулся с настоящей войны. Давай покажем этим паладинам, что мы можем сражаться с Плетью даже во время подготовки к состязаниям.$B$BОтправляйся в Ледяную Корону, и убивай всех служителей культа Проклятых, которые тебе встретятся. Чаще всего они бродят вокруг Алдур\'тара и Заставы Вестника Смерти.','Убейте 15 членов Культа Проклятых в Ледяной Короне по заданию Зор\'бе Кровопускателя с Ристалища Серебряного турнира. Вы можете действовать в любой области Ледяной Короны.','Пусть все знают – мы готовы сражаться с Плетью в любой момент, где бы мы ни были и чем бы ни занимались.','Ты испытал себя в бою против Плети?','Вернитесь к Зор\'бе Кровопускателю на Ристалище Серебряного турнира в Ледяную Корону.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Битва на вражеской территории',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пока мы тут играем в войну, неплохо было бы вспомнить о том, что нас окружают реальные противники. Серебряный Авангард хочет найти лучших воинов с помощью турнира, но мы можем отыскать их и среди тех, кто вернулся с настоящей войны. Давай покажем этим паладинам, что мы можем сражаться с Плетью даже во время подготовки к состязаниям.$B$BОтправляйся в Ледяную Корону, и убивай всех служителей культа Проклятых, которые тебе встретятся. Чаще всего они бродят вокруг Алдур\'тара и Заставы Вестника Смерти.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 15 членов Культа Проклятых в Ледяной Короне по заданию Зор\'бе Кровопускателя с Ристалища Серебряного турнира. Вы можете действовать в любой области Ледяной Короны.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Пусть все знают – мы готовы сражаться с Плетью в любой момент, где бы мы ни были и чем бы ни занимались.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты испытал себя в бою против Плети?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Зор\'бе Кровопускателю на Ристалище Серебряного турнира в Ледяную Корону.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13792,'Бредущий Тенью','Теперь, когда демонические врата разрушены, мы должны восполнить жизненную силу природы. Сердце леса необходимо вернуть!$B$BВ этом нам поможет Гайван Бредущий Тенью, великий друид-медведь. Он отправился на юго-запад, мимо Холма Демонического Огня к Обители Дор\'Данил – именно там, глубоко под землей, хранится Сердце леса. Его оберегают друиды Ясеневого леса.$B$BРазыщи Гайвана и поведай ему о том, что случилось.','Поговорите с Гайваном Бредущим Тенью. Его можно найти где-то рядом со входом в Обитель Дор\'Данил, что в Ясеневом лесу.','Ты храбро поступил, добравшись сюда, но боюсь, что помощь запоздала. Все друиды либо мертвы, либо сошли с ума.$B$BОднако вести твои еще более тревожны. Если ты говоришь правду, то Кривокрону надо как можно скорее вернуть Сердце леса – иначе весь Ясеневый лес обречен на гибель!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бредущий Тенью',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда демонические врата разрушены, мы должны восполнить жизненную силу природы. Сердце леса необходимо вернуть!$B$BВ этом нам поможет Гайван Бредущий Тенью, великий друид-медведь. Он отправился на юго-запад, мимо Холма Демонического Огня к Обители Дор\'Данил – именно там, глубоко под землей, хранится Сердце леса. Его оберегают друиды Ясеневого леса.$B$BРазыщи Гайвана и поведай ему о том, что случилось.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Гайваном Бредущим Тенью. Его можно найти где-то рядом со входом в Обитель Дор\'Данил, что в Ясеневом лесу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты храбро поступил, добравшись сюда, но боюсь, что помощь запоздала. Все друиды либо мертвы, либо сошли с ума.$B$BОднако вести твои еще более тревожны. Если ты говоришь правду, то Кривокрону надо как можно скорее вернуть Сердце леса – иначе весь Ясеневый лес обречен на гибель!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (13793,'На равных с чемпионами','Итак, чемпион, ты $gосвоил:освоила; искусство верхового поединка и $gпрошел:прошла; испытания всех уровней. Теперь настала пора убедиться, что ты можешь одолеть любого противника на турнире.$B$BПродолжай оттачивать приемы боя, узнавай больше о слабых местах своих оппонентов. Чемпионы всех городов тренируются на Арене чемпионов. Отправляйся в стойла, выбери себе ездовое животное и сразись с ними.','Вернитесь к Иллирии Приход Тьмы на Ристалище Серебряного турнира в Ледяную Корону.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На равных с чемпионами',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Итак, чемпион, ты $gосвоил:освоила; искусство верхового поединка и $gпрошел:прошла; испытания всех уровней. Теперь настала пора убедиться, что ты можешь одолеть любого противника на турнире.$B$BПродолжай оттачивать приемы боя, узнавай больше о слабых местах своих оппонентов. Чемпионы всех городов тренируются на Арене чемпионов. Отправляйся в стойла, выбери себе ездовое животное и сразись с ними.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Иллирии Приход Тьмы на Ристалище Серебряного турнира в Ледяную Корону.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13794,'Эдрик Чистый','Я обратилась к моим братьям из Серебряного Авангарда с просьбой обратить особое внимание на тех, кто сумел получить звание чемпиона. Эдрик Чистый, абсолютный чемпион нашего братства, лично следит за тренировками воинов из всех городов Азерота и помогает им подготовиться к главному состязанию.$B$BПожалуйста, подойди к нему и представься. Он будет рад встретиться с тобой и подготовить тебя к поединкам с величайшими воинами Азерота.','Поговорите с Эдриком Чистым из Серебряного павильона на Ристалище Серебряного турнира.','Наконец-то мы встретились, чемпион. Верховный лорд поручил мне координировать тренировки всех чемпионов и поддерживать порядок на Ристалище.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Эдрик Чистый',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я обратилась к моим братьям из Серебряного Авангарда с просьбой обратить особое внимание на тех, кто сумел получить звание чемпиона. Эдрик Чистый, абсолютный чемпион нашего братства, лично следит за тренировками воинов из всех городов Азерота и помогает им подготовиться к главному состязанию.$B$BПожалуйста, подойди к нему и представься. Он будет рад встретиться с тобой и подготовить тебя к поединкам с величайшими воинами Азерота.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Эдриком Чистым из Серебряного павильона на Ристалище Серебряного турнира.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Наконец-то мы встретились, чемпион. Верховный лорд поручил мне координировать тренировки всех чемпионов и поддерживать порядок на Ристалище.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13795,'Гроза Плети','Поговорите с Кроком Грозой Плети в северной стороне Ристалище Серебряного турнира.','Значит, ты $Gстал:стала; чемпионом, $N? Я никогда в тебе не сомневался. Мы, рыцари, созданы для битвы, а не для тренировок с деревянными манекенами. Давай покажем этим паладинам и их гостям, на что мы способны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гроза Плети',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Кроком Грозой Плети в северной стороне Ристалище Серебряного турнира.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Значит, ты $Gстал:стала; чемпионом, $N? Я никогда в тебе не сомневался. Мы, рыцари, созданы для битвы, а не для тренировок с деревянными манекенами. Давай покажем этим паладинам и их гостям, на что мы способны.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13796,'Сердце леса','Ты $Gдолжен:должна; любой ценой доставить Сердце леса Кривокрону!$B$BОскверненное Ордой, оно хранится в глубине Обители Дор\'Данил. Только Кривокрон способен очистить его от зла.$B$BНо чтобы прикоснуться к нему, тебе понадобится Сила природы. Собери несколько непорочных душ покалеченных друидов и хранителей, чтобы они смогли объединиться в Силу природы.$B$BУдачи, $n!','Добудьте Сердце леса.','Вернитесь к Кривокрону на лесопилку Песни Войны, что в Ясеневом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сердце леса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $Gдолжен:должна; любой ценой доставить Сердце леса Кривокрону!$B$BОскверненное Ордой, оно хранится в глубине Обители Дор\'Данил. Только Кривокрон способен очистить его от зла.$B$BНо чтобы прикоснуться к нему, тебе понадобится Сила природы. Собери несколько непорочных душ покалеченных друидов и хранителей, чтобы они смогли объединиться в Силу природы.$B$BУдачи, $n!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте Сердце леса.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кривокрону на лесопилку Песни Войны, что в Ясеневом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13797,'Грязные делишки','Что нужно Драаке – так это некий магнит, к которому бы притягивались демонические снаряды.$b$b<Дуран смущенно ухмыляется.>$b$bКажется, я знаю, что нам поможет.$b$bОтыщи в шахтах куски руды величиной с кулак, а я пока приготовлю особые... чары.','Осмотрите кучки свежих обломков и найдите 10 кусков руды.','Молодец! Это удержит распространение проклятия на какое-то время...','Ты собрал нужную нам руду?','Вернитесь к Дурану в шахту Расщепленного Дерева, что в Ясеневом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Грязные делишки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что нужно Драаке – так это некий магнит, к которому бы притягивались демонические снаряды.$b$b<Дуран смущенно ухмыляется.>$b$bКажется, я знаю, что нам поможет.$b$bОтыщи в шахтах куски руды величиной с кулак, а я пока приготовлю особые... чары.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Осмотрите кучки свежих обломков и найдите 10 кусков руды.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Молодец! Это удержит распространение проклятия на какое-то время...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты собрал нужную нам руду?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дурану в шахту Расщепленного Дерева, что в Ясеневом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (13799,'Where Are My Keys?','I can\'t find my keys -- I suspect my evil twin is at fault. "Take care" of him for me, $n.','Dr. Fingers wants you to kill his evil clone, Evil Fingers, and retrieve his keys.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Where Are My Keys?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','I can\'t find my keys -- I suspect my evil twin is at fault. "Take care" of him for me, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Dr. Fingers wants you to kill his evil clone, Evil Fingers, and retrieve his keys.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (13800,'Get My Keys!','Get \'em!','Find Dr. Fingers\' Keys.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Get My Keys!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Get \'em!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Find Dr. Fingers\' Keys.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (13801,'Голоса мертвых эльфов','Т...ты это слышишь? Призраки! Ненавижу призраков!$b$bИх завывания доносятся прямо из курганов на юге. О-о, заставь их замолчать!!!$b$bПожалуйста, $gмилостливый господин:милостливая госпожа;, я заплачу – только пусть эти звуки более меня не мучают!','Уничтожьте 15 любых призраков ночных эльфов в Обители Дор\'Данил.','Ура!$B$BТы заставил голоса умолкнуть! Спасибо, спасибо тебе!','Поговорите с Пиксель на Заставе Расщепленного Дерева.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Голоса мертвых эльфов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Т...ты это слышишь? Призраки! Ненавижу призраков!$b$bИх завывания доносятся прямо из курганов на юге. О-о, заставь их замолчать!!!$b$bПожалуйста, $gмилостливый господин:милостливая госпожа;, я заплачу – только пусть эти звуки более меня не мучают!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 15 любых призраков ночных эльфов в Обители Дор\'Данил.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ура!$B$BТы заставил голоса умолкнуть! Спасибо, спасибо тебе!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Пиксель на Заставе Расщепленного Дерева.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (13802,'The Goblin with Two Brains','Do you see them, along the shore? Such magnificent specimens! Look at their primitive society in action, working like a well-oiled machine from the lowliest grunt to their leader, who I\'ve named "King Burgrurble."$B$BI must study their brains.$B$BCan you procure an intact Slobberfang Murloc brain stem for me? Kill them – for science!','Bring a Slobberfang Murloc Brain Stem to Professor Flozz along the coast.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','The Goblin with Two Brains',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Do you see them, along the shore? Such magnificent specimens! Look at their primitive society in action, working like a well-oiled machine from the lowliest grunt to their leader, who I\'ve named "King Burgrurble."$B$BI must study their brains.$B$BCan you procure an intact Slobberfang Murloc brain stem for me? Kill them – for science!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Bring a Slobberfang Murloc Brain Stem to Professor Flozz along the coast.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (13803,'Кровь слабых','Осквернить Сердце Леса?$B$BКакое жестокое, чудовищное в своей порочности деяние!$B$BЯ просто в восторге от этой идеи!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кровь слабых',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Осквернить Сердце Леса?$B$BКакое жестокое, чудовищное в своей порочности деяние!$B$BЯ просто в восторге от этой идеи!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (13804,'To Catch a Fish-Thing','Look at these results! Such a unique electrochemical makeup -- ah, but I wouldn\'t suspect a lowly $c would understand the magnormity of what I\'ve discovered here. I\'ll need a live specimen.$B$BI would acquire one myself, but apparently they bite.$B$BHere, I\'ve configured this trap to hone in on their unique brain patterns. Just set the trap, then hit this button to slurp up a Slobberfang. But first, I\'ll need you to sign this indemnification waiver. This technology is bleeding edge!','Place a trap and use the remote to capture a live Slobberfang Murloc. Return the filled trap to Professor Flozz.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','To Catch a Fish-Thing',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Look at these results! Such a unique electrochemical makeup -- ah, but I wouldn\'t suspect a lowly $c would understand the magnormity of what I\'ve discovered here. I\'ll need a live specimen.$B$BI would acquire one myself, but apparently they bite.$B$BHere, I\'ve configured this trap to hone in on their unique brain patterns. Just set the trap, then hit this button to slurp up a Slobberfang. But first, I\'ll need you to sign this indemnification waiver. This technology is bleeding edge!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Place a trap and use the remote to capture a live Slobberfang Murloc. Return the filled trap to Professor Flozz.',`objectives_loc8`);
