INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (13808,'Миссия немыслима','Да, дружище, для тебя тут найдется работа.$B$BНадеюсь, ты за нее возьмешься...','Поговорите с Крокком у Тлеющей жаровни, что в Сатирнааре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Миссия немыслима',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, дружище, для тебя тут найдется работа.$B$BНадеюсь, ты за нее возьмешься...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Крокком у Тлеющей жаровни, что в Сатирнааре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13809,'Атака с воздуха','После того как тебе удалось обнаружить лазутчика Культа Проклятых, верховный лорд Тирион Фордринг приказал удвоить охрану. Он не верит, что их остановит поражение Черного рыцаря.$B$BВскоре после этого наши воздушные разведчики видели Ледяную Пасть – змея, который возглавляет отряд наемников Культа. Его видели на юго-западе, между Железным валом и Алдур\'таром.','Эдрик Чистый из Серебряного павильона на Ристалище Серебряного турнира просит вас уничтожить Ледяную Пасть и 3 бомбистов-сектантов.','Вы одержали победили отряд сектантов Культа Проклятых?','Вернитесь к Эдрику Чистому на Ристалище Серебряного турнира в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Атака с воздуха',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','После того как тебе удалось обнаружить лазутчика Культа Проклятых, верховный лорд Тирион Фордринг приказал удвоить охрану. Он не верит, что их остановит поражение Черного рыцаря.$B$BВскоре после этого наши воздушные разведчики видели Ледяную Пасть – змея, который возглавляет отряд наемников Культа. Его видели на юго-западе, между Железным валом и Алдур\'таром.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Эдрик Чистый из Серебряного павильона на Ристалище Серебряного турнира просит вас уничтожить Ледяную Пасть и 3 бомбистов-сектантов.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы одержали победили отряд сектантов Культа Проклятых?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Эдрику Чистому на Ристалище Серебряного турнира в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13810,'Битва на вражеской территории','Для постройки Колизея было выбрано очень опасное место, $n. За эти земли, отбитые у Плети, мы заплатили кровью и болью, но враг и сейчас не прекращает атаковать нас бесчисленным войском. Хуже того, эту ненавистную нежить поддерживают приверженцы среди культа Проклятых.$B$BОтправляйся в Ледяную Корону, и убивай всех служителей культа, которые тебе встретятся.','Убейте 15 членов Культа Проклятых в Ледяной Короне по заданию Селлиана Первого Луча из Серебряного павильона на Ристалище Серебряного турнира. Вы можете найти их в любой области Ледяной Короны.','Ты испытал себя в бою против Плети?','Вернитесь к Селлиану Первому Лучу на Ристалище Серебряного турнира в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Битва на вражеской территории',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Для постройки Колизея было выбрано очень опасное место, $n. За эти земли, отбитые у Плети, мы заплатили кровью и болью, но враг и сейчас не прекращает атаковать нас бесчисленным войском. Хуже того, эту ненавистную нежить поддерживают приверженцы среди культа Проклятых.$B$BОтправляйся в Ледяную Корону, и убивай всех служителей культа, которые тебе встретятся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 15 членов Культа Проклятых в Ледяной Короне по заданию Селлиана Первого Луча из Серебряного павильона на Ристалище Серебряного турнира. Вы можете найти их в любой области Ледяной Короны.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты испытал себя в бою против Плети?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Селлиану Первому Лучу на Ристалище Серебряного турнира в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (13811,'На равных с чемпионами','Итак, чемпион, ты $gосвоил:освоила; искусство верхового поединка и $gпрошел:прошла; испытания всех уровней. Теперь настала пора убедиться, что ты можешь одолеть любого противника на турнире.$B$BПродолжай оттачивать приемы боя, узнавай больше о слабых местах своих оппонентов. Чемпионы всех городов тренируются на Арене чемпионов. Отправляйся в стойла, выбери себе ездовое животное и сразись с ними.','Вернитесь к Луури на Ристалище Серебряного турнира в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На равных с чемпионами',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Итак, чемпион, ты $gосвоил:освоила; искусство верхового поединка и $gпрошел:прошла; испытания всех уровней. Теперь настала пора убедиться, что ты можешь одолеть любого противника на турнире.$B$BПродолжай оттачивать приемы боя, узнавай больше о слабых местах своих оппонентов. Чемпионы всех городов тренируются на Арене чемпионов. Отправляйся в стойла, выбери себе ездовое животное и сразись с ними.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Луури на Ристалище Серебряного турнира в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13812,'Атака с воздуха','После того как тебе удалось обнаружить лазутчика Культа Проклятых, Серебряный Авангард приказал удвоить охрану. Они не верят, что Культ остановит поражение Черного рыцаря.$B$BВскоре после этого наши воздушные разведчики видели Ледяную Пасть – змея, который возглавляет отряд наемников Культа.$B$BТы должен перехватить их до того, как они нападут на нас. Ледяную Пасть видели на юго-западе, между Железным валом и Алдур\'таром.','Крок Гроза Плети с Ристалища Серебряного турнира просит вас уничтожить Ледяную Пасть и 3 бомбистов-сектантов.','Вы одержали победили отряд сектантов Культа Проклятых?','Вернитесь к Кроку Грозе Плети в Ледяную Корону.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Атака с воздуха',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','После того как тебе удалось обнаружить лазутчика Культа Проклятых, Серебряный Авангард приказал удвоить охрану. Они не верят, что Культ остановит поражение Черного рыцаря.$B$BВскоре после этого наши воздушные разведчики видели Ледяную Пасть – змея, который возглавляет отряд наемников Культа.$B$BТы должен перехватить их до того, как они нападут на нас. Ледяную Пасть видели на юго-западе, между Железным валом и Алдур\'таром.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Крок Гроза Плети с Ристалища Серебряного турнира просит вас уничтожить Ледяную Пасть и 3 бомбистов-сектантов.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы одержали победили отряд сектантов Культа Проклятых?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кроку Грозе Плети в Ледяную Корону.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13813,'Битва на вражеской территории','Пока мы тут играем в войну, неплохо было бы вспомнить о том, что нас окружают реальные противники. Серебряный Авангард хочет найти лучших воинов с помощью турнира, но мы можем отыскать их и среди тех, кто вернулся из настоящей битвы. Давай покажем этим паладинам, что мы можем сражаться с Плетью даже во время подготовки к состязаниям.$B$BОтправляйся в Ледяную Корону, и убивай всех служителей культа Проклятых, которые тебе встретятся. Чаще всего они бродят вокруг Алдур\'тара и Заставы Вестника Смерти.','Убейте 15 членов Культа Проклятых в Ледяной Короне по заданию Зор\'бе Кровопускателя с Ристалища Серебряного турнира. Вы можете действовать в любой области Ледяной Короны.','Пусть все знают – мы готовы сражаться с Плетью в любой момент, где бы мы ни были и чем бы ни занимались.','Ты испытал себя в бою против Плети?','Вернитесь к Зор\'бе Кровопускателю на Ристалище Серебряного турнира в Ледяную Корону.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Битва на вражеской территории',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пока мы тут играем в войну, неплохо было бы вспомнить о том, что нас окружают реальные противники. Серебряный Авангард хочет найти лучших воинов с помощью турнира, но мы можем отыскать их и среди тех, кто вернулся из настоящей битвы. Давай покажем этим паладинам, что мы можем сражаться с Плетью даже во время подготовки к состязаниям.$B$BОтправляйся в Ледяную Корону, и убивай всех служителей культа Проклятых, которые тебе встретятся. Чаще всего они бродят вокруг Алдур\'тара и Заставы Вестника Смерти.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 15 членов Культа Проклятых в Ледяной Короне по заданию Зор\'бе Кровопускателя с Ристалища Серебряного турнира. Вы можете действовать в любой области Ледяной Короны.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Пусть все знают – мы готовы сражаться с Плетью в любой момент, где бы мы ни были и чем бы ни занимались.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты испытал себя в бою против Плети?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Зор\'бе Кровопускателю на Ристалище Серебряного турнира в Ледяную Корону.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13814,'На равных с чемпионами','Итак, чемпион, ты $gосвоил:освоила; искусство верхового поединка и $gпрошел:прошла; испытания всех уровней. Теперь настала пора убедиться, что ты можешь одолеть любого противника на турнире.$B$BПродолжай оттачивать приемы боя, узнавай больше о слабых местах своих оппонентов. Чемпионы всех городов тренируются на Арене чемпионов. Отправляйся в стойла, выбери себе ездовое животное и сразись с ними.','Принесите 4 знака чемпиона Иллирии Приходу Тьмы на Ристалище Серебряного турнира.$B$BЕсли вы потеряете копье, возьмите другое с любой оружейной стойки рядом со стойлами или в павильоне Похитителей Солнца.','Вернитесь к Иллирии Приход Тьмы на Ристалище Серебряного турнира в Ледяную Корону.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На равных с чемпионами',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Итак, чемпион, ты $gосвоил:освоила; искусство верхового поединка и $gпрошел:прошла; испытания всех уровней. Теперь настала пора убедиться, что ты можешь одолеть любого противника на турнире.$B$BПродолжай оттачивать приемы боя, узнавай больше о слабых местах своих оппонентов. Чемпионы всех городов тренируются на Арене чемпионов. Отправляйся в стойла, выбери себе ездовое животное и сразись с ними.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 4 знака чемпиона Иллирии Приходу Тьмы на Ристалище Серебряного турнира.$B$BЕсли вы потеряете копье, возьмите другое с любой оружейной стойки рядом со стойлами или в павильоне Похитителей Солнца.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Иллирии Приход Тьмы на Ристалище Серебряного турнира в Ледяную Корону.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (13815,'Лесоруб','Доложите о выполнении задания Крокку. Его можно найти у тлеющей жаровни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лесоруб',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доложите о выполнении задания Крокку. Его можно найти у тлеющей жаровни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (13816,'Священный планетарий (героич.)','Слушай внимательно! На кону – судьба всего Азерота.$B$BТолько одно спасет нас – нужно найти Священный планетарий и помешать этому Алгалону отправить сообщение его повелителям-титанам.$B$BОтыщи Священный планетарий и возвращайся со всеми данными, которые сможешь там собрать. Может быть, мы успеем подготовиться к прибытию Алгалона.','Найдите Священный планетарий по заданию геолога Лорен из Архива в Ульдуаре.','Закрыт? Так я и думал!$B$BЯ сообщу Бранну... может быть, он обнаружит какие-либо сведения в Архиве.','Вход в Священный планетарий найден','Вернитесь к геологу Лорену в Ульдуар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Священный планетарий (героич.)',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слушай внимательно! На кону – судьба всего Азерота.$B$BТолько одно спасет нас – нужно найти Священный планетарий и помешать этому Алгалону отправить сообщение его повелителям-титанам.$B$BОтыщи Священный планетарий и возвращайся со всеми данными, которые сможешь там собрать. Может быть, мы успеем подготовиться к прибытию Алгалона.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Священный планетарий по заданию геолога Лорен из Архива в Ульдуаре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Закрыт? Так я и думал!$B$BЯ сообщу Бранну... может быть, он обнаружит какие-либо сведения в Архиве.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Вход в Священный планетарий найден',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к геологу Лорену в Ульдуар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13817,'Диск доступа к Архиву (героич.)','Платиновый диск правильной формы выглядит совершенно новым – на нем нет ни единой царапины. По краю его выгравирована руническая надпись: "АРХИВ".$B$BДолжно быть, в глубинах Ульдуара есть устройство, с помощью которого можно прочитать этот диск.','Отнесите диск доступа к Архиву к панели управления Архивом в Ульдуаре.','Платиновый диск идеально подходит к гнезду на панели. Он начинает вращаться, белые лучи считывают с него какую-то информацию.','Гнездо приемника открывается, а панель управления жужжит и вибрирует.','Вернитесь к панели управления Архивом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Диск доступа к Архиву (героич.)',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Платиновый диск правильной формы выглядит совершенно новым – на нем нет ни единой царапины. По краю его выгравирована руническая надпись: "АРХИВ".$B$BДолжно быть, в глубинах Ульдуара есть устройство, с помощью которого можно прочитать этот диск.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите диск доступа к Архиву к панели управления Архивом в Ульдуаре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Платиновый диск идеально подходит к гнезду на панели. Он начинает вращаться, белые лучи считывают с него какую-то информацию.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Гнездо приемника открывается, а панель управления жужжит и вибрирует.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к панели управления Архивом.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13818,'Алгалон (героич.)','Ты $gсправился:справилась;, $n. Теперь возьми печати, отнеси их к панели управления Архивом и попытайся получить доступ к Священному планетарию.$B$BПоторопись, $gдруг:подруга; – дорога каждая секунда.','Принесите печати хранителей к панели управления Архивом в Ульдуаре.','Ожидайте подтверждения.$B$BДоступ в Священный планетарий разрешен. Пожалуйста, возьмите ключ.','Яркие лучи панели периодически освещают стеклянную поверхность, как будто ожидают ввода данных.','Вернитесь к панели управления Архивом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Алгалон (героич.)',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gсправился:справилась;, $n. Теперь возьми печати, отнеси их к панели управления Архивом и попытайся получить доступ к Священному планетарию.$B$BПоторопись, $gдруг:подруга; – дорога каждая секунда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите печати хранителей к панели управления Архивом в Ульдуаре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ожидайте подтверждения.$B$BДоступ в Священный планетарий разрешен. Пожалуйста, возьмите ключ.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Яркие лучи панели периодически освещают стеклянную поверхность, как будто ожидают ввода данных.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к панели управления Архивом.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (13819,'Все хорошо, что хорошо кончается (героич.)','Мы должны поторопиться, $n – надо передать код отклика из Даларана как можно скорее.$B$BОтнеси его Ронину, я встречу тебя там.','Доставьте код отклика "Альфа" Ронину в Даларан.','Наконец-то ты здесь. Надеюсь, это сработает.','Вернитесь к Ронину в Лес Хрустальной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Все хорошо, что хорошо кончается (героич.)',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы должны поторопиться, $n – надо передать код отклика из Даларана как можно скорее.$B$BОтнеси его Ронину, я встречу тебя там.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте код отклика "Альфа" Ронину в Даларан.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Наконец-то ты здесь. Надеюсь, это сработает.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ронину в Лес Хрустальной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13820,'Семья Рвизасовов','Верховный лорд поручил мне завершить строительство Колизея как можно быстрее. Мы бросили все наши силы на эту работу, но очень скоро обнаружили, что нам потребуется помощь в доставке материалов. Для этого я наняла парочку гоблинов – Беззла Рвизасова и его брата Боззла.$B$BОни руководят строительством юго-восточной части Ристалища. Поговори с Беззлом и узнай, не нужна ли им помощь в доставке материалов.','Поговорите с Беззлом Рвизасовом на Ристалище Серебряного турнира.','Итак, юстициар послал вас к нам? Хорошо хорошо...$B$BНам всегда может понадобиться дополнительная помощь с "запросом" материалов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Семья Рвизасовов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Верховный лорд поручил мне завершить строительство Колизея как можно быстрее. Мы бросили все наши силы на эту работу, но очень скоро обнаружили, что нам потребуется помощь в доставке материалов. Для этого я наняла парочку гоблинов – Беззла Рвизасова и его брата Боззла.$B$BОни руководят строительством юго-восточной части Ристалища. Поговори с Беззлом и узнай, не нужна ли им помощь в доставке материалов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Беззлом Рвизасовом на Ристалище Серебряного турнира.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Итак, юстициар послал вас к нам? Хорошо хорошо...$B$BНам всегда может понадобиться дополнительная помощь с "запросом" материалов.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13821,'Печать Фрейи (героич.)','Добудьте печать Фрейи по заданию геолога Лорен.$B$BЗа дополнительными сведениями обратитесь к панели управления Архивом.','Вернитесь к геологу Лорену в Ульдуар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Печать Фрейи (героич.)',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте печать Фрейи по заданию геолога Лорен.$B$BЗа дополнительными сведениями обратитесь к панели управления Архивом.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к геологу Лорену в Ульдуар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13822,'Печать Ходира (героич.)','Печать Ходира будет нелегко раздобыть. Во-первых, тебе придется одолеть самого Ходира. А во-вторых, одолеть его нужно до того, как он уничтожит сундук с печатью!$B$BВоспользуйся панелью управления Архивом, чтобы получить дополнительные сведения. Эта премудрая штуковина стоит всех библиотек мира!','Добудьте печать Ходира по заданию геолога Лорен.$B$BЗа дополнительными сведениями обратитесь к панели управления Архивом.','Вернитесь к геологу Лорену в Ульдуар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Печать Ходира (героич.)',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Печать Ходира будет нелегко раздобыть. Во-первых, тебе придется одолеть самого Ходира. А во-вторых, одолеть его нужно до того, как он уничтожит сундук с печатью!$B$BВоспользуйся панелью управления Архивом, чтобы получить дополнительные сведения. Эта премудрая штуковина стоит всех библиотек мира!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте печать Ходира по заданию геолога Лорен.$B$BЗа дополнительными сведениями обратитесь к панели управления Архивом.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к геологу Лорену в Ульдуар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13823,'Печать Торима (героич.)','Торим не в себе, $n. Он во власти темных сил.$B$BТемная сущность приняла обличье его погибшей жены, Сиф.$B$BНельзя позволить иллюзии свести его с ума. Если это случится, то мы никогда не сможем найти печать Торима!$B$BВразуми его, и побыстрее.$B$BКак обычно, за подробностями этой жуткой истории можешь обратиться к панели управления Архивом... но они вряд ли тебе понравятся.','Добудьте печать Торима по заданию геолога Лорен.$B$BЗа дополнительными сведениями обратитесь к панели управления Архивом.','Вернитесь к геологу Лорену в Ульдуар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Печать Торима (героич.)',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Торим не в себе, $n. Он во власти темных сил.$B$BТемная сущность приняла обличье его погибшей жены, Сиф.$B$BНельзя позволить иллюзии свести его с ума. Если это случится, то мы никогда не сможем найти печать Торима!$B$BВразуми его, и побыстрее.$B$BКак обычно, за подробностями этой жуткой истории можешь обратиться к панели управления Архивом... но они вряд ли тебе понравятся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте печать Торима по заданию геолога Лорен.$B$BЗа дополнительными сведениями обратитесь к панели управления Архивом.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к геологу Лорену в Ульдуар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13824,'Печать Мимирона (героич.)','Мимирон хитер – в его комнате установлен какой-то механизм самоуничтожения.$B$BЕсли хочешь получить его печать, тебе придется победить его до того, как механизм завершит свой цикл. Если тебе нужно больше информации – воспользуйся панелью управления Архивом.','Добудьте печать Мимирона по заданию геолога Лорен.$B$BЗа дополнительными сведениями обратитесь к панели управления Архивом.','Вернитесь к геологу Лорену в Ульдуар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Печать Мимирона (героич.)',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мимирон хитер – в его комнате установлен какой-то механизм самоуничтожения.$B$BЕсли хочешь получить его печать, тебе придется победить его до того, как механизм завершит свой цикл. Если тебе нужно больше информации – воспользуйся панелью управления Архивом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте печать Мимирона по заданию геолога Лорен.$B$BЗа дополнительными сведениями обратитесь к панели управления Архивом.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к геологу Лорену в Ульдуар.',`completedtext_loc8`);
