INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (13826,'Нат Пэгл, великий рыболов') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нат Пэгл, великий рыболов',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (13827,'Сокровище!','Вернитесь к сундуку с пиратскими сокровищами.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сокровище!',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к сундуку с пиратскими сокровищами.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13828,'Мастер ближнего боя','Суть турнира – это верховой поединок. Возьми копье и оседлай кель\'дорайского скакуна – он ждет тебя снаружи.$B$BВерхом на нем отправляйся к Джерану Локвуду, его можно найти с северной стороны Ристалища, на тренировочной площадке к востоку от Арены претендентов. Джеран обучит тебя тонкостям ведения ближнего боя, чтобы поединок не закончился для тебя с первым ударом.','Во время тренировки помни, чему учил тебя мастер.','Вы разговаривали с Джераном Локвудом и практиковались в рукопашном бою?','Вернитесь к чародею Таэлису на Ристалище Серебряного турнира в Ледяную Корону.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мастер ближнего боя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Суть турнира – это верховой поединок. Возьми копье и оседлай кель\'дорайского скакуна – он ждет тебя снаружи.$B$BВерхом на нем отправляйся к Джерану Локвуду, его можно найти с северной стороны Ристалища, на тренировочной площадке к востоку от Арены претендентов. Джеран обучит тебя тонкостям ведения ближнего боя, чтобы поединок не закончился для тебя с первым ударом.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Во время тренировки помни, чему учил тебя мастер.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы разговаривали с Джераном Локвудом и практиковались в рукопашном бою?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к чародею Таэлису на Ристалище Серебряного турнира в Ледяную Корону.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13829,'Мастер ближнего боя','Суть турнира – это верховой поединок. Возьми копье и оседлай крылобега Похитителей Солнца – он ждет тебя снаружи.$B$BВерхом на нем отправляйся к Джерану Локвуду, его можно найти с северной стороны Ристалища, на тренировочной площадке к востоку от Арены претендентов. Джеран обучит тебя тонкостям ведения ближнего боя, чтобы поединок не закончился для тебя с первым ударом.','Вооружитесь копьем и оседлайте крылобега Похитителей Солнца – он ждет вас снаружи павильона. Поговорите с Джераном Локвудом и отработайте прием "Выпад" 5 раз на манекене для ближнего боя. После этого вернитесь к магистру Эдиену Солнечной Низине в шатер Орды на Ристалище Серебряного турнира.','Во время тренировки помни, чему учил тебя мастер.','Вы разговаривали с Джераном Локвудом и практиковались в рукопашном бою?','Вернитесь к магистру Эдиену Солнечной Низине на Ристалище Серебряного турнира, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мастер ближнего боя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Суть турнира – это верховой поединок. Возьми копье и оседлай крылобега Похитителей Солнца – он ждет тебя снаружи.$B$BВерхом на нем отправляйся к Джерану Локвуду, его можно найти с северной стороны Ристалища, на тренировочной площадке к востоку от Арены претендентов. Джеран обучит тебя тонкостям ведения ближнего боя, чтобы поединок не закончился для тебя с первым ударом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вооружитесь копьем и оседлайте крылобега Похитителей Солнца – он ждет вас снаружи павильона. Поговорите с Джераном Локвудом и отработайте прием "Выпад" 5 раз на манекене для ближнего боя. После этого вернитесь к магистру Эдиену Солнечной Низине в шатер Орды на Ристалище Серебряного турнира.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Во время тренировки помни, чему учил тебя мастер.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы разговаривали с Джераном Локвудом и практиковались в рукопашном бою?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к магистру Эдиену Солнечной Низине на Ристалище Серебряного турнира, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (13830,'Рыба-призрак','$GВсякий стоящий рыболов:Всякая стоящая рыбачка; в Нордсколе знает о карликовой рыбе-прилипале, называемой среди знатоков "сосокунем". Она несъедобна, но алхимики часто используют ее для приготовления зелий.$B$BНо речь не об этом. Если ты внимательно присмотришься к косяку прилипал в водах Слияния рек в низине Шолазар, то заметишь затесавшуюся среди них рыбу-призрака. На воздухе она становится прозрачной и в конце концов попросту исчезает. Многие считают, что она возвращается в Шолазар, но есть и те, кто сочиняет о ней всякие небылицы.$B$BВылови эту рыбу и раскрой ее секрет!','Раскройте тайну рыбы-призрака по просьбе Марсии Чейз из Даларана.','Рыба-призрак преследует вас изо всех сил? $b$b<Марсия выглядит особенно гордой собой за свой каламбур.>','Загадка рыбы-призрака раскрыта.','Вернитесь к Марсии Чейз в Даларан.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рыба-призрак',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$GВсякий стоящий рыболов:Всякая стоящая рыбачка; в Нордсколе знает о карликовой рыбе-прилипале, называемой среди знатоков "сосокунем". Она несъедобна, но алхимики часто используют ее для приготовления зелий.$B$BНо речь не об этом. Если ты внимательно присмотришься к косяку прилипал в водах Слияния рек в низине Шолазар, то заметишь затесавшуюся среди них рыбу-призрака. На воздухе она становится прозрачной и в конце концов попросту исчезает. Многие считают, что она возвращается в Шолазар, но есть и те, кто сочиняет о ней всякие небылицы.$B$BВылови эту рыбу и раскрой ее секрет!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раскройте тайну рыбы-призрака по просьбе Марсии Чейз из Даларана.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Рыба-призрак преследует вас изо всех сил? $b$b<Марсия выглядит особенно гордой собой за свой каламбур.>',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Загадка рыбы-призрака раскрыта.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Марсии Чейз в Даларан.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13831,'Странное предписание','Неподалеку стоит грубо вытесанная аптекарская скамья, вся заваленная исписанными пергаментами и причудливыми склянками. Похоже, Отрекшиеся также изучали работы Грязного Копыта. Вы хватаете несколько свитков, которые кажутся наиболее важными, и готовитесь разгромить лабораторию. Несомненно, Целителя Деревьев заинтересует ваша находка.','Доставьте записи аптекаря Тарнариуну Исцелителю Деревьев в Лор\'данел.','Принесите записи аптекаря Тарнариуну Исцелителю Деревьев в Лор\'данел, что на Темных берегах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Странное предписание',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Неподалеку стоит грубо вытесанная аптекарская скамья, вся заваленная исписанными пергаментами и причудливыми склянками. Похоже, Отрекшиеся также изучали работы Грязного Копыта. Вы хватаете несколько свитков, которые кажутся наиболее важными, и готовитесь разгромить лабораторию. Несомненно, Целителя Деревьев заинтересует ваша находка.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте записи аптекаря Тарнариуну Исцелителю Деревьев в Лор\'данел.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите записи аптекаря Тарнариуну Исцелителю Деревьев в Лор\'данел, что на Темных берегах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13832,'Звезда сточных вод','Принесите Марсии Чейз в Даларан ржавое украшение.','Вернитесь к Марсии Чейз в Даларан.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Звезда сточных вод',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Марсии Чейз в Даларан ржавое украшение.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Марсии Чейз в Даларан.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13833,'Густая кровь','Как можно понять из названия, ужорь – это весьма прожорливая рыбешка. Лекари используют ее для варки исцеляющих составов, поэтому если хочешь заработать – иди за ужрем-кровопийцей.$B$BОни падки на кровь, поэтому проще всего убить какую-нибудь зверушку в Борейской тундре, намазаться ее кровью, затем искупаться в озерной воде и начать рыбачить.','Принесите Марсии Чейз в Даларан 5 ужрей-кровопийц.','Ну что – удалось поймать хоть одного ужорька? Не забывай – их проще всего приманить на кровь!','Вернитесь к Марсии Чейз в Даларан.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Густая кровь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как можно понять из названия, ужорь – это весьма прожорливая рыбешка. Лекари используют ее для варки исцеляющих составов, поэтому если хочешь заработать – иди за ужрем-кровопийцей.$B$BОни падки на кровь, поэтому проще всего убить какую-нибудь зверушку в Борейской тундре, намазаться ее кровью, затем искупаться в озерной воде и начать рыбачить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Марсии Чейз в Даларан 5 ужрей-кровопийц.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что – удалось поймать хоть одного ужорька? Не забывай – их проще всего приманить на кровь!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Марсии Чейз в Даларан.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13834,'Опасный деликатес','Чем ценнее улов, тем опаснее рыбалка. В озере Ледяных Оков водится редкая рыба, но ловить ее примется лишь безрассудный.$B$BЯ толкую о террорели. Она страшно ядовита и ужасно вкусна. Вот принесешь мне ее – тогда пойдет другой разговор.','Принесите Марсии Чейз в Даларан 10 террорелей.','Вернитесь к Марсии Чейз в Даларан.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Опасный деликатес',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чем ценнее улов, тем опаснее рыбалка. В озере Ледяных Оков водится редкая рыба, но ловить ее примется лишь безрассудный.$B$BЯ толкую о террорели. Она страшно ядовита и ужасно вкусна. Вот принесешь мне ее – тогда пойдет другой разговор.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Марсии Чейз в Даларан 10 террорелей.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Марсии Чейз в Даларан.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13835,'Мастер дальнего боя','Чтобы преуспеть в верховом поединке, нужно лишить противника защиты. Возьми вот это копье и оседлай кель\'дорайского скакуна – он ждет тебя снаружи.$B$BПотом езжай к Валису Ловцу Ветра, его можно найти с северной стороны Ристалища, на тренировочной площадке к востоку от Арены претендентов. Валис научит тебя приему "Удар по щиту" – это поможет тебе ослабить противника.','Вооружитесь копьем и оседлайте кель\'дорайского скакуна – он ждет вас снаружи павильона. Поговорите с Валисом Ловцом Ветра и отработайте "Удар по щиту" 2 раза на мишени для дальнего боя. После этого вернитесь к разведчице Шалиндрии на Ристалище Серебряного турнира.','Запомни уроки Валиса, $N. Они станут ключом к твоей победе в турнире.','Ты уже $Gнаучился:научилась; разбивать щиты противников?','Вернитесь к разведчице Шалиндрия на Ристалище Серебряного турнира в Ледяную Корону.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мастер дальнего боя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чтобы преуспеть в верховом поединке, нужно лишить противника защиты. Возьми вот это копье и оседлай кель\'дорайского скакуна – он ждет тебя снаружи.$B$BПотом езжай к Валису Ловцу Ветра, его можно найти с северной стороны Ристалища, на тренировочной площадке к востоку от Арены претендентов. Валис научит тебя приему "Удар по щиту" – это поможет тебе ослабить противника.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вооружитесь копьем и оседлайте кель\'дорайского скакуна – он ждет вас снаружи павильона. Поговорите с Валисом Ловцом Ветра и отработайте "Удар по щиту" 2 раза на мишени для дальнего боя. После этого вернитесь к разведчице Шалиндрии на Ристалище Серебряного турнира.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Запомни уроки Валиса, $N. Они станут ключом к твоей победе в турнире.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты уже $Gнаучился:научилась; разбивать щиты противников?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к разведчице Шалиндрия на Ристалище Серебряного турнира в Ледяную Корону.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13836,'Обезручен!','До меня дошли слухи о трагедии в даларанской тюрьме – особо опасный заключенный отгрыз руку одному из охранников и выбросил ее в воду.$b$bДоктора из больницы скорой помощи говорят, что ее еще можно пришить.$B$BДостаточно порыбачить хорошенько возле тюрьмы и, ставлю свой любимый гарпун, рука непременно всплывет на поверхность. Найди руку и принеси ее Олисарре Доброй в Даларан. Остальное она сделает сама.','Принесите откушенную руку Олисарре Доброй в Даларан.','Приветствую. У вас лишней руки не найдется?','Вернитесь к Олисарре Доброй в центр неотложной помощи в Даларане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обезручен!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','До меня дошли слухи о трагедии в даларанской тюрьме – особо опасный заключенный отгрыз руку одному из охранников и выбросил ее в воду.$b$bДоктора из больницы скорой помощи говорят, что ее еще можно пришить.$B$BДостаточно порыбачить хорошенько возле тюрьмы и, ставлю свой любимый гарпун, рука непременно всплывет на поверхность. Найди руку и принеси ее Олисарре Доброй в Даларан. Остальное она сделает сама.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите откушенную руку Олисарре Доброй в Даларан.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Приветствую. У вас лишней руки не найдется?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Олисарре Доброй в центр неотложной помощи в Даларане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13837,'Мастер стремительной атаки','Самым эффективным приемом в верховом поединке является "Рывок". Возьми копье и оседлай кель\'дорайского скакуна – он ждет тебя снаружи.$B$BВерхом на нем отправляйся к Рагану Сталебрюху, его можно найти с северной стороны Ристалища, на тренировочной площадке к востоку от Арены претендентов. Он научит тебя этому удару и покажет основные стратегические приемы.','Вооружитесь копьем и оседлайте кель\'дорайского скакуна – он ждет вас снаружи павильона. Поговорите с Раганом Сталебрюхом и отработайте "Рывок" 2 раза на манекене для стремительной атаки. После этого вернитесь к Аварету Молниеносному Удару в шатер Альянса на Ристалище Серебряного турнира.','С таким учителем, как Раган, ты не успеешь глазом моргнуть, как научишься премудростям верхового поединка.','Ты $Gнаучился:научилась; приему "Рывок"?','Вернитесь к Аварету Молниеносному Удару в Ледяную Корону.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мастер стремительной атаки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Самым эффективным приемом в верховом поединке является "Рывок". Возьми копье и оседлай кель\'дорайского скакуна – он ждет тебя снаружи.$B$BВерхом на нем отправляйся к Рагану Сталебрюху, его можно найти с северной стороны Ристалища, на тренировочной площадке к востоку от Арены претендентов. Он научит тебя этому удару и покажет основные стратегические приемы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вооружитесь копьем и оседлайте кель\'дорайского скакуна – он ждет вас снаружи павильона. Поговорите с Раганом Сталебрюхом и отработайте "Рывок" 2 раза на манекене для стремительной атаки. После этого вернитесь к Аварету Молниеносному Удару в шатер Альянса на Ристалище Серебряного турнира.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','С таким учителем, как Раган, ты не успеешь глазом моргнуть, как научишься премудростям верхового поединка.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gнаучился:научилась; приему "Рывок"?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аварету Молниеносному Удару в Ледяную Корону.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13838,'Мастер дальнего боя','Чтобы преуспеть в верховом поединке, нужно лишить противника защиты. Возьми вот это копье и оседлай крылобега Похитителей Солнца – он ждет тебя снаружи.$B$BПотом езжай к Валису Ловцу Ветра, его можно найти с северной стороны Ристалища, на тренировочной площадке к востоку от Арены претендентов. Валис научит тебя приему "Удар по щиту" – это поможет тебе ослабить противника.','Запомни уроки Валиса, $N. Они станут ключом к твоей победе в турнире.','Ты уже $Gнаучился:научилась; разбивать щиты противников?','Вернитесь к Галатии Сияющий Рассвет на Ристалище Серебряного турнира, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мастер дальнего боя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чтобы преуспеть в верховом поединке, нужно лишить противника защиты. Возьми вот это копье и оседлай крылобега Похитителей Солнца – он ждет тебя снаружи.$B$BПотом езжай к Валису Ловцу Ветра, его можно найти с северной стороны Ристалища, на тренировочной площадке к востоку от Арены претендентов. Валис научит тебя приему "Удар по щиту" – это поможет тебе ослабить противника.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Запомни уроки Валиса, $N. Они станут ключом к твоей победе в турнире.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты уже $Gнаучился:научилась; разбивать щиты противников?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Галатии Сияющий Рассвет на Ристалище Серебряного турнира, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13839,'Мастер стремительной атаки','Опыт и практика сделают из тебя непобедимым воином.','Ты $Gнаучился:научилась; приему "Рывок"?','Вернитесь к Амариэлю Верному Солнцу на Ристалище Серебряного турнира, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мастер стремительной атаки',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Опыт и практика сделают из тебя непобедимым воином.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gнаучился:научилась; приему "Рывок"?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Амариэлю Верному Солнцу на Ристалище Серебряного турнира, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13840,'ПОВТОРНОЕ ИСПОЛЬЗОВАНИЕ','"Куд... куд... куд... КУДАХ!$B$BКуд... куд... куд."$B$BКурица смотрит на вас одним глазом, затем начинает скрести когтями землю. Кажется, она пытается что-то написать, но вы не можете разобрать буквы. Может быть... С-А-Л-Ь-Д-Е-Н? Не дожидаясь расспросов, курица разворачивается и отправляется по своим куриным делам.','Найдите цыплячий корм и вернитесь к загадочной курице. Когда найдете курицу, покажите ей, как вы рады ее видеть (эмоция "/рад"), а потом накормите специальным цыплячьим кормом.','Вернитесь к курице.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','ПОВТОРНОЕ ИСПОЛЬЗОВАНИЕ',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','"Куд... куд... куд... КУДАХ!$B$BКуд... куд... куд."$B$BКурица смотрит на вас одним глазом, затем начинает скрести когтями землю. Кажется, она пытается что-то написать, но вы не можете разобрать буквы. Может быть... С-А-Л-Ь-Д-Е-Н? Не дожидаясь расспросов, курица разворачивается и отправляется по своим куриным делам.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите цыплячий корм и вернитесь к загадочной курице. Когда найдете курицу, покажите ей, как вы рады ее видеть (эмоция "/рад"), а потом накормите специальным цыплячьим кормом.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к курице.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (13841,'Искренние извинения','Глупцы!!!$B$BЭта безмозглая женщина, Драака, позволила себе попасть под влияние демона!$B$B<Гаррош внимательно смотрит на вас.>$B$BБоюсь, эта скверна не миновала и тебя...','Будем надеяться, что он проявит милосердие...','Драака') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Искренние извинения',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Глупцы!!!$B$BЭта безмозглая женщина, Драака, позволила себе попасть под влияние демона!$B$B<Гаррош внимательно смотрит на вас.>$B$BБоюсь, эта скверна не миновала и тебя...',`offerrewardtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Будем надеяться, что он проявит милосердие...',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Драака',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (13842,'Искупление','Поговорите с Дураном в шахте Расщепленного Дерева.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Искупление',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Дураном в шахте Расщепленного Дерева.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (13843,'Комплект для сборки Хламобота','Копаясь в базе данных панели управления прототипом, вы находите чертежи комплекта для сборки Хламобота. Имея достаточно навыков в инженерном деле, вы можете изучить их и самостоятельно производить комплекты для сборки.','Изучите данные панели управления прототипом в библиотеке Изобретателя.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Комплект для сборки Хламобота',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Копаясь в базе данных панели управления прототипом, вы находите чертежи комплекта для сборки Хламобота. Имея достаточно навыков в инженерном деле, вы можете изучить их и самостоятельно производить комплекты для сборки.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Изучите данные панели управления прототипом в библиотеке Изобретателя.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (13844,'Сокровища Алталакса','Прежде, чем ты снова ринешься в бой, |3-6($c), выслушай то, что я хочу тебе сказать, ибо это важно. Мои разведчики докладывают, что Отрекшиеся исследуют разрушенную башню Алталакса на юге.$b$bПеред нападением в этом промозглом месте был расквартирован дивизион Совета Теней под командованием павшего высокорожденного Атрикуса Нарассина. Нарассин давно покоится в земле, но если какие-то его бумаги уцелели, мы не должны допустить, чтобы они попали в руки врага. Добудь записи о его исследованиях и убей командира Отрекшихся, который привел нежить к этим руинам.','Найдите фолиант Нарассина среди руин Алталакса и убейте предводителя Отрекшихся Тигана Холловея.','Ну-ка, посмотрим, что тут у нас... Святая Элуна, его труды записаны как минимум на шести разных языках! А это что, кровь? У меня мурашки бегут по коже от одного вида этих бумаг... но у нас они будут в большей безопасности. Правда, нам потребуется много времени, чтобы расшифровать эти записи...$B$BА? Что? Награда? Вот, держи. Хорошую трепку ты задал этим падальщикам. А теперь – назад, в бой!','Нарассин больше не побеспокоит нас, но его труды не должны достаться в руки врагов. Страшно представить, как они смогут использовать плоды его темных изысканий.','Верните фолиант Матасу Дикому Лесу, находящемуся на Руинах Матистры на Темных берегах.','Отрекшиеся рыщут вблизи башни. Пусть не ждут пощады!','Тиган Холловей') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сокровища Алталакса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прежде, чем ты снова ринешься в бой, |3-6($c), выслушай то, что я хочу тебе сказать, ибо это важно. Мои разведчики докладывают, что Отрекшиеся исследуют разрушенную башню Алталакса на юге.$b$bПеред нападением в этом промозглом месте был расквартирован дивизион Совета Теней под командованием павшего высокорожденного Атрикуса Нарассина. Нарассин давно покоится в земле, но если какие-то его бумаги уцелели, мы не должны допустить, чтобы они попали в руки врага. Добудь записи о его исследованиях и убей командира Отрекшихся, который привел нежить к этим руинам.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите фолиант Нарассина среди руин Алталакса и убейте предводителя Отрекшихся Тигана Холловея.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну-ка, посмотрим, что тут у нас... Святая Элуна, его труды записаны как минимум на шести разных языках! А это что, кровь? У меня мурашки бегут по коже от одного вида этих бумаг... но у нас они будут в большей безопасности. Правда, нам потребуется много времени, чтобы расшифровать эти записи...$B$BА? Что? Награда? Вот, держи. Хорошую трепку ты задал этим падальщикам. А теперь – назад, в бой!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Нарассин больше не побеспокоит нас, но его труды не должны достаться в руки врагов. Страшно представить, как они смогут использовать плоды его темных изысканий.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Верните фолиант Матасу Дикому Лесу, находящемуся на Руинах Матистры на Темных берегах.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Отрекшиеся рыщут вблизи башни. Пусть не ждут пощады!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Тиган Холловей',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (13845,'Запечатанный фиал с ядом','Этот яд, похоже, смертельно опасен. Может быть, кто-нибудь в Даларане заинтересуется им.','Вернитесь к алхимику Синесре на Черный рынок, что в Даларане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Запечатанный фиал с ядом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этот яд, похоже, смертельно опасен. Может быть, кто-нибудь в Даларане заинтересуется им.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к алхимику Синесре на Черный рынок, что в Даларане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (13846,'Вклад в общее дело','Лучшие из лучших чемпионов ежедневно приходят к часовне, чтобы послушать речи исповедницы.$B$B$GВидел:Видела; бы ты, как это их вдохновляет! Они находят в себе силы продолжать сражение за дело Серебряного Авангарда и вносят посильный вклад в наше общее дело.$B$BМожет быть, и ты, $n, внесешь свою лепту? Пожертвуй немного золота на нужды Авангарда!','Поговорите с оруженосцем Арти и пожертвуйте 10 золотых на нужды Серебряного Авангарда.','Ты хочешь сделать пожертвование?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вклад в общее дело',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Лучшие из лучших чемпионов ежедневно приходят к часовне, чтобы послушать речи исповедницы.$B$B$GВидел:Видела; бы ты, как это их вдохновляет! Они находят в себе силы продолжать сражение за дело Серебряного Авангарда и вносят посильный вклад в наше общее дело.$B$BМожет быть, и ты, $n, внесешь свою лепту? Пожертвуй немного золота на нужды Авангарда!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с оруженосцем Арти и пожертвуйте 10 золотых на нужды Серебряного Авангарда.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты хочешь сделать пожертвование?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13847,'У вражеских врат','Несмотря на проводимый турнир, Серебряный Авангард продолжает подготовку к штурму цитадели Ледяной Короны.$B$BНа юго-западе Ледяной Короны, во Дворе Костей, отряд отважных рыцарей разбил лагерь прямо к югу от Корп\'ретара. Бери копье, седлай боевого скакуна Серебряного Рассвета и отправляйся на истребление подданных Короля-лича.$B$BПусть тебя не смущают костяные пехотинцы, $n – копыта твоего скакуна легко переломают их истлевшие кости.','Убейте 15 костяных пехотинцев, 10 костяных разведчиков и 3 костяных лейтенантов по заданию капитана Джозефа Холли из Павильона Серебряного союза на Ристалище Серебряного турнира.','Твоя доблесть на поле битвы показала рыцарям, что мы способны не только блистать на парадах, но и встретить врага лицом к лицу!','Служили вместе с крестоносцами при Дворе Костей?','Вернитесь к капитану Джозефу Холли на Ристалище Серебряного турнира в Ледяную Корону.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','У вражеских врат',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Несмотря на проводимый турнир, Серебряный Авангард продолжает подготовку к штурму цитадели Ледяной Короны.$B$BНа юго-западе Ледяной Короны, во Дворе Костей, отряд отважных рыцарей разбил лагерь прямо к югу от Корп\'ретара. Бери копье, седлай боевого скакуна Серебряного Рассвета и отправляйся на истребление подданных Короля-лича.$B$BПусть тебя не смущают костяные пехотинцы, $n – копыта твоего скакуна легко переломают их истлевшие кости.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 15 костяных пехотинцев, 10 костяных разведчиков и 3 костяных лейтенантов по заданию капитана Джозефа Холли из Павильона Серебряного союза на Ристалище Серебряного турнира.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Твоя доблесть на поле битвы показала рыцарям, что мы способны не только блистать на парадах, но и встретить врага лицом к лицу!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Служили вместе с крестоносцами при Дворе Костей?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Джозефу Холли на Ристалище Серебряного турнира в Ледяную Корону.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (13848,'Плохие новости','<Командир Мрачный Клык с огорчением изучает принесенный вами отчет.>$B$BПлохие новости...$B$BНадеюсь, добрые духи позаботятся о выживших, пока мы прокладываем путь к Заставе Расщепленного Дерева.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Плохие новости',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Командир Мрачный Клык с огорчением изучает принесенный вами отчет.>$B$BПлохие новости...$B$BНадеюсь, добрые духи позаботятся о выживших, пока мы прокладываем путь к Заставе Расщепленного Дерева.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13849,'Астранаар в огне!','$C, в Астранааре пожар!$B$BБыстрее, хватай ведро с водой и туши огонь, пока еще можно что-то спасти!','Потушите 15 пожаров.','Вернитесь к часовому Тенисил в Астранаар, что в Ясеневом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Астранаар в огне!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$C, в Астранааре пожар!$B$BБыстрее, хватай ведро с водой и туши огонь, пока еще можно что-то спасти!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Потушите 15 пожаров.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к часовому Тенисил в Астранаар, что в Ясеневом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13850,'Иммунитет к яду','Хочешь купить ядошкурого равазавра? Тогда у меня для тебя плохие новости.$B$BЭти зверюшки ядовиты от кончика носа до кончика хвоста: ядовитая кровь, ядовитая слюна, ядовитая шкура. Заберись на такого, и через несколько часов ты труп.$B$BЧтобы этого не произошло, нужно выработать иммунитет к их яду, а это – долгий, очень долгий процесс... нужно, чтобы кровь равазавра попала на твою кожу бесчисленное количество раз. Если хочешь попробовать – равазавры во множестве обитают на севере Топей, это к северо-западу отсюда.','Все еще не застрахован, да? Сдаваться. Это занимает слишком много времени!','Вернитесь к Мор\'веку в Топи, что в Кратере Ун\'Горо.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Иммунитет к яду',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хочешь купить ядошкурого равазавра? Тогда у меня для тебя плохие новости.$B$BЭти зверюшки ядовиты от кончика носа до кончика хвоста: ядовитая кровь, ядовитая слюна, ядовитая шкура. Заберись на такого, и через несколько часов ты труп.$B$BЧтобы этого не произошло, нужно выработать иммунитет к их яду, а это – долгий, очень долгий процесс... нужно, чтобы кровь равазавра попала на твою кожу бесчисленное количество раз. Если хочешь попробовать – равазавры во множестве обитают на севере Топей, это к северо-западу отсюда.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Все еще не застрахован, да? Сдаваться. Это занимает слишком много времени!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мор\'веку в Топи, что в Кратере Ун\'Горо.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13851,'У вражеских врат','Несмотря на проводимый турнир, Серебряный Авангард продолжает подготовку к штурму цитадели Ледяной Короны.$B$BНа юго-западе Ледяной Короны, во Дворе Костей, отряд отважных рыцарей разбил лагерь прямо к югу от Корп\'ретар. Бери копье, седлай боевого скакуна Серебряного Рассвета и отправляйся на истребление подданных Короля-лича.$B$BПусть тебя не смущают костяные пехотинцы, $n – копыта твоего скакуна легко переломают их истлевшие кости.','Убейте 15 костяных пехотинцев, 10 костяных разведчиков и 3 костяных лейтенантов по заданию Клары Взубногой из Павильона Серебряного союза на Ристалище Серебряного турнира.','Твоя доблесть на поле битвы показала рыцарям, что мы достойные союзники.','Служили вместе с крестоносцами при Дворе Костей?','Вернитесь к Кларе Взубногой на Ристалище Серебряного турнира в Ледяную Корону.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','У вражеских врат',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Несмотря на проводимый турнир, Серебряный Авангард продолжает подготовку к штурму цитадели Ледяной Короны.$B$BНа юго-западе Ледяной Короны, во Дворе Костей, отряд отважных рыцарей разбил лагерь прямо к югу от Корп\'ретар. Бери копье, седлай боевого скакуна Серебряного Рассвета и отправляйся на истребление подданных Короля-лича.$B$BПусть тебя не смущают костяные пехотинцы, $n – копыта твоего скакуна легко переломают их истлевшие кости.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 15 костяных пехотинцев, 10 костяных разведчиков и 3 костяных лейтенантов по заданию Клары Взубногой из Павильона Серебряного союза на Ристалище Серебряного турнира.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Твоя доблесть на поле битвы показала рыцарям, что мы достойные союзники.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Служили вместе с крестоносцами при Дворе Костей?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кларе Взубногой на Ристалище Серебряного турнира в Ледяную Корону.',`completedtext_loc8`);
