INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13860,'У вражеских врат','Несмотря на проводимый турнир, Серебряный Авангард продолжает подготовку к штурму цитадели Ледяной Короны.$B$BНа юго-западе Ледяной Короны, во Дворе Костей, отряд отважных рыцарей разбил лагерь прямо к югу от Корп\'ретара. Бери копье, седлай боевого скакуна Серебряного Рассвета и отправляйся на истребление подданных Короля-лича.$B$BПусть тебя не смущают костяные пехотинцы, $n – копыта твоего скакуна легко переломают их истлевшие кости.','Убейте 15 костяных пехотинцев, 10 костяных разведчиков и 3 костяных лейтенантов по заданию дрессировщика Дреча из Павильона Похитителей Солнца на Ристалище Серебряного турнира.','Рыцари Серебряного Авангарда убедились в нашей доблести и теперь знают, что мы будем стоять до конца.','Служили вместе с крестоносцами при Дворе Костей?','Вернитесь к дрессировщику Дречу на Ристалище Серебряного турнира, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','У вражеских врат',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Несмотря на проводимый турнир, Серебряный Авангард продолжает подготовку к штурму цитадели Ледяной Короны.$B$BНа юго-западе Ледяной Короны, во Дворе Костей, отряд отважных рыцарей разбил лагерь прямо к югу от Корп\'ретара. Бери копье, седлай боевого скакуна Серебряного Рассвета и отправляйся на истребление подданных Короля-лича.$B$BПусть тебя не смущают костяные пехотинцы, $n – копыта твоего скакуна легко переломают их истлевшие кости.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 15 костяных пехотинцев, 10 костяных разведчиков и 3 костяных лейтенантов по заданию дрессировщика Дреча из Павильона Похитителей Солнца на Ристалище Серебряного турнира.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Рыцари Серебряного Авангарда убедились в нашей доблести и теперь знают, что мы будем стоять до конца.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Служили вместе с крестоносцами при Дворе Костей?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к дрессировщику Дречу на Ристалище Серебряного турнира, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13861,'Пока часть рыцарей тренируется перед турниром, остальные готовятся к атаке на крепость врага – цитадель Ледяной Короны.$B$BНа юго-западе Ледяной Короны, во Дворе Костей, отряд отважных рыцарей разбил лагерь прямо к югу от Корп\'ретар. Бери копье, седлай турнирного скакуна и отправляйся на истребление подданных Короля-лича.$B$BПусть тебя не смущают костяные пехотинцы, $n – копыта твоего скакуна легко переломают их истлевшие кости.','По заданию Эдрика Чистого из Серебряного павильона на Ристалище Серебряного турнира убейте 3 костяных командиров.','Сражались ли вы с врагом при Дворе Костей?','Вернитесь к Эдрику Чистому на Ристалище Серебряного турнира в Ледяной Короне.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пока часть рыцарей тренируется перед турниром, остальные готовятся к атаке на крепость врага – цитадель Ледяной Короны.$B$BНа юго-западе Ледяной Короны, во Дворе Костей, отряд отважных рыцарей разбил лагерь прямо к югу от Корп\'ретар. Бери копье, седлай турнирного скакуна и отправляйся на истребление подданных Короля-лича.$B$BПусть тебя не смущают костяные пехотинцы, $n – копыта твоего скакуна легко переломают их истлевшие кости.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По заданию Эдрика Чистого из Серебряного павильона на Ристалище Серебряного турнира убейте 3 костяных командиров.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Сражались ли вы с врагом при Дворе Костей?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Эдрику Чистому на Ристалище Серебряного турнира в Ледяной Короне.',`completedtext_loc8`);
