INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (13865,'Мокрая работенка','Слушай внимательно, |3-6($c).$b$bВ этих краях эльфами командуют трое, и внимание их сосредоточено на лесопилке. Убить их – значит посеять панику и беспорядок в рядах эльфов, и, возможно, тогда мы сможем выполнить свою задачу здесь.$b$bБудешь на месте, учти, что чем больше разведчиков ты сможешь уничтожить, тем ближе окажется наша цель.','Доложите о выполнении задания Крокку. Его можно найти у тлеющей жаровни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мокрая работенка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слушай внимательно, |3-6($c).$b$bВ этих краях эльфами командуют трое, и внимание их сосредоточено на лесопилке. Убить их – значит посеять панику и беспорядок в рядах эльфов, и, возможно, тогда мы сможем выполнить свою задачу здесь.$b$bБудешь на месте, учти, что чем больше разведчиков ты сможешь уничтожить, тем ближе окажется наша цель.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доложите о выполнении задания Крокку. Его можно найти у тлеющей жаровни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (13866,'К заставе!','Леса позади тебя только кажутся спокойными – на самом деле наши враги притаились за каждым деревом. Я видел много тел орков, подстреленных в спину – они даже не успели обнажить оружие.$b$bТам, за границей, пролегают опасные земли, но смекалка и острые клинки помогут нам выжить на заставе Мор\'шан. Именно оттуда Кадрак планирует начать нападение – он всегда предпочитал действие разговорам. С этого момента вы с ним будете действовать заодно.$b$bОкликни меня, когда будешь $Gготов:готова; лететь, и я тебе помогу.','Поговорите с Кулгом Кровобрызгом на границе Ясеневого леса и Азшары, и он оправит вас на заставу Мор\'шан. По прибытии немедленно разыщите Кадрака.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','К заставе!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Леса позади тебя только кажутся спокойными – на самом деле наши враги притаились за каждым деревом. Я видел много тел орков, подстреленных в спину – они даже не успели обнажить оружие.$b$bТам, за границей, пролегают опасные земли, но смекалка и острые клинки помогут нам выжить на заставе Мор\'шан. Именно оттуда Кадрак планирует начать нападение – он всегда предпочитал действие разговорам. С этого момента вы с ним будете действовать заодно.$b$bОкликни меня, когда будешь $Gготов:готова; лететь, и я тебе помогу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Кулгом Кровобрызгом на границе Ясеневого леса и Азшары, и он оправит вас на заставу Мор\'шан. По прибытии немедленно разыщите Кадрака.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13867,'Устранение угрозы фурболгов','Если идти прямо на север Астранаара, можно встретить фурболгов из племени Колючий Мех. Мои разведчики докладывают, что за прошедшие несколько месяцев их численность значительно выросла. Если их окажется слишком много, они могут попытаться собрать армию и атаковать сам Астранаар!$B$BОтправляйся в деревню Колючего Меха и убей как можно больше этих существ.$B$BЯ же останусь в Астранааре и буду ждать от тебя известий. Да пребудет с тобой Элуна, |3-6($c).','Убейте 15 фурболгов в деревне Колючего Меха.','Вернитесь к Раэне Волкопас в Астранаар, что в Ясеневом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Устранение угрозы фурболгов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если идти прямо на север Астранаара, можно встретить фурболгов из племени Колючий Мех. Мои разведчики докладывают, что за прошедшие несколько месяцев их численность значительно выросла. Если их окажется слишком много, они могут попытаться собрать армию и атаковать сам Астранаар!$B$BОтправляйся в деревню Колючего Меха и убей как можно больше этих существ.$B$BЯ же останусь в Астранааре и буду ждать от тебя известий. Да пребудет с тобой Элуна, |3-6($c).',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 15 фурболгов в деревне Колючего Меха.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Раэне Волкопас в Астранаар, что в Ясеневом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13868,'Искажающее влияние?','Обыскивая сумки мертвого фурболга, вы находите маленький оберег, явно изготовленный руками троллей.$B$BПодняв его с земли, вы внезапно ощущаете что-то странное в этом куске дерева – как будто его окружает некая темная аура проклятья$B$BОсторожно завернув его в обрывок какой-то ткани, вы кладете оберег в сумку и напоминаете себе непременно показать его Раэне Волкопас при следующем визите в Астранаар.','Отнесите оберег троллей Раэне Волкопас в Астранаар, что в Ясеневом лесу.','Оберег троллей? Что он делал в руках фурболга?$B$BТы прав, здесь чувствуется след порчи...$B$BНо я знаю, кто может помочь нам разобраться.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Искажающее влияние?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Обыскивая сумки мертвого фурболга, вы находите маленький оберег, явно изготовленный руками троллей.$B$BПодняв его с земли, вы внезапно ощущаете что-то странное в этом куске дерева – как будто его окружает некая темная аура проклятья$B$BОсторожно завернув его в обрывок какой-то ткани, вы кладете оберег в сумку и напоминаете себе непременно показать его Раэне Волкопас при следующем визите в Астранаар.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите оберег троллей Раэне Волкопас в Астранаар, что в Ясеневом лесу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Оберег троллей? Что он делал в руках фурболга?$B$BТы прав, здесь чувствуется след порчи...$B$BНо я знаю, кто может помочь нам разобраться.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13869,'Вернуть останки','То, что сатиры сделали с этим деревьями, ужасно, но это не идет ни в какое сравнение с массовыми убийствами, которые учинили орки!$B$B<Великий Древний весь сотрясается от ярости, осыпая вас листьями.>$B$B$r, я прошу тебя отправиться по дороге, ведущей на лесопилку, и спасти хотя бы остатки этих деревьев, древней и энтов, погибших от руки высокомерной Орды.','Раздобудьте 10 штабелей древесины клана Песни Войны.','Вернитесь к Кривокрону на лесопилку Песни Войны, что в Ясеневом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вернуть останки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','То, что сатиры сделали с этим деревьями, ужасно, но это не идет ни в какое сравнение с массовыми убийствами, которые учинили орки!$B$B<Великий Древний весь сотрясается от ярости, осыпая вас листьями.>$B$B$r, я прошу тебя отправиться по дороге, ведущей на лесопилку, и спасти хотя бы остатки этих деревьев, древней и энтов, погибших от руки высокомерной Орды.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте 10 штабелей древесины клана Песни Войны.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кривокрону на лесопилку Песни Войны, что в Ясеневом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13870,'Как нельзя лучше','Ну что, |3-6($c), все складывается как нельзя лучше.$b$bПока эльфы еще не оправились от твоей последней вылазки – самое время совершить набег на лесопилку!$b$bНайди способ проникнуть туда и поговори с надзирателем Гортаком. Он расскажет тебе, как лучше всего сопроводить дипломата в безопасное место.$b$bУдачи!','Крокк просит вас проникнуть на лесопилку Песни Войны и поговорить с надзирателем Гортаком.','<Гортак огорченно вздыхает.>$B$BАх, где же ты был час назад... В наш лагерь прокрался ночной эльф-убийца и напал на дипломата. К сожалению, раны оказались смертельными.$B$BМы до сих пор не знаем, как наемнику удалось проскользнуть незамеченным.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Как нельзя лучше',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну что, |3-6($c), все складывается как нельзя лучше.$b$bПока эльфы еще не оправились от твоей последней вылазки – самое время совершить набег на лесопилку!$b$bНайди способ проникнуть туда и поговори с надзирателем Гортаком. Он расскажет тебе, как лучше всего сопроводить дипломата в безопасное место.$b$bУдачи!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Крокк просит вас проникнуть на лесопилку Песни Войны и поговорить с надзирателем Гортаком.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Гортак огорченно вздыхает.>$B$BАх, где же ты был час назад... В наш лагерь прокрался ночной эльф-убийца и напал на дипломата. К сожалению, раны оказались смертельными.$B$BМы до сих пор не знаем, как наемнику удалось проскользнуть незамеченным.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (13871,'Безопасность превыше всего!','Можно подумать, мне тут нечем заняться!$b$bНе так уж легко сохранять порядок в этом месте, когда со всех сторон атакуют эльфы и дренеи. А тут еще какой-то убийца шныряет вокруг лагеря, и уже перерезал горло чрезвычайно важному послу... причем во время моего дежурства!$b$bЭто зашло слишком далеко, |3-6($c). Ищи по всему лагерю, пока не найдешь наемника, и отомсти за погибшего дипломата.$b$bКогда я предстану перед Адским Криком, я хочу хотя бы предъявить ему голову убийцы в качестве оправдания.','Надзиратель Гортак просит вас принести ему голову калдорайской убийцы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Безопасность превыше всего!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Можно подумать, мне тут нечем заняться!$b$bНе так уж легко сохранять порядок в этом месте, когда со всех сторон атакуют эльфы и дренеи. А тут еще какой-то убийца шныряет вокруг лагеря, и уже перерезал горло чрезвычайно важному послу... причем во время моего дежурства!$b$bЭто зашло слишком далеко, |3-6($c). Ищи по всему лагерю, пока не найдешь наемника, и отомсти за погибшего дипломата.$b$bКогда я предстану перед Адским Криком, я хочу хотя бы предъявить ему голову убийцы в качестве оправдания.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Надзиратель Гортак просит вас принести ему голову калдорайской убийцы.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (13872,'Мудрость воргена','Этот парень напротив меня известен как пилигрим Гефест. Он ворген.$B$BНе так давно он вместе с сестрой прибыл в Астранаар в поисках убежища. Насколько мне удалось понять, он хочет помочь Служителям Земли справиться с последствиями Катаклизма. Его сестра обладает еще более могущественными способностями. Ее отправили на восток усмирять вулкан.$B$BВозможно, этот ворген сможет нам помочь. Отнеси ему оберег и спроси, что он о нем думает.','Отнесите оберег троллей пилигриму Гефесту в Астранаар, что в Ясеневом лесу.','<Ворген смотрит на резную деревяшку, лежащую у вас на ладони, и протягивает к ней руку.>','<Ворген безразлично смотрит на то, как вы приближаетесь к нему.>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мудрость воргена',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этот парень напротив меня известен как пилигрим Гефест. Он ворген.$B$BНе так давно он вместе с сестрой прибыл в Астранаар в поисках убежища. Насколько мне удалось понять, он хочет помочь Служителям Земли справиться с последствиями Катаклизма. Его сестра обладает еще более могущественными способностями. Ее отправили на восток усмирять вулкан.$B$BВозможно, этот ворген сможет нам помочь. Отнеси ему оберег и спроси, что он о нем думает.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите оберег троллей пилигриму Гефесту в Астранаар, что в Ясеневом лесу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Ворген смотрит на резную деревяшку, лежащую у вас на ладони, и протягивает к ней руку.>',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Ворген безразлично смотрит на то, как вы приближаетесь к нему.>',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13873,'Последняя просьба Шилы','Я... не могу поверить, что она погибла. Все случилось так быстро...$b$bПолагаю, я должен поблагодарить тебя за то, что ты $gотомстил:отомстила; за смерть госпожи. Весь Луносвет в долгу перед тобой.$b$bВ безграничной мудрости своей повелительница предвидела свою смерть. Она оставила это послание и попросила доставить его по назначению, если с ней что-то случится.$b$bМы должны были присоединиться к оргриммарскому эскорту на перекрестке, что к северу от этого места. Прошу тебя, |3-6($r), встреть их вместо нас и убедись, что письмо попало в нужные руки.','Страж Менерин просит вас отнести запечатанное послание Шилы стражу Гуртару.','<Страж Гуртар внимательно выслушивает ваше сообщение о смерти Шилы.>$B$BЯ лично доставлю это известие Адскому Крику. Тебе же придется заняться другим поручением...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Последняя просьба Шилы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я... не могу поверить, что она погибла. Все случилось так быстро...$b$bПолагаю, я должен поблагодарить тебя за то, что ты $gотомстил:отомстила; за смерть госпожи. Весь Луносвет в долгу перед тобой.$b$bВ безграничной мудрости своей повелительница предвидела свою смерть. Она оставила это послание и попросила доставить его по назначению, если с ней что-то случится.$b$bМы должны были присоединиться к оргриммарскому эскорту на перекрестке, что к северу от этого места. Прошу тебя, |3-6($r), встреть их вместо нас и убедись, что письмо попало в нужные руки.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Страж Менерин просит вас отнести запечатанное послание Шилы стражу Гуртару.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Страж Гуртар внимательно выслушивает ваше сообщение о смерти Шилы.>$B$BЯ лично доставлю это известие Адскому Крику. Тебе же придется заняться другим поручением...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13874,'Жизнь без оберега','Фурболги опять решили наложить лапы на то, что им не принадлежит.$B$B<Гефест задумчиво крутит оберег в руках, после чего откладывает в сторону.>$B$BНа этой деревяшке есть символ, который накладывает порчу на всех, кто не принадлежит расе троллей. Как я понимаю, фурболги и раньше этим занимались. Некоторые из них ничему не учатся.$B$BНе сомневаюсь, они хранят обереги в Берлоге Колючего Меха. Она находится прямо над их деревней на севере.','Найдите 8 оберегов троллей.','Думаешь, ты собрал все тролльи обереги в Берлоге Колючего Меха? Лучше проверь еще раз.$B$BЕсли там остался хотя бы один амулет, племя Колючего Меха продолжит нападать на нас, повинуясь его нечестивой силе.','Вернитесь к пилигриму Гефесту в Астранаар, что в Ясеневом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жизнь без оберега',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Фурболги опять решили наложить лапы на то, что им не принадлежит.$B$B<Гефест задумчиво крутит оберег в руках, после чего откладывает в сторону.>$B$BНа этой деревяшке есть символ, который накладывает порчу на всех, кто не принадлежит расе троллей. Как я понимаю, фурболги и раньше этим занимались. Некоторые из них ничему не учатся.$B$BНе сомневаюсь, они хранят обереги в Берлоге Колючего Меха. Она находится прямо над их деревней на севере.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите 8 оберегов троллей.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Думаешь, ты собрал все тролльи обереги в Берлоге Колючего Меха? Лучше проверь еще раз.$B$BЕсли там остался хотя бы один амулет, племя Колючего Меха продолжит нападать на нас, повинуясь его нечестивой силе.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к пилигриму Гефесту в Астранаар, что в Ясеневом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (13875,'Просьба Гуртара','$c, у меня есть к тебе просьба исключительно личного характера.$b$bМного лун сменилось с тех пор, как я в последний раз видел мою возлюбленную, Драаку, и много еще сменится, пока мы сможем снова быть вместе. Боюсь, что чувства ее со временем угаснут.$b$bЭтот венок очень дорог нам обоим, как и кровавые чашечки – цветы, что растут только в этих местах.$b$bПожалуйста, собери их, вплети в венок и подари его от меня Драаке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Просьба Гуртара',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$c, у меня есть к тебе просьба исключительно личного характера.$b$bМного лун сменилось с тех пор, как я в последний раз видел мою возлюбленную, Драаку, и много еще сменится, пока мы сможем снова быть вместе. Боюсь, что чувства ее со временем угаснут.$b$bЭтот венок очень дорог нам обоим, как и кровавые чашечки – цветы, что растут только в этих местах.$b$bПожалуйста, собери их, вплети в венок и подари его от меня Драаке.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (13876,'Он зашел слишком далеко','Да, |3-6($r), я говорю на твоем языке.$B$BМы, фурболги, уже сталкивались с такого вида порчей. Не так давно наш вождь хитростью завладел идолом Ремула. Эта оскверненная демонами святыня околдовала все племя, и если бы не друид по имени Бролл Медвежья Шкура, нам бы не видать спасения.$B$BНо на этот раз мы ничего не крали. Тролли Зорам\'гара сами подарили нам эти обереги в знак дружбы. Видимо, дружба эта оказалась смертельной.$B$BНаш вождь, Дал Жилотяг, зашел слишком далеко. Войди в берлогу и забери его обереги.','Найдите коллекцию Жилотяга.','Вернитесь к Виру Темному Носу ко входу в Берлогу Колючего Меха, что в Ясеневом лесу.','Добудь коллекцию Жилотяга.','Дал Жилотяг') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Он зашел слишком далеко',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Да, |3-6($r), я говорю на твоем языке.$B$BМы, фурболги, уже сталкивались с такого вида порчей. Не так давно наш вождь хитростью завладел идолом Ремула. Эта оскверненная демонами святыня околдовала все племя, и если бы не друид по имени Бролл Медвежья Шкура, нам бы не видать спасения.$B$BНо на этот раз мы ничего не крали. Тролли Зорам\'гара сами подарили нам эти обереги в знак дружбы. Видимо, дружба эта оказалась смертельной.$B$BНаш вождь, Дал Жилотяг, зашел слишком далеко. Войди в берлогу и забери его обереги.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите коллекцию Жилотяга.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Виру Темному Носу ко входу в Берлогу Колючего Меха, что в Ясеневом лесу.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Добудь коллекцию Жилотяга.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Дал Жилотяг',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13877,'По течению','<Ворген окидывает вас оценивающим взглядом, и только после этого переходит к своей просьбе.>$B$BЕсли мы не будем действовать быстро, вулкан поглотит весь Ясеневый лес. Поверь мне на слово, его извержение не было вызвано естественными причинами.$B$BМоя сестра Сабина, могущественный шаман Служителей Земли, отправилась на восток, к Громовой вершине, где течет поток лавы. Она пытается объединить силы прочих стихий, чтобы противостоять повелителю пламени, который стоит за этими чудовищными разрушениями. $B$B$n, я прошу тебя – найди ее и предложи свою помощь.','Поговорите с Сабиной на южной границе лавового потока Громовой вершины, что в Ясеневом лесу.','Должно быть, тебя послал мой брат, а он бы не отправил с поручением того, в ком не уверен на сто процентов.$B$BВо имя всего святого, надеюсь, он в тебе не ошибся.$B$BЭти элементали – мои друзья. Выслушай их и сделай все, о чем они тебя попросят. Только так можно предотвратить гибель Ясеневого леса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','По течению',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Ворген окидывает вас оценивающим взглядом, и только после этого переходит к своей просьбе.>$B$BЕсли мы не будем действовать быстро, вулкан поглотит весь Ясеневый лес. Поверь мне на слово, его извержение не было вызвано естественными причинами.$B$BМоя сестра Сабина, могущественный шаман Служителей Земли, отправилась на восток, к Громовой вершине, где течет поток лавы. Она пытается объединить силы прочих стихий, чтобы противостоять повелителю пламени, который стоит за этими чудовищными разрушениями. $B$B$n, я прошу тебя – найди ее и предложи свою помощь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Сабиной на южной границе лавового потока Громовой вершины, что в Ясеневом лесу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Должно быть, тебя послал мой брат, а он бы не отправил с поручением того, в ком не уверен на сто процентов.$B$BВо имя всего святого, надеюсь, он в тебе не ошибся.$B$BЭти элементали – мои друзья. Выслушай их и сделай все, о чем они тебя попросят. Только так можно предотвратить гибель Ясеневого леса.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13878,'Сквозь огонь и воду','Помоги мне, |3-6($c)! Проклятые свинобразы подожгли стойла! Пожар! Пожар!$b$b<Дорак продолжает бессвязно выкрикивать что-то до тех пор, пока вам не удается успокоить его.>$b$bТам до сих пор остались волки. Кто-то должен спасти волчат!','Снимите цепи с волков в горящих стойлах.','Найдите Дорака к югу от Дальней заставы в Северных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сквозь огонь и воду',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Помоги мне, |3-6($c)! Проклятые свинобразы подожгли стойла! Пожар! Пожар!$b$b<Дорак продолжает бессвязно выкрикивать что-то до тех пор, пока вам не удается успокоить его.>$b$bТам до сих пор остались волки. Кто-то должен спасти волчат!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Снимите цепи с волков в горящих стойлах.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Найдите Дорака к югу от Дальней заставы в Северных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13879,'Громовая вершина','Приветствую тебя, |3-6($c).$b$bПрими мои поздравления с успешным нападением на Астранаар. Это унижение эльфы никогда не забудут.$b$bЖаль, что не только они препятствуют Орде захватить Ясеневый лес...$b$bЕще одна беда наступает с востока, и шаман Служителей Земли уже отправился туда, чтобы попытаться найти выход из кризиса. Разыщи его рядом с подножием вулкана Громовая вершина и окажи всю возможную помощь.','Бройк поручил вам найти Стиквада у Громовой вершины.','<Гоблин некоторое время пялится на вас, озадаченно моргая.>$B$BДухи шепнули мне, что помощь близится.$B$BПрости, но я ожидал, что они пошлют кого-нибудь более... сильного.$B$BЭти элементали – наши верные союзники. Выслушай их и сделай так, как они просят. Если мы потерпим неудачу, в Ясеневом лесу не останется ничего, за что стоило бы бороться.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Громовая вершина',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приветствую тебя, |3-6($c).$b$bПрими мои поздравления с успешным нападением на Астранаар. Это унижение эльфы никогда не забудут.$b$bЖаль, что не только они препятствуют Орде захватить Ясеневый лес...$b$bЕще одна беда наступает с востока, и шаман Служителей Земли уже отправился туда, чтобы попытаться найти выход из кризиса. Разыщи его рядом с подножием вулкана Громовая вершина и окажи всю возможную помощь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Бройк поручил вам найти Стиквада у Громовой вершины.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Гоблин некоторое время пялится на вас, озадаченно моргая.>$B$BДухи шепнули мне, что помощь близится.$B$BПрости, но я ожидал, что они пошлют кого-нибудь более... сильного.$B$BЭти элементали – наши верные союзники. Выслушай их и сделай так, как они просят. Если мы потерпим неудачу, в Ясеневом лесу не останется ничего, за что стоило бы бороться.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13880,'Горячая лава','<Огромный элементаль земли смотрит на вас сверху вниз.>$B$BЕсли мы хотим победить, необходимо остановить поток лавы. Я передам тебе частичку своей силы – воспользуйся ей, чтобы заполнить лавовые разломы!','С помощью дара земли заполните 8 лавовых разломов.','Готово?','Вернитесь к Недру на Громовую вершину, что в Ясеневом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Горячая лава',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Огромный элементаль земли смотрит на вас сверху вниз.>$B$BЕсли мы хотим победить, необходимо остановить поток лавы. Я передам тебе частичку своей силы – воспользуйся ей, чтобы заполнить лавовые разломы!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','С помощью дара земли заполните 8 лавовых разломов.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Готово?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Недру на Громовую вершину, что в Ясеневом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (13881,'Одержимые','Больше всего меня беспокоит судьба колючешерстных медведей, что обитают в этих оскверненных лесах. Недавно тяжелая болезнь поразила целое поселение к югу отсюда, и даже медвежье святилище не уберегло их от этой беды.$B$B$n, я не знаю, в чем причина этой болезни, но она пожирает их изнутри. Как бы ни было мучительно думать о том, что мы потеряем целое поколение медведей... надо положить конец их страданиям, чтобы земля вновь приняла их в свои объятья.$B$BНо что еще более важно – мы должны найти источник заразы! Возможно, это озеро, из которого все они пили...','Убейте 6 одержимых колючешерстных медведей и обследуйте озеро, из которого они пили.','Иссякший источник изучен','Вернитесь к Катрене Зимний Шорох в Рощу Древних, что на Темных берегах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Одержимые',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Больше всего меня беспокоит судьба колючешерстных медведей, что обитают в этих оскверненных лесах. Недавно тяжелая болезнь поразила целое поселение к югу отсюда, и даже медвежье святилище не уберегло их от этой беды.$B$B$n, я не знаю, в чем причина этой болезни, но она пожирает их изнутри. Как бы ни было мучительно думать о том, что мы потеряем целое поколение медведей... надо положить конец их страданиям, чтобы земля вновь приняла их в свои объятья.$B$BНо что еще более важно – мы должны найти источник заразы! Возможно, это озеро, из которого все они пили...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 6 одержимых колючешерстных медведей и обследуйте озеро, из которого они пили.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Иссякший источник изучен',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Катрене Зимний Шорох в Рощу Древних, что на Темных берегах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (13882,'Семена жизни','Отнесите семена Катрене Зимний Шорох в Рощу Древних, что на Темных берегах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Семена жизни',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите семена Катрене Зимний Шорох в Рощу Древних, что на Темных берегах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13883,'Обломки кораблей','Эти корабли строили спустя рукава – другого объяснения я не нахожу!$b$bНаверное, строители слишком торопились. Ты только посмотри – бронированная обшивка отваливается даже при непрямом попадании!$b$bДавай я тебе покажу, как это поправить – но сначала надо подобрать куски обшивки со дна моря.$b$bТы принеси обшивку, а я сделаю все остальное.','Соберите 10 кусков затонувшего металлолома.','Тебе удалось добыть обшивку?','Поговорите с Дагруном в Зорам\'гаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обломки кораблей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти корабли строили спустя рукава – другого объяснения я не нахожу!$b$bНаверное, строители слишком торопились. Ты только посмотри – бронированная обшивка отваливается даже при непрямом попадании!$b$bДавай я тебе покажу, как это поправить – но сначала надо подобрать куски обшивки со дна моря.$b$bТы принеси обшивку, а я сделаю все остальное.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 кусков затонувшего металлолома.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось добыть обшивку?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Дагруном в Зорам\'гаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13884,'Потушить огонь','Если мы хотим отвоевать территорию и положить конец уничтожению леса, сначала надо разобраться со слугами лорда Магматара.$B$BЯ имею в виду лавовых яростней, что купаются в магме на севере отсюда. Они питаются силой своей стихии, поэтому в одиночку тебе их не одолеть.$B$BОкликни меня, когда будешь $gготов:готова; – и я вызову тебе на помощь своего элементаля.','Убейте 10 лавовых яростеней. Обратитесь к Арктану, если вам потребуется еще один морозный волноход.','Вернитесь к Арктану на Громовую вершину, что в Ясеневом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Потушить огонь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если мы хотим отвоевать территорию и положить конец уничтожению леса, сначала надо разобраться со слугами лорда Магматара.$B$BЯ имею в виду лавовых яростней, что купаются в магме на севере отсюда. Они питаются силой своей стихии, поэтому в одиночку тебе их не одолеть.$B$BОкликни меня, когда будешь $gготов:готова; – и я вызову тебе на помощь своего элементаля.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 лавовых яростеней. Обратитесь к Арктану, если вам потребуется еще один морозный волноход.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Арктану на Громовую вершину, что в Ясеневом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (13885,'В защиту Темных берегов','Значит, животные теперь в безопасности! Спасибо, спасибо тебе!$B$BТеперь мы должны обратить наше внимание на источник заразы.','Вернитесь к Катрене Зимний Шорох в Рощу Древних, что на Темных берегах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В защиту Темных берегов',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Значит, животные теперь в безопасности! Спасибо, спасибо тебе!$B$BТеперь мы должны обратить наше внимание на источник заразы.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Катрене Зимний Шорох в Рощу Древних, что на Темных берегах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (13886,'Вихрь','Время пришло, $n. Вооружайся и приходи ко мне. Я вызову кружащийся вихрь, который в мгновение ока перенесет тебя по небу в Громовую вершину.$B$BНаправь силу Служителей Земли через элементаля, чтобы уничтожить лорда Магматара, и равновесие вновь будет восстановлено.','Убейте лорда Магматара с помощью Кружащегося вихря.','Вернитесь к страннице Сабине на Громовую вершину, что в Ясеневом лесу.','Сама сущность Громовой вершины противостоит тебе!','Лорд Магматар') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вихрь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Время пришло, $n. Вооружайся и приходи ко мне. Я вызову кружащийся вихрь, который в мгновение ока перенесет тебя по небу в Громовую вершину.$B$BНаправь силу Служителей Земли через элементаля, чтобы уничтожить лорда Магматара, и равновесие вновь будет восстановлено.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте лорда Магматара с помощью Кружащегося вихря.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к страннице Сабине на Громовую вершину, что в Ясеневом лесу.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Сама сущность Громовой вершины противостоит тебе!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Лорд Магматар',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13887,'Яйца ядошкурого равазавра','Теперь, когда у тебя выработался иммунитет к яду равазавра, ты сможешь прикасаться как к самим животным, так и к ядовитым яйцам. Эти ящеры – хищные зверюги, и их надо приручать с самого рождения.$B$BТак что, если ты хочешь оседлать равазавра, найди невылупившееся яйцо – их полно в гнездах по всей Топи. Ищи яйца со светлой скорлупой – именно из таких рождаются ядошкурые равазавры.$B$BЕсли принесешь мне несколько яиц, я разрешу тебе взять одно из них и научу, как приручить твоего зверька.','Принесите Мор\'веку 4 яйца ядошкурого равазавра. Он будет ждать вас на юго-востоке Топей.','Вернитесь к Мор\'веку в Топи, что в Кратере Ун\'Горо.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Яйца ядошкурого равазавра',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда у тебя выработался иммунитет к яду равазавра, ты сможешь прикасаться как к самим животным, так и к ядовитым яйцам. Эти ящеры – хищные зверюги, и их надо приручать с самого рождения.$B$BТак что, если ты хочешь оседлать равазавра, найди невылупившееся яйцо – их полно в гнездах по всей Топи. Ищи яйца со светлой скорлупой – именно из таких рождаются ядошкурые равазавры.$B$BЕсли принесешь мне несколько яиц, я разрешу тебе взять одно из них и научу, как приручить твоего зверька.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Мор\'веку 4 яйца ядошкурого равазавра. Он будет ждать вас на юго-востоке Топей.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мор\'веку в Топи, что в Кратере Ун\'Горо.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (13888,'Вихрь','Время пришло, $n. Вооружайся и приходи ко мне. Я вызову кружащийся вихрь, который в мгновение ока перенесет тебя по небу в Громовую вершину.$B$BНаправь силу Служителей Земли через элементаля, чтобы уничтожить лорда Магматара, и равновесие вновь будет восстановлено.','Убейте лорда Магматара с помощью Кружащегося вихря.','Вернитесь к Стикваду на Громовую вершину, что в Ясеневом лесу.','Сама сущность Громовой вершины противостоит тебе!','Лорд Магматар') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вихрь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Время пришло, $n. Вооружайся и приходи ко мне. Я вызову кружащийся вихрь, который в мгновение ока перенесет тебя по небу в Громовую вершину.$B$BНаправь силу Служителей Земли через элементаля, чтобы уничтожить лорда Магматара, и равновесие вновь будет восстановлено.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте лорда Магматара с помощью Кружащегося вихря.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Стикваду на Громовую вершину, что в Ясеневом лесу.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Сама сущность Громовой вершины противостоит тебе!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Лорд Магматар',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13889,'Бедный, голодный равазаврик','Ваш равазаврик хочет съесть 15 кусков свежего мяса динозавра.','Судя по довольному урчанию, равазаврик удовлетворен количеством мяса, но невозможно предугадать, когда он снова проголодается.','Детеныш поднимает голову и смотрит на вас.','Поговорите со своим равазавриком.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бедный, голодный равазаврик',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Ваш равазаврик хочет съесть 15 кусков свежего мяса динозавра.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Судя по довольному урчанию, равазаврик удовлетворен количеством мяса, но невозможно предугадать, когда он снова проголодается.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Детеныш поднимает голову и смотрит на вас.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите со своим равазавриком.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (13890,'Да будет вечное пламя','Это не просто какое-то мелкое поручение, |3-6($r)!$b$bКорабли продолжают прибывать, и если огонь на маяке так и не загорится, они потеряются в море – а то и совсем пропадут! Только тебе я могу доверить хранить путеводный свет.$b$bДля начала собери сальники гидр, обитающих в этих водах, затем принеси их в кузню и перетопи в масло.$b$bЕсли потом ты подольешь это масло в светильник маяка, у нас появится чуть больше времени, чтобы продержаться.','Командир Мрачный Клык из Зорам\'гара поручил вам залить жир гидры-тайнохлыста в огонь на маяке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Да будет вечное пламя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это не просто какое-то мелкое поручение, |3-6($r)!$b$bКорабли продолжают прибывать, и если огонь на маяке так и не загорится, они потеряются в море – а то и совсем пропадут! Только тебе я могу доверить хранить путеводный свет.$b$bДля начала собери сальники гидр, обитающих в этих водах, затем принеси их в кузню и перетопи в масло.$b$bЕсли потом ты подольешь это масло в светильник маяка, у нас появится чуть больше времени, чтобы продержаться.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Командир Мрачный Клык из Зорам\'гара поручил вам залить жир гидры-тайнохлыста в огонь на маяке.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (13891,'Поглотитель Темных берегов','Вернитесь к Катрене Зимний Шорох в Рощу Древних, что на Темных берегах.','Кто знает, что они могут найти…','Йо\'тал Поглотитель') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поглотитель Темных берегов',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Катрене Зимний Шорох в Рощу Древних, что на Темных берегах.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Кто знает, что они могут найти…',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Йо\'тал Поглотитель',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (13892,'Не оставляй следов','На юго-западе отсюда лежит тело существа, которое имеет какое-то отношение к почитаемым культом Сумеречного Молота древним богам.$B$BОн пал в битве в стародавние времена – чуть ли не от руки самих Титанов или одного из их созданий.$B$BНо сейчас к его телу проявляют особый интерес сектанты Сумеречного Молота, и я боюсь, что они затевают что-то недоброе.$B$BНадо выяснить, что они там делают и с какими целями. Вот, возьми эту статуэтку – ее магия укроет тебя от посторонних глаз, пока ты будешь собирать сведения.','Проникните к Мечу Властителя, воспользовавшись магией статуэтки пантеры, и проследите за служителями культа Сумеречного Молота.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Не оставляй следов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На юго-западе отсюда лежит тело существа, которое имеет какое-то отношение к почитаемым культом Сумеречного Молота древним богам.$B$BОн пал в битве в стародавние времена – чуть ли не от руки самих Титанов или одного из их созданий.$B$BНо сейчас к его телу проявляют особый интерес сектанты Сумеречного Молота, и я боюсь, что они затевают что-то недоброе.$B$BНадо выяснить, что они там делают и с какими целями. Вот, возьми эту статуэтку – ее магия укроет тебя от посторонних глаз, пока ты будешь собирать сведения.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проникните к Мечу Властителя, воспользовавшись магией статуэтки пантеры, и проследите за служителями культа Сумеречного Молота.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (13893,'Соггот и Кронн','Меч Властителя – это поле древней битвы, $n. Титаны отправили двадцать каменных великанов, чтобы одолеть Соггота, но уцелел из них только один.$B$BСкрижали гласят, что Кронн, самый большой из каменных великанов, позволил Согготу захватить его своими щупальцами... но лишь для того, чтобы добраться до головы чудовища, которую он расколол своим могучим мечом.$B$BХорошо, что Соггот погиб. У нас больше нет двадцати каменных великанов, чтобы остановить его.','Рассказ дворфа встревожил меня... и дал пищу для размышлений. Похоже, у нас не так уж много вариантов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Соггот и Кронн',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Меч Властителя – это поле древней битвы, $n. Титаны отправили двадцать каменных великанов, чтобы одолеть Соггота, но уцелел из них только один.$B$BСкрижали гласят, что Кронн, самый большой из каменных великанов, позволил Согготу захватить его своими щупальцами... но лишь для того, чтобы добраться до головы чудовища, которую он расколол своим могучим мечом.$B$BХорошо, что Соггот погиб. У нас больше нет двадцати каменных великанов, чтобы остановить его.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Рассказ дворфа встревожил меня... и дал пищу для размышлений. Похоже, у нас не так уж много вариантов.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (13894,'Знак убийства') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Знак убийства',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (13895,'Дремлющие древни','Хотя на нашей стороне нет двадцати каменных великанов, чтобы сокрушить врагов, наша древняя деревянная кожа прочнее любого гранита.$B$BПосмотри по сторонам, |3-6($r): здесь дремлют мои братья и сестры, но рог хранителя пробудит их в час битвы.$B$BНайди хранителя чащи Ароса возле моста, что на северо-востоке.$B$BОбъясни ему всю серьезность ситуации.','Тело Ароса еще не успело остыть – а значит, его убийцы где-то рядом...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дремлющие древни',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хотя на нашей стороне нет двадцати каменных великанов, чтобы сокрушить врагов, наша древняя деревянная кожа прочнее любого гранита.$B$BПосмотри по сторонам, |3-6($r): здесь дремлют мои братья и сестры, но рог хранителя пробудит их в час битвы.$B$BНайди хранителя чащи Ароса возле моста, что на северо-востоке.$B$BОбъясни ему всю серьезность ситуации.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тело Ароса еще не успело остыть – а значит, его убийцы где-то рядом...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13896,'Раскопанное знание','Послушай, $n, мы должны понять, с чем нам придется иметь дело.$B$BЯ знаю, кто может помочь разобраться в этом деле. На юго-западе отсюда, прямо под Мечом Властителя, я видела группу дворфов-археологов, которые раскапывали близлежащие руины.$B$BЧто-то мне подсказывает, что они могли наткнуться на некие знания, которые могут оказаться полезными.','Поговорите с археологом Гроффом на Раскопках Сомнамбулера.','Ну да, мы знаем кое-что о Согготе. Вопрос лишь в том, надо ли тебе это знать...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Раскопанное знание',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Послушай, $n, мы должны понять, с чем нам придется иметь дело.$B$BЯ знаю, кто может помочь разобраться в этом деле. На юго-западе отсюда, прямо под Мечом Властителя, я видела группу дворфов-археологов, которые раскапывали близлежащие руины.$B$BЧто-то мне подсказывает, что они могли наткнуться на некие знания, которые могут оказаться полезными.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с археологом Гроффом на Раскопках Сомнамбулера.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну да, мы знаем кое-что о Согготе. Вопрос лишь в том, надо ли тебе это знать...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (13897,'Битва за Темные берега','Убейте аватара Соггота у Меча Властителя.','Вернитесь к Балрену-медведю в Рощу Древних, что на Темных берегах.','Пусть он вернется туда, откуда пришел.','Аватара Соггота') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Битва за Темные берега',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте аватара Соггота у Меча Властителя.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Балрену-медведю в Рощу Древних, что на Темных берегах.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Пусть он вернется туда, откуда пришел.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Аватара Соггота',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (13898,'Волны против нас','Убийство хранителя чащи приравнивается к объявлению войны, $n, и наги еще поплатятся за это.$B$BНайди их логово внутри пещеры на острове Най\'вел, что на юго-западе отсюда.$B$BОни должны понять, что это им не сойдет с рук.','Молодец, Ддхилер. Наги стремятся уничтожить все живое на поверхности – так что пусть рука твоя не дрогнет, когда ты будешь изгонять их с наших земель обратно в пучины океана, из которого они вышли.','Вернитесь к Фелросу в Рощу Древних, что на Темных берегах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Волны против нас',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Убийство хранителя чащи приравнивается к объявлению войны, $n, и наги еще поплатятся за это.$B$BНайди их логово внутри пещеры на острове Най\'вел, что на юго-западе отсюда.$B$BОни должны понять, что это им не сойдет с рук.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Молодец, Ддхилер. Наги стремятся уничтожить все живое на поверхности – так что пусть рука твоя не дрогнет, когда ты будешь изгонять их с наших земель обратно в пучины океана, из которого они вышли.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фелросу в Рощу Древних, что на Темных берегах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`offerrewardtext_loc8`) VALUES (13899,'Если наги действительно решили связать свою судьбу с Сумеречным Молотом... да смилуется Элуна над их душами.$B$BОтправляйся в их логово на острове Назж\'вел и найди их предводителя, полководца Гневного Гребня.$B$BВозможно, рог древних все еще можно спасти.','У вождя не оказалось при себе рога. Возможно, он говорил вам правду?') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если наги действительно решили связать свою судьбу с Сумеречным Молотом... да смилуется Элуна над их душами.$B$BОтправляйся в их логово на острове Назж\'вел и найди их предводителя, полководца Гневного Гребня.$B$BВозможно, рог древних все еще можно спасти.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','У вождя не оказалось при себе рога. Возможно, он говорил вам правду?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (13900,'Дар Азшаре') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дар Азшаре',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (13902,'В наступление!','Если тебе доверяет сам Малфурион, то и мне негоже сомневаться. Но наши враги на юге значительно превосходят нас по численности.$B$BОднако там, где не поможет грубая сила, мы будем действовать умом и хитростью.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В наступление!',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Если тебе доверяет сам Малфурион, то и мне негоже сомневаться. Но наши враги на юге значительно превосходят нас по численности.$B$BОднако там, где не поможет грубая сила, мы будем действовать умом и хитростью.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13903,'Обед из улья Гориши','Ваш равазаврик проголодался. Принесите ему 10 кусков мяса силитида.','Ваш равазаврик дарит вам ослепительно клыкастую улыбку и сыто облизывается.','Детеныш поднимает голову и смотрит на вас.','Поговорите со своим равазавриком.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обед из улья Гориши',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Ваш равазаврик проголодался. Принесите ему 10 кусков мяса силитида.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ваш равазаврик дарит вам ослепительно клыкастую улыбку и сыто облизывается.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Детеныш поднимает голову и смотрит на вас.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите со своим равазавриком.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13904,'Всмятку, в мешочек или сырые?','Ваш равазаврик хочет, чтобы вы принесли ему 12 яиц силитида.','Ваш равазаврик довольно облизывается, расправившись с яйцами силитида. Вам показалось – или он слегка разочарован тем, что еда уже кончилась?','Детеныш смотрит на тебя.','Поговорите со своим равазавриком.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Всмятку, в мешочек или сырые?',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Ваш равазаврик хочет, чтобы вы принесли ему 12 яиц силитида.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ваш равазаврик довольно облизывается, расправившись с яйцами силитида. Вам показалось – или он слегка разочарован тем, что еда уже кончилась?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Детеныш смотрит на тебя.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите со своим равазавриком.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13905,'Перья опаляющего руха','Равазаврик внимательно смотрит на вас, словно сомневается, поймете ли вы его. Затем он рисует в грязи два пера и указывает когтем сначала на рисунок, а потом на свои локти и колени.$B$BОн, вроде бы, не голоден, что бы значили эти перья?$B$BНаверное, он хочет использовать их в качестве украшения, как другие ящеры. Самыми большими перьями могут похвастаться опаляющие рухи, которых легко найти вокруг останков огромных животных в западном Танарисе, к северо-востоку от Долины Кактусов.','Ваш равазаврик хочет, чтобы вы принесли ему 5 перьев опаляющего руха.','Равазаврик берет у вас перья и начинает рассматривать их, примеряя к повязкам на коленях.','Ваш равазаврик выжидательно смотрит на вас.','Вернитесь к Равазаврику.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Перья опаляющего руха',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Равазаврик внимательно смотрит на вас, словно сомневается, поймете ли вы его. Затем он рисует в грязи два пера и указывает когтем сначала на рисунок, а потом на свои локти и колени.$B$BОн, вроде бы, не голоден, что бы значили эти перья?$B$BНаверное, он хочет использовать их в качестве украшения, как другие ящеры. Самыми большими перьями могут похвастаться опаляющие рухи, которых легко найти вокруг останков огромных животных в западном Танарисе, к северо-востоку от Долины Кактусов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Ваш равазаврик хочет, чтобы вы принесли ему 5 перьев опаляющего руха.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Равазаврик берет у вас перья и начинает рассматривать их, примеряя к повязкам на коленях.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ваш равазаврик выжидательно смотрит на вас.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Равазаврику.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13906,'Они так быстро растут','При хорошем уходе равазавры быстро растут. По мере взросления молочные зубы заменятся коренными. Если ты будешь собирать все выпавшие зубы, то сможешь легко определить, когда он достаточно окрепнет для того, чтобы его можно было тренировать как верховое животное.$B$BОн сам даст тебе знать о том, что ему нужно, так что внимательно следи за ним и тщательно ухаживай за своим малышом. А когда все его молочные зубы выпадут, возвращайся ко мне со своим равазавром и всем, что нужно для его седла.','Ты хорошо заботился о своем ящере?','Вернитесь к Мор\'веку в Топи, что в Кратере Ун\'Горо.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Они так быстро растут',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','При хорошем уходе равазавры быстро растут. По мере взросления молочные зубы заменятся коренными. Если ты будешь собирать все выпавшие зубы, то сможешь легко определить, когда он достаточно окрепнет для того, чтобы его можно было тренировать как верховое животное.$B$BОн сам даст тебе знать о том, что ему нужно, так что внимательно следи за ним и тщательно ухаживай за своим малышом. А когда все его молочные зубы выпадут, возвращайся ко мне со своим равазавром и всем, что нужно для его седла.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты хорошо заботился о своем ящере?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мор\'веку в Топи, что в Кратере Ун\'Горо.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13907,'Зачистка руин','Великие бородачи из Стальгорна послали меня на раскопки Сомнамбулера, как только до них дошли слухи о случившемся несчастье. Да ты $gсам:сама; посмотри! Драгоценные артефакты в одночасье смыло в море, месяцы кропотливой работы воргену под хвост! $B$BМало того, волны разрушили поселения мурлоков, которые располагались вдоль берега. Скажешь, туда им и дорога? Ага, как же! Выжившие мурлоки пытаются пробраться под защиту руин и, если честно, наносят куда больше ущерба, чем стихии. Ну чего ты ждешь – сделай что-нибудь!','Убейте 10 оракулов племени Серой Мглы или беженцев из племени Серой Мглы возле Раскопок Сомнамбулера.','Вернитесь к археологу Гроффу на Раскопки Сомнамбулера на Темных берегах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зачистка руин',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Великие бородачи из Стальгорна послали меня на раскопки Сомнамбулера, как только до них дошли слухи о случившемся несчастье. Да ты $gсам:сама; посмотри! Драгоценные артефакты в одночасье смыло в море, месяцы кропотливой работы воргену под хвост! $B$BМало того, волны разрушили поселения мурлоков, которые располагались вдоль берега. Скажешь, туда им и дорога? Ага, как же! Выжившие мурлоки пытаются пробраться под защиту руин и, если честно, наносят куда больше ущерба, чем стихии. Ну чего ты ждешь – сделай что-нибудь!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 оракулов племени Серой Мглы или беженцев из племени Серой Мглы возле Раскопок Сомнамбулера.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к археологу Гроффу на Раскопки Сомнамбулера на Темных берегах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13908,'Приготовьтесь к поездке','Твой равазавр окреп, возмужал и сильно к тебе привязался. Пожалуй, вскоре ты сможешь ездить на нем – как только я доделаю седло и уздечку. Правда, их тоже придется укрепить, чтобы они выдержали воздействие яда равазавра.$B$BПринеси мне немного грубой кожи, рунической ткани и денег на остальные ингредиенты – и я тут же примусь за работу.','Принесите 20 кусков грубой кожи, 20 отрезов рунической ткани и 80 золотых монет Мор\'веку. Он ждет вас на юго-востоке Топей в Кратере Ун\'Горо','Вернитесь к Мор\'веку в Топи, что в Кратере Ун\'Горо.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приготовьтесь к поездке',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Твой равазавр окреп, возмужал и сильно к тебе привязался. Пожалуй, вскоре ты сможешь ездить на нем – как только я доделаю седло и уздечку. Правда, их тоже придется укрепить, чтобы они выдержали воздействие яда равазавра.$B$BПринеси мне немного грубой кожи, рунической ткани и денег на остальные ингредиенты – и я тут же примусь за работу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 20 кусков грубой кожи, 20 отрезов рунической ткани и 80 золотых монет Мор\'веку. Он ждет вас на юго-востоке Топей в Кратере Ун\'Горо',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мор\'веку в Топи, что в Кратере Ун\'Горо.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13909,'Обломки для бездомных','Мы сможем найти выход из ситуации. Надо только немного подумать... Мы, дворфы, издавна славились своей мудростью!$B$BЗначит, так: этим мурлокам нужен новый дом, верно? Мысли созидательно, $n! В буквальном смысле...$B$BВо время катаклизма на берег вынесло целую кучу всякого мусора, да и некоторые хижины все еще можно восстановить. Ну-ка, пробегись по побережью и собери все подходящие материалы для строительства. Поверь, для них особо стараться не придется!','Соберите 5 подлежащих восстановлению частей строений Серой Мглы на берегу и в воде возле Раскопок Сомнамбулера.','Принесите обломки археологу Гроффу на Раскопки Сомнамбулера на Темных берегах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обломки для бездомных',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы сможем найти выход из ситуации. Надо только немного подумать... Мы, дворфы, издавна славились своей мудростью!$B$BЗначит, так: этим мурлокам нужен новый дом, верно? Мысли созидательно, $n! В буквальном смысле...$B$BВо время катаклизма на берег вынесло целую кучу всякого мусора, да и некоторые хижины все еще можно восстановить. Ну-ка, пробегись по побережью и собери все подходящие материалы для строительства. Поверь, для них особо стараться не придется!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 5 подлежащих восстановлению частей строений Серой Мглы на берегу и в воде возле Раскопок Сомнамбулера.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите обломки археологу Гроффу на Раскопки Сомнамбулера на Темных берегах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13910,'Новый дом','Что нам стоит дом построить? Нарисовал – и будем жить! К западу от раскопок я установил на побережье наш флаг. Песок там достаточно плотный, и вполне подходит для постройки. Возьми мои инструменты и собранные материалы, и возведи этим несчастным тварям новые хижины.','Постройте лачугу для мурлоков в специальном месте на западе от раскопок рассеянного геолога.','Ха-ха, похоже, ты построила им целую деревню! И как, они купились? Отлично, отлично! Пойдем посмотрим, как воплощаются в жизнь мои планы. $B$B<Археолог хмурится, глядя как толпы мурлоков стекаются в хижину со всех сторон света.>$B$BЧто же я наделал?','Как там строятся новые бунгало на побережье?','Вернитесь к археологу Гроффу на Раскопки Сомнамбулера на Темных берегах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новый дом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что нам стоит дом построить? Нарисовал – и будем жить! К западу от раскопок я установил на побережье наш флаг. Песок там достаточно плотный, и вполне подходит для постройки. Возьми мои инструменты и собранные материалы, и возведи этим несчастным тварям новые хижины.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Постройте лачугу для мурлоков в специальном месте на западе от раскопок рассеянного геолога.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ха-ха, похоже, ты построила им целую деревню! И как, они купились? Отлично, отлично! Пойдем посмотрим, как воплощаются в жизнь мои планы. $B$B<Археолог хмурится, глядя как толпы мурлоков стекаются в хижину со всех сторон света.>$B$BЧто же я наделал?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как там строятся новые бунгало на побережье?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к археологу Гроффу на Раскопки Сомнамбулера на Темных берегах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (13911,'Рассеянный геолог','Как, ты говоришь, тебя зовут? $n? Мы знакомы? Если тебя прислали из Лиги, можешь передать им, что я никуда отсюда не уйду без моей находки! Она была уже у меня в руках... как вдруг раздались крики, и меня захлестнуло волной...$B$BСлушай, как там тебя зовут, я все записал в моем путевом журнале, и я знаю, где он сейчас лежит! Отыщем журнал – отыщем и мою находку! Или наоборот?... Иди за мной!','Покажите геологу Сомнамбулеру, где лежит его журнал, после чего поговорите с археологом Фердом на раскопках.','Геолог Сомнамбулер дошел до места.','Поговорите с археологом Фердом на Раскопках Сомнамбулера на Темных берегах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рассеянный геолог',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как, ты говоришь, тебя зовут? $n? Мы знакомы? Если тебя прислали из Лиги, можешь передать им, что я никуда отсюда не уйду без моей находки! Она была уже у меня в руках... как вдруг раздались крики, и меня захлестнуло волной...$B$BСлушай, как там тебя зовут, я все записал в моем путевом журнале, и я знаю, где он сейчас лежит! Отыщем журнал – отыщем и мою находку! Или наоборот?... Иди за мной!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Покажите геологу Сомнамбулеру, где лежит его журнал, после чего поговорите с археологом Фердом на раскопках.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Геолог Сомнамбулер дошел до места.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с археологом Фердом на Раскопках Сомнамбулера на Темных берегах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13912,'Тайны болота','Кто бы мог подумать, что вечно рассеянный Сомнамбулер – на самом деле непризнанный гений! Вот уж воистину тайна, скрытая под пылью веков. Но я не собираюсь преуменьшать заслуги старика. Смотри, что мне удалось обнаружить в его записях... нет, не то... это список покупок... нашел! Вот, смотри: на этой странице он пытается определить, который сейчас год с помощью Диска!$B$BПохоже, этот артефакт Титанов представляет собой некий диск с зашифрованными надписями. Незадолго до катастрофы мы со всеми предосторожностями выкопали его из-под земли, но не успели поднять на поверхность. Если он все еще лежит там, среди руин, пожалуйста, принеси его мне!','Найдите покрытый грязью древний диск среди ближайших руин.','Отнесите диск археологу Ферду на Прибрежные раскопки рассеянного археолога на Темных берегах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тайны болота',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кто бы мог подумать, что вечно рассеянный Сомнамбулер – на самом деле непризнанный гений! Вот уж воистину тайна, скрытая под пылью веков. Но я не собираюсь преуменьшать заслуги старика. Смотри, что мне удалось обнаружить в его записях... нет, не то... это список покупок... нашел! Вот, смотри: на этой странице он пытается определить, который сейчас год с помощью Диска!$B$BПохоже, этот артефакт Титанов представляет собой некий диск с зашифрованными надписями. Незадолго до катастрофы мы со всеми предосторожностями выкопали его из-под земли, но не успели поднять на поверхность. Если он все еще лежит там, среди руин, пожалуйста, принеси его мне!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите покрытый грязью древний диск среди ближайших руин.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите диск археологу Ферду на Прибрежные раскопки рассеянного археолога на Темных берегах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`endtext_loc8`) VALUES (13913,'Они забрали наших гномов!','Мы вызвали из Города Механиков команду гномов-подрывников, и она прибыла на прошлой неделе. Это было весьма кстати, потому что как раз в тот день на нас напала Орда, и мы потеряли много солдат. Большую часть подрывной команды тоже увели в плен. Теперь мы по уши в Орде, приют Серебряного Ветра потерян, а впридачу к нему около десятка гномов.$B$BПрошу, помоги нам, $n. Пойди на восток, в приют Серебряного Ветра, и поищи, не осталось ли там выживших гномов. Их увел огромный жестокий орк по имени Тундрак. Найдешь его – найдешь и наших гномов.','Буг и Минкс на свободе') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Они забрали наших гномов!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы вызвали из Города Механиков команду гномов-подрывников, и она прибыла на прошлой неделе. Это было весьма кстати, потому что как раз в тот день на нас напала Орда, и мы потеряли много солдат. Большую часть подрывной команды тоже увели в плен. Теперь мы по уши в Орде, приют Серебряного Ветра потерян, а впридачу к нему около десятка гномов.$B$BПрошу, помоги нам, $n. Пойди на восток, в приют Серебряного Ветра, и поищи, не осталось ли там выживших гномов. Их увел огромный жестокий орк по имени Тундрак. Найдешь его – найдешь и наших гномов.',`details_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Буг и Минкс на свободе',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13914,'Перья опаляющего руха','Равазаврик внимательно смотрит на вас, словно сомневается, поймете ли вы его. Затем он рисует в грязи два пера и показывает когтем сначала на рисунок, а потом на свои локти и колени.$B$BОн, вроде бы, не голоден, что бы значили эти перья?$B$BНаверное, он хочет использовать их в качестве украшения, как другие ящеры. Самыми большими перьями могут похвастаться опаляющие рухи, которых легко найти вокруг останков огромных животных в западном Танарисе, к северо-востоку от Долины Кактусов.','Ваш равазаврик хочет, чтобы вы принесли ему 5 перьев опаляющего руха.','Равазаврик берет у вас перья и начинает рассматривать их, примеряя к повязкам на коленях.','Ваш равазаврик выжидательно смотрит на вас.','Поговорите со своим равазавриком.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Перья опаляющего руха',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Равазаврик внимательно смотрит на вас, словно сомневается, поймете ли вы его. Затем он рисует в грязи два пера и показывает когтем сначала на рисунок, а потом на свои локти и колени.$B$BОн, вроде бы, не голоден, что бы значили эти перья?$B$BНаверное, он хочет использовать их в качестве украшения, как другие ящеры. Самыми большими перьями могут похвастаться опаляющие рухи, которых легко найти вокруг останков огромных животных в западном Танарисе, к северо-востоку от Долины Кактусов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Ваш равазаврик хочет, чтобы вы принесли ему 5 перьев опаляющего руха.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Равазаврик берет у вас перья и начинает рассматривать их, примеряя к повязкам на коленях.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ваш равазаврик выжидательно смотрит на вас.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите со своим равазавриком.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13915,'Бедный, голодный равазаврик','Равазаврик выжидательно смотрит на вас, после чего начинает опять что-то рисовать в грязи.$B$BКонечно, рисунки очень грубые, но вам все же удается разобрать очертания деметродонов, стегодонов и терродактилей. Когда ящер заканчивает рисунок, он ощеривает зубы и выразительно щелкает челюстью.$B$BНаверное, ваш равазаврик хочет свежего мяса. Убейте несколько любых деметродонов, стегодонов и терродактилей в Кратере Ун\'Горо и накормите голодного малыша.','Ваш равазаврик хочет съесть 15 кусков свежего мяса динозавра.','Судя по довольному урчанию, равазаврик удовлетворен количеством мяса, но невозможно предугадать, когда он снова проголодается.','Равазаврик облизывается и наклоняет голову набок.','Поговорите со своим равазавриком.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бедный, голодный равазаврик',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Равазаврик выжидательно смотрит на вас, после чего начинает опять что-то рисовать в грязи.$B$BКонечно, рисунки очень грубые, но вам все же удается разобрать очертания деметродонов, стегодонов и терродактилей. Когда ящер заканчивает рисунок, он ощеривает зубы и выразительно щелкает челюстью.$B$BНаверное, ваш равазаврик хочет свежего мяса. Убейте несколько любых деметродонов, стегодонов и терродактилей в Кратере Ун\'Горо и накормите голодного малыша.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Ваш равазаврик хочет съесть 15 кусков свежего мяса динозавра.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Судя по довольному урчанию, равазаврик удовлетворен количеством мяса, но невозможно предугадать, когда он снова проголодается.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Равазаврик облизывается и наклоняет голову набок.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите со своим равазавриком.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (13916,'Всмятку, в мешочек или сырые?','Равазаврик пытается привлечь ваше внимание, и вы слышите, как бурчит у него в животе. Он рисует в грязи несколько силитидов и добавляет внизу какие-то овалы, настойчиво указывая на них когтем.$B$BСомнений нет – ему нужны яйца силитидов! К счастью, вы знаете, где раздобыть лакомство для малыша – в Ядовитом улье, который находится в западном Танарисе, рядом с Кратером Ун\'Горо.','Ваш равазаврик хочет, чтобы вы принесли ему 12 яиц силитида.','Ваш равазаврик довольно облизывается, расправившись с яйцами силитида. Вам показалось – или он слегка разочарован тем, что еда уже кончилась?','Поговорите со своим равазавриком.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Всмятку, в мешочек или сырые?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Равазаврик пытается привлечь ваше внимание, и вы слышите, как бурчит у него в животе. Он рисует в грязи несколько силитидов и добавляет внизу какие-то овалы, настойчиво указывая на них когтем.$B$BСомнений нет – ему нужны яйца силитидов! К счастью, вы знаете, где раздобыть лакомство для малыша – в Ядовитом улье, который находится в западном Танарисе, рядом с Кратером Ун\'Горо.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Ваш равазаврик хочет, чтобы вы принесли ему 12 яиц силитида.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ваш равазаврик довольно облизывается, расправившись с яйцами силитида. Вам показалось – или он слегка разочарован тем, что еда уже кончилась?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите со своим равазавриком.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13917,'Обед из улья Гориши','Равазаврик испытующе смотрит на вас, после чего начинает что-то рисовать в грязи.$B$BСреди нарисованных знаков вы разбираете изображения различных больших насекомых, например, горишских силитидов. Малыш заканчивает рисунок, после чего указывает на него короткой лапой, чавкает и облизывается.$B$BОчевидно, он хочет, чтобы вы отправились в Скользкий овраг, что на юге Кратера Ун\'Горо, и принесли ему мясо силитидов. Когда соберете мясо, угостите им своего равазаврика.','Ваш равазаврик проголодался. Принесите ему 10 кусков мяса силитида.','Ваш равазаврик дарит вам ослепительно клыкастую улыбку и сыто облизывается.','Детеныш поднимает голову и смотрит на вас.','Поговорите со своим равазавриком.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обед из улья Гориши',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Равазаврик испытующе смотрит на вас, после чего начинает что-то рисовать в грязи.$B$BСреди нарисованных знаков вы разбираете изображения различных больших насекомых, например, горишских силитидов. Малыш заканчивает рисунок, после чего указывает на него короткой лапой, чавкает и облизывается.$B$BОчевидно, он хочет, чтобы вы отправились в Скользкий овраг, что на юге Кратера Ун\'Горо, и принесли ему мясо силитидов. Когда соберете мясо, угостите им своего равазаврика.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Ваш равазаврик проголодался. Принесите ему 10 кусков мяса силитида.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ваш равазаврик дарит вам ослепительно клыкастую улыбку и сыто облизывается.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Детеныш поднимает голову и смотрит на вас.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите со своим равазавриком.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13918,'Терминал титанов','Теперь, когда диск у нас в руках, многие предыдущие находки обретают новое значение. Например, вскоре после моего прибытия, геолог Сомнамбулер откопал нечто, напоминающее доисторический тостер.$B$BЯ же всегда был убежден, что это устройство предназначено для чтения данных. К несчастью, его разбило и унесло волной вместе со всем нашим лагерем во время цунами!$B$BНо он не мог уплыть далеко – наверняка обломки все еще валяются на линии прибоя. Вот, возьми мой проверенный детектор артефактов и прочеши им весь пляж.','Используйте обнаружитель затерянных артефактов на пляже возле Раскопок Сомнамбулера, чтобы найти 5 деталей артефакта. Соберите их вместе, чтобы получить древнее устройство с прорезью.','Отнесите устройство археологу Ферду на Раскопки Сомнамбулера на Темных берегах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Терминал титанов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда диск у нас в руках, многие предыдущие находки обретают новое значение. Например, вскоре после моего прибытия, геолог Сомнамбулер откопал нечто, напоминающее доисторический тостер.$B$BЯ же всегда был убежден, что это устройство предназначено для чтения данных. К несчастью, его разбило и унесло волной вместе со всем нашим лагерем во время цунами!$B$BНо он не мог уплыть далеко – наверняка обломки все еще валяются на линии прибоя. Вот, возьми мой проверенный детектор артефактов и прочеши им весь пляж.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте обнаружитель затерянных артефактов на пляже возле Раскопок Сомнамбулера, чтобы найти 5 деталей артефакта. Соберите их вместе, чтобы получить древнее устройство с прорезью.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите устройство археологу Ферду на Раскопки Сомнамбулера на Темных берегах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`) VALUES (13919,'Путешествие к Лунному колодцу','Ничего не вышло...$B$B<С глубокой скорбью на лице Пельтур достает Слезу из чаши и бережно омывает ее.>$B$BДолжно быть, на святыню как-то повлияло извержение Громовой вершины. Пожалуйста, отнеси Слезу к Лунному колодцу чистоты. Это единственное место, еще не затронутое скверной – его охраняет сама сила богини. Он находится на юго-востоке от подножия вулкана.$B$BОмой святыню в водах, благословленных Элуной. Я не могу знать, что будет дальше. Я боюсь за судьбу моей дочери. Теперь она в твоих руках, $n.','Очистите Слезу Элуны в Лунном колодце чистоты, что в Ясеневом лесу.','Слеза Элуны очищена.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путешествие к Лунному колодцу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ничего не вышло...$B$B<С глубокой скорбью на лице Пельтур достает Слезу из чаши и бережно омывает ее.>$B$BДолжно быть, на святыню как-то повлияло извержение Громовой вершины. Пожалуйста, отнеси Слезу к Лунному колодцу чистоты. Это единственное место, еще не затронутое скверной – его охраняет сама сила богини. Он находится на юго-востоке от подножия вулкана.$B$BОмой святыню в водах, благословленных Элуной. Я не могу знать, что будет дальше. Я боюсь за судьбу моей дочери. Теперь она в твоих руках, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Очистите Слезу Элуны в Лунном колодце чистоты, что в Ясеневом лесу.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Слеза Элуны очищена.',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13920,'Прежде, чем уйти...','Здесь, в Дозоре Адского Крика, не хватает таких |3-8($c), как ты. Поэтому прежде, чем ты отправишься в путь, я хочу попросить тебя об одной услуге.$b$bИз-за непрекращающихся атак Альянса мы потеряли в море множество ценных товаров, в том числе провизию, необходимую для поддержания сил наших солдат, участвующих в битве за Ясеневый лес.$b$bОднако к востоку отсюда находятся богатые охотничьи угодья. Добудь для наших отрядов самое лучшее мясо, которое только сможешь найти!','Принесите 5 стейков из оленины командиру Мрачному Клыку в форт Зорам\'гар.','Что это у тебя там, дружище?$B$BАх, да! Вкусная оленина – счастливый солдат!$B$BВот, возьми пару монет за труды.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прежде, чем уйти...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Здесь, в Дозоре Адского Крика, не хватает таких |3-8($c), как ты. Поэтому прежде, чем ты отправишься в путь, я хочу попросить тебя об одной услуге.$b$bИз-за непрекращающихся атак Альянса мы потеряли в море множество ценных товаров, в том числе провизию, необходимую для поддержания сил наших солдат, участвующих в битве за Ясеневый лес.$b$bОднако к востоку отсюда находятся богатые охотничьи угодья. Добудь для наших отрядов самое лучшее мясо, которое только сможешь найти!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 5 стейков из оленины командиру Мрачному Клыку в форт Зорам\'гар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что это у тебя там, дружище?$B$BАх, да! Вкусная оленина – счастливый солдат!$B$BВот, возьми пару монет за труды.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (13921,'Тот, кто будет прощен','<Вы чувствуете, как в вашей голове раздается бесконечно умиротворяющий голос, исходящий откуда-то из колодца.>$B$BТы желаешь исцелить дитя, но каждое деяние, даже самое благое, должно быть оплачено. На востоке отсюда высится Башня в Ночных лесах, а рядом с ней возле моего лунного колодца бродит существо, поддавшееся скверне.$B$BАврий Дурной Толк жаждет прощения и освобождения. Даруешь ли ты ему то, о чем он просит, если это приблизит тебя к цели?','Поговорите с Аврием Дурным Толком у башни в Ночных лесах, что в Ясеневом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тот, кто будет прощен',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Вы чувствуете, как в вашей голове раздается бесконечно умиротворяющий голос, исходящий откуда-то из колодца.>$B$BТы желаешь исцелить дитя, но каждое деяние, даже самое благое, должно быть оплачено. На востоке отсюда высится Башня в Ночных лесах, а рядом с ней возле моего лунного колодца бродит существо, поддавшееся скверне.$B$BАврий Дурной Толк жаждет прощения и освобождения. Даруешь ли ты ему то, о чем он просит, если это приблизит тебя к цели?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Аврием Дурным Толком у башни в Ночных лесах, что в Ясеневом лесу.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13922,'В оскверненных руках','Мой бывший клан Кабарог Скверны из Ночной поляны довольно часто охотился у Зеркала Небес и собирал лунные камни, которые встречаются только в тех местах.$B$BЭти лунные камни известны своими целебными свойствами. Не сомневаюсь, они могут помочь исцелить эту бедную девочку из Астранаара.$B$BНочная поляна находится возле дороги, ведущей на север. От нее отходит множество тропинок, огибающих холмы с восточной стороны – именно там ты найдешь моих нераскаявшихся братьев. У них есть то, что тебе нужно.','Добудьте 5 лунных камней Упавшего Неба.','Чтобы исцелить девочку, потребуются все пять лунных камней.','Вернитесь к Аврию Дурному Толку у башни в Ночных лесах, что в Ясеневом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В оскверненных руках',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мой бывший клан Кабарог Скверны из Ночной поляны довольно часто охотился у Зеркала Небес и собирал лунные камни, которые встречаются только в тех местах.$B$BЭти лунные камни известны своими целебными свойствами. Не сомневаюсь, они могут помочь исцелить эту бедную девочку из Астранаара.$B$BНочная поляна находится возле дороги, ведущей на север. От нее отходит множество тропинок, огибающих холмы с восточной стороны – именно там ты найдешь моих нераскаявшихся братьев. У них есть то, что тебе нужно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 5 лунных камней Упавшего Неба.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Чтобы исцелить девочку, потребуются все пять лунных камней.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аврию Дурному Толку у башни в Ночных лесах, что в Ясеневом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13923,'На заставу Адского Крика','Вперед, в самое пекло, |3-6($r)!$b$bЗастава Адского Крика – самый ненадежный фронт во всем Ясеневом лесу, но ты многое узнаешь, побывав там лично... если, конечно, выживешь.$b$bКак закончишь последние приготовления, поговори с Андруком. Я поручил ему отправить тебя прямо на заставу.$b$bПрибудешь на место и немедленно разыщешь капитана Гоггата. Он выдаст тебе дальнейшие инструкции.$b$bСмерть и боль нашим врагам! За Орду!','Поговорите с капитаном Гоггатом в дозоре Адского Крика.','Ты явилась сюда беспомощной как дитя, а покинешь нас закаленным в боях воителем Орды!$B$BСо щитом или на щите...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На заставу Адского Крика',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вперед, в самое пекло, |3-6($r)!$b$bЗастава Адского Крика – самый ненадежный фронт во всем Ясеневом лесу, но ты многое узнаешь, побывав там лично... если, конечно, выживешь.$b$bКак закончишь последние приготовления, поговори с Андруком. Я поручил ему отправить тебя прямо на заставу.$b$bПрибудешь на место и немедленно разыщешь капитана Гоггата. Он выдаст тебе дальнейшие инструкции.$b$bСмерть и боль нашим врагам! За Орду!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с капитаном Гоггатом в дозоре Адского Крика.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты явилась сюда беспомощной как дитя, а покинешь нас закаленным в боях воителем Орды!$B$BСо щитом или на щите...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (13924,'Все в порядке','Спасибо за то, что ты $gспас:спасла; меня от участи хуже, чем смерть! За то, что ты $gуберег:уберегла; от погибели меня и этого несчастного ребенка.$b$bТеперь дитя почти в безопасности. Осталось только отнести лунные камни назад, на запад от Астранаара. Передай их Пельтуру – он знает, что делать дальше.$B$BСтупай с миром, и да хранит тебя Элуна!','Отнесите освященные лунные камни Пельтуру Белой Луне в Астранаар, что в Ясеневом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Все в порядке',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Спасибо за то, что ты $gспас:спасла; меня от участи хуже, чем смерть! За то, что ты $gуберег:уберегла; от погибели меня и этого несчастного ребенка.$b$bТеперь дитя почти в безопасности. Осталось только отнести лунные камни назад, на запад от Астранаара. Передай их Пельтуру – он знает, что делать дальше.$B$BСтупай с миром, и да хранит тебя Элуна!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите освященные лунные камни Пельтуру Белой Луне в Астранаар, что в Ясеневом лесу.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13925,'Подстелить соломку','А ты никак $gслышал:слышала; про Древних богов, $n? Мы с Ону единогласны во мнении, что найденный тобой артефакт мог быть изготовлен только ими, и теперь он поглощает Темные Берега. Что-то пробудило кошмары, которые мы считали давно позабытыми. Это неподвластно тебе и мне... но я хочу хотя бы сохранить природу от воздействия зла.$B$BВ этом побеге заключена энергия жизни, которую ты мне $gпринес:принесла;. Хочется верить, что она защитит местных обитателей. Испытай ее на любом медведе, олене или лунопарде, не затронутом порчей, и дай мне знать, что случится!','Испытайте саженец жизненоса на любом здоровом седом колючешерстном медведе, белохвостом олене, лунопарде-матриархе или патриархе.','Вернитесь к Катрене Зимний Шорох в Рощу Древних, что на Темных берегах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подстелить соломку',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А ты никак $gслышал:слышала; про Древних богов, $n? Мы с Ону единогласны во мнении, что найденный тобой артефакт мог быть изготовлен только ими, и теперь он поглощает Темные Берега. Что-то пробудило кошмары, которые мы считали давно позабытыми. Это неподвластно тебе и мне... но я хочу хотя бы сохранить природу от воздействия зла.$B$BВ этом побеге заключена энергия жизни, которую ты мне $gпринес:принесла;. Хочется верить, что она защитит местных обитателей. Испытай ее на любом медведе, олене или лунопарде, не затронутом порчей, и дай мне знать, что случится!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Испытайте саженец жизненоса на любом здоровом седом колючешерстном медведе, белохвостом олене, лунопарде-матриархе или патриархе.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Катрене Зимний Шорох в Рощу Древних, что на Темных берегах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13926,'Ру, оракул-сиротка','Дети будут очень рады такому другу, как вы, $n. Как замечательно, что вы станете опекать одного из них!$B$BВозьмите эту свистульку, с ее помощью вы сможете позвать своего воспитанника. Свистулька не прослужит долго, но на Детскую неделю должно хватить.$B$BПозовите сиротку, $n! Он будет очень рад познакомиться с вами и попутешествовать по Нордсколу.','Поговорите с попечительницей сирот Арией; после этого воспользуйтесь детской свистулькой оракула, чтобы позвать сиротку, о котором вы будете заботиться во время Детской недели.','Ты уведешь нас подальше от остальных детенышей? Хорошо. Тогда ты нам нравишься. Злые детеныши людей-собак отнимают наши игрушки.','Ты позаботишься о нас?','Поговорите с оракулом-сиротой. Воспользуйтесь детской свистулькой, чтобы позвать вашего подопечного, если его нет рядом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ру, оракул-сиротка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Дети будут очень рады такому другу, как вы, $n. Как замечательно, что вы станете опекать одного из них!$B$BВозьмите эту свистульку, с ее помощью вы сможете позвать своего воспитанника. Свистулька не прослужит долго, но на Детскую неделю должно хватить.$B$BПозовите сиротку, $n! Он будет очень рад познакомиться с вами и попутешествовать по Нордсколу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с попечительницей сирот Арией; после этого воспользуйтесь детской свистулькой оракула, чтобы позвать сиротку, о котором вы будете заботиться во время Детской недели.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты уведешь нас подальше от остальных детенышей? Хорошо. Тогда ты нам нравишься. Злые детеныши людей-собак отнимают наши игрушки.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты позаботишься о нас?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с оракулом-сиротой. Воспользуйтесь детской свистулькой, чтобы позвать вашего подопечного, если его нет рядом.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13927,'Кекек, волчер-сиротка','Дети будут очень рады такому другу, как вы, $n. Как замечательно, что вы станете опекать одного из них!$B$BВозьмите эту свистульку, с ее помощью вы сможете позвать своего воспитанника. Свистулька не прослужит долго, но на Детскую неделю должно хватить.$B$BПозовите сиротку, $n! Он будет очень рад познакомиться с вами и попутешествовать по Нордсколу.','Поговорите с попечительницей сирот Арией, после этого воспользуйтесь детской свистулькой волчера, чтобы позвать сиротку, о котором вы будете заботиться во время Детской недели.','Ты отведешь Кекека на охоту? Хорошо бы отправиться подальше от этой старой злой попечительницы, которая не дает Кекеку охотиться.','Попечительница сирот говорит Кекек идти с вами.','Поговорите с волчером-сиротой. Воспользуйтесь детской свистулькой, чтобы позвать вашего подопечного, если его нет рядом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кекек, волчер-сиротка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Дети будут очень рады такому другу, как вы, $n. Как замечательно, что вы станете опекать одного из них!$B$BВозьмите эту свистульку, с ее помощью вы сможете позвать своего воспитанника. Свистулька не прослужит долго, но на Детскую неделю должно хватить.$B$BПозовите сиротку, $n! Он будет очень рад познакомиться с вами и попутешествовать по Нордсколу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с попечительницей сирот Арией, после этого воспользуйтесь детской свистулькой волчера, чтобы позвать сиротку, о котором вы будете заботиться во время Детской недели.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты отведешь Кекека на охоту? Хорошо бы отправиться подальше от этой старой злой попечительницы, которая не дает Кекеку охотиться.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Попечительница сирот говорит Кекек идти с вами.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с волчером-сиротой. Воспользуйтесь детской свистулькой, чтобы позвать вашего подопечного, если его нет рядом.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13928,'Тела павших','Хранитель Ордан поручил мне и моим часовым охранять башню. Пока нам удавалось сдерживать атаки Орды, но теперь их войска заходят с севера, чтобы напрямую напасть на крепость.$B$BХранитель отправил дриад на защиту дерева, но что они могут сделать против авангарда орков Песни Войны?$B$BПрошу тебя, отправляйся туда и принеси как можно больше тел павших сестер. Их надо отнести Халаннии в Приют. Она сможет им помочь.','Соберите 10 трупов смеющихся сестер Халаннии.','Я просто потрясена тем, как тебе удалось прорваться сюда, сквозь строй ордынских воинов.','Поговорите с Халаннией на втором уровне приюта в Ночных Лесах, что в Ясеневом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тела павших',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хранитель Ордан поручил мне и моим часовым охранять башню. Пока нам удавалось сдерживать атаки Орды, но теперь их войска заходят с севера, чтобы напрямую напасть на крепость.$B$BХранитель отправил дриад на защиту дерева, но что они могут сделать против авангарда орков Песни Войны?$B$BПрошу тебя, отправляйся туда и принеси как можно больше тел павших сестер. Их надо отнести Халаннии в Приют. Она сможет им помочь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 трупов смеющихся сестер Халаннии.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я просто потрясена тем, как тебе удалось прорваться сюда, сквозь строй ордынских воинов.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Халаннией на втором уровне приюта в Ночных Лесах, что в Ясеневом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (13929,'Самое большое дерево!','Мы помним, что еще перед большой войной Су-сэй рассказывал нам о большом-пребольшом дереве!$B$BСу-сэй, кажется, называл его Седой Пастью, и оно в центре Серых холмов. Нет, неправильно, он говорил иначе! Мы вспомнили! Большое дерево растет прямо посреди Седых холмов! Такое не пропустишь!$B$BТы отведешь нас туда, да? И мы заберемся прямо внутрь? Су-сэй говорил, там живут большие люди-медведи. Может нам удастся их увидеть.','Отведите вашего подопечного Ру к Седой Пасти. Не забудьте позвать сиротку, если его не окажется рядом, когда вы прибудете на место.','Мы никогда не думали, что деревья бывают такими большими! Может быть, Великие специально сделали их такими?','Мы можем увидеть большое дерево? А мы можем?','Ру посетил Седую Пасть','Поговорите с оракулом-сиротой. Воспользуйтесь детской свистулькой, чтобы позвать вашего подопечного, если его нет рядом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Самое большое дерево!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы помним, что еще перед большой войной Су-сэй рассказывал нам о большом-пребольшом дереве!$B$BСу-сэй, кажется, называл его Седой Пастью, и оно в центре Серых холмов. Нет, неправильно, он говорил иначе! Мы вспомнили! Большое дерево растет прямо посреди Седых холмов! Такое не пропустишь!$B$BТы отведешь нас туда, да? И мы заберемся прямо внутрь? Су-сэй говорил, там живут большие люди-медведи. Может нам удастся их увидеть.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отведите вашего подопечного Ру к Седой Пасти. Не забудьте позвать сиротку, если его не окажется рядом, когда вы прибудете на место.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мы никогда не думали, что деревья бывают такими большими! Может быть, Великие специально сделали их такими?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мы можем увидеть большое дерево? А мы можем?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Ру посетил Седую Пасть',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с оракулом-сиротой. Воспользуйтесь детской свистулькой, чтобы позвать вашего подопечного, если его нет рядом.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (13930,'Дом людей-медведей','Верховный шаман Ракжак всегда рассказывал истории о великих воинах прошлого. Как-то он поведал об огромных людях-медведях, которые сражались за великий город-дерево.$B$BКекек хочет посмотреть на то дерево и место битвы! Верховный шаман Ракжак сказал Кекеку, что город-дерево называется Седая Пасть и находится в самом центре Седых холмов.$B$BКекек никогда раньше не видел городов до того, как встретился с попечительницей сирот, но в этом городе нет воинов – только мужчины в фиолетовых одеждах. Кекек хочет увидеть настоящих героев, которые сражаются за свой город!','Отведите вашего подопечного Кекека к Седой Пасти. Не забудьте позвать сиротку, если его не окажется рядом, когда вы прибудете на место.','Вот такой город очень нравится Кекеку. Эти люди-медведи сражаются так же отважно, как и племя Бешеного Сердца. Госпожа попечительница не разрешает Кекеку драться, но он все равно станет воином!','Кекек хочет посетить дерево людей-медведей. Мы идем.','Кекек посетил Седую Пасть','Поговорите с волчером-сиротой. Воспользуйтесь детской свистулькой, чтобы позвать вашего подопечного, если его нет рядом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дом людей-медведей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Верховный шаман Ракжак всегда рассказывал истории о великих воинах прошлого. Как-то он поведал об огромных людях-медведях, которые сражались за великий город-дерево.$B$BКекек хочет посмотреть на то дерево и место битвы! Верховный шаман Ракжак сказал Кекеку, что город-дерево называется Седая Пасть и находится в самом центре Седых холмов.$B$BКекек никогда раньше не видел городов до того, как встретился с попечительницей сирот, но в этом городе нет воинов – только мужчины в фиолетовых одеждах. Кекек хочет увидеть настоящих героев, которые сражаются за свой город!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отведите вашего подопечного Кекека к Седой Пасти. Не забудьте позвать сиротку, если его не окажется рядом, когда вы прибудете на место.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот такой город очень нравится Кекеку. Эти люди-медведи сражаются так же отважно, как и племя Бешеного Сердца. Госпожа попечительница не разрешает Кекеку драться, но он все равно станет воином!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Кекек хочет посетить дерево людей-медведей. Мы идем.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Кекек посетил Седую Пасть',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с волчером-сиротой. Воспользуйтесь детской свистулькой, чтобы позвать вашего подопечного, если его нет рядом.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13931,'Новый подарок к новому году','Мы не только поим всех подряд, но и дарим пивные кружки! Красивые, памятные кружки, полученные совершенно законным образом! Вот тебе купон на такую кружку.$b$bПоговори с Бликсом рядом с лагерем Хмельного фестиваля. Он довольно странный тип, тем более, что очки эти никогда не снимает. Он и отоварит твой купон. Он же занимается прочей праздничной торговлей.','Отоварьте свой купон на праздничную кружку у Бликса Чиништукса в лагере Хмельного фестиваля.','Что это? Ваучер на кружку? Так ты любишь выпить? После того, как я дам тебе эту кружку, выпей! Потом еще несколько. Может быть, еще несколько после этого... А потом приходи ко мне.$B$BСлушай, я знаю, что ты когда-нибудь вернешься. Если ты хочешь выкупить билеты на Хмельный фестиваль или знаки тебе нужно будет поговорить со мной.$B$BВ любом случае, вот кружка, и не забудь поговорить со мной позже.','Что происходит? Есть что-нибудь для меня?','Вернитесь к Бликсу Чиништуксу в Дуротар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новый подарок к новому году',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы не только поим всех подряд, но и дарим пивные кружки! Красивые, памятные кружки, полученные совершенно законным образом! Вот тебе купон на такую кружку.$b$bПоговори с Бликсом рядом с лагерем Хмельного фестиваля. Он довольно странный тип, тем более, что очки эти никогда не снимает. Он и отоварит твой купон. Он же занимается прочей праздничной торговлей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отоварьте свой купон на праздничную кружку у Бликса Чиништукса в лагере Хмельного фестиваля.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что это? Ваучер на кружку? Так ты любишь выпить? После того, как я дам тебе эту кружку, выпей! Потом еще несколько. Может быть, еще несколько после этого... А потом приходи ко мне.$B$BСлушай, я знаю, что ты когда-нибудь вернешься. Если ты хочешь выкупить билеты на Хмельный фестиваль или знаки тебе нужно будет поговорить со мной.$B$BВ любом случае, вот кружка, и не забудь поговорить со мной позже.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что происходит? Есть что-нибудь для меня?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бликсу Чиништуксу в Дуротар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13932,'Новый подарок к новому году','Главное на Хмельном фестивале – не гонки на баранах, а выпивка! Улучи минутку и отдай свой купон Белби Быстросмен. Она стоит за поляной, на которой проходит Хмельной фестиваль. Если ты ее не увидишь, не беспокойся, она-то тебя всяко заметит.$b$bВ общем, отдай ей свой купон, и получишь бесплатную праздничную кружку. Кроме того, именно Белби занимается прочей праздничной торговлей.','Отоварьте свой купон на праздничную кружку у Бликса Чиништукса в лагере Хмельного фестиваля.','Ой, это всего лишь ваучер на кружку... Может, ты просто играешь, чтобы их получить. Итак, вот тебе кружка этого года.$B$BНо я подозреваю, что увижу тебя гораздо раньше. В конце концов, если ты хочешь выкупить какие-либо жетоны Хмельного фестиваля, я твоя девушка...$B$BА может я его девушка...$B$BОоооо... или его...','Что происходит? Есть что-нибудь для меня?','Вернитесь к Белби Быстросмен в Дун Морог.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новый подарок к новому году',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Главное на Хмельном фестивале – не гонки на баранах, а выпивка! Улучи минутку и отдай свой купон Белби Быстросмен. Она стоит за поляной, на которой проходит Хмельной фестиваль. Если ты ее не увидишь, не беспокойся, она-то тебя всяко заметит.$b$bВ общем, отдай ей свой купон, и получишь бесплатную праздничную кружку. Кроме того, именно Белби занимается прочей праздничной торговлей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отоварьте свой купон на праздничную кружку у Бликса Чиништукса в лагере Хмельного фестиваля.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ой, это всего лишь ваучер на кружку... Может, ты просто играешь, чтобы их получить. Итак, вот тебе кружка этого года.$B$BНо я подозреваю, что увижу тебя гораздо раньше. В конце концов, если ты хочешь выкупить какие-либо жетоны Хмельного фестиваля, я твоя девушка...$B$BА может я его девушка...$B$BОоооо... или его...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что происходит? Есть что-нибудь для меня?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Белби Быстросмен в Дун Морог.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (13933,'Святилище бронзовых драконов','Иногда верховный оракул Су-сэй рассказывает истории о великой святыне драконов – не такой, конечно, как Великий камень дождя, а совсем другой. Су-сэй говорит, что мы можем увидеть в ней себя – точнее, какими мы будем через много лет.$B$BОтведешь нас туда? Мы помним, что это святилище бронзовых драконов, которое находится в Драконьем Погосте. Су-сэй говорит, что Великий камень дождя показал ему святилище на северо-востоке от Храма Драконьего Покоя или на северо-западе от места, которое сухокожие зовут Крепостью Стражей Зимы. Идем?','Отведите вашего подопечного Ру к Бронзовому святилищу драконов. Не забудьте позвать сиротку, если его не окажется рядом, когда вы прибудете на место.','Мы очень рады, что ты $Gпривел:привела; нас сюда, $N. Мы волновались, что случится с нами в будущем с тех пор, как попечительница нашла нас в Шолазаре.','Мы посетим храм драконьих тварей?','Ру посетил Бронзовое святилище драконов','Поговорите с оракулом-сиротой. Воспользуйтесь детской свистулькой, чтобы позвать вашего подопечного, если его нет рядом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Святилище бронзовых драконов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Иногда верховный оракул Су-сэй рассказывает истории о великой святыне драконов – не такой, конечно, как Великий камень дождя, а совсем другой. Су-сэй говорит, что мы можем увидеть в ней себя – точнее, какими мы будем через много лет.$B$BОтведешь нас туда? Мы помним, что это святилище бронзовых драконов, которое находится в Драконьем Погосте. Су-сэй говорит, что Великий камень дождя показал ему святилище на северо-востоке от Храма Драконьего Покоя или на северо-западе от места, которое сухокожие зовут Крепостью Стражей Зимы. Идем?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отведите вашего подопечного Ру к Бронзовому святилищу драконов. Не забудьте позвать сиротку, если его не окажется рядом, когда вы прибудете на место.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мы очень рады, что ты $Gпривел:привела; нас сюда, $N. Мы волновались, что случится с нами в будущем с тех пор, как попечительница нашла нас в Шолазаре.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мы посетим храм драконьих тварей?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Ру посетил Бронзовое святилище драконов',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с оракулом-сиротой. Воспользуйтесь детской свистулькой, чтобы позвать вашего подопечного, если его нет рядом.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (13934,'Святилище бронзовых драконов','Когда Кекек был щенком, он слышал, как старейшины рассказывали об одном далеком святилище. Они говорили, что род бронзовых драконов, который его оберегает, может видеть будущее.$B$BКекек станет великим воином! Пойдем, посмотрим каким вырастет Кекек. Святилище бронзовых драконов находится где-то на Драконьем Погосте, на северо-восток от храма Драконьего Покоя и на северо-запад от Крепости Стражей Зимы.$B$BПойдем, увидим будущее. Плохо, что попечительница ругает Кекека. Кекек воин, а не забияка.','Отведите вашего подопечного Кекека к Бронзовому святилищу драконов. Не забудьте позвать сиротку, если его не окажется рядом, когда вы прибудете на место.','Вот видишь? Кекек был прав. Кекек всегда прав.$B$BМожет быть, теперь ты будешь слушать Кекека, даже если он говорит, что небо зеленое.','Кекек хочет посетить святилище драконов.','Кекек посетил Бронзовое святилище драконов','Поговорите с волчером-сиротой. Воспользуйтесь детской свистулькой, чтобы позвать вашего подопечного, если его нет рядом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Святилище бронзовых драконов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда Кекек был щенком, он слышал, как старейшины рассказывали об одном далеком святилище. Они говорили, что род бронзовых драконов, который его оберегает, может видеть будущее.$B$BКекек станет великим воином! Пойдем, посмотрим каким вырастет Кекек. Святилище бронзовых драконов находится где-то на Драконьем Погосте, на северо-восток от храма Драконьего Покоя и на северо-запад от Крепости Стражей Зимы.$B$BПойдем, увидим будущее. Плохо, что попечительница ругает Кекека. Кекек воин, а не забияка.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отведите вашего подопечного Кекека к Бронзовому святилищу драконов. Не забудьте позвать сиротку, если его не окажется рядом, когда вы прибудете на место.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот видишь? Кекек был прав. Кекек всегда прав.$B$BМожет быть, теперь ты будешь слушать Кекека, даже если он говорит, что небо зеленое.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Кекек хочет посетить святилище драконов.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Кекек посетил Бронзовое святилище драконов',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с волчером-сиротой. Воспользуйтесь детской свистулькой, чтобы позвать вашего подопечного, если его нет рядом.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13935,'Защитить древо!','Мы использовали силу сердца леса для защиты древа от Орды, но его возможности не безграничны. Теперь мы воспользуемся святыней, чтобы дать врагам отпор!$B$BЗдесь неподалеку охотится Тенумбра, великая хищница леса. В ее силе и ловкости мы должны черпать вдохновение. Ты станешь $gедин:едина; с ее тенью, впитаешь в себя дух пантеры и уничтожишь тех, кто посягает на величие Ясеневого леса!','Поговорите с Халаннией, чтобы призвать тень Тенумбры, и воспользуйтесь ее силой, чтобы уничтожить 50 врагов из клана Песни Войны в приюте в Ночных Лесах.','Поговорите с часовой Мелирией Ледяной Тенью у башни в Ночных лесах, что в Ясеневом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Защитить древо!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы использовали силу сердца леса для защиты древа от Орды, но его возможности не безграничны. Теперь мы воспользуемся святыней, чтобы дать врагам отпор!$B$BЗдесь неподалеку охотится Тенумбра, великая хищница леса. В ее силе и ловкости мы должны черпать вдохновение. Ты станешь $gедин:едина; с ее тенью, впитаешь в себя дух пантеры и уничтожишь тех, кто посягает на величие Ясеневого леса!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Халаннией, чтобы призвать тень Тенумбры, и воспользуйтесь ее силой, чтобы уничтожить 50 врагов из клана Песни Войны в приюте в Ночных Лесах.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с часовой Мелирией Ледяной Тенью у башни в Ночных лесах, что в Ясеневом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (13936,'Болван Шкрып','Задержки, опять задержки! Сил моих не хватает!$b$bМне сказали, что этот гоблин просто гений – мол, он изобретет такое устройство, которое превратит в пыль наших врагов, но пока что он нас только завтраками кормит! Если он еще раз явится с пустыми руками, клянусь, сброшу его с обрыва! $b$bИди поговори с ним, |3-6($c). Скажи ему, что мое терпение на исходе.','Капитан Гоггат просит вас поговорить с Шкрыпом в Дозоре Адского Крика.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Болван Шкрып',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Задержки, опять задержки! Сил моих не хватает!$b$bМне сказали, что этот гоблин просто гений – мол, он изобретет такое устройство, которое превратит в пыль наших врагов, но пока что он нас только завтраками кормит! Если он еще раз явится с пустыми руками, клянусь, сброшу его с обрыва! $b$bИди поговори с ним, |3-6($c). Скажи ему, что мое терпение на исходе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Капитан Гоггат просит вас поговорить с Шкрыпом в Дозоре Адского Крика.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13937,'Поездка в "Чудо чудное".','А у нас есть еще минутка? Мы слышали, что в Даларане есть магазин игрушек, но никогда там не были. Госпожа попечительница говорит, что сирот слишком много, и мы будем мешать покупателям. Может быть, мы могли бы заглянуть туда вдвоем?$B$BА еще мы всегда хотели бумажный дирижаблик. Как ты думаешь, они продаются в "Чуде чудном"? Это наша мечта... Может быть, ты подаришь нам его?','Купите бумажный дирижаблик в магазине "Чудо чудное" и бросьте его вашему подопечному Ру.','Это было здорово! Нам понравился магазин игрушек. Может быть, попечительница приведет нас сюда еще раз? Мы ее попросим. И ты ее попроси, пожалуйста!','Мы идем в "Чудо чудное"?','Поговорите с оракулом-сиротой. Воспользуйтесь детской свистулькой, чтобы позвать вашего подопечного, если его нет рядом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поездка в "Чудо чудное".',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А у нас есть еще минутка? Мы слышали, что в Даларане есть магазин игрушек, но никогда там не были. Госпожа попечительница говорит, что сирот слишком много, и мы будем мешать покупателям. Может быть, мы могли бы заглянуть туда вдвоем?$B$BА еще мы всегда хотели бумажный дирижаблик. Как ты думаешь, они продаются в "Чуде чудном"? Это наша мечта... Может быть, ты подаришь нам его?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Купите бумажный дирижаблик в магазине "Чудо чудное" и бросьте его вашему подопечному Ру.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это было здорово! Нам понравился магазин игрушек. Может быть, попечительница приведет нас сюда еще раз? Мы ее попросим. И ты ее попроси, пожалуйста!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мы идем в "Чудо чудное"?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с оракулом-сиротой. Воспользуйтесь детской свистулькой, чтобы позвать вашего подопечного, если его нет рядом.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13938,'Заглянем в "Чудо чудное".','Может Кекек тебя еще кое о чем попросить? Попечительница рассказывала, что в Даларане есть магазин игрушек "Чудо чудное", но Кекека туда не пускают. Говорят, если Кекек туда пойдет, придется отвести и всех остальных сирот. Но Кекек очень хочет попасть в магазин!$B$BКекек видел, как другие дети играют с бумажными дирижабликами. Говорят, их продают в "Чуде чудном". Ты запустишь такой дирижаблик, чтобы он летал вокруг Кекека?','Купите бумажный дирижаблик в магазине "Чудо чудное" и бросьте его вашему подопечному Кекеку.','Кекеку нравится играть с бумажным дирижабликом. Конечно, охота гораздо веселее, но теперь Кекеку будет, чем заняться в приюте.','Этот магазин игрушек еще не открылся?','Поговорите с волчером-сиротой. Воспользуйтесь детской свистулькой, чтобы позвать вашего подопечного, если его нет рядом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Заглянем в "Чудо чудное".',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Может Кекек тебя еще кое о чем попросить? Попечительница рассказывала, что в Даларане есть магазин игрушек "Чудо чудное", но Кекека туда не пускают. Говорят, если Кекек туда пойдет, придется отвести и всех остальных сирот. Но Кекек очень хочет попасть в магазин!$B$BКекек видел, как другие дети играют с бумажными дирижабликами. Говорят, их продают в "Чуде чудном". Ты запустишь такой дирижаблик, чтобы он летал вокруг Кекека?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Купите бумажный дирижаблик в магазине "Чудо чудное" и бросьте его вашему подопечному Кекеку.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Кекеку нравится играть с бумажным дирижабликом. Конечно, охота гораздо веселее, но теперь Кекеку будет, чем заняться в приюте.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Этот магазин игрушек еще не открылся?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с волчером-сиротой. Воспользуйтесь детской свистулькой, чтобы позвать вашего подопечного, если его нет рядом.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13939,'Мох скверны','[Deprecated] I\'d hoped to never return to Teldrassil for such grim business. I\'d hoped that its corruption had been wiped away completely. Something fowl lingers.$B$BThe corruption of the wicked fel moss still threatens to turn peaceful creatures against us. The grells and gellkin still infest the area and threaten Shadowglen\'s residents.$B$BEngage these grells and grellkin, $n, and see if they are indeed caught under the enchantment of the wicked fel moss. Once we know for certain, we will know how to proceed.','Соберите 6 образцов мха скверны.','Вернитесь к Тариндрелле в Тенистую долину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мох скверны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','[Deprecated] I\'d hoped to never return to Teldrassil for such grim business. I\'d hoped that its corruption had been wiped away completely. Something fowl lingers.$B$BThe corruption of the wicked fel moss still threatens to turn peaceful creatures against us. The grells and gellkin still infest the area and threaten Shadowglen\'s residents.$B$BEngage these grells and grellkin, $n, and see if they are indeed caught under the enchantment of the wicked fel moss. Once we know for certain, we will know how to proceed.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 6 образцов мха скверны.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тариндрелле в Тенистую долину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (13940,'Пробуждение ото Сна','Держись крепче, $n. Дорога в мир бодрствующих может оказаться тяжелой для твоего неподготовленного разума и тела.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пробуждение ото Сна',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Держись крепче, $n. Дорога в мир бодрствующих может оказаться тяжелой для твоего неподготовленного разума и тела.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (13941,'Зловещее прикосновение','Гитьис Зловещая прославилась своим ядом – более сильным, чем у любого другого чащобного тенетника. Дирания Серебряное Сияние, живущая у основания Альдрассила, наверняка весьма заинтересована в яде из переполненных ядовитых желез Гитьис, чтобы создать не менее мощную противоядную сыворотку. Возможно, она так в этом заинтересована, что даже предложит награду...','Принесите переполненную ядовитую железу Дирании Серебряное Сияние в Альдрассил.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зловещее прикосновение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Гитьис Зловещая прославилась своим ядом – более сильным, чем у любого другого чащобного тенетника. Дирания Серебряное Сияние, живущая у основания Альдрассила, наверняка весьма заинтересована в яде из переполненных ядовитых желез Гитьис, чтобы создать не менее мощную противоядную сыворотку. Возможно, она так в этом заинтересована, что даже предложит награду...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите переполненную ядовитую железу Дирании Серебряное Сияние в Альдрассил.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (13943,'Превентивный удар','Наши войска еще не готовы осадить Астранаар, |3-6($c). Однако наши враги знают о скором нападении и не сидят на месте. Они разбили лагерь у подножия скалы и намереваются напасть на нас при свете луны.$b$bЯ хочу, чтобы ты $gвышиб:вышибла; эти мысли у них из головы – можно вместе с мозгами. Возвращайся, когда утихомиришь этих остроухих.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Превентивный удар',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наши войска еще не готовы осадить Астранаар, |3-6($c). Однако наши враги знают о скором нападении и не сидят на месте. Они разбили лагерь у подножия скалы и намереваются напасть на нас при свете луны.$b$bЯ хочу, чтобы ты $gвышиб:вышибла; эти мысли у них из головы – можно вместе с мозгами. Возвращайся, когда утихомиришь этих остроухих.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (13944,'Взорвите сломанный фургон в Дозоре Адского Крика с помощью импровизированной взрывчатки.','Значит, Шкрып все-таки сделал что-то стоящее?$B$BСамое время…','Поговорите с капитаном Гоггатом в дозоре Адского Крика, что в Ясеневом лесу.') ON DUPLICATE KEY UPDATE `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Взорвите сломанный фургон в Дозоре Адского Крика с помощью импровизированной взрывчатки.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Значит, Шкрып все-таки сделал что-то стоящее?$B$BСамое время…',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с капитаном Гоггатом в дозоре Адского Крика, что в Ясеневом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (13945,'Опасность обители','Агрессия племени Кривой Сосны связывает нам руки. Никто из наших не горит желанием взять на себя ответственность и выступить против существ, которые некогда были нашими друзьями, но я все больше опасаюсь того, что они планируют вскоре захватить Доланаар.$b$bБольше всего меня беспокоят фурболги в лощине Бен\'этиль и обители Бен\'этиль. Я хочу, чтобы ты $gотправился:отправилась; на запад, $gдобрался:добралась; до обители и $gубил:убила; так много фурболгов Кривой Сосны, как только сможешь. Может быть, у нас больше не будет возможностей уменьшить их силы, поэтому действуй без промедлений.','Убейте 20 фурболгов Кривой Сосны внутри и вокруг обители Бен\'этиль.','Впечатляет. Надеюсь, моя охотница справилась со своей ношей. Главное, что вы оба живы, так что мне не на что жаловаться.','Вернитесь к часовому Кире Песнь Звезд в Доланаар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Опасность обители',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Агрессия племени Кривой Сосны связывает нам руки. Никто из наших не горит желанием взять на себя ответственность и выступить против существ, которые некогда были нашими друзьями, но я все больше опасаюсь того, что они планируют вскоре захватить Доланаар.$b$bБольше всего меня беспокоят фурболги в лощине Бен\'этиль и обители Бен\'этиль. Я хочу, чтобы ты $gотправился:отправилась; на запад, $gдобрался:добралась; до обители и $gубил:убила; так много фурболгов Кривой Сосны, как только сможешь. Может быть, у нас больше не будет возможностей уменьшить их силы, поэтому действуй без промедлений.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 20 фурболгов Кривой Сосны внутри и вокруг обители Бен\'этиль.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Впечатляет. Надеюсь, моя охотница справилась со своей ношей. Главное, что вы оба живы, так что мне не на что жаловаться.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к часовому Кире Песнь Звезд в Доланаар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (13946,'Возмездие природы','Я рада, что ты $gрешил:решила; исправить свою ошибку – это говорит много хорошего о твоем характере.$b$bУ меня есть для тебя еще одно задание. Я собрала несколько семян гневоплода. Они похожи на шишки Скверны, но гораздо более мощные. Природа часто очень негативно реагирует на демонов, и эти семена гневоплода являют собой яркий пример такой реакции.$b$bК северу отсюда, в Пещере Бесов находятся грелли в огромном количестве. Используй эти семена гневоплода, чтобы избавиться от них, пока они не стали совсем серьезной угрозой.','Используйте семена гневоплода, чтобы убить 12 греллей в Пещере Бесов.','Хорошо. Я знаю, это была не очень приятная работа, но мы очень ценим, что ты ее выполнил.$B$BЯ боюсь за наш любимый Тельдрассил… Кажется, что с каждым днем появляется все больше порчи.','Вернитесь к Сирелу Остролисту в Доланаар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возмездие природы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я рада, что ты $gрешил:решила; исправить свою ошибку – это говорит много хорошего о твоем характере.$b$bУ меня есть для тебя еще одно задание. Я собрала несколько семян гневоплода. Они похожи на шишки Скверны, но гораздо более мощные. Природа часто очень негативно реагирует на демонов, и эти семена гневоплода являют собой яркий пример такой реакции.$b$bК северу отсюда, в Пещере Бесов находятся грелли в огромном количестве. Используй эти семена гневоплода, чтобы избавиться от них, пока они не стали совсем серьезной угрозой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте семена гневоплода, чтобы убить 12 греллей в Пещере Бесов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо. Я знаю, это была не очень приятная работа, но мы очень ценим, что ты ее выполнил.$B$BЯ боюсь за наш любимый Тельдрассил… Кажется, что с каждым днем появляется все больше порчи.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сирелу Остролисту в Доланаар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (13947,'Адстранаар!','Так значит Шкрып все-таки изобрел хорошую взрывчатку?$b$bКак нельзя вовремя. Пока мы тут прохлаждаемся, эльфы Астранаара готовят атаку на наш лагерь.$b$bНо мы сбросим на них наши бомбы с воздуха! Гибель Астранаара станет величайшей трагедией для всех ночных эльфов.$b$bКак только завершишь последние приготовления, поговори с Тракой. И пусть рука твоя будет твердой, |3-6($c).','Твои деяния будут навеки вписаны в историю Орды.$B$BСегодня мы нанесли сокрушительный удар врагу!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Адстранаар!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Так значит Шкрып все-таки изобрел хорошую взрывчатку?$b$bКак нельзя вовремя. Пока мы тут прохлаждаемся, эльфы Астранаара готовят атаку на наш лагерь.$b$bНо мы сбросим на них наши бомбы с воздуха! Гибель Астранаара станет величайшей трагедией для всех ночных эльфов.$b$bКак только завершишь последние приготовления, поговори с Тракой. И пусть рука твоя будет твердой, |3-6($c).',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Твои деяния будут навеки вписаны в историю Орды.$B$BСегодня мы нанесли сокрушительный удар врагу!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13948,'В дозор','Похоже, служители культа откапывают останки существа, известного как Соггот Скользящий.$B$BНаверное, их надзиратели, что стоят на вершине платформ, знают больше о том, зачем это делается.','Проникните к Мечу Властителя, воспользовавшись магией статуэтки пантеры, и проследите за предводителями культа Сумеречного Молота.','Вернитесь к Балрену-медведю в Рощу Древних, что на Темных берегах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В дозор',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Похоже, служители культа откапывают останки существа, известного как Соггот Скользящий.$B$BНаверное, их надзиратели, что стоят на вершине платформ, знают больше о том, зачем это делается.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проникните к Мечу Властителя, воспользовавшись магией статуэтки пантеры, и проследите за предводителями культа Сумеречного Молота.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Балрену-медведю в Рощу Древних, что на Темных берегах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (13950,'Друзья детства!','Знаешь, в сиротском приюте так одиноко... Иногда нам хочется увидеть другие края, встретить новых друзей.$B$BМожет быть, ты отведешь нас туда, где живут другие детеныши? Мы слышали про такое место – Приют Зимних Плавников, которое находится в огромной Борейской тундре. Мы думаем, оно может находиться на границе с островом Хладарра.$B$BГоспожа попечительница говорит, что кто-то смелый спас выводок детенышей в этом месте. Наверное, им теперь тоже одиноко, и им нужны друзья. Ты отведешь нас туда?','Отведите вашего подопечного Ру к Приюту Зимних Плавников. Не забудьте позвать сиротку, если его не окажется рядом, когда вы прибудете на место.','Это было весело! А мы еще сюда вернемся? Мы хотим еще раз встретиться с друзьями!','Ты отведёшь меня в Приют Зимних Плавноиков, $N?','Ру посетил Приют Зимних Плавников','Поговорите с оракулом-сиротой. Воспользуйтесь детской свистулькой, чтобы позвать вашего подопечного, если его нет рядом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Друзья детства!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Знаешь, в сиротском приюте так одиноко... Иногда нам хочется увидеть другие края, встретить новых друзей.$B$BМожет быть, ты отведешь нас туда, где живут другие детеныши? Мы слышали про такое место – Приют Зимних Плавников, которое находится в огромной Борейской тундре. Мы думаем, оно может находиться на границе с островом Хладарра.$B$BГоспожа попечительница говорит, что кто-то смелый спас выводок детенышей в этом месте. Наверное, им теперь тоже одиноко, и им нужны друзья. Ты отведешь нас туда?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отведите вашего подопечного Ру к Приюту Зимних Плавников. Не забудьте позвать сиротку, если его не окажется рядом, когда вы прибудете на место.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это было весело! А мы еще сюда вернемся? Мы хотим еще раз встретиться с друзьями!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты отведёшь меня в Приют Зимних Плавноиков, $N?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Ру посетил Приют Зимних Плавников',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с оракулом-сиротой. Воспользуйтесь детской свистулькой, чтобы позвать вашего подопечного, если его нет рядом.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (13951,'Друзья детства!','Отведите вашего подопечного Кекека на Поляну Снегопада. Не забудьте позвать сиротку, если его не окажется рядом, когда вы прибудете на место.','Кекеку понравились новые друзья. Кекек хочет еще как-нибудь встретиться с ними и поохотиться. Может быть, Кекек даже вместе с ними пойдет дразнить людей-моржей.','Ты отведёшь Кекека на Поляну Снегопада?','Кекек посетил Поляну Снегопада','Поговорите с волчером-сиротой. Воспользуйтесь детской свистулькой, чтобы позвать вашего подопечного, если его нет рядом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Друзья детства!',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отведите вашего подопечного Кекека на Поляну Снегопада. Не забудьте позвать сиротку, если его не окажется рядом, когда вы прибудете на место.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Кекеку понравились новые друзья. Кекек хочет еще как-нибудь встретиться с ними и поохотиться. Может быть, Кекек даже вместе с ними пойдет дразнить людей-моржей.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты отведёшь Кекека на Поляну Снегопада?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Кекек посетил Поляну Снегопада',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с волчером-сиротой. Воспользуйтесь детской свистулькой, чтобы позвать вашего подопечного, если его нет рядом.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (13952,'Благодарный покойник','Как приятно было навестить друзей и родных! Только, кажется, я немного перестаралась... и съела все, что они приготовили для меня! Даже крошки подмела!$B$BМогу ли я попросить тебя принести мне еще вкусного поминального хлеба? Я была бы очень благодарна!$B$BКажется, рецепт можно купить у Чепмана.','Принесите поминальный хлеб веселому духу человека на кладбище Штормграда.$B$BЧтобы увидеть дух, используйте оранжевые бархатцы.','Какой же все-таки вкусный этот поминальный хлеб!$B$BПрошу, прими вот это в знак моей благодарности... Веселого тебе праздника!','Вернитесь к веселому духу человека в Элвиннский лес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Благодарный покойник',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как приятно было навестить друзей и родных! Только, кажется, я немного перестаралась... и съела все, что они приготовили для меня! Даже крошки подмела!$B$BМогу ли я попросить тебя принести мне еще вкусного поминального хлеба? Я была бы очень благодарна!$B$BКажется, рецепт можно купить у Чепмана.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите поминальный хлеб веселому духу человека на кладбище Штормграда.$B$BЧтобы увидеть дух, используйте оранжевые бархатцы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Какой же все-таки вкусный этот поминальный хлеб!$B$BПрошу, прими вот это в знак моей благодарности... Веселого тебе праздника!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к веселому духу человека в Элвиннский лес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (13953,'Наги среди нас','Похоже, череп этого существа был расколот в битве с Аросом, и внешне оно точно подходит под описание наги. $B$BГоворят, что несмотря на свой чудовищный облик, наги некогда были ночными эльфами, попавшими под власть тайной магии королевы Азшары.$B$BКажется, именно они пытаются помешать вам заполучить рог древних.','Значит, наги объединились с культом Сумеречного Молота? Отлично, это то, что надо...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наги среди нас',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Похоже, череп этого существа был расколот в битве с Аросом, и внешне оно точно подходит под описание наги. $B$BГоворят, что несмотря на свой чудовищный облик, наги некогда были ночными эльфами, попавшими под власть тайной магии королевы Азшары.$B$BКажется, именно они пытаются помешать вам заполучить рог древних.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Значит, наги объединились с культом Сумеречного Молота? Отлично, это то, что надо...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (13954,'Королева драконов','Верховный оракул Су-сэй говорил, что Великие создали всех драконов, и даже их королеву. Мы хотим ее увидеть! Ты отведешь нас на вершину Храма Драконьего Покоя? Мы помним, что Су-сэй рассказывал про храм – он в самом центре Драконьего Погоста.$B$BМы очень-очень хотим увидеть королеву драконов! Наверное, она очень большая и красивая. Может быть, она поможет нам найти новых родителей.$B$BПойдем?','Как ты думаешь, она раньше видела оракула? Может быть, она тоже встретилась с нами впервые? Кажется, мы ей понравились, но мы не уверены. Она такая молчаливая. Но это все равно было здорово!','Поговорите с оракулом-сиротой. Воспользуйтесь детской свистулькой, чтобы позвать вашего подопечного, если его нет рядом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Королева драконов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Верховный оракул Су-сэй говорил, что Великие создали всех драконов, и даже их королеву. Мы хотим ее увидеть! Ты отведешь нас на вершину Храма Драконьего Покоя? Мы помним, что Су-сэй рассказывал про храм – он в самом центре Драконьего Погоста.$B$BМы очень-очень хотим увидеть королеву драконов! Наверное, она очень большая и красивая. Может быть, она поможет нам найти новых родителей.$B$BПойдем?',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Как ты думаешь, она раньше видела оракула? Может быть, она тоже встретилась с нами впервые? Кажется, мы ей понравились, но мы не уверены. Она такая молчаливая. Но это все равно было здорово!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с оракулом-сиротой. Воспользуйтесь детской свистулькой, чтобы позвать вашего подопечного, если его нет рядом.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13955,'Королева драконов','Кекеку всегда нравились драконы. Кекек даже хотел превратиться в дракона, но госпожа попечительница не разрешила. Но она сказала, что ты можешь отвести Кекека познакомиться с королевой драконов.$B$BКекек думает, что госпожа попечительница наконец-то предложила что-то хорошее. Ты отведешь Кекека в Храм Драконьего Покоя, в центре Драконьего Погоста? Давай встретимся с королевой драконов! Наверное, она очень большая, раз живет на самой вершине! Кекеку не терпится познакомиться с ней!','Кекек ожидал, что королева будет выглядеть иначе, но Кекек понимает, почему она такая. Если бы королева всегда была большим драконом, она бы раздавила посетителей! Но Кекек все равно хочет посмотреть на нее еще раз.','Мы сейчас пойдем к королеве драконов?','Поговорите с волчером-сиротой. Воспользуйтесь детской свистулькой, чтобы позвать вашего подопечного, если его нет рядом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Королева драконов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кекеку всегда нравились драконы. Кекек даже хотел превратиться в дракона, но госпожа попечительница не разрешила. Но она сказала, что ты можешь отвести Кекека познакомиться с королевой драконов.$B$BКекек думает, что госпожа попечительница наконец-то предложила что-то хорошее. Ты отведешь Кекека в Храм Драконьего Покоя, в центре Драконьего Погоста? Давай встретимся с королевой драконов! Наверное, она очень большая, раз живет на самой вершине! Кекеку не терпится познакомиться с ней!',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Кекек ожидал, что королева будет выглядеть иначе, но Кекек понимает, почему она такая. Если бы королева всегда была большим драконом, она бы раздавила посетителей! Но Кекек все равно хочет посмотреть на нее еще раз.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мы сейчас пойдем к королеве драконов?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с волчером-сиротой. Воспользуйтесь детской свистулькой, чтобы позвать вашего подопечного, если его нет рядом.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (13956,'Встреча с Великим','Верховный оракул Су-сэй всегда рассказывал нам про то, какие святилища строили Великие, и как мы дарили им блестяшки, но он сам никогда не видел Великих. Никто их не видел – но, может, ты знаешь, где их искать?$B$BСу-сэй говорит, что Великие построили врата и поставили их в центре южной части Шолазара. Су-сэй не знает, куда они ведут, но может быть, там мы найдем Великих! Отведи нас к вратам, $n, мы должны это выяснить!','Отведите вашего подопечного Ру к Этимидиану на Террасу Создателя. Не забудьте позвать сиротку, если его не окажется рядом, когда вы прибудете на место.','Мы увидели Великого! Жаль, что он спал, но мы тоже любим вздремнуть! Вот бы узнать о снах, которые видят Великие – а не только о блестяшках и святилищах...$B$BА мы сможем еще навестить его, когда он не будет отдыхать?','Вы знаете, как найти Этимидиана? Мы никогда не видели его раньше.','Ру посетил Этимидиана','Поговорите с оракулом-сиротой. Воспользуйтесь детской свистулькой, чтобы позвать вашего подопечного, если его нет рядом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Встреча с Великим',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Верховный оракул Су-сэй всегда рассказывал нам про то, какие святилища строили Великие, и как мы дарили им блестяшки, но он сам никогда не видел Великих. Никто их не видел – но, может, ты знаешь, где их искать?$B$BСу-сэй говорит, что Великие построили врата и поставили их в центре южной части Шолазара. Су-сэй не знает, куда они ведут, но может быть, там мы найдем Великих! Отведи нас к вратам, $n, мы должны это выяснить!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отведите вашего подопечного Ру к Этимидиану на Террасу Создателя. Не забудьте позвать сиротку, если его не окажется рядом, когда вы прибудете на место.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мы увидели Великого! Жаль, что он спал, но мы тоже любим вздремнуть! Вот бы узнать о снах, которые видят Великие – а не только о блестяшках и святилищах...$B$BА мы сможем еще навестить его, когда он не будет отдыхать?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы знаете, как найти Этимидиана? Мы никогда не видели его раньше.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Ру посетил Этимидиана',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с оракулом-сиротой. Воспользуйтесь детской свистулькой, чтобы позвать вашего подопечного, если его нет рядом.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (13957,'Великий Хеминг Эрнестуэй','Знаешь, с кем Кекек всегда мечтал познакомиться? С Хемингом Эрнестуэем, про которого рассказывал Старейшина Харкек. Говорят, он странствует по Шолазару и охотится на огромных зверей! Даже старейшины племени Бешеного Сердца почитают Хеминга Эрнестуэя как великого охотника.$B$BСтарейшина Харкек сказал Кекеку, что Лагерь Эрнестуэя находится в центре западной части Шолазара, на берегу реки, которая называется Разлом Морского Потока. Своди Кекека туда, чтобы он спросил у Хеминга, как стать таким великим охотником!','Отведите вашего подопечного Кекека познакомиться с Хемингом Эрнестуэем в Лагерь Эрнестуэя. Не забудьте позвать сиротку, если его не окажется рядом, когда вы прибудете на место.','Ты поможешь Кекеку прочитать книгу? Тогда Кекек сможет охотиться вместе с Хемингом Эрнестуэем!','Кекек познакомился с Хемингом Эрнестуэем','Поговорите с волчером-сиротой. Воспользуйтесь детской свистулькой, чтобы позвать вашего подопечного, если его нет рядом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Великий Хеминг Эрнестуэй',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Знаешь, с кем Кекек всегда мечтал познакомиться? С Хемингом Эрнестуэем, про которого рассказывал Старейшина Харкек. Говорят, он странствует по Шолазару и охотится на огромных зверей! Даже старейшины племени Бешеного Сердца почитают Хеминга Эрнестуэя как великого охотника.$B$BСтарейшина Харкек сказал Кекеку, что Лагерь Эрнестуэя находится в центре западной части Шолазара, на берегу реки, которая называется Разлом Морского Потока. Своди Кекека туда, чтобы он спросил у Хеминга, как стать таким великим охотником!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отведите вашего подопечного Кекека познакомиться с Хемингом Эрнестуэем в Лагерь Эрнестуэя. Не забудьте позвать сиротку, если его не окажется рядом, когда вы прибудете на место.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты поможешь Кекеку прочитать книгу? Тогда Кекек сможет охотиться вместе с Хемингом Эрнестуэем!',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Кекек познакомился с Хемингом Эрнестуэем',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с волчером-сиротой. Воспользуйтесь детской свистулькой, чтобы позвать вашего подопечного, если его нет рядом.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (13958,'Состояние критическое!','Враги отступают, и победа уже близка!$b$bОднако не стоит праздновать заранее, |3-6($c). Еще многое предстоит сделать до того, как Орда окончательно заявит свои права на Ясеневый лес.$b$bЯ слышал, что возле Приюта в Ночных Лесах снова идут бои, и ордынцы несут тяжелые потери. Судя по донесениям, среди них много раненых.$b$bОтнеси туда эти лекарственные препараты и передай Таггу. Расскажи ему о нашем нападении на Астранаар. Возможно, эта новость поднимет боевой дух наших воинов.','Гоггат поручил вам отнести боевой перевязочный набор Таггу в приют в Ночных Лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Состояние критическое!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Враги отступают, и победа уже близка!$b$bОднако не стоит праздновать заранее, |3-6($c). Еще многое предстоит сделать до того, как Орда окончательно заявит свои права на Ясеневый лес.$b$bЯ слышал, что возле Приюта в Ночных Лесах снова идут бои, и ордынцы несут тяжелые потери. Судя по донесениям, среди них много раненых.$b$bОтнеси туда эти лекарственные препараты и передай Таггу. Расскажи ему о нашем нападении на Астранаар. Возможно, эта новость поднимет боевой дух наших воинов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Гоггат поручил вам отнести боевой перевязочный набор Таггу в приют в Ночных Лесах.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13959,'Возвращение в приют','Нам было весело с тобой, $n. Жаль, что ты не можешь стать $gнашим папочкой:нашей мамочкой;, и нам пора возвращаться к попечительнице сирот Арии в Даларан.$B$BМожет быть, ты еще навестишь нас как-нибудь? Нам очень понравилось общаться с малышами Зимних Плавников и с королевой драконов. И никто нам не поверит, что мы видели одного из Великих!$B$BМы будем скучать по тебе, $n. Обещаем, мы будем тебе писать!','Отведите вашего подопечного обратно в приют Даларана, отдав детскую свистульку оракула попечительнице сирот Арии.','Похоже, малыш Ру отлично провел время на этой неделе. Я знаю, ему одиноко в нашем приюте, и мне всегда хотелось, чтобы он завел новых друзей. Спасибо, что согласились присмотреть за ним.','Нам обязательно возвращаться? Мы хотим остаться с тобой.','Вернитесь к попечительнице сирот Арии в Даларан.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение в приют',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нам было весело с тобой, $n. Жаль, что ты не можешь стать $gнашим папочкой:нашей мамочкой;, и нам пора возвращаться к попечительнице сирот Арии в Даларан.$B$BМожет быть, ты еще навестишь нас как-нибудь? Нам очень понравилось общаться с малышами Зимних Плавников и с королевой драконов. И никто нам не поверит, что мы видели одного из Великих!$B$BМы будем скучать по тебе, $n. Обещаем, мы будем тебе писать!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отведите вашего подопечного обратно в приют Даларана, отдав детскую свистульку оракула попечительнице сирот Арии.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Похоже, малыш Ру отлично провел время на этой неделе. Я знаю, ему одиноко в нашем приюте, и мне всегда хотелось, чтобы он завел новых друзей. Спасибо, что согласились присмотреть за ним.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Нам обязательно возвращаться? Мы хотим остаться с тобой.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к попечительнице сирот Арии в Даларан.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13960,'Возвращение в приют','Знаешь, а мы не так уж и плохо провели время вместе, $n. Ты $gпоказал:показала; Кекеку много всяких интересных мест. Кекек нашел новых друзей и сделал много всего такого, что не снилось другим щенкам.$B$BТеперь мы друзья – Кекек, ты, Хеминг Эрнестуэй и щенки Поляны Снегопада. Может быть, ты когда-нибудь принесешь Кекеку книгу про зеленые холмы? А Кекек обещает написать тебе как-нибудь и рассказать, как идут дела. Может быть, Кекек даже не будет больше дразнить длинноязыких детей.$B$BА теперь Кекеку пора возвращаться к попечительнице Арии, в фиолетовый город людей.','Отведите вашего подопечного обратно в приют Даларана, отдав детскую свистульку волчера попечительнице сирот Арии.','Спасибо, что ты $Gсогласился:согласилась; присмотреть за Кекеком. Знаю, он может доставить много хлопот, но все, что надо этому малышу, – это немного внимания и новые друзья. Не сомневаюсь, он еще долгое время будет рассказывать истории о ваших приключениях.','Кекек не хочет идти. Кекек хочет увидеть больше Нордскола с Джерси.','Вернитесь к попечительнице сирот Арии в Даларан.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение в приют',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Знаешь, а мы не так уж и плохо провели время вместе, $n. Ты $gпоказал:показала; Кекеку много всяких интересных мест. Кекек нашел новых друзей и сделал много всего такого, что не снилось другим щенкам.$B$BТеперь мы друзья – Кекек, ты, Хеминг Эрнестуэй и щенки Поляны Снегопада. Может быть, ты когда-нибудь принесешь Кекеку книгу про зеленые холмы? А Кекек обещает написать тебе как-нибудь и рассказать, как идут дела. Может быть, Кекек даже не будет больше дразнить длинноязыких детей.$B$BА теперь Кекеку пора возвращаться к попечительнице Арии, в фиолетовый город людей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отведите вашего подопечного обратно в приют Даларана, отдав детскую свистульку волчера попечительнице сирот Арии.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо, что ты $Gсогласился:согласилась; присмотреть за Кекеком. Знаю, он может доставить много хлопот, но все, что надо этому малышу, – это немного внимания и новые друзья. Не сомневаюсь, он еще долгое время будет рассказывать истории о ваших приключениях.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Кекек не хочет идти. Кекек хочет увидеть больше Нордскола с Джерси.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к попечительнице сирот Арии в Даларан.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (13961,'Допросить их','Следуя инстинкту, мы должны были бы разорвать нападающих на куски, но мудрость подсказывает иное. Нам необходимо допросить одного из этих погромщиков свинобразов и узнать все, что можно. Возьми эту сеть, $n, и поймай ею одного из них. Они атакуют нашу ферму с запада. Оглуши его и принеси сюда.','Используйте сеть Гроль\'дома для поимки погромщика из племени Иглогривых и притащите его Тогрик на ферму Гроль\'дома.','Ох. Мы же хотим допросить этого свинобраза, а не сделать из него свиные отбивные!','Не переусердствуй, допрашивая нашего пленника – для того, чтобы отвечать на вопросы, ему определенно нужна голова.','Пленник из племени Иглогривых доставлен','Поговорите с Тогрик на ферме Гроль\'дома в Северных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Допросить их',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Следуя инстинкту, мы должны были бы разорвать нападающих на куски, но мудрость подсказывает иное. Нам необходимо допросить одного из этих погромщиков свинобразов и узнать все, что можно. Возьми эту сеть, $n, и поймай ею одного из них. Они атакуют нашу ферму с запада. Оглуши его и принеси сюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте сеть Гроль\'дома для поимки погромщика из племени Иглогривых и притащите его Тогрик на ферму Гроль\'дома.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ох. Мы же хотим допросить этого свинобраза, а не сделать из него свиные отбивные!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Не переусердствуй, допрашивая нашего пленника – для того, чтобы отвечать на вопросы, ему определенно нужна голова.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Пленник из племени Иглогривых доставлен',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Тогрик на ферме Гроль\'дома в Северных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (13962,'Безвыходное положение','Хотя боевые перевязочные наборы помогут нам продолжать сражаться, мы все еще находимся в безвыходном положении.$b$bДриад легко победить, но их предводитель воскрешает павших воинов, едва их тела коснутся земли. Нам приходится сражаться с бесконечным потоком этих вредителей!$b$bСам Хранитель Одан прячется вот в том мутировавшем древе. Сколько мы ни пытались пробиться к нему, все впустую. Может быть, тебе удастся добраться до этого шамана, пока мы будем расчищать тебе путь от дриад?$b$bДля покорителя Астранаара это должно быть легкой прогулкой.','Тагг из приюта в Ночных Лесах просит вас убить хранителя Ордануса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Безвыходное положение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хотя боевые перевязочные наборы помогут нам продолжать сражаться, мы все еще находимся в безвыходном положении.$b$bДриад легко победить, но их предводитель воскрешает павших воинов, едва их тела коснутся земли. Нам приходится сражаться с бесконечным потоком этих вредителей!$b$bСам Хранитель Одан прячется вот в том мутировавшем древе. Сколько мы ни пытались пробиться к нему, все впустую. Может быть, тебе удастся добраться до этого шамана, пока мы будем расчищать тебе путь от дриад?$b$bДля покорителя Астранаара это должно быть легкой прогулкой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Тагг из приюта в Ночных Лесах просит вас убить хранителя Ордануса.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (13963,'Всеми правдами и неправдами','Думаю, если плеснуть ему в лицо ледяной водой, он придет в себя. Как ты думаешь, что он может рассказать нам?$b$bЯ запру его в загоне для животных, что находится сзади. Не думаю, что он будет долго оставаться в сознании. Узнай все, что сможешь о том, почему свинобразы нападают на наши фермы! Методы проведения допроса можешь выбирать самостоятельно.','Допросите пленника из племени Иглогривых. Если он без сознания, Тогрик может привести его в чувство.','Очень интересно. Похоже, наш приятель одновременно и преклоняется перед кем-то по имени Мучеклык, и до смерти боится его. Могущественный лидер может вдохновить своих солдат как на великие, так и на ужасные поступки… нам, оркам, это известно как нельзя лучше.$B$BНадо обратить внимание на этого Мучеклыка.','Поговорите с Тогрик на ферме Гроль\'дома в Северных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Всеми правдами и неправдами',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Думаю, если плеснуть ему в лицо ледяной водой, он придет в себя. Как ты думаешь, что он может рассказать нам?$b$bЯ запру его в загоне для животных, что находится сзади. Не думаю, что он будет долго оставаться в сознании. Узнай все, что сможешь о том, почему свинобразы нападают на наши фермы! Методы проведения допроса можешь выбирать самостоятельно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Допросите пленника из племени Иглогривых. Если он без сознания, Тогрик может привести его в чувство.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Очень интересно. Похоже, наш приятель одновременно и преклоняется перед кем-то по имени Мучеклык, и до смерти боится его. Могущественный лидер может вдохновить своих солдат как на великие, так и на ужасные поступки… нам, оркам, это известно как нельзя лучше.$B$BНадо обратить внимание на этого Мучеклыка.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Тогрик на ферме Гроль\'дома в Северных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (13964,'К башне Звездной Пыли') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','К башне Звездной Пыли',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13965,'Весточка от Эдьюнов','$n, если у тебя есть свободная минутка, я бы хотел попросить тебя о небольшой услуге.$B$BДавненько я не получал весточки от своих друзей, семьи Эдьюнов. Может быть, ты сбегаешь к ним и узнаешь, как они поживают?$B$BВечная благодарность тебе обеспечена. Их дом находится на маленьком островке земли к западу от святилища Эссины.','Поговорите с Бенджари Эдьюном в доме Эдьюнов, что в Ясеневом лесу.','Говоришь, тебя послал Фалдреас? Хороший он человек.$B$BНам и впрямь пригодится помощь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Весточка от Эдьюнов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, если у тебя есть свободная минутка, я бы хотел попросить тебя о небольшой услуге.$B$BДавненько я не получал весточки от своих друзей, семьи Эдьюнов. Может быть, ты сбегаешь к ним и узнаешь, как они поживают?$B$BВечная благодарность тебе обеспечена. Их дом находится на маленьком островке земли к западу от святилища Эссины.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Бенджари Эдьюном в доме Эдьюнов, что в Ясеневом лесу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Говоришь, тебя послал Фалдреас? Хороший он человек.$B$BНам и впрямь пригодится помощь.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (13966,'Подарок к Зимнему Покрову') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подарок к Зимнему Покрову',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (13967,'Проредить... стадо?','В южных районах численность фурболгов превышает все наши расчеты. К тому же, они гораздо более агрессивны, чем ожидалось.$b$bУчитывая, что мы разрываемся между охотой на эльфов и добычей бесценной древесины, только ты можешь помочь нам сократить популяцию фурболгов.$b$bПока что я занимаюсь теоретическими расчетами, но вскоре ты понадобишься мне для проведения экспериментов. А пока что займись нашей мохнатой проблемой и принеси Таркану уши фурболгов в доказательство ее решения.','Сенани Громовое Сердце в приюте Серебряного Ветра просит вас принести Таркану 15 ушей фурболгов – тотемистов из племени Гиблой Чащи и ведмедей из племени Гиблой Чащи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Проредить... стадо?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В южных районах численность фурболгов превышает все наши расчеты. К тому же, они гораздо более агрессивны, чем ожидалось.$b$bУчитывая, что мы разрываемся между охотой на эльфов и добычей бесценной древесины, только ты можешь помочь нам сократить популяцию фурболгов.$b$bПока что я занимаюсь теоретическими расчетами, но вскоре ты понадобишься мне для проведения экспериментов. А пока что займись нашей мохнатой проблемой и принеси Таркану уши фурболгов в доказательство ее решения.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сенани Громовое Сердце в приюте Серебряного Ветра просит вас принести Таркану 15 ушей фурболгов – тотемистов из племени Гиблой Чащи и ведмедей из племени Гиблой Чащи.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (13968,'Уничтожение Мучеклыка','Кажется, в результате волнений на юге этот "Мучеклык" собрал под своими знаменами всех беженцев племени Иглогривых. Под его руководством они стали несколько опаснее обычных разбойников. С такими типами не дискутируют, его надо уничтожить и точка.$b$bЕсли наш пленник не врет, ты найдешь Мучеклыка к юго-востоку отсюда в месте, которое называется Тернистым холмом. Исследуй те утесы, откуда ему лучше всего видна дорога. Убей его, $n, и угроза минует.','Уничтожьте Мучеклыка, предводителя Иглогривых.','Что, Мучеклык вел себя так, как я и предсказывала? Сразу попытался перерезать тебе глотку? Хорошо, что он уже покойник.$B$BСвинобраза из племени Иглогривых отстранили от руководства в Южных Степях, не хватало еще, чтобы твари типа него были у власти. Может быть, теперь у нас появится возможность договориться с выжившими... Хотя эти горячие головы могут одержать верх.','Вернитесь к Тогрик на ферму Гроль\'дома в Северных Степях.','Ужасный свинобраз Тернистого холма.','Мучеклык') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уничтожение Мучеклыка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кажется, в результате волнений на юге этот "Мучеклык" собрал под своими знаменами всех беженцев племени Иглогривых. Под его руководством они стали несколько опаснее обычных разбойников. С такими типами не дискутируют, его надо уничтожить и точка.$b$bЕсли наш пленник не врет, ты найдешь Мучеклыка к юго-востоку отсюда в месте, которое называется Тернистым холмом. Исследуй те утесы, откуда ему лучше всего видна дорога. Убей его, $n, и угроза минует.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте Мучеклыка, предводителя Иглогривых.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что, Мучеклык вел себя так, как я и предсказывала? Сразу попытался перерезать тебе глотку? Хорошо, что он уже покойник.$B$BСвинобраза из племени Иглогривых отстранили от руководства в Южных Степях, не хватало еще, чтобы твари типа него были у власти. Может быть, теперь у нас появится возможность договориться с выжившими... Хотя эти горячие головы могут одержать верх.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тогрик на ферму Гроль\'дома в Северных Степях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Ужасный свинобраз Тернистого холма.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Мучеклык',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13969,'Пропавший кодо Гроль\'дома','$GДруг:Подруга;, если ты путешествуешь на юг, к Тернистому Холму, то, может быть, сможешь и поискать одного из наших пропавших кодо? Не каждый караван из Дальней заставы доходит сюда. Эти головорезы Иглогривые угнали нагруженного кодо прошлым утром. Возможно, они уже убили его, но я надеюсь, что нет – наши стойла и без того опустели.','Найдите пропавшего кодо Гроль\'дома где-то на Тернистом холме.','Этот несчастный искалеченный кодо находится на краю гибели. Иглогривые даже не успели разгрузить его. Если его получится привести в чувство, вам, скорее всего, удастся спасти и товары.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пропавший кодо Гроль\'дома',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$GДруг:Подруга;, если ты путешествуешь на юг, к Тернистому Холму, то, может быть, сможешь и поискать одного из наших пропавших кодо? Не каждый караван из Дальней заставы доходит сюда. Эти головорезы Иглогривые угнали нагруженного кодо прошлым утром. Возможно, они уже убили его, но я надеюсь, что нет – наши стойла и без того опустели.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите пропавшего кодо Гроль\'дома где-то на Тернистом холме.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Этот несчастный искалеченный кодо находится на краю гибели. Иглогривые даже не успели разгрузить его. Если его получится привести в чувство, вам, скорее всего, удастся спасти и товары.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13970,'Животноводство','Кодо – выносливые создания. Немного еды, и этот великан придет в себя.$b$bИглогривые ограбили немало караванов, и, должно быть, награбили огромное количество зерна. Мешки с украденным зерном можно найти в их лагерях.','Соберите 5 мешков украденного зерна в лагерях Иглогривых на Тернистом холме.','Кодо очень прожорлив! С таким же успехом ты мог бы высыпать зерно из этих мешков в пропасть!$B$BЖивотное оживает на глазах.','Животное не может поднять голову, однако с мольбой смотрит на вас большими влажными глазами.','Отнесите зерно кодо Гроль\'дома на Тернистый холм, в Северных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Животноводство',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кодо – выносливые создания. Немного еды, и этот великан придет в себя.$b$bИглогривые ограбили немало караванов, и, должно быть, награбили огромное количество зерна. Мешки с украденным зерном можно найти в их лагерях.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 5 мешков украденного зерна в лагерях Иглогривых на Тернистом холме.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Кодо очень прожорлив! С таким же успехом ты мог бы высыпать зерно из этих мешков в пропасть!$B$BЖивотное оживает на глазах.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Животное не может поднять голову, однако с мольбой смотрит на вас большими влажными глазами.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите зерно кодо Гроль\'дома на Тернистый холм, в Северных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (13971,'Возвращение кодо','Огромное животное медленно поднимается, стряхивает грязь и пыль степей со своих вновь мощных лап и, повинуясь инстинкту, медленно направляется в сторону фермы Гроль\'дома.$b$bТебе стоит поговорить с Краналом Фиссом и убедиться, что кодо успешно добрался до фермы.','Поговорите с Краналом Фиссом с фермы Гроль\'дома, чтобы быть $gуверенным:уверенной;, что пропавший кодо благополучно прибыл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение кодо',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Огромное животное медленно поднимается, стряхивает грязь и пыль степей со своих вновь мощных лап и, повинуясь инстинкту, медленно направляется в сторону фермы Гроль\'дома.$b$bТебе стоит поговорить с Краналом Фиссом и убедиться, что кодо успешно добрался до фермы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Краналом Фиссом с фермы Гроль\'дома, чтобы быть $gуверенным:уверенной;, что пропавший кодо благополучно прибыл.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (13972,'Among Humans Again','Наконец-то! Похоже, снадобье Греннана подействовало на одного из диких!$B$BТеперь ты сможешь контролировать себя большую часть времени – только не давай гневу вырваться наружу.$B$BА сейчас с тобой хочет поговорить мэр Армстед. Гилнеас под осадой, и нам нужен каждый боец, способный держать оружие.','Speak to Gwen Armstead in Grimmburg.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Among Humans Again',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наконец-то! Похоже, снадобье Греннана подействовало на одного из диких!$B$BТеперь ты сможешь контролировать себя большую часть времени – только не давай гневу вырваться наружу.$B$BА сейчас с тобой хочет поговорить мэр Армстед. Гилнеас под осадой, и нам нужен каждый боец, способный держать оружие.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Speak to Gwen Armstead in Grimmburg.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13973,'Ополчение Гроль\'дома','Они появились из ниоткуда, |3-6($c)! Орда Иглогривых, до самого горизонта – одни спины, рыла и клыки. Мы были вынуждены вернуться на ферму, но они продолжали наступать.$b$bЛучшие из наших защитников пали на поле боя, и мы не можем найти фермера Ралтона. Мне нужно, чтобы ты $gзанял:заняла; наступательную позицию. Удерживай этих свинорылых на расстоянии, а я позабочусь о раненых до тех пор, пока не прибудет помощь.','Убейте 6 погромщиков из племени Иглогривых.','Вернитесь к Уне Волчий Коготь на ферму Гроль\'дома в Северных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ополчение Гроль\'дома',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Они появились из ниоткуда, |3-6($c)! Орда Иглогривых, до самого горизонта – одни спины, рыла и клыки. Мы были вынуждены вернуться на ферму, но они продолжали наступать.$b$bЛучшие из наших защитников пали на поле боя, и мы не можем найти фермера Ралтона. Мне нужно, чтобы ты $gзанял:заняла; наступательную позицию. Удерживай этих свинорылых на расстоянии, а я позабочусь о раненых до тех пор, пока не прибудет помощь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 6 погромщиков из племени Иглогривых.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Уне Волчий Коготь на ферму Гроль\'дома в Северных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13974,'Маленькая посылка Шкрыпа','Шкрып попросил вас отнести маленькую посылку Флузу в приют Серебряного Ветра.','Никак в лесу что-то сдохло – малыш Шкрып и впрямь изобрел что-то стоящее! Говоришь, от этой штуки весь Астранаар взлетел на воздух?$B$BНу, как видишь, нам не потребовалась помощь, чтобы захватить приют Серебряного Ветра... но эта штука такая маленькая, что может в ладошке поместиться! Если в ней действительно заключена такая мощь, я даже представить не могу, что мы можем с ней сделать!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Маленькая посылка Шкрыпа',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Шкрып попросил вас отнести маленькую посылку Флузу в приют Серебряного Ветра.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Никак в лесу что-то сдохло – малыш Шкрып и впрямь изобрел что-то стоящее! Говоришь, от этой штуки весь Астранаар взлетел на воздух?$B$BНу, как видишь, нам не потребовалась помощь, чтобы захватить приют Серебряного Ветра... но эта штука такая маленькая, что может в ладошке поместиться! Если в ней действительно заключена такая мощь, я даже представить не могу, что мы можем с ней сделать!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13976,'Три друга леса','Не хочешь совершить небольшое путешествие на юг? У меня там живут друзья, от которых давно уже не поступало вестей. Увы, я не могу покинуть свою семью и отправиться навестить их – $gсам:сама; видишь, что тут творится. То какие-то щупальца лезут из-под земли, то демоны бродят по округе.$B$BОдного из моих товарищей зовут Больюн, и он разбил свой лагерь к северо-западу от этого проклятого святилища Огненной Расщелины. Аленндаар и Харлон намеревались присоединиться к нему, так что все вместе они должны быть в безопасности. Но кто сейчас может за это поручиться?$B$BЗаранее спасибо, $n.','Поговорите с Больюном в его лагере, что в Ясеневом лесу.','Жрица, берегись! Калива, пленившая нас демонесса, где-то неподалеку!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Три друга леса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не хочешь совершить небольшое путешествие на юг? У меня там живут друзья, от которых давно уже не поступало вестей. Увы, я не могу покинуть свою семью и отправиться навестить их – $gсам:сама; видишь, что тут творится. То какие-то щупальца лезут из-под земли, то демоны бродят по округе.$B$BОдного из моих товарищей зовут Больюн, и он разбил свой лагерь к северо-западу от этого проклятого святилища Огненной Расщелины. Аленндаар и Харлон намеревались присоединиться к нему, так что все вместе они должны быть в безопасности. Но кто сейчас может за это поручиться?$B$BЗаранее спасибо, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Больюном в его лагере, что в Ясеневом лесу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Жрица, берегись! Калива, пленившая нас демонесса, где-то неподалеку!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (13977,'Массовое производство','Ха-ха! Ты это $gвидел:видела;?!$b$bНадо немедленно запустить это в производство!$b$bВот, отнеси эти остатки Джинксу. Он строит новый склад к западу отсюда.','Флуз просит вас отнести порошок "Пиф-паф!" Шкрыпа Джинксу в Производственный цех.','<Джинкс внимательно изучает принесенный вами порошок.>$B$BХмм... Мне понадобится немного времени, но мы определенно сможем использовать его при изготовлении бомбы.','Что там у вас, босс?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Массовое производство',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ха-ха! Ты это $gвидел:видела;?!$b$bНадо немедленно запустить это в производство!$b$bВот, отнеси эти остатки Джинксу. Он строит новый склад к западу отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Флуз просит вас отнести порошок "Пиф-паф!" Шкрыпа Джинксу в Производственный цех.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Джинкс внимательно изучает принесенный вами порошок.>$B$BХмм... Мне понадобится немного времени, но мы определенно сможем использовать его при изготовлении бомбы.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что там у вас, босс?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (13978,'Скрывающиеся во мгле','Мы построили стены и укрепления, чтобы защититься от врагов... но они все равно уже стоят на пороге.$B$BЧтобы сдержать первую волну нападавших, нашим ополченцам пришлось оставить город без защиты.$B$BУвы, мои худшие опасения подтвердились, и Гриммбург оказался под осадой орков.$B$BОни то ли ждут приказа наступать, то ли просто докладывают о наших передвижениях основным войскам. В любом случае – мы должны от них избавиться!$B$BЗнаю, ты $gодин:одна; из диких, но ты не $gчужой:чужая; в нашем городе. Дай врагу отпор, докажи, что в тебе осталось еще что-то человеческое.','Гвен Армстед из Гриммбурга просит вас убить 8 орков-разведчиков.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Скрывающиеся во мгле',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы построили стены и укрепления, чтобы защититься от врагов... но они все равно уже стоят на пороге.$B$BЧтобы сдержать первую волну нападавших, нашим ополченцам пришлось оставить город без защиты.$B$BУвы, мои худшие опасения подтвердились, и Гриммбург оказался под осадой орков.$B$BОни то ли ждут приказа наступать, то ли просто докладывают о наших передвижениях основным войскам. В любом случае – мы должны от них избавиться!$B$BЗнаю, ты $gодин:одна; из диких, но ты не $gчужой:чужая; в нашем городе. Дай врагу отпор, докажи, что в тебе осталось еще что-то человеческое.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Гвен Армстед из Гриммбурга просит вас убить 8 орков-разведчиков.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (13979,'Гоблинские эксперты','Прекратить бы хоть ненадолго эти проклятые гоблинские бомбардировки! Мы смогли бы нанести ответный удар и отвоевать приют Серебряного Ветра.$B$BЯ всегда думала, что гоблины либо слишком ленивы, чтобы создать что-то стоящее, либо столь энергичны, что подрываются на собственных изобретениях. К несчастью, этими вредителями руководит сам главный бумженер Бдыжень.$B$BПослушай, отправляйся-ка ты к Производственному цеху на западной стороне приюта и не возвращайся без головы главного бумженера!','Добудьте голову Бдыжня.','Так-то лучше. Теперь их механики снова предадутся лени, будут выпускать меньше бомб и устраивать меньше несчастных случаев.','Надеюсь, этот омерзительный, никчемный гоблин заткнулся навеки?','Вернитесь к охотнице Джалин в Башню Звездной Пыли, что в Ясеневом лесу.','Будем надеяться, его голова не взорвется!','Главный бумженер Бдыжень') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гоблинские эксперты',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прекратить бы хоть ненадолго эти проклятые гоблинские бомбардировки! Мы смогли бы нанести ответный удар и отвоевать приют Серебряного Ветра.$B$BЯ всегда думала, что гоблины либо слишком ленивы, чтобы создать что-то стоящее, либо столь энергичны, что подрываются на собственных изобретениях. К несчастью, этими вредителями руководит сам главный бумженер Бдыжень.$B$BПослушай, отправляйся-ка ты к Производственному цеху на западной стороне приюта и не возвращайся без головы главного бумженера!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте голову Бдыжня.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так-то лучше. Теперь их механики снова предадутся лени, будут выпускать меньше бомб и устраивать меньше несчастных случаев.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Надеюсь, этот омерзительный, никчемный гоблин заткнулся навеки?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к охотнице Джалин в Башню Звездной Пыли, что в Ясеневом лесу.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Будем надеяться, его голова не взорвется!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Главный бумженер Бдыжень',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (13980,'Они где-то рядом!','Они где-то рядом, |3-6($c), и они охотятся на нас.$b$bМоих людей находят мертвыми, и у меня нет ни тени сомнения в том, что тут замешаны длинноухие!$b$bПохоже, твои действия в Астранааре заставили их изрядно поволноваться, и они изо всех сил пытаются отсрочить свое окончательное поражение.$b$bВот, возьми эти очки – в них ты увидишь даже самых пронырливых эльфов. Не дай им подобраться со спины, пока мы не закончим со взрывчаткой.','Джинкс из Производственного цеха просит вас уничтожить 12 убийц из Ясеневого леса.','Молодец, друг.$B$BТеперь у нас хватит времени изготовить бомбу. Она уже почти готова!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Они где-то рядом!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Они где-то рядом, |3-6($c), и они охотятся на нас.$b$bМоих людей находят мертвыми, и у меня нет ни тени сомнения в том, что тут замешаны длинноухие!$b$bПохоже, твои действия в Астранааре заставили их изрядно поволноваться, и они изо всех сил пытаются отсрочить свое окончательное поражение.$b$bВот, возьми эти очки – в них ты увидишь даже самых пронырливых эльфов. Не дай им подобраться со спины, пока мы не закончим со взрывчаткой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Джинкс из Производственного цеха просит вас уничтожить 12 убийц из Ясеневого леса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Молодец, друг.$B$BТеперь у нас хватит времени изготовить бомбу. Она уже почти готова!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (13981,'Они готовят бомбу!','Что? Настолько большая?!$B$BОх, не нравится мне все это...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Они готовят бомбу!',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что? Настолько большая?!$B$BОх, не нравится мне все это...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (13982,'В цепях','Берегись, $n. Когда мы попали в плен к Каливе, то слышали, как она упоминала твое имя.$B$BТолько ее сердце может освободить нас из этих оков, но я боюсь, что она подстроила тебе ловушку.','Добудьте сердце Каливы.','Знаю, это мерзко, но если мы хотим избавиться от цепей Каливы, недостаточно убить нашу повелительницу.$B$BКаждый из нас должен проглотить кусок ее нечестивого сердца!','Если мы хотим обрести свободу, нам нужно сердце Каливы.','Вернитесь к Больюну в его лагерь, что в Ясеневом лесу.','Мерзкая демоница! Вырви ее сердце!','Калива') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В цепях',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Берегись, $n. Когда мы попали в плен к Каливе, то слышали, как она упоминала твое имя.$B$BТолько ее сердце может освободить нас из этих оков, но я боюсь, что она подстроила тебе ловушку.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте сердце Каливы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Знаю, это мерзко, но если мы хотим избавиться от цепей Каливы, недостаточно убить нашу повелительницу.$B$BКаждый из нас должен проглотить кусок ее нечестивого сердца!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если мы хотим обрести свободу, нам нужно сердце Каливы.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Больюну в его лагерь, что в Ясеневом лесу.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Мерзкая демоница! Вырви ее сердце!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Калива',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (13983,'Гвозди для собственного гроба','Джинкс просит вас собрать 3 бронзовых шестеренки, 3 куска медной обшивки и 5 зажимных болта.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гвозди для собственного гроба',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Джинкс просит вас собрать 3 бронзовых шестеренки, 3 куска медной обшивки и 5 зажимных болта.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (13984,'Tracking Our Every Move','Разведчики орков используют для слежки специально натасканных волков, и я не удивлюсь, если в их шайке есть и сам укротитель.$B$BТы принеси мне ошейники, которые носят эти волки, а мы пустим по их следу одну из наших гончих.','Gwen Armstead in Grimmburg wants you to bring her 3 Spiked Wolf Collars.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Tracking Our Every Move',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Разведчики орков используют для слежки специально натасканных волков, и я не удивлюсь, если в их шайке есть и сам укротитель.$B$BТы принеси мне ошейники, которые носят эти волки, а мы пустим по их следу одну из наших гончих.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Gwen Armstead in Grimmburg wants you to bring her 3 Spiked Wolf Collars.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (13985,'Очищение святилища','Убейте 12 демонов в святилище Огненной Расщелины.','Прекрасно, малыш. А теперь отойди в сторонку, я тут немного занят.','Поговорите с Высоким Баобобом в Святилище Эссины, что в Ясеневом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Очищение святилища',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 демонов в святилище Огненной Расщелины.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно, малыш. А теперь отойди в сторонку, я тут немного занят.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Высоким Баобобом в Святилище Эссины, что в Ясеневом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13986,'Раненый товарищ','Думаю, ты знаешь, какие жаркие бои ведутся в этих краях, |3-6($c). Нам пока удается удержать позиции, но не всегда удается избежать потерь.$b$bОдин из наших воинов, Апони Светлая Грива, была ранена в руку в одном из сражений. Ее тут же отправили назад в Громовой Утес для лечения, и она была так расстроена этим решением, что забыла здесь свой щит. Не затруднит ли тебя передать его ей вместе с нашими наилучшими пожеланиями? Мы все соскучились по ее улыбке.$b$bТы найдешь ее на Вершине Старейшин.','Отнесите побитый фамильный щит Апони Светлой Гриве на Вершину Старейшин Громового Утеса.','О мой щит! Я не собираюсь использовать его в ближайшее время, но спасибо. Я ненавижу, что бесполезно сижу здесь, когда я мог бы помогать на передовой, но с такой рукой...$B$BБереги себя там, хорошо?','О! Привет. Я не уверен, что мы раньше встречались, могу ли я что-нибудь для вас сделать?','Вернитесь к Апони Светлой Гриве в Мулгор.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Раненый товарищ',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Думаю, ты знаешь, какие жаркие бои ведутся в этих краях, |3-6($c). Нам пока удается удержать позиции, но не всегда удается избежать потерь.$b$bОдин из наших воинов, Апони Светлая Грива, была ранена в руку в одном из сражений. Ее тут же отправили назад в Громовой Утес для лечения, и она была так расстроена этим решением, что забыла здесь свой щит. Не затруднит ли тебя передать его ей вместе с нашими наилучшими пожеланиями? Мы все соскучились по ее улыбке.$b$bТы найдешь ее на Вершине Старейшин.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите побитый фамильный щит Апони Светлой Гриве на Вершину Старейшин Громового Утеса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О мой щит! Я не собираюсь использовать его в ближайшее время, но спасибо. Я ненавижу, что бесполезно сижу здесь, когда я мог бы помогать на передовой, но с такой рукой...$B$BБереги себя там, хорошо?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','О! Привет. Я не уверен, что мы раньше встречались, могу ли я что-нибудь для вас сделать?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Апони Светлой Гриве в Мулгор.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13987,'$n, мне крайне нужна твоя помощь! Я не могу вечно сдерживать наступление демонов. А если я потерплю поражение, Астранаар падет вместе со мной!$B$BУмоляю, помоги мне!','Убейте 30 вторгшихся демонов.','Еще немного – и мы будем спасены.','Поговорите с Высоким Баобобом в Святилище Эссины, что в Ясеневом лесу.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, мне крайне нужна твоя помощь! Я не могу вечно сдерживать наступление демонов. А если я потерплю поражение, Астранаар падет вместе со мной!$B$BУмоляю, помоги мне!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 30 вторгшихся демонов.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Еще немного – и мы будем спасены.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Высоким Баобобом в Святилище Эссины, что в Ясеневом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13988,'Растущая проблема','Внезапно появившаяся буйная растительность на прежде бесплодной земле... Мой приятель Джеррек уже видел такое где-то в Степях. Мне бы стоило взглянуть на это, но я не могу оставить свой пост.$b$bПоэтому, $n, я одолжу тебе свои "глаза". Этот орел мне служит с тех самых пор, как мне дали имя. Пожалуйста, возьми его с собой на Громовую Вершину, где ждет Джеррек, и мы во всем разберемся.$b$bЧтобы добраться туда, иди по дороге, ведущей от Перекрестка на восток. Поверни на юг у большого покрытого рисунками камня.','Возьмите орла Глаза Тонги на Громовую Вершину на юго-западе от Кабестана.','Я рад, что Тонга смог увидеть эти заросли своими глазами – масштабов разрушений не передать словами. Его тотем с тобой? Когда я закончу здесь, я верну его Тонге.','Тонга знает эти земли лучше любого из нас, и я знаю, как больно ему видеть ее разорванной на части.','Поговорите с Джерреком на Громовой вершине в Северных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Растущая проблема',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Внезапно появившаяся буйная растительность на прежде бесплодной земле... Мой приятель Джеррек уже видел такое где-то в Степях. Мне бы стоило взглянуть на это, но я не могу оставить свой пост.$b$bПоэтому, $n, я одолжу тебе свои "глаза". Этот орел мне служит с тех самых пор, как мне дали имя. Пожалуйста, возьми его с собой на Громовую Вершину, где ждет Джеррек, и мы во всем разберемся.$b$bЧтобы добраться туда, иди по дороге, ведущей от Перекрестка на восток. Поверни на юг у большого покрытого рисунками камня.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возьмите орла Глаза Тонги на Громовую Вершину на юго-западе от Кабестана.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я рад, что Тонга смог увидеть эти заросли своими глазами – масштабов разрушений не передать словами. Его тотем с тобой? Когда я закончу здесь, я верну его Тонге.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тонга знает эти земли лучше любого из нас, и я знаю, как больно ему видеть ее разорванной на части.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Джерреком на Громовой вершине в Северных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (13989,'Король Гиблой Чащи','Мне нет дела до того, кто ты $gтакой:такая;, |3-6($r). Меня заботит только судьба фурболгов.$B$BОтнеси это знамя Кровавого Клыка кратчайшим путем в деревню Зеленой Лапы и воткни древко в тотемный холм. Обитатели расценят это как знак агрессии и постараются уничтожить знамя, но ты оберегай его, пока на защиту чести племени не выйдет сам вождь Мургут. И тогда ты убьешь предателя!$B$BЗапомни, друг, тебе надо беречь силы и готовиться к долгому сражению.','Поместите знамя Кровавого Клыка на тотемном кургане Гиблой Чащи и не позвольте фурболгам уничтожить его, пока не появится вождь. Одолейте вождя Мургута.','Хорошо. Мургут продал свое племя Орде, присоединившись к ним после того, как они захватили приют Серебряного Ветра.$B$BХотя он оправдывает свои действия попыткой спасти свой народ, в действительности он обрек его на позорное рабство. Теперь же он получил по заслугам!$B$BВпрочем, хватит о нем. Я хочу рассказать тебе еще об одном предателе, чья сила может сделать твой жезл еще более могущественным.','Вернитесь к Кролгу в его хижину, что в Ясеневом лесу.','Убей вождя фурболгов!','Вождь Мургут') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Король Гиблой Чащи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне нет дела до того, кто ты $gтакой:такая;, |3-6($r). Меня заботит только судьба фурболгов.$B$BОтнеси это знамя Кровавого Клыка кратчайшим путем в деревню Зеленой Лапы и воткни древко в тотемный холм. Обитатели расценят это как знак агрессии и постараются уничтожить знамя, но ты оберегай его, пока на защиту чести племени не выйдет сам вождь Мургут. И тогда ты убьешь предателя!$B$BЗапомни, друг, тебе надо беречь силы и готовиться к долгому сражению.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поместите знамя Кровавого Клыка на тотемном кургане Гиблой Чащи и не позвольте фурболгам уничтожить его, пока не появится вождь. Одолейте вождя Мургута.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо. Мургут продал свое племя Орде, присоединившись к ним после того, как они захватили приют Серебряного Ветра.$B$BХотя он оправдывает свои действия попыткой спасти свой народ, в действительности он обрек его на позорное рабство. Теперь же он получил по заслугам!$B$BВпрочем, хватит о нем. Я хочу рассказать тебе еще об одном предателе, чья сила может сделать твой жезл еще более могущественным.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кролгу в его хижину, что в Ясеневом лесу.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Убей вождя фурболгов!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Вождь Мургут',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (13990,'Рекламный код Upper Deck – верховой цыпленок') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рекламный код Upper Deck – верховой цыпленок',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (13991,'Похищенное серебро','Ну что же, $n. Я признаю, что для тебя найдется место в великой Орде. Ты $gпродемонстрировал:продемонстрировала; силу, хитрость, инициативу... И даже Тхорк недавно упоминал твое имя, а нас не так-то легко впечатлить. Хорошо.$b$bТеперь можно приступить к настоящей работе. Недавно был похищен груз серебра, предназначавшегося в уплату стражникам Перекрестка. Расследованием руководит Газрог из Кабестана. Поговори с ним!$b$bПросто следуй дорогой, ведущей отсюда на восток и попадешь на побережье.','Поговорите с Газрогом у входа в Кабестан.','Я, конечно, надеялся на отряд пехоты… но если ты заслужил доверие Сергры, я полагаю, тебя будет более, чем достаточно. Давай я объясню, что здесь происходит.','Поговорите с Газрогом у входа в Кабестан в Северных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Похищенное серебро',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну что же, $n. Я признаю, что для тебя найдется место в великой Орде. Ты $gпродемонстрировал:продемонстрировала; силу, хитрость, инициативу... И даже Тхорк недавно упоминал твое имя, а нас не так-то легко впечатлить. Хорошо.$b$bТеперь можно приступить к настоящей работе. Недавно был похищен груз серебра, предназначавшегося в уплату стражникам Перекрестка. Расследованием руководит Газрог из Кабестана. Поговори с ним!$b$bПросто следуй дорогой, ведущей отсюда на восток и попадешь на побережье.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Газрогом у входа в Кабестан.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я, конечно, надеялся на отряд пехоты… но если ты заслужил доверие Сергры, я полагаю, тебя будет более, чем достаточно. Давай я объясню, что здесь происходит.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Газрогом у входа в Кабестан в Северных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13992,'Небольшая диверсия','Убейте 8 кентавров из племени Колкар.','Вернитесь к Та\'джари к Забытым прудам в Северных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Небольшая диверсия',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 кентавров из племени Колкар.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Та\'джари к Забытым прудам в Северных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (13993,'Ты – бомба!','Ну что ж, $n, у нас все готово.$b$bЯ запрограммировал дорогу в Когтистые горы, так что тебе останется только побеспокоиться о самой бомбе.$b$bЕсли какой-нибудь недоброжелатель попробует сунуться к тебе, используй циркулярные пилы, а если врагам удастся подобраться слишком близко, оглуши их коротким замыканием.$b$bЗапомни, у тебя есть только один шанс починить бомбу, если она окажется серьезно повреждена.$b$bНу, собирайся с духом и возвращайся ко мне.$b$bУдачи!','Джинкс просит вас направить модифицированный крошшер к Когтистым горам и поговорить с Саурбозом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ты – бомба!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну что ж, $n, у нас все готово.$b$bЯ запрограммировал дорогу в Когтистые горы, так что тебе останется только побеспокоиться о самой бомбе.$b$bЕсли какой-нибудь недоброжелатель попробует сунуться к тебе, используй циркулярные пилы, а если врагам удастся подобраться слишком близко, оглуши их коротким замыканием.$b$bЗапомни, у тебя есть только один шанс починить бомбу, если она окажется серьезно повреждена.$b$bНу, собирайся с духом и возвращайся ко мне.$b$bУдачи!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Джинкс просит вас направить модифицированный крошшер к Когтистым горам и поговорить с Саурбозом.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (13994,'(DEPRECATED)','Послушай, $n, ты $gдолжен:должна; в точности выполнить указания инквизитора.$B$BОн утверждает, что Орда напала на Гилнеас. Если это правда – то мы должны как можно скорее предупредить клан Волчьего Сердца, пока еще не поздно.$B$BКроме того, Балвус Волчье Сердце с меня шкуру живьем снимет, если узнает, что я оставил тебя умирать на складах Седогрива.$B$BБеги, $n. Спасай свою шкуру... и предупреди наших братьев из Черной дубравы, когда придет время.','Speak to Inquisitor Blackwell in Grimmburg.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','(DEPRECATED)',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Послушай, $n, ты $gдолжен:должна; в точности выполнить указания инквизитора.$B$BОн утверждает, что Орда напала на Гилнеас. Если это правда – то мы должны как можно скорее предупредить клан Волчьего Сердца, пока еще не поздно.$B$BКроме того, Балвус Волчье Сердце с меня шкуру живьем снимет, если узнает, что я оставил тебя умирать на складах Седогрива.$B$BБеги, $n. Спасай свою шкуру... и предупреди наших братьев из Черной дубравы, когда придет время.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Speak to Inquisitor Blackwell in Grimmburg.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (13995,'Гора короля кентавров','Нас прислали сюда, чтобы мы отследили перемещения кентавров из племени Колкар, но после недели наблюдений за тем, как эти грязные твари носятся по оазису, у меня руки чешутся познакомить мой топор с их шеями. Что скажешь, |3-6($c)? Поможешь мне?$b$bМожет, это заставит показаться Курака – самого сильного из них.','Защитите Горгала Злошрама, когда он нападет на кентавров. Помогите ему убить Курака.','И зачем ты так распалил Горгала? Впрочем, я не могу пожаловаться на результаты. Посмотрим, что эти зверюги будут делать без Курака.$B$BНадо еще подождать, хоть Горгалу это и не понравится.','Кентаврам нанесен урон','Поговорите с Шузой в Застывшем оазисе в Северных Степях.','Его присутствие здесь – оскорбление чувств. Даже у его блох водятся блохи.','Курак') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гора короля кентавров',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нас прислали сюда, чтобы мы отследили перемещения кентавров из племени Колкар, но после недели наблюдений за тем, как эти грязные твари носятся по оазису, у меня руки чешутся познакомить мой топор с их шеями. Что скажешь, |3-6($c)? Поможешь мне?$b$bМожет, это заставит показаться Курака – самого сильного из них.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Защитите Горгала Злошрама, когда он нападет на кентавров. Помогите ему убить Курака.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','И зачем ты так распалил Горгала? Впрочем, я не могу пожаловаться на результаты. Посмотрим, что эти зверюги будут делать без Курака.$B$BНадо еще подождать, хоть Горгалу это и не понравится.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Кентаврам нанесен урон',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Шузой в Застывшем оазисе в Северных Степях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Его присутствие здесь – оскорбление чувств. Даже у его блох водятся блохи.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Курак',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (13996,'Can You Get This Quest While I\'m In Combat?','Your mission, if you are able to read this while I\'m in combat, is to kill 5 of these insufferable little kobolds that are constantly keeping me in combat.$B$BJust the fact that you are reading this is a huge WIN! Isn\'t Dan awesome?!!','ELM Daze Target on Designer Island has asked you to kill 5 ELM Attackers for Dan and Great Justice!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Can You Get This Quest While I\'m In Combat?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Your mission, if you are able to read this while I\'m in combat, is to kill 5 of these insufferable little kobolds that are constantly keeping me in combat.$B$BJust the fact that you are reading this is a huge WIN! Isn\'t Dan awesome?!!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','ELM Daze Target on Designer Island has asked you to kill 5 ELM Attackers for Dan and Great Justice!',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (13997,'If You\'re Reading This While I\'m In Combat...','Dan is the most awesome programmer in the world... the World of Warcraft!$B$BIsn\'t it weird that you used to not be able to talk with me at all while I was fighting? No longer, my friend, now that Dan has made significant improvements to one of my creature flags!$B$BCelebrate with me by snuffing out the lives of these awful creatures that perpetually have me in combat.','ELM Daze Target wants you to kill 5 ELM Attackers for Dan and Great Justice!','Вернитесь к ELM Daze Target на Остров Дизайнера.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','If You\'re Reading This While I\'m In Combat...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Dan is the most awesome programmer in the world... the World of Warcraft!$B$BIsn\'t it weird that you used to not be able to talk with me at all while I was fighting? No longer, my friend, now that Dan has made significant improvements to one of my creature flags!$B$BCelebrate with me by snuffing out the lives of these awful creatures that perpetually have me in combat.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','ELM Daze Target wants you to kill 5 ELM Attackers for Dan and Great Justice!',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ELM Daze Target на Остров Дизайнера.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (13998,'Веруем в грибы','Посадите грибные культуры возле Застывшего оазиса и понаблюдайте за результатом.','Грибная культура посажена','Сообщите о результатах аптекарю Хелбриму в Перекрестке в Северных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Веруем в грибы',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Посадите грибные культуры возле Застывшего оазиса и понаблюдайте за результатом.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Грибная культура посажена',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Сообщите о результатах аптекарю Хелбриму в Перекрестке в Северных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13999,'Кто кого дурит?','Подумай, $n, какие возможности! Постоянно развивающаяся служба доставки любых ядовитых грибов. Мои компаньоны в Подгороде непременно захотят узнать об этом.$b$bВот мои заметки и дополнительные образцы. Если поторопимся, успеем к следующему кораблю в Восточные королевства. Отправляйся по дороге, которая проходит к востоку отсюда, она приведет тебя в Кабестан. Найди таверну "Сломанный Киль" в южной части города, а в ней мою приятельницу Сашию и доставь ей это.','Доставьте изыскания Хелбрима Сашие в Кабестан в Северных Степях.','Тсс! Давай записку. За тобой не следили?','Кто ты? Тебя послал Хелбрим? Веди себя тихо.','Доставьте изыскания Хелбрима Сашие в Кабестан в Северных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кто кого дурит?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Подумай, $n, какие возможности! Постоянно развивающаяся служба доставки любых ядовитых грибов. Мои компаньоны в Подгороде непременно захотят узнать об этом.$b$bВот мои заметки и дополнительные образцы. Если поторопимся, успеем к следующему кораблю в Восточные королевства. Отправляйся по дороге, которая проходит к востоку отсюда, она приведет тебя в Кабестан. Найди таверну "Сломанный Киль" в южной части города, а в ней мою приятельницу Сашию и доставь ей это.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте изыскания Хелбрима Сашие в Кабестан в Северных Степях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тсс! Давай записку. За тобой не следили?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Кто ты? Тебя послал Хелбрим? Веди себя тихо.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доставьте изыскания Хелбрима Сашие в Кабестан в Северных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (14000,'Hunt or Be Hunted','Думаю, этого хватит, чтобы выследить укротителя волков.$B$BОтнеси ошейники ловчему Расселу. Я уже попросил его выделить для этой цели одну из лучших гончих.','Bring the Spiked Wolf Collars to Huntsman Rusell in Grimmburg.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Hunt or Be Hunted',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Думаю, этого хватит, чтобы выследить укротителя волков.$B$BОтнеси ошейники ловчему Расселу. Я уже попросил его выделить для этой цели одну из лучших гончих.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Bring the Spiked Wolf Collars to Huntsman Rusell in Grimmburg.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (14001,'Гоблинские спасательные шлюпки','Ой, прости, $n, я думал, ты того!$B$BТут черти что творится, Орда погрызлась с Альянсом! Уж не знаю, кто это начал, но мы умудрились заплыть в самое пекло.$B$BНашим братьям и сестрам нужна помощь.$B$B<Гоблин тычет пальцем в сторону спасательных капсул, плавающих вокруг.>$B$BЯ немного посижу и соберусь с силами, а ты пока помоги потерпевшим! Возьми мои термогидратные ласты, с ними ты сможешь плавать быстрее.$B$BИ передай Хамми, что я скоро приплыву, чтоб она не волновалась.','Спасите 6 уцелевших гоблинов.','Отправляйтесь к Хамми Кофельнагель на Берег Кораблекрушения на Затерянных островах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гоблинские спасательные шлюпки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ой, прости, $n, я думал, ты того!$B$BТут черти что творится, Орда погрызлась с Альянсом! Уж не знаю, кто это начал, но мы умудрились заплыть в самое пекло.$B$BНашим братьям и сестрам нужна помощь.$B$B<Гоблин тычет пальцем в сторону спасательных капсул, плавающих вокруг.>$B$BЯ немного посижу и соберусь с силами, а ты пока помоги потерпевшим! Возьми мои термогидратные ласты, с ними ты сможешь плавать быстрее.$B$BИ передай Хамми, что я скоро приплыву, чтоб она не волновалась.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Спасите 6 уцелевших гоблинов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отправляйтесь к Хамми Кофельнагель на Берег Кораблекрушения на Затерянных островах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (14002,'A Job for a Bloodhound','Отнеси ошейники в дальние клетки и дай их обнюхать любой гончей – они знают, что надо делать.$B$BКак только найдешь то, что ищешь, приготовься к жестокой схватке. И не забудь доложить мэру, что дело сделано.','Use the Spiked Worg Collars near the cages behind Huntsman Russell. Follow the Gilnean Bloodhound to find and kill the leader of the Orc Scouts.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','A Job for a Bloodhound',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Отнеси ошейники в дальние клетки и дай их обнюхать любой гончей – они знают, что надо делать.$B$BКак только найдешь то, что ищешь, приготовься к жестокой схватке. И не забудь доложить мэру, что дело сделано.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Use the Spiked Worg Collars near the cages behind Huntsman Russell. Follow the Gilnean Bloodhound to find and kill the leader of the Orc Scouts.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (14003,'Починка самофланжа','Так-так, он работает не так, как надо. Кажется, я его сломал.$b$bВпрочем, нет оснований для беспокойства. Окажи мне услугу, сбегай к Браку тут в лагере. Он быстро разберется с этой штуковиной!','Отнесите сломанный самофланж к Браку Трубореву в лагере.','Пароклапан прислал самофланж? Ну-ка, дай взглянуть на эту штуку!$B$BОкей, мы починим его. Дай-ка мне вон тот здоровый молоток...','Доставьте сломанный самофланж Браку Трубореву в лагерь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Починка самофланжа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Так-так, он работает не так, как надо. Кажется, я его сломал.$b$bВпрочем, нет оснований для беспокойства. Окажи мне услугу, сбегай к Браку тут в лагере. Он быстро разберется с этой штуковиной!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите сломанный самофланж к Браку Трубореву в лагере.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Пароклапан прислал самофланж? Ну-ка, дай взглянуть на эту штуку!$B$BОкей, мы починим его. Дай-ка мне вон тот здоровый молоток...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доставьте сломанный самофланж Браку Трубореву в лагерь.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14004,'Вернуться к создателю самофланжа','Увы, у меня ничего не вышло. Структурная целостность самофланжа крайне низка. Я могу добавить пару циферблатов и рычаг-другой, чтобы попытаться исправить это, но... от этого может стать только хуже.$B$BСмотри, что я нашла, когда заблокировала стравливающий клапан и сняла крышку с корпуса дифференциала: личное клеймо "Начальник Медноклин". Отнеси это обратно Пароклапану и скажи, что этот Медноклин – настоящий гений. Когда закончишь здесь, просто скажи мне, и я отправлю тебя обратно при помощи телепорта Брака.','Что сказала Венаки? Медноклин? НАЧАЛЬНИК Медноклин? О, нет, должно быть, это будет непросто.','Это мой самофланж? Я даже не узнаю его.','Доставьте переконструированные обломки самофланжа Пароклапану в Лагерь Котельника, что в Северных Степях. Чтобы попасть к нему, поговорите с Венаки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вернуться к создателю самофланжа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Увы, у меня ничего не вышло. Структурная целостность самофланжа крайне низка. Я могу добавить пару циферблатов и рычаг-другой, чтобы попытаться исправить это, но... от этого может стать только хуже.$B$BСмотри, что я нашла, когда заблокировала стравливающий клапан и сняла крышку с корпуса дифференциала: личное клеймо "Начальник Медноклин". Отнеси это обратно Пароклапану и скажи, что этот Медноклин – настоящий гений. Когда закончишь здесь, просто скажи мне, и я отправлю тебя обратно при помощи телепорта Брака.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что сказала Венаки? Медноклин? НАЧАЛЬНИК Медноклин? О, нет, должно быть, это будет непросто.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Это мой самофланж? Я даже не узнаю его.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доставьте переконструированные обломки самофланжа Пароклапану в Лагерь Котельника, что в Северных Степях. Чтобы попасть к нему, поговорите с Венаки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertargetname_loc8`) VALUES (14005,'Месть Элуны','Используйте данные Тариндреллой силы, чтобы пробраться к источнику порчи и уничтожить его.','Вернитесь к Тариндрелле к Прудам Арлитриэна.','Корень Порока') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Месть Элуны',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте данные Тариндреллой силы, чтобы пробраться к источнику порчи и уничтожить его.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тариндрелле к Прудам Арлитриэна.',`completedtext_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Корень Порока',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (14006,'Руководство по эксплуатации','Соберите руководство по эксплуатации самофланжа.','Отнесите руководство Пароклапану в Лагерь Котельника, что в Северных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Руководство по эксплуатации',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите руководство по эксплуатации самофланжа.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите руководство Пароклапану в Лагерь Котельника, что в Северных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14014,'Верните наши вещи!','Наши бомбы и инструменты! Подлые макаки выкрали их под покровом ночи и унесли на восток!$B$BПожалуйста, доберись до обезьяних владений и конфискуй то, что принадлежит нам по праву. Я верю, ты справишься, $n. Без инструментов мы застрянем на этом острове навеки!','Добудьте 8 ящиков инструментов.','<Хамми вздыхает с облегчением при виде найденных вами инструментов и бомб.>$B$BЯ уж думала, мы обречены. Но теперь у нас есть все необходимое, чтобы выбраться с этого острова!','Обезьяны с гранатами?! Это конец света!!!','Отправляйтесь к Хамми Кофельнагель на Берег Кораблекрушения на Затерянных островах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Верните наши вещи!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наши бомбы и инструменты! Подлые макаки выкрали их под покровом ночи и унесли на восток!$B$BПожалуйста, доберись до обезьяних владений и конфискуй то, что принадлежит нам по праву. Я верю, ты справишься, $n. Без инструментов мы застрянем на этом острове навеки!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 8 ящиков инструментов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Хамми вздыхает с облегчением при виде найденных вами инструментов и бомб.>$B$BЯ уж думала, мы обречены. Но теперь у нас есть все необходимое, чтобы выбраться с этого острова!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Обезьяны с гранатами?! Это конец света!!!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отправляйтесь к Хамми Кофельнагель на Берег Кораблекрушения на Затерянных островах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (14015,'Incomplete Cartography','Вы разворачиваете свиток и обнаруживаете довольно подробную карту Гилнеаса, всего с одной ошибкой – все пространство между побережьем и гриммбургскими скалами не прорисовано.$B$BТакже на карте изображены стрелки, вероятн обозначающие планы Орды по продвижению вглубь Гилнеаса. Несомненно, мэру Армстед пригодится этот документ.','Bring the Soaked Map to Mayor Armstead in Grimmburg.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Incomplete Cartography',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы разворачиваете свиток и обнаруживаете довольно подробную карту Гилнеаса, всего с одной ошибкой – все пространство между побережьем и гриммбургскими скалами не прорисовано.$B$BТакже на карте изображены стрелки, вероятн обозначающие планы Орды по продвижению вглубь Гилнеаса. Несомненно, мэру Армстед пригодится этот документ.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Bring the Soaked Map to Mayor Armstead in Grimmburg.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (14016,'Проклятие Черного рыцаря','После твоей победы я было распорядилась убрать останки Черного рыцаря с Ристалища, но исповедница Пейлтресс настояла на том, чтобы похоронить его по всем правилам. И с тех пор на нашем кладбище происходят странные вещи, которые отпугивают жителей, желающих воздать почести павшим героям.$B$BТы не $gмог:могла; бы лично посетить кладбище и выяснить, что там творится? Оно находится на восточном краю Ристалища.','Рыцарь Райдалла из Серебряного павильона на Ристалище Серебряного Турнира просит вас осмотреть могилу Черного рыцаря.','<Рыцарь Райдалла хмурится.>$B$BДумаешь, это было запланировано? Пожалуй, это не имеет значения, но мне кажется, что нас обвели вокруг пальца. Мы должны вмешаться!','Осмотреть могилу Черного рыцаря.','Вернитесь к рыцарю Райдалле на Ристалище Серебряного турнира, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Проклятие Черного рыцаря',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','После твоей победы я было распорядилась убрать останки Черного рыцаря с Ристалища, но исповедница Пейлтресс настояла на том, чтобы похоронить его по всем правилам. И с тех пор на нашем кладбище происходят странные вещи, которые отпугивают жителей, желающих воздать почести павшим героям.$B$BТы не $gмог:могла; бы лично посетить кладбище и выяснить, что там творится? Оно находится на восточном краю Ристалища.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Рыцарь Райдалла из Серебряного павильона на Ристалище Серебряного Турнира просит вас осмотреть могилу Черного рыцаря.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Рыцарь Райдалла хмурится.>$B$BДумаешь, это было запланировано? Пожалуй, это не имеет значения, но мне кажется, что нас обвели вокруг пальца. Мы должны вмешаться!',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Осмотреть могилу Черного рыцаря.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к рыцарю Райдалле на Ристалище Серебряного турнира, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14017,'Судьба Черного рыцаря','Говоришь, его тело забрали служители культа Проклятых? Я знаю только одно место, куда они могли бы его отнести: это Застава Вестника Смерти, что на западе от Ристалища.$B$BМы должны остановить их во что бы то ни стало. Это только подтверждает правдивость мрачных слухов... Среди них совершает свои темные обряды бесславный доктор Колер. Найди алтарь, возвышающийся над лагерем служителей культа, убей доктора и принеси мне доказательства его грязных деяний. Любой ценой замедли их работу!','Перехватите приказы доктора Колера на Заставе Вестника Смерти, а затем вернитесь к рыцарю Райдалле в Серебряный павильон на Ристалище Серебряного Турнира.','Тебе удалось выяснить, что они делают с останками Черного рыцаря?','Вернитесь к рыцарю Райдалле на Ристалище Серебряного турнира, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Судьба Черного рыцаря',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Говоришь, его тело забрали служители культа Проклятых? Я знаю только одно место, куда они могли бы его отнести: это Застава Вестника Смерти, что на западе от Ристалища.$B$BМы должны остановить их во что бы то ни стало. Это только подтверждает правдивость мрачных слухов... Среди них совершает свои темные обряды бесславный доктор Колер. Найди алтарь, возвышающийся над лагерем служителей культа, убей доктора и принеси мне доказательства его грязных деяний. Любой ценой замедли их работу!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Перехватите приказы доктора Колера на Заставе Вестника Смерти, а затем вернитесь к рыцарю Райдалле в Серебряный павильон на Ристалище Серебряного Турнира.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось выяснить, что они делают с останками Черного рыцаря?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к рыцарю Райдалле на Ристалище Серебряного турнира, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (14018,'Тот, кто будет прощен','Это голос самой богини воззвал к тебе из колодца, $n! Лекарство для Релары находится к востоку от Башни в Ночных лесах. Там ты найдешь того, кто поддался скверне.$B$BАврий Дурной Толк – именно тот, кто жаждет прощения и очищения. Если ты поможешь ему, то спасешь и мою дочь.','Поговорите с Аврием Дурным Толком у башни в Ночных лесах, что в Ясеневом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тот, кто будет прощен',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это голос самой богини воззвал к тебе из колодца, $n! Лекарство для Релары находится к востоку от Башни в Ночных лесах. Там ты найдешь того, кто поддался скверне.$B$BАврий Дурной Толк – именно тот, кто жаждет прощения и очищения. Если ты поможешь ему, то спасешь и мою дочь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Аврием Дурным Толком у башни в Ночных лесах, что в Ясеневом лесу.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (14019,'Связка спелых бананчиков','У нас тут вот какое дело. В джунглях на востоке водится множество обезьян. Так эти макаки стащили всю нашу взрывчатку и теперь швыряются ею куда ни попадя.$B$BИногда – прямо в нас!$B$BПо моей просьбе Физз Лихтер начинил эти бананы селитрой. Ни одна обезьяна не устоит перед связкой спелых бананчиков!$B$BТебе всего-то и нужно, что пойти в джунгли и покормить обезьянок.','Накормите 10 обезьян с гранатой, бросив им бананы с селитрой.','Отведали спелых бананов и взлетели на воздух?! Хотелось бы на это посмотреть!$B$BДумаю, надо сходить самолично покормить зверюшек!','Вернитесь к Бамму Взрыбомму на Берег Кораблекрушения на Затерянных островах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Связка спелых бананчиков',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У нас тут вот какое дело. В джунглях на востоке водится множество обезьян. Так эти макаки стащили всю нашу взрывчатку и теперь швыряются ею куда ни попадя.$B$BИногда – прямо в нас!$B$BПо моей просьбе Физз Лихтер начинил эти бананы селитрой. Ни одна обезьяна не устоит перед связкой спелых бананчиков!$B$BТебе всего-то и нужно, что пойти в джунгли и покормить обезьянок.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Накормите 10 обезьян с гранатой, бросив им бананы с селитрой.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отведали спелых бананов и взлетели на воздух?! Хотелось бы на это посмотреть!$B$BДумаю, надо сходить самолично покормить зверюшек!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бамму Взрыбомму на Берег Кораблекрушения на Затерянных островах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (14020,'Проклятие','Проклятие застало всех нас врасплох. Все было в порядке, пока однажды целые деревни не начали превращаться в стаи воющих воргенов. По приказу лорда Седогрива мы не покладая рук пытались найти лекарство от этой напасти, но удача от нас отвернулась.$B$BОднако нам все же удалось обнаружить нечто обнадеживающее. Оказалось, что очищенная вытяжка из черной мандрагоры способна облегчить большинство симптомов Проклятия.$B$BНо беда не ходит в одиночку. После нападения орков связь с нашим городом прервалась, и мне неоткуда больше достать сырье для снадобья. Пожалуйста, если тебе встретится по пути черная мандрагора, собери ее и принеси мне, чтобы я смог приготовить еще немного вытяжки.','Креннан Аранас из Гриммбурга просит вас раздобыть 8 черных мандрагор.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Проклятие',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Проклятие застало всех нас врасплох. Все было в порядке, пока однажды целые деревни не начали превращаться в стаи воющих воргенов. По приказу лорда Седогрива мы не покладая рук пытались найти лекарство от этой напасти, но удача от нас отвернулась.$B$BОднако нам все же удалось обнаружить нечто обнадеживающее. Оказалось, что очищенная вытяжка из черной мандрагоры способна облегчить большинство симптомов Проклятия.$B$BНо беда не ходит в одиночку. После нападения орков связь с нашим городом прервалась, и мне неоткуда больше достать сырье для снадобья. Пожалуйста, если тебе встретится по пути черная мандрагора, собери ее и принеси мне, чтобы я смог приготовить еще немного вытяжки.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Креннан Аранас из Гриммбурга просит вас раздобыть 8 черных мандрагор.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (14021,'Глубинная суть проблемы','Хитроумные обезьяны-рудокопы!$B$BВ этой пещере их полно, и они добывают руду... кирками! Это совсем не похоже на них, и я уверен, что все дело в каджа\'мите!$B$BНикто из моих горняков не вернулся... У меня почти не осталось работников! $n, ты же видишь, ситуация безвыходная.$B$B<Штейгер понижает голос.>$B$BЭти парни и в подметки не годятся моей старой команде. Какие были тролли! Какие тролли! Сейчас таких уже не делают!$B$BНо, может, ты проводишь моего последнего шахтера в пещеру и защитишь его от обезьян? Пойми, нам очень нужен каджа\'мит!','Проведите испуганного шахтера по Каджа\'митовой пещере.','Мы напали на жилу!!!$B$BТак что там с этим пигмеем-знахарем? Он мертв? Потому что если он мертв, то я обозначу это место, как свое. Впрочем… все равно по гоблинским законам весь каджа\'мит принадлежит нам!','Вернитесь к штейгеру Промокаху к входу в Каджа\'митовую пещеру на Затерянных островах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Глубинная суть проблемы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хитроумные обезьяны-рудокопы!$B$BВ этой пещере их полно, и они добывают руду... кирками! Это совсем не похоже на них, и я уверен, что все дело в каджа\'мите!$B$BНикто из моих горняков не вернулся... У меня почти не осталось работников! $n, ты же видишь, ситуация безвыходная.$B$B<Штейгер понижает голос.>$B$BЭти парни и в подметки не годятся моей старой команде. Какие были тролли! Какие тролли! Сейчас таких уже не делают!$B$BНо, может, ты проводишь моего последнего шахтера в пещеру и защитишь его от обезьян? Пойми, нам очень нужен каджа\'мит!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проведите испуганного шахтера по Каджа\'митовой пещере.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мы напали на жилу!!!$B$BТак что там с этим пигмеем-знахарем? Он мертв? Потому что если он мертв, то я обозначу это место, как свое. Впрочем… все равно по гоблинским законам весь каджа\'мит принадлежит нам!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к штейгеру Промокаху к входу в Каджа\'митовую пещеру на Затерянных островах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (14022,'Пиршество странников','А ты не хочешь присоединиться к Пиршеству странников, $n? Когда-то в этот день мы вспоминали о былых путешествиях, рассказывали друзьям о том, как нам улыбнулась удача, и приглашали их разделить с нами пищу. Многие до сих пор соблюдают эту традицию.$B$BТы тоже можешь отметить Пиршество странников – в честь этого праздника в каждой столице накрыты пиршественные столы, ломящиеся от изобилия яств. $B$BА если ты хочешь узнать, как готовятся эти изысканные кушанья, найди Грегори Табора – он стоит рядом с вратами Штормграда.','Поговорите с Грегори Табором – он стоит рядом с вратами Штормграда.','Если хочешь научиться готовить особые блюда Пиршества странников – я могу тебе помочь. Главное – знать основы кулинарии!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пиршество странников',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А ты не хочешь присоединиться к Пиршеству странников, $n? Когда-то в этот день мы вспоминали о былых путешествиях, рассказывали друзьям о том, как нам улыбнулась удача, и приглашали их разделить с нами пищу. Многие до сих пор соблюдают эту традицию.$B$BТы тоже можешь отметить Пиршество странников – в честь этого праздника в каждой столице накрыты пиршественные столы, ломящиеся от изобилия яств. $B$BА если ты хочешь узнать, как готовятся эти изысканные кушанья, найди Грегори Табора – он стоит рядом с вратами Штормграда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Грегори Табором – он стоит рядом с вратами Штормграда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Если хочешь научиться готовить особые блюда Пиршества странников – я могу тебе помочь. Главное – знать основы кулинарии!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14023,'Пряная хлебная запеканка','Наша пряная хлебная запеканка – главное блюдо праздничного стола Пиршества странников. Этот рецепт недаром включен в пиршественную поваренную книгу как самое популярное блюдо Штормграда.$B$BЕсли ты умеешь готовить, навести торговцев Пиршества странников и купи пиршественную поваренную книгу, а также все необходимые ингредиенты для приготовления праздничного угощения. А если ты не знаешь, как обращаться с кастрюлями и сковородками – самое время научиться!$B$BКак только приготовишь хлебную запеканку, принеси ее Джасперу Муру, он стоит возле праздничных столов.','Приготовьте 5 порций пряной хлебной запеканки и отнесите ее Джасперу Муру, который стоит возле праздничных столов у ворот Штормграда.','Превосходно! Это то, что надо. Конечно, нелегко накрыть такой огромный стол, но праздник того стоит.','Пряная хлебная запеканка никогда не будет лишней – это одно из самых любимых праздничных блюд.','Вернитесь к Джасперу Муру в Златоземье, что в Элвиннском лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пряная хлебная запеканка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наша пряная хлебная запеканка – главное блюдо праздничного стола Пиршества странников. Этот рецепт недаром включен в пиршественную поваренную книгу как самое популярное блюдо Штормграда.$B$BЕсли ты умеешь готовить, навести торговцев Пиршества странников и купи пиршественную поваренную книгу, а также все необходимые ингредиенты для приготовления праздничного угощения. А если ты не знаешь, как обращаться с кастрюлями и сковородками – самое время научиться!$B$BКак только приготовишь хлебную запеканку, принеси ее Джасперу Муру, он стоит возле праздничных столов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Приготовьте 5 порций пряной хлебной запеканки и отнесите ее Джасперу Муру, который стоит возле праздничных столов у ворот Штормграда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Превосходно! Это то, что надо. Конечно, нелегко накрыть такой огромный стол, но праздник того стоит.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Пряная хлебная запеканка никогда не будет лишней – это одно из самых любимых праздничных блюд.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джасперу Муру в Златоземье, что в Элвиннском лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14024,'Тыквенный пирог','Ах, как ароматно пахнет приготовленная тобой пряная хлебная запеканка! Но праздничный стол Пиршества странников невозможно представить без огромного тыквенного пирога. Этот десерт очень популярен в Штормграде, поскольку готовится из спелых элвиннских тыкв, которые растут только в этих краях.$B$BЕсли ты еще не знаешь, как готовить тыквенный пирог, загляни в свою пиршественную поваренную книгу.$B$BКстати, тебя не затруднит испечь несколько кусочков и отнести их Эдварду Уинслоу? Он накрывает столы рядом со Стальгорном, и тыквенный пирог наверняка у него уже кончился.','Испеките 5 кусков тыквенного пирога и принесите их Эдварду Уинслоу, который стоит возле праздничных столов Стальгорна.','Тыквенный пирог идет нарасхват – первый раз вижу, чтобы дворфам так нравилось что-то, приготовленное из овощей.','Тыквенный пирог? Его-то нам и не хватало!','Вернитесь к Эдварду Уинслоу ко Вратам Стальгорна, что в Дун Мороге.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тыквенный пирог',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ах, как ароматно пахнет приготовленная тобой пряная хлебная запеканка! Но праздничный стол Пиршества странников невозможно представить без огромного тыквенного пирога. Этот десерт очень популярен в Штормграде, поскольку готовится из спелых элвиннских тыкв, которые растут только в этих краях.$B$BЕсли ты еще не знаешь, как готовить тыквенный пирог, загляни в свою пиршественную поваренную книгу.$B$BКстати, тебя не затруднит испечь несколько кусочков и отнести их Эдварду Уинслоу? Он накрывает столы рядом со Стальгорном, и тыквенный пирог наверняка у него уже кончился.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Испеките 5 кусков тыквенного пирога и принесите их Эдварду Уинслоу, который стоит возле праздничных столов Стальгорна.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тыквенный пирог идет нарасхват – первый раз вижу, чтобы дворфам так нравилось что-то, приготовленное из овощей.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тыквенный пирог? Его-то нам и не хватало!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Эдварду Уинслоу ко Вратам Стальгорна, что в Дун Мороге.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (14025,'На линии фронта') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На линии фронта',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (14026,'Шумные прощания') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Шумные прощания',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (14027,'Лицом к лицу','Моим людям очень нужна помощь, $n. Мы из всех сил стараемся дать оркам отпор, но нас слишком мало.$B$BНо если ты уничтожишь несколько нападавших, это склонит чашу весов в нашу пользу. Посмотрим, способны ли члены твоего клана убивать врагов, или ярости вашей хватает только на охоту за нашими овцами.','Лейтенант Райт поручил вам убить 10 орков-захватчиков.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лицом к лицу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Моим людям очень нужна помощь, $n. Мы из всех сил стараемся дать оркам отпор, но нас слишком мало.$B$BНо если ты уничтожишь несколько нападавших, это склонит чашу весов в нашу пользу. Посмотрим, способны ли члены твоего клана убивать врагов, или ярости вашей хватает только на охоту за нашими овцами.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Лейтенант Райт поручил вам убить 10 орков-захватчиков.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14028,'Клюквенный соус','Если ты еще не $gпробовал:пробовала; клюквенный соус – ты не знаешь вкус жизни. Он делается из свежайшей клюквы, которая растет в Болотине. Если хочешь попробовать его приготовить – купи все, что тебе надо, у торговца Пиршества странников.$B$BА рецепт должен быть в твоей пиршественной поваренной книге.$B$BЕсли у тебя есть свободная минутка – может быть, ты поможешь Джасперу Муру приготовить очередную порцию соуса для штормградского стола? Я как раз собирался обменять пару порций на испеченный тобой пирог.','Приготовьте 5 порций клюквенного соуса и отнесите ее Джасперу Муру, который стоит возле праздничных столов у ворот Штормграда.','Наконец-то, клюквенный соус прибыл! Ты не поверишь, как быстро он кончается.','Мне кажется, или я чувствую запах клюквенного соуса?','Вернитесь к Джасперу Муру в Златоземье, что в Элвиннском лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Клюквенный соус',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если ты еще не $gпробовал:пробовала; клюквенный соус – ты не знаешь вкус жизни. Он делается из свежайшей клюквы, которая растет в Болотине. Если хочешь попробовать его приготовить – купи все, что тебе надо, у торговца Пиршества странников.$B$BА рецепт должен быть в твоей пиршественной поваренной книге.$B$BЕсли у тебя есть свободная минутка – может быть, ты поможешь Джасперу Муру приготовить очередную порцию соуса для штормградского стола? Я как раз собирался обменять пару порций на испеченный тобой пирог.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Приготовьте 5 порций клюквенного соуса и отнесите ее Джасперу Муру, который стоит возле праздничных столов у ворот Штормграда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Наконец-то, клюквенный соус прибыл! Ты не поверишь, как быстро он кончается.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мне кажется, или я чувствую запах клюквенного соуса?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джасперу Муру в Златоземье, что в Элвиннском лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (14029,'Прорвать осаду') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прорвать осаду',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14030,'Голодающие Дарнаса','Спасибо за клюквенный соус! Нам еще так много надо приготовить – я просто не успеваю за всем следить. Но самое главное – я должен заботиться о том, чтобы Исаак Аллертон из Дарнаса не испытывал недостатка в провизии, а у него как раз кончились все угощения. Я могу рассчитывать на твою помощь? Было бы неплохо, если бы ты $gприготовил:приготовила; несколько порций хлебной запеканки и тыквенного пирога. Все нужные ингредиенты есть у продавца.$B$BОтнеси готовую еду к праздничным столам, которые накрыты рядом со входом в Дарнас, прямо под Террасой Воинов.','Приготовьте 5 порций хлебной запеканки и отнесите ее Исааку Аллертону, который стоит у входа в Дарнас.','Спасибо за доставку – я уже начал волноваться.$B$BСлушай, пока ты здесь, может, займешься приготовлением засахаренного батата?','Ты хочешь поучаствовать в Пиршестве странников?','Вернитесь к Исааку Аллертону на Террасу Воинов, что в Дарнасе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Голодающие Дарнаса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Спасибо за клюквенный соус! Нам еще так много надо приготовить – я просто не успеваю за всем следить. Но самое главное – я должен заботиться о том, чтобы Исаак Аллертон из Дарнаса не испытывал недостатка в провизии, а у него как раз кончились все угощения. Я могу рассчитывать на твою помощь? Было бы неплохо, если бы ты $gприготовил:приготовила; несколько порций хлебной запеканки и тыквенного пирога. Все нужные ингредиенты есть у продавца.$B$BОтнеси готовую еду к праздничным столам, которые накрыты рядом со входом в Дарнас, прямо под Террасой Воинов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Приготовьте 5 порций хлебной запеканки и отнесите ее Исааку Аллертону, который стоит у входа в Дарнас.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо за доставку – я уже начал волноваться.$B$BСлушай, пока ты здесь, может, займешься приготовлением засахаренного батата?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты хочешь поучаствовать в Пиршестве странников?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Исааку Аллертону на Террасу Воинов, что в Дарнасе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (14031,'Фотоохота','Эй, $n, тут по всей пещере какие-то странные рисунки и другие артефакты.$b$bМожет, ты воспользуешься своей фотокамерой ТКК с ультравспышкой и сделаешь снимки в означенных местах? Кроме того, сфотографируй алтарь, который находится в глубине пещеры.$b$bУверен, Хамми это будет интересно.','Фотокамерой ТКК с ультравспышкой сделайте снимки алтаря пигмеев и наскальных рисунков в трех пещерах.','Отправляйтесь к Хамми Кофельнагель на Берег Кораблекрушения на Затерянных островах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Фотоохота',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эй, $n, тут по всей пещере какие-то странные рисунки и другие артефакты.$b$bМожет, ты воспользуешься своей фотокамерой ТКК с ультравспышкой и сделаешь снимки в означенных местах? Кроме того, сфотографируй алтарь, который находится в глубине пещеры.$b$bУверен, Хамми это будет интересно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Фотокамерой ТКК с ультравспышкой сделайте снимки алтаря пигмеев и наскальных рисунков в трех пещерах.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отправляйтесь к Хамми Кофельнагель на Берег Кораблекрушения на Затерянных островах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (14032,'Kobold Camp Cleanup [Programming Test]','Первое твое задание, $n, – это зачистка. Северные леса наводнили кобольды. Ступай туда и уничтожь столько кобольдов-вредителей, сколько сможешь. Сократи их число, чтобы в один прекрасный день мы смогли вытеснить их из Североземья.','Уничтожьте 10 кобольдов-вредителей. Вернитесь к маршалу Макбрайду.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Kobold Camp Cleanup [Programming Test]',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Первое твое задание, $n, – это зачистка. Северные леса наводнили кобольды. Ступай туда и уничтожь столько кобольдов-вредителей, сколько сможешь. Сократи их число, чтобы в один прекрасный день мы смогли вытеснить их из Североземья.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 10 кобольдов-вредителей. Вернитесь к маршалу Макбрайду.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (14033,'Засахаренный батат','Раз уж ты здесь, помоги нам пополнить запасы тельдрассильской сладкой картошки – она идет на изготовление самого вкусного засахаренного батата, который ты когда-либо $gпробовал:пробовала;.$B$BЕсли не веришь – приготовь $gсам:сама;, этот рецепт есть в твоей пиршественной поваренной книге. А если после этого у тебя останется немного угощения – можешь поделиться с Грегори Табором, который накрывает столы возле Штормграда. Он их просто обожает, хотя его послушать – так можно подумать, у него каждое блюдо самое любимое.','Приготовьте 5 порций засахаренного батата и отнесите их Грегори Табору, который стоит у ворот Штормграда.','А, засахаренный батат! Это мое любимое лакомство! Не иначе, Исаак проговорился?','Вернитесь к Грегори Табору в Златоземье, что в Элвиннском лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Засахаренный батат',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Раз уж ты здесь, помоги нам пополнить запасы тельдрассильской сладкой картошки – она идет на изготовление самого вкусного засахаренного батата, который ты когда-либо $gпробовал:пробовала;.$B$BЕсли не веришь – приготовь $gсам:сама;, этот рецепт есть в твоей пиршественной поваренной книге. А если после этого у тебя останется немного угощения – можешь поделиться с Грегори Табором, который накрывает столы возле Штормграда. Он их просто обожает, хотя его послушать – так можно подумать, у него каждое блюдо самое любимое.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Приготовьте 5 порций засахаренного батата и отнесите их Грегори Табору, который стоит у ворот Штормграда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, засахаренный батат! Это мое любимое лакомство! Не иначе, Исаак проговорился?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Грегори Табору в Златоземье, что в Элвиннском лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (14034,'Припугнуть Фута','Благодаря последнему конфликту между Альянсом и Ордой я получал прибыль, пока контр-адмирал Хартли не навестил МОЙ порт и не засунул нос своего корабля в мои дела. Он разыскивал корабли Орды и лишал их возможности посещать нейтральный порт.$b$bЯ не собираюсь позволять ему загребать мои деньги своими пухлыми ручонками! Раздобудьте мне план его флагманского судна. Главный инженер Хартли пьянствует в таверне "Сломанный киль" вон там на холме...','Добудьте чертеж корабля у главного инженера Фута в таверне "Сломанный киль", что в Кабестане.','Ага, то что надо! Значит, его флагманский корабль называется "Непобедимый", да?$B$BПосмотрим, как отправить эту посудину на дно моря.','Принесите план судна Газлоу в Кабестан в Северных Степях.','Он держит тот план, что нам нужен.','Главный инженер Фут') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Припугнуть Фута',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Благодаря последнему конфликту между Альянсом и Ордой я получал прибыль, пока контр-адмирал Хартли не навестил МОЙ порт и не засунул нос своего корабля в мои дела. Он разыскивал корабли Орды и лишал их возможности посещать нейтральный порт.$b$bЯ не собираюсь позволять ему загребать мои деньги своими пухлыми ручонками! Раздобудьте мне план его флагманского судна. Главный инженер Хартли пьянствует в таверне "Сломанный киль" вон там на холме...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте чертеж корабля у главного инженера Фута в таверне "Сломанный киль", что в Кабестане.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ага, то что надо! Значит, его флагманский корабль называется "Непобедимый", да?$B$BПосмотрим, как отправить эту посудину на дно моря.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите план судна Газлоу в Кабестан в Северных Степях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Он держит тот план, что нам нужен.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Главный инженер Фут',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (14035,'Запеченная индейка','Какой же праздник Пиршества странников без главного украшения – и я вовсе не имею в виду бутафорский рог изобилия. Я говорю про огромную жареную индейку, царицу праздничного стола!$B$BПо-моему, в твоей пиршественной поваренной книге есть подходящий рецепт. Почему бы тебе не убить несколько диких индеек и не приготовить их к празднику? Индейки водятся повсюду в Элвиннском лесу, так что тебе не составит труда отыскать добычу.$B$BКак только закончишь готовить, принеси жареных индеек Исааку Аллертону к вратам Дарнаса, хорошо?','Приготовьте 5 запеченных индеек и отнесите их Исааку Аллертону к вратам Дарнаса.','Вернитесь к Исааку Аллертону на Террасу Воинов, что в Дарнасе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Запеченная индейка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Какой же праздник Пиршества странников без главного украшения – и я вовсе не имею в виду бутафорский рог изобилия. Я говорю про огромную жареную индейку, царицу праздничного стола!$B$BПо-моему, в твоей пиршественной поваренной книге есть подходящий рецепт. Почему бы тебе не убить несколько диких индеек и не приготовить их к празднику? Индейки водятся повсюду в Элвиннском лесу, так что тебе не составит труда отыскать добычу.$B$BКак только закончишь готовить, принеси жареных индеек Исааку Аллертону к вратам Дарнаса, хорошо?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Приготовьте 5 запеченных индеек и отнесите их Исааку Аллертону к вратам Дарнаса.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Исааку Аллертону на Террасу Воинов, что в Дарнасе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (14036,'Пиршество странников','Ты $gпришел:пришла; сюда, чтобы отпраздновать с нами Пиршество странников? Когда-то в этот день мы вспоминали о былых путешествиях, рассказывали друзьям о том, как нам улыбнулась удача, и приглашали их разделить с нами пищу. Многие до сих пор соблюдают эту традицию.$B$BТы тоже можешь отметить Пиршество странников – в честь этого праздника в каждой столице накрыты пиршественные столы, ломящиеся от изобилия яств. $B$BА если ты хочешь узнать, как готовятся эти изысканные кушанья, найди Майлса Стендиша во внутреннем дворе Подгорода.','Поговорите с Майлсом Стендишом во внутреннем дворе Подгорода.','Если хочешь научиться готовить особые блюда Пиршества странников – я могу тебе помочь. Главное – знать основы кулинарии!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пиршество странников',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gпришел:пришла; сюда, чтобы отпраздновать с нами Пиршество странников? Когда-то в этот день мы вспоминали о былых путешествиях, рассказывали друзьям о том, как нам улыбнулась удача, и приглашали их разделить с нами пищу. Многие до сих пор соблюдают эту традицию.$B$BТы тоже можешь отметить Пиршество странников – в честь этого праздника в каждой столице накрыты пиршественные столы, ломящиеся от изобилия яств. $B$BА если ты хочешь узнать, как готовятся эти изысканные кушанья, найди Майлса Стендиша во внутреннем дворе Подгорода.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Майлсом Стендишом во внутреннем дворе Подгорода.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Если хочешь научиться готовить особые блюда Пиршества странников – я могу тебе помочь. Главное – знать основы кулинарии!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14037,'Пряная хлебная запеканка','Наша пряная хлебная запеканка – главное блюдо праздничного стола Пиршества странников. Этот рецепт был придуман еще во времена расцвета Лордерона, и дошел до наших дней без изменений.$B$BЕсли ты умеешь готовить, навести торговцев Пиршества странников и приобрети пиршественную поваренную книгу, а также все необходимые ингредиенты для приготовления праздничного угощения. А если ты не знаешь, как обращаться с кастрюлями и сковородками – самое время научиться!$B$BКак только приготовишь хлебную запеканку, принеси ее Вильяму Маллинсу, который стоит возле праздничных столов.','Приготовьте 5 порций пряной хлебной запеканки и отнесите ее Вильяму Маллинсу, который стоит возле праздничных столов во внутреннем дворе Подгорода.','На столах явно недостает пряной хлебной запеканки.','Вернитесь к Вильяму Маллинсу на Руины Лордерона, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пряная хлебная запеканка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наша пряная хлебная запеканка – главное блюдо праздничного стола Пиршества странников. Этот рецепт был придуман еще во времена расцвета Лордерона, и дошел до наших дней без изменений.$B$BЕсли ты умеешь готовить, навести торговцев Пиршества странников и приобрети пиршественную поваренную книгу, а также все необходимые ингредиенты для приготовления праздничного угощения. А если ты не знаешь, как обращаться с кастрюлями и сковородками – самое время научиться!$B$BКак только приготовишь хлебную запеканку, принеси ее Вильяму Маллинсу, который стоит возле праздничных столов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Приготовьте 5 порций пряной хлебной запеканки и отнесите ее Вильяму Маллинсу, который стоит возле праздничных столов во внутреннем дворе Подгорода.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','На столах явно недостает пряной хлебной запеканки.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Вильяму Маллинсу на Руины Лордерона, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (14038,'Кто не с нами, тот против нас','<Газлоу расстилает план на столе и после некоторого размышления тыкает пальцем в место в кормовой части судна, ниже ватерлинии>.$b$bЗдесь! Здесь, где коленвал подходит к винтовому механизму, обшивка тоньше всего. И это прямо рядом с крюйт-камерой!$b$b$n, я, конечно же, не буду иметь никакого отношения к тому, что $gкакой-то предприимчивый:какая-то предприимчивая:c; |3-6($c) из Орды прикрепит мину к этой части судна. Даже если я сам и дал $gему:ей; эту мину. И заплатил $gему:ей;. Корабль стоит на якоре к юго-востоку отсюда... иди туда!$b$bПотом свяжись со мной по радио при помощи этого краденого ГНМ-передатчика.','Прикрепите магнитную мину в самой тонкой части корпуса "Непобедимого".','Поговорите с Газлоу в Кабестане в Северных Степях.','Голос Газлоу слышен в ГНМ-передатчике…','Газлоу') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кто не с нами, тот против нас',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Газлоу расстилает план на столе и после некоторого размышления тыкает пальцем в место в кормовой части судна, ниже ватерлинии>.$b$bЗдесь! Здесь, где коленвал подходит к винтовому механизму, обшивка тоньше всего. И это прямо рядом с крюйт-камерой!$b$b$n, я, конечно же, не буду иметь никакого отношения к тому, что $gкакой-то предприимчивый:какая-то предприимчивая:c; |3-6($c) из Орды прикрепит мину к этой части судна. Даже если я сам и дал $gему:ей; эту мину. И заплатил $gему:ей;. Корабль стоит на якоре к юго-востоку отсюда... иди туда!$b$bПотом свяжись со мной по радио при помощи этого краденого ГНМ-передатчика.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Прикрепите магнитную мину в самой тонкой части корпуса "Непобедимого".',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Газлоу в Кабестане в Северных Степях.',`completedtext_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Голос Газлоу слышен в ГНМ-передатчике…',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Газлоу',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (14039,'Дом Калдорай','Встретить тебя – бесспорная честь для меня. Ты доказательство благородства нашей расы.$b$bТеперь иди и закончи последнее задание. Отнеси воды Тиранде Шелест Ветра в Дарнас.','Отнесите наполненный сосуд Тиранде Шелест Ветра в Дарнас.','А, священные воды из лунных колодцев. Ты показал их духу Калдорай?$B$BС недавних пор я убедилась, что духи больше задают вопросов, чем дают ответов, но такова жажда открытий, которая движет нами в самые тяжелые минуты.$B$BЯ дам тебе самые простые ответы, какие смогу. Малфурион вернулся ко мне... к нам... но трудные времена еще не прошли. Олений Шлем ушел и мир содрогнулся от боли – Малфуриону многое предстоит сделать, и теперь ему понадобится помощь.','Как дела, юноша?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дом Калдорай',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Встретить тебя – бесспорная честь для меня. Ты доказательство благородства нашей расы.$b$bТеперь иди и закончи последнее задание. Отнеси воды Тиранде Шелест Ветра в Дарнас.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите наполненный сосуд Тиранде Шелест Ветра в Дарнас.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, священные воды из лунных колодцев. Ты показал их духу Калдорай?$B$BС недавних пор я убедилась, что духи больше задают вопросов, чем дают ответов, но такова жажда открытий, которая движет нами в самые тяжелые минуты.$B$BЯ дам тебе самые простые ответы, какие смогу. Малфурион вернулся ко мне... к нам... но трудные времена еще не прошли. Олений Шлем ушел и мир содрогнулся от боли – Малфуриону многое предстоит сделать, и теперь ему понадобится помощь.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как дела, юноша?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14040,'Тыквенный пирог','Ты $gприготовил:приготовила; отличную хлебную запеканку! Но праздничный стол Пиршества странников невозможно представить без огромного тыквенного пирога. Этот десерт очень популярен в наших краях, поскольку готовится из спелых тирисфальских тыкв, которые растут только в этих краях.$B$BЕсли ты еще не знаешь, как готовить тыквенный пирог, загляни в свою пиршественную поваренную книгу.$B$BКстати, тебя не затруднит испечь несколько кусочков и отнести их Фрэнсису Итону? Он накрывает столы рядом со Оргриммаром, и наверняка у него уже кончился тыквенный пирог.','Испеките 5 кусков тыквенного пирога и принесите их Фрэнсису Итону, который стоит у праздничных столов возле Оргриммара.','Тыквенному пирогу мы всегда рады.','Вернитесь к Фрэнсису Итону на Свиноферму, что в Дуротаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тыквенный пирог',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gприготовил:приготовила; отличную хлебную запеканку! Но праздничный стол Пиршества странников невозможно представить без огромного тыквенного пирога. Этот десерт очень популярен в наших краях, поскольку готовится из спелых тирисфальских тыкв, которые растут только в этих краях.$B$BЕсли ты еще не знаешь, как готовить тыквенный пирог, загляни в свою пиршественную поваренную книгу.$B$BКстати, тебя не затруднит испечь несколько кусочков и отнести их Фрэнсису Итону? Он накрывает столы рядом со Оргриммаром, и наверняка у него уже кончился тыквенный пирог.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Испеките 5 кусков тыквенного пирога и принесите их Фрэнсису Итону, который стоит у праздничных столов возле Оргриммара.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тыквенному пирогу мы всегда рады.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фрэнсису Итону на Свиноферму, что в Дуротаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14041,'Клюквенный соус','Ты уже $gпробовал:пробовала; клюквенный соус? Он делается из свежайшей клюквы с берегов реки Строптивой. Если хочешь его приготовить – купи все необходимое у торговца Пиршества странников.$B$BА рецепт записан в твоей пиршественной поваренной книге.$B$BЕсли у тебя есть свободная минутка – может быть, ты поможешь Докину Дальнему Лугу приготовить немного соуса? Он стоит у подъемника на западе Громового Утеса.','Приготовьте пять порций клюквенного соуса и принесите их Докину Дальнему Лугу, который ждет у подъемника на западе Громового Утеса.','Новая порция клюквенного соуса? Отлично, он так быстро кончается!','Как идет празднование Пиршества странников?','Вернитесь к Докину Дальнему Лугу в Громовой Утес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Клюквенный соус',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты уже $gпробовал:пробовала; клюквенный соус? Он делается из свежайшей клюквы с берегов реки Строптивой. Если хочешь его приготовить – купи все необходимое у торговца Пиршества странников.$B$BА рецепт записан в твоей пиршественной поваренной книге.$B$BЕсли у тебя есть свободная минутка – может быть, ты поможешь Докину Дальнему Лугу приготовить немного соуса? Он стоит у подъемника на западе Громового Утеса.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Приготовьте пять порций клюквенного соуса и принесите их Докину Дальнему Лугу, который ждет у подъемника на западе Громового Утеса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Новая порция клюквенного соуса? Отлично, он так быстро кончается!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как идет празднование Пиршества странников?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Докину Дальнему Лугу в Громовой Утес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (14042,'Оружие и контрабанда','Должно быть, Хартли выгрузил всю свою артиллерию на берегу. Давай-ка заставим его показать зубы, $n!$B$BПробегись по берегу и найди его боеприпасы. Подожги их. Он останется безоружным и застрянет на берегу, пока чинят "Непобедимый". А я буду ждать тебя в Кабестане.','Уничтожьте 5 Тераморских схронов боеприпасов на берегу.','Вернитесь к Газлоу в Кабестан, что в Северных Степях.','Из украденного ГНМ-передатчика раздается треск и голос Газлоу…','Газлоу') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оружие и контрабанда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Должно быть, Хартли выгрузил всю свою артиллерию на берегу. Давай-ка заставим его показать зубы, $n!$B$BПробегись по берегу и найди его боеприпасы. Подожги их. Он останется безоружным и застрянет на берегу, пока чинят "Непобедимый". А я буду ждать тебя в Кабестане.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 5 Тераморских схронов боеприпасов на берегу.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Газлоу в Кабестан, что в Северных Степях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Из украденного ГНМ-передатчика раздается треск и голос Газлоу…',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Газлоу',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14043,'Засахаренный батат','Раз уж ты здесь, помоги нам пополнить запасы мулгорского сочного батата – он идет на изготовление самого вкусного засахаренного деликатеса, который ты когда-либо $gпробовал:пробовала;.$B$BЕсли не веришь – приготовь $gсам:сама;, этот рецепт есть в твоей пиршественной поваренной книге. А если после этого у тебя останется немного угощения – можешь поделиться с Фрэнсисом Итоном, который накрывает столы возле Оргриммара. Боюсь, у него опять кончились все запасы угощений, несмотря на все мои усилия.','Приготовьте 5 порций засахаренного батата и принесите их Фрэнсису Итону, который стоит у праздничных столов возле Оргриммара.','А, Докин поручил тебе приготовить засахаренный батат?$B$B<Френсис улыбается.>$B$BОтлично, иначе он не справился бы. Спасибо за помощь!','А, привет еще раз, $N.','Вернитесь к Фрэнсису Итону на Свиноферму, что в Дуротаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Засахаренный батат',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Раз уж ты здесь, помоги нам пополнить запасы мулгорского сочного батата – он идет на изготовление самого вкусного засахаренного деликатеса, который ты когда-либо $gпробовал:пробовала;.$B$BЕсли не веришь – приготовь $gсам:сама;, этот рецепт есть в твоей пиршественной поваренной книге. А если после этого у тебя останется немного угощения – можешь поделиться с Фрэнсисом Итоном, который накрывает столы возле Оргриммара. Боюсь, у него опять кончились все запасы угощений, несмотря на все мои усилия.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Приготовьте 5 порций засахаренного батата и принесите их Фрэнсису Итону, который стоит у праздничных столов возле Оргриммара.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, Докин поручил тебе приготовить засахаренный батат?$B$B<Френсис улыбается.>$B$BОтлично, иначе он не справился бы. Спасибо за помощь!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','А, привет еще раз, $N.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фрэнсису Итону на Свиноферму, что в Дуротаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14044,'Нехватка продовольствия в Подгороде','Спасибо за то, что $gпринес:принесла; нам засахаренный батат! Нам еще так много надо приготовить – я просто не успеваю за всем следить. А тут еще Майлс жалуется на то, что у него практически кончился клюквенный соус и запеканка. Я могу рассчитывать на твою помощь? Было бы неплохо, если бы ты $gприготовил:приготовила; несколько порций угощения. Все нужные ингредиенты есть у продавца.$B$BОтнеси готовую еду Майлсу к праздничным столам, которые накрыты в руинах над Подгородом.','Приготовьте 5 порций пряной хлебной запеканки и 5 порций клюквенного соуса, и отнесите их Майлсу Стендишу к входу в Подгород.','Спасибо за доставку – я уже начал волноваться. Плохо, когда на столах одни объедки.','Рад снова видеть тебя, $N.','Вернитесь к Майлсу Стендишу на Руины Лордерона, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нехватка продовольствия в Подгороде',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Спасибо за то, что $gпринес:принесла; нам засахаренный батат! Нам еще так много надо приготовить – я просто не успеваю за всем следить. А тут еще Майлс жалуется на то, что у него практически кончился клюквенный соус и запеканка. Я могу рассчитывать на твою помощь? Было бы неплохо, если бы ты $gприготовил:приготовила; несколько порций угощения. Все нужные ингредиенты есть у продавца.$B$BОтнеси готовую еду Майлсу к праздничным столам, которые накрыты в руинах над Подгородом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Приготовьте 5 порций пряной хлебной запеканки и 5 порций клюквенного соуса, и отнесите их Майлсу Стендишу к входу в Подгород.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо за доставку – я уже начал волноваться. Плохо, когда на столах одни объедки.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Рад снова видеть тебя, $N.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Майлсу Стендишу на Руины Лордерона, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (14045,'Найти барона Дольноберега','Этот грязный пират барон Дольноберег держал в страхе местные воды до тех пор, пока Альянс не потопил его флот и не повязал выживших. Думаешь, я доволен? По мне видно, что я свечусь от радости, $n?$b$bДо того, как его поймали, Дольноберег захватил один из моих самых ценных грузов. Я хочу получить обратно свои товары! Найди Дольноберега в лагере Альянса к югу отсюда и попробуй заставить его рассказать, где он держит мои сокровища.','Найдите упомянутого пирата барона Дольноберега и поговорите с ним.','Хе-хе! Старик Газлоу все еще не расстался с мечтой снова увидеть свои товары, да? Ну что, похоже, нам есть о чем поторговаться с этим лопоухим любителем золотишка.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Найти барона Дольноберега',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этот грязный пират барон Дольноберег держал в страхе местные воды до тех пор, пока Альянс не потопил его флот и не повязал выживших. Думаешь, я доволен? По мне видно, что я свечусь от радости, $n?$b$bДо того, как его поймали, Дольноберег захватил один из моих самых ценных грузов. Я хочу получить обратно свои товары! Найди Дольноберега в лагере Альянса к югу отсюда и попробуй заставить его рассказать, где он держит мои сокровища.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите упомянутого пирата барона Дольноберега и поговорите с ним.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хе-хе! Старик Газлоу все еще не расстался с мечтой снова увидеть свои товары, да? Ну что, похоже, нам есть о чем поторговаться с этим лопоухим любителем золотишка.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (14046,'Потребности истинного барона','Да, $gприятель:подруга;, я без сомнений отправлюсь на виселицу. На кой мне теперь эти сокровища...$b$bРазве что купить на них свою жизнь. Я заключу с тобой сделку, |3-6($r). Разбей эти наручники и я скажу тебе, где закопаны сокровища.$b$bО, моему слову можно верить, $gприятель:подруга;. Я же был настоящим бароном.','Если вы доверяете барону Дольноберегу, поговорите с ним и освободите его от наручников.','Если вы доверяете барону Дольноберегу, поговорите с ним и освободите его от наручников.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Потребности истинного барона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Да, $gприятель:подруга;, я без сомнений отправлюсь на виселицу. На кой мне теперь эти сокровища...$b$bРазве что купить на них свою жизнь. Я заключу с тобой сделку, |3-6($r). Разбей эти наручники и я скажу тебе, где закопаны сокровища.$b$bО, моему слову можно верить, $gприятель:подруга;. Я же был настоящим бароном.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Если вы доверяете барону Дольноберегу, поговорите с ним и освободите его от наручников.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Если вы доверяете барону Дольноберегу, поговорите с ним и освободите его от наручников.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14047,'Запеченная индейка','Какой же праздник Пиршества странников без главного украшения – огромной жареной индейки, царицы праздничного стола!$B$BПо-моему, в твоей пиршественной поваренной книге есть подходящий рецепт. Почему бы тебе не убить несколько диких индеек и не приготовить их к празднику? Индейки водятся повсюду в Тирисфальских лесах, так что тебе не составит труда отыскать добычу.$B$BКак только закончишь готовить, принеси жареных индеек Фрэнсису Итону к вратам Оргриммара, хорошо?','Приготовьте 5 запеченных индеек и принесите их Фрэнсису Итону к вратам Оргриммара.','Что привело тебя в Оргриммар, $N?','Вернитесь к Фрэнсису Итону на Свиноферму, что в Дуротаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Запеченная индейка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Какой же праздник Пиршества странников без главного украшения – огромной жареной индейки, царицы праздничного стола!$B$BПо-моему, в твоей пиршественной поваренной книге есть подходящий рецепт. Почему бы тебе не убить несколько диких индеек и не приготовить их к празднику? Индейки водятся повсюду в Тирисфальских лесах, так что тебе не составит труда отыскать добычу.$B$BКак только закончишь готовить, принеси жареных индеек Фрэнсису Итону к вратам Оргриммара, хорошо?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Приготовьте 5 запеченных индеек и принесите их Фрэнсису Итону к вратам Оргриммара.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что привело тебя в Оргриммар, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фрэнсису Итону на Свиноферму, что в Дуротаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14048,'Слишком мало индеек','Принесите 20 запеченных индеек Кэтрин Железный Чан к вратам Стальгорна.','Тебе удалось найти индеек?','Вернитесь к Кэтрин Железный Чан ко Вратам Стальгорна, что в Дун Мороге.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Слишком мало индеек',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 20 запеченных индеек Кэтрин Железный Чан к вратам Стальгорна.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось найти индеек?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кэтрин Железный Чан ко Вратам Стальгорна, что в Дун Мороге.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14049,'Самая необычная карта','Такое дельце, $gприятель:подруга;. Чтобы защитить карту сокровищ, я вытатуировал ее на голове моего первого помощника.$b$bРазумеется, сейчас он мертв, как и все остальные члены команды. Альянс понятия не имеет, что у них в руках, и его отрубленная голова украшает сейчас дерево у входа в их лагерь.$b$bСними эту голову и принеси ее Газлоу в Кабестан.','Возьмите татуированную голову у входа в лагерь Альянса.','Что? Что это? Я отправил тебя за сокровищами, а ты приносишь мне воняющую отрубленную голову?','Барон Дольноберег жив? У тебя есть что-то для меня?','Отнесите татуированные головы Газлоу в Кабестан, что в Северных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Самая необычная карта',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Такое дельце, $gприятель:подруга;. Чтобы защитить карту сокровищ, я вытатуировал ее на голове моего первого помощника.$b$bРазумеется, сейчас он мертв, как и все остальные члены команды. Альянс понятия не имеет, что у них в руках, и его отрубленная голова украшает сейчас дерево у входа в их лагерь.$b$bСними эту голову и принеси ее Газлоу в Кабестан.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возьмите татуированную голову у входа в лагерь Альянса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что? Что это? Я отправил тебя за сокровищами, а ты приносишь мне воняющую отрубленную голову?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Барон Дольноберег жив? У тебя есть что-то для меня?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите татуированные головы Газлоу в Кабестан, что в Северных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (14050,'Богатство Газлоу','Разрази меня гром! Ты $gбыл:была; $gправ:права;!$b$bЧертов Барон, а? Зарыл сокровище прямо у меня под носом. Или, вернее, прямо над головой. На карте отмечено место в скалах над Кабестаном, на юге.$b$bВыйди из города по дороге на запад, заберись на холм, поверни на юг и иди обратно к берегу, там найди огромное дерево на берегу залива. Принеси мне мое сокровище и получишь свою долю!','Газлоу из Кабестана хочет, чтобы вы отправились в скалы над городом и выкопали его сокровище.','Вернитесь к Газлоу в Кабестан, что в Северных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Богатство Газлоу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Разрази меня гром! Ты $gбыл:была; $gправ:права;!$b$bЧертов Барон, а? Зарыл сокровище прямо у меня под носом. Или, вернее, прямо над головой. На карте отмечено место в скалах над Кабестаном, на юге.$b$bВыйди из города по дороге на запад, заберись на холм, поверни на юг и иди обратно к берегу, там найди огромное дерево на берегу залива. Принеси мне мое сокровище и получишь свою долю!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Газлоу из Кабестана хочет, чтобы вы отправились в скалы над городом и выкопали его сокровище.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Газлоу в Кабестан, что в Северных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14051,'Не забыть про запеканку!','Ох, как нелегко следить за тем, чтобы праздничные столы не пустовали! Одной рукой помешиваю клюквенный соус, другой готовлю засахаренный батат, а еще надо следить за тем, чтобы пироги не подгорели!$B$BИ почему у меня такое чувство, что я что-то упустила из виду? Точно, я забыла про запеканку! Ай, беда... что же делать? Я уже не успею приготовить все, что собиралась! Послушай, может быть, ты мне поможешь? Это несложно – просто купи несколько тарелок готовой запеканки или приготовь ее $gсам:сама; – все ингредиенты можно купить прямо здесь.','Принесите 20 порций пряной хлебной запеканки Кэтрин Железный Чан к праздничным столам у ворот Стальгорна.','Слава добрым духам! Какой же праздничный стол без хлебной запеканки?','Ну, что там с запеканкой?','Вернитесь к Кэтрин Железный Чан ко Вратам Стальгорна, что в Дун Мороге.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Не забыть про запеканку!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ох, как нелегко следить за тем, чтобы праздничные столы не пустовали! Одной рукой помешиваю клюквенный соус, другой готовлю засахаренный батат, а еще надо следить за тем, чтобы пироги не подгорели!$B$BИ почему у меня такое чувство, что я что-то упустила из виду? Точно, я забыла про запеканку! Ай, беда... что же делать? Я уже не успею приготовить все, что собиралась! Послушай, может быть, ты мне поможешь? Это несложно – просто купи несколько тарелок готовой запеканки или приготовь ее $gсам:сама; – все ингредиенты можно купить прямо здесь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 20 порций пряной хлебной запеканки Кэтрин Железный Чан к праздничным столам у ворот Стальгорна.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Слава добрым духам! Какой же праздничный стол без хлебной запеканки?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, что там с запеканкой?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кэтрин Железный Чан ко Вратам Стальгорна, что в Дун Мороге.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (14052,'Встреча с Тони','Эта ситуация с пиратами мне все портит. Капитан Шпрота нападает на все корабли, какие увидит. Даже на те, чьи владельцы заплатили мне за "покровительство". Мы должны стрясти деньги с этих пиратов и побыстрее!$b$bЯ знаю одного парня, он лейтенант у Шпроты, такой же корыстный делец, как и Головокружилкинс. Я предложил ему устроить маленький "мятеж" и переманить кое-кого из пиратов на нашу сторону. Если эти ребята будут работать на нас, мы станем получать бешеные деньги, понимаешь?$b$bПоговори с Тони Два Клыка на Острове Битв к югу отсюда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Встреча с Тони',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эта ситуация с пиратами мне все портит. Капитан Шпрота нападает на все корабли, какие увидит. Даже на те, чьи владельцы заплатили мне за "покровительство". Мы должны стрясти деньги с этих пиратов и побыстрее!$b$bЯ знаю одного парня, он лейтенант у Шпроты, такой же корыстный делец, как и Головокружилкинс. Я предложил ему устроить маленький "мятеж" и переманить кое-кого из пиратов на нашу сторону. Если эти ребята будут работать на нас, мы станем получать бешеные деньги, понимаешь?$b$bПоговори с Тони Два Клыка на Острове Битв к югу отсюда.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14053,'У нас опять кончился соус?','Мой супруг, Джаспер, собирался приготовить клюквенный соус, но потом оказалось, что на столах слишком мало засахаренного батата. Похоже, ему не справиться без посторонней помощи. Если ты умеешь готовить, можешь купить клюкву у продавца Пиршества странников – он стоит рядом с вратами в Стальгорн.$B$BА если тебе не хочется браться за половник – ты всегда можешь попросить кого-нибудь приготовить соус для тебя.','Принесите 20 порций клюквенного соуса Эллен Мур к праздничным столам возле Штормграда.','Ты уже несешь клюквенный соус?','Вернитесь к Эллен Мур в Златоземье, что в Элвиннском лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','У нас опять кончился соус?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мой супруг, Джаспер, собирался приготовить клюквенный соус, но потом оказалось, что на столах слишком мало засахаренного батата. Похоже, ему не справиться без посторонней помощи. Если ты умеешь готовить, можешь купить клюкву у продавца Пиршества странников – он стоит рядом с вратами в Стальгорн.$B$BА если тебе не хочется браться за половник – ты всегда можешь попросить кого-нибудь приготовить соус для тебя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 20 порций клюквенного соуса Эллен Мур к праздничным столам возле Штормграда.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты уже несешь клюквенный соус?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Эллен Мур в Златоземье, что в Элвиннском лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14054,'Проще пареной тыквы','Исаак трудится не покладая рук, чтобы все смогли отведать разнообразные угощенья в честь Пиршества странников, и научились готовить традиционные блюда из тех продуктов, что принес нам последний урожай. Я же стараюсь, чтобы гости ни в чем не испытывали недостатка, но одно из любимых блюд Исаака – тыквенный пирог – уже практически закончилось.$B$BТы сможешь принести еще? Если возьмешься лично его приготовить, купи несколько спелых элвиннских тыкв у праздничного торговца возле Штормграда.','Принесите 20 кусков тыквенного пирога Мэри Аллертон к праздничным столам возле Дарнаса.','Отличные пироги! Исааку и прочим гостям они очень понравятся!','Как там пироги, уже готовы?','Вернитесь к Мэри Аллертон на Террасу Воинов, что в Дарнасе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Проще пареной тыквы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Исаак трудится не покладая рук, чтобы все смогли отведать разнообразные угощенья в честь Пиршества странников, и научились готовить традиционные блюда из тех продуктов, что принес нам последний урожай. Я же стараюсь, чтобы гости ни в чем не испытывали недостатка, но одно из любимых блюд Исаака – тыквенный пирог – уже практически закончилось.$B$BТы сможешь принести еще? Если возьмешься лично его приготовить, купи несколько спелых элвиннских тыкв у праздничного торговца возле Штормграда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 20 кусков тыквенного пирога Мэри Аллертон к праздничным столам возле Дарнаса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличные пироги! Исааку и прочим гостям они очень понравятся!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как там пироги, уже готовы?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мэри Аллертон на Террасу Воинов, что в Дарнасе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14055,'Батат – значит, батат!','Моя жена Эллен попросила меня проследить за тем, чтобы столы не пустовали, а сама никак не может определиться, что же ей приготовить. Сначала она поручила мне испечь тыквенный пирог, а потом передумала и решила делать засахаренный батат.$B$BА у меня уже тесто для пирога поднялось! Послушай, может быть, ты займешься этой сладкой картошкой? Представляешь, как она обрадуется, если мы приготовим все, что ей хотелось?$B$BКстати, все необходимые ингредиенты можно приобрести у праздничного торговца в Дарнасе. Удачи, $n.','Принесите 20 порций засахаренного батата Джасперу Муру к праздничным столам возле Штормграда.','Засахаренный батат у тебя?','Вернитесь к Джасперу Муру в Златоземье, что в Элвиннском лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Батат – значит, батат!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Моя жена Эллен попросила меня проследить за тем, чтобы столы не пустовали, а сама никак не может определиться, что же ей приготовить. Сначала она поручила мне испечь тыквенный пирог, а потом передумала и решила делать засахаренный батат.$B$BА у меня уже тесто для пирога поднялось! Послушай, может быть, ты займешься этой сладкой картошкой? Представляешь, как она обрадуется, если мы приготовим все, что ей хотелось?$B$BКстати, все необходимые ингредиенты можно приобрести у праздничного торговца в Дарнасе. Удачи, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 20 порций засахаренного батата Джасперу Муру к праздничным столам возле Штормграда.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Засахаренный батат у тебя?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джасперу Муру в Златоземье, что в Элвиннском лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (14056,'Там мрачный Гломп над златом чахнет','Что? Мятеж по дешевке – это к Головокружилкинсу.$b$bДа, $gприятель:подруга;, мы можем сделать эту работу. Но деньги вперед. Капитан Шпрота складирует все денежки, которые мы получаем. Из них я смогу заплатить мятежникам.$b$bСокровища лежат сразу за казармами. Займись сначала "казначеем" капитана. С Гломпом справиться нелегко. Поверь мне на слово, уж я пробовал.','Убейте Гломпа и добудьте сокровища Гломпа.','Отнесите сокровище Тони Два Клыка на Остров Битв, что в Северных Степях.','Осторожнее, у него смещен центр тяжести.','Гломп') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Там мрачный Гломп над златом чахнет',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что? Мятеж по дешевке – это к Головокружилкинсу.$b$bДа, $gприятель:подруга;, мы можем сделать эту работу. Но деньги вперед. Капитан Шпрота складирует все денежки, которые мы получаем. Из них я смогу заплатить мятежникам.$b$bСокровища лежат сразу за казармами. Займись сначала "казначеем" капитана. С Гломпом справиться нелегко. Поверь мне на слово, уж я пробовал.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Гломпа и добудьте сокровища Гломпа.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите сокровище Тони Два Клыка на Остров Битв, что в Северных Степях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Осторожнее, у него смещен центр тяжести.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Гломп',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (14057,'Оружие. Нам нужно оружие','Для настоящего хорошего мятежа нужно оружие. Все лучшее капитан Шпрота взял себе: целую партию больших тяжелых дворфийских кремневых винтовок. Он хранит их где-то в другом здании на острове. Принеси мне шесть таких винтовок и я раздам их моим будущим офицерам...','Соберите 6 тяжелых дворфийских винтовок.','<Тони берет одну из винтовок и смотрит внутрь ствола.>$B$BОоо, отлично. Сверкающая. Громкая. Вот это я понимаю.$B$BОсталось не так много сделать…','Доставьте винтовки Тони Два Клыка на Остров Битв в Северных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оружие. Нам нужно оружие',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Для настоящего хорошего мятежа нужно оружие. Все лучшее капитан Шпрота взял себе: целую партию больших тяжелых дворфийских кремневых винтовок. Он хранит их где-то в другом здании на острове. Принеси мне шесть таких винтовок и я раздам их моим будущим офицерам...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 6 тяжелых дворфийских винтовок.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Тони берет одну из винтовок и смотрит внутрь ствола.>$B$BОоо, отлично. Сверкающая. Громкая. Вот это я понимаю.$B$BОсталось не так много сделать…',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доставьте винтовки Тони Два Клыка на Остров Битв в Северных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (14058,'Батат – значит, батат!','Роберта Картер попросила меня помочь ей и приготовить одно из ее любимых блюд – засахаренный батат. Я бы рад помочь, но уже пообещал хозяйке накрыть на стол.$B$BМоя благодарность не будет иметь границ, если ты поможешь мне с этим. Роберта никогда не простит мне, если я ее подведу.$B$BКстати, если ты собираешься самостоятельно приготовить это блюдо, могу порекомендовать купить все необходимое у праздничного торговца в Громовом Утесе. Заранее спасибо, $n.','Принесите 20 порций засахаренного батата Вильяму Маллинсу к праздничным столам над Подгородом.','Вернитесь к Вильяму Маллинсу на Руины Лордерона, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Батат – значит, батат!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Роберта Картер попросила меня помочь ей и приготовить одно из ее любимых блюд – засахаренный батат. Я бы рад помочь, но уже пообещал хозяйке накрыть на стол.$B$BМоя благодарность не будет иметь границ, если ты поможешь мне с этим. Роберта никогда не простит мне, если я ее подведу.$B$BКстати, если ты собираешься самостоятельно приготовить это блюдо, могу порекомендовать купить все необходимое у праздничного торговца в Громовом Утесе. Заранее спасибо, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 20 порций засахаренного батата Вильяму Маллинсу к праздничным столам над Подгородом.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Вильяму Маллинсу на Руины Лордерона, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14059,'У нас опять кончился соус?','Не понимаю, куда девается весь клюквенный соус – можно подумать, его поганищам скармливают, стоит мне только отвернуться. Поможешь мне приготовить еще? Если ты умеешь готовить, можешь купить сочную мулгорскую клюкву у праздничного торговца, который стоит возле Оргриммара.$B$BА если тебе лень возиться с ягодами – просто попроси кого-нибудь приготовить соус.','Принесите 20 порций клюквенного соуса Роберте Картер, которая стоит возле праздничных столов во внутреннем дворе Подгорода.','Ты уже несешь клюквенный соус?','Вернитесь к Роберте Картер на Руины Лордерона, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','У нас опять кончился соус?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не понимаю, куда девается весь клюквенный соус – можно подумать, его поганищам скармливают, стоит мне только отвернуться. Поможешь мне приготовить еще? Если ты умеешь готовить, можешь купить сочную мулгорскую клюкву у праздничного торговца, который стоит возле Оргриммара.$B$BА если тебе лень возиться с ягодами – просто попроси кого-нибудь приготовить соус.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 20 порций клюквенного соуса Роберте Картер, которая стоит возле праздничных столов во внутреннем дворе Подгорода.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты уже несешь клюквенный соус?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Роберте Картер на Руины Лордерона, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14060,'Проще пареной тыквы','Докин и Лаха трудятся не покладая рук, чтобы все смогли отведать разнообразные угощенья в честь Пиршества странников, и научились готовить традиционные блюда из тех продуктов, что принес нам последний урожай. Я же стараюсь, чтобы гости ни в чем не испытывали недостатка, но одно из наших любимых блюд – тыквенный пирог – уже практически закончилось.$B$BТы сможешь принести еще? Если возьмешься лично его приготовить, купи несколько спелых тирисфальских тыкв у торговца Пиршества странников возле Подгорода.','Принесите 20 кусков тыквенного пирога Мархаре Голдвит к праздничным столам возле Громового Утеса.','Как там пироги, уже готовы?','Вернитесь к Махаре Золотой Пшенице в Мулгор.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Проще пареной тыквы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Докин и Лаха трудятся не покладая рук, чтобы все смогли отведать разнообразные угощенья в честь Пиршества странников, и научились готовить традиционные блюда из тех продуктов, что принес нам последний урожай. Я же стараюсь, чтобы гости ни в чем не испытывали недостатка, но одно из наших любимых блюд – тыквенный пирог – уже практически закончилось.$B$BТы сможешь принести еще? Если возьмешься лично его приготовить, купи несколько спелых тирисфальских тыкв у торговца Пиршества странников возле Подгорода.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 20 кусков тыквенного пирога Мархаре Голдвит к праздничным столам возле Громового Утеса.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как там пироги, уже готовы?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Махаре Золотой Пшенице в Мулгор.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14061,'Слишком мало индеек','С самого начала праздника я не отхожу от плиты, но угощений надо гораздо больше, чем я могу приготовить одна. Может быть, мне удастся уговорить тебя помочь?$B$BХорошую дикую индейку достать тут очень сложно – разве что ты сумеешь принесешь мне несколько порций. Если решишь лично их приготовить, то могу посоветовать охотиться на птиц в Тирисфальских лесах. Все остальные ингредиенты можно купить у любого торговца Пиршества странников.','Принесите 20 запеченных индеек Ондани Большой Мельнице к вратам Оргриммара.','Как идет охота на индеек?','Вернитесь к Ондани Большой Мельнице на Свиноферму, что в Дуротаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Слишком мало индеек',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','С самого начала праздника я не отхожу от плиты, но угощений надо гораздо больше, чем я могу приготовить одна. Может быть, мне удастся уговорить тебя помочь?$B$BХорошую дикую индейку достать тут очень сложно – разве что ты сумеешь принесешь мне несколько порций. Если решишь лично их приготовить, то могу посоветовать охотиться на птиц в Тирисфальских лесах. Все остальные ингредиенты можно купить у любого торговца Пиршества странников.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 20 запеченных индеек Ондани Большой Мельнице к вратам Оргриммара.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как идет охота на индеек?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ондани Большой Мельнице на Свиноферму, что в Дуротаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (14062,'Не забыть про запеканку!','Ох, как нелегко следить за тем, чтобы праздничные столы не пустовали! Одной рукой помешиваю клюквенный соус, другой готовлю засахаренный батат, а еще надо следить за тем, чтобы пироги не подгорели!$B$BИ почему у меня такое чувство, что я что-то упустила из виду? Точно, я забыла про запеканку! Ай, беда... что же делать? Я уже не успею приготовить все, что собиралась! Послушай, может быть, ты мне поможешь? Это несложно – просто купи несколько тарелок готовой запеканки или приготовь ее $gсам:сама; – все ингредиенты можно купить прямо здесь.','Принесите 20 порций пряной хлебной запеканки Ондани Большой Мельнице к вратам Оргриммара.','Ты как раз вовремя! Самое время накрывать на стол и мне не хватает хлебной запеканки.','Вернитесь к Ондани Большой Мельнице на Свиноферму, что в Дуротаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Не забыть про запеканку!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ох, как нелегко следить за тем, чтобы праздничные столы не пустовали! Одной рукой помешиваю клюквенный соус, другой готовлю засахаренный батат, а еще надо следить за тем, чтобы пироги не подгорели!$B$BИ почему у меня такое чувство, что я что-то упустила из виду? Точно, я забыла про запеканку! Ай, беда... что же делать? Я уже не успею приготовить все, что собиралась! Послушай, может быть, ты мне поможешь? Это несложно – просто купи несколько тарелок готовой запеканки или приготовь ее $gсам:сама; – все ингредиенты можно купить прямо здесь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 20 порций пряной хлебной запеканки Ондани Большой Мельнице к вратам Оргриммара.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты как раз вовремя! Самое время накрывать на стол и мне не хватает хлебной запеканки.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ондани Большой Мельнице на Свиноферму, что в Дуротаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14063,'Мятеж!','А теперь переходим к моей любимой части мятежа: убийства! Пиратам неважно, кто пойдет в расход, важно, кто контролирует корабли. У восточной части этого острова стоит на якоре корабль "Кинжал девы", бывший флагманский корабль капитана Шпроты. Он оставил там Алисию Катберт, это одна из его самых надежных офицеров. Устраним ее – и корабль наш, а вместе с ним и море.$b$bМои люди будут в лодках. Заберись на "Кинжал девы" и протруби там в этот рог – это будет сигнал для нас, что можно начинать. Давай!','Используйте пиратский сигнальный рог, чтобы призвать Тони Два Клыка и его команду на "Кинжал Девы". Помогите ему справиться с Алисией Катберт.','Так значит Тони закатил там представление? Хорошо! В этих водах нам пригодятся такие пираты, как он. Настоящий деловой человек.$B$B<Головокружилкинс с жадностью потирает руки.>$B$BПолагаю, я твой должник. Не хочешь застраховать свою добычу? В городах вроде этого никогда ни в чем нельзя быть уверенным...','Это случайно не "Кинжал девы" снимается с якоря там на горизонте? Твоя работа?','Расскажите об успехе управляющему пристанью Головокружилкинсу в Кабестане, что в Северных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мятеж!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А теперь переходим к моей любимой части мятежа: убийства! Пиратам неважно, кто пойдет в расход, важно, кто контролирует корабли. У восточной части этого острова стоит на якоре корабль "Кинжал девы", бывший флагманский корабль капитана Шпроты. Он оставил там Алисию Катберт, это одна из его самых надежных офицеров. Устраним ее – и корабль наш, а вместе с ним и море.$b$bМои люди будут в лодках. Заберись на "Кинжал девы" и протруби там в этот рог – это будет сигнал для нас, что можно начинать. Давай!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте пиратский сигнальный рог, чтобы призвать Тони Два Клыка и его команду на "Кинжал Девы". Помогите ему справиться с Алисией Катберт.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так значит Тони закатил там представление? Хорошо! В этих водах нам пригодятся такие пираты, как он. Настоящий деловой человек.$B$B<Головокружилкинс с жадностью потирает руки.>$B$BПолагаю, я твой должник. Не хочешь застраховать свою добычу? В городах вроде этого никогда ни в чем нельзя быть уверенным...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Это случайно не "Кинжал девы" снимается с якоря там на горизонте? Твоя работа?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Расскажите об успехе управляющему пристанью Головокружилкинсу в Кабестане, что в Северных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (14064,'Богатый пир','Если ты еще не $gпробовал:пробовала; блюд с пиршественного стола – считай, Пиршество странников прошло мимо тебя!$B$BПожалуйста, присаживайся, отведай наших угощений. Не стесняйся пересаживаться поближе – или просто попроси соседей передать тебе любое блюдо.$B$BКогда насытишься вдоволь, почувствуешь, как на тебя снизойдет дух пиршества.','Съешьте по 5 порций каждого из праздничных блюд с пиршественного стола, пока не ощутите дух пиршества.','Вернитесь к хозяйке пиршественного стола.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Богатый пир',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если ты еще не $gпробовал:пробовала; блюд с пиршественного стола – считай, Пиршество странников прошло мимо тебя!$B$BПожалуйста, присаживайся, отведай наших угощений. Не стесняйся пересаживаться поближе – или просто попроси соседей передать тебе любое блюдо.$B$BКогда насытишься вдоволь, почувствуешь, как на тебя снизойдет дух пиршества.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Съешьте по 5 порций каждого из праздничных блюд с пиршественного стола, пока не ощутите дух пиршества.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к хозяйке пиршественного стола.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (14065,'Богатый пир','Если ты еще не $gпробовал:пробовала; блюд с пиршественного стола – считай, Пиршество странников прошло мимо тебя!$B$BПожалуйста, присаживайся, отведай наших угощений. Не стесняйся пересаживаться поближе – или просто попроси соседей передать тебе любое блюдо.$B$BКогда насытишься вдоволь, почувствуешь, как на тебя снизойдет дух пиршества.','Съешьте по 5 порций каждого из праздничных блюд с пиршественного стола, пока не ощутите дух пиршества.','Вернитесь к хозяйке богатого пира.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Богатый пир',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если ты еще не $gпробовал:пробовала; блюд с пиршественного стола – считай, Пиршество странников прошло мимо тебя!$B$BПожалуйста, присаживайся, отведай наших угощений. Не стесняйся пересаживаться поближе – или просто попроси соседей передать тебе любое блюдо.$B$BКогда насытишься вдоволь, почувствуешь, как на тебя снизойдет дух пиршества.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Съешьте по 5 порций каждого из праздничных блюд с пиршественного стола, пока не ощутите дух пиршества.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к хозяйке богатого пира.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (14066,'Осмотр места преступления','Недавно был похищен груз серебра. Он предназначался в уплату стражам Перекрестка, и его необходимо вернуть.$B$BЯ собираю информацию среди населения здесь, а для тебя у меня есть другое задание – обыщи место преступления. Отправляйся на запад, там ты найдешь разбитую повозку из каравана. Она находится к северу от дороги, что ведет отсюда в Перекресток. Выясни, кто взял наши деньги и верни их!','Найдите разбитую повозку каравана возле дороги между Кабестаном и Перекрестком и поищите вокруг улики.','Караван Орды не просто ограбили. Он подвергся жестокому нападению. Ящики с припасами были разодраны острыми когтями. Повозка разбита. Еда сожрана, серебро исчезло, менее полезные припасы брошены на землю...','Караван найден','Найдите обломки каравана возле дороги между Кабестаном и Перекрестком и поищите улики.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Осмотр места преступления',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Недавно был похищен груз серебра. Он предназначался в уплату стражам Перекрестка, и его необходимо вернуть.$B$BЯ собираю информацию среди населения здесь, а для тебя у меня есть другое задание – обыщи место преступления. Отправляйся на запад, там ты найдешь разбитую повозку из каравана. Она находится к северу от дороги, что ведет отсюда в Перекресток. Выясни, кто взял наши деньги и верни их!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите разбитую повозку каравана возле дороги между Кабестаном и Перекрестком и поищите вокруг улики.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Караван Орды не просто ограбили. Он подвергся жестокому нападению. Ящики с припасами были разодраны острыми когтями. Повозка разбита. Еда сожрана, серебро исчезло, менее полезные припасы брошены на землю...',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Караван найден',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Найдите обломки каравана возле дороги между Кабестаном и Перекрестком и поищите улики.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (14067,'Похищенное серебро','Совершенно ясно, что похитившие серебро Орды ящеры действовали без сообщников!$b$bПора хорошенько проучить их.','Убейте 8 яркочешуйчатых опустошителей, 4 яркочешуйчатых смертехвата и найдите украденное серебро.','Верните украденное серебро Газрогу. Его можно найти у входа в Кабестан, что в Северных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Похищенное серебро',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Совершенно ясно, что похитившие серебро Орды ящеры действовали без сообщников!$b$bПора хорошенько проучить их.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 яркочешуйчатых опустошителей, 4 яркочешуйчатых смертехвата и найдите украденное серебро.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Верните украденное серебро Газрогу. Его можно найти у входа в Кабестан, что в Северных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14068,'Охота на яфферов','Уфтановка ловуффек для яфферов, может быть, и опафное дело, но я разработал соверфенно новую ловуффку, которая знафительно сниффает рифк.$b$bПолофы ловуффку на землю, и она нафнет издавать виффафие звуки, тофь-в-тофь как яфферы. Таким образом мы заманим яффера в ловуффку, а как только он фтупит туда, ловуффка зафлопнется. Фсе, яффер уфе не так опафен! Фсе офень просто. Я бы и фам фделал это, но недавно перебефал дорогу королю Деруффий Коготь.','Используйте "Ловуфку для яфферов" Кала\'мы для поимки 5 маленьких яфферов.','Ура! Ты поймал яфферов, котофых я искал! Теперь мы отпфафим их тфоллям, а те верхом на них будут бороффа с Альянфом!','Гфе маленькие яфферы?','Принесите маеньких яфферов Кала\'ме в Северных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота на яфферов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Уфтановка ловуффек для яфферов, может быть, и опафное дело, но я разработал соверфенно новую ловуффку, которая знафительно сниффает рифк.$b$bПолофы ловуффку на землю, и она нафнет издавать виффафие звуки, тофь-в-тофь как яфферы. Таким образом мы заманим яффера в ловуффку, а как только он фтупит туда, ловуффка зафлопнется. Фсе, яффер уфе не так опафен! Фсе офень просто. Я бы и фам фделал это, но недавно перебефал дорогу королю Деруффий Коготь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте "Ловуфку для яфферов" Кала\'мы для поимки 5 маленьких яфферов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ура! Ты поймал яфферов, котофых я искал! Теперь мы отпфафим их тфоллям, а те верхом на них будут бороффа с Альянфом!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Гфе маленькие яфферы?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите маеньких яфферов Кала\'ме в Северных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (14069,'Хороших работников трудно найти','У меня ничего не вышло! Я делал все что мог, чтобы выполнить план по производству "Каджа-Колы", но ты же знаешь... с этими троллями – просто беда. Сложно найти толковых помощников!$B$BДумаю, понадобится твое личное участие. Полагаю, пары ударов током от батареи твоего гоблинского все-в-одном-чудо-пояса будет достаточно. Главное, приструнить основных зачинщиков мятежа, и тогда остальные тролли быстренько придут в чувство.$B$BПроизводство "Каджа-Колы" должно идти без перебоев, иначе торговый принц с нас шкуру спустит!','Усмирите 8 взбунтовавшихся троллей.','Вернитесь к штейгеру Промокаху в штаб-квартиру ТКК на Кезане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хороших работников трудно найти',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У меня ничего не вышло! Я делал все что мог, чтобы выполнить план по производству "Каджа-Колы", но ты же знаешь... с этими троллями – просто беда. Сложно найти толковых помощников!$B$BДумаю, понадобится твое личное участие. Полагаю, пары ударов током от батареи твоего гоблинского все-в-одном-чудо-пояса будет достаточно. Главное, приструнить основных зачинщиков мятежа, и тогда остальные тролли быстренько придут в чувство.$B$BПроизводство "Каджа-Колы" должно идти без перебоев, иначе торговый принц с нас шкуру спустит!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Усмирите 8 взбунтовавшихся троллей.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к штейгеру Промокаху в штаб-квартиру ТКК на Кезане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (14070,'Как вразумить должников','Все-таки надо бы разобраться с нашими должниками. Никчемные лодыри прячутся в Рабочем квартале. Я знаю, как ты не любишь шастать по трущобам, но, как говорится, кому сейчас легко?$B$B<Хамми листает какие-то бумаги.>$B$BЗдесь у меня все записано. Все имена.$B$BДумаю, стоит начать, скажем так, с "личной беседы". Пара-тройка стратегических избиений – даже без тяжких физических повреждений – и все остальные сразу поймут намек. И должники, и конкуренты.$B$B$n – не из тех гоблинов, с кем можно шутки шутить!','Избейте Бруно Негорючего, Френки Скрипетельку, Джека Молотка и Судзи Магика.','Вот и славно! Теперь твои должники дважды подумают, прежде чем уклоняться от выплаты долга.$B$B<Хамми впадает в задумчивость и рассеянно постукивает карандашом по нижней губе.>$B$BЯ тут вот что подумала... может, нам стоит увеличить процентную ставку по займам?','Вернитесь к Хамми Кофельнагель в штаб-квартиру ТКК на Кезане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Как вразумить должников',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Все-таки надо бы разобраться с нашими должниками. Никчемные лодыри прячутся в Рабочем квартале. Я знаю, как ты не любишь шастать по трущобам, но, как говорится, кому сейчас легко?$B$B<Хамми листает какие-то бумаги.>$B$BЗдесь у меня все записано. Все имена.$B$BДумаю, стоит начать, скажем так, с "личной беседы". Пара-тройка стратегических избиений – даже без тяжких физических повреждений – и все остальные сразу поймут намек. И должники, и конкуренты.$B$B$n – не из тех гоблинов, с кем можно шутки шутить!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Избейте Бруно Негорючего, Френки Скрипетельку, Джека Молотка и Судзи Магика.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот и славно! Теперь твои должники дважды подумают, прежде чем уклоняться от выплаты долга.$B$B<Хамми впадает в задумчивость и рассеянно постукивает карандашом по нижней губе.>$B$BЯ тут вот что подумала... может, нам стоит увеличить процентную ставку по займам?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хамми Кофельнагель в штаб-квартиру ТКК на Кезане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (14071,'Кружим по кварталу','Я слышала, $n, ты собираешься устроить корпоративный банкет. Всем банкетам банкет! И это правильно. Чем веселее твоя вечеринка, тем вернее твое продвижение по службе. Проверено опытом!$B$BТак что садись в свой хотрод да отправляйся собирать друзей по всему городу.$B$BНу, а когда станешь $gторговым принцем:торговой принцессой;, обо мне не забудь, лады?','Прокатитесь на хотроде и соберите своих друзей: Туза, Гоббера и Иззи.','Вот и славно. У тебя такой солидный вид, когда ты разъезжаешь на этом хотроде. Думаю, ты произвел на горожан неизгладимое впечатление.','Вернитесь к Мегз Жестекрошшер в штаб-квартиру ТКК на Кезане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кружим по кварталу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я слышала, $n, ты собираешься устроить корпоративный банкет. Всем банкетам банкет! И это правильно. Чем веселее твоя вечеринка, тем вернее твое продвижение по службе. Проверено опытом!$B$BТак что садись в свой хотрод да отправляйся собирать друзей по всему городу.$B$BНу, а когда станешь $gторговым принцем:торговой принцессой;, обо мне не забудь, лады?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Прокатитесь на хотроде и соберите своих друзей: Туза, Гоббера и Иззи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот и славно. У тебя такой солидный вид, когда ты разъезжаешь на этом хотроде. Думаю, ты произвел на горожан неизгладимое впечатление.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мегз Жестекрошшер в штаб-квартиру ТКК на Кезане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (14072,'Против Верога','Доставьте оперативную информацию Шузе в Застывший оазис, что в Северных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Против Верога',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доставьте оперативную информацию Шузе в Застывший оазис, что в Северных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (14073,'Регтар Врата Смерти получает подкрепление') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Регтар Врата Смерти получает подкрепление',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14074,'Лапами кверху','Серебряный Авангард отправил сюда крейсерский корабль, перевозивший мясо долгоногов и прочие припасы для турнира, но он так и не добрался до пункта назначения. Наши разведчики доложили, что на него напали квалдиры, безжалостные пираты, которые бороздят эти моря.$B$BОни убили всю команду и перетащили груз на остров, который теперь называется Лагерь Хротгара. Посмотри на север – и увидишь его среди туманов. Может быть, ты поможешь нам вернуть украденные припасы? Если мясо долгоногов не прибудет вовремя, у нас может кончиться провизия.','Верните 10 украденных окорочков долгонога Нараси Снежной Заре из Павильона Серебряного союза на Ристалище Серебряного турнира.','М-да, выглядят они... не очень, но есть можно. Крестоносцы будут рады узнать, что нам удалось спасти хоть какие-то припасы с корабля.','Тебе удалось найти украденные припасы?','Вернитесь к Нараси Снежной Заре на Ристалище Серебряного турнира в Ледяную Корону.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лапами кверху',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Серебряный Авангард отправил сюда крейсерский корабль, перевозивший мясо долгоногов и прочие припасы для турнира, но он так и не добрался до пункта назначения. Наши разведчики доложили, что на него напали квалдиры, безжалостные пираты, которые бороздят эти моря.$B$BОни убили всю команду и перетащили груз на остров, который теперь называется Лагерь Хротгара. Посмотри на север – и увидишь его среди туманов. Может быть, ты поможешь нам вернуть украденные припасы? Если мясо долгоногов не прибудет вовремя, у нас может кончиться провизия.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните 10 украденных окорочков долгонога Нараси Снежной Заре из Павильона Серебряного союза на Ристалище Серебряного турнира.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','М-да, выглядят они... не очень, но есть можно. Крестоносцы будут рады узнать, что нам удалось спасти хоть какие-то припасы с корабля.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось найти украденные припасы?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Нараси Снежной Заре на Ристалище Серебряного турнира в Ледяную Корону.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (14075,'Беспорядки в шахтах','В Каджа\'митовой шахте опять беспорядки. Вернулись роющие черви, и они – в прямом смысле слова – пожирают всю прибыль Торгового дома Каджаро!$B$BДобыча каджа\'мита практически остановлена, а это, как ты понимаешь, отрицательно сказывается на производстве "Каджа-Колы"!$B$BМы пригласили истребителя червей, но он, шельмец, взял деньги вперед и сбежал.$B$BМожет быть, ты $gсам:сама; очистишь три шахты? Я бы пошел вместе с тобой, да вот пока не прошел обучение на семинаре по боевому искусству.','Убейте 6 роющих червей.','Так им и надо, паразитам!','Вернитесь к штейгеру Промокаху в штаб-квартиру ТКК на Кезане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Беспорядки в шахтах',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В Каджа\'митовой шахте опять беспорядки. Вернулись роющие черви, и они – в прямом смысле слова – пожирают всю прибыль Торгового дома Каджаро!$B$BДобыча каджа\'мита практически остановлена, а это, как ты понимаешь, отрицательно сказывается на производстве "Каджа-Колы"!$B$BМы пригласили истребителя червей, но он, шельмец, взял деньги вперед и сбежал.$B$BМожет быть, ты $gсам:сама; очистишь три шахты? Я бы пошел вместе с тобой, да вот пока не прошел обучение на семинаре по боевому искусству.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 6 роющих червей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так им и надо, паразитам!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к штейгеру Промокаху в штаб-квартиру ТКК на Кезане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14076,'Завтрак для чемпионов','Найдите 4 яйца йормунгаров и принесите их Савинии Певице Преданий на Ристалище Серебряного турнира.','Тебе удалось добыть яйца йормунгаров? По-моему, эти червяки скоро примутся пожирать своих надсмотрщиков.','Вернитесь к Савинии Певице Преданий на Ристалище Серебряного турнира в Ледяную Корону.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Завтрак для чемпионов',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите 4 яйца йормунгаров и принесите их Савинии Певице Преданий на Ристалище Серебряного турнира.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось добыть яйца йормунгаров? По-моему, эти червяки скоро примутся пожирать своих надсмотрщиков.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Савинии Певице Преданий на Ристалище Серебряного турнира в Ледяную Корону.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (14077,'Милосердие Света','Последняя проповедь Исповедницы Пейлтресс заставила меня задуматься о том, что нам недостаточно просто сражаться плечом к плечу с рыцарями Авангарда – мы должны помогать им исполнить свой долг.$B$BУ северного побережья находится Лагерь Хротгара – остров, который захватили морские пираты – квалдиры, убив всех обитавших на нем клыкарров. Возьми эту книгу и прочти отходную молитву рядом с телами павших жителей. Пусть их несчастные души обретут покой вдали от зловещих туманов острова.','Воспользуйтесь Молитвенником исповедницы для проведения последнего обряда над телами 8 убитых туаликов, после чего вернитесь к Нараси Снежной Заре в шатер Альянса на Ристалище Серебряного турнира.','<Нараси забирает у вас молитвенник.>$B$BСпасибо. Этот молитвенник подарила мне сама Исповедница Пейлтресс. Она будет рада узнать, что он послужил благому делу.','Вернитесь к Нараси Снежной Заре на Ристалище Серебряного турнира в Ледяную Корону.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Милосердие Света',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Последняя проповедь Исповедницы Пейлтресс заставила меня задуматься о том, что нам недостаточно просто сражаться плечом к плечу с рыцарями Авангарда – мы должны помогать им исполнить свой долг.$B$BУ северного побережья находится Лагерь Хротгара – остров, который захватили морские пираты – квалдиры, убив всех обитавших на нем клыкарров. Возьми эту книгу и прочти отходную молитву рядом с телами павших жителей. Пусть их несчастные души обретут покой вдали от зловещих туманов острова.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь Молитвенником исповедницы для проведения последнего обряда над телами 8 убитых туаликов, после чего вернитесь к Нараси Снежной Заре в шатер Альянса на Ристалище Серебряного турнира.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Нараси забирает у вас молитвенник.>$B$BСпасибо. Этот молитвенник подарила мне сама Исповедница Пейлтресс. Она будет рада узнать, что он послужил благому делу.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Нараси Снежной Заре на Ристалище Серебряного турнира в Ледяную Корону.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (14078,'Тотальная эвакуация','А ты что здесь делаешь? Разве ты не $gслышал:слышала; про эвакуацию?$B$BНемедленно разыщи лейтенанта Вальдена, и он выдаст тебе дальнейшие инструкции.','Найдите лейтенанта Вальдена в северо-западном углу Торговой площади.','На трупе мужчины видны глубокие раны от когтей.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тотальная эвакуация',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А ты что здесь делаешь? Разве ты не $gслышал:слышала; про эвакуацию?$B$BНемедленно разыщи лейтенанта Вальдена, и он выдаст тебе дальнейшие инструкции.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите лейтенанта Вальдена в северо-западном углу Торговой площади.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','На трупе мужчины видны глубокие раны от когтей.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14079,'Уроки верховой езды в Элвиннском лесу','Это рекламное сообщение об уроках верховой езды и продаже скакунов пришло от Рандала Охотника.$B$BЕго можно найти на лесопилке Восточной долины, в Элвиннском лесу, вдоль дороги, ведущей из Штормграда.','Верните это рекламное сообщение Рандалу Охотнику на лесопилку Восточной долины в Элвиннском лесу.','Итак, давайте начнем твое обучение верховой езде?','О, вы получили мое письмо? Хорошо.','Вернитесь к Рандалу Охотнику на Озеро Каменных Столбов, что в Элвиннском лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уроки верховой езды в Элвиннском лесу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это рекламное сообщение об уроках верховой езды и продаже скакунов пришло от Рандала Охотника.$B$BЕго можно найти на лесопилке Восточной долины, в Элвиннском лесу, вдоль дороги, ведущей из Штормграда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните это рекламное сообщение Рандалу Охотнику на лесопилку Восточной долины в Элвиннском лесу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Итак, давайте начнем твое обучение верховой езде?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','О, вы получили мое письмо? Хорошо.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Рандалу Охотнику на Озеро Каменных Столбов, что в Элвиннском лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14080,'Остановить нападение','Квалдиры, морские твари, что захватили наши грузы, завладели островом клыкарров, который находится на севере пролива, убили его обитателей и переименовали его в Лагерь Хротгара. Если позволить им закрепиться на этой позиции, они изберут нас следующей целью.$B$BАвангард бросил все силы на борьбу с Плетью, поэтому защитить Ристалище можем только мы. Лети на север от турнирной площадки, пока не увидишь этот остров, и убей квалдиров прежде, чем они возьмутся за нас.','Нараси Снежная Заря из Павильона Серебряного союза на Ристалище Серебряного турнира просит вас убить 10 квалдиров.','Твои действия подтвердили, что мы сражаемся плечом к плечу с Серебряным Авангардом, в то время как Похитители Солнца прохлаждаются в тени.','Вы показали квалдирам, что мы не позволим им угрожать нам?','Вернитесь к Нараси Снежной Заре на Ристалище Серебряного турнира в Ледяную Корону.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Остановить нападение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Квалдиры, морские твари, что захватили наши грузы, завладели островом клыкарров, который находится на севере пролива, убили его обитателей и переименовали его в Лагерь Хротгара. Если позволить им закрепиться на этой позиции, они изберут нас следующей целью.$B$BАвангард бросил все силы на борьбу с Плетью, поэтому защитить Ристалище можем только мы. Лети на север от турнирной площадки, пока не увидишь этот остров, и убей квалдиров прежде, чем они возьмутся за нас.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Нараси Снежная Заря из Павильона Серебряного союза на Ристалище Серебряного турнира просит вас убить 10 квалдиров.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Твои действия подтвердили, что мы сражаемся плечом к плечу с Серебряным Авангардом, в то время как Похитители Солнца прохлаждаются в тени.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы показали квалдирам, что мы не позволим им угрожать нам?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Нараси Снежной Заре на Ристалище Серебряного турнира в Ледяную Корону.',`completedtext_loc8`);
