INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14088,'Уроки верховой езды в Дуротаре','Это рекламное сообщение об уроках верховой езды и продаже скакунов пришло от Ксар\'Ти.$B$BЕго можно найти в Деревне Сен\'джин, что в южном Дуротаре.','Верните это рекламное сообщение Ксар\'Ти в деревню Сен\'джин в Дуротаре.','Итак, давайте начнем твое обучение верховой езде?','О, вы получили мое письмо? Хорошо.','Вернитесь к Ксар\'ти на Побережье Черного Копья, что в Дуротаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уроки верховой езды в Дуротаре',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это рекламное сообщение об уроках верховой езды и продаже скакунов пришло от Ксар\'Ти.$B$BЕго можно найти в Деревне Сен\'джин, что в южном Дуротаре.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните это рекламное сообщение Ксар\'Ти в деревню Сен\'джин в Дуротаре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Итак, давайте начнем твое обучение верховой езде?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','О, вы получили мое письмо? Хорошо.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ксар\'ти на Побережье Черного Копья, что в Дуротаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14089,'Уроки верховой езды в Тирисфальских лесах','Это рекламное сообщение об уроках верховой езды и продаже скакунов пришло от Вельмы Варнам.$B$BЕе можно найти в Брилле, в Тирисфальских лесах.','Верните это рекламное сообщение Вельме Варнам в Брилл в Тирисфальских лесах.','Итак, давайте начнем твое обучение верховой езде?','О, вы получили мое письмо? Хорошо.','Вернитесь к Вельме Варнам в Брилл, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уроки верховой езды в Тирисфальских лесах',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это рекламное сообщение об уроках верховой езды и продаже скакунов пришло от Вельмы Варнам.$B$BЕе можно найти в Брилле, в Тирисфальских лесах.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните это рекламное сообщение Вельме Варнам в Брилл в Тирисфальских лесах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Итак, давайте начнем твое обучение верховой езде?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','О, вы получили мое письмо? Хорошо.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Вельме Варнам в Брилл, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14090,'Гормоку нужны снобольды','Воспользуйтесь утяжеленной сетью, чтобы поймать 8 последователей с Холмов Снежной Слепоты, и приведите их Савинии Певице Преданий в Павильон Серебряного союза на Ристалище Серебряного турнира.','Чем быстрее мы уберем этих вонючих тварей в клетку, тем лучше. Жаль, что Серебряный Авангард не поручил Похитителям Солнца присматривать за этой тварью. Они так похожи, что им не составило бы труда найти общий язык.','Вам уже удалось собрать этих снобольдов? Гнев Гормока не проявляет никаких признаков ослабления.','Вернитесь к Савинии Певице Преданий на Ристалище Серебряного турнира в Ледяную Корону.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гормоку нужны снобольды',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь утяжеленной сетью, чтобы поймать 8 последователей с Холмов Снежной Слепоты, и приведите их Савинии Певице Преданий в Павильон Серебряного союза на Ристалище Серебряного турнира.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Чем быстрее мы уберем этих вонючих тварей в клетку, тем лучше. Жаль, что Серебряный Авангард не поручил Похитителям Солнца присматривать за этой тварью. Они так похожи, что им не составило бы труда найти общий язык.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вам уже удалось собрать этих снобольдов? Гнев Гормока не проявляет никаких признаков ослабления.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Савинии Певице Преданий на Ристалище Серебряного турнира в Ледяную Корону.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (14091,'Дурной знак','Похоже, лейтенант скончался от нанесенных ран, и эту новость надо немедленно сообщить принцу.$B$BВы слышите шум драки, доносящийся со стороны рынка.','Вернитесь к принцу Лиаму Седогриву на Торговую площадь.','А, это снова ты. Похоже, ты не из тех, кто прячет голову в песок, и это хорошо.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дурной знак',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Похоже, лейтенант скончался от нанесенных ран, и эту новость надо немедленно сообщить принцу.$B$BВы слышите шум драки, доносящийся со стороны рынка.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь к принцу Лиаму Седогриву на Торговую площадь.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, это снова ты. Похоже, ты не из тех, кто прячет голову в песок, и это хорошо.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14092,'Завтрак для чемпионов','Принесите 4 яйца йормунгаров Тайлосу Вестнику Зари в шатер Орды на Ристалище Серебряного турнира.','Тебе удалось добыть яйца? А то йормунгары уже проявляют недовольство.','Вернитесь к Тайлосу Вестнику Зари на Ристалище Серебряного турнира, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Завтрак для чемпионов',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 4 яйца йормунгаров Тайлосу Вестнику Зари в шатер Орды на Ристалище Серебряного турнира.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось добыть яйца? А то йормунгары уже проявляют недовольство.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тайлосу Вестнику Зари на Ристалище Серебряного турнира, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (14093,'И разверзся ад','Воргены! Отец предупреждал меня, что создания верховного мага Аругала обезумели.$B$BНо откуда они взялись?$B$BВпрочем, наверное, это не имеет значения. Лучше помоги нам справиться с ними. Покажем им, из какого теста сделаны настоящие гилнеаcцы!','Принц Лиам Седогрив приказал вам убить 6 озлобленных воргенов.','Вернитесь к принцу Лиаму Седогриву на Торговую площадь в Гилнеас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','И разверзся ад',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Воргены! Отец предупреждал меня, что создания верховного мага Аругала обезумели.$B$BНо откуда они взялись?$B$BВпрочем, наверное, это не имеет значения. Лучше помоги нам справиться с ними. Покажем им, из какого теста сделаны настоящие гилнеаcцы!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принц Лиам Седогрив приказал вам убить 6 озлобленных воргенов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к принцу Лиаму Седогриву на Торговую площадь в Гилнеас.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (14094,'Спасение припасов','Послушай, $n, мы не можем допустить, чтобы все припасы были уничтожены.$B$BСейчас, когда Гилнеас отрезан от остального мира, мы не продержимся и зиму, если потеряем еще больше продовольствия.$B$BПожалуйста, помоги мне спасти хоть что-то!','Спасите 4 ящика с припасами.','Превосходно! Я отнесу их в безопасное место.','Вернитесь к Гвен Армстед на Торговую площадь в Гилнеас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спасение припасов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Послушай, $n, мы не можем допустить, чтобы все припасы были уничтожены.$B$BСейчас, когда Гилнеас отрезан от остального мира, мы не продержимся и зиму, если потеряем еще больше продовольствия.$B$BПожалуйста, помоги мне спасти хоть что-то!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Спасите 4 ящика с припасами.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Превосходно! Я отнесу их в безопасное место.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гвен Армстед на Торговую площадь в Гилнеас.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14095,'Опознание останков','Неповрежденный зуб кракена – это действительно редкая находка. Наверняка она заинтересует Крестоносца Серебристый Рассвет из Серебряного павильона.','Отнесите зуб кракена Крестоносцу Серебристый Рассвет в Серебряный павильон.','Я знал, что тебе не составит труда справиться с кракеном. Теперь, когда это чудовище не нападает на наши корабли, квалдирам останется только спасаться бегством. Очень хорошо, чемпион!','Что там у тебя, чемпион?','Вернитесь к крестоносцу Серебристому Рассвету на Ристалище Серебряного турнира, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Опознание останков',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Неповрежденный зуб кракена – это действительно редкая находка. Наверняка она заинтересует Крестоносца Серебристый Рассвет из Серебряного павильона.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите зуб кракена Крестоносцу Серебристый Рассвет в Серебряный павильон.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я знал, что тебе не составит труда справиться с кракеном. Теперь, когда это чудовище не нападает на наши корабли, квалдирам останется только спасаться бегством. Очень хорошо, чемпион!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что там у тебя, чемпион?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к крестоносцу Серебристому Рассвету на Ристалище Серебряного турнира, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14096,'На этот раз ты нарвался, Кул','Рыцарь Кул опять угодил в беду, но на этот раз увлек за собой других. Как только он увидел, что приспешники культа Проклятых разбили лагерь на Заставе Вестника Смерти, что на западе от Ристалища, то собрал группу претендентов и повел их на бой с захватчиками.$B$BРазумеется, не имея должного подкрепления, они были разбиты и захвачены в плен. Я не сомневаюсь, что злодеи принесут их в жертву, дабы подпитать этой силой свою зловещую магию. Ключи от черных клеток, в которых держат пленников, могут храниться у любого из служителей культа. Прошу тебя, найди ключи, спаси Кула и несчастных претендентов от ужасной участи!','Спасите Кула Безрассудного и 4 пленных претендентов с Заставы Вестника Смерти и вернитесь к Нараси Снежной Заре в шатер Альянса на Ристалище Серебряного турнира.','Благодаря тебе Кул и другие претенденты снова вернулись в строй, чтобы сражаться с Плетью. К несчастью, нам не впервой спасать этого доблестного мужа от самого себя. Надеюсь, претенденты выберут себе другой пример для подражания.','Ты освободил Кула и тех безнадежных претендентов?','Вернитесь к Нараси Снежной Заре на Ристалище Серебряного турнира в Ледяную Корону.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На этот раз ты нарвался, Кул',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Рыцарь Кул опять угодил в беду, но на этот раз увлек за собой других. Как только он увидел, что приспешники культа Проклятых разбили лагерь на Заставе Вестника Смерти, что на западе от Ристалища, то собрал группу претендентов и повел их на бой с захватчиками.$B$BРазумеется, не имея должного подкрепления, они были разбиты и захвачены в плен. Я не сомневаюсь, что злодеи принесут их в жертву, дабы подпитать этой силой свою зловещую магию. Ключи от черных клеток, в которых держат пленников, могут храниться у любого из служителей культа. Прошу тебя, найди ключи, спаси Кула и несчастных претендентов от ужасной участи!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Спасите Кула Безрассудного и 4 пленных претендентов с Заставы Вестника Смерти и вернитесь к Нараси Снежной Заре в шатер Альянса на Ристалище Серебряного турнира.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Благодаря тебе Кул и другие претенденты снова вернулись в строй, чтобы сражаться с Плетью. К несчастью, нам не впервой спасать этого доблестного мужа от самого себя. Надеюсь, претенденты выберут себе другой пример для подражания.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты освободил Кула и тех безнадежных претендентов?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Нараси Снежной Заре на Ристалище Серебряного турнира в Ледяную Корону.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (14097,'Уберите этого торговца!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уберите этого торговца!',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (14098,'Эвакуация Торговой площади','Теперь здесь стало небезопасно – даже родные стены не могут защитить от беды.$B$BМы пытаемся не пустить воргенов в дома, но их слишком много, и за всеми невозможно уследить.$B$BПомоги нам эвакуировать жителей в тюремный квартал – армия моего отца сможет лучше их защитить.','Помогите эвакуировать людей из 3 домов.','Вернитесь к принцу Лиаму Седогриву на Торговую площадь в Гилнеас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Эвакуация Торговой площади',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь здесь стало небезопасно – даже родные стены не могут защитить от беды.$B$BМы пытаемся не пустить воргенов в дома, но их слишком много, и за всеми невозможно уследить.$B$BПомоги нам эвакуировать жителей в тюремный квартал – армия моего отца сможет лучше их защитить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Помогите эвакуировать людей из 3 домов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к принцу Лиаму Седогриву на Торговую площадь в Гилнеас.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (14099,'Королевский приказ','Теперь тебе тоже пора уходить, $n. Ступай в Военный квартал вместе с остальными жителями.$B$BКак только пересечешь мост, разыщи Гвен Армстед и узнай, все ли прошло благополучно.$B$BА я останусь здесь и буду прикрывать отход вместе со стражниками.$B$BИди же! Это приказ.','Поговорите с Гвен Армстед в северо-восточной части Военного квартала.','Мы в порядке! Все еще с трудом приходим в себя, но живы...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Королевский приказ',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь тебе тоже пора уходить, $n. Ступай в Военный квартал вместе с остальными жителями.$B$BКак только пересечешь мост, разыщи Гвен Армстед и узнай, все ли прошло благополучно.$B$BА я останусь здесь и буду прикрывать отход вместе со стражниками.$B$BИди же! Это приказ.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Гвен Армстед в северо-восточной части Военного квартала.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мы в порядке! Все еще с трудом приходим в себя, но живы...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14100,'Реликвия Служителей Земли','Ты уже многому $gнаучился:научилась;, $n. Теперь, когда тебе подвластны все четыре основных элемента, пора узнать, как сохранять между ними равновесие. Тебе пригодится это знание – потренировавшись, ты сможешь носить с собой только одну реликвию вместо четырех тотемов.$B$BПоговори с Готуром Четыре Ветра на Аллее Мудрости в Оргриммаре и обрети власть над четырьмя стихиями.','Принесите четыре тотема Готуру Четыре Ветра в Оргриммар.','Ах, ты $Gосвоил:освоила; четыре тотема. Ты $Gдолжен:должна; гордиться своими достижениями, юный $R, но это только начало твоего пути.$B$BВот, прими этот дар от Земляного кольца. Носи эту реликвию с собой и в твоем распоряжении будет сила всех четырех стихий.$B$BПродолжай тренироваться, дружище. Перед этим миром предстоят серьезные испытания - я слышу это на ветру и чувствую это в грохоте земли. Мы должны быть готовы к худшему.','Хммм, что заставило тебя обратиться за помощью к Служителям Земли?','Вернитесь к Готуре Четырем Ветрам в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Реликвия Служителей Земли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты уже многому $gнаучился:научилась;, $n. Теперь, когда тебе подвластны все четыре основных элемента, пора узнать, как сохранять между ними равновесие. Тебе пригодится это знание – потренировавшись, ты сможешь носить с собой только одну реликвию вместо четырех тотемов.$B$BПоговори с Готуром Четыре Ветра на Аллее Мудрости в Оргриммаре и обрети власть над четырьмя стихиями.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите четыре тотема Готуру Четыре Ветра в Оргриммар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ах, ты $Gосвоил:освоила; четыре тотема. Ты $Gдолжен:должна; гордиться своими достижениями, юный $R, но это только начало твоего пути.$B$BВот, прими этот дар от Земляного кольца. Носи эту реликвию с собой и в твоем распоряжении будет сила всех четырех стихий.$B$BПродолжай тренироваться, дружище. Перед этим миром предстоят серьезные испытания - я слышу это на ветру и чувствую это в грохоте земли. Мы должны быть готовы к худшему.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Хммм, что заставило тебя обратиться за помощью к Служителям Земли?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Готуре Четырем Ветрам в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (14101,'Дроттинн Хротгар','Квалдиры, морские врайкулы, которые грабят корабли и прибрежные поселения, захватили остров клыкарров, что находится на севере пролива. Их предводитель – бывалый пират Дроттинн Хротгар, который давно уже стремится установить контроль над этими морями.$B$BПока он правит шайкой бандитов, наши корабли и транспортные суда находятся в постоянной опасности. А если мы окажемся отрезанными от остального мира, нам останется только сдаться на милость Королю-личу.$B$BВозьми этот боевой рог Квалдира и отнеси его к кругу клыкаррских статуй на северо-востоке Лагеря Хротгара. С его помощью ты сможешь бросить вызов предводителю квалдиров.','Верховный крестоносец Аделард из Серебряного павильона на Ристалище Серебряного турнира просит вас одолеть Дроттинна Хротгара.','Смерть Дроттинна приведет к стычкам среди квалдиров, стремящихся занять его место, что поможет нам выиграть время. Крестоносцы турнира в долгу у тебя, чемпион.','Вернитесь к верховному крестоносцу Аделарду на Ристалище Серебряного турнира, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дроттинн Хротгар',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Квалдиры, морские врайкулы, которые грабят корабли и прибрежные поселения, захватили остров клыкарров, что находится на севере пролива. Их предводитель – бывалый пират Дроттинн Хротгар, который давно уже стремится установить контроль над этими морями.$B$BПока он правит шайкой бандитов, наши корабли и транспортные суда находятся в постоянной опасности. А если мы окажемся отрезанными от остального мира, нам останется только сдаться на милость Королю-личу.$B$BВозьми этот боевой рог Квалдира и отнеси его к кругу клыкаррских статуй на северо-востоке Лагеря Хротгара. С его помощью ты сможешь бросить вызов предводителю квалдиров.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верховный крестоносец Аделард из Серебряного павильона на Ристалище Серебряного турнира просит вас одолеть Дроттинна Хротгара.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Смерть Дроттинна приведет к стычкам среди квалдиров, стремящихся занять его место, что поможет нам выиграть время. Крестоносцы турнира в долгу у тебя, чемпион.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному крестоносцу Аделарду на Ристалище Серебряного турнира, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (14102,'Призыватель туманов Йингвар','Вернитесь к верховному крестоносцу Аделарду на Ристалище Серебряного турнира, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Призыватель туманов Йингвар',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному крестоносцу Аделарду на Ристалище Серебряного турнира, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (14103,'Титановый порошок','Превосходно! Еще одна порция порошка!$B$BТолько между нами, ювелирами – я знаю, как легко и непринужденно заработать много денег, продавая изделия из "чистого титана" незадачливым даларанским магам. Их великого ума не хватает на то, чтобы экономно относиться к золоту. Так что если добудешь еще порошка – с радостью куплю его у тебя.','Вернитесь к Тимоти Джонсу в Лес Хрустальной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Титановый порошок',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Превосходно! Еще одна порция порошка!$B$BТолько между нами, ювелирами – я знаю, как легко и непринужденно заработать много денег, продавая изделия из "чистого титана" незадачливым даларанским магам. Их великого ума не хватает на то, чтобы экономно относиться к золоту. Так что если добудешь еще порошка – с радостью куплю его у тебя.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тимоти Джонсу в Лес Хрустальной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (14104,'Орнолф Меченый','Орнолф Меченый – безжалостный пират, о котором со страхом отзываются даже его собратья-квалдиры. Он и его команда "Ярости Бора" грабят суда и убивают наших людей.$B$BОрнолф и его бандиты были среди тех, кто принял участие в расправе над обитателями острова клыкарров, который теперь носит название Лагерь Хротгара. Корабль этого пирата стоит на якоре в гавани на востоке этого острова. Возьми этот захваченный флаг и установи его на корабле. Не сомневаюсь, это приведет Орнолфа в ярость, и он попытается лично расправиться с тобой. Удачи!','Верховный крестоносец Аделард из Серебряного павильона на Ристалище Серебряного турнира просит вас одолеть Орнолфа Меченого.','Команда Орнолфа захочет отомстить за своего вождя, но сейчас, когда они остались без предводителя, их будет легко уничтожить. Мы должны выполнить свою миссию и дожить до того дня, когда Ледяная Корона будет очищена от Плети и прочего зла.','Вернитесь к верховному крестоносцу Аделарду на Ристалище Серебряного турнира, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Орнолф Меченый',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Орнолф Меченый – безжалостный пират, о котором со страхом отзываются даже его собратья-квалдиры. Он и его команда "Ярости Бора" грабят суда и убивают наших людей.$B$BОрнолф и его бандиты были среди тех, кто принял участие в расправе над обитателями острова клыкарров, который теперь носит название Лагерь Хротгара. Корабль этого пирата стоит на якоре в гавани на востоке этого острова. Возьми этот захваченный флаг и установи его на корабле. Не сомневаюсь, это приведет Орнолфа в ярость, и он попытается лично расправиться с тобой. Удачи!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верховный крестоносец Аделард из Серебряного павильона на Ристалище Серебряного турнира просит вас одолеть Орнолфа Меченого.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Команда Орнолфа захочет отомстить за своего вождя, но сейчас, когда они остались без предводителя, их будет легко уничтожить. Мы должны выполнить свою миссию и дожить до того дня, когда Ледяная Корона будет очищена от Плети и прочего зла.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному крестоносцу Аделарду на Ристалище Серебряного турнира, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (14105,'Вестник смерти Карос','Культ Проклятых удвоил свои усилия, стремясь к нашему уничтожению. Они обнаглели настолько, что собрали свои силы на западе от Ристалища, на Заставе Вестника Смерти.$B$BВозглавляет их безжалостный Вестник Смерти Карос, и скоро его люди нападут на нас из-за возведенных укрытий.$B$BНаши солдаты и искатели славы готовятся отразить атаку, но только чемпионы могут обезглавить войско противника. Найди Вестника Смерти, $n, и убей его.','Верховный крестоносец Аделард из Серебряного павильона на Ристалище Серебряного турнира просит вас одолеть вестника смерти Кароса.','Ты служишь примером всем, кто собрался под нашими знаменами. Вместе мы покажем Плети, что нас не одолеть!','Вернитесь к верховному крестоносцу Аделарду на Ристалище Серебряного турнира, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вестник смерти Карос',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Культ Проклятых удвоил свои усилия, стремясь к нашему уничтожению. Они обнаглели настолько, что собрали свои силы на западе от Ристалища, на Заставе Вестника Смерти.$B$BВозглавляет их безжалостный Вестник Смерти Карос, и скоро его люди нападут на нас из-за возведенных укрытий.$B$BНаши солдаты и искатели славы готовятся отразить атаку, но только чемпионы могут обезглавить войско противника. Найди Вестника Смерти, $n, и убей его.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верховный крестоносец Аделард из Серебряного павильона на Ристалище Серебряного турнира просит вас одолеть вестника смерти Кароса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты служишь примером всем, кто собрался под нашими знаменами. Вместе мы покажем Плети, что нас не одолеть!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному крестоносцу Аделарду на Ристалище Серебряного турнира, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (14106,'Na Kada\'s Quest Test','Вернитесь к настоящему Ронакаде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Na Kada\'s Quest Test',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к настоящему Ронакаде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14107,'Судьба Павших','Серебряный Авангард – не единственная сила, противостоящая Королю-личу в Ледяной Короне. Но наш враг хочет обратить против нас души павших союзников...$B$BИх духи блуждают по Долине павших героев, на юго-западе от ристалища и к западу от Алдуртара. Земля там буквально усыпана кристаллами душ, которые Плеть использует для подчинения призраков. Собери эти кристаллы и освяти с помощью Благословенной светом реликвии, чтобы даровать покой неприкаянным духам. Они это заслужили.','Крестоносец Серебристый Рассвет из Серебряного павильона просит вас даровать покой 6 духам павших героев.','Вы принесли мир духам павших героев?','Вернитесь к крестоносцу Серебристому Рассвету на Ристалище Серебряного турнира, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Судьба Павших',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Серебряный Авангард – не единственная сила, противостоящая Королю-личу в Ледяной Короне. Но наш враг хочет обратить против нас души павших союзников...$B$BИх духи блуждают по Долине павших героев, на юго-западе от ристалища и к западу от Алдуртара. Земля там буквально усыпана кристаллами душ, которые Плеть использует для подчинения призраков. Собери эти кристаллы и освяти с помощью Благословенной светом реликвии, чтобы даровать покой неприкаянным духам. Они это заслужили.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Крестоносец Серебристый Рассвет из Серебряного павильона просит вас даровать покой 6 духам павших героев.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы принесли мир духам павших героев?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к крестоносцу Серебристому Рассвету на Ристалище Серебряного турнира, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14108,'Изгнать Кракена!','Неужели с кракеном еще не покончено? Поторопись, крестоносец – времени осталось мало!','Вернитесь к крестоносцу Серебристому Рассвету на Ристалище Серебряного турнира, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Изгнать Кракена!',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Неужели с кракеном еще не покончено? Поторопись, крестоносец – времени осталось мало!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к крестоносцу Серебристому Рассвету на Ристалище Серебряного турнира, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (14109,'Новый наряд','Новый наряд? Да ты что?! Твой банкет – настоящее событие! Все сливки общества этого острова соберутся! Прямо-таки взбитые сливки!$B$BНу, что же... удачных покупок! Кстати, лучшие в городе магазины – в Переулке Дельцов.','Купите блестящие украшения у Гэппи Серебряного Зуба, новый стильный костюмчик у Забо и модные темные очки у Миссы Фарцовщицы в переулке Дельцов.','Вернитесь к своей подруге Конфетке в штаб-квартиру ТКК в Кезане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новый наряд',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Новый наряд? Да ты что?! Твой банкет – настоящее событие! Все сливки общества этого острова соберутся! Прямо-таки взбитые сливки!$B$BНу, что же... удачных покупок! Кстати, лучшие в городе магазины – в Переулке Дельцов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Купите блестящие украшения у Гэппи Серебряного Зуба, новый стильный костюмчик у Забо и модные темные очки у Миссы Фарцовщицы в переулке Дельцов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к своей подруге Конфетке в штаб-квартиру ТКК в Кезане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) VALUES (14109,'Как отоварился, Джиксид? Жуть, как хочется увидеть новый наряд на тебе!$B$BНадеюсь, это того стоит.') ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как отоварился, Джиксид? Жуть, как хочется увидеть новый наряд на тебе!$B$BНадеюсь, это того стоит.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14110,'Новый наряд','Новый наряд? Да ты что?! Твой банкет – настоящее событие! Все сливки общества этого острова соберутся! Прямо-таки взбитые сливки!$B$BНу, что же... удачных покупок! Кстати, лучшие в городе магазины – в Переулке Дельцов.','Купите блестящие украшения у Гэппи Серебряного Зуба, новый стильный костюмчик у Забо и модные темные очки у Миссы Фарцовщицы в переулке Дельцов.','О да, ты всех сразишь своим видом! С твоей-то прытью уже со дня на день займешь место торгового принца, помяни мое слово.$B$BТы уж меня не забудь, когда это случится!$B$BДавай я тебе помогу одеться.','Ну что, закупилась? Уже хочу посмотреть на тебя в новом прикиде. Прям жду не дождусь!$B$BЭто будет что-то с чем-то!','Вернитесь к Чипу Идейлу в штаб-квартиру ТКК на Кезане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новый наряд',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Новый наряд? Да ты что?! Твой банкет – настоящее событие! Все сливки общества этого острова соберутся! Прямо-таки взбитые сливки!$B$BНу, что же... удачных покупок! Кстати, лучшие в городе магазины – в Переулке Дельцов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Купите блестящие украшения у Гэппи Серебряного Зуба, новый стильный костюмчик у Забо и модные темные очки у Миссы Фарцовщицы в переулке Дельцов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О да, ты всех сразишь своим видом! С твоей-то прытью уже со дня на день займешь место торгового принца, помяни мое слово.$B$BТы уж меня не забудь, когда это случится!$B$BДавай я тебе помогу одеться.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, закупилась? Уже хочу посмотреть на тебя в новом прикиде. Прям жду не дождусь!$B$BЭто будет что-то с чем-то!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Чипу Идейлу в штаб-квартиру ТКК на Кезане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14111,'Реликвия Служителей Земли','Ты уже многому $gнаучился:научилась;, $n. Теперь, когда тебе подвластны все четыре основных элемента, пора узнать, как сохрянять между ними равновесие. Тебе пригодится это знание – потренировавшись, ты сможешь носить с собой только одну реликвию вместо четырех тотемов.$B$BПоговори с Предсказателем Эанну в Стальгорне возле Великой Кузни – он поможет тебе отточить мастерство в повелевании стихиями.','Принесите четыре тотема Предсказателю Эанну в Стальгорн.','Ах, ты $Gосвоил:освоила; четыре тотема. Ты $Gдолжен:должна; гордиться своими достижениями, юный $R, но это только начало твоего пути.$B$BВот, прими этот дар от Земляного кольца. Носи эту реликвию с собой и в твоем распоряжении будет сила всех четырех стихий.$B$BТвое обучение должно продолжаться! Я чувствую, что этому миру предстоит немало испытаний и нам понадобится сила стоящих за нами стихий, если мы хотим победить.','Духи шевелятся внутри вас. Что заставило вас обратиться за помощью к Служителям Земли?','Вернитесь к предсказателю Эанну в Дун Морог.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Реликвия Служителей Земли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты уже многому $gнаучился:научилась;, $n. Теперь, когда тебе подвластны все четыре основных элемента, пора узнать, как сохрянять между ними равновесие. Тебе пригодится это знание – потренировавшись, ты сможешь носить с собой только одну реликвию вместо четырех тотемов.$B$BПоговори с Предсказателем Эанну в Стальгорне возле Великой Кузни – он поможет тебе отточить мастерство в повелевании стихиями.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите четыре тотема Предсказателю Эанну в Стальгорн.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ах, ты $Gосвоил:освоила; четыре тотема. Ты $Gдолжен:должна; гордиться своими достижениями, юный $R, но это только начало твоего пути.$B$BВот, прими этот дар от Земляного кольца. Носи эту реликвию с собой и в твоем распоряжении будет сила всех четырех стихий.$B$BТвое обучение должно продолжаться! Я чувствую, что этому миру предстоит немало испытаний и нам понадобится сила стоящих за нами стихий, если мы хотим победить.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Духи шевелятся внутри вас. Что заставило вас обратиться за помощью к Служителям Земли?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к предсказателю Эанну в Дун Морог.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (14112,'Кстати, чем питаются йети?','Рыцари поймали огромного йети по кличке Ледяной Рев, который будет участвовать в гладиаторских боях, и поручили нам тренировать и кормить его.$B$BЖаль, им не понравилась моя идея отдать ему на растерзание парочку Похитителей Солнца. Эта тварь предпочитает мясо акул, так что тебе придется отправиться за ним на "Серебряный Клинок", который стоит на якоре к северу пролива. Возьми свежую наживку из бочек на борту и брось ее в воду – она привлечет внимание акул.','Савиния Певица Преданий из Павильона Серебряного союза на Ристалище Серебряного турнира просит вас принести ей 3 куска мяса акулы Северного моря.','Я рада, что мы справились с этой задачей. Пусть это была не самая почетная миссия на свете, но раз уж мы заключили договор с Серебряным Авангардом, мы должны выполнять все, что они от нас потребуют. Во всяком случае, это выгодно отличает нас от Похитителей Солнца.','Вернитесь к Савинии Певице Преданий на Ристалище Серебряного турнира, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кстати, чем питаются йети?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Рыцари поймали огромного йети по кличке Ледяной Рев, который будет участвовать в гладиаторских боях, и поручили нам тренировать и кормить его.$B$BЖаль, им не понравилась моя идея отдать ему на растерзание парочку Похитителей Солнца. Эта тварь предпочитает мясо акул, так что тебе придется отправиться за ним на "Серебряный Клинок", который стоит на якоре к северу пролива. Возьми свежую наживку из бочек на борту и брось ее в воду – она привлечет внимание акул.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Савиния Певица Преданий из Павильона Серебряного союза на Ристалище Серебряного турнира просит вас принести ей 3 куска мяса акулы Северного моря.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я рада, что мы справились с этой задачей. Пусть это была не самая почетная миссия на свете, но раз уж мы заключили договор с Серебряным Авангардом, мы должны выполнять все, что они от нас потребуют. Во всяком случае, это выгодно отличает нас от Похитителей Солнца.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Савинии Певице Преданий на Ристалище Серебряного турнира, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (14113,'Банкет','Ничего себе! Да тут собрался весь цвет кезанского общества! Кому какое дело до дракона?$B$BМы решили устроить банкет у бассейна. Гости, похоже, довольны. И все ждут тебя!$B$BТак что давай наряжайся, иди к бассейну и общайся с гостями. Я тоже скоро приду... но сначала мне надо кое-что сделать.','Наденьте свой потрясный прикид для вечеринки (темные очки, новый стильный костюмчик и блестящие украшения) и отправляйтесь развлекать 10 кутил из Кезана, собравшихся у бассейна в штаб-квартире ТКК.','Как все здорово получилось. Банкет удался на славу!$B$BЭ... Что это?','Вернитесь к Хамми Кофельнагель в штаб-квартиру ТКК на Кезане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Банкет',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ничего себе! Да тут собрался весь цвет кезанского общества! Кому какое дело до дракона?$B$BМы решили устроить банкет у бассейна. Гости, похоже, довольны. И все ждут тебя!$B$BТак что давай наряжайся, иди к бассейну и общайся с гостями. Я тоже скоро приду... но сначала мне надо кое-что сделать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Наденьте свой потрясный прикид для вечеринки (темные очки, новый стильный костюмчик и блестящие украшения) и отправляйтесь развлекать 10 кутил из Кезана, собравшихся у бассейна в штаб-квартире ТКК.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Как все здорово получилось. Банкет удался на славу!$B$BЭ... Что это?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хамми Кофельнагель в штаб-квартиру ТКК на Кезане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (14114,'The New You (Tracking Event)') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','The New You (Tracking Event)',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (14115,'Пираты-наемники','Убейте 12 пиратов-наемников, чтобы спасти свою карьеру.','Да, впечатляюще. Но, боюсь, у меня есть и другие не слишком приятные новости.$B$BТолько сразу меня не убивай...','Вернитесь к Хамми Кофельнагель в штаб-квартиру ТКК на Кезане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пираты-наемники',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 пиратов-наемников, чтобы спасти свою карьеру.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, впечатляюще. Но, боюсь, у меня есть и другие не слишком приятные новости.$B$BТолько сразу меня не убивай...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хамми Кофельнагель в штаб-квартиру ТКК на Кезане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (14116,'Незваный гость','Пока ты там $gразбирался:разбиралась; с пиратами, я видела торгового принца. Он потихоньку поднялся по лестнице. Думал, наверное, его никто не заметит. Он сейчас на балконе на верхней площадке.$B$B$n, я думаю, это он подослал пиратов.$B$B<Хамми морщится.>$B$BТебе надо подняться наверх. И как можно скорее! Нельзя заставлять его ждать.','Поговорите с торговым принцем Галливиксом на верхнем этаже штаб-квартиры ТКК на Кезане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Незваный гость',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пока ты там $gразбирался:разбиралась; с пиратами, я видела торгового принца. Он потихоньку поднялся по лестнице. Думал, наверное, его никто не заметит. Он сейчас на балконе на верхней площадке.$B$B$n, я думаю, это он подослал пиратов.$B$B<Хамми морщится.>$B$BТебе надо подняться наверх. И как можно скорее! Нельзя заставлять его ждать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с торговым принцем Галливиксом на верхнем этаже штаб-квартиры ТКК на Кезане.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (14117,'Глаза Ясеневого леса','Кругом враги, |3-6($c), даже тут, у самых наших дверей. Ночные эльфы прислали подкрепление на заставу Талрендис, пытаясь оcтановить наше вторжение в Ясеневый лес. В то время, как мы разговариваем, их разведчики прочесывают близлежащие холмы, докладывая о каждом движении у врат.$b$bНадо избавиться от этих глаз Ясеневого леса.$b$bИди. Они бродят возле врат, больше всего их в восточной части. Убей разведчиков, которые следят за нами!','Убейте 8 разведчиков с заставы Талрендис.','Отлично! Их разведчики не смогут доставить донесения, и Талрендис станет жертвой такого же террора, какому они пытались подвергнуть нас.','Вернитесь к Аг\'тору Кровопалу к задним вратам Оргриммара в Азшаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Глаза Ясеневого леса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кругом враги, |3-6($c), даже тут, у самых наших дверей. Ночные эльфы прислали подкрепление на заставу Талрендис, пытаясь оcтановить наше вторжение в Ясеневый лес. В то время, как мы разговариваем, их разведчики прочесывают близлежащие холмы, докладывая о каждом движении у врат.$b$bНадо избавиться от этих глаз Ясеневого леса.$b$bИди. Они бродят возле врат, больше всего их в восточной части. Убей разведчиков, которые следят за нами!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 разведчиков с заставы Талрендис.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! Их разведчики не смогут доставить донесения, и Талрендис станет жертвой такого же террора, какому они пытались подвергнуть нас.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аг\'тору Кровопалу к задним вратам Оргриммара в Азшаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (14118,'Оленина для солдат','Из-за того, что мы истратили все ресурсы этих земель на наши боевые машины, местным животным негде жить. Они в любом случае умрут, поэтому пусть хотя бы их мясо не пропадет даром. Желудки воинов Оргриммара совершенно пусты.$b$bПоохоться на ослабших мохоногих маралов в округе и запасись их мясом для нашей пехоты.','Соберите 15 больших кусков оленины, убив ослабших мохоногих маралов.','Мясо – и много! Замечательно. Теперь нам не придется строить арсенал на голодный желудок.','Принесите оленину Аг\'тору Кровопалу к задним вратам Оргриммара в Азшаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оленина для солдат',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Из-за того, что мы истратили все ресурсы этих земель на наши боевые машины, местным животным негде жить. Они в любом случае умрут, поэтому пусть хотя бы их мясо не пропадет даром. Желудки воинов Оргриммара совершенно пусты.$b$bПоохоться на ослабших мохоногих маралов в округе и запасись их мясом для нашей пехоты.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 15 больших кусков оленины, убив ослабших мохоногих маралов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мясо – и много! Замечательно. Теперь нам не придется строить арсенал на голодный желудок.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите оленину Аг\'тору Кровопалу к задним вратам Оргриммара в Азшаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (14119,'Blank [PH]','Вернитесь к Линзи Черноболт на Железную плотину, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Blank [PH]',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Линзи Черноболт на Железную плотину, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (14120,'Миллиард деревянных?!','Ты весьма $gчестолюбивый юнец:честолюбивая девушка;, $n. Может быть, даже чересчур, а это, знаешь ли, не всегда хорошо. Хотя в твоем возрасте я был точно таким же, так что ты – это я, только моложе.$B$BУ меня к тебе предложение. Ты, должно быть, $gзаметил:заметила;, что из-за твоего дракона началось извержение Каджаро. Все, кто останется на Кезане, умрут! Но если ты принесешь мне миллиард деревянных до того, как моя яхта отчалит от острова, я позабочусь о том, чтобы ты $gоказался:оказалась; в числе немногих спасшихся счастливцев.$B$BВ общем так – хочешь жить, думай, где достать бабки!','Поговорите с Хамми Кофельнагель в штаб-квартире ТКК на Кезане.','Миллиард деревянных?! Где мы возьмем столько денег?$B$B<Хамми на мгновение задумывается.>$B$BТак... А торговый принц, когда предлагал тебе бежать на его яхте, про меня что-нибудь говорил? Ну, что меня тоже возьмут.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Миллиард деревянных?!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты весьма $gчестолюбивый юнец:честолюбивая девушка;, $n. Может быть, даже чересчур, а это, знаешь ли, не всегда хорошо. Хотя в твоем возрасте я был точно таким же, так что ты – это я, только моложе.$B$BУ меня к тебе предложение. Ты, должно быть, $gзаметил:заметила;, что из-за твоего дракона началось извержение Каджаро. Все, кто останется на Кезане, умрут! Но если ты принесешь мне миллиард деревянных до того, как моя яхта отчалит от острова, я позабочусь о том, чтобы ты $gоказался:оказалась; в числе немногих спасшихся счастливцев.$B$BВ общем так – хочешь жить, думай, где достать бабки!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Хамми Кофельнагель в штаб-квартире ТКК на Кезане.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Миллиард деревянных?! Где мы возьмем столько денег?$B$B<Хамми на мгновение задумывается.>$B$BТак... А торговый принц, когда предлагал тебе бежать на его яхте, про меня что-нибудь говорил? Ну, что меня тоже возьмут.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14121,'Грабь награбленное','Мы все умрем!!!$B$B<Вы даете Мегз пощечину, чтобы прекратить истерику.>$B$BПрошу прощения, $gгосподин:госпожа; $n. Этого больше не повторится. Так... надо срочно придумать, где взять столько денег.$B$BГоворят, торговый принц нанял грабителей, и те уже бесчинствуют на улицах.$B$BСадись в свой хотрод и поезжай в город. Дави их без жалости, этих грабителей. А заодно собирай все добро, что они успели награбить. По-моему, это будет лишь справедливо.','Садитесь в хотрод, задавите 12 наемных грабителей и заберите у каждого украденные им вещи.','Что, правда?! Ты их всех задавил? Ну, что же... так и им и надо.$B$BСлушай, тут же куча добра. Думаешь, этого хватит, чтобы купить тебе место на яхте торгового принца?$B$BА ты можешь кого-нибудь взять с собой? А то меня как-то уже не прельщает заниматься маркетингом... как ни кручусь, все гроши зарабатываю.','Ну что, награбил награбленное?','Вернитесь к Мегз Жестекрошшер в штаб-квартиру ТКК на Кезане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Грабь награбленное',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы все умрем!!!$B$B<Вы даете Мегз пощечину, чтобы прекратить истерику.>$B$BПрошу прощения, $gгосподин:госпожа; $n. Этого больше не повторится. Так... надо срочно придумать, где взять столько денег.$B$BГоворят, торговый принц нанял грабителей, и те уже бесчинствуют на улицах.$B$BСадись в свой хотрод и поезжай в город. Дави их без жалости, этих грабителей. А заодно собирай все добро, что они успели награбить. По-моему, это будет лишь справедливо.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Садитесь в хотрод, задавите 12 наемных грабителей и заберите у каждого украденные им вещи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что, правда?! Ты их всех задавил? Ну, что же... так и им и надо.$B$BСлушай, тут же куча добра. Думаешь, этого хватит, чтобы купить тебе место на яхте торгового принца?$B$BА ты можешь кого-нибудь взять с собой? А то меня как-то уже не прельщает заниматься маркетингом... как ни кручусь, все гроши зарабатываю.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, награбил награбленное?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мегз Жестекрошшер в штаб-квартиру ТКК на Кезане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14122,'Ограбление банка','Все твои счета заморожены, а Первый банк Кезана закрылся!$B$BТебе нужна куча денег. А где их взять? Думаю, надо просто забрать свои деньги из банка! В твоем гоблинском все-в-одном-чудо-поясе столько всяких полезных приспособлений. Наверняка там найдется какой-нибудь инструмент, чтобы вскрыть дверь в хранилище.$B$BНадеюсь, ты $gслушал:слушала; мои советы и $gотложил:отложила; энную сумму на черный день. Потому что сегодня – самый что ни на есть черный день. Хотя и подсвеченный раскаленной магмой!!!','Взломайте хранилище Первого банка Кезана и заберите свои личные сбережения.','Стало быть, ты не транжирил средства! Я тобой горжусь!$B$B<Хамми считает ваши деревянные.>$B$BЭ... слушай... но этого мало.','Ну что, получилось? Ты забрал свои личные сбережения из банка?','Вернитесь к Хамми Кофельнагель в штаб-квартиру ТКК на Кезане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ограбление банка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Все твои счета заморожены, а Первый банк Кезана закрылся!$B$BТебе нужна куча денег. А где их взять? Думаю, надо просто забрать свои деньги из банка! В твоем гоблинском все-в-одном-чудо-поясе столько всяких полезных приспособлений. Наверняка там найдется какой-нибудь инструмент, чтобы вскрыть дверь в хранилище.$B$BНадеюсь, ты $gслушал:слушала; мои советы и $gотложил:отложила; энную сумму на черный день. Потому что сегодня – самый что ни на есть черный день. Хотя и подсвеченный раскаленной магмой!!!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Взломайте хранилище Первого банка Кезана и заберите свои личные сбережения.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Стало быть, ты не транжирил средства! Я тобой горжусь!$B$B<Хамми считает ваши деревянные.>$B$BЭ... слушай... но этого мало.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, получилось? Ты забрал свои личные сбережения из банка?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хамми Кофельнагель в штаб-квартиру ТКК на Кезане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14123,'Антикварные ценности','Есть всего один способ достать миллиард деревянных: украсть у богатых!$B$BЭтот мерзавец торговый принц награбил целые горы всевозможного антиквариата и дорогущих предметов искусства. Давно пора отобрать у него эти ценности и отдать их бедным... например, нам!$B$BСейчас мы тебя замаскируем под одного из прихлебателей Галливикса. А потом ты спокойненько зайдешь на виллу торгового принца и "приберешь" антикварные ценности.$B$BТолько старайся не приближаться к его свиньям. Они чуют чужих. Их не обманешь никакой маскировкой!','Раздобудьте "Ястреба Малди", "Гоблину Лизу" и "Платиновую бомбу".','Ух ты! Да они стоят целое состояние!$B$B<Крадли жадно разглядывает вашу добычу.>$B$BОстается надеяться, что торговый принц их не признает, когда ты будешь ему отдавать все богатства...','Ну что, забрал ценности?','Вернитесь к Крадли Дротик в штаб-квартиру ТКК на Кезане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Антикварные ценности',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Есть всего один способ достать миллиард деревянных: украсть у богатых!$B$BЭтот мерзавец торговый принц награбил целые горы всевозможного антиквариата и дорогущих предметов искусства. Давно пора отобрать у него эти ценности и отдать их бедным... например, нам!$B$BСейчас мы тебя замаскируем под одного из прихлебателей Галливикса. А потом ты спокойненько зайдешь на виллу торгового принца и "приберешь" антикварные ценности.$B$BТолько старайся не приближаться к его свиньям. Они чуют чужих. Их не обманешь никакой маскировкой!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте "Ястреба Малди", "Гоблину Лизу" и "Платиновую бомбу".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ух ты! Да они стоят целое состояние!$B$B<Крадли жадно разглядывает вашу добычу.>$B$BОстается надеяться, что торговый принц их не признает, когда ты будешь ему отдавать все богатства...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, забрал ценности?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Крадли Дротик в штаб-квартиру ТКК на Кезане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14124,'Каджа\'митовые месторождения','Нам нужна куча денег, чтобы расплатиться с торговым принцем и убраться с Кезана подобру-поздорову! И эти деньги – буквально у нас под ногами, в Каджа\'митовой шахте. Подходи и бери!$B$BПоследние из известных нам каджа\'митовых месторождений остались как раз на Кезане. Они здесь повсюду, куда ни плюнь. Собственно, благодаря им мы и стали гениальнейшими механиками и алхимиками. Если эти месторождения не стоят миллиарда деревянных, тогда я даже не знаю, что может стоить...$B$BВозьми у меня разрывные бомбы, подорви ближайшее месторождение и собери разлетевшиеся куски.$B$BТолько будь $gосторожен:осторожна;. Берегись бунтующих троллей!','Соберите 12 кусков каджа\'мита.','Отлично, отлично! У тебя в мешках – целое состояние.$B$BКогда торговый принц это увидит, держу пари, он нас всех возьмет на свою яхту!','Сколько ты уже собрал?','Вернитесь к штейгеру Промокаху в штаб-квартиру ТКК на Кезане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Каджа\'митовые месторождения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нам нужна куча денег, чтобы расплатиться с торговым принцем и убраться с Кезана подобру-поздорову! И эти деньги – буквально у нас под ногами, в Каджа\'митовой шахте. Подходи и бери!$B$BПоследние из известных нам каджа\'митовых месторождений остались как раз на Кезане. Они здесь повсюду, куда ни плюнь. Собственно, благодаря им мы и стали гениальнейшими механиками и алхимиками. Если эти месторождения не стоят миллиарда деревянных, тогда я даже не знаю, что может стоить...$B$BВозьми у меня разрывные бомбы, подорви ближайшее месторождение и собери разлетевшиеся куски.$B$BТолько будь $gосторожен:осторожна;. Берегись бунтующих троллей!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 12 кусков каджа\'мита.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, отлично! У тебя в мешках – целое состояние.$B$BКогда торговый принц это увидит, держу пари, он нас всех возьмет на свою яхту!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Сколько ты уже собрал?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к штейгеру Промокаху в штаб-квартиру ТКК на Кезане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (14125,'Страховочный план','У нас уже целая куча деревянных, но этого все равно мало. Но на этот случай у меня есть план! Здание штаба застраховано, и если вдруг что случится, мы получим страховку.$B$BПосле банкета остались фейерверки, и я разложила их по всему зданию. Тебе только и нужно, что зайти в штаб и устроить маленькую диверсию.$B$BПредлагаю следующую огнеопасную комбинацию: неисправный генератор, прохудившаяся печка и легковоспламеняющаяся кровать. А потом просто выходишь наружу и посылаешь в здание газобота.$B$BПлан идеальный, а главное – надежный!','Устройте перегрузку барахлящего генератора, включите прохудившуюся печку, уроните сигару на легковоспламеняющуюся кровать и запустите газобота, чтобы поджечь штаб-квартиру ТКК!','Поговорите с оценщиком из страховой компании в штаб-квартире ТКК на Кезане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Страховочный план',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У нас уже целая куча деревянных, но этого все равно мало. Но на этот случай у меня есть план! Здание штаба застраховано, и если вдруг что случится, мы получим страховку.$B$BПосле банкета остались фейерверки, и я разложила их по всему зданию. Тебе только и нужно, что зайти в штаб и устроить маленькую диверсию.$B$BПредлагаю следующую огнеопасную комбинацию: неисправный генератор, прохудившаяся печка и легковоспламеняющаяся кровать. А потом просто выходишь наружу и посылаешь в здание газобота.$B$BПлан идеальный, а главное – надежный!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Устройте перегрузку барахлящего генератора, включите прохудившуюся печку, уроните сигару на легковоспламеняющуюся кровать и запустите газобота, чтобы поджечь штаб-квартиру ТКК!',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с оценщиком из страховой компании в штаб-квартире ТКК на Кезане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (14126,'Сбережения','Ну вот, мы набрали нужную сумму. Осталось только добраться до яхты торгового принца. Она уже готовится выйти из порта!$B$BНам надо поторопиться. Давай, забирайся в машину. Я – за рулем!','Отдайте ваши сбережения торговому принцу Галливиксу на борту его яхты на Кезане.','Мои поздравления, у тебя все получилось. Вижу, ты принесла все, о чем я просил, включая и твой хотрод.$B$B<Торговый принц злобно усмехается.>$B$BМиллиард деревянных – солидная сумма. На дороге точно не валяется. Теперь я самый богатый и самый могущественный гоблин во всем Азероте! Но самое ПЕЧАЛЬНОЕ В ЭТОМ ДЛЯ ТЕБЯ – ЭТО ТО, ЧТО Я ИЗМЕНЯЮ УСЛОВИЯ СДЕЛКИ. Отныне ты моя рабыня. Спускайся в трюм и принимайся кидать уголь в печь. Следующая остановка: Азшара!$B$BХа-ха-ха!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сбережения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну вот, мы набрали нужную сумму. Осталось только добраться до яхты торгового принца. Она уже готовится выйти из порта!$B$BНам надо поторопиться. Давай, забирайся в машину. Я – за рулем!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отдайте ваши сбережения торговому принцу Галливиксу на борту его яхты на Кезане.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мои поздравления, у тебя все получилось. Вижу, ты принесла все, о чем я просил, включая и твой хотрод.$B$B<Торговый принц злобно усмехается.>$B$BМиллиард деревянных – солидная сумма. На дороге точно не валяется. Теперь я самый богатый и самый могущественный гоблин во всем Азероте! Но самое ПЕЧАЛЬНОЕ В ЭТОМ ДЛЯ ТЕБЯ – ЭТО ТО, ЧТО Я ИЗМЕНЯЮ УСЛОВИЯ СДЕЛКИ. Отныне ты моя рабыня. Спускайся в трюм и принимайся кидать уголь в печь. Следующая остановка: Азшара!$B$BХа-ха-ха!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (14127,'Возвращение высокорожденных?','Восковая печать на этих приказах недавно была сломана. Аккуратные записи карандашом, которые делали ночные эльфы, прочесть невозможно, но на небольшой от руки нарисованной карте изображены близлежащие руины. Ниже карты видны руны, написанные металлическими мерцающими чернилами.$b$bНет никаких сомнений, что Аг\'тору будет интересно на это взглянуть.','Доставьте приказы разведчика Аг\'тору Кровопалу к задним вратам Оргриммара.','<Аг\'тор, прищурясь, смотрит на пергамент, повернув его к свету.>$B$BНет, я тоже не понимаю, что тут написано. Но мне не нравится то, что я здесь вижу. Это чародейские руны?$B$BМне нужно, чтобы ты отнес это специалисту.','Отнесите приказы разведчика Аг\'тору Кровопалу к задним вратам Оргриммара в Азшаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение высокорожденных?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Восковая печать на этих приказах недавно была сломана. Аккуратные записи карандашом, которые делали ночные эльфы, прочесть невозможно, но на небольшой от руки нарисованной карте изображены близлежащие руины. Ниже карты видны руны, написанные металлическими мерцающими чернилами.$b$bНет никаких сомнений, что Аг\'тору будет интересно на это взглянуть.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте приказы разведчика Аг\'тору Кровопалу к задним вратам Оргриммара.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Аг\'тор, прищурясь, смотрит на пергамент, повернув его к свету.>$B$BНет, я тоже не понимаю, что тут написано. Но мне не нравится то, что я здесь вижу. Это чародейские руны?$B$BМне нужно, чтобы ты отнес это специалисту.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите приказы разведчика Аг\'тору Кровопалу к задним вратам Оргриммара в Азшаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14128,'Возвращение высокорожденных?','Наши союзники эльфы крови осматривали изображенные на этой карте руины, и, вероятно, смогут понять эти таинственные записи. Найди среди них ту, кого зовут Малинея Опустошительница Небес. Она проводит исследования на оргриммарской пересадочной станции ракетной дороги к северу отсюда – это часть новой транспортной системы гоблинов, которая, извиваясь, проходит через эти земли. Давай, поторапливайся!','Доставьте приказы разведчика Малинее Опустошительнице Небес на оргриммарскую пересадочную станцию ракетной дороги.','Что? Дай это сюда, сейчас же! Аг\'тор прав, это чародейские руны. Они исследуют магические места? Экспериментируют с тайной магией? Это идет вразрез с тысячелетней историей ночных эльфов.$B$BПфф! Думать, что они станут компетентными в этой области, – даже те, кто считался когда-то высокорожденными, – это же абсурд.$B$B<Малинея презрительно отбрасывает свиток в сторону, но на ее лице появляется тень беспокойства.>','Надеюсь, ты отвлек меня ради чего-то серьезного?','Доставьте приказы разведчика Малинее Опустошительнице Небес на оргриммарскую пересадочную станцию ракетной дороги в Азшаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение высокорожденных?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наши союзники эльфы крови осматривали изображенные на этой карте руины, и, вероятно, смогут понять эти таинственные записи. Найди среди них ту, кого зовут Малинея Опустошительница Небес. Она проводит исследования на оргриммарской пересадочной станции ракетной дороги к северу отсюда – это часть новой транспортной системы гоблинов, которая, извиваясь, проходит через эти земли. Давай, поторапливайся!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте приказы разведчика Малинее Опустошительнице Небес на оргриммарскую пересадочную станцию ракетной дороги.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что? Дай это сюда, сейчас же! Аг\'тор прав, это чародейские руны. Они исследуют магические места? Экспериментируют с тайной магией? Это идет вразрез с тысячелетней историей ночных эльфов.$B$BПфф! Думать, что они станут компетентными в этой области, – даже те, кто считался когда-то высокорожденными, – это же абсурд.$B$B<Малинея презрительно отбрасывает свиток в сторону, но на ее лице появляется тень беспокойства.>',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Надеюсь, ты отвлек меня ради чего-то серьезного?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доставьте приказы разведчика Малинее Опустошительнице Небес на оргриммарскую пересадочную станцию ракетной дороги в Азшаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (14130,'Друзья бывают разных цветов','Меня и моих братьев преследуют.$b$bНедавно убили нашего вожака, а сейчас черные драконы ищут тех из нас, кто остался в живых. Я здесь, чтобы найти Азурегоса и переправить его в безопасное место, если только он даст возможность это сделать.$b$bУ Азурегоса мало друзей и выбирает он их немного... странным образом. Единственный, кого я здесь знаю, это мурлок по имени Эргл. Ты сможешь найти его на берегу к северо-востоку отсюда.$b$bСделай все возможное, чтобы найти Азурегоса и прислать его ко мне.$b$bПожалуйста, торопись.','Найдите Эргла в руинах храма Арккоран.','Привет! Новый друг! Так рад тебя видеть. Меня зовут Эргл. Для удобства "г" можно не произносить.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Друзья бывают разных цветов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Меня и моих братьев преследуют.$b$bНедавно убили нашего вожака, а сейчас черные драконы ищут тех из нас, кто остался в живых. Я здесь, чтобы найти Азурегоса и переправить его в безопасное место, если только он даст возможность это сделать.$b$bУ Азурегоса мало друзей и выбирает он их немного... странным образом. Единственный, кого я здесь знаю, это мурлок по имени Эргл. Ты сможешь найти его на берегу к северо-востоку отсюда.$b$bСделай все возможное, чтобы найти Азурегоса и прислать его ко мне.$b$bПожалуйста, торопись.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Эргла в руинах храма Арккоран.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Привет! Новый друг! Так рад тебя видеть. Меня зовут Эргл. Для удобства "г" можно не произносить.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14131,'Собери мне чуть-чуть','Азурегос... Азурегос. Азу? Дракон? Да, мы с ним друзья! Он научил меня говорить. Говорил, что ему нравится мой цвет... можно подумать, он художник, да?$b$bНе помню, куда он пошел. Ммм... у меня что-то с памятью.$b$bЯ засадил весь пляж растениями кауфи. Они любят песок. Это странно.$b$bМожешь собрать их?','Соберите 10 бобов кауфи с растений в руинах храма Арккоран.','Красивые бобы! Они так вкусно пахнут, да?','Так устал, так трудно сосредоточиться.','Вернитесь к Эрглу на берег в руины храма Арккоран.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Собери мне чуть-чуть',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Азурегос... Азурегос. Азу? Дракон? Да, мы с ним друзья! Он научил меня говорить. Говорил, что ему нравится мой цвет... можно подумать, он художник, да?$b$bНе помню, куда он пошел. Ммм... у меня что-то с памятью.$b$bЯ засадил весь пляж растениями кауфи. Они любят песок. Это странно.$b$bМожешь собрать их?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 бобов кауфи с растений в руинах храма Арккоран.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Красивые бобы! Они так вкусно пахнут, да?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Так устал, так трудно сосредоточиться.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Эрглу на берег в руины храма Арккоран.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (14132,'Это просто невежливо!','Если бы они попросили, я бы поделился. А они просто стали рвать и крошить мои растения кауфи. Это невежливо! Тебе надо научить их, как себя вести.$b$bПусть макринни замолчат.','Убейте 10 макринни в руинах храма Арккоран.','Слишком жестоко? Нет, не слишком. Они это заслужили.$B$BЯ их растения не портил. Никогда.','Вернитесь к Эрглу на берег в руины храма Арккоран.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Это просто невежливо!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если бы они попросили, я бы поделился. А они просто стали рвать и крошить мои растения кауфи. Это невежливо! Тебе надо научить их, как себя вести.$b$bПусть макринни замолчат.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 макринни в руинах храма Арккоран.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Слишком жестоко? Нет, не слишком. Они это заслужили.$B$BЯ их растения не портил. Никогда.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Эрглу на берег в руины храма Арккоран.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`) VALUES (14133,'Путь к сердцу мага','Теперь, когда ты $gвыполнил:выполнила; поручения Эргла, он расскажет тебе об Азурегосе. Поговори с ним, может быть, узнаешь что-нибудь полезное о возможном местонахождении Азурегоса.','Спросите Эргла об Азурегосе.','Спросите Эргла об Азурегосе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путь к сердцу мага',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда ты $gвыполнил:выполнила; поручения Эргла, он расскажет тебе об Азурегосе. Поговори с ним, может быть, узнаешь что-нибудь полезное о возможном местонахождении Азурегоса.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Спросите Эргла об Азурегосе.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Спросите Эргла об Азурегосе.',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (14134,'Древесина для подрядчика','Теперь, когда ты $gнаучился:научилась; управлять этой штукой, давай сделаем то, что должен был делать я, – заготовим древесину. Иначе эти орки построят катапульту из МЕНЯ!$b$bВ этой области много спиленных деревьев. Воспользуйся крошшером и собери столько, сколько сможешь.','Воспользуйтесь перепрограммированным крошшером, чтобы собрать 6 штабелей азшарской древесины. Если вы потеряете свой крошшер, можно поймать и перепрограммировать другой.','Воспользуйтесь перепрограммированным крошшером, чтобы собрать 6 азшарских штабелей пиломатериалов. Если вы потеряете свой крошшер, можно поймать и перепрограммировать другой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Древесина для подрядчика',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда ты $gнаучился:научилась; управлять этой штукой, давай сделаем то, что должен был делать я, – заготовим древесину. Иначе эти орки построят катапульту из МЕНЯ!$b$bВ этой области много спиленных деревьев. Воспользуйся крошшером и собери столько, сколько сможешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь перепрограммированным крошшером, чтобы собрать 6 штабелей азшарской древесины. Если вы потеряете свой крошшер, можно поймать и перепрограммировать другой.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Воспользуйтесь перепрограммированным крошшером, чтобы собрать 6 азшарских штабелей пиломатериалов. Если вы потеряете свой крошшер, можно поймать и перепрограммировать другой.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (14135,'На деревья','Замри на секундочку, я подключу циркулярную пилу.$b$bСнайперы ночных эльфов с заставы Талрендис прячутся в деревьях и стреляют в моих рабочих. Я хочу, чтобы ты $gзанялся:занялась; этими снайперами... предварительно занявшись деревьями. Поищи азшарские молодые деревца восточнее главных ворот. Твой крошшер сам поймет, что ему делать. Поруби их!','Воспользуйтесь циркулярной пилой крошшера, чтобы спилить азшарские молодые деревца и убейте 9 снайперов с заставы Талрендис, когда они появятся.','Воспользуйтесь циркулярной пилой крошшера, чтобы спилить азшарские деревца и убейте 9 снайперов с заставы Талрендис, когда они появятся.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На деревья',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Замри на секундочку, я подключу циркулярную пилу.$b$bСнайперы ночных эльфов с заставы Талрендис прячутся в деревьях и стреляют в моих рабочих. Я хочу, чтобы ты $gзанялся:занялась; этими снайперами... предварительно занявшись деревьями. Поищи азшарские молодые деревца восточнее главных ворот. Твой крошшер сам поймет, что ему делать. Поруби их!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь циркулярной пилой крошшера, чтобы спилить азшарские молодые деревца и убейте 9 снайперов с заставы Талрендис, когда они появятся.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Воспользуйтесь циркулярной пилой крошшера, чтобы спилить азшарские деревца и убейте 9 снайперов с заставы Талрендис, когда они появятся.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14136,'Спасательная операция на море','Вы помогли отразить атаку квалдиров?','Вернитесь к Гиране Окровавленной на Ристалище Серебряного турнира, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спасательная операция на море',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы помогли отразить атаку квалдиров?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гиране Окровавленной на Ристалище Серебряного турнира, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (14137,'Изучение классовых навыков') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Изучение классовых навыков',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (14138,'Бизнес – прежде всего','Что касается беспорядков в Каджа\'митовой шахте... штейгер Промоках уже сбился с ног. Ищет тебя. Он что-то говорил о "взбунтовавшихся вконец обнаглевших троллях".$B$BКаджа\'мит, добываемый нашими троллями, – основной компонент "Каджа-Колы". На этой шипучке мы делаем огромные деньги, и, кстати, благодаря ей ты $gсам:сама; можешь стать $gторговым принцем:торговой принцессой;!$B$BНо сначала нам нужно восстановить производство. Иди на восток, найди штейгера. Вручи ему вот это, чтобы у него был стимул к действию.','Передайте поощрение Хамми штейгеру Промокаху в штаб-квартире ТКК на Кезане.','Подарок от Хамми? Никак премия!','Э... все идет замечательно. Да.$B$BА это что?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бизнес – прежде всего',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что касается беспорядков в Каджа\'митовой шахте... штейгер Промоках уже сбился с ног. Ищет тебя. Он что-то говорил о "взбунтовавшихся вконец обнаглевших троллях".$B$BКаджа\'мит, добываемый нашими троллями, – основной компонент "Каджа-Колы". На этой шипучке мы делаем огромные деньги, и, кстати, благодаря ей ты $gсам:сама; можешь стать $gторговым принцем:торговой принцессой;!$B$BНо сначала нам нужно восстановить производство. Иди на восток, найди штейгера. Вручи ему вот это, чтобы у него был стимул к действию.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Передайте поощрение Хамми штейгеру Промокаху в штаб-квартире ТКК на Кезане.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Подарок от Хамми? Никак премия!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Э... все идет замечательно. Да.$B$BА это что?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (14139,'Phase 1 Complete (Tracking Event)') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Phase 1 Complete (Tracking Event)',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14140,'Остановить нападение','Квалдиры, морские врайкулы, что захватили наши грузы, завладели островом клыкарров, который находится на севере пролива, убили его обитателей и переименовали его в Лагерь Хротгара. Если позволить им закрепиться на этой позиции, они изберут нас следующей целью.$B$BАвангард бросил все силы на борьбу с Плетью, поэтому защитить Ристалище можем только мы. Лети на север от турнирной площадки, пока не увидишь этот остров, и убей квалдиров прежде, чем они возьмутся за нас.','Гирана Окровавленная с Ристалища Серебряного турнира просит вас убить 10 квалдиров.','Твои действия подтвердили, что Похитители Солнца – гораздо более надежные союзники Серебряного Авангарда, нежели Серебряный союз. Вместе мы одержим победу!','Вы показали квалдирам, что мы не позволим им угрожать нам?','Вернитесь к Гиране Окровавленной на Ристалище Серебряного турнира, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Остановить нападение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Квалдиры, морские врайкулы, что захватили наши грузы, завладели островом клыкарров, который находится на севере пролива, убили его обитателей и переименовали его в Лагерь Хротгара. Если позволить им закрепиться на этой позиции, они изберут нас следующей целью.$B$BАвангард бросил все силы на борьбу с Плетью, поэтому защитить Ристалище можем только мы. Лети на север от турнирной площадки, пока не увидишь этот остров, и убей квалдиров прежде, чем они возьмутся за нас.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Гирана Окровавленная с Ристалища Серебряного турнира просит вас убить 10 квалдиров.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Твои действия подтвердили, что Похитители Солнца – гораздо более надежные союзники Серебряного Авангарда, нежели Серебряный союз. Вместе мы одержим победу!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы показали квалдирам, что мы не позволим им угрожать нам?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гиране Окровавленной на Ристалище Серебряного турнира, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14141,'Гормоку нужны снобольды','Воспользуйтесь утяжеленной сетью, чтобы поймать 8 последователей с Холмов Снежной Слепоты, и приведите их Тайлосу Вестнику Зари в шатер Орды на Ристалище Серебряного турнира.','Чем быстрее мы уберем этих вонючих тварей в клетку, тем лучше. Жаль, что Серебряный Авангард не поручил Серебряному союзу присматривать за тварями. Вскоре им придется запачкать свои белоснежные ручки в борьбе за Цитадель Ледяной Короны, и я опасаюсь, что они окажутся слишком слабыми и ненадежными союзниками.','Вам уже удалось собрать этих снобольдов? Гнев Гормока не проявляет никаких признаков ослабления.','Вернитесь к Тайлосу Вестнику Зари на Ристалище Серебряного турнира, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гормоку нужны снобольды',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь утяжеленной сетью, чтобы поймать 8 последователей с Холмов Снежной Слепоты, и приведите их Тайлосу Вестнику Зари в шатер Орды на Ристалище Серебряного турнира.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Чем быстрее мы уберем этих вонючих тварей в клетку, тем лучше. Жаль, что Серебряный Авангард не поручил Серебряному союзу присматривать за тварями. Вскоре им придется запачкать свои белоснежные ручки в борьбе за Цитадель Ледяной Короны, и я опасаюсь, что они окажутся слишком слабыми и ненадежными союзниками.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вам уже удалось собрать этих снобольдов? Гнев Гормока не проявляет никаких признаков ослабления.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тайлосу Вестнику Зари на Ристалище Серебряного турнира, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14142,'На этот раз ты нарвался, Кул','Рыцарь Кул опять угодил в беду, но на этот раз увлек за собой других. Как только он увидел, что члены культа Проклятых разбили лагерь на Заставе Вестника Смерти, к западу от Ристалища, то собрал группу претендентов и повел их на бой с захватчиками.$B$BРазумеется, не имея должного подкрепления, они были разбиты и захвачены в плен. Я не сомневаюсь, что мерзавцы принесут их в жертву, дабы подпитать этой силой свою зловещую магию. Ключи от черных клеток, в которых держат пленников, могут храниться у любого из служителей культа. Прошу тебя – найди ключи, спаси Кула и несчастных претендентов от ужасной участи!','Спасите Кула Безрассудного и 4 пленных претендентов с Заставы Вестника Смерти и вернитесь к Гиране Окровавленной на Ристалище Серебряного турнира.','К сожалению, Кулу придется смириться с очередным поражением. Нам уже не раз приходилось спасать его от самого себя. Жаль, что некоторые претенденты берут с него пример и начинают вести себя как представители Серебряного союза.','Ты освободил Кула и тех безнадежных претендентов?','Вернитесь к Гиране Окровавленной на Ристалище Серебряного турнира, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На этот раз ты нарвался, Кул',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Рыцарь Кул опять угодил в беду, но на этот раз увлек за собой других. Как только он увидел, что члены культа Проклятых разбили лагерь на Заставе Вестника Смерти, к западу от Ристалища, то собрал группу претендентов и повел их на бой с захватчиками.$B$BРазумеется, не имея должного подкрепления, они были разбиты и захвачены в плен. Я не сомневаюсь, что мерзавцы принесут их в жертву, дабы подпитать этой силой свою зловещую магию. Ключи от черных клеток, в которых держат пленников, могут храниться у любого из служителей культа. Прошу тебя – найди ключи, спаси Кула и несчастных претендентов от ужасной участи!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Спасите Кула Безрассудного и 4 пленных претендентов с Заставы Вестника Смерти и вернитесь к Гиране Окровавленной на Ристалище Серебряного турнира.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','К сожалению, Кулу придется смириться с очередным поражением. Нам уже не раз приходилось спасать его от самого себя. Жаль, что некоторые претенденты берут с него пример и начинают вести себя как представители Серебряного союза.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты освободил Кула и тех безнадежных претендентов?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гиране Окровавленной на Ристалище Серебряного турнира, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14143,'Лапами кверху','Серебряный Авангард отправил сюда крейсерский корабль, перевозивший мясо долгоногов и прочие припасы для турнира, но он так и не добрался до пункта назначения. Наши разведчики доложили, что на него напали квалдиры, безжалостные пираты, которые бороздят эти моря.$B$BОни убили всю команду и перетащили груз на остров, который теперь называется Лагерь Хротгара. Посмотри на север – и увидишь его среди туманов. Может быть, ты поможешь нам вернуть украденные припасы? Если мясо долгоногов не прибудет вовремя, у нас может кончиться провизия.','Верните 10 украденных окорочков долгонога Гиране Окровавленной из Павильона Похитителей Солнца на Ристалище Серебряного турнира.','М-да, выглядят они... не очень, но есть можно. Крестоносцы будут рады узнать, что нам удалось спасти хоть какие-то припасы с корабля. А эти обглоданные куски можно будет отдать Серебряному союзу, что значительно улучшит мое настроение.','Тебе удалось найти украденные припасы?','Вернитесь к Гиране Окровавленной на Ристалище Серебряного турнира, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лапами кверху',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Серебряный Авангард отправил сюда крейсерский корабль, перевозивший мясо долгоногов и прочие припасы для турнира, но он так и не добрался до пункта назначения. Наши разведчики доложили, что на него напали квалдиры, безжалостные пираты, которые бороздят эти моря.$B$BОни убили всю команду и перетащили груз на остров, который теперь называется Лагерь Хротгара. Посмотри на север – и увидишь его среди туманов. Может быть, ты поможешь нам вернуть украденные припасы? Если мясо долгоногов не прибудет вовремя, у нас может кончиться провизия.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните 10 украденных окорочков долгонога Гиране Окровавленной из Павильона Похитителей Солнца на Ристалище Серебряного турнира.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','М-да, выглядят они... не очень, но есть можно. Крестоносцы будут рады узнать, что нам удалось спасти хоть какие-то припасы с корабля. А эти обглоданные куски можно будет отдать Серебряному союзу, что значительно улучшит мое настроение.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось найти украденные припасы?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гиране Окровавленной на Ристалище Серебряного турнира, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (14144,'Милосердие Света','Последняя проповедь Исповедницы Пейлтресс заставила меня задуматься о том, что нам недостаточно просто сражаться плечом к плечу с рыцарями Авангарда – мы должны помогать им исполнить свой долг.$B$BУ северного побережья находится Лагерь Хротгара – остров, который захватили морские пираты – квалдиры, убив всех обитавших на нем клыкарров. Возьми эту книгу и прочти отходную молитву рядом с телами павших жителей. Пусть их несчастные души обретут покой вдали от зловещих туманов острова.','Воспользуйтесь Молитвенником исповедницы для проведения последнего обряда над телами 8 убитых туаликов, после чего вернитесь к Гиране Окровавленной в шатер Орды на Ристалище Серебряного турнира.','Вернитесь к Гиране Окровавленной на Ристалище Серебряного турнира, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Милосердие Света',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Последняя проповедь Исповедницы Пейлтресс заставила меня задуматься о том, что нам недостаточно просто сражаться плечом к плечу с рыцарями Авангарда – мы должны помогать им исполнить свой долг.$B$BУ северного побережья находится Лагерь Хротгара – остров, который захватили морские пираты – квалдиры, убив всех обитавших на нем клыкарров. Возьми эту книгу и прочти отходную молитву рядом с телами павших жителей. Пусть их несчастные души обретут покой вдали от зловещих туманов острова.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь Молитвенником исповедницы для проведения последнего обряда над телами 8 убитых туаликов, после чего вернитесь к Гиране Окровавленной в шатер Орды на Ристалище Серебряного турнира.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гиране Окровавленной на Ристалище Серебряного турнира, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (14145,'Кстати, чем питаются йети?','Тайлос Вестник Зари из Павильона Похитителей Солнца на Ристалище Серебряного турнира просит вас принести ему 3 куска мяса акулы Северного моря.','Вернитесь к Тайлосу Вестнику Зари на Ристалище Серебряного турнира, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кстати, чем питаются йети?',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Тайлос Вестник Зари из Павильона Похитителей Солнца на Ристалище Серебряного турнира просит вас принести ему 3 куска мяса акулы Северного моря.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тайлосу Вестнику Зари на Ристалище Серебряного турнира, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (14146,'Защитить врата!','Боже, что происходит?$b$b<Вопли, крики и шум битвы наполняют радиоэфир.>$b$b$n! Сейчас же возвращайся сюда. Спеши к вратам – на нас напали!$b$bПомоги нам дать отпор захватчикам. Я сейчас заряжу твой гранатомет!','Подрядчик Жаднюк просит вас поспешить к задним вратам Оргриммара и убить 20 ночных эльфов-налетчиков.','Подрядчик Жаднюк просит вас поспешить к задним вратам Оргриммара и убить 20 ночных эльфов-налетчиков.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Защитить врата!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Боже, что происходит?$b$b<Вопли, крики и шум битвы наполняют радиоэфир.>$b$b$n! Сейчас же возвращайся сюда. Спеши к вратам – на нас напали!$b$bПомоги нам дать отпор захватчикам. Я сейчас заряжу твой гранатомет!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Подрядчик Жаднюк просит вас поспешить к задним вратам Оргриммара и убить 20 ночных эльфов-налетчиков.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Подрядчик Жаднюк просит вас поспешить к задним вратам Оргриммара и убить 20 ночных эльфов-налетчиков.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (14147,'Blank [PH]','Вернитесь к Линзи Черноболт на Железную плотину, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Blank [PH]',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Линзи Черноболт на Железную плотину, что в Ледяной Короне.',`completedtext_loc8`);
