INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (14151,'Багровый рубин','Багровый рубин обработать непросто – это самый изысканный камень во всем Нордсколе. На солнце он сияет подобно багровой хрустальной розе.$b$bНо прежде, чем я передам тебе рецепт, тебе придется сделать пять эпических трансмутаций драгоценных камней. Можешь создавать любые камни, даже одинаковые.$b$bВозвращайся, когда будешь $gготов:готова;.','Линзи Черноболт просит вас успешно трансмутировать пять эпических драгоценных камней с помощью алхимии. Можно трансмутировать аметрин, око Зула, страхолит, царский янтарь и величественный циркон.','Вернитесь к Линзи Черноболт в Даларан.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Багровый рубин',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Багровый рубин обработать непросто – это самый изысканный камень во всем Нордсколе. На солнце он сияет подобно багровой хрустальной розе.$b$bНо прежде, чем я передам тебе рецепт, тебе придется сделать пять эпических трансмутаций драгоценных камней. Можешь создавать любые камни, даже одинаковые.$b$bВозвращайся, когда будешь $gготов:готова;.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Линзи Черноболт просит вас успешно трансмутировать пять эпических драгоценных камней с помощью алхимии. Можно трансмутировать аметрин, око Зула, страхолит, царский янтарь и величественный циркон.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Линзи Черноболт в Даларан.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14152,'Спасательная операция на море','Похоже, дела обстоят еще хуже, чем мы предполагали. Но с твоей помощью мы смогли спасти многих членов команды "Гребня Волны".','Вы помогли отразить атаку квалдиров?','Вернитесь к Нараси Снежной Заре на Ристалище Серебряного турнира в Ледяную Корону.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спасательная операция на море',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Похоже, дела обстоят еще хуже, чем мы предполагали. Но с твоей помощью мы смогли спасти многих членов команды "Гребня Волны".',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы помогли отразить атаку квалдиров?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Нараси Снежной Заре на Ристалище Серебряного турнира в Ледяную Корону.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (14153,'Банкет','Ого! Ничего себе! Да тут собрался весь цвет кезанского общества! Кому какое дело до несчастного дракона?$B$BМы решили устроить банкет у бассейна. Гости, похоже, довольны. И все ждут тебя!$B$BТак что давай наряжайся, иди к бассейну и общайся с гостями. Я тоже скоро приду... Только схожу возьму вещи.','Наденьте свой потрясный прикид для вечеринки (темные очки, новый стильный костюмчик и блестящие украшения) и отправляйтесь развлекать 10 кутил из Кезана, собравшихся у бассейна в штаб-квартире ТКК.','Как все здорово получилось. Банкет удался на славу!$B$BЭ... Что это?','Вернитесь к Хамми Кофельнагель в штаб-квартиру ТКК на Кезане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Банкет',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ого! Ничего себе! Да тут собрался весь цвет кезанского общества! Кому какое дело до несчастного дракона?$B$BМы решили устроить банкет у бассейна. Гости, похоже, довольны. И все ждут тебя!$B$BТак что давай наряжайся, иди к бассейну и общайся с гостями. Я тоже скоро приду... Только схожу возьму вещи.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Наденьте свой потрясный прикид для вечеринки (темные очки, новый стильный костюмчик и блестящие украшения) и отправляйтесь развлекать 10 кутил из Кезана, собравшихся у бассейна в штаб-квартире ТКК.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Как все здорово получилось. Банкет удался на славу!$B$BЭ... Что это?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хамми Кофельнагель в штаб-квартиру ТКК на Кезане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (14154,'На расстоянии укуса','Один из этих вшивых щенков хорошенько зацепил Демпси, и его все еще нельзя переносить, пока кровотечение не остановится.$B$BНам надо удержать позицию всего на несколько минут. Помоги нам дать отпор этим чудовищам, $Gбрат:сестра;!','В течение 2 минут сдерживайте натиск воргенов на крыше тюрьмы Гилнеаса.','Сдерживайте натиск воргенов в течение 2 минут.','Поговорите с лордом Дарием Краули на вершине Каменной тюрьмы в Гилнеасе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На расстоянии укуса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Один из этих вшивых щенков хорошенько зацепил Демпси, и его все еще нельзя переносить, пока кровотечение не остановится.$B$BНам надо удержать позицию всего на несколько минут. Помоги нам дать отпор этим чудовищам, $Gбрат:сестра;!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','В течение 2 минут сдерживайте натиск воргенов на крыше тюрьмы Гилнеаса.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Сдерживайте натиск воргенов в течение 2 минут.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с лордом Дарием Краули на вершине Каменной тюрьмы в Гилнеасе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (14156,'Засланный шпион','Если король хочет спасти лорда Краули и его шайку предателей, то мы, конечно, подчинимся.$B$BВ любом случае... одному из моих людей было приказано внедриться в банду Краули, и я был бы счастлив узнать, что он уцелел.$B$BСвяжись с Шоном Демпси, только тайно... люди Краули не должны узнать, на кого он работает на самом деле. Эти парни могут быть опаснее воргенов.','Найдите Шона Демпси на крыше тюрьмы Гилнеаса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Засланный шпион',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если король хочет спасти лорда Краули и его шайку предателей, то мы, конечно, подчинимся.$B$BВ любом случае... одному из моих людей было приказано внедриться в банду Краули, и я был бы счастлив узнать, что он уцелел.$B$BСвяжись с Шоном Демпси, только тайно... люди Краули не должны узнать, на кого он работает на самом деле. Эти парни могут быть опаснее воргенов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Шона Демпси на крыше тюрьмы Гилнеаса.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (14157,'Старые распри','Как только ни называли лорда Дария Краули – мятежником, предателем, террористом...$B$BДо начала гражданской войны я считал его своим другом.$B$BЯ не виню его за то, что он возглавил восстание против меня. Мы выстроили тридцатиметровую стену между его землями и Гилнеасом... но у нас не было иного пути.$B$BКак бы то ни было, сейчас нам нужен такой человек, как Краули.$B$BПроникни в Каменную тюрьму и узнай у капитана Бродерика, где содержится Краули. Я бы послал одного из своих людей, но, боюсь, наши старые распри могут помешать переговорам.','Поговорите с капитаном Бродериком в Каменной тюрьме, что в Гилнеасе.','Седогрив хочет спасти Краули? Неужели наш король сошел с ума?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Старые распри',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как только ни называли лорда Дария Краули – мятежником, предателем, террористом...$B$BДо начала гражданской войны я считал его своим другом.$B$BЯ не виню его за то, что он возглавил восстание против меня. Мы выстроили тридцатиметровую стену между его землями и Гилнеасом... но у нас не было иного пути.$B$BКак бы то ни было, сейчас нам нужен такой человек, как Краули.$B$BПроникни в Каменную тюрьму и узнай у капитана Бродерика, где содержится Краули. Я бы послал одного из своих людей, но, боюсь, наши старые распри могут помешать переговорам.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с капитаном Бродериком в Каменной тюрьме, что в Гилнеасе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Седогрив хочет спасти Краули? Неужели наш король сошел с ума?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (14158,'Phase 6 Complete (Tracking Event)') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Phase 6 Complete (Tracking Event)',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (14159,'Арсенал мятежного лорда','Арсенал, о котором упомянул Краули – это подвал в здании, которое находится на западе от этого места.$B$BДа, меня тоже беспокоит, что находящееся там оружие было пронесено в город врагами, но сегодня оно может спасти жителей Гилнеаса.$B$BРазыщи Джосайю Авери и конфискуй арсенал мятежников. Пусть это оружие послужит благому делу.','Поговорите с Джосайей Авери в Военном квартале Гилнеаса.','Не смотри на меня! Оставь меня в покое!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Арсенал мятежного лорда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Арсенал, о котором упомянул Краули – это подвал в здании, которое находится на западе от этого места.$B$BДа, меня тоже беспокоит, что находящееся там оружие было пронесено в город врагами, но сегодня оно может спасти жителей Гилнеаса.$B$BРазыщи Джосайю Авери и конфискуй арсенал мятежников. Пусть это оружие послужит благому делу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Джосайей Авери в Военном квартале Гилнеаса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Не смотри на меня! Оставь меня в покое!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14160,'Список заслуг','В этом свитке перечислены многие великие достижения, полученные |3-4($n) в области ювелирного искусства.$b$bОтнесите его Тимоти Джонсу и получите причитающуюся награду.','Доставьте Список заслуг Тимоти Джонсу в Даларан.','Прекрасный список дел, $N! Вы должны быть щедро вознаграждены за свои достижения.','Добрый день, $N. Что у тебя там?','Вернитесь к Тимоти Джонсу в ювелирный магазин Картье и компании, что в Даларане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Список заслуг',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В этом свитке перечислены многие великие достижения, полученные |3-4($n) в области ювелирного искусства.$b$bОтнесите его Тимоти Джонсу и получите причитающуюся награду.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте Список заслуг Тимоти Джонсу в Даларан.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасный список дел, $N! Вы должны быть щедро вознаграждены за свои достижения.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Добрый день, $N. Что у тебя там?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тимоти Джонсу в ювелирный магазин Картье и компании, что в Даларане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (14161,'Удар по василискам','Мы передвинули целую гору из-за карьера по добыче минералов внизу. Но мы не подумали о подземных василисках, которые теперь стали, гм, наземными. Ты выглядишь $gинициативным:инициативной; – отправляйся туда и устрани эту помеху, а я тебя чем-нибудь отблагодарю.','Убейте 10 серокаменных василисков в карьере у подножья горы.','Хорошо, хорошо. Одной головной болью меньше.','Вернитесь к Хорзаку Кругоглоду на оргриммарскую пересадочную станцию ракетной дороги в Азшаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Удар по василискам',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы передвинули целую гору из-за карьера по добыче минералов внизу. Но мы не подумали о подземных василисках, которые теперь стали, гм, наземными. Ты выглядишь $gинициативным:инициативной; – отправляйся туда и устрани эту помеху, а я тебя чем-нибудь отблагодарю.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 серокаменных василисков в карьере у подножья горы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо, хорошо. Одной головной болью меньше.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хорзаку Кругоглоду на оргриммарскую пересадочную станцию ракетной дороги в Азшаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (14162,'Отчитаться Хорзаку','Ты первоклассно $gвыполнил:выполнила; работу по лесозаготовкам. Но теперь говорят, что не хватает камней. Ты $gдумал:думала;, что если мы можем двигать горы, то собрать кучу камней – для нас раз плюнуть?..$b$bНу, это не моя проблема. Может быть, ты этим займешься? Поговори с Хорзаком Кругоглодом перед оргриммарской пересадочной станцией ракетной дороги. Может, ты сможешь ему помочь. Иди по дороге на северо-восток и найдешь его на ракетной башне.','Найдите Хорзака Кругоглода на оргриммарской пересадочной станции ракетной дороги в Азшаре.','Найдите Хорзака Кругоглода на оргриммарской пересадочной станции ракетной дороги в Азшаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отчитаться Хорзаку',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты первоклассно $gвыполнил:выполнила; работу по лесозаготовкам. Но теперь говорят, что не хватает камней. Ты $gдумал:думала;, что если мы можем двигать горы, то собрать кучу камней – для нас раз плюнуть?..$b$bНу, это не моя проблема. Может быть, ты этим займешься? Поговори с Хорзаком Кругоглодом перед оргриммарской пересадочной станцией ракетной дороги. Может, ты сможешь ему помочь. Иди по дороге на северо-восток и найдешь его на ракетной башне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Хорзака Кругоглода на оргриммарской пересадочной станции ракетной дороги в Азшаре.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Найдите Хорзака Кругоглода на оргриммарской пересадочной станции ракетной дороги в Азшаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (14163,'Призыв к оружию: Остров Завоеваний','Чем ближе мы к схватке с Королем-личом, тем очевиднее тот факт, что Орда стоит на пути к нашей победе в Ледяной Короне.$B$BЧтобы отрезать нам путь к Острову Завоеваний, они выслали элитную армию стражей, известную как Кор\'крон. Стоит ли говорить о том, насколько стратегически важен этот клочок земли? Я поручаю тебе, $n, одержать победу в сражении за остров!','Победите на поле боя Острова Завоеваний и вернитесь к бригадному генералу Альянса в любую из столиц Альянса, на Озеро Ледяных Оков, в Даларан или в Шаттрат.','Одержана победа на Острове Завоеваний','Вернитесь к бригадному генералу Альянса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Призыв к оружию: Остров Завоеваний',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чем ближе мы к схватке с Королем-личом, тем очевиднее тот факт, что Орда стоит на пути к нашей победе в Ледяной Короне.$B$BЧтобы отрезать нам путь к Острову Завоеваний, они выслали элитную армию стражей, известную как Кор\'крон. Стоит ли говорить о том, насколько стратегически важен этот клочок земли? Я поручаю тебе, $n, одержать победу в сражении за остров!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите на поле боя Острова Завоеваний и вернитесь к бригадному генералу Альянса в любую из столиц Альянса, на Озеро Ледяных Оков, в Даларан или в Шаттрат.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Одержана победа на Острове Завоеваний',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к бригадному генералу Альянса.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (14164,'Призыв к оружию: Остров Завоеваний','Вскоре мы добьемся победы в Нордсколе... но для начала нам надо закрепиться в Ледяной Короне, наладить поставки продовольствия и подкреплений.$B$BОстров Завоеваний представляется мне идеальным плацдармом – это богатое ресурсами место легко защитить от нападений. Однако похоже, что Альянс пришел к такому же выводу и послал Седьмой Легион навстречу нашим войскам.$B$B$n, отправляйся туда и сделай все для нашей победы!','Принесите почетные знаки каждого поля боя ордынскому вестнику войны в любую столицу Орды, на Озеро Ледяных Оков, в Даларан или Шаттрат.','Одержана победа на Острове Завоеваний','Вернитесь к ордынскому вестнику войны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Призыв к оружию: Остров Завоеваний',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вскоре мы добьемся победы в Нордсколе... но для начала нам надо закрепиться в Ледяной Короне, наладить поставки продовольствия и подкреплений.$B$BОстров Завоеваний представляется мне идеальным плацдармом – это богатое ресурсами место легко защитить от нападений. Однако похоже, что Альянс пришел к такому же выводу и послал Седьмой Легион навстречу нашим войскам.$B$B$n, отправляйся туда и сделай все для нашей победы!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите почетные знаки каждого поля боя ордынскому вестнику войны в любую столицу Орды, на Озеро Ледяных Оков, в Даларан или Шаттрат.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Одержана победа на Острове Завоеваний',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ордынскому вестнику войны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (14165,'Хладный камень','Найдите в карьере у подножья горы окаменевшего горняка и принесите его Хорзаку Кругоглоду на оргриммарскую пересадочную станцию ракетной дороги.','Ну-ну, давай посмотрим, что ты тут принес…$B$B<Хорзак рассматривает раздробленные остатки бедного окаменевшего рабочего.>$B$BТут одни крошки! Мало толку. Даже хорошей плитки на пол из него не сделать. Работают мои шахтеры не блестяще, но кирпичи из них и вовсе никакие.$B$B<Вздыхает.> Думаю, надо их оживить. Тогда мои затраты хоть немного окупятся.','Окаменевший рабочий доставлен','Вернитесь к Хорзаку Кругоглоду на оргриммарскую пересадочную станцию ракетной дороги в Азшаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хладный камень',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите в карьере у подножья горы окаменевшего горняка и принесите его Хорзаку Кругоглоду на оргриммарскую пересадочную станцию ракетной дороги.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну-ну, давай посмотрим, что ты тут принес…$B$B<Хорзак рассматривает раздробленные остатки бедного окаменевшего рабочего.>$B$BТут одни крошки! Мало толку. Даже хорошей плитки на пол из него не сделать. Работают мои шахтеры не блестяще, но кирпичи из них и вовсе никакие.$B$B<Вздыхает.> Думаю, надо их оживить. Тогда мои затраты хоть немного окупятся.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Окаменевший рабочий доставлен',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хорзаку Кругоглоду на оргриммарскую пересадочную станцию ракетной дороги в Азшаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (14166,'Благодарный покойник','Как приятно было навестить друзей и родных! Только, кажется, я немного перестарался... и съел все, что они приготовили для меня! Даже крошки подмел!$B$BМогу ли я попросить тебя принести мне еще вкусного поминального хлеба? Я бы был очень благодарен!$B$BКажется, рецепт можно купить у Чепмана.','Принесите поминальный хлеб веселому даларанскому духу на кладбище Даларана.$B$BЧтобы увидеть дух, используйте оранжевые бархатцы.','Какой же все-таки вкусный этот поминальный хлеб!$B$BПрошу, прими вот это в знак моей благодарности... Веселого тебе праздника!','Вернитесь к веселому даларанскому духу к Сумеречному ручью, что в Лесу Хрустальной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Благодарный покойник',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как приятно было навестить друзей и родных! Только, кажется, я немного перестарался... и съел все, что они приготовили для меня! Даже крошки подмел!$B$BМогу ли я попросить тебя принести мне еще вкусного поминального хлеба? Я бы был очень благодарен!$B$BКажется, рецепт можно купить у Чепмана.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите поминальный хлеб веселому даларанскому духу на кладбище Даларана.$B$BЧтобы увидеть дух, используйте оранжевые бархатцы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Какой же все-таки вкусный этот поминальный хлеб!$B$BПрошу, прими вот это в знак моей благодарности... Веселого тебе праздника!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к веселому даларанскому духу к Сумеречному ручью, что в Лесу Хрустальной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (14167,'Благодарный покойник','Как приятно было навестить друзей и родных! Только, кажется, я немного перестарался... и съел все, что они приготовили для меня! Даже крошки подмел!$B$BМогу ли я попросить тебя принести мне еще вкусного поминального хлеба? Я бы был очень благодарен!$B$BКажется, рецепт можно купить у Чепмана.','Принесите поминальный хлеб веселому духу дворфа на кладбище Стальгорна.$B$BЧтобы увидеть дух, используйте оранжевые бархатцы.','Какой же все-таки вкусный этот поминальный хлеб!$B$BПрошу, прими вот это в знак моей благодарности... Веселого тебе праздника!','Вернитесь к веселому духу дворфа ко Вратам Стальгорна, что в Дун Мороге.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Благодарный покойник',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как приятно было навестить друзей и родных! Только, кажется, я немного перестарался... и съел все, что они приготовили для меня! Даже крошки подмел!$B$BМогу ли я попросить тебя принести мне еще вкусного поминального хлеба? Я бы был очень благодарен!$B$BКажется, рецепт можно купить у Чепмана.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите поминальный хлеб веселому духу дворфа на кладбище Стальгорна.$B$BЧтобы увидеть дух, используйте оранжевые бархатцы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Какой же все-таки вкусный этот поминальный хлеб!$B$BПрошу, прими вот это в знак моей благодарности... Веселого тебе праздника!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к веселому духу дворфа ко Вратам Стальгорна, что в Дун Мороге.',`completedtext_loc8`);
