INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (14178,'Призыв к оружию: Низина Арати','Беда битвы на несколько фронтов, $gпарень:подруга;, в том, что приходится рассредотачивать силы, и в результате мы рискуем потерять все!$B$BНам каждый день требуется подкрепление. Сегодня войскам в Низине Арати требуются отважные бойцы.$B$BИди, $n, и принеси нам победу. Мы не можем позволить Ордынским отродьям претендовать на ресурсы, которые по праву принадлежат нам!','Победите на поле боя Низины Арати и вернитесь к бригадному генералу Альянса в любую из столиц Альянса, на Озеро Ледяных Оков, в Даларан или в Шаттрат.','Одержана победа в Низине Арати','Вернитесь к бригадному генералу Альянса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Призыв к оружию: Низина Арати',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Беда битвы на несколько фронтов, $gпарень:подруга;, в том, что приходится рассредотачивать силы, и в результате мы рискуем потерять все!$B$BНам каждый день требуется подкрепление. Сегодня войскам в Низине Арати требуются отважные бойцы.$B$BИди, $n, и принеси нам победу. Мы не можем позволить Ордынским отродьям претендовать на ресурсы, которые по праву принадлежат нам!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите на поле боя Низины Арати и вернитесь к бригадному генералу Альянса в любую из столиц Альянса, на Озеро Ледяных Оков, в Даларан или в Шаттрат.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Одержана победа в Низине Арати',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к бригадному генералу Альянса.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (14179,'Призыв к оружию: Око Бури','Битва с Ордой не знает границ, $n. Даже в Запределье старая ненависть может вспыхнуть с новой силой, склонив чаши весов войны в пользу одного из противников.$B$BОтправляйся в Око Бури и убедись, что Альянс одержит верх в Запределье, как и по всему Азероту.','Победите на поле боя Ока Бури и вернитесь к бригадному генералу Альянса в любую из столиц Альянса, на Озеро Ледяных Оков, в Даларан или в Шаттрат.','Мы на шаг приблизились к полной победе над Ордой! Мы не можем позволить врагу завоевать плацдарм ни в этом мире, ни в каком другом!','Одержана победа в Оке Бури','Вернитесь к бригадному генералу Альянса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Призыв к оружию: Око Бури',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Битва с Ордой не знает границ, $n. Даже в Запределье старая ненависть может вспыхнуть с новой силой, склонив чаши весов войны в пользу одного из противников.$B$BОтправляйся в Око Бури и убедись, что Альянс одержит верх в Запределье, как и по всему Азероту.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите на поле боя Ока Бури и вернитесь к бригадному генералу Альянса в любую из столиц Альянса, на Озеро Ледяных Оков, в Даларан или в Шаттрат.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мы на шаг приблизились к полной победе над Ордой! Мы не можем позволить врагу завоевать плацдарм ни в этом мире, ни в каком другом!',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Одержана победа в Оке Бури',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к бригадному генералу Альянса.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (14180,'Призыв к оружию: Ущелье Песни Войны','Среброкрылые Часовые охраняют леса в Ущелье Песни Войны.Мы помогаем им сохранить этот лес, но не только из любви к природе – он представляет собой естественную преграду для наступления сил Орды.$B$BНо сейчас им как никогда нужна наша помощь. Мы должны послать подкрепление незамедлительно – иначе вместо Ясеневого леса мы вскоре увидим бесплодные Степи!','Победите на поле боя Ущелья Песни Войны и вернитесь к бригадному генералу Альянса в любую из столиц Альянса, на Озеро Ледяных Оков, в Даларан или в Шаттрат.','Одержана победа в Ущелье Песни Войны','Вернитесь к бригадному генералу Альянса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Призыв к оружию: Ущелье Песни Войны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Среброкрылые Часовые охраняют леса в Ущелье Песни Войны.Мы помогаем им сохранить этот лес, но не только из любви к природе – он представляет собой естественную преграду для наступления сил Орды.$B$BНо сейчас им как никогда нужна наша помощь. Мы должны послать подкрепление незамедлительно – иначе вместо Ясеневого леса мы вскоре увидим бесплодные Степи!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите на поле боя Ущелья Песни Войны и вернитесь к бригадному генералу Альянса в любую из столиц Альянса, на Озеро Ледяных Оков, в Даларан или в Шаттрат.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Одержана победа в Ущелье Песни Войны',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к бригадному генералу Альянса.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`) VALUES (14182,'Призыв к оружию: Око Бури','Мы будем сражаться с врагами повсюду – в Азероте и Запределье. $B$BНельзя позволить Альянсу закрепиться в Оке Бури. Брось им вызов сегодня, ибо завтра может быть слишком поздно!','Победите на поле боя Ока Бури и вернитесь к ордынскому вестнику войны в любую из столиц Орды, на Озеро Ледяных Оков, в Даларан или в Шаттрат.','Одержана победа в Оке Бури','Вернитесь к ордынскому вестнику войны.','Одержана победа в Оке Бури') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Призыв к оружию: Око Бури',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы будем сражаться с врагами повсюду – в Азероте и Запределье. $B$BНельзя позволить Альянсу закрепиться в Оке Бури. Брось им вызов сегодня, ибо завтра может быть слишком поздно!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите на поле боя Ока Бури и вернитесь к ордынскому вестнику войны в любую из столиц Орды, на Озеро Ледяных Оков, в Даларан или в Шаттрат.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Одержана победа в Оке Бури',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ордынскому вестнику войны.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Одержана победа в Оке Бури',`questgivertextwindow_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (14184,'Мое время прошло...','<Фуриен слабо машет рукой, подзывая вас подойти ближе, и с трудом выговаривает слова.>$B$BТак нелепо... неосторожно... попал под огонь Альянса...$B$BНужно сказать сестре... чтобы она знала...$B$BВозьми моего дракондора, |3-6($r)... он отвезет тебя к ней...$B$B<Фуриен умирает.>','Выполняя последнюю волю Фуриена в Тефрис-Аране, садитесь на его дракондора, отправляйтесь на Пост Фуриена и расскажите его сестре Серелии о смерти брата.','Что?!$B$BФуриен?! Мой брат убит?$B$BОни за это заплатят! Все до единого!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мое время прошло...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Фуриен слабо машет рукой, подзывая вас подойти ближе, и с трудом выговаривает слова.>$B$BТак нелепо... неосторожно... попал под огонь Альянса...$B$BНужно сказать сестре... чтобы она знала...$B$BВозьми моего дракондора, |3-6($r)... он отвезет тебя к ней...$B$B<Фуриен умирает.>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выполняя последнюю волю Фуриена в Тефрис-Аране, садитесь на его дракондора, отправляйтесь на Пост Фуриена и расскажите его сестре Серелии о смерти брата.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что?!$B$BФуриен?! Мой брат убит?$B$BОни за это заплатят! Все до единого!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (14185,'УКАЗАТЕЛЬ: приглашение на тренировки по верховой езде (40)') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','УКАЗАТЕЛЬ: приглашение на тренировки по верховой езде (40)',`title_loc8`);
