INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (14188,'Месть за Фуриена','Нет, я не верю!$B$BМой брат погиб... убит этими ублюдками из Альянса!$B$BОни за это заплатят, |3-6($r)! Они еще пожалеют, что родились на свет!$B$BМогу я рассчитывать на твою помощь? Незадолго до гибели Фуриен занимался изучением древних артефактов в восточных землях. Тебе надо поговорить с Сорремом. Он должен знать, где проходили исследования брата.','По просьбе Серелии поговорите с Сорремом на Посту Фуриена.','Фуриена больше нет с нами…. Жаль… очень жаль.$B$BЯ помогу тебе отомстить за него.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Месть за Фуриена',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нет, я не верю!$B$BМой брат погиб... убит этими ублюдками из Альянса!$B$BОни за это заплатят, |3-6($r)! Они еще пожалеют, что родились на свет!$B$BМогу я рассчитывать на твою помощь? Незадолго до гибели Фуриен занимался изучением древних артефактов в восточных землях. Тебе надо поговорить с Сорремом. Он должен знать, где проходили исследования брата.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По просьбе Серелии поговорите с Сорремом на Посту Фуриена.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Фуриена больше нет с нами…. Жаль… очень жаль.$B$BЯ помогу тебе отомстить за него.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (14189,'Расшифровка','Да, Фуриен занимался каким-то важным исследовательским проектом. Я не знаю подробностей. Он ничего мне не рассказывал.$B$BК счастью, мне удалось получить его личный журнал. Но прочитать я его не могу – записи зашифрованы.$B$BНе исключено, что ключ к шифру найдется в восточных краях, где Фуриен проводил исследования.$B$BМожет быть, ты поможешь мне разгадать эту загадку, |3-6($c)? Возьми записи и посоветуйся с Наримаром.','По поручению Соррема разыщите древние таблички.$B$BПобеседуйте с Наримаром на Посту Фуриена, чтобы отправиться туда, где Фуриен занимался своими исследованиями.','Сравнив знаки, начертанные на древней табличке, с записями Фуриена, вы замечаете явное сходство.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Расшифровка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Да, Фуриен занимался каким-то важным исследовательским проектом. Я не знаю подробностей. Он ничего мне не рассказывал.$B$BК счастью, мне удалось получить его личный журнал. Но прочитать я его не могу – записи зашифрованы.$B$BНе исключено, что ключ к шифру найдется в восточных краях, где Фуриен проводил исследования.$B$BМожет быть, ты поможешь мне разгадать эту загадку, |3-6($c)? Возьми записи и посоветуйся с Наримаром.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По поручению Соррема разыщите древние таблички.$B$BПобеседуйте с Наримаром на Посту Фуриена, чтобы отправиться туда, где Фуриен занимался своими исследованиями.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сравнив знаки, начертанные на древней табличке, с записями Фуриена, вы замечаете явное сходство.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14190,'Идеальная призма','Должен быть способ оживить тех, кого василиски превратили в камень. Эти саботажники ночные эльфы, которые шастают вокруг моего карьера, должны что-то знать. Им-то взгляды василисков не приносят вреда!$b$bЯ хочу, чтобы ты $gузнал:узнала;, в чем их секрет, $n. Расправься с несколькими саботажниками с заставы Талрендис, которые шатаются без дела позади карьера, и узнай, какое заклинание или что там они используют, чтобы противостоять василискам. Когда все сделаешь, сообщи мне об этом по радио из главной кузни.','Снимите хрустальную подвеску с саботажника с заставы Талрендис в карьере у подножья горы.','<Из странных гоблинских динамиков слышны шип и треск.>','Воспользуйтесь штабным радио в здании главной кузни карьера у подножия горы в Азшаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Идеальная призма',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Должен быть способ оживить тех, кого василиски превратили в камень. Эти саботажники ночные эльфы, которые шастают вокруг моего карьера, должны что-то знать. Им-то взгляды василисков не приносят вреда!$b$bЯ хочу, чтобы ты $gузнал:узнала;, в чем их секрет, $n. Расправься с несколькими саботажниками с заставы Талрендис, которые шатаются без дела позади карьера, и узнай, какое заклинание или что там они используют, чтобы противостоять василискам. Когда все сделаешь, сообщи мне об этом по радио из главной кузни.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Снимите хрустальную подвеску с саботажника с заставы Талрендис в карьере у подножья горы.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Из странных гоблинских динамиков слышны шип и треск.>',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Воспользуйтесь штабным радио в здании главной кузни карьера у подножия горы в Азшаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (14191,'По следам Фуриена','Вам удается прочесть отдельные фрагменты текста, но для того чтобы расшифровать записи в журнале, этого явно недостаточно.$B$BВы смотрите на северо-восток и вроде бы различаете вдалеке руины, изображение которых встречается в журнале.$B$BПохоже, эти развалины имели большое значение для исследований Фуриена.','Следуя указаниям древних табличек в святилище Элуны, обойдите три места в Саргероне, где расположены самые примечательные руины.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','По следам Фуриена',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вам удается прочесть отдельные фрагменты текста, но для того чтобы расшифровать записи в журнале, этого явно недостаточно.$B$BВы смотрите на северо-восток и вроде бы различаете вдалеке руины, изображение которых встречается в журнале.$B$BПохоже, эти развалины имели большое значение для исследований Фуриена.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Следуя указаниям древних табличек в святилище Элуны, обойдите три места в Саргероне, где расположены самые примечательные руины.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14192,'Призмолом','Если эта твоя призма настроена так, чтобы преломлять взгляд василисков, то мы можем использовать ее свойства и для обратного процесса. Нам только нужен источник энергии.$b$bВ оружейном шкафу справа от тебя есть прототип лазерного горного бура. Мне всегда нравилась эта штука, утомляло только то, что почти каждый день она кого-то разрезала на части. Возьми свой кристалл и вставь его на место линз в буре...','Отнесите хрустальную подвеску в оружейный шкаф в штабе карьера у подножья горы.','<Вы вынимаете из бура линзы и вставляете на их место кристалл. Бур зловеще жужжит.>','<Оружейный шкаф полон отвратительных сломанных механизмов, к некоторым прилипли отрезанные конечности гоблинов. Вы находите лазерный бур, заботливо уложенный в деревянный ящик, обитый бархатом.>','Отнесите хрустальную подвеску в оружейный шкаф в штабе карьера у подножья горы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Призмолом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если эта твоя призма настроена так, чтобы преломлять взгляд василисков, то мы можем использовать ее свойства и для обратного процесса. Нам только нужен источник энергии.$b$bВ оружейном шкафу справа от тебя есть прототип лазерного горного бура. Мне всегда нравилась эта штука, утомляло только то, что почти каждый день она кого-то разрезала на части. Возьми свой кристалл и вставь его на место линз в буре...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите хрустальную подвеску в оружейный шкаф в штабе карьера у подножья горы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Вы вынимаете из бура линзы и вставляете на их место кристалл. Бур зловеще жужжит.>',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Оружейный шкаф полон отвратительных сломанных механизмов, к некоторым прилипли отрезанные конечности гоблинов. Вы находите лазерный бур, заботливо уложенный в деревянный ящик, обитый бархатом.>',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите хрустальную подвеску в оружейный шкаф в штабе карьера у подножья горы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (14193,'Пара дынь решит любую проблему','Символы на руинах дают ясно понять: есть что-то особенное в древнем источнике, находящемся в святилище Элуны.$B$BТому, кто умоет в нем лицо, даются какие-то особые способности. Вот только источник давно высох... и его надо как-то наполнить, чтобы было чем умыться.$B$BРазмышляя над этой проблемой, вы замечаете плод дыни на земле под ближайшим деревом...','Соберите 8 плодов дыни.','Выжмите дынный сок в кубок Элуны в Пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пара дынь решит любую проблему',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Символы на руинах дают ясно понять: есть что-то особенное в древнем источнике, находящемся в святилище Элуны.$B$BТому, кто умоет в нем лицо, даются какие-то особые способности. Вот только источник давно высох... и его надо как-то наполнить, чтобы было чем умыться.$B$BРазмышляя над этой проблемой, вы замечаете плод дыни на земле под ближайшим деревом...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 плодов дыни.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Выжмите дынный сок в кубок Элуны в Пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14194,'Превоплощение','<Вас вызывают по ближайшему радио.>$b$bЭй, $n, ты $gнашел:нашла; эту пушку? Хорошо! Только не направляй ее себе в глаз.$b$bНаправь эту малышку на моих окаменевших рабочих и преломленный свет снимет с рабочих окаменелость. Ну или расплавит их. Неважно. Верни моих рабочих в состояние, в котором они будут приносить прибыль! А если от процесса превоплощения у них поедет крыша, то надо их убить из соображений безопасности.','Воспользуйтесь превоплотителем, чтобы оживить окаменевших горняков в карьере у подножья горы.','Ого, смотри-ка, все твои конечности на месте.','Вернитесь к Хорзаку Кругоглоду на оргриммарскую пересадочную станцию ракетной дороги в Азшаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Превоплощение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Вас вызывают по ближайшему радио.>$b$bЭй, $n, ты $gнашел:нашла; эту пушку? Хорошо! Только не направляй ее себе в глаз.$b$bНаправь эту малышку на моих окаменевших рабочих и преломленный свет снимет с рабочих окаменелость. Ну или расплавит их. Неважно. Верни моих рабочих в состояние, в котором они будут приносить прибыль! А если от процесса превоплощения у них поедет крыша, то надо их убить из соображений безопасности.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь превоплотителем, чтобы оживить окаменевших горняков в карьере у подножья горы.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ого, смотри-ка, все твои конечности на месте.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хорзаку Кругоглоду на оргриммарскую пересадочную станцию ракетной дороги в Азшаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (14195,'Многое проясняется','Что-то изменилось... может быть, это побочное действие ритуала омовения в фонтане Элуны.$B$BВы еще не до конца понимаете древний язык, на котором Фуриен вел записи в своем журнале, но вам стало значительно легче их читать.$B$BПохоже, что больше всего Фуриена интересовали руины в северных горах Саргерона. Он был уверен: там есть что-то такое, что поможет ему вытеснить силы Альянса из этих земель.$B$BВы уже знаете, что делать дальше: нужно найти эти руины и раскрыть их тайну.','Воспользовавшись подсказкой, полученной из записей Фуриена, разыщите разрушенные чертоги Элуны на севере Саргерона.','Теперь вам понятно, почему все подсказки вели вас сюда.$B$BВы сразу узнали этот рунический камень из последней записи в журнале Фуриена:$B$B"Древние почитали самоцветы, созданные этим таинственным объектом, поскольку считали их даром самой богини. Существовало поверье, что это не просто камни, но грозное оружие, способное защитить от любого врага".') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Многое проясняется',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что-то изменилось... может быть, это побочное действие ритуала омовения в фонтане Элуны.$B$BВы еще не до конца понимаете древний язык, на котором Фуриен вел записи в своем журнале, но вам стало значительно легче их читать.$B$BПохоже, что больше всего Фуриена интересовали руины в северных горах Саргерона. Он был уверен: там есть что-то такое, что поможет ему вытеснить силы Альянса из этих земель.$B$BВы уже знаете, что делать дальше: нужно найти эти руины и раскрыть их тайну.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользовавшись подсказкой, полученной из записей Фуриена, разыщите разрушенные чертоги Элуны на севере Саргерона.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь вам понятно, почему все подсказки вели вас сюда.$B$BВы сразу узнали этот рунический камень из последней записи в журнале Фуриена:$B$B"Древние почитали самоцветы, созданные этим таинственным объектом, поскольку считали их даром самой богини. Существовало поверье, что это не просто камни, но грозное оружие, способное защитить от любого врага".',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (14196,'Поджигатель','Теперь вы свободно читаете и понимаете зашифрованные письмена.$B$BНа руническом камне написано, что здешние самоцветы обладают способностью вызывать огненный шторм.$B$BСуществует два способа, как превратить огненный шторм в мощнейшее оружие: либо в течение долгого времени поклоняться и верно служить Элуне, либо зарядить и усилить бурю духовной энергией павших врагов.$B$BГлядя на призрачных слуг Элуны, вы понимаете, что у вас нет ни времени, ни желания поклоняться вражеской богине...','Создайте бушующий вихрь, убив 7 адептов Элуны рядом с огненным штормом.$B$BЕсли вы потеряете свой самоцвет вихря, возьмите еще один у древнего рунического камня вихря.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поджигатель',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь вы свободно читаете и понимаете зашифрованные письмена.$B$BНа руническом камне написано, что здешние самоцветы обладают способностью вызывать огненный шторм.$B$BСуществует два способа, как превратить огненный шторм в мощнейшее оружие: либо в течение долгого времени поклоняться и верно служить Элуне, либо зарядить и усилить бурю духовной энергией павших врагов.$B$BГлядя на призрачных слуг Элуны, вы понимаете, что у вас нет ни времени, ни желания поклоняться вражеской богине...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Создайте бушующий вихрь, убив 7 адептов Элуны рядом с огненным штормом.$B$BЕсли вы потеряете свой самоцвет вихря, возьмите еще один у древнего рунического камня вихря.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14197,'Выполнить план','Железо из карьера хрупкое и содержит примеси, но если знать, кому дать взятку, то гоблинским стандартам качества оно соответствует. У Кругоглода проблемы с производительностью, но мои-то сроки никто не отменял. У меня есть план и его надо выполнить!$b$bОтправляйся в карьер у подножья горы и собери все слитки железа, какие найдешь. Должны получиться штабеля уже выплавленных и готовых к отправке слитков.','Соберите 20 слитков железа в карьере у подножья горы в Азшаре.','Отлично! Когда речь идет о железе, количество важнее, чем качество.','Ты подготовил груз к отправке?','Принесите железо штейгеру Фиск на оргриммарскую пересадочную станцию ракетной дороги в Азшаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Выполнить план',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Железо из карьера хрупкое и содержит примеси, но если знать, кому дать взятку, то гоблинским стандартам качества оно соответствует. У Кругоглода проблемы с производительностью, но мои-то сроки никто не отменял. У меня есть план и его надо выполнить!$b$bОтправляйся в карьер у подножья горы и собери все слитки железа, какие найдешь. Должны получиться штабеля уже выплавленных и готовых к отправке слитков.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 20 слитков железа в карьере у подножья горы в Азшаре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! Когда речь идет о железе, количество важнее, чем качество.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты подготовил груз к отправке?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите железо штейгеру Фиск на оргриммарскую пересадочную станцию ракетной дороги в Азшаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (14198,'Всадник бушующего вихря','У вас есть повод гордиться: вам удалось раскрыть древнюю тайну адептов Элуны.$B$BТеперь вы владеете грозным оружием, способным причинить немалый ущерб врагу.$B$BВы смогли получить его благодаря неустанным трудам Фуриена, и будет справедливо, если мощь этого оружия обрушится на тех, кто лишил его жизни.$B$BЭти скоты из Альянса, засевшие на Высоте Найджела, сполна за все заплатят!','Используйте силу самоцвета бушующего вихря на руинах Высоты Найджела. Призвав огненный шторм, убейте 40 защитников Высоты Найджела и сожгите 15 торговцев Высоты Найджела.$B$BЕсли вы потеряете свой самоцвет бушующего вихря, возьмите еще один у древнего рунического камня вихря.','Вернитесь к Серелии на Пост Фуриена в Пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Всадник бушующего вихря',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У вас есть повод гордиться: вам удалось раскрыть древнюю тайну адептов Элуны.$B$BТеперь вы владеете грозным оружием, способным причинить немалый ущерб врагу.$B$BВы смогли получить его благодаря неустанным трудам Фуриена, и будет справедливо, если мощь этого оружия обрушится на тех, кто лишил его жизни.$B$BЭти скоты из Альянса, засевшие на Высоте Найджела, сполна за все заплатят!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте силу самоцвета бушующего вихря на руинах Высоты Найджела. Призвав огненный шторм, убейте 40 защитников Высоты Найджела и сожгите 15 торговцев Высоты Найджела.$B$BЕсли вы потеряете свой самоцвет бушующего вихря, возьмите еще один у древнего рунического камня вихря.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Серелии на Пост Фуриена в Пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14199,'Победный трофей: Черный рыцарь','Мой коллега, Верховный маг Времиар, попросил меня предупредить тебя об опасности. Скоро ты будешь участвовать в Испытании чемпиона в Ледяной Короне. Остерегайся вмешательства со стороны соперника, известного как Черный рыцарь.$B$BПринеси мне осколок его души в доказательство того, что он больше не станет на пути Кирин-Тора. Мне было сказано, что в вашем противостоянии должен остаться лишь один.','Верховный маг Лан\'далок из Даларана просит вас принести ему осколок души Черного рыцаря.$B$BЭто задание выполняется в героическом режиме.','Приятно видеть, что ты $Gвышел:вышла; из испытания победителем. Поистине, ты чемпион не только Серебряного Авангарда, но и Кирин-Тора.$B$BОстается только надеяться, что ты $Gнанес:нанесла; последний удар этому темному злодею.','Черный Рыцарь появился неожиданно, как предвидел Верховный маг Времиар?','Вернитесь к верховному магу Лан\'далоку в Опустевшие леса, что в Лесу Хрустальной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Победный трофей: Черный рыцарь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мой коллега, Верховный маг Времиар, попросил меня предупредить тебя об опасности. Скоро ты будешь участвовать в Испытании чемпиона в Ледяной Короне. Остерегайся вмешательства со стороны соперника, известного как Черный рыцарь.$B$BПринеси мне осколок его души в доказательство того, что он больше не станет на пути Кирин-Тора. Мне было сказано, что в вашем противостоянии должен остаться лишь один.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верховный маг Лан\'далок из Даларана просит вас принести ему осколок души Черного рыцаря.$B$BЭто задание выполняется в героическом режиме.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Приятно видеть, что ты $Gвышел:вышла; из испытания победителем. Поистине, ты чемпион не только Серебряного Авангарда, но и Кирин-Тора.$B$BОстается только надеяться, что ты $Gнанес:нанесла; последний удар этому темному злодею.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Черный Рыцарь появился неожиданно, как предвидел Верховный маг Времиар?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному магу Лан\'далоку в Опустевшие леса, что в Лесу Хрустальной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (14200,'Знак для почты – начало') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Знак для почты – начало',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14201,'Тысяча историй на песке','Руины вокруг озера Меннар, что к востоку отсюда, могут многое рассказать. Низшие расы – такие, как неуклюжие дворфы – воюют за правду кирками и лопатами. <Малинея морщит нос.> Мы прибегнем к более элегантным методам.$b$bМоя магия ясновидения, конечно, немного устарела, но все же у меня должно получиться приподнять покровы времени. Кости моих предков давно уже истлели, но какие-то их личные драгоценности еще могли уцелеть – принеси мне немного.','Соберите 5 эльфийских артефактов в руинах вокруг озера Меннар в Азшаре.','Сделал за меня черную работу?','Принесите эльфийские артефакты Малинее Опустошительнице Небес на оргриммарскую пересадочную станцию ракетной дороги в Азшаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тысяча историй на песке',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Руины вокруг озера Меннар, что к востоку отсюда, могут многое рассказать. Низшие расы – такие, как неуклюжие дворфы – воюют за правду кирками и лопатами. <Малинея морщит нос.> Мы прибегнем к более элегантным методам.$b$bМоя магия ясновидения, конечно, немного устарела, но все же у меня должно получиться приподнять покровы времени. Кости моих предков давно уже истлели, но какие-то их личные драгоценности еще могли уцелеть – принеси мне немного.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 5 эльфийских артефактов в руинах вокруг озера Меннар в Азшаре.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Сделал за меня черную работу?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите эльфийские артефакты Малинее Опустошительнице Небес на оргриммарскую пересадочную станцию ракетной дороги в Азшаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14202,'Исследование озера','Надо снести все эти грязные древние руины, если мы хотим извлечь всю пользу из Азшары. Посмотри на мою карту – видишь озеро Меннар, на востоке? Я скажу тебе, что вижу на ней я: будущий склад ракетного топлива!$b$bНо нам нужно хорошенько изучить местность, прежде чем мы начнем сносить, рыть, засыпать землей и заливать озеро асфальтом. Все мои исследователи перепуганы чем-то, что витает в тех краях. Отправляйся туда с одним из моих младших геодезистов и сними показания с оборудования, которое там установлено.','Проводите гоблина-геодезиста к трем устройствам исследовательского оборудования, установленного вокруг озера Меннар, и защищайте его, пока он снимает показания. Другого геодезиста всегда можно вызвать при помощи маяка геодезиста.','Прекрасно! Теперь мы лучше знаем озеро и можем изменить его.','Кучка дохлых эльфов не помешает прогрессу. Не в мою смену!','Вернитесь к Кустеру Дубнику на оргриммарскую пересадочную станцию ракетной дороги в Азшаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Исследование озера',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Надо снести все эти грязные древние руины, если мы хотим извлечь всю пользу из Азшары. Посмотри на мою карту – видишь озеро Меннар, на востоке? Я скажу тебе, что вижу на ней я: будущий склад ракетного топлива!$b$bНо нам нужно хорошенько изучить местность, прежде чем мы начнем сносить, рыть, засыпать землей и заливать озеро асфальтом. Все мои исследователи перепуганы чем-то, что витает в тех краях. Отправляйся туда с одним из моих младших геодезистов и сними показания с оборудования, которое там установлено.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проводите гоблина-геодезиста к трем устройствам исследовательского оборудования, установленного вокруг озера Меннар, и защищайте его, пока он снимает показания. Другого геодезиста всегда можно вызвать при помощи маяка геодезиста.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно! Теперь мы лучше знаем озеро и можем изменить его.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Кучка дохлых эльфов не помешает прогрессу. Не в мою смену!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кустеру Дубнику на оргриммарскую пересадочную станцию ракетной дороги в Азшаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (14203,'Промокший рецепт','Похоже, это остатки смеси, применяемой для изготовления очень крепкого вина. Возможно, владелец лавки "Еще по сто" заинтересуется этим рецептом...','Принесите промокший рецепт Кристи Стоктон в Даларан.','Вернитесь к Кристи Стоктон на Железную плотину, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Промокший рецепт',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Похоже, это остатки смеси, применяемой для изготовления очень крепкого вина. Возможно, владелец лавки "Еще по сто" заинтересуется этим рецептом...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите промокший рецепт Кристи Стоктон в Даларан.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кристи Стоктон на Железную плотину, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (14204,'Из тени','Он стал одним из них, да? Как мы можем сражаться с врагом, который может сотворить подобное с каждым из нас?$B$BЗнаешь, для начала мы могли бы воспользоваться арсеналом моего отца.$B$BПлохо только, что повсюду на улицах скрываются воргены. Возьми одного из моих мастифов – они все обучены выслеживать этих тварей.$B$BНадо расчистить путь, иначе мы не сможем вытащить пушки на поверхность.','Убейте 6 скрытней из стаи Кровавых Клыков.','Превосходно. Я немедленно начну установку пушек.','Вернитесь к Лорне Краули в Военный квартал Гилнеаса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Из тени',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Он стал одним из них, да? Как мы можем сражаться с врагом, который может сотворить подобное с каждым из нас?$B$BЗнаешь, для начала мы могли бы воспользоваться арсеналом моего отца.$B$BПлохо только, что повсюду на улицах скрываются воргены. Возьми одного из моих мастифов – они все обучены выслеживать этих тварей.$B$BНадо расчистить путь, иначе мы не сможем вытащить пушки на поверхность.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 6 скрытней из стаи Кровавых Клыков.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Превосходно. Я немедленно начну установку пушек.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лорне Краули в Военный квартал Гилнеаса.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (14209,'Субстанция в двигателе','Десять тысяч лет ветров и непогоды не разрушили эти древние руины. Поэтому я использую мой лучший и самый большой бульдозер, чтобы сровнять их с землей. Я дал ему имя – Марджен.$b$bНо недавно он меня подвел, $n. В тот самый момент, когда мы оказались в этих заколдованных лесах, его мотор испустил душераздирающий стон и перестал работать. И теперь мои инженеры говорят, что его клапаны чем-то забиты. Отправляйся туда и осмотри моторный отсек Марджена, а мне принеси образец того, что туда попало.','Осмотрите бульдозер Дубника и соберите образцы неизвестной субстанции, которые засорили двигатель.','Принесите образец неизвестной субстанции Кустеру Дубнику на оргриммарскую пересадочную станцию ракетной дороги в Азшаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Субстанция в двигателе',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Десять тысяч лет ветров и непогоды не разрушили эти древние руины. Поэтому я использую мой лучший и самый большой бульдозер, чтобы сровнять их с землей. Я дал ему имя – Марджен.$b$bНо недавно он меня подвел, $n. В тот самый момент, когда мы оказались в этих заколдованных лесах, его мотор испустил душераздирающий стон и перестал работать. И теперь мои инженеры говорят, что его клапаны чем-то забиты. Отправляйся туда и осмотри моторный отсек Марджена, а мне принеси образец того, что туда попало.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Осмотрите бульдозер Дубника и соберите образцы неизвестной субстанции, которые засорили двигатель.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите образец неизвестной субстанции Кустеру Дубнику на оргриммарскую пересадочную станцию ракетной дороги в Азшаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (14212,'Готовность к жертве','Поговорите с Тобиасом Мистмантлом в Соборе Рассвета, что в Гилнеасе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Готовность к жертве',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Тобиасом Мистмантлом в Соборе Рассвета, что в Гилнеасе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (14213,'Десять фунтов плоти','Согласно записям Фуриена, эта древняя жаровня предназначена для жертвоприношений.$B$BЕсли вы правильно поняли расшифрованные фрагменты, всякому, кто положит в горящую жаровню плоть убитых врагов Элуны, дается божественное благословение.$B$BОглядевшись по сторонам, вы решаете, что сатиры, завладевшие этими землями, вполне подойдут в качестве жертвы.','Соберите 10 кусков плоти сатиров Саргерона и положите их на жаровню Элуны.','Вам даруется божественное благословение.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Десять фунтов плоти',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Согласно записям Фуриена, эта древняя жаровня предназначена для жертвоприношений.$B$BЕсли вы правильно поняли расшифрованные фрагменты, всякому, кто положит в горящую жаровню плоть убитых врагов Элуны, дается божественное благословение.$B$BОглядевшись по сторонам, вы решаете, что сатиры, завладевшие этими землями, вполне подойдут в качестве жертвы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 кусков плоти сатиров Саргерона и положите их на жаровню Элуны.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вам даруется божественное благословение.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (14214,'Послание Седогриву','Поговорите с королем Генном Седогривом в Военном квартале.','Я знал, что Краули примет правильное решение. Его арсенал нам очень поможет.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Послание Седогриву',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с королем Генном Седогривом в Военном квартале.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я знал, что Краули примет правильное решение. Его арсенал нам очень поможет.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (14215,'Воспоминания мертвых','Руны на найденном тобой перстне еще читаются: его вручили Калифе, когда ей дали доступ в Академию. Пара правильных заклинаний, и этот артефакт откроет нам ее душу.$b$BОтнеси перстень обратно на озеро Меннар. Теперь дух Калифы должен быть виден тебе на берегу. Прикоснись к ней, и перстень даст тебе возможность видеть мир ее глазами и пережить последние часы ее жизни. Изучи ее мысли, $n! Поговори с другими духами и узнай секреты озера Меннар...','Отнесите перстень Калифы на берег озера Меннар. Прикоснитесь к духу Калифы, чтобы пережить ее воспоминания. Поговорите с другими духами, пока не узнаете секреты озера Меннар.','Вы чувствуете головокружение, когда видения исчезают, и с облегчением ощущаете под своими ногами землю, а в груди – ваше трепещущее сердце.','Отнесите перстень Калифы на берег озера Меннар. Прикоснитесь к духу Калифы, чтобы пережить ее воспоминания. Поговорите с другими духами, пока не узнаете секреты озера Меннар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Воспоминания мертвых',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Руны на найденном тобой перстне еще читаются: его вручили Калифе, когда ей дали доступ в Академию. Пара правильных заклинаний, и этот артефакт откроет нам ее душу.$b$BОтнеси перстень обратно на озеро Меннар. Теперь дух Калифы должен быть виден тебе на берегу. Прикоснись к ней, и перстень даст тебе возможность видеть мир ее глазами и пережить последние часы ее жизни. Изучи ее мысли, $n! Поговори с другими духами и узнай секреты озера Меннар...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите перстень Калифы на берег озера Меннар. Прикоснитесь к духу Калифы, чтобы пережить ее воспоминания. Поговорите с другими духами, пока не узнаете секреты озера Меннар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы чувствуете головокружение, когда видения исчезают, и с облегчением ощущаете под своими ногами землю, а в груди – ваше трепещущее сердце.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите перстень Калифы на берег озера Меннар. Прикоснитесь к духу Калифы, чтобы пережить ее воспоминания. Поговорите с другими духами, пока не узнаете секреты озера Меннар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (14216,'Загадка песчаникового камня','Перед своей смертью Калифа должна была спрятать что-то на дне озера, мощный артефакт, на создание которого верховные маги потратили последние минуты своей жизни. Нет никаких сомнений в том, что Малинея Опустошительница Небес захочет увидеть этот артефакт, если, конечно, он все еще существует. Исследуй дно озера Меннар, чтобы найти его.','Достаньте песчаниковый камень со дна озера Меннар.','Отнесите песчаниковый камень Малинее Опустошительнице Небес на оргриммарскую пересадочную станцию ракетной дороги в Азшаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Загадка песчаникового камня',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Перед своей смертью Калифа должна была спрятать что-то на дне озера, мощный артефакт, на создание которого верховные маги потратили последние минуты своей жизни. Нет никаких сомнений в том, что Малинея Опустошительница Небес захочет увидеть этот артефакт, если, конечно, он все еще существует. Исследуй дно озера Меннар, чтобы найти его.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Достаньте песчаниковый камень со дна озера Меннар.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите песчаниковый камень Малинее Опустошительнице Небес на оргриммарскую пересадочную станцию ракетной дороги в Азшаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (14217,'Жертвоприношение сатиров','Как все забавно выходит: вы получаете благословение в храме богини ваших врагов!$B$BВпрочем, благословение никогда не лишнее, и вы собираетесь использовать эту возможность с максимальной пользой для себя.','Соберите 10 кусков плоти сатиров Саргерона и положите их на жаровню Элуны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жертвоприношение сатиров',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как все забавно выходит: вы получаете благословение в храме богини ваших врагов!$B$BВпрочем, благословение никогда не лишнее, и вы собираетесь использовать эту возможность с максимальной пользой для себя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 кусков плоти сатиров Саргерона и положите их на жаровню Элуны.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (14218,'Кровь и пепел','Время пришло, $n. Если мы намереваемся сократить их численность, лучшего момента не придумаешь.$B$BМы заняли стратегически выгодную позицию, у нас есть достаточно оружия.$B$BОсталось узнать, хватит ли нам смелости... но я не думаю, что сейчас вижу перед собой труса.','Вернитесь к Тобиасу Мистмантлу, который ждет возле Собора Рассвета в Гилнеасе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кровь и пепел',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Время пришло, $n. Если мы намереваемся сократить их численность, лучшего момента не придумаешь.$B$BМы заняли стратегически выгодную позицию, у нас есть достаточно оружия.$B$BОсталось узнать, хватит ли нам смелости... но я не думаю, что сейчас вижу перед собой труса.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тобиасу Мистмантлу, который ждет возле Собора Рассвета в Гилнеасе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`) VALUES (14219,'Оружие поверженного врага','Вы сразу узнали эту статую – по рисунку в записях Фуриена.$B$BВы пока не смогли прочитать записи рядом с изображением, но по рисунку и так все ясно. После битвы оружие поверженного врага складывали у подножия статуи в обмен на какой-то божественный дар.$B$BПока вы размышляете над этим ритуалом, ваш взгляд привлекает блеск стали на ближайшей оружейной стойке...','Соберите 20 сабель сатиров – возьмите с оружейных стоек или отберите у сатиров, обитающих в этих краях, – и сложите их у подножия статуи прислужницы Элуны.','Ритуал завершен, и вы получаете божественный дар.$B$BВы невольно задумываетесь о том, а что бы сказала Элуна, если бы узнала, кому она сейчас подарила свое благословение.','Статуя стоит, как будто в ожидании.','Военный обряд Элуны совершен') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оружие поверженного врага',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы сразу узнали эту статую – по рисунку в записях Фуриена.$B$BВы пока не смогли прочитать записи рядом с изображением, но по рисунку и так все ясно. После битвы оружие поверженного врага складывали у подножия статуи в обмен на какой-то божественный дар.$B$BПока вы размышляете над этим ритуалом, ваш взгляд привлекает блеск стали на ближайшей оружейной стойке...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 20 сабель сатиров – возьмите с оружейных стоек или отберите у сатиров, обитающих в этих краях, – и сложите их у подножия статуи прислужницы Элуны.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ритуал завершен, и вы получаете божественный дар.$B$BВы невольно задумываетесь о том, а что бы сказала Элуна, если бы узнала, кому она сейчас подарила свое благословение.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Статуя стоит, как будто в ожидании.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Военный обряд Элуны совершен',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (14220,'Конец всего') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Конец всего',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (14221,'Отступать, но не сдаваться','Поговорите с лордом Дарием Краули в Соборе Рассвета.','Мы отдали им все, что у нас было... но они все равно вернулись. Не беспокойся, $n. Мы перебьем многих из них еще до заката.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отступать, но не сдаваться',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с лордом Дарием Краули в Соборе Рассвета.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мы отдали им все, что у нас было... но они все равно вернулись. Не беспокойся, $n. Мы перебьем многих из них еще до заката.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (14222,'Последний рубеж','Нас зажали в тиски, $n. Молись, если думаешь, что это тебе поможет.$B$BА теперь давай наберемся смелости и перебьем этих шавок.','Вернитесь к лорду Дарию Краули в Собор Рассвета, что в Гилнеасе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Последний рубеж',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нас зажали в тиски, $n. Молись, если думаешь, что это тебе поможет.$B$BА теперь давай наберемся смелости и перебьем этих шавок.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лорду Дарию Краули в Собор Рассвета, что в Гилнеасе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (14223,'Спокойный сон капитана','Мы – передовой пост сил в этом регионе, и отвечаем за то, чтобы заранее выявить возможных противников и избавить Орду от неприятных сюрпризов, когда начнется кампания в Пустошах.$B$BНедавно один из наших разведчиков был пойман и принесен в жертву адептами Пылающего Клинка в их крепости к востоку отсюда. С тех самых пор я постоянно получаю угрозы от одного из этих выскочек по имени Кохор.$B$BДни ордена сочтены, но я с удовольствием заплачу из собственного кармана тому, кто заткнет этого гада прямо сейчас!','Убейте Кохора по просьбе Соррема с Поста Фуриена.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спокойный сон капитана',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы – передовой пост сил в этом регионе, и отвечаем за то, чтобы заранее выявить возможных противников и избавить Орду от неприятных сюрпризов, когда начнется кампания в Пустошах.$B$BНедавно один из наших разведчиков был пойман и принесен в жертву адептами Пылающего Клинка в их крепости к востоку отсюда. С тех самых пор я постоянно получаю угрозы от одного из этих выскочек по имени Кохор.$B$BДни ордена сочтены, но я с удовольствием заплачу из собственного кармана тому, кто заткнет этого гада прямо сейчас!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Кохора по просьбе Соррема с Поста Фуриена.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (14225,'Ты поймешь, когда увидишь','Перед смертью Кохор упомнянул о призыве какого-то ужасного демона, который может угрожать всему региону.$B$BСкорее всего, он блефовал, но для очистки совести стоит проверить информацию.$B$BМы не можем ждать до того момента, когда вторжение Орды в Пустоши наберет силу. Обыщи крепость Громового Топора в поисках улик и предотврати трагедию, если угроза действительно существует.','Найдите следы древнего ритуала призыва в крепости Громового Топора по просьбе Соррема с Поста Фуриена.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ты поймешь, когда увидишь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Перед смертью Кохор упомнянул о призыве какого-то ужасного демона, который может угрожать всему региону.$B$BСкорее всего, он блефовал, но для очистки совести стоит проверить информацию.$B$BМы не можем ждать до того момента, когда вторжение Орды в Пустоши наберет силу. Обыщи крепость Громового Топора в поисках улик и предотврати трагедию, если угроза действительно существует.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите следы древнего ритуала призыва в крепости Громового Топора по просьбе Соррема с Поста Фуриена.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (14226,'Проблема под ногами','Посмотри на себя. Выполняешь поручения. $gТакой ответственный:Такая ответственная;. Двигаешься все дальше и дальше... вперед и вперед!$b$bА впереди демоны! Разнообразные неприятные демоны. Демоны, которые бы оценили твои внутренности! Но не волнуйся. Нет-нет, нет оснований для беспокойства, я дам тебе помощника!$b$bПрицелиться, превратить в насекомое, прихлопнуть. Прицелиться, превратить в насекомое, прихлопнуть! Довольно эффективно. И довольно неопрятно... но все равно, не надо переживать. Нет-нет, не волнуйся, в конце концов не нам же это убирать!','Воспользуйтесь личным чародейским помощником, чтобы обратить в насекомых 12 демонов, а затем прихлопнуть их.','<Кажется, что верховный маг Ксилем исполняет какое-то подобие танца, когда поворачивается к вам.>$B$BНе волнуйся и, самое главное, помни о том, что если выделения жуков попадут на тебя, ты пожалеешь… Впрочем, ты в любом случае пожалеешь. Твои ботинки и сейчас-то не очень хорошо пахнут, а завтра они будут просто вонять!','Вернитесь к проекции верховного мага Ксилема в руины Нордрессы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Проблема под ногами',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Посмотри на себя. Выполняешь поручения. $gТакой ответственный:Такая ответственная;. Двигаешься все дальше и дальше... вперед и вперед!$b$bА впереди демоны! Разнообразные неприятные демоны. Демоны, которые бы оценили твои внутренности! Но не волнуйся. Нет-нет, нет оснований для беспокойства, я дам тебе помощника!$b$bПрицелиться, превратить в насекомое, прихлопнуть. Прицелиться, превратить в насекомое, прихлопнуть! Довольно эффективно. И довольно неопрятно... но все равно, не надо переживать. Нет-нет, не волнуйся, в конце концов не нам же это убирать!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь личным чародейским помощником, чтобы обратить в насекомых 12 демонов, а затем прихлопнуть их.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Кажется, что верховный маг Ксилем исполняет какое-то подобие танца, когда поворачивается к вам.>$B$BНе волнуйся и, самое главное, помни о том, что если выделения жуков попадут на тебя, ты пожалеешь… Впрочем, ты в любом случае пожалеешь. Твои ботинки и сейчас-то не очень хорошо пахнут, а завтра они будут просто вонять!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к проекции верховного мага Ксилема в руины Нордрессы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (14227,'Голова на голове','Соберите 100 отбеленных черепов в Крепости Громового Топора, затем принесите их в круг призыва Пылающего Клинка, вызовите и убейте Назаргена.','Поговорите с Сорремом на Посту Фуриена.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Голова на голове',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 100 отбеленных черепов в Крепости Громового Топора, затем принесите их в круг призыва Пылающего Клинка, вызовите и убейте Назаргена.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Сорремом на Посту Фуриена.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14230,'Потрясающе. Возвращайся к делам.$B$BСпасибо, малыш.','И это снова ты... Полагаю, ты вернулся с моей книгой?','Вернитесь к Терезе Остролист в руины Нордрессы.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Потрясающе. Возвращайся к делам.$B$BСпасибо, малыш.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','И это снова ты... Полагаю, ты вернулся с моей книгой?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Терезе Остролист в руины Нордрессы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (14231,'Useless quest record') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Useless quest record',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (14232,'Надрать уши','Ни для кого не секрет, что Соррем презирает клан Пылающего Клинка, занявший крепость Громового Топора.$B$BДумаю, ему придется по вкусу, если кто-то задаст им трепку.','Принесите 25 ушей прислужников Пылающего Клинка Соррему на Пост Фуриена.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Надрать уши',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ни для кого не секрет, что Соррем презирает клан Пылающего Клинка, занявший крепость Громового Топора.$B$BДумаю, ему придется по вкусу, если кто-то задаст им трепку.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 25 ушей прислужников Пылающего Клинка Соррему на Пост Фуриена.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (14233,'Орки умеют писать?','Разбирая вещи мертвого орка, вы нашли полевой дневник. Он сильно намок, однако текст можно разобрать, хотя и с трудом.$B$BВы быстро пролистываете дневник и понимаете, что на его страницах изложена весьма интересная история. Как хорошо, что когда-то вы решили выучить язык орков!$B$BОказывается, боевые корабли Альянса стреляли не только по яхте торгового принца, но и по оркам. И вы припоминаете, что за минуту до того, как Альянс открыл огонь, мимо вас прошел боевой корабль орков. Может, корабли Альянса стреляли не в вас, а в орков?$B$BПроклятые орки! Это из-за них вас потопили!','Отнесите полевой дневник Хамми Кофельнагель на Берег Кораблекрушения на Затерянных островах.','Орки? Их корабль потопили, и они оказались на острове? А теперь на этот остров прибыли и войска Альянса? Как ты думаешь, они убьют нас?$B$B<Хамми задумчиво смотрит вдаль.>$B$BЗнаешь, что? Кажется, пора потолковать с этими орками.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Орки умеют писать?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Разбирая вещи мертвого орка, вы нашли полевой дневник. Он сильно намок, однако текст можно разобрать, хотя и с трудом.$B$BВы быстро пролистываете дневник и понимаете, что на его страницах изложена весьма интересная история. Как хорошо, что когда-то вы решили выучить язык орков!$B$BОказывается, боевые корабли Альянса стреляли не только по яхте торгового принца, но и по оркам. И вы припоминаете, что за минуту до того, как Альянс открыл огонь, мимо вас прошел боевой корабль орков. Может, корабли Альянса стреляли не в вас, а в орков?$B$BПроклятые орки! Это из-за них вас потопили!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите полевой дневник Хамми Кофельнагель на Берег Кораблекрушения на Затерянных островах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Орки? Их корабль потопили, и они оказались на острове? А теперь на этот остров прибыли и войска Альянса? Как ты думаешь, они убьют нас?$B$B<Хамми задумчиво смотрит вдаль.>$B$BЗнаешь, что? Кажется, пора потолковать с этими орками.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (14234,'Враг моего врага','Мне жутко не хочется просить тебя об этом, но ведь не зря же тебе так много платят. Можешь отнести полевой дневник мертвого орка тому, кто всем заправляет у них в лагере?$B$BСудя по тому, что там написано, они должны быть где-то на вершине острова, так что иди вверх по склону, мимо Каджа\'митовой пещеры, держи курс на юго-восток.$B$BНу, удачи, $n. Ты мне всегда $gнравился:нравилась;.','Доставьте полевой дневник Аггре в главный лагерь Орды на Затерянных островах.','<Аггра пытается вырвать у вас из рук полевой журнал, но потом останавливается и делает глубокий вдох.>$B$BИзвини. Последняя пара дней была очень тяжелой для всех нас.$B$BМеня зовут Аггра. Мы – это все, что осталось от команды "Ярости Дреки".$B$BМожет быть, у нас получится сработаться. Ведь Альянс – наш общий враг. Остров кишит убийцами из ШРУ, и они не остановятся, пока хоть кто-то из нас будет жив.','<Орк смотрит на вас, и глаза ее сужаются.>$B$BДолжно быть, ты с того затонувшего гоблинского корабля с рабами. А что это у тебя в руке?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Враг моего врага',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне жутко не хочется просить тебя об этом, но ведь не зря же тебе так много платят. Можешь отнести полевой дневник мертвого орка тому, кто всем заправляет у них в лагере?$B$BСудя по тому, что там написано, они должны быть где-то на вершине острова, так что иди вверх по склону, мимо Каджа\'митовой пещеры, держи курс на юго-восток.$B$BНу, удачи, $n. Ты мне всегда $gнравился:нравилась;.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте полевой дневник Аггре в главный лагерь Орды на Затерянных островах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Аггра пытается вырвать у вас из рук полевой журнал, но потом останавливается и делает глубокий вдох.>$B$BИзвини. Последняя пара дней была очень тяжелой для всех нас.$B$BМеня зовут Аггра. Мы – это все, что осталось от команды "Ярости Дреки".$B$BМожет быть, у нас получится сработаться. Ведь Альянс – наш общий враг. Остров кишит убийцами из ШРУ, и они не остановятся, пока хоть кто-то из нас будет жив.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Орк смотрит на вас, и глаза ее сужаются.>$B$BДолжно быть, ты с того затонувшего гоблинского корабля с рабами. А что это у тебя в руке?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (14235,'Гибельная долина','Наш охотник Килаг Жутеклык вместе с парой разведчиков отправился по этой тропе на запад, в долину. Они... ищут.. "драгоценный груз"... который мы охраняли, когда эти мерзавцы из Альянса потопили наш корабль.$B$BНо путь разведчикам преградили смертоносные растения.$B$B$n, докажи, что ты настоящий гоблин и |3-6($c). Отправляйся в Гибельную долину и найди Килага.','Найдите Килага Жутеклыка в Гибельной долине на Затерянных островах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гибельная долина',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наш охотник Килаг Жутеклык вместе с парой разведчиков отправился по этой тропе на запад, в долину. Они... ищут.. "драгоценный груз"... который мы охраняли, когда эти мерзавцы из Альянса потопили наш корабль.$B$BНо путь разведчикам преградили смертоносные растения.$B$B$n, докажи, что ты настоящий гоблин и |3-6($c). Отправляйся в Гибельную долину и найди Килага.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Килага Жутеклыка в Гибельной долине на Затерянных островах.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (14236,'Газонокосилка','<У Килага едва находится время между выстрелами, чтобы взглянуть на вас, но на миг его взгляд останавливается на вашем гоблинском все-в-одном-чудо-поясе.>$B$BТут требуется креативное решение. Вытаскивай что-нибудь подходящее из этого пояса и приступай к работе!$B$B<По краткому размышлению вам приходит в голову одна идея, и она достаточно безумна, чтобы сработать!>','С помощью газонокосилки в вашем гоблинском все-в-одном-чудо-поясе выкосите 100 растений в Гибельной долине.','Вернитесь к Килагу Жутеклыку в Гибельную долину на Затерянных островах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Газонокосилка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<У Килага едва находится время между выстрелами, чтобы взглянуть на вас, но на миг его взгляд останавливается на вашем гоблинском все-в-одном-чудо-поясе.>$B$BТут требуется креативное решение. Вытаскивай что-нибудь подходящее из этого пояса и приступай к работе!$B$B<По краткому размышлению вам приходит в голову одна идея, и она достаточно безумна, чтобы сработать!>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','С помощью газонокосилки в вашем гоблинском все-в-одном-чудо-поясе выкосите 100 растений в Гибельной долине.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Килагу Жутеклыку в Гибельную долину на Затерянных островах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (14237,'Движение вперед','Килаг уже должен был выйти на позицию. Следуй вперед, к Лесному наблюдательному пункту. Все остальные соберутся здесь и тоже скоро выдвинутся.$B$BИди по тропе на север, через Гибельную долину. Хотя благодаря твоим усилиям теперь она уже не такая и гибельная, верно?$B$BКилаг с разведчиками прячутся недалеко от тропы. Убийцы из ШРУ скоро их обнаружат, так что поторопись!','Найдите Килага Жутеклыка и его разведчиков на Лесном наблюдательном пункте на Затерянных островах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Движение вперед',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Килаг уже должен был выйти на позицию. Следуй вперед, к Лесному наблюдательному пункту. Все остальные соберутся здесь и тоже скоро выдвинутся.$B$BИди по тропе на север, через Гибельную долину. Хотя благодаря твоим усилиям теперь она уже не такая и гибельная, верно?$B$BКилаг с разведчиками прячутся недалеко от тропы. Убийцы из ШРУ скоро их обнаружат, так что поторопись!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Килага Жутеклыка и его разведчиков на Лесном наблюдательном пункте на Затерянных островах.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (14238,'Инфракрасный = Инфрамертвый','Тс-с, не шуми. Долина к северо-западу отсюда кишит убийцами Альянса.$B$BК сожалению, нам не удалось их обнаружить. Проклятые трусы! Прячутся и не хотят выходить на бой.$B$BНо гоблины славятся своими инженерными находками. Наверняка у тебя найдутся очки, которые позволят увидеть убийц!$B$BПоэтому я прошу тебя объединить усилия с одним из моих разведчиков и убить всех убийц из ШРУ, которые попадутся вам на пути.','Убейте 10 убийц из ШРУ.$B$BЕсли с вашим орком-разведчиком что-то случится, вернитесь к Килагу – возможно, он выдаст вам другого напарника.','Вернитесь к Килагу Жутеклыку на Затерянные острова, на Лесной наблюдательный пункт.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Инфракрасный = Инфрамертвый',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тс-с, не шуми. Долина к северо-западу отсюда кишит убийцами Альянса.$B$BК сожалению, нам не удалось их обнаружить. Проклятые трусы! Прячутся и не хотят выходить на бой.$B$BНо гоблины славятся своими инженерными находками. Наверняка у тебя найдутся очки, которые позволят увидеть убийц!$B$BПоэтому я прошу тебя объединить усилия с одним из моих разведчиков и убить всех убийц из ШРУ, которые попадутся вам на пути.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 убийц из ШРУ.$B$BЕсли с вашим орком-разведчиком что-то случится, вернитесь к Килагу – возможно, он выдаст вам другого напарника.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Килагу Жутеклыку на Затерянные острова, на Лесной наблюдательный пункт.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (14239,'Не иди к Свету!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Не иди к Свету!',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (14239,'Теперь все зависит от тебя. Вернешься ли ты к земной жизни и подвигам, которых ждут от тебя твои оставшиеся в живых собратья, или останешься здесь для вечной жизни?$B$BРешать только тебе.$B$BНе иди к Свету, Хорнеп!') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь все зависит от тебя. Вернешься ли ты к земной жизни и подвигам, которых ждут от тебя твои оставшиеся в живых собратья, или останешься здесь для вечной жизни?$B$BРешать только тебе.$B$BНе иди к Свету, Хорнеп!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (14240,'К утесам','По моему приказу разведчик Бракс отправился к утесам на побережье.$B$BА тебя я посажу на Бастию. Двигайся по тропе и передай Браксу, что мы пойдем другим путем.$B$BМы попытаемся выбить Альянс с его плацдарма! Там и увидимся!','Поговорите с разведчиком Браксом, который находится на Затерянных Островах, на тропе, ведущей к северу от Дикой лощины.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','К утесам',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','По моему приказу разведчик Бракс отправился к утесам на побережье.$B$BА тебя я посажу на Бастию. Двигайся по тропе и передай Браксу, что мы пойдем другим путем.$B$BМы попытаемся выбить Альянс с его плацдарма! Там и увидимся!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с разведчиком Браксом, который находится на Затерянных Островах, на тропе, ведущей к северу от Дикой лощины.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14241,'К гиролету!','Альянс похитил у нас кое-что очень важное для Орды. Сейчас оно находится на одном из их кораблей.$B$BНа другом краю плацдарма стоит гиролет. Иди к нему. Наши воины тебя прикроют.$B$BЗабери ключи от летающей машины у их агента.$B$BЛети к флагману, "Караулу Возмездия", и верни наш драгоценный груз!','Добудьте ключи от гиролета.','Проклятье, да что там с зажиганием?$B$BЭто будет просто чудо, если машина взлетит, не выкинув какой-нибудь штуки – не превратится в курицу, например, или не уменьшится до размеров муравья.$B$BСмотри, кто-то оставил мелочь в пепельнице! Интересно, что еще здесь есть?','Хм, это похоже на творение инженеров-гномов – с большим количеством ненужных деталей и мер предосторожности.','Отправляйтесь к гиролету, который находится на Затерянных островах на плацдарме Альянса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','К гиролету!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Альянс похитил у нас кое-что очень важное для Орды. Сейчас оно находится на одном из их кораблей.$B$BНа другом краю плацдарма стоит гиролет. Иди к нему. Наши воины тебя прикроют.$B$BЗабери ключи от летающей машины у их агента.$B$BЛети к флагману, "Караулу Возмездия", и верни наш драгоценный груз!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте ключи от гиролета.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Проклятье, да что там с зажиганием?$B$BЭто будет просто чудо, если машина взлетит, не выкинув какой-нибудь штуки – не превратится в курицу, например, или не уменьшится до размеров муравья.$B$BСмотри, кто-то оставил мелочь в пепельнице! Интересно, что еще здесь есть?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Хм, это похоже на творение инженеров-гномов – с большим количеством ненужных деталей и мер предосторожности.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отправляйтесь к гиролету, который находится на Затерянных островах на плацдарме Альянса.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (14242,'Драгоценный груз','Они сказали, их "драгоценный груз", чем бы он там ни был, хранится на корабле Альянса "Караул Возмездия".$B$BВыход у вас только один... Забраться в эту штуковину и отправиться за грузом!','Обнаружьте местонахождение драгоценного груза в трюме корабля Альянса "Караул Возмездия" у побережья Затерянных островов.','Если бы не ты, меня бы уже наверняка обратили в рабство и переправили в Штормград как почетный трофей.$B$BЭти псы альянсовские нашли меня на берегу без сознания и поместили в эту магическую клетку. В ней я не мог воззвать к стихиям.$B$BНо теперь ко мне вернулись силы!','Не поможешь выбраться из этой клетки?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Драгоценный груз',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Они сказали, их "драгоценный груз", чем бы он там ни был, хранится на корабле Альянса "Караул Возмездия".$B$BВыход у вас только один... Забраться в эту штуковину и отправиться за грузом!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обнаружьте местонахождение драгоценного груза в трюме корабля Альянса "Караул Возмездия" у побережья Затерянных островов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Если бы не ты, меня бы уже наверняка обратили в рабство и переправили в Штормград как почетный трофей.$B$BЭти псы альянсовские нашли меня на берегу без сознания и поместили в эту магическую клетку. В ней я не мог воззвать к стихиям.$B$BНо теперь ко мне вернулись силы!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Не поможешь выбраться из этой клетки?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (14243,'Возмездие вождя','Братья Земли и Огня, внимайте! Сестры Воды и Воздуха, услышьте мой зов!$B$BАзерот на краю гибели, самому его существованию угрожает опасность! Даруйте мне свою силу, как в древние времена вы наделяли ею моих предков. Позвольте мне сделать проводником вашей воли это дитя Кезана.$B$BДавайте покончим с теми, кто хочет воспрепятствовать нам в исцелении этого мира!','С помощью вихря стихий убейте 50 матросов Альянса.$B$BКогда это будет сделано, вас перенесут к Лесному наблюдательному пункту.','Ты справился с тем, что мало кому оказывалось под силу, Военфельдшер. Наш мир в долгу перед тобой – в большей степени, чем ты можешь себе представить.','Поговорите с вождем на Лесном наблюдательном пункте на Затерянных островах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возмездие вождя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Братья Земли и Огня, внимайте! Сестры Воды и Воздуха, услышьте мой зов!$B$BАзерот на краю гибели, самому его существованию угрожает опасность! Даруйте мне свою силу, как в древние времена вы наделяли ею моих предков. Позвольте мне сделать проводником вашей воли это дитя Кезана.$B$BДавайте покончим с теми, кто хочет воспрепятствовать нам в исцелении этого мира!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','С помощью вихря стихий убейте 50 матросов Альянса.$B$BКогда это будет сделано, вас перенесут к Лесному наблюдательному пункту.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты справился с тем, что мало кому оказывалось под силу, Военфельдшер. Наш мир в долгу перед тобой – в большей степени, чем ты можешь себе представить.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с вождем на Лесном наблюдательном пункте на Затерянных островах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (14244,'Вперед и вверх!','Пока ты $gзанимался:занималась; спасением вождя и всех нас от Альянса, штейгер Промоках соорудил вот эту ракетную пращу, чтобы перебросить нас через этот кишащий акулами пролив прямо на остров.$B$BК счастью, при кораблекрушении штейгеру удалось спасти Городок-из-табакерки. Когда ты его развернешь, у нас будет свой город. Хотелось бы поскорее... А то я уже и не помню, когда в последний раз спала в нормальной постели!$B$BПромоках ждет тебя на месте высадки. Отправляйся следующей ракетой.','Постарайтесь не погибнуть во время перелета через Зловещий пролив на ракете, запущенной из ракетной пращи.','Поговорите со штейгером Промокахом на месте высадки на Затерянных островах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вперед и вверх!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пока ты $gзанимался:занималась; спасением вождя и всех нас от Альянса, штейгер Промоках соорудил вот эту ракетную пращу, чтобы перебросить нас через этот кишащий акулами пролив прямо на остров.$B$BК счастью, при кораблекрушении штейгеру удалось спасти Городок-из-табакерки. Когда ты его развернешь, у нас будет свой город. Хотелось бы поскорее... А то я уже и не помню, когда в последний раз спала в нормальной постели!$B$BПромоках ждет тебя на месте высадки. Отправляйся следующей ракетой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Постарайтесь не погибнуть во время перелета через Зловещий пролив на ракете, запущенной из ракетной пращи.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите со штейгером Промокахом на месте высадки на Затерянных островах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (14245,'Городок-из-табакерки','В трюме корабля торгового принца был целый городок! Когда начался бой, мне удалось его стащить.$B$BХочешь принять участие в церемонии его развертывания? Тогда заберись на эту огромную гору взрывчатки и нажми на детонатор. И – ба-бах! – моментально построится город!','Заберитесь на гору взрывчатки и нажмите на поршень Городка-из-табакерки.','<Кашляет.>$B$BЭй! Где пристань?! Кто-то украл пристань и нефтезавод нашего Городка-из-табакерки!$B$BКто мог это сделать?$B$BГде торговый принц?','Поговорите со штейгером Промокахом в Городке-из-табакерки на Затерянных островах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Городок-из-табакерки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В трюме корабля торгового принца был целый городок! Когда начался бой, мне удалось его стащить.$B$BХочешь принять участие в церемонии его развертывания? Тогда заберись на эту огромную гору взрывчатки и нажми на детонатор. И – ба-бах! – моментально построится город!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заберитесь на гору взрывчатки и нажмите на поршень Городка-из-табакерки.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Кашляет.>$B$BЭй! Где пристань?! Кто-то украл пристань и нефтезавод нашего Городка-из-табакерки!$B$BКто мог это сделать?$B$BГде торговый принц?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите со штейгером Промокахом в Городке-из-табакерки на Затерянных островах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (14246,'Спасение перепелятников','Этот когда-то бесплодный край превращается в цветущий сад, и обитателям пустыни остается все меньше пространства для жизни.$B$BОни вымирают. И больше всего нас тревожит сокращение численности перепелятников. Хищники уничтожают птиц, разоряют их гнезда, поедают яйца.$B$BЯ приобрел в Танарисе несколько яиц перепелятников и покрыл их защитным феромоном. Разложи эти яйца по гнездам – по одному в каждое гнездо – и проследи, чтобы они оставались в сохранности, пока не появится перепелятник и не заберет яйцо.$B$BЭто будет твой вклад в сохранение природного равновесия на этой земле.','Разложите 3 яйца перепелятников по гнездам и защищайте яйца от хищников, пока птицы их не увидят и не заберут.','Вернитесь к Тунку, находящемуся в Обители Тунка в Пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спасение перепелятников',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этот когда-то бесплодный край превращается в цветущий сад, и обитателям пустыни остается все меньше пространства для жизни.$B$BОни вымирают. И больше всего нас тревожит сокращение численности перепелятников. Хищники уничтожают птиц, разоряют их гнезда, поедают яйца.$B$BЯ приобрел в Танарисе несколько яиц перепелятников и покрыл их защитным феромоном. Разложи эти яйца по гнездам – по одному в каждое гнездо – и проследи, чтобы они оставались в сохранности, пока не появится перепелятник и не заберет яйцо.$B$BЭто будет твой вклад в сохранение природного равновесия на этой земле.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разложите 3 яйца перепелятников по гнездам и защищайте яйца от хищников, пока птицы их не увидят и не заберут.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тунку, находящемуся в Обители Тунка в Пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (14247,'Упрямые земли','Я выполняю задание Круга Кенария: превращаю бесплодную пустошь в цветущие сочные луга.$B$BЗемли к югу отсюда хорошо приняли перемены, но здесь что-то мешает озеленению – пустыня сопротивляется всем нашим усилиям.$B$BМожет быть, ты сумеешь найти причину.$B$BПрошу тебя, |3-6($r). Обойди эти края и разыщи источник сопротивления.','По поручению Тунка из Обители Тунка отыщите необычный фрагмент ландшафта.','<Вы смотрите по сторонам, изучаете взглядом горизонт, пытаясь понять, откуда взялся этот камень и кто мог его здесь оставить…>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Упрямые земли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я выполняю задание Круга Кенария: превращаю бесплодную пустошь в цветущие сочные луга.$B$BЗемли к югу отсюда хорошо приняли перемены, но здесь что-то мешает озеленению – пустыня сопротивляется всем нашим усилиям.$B$BМожет быть, ты сумеешь найти причину.$B$BПрошу тебя, |3-6($r). Обойди эти края и разыщи источник сопротивления.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По поручению Тунка из Обители Тунка отыщите необычный фрагмент ландшафта.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Вы смотрите по сторонам, изучаете взглядом горизонт, пытаясь понять, откуда взялся этот камень и кто мог его здесь оставить…>',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (14248,'Требуется помощь!','Вот это новости! Штейгер Промоках обнаружил на острове пещеру, полную каджа\'мита! Это большая удача.$B$BКонечно, у всякой медали есть и оборотная сторона. Он взял с собой кое-кого из уцелевших, чтобы те помогли ему добыть руду, да только никто из них не вернулся.$B$BКаким безумием это ни кажется, но штейгер уверяет, что пещера кишмя кишит обезьянами... с кирками! И они добывают каджа\'мит! Как такое вообще может быть?$B$BМожешь $gсам:сама; отправиться на юго-восток, зайти в пещеру и посмотреть? Штейгера найдешь прямо у входа.','Поговорите со штейгером Промокахом у входа в Каджа\'митовую пещеру на Затерянных островах.','Босс! Э... ну, я типа понимаю, ты больше не босс, но... я рад тебя видеть!$B$BПросто не верится, да? Пещера, полная разумных и свирепых обезьян, копающих каджа\'мит!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Требуется помощь!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот это новости! Штейгер Промоках обнаружил на острове пещеру, полную каджа\'мита! Это большая удача.$B$BКонечно, у всякой медали есть и оборотная сторона. Он взял с собой кое-кого из уцелевших, чтобы те помогли ему добыть руду, да только никто из них не вернулся.$B$BКаким безумием это ни кажется, но штейгер уверяет, что пещера кишмя кишит обезьянами... с кирками! И они добывают каджа\'мит! Как такое вообще может быть?$B$BМожешь $gсам:сама; отправиться на юго-восток, зайти в пещеру и посмотреть? Штейгера найдешь прямо у входа.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите со штейгером Промокахом у входа в Каджа\'митовую пещеру на Затерянных островах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Босс! Э... ну, я типа понимаю, ты больше не босс, но... я рад тебя видеть!$B$BПросто не верится, да? Пещера, полная разумных и свирепых обезьян, копающих каджа\'мит!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (14249,'Приодеть Вилла','Буду изумительным верховным магом! Великолепным! Если у меня не будет этих идиотских одеяний и шляпы, он не станет даже разговаривать со мной. Пффф.$b$bСамый необыкновенный верховный маг, какого только видела эта земля, не может быть одет во что попало. Я должен показать ему, что я особенный, и я знаю, как это сделать.$b$bИди и убей этих гиппогрифов. И принеси мне МНОГО перьев.$b$bТы меня $gслышал:слышала;? Большую охапку перьев! Давай-давай, к тому моменту, когда вернешься, одеяние будет уже почти готово.','Добудьте 80 нетронутых перьев громоголова у гиппогрифов возле руин Нордрессы.','Ха-ха! Прекрасно! Давай-ка по-быстрому соберем все вместе. Без сомнения, я произведу на верховного мага впечатление своим одеянием!','Вернитесь к Виллу Роботронику в руины Нордрессы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приодеть Вилла',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Буду изумительным верховным магом! Великолепным! Если у меня не будет этих идиотских одеяний и шляпы, он не станет даже разговаривать со мной. Пффф.$b$bСамый необыкновенный верховный маг, какого только видела эта земля, не может быть одет во что попало. Я должен показать ему, что я особенный, и я знаю, как это сделать.$b$bИди и убей этих гиппогрифов. И принеси мне МНОГО перьев.$b$bТы меня $gслышал:слышала;? Большую охапку перьев! Давай-давай, к тому моменту, когда вернешься, одеяние будет уже почти готово.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 80 нетронутых перьев громоголова у гиппогрифов возле руин Нордрессы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ха-ха! Прекрасно! Давай-ка по-быстрому соберем все вместе. Без сомнения, я произведу на верховного мага впечатление своим одеянием!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Виллу Роботронику в руины Нордрессы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14250,'Возобновляемый ресурс','Нам снова нужен оживленный базальт. В округе есть только один надежный источник – это горный гигант по имени Бальбоа. Убивать его нельзя, если мы хотим получать базальт и дальше, так что нужно просто обрубить нужные куски за один раз.$b$bОн бродит к северо-востоку и к востоку отсюда. Найди его, заложи на его пути заряд, и потом прячься, пока не выстрелит. Когда он скроется, сможешь взять базальт и принести мне.','Воспользуйтесь чародейским зарядом, чтобы получить 5 порций оживленного базальта от Бальбоа в руинах Нордрессы.','Отлично. Теперь мы продержимся несколько часов, прежде чем придется идти за новой порцией.$B$BБальбоа не назовешь сообразительным, так что, надеюсь, мы еще некоторое время сможем пополнять запасы, пока до него не дойдет.','Я слышал взрывы. Не знаю, твои это были или нет... от гоблинов тоже бывает много шума.','Вернитесь к Таркулу Железному Черепу в руины Нордрессы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возобновляемый ресурс',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нам снова нужен оживленный базальт. В округе есть только один надежный источник – это горный гигант по имени Бальбоа. Убивать его нельзя, если мы хотим получать базальт и дальше, так что нужно просто обрубить нужные куски за один раз.$b$bОн бродит к северо-востоку и к востоку отсюда. Найди его, заложи на его пути заряд, и потом прячься, пока не выстрелит. Когда он скроется, сможешь взять базальт и принести мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь чародейским зарядом, чтобы получить 5 порций оживленного базальта от Бальбоа в руинах Нордрессы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично. Теперь мы продержимся несколько часов, прежде чем придется идти за новой порцией.$B$BБальбоа не назовешь сообразительным, так что, надеюсь, мы еще некоторое время сможем пополнять запасы, пока до него не дойдет.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я слышал взрывы. Не знаю, твои это были или нет... от гоблинов тоже бывает много шума.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Таркулу Железному Черепу в руины Нордрессы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14251,'Новое начало','Никогда раньше кентавры не забирались так далеко на север. Кто-то их надоумил!$B$BКак бы там ни было, я разорен. Я вложил все в этот груз.$B$BК счастью, ни один кентавр не сможет лишить меня гоблинской смекалки! Я начну с самого начала и построю империю!$B$B<Бизби замечает вдали скорпиона.>$B$BЯд всегда в ходу. Что скажешь, друг?','Соберите 15 жал скорпиона.','Вот так я и начал.$B$BПродавал яд оргриммарским разбойникам. Ах-х, какие были деньки….','Посмотрим-ка на эти скорпионьи хвосты, друг.','Вернитесь к Бизби, находящемуся в Караване Бизби, что в Пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новое начало',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Никогда раньше кентавры не забирались так далеко на север. Кто-то их надоумил!$B$BКак бы там ни было, я разорен. Я вложил все в этот груз.$B$BК счастью, ни один кентавр не сможет лишить меня гоблинской смекалки! Я начну с самого начала и построю империю!$B$B<Бизби замечает вдали скорпиона.>$B$BЯд всегда в ходу. Что скажешь, друг?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 15 жал скорпиона.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот так я и начал.$B$BПродавал яд оргриммарским разбойникам. Ах-х, какие были деньки….',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Посмотрим-ка на эти скорпионьи хвосты, друг.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бизби, находящемуся в Караване Бизби, что в Пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (14252,'Много золота за плохие хвосты','Соберите 15 хвостов старых василисков.','Вернитесь к Бизби, находящемуся в Караване Бизби, что в Пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Много золота за плохие хвосты',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 15 хвостов старых василисков.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бизби, находящемуся в Караване Бизби, что в Пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14253,'Оперите меня!','Скажи, |3-6($c), пока будешь исследовать пустыню, не сделаешь мне одолжение?$B$BПоищи жутких перепелятников. Их маслянистые перья лучше всего подойдут для оперения стрел, а правильному покупателю их можно продать за неплохую цену.$B$BК счастью для тебя, я знаю правильных покупателей!','Соберите 25 перьев жуткого перепелятника.','Как продвигаются поиски перепелятников?','Вернитесь к Бизби, находящемуся в Караване Бизби, что в Пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оперите меня!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Скажи, |3-6($c), пока будешь исследовать пустыню, не сделаешь мне одолжение?$B$BПоищи жутких перепелятников. Их маслянистые перья лучше всего подойдут для оперения стрел, а правильному покупателю их можно продать за неплохую цену.$B$BК счастью для тебя, я знаю правильных покупателей!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 25 перьев жуткого перепелятника.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как продвигаются поиски перепелятников?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бизби, находящемуся в Караване Бизби, что в Пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (14254,'Тяжелый металл','Вы почему-то уверены, что этот камень и есть причина того, что пустыня сопротивляется распространению растений.$B$BВы смотрите на запад и замечаете след из тлеющих обломков. Похоже, они как-то связаны с проблемой, о которой рассказывал Тунк.$B$BВас осеняет догадка, что, если убрать эти обломки, сопротивление пустыни исчезнет само собой.$B$BИ потом, их, наверное, можно как-то использовать?','Соберите 7 образцов элемента 116 и отнесите их Бизби из каравана Бизби.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тяжелый металл',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы почему-то уверены, что этот камень и есть причина того, что пустыня сопротивляется распространению растений.$B$BВы смотрите на запад и замечаете след из тлеющих обломков. Похоже, они как-то связаны с проблемой, о которой рассказывал Тунк.$B$BВас осеняет догадка, что, если убрать эти обломки, сопротивление пустыни исчезнет само собой.$B$BИ потом, их, наверное, можно как-то использовать?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 7 образцов элемента 116 и отнесите их Бизби из каравана Бизби.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (14255,'Этель-Ретор','У нас немало врагов в этих землях – не хотелось бы еще прогневить и Круг Кенария.$B$BКогда мы построили этот форт, представители Круга обратились к нам с просьбой присмотреть за одной их исследовательницей.$B$BВ последний раз Корру видели в башне на западе. Правда, довольно давно. Так что пора бы ее навестить. Сделай мне одолжение, сходи посмотри, все ли с ней хорошо.','По поручению Серелии с Поста Фуриена отправляйтесь к Корре в Этель-Ретор.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Этель-Ретор',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У нас немало врагов в этих землях – не хотелось бы еще прогневить и Круг Кенария.$B$BКогда мы построили этот форт, представители Круга обратились к нам с просьбой присмотреть за одной их исследовательницей.$B$BВ последний раз Корру видели в башне на западе. Правда, довольно давно. Так что пора бы ее навестить. Сделай мне одолжение, сходи посмотри, все ли с ней хорошо.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По поручению Серелии с Поста Фуриена отправляйтесь к Корре в Этель-Ретор.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (14256,'Угроза с моря','Из всей команды, отправленной наблюдать за изменениями на этом побережье Пустошей, уцелела лишь я одна.$B$BЯ уже доложила начальству об опасном увеличении численности наг, но, похоже, без толку.$B$BОни решают другие проблемы, им явно не до моих изысканий, и поэтому я вынуждена обратиться за помощью к тебе, $gчужеземец:чужестранка;.$B$BНо сначала я покажу тебе, с чем нам придется столкнуться.','Поговорите с Коррой и она вам покажет, чем опасны наги.','Итак, теперь ты понимаешь. Это не просто компания из нескольких наг, а целая армия, организованная и способная причинить очень серьезный ущерб.$B$BТак ты согласишься помочь мне в моих исследованиях?','Поговорите с кенарийской исследовательницей Коррой, находящейся в Этель-Реторе, что в Пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Угроза с моря',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Из всей команды, отправленной наблюдать за изменениями на этом побережье Пустошей, уцелела лишь я одна.$B$BЯ уже доложила начальству об опасном увеличении численности наг, но, похоже, без толку.$B$BОни решают другие проблемы, им явно не до моих изысканий, и поэтому я вынуждена обратиться за помощью к тебе, $gчужеземец:чужестранка;.$B$BНо сначала я покажу тебе, с чем нам придется столкнуться.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Коррой и она вам покажет, чем опасны наги.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Итак, теперь ты понимаешь. Это не просто компания из нескольких наг, а целая армия, организованная и способная причинить очень серьезный ущерб.$B$BТак ты согласишься помочь мне в моих исследованиях?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с кенарийской исследовательницей Коррой, находящейся в Этель-Реторе, что в Пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14257,'Охота на наг','Мы уже знаем, что наги – враги природного равновесия. И если прольется их кровь, я не стану терзаться угрызениями совести.$B$BНо их слишком много. Как бы мы ни старались, у нас все равно не получится уничтожить их всех – разве только слегка проредить их ряды.$B$BНо у меня есть план, |3-6($c). Ты будешь не только убивать врагов, но и собирать определенные компоненты, необходимые для моих дальнейших исследований...','Соберите 10 костей наг, 30 образцов чешуи колдуний и 4 гребня воинов из клана Скользящего Плавника.','Тебе удалось собрать все, что мне нужно?','Поговорите с кенарийской исследовательницей Коррой, находящейся в Этель-Реторе, что в Пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота на наг',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы уже знаем, что наги – враги природного равновесия. И если прольется их кровь, я не стану терзаться угрызениями совести.$B$BНо их слишком много. Как бы мы ни старались, у нас все равно не получится уничтожить их всех – разве только слегка проредить их ряды.$B$BНо у меня есть план, |3-6($c). Ты будешь не только убивать врагов, но и собирать определенные компоненты, необходимые для моих дальнейших исследований...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 костей наг, 30 образцов чешуи колдуний и 4 гребня воинов из клана Скользящего Плавника.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось собрать все, что мне нужно?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с кенарийской исследовательницей Коррой, находящейся в Этель-Реторе, что в Пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (14258,'Обстрел','После того как мы построили этот терминал ракетной дороги, наги начали двигаться на полуостров. Но в этом мире нет проблем, которые невозможно было бы решить при помощи огневой мощи! Мой папа всегда так говорил. До несчастного случая.$b$bКстати, у меня заканчиваются боеприпасы. Окажи мне услугу, собери снаряды для мортир, которые я сложил в секретной лаборатории к западу отсюда. Обеспечь меня боеприпасами, а я разрешу тебе пострелять!','Принесите 5 снарядов для гоблинской мортиры из секретной лаборатории в Азшаре.','Чудесно! Прекрасно! Прелестно!$B$BТеперь у меня есть боеприпасы для мортир, и я смогу прикрыть тебя, когда ты будешь атаковать наг к востоку отсюда. Воспользуйся этими знаками, чтобы отметить цели, а я полью огнем всю территорию. Устроим отличный, беспощадный, беспорядочный обстрел! Надеюсь, у тебя хорошая броня...','Принесите снаряды бомбардиру капитану Смуксу на Оргриммарскую южную конечную станцию ракетной дороги в Азшаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обстрел',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','После того как мы построили этот терминал ракетной дороги, наги начали двигаться на полуостров. Но в этом мире нет проблем, которые невозможно было бы решить при помощи огневой мощи! Мой папа всегда так говорил. До несчастного случая.$b$bКстати, у меня заканчиваются боеприпасы. Окажи мне услугу, собери снаряды для мортир, которые я сложил в секретной лаборатории к западу отсюда. Обеспечь меня боеприпасами, а я разрешу тебе пострелять!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 5 снарядов для гоблинской мортиры из секретной лаборатории в Азшаре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Чудесно! Прекрасно! Прелестно!$B$BТеперь у меня есть боеприпасы для мортир, и я смогу прикрыть тебя, когда ты будешь атаковать наг к востоку отсюда. Воспользуйся этими знаками, чтобы отметить цели, а я полью огнем всю территорию. Устроим отличный, беспощадный, беспорядочный обстрел! Надеюсь, у тебя хорошая броня...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите снаряды бомбардиру капитану Смуксу на Оргриммарскую южную конечную станцию ракетной дороги в Азшаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (14259,'Больше, больше снарядов!','Спасибо, что $gпомог:помогла; с боеприпасами, $n.$B$BВот что я тебе скажу: доставь мне из лаборатории еще снарядов, а я снабжу тебя сигнальными дымовыми шашками. Ты на поле, я за орудиями – вместе мы разнесем эти скалы так, что они целиком обрушатся в море!','Доставьте 5 снарядов для гоблинской мортиры из Секретной Лаборатории в Азшаре.','Принесите снаряды бомбардиру капитану Смуксу на Оргриммарскую южную конечную станцию ракетной дороги в Азшаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Больше, больше снарядов!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Спасибо, что $gпомог:помогла; с боеприпасами, $n.$B$BВот что я тебе скажу: доставь мне из лаборатории еще снарядов, а я снабжу тебя сигнальными дымовыми шашками. Ты на поле, я за орудиями – вместе мы разнесем эти скалы так, что они целиком обрушатся в море!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте 5 снарядов для гоблинской мортиры из Секретной Лаборатории в Азшаре.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите снаряды бомбардиру капитану Смуксу на Оргриммарскую южную конечную станцию ракетной дороги в Азшаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (14260,'Под маскировкой','Используйте оберег Скользящего Плавника.','Давай, шевелись! У нас еще столько дел!$B$BМне что, надо втолковывать каждому по отдельности, что и как делать?!','Поговорите с Валишж, находящейся на Берегу Скользящего Плавника в Пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Под маскировкой',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте оберег Скользящего Плавника.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Давай, шевелись! У нас еще столько дел!$B$BМне что, надо втолковывать каждому по отдельности, что и как делать?!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Валишж, находящейся на Берегу Скользящего Плавника в Пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (14261,'Ледяной холод','У меня есть идеальное решение для нашей проблемы с драконами. Мой Криохлад 16.$b$bИзначально я изобрел его для замораживания моих рабочих на время транспортировки и между сменами – в этом случае их не надо кормить, да и вообще думать о них. Правда, возникли некоторые... осложнения. Но для драконов это должно подойти!','Воспользуйтесь Криохладом 16, чтобы убить 8 агатовых драконов.','Вернитесь к Фено Гвоздеглоту на северную конечную станцию ракетной дороги.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ледяной холод',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У меня есть идеальное решение для нашей проблемы с драконами. Мой Криохлад 16.$b$bИзначально я изобрел его для замораживания моих рабочих на время транспортировки и между сменами – в этом случае их не надо кормить, да и вообще думать о них. Правда, возникли некоторые... осложнения. Но для драконов это должно подойти!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь Криохладом 16, чтобы убить 8 агатовых драконов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фено Гвоздеглоту на северную конечную станцию ракетной дороги.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (14262,'Выпотрошить рыбку','Борьба с существами, которые могут в любой момент исчезнуть в море и вынырнуть, где им заблагорассудится, действует мне на нервы. Но я не сдамся, пока в Азшаре не останется никого из им подобных.$b$bНаги из клана Бича Злобы забрались наверх по скалам и осаждают заставу с востока. Уничтожь их, $n. Вспори им брюхо, чтобы они поняли, что значит ярость Орды.','Убейте 6 сынов штормов из клана Бича Злобы и 6 зовущих море из клана Бича Злобы.','Вернитесь к Торгу Двудробу на южную конечную станцию ракетной дороги в Азшаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Выпотрошить рыбку',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Борьба с существами, которые могут в любой момент исчезнуть в море и вынырнуть, где им заблагорассудится, действует мне на нервы. Но я не сдамся, пока в Азшаре не останется никого из им подобных.$b$bНаги из клана Бича Злобы забрались наверх по скалам и осаждают заставу с востока. Уничтожь их, $n. Вспори им брюхо, чтобы они поняли, что значит ярость Орды.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 6 сынов штормов из клана Бича Злобы и 6 зовущих море из клана Бича Злобы.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Торгу Двудробу на южную конечную станцию ракетной дороги в Азшаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (14263,'Расход тимьяна','Тимьян живого гнева. Мне нужно еще! И побыстрее с этим, ладно?','Соберите 8 пучков тимьяна живого гнева возле руин Нордрессы.','Прекрасно. Интересно, как совершенно обычные вещи становятся полезными под действием заклинаний такого рода.$B$BЕще столько надо узнать!','Вернитесь к Карле Свистолом в руины Нордрессы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Расход тимьяна',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тимьян живого гнева. Мне нужно еще! И побыстрее с этим, ладно?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 пучков тимьяна живого гнева возле руин Нордрессы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно. Интересно, как совершенно обычные вещи становятся полезными под действием заклинаний такого рода.$B$BЕще столько надо узнать!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Карле Свистолом в руины Нордрессы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (14264,'Морской бой','Здесь появились приспешники Нептулона. Они очень стараются нам помешать и сбивают все наши планы. Очевидно, они догадались, зачем мы здесь.$B$BЧто лишь подтверждает мои подозрения: то, что мы ищем, где-то тут, в этих руинах!$B$BНашим воинам не одолеть элементалей воды! Возьми этот трезубец – он поможет тебе уничтожить никчемных прислужников Хозяина Приливов.$B$BКогда мы найдем то, что ищем, сам Нептулон содрогнется от страха!','Убейте 5 слуг Нептулона. (Для того чтобы с ними сразиться, вы должны быть в обличье наги.)$B$BЕсли вы потеряете трезубец клана Скользящего Плавника, возвращайтесь к Валишж.$B$BЕсли вы потеряете оберег клана Скользящего Плавника, возвращайтесь к Корре в Этель-Ретор.','Ряды врага поредели, и это отрадно.$B$BА ты, я смотрю, можешь стать нам достойным помощником…','Вернитесь к Валишж на Берегу Скользящего Плавника в Пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Морской бой',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Здесь появились приспешники Нептулона. Они очень стараются нам помешать и сбивают все наши планы. Очевидно, они догадались, зачем мы здесь.$B$BЧто лишь подтверждает мои подозрения: то, что мы ищем, где-то тут, в этих руинах!$B$BНашим воинам не одолеть элементалей воды! Возьми этот трезубец – он поможет тебе уничтожить никчемных прислужников Хозяина Приливов.$B$BКогда мы найдем то, что ищем, сам Нептулон содрогнется от страха!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 5 слуг Нептулона. (Для того чтобы с ними сразиться, вы должны быть в обличье наги.)$B$BЕсли вы потеряете трезубец клана Скользящего Плавника, возвращайтесь к Валишж.$B$BЕсли вы потеряете оберег клана Скользящего Плавника, возвращайтесь к Корре в Этель-Ретор.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ряды врага поредели, и это отрадно.$B$BА ты, я смотрю, можешь стать нам достойным помощником…',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Валишж на Берегу Скользящего Плавника в Пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (14265,'Твой наставник','Большинство жителей без проблем добрались до другой части города... но оказалось, что здесь тоже водятся воргены.$B$BМы намереваемся двигаться дальше на юг, как только пересчитаем людей.$B$BКстати, чуть не забыла – тебя искал один человек. Некий Клиз утверждает, что был твоим наставником, и он хочет убедиться, что с тобой все в порядке.','Поговорите с сержантом Клизом в Военном квартале.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Твой наставник',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Большинство жителей без проблем добрались до другой части города... но оказалось, что здесь тоже водятся воргены.$B$BМы намереваемся двигаться дальше на юг, как только пересчитаем людей.$B$BКстати, чуть не забыла – тебя искал один человек. Некий Клиз утверждает, что был твоим наставником, и он хочет убедиться, что с тобой все в порядке.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с сержантом Клизом в Военном квартале.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (14267,'Исследование святилища наг','Наги построили в скалах несколько святилищ. Не знаю, зачем, $n, но, думаю, все это с целью укрепления сил наших противников. Мне нужен кто-то, кто бы пробрался туда и все узнал.$b$bОдно из ближайших святилищ слабо охраняется: перейди первый мост к востоку отсюда и затем направляйся на север к заливу. Увидишь небольшую площадку, там найдешь святилище. Исследуй его и сообщи мне о том, что узнаешь.','Исследуйте святилище наг для Торга Двудроба.','Камень в центре этого святилища испускает слабый свет и рокочет, как бурное море.','Исследуйте святилище наг в Штормовых утесах для Торга Двудроба.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Исследование святилища наг',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наги построили в скалах несколько святилищ. Не знаю, зачем, $n, но, думаю, все это с целью укрепления сил наших противников. Мне нужен кто-то, кто бы пробрался туда и все узнал.$b$bОдно из ближайших святилищ слабо охраняется: перейди первый мост к востоку отсюда и затем направляйся на север к заливу. Увидишь небольшую площадку, там найдешь святилище. Исследуй его и сообщи мне о том, что узнаешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Исследуйте святилище наг для Торга Двудроба.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Камень в центре этого святилища испускает слабый свет и рокочет, как бурное море.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Исследуйте святилище наг в Штормовых утесах для Торга Двудроба.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (14268,'Глубокая тайна','Королева Азшара хочет отыскать вход в царство воды... уж не знаю, зачем.$B$BКак бы там ни было, она убеждена, что древние знали, где находится это место.$B$BМне поручили возглавить поисковую группу и осмотреть все руины в этом районе. Мы будем искать и не успокоимся, пока не найдем то, что ищем!$B$BНеподалеку отсюда, на севере, располагается обширный участок развалин. Возьми этот посох, он поможет тебе.$B$BИ не возвращайся, пока не найдешь то, что нужно найти!','По поручению жрицы Валишж разыщите древнюю гравировку Нептулона.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Глубокая тайна',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Королева Азшара хочет отыскать вход в царство воды... уж не знаю, зачем.$B$BКак бы там ни было, она убеждена, что древние знали, где находится это место.$B$BМне поручили возглавить поисковую группу и осмотреть все руины в этом районе. Мы будем искать и не успокоимся, пока не найдем то, что ищем!$B$BНеподалеку отсюда, на севере, располагается обширный участок развалин. Возьми этот посох, он поможет тебе.$B$BИ не возвращайся, пока не найдешь то, что нужно найти!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По поручению жрицы Валишж разыщите древнюю гравировку Нептулона.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (14269,'Кто-то ищет тебя','Большинство жителей без проблем добрались до другой части города... но оказалось, что здесь тоже водятся воргены.$B$BМы намереваемся двигаться дальше на юг, как только пересчитаем людей.$B$BКстати, чуть не забыла – тебя искала какая-то женщина. Некая Лорен... кажется, она расстроилась, узнав, что ты $gуцелел:уцелела;. По-моему, она упомянула, что должна тебе денег.','Поговорите с Лорен Укрывательницей в Военном квартале.','Ой, привет! А вот и ты!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кто-то ищет тебя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Большинство жителей без проблем добрались до другой части города... но оказалось, что здесь тоже водятся воргены.$B$BМы намереваемся двигаться дальше на юг, как только пересчитаем людей.$B$BКстати, чуть не забыла – тебя искала какая-то женщина. Некая Лорен... кажется, она расстроилась, узнав, что ты $gуцелел:уцелела;. По-моему, она упомянула, что должна тебе денег.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Лорен Укрывательницей в Военном квартале.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ой, привет! А вот и ты!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14270,'Осколок краеугольного камня','Воздух вокруг этого странного камня потрескивает от избытка энергии. Сам камень гладкий и холодный, как лед. Если проносить над ним руку, он периодически пульсирует.$b$bПохоже, что от поверхности этого артефакта был отколот кусок в форме клина. Скорее всего этот "осколок краеугольного камня" – ключ к секретам артефакта. Обыщите земли возле храма и найдите осколок.','Найдите поблизости осколок краеугольного камня.','Осколок встает на место и на поверхности камня внезапно проступают не видимые прежде руны, мерцая голубым и фиолетовым цветами. Поток чар, направленный к вашему телу, такой мощный, что у вас подгибаются колени.','Камень силы наг пульсирует и жужжит.','Соедините осколок краеугольного камня с камнем силы наг в Штормовых утесах в Азшаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Осколок краеугольного камня',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Воздух вокруг этого странного камня потрескивает от избытка энергии. Сам камень гладкий и холодный, как лед. Если проносить над ним руку, он периодически пульсирует.$b$bПохоже, что от поверхности этого артефакта был отколот кусок в форме клина. Скорее всего этот "осколок краеугольного камня" – ключ к секретам артефакта. Обыщите земли возле храма и найдите осколок.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите поблизости осколок краеугольного камня.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Осколок встает на место и на поверхности камня внезапно проступают не видимые прежде руны, мерцая голубым и фиолетовым цветами. Поток чар, направленный к вашему телу, такой мощный, что у вас подгибаются колени.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Камень силы наг пульсирует и жужжит.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Соедините осколок краеугольного камня с камнем силы наг в Штормовых утесах в Азшаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (14271,'Доложиться Двудробу','Вокруг вас, обдавая холодком, пульсирует магическое поле. За этой волшебной стеной вы чувствуете себя в безопасности.$b$bТорг Двудроб хочет узнать, что вы тут обнаружили!','Вернитесь к Торгу Двудробу на оргриммарскую южную конечную станцию ракетной дороги в Азшаре.','Вернитесь к Торгу Двудробу на южную конечную станцию ракетной дороги в Азшаре и сообщите, что вы обнаружили.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Доложиться Двудробу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вокруг вас, обдавая холодком, пульсирует магическое поле. За этой волшебной стеной вы чувствуете себя в безопасности.$b$bТорг Двудроб хочет узнать, что вы тут обнаружили!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь к Торгу Двудробу на оргриммарскую южную конечную станцию ракетной дороги в Азшаре.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Торгу Двудробу на южную конечную станцию ракетной дороги в Азшаре и сообщите, что вы обнаружили.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (14273,'Странные знакомства','Большинство жителей без проблем добрались до другой части города... но оказалось, что здесь тоже водятся воргены.$B$BМы намереваемся двигаться дальше на юг, как только пересчитаем людей.$B$BКстати, чуть не забыла – тебя искал какой-то странный парень по имени Вит... жуткий тип, у меня от него мурашки по коже.$B$BОн все говорил о каком-то запретном знании.','Поговорите с Витом Дарквокером в Военном квартале.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Странные знакомства',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Большинство жителей без проблем добрались до другой части города... но оказалось, что здесь тоже водятся воргены.$B$BМы намереваемся двигаться дальше на юг, как только пересчитаем людей.$B$BКстати, чуть не забыла – тебя искал какой-то странный парень по имени Вит... жуткий тип, у меня от него мурашки по коже.$B$BОн все говорил о каком-то запретном знании.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Витом Дарквокером в Военном квартале.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (14275,'Кто-то следит за тобой','Большинство жителей без проблем добрались до другой части города... но оказалось, что здесь тоже водятся воргены.$B$BМы намереваемся двигаться дальше на юг, как только пересчитаем людей.$B$BКстати, чуть не забыла – тебя искал какой-то человек по имени Блейк. Сказал, что собирается искать спасения в лесах.','Поговорите с ловчим Блейком в Военном квартале.','$n! Я так и знал, что найду тебя где-то здесь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кто-то следит за тобой',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Большинство жителей без проблем добрались до другой части города... но оказалось, что здесь тоже водятся воргены.$B$BМы намереваемся двигаться дальше на юг, как только пересчитаем людей.$B$BКстати, чуть не забыла – тебя искал какой-то человек по имени Блейк. Сказал, что собирается искать спасения в лесах.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с ловчим Блейком в Военном квартале.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','$n! Я так и знал, что найду тебя где-то здесь.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (14276,'Верный выстрел','Очень хорошо, Корольвсех. Скоро воргены пожалеют о том, что ступили на эти земли.','Вернитесь к ловчему Блейку в Военный квартал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Верный выстрел',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Очень хорошо, Корольвсех. Скоро воргены пожалеют о том, что ступили на эти земли.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ловчему Блейку в Военный квартал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (14277,'Зов магии','Большинство жителей без проблем добрались до другой части города... но оказалось, что здесь тоже водятся воргены.$B$BМы намереваемся двигаться дальше на юг, как только пересчитаем людей.$B$BКстати, чуть не забыла – тебя искала какая-то волшебница по имени Мириам. Странная она, сказала что-то про то, что ты $gдолжен быть готов:должна быть готова;...','Поговорите с Мириам Пробудительницей Чар в Военном квартале.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зов магии',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Большинство жителей без проблем добрались до другой части города... но оказалось, что здесь тоже водятся воргены.$B$BМы намереваемся двигаться дальше на юг, как только пересчитаем людей.$B$BКстати, чуть не забыла – тебя искала какая-то волшебница по имени Мириам. Странная она, сказала что-то про то, что ты $gдолжен быть готов:должна быть готова;...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Мириам Пробудительницей Чар в Военном квартале.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (14278,'В поисках сестры','Большинство жителей без проблем добрались до другой части города... но оказалось, что здесь тоже водятся воргены.$B$BМы намереваемся двигаться дальше на юг, как только пересчитаем людей.$B$BКстати, чуть не забыла – тебя искала сестра Альмира, одна из священнослужительниц. Она сказала, что тебе угрожает опасность, и только Свет может защитить тебя от неминуемой смерти.$B$BПо-моему, тебе надо с ней поговорить – она была очень обеспокоена.','Поговорите с сестрой Альмирой в Военном квартале.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В поисках сестры',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Большинство жителей без проблем добрались до другой части города... но оказалось, что здесь тоже водятся воргены.$B$BМы намереваемся двигаться дальше на юг, как только пересчитаем людей.$B$BКстати, чуть не забыла – тебя искала сестра Альмира, одна из священнослужительниц. Она сказала, что тебе угрожает опасность, и только Свет может защитить тебя от неминуемой смерти.$B$BПо-моему, тебе надо с ней поговорить – она была очень обеспокоена.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с сестрой Альмирой в Военном квартале.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (14280,'Ветра шепчут твое имя','Большинство жителей без проблем добрались до другой части города... но оказалось, что здесь тоже водятся воргены.$B$BМы намереваемся двигаться дальше на юг, как только пересчитаем людей.$B$BКстати, чуть не забыла – тебя искала женщина-друид по имени Целестина. Сказала, что ветра прошептали ей твое имя.$B$BЧепуха какая-то, честное слово.','Поговорите с Целестиной Урожайной в Военном квартале.','Благословение богам! Ты жив и в добром здравии!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ветра шепчут твое имя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Большинство жителей без проблем добрались до другой части города... но оказалось, что здесь тоже водятся воргены.$B$BМы намереваемся двигаться дальше на юг, как только пересчитаем людей.$B$BКстати, чуть не забыла – тебя искала женщина-друид по имени Целестина. Сказала, что ветра прошептали ей твое имя.$B$BЧепуха какая-то, честное слово.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Целестиной Урожайной в Военном квартале.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Благословение богам! Ты жив и в добром здравии!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (14281,'Кольцо льда','Вернитесь к Мириам Пробудительнице Чар в Военный квартал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кольцо льда',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мириам Пробудительнице Чар в Военный квартал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (14282,'Раскрытая тайна','Ты $gстарался:старалась; не зря, и не зря $gрисковал:рисковала; жизнью.$B$BТы $gузнал:узнала;, зачем наги явились к побережью у Пустошей, и $gзаполучил:заполучила; предмет их упорных поисков.$B$BЧто касается найденных тобой надписей, тут задача ясна...','Отнесите древнюю гравировку Нептулона кенарийской исследовательнице Корре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Раскрытая тайна',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gстарался:старалась; не зря, и не зря $gрисковал:рисковала; жизнью.$B$BТы $gузнал:узнала;, зачем наги явились к побережью у Пустошей, и $gзаполучил:заполучила; предмет их упорных поисков.$B$BЧто касается найденных тобой надписей, тут задача ясна...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите древнюю гравировку Нептулона кенарийской исследовательнице Корре.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (14284,'Месть загробника','Я Гидронис, слуга Нептулона, Хозяина Приливов, хозяина всех вод.$B$BАзшара и ее злобные наги воспротивились власти моего господина и объявили ему войну. Это лишь первая битва, а будут еще... я уверен. И борьба будет долгой и трудной.$B$BЯ сражался, как мог, |3-6($r), и выбился из сил.$B$BМои действия привлекли внимание их жрицы.$B$BВ одиночку мне с ней не справиться. Но вместе мы можем попробовать ее одолеть.','Сядьте верхом на лорда Гидрониса и сразитесь со жрицей Валишж.','Жрицы больше нет…') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Месть загробника',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я Гидронис, слуга Нептулона, Хозяина Приливов, хозяина всех вод.$B$BАзшара и ее злобные наги воспротивились власти моего господина и объявили ему войну. Это лишь первая битва, а будут еще... я уверен. И борьба будет долгой и трудной.$B$BЯ сражался, как мог, |3-6($r), и выбился из сил.$B$BМои действия привлекли внимание их жрицы.$B$BВ одиночку мне с ней не справиться. Но вместе мы можем попробовать ее одолеть.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сядьте верхом на лорда Гидрониса и сразитесь со жрицей Валишж.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Жрицы больше нет…',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (14285,'Спасение в единстве','Боюсь, это все, чему я могу научить тебя сейчас, когда воргены буквально дышат нам в затылок.$B$BТеперь нам надо присоединиться к другим беженцам и направиться на юг. Нам сообщили, что там нас ждет король Седогрив.$B$BЕсли мы будем держаться вместе, то сможем выжить... особенно если ты сможешь прицепиться к кому-нибудь посильнее.','Поговорите с королем Генном Седогривом в Военном квартале.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спасение в единстве',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Боюсь, это все, чему я могу научить тебя сейчас, когда воргены буквально дышат нам в затылок.$B$BТеперь нам надо присоединиться к другим беженцам и направиться на юг. Нам сообщили, что там нас ждет король Седогрив.$B$BЕсли мы будем держаться вместе, то сможем выжить... особенно если ты сможешь прицепиться к кому-нибудь посильнее.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с королем Генном Седогривом в Военном квартале.',`objectives_loc8`);
