INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (14293,'Спасти Креннана Аранаса','Спасите Креннана Аранаса.','Поговорите с лордом Годфри в Военном квартале Гилнеаса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спасти Креннана Аранаса',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Спасите Креннана Аранаса.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с лордом Годфри в Военном квартале Гилнеаса.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (14294,'Время перегруппироваться','Мы сделали все, что могли. Скажи королю Седогриву, что нам удалось выиграть для него немного времени.$B$BУ меня такое чувство, что воргены недолго будут зализывать раны и скоро перейдут в наступление.$B$BВ таком случае нам придется отступить на запад к площади Седогрива. Это последнее место, которое мы можем удерживать, не чувствуя себя запертыми в ловушке.','Поговорите с королем Генном Седогривом на площади Седогрива в Гилнеасе.','У нас осталось не так уж много вариантов, $n. Придется действовать решительно.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Время перегруппироваться',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы сделали все, что могли. Скажи королю Седогриву, что нам удалось выиграть для него немного времени.$B$BУ меня такое чувство, что воргены недолго будут зализывать раны и скоро перейдут в наступление.$B$BВ таком случае нам придется отступить на запад к площади Седогрива. Это последнее место, которое мы можем удерживать, не чувствуя себя запертыми в ловушке.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с королем Генном Седогривом на площади Седогрива в Гилнеасе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','У нас осталось не так уж много вариантов, $n. Придется действовать решительно.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (14295,'Сестры моря','Нападением на заставу руководят наги-ведьмы. Они отразили прямую атаку моих лучших пехотинцев, но там, где потерпели поражение другие, нам сможешь помочь ты.$b$bНайди и убей леди Силистру и леди Вестру на восточном краю скал, возле обломков древнего колосса ночных эльфов. Сначала тебе понадобится уничтожить камни власти, которые дают им силу. Не разочаруй меня, |3-6($c)!','Убейте леди Силистру и леди Вестру, уничтожив их камни силы.','Вот так мы управлялись со змеями в Дуротаре – давили их своими сапогами! Орда гордится тобой, Синделл. Как только придет подкрепление, мы разделаемся с остальными тварями и раз и навсегда объявим этот полуостров своим.','Вернитесь к Торгу Двудробу на южную конечную станцию ракетной дороги в Азшаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сестры моря',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нападением на заставу руководят наги-ведьмы. Они отразили прямую атаку моих лучших пехотинцев, но там, где потерпели поражение другие, нам сможешь помочь ты.$b$bНайди и убей леди Силистру и леди Вестру на восточном краю скал, возле обломков древнего колосса ночных эльфов. Сначала тебе понадобится уничтожить камни власти, которые дают им силу. Не разочаруй меня, |3-6($c)!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте леди Силистру и леди Вестру, уничтожив их камни силы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот так мы управлялись со змеями в Дуротаре – давили их своими сапогами! Орда гордится тобой, Синделл. Как только придет подкрепление, мы разделаемся с остальными тварями и раз и навсегда объявим этот полуостров своим.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Торгу Двудробу на южную конечную станцию ракетной дороги в Азшаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (14296,'Смотри, куда идешь','Это одновременно и просто, и нет. Вдоль всего пути наверх тянутся силовые провода. Точно такие, как этот справа! Я знаю, что говорю.$b$bТак вот. Воспользуйся моими приспособлениями для прыжков, чтобы подняться к замку, и прикасайся ко всем проводам, какие увидишь по пути. Когда ты придешь ко мне наверх, ты $gдолжен сам:должна сама; излучать энергию, иначе никак.$b$bИ не забывай все время двигаться, а то улетишь!','Получите 6 энергетических зарядов, прикасаясь к силовым проводам при подъеме к Волшебному замку.','Именно в этот момент большинство моих учеников спрашивает, есть ли какая-то внятная причина хранить энергию для портала в этих проводах, если собирать ее надо таким извращенным способом.$B$BКонечно же, причина есть! Я хочу увидеть, что вы предпримете… какую выберете стратегию, какие совершите ошибки, где будете сомневаться, в чем преуспеете. В этом истинный смысл всех испытаний.$B$BТак что, продолжим. Больше испытаний! Звучит волнующе, правда?!','Поговорите с проекцией верховного мага Ксилема на вершине в Волшебном замке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Смотри, куда идешь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это одновременно и просто, и нет. Вдоль всего пути наверх тянутся силовые провода. Точно такие, как этот справа! Я знаю, что говорю.$b$bТак вот. Воспользуйся моими приспособлениями для прыжков, чтобы подняться к замку, и прикасайся ко всем проводам, какие увидишь по пути. Когда ты придешь ко мне наверх, ты $gдолжен сам:должна сама; излучать энергию, иначе никак.$b$bИ не забывай все время двигаться, а то улетишь!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Получите 6 энергетических зарядов, прикасаясь к силовым проводам при подъеме к Волшебному замку.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Именно в этот момент большинство моих учеников спрашивает, есть ли какая-то внятная причина хранить энергию для портала в этих проводах, если собирать ее надо таким извращенным способом.$B$BКонечно же, причина есть! Я хочу увидеть, что вы предпримете… какую выберете стратегию, какие совершите ошибки, где будете сомневаться, в чем преуспеете. В этом истинный смысл всех испытаний.$B$BТак что, продолжим. Больше испытаний! Звучит волнующе, правда?!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с проекцией верховного мага Ксилема на вершине в Волшебном замке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (14297,'За освобождение','Еще когда мы начали строить эту башню, я уже знал, что от них будут одни проблемы. Присваивают наши взятки. Крадут наших рабочих.$b$bВ Азшаре многие строятся и рабочая сила недешева. Мне нужны мои люди обратно!','Воспользуйтесь железнокованными ключами сектантов и драконов, чтобы освободить 4 гоблинов-рабочих на Черной гряде.','Спасибо, приятель. Вот твое вознаграждение.$B$BА теперь извини, мне надо заставить этих бездельников работать.','Вернитесь к Зелликсу Зажигателю на северную конечную станцию ракетной дороги.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','За освобождение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Еще когда мы начали строить эту башню, я уже знал, что от них будут одни проблемы. Присваивают наши взятки. Крадут наших рабочих.$b$bВ Азшаре многие строятся и рабочая сила недешева. Мне нужны мои люди обратно!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь железнокованными ключами сектантов и драконов, чтобы освободить 4 гоблинов-рабочих на Черной гряде.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо, приятель. Вот твое вознаграждение.$B$BА теперь извини, мне надо заставить этих бездельников работать.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Зелликсу Зажигателю на северную конечную станцию ракетной дороги.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (14298,'Убить сектантов/драконов') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Убить сектантов/драконов',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (14299,'Пристанище Ксилема','Чудесно с твоей стороны! Приятно видеть. Есть, чему поучиться.$b$bТеперь ступай, возвращайся в мою башню. Джоанна тебе поможет. Я открою для тебя портал.','Воспользуйтесь порталом в башню верховного мага Ксилема и найдите в башне Джоанну.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пристанище Ксилема',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чудесно с твоей стороны! Приятно видеть. Есть, чему поучиться.$b$bТеперь ступай, возвращайся в мою башню. Джоанна тебе поможет. Я открою для тебя портал.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь порталом в башню верховного мага Ксилема и найдите в башне Джоанну.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (14301,'Возвращение с докладом','У нас получилось! Вместе мы одолели опасного противника.$B$BНептулон непременно узнает о твоей доблести, |3-6($c). Благодарю тебя от его имени... $B$BА теперь тебе надо идти. Скоро здесь будет небезопасно. Наги явятся мстить за свою жрицу.','Возвращайтесь в Этель-Ретор к кенарийской исследовательнице Корре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение с докладом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У нас получилось! Вместе мы одолели опасного противника.$B$BНептулон непременно узнает о твоей доблести, |3-6($c). Благодарю тебя от его имени... $B$BА теперь тебе надо идти. Скоро здесь будет небезопасно. Наги явятся мстить за свою жрицу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возвращайтесь в Этель-Ретор к кенарийской исследовательнице Корре.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (14302,'Рапорт начальству') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рапорт начальству',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (14303,'Возвращение к Аггре','$n, вернись в главный лагерь Орды и передай Аггре, что мы живы.$B$BСкажи ей, я иду к Лесному наблюдательному пункту, а встретимся мы все в северо-западной части острова. Надеюсь увидеть тебя там.$B$BМы выследим воинов Альянса и перебьем их всех до одного!','Сообщите Аггре о том, что произошло. Она находится на Затерянных островах, в главном лагере Орды.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение к Аггре',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, вернись в главный лагерь Орды и передай Аггре, что мы живы.$B$BСкажи ей, я иду к Лесному наблюдательному пункту, а встретимся мы все в северо-западной части острова. Надеюсь увидеть тебя там.$B$BМы выследим воинов Альянса и перебьем их всех до одного!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сообщите Аггре о том, что произошло. Она находится на Затерянных островах, в главном лагере Орды.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14304,'Кровь на анализ','Принесите 10 напившихся крови пиявок.','У тебя получилось взять образцы крови?','Вернитесь к Трессе Янтарный Очаг, находящейся на Просеке Карнума в Пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кровь на анализ',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 напившихся крови пиявок.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У тебя получилось взять образцы крови?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Трессе Янтарный Очаг, находящейся на Просеке Карнума в Пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (14305,'Время пожинать','В Круге Кенария все хорошо понимают, что этот чудесный оазис может высохнуть и исчезнуть буквально за несколько дней.$B$BМы должны соблюдать осторожность: не вмешиваться в происходящие здесь процессы, но поддерживать их и по возможности оберегать.$B$BПосле катаклизма в здешних местах появились новые виды растений.$B$BСобери мне образцы. Я хочу их изучить и понять, что они из себя представляют.','Соберите 10 образцов дикого алоэ.','Вернитесь к ботанику Ферре, находящейся на Просеке Карнума в Пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Время пожинать',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В Круге Кенария все хорошо понимают, что этот чудесный оазис может высохнуть и исчезнуть буквально за несколько дней.$B$BМы должны соблюдать осторожность: не вмешиваться в происходящие здесь процессы, но поддерживать их и по возможности оберегать.$B$BПосле катаклизма в здешних местах появились новые виды растений.$B$BСобери мне образцы. Я хочу их изучить и понять, что они из себя представляют.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 образцов дикого алоэ.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ботанику Ферре, находящейся на Просеке Карнума в Пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (14306,'Прополка','Хотелось бы верить в лучшее, но реакция некоторых представителей флоры и фауны проходит не так, как мы планировали. В общем, этого и следовало ожидать при столь резком изменении экологической ситуации.$B$BВыкорчеванные плеточники – яркий пример упомянутой негативной реакции. Этот сорняк грозит захватить все поля на востоке и юге. Его надо уничтожить, пока он не причинил непоправимого вреда.$B$BВ связи с чем у меня к тебе просьба: если где встретишь этого паразита, вырывай его с корнем!','Уничтожьте 7 выкорчеванных плеточников.','Вернитесь к ботанику Ферре, находящейся на Просеке Карнума в Пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прополка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хотелось бы верить в лучшее, но реакция некоторых представителей флоры и фауны проходит не так, как мы планировали. В общем, этого и следовало ожидать при столь резком изменении экологической ситуации.$B$BВыкорчеванные плеточники – яркий пример упомянутой негативной реакции. Этот сорняк грозит захватить все поля на востоке и юге. Его надо уничтожить, пока он не причинил непоправимого вреда.$B$BВ связи с чем у меня к тебе просьба: если где встретишь этого паразита, вырывай его с корнем!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 7 выкорчеванных плеточников.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ботанику Ферре, находящейся на Просеке Карнума в Пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (14307,'Враждебный ветер','Ветер перемен дует в полную силу, |3-6($r). В том нет сомнений.$B$BЗдесь у нас столько дел, важных и спешных! Но самое главное на сегодняшний день – расширение нашего оазиса.$B$BМы даже не смели надеяться на столь бурный рост, и нам непонятны его причины. Однако сейчас мы столкнулись с одной проблемой.$B$BНа западе, на границе оазиса и песков, появились какие-то странные вихри, не дающие растениям проникать дальше в пустыню.$B$BТебе надо пойти туда и устранить это враждебное препятствие жизни!','Уничтожьте 5 вихревых штормоходов.','Вернитесь к Карнуму Ткачу Болот, находящемуся на Просеке Карнума в Пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Враждебный ветер',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ветер перемен дует в полную силу, |3-6($r). В том нет сомнений.$B$BЗдесь у нас столько дел, важных и спешных! Но самое главное на сегодняшний день – расширение нашего оазиса.$B$BМы даже не смели надеяться на столь бурный рост, и нам непонятны его причины. Однако сейчас мы столкнулись с одной проблемой.$B$BНа западе, на границе оазиса и песков, появились какие-то странные вихри, не дающие растениям проникать дальше в пустыню.$B$BТебе надо пойти туда и устранить это враждебное препятствие жизни!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 5 вихревых штормоходов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Карнуму Ткачу Болот, находящемуся на Просеке Карнума в Пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (14308,'Когда наука атакует','Ты $gвидел:видела; взрывы по пути сюда? Секретная лаборатория охвачена огнем! Опять! Если мы не потушим этот огонь, будет достигнута критическая температура, и все расплавится.$b$bСмотри, я даю тебе канистру с экспериментальным многоцветным жидкогелем под давлением: это самый неустойчивый огненный ингибитор, какой только известен науке! (Держи канистру подальше от открытого огня.) Потуши огонь, залей водой моих студентов-исследователей и свяжись со мной при помощи переговорного устройства на центральном пульте управления.','Воспользуйтесь огнеустранителем Х-21, чтобы потушить 8 очагов пожара и спасти 6 студентов-исследователей из пекла в секретной лаборатории.$B$BЕсли вы потеряете ваш огнеустранитель, возьмите еще один у ассистентки Грили на южной конечной станции ракетной дороги.','Свяжитесь с ассистенткой Грили при помощи переговорного устройства в западной части секретной лаборатории в Азшаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Когда наука атакует',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gвидел:видела; взрывы по пути сюда? Секретная лаборатория охвачена огнем! Опять! Если мы не потушим этот огонь, будет достигнута критическая температура, и все расплавится.$b$bСмотри, я даю тебе канистру с экспериментальным многоцветным жидкогелем под давлением: это самый неустойчивый огненный ингибитор, какой только известен науке! (Держи канистру подальше от открытого огня.) Потуши огонь, залей водой моих студентов-исследователей и свяжись со мной при помощи переговорного устройства на центральном пульте управления.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь огнеустранителем Х-21, чтобы потушить 8 очагов пожара и спасти 6 студентов-исследователей из пекла в секретной лаборатории.$B$BЕсли вы потеряете ваш огнеустранитель, возьмите еще один у ассистентки Грили на южной конечной станции ракетной дороги.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Свяжитесь с ассистенткой Грили при помощи переговорного устройства в западной части секретной лаборатории в Азшаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (14309,'Успокоительное для кодо','Напоите 5 разъяренных кодо успокаивающим настоем.','Отлично! Карнум будет доволен!$B$BПрими это в знак благодарности. От меня лично.','Вернитесь к Трессе Янтарный Очаг, находящейся на Просеке Карнума в Пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Успокоительное для кодо',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Напоите 5 разъяренных кодо успокаивающим настоем.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! Карнум будет доволен!$B$BПрими это в знак благодарности. От меня лично.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Трессе Янтарный Очаг, находящейся на Просеке Карнума в Пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (14310,'Ошибка сегментации: дамп памяти сохранен','Поскольку мы выключили центральный реактор, я хочу, чтобы ты $gдоставил:доставила; мне его ядро. Это 100% очищенный азшаритовый кристалл, который одновременно и очень мощный, и очень опасный. И красивый. Драгоценный азшарит, формирователь миров будущего!$b$bОгромный рычаг слева от тебя освободит ядро и отправит его мне по системе рельсов. Температура ядра будет очень высока, поэтому по пути сюда тебе потребуется периодически охлаждать его при помощи огнеустранителя... и не позволяй температуре достигать критических значений!','Активируйте панель управления реактором и сопроводите азшаритовое ядро на южную конечную станцию ракетной дороги. Используйте огнеустранитель Х-21, когда ядро будет перегреваться.','Поговорите с ассистенткой Грили на южной конечной станции ракетной дороги в Азшаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ошибка сегментации: дамп памяти сохранен',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Поскольку мы выключили центральный реактор, я хочу, чтобы ты $gдоставил:доставила; мне его ядро. Это 100% очищенный азшаритовый кристалл, который одновременно и очень мощный, и очень опасный. И красивый. Драгоценный азшарит, формирователь миров будущего!$b$bОгромный рычаг слева от тебя освободит ядро и отправит его мне по системе рельсов. Температура ядра будет очень высока, поэтому по пути сюда тебе потребуется периодически охлаждать его при помощи огнеустранителя... и не позволяй температуре достигать критических значений!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Активируйте панель управления реактором и сопроводите азшаритовое ядро на южную конечную станцию ракетной дороги. Используйте огнеустранитель Х-21, когда ядро будет перегреваться.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с ассистенткой Грили на южной конечной станции ракетной дороги в Азшаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (14311,'Чудо своими руками','Посадите семена Кенария в 5 местах на плодородной земле в Кенарийских Зарослях.','Возрождение! Это так окрыляет, правда?','Вернитесь к ботанику Ферре, находящейся на Просеке Карнума в Пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чудо своими руками',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Посадите семена Кенария в 5 местах на плодородной земле в Кенарийских Зарослях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Возрождение! Это так окрыляет, правда?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ботанику Ферре, находящейся на Просеке Карнума в Пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (14312,'Позвольте представить','Гаррен Темный Ветер на Просеке Карнума хочет, чтобы вы поговорили с ханом Ле\'прахом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Позвольте представить',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Гаррен Темный Ветер на Просеке Карнума хочет, чтобы вы поговорили с ханом Ле\'прахом.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (14313,'Снова среди людей','Так снадобье Креннана тебя не прикончило? Надо же, значит, твоя человеческая часть души победила.$B$BПожалуй, я не стану тебя убивать – во всяком случае, не сейчас.$B$BИди, сообщи хорошие новости Креннану Аранасу. Он сейчас в том доме, где мы держим таких, как ты.$B$BНо помни, $n: я за тобой слежу. Только попробуй выкинуть какой-нибудь фокус – сразу получишь пулю промеж глаз.','Поговорите с Креннаном Аранасом в Темной Гавани.','Сработало! Хвала Свету, сработало!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Снова среди людей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Так снадобье Креннана тебя не прикончило? Надо же, значит, твоя человеческая часть души победила.$B$BПожалуй, я не стану тебя убивать – во всяком случае, не сейчас.$B$BИди, сообщи хорошие новости Креннану Аранасу. Он сейчас в том доме, где мы держим таких, как ты.$B$BНо помни, $n: я за тобой слежу. Только попробуй выкинуть какой-нибудь фокус – сразу получишь пулю промеж глаз.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Креннаном Аранасом в Темной Гавани.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сработало! Хвала Свету, сработало!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (14314,'Побег из плена','Все началось со сна, который предупреждал меня о надвигающейся опасности. Я видел легионы демонов, заполоняющих наши земли и нападающих на наших собратьев.$B$BСон стал явью. Пылающий Клинок и их хозяева-демоны согнали племя Маграм с их земель на юге. В свою очередь, Маграм победили моих бойцов и заняли наши дома.$B$BБой был жестоким. В живых осталась лишь горстка Колкар. Я прошу тебя, отправляйся в земли на востоке, что раньше были моими, и освободи моих соплеменников.','Уничтожьте стражей племени Маграм в деревне Маграм.','Вернитесь к хану Ле\'праху, находящемуся на Просеке Карнума в Пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Побег из плена',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Все началось со сна, который предупреждал меня о надвигающейся опасности. Я видел легионы демонов, заполоняющих наши земли и нападающих на наших собратьев.$B$BСон стал явью. Пылающий Клинок и их хозяева-демоны согнали племя Маграм с их земель на юге. В свою очередь, Маграм победили моих бойцов и заняли наши дома.$B$BБой был жестоким. В живых осталась лишь горстка Колкар. Я прошу тебя, отправляйся в земли на востоке, что раньше были моими, и освободи моих соплеменников.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте стражей племени Маграм в деревне Маграм.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к хану Ле\'праху, находящемуся на Просеке Карнума в Пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (14315,'Лиам в замешательстве','Убирайся! Это просто причуды моего воображения... Ты не существуешь, ты $gумер:умерла;!$B$BЯ видел, как воргены набросились на тебя... в Гилнеасе...$B$BЛучше бы они схватили меня... это я должен был погибнуть вместо тебя...$B$BО боги... сначала земля шатается как пьяная... теперь еще и галлюцинации... последняя рюмка явно была лишней...$B$B<Похоже, принц полностью потерял связь с реальностью. Наверное, вам стоит поискать кого-нибудь другого, с кем можно было бы поговорить.>','Поговорите с Гвен Армстед в Темной Гавани.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лиам в замешательстве',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Убирайся! Это просто причуды моего воображения... Ты не существуешь, ты $gумер:умерла;!$B$BЯ видел, как воргены набросились на тебя... в Гилнеасе...$B$BЛучше бы они схватили меня... это я должен был погибнуть вместо тебя...$B$BО боги... сначала земля шатается как пьяная... теперь еще и галлюцинации... последняя рюмка явно была лишней...$B$B<Похоже, принц полностью потерял связь с реальностью. Наверное, вам стоит поискать кого-нибудь другого, с кем можно было бы поговорить.>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Гвен Армстед в Темной Гавани.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (14316,'Имущество кентавров','С тех пор как демоны заняли их земли, Маграм разорвали соглашения со всеми другими племенами.$B$BОни стали недоверчивыми, агрессивными и крадут у других вместо того, чтобы самим себя обеспечивать.$B$BМногие наши припасы исчезли, и мы подозреваем, что в этом виноваты Маграм.$B$BПожалуйста, $n, пойди в их владения на востоке и разыщи украденное у нас.','Отыщите 7 ящиков с припасами Кенария в землях Маграм.','Вернитесь к Гаррену Темному Ветру, находящемуся на Просеке Карнума в Пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Имущество кентавров',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','С тех пор как демоны заняли их земли, Маграм разорвали соглашения со всеми другими племенами.$B$BОни стали недоверчивыми, агрессивными и крадут у других вместо того, чтобы самим себя обеспечивать.$B$BМногие наши припасы исчезли, и мы подозреваем, что в этом виноваты Маграм.$B$BПожалуйста, $n, пойди в их владения на востоке и разыщи украденное у нас.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщите 7 ящиков с припасами Кенария в землях Маграм.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гаррену Темному Ветру, находящемуся на Просеке Карнума в Пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (14317,'Подземные толчки','$n! Мы уж не надеялись вновь увидеть тебя!$B$BПослушай, нам очень нужна твоя помощь. Нас накрыло волной мощного землетрясения, и подземные толчки все еще не прекратились. А от принца Лиама толку мало...$B$BМы должны убедиться, что все еще способны обороняться. Теперь только Врата Королевы отделяют нас от обезумевшей толпой разъяренных воргенов Черной дубравы.$B$BСледуй по этой дороге на восток, за пределы города, и сообщи мне, устояли ли врата.','Гвен Армстед просит вас осмотреть Врата Королевы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подземные толчки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n! Мы уж не надеялись вновь увидеть тебя!$B$BПослушай, нам очень нужна твоя помощь. Нас накрыло волной мощного землетрясения, и подземные толчки все еще не прекратились. А от принца Лиама толку мало...$B$BМы должны убедиться, что все еще способны обороняться. Теперь только Врата Королевы отделяют нас от обезумевшей толпой разъяренных воргенов Черной дубравы.$B$BСледуй по этой дороге на восток, за пределы города, и сообщи мне, устояли ли врата.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Гвен Армстед просит вас осмотреть Врата Королевы.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (14318,'Сложные переговоры','Есть только один способ завоевать доверие и благосклонность племени Маграм.$B$BЗаставить их уважать нашу силу!$B$BОни понесли большие потери в войне против моего клана. Сейчас они владеют незнакомой им землей, где им нелегко прокормиться.$B$BПришло время нанести удар.$B$BПоговори со мной, когда будешь $gготов:готова;, затем скачи туда и вонзи мое копье в камень Отцов. Если мы сможем убить достаточное количество Маграм, их вождь подчинится нашей воле.','Хан Ле\'прах хочет, чтобы вы вонзили Копье хана Колкар в камень Отцов и защищали его от клана Маграм, пока не появится вождь Камма.$B$BПоговорите с ханом Ле\'прахом, когда будете готовы отправиться на поле боя.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сложные переговоры',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Есть только один способ завоевать доверие и благосклонность племени Маграм.$B$BЗаставить их уважать нашу силу!$B$BОни понесли большие потери в войне против моего клана. Сейчас они владеют незнакомой им землей, где им нелегко прокормиться.$B$BПришло время нанести удар.$B$BПоговори со мной, когда будешь $gготов:готова;, затем скачи туда и вонзи мое копье в камень Отцов. Если мы сможем убить достаточное количество Маграм, их вождь подчинится нашей воле.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Хан Ле\'прах хочет, чтобы вы вонзили Копье хана Колкар в камень Отцов и защищали его от клана Маграм, пока не появится вождь Камма.$B$BПоговорите с ханом Ле\'прахом, когда будете готовы отправиться на поле боя.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (14319,'Долгий путь к исцелению','Слушай, $n, я не собираюсь ходить вокруг да около.$B$BЕсть вероятность, что снадобье, изготовленное Креннаном, действует не столь успешно, как кажется. Или, возможно, его потребуется немного больше.$B$BВ любом случае, он знает об этом лучше, чем я. Иди навести его.','Поговорите с Креннаном Аранасом в Темной Гавани.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Долгий путь к исцелению',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слушай, $n, я не собираюсь ходить вокруг да около.$B$BЕсть вероятность, что снадобье, изготовленное Креннаном, действует не столь успешно, как кажется. Или, возможно, его потребуется немного больше.$B$BВ любом случае, он знает об этом лучше, чем я. Иди навести его.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Креннаном Аранасом в Темной Гавани.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (14320,'В поисках ингредиентов','Ах, да. Насколько нам известно, последствия Проклятия невозможно снять полностью.$B$BОднако с помощью лечения ты сможешь контролировать свой разум... и держать зверя на привязи.$B$BТы не представляешь, как мы рады видеть, что лекарство тебе помогло. Обычно мне удавалось вылечить только недавно заразившихся.$B$BТеперь мы должны продолжить курс лечения – если, конечно, ты хочешь обратить эффекты Проклятия.$B$BДля новой порции лекарства мне понадобится эссенция мандрагоры – к счастью, на юго-западе от города, под навесом еще остались ящики с этим снадобьем.','Найдите ящик с эссенцией мандрагоры.','Похоже, что ящик сильно пострадал, и все находящиеся в нем склянки разбились.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В поисках ингредиентов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ах, да. Насколько нам известно, последствия Проклятия невозможно снять полностью.$B$BОднако с помощью лечения ты сможешь контролировать свой разум... и держать зверя на привязи.$B$BТы не представляешь, как мы рады видеть, что лекарство тебе помогло. Обычно мне удавалось вылечить только недавно заразившихся.$B$BТеперь мы должны продолжить курс лечения – если, конечно, ты хочешь обратить эффекты Проклятия.$B$BДля новой порции лекарства мне понадобится эссенция мандрагоры – к счастью, на юго-западе от города, под навесом еще остались ящики с этим снадобьем.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите ящик с эссенцией мандрагоры.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Похоже, что ящик сильно пострадал, и все находящиеся в нем склянки разбились.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (14321,'Вторжение','Поговорите с Гвен Армстед в Темной Гавани.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вторжение',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Гвен Армстед в Темной Гавани.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (14322,'Плохая наука! Плохая!','Я пытался приручить местных гиппогрифов при помощи серии ослабляющих электрических ударов, а они вдруг непонятно с чего пришли в ярость! И теперь мои подопытные крушат все вокруг! $C, устрани результаты моих неудачных экспериментов, пока они не устранили меня.','Убейте 8 заряженных электричеством гиппогрифов.','То есть, мир снова безопасен для занятий наукой? Прекрасно! В следующий раз попробую раскаленные иглы или что-то вроде этого.','Вернитесь к Твистексу Языкасту в секретную лабораторию в Азшаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Плохая наука! Плохая!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я пытался приручить местных гиппогрифов при помощи серии ослабляющих электрических ударов, а они вдруг непонятно с чего пришли в ярость! И теперь мои подопытные крушат все вокруг! $C, устрани результаты моих неудачных экспериментов, пока они не устранили меня.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 заряженных электричеством гиппогрифов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','То есть, мир снова безопасен для занятий наукой? Прекрасно! В следующий раз попробую раскаленные иглы или что-то вроде этого.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Твистексу Языкасту в секретную лабораторию в Азшаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (14323,'Абсорбент','Мне нужно еще кое-что. Горячая вода.$b$bЕе здесь найти не так-то просто. Ни горячих источников, ни друзей, которые могли бы поделиться. Хотя есть один способ. Возьми эту губку... Это исключительный абсорбент! Намочи ее в Коварном источнике на песчаной отмели к востоку отсюда.$b$bКогда соберется достаточно жидкости, отожми губку возле башни, чтобы вызвать громадного элементаля. У него есть горячая вода.','Соберите 20 капель кипящей воды из Коварного источника восточнее руин храма Арккоран.','Вы собрали необходимое количество капель кипящей воды, как просил вас Эргл. Теперь осталось только вызвать громадного элементаля.','Вернитесь к Эрглу на берег в руины храма Арккоран.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Абсорбент',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне нужно еще кое-что. Горячая вода.$b$bЕе здесь найти не так-то просто. Ни горячих источников, ни друзей, которые могли бы поделиться. Хотя есть один способ. Возьми эту губку... Это исключительный абсорбент! Намочи ее в Коварном источнике на песчаной отмели к востоку отсюда.$b$bКогда соберется достаточно жидкости, отожми губку возле башни, чтобы вызвать громадного элементаля. У него есть горячая вода.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 20 капель кипящей воды из Коварного источника восточнее руин храма Арккоран.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы собрали необходимое количество капель кипящей воды, как просил вас Эргл. Теперь осталось только вызвать громадного элементаля.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Эрглу на берег в руины храма Арккоран.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (14324,'Горячая вода','Эргл говорит, что теперь вы сможете использовать наполненную азшарийскую морскую губку, чтобы вызвать громадного элементаля возле башни Эльдары к северо-востоку отсюда.','Получите магическую сферу кипящей воды от повелителя кипящей воды у башни Эльдары.','Удобно, да? Кому нужны эти горячие источники. Прекрасно.','А, вот и ты!','Вернитесь к Эрглу на берег в руины храма Арккоран.','Использование кипящей воды в развлекательных целях на коммерческой основе невозможно из-за того, что слишком опасно.','Повелитель кипящей воды') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Горячая вода',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эргл говорит, что теперь вы сможете использовать наполненную азшарийскую морскую губку, чтобы вызвать громадного элементаля возле башни Эльдары к северо-востоку отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Получите магическую сферу кипящей воды от повелителя кипящей воды у башни Эльдары.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Удобно, да? Кому нужны эти горячие источники. Прекрасно.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','А, вот и ты!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Эрглу на берег в руины храма Арккоран.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Использование кипящей воды в развлекательных целях на коммерческой основе невозможно из-за того, что слишком опасно.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Повелитель кипящей воды',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (14325,'Работа за еду','<Вождь Камма слушает вас, пока вы рассказываете про угрозу демонов и объясняете видения хана Ле\'праха.>$B$BНе надо рассказывать мне о демонах, |3-6($r). Они изгнали наш клан из земель наших предков.$B$BИз-за них мы были вынуждены захватить земли Колкар, где теперь пытаемся выжить.$B$BВойна против Колкар стоила моему народу больших потерь. Те, кто остались в живых, измождены, и им не хватает пищи.$B$BПринеси еды моим соплеменникам, а потом, если захочешь, поговорим о демонах.','Соберите 5 боков василиска.','Вернитесь к Хану Камме в новой деревне Маграм в Пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Работа за еду',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Вождь Камма слушает вас, пока вы рассказываете про угрозу демонов и объясняете видения хана Ле\'праха.>$B$BНе надо рассказывать мне о демонах, |3-6($r). Они изгнали наш клан из земель наших предков.$B$BИз-за них мы были вынуждены захватить земли Колкар, где теперь пытаемся выжить.$B$BВойна против Колкар стоила моему народу больших потерь. Те, кто остались в живых, измождены, и им не хватает пищи.$B$BПринеси еды моим соплеменникам, а потом, если захочешь, поговорим о демонах.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 5 боков василиска.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хану Камме в новой деревне Маграм в Пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (14326,'Встретимся наверху','Кто бы мог подумать, что войска Альянса снова возьмут меня в плен. Просто слов нет, чтобы выразить благодарность... Тебя ведь зовут $n, верно?$B$BДавай встретимся на верхней палубе и там уже разберемся с ними.','Проберитесь на верхнюю палубу "Караула Возмездия", который стоит у Затерянных островов, и поговорите с Траллом.','У меня важное поручение, и поэтому нельзя допустить, чтобы эти негодяи мне помешали. Разберемся с ними раз и навсегда!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Встретимся наверху',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кто бы мог подумать, что войска Альянса снова возьмут меня в плен. Просто слов нет, чтобы выразить благодарность... Тебя ведь зовут $n, верно?$B$BДавай встретимся на верхней палубе и там уже разберемся с ними.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проберитесь на верхнюю палубу "Караула Возмездия", который стоит у Затерянных островов, и поговорите с Траллом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','У меня важное поручение, и поэтому нельзя допустить, чтобы эти негодяи мне помешали. Разберемся с ними раз и навсегда!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (14327,'Я даю слово','Похоже, у нас нет выбора.$B$BХотя мне и не особо хочется сотрудничать с Колкар, в словах их вождя есть мудрость.$B$BПередай ему, что наши копья помогут ему в бою.','Хан Камма хочет, чтобы вы поговорили с ханом Ле\'прахом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Я даю слово',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Похоже, у нас нет выбора.$B$BХотя мне и не особо хочется сотрудничать с Колкар, в словах их вождя есть мудрость.$B$BПередай ему, что наши копья помогут ему в бою.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Хан Камма хочет, чтобы вы поговорили с ханом Ле\'прахом.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (14328,'Три принца','Клан Гелкис обитает на юго-западе Пустошей. Они настолько же упрямы, как и клан Маграм, а поскольку они не пострадали от войны и переселения, они гораздо сильнее.$B$BЧтобы укротить клан Гелкис, понадобится серьезная демонстрация силы.$B$BПравят кланом Хан Шодо и его три сына. Шодо стареет, и старые раны дают о себе знать. Он никогда не покидает своей пещеры и управляет племенем через своих сыновей.$B$BУбей их и убеди вождя присоединиться к нам.','Расправьтесь с Рохо, Шериком и Джорретом.','Поговорите с Ханом Шодо в Пещере Болгана, что в Пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Три принца',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Клан Гелкис обитает на юго-западе Пустошей. Они настолько же упрямы, как и клан Маграм, а поскольку они не пострадали от войны и переселения, они гораздо сильнее.$B$BЧтобы укротить клан Гелкис, понадобится серьезная демонстрация силы.$B$BПравят кланом Хан Шодо и его три сына. Шодо стареет, и старые раны дают о себе знать. Он никогда не покидает своей пещеры и управляет племенем через своих сыновей.$B$BУбей их и убеди вождя присоединиться к нам.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Расправьтесь с Рохо, Шериком и Джорретом.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Ханом Шодо в Пещере Болгана, что в Пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (14329,'Не так быстро!','Хан Шодо хочет, чтобы вы убили 10 извергов из племени Мародин в Долине Копий.$B$BВы должны обыскать их тела в поисках подсказок о местонахождении Керры.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Не так быстро!',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Хан Шодо хочет, чтобы вы убили 10 извергов из племени Мародин в Долине Копий.$B$BВы должны обыскать их тела в поисках подсказок о местонахождении Керры.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (14330,'За закрытыми дверьми','Вы узнали, где держат дочь Хана Шодо, Керру. Она томится в заточении в Мародоне!$B$BПопытка спасти ее весьма рискована, однако если вам нужна помощь клана Гелкис, придется освободить дочь вождя.','Найдите Керру в стенах Марадона.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','За закрытыми дверьми',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы узнали, где держат дочь Хана Шодо, Керру. Она томится в заточении в Мародоне!$B$BПопытка спасти ее весьма рискована, однако если вам нужна помощь клана Гелкис, придется освободить дочь вождя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Керру в стенах Марадона.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (14332,'Время перемен','<Керра слушает вас, пока вы рассказываете о последних событиях.>$B$BЯ соглашусь со словами вождя клана Колкар. Пришло время покончить со старыми распрями. Жаль, что племена решили объединиться лишь тогда, когда появился внешний враг – демоны.$B$BЯ вернусь к своему отцу и попытаюсь убедить его присоединиться к вам. Я даю тебе слово, что он согласится.$B$BВернись к хану Ле\'праху и сообщи ему, что кентавры племени Гелкис готовы сражаться вместе.','Керра хочет, чтобы вы поговорили с ханом Ле\'прахом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Время перемен',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Керра слушает вас, пока вы рассказываете о последних событиях.>$B$BЯ соглашусь со словами вождя клана Колкар. Пришло время покончить со старыми распрями. Жаль, что племена решили объединиться лишь тогда, когда появился внешний враг – демоны.$B$BЯ вернусь к своему отцу и попытаюсь убедить его присоединиться к вам. Я даю тебе слово, что он согласится.$B$BВернись к хану Ле\'праху и сообщи ему, что кентавры племени Гелкис готовы сражаться вместе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Керра хочет, чтобы вы поговорили с ханом Ле\'прахом.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (14333,'Пока ты здесь','Мародин много лет нападали на лагеря Гелкис, крадя все, что плохо лежало.$B$BОдно из их любимых занятий – похищение и осквернение святых реликвий племени Гелкис.$B$BКлан Гелкис оценит, если ты найдешь и уничтожишь оскверненные артефакты.','Обыщите Долину Копий и найдите 6 оскверненных реликвий.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пока ты здесь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мародин много лет нападали на лагеря Гелкис, крадя все, что плохо лежало.$B$BОдно из их любимых занятий – похищение и осквернение святых реликвий племени Гелкис.$B$BКлан Гелкис оценит, если ты найдешь и уничтожишь оскверненные артефакты.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обыщите Долину Копий и найдите 6 оскверненных реликвий.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (14334,'Брюхажира','Салют, $gприятель:подруга;!$B$BДумаешь, тебе удастся нам тут подсобить, а?$B$BМы легко справимся с любым китом в этих водах, но есть один, который слишком велик для нашего копья.$B$BБрюхажира все растет и растет – еще бы, она слопала всю рыбу на милю вокруг!$B$BНайди ее и заткни, наконец, эту прожорливую глотку!','Убейте Брюхажиру по заданию Май\'Лахии.','Ух ты! У тебя получилось!$B$BСкоро в наших сетях снова появится рыба.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Брюхажира',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Салют, $gприятель:подруга;!$B$BДумаешь, тебе удастся нам тут подсобить, а?$B$BМы легко справимся с любым китом в этих водах, но есть один, который слишком велик для нашего копья.$B$BБрюхажира все растет и растет – еще бы, она слопала всю рыбу на милю вокруг!$B$BНайди ее и заткни, наконец, эту прожорливую глотку!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Брюхажиру по заданию Май\'Лахии.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ух ты! У тебя получилось!$B$BСкоро в наших сетях снова появится рыба.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (14335,'Дело нужное','Ты наверняка $gзаметил:заметила;, все эти природные катаклизмы имеют далеко идущие последствия. Некоторые из них к добру, но другие, увы... нет.$B$BК югу отсюда лангустины выбрались из моря и перекрыли дорогу в деревню.$B$BПрошу тебя, |3-6($c), отправляйся туда и разберись с этим тварями.','Убейте 5 крабов с мертвой хваткой и 5 жестколапых клешневиков.','Поговорите с Тайгой Мудрой Гривой в деревне Ночных Охотников.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дело нужное',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты наверняка $gзаметил:заметила;, все эти природные катаклизмы имеют далеко идущие последствия. Некоторые из них к добру, но другие, увы... нет.$B$BК югу отсюда лангустины выбрались из моря и перекрыли дорогу в деревню.$B$BПрошу тебя, |3-6($c), отправляйся туда и разберись с этим тварями.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 5 крабов с мертвой хваткой и 5 жестколапых клешневиков.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Тайгой Мудрой Гривой в деревне Ночных Охотников.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (14336,'Убивай или будешь убит','Раньше рифы защищали нас от нападения с моря, но теперь землетрясения открыли путь кораблям Отрекшихся.$B$BБыстрее, $n. Мы должны замедлить продвижение врага и оповестить оставшихся ополченцев.$B$BКажется, я слышу голос принца и его людей, сражающихся с нежитью. Спроси Лиама, чем ты можешь ему помочь.$B$BДа... и постарайся защитить его. Боюсь, что в его теперешнем состоянии он несколько беспечен.','Поговорите с принцем Лиамом Седогривом. Вы найдете его рядом с Темной Гаванью.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Убивай или будешь убит',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Раньше рифы защищали нас от нападения с моря, но теперь землетрясения открыли путь кораблям Отрекшихся.$B$BБыстрее, $n. Мы должны замедлить продвижение врага и оповестить оставшихся ополченцев.$B$BКажется, я слышу голос принца и его людей, сражающихся с нежитью. Спроси Лиама, чем ты можешь ему помочь.$B$BДа... и постарайся защитить его. Боюсь, что в его теперешнем состоянии он несколько беспечен.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с принцем Лиамом Седогривом. Вы найдете его рядом с Темной Гаванью.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (14337,'Деревня Ночных Охотников','Привет, |3-6($c).$B$BДо меня дошли слухи, что деревне Ночных Охотников не помешает помощь. Здесь у нас лишней работы нет, так что почему бы тебе не отправиться туда и не помочь им?$B$BДеревня расположена на берегу к юго-западу отсюда. По прибытии найди Май\'Лахию, она скажет тебе, что делать.','Поговорите с Май\'Лахией по просьбе Карнума Ткача Болот.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Деревня Ночных Охотников',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Привет, |3-6($c).$B$BДо меня дошли слухи, что деревне Ночных Охотников не помешает помощь. Здесь у нас лишней работы нет, так что почему бы тебе не отправиться туда и не помочь им?$B$BДеревня расположена на берегу к юго-западу отсюда. По прибытии найди Май\'Лахию, она скажет тебе, что делать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Май\'Лахией по просьбе Карнума Ткача Болот.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (14338,'Застава Скитающихся Духов','Ну здравствуй, |3-6($c).$B$BОтрадно видеть тебя в добром здравии. Сейчас мне нужна твоя помощь.$B$BТебе придется отправиться на заставу Скитающихся духов к юго-западу отсюда и найти там Отрекшегося по имени Маурин Костолом.$B$BМожет быть, у него есть решение хотя бы одной из проблем, с которыми мы здесь столкнулись?$B$BПоговори с ним и помоги ему, чем сможешь.','По поручению Карнума Ткача Болот поговорите с Маурином Костоломом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Застава Скитающихся Духов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну здравствуй, |3-6($c).$B$BОтрадно видеть тебя в добром здравии. Сейчас мне нужна твоя помощь.$B$BТебе придется отправиться на заставу Скитающихся духов к юго-западу отсюда и найти там Отрекшегося по имени Маурин Костолом.$B$BМожет быть, у него есть решение хотя бы одной из проблем, с которыми мы здесь столкнулись?$B$BПоговори с ним и помоги ему, чем сможешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По поручению Карнума Ткача Болот поговорите с Маурином Костоломом.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (14339,'Тара для перевозки','Я сейчас занимаюсь одним важным делом – на благо Круга Кенария и для себя лично.$B$BВидишь ли, |3-6($c), мне надо срочно сварить... одно особое зелье. В общем и целом работа закончена, но мне еще нужно его испытать, чтобы убедиться, что все получилось.$B$BИспытывать я его буду на нагах, что угрожают нам с запада. Если получится их истребить, это будет хорошая помощь Кругу.$B$BНо для начала мне необходимо найти тару для перевозки. Думаю, полые рога умирающих кодо – это как раз то, что нужно.','Соберите 3 полых рога умирающих кодо и отнесите их Маурину Костолому.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тара для перевозки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я сейчас занимаюсь одним важным делом – на благо Круга Кенария и для себя лично.$B$BВидишь ли, |3-6($c), мне надо срочно сварить... одно особое зелье. В общем и целом работа закончена, но мне еще нужно его испытать, чтобы убедиться, что все получилось.$B$BИспытывать я его буду на нагах, что угрожают нам с запада. Если получится их истребить, это будет хорошая помощь Кругу.$B$BНо для начала мне необходимо найти тару для перевозки. Думаю, полые рога умирающих кодо – это как раз то, что нужно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 3 полых рога умирающих кодо и отнесите их Маурину Костолому.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`) VALUES (14340,'Встречают по одежке','Думаю, каждый человек должен учиться.$b$bВот, возьми мою шляпу волшебника. Я не сомневаюсь, что он возьмет тебя в $gученики:ученицы;, если ты будешь выглядеть подобающе... тебе только надо умело подлизаться к нему. Попрыгать, так сказать, через обруч. Небольшой такой пылающий обруч с вращающимися лезвиями.$b$bТы найдешь проекцию Ксилема на вершине того холма к северо-востоку отсюда.','Наденьте вашу новую шляпу волшебника и поговорите с проекцией верховного мага Ксилема. Его можно найти к северо-востоку от северной пересадочной станции ракетной дороги.','Глядя на тебя, сразу думаешь о высокой моде! Довольно красивая шляпа, должен сказать.$B$BУченики. Ученики? Несколько у меня уже есть, но учеников много не бывает.','Приветствую.','Отправляйтесь к верховному магу Ксилему в своей шляпе волшебника.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Встречают по одежке',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Думаю, каждый человек должен учиться.$b$bВот, возьми мою шляпу волшебника. Я не сомневаюсь, что он возьмет тебя в $gученики:ученицы;, если ты будешь выглядеть подобающе... тебе только надо умело подлизаться к нему. Попрыгать, так сказать, через обруч. Небольшой такой пылающий обруч с вращающимися лезвиями.$b$bТы найдешь проекцию Ксилема на вершине того холма к северо-востоку отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Наденьте вашу новую шляпу волшебника и поговорите с проекцией верховного мага Ксилема. Его можно найти к северо-востоку от северной пересадочной станции ракетной дороги.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Глядя на тебя, сразу думаешь о высокой моде! Довольно красивая шляпа, должен сказать.$B$BУченики. Ученики? Несколько у меня уже есть, но учеников много не бывает.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Приветствую.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Отправляйтесь к верховному магу Ксилему в своей шляпе волшебника.',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (14341,'Снаряжение Смида','Прошу прощения, $gюный:юная:r; |3-6($r).$B$BМне нужна помощь. У меня тут был срочный заказ на снаряжение, его надо как можно скорее доставить заказчику.$B$BЯ уже староват для таких путешествий, тем более, что тут у нас нынче небезопасно.$B$BУважь старика, помоги.$B$BСнаряжение надо доставить гоблину Смиду. Он живет к юго-востоку отсюда.','По поручению Натаки на Заставе Скитающихся Духов отнесите Смиду его снаряжение.','А-а, мое снаряжение!$B$BВот спасибо, дружище!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Снаряжение Смида',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прошу прощения, $gюный:юная:r; |3-6($r).$B$BМне нужна помощь. У меня тут был срочный заказ на снаряжение, его надо как можно скорее доставить заказчику.$B$BЯ уже староват для таких путешествий, тем более, что тут у нас нынче небезопасно.$B$BУважь старика, помоги.$B$BСнаряжение надо доставить гоблину Смиду. Он живет к юго-востоку отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По поручению Натаки на Заставе Скитающихся Духов отнесите Смиду его снаряжение.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А-а, мое снаряжение!$B$BВот спасибо, дружище!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (14342,'Вторжение демонов','Демоны готовят вторжение, |3-6($r)!$B$BЕсли мы не найдем способ остановить их сейчас, потом нам с ними уже не справиться. У нас есть пара недель, не больше. Я только что возвратился с поля Маннорок, где инферналы в прямом смысле слова валятся с неба!$B$BНужно их задержать, чтобы выиграть время. Отправляйся туда и постарайся прикончить хоть нескольких демонов!','По поручению Фелгура Бью-Двоих уничтожьте 10 младших инферналов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вторжение демонов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Демоны готовят вторжение, |3-6($r)!$B$BЕсли мы не найдем способ остановить их сейчас, потом нам с ними уже не справиться. У нас есть пара недель, не больше. Я только что возвратился с поля Маннорок, где инферналы в прямом смысле слова валятся с неба!$B$BНужно их задержать, чтобы выиграть время. Отправляйся туда и постарайся прикончить хоть нескольких демонов!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По поручению Фелгура Бью-Двоих уничтожьте 10 младших инферналов.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (14343,'Зелье Маурина','<Маурин разливает зелье по полым рогам кодо и тщательно их запечатывает.>$B$BНу вот, |3-6($c), все готово.$B$BОтнеси их Карнуму. Он сам разберется, как применить это снадобье против наг.$B$BА я прослежу за результатом. Мне же надо понять, насколько эффективна моя формула!','По поручению Маурина отнесите зелье Маурина Карнуму в Рощу Карнума.','Сказать по правде, меня как-то не радует, что приходиться применять столь жестокие меры. Но, боюсь, у нас просто нет выбора…') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зелье Маурина',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Маурин разливает зелье по полым рогам кодо и тщательно их запечатывает.>$B$BНу вот, |3-6($c), все готово.$B$BОтнеси их Карнуму. Он сам разберется, как применить это снадобье против наг.$B$BА я прослежу за результатом. Мне же надо понять, насколько эффективна моя формула!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По поручению Маурина отнесите зелье Маурина Карнуму в Рощу Карнума.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сказать по правде, меня как-то не радует, что приходиться применять столь жестокие меры. Но, боюсь, у нас просто нет выбора…',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (14344,'Уничтожение Джукгара','Вы узнаете в этом сущность призванного демона.$B$BОпасные потоки неведанной энергии струятся по ее поверхности.$B$BВы смотрите на сущность и вам является видение, в котором вы контролируете демонов. Вас охватывет восторг, когда вы понимаете, какая огромная сила находится в ваших руках.$B$BВы погружаетесь в размышления о том, как можно использовать это сокровище против демона...','Используйте источник мощи преисподней, чтобы взять под контроль лорда Азретока у алтаря Джукгара и использовать его силы для убийства Джугкара Грим\'рода.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уничтожение Джукгара',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы узнаете в этом сущность призванного демона.$B$BОпасные потоки неведанной энергии струятся по ее поверхности.$B$BВы смотрите на сущность и вам является видение, в котором вы контролируете демонов. Вас охватывет восторг, когда вы понимаете, какая огромная сила находится в ваших руках.$B$BВы погружаетесь в размышления о том, как можно использовать это сокровище против демона...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте источник мощи преисподней, чтобы взять под контроль лорда Азретока у алтаря Джукгара и использовать его силы для убийства Джугкара Грим\'рода.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (14345,'Изматывающая учеба','Изумительно!$b$bАзу всегда старается раздобыть магические артефакты. Он говорил, что он пытался подружиться с этим верховным магом. Ксилемом!$b$bУ Ксилема МНОГО учеников. Он всех берет. Изматывает их, потом они бродят тут и там. Большая текучка.$b$bПоследнего видел вчера. Он направлялся к той большой гоблинской строящейся башне, на запад. Может, он тебе поможет встретиться с Ксилемом? Может, Ксилем знает, где Азу?$b$bВеди себя хорошо!','Поговорите с Соратой Жонглирующим Огнем на северной пересадочной станции ракетной дороги.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Изматывающая учеба',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Изумительно!$b$bАзу всегда старается раздобыть магические артефакты. Он говорил, что он пытался подружиться с этим верховным магом. Ксилемом!$b$bУ Ксилема МНОГО учеников. Он всех берет. Изматывает их, потом они бродят тут и там. Большая текучка.$b$bПоследнего видел вчера. Он направлялся к той большой гоблинской строящейся башне, на запад. Может, он тебе поможет встретиться с Ксилемом? Может, Ксилем знает, где Азу?$b$bВеди себя хорошо!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Соратой Жонглирующим Огнем на северной пересадочной станции ракетной дороги.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (14346,'Очищение нашей расселины','Как ты $gсам убедился:сама убедилась;, $n, наги все еще представляют серьезную угрозу для этого региона. Пора прогнать их обратно в море!$B$BКогда будешь $gготов:готова;, Жутекрыл доставит тебя к расселине, где наги готовят массированную атаку. Прибыв на место, воспользуйся зельем Маурина. Пусть эти наги узнают, что с нами лучше не связываться!','По поручению Карнума Ткача Болот убейте 10 захватчиков и 10 сирен из клана Скользящего Плавника, а также трех морских великанов при помощи зелья Маурина.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Очищение нашей расселины',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как ты $gсам убедился:сама убедилась;, $n, наги все еще представляют серьезную угрозу для этого региона. Пора прогнать их обратно в море!$B$BКогда будешь $gготов:готова;, Жутекрыл доставит тебя к расселине, где наги готовят массированную атаку. Прибыв на место, воспользуйся зельем Маурина. Пусть эти наги узнают, что с нами лучше не связываться!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По поручению Карнума Ткача Болот убейте 10 захватчиков и 10 сирен из клана Скользящего Плавника, а также трех морских великанов при помощи зелья Маурина.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (14347,'Держать строй!','$n! Я все еще не знаю, $gжив ты или мертв:жива ты или мертва;... человек ты или ворген...$B$BДа что там говорить – я даже не уверен, что это все происходит на самом деле. Но одно я знаю точно – сегодня мы убьем множество этих чертовых Отрекшихся.','Вернитесь к принцу Лиаму Седогриву. Он ждет вас возле Темной Гавани, что в Гилнеасе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Держать строй!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n! Я все еще не знаю, $gжив ты или мертв:жива ты или мертва;... человек ты или ворген...$B$BДа что там говорить – я даже не уверен, что это все происходит на самом деле. Но одно я знаю точно – сегодня мы убьем множество этих чертовых Отрекшихся.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к принцу Лиаму Седогриву. Он ждет вас возле Темной Гавани, что в Гилнеасе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (14348,'Одному не справиться','Смотри и запоминай, $n. Труднее всего справиться с этими большими толстыми тварями – поганищами, так что не нападай на них в одиночку.$B$BПравда, у меня есть одна идея, настолько безумная, что это может сработать. Должен тебя предупредить: это связано с риском для жизни.$B$BВидишь бочки с порохом, стоящие под навесом и рядом с мельницами? Хватай их и кидай прямо на головы поганищ. А дальше я с ними сам разберусь с помощью верного мушкета.','Вернитесь к принцу Лиаму Седогриву в Темную Гавань, что в Гилнеасе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Одному не справиться',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Смотри и запоминай, $n. Труднее всего справиться с этими большими толстыми тварями – поганищами, так что не нападай на них в одиночку.$B$BПравда, у меня есть одна идея, настолько безумная, что это может сработать. Должен тебя предупредить: это связано с риском для жизни.$B$BВидишь бочки с порохом, стоящие под навесом и рядом с мельницами? Хватай их и кидай прямо на головы поганищ. А дальше я с ними сам разберусь с помощью верного мушкета.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к принцу Лиаму Седогриву в Темную Гавань, что в Гилнеасе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (14349,'Приказ по армии','$C, к нам поступил приказ от самой Сильваны – отправить самых надежных агентов назад в Подгород для выполнения крайне важной тактической операции.$B$BК несчастью, все агенты, на которых я мог бы положиться в этом деле, были убиты три года назад. Вместо них мне пришлось набрать шайку безмозглых головорезов.$B$B<Натанос сурово смотрит на вас.>$B$BНемедленно отправляйся в Подгород на аудиенцию к Темной Госпоже. Постарайся не опозорить мои седины, |3-6($c)!','Отправляйтесь в Подгород и поговорите с леди Сильваной Ветрокрылой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приказ по армии',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$C, к нам поступил приказ от самой Сильваны – отправить самых надежных агентов назад в Подгород для выполнения крайне важной тактической операции.$B$BК несчастью, все агенты, на которых я мог бы положиться в этом деле, были убиты три года назад. Вместо них мне пришлось набрать шайку безмозглых головорезов.$B$B<Натанос сурово смотрит на вас.>$B$BНемедленно отправляйся в Подгород на аудиенцию к Темной Госпоже. Постарайся не опозорить мои седины, |3-6($c)!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Подгород и поговорите с леди Сильваной Ветрокрылой.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14350,'Курьер из Багрового Легиона','Возвращайтесь в Восточные Чумные земли и выследите курьера из Багрового Легиона. Убейте его и заберите приказ верховного рыцаря.$B$BЗа дальнейшими указаниями обращайтесь к Натаносу Гнилостню.','<Натанос смеется.>$B$BНаконец-то! Ура! Шанс уничтожить Алого Оракула!','Если ты справишься с этой задачей, можешь считать, что почти заслужил мое уважение, $C.','Вернитесь к Натаносу Гнилостню в Поместье Маррисов, что в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Курьер из Багрового Легиона',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возвращайтесь в Восточные Чумные земли и выследите курьера из Багрового Легиона. Убейте его и заберите приказ верховного рыцаря.$B$BЗа дальнейшими указаниями обращайтесь к Натаносу Гнилостню.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Натанос смеется.>$B$BНаконец-то! Ура! Шанс уничтожить Алого Оракула!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если ты справишься с этой задачей, можешь считать, что почти заслужил мое уважение, $C.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Натаносу Гнилостню в Поместье Маррисов, что в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14351,'Битва за Хилсбрад','Поскольку ты $gпроявил:проявила; немалое мужество и стойкость в битве за Хилсбрад, я написала это рекомендательное письмо, описывающее твой героизм. Пусть его прочитает высшее командование.$B$BОтнеси мое письмо Брагору Кровопалу в Подгород. Можешь гордиться собой, |3-6($c).','Отнесите запечатанное рекомендательное письмо Дарталии Брагору Кровопалу в Подгород.','Так ты тот печально известный $C, который нанес такой решающий удар силам Альянса в Предгорьях Хилсбрада? Весть о твоих славных подвигах быстро дошла до Подгорода.$B$BУ тебя есть будущее в рядах Темной Госпожи, если ты продолжишь демонстрировать такое лидерство и опыт в бою.$B$BВ то время как наша главная угроза - это армия Плети Короля-лича, спускающаяся с севера, человеческая «проблема» продолжает мешать нашим планам сражения. Однако ты $Gпоказал:показала;, что люди могут падать и падут.','Что принесло $C с поля боя в Подгород?','Вернитесь к Брагору Кровопалу в Подгород.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Битва за Хилсбрад',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Поскольку ты $gпроявил:проявила; немалое мужество и стойкость в битве за Хилсбрад, я написала это рекомендательное письмо, описывающее твой героизм. Пусть его прочитает высшее командование.$B$BОтнеси мое письмо Брагору Кровопалу в Подгород. Можешь гордиться собой, |3-6($c).',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите запечатанное рекомендательное письмо Дарталии Брагору Кровопалу в Подгород.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так ты тот печально известный $C, который нанес такой решающий удар силам Альянса в Предгорьях Хилсбрада? Весть о твоих славных подвигах быстро дошла до Подгорода.$B$BУ тебя есть будущее в рядах Темной Госпожи, если ты продолжишь демонстрировать такое лидерство и опыт в бою.$B$BВ то время как наша главная угроза - это армия Плети Короля-лича, спускающаяся с севера, человеческая «проблема» продолжает мешать нашим планам сражения. Однако ты $Gпоказал:показала;, что люди могут падать и падут.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что принесло $C с поля боя в Подгород?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Брагору Кровопалу в Подгород.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14352,'Нечестивый союз','Госпожа моя!$B$BНаше предложение вам прекрасно известно. Для вас это отличная возможность получить безграничную власть над Степями и окрестными землями. От вас нам требуется лишь небольшое содействие – дайте нам свободу действий в этих землях.$B$BМы убедительно просим вас рассмотреть это предложение. Мы обладаем великой силой и охотно поделимся ею с тем, кто достаточно мудр, чтобы примкнуть к нам. Я буду ждать вас у Курганов Иглошкурых.$B$BС наилучшими пожеланиями,$BПосланник Малкин.','Отнесите маленький свиток Брагору Кровопалу в Подгород.','Я видел знак отличия на этом свитке раньше, когда был в Нордсколе. Ты говоришь, что это была та старушка, которая водит свиней в Лабиринты Иглошкурых?$B$BБудь я проклят, если позволю Плети закрепиться здесь. Тот, кто написал это - этот Малкин - очевидно, один из слуг Короля-лича, и это делает его целью. Твоей целью.$B$BОни не возьмут Калимдор.','Чего ты хочешь, $N? Лучше бы это было важно.','Вернитесь к Брагору Кровопалу в Подгород.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нечестивый союз',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Госпожа моя!$B$BНаше предложение вам прекрасно известно. Для вас это отличная возможность получить безграничную власть над Степями и окрестными землями. От вас нам требуется лишь небольшое содействие – дайте нам свободу действий в этих землях.$B$BМы убедительно просим вас рассмотреть это предложение. Мы обладаем великой силой и охотно поделимся ею с тем, кто достаточно мудр, чтобы примкнуть к нам. Я буду ждать вас у Курганов Иглошкурых.$B$BС наилучшими пожеланиями,$BПосланник Малкин.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите маленький свиток Брагору Кровопалу в Подгород.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я видел знак отличия на этом свитке раньше, когда был в Нордсколе. Ты говоришь, что это была та старушка, которая водит свиней в Лабиринты Иглошкурых?$B$BБудь я проклят, если позволю Плети закрепиться здесь. Тот, кто написал это - этот Малкин - очевидно, один из слуг Короля-лича, и это делает его целью. Твоей целью.$B$BОни не возьмут Калимдор.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Чего ты хочешь, $N? Лучше бы это было важно.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Брагору Кровопалу в Подгород.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14353,'Нечестивый союз','Предположительно, этот Малкин находится за пределами Курганов Иглошкурых. Это не обсуждается – он должен умереть!$b$bМой связной из Оргриммара сообщил, что их разведчики обнаружили там следы чумы. Очевидно, что Иглошкуры тоже заражены – они стали слишком сильными. Мы должны немедленно положить конец козням Плети!$b$bНайди этого Малкина и убей его. Доложи мне, когда дело будет сделано.','Принести голову посла Брагору Кровопалу в Подгород.','Хорошая работа, $C!$B$BТы $Gвозвысил:возвысила; Орду, не позволив Плети пустить корни на нашей земле. Подобный поступок заслуживает награды, а у Отрекшихся есть достаточно вещей$B$BМы можем не знать всего, что они сделали в Курганах, но мы узнаем. Они не могут вечно скрываться в темноте.','Ты $Gнашел:нашла; посла, $N? Он мертв?$B$BМы не можем позволить Плети закрепиться на Калимдоре. Она представляют собой достаточную угрозу для наших границ, чтобы иметь дело с ней на двух фронтах.$B$BЕдинственный оптимистичный знак...','Вернитесь к Брагору Кровопалу в Королевский квартал, что в Подгороде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нечестивый союз',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Предположительно, этот Малкин находится за пределами Курганов Иглошкурых. Это не обсуждается – он должен умереть!$b$bМой связной из Оргриммара сообщил, что их разведчики обнаружили там следы чумы. Очевидно, что Иглошкуры тоже заражены – они стали слишком сильными. Мы должны немедленно положить конец козням Плети!$b$bНайди этого Малкина и убей его. Доложи мне, когда дело будет сделано.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принести голову посла Брагору Кровопалу в Подгород.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошая работа, $C!$B$BТы $Gвозвысил:возвысила; Орду, не позволив Плети пустить корни на нашей земле. Подобный поступок заслуживает награды, а у Отрекшихся есть достаточно вещей$B$BМы можем не знать всего, что они сделали в Курганах, но мы узнаем. Они не могут вечно скрываться в темноте.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gнашел:нашла; посла, $N? Он мертв?$B$BМы не можем позволить Плети закрепиться на Калимдоре. Она представляют собой достаточную угрозу для наших границ, чтобы иметь дело с ней на двух фронтах.$B$BЕдинственный оптимистичный знак...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Брагору Кровопалу в Королевский квартал, что в Подгороде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (14354,'Дары Элуны','Просто невыносимо!$B$BСатиры оскверняют наши священные земли...$B$BИх дни сочтены, |3-6($r). Уж в этом я могу тебя заверить. Как только у нас будет достаточно бойцов, я поведу их в атаку и избавлю землю от этих гадких созданий.$B$BА сейчас не $gмог:могла; бы ты немного облегчить мне жизнь?$B$BОтправляйся на восток, в Саргерон, и изучи руины. Найди реликвии Элуны и убедись, что они находятся в хорошем состоянии.$B$BЯ щедро вознагражу тебя за это.','Отправьтесь к реликвиям Элуны в Саргероне.','Вернитесь к Валлариэлю на Высоте Найджела в Пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дары Элуны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Просто невыносимо!$B$BСатиры оскверняют наши священные земли...$B$BИх дни сочтены, |3-6($r). Уж в этом я могу тебя заверить. Как только у нас будет достаточно бойцов, я поведу их в атаку и избавлю землю от этих гадких созданий.$B$BА сейчас не $gмог:могла; бы ты немного облегчить мне жизнь?$B$BОтправляйся на восток, в Саргерон, и изучи руины. Найди реликвии Элуны и убедись, что они находятся в хорошем состоянии.$B$BЯ щедро вознагражу тебя за это.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправьтесь к реликвиям Элуны в Саргероне.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Валлариэлю на Высоте Найджела в Пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (14355,'В монастырь Алого ордена','Одна из моих задач – помогать Отрекшимся охранять границы, и в этом ты, |3-6($c), можешь мне помочь.$b$bЖивой или мертвый – Алому ордену без разницы; они убивают моих людей наравне с нежитью. Они – моя главная проблема, с которой тебе предстоит разобраться.$b$bОтправляйся в Монастырь и убей верховного инквизитора Вайтмейн с ее лейтенантами.','Убейте верховного инквизитора Вайтмейн, командира Алого ордена Могрейна, Ирода из Алого ордена и псаря Локси, после этого вернитесь с докладом к Брагору Кровопалу в Подгород.','Ты $Gсослужил:сослужила; Темной Госпоже отличную службу, $C. Это задание было не из легких.$B$BЯ не забуду о твоей преданности Отрекшимся и стойкости в битве.','Вернитесь к Брагору Кровопалу в Королевский квартал, что в Подгороде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В монастырь Алого ордена',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Одна из моих задач – помогать Отрекшимся охранять границы, и в этом ты, |3-6($c), можешь мне помочь.$b$bЖивой или мертвый – Алому ордену без разницы; они убивают моих людей наравне с нежитью. Они – моя главная проблема, с которой тебе предстоит разобраться.$b$bОтправляйся в Монастырь и убей верховного инквизитора Вайтмейн с ее лейтенантами.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте верховного инквизитора Вайтмейн, командира Алого ордена Могрейна, Ирода из Алого ордена и псаря Локси, после этого вернитесь с докладом к Брагору Кровопалу в Подгород.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты $Gсослужил:сослужила; Темной Госпоже отличную службу, $C. Это задание было не из легких.$B$BЯ не забуду о твоей преданности Отрекшимся и стойкости в битве.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Брагору Кровопалу в Королевский квартал, что в Подгороде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14356,'Силы разрушения...','Послушай, |3-6($c).$b$bТебе это, возможно, неизвестно, но Огриммар столкнулся с неожиданной проблемой. Глубоко в Огненной Пропасти творит свои зловещие дела секта Совета Теней – Пламенеющий Клинок. Она состоит в основном из орков, поэтому я не могу доверять вот этим бугаям. Твоя помощь придется как нельзя кстати.$b$bВо владении Совета оказались две книги, которые не должны попасть в руки Пламенеющего Клинка и Отрекшихся. Принеси их мне.','Принесите книги "Заклинания Тьмы" и "Заклятия Пустоты" Брагору Кровопалу в Подгород.','Хорошо, $C. Ты хорошо $Gпоработал:поработала;. Я сохраню их от посторонних глаз и последнее, что нам нужно, - это восстание сильного Совета Теней.$B$BСвяжись со мной в будущем, здесь всегда есть чем заняться соответственно мне может понадобиться способный боец.','Вы сохранили книги? Их нужно держать подальше от чужих рук.','Вернитесь к Брагору Кровопалу в Королевский квартал Подгорода.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Силы разрушения...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Послушай, |3-6($c).$b$bТебе это, возможно, неизвестно, но Огриммар столкнулся с неожиданной проблемой. Глубоко в Огненной Пропасти творит свои зловещие дела секта Совета Теней – Пламенеющий Клинок. Она состоит в основном из орков, поэтому я не могу доверять вот этим бугаям. Твоя помощь придется как нельзя кстати.$b$bВо владении Совета оказались две книги, которые не должны попасть в руки Пламенеющего Клинка и Отрекшихся. Принеси их мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите книги "Заклинания Тьмы" и "Заклятия Пустоты" Брагору Кровопалу в Подгород.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо, $C. Ты хорошо $Gпоработал:поработала;. Я сохраню их от посторонних глаз и последнее, что нам нужно, - это восстание сильного Совета Теней.$B$BСвяжись со мной в будущем, здесь всегда есть чем заняться соответственно мне может понадобиться способный боец.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы сохранили книги? Их нужно держать подальше от чужих рук.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Брагору Кровопалу в Королевский квартал Подгорода.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (14357,'Оружие поверженного врага','Соберите 20 сабель сатиров – возьмите с оружейных стоек или отберите у сатиров, обитающих в этих краях.','По завершении ритуала вы получаете божественный дар.$B$BВы ощущаете невольное восхищение, получив один из даров Элуны.','Военный обряд Элуны совершен','Поместите сабли сатиров на статую прислужницы Элуны в Саргероне, что в Пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оружие поверженного врага',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 20 сабель сатиров – возьмите с оружейных стоек или отберите у сатиров, обитающих в этих краях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','По завершении ритуала вы получаете божественный дар.$B$BВы ощущаете невольное восхищение, получив один из даров Элуны.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Военный обряд Элуны совершен',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поместите сабли сатиров на статую прислужницы Элуны в Саргероне, что в Пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (14358,'Десять фунтов плоти','Добудьте 10 кусков плоти различных сатиров в Саргероне.','Божественная жаровня дарует вам благословение.','Поместите плоть сатира на жаровню Элуны в Саргероне, что в Пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Десять фунтов плоти',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 10 кусков плоти различных сатиров в Саргероне.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Божественная жаровня дарует вам благословение.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поместите плоть сатира на жаровню Элуны в Саргероне, что в Пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (14359,'Благословение свыше','Вы чувствуете глубокую связь с прошлым, получив древнее благословение, дарованное этой реликвией.$B$BВы решаете заслужить благословение еще раз.','Добудьте 10 кусков плоти различных сатиров в Саргероне и возложите на жаровню Элуны.','Божественная жаровня дарует вам благословление.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Благословение свыше',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы чувствуете глубокую связь с прошлым, получив древнее благословение, дарованное этой реликвией.$B$BВы решаете заслужить благословение еще раз.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 10 кусков плоти различных сатиров в Саргероне и возложите на жаровню Элуны.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Божественная жаровня дарует вам благословление.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (14360,'Пара дынь решит любую проблему','Символы на руинах Саргерона вкупе с расшифрованными фрагментами записей Фуриена определенно указывают на то, что древний источник в святилище Элуны обладает магической силой.$B$BТому, кто умоет в нем лицо, даются какие-то особые способности. Вот только источник давно высох... и его надо как-то наполнить, чтобы было чем умыться.$B$BРазмышляя над этой проблемой, вы замечаете плод дыни на земле под ближайшим деревом...','Соберите 8 плодов дыни и выжмите их сок в кубок Элуны в Саргероне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пара дынь решит любую проблему',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Символы на руинах Саргерона вкупе с расшифрованными фрагментами записей Фуриена определенно указывают на то, что древний источник в святилище Элуны обладает магической силой.$B$BТому, кто умоет в нем лицо, даются какие-то особые способности. Вот только источник давно высох... и его надо как-то наполнить, чтобы было чем умыться.$B$BРазмышляя над этой проблемой, вы замечаете плод дыни на земле под ближайшим деревом...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 плодов дыни и выжмите их сок в кубок Элуны в Саргероне.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (14361,'Спокойный сон капитана','Мы – передовой пост сил в этом регионе, и отвечаем за то, чтобы заранее выявить возможных противников и избавить Альянс от неприятных сюрпризов, когда начнется кампания в Пустошах.$B$BНедавно один из наших разведчиков был пойман и принесен в жертву адептами Пылающего Клинка в их крепости к западу отсюда. С тех пор нам постоянно поступают угрозы и оскорбления от одного типа из этого клана по имени Кохор.$B$BПылающему Клинку уже недолго осталось, но я хорошо заплачу, если ты заставишь этого гада заткнуться прямо сейчас!','Ликвидируйте Кохора.','Вернитесь к капитану Пентигасту на Высоте Найджела в Пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спокойный сон капитана',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы – передовой пост сил в этом регионе, и отвечаем за то, чтобы заранее выявить возможных противников и избавить Альянс от неприятных сюрпризов, когда начнется кампания в Пустошах.$B$BНедавно один из наших разведчиков был пойман и принесен в жертву адептами Пылающего Клинка в их крепости к западу отсюда. С тех пор нам постоянно поступают угрозы и оскорбления от одного типа из этого клана по имени Кохор.$B$BПылающему Клинку уже недолго осталось, но я хорошо заплачу, если ты заставишь этого гада заткнуться прямо сейчас!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Ликвидируйте Кохора.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Пентигасту на Высоте Найджела в Пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (14362,'Надрать уши','Капитан Пентигаст не скрывает своего отвращения к культу Пылающего Клинка, занявшему крепость Громового Топора.$B$BДоказательства их гибели придутся ему по душе.','Добудьте 25 ушей прислужников Пылающего Клинка.','Вернитесь к капитану Пентигасту на Высоте Найджела в Пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Надрать уши',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Капитан Пентигаст не скрывает своего отвращения к культу Пылающего Клинка, занявшему крепость Громового Топора.$B$BДоказательства их гибели придутся ему по душе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 25 ушей прислужников Пылающего Клинка.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Пентигасту на Высоте Найджела в Пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (14363,'Ты поймешь, когда увидишь','Перед смертью Кохор рассказал о ритуале призыва демона, который может угрожать всему региону.$B$BОн мог блефовать, но рисковать не стоит.$B$BДело не может ждать до того момента, когда вторжение Альянса в Пустоши наберет силу. Вам необходимо обыскать крепость Громового Топора в поисках улик и предотвратить трагедию.','Найдите следы древнего ритуала призыва в крепости Громового Топора.','Вернитесь к капитану Пентигасту на Высоте Найджела в Пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ты поймешь, когда увидишь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Перед смертью Кохор рассказал о ритуале призыва демона, который может угрожать всему региону.$B$BОн мог блефовать, но рисковать не стоит.$B$BДело не может ждать до того момента, когда вторжение Альянса в Пустоши наберет силу. Вам необходимо обыскать крепость Громового Топора в поисках улик и предотвратить трагедию.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите следы древнего ритуала призыва в крепости Громового Топора.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Пентигасту на Высоте Найджела в Пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (14364,'Голова на голове','Соберите 100 отбеленных черепов в Крепости Громового Топора, затем принесите их в круг призыва Пылающего Клинка, вызовите и убейте Назаргена.','Поговорите с капитаном Пентигастом на Высоте Найджела.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Голова на голове',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 100 отбеленных черепов в Крепости Громового Топора, затем принесите их в круг призыва Пылающего Клинка, вызовите и убейте Назаргена.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с капитаном Пентигастом на Высоте Найджела.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (14365,'Этель-Ретор','Мы недавно получили просьбу о помощи от исследовательницы из Круга Кенария.$B$BК сожалению, мы никого не можем туда отправить, так что я попрошу тебя навестить ее от нашего имени.$B$BКорру можно найти возле разрушенной башни Этель-Ретор, находящейся на берегу на западе.','Капрал Мелкис хочет, чтобы вы поговорили с Коррой у Этель-Ретора.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Этель-Ретор',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы недавно получили просьбу о помощи от исследовательницы из Круга Кенария.$B$BК сожалению, мы никого не можем туда отправить, так что я попрошу тебя навестить ее от нашего имени.$B$BКорру можно найти возле разрушенной башни Этель-Ретор, находящейся на берегу на западе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Капрал Мелкис хочет, чтобы вы поговорили с Коррой у Этель-Ретора.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (14366,'Удержание позиций','Думаю, здесь мы можем удерживать позиции. Сообщи об этом мэру Армстед.$B$BЭто только малая часть сил Отрекшихся, но если мы не нападем на них в ближайшее время, нам придется иметь дело с куда большей проблемой.$B$BУзнай, как нам завязать бой с армией Отрекшихся прямо на месте их высадки.','Поговорите с Гвен Армстед в Темной Гавани.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Удержание позиций',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Думаю, здесь мы можем удерживать позиции. Сообщи об этом мэру Армстед.$B$BЭто только малая часть сил Отрекшихся, но если мы не нападем на них в ближайшее время, нам придется иметь дело с куда большей проблемой.$B$BУзнай, как нам завязать бой с армией Отрекшихся прямо на месте их высадки.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Гвен Армстед в Темной Гавани.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (14367,'Подвал Фермы Аллена') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подвал Фермы Аллена',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (14368,'Спасите детей!','Бедные мои детки не успели спрятаться, а проклятые военные не выпускают меня из подвала, чтобы отыскать их. Они все еще где-то там, на ферме!$B$BОтрекшиеся не пощадят даже столь невинные души...$B$BМоих детей зовут Синтия, Эшли и Джеймс. Если ты увидишь их, пожалуйста, приведи сюда – и я буду у тебя в неоплатном долгу.','Спасите Синтию, Эшли и Джеймса, которые остались где-то на ферме Хэммондов.','Вернитесь к Мелинде Хэммонд в подвал Фермы Аллена в Гилнеасе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спасите детей!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Бедные мои детки не успели спрятаться, а проклятые военные не выпускают меня из подвала, чтобы отыскать их. Они все еще где-то там, на ферме!$B$BОтрекшиеся не пощадят даже столь невинные души...$B$BМоих детей зовут Синтия, Эшли и Джеймс. Если ты увидишь их, пожалуйста, приведи сюда – и я буду у тебя в неоплатном долгу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Спасите Синтию, Эшли и Джеймса, которые остались где-то на ферме Хэммондов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мелинде Хэммонд в подвал Фермы Аллена в Гилнеасе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (14369,'Звериная сила','Не стану лгать, $n – мне не нравится сражаться бок о бок с воргеном.$B$BКто знает, как долго будет действовать на тебя снадобье Креннана, и не соберешься ли ты откусить мою голову в разгар битвы.$B$BНо пока этого не произошло, мы, пожалуй, найдем применение твоей звериной силе.$B$BСтупай на поле боя и убей столько Отрекшихся, сколько сможешь.$B$BИ не стесняйся использовать самые жестокие приемы – пусть они знают, с кем связались.','Вернитесь к лорду Годфри в подвал Фермы Аллена, что в Гилнеасе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Звериная сила',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не стану лгать, $n – мне не нравится сражаться бок о бок с воргеном.$B$BКто знает, как долго будет действовать на тебя снадобье Креннана, и не соберешься ли ты откусить мою голову в разгар битвы.$B$BНо пока этого не произошло, мы, пожалуй, найдем применение твоей звериной силе.$B$BСтупай на поле боя и убей столько Отрекшихся, сколько сможешь.$B$BИ не стесняйся использовать самые жестокие приемы – пусть они знают, с кем связались.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лорду Годфри в подвал Фермы Аллена, что в Гилнеасе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (14370,'Таинственный азшарит','Азшарит! Эту таинственную кристаллическую субстанцию использовали, чтобы наделять оружие мощью Скверны, но мы обнаружили, что она способна удерживать огромное количество энергии. Наверное, это самое крупное открытие гоблинов со времен каджа\'мита.$b$bНо что это за субстанция? Откуда она взялась? Почему ее находят только здесь? Наука требует ответов! Мне нужны еще образцы для изучения. Поищи залежи азшарита в ближайших скалах.','Соберите 5 образцов азшарита в ближайших скалах.','Ах, великолепно. Некоторые из этих образцов выглядят свежими. У меня будет достаточно материала, пока я буду пытаться решить эту загадку!','Принесите образцы ассистенту Грили на южную конечную станцию ракетной дороги в Азшаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Таинственный азшарит',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Азшарит! Эту таинственную кристаллическую субстанцию использовали, чтобы наделять оружие мощью Скверны, но мы обнаружили, что она способна удерживать огромное количество энергии. Наверное, это самое крупное открытие гоблинов со времен каджа\'мита.$b$bНо что это за субстанция? Откуда она взялась? Почему ее находят только здесь? Наука требует ответов! Мне нужны еще образцы для изучения. Поищи залежи азшарита в ближайших скалах.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 5 образцов азшарита в ближайших скалах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ах, великолепно. Некоторые из этих образцов выглядят свежими. У меня будет достаточно материала, пока я буду пытаться решить эту загадку!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите образцы ассистенту Грили на южную конечную станцию ракетной дороги в Азшаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14371,'Гигантская закуска','Может быть, пока ты бегаешь по скалам, ты $gмог:могла; бы помочь мне с еще одним исследованием? По скалам бродят великаны, они обитают здесь с тех самых времен, когда эти горы только формировались. Может быть, им известно, откуда взялся азшарит? В наших интересах подружиться с этими великанами и узнать ответ.$b$bПодготовь гигантское количество еды, она пригодится, чтобы их задобрить. Поохоться на скальных мокрокрылов, которые так мешают нашим исследованиям, и принеси мне их туши.','Соберите 8 изуродованных туш скальных мокрокрылов.','Фу! Какая вонь! Ну, будем надеяться, что великанам аромат этой кучи туш покажется более соблазнительным.','Вероятно, мне стоило предупредить тебя о том, что мокрокрылы могут стрелять молниями.','Принесите туши ассистентке Грили на южную конечную станцию ракетной дороги в Азшаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гигантская закуска',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Может быть, пока ты бегаешь по скалам, ты $gмог:могла; бы помочь мне с еще одним исследованием? По скалам бродят великаны, они обитают здесь с тех самых времен, когда эти горы только формировались. Может быть, им известно, откуда взялся азшарит? В наших интересах подружиться с этими великанами и узнать ответ.$b$bПодготовь гигантское количество еды, она пригодится, чтобы их задобрить. Поохоться на скальных мокрокрылов, которые так мешают нашим исследованиям, и принеси мне их туши.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 изуродованных туш скальных мокрокрылов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Фу! Какая вонь! Ну, будем надеяться, что великанам аромат этой кучи туш покажется более соблазнительным.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вероятно, мне стоило предупредить тебя о том, что мокрокрылы могут стрелять молниями.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите туши ассистентке Грили на южную конечную станцию ракетной дороги в Азшаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (14372,'Лагерь Таргада','Радует, что ты до сих пор $gжив:жива;, $n. Мне сообщили, что активность демонов на юге увеличилась.$B$BНа границе есть лагерь, который окажется отрезанным, если демоны двинутся на север.$B$BМожет, ты сможешь помочь?$B$BЯ знаю, что лагерем руководит Таргад. Он скажет, что нужно делать.$B$BСпасибо, друг. Удачи.','Карнум Ткач Болот хочет, чтобы вы поговорили с Таргадом.','Демоны?$B$BО, о демонах я тебе много могу рассказать!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лагерь Таргада',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Радует, что ты до сих пор $gжив:жива;, $n. Мне сообщили, что активность демонов на юге увеличилась.$B$BНа границе есть лагерь, который окажется отрезанным, если демоны двинутся на север.$B$BМожет, ты сможешь помочь?$B$BЯ знаю, что лагерем руководит Таргад. Он скажет, что нужно делать.$B$BСпасибо, друг. Удачи.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Карнум Ткач Болот хочет, чтобы вы поговорили с Таргадом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Демоны?$B$BО, о демонах я тебе много могу рассказать!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (14373,'Вторжение демонов','Слушай сюда. И смотри сюда.$B$B<Таргад указывает на восток.>$B$BВидишь большие зеленые светящиеся шары, что падают с неба?$B$BЭто кучка демонов, которые беспрепятственно шарятся по этим землям. Ну, почти беспрепятственно... я им постоянно хвосты накручиваю, чтоб не зарывались.$B$BТы как насчет того, чтобы продолжить это дело?','Уничтожьте 10 младших инферналов.','Ну, дружок!$B$BНе бойся еще парочку уложить для профилактики!','Вернитесь к Таргаду в Лагерь Таргада, что в Пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вторжение демонов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слушай сюда. И смотри сюда.$B$B<Таргад указывает на восток.>$B$BВидишь большие зеленые светящиеся шары, что падают с неба?$B$BЭто кучка демонов, которые беспрепятственно шарятся по этим землям. Ну, почти беспрепятственно... я им постоянно хвосты накручиваю, чтоб не зарывались.$B$BТы как насчет того, чтобы продолжить это дело?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 10 младших инферналов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну, дружок!$B$BНе бойся еще парочку уложить для профилактики!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Таргаду в Лагерь Таргада, что в Пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (14375,'Последняя капля человечности','Я тебя вытащу, $n. Я тебе приготовил такую дозу, что хватит свалить лошадь, но я знаю, что делаю. Я знаю, из какого теста ты $gсделан:сделана;. Ты выдержишь, и все будет хорошо.$b$bВерь мне, $n. Я понимаю, через что тебе придется пройти...$b$bА теперь выпей это и закрой глаза.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Последняя капля человечности',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я тебя вытащу, $n. Я тебе приготовил такую дозу, что хватит свалить лошадь, но я знаю, что делаю. Я знаю, из какого теста ты $gсделан:сделана;. Ты выдержишь, и все будет хорошо.$b$bВерь мне, $n. Я понимаю, через что тебе придется пройти...$b$bА теперь выпей это и закрой глаза.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (14376,'Уничтожение Джукгара','Вы узнаете в этом сущность призванного демона.$B$BОпасные потоки неведанной энергии струятся по ее поверхности.$B$BВы смотрите на сущность и вам является видение, в котором вы контролируете демонов. Вас охватывет восторг, когда вы понимаете, какая огромная сила находится в ваших руках.$B$BВы погружаетесь в размышления о том, как можно использовать это сокровище против демона...','Используйте источник мощи преисподней, чтобы взять под контроль лорда Азретока у алтаря Джукгара и использовать его силы для убийства Джугкара Грим\'рода.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уничтожение Джукгара',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы узнаете в этом сущность призванного демона.$B$BОпасные потоки неведанной энергии струятся по ее поверхности.$B$BВы смотрите на сущность и вам является видение, в котором вы контролируете демонов. Вас охватывет восторг, когда вы понимаете, какая огромная сила находится в ваших руках.$B$BВы погружаетесь в размышления о том, как можно использовать это сокровище против демона...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте источник мощи преисподней, чтобы взять под контроль лорда Азретока у алтаря Джукгара и использовать его силы для убийства Джугкара Грим\'рода.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (14377,'Дружба с великанами','При поверхностном изучении образцов азшарита, которые ты мне $gпринес:принесла;, выяснилось, что его природа и форма – не биологические. Подобными же свойствами в Азшаре обладают великаны, которые бродят по этим скалам.$b$bКажется, что один из них не против помочь нам в наших исследованиях. Отнеси собранное тобой мясо Гормунгану, его можно найти к западу отсюда. Подружись с ним, а потом расспроси – выясни, знает ли он секрет азшарита!','Поговорите с Гормунганом у южной конечной станции ракетной дороги и узнайте секрет азшарита.','Помедленнее – так что ты говоришь? Я правильно тебя поняла? Все эти отложения азшарита образовались там, где великаны… о боже. Омерзительно! Давай не будем говорить об этом Дреку, он ведь считает это делом своей жизни.$B$BНу ладно, по крайней мере мы теперь знаем, откуда берется азшарит, и почему его так немного. Надо придумать способ увеличить его, гм, "производство".','Вернитесь к ассистентке Грили на южную конечную станцию ракетной дороги в Азшаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дружба с великанами',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','При поверхностном изучении образцов азшарита, которые ты мне $gпринес:принесла;, выяснилось, что его природа и форма – не биологические. Подобными же свойствами в Азшаре обладают великаны, которые бродят по этим скалам.$b$bКажется, что один из них не против помочь нам в наших исследованиях. Отнеси собранное тобой мясо Гормунгану, его можно найти к западу отсюда. Подружись с ним, а потом расспроси – выясни, знает ли он секрет азшарита!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Гормунганом у южной конечной станции ракетной дороги и узнайте секрет азшарита.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Помедленнее – так что ты говоришь? Я правильно тебя поняла? Все эти отложения азшарита образовались там, где великаны… о боже. Омерзительно! Давай не будем говорить об этом Дреку, он ведь считает это делом своей жизни.$B$BНу ладно, по крайней мере мы теперь знаем, откуда берется азшарит, и почему его так немного. Надо придумать способ увеличить его, гм, "производство".',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ассистентке Грили на южную конечную станцию ракетной дороги в Азшаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (14378,'Охота на Брендола','Отыщите сумку Брендола.','Вернитесь к Таргаду в Лагерь Таргада, что в Пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота на Брендола',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщите сумку Брендола.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Таргаду в Лагерь Таргада, что в Пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (14379,'Удар по лобстудару!','Таргад не знает ни сна, ни отдыха, охотясь за древними реликвиями Титанов. Он настолько занят, что если бы не я, он бы забывал есть!$B$BКстати, я бы хотела приготовить ему что-нибудь особенное. Может, ты мне поможешь?$B$BЛобстудары бродят по берегу на западе. Я бы никогда не смогла противостоять им в бою, но смогу сделать прекрасный обед, если ты мне принесешь немного их хвостов!','Достаньте 7 сочных хвостов лобстудара.','О-о-о-о, годится-годится!$B$BТаргад будет так удивлен!','Вернитесь к Думти в Лагерь Таргада, что в Пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Удар по лобстудару!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Таргад не знает ни сна, ни отдыха, охотясь за древними реликвиями Титанов. Он настолько занят, что если бы не я, он бы забывал есть!$B$BКстати, я бы хотела приготовить ему что-нибудь особенное. Может, ты мне поможешь?$B$BЛобстудары бродят по берегу на западе. Я бы никогда не смогла противостоять им в бою, но смогу сделать прекрасный обед, если ты мне принесешь немного их хвостов!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Достаньте 7 сочных хвостов лобстудара.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О-о-о-о, годится-годится!$B$BТаргад будет так удивлен!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Думти в Лагерь Таргада, что в Пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (14380,'Впечатляющее открытие','<Таргад обыскивает сумку и вынимает интересную вещичку.>$B$BА вот это странно... это полый рог кодо с каким-то зельем внутри.$B$B<Таргад нюхает зелье.>$B$BФУУУ! Уж точно не какой-нибудь хороший эликсир. Эта штука создана для одной цели... для убийства.$B$BКак насчет того, чтобы пойти к Карнуму и посмотреть, что он скажет...','Отнесите странное зелье Карнуму на Просеку Карнума.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Впечатляющее открытие',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Таргад обыскивает сумку и вынимает интересную вещичку.>$B$BА вот это странно... это полый рог кодо с каким-то зельем внутри.$B$B<Таргад нюхает зелье.>$B$BФУУУ! Уж точно не какой-нибудь хороший эликсир. Эта штука создана для одной цели... для убийства.$B$BКак насчет того, чтобы пойти к Карнуму и посмотреть, что он скажет...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите странное зелье Карнуму на Просеку Карнума.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (14381,'Очищение нашей расселины','О, я узнаю это творение зла. Это зелье вызывает ужасную болезнь, которая убивает почти мгновенно и очень жестоко. Хоть я и ненавижу применять подобные средства, боюсь, выбора у нас нет.$B$BКак ты наверняка знаешь, наги являются серьезной угрозой для региона. Пришло время прогнать их обратно в море!$B$BКогда будешь $gготов:готова;, Жутекрыл доставит тебя к расселине, где они готовят яростную атаку.$B$BИспользуй зелье на нагах и их союзниках, чтобы обезопасить Пустоши!','Убейте 10 захватчиков и 10 сирен из клана Скользящего Плавника, а также трех морских великанов при помощи зелья Маурина.','Вернитесь к Карнуму Ткачу Болот, находящемуся на Просеке Карнума в Пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Очищение нашей расселины',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','О, я узнаю это творение зла. Это зелье вызывает ужасную болезнь, которая убивает почти мгновенно и очень жестоко. Хоть я и ненавижу применять подобные средства, боюсь, выбора у нас нет.$B$BКак ты наверняка знаешь, наги являются серьезной угрозой для региона. Пришло время прогнать их обратно в море!$B$BКогда будешь $gготов:готова;, Жутекрыл доставит тебя к расселине, где они готовят яростную атаку.$B$BИспользуй зелье на нагах и их союзниках, чтобы обезопасить Пустоши!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 захватчиков и 10 сирен из клана Скользящего Плавника, а также трех морских великанов при помощи зелья Маурина.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Карнуму Ткачу Болот, находящемуся на Просеке Карнума в Пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (14382,'Двое у моря','Надо сказать, эти катапульты Отрекшихся выбили из нас всю отвагу, $n. Даже если мы с ними справимся – в порту стоят два корабля с заряженными пушками, нацеленными прямо на нас.$B$BНо у меня есть план, как убить двух зайцев одним выстрелом. Роль выстрела придется исполнить тебе.$B$BТы убьешь катапультчиков, а потом нацелишь орудия на корабли Отрекшихся и отправишь себя в полет. Не бойся, если ты хорошо прицелишься, то приземлишься прямо на палубу. Как только окажешься на месте, не мешкай, спускайся в трюм и перережь глотки капитанам кораблей. Удачи, |3-6($c).','Воспользуйтесь катапультой Отрекшихся, чтобы попасть на корабли и убить капитанов – Морриса и Ансона.','Вернитесь к лорду Годфри в подвал Фермы Аллена, что в Гилнеасе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Двое у моря',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Надо сказать, эти катапульты Отрекшихся выбили из нас всю отвагу, $n. Даже если мы с ними справимся – в порту стоят два корабля с заряженными пушками, нацеленными прямо на нас.$B$BНо у меня есть план, как убить двух зайцев одним выстрелом. Роль выстрела придется исполнить тебе.$B$BТы убьешь катапультчиков, а потом нацелишь орудия на корабли Отрекшихся и отправишь себя в полет. Не бойся, если ты хорошо прицелишься, то приземлишься прямо на палубу. Как только окажешься на месте, не мешкай, спускайся в трюм и перережь глотки капитанам кораблей. Удачи, |3-6($c).',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь катапультой Отрекшихся, чтобы попасть на корабли и убить капитанов – Морриса и Ансона.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лорду Годфри в подвал Фермы Аллена, что в Гилнеасе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (14383,'Ужасные механики Опустошенного берега','Негодяи! Нечестивцы! С самого начала моей операции в Азшаре семейка Прибамбасов мешает моей работе и срывает мои исследования. А теперь еще и толпа второсортных механиков примчалась к ним на помощь. Так что у меня есть важное дело: принять меры, чтобы с этими гномами было покончено навсегда.$b$bОтправляйся на Опустошенный берег, который находится южнее моей секретной лаборатории, и прикати мне несколько их непропорционально огромных голов.','Убейте Бингема Прибамбаса на Опустошенном берегу, а вместе с ним 4 гномов с сетеметами и 6 гномов с шокерами.','О, чудесно. Расскажи подробнее. А этот не по годам развитый юный Прибамбас? Тоже убит? Ах, прекрасно. Моя работа очень важная, но иногда я скучаю по процессу уничтожения врагов на более персональном уровне. Вот, возможно тебе пригодится что-то из моего старого оборудования.','Вернитесь к Хобарту Дреку на южную конечную станцию ракетной дороги в Азшаре.','Угроза с усами.','Бингем Прибамбас') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ужасные механики Опустошенного берега',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Негодяи! Нечестивцы! С самого начала моей операции в Азшаре семейка Прибамбасов мешает моей работе и срывает мои исследования. А теперь еще и толпа второсортных механиков примчалась к ним на помощь. Так что у меня есть важное дело: принять меры, чтобы с этими гномами было покончено навсегда.$b$bОтправляйся на Опустошенный берег, который находится южнее моей секретной лаборатории, и прикати мне несколько их непропорционально огромных голов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Бингема Прибамбаса на Опустошенном берегу, а вместе с ним 4 гномов с сетеметами и 6 гномов с шокерами.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, чудесно. Расскажи подробнее. А этот не по годам развитый юный Прибамбас? Тоже убит? Ах, прекрасно. Моя работа очень важная, но иногда я скучаю по процессу уничтожения врагов на более персональном уровне. Вот, возможно тебе пригодится что-то из моего старого оборудования.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хобарту Дреку на южную конечную станцию ракетной дороги в Азшаре.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Угроза с усами.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Бингем Прибамбас',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (14384,'Изменение маршрута!','Смирно!$B$BИменем стражи Высоты Найджела мне приказано отсылать всех способных держать оружие союзников прямо к капралу Мелкису.$B$BУ меня нет полномочий предоставлять какую-либо другую информацию.$B$BЯ могу предложить лишь услуги транспортировки. Можешь использовать моего грифона. Он тебя доставит, куда нужно.$B$BВольно.','Офицер Дженки хочет, чтобы вы, используя ее грифона, добрались до Высоты Найджела и поговорили с капралом Мелкисом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Изменение маршрута!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Смирно!$B$BИменем стражи Высоты Найджела мне приказано отсылать всех способных держать оружие союзников прямо к капралу Мелкису.$B$BУ меня нет полномочий предоставлять какую-либо другую информацию.$B$BЯ могу предложить лишь услуги транспортировки. Можешь использовать моего грифона. Он тебя доставит, куда нужно.$B$BВольно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Офицер Дженки хочет, чтобы вы, используя ее грифона, добрались до Высоты Найджела и поговорили с капралом Мелкисом.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14385,'Первый эксперимент с азшаритом','В общем, я знаю только один верный способ заставить великана мчаться в уборную, но тебе он не понравится. Нам нужно большое количество... слабительного. Погоди! Может быть, гномы занимаются тем же самым? Это же не может быть простым совпадением. Интересно, что они пытаются здесь провернуть?$b$bНаша разведка сообщает, что в башню Прибамбасов, что на берегу южнее секретной лаборатории, доставляли слабительное. Достань это слабительное и скорми его Гормунгану!','Заберите гигантскую порцию слабительного из башни гномов на Опустошенном берегу. Попытайтесь накормить слабительным великана Гормунгана.','Что, не прошло? В буквальном смысле слова? Гм, Дрека такой ответ не устроит. Надо придумать что-то еще.$B$BМожет быть мои практиканты подбросят это слабительное в лагерь ночных эльфов? По крайней мере посмеемся.','Теперь у тебя есть слабительное, попытайся накормить им Гормунгана. И дай ему журнальчик или что-нибудь вроде того. Сделай это для науки!','Сообщите о результатах ассистентке Грили на южной конечной станции ракетной дороги в Азшаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Первый эксперимент с азшаритом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В общем, я знаю только один верный способ заставить великана мчаться в уборную, но тебе он не понравится. Нам нужно большое количество... слабительного. Погоди! Может быть, гномы занимаются тем же самым? Это же не может быть простым совпадением. Интересно, что они пытаются здесь провернуть?$b$bНаша разведка сообщает, что в башню Прибамбасов, что на берегу южнее секретной лаборатории, доставляли слабительное. Достань это слабительное и скорми его Гормунгану!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заберите гигантскую порцию слабительного из башни гномов на Опустошенном берегу. Попытайтесь накормить слабительным великана Гормунгана.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что, не прошло? В буквальном смысле слова? Гм, Дрека такой ответ не устроит. Надо придумать что-то еще.$B$BМожет быть мои практиканты подбросят это слабительное в лагерь ночных эльфов? По крайней мере посмеемся.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Теперь у тебя есть слабительное, попытайся накормить им Гормунгана. И дай ему журнальчик или что-нибудь вроде того. Сделай это для науки!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Сообщите о результатах ассистентке Грили на южной конечной станции ракетной дороги в Азшаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (14386,'Вожак стаи','Выследите темного следопыта Тиалу и убейте ее с помощью мастифов.','Вернитесь к лорду Годфри в подвал Фермы Аллена, что в Гилнеасе.','Не забудь про свисток!','Темный следопыт Тиала') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вожак стаи',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выследите темного следопыта Тиалу и убейте ее с помощью мастифов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лорду Годфри в подвал Фермы Аллена, что в Гилнеасе.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Не забудь про свисток!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Темный следопыт Тиала',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (14387,'Дела на местности','Да, да. Добро пожаловать в Пустоши, |3-6($r).$B$BПрощу прощения за настойчивость, но у нас маленький аванпост и большие проблемы, многие из которых нужно быстро решить.$B$BОпустим формальности. Нам нужна любая помощь.$B$BДля начала, наш друг Валлариэль стал каким-то беспокойным и настаивает, чтобы мы отправили кого-то обследовать руины на востоке.$B$BПочему бы тебе $gсамому:самой; не поговорить с ним...','Капитан Пентигаст хочет, чтобы вы поговорили с Валлариэлем в Высоте Найджела.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дела на местности',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Да, да. Добро пожаловать в Пустоши, |3-6($r).$B$BПрощу прощения за настойчивость, но у нас маленький аванпост и большие проблемы, многие из которых нужно быстро решить.$B$BОпустим формальности. Нам нужна любая помощь.$B$BДля начала, наш друг Валлариэль стал каким-то беспокойным и настаивает, чтобы мы отправили кого-то обследовать руины на востоке.$B$BПочему бы тебе $gсамому:самой; не поговорить с ним...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Капитан Пентигаст хочет, чтобы вы поговорили с Валлариэлем в Высоте Найджела.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (14388,'Второй эксперимент с азшаритом','Окей, новый план. Мы его НАПУГАЕМ! Жизненный опыт мне подсказывает, что самые большие существа обычно боятся маленьких – например, крыс. Гм. Крыс-то тут полно, а вот как уговорить их навестить великана?$b$bЭй! А ты ведь не против, чтобы я разобрала тебя на клетки и собрала заново? Больно будет только в начале. Я могу уменьшить тебя до размера крысы, а ты оседлаешь одну из них, как лошадь. Это настолько безумно, что не может не сработать! Когда будешь $gготов:готова; к уменьшению, скажи...','Сообщите ассистентке Грили, что вы готовы быть $gуменьшенным:уменьшенной; до размера крысы. Затем оседлайте крысу ракетной дороги и воспользуйтесь ею, чтобы напугать великана Гормунгана.','То есть, испуг тоже не помог? Черт побери! Придется сообщить Дреку неприятные новости: азшарит так и останется самой редкой субстанцией на планете. Надо использовать его экономно.','Сообщите о результатах ассистентке Грили на южной конечной станции ракетной дороги в Азшаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Второй эксперимент с азшаритом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Окей, новый план. Мы его НАПУГАЕМ! Жизненный опыт мне подсказывает, что самые большие существа обычно боятся маленьких – например, крыс. Гм. Крыс-то тут полно, а вот как уговорить их навестить великана?$b$bЭй! А ты ведь не против, чтобы я разобрала тебя на клетки и собрала заново? Больно будет только в начале. Я могу уменьшить тебя до размера крысы, а ты оседлаешь одну из них, как лошадь. Это настолько безумно, что не может не сработать! Когда будешь $gготов:готова; к уменьшению, скажи...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сообщите ассистентке Грили, что вы готовы быть $gуменьшенным:уменьшенной; до размера крысы. Затем оседлайте крысу ракетной дороги и воспользуйтесь ею, чтобы напугать великана Гормунгана.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','То есть, испуг тоже не помог? Черт побери! Придется сообщить Дреку неприятные новости: азшарит так и останется самой редкой субстанцией на планете. Надо использовать его экономно.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Сообщите о результатах ассистентке Грили на южной конечной станции ракетной дороги в Азшаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`endtext_loc8`) VALUES (14389,'Разве не очевидно?','Азурегос! Да, конечно. Беспокойный старый дракон, но с добрым сердцем. Нападения бродяг в течение всех этих лет не пошли ему на пользу. Теперь он со странностями.$b$bНе так давно, в очередной раз возвращаясь от Анары, нашей местной целительницы душ, я заметила, что Азурегос к ней неровно дышит. Думаю, он и сейчас у нее.$b$bПортал за моей спиной – самый быстрый способ добраться туда. Правда, он немного жжется.','Найдите Анару и, возможно, Азурегоса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разве не очевидно?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Азурегос! Да, конечно. Беспокойный старый дракон, но с добрым сердцем. Нападения бродяг в течение всех этих лет не пошли ему на пользу. Теперь он со странностями.$b$bНе так давно, в очередной раз возвращаясь от Анары, нашей местной целительницы душ, я заметила, что Азурегос к ней неровно дышит. Думаю, он и сейчас у нее.$b$bПортал за моей спиной – самый быстрый способ добраться туда. Правда, он немного жжется.',`details_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Найдите Анару и, возможно, Азурегоса.',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`) VALUES (14390,'Когда легко – скучно','После долгих поисков со множеством затруднений вы наконец нашли Азурегоса.$b$bТеперь осталось только уговорить его встретиться с Калесгосом и положить конец исходящей от черных драконов угрозе в Азшаре.','Убедите Азурегоса прекратить отшельничество и встретиться с Калесгосом.','Убедите Азурегоса встретиться с Калесгосом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Когда легко – скучно',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','После долгих поисков со множеством затруднений вы наконец нашли Азурегоса.$b$bТеперь осталось только уговорить его встретиться с Калесгосом и положить конец исходящей от черных драконов угрозе в Азшаре.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убедите Азурегоса прекратить отшельничество и встретиться с Калесгосом.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Убедите Азурегоса встретиться с Калесгосом.',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (14391,'Смена ролей','Азурегос и Калесгос должны встретиться на северной конечной станции ракетной дороги. Вы тоже должны быть там, чтобы убедиться, что Калесгосу не потребуется дополнительная помощь.$b$bВ случае смерти поможет Анара.','Поговорите с Анарой, чтобы вернуться в мир живых, а затем встретьтесь с Калесгосом на северной конечной станции ракетной дороги.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Смена ролей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Азурегос и Калесгос должны встретиться на северной конечной станции ракетной дороги. Вы тоже должны быть там, чтобы убедиться, что Калесгосу не потребуется дополнительная помощь.$b$bВ случае смерти поможет Анара.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Анарой, чтобы вернуться в мир живых, а затем встретьтесь с Калесгосом на северной конечной станции ракетной дороги.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (14392,'Прощай, рыбка','Спасибо, $gмалыш:малышка;.$b$bКак порой просто потерять голову от любви и забыть обо всем, даже если ты дракон. Но теперь я собираюсь снова посвятить себя тому, чтобы Кейлек никогда не смог занять место Малигоса. Нельзя придумать дело благороднее этого.$b$bОтправляйся обратно в гавань. Думаю, там тебя ждут.$b$bСмотри, чтобы по пути тебя не раздавили и не съели.','Привет… еще раз.$B$BСлушай, я давал тебе свою шляпу. Это был подарок. Я думал, ты найдешь ей применение. Точнее, я надеялся, что ты унесешь ее подальше от меня.$B$BМожешь представить себе мое удивление, когда явился Ксилем собственной персоной и отдал ее мне обратно? "Хочешь больше походить на моих учеников, Сората? Дай своей шляпе второй шанс." Не самые приятные минуты.$B$BТак о чем это я... Неужели ты просто выбросил ее, дав ему возможность ее найти? Нет. Вряд ли. Ты возьмешь эту шляпу и ты ее полюбишь. Да.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прощай, рыбка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Спасибо, $gмалыш:малышка;.$b$bКак порой просто потерять голову от любви и забыть обо всем, даже если ты дракон. Но теперь я собираюсь снова посвятить себя тому, чтобы Кейлек никогда не смог занять место Малигоса. Нельзя придумать дело благороднее этого.$b$bОтправляйся обратно в гавань. Думаю, там тебя ждут.$b$bСмотри, чтобы по пути тебя не раздавили и не съели.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Привет… еще раз.$B$BСлушай, я давал тебе свою шляпу. Это был подарок. Я думал, ты найдешь ей применение. Точнее, я надеялся, что ты унесешь ее подальше от меня.$B$BМожешь представить себе мое удивление, когда явился Ксилем собственной персоной и отдал ее мне обратно? "Хочешь больше походить на моих учеников, Сората? Дай своей шляпе второй шанс." Не самые приятные минуты.$B$BТак о чем это я... Неужели ты просто выбросил ее, дав ему возможность ее найти? Нет. Вряд ли. Ты возьмешь эту шляпу и ты ее полюбишь. Да.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (14393,'В бой!','Много поколений кланы кентавров сражались друг с другом, но теперь с этим покончено.$B$BБлагодаря тебе мы вместе сражаемся против общего врага. Или мы отвоюем земли наших предков, или умрем братьями.$B$BА ты, $n?$B$BТы $gзаслужил:заслужила; право сражаться вместе с нами. Я дам тебе группу лучших кентавров, чтобы ты $gповел:повела; их в бой.$B$B$gГотов:Готова; ли ты к битве?','Хан Ле\'прах хочет, чтобы вы убили 15 чернокнижников из клана Пылающего Клинка, 3 стражей ужаса–захватчиков и жрицу Тан\'дариссу.$B$BПоговорите с ханом Ле\'прахом, чтобы вступить в бой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В бой!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Много поколений кланы кентавров сражались друг с другом, но теперь с этим покончено.$B$BБлагодаря тебе мы вместе сражаемся против общего врага. Или мы отвоюем земли наших предков, или умрем братьями.$B$BА ты, $n?$B$BТы $gзаслужил:заслужила; право сражаться вместе с нами. Я дам тебе группу лучших кентавров, чтобы ты $gповел:повела; их в бой.$B$B$gГотов:Готова; ли ты к битве?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Хан Ле\'прах хочет, чтобы вы убили 15 чернокнижников из клана Пылающего Клинка, 3 стражей ужаса–захватчиков и жрицу Тан\'дариссу.$B$BПоговорите с ханом Ле\'прахом, чтобы вступить в бой.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (14394,'Смерть Агогридону!','Мы уже почти у цели, $n!$B$BЕсли сейчас устранить вождя армии демонов, это сломит их боевой дух. И если у нас все получится, Пустоши будут наши!$B$BТеперь, что требуется от тебя: проведи отряд кентавров на юг по ущелью, в лощину Тьмы. Узнай, где скрывается Агогридон!$B$BЯ соберу остальных вождей и приведу их туда, чтобы тебе не пришлось драться с ним в одиночку.','Убейте Агогридона.','Агогридона больше нет.$B$BДемоны уже никогда не захватят наши земли!','Поговорите с ханом Ле\'прахом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Смерть Агогридону!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы уже почти у цели, $n!$B$BЕсли сейчас устранить вождя армии демонов, это сломит их боевой дух. И если у нас все получится, Пустоши будут наши!$B$BТеперь, что требуется от тебя: проведи отряд кентавров на юг по ущелью, в лощину Тьмы. Узнай, где скрывается Агогридон!$B$BЯ соберу остальных вождей и приведу их туда, чтобы тебе не пришлось драться с ним в одиночку.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Агогридона.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Агогридона больше нет.$B$BДемоны уже никогда не захватят наши земли!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с ханом Ле\'прахом.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (14395,'Слушая наше дыхание','$n! Я как раз направлялся сюда, когда все это случилось. $B$BНельзя тратить ни минуты. Большая часть городской стражи была на том участке земли, который обвалился в воду.$B$BМы должны как можно скорее вытащить ребят на берег, и там им окажут всю возможную помощь.','Cпасите 4 утопающих стражей.','Вернитесь к принцу Лиаму Седогриву. Он ждет вас на Ферме Аллена, что в Гилнеасе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Слушая наше дыхание',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n! Я как раз направлялся сюда, когда все это случилось. $B$BНельзя тратить ни минуты. Большая часть городской стражи была на том участке земли, который обвалился в воду.$B$BМы должны как можно скорее вытащить ребят на берег, и там им окажут всю возможную помощь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Cпасите 4 утопающих стражей.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к принцу Лиаму Седогриву. Он ждет вас на Ферме Аллена, что в Гилнеасе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (14396,'И земля содрогнулась','Это еще что за напасть, $n?$B$BНепохоже на очередной пушечный залп...$B$BНу-ка, выберись на поверхность и выясни, что там происходит.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','И земля содрогнулась',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это еще что за напасть, $n?$B$BНепохоже на очередной пушечный залп...$B$BНу-ка, выберись на поверхность и выясни, что там происходит.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (14397,'Эвакуация','Только благодаря слепой удаче нам удалось избежать гибели, $n, но теперь фортуна от нас отвернулась.$B$BПрямо в этот момент приливные волны накрывают побережье, да и земля под нами не кажется мне слишком надежной.$B$BМне самому трудно в это поверить, но нам снова придется убегать... Проклятье, $n. Как можно потерять родину дважды за такой короткий промежуток времени? Но природные катаклизмы – это тот враг, которого нам не одолеть.$B$BСкажи Гвен, пусть готовит людей к эвакуации.','Поговорите с Гвен Армстед в Темной Гавани.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Эвакуация',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Только благодаря слепой удаче нам удалось избежать гибели, $n, но теперь фортуна от нас отвернулась.$B$BПрямо в этот момент приливные волны накрывают побережье, да и земля под нами не кажется мне слишком надежной.$B$BМне самому трудно в это поверить, но нам снова придется убегать... Проклятье, $n. Как можно потерять родину дважды за такой короткий промежуток времени? Но природные катаклизмы – это тот враг, которого нам не одолеть.$B$BСкажи Гвен, пусть готовит людей к эвакуации.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Гвен Армстед в Темной Гавани.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (14398,'Бабуля Валь','Найдите бабулю Валь в ее домике.','А, дорогой гость, добро пожаловать! Не желаешь чашечку чая?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бабуля Валь',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите бабулю Валь в ее домике.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, дорогой гость, добро пожаловать! Не желаешь чашечку чая?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14399,'Девичья память','Уйти? Сейчас?$B$BНу что ж, надо – так надо. $gМилок, будь так любезен:Милочка, будь так любезна;, окажи мне одну услугу.$B$BГде-то тут лежит моя любимая книга, без которой я не могу отправиться в путь. Принеси ее мне, пожалуйста.$B$B<Сколько вы не пытаетесь убедить бабулю в серьезности ситуации и опасности промедления, она только качает головой.>$B$BДорогуша, неужели тебе так трудно просто принести мне книгу?','Найдите завернутую в холст книгу.','Как дела, дорогуша? Не желаешь чашечку чая?','Вернитесь к бабуле Валь в ее домик в Гилнеасе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Девичья память',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Уйти? Сейчас?$B$BНу что ж, надо – так надо. $gМилок, будь так любезен:Милочка, будь так любезна;, окажи мне одну услугу.$B$BГде-то тут лежит моя любимая книга, без которой я не могу отправиться в путь. Принеси ее мне, пожалуйста.$B$B<Сколько вы не пытаетесь убедить бабулю в серьезности ситуации и опасности промедления, она только качает головой.>$B$BДорогуша, неужели тебе так трудно просто принести мне книгу?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите завернутую в холст книгу.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как дела, дорогуша? Не желаешь чашечку чая?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к бабуле Валь в ее домик в Гилнеасе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14400,'Мне нечего надеть!','Что, ты говоришь, происходит?$B$BАх, да... Эвакуация.$B$BНо право же, я не могу выйти из дома в таком виде!$B$B$gБудь добр:Будь добра;, подай мне мое выходное платье. Оно висит на бельевой веревке снаружи.$B$B<Вы пытаетесь убедить бабулю, что она одета вполне прилично, но тщетно.>$B$BАх, ну что за молодежь пошла, никакого понятия о хороших манерах! Можно подумать, тебя воспитывали огры... Так где мое платье, дорогуша?','Принесите бабушкино выходное платье.','Надеюсь, тебе не составило труда разыскать мою одежду?','Вернитесь к бабуле Валь в ее домик в Гилнеасе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мне нечего надеть!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что, ты говоришь, происходит?$B$BАх, да... Эвакуация.$B$BНо право же, я не могу выйти из дома в таком виде!$B$B$gБудь добр:Будь добра;, подай мне мое выходное платье. Оно висит на бельевой веревке снаружи.$B$B<Вы пытаетесь убедить бабулю, что она одета вполне прилично, но тщетно.>$B$BАх, ну что за молодежь пошла, никакого понятия о хороших манерах! Можно подумать, тебя воспитывали огры... Так где мое платье, дорогуша?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите бабушкино выходное платье.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Надеюсь, тебе не составило труда разыскать мою одежду?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к бабуле Валь в ее домик в Гилнеасе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14401,'Любимый кот бабули','Ах, да! Эвакуация...$B$BНо я не могу бросить здесь моего ненаглядного котика! Он такой рыжий, полосатый...$B$BВсе любит играть в сломанной повозке рядом с деревом к северо-востоку отсюда. Быстрее, сбегай за моим дорогим Шансом, и мы отправимся в путь.','Найдите кота Шанса.','Ты такой милый молодой человек, Корольвсех.','Вернитесь к бабуле Валь в ее домик в Гилнеасе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Любимый кот бабули',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ах, да! Эвакуация...$B$BНо я не могу бросить здесь моего ненаглядного котика! Он такой рыжий, полосатый...$B$BВсе любит играть в сломанной повозке рядом с деревом к северо-востоку отсюда. Быстрее, сбегай за моим дорогим Шансом, и мы отправимся в путь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите кота Шанса.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты такой милый молодой человек, Корольвсех.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к бабуле Валь в ее домик в Гилнеасе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (14402,'В путь!','Думаю, теперь я готова отправиться в путь.$B$BМоя любимая книжка и дорогой котик при мне, и одета я – не стыдно людям показаться.$B$BОх, надеюсь, я ничего не забыла!$B$BСкажи этому вашему мэру, что я уже выхожу. Надеюсь, мы еще увидимся в городе!','Поговорите с Гвен Армстед в Темной Гавани.','Без преувеличения, ты совершила невозможное! Ты убедила бабулю Валь выйти из дома.$B$BГоворю тебе, ты – нечто особенное.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В путь!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Думаю, теперь я готова отправиться в путь.$B$BМоя любимая книжка и дорогой котик при мне, и одета я – не стыдно людям показаться.$B$BОх, надеюсь, я ничего не забыла!$B$BСкажи этому вашему мэру, что я уже выхожу. Надеюсь, мы еще увидимся в городе!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Гвен Армстед в Темной Гавани.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Без преувеличения, ты совершила невозможное! Ты убедила бабулю Валь выйти из дома.$B$BГоворю тебе, ты – нечто особенное.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (14403,'Братья Хейварды') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Братья Хейварды',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (14404,'Судно требует ремонта','Говоришь, началась эвакуация? Что ж, мы подумывали о том же, когда на пороге появились Отрекшиеся.$B$BПо-моему, морской путь – самый безопасный, но наши лодки сильно потрепало во время последнего подземного толчка.$B$BЧтобы закончить починку, мне потребуются кое-какие материалы и инструменты. Если ты мне поможешь, мы с братьями сможем быстро уплыть отсюда.','Вернитесь к Себастьяну Хейварду на Рыбное хозяйство Хейварда в Гилнеасе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Судно требует ремонта',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Говоришь, началась эвакуация? Что ж, мы подумывали о том же, когда на пороге появились Отрекшиеся.$B$BПо-моему, морской путь – самый безопасный, но наши лодки сильно потрепало во время последнего подземного толчка.$B$BЧтобы закончить починку, мне потребуются кое-какие материалы и инструменты. Если ты мне поможешь, мы с братьями сможем быстро уплыть отсюда.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Себастьяну Хейварду на Рыбное хозяйство Хейварда в Гилнеасе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (14405,'Спасение в море','Спасибо за помощь, $n. Наш корабль готов к отплытию.$B$BМожешь сказать мисс Армстед, что мы не присоединимся к наземной эвакуации.$B$BМы, Хейварды, всегда были морскими волками. Если уж нам придется покинуть наши дома – мы лучше уйдем в море.','Вернитесь к Гвен Армстед в Темную Гавань.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спасение в море',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Спасибо за помощь, $n. Наш корабль готов к отплытию.$B$BМожешь сказать мисс Армстед, что мы не присоединимся к наземной эвакуации.$B$BМы, Хейварды, всегда были морскими волками. Если уж нам придется покинуть наши дома – мы лучше уйдем в море.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь к Гвен Армстед в Темную Гавань.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (14406,'Сад Краули','Поговорите с Лорной Краули в саду Краули.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сад Краули',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Лорной Краули в саду Краули.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (14407,'Тоска Азшары','Эй! Рада видеть тебя снова.$b$bЯ пришла по поручению моего хозяина, Кейлека. Ему нужна твоя помощь. Как можно скорее найди его в трущобах под мостом!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тоска Азшары',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эй! Рада видеть тебя снова.$b$bЯ пришла по поручению моего хозяина, Кейлека. Ему нужна твоя помощь. Как можно скорее найди его в трущобах под мостом!',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (14408,'План объекта номер 9','Мизерного интеллекта моих благодетелей хватило на то, чтобы построить межпланетный транспорт. Спроектирована эта так называемая "ракета" так, что в голову приходят мысли только о гибели. Но, думаю, небольшая доработка катализаторов топлива позволит создать стабильный состав, побочным продуктом которого будет пригодный для вдыхания кислород. Чтобы произвести такие изменения, мне нужны чертежи ракеты.$b$bБудем надеяться, что они еще не сгорели. Найди архив лаборатории и попытайся проникнуть в него. Чертежи должны быть у самого директора лаборатории, если, конечно, он еще жив.','Найдите чертежи секретной ракеты в здании архива в восточной части лаборатории. Воспользуйтесь дверным звонком и убейте директора лаборатории, когда он появится.','Отнесите чертежи секретной ракеты объекту №9 в секретную лабораторию в Азшаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','План объекта номер 9',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мизерного интеллекта моих благодетелей хватило на то, чтобы построить межпланетный транспорт. Спроектирована эта так называемая "ракета" так, что в голову приходят мысли только о гибели. Но, думаю, небольшая доработка катализаторов топлива позволит создать стабильный состав, побочным продуктом которого будет пригодный для вдыхания кислород. Чтобы произвести такие изменения, мне нужны чертежи ракеты.$b$bБудем надеяться, что они еще не сгорели. Найди архив лаборатории и попытайся проникнуть в него. Чертежи должны быть у самого директора лаборатории, если, конечно, он еще жив.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите чертежи секретной ракеты в здании архива в восточной части лаборатории. Воспользуйтесь дверным звонком и убейте директора лаборатории, когда он появится.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите чертежи секретной ракеты объекту №9 в секретную лабораторию в Азшаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14409,'Осторожное возвращение','Удели мне минутку внимания, |3-6($c).$b$bГрядут большие перемены, и это предчувствие заставило нас покинуть руины Эльдре\'Таласа. Я прибыл сюда для исследования этого города и не могу оторваться от своей работы, но если у тебя есть свободное время, я мог бы дать тебе поручение.$b$bОдин из моих коллег отправился в Дарнас побеседовать с Верховной жрицей – он надеется, что мы сможем найти с ней общий язык. Пожалуйста, отнеси ему этот журнал – он может помочь ему в выполнении дипломатической миссии. Моего коллегу зовут Мордент Вечерняя Тень, и сейчас он находится в храме.','Отнесите журнал Дароса Морденту Вечерней Тени в Дарнас.','Ах, сочинения Дароса. Он всегда внимательно следил за прогрессом. Его слова могут помочь объяснить, как далеко мы зашли.$B$BБлагодарю тебя за это, $R. Возможно, мы еще увидимся, когда поймем, что не хотим причинять вреда.','Кажется, у меня есть время поговорить. По какому поводу это происходит?','Вернитесь к верховному магу Морденту Вечерней Тени в Храмовые сады, что в Дарнасе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Осторожное возвращение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Удели мне минутку внимания, |3-6($c).$b$bГрядут большие перемены, и это предчувствие заставило нас покинуть руины Эльдре\'Таласа. Я прибыл сюда для исследования этого города и не могу оторваться от своей работы, но если у тебя есть свободное время, я мог бы дать тебе поручение.$b$bОдин из моих коллег отправился в Дарнас побеседовать с Верховной жрицей – он надеется, что мы сможем найти с ней общий язык. Пожалуйста, отнеси ему этот журнал – он может помочь ему в выполнении дипломатической миссии. Моего коллегу зовут Мордент Вечерняя Тень, и сейчас он находится в храме.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите журнал Дароса Морденту Вечерней Тени в Дарнас.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ах, сочинения Дароса. Он всегда внимательно следил за прогрессом. Его слова могут помочь объяснить, как далеко мы зашли.$B$BБлагодарю тебя за это, $R. Возможно, мы еще увидимся, когда поймем, что не хотим причинять вреда.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Кажется, у меня есть время поговорить. По какому поводу это происходит?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному магу Морденту Вечерней Тени в Храмовые сады, что в Дарнасе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (14410,'В дебрях Фераласа','Ты храбро $gсражался:сражалась;, охраняя покой этих земель вместе с нами. Если не возражаешь, здесь есть и другие, кому твоя помощь придется весьма кстати.$B$BК югу отсюда лежат нетронутые леса Фераласа. Там, под сенью Двух Колоссов, ты найдешь Теларона Полет Ветра. Он со своими товарищами-друидами из Покоев Дремлющего обнаружил признаки страшного заболевания.$B$BИм понадобится твоя помощь, |3-6($c). Поспеши туда.','Отправляйтесь в Фералас и поговорите с Телароном Полетом Ветра в Покоях Дремлющего.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В дебрях Фераласа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты храбро $gсражался:сражалась;, охраняя покой этих земель вместе с нами. Если не возражаешь, здесь есть и другие, кому твоя помощь придется весьма кстати.$B$BК югу отсюда лежат нетронутые леса Фераласа. Там, под сенью Двух Колоссов, ты найдешь Теларона Полет Ветра. Он со своими товарищами-друидами из Покоев Дремлющего обнаружил признаки страшного заболевания.$B$BИм понадобится твоя помощь, |3-6($c). Поспеши туда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Фералас и поговорите с Телароном Полетом Ветра в Покоях Дремлющего.',`objectives_loc8`);
