INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (14412,'Как в море корабли','Превосходно. Я уже почти закончил.','Вернитесь к Себастьяну Хейварду на Рыбное хозяйство Хейварда в Гилнеасе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Как в море корабли',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Превосходно. Я уже почти закончил.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Себастьяну Хейварду на Рыбное хозяйство Хейварда в Гилнеасе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (14413,'Вершина обучения','Это очень увлекательно! Ты $gхотел:хотела; чего-то интересного? Ты это получишь!$b$bПришло время испытаний... время ТВОИХ испытаний. Много сложных задач надо будет выполнить, многому научиться. Ты многое узнаешь об испытаниях. Я узнаю многое о тебе.$b$bА теперь иди. В мой Волшебный замок. Там мы с тобой, конечно, снова встретимся, потому что я вездесущ.','Поговорите с проекцией верховного мага Ксилема у подножия Волшебного замка.','Так быстро! Надеюсь, прогулка была приятной. Не сильно тошнило?$B$BВпереди еще много бега и прыжков, так что крепкий желудок тебе не помешает.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вершина обучения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это очень увлекательно! Ты $gхотел:хотела; чего-то интересного? Ты это получишь!$b$bПришло время испытаний... время ТВОИХ испытаний. Много сложных задач надо будет выполнить, многому научиться. Ты многое узнаешь об испытаниях. Я узнаю многое о тебе.$b$bА теперь иди. В мой Волшебный замок. Там мы с тобой, конечно, снова встретимся, потому что я вездесущ.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с проекцией верховного мага Ксилема у подножия Волшебного замка.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так быстро! Надеюсь, прогулка была приятной. Не сильно тошнило?$B$BВпереди еще много бега и прыжков, так что крепкий желудок тебе не помешает.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (14414,'Feralas Breadcrumb [PH]','Я еще вырасту до длиного задания! За Фералас!!!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Feralas Breadcrumb [PH]',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я еще вырасту до длиного задания! За Фералас!!!',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (14415,'Призраки в саду','Послушай, $n... Я знаю, что с тобой произошло, но все равно хочу довериться, даже несмотря на постигшую тебя... беду. В конце концов, ведь ты $gбыл:была; с моим отцом до самого конца.$B$BПойми, я не хочу уходить отсюда. Это небезопасно.$B$BВо-первых, землетрясения открыли проход в горах, которым немедленной воспользовались эттины. Мало того, с самого начала моего затворничества в саду бродят какие-то призраки в обличье гигантских волков!$B$BНет, я не сдвинусь с места, пока не пойму, что тут происходит.','Осмотрите сад Краули.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Призраки в саду',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Послушай, $n... Я знаю, что с тобой произошло, но все равно хочу довериться, даже несмотря на постигшую тебя... беду. В конце концов, ведь ты $gбыл:была; с моим отцом до самого конца.$B$BПойми, я не хочу уходить отсюда. Это небезопасно.$B$BВо-первых, землетрясения открыли проход в горах, которым немедленной воспользовались эттины. Мало того, с самого начала моего затворничества в саду бродят какие-то призраки в обличье гигантских волков!$B$BНет, я не сдвинусь с места, пока не пойму, что тут происходит.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Осмотрите сад Краули.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (14416,'Голодный эттин','Послушай, $n, без средств передвижения мы далеко не уйдем.$B$BЕсли мы попробуем уйти на своих двоих, Отрекшиеся мигом нас настигнут.$B$BЕще недавно мне бы не составило труда увести нескольких лошадей из стойл к юго-востоку отсюда, но последнее землетрясение заставило огромного эттина Корота спуститься с гор и искать пропитание в другом месте. Так что если мы в ближайшее время не заберем лошадей, это сделает он.','Приведите 5 горных коней Лорне Краули в сад Краули.','Я позабочусь о том, чтобы эти лошади попали в Темную Гавань.','Вернитесь к Лорне Краули в сад Краули.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Голодный эттин',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Послушай, $n, без средств передвижения мы далеко не уйдем.$B$BЕсли мы попробуем уйти на своих двоих, Отрекшиеся мигом нас настигнут.$B$BЕще недавно мне бы не составило труда увести нескольких лошадей из стойл к юго-востоку отсюда, но последнее землетрясение заставило огромного эттина Корота спуститься с гор и искать пропитание в другом месте. Так что если мы в ближайшее время не заберем лошадей, это сделает он.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Приведите 5 горных коней Лорне Краули в сад Краули.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я позабочусь о том, чтобы эти лошади попали в Темную Гавань.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лорне Краули в сад Краули.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`objectives_loc8`,`completedtext_loc8`) VALUES (14418,'Отнесите гроссбух Андрона Алерику Хоукинсу в Зал Темной Госпожи в Подгороде.','Вернитесь к Алерику Хокинсу на озеро Лордамер, что в Серебряном бору.') ON DUPLICATE KEY UPDATE `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите гроссбух Андрона Алерику Хоукинсу в Зал Темной Госпожи в Подгороде.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Алерику Хокинсу на озеро Лордамер, что в Серебряном бору.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (14419,'Рекомендательное письмо должно убедить Андрона, что ты – тот самый гонец, которого он ждал. Мне приходилось встречаться с Андроном, он не настолько умен, чтобы заподозрить неладное.$b$bНаша госпожа подозревает, что Андрон тайно помогает другой группировке, и тебе предстоит выяснить, какой именно. Хорошо бы также получить доказательства.$b$bПоговори с Андроном и вытяни из него эти сведения. Его можно найти в лавке неподалеку от Района Фармацевтов.','Поговорите с Андроном Гантом в Подгороде.','Вернитесь к Андрону Ганту на озеро Лордамер, что близ Альтеракских гор.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Рекомендательное письмо должно убедить Андрона, что ты – тот самый гонец, которого он ждал. Мне приходилось встречаться с Андроном, он не настолько умен, чтобы заподозрить неладное.$b$bНаша госпожа подозревает, что Андрон тайно помогает другой группировке, и тебе предстоит выяснить, какой именно. Хорошо бы также получить доказательства.$b$bПоговори с Андроном и вытяни из него эти сведения. Его можно найти в лавке неподалеку от Района Фармацевтов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Андроном Гантом в Подгороде.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Андрону Ганту на озеро Лордамер, что близ Альтеракских гор.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`objectives_loc8`,`completedtext_loc8`) VALUES (14420,'Принесите рекомендательное письмо Астора Менниту Каркаду в Квартал Разбойников Подгорода.','Вернитесь к Менниту Каркаду на Руины Лордерона, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите рекомендательное письмо Астора Менниту Каркаду в Квартал Разбойников Подгорода.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Менниту Каркаду на Руины Лордерона, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (14421,'Гроссбух с необходимой твоим нанимателям информацией стоит на книжной полке за моей спиной. Передай его заказчикам вместе с поклоном от меня и сообщи, что, если они оценят полученные сведения и захотят продолжить наше сотрудничество, я предпочел бы иметь дело с тобой.','Отнесите гроссбух Андрона Менниту Каркаду в Квартал Разбойников Подгорода.','Вернитесь к Менниту Каркаду на Руины Лордерона, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Гроссбух с необходимой твоим нанимателям информацией стоит на книжной полке за моей спиной. Передай его заказчикам вместе с поклоном от меня и сообщи, что, если они оценят полученные сведения и захотят продолжить наше сотрудничество, я предпочел бы иметь дело с тобой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите гроссбух Андрона Менниту Каркаду в Квартал Разбойников Подгорода.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Менниту Каркаду на Руины Лордерона, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (14422,'Ракета ящеров','Вскоре после того, как мой интеллект возрос, я воспользовалась объектом №4, чтобы обзавестись потомством и создать уникальную расу сверхумных ящеров. Впоследствии объект №4 стал избегать контактов со мной, и я решила вынуть из него все внутренности в нашу следующую встречу.$b$bТем не менее, в лаборатории осталось достаточно наших детей с отличным наборов генов, подходящим для развития моей расы. Пожалуйста, освободи их из клеток и принеси к ракете.','Освободите из клеток пять экспериментальных ящеров и доставьте их объекту №9 к ракете.','Поговорите с объектом №9 в секретной лаборатории в Азшаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ракета ящеров',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вскоре после того, как мой интеллект возрос, я воспользовалась объектом №4, чтобы обзавестись потомством и создать уникальную расу сверхумных ящеров. Впоследствии объект №4 стал избегать контактов со мной, и я решила вынуть из него все внутренности в нашу следующую встречу.$b$bТем не менее, в лаборатории осталось достаточно наших детей с отличным наборов генов, подходящим для развития моей расы. Пожалуйста, освободи их из клеток и принеси к ракете.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Освободите из клеток пять экспериментальных ящеров и доставьте их объекту №9 к ракете.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с объектом №9 в секретной лаборатории в Азшаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14423,'Бульдозерсизм','...нам нужен жрец!$b$bК счастью, небольшая часть моего бюджета предусматривает освящение техники. Возьми это сигнальное ружье и отправляйся к Марджену, моему несчастному любимому сломанному бульдозеру. Дай сигнал, после чего появится один из наших жрецов-десантников и возьмет ситуацию под свой контроль. Возвращайся, когда о моем бульдозере позаботятся!','Воспользуйтесь освященным сигнальным пистолетом, чтобы призвать жреца на помощь, а затем "изгоните духов" из бульдозера.','Что? Что?..$B$BМарджен! О, мой дорогой Марджен!!','Как дела у Марджена? Снова здоров и весел?','Вернитесь к Дубнику на оргриммарскую пересадочную станцию ракетной дороги в Азшаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бульдозерсизм',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','...нам нужен жрец!$b$bК счастью, небольшая часть моего бюджета предусматривает освящение техники. Возьми это сигнальное ружье и отправляйся к Марджену, моему несчастному любимому сломанному бульдозеру. Дай сигнал, после чего появится один из наших жрецов-десантников и возьмет ситуацию под свой контроль. Возвращайся, когда о моем бульдозере позаботятся!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь освященным сигнальным пистолетом, чтобы призвать жреца на помощь, а затем "изгоните духов" из бульдозера.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что? Что?..$B$BМарджен! О, мой дорогой Марджен!!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как дела у Марджена? Снова здоров и весел?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дубнику на оргриммарскую пересадочную станцию ракетной дороги в Азшаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (14424,'Снова нужна наука','<Дубник утирает слезы, а потом решительно выдвигает вперед подбородок.>$b$bБольше никогда, $n! Ни один бульдозер не заслуживает судьбы моего Марджена. Нам нужно позаботиться о некоторой духонепроницаемости. Это работа для наших лучших ученых, я как раз знаю одну сотрудницу, которой она будет по плечу! Поищи ассистентку Грили на южной конечной станции ракетной дороги. Она администратор всемирно известной секретной лаборатории Азшары и она мне кое-чем обязана.','Найдите ассистентку Грили на южной конечной станции ракетной дороги. Ракетная дорога гоблинов позволяет быстро перемещаться по Азшаре.','О чем там говорит Дубник? Испорченная духами строительная техника? А что, похоже, что у меня есть время на охоту за привидениями?$B$BМоя лаборатория наполовину расплавилась, огонь повсюду, животные мутируют, и – что куда хуже – сроки проектов срываются. Мне самой не помешала бы помощь!','Найдите ассистентку Грили на южной конечной станции ракетной дороги. Ракетная дорога гоблинов позволяет быстро перемещаться по Азшаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Снова нужна наука',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Дубник утирает слезы, а потом решительно выдвигает вперед подбородок.>$b$bБольше никогда, $n! Ни один бульдозер не заслуживает судьбы моего Марджена. Нам нужно позаботиться о некоторой духонепроницаемости. Это работа для наших лучших ученых, я как раз знаю одну сотрудницу, которой она будет по плечу! Поищи ассистентку Грили на южной конечной станции ракетной дороги. Она администратор всемирно известной секретной лаборатории Азшары и она мне кое-чем обязана.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите ассистентку Грили на южной конечной станции ракетной дороги. Ракетная дорога гоблинов позволяет быстро перемещаться по Азшаре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О чем там говорит Дубник? Испорченная духами строительная техника? А что, похоже, что у меня есть время на охоту за привидениями?$B$BМоя лаборатория наполовину расплавилась, огонь повсюду, животные мутируют, и – что куда хуже – сроки проектов срываются. Мне самой не помешала бы помощь!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Найдите ассистентку Грили на южной конечной станции ракетной дороги. Ракетная дорога гоблинов позволяет быстро перемещаться по Азшаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (14425,'The First Quest','Greetings, $n, this is a test. Accept and kill stuff','Test Thrall wants you to kill something.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','The First Quest',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Greetings, $n, this is a test. Accept and kill stuff',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Test Thrall wants you to kill something.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (14426,'The Second Quest','This is the second quest! This time you won\'t have to kill stuff.','Santa Thrall wants you to collect 5 boozles, whatever those are.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','The Second Quest',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','This is the second quest! This time you won\'t have to kill stuff.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Santa Thrall wants you to collect 5 boozles, whatever those are.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (14427,'Item Quest','Item collection quest','Get the items') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Item Quest',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Item collection quest',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Get the items',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (14428,'Записи сказительницы Янтарный Ветер','Если моим источникам можно верить, сказительница Янтарный Ветер предсказывает, что Альянс будет исследовать руины на востоке. Я еще не выяснял, каковы границы ее возможностей: я надеюсь, что ты дашь мне полный отчет, вынудив ее на поединок и убив ее.$b$bРаз она "сказительница", то, наверное, при ней будут записи, в которых будет описано, что затевают эти ночные эльфы. Достань мне эти записи. И необязательно бежать обратно; воспользуйся их же собственными гадальными камнями и свяжись со мной оттуда.','Убейте сказительницу Янтарный Ветер в Лагере дарнасских эльфов и возьмите ее записи.','Воспользуйтесь верхним гадальным камнем в Лагере дарнасских эльфов, чтобы получить дальнейшие инструкции.','Остается надеяться, что у нее есть нужная нам информация.','Сказительница Янтарный Ветер') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Записи сказительницы Янтарный Ветер',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если моим источникам можно верить, сказительница Янтарный Ветер предсказывает, что Альянс будет исследовать руины на востоке. Я еще не выяснял, каковы границы ее возможностей: я надеюсь, что ты дашь мне полный отчет, вынудив ее на поединок и убив ее.$b$bРаз она "сказительница", то, наверное, при ней будут записи, в которых будет описано, что затевают эти ночные эльфы. Достань мне эти записи. И необязательно бежать обратно; воспользуйся их же собственными гадальными камнями и свяжись со мной оттуда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте сказительницу Янтарный Ветер в Лагере дарнасских эльфов и возьмите ее записи.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Воспользуйтесь верхним гадальным камнем в Лагере дарнасских эльфов, чтобы получить дальнейшие инструкции.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Остается надеяться, что у нее есть нужная нам информация.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Сказительница Янтарный Ветер',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (14429,'Разрушение порождений тайной магии','Порождениями тайной магии являются существа, созданные при помощи чистой маны и интеллекта. При правильном использовании порождение позволяет своему владельцу быстро усваивать огромное количество знаний тайной магии. Но порождения опасны, $n. Очень умны! Очень могущественны! И очень чувствительны к внешним злонамеренным воздействиям...$b$bДавай поучим этих любителей и используем против них их же собственную магию. Убей начинающих наставников и исследователей и возьми их рунические камни. Когда закончишь, свяжись со мной при помощи нижнего гадального камня.','Убейте начинающих наставников и начинающих исследователей и соберите 10 настроенных рунических камней.','Воспользуйтесь нижним гадальным камнем в Лагере дарнасских эльфов, чтобы получить дальнейшие инструкции.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разрушение порождений тайной магии',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Порождениями тайной магии являются существа, созданные при помощи чистой маны и интеллекта. При правильном использовании порождение позволяет своему владельцу быстро усваивать огромное количество знаний тайной магии. Но порождения опасны, $n. Очень умны! Очень могущественны! И очень чувствительны к внешним злонамеренным воздействиям...$b$bДавай поучим этих любителей и используем против них их же собственную магию. Убей начинающих наставников и исследователей и возьми их рунические камни. Когда закончишь, свяжись со мной при помощи нижнего гадального камня.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте начинающих наставников и начинающих исследователей и соберите 10 настроенных рунических камней.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Воспользуйтесь нижним гадальным камнем в Лагере дарнасских эльфов, чтобы получить дальнейшие инструкции.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (14430,'Взлом порождений тайной магии','А теперь мы возьмем под контроль их порождения тайной магии и устроим хаос. Ты раньше $gслышал:слышала; о магии такого типа, $n? Нет? Ха! Это делает мой план еще более восхитительным. Поблизости должно находиться огромное порождение тайной магии. Благодаря собранным тобой руническим камням, мы знаем, как с ним общаться. Обратись к нему и скажи: "Аль\'тет к\'толгар". $gПонял:Поняла;? Повтори. Довольно похоже. А потом снова свяжись со мной и расскажи, что происходит!','Обратитесь к порождению тайной магии в Лагере дарнасских эльфов и произнесите магические слова.','Порождение тайной магии взломано','Вернитесь к Андорелу Верному Солнцу на северную пересадочную станцию ракетной дороги в Азшаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Взлом порождений тайной магии',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А теперь мы возьмем под контроль их порождения тайной магии и устроим хаос. Ты раньше $gслышал:слышала; о магии такого типа, $n? Нет? Ха! Это делает мой план еще более восхитительным. Поблизости должно находиться огромное порождение тайной магии. Благодаря собранным тобой руническим камням, мы знаем, как с ним общаться. Обратись к нему и скажи: "Аль\'тет к\'толгар". $gПонял:Поняла;? Повтори. Довольно похоже. А потом снова свяжись со мной и расскажи, что происходит!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обратитесь к порождению тайной магии в Лагере дарнасских эльфов и произнесите магические слова.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Порождение тайной магии взломано',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Андорелу Верному Солнцу на северную пересадочную станцию ракетной дороги в Азшаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (14431,'Овраг Черночревов','С тех пор, как мы обосновались в Азшаре, фурболги из племени Черночревов, которые живут в этих краях, отделились от своих собратьев Древобрюхов. Они стали дикими, |3-6($c), и то и дело нападают на наших воинов. Хуже того, мы видели, что они на дружеской ноге с ночными эльфами с Талрендис. Мы не можем допустить, чтобы они стали союзниками!$b$bК юго-западу отсюда ты найдешь большой овраг, где, как сообщают мои разведчики, ночные эльфы особенно активны. Убей их и собери всю оперативную информацию, какую найдешь.','Убейте 8 биологов с заставы Талрендис, обыщите одно из тел и заберите оперативную информацию Черночревов.','Отнесите оперативную информацию Хаггруму Кровопалу на северную пересадочную станцию ракетной дороги в Азшаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Овраг Черночревов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','С тех пор, как мы обосновались в Азшаре, фурболги из племени Черночревов, которые живут в этих краях, отделились от своих собратьев Древобрюхов. Они стали дикими, |3-6($c), и то и дело нападают на наших воинов. Хуже того, мы видели, что они на дружеской ноге с ночными эльфами с Талрендис. Мы не можем допустить, чтобы они стали союзниками!$b$bК юго-западу отсюда ты найдешь большой овраг, где, как сообщают мои разведчики, ночные эльфы особенно активны. Убей их и собери всю оперативную информацию, какую найдешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 биологов с заставы Талрендис, обыщите одно из тел и заберите оперативную информацию Черночревов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите оперативную информацию Хаггруму Кровопалу на северную пересадочную станцию ракетной дороги в Азшаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14432,'Отвар из древовидного вереска','Прекрасно, этого достаточно. Мы вскипятим все это, и ты сможешь насладиться ароматом, а потом вмиг заговоришь, как фурболг. Детали нашего плана прорисовываются…','Как дела? Я сам пробовал как-то эти травки, но они были слишком горькие, даже для такого обладателя луженого желудка, как я.','Вернитесь к Хаггруму Кровопалу на северную пересадочную станцию ракетной дороги в Азшаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отвар из древовидного вереска',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно, этого достаточно. Мы вскипятим все это, и ты сможешь насладиться ароматом, а потом вмиг заговоришь, как фурболг. Детали нашего плана прорисовываются…',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как дела? Я сам пробовал как-то эти травки, но они были слишком горькие, даже для такого обладателя луженого желудка, как я.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хаггруму Кровопалу на северную пересадочную станцию ракетной дороги в Азшаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (14433,'Обратная сторона дипломатии','Отлично сработано! Дай мне взглянуть на эти документы. Хм. Теперь мы точно знаем место и время проведения окончательных переговоров. Не переживай, если одеяния тебе малы или велики – я все устрою.','Принесите одеяния и план встречи Хаггруму Кровопалу на северную пересадочную станцию ракетной дороги в Азшаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обратная сторона дипломатии',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично сработано! Дай мне взглянуть на эти документы. Хм. Теперь мы точно знаем место и время проведения окончательных переговоров. Не переживай, если одеяния тебе малы или велики – я все устрою.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите одеяния и план встречи Хаггруму Кровопалу на северную пересадочную станцию ракетной дороги в Азшаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (14434,'Деревня Рут\'теран') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Деревня Рут\'теран',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (14435,'Обман Черночревов','Вернитесь к Хаггруму Кровопалу на северную пересадочную станцию ракетной дороги в Азшаре.','Думаешь, у тебя получится перехитрить фурболгов?','Унгарл') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обман Черночревов',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хаггруму Кровопалу на северную пересадочную станцию ракетной дороги в Азшаре.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Думаешь, у тебя получится перехитрить фурболгов?',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Унгарл',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (14436,'Дворфийские делишки','Некие дворфы готовят раскопки на северо-западе – полагают, что в земле скрыты великие тайны. В некотором роде они правы, но оскверняя и уродуя лик природы, нельзя постигнуть ее мудрость. $B$BСобери инструменты дворфов, уничтожь их и принеси мне.$B$BЛомать инструменты можно в кузнице, которая есть в Громовом Утесе, но подойдет любая, даже та, что находится в дворфийском лагере.','Соберите 5 кирок геолога.$B$BСломайте их в кузнице. $B$BОтнесите 5 сломанных инструментов Ахмо Громовому Рогу в деревню Кровавого Копыта.','Вернитесь к Ахмо Громовому Рогу в деревню Кровавого Копыта, что в Мулгоре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дворфийские делишки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Некие дворфы готовят раскопки на северо-западе – полагают, что в земле скрыты великие тайны. В некотором роде они правы, но оскверняя и уродуя лик природы, нельзя постигнуть ее мудрость. $B$BСобери инструменты дворфов, уничтожь их и принеси мне.$B$BЛомать инструменты можно в кузнице, которая есть в Громовом Утесе, но подойдет любая, даже та, что находится в дворфийском лагере.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 5 кирок геолога.$B$BСломайте их в кузнице. $B$BОтнесите 5 сломанных инструментов Ахмо Громовому Рогу в деревню Кровавого Копыта.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ахмо Громовому Рогу в деревню Кровавого Копыта, что в Мулгоре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (14437,'Обряды Матери-Земли','Чтобы продолжить прохождение обрядов Матери-Земли, ты $gдолжен:должна; выдержать еще два испытания. Тебе бы не помешало поднабраться опыта, $n.$b$bОтправляйся в деревню Кровавого Копыта и найди Ахмо Громового Рога. Там ты сможешь продолжить свои тренировки и завоевать расположение старейшин Громового Утеса. $b$bОтнеси этот тотем Ахмо. Он узнает мою руку в этой резьбе и поможет тебе в твоем путешествии.$b$bСледуй по дороге из Лагеря Нараче, да поспеши. И не уходи далеко от дороги – заблудишься!','Отнесите тотем Соколиного Ветра Ахмо Громовому Рогу в деревню Кровавого Копыта. Следуйте по дороге из Лагеря Нараче.','Вернитесь к Ахмо Громовому Рогу в деревню Кровавого Копыта, что в Мулгоре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обряды Матери-Земли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чтобы продолжить прохождение обрядов Матери-Земли, ты $gдолжен:должна; выдержать еще два испытания. Тебе бы не помешало поднабраться опыта, $n.$b$bОтправляйся в деревню Кровавого Копыта и найди Ахмо Громового Рога. Там ты сможешь продолжить свои тренировки и завоевать расположение старейшин Громового Утеса. $b$bОтнеси этот тотем Ахмо. Он узнает мою руку в этой резьбе и поможет тебе в твоем путешествии.$b$bСледуй по дороге из Лагеря Нараче, да поспеши. И не уходи далеко от дороги – заблудишься!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите тотем Соколиного Ветра Ахмо Громовому Рогу в деревню Кровавого Копыта. Следуйте по дороге из Лагеря Нараче.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ахмо Громовому Рогу в деревню Кровавого Копыта, что в Мулгоре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (14438,'Недобрые соседи','$n, нашей земле причиняют боль раздоры ее обитателей. Я надеюсь, что тебе не суждено увидеть столько войн, сколько выпало мне. И все же я вынужден просить тебя вступить в бой. Так ты поймешь, что малая угроза, если не искоренить ее, со временем разрастается.$B$BГноллы-бледногривы поселились на юге от нашей деревни и в пещере на западе. Они не обращают внимания на наши попытки договориться и без жалости убивают животных Мулгора.$B$BСловами их не остановить.','Убейте 15 гноллов из стаи Бледногривов и возвращайтесь к Ахмо Громовому Рогу в деревню Кровавого Копыта.','Вернитесь к Ахмо Громовому Рогу в деревню Кровавого Копыта, что в Мулгоре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Недобрые соседи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, нашей земле причиняют боль раздоры ее обитателей. Я надеюсь, что тебе не суждено увидеть столько войн, сколько выпало мне. И все же я вынужден просить тебя вступить в бой. Так ты поймешь, что малая угроза, если не искоренить ее, со временем разрастается.$B$BГноллы-бледногривы поселились на юге от нашей деревни и в пещере на западе. Они не обращают внимания на наши попытки договориться и без жалости убивают животных Мулгора.$B$BСловами их не остановить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 15 гноллов из стаи Бледногривов и возвращайтесь к Ахмо Громовому Рогу в деревню Кровавого Копыта.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ахмо Громовому Рогу в деревню Кровавого Копыта, что в Мулгоре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (14439,'Путешествие в Громовой Утес','Отныне тебя будут почитать в стенах нашего великого города. $GПрошедший:Прошедшая; обряды Матери-Земли заслуживает такой чести.$B$bВыполни последнее задание, отыщи нашего юного вождя Бейна Кровавое Копыто, живущего на вершине высочайшего плато в Громовом Утесе.','Поговорите с Бейном Кровавым Копытом в Громовом Утесе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путешествие в Громовой Утес',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Отныне тебя будут почитать в стенах нашего великого города. $GПрошедший:Прошедшая; обряды Матери-Земли заслуживает такой чести.$B$bВыполни последнее задание, отыщи нашего юного вождя Бейна Кровавое Копыто, живущего на вершине высочайшего плато в Громовом Утесе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Бейном Кровавым Копытом в Громовом Утесе.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (14440,'Обряды Матери-Земли','Ты $gпрошел:прошла; обряды Матери-Земли и $gзаслужил:заслужила; достойное место среди жителей Громового Утеса.$B$BЧтобы сохранить это таким трудом заработанное место, тебе придется и дальше служить своему народу.$b$bМы охотники, $n. Внизу, в Мулгоре, есть могучий кодо по имени Арра\'чея. Выследи и убей его, проявив свое искусство охотника, и принеси мне рог Арра\'чеи.','Бейн Кровавое Копыто из Громового Утеса попросил принести ему рог Арра\'чеи.','Вернитесь к Бейну Кровавому Копыту в Пустоши.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обряды Матери-Земли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gпрошел:прошла; обряды Матери-Земли и $gзаслужил:заслужила; достойное место среди жителей Громового Утеса.$B$BЧтобы сохранить это таким трудом заработанное место, тебе придется и дальше служить своему народу.$b$bМы охотники, $n. Внизу, в Мулгоре, есть могучий кодо по имени Арра\'чея. Выследи и убей его, проявив свое искусство охотника, и принеси мне рог Арра\'чеи.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Бейн Кровавое Копыто из Громового Утеса попросил принести ему рог Арра\'чеи.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бейну Кровавому Копыту в Пустоши.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (14441,'Автограф Гарроша','Говорят, что Гаррош Адский Крик – один из величайших героев Орды. Когда я вырасту, я тоже хочу стать героем Орды!$b$bТы $gзнаком:знакома; с Гаррошем? Окажи мне услугу! Возьми у него автограф! Я не знаю, как его попросить, у него нет времени для таких, как я... другое дело ты! Ты $gтакой же искатель:такая же искательница; приключений, как и он! Готов поспорить, что тебе получить у него автограф – раз плюнуть!$b$bПожалуйста!','Отправляйтесь в крепость Громмаш, что на Аллее Силы в Оргриммаре, и постарайтесь получить автограф Гарроша Адского Крика для своего подопечного.','Вернитесь к своему подопечному орку-сироте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Автограф Гарроша',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Говорят, что Гаррош Адский Крик – один из величайших героев Орды. Когда я вырасту, я тоже хочу стать героем Орды!$b$bТы $gзнаком:знакома; с Гаррошем? Окажи мне услугу! Возьми у него автограф! Я не знаю, как его попросить, у него нет времени для таких, как я... другое дело ты! Ты $gтакой же искатель:такая же искательница; приключений, как и он! Готов поспорить, что тебе получить у него автограф – раз плюнуть!$b$bПожалуйста!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в крепость Громмаш, что на Аллее Силы в Оргриммаре, и постарайтесь получить автограф Гарроша Адского Крика для своего подопечного.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к своему подопечному орку-сироте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (14442,'Мой любимый объект','Не знаю, $gобратил:обратила; ли ты внимание на это, но весь комплекс лаборатории представляет собой весьма плачевное зрелище! Не очень жалко списать всех этих гиппогрифов, но пропал еще и результат моего лучшего эксперимента – объект №9!$b$bОбъект №9 – это самка ящера, которую мы привезли из Степей. Интересно, жива ли она еще? Посмотри у главного комплекса к западу отсюда, возле гигантской сверхсекретной ракеты. Не заметить ее нельзя.','Найдите объект №9 где-то возле комплекса секретной лаборатории в Азшаре.','Найдите объект №9 где-то возле комплекса секретной лаборатории в Азшаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мой любимый объект',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не знаю, $gобратил:обратила; ли ты внимание на это, но весь комплекс лаборатории представляет собой весьма плачевное зрелище! Не очень жалко списать всех этих гиппогрифов, но пропал еще и результат моего лучшего эксперимента – объект №9!$b$bОбъект №9 – это самка ящера, которую мы привезли из Степей. Интересно, жива ли она еще? Посмотри у главного комплекса к западу отсюда, возле гигантской сверхсекретной ракеты. Не заметить ее нельзя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите объект №9 где-то возле комплекса секретной лаборатории в Азшаре.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Найдите объект №9 где-то возле комплекса секретной лаборатории в Азшаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14443,'Потертая рукоять','Принесите потертую рукоять Каладису Сияющему Копью в Покой Кель\'Делара к югу от ристалища Серебряного Турнира.','Что это у тебя?','Вернитесь к Каладису Сияющему Копью в Покой Кель\'Делара.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Потертая рукоять',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите потертую рукоять Каладису Сияющему Копью в Покой Кель\'Делара к югу от ристалища Серебряного Турнира.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что это у тебя?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Каладису Сияющему Копью в Покой Кель\'Делара.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (14444,'То, что знают драконы','Ошибки быть не может – это рукоять могущественного древнего клинка. Вот только что это был за клинок? Я не могу вспомнить ни одного меча с такой гравировкой, но не все еще потеряно.$B$BМы должны обратиться к Кориалстразу, более известному тебе как Крас. Он – давний друг кель\'дорай и Кирин-Тора. За его плечами мудрость рода красных драконов; наверняка, он сможет нам помочь. Отправляйся за его советом на вершину Храма Драконьего Покоя.','Поговорите с Красом на вершине Храма Драконьего Покоя.','Нельзя допустить, чтобы книга осталась в руках Похитителей Солнца. Если мы рассчитываем опознать этот меч и использовать его в наших целях, надо найти способ перехватить книгу, которую одолжил им Крас.','Вернитесь к чародею Тибалину в Серебряный Анклав, что в Даларане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','То, что знают драконы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ошибки быть не может – это рукоять могущественного древнего клинка. Вот только что это был за клинок? Я не могу вспомнить ни одного меча с такой гравировкой, но не все еще потеряно.$B$BМы должны обратиться к Кориалстразу, более известному тебе как Крас. Он – давний друг кель\'дорай и Кирин-Тора. За его плечами мудрость рода красных драконов; наверняка, он сможет нам помочь. Отправляйся за его советом на вершину Храма Драконьего Покоя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Красом на вершине Храма Драконьего Покоя.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Нельзя допустить, чтобы книга осталась в руках Похитителей Солнца. Если мы рассчитываем опознать этот меч и использовать его в наших целях, надо найти способ перехватить книгу, которую одолжил им Крас.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к чародею Тибалину в Серебряный Анклав, что в Даларане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (14445,'До скорой встречи','Наши судьбы соединены навеки. То, что сейчас происходит на наших глазах, изменит облик мира и в конце концов его уничтожит. Поэтому мы должны изменить ход событий, пока не поздно.$B$BЗнай, $gбрат:сестра;, ты всегда можешь рассчитывать на меня! Мы встретимся на большом острове. И пусть до тех пор ничто не нарушит твой душевный покой, $n.','Поговорите с Хамми Кофельнагель на Лесном наблюдательном пункте на Затерянных островах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','До скорой встречи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наши судьбы соединены навеки. То, что сейчас происходит на наших глазах, изменит облик мира и в конце концов его уничтожит. Поэтому мы должны изменить ход событий, пока не поздно.$B$BЗнай, $gбрат:сестра;, ты всегда можешь рассчитывать на меня! Мы встретимся на большом острове. И пусть до тех пор ничто не нарушит твой душевный покой, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Хамми Кофельнагель на Лесном наблюдательном пункте на Затерянных островах.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (14446,'Катаклизм!','Внимай мне, |3-6($c)!$B$BВетра перемен уже превратились в неумолимый шторм, несущийся по всему Азероту.$B$BДостанет ли тебе отваги справиться с истинной причиной наших бед?$B$BСобери всю свою решимость, |3-6($r), и моли, чтобы сила и удача не оставили тебя в грядущих испытаниях.$B$BНежданный союзник кинул клич всем, кто услышит. Взгляни в Воды предвидения – и узри судьбу мира!','Намбрия желает, чтобы вы взглянули в Воды предвидения.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Катаклизм!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Внимай мне, |3-6($c)!$B$BВетра перемен уже превратились в неумолимый шторм, несущийся по всему Азероту.$B$BДостанет ли тебе отваги справиться с истинной причиной наших бед?$B$BСобери всю свою решимость, |3-6($r), и моли, чтобы сила и удача не оставили тебя в грядущих испытаниях.$B$BНежданный союзник кинул клич всем, кто услышит. Взгляни в Воды предвидения – и узри судьбу мира!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Намбрия желает, чтобы вы взглянули в Воды предвидения.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (14447,'Уж кто бы говорил!','Несмотря на то, что нам надлежит методично атаковать силы Альянса, не стоит забывать и о Плети.$b$bПусть еще несколько недель у нас не будет хватать сил для серьезного нападения на ледник, но это не должно нам помешать хорошенько изучить вражеские укрепления.$b$bЯ попросил нашего агента – одного из рыцарей смерти – помочь тебе в данном начинании. Кто может знать о противнике лучше, чем они?$b$bПозволь представить тебе Кольтиру Ткача Смерти.','По заданию покорителя небес Корма поговорите с Кольтирой Ткачом Смерти на борту "Молота Оргрима".') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уж кто бы говорил!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Несмотря на то, что нам надлежит методично атаковать силы Альянса, не стоит забывать и о Плети.$b$bПусть еще несколько недель у нас не будет хватать сил для серьезного нападения на ледник, но это не должно нам помешать хорошенько изучить вражеские укрепления.$b$bЯ попросил нашего агента – одного из рыцарей смерти – помочь тебе в данном начинании. Кто может знать о противнике лучше, чем они?$b$bПозволь представить тебе Кольтиру Ткача Смерти.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По заданию покорителя небес Корма поговорите с Кольтирой Ткачом Смерти на борту "Молота Оргрима".',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (14448,'Уж кто бы говорил!','Несмотря на то, что нам надлежит методично атаковать силы Альянса, не стоит забывать и о Плети.$b$bПусть еще несколько недель у нас не будет хватать сил для серьезного нападения на ледник, но это не должно нам помешать хорошенько изучить вражеские укрепления.$b$bЯ попросил нашего агента – одного из рыцарей смерти – помочь тебе в данном начинании. Кто может знать о противнике лучше, чем они?$b$bПозволь представить тебе Кольтиру Ткача Смерти.','По заданию покорителя небес Корма поговорите с Кольтирой Ткачом Смерти на борту "Молота Оргрима".') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уж кто бы говорил!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Несмотря на то, что нам надлежит методично атаковать силы Альянса, не стоит забывать и о Плети.$b$bПусть еще несколько недель у нас не будет хватать сил для серьезного нападения на ледник, но это не должно нам помешать хорошенько изучить вражеские укрепления.$b$bЯ попросил нашего агента – одного из рыцарей смерти – помочь тебе в данном начинании. Кто может знать о противнике лучше, чем они?$b$bПозволь представить тебе Кольтиру Ткача Смерти.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По заданию покорителя небес Корма поговорите с Кольтирой Ткачом Смерти на борту "Молота Оргрима".',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (14449,'Первый шаг','Это будет твое первое настоящее испытание, таурен.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Первый шаг',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это будет твое первое настоящее испытание, таурен.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (14450,'Random Drop Test Progressive','This quest tests random drops with progressive drop percentage.','Get 10 Progressive Widgets.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Random Drop Test Progressive',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','This quest tests random drops with progressive drop percentage.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Get 10 Progressive Widgets.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (14451,'Random Drop Flat Rate','This quest tests random drops with flat rate drop percentage.','Get 10 Flat Widgets.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Random Drop Flat Rate',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','This quest tests random drops with flat rate drop percentage.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Get 10 Flat Widgets.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`objectives_loc8`,`completedtext_loc8`) VALUES (14452,'Убейте 6 налетчиков из племени Дыбогривов.','Вернитесь к Груллу Соколиному Ветру.') ON DUPLICATE KEY UPDATE `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 6 налетчиков из племени Дыбогривов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Груллу Соколиному Ветру.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (14453,'Скромная просьба','Все члены племени живут вместе в мире и гармонии. Мы живем вместе и работаем вместе. Мы преданы друг другу и отвечаем друг за друга. Я обращаюсь к тебе со скромной просьбой.$b$bМоя матушка сегодня отправилась за водой к источнику к юго-востоку от Нараче. С тех пор прошло довольно много времени. Не поищешь ли ты ее, пока я занимаюсь делами племени?','Поищите матушку вождя Соколиный Ветер у источника к юго-востоку от Лагеря Нараче.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Скромная просьба',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Все члены племени живут вместе в мире и гармонии. Мы живем вместе и работаем вместе. Мы преданы друг другу и отвечаем друг за друга. Я обращаюсь к тебе со скромной просьбой.$b$bМоя матушка сегодня отправилась за водой к источнику к юго-востоку от Нараче. С тех пор прошло довольно много времени. Не поищешь ли ты ее, пока я занимаюсь делами племени?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поищите матушку вождя Соколиный Ветер у источника к юго-востоку от Лагеря Нараче.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (14454,'Плененный воин','Свинобразы не только громят наши дома, они еще и берут тауренов в плен. Я видел, как они тащили Храбреца Острого Рога, нашего наставника юных воинов, в одной из своих грязных клеток. Пожалуйста, найди на одном из тел свинобразов ключ и спаси его!','Найдите у свинобразов из племени Дыбогривов грубый ключ и отоприте клетку, в которой держат Храбреца Острого Рога.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Плененный воин',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Свинобразы не только громят наши дома, они еще и берут тауренов в плен. Я видел, как они тащили Храбреца Острого Рога, нашего наставника юных воинов, в одной из своих грязных клеток. Пожалуйста, найди на одном из тел свинобразов ключ и спаси его!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите у свинобразов из племени Дыбогривов грубый ключ и отоприте клетку, в которой держат Храбреца Острого Рога.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (14455,'Знать привычки своей жертвы, – еще одна охотничья премудрость. В тех землях, откуда они пришли, свинобразы живут под защитой огромных колючих корней. Когда племя переходит на новое место, их шаманы сеют и выращивают новые корни с шипами, которые будут служить им укрытием.$b$bЭти корни портят землю и наносят вред другим живым существам, превращая территорию, на которой живут свинобразы, в бесплодные земли. Отправляйся на юг и останови этих заклинателей шипов, $n.','Теперь, когда осквернители мертвы, Мать-Земля сможет залечить свои раны. Корни засохнут и больше не будут расти здесь. Баланс восстановится.','Вернитесь к Эдане Громовой Рог.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Знать привычки своей жертвы, – еще одна охотничья премудрость. В тех землях, откуда они пришли, свинобразы живут под защитой огромных колючих корней. Когда племя переходит на новое место, их шаманы сеют и выращивают новые корни с шипами, которые будут служить им укрытием.$b$bЭти корни портят землю и наносят вред другим живым существам, превращая территорию, на которой живут свинобразы, в бесплодные земли. Отправляйся на юг и останови этих заклинателей шипов, $n.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь, когда осквернители мертвы, Мать-Земля сможет залечить свои раны. Корни засохнут и больше не будут расти здесь. Баланс восстановится.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Эдане Громовой Рог.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`objectives_loc8`,`completedtext_loc8`) VALUES (14456,'Верните 7 винтовок, украденных ворами из племени Дыбогривов.','Вернитесь к Эдане Громовой Рог.') ON DUPLICATE KEY UPDATE `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните 7 винтовок, украденных ворами из племени Дыбогривов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Эдане Громовой Рог.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (14456,'Молодец, Поував. Относись к жертве с должным уважением и принимай во внимание ее силу, но никогда не бойся ее. В страхе ты сам можешь превратиться в жертву.','Сколько винтовок ты принес мне, сын мой?') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Молодец, Поував. Относись к жертве с должным уважением и принимай во внимание ее силу, но никогда не бойся ее. В страхе ты сам можешь превратиться в жертву.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Сколько винтовок ты принес мне, сын мой?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14457,'План Похитителей Солнца','Добудьте приказы Похитителей Солнца.','<Чародей Тибалин изучает перехваченные приказы.>$B$BУбитый тобой агент должен был доставить книгу из Храма Драконьего Покоя в Ледяную Корону, но сначала он собирался забрать ее у магистра Хатореля в Прибежище Похитителя Солнца. Это наш шанс перехватить книгу, Лолита! Хотя это будет непросто...','Ну что, у этого агента было с собой что-нибудь полезное?','Вернитесь к чародею Тибалину в Серебряный Анклав, что в Даларане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','План Похитителей Солнца',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте приказы Похитителей Солнца.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Чародей Тибалин изучает перехваченные приказы.>$B$BУбитый тобой агент должен был доставить книгу из Храма Драконьего Покоя в Ледяную Корону, но сначала он собирался забрать ее у магистра Хатореля в Прибежище Похитителя Солнца. Это наш шанс перехватить книгу, Лолита! Хотя это будет непросто...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, у этого агента было с собой что-нибудь полезное?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к чародею Тибалину в Серебряный Анклав, что в Даларане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (14458,'Идите к Эдане','Мы нанесли свинобразам серьезный удар. Я останусь здесь и буду держать оборону, но ты $gдолжен:должна; двигаться дальше.$b$bНайди Эдану Громовой Рог; она отправилась на юго-запад вместе с несколькими храбрецами, чтобы истребить Дыбогривов до последнего свинобраза.','Идите к Эдане Громовой Рог на юго-запад.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Идите к Эдане',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы нанесли свинобразам серьезный удар. Я останусь здесь и буду держать оборону, но ты $gдолжен:должна; двигаться дальше.$b$bНайди Эдану Громовой Рог; она отправилась на юго-запад вместе с несколькими храбрецами, чтобы истребить Дыбогривов до последнего свинобраза.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Идите к Эдане Громовой Рог на юго-запад.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (14458,'Впереди тебя ждет еще больше испытаний, Поував. Надеюсь, что ты готов.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Впереди тебя ждет еще больше испытаний, Поував. Надеюсь, что ты готов.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (14459,'Боевые вепри','Здесь еще многое нужно сделать. Свинобразы приручают диких вепрей, чтобы использовать их в бою против нас.$b$bНет надежды, что эти бронированные боевые вепри смогут стать такими же, как раньше; их необходимо истребить для нашей безопасности и их покоя. Отправляйся в загон, что на юге, и убей их, $n. Потом возвращайся ко мне.','Убейте 10 бронированных боевых вепрей.','Вернитесь к Эдане Громовой Рог.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Боевые вепри',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Здесь еще многое нужно сделать. Свинобразы приручают диких вепрей, чтобы использовать их в бою против нас.$b$bНет надежды, что эти бронированные боевые вепри смогут стать такими же, как раньше; их необходимо истребить для нашей безопасности и их покоя. Отправляйся в загон, что на юге, и убей их, $n. Потом возвращайся ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 бронированных боевых вепрей.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Эдане Громовой Рог.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (14459,'Превосходно, Поував. Эти чудовища могли нанести еще больший вред, чем сами свинобразы, если бы мы ничего не предприняли.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Превосходно, Поував. Эти чудовища могли нанести еще больший вред, чем сами свинобразы, если бы мы ничего не предприняли.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (14460,'Убейте Визгуна Терновую Мантию.','<Вождь Соколиный Ветер держит гриву Терновой Мантии над головой.>$B$BВождь Дыбогривов убит. Дух Великой Матери Соколиный Ветер отомщен!','Вернитесь к вождю Соколиному Ветру в Лагерь Нараче.') ON DUPLICATE KEY UPDATE `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Визгуна Терновую Мантию.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Вождь Соколиный Ветер держит гриву Терновой Мантии над головой.>$B$BВождь Дыбогривов убит. Дух Великой Матери Соколиный Ветер отомщен!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к вождю Соколиному Ветру в Лагерь Нараче.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (14461,'Пища зла','Ты не просто очистил загон вепрей, ты еще и положил конец ужасному осквернению. Молодец.','Вернитесь к Эдане Громовой Рог.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пища зла',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты не просто очистил загон вепрей, ты еще и положил конец ужасному осквернению. Молодец.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Эдане Громовой Рог.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (14462,'Где моя голова?','Встретьтесь с Крадли Дротик у подножия северной башни заставы Талрендис.','Встретьтесь с наемной убийцей Крадли Дротик у подножия северной башни заставы Талрендис в Азшаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Где моя голова?',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Встретьтесь с Крадли Дротик у подножия северной башни заставы Талрендис.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Встретьтесь с наемной убийцей Крадли Дротик у подножия северной башни заставы Талрендис в Азшаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (14463,'Лошади для Темной Гавани','Вызволив лошадей, ты, возможно, $gспас:спасла; многих жителей этого города. Я слышала, у них есть повозки в Темной Гавани, но их некому везти.$B$BСкажи мэру Армстед, что она может распоряжаться этими лошадьми по своему усмотрению.$B$BЯ же соберу вещи и скоро присоединюсь к вам.','Поговорите с Гвен Армстед в Темной Гавани.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лошади для Темной Гавани',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вызволив лошадей, ты, возможно, $gспас:спасла; многих жителей этого города. Я слышала, у них есть повозки в Темной Гавани, но их некому везти.$B$BСкажи мэру Армстед, что она может распоряжаться этими лошадьми по своему усмотрению.$B$BЯ же соберу вещи и скоро присоединюсь к вам.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Гвен Армстед в Темной Гавани.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (14464,'Молниеносное убийство','Территорию у подножия башни патрулируют самые лучшие телохранители капитана. Поэтому вот что мы сделаем: заберемся наверх, оттуда порежем на лапшу всю эту элиту и потом спустимся вниз на моем портативном низковысотном парашюте. А в башне я заложу взрывчатку, и она взлетит на воздух после нашего спуска. Не забудь прихватить голову для Чога. $gПонял:Поняла;?$b$bИ НЕ соглашайся на это мероприятие, если ты не $GОТЪЯВЛЕННЫЙ:ОТЪЯВЛЕННАЯ; ЗАДИРА. Ясно?','Сообщите Крадли Дротик, что вы готовы подняться на башню и совершить покушение на капитана Грюнвальда. Заберите голову капитана.','Принесите голову капитана Грюнвальда Чогу в Храбростан в Азшаре. Крадли Дротик подскажет вам, как покинуть башню кратчайшим путем!','Вот голова, которую тебе нужно забрать. Держи.','Капитан Грюнвальд') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Молниеносное убийство',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Территорию у подножия башни патрулируют самые лучшие телохранители капитана. Поэтому вот что мы сделаем: заберемся наверх, оттуда порежем на лапшу всю эту элиту и потом спустимся вниз на моем портативном низковысотном парашюте. А в башне я заложу взрывчатку, и она взлетит на воздух после нашего спуска. Не забудь прихватить голову для Чога. $gПонял:Поняла;?$b$bИ НЕ соглашайся на это мероприятие, если ты не $GОТЪЯВЛЕННЫЙ:ОТЪЯВЛЕННАЯ; ЗАДИРА. Ясно?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сообщите Крадли Дротик, что вы готовы подняться на башню и совершить покушение на капитана Грюнвальда. Заберите голову капитана.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите голову капитана Грюнвальда Чогу в Храбростан в Азшаре. Крадли Дротик подскажет вам, как покинуть башню кратчайшим путем!',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Вот голова, которую тебе нужно забрать. Держи.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Капитан Грюнвальд',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (14466,'Королевская обсерватория','Ты $gдолжен:должна; поговорить с Генном. Он уже давно не выходил из своей обсерватории, с самого начала всех этих ужасных событий...$B$BНаверное, обдумывает план спасения нашего народа. Ты же знаешь, он никогда не сдается.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Королевская обсерватория',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gдолжен:должна; поговорить с Генном. Он уже давно не выходил из своей обсерватории, с самого начала всех этих ужасных событий...$B$BНаверное, обдумывает план спасения нашего народа. Ты же знаешь, он никогда не сдается.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (14467,'Горе тебе, Гилнеас!','Посмотри, $n! Посмотри, что стало с Темной Гаванью!$b$bВзгляни, во что превратилось последнее безопасное убежище Гилнеаса!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Горе тебе, Гилнеас!',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Посмотри, $n! Посмотри, что стало с Темной Гаванью!$b$bВзгляни, во что превратилось последнее безопасное убежище Гилнеаса!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (14468,'Очередной новобранец','У меня для тебя есть дельце! Ты сможешь познакомиться с новыми культурами, пережить захватывающие приключения, повзрывать всякие штуки, и за все это тебе еще и заплатят! Думаешь, что все это так прекрасно, что не может быть правдой? А вот и нет – именно такими вещами мы и занимаемся!$b$bЕсли тебе интересно, отправляйся на заставу Галливикса, которая находится на Одинокой вершине, к северу отсюда, и разыщи там командующего Молотова.','Поговорите с командующим Молотовым на Одинокой вершине.','Ты из последних рекрутов, да?$B$BОбъясняю коротко. Нас наняли, чтобы мы держали наг в руинах подальше от Галливикса и его собственности. Твоя забота – делать то, что прикажут, моя забота – следить, чтобы тебе за это заплатили.$B$BДобро пожаловать в батальон Трюмных Вод.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Очередной новобранец',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У меня для тебя есть дельце! Ты сможешь познакомиться с новыми культурами, пережить захватывающие приключения, повзрывать всякие штуки, и за все это тебе еще и заплатят! Думаешь, что все это так прекрасно, что не может быть правдой? А вот и нет – именно такими вещами мы и занимаемся!$b$bЕсли тебе интересно, отправляйся на заставу Галливикса, которая находится на Одинокой вершине, к северу отсюда, и разыщи там командующего Молотова.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с командующим Молотовым на Одинокой вершине.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты из последних рекрутов, да?$B$BОбъясняю коротко. Нас наняли, чтобы мы держали наг в руинах подальше от Галливикса и его собственности. Твоя забота – делать то, что прикажут, моя забота – следить, чтобы тебе за это заплатили.$B$BДобро пожаловать в батальон Трюмных Вод.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14470,'Военный прорыв','У нас пропала связь с сержантом Динамо, который занимал позицию на ближайшем горном хребте, к северу от центрального минного поля. Велика вероятность того, что их разбили.$b$bУ него осталась наша последняя РЗТ. Отправляйся туда и верни ее. Пока будешь там, уничтожай всех наг, которым удалось прорваться.','Убейте полководца Креллиана и верните РЗТ.','Ты быстро управился, рекрут.$B$BОна красотка, не правда ли? Сам собирал. У меня на эту малышку особенные планы.','Где моя ракета, рекрут?','Вернитесь к Гликсу Шлифферцу на заставу Галливикса, что на Одинокой вершине в Азшаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Военный прорыв',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У нас пропала связь с сержантом Динамо, который занимал позицию на ближайшем горном хребте, к северу от центрального минного поля. Велика вероятность того, что их разбили.$b$bУ него осталась наша последняя РЗТ. Отправляйся туда и верни ее. Пока будешь там, уничтожай всех наг, которым удалось прорваться.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте полководца Креллиана и верните РЗТ.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты быстро управился, рекрут.$B$BОна красотка, не правда ли? Сам собирал. У меня на эту малышку особенные планы.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Где моя ракета, рекрут?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гликсу Шлифферцу на заставу Галливикса, что на Одинокой вершине в Азшаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (14471,'Первоклассная мортира','Эй, $gприятель:подруга;! Любишь взрывы? Ну, конечно, любишь. Кто же не любит повзрывать?!$b$bЧтобы сдерживать наг, у меня есть мортиры, они установлены наверху на горном хребте, к востоку отсюда. Иди, рекрут. Обстреляй их... расстреляй их всех! А-ха-ха-ха!','Воспользуйтесь гоблинской мортирой, чтобы убить 60 нападающих из клана Бича Злобы.','Можешь поверить, что они ПЛАТЯТ, за то, что мы это делаем?','Вернитесь к Зизу Залпомбацу на заставу Галливикса, что на Одинокой вершине в Азшаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Первоклассная мортира',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эй, $gприятель:подруга;! Любишь взрывы? Ну, конечно, любишь. Кто же не любит повзрывать?!$b$bЧтобы сдерживать наг, у меня есть мортиры, они установлены наверху на горном хребте, к востоку отсюда. Иди, рекрут. Обстреляй их... расстреляй их всех! А-ха-ха-ха!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь гоблинской мортирой, чтобы убить 60 нападающих из клана Бича Злобы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Можешь поверить, что они ПЛАТЯТ, за то, что мы это делаем?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Зизу Залпомбацу на заставу Галливикса, что на Одинокой вершине в Азшаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (14472,'В голову!','Наги пользуются этими великанами для того, чтобы проложить проходы через наши минные поля. Пришло время использовать РЗТ!$b$bОтправляйся ко входу на южное минное поле – думаю, ты $gсам догадаешься:сама догадаешься;, что делать дальше.','Воспользуйтесь РЗТ, чтобы убить порабощенного сына Арккорока на южном минном поле.','БАМ! Прямо в голову! Отличный выстрел, сынок.','Вернитесь к Гликсу Шлифферцу на заставу Галливикса, что на Одинокой вершине в Азшаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В голову!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наги пользуются этими великанами для того, чтобы проложить проходы через наши минные поля. Пришло время использовать РЗТ!$b$bОтправляйся ко входу на южное минное поле – думаю, ты $gсам догадаешься:сама догадаешься;, что делать дальше.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь РЗТ, чтобы убить порабощенного сына Арккорока на южном минном поле.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','БАМ! Прямо в голову! Отличный выстрел, сынок.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гликсу Шлифферцу на заставу Галливикса, что на Одинокой вершине в Азшаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (14473,'Теперь это наше дело','Обезьяны крадут все, что не прибито гвоздями! Видишь ли, эти вороватые чудовища стащили яйца тероящера-матриарха и привели ее этим в бешенство. Хуже того: из яиц уже вылупляется потомство! Так что теперь здесь полно голодных тероящеров-детенышей, которые мечтают закусить нами!$B$BМы, в общем, здесь ни при чем, но теперь это и наша головная боль. Поэтому тебе нужно отправиться в джунгли и убить этих голодных молодых ящеров, пока они тут нас всех не съели.','Убейте 6 тероящеров-детенышей.','Будем надеяться, что нам не придется потом разбираться с их мамочкой. Это будет настоящей катастрофой.','Вернитесь к Макссу Оползню на Берег Кораблекрушения на Затерянных островах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Теперь это наше дело',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Обезьяны крадут все, что не прибито гвоздями! Видишь ли, эти вороватые чудовища стащили яйца тероящера-матриарха и привели ее этим в бешенство. Хуже того: из яиц уже вылупляется потомство! Так что теперь здесь полно голодных тероящеров-детенышей, которые мечтают закусить нами!$B$BМы, в общем, здесь ни при чем, но теперь это и наша головная боль. Поэтому тебе нужно отправиться в джунгли и убить этих голодных молодых ящеров, пока они тут нас всех не съели.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 6 тероящеров-детенышей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Будем надеяться, что нам не придется потом разбираться с их мамочкой. Это будет настоящей катастрофой.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Макссу Оползню на Берег Кораблекрушения на Затерянных островах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (14474,'Гоблинские спасательные шлюпки','Ах, $n, прости, я думал, ты $gпомер:умерла;!$B$BБред какой-то. Мы плыли-плыли и оказались в самой гуще боя Альянса с Ордой!$B$BНаших братьев и сестер нужно спасти.$B$B<Он указывает на спасательные капсулы в воде.>$B$BЯ, пожалуй, посижу тут еще немного, переведу дыхание. А ты тем временем поможешь им выбраться? Возьми мои термогидратные ласты, чтобы быстрее двигаться.$B$BДа, и скажи Хамми, что я скоро буду.','Спасите 6 уцелевших гоблинов.','Отправляйтесь к Хамми Кофельнагель на Берег Кораблекрушения на Затерянных островах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гоблинские спасательные шлюпки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ах, $n, прости, я думал, ты $gпомер:умерла;!$B$BБред какой-то. Мы плыли-плыли и оказались в самой гуще боя Альянса с Ордой!$B$BНаших братьев и сестер нужно спасти.$B$B<Он указывает на спасательные капсулы в воде.>$B$BЯ, пожалуй, посижу тут еще немного, переведу дыхание. А ты тем временем поможешь им выбраться? Возьми мои термогидратные ласты, чтобы быстрее двигаться.$B$BДа, и скажи Хамми, что я скоро буду.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Спасите 6 уцелевших гоблинов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отправляйтесь к Хамми Кофельнагель на Берег Кораблекрушения на Затерянных островах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (14475,'Нелетная погода!','Знаешь, в чем проблема с этими ветрокрылами, $n? Летать на них невозможно! Каждого ветрокрыла, которого я отправляю, снайперы ночных эльфов превращают в решето.$b$bСтрелки заставы Талрендис засели в самой южной башне, у гор. Я отправил туда одного из этих тряпок-гоблинов, чтобы он разобрался с башней, но от него никаких известий. Найди бомбардира капитана Смукса и сделай так, чтобы он поторопился!','Найдите бомбардира капитана Смукса в самой южной башне ночных эльфов на заставе Талрендис.','Наконец-то подкрепление!','Найдите бомбардира капитана Смукса в самой южной башне ночных эльфов на заставе Талрендис в Азшаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нелетная погода!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Знаешь, в чем проблема с этими ветрокрылами, $n? Летать на них невозможно! Каждого ветрокрыла, которого я отправляю, снайперы ночных эльфов превращают в решето.$b$bСтрелки заставы Талрендис засели в самой южной башне, у гор. Я отправил туда одного из этих тряпок-гоблинов, чтобы он разобрался с башней, но от него никаких известий. Найди бомбардира капитана Смукса и сделай так, чтобы он поторопился!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите бомбардира капитана Смукса в самой южной башне ночных эльфов на заставе Талрендис.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Наконец-то подкрепление!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Найдите бомбардира капитана Смукса в самой южной башне ночных эльфов на заставе Талрендис в Азшаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (14476,'Ко взрыву готовы','Башня была вне досягаемости для пушечного огня, поэтому я подумал, что мы можем поступить старомодно – взорвать ее. Мы заложили взрывчатку, но охрана атаковала нас, и мы не успели привести детонаторы в боевое положение.$b$b$n! Отправляйся туда и активируй три детонатора, которые мы разместили вокруг подножия башни. Эти штуки примотаны к взрывпакетам, которые я разместил вдоль гребня горы... Получится отличный фейерверк!','Приведите в боевое положение три детонатора взрывчатки, заложенной у подножия самой южной башни заставы Талрендис.','Прелестно. Давай подожжем этот сарай!','Вернитесь к бомбардиру капитану Смуксу на заставу Талрендис в Азшаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ко взрыву готовы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Башня была вне досягаемости для пушечного огня, поэтому я подумал, что мы можем поступить старомодно – взорвать ее. Мы заложили взрывчатку, но охрана атаковала нас, и мы не успели привести детонаторы в боевое положение.$b$b$n! Отправляйся туда и активируй три детонатора, которые мы разместили вокруг подножия башни. Эти штуки примотаны к взрывпакетам, которые я разместил вдоль гребня горы... Получится отличный фейерверк!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Приведите в боевое положение три детонатора взрывчатки, заложенной у подножия самой южной башни заставы Талрендис.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прелестно. Давай подожжем этот сарай!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к бомбардиру капитану Смуксу на заставу Талрендис в Азшаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (14477,'Нажми на кнопку!','Дай-ка проверить соединения... и все готово. Ты за $gглавного:главную;, $n. Нажимай. Нажимай на кнопку!$b$bА после фейерверка отправляйся к Кроуму в Храбростан и сообщи ему, что небо чистое.$b$bЖми!','Подорвите взрывчатку!','Подорвите взрывчатку','Вернитесь к Кроуму в Храбростан в Азшаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нажми на кнопку!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Дай-ка проверить соединения... и все готово. Ты за $gглавного:главную;, $n. Нажимай. Нажимай на кнопку!$b$bА после фейерверка отправляйся к Кроуму в Храбростан и сообщи ему, что небо чистое.$b$bЖми!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Подорвите взрывчатку!',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Подорвите взрывчатку',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кроуму в Храбростан в Азшаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (14478,'Операция по потрошению рыбы','Добро пожаловать снова на службу, солдат. Приятно, что ты опять с нами.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Операция по потрошению рыбы',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Добро пожаловать снова на службу, солдат. Приятно, что ты опять с нами.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (14479,'Таких много','Хватит болтовни. Оторви свою задницу и дуй к ракете, солдат.$b$bИ запомни, убитым мы не платим.','Воспользуйтесь ракетой, чтобы добраться до Разоренного побережья, и явитесь на службу к лейтенанту Дрексу.','Потрясло по дороге?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Таких много',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хватит болтовни. Оторви свою задницу и дуй к ракете, солдат.$b$bИ запомни, убитым мы не платим.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь ракетой, чтобы добраться до Разоренного побережья, и явитесь на службу к лейтенанту Дрексу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Потрясло по дороге?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (14480,'Истребление','Убейте 30 наг из клана Бича Злобы в руинах Эльдарата.','Твое имя у всех на устах… можно подумать, ты из подрывного отряда. Ты жесток.','Вернитесь к сержанту Зелксу в руины Эльдарата.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Истребление',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 30 наг из клана Бича Злобы в руинах Эльдарата.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Твое имя у всех на устах… можно подумать, ты из подрывного отряда. Ты жесток.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к сержанту Зелксу в руины Эльдарата.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (14481,'В бездну','Орда и Альянс ожесточенно бьются друг с другом в западных морях.$B$BА прямо под ними великая вражеская сила вынашивает план, который может погубить всех нас.$B$BЯ отправляю тебя на переговоры с адмиралом сил Альянса. Поведай ему о своем видении. Убеди его обратить взор к истинной угрозе в толще вод, пока еще не слишком поздно...$B$BЧтобы получить аудиенцию у адмирала, тебе нужно сначала обратиться к вербовщику в гавани.','Намбрия просит вас поговорить с вербовщиком Бернсом в порту Штормграда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В бездну',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Орда и Альянс ожесточенно бьются друг с другом в западных морях.$B$BА прямо под ними великая вражеская сила вынашивает план, который может погубить всех нас.$B$BЯ отправляю тебя на переговоры с адмиралом сил Альянса. Поведай ему о своем видении. Убеди его обратить взор к истинной угрозе в толще вод, пока еще не слишком поздно...$B$BЧтобы получить аудиенцию у адмирала, тебе нужно сначала обратиться к вербовщику в гавани.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Намбрия просит вас поговорить с вербовщиком Бернсом в порту Штормграда.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (14482,'Зов долга','Отправляйтесь в бой на корабле наемников.','Бьюсь об заклад, не такое сражение ты ожидал увидеть. И все же это бой, вскоре сам убедишься...','Отправляйтесь в Вайш\'ир на корабле наемников','Поговорите с Эрунаком.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зов долга',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в бой на корабле наемников.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Бьюсь об заклад, не такое сражение ты ожидал увидеть. И все же это бой, вскоре сам убедишься...',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Отправляйтесь в Вайш\'ир на корабле наемников',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Эрунаком.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14483,'Не любовь витает в воздухе (а что-то иное!)','Оборотная сторона открытки исчерчена подробными и зловещими планами по заражению всего Азерота. Вы должны немедленно отнести ее одному из следователей Хитрой Шестеренки!','Принесите выцветшую открытку ко дню всех влюбленных детективу Крямсу Гвоздезубу в Оргриммар.','Что это тут у нас?$B$BОго, это уже серьезно. Очень серьезно. Целая куча головоломных деталей в одной упаковке. Спасибо, ты очень $Gпомог:помогла; нам в расследовании. Приятно было работать с тобой.','Ты позаботился об этих коварных злодеях?','Вернитесь к детективу Крямсу Гвоздезубу в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Не любовь витает в воздухе (а что-то иное!)',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Оборотная сторона открытки исчерчена подробными и зловещими планами по заражению всего Азерота. Вы должны немедленно отнести ее одному из следователей Хитрой Шестеренки!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите выцветшую открытку ко дню всех влюбленных детективу Крямсу Гвоздезубу в Оргриммар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что это тут у нас?$B$BОго, это уже серьезно. Очень серьезно. Целая куча головоломных деталей в одной упаковке. Спасибо, ты очень $Gпомог:помогла; нам в расследовании. Приятно было работать с тобой.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты позаботился об этих коварных злодеях?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к детективу Крямсу Гвоздезубу в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (14484,'Голова змеи','В офицерском лагере нас учат всегда отрубать змее голову. Не очень умный совет, учитывая то, что мы никогда не имели дела со змеями, но сейчас в нем есть смысл.$b$bВозьми здесь людей и убей лорда Кассара.','Убейте лорда Кассара в храме Зин-Малор.','Рад, что ты на нашей стороне, солдат.','Вернитесь к сержанту Зелксу в руины Эльдарата.','Чем крупнее враг, тем больше должна быть бомба.','Лорд Кассар') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Голова змеи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В офицерском лагере нас учат всегда отрубать змее голову. Не очень умный совет, учитывая то, что мы никогда не имели дела со змеями, но сейчас в нем есть смысл.$b$bВозьми здесь людей и убей лорда Кассара.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте лорда Кассара в храме Зин-Малор.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Рад, что ты на нашей стороне, солдат.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к сержанту Зелксу в руины Эльдарата.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Чем крупнее враг, тем больше должна быть бомба.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Лорд Кассар',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (14485,'Будем надеяться, что это уничтожит основной источник их магии. Вообще-то на самом деле это только предположение. Но кто же откажется от возможности лишний раз что-то повзрывать.','Вернитесь к сержанту Зелксу в руины Эльдарата.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Будем надеяться, что это уничтожит основной источник их магии. Вообще-то на самом деле это только предположение. Но кто же откажется от возможности лишний раз что-то повзрывать.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к сержанту Зелксу в руины Эльдарата.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14486,'Доставка заказа','Эй, $gприятель:подруга;! Хочешь быстро заработать?$b$bПринеси мне все скрижали высокорожденных, какие найдешь в руинах.','Соберите 12 скрижалей высокорожденных в руинах Эльдарата.','Отлично. Вот твоя доля.$B$BС тобой приятно иметь дело.','Эльфы Крови их оценивают очень высоко. Бешеных денег стоят.','Вернитесь к Торе Галотрикс в руины Эльдарата.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Доставка заказа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эй, $gприятель:подруга;! Хочешь быстро заработать?$b$bПринеси мне все скрижали высокорожденных, какие найдешь в руинах.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 12 скрижалей высокорожденных в руинах Эльдарата.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично. Вот твоя доля.$B$BС тобой приятно иметь дело.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Эльфы Крови их оценивают очень высоко. Бешеных денег стоят.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Торе Галотрикс в руины Эльдарата.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14487,'Все еще бьющееся сердце','Командующий Молотов нашел кое-кого в секретной лаборатории, кто хочет купить виденный тобою ранее артефакт.$b$bНаверняка он все еще в центре руин с верховной жрицей, где ты его и $gзаметил:заметила; в первый раз. Доставь его сюда в целости и сохранности, солдат.','Найдите сердце Арккорока в центре руин Эльдарата.','Ха-ха-ха! Оно ОГРОМНОЕ!$B$BКогда тут все придет в порядок и ты будешь готов, ты-то и отнесешь его дядюшке Бедламу.','Как же мне нравится, когда люди бросают бесценные артефакты где попало.','Вернитесь к капитану Торку в руины Эльдарата.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Все еще бьющееся сердце',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Командующий Молотов нашел кое-кого в секретной лаборатории, кто хочет купить виденный тобою ранее артефакт.$b$bНаверняка он все еще в центре руин с верховной жрицей, где ты его и $gзаметил:заметила; в первый раз. Доставь его сюда в целости и сохранности, солдат.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите сердце Арккорока в центре руин Эльдарата.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ха-ха-ха! Оно ОГРОМНОЕ!$B$BКогда тут все придет в порядок и ты будешь готов, ты-то и отнесешь его дядюшке Бедламу.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как же мне нравится, когда люди бросают бесценные артефакты где попало.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Торку в руины Эльдарата.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (14488,'Получите, распишитесь','Непросто было меня найти, да? Ну да ладно, пора действовать. Сейчас или никогда.$b$bВозьми этот набор и отправляйся вглубь крепости, чтобы передать документы главе этой мерзоносной фармацевтической корпорации, Хаммелу.$B$BВ сундучке лежат сами бумаги и некоторые нейтрализаторы газов. Они защитят тебя от любых неприятных сюрпризов, которые могут встретиться на пути.','Отнесите повестку в суд аптекарю Хаммелу в Крепость Темного Клыка.','Отнесите повестку в суд аптекарю Хаммелу в Крепость Темного Клыка.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Получите, распишитесь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Непросто было меня найти, да? Ну да ладно, пора действовать. Сейчас или никогда.$b$bВозьми этот набор и отправляйся вглубь крепости, чтобы передать документы главе этой мерзоносной фармацевтической корпорации, Хаммелу.$B$BВ сундучке лежат сами бумаги и некоторые нейтрализаторы газов. Они защитят тебя от любых неприятных сюрпризов, которые могут встретиться на пути.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите повестку в суд аптекарю Хаммелу в Крепость Темного Клыка.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите повестку в суд аптекарю Хаммелу в Крепость Темного Клыка.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (14491,'Беспокойная земля','Еще недавно группа дворфов, пришедших непрошенными в наши владения к западу отсюда, перекапывала песок в поисках сокровищ. А когда сама земля раскололась, ее духи, и без того потревоженные вторжением, поднялись и потребовали возмездия.$b$bЭти духи до сих пор витают над бывшим местом раскопок, $n. Мы должны вернуть им покой.$b$bВозьми с собой на запад этот барабан и поиграй духам. Ритм должен усмирить их ярость.','Используйте барабан успокоения Земли, чтобы успокоить 6 потревоженных духов земли.','Вернитесь к Ахмо Громовому Рогу в деревню Кровавого Копыта.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Беспокойная земля',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Еще недавно группа дворфов, пришедших непрошенными в наши владения к западу отсюда, перекапывала песок в поисках сокровищ. А когда сама земля раскололась, ее духи, и без того потревоженные вторжением, поднялись и потребовали возмездия.$b$bЭти духи до сих пор витают над бывшим местом раскопок, $n. Мы должны вернуть им покой.$b$bВозьми с собой на запад этот барабан и поиграй духам. Ритм должен усмирить их ярость.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте барабан успокоения Земли, чтобы успокоить 6 потревоженных духов земли.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ахмо Громовому Рогу в деревню Кровавого Копыта.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (20438,'Подходящая маскировка','Заслать тебя в Прибежище Похитителя Солнца будет нелегко. Туда допускаются только обладатели гербовых накидок Похитителей Солнца. Если бы нам только удалось заполучить одну из них, остальное можно было бы решить с помощью пары заклинаний.$B$BНо у меня есть идея! На балконе над "Нитями судьбы" стоит некто Шанди Шикблеск. Я его пару раз выручал в прошлом, так что он задолжал мне ответную услугу. Он стирает одежду многих граждан этого города. Может быть, он согласится одолжить тебе гербовую накидку...','Позаимствуйте у Шанди Шикблеска гербовую накидку.','Я так и знал, что Шанди найдет выход из ситуации. Сейчас я наложу чары на эту накидку, и ты сможешь ее примерить. Чем быстрее ты вернешься, тем быстрее мы отдадим ее обратно Шанди. Возможно, за это время ее владелец не успеет хватиться своей гербовой накидки.','Ну что, Шанди помог тебе добыть гербовую накидку?','Вернитесь к чародею Тибалину в Серебряный Анклав, что в Даларане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подходящая маскировка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Заслать тебя в Прибежище Похитителя Солнца будет нелегко. Туда допускаются только обладатели гербовых накидок Похитителей Солнца. Если бы нам только удалось заполучить одну из них, остальное можно было бы решить с помощью пары заклинаний.$B$BНо у меня есть идея! На балконе над "Нитями судьбы" стоит некто Шанди Шикблеск. Я его пару раз выручал в прошлом, так что он задолжал мне ответную услугу. Он стирает одежду многих граждан этого города. Может быть, он согласится одолжить тебе гербовую накидку...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Позаимствуйте у Шанди Шикблеска гербовую накидку.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я так и знал, что Шанди найдет выход из ситуации. Сейчас я наложу чары на эту накидку, и ты сможешь ее примерить. Чем быстрее ты вернешься, тем быстрее мы отдадим ее обратно Шанди. Возможно, за это время ее владелец не успеет хватиться своей гербовой накидки.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, Шанди помог тебе добыть гербовую накидку?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к чародею Тибалину в Серебряный Анклав, что в Даларане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (20439,'Встреча с магистром Хаторелем','Я зачаровал эту гербовую накидку особым заклинанием, которое позволит тебе пробраться мимо охранников Прибежища Похитителя Солнца. Оно будет действовать недолго, но за это время ты $gдолжен:должна; успеть найти бар "Грязное животное" и встретиться там с представителем Похитителей Солнца, этим магистром Хаторелем.$B$BВозьми у него копию "Древних клинков драконьей ковки", которую его люди одолжили в Храме Драконьего Покоя, и сразу же возвращайся ко мне.','Возьмите книгу "Древние клинки драконьей ковки" у магистра Хатореля из Прибежища Похитителя Солнца.','Превосходно! Теперь, когда книга в наших руках, мы должны как можно скорее доставить ее Каладису Сияющему Копью. Нельзя допустить, чтобы она снова оказалась у Похитителей Солнца.$B$BА я позабочусь о том, чтобы Шанди Шикблеск получил обратно свою накидку и солидную награду за помощь.','Книга у тебя?','Вернитесь к чародею Тибалину в Серебряный Анклав, что в Даларане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Встреча с магистром Хаторелем',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я зачаровал эту гербовую накидку особым заклинанием, которое позволит тебе пробраться мимо охранников Прибежища Похитителя Солнца. Оно будет действовать недолго, но за это время ты $gдолжен:должна; успеть найти бар "Грязное животное" и встретиться там с представителем Похитителей Солнца, этим магистром Хаторелем.$B$BВозьми у него копию "Древних клинков драконьей ковки", которую его люди одолжили в Храме Драконьего Покоя, и сразу же возвращайся ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возьмите книгу "Древние клинки драконьей ковки" у магистра Хатореля из Прибежища Похитителя Солнца.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Превосходно! Теперь, когда книга в наших руках, мы должны как можно скорее доставить ее Каладису Сияющему Копью. Нельзя допустить, чтобы она снова оказалась у Похитителей Солнца.$B$BА я позабочусь о том, чтобы Шанди Шикблеск получил обратно свою накидку и солидную награду за помощь.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Книга у тебя?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к чародею Тибалину в Серебряный Анклав, что в Даларане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (20440,'Отравленная вода','Наши священные колодцы были отравлены, и мне нужна твоя помощь, чтобы их очистить.$b$bЯ должен создать тотем очищения, а потом ты отнесешь этот тотем к колодцу и совершишь обряд очищения.$b$bСначала сделаем тотем для колодца Заиндевевшего Копыта. Земля поможет нам. Принеси мне лапы волков прерий и когти взрослых долгоногов. И тех, и других ты найдешь на юго-западе.$b$bВозвращайся ко мне с лапами и когтями, $n.','Вернитесь к Муллу Громовому Рогу в деревню Кровавого Копыта.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отравленная вода',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наши священные колодцы были отравлены, и мне нужна твоя помощь, чтобы их очистить.$b$bЯ должен создать тотем очищения, а потом ты отнесешь этот тотем к колодцу и совершишь обряд очищения.$b$bСначала сделаем тотем для колодца Заиндевевшего Копыта. Земля поможет нам. Принеси мне лапы волков прерий и когти взрослых долгоногов. И тех, и других ты найдешь на юго-западе.$b$bВозвращайся ко мне с лапами и когтями, $n.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Муллу Громовому Рогу в деревню Кровавого Копыта.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (20441,'Обряд прозрения','Убедись, что ты $gготов:готова; оставить деревню Кровавого Копыта позади, $n. Следующий этап твоего путешествия уведет тебя далеко от этих мест.$b$bТвоя дорога идет вперед, через поля Мулгора. Мать-Земля будет с тобой на протяжении всего пути. Когда будешь $gготов:готова;, выпей воды перед костром племени. Выпитая тобой священная вода заставит твои глаза распахнуться и позволит духам вести тебя.','Выпейте воду провидения перед костром племени в деревне Кровавого Копыта.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обряд прозрения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Убедись, что ты $gготов:готова; оставить деревню Кровавого Копыта позади, $n. Следующий этап твоего путешествия уведет тебя далеко от этих мест.$b$bТвоя дорога идет вперед, через поля Мулгора. Мать-Земля будет с тобой на протяжении всего пути. Когда будешь $gготов:готова;, выпей воды перед костром племени. Выпитая тобой священная вода заставит твои глаза распахнуться и позволит духам вести тебя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выпейте воду провидения перед костром племени в деревне Кровавого Копыта.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (23733,'Обряды Матери-Земли','Если ты уже готов покинуть Лагерь Нараче, я помогу тебе вызвать духов. Они тебя проводят.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обряды Матери-Земли',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Если ты уже готов покинуть Лагерь Нараче, я помогу тебе вызвать духов. Они тебя проводят.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (24215,'Смотри, $n. Это равнины Мулгора – наш дом, колыбель самой Матери-Земли. Здесь, в этом цветущем и мирном краю она дает нам все необходимое для жизни. Тебе предстоит защищать эту землю с оружием в руках.$B$BТвой путь будет долгим и трудным, он приведет тебя на самые темные окраины этого мира – и еще дальше.$B$BПрямо под нами находится деревня Кровавого Копыта. Первый шаг на твоем долгом пути. Выпей воду провидения, и духи проводят тебя туда.','Выпейте воду провидения.','Добро пожаловать в деревню Кровавого Копыта! Рад, что ты благополучно добрался.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Смотри, $n. Это равнины Мулгора – наш дом, колыбель самой Матери-Земли. Здесь, в этом цветущем и мирном краю она дает нам все необходимое для жизни. Тебе предстоит защищать эту землю с оружием в руках.$B$BТвой путь будет долгим и трудным, он приведет тебя на самые темные окраины этого мира – и еще дальше.$B$BПрямо под нами находится деревня Кровавого Копыта. Первый шаг на твоем долгом пути. Выпей воду провидения, и духи проводят тебя туда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выпейте воду провидения.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Добро пожаловать в деревню Кровавого Копыта! Рад, что ты благополучно добрался.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (24216,'Орда в долгу перед тобой, $n. Твой народ гордится твоей отвагой на защите наших земель.','Ты уже вернулся, $n. Ты принес новости о победе?') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Орда в долгу перед тобой, $n. Твой народ гордится твоей отвагой на защите наших земель.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты уже вернулся, $n. Ты принес новости о победе?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (24217,'Орда в долгу перед тобой, $n. Твой народ гордится твоей отвагой на защите наших земель.','Ты уже вернулся, $n. Ты принес новости о победе?') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Орда в долгу перед тобой, $n. Твой народ гордится твоей отвагой на защите наших земель.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты уже вернулся, $n. Ты принес новости о победе?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (24218,'Призыв к оружию: Ущелье Песни Войны','Среброкрылые Часовые охраняют леса в Ущелье Песни Войны.Мы помогаем им сохранить этот лес, но делаем это не только из любви к природе – он представляет собой естественную преграду для наступления сил Орды.$B$BНо сейчас им как никогда нужна наша помощь. Мы должны послать подкрепление незамедлительно – иначе вместо Ясеневого леса мы вскоре увидим бесплодные Степи!','Победите на поле боя Ущелья Песни Войны и вернитесь к бригадному генералу Альянса в любую из столиц Альянса, на Озеро Ледяных Оков, в Даларан или в Шаттрат.','Славная работа, $n. Мы должны любой ценой обеспечить нерушимость наших границ!','Поведай мне, $n, вести с передовой.','Победа в Ущелье Песни Войны','Вернитесь к бригадному генералу Альянса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Призыв к оружию: Ущелье Песни Войны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Среброкрылые Часовые охраняют леса в Ущелье Песни Войны.Мы помогаем им сохранить этот лес, но делаем это не только из любви к природе – он представляет собой естественную преграду для наступления сил Орды.$B$BНо сейчас им как никогда нужна наша помощь. Мы должны послать подкрепление незамедлительно – иначе вместо Ясеневого леса мы вскоре увидим бесплодные Степи!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите на поле боя Ущелья Песни Войны и вернитесь к бригадному генералу Альянса в любую из столиц Альянса, на Озеро Ледяных Оков, в Даларан или в Шаттрат.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Славная работа, $n. Мы должны любой ценой обеспечить нерушимость наших границ!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Поведай мне, $n, вести с передовой.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Победа в Ущелье Песни Войны',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к бригадному генералу Альянса.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (24219,'Призыв к оружию: Ущелье Песни Войны','Среброкрылые Часовые охраняют леса в Ущелье Песни Войны.Мы помогаем им сохранить этот лес, но делаем это не только из любви к природе – он представляет собой естественную преграду для наступления сил Орды.$B$BНо сейчас им как никогда нужна наша помощь. Мы должны послать подкрепление незамедлительно – иначе вместо Ясеневого леса мы вскоре увидим бесплодные Степи!','Победите на поле боя Ущелья Песни Войны и вернитесь к бригадному генералу Альянса в любую из столиц Альянса, на Озеро Ледяных Оков, в Даларан или в Шаттрат.','Славная работа, $n. Мы должны любой ценой обеспечить нерушимость наших границ!','Поведай мне, $n, вести с передовой.','Победа в Ущелье Песни Войны','Вернитесь к бригадному генералу Альянса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Призыв к оружию: Ущелье Песни Войны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Среброкрылые Часовые охраняют леса в Ущелье Песни Войны.Мы помогаем им сохранить этот лес, но делаем это не только из любви к природе – он представляет собой естественную преграду для наступления сил Орды.$B$BНо сейчас им как никогда нужна наша помощь. Мы должны послать подкрепление незамедлительно – иначе вместо Ясеневого леса мы вскоре увидим бесплодные Степи!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите на поле боя Ущелья Песни Войны и вернитесь к бригадному генералу Альянса в любую из столиц Альянса, на Озеро Ледяных Оков, в Даларан или в Шаттрат.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Славная работа, $n. Мы должны любой ценой обеспечить нерушимость наших границ!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Поведай мне, $n, вести с передовой.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Победа в Ущелье Песни Войны',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к бригадному генералу Альянса.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (24220,'Призыв к оружию: Низина Арати','Беда битвы на несколько фронтов, $gпарень:подруга;, в том, что приходится рассредотачивать силы, и в результате мы рискуем потерять все!$B$BНам каждый день требуется подкрепление. Сегодня войскам в Низине Арати требуются отважные бойцы.$B$BИди, $n, и принеси нам победу. Мы не можем позволить ордынским отродьям претендовать на ресурсы, которые по праву принадлежат нам!','Победите на поле боя Низины Арати и вернитесь к бригадному генералу Альянса в любую из столиц Альянса, на Озеро Ледяных Оков, в Даларан или в Шаттрат.','Поведай мне, $n, вести с передовой.','Победа в Низине Арати','Вернитесь к бригадному генералу Альянса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Призыв к оружию: Низина Арати',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Беда битвы на несколько фронтов, $gпарень:подруга;, в том, что приходится рассредотачивать силы, и в результате мы рискуем потерять все!$B$BНам каждый день требуется подкрепление. Сегодня войскам в Низине Арати требуются отважные бойцы.$B$BИди, $n, и принеси нам победу. Мы не можем позволить ордынским отродьям претендовать на ресурсы, которые по праву принадлежат нам!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите на поле боя Низины Арати и вернитесь к бригадному генералу Альянса в любую из столиц Альянса, на Озеро Ледяных Оков, в Даларан или в Шаттрат.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Поведай мне, $n, вести с передовой.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Победа в Низине Арати',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к бригадному генералу Альянса.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (24221,'Призыв к оружию: Низина Арати','Альянс вот-вот захватит Низину Арати! Мы немедленно должны послать туда подкрепление, иначе все наши труды пойдут прахом.$B$BНе медли, |3-6($c), отправляйся в Низину Арати и сокруши врагов. Орда победит!','Победите на поле боя Низины Арати и вернитесь к ордынскому вестнику войны в любую из столиц Орды, на Озеро Ледяных Оков, в Даларан или в Шаттрат.','Ты принес великую славу Орде, $n. Твоя победа сегодня принесет тысячу побед завтра!','Ты уже вернулся, $n. Ты принес новости о победе?','Победа в Низине Арати','Вернитесь к ордынскому вестнику войны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Призыв к оружию: Низина Арати',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Альянс вот-вот захватит Низину Арати! Мы немедленно должны послать туда подкрепление, иначе все наши труды пойдут прахом.$B$BНе медли, |3-6($c), отправляйся в Низину Арати и сокруши врагов. Орда победит!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите на поле боя Низины Арати и вернитесь к ордынскому вестнику войны в любую из столиц Орды, на Озеро Ледяных Оков, в Даларан или в Шаттрат.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты принес великую славу Орде, $n. Твоя победа сегодня принесет тысячу побед завтра!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты уже вернулся, $n. Ты принес новости о победе?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Победа в Низине Арати',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ордынскому вестнику войны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (24222,'Call to Arms: Eye of the Storm DEPRECATED','Мы будем сражаться с врагами повсюду – в Азероте и Запределье. $B$BНельзя позволить Альянсу закрепиться в Оке Бури. Брось им вызов сегодня, ибо завтра может быть слишком поздно!','Победите в игре на поле боя Ока Бури и вернитесь к ордынскому вестнику войны в любую из столиц Орды, на Озеро Ледяных Оков, в Даларан или в Шаттрат.','Победа на поле боя Ока Бури','Вернитесь к ордынскому вестнику войны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Call to Arms: Eye of the Storm DEPRECATED',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы будем сражаться с врагами повсюду – в Азероте и Запределье. $B$BНельзя позволить Альянсу закрепиться в Оке Бури. Брось им вызов сегодня, ибо завтра может быть слишком поздно!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите в игре на поле боя Ока Бури и вернитесь к ордынскому вестнику войны в любую из столиц Орды, на Озеро Ледяных Оков, в Даларан или в Шаттрат.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Победа на поле боя Ока Бури',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ордынскому вестнику войны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (24223,'Призыв к оружию: Низина Арати','Беда битвы на несколько фронтов, $gпарень:подруга;, в том, что приходится рассредотачивать силы, и в результате мы рискуем потерять все!$B$BНам каждый день требуется подкрепление. Сегодня войскам в Низине Арати требуются отважные бойцы.$B$BИди, $n, и принеси нам победу. Мы не можем позволить ордынским отродьям претендовать на ресурсы, которые по праву принадлежат нам!','Победите на поле боя Низины Арати и вернитесь к бригадному генералу Альянса в любую из столиц Альянса, на Озеро Ледяных Оков, в Даларан или в Шаттрат.','Прекрасная новость, $n! Если наши тактические действия будут и впредь столь же успешны, Орде очень скоро придется отступать по всем фронтам!','Поведай мне, $n, вести с передовой.','Победа в Низине Арати','Вернитесь к бригадному генералу Альянса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Призыв к оружию: Низина Арати',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Беда битвы на несколько фронтов, $gпарень:подруга;, в том, что приходится рассредотачивать силы, и в результате мы рискуем потерять все!$B$BНам каждый день требуется подкрепление. Сегодня войскам в Низине Арати требуются отважные бойцы.$B$BИди, $n, и принеси нам победу. Мы не можем позволить ордынским отродьям претендовать на ресурсы, которые по праву принадлежат нам!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите на поле боя Низины Арати и вернитесь к бригадному генералу Альянса в любую из столиц Альянса, на Озеро Ледяных Оков, в Даларан или в Шаттрат.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасная новость, $n! Если наши тактические действия будут и впредь столь же успешны, Орде очень скоро придется отступать по всем фронтам!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Поведай мне, $n, вести с передовой.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Победа в Низине Арати',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к бригадному генералу Альянса.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (24224,'Призыв к оружию: Ущелье Песни Войны','Среброкрылые Часовые охраняют леса в Ущелье Песни Войны.Мы помогаем им сохранить этот лес, но делаем это не только из любви к природе – он представляет собой естественную преграду для наступления сил Орды.$B$BНо сейчас им как никогда нужна наша помощь. Мы должны послать подкрепление незамедлительно – иначе вместо Ясеневого леса мы вскоре увидим бесплодные Степи!','Победите на поле боя Ущелья Песни Войны и вернитесь к бригадному генералу Альянса в любую из столиц Альянса, на Озеро Ледяных Оков, в Даларан или в Шаттрат.','Славная работа, $n. Мы должны любой ценой обеспечить нерушимость наших границ!','Поведай мне, $n, вести с передовой.','Победа в Ущелье Песни Войны','Вернитесь к бригадному генералу Альянса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Призыв к оружию: Ущелье Песни Войны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Среброкрылые Часовые охраняют леса в Ущелье Песни Войны.Мы помогаем им сохранить этот лес, но делаем это не только из любви к природе – он представляет собой естественную преграду для наступления сил Орды.$B$BНо сейчас им как никогда нужна наша помощь. Мы должны послать подкрепление незамедлительно – иначе вместо Ясеневого леса мы вскоре увидим бесплодные Степи!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите на поле боя Ущелья Песни Войны и вернитесь к бригадному генералу Альянса в любую из столиц Альянса, на Озеро Ледяных Оков, в Даларан или в Шаттрат.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Славная работа, $n. Мы должны любой ценой обеспечить нерушимость наших границ!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Поведай мне, $n, вести с передовой.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Победа в Ущелье Песни Войны',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к бригадному генералу Альянса.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (24225,'Орда в долгу перед тобой, $n. Твой народ гордится твоей отвагой на защите наших земель.','Ты уже вернулся, $n. Ты принес новости о победе?') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Орда в долгу перед тобой, $n. Твой народ гордится твоей отвагой на защите наших земель.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты уже вернулся, $n. Ты принес новости о победе?',`requestitemstext_loc8`);
