INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (24509,'Temp Quest Record') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Temp Quest Record',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (24510,'В ледяную цитадель','$C! Быстрее, иди сюда, нам надо поговорить.$B$BМоя покровительница, леди Джайна Праудмур, обнаружила брешь в обороне цитадели Ледяной Короны – некое место, известное как Кузня Душ. Она оставила мне поручение найти тех, кто мог бы ей помочь... и я надеюсь, что ты не откажешь в этой просьбе.$B$BПожалуйста, найди ее как можно скорее.','$n! Я рада, что ты $gоткликнулся:откликнулась; на зов.$B$BНам представилась уникальная возможность проникнуть в Цитадель Ледяной Короны, но мы должны действовать быстро, пока Артас не догадался, что происходит.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В ледяную цитадель',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$C! Быстрее, иди сюда, нам надо поговорить.$B$BМоя покровительница, леди Джайна Праудмур, обнаружила брешь в обороне цитадели Ледяной Короны – некое место, известное как Кузня Душ. Она оставила мне поручение найти тех, кто мог бы ей помочь... и я надеюсь, что ты не откажешь в этой просьбе.$B$BПожалуйста, найди ее как можно скорее.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','$n! Я рада, что ты $gоткликнулся:откликнулась; на зов.$B$BНам представилась уникальная возможность проникнуть в Цитадель Ледяной Короны, но мы должны действовать быстро, пока Артас не догадался, что происходит.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24512,'Спасение пленников','Те, кто сдался, когда пала Застава Чести, больше не достойны Орды, |3-6($c). Но я пока не отказываюсь от них. Тюремная башня внизу плохо охраняется. Давай дадим пленникам последний шанс умереть с честью.$b$bЯ закрепил веревки, которые помогут тебе при спуске и при подъеме. Соскользни вниз, возьми конфискованное оружие и отдай его узникам в башне.$b$bИ оставайся у башни, $n! Мы еще не очень хорошо вооружены для штурма.','Возьмите 5 ящиков конфискованного оружия с Заставы Чести и вооружите им 5 узников Когтистых гор. Используйте веревки, чтобы быстро пробраться в лагерь Альянса и быстро исчезнуть оттуда.','Вернитесь к Холгому на Верхнем пути в Южных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спасение пленников',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Те, кто сдался, когда пала Застава Чести, больше не достойны Орды, |3-6($c). Но я пока не отказываюсь от них. Тюремная башня внизу плохо охраняется. Давай дадим пленникам последний шанс умереть с честью.$b$bЯ закрепил веревки, которые помогут тебе при спуске и при подъеме. Соскользни вниз, возьми конфискованное оружие и отдай его узникам в башне.$b$bИ оставайся у башни, $n! Мы еще не очень хорошо вооружены для штурма.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возьмите 5 ящиков конфискованного оружия с Заставы Чести и вооружите им 5 узников Когтистых гор. Используйте веревки, чтобы быстро пробраться в лагерь Альянса и быстро исчезнуть оттуда.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Холгому на Верхнем пути в Южных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24513,'Око за око','Кто идет? Звук твоих шагов не похож на ленивую походку стражника.$b$b$c, говоришь? $gТакой отважный:Такая отважная:c; – и еще на свободе? Я уже потерял надежду. Я утратил зрение и больше не годен для войны.$b$bЯ осмелился заговорить с капитаном Пиком во время зверской экзекуции одного из заключенных. В ответ он ударил меня по голове. И продолжил бить. До тех пор, пока я не ослеп, |3-6($r).$b$bКапитана Пика всегда можно найти на вершине этой башни. Если понятие справедливости тебе не чуждо, принеси мне его глаза.$b$bЕсли же он не расстанется с ними по доброй воле... То его судьба будет решена.','Убейте капитана Пика и принесите Олтаргу его глаза.','Пик – это монстр. Если бы его командование об этом узнало, они бы еще благодарили Орду за то, что его прикончили.','Принесите глаза Пика Олтаргу на Заставе Чести в Южных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Око за око',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кто идет? Звук твоих шагов не похож на ленивую походку стражника.$b$b$c, говоришь? $gТакой отважный:Такая отважная:c; – и еще на свободе? Я уже потерял надежду. Я утратил зрение и больше не годен для войны.$b$bЯ осмелился заговорить с капитаном Пиком во время зверской экзекуции одного из заключенных. В ответ он ударил меня по голове. И продолжил бить. До тех пор, пока я не ослеп, |3-6($r).$b$bКапитана Пика всегда можно найти на вершине этой башни. Если понятие справедливости тебе не чуждо, принеси мне его глаза.$b$bЕсли же он не расстанется с ними по доброй воле... То его судьба будет решена.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте капитана Пика и принесите Олтаргу его глаза.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Пик – это монстр. Если бы его командование об этом узнало, они бы еще благодарили Орду за то, что его прикончили.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите глаза Пика Олтаргу на Заставе Чести в Южных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24514,'Шкуры ящеров','Мы окружены здесь, |3-6($c), с одной стороны ущелье, с другой – войска Альянса, и наши запасы подходят к концу. Но мы, таурены, всегда умели обходиться тем, что есть под рукой.$b$bУ нас нет кузницы, но если достать хорошую крепкую кожу, умелый кожевник сможет залатать и укрепить наши доспехи.$b$bТам внизу площадка для охоты на страхокусов. Их нелегко убить, в частности из-за их жесткой и прочной кожи. Поохоться и принеси их шкуры мне, $n!','Добудьте 8 шкур страхокусов, убивая луговых страхокусов и зубастых страхокусов.','Страхокусы охотятся группами и окружают свою жертву. Да, мы охотимся на них, но при этом мы их уважаем.','Доставьте шкуры Онатай на Охотничий холм в Южных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Шкуры ящеров',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы окружены здесь, |3-6($c), с одной стороны ущелье, с другой – войска Альянса, и наши запасы подходят к концу. Но мы, таурены, всегда умели обходиться тем, что есть под рукой.$b$bУ нас нет кузницы, но если достать хорошую крепкую кожу, умелый кожевник сможет залатать и укрепить наши доспехи.$b$bТам внизу площадка для охоты на страхокусов. Их нелегко убить, в частности из-за их жесткой и прочной кожи. Поохоться и принеси их шкуры мне, $n!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 8 шкур страхокусов, убивая луговых страхокусов и зубастых страхокусов.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Страхокусы охотятся группами и окружают свою жертву. Да, мы охотимся на них, но при этом мы их уважаем.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доставьте шкуры Онатай на Охотничий холм в Южных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (24515,'Сигнал бедствия') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сигнал бедствия',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24517,'Посеять среди них страх','Ты видишь тропу, что лежит перед нами, $n? Это МОЯ тропа. Cобакам из Альянса стоит смотреть по сторонам, если уж им хватает наглости ходить по ней.$b$bПришло время собрать дань! Убей пехотинцев Заставы Чести и посмотрим, насколько быстро побегут они под свои спасительные стены.$b$bНепременно нужно убить и хотя бы одного из их офицеров, патрулирующих дорогу. Они должны понять, что здесь каждому из них грозит опасность.','Убейте 8 пехотинцев Заставы Чести и 1 офицера Заставы Чести.','Вернитесь к Килроку Кровавой Дубине на Охотничий холм в Южных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Посеять среди них страх',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты видишь тропу, что лежит перед нами, $n? Это МОЯ тропа. Cобакам из Альянса стоит смотреть по сторонам, если уж им хватает наглости ходить по ней.$b$bПришло время собрать дань! Убей пехотинцев Заставы Чести и посмотрим, насколько быстро побегут они под свои спасительные стены.$b$bНепременно нужно убить и хотя бы одного из их офицеров, патрулирующих дорогу. Они должны понять, что здесь каждому из них грозит опасность.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 пехотинцев Заставы Чести и 1 офицера Заставы Чести.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Килроку Кровавой Дубине на Охотничий холм в Южных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (24518,'Нижний путь','Эти бумаги были найдены в кожаной сумке, спрятанной под одеждой офицера.$b$bТопографические карты местности вокруг Заставы Чести с чем-то вроде большой незаконченной дороги, пересекающей все Степи и идущей из Терамора. Похоже, Альянс планирует проложить дорогу от побережья в самое сердце Калимдора!$b$bКилрок Кровавая Дубина захочет посмотреть на эти карты.','Доставьте проекты дорог Килроку Кровавой Дубине на Охотничий холм в Южных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нижний путь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти бумаги были найдены в кожаной сумке, спрятанной под одеждой офицера.$b$bТопографические карты местности вокруг Заставы Чести с чем-то вроде большой незаконченной дороги, пересекающей все Степи и идущей из Терамора. Похоже, Альянс планирует проложить дорогу от побережья в самое сердце Калимдора!$b$bКилрок Кровавая Дубина захочет посмотреть на эти карты.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доставьте проекты дорог Килроку Кровавой Дубине на Охотничий холм в Южных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (24519,'Нейтрализация топографа','Все эти карты были нарисованы одной и той же рукой. Я как-то видел топографа человека, который бродил туда-сюда вдоль дороги между хранилищем и густым лесом на востоке.$b$bМы можем поломать их планы, разобравшись с этим топографом, $n.$b$b<Килрок показывает на подпись в нижней части карты>.$b$bКак ты думаешь, что тут написано? "Зьюкс"? Даже имена у людей какие-то слабые и невыразительные. Убей его.','Найдите и убейте топографа Генри Зьюкса.','Вернитесь к Килроку Кровавой Дубине на Охотничий холм в Южных Степях.','Ищи вдоль дороги, ведущей на юг к Заставе Чести.','Генри Зьюкс') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нейтрализация топографа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Все эти карты были нарисованы одной и той же рукой. Я как-то видел топографа человека, который бродил туда-сюда вдоль дороги между хранилищем и густым лесом на востоке.$b$bМы можем поломать их планы, разобравшись с этим топографом, $n.$b$b<Килрок показывает на подпись в нижней части карты>.$b$bКак ты думаешь, что тут написано? "Зьюкс"? Даже имена у людей какие-то слабые и невыразительные. Убей его.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите и убейте топографа Генри Зьюкса.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Килроку Кровавой Дубине на Охотничий холм в Южных Степях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Ищи вдоль дороги, ведущей на юг к Заставе Чести.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Генри Зьюкс',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (24520,'Добрые вести для Хамми','Я бы отпраздновал вместе с тобой, но, похоже, этот дракон действительно задал перцу старушке Каджаро, $n. Так что, наверное, я... э... соберу вещички и сяду на первый же корабль, уходящий с острова!$B$BА тебе, думаю, надо вернуться в штаб и рассказать Хамми, как ты $gвыиграл:выиграла; для нас чемпионский титул. Про дракона и Каджаро ей тоже стоит знать.$B$BУдачи!','Поговорите с Хамми Кофельнагель в штаб-квартире ТКК на Кезане.','Ты не шутишь?! СМЕРТОКРЫЛ? <Хамми на мгновение растерянно умолкает.>$B$BЛадно, ничего страшного. Мы все равно организуем вечеринку. Я уверена, что о драконе позабудут еще раньше, чем она закончится, да и земля перестанет трястись.$B$BВ любом случае, мы сможем зафрахтовать корабль и смыться с острова.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Добрые вести для Хамми',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я бы отпраздновал вместе с тобой, но, похоже, этот дракон действительно задал перцу старушке Каджаро, $n. Так что, наверное, я... э... соберу вещички и сяду на первый же корабль, уходящий с острова!$B$BА тебе, думаю, надо вернуться в штаб и рассказать Хамми, как ты $gвыиграл:выиграла; для нас чемпионский титул. Про дракона и Каджаро ей тоже стоит знать.$B$BУдачи!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Хамми Кофельнагель в штаб-квартире ТКК на Кезане.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты не шутишь?! СМЕРТОКРЫЛ? <Хамми на мгновение растерянно умолкает.>$B$BЛадно, ничего страшного. Мы все равно организуем вечеринку. Я уверена, что о драконе позабудут еще раньше, чем она закончится, да и земля перестанет трястись.$B$BВ любом случае, мы сможем зафрахтовать корабль и смыться с острова.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (24521,'Перепроверка','[Deprecated] $n, Coach Crosscheck, the leader of our fearless Bilgewater Buccaneers, is looking for you.$B$BHe says that the division title against the Steamwheedle Sharks is on the line and that you\'re the only one that can bring it home for us!$B$BHead west into town. You can\'t miss Kajaro Field!','Поговорите с тренером Проверяком на площадке Каджаро на Кезане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Перепроверка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','[Deprecated] $n, Coach Crosscheck, the leader of our fearless Bilgewater Buccaneers, is looking for you.$B$BHe says that the division title against the Steamwheedle Sharks is on the line and that you\'re the only one that can bring it home for us!$B$BHead west into town. You can\'t miss Kajaro Field!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с тренером Проверяком на площадке Каджаро на Кезане.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24522,'Путешествие к Солнечному Колодцу','Как можно быстрее отнеси Кель\'Делар к Солнечному Колодцу! Мы должны поверить словам Утера о том, что оскверненный могуществом Короля-лича клинок не всегда будет тебе подвластен. Ты $gдолжен:должна; отправиться на Остров Кель\'Данас и найти вход в сам Солнечный Колодец. Только он обладает силой очистить меч.$B$BУчти, что стражники Солнечного Колодца не позволят тебе пройти без разрешения, поэтому тебе придется заручиться поддержкой Халдарона Светлого Крыла, начальника охраны.','Поговорите с Халдароном Светлым Крылом у входа на плато Солнечного Колодца на острове Кель\'Данас.','Пропустить тебя в Солнечный Колодец? Это невозможно! Это самое священное и важное место для нашего народа. И мы только недавно смогли вернуть его себе при помощи Армии Расколотого Солнца. Здесь не место туристам и путешественникам.','Что привело тебя сюда?','Вернитесь к Халдарону Светлому Крылу в Деревню Утренней Звезды, что на Острове Кель\'Данас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путешествие к Солнечному Колодцу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как можно быстрее отнеси Кель\'Делар к Солнечному Колодцу! Мы должны поверить словам Утера о том, что оскверненный могуществом Короля-лича клинок не всегда будет тебе подвластен. Ты $gдолжен:должна; отправиться на Остров Кель\'Данас и найти вход в сам Солнечный Колодец. Только он обладает силой очистить меч.$B$BУчти, что стражники Солнечного Колодца не позволят тебе пройти без разрешения, поэтому тебе придется заручиться поддержкой Халдарона Светлого Крыла, начальника охраны.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Халдароном Светлым Крылом у входа на плато Солнечного Колодца на острове Кель\'Данас.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Пропустить тебя в Солнечный Колодец? Это невозможно! Это самое священное и важное место для нашего народа. И мы только недавно смогли вернуть его себе при помощи Армии Расколотого Солнца. Здесь не место туристам и путешественникам.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что привело тебя сюда?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Халдарону Светлому Крылу в Деревню Утренней Звезды, что на Острове Кель\'Данас.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`completedtext_loc8`) VALUES (24523,'Вернитесь к Уне Буйногривой в Лагерь Солнечного Пастбища, что в Мулгоре.') ON DUPLICATE KEY UPDATE `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Уне Буйногривой в Лагерь Солнечного Пастбища, что в Мулгоре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (24525,'Преследование противника','Не каждый, кто сбежал из Таурахо, смог сбежать и из Уна\'фе, $n. Некоторые умерли от ран в дороге. На кого-то напали свинобразы.$b$bЯ возьму на себя невеселую работу по розыску и сбору тел. Но ты тоже можешь кое-что сделать.$b$bЗубастые падальщики, которые рыщут к югу отсюда, находят тела погибших, выгрызают их внутренности, растаскивают конечности. Пожалуйста, займись ими, чтобы я смог совершить похоронные обряды, как подобает.','Убейте 6 зубастых падальщиков.','Итак, все сделано.$B$BВ принципе эти падальщики – часть обычной жизни Матери-Земли. Но сейчас их количество на разоренных как Альянсом, так и в результате катаклизма холмах стремительно увеличивается. С ними нужно бороться.','Вернитесь к Макабе Плоскому Копыту в Лагерь Уна\'фе в Южных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Преследование противника',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не каждый, кто сбежал из Таурахо, смог сбежать и из Уна\'фе, $n. Некоторые умерли от ран в дороге. На кого-то напали свинобразы.$b$bЯ возьму на себя невеселую работу по розыску и сбору тел. Но ты тоже можешь кое-что сделать.$b$bЗубастые падальщики, которые рыщут к югу отсюда, находят тела погибших, выгрызают их внутренности, растаскивают конечности. Пожалуйста, займись ими, чтобы я смог совершить похоронные обряды, как подобает.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 6 зубастых падальщиков.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Итак, все сделано.$B$BВ принципе эти падальщики – часть обычной жизни Матери-Земли. Но сейчас их количество на разоренных как Альянсом, так и в результате катаклизма холмах стремительно увеличивается. С ними нужно бороться.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Макабе Плоскому Копыту в Лагерь Уна\'фе в Южных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24529,'Хуже худшего','Когда несчастные бежали из Таурахо на север, с наступлением ночи они оказались разделены. Многих из них тогда взяли в плен свинобразы из племени Дыбогривов, чьи лагеря разбиты к западу и к юго-западу отсюда.$b$bНе знаю, на что рассчитывали свинобразы, захватывая в плен наших беженцев, но тем самым они вызвали лишь мою ярость. Мы отплатим им той же монетой.$b$bСпаси моих братьев и сестер, заключенных в их лагерях, и убей тех, кто схватил их – свинобразы должны быть наказаны.','Спасите 5 пленных беженцев из Таурахо и убейте 8 терноплетов или бритвостражей из племени Дыбогривов.','Вернитесь к Макабе Плоскому Копыту в Лагерь Уна\'фе в Южных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хуже худшего',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда несчастные бежали из Таурахо на север, с наступлением ночи они оказались разделены. Многих из них тогда взяли в плен свинобразы из племени Дыбогривов, чьи лагеря разбиты к западу и к юго-западу отсюда.$b$bНе знаю, на что рассчитывали свинобразы, захватывая в плен наших беженцев, но тем самым они вызвали лишь мою ярость. Мы отплатим им той же монетой.$b$bСпаси моих братьев и сестер, заключенных в их лагерях, и убей тех, кто схватил их – свинобразы должны быть наказаны.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Спасите 5 пленных беженцев из Таурахо и убейте 8 терноплетов или бритвостражей из племени Дыбогривов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Макабе Плоскому Копыту в Лагерь Уна\'фе в Южных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (24534,'Понятным им языком','Свинобразы нападают, когда чувствуют в жертве слабость. Им понятен только язык силы. Ну так продемонстрируем им силу.$b$b<Макаба вытаскивает из сумки большой рог.>$b$bБез сомнения, это грубый ход, но он подействует. Вожди Дыбогривов используют рога вроде этого, чтобы вызывать друг друга на бой с целью определить лидера.$b$bЯ хочу, чтобы ты $gвызвал:вызвала; на одиночный бой Саблеморда. Победи его на глазах у его соплеменников. Протруби в рог на боевой площадке Дыбогривов к югу отсюда.','Протрубите в рог на боевой площадке Дыбогривов и победите Саблеморда в одиночном бою.','Ну что, сбила спесь с Дыбогривов?','Вернитесь к Макабе Плоскому Копыту в Лагерь Уна\'фе в Южных Степях.','Протрубите в боевой рог, чтобы вызвать Саблеморда.','Саблеморд') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Понятным им языком',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Свинобразы нападают, когда чувствуют в жертве слабость. Им понятен только язык силы. Ну так продемонстрируем им силу.$b$b<Макаба вытаскивает из сумки большой рог.>$b$bБез сомнения, это грубый ход, но он подействует. Вожди Дыбогривов используют рога вроде этого, чтобы вызывать друг друга на бой с целью определить лидера.$b$bЯ хочу, чтобы ты $gвызвал:вызвала; на одиночный бой Саблеморда. Победи его на глазах у его соплеменников. Протруби в рог на боевой площадке Дыбогривов к югу отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Протрубите в рог на боевой площадке Дыбогривов и победите Саблеморда в одиночном бою.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, сбила спесь с Дыбогривов?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Макабе Плоскому Копыту в Лагерь Уна\'фе в Южных Степях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Протрубите в боевой рог, чтобы вызвать Саблеморда.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Саблеморд',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (24535,'Талориен Искатель Рассвета','Если Кель\'Делар действительно у тебя, $n, я, возможно, смогу пропустить тебя в Солнечный Колодец. Как ты помнишь, этим мечом когда-то сражался Талориен Искатель Рассвета, защищая Колодец от Плети. Талориен пал на том месте, которое мы сейчас называем Тропой Мертвых. Ценой своей жизни он выиграл время, необходимое для того, чтобы его люди сумели подготовиться и встретить врага во всеоружии. Останки Талориена покоятся на этом острове в южном конце Тропы. Наведайся туда, и, если дух героя благословит тебя, я разрешу тебе пройти в Солнечный Колодец.','Наведайтесь к останкам Талориена Искателя Рассвета и получите его благословение на владение Кель\'Деларом.','Честно говоря, я не ожидал, что дух Талориена признает в тебе наследного владельца Кель\'Делара, но я склоняю голову перед его решением. Дорога в Солнечный Колодец свободна для тебя. Но помни: эти земли для нас святые, и ты, наш гость, должен вести себя подобающим образом.','Вернитесь к Халдарону Светлому Крылу в Деревню Утренней Звезды, что на Острове Кель\'Данас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Талориен Искатель Рассвета',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если Кель\'Делар действительно у тебя, $n, я, возможно, смогу пропустить тебя в Солнечный Колодец. Как ты помнишь, этим мечом когда-то сражался Талориен Искатель Рассвета, защищая Колодец от Плети. Талориен пал на том месте, которое мы сейчас называем Тропой Мертвых. Ценой своей жизни он выиграл время, необходимое для того, чтобы его люди сумели подготовиться и встретить врага во всеоружии. Останки Талориена покоятся на этом острове в южном конце Тропы. Наведайся туда, и, если дух героя благословит тебя, я разрешу тебе пройти в Солнечный Колодец.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Наведайтесь к останкам Талориена Искателя Рассвета и получите его благословение на владение Кель\'Деларом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Честно говоря, я не ожидал, что дух Талориена признает в тебе наследного владельца Кель\'Делара, но я склоняю голову перед его решением. Дорога в Солнечный Колодец свободна для тебя. Но помни: эти земли для нас святые, и ты, наш гость, должен вести себя подобающим образом.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Халдарону Светлому Крылу в Деревню Утренней Звезды, что на Острове Кель\'Данас.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24536,'Дышать нечем!','С помощью анализатора воздуха Гвоздезуба изучите состав воздуха вокруг шести надушенных стражников, а затем вернитесь к детективу с результатами.','Спасибо тебе, $Gприятель:приятельница;. А ну-ка, давай посмотрим, что у нас здесь.$B$B<Берет устройство из ваших рук и начинает с ним возиться.>','Ты уже $Gпроанализировал:проанализировала; эту вонь, $Gпарень:девочка;?','Вернитесь к детективу Крямсу Гвоздезубу в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дышать нечем!',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','С помощью анализатора воздуха Гвоздезуба изучите состав воздуха вокруг шести надушенных стражников, а затем вернитесь к детективу с результатами.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо тебе, $Gприятель:приятельница;. А ну-ка, давай посмотрим, что у нас здесь.$B$B<Берет устройство из ваших рук и начинает с ним возиться.>',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты уже $Gпроанализировал:проанализировала; эту вонь, $Gпарень:девочка;?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к детективу Крямсу Гвоздезубу в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24539,'Когда деревья атакуют','Этот лагерь был построен на самом краю джунглей, но сейчас буйная растительность практически полностью поглотила его. В этом есть что-то неестественное!$b$bЯ совершила страшную ошибку, отправив наиболее здоровых беженцев на поиски орехов и ягод. Те из них, кто вернулся, рассказывают о том, что растения буквально захватывали их, обвиваясь вокруг ног и даже подвешивая на ветвях. Я беспокоюсь о тех, кто еще не вернулся.$b$b$c, пожалуйста, обыщи джунгли вокруг лагеря и освободи тех, кто оказался в плену разбушевавшейся растительности.','Спасите 5 беженцев из Таурахо, убив хваткие лианы, которые опутывают их.','Вернитесь к Лейн Высокой Траве в Лагерь Уна\'фе в Южных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Когда деревья атакуют',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этот лагерь был построен на самом краю джунглей, но сейчас буйная растительность практически полностью поглотила его. В этом есть что-то неестественное!$b$bЯ совершила страшную ошибку, отправив наиболее здоровых беженцев на поиски орехов и ягод. Те из них, кто вернулся, рассказывают о том, что растения буквально захватывали их, обвиваясь вокруг ног и даже подвешивая на ветвях. Я беспокоюсь о тех, кто еще не вернулся.$b$b$c, пожалуйста, обыщи джунгли вокруг лагеря и освободи тех, кто оказался в плену разбушевавшейся растительности.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Спасите 5 беженцев из Таурахо, убив хваткие лианы, которые опутывают их.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лейн Высокой Траве в Лагерь Уна\'фе в Южных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (24540,'Танец войны','Победите Орно Зловещего Тотема на тропе Каменного Когтя.','Вернитесь к Бейну Кровавому Копыту в Громовом Утесе.','Убейте его!','Орно Зловещий Тотем') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Танец войны',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Орно Зловещего Тотема на тропе Каменного Когтя.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бейну Кровавому Копыту в Громовом Утесе.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Убейте его!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Орно Зловещий Тотем',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (24541,'Позаимствовать духи','Я так и знал, что дело здесь нечисто! Сюда добавлен какой-то химикат, влияющий на подсознание, но с тем количеством, которое у меня есть, хороший анализ не сделаешь. Мне нужно намного больше.\r\n\r\nНо не вздумай покупать духи! Эти негодяи от меня ни гроша не получат. Нет, мы пойдем другим путем.\r\n\r\nСейчас мы замаскируем тебя под посыльного. Я видел, головорезы из химической компании охраняют ящики с товарами возле ворот. Беги мимо, но не останавливайся – иначе они тебя раскусят. Они бросят тебе ящик – хватай его и тащи сюда!','Замаскировавшись под посыльного, отправляйтесь к воротам Оргриммара, возле которых находятся товары Королевской химической компании. Добудьте ящик Королевской компании и вернитесь к детективу Крямсу Гвоздезубу в Оргриммар.','Ну что, $Gприятель:приятельница;, отличная работа! Высший класс. Давай-ка посмотрим, что у нас здесь.$B$B<Открывает ящик и начинает копаться внутри.>','Они бросили тебе ящик, чтобы доставить?','Украдите ящик с духами Королевской химической компании возле Оргриммара.','Вернитесь к детективу Крямсу Гвоздезубу в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Позаимствовать духи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я так и знал, что дело здесь нечисто! Сюда добавлен какой-то химикат, влияющий на подсознание, но с тем количеством, которое у меня есть, хороший анализ не сделаешь. Мне нужно намного больше.\r\n\r\nНо не вздумай покупать духи! Эти негодяи от меня ни гроша не получат. Нет, мы пойдем другим путем.\r\n\r\nСейчас мы замаскируем тебя под посыльного. Я видел, головорезы из химической компании охраняют ящики с товарами возле ворот. Беги мимо, но не останавливайся – иначе они тебя раскусят. Они бросят тебе ящик – хватай его и тащи сюда!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Замаскировавшись под посыльного, отправляйтесь к воротам Оргриммара, возле которых находятся товары Королевской химической компании. Добудьте ящик Королевской компании и вернитесь к детективу Крямсу Гвоздезубу в Оргриммар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну что, $Gприятель:приятельница;, отличная работа! Высший класс. Давай-ка посмотрим, что у нас здесь.$B$B<Открывает ящик и начинает копаться внутри.>',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Они бросили тебе ящик, чтобы доставить?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Украдите ящик с духами Королевской химической компании возле Оргриммара.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к детективу Крямсу Гвоздезубу в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24542,'Необычные цветы','В Степях недавно появился верховный друид Наралекс. Он либо стоит за всем этим безумием, либо, напротив, пытается как-то все исправить. В любом случае, тебе стоит поговорить с ним, пока эти джунгли не захватили весь мир! Его можно найти в небольшом святилище на западе.$b$bПо пути собери несколько образцов растений, чтобы он смог изучить их. Нераспустившиеся цветочные бутоны смогут дать ему наиболее полную информацию обо всем, что недавно произошло здесь.','Соберите 10 необычных цветочных бутонов в Буйных зарослях.','Вернитесь к Наралексу в Буйные заросли в Южных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Необычные цветы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В Степях недавно появился верховный друид Наралекс. Он либо стоит за всем этим безумием, либо, напротив, пытается как-то все исправить. В любом случае, тебе стоит поговорить с ним, пока эти джунгли не захватили весь мир! Его можно найти в небольшом святилище на западе.$b$bПо пути собери несколько образцов растений, чтобы он смог изучить их. Нераспустившиеся цветочные бутоны смогут дать ему наиболее полную информацию обо всем, что недавно произошло здесь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 необычных цветочных бутонов в Буйных зарослях.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Наралексу в Буйные заросли в Южных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (24543,'Разделенная семья','Дети, которых ты здесь видишь, были спасены из Таурахо, когда там начался бой. Я пытаюсь разыскать их родителей.$b$bОдин из тех беженцев, которых ты $gспас:спасла; от свинобразов, говорит, что родители самого сильного ребенка – Кирдж и Мора Жесткий Рог. Кроме того, он сказал, что Кирдж разбил лагерь в Кровавых полях, к северу от места битвы в Таурахо.$b$bПожалуйста, отправляйся туда и сообщи Кирджу Жесткому Рогу, что с его ребенком все в порядке!','<Кирдж внимательно слушает и опускается на колени.>$B$BЖив! Мой мальчик жив! Спасибо матери-земле, у меня все еще есть сын.$B$B<Кирдж берет себя в руки.>$B$BВоин, мать моего мальчика не смогла уйти из Таурахо живой. Я отомщу за ее смерть, даже если это будет означать, что моему сыну придется потерять обоих родителей.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разделенная семья',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Дети, которых ты здесь видишь, были спасены из Таурахо, когда там начался бой. Я пытаюсь разыскать их родителей.$b$bОдин из тех беженцев, которых ты $gспас:спасла; от свинобразов, говорит, что родители самого сильного ребенка – Кирдж и Мора Жесткий Рог. Кроме того, он сказал, что Кирдж разбил лагерь в Кровавых полях, к северу от места битвы в Таурахо.$b$bПожалуйста, отправляйся туда и сообщи Кирджу Жесткому Рогу, что с его ребенком все в порядке!',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Кирдж внимательно слушает и опускается на колени.>$B$BЖив! Мой мальчик жив! Спасибо матери-земле, у меня все еще есть сын.$B$B<Кирдж берет себя в руки.>$B$BВоин, мать моего мальчика не смогла уйти из Таурахо живой. Я отомщу за ее смерть, даже если это будет означать, что моему сыну придется потерять обоих родителей.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`endtext_loc8`) VALUES (24544,'Paul Test Quest','Go to Fort Grookin') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Paul Test Quest',`title_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Go to Fort Grookin',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24545,'Святость и скверна','Я дам тебе одно задание, |3-6($r), хоть это и противоречит моим убеждениям. Скорее всего ты не оправдаешь надежд.$b$bНо лучше забудь мои слова и посвяти все свои силы этому новому заданию. А я дам тебе необходимые знания и ресурсы. $b$bНайди Отмщение Света, молот, брошенный Артасом в Пещере Ледяной Скорби. Если усилить его саронитом и разъедающей кровью поганищ, он нам еще отлично послужит.','Когда вы приближаетесь, пламя кузницы, кажется, горит еще сильнее.','Вернитесь в Кузню рун, что в Цитадели Ледяной Короны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Святость и скверна',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я дам тебе одно задание, |3-6($r), хоть это и противоречит моим убеждениям. Скорее всего ты не оправдаешь надежд.$b$bНо лучше забудь мои слова и посвяти все свои силы этому новому заданию. А я дам тебе необходимые знания и ресурсы. $b$bНайди Отмщение Света, молот, брошенный Артасом в Пещере Ледяной Скорби. Если усилить его саронитом и разъедающей кровью поганищ, он нам еще отлично послужит.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Когда вы приближаетесь, пламя кузницы, кажется, горит еще сильнее.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь в Кузню рун, что в Цитадели Ледяной Короны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (24546,'Отступать некуда','Альянс прошел через Степи, уничтожая все на своем пути. Или мы остановим их, или у нас ничего не останется.$b$bВ Кровавых полях много стратегически важных холмов, отмеченных деревянными башнями и нейтральными серыми знаменами. Надо захватить эти холмы, если мы рассчитываем остановить натиск Альянса!$b$bПоищи башни к северу, востоку и югу от того, что осталось на месте Таурахо. Вывеси вместо нейтрального флага наш и защищай холмы от нападений!','Захватите нейтральный холм в Кровавых полях и защитите его от атак Альянса.','Значит, ты удержал свои земли! Если все будут такими же стойкими, то мы выгоним Альянс с нашей территории.','Вернитесь к Кирджу Жестокому Рогу в Лагерь Вендетты в Южных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отступать некуда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Альянс прошел через Степи, уничтожая все на своем пути. Или мы остановим их, или у нас ничего не останется.$b$bВ Кровавых полях много стратегически важных холмов, отмеченных деревянными башнями и нейтральными серыми знаменами. Надо захватить эти холмы, если мы рассчитываем остановить натиск Альянса!$b$bПоищи башни к северу, востоку и югу от того, что осталось на месте Таурахо. Вывеси вместо нейтрального флага наш и защищай холмы от нападений!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Захватите нейтральный холм в Кровавых полях и защитите его от атак Альянса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Значит, ты удержал свои земли! Если все будут такими же стойкими, то мы выгоним Альянс с нашей территории.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кирджу Жестокому Рогу в Лагерь Вендетты в Южных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (24547,'Пиршество душ','Грань Тьмы – одно из самых могущественных орудий, которым может владеть |3-6($c).$b$bТеперь твоя жажда власти утолена?$b$b<Вы ощущаете на себе проницательный взгляд Могрейна.>$b$bЯ полагаю, что нет. В таком случае, вот мое последнее предупреждение...$b$bТы приступаешь к самой опасной части своей миссии. Обуздай свои желания, ибо если твои устремления порочны, то душа твоя обречена.$b$bЭтот клинок – не более чем пустой сосуд, тень того, чем он может стать.','<Верховный лорд Могрейн пристально смотрит на вас.>$B$BОчевидно, ты успешно преодолел эту часть испытания.$B$BМолись, чтобы судьба и дальше тебе улыбалась...','Вернитесь к верховному лорду Дариону Могрейну в Цитадель Ледяной Короны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пиршество душ',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Грань Тьмы – одно из самых могущественных орудий, которым может владеть |3-6($c).$b$bТеперь твоя жажда власти утолена?$b$b<Вы ощущаете на себе проницательный взгляд Могрейна.>$b$bЯ полагаю, что нет. В таком случае, вот мое последнее предупреждение...$b$bТы приступаешь к самой опасной части своей миссии. Обуздай свои желания, ибо если твои устремления порочны, то душа твоя обречена.$b$bЭтот клинок – не более чем пустой сосуд, тень того, чем он может стать.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Верховный лорд Могрейн пристально смотрит на вас.>$B$BОчевидно, ты успешно преодолел эту часть испытания.$B$BМолись, чтобы судьба и дальше тебе улыбалась...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному лорду Дариону Могрейну в Цитадель Ледяной Короны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24548,'Расколотый трон','Трон Короля-лича некогда служил его тюрьмой. Сам Кил\'джеден выковал сосуд из ледяных кристаллов Круговерти Пустоты с единственной целью – заключить в нем мятежную душу Нер\'зула.$b$bРазбив кристальную тюрьму с помощью Ледяной Скорби, Артас освободил дух Нер\'зула и позволил ему слиться со своей душой. Осколки этого кристалла до сих пор рассыпаны по всей цитадели. $b$bЧтобы сила твоего оружия навеки пребывала в нем, мне потребуются только те осколки, что находились во владении самых могущественных прислужников Короля-лича.','Верховный лорд Могрейн поручил вам собрать 50 осколков Льда Тьмы.$B$BОсколки Льда Тьмы можно получить только в рейде 25 игроков.','Вернитесь к верховному лорду Дариону Могрейну.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Расколотый трон',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Трон Короля-лича некогда служил его тюрьмой. Сам Кил\'джеден выковал сосуд из ледяных кристаллов Круговерти Пустоты с единственной целью – заключить в нем мятежную душу Нер\'зула.$b$bРазбив кристальную тюрьму с помощью Ледяной Скорби, Артас освободил дух Нер\'зула и позволил ему слиться со своей душой. Осколки этого кристалла до сих пор рассыпаны по всей цитадели. $b$bЧтобы сила твоего оружия навеки пребывала в нем, мне потребуются только те осколки, что находились во владении самых могущественных прислужников Короля-лича.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верховный лорд Могрейн поручил вам собрать 50 осколков Льда Тьмы.$B$BОсколки Льда Тьмы можно получить только в рейде 25 игроков.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному лорду Дариону Могрейну.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (24549,'Темная Скорбь...','Верховный лорд Могрейн просит вас принести ему Грань Тьмы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Темная Скорбь...',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верховный лорд Могрейн просит вас принести ему Грань Тьмы.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (24550,'Путешествие в Громовой Утес','Поговорите с Бейном Кровавым Копытом в Громовом Утесе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путешествие в Громовой Утес',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Бейном Кровавым Копытом в Громовом Утесе.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (24551,'Встреча с новым начальником','Вернитесь к полководцу Кровавому Эфесу в Лагерь Вендетты в Южных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Встреча с новым начальником',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к полководцу Кровавому Эфесу в Лагерь Вендетты в Южных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24552,'Гордость льва','Если ты жаждешь отомстить захватчикам Альянса, советую понаблюдать за самыми жестокими хищниками Степей.$b$bЯ говорю о хитрости, силе и коварстве льва, незаметно крадущегося к своей жертве сквозь высокую траву. Пусть они научат тебя тому, как нужно вести эту войну.$b$bПоохоться на равнинных хищников и хозяев стаи, а затем вернись ко мне и расскажи, чему тебе удалось научиться. Обычно их можно найти под сенью больших деревьев.','Убейте равнинных хищников и равнинных хозяев стаи общим числом 5 особей.','Вернитесь к Джорну Небесному Провидцу в Лагерь Вендетты в Южных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гордость льва',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если ты жаждешь отомстить захватчикам Альянса, советую понаблюдать за самыми жестокими хищниками Степей.$b$bЯ говорю о хитрости, силе и коварстве льва, незаметно крадущегося к своей жертве сквозь высокую траву. Пусть они научат тебя тому, как нужно вести эту войну.$b$bПоохоться на равнинных хищников и хозяев стаи, а затем вернись ко мне и расскажи, чему тебе удалось научиться. Обычно их можно найти под сенью больших деревьев.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте равнинных хищников и равнинных хозяев стаи общим числом 5 особей.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джорну Небесному Провидцу в Лагерь Вендетты в Южных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24553,'Очищение Кель\'Делара','Признаюсь, я сомневался в том, что тебе удалось перековать Кель\'Делар и что дух Талориена удостоит тебя вниманием. Ты не представляешь, что означает для меня и моего народа возвращение легендарного меча. $B$BКак и было обещано, я разрешаю тебе пройти к Солнечному Колодцу и встретиться с властителями Луносвета. Погрузи меч в Солнечный Колодец. После очищения его сила будет навеки связана с тобой. Затем отнеси меч Каладису Сияющему Копью в Покой Кель\'Делара.','Окуните закаленный Кель\'Делар в Солнечный Колодец. Когда вы будете готовы войти на плато Солнечного Колодца, обратитесь к хранителю Солнечного Колодца.','Это невероятно, Лолита. Ты действительно совершила невозможное! Все кель\'дорай знают о Талориене Искателе Рассвета и легендарном Кель\'Деларе, но никто и не думал, что меч может быть восстановлен.','Что произошло во время твоего путешествия к Солнечному Колодцу?','Вернитесь к Каладису Сияющему Копью в Покой Кель\'Делара, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Очищение Кель\'Делара',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Признаюсь, я сомневался в том, что тебе удалось перековать Кель\'Делар и что дух Талориена удостоит тебя вниманием. Ты не представляешь, что означает для меня и моего народа возвращение легендарного меча. $B$BКак и было обещано, я разрешаю тебе пройти к Солнечному Колодцу и встретиться с властителями Луносвета. Погрузи меч в Солнечный Колодец. После очищения его сила будет навеки связана с тобой. Затем отнеси меч Каладису Сияющему Копью в Покой Кель\'Делара.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Окуните закаленный Кель\'Делар в Солнечный Колодец. Когда вы будете готовы войти на плато Солнечного Колодца, обратитесь к хранителю Солнечного Колодца.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это невероятно, Лолита. Ты действительно совершила невозможное! Все кель\'дорай знают о Талориене Искателе Рассвета и легендарном Кель\'Деларе, но никто и не думал, что меч может быть восстановлен.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что произошло во время твоего путешествия к Солнечному Колодцу?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Каладису Сияющему Копью в Покой Кель\'Делара, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (24554,'Потертая рукоять','Эта потертая рукоять меча знавала лучшие дни, но даже сейчас по ней можно сказать, что делал ее настоящий мастер.$B$BИзящная гравировка и инкрустация драгоценными камнями свидетельствует о том, что оружие некогда принадлежало знатному человеку. Похитителей Солнца наверняка заинтересует эта находка. Найдите их представителя в Покое Кель\'Делара к югу от ристалища Серебряного Турнира.','Принесите потертую рукоять Миралию Блеску Солнца в Покой Кель\'Делара, что к югу от ристалища Серебряного Турнира.','<Миралий принимает рукоять из ваших рук и внимательно ее изучает.>$B$BГоворишь, это было в цитадели? Как эта рукоять могла там оказаться? Этот меч не мог быть сделан руками Плети.$B$BЛишь немногие обитатели Азерота способны создать оружие такого качества. Мы должны обратиться к ним за советом.','Вернитесь к Миралию Блеску Солнца в Покой Кель\'Делара.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Потертая рукоять',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эта потертая рукоять меча знавала лучшие дни, но даже сейчас по ней можно сказать, что делал ее настоящий мастер.$B$BИзящная гравировка и инкрустация драгоценными камнями свидетельствует о том, что оружие некогда принадлежало знатному человеку. Похитителей Солнца наверняка заинтересует эта находка. Найдите их представителя в Покое Кель\'Делара к югу от ристалища Серебряного Турнира.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите потертую рукоять Миралию Блеску Солнца в Покой Кель\'Делара, что к югу от ристалища Серебряного Турнира.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Миралий принимает рукоять из ваших рук и внимательно ее изучает.>$B$BГоворишь, это было в цитадели? Как эта рукоять могла там оказаться? Этот меч не мог быть сделан руками Плети.$B$BЛишь немногие обитатели Азерота способны создать оружие такого качества. Мы должны обратиться к ним за советом.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Миралию Блеску Солнца в Покой Кель\'Делара.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (24555,'То, что знают драконы','Ошибки быть не может – это рукоять могущественного древнего клинка. Вот только что это был за клинок? Я не могу вспомнить ни одного меча с такой гравировкой, но не все еще потеряно.$B$BМы должны обратиться к Кориалстразу, более известному тебе как Крас. Он – давний друг кель\'дорай и Кирин-Тора. За его плечами мудрость рода красных драконов; наверняка, он сможет нам помочь. Отправляйся за его советом на вершину Храма Драконьего Покоя, после чего поговори с Магистром Хаторелем в даларанском Прибежище Похитителя Солнца.','Поговорите с Красом на вершине Храма Драконьего Покоя.','Мы должны забрать книгу Краса из рук Серебряного союза. Без нее нам никогда не разгадать тайну клинка и не узнать его подлинной силы.','Вернитесь к магистру Хаторелю в заведение Грязное животное, что в Даларане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','То, что знают драконы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ошибки быть не может – это рукоять могущественного древнего клинка. Вот только что это был за клинок? Я не могу вспомнить ни одного меча с такой гравировкой, но не все еще потеряно.$B$BМы должны обратиться к Кориалстразу, более известному тебе как Крас. Он – давний друг кель\'дорай и Кирин-Тора. За его плечами мудрость рода красных драконов; наверняка, он сможет нам помочь. Отправляйся за его советом на вершину Храма Драконьего Покоя, после чего поговори с Магистром Хаторелем в даларанском Прибежище Похитителя Солнца.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Красом на вершине Храма Драконьего Покоя.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мы должны забрать книгу Краса из рук Серебряного союза. Без нее нам никогда не разгадать тайну клинка и не узнать его подлинной силы.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к магистру Хаторелю в заведение Грязное животное, что в Даларане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24556,'Подходящая маскировка','Позаимствуйте у Шанди Шикблеска гербовую накидку.','Я так и знал, что Шанди найдет выход из ситуации. Сейчас я наложу чары на эту накидку, и ты сможешь ее примерить. Чем быстрее ты вернешься, тем быстрее мы отдадим ее обратно Шанди. Возможно, за это время ее владелец не успеет хватиться своей гербовой накидки.','Ну что, Шанди помог тебе добыть гербовую накидку Серебряного союза?','Вернитесь к магистру Хаторелю в заведение Грязное животное, что в Даларане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подходящая маскировка',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Позаимствуйте у Шанди Шикблеска гербовую накидку.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я так и знал, что Шанди найдет выход из ситуации. Сейчас я наложу чары на эту накидку, и ты сможешь ее примерить. Чем быстрее ты вернешься, тем быстрее мы отдадим ее обратно Шанди. Возможно, за это время ее владелец не успеет хватиться своей гербовой накидки.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, Шанди помог тебе добыть гербовую накидку Серебряного союза?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к магистру Хаторелю в заведение Грязное животное, что в Даларане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24557,'Ну что, у этого агента было с собой что-нибудь полезное?','Вернитесь к магистру Хаторелю в заведение Грязное животное, что в Даларане.') ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, у этого агента было с собой что-нибудь полезное?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к магистру Хаторелю в заведение Грязное животное, что в Даларане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24558,'Возвращение к Миралию Блеску Солнца','Принесите книгу "Древние клинки драконьей ковки" Миралию Блеску Солнца в Покой Кель\'Делара.','<Миралий забирает у вас тяжелую книгу и начинает внимательно ее пролистывать.>$B$BАх вот почему символы на рукояти казались мне такими знакомыми... Да, этот меч был точно выкован драконами и передан в дар смертным, но что это был за клинок и как он оказался в Ледяной Короне?','Мы ожидали твоего возвращения. Что тебя задержало?','Вернитесь к Миралию Блеску Солнца в Покой Кель\'Делара.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение к Миралию Блеску Солнца',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите книгу "Древние клинки драконьей ковки" Миралию Блеску Солнца в Покой Кель\'Делара.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Миралий забирает у вас тяжелую книгу и начинает внимательно ее пролистывать.>$B$BАх вот почему символы на рукояти казались мне такими знакомыми... Да, этот меч был точно выкован драконами и передан в дар смертным, но что это был за клинок и как он оказался в Ледяной Короне?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мы ожидали твоего возвращения. Что тебя задержало?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Миралию Блеску Солнца в Покой Кель\'Делара.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24559,'Перековать меч','Нельзя допустить, чтобы великий Кель\'Делар оставался расколотым и обесчещенным. Возьми фрагменты клинка вместе с потертой рукоятью и отправляйся в Яму Сарона, что в цитадели Ледяной Короны.$B$BВ этой яме слуги Короля-лича добывают и обрабатывают саронитовую руду. Только с помощью заряженного саронита можно перековать Кель\'Делар.$B$BТы $gдолжен:должна; собрать саронитовые слитки и перековать меч, вопользовавшись молотом и наковальней начальника кузни.','Возьмите 5 слитков зараженного саронита и молот начальника кузни, чтобы соединить фрагменты Кель\'Делара и создать перекованный Кель\'Делар.','Значит, несмотря на дерзкие речи королевы Лана\'тель, ты все же воссоздал Кель\'Делар! Осталось лишь закалить клинок – и мы покажем ей, как были неосмотрительны ее слова.','Тебе удалось воссоздать Кель\'Делар?','Вернитесь к Миралию Блеску Солнца в Ледяные залы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Перековать меч',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нельзя допустить, чтобы великий Кель\'Делар оставался расколотым и обесчещенным. Возьми фрагменты клинка вместе с потертой рукоятью и отправляйся в Яму Сарона, что в цитадели Ледяной Короны.$B$BВ этой яме слуги Короля-лича добывают и обрабатывают саронитовую руду. Только с помощью заряженного саронита можно перековать Кель\'Делар.$B$BТы $gдолжен:должна; собрать саронитовые слитки и перековать меч, вопользовавшись молотом и наковальней начальника кузни.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возьмите 5 слитков зараженного саронита и молот начальника кузни, чтобы соединить фрагменты Кель\'Делара и создать перекованный Кель\'Делар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Значит, несмотря на дерзкие речи королевы Лана\'тель, ты все же воссоздал Кель\'Делар! Осталось лишь закалить клинок – и мы покажем ей, как были неосмотрительны ее слова.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось воссоздать Кель\'Делар?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Миралию Блеску Солнца в Ледяные залы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24560,'Закалить клинок','Наконец-то фрагменты Кель\'Делара воссоединились, и клинок снова стал целым. Но он еще не готов к битве, ибо для начала его надо закалить. Эти саронитовые зубцы очень хрупкие и могут отколоться в момент удара.$B$BНо глубоко под цитаделью Ледяной Короны есть Кузня Душ, в которой можно закалить подобный клинок. Отнеси Кель\'Делар в обитель Пожирателя Душ и найди там горнило душ. Закали меч и принеси его мне. Я буду ждать тебя в Ледяных залах.','Закалите перекованный Кель\'Делар в горниле душ.','После закалки клинок должен был восстановиться во всем своем былом могуществе. Что же случилось?','Пока клинок не будет закален, он бесполезен.','Вернитесь к Миралию Блеску Солнца в Ледяные залы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Закалить клинок',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наконец-то фрагменты Кель\'Делара воссоединились, и клинок снова стал целым. Но он еще не готов к битве, ибо для начала его надо закалить. Эти саронитовые зубцы очень хрупкие и могут отколоться в момент удара.$B$BНо глубоко под цитаделью Ледяной Короны есть Кузня Душ, в которой можно закалить подобный клинок. Отнеси Кель\'Делар в обитель Пожирателя Душ и найди там горнило душ. Закали меч и принеси его мне. Я буду ждать тебя в Ледяных залах.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Закалите перекованный Кель\'Делар в горниле душ.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','После закалки клинок должен был восстановиться во всем своем былом могуществе. Что же случилось?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Пока клинок не будет закален, он бесполезен.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Миралию Блеску Солнца в Ледяные залы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24561,'Залы Отражений','Отнесите Кель\'Делар в Покои Клинка, что в Залах Отражений.','Что произошло в Залах Отражений?','Вернитесь к Миралию Блеску Солнца в Ледяные залы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Залы Отражений',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите Кель\'Делар в Покои Клинка, что в Залах Отражений.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что произошло в Залах Отражений?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Миралию Блеску Солнца в Ледяные залы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24562,'Путешествие к Солнечному Колодцу','Поговорите с Халдароном Светлым Крылом у входа на плато Солнечного Колодца на острове Кель\'Данас.','Что привело тебя сюда?','Вернитесь к Халдарону Светлому Крылу в Деревню Утренней Звезды, что на Острове Кель\'Данас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путешествие к Солнечному Колодцу',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Халдароном Светлым Крылом у входа на плато Солнечного Колодца на острове Кель\'Данас.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что привело тебя сюда?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Халдарону Светлому Крылу в Деревню Утренней Звезды, что на Острове Кель\'Данас.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24563,'Талориен Искатель Рассвета','Ты ведь работаешь на Миралия Блеска Солнца, верно? Думаю, я знают способ испытать, что за клинок у тебя в руках. Полагаю, тебе известна история этого меча? Им владел Талориен Искатель Рассвета, что защищал Колодец от нашествия Плети. Талориен пал на том месте, что мы сейчас называем Тропой Мертвых. Ценой своей жизни он выиграл время, необходимое для того, чтобы его люди сумели подготовиться и встретить врага во всеоружии. Останки Талориена покоятся на этом острове в южном конце Тропы. Наведайся туда, и, если дух героя благословит тебя, я разрешу тебе пройти в Солнечный Колодец.','Наведайтесь к останкам Талориена Искателя Рассвета и получите его благословение на владение Кель\'Деларом.','Вернитесь к Халдарону Светлому Крылу в Деревню Утренней Звезды, что на Острове Кель\'Данас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Талориен Искатель Рассвета',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты ведь работаешь на Миралия Блеска Солнца, верно? Думаю, я знают способ испытать, что за клинок у тебя в руках. Полагаю, тебе известна история этого меча? Им владел Талориен Искатель Рассвета, что защищал Колодец от нашествия Плети. Талориен пал на том месте, что мы сейчас называем Тропой Мертвых. Ценой своей жизни он выиграл время, необходимое для того, чтобы его люди сумели подготовиться и встретить врага во всеоружии. Останки Талориена покоятся на этом острове в южном конце Тропы. Наведайся туда, и, если дух героя благословит тебя, я разрешу тебе пройти в Солнечный Колодец.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Наведайтесь к останкам Талориена Искателя Рассвета и получите его благословение на владение Кель\'Деларом.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Халдарону Светлому Крылу в Деревню Утренней Звезды, что на Острове Кель\'Данас.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24564,'Очищение Кель\'Делара','Истекают часы изгнания Кель\'Делара. Тебя ждет Солнечный Колодец, $n.$B$BТам ты встретишь Лор\'темара Терона, регента Кель\'Таласа и Верховного магистра Роммата. Будь $gосторожен:осторожна; с ними, не давай вовлечь себя в политические махинации.$B$BСосредоточься на своей миссии. Когда ты будешь $Gготов:готова; завершить восстановление Кель\'Делара, поговори с хранителем Солнечного Колодца. Окуни меч в Солнечный Колодец, а затем отнеси его Миралию Блеску Солнца в Покой Кель\'Делара.','Окуните закаленный Кель\'Делар в Солнечный Колодец. Когда вы будете готовы войти на плато Солнечного Колодца, обратитесь к хранителю Солнечного Колодца.','Вернитесь к Миралию Блеску Солнца в Покой Кель\'Делара, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Очищение Кель\'Делара',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Истекают часы изгнания Кель\'Делара. Тебя ждет Солнечный Колодец, $n.$B$BТам ты встретишь Лор\'темара Терона, регента Кель\'Таласа и Верховного магистра Роммата. Будь $gосторожен:осторожна; с ними, не давай вовлечь себя в политические махинации.$B$BСосредоточься на своей миссии. Когда ты будешь $Gготов:готова; завершить восстановление Кель\'Делара, поговори с хранителем Солнечного Колодца. Окуни меч в Солнечный Колодец, а затем отнеси его Миралию Блеску Солнца в Покой Кель\'Делара.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Окуните закаленный Кель\'Делар в Солнечный Колодец. Когда вы будете готовы войти на плато Солнечного Колодца, обратитесь к хранителю Солнечного Колодца.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Миралию Блеску Солнца в Покой Кель\'Делара, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24565,'Биологическая угроза','Силы, бушевавшие здесь, воздействовали и на живую природу, создав новые, нестабильные, но обладающие огромной силой формы жизни. Если позволить им распространиться за пределы этой рощи, баланс всей существующей экосистемы окажется нарушен. Местная жизнь будет вынуждена уступить место более сильным захватчикам.$b$BТебе необходимо остановить распространение растительности. Возвращайся, когда завершишь работу.','Убейте 5 загадочных страхокусов и 5 загадочных равнинных долгоногов.','Вернитесь к Наралексу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Биологическая угроза',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Силы, бушевавшие здесь, воздействовали и на живую природу, создав новые, нестабильные, но обладающие огромной силой формы жизни. Если позволить им распространиться за пределы этой рощи, баланс всей существующей экосистемы окажется нарушен. Местная жизнь будет вынуждена уступить место более сильным захватчикам.$b$BТебе необходимо остановить распространение растительности. Возвращайся, когда завершишь работу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 5 загадочных страхокусов и 5 загадочных равнинных долгоногов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Наралексу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (24566,'Что посеешь, то и пожнешь','Думаю, благодаря тому, что ты $gпринес:принесла; мне, мы найдем решение. Я наполнил семена хлещущей лозы исцеляющей энергией.$b$bДостаточно просто прикоснуться к ним, и они дадут достаточно силы, чтобы противостоять разрушающему воздействию.$b$bИди и попробуй вылечить мутировавших ящеров и равнинных долгоногов, посыпав их семенами. Доложи мне о результатах.','Примените умиротворяющие семена к 6 загадочным страхокусам или загадочным равнинным долгоногам и посмотрите на результаты.','Ничего себе. Кажется, эту силу трудно контролировать…$B$BПожалуйста, не говори об этом Наралексу. Это только расстроит его.','Вернитесь к Муйону в Буйные заросли в Южных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Что посеешь, то и пожнешь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Думаю, благодаря тому, что ты $gпринес:принесла; мне, мы найдем решение. Я наполнил семена хлещущей лозы исцеляющей энергией.$b$bДостаточно просто прикоснуться к ним, и они дадут достаточно силы, чтобы противостоять разрушающему воздействию.$b$bИди и попробуй вылечить мутировавших ящеров и равнинных долгоногов, посыпав их семенами. Доложи мне о результатах.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Примените умиротворяющие семена к 6 загадочным страхокусам или загадочным равнинным долгоногам и посмотрите на результаты.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ничего себе. Кажется, эту силу трудно контролировать…$B$BПожалуйста, не говори об этом Наралексу. Это только расстроит его.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Муйону в Буйные заросли в Южных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (24567,'Перепроверка','$n, тебя ищет тренер Проверяк, лидер наших бесстрашных "Буканьеров Трюмных Вод".$B$BРешающий матч за звание чемпиона против "Акул Хитрой Шестеренки" уже совсем скоро, и Проверяк говорит, что без тебя нам не вырвать победу.$B$BИди на запад, в город. Площадку Каджаро увидишь сразу. Ее нельзя не заметить!$B$BДавай-давай, слава звезды футбомбы еще никому не повредила!','Поговорите с тренером Проверяком на площадке Каджаро на Кезане.','А вот и ты, малыш! Давай быстрее! Нельзя терять ни минуты! Нужно срочно чинить крошшер.$B$BВ этот раз ты не будешь сидеть на скамейке запасных... ты выиграешь этот матч и принесешь нашей команде чемпионский титул!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Перепроверка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, тебя ищет тренер Проверяк, лидер наших бесстрашных "Буканьеров Трюмных Вод".$B$BРешающий матч за звание чемпиона против "Акул Хитрой Шестеренки" уже совсем скоро, и Проверяк говорит, что без тебя нам не вырвать победу.$B$BИди на запад, в город. Площадку Каджаро увидишь сразу. Ее нельзя не заметить!$B$BДавай-давай, слава звезды футбомбы еще никому не повредила!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с тренером Проверяком на площадке Каджаро на Кезане.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А вот и ты, малыш! Давай быстрее! Нельзя терять ни минуты! Нужно срочно чинить крошшер.$B$BВ этот раз ты не будешь сидеть на скамейке запасных... ты выиграешь этот матч и принесешь нашей команде чемпионский титул!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24568,'На стены!','$n, они собираются у ворот! Альянс пытается силой прорубить себе дорогу в Мулгор, используя пехотные войска для того, чтобы победить стражу.$b$bУ нас не хватает оружия, чтобы защитить свои стены. Остается лишь обливать захватчиков кипящей водой и ждать подмоги... С этим мы справимся.$b$BНо нам нужен кто-то, кто мог бы координировать действия обороны. Только скажи – я дарую тебе орлиный взор, и ты увидишь поле боя с высоты птичьего полета. $b$BТы $gнужен:нужна; нам, $n!','Поговорите с Винноа Сосновый Бор в Кровавых полях, чтобы защитить врата Мулгора от атаки.','Вернитесь к Винноа Сосновый Бор в Лагерь Вендетты в Южных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На стены!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, они собираются у ворот! Альянс пытается силой прорубить себе дорогу в Мулгор, используя пехотные войска для того, чтобы победить стражу.$b$bУ нас не хватает оружия, чтобы защитить свои стены. Остается лишь обливать захватчиков кипящей водой и ждать подмоги... С этим мы справимся.$b$BНо нам нужен кто-то, кто мог бы координировать действия обороны. Только скажи – я дарую тебе орлиный взор, и ты увидишь поле боя с высоты птичьего полета. $b$BТы $gнужен:нужна; нам, $n!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Винноа Сосновый Бор в Кровавых полях, чтобы защитить врата Мулгора от атаки.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Винноа Сосновый Бор в Лагерь Вендетты в Южных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24569,'Прорыв блокады','$n, на Кровавых полях ты $gпоказал:показала; на что ты $gспособен:способна;. Но Альянс все еще грозит нашим друзьям тауренам.$b$bОсадные машины у ворот Мулгора – это как копье, направленное прямо к нашему сердцу. Я хочу, чтобы ты $gпошел:пошла; к воротам, это к югу отсюда, и $gвывел:вывела; из строя эти механизмы.$b$bВозьми вот эти клейкие бомбы. Их сделали наши новые союзники гоблины. Выглядят они, конечно, как покрытые слизью носки со взрывчатым порошком внутри... Но главное, что они работают.','Очень хорошо. Теперь, если они решатся на штурм ворот, им придется иметь дело с пехотой.$B$BДумаешь, им этого захочется?','Почему Гар\'дул позволил Альянсу установить все эти осадные машины? Почему ничего не было предпринято, пока я не оказался здесь? Гар\'дул должен будет за это ответить...','Вернитесь к полководцу Кровавому Эфесу в Лагерь Вендетты в Южных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прорыв блокады',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, на Кровавых полях ты $gпоказал:показала; на что ты $gспособен:способна;. Но Альянс все еще грозит нашим друзьям тауренам.$b$bОсадные машины у ворот Мулгора – это как копье, направленное прямо к нашему сердцу. Я хочу, чтобы ты $gпошел:пошла; к воротам, это к югу отсюда, и $gвывел:вывела; из строя эти механизмы.$b$bВозьми вот эти клейкие бомбы. Их сделали наши новые союзники гоблины. Выглядят они, конечно, как покрытые слизью носки со взрывчатым порошком внутри... Но главное, что они работают.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Очень хорошо. Теперь, если они решатся на штурм ворот, им придется иметь дело с пехотой.$B$BДумаешь, им этого захочется?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Почему Гар\'дул позволил Альянсу установить все эти осадные машины? Почему ничего не было предпринято, пока я не оказался здесь? Гар\'дул должен будет за это ответить...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к полководцу Кровавому Эфесу в Лагерь Вендетты в Южных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24570,'Ловля змей','Разрушения, вызванные высвобожденными здесь энергиями, должны быть тщательно изучены, если мы хотим найти способ справиться с ними.$b$bК счастью, не все живые существа подверглись порче в одинаковой степени. Небольшие змеи пьют мало воды и не едят растений, так что они должны были оказаться наиболее устойчивыми к искажению. Тем не менее и они изменили свою окраску.$b$bПоймай в джунглях несколько змей и принеси их мне, так мы сможем узнать, что тут произошло с живыми существами.','Поймайте 5 ослабших гадюк.','Эти отлично подойдут. В Степях не бывает змей такой яркой окраски, но в остальном они выглядят нормальными.','Ты достаточно собрал? Для качественного исследования нам потребуется несколько экземпляров.','Вернитесь к Муйону в Заросший лагерь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ловля змей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Разрушения, вызванные высвобожденными здесь энергиями, должны быть тщательно изучены, если мы хотим найти способ справиться с ними.$b$bК счастью, не все живые существа подверглись порче в одинаковой степени. Небольшие змеи пьют мало воды и не едят растений, так что они должны были оказаться наиболее устойчивыми к искажению. Тем не менее и они изменили свою окраску.$b$bПоймай в джунглях несколько змей и принеси их мне, так мы сможем узнать, что тут произошло с живыми существами.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поймайте 5 ослабших гадюк.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Эти отлично подойдут. В Степях не бывает змей такой яркой окраски, но в остальном они выглядят нормальными.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты достаточно собрал? Для качественного исследования нам потребуется несколько экземпляров.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Муйону в Заросший лагерь.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (24571,'Семена хлещущей лозы','Должен быть способ исцелить эти несчастные существа, сохранив им жизнь. У меня есть идея, но мне потребуется твоя помощь, |3-6($c).$b$bРастения хлещущей лозы, которые бродят здесь, сейчас плодоносят, их семена полны изначальной энергии этих мест. Собери семена, принеси мне, и мы посмотрим, что можно сделать.','Соберите 4 скорченных семечка хлещущей лозы.','Ничего себе, какие они... активные. Как бы то ни было, это значит лишь, что мы должны действовать быстро, пока разрушающее воздействие не усилилось.','Вернитесь к Муйону в Буйные заросли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Семена хлещущей лозы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Должен быть способ исцелить эти несчастные существа, сохранив им жизнь. У меня есть идея, но мне потребуется твоя помощь, |3-6($c).$b$bРастения хлещущей лозы, которые бродят здесь, сейчас плодоносят, их семена полны изначальной энергии этих мест. Собери семена, принеси мне, и мы посмотрим, что можно сделать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 4 скорченных семечка хлещущей лозы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ничего себе, какие они... активные. Как бы то ни было, это значит лишь, что мы должны действовать быстро, пока разрушающее воздействие не усилилось.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Муйону в Буйные заросли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (24572,'Возвращение Таурахо','Ты $gпоказал:показала; себя с лучшей стороны у ворот, $n! Альянс отступает. Но я не удовлетворен.$b$bОни захватили Таурахо, который для нас нечто большее, чем обычный охотничий лагерь. Эти "воины Альянса" показали свое истинное лицо – они просто банда мясников.$b$bИ сейчас группа людей все еще рыщет по пепелищу.$b$b<Кровавый Эфес отшвыривает топор в грязь.>$b$bЗаставь их страдать.','Убейте 8 мародеров Таурахо на руинах Таурахо.','Отлично! Я повешу их тела вдоль Золотого пути, чтобы Альянс понял, с кем имеет дело.','Вернитесь к полководцу Кровавому Эфесу в Лагерь Вендетты в Южных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение Таурахо',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gпоказал:показала; себя с лучшей стороны у ворот, $n! Альянс отступает. Но я не удовлетворен.$b$bОни захватили Таурахо, который для нас нечто большее, чем обычный охотничий лагерь. Эти "воины Альянса" показали свое истинное лицо – они просто банда мясников.$b$bИ сейчас группа людей все еще рыщет по пепелищу.$b$b<Кровавый Эфес отшвыривает топор в грязь.>$b$bЗаставь их страдать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 мародеров Таурахо на руинах Таурахо.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! Я повешу их тела вдоль Золотого пути, чтобы Альянс понял, с кем имеет дело.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к полководцу Кровавому Эфесу в Лагерь Вендетты в Южных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24573,'Последние почести','Теперь, когда непосредственной угрозы нет, не $gмог:могла; бы ты помочь с одним не столь веселым делом?$b$bМы, таурены, не хороним своих мертвецов. Мы подготавливаем тело к возрождению в виде стихий и затем переносим его в одно из священных погребальных мест. Для погибших в Таурахо не были исполнены погребальные ритуалы, и, боюсь, что необразованные солдаты Альянса сожгут тела мертвых до того, как ритуал будет совершен.$b$b$n, возьми, пожалуйста, этот тотем и сделай все, что нужно, для Крульмоо, Дранха, Йонады и Омусы. Они... так и не смогли выбраться оттуда.','Примените погребальный тотем к телам Крульмоо, Дранха, Йонада и Омусы на руинах Таурахо.','<Винноа склоняет голову.>Спасибо тебе.','Их души нашли успокоение в лоне Матери-Земли?','Вернитесь к Винноа Сосновый Бор в Лагерь Вендетты в Южных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Последние почести',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда непосредственной угрозы нет, не $gмог:могла; бы ты помочь с одним не столь веселым делом?$b$bМы, таурены, не хороним своих мертвецов. Мы подготавливаем тело к возрождению в виде стихий и затем переносим его в одно из священных погребальных мест. Для погибших в Таурахо не были исполнены погребальные ритуалы, и, боюсь, что необразованные солдаты Альянса сожгут тела мертвых до того, как ритуал будет совершен.$b$b$n, возьми, пожалуйста, этот тотем и сделай все, что нужно, для Крульмоо, Дранха, Йонады и Омусы. Они... так и не смогли выбраться оттуда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Примените погребальный тотем к телам Крульмоо, Дранха, Йонада и Омусы на руинах Таурахо.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Винноа склоняет голову.>Спасибо тебе.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Их души нашли успокоение в лоне Матери-Земли?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Винноа Сосновый Бор в Лагерь Вендетты в Южных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (24574,'Собрать плоды хаоса','Я в самом деле посеял хаос, теперь время пожинать плоды.$b$bМножество неуклюжих выростов растений толпами бродят вокруг, $n. Они – красноречивый пример того, как неустойчивые силы видоизменили эту область. Убей столько, сколько сможешь, мы должны суметь остановить этот неконтролируемый рост.$b$bА раз уж ты этим занимаешься... будь начеку и обращай внимание на те их части, которые особенно сильно изменены. Собери их все и принеси их мне.','Убейте 5 выростов и найдите извивающееся сердце.','<Наралекс медленно берет у вас извивающееся сердце, видно, как он взволнован.>$B$BЯ был дураком. Все это время ответ был у меня перед глазами, а я не хотел замечать его... И эта грязная штука лишнее тому доказательство.$B$BНам с тобой надо многое сделать.','Вернитесь к Наралексу в Буйные заросли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Собрать плоды хаоса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я в самом деле посеял хаос, теперь время пожинать плоды.$b$bМножество неуклюжих выростов растений толпами бродят вокруг, $n. Они – красноречивый пример того, как неустойчивые силы видоизменили эту область. Убей столько, сколько сможешь, мы должны суметь остановить этот неконтролируемый рост.$b$bА раз уж ты этим занимаешься... будь начеку и обращай внимание на те их части, которые особенно сильно изменены. Собери их все и принеси их мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 5 выростов и найдите извивающееся сердце.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Наралекс медленно берет у вас извивающееся сердце, видно, как он взволнован.>$B$BЯ был дураком. Все это время ответ был у меня перед глазами, а я не хотел замечать его... И эта грязная штука лишнее тому доказательство.$B$BНам с тобой надо многое сделать.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Наралексу в Буйные заросли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (24575,'День освобождения','Вернитесь к Лорне Краули на Пост у стойл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','День освобождения',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лорне Краули на Пост у стойл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24576,'Разговор по душам...','<Рока с отвращением выслушивает, почему вы пытаетесь выследить Снивела.> $B$BТо есть, все это время я была под действием заклинания этого алхимика? Как я только могла купиться на эту подставу! Ну, попадись мне только этот маленький мерзавец – разорву на части!$B$BЕсли он закончил все свои дела, то должен направляться к башне дирижаблей, что в центре Оргриммара. $n, нельзя допустить, чтобы он поднялся на борт и улетел, избежав наказания!$B$BБеги к башне как можно быстрее!','Отправляйтесь к башне дирижаблей, что в центре Оргриммара, и допросите Снивела Ржавстера. Постарайтесь получить хоть какие-нибудь доказательства.','Ты $Gпринес:принесла; его гроссбух? Очень хорошо, $N. Здесь должна быть куча ценной информации!','Ты $Gнашел:нашла; этого парня – или он от тебя улизнул?','Вернитесь к детективу Крямсу Гвоздезубу в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разговор по душам...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Рока с отвращением выслушивает, почему вы пытаетесь выследить Снивела.> $B$BТо есть, все это время я была под действием заклинания этого алхимика? Как я только могла купиться на эту подставу! Ну, попадись мне только этот маленький мерзавец – разорву на части!$B$BЕсли он закончил все свои дела, то должен направляться к башне дирижаблей, что в центре Оргриммара. $n, нельзя допустить, чтобы он поднялся на борт и улетел, избежав наказания!$B$BБеги к башне как можно быстрее!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь к башне дирижаблей, что в центре Оргриммара, и допросите Снивела Ржавстера. Постарайтесь получить хоть какие-нибудь доказательства.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты $Gпринес:принесла; его гроссбух? Очень хорошо, $N. Здесь должна быть куча ценной информации!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gнашел:нашла; этого парня – или он от тебя улизнул?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к детективу Крямсу Гвоздезубу в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (24577,'Визит в Крепость Отчаяния','Благодаря тебе острая угроза миновала. Но моя работа в Степях только начинается.$b$bПока здесь командовал полководец Гар\'дул, захватили Заставу Чести и разгромили Таурахо. Вождь послал меня, чтобы я навел здесь порядок.$b$bОтправляйся на юг в Крепость Отчаяния и сообщи Гар\'дулу, что пришел час расплаты.$b$bКогда будешь $gготов:готова; к выходу, скажи мне, я отправлю вместе с тобой свой передовой отряд.','Поговорите с полководцем Кровавым Эфесом, затем отправляйтесь в Крепость Отчаяния и сообщите Гар\'дулу, что Кровавый Эфес скоро будет.','<Гар\'дул покрывается холодным потом.>$B$BПослушай, давай обсудим это в другом месте, не перед всеми...','Поговорите с полководцем Кровавым Эфесом, затем отправляйтесь в Крепость Отчаяния и сообщите Гар\'дулу, что Кровавый Эфес скоро будет.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Визит в Крепость Отчаяния',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Благодаря тебе острая угроза миновала. Но моя работа в Степях только начинается.$b$bПока здесь командовал полководец Гар\'дул, захватили Заставу Чести и разгромили Таурахо. Вождь послал меня, чтобы я навел здесь порядок.$b$bОтправляйся на юг в Крепость Отчаяния и сообщи Гар\'дулу, что пришел час расплаты.$b$bКогда будешь $gготов:готова; к выходу, скажи мне, я отправлю вместе с тобой свой передовой отряд.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с полководцем Кровавым Эфесом, затем отправляйтесь в Крепость Отчаяния и сообщите Гар\'дулу, что Кровавый Эфес скоро будет.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Гар\'дул покрывается холодным потом.>$B$BПослушай, давай обсудим это в другом месте, не перед всеми...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с полководцем Кровавым Эфесом, затем отправляйтесь в Крепость Отчаяния и сообщите Гар\'дулу, что Кровавый Эфес скоро будет.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (24578,'Черная дубрава','Это заняло у меня немало времени, но я наконец-то смогла разобрать, что тут произошло.$B$BЕсли вкратце, то после вспышки Проклятия в городе остались выжившие. Они присоединились к беженцам в горах, в Пределе Бури.$B$BВ городе остался только автор этого дневника – старик по имени Брэдшоу. Он заметил, что воргены внезапно прекратили нападения, и попытался совершить вылазку в Черную дубраву.$B$BЖил он на старой мельнице к северо-востоку от города. Пожалуйста, сходи туда и поищи какие-нибудь следы его пребывания.','Осмотрите мельницу Брэдшоу рядом с Грозовым Перевалом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Черная дубрава',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это заняло у меня немало времени, но я наконец-то смогла разобрать, что тут произошло.$B$BЕсли вкратце, то после вспышки Проклятия в городе остались выжившие. Они присоединились к беженцам в горах, в Пределе Бури.$B$BВ городе остался только автор этого дневника – старик по имени Брэдшоу. Он заметил, что воргены внезапно прекратили нападения, и попытался совершить вылазку в Черную дубраву.$B$BЖил он на старой мельнице к северо-востоку от города. Пожалуйста, сходи туда и поищи какие-нибудь следы его пребывания.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Осмотрите мельницу Брэдшоу рядом с Грозовым Перевалом.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (24579,'Сартарион должен умереть!','Убейте Сартариона.$B$BЭто задание можно выполнить на любом уровне сложности и любым составом рейда.','Теперь, когда Сартарион погиб, Смертокрылу и Зловестине придется пересмотреть свои планы.','Вернитесь к верховному магу Лан\'далоку в Даларан.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сартарион должен умереть!',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Сартариона.$B$BЭто задание можно выполнить на любом уровне сложности и любым составом рейда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь, когда Сартарион погиб, Смертокрылу и Зловестине придется пересмотреть свои планы.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному магу Лан\'далоку в Даларан.',`completedtext_loc8`);
