INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (24581,'Нот Чумной должен умереть!','Убейте Нота Чумного.$B$BЭто задание можно выполнить на любом уровне сложности и любым составом рейда.','Еще одной помехой меньше. Теперь, когда Нот уничтожен, исследования Плети по обнаружению новых способов создания нежити, сойдут на нет.','Вернитесь к верховному магу Лан\'далоку в Даларан.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нот Чумной должен умереть!',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Нота Чумного.$B$BЭто задание можно выполнить на любом уровне сложности и любым составом рейда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Еще одной помехой меньше. Теперь, когда Нот уничтожен, исследования Плети по обнаружению новых способов создания нежити, сойдут на нет.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному магу Лан\'далоку в Даларан.',`completedtext_loc8`);
