INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (24589,'Лорд Джараксус должен умереть!','Убейте лорда Джараксуса.$B$BЭто задание можно выполнить на любом уровне сложности и любым составом рейда.','Какое счастье для всего Азерота, что Времиар смог предвидеть появление лорда Джараксуса и что тебе удалось вовремя его устранить.','Вернитесь к верховному магу Лан\'далоку в Даларан.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лорд Джараксус должен умереть!',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте лорда Джараксуса.$B$BЭто задание можно выполнить на любом уровне сложности и любым составом рейда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Какое счастье для всего Азерота, что Времиар смог предвидеть появление лорда Джараксуса и что тебе удалось вовремя его устранить.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному магу Лан\'далоку в Даларан.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (24590,'Лорд Ребрад должен умереть!','Благодаря тебе Ледяной Трон остался без своего верного стражника. Теперь мы сможем гораздо успешнее атаковать силы Короля-лича.','Вернитесь к верховному магу Лан\'далоку в Даларан.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лорд Ребрад должен умереть!',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Благодаря тебе Ледяной Трон остался без своего верного стражника. Теперь мы сможем гораздо успешнее атаковать силы Короля-лича.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному магу Лан\'далоку в Даларан.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (24591,'Отстранение Гар\'дула','Когда Кровавый Эфес прибудет, я бы хотел поговорить с ним без лишних ушей. Ты можешь сопровождать меня, чтобы я был уверен, что все идет именно так? Кровавый Эфес... он такой... эээ... от него можно ждать чего угодно.$b$b<Гар\'дул пытается взять себя в руки.>$b$bПриходи на вершину северной башни, и мы вместе поговорим с Кровавым Эфесом.','Поговорите с полководцем Кровавым Эфесом, в Крепости Отчаяния в Южных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отстранение Гар\'дула',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда Кровавый Эфес прибудет, я бы хотел поговорить с ним без лишних ушей. Ты можешь сопровождать меня, чтобы я был уверен, что все идет именно так? Кровавый Эфес... он такой... эээ... от него можно ждать чего угодно.$b$b<Гар\'дул пытается взять себя в руки.>$b$bПриходи на вершину северной башни, и мы вместе поговорим с Кровавым Эфесом.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с полководцем Кровавым Эфесом, в Крепости Отчаяния в Южных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`completedtext_loc8`) VALUES (24592,'Король Седогрив захвачен в плен лордом Годфри в Пределе Бури!$B$BПроклятый предатель смог убедить еще двух лордов, что они смогут заключить союз с Отрекшимися, предложив им взамен венценосного заложника.$B$BСлушай внимательно, $n: мы должны разрешить это дело с минимальным кровопролитием.$B$BВозьми это снадобье – оно поможет тебе $gнезамеченным:незамеченной; прокрасться в их лагерь и убить мятежных лордов прежде, чем ситуация выйдет из-под контроля.','Поговорите с королем Седогривом в Пределе бури, что в Гилнеасе.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Король Седогрив захвачен в плен лордом Годфри в Пределе Бури!$B$BПроклятый предатель смог убедить еще двух лордов, что они смогут заключить союз с Отрекшимися, предложив им взамен венценосного заложника.$B$BСлушай внимательно, $n: мы должны разрешить это дело с минимальным кровопролитием.$B$BВозьми это снадобье – оно поможет тебе $gнезамеченным:незамеченной; прокрасться в их лагерь и убить мятежных лордов прежде, чем ситуация выйдет из-под контроля.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с королем Седогривом в Пределе бури, что в Гилнеасе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24593,'Не человек, но и не зверь','Испейте воды из Источника Спокойствия, Источника Равновесия и Источника Ярости.','Поговорите с лордом Дарием Краули в Тал\'дорене, что в Гилнеасе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Не человек, но и не зверь',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Испейте воды из Источника Спокойствия, Источника Равновесия и Источника Ярости.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с лордом Дарием Краули в Тал\'дорене, что в Гилнеасе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24594,'Очищение Кель\'Делара','Окуните закаленный Кель\'Делар в Солнечный Колодец. Когда вы будете готовы войти на плато Солнечного Колодца, обратитесь к хранителю Солнечного Колодца.','Вернитесь к Миралию Блеску Солнца в Покой Кель\'Делара, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Очищение Кель\'Делара',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Окуните закаленный Кель\'Делар в Солнечный Колодец. Когда вы будете готовы войти на плато Солнечного Колодца, обратитесь к хранителю Солнечного Колодца.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Миралию Блеску Солнца в Покой Кель\'Делара, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24595,'Очищение Кель\'Делара','Признаюсь, я сомневался в том, что тебе удалось перековать Кель\'Делар и что дух Талориена удостоит тебя вниманием. Ты не представляешь, что означает для меня и моего народа возвращение легендарного меча. $B$BКак и было обещано, я разрешаю тебе пройти к Солнечному Колодцу и встретиться с властителями Луносвета. Погрузи меч в Солнечный Колодец. После очищения его сила будет навеки связана с тобой. Затем отнеси меч Каладису Сияющему Копью в Покой Кель\'Делара.','Окуните закаленный Кель\'Делар в Солнечный Колодец. Когда вы будете готовы войти на плато Солнечного Колодца, обратитесь к хранителю Солнечного Колодца.','Вернитесь к Каладису Сияющему Копью в Покой Кель\'Делара, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Очищение Кель\'Делара',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Признаюсь, я сомневался в том, что тебе удалось перековать Кель\'Делар и что дух Талориена удостоит тебя вниманием. Ты не представляешь, что означает для меня и моего народа возвращение легендарного меча. $B$BКак и было обещано, я разрешаю тебе пройти к Солнечному Колодцу и встретиться с властителями Луносвета. Погрузи меч в Солнечный Колодец. После очищения его сила будет навеки связана с тобой. Затем отнеси меч Каладису Сияющему Копью в Покой Кель\'Делара.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Окуните закаленный Кель\'Делар в Солнечный Колодец. Когда вы будете готовы войти на плато Солнечного Колодца, обратитесь к хранителю Солнечного Колодца.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Каладису Сияющему Копью в Покой Кель\'Делара, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24596,'Очищение Кель\'Делара','Окуните закаленный Кель\'Делар в Солнечный Колодец. Когда вы будете готовы войти на плато Солнечного Колодца, обратитесь к хранителю Солнечного Колодца.','Неужели я действительно вижу перед собой оружие Талориена Искателя Рассвета? Это великий день для Похитителей Солнца и всех син\'дорай.','Что случилось у Солнечного Колодца?','Вернитесь к Миралию Блеску Солнца в Покой Кель\'Делара, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Очищение Кель\'Делара',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Окуните закаленный Кель\'Делар в Солнечный Колодец. Когда вы будете готовы войти на плато Солнечного Колодца, обратитесь к хранителю Солнечного Колодца.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Неужели я действительно вижу перед собой оружие Талориена Искателя Рассвета? Это великий день для Похитителей Солнца и всех син\'дорай.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что случилось у Солнечного Колодца?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Миралию Блеску Солнца в Покой Кель\'Делара, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24597,'Подарок для короля Штормграда','Хочешь создать чудесный браслет-оберег для короля Штормграда? Он будет в восторге.$B$BА у тебя есть набор собирателя прелестных оберегов?','Спасибо тебе за этот чудесный браслет-оберег.','Приятное знакомство, |3-6($C). У тебя есть что-нибудь для меня?','Вернитесь к королю Вариану Ринну.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подарок для короля Штормграда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хочешь создать чудесный браслет-оберег для короля Штормграда? Он будет в восторге.$B$BА у тебя есть набор собирателя прелестных оберегов?',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо тебе за этот чудесный браслет-оберег.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Приятное знакомство, |3-6($C). У тебя есть что-нибудь для меня?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к королю Вариану Ринну.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24598,'Очищение Кель\'Делара','Окуните закаленный Кель\'Делар в Солнечный Колодец. Когда вы будете готовы войти на плато Солнечного Колодца, обратитесь к хранителю Солнечного Колодца.','Вернитесь к Миралию Блеску Солнца в Покой Кель\'Делара, что в Ледяной Короне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Очищение Кель\'Делара',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Окуните закаленный Кель\'Делар в Солнечный Колодец. Когда вы будете готовы войти на плато Солнечного Колодца, обратитесь к хранителю Солнечного Колодца.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Миралию Блеску Солнца в Покой Кель\'Делара, что в Ледяной Короне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24601,'Ров Кошмаров','Помогите Наралексу закрыть Ров Кошмаров.','Вернитесь к Наралексу в Ров Кошмаров в Южных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ров Кошмаров',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Помогите Наралексу закрыть Ров Кошмаров.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Наралексу в Ров Кошмаров в Южных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24602,'Покой для усопших','Найдите 5 пропавших памятных вещей.','Вернитесь к Креннану Аранасу в Покой Адерика, что в Гилнеасе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Покой для усопших',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите 5 пропавших памятных вещей.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Креннану Аранасу в Покой Адерика, что в Гилнеасе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (24603,'Война Манкрика','В тот день я думал, что ненависть утихла. Я похоронил жену и принес ей последнюю жертву, кровь убийц, которая успокоила ее страдающую душу. И я думал, ко мне вернется покой.$b$bЯ ошибался.$b$bНе будет мне покоя до тех пор, пока по этой земле ходит хотя бы один отвратительный, визжащий, жестокий свинобраз! У меня лишь две руки, и я не могу убивать их достаточно быстро. Помоги мне, |3-6($r)!','Убейте 13 свинобразов из племени Иглогривых.','Хорошо. Возьми свою награду. Это только начало.','Вернитесь к Манкрику в Южные Степи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Война Манкрика',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В тот день я думал, что ненависть утихла. Я похоронил жену и принес ей последнюю жертву, кровь убийц, которая успокоила ее страдающую душу. И я думал, ко мне вернется покой.$b$bЯ ошибался.$b$bНе будет мне покоя до тех пор, пока по этой земле ходит хотя бы один отвратительный, визжащий, жестокий свинобраз! У меня лишь две руки, и я не могу убивать их достаточно быстро. Помоги мне, |3-6($r)!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 13 свинобразов из племени Иглогривых.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо. Возьми свою награду. Это только начало.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Манкрику в Южные Степи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (24604,'Забота о Манкрике','Я попрошу тебя об одолжении, |3-6($c).$B$BВоин по имени Манкрик прошел через наш лагерь не так давно. Он путешествовал в одиночку. Много дней назад его жена была убита свинобразом, но он до сих пор жаждет мести. Я не могу забыть его глаза... Горящие ненавистью, огонь которой не погасить.$b$bМы недолго разговаривали с ним, но я чувствую отчаяние, когда думаю о том, как он странствует где-то вдалеке совершенно один. Пожалуйста, отнеси это Манкрику и скажи, что это подарок от меня...','Отнесите подарок Махки Манкрику к югу от Кремневого лагеря.','Тебя прислала Махка?$B$B<Манкрик перестает сердиться.>$B$BЭто слабое утешение. Но ничто не может утешить меня с тех пор, как я здесь.','<Манкрик рычит.>$B$BЧто это?! Я занят!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Забота о Манкрике',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я попрошу тебя об одолжении, |3-6($c).$B$BВоин по имени Манкрик прошел через наш лагерь не так давно. Он путешествовал в одиночку. Много дней назад его жена была убита свинобразом, но он до сих пор жаждет мести. Я не могу забыть его глаза... Горящие ненавистью, огонь которой не погасить.$b$bМы недолго разговаривали с ним, но я чувствую отчаяние, когда думаю о том, как он странствует где-то вдалеке совершенно один. Пожалуйста, отнеси это Манкрику и скажи, что это подарок от меня...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите подарок Махки Манкрику к югу от Кремневого лагеря.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебя прислала Махка?$B$B<Манкрик перестает сердиться.>$B$BЭто слабое утешение. Но ничто не может утешить меня с тех пор, как я здесь.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Манкрик рычит.>$B$BЧто это?! Я занят!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24606,'Кровь Степей','Этот яркий красный камень, зажатый в кулаке свинобраза, был аккуратно обтесан для придания ему формы большого кабана с колючей лозой на спине. Его поверхность гладкая, тщательно отполированная.$b$bСделал ли его кто-то из свинобразов? Если найдешь другие, может быть, шаман в Кремневом лагере и сможет рассказать тебе об этом больше.','Соберите у свинобразов из племени Иглогривых 6 безделушек из кровавых осколков.','Это кровавые осколки. Их находят повсюду в Степях.$B$BГоворят, они сделаны из крови Агамаггана, великого полубога, от которого происходят свинобразы. Я знаю, что свинобразы высоко ценят их, но я никогда не слышала, чтобы они тратили время на подобную полировку...$B$BНаверное, тут что-то еще.','Да?','Вернитесь к Махке в Кремневый лагерь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кровь Степей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этот яркий красный камень, зажатый в кулаке свинобраза, был аккуратно обтесан для придания ему формы большого кабана с колючей лозой на спине. Его поверхность гладкая, тщательно отполированная.$b$bСделал ли его кто-то из свинобразов? Если найдешь другие, может быть, шаман в Кремневом лагере и сможет рассказать тебе об этом больше.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите у свинобразов из племени Иглогривых 6 безделушек из кровавых осколков.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это кровавые осколки. Их находят повсюду в Степях.$B$BГоворят, они сделаны из крови Агамаггана, великого полубога, от которого происходят свинобразы. Я знаю, что свинобразы высоко ценят их, но я никогда не слышала, чтобы они тратили время на подобную полировку...$B$BНаверное, тут что-то еще.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Махке в Кремневый лагерь.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (24607,'Возрождение Черного Копья','Племя Черного Копья стало жертвой обстоятельств. Мы попали в изгнание. Раз за разом мы были вынуждены покидать свои дома... Однако на сей раз мы не сбежим как трусы.$B$BВол\'джин всегда мудро правил племенем и долгое время оберегал нас от невзгод. Сейчас же его мудрость подсказывает ему, что под началом Гарроша Адского Крика Орду ждет непонятное будущее.$B$BВ этот раз мы не сбежим. Мы будем сражаться за свой дом до конца.$B$BПора начать твое обучение, $n. Отправляйся на восток и поговори с Нортетом.','Встретьтесь с Нортетом на тренировочной площадке Черного Копья.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возрождение Черного Копья',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Племя Черного Копья стало жертвой обстоятельств. Мы попали в изгнание. Раз за разом мы были вынуждены покидать свои дома... Однако на сей раз мы не сбежим как трусы.$B$BВол\'джин всегда мудро правил племенем и долгое время оберегал нас от невзгод. Сейчас же его мудрость подсказывает ему, что под началом Гарроша Адского Крика Орду ждет непонятное будущее.$B$BВ этот раз мы не сбежим. Мы будем сражаться за свой дом до конца.$B$BПора начать твое обучение, $n. Отправляйся на восток и поговори с Нортетом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Встретьтесь с Нортетом на тренировочной площадке Черного Копья.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (24608,'Кривозуб','Я не ищу более почета или славы, |3-6($c). Стереть свинобразов с лица земли – вот что еще имеет для меня значение. Они должны умереть и неважно, кто и как это сделает.$b$bКривозуб, главарь этих отвратительных Иглогривых, сидит в своей берлоге на вершине холма, к северо-западу отсюда. Оборви его жизнь.$b$BА я останусь здесь и сложу из их тел такой курган, что из Лабиринта ни одна тварь не посмеет более даже высунуть нос...','Убейте Кривозуба.','Хорошо. Хорошо! Они все умрут! И их вожди, и их женщины, и их дети, и их тупые домашние животные!','Вернитесь к Манкрику в Южные Степи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кривозуб',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я не ищу более почета или славы, |3-6($c). Стереть свинобразов с лица земли – вот что еще имеет для меня значение. Они должны умереть и неважно, кто и как это сделает.$b$bКривозуб, главарь этих отвратительных Иглогривых, сидит в своей берлоге на вершине холма, к северо-западу отсюда. Оборви его жизнь.$b$BА я останусь здесь и сложу из их тел такой курган, что из Лабиринта ни одна тварь не посмеет более даже высунуть нос...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Кривозуба.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо. Хорошо! Они все умрут! И их вожди, и их женщины, и их дети, и их тупые домашние животные!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Манкрику в Южные Степи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24609,'Подарок для правителя Стальгорна','Хочешь создать чудесный браслет-оберег для Мурадина Бронзоборода? Он будет в восторге.$B$BА у тебя есть набор собирателя чудесных оберегов?','Подарите чудесный браслет-оберег Мурадину Бронзобороду в Стальгорне.','Спасибо тебе за этот чудесный браслет-оберег.','Приятное знакомство, |3-6($C). У тебя есть что-нибудь для меня?','Вернитесь к Мурадину Бронзобороду в Дун Морог.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подарок для правителя Стальгорна',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хочешь создать чудесный браслет-оберег для Мурадина Бронзоборода? Он будет в восторге.$B$BА у тебя есть набор собирателя чудесных оберегов?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Подарите чудесный браслет-оберег Мурадину Бронзобороду в Стальгорне.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо тебе за этот чудесный браслет-оберег.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Приятное знакомство, |3-6($C). У тебя есть что-нибудь для меня?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мурадину Бронзобороду в Дун Морог.',`completedtext_loc8`);
