INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (24617,'Тал\'дорен, дом среди глуши','Ты не $gодинок:одинока;, $n. Подобных тебе много, и все они чувствуют себя потерянными и запутавшимися.$B$BНо есть место, которое станет тебе домом.$B$BТал\'дорен, спрятанный в глухой чаще, некогда был пристанищем друидов, которые принимали облик волка.$B$BТам ты найдешь ответы на свои вопросы и там же обретешь наставника. Одного из старых друзей.','Поговорите с Дарием Краули в Тал\'дорене, самом сердце Черной дубравы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тал\'дорен, дом среди глуши',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты не $gодинок:одинока;, $n. Подобных тебе много, и все они чувствуют себя потерянными и запутавшимися.$B$BНо есть место, которое станет тебе домом.$B$BТал\'дорен, спрятанный в глухой чаще, некогда был пристанищем друидов, которые принимали облик волка.$B$BТам ты найдешь ответы на свои вопросы и там же обретешь наставника. Одного из старых друзей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Дарием Краули в Тал\'дорене, самом сердце Черной дубравы.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (24618,'Захватить Боевой Шрам','Мы дрались с Альянсом до последнего, даже когда земля начала гореть под нашими ногами. К востоку отсюда ты увидишь Боевой Шрам, широкую полосу земли, лишенную растительности. С виду он мало чем отличается от просто линии на песке, но эта линия должна быть НАШЕЙ.$b$bВ центре Шрама находится флаг, показывающий, кто контролирует эту территорию. Найди этот флаг.$b$bЕсли он все еще не наш, захвати его для Орды – это изменит исход битвы в нашу пользу. Исследуй Боевой Шрам и убей любого, кого увидишь там!','Флаг обнаружен','Вернитесь к полководцу Кровавому Эфесу в Крепость Отчаяния в Южных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Захватить Боевой Шрам',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы дрались с Альянсом до последнего, даже когда земля начала гореть под нашими ногами. К востоку отсюда ты увидишь Боевой Шрам, широкую полосу земли, лишенную растительности. С виду он мало чем отличается от просто линии на песке, но эта линия должна быть НАШЕЙ.$b$bВ центре Шрама находится флаг, показывающий, кто контролирует эту территорию. Найди этот флаг.$b$bЕсли он все еще не наш, захвати его для Орды – это изменит исход битвы в нашу пользу. Исследуй Боевой Шрам и убей любого, кого увидишь там!',`details_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Флаг обнаружен',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к полководцу Кровавому Эфесу в Крепость Отчаяния в Южных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24619,'Конечности есть конечности','Я всегда хотел попробовать сделать поганище. Кажется, что это довольно просто, но, знаешь, тут как с любой наукой – сколько ни читай книги, без практики никуда!$b$bДля начала мне нужны конечности. Много конечностей. Ты мне их и достанешь.$b$bМожно не быть $gразборчивым:разборчивой;: люди, орки... Не имеет значения. Конечности есть конечности.$b$bГлавное, убедись, что все тела, которые ты достанешь, из Боевого Шрама, то есть свеженькие.$b$b<Колдер вручает вам ржавую от запекшейся крови костяную пилу и обезоруживающе улыбается>.','Примените костяную пилу Колдера к телам в Боевом Шраме и соберите 15 отрезанных конечностей.','Принесла мне части тела? Давай посмотрим!','Принесите конечности Колдеру Грею, он находится снаружи Крепости Отчаяния в Южных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Конечности есть конечности',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я всегда хотел попробовать сделать поганище. Кажется, что это довольно просто, но, знаешь, тут как с любой наукой – сколько ни читай книги, без практики никуда!$b$bДля начала мне нужны конечности. Много конечностей. Ты мне их и достанешь.$b$bМожно не быть $gразборчивым:разборчивой;: люди, орки... Не имеет значения. Конечности есть конечности.$b$bГлавное, убедись, что все тела, которые ты достанешь, из Боевого Шрама, то есть свеженькие.$b$b<Колдер вручает вам ржавую от запекшейся крови костяную пилу и обезоруживающе улыбается>.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Примените костяную пилу Колдера к телам в Боевом Шраме и соберите 15 отрезанных конечностей.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Принесла мне части тела? Давай посмотрим!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите конечности Колдеру Грею, он находится снаружи Крепости Отчаяния в Южных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24620,'Сердце есть сердце','Какие миленькие конечности! Мышцы, сухожилия, пальчики... Я ТАК голоден!$b$bНо сначала работа. Когда я сошью эту груду ручек и ножек вместе, мне понадобится сердце, достаточно сильное, чтобы гнать слизь через всю эту путаницу вен. Я бы использовал свое, но оно высохло и скукожилось и напоминает луковую шелуху.$b$bНет, мне нужен настоящий мощный мотор. Иди к югу от Боевого Шрама и принеси мне сердце самца тяжелоногого кодо.','Убейте самца тяжелоногого кодо в Боевом Шраме и возьмите его огромное сердце.','Вернитесь к Колдеру Грею, он находится снаружи Крепости Отчаяния в Южных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сердце есть сердце',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Какие миленькие конечности! Мышцы, сухожилия, пальчики... Я ТАК голоден!$b$bНо сначала работа. Когда я сошью эту груду ручек и ножек вместе, мне понадобится сердце, достаточно сильное, чтобы гнать слизь через всю эту путаницу вен. Я бы использовал свое, но оно высохло и скукожилось и напоминает луковую шелуху.$b$bНет, мне нужен настоящий мощный мотор. Иди к югу от Боевого Шрама и принеси мне сердце самца тяжелоногого кодо.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте самца тяжелоногого кодо в Боевом Шраме и возьмите его огромное сердце.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Колдеру Грею, он находится снаружи Крепости Отчаяния в Южных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24621,'Мозги есть мозги','Мое поганище приобретает форму! Осталось только набить этот череп чем-нибудь полезным.$b$bЯ говорю о мозгах, $n! И вот теперь подойдет не все. Процесс создания поганища наносит большой урон его мозгам, так что начинать лучше с кого-то поумнее.$b$bКто-нибудь из офицеров Альянса подойдет. Найди какого-нибудь капитана на дальней стороне Боевого Шрама и постарайся не сильно повредить его мозг, когда будешь убивать.','<Колдер держит мозги на вытянутой руке и достает из-за пояса какой-то сложный инструмент, покрытый запекшейся кровью.>$B$BОчень хорошо! Теперь хитрость в том, чтобы примитивные функции нервной системы сохранить, а высшие когнитивные функции удалить. Зачем нашему новому другу такая штука, как мораль, или воспоминания о том, что он из Альянса...$B$B<Колдер запускает руки в мозг и вытаскивает большие куски.>$B$BИ вот теперь... мы закончили! Отлично получилось.','Мозгииииииииии...','Принесите свежий мозг Колдеру Грею, он находится снаружи Крепости Отчаяния в Южных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мозги есть мозги',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мое поганище приобретает форму! Осталось только набить этот череп чем-нибудь полезным.$b$bЯ говорю о мозгах, $n! И вот теперь подойдет не все. Процесс создания поганища наносит большой урон его мозгам, так что начинать лучше с кого-то поумнее.$b$bКто-нибудь из офицеров Альянса подойдет. Найди какого-нибудь капитана на дальней стороне Боевого Шрама и постарайся не сильно повредить его мозг, когда будешь убивать.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Колдер держит мозги на вытянутой руке и достает из-за пояса какой-то сложный инструмент, покрытый запекшейся кровью.>$B$BОчень хорошо! Теперь хитрость в том, чтобы примитивные функции нервной системы сохранить, а высшие когнитивные функции удалить. Зачем нашему новому другу такая штука, как мораль, или воспоминания о том, что он из Альянса...$B$B<Колдер запускает руки в мозг и вытаскивает большие куски.>$B$BИ вот теперь... мы закончили! Отлично получилось.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мозгииииииииии...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите свежий мозг Колдеру Грею, он находится снаружи Крепости Отчаяния в Южных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (24622,'Лучший спутник тролля','Ищешь, чем заняться? Нам очень не хватает ящеров. К югу отсюда есть остров; отправляйся туда и поговори с нашими управляющими – они подскажут, где найти ящеров.$B$BКстати, им тоже помощь не помешает. Надо делать мир лучше, а?','Поговорите с Киджарой на Берегу Кровавого Когтя.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лучший спутник тролля',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ищешь, чем заняться? Нам очень не хватает ящеров. К югу отсюда есть остров; отправляйся туда и поговори с нашими управляющими – они подскажут, где найти ящеров.$B$BКстати, им тоже помощь не помешает. Надо делать мир лучше, а?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Киджарой на Берегу Кровавого Когтя.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (24623,'Спасение детенышей','У меня есть одно важное дело, $gприятель:подруга;.$B$BКто-то с соседнего острова ворует наших детенышей. Сначала я думала, что они сами убегают, но сейчас мы не досчитались более десятка.$B$BПожалуйста, отправляйся в Падение Залазана, что к северо-западу отсюда, и приведи детенышей назад. Бедные малыши...','Спасите 12 потерянных кровопалых детенышей с помощью свистка Кровопалых.','Большое спасибо! Они бывают агрессивны, если их рассердить, но большую часть времени такие милые.','Вернитесь к Киджаре на Берег Кровавого Когтя на островах Эха.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спасение детенышей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У меня есть одно важное дело, $gприятель:подруга;.$B$BКто-то с соседнего острова ворует наших детенышей. Сначала я думала, что они сами убегают, но сейчас мы не досчитались более десятка.$B$BПожалуйста, отправляйся в Падение Залазана, что к северо-западу отсюда, и приведи детенышей назад. Бедные малыши...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Спасите 12 потерянных кровопалых детенышей с помощью свистка Кровопалых.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Большое спасибо! Они бывают агрессивны, если их рассердить, но большую часть времени такие милые.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Киджаре на Берег Кровавого Когтя на островах Эха.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24624,'Жест милосердия','Тот, кто украл наших ящеров, осквернил их какой-то магией. И теперь нам ничего не остается, кроме как помочь им упокоиться с миром. Отправляйся в Падение Залазана, что к северо-западу отсюда, и доведи дело до конца.$B$BНадеюсь, тебе по плечу эта работа. Я бы точно не смог это сделать, если даже нет другого выхода.','Убейте 8 оскверненных кровопалых ящеров.','Вернитесь к Тегаши на Берег Кровавого Когтя на островах Эха.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жест милосердия',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тот, кто украл наших ящеров, осквернил их какой-то магией. И теперь нам ничего не остается, кроме как помочь им упокоиться с миром. Отправляйся в Падение Залазана, что к северо-западу отсюда, и доведи дело до конца.$B$BНадеюсь, тебе по плечу эта работа. Я бы точно не смог это сделать, если даже нет другого выхода.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 оскверненных кровопалых ящеров.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тегаши на Берег Кровавого Когтя на островах Эха.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (24624,'Спасибо, $C.$B$BИменно такие храбрецы, как ты, смогут возродить Черное Копье. Я надеюсь, наши ряды пополнятся теми, кто хотя бы вполовину силен, как ты.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо, $C.$B$BИменно такие храбрецы, как ты, смогут возродить Черное Копье. Я надеюсь, наши ряды пополнятся теми, кто хотя бы вполовину силен, как ты.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (24625,'Спутник морской ведьмы','Кажется, мне удалось понять, кто оскверняет наших детенышей. Это некий нага. Я видел, как он поднимал над малышами какую-то красную сферу, и они... начинали меняться.$B$BПолагаю, он уверен, что о его проделках никто не знает, поэтому ты сможешь застать его врасплох. Отправляйся в Падение Залазана на северо-запад отсюда, убей этого нагу и принеси мне его сферу.','Убейте Наж\'тесса и заберите его сферу.','Вернитесь к Тегаши на Берег Кровавого Когтя на островах Эха.','Наж\'тесс надеялся обратить союзников троллей против них, но просчитался.','Наж\'тесс') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спутник морской ведьмы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кажется, мне удалось понять, кто оскверняет наших детенышей. Это некий нага. Я видел, как он поднимал над малышами какую-то красную сферу, и они... начинали меняться.$B$BПолагаю, он уверен, что о его проделках никто не знает, поэтому ты сможешь застать его врасплох. Отправляйся в Падение Залазана на северо-запад отсюда, убей этого нагу и принеси мне его сферу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Наж\'тесса и заберите его сферу.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тегаши на Берег Кровавого Когтя на островах Эха.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Наж\'тесс надеялся обратить союзников троллей против них, но просчитался.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Наж\'тесс',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (24625,'Молодец, Дефхэвен! Этот нага нам здорово помешал, но никто не может сдерживать нас вечно.$B$BХорошо, что ты с нами, Дефхэвен. У тебя горячее сердце.','Мы уже давно воюем с нагами, и последние битвы прошли для нас не слишком удачно. Но теперь все будет по-другому. Времена изменились, в том числе благодаря тебе.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Молодец, Дефхэвен! Этот нага нам здорово помешал, но никто не может сдерживать нас вечно.$B$BХорошо, что ты с нами, Дефхэвен. У тебя горячее сердце.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мы уже давно воюем с нагами, и последние битвы прошли для нас не слишком удачно. Но теперь все будет по-другому. Времена изменились, в том числе благодаря тебе.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24626,'Молодой и горячий','Ты молодец, $n.$B$BМорайа давно просила привести ей новых ящеров, пора выполнить эту просьбу! Я уже направила других помощников на поиски ящеров, но есть один особенный зверь, которого я давно обещала Морайе.$B$BСтремительный Коготь – самый быстрый и храбрый из молодых ящеров, правда, немного непослушный. Сейчас он бродит по этому острову. Возьми лассо, поймай Стремительного Когтя и приведи в стойла на главный остров. Но знай: будет нелегко!','Поймайте Стремительного Когтя и приведите его в стойла возле крепости Черного Копья.','Поговорите с Морайей в крепости Черного Копья на островах Эха.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Молодой и горячий',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты молодец, $n.$B$BМорайа давно просила привести ей новых ящеров, пора выполнить эту просьбу! Я уже направила других помощников на поиски ящеров, но есть один особенный зверь, которого я давно обещала Морайе.$B$BСтремительный Коготь – самый быстрый и храбрый из молодых ящеров, правда, немного непослушный. Сейчас он бродит по этому острову. Возьми лассо, поймай Стремительного Когтя и приведи в стойла на главный остров. Но знай: будет нелегко!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поймайте Стремительного Когтя и приведите его в стойла возле крепости Черного Копья.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Морайей в крепости Черного Копья на островах Эха.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24627,'Слишком близко','Ночные эльфы многому нас научили за это время, $n. Они рассказали нам, кто мы и откуда взялись. $B$BБлагодаря им... благодаря этому месту мы больше не страшимся превратиться в зверей. Мы обрели свободу воли.$B$BНедаром Отрекшиеся так стремятся отыскать это место.$B$BИм нужна не земля, а то, что мы охраняем – артефакт, способный распространить Проклятье на все человечество. Нельзя позволить им завладеть этим предметом.$B$BБанши Сильваны подобрались слишком близко. Помоги моим следопытам отогнать их прочь.','Убейте 6 стенающих банши.','Вернитесь к лорду Дарию Краули в Тал\'дорен, что в Гилнеасе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Слишком близко',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ночные эльфы многому нас научили за это время, $n. Они рассказали нам, кто мы и откуда взялись. $B$BБлагодаря им... благодаря этому месту мы больше не страшимся превратиться в зверей. Мы обрели свободу воли.$B$BНедаром Отрекшиеся так стремятся отыскать это место.$B$BИм нужна не земля, а то, что мы охраняем – артефакт, способный распространить Проклятье на все человечество. Нельзя позволить им завладеть этим предметом.$B$BБанши Сильваны подобрались слишком близко. Помоги моим следопытам отогнать их прочь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 6 стенающих банши.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лорду Дарию Краули в Тал\'дорен, что в Гилнеасе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (24628,'Приготовления','Принесите Вассандре 6 лунных листьев.','Эти листочки растут по воле самой Элуны. С их помощью твой дух обретет равновесие, а разум навсегда одержит верх над звериным началом.','Вернитесь к Вассандре в Тал\'дорен, что в Черной дубраве.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приготовления',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Вассандре 6 лунных листьев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Эти листочки растут по воле самой Элуны. С их помощью твой дух обретет равновесие, а разум навсегда одержит верх над звериным началом.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Вассандре в Тал\'дорен, что в Черной дубраве.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24629,'Легкий аромат духов','Похоже, ты умеешь делать деньги, |3-6($c). Как насчет одного беспроигрышного дельца?$B$BКоролевская компания хочет предложить образцы новых праздничных изделий как можно большему числу потенциальных клиентов. Помоги нам сеять любовь – а взамен получишь хорошую скидку на продукцию Королевской компании!$B$BВремя – деньги, дружище! Что скажешь?','Опрыскайте десять прохожих из флакончика духов королевской компании с распылителем.','Очень хорошо, $N! Теперь за нашими духами целая очередь выстроится – раз уж клиенты успели опробовать их эффект.$B$BВот, держи небольшое вознаграждение за помощь.','Эти духи не будут распыляться сами по себе, ты же знаешь.$B$BИдите!','Вернитесь к специалисту по связям с общественностью в любую столицу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Легкий аромат духов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Похоже, ты умеешь делать деньги, |3-6($c). Как насчет одного беспроигрышного дельца?$B$BКоролевская компания хочет предложить образцы новых праздничных изделий как можно большему числу потенциальных клиентов. Помоги нам сеять любовь – а взамен получишь хорошую скидку на продукцию Королевской компании!$B$BВремя – деньги, дружище! Что скажешь?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Опрыскайте десять прохожих из флакончика духов королевской компании с распылителем.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Очень хорошо, $N! Теперь за нашими духами целая очередь выстроится – раз уж клиенты успели опробовать их эффект.$B$BВот, держи небольшое вознаграждение за помощь.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Эти духи не будут распыляться сами по себе, ты же знаешь.$B$BИдите!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к специалисту по связям с общественностью в любую столицу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24630,'Хозяйка Лабиринтов','Пятеро из нас беседовали с духами и узнали причину агрессии свинобразов. Чарлга Остробок руководит ими из Лабиринтов Иглошкурых. Она обещает им воскресить Агамаггана, и тем самым добивается того, что они так неистово убивают и грабят.$b$bПожалуйста, |3-6($c), положи этому конец. Если убить Чарлгу, свинобразы, может быть, и не остановятся, но они точно станут менее опасными.','Убейте Чарлгу Остробок в Лабиринтах Иглошкурых.','Вернитесь к Махке в Кремневый лагерь в Южных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хозяйка Лабиринтов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пятеро из нас беседовали с духами и узнали причину агрессии свинобразов. Чарлга Остробок руководит ими из Лабиринтов Иглошкурых. Она обещает им воскресить Агамаггана, и тем самым добивается того, что они так неистово убивают и грабят.$b$bПожалуйста, |3-6($c), положи этому конец. Если убить Чарлгу, свинобразы, может быть, и не остановятся, но они точно станут менее опасными.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Чарлгу Остробок в Лабиринтах Иглошкурых.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Махке в Кремневый лагерь в Южных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24631,'Небесные всадники','<Томуса фыркает, забирая обратно свой крюк.>$B$BЖажда мести не утолена. До сих пор. Я не могу позволить им уйти безнаказанными.','Наемники свирепы и в небе, и на земле. Как идет битва?','Вернитесь к Томусе в Крепость Отчаяния в Южных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Небесные всадники',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Томуса фыркает, забирая обратно свой крюк.>$B$BЖажда мести не утолена. До сих пор. Я не могу позволить им уйти безнаказанными.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Наемники свирепы и в небе, и на земле. Как идет битва?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Томусе в Крепость Отчаяния в Южных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (24632,'Возмездие таурена','Мой народ по природе своей миролюбив, но жажда справедливости заставляет и нас приходить в ярость.$b$bСтарый друг Ганн Каменное Копье пережил мясорубку в Таурахо, но впал в чудовищную ярость. Старейшины племени не смогли сдержать его гнев.$b$bТо, что он делает сейчас, имеет мало общего с Ордой. Он стал разбойником, $n, и вместе с небольшой компанией таких же, как он, жаждущих лишь возмездия, использует любой шанс наброситься на Альянс.$b$BЕсли месть – это то, что ты ищещь, то найди его на юго-востоке отсюда, у подножия Бейл Модан.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возмездие таурена',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мой народ по природе своей миролюбив, но жажда справедливости заставляет и нас приходить в ярость.$b$bСтарый друг Ганн Каменное Копье пережил мясорубку в Таурахо, но впал в чудовищную ярость. Старейшины племени не смогли сдержать его гнев.$b$bТо, что он делает сейчас, имеет мало общего с Ордой. Он стал разбойником, $n, и вместе с небольшой компанией таких же, как он, жаждущих лишь возмездия, использует любой шанс наброситься на Альянс.$b$BЕсли месть – это то, что ты ищещь, то найди его на юго-востоке отсюда, у подножия Бейл Модан.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (24633,'Просьба Махки','Не могу выбросить его из головы, $n. Иногда, глубокой ночью, я просыпаюсь от того, что слышу, как он рыдает в бессильной ярости и страданиях, а эхо разносит его стенания по равнинам. Стоит лишь представить его там, одного, испытывающего такую невыносимую боль...$b$bПрошу тебя, сделай одолжение – найди Манкрика и скажи, что я хочу его увидеть.','Поговорите с Манкриком.','Поговорите с Манкриком','Вернитесь к Махке в Кремневый лагерь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Просьба Махки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не могу выбросить его из головы, $n. Иногда, глубокой ночью, я просыпаюсь от того, что слышу, как он рыдает в бессильной ярости и страданиях, а эхо разносит его стенания по равнинам. Стоит лишь представить его там, одного, испытывающего такую невыносимую боль...$b$bПрошу тебя, сделай одолжение – найди Манкрика и скажи, что я хочу его увидеть.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Манкриком.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Поговорите с Манкриком',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Махке в Кремневый лагерь.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (24634,'Битва умов','Я убежден, что шпионы Альянса рыщут по полю и собирают секретную информацию. Они ведь выбрали для атаки Таурахо именно тот момент, когда охотники были далеко от лагеря. И обо всех перемещениях Гар\'дула они тоже откуда-то знали.$b$bТак вот, $n, меня, к примеру, им не переиграть. Не здесь. Мы выиграем эту битву умов.$b$bДаже сейчас я слышу доклады сотрудников Альянса, крадущихся в тени, особенно здесь, вне этих стен. Убей их и принеси мне что-нибудь полезное.','Убейте разведчика Степей и заберите инструкции ШРУ.','Ха! Этот дурак не уничтожил приказы.$B$BДавай посмотрим, что здесь интересного...','Вернитесь к полководцу Кровавому Эфесу в Крепость Отчаяния в Южных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Битва умов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я убежден, что шпионы Альянса рыщут по полю и собирают секретную информацию. Они ведь выбрали для атаки Таурахо именно тот момент, когда охотники были далеко от лагеря. И обо всех перемещениях Гар\'дула они тоже откуда-то знали.$b$bТак вот, $n, меня, к примеру, им не переиграть. Не здесь. Мы выиграем эту битву умов.$b$bДаже сейчас я слышу доклады сотрудников Альянса, крадущихся в тени, особенно здесь, вне этих стен. Убей их и принеси мне что-нибудь полезное.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте разведчика Степей и заберите инструкции ШРУ.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ха! Этот дурак не уничтожил приказы.$B$BДавай посмотрим, что здесь интересного...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к полководцу Кровавому Эфесу в Крепость Отчаяния в Южных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24635,'Легкий аромат одеколона','Кажется, ты знаешь, как вести дела, |3-6($c). Как насчет небольшой сделки?$B$BКоролевская компания хочет предложить образцы новых праздничных изделий как можно большему числу потенциальных клиентов. Помоги нам сеять любовь – а взамен получишь хорошую скидку на продукцию Королевской компании!$B$BВремя – деньги, дружище! Что скажешь?','Опрыскайте десять прохожих из флакончика одеколона королевской компании с распылителем.','Прекрасно, $N! Теперь наши одеколоны будут ящиками покупать – раз уж клиенты успели опробовать их эффект.$B$BВот, держи небольшое вознаграждение за помощь.','Одеколон не выдаст себя, ты же знаешь.$B$BПолучить распыление!','Вернитесь к специалисту по связям с общественностью в любую столицу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Легкий аромат одеколона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кажется, ты знаешь, как вести дела, |3-6($c). Как насчет небольшой сделки?$B$BКоролевская компания хочет предложить образцы новых праздничных изделий как можно большему числу потенциальных клиентов. Помоги нам сеять любовь – а взамен получишь хорошую скидку на продукцию Королевской компании!$B$BВремя – деньги, дружище! Что скажешь?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Опрыскайте десять прохожих из флакончика одеколона королевской компании с распылителем.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно, $N! Теперь наши одеколоны будут ящиками покупать – раз уж клиенты успели опробовать их эффект.$B$BВот, держи небольшое вознаграждение за помощь.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Одеколон не выдаст себя, ты же знаешь.$B$BПолучить распыление!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к специалисту по связям с общественностью в любую столицу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24636,'Вкус конфет','Гляжу, у тебя есть предпринимательская хватка, |3-6($c). Не хочешь заработать немного звонких монет с моей помощью?$B$BКоролевская компания хочет предложить образцы новых праздничных изделий как можно большему числу потенциальных клиентов. Помоги нам сеять любовь – а взамен получишь хорошую скидку на продукцию Королевской компании!$B$BВремя – деньги, дружище! Что скажешь?','Раздайте десяти прохожим кусочки королевского шоколада.','Очень хорошо, $N! Теперь клиенты будут драться за наши шоколадки – раз уж они успели оценить их изумительно нежный, сладкий вкус.$B$BВот, держи небольшое вознаграждение за помощь.','Знаешь, эти конфеты не будут бросаться на людей.$B$BТебе нужно приниматься за работу!','Вернитесь к специалисту по связям с общественностью в любую столицу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вкус конфет',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Гляжу, у тебя есть предпринимательская хватка, |3-6($c). Не хочешь заработать немного звонких монет с моей помощью?$B$BКоролевская компания хочет предложить образцы новых праздничных изделий как можно большему числу потенциальных клиентов. Помоги нам сеять любовь – а взамен получишь хорошую скидку на продукцию Королевской компании!$B$BВремя – деньги, дружище! Что скажешь?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздайте десяти прохожим кусочки королевского шоколада.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Очень хорошо, $N! Теперь клиенты будут драться за наши шоколадки – раз уж они успели оценить их изумительно нежный, сладкий вкус.$B$BВот, держи небольшое вознаграждение за помощь.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Знаешь, эти конфеты не будут бросаться на людей.$B$BТебе нужно приниматься за работу!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к специалисту по связям с общественностью в любую столицу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (24637,'Ответственный за штурм Таурахо','У этого шпиона был приказ обеспечивать безопасность дорог между командным пунктом Альянса и Фортом Триумфа. Генерал Готорн сейчас в пути.$b$b<Кровавый Эфес сжимает кулак, сминая документы в комок.>$b$bЭто ОН, $n! Именно Готорн – хотел бы я плюнуть ему в лицо – отдал приказ штурмовать Таурахо! Но теперь мы знаем, где и когда искать его, чтобы убить. Быстрее, иди по дороге на север от Боевого Шрама и найди там наемного убийцу Картога. УНИЧТОЖЬ Готорна и повесь его тело на обочине дороги!','Поговорите с Картогом, потом заманите генерала Готорна в ловушку и убейте его.','Вернитесь к полководцу Кровавому Эфесу в Крепость Отчаяния в Южных Степях.','Найдите Картога у дороги, ведущей на север от Боевого Шрама. Вместе с ним устрой засаду и убей Палача Таурахо.','Генерал Готорн') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ответственный за штурм Таурахо',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У этого шпиона был приказ обеспечивать безопасность дорог между командным пунктом Альянса и Фортом Триумфа. Генерал Готорн сейчас в пути.$b$b<Кровавый Эфес сжимает кулак, сминая документы в комок.>$b$bЭто ОН, $n! Именно Готорн – хотел бы я плюнуть ему в лицо – отдал приказ штурмовать Таурахо! Но теперь мы знаем, где и когда искать его, чтобы убить. Быстрее, иди по дороге на север от Боевого Шрама и найди там наемного убийцу Картога. УНИЧТОЖЬ Готорна и повесь его тело на обочине дороги!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Картогом, потом заманите генерала Готорна в ловушку и убейте его.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к полководцу Кровавому Эфесу в Крепость Отчаяния в Южных Степях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Найдите Картога у дороги, ведущей на север от Боевого Шрама. Вместе с ним устрой засаду и убей Палача Таурахо.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Генерал Готорн',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24638,'Конец Королевской компании','В этом гроссбухе указано множество мест, и ты, $gпарень, должен:подруга, должна; проверить для меня кое-что. Нельзя допустить, чтобы это продолжалось и дальше.$b$bВот запись, которая меня особенно волнует: в ней говорится о месте за вратами Оргриммара, на западе! Не нравится меня это. Иди туда и разберись.$b$bДа, если увидишь что-то большое и опасное – брось в него эту бомбу.','Убейте 5 служащих химической компании и воспользуйтесь кориевой бомбой Гвоздезуба, чтобы уничтожить повозку с химикатами к западу от врат Оргриммара в Дуротаре. После этого вернитесь к детективу Крямсу Гвоздезубу в Оргриммар.','Хорошая работа, $Gпарень:девчонка;. Ты заслуживаешь немного чего-то. И Эй, приходи завтра, если у тебя будет время; у меня может быть для тебя работа.','Ты $Gпреподал:преподала; им урок?','Вернитесь к детективу Крямсу Гвоздезубу на Аллею Силы Оргриммара.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Конец Королевской компании',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В этом гроссбухе указано множество мест, и ты, $gпарень, должен:подруга, должна; проверить для меня кое-что. Нельзя допустить, чтобы это продолжалось и дальше.$b$bВот запись, которая меня особенно волнует: в ней говорится о месте за вратами Оргриммара, на западе! Не нравится меня это. Иди туда и разберись.$b$bДа, если увидишь что-то большое и опасное – брось в него эту бомбу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 5 служащих химической компании и воспользуйтесь кориевой бомбой Гвоздезуба, чтобы уничтожить повозку с химикатами к западу от врат Оргриммара в Дуротаре. После этого вернитесь к детективу Крямсу Гвоздезубу в Оргриммар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошая работа, $Gпарень:девчонка;. Ты заслуживаешь немного чего-то. И Эй, приходи завтра, если у тебя будет время; у меня может быть для тебя работа.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gпреподал:преподала; им урок?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к детективу Крямсу Гвоздезубу на Аллею Силы Оргриммара.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24639,'Азы мастерства: поражение цели','Ну ладно, $gдружище:подруга;. Начнем с азов. Посмотрим, как ты владеешь этим своим оружьицем.$B$BПопробуй-ка разнести в щепки вон те манекены-тики. Не торопись. Делай, как получится. А я посмотрю, как ты дерешься и что с этим можно сделать.','Уничтожьте 6 манекенов-тики.','Вернитесь к Нортету на тренировочную площадку Черного Копья на островах Эха.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Азы мастерства: поражение цели',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну ладно, $gдружище:подруга;. Начнем с азов. Посмотрим, как ты владеешь этим своим оружьицем.$B$BПопробуй-ка разнести в щепки вон те манекены-тики. Не торопись. Делай, как получится. А я посмотрю, как ты дерешься и что с этим можно сделать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 6 манекенов-тики.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Нортету на тренировочную площадку Черного Копья на островах Эха.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24641,'Практическое занятие','Пора применить все эти умения на практике, $gдружище:подруга;. Для начала дам простое задание.$B$BСмотри, рыси убивают кабанов. А кабаны – наш продовольственный запас, и как-то вовсе не хочется им делиться. Если желаешь сегодня поужинать, кабаны должны быть живы. По крайней мере, до вечера.$B$BРыси здесь повсюду. Принеси мне побольше их шкур.','Добудьте 6 шкур буйногривой рыси.','Вернитесь к Нортету на тренировочную площадку Черного Копья на островах Эха.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Практическое занятие',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пора применить все эти умения на практике, $gдружище:подруга;. Для начала дам простое задание.$B$BСмотри, рыси убивают кабанов. А кабаны – наш продовольственный запас, и как-то вовсе не хочется им делиться. Если желаешь сегодня поужинать, кабаны должны быть живы. По крайней мере, до вечера.$B$BРыси здесь повсюду. Принеси мне побольше их шкур.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 6 шкур буйногривой рыси.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Нортету на тренировочную площадку Черного Копья на островах Эха.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24642,'Яма испытаний','Ты уже многому $gнаучился:научилась;, |3-6($c). Конечно, это еще не все. Но мы больше не будем практиковаться на манекенах-тики. Просто жаль тратить время...$B$BДавай-ка испробуем твои силы на настоящем противнике. На том, кто будет биться до смерти. Иди в яму испытаний – там тебе подберут соперника. Скажи тюремщику, когда будешь $gготов:готова;.','Поговорите с тюремщиком Черного Копья, а затем спуститесь в яму испытаний и убейте пленного разведчика из клана Злобной Чешуи.','Вернитесь к Нортету на тренировочную площадку Черного Копья на островах Эха.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Яма испытаний',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты уже многому $gнаучился:научилась;, |3-6($c). Конечно, это еще не все. Но мы больше не будем практиковаться на манекенах-тики. Просто жаль тратить время...$B$BДавай-ка испробуем твои силы на настоящем противнике. На том, кто будет биться до смерти. Иди в яму испытаний – там тебе подберут соперника. Скажи тюремщику, когда будешь $gготов:готова;.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с тюремщиком Черного Копья, а затем спуститесь в яму испытаний и убейте пленного разведчика из клана Злобной Чешуи.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Нортету на тренировочную площадку Черного Копья на островах Эха.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (24643,'Превосходя ожидания','Ты превосходишь все наши ожидания, так что хватит ходить в новичках – самое время взяться за что-нибудь серьезное.$B$BОтправляйся в деревню, что к юго-востоку отсюда, и начинай выполнять различные поручения. Будь на виду – и тебе быстро предложат серьезную работу.','Поговорите с Вол\'джином в крепости Черного Копья.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Превосходя ожидания',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты превосходишь все наши ожидания, так что хватит ходить в новичках – самое время взяться за что-нибудь серьезное.$B$BОтправляйся в деревню, что к юго-востоку отсюда, и начинай выполнять различные поручения. Будь на виду – и тебе быстро предложат серьезную работу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Вол\'джином в крепости Черного Копья.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (24644,'Troll Introduction Complete') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Troll Introduction Complete',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24645,'Конец Королевской компании','В этом гроссбухе указано множество мест, и ты, $gпарень, должен:подруга, должна; проверить для меня кое-что. Нельзя допустить, чтобы это продолжалось и дальше.$b$bВот запись, которая меня особенно волнует: в ней говорится о месте за вратами Янтарной мельницы, в Серебряном бору! Не нравится мне это. Иди туда и разберись.$b$bДа, если увидишь что-то большое и опасное – брось в него эту бомбу.','Убейте 5 головорезов химической компании и воспользуйтесь кориевой бомбой Гвоздезуба, чтобы уничтожить повозку с химикатами за вратами Янтарной мельницы, в Серебряном бору. После этого вернитесь к детективу в Оргриммар.','Хорошая работа, $Gпарень:девчонка;. Ты заслуживаешь немного чего-то. И Эй, приходи завтра, если у тебя будет время; у меня может быть для тебя работа.','Ты $Gпреподал:преподала; им урок?','Вернитесь к детективу Крямсу Гвоздезубу на Аллею Силы Оргриммара.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Конец Королевской компании',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В этом гроссбухе указано множество мест, и ты, $gпарень, должен:подруга, должна; проверить для меня кое-что. Нельзя допустить, чтобы это продолжалось и дальше.$b$bВот запись, которая меня особенно волнует: в ней говорится о месте за вратами Янтарной мельницы, в Серебряном бору! Не нравится мне это. Иди туда и разберись.$b$bДа, если увидишь что-то большое и опасное – брось в него эту бомбу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 5 головорезов химической компании и воспользуйтесь кориевой бомбой Гвоздезуба, чтобы уничтожить повозку с химикатами за вратами Янтарной мельницы, в Серебряном бору. После этого вернитесь к детективу в Оргриммар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошая работа, $Gпарень:девчонка;. Ты заслуживаешь немного чего-то. И Эй, приходи завтра, если у тебя будет время; у меня может быть для тебя работа.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gпреподал:преподала; им урок?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к детективу Крямсу Гвоздезубу на Аллею Силы Оргриммара.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (24646,'Отвоевать свое','С тех пор, как Отрекшиеся вторглись в Гилнеас, мы всеми силами пытались скрыть от них местонахождение Косы Элуны. Под покровом ночи мы перевозили ее из одного безопасного места в другое. Сколько бы ни старались темные следопыты засечь наши передвижения, им никогда не удавалось подойти близко... до сегодняшнего дня.$B$BПоследний раз их видели возле охотничьего домика на краю леса, к западу отсюда. Когда обнаружишь их, подуй в этот рог, и Тобиас с его охотниками разберутся с проклятой нежитью.$B$BТолько тогда ты сможешь спокойно войти в дом и забрать Косу. Поторопись, $n – она не должна попасть в руки Сильваны!','Вернитесь к лорду Дарию Краули в Тал\'дорен, что в Гилнеасе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отвоевать свое',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','С тех пор, как Отрекшиеся вторглись в Гилнеас, мы всеми силами пытались скрыть от них местонахождение Косы Элуны. Под покровом ночи мы перевозили ее из одного безопасного места в другое. Сколько бы ни старались темные следопыты засечь наши передвижения, им никогда не удавалось подойти близко... до сегодняшнего дня.$B$BПоследний раз их видели возле охотничьего домика на краю леса, к западу отсюда. Когда обнаружишь их, подуй в этот рог, и Тобиас с его охотниками разберутся с проклятой нежитью.$B$BТолько тогда ты сможешь спокойно войти в дом и забрать Косу. Поторопись, $n – она не должна попасть в руки Сильваны!',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лорду Дарию Краули в Тал\'дорен, что в Гилнеасе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24647,'Конец Королевской компании','В этом гроссбухе указано множество мест, и ты, $gпарень, должен:подруга, должна; проверить для меня кое-что. Нельзя допустить, чтобы это продолжалось и дальше.$b$bВот запись, которая меня особенно волнует: в ней говорится о месте за пределами Хилсбрада – да, ты правильно думаешь, там говорится о предгорьях! Не нравится мне это. Иди туда и разберись.$b$bДа, если увидишь что-то большое и опасное – брось в него эту бомбу.','Убейте 5 уборщиков химической компании и воспользуйтесь кориевой бомбой Гвоздезуба, чтобы уничтожить повозку с химикатами за пределами Хилсбрада, в предгорьях. После этого вернитесь к детективу в Оргриммар.','Хорошая работа, $Gпарень:девчонка;. Ты заслуживаешь немного чего-то. И Эй, приходи завтра, если у тебя будет время; у меня может быть для тебя работа.','Ты $Gпреподал:преподала; им урок?','Вернитесь к детективу Крямсу Гвоздезубу на Аллею Силы Оргриммара.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Конец Королевской компании',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В этом гроссбухе указано множество мест, и ты, $gпарень, должен:подруга, должна; проверить для меня кое-что. Нельзя допустить, чтобы это продолжалось и дальше.$b$bВот запись, которая меня особенно волнует: в ней говорится о месте за пределами Хилсбрада – да, ты правильно думаешь, там говорится о предгорьях! Не нравится мне это. Иди туда и разберись.$b$bДа, если увидишь что-то большое и опасное – брось в него эту бомбу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 5 уборщиков химической компании и воспользуйтесь кориевой бомбой Гвоздезуба, чтобы уничтожить повозку с химикатами за пределами Хилсбрада, в предгорьях. После этого вернитесь к детективу в Оргриммар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошая работа, $Gпарень:девчонка;. Ты заслуживаешь немного чего-то. И Эй, приходи завтра, если у тебя будет время; у меня может быть для тебя работа.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gпреподал:преподала; им урок?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к детективу Крямсу Гвоздезубу на Аллею Силы Оргриммара.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24648,'Конец Королевской компании','В этом гроссбухе указано множество мест, и ты, $gпарень, должен:подруга, должна; проверить для меня кое-что. Нельзя допустить, чтобы это продолжалось и дальше.$b$bВот запись, которая меня особенно волнует: в ней говорится о Сторожевом посте за пределами Терамора в Пылевых топях! И не смотри на меня так – это для твоего же блага. Иди туда и разберись.$b$bДа, если увидишь что-то большое и опасное – брось в него эту бомбу.','Убейте 5 забияк химической компании и воспользуйтесь кориевой бомбой Гвоздезуба, чтобы уничтожить повозку с химикатами возле Сторожевого поста за пределами Терамора в Пылевых топях. После этого вернитесь к детективу в Оргриммар.','Хорошая работа, $Gпарень:девчонка;. Ты заслуживаешь немного чего-то. И Эй, приходи завтра, если у тебя будет время; у меня может быть для тебя работа.','Ты $Gпреподал:преподала; им урок?','Вернитесь к детективу Крямсу Гвоздезубу на Аллею Силы Оргриммара.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Конец Королевской компании',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В этом гроссбухе указано множество мест, и ты, $gпарень, должен:подруга, должна; проверить для меня кое-что. Нельзя допустить, чтобы это продолжалось и дальше.$b$bВот запись, которая меня особенно волнует: в ней говорится о Сторожевом посте за пределами Терамора в Пылевых топях! И не смотри на меня так – это для твоего же блага. Иди туда и разберись.$b$bДа, если увидишь что-то большое и опасное – брось в него эту бомбу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 5 забияк химической компании и воспользуйтесь кориевой бомбой Гвоздезуба, чтобы уничтожить повозку с химикатами возле Сторожевого поста за пределами Терамора в Пылевых топях. После этого вернитесь к детективу в Оргриммар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошая работа, $Gпарень:девчонка;. Ты заслуживаешь немного чего-то. И Эй, приходи завтра, если у тебя будет время; у меня может быть для тебя работа.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gпреподал:преподала; им урок?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к детективу Крямсу Гвоздезубу на Аллею Силы Оргриммара.',`completedtext_loc8`);
