INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24653,'Эхо Агамаггана','Я думаю, свинобразами движут не только животные инстинкты. Поможешь мне узнать об этом больше?$b$BЯ заметила, что в их лагерях и поселениях, которых множество к западу отсюда, можно найти особенные кабаньи черепа. Даже с большого расстояния заметно, как они блестят, словно отлично отполированные... в отличие от других останков, которые просто свалены в груды мусора. Думаю, они являются объектом поклонения.$b$BПринеси мне несколько таких черепов, $n, и я детально изучу их.','Соберите 3 отполированных кабаньих черепа.','Вернитесь к Махке в Кремневый лагерь в Южных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Эхо Агамаггана',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я думаю, свинобразами движут не только животные инстинкты. Поможешь мне узнать об этом больше?$b$BЯ заметила, что в их лагерях и поселениях, которых множество к западу отсюда, можно найти особенные кабаньи черепа. Даже с большого расстояния заметно, как они блестят, словно отлично отполированные... в отличие от других останков, которые просто свалены в груды мусора. Думаю, они являются объектом поклонения.$b$BПринеси мне несколько таких черепов, $n, и я детально изучу их.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 3 отполированных кабаньих черепа.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Махке в Кремневый лагерь в Южных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24654,'Проблема с жучками','Ты весь покрыт горячей смолой и репеллентом! Не волнуйся, друг. Это пройдет.$B$BКогда-нибудь.','Альянс – это ерунда. Тучи муравьеобразных тварей?$B$B<Крогол содрогается.>','Вернитесь к Кроголу в Крепость Отчаяния в Южных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Проблема с жучками',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты весь покрыт горячей смолой и репеллентом! Не волнуйся, друг. Это пройдет.$B$BКогда-нибудь.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Альянс – это ерунда. Тучи муравьеобразных тварей?$B$B<Крогол содрогается.>',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кроголу в Крепость Отчаяния в Южных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24655,'Дышать нечем!','Изучите состав воздуха вокруг шести надушенных стражников при помощи анализатора воздуха Гвоздезуба, а затем вернитесь к детективу с результатами.','Спасибо тебе, $Gприятель:приятельница;. А ну-ка, давай посмотрим, что у нас здесь.$B$B<Берет устройство из ваших рук и начинает с ним возиться.>','Ты уже $Gпроанализировал:проанализировала; эту вонь, $Gпарень:девочка;?','Вернитесь к инспектору Кромсу Гвоздезубу в Штормград.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дышать нечем!',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Изучите состав воздуха вокруг шести надушенных стражников при помощи анализатора воздуха Гвоздезуба, а затем вернитесь к детективу с результатами.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо тебе, $Gприятель:приятельница;. А ну-ка, давай посмотрим, что у нас здесь.$B$B<Берет устройство из ваших рук и начинает с ним возиться.>',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты уже $Gпроанализировал:проанализировала; эту вонь, $Gпарень:девочка;?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к инспектору Кромсу Гвоздезубу в Штормград.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (24656,'Позаимствовать духи','Я так и знал, что дело здесь нечисто! Сюда добавлен какой-то химикат, влияющий на подсознание, но с тем количеством, которое у меня есть, хороший анализ не сделаешь. Мне нужно намного больше.\r\n\r\nНо не вздумай покупать духи! Эти негодяи от меня ни гроша не получат. Нет, мы пойдем другим путем.\r\n\r\nСейчас мы замаскируем тебя под посыльного. Я видел, головорезы из химической компании охраняют ящики с товарами возле ворот. Беги мимо, но не останавливайся – иначе они тебя раскусят. Они бросят тебе ящик – хватай его и тащи сюда!','Замаскировавшись под посыльного, отправляйтесь к воротам Штормграда, возле которых находятся товары Королевской химической компании. Добудьте ящик Королевской компании и вернитесь к инспектору Кромсу Гвоздезубу в Штормград.','Ну что, $Gприятель:приятельница;, отличная работа! Высший класс. Давай-ка посмотрим, что у нас здесь.$B$B<Открывает ящик и начинает копаться внутри.>','Они бросили тебе ящик, чтобы доставить?','Украдите ящик с духами Королевской химической компании рядом со Штормградом.','Вернитесь к инспектору Кромсу Гвоздезубу в Штормград.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Позаимствовать духи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я так и знал, что дело здесь нечисто! Сюда добавлен какой-то химикат, влияющий на подсознание, но с тем количеством, которое у меня есть, хороший анализ не сделаешь. Мне нужно намного больше.\r\n\r\nНо не вздумай покупать духи! Эти негодяи от меня ни гроша не получат. Нет, мы пойдем другим путем.\r\n\r\nСейчас мы замаскируем тебя под посыльного. Я видел, головорезы из химической компании охраняют ящики с товарами возле ворот. Беги мимо, но не останавливайся – иначе они тебя раскусят. Они бросят тебе ящик – хватай его и тащи сюда!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Замаскировавшись под посыльного, отправляйтесь к воротам Штормграда, возле которых находятся товары Королевской химической компании. Добудьте ящик Королевской компании и вернитесь к инспектору Кромсу Гвоздезубу в Штормград.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну что, $Gприятель:приятельница;, отличная работа! Высший класс. Давай-ка посмотрим, что у нас здесь.$B$B<Открывает ящик и начинает копаться внутри.>',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Они бросили тебе ящик, чтобы доставить?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Украдите ящик с духами Королевской химической компании рядом со Штормградом.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к инспектору Кромсу Гвоздезубу в Штормград.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24657,'Разговор по душам...','<Марион с отвращением выслушивает, почему вы пытаетесь выследить Снивела.> $B$BХочешь сказать, он опрыскал меня каким-то химикатом? Фу! Как я только могла купиться на эту подставу!$B$BЕсли он закончил все свои дела, то должен направляться к докам, чтобы сесть на корабль, отправляющийся в Южные моря. $n, нельзя допустить, чтобы он поднялся на борт и уплыл, избежав наказания!$B$BБеги в порт Штормграда как можно быстрее!','Отправляйтесь в порт Штормграда и допросите Снивела Ржавстера. Постарайтесь получить хоть какие-нибудь доказательства.','Ты $Gпринес:принесла; его гроссбух? Очень хорошо, $N. Здесь должна быть куча ценной информации!','Ты $Gнашел:нашла; этого парня – или он от тебя улизнул?','Вернитесь к инспектору Кромсу Гвоздезубу в Штормград.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разговор по душам...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Марион с отвращением выслушивает, почему вы пытаетесь выследить Снивела.> $B$BХочешь сказать, он опрыскал меня каким-то химикатом? Фу! Как я только могла купиться на эту подставу!$B$BЕсли он закончил все свои дела, то должен направляться к докам, чтобы сесть на корабль, отправляющийся в Южные моря. $n, нельзя допустить, чтобы он поднялся на борт и уплыл, избежав наказания!$B$BБеги в порт Штормграда как можно быстрее!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в порт Штормграда и допросите Снивела Ржавстера. Постарайтесь получить хоть какие-нибудь доказательства.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты $Gпринес:принесла; его гроссбух? Очень хорошо, $N. Здесь должна быть куча ценной информации!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gнашел:нашла; этого парня – или он от тебя улизнул?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к инспектору Кромсу Гвоздезубу в Штормград.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24658,'Конец Королевской компании','В этом гроссбухе указано множество мест, и ты, $gпарень, должен:подруга, должна; проверить для меня кое-что. Нельзя допустить, чтобы это продолжалось и дальше.$b$bВот запись, которая меня особенно волнует: в ней говорится о месте к северо-востоку от Гарнизона у Западного ручья, что за пределами Элвиннского леса! Не нравится мне это. Иди туда и разберись.$b$bДа, если увидишь что-то большое и опасное – брось в него эту бомбу.','Хорошая работа, $Gпарень:девчонка;. Ты заслуживаешь немного чего-то. И Эй, приходи завтра, если у тебя будет время; у меня может быть для тебя работа.','Ты $Gпреподал:преподала; им урок?','Вернитесь к инспектору Кромсу Гвоздезубу в Торговый квартал Штормграда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Конец Королевской компании',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В этом гроссбухе указано множество мест, и ты, $gпарень, должен:подруга, должна; проверить для меня кое-что. Нельзя допустить, чтобы это продолжалось и дальше.$b$bВот запись, которая меня особенно волнует: в ней говорится о месте к северо-востоку от Гарнизона у Западного ручья, что за пределами Элвиннского леса! Не нравится мне это. Иди туда и разберись.$b$bДа, если увидишь что-то большое и опасное – брось в него эту бомбу.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошая работа, $Gпарень:девчонка;. Ты заслуживаешь немного чего-то. И Эй, приходи завтра, если у тебя будет время; у меня может быть для тебя работа.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gпреподал:преподала; им урок?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к инспектору Кромсу Гвоздезубу в Торговый квартал Штормграда.',`completedtext_loc8`);
