INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24660,'Конец Королевской компании','В этом гроссбухе указано множество мест, и ты, $gпарень, должен:подруга, должна; проверить для меня кое-что. Нельзя допустить, чтобы это продолжалось и дальше.$b$bВот запись, которая меня особенно волнует: в ней говорится о месте к юго-востоку от Темнолесья в Сумеречном лесу. Не нравится мне это. Иди туда и разберись.$b$bДа, если увидишь что-то большое и опасное – брось в него эту бомбу.','Убейте 5 уборщиков химической компании и воспользуйтесь кориевой бомбой Гвоздезуба, чтобы уничтожить повозку с химикатами на заброшенной ферме к юго-востоку от Темнолесья в Сумеречном лесу. После этого вернитесь к инспектору Кромсу Гвоздезубу в Штормград.','Хорошая работа, $Gпарень:девчонка;. Ты заслуживаешь немного чего-то. И Эй, приходи завтра, если у тебя будет время; у меня может быть для тебя работа.','Ты $Gпреподал:преподала; им урок?','Вернитесь к инспектору Кромсу Гвоздезубу в Торговый квартал Штормграда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Конец Королевской компании',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В этом гроссбухе указано множество мест, и ты, $gпарень, должен:подруга, должна; проверить для меня кое-что. Нельзя допустить, чтобы это продолжалось и дальше.$b$bВот запись, которая меня особенно волнует: в ней говорится о месте к юго-востоку от Темнолесья в Сумеречном лесу. Не нравится мне это. Иди туда и разберись.$b$bДа, если увидишь что-то большое и опасное – брось в него эту бомбу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 5 уборщиков химической компании и воспользуйтесь кориевой бомбой Гвоздезуба, чтобы уничтожить повозку с химикатами на заброшенной ферме к юго-востоку от Темнолесья в Сумеречном лесу. После этого вернитесь к инспектору Кромсу Гвоздезубу в Штормград.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошая работа, $Gпарень:девчонка;. Ты заслуживаешь немного чего-то. И Эй, приходи завтра, если у тебя будет время; у меня может быть для тебя работа.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gпреподал:преподала; им урок?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к инспектору Кромсу Гвоздезубу в Торговый квартал Штормграда.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24661,'REUSE ME','В этом гроссбухе указано множество мест, и ты, $gпарень, должен:подруга, должна; проверить для меня кое-что. Нельзя допустить, чтобы это продолжалось и дальше.$b$bВот запись, которая меня особенно волнует: в ней говорится о месте за вратами Оргриммара, на западе! Не нравится мне это. Иди туда и разберись.$b$bДа, если увидишь что-то большое и опасное – брось в него эту бомбу.','Убейте 5 служащих химической компании и воспользуйтесь кориевой бомбой Гвоздезуба, чтобы уничтожить повозку с химикатами к западу от врат Оргриммара в Дуротаре. После этого вернитесь к детективу Крямсу Гвоздезубу в Оргриммар.','Вернитесь к детективу Крямсу Гвоздезубу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','REUSE ME',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В этом гроссбухе указано множество мест, и ты, $gпарень, должен:подруга, должна; проверить для меня кое-что. Нельзя допустить, чтобы это продолжалось и дальше.$b$bВот запись, которая меня особенно волнует: в ней говорится о месте за вратами Оргриммара, на западе! Не нравится мне это. Иди туда и разберись.$b$bДа, если увидишь что-то большое и опасное – брось в него эту бомбу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 5 служащих химической компании и воспользуйтесь кориевой бомбой Гвоздезуба, чтобы уничтожить повозку с химикатами к западу от врат Оргриммара в Дуротаре. После этого вернитесь к детективу Крямсу Гвоздезубу в Оргриммар.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к детективу Крямсу Гвоздезубу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24662,'Конец Королевской компании','В этом гроссбухе указано множество мест, и ты, $gпарень, должен:подруга, должна; проверить для меня кое-что. Нельзя допустить, чтобы это продолжалось и дальше.$b$bВот запись, которая меня особенно волнует: в ней говорится о Сторожевом посте за пределами Терамора в Пылевых топях! И не смотри на меня так – это для твоего же блага. Иди туда и разберись.$b$bДа, если увидишь что-то большое и опасное – брось в него эту бомбу.','Убейте 5 забияк химической компании и воспользуйтесь кориевой бомбой Гвоздезуба, чтобы уничтожить повозку с химикатами возле Сторожевого поста за пределами Терамора в Пылевых топях. После этого вернитесь к инспектору в Штормград.','Хорошая работа, $Gпарень:девчонка;. Ты заслуживаешь немного чего-то. И Эй, приходи завтра, если у тебя будет время; у меня может быть для тебя работа.','Ты $Gпреподал:преподала; им урок?','Вернитесь к инспектору Кромсу Гвоздезубу в Торговый квартал Штормграда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Конец Королевской компании',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В этом гроссбухе указано множество мест, и ты, $gпарень, должен:подруга, должна; проверить для меня кое-что. Нельзя допустить, чтобы это продолжалось и дальше.$b$bВот запись, которая меня особенно волнует: в ней говорится о Сторожевом посте за пределами Терамора в Пылевых топях! И не смотри на меня так – это для твоего же блага. Иди туда и разберись.$b$bДа, если увидишь что-то большое и опасное – брось в него эту бомбу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 5 забияк химической компании и воспользуйтесь кориевой бомбой Гвоздезуба, чтобы уничтожить повозку с химикатами возле Сторожевого поста за пределами Терамора в Пылевых топях. Пос