INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24666,'Конец Королевской компании','Хорошая работа, $Gпарень:девчонка;. Ты заслуживаешь немного чего-то. И Эй, приходи завтра, если у тебя будет время; у меня может быть для тебя работа.','Ты $Gпреподал:преподала; им урок?','Вернитесь к инспектору Кромсу Гвоздезубу в Торговый квартал Штормграда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Конец Королевской компании',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошая работа, $Gпарень:девчонка;. Ты заслуживаешь немного чего-то. И Эй, приходи завтра, если у тебя будет время; у меня может быть для тебя работа.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gпреподал:преподала; им урок?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к инспектору Кромсу Гвоздезубу в Торговый квартал Штормграда.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24667,'Кремневый лагерь','Я возился с силитидами почти месяц, так что теперь я в этом эксперт. Как раз на прошлой неделе тут были Служители Земли и просили меня письменно изложить все, что я знаю.$b$b<Крогол вручает вам потрепанную книгу.>$b$bВообще-то писатель из меня никудышный. Да и читатель тоже, если уж на то пошло. Но все же эта книга представляет собой наиболее подробный справочник, когда-либо написанный об этих гадах.$b$bОтнеси ее Тауне Небесной Охотнице в Кремневый лагерь. Это к югу отсюда, на запад от главной дороги.','Это от Крогола? Замечательно! Хотя в мире сейчас происходят вещи и посерьезнее, мы все же не можем не обращать внимания на проблему с силитидами. Очень важно, что есть такие люди, как Крогол, которые так тщательно изучают наших врагов, это поможет нам в будущих битвах!$B$B<Тауна открывает книгу и бросает взгляд на первую страницу. Она меняется в лице.>$B$BОх. Ну что ж. По крайней мере это хоть что-то.','У тебя какие-то новости с севера?','Отнесите полевой справочник Крогола по силитидам Тауне Небесной Охотнице в Кремневый лагерь в Южных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кремневый лагерь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я возился с силитидами почти месяц, так что теперь я в этом эксперт. Как раз на прошлой неделе тут были Служители Земли и просили меня письменно изложить все, что я знаю.$b$b<Крогол вручает вам потрепанную книгу.>$b$bВообще-то писатель из меня никудышный. Да и читатель тоже, если уж на то пошло. Но все же эта книга представляет собой наиболее подробный справочник, когда-либо написанный об этих гадах.$b$bОтнеси ее Тауне Небесной Охотнице в Кремневый лагерь. Это к югу отсюда, на запад от главной дороги.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это от Крогола? Замечательно! Хотя в мире сейчас происходят вещи и посерьезнее, мы все же не можем не обращать внимания на проблему с силитидами. Очень важно, что есть такие люди, как Крогол, которые так тщательно изучают наших врагов, это поможет нам в будущих битвах!$B$B<Тауна открывает книгу и бросает взгляд на первую страницу. Она меняется в лице.>$B$BОх. Ну что ж. По крайней мере это хоть что-то.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У тебя какие-то новости с севера?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите полевой справочник Крогола по силитидам Тауне Небесной Охотнице в Кремневый лагерь в Южных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (24671,'Куриный переполох','Это просто смешно! Величайший гений-гоблин своего времени занимается поставками продовольствия?! Именно для этих целей я разработал микромеханоцыпа, а они его упустили!$B$B<У Хобарта поднимается давление, он становится темно-зеленым.>$B$BЯ что, похож на загонщика клуш? Нет, друг мой, только не я! Бамм точно похож, но он слишком ленив.$b$bТвое положение в обществе в последнее время сильно пошатнулось, так что ты и займешься этим делом!$B$BВозьми эти фейерверки с дистанционным управлением и прикрепи их к курицам, да побыстрее!','Прикрепите фейерверки с дистанционным управлением к 10 клушам.','Какой успех! Да и кто бы сомневался!$B$BГрили, запускай птицефикатор!','Вернитесь к Хобарту Дреку к Городку-из-табакерки на Затерянных островах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Куриный переполох',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это просто смешно! Величайший гений-гоблин своего времени занимается поставками продовольствия?! Именно для этих целей я разработал микромеханоцыпа, а они его упустили!$B$B<У Хобарта поднимается давление, он становится темно-зеленым.>$B$BЯ что, похож на загонщика клуш? Нет, друг мой, только не я! Бамм точно похож, но он слишком ленив.$b$bТвое положение в обществе в последнее время сильно пошатнулось, так что ты и займешься этим делом!$B$BВозьми эти фейерверки с дистанционным управлением и прикрепи их к курицам, да побыстрее!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Прикрепите фейерверки с дистанционным управлением к 10 клушам.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Какой успех! Да и кто бы сомневался!$B$BГрили, запускай птицефикатор!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хобарту Дреку к Городку-из-табакерки на Затерянных островах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (24672,'Вперед и вверх','Я выполню поручение Дария и проведу наших людей через Черную дубраву.$B$BА ты $gдолжен:должна; догнать короля Седогрива – он с Креннаном отправился в Предел Бури вызволять беженцев, которые, по утверждению лорда Годфри, обосновались в горах.$B$BСледуй по дороге, ведущей из Грозового Перевала. Я попросила Креннана подождать тебя у Предела Бури возле моста.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вперед и вверх',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я выполню поручение Дария и проведу наших людей через Черную дубраву.$B$BА ты $gдолжен:должна; догнать короля Седогрива – он с Креннаном отправился в Предел Бури вызволять беженцев, которые, по утверждению лорда Годфри, обосновались в горах.$B$BСледуй по дороге, ведущей из Грозового Перевала. Я попросила Креннана подождать тебя у Предела Бури возле моста.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (24673,'Возвращение в Грозовой Перевал','Поговорите с Гвен Армстед в Грозовом Перевале.','Король Седогрив вкратце поведал мне о наших планах перед отправлением в Черную дубраву. Честно говоря, мне все это по-прежнему представляется полнейшим безумием.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение в Грозовой Перевал',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Гвен Армстед в Грозовом Перевале.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Король Седогрив вкратце поведал мне о наших планах перед отправлением в Черную дубраву. Честно говоря, мне все это по-прежнему представляется полнейшим безумием.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (24674,'Рабы не мы','Вернитесь к Маркусу на Пост у стойл.','Избавься от этого… этого… ПОГАНИЩА.','Надсмотрщик Бульогг') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рабы не мы',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Маркусу на Пост у стойл.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Избавься от этого… этого… ПОГАНИЩА.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Надсмотрщик Бульогг',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24675,'Последняя трапеза','Я не наивная девочка, $n. Я знаю, что ждет нас впереди.$B$BНаши люди пройдут через эти врата и сразятся с врагом, который сильнее нас, лучше вооружен и превосходит нас в численности.$B$BДаже если мы одержим победу, она достанется нам великой ценой, и для многих из нас эта трапеза станет последней.$B$BЯ не могу держать в руках меч, но зато мне по руке поварской нож. Принеси мне немного мяса оленей, которые бродят по этим полям, и сделаю все для того, чтобы последний ужин наших солдат стал для них лучшим в жизни.','Добудьте 10 кусков вырезки оленины.','Вернитесь к Магде Вайтволл на Пост у стойл в Гилнеасе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Последняя трапеза',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я не наивная девочка, $n. Я знаю, что ждет нас впереди.$B$BНаши люди пройдут через эти врата и сразятся с врагом, который сильнее нас, лучше вооружен и превосходит нас в численности.$B$BДаже если мы одержим победу, она достанется нам великой ценой, и для многих из нас эта трапеза станет последней.$B$BЯ не могу держать в руках меч, но зато мне по руке поварской нож. Принеси мне немного мяса оленей, которые бродят по этим полям, и сделаю все для того, чтобы последний ужин наших солдат стал для них лучшим в жизни.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 10 кусков вырезки оленины.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Магде Вайтволл на Пост у стойл в Гилнеасе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (24676,'Полное уничтожение','Благодаря тебе жители Деревни Тлеющего Угля встанут на нашу сторону.','Вернитесь к Лорне Краули на Пост у стойл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Полное уничтожение',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Благодаря тебе жители Деревни Тлеющего Угля встанут на нашу сторону.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лорне Краули на Пост у стойл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (24677,'Атака с фланга','Спасибо тебе, $n. Но нам еще не время почивать на лаврах.$B$BМы недавно узнали, что один из шахтерских городков находится под оккупацией Отрекшихся. Туда уже отправились мои люди под командованием дочери лорда Краули, а поддержку им вскоре окажет сам принц Лиам.$B$BПоговори с лордом Хьювелом, пусть выдаст тебе лошадь. Я же останусь здесь и закончу зачистку Гилнеаса от нежити.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Атака с фланга',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Спасибо тебе, $n. Но нам еще не время почивать на лаврах.$B$BМы недавно узнали, что один из шахтерских городков находится под оккупацией Отрекшихся. Туда уже отправились мои люди под командованием дочери лорда Краули, а поддержку им вскоре окажет сам принц Лиам.$B$BПоговори с лордом Хьювелом, пусть выдаст тебе лошадь. Я же останусь здесь и закончу зачистку Гилнеаса от нежити.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (24678,'По колено в нечисти','Пора отправляться в путь, $n. Большинство жителей уже переправилось на другую сторону, остались только мы с тобой.$B$BВот, возьми этот факел – он тебе пригодится, чтобы отпугивать кусачих тварей, которые живут в туннеле.$B$BСпустись в туннель по лестнице у меня за спиной, а когда доберешься до выхода, разыщи Креннана, он хотел с тобой поговорить.','Воспользуйтесь полусгоревшим факелом, чтобы добраться до другого конца туннеля под Гилнеасом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','По колено в нечисти',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пора отправляться в путь, $n. Большинство жителей уже переправилось на другую сторону, остались только мы с тобой.$B$BВот, возьми этот факел – он тебе пригодится, чтобы отпугивать кусачих тварей, которые живут в туннеле.$B$BСпустись в туннель по лестнице у меня за спиной, а когда доберешься до выхода, разыщи Креннана, он хотел с тобой поговорить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь полусгоревшим факелом, чтобы добраться до другого конца туннеля под Гилнеасом.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24679,'Благословение патриарха','Ты $gсправился:справилась;, $n! Теперь ты знаешь, что даже в самые тяжелые времена мы должны чтить умерших.$B$BВозьми это подношение и оставь его на могиле Адерика.$B$BНадеюсь, этого будет достаточно, чтобы умиротворить духов наших предков.','Положите благословенные подношения на могилу Адерика.','Вернитесь к Креннану Аранасу в Покой Адерика, что в Гилнеасе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Благословение патриарха',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gсправился:справилась;, $n! Теперь ты знаешь, что даже в самые тяжелые времена мы должны чтить умерших.$B$BВозьми это подношение и оставь его на могиле Адерика.$B$BНадеюсь, этого будет достаточно, чтобы умиротворить духов наших предков.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Положите благословенные подношения на могилу Адерика.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Креннану Аранасу в Покой Адерика, что в Гилнеасе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (24681,'И у нас есть союзники','Мы почти справились, Корольвсех. Теперь от спасения нас отделяет только одно препятствие...','Вернитесь к лорду Дарию Краули в Килевую гавань, что в Гилнеасе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','И у нас есть союзники',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мы почти справились, Корольвсех. Теперь от спасения нас отделяет только одно препятствие...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лорду Дарию Краули в Килевую гавань, что в Гилнеасе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (24682,'Яма Сарона','Быстрее, шагай в портал! Я присоединюсь к тебе позже.','Встретьтесь с леди Сильваной Ветрокрылой на входе в Яму Сарона.','Жалкие идиоты. Я уже начинаю сомневаться, что эти турнирные крысы способны хоть чем-то мне помочь. Надеюсь, ты не из их числа?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Яма Сарона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Быстрее, шагай в портал! Я присоединюсь к тебе позже.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Встретьтесь с леди Сильваной Ветрокрылой на входе в Яму Сарона.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Жалкие идиоты. Я уже начинаю сомневаться, что эти турнирные крысы способны хоть чем-то мне помочь. Надеюсь, ты не из их числа?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (24683,'Яма Сарона','Быстрее, шагай в портал! Я присоединюсь к тебе позже.','Встретьтесь с леди Джайной Праудмур в Яме Сарона.','Я недооценила этого Повелителя Плети и расплатилась за свою ошибку жизнями людей.$B$BКаждый раз, когда я думаю, что не могу больше усугубить свою вину, приведшую к предательству Артаса, жизнь показывает, что это не так.$B$BНо мы не должны сдаваться! Нельзя допустить, чтобы эти смерти оказались бессмысленными.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Яма Сарона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Быстрее, шагай в портал! Я присоединюсь к тебе позже.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Встретьтесь с леди Джайной Праудмур в Яме Сарона.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я недооценила этого Повелителя Плети и расплатилась за свою ошибку жизнями людей.$B$BКаждый раз, когда я думаю, что не могу больше усугубить свою вину, приведшую к предательству Артаса, жизнь показывает, что это не так.$B$BНо мы не должны сдаваться! Нельзя допустить, чтобы эти смерти оказались бессмысленными.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24684,'Визил в курятнике','<Ганн хватает вас рукой, покрытой запекшейся кровью.>$b$bРаны мои серьезны, но я не успокоюсь, пока дворфы Бейл Модана не ответят за свои преступления.<Хрипит.> Во время последнего рейда мы тайно переправили в их крепость одного из наших. Гоблин-диверсант по имени Визил Темнила.$b$bПрорвись к воротам, убей, кого сможешь, проникни в крепость Бейл\'дана, что на юге, и найди Визила.$b$bЭту крепость <кашляет> можно разрушить только изнутри, и Визил не может справиться с этим один.','Отправляйтесь в крепость Бейл\'дан и убейте 10 дворфов Бейл\'дана (ружейников, солдат и офицеров). Затем найдите Визила Темнилу, который должен быть внутри крепости.','Найдите Визила Темнилу в крепости Бейл\'дан в Южных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Визил в курятнике',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Ганн хватает вас рукой, покрытой запекшейся кровью.>$b$bРаны мои серьезны, но я не успокоюсь, пока дворфы Бейл Модана не ответят за свои преступления.<Хрипит.> Во время последнего рейда мы тайно переправили в их крепость одного из наших. Гоблин-диверсант по имени Визил Темнила.$b$bПрорвись к воротам, убей, кого сможешь, проникни в крепость Бейл\'дана, что на юге, и найди Визила.$b$bЭту крепость <кашляет> можно разрушить только изнутри, и Визил не может справиться с этим один.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в крепость Бейл\'дан и убейте 10 дворфов Бейл\'дана (ружейников, солдат и офицеров). Затем найдите Визила Темнилу, который должен быть внутри крепости.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Найдите Визила Темнилу в крепости Бейл\'дан в Южных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24685,'Дворфийская крепость','Не знаю, $gобратил:обратила; ли ты внимание на это, но вся крепость возведена вокруг огромной пушки. Если бы мы могли найти подходящие для нее снаряды, то все тут взлетело бы на воздух как нечего делать!$b$bОднако для того, чтобы найти их, мне нужен план крепости, и до сих пор мне не удавалось украсть его.$b$BПоищи схемы на нижнем этаже. Вот лестница, что ведет туда.','Найдите планы бейл\'данской крепости.','Посмотрим, посмотрим.$B$BПохоже, артиллейрийские снаряды изготовлены здесь, а потом спрятаны в укромном месте…$B$B<Визил потирает руки.>$B$BПихля, ты готова устроить небольшой фейерверк?','Давай сюда планы, быстро! У нас мало времени.','Вернитесь к Визилу Темниле в крепость Бейл\'дан в Южных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дворфийская крепость',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не знаю, $gобратил:обратила; ли ты внимание на это, но вся крепость возведена вокруг огромной пушки. Если бы мы могли найти подходящие для нее снаряды, то все тут взлетело бы на воздух как нечего делать!$b$bОднако для того, чтобы найти их, мне нужен план крепости, и до сих пор мне не удавалось украсть его.$b$BПоищи схемы на нижнем этаже. Вот лестница, что ведет туда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите планы бейл\'данской крепости.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Посмотрим, посмотрим.$B$BПохоже, артиллейрийские снаряды изготовлены здесь, а потом спрятаны в укромном месте…$B$B<Визил потирает руки.>$B$BПихля, ты готова устроить небольшой фейерверк?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Давай сюда планы, быстро! У нас мало времени.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Визилу Темниле в крепость Бейл\'дан в Южных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (24686,'Несомые волей волн','Жизненный цикл кровоцветов Ун\'Горо удивителен.$b$bСемена растут на деревьях, что напротив нас, а когда созревают, падают в реку. Течением реки их уносит к северу отсюда, где из семян, словно из яиц, через какое-то время появляются новорожденные кровоцветы.$b$bМне необходимы эти семена для исследований. Возьми эту сеть и собери с ее помощью яркие оранжевые семена. Это нужно делать под водой.','Выловите семена кровоцветов с помощью сети Гарла. Необходимо 4 штуки.','Ты уже достала семена?','Вернитесь к Гарлу Когтю Бури в Кратер Ун\'Горо.','Эти крохотные семена переносятся подводными течениями.','Семечко кровоцвета') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Несомые волей волн',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Жизненный цикл кровоцветов Ун\'Горо удивителен.$b$bСемена растут на деревьях, что напротив нас, а когда созревают, падают в реку. Течением реки их уносит к северу отсюда, где из семян, словно из яиц, через какое-то время появляются новорожденные кровоцветы.$b$bМне необходимы эти семена для исследований. Возьми эту сеть и собери с ее помощью яркие оранжевые семена. Это нужно делать под водой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выловите семена кровоцветов с помощью сети Гарла. Необходимо 4 штуки.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты уже достала семена?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гарлу Когтю Бури в Кратер Ун\'Горо.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Эти крохотные семена переносятся подводными течениями.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Семечко кровоцвета',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (24687,'Букет смерти','Тебе уже знакома первая фаза жизненного цикла кровоцветов: созревание и водная миграция семян. Следующая фаза, во время которой молодые кровоцветы живут группами, не настолько безобидна.$b$bНоворожденные кровоцветы довольно беззащитны, поэтому первое время они держатся вместе, образуя огромные стаи, – в них слабость каждой отдельной особи компенсируется их большим количеством. Сами по себе стайки молодых кровоцветов неагрессивны, но стоит тронуть одного, как вся стая бросится на защиту.$b$bИх нужно уничтожить ради всеобщей безопасности. Кровоцветы обитают неподалеку: к северу и к западу отсюда.','Убейте 6 стаек молодых кровоцветов.','Ты вернулся с победой. Отлично, отлично... Возможно, кратер станет теперь чуть более безопасным местом для путешественников.','Вернитесь к Итису Лунному Стражу в Топи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Букет смерти',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе уже знакома первая фаза жизненного цикла кровоцветов: созревание и водная миграция семян. Следующая фаза, во время которой молодые кровоцветы живут группами, не настолько безобидна.$b$bНоворожденные кровоцветы довольно беззащитны, поэтому первое время они держатся вместе, образуя огромные стаи, – в них слабость каждой отдельной особи компенсируется их большим количеством. Сами по себе стайки молодых кровоцветов неагрессивны, но стоит тронуть одного, как вся стая бросится на защиту.$b$bИх нужно уничтожить ради всеобщей безопасности. Кровоцветы обитают неподалеку: к северу и к западу отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 6 стаек молодых кровоцветов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты вернулся с победой. Отлично, отлично... Возможно, кратер станет теперь чуть более безопасным местом для путешественников.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Итису Лунному Стражу в Топи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24688,'Зен\'Алири','Ты уже $gвстречал:встречала; одного из моих новых учеников – юного воргена по имени Гарл. Другой ученик – тролль Зен\'Алири. Сейчас он находится в лагере вместе с исследователями экспедиции Маршалла, это к западу отсюда.$b$bПринеси ему вот эти результаты исследований, $n, и пусть он их внимательно прочитает.','Вернитесь к Зен\'Алири на заставу Маршалла.','Вернитесь к Зен\'Алири на заставу Маршалла.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зен\'Алири',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты уже $gвстречал:встречала; одного из моих новых учеников – юного воргена по имени Гарл. Другой ученик – тролль Зен\'Алири. Сейчас он находится в лагере вместе с исследователями экспедиции Маршалла, это к западу отсюда.$b$bПринеси ему вот эти результаты исследований, $n, и пусть он их внимательно прочитает.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь к Зен\'Алири на заставу Маршалла.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Зен\'Алири на заставу Маршалла.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (24689,'По течению на север','С учением Круга Кенария меня познакомил ночной эльф – друид Итис Лунный Страж. Его лагерь расположен к северу отсюда, у откосов в восточной части кратера. Следуй по течению за семенами кровоцветов, они непременно приведут тебя к нему.$b$bЯ изучаю лишь семена и другие реагенты, а вот он занимается гораздо более сложными исследованиями. Если ты хочешь больше узнать о растительном мире Ун\'Горо, тебе необходимо поговорить именно с ним.','Свяжитесь с Итисом Лунным Стражем в Тревожных садах.','А... Тебя послал Гарл? Как его исследования? Он не из тех, кто схватывает все на лету, однако та сила, которой он обладает в форме медведя, вызывает уважение.$B$BА теперь необходимо заняться более важными делами.','Свяжитесь с Итисом Лунным Стражем в Тревожных садах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','По течению на север',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','С учением Круга Кенария меня познакомил ночной эльф – друид Итис Лунный Страж. Его лагерь расположен к северу отсюда, у откосов в восточной части кратера. Следуй по течению за семенами кровоцветов, они непременно приведут тебя к нему.$b$bЯ изучаю лишь семена и другие реагенты, а вот он занимается гораздо более сложными исследованиями. Если ты хочешь больше узнать о растительном мире Ун\'Горо, тебе необходимо поговорить именно с ним.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Свяжитесь с Итисом Лунным Стражем в Тревожных садах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А... Тебя послал Гарл? Как его исследования? Он не из тех, кто схватывает все на лету, однако та сила, которой он обладает в форме медведя, вызывает уважение.$B$BА теперь необходимо заняться более важными делами.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Свяжитесь с Итисом Лунным Стражем в Тревожных садах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (24690,'Яропламень','Я все еще обеспокоен из-за этих элементалей огня, $n. Одна последняя просьба: доберись до верхушки вулкана Огненного венца и убей того из них, которого называют Яропламень. Это самый большой и сильный элементаль огня в кратере. Когда его не станет, я смогу спать спокойнее.','Убейте Яропламеня.','Наконец-то Яропламень отправился на тот свет. Спасибо, Нарейша… Я чуть не спятил, пока он был жив.','Вернитесь к Виллидену Маршаллу на заставу Маршалла.','Он сожжет тебя.','Яропламень') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Яропламень',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я все еще обеспокоен из-за этих элементалей огня, $n. Одна последняя просьба: доберись до верхушки вулкана Огненного венца и убей того из них, которого называют Яропламень. Это самый большой и сильный элементаль огня в кратере. Когда его не станет, я смогу спать спокойнее.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Яропламеня.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Наконец-то Яропламень отправился на тот свет. Спасибо, Нарейша… Я чуть не спятил, пока он был жив.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Виллидену Маршаллу на заставу Маршалла.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Он сожжет тебя.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Яропламень',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24691,'Специфические лакомства','Эй, $gпарень:милашка;, не хочешь чуть подзаработать?$b$bИз авторитетных источников мне стало известно, что некоторые ребята платят ХОРОШИЕ деньги за ноги силитидов. Видимо, если правильно их приготовить, вкус будет отменный. Силитиды похожи на подземных лобстеров и живут прямо к югу отсюда.$b$bПроблема в том, что мне нужно действительно немало этих ног, чтобы заплатить за прикрытие. Как думаешь, сможешь достать мне 8 дюжин или около того?','Раздобудьте 96 ног силитидов.','Мне требуется их так много потому, что я должен платить за погрузку, транспортировку, рекламу... А, да, еще я должен платить тебе.','Вернитесь к Квикксилю на заставу Маршалла.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Специфические лакомства',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эй, $gпарень:милашка;, не хочешь чуть подзаработать?$b$bИз авторитетных источников мне стало известно, что некоторые ребята платят ХОРОШИЕ деньги за ноги силитидов. Видимо, если правильно их приготовить, вкус будет отменный. Силитиды похожи на подземных лобстеров и живут прямо к югу отсюда.$b$bПроблема в том, что мне нужно действительно немало этих ног, чтобы заплатить за прикрытие. Как думаешь, сможешь достать мне 8 дюжин или около того?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте 96 ног силитидов.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мне требуется их так много потому, что я должен платить за погрузку, транспортировку, рекламу... А, да, еще я должен платить тебе.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Квикксилю на заставу Маршалла.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (24692,'Молодой колосс','Если ты хочешь быть $gполезным:полезной;, то, может быть, поможешь нам справиться с одной скрытой угрозой?$b$bК югу отсюда, в самом сердце джунглей, находится аванпост силитидов под названием Скользкий овраг. Его ни с чем не спутаешь, он весь жужжит и вибрирует.$b$bОдин из моих разведчиков донес, что силитиды прячут молодого колосса у себя в центральном подземном зале, и как только он вырастет, они выпустят его прямо в Ун\'Горо!$b$bНельзя допустить, чтобы это произошло, $n. Найди колосса и убей его.','Убейте молодого колосса из улья Гориши.','Вернитесь к Холании Маршалл на заставу Маршалла.','Когда он начнет читать заклинание "Ядовитый взрыв", тебе лучше спрятаться в укрытие.','Молодой колосс из улья Гориши') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Молодой колосс',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если ты хочешь быть $gполезным:полезной;, то, может быть, поможешь нам справиться с одной скрытой угрозой?$b$bК югу отсюда, в самом сердце джунглей, находится аванпост силитидов под названием Скользкий овраг. Его ни с чем не спутаешь, он весь жужжит и вибрирует.$b$bОдин из моих разведчиков донес, что силитиды прячут молодого колосса у себя в центральном подземном зале, и как только он вырастет, они выпустят его прямо в Ун\'Горо!$b$bНельзя допустить, чтобы это произошло, $n. Найди колосса и убей его.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте молодого колосса из улья Гориши.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Холании Маршалл на заставу Маршалла.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Когда он начнет читать заклинание "Ядовитый взрыв", тебе лучше спрятаться в укрытие.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Молодой колосс из улья Гориши',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (24693,'Мшистая горка','Здесь, на заставе Маршалла, практически невозможно спекулировать – у этих ученых все время возникают какие-то подозрения. Тем не менее здесь есть одно местечко, где твоя помощь пригодилась бы.$b$bМой деловой партнер Гремикс расположил свой лагерь к северо-западу отсюда, за вулканом. Он обладает находчивостью, деловой хваткой и видит потенциальные пути получения прибыли даже лучше, чем я. Если хочешь подзаработать, уверен, он сможет подкинуть тебе работенку.','Поговорите с Гремиксом на Мшистой горке.','Отлично, если тебя рекомендовал Квикксиль, то надо полагать, с тобой все в порядке. За все те годы, что мы работаем вместе, Квикксиль ни разу не подвел меня.','Вернитесь к Гремиксу на Мшистую горку.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мшистая горка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Здесь, на заставе Маршалла, практически невозможно спекулировать – у этих ученых все время возникают какие-то подозрения. Тем не менее здесь есть одно местечко, где твоя помощь пригодилась бы.$b$bМой деловой партнер Гремикс расположил свой лагерь к северо-западу отсюда, за вулканом. Он обладает находчивостью, деловой хваткой и видит потенциальные пути получения прибыли даже лучше, чем я. Если хочешь подзаработать, уверен, он сможет подкинуть тебе работенку.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Гремиксом на Мшистой горке.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, если тебя рекомендовал Квикксиль, то надо полагать, с тобой все в порядке. За все те годы, что мы работаем вместе, Квикксиль ни разу не подвел меня.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гремиксу на Мшистую горку.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24694,'Терраса Создателя','<Вглядываясь в шар перед собой, вы слышите голос.>$b$BХрустальные опоры активированы. Достаточное количество кристаллов собрано. Необходимые условия выполнены. Мы готовы к телепортация на Террасу Создателя.$b$bПоговори со мной, когда будешь $gготов:готова;, |3-6($r). Мы посоветуемся с Хранителем.','Поговорите с исследователем Ун\'Горо, чтобы отправиться на Террасу Создателя, после чего отыщите Набию.','Поговорите с исследователем Ун\'Горо, чтобы отправиться на Террасу Создателя, после чего отыщите Набию.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Терраса Создателя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Вглядываясь в шар перед собой, вы слышите голос.>$b$BХрустальные опоры активированы. Достаточное количество кристаллов собрано. Необходимые условия выполнены. Мы готовы к телепортация на Террасу Создателя.$b$bПоговори со мной, когда будешь $gготов:готова;, |3-6($r). Мы посоветуемся с Хранителем.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с исследователем Ун\'Горо, чтобы отправиться на Террасу Создателя, после чего отыщите Набию.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с исследователем Ун\'Горо, чтобы отправиться на Террасу Создателя, после чего отыщите Набию.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24695,'С высоты их мудрости','Потяните за рычаги, что находятся за Набией, и выполните ее задания.','Вернитесь к Набии в Зал Спокойствия.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','С высоты их мудрости',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Потяните за рычаги, что находятся за Набией, и выполните ее задания.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Набии в Зал Спокойствия.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (24696,'Un\'Goro: PRK - E - Shizzle\'s Flyer 02 - Testing It Out') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Un\'Goro: PRK - E - Shizzle\'s Flyer 02 - Testing It Out',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24697,'Как вернуть мясу свежесть','Поверить не могу, что мы встретились... Я Нолен Заклепайко, начальник охраны экспедиции Маршалла. Кроме того, я их кок. Между этими занятиями больше общего, чем тебе кажется.$b$bУ меня есть забавное дельце для тебя. $gЗаметил:Заметила; по периметру лагеря ямы с кольями? Посмотрим, сможешь ли ты заманить туда парочку динозавров из тех, что бродят рядом. Если подбросить им вот этот кусок гнилого мяса, возможны два результата: они либо придут в ярость, либо сойдут с ума от голода. Впрочем, неважно – главное, чтобы они последовали за тобой в яму!','Заманите ближайших динозавров в ямы вокруг заставы Маршалла, бросив им ошметки гниющего мяса.','Вернитесь к Нолену Заклепайко на заставу Маршалла.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Как вернуть мясу свежесть',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Поверить не могу, что мы встретились... Я Нолен Заклепайко, начальник охраны экспедиции Маршалла. Кроме того, я их кок. Между этими занятиями больше общего, чем тебе кажется.$b$bУ меня есть забавное дельце для тебя. $gЗаметил:Заметила; по периметру лагеря ямы с кольями? Посмотрим, сможешь ли ты заманить туда парочку динозавров из тех, что бродят рядом. Если подбросить им вот этот кусок гнилого мяса, возможны два результата: они либо придут в ярость, либо сойдут с ума от голода. Впрочем, неважно – главное, чтобы они последовали за тобой в яму!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заманите ближайших динозавров в ямы вокруг заставы Маршалла, бросив им ошметки гниющего мяса.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Нолену Заклепайко на заставу Маршалла.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (24698,'Археологическая авантюра','Старый добрый Волен. Как его дела? Надеюсь, лучше, чем мои...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Археологическая авантюра',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Старый добрый Волен. Как его дела? Надеюсь, лучше, чем мои...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (24699,'Гормашш Клейкий','Убейте Гормашша и добудьте невероятно липкую смолу.','Да, да, та самая смола…$B$BЭй, минуточку, руки мои, руки... Я не могу их разлепить…$B$BМожет быть, это не такая уж хорошая идея. Впрочем, стоп! Растворитель суперлипкой смолы! Вот что разойдется за полдня!','Вернитесь к Таре на Мшистую горку.','Постарайся не прикасаться к нему, когда будешь убивать.','Гормашш') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гормашш Клейкий',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Гормашша и добудьте невероятно липкую смолу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, да, та самая смола…$B$BЭй, минуточку, руки мои, руки... Я не могу их разлепить…$B$BМожет быть, это не такая уж хорошая идея. Впрочем, стоп! Растворитель суперлипкой смолы! Вот что разойдется за полдня!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Таре на Мшистую горку.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Постарайся не прикасаться к нему, когда будешь убивать.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Гормашш',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24700,'Нелегко собрать','В Смоляных ямах, что к северу отсюда, скрывается настоящее сокровище – редкие цветы, растущие на дне ям. Их называют смолоцветами и особенно ценят за красоту и долговечность. Прошло уже достаточно времени с тех пор, как я наведывалась туда за ними в последний раз, так что новые смолоцветы скорее всего уже выросли. Соберешь несколько для меня?$b$bКстати, удачного плавания в смоле. Совсем не похоже на воду.','Соберите 4 цветка смолоцвета.','Ох, вот и они. Отлично, красавец! Вот немного золота, ты заслужил эту награду.','Ты уже достал смолоцветы? Не вижу их у тебя...','Вернитесь к Таре на Мшистую горку.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нелегко собрать',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В Смоляных ямах, что к северу отсюда, скрывается настоящее сокровище – редкие цветы, растущие на дне ям. Их называют смолоцветами и особенно ценят за красоту и долговечность. Прошло уже достаточно времени с тех пор, как я наведывалась туда за ними в последний раз, так что новые смолоцветы скорее всего уже выросли. Соберешь несколько для меня?$b$bКстати, удачного плавания в смоле. Совсем не похоже на воду.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 4 цветка смолоцвета.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ох, вот и они. Отлично, красавец! Вот немного золота, ты заслужил эту награду.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты уже достал смолоцветы? Не вижу их у тебя...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Таре на Мшистую горку.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (24701,'Мусор Маршалла','Неотъемлемой частью умения делать деньги является отсутствие совести. Ты $gдолжен быть готов:должна быть готова; получить свою выгоду за счет неудач других. И в конце концов все приводит к одному вопросу: "Насколько сильно ты любишь деньги?"$b$bПокидая укрытие на севере, Маршалл и его люди бросили немало припасов. Они не являются редкими и даже хоть чего-то стоящими, но все это находится там, и любой может взять что угодно. Его лагерь высоко в горах на севере.$b$bДа, и смотри по сторонам – что-то же заставило их оттуда бежать...','Раздобудьте 10 упаковок выброшенных припасов.','Это куча хлама, конечно, но куча БЕСПЛАТНОГО хлама, вот что для меня самое главное.$B$BНу, почти бесплатного. Вот твоя награда. Благодарю!','Вернитесь к Дорин на Мшистую горку.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мусор Маршалла',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Неотъемлемой частью умения делать деньги является отсутствие совести. Ты $gдолжен быть готов:должна быть готова; получить свою выгоду за счет неудач других. И в конце концов все приводит к одному вопросу: "Насколько сильно ты любишь деньги?"$b$bПокидая укрытие на севере, Маршалл и его люди бросили немало припасов. Они не являются редкими и даже хоть чего-то стоящими, но все это находится там, и любой может взять что угодно. Его лагерь высоко в горах на севере.$b$bДа, и смотри по сторонам – что-то же заставило их оттуда бежать...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте 10 упаковок выброшенных припасов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это куча хлама, конечно, но куча БЕСПЛАТНОГО хлама, вот что для меня самое главное.$B$BНу, почти бесплатного. Вот твоя награда. Благодарю!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дорин на Мшистую горку.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24702,'Здесь покоится Даданга','Не знавший устали скакун и верный друг.$b$bПогибла вскоре после Катаклизма. Она всегда ненавидела громкие звуки.$b$bВместо цветов оставьте несколько ростков кровоцветов. Не было чего-то, что она любила бы при жизни больше.','Добудьте 10 ростков кровоцветов.','<Вы кладете ростки кровоцветов на могилу, и воздух словно пропитывается благодарностью.>','Не знавший устали скакун и верный друг.$B$BПогибла вскоре после Катаклизма. Она всегда ненавидела громкие звуки.$B$BВместо цветов оставьте несколько ростков кровоцветов. Не было чего-то, что она любила бы при жизни больше.','Вернитесь к могиле Даданги в укрытие Маршалла.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Здесь покоится Даданга',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не знавший устали скакун и верный друг.$b$bПогибла вскоре после Катаклизма. Она всегда ненавидела громкие звуки.$b$bВместо цветов оставьте несколько ростков кровоцветов. Не было чего-то, что она любила бы при жизни больше.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 10 ростков кровоцветов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Вы кладете ростки кровоцветов на могилу, и воздух словно пропитывается благодарностью.>',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Не знавший устали скакун и верный друг.$B$BПогибла вскоре после Катаклизма. Она всегда ненавидела громкие звуки.$B$BВместо цветов оставьте несколько ростков кровоцветов. Не было чего-то, что она любила бы при жизни больше.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к могиле Даданги в укрытие Маршалла.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`) VALUES (24703,'Важный урок','Приветствую тебя, $gпутник:путница;! Ты $gдолжен:должна; знать, что только что $gступил:ступила; на землю, где расположил свой лагерь Максимилиан Североземский! Доводилось ли тебе слышать одну из тех песен, в которой восхваляют мои подвиги? Вижу по глазам, что доводилось. Твое лицо отражает восторг от встречи так же ясно, как воды Озера Каменных Столбов отражают лик Белой Дамы.$b$bНет сомнений, что ты ищешь приключений. И поскольку ты выглядишь достаточно $gспособным:способной; и $gисполненным:исполненной; исключительно благих намерений, я предлагаю тебе стать моим оруженосцем.','Поговорите с Максимилианом Североземским, чтобы узнать больше о том, как стать оруженосцем.','Курс молодого оруженосца пройден') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Важный урок',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приветствую тебя, $gпутник:путница;! Ты $gдолжен:должна; знать, что только что $gступил:ступила; на землю, где расположил свой лагерь Максимилиан Североземский! Доводилось ли тебе слышать одну из тех песен, в которой восхваляют мои подвиги? Вижу по глазам, что доводилось. Твое лицо отражает восторг от встречи так же ясно, как воды Озера Каменных Столбов отражают лик Белой Дамы.$b$bНет сомнений, что ты ищешь приключений. И поскольку ты выглядишь достаточно $gспособным:способной; и $gисполненным:исполненной; исключительно благих намерений, я предлагаю тебе стать моим оруженосцем.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Максимилианом Североземским, чтобы узнать больше о том, как стать оруженосцем.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Курс молодого оруженосца пройден',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24704,'В этом кратере водится множество зловредных драконов. $gВидел:Видела; ли ты их? Они летают повсюду, выставляя напоказ свои шипастые спины и драконьи морды. $b$bНо не обманись, они вовсе не служат прекрасной Алекстразе. Напротив, эти драконы полны злобы, и настоящий герой обязан истребить их.$b$bЯ решил, что убью не меньше 15. Как мой оруженосец ты последуешь за мной. Если отстанешь, возвращайся обратно сюда, к горячим источникам. Здесь ты сможешь найти меня.','Помогите Максимилиану Североземскому убить 15 "драконов".','Найдите Максимилиана в его лагере на Горячих источниках Голакка. Если вы уже сопровождаете Максимилиана, сперва поговорите с ним и попрощайтесь.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В этом кратере водится множество зловредных драконов. $gВидел:Видела; ли ты их? Они летают повсюду, выставляя напоказ свои шипастые спины и драконьи морды. $b$bНо не обманись, они вовсе не служат прекрасной Алекстразе. Напротив, эти драконы полны злобы, и настоящий герой обязан истребить их.$b$bЯ решил, что убью не меньше 15. Как мой оруженосец ты последуешь за мной. Если отстанешь, возвращайся обратно сюда, к горячим источникам. Здесь ты сможешь найти меня.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Помогите Максимилиану Североземскому убить 15 "драконов".',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Найдите Максимилиана в его лагере на Горячих источниках Голакка. Если вы уже сопровождаете Максимилиана, сперва поговорите с ним и попрощайтесь.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`completedtext_loc8`) VALUES (24705,'Найдите Максимилиана в его лагере на Горячих источниках Голакка. Если вы уже сопровождаете Максимилиана, сперва поговорите с ним и попрощайтесь.') ON DUPLICATE KEY UPDATE `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Найдите Максимилиана в его лагере на Горячих источниках Голакка. Если вы уже сопровождаете Максимилиана, сперва поговорите с ним и попрощайтесь.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`objectives_loc8`,`completedtext_loc8`) VALUES (24706,'Не отходите от Максимилиана Североземского, пока он будет говорить с двумя кипящими фуриями.','Найдите Максимилиана в его лагере на Горячих источниках Голакка. Если вы уже сопровождаете Максимилиана, сперва поговорите с ним и попрощайтесь.') ON DUPLICATE KEY UPDATE `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Не отходите от Максимилиана Североземского, пока он будет говорить с двумя кипящими фуриями.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Найдите Максимилиана в его лагере на Горячих источниках Голакка. Если вы уже сопровождаете Максимилиана, сперва поговорите с ним и попрощайтесь.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (24707,'Баллада о Максимилиане','Настал тот час, что мы ждали, оруженосец $n. Прародительница драконов Ун\'Горо примет смерть от моей руки. Наша задача тяжела, и мы отправляемся в опасный путь, но сила Света благословила нас, и теперь успех гарантирован.$b$bТы $gготов:готова; отправиться в путь?','Ура! День прожит не зря! Сегодня мы поняли, что поистине бесценна отвага, а доспехи всегда можно заменить.$B$BВажность твоего участия в этом деле позволяет мне прямо сейчас произвести тебя из оруженосца в начинающего рыцаря. Нас не связывают более узы служения, ты свободна и можешь сама выбирать себе господина.$B$BСтупай с честью, юная героиня! Во имя рыцарства, Света и прекрасной Долории!','Вернитесь к Максимилиану Североземскому на Горячие источники Голакка, что в Кратере Ун\'Горо.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Баллада о Максимилиане',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Настал тот час, что мы ждали, оруженосец $n. Прародительница драконов Ун\'Горо примет смерть от моей руки. Наша задача тяжела, и мы отправляемся в опасный путь, но сила Света благословила нас, и теперь успех гарантирован.$b$bТы $gготов:готова; отправиться в путь?',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ура! День прожит не зря! Сегодня мы поняли, что поистине бесценна отвага, а доспехи всегда можно заменить.$B$BВажность твоего участия в этом деле позволяет мне прямо сейчас произвести тебя из оруженосца в начинающего рыцаря. Нас не связывают более узы служения, ты свободна и можешь сама выбирать себе господина.$B$BСтупай с честью, юная героиня! Во имя рыцарства, Света и прекрасной Долории!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Максимилиану Североземскому на Горячие источники Голакка, что в Кратере Ун\'Горо.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24708,'Костеискатель 3000','Вот что я больше всего не люблю в раскопках, так это то, что на самом деле половину времени ты просто возишься в грязи. Поэтому я проводил большую часть времени здесь, занимаясь конструированием вместо того, чтобы копать.$b$bПозволь продемонстрировать свое изобретение – Костеискатель 3000. Осталось несколько завершающих штрихов, и если он будет работать так, как задумано, то с легкостью обнаружит самые большие кости вокруг. Классно, да?$b$bПроверь его и посмотрим, сможешь ли ты найти какие-нибудь невероятно огромные останки динозавров.','Найдите коготь огромного динозавра.','Вернитесь к Искру Пустокопу на Горячие источники Голакка.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Костеискатель 3000',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот что я больше всего не люблю в раскопках, так это то, что на самом деле половину времени ты просто возишься в грязи. Поэтому я проводил большую часть времени здесь, занимаясь конструированием вместо того, чтобы копать.$b$bПозволь продемонстрировать свое изобретение – Костеискатель 3000. Осталось несколько завершающих штрихов, и если он будет работать так, как задумано, то с легкостью обнаружит самые большие кости вокруг. Классно, да?$b$bПроверь его и посмотрим, сможешь ли ты найти какие-нибудь невероятно огромные останки динозавров.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите коготь огромного динозавра.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Искру Пустокопу на Горячие источники Голакка.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (24709,'Повесть о двух землекопах','Эй-эй, минуточку, на этой кости следы кирки. Это ведь не твоя работа? Нет, мне знакома эта метка... Это, должно быть, тот треклятый дворф! Ага!$b$bПозволь мне отвлечься на минутку и пояснить. К югу отсюда работает еще один археолог по имени Даррин Мрачнокоп, сторонник того безответственного, безрассудного археологического метода, который оскорбляет даже меня.$b$bБесценная кость, испорченная грубой работой киркой. Это была последняя капля, Даррин!$b$b$n, отправляйся и положи конец существованию Мрачнокопа и его небрежным раскопкам.','Убейте Даррина Мрачнокопа и раздобудьте его археологические находки.','Дело сделано? Ты сумела достать его записки?','Вернитесь к Искру Пустокопу на Горячие источники Голакка.','Археология не терпит беспечности, такое нельзя оставлять без наказания.','Даррин Мрачнокоп') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Повесть о двух землекопах',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эй-эй, минуточку, на этой кости следы кирки. Это ведь не твоя работа? Нет, мне знакома эта метка... Это, должно быть, тот треклятый дворф! Ага!$b$bПозволь мне отвлечься на минутку и пояснить. К югу отсюда работает еще один археолог по имени Даррин Мрачнокоп, сторонник того безответственного, безрассудного археологического метода, который оскорбляет даже меня.$b$bБесценная кость, испорченная грубой работой киркой. Это была последняя капля, Даррин!$b$b$n, отправляйся и положи конец существованию Мрачнокопа и его небрежным раскопкам.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Даррина Мрачнокопа и раздобудьте его археологические находки.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Дело сделано? Ты сумела достать его записки?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Искру Пустокопу на Горячие источники Голакка.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Археология не терпит беспечности, такое нельзя оставлять без наказания.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Даррин Мрачнокоп',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (24714,'В поисках Чи-Та 3','Чи-Та неподвижно лежит перед вами. Похоже, ее питание полностью отключено.','Вернитесь к Чи-Та 3 в Кратер Ун\'Горо.','Запрограммированный примат.','Чи-Та 3') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В поисках Чи-Та 3',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Чи-Та неподвижно лежит перед вами. Похоже, ее питание полностью отключено.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Чи-Та 3 в Кратер Ун\'Горо.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Запрограммированный примат.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Чи-Та 3',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24715,'Ремонт Чи-Та 3','<Неожиданно горилла открывает глаза и начинает говорить.>$b$b...действующая мощность... меньше 5%... случайность... масляный резервуар проколот...$b$b...нужно кокосовое молоко... камень... спасти Чи-Та 3...$b$b<Чи-Та закрывает глаза.>','Вы совершенно уверены, что Чи-Та 3 попросила вас достать кокос, расколоть его о ближайший камень и дать ей вязкое кокосовое молоко.','Вы выливаете кокосовое молоко в то, что больше всего похоже на масляный резервуар Чи-Та 3. Вы слышите, как механизмы приходят в действие.','<Чи-Та 3 находится в энергосберегающем режиме.>','Вернитесь к Чи-Та 3 к пещере Лишайников.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ремонт Чи-Та 3',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Неожиданно горилла открывает глаза и начинает говорить.>$b$b...действующая мощность... меньше 5%... случайность... масляный резервуар проколот...$b$b...нужно кокосовое молоко... камень... спасти Чи-Та 3...$b$b<Чи-Та закрывает глаза.>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вы совершенно уверены, что Чи-Та 3 попросила вас достать кокос, расколоть его о ближайший камень и дать ей вязкое кокосовое молоко.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы выливаете кокосовое молоко в то, что больше всего похоже на масляный резервуар Чи-Та 3. Вы слышите, как механизмы приходят в действие.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Чи-Та 3 находится в энергосберегающем режиме.>',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Чи-Та 3 к пещере Лишайников.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24716,'Возвращение Чи-Та 3','Приветствую. Я есть модуль Чи-Та 3. Ты...|3-6($r)?$b$bЧи-Та завершила изучение местных горилл. Чи-Та собрала данные и готова отдать их Карне.$b$bЧи-Та готова вернуться к Карне. Ты тоже? Мы отправляемся немедленно, так что приготовься.','Отведите Чи-Ту 3 обратно к Карне Сомнамбулер на Мшистую горку.','Вернитесь к Карне Сомнамбулер на Мшистую горку.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение Чи-Та 3',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приветствую. Я есть модуль Чи-Та 3. Ты...|3-6($r)?$b$bЧи-Та завершила изучение местных горилл. Чи-Та собрала данные и готова отдать их Карне.$b$bЧи-Та готова вернуться к Карне. Ты тоже? Мы отправляемся немедленно, так что приготовься.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отведите Чи-Ту 3 обратно к Карне Сомнамбулер на Мшистую горку.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Карне Сомнамбулер на Мшистую горку.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24717,'Обезьяны Ун\'Горо','Принесите 2 шкуры ун\'горской гориллы, 2 шкуры ун\'горского топтуна и 2 шкуры ун\'горского рокотуна Гремиксу на Мшистую горку.','Никогда не знаешь, что сейчас в моде и на какую расцветку будет больший спрос. Попробуй достать шкуры разных видов горилл.','Вернитесь к Гремиксу на Мшистую горку.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обезьяны Ун\'Горо',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 2 шкуры ун\'горской гориллы, 2 шкуры ун\'горского топтуна и 2 шкуры ун\'горского рокотуна Гремиксу на Мшистую горку.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Никогда не знаешь, что сейчас в моде и на какую расцветку будет больший спрос. Попробуй достать шкуры разных видов горилл.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гремиксу на Мшистую горку.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (24718,'Могучая У\'ча','Оглядевшись вокруг, вы замечаете в этой части пещеры разбросанные повсюду клочки красного меха, довольно похожего на мех обезьяны.$b$bСудя по тому, что говорил Гремикс, он определенно будет заинтересован в шкуре красной гориллы – если получится ее достать.','Принесите шкуру У\'чи Гремиксу на Мшистую горку.','Красный мех? Так чего ты ждешь! Возвращайся назад и достань шкуру этой красной гориллы! Двойная цена!','Вернитесь к Гремиксу на Мшистую горку.','Вот так-то и выглядит красная горилла.','Могучая У\'ча') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Могучая У\'ча',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Оглядевшись вокруг, вы замечаете в этой части пещеры разбросанные повсюду клочки красного меха, довольно похожего на мех обезьяны.$b$bСудя по тому, что говорил Гремикс, он определенно будет заинтересован в шкуре красной гориллы – если получится ее достать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите шкуру У\'чи Гремиксу на Мшистую горку.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Красный мех? Так чего ты ждешь! Возвращайся назад и достань шкуру этой красной гориллы! Двойная цена!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гремиксу на Мшистую горку.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Вот так-то и выглядит красная горилла.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Могучая У\'ча',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24719,'Белые когти','Остановись, |3-6($r). Помощь $gтакого:такой:c; |3-1($c), как ты, могла бы мне пригодиться.$b$bПрямо за этим лагерем живут ящеры со смертоносными когтями. Я пробовал использовать эти когти для друидических ритуалов, но тщетно. Тем не менее я заметил, что хотя у большинства ящеров когти черного цвета, там есть и другие – с белыми когтями.$b$bПути природы неисповедимы. Может быть, ты $gмог:могла; бы достать мне несколько белых когтей, и я попробую в последний раз?','Добудьте 5 белых когтей равазавра.','Ты уже достала когти?','Вернитесь к Гарлу Когтю Бури в Кратер Ун\'Горо.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Белые когти',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Остановись, |3-6($r). Помощь $gтакого:такой:c; |3-1($c), как ты, могла бы мне пригодиться.$b$bПрямо за этим лагерем живут ящеры со смертоносными когтями. Я пробовал использовать эти когти для друидических ритуалов, но тщетно. Тем не менее я заметил, что хотя у большинства ящеров когти черного цвета, там есть и другие – с белыми когтями.$b$bПути природы неисповедимы. Может быть, ты $gмог:могла; бы достать мне несколько белых когтей, и я попробую в последний раз?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 5 белых когтей равазавра.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты уже достала когти?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гарлу Когтю Бури в Кратер Ун\'Горо.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24720,'Кристаллы силы','Уверена, ты $gвидел:видела; их, $n. Они повсюду! $B$BТы не понимаешь, о чем я? О кристаллах, конечно! Большинство их просто игнорирует, но я чувствую, что в них заключена какая-то сила. Я уже давно провожу с ними эксперименты, но пока, видимо, так же далека от разгадки, как и в первые дни исследований... Впрочем, я не теряю надежды! $B$BСейчас у меня почти вышел запас кристаллов. Не поможешь ли мне его восполнить?$b$bЖелтые кристаллы можно найти на северо-западе, красные на... о, я уверена, ты разберешься.','Соберите по 7 кристаллов силы каждого цвета: красных, синих, желтых и зеленых.','Вернитесь к Джей Ди Колли на заставу Маршалла.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кристаллы силы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Уверена, ты $gвидел:видела; их, $n. Они повсюду! $B$BТы не понимаешь, о чем я? О кристаллах, конечно! Большинство их просто игнорирует, но я чувствую, что в них заключена какая-то сила. Я уже давно провожу с ними эксперименты, но пока, видимо, так же далека от разгадки, как и в первые дни исследований... Впрочем, я не теряю надежды! $B$BСейчас у меня почти вышел запас кристаллов. Не поможешь ли мне его восполнить?$b$bЖелтые кристаллы можно найти на северо-западе, красные на... о, я уверена, ты разберешься.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите по 7 кристаллов силы каждого цвета: красных, синих, желтых и зеленых.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джей Ди Колли на заставу Маршалла.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (24721,'Восточный пилон','В скалах над нами расположен огромный хрустальный пилон. Я понятия не имею, кто и с какой целью установил его здесь, в таком странном месте.$b$bВозможно, тебе удастся узнать больше. Лично мне безразлично, что это такое, так что не нужно возвращаться сюда с отчетом, но вот какого-нибудь исследователя на заставе Маршалла добытая тобой информация может заинтересовать.','Найдите и изучите восточный хрустальный пилон','Вернитесь к Джей Ди Колли на заставу Маршалла.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Восточный пилон',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В скалах над нами расположен огромный хрустальный пилон. Я понятия не имею, кто и с какой целью установил его здесь, в таком странном месте.$b$bВозможно, тебе удастся узнать больше. Лично мне безразлично, что это такое, так что не нужно возвращаться сюда с отчетом, но вот какого-нибудь исследователя на заставе Маршалла добытая тобой информация может заинтересовать.',`details_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Найдите и изучите восточный хрустальный пилон',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джей Ди Колли на заставу Маршалла.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (24722,'Северный пилон','Ты $gоказал:оказала; нам немало услуг, $n... Дай теперь Гремиксу оказать услугу тебе. Атаки на заставу Маршалла, несомненно, внушают ужас. Враг нападал без предупреждений и не брал пленных. Невероятная удача, что столь многим удалось выжить.$b$bНесколько недель назад я проходил мимо хрустального пилона в горах к северо-востоку отсюда, на востоке от заставы Маршалла. Думаю, пилон и эти нападения могут быть связаны. Может быть, ты сможешь выяснить это? Уверен, на заставе Маршалла найдется кому отблагодарить тебя.','Найдите и изучите северный хрустальный пилон','Вернитесь к Джей Ди Колли на заставу Маршалла.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Северный пилон',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gоказал:оказала; нам немало услуг, $n... Дай теперь Гремиксу оказать услугу тебе. Атаки на заставу Маршалла, несомненно, внушают ужас. Враг нападал без предупреждений и не брал пленных. Невероятная удача, что столь многим удалось выжить.$b$bНесколько недель назад я проходил мимо хрустального пилона в горах к северо-востоку отсюда, на востоке от заставы Маршалла. Думаю, пилон и эти нападения могут быть связаны. Может быть, ты сможешь выяснить это? Уверен, на заставе Маршалла найдется кому отблагодарить тебя.',`details_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Найдите и изучите северный хрустальный пилон',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джей Ди Колли на заставу Маршалла.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (24723,'Западный пилон','Исследования Даррина касались в том числе и предмета, крайне интересующего меня – возможной связи между титанами и динозаврами. Джей Ди Колли в лагере только и говорит – титаны то, кристаллы это... Пожалуй, ей было бы интересно.$b$bПрежде, чем отправиться к ней, возможно, ты захочешь проверить хрустальный пилон неподалеку. Он находится прямо среди скал на западе. Пилон покрыт кристаллами, и мне всегда казалось, что он как-то связан с титанами.','Отыщите западный хрустальный пилон.','Найдите и изучите западный хрустальный пилон','Вернитесь к Джей Ди Колли на заставу Маршалла.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Западный пилон',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Исследования Даррина касались в том числе и предмета, крайне интересующего меня – возможной связи между титанами и динозаврами. Джей Ди Колли в лагере только и говорит – титаны то, кристаллы это... Пожалуй, ей было бы интересно.$b$bПрежде, чем отправиться к ней, возможно, ты захочешь проверить хрустальный пилон неподалеку. Он находится прямо среди скал на западе. Пилон покрыт кристаллами, и мне всегда казалось, что он как-то связан с титанами.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщите западный хрустальный пилон.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Найдите и изучите западный хрустальный пилон',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джей Ди Колли на заставу Маршалла.',`completedtext_loc8`);
