INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (24728,'Кристалл-хранитель','Вернитесь к западному хрустальному пилону, что в Кратере Ун\'Горо.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кристалл-хранитель',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к западному хрустальному пилону, что в Кратере Ун\'Горо.',`completedtext_loc8`);
