INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24730,'Игра в кости','Думаешь, раз в экспедиции Маршалла я ответственный за раскопки, то мне страшно нравится копаться в земле? Нет, я, конечно, мог бы придумать более паршивое занятие, но сейчас что-то ничего не приходит в голову.$B$BМы должны были вести раскопки в местечке под названием Путь Ужаса – неплохое название, не находишь? Искать, значит, там дохлых стегодонов и деметродонов... А их там, между прочим, и живых полным полно! Вил и Хол, видишь ли, хотят изучать это гиблое место, поэтому мы должны исправно поставлять им кости динозавров. Между нами говоря, живые для этих целей сгодились бы не хуже!','Добудьте 8 костей динозавров.','Прекрасно, отличные кости, ну просто прелесть, что за кости! А теперь, если позволишь, на тот случай, если кто-то нас слушает...$B$BСПАСИБО, ЧТО ВЫРЫЛ ДЛЯ НАС ЭТИ ДРЕВНЕЙШИЕ КОСТИ И НЕ ОХОТИЛСЯ НА ЖИВОТНЫХ, ЧТО МОГЛО БЫ НАНЕСТИ НЕПОПРАВИМЫЙ УЩЕРБ ОКРУЖАЮЩЕЙ СРЕДЕ!$B$BТихо, тихо, не спорь со мной, мне совершенно не интересно, где ты на самом деле их взял, так что давай замнем этот вопрос для ясности. Вот, возьми это в награду и держи рот на замке, хорошо?','Можешь думать обо мне что хочешь, но эти лабораторные крысы даже не поймут, принадлежат ли принесенные им кости древним динозаврам или тем, которые пытались сожрать нас вместе с палатками прошлой ночью! Выбраться бы отсюда живым...','Вернитесь к Искру Пустокопу на Горячие источники Голакка.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Игра в кости',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Думаешь, раз в экспедиции Маршалла я ответственный за раскопки, то мне страшно нравится копаться в земле? Нет, я, конечно, мог бы придумать более паршивое занятие, но сейчас что-то ничего не приходит в голову.$B$BМы должны были вести раскопки в местечке под названием Путь Ужаса – неплохое название, не находишь? Искать, значит, там дохлых стегодонов и деметродонов... А их там, между прочим, и живых полным полно! Вил и Хол, видишь ли, хотят изучать это гиблое место, поэтому мы должны исправно поставлять им кости динозавров. Между нами говоря, живые для этих целей сгодились бы не хуже!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 8 костей динозавров.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно, отличные кости, ну просто прелесть, что за кости! А теперь, если позволишь, на тот случай, если кто-то нас слушает...$B$BСПАСИБО, ЧТО ВЫРЫЛ ДЛЯ НАС ЭТИ ДРЕВНЕЙШИЕ КОСТИ И НЕ ОХОТИЛСЯ НА ЖИВОТНЫХ, ЧТО МОГЛО БЫ НАНЕСТИ НЕПОПРАВИМЫЙ УЩЕРБ ОКРУЖАЮЩЕЙ СРЕДЕ!$B$BТихо, тихо, не спорь со мной, мне совершенно не интересно, где ты на самом деле их взял, так что давай замнем этот вопрос для ясности. Вот, возьми это в награду и держи рот на замке, хорошо?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Можешь думать обо мне что хочешь, но эти лабораторные крысы даже не поймут, принадлежат ли принесенные им кости древним динозаврам или тем, которые пытались сожрать нас вместе с палатками прошлой ночью! Выбраться бы отсюда живым...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Искру Пустокопу на Горячие источники Голакка.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24731,'Добыча Лар\'корви','Однажды мой брат имел неосторожность отрезать кусок мяса от добычи Лар\'корви, когда того не было рядом. Но оказалось, что Лар\'корви наблюдал за ним из укрытия. После этого Лар\'корви, разрушая все на своем пути, несколько дней преследовал моего брата, пока перепуганный бедняга не решил бежать из кратера.$B$BНо Лар\'корви все равно настиг его недалеко от этого места и убил. $B$BЕсли хочешь привлечь к себе внимание Лар\'корви, найди его свежеубитую добычу и отрежь от нее кусок мяса. $B$BЗатем возвращайся ко мне.$b$bПоиски стоит начать с запада.','Найдите последнюю добычу Лар\'корви и украдите часть трупа жесткозуба.','Вернитесь к землепроходцу Торве в Кратер Ун\'Горо.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Добыча Лар\'корви',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Однажды мой брат имел неосторожность отрезать кусок мяса от добычи Лар\'корви, когда того не было рядом. Но оказалось, что Лар\'корви наблюдал за ним из укрытия. После этого Лар\'корви, разрушая все на своем пути, несколько дней преследовал моего брата, пока перепуганный бедняга не решил бежать из кратера.$B$BНо Лар\'корви все равно настиг его недалеко от этого места и убил. $B$BЕсли хочешь привлечь к себе внимание Лар\'корви, найди его свежеубитую добычу и отрежь от нее кусок мяса. $B$BЗатем возвращайся ко мне.$b$bПоиски стоит начать с запада.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите последнюю добычу Лар\'корви и украдите часть трупа жесткозуба.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к землепроходцу Торве в Кратер Ун\'Горо.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24732,'Запах Лар\'корви','Я удивлен, что Лар\'корви не вышел к тебе, $n! И все же у меня есть задумка, как выманить его. $B$BПоскольку Лар\'корви – доминирующий самец в своей стае, он может выбирать любую самку. А выбирает он многих! Ты найдешь много кладок равазавров к западу отсюда. Подберись к ним поближе и сделай так, чтобы самки напали на тебя. В их головах находятся железы, источающие жуткий запах – так эти твари оповещают своих самцов о готовности к размножению. Принеси мне две такие железы.','Добудьте 2 феромонные железы равазавра.','Вернитесь к землепроходцу Торве в Кратер Ун\'Горо.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Запах Лар\'корви',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я удивлен, что Лар\'корви не вышел к тебе, $n! И все же у меня есть задумка, как выманить его. $B$BПоскольку Лар\'корви – доминирующий самец в своей стае, он может выбирать любую самку. А выбирает он многих! Ты найдешь много кладок равазавров к западу отсюда. Подберись к ним поближе и сделай так, чтобы самки напали на тебя. В их головах находятся железы, источающие жуткий запах – так эти твари оповещают своих самцов о готовности к размножению. Принеси мне две такие железы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 2 феромонные железы равазавра.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к землепроходцу Торве в Кратер Ун\'Горо.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (24733,'Приманка для Лар\'корви','Это самая сложная часть нашего плана. Иди вдоль реки на север, пока не увидишь излучину. Именно там я в последний раз видел Лар\'корви. Ты легко узнаешь это место – там повсюду разбросаны дочиста обглоданные кости крупных животных, имевших неосторожность бродить в этом месте.$b$bВозьми найденное мясо и положи его там. Затем полей мясо вот этим составом.$b$bЕсли это не поможет выманить Лар\'корви, то я не знаю, что еще можно сделать.','Вернитесь к землепроходцу Торве в Кратер Ун\'Горо.','Если и есть что-то, что Лар\'корви любит больше, чем мясо, так это прекрасные дамы.','Лар\'корви') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приманка для Лар\'корви',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это самая сложная часть нашего плана. Иди вдоль реки на север, пока не увидишь излучину. Именно там я в последний раз видел Лар\'корви. Ты легко узнаешь это место – там повсюду разбросаны дочиста обглоданные кости крупных животных, имевших неосторожность бродить в этом месте.$b$bВозьми найденное мясо и положи его там. Затем полей мясо вот этим составом.$b$bЕсли это не поможет выманить Лар\'корви, то я не знаю, что еще можно сделать.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к землепроходцу Торве в Кратер Ун\'Горо.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Если и есть что-то, что Лар\'корви любит больше, чем мясо, так это прекрасные дамы.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Лар\'корви',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24734,'Потерялся!','Помоги мне, $n! Мой друг Ринго отправился сегодня исследовать вулкан к югу отсюда, и его что-то долго нет! Я очень беспокоюсь.$B$BТы сможешь найти его? Вот, возьми с собой эту флягу, уверена, что если ты найдешь его, она ему пригодится!','Найдите следы Ринго у Вулкана Огненного Венца.','Похоже, то, что вы нашли, принадлежит Ринго. Если он оставил свои вещи здесь, то вряд ли ушел слишком далеко. Может быть, стоит поискать его.','Сумка Ринго лежит на скале перед вами.','Найдите следы Ринго у Вулкана Огненного Венца.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Потерялся!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Помоги мне, $n! Мой друг Ринго отправился сегодня исследовать вулкан к югу отсюда, и его что-то долго нет! Я очень беспокоюсь.$B$BТы сможешь найти его? Вот, возьми с собой эту флягу, уверена, что если ты найдешь его, она ему пригодится!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите следы Ринго у Вулкана Огненного Венца.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Похоже, то, что вы нашли, принадлежит Ринго. Если он оставил свои вещи здесь, то вряд ли ушел слишком далеко. Может быть, стоит поискать его.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Сумка Ринго лежит на скале перед вами.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Найдите следы Ринго у Вулкана Огненного Венца.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (24735,'Дружеская помощь','Уф... Как здесь жарко! $B$BЯ тут прогуливался по окрестностям, как вдруг накатила эта жуткая жара. Похоже, у меня тепловой удар. $B$BПомоги мне добраться до моей подруги Мучи на заставу Маршалла. Думаю, я сумею дойти, если кто-то будет вести меня. $B$BЕсли головокружение станет слишком сильным, слегка ударь меня по щеке. А если я вдруг потеряю сознание, просто плесни мне в лицо воды из фляги Мучи. Думаю, этого будет достаточно...','Отведите Ринго к Муче Кусора на заставу Маршалла. $B$BЕсли ему станет нехорошо, похлопайте его по щекам. Если Ринго потеряет сознание, плесните на него воды из фляги Мучи, чтобы привести его в чувство.','Сопроводите Ринго до заставы Маршалла.','Вернитесь к Муче Кусора на заставу Маршалла.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дружеская помощь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Уф... Как здесь жарко! $B$BЯ тут прогуливался по окрестностям, как вдруг накатила эта жуткая жара. Похоже, у меня тепловой удар. $B$BПомоги мне добраться до моей подруги Мучи на заставу Маршалла. Думаю, я сумею дойти, если кто-то будет вести меня. $B$BЕсли головокружение станет слишком сильным, слегка ударь меня по щеке. А если я вдруг потеряю сознание, просто плесни мне в лицо воды из фляги Мучи. Думаю, этого будет достаточно...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отведите Ринго к Муче Кусора на заставу Маршалла. $B$BЕсли ему станет нехорошо, похлопайте его по щекам. Если Ринго потеряет сознание, плесните на него воды из фляги Мучи, чтобы привести его в чувство.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Сопроводите Ринго до заставы Маршалла.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Муче Кусора на заставу Маршалла.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24736,'Крылолет Шиззла','Я работаю над ветролетом! $B$BИ вот, застрял здесь и не могу выбраться! С удовольствием тормознул бы грифона или ветрокрыла, чтобы подбросили меня до Прибамбасска, да только ужасно боюсь этих тварей! $B$BТы мне не поможешь? Мне осталось сделать только крылья, и я думаю, что чешуя терродактиля была бы идеальным материалом. Однако маленькому гоблину не под силу справиться со столь грозными хищниками! А ты на вид весьма $gкрут:крута;! Может, попытаешься добыть мне чешуек?','Соберите 35 чешуй перепончатого терродактиля.','Да, эта чешуя подходит просто превосходно! С помощью этих чешуек мне уж точно удастся поднять мое творение в воздух! $B$BБлагодарю тебя!','Как вы лодку назовете, так она и поплывет! Нужно хорошее имя моему летательному аппарату! Я назову его... Крылолет!','Вернитесь к Шиззлу на Мшистую горку.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Крылолет Шиззла',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я работаю над ветролетом! $B$BИ вот, застрял здесь и не могу выбраться! С удовольствием тормознул бы грифона или ветрокрыла, чтобы подбросили меня до Прибамбасска, да только ужасно боюсь этих тварей! $B$BТы мне не поможешь? Мне осталось сделать только крылья, и я думаю, что чешуя терродактиля была бы идеальным материалом. Однако маленькому гоблину не под силу справиться со столь грозными хищниками! А ты на вид весьма $gкрут:крута;! Может, попытаешься добыть мне чешуек?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 35 чешуй перепончатого терродактиля.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, эта чешуя подходит просто превосходно! С помощью этих чешуек мне уж точно удастся поднять мое творение в воздух! $B$BБлагодарю тебя!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как вы лодку назовете, так она и поплывет! Нужно хорошее имя моему летательному аппарату! Я назову его... Крылолет!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Шиззлу на Мшистую горку.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24737,'Суперлипучка','Я всегда ищу способ быстро заработать. Если ты поможешь воплотить мою последнюю идею, я поделюсь с тобой доходами. Что ты на это скажешь?$b$bТак я и думала!$b$bМы с тобой сделаем немного клея. Ступай к смоляным ямам в северной части Кратера Ун\'Горо и принеси мне смолы. Но не просто смолы, а смолы из монстров, живущих вокруг этих ям. Обычная смола недостаточно липкая.$b$bЯ дам тебе специальный скребок, чтобы руки остались сухими и чистыми.','Соберите 8 образцов сверхлипкой смолы.','Да, похоже, эта смола довольно липкая. Я имею в виду, она липкая, конечно, но не настолько, чтобы покупатели отсыпали монеты горстями за нее. Похоже, тут надо подумать еще.','И снова Тара на коне – суперлипкий клей станет хитом сезона!','Вернитесь к Таре на Мшистую горку.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Суперлипучка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я всегда ищу способ быстро заработать. Если ты поможешь воплотить мою последнюю идею, я поделюсь с тобой доходами. Что ты на это скажешь?$b$bТак я и думала!$b$bМы с тобой сделаем немного клея. Ступай к смоляным ямам в северной части Кратера Ун\'Горо и принеси мне смолы. Но не просто смолы, а смолы из монстров, живущих вокруг этих ям. Обычная смола недостаточно липкая.$b$bЯ дам тебе специальный скребок, чтобы руки остались сухими и чистыми.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 образцов сверхлипкой смолы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, похоже, эта смола довольно липкая. Я имею в виду, она липкая, конечно, но не настолько, чтобы покупатели отсыпали монеты горстями за нее. Похоже, тут надо подумать еще.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','И снова Тара на коне – суперлипкий клей станет хитом сезона!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Таре на Мшистую горку.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24738,'Дневник Вилидена','Вы обнаружили изорванный дневник. Некоторая часть записей все же понятна, и разборчиво видна подпись: "Вилиден Маршалл, полноправный владелец всего, изложенного ниже". Если записи в дневнике актуальны, Виллидена можно найти где-то в центральной части кратера. Согласно дневнику, он вместе со своими спутниками после нападения на их убежище отправился разыскивать подходящую позицию для ответной атаки.','Верните дневник Виллидену Маршаллу, который находится где-то в Кратере Ун\'Горо.','Вернитесь к Виллидену Маршаллу на заставу Маршалла.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дневник Вилидена',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы обнаружили изорванный дневник. Некоторая часть записей все же понятна, и разборчиво видна подпись: "Вилиден Маршалл, полноправный владелец всего, изложенного ниже". Если записи в дневнике актуальны, Виллидена можно найти где-то в центральной части кратера. Согласно дневнику, он вместе со своими спутниками после нападения на их убежище отправился разыскивать подходящую позицию для ответной атаки.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните дневник Виллидену Маршаллу, который находится где-то в Кратере Ун\'Горо.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Виллидену Маршаллу на заставу Маршалла.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24739,'Спасение экспедиции','Меня зовут Виллиден Маршалл. Я руковожу отдельной исследовательской группой. Теперь, когда наш лагерь расположен ближе к центру, мы сможем многое сделать... Например, вернуть кое-что из брошенного имущества.$b$bМы оставили некоторые старые вещи в лагерях, на северо-востоке и юго-западе, которые пришлось покинуть. Ты выглядишь достаточно $gсообразительным:сообразительной;. Может быть, принесешь нам кое-что обратно?','Принесите ящик с провизией и исследовательское оборудование Виллидену Маршаллу в Кратер Ун\'Горо.','Вернитесь к Виллидену Маршаллу на заставу Маршалла.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спасение экспедиции',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Меня зовут Виллиден Маршалл. Я руковожу отдельной исследовательской группой. Теперь, когда наш лагерь расположен ближе к центру, мы сможем многое сделать... Например, вернуть кое-что из брошенного имущества.$b$bМы оставили некоторые старые вещи в лагерях, на северо-востоке и юго-западе, которые пришлось покинуть. Ты выглядишь достаточно $gсообразительным:сообразительной;. Может быть, принесешь нам кое-что обратно?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите ящик с провизией и исследовательское оборудование Виллидену Маршаллу в Кратер Ун\'Горо.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Виллидену Маршаллу на заставу Маршалла.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24740,'Вулканическая активность','Добро пожаловать. Я Виллиден Маршалл, мы с сестрой возглавляем эту экспедицию исследователей и ученых. Есть минутка?$b$bМне очень не нравятся те элементали на вулкане, |3-6($c). У нас здесь слишком много оборудования, заметок... Один безумный элементаль нанесет огромный, огромный ущерб, стоит лишь ему промчаться сквозь лагерь.$b$bДай им понять, что мы не беспомощные соседи. И принеси немного пепла, который остается после них... Раз уж такое дело, заодно проведем небольшое исследование.','Надеюсь, своей цели мы добились. Сохраню этот пепел... Несомненно, однажды он понадобится.','Думаешь, вулкан еще действует? Тогда странно, что во время катаклизма не случилось извержение.','Вернитесь к Виллидену Маршаллу на заставу Маршалла.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вулканическая активность',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Добро пожаловать. Я Виллиден Маршалл, мы с сестрой возглавляем эту экспедицию исследователей и ученых. Есть минутка?$b$bМне очень не нравятся те элементали на вулкане, |3-6($c). У нас здесь слишком много оборудования, заметок... Один безумный элементаль нанесет огромный, огромный ущерб, стоит лишь ему промчаться сквозь лагерь.$b$bДай им понять, что мы не беспомощные соседи. И принеси немного пепла, который остается после них... Раз уж такое дело, заодно проведем небольшое исследование.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Надеюсь, своей цели мы добились. Сохраню этот пепел... Несомненно, однажды он понадобится.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Думаешь, вулкан еще действует? Тогда странно, что во время катаклизма не случилось извержение.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Виллидену Маршаллу на заставу Маршалла.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24741,'Обмен с довеском','Хобарт думает, нам хватит этих клушиных яичек, чтобы наесться? Как же, как же! Надо добыть настоящих яиц, нормального размера!$B$BЯ уже наставил ловушек на утесе Ящеров – вверх по тропе к востоку отсюда. Возьми эти яйца клуши и положи в ловушки. Костлявые ящеры непременно придут за ними, а ты тут как тут – заберешь их яйца, уж они-то покрупнее будут!$B$BПравда, я гений?!','Добудьте 5 яиц костлявых ящеров.','Прелесть! Только посмотри на размерчик!$B$BДреку нипочем не найти яиц крупнее!','Ну, много собрать удалось? Я прямо предвкушаю, какой замечательный омлетище мы сейчас приготовим!','Вернитесь к Бамму Взрыбомму к Городку-из-табакерки на Затерянных островах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обмен с довеском',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хобарт думает, нам хватит этих клушиных яичек, чтобы наесться? Как же, как же! Надо добыть настоящих яиц, нормального размера!$B$BЯ уже наставил ловушек на утесе Ящеров – вверх по тропе к востоку отсюда. Возьми эти яйца клуши и положи в ловушки. Костлявые ящеры непременно придут за ними, а ты тут как тут – заберешь их яйца, уж они-то покрупнее будут!$B$BПравда, я гений?!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 5 яиц костлявых ящеров.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прелесть! Только посмотри на размерчик!$B$BДреку нипочем не найти яиц крупнее!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, много собрать удалось? Я прямо предвкушаю, какой замечательный омлетище мы сейчас приготовим!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бамму Взрыбомму к Городку-из-табакерки на Затерянных островах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24742,'Найти источник','Я разработал термометр, чтобы измерять температуру вулкана, и теперь хочу найти потоки лавы с наивысшей температурой. Термометр дает результаты по шкале Кракленгейта!$B$BВот, держи, отправляйся на хребет и проверь все горячие точки!$b$bВ наиболее горячих точках из земли выступают раскаленные каменные столбы. Найдешь их у основания Вулкана Огненного Венца... Сделаешь круг по периметру и, скорее всего, этого будет достаточно.','Я бы и сам пошел, но уж больно боюсь элементалей огня!','Вернитесь к Краклу на заставу Маршалла.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Найти источник',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я разработал термометр, чтобы измерять температуру вулкана, и теперь хочу найти потоки лавы с наивысшей температурой. Термометр дает результаты по шкале Кракленгейта!$B$BВот, держи, отправляйся на хребет и проверь все горячие точки!$b$bВ наиболее горячих точках из земли выступают раскаленные каменные столбы. Найдешь их у основания Вулкана Огненного Венца... Сделаешь круг по периметру и, скорее всего, этого будет достаточно.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я бы и сам пошел, но уж больно боюсь элементалей огня!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Краклу на заставу Маршалла.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (24743,'Грань Тьмы') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Грань Тьмы',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (24744,'Мегаяйцо','Бамм Взрыбомм? Он кем себя вообще возомнил? Эти яйца его так называемых костлявых ящеров и близко не лежали к тому, что мы собираемся найти!$B$BКак ты прекрасно знаешь, каждый Городок-из-табакерки снабжен микромеханоцыпом как раз на случай подобного пищевого кризиса. К счастью, мой могучий интеллект сумел вычислить, куда удрала наша чудесная запрограммированная цыпочка.$B$BОтправляйся на север, к Выгоревшему оврагу, но берегись: у нее половина контактов перегорела, а другую половину перемкнуло, так что теперь этот механоцып не совсем... даже совсем не микроскопический!','Добудьте мегаяйцо.','Ай да я! Мой гений снова всех спас! Так что отдохни, Бамм Взрыбомм!$B$BА теперь пора пожинать плоды!','Только подумай, как я... ну, мы... будем купаться в лучах славы, когда вернем мегаяйцо!','Вернитесь к Хобарту Дреку в Городок-из-табакерки на Затерянных островах.','Добудь мегаяйцо!','Механоцып') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мегаяйцо',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Бамм Взрыбомм? Он кем себя вообще возомнил? Эти яйца его так называемых костлявых ящеров и близко не лежали к тому, что мы собираемся найти!$B$BКак ты прекрасно знаешь, каждый Городок-из-табакерки снабжен микромеханоцыпом как раз на случай подобного пищевого кризиса. К счастью, мой могучий интеллект сумел вычислить, куда удрала наша чудесная запрограммированная цыпочка.$B$BОтправляйся на север, к Выгоревшему оврагу, но берегись: у нее половина контактов перегорела, а другую половину перемкнуло, так что теперь этот механоцып не совсем... даже совсем не микроскопический!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте мегаяйцо.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ай да я! Мой гений снова всех спас! Так что отдохни, Бамм Взрыбомм!$B$BА теперь пора пожинать плоды!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Только подумай, как я... ну, мы... будем купаться в лучах славы, когда вернем мегаяйцо!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хобарту Дреку в Городок-из-табакерки на Затерянных островах.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Добудь мегаяйцо!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Механоцып',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24745,'Не любовь витает в воздухе (а что-то иное!)','Оборотная сторона открытки исчерчена подробными и зловещими планами по заражению всего Азерота. Вы должны немедленно отнести ее одному из следователей Хитрой Шестеренки!','Принесите выцветшую открытку ко дню всех влюбленных инспектору Кромсу Гвоздезубу в Штормград.','Что это тут у нас?$B$BОго, это уже серьезно. Очень серьезно. Целая куча головоломных деталей в одной упаковке. Спасибо, ты очень $Gпомог:помогла; нам в расследовании. Приятно было работать с тобой.','Ты позаботился об этих коварных злодеях?','Вернитесь к инспектору Кромсу Гвоздезубу в Штормград.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Не любовь витает в воздухе (а что-то иное!)',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Оборотная сторона открытки исчерчена подробными и зловещими планами по заражению всего Азерота. Вы должны немедленно отнести ее одному из следователей Хитрой Шестеренки!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите выцветшую открытку ко дню всех влюбленных инспектору Кромсу Гвоздезубу в Штормград.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что это тут у нас?$B$BОго, это уже серьезно. Очень серьезно. Целая куча головоломных деталей в одной упаковке. Спасибо, ты очень $Gпомог:помогла; нам в расследовании. Приятно было работать с тобой.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты позаботился об этих коварных злодеях?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к инспектору Кромсу Гвоздезубу в Штормград.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (24746,'REUSE','Вернитесь к ...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','REUSE',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ...',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (24747,'Диверсия!','Для воздушных взрывов дворфы встроили в свои снаряды таймеры. Так что все очень просто! Достаточно изменить настройки для одного из снарядов и положить его на погрузочную платформу. Таким образом, он попадет в ствол пушки и – бум, детка. БУМ!$b$bЗа хранилищем на этом уровне находятся две погрузочные платформы со снарядами.$b$BКак только все будет готово... Беги! Беги быстрее ветра, $n! И вернись обратно в лагерь к Ганну. А я сразу за тобой.','Подготовьте все для взрыва дворфийского артиллерийского снаряда и бегите подальше от Бейл\'дана, пока снаряд не взорвался.','Бейл\'дан разрушен?$B$B<Морщась от боли, Ганн поворачивает голову и смотрит на то, как горизонт за его спиной застилают клубы дыма.>$B$BПихля, ты отомстила за Таурахо и за тауренов. Захватчики нескоро оправятся от этого удара. Спасибо тебе.$B$B<Ганн закрывает глаза, его голова наклоняется вперед, он кашляет.>','Вернитесь к Ганну Каменному Копью в Острие копья в Южных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Диверсия!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Для воздушных взрывов дворфы встроили в свои снаряды таймеры. Так что все очень просто! Достаточно изменить настройки для одного из снарядов и положить его на погрузочную платформу. Таким образом, он попадет в ствол пушки и – бум, детка. БУМ!$b$bЗа хранилищем на этом уровне находятся две погрузочные платформы со снарядами.$b$BКак только все будет готово... Беги! Беги быстрее ветра, $n! И вернись обратно в лагерь к Ганну. А я сразу за тобой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Подготовьте все для взрыва дворфийского артиллерийского снаряда и бегите подальше от Бейл\'дана, пока снаряд не взорвался.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Бейл\'дан разрушен?$B$B<Морщась от боли, Ганн поворачивает голову и смотрит на то, как горизонт за его спиной застилают клубы дыма.>$B$BПихля, ты отомстила за Таурахо и за тауренов. Захватчики нескоро оправятся от этого удара. Спасибо тебе.$B$B<Ганн закрывает глаза, его голова наклоняется вперед, он кашляет.>',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ганну Каменному Копью в Острие копья в Южных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (24748,'Последняя битва Короля-лича','Клинок Темной Скорби еще не успел остыть после ковки, но он уже стал частью истории этого мира как оружие неповторимой судьбы.$b$bПриняв его, ты возлагаешь на себя огромную ответственность, и теперь тебе настало время совершить то, что предназначено.$b$bВозьми это оружие, выкованное из легенд и мифов, и отправляйся на бой с врагом. Отомсти за тысячи душ, погубленных за все время этой жестокой войны. Пусть они наконец-то обретут покой.$b$bОбрети мужество, |3-6($c), и веди Темную Скорбь по дороге судьбы.','Верховный лорд Дарион Могрейн приказал вам убить Короля-лича.','Свершилось...$B$BПусть же навеки запомнят жители Азерота наши деяния. Пусть в сердцах их вечно горят жертвенные костры в память о тех, кто погиб на поле боя. И пусть никогда больше не коснется их смертельная опасность перед лицом великого зла.','Вернитесь к верховному лорду Дариону Могрейну.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Последняя битва Короля-лича',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Клинок Темной Скорби еще не успел остыть после ковки, но он уже стал частью истории этого мира как оружие неповторимой судьбы.$b$bПриняв его, ты возлагаешь на себя огромную ответственность, и теперь тебе настало время совершить то, что предназначено.$b$bВозьми это оружие, выкованное из легенд и мифов, и отправляйся на бой с врагом. Отомсти за тысячи душ, погубленных за все время этой жестокой войны. Пусть они наконец-то обретут покой.$b$bОбрети мужество, |3-6($c), и веди Темную Скорбь по дороге судьбы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верховный лорд Дарион Могрейн приказал вам убить Короля-лича.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Свершилось...$B$BПусть же навеки запомнят жители Азерота наши деяния. Пусть в сердцах их вечно горят жертвенные костры в память о тех, кто погиб на поле боя. И пусть никогда больше не коснется их смертельная опасность перед лицом великого зла.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному лорду Дариону Могрейну.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (24749,'Сила нечестивости','Чтобы раскрыть истинный потенциал оружия, тебе придется наполнить клинок положенными ему силами, и прежде всего – нечестивостью.$b$bНайди и убей существо, зовущееся профессором Мерзоцидом... Впрочем, одной его смертью ты не добьешься своей цели. Тебе придется использовать его средства против него самого.$b$bНайди способ поглотить его мутировавшую слизь. Используй эту мерзостную субстанцию, чтобы наполнить оружие силой нечестивости. Если ты справишься с этим заданием, я скажу тебе, что делать дальше.','Наполните Грань Тьмы силой нечестивости и убейте профессора Мерзоцида.','Вернитесь к верховному лорду Дариону Могрейну.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сила нечестивости',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чтобы раскрыть истинный потенциал оружия, тебе придется наполнить клинок положенными ему силами, и прежде всего – нечестивостью.$b$bНайди и убей существо, зовущееся профессором Мерзоцидом... Впрочем, одной его смертью ты не добьешься своей цели. Тебе придется использовать его средства против него самого.$b$bНайди способ поглотить его мутировавшую слизь. Используй эту мерзостную субстанцию, чтобы наполнить оружие силой нечестивости. Если ты справишься с этим заданием, я скажу тебе, что делать дальше.',`details_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Наполните Грань Тьмы силой нечестивости и убейте профессора Мерзоцида.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному лорду Дариону Могрейну.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (24750,'Возрождение Черного Копья','Племя Черного Копья стало жертвой обстоятельств. Мы попали в изгнание. Раз за разом мы были вынуждены покидать свои дома... Однако на сей раз мы не сбежим как трусы.$B$BВол\'джин всегда мудро правил племенем и долгое время оберегал нас от невзгод. Сейчас же его мудрость подсказывает ему, что под началом Гарроша Адского Крика Орду ждет непонятное будущее.$B$BВ этот раз мы не сбежим. Мы будем сражаться за свой дом до конца.$B$BПора начать твое обучение, $n. Отправляйся на восток и поговори с Соратой.','Найдите Сорату на тренировочной площадке Черного Копья.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возрождение Черного Копья',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Племя Черного Копья стало жертвой обстоятельств. Мы попали в изгнание. Раз за разом мы были вынуждены покидать свои дома... Однако на сей раз мы не сбежим как трусы.$B$BВол\'джин всегда мудро правил племенем и долгое время оберегал нас от невзгод. Сейчас же его мудрость подсказывает ему, что под началом Гарроша Адского Крика Орду ждет непонятное будущее.$B$BВ этот раз мы не сбежим. Мы будем сражаться за свой дом до конца.$B$BПора начать твое обучение, $n. Отправляйся на восток и поговори с Соратой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Сорату на тренировочной площадке Черного Копья.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24751,'Азы мастерства: поражение цели','Ну ладно, $gдружище:подруга;. Начнем с самого простого. Хочу убедиться, что ты владеешь азами тайных искусств.$B$BДавай-ка попробуем поразить эти манекены-тики. Не торопись. Делай как получится. А я посмотрю, насколько ты умеешь творить заклинания.','Уничтожьте 6 манекенов-тики.','Вернитесь к Сорате на тренировочную площадку Черного Копья на островах Эха.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Азы мастерства: поражение цели',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну ладно, $gдружище:подруга;. Начнем с самого простого. Хочу убедиться, что ты владеешь азами тайных искусств.$B$BДавай-ка попробуем поразить эти манекены-тики. Не торопись. Делай как получится. А я посмотрю, насколько ты умеешь творить заклинания.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 6 манекенов-тики.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сорате на тренировочную площадку Черного Копья на островах Эха.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24753,'Практическое занятие','Пора применить все эти умения на практике, $gдружище:подруга;. Для начала дам простое задание.$B$BСмотри, рыси убивают кабанов. А кабаны – наш продовольственный запас, и как-то вовсе не хочется им делиться. Если желаешь сегодня поужинать, кабаны должны быть живы. По крайней мере, до вечера.$B$BРыси здесь повсюду. Принеси мне побольше их шкур.','Добудьте 6 шкур буйногривой рыси.','Вернитесь к Сорате на тренировочную площадку Черного Копья на островах Эха.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Практическое занятие',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пора применить все эти умения на практике, $gдружище:подруга;. Для начала дам простое задание.$B$BСмотри, рыси убивают кабанов. А кабаны – наш продовольственный запас, и как-то вовсе не хочется им делиться. Если желаешь сегодня поужинать, кабаны должны быть живы. По крайней мере, до вечера.$B$BРыси здесь повсюду. Принеси мне побольше их шкур.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 6 шкур буйногривой рыси.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сорате на тренировочную площадку Черного Копья на островах Эха.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24754,'Яма испытаний','Ты отлично $gсправился:справилась;, |3-6($c). Может, я и мог бы тебя еще чему-то научить, но глупо тратить время на тренировки.$B$BТебя ждет последний экзамен. Отправляйся в яму испытаний, что в центре этой области, и сразись с настоящим противником – таким, который жаждет тебя растерзать. Когда будешь $gготов:готова;, дай смотрителю знак.','Поговорите с тюремщиком Черного Копья, а затем спуститесь в яму испытаний и убейте пленного разведчика из клана Злобной Чешуи.','Вернитесь к Сорате на тренировочную площадку Черного Копья на островах Эха.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Яма испытаний',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты отлично $gсправился:справилась;, |3-6($c). Может, я и мог бы тебя еще чему-то научить, но глупо тратить время на тренировки.$B$BТебя ждет последний экзамен. Отправляйся в яму испытаний, что в центре этой области, и сразись с настоящим противником – таким, который жаждет тебя растерзать. Когда будешь $gготов:готова;, дай смотрителю знак.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с тюремщиком Черного Копья, а затем спуститесь в яму испытаний и убейте пленного разведчика из клана Злобной Чешуи.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сорате на тренировочную площадку Черного Копья на островах Эха.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (24755,'Превосходя ожидания','Ты превосходишь все наши ожидания, так что хватит ходить в новичках – самое время взяться за что-нибудь серьезное.$B$BОтправляйся в деревню, что к юго-востоку отсюда, и начинай выполнять различные поручения. Будь на виду – и тебе быстро предложат серьезную работу.','Поговорите с Вол\'джином в крепости Черного Копья.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Превосходя ожидания',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты превосходишь все наши ожидания, так что хватит ходить в новичках – самое время взяться за что-нибудь серьезное.$B$BОтправляйся в деревню, что к юго-востоку отсюда, и начинай выполнять различные поручения. Будь на виду – и тебе быстро предложат серьезную работу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Вол\'джином в крепости Черного Копья.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (24756,'Сила крови','Итак, твое оружие готово к тому, чтобы его наделили силой крови.$b$bТебе предстоит сразиться с королевой Лана\'тель, ибо только так ты сможешь попасть под влияние ее Кровавого зеркала. С помощью этой силы Грань Тьмы выпьет кровь ближайшего живого существа – тебя, |3-6($r).$b$bКогда меч пробудится, поддайся бешеной кровожадности, которую насылает королева, и используй обретенную силу, чтобы убить ее.$b$bПусть ее крики дойдут до самого Короля-лича, и в ее предсмертном вопле он услышит свой приговор.','Наполните Грань Тьмы силой крови и убейте Лана\'тель.','Вернитесь к верховному лорду Дариону Могрейну.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сила крови',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Итак, твое оружие готово к тому, чтобы его наделили силой крови.$b$bТебе предстоит сразиться с королевой Лана\'тель, ибо только так ты сможешь попасть под влияние ее Кровавого зеркала. С помощью этой силы Грань Тьмы выпьет кровь ближайшего живого существа – тебя, |3-6($r).$b$bКогда меч пробудится, поддайся бешеной кровожадности, которую насылает королева, и используй обретенную силу, чтобы убить ее.$b$bПусть ее крики дойдут до самого Короля-лича, и в ее предсмертном вопле он услышит свой приговор.',`details_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Наполните Грань Тьмы силой крови и убейте Лана\'тель.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному лорду Дариону Могрейну.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (24757,'Сила льда','Теперь Грань Тьмы готова впитать последний глоток силы.$b$bРади этого умрет Синдрагоса, что прогибает спину под самим Королем-личом. Но прежде чем она падет, тебе придется пережить четыре ее ледяных вздоха.$b$bПосле смерти Синдрагосы ничто не будет стоять между тобой и Королем-личом.','Теперь топор впитал великую силу, и кузня уже готова к выковке Темной Скорби.','Наполните Грань Тьмы силой льда и убейте Синдрагосу.','Вернитесь к верховному лорду Дариону Могрейну.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сила льда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь Грань Тьмы готова впитать последний глоток силы.$b$bРади этого умрет Синдрагоса, что прогибает спину под самим Королем-личом. Но прежде чем она падет, тебе придется пережить четыре ее ледяных вздоха.$b$bПосле смерти Синдрагосы ничто не будет стоять между тобой и Королем-личом.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь топор впитал великую силу, и кузня уже готова к выковке Темной Скорби.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Наполните Грань Тьмы силой льда и убейте Синдрагосу.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному лорду Дариону Могрейну.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (24758,'Возрождение Черного Копья','Племя Черного Копья стало жертвой обстоятельств. Мы попали в изгнание. Раз за разом мы были вынуждены покидать свои дома... Однако на сей раз мы не сбежим как трусы.$B$BВол\'джин всегда мудро правил племенем и долгое время оберегал нас от невзгод. Сейчас же его мудрость подсказывает ему, что под началом Гарроша Адского Крика Орду ждет непонятное будущее.$B$BВ этот раз мы не сбежим. Мы будем сражаться за свой дом до конца.$B$BПора начать твое обучение, $n. Отправляйся на восток и поговори с Некали.','Повстречайтесь с Некали на тренировочной площадке Черного Копья.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возрождение Черного Копья',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Племя Черного Копья стало жертвой обстоятельств. Мы попали в изгнание. Раз за разом мы были вынуждены покидать свои дома... Однако на сей раз мы не сбежим как трусы.$B$BВол\'джин всегда мудро правил племенем и долгое время оберегал нас от невзгод. Сейчас же его мудрость подсказывает ему, что под началом Гарроша Адского Крика Орду ждет непонятное будущее.$B$BВ этот раз мы не сбежим. Мы будем сражаться за свой дом до конца.$B$BПора начать твое обучение, $n. Отправляйся на восток и поговори с Некали.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Повстречайтесь с Некали на тренировочной площадке Черного Копья.',`objectives_loc8`);
