INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (24762,'А ты молодец. Когда-нибудь станешь очень сильной.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А ты молодец. Когда-нибудь станешь очень сильной.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (24763,'Превосходя ожидания','Ты превосходишь все наши ожидания, так что хватит ходить в новичках – самое время взяться за что-нибудь серьезное.$B$BОтправляйся в деревню, что к юго-востоку отсюда, и начинай выполнять различные поручения. Будь на виду – и тебе быстро предложат серьезную работу.','Поговорите с Вол\'джином в крепости Черного Копья.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Превосходя ожидания',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты превосходишь все наши ожидания, так что хватит ходить в новичках – самое время взяться за что-нибудь серьезное.$B$BОтправляйся в деревню, что к юго-востоку отсюда, и начинай выполнять различные поручения. Будь на виду – и тебе быстро предложат серьезную работу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Вол\'джином в крепости Черного Копья.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (24764,'Возрождение Черного Копья','Племя Черного Копья стало жертвой обстоятельств. Мы попали в изгнание. Раз за разом мы были вынуждены покидать свои дома... Однако на сей раз мы не сбежим как трусы.$B$BВол\'джин всегда мудро правил племенем и долгое время оберегал нас от невзгод. Сейчас же его мудрость подсказывает ему, что под началом Гарроша Адского Крика Орду ждет непонятное будущее.$B$BВ этот раз мы не сбежим. Мы будем сражаться за свой дом до конца.$B$BПора начать твое обучение, $n. Отправляйся на восток и поговори с Зен\'таброй.','Найдите Зен\'табру на тренировочной площадке Черного Копья.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возрождение Черного Копья',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Племя Черного Копья стало жертвой обстоятельств. Мы попали в изгнание. Раз за разом мы были вынуждены покидать свои дома... Однако на сей раз мы не сбежим как трусы.$B$BВол\'джин всегда мудро правил племенем и долгое время оберегал нас от невзгод. Сейчас же его мудрость подсказывает ему, что под началом Гарроша Адского Крика Орду ждет непонятное будущее.$B$BВ этот раз мы не сбежим. Мы будем сражаться за свой дом до конца.$B$BПора начать твое обучение, $n. Отправляйся на восток и поговори с Зен\'таброй.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Зен\'табру на тренировочной площадке Черного Копья.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24765,'Азы мастерства: поражение цели','Ну ладно, $gдружище:подруга;. Начнем с самого простого. Хочу убедиться, что ты владеешь азами тайных искусств.$B$BДавай-ка попробуем поразить эти манекены-тики. Не торопись. Делай, как получится. А я посмотрю, насколько ты умеешь творить заклинания.','Уничтожьте 6 манекенов-тики.','Вернитесь к Зен\'табре на тренировочную площадку Черного Копья на островах Эха.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Азы мастерства: поражение цели',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну ладно, $gдружище:подруга;. Начнем с самого простого. Хочу убедиться, что ты владеешь азами тайных искусств.$B$BДавай-ка попробуем поразить эти манекены-тики. Не торопись. Делай, как получится. А я посмотрю, насколько ты умеешь творить заклинания.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 6 манекенов-тики.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Зен\'табре на тренировочную площадку Черного Копья на островах Эха.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24766,'Искусство друида','Достигните 3-го уровня, чтобы выучить "Лунный огонь". Потренируйтесь в его использовании на манекене-тики на тренировочной площадке Черного Копья.','Вернитесь к Зен\'табре на тренировочную площадку Черного Копья на островах Эха.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Искусство друида',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Достигните 3-го уровня, чтобы выучить "Лунный огонь". Потренируйтесь в его использовании на манекене-тики на тренировочной площадке Черного Копья.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Зен\'табре на тренировочную площадку Черного Копья на островах Эха.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24767,'Практическое занятие','Пора применить все эти умения на практике, $gдружище:подруга;. Для начала дам простое задание.$B$BСмотри, рыси убивают кабанов. А кабаны – наш продовольственный запас, и как-то вовсе не хочется им делиться. Если желаешь сегодня поужинать, кабаны должны быть живы. По крайней мере, до вечера.$B$BРыси здесь повсюду. Принеси мне побольше их шкур.','Добудьте 6 шкур буйногривой рыси.','Вернитесь к Зен\'табре на тренировочную площадку Черного Копья на островах Эха.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Практическое занятие',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пора применить все эти умения на практике, $gдружище:подруга;. Для начала дам простое задание.$B$BСмотри, рыси убивают кабанов. А кабаны – наш продовольственный запас, и как-то вовсе не хочется им делиться. Если желаешь сегодня поужинать, кабаны должны быть живы. По крайней мере, до вечера.$B$BРыси здесь повсюду. Принеси мне побольше их шкур.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 6 шкур буйногривой рыси.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Зен\'табре на тренировочную площадку Черного Копья на островах Эха.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24768,'Яма испытаний','Поговорите с тюремщиком Черного Копья, а затем спуститесь в яму испытаний и убейте пленного разведчика из клана Злобной Чешуи.','Вернитесь к Зен\'табре на тренировочную площадку Черного Копья на островах Эха.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Яма испытаний',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с тюремщиком Черного Копья, а затем спуститесь в яму испытаний и убейте пленного разведчика из клана Злобной Чешуи.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Зен\'табре на тренировочную площадку Черного Копья на островах Эха.',`completedtext_loc8`);
