INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) VALUES (24785,'Конечно, это не самые страшные зверюги, но царапаются изрядно. Могут все ноги тебе изодрать, если их вовремя не унести. Ноги в смысле, не рысей.') ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Конечно, это не самые страшные зверюги, но царапаются изрядно. Могут все ноги тебе изодрать, если их вовремя не унести. Ноги в смысле, не рысей.',`requestitemstext_loc8`);
