INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (24792,'Засланный шпион','Кажется мне, что ты вполне можешь стать во главе этой операции. В журнале сказано, что он скрывается в Крепости Темного Клыка, и именно туда я намереваюсь тебя послать.$b$bОдин из наших людей уже проделал этот путь, но он недостаточно силен, чтобы закончить начатое. Иди же и встреться со следователем – да не забудь прихватить с собой друзей!','Найдите следователя Феззена Клейстра в Крепости Темного Клыка.','Фантастика. Помощь именно то, что мне нужно.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Засланный шпион',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кажется мне, что ты вполне можешь стать во главе этой операции. В журнале сказано, что он скрывается в Крепости Темного Клыка, и именно туда я намереваюсь тебя послать.$b$bОдин из наших людей уже проделал этот путь, но он недостаточно силен, чтобы закончить начатое. Иди же и встреться со следователем – да не забудь прихватить с собой друзей!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите следователя Феззена Клейстра в Крепости Темного Клыка.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Фантастика. Помощь именно то, что мне нужно.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (24793,'Засланный шпион','Кажется мне, что ты вполне можешь стать во главе этой операции. В журнале сказано, что он скрывается в Крепости Темного Клыка, и именно туда я намереваюсь тебя послать.$b$bОдин из наших людей уже проделал этот путь, но он недостаточно силен, чтобы закончить начатое. Иди же и встреться со следователем – да не забудь прихватить с собой друзей!','Найдите следователя Феззена Клейстра в Крепости Темного Клыка.','Фантастика. Помощь именно то, что мне нужно.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Засланный шпион',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кажется мне, что ты вполне можешь стать во главе этой операции. В журнале сказано, что он скрывается в Крепости Темного Клыка, и именно туда я намереваюсь тебя послать.$b$bОдин из наших людей уже проделал этот путь, но он недостаточно силен, чтобы закончить начатое. Иди же и встреться со следователем – да не забудь прихватить с собой друзей!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите следователя Феззена Клейстра в Крепости Темного Клыка.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Фантастика. Помощь именно то, что мне нужно.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (24794,'Поговорить с Мучей','Моя давняя подруга Муча последнее время сильно обеспокоена. Я бы помог ей, но, как видишь, мне тут сейчас более чем комфортно.$b$bНе $gмог:могла; бы ты проведать ее и выяснить, в чем дело?','Поговорите с Мучей Кусора на заставе Маршалла.','Что? Тебя послал Кракл?','Поговорите с Мучей Кусора на заставе Маршалла.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поговорить с Мучей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Моя давняя подруга Муча последнее время сильно обеспокоена. Я бы помог ей, но, как видишь, мне тут сейчас более чем комфортно.$b$bНе $gмог:могла; бы ты проведать ее и выяснить, в чем дело?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Мучей Кусора на заставе Маршалла.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что? Тебя послал Кракл?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Мучей Кусора на заставе Маршалла.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`objectives_loc8`,`completedtext_loc8`) VALUES (24795,'Принесите восстановленный Кель\'Делар Вершительнице правосудия Мариэль Чистосердечной на ристалище Серебряного Турнира.','Вернитесь к Вершительнице правосудия Мариэль Чистосердечной в Серебряный павильон на Ристалище Серебряного турнира.') ON DUPLICATE KEY UPDATE `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите восстановленный Кель\'Делар Вершительнице правосудия Мариэль Чистосердечной на ристалище Серебряного Турнира.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Вершительнице правосудия Мариэль Чистосердечной в Серебряный павильон на Ристалище Серебряного турнира.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24796,'Принесите восстановленный Кель\'Делар Верисе Ветрокрылой в Аметистовую цитадель Даларана.','Ты совершила настоящий подвиг, Лолита. День, когда погибли Талориен и Анастериан, когда казалось, будто Кель\'Делар потерян навсегда, стал самым темным в моей жизни. Для меня нет большей радости, чем видеть легендарный клинок возрожденным.$B$BУ меня нет ни тени сомнения в том, что ты предназначена быть его владельцем. Магия Кель\'Делар уже объединила клинок с твоей силой и твоими умениями.','Это правда, что тебе удалось восстановить Кель\'Делар?','Вернитесь к Верисе Ветрокрылой в Аметистовую цитадель, что в Даларане.') ON DUPLICATE KEY UPDATE `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите восстановленный Кель\'Делар Верисе Ветрокрылой в Аметистовую цитадель Даларана.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты совершила настоящий подвиг, Лолита. День, когда погибли Талориен и Анастериан, когда казалось, будто Кель\'Делар потерян навсегда, стал самым темным в моей жизни. Для меня нет большей радости, чем видеть легендарный клинок возрожденным.$B$BУ меня нет ни тени сомнения в том, что ты предназначена быть его владельцем. Магия Кель\'Делар уже объединила клинок с твоей силой и твоими умениями.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Это правда, что тебе удалось восстановить Кель\'Делар?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Верисе Ветрокрылой в Аметистовую цитадель, что в Даларане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (24797,'REUSE') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','REUSE',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24798,'Победа Похитителей Солнца','Наконец-то Кель\'Делар восстановлен во славу всех Похитителей Солнца и величайшей расы син\'дорай!$B$BОтныне ты – $gгерой:героиня; Луносвета, $n.$B$BУвы, клинок почувствовал, что ты $gнеопытен:неопытна; в обращении с мечами, и потому не связал с тобой свою силу. Кто же станет его истинным хозяином? Я не знаю син\'дорай, достойного этой чести. Только Серебряный Авангард сможет нам помочь. Отправляйся к ристалищу Серебряного Турнира и передай этот клинок Вершительнице правосудия Мариэль Чистосердечной.','Принесите восстановленный Кель\'Делар Вершительнице правосудия Мариэль Чистосердечной на ристалище Серебряного Турнира.','Освобождение великого меча из хватки злых сил – это благой знак, дающий нам надежду в темные времена. Теперь, когда на нашей стороне Кель\'Делар и союзники из Похитителей Солнца, у Короля-лича есть повод бояться за свою жизнь.$B$BАвангард владеет огромной оружейной. Если ты доверишь нам Кель\'Делар, мы подберем тебе взамен клинок, достойный героя.','Это правда, что тебе удалось восстановить Кель\'Делар?','Вернитесь к Вершительнице правосудия Мариэль Чистосердечной в Серебряный павильон на Ристалище Серебряного турнира.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Победа Похитителей Солнца',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наконец-то Кель\'Делар восстановлен во славу всех Похитителей Солнца и величайшей расы син\'дорай!$B$BОтныне ты – $gгерой:героиня; Луносвета, $n.$B$BУвы, клинок почувствовал, что ты $gнеопытен:неопытна; в обращении с мечами, и потому не связал с тобой свою силу. Кто же станет его истинным хозяином? Я не знаю син\'дорай, достойного этой чести. Только Серебряный Авангард сможет нам помочь. Отправляйся к ристалищу Серебряного Турнира и передай этот клинок Вершительнице правосудия Мариэль Чистосердечной.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите восстановленный Кель\'Делар Вершительнице правосудия Мариэль Чистосердечной на ристалище Серебряного Турнира.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Освобождение великого меча из хватки злых сил – это благой знак, дающий нам надежду в темные времена. Теперь, когда на нашей стороне Кель\'Делар и союзники из Похитителей Солнца, у Короля-лича есть повод бояться за свою жизнь.$B$BАвангард владеет огромной оружейной. Если ты доверишь нам Кель\'Делар, мы подберем тебе взамен клинок, достойный героя.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Это правда, что тебе удалось восстановить Кель\'Делар?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Вершительнице правосудия Мариэль Чистосердечной в Серебряный павильон на Ристалище Серебряного турнира.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24799,'Победа Похитителей Солнца','Наконец-то Кель\'Делар восстановлен во славу всех Похитителей Солнца и величайшей расы син\'дорай!$B$BОтныне ты – $gгерой:героиня; Орды, $n.$B$BУвы, клинок почувствовал в тебе |3-6($c), $gнеопытного:неопытную; в обращении с мечом, и потому не связал с тобой свою силу. Кто же станет его истинным хозяином? Не стану скрывать разочарования – я надеялся, что им станет достойный син\'дорай. Только Серебряный Авангард сможет нам помочь. Отправляйся к ристалищу Серебряного Турнира и передай этот клинок Вершительнице правосудия Мариэль Чистосердечной.','Принесите восстановленный Кель\'Делар Вершительнице правосудия Мариэль Чистосердечной на ристалище Серебряного Турнира.','Вернитесь к Вершительнице правосудия Мариэль Чистосердечной в Серебряный павильон на Ристалище Серебряного турнира.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Победа Похитителей Солнца',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наконец-то Кель\'Делар восстановлен во славу всех Похитителей Солнца и величайшей расы син\'дорай!$B$BОтныне ты – $gгерой:героиня; Орды, $n.$B$BУвы, клинок почувствовал в тебе |3-6($c), $gнеопытного:неопытную; в обращении с мечом, и потому не связал с тобой свою силу. Кто же станет его истинным хозяином? Не стану скрывать разочарования – я надеялся, что им станет достойный син\'дорай. Только Серебряный Авангард сможет нам помочь. Отправляйся к ристалищу Серебряного Турнира и передай этот клинок Вершительнице правосудия Мариэль Чистосердечной.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите восстановленный Кель\'Делар Вершительнице правосудия Мариэль Чистосердечной на ристалище Серебряного Турнира.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Вершительнице правосудия Мариэль Чистосердечной в Серебряный павильон на Ристалище Серебряного турнира.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24800,'Победа Похитителей Солнца','Наконец-то Кель\'Делар восстановлен во славу всех Похитителей Солнца и величайшей расы син\'дорай!$B$BОтныне ты – $gгерой:героиня; Луносвета и всей Орды, $n.$B$BВерховный маг Этас Похититель Солнца, предводитель Похитителей Солнца, просил о встрече с тобой после того, как ты вернешься из Солнечного Колодца. Захвати с собой Кель\'Делар и отправляйся в Аметистовую цитадель Даларана как можно быстрее. Полагаю, Верховный маг желает лично тебя поздравить!','Принесите восстановленный Кель\'Делар Верховному магу Этасу Похитителю Солнца в Аметистовую цитадель Даларана.','Вернитесь к верховному магу Этасу Похитителю Солнца в Аметистовую цитадель, что в Даларане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Победа Похитителей Солнца',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наконец-то Кель\'Делар восстановлен во славу всех Похитителей Солнца и величайшей расы син\'дорай!$B$BОтныне ты – $gгерой:героиня; Луносвета и всей Орды, $n.$B$BВерховный маг Этас Похититель Солнца, предводитель Похитителей Солнца, просил о встрече с тобой после того, как ты вернешься из Солнечного Колодца. Захвати с собой Кель\'Делар и отправляйся в Аметистовую цитадель Даларана как можно быстрее. Полагаю, Верховный маг желает лично тебя поздравить!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите восстановленный Кель\'Делар Верховному магу Этасу Похитителю Солнца в Аметистовую цитадель Даларана.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному магу Этасу Похитителю Солнца в Аметистовую цитадель, что в Даларане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24801,'Победа Похитителей Солнца','Наконец-то Кель\'Делар восстановлен во славу всех Похитителей Солнца и величайшей расы син\'дорай! Это огромный шаг к победе над Королем-личом.$B$BВерховный маг Этас Похититель Солнца, предводитель Похитителей Солнца, просил о встрече с тобой после того, как ты вернешься из Солнечного Колодца. Захвати с собой Кель\'Делар и отправляйся в Аметистовую цитадель Даларана как можно быстрее. Полагаю, Верховный маг желает лично тебя поздравить!','Принесите восстановленный Кель\'Делар Верховному магу Этасу Похитителю Солнца в Аметистовую цитадель Даларана.','Вернитесь к верховному магу Этасу Похитителю Солнца в Аметистовую цитадель, что в Даларане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Победа Похитителей Солнца',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наконец-то Кель\'Делар восстановлен во славу всех Похитителей Солнца и величайшей расы син\'дорай! Это огромный шаг к победе над Королем-личом.$B$BВерховный маг Этас Похититель Солнца, предводитель Похитителей Солнца, просил о встрече с тобой после того, как ты вернешься из Солнечного Колодца. Захвати с собой Кель\'Делар и отправляйся в Аметистовую цитадель Даларана как можно быстрее. Полагаю, Верховный маг желает лично тебя поздравить!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите восстановленный Кель\'Делар Верховному магу Этасу Похитителю Солнца в Аметистовую цитадель Даларана.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному магу Этасу Похитителю Солнца в Аметистовую цитадель, что в Даларане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24803,'Калуакское рыбоборье','Не стой там просто! Дайте мне акулу, и я объявлю вас победителем!','Калуаки имеют давнюю традицию оттачивать наши навыки рыбалки, проверяя их каждую неделю.$B$BПервый учащийся, который поймает и принесет мне черную акулу, будет щедро вознагражден и будет известен как величайший рыбак севера... хотя бы на пару дней.$B$BЛюбимая еда черноплодной акулы - пигмеев. Попробуйте ловить черную подсказку везде, где вы обычно ловите рыбу.','Вернитесь к старейшине Чистому Потоку в Тернистую долину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Калуакское рыбоборье',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Не стой там просто! Дайте мне акулу, и я объявлю вас победителем!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Калуаки имеют давнюю традицию оттачивать наши навыки рыбалки, проверяя их каждую неделю.$B$BПервый учащийся, который поймает и принесет мне черную акулу, будет щедро вознагражден и будет известен как величайший рыбак севера... хотя бы на пару дней.$B$BЛюбимая еда черноплодной акулы - пигмеев. Попробуйте ловить черную подсказку везде, где вы обычно ловите рыбу.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старейшине Чистому Потоку в Тернистую долину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (24804,'Необычные ароматы','Не нравится мне эта Королевская химическая компания... Ребята из Хитрой Шестеренки давно уже присматривают за ними, и им бы не помешала помощь.$b$bИди в Штормград, если хочешь принять участие в этом деле. Расследование возглавляет инспектор Кромс Гвоздезуб, и ему пригодятся толковые помощники.','Отчитайтесь перед инспектором Кромсом Гвоздезубом в Штормграде.','Привет! У тебя найдется для меня время? Мне бы пригодилась твоя помощь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Необычные ароматы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не нравится мне эта Королевская химическая компания... Ребята из Хитрой Шестеренки давно уже присматривают за ними, и им бы не помешала помощь.$b$bИди в Штормград, если хочешь принять участие в этом деле. Расследование возглавляет инспектор Кромс Гвоздезуб, и ему пригодятся толковые помощники.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отчитайтесь перед инспектором Кромсом Гвоздезубом в Штормграде.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Привет! У тебя найдется для меня время? Мне бы пригодилась твоя помощь.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (24805,'Необычные ароматы','Не нравится мне эта Королевская химическая компания... Ребята из Хитрой Шестеренки давно уже присматривают за ними, и им бы не помешала помощь.$b$bИди в Оргриммар, если хочешь принять участие в этом деле. Расследование возглавляет детектив Крямс Гвоздезуб, и ему пригодятся толковые помощники.','Отчитайтесь перед детективом Крямсом Гвоздезубом в Оргриммаре.','Привет! У тебя найдется для меня время? Мне бы пригодилась твоя помощь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Необычные ароматы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не нравится мне эта Королевская химическая компания... Ребята из Хитрой Шестеренки давно уже присматривают за ними, и им бы не помешала помощь.$b$bИди в Оргриммар, если хочешь принять участие в этом деле. Расследование возглавляет детектив Крямс Гвоздезуб, и ему пригодятся толковые помощники.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отчитайтесь перед детективом Крямсом Гвоздезубом в Оргриммаре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Привет! У тебя найдется для меня время? Мне бы пригодилась твоя помощь.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24806,'Пусть тебе улыбнется удача – в другой раз!','Боюсь, у нас уже был победитель на сегодня, $Gмолодой:молодая; $N. Однако, если вы принесете акулу, я увижу, что она снова попала в воду, и у меня может быть кое-что для вас...','Боюсь, у нас уже был победитель на сегодня, $Gмолодой:молодая; $N. Однако, если вы принесете акулу, я увижу, что она снова попала в воду, и у меня может быть кое-что для вас...','Вернитесь к старейшине Чистому Потоку в Тернистую долину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пусть тебе улыбнется удача – в другой раз!',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Боюсь, у нас уже был победитель на сегодня, $Gмолодой:молодая; $N. Однако, если вы принесете акулу, я увижу, что она снова попала в воду, и у меня может быть кое-что для вас...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Боюсь, у нас уже был победитель на сегодня, $Gмолодой:молодая; $N. Однако, если вы принесете акулу, я увижу, что она снова попала в воду, и у меня может быть кое-что для вас...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старейшине Чистому Потоку в Тернистую долину.',`completedtext_loc8`);
