INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24812,'Пощады не будет','Наги принесли много горя нашему народу. Они не заслуживают пощады.$B$BОтправляйся в пещеру и убей всех наг, которых встретишь. Чем меньше их останется, тем меньше вероятность их дальнейшего нападения. Не сомневаюсь, что ты не пропустишь ни одной.','Убейте 12 наг Злобной Чешуи.','Вернитесь к Моракки в грот Злобной Чешуи на островах Эха.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пощады не будет',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наги принесли много горя нашему народу. Они не заслуживают пощады.$B$BОтправляйся в пещеру и убей всех наг, которых встретишь. Чем меньше их останется, тем меньше вероятность их дальнейшего нападения. Не сомневаюсь, что ты не пропустишь ни одной.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 наг Злобной Чешуи.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Моракки в грот Злобной Чешуи на островах Эха.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (24813,'Территориальный амулет','Это не просто контратака. Мы намерены уничтожить всех оставшихся наг и обезопасить себя от их возвращения.$B$BРазмести эти амулеты на каждом флаге Злобной Чешуи, которые найдешь в пещере. Это четко даст понять нагам, как мы относимся к их присутствию. Кроме того, магия, заключенная в амулетах, подорвет силы любого приблизившегося к ним представителя Злобной Чешуи. Пусть прочувствуют наше гостеприимство...','Разместите 8 территориальных амулетов на флагах Злобной Чешуи.','Теперь они не посмеют вернуться.','Вернитесь к Моракки в грот Злобной Чешуи на островах Эха.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Территориальный амулет',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это не просто контратака. Мы намерены уничтожить всех оставшихся наг и обезопасить себя от их возвращения.$B$BРазмести эти амулеты на каждом флаге Злобной Чешуи, которые найдешь в пещере. Это четко даст понять нагам, как мы относимся к их присутствию. Кроме того, магия, заключенная в амулетах, подорвет силы любого приблизившегося к ним представителя Злобной Чешуи. Пусть прочувствуют наше гостеприимство...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разместите 8 территориальных амулетов на флагах Злобной Чешуи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь они не посмеют вернуться.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Моракки в грот Злобной Чешуи на островах Эха.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (24814,'Древний враг','На острове объявилась морская ведьма. Мы столько ждали шанса отомстить ей, и сейчас эта честь выпала тебе.$B$BОтправляйся на северо-восток и встреться с Вол\'джином. Дай ему знать, когда будешь $gготов:готова; вступить в бой.','Поговорите с Вол\'джином в гроте Злобной Чешуи и помогите ему убить морскую ведьму Зар\'джиру.','В момент смерти морской ведьмы высвободилось огромное количество энергии, и теперь с ее помощью я смогу увидеть отдаленные земли.$B$BЯ собираюсь связаться с Траллом и хочу, чтобы ты увидел это сам. Может, это откроет тебе глаза на многое.','Поговорите с Вол\'джином в крепости Черного Копья на островах Эха.','Морская Ведьма, убившая отца Вол\'джина и прогнавшая троллей с родных островов, вернулась, и Вол\'джин наконец может ей отомстить.','Зар\'джира') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Древний враг',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На острове объявилась морская ведьма. Мы столько ждали шанса отомстить ей, и сейчас эта честь выпала тебе.$B$BОтправляйся на северо-восток и встреться с Вол\'джином. Дай ему знать, когда будешь $gготов:готова; вступить в бой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Вол\'джином в гроте Злобной Чешуи и помогите ему убить морскую ведьму Зар\'джиру.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','В момент смерти морской ведьмы высвободилось огромное количество энергии, и теперь с ее помощью я смогу увидеть отдаленные земли.$B$BЯ собираюсь связаться с Траллом и хочу, чтобы ты увидел это сам. Может, это откроет тебе глаза на многое.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Вол\'джином в крепости Черного Копья на островах Эха.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Морская Ведьма, убившая отца Вол\'джина и прогнавшая троллей с родных островов, вернулась, и Вол\'джин наконец может ей отомстить.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Зар\'джира',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (24815,'Выбери свой путь') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Выбери свой путь',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (24816,'Кто главный в пищевой цепи?','Ладно, ладно... согласен, идея с яйцами не шибко удачна. А вот как насчет акульего мясца?$B$BПравда, тут одно небольшое препятствие. Точнее, большое. Даже, я бы сказал, ОЧЕНЬ большое: Молот!$B$BА у меня, конечно же, есть блестящая идея. Плыви на запад в Зловещий пролив и добудь нам акульего мяса. Отдай его моей ассистентке, Грили. А я... я слишком важная фигура, чтобы заниматься подобной ерундой.','Добудьте 5 кусков акульего мяса.','Отлично – то, что нужно! Мы соединим эти куски акульего мяса с оставшимися деталями механоцыпа и сделаем механизм для погружения, который поможет нам избавиться от Молота!','Принесите куски акульего мяса ассистентке Грили к Городку-из-табакерки на Затерянных островах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кто главный в пищевой цепи?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ладно, ладно... согласен, идея с яйцами не шибко удачна. А вот как насчет акульего мясца?$B$BПравда, тут одно небольшое препятствие. Точнее, большое. Даже, я бы сказал, ОЧЕНЬ большое: Молот!$B$BА у меня, конечно же, есть блестящая идея. Плыви на запад в Зловещий пролив и добудь нам акульего мяса. Отдай его моей ассистентке, Грили. А я... я слишком важная фигура, чтобы заниматься подобной ерундой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 5 кусков акульего мяса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично – то, что нужно! Мы соединим эти куски акульего мяса с оставшимися деталями механоцыпа и сделаем механизм для погружения, который поможет нам избавиться от Молота!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите куски акульего мяса ассистентке Грили к Городку-из-табакерки на Затерянных островах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (24817,'Гоблин в акульей шкуре','Соединив то, что осталось от механоцыпа, с этими кусками акульего мяса, мы получили великолепный подводный боевой механизм: паровую мехакулу XD!$B$BМы с Хобартом хотим, чтобы ею $gуправлял:управляла; ты, $n. Отправляйся на запад, к воде, и активируй устройство управления паровой мехакулой XD.$b$bТебе нужно убить Молота, если мы хотим получить возможность разработать природные ресурсы Зловещего пролива в полной мере. Это на благо картеля!','Активируйте устройство управления паровой мехакулой XD и с ее помощью уничтожьте Молота.','Очень хорошо, мой мальчик! Городок-из-табакерки спасен и картель Трюмных Вод снова разбогатеет благодаря моему абсолютно невероятному интеллекту и поразительным знаниям инженерного дела!','Доложите о своем успехе Хобарту Дреку в Городке-из-табакерки на Затерянных островах.','Воспользуйся паровой мехакулой XD, чтобы уничтожить это чудовище!','Молот') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гоблин в акульей шкуре',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Соединив то, что осталось от механоцыпа, с этими кусками акульего мяса, мы получили великолепный подводный боевой механизм: паровую мехакулу XD!$B$BМы с Хобартом хотим, чтобы ею $gуправлял:управляла; ты, $n. Отправляйся на запад, к воде, и активируй устройство управления паровой мехакулой XD.$b$bТебе нужно убить Молота, если мы хотим получить возможность разработать природные ресурсы Зловещего пролива в полной мере. Это на благо картеля!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Активируйте устройство управления паровой мехакулой XD и с ее помощью уничтожьте Молота.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Очень хорошо, мой мальчик! Городок-из-табакерки спасен и картель Трюмных Вод снова разбогатеет благодаря моему абсолютно невероятному интеллекту и поразительным знаниям инженерного дела!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доложите о своем успехе Хобарту Дреку в Городке-из-табакерки на Затерянных островах.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Воспользуйся паровой мехакулой XD, чтобы уничтожить это чудовище!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Молот',`questgivertargetname_loc8`);
