INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24831,'Путь мудрости','Ты настоящий герой, сражающийся за правое дело, $n. Мало кто может сравниться с тобой на поле боя.$B$BВраги произносят твое имя испуганным шепотом, ибо знают, что с тобой нельзя не считаться.$B$BПрими этот скромный дар в благодарность за свершенные подвиги.','Ты желаешь и дальше идти путем мудрости?','Вернитесь к Орму Кающемуся.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путь мудрости',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты настоящий герой, сражающийся за правое дело, $n. Мало кто может сравниться с тобой на поле боя.$B$BВраги произносят твое имя испуганным шепотом, ибо знают, что с тобой нельзя не считаться.$B$BПрими этот скромный дар в благодарность за свершенные подвиги.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты желаешь и дальше идти путем мудрости?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Орму Кающемуся.',`completedtext_loc8`);
