INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (24848,'Фейерверки в "Позолоченной розе"','$gМалыш:Малышка;, это не просто дурно пахнет. В этом ящике хранились ракеты, начиненные каким-то химическим реактивом. Я не могу определить на месте, что это было, но и в лабораторию тебе бежать не придется.\r\n\r\nВместо этого мы подкупим парня, который изготовил эти штуки. Я узнал марку производителя – это Снивел Ржавстер.$B$BИз достоверных источников мне стало известно, что Ржавстер сейчас находится здесь, в Штормграде. Он снял комнату в "Позолоченной розе", и его часто видят в компании одной молодой дамы, Марион Саттон. Отправляйся в таверну и разузнай, что ей известно.','Поговорите с Марион Саттон в "Позолоченной розе", которая находится в Торговом квартале Штормграда.','Ты... А где же Ржавстер? Это он послал тебя? Слава небесам, он так задерживается, что я чуть было не впала в отчаяние...$B$B<Девушка начинает понимать, что у вас нет никакого послания от Ржавстера, и глаза ее наполняются слезами.>$B$BЭто так на него непохоже... но что еще мне остается думать?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Фейерверки в "Позолоченной розе"',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$gМалыш:Малышка;, это не просто дурно пахнет. В этом ящике хранились ракеты, начиненные каким-то химическим реактивом. Я не могу определить на месте, что это было, но и в лабораторию тебе бежать не придется.\r\n\r\nВместо этого мы подкупим парня, который изготовил эти штуки. Я узнал марку производителя – это Снивел Ржавстер.$B$BИз достоверных источников мне стало известно, что Ржавстер сейчас находится здесь, в Штормграде. Он снял комнату в "Позолоченной розе", и его часто видят в компании одной молодой дамы, Марион Саттон. Отправляйся в таверну и разузнай, что ей известно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Марион Саттон в "Позолоченной розе", которая находится в Торговом квартале Штормграда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты... А где же Ржавстер? Это он послал тебя? Слава небесам, он так задерживается, что я чуть было не впала в отчаяние...$B$B<Девушка начинает понимать, что у вас нет никакого послания от Ржавстера, и глаза ее наполняются слезами.>$B$BЭто так на него непохоже... но что еще мне остается думать?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24849,'По горячим следам','Это долгая история, $n. Я влюбилась в него с первого взгляда... понимаешь, было в этом гоблине что-то такое, особенное, что я глаз от него не могла отвести.$B$BМы провели вместе целую неделю, а потом Снивел сказал, что получил кучу денег, и потому берет меня с собой на отдых в Южных морях! Представляешь?$B$BВ общем, он велел мне собирать вещи, пока он улаживает кое-какие дела. Он собирался только зайти в банк, аукционный дом и парикмахерскую, но так и не вернулся! Я уже начинаю думать, что меня попросту обманули...','Поищите Снивела Ржавстера в счетной палате Штормграда, аукционном доме и парикмахерской.','Он говорил только о том, как смыться из города со всеми деньгами? Значит, он действительно меня бросил...$B$BАх, $N, как глупо было поверить его обещаниям, но я не могла удержаться. Он был таким обольстительным!','Кто ты?','Вернитесь к Марион Саттон в Штормград.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','По горячим следам',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это долгая история, $n. Я влюбилась в него с первого взгляда... понимаешь, было в этом гоблине что-то такое, особенное, что я глаз от него не могла отвести.$B$BМы провели вместе целую неделю, а потом Снивел сказал, что получил кучу денег, и потому берет меня с собой на отдых в Южных морях! Представляешь?$B$BВ общем, он велел мне собирать вещи, пока он улаживает кое-какие дела. Он собирался только зайти в банк, аукционный дом и парикмахерскую, но так и не вернулся! Я уже начинаю думать, что меня попросту обманули...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поищите Снивела Ржавстера в счетной палате Штормграда, аукционном доме и парикмахерской.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Он говорил только о том, как смыться из города со всеми деньгами? Значит, он действительно меня бросил...$B$BАх, $N, как глупо было поверить его обещаниям, но я не могла удержаться. Он был таким обольстительным!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Кто ты?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Марион Саттон в Штормград.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24851,'По горячим следам','Это долгая история, $n. Я влюбилась в него с первого взгляда... понимаешь, было в этом гоблине что-то такое, особенное, что я глаз от него не могла отвести.$B$BМы провели вместе целую неделю, а потом Снивел сказал, что получил кучу денег, и потому берет меня с собой на отдых в Южных морях! Представляешь?$B$BВ общем, он велел мне собирать вещи, пока он улаживает кое-какие дела. Он собирался только зайти в банк, аукционный дом и парикмахерскую, но так и не вернулся! Я уже начинаю думать, что меня попросту обманули...','Он говорил только о том, как смыться из города со всеми деньгами? Значит, он действительно меня бросил...$B$BАх, $N, как глупо было поверить его обещаниям, но я не могла удержаться. Он был таким обольстительным!','Кто ты?','Вернитесь к Роке в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','По горячим следам',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это долгая история, $n. Я влюбилась в него с первого взгляда... понимаешь, было в этом гоблине что-то такое, особенное, что я глаз от него не могла отвести.$B$BМы провели вместе целую неделю, а потом Снивел сказал, что получил кучу денег, и потому берет меня с собой на отдых в Южных морях! Представляешь?$B$BВ общем, он велел мне собирать вещи, пока он улаживает кое-какие дела. Он собирался только зайти в банк, аукционный дом и парикмахерскую, но так и не вернулся! Я уже начинаю думать, что меня попросту обманули...',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Он говорил только о том, как смыться из города со всеми деньгами? Значит, он действительно меня бросил...$B$BАх, $N, как глупо было поверить его обещаниям, но я не могла удержаться. Он был таким обольстительным!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Кто ты?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Роке в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (24852,'Откройте 4 клетки свинобразов.','Благодаря тебе наши люди свободны и могут защищать наш дом.','Вернитесь к Груллу Соколиному Ветру.') ON DUPLICATE KEY UPDATE `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Откройте 4 клетки свинобразов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Благодаря тебе наши люди свободны и могут защищать наш дом.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Груллу Соколиному Ветру.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (24854,'В поисках Когтя Бури','Зен\'Алири следует путем друида, |3-6($r). Есть надежда, что однажды Зен\'Алири присоединится к друидам-воронам и сможет как буревестник парить высоко в небе над кратером.$b$bНо мой наставник говорит: сейчас я остаюсь здесь и жду. Так ждет и Зен\'Алири.$b$bЯ знаю еще одного друида, кому твоя помощь может оказаться полезной. Его зовут Гарл Коготь Бури. Он изучает реагенты где-то к востоку отсюда. Может быть тебе пойти поговорить с ним?','Зен\'Алири правильно поступил, отправив тебя сюда. Я зашел в тупик в своих исследованиях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В поисках Когтя Бури',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Зен\'Алири следует путем друида, |3-6($r). Есть надежда, что однажды Зен\'Алири присоединится к друидам-воронам и сможет как буревестник парить высоко в небе над кратером.$b$bНо мой наставник говорит: сейчас я остаюсь здесь и жду. Так ждет и Зен\'Алири.$b$bЯ знаю еще одного друида, кому твоя помощь может оказаться полезной. Его зовут Гарл Коготь Бури. Он изучает реагенты где-то к востоку отсюда. Может быть тебе пойти поговорить с ним?',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Зен\'Алири правильно поступил, отправив тебя сюда. Я зашел в тупик в своих исследованиях.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24855,'Ненормальная растительность','Взгляни, как странно реагирует растительность на кровоцветы в Тревожных садах, что на севере. Деревья усыпаны цветами, и побегов стало гораздо больше. Из земли тянутся огромные странные цветы, которые никогда не росли в тех местах раньше.$b$bСама земля взывает к нам, |3-6($r). Кровоцветы нарушают баланс.$b$bМое последнее задание тебе будет таким: доберись до скопления взрослых кровоцветов и сократи их число.','Уничтожьте 11 взрослых кровоцветов. Подойдут любые их виды.','Вернитесь к Итису Лунному Стражу в Тревожные сады.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ненормальная растительность',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Взгляни, как странно реагирует растительность на кровоцветы в Тревожных садах, что на севере. Деревья усыпаны цветами, и побегов стало гораздо больше. Из земли тянутся огромные странные цветы, которые никогда не росли в тех местах раньше.$b$bСама земля взывает к нам, |3-6($r). Кровоцветы нарушают баланс.$b$bМое последнее задание тебе будет таким: доберись до скопления взрослых кровоцветов и сократи их число.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 11 взрослых кровоцветов. Подойдут любые их виды.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Итису Лунному Стражу в Тревожные сады.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (24856,'Неотвратимое вторжение!','Здесь твоя работа завершена, но ты, как я понимаю, без дела грустишь и чахнешь. Покой и скука – оно не для нас, верно?$B$BПомнишь Мегз Жестекрошшер, нашу старую подругу и по совместительству – торгового представителя? Она сейчас за холмами на юго-востоке, сразу за утесом Ящеров. Если пойдешь из города по дороге на восток, а потом на развилке свернешь на юг, ты ее не пропустишь.$B$BНасколько мне известно, у нее там возникли какие-то недоразумения со змеелюдьми из руин на берегу. Может быть, сходишь туда – разберешься?','Поговорите с Мегз Жестекрошшер у западного входа в руины Вайш\'элана на Затерянных островах.','У нас возникла небольшая проблема.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Неотвратимое вторжение!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Здесь твоя работа завершена, но ты, как я понимаю, без дела грустишь и чахнешь. Покой и скука – оно не для нас, верно?$B$BПомнишь Мегз Жестекрошшер, нашу старую подругу и по совместительству – торгового представителя? Она сейчас за холмами на юго-востоке, сразу за утесом Ящеров. Если пойдешь из города по дороге на восток, а потом на развилке свернешь на юг, ты ее не пропустишь.$B$BНасколько мне известно, у нее там возникли какие-то недоразумения со змеелюдьми из руин на берегу. Может быть, сходишь туда – разберешься?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Мегз Жестекрошшер у западного входа в руины Вайш\'элана на Затерянных островах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','У нас возникла небольшая проблема.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24857,'Нападение на Лагерь Нараче','Внимательно изучив карту, вы понимаете, что перед вами не что иное, как план нападения племени Дыбогривов на Лагерь Нараче. $b$bВождь Соколиный Ветер непременно должен об этом узнать!','Отнесите план нападения племени Дыбогривов вождю Соколиному Ветру в Лагерь Нараче.','Это вызывает тревогу! Но с этой информацией мы можем призвать наших собратьев из Деревни Кровавого Копыта, чтобы они помогли предотвратить атаку. Ты $Gспас:спасла; жизни многим $R, $N.','У тебя озабоченный вид, $N. Какие новости ты $Gпринес:принесла;?','Вернитесь к вождю Соколиному Ветру в Лагерь Нараче, что в Мулгоре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нападение на Лагерь Нараче',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Внимательно изучив карту, вы понимаете, что перед вами не что иное, как план нападения племени Дыбогривов на Лагерь Нараче. $b$bВождь Соколиный Ветер непременно должен об этом узнать!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите план нападения племени Дыбогривов вождю Соколиному Ветру в Лагерь Нараче.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это вызывает тревогу! Но с этой информацией мы можем призвать наших собратьев из Деревни Кровавого Копыта, чтобы они помогли предотвратить атаку. Ты $Gспас:спасла; жизни многим $R, $N.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У тебя озабоченный вид, $N. Какие новости ты $Gпринес:принесла;?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к вождю Соколиному Ветру в Лагерь Нараче, что в Мулгоре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (24858,'Представитель картеля Трюмных Вод','Похоже, наги в руинах собираются напасть на наш Городок-из-табакерки. И доказательство тому – эти трупы разведчиков.$B$BНе знаю как ты, а я не собираюсь сидеть сложа руки. Давай нанесем превентивный удар!$B$BМожешь заложить основы наших прибрежных владений, заменив их флаги нашими? Ведь этой земле цены нет!','Уничтожьте 10 знамен наг и замените их на знамена картеля Трюмных Вод.','Как жаль, что мне не удалось увидеть их чешуйчатые морды, когда они заметили, что знамена заменили.$B$BС другой стороны, я совсем не горю желанием видеть их оскаленные пасти.','Вернитесь к Мегз Жестекрошшер на Затерянные острова в руины Вайш\'элана.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Представитель картеля Трюмных Вод',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Похоже, наги в руинах собираются напасть на наш Городок-из-табакерки. И доказательство тому – эти трупы разведчиков.$B$BНе знаю как ты, а я не собираюсь сидеть сложа руки. Давай нанесем превентивный удар!$B$BМожешь заложить основы наших прибрежных владений, заменив их флаги нашими? Ведь этой земле цены нет!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 10 знамен наг и замените их на знамена картеля Трюмных Вод.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Как жаль, что мне не удалось увидеть их чешуйчатые морды, когда они заметили, что знамена заменили.$B$BС другой стороны, я совсем не горю желанием видеть их оскаленные пасти.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мегз Жестекрошшер на Затерянные острова в руины Вайш\'элана.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24859,'Шкуры наг','По углам то и дело шепчутся о материале таком прочном и изящном, что гоблины, обладающие утонченным вкусом, готовы выложить за него кучу бабок.$B$BДа, конечно, я говорю о шкуре наг!$B$B<Бретт оглядывается по сторонам, чтобы убедиться в том, что никто не подслушивает.>$B$BЯ знаю, что ты идешь туда и что тебе придется сражаться с ними. Слушай, им же все равно не понадобятся их шкуры! Они же будут уже мертвы!','Добудьте 5 целых шкур наг.','Мы будем купаться в деньгах, точно тебе говорю! Ну, конечно, если сумеем выбраться с этого острова.','Ну? Сколько достанется мне? Думаю, вполне справедливо будет разделить в пропорции 95 к 5.','Вернитесь к Бретту "Сдачи нет" Маквиду на Затерянные острова в руины Вайш\'элана.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Шкуры наг',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','По углам то и дело шепчутся о материале таком прочном и изящном, что гоблины, обладающие утонченным вкусом, готовы выложить за него кучу бабок.$B$BДа, конечно, я говорю о шкуре наг!$B$B<Бретт оглядывается по сторонам, чтобы убедиться в том, что никто не подслушивает.>$B$BЯ знаю, что ты идешь туда и что тебе придется сражаться с ними. Слушай, им же все равно не понадобятся их шкуры! Они же будут уже мертвы!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 5 целых шкур наг.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мы будем купаться в деньгах, точно тебе говорю! Ну, конечно, если сумеем выбраться с этого острова.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну? Сколько достанется мне? Думаю, вполне справедливо будет разделить в пропорции 95 к 5.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бретту "Сдачи нет" Маквиду на Затерянные острова в руины Вайш\'элана.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24860,'Profitable Preservation','You know, the naga are the mutated and prettier versions of the kaldorei, better known as the night elves. Don\'t ask me... it\'s a long story.$B$BSuffice to say that I\'m sure you could \'procure\' an artifact or two while you\'re down there in the ruins. If you know what I mean?$B$BWe have to preserve them in the homes of wealthy collectors everywhere! Right?','Collect 12 Kaldorei Artifacts.','Return to Ace at the Ruins of Vashj\'elan on the Lost Isles.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Profitable Preservation',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','You know, the naga are the mutated and prettier versions of the kaldorei, better known as the night elves. Don\'t ask me... it\'s a long story.$B$BSuffice to say that I\'m sure you could \'procure\' an artifact or two while you\'re down there in the ruins. If you know what I mean?$B$BWe have to preserve them in the homes of wealthy collectors everywhere! Right?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Collect 12 Kaldorei Artifacts.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Return to Ace at the Ruins of Vashj\'elan on the Lost Isles.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (24861,'Погребальный обряд','Лагерю больше ничто не угрожает, свинобразов мы с твоей помощью прогнали, за что прими мою самую искреннюю благодарность. Спасибо за все, что ты $gсделал:сделала; для моей матери, сына – всех нас.$B$BА сейчас мы должны проводить Великую Мать Соколиный Ветер в последний путь. Положи жертвенное подношение к ее ногам, $n, а потом мы простимся.','Принесите церемониальную жертву на могиле Великой Матери Соколиный Ветер.','Во всем должно быть равновесие. Дух Великой Матери Соколиный Ветер отправляется в последний путь, а твой – только начинается.','Вернитесь к Вождю Соколиному Ветру.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Погребальный обряд',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Лагерю больше ничто не угрожает, свинобразов мы с твоей помощью прогнали, за что прими мою самую искреннюю благодарность. Спасибо за все, что ты $gсделал:сделала; для моей матери, сына – всех нас.$B$BА сейчас мы должны проводить Великую Мать Соколиный Ветер в последний путь. Положи жертвенное подношение к ее ногам, $n, а потом мы простимся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите церемониальную жертву на могиле Великой Матери Соколиный Ветер.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Во всем должно быть равновесие. Дух Великой Матери Соколиный Ветер отправляется в последний путь, а твой – только начинается.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Вождю Соколиному Ветру.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (24862,'Тяжелые испытания','Посмотри вокруг, |3-6($c). Нам не удалось избавиться от слежки – эта долина испещрена тайными тропами, знакомыми лишь Орде. Они организуют засады там, где это, казалось бы, невозможно, и грабят наши караваны. А затем просто растворяются среди холмов!$b$BЯ хочу, чтобы ты как можно быстрее $gдобрался:добралась; до Заставы Чести и $gсообщил:сообщила; им о том, что дороги все еще небезопасны. Поговори со снабженцем Маттингли, она находится у ворот.$b$bИ убей по пути тех головорезов, что встретятся!','Убейте 8 разведчиков Охотничьего холма.','Они устроили засаду и вокруг дорог в Когтистые горы тоже? Нам тут просто не передохнуть. Ну ладно, так откуда они появляются?','Поговорите с Джанис Маттингли на Заставе Чести в Южных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тяжелые испытания',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Посмотри вокруг, |3-6($c). Нам не удалось избавиться от слежки – эта долина испещрена тайными тропами, знакомыми лишь Орде. Они организуют засады там, где это, казалось бы, невозможно, и грабят наши караваны. А затем просто растворяются среди холмов!$b$BЯ хочу, чтобы ты как можно быстрее $gдобрался:добралась; до Заставы Чести и $gсообщил:сообщила; им о том, что дороги все еще небезопасны. Поговори со снабженцем Маттингли, она находится у ворот.$b$bИ убей по пути тех головорезов, что встретятся!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 разведчиков Охотничьего холма.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Они устроили засаду и вокруг дорог в Когтистые горы тоже? Нам тут просто не передохнуть. Ну ладно, так откуда они появляются?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Джанис Маттингли на Заставе Чести в Южных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24863,'Прорвать осаду','Соберите 10 ящиков с припасами Каменного Когтя в руинах к западу от Заставы Чести.','Доставьте ящики Джанис Маттингли на Заставу Чести в Южных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прорвать осаду',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 ящиков с припасами Каменного Когтя в руинах к западу от Заставы Чести.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доставьте ящики Джанис Маттингли на Заставу Чести в Южных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (24864,'Неотразимый надувной пони','У меня есть план, и только ты достаточно $Gбезумен:безумна;, чтобы хотя бы попытаться его осуществить!$B$BВот, возьми этого неотразимого надувного пони, отнеси его в лягушатник Вайш\'элана и надуй. Затем садись на него верхом и плыви к молодняку наг. Наверняка ты сможешь приманить маленьких наг.$B$BПриведи их сюда, и тогда мы перейдем к следующему пункту нашего плана.','Приманите 12 маленьких наг с помощью неотразимого надувного пони.','О, какие они милые! Эх, набить бы из них чучела да продать за газильон деревянных!','Вернитесь к Мегз Жестекрошшер на Затерянные острова в руины Вайш\'элана.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Неотразимый надувной пони',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У меня есть план, и только ты достаточно $Gбезумен:безумна;, чтобы хотя бы попытаться его осуществить!$B$BВот, возьми этого неотразимого надувного пони, отнеси его в лягушатник Вайш\'элана и надуй. Затем садись на него верхом и плыви к молодняку наг. Наверняка ты сможешь приманить маленьких наг.$B$BПриведи их сюда, и тогда мы перейдем к следующему пункту нашего плана.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Приманите 12 маленьких наг с помощью неотразимого надувного пони.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, какие они милые! Эх, набить бы из них чучела да продать за газильон деревянных!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мегз Жестекрошшер на Затерянные острова в руины Вайш\'элана.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24865,'Это еще годится в пищу?','То, что вы нашли, больше всего похоже на ящик с провизией, оставленный после бегства из лагеря. На обратной стороне имеется штамп: "СОБСТВЕННОСТЬ ЭКСПЕДИЦИИ МАРШАЛЛА".$B$BВозможно, вам удастся найти того, кому это пригодится?','Верните ящик с провизией Виллидену Маршаллу на заставу Маршалла.','Верните ящик с провизией Виллидену Маршаллу на заставу Маршалла.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Это еще годится в пищу?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','То, что вы нашли, больше всего похоже на ящик с провизией, оставленный после бегства из лагеря. На обратной стороне имеется штамп: "СОБСТВЕННОСТЬ ЭКСПЕДИЦИИ МАРШАЛЛА".$B$BВозможно, вам удастся найти того, кому это пригодится?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните ящик с провизией Виллидену Маршаллу на заставу Маршалла.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Верните ящик с провизией Виллидену Маршаллу на заставу Маршалла.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (24866,'Покинутый лагерь исследователей','То, что вы нашли, больше всего похоже на деталь исследовательского оборудования, брошенного во время бегства из лагеря. На устройстве нацарапана надпись: "СОБСТВЕННОСТЬ ИКСПИДИТСИИ МАРШАЛЛА".$B$BВозможно, вам удастся найти того, кому это пригодится?','Верните исследовательское оборудование Холании Маршалл на заставу Маршалла.','Черт возьми... Это же старый переносной динамометр Шиззла! Где ты достала его?$B$BНадо же, до сих пор работает, а сколько лет прошло. Нужно отдать его Шиззлу как можно быстрее.','Верните исследовательское оборудование Холании Маршалл на заставу Маршалла.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Покинутый лагерь исследователей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','То, что вы нашли, больше всего похоже на деталь исследовательского оборудования, брошенного во время бегства из лагеря. На устройстве нацарапана надпись: "СОБСТВЕННОСТЬ ИКСПИДИТСИИ МАРШАЛЛА".$B$BВозможно, вам удастся найти того, кому это пригодится?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните исследовательское оборудование Холании Маршалл на заставу Маршалла.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Черт возьми... Это же старый переносной динамометр Шиззла! Где ты достала его?$B$BНадо же, до сих пор работает, а сколько лет прошло. Нужно отдать его Шиззлу как можно быстрее.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Верните исследовательское оборудование Холании Маршалл на заставу Маршалла.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24867,'[NOT USED] Lumberjack Slam Placeholder','Placeholder, $n! This is a placeholder lumberjack quest. You? Grab that lumberjack. And do something ... placeholder-y with him.$B$BYou heard me.','Do something cool with the lumberjack.','Вернитесь к Джанис Маттингли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[NOT USED] Lumberjack Slam Placeholder',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Placeholder, $n! This is a placeholder lumberjack quest. You? Grab that lumberjack. And do something ... placeholder-y with him.$B$BYou heard me.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Do something cool with the lumberjack.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джанис Маттингли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (24868,'Сдавайся, не то хуже будет!','$n, тебе с Тузом нужно захватить маленьких наг и превратить их в средство убеждения. Главарь наг должен понять, что пора сдаваться.$B$BАс знает, куда идти – в южную часть развалин... следуй за ним.','Разберитесь с главарем наг в руинах Вайш\'элана.','Безликий из глубин? Это еще что такое? По имени ВООБЩЕ на нагу не похоже!$B$BНу да ладно, ты же убил ЭТО, чем бы оно ни было. И все. У нас есть дела поважнее...','Вернитесь к Мегз Жестекрошшер в руины Вайш\'элана на Затерянных островах.','Это их лидер?! Разберись с ним!','Безликий из глубин') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сдавайся, не то хуже будет!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, тебе с Тузом нужно захватить маленьких наг и превратить их в средство убеждения. Главарь наг должен понять, что пора сдаваться.$B$BАс знает, куда идти – в южную часть развалин... следуй за ним.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разберитесь с главарем наг в руинах Вайш\'элана.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Безликий из глубин? Это еще что такое? По имени ВООБЩЕ на нагу не похоже!$B$BНу да ладно, ты же убил ЭТО, чем бы оно ни было. И все. У нас есть дела поважнее...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мегз Жестекрошшер в руины Вайш\'элана на Затерянных островах.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Это их лидер?! Разберись с ним!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Безликий из глубин',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24869,'Перевербовка','Мы планировали заслать агента в Культ Проклятых, чтобы получить возможность следить за действиями Короля-лича напрямую, но мы... недооценили силу Артаса и его приближенной, Леди Смертный Шепот.$B$BВ итоге, один из наших людей, Дарнаван, был обращен на их сторону.$B$BЕсли ты собираешься расчистить путь в молельню, прошу тебя, поищи Дарнавана. Если тебе удастся вернуть его живым, мы постараемся устранить последствия промывки мозгов.','Убейте Леди Смертный Шепот, сохранив жизнь Дарнавану.','Вернитесь к разведчику Минчару.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Перевербовка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы планировали заслать агента в Культ Проклятых, чтобы получить возможность следить за действиями Короля-лича напрямую, но мы... недооценили силу Артаса и его приближенной, Леди Смертный Шепот.$B$BВ итоге, один из наших людей, Дарнаван, был обращен на их сторону.$B$BЕсли ты собираешься расчистить путь в молельню, прошу тебя, поищи Дарнавана. Если тебе удастся вернуть его живым, мы постараемся устранить последствия промывки мозгов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Леди Смертный Шепот, сохранив жизнь Дарнавану.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к разведчику Минчару.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24870,'Оборона Черепного вала','Это место – какой-то сумасшедший дом! Мало того, что нам приходится воевать с Плетью, так теперь еще эти псы из Альянса кусают нас за бока. Сколько можно воевать на два фронта!$B$BМы прибыли сюда, чтобы обеспечить безопасную высадку наших кораблей, но какое-то гигантское чудовище на другой стороне вала швыряет обломки во все, что движется, и не дает приблизиться малым судам.$B$BСкажу тебе честно – нам с этим громилой не справиться. Одна надежда на тебя и твоих спутников.','Убейте гниющего ледяного великана.','Вернитесь к кор\'кронскому лейтенанту.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оборона Черепного вала',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это место – какой-то сумасшедший дом! Мало того, что нам приходится воевать с Плетью, так теперь еще эти псы из Альянса кусают нас за бока. Сколько можно воевать на два фронта!$B$BМы прибыли сюда, чтобы обеспечить безопасную высадку наших кораблей, но какое-то гигантское чудовище на другой стороне вала швыряет обломки во все, что движется, и не дает приблизиться малым судам.$B$BСкажу тебе честно – нам с этим громилой не справиться. Одна надежда на тебя и твоих спутников.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте гниющего ледяного великана.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к кор\'кронскому лейтенанту.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (24871,'Оборона Черепного вала','Это место – какой-то сумасшедший дом! Мало того, что нам приходится воевать с Плетью, так теперь еще эти псы из Орды кусают нас за бока. Сколько можно воевать на два фронта!$B$BМы прибыли сюда, чтобы обеспечить безопасную высадку наших кораблей, но какое-то гигантское чудовище на другой стороне вала швыряет обломки во все, что движется, и не дает приблизиться малым судам.$B$BСкажу тебе честно – нам с этим громилой не справиться. Одна надежда на тебя и твоих спутников.','Убейте гниющего ледяного великана.','Гигант мертв? Слава Свету!$B$BПуть вперед скоро станет ясен. Возьми это в знак нашей благодарности и потом мы вместе выпьем за праздник, когда Ледяной Трон будет рассыпан в пыль!','Вернитесь к лейтенанту "Усмирителя небес".') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оборона Черепного вала',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это место – какой-то сумасшедший дом! Мало того, что нам приходится воевать с Плетью, так теперь еще эти псы из Орды кусают нас за бока. Сколько можно воевать на два фронта!$B$BМы прибыли сюда, чтобы обеспечить безопасную высадку наших кораблей, но какое-то гигантское чудовище на другой стороне вала швыряет обломки во все, что движется, и не дает приблизиться малым судам.$B$BСкажу тебе честно – нам с этим громилой не справиться. Одна надежда на тебя и твоих спутников.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте гниющего ледяного великана.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Гигант мертв? Слава Свету!$B$BПуть вперед скоро станет ясен. Возьми это в знак нашей благодарности и потом мы вместе выпьем за праздник, когда Ледяной Трон будет рассыпан в пыль!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лейтенанту "Усмирителя небес".',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24872,'Отдых для измученной души','Я прошу тебя и твоих спутников взять эти Кристаллы жизни. В них заключена великая сила Святилища драконов из Драконьего Погоста. Знай же, что только с их помощью мне так долго удавалось оградить это место от влияния темной магии. $B$BБрось вызов Синдрагосе, и когда силы ее истощатся в бою, четыре твоих спутника смогут активировать кристаллы, чтобы вытянуть покоящуюся внутри нее сущность. Если затем ты одержишь победу, ты сможешь вернуть ее душу в Святилище драконов.','Воспользуйтесь кристаллами жизни, чтобы сохранить душу Синдрагосы.','*Калесгос вздыхает.*$B$Столько страданий, столько бессмысленных разрушений. Это было не самое спокойное время для моих братьев и сестер, но спасибо за ваши старания, храбрые искатели приключений, эта темная, но все же благородная душа наконец-то найдет покой. Отдохни, Синдрагоса. Ты дома...','Что это у тебя в руках, $Gсмертный:смертная;?','Верните душу Синдрагосы Калесгосу в Храм Драконьего Покоя в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отдых для измученной души',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я прошу тебя и твоих спутников взять эти Кристаллы жизни. В них заключена великая сила Святилища драконов из Драконьего Погоста. Знай же, что только с их помощью мне так долго удавалось оградить это место от влияния темной магии. $B$BБрось вызов Синдрагосе, и когда силы ее истощатся в бою, четыре твоих спутника смогут активировать кристаллы, чтобы вытянуть покоящуюся внутри нее сущность. Если затем ты одержишь победу, ты сможешь вернуть ее душу в Святилище драконов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь кристаллами жизни, чтобы сохранить душу Синдрагосы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','*Калесгос вздыхает.*$B$Столько страданий, столько бессмысленных разрушений. Это было не самое спокойное время для моих братьев и сестер, но спасибо за ваши старания, храбрые искатели приключений, эта темная, но все же благородная душа наконец-то найдет покой. Отдохни, Синдрагоса. Ты дома...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что это у тебя в руках, $Gсмертный:смертная;?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Верните душу Синдрагосы Калесгосу в Храм Драконьего Покоя в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (24873,'Болезненная задача','Профессор Мерзоцид прячется в своей поганой лаборатории, ставит опыты и выводит все более и более смертоносные штаммы порчи, которыми он планирует заразить всех нас. Если только мы сможем получить чистые образцы этих токсинов, наши исследователи немедленно приступят к изготовлению противоядия, которое спасет множество жизней.$B$BНо есть одна проблема – для того, чтобы получить требуемый образец, надо заразить живое существо двумя активными штаммами. Но если вдруг тебе... не посчастливится... стать носителем этой заразы, немедленно возвращайся сюда, чтобы мы могли поставить на тебе опыты.','Если вы заразитесь оранжевой и зеленой порчей, вернитесь к алхимику Адрианне.','Наконец-то у нас есть живые образцы для изучения! В этот день ты $Gпомог:помогла; спасти бесчисленное количество жизней, $N.$B$BПожалуйста, прими это в знак благодарности за это великое дело.','Заразитесь двумя видами порчи.','Вернитесь к Адрианне в Цитадель Ледяной Короны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Болезненная задача',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Профессор Мерзоцид прячется в своей поганой лаборатории, ставит опыты и выводит все более и более смертоносные штаммы порчи, которыми он планирует заразить всех нас. Если только мы сможем получить чистые образцы этих токсинов, наши исследователи немедленно приступят к изготовлению противоядия, которое спасет множество жизней.$B$BНо есть одна проблема – для того, чтобы получить требуемый образец, надо заразить живое существо двумя активными штаммами. Но если вдруг тебе... не посчастливится... стать носителем этой заразы, немедленно возвращайся сюда, чтобы мы могли поставить на тебе опыты.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Если вы заразитесь оранжевой и зеленой порчей, вернитесь к алхимику Адрианне.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Наконец-то у нас есть живые образцы для изучения! В этот день ты $Gпомог:помогла; спасти бесчисленное количество жизней, $N.$B$BПожалуйста, прими это в знак благодарности за это великое дело.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Заразитесь двумя видами порчи.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Адрианне в Цитадель Ледяной Короны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24874,'Каждая капля крови...','Эти проклятые кровопийцы Плети, что именуют себя Сан\'лейн... у меня от них мурашки по коже. За ними следил один из наших лучших агентов, но сегодня утром с ним случилась беда – он попал в плен. Теперь его допрашивает сама Королева, и его крики эхом разносятся по Багровым залам. Пожалуйста, спаси его, пока еще не поздно!','Спасите разведчика Минчара прежде, чем его казнят.','Поговорите с Минчаром.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Каждая капля крови...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти проклятые кровопийцы Плети, что именуют себя Сан\'лейн... у меня от них мурашки по коже. За ними следил один из наших лучших агентов, но сегодня утром с ним случилась беда – он попал в плен. Теперь его допрашивает сама Королева, и его крики эхом разносятся по Багровым залам. Пожалуйста, спаси его, пока еще не поздно!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Спасите разведчика Минчара прежде, чем его казнят.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Минчаром.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24875,'Перевербовка','Мы планировали заслать агента в Культ Проклятых, чтобы получить возможность следить за действиями Короля-лича напрямую, но мы... недооценили силу Артаса и его приближенной, Леди Смертный Шепот.$B$BВ итоге, один из наших людей, Дарнаван, был обращен на их сторону.$B$BЕсли ты собираешься расчистить путь в молельню, прошу тебя, поищи Дарнавана. Если тебе удастся вернуть его живым, мы постараемся устранить последствия промывки мозгов.','Убейте Леди Смертный Шепот, сохранив жизнь Дарнавану.','Вернитесь к разведчику Минчару.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Перевербовка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы планировали заслать агента в Культ Проклятых, чтобы получить возможность следить за действиями Короля-лича напрямую, но мы... недооценили силу Артаса и его приближенной, Леди Смертный Шепот.$B$BВ итоге, один из наших людей, Дарнаван, был обращен на их сторону.$B$BЕсли ты собираешься расчистить путь в молельню, прошу тебя, поищи Дарнавана. Если тебе удастся вернуть его живым, мы постараемся устранить последствия промывки мозгов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Леди Смертный Шепот, сохранив жизнь Дарнавану.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к разведчику Минчару.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24876,'Оборона Черепного вала','Это место – какой-то сумасшедший дом! Мало того, что нам приходится воевать с Плетью, так теперь еще эти псы из Орды кусают нас за бока. Сколько можно воевать на два фронта!$B$BМы прибыли сюда, чтобы обеспечить безопасную высадку наших кораблей, но какое-то гигантское чудовище на другой стороне вала швыряет обломки во все, что движется, и не дает приблизиться малым судам.$B$BСкажу тебе честно – нам с этим громилой не справиться. Одна надежда на тебя и твоих спутников.','Убейте гниющего ледяного великана.','Вернитесь к лейтенанту "Усмирителя небес".') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оборона Черепного вала',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это место – какой-то сумасшедший дом! Мало того, что нам приходится воевать с Плетью, так теперь еще эти псы из Орды кусают нас за бока. Сколько можно воевать на два фронта!$B$BМы прибыли сюда, чтобы обеспечить безопасную высадку наших кораблей, но какое-то гигантское чудовище на другой стороне вала швыряет обломки во все, что движется, и не дает приблизиться малым судам.$B$BСкажу тебе честно – нам с этим громилой не справиться. Одна надежда на тебя и твоих спутников.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте гниющего ледяного великана.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лейтенанту "Усмирителя небес".',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24877,'Оборона Черепного вала','Это место – какой-то сумасшедший дом! Мало того, что нам приходится воевать с Плетью, так теперь еще эти псы из Альянса кусают нас за бока. Сколько можно воевать на два фронта!$B$BМы прибыли сюда, чтобы обеспечить безопасную высадку наших кораблей, но какое-то гигантское чудовище на другой стороне вала швыряет обломки во все, что движется, и не дает приблизиться малым судам.$B$BСкажу тебе честно – нам с этим громилой не справиться. Одна надежда на тебя и твоих спутников.','Убейте гниющего ледяного великана.','Вернитесь к кор\'кронскому лейтенанту.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оборона Черепного вала',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это место – какой-то сумасшедший дом! Мало того, что нам приходится воевать с Плетью, так теперь еще эти псы из Альянса кусают нас за бока. Сколько можно воевать на два фронта!$B$BМы прибыли сюда, чтобы обеспечить безопасную высадку наших кораблей, но какое-то гигантское чудовище на другой стороне вала швыряет обломки во все, что движется, и не дает приблизиться малым судам.$B$BСкажу тебе честно – нам с этим громилой не справиться. Одна надежда на тебя и твоих спутников.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте гниющего ледяного великана.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к кор\'кронскому лейтенанту.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (24878,'Болезненная задача','Профессор Мерзоцид прячется в своей поганой лаборатории, ставит опыты и выводит все более и более смертоносные штаммы порчи, которыми он планирует заразить всех нас. Если только мы сможем получить чистые образцы этих токсинов, наши исследователи немедленно приступят к изготовлению противоядия, которое спасет множество жизней.$B$BНо есть одна проблема – для того, чтобы получить требуемый образец, надо заразить живое существо двумя активными штаммами. Но если вдруг тебе... не посчастливится... стать носителем этой заразы, немедленно возвращайся сюда, чтобы мы могли поставить на тебе опыты.','Если вы заразитесь оранжевой и зеленой порчей, вернитесь к алхимику Адрианне.','Заразитесь двумя видами порчи.','Вернитесь к Адрианне в Цитадель Ледяной Короны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Болезненная задача',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Профессор Мерзоцид прячется в своей поганой лаборатории, ставит опыты и выводит все более и более смертоносные штаммы порчи, которыми он планирует заразить всех нас. Если только мы сможем получить чистые образцы этих токсинов, наши исследователи немедленно приступят к изготовлению противоядия, которое спасет множество жизней.$B$BНо есть одна проблема – для того, чтобы получить требуемый образец, надо заразить живое существо двумя активными штаммами. Но если вдруг тебе... не посчастливится... стать носителем этой заразы, немедленно возвращайся сюда, чтобы мы могли поставить на тебе опыты.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Если вы заразитесь оранжевой и зеленой порчей, вернитесь к алхимику Адрианне.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Заразитесь двумя видами порчи.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Адрианне в Цитадель Ледяной Короны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (24879,'Каждая капля крови...','Эти проклятые кровопийцы Плети, что именуют себя Сан\'лейн... у меня от них мурашки по коже. За ними следил один из наших лучших агентов, но сегодня утром с ним случилась беда – он попал в плен. Теперь его допрашивает сама Королева, и его крики эхом разносятся по Багровым залам. Пожалуйста, спаси его, пока еще не поздно!','Спасите разведчика Минчара прежде, чем его казнят.','Фух, я уж думал, что я покойник! Я услышал ритуал возрождения, который проводили в этих залах и подобрался поближе, чтобы рассмотреть, но один из этих проклятых вампиров учуял меня. Они подвесили меня здесь, вытягивая жизненную силу в надежде, что я сломаюсь и выдам планы наступления. Как будто бы я знал что планирует Тирион! Пожалуйста, примите эти трофеи в качестве небольшой благодарности за спасение моей жизни.','Поговорите с Минчаром.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Каждая капля крови...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти проклятые кровопийцы Плети, что именуют себя Сан\'лейн... у меня от них мурашки по коже. За ними следил один из наших лучших агентов, но сегодня утром с ним случилась беда – он попал в плен. Теперь его допрашивает сама Королева, и его крики эхом разносятся по Багровым залам. Пожалуйста, спаси его, пока еще не поздно!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Спасите разведчика Минчара прежде, чем его казнят.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Фух, я уж думал, что я покойник! Я услышал ритуал возрождения, который проводили в этих залах и подобрался поближе, чтобы рассмотреть, но один из этих проклятых вампиров учуял меня. Они подвесили меня здесь, вытягивая жизненную силу в надежде, что я сломаюсь и выдам планы наступления. Как будто бы я знал что планирует Тирион! Пожалуйста, примите эти трофеи в качестве небольшой благодарности за спасение моей жизни.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Минчаром.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24880,'Отдых для измученной души','Я прошу тебя и твоих спутников взять эти Кристаллы жизни. В них заключена великая сила Святилища драконов из Драконьего Погоста. Знай же, что только с их помощью мне так долго удавалось оградить это место от влияния темной магии. $B$BБрось вызов Синдрагосе, и когда силы ее истощатся в бою, четыре твоих спутника смогут активировать кристаллы, чтобы вытянуть покоящуюся внутри нее сущность. Если затем ты одержишь победу, ты сможешь вернуть ее душу в Святилище драконов.','Воспользуйтесь кристаллами жизни, чтобы сохранить душу Синдрагосы.','Верните душу Синдрагосы Калесгосу в Храм Драконьего Покоя в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отдых для измученной души',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я прошу тебя и твоих спутников взять эти Кристаллы жизни. В них заключена великая сила Святилища драконов из Драконьего Погоста. Знай же, что только с их помощью мне так долго удавалось оградить это место от влияния темной магии. $B$BБрось вызов Синдрагосе, и когда силы ее истощатся в бою, четыре твоих спутника смогут активировать кристаллы, чтобы вытянуть покоящуюся внутри нее сущность. Если затем ты одержишь победу, ты сможешь вернуть ее душу в Святилище драконов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь кристаллами жизни, чтобы сохранить душу Синдрагосы.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Верните душу Синдрагосы Калесгосу в Храм Драконьего Покоя в Драконьем Погосте.',`completedtext_loc8`);
