INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (24897,'Возвращение в город','Мы ошиблись. Это не наги готовили нападение... а племя Умлот.$B$B$n, тебе нужно вернуться в Городок-из-табакерки. Нас уже атакуют!$B$BВот, возьми. Мы его выкупили у одного пигмея, утверждавшего, что когда-то он принадлежал их великому вождю, чье имя на нашем языке звучит как Темный Шлем.$B$BС его помощью ты их обманешь, и они на тебя не нападут.','Поговорите с Хамми Кофельнагель в Городке-из-табакерки на Затерянных островах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение в город',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы ошиблись. Это не наги готовили нападение... а племя Умлот.$B$B$n, тебе нужно вернуться в Городок-из-табакерки. Нас уже атакуют!$B$BВот, возьми. Мы его выкупили у одного пигмея, утверждавшего, что когда-то он принадлежал их великому вождю, чье имя на нашем языке звучит как Темный Шлем.$B$BС его помощью ты их обманешь, и они на тебя не нападут.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Хамми Кофельнагель в Городке-из-табакерки на Затерянных островах.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (24898,'Груды гуано','$gБратишка:сестричка;, в логовах Иглошкурых ты найдешь не только свиней. Там есть еще и летучие мыши... И раз уж ты все равно отправляешься туда и наверняка привлечешь внимание свинобразов, принеси-ка мне немного гуано.$b$BДа-да, гуано. Выделения. И не смотри на меня так. Конечно, это всего лишь нечистоты, но без них древние ритуалы – ничто... Ритуалы, благодаря которым земля все еще вертится и не раскалывается на куски под ногами всех этих болванов, что живут на ее поверхности.$b$bПросто принеси Зан\'до одну кучку гуано, хорошо?','Принесите Зан\'до в Кремневый лагерь 1 кучку гуано летучей мыши Лабиринтов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Груды гуано',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$gБратишка:сестричка;, в логовах Иглошкурых ты найдешь не только свиней. Там есть еще и летучие мыши... И раз уж ты все равно отправляешься туда и наверняка привлечешь внимание свинобразов, принеси-ка мне немного гуано.$b$BДа-да, гуано. Выделения. И не смотри на меня так. Конечно, это всего лишь нечистоты, но без них древние ритуалы – ничто... Ритуалы, благодаря которым земля все еще вертится и не раскалывается на куски под ногами всех этих болванов, что живут на ее поверхности.$b$bПросто принеси Зан\'до одну кучку гуано, хорошо?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Зан\'до в Кремневый лагерь 1 кучку гуано летучей мыши Лабиринтов.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24899,'Груды гуано','Как видишь, $n, в Королевском фармацевтическом обществе проводят весьма... любопытные эксперименты.$B$BПоскольку я мастер-аптекарь, в мои обязанности входит наблюдать за самыми интересными проектами. Работы полно, а времени в обрез!$B$BХоть ты и |3-6($c), но, судя по всему, немало $gстранствовал:странствовала;. Не поможешь мне?$B$BНам очень нужно редкое вещество. Оно на редкость мерзкое, и его получают только от особой разновидности летучих мышей, которые водятся в дыре под названием Лабиринты Иглошкурых. Принеси мне гуано летучих мышей Лабиринтов, и мы примемся за работу...','Принесите 1 кучку гуано летучей мыши Лабиринтов опытному аптекарю Фаранеллу в Подгород.','Return to Master Apothecary Faranell at Alterac Mountains.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Груды гуано',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как видишь, $n, в Королевском фармацевтическом обществе проводят весьма... любопытные эксперименты.$B$BПоскольку я мастер-аптекарь, в мои обязанности входит наблюдать за самыми интересными проектами. Работы полно, а времени в обрез!$B$BХоть ты и |3-6($c), но, судя по всему, немало $gстранствовал:странствовала;. Не поможешь мне?$B$BНам очень нужно редкое вещество. Оно на редкость мерзкое, и его получают только от особой разновидности летучих мышей, которые водятся в дыре под названием Лабиринты Иглошкурых. Принеси мне гуано летучих мышей Лабиринтов, и мы примемся за работу...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 1 кучку гуано летучей мыши Лабиринтов опытному аптекарю Фаранеллу в Подгород.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Return to Master Apothecary Faranell at Alterac Mountains.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24900,'Корни Синелиста','Корень синелиста – признанный деликатес в любом уголке мира! Но растет он только здесь, в Степях, глубоко под землей в Лабиринтах Иглошкурых.$B$BК тому же клубни так сложно найти, если не знать точно где искать! Поэтому я специально надрессировал этих шмыгуносов, чтобы они находили корни под землей. Обоняние у них просто невероятное – они чуют корни с пятидесяти шагов!$B$BЗадачка, конечно, непростая, но если принесешь мне корней, я хорошо заплачу.','In Razorfen Kraul, use the Crate with Holes to summon a Snufflenose Gopher, and use the Command Stick on the gopher to make it search for Tubers.$B$BBring 6 Blueleaf Tubers to Mebok Mizzyrix in Ratchet.','Вернитесь к Мебоку Миззриксу в Кремневый лагерь, что в Южных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Корни Синелиста',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Корень синелиста – признанный деликатес в любом уголке мира! Но растет он только здесь, в Степях, глубоко под землей в Лабиринтах Иглошкурых.$B$BК тому же клубни так сложно найти, если не знать точно где искать! Поэтому я специально надрессировал этих шмыгуносов, чтобы они находили корни под землей. Обоняние у них просто невероятное – они чуют корни с пятидесяти шагов!$B$BЗадачка, конечно, непростая, но если принесешь мне корней, я хорошо заплачу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','In Razorfen Kraul, use the Crate with Holes to summon a Snufflenose Gopher, and use the Command Stick on the gopher to make it search for Tubers.$B$BBring 6 Blueleaf Tubers to Mebok Mizzyrix in Ratchet.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мебоку Миззриксу в Кремневый лагерь, что в Южных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (24901,'Городок-из-табакерки под угрозой!','$n, ты $gдолжен:должна; нас защитить!$B$BЯ заставила этих идиотов активировать артиллерийскую оборону города, но проклятые умлотские воины все прут и прут!$B$BДавай-ка становись за один из наших баллистических уничтожителей и устрани пигмеев, которые угрожают городу!','С помощью баллистического уничтожителя сразите 30 воинов Умлота.','Ладно, думаю, пока хватит. Но ведь они захватили в плен множество жителей!$B$BМы этого так не оставим. Пора перенести линию фронта на их территорию!','Вернитесь к Хамми Кофельнагель в Городок-из-табакерки на Затерянных островах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Городок-из-табакерки под угрозой!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, ты $gдолжен:должна; нас защитить!$B$BЯ заставила этих идиотов активировать артиллерийскую оборону города, но проклятые умлотские воины все прут и прут!$B$BДавай-ка становись за один из наших баллистических уничтожителей и устрани пигмеев, которые угрожают городу!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','С помощью баллистического уничтожителя сразите 30 воинов Умлота.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ладно, думаю, пока хватит. Но ведь они захватили в плен множество жителей!$B$BМы этого так не оставим. Пора перенести линию фронта на их территорию!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хамми Кофельнагель в Городок-из-табакерки на Затерянных островах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (24902,'В погоне за Сильваной','Чума? Нечто столь ужасное, что даже орки отказываются марать руки? Мы должны немедленно известить короля Седогрива!','Погоня за Сильваной','Вернитесь к Лорне Краули на площадь Седогрива в Гилнеас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В погоне за Сильваной',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Чума? Нечто столь ужасное, что даже орки отказываются марать руки? Мы должны немедленно известить короля Седогрива!',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Погоня за Сильваной',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лорне Краули на площадь Седогрива в Гилнеас.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (24903,'Месть или выживание','Поговорите с королем Генном Седогривом на площади Седогрива в Гилнеасе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Месть или выживание',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с королем Генном Седогривом на площади Седогрива в Гилнеасе.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (24904,'Битва за Гилнеас','Час битвы настал, $n. Мы призвали на службу и вооружили каждого боеспособного жителя.$B$BТеперь мы готовы встретить врага лицом к лицу. Пора раз и навсегда свести счеты с Сильваной и ее приспешниками-Отрекшимися.$B$BЛиам собирает войска у этих ворот, а король Седогрив и мой отец развернут атаку с других позиций.$B$BТы тоже играешь важную роль в этом замысле. Возьми эту рапиру и оправляйся в бой – пусть это зрелище вдохновит наших бравых воинов. А теперь ступай и поговори с Креннаном Аранасом. Он ждет только тебя, чтобы начать битву за Гилнеас.','Одержите победу в битве за Гилнеас.','Мы смогли дать отпор Отрекшимся и освободили три из четырех кварталов города... но какой ценой?','Поговорите с Лорной Краули в гостинице на площади Седогрива в Гилнеас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Битва за Гилнеас',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Час битвы настал, $n. Мы призвали на службу и вооружили каждого боеспособного жителя.$B$BТеперь мы готовы встретить врага лицом к лицу. Пора раз и навсегда свести счеты с Сильваной и ее приспешниками-Отрекшимися.$B$BЛиам собирает войска у этих ворот, а король Седогрив и мой отец развернут атаку с других позиций.$B$BТы тоже играешь важную роль в этом замысле. Возьми эту рапиру и оправляйся в бой – пусть это зрелище вдохновит наших бравых воинов. А теперь ступай и поговори с Креннаном Аранасом. Он ждет только тебя, чтобы начать битву за Гилнеас.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Одержите победу в битве за Гилнеас.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мы смогли дать отпор Отрекшимся и освободили три из четырех кварталов города... но какой ценой?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Лорной Краули в гостинице на площади Седогрива в Гилнеас.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (24905,'Взаимная услуга','Знаешь, пока ты там $gзанимался:занималась; своими делами, здесь останавливалась Мегз. Мы с ней давненько не видались, но она со мной толком и не поговорила – лишь сказала передать тебе, что у нее вырисовывается новое дельце.$b$bОна сказала, что отправляется к поселению Песчаного Молота и собирается заняться там какой-то торговлей, вроде бы что-то, связанное с ограми. Раз уж здесь тебе делать больше нечего, можешь отправиться за ней... Такого гоблина, как она, не стоит заставлять ждать.','Найдите Мегз Жестекрошшер в поселении Песчаного Молота.','На этот раз у меня действительно особенное задание для тебя, $B. Мы собираемся принять этих огров в Орду... Для того, чтобы они работали непосредственно на нас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Взаимная услуга',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Знаешь, пока ты там $gзанимался:занималась; своими делами, здесь останавливалась Мегз. Мы с ней давненько не видались, но она со мной толком и не поговорила – лишь сказала передать тебе, что у нее вырисовывается новое дельце.$b$bОна сказала, что отправляется к поселению Песчаного Молота и собирается заняться там какой-то торговлей, вроде бы что-то, связанное с ограми. Раз уж здесь тебе делать больше нечего, можешь отправиться за ней... Такого гоблина, как она, не стоит заставлять ждать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Мегз Жестекрошшер в поселении Песчаного Молота.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','На этот раз у меня действительно особенное задание для тебя, $B. Мы собираемся принять этих огров в Орду... Для того, чтобы они работали непосредственно на нас.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24906,'Спасение имущества','Продвигать товар на этот рынок нужно КАК МОЖНО БЫСТРЕЕ, если мы хотим конкурентоспособности. Есть у меня одна идейка.$b$bПрибамбасск осажен пиратами, но почти весь товар с разбитых судов остался нетронутым... Его просто смыло в море. Коробки так и остались лежать на мелководье к югу от города.$b$bОтправляйся прямиком туда и собери все, что сможешь. Это же не просто ящики – это чистая прибыль терпеливо дожидается нас на волнах.','Соберите 7 контейнеров с припасами Хитрой Шестеренки.','Хмм, пригодится. Хороший товар. Покупатели уже выстроились в очередь, разумеется. $B$BВот и твой аванс. Аванс за ту работу, которую тебе еще предстоит выполнить для меня и картеля Трюмных Вод... Коллега.','Давай-ка посмотрим, что тебе удалось достать.','Вернитесь к Мегз Жестекрошшер в Прибамбасск.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спасение имущества',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Продвигать товар на этот рынок нужно КАК МОЖНО БЫСТРЕЕ, если мы хотим конкурентоспособности. Есть у меня одна идейка.$b$bПрибамбасск осажен пиратами, но почти весь товар с разбитых судов остался нетронутым... Его просто смыло в море. Коробки так и остались лежать на мелководье к югу от города.$b$bОтправляйся прямиком туда и собери все, что сможешь. Это же не просто ящики – это чистая прибыль терпеливо дожидается нас на волнах.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 7 контейнеров с припасами Хитрой Шестеренки.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хмм, пригодится. Хороший товар. Покупатели уже выстроились в очередь, разумеется. $B$BВот и твой аванс. Аванс за ту работу, которую тебе еще предстоит выполнить для меня и картеля Трюмных Вод... Коллега.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Давай-ка посмотрим, что тебе удалось достать.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мегз Жестекрошшер в Прибамбасск.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (24907,'Топая по лужам','Ситуация такова: если мы хотим упрочить положение картеля Трюмных Вод на рынке Прибамбасска, необходимо начать предоставлять потребителям услуги.$b$bНовый берег – отличное место для развития нашего бизнеса, однако в море есть и огромные морские великаны, так что цена недвижимости там невелика.$b$bОтправляйся к отмелям на юге от города и убей как можно больше великанов, а я поделюсь с тобой комиссионными с некоторых сделок.','Убейте 8 приливных странников.','Цены на недвижимость сильно упали с того момента, как мы виделись последний раз. Людям нравится вид на море – но только на море, без неуклюжих морских великанов, сотрясающих все вокруг своими шагами.$B$BВот твоя доля, Эльфазито.','Вернитесь к Мегз Жестекрошшер в Прибамбасск, что в Танарисе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Топая по лужам',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ситуация такова: если мы хотим упрочить положение картеля Трюмных Вод на рынке Прибамбасска, необходимо начать предоставлять потребителям услуги.$b$bНовый берег – отличное место для развития нашего бизнеса, однако в море есть и огромные морские великаны, так что цена недвижимости там невелика.$b$bОтправляйся к отмелям на юге от города и убей как можно больше великанов, а я поделюсь с тобой комиссионными с некоторых сделок.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 приливных странников.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Цены на недвижимость сильно упали с того момента, как мы виделись последний раз. Людям нравится вид на море – но только на море, без неуклюжих морских великанов, сотрясающих все вокруг своими шагами.$B$BВот твоя доля, Эльфазито.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мегз Жестекрошшер в Прибамбасск, что в Танарисе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24908,'[NOT USED] Build the Fort Placeholder','Nice work! For our next placeholder, talk to that dude. Uh, Foreman Franklin. Special stuff will happen.','Contact Foreman Franklin.','Поговорите со штейгером Франклином.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[NOT USED] Build the Fort Placeholder',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Nice work! For our next placeholder, talk to that dude. Uh, Foreman Franklin. Special stuff will happen.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Contact Foreman Franklin.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите со штейгером Франклином.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24909,'[NOT USED] Protect the Pass Placeholder','This here placeholder will be like a shootin\' gallery. On Steroids.','Use the guns.','Отправляйтесь к штейгеру Франклину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[NOT USED] Protect the Pass Placeholder',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','This here placeholder will be like a shootin\' gallery. On Steroids.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Use the guns.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отправляйтесь к штейгеру Франклину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24910,'Спасательная ракета','Ну что ж, $n, кое-что мы здесь уже сделали. Настало время приниматься за настоящую работу.$b$bВ руинах Порта Хитрой Шестеренки осталось немало беспомощных гоблинов, потерявших надежду на спасение. Каждый из них – наш потенциальный покупатель. Но пираты расстреливают любую лодку, что покидает порт... так что мы отправимся по воздуху!$b$bРядом с пристанью, прямо за городом, есть воздушный шар, наполненный горячим воздухом, и мы можем его использовать. Отправляйся туда и забирайся в корзину, а я догоню.','Доставьте спасательные ракеты 5 уцелевшим из картеля и убейте бомбами 40 громил южных морей.','Поговорите с Мегз Жестекрошшер в Прибамбасске, что в Танарисе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спасательная ракета',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну что ж, $n, кое-что мы здесь уже сделали. Настало время приниматься за настоящую работу.$b$bВ руинах Порта Хитрой Шестеренки осталось немало беспомощных гоблинов, потерявших надежду на спасение. Каждый из них – наш потенциальный покупатель. Но пираты расстреливают любую лодку, что покидает порт... так что мы отправимся по воздуху!$b$bРядом с пристанью, прямо за городом, есть воздушный шар, наполненный горячим воздухом, и мы можем его использовать. Отправляйся туда и забирайся в корзину, а я догоню.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте спасательные ракеты 5 уцелевшим из картеля и убейте бомбами 40 громил южных морей.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Мегз Жестекрошшер в Прибамбасске, что в Танарисе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (24911,'Тропический рай манит','Явитесь к Виллидену Маршаллу на заставу Маршалла, что в кратере Ун\'Горо.','Эй, Холания, ты только посмотри на его прикид!$B$B<Виллиден поворачивается к вам>$B$BГм. Тебя послал наш вербовщик? Ладно. Для начала честно признаюсь – Ун\'Горо не совсем похож на тот райский уголок, который он тебе, должно быть, описал. Впрочем, это ты скорее всего уже понял, добираясь сюда.$B$BПриступим к работе?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тропический рай манит',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Явитесь к Виллидену Маршаллу на заставу Маршалла, что в кратере Ун\'Горо.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Эй, Холания, ты только посмотри на его прикид!$B$B<Виллиден поворачивается к вам>$B$BГм. Тебя послал наш вербовщик? Ладно. Для начала честно признаюсь – Ун\'Горо не совсем похож на тот райский уголок, который он тебе, должно быть, описал. Впрочем, это ты скорее всего уже понял, добираясь сюда.$B$BПриступим к работе?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`) VALUES (24912,'Великая сила','<Верховный лорд Дарион Могрейн с настойчивостью обращается к вам.>$B$BГрань Тьмы впитала нужную силу.$B$BНастал час перековать этот топор в Темную Скорбь...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Великая сила',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Верховный лорд Дарион Могрейн с настойчивостью обращается к вам.>$B$BГрань Тьмы впитала нужную силу.$B$BНастал час перековать этот топор в Темную Скорбь...',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24913,'Помни о Свете','Магтур слабеет с каждым мигом, $n. Мое снадобье готово... оно должно помочь. Просто обязано!$B$BТы так много $gсделал:сделала; для нас обоих. Я был бы признателен, если бы ты $gпочтил:почтила; нас своим присутствием в последние минуты жизни Магтора.','Поддержите анахорета Авууна в последние минуты жизни Магтура.','Поговорите с анахоретом Авууном.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Помни о Свете',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Магтур слабеет с каждым мигом, $n. Мое снадобье готово... оно должно помочь. Просто обязано!$B$BТы так много $gсделал:сделала; для нас обоих. Я был бы признателен, если бы ты $gпочтил:почтила; нас своим присутствием в последние минуты жизни Магтора.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поддержите анахорета Авууна в последние минуты жизни Магтура.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с анахоретом Авууном.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (24914,'Личное имущество','На ящике не видно ни петель, ни замка. Если бы не шум перекатывающихся внутри предметов, его вполне можно было бы принять за цельный кусок металла. $b$bЕдинственным, кто смог бы его открыть, является верховный лорд Могрейн.','<После начертания замысловатого узора из рун на каждой стороне ящичка проявились границы крышки и звук щелчка эхом разнесся по помещению.>$B$BВот, держи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Личное имущество',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На ящике не видно ни петель, ни замка. Если бы не шум перекатывающихся внутри предметов, его вполне можно было бы принять за цельный кусок металла. $b$bЕдинственным, кто смог бы его открыть, является верховный лорд Могрейн.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<После начертания замысловатого узора из рун на каждой стороне ящичка проявились границы крышки и звук щелчка эхом разнесся по помещению.>$B$BВот, держи.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`) VALUES (24915,'Воссоединение Могрейна','Что это у тебя, |3-6($C)? Во мне пробуждаются чувства, которые, я думал, уже давно мертвы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Воссоединение Могрейна',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что это у тебя, |3-6($C)? Во мне пробуждаются чувства, которые, я думал, уже давно мертвы.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`) VALUES (24916,'Медальон Джайны','Чем я могу помочь тебе, |3-6($C)?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Медальон Джайны',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Чем я могу помочь тебе, |3-6($C)?',`requestitemstext_loc8`);
