INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`) VALUES (24919,'Искупление Утера Светоносного','Чем могу служить, |3-6($R)?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Искупление Утера Светоносного',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Чем могу служить, |3-6($R)?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24920,'Оттянуть неизбежное','Оседлайте пойманного нетопыря, уничтожьте 6 катапульт Отрекшихся и убейте 40 Отрекшихся-захватчиков.','Вернитесь к королю Генну Седогриву на площадь Седогрива в Гилнеасе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оттянуть неизбежное',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Оседлайте пойманного нетопыря, уничтожьте 6 катапульт Отрекшихся и убейте 40 Отрекшихся-захватчиков.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к королю Генну Седогриву на площадь Седогрива в Гилнеасе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (24921,'Доклад Обри','Эй, ты, там! $GНовенький:Новенькая;? Добро пожаловать в Калимдор, землю, всегда готовую тебя убить.$b$bТам в крепости проблемы. Наверное, ты и $gсам заметил:сама заметила; по пути сюда. Адмиралу Обри пригодится любая пара рук. Считай, что это приказ, |3-6($c)!$b$bИди по дороге вверх на холм и ты найдешь Обри в башне, на самом верху.','Обратитесь к адмиралу Обри.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Доклад Обри',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эй, ты, там! $GНовенький:Новенькая;? Добро пожаловать в Калимдор, землю, всегда готовую тебя убить.$b$bТам в крепости проблемы. Наверное, ты и $gсам заметил:сама заметила; по пути сюда. Адмиралу Обри пригодится любая пара рук. Считай, что это приказ, |3-6($c)!$b$bИди по дороге вверх на холм и ты найдешь Обри в башне, на самом верху.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Обратитесь к адмиралу Обри.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (24924,'Деревня Умлот','Пигмеи увели почти всех наших в свою деревню. И кто знает, какое зло они замыслили?$B$B$n, иди туда и освободи всех пленников, пока пигмеи не зачаровали их магией вуду!$B$BИззи уже на юго-востоке, рядом с деревней Умлот. Она сообщит тебе последние новости.$B$BТвой шлем пигмея в скверном состоянии, но он позволит тебе добраться до места.$B$BНадеюсь.','Поговорите с Иззи в деревне Умлот на Затерянных островах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Деревня Умлот',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пигмеи увели почти всех наших в свою деревню. И кто знает, какое зло они замыслили?$B$B$n, иди туда и освободи всех пленников, пока пигмеи не зачаровали их магией вуду!$B$BИззи уже на юго-востоке, рядом с деревней Умлот. Она сообщит тебе последние новости.$B$BТвой шлем пигмея в скверном состоянии, но он позволит тебе добраться до места.$B$BНадеюсь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Иззи в деревне Умлот на Затерянных островах.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (24925,'Свободу пленникам','Они захватили в плен многих наших и проводят над ними какие-то странные ритуалы – похоже, высасывают жизненную энергию!$B$BОтправляйся в деревню и освободи пленников, пока не поздно!','Освободите 5 пленных гоблинов.','Ты хорошо потрудился, но заложников было намного больше.$B$BВот проклятье! Наверное, они увели остальных в другие свои поселения – выше по склону вулкана!','Вернитесь к Иззи в деревню Умлот на Затерянных островах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Свободу пленникам',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Они захватили в плен многих наших и проводят над ними какие-то странные ритуалы – похоже, высасывают жизненную энергию!$B$BОтправляйся в деревню и освободи пленников, пока не поздно!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Освободите 5 пленных гоблинов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты хорошо потрудился, но заложников было намного больше.$B$BВот проклятье! Наверное, они увели остальных в другие свои поселения – выше по склону вулкана!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Иззи в деревню Умлот на Затерянных островах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24926,'Помочь Чи-Та 3','Приветствую. Я есть модуль Чи-Та 3. Ты... |3-6($r)?$b$bЧи-Та успешно выполнила свое задание по изучению местных горилл. Чи-Та собрала данные, которые нужны Карне.$b$bЧи-Та не возвращается однако. Чи-Та нашла новую семью. Здесь, с гориллами, Чи-Та остается.$b$b<Чи-Та отсоединяет от своей руки маленькое устройство и отдает его вам.>$b$bТы принесешь данные Карне. Ты расскажешь ей, что случилось.','Чт-т... Что это?','Вернитесь к Карне Сомнамбулер на Мшистую горку в Кратере Ун\'Горо.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Помочь Чи-Та 3',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приветствую. Я есть модуль Чи-Та 3. Ты... |3-6($r)?$b$bЧи-Та успешно выполнила свое задание по изучению местных горилл. Чи-Та собрала данные, которые нужны Карне.$b$bЧи-Та не возвращается однако. Чи-Та нашла новую семью. Здесь, с гориллами, Чи-Та остается.$b$b<Чи-Та отсоединяет от своей руки маленькое устройство и отдает его вам.>$b$bТы принесешь данные Карне. Ты расскажешь ей, что случилось.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Чт-т... Что это?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Карне Сомнамбулер на Мшистую горку в Кратере Ун\'Горо.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (24927,'Сундук мертвеца','Так, детка, ты уловишь суть происходящего здесь очень быстро. Есть пираты, есть гоблины, гоблины сражаются с пиратами. Есть жалкая кучка маленьких гномов, которые тоже пытаются сражаться с пиратами.$b$bНе вдаваясь в лишние подробности – нам нужно убить как можно больше пиратов. Иди-ка и сделай это, идет? Не хотелось бы, чтобы в итоге оказалось, что гномы убили больше пиратов, чем мы.','Я счастлив доложить, что твои усилия увенчались успехом: наш рейтинг популярности взлетел до небес!','Вернитесь к Мегз Жестекрошшер в Бухту Сорванных Парусов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сундук мертвеца',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Так, детка, ты уловишь суть происходящего здесь очень быстро. Есть пираты, есть гоблины, гоблины сражаются с пиратами. Есть жалкая кучка маленьких гномов, которые тоже пытаются сражаться с пиратами.$b$bНе вдаваясь в лишние подробности – нам нужно убить как можно больше пиратов. Иди-ка и сделай это, идет? Не хотелось бы, чтобы в итоге оказалось, что гномы убили больше пиратов, чем мы.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я счастлив доложить, что твои усилия увенчались успехом: наш рейтинг популярности взлетел до небес!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мегз Жестекрошшер в Бухту Сорванных Парусов.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (24928,'Дотла!','Я провела тщательную оценку недвижимости здесь и, к сожалению, ее рыночная стоимость ниже даже минимального приемлемого уровня. Придется заняться восстановлением.$b$bТебе повезло – я кое-что знаю о поджогах. Надеюсь, ты тоже! Подожжешь эти отвратительные ветхие лачуги с помощью абсолютно безопасных в использовании бутылок горючего рома.$b$bСтарайся держаться с подветренной стороны.','Подожгите лачуги на северо-западе, северо-восторе и юго-западе.','Великолепно. Когда-нибудь думал о том, чтобы заняться поджогами всерьез? Знаю несколько ребят, отличная работка.$B$BЛадно, об этом поболтаем потом. Здесь еще полно работы!','Вернитесь к Мегз Жестекрошшер в Бухту Сорванных Парусов, что в Танарисе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дотла!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я провела тщательную оценку недвижимости здесь и, к сожалению, ее рыночная стоимость ниже даже минимального приемлемого уровня. Придется заняться восстановлением.$b$bТебе повезло – я кое-что знаю о поджогах. Надеюсь, ты тоже! Подожжешь эти отвратительные ветхие лачуги с помощью абсолютно безопасных в использовании бутылок горючего рома.$b$bСтарайся держаться с подветренной стороны.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Подожгите лачуги на северо-западе, северо-восторе и юго-западе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Великолепно. Когда-нибудь думал о том, чтобы заняться поджогами всерьез? Знаю несколько ребят, отличная работка.$B$BЛадно, об этом поболтаем потом. Здесь еще полно работы!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мегз Жестекрошшер в Бухту Сорванных Парусов, что в Танарисе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (24929,'Расставить точки над Ингви','Правитель Умлота Ингви обладает слишком большой властью. Его нельзя оставлять в живых. Сейчас он торчит за навесным мостом на западе деревни и не переставая несет какую-то пигмейскую околесицу.$B$BУбей его, пока он не натравил на нас всю деревню.$B$BЭто будет легче легкого!','Убейте Ингви.','Прекрасно, приятель! Надеюсь, он не оказал упорного сопротивления.','Вернитесь к Иззи в деревню Умлот на Затерянных островах.','Пусть они никогда этого не забудут.','Ингви') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Расставить точки над Ингви',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Правитель Умлота Ингви обладает слишком большой властью. Его нельзя оставлять в живых. Сейчас он торчит за навесным мостом на западе деревни и не переставая несет какую-то пигмейскую околесицу.$B$BУбей его, пока он не натравил на нас всю деревню.$B$BЭто будет легче легкого!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Ингви.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно, приятель! Надеюсь, он не оказал упорного сопротивления.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Иззи в деревню Умлот на Затерянных островах.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Пусть они никогда этого не забудут.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Ингви',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24930,'Попутное дело','Если король Седогрив просит тебя рискнуть жизнью ради предателя – это твое дело.$B$BТолько сделай по пути что-нибудь полезное – убей несколько вшивых шавок.','Убейте 5 воргенов из стаи Кровавых Клыков.','Вернитесь к лорду Годфри в Военный квартал Гилнеаса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Попутное дело',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если король Седогрив просит тебя рискнуть жизнью ради предателя – это твое дело.$B$BТолько сделай по пути что-нибудь полезное – убей несколько вшивых шавок.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 5 воргенов из стаи Кровавых Клыков.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лорду Годфри в Военный квартал Гилнеаса.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24931,'Довесок – взорени','Ты собираешься охотиться на гиен, так ведь? У меня есть одно предложение, если не против. Мне нужны глаза стеклошкурых взореней, что бродят на севере. В них можно найти восхитительные кристаллы, крайне ценные... для коллекционеров.$b$bВпрочем, ты $gмог:могла; слышать и о том, что некоторые жалкие личности используют их для усиления паранормальных способностей, но, уверяю тебя, мой интерес здесь чисто академический!$b$bПринеси мне горсть этих кристаллов, а я хорошо заплачу... По крайней мере, определенно лучше, чем за них платят эти скупые гоблины!','Соберите со стеклошкурых взореней 5 глазных кристаллов.','Ох, превосходно! То, что нужно... Прямо сочится энергией…$B$BМ...Гм! Я имею в виду, отличный экземпляр для моей коллекции! Нарайну Причуденю не нужно подпитывать свои удивительные силы из внешних источников!$B$BЗабирай свою награду и выметайся!','Ты, ох, ты достал их?','Вернитесь к Нарайну Причуденю на стоянку бутлегеров в Танарисе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Довесок – взорени',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты собираешься охотиться на гиен, так ведь? У меня есть одно предложение, если не против. Мне нужны глаза стеклошкурых взореней, что бродят на севере. В них можно найти восхитительные кристаллы, крайне ценные... для коллекционеров.$b$bВпрочем, ты $gмог:могла; слышать и о том, что некоторые жалкие личности используют их для усиления паранормальных способностей, но, уверяю тебя, мой интерес здесь чисто академический!$b$bПринеси мне горсть этих кристаллов, а я хорошо заплачу... По крайней мере, определенно лучше, чем за них платят эти скупые гоблины!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите со стеклошкурых взореней 5 глазных кристаллов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ох, превосходно! То, что нужно... Прямо сочится энергией…$B$BМ...Гм! Я имею в виду, отличный экземпляр для моей коллекции! Нарайну Причуденю не нужно подпитывать свои удивительные силы из внешних источников!$B$BЗабирай свою награду и выметайся!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты, ох, ты достал их?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Нарайну Причуденю на стоянку бутлегеров в Танарисе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (24932,'Снижение потерь','Всю последнюю неделю размышлял, можно ли извлечь какую-то выгоду из этих отвратительных, опасных, безжалостных насекомых. Но сейчас размышления зашли в тупик, у меня больше нет никаких идей, и к тому же я ужасно проголодался. $b$bЭти существа совершенно бесполезны, и я думаю – настало время от них избавиться. Отправляйся в яму и приступай к уничтожению насекомых.','Убейте 15 силитидов из улья Хаззали в Зияющей бездне.','Получается не так уж быстро. Должен быть какой-то другой способ...','Вернитесь к Зеке Волочилкинсу на стоянку бутлегеров в Танарис.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Снижение потерь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Всю последнюю неделю размышлял, можно ли извлечь какую-то выгоду из этих отвратительных, опасных, безжалостных насекомых. Но сейчас размышления зашли в тупик, у меня больше нет никаких идей, и к тому же я ужасно проголодался. $b$bЭти существа совершенно бесполезны, и я думаю – настало время от них избавиться. Отправляйся в яму и приступай к уничтожению насекомых.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 15 силитидов из улья Хаззали в Зияющей бездне.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Получается не так уж быстро. Должен быть какой-то другой способ...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Зеке Волочилкинсу на стоянку бутлегеров в Танарис.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24933,'Цыпленок в пустыне','У меня появился план, но для его реализации нам потребуется наживка.$b$bЯ кое-что увидел однажды. Стоило хромоногой гиене подобраться слишком близко к краю ямы, как из глубины ее молнией выскочил силитид. Проглотил гиену практически целиком! Отвратительное зрелище!$b$bТаким образом, нам нужно только мясо гиены. Иди достань несколько кусков – оно должно быть достаточно свежим – и принеси его сюда. Эти твари водятся в изобилии на севере от лагеря.','Соберите 6 кусков мяса гиены.','Ох, выглядит так аппетитно. Еле борюсь с искушением пожарить чуть-чуть для себя.$B$BНет! Надо сосредоточиться на том, чтобы выбраться отсюда.$B$BНу, может быть только один кусочек...','Оно ведь свежее, так? Они вряд ли любят вяленое на солнце мясо.','Вернитесь к Зеке Волочилкинсу на стоянку бутлегеров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Цыпленок в пустыне',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У меня появился план, но для его реализации нам потребуется наживка.$b$bЯ кое-что увидел однажды. Стоило хромоногой гиене подобраться слишком близко к краю ямы, как из глубины ее молнией выскочил силитид. Проглотил гиену практически целиком! Отвратительное зрелище!$b$bТаким образом, нам нужно только мясо гиены. Иди достань несколько кусков – оно должно быть достаточно свежим – и принеси его сюда. Эти твари водятся в изобилии на севере от лагеря.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 6 кусков мяса гиены.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ох, выглядит так аппетитно. Еле борюсь с искушением пожарить чуть-чуть для себя.$B$BНет! Надо сосредоточиться на том, чтобы выбраться отсюда.$B$BНу, может быть только один кусочек...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Оно ведь свежее, так? Они вряд ли любят вяленое на солнце мясо.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Зеке Волочилкинсу на стоянку бутлегеров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24934,'Дать отпор идущим на абордаж!','Для нас море – это жизнь, $n, и как раз сейчас мои корабли либо движутся обратно в Терамор для ремонта, либо ржавеют на дне этого залива. На плаву только Блэкпул, лишь он и защищает гавань.$b$bНо и этот корабль только что подал сигнал, что его берут на абордаж!$b$bСкажи мне, когда ты будешь $gготов:готова;, и один из наших морских грифонов отнесет тебя на палубу. Убей морских волков Грознорева, которые осмелились поднять руку на мой самый ценный корабль, и отправляйся к капитану Фишеру за дальнейшими приказами.','Поговорите с адмиралом Обри, затем отправляйтесь на Блэкпул и убейте 6 морских волков Грознорева.','Поговорите с капитаном Фишером.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дать отпор идущим на абордаж!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Для нас море – это жизнь, $n, и как раз сейчас мои корабли либо движутся обратно в Терамор для ремонта, либо ржавеют на дне этого залива. На плаву только Блэкпул, лишь он и защищает гавань.$b$bНо и этот корабль только что подал сигнал, что его берут на абордаж!$b$bСкажи мне, когда ты будешь $gготов:готова;, и один из наших морских грифонов отнесет тебя на палубу. Убей морских волков Грознорева, которые осмелились поднять руку на мой самый ценный корабль, и отправляйся к капитану Фишеру за дальнейшими приказами.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с адмиралом Обри, затем отправляйтесь на Блэкпул и убейте 6 морских волков Грознорева.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с капитаном Фишером.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24935,'Body And Soul','There are powerful and evil magics at work in this village. Yngwie, was tough. In fact, he was probably too tough.$B$BIf you were to drag his body down to the big blue bonfire and toss it in, you\'d release his soul. Destroying it would deal with the Oomlot chieftain for good, and ensure that the attacks upon the Town-In-A-Box come to an end.','Destroy Yngwie\'s Soul.$B$BIf you somehow misplace Yngwie\'s Body, ask Izzy if she found it.','Return to Izzy at Oomlot Village on the Lost Isles.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Body And Soul',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','There are powerful and evil magics at work in this village. Yngwie, was tough. In fact, he was probably too tough.$B$BIf you were to drag his body down to the big blue bonfire and toss it in, you\'d release his soul. Destroying it would deal with the Oomlot chieftain for good, and ensure that the attacks upon the Town-In-A-Box come to an end.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Destroy Yngwie\'s Soul.$B$BIf you somehow misplace Yngwie\'s Body, ask Izzy if she found it.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Return to Izzy at Oomlot Village on the Lost Isles.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24936,'Body And Soul','There are powerful and evil magics at work in this village, $n. Yngwie, was tough. In fact, he was probably too tough.$B$BIf you were to drag his body over to the big blue bonfire and toss it in, you\'d release his soul. Destroying it would deal with the Oomlot chieftain for good, and ensure that the attacks upon the Town-In-A-Box come to an end.','Destroy Yngwie\'s Soul.$B$BIf you somehow misplace Yngwie\'s Body, ask Izzy if she found it.','Return to Izzy at Oomlot Village on the Lost Isles.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Body And Soul',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','There are powerful and evil magics at work in this village, $n. Yngwie, was tough. In fact, he was probably too tough.$B$BIf you were to drag his body over to the big blue bonfire and toss it in, you\'d release his soul. Destroying it would deal with the Oomlot chieftain for good, and ensure that the attacks upon the Town-In-A-Box come to an end.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Destroy Yngwie\'s Soul.$B$BIf you somehow misplace Yngwie\'s Body, ask Izzy if she found it.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Return to Izzy at Oomlot Village on the Lost Isles.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (24937,'С Умлотом покончено','$n, тебе нужно вернуться в Городок-из-табакерки и предупредить жителей о гоблинах-зомби в жерле вулкана!','Поговорите с Хамми Кофельнагель в Городке-из-табакерки на Затерянных островах.','Они превратили их в зомби? Тоже мне, новость...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','С Умлотом покончено',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, тебе нужно вернуться в Городок-из-табакерки и предупредить жителей о гоблинах-зомби в жерле вулкана!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Хамми Кофельнагель в Городке-из-табакерки на Затерянных островах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Они превратили их в зомби? Тоже мне, новость...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (24938,'Капитан Фишер сигнализировал нам снизу. Флот Орды высаживает десант на берег? Мы не можем уступить им его.$b$bЯ уже отправил туда двух моих лучших стрелков для защиты берегового плацдарма. Поговори на берегу с канониром Смайтом.$b$bЧтобы пройти туда через внутренний двор, тебе придется держать бой. Посмотри, сможешь ли ты помочь другим обеспечить безопасность крепости.','Поговорите с канониром Смайтом.','Тебя прислал Обри? Хорошо! Думаю, ты знаешь, для чего нужны пушки?','Поговорите с канониром Смайтом.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Капитан Фишер сигнализировал нам снизу. Флот Орды высаживает десант на берег? Мы не можем уступить им его.$b$bЯ уже отправил туда двух моих лучших стрелков для защиты берегового плацдарма. Поговори на берегу с канониром Смайтом.$b$bЧтобы пройти туда через внутренний двор, тебе придется держать бой. Посмотри, сможешь ли ты помочь другим обеспечить безопасность крепости.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с канониром Смайтом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебя прислал Обри? Хорошо! Думаю, ты знаешь, для чего нужны пушки?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с канониром Смайтом.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (24939,'До последнего патрона','У нас достаточно оружия, но не хватает людей, $n. На берегу есть артиллерийские орудия – залей огнем приближающиеся лодки!','Хо-хо! Берег наш!$B$BВ конце концов мы смогли сохранить свой плацдарм на этом клочке земли.','Поговорите с канониром Смайтом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','До последнего патрона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У нас достаточно оружия, но не хватает людей, $n. На берегу есть артиллерийские орудия – залей огнем приближающиеся лодки!',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хо-хо! Берег наш!$B$BВ конце концов мы смогли сохранить свой плацдарм на этом клочке земли.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с канониром Смайтом.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (24940,'На вулкан!','Целая команда наших отправилась наверх, чтобы спасти остальных и противостоять нападению. Там, на Затерянном пике, затевается что-то ужасное.$B$BОни хотят дождаться тебя, прежде чем что-то предпринимать против пигмеев. Как видишь, этим злобным мелким созданиям удалось превратить множество из нас в зомби!$B$BСпаси нас, $n!','Поговорите с тренером Проверяком на Затерянном пике на Затерянных островах.','О, вот и прибыл мой звездный игрок!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На вулкан!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Целая команда наших отправилась наверх, чтобы спасти остальных и противостоять нападению. Там, на Затерянном пике, затевается что-то ужасное.$B$BОни хотят дождаться тебя, прежде чем что-то предпринимать против пигмеев. Как видишь, этим злобным мелким созданиям удалось превратить множество из нас в зомби!$B$BСпаси нас, $n!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с тренером Проверяком на Затерянном пике на Затерянных островах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, вот и прибыл мой звездный игрок!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24941,'Наброска картечи','Соберите 15 предметов для наброски картечи.','Войска Орды собираются в нижней части холма. Заряди пушку обрезками железа, которые ты собрала, отойди, закрой одно ухо и дергай за шнур...','Пакстон уже зарядил пушку. То, что ты принесла, отлично подошло.','Огонь!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наброска картечи',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 15 предметов для наброски картечи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Войска Орды собираются в нижней части холма. Заряди пушку обрезками железа, которые ты собрала, отойди, закрой одно ухо и дергай за шнур...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Пакстон уже зарядил пушку. То, что ты принесла, отлично подошло.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Огонь!',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (24942,'Зомби против реактивных сапог с суперускорителем','Прошедшие мимо зомби – лишь жалкая горстка по сравнению с той толпой, что дожидается на той стороне ущелья. Если мы не расправимся с ними в ближайшее время, пигмеи-знахари нашлют их на город, и тогда никто не устоит. Зомби слишком много! Тут даже пушки бессильны.$B$BЯ тут раздобыл пару универсальных ботинок, Грили их модифицировала – и теперь у нас есть реактивные сапоги с суперускорителем!$B$BВозьми эти чудо-сапожки и испепели всех зомби в устанских деревнях на востоке.','С помощью реактивных сапог с суперускорителем уничтожьте 50 гоблинов-зомби.','У тебя все получилось! Теперь о зомби можно больше не думать. Почтим их память минутой молчания.$B$BХотя минута – это слишком. С них и пары секунд хватит.','Вернитесь к тренеру Проверяку на Затерянный пик на Затерянных островах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зомби против реактивных сапог с суперускорителем',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прошедшие мимо зомби – лишь жалкая горстка по сравнению с той толпой, что дожидается на той стороне ущелья. Если мы не расправимся с ними в ближайшее время, пигмеи-знахари нашлют их на город, и тогда никто не устоит. Зомби слишком много! Тут даже пушки бессильны.$B$BЯ тут раздобыл пару универсальных ботинок, Грили их модифицировала – и теперь у нас есть реактивные сапоги с суперускорителем!$B$BВозьми эти чудо-сапожки и испепели всех зомби в устанских деревнях на востоке.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','С помощью реактивных сапог с суперускорителем уничтожьте 50 гоблинов-зомби.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','У тебя все получилось! Теперь о зомби можно больше не думать. Почтим их память минутой молчания.$B$BХотя минута – это слишком. С них и пары секунд хватит.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к тренеру Проверяку на Затерянный пик на Затерянных островах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (24943,'Вернуть внутренний двор','Это был довольно оригинальный способ... Вон те тела проколоты ножами и вилками!$b$bКлан Грознорева пробил стены, но мы все еще можем изменить исход битвы. Иди вниз и помоги нашим удержать внутренний двор...','Убейте 10 рубак Грознорева.','Превосходно! Мы задали им жару, теперь мы сможем дождаться подкрепления.$B$BПри условии, что мы найдем способ вывести из строя их артиллерию...','Вернитесь к Томасу Пакстону.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вернуть внутренний двор',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это был довольно оригинальный способ... Вон те тела проколоты ножами и вилками!$b$bКлан Грознорева пробил стены, но мы все еще можем изменить исход битвы. Иди вниз и помоги нашим удержать внутренний двор...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 рубак Грознорева.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Превосходно! Мы задали им жару, теперь мы сможем дождаться подкрепления.$B$BПри условии, что мы найдем способ вывести из строя их артиллерию...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Томасу Пакстону.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24944,'После битвы','Бой не закончен, |3-6($c). Наше преимущество невелико.$b$bНекоторые из наших солдат во внутреннем дворе все еще дышат. Мы можем спасти их! Я пропитал эти лоскуты травяным настоем, который мы использовали еще в Гилнеасе. Пахнет ужасно, но поднимет на ноги и мертвого.$b$bИспользуй их для перевязок искалеченных защитников внутреннего двора и, может быть, они снова будут в строю.','Используйте пропитанные травяным настоем повязки для перевязки 6 искалеченных защитников.','Вернитесь к Толливеру Песьему Зубу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','После битвы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Бой не закончен, |3-6($c). Наше преимущество невелико.$b$bНекоторые из наших солдат во внутреннем дворе все еще дышат. Мы можем спасти их! Я пропитал эти лоскуты травяным настоем, который мы использовали еще в Гилнеасе. Пахнет ужасно, но поднимет на ноги и мертвого.$b$bИспользуй их для перевязок искалеченных защитников внутреннего двора и, может быть, они снова будут в строю.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте пропитанные травяным настоем повязки для перевязки 6 искалеченных защитников.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Толливеру Песьему Зубу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (24945,'Три пигмея','Слушай, вот мы уничтожаем зомби – это, конечно, просто замечательно. Даже несмотря на то, что они наши друзья, родственники и все такое. Но тебе не кажется, что лучше бы нам разобраться с пигмеями, которые их создают?$B$BВ трех деревнях Устана – Норде, Соре и Осте – живут три знахаря: Гаал, Мальмо и Телох.$B$BМожет, ты разберешься с ними? Лично я не хочу, чтобы меня превратили в зомби!','Убейте Гаала, Мальмо и Телоха.','Уф! Прямо гора с плеч! Теперь мы можем разобраться с оставшимися зомби, не боясь новой волны нашествия!','Вернитесь к штейгеру Промокаху на Затерянный пик на Затерянных островах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Три пигмея',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слушай, вот мы уничтожаем зомби – это, конечно, просто замечательно. Даже несмотря на то, что они наши друзья, родственники и все такое. Но тебе не кажется, что лучше бы нам разобраться с пигмеями, которые их создают?$B$BВ трех деревнях Устана – Норде, Соре и Осте – живут три знахаря: Гаал, Мальмо и Телох.$B$BМожет, ты разберешься с ними? Лично я не хочу, чтобы меня превратили в зомби!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Гаала, Мальмо и Телоха.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Уф! Прямо гора с плеч! Теперь мы можем разобраться с оставшимися зомби, не боясь новой волны нашествия!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к штейгеру Промокаху на Затерянный пик на Затерянных островах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24946,'Зажигательная смесь','Пигмеи умеют повеселиться – этого у них не отнять! Но вот смекалки им недостает. И, кажется, я знаю, что помогает им отжигать как следует – зажигательная смесь!$B$BОказывается, эта штука не только зажигает звезды на любой вечеринке, но еще и отлично взрывается! Мы должны ее получить!$B$BТак что когда будешь на востоке, в Устане, обязательно прихвати с собой побольше этой смеси. Поверь, она тебе пригодится!','Соберите 5 пригоршней зажигательной смеси.','Вполне достаточно. Если честно, то это даже больше, чем нам нужно. Дело в том, что я изобрела оружие, в которое превратятся эти сапоги, когда ты отдашь их Хобарту.$B$BДавай сюда смесь, загружу ее в реактивные сапоги с суперускорителем.','Хм... Сейчас посмотрим, сколько тебе удалось добыть.','Вернитесь к ассистентке Грили на Затерянный пик на Затерянных островах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зажигательная смесь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пигмеи умеют повеселиться – этого у них не отнять! Но вот смекалки им недостает. И, кажется, я знаю, что помогает им отжигать как следует – зажигательная смесь!$B$BОказывается, эта штука не только зажигает звезды на любой вечеринке, но еще и отлично взрывается! Мы должны ее получить!$B$BТак что когда будешь на востоке, в Устане, обязательно прихвати с собой побольше этой смеси. Поверь, она тебе пригодится!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 5 пригоршней зажигательной смеси.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вполне достаточно. Если честно, то это даже больше, чем нам нужно. Дело в том, что я изобрела оружие, в которое превратятся эти сапоги, когда ты отдашь их Хобарту.$B$BДавай сюда смесь, загружу ее в реактивные сапоги с суперускорителем.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Хм... Сейчас посмотрим, сколько тебе удалось добыть.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ассистентке Грили на Затерянный пик на Затерянных островах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (24947,'Время идет!','Мы не можем просто почивать здесь на лаврах, детка. Нужно постоянно двигаться вперед! Да, люди говорят о нас.$b$bК сожалению, также они говорят и об этой пустоголовой гномке Келси, которая проворачивала свои делишки прямо у нас под носом. Если мы хотим вышвырнуть ее из города, по праву считающегося городом гоблинов, нужно поставить окончательную точку в этом деле.$b$bМы позаботимся о Прибамбасске и сами решим проблему с пиратами. Отправляйся на юг к Бухте Сорванных Парусов, там и встретимся.','Встретьтесь с Мегз Жестекрошшер в Бухте Сорванных Парусов.','Хорошо, что ты здесь! Мне потребуется немало помощи, если мы хотим опередить этих гномов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Время идет!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы не можем просто почивать здесь на лаврах, детка. Нужно постоянно двигаться вперед! Да, люди говорят о нас.$b$bК сожалению, также они говорят и об этой пустоголовой гномке Келси, которая проворачивала свои делишки прямо у нас под носом. Если мы хотим вышвырнуть ее из города, по праву считающегося городом гоблинов, нужно поставить окончательную точку в этом деле.$b$bМы позаботимся о Прибамбасске и сами решим проблему с пиратами. Отправляйся на юг к Бухте Сорванных Парусов, там и встретимся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Встретьтесь с Мегз Жестекрошшер в Бухте Сорванных Парусов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо, что ты здесь! Мне потребуется немало помощи, если мы хотим опередить этих гномов.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (24948,'Снятие блокады','Используйте факел Пакстона, чтобы поджечь 3 катапульты и 1 метатель клинков Грознорева.','Хорошо! Без артиллерии войска Орды должны будут отступить и перегруппироваться. Мы выиграли время, чтобы обеспечить безопасность крепости. Отлично!','Вернитесь к Томасу Пакстону.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Снятие блокады',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте факел Пакстона, чтобы поджечь 3 катапульты и 1 метатель клинков Грознорева.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо! Без артиллерии войска Орды должны будут отступить и перегруппироваться. Мы выиграли время, чтобы обеспечить безопасность крепости. Отлично!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Томасу Пакстону.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (24949,'Трофеи зовут','Расточительность дорого обходится здесь, детка. Эти пираты сидят среди разнообразного ценного барахла и ждут, пока их поймают. Ты можешь поверить, что они просто сидят там и ждут?$b$bЯ имею в виду, зачем же они тогда все это собирают, раз затем просто сидят на золотых горах! Краденые товары должны быть проданы, а на вырученные деньги можно купить много красивых безделушек.$b$bВ любом случае, будь душкой, сходи туда и собери столько добычи, сколько сможешь унести! Чао!','Соберите 10 ящиков с пиратской добычей.','Великолепно! А ведь эти идиоты просто сидели на горе золота.$B$BВот тебе кое-что для начала, детали обговорим позднее.','Вернитесь к Мегз Жестекрошшер в Бухту Сорванных Парусов, что в Танарисе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Трофеи зовут',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Расточительность дорого обходится здесь, детка. Эти пираты сидят среди разнообразного ценного барахла и ждут, пока их поймают. Ты можешь поверить, что они просто сидят там и ждут?$b$bЯ имею в виду, зачем же они тогда все это собирают, раз затем просто сидят на золотых горах! Краденые товары должны быть проданы, а на вырученные деньги можно купить много красивых безделушек.$b$bВ любом случае, будь душкой, сходи туда и собери столько добычи, сколько сможешь унести! Чао!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 ящиков с пиратской добычей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Великолепно! А ведь эти идиоты просто сидели на горе золота.$B$BВот тебе кое-что для начала, детали обговорим позднее.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мегз Жестекрошшер в Бухту Сорванных Парусов, что в Танарисе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (24950,'Капитан "Борода ужаса"','Убейте капитана "Борода Ужаса"','Морские великаны? Ты думаешь, он специально натаскивал их для нападения на Прибамбасск?$B$BА, как бы то ни было – он теперь покойник, а город нам по горло обязан! Скорее бы увидеть выражение лица Марина.$B$BВот твоя доля, детка. Твои дела идут в гору!','Вернитесь к Мегз Жестекрошшер в Бухту Сорванных Парусов, что в Танарисе.','Внуши ему страх.','Капитан "Борода ужаса"') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Капитан "Борода ужаса"',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте капитана "Борода Ужаса"',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Морские великаны? Ты думаешь, он специально натаскивал их для нападения на Прибамбасск?$B$BА, как бы то ни было – он теперь покойник, а город нам по горло обязан! Скорее бы увидеть выражение лица Марина.$B$BВот твоя доля, детка. Твои дела идут в гору!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мегз Жестекрошшер в Бухту Сорванных Парусов, что в Танарисе.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Внуши ему страх.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Капитан "Борода ужаса"',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (24951,'Отличная идея','Теперь, когда у нас есть куча отличного свежего мяса, мы просто привяжем его к этому канату... Готово! Теперь ты сможешь поймать для меня силитида.$b$bЧто? И не смотри на меня так, все совершенно безопасно. Ну, практически безопасно. Ладно, ладно, ты можешь умереть в страшных муках. Но это же так просто! Всего лишь бросишь кусок мяса, подождешь, пока насекомое набросится на него и вытащишь его сюда за веревку!$b$bТвоя задача – найти членистонога, только они охотятся на гиен, и их можно найти в огромном количестве у края ямы.','Поймайте членистонога из улья Хаззали с помощью приманки для жуков.','Ты только посмотри, какой огромный! Превосходно. Этот уродец поможет нам уничтожить целый улей.','Вернитесь к Зеке Волочилкинсу на стоянку бутлегеров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отличная идея',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда у нас есть куча отличного свежего мяса, мы просто привяжем его к этому канату... Готово! Теперь ты сможешь поймать для меня силитида.$b$bЧто? И не смотри на меня так, все совершенно безопасно. Ну, практически безопасно. Ладно, ладно, ты можешь умереть в страшных муках. Но это же так просто! Всего лишь бросишь кусок мяса, подождешь, пока насекомое набросится на него и вытащишь его сюда за веревку!$b$bТвоя задача – найти членистонога, только они охотятся на гиен, и их можно найти в огромном количестве у края ямы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поймайте членистонога из улья Хаззали с помощью приманки для жуков.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты только посмотри, какой огромный! Превосходно. Этот уродец поможет нам уничтожить целый улей.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Зеке Волочилкинсу на стоянку бутлегеров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24952,'Реактивные сапоги','Тебе нужно доставить эти сапоги Хобарту Дреку в кратер.$B$BОни заряжены остатками зажигательной смеси, так что в них хватит мощности на один прыжок.$B$BКогда будешь $gготов:готова;, активируй сапоги. И не волнуйся. Они запрограммированы на безопасную посадку.$B$BНаверное.','Доберитесь до Хобарта Дрека с помощью заряженных зажигательной смесью реактивных сапог.','Нам нельзя терять времени, малыш!$B$BТак, а что с силовым приводом на левом сапоге? Барахлит, кажется.','А вот и ты!','Отдайте заряженные зажигательной смесью реактивные сапоги Хобарту Дреку в Затерянном кратере на Затерянных островах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Реактивные сапоги',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе нужно доставить эти сапоги Хобарту Дреку в кратер.$B$BОни заряжены остатками зажигательной смеси, так что в них хватит мощности на один прыжок.$B$BКогда будешь $gготов:готова;, активируй сапоги. И не волнуйся. Они запрограммированы на безопасную посадку.$B$BНаверное.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доберитесь до Хобарта Дрека с помощью заряженных зажигательной смесью реактивных сапог.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Нам нельзя терять времени, малыш!$B$BТак, а что с силовым приводом на левом сапоге? Барахлит, кажется.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','А вот и ты!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отдайте заряженные зажигательной смесью реактивные сапоги Хобарту Дреку в Затерянном кратере на Затерянных островах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (24953,'Просто хочу избавиться от насекомых','А теперь настало время для кульминации. Мы привяжем к пойманному насекомому столько взрывчатки, сколько оно сможет унести, а невероятная сила мысли Причуденя заставит этого уродца отправиться прямо в центр подземного улья.$b$bА затем... БУМ! Нет больше насекомых!$b$bТебе будет оказана особая честь управлять отвратительным созданием. Иди поговори с Нарайном и подготовь нашего членистоногого друга.','Поговорите с Нарайном Причуденем, чтобы отправить управляемого членистонога в улей Зияющей бездны.','Ох, это было восхитительно! Тебе стоило видеть, как языки пламени вырывались из улья!$B$BВот твоя награда, ты отлично развлек меня!','Вернитесь к Зеке Волочилкинсу на стоянку бутлегеров в Танарис.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Просто хочу избавиться от насекомых',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А теперь настало время для кульминации. Мы привяжем к пойманному насекомому столько взрывчатки, сколько оно сможет унести, а невероятная сила мысли Причуденя заставит этого уродца отправиться прямо в центр подземного улья.$b$bА затем... БУМ! Нет больше насекомых!$b$bТебе будет оказана особая честь управлять отвратительным созданием. Иди поговори с Нарайном и подготовь нашего членистоногого друга.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Нарайном Причуденем, чтобы отправить управляемого членистонога в улей Зияющей бездны.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ох, это было восхитительно! Тебе стоило видеть, как языки пламени вырывались из улья!$B$BВот твоя награда, ты отлично развлек меня!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Зеке Волочилкинсу на стоянку бутлегеров в Танарис.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24954,'Дети бога-черепахи','Вулканот – бог-черепаха, обитающий в пещере. Ему и поклоняются эти... дикари.$B$BНикакой он, конечно, не бог.$B$B<Хобарт закатывает глаза.>$B$BНо он достаточно силен – настолько, что я намерен изобрести для тебя новое оружие, сделав его из единственного нормального сапога, что у нас остался.$B$BЯ думаю, тут вполне подойдет старинное правило: "С огнем борись огнем". Ну, и к тому же мне нравится огонь!$B$BРаздобудь-ка мне несколько огневых желез детей Вулканота. А я пока переделаю наш реактивный сапог в нечто более соответствующее ситуации.','Добудьте 5 огневых желез.','Вернитесь к Хобарту Дреку к Затерянному кратеру на Затерянных островах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дети бога-черепахи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вулканот – бог-черепаха, обитающий в пещере. Ему и поклоняются эти... дикари.$B$BНикакой он, конечно, не бог.$B$B<Хобарт закатывает глаза.>$B$BНо он достаточно силен – настолько, что я намерен изобрести для тебя новое оружие, сделав его из единственного нормального сапога, что у нас остался.$B$BЯ думаю, тут вполне подойдет старинное правило: "С огнем борись огнем". Ну, и к тому же мне нравится огонь!$B$BРаздобудь-ка мне несколько огневых желез детей Вулканота. А я пока переделаю наш реактивный сапог в нечто более соответствующее ситуации.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 5 огневых желез.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хобарту Дреку к Затерянному кратеру на Затерянных островах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (24955,'Без права подписи','Скорее всего, я уже упоминала о том, что пытаюсь сделать так, чтобы эти огры из клана Песчаного молота присоединились к Орде... Картелю Трюмных Вод пригодилась бы столь дешевая рабочая сила.$b$bДля того, чтобы справиться с этой задачей, прежде всего нужно достичь устных договоренностей о начале процесса и все такое прочее, иначе я рискую получить хорошую взбучку. Так что я подготовила вот этот документ, который позволит без лишних формальностей перейти к подписанию временного рабочего контракта.$b$bУ меня есть маскировочный костюм для тебя, так что надевай его и собери столько подписей, сколько нужно.','Соберите 10 подписей огров из клана Песчаного молота.','Ух ты, отличная работа! Поразительно, что ты смог научить их держать ручку, а не проглатывать ее целиком.$B$BКостюм, хм, выбрось здесь где-нибудь. Подальше от меня. Брось в костер.','Вернитесь к Мегз Жестекрошшер в Вербовочный лагерь Песчаного Молота, что в Танарисе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Без права подписи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Скорее всего, я уже упоминала о том, что пытаюсь сделать так, чтобы эти огры из клана Песчаного молота присоединились к Орде... Картелю Трюмных Вод пригодилась бы столь дешевая рабочая сила.$b$bДля того, чтобы справиться с этой задачей, прежде всего нужно достичь устных договоренностей о начале процесса и все такое прочее, иначе я рискую получить хорошую взбучку. Так что я подготовила вот этот документ, который позволит без лишних формальностей перейти к подписанию временного рабочего контракта.$b$bУ меня есть маскировочный костюм для тебя, так что надевай его и собери столько подписей, сколько нужно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 подписей огров из клана Песчаного молота.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ух ты, отличная работа! Поразительно, что ты смог научить их держать ручку, а не проглатывать ее целиком.$B$BКостюм, хм, выбрось здесь где-нибудь. Подальше от меня. Брось в костер.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мегз Жестекрошшер в Вербовочный лагерь Песчаного Молота, что в Танарисе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (24956,'Уничтожение Грознорева','Убейте 4 лейтенантов Грознорева и добудьте шлем Грознорева, убив Кэргу Грознорева.','<Толливер почтительно берет шлем дрожащими руками.>$B$BБоевые корабли Грознорева перехватили наше судно, когда мы бежали из Гилнеаса. Нас собирались предъявить их вождю, как трофеи. Когда мы приблизились к берегу, некоторые из нас дали отпор. Грознорев убивал без разбора, заходясь от смеха. Наш корабль перевернулся, и он приказал стрелять в нас, пока мы тонули. Немногие из нас смогли добраться до земли.$B$BА потом я узнал, что он носил скальп моего брата как... как трофей.$B$B<Он закрывает глаза.>','Он мертв? Ты принесла его... Шлем?','Принесите шлем Толливеру Песьему Зубу.','Убей Кэргу Грознорева. Берегись его приспешников.','Кэрга Грознорев') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уничтожение Грознорева',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 4 лейтенантов Грознорева и добудьте шлем Грознорева, убив Кэргу Грознорева.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Толливер почтительно берет шлем дрожащими руками.>$B$BБоевые корабли Грознорева перехватили наше судно, когда мы бежали из Гилнеаса. Нас собирались предъявить их вождю, как трофеи. Когда мы приблизились к берегу, некоторые из нас дали отпор. Грознорев убивал без разбора, заходясь от смеха. Наш корабль перевернулся, и он приказал стрелять в нас, пока мы тонули. Немногие из нас смогли добраться до земли.$B$BА потом я узнал, что он носил скальп моего брата как... как трофей.$B$B<Он закрывает глаза.>',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Он мертв? Ты принесла его... Шлем?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите шлем Толливеру Песьему Зубу.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Убей Кэргу Грознорева. Берегись его приспешников.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Кэрга Грознорев',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24957,'Найди себе сентипаару','Соберите 20 сентипаар с силитидов-сентипааров.','Фу! Это не лагерь, а какое-то скопище ужасных запахов!$B$BНе думаю, что нам стоит долго тут находиться.','Достаточно собрал? Не думаю, что эти огры любители небольших порций.','Вернитесь к Мегз Жестекрошшер в Вербовочный лагерь Песчаного Молота, что в Танарисе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Найди себе сентипаару',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 20 сентипаар с силитидов-сентипааров.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Фу! Это не лагерь, а какое-то скопище ужасных запахов!$B$BНе думаю, что нам стоит долго тут находиться.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Достаточно собрал? Не думаю, что эти огры любители небольших порций.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мегз Жестекрошшер в Вербовочный лагерь Песчаного Молота, что в Танарисе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (24958,'Вулканот!','Это стоило мне литров крови, пота и слез, но моя запатентованная ботзука наконец-то готова!$B$BНичтожные пигмеи скармливают представителей нашего народа своему "богу" – Вулканоту – и собираются напустить его прямо на наш город!$B$BТы $gдолжен:должна; пойти в пещеру и убить эту тварь, пока не поздно!','Убейте Вулканота с помощью ботзуки.','Остальные уже в городе.$B$BЗапрыгивай, нам нужно убираться отсюда, пока вулкан не разнес тут все в клочья!!!','Поговорите с Хамми Кофельнагель в ветролете в пещере Вулканота на Затерянных островах.','Воспользуйся ботзукой, чтобы справиться с этим чудовищем!!!','Вулканот') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вулканот!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это стоило мне литров крови, пота и слез, но моя запатентованная ботзука наконец-то готова!$B$BНичтожные пигмеи скармливают представителей нашего народа своему "богу" – Вулканоту – и собираются напустить его прямо на наш город!$B$BТы $gдолжен:должна; пойти в пещеру и убить эту тварь, пока не поздно!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Вулканота с помощью ботзуки.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Остальные уже в городе.$B$BЗапрыгивай, нам нужно убираться отсюда, пока вулкан не разнес тут все в клочья!!!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Хамми Кофельнагель в ветролете в пещере Вулканота на Затерянных островах.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Воспользуйся ботзукой, чтобы справиться с этим чудовищем!!!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Вулканот',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (24959,'Только что из могилы','$n!$b$bПоднимайся, $n!$b$bС возвращением в мир живых. С помощью благословения и силы Темной Госпожи я вырвала тебя из лап смерти.$b$bНо ты не в рабстве, $n. Только тебе решать, какой путь выбрать дальше. Если захочешь служить леди Сильване, я советую тебе поговорить с гробовщиком Мордо. Ты найдешь его на кладбище, позади меня.','Поговорите с гробовщиком Мордо в Похоронном Звоне, что в Тирисфальских лесах.','Привет-привет! Ты, должно быть... $n?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Только что из могилы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n!$b$bПоднимайся, $n!$b$bС возвращением в мир живых. С помощью благословения и силы Темной Госпожи я вырвала тебя из лап смерти.$b$bНо ты не в рабстве, $n. Только тебе решать, какой путь выбрать дальше. Если захочешь служить леди Сильване, я советую тебе поговорить с гробовщиком Мордо. Ты найдешь его на кладбище, позади меня.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с гробовщиком Мордо в Похоронном Звоне, что в Тирисфальских лесах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Привет-привет! Ты, должно быть... $n?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24960,'Пробуждение','$gКороль:Королева;, $gкрестьянин:крестьянка;, |3-6($c)... Мне без разницы, кем ты $gбыл:была; раньше. Мне просто нужен кто-то, у кого язык работает.$b$bБыть поднятым из могилы тяжело. Не все чувствуют себя в этой новой жизни так же хорошо, как ты. В частности, прямо сейчас у нас есть трое новеньких, у которых, похоже, проблемы.$b$bРазыщи их и поговори с ними. Может быть, им просто нужно с кем-то поделиться.$b$bТы найдешь их на кладбище.','Поговорите с маршалом Редпатом, Лилиан Восс и Валдредом Мораем.','Вернитесь к смотрителю Кайсу в Похоронный Звон, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пробуждение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$gКороль:Королева;, $gкрестьянин:крестьянка;, |3-6($c)... Мне без разницы, кем ты $gбыл:была; раньше. Мне просто нужен кто-то, у кого язык работает.$b$bБыть поднятым из могилы тяжело. Не все чувствуют себя в этой новой жизни так же хорошо, как ты. В частности, прямо сейчас у нас есть трое новеньких, у которых, похоже, проблемы.$b$bРазыщи их и поговори с ними. Может быть, им просто нужно с кем-то поделиться.$b$bТы найдешь их на кладбище.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с маршалом Редпатом, Лилиан Восс и Валдредом Мораем.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к смотрителю Кайсу в Похоронный Звон, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24961,'Замогильная правда','Не так давно я видела, как молодая Отрекшаяся бежала в сторону старой таверны. Она вопила что есть мочи и молила, чтобы ее забрали домой.$B$BНе все из нас могут похвастаться должной выдержкой, $n. Однако мы должны смириться с тем, что стали нежитью, если хотим одержать верх над нашими врагами.$B$BВозьми мое зеркальце и покажи его той девушке. Она должна увидеть, кто она на самом деле, – тогда она сможет к нам присоединиться. Кроме того... лишнее тело тоже не помешает.','Дайте карманное зеркальце Элрет Лилиан Восс в Похоронном Звоне.','Вернитесь к новобранцу Элрет в Похоронный Звон, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Замогильная правда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не так давно я видела, как молодая Отрекшаяся бежала в сторону старой таверны. Она вопила что есть мочи и молила, чтобы ее забрали домой.$B$BНе все из нас могут похвастаться должной выдержкой, $n. Однако мы должны смириться с тем, что стали нежитью, если хотим одержать верх над нашими врагами.$B$BВозьми мое зеркальце и покажи его той девушке. Она должна увидеть, кто она на самом деле, – тогда она сможет к нам присоединиться. Кроме того... лишнее тело тоже не помешает.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Дайте карманное зеркальце Элрет Лилиан Восс в Похоронном Звоне.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к новобранцу Элрет в Похоронный Звон, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (24962,'Истрепавшийся свиток','Пока ты $gразбирался:разбиралась; с безмозглыми тварями, тебе тут свиток пришел. Думаю, там говорится о чем-то важном – на свитке печать самого Ксавьера, учителя охотников. Я бы на твоем месте немедленно ознакомился с этим посланием.','Прочитайте истрепавшийся свиток и поговорите с ловчим Ксавьером в Похоронном Звоне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Истрепавшийся свиток',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пока ты $gразбирался:разбиралась; с безмозглыми тварями, тебе тут свиток пришел. Думаю, там говорится о чем-то важном – на свитке печать самого Ксавьера, учителя охотников. Я бы на твоем месте немедленно ознакомился с этим посланием.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Прочитайте истрепавшийся свиток и поговорите с ловчим Ксавьером в Похоронном Звоне.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24963,'Убей их нежно','Итак, послушай. Есть два способа заставить людей делать то, что тебе нужно. Можно обеспечить человека тем, что он хочет – товарами, услугами, чем угодно еще. Или можно избить его до полусмерти.$b$bЧасто оказывается, что совмещение первого и второго подходов более эффективно, а ты теперь отлично $gзнаком:знакома; с обоими методами. Возьми эти угощения из силитидов, пойди и вышиби дух из некоторых огров, а затем предложи им лакомство прежде, чем нанесешь последний удар. Все ясно?','Скормите кусочки лакомства на пробу от картеля Трюмных Вод 8 избитым до полусмерти ограм.','Вернитесь к Мегз Жестекрошшер в Вербовочный лагерь Песчаного Молота, что в Танарисе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Убей их нежно',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Итак, послушай. Есть два способа заставить людей делать то, что тебе нужно. Можно обеспечить человека тем, что он хочет – товарами, услугами, чем угодно еще. Или можно избить его до полусмерти.$b$bЧасто оказывается, что совмещение первого и второго подходов более эффективно, а ты теперь отлично $gзнаком:знакома; с обоими методами. Возьми эти угощения из силитидов, пойди и вышиби дух из некоторых огров, а затем предложи им лакомство прежде, чем нанесешь последний удар. Все ясно?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Скормите кусочки лакомства на пробу от картеля Трюмных Вод 8 избитым до полусмерти ограм.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мегз Жестекрошшер в Вербовочный лагерь Песчаного Молота, что в Танарисе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (24970,'Не лучше зомби','Пока ты $gбыл:была; в пещере, приходил твой друг Дарнелл, принес тревожные новости.$b$bПосле появления валь\'кир все больше и больше нежити отказываются присоединиться к нам и воевать под знаменами Темной Госпожи. Они разбили небольшой лагерь тут в долине и теперь собирают силы.$b$bИх план – напасть на Похоронный Звон, |3-6($c).$b$bДарнелл ушел по дороге, ведущей на восток. Будь $gосторожен:осторожна;, $n. Мозги у этой нежити, конечно, остались, но работают они порой странно.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Не лучше зомби',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пока ты $gбыл:была; в пещере, приходил твой друг Дарнелл, принес тревожные новости.$b$bПосле появления валь\'кир все больше и больше нежити отказываются присоединиться к нам и воевать под знаменами Темной Госпожи. Они разбили небольшой лагерь тут в долине и теперь собирают силы.$b$bИх план – напасть на Похоронный Звон, |3-6($c).$b$bДарнелл ушел по дороге, ведущей на восток. Будь $gосторожен:осторожна;, $n. Мозги у этой нежити, конечно, остались, но работают они порой странно.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (24971,'Нападение на лагерь гнилодумов','Убейте маршала Редпата и 8 гнилодумов-нежитей.','Быть после смерти возрожденным валь\'кирами нелегко. Многие не могут перенести шока и превращаются в зомби или вурдалаков.$b$bВ некоторых человечности остается столько, чтобы казаться нормальными лишь на вид… но при этом изнутри они больны. Этих гнилодумов надо убивать сразу же, в тот же день, когда они возвращаются к жизни.$b$bЧто касается тебя... ты – сильный $c. Я знаю, что с тобой все будет в порядке. Скоро ты покинешь Похоронный Звон.','Вернитесь к палачу Аррену в Похоронный Звон в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нападение на лагерь гнилодумов',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте маршала Редпата и 8 гнилодумов-нежитей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Быть после смерти возрожденным валь\'кирами нелегко. Многие не могут перенести шока и превращаются в зомби или вурдалаков.$b$bВ некоторых человечности остается столько, чтобы казаться нормальными лишь на вид… но при этом изнутри они больны. Этих гнилодумов надо убивать сразу же, в тот же день, когда они возвращаются к жизни.$b$bЧто касается тебя... ты – сильный $c. Я знаю, что с тобой все будет в порядке. Скоро ты покинешь Похоронный Звон.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к палачу Аррену в Похоронный Звон в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (24972,'Важные разведданные','<Из своего одеяния Сарвис достает листок бумаги.>$b$bЭто необходимо передать моему разведчику, стражу смерти Симмеру. Это информация о местопребывании тех, кто остался от Алого ордена. Мы их уничтожим, всех до единого. И у меня есть ощущение, что ты сможешь это сделать, $n.$b$bВыходи из Похоронного Звона по дороге, ведущей на север. Вскоре после того, как дойдешь до Тирисфаля, увидишь большой дом. Симмер в нем.','Отнесите бумаги Алого ордена стражу смерти Симмеру в поместье Калстона, что в Тирисфальских лесах.','Да? Что тебе нужно?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Важные разведданные',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Из своего одеяния Сарвис достает листок бумаги.>$b$bЭто необходимо передать моему разведчику, стражу смерти Симмеру. Это информация о местопребывании тех, кто остался от Алого ордена. Мы их уничтожим, всех до единого. И у меня есть ощущение, что ты сможешь это сделать, $n.$b$bВыходи из Похоронного Звона по дороге, ведущей на север. Вскоре после того, как дойдешь до Тирисфаля, увидишь большой дом. Симмер в нем.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите бумаги Алого ордена стражу смерти Симмеру в поместье Калстона, что в Тирисфальских лесах.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да? Что тебе нужно?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (24973,'Паучья низина','Одна из наших самых серьезных проблем – это добыча природных ресурсов, необходимых для выживания. Золота в Лордероне было очень мало даже много лет назад, во времена расцвета власти Альянса.$b$bК северо-западу отсюда есть золотой рудник, но он весь кишит пауками. Нам нужно золото из рудника, но мы не можем его добывать, пока там везде бегают эти членистоногие твари. У меня не так много рабочих рук для этой задачи, так что придется действовать постепенно. $b$bОтправляйся туда – может быть, ты сможешь чем-то помочь нам, $n.','Убейте 8 молодых ночных кругопрядов и 5 ночных кругопрядов.','Ну что же, для начала неплохо. Очистка всей территории займет несколько недель или даже месяцев. А после этого нам придется пойти туда с факелами, чтобы сжечь паутину.$b$bТы отлично $gсправился:справилась;, $n.','Вернитесь к палачу Аррену в Похоронный Звон, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Паучья низина',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Одна из наших самых серьезных проблем – это добыча природных ресурсов, необходимых для выживания. Золота в Лордероне было очень мало даже много лет назад, во времена расцвета власти Альянса.$b$bК северо-западу отсюда есть золотой рудник, но он весь кишит пауками. Нам нужно золото из рудника, но мы не можем его добывать, пока там везде бегают эти членистоногие твари. У меня не так много рабочих рук для этой задачи, так что придется действовать постепенно. $b$bОтправляйся туда – может быть, ты сможешь чем-то помочь нам, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 молодых ночных кругопрядов и 5 ночных кругопрядов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну что же, для начала неплохо. Очистка всей территории займет несколько недель или даже месяцев. А после этого нам придется пойти туда с факелами, чтобы сжечь паутину.$b$bТы отлично $gсправился:справилась;, $n.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к палачу Аррену в Похоронный Звон, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24974,'Невыносимое одиночество','Вот представь: работаешь ты усердно всю свою жизнь – и что потом? Умираешь от чумы, переходишь в ряды нежити, работаешь еще усердней. А потом что? Да, накопишь деньжат, купишь небольшой домик, познакомишься с парочкой надоедливых соседей... А счастье? Его-то впрок не напасешься.$b$bЯ чувствую себя одиноким стариком, $n. Мне нужен спутник. Вот, возьми этот поводок и приведи мне одного из мурлоков с Шепчущего берега на северо-западе. Запомни: пока мурлок полон сил, он не даст накинуть на себя поводок. Поэтому тебе придется сначала измотать его, а потом уже привести ко мне.','Накиньте поводок на мурлока из племени Злобного Плавника, а затем приведите его Седрику Калстону в поместье Калстона.','Вернитесь к Седрику Калстону в поместье Калстона, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Невыносимое одиночество',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот представь: работаешь ты усердно всю свою жизнь – и что потом? Умираешь от чумы, переходишь в ряды нежити, работаешь еще усердней. А потом что? Да, накопишь деньжат, купишь небольшой домик, познакомишься с парочкой надоедливых соседей... А счастье? Его-то впрок не напасешься.$b$bЯ чувствую себя одиноким стариком, $n. Мне нужен спутник. Вот, возьми этот поводок и приведи мне одного из мурлоков с Шепчущего берега на северо-западе. Запомни: пока мурлок полон сил, он не даст накинуть на себя поводок. Поэтому тебе придется сначала измотать его, а потом уже привести ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Накиньте поводок на мурлока из племени Злобного Плавника, а затем приведите его Седрику Калстону в поместье Калстона.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Седрику Калстону в поместье Калстона, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24975,'Поля Горя','Кто это тут? $gНовенький:Новенькая:c; |3-6($c)? Если хочешь проявить себя перед Темной Госпожой, придется следовать обычаям Отрекшихся.$B$BК западу отсюда есть ферма. Люди растекаются по этой земле, как плесень по трупу. К тому же Алый орден постоянно ходит дозором возле своей башни. Преподай этим ничтожествам урок и укради у них десять их драгоценных тыкв.$B$BКак наберешь десяток, неси их сюда.','Украдите 10 тыкв с усадьбы Соллиден в Тирисфальских лесах.','Ну что, уже насобирала десяток?','Вернитесь к аптекарю Юхану в поместье Калстона, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поля Горя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кто это тут? $gНовенький:Новенькая:c; |3-6($c)? Если хочешь проявить себя перед Темной Госпожой, придется следовать обычаям Отрекшихся.$B$BК западу отсюда есть ферма. Люди растекаются по этой земле, как плесень по трупу. К тому же Алый орден постоянно ходит дозором возле своей башни. Преподай этим ничтожествам урок и укради у них десять их драгоценных тыкв.$B$BКак наберешь десяток, неси их сюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Украдите 10 тыкв с усадьбы Соллиден в Тирисфальских лесах.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, уже насобирала десяток?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к аптекарю Юхану в поместье Калстона, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24976,'Разнообразие – вот что придает вкус смерти','Найдите 4 кабачковых цвета, 4 побега ксавренова терна и 8 соленых морских огурцов.','Вернитесь к аптекарю Юхану в поместье Калстона, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разнообразие – вот что придает вкус смерти',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите 4 кабачковых цвета, 4 побега ксавренова терна и 8 соленых морских огурцов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к аптекарю Юхану в поместье Калстона, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24977,'Эксперимент Юхана','Безвредные тыковки, да? Это только так кажется. Если мы хотим победить силы Плети на севере и нашествие людей на юге, нам нужно извлечь всю пользу из нашего дара нежития.$B$BНемного смекалки, и простая тыква превратится в шпиона Темной Госпожи. С помощью моей последней формулы эта тыква станет лакомым блюдом.$B$BВот недавно мы поймали еще одного ревнителя Алого ордена, сейчас он снаружи, возле беседки. Иди, отнеси ему эту тыкву.','Отнесите отравленную тыкву пленному ревнителю Алого ордена в поместье Калстона.','Благословенный Свет! Наконец-то еда! Сладенькая тыквочка...','Прочь, нечестивое создание! Свет, защити меня! Алый орден избавит Азерот от таких...$B$BОй... Это что, еда для меня? Я умираю с голода...','Вернитесь к пленному ревнителю Алого ордена в Западные Чумные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Эксперимент Юхана',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Безвредные тыковки, да? Это только так кажется. Если мы хотим победить силы Плети на севере и нашествие людей на юге, нам нужно извлечь всю пользу из нашего дара нежития.$B$BНемного смекалки, и простая тыква превратится в шпиона Темной Госпожи. С помощью моей последней формулы эта тыква станет лакомым блюдом.$B$BВот недавно мы поймали еще одного ревнителя Алого ордена, сейчас он снаружи, возле беседки. Иди, отнеси ему эту тыкву.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите отравленную тыкву пленному ревнителю Алого ордена в поместье Калстона.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Благословенный Свет! Наконец-то еда! Сладенькая тыквочка...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Прочь, нечестивое создание! Свет, защити меня! Алый орден избавит Азерот от таких...$B$BОй... Это что, еда для меня? Я умираю с голода...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к пленному ревнителю Алого ордена в Западные Чумные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24978,'Урожай фермеров','Люди – очень ненадежные создания. Фермеры к западу отсюда не исключение. Сегодня они мирно возделывают свои поля, а завтра вооружатся косами и пойдут против нас. Силы Альянса совсем недалеко, в Гилнеасе, а к югу простираются владения Штормграда... И те, и другие могут завербовать земледельцев и нанести нам удар.$b$bПоэтому фермерам придется умереть. Проследи за этим.','Убейте 10 тирисфальских фермеров или батраков.','Вернитесь к стражу смерти Симмеру в поместье Калстона, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Урожай фермеров',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Люди – очень ненадежные создания. Фермеры к западу отсюда не исключение. Сегодня они мирно возделывают свои поля, а завтра вооружатся косами и пойдут против нас. Силы Альянса совсем недалеко, в Гилнеасе, а к югу простираются владения Штормграда... И те, и другие могут завербовать земледельцев и нанести нам удар.$b$bПоэтому фермерам придется умереть. Проследи за этим.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 тирисфальских фермеров или батраков.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к стражу смерти Симмеру в поместье Калстона, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24979,'Письмо Алого ордена','Лейтенант Геблер:$b$bЗанятно, что вы решили взять пленницу... к тому же из числа нежити. О чем вы думали? Можно подумать, бывший статус помог бы ей увильнуть от законов Алого ордена.$b$bЭто волнует меня больше всего, Геблер. Хочу напомнить, что за такое поведение существует определенное наказание. Приказываю вам немедленно казнить ее – она больше не одна из нас.','Разыщите пленницу в Палисаде Алого ордена.','Алый орден не берет пленных. Но для этой девушки сделали исключение… интересно.$B$BНо то, на что она способна, интересней в сто крат. Она прошла сквозь тюремную решетку и убила стража? Почему она сразу этого не сделала?','Письмо? Что в нем?','Сообщите о своих находках стражу смерти Симмеру в поместье Калстона, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Письмо Алого ордена',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Лейтенант Геблер:$b$bЗанятно, что вы решили взять пленницу... к тому же из числа нежити. О чем вы думали? Можно подумать, бывший статус помог бы ей увильнуть от законов Алого ордена.$b$bЭто волнует меня больше всего, Геблер. Хочу напомнить, что за такое поведение существует определенное наказание. Приказываю вам немедленно казнить ее – она больше не одна из нас.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите пленницу в Палисаде Алого ордена.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Алый орден не берет пленных. Но для этой девушки сделали исключение… интересно.$B$BНо то, на что она способна, интересней в сто крат. Она прошла сквозь тюремную решетку и убила стража? Почему она сразу этого не сделала?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Письмо? Что в нем?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Сообщите о своих находках стражу смерти Симмеру в поместье Калстона, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24980,'Палисад Алого ордена','Нам нужен кто-то такой же "инициативный", как ты, чтобы навсегда покончить с Алым орденом. $B$BДокажи мне, что ты $Gдостоин:достойна; служить Темной Госпоже: отправляйся на запад, к башне за усадьбой Соллиден, и убей 10 воинов из Алого ордена.','Убейте 10 воинов Алого ордена.','Вернитесь к стражу смерти Симмеру в поместье Калстона, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Палисад Алого ордена',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нам нужен кто-то такой же "инициативный", как ты, чтобы навсегда покончить с Алым орденом. $B$BДокажи мне, что ты $Gдостоин:достойна; служить Темной Госпоже: отправляйся на запад, к башне за усадьбой Соллиден, и убей 10 воинов из Алого ордена.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 воинов Алого ордена.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к стражу смерти Симмеру в поместье Калстона, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24981,'Источник неприятностей','В документах палача Аррена из Похоронного Звона содержится информация, необходимая нам для того, чтобы истребить всех людей в наших землях. Судя по этим данным, Алый орден прислал в разрушенную башню на юго-западе от Брилла капитана Перрина с людьми.$B$BУбей 3 ревнителей и 3 миссионеров из его отряда, а заодно постарайся узнать, что они там затевают.','Убейте 3 ревнителей и 3 миссионеров Алого ордена и найдите послание.','Кажется, нам придется держать ухо востро с этой Восс. Не думаю, что Отрекшиеся получат награду, если ее поймают… Я просто опасаюсь, что в один прекрасный момент она станет играть против нас.','Когда-нибудь мы вырежем весь этот Алый орден, как скотов.','Вернитесь к палачу Зуганду в Брилл, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Источник неприятностей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В документах палача Аррена из Похоронного Звона содержится информация, необходимая нам для того, чтобы истребить всех людей в наших землях. Судя по этим данным, Алый орден прислал в разрушенную башню на юго-западе от Брилла капитана Перрина с людьми.$B$BУбей 3 ревнителей и 3 миссионеров из его отряда, а заодно постарайся узнать, что они там затевают.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 3 ревнителей и 3 миссионеров Алого ордена и найдите послание.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Кажется, нам придется держать ухо востро с этой Восс. Не думаю, что Отрекшиеся получат награду, если ее поймают… Я просто опасаюсь, что в один прекрасный момент она станет играть против нас.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Когда-нибудь мы вырежем весь этот Алый орден, как скотов.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к палачу Зуганду в Брилл, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (24982,'Новые Отрекшиеся','Честно говоря, прежние Отрекшиеся были группой жалких слюнтяев. Мы ютились в старых, обветшалых человеческих домах, прятались от Плети и ползали в ногах у Орды.$b$bА сейчас посмотри вокруг – перед тобой поколение новых Отрекшихся. Мы заявили о себе здесь, в Азероте, и не собираемся останавливаться на достигнутом. Скоро весь мир склонится перед нами!$b$bХочешь дам тебе совет? Поговори с мировым судьей Севреном в Брилле. Он в городе главный. Дорога приведет тебя прямо туда.','Поговорите с мировым судьей Севреном в Брилле, что в Тирисфальских лесах.','Да, я являюсь мировым судьей Брилла и докладываю о делах непосредственно Темной Госпоже. Удиви меня, и, возможно, тебе посчастливится увидеть саму королеву банши. Итак, твое первое задание…') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новые Отрекшиеся',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Честно говоря, прежние Отрекшиеся были группой жалких слюнтяев. Мы ютились в старых, обветшалых человеческих домах, прятались от Плети и ползали в ногах у Орды.$b$bА сейчас посмотри вокруг – перед тобой поколение новых Отрекшихся. Мы заявили о себе здесь, в Азероте, и не собираемся останавливаться на достигнутом. Скоро весь мир склонится перед нами!$b$bХочешь дам тебе совет? Поговори с мировым судьей Севреном в Брилле. Он в городе главный. Дорога приведет тебя прямо туда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с мировым судьей Севреном в Брилле, что в Тирисфальских лесах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, я являюсь мировым судьей Брилла и докладываю о делах непосредственно Темной Госпоже. Удиви меня, и, возможно, тебе посчастливится увидеть саму королеву банши. Итак, твое первое задание…',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (24983,'Обязанности Отрекшихся','Мне нужен свежий отчет с восточной базы наших стражей смерти.$B$BЯ хочу знать, не проникли ли новые силы Плети за Бастион, в Тирисфаль. На границе с Чумными землями нужно постоянно смотреть в оба! Нельзя, чтобы Плеть устроила здесь еще одну крепость.$B$BИди по дороге на юг, а на развилке сверни на восток, к базе. Поговори со стражем смерти Линнеей, у нее есть вся нужная мне информация.','Поговорите с Линнеей в Лагере стражей смерти в Тирисфальских лесах.','Севрену нужен отчет? Ну что же, защитники Бастиона сдерживают силы Плети, но часть из них все же проникает время от времени.$B$BПлеть видели к востоку от нашей базы, возле усадьбы Балнира.','Вернитесь к стражу смерти Линне в Западные Чумные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обязанности Отрекшихся',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне нужен свежий отчет с восточной базы наших стражей смерти.$B$BЯ хочу знать, не проникли ли новые силы Плети за Бастион, в Тирисфаль. На границе с Чумными землями нужно постоянно смотреть в оба! Нельзя, чтобы Плеть устроила здесь еще одну крепость.$B$BИди по дороге на юг, а на развилке сверни на восток, к базе. Поговори со стражем смерти Линнеей, у нее есть вся нужная мне информация.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Линнеей в Лагере стражей смерти в Тирисфальских лесах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Севрену нужен отчет? Ну что же, защитники Бастиона сдерживают силы Плети, но часть из них все же проникает время от времени.$B$BПлеть видели к востоку от нашей базы, возле усадьбы Балнира.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к стражу смерти Линне в Западные Чумные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (24984,'Блудный лич','Давным-давно Гюнтер Чародей, Бетор Ледострел и Тул Коготь Ворона, который стал теперь некромантом Плети, дружили и состояли в Кирин-Торе – сообществе магов Даларана.$B$BГюнтер пал жертвой Чумы, но мы полагали, что он так и сгинул в небытие или встал под знамена Короля-лича. Нам стало известно, что он остался свободным.$B$BМы должны привлечь его на свою сторону. Его можно найти на острове посреди озера Ясноводного, что к востоку отсюда. Убеди его присоединиться к нам.','Поговорите с Гюнтером Чародеем в Приюте Гюнтера, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Блудный лич',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Давным-давно Гюнтер Чародей, Бетор Ледострел и Тул Коготь Ворона, который стал теперь некромантом Плети, дружили и состояли в Кирин-Торе – сообществе магов Даларана.$B$BГюнтер пал жертвой Чумы, но мы полагали, что он так и сгинул в небытие или встал под знамена Короля-лича. Нам стало известно, что он остался свободным.$B$BМы должны привлечь его на свою сторону. Его можно найти на острове посреди озера Ясноводного, что к востоку отсюда. Убеди его присоединиться к нам.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Гюнтером Чародеем в Приюте Гюнтера, что в Тирисфальских лесах.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24985,'Доказательство преданности','Хорошо. Я принимаю эту игру, но только потому, что чувствую в тебе... превосходство. Но прежде чем я поверю тебе, ты $gдолжен:должна; доказать, что являешься врагом Плети.$B$BНа южном берегу этого острова находится старый окровавленный алтарь, которым пользуется адепт Плети – Лилит Нефара.$B$BВозьми из этого ящика манящую свечу, зажги ее на алтаре, и Лилит пробудится. Убей ее, и я поверю, что ты – $gсоюзник:союзница;.','Найдите манящую свечу.$B$Bпризовите Лилит Нефару и убейте ее.','Вернитесь к Гюнтеру Чародею в приют Гюнтера в Тирисфальские леса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Доказательство преданности',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хорошо. Я принимаю эту игру, но только потому, что чувствую в тебе... превосходство. Но прежде чем я поверю тебе, ты $gдолжен:должна; доказать, что являешься врагом Плети.$B$BНа южном берегу этого острова находится старый окровавленный алтарь, которым пользуется адепт Плети – Лилит Нефара.$B$BВозьми из этого ящика манящую свечу, зажги ее на алтаре, и Лилит пробудится. Убей ее, и я поверю, что ты – $gсоюзник:союзница;.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите манящую свечу.$B$Bпризовите Лилит Нефару и убейте ее.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гюнтеру Чародею в приют Гюнтера в Тирисфальские леса.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24986,'Возвращение блудного лича','Отнеси этот самоцвет Пустоты моему старому товарищу Бетору, который обитает в Подгороде. С его помощью мы сможем общаться, а мне очень многое надо ему сказать.','Отнесите самоцвет Пустоты Бетору Ледострелу в Подгород.','Вернитесь к Бетору Ледострелу в Западные Чумные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение блудного лича',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Отнеси этот самоцвет Пустоты моему старому товарищу Бетору, который обитает в Подгороде. С его помощью мы сможем общаться, а мне очень многое надо ему сказать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите самоцвет Пустоты Бетору Ледострелу в Подгород.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бетору Ледострелу в Западные Чумные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (24987,'Благоволение Темной Госпожи') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Благоволение Темной Госпожи',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24988,'Смертельный холод','Так холодно... Чума нежити расползается по моим венам, как клубок ледяных змеев, и скоро я впаду в беспамятство. Но никакой злой рок не помешает мне нести службу нашей Темной Госпоже. Когда прозвучал зов, я шила мешки для павших солдат великой армии Сильваны.$B$BТеперь мои руки дрожат от холода. Если ты принесешь мне пять шкурок сумеречницы, я сошью себе одеяло. Помоги мне, $n, чтобы я могла и дальше служить нашему делу.','Добудьте 5 шкурок сумеречницы.','Вернитесь к Гретхен Дедмар в Лагерь стражей смерти, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Смертельный холод',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Так холодно... Чума нежити расползается по моим венам, как клубок ледяных змеев, и скоро я впаду в беспамятство. Но никакой злой рок не помешает мне нести службу нашей Темной Госпоже. Когда прозвучал зов, я шила мешки для павших солдат великой армии Сильваны.$B$BТеперь мои руки дрожат от холода. Если ты принесешь мне пять шкурок сумеречницы, я сошью себе одеяло. Помоги мне, $n, чтобы я могла и дальше служить нашему делу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 5 шкурок сумеречницы.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гретхен Дедмар в Лагерь стражей смерти, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (24989,'Возвращение к мировому судье','Теперь возвращайся к мировому судье Севрену с той информацией, которую я тебе дала. Он очень ждет ее, так что поспеши.','Вернитесь к мировому судье Севрену в Брилл.','Неприятно слышать, что Плеть просачивается через Бастион. Даже теперь они не прекращают своих атак.$B$BНо мы не уступим. Король Лич мертв, и мы не позволим снова захватить нас!','Вернитесь к мировому судье Севрену в Западные Чумные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение к мировому судье',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь возвращайся к мировому судье Севрену с той информацией, которую я тебе дала. Он очень ждет ее, так что поспеши.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь к мировому судье Севрену в Брилл.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Неприятно слышать, что Плеть просачивается через Бастион. Даже теперь они не прекращают своих атак.$B$BНо мы не уступим. Король Лич мертв, и мы не позволим снова захватить нас!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мировому судье Севрену в Западные Чумные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24990,'Смерть от псов Тьмы','Леди Сильвана обратилась к Королевскому фармацевтическому обществу. Она хочет, чтобы мы вывели новую чуму – смертоноснее любой другой болезни, существующей в Азероте, чтобы она уничтожила всех наших врагов, живых и мертвых.$B$BВ своих изысканиях я обнаружил, что для этого потребуется кровь животных. Наполни эти сосуды кровью псов Тьмы, чтобы я мог провести эксперимент.','Наполните 5 сосудов кровью псов Тьмы.','Вернитесь к младшему аптекарю Холланду в Брилл, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Смерть от псов Тьмы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Леди Сильвана обратилась к Королевскому фармацевтическому обществу. Она хочет, чтобы мы вывели новую чуму – смертоноснее любой другой болезни, существующей в Азероте, чтобы она уничтожила всех наших врагов, живых и мертвых.$B$BВ своих изысканиях я обнаружил, что для этого потребуется кровь животных. Наполни эти сосуды кровью псов Тьмы, чтобы я мог провести эксперимент.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Наполните 5 сосудов кровью псов Тьмы.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к младшему аптекарю Холланду в Брилл, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (24991,'Ферма Гаррена','Как можно заметить, Королевское фармацевтическое общество имеет довольно широкую зону влияния. Мы серьезно относимся к нашему делу по разработке чумы. Мы считаем, что чем больше агентов занимается осуществлением экспериментов, тем скорее мы сможем добиться поставленной цели.$b$bОдин из наших агентов работает в небольшом лагере к северу отсюда. Его зовут Джеррод. Возможно, ему понадобится ассистент... твоего уровня.','Поговорите с аптекарем Джерродом на ферме Гаррена в Тирисфальских лесах.','Холланд? Да он дилетант. Наличие двухэтажной аптеки совсем не обязательно для того, чтобы создать настоящую чуму. Для этого нужна любовь… к делу. И еще пара-тройка хороших ассистентов. $B$BПойдем, я покажу тебе, как работают профессионалы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ферма Гаррена',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как можно заметить, Королевское фармацевтическое общество имеет довольно широкую зону влияния. Мы серьезно относимся к нашему делу по разработке чумы. Мы считаем, что чем больше агентов занимается осуществлением экспериментов, тем скорее мы сможем добиться поставленной цели.$b$bОдин из наших агентов работает в небольшом лагере к северу отсюда. Его зовут Джеррод. Возможно, ему понадобится ассистент... твоего уровня.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с аптекарем Джерродом на ферме Гаррена в Тирисфальских лесах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Холланд? Да он дилетант. Наличие двухэтажной аптеки совсем не обязательно для того, чтобы создать настоящую чуму. Для этого нужна любовь… к делу. И еще пара-тройка хороших ассистентов. $B$BПойдем, я покажу тебе, как работают профессионалы.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (24992,'Сбежавшие из Гилнеаса','Воргены-разбойники в Тирисфальских лесах – это что-то новенькое. Палач Зуганд чрезвычайно заинтересуется подобным известием.','Отправляйтесь в Брилл и доложите палачу Зуганду о присутствии воргенов в Тирисфальских лесах.','Хм… что и следовало ожидать. Когда поток воргенов хлынул из Гилнеаса, стало ясно, что рано или поздно они объявятся и в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сбежавшие из Гилнеаса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Воргены-разбойники в Тирисфальских лесах – это что-то новенькое. Палач Зуганд чрезвычайно заинтересуется подобным известием.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Брилл и доложите палачу Зуганду о присутствии воргенов в Тирисфальских лесах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хм… что и следовало ожидать. Когда поток воргенов хлынул из Гилнеаса, стало ясно, что рано или поздно они объявятся и в Тирисфальских лесах.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (24993,'Уничтожить воргенов','С воргенами нужно разобраться как можно скорее. В первую очередь с теми, кто успел проникнуть в Брилл.$b$bЯ хочу, чтобы теперь ты $gследил:следила; за всеми подозрительными событиями в деревне, $n. Нам известно, что воргены могут прятаться в тени, поэтому обращай внимание даже на мелочи: отпечатки ног, осыпающиеся камешки... малейшие изменения.','Найдите и убейте 5 воргенов-разведчиков на территории Брилла.','Подумать только, они были прямо у нас под носом! Я установлю боевое дежурство среди стражей смерти… такое больше НЕ ПОВТОРИТСЯ!','Вернитесь к палачу Зуганду в Брилл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уничтожить воргенов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','С воргенами нужно разобраться как можно скорее. В первую очередь с теми, кто успел проникнуть в Брилл.$b$bЯ хочу, чтобы теперь ты $gследил:следила; за всеми подозрительными событиями в деревне, $n. Нам известно, что воргены могут прятаться в тени, поэтому обращай внимание даже на мелочи: отпечатки ног, осыпающиеся камешки... малейшие изменения.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите и убейте 5 воргенов-разведчиков на территории Брилла.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Подумать только, они были прямо у нас под носом! Я установлю боевое дежурство среди стражей смерти… такое больше НЕ ПОВТОРИТСЯ!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к палачу Зуганду в Брилл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24994,'Погибельник','Посыльный только что доставил мне бушель мракоцветов. Мракоцветов! А я заказывал погибельник! Это ставит меня в несколько затруднительное положение, $n.$b$bЕсли поможешь мне его разрешить, я тебя отблагодарю. $B$BНасколько я знаю, погибельник любит места массовых захоронений, как например к северу от брилльского кладбища. Поторопись, но помни о гноллах, которые обитают в тех местах!','Соберите 10 веток погибельника.','<Аптекарь бормочет себе под нос.>$B$BНу как можно было перепутать погибельник с мракоцветом?! Что я теперь с ним буду делать?','Вернитесь к аптекарю Джерроду в Бастион, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Погибельник',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Посыльный только что доставил мне бушель мракоцветов. Мракоцветов! А я заказывал погибельник! Это ставит меня в несколько затруднительное положение, $n.$b$bЕсли поможешь мне его разрешить, я тебя отблагодарю. $B$BНасколько я знаю, погибельник любит места массовых захоронений, как например к северу от брилльского кладбища. Поторопись, но помни о гноллах, которые обитают в тех местах!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 веток погибельника.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Аптекарь бормочет себе под нос.>$B$BНу как можно было перепутать погибельник с мракоцветом?! Что я теперь с ним буду делать?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к аптекарю Джерроду в Бастион, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24995,'Чешуя – залог успеха','Пока ты $gсобирал:собирала; для меня образцы, я провел исследования и обнаружил, что для должного распространения этой болезни потребуются и другие реагенты. Отравить какую-нибудь одну жалкую жертву – это ерунда, а вот отравить весь мир куда сложнее.$B$BМне потребуется 5 чешуек мурлоков из племени Злобного Плавника. Эти создания часто бездумно прогуливаются вдоль берега к северу отсюда.','Добудьте 5 чешуек мурлоков из племени Злобного Плавника.','Вернитесь к аптекарю Джерроду в Бастион, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чешуя – залог успеха',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пока ты $gсобирал:собирала; для меня образцы, я провел исследования и обнаружил, что для должного распространения этой болезни потребуются и другие реагенты. Отравить какую-нибудь одну жалкую жертву – это ерунда, а вот отравить весь мир куда сложнее.$B$BМне потребуется 5 чешуек мурлоков из племени Злобного Плавника. Эти создания часто бездумно прогуливаются вдоль берега к северу отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 5 чешуек мурлоков из племени Злобного Плавника.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к аптекарю Джерроду в Бастион, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (24996,'Эксперимент Холланда','Отнесите особый напиток Холланда пленному горному пехотинцу.','Выпивка, ну наконец-то! И это вы называете элем? Это, конечно, не "Болтливое пиво", но сейчас я согласен на что угодно, лишь бы промочить горло.','Вернитесь к пленному горному пехотинцу в Западные Чумные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Эксперимент Холланда',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите особый напиток Холланда пленному горному пехотинцу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Выпивка, ну наконец-то! И это вы называете элем? Это, конечно, не "Болтливое пиво", но сейчас я согласен на что угодно, лишь бы промочить горло.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к пленному горному пехотинцу в Западные Чумные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24997,'Грабители могил','Братские могилы к западу отсюда были вырыты, чтобы вместить в себя... огромное количество мертвых тел, появившихся в Тирисфальских лесах после прихода чумы.$B$BТела в этих могилах еще не превратились в нежить, но теперь Плеть подослала гноллов из стаи Гнилошкуров, чтобы они воровали из могил трупы и пополняли ими ряды их армии. Этого нельзя допустить!$B$BУ тебя будет два задания: убить гноллов Гнилошкуров возле братских могил и Фермы Гаррена, а также отобрать у них бальзамирующую лимфу, поддерживающую в них жизнь.','Убивайте грабителей могил и полукровок из стаи Гнилошкуров и добудьте 6 образцов бальзамирующей лимфы.','Ты сделала то, о чем я просил? Убила этих псов и забрала у них лимфу?','Вернитесь к ученику Криспину на ферму Гаррена в Тирисфальские леса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Грабители могил',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Братские могилы к западу отсюда были вырыты, чтобы вместить в себя... огромное количество мертвых тел, появившихся в Тирисфальских лесах после прихода чумы.$B$BТела в этих могилах еще не превратились в нежить, но теперь Плеть подослала гноллов из стаи Гнилошкуров, чтобы они воровали из могил трупы и пополняли ими ряды их армии. Этого нельзя допустить!$B$BУ тебя будет два задания: убить гноллов Гнилошкуров возле братских могил и Фермы Гаррена, а также отобрать у них бальзамирующую лимфу, поддерживающую в них жизнь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убивайте грабителей могил и полукровок из стаи Гнилошкуров и добудьте 6 образцов бальзамирующей лимфы.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты сделала то, о чем я просил? Убила этих псов и забрала у них лимфу?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ученику Криспину на ферму Гаррена в Тирисфальские леса.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (24998,'Червеглаз','Червеглаз – отвратительное животное, даже по меркам гноллов. Он возглавляет банду гноллов-отступников, они занимаются тем, что раскапывают землю и крадут трупы, все, какие найдут.$b$bА это наши трупы! У нас были на них планы!$b$bЧервеглаза можно найти на дороге перед нами. Будь с ним $gбезжалостным:безжалостной;. Жалость – удел слабых.','Убейте Червеглаза и отрежьте у него лапу.','Превосходно! Теперь осталось только уговорить Джеррода переехать в ту хижину…','Да?','Вернитесь к ученику Криспину на ферму Гаррена в Тирисфальские леса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Червеглаз',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Червеглаз – отвратительное животное, даже по меркам гноллов. Он возглавляет банду гноллов-отступников, они занимаются тем, что раскапывают землю и крадут трупы, все, какие найдут.$b$bА это наши трупы! У нас были на них планы!$b$bЧервеглаза можно найти на дороге перед нами. Будь с ним $gбезжалостным:безжалостной;. Жалость – удел слабых.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Червеглаза и отрежьте у него лапу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Превосходно! Теперь осталось только уговорить Джеррода переехать в ту хижину…',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ученику Криспину на ферму Гаррена в Тирисфальские леса.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (24999,'Посеять страх','Ты, кажется, охотишься на мурлоков на севере по поручению Джеррода. Это хорошо... Мы можем использовать их части тела для создания ядов. Хотя меня иногда посещают некоторые сомнения... $b$bРайон нереста племени Злобного Плавника находится неподалеку от северного берега Тирисфальских лесов, так что среди взрослых особей на побережье тебе наверняка встречались и головастики. Если эти маленькие впечатлительные мурлоки захотят когда-нибудь отомстить нам... нам придется несладко. Отправляйся на побережье и припугни их хорошенько, чтобы они знали, что с Отрекшимися и Ордой шутки плохи.','Преследуйте 12 головастиков племени Злобного Плавника, пока они не потеряют сознание от страха.','Вернитесь к ученику Криспину на ферму Гаррена в Тирисфальские леса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Посеять страх',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты, кажется, охотишься на мурлоков на севере по поручению Джеррода. Это хорошо... Мы можем использовать их части тела для создания ядов. Хотя меня иногда посещают некоторые сомнения... $b$bРайон нереста племени Злобного Плавника находится неподалеку от северного берега Тирисфальских лесов, так что среди взрослых особей на побережье тебе наверняка встречались и головастики. Если эти маленькие впечатлительные мурлоки захотят когда-нибудь отомстить нам... нам придется несладко. Отправляйся на побережье и припугни их хорошенько, чтобы они знали, что с Отрекшимися и Ордой шутки плохи.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Преследуйте 12 головастиков племени Злобного Плавника, пока они не потеряют сознание от страха.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ученику Криспину на ферму Гаррена в Тирисфальские леса.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25000,'Люди Тигана','Эй, |3-6($c)!$b$bТы собираешься помочь капралу Тигану? Он отвечает за дороги, по которым происходит снабжение.$b$bВ помощниках у него двое самых злобных дворфов, каких я когда-либо встречал. Если хочешь произвести впечатление на этих двоих, тебе надо показать, что ты можешь выстоять против хищников, которые тут водятся.$b$bНаиболее опасны ящеры, которые водятся к западу от крепости. Принеси Гаучо несколько свежих шкур, тем самым ты сразу и произведешь хорошее впечатление, и снабдишь войска необходимым.','Добудьте 8 шкур страхокусов, убивая луговых страхокусов и зубастых страхокусов.','Эй, а ты сильнее, чем кажешься. Шкуры страхокусов защищают от стрел, клинков и топоров. Их нелегко добыть, в этих местах они ценятся на вес серебра. Отлично.','Принесите шкуры Гаучо в экспедицию Тигана в Южных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Люди Тигана',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эй, |3-6($c)!$b$bТы собираешься помочь капралу Тигану? Он отвечает за дороги, по которым происходит снабжение.$b$bВ помощниках у него двое самых злобных дворфов, каких я когда-либо встречал. Если хочешь произвести впечатление на этих двоих, тебе надо показать, что ты можешь выстоять против хищников, которые тут водятся.$b$bНаиболее опасны ящеры, которые водятся к западу от крепости. Принеси Гаучо несколько свежих шкур, тем самым ты сразу и произведешь хорошее впечатление, и снабдишь войска необходимым.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 8 шкур страхокусов, убивая луговых страхокусов и зубастых страхокусов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Эй, а ты сильнее, чем кажешься. Шкуры страхокусов защищают от стрел, клинков и топоров. Их нелегко добыть, в этих местах они ценятся на вес серебра. Отлично.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите шкуры Гаучо в экспедицию Тигана в Южных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (25001,'Пескоскреб','Другие мои помощники сейчас заняты размещением наших новых товарищей в комфортабельных клетках и отправкой туда, где их труд наиболее необходим. Орде. Тем временем нам стоит заняться последним пунктом нашей программы.$b$BИх вожак, Пескоскреб, скорее всего настолько туп, что даже не видит ничего странного в наших действиях. Но я терпеть не могу оставлять что-то незаконченным, детка. Он обитает в пещере на западе, совсем недалеко отсюда. Принимайся за дело, избавься от него, и мы наконец-то сможем поставить точку в этом дельце, идет?','Убить Пескоскреба.','Ну вот и готово! Теперь, кроме песка, здесь ничего не осталось. Ты молодец, детка.$B$BИ, пожалуй, мне не стоило быть столь вспыльчивой. В логове огра не нашлось чего-нибудь интересного?','Вернитесь к Мегз Жестекрошшер в Вербовочный лагерь Песчаного Молота, что в Танарисе.','Вождь Песчаного Молота.','Пескоскреб') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пескоскреб',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Другие мои помощники сейчас заняты размещением наших новых товарищей в комфортабельных клетках и отправкой туда, где их труд наиболее необходим. Орде. Тем временем нам стоит заняться последним пунктом нашей программы.$b$BИх вожак, Пескоскреб, скорее всего настолько туп, что даже не видит ничего странного в наших действиях. Но я терпеть не могу оставлять что-то незаконченным, детка. Он обитает в пещере на западе, совсем недалеко отсюда. Принимайся за дело, избавься от него, и мы наконец-то сможем поставить точку в этом дельце, идет?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убить Пескоскреба.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну вот и готово! Теперь, кроме песка, здесь ничего не осталось. Ты молодец, детка.$B$BИ, пожалуй, мне не стоило быть столь вспыльчивой. В логове огра не нашлось чего-нибудь интересного?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мегз Жестекрошшер в Вербовочный лагерь Песчаного Молота, что в Танарисе.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Вождь Песчаного Молота.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Пескоскреб',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25002,'Припасы','<На теле вы обнаружили длинный список предметов, срочно необходимых на фронте.>$b$b<Кровавый след в грязи указывает на то, что тела притащили с юга, через логовища ящеров.>$b$b<Похоже, что ящеры утащили все ящики с необходимыми припасами. Чтобы можно было пережить эту катастрофу, необходимо вернуть ящики капралу Тигану!>','Что? Мой караван был разграблен этими холоднокровными тварями с острыми как ножницы когтями?','Доставьте ящики капралу Тигану в экспедицию Тигана, что в Южных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Припасы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<На теле вы обнаружили длинный список предметов, срочно необходимых на фронте.>$b$b<Кровавый след в грязи указывает на то, что тела притащили с юга, через логовища ящеров.>$b$b<Похоже, что ящеры утащили все ящики с необходимыми припасами. Чтобы можно было пережить эту катастрофу, необходимо вернуть ящики капралу Тигану!>',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что? Мой караван был разграблен этими холоднокровными тварями с острыми как ножницы когтями?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доставьте ящики капралу Тигану в экспедицию Тигана, что в Южных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25003,'Семейный склеп','Семейная усыпальница Агамондов – самое укрепленное место на мельницах. Капитан Даргол поднял предков рода Агамондов с помощью некромантии и собирается использовать их против нас.$B$BТы $gдолжен:должна; не допустить этого. Отправляйся в Семейную усыпальницу Агамондов и убей их неупокоенных предков.','Убейте 5 стенающих прародительниц и 5 гниющих предков.','Вернитесь к Колману Фартингу на Мельницы Агамондов, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Семейный склеп',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Семейная усыпальница Агамондов – самое укрепленное место на мельницах. Капитан Даргол поднял предков рода Агамондов с помощью некромантии и собирается использовать их против нас.$B$BТы $gдолжен:должна; не допустить этого. Отправляйся в Семейную усыпальницу Агамондов и убей их неупокоенных предков.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 5 стенающих прародительниц и 5 гниющих предков.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Колману Фартингу на Мельницы Агамондов, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25004,'Нападение на мельницы','Соберите 5 зазубренных ребер и 3 почерневших черепа.','Вернитесь к Колману Фартингу на Мельницы Агамондов, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нападение на мельницы',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 5 зазубренных ребер и 3 почерневших черепа.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Колману Фартингу на Мельницы Агамондов, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25005,'Разговор с Севреном','Я уничтожил все останки, которые ты $gпринес:принесла;, $n. То есть все, кроме этих... $b$bПри жизни Девлин Агамонд был слабым и острым на язык. Чума поразила его одним из первых. Он пробыл рабом Плети долгое время – намного дольше, чем большинство других, и поэтому может обладать ценными знаниями.$b$bОтнеси его останки мировому судье Севрену и расскажи ему то, что я сейчас поведал тебе. Он поймет, что нужно сделать.','Поговорите с мировым судьей Севреном в Брилле, что в Тирисфальских лесах.','Вернитесь к мировому судье Севрену в Западные Чумные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разговор с Севреном',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я уничтожил все останки, которые ты $gпринес:принесла;, $n. То есть все, кроме этих... $b$bПри жизни Девлин Агамонд был слабым и острым на язык. Чума поразила его одним из первых. Он пробыл рабом Плети долгое время – намного дольше, чем большинство других, и поэтому может обладать ценными знаниями.$b$bОтнеси его останки мировому судье Севрену и расскажи ему то, что я сейчас поведал тебе. Он поймет, что нужно сделать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с мировым судьей Севреном в Брилле, что в Тирисфальских лесах.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мировому судье Севрену в Западные Чумные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25006,'Слабеющая хватка','Ах, как жаль. Похоже, власть Короля-лича над разумом Девлина не ослабла. А может, наши методы недостаточно эффективны. Хотя, возможно, этот простофиля Девлин просто не понял, чего мы от него хотели.','Вернитесь к мировому судье Севрену в Брилл, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Слабеющая хватка',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ах, как жаль. Похоже, власть Короля-лича над разумом Девлина не ослабла. А может, наши методы недостаточно эффективны. Хотя, возможно, этот простофиля Девлин просто не понял, чего мы от него хотели.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мировому судье Севрену в Брилл, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25007,'На восток, и только на восток!','Ты многое для нас $gсделал:сделала;, $n, но есть места, где в тебе нуждаются намного больше, чем здесь.$b$bК востоку отсюда находится Бастион: укрепленные баррикады на границе с Чумными землями. Бастион защищает нас от нашествий Плети, и именно благодаря ему мы можем позволить себе размещать войска здесь, в Тирисфальских лесах.$b$bОтправляйся в Бастион и поговори с верховным палачом Деррингтоном. Он наш союзник и без сомнения высоко оценит любую помощь, которую ты сможешь предложить.','Поговорите с верховным палачом Деррингтоном в Бастионе, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На восток, и только на восток!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты многое для нас $gсделал:сделала;, $n, но есть места, где в тебе нуждаются намного больше, чем здесь.$b$bК востоку отсюда находится Бастион: укрепленные баррикады на границе с Чумными землями. Бастион защищает нас от нашествий Плети, и именно благодаря ему мы можем позволить себе размещать войска здесь, в Тирисфальских лесах.$b$bОтправляйся в Бастион и поговори с верховным палачом Деррингтоном. Он наш союзник и без сомнения высоко оценит любую помощь, которую ты сможешь предложить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с верховным палачом Деррингтоном в Бастионе, что в Тирисфальских лесах.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25008,'Грязные животные','Наверное, ты уже знаешь, кто такие зубастые падальщики. Они воняют еще хуже, чем старый грязный Пит тут у нас. Никчемные твари! Крадут нашу добычу, роются в наших припасах и, что еще хуже, даже съесть их нельзя.$b$bИди и убей нескольких.$b$bА если понравится – продолжай.','Убейте 6 зубастых падальщиков.','Ооооо да! Лучшие падальщики – это мертвые падальщики.','Вернитесь к Гаучо в экспедицию Тигана в Южных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Грязные животные',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наверное, ты уже знаешь, кто такие зубастые падальщики. Они воняют еще хуже, чем старый грязный Пит тут у нас. Никчемные твари! Крадут нашу добычу, роются в наших припасах и, что еще хуже, даже съесть их нельзя.$b$bИди и убей нескольких.$b$bА если понравится – продолжай.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 6 зубастых падальщиков.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ооооо да! Лучшие падальщики – это мертвые падальщики.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гаучо в экспедицию Тигана в Южных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25009,'Война с Алым орденом','У нас до сих пор война, а Алый орден набирает силу. В отчете палача Аррена сказано, что члены Алого ордена под предводительством капитана Вакона совершали боевые вылазки из разрушенной башни, стоящей возле усадьбы Балнира, что на юго-востоке Тирисфаля.$B$BУбейте 3 ревнителей и 4 келейников из Алого ордена – это должно нанести ордену сокрушающий удар!','Убейте 3 ревнителей и 4 келейников Алого ордена.','Твои действия значительно замедлят продвижение Алого ордена по Тирисфалю… возможно, даже остановят окончательно. Но есть и другие угрозы.','Вернитесь к верховному палачу Деррингтону в Бастион, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Война с Алым орденом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У нас до сих пор война, а Алый орден набирает силу. В отчете палача Аррена сказано, что члены Алого ордена под предводительством капитана Вакона совершали боевые вылазки из разрушенной башни, стоящей возле усадьбы Балнира, что на юго-востоке Тирисфаля.$B$BУбейте 3 ревнителей и 4 келейников из Алого ордена – это должно нанести ордену сокрушающий удар!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 3 ревнителей и 4 келейников Алого ордена.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Твои действия значительно замедлят продвижение Алого ордена по Тирисфалю… возможно, даже остановят окончательно. Но есть и другие угрозы.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному палачу Деррингтону в Бастион, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25010,'Смертельный союзник','Незадолго до твоего появления в Бастионе, ко мне обратилась самая необычная девушка-отрекшаяся из всех, которые мне когда-либо встречались. Она поклялась в ненависти к Алому ордену, и я направил ее сражаться с нашими врагами на севере. Ты говоришь, что $gвидел:видела; мертвых рыцарей ордена? Это, скорее всего, ее рук дело.$b$bПроведай, как у нее дела. Возможно, ей нужна какая-то помощь в вендетте против Алого ордена... Хотя не удивлюсь, если она уже успела расправиться со всеми рыцарями.','Разыщите новую союзницу на Заставе Алого ордена в Тирисфальских лесах.','Вернитесь к палачу Зуганду в Западные Чумные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Смертельный союзник',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Незадолго до твоего появления в Бастионе, ко мне обратилась самая необычная девушка-отрекшаяся из всех, которые мне когда-либо встречались. Она поклялась в ненависти к Алому ордену, и я направил ее сражаться с нашими врагами на севере. Ты говоришь, что $gвидел:видела; мертвых рыцарей ордена? Это, скорее всего, ее рук дело.$b$bПроведай, как у нее дела. Возможно, ей нужна какая-то помощь в вендетте против Алого ордена... Хотя не удивлюсь, если она уже успела расправиться со всеми рыцарями.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите новую союзницу на Заставе Алого ордена в Тирисфальских лесах.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к палачу Зуганду в Западные Чумные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25011,'К большому и светлому будущему','Ты $gсовершил:совершила; достаточно подвигов здесь, в Бастионе, $n. Не знаю, представится ли еще возможность. И если жажда приключений все еще мучает тебя, отправляйся лучше в Серебряный бор.$b$bПоговори с одним из моих людей, Тимоти Каннингхемом. Он подбросит тебя до Брилла. Бесплатно, разумеется.','Поговорите с Тимоти Каннингхемом в Бастионе, что в Тирисфальских лесах.','Конечно, я тебя отвезу. Слово Деррингтона для меня приказ.','Вернитесь к аптекарю Ренферрелу в Серебряный бор.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','К большому и светлому будущему',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gсовершил:совершила; достаточно подвигов здесь, в Бастионе, $n. Не знаю, представится ли еще возможность. И если жажда приключений все еще мучает тебя, отправляйся лучше в Серебряный бор.$b$bПоговори с одним из моих людей, Тимоти Каннингхемом. Он подбросит тебя до Брилла. Бесплатно, разумеется.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Тимоти Каннингхемом в Бастионе, что в Тирисфальских лесах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Конечно, я тебя отвезу. Слово Деррингтона для меня приказ.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к аптекарю Ренферрелу в Серебряный бор.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25012,'Послание на тот свет','Если ты возвращаешься в Брилл, тебе стоит заскочить к палачу Зуганду. Я слышал, что в Серебряном бору, что к югу отсюда, что-то происходит. У него больше информации.$b$bКогда будешь $gготов:готова; отправиться в путь, сообщи мне.','Поговорите с палачом Зугандом в Брилле, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Послание на тот свет',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если ты возвращаешься в Брилл, тебе стоит заскочить к палачу Зуганду. Я слышал, что в Серебряном бору, что к югу отсюда, что-то происходит. У него больше информации.$b$bКогда будешь $gготов:готова; отправиться в путь, сообщи мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с палачом Зугандом в Брилле, что в Тирисфальских лесах.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25013,'Ядреная смесь','Добудьте 4 образца яда злобного ночного кругопряда','Вернитесь к аптекарю Дитерсу в Бастион, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ядреная смесь',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 4 образца яда злобного ночного кругопряда',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к аптекарю Дитерсу в Бастион, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (25014,'Сокровище Пескоскреба','Внутри истертого каменного сундука в глубине логова Пескроскреба вы нашли удивительный артефакт.$b$bФормой предмет напоминает жука с отполированной до зеркального блеска голубыми крылышками, прорезанными золотыми линиями. Похоже, это какой-то механизм, однако вряд ли руки смертного смогли бы сотворить нечто подобное, да и к тому же, артефакт определенно древний.$b$bПожалуй, стоит показать находку Мегз.','Поговорите с Мегз Жестекрошшер.','Удалось что-нибудь найти?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сокровище Пескоскреба',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Внутри истертого каменного сундука в глубине логова Пескроскреба вы нашли удивительный артефакт.$b$bФормой предмет напоминает жука с отполированной до зеркального блеска голубыми крылышками, прорезанными золотыми линиями. Похоже, это какой-то механизм, однако вряд ли руки смертного смогли бы сотворить нечто подобное, да и к тому же, артефакт определенно древний.$b$bПожалуй, стоит показать находку Мегз.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Мегз Жестекрошшер.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось что-нибудь найти?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25015,'Пусть они завизжат','Свинобразы – один из типичных видов Калимдора. Маленькие колючие куски мяса. Одних только их достаточно, чтобы ненавидеть весь континент.$b$bИх набеги начались почти сразу же после того, как мы установили передовые лагеря. Хуже того, этим шипастым дьяволам, кажется, совсем неплохо живется в колючих зарослях. Я хочу, чтобы ты $gпомог:помогла; мне отогнать их, и мы смогли восстановить контакт с передовой ставкой.$b$bА заодно, раздобудь одну из тех витых палок, которыми пользуются их заклинатели, чтобы контролировать растительность...','Убейте бритвостражей и загадочных терноплетов из племени Дыбогривов общим числом 8. Возьмите у одного из терноплетов ежевичный посох.','<Капрал Тиган кивает, когда получает от вас отчет, и обеими руками берет ежевичный посох.>$B$BТак эту штуку свинобразы используют против нас? Думаешь, они и джунгли создали при помощи него?','Должен заметить, что тебе, наверное, понадобится мачете, чтобы пробиться сквозь чащу.$B$BЭти джунгли появились как из ниоткуда!','Отнесите ежевичный посох капралу Тигану в экспедицию Тигана, что в Южных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пусть они завизжат',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Свинобразы – один из типичных видов Калимдора. Маленькие колючие куски мяса. Одних только их достаточно, чтобы ненавидеть весь континент.$b$bИх набеги начались почти сразу же после того, как мы установили передовые лагеря. Хуже того, этим шипастым дьяволам, кажется, совсем неплохо живется в колючих зарослях. Я хочу, чтобы ты $gпомог:помогла; мне отогнать их, и мы смогли восстановить контакт с передовой ставкой.$b$bА заодно, раздобудь одну из тех витых палок, которыми пользуются их заклинатели, чтобы контролировать растительность...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте бритвостражей и загадочных терноплетов из племени Дыбогривов общим числом 8. Возьмите у одного из терноплетов ежевичный посох.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Капрал Тиган кивает, когда получает от вас отчет, и обеими руками берет ежевичный посох.>$B$BТак эту штуку свинобразы используют против нас? Думаешь, они и джунгли создали при помощи него?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Должен заметить, что тебе, наверное, понадобится мачете, чтобы пробиться сквозь чащу.$B$BЭти джунгли появились как из ниоткуда!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите ежевичный посох капралу Тигану в экспедицию Тигана, что в Южных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (25016,'FLAG - Training Complete') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','FLAG - Training Complete',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25017,'Преграды древности','Годами эта долина была запечатана за неприступными воротами. Теперь же, когда ураган катаклизма пронесся и над ней, доступ к спрятанным сокровищам оказался открыт.$b$bОднако на нашем пути все еще есть некоторые преграды. Древние детища титанов пробудились и блуждают теперь в песках, нападая на каждого, кто встретится на их пути.$b$bКто-то должен уничтожить патрулирующих долину големов. Ты $gготов:готова?;','Уничтожьте 6 песчанокаменных големов.','Вернитесь к Андорену Восходу Солнца в экспедицию Восхода Солнца, что в Танарисе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Преграды древности',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Годами эта долина была запечатана за неприступными воротами. Теперь же, когда ураган катаклизма пронесся и над ней, доступ к спрятанным сокровищам оказался открыт.$b$bОднако на нашем пути все еще есть некоторые преграды. Древние детища титанов пробудились и блуждают теперь в песках, нападая на каждого, кто встретится на их пути.$b$bКто-то должен уничтожить патрулирующих долину големов. Ты $gготов:готова?;',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 6 песчанокаменных големов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Андорену Восходу Солнца в экспедицию Восхода Солнца, что в Танарисе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25018,'Андорен должен узнать','Слушай меня внимательно, $n. Я понятия не имею, где огры раздобыли эту штуку, но она определенно создана титанами. Я не очень хорошо разбираюсь в этом, однако понимаю, что найденный артефакт гораздо старше песка, на котором мы стоим.$b$BА еще я знаю, что такие штуки никогда не приносят ничего, кроме неприятностей. Не хочу оставлять это у себя. Отнеси его на юг, в долину Стражей, и отдай Андорену Восходу Солнца. И, пожалуйста, детка, не задавай лишних вопросов.','Отнесите артефакт Андорену Восходу Солнца, который находится в долине Стражей.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Андорен должен узнать',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слушай меня внимательно, $n. Я понятия не имею, где огры раздобыли эту штуку, но она определенно создана титанами. Я не очень хорошо разбираюсь в этом, однако понимаю, что найденный артефакт гораздо старше песка, на котором мы стоим.$b$BА еще я знаю, что такие штуки никогда не приносят ничего, кроме неприятностей. Не хочу оставлять это у себя. Отнеси его на юг, в долину Стражей, и отдай Андорену Восходу Солнца. И, пожалуйста, детка, не задавай лишних вопросов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите артефакт Андорену Восходу Солнца, который находится в долине Стражей.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25019,'Предъявить права','Убейте 10 дворфов-археологов.','Отлично. Чем меньше вмешательства со стороны Альянса, тем лучше.','Вернитесь к Андорену Восходу Солнца.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Предъявить права',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 дворфов-археологов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично. Чем меньше вмешательства со стороны Альянса, тем лучше.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Андорену Восходу Солнца.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25020,'Фрагменты языка','В Руинах Южной Луны, что расположены к востоку отсюда, мы сделали некоторые находки. Сдвиг песчаных пластов позволил моим коллегам обнаружить каменные осколки, испещренные древними надписями.$b$bЯзык, на котором сделаны надписи, нам неизвестен, однако между ними и тем, что мы обнаруживали в других руинах титанов имеется определенное сходство. Расшифровка заключенной в них информации может пролить свет на многие тайны.$b$bК сожалению, мои коллеги вынуждены постоянно сражаться с Альянсом за каждую скрижаль. Мне нужно, чтобы ты $gсам:сама; $gотправился:отправилась; в Руины Южной Луны и $gдостал:достала; несколько скрижалей.','Соберите 5 древних иероглифов.','Ты достала скрижали?','Вернитесь к Андорену Восходу Солнца.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Фрагменты языка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В Руинах Южной Луны, что расположены к востоку отсюда, мы сделали некоторые находки. Сдвиг песчаных пластов позволил моим коллегам обнаружить каменные осколки, испещренные древними надписями.$b$bЯзык, на котором сделаны надписи, нам неизвестен, однако между ними и тем, что мы обнаруживали в других руинах титанов имеется определенное сходство. Расшифровка заключенной в них информации может пролить свет на многие тайны.$b$bК сожалению, мои коллеги вынуждены постоянно сражаться с Альянсом за каждую скрижаль. Мне нужно, чтобы ты $gсам:сама; $gотправился:отправилась; в Руины Южной Луны и $gдостал:достала; несколько скрижалей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 5 древних иероглифов.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты достала скрижали?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Андорену Восходу Солнца.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25021,'Выжить за счет крови','<Мазога набирает полную горсть крови и подносит ее к губам. Пыль превращается в жидкость и с бульканьем струится по его горлу.>$B$BПьешь кровь – получаешь силу... Вот, я пью их кровь...$B$B<Мазога ухмыляется, обнажая окровавленные губы.>','Ты же не пил ее сам, так? Мне нужна вся кровь...','Вернитесь к Мазоге на Заставу Скорбных Песков, что в Танарисе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Выжить за счет крови',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Мазога набирает полную горсть крови и подносит ее к губам. Пыль превращается в жидкость и с бульканьем струится по его горлу.>$B$BПьешь кровь – получаешь силу... Вот, я пью их кровь...$B$B<Мазога ухмыляется, обнажая окровавленные губы.>',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты же не пил ее сам, так? Мне нужна вся кровь...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мазоге на Заставу Скорбных Песков, что в Танарисе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25022,'Неудавшаяся попытка договориться','Я говорил послу Гейнсу, что это глупая идея, но он настаивал, что сумеет договориться со свинобразами о союзе против Орды. Но даже если бы ему это и удалось, я, например, не хотел бы воевать вместе с такими... свиноподобными союзниками.$b$bВ общем, Гейнс не вернулся, и, если из-за этих визжащих тварей мы потеряем одного из наших лучших переговорщиков, генерал Готорн сочтет меня ответственным за это.$b$bНайди посла в джунглях и спаси его, если он все еще жив.','Спасите посла Гейнса от свинобразов в Буйных зарослях.','Превосходно. Гейнс недавно прошел здесь, направляясь к Северной Страже и теплой ванне.$B$BВообще-то его миссия не совсем провалилась. Мы многое узнали об этих свинобразах и их структуре руководства.$B$BТеперь мы можем все устроить... так, как Я считаю нужным.','Вернитесь к капралу Тигану в экспедицию Тигана в Южных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Неудавшаяся попытка договориться',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я говорил послу Гейнсу, что это глупая идея, но он настаивал, что сумеет договориться со свинобразами о союзе против Орды. Но даже если бы ему это и удалось, я, например, не хотел бы воевать вместе с такими... свиноподобными союзниками.$b$bВ общем, Гейнс не вернулся, и, если из-за этих визжащих тварей мы потеряем одного из наших лучших переговорщиков, генерал Готорн сочтет меня ответственным за это.$b$bНайди посла в джунглях и спаси его, если он все еще жив.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Спасите посла Гейнса от свинобразов в Буйных зарослях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Превосходно. Гейнс недавно прошел здесь, направляясь к Северной Страже и теплой ванне.$B$BВообще-то его миссия не совсем провалилась. Мы многое узнали об этих свинобразах и их структуре руководства.$B$BТеперь мы можем все устроить... так, как Я считаю нужным.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капралу Тигану в экспедицию Тигана в Южных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25023,'Старые друзья','Ладно, хватайся за лестницу, надо выбираться отсюда!$B$BМы облетим город, а потом ты встретишься кое с кем из давних друзей!','Поговорите с Траллом у дозорного пункта вождя на Затерянных островах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Старые друзья',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ладно, хватайся за лестницу, надо выбираться отсюда!$B$BМы облетим город, а потом ты встретишься кое с кем из давних друзей!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Траллом у дозорного пункта вождя на Затерянных островах.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25024,'Противостояние десанту','Друг мой, просто дело в том, что Альянс застиг нас врасплох. Мы разобрались с их кораблями, но у них остались самолеты – они сбрасывают на берег десантников прославленного 127-го полка.$B$BНаши новобранцы и разведчики стоят насмерть, но они не в силах разгромить превосходящие в численности силы противника. Но я уверен, что если в битву вступишь ты, положение дел сразу же изменится.','Убейте 10 парашютистов Альянса.','Беспримерное проявление доблести.','Вернитесь к Траллу на дозорный пункт вождя на Затерянных островах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Противостояние десанту',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Друг мой, просто дело в том, что Альянс застиг нас врасплох. Мы разобрались с их кораблями, но у них остались самолеты – они сбрасывают на берег десантников прославленного 127-го полка.$B$BНаши новобранцы и разведчики стоят насмерть, но они не в силах разгромить превосходящие в численности силы противника. Но я уверен, что если в битву вступишь ты, положение дел сразу же изменится.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 парашютистов Альянса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Беспримерное проявление доблести.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Траллу на дозорный пункт вождя на Затерянных островах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (25025,'Санг\'траз Отражатель','Кровь говорит со мной. Я чувствую, как течет она под песками... Пустыня страданий, пропитанная смертью... $b$b<Мазога закатывает глаза.>$b$bЗдесь! Кровь течет к югу, в долину костей. Заккару! Заккару, порождение Маккари, тьмы, жаждущей жертвоприношений... Его отец был изгнан из Зул\'Фаррака, и вознесение его прекратилось... Он почувствует вкус крови еще один раз... $b$b<Мазога крутится на месте.>$b$bСтупай, |3-6($c). Санг\'тразом владеет Заккару. Поверь мне, лучше разъединить их.','Победите Заккару и заберите усмиренный Санг\'траз.','<Мазога берет меч из ваших рук и ухмыляется.>$B$BРазве он не прекрасен, а? В этом мире не только тролли жаждут крови, да.$B$BДавай найдем и второй меч...','Заккару, порождение Маккари.','Заккару') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Санг\'траз Отражатель',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кровь говорит со мной. Я чувствую, как течет она под песками... Пустыня страданий, пропитанная смертью... $b$b<Мазога закатывает глаза.>$b$bЗдесь! Кровь течет к югу, в долину костей. Заккару! Заккару, порождение Маккари, тьмы, жаждущей жертвоприношений... Его отец был изгнан из Зул\'Фаррака, и вознесение его прекратилось... Он почувствует вкус крови еще один раз... $b$b<Мазога крутится на месте.>$b$bСтупай, |3-6($c). Санг\'тразом владеет Заккару. Поверь мне, лучше разъединить их.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Заккару и заберите усмиренный Санг\'траз.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Мазога берет меч из ваших рук и ухмыляется.>$B$BРазве он не прекрасен, а? В этом мире не только тролли жаждут крови, да.$B$BДавай найдем и второй меч...',`offerrewardtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Заккару, порождение Маккари.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Заккару',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (25027,'Отомстить Трехзубой','По словам Гейнса, "Трехзубой" свинобразы называют своего матриарха. Это она устроила в джунглях эту безумную колючую чащу и это по ее приказу Гейнса должны были "разорвать на части и скормить зарослям". Милая леди.$b$bДавай отнесемся к ней так же, как она относится к другим. Возьми ежевичный посох, который ты $gдостал:достала;, и отделай с его помощью Трехзубую, чтобы отстранить ее от дел. А потом убей тех ведьм, которых она обучает, чтобы точно знать, что никто не займет ее место.','Воспользуйтесь ежевичным посохом, чтобы победить Трехзубую, и убейте 2 загадочных ведьм в Буйных зарослях.','Разорвана на части?! Я почти пожалел ее. Но жгучая ненависть сильнее. Она получила по заслугам.$B$B<Капрал Тиган берет ежевичный посох и постукивает им по колену.>$B$BПроблема решена.','Теперь я понимаю, почему Орда ненавидит этих тварей. Справилась с Трехзубой?','Вернитесь к капралу Тигану в экспедицию Тигана в Южных Степях.','Воспользуйтесь ежевичным посохом, чтобы обернуть ее магию против нее самой.','Трехзубая') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отомстить Трехзубой',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','По словам Гейнса, "Трехзубой" свинобразы называют своего матриарха. Это она устроила в джунглях эту безумную колючую чащу и это по ее приказу Гейнса должны были "разорвать на части и скормить зарослям". Милая леди.$b$bДавай отнесемся к ней так же, как она относится к другим. Возьми ежевичный посох, который ты $gдостал:достала;, и отделай с его помощью Трехзубую, чтобы отстранить ее от дел. А потом убей тех ведьм, которых она обучает, чтобы точно знать, что никто не займет ее место.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь ежевичным посохом, чтобы победить Трехзубую, и убейте 2 загадочных ведьм в Буйных зарослях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Разорвана на части?! Я почти пожалел ее. Но жгучая ненависть сильнее. Она получила по заслугам.$B$B<Капрал Тиган берет ежевичный посох и постукивает им по колену.>$B$BПроблема решена.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Теперь я понимаю, почему Орда ненавидит этих тварей. Справилась с Трехзубой?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капралу Тигану в экспедицию Тигана в Южных Степях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Воспользуйтесь ежевичным посохом, чтобы обернуть ее магию против нее самой.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Трехзубая',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25028,'Проблемы растут из земли','Со стороны Тигана глупо думать, что эти внезапно появившиеся заросли – дело рук свинобразов. Посмотри вокруг. Я уже не первый день наблюдаю за ростом и цветением этих растений – каждое следующее поколение мутирует еще больше, чем предыдущее. Это не похоже на магию свинобразов, это что-то первобытное. И опасное.$b$bПозавчера через наш лагерь проходил один великий друид. Найди Наралекса, он где-то в центре этой чащи. Он скажет, как быть.$b$bЧтобы ему легче было понять, в чем дело, принеси ему образцы растений из разных мест зарослей.','Соберите 10 необычных цветочных бутонов в Буйных зарослях.','Отнесите цветочные бутоны Наралексу в Буйные заросли в Южных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Проблемы растут из земли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Со стороны Тигана глупо думать, что эти внезапно появившиеся заросли – дело рук свинобразов. Посмотри вокруг. Я уже не первый день наблюдаю за ростом и цветением этих растений – каждое следующее поколение мутирует еще больше, чем предыдущее. Это не похоже на магию свинобразов, это что-то первобытное. И опасное.$b$bПозавчера через наш лагерь проходил один великий друид. Найди Наралекса, он где-то в центре этой чащи. Он скажет, как быть.$b$bЧтобы ему легче было понять, в чем дело, принеси ему образцы растений из разных мест зарослей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 необычных цветочных бутонов в Буйных зарослях.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите цветочные бутоны Наралексу в Буйные заросли в Южных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25029,'Смерти в семье','Семья Агамондов была самой преуспевающей в Тирисфальских лесах. Я работал на их мельницах... еще до чумы.$B$BКогда Плеть явилась в первый раз, Агамонды укрепили свой дом и уговорили всех работников остаться и помогать им держать оборону. А мы были дураками, но дураками преданными...$B$BИз-за гордыни Агамондов мы стали нежитью, а сами они служат Плети!$B$BСослужи Отрекшимся службу – убей Агамондов, ставших жертвами чумы, и принеси мне их останки.','Месть сладка, не правда ли? Ты заметил хоть какие-то признаки свободной воли в Агамондах, когда убивал их? Надеюсь, что да. Надеюсь, они почувствовали страх, прежде чем упокоились навсегда.$B$BКонечно, глупо на это надеяться, но тем не менее.','Вернитесь к Колману Фартингу на Мельницы Агамондов, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Смерти в семье',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Семья Агамондов была самой преуспевающей в Тирисфальских лесах. Я работал на их мельницах... еще до чумы.$B$BКогда Плеть явилась в первый раз, Агамонды укрепили свой дом и уговорили всех работников остаться и помогать им держать оборону. А мы были дураками, но дураками преданными...$B$BИз-за гордыни Агамондов мы стали нежитью, а сами они служат Плети!$B$BСослужи Отрекшимся службу – убей Агамондов, ставших жертвами чумы, и принеси мне их останки.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Месть сладка, не правда ли? Ты заметил хоть какие-то признаки свободной воли в Агамондах, когда убивал их? Надеюсь, что да. Надеюсь, они почувствовали страх, прежде чем упокоились навсегда.$B$BКонечно, глупо на это надеяться, но тем не менее.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Колману Фартингу на Мельницы Агамондов, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25030,'Мельницы с привидениями','Череп окутан зловещей аурой. Колман Фартинг наверняка этим заинтересуется.','Так-так, что тут у нас?','Вернитесь к Колману Фартингу на Мельницы Агамондов, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мельницы с привидениями',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Череп окутан зловещей аурой. Колман Фартинг наверняка этим заинтересуется.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Так-так, что тут у нас?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Колману Фартингу на Мельницы Агамондов, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (25031,'Курс на мельницы','Мельницы Агамондов на западе захватила Плеть. Само семейство убили, а их владения объявили собственностью Плети.$b$bЭто, наверное, самое большое укрепление Плети в Тирисфальских лесах. Если ты $gнастоящий:настоящая:c; |3-6($c), отправляйся к мельницам и поговори с Колманом Фартингом. Он сражается за то, чтобы вернуть эти земли обратно, и ему определенно помощь не помешает. Эта дорога приведет тебя прямо к нему.','Стоять! Не двигаться! О, да ты ведь не из Плети.$B$BСлава королеве банши, что ты приехал. Я и представить себе не мог, что дела здесь так плохи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Курс на мельницы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мельницы Агамондов на западе захватила Плеть. Само семейство убили, а их владения объявили собственностью Плети.$b$bЭто, наверное, самое большое укрепление Плети в Тирисфальских лесах. Если ты $gнастоящий:настоящая:c; |3-6($c), отправляйся к мельницам и поговори с Колманом Фартингом. Он сражается за то, чтобы вернуть эти земли обратно, и ему определенно помощь не помешает. Эта дорога приведет тебя прямо к нему.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Стоять! Не двигаться! О, да ты ведь не из Плети.$B$BСлава королеве банши, что ты приехал. Я и представить себе не мог, что дела здесь так плохи.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25032,'Секреты оазиса','Да, теперь я вижу и вторую часть... На юге...$b$bЭто рядом. Бывший оазис, захороненный теперь под слоем ила и водой. Не задерживайся!','Разыщите Джанг\'траз Охранитель.','Мазога? Забрал меч? Что за подлость...$B$B<Во взгляде Трентона проскальзывает ярость.>$B$BПо крайней мере, тебе удалось сохранить свою жизнь.','Вернитесь к Трентону Молоту Света на Заставу Скорбных Песков, что в Танарисе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Секреты оазиса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Да, теперь я вижу и вторую часть... На юге...$b$bЭто рядом. Бывший оазис, захороненный теперь под слоем ила и водой. Не задерживайся!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите Джанг\'траз Охранитель.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мазога? Забрал меч? Что за подлость...$B$B<Во взгляде Трентона проскальзывает ярость.>$B$BПо крайней мере, тебе удалось сохранить свою жизнь.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Трентону Молоту Света на Заставу Скорбных Песков, что в Танарисе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25033,'Красный гонец','В сообщениях от моего начальства в Брилле упоминается, что агент Алого ордена направляется из Монастыря к Похоронному Звону. Судя по этим сообщениям, гонец несет важную информацию. Я не знаю подробностей, но что бы у него ни оказалось, мы должны это перехватить! $b$bА ты, $n, наиболее квалифицированная особа, которую я могу послать на это задание. Найди гонца и принеси мне информацию, которую тебе удастся найти.','Убейте Мевена Коргала в лагере рыцарей и получите информацию, которой он обладает.','Вернитесь к палачу Аррену в Похоронный Звон, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Красный гонец',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В сообщениях от моего начальства в Брилле упоминается, что агент Алого ордена направляется из Монастыря к Похоронному Звону. Судя по этим сообщениям, гонец несет важную информацию. Я не знаю подробностей, но что бы у него ни оказалось, мы должны это перехватить! $b$bА ты, $n, наиболее квалифицированная особа, которую я могу послать на это задание. Найди гонца и принеси мне информацию, которую тебе удастся найти.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Мевена Коргала в лагере рыцарей и получите информацию, которой он обладает.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к палачу Аррену в Похоронный Звон, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (25034,'На фронт!','Я бы хотел оставить тебя здесь, но, похоже, тебя призывают на фронт. Посла Гейнса – помнишь его? – перевели в передовую ставку, и в своем последнем сообщении он просил прислать ему в $gпомощники:помощницы; именно тебя.$b$bКомандная ставка находится к югу отсюда, в том месте, которое называется "Кровавые поля".$b$bБудь $gосторожен:осторожна;, $n. Орда устроила засады вдоль дороги, некоторые из наших офицеров подверглись нападению.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На фронт!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я бы хотел оставить тебя здесь, но, похоже, тебя призывают на фронт. Посла Гейнса – помнишь его? – перевели в передовую ставку, и в своем последнем сообщении он просил прислать ему в $gпомощники:помощницы; именно тебя.$b$bКомандная ставка находится к югу отсюда, в том месте, которое называется "Кровавые поля".$b$bБудь $gосторожен:осторожна;, $n. Орда устроила засады вдоль дороги, некоторые из наших офицеров подверглись нападению.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (25035,'Прорыв обороны','Вол\'джин приказал начать крупномасштабную атаку на наг, оккупировавших наш северный остров. Многие уже вступили с ними в бой у моста, но несколько бойцов должны прорвать их оборону и пробраться вглубь острова.$B$BПоговори с Йорнуном, чтобы отправиться на остров, а там найди капитана дозора Моракки. Он расскажет, чем ты можешь помочь.','Поговорите с Йорнуном, чтобы отправиться в грот Злобной Чешуи, а там найдите Моракки.','Здорово, что ты с нами, братишка.$B$BВ такие минуты начинаешь гордиться, что служишь Вол\'джину, и хочется шагнуть прямо навстречу опасности.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прорыв обороны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вол\'джин приказал начать крупномасштабную атаку на наг, оккупировавших наш северный остров. Многие уже вступили с ними в бой у моста, но несколько бойцов должны прорвать их оборону и пробраться вглубь острова.$B$BПоговори с Йорнуном, чтобы отправиться на остров, а там найди капитана дозора Моракки. Он расскажет, чем ты можешь помочь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Йорнуном, чтобы отправиться в грот Злобной Чешуи, а там найдите Моракки.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Здорово, что ты с нами, братишка.$B$BВ такие минуты начинаешь гордиться, что служишь Вол\'джину, и хочется шагнуть прямо навстречу опасности.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (25036,'Беспокойство Тигана','Так значит Пакстон говорит, что в Степях нет никаких джунглей? А как бы ты назвала ЭТО?$B$BУ меня несколько ящиков с припасами, которые надо доставить в лагерь, а лагерь окружен зарослями, которые – я клянусь! – увеличиваются с каждым часом!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Беспокойство Тигана',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так значит Пакстон говорит, что в Степях нет никаких джунглей? А как бы ты назвала ЭТО?$B$BУ меня несколько ящиков с припасами, которые надо доставить в лагерь, а лагерь окружен зарослями, которые – я клянусь! – увеличиваются с каждым часом!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25037,'Ловля крабов','Похоже, на старости лет мой организм забастовал – кабанину уже не принимает. Видать, она только для молодых хороша.$B$BМы уже расставили в округе несколько ловушек для крабов, но мне просто не терпится – хочется уже сейчас насладиться свежим крабовым мясом. Может, выполнишь прихоть старика? Крабов полно по всему острову, но лучше всего ловить их на восточном побережье.','Убейте карликовых приливных крабов и добудьте 5 порций свежего крабового мяса.','Вернитесь к Тора\'джину в крепость Черного Копья на островах Эха.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ловля крабов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Похоже, на старости лет мой организм забастовал – кабанину уже не принимает. Видать, она только для молодых хороша.$B$BМы уже расставили в округе несколько ловушек для крабов, но мне просто не терпится – хочется уже сейчас насладиться свежим крабовым мясом. Может, выполнишь прихоть старика? Крабов полно по всему острову, но лучше всего ловить их на восточном побережье.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте карликовых приливных крабов и добудьте 5 порций свежего крабового мяса.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тора\'джину в крепость Черного Копья на островах Эха.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (25037,'Ммм, как вкусно. Спасибо тебе за доброту. Ты заслужил расположение духов.','Крабовое мясо – один из лучших даров моря.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ммм, как вкусно. Спасибо тебе за доброту. Ты заслужил расположение духов.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Крабовое мясо – один из лучших даров моря.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25038,'Задание Толстяка','Хозяину надо растения. У нас большие руки, цветы рвать никак. Ты нам помогать, мы тебя не трогать. Нам надо мракоцвет, он растет тут и у дороги.$B$BТы соберешь – отнеси хозяину Холланду в Брилл.','Соберите 3 мракоцвета для младшего аптекаря Холланда из Брилла.','Что это? Мракоцвет?! Зачем он мне сдался?! Эта тупая гора мяса собирает ромашки и привлекает – сколько, Темная Госпожа знает, – к этому делу таких простаков, как ты! Без обид.$B$BС мракоцветами разберемся позже, сейчас у нас есть дела поважнее.','Вернитесь к младшему аптекарю Холланду в Брилл, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Задание Толстяка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хозяину надо растения. У нас большие руки, цветы рвать никак. Ты нам помогать, мы тебя не трогать. Нам надо мракоцвет, он растет тут и у дороги.$B$BТы соберешь – отнеси хозяину Холланду в Брилл.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 3 мракоцвета для младшего аптекаря Холланда из Брилла.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что это? Мракоцвет?! Зачем он мне сдался?! Эта тупая гора мяса собирает ромашки и привлекает – сколько, Темная Госпожа знает, – к этому делу таких простаков, как ты! Без обид.$B$BС мракоцветами разберемся позже, сейчас у нас есть дела поважнее.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к младшему аптекарю Холланду в Брилл, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25039,'Воргенов не видали?','Послушай... |3-6($r)! Тут такое... э... странное дельце.$b$bРыбачил я давече на Ясноводном озере, а тут гляжу – бежит по лесу какое-то дьявольское создание, как будто полуволк, получеловек. А вдруг это один из этих... воргенов... или как их там?$b$bВ общем, нужно ведь рассказать об этом палачу Зуганду, но я его что-то побаиваюсь. Может, ты $gмог:могла; бы поговорить с ним вместо меня?','Поведайте палачу Зуганду о воргенах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Воргенов не видали?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Послушай... |3-6($r)! Тут такое... э... странное дельце.$b$bРыбачил я давече на Ясноводном озере, а тут гляжу – бежит по лесу какое-то дьявольское создание, как будто полуволк, получеловек. А вдруг это один из этих... воргенов... или как их там?$b$bВ общем, нужно ведь рассказать об этом палачу Зуганду, но я его что-то побаиваюсь. Может, ты $gмог:могла; бы поговорить с ним вместо меня?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поведайте палачу Зуганду о воргенах.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (25040,'FLAG - Worgen Attacked') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','FLAG - Worgen Attacked',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25041,'Гордость льва','Нельзя не уважать львов, $n! Жестокие убийцы. И нельзя не восхищаться их грацией... Игрой мускулов под кожей... Острыми, как бритва, когтями... Преследующий свою жертву хищник... В этом есть что-то первобытное...$b$bПрости, я увлекся. Как я сказал, львов нельзя не уважать, но они уничтожают наши патрули. Буквально. Ночью мои люди боятся даже отойти в уборную в одиночку. Не поможешь сделать это место чуть более безопасным?$b$BСтепные львы обычно нежатся в тени под деревьями.','Убейте равнинных хищников и хозяев стаи общим числом 5 особей.','Очень хорошо! Было трудно? Понравилось охотиться?$B$BТы бежишь через высокие степные травы, запах жертвы заставляет тебя мчаться все быстрее, потом ты совершаешь последний прыжок, чтобы вцепиться жертве в горло, и адреналин бушует у тебя в крови в то время, как твои клыки... Ну, в общем, что-то в таком духе.','Вернитесь к Сэму Тралли в передовой ставке в Южных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гордость льва',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нельзя не уважать львов, $n! Жестокие убийцы. И нельзя не восхищаться их грацией... Игрой мускулов под кожей... Острыми, как бритва, когтями... Преследующий свою жертву хищник... В этом есть что-то первобытное...$b$bПрости, я увлекся. Как я сказал, львов нельзя не уважать, но они уничтожают наши патрули. Буквально. Ночью мои люди боятся даже отойти в уборную в одиночку. Не поможешь сделать это место чуть более безопасным?$b$BСтепные львы обычно нежатся в тени под деревьями.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте равнинных хищников и хозяев стаи общим числом 5 особей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Очень хорошо! Было трудно? Понравилось охотиться?$B$BТы бежишь через высокие степные травы, запах жертвы заставляет тебя мчаться все быстрее, потом ты совершаешь последний прыжок, чтобы вцепиться жертве в горло, и адреналин бушует у тебя в крови в то время, как твои клыки... Ну, в общем, что-то в таком духе.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сэму Тралли в передовой ставке в Южных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25042,'Хороший солдат – сытый солдат','Правду говорят: хороший солдат – сытый солдат. А нам нужно быть очень хорошими солдатами.$b$bВот я и думаю, если мы зажарим несколько этих гигантских неповоротливых грозорылов, то у нас будет достаточно мяса для того, чтобы прокормиться в течение нескольких недель.$b$bГрозорылы медлительные и неповоротливые, поэтому убить их будет несложно. Только если... На тебе случайно нет никаких металлических предметов?','<Глаза Сэма округляются, когда вы выкладываете перед ним огромные куски мяса.>$B$BО, да… Ооо… ДА! Свой я съем сырым. Думаю, надо пожарить несколько для остальных. А ты какую степень прожарки предпочитаешь?','<Тралли облизывает губы, едва сдерживая слюну.>$B$BМои стейки готовы? Свежие, с кровью?','Принесите стейки Сэму Тралли в Ставку командования в Южных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хороший солдат – сытый солдат',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Правду говорят: хороший солдат – сытый солдат. А нам нужно быть очень хорошими солдатами.$b$bВот я и думаю, если мы зажарим несколько этих гигантских неповоротливых грозорылов, то у нас будет достаточно мяса для того, чтобы прокормиться в течение нескольких недель.$b$bГрозорылы медлительные и неповоротливые, поэтому убить их будет несложно. Только если... На тебе случайно нет никаких металлических предметов?',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Глаза Сэма округляются, когда вы выкладываете перед ним огромные куски мяса.>$B$BО, да… Ооо… ДА! Свой я съем сырым. Думаю, надо пожарить несколько для остальных. А ты какую степень прожарки предпочитаешь?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Тралли облизывает губы, едва сдерживая слюну.>$B$BМои стейки готовы? Свежие, с кровью?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите стейки Сэму Тралли в Ставку командования в Южных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25043,'Кровавые поля','Очень хорошо. Может быть, нам никогда не удастся полностью прогнать Орду из этих земель, но приструнить их мы сможем.','Вернитесь к генералу Готорну в передовую ставку, что в Южных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кровавые поля',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Очень хорошо. Может быть, нам никогда не удастся полностью прогнать Орду из этих земель, но приструнить их мы сможем.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к генералу Готорну в передовую ставку, что в Южных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (25044,'Обратная сторона дипломатии','Я не забыл, как заглянул в глаза смерти, находясь в лапах свинобразов в этих грязных джунглях. Генерал приказал нанести несколько стратегических ударов, но не допускать массовых убийств. Я же не так щепетилен.$b$bВозьми этот рог, который я "одолжил" во время переговоров. Протруби в него на площадке Дыбогривов для боя к западу отсюда – ее трудно не заметить. Я хочу, чтобы ты $gвызвал:вызвала; на одиночный бой Саблеморда, чемпиона Дыбогривов. Если он будет убит на глазах у всех, они в панике разбегутся.','Говоришь, "свинокалипсис"? Похоже, у этих тварей очень оригинальное представление о том, что такое "одиночный бой"!$B$BНе имеет значения, ты отлично справилась. Свинобразы в панике бросились врассыпную, теперь я без проблем смогу убедить командиров боевых частей перебить их всех поодиночке. Генералу необязательно знать, что мы немного расширили кампанию. Это на благо.','Саблеморд! Он убит? Какие новости?','Вернитесь к послу Гейнсу в передовую ставку в Южных Степях.','Протруби в боевой рог, чтобы вызвать Саблеморда.','Саблеморд') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обратная сторона дипломатии',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я не забыл, как заглянул в глаза смерти, находясь в лапах свинобразов в этих грязных джунглях. Генерал приказал нанести несколько стратегических ударов, но не допускать массовых убийств. Я же не так щепетилен.$b$bВозьми этот рог, который я "одолжил" во время переговоров. Протруби в него на площадке Дыбогривов для боя к западу отсюда – ее трудно не заметить. Я хочу, чтобы ты $gвызвал:вызвала; на одиночный бой Саблеморда, чемпиона Дыбогривов. Если он будет убит на глазах у всех, они в панике разбегутся.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Говоришь, "свинокалипсис"? Похоже, у этих тварей очень оригинальное представление о том, что такое "одиночный бой"!$B$BНе имеет значения, ты отлично справилась. Свинобразы в панике бросились врассыпную, теперь я без проблем смогу убедить командиров боевых частей перебить их всех поодиночке. Генералу необязательно знать, что мы немного расширили кампанию. Это на благо.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Саблеморд! Он убит? Какие новости?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к послу Гейнсу в передовую ставку в Южных Степях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Протруби в боевой рог, чтобы вызвать Саблеморда.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Саблеморд',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25045,'Отступать некуда','Контролирование территории требует постоянного наблюдения. Смотри, на этой карте изображены несколько стратегических холмов, таких же, как этот. Если мы хотим держать врага в руках, Альянс должен завладеть ими.$b$bМои разведчики уже выяснили точное расположение холмов на поле. Мне нужен кто-то, кто бы возглавил захват, и ты отлично подходишь.$b$bОтыщи нейтральные серые флаги на холмах к северу, востоку и югу от руин Таурахо. Захвати один из них и защищай его!','Захватите нейтральный холм в Кровавых полях и защитите его от атак Орды.','Вернитесь к генералу Готорну в передовую ставку, что в Южных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отступать некуда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Контролирование территории требует постоянного наблюдения. Смотри, на этой карте изображены несколько стратегических холмов, таких же, как этот. Если мы хотим держать врага в руках, Альянс должен завладеть ими.$b$bМои разведчики уже выяснили точное расположение холмов на поле. Мне нужен кто-то, кто бы возглавил захват, и ты отлично подходишь.$b$bОтыщи нейтральные серые флаги на холмах к северу, востоку и югу от руин Таурахо. Захвати один из них и защищай его!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Захватите нейтральный холм в Кровавых полях и защитите его от атак Орды.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к генералу Готорну в передовую ставку, что в Южных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25046,'Объятия дочери','Шепот продолжается:$b$b"Меня зовут Лилиан Восс. Прежде, чем умереть, я была членом Алого ордена. Мой отец, Верховный жрец Восс, растил меня так, чтобы я могла стать оружием против Плети. Я обучалась скрытности, колдовству, воинским искусствам – всему, что могло сделать меня сильнее. Из-за отца у меня не было детства."$b$b"А потом, по прихоти судьбы, я умерла и превратилась... в это. Мой отец отказался от меня и, когда я вернулась, приказал убить меня."$b$b"Идем, поговорим с ним. Он сейчас в башне на северо-западе".','Отведите Лилиан Восс к ее отцу в башню на Пути Рыцаря.','От рождения до смерти (а может, и до нежития) каждый из нас идет своим путем. Для кого-то этот путь будет трудным, для кого-то легким. Этой девушке приходится не сладко. $B$BНадеюсь, она решит встать на нашу сторону и последовать за Темной Госпожой. С таким сильным союзником, как она, мы сможем горы свернуть.$B$BКстати, Магох... Ты отлично справился со своим заданием. Если у тебя есть время и желание, у меня для тебя всегда найдется работенка в Чумных землях.','Вернитесь к верховному палачу Деррингтону в Бастион, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Объятия дочери',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Шепот продолжается:$b$b"Меня зовут Лилиан Восс. Прежде, чем умереть, я была членом Алого ордена. Мой отец, Верховный жрец Восс, растил меня так, чтобы я могла стать оружием против Плети. Я обучалась скрытности, колдовству, воинским искусствам – всему, что могло сделать меня сильнее. Из-за отца у меня не было детства."$b$b"А потом, по прихоти судьбы, я умерла и превратилась... в это. Мой отец отказался от меня и, когда я вернулась, приказал убить меня."$b$b"Идем, поговорим с ним. Он сейчас в башне на северо-западе".',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отведите Лилиан Восс к ее отцу в башню на Пути Рыцаря.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','От рождения до смерти (а может, и до нежития) каждый из нас идет своим путем. Для кого-то этот путь будет трудным, для кого-то легким. Этой девушке приходится не сладко. $B$BНадеюсь, она решит встать на нашу сторону и последовать за Темной Госпожой. С таким сильным союзником, как она, мы сможем горы свернуть.$B$BКстати, Магох... Ты отлично справился со своим заданием. Если у тебя есть время и желание, у меня для тебя всегда найдется работенка в Чумных землях.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному палачу Деррингтону в Бастион, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25047,'Разбитая статуэтка пантеры','Прошлый владелец просто выбросил эту разбитую статуэтку. Однако умелый ювелир мог бы ее полностью восстановить при помощи определенных материалов.','Почините разбитую статуэтку, применив необходимые умения и материалы.','Completion text.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разбитая статуэтка пантеры',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прошлый владелец просто выбросил эту разбитую статуэтку. Однако умелый ювелир мог бы ее полностью восстановить при помощи определенных материалов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Почините разбитую статуэтку, применив необходимые умения и материалы.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Completion text.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25048,'Спасение имущества','Если мы хотим убедить господина Гогельмогеля разрешить поселить здесь больше гномов, нам необходимо продемонстировать ему, какие мы хорошие! И я знаю только один способ.$b$bПрибамбасск осажден пиратами, но множество товаров, смытых с кораблей, остались нетронутыми... их просто вынесло на берег. Большинство из них можно найти на мелководье к югу от города.$b$bЕсли бы ты $gмог:могла; собрать там кое-что, то наша дружба стала бы еще прочнее! И, кроме того, этой противной гоблинской девчонке ничего не достанется.','Соберите 7 контейнеров с припасами Хитрой Шестеренки.','Выглядит неплохо! Какая удача!$B$BГоблины Хитрой Шестеренки непременно обрадуются, узнав, что их груз в целости и сохранности. Разумеется, вот и твоя награда за такой хороший поступок!$B$BВпрочем, нам еще многое предстоит сделать! Пора-пора!','Ну, давай-ка посмотрим, что там в этих коробках!','Вернитесь к Келси Стализвон в Прибамбасск.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спасение имущества',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если мы хотим убедить господина Гогельмогеля разрешить поселить здесь больше гномов, нам необходимо продемонстировать ему, какие мы хорошие! И я знаю только один способ.$b$bПрибамбасск осажден пиратами, но множество товаров, смытых с кораблей, остались нетронутыми... их просто вынесло на берег. Большинство из них можно найти на мелководье к югу от города.$b$bЕсли бы ты $gмог:могла; собрать там кое-что, то наша дружба стала бы еще прочнее! И, кроме того, этой противной гоблинской девчонке ничего не достанется.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 7 контейнеров с припасами Хитрой Шестеренки.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Выглядит неплохо! Какая удача!$B$BГоблины Хитрой Шестеренки непременно обрадуются, узнав, что их груз в целости и сохранности. Разумеется, вот и твоя награда за такой хороший поступок!$B$BВпрочем, нам еще многое предстоит сделать! Пора-пора!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, давай-ка посмотрим, что там в этих коробках!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Келси Стализвон в Прибамбасск.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25049,'Топая по лужам','У нас тут сложилась сложная ситуация! Отлично, что океан теперь так близко, что корабли могут попадать прямо в Прибамбасск. Но вместе с океаном пришли и отвратительные морские великаны, а это немалая угроза всему городу! Несомненно, если мы сможем справиться с этой угрозой, Гогельмогель оценит это по достоинству.$b$bНе волнуйся, я не предлагаю тебе поработать для нас лишь по доброте душевной! Я отлично награжу тебя, если поможешь нам!','Убейте 8 приливных странников.','Ох, теперь здесь станет гораздо более уютно!$B$BПо крайней мере до тех пор, пока из моря не придут новые... В любом случае – спасибо тебе!','Вернитесь к Келси Стализвон в Прибамбасск.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Топая по лужам',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У нас тут сложилась сложная ситуация! Отлично, что океан теперь так близко, что корабли могут попадать прямо в Прибамбасск. Но вместе с океаном пришли и отвратительные морские великаны, а это немалая угроза всему городу! Несомненно, если мы сможем справиться с этой угрозой, Гогельмогель оценит это по достоинству.$b$bНе волнуйся, я не предлагаю тебе поработать для нас лишь по доброте душевной! Я отлично награжу тебя, если поможешь нам!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 приливных странников.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ох, теперь здесь станет гораздо более уютно!$B$BПо крайней мере до тех пор, пока из моря не придут новые... В любом случае – спасибо тебе!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Келси Стализвон в Прибамбасск.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25050,'Спасательная ракета','Порт Хитрой Шестеренки на востоке отсюда оказался затоплен после наводнения, а несчастные гоблины и до сих пор остаются там! У них нет ни единого шанса выбраться, так как эти подлые пираты обстреливают каждую лодку, что покидает здесь пристань.$b$BНо что если мы поднимемся в небо? Этого они не ожидают! Здесь, на пристани, есть воздушный шар, наполненный горячим воздухом. С его помощью мы можем спасти гоблинов, да и о пиратах позаботиться. Господин Гогельмогель будет так доволен!$b$bОтправляйся на пристань и забирайся в воздушный шар, а я приду чуть позже, ок? Нужно захватить ракеты...','Прекрасно! Похоже, всем спасенным гоблинам удалось добраться домой, и даже не произошло ни одного взрыва. Пусть теперь эта гоблинская девчонка завидует!$B$BА вот и особая награда для тебя, мистер.','Вернитесь к Келси Стализвон в Танарис.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спасательная ракета',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Порт Хитрой Шестеренки на востоке отсюда оказался затоплен после наводнения, а несчастные гоблины и до сих пор остаются там! У них нет ни единого шанса выбраться, так как эти подлые пираты обстреливают каждую лодку, что покидает здесь пристань.$b$BНо что если мы поднимемся в небо? Этого они не ожидают! Здесь, на пристани, есть воздушный шар, наполненный горячим воздухом. С его помощью мы можем спасти гоблинов, да и о пиратах позаботиться. Господин Гогельмогель будет так доволен!$b$bОтправляйся на пристань и забирайся в воздушный шар, а я приду чуть позже, ок? Нужно захватить ракеты...',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно! Похоже, всем спасенным гоблинам удалось добраться домой, и даже не произошло ни одного взрыва. Пусть теперь эта гоблинская девчонка завидует!$B$BА вот и особая награда для тебя, мистер.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Келси Стализвон в Танарис.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25051,'Истребление пауков','Пауки, заполонившие Мглистую пещеру на северо-западе, – еще одна головная боль. Огры могли бы с ними справиться и сами – большая ошибка отвлекаться на них, когда поблизости шныряют силы Терамора.$B$BМне надо, чтобы кто-нибудь уничтожил паучьи яйца в Мглистой пещере и покончил с этим нашествием. Яйца можно найти в самых глубоких затянутых паутиной шахтах... ну, там же и пауков-охранников кладок, конечно.','Уничтожьте 8 яиц пауков Мглистой пещеры в Мглистой пещере.','Вернитесь к Крогу в деревню Гиблотопь в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Истребление пауков',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пауки, заполонившие Мглистую пещеру на северо-западе, – еще одна головная боль. Огры могли бы с ними справиться и сами – большая ошибка отвлекаться на них, когда поблизости шныряют силы Терамора.$B$BМне надо, чтобы кто-нибудь уничтожил паучьи яйца в Мглистой пещере и покончил с этим нашествием. Яйца можно найти в самых глубоких затянутых паутиной шахтах... ну, там же и пауков-охранников кладок, конечно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 8 яиц пауков Мглистой пещеры в Мглистой пещере.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Крогу в деревню Гиблотопь в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25052,'Сундук мертвеца','Будь я проклята, тут проходит действительно грандиозное сражение с пиратами! Мы делаем все возможное для того, чтобы ни Прибамбасск, ни наши новые гномьи дома здесь не оказались вновь под угрозой осады!$b$bУбивая пиратов, разумеется.$b$BКак насчет того, чтобы помочь нам? Не можем же мы допустить, чтобы какая-то зеленоносая и шайка ее разбойников обставили нас и убили больше пиратов. Я бы по достоинству оценила твою помощь!','Хорошо! Мы расчистили местность вокруг!','Вернитесь к Келси Стализвон в Бухту Сорванных Парусов, что в Танарисе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сундук мертвеца',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Будь я проклята, тут проходит действительно грандиозное сражение с пиратами! Мы делаем все возможное для того, чтобы ни Прибамбасск, ни наши новые гномьи дома здесь не оказались вновь под угрозой осады!$b$bУбивая пиратов, разумеется.$b$BКак насчет того, чтобы помочь нам? Не можем же мы допустить, чтобы какая-то зеленоносая и шайка ее разбойников обставили нас и убили больше пиратов. Я бы по достоинству оценила твою помощь!',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо! Мы расчистили местность вокруг!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Келси Стализвон в Бухту Сорванных Парусов, что в Танарисе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25053,'Дотла!','Знаешь, это место стало бы отличным домом для нас, гномов, если бы только оно не было таким грязным, захламленным и заполоненным пиратами! О пиратах мы позаботимся, а вот проблема грязи и мусора остается актуальной.$b$bЯ имею в виду, что ни один уважающий себя гном не станет жить в такой лачуге, как эти постройки на берегу! Так что вот, возьми эту бутылку горючего рома и сожги жалкие халупы дотла!','Подожгите лачуги на северо-западе, северо-восторе и юго-западе с помощью горючего рома.','Разве не прекрасно было смотреть на это?','Вернитесь к Келси Стализвон в Бухту Сорванных Парусов, что в Танарисе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дотла!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Знаешь, это место стало бы отличным домом для нас, гномов, если бы только оно не было таким грязным, захламленным и заполоненным пиратами! О пиратах мы позаботимся, а вот проблема грязи и мусора остается актуальной.$b$bЯ имею в виду, что ни один уважающий себя гном не станет жить в такой лачуге, как эти постройки на берегу! Так что вот, возьми эту бутылку горючего рома и сожги жалкие халупы дотла!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Подожгите лачуги на северо-западе, северо-восторе и юго-западе с помощью горючего рома.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Разве не прекрасно было смотреть на это?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Келси Стализвон в Бухту Сорванных Парусов, что в Танарисе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25055,'Усмирение стихий','Стихии разбушевались, |3-6($c). Землетрясения, от которых мы страдаем и которые грозят обрушить Стальгорн, – не обычные явления природы. Служители Земли пришли к мнению, что мы должны утихомирить стихии, пока они не разорвали Азерот на куски. Нам нужна твоя помощь, $n.$B$BЯ дам тебе мешок с припасами Служителей Земли. В нем ты найдешь две вещи: сапту стихий и тотем очищения. С помощью сапты ты увидишь, что творится в мире элементалей, и затем усмиришь встревоженных духов земли, воспользовавшись тотемом очищения.','Гаван Серое Перо хочет, чтобы с помощью сапты стихий и тотема очищения из припасов Служителей Земли вы усмирили 20 потревоженных духов земли.','Вернитесь к Гавану Серому Перу в Стальгорн.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Усмирение стихий',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Стихии разбушевались, |3-6($c). Землетрясения, от которых мы страдаем и которые грозят обрушить Стальгорн, – не обычные явления природы. Служители Земли пришли к мнению, что мы должны утихомирить стихии, пока они не разорвали Азерот на куски. Нам нужна твоя помощь, $n.$B$BЯ дам тебе мешок с припасами Служителей Земли. В нем ты найдешь две вещи: сапту стихий и тотем очищения. С помощью сапты ты увидишь, что творится в мире элементалей, и затем усмиришь встревоженных духов земли, воспользовавшись тотемом очищения.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Гаван Серое Перо хочет, чтобы с помощью сапты стихий и тотема очищения из припасов Служителей Земли вы усмирили 20 потревоженных духов земли.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гавану Серому Перу в Стальгорн.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25056,'Чумные мишки','Добудьте 5 шкур зачумленного мишки.','Дитерс, ты снова всех сделал! Эти шкуры просто превосходны.','Так... Сколько шкур тебе удалось раздобыть?','Вернитесь к аптекарю Дитерсу в Бастион, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чумные мишки',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 5 шкур зачумленного мишки.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Дитерс, ты снова всех сделал! Эти шкуры просто превосходны.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Так... Сколько шкур тебе удалось раздобыть?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к аптекарю Дитерсу в Бастион, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (25057,'В кандалы','Наша политика призыва на военную службу неопасных преступников из тюрем Штормграда нам же самим и принесла неприятности, $n. Некоторые из моих не слишком щепетильных солдат после нашей победы в Таурахо мародерствуют на руинах города.$b$bЭто серьезное нарушение дисциплины! Хуже того, подобное надругательство развязывает руки нашим врагам и они дерутся еще ожесточеннее, а ведь нашей конечной целью является мир.$b$bВозьми эти кандалы и призови мародеров Таурахо к порядку. Сначала попытайся с ними поговорить, но, возможно, тебе потребуется применить силу, чтобы арестовать их.','Вернитесь к генералу Готорну в передовую ставку в Южных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В кандалы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наша политика призыва на военную службу неопасных преступников из тюрем Штормграда нам же самим и принесла неприятности, $n. Некоторые из моих не слишком щепетильных солдат после нашей победы в Таурахо мародерствуют на руинах города.$b$bЭто серьезное нарушение дисциплины! Хуже того, подобное надругательство развязывает руки нашим врагам и они дерутся еще ожесточеннее, а ведь нашей конечной целью является мир.$b$bВозьми эти кандалы и призови мародеров Таурахо к порядку. Сначала попытайся с ними поговорить, но, возможно, тебе потребуется применить силу, чтобы арестовать их.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к генералу Готорну в передовую ставку в Южных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25058,'Разминирование по-гоблински','Один-ноль в пользу гоблинов! Какие все-таки недоумки все эти дворфы и гномы!','Вернитесь к Хамми Кофельнагель на дозорный пункт вождя на Затерянных островах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разминирование по-гоблински',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Один-ноль в пользу гоблинов! Какие все-таки недоумки все эти дворфы и гномы!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хамми Кофельнагель на дозорный пункт вождя на Затерянных островах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25059,'Оперативные данные из Таурахо','Генерал слишком занят мародерами Таурахо. Слишком мягок! Нам нужно сконцентрироваться на нашем следующем ударе по Орде.$b$bВ огне Таурахо может погибнуть ценная оперативная информация. Пока ты выполняешь задание генерала, поищи какие-нибудь карты или любые другие бумаги. Я немного говорю на орочьем языке, так что я смогу кое-что понять в документах, которые ты найдешь.','Обыщите руины Таурахо и найдите 3 документа оперативной информации Таурахо.','Что ты принесла мне? Хмм. Интересно. В этом документе из Оргриммара говорится, что Орда производит изменения в руководстве. Думаю, после того, что мы устроили в Таурахо, полетят шапки.$B$BА это что? Смертный приговор генералу! Об этом полезно знать... Очень полезно...','Ты уже обыскала руины?','Доставьте оперативную информацию из Таурахо послу Гейнсу в главную ставку в Южных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оперативные данные из Таурахо',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Генерал слишком занят мародерами Таурахо. Слишком мягок! Нам нужно сконцентрироваться на нашем следующем ударе по Орде.$b$bВ огне Таурахо может погибнуть ценная оперативная информация. Пока ты выполняешь задание генерала, поищи какие-нибудь карты или любые другие бумаги. Я немного говорю на орочьем языке, так что я смогу кое-что понять в документах, которые ты найдешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обыщите руины Таурахо и найдите 3 документа оперативной информации Таурахо.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что ты принесла мне? Хмм. Интересно. В этом документе из Оргриммара говорится, что Орда производит изменения в руководстве. Думаю, после того, что мы устроили в Таурахо, полетят шапки.$B$BА это что? Смертный приговор генералу! Об этом полезно знать... Очень полезно...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты уже обыскала руины?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доставьте оперативную информацию из Таурахо послу Гейнсу в главную ставку в Южных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25060,'Что такое "сумасшествие"','Убейте 10 уцелевших безумцев.','Меня очень беспокоят твои донесения об их поведении... беспокоят и слегка удивляют.$B$BЛучше бы Жестекрошшер сбежала на одном из этих кораблей...','Вернитесь к Келси Стализвон в лагерь Стализвон.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Что такое "сумасшествие"',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 уцелевших безумцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Меня очень беспокоят твои донесения об их поведении... беспокоят и слегка удивляют.$B$BЛучше бы Жестекрошшер сбежала на одном из этих кораблей...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Келси Стализвон в лагерь Стализвон.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25061,'Край земли','Фью! Эй! Да подойди поближе, $gболван:дурочка;, или ты думаешь, я могу читать твои мысли? Ох... Короче, подойди ко мне!$b$BТы славно $gпоработал:поработала; здесь на благо Гномрегана, $gдруг:подруга;! А если вспомнить, что ты $gделал:делала; все это лишь ради денег, так и вовсе потрясающая, просто превосходная работа! Но теперь Келси Стализвон может потребоваться более непосредственная помощь.$b$bОна вновь уехала отсюда... и просила передать тебе, чтобы ты $Gвстретился:встретилась; с ней на Пляже на Краю света, далеко на юге. Я бы не стал заставлять ее ждать!','Поговорите с Келси Стализвон на Станции Стализвон.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Край земли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Фью! Эй! Да подойди поближе, $gболван:дурочка;, или ты думаешь, я могу читать твои мысли? Ох... Короче, подойди ко мне!$b$BТы славно $gпоработал:поработала; здесь на благо Гномрегана, $gдруг:подруга;! А если вспомнить, что ты $gделал:делала; все это лишь ради денег, так и вовсе потрясающая, просто превосходная работа! Но теперь Келси Стализвон может потребоваться более непосредственная помощь.$b$bОна вновь уехала отсюда... и просила передать тебе, чтобы ты $Gвстретился:встретилась; с ней на Пляже на Краю света, далеко на юге. Я бы не стал заставлять ее ждать!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Келси Стализвон на Станции Стализвон.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25063,'Черепахизация','Нам совершенно необходимо получить предмет, о котором говорится в этом дневнике. Достать его из сундука вполне возможно, но вот сам предмет, похоже, опасен и нестабилен. Попытка вскрыть сундук силой может оказаться смертельной.$b$bК счастью, мы знаем, где находится ключ... по крайней мере, статистически. На восточном краю берега живет множество морских черепах. У одной из них должен быть ключ.','Добудьте ключ из желудка черепахи. Должно быть, его проглотила одна из гигантских береговых черепах.','Черт возьми, с каждым часом этот день становится все лучше и лучше! Еще чуть-чуть – и я бы улыбнулась.$B$BА ты не смотри, с тебя достаточно улыбок на сегодня.','Надеюсь, что в черепахоубийственном угаре ты не погнул ключ.','Вернитесь к Келси Стализвон в лагерь Стализвон.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Черепахизация',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нам совершенно необходимо получить предмет, о котором говорится в этом дневнике. Достать его из сундука вполне возможно, но вот сам предмет, похоже, опасен и нестабилен. Попытка вскрыть сундук силой может оказаться смертельной.$b$bК счастью, мы знаем, где находится ключ... по крайней мере, статистически. На восточном краю берега живет множество морских черепах. У одной из них должен быть ключ.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте ключ из желудка черепахи. Должно быть, его проглотила одна из гигантских береговых черепах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Черт возьми, с каждым часом этот день становится все лучше и лучше! Еще чуть-чуть – и я бы улыбнулась.$B$BА ты не смотри, с тебя достаточно улыбок на сегодня.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Надеюсь, что в черепахоубийственном угаре ты не погнул ключ.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Келси Стализвон в лагерь Стализвон.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (25064,'Морайа','Морайе нужна помощь с ящерами. Будет свободная минута – найди ее в другом конце крепости Черного Копья и поговори.','Поговорите с Морайей.','Привет, дорогуша. Тебя прислал Вол\'джин? Как мило с его стороны.$B$BДа, помощь мне нужна, и на месте тебе сидеть не придется.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Морайа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Морайе нужна помощь с ящерами. Будет свободная минута – найди ее в другом конце крепости Черного Копья и поговори.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Морайей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Привет, дорогуша. Тебя прислал Вол\'джин? Как мило с его стороны.$B$BДа, помощь мне нужна, и на месте тебе сидеть не придется.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25065,'И ты, Брут?','Пришло время завершить это дело. Исходя из того, что мы выяснили, этот таинственный предмет находится по власти некоего "сообразительного" животного, описанного в журнале. Мы не можем с уверенностью сказать, что случилось с этим существом, так что будь осторожнее.$b$bЭтот... "Мордофарш" скрывается где-то среди холмов, недалеко от того места, где гоблины хоронят своих мертвецов. Разыщи кладбище, а где-то неподалеку найдешь и того, кто нам нужен.','Добудьте сундук Мордофарша.','Вернитесь к Келси Стализвон в лагерь Стализвон.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','И ты, Брут?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пришло время завершить это дело. Исходя из того, что мы выяснили, этот таинственный предмет находится по власти некоего "сообразительного" животного, описанного в журнале. Мы не можем с уверенностью сказать, что случилось с этим существом, так что будь осторожнее.$b$bЭтот... "Мордофарш" скрывается где-то среди холмов, недалеко от того места, где гоблины хоронят своих мертвецов. Разыщи кладбище, а где-то неподалеку найдешь и того, кто нам нужен.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте сундук Мордофарша.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Келси Стализвон в лагерь Стализвон.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25066,'Гордость Кезана','Нет, ну натурально – уже ни в какие ворота не лезет! Эти гномы... они просто патологически неспособны вовремя остановиться!$B$BТут уже задета честь гоблинов! Давай-ка, полезай в "Гордость Кезана", $n, и покажи этим недомеркам, почем фунт лиха!$B$BСкажи, когда будешь $gготов:готова;!','Сбейте 10 гномреганских истребителей-невидимок.','ДА!','Вернитесь к Хамми Кофельнагель на дозорный пункт вождя на Затерянных островах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гордость Кезана',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нет, ну натурально – уже ни в какие ворота не лезет! Эти гномы... они просто патологически неспособны вовремя остановиться!$B$BТут уже задета честь гоблинов! Давай-ка, полезай в "Гордость Кезана", $n, и покажи этим недомеркам, почем фунт лиха!$B$BСкажи, когда будешь $gготов:готова;!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сбейте 10 гномреганских истребителей-невидимок.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','ДА!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хамми Кофельнагель на дозорный пункт вождя на Затерянных островах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (25067,'Громодром: Ненормий!','Одержите победу над Ненормием.','Впечатляющее начало. Готовься к большему.','Ненормий побежден','Вернитесь к Катрине Тернер в Прибамбасск, что в Танарисе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Громодром: Ненормий!',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Одержите победу над Ненормием.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Впечатляющее начало. Готовься к большему.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Ненормий побежден',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Катрине Тернер в Прибамбасск, что в Танарисе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25068,'Рассыпающееся прошлое','Существа, блуждающие по этим руинам – земельники, древние прародители дворфов, создания титанов, принимавшие участие в изначальном формировании мира.$b$bОднако еще тысячи лет назад что-то произошло, и земельники оказались испорчены и искажены. Тех, что встретились нам недавно, похоже, постигла та же участь. Впрочем, эти растерянно блуждающие создания могут принести пользу и нам.$b$bУничтожь земельников среди руин и собери драгоценные камни, которыми они инкрустированы. Магическая энергия этих камней ценна и сама по себе, и как предмет изучения.','Соберите 5 самоцветов земли.','Изумительно. Подумать только, те, кто создавали наш мир, создали и это...','Вернитесь к Андорену Восходу Солнца.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рассыпающееся прошлое',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Существа, блуждающие по этим руинам – земельники, древние прародители дворфов, создания титанов, принимавшие участие в изначальном формировании мира.$b$bОднако еще тысячи лет назад что-то произошло, и земельники оказались испорчены и искажены. Тех, что встретились нам недавно, похоже, постигла та же участь. Впрочем, эти растерянно блуждающие создания могут принести пользу и нам.$b$bУничтожь земельников среди руин и собери драгоценные камни, которыми они инкрустированы. Магическая энергия этих камней ценна и сама по себе, и как предмет изучения.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 5 самоцветов земли.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Изумительно. Подумать только, те, кто создавали наш мир, создали и это...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Андорену Восходу Солнца.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (25069,'Тайны Ульдума','Мы готовы войти в сам вестибюль, $n. Наступил момент поистине уникальной значимости.$b$bПо тем записям, что ты $gпринес:принесла; можно сделать вывод, что на месте этих руин когда-то находились огромные врата в сам Ульдум. Землетрясение, расколовшее ворота, возможно засыпало туннели, но, тем не менее, есть шанс обнаружить удивительные артефакты, сокрытые здесь.$b$bПостарайся найти среди руин что-то неповрежденное, пригодное для дальнейших исследований. Дух захватывает от волнения!','Осмотрите вестибюль Ульдума в поисках неповрежденных артефактов.','Тысячелетиями этот сундук лежал запечатанным и нетронутым.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тайны Ульдума',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы готовы войти в сам вестибюль, $n. Наступил момент поистине уникальной значимости.$b$bПо тем записям, что ты $gпринес:принесла; можно сделать вывод, что на месте этих руин когда-то находились огромные врата в сам Ульдум. Землетрясение, расколовшее ворота, возможно засыпало туннели, но, тем не менее, есть шанс обнаружить удивительные артефакты, сокрытые здесь.$b$bПостарайся найти среди руин что-то неповрежденное, пригодное для дальнейших исследований. Дух захватывает от волнения!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Осмотрите вестибюль Ульдума в поисках неповрежденных артефактов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тысячелетиями этот сундук лежал запечатанным и нетронутым.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25070,'Что сокрыто внутри','Стоило вам коснуться сундука, как где-то вдалеке послышался шум. Грохот тяжелых шагов эхом отзывается в туннелях за вашей спиной, а крышка сундука тем временем начинает закрываться сама собой.$b$bЧто-то приближается!','Победите привратника.','Сундук вновь открывается, а весь вестибюль погружается в тишину.','Откройте древний сундук.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Что сокрыто внутри',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Стоило вам коснуться сундука, как где-то вдалеке послышался шум. Грохот тяжелых шагов эхом отзывается в туннелях за вашей спиной, а крышка сундука тем временем начинает закрываться сама собой.$b$bЧто-то приближается!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите привратника.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сундук вновь открывается, а весь вестибюль погружается в тишину.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Откройте древний сундук.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (25071,'FLAG - Purple Murloc') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','FLAG - Purple Murloc',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25072,'Несколько хороших гоблинов','Знаешь, мы ведь не веселые песенки тут с гномами распевали и не развлекались игрой с опасными устройствами. Мои ребята пытались зачистить этот улей на протяжении целой недели! Вот только наши потери оказались настолько велики, что теперь у насекомых есть определенное преимущество.$b$bПовезло хоть в одном – этим тварям мы либо вообще не нравимся на вкус, либо нравимся настолько, что они хранят нас в качестве деликатеса в коконах. Мне нужно, чтобы ты $gспас:спасла; моих ребят, оказавшихся в этих коконах.','Освободите из коконов Хаззали 8 пленных гоблинов – охотников на жуков.','Спасибо, твоя помощь просто неоценима! Видишь ли, потерять солдата – значит, потерять огневую мощь. И воинский дух. И оружие. И запасной боекомплект, который ты одолжил этому парню.$B$BНу, ты сам все понимаешь.','Вернитесь к Зеке Волочилкинсу на стоянку бутлегеров в Танарис.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Несколько хороших гоблинов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Знаешь, мы ведь не веселые песенки тут с гномами распевали и не развлекались игрой с опасными устройствами. Мои ребята пытались зачистить этот улей на протяжении целой недели! Вот только наши потери оказались настолько велики, что теперь у насекомых есть определенное преимущество.$b$bПовезло хоть в одном – этим тварям мы либо вообще не нравимся на вкус, либо нравимся настолько, что они хранят нас в качестве деликатеса в коконах. Мне нужно, чтобы ты $gспас:спасла; моих ребят, оказавшихся в этих коконах.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Освободите из коконов Хаззали 8 пленных гоблинов – охотников на жуков.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо, твоя помощь просто неоценима! Видишь ли, потерять солдата – значит, потерять огневую мощь. И воинский дух. И оружие. И запасной боекомплект, который ты одолжил этому парню.$B$BНу, ты сам все понимаешь.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Зеке Волочилкинсу на стоянку бутлегеров в Танарис.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25073,'Деревня Сен\'джин','Ты совсем $gмолодой:молодая;, но справляешься отлично. Не сомневаюсь, что еще не раз услышу твое имя.$B$BА теперь ступай на северо-запад через лощину и доберись до деревни Сен\'джин. Найди в ней мастера Гадрина – думаю, он поручит тебе парочку заданий, прежде чем отправить в дебри Дуротара.$B$BПомни, $n, мы не всегда согласны с юным Адским Криком, но им движут благородные мотивы, и всех нас объединяет Орда. Ступай и не посрами Черное Копье.','Поговорите с мастером Гадрином в деревне Сен\'джин.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Деревня Сен\'джин',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты совсем $gмолодой:молодая;, но справляешься отлично. Не сомневаюсь, что еще не раз услышу твое имя.$B$BА теперь ступай на северо-запад через лощину и доберись до деревни Сен\'джин. Найди в ней мастера Гадрина – думаю, он поручит тебе парочку заданий, прежде чем отправить в дебри Дуротара.$B$BПомни, $n, мы не всегда согласны с юным Адским Криком, но им движут благородные мотивы, и всех нас объединяет Орда. Ступай и не посрами Черное Копье.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с мастером Гадрином в деревне Сен\'джин.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (25074,'Встретимся в Форте Триумфа','Ты слышала? Генерал не добрался!$B$BУбит в поле, как какая-то собака!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Встретимся в Форте Триумфа',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты слышала? Генерал не добрался!$B$BУбит в поле, как какая-то собака!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (25075,'Сбор деталей','Эти большие дворфийские осадные машины не подходят для ближнего боя в Боевом Шраме.$b$bЯ собираюсь сконструировать другие, но для начала мне нужны дополнительные детали. В Боевом Шраме осталось много обломков. Мне $gнужен инициативный:нужна инициативная:c; |3-6($c), $gкоторый:которая:c; сможет мне их принести.$b$bЯ говорю о тебе, $n.','Принесите детали Миззи Поршняки в Форт Триумфа в Южных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сбор деталей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти большие дворфийские осадные машины не подходят для ближнего боя в Боевом Шраме.$b$bЯ собираюсь сконструировать другие, но для начала мне нужны дополнительные детали. В Боевом Шраме осталось много обломков. Мне $gнужен инициативный:нужна инициативная:c; |3-6($c), $gкоторый:которая:c; сможет мне их принести.$b$bЯ говорю о тебе, $n.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите детали Миззи Поршняки в Форт Триумфа в Южных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (25076,'Приручение зверя','$n, до сих пор ты $gтренировал:тренировала; свои навыки одиночного боя. Пришло время научить тебя новому виду сражений: при помощи обученного питомца.$b$bИспользуй этот хлыст на сумеречнице-вампире, чтобы она стала служить тебе верой и правдой. Приручение происходит не сразу, но я верю, что в итоге у тебя все получится.','Приручите сумеречницу-вампира при помощи хлыста приручения.','Приручите сумеречницу-вампира.','Вернитесь к Дедлоу Полыннику в Брилл, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приручение зверя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, до сих пор ты $gтренировал:тренировала; свои навыки одиночного боя. Пришло время научить тебя новому виду сражений: при помощи обученного питомца.$b$bИспользуй этот хлыст на сумеречнице-вампире, чтобы она стала служить тебе верой и правдой. Приручение происходит не сразу, но я верю, что в итоге у тебя все получится.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Приручите сумеречницу-вампира при помощи хлыста приручения.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Приручите сумеречницу-вампира.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дедлоу Полыннику в Брилл, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (25077,'Приручение зверя','Последний раз мы видели молодых зачумленных мишек в горах между этими местами и Чумными землями. Для защитных сооружений Бастиона передвижение этих медведей в Тирисфальские леса служит испытанием, но для нас, охотников, их переход – это благо.$b$bДокажи мне, что наш последний урок кое-чему научил тебя. Иди далеко на восток и используй хлыст приручения.','Используйте хлыст приручения, чтобы подружиться с зачумленным мишкой.','Приручите зачумленного мишку.','Вернитесь к Дедлоу Полыннику в Брилл, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приручение зверя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Последний раз мы видели молодых зачумленных мишек в горах между этими местами и Чумными землями. Для защитных сооружений Бастиона передвижение этих медведей в Тирисфальские леса служит испытанием, но для нас, охотников, их переход – это благо.$b$bДокажи мне, что наш последний урок кое-чему научил тебя. Иди далеко на восток и используй хлыст приручения.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте хлыст приручения, чтобы подружиться с зачумленным мишкой.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Приручите зачумленного мишку.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дедлоу Полыннику в Брилл, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (25078,'Приручение зверя','Твое последнее испытание касается пауков, которые обитают в Долине ядовитых пауков, к северу от Бастиона. Да, даже эти создания могут стать ценным союзником. Мне встречалось множество охотников, которые рассчитвают на этих пауков, как на оружие в своем арсенале.$b$bИспользуй этот хлыст, чтобы приучить одного из пауков, а затем возвращайся ко мне.','Приручите злобного ночного кругопряда при помощи хлыста приручения.','Приручите злобного ночного кругопряда.','Вернитесь к Дедлоу Полыннику в Брилл, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приручение зверя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Твое последнее испытание касается пауков, которые обитают в Долине ядовитых пауков, к северу от Бастиона. Да, даже эти создания могут стать ценным союзником. Мне встречалось множество охотников, которые рассчитвают на этих пауков, как на оружие в своем арсенале.$b$bИспользуй этот хлыст, чтобы приучить одного из пауков, а затем возвращайся ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Приручите злобного ночного кругопряда при помощи хлыста приручения.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Приручите злобного ночного кругопряда.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дедлоу Полыннику в Брилл, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25079,'Игры с порохом','Победите специалиста по минированию возле Боевого Шрама и отберите у него бочонок взрывчатой смеси М04И-8СЕХ.','Прекрасно! Поставь бочонок вон туда. Я измерю кое-какие параметры, раз уж я все равно в защитном костюме.','Ты достал бочонок взрывчатой смеси М04И-8СЕХ?$B$BКогда будешь нести, не тряси его...','Принесите бочонок взрывчатой смеси М04И-8СЕХ Миззи Поршняки в Форт Триумфа в Южных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Игры с порохом',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите специалиста по минированию возле Боевого Шрама и отберите у него бочонок взрывчатой смеси М04И-8СЕХ.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно! Поставь бочонок вон туда. Я измерю кое-какие параметры, раз уж я все равно в защитном костюме.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты достал бочонок взрывчатой смеси М04И-8СЕХ?$B$BКогда будешь нести, не тряси его...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите бочонок взрывчатой смеси М04И-8СЕХ Миззи Поршняки в Форт Триумфа в Южных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25080,'Батарейки в комплект не входят','Окей! С запчастями, которые ты $gпринес:принесла; мне, моя многозадачная осадная машина почти готова. Все, что мне еще нужно, это компактный источник питания.$b$bЯ обратила внимание, что местная живность так и искрит. Не $gмог:могла; бы ты поохотиться на громоголовов и принести мне целую электрогизаторную железу? Возможно, придется убить нескольких, прежде чем найдешь хорошую железу.','<Когда вы вручаете железу Миззи, ее бьет током и она падает на землю.>$B$BАй, АЙ! Это ужасно! Я в восторге!','Уметь стрелять молниями – это колоссальное эволюционное достижение.','Отнесите железу Миззи Поршняки в Форт Триумфа в Южных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Батарейки в комплект не входят',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Окей! С запчастями, которые ты $gпринес:принесла; мне, моя многозадачная осадная машина почти готова. Все, что мне еще нужно, это компактный источник питания.$b$bЯ обратила внимание, что местная живность так и искрит. Не $gмог:могла; бы ты поохотиться на громоголовов и принести мне целую электрогизаторную железу? Возможно, придется убить нескольких, прежде чем найдешь хорошую железу.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Когда вы вручаете железу Миззи, ее бьет током и она падает на землю.>$B$BАй, АЙ! Это ужасно! Я в восторге!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Уметь стрелять молниями – это колоссальное эволюционное достижение.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите железу Миззи Поршняки в Форт Триумфа в Южных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (25081,'Захватить Боевой Шрам','Орда отчаянно дралась с нами, из своей крепости к западу отсюда. И бои все еще продолжаются, даже несмотря на то, что уже земля раскалывается у нас под ногами.$b$bКто-то должен повлиять на ситуацию! Я хочу, чтобы ты $gпробрался:пробралась; в Боевой Шрам и $gпомог:помогла; моим людям разбить войска Орды.$b$bВ центре Боевого Шрама ты увидишь флаг, показывающий, кто контролирует эту территорию. Если ты поможешь захватить Шрам, это будет огромным достижением. Конечно, если этого еще не сделал кто-то другой.','Флаг Боевого Шрама найден','Вернитесь к командиру Робертсу в Форт Триумфа в Южных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Захватить Боевой Шрам',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Орда отчаянно дралась с нами, из своей крепости к западу отсюда. И бои все еще продолжаются, даже несмотря на то, что уже земля раскалывается у нас под ногами.$b$bКто-то должен повлиять на ситуацию! Я хочу, чтобы ты $gпробрался:пробралась; в Боевой Шрам и $gпомог:помогла; моим людям разбить войска Орды.$b$bВ центре Боевого Шрама ты увидишь флаг, показывающий, кто контролирует эту территорию. Если ты поможешь захватить Шрам, это будет огромным достижением. Конечно, если этого еще не сделал кто-то другой.',`details_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Флаг Боевого Шрама найден',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру Робертсу в Форт Триумфа в Южных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (25082,'Выкурить жуков','Мы никогда не узнаем, почему Верховное командование решило, что место, где силитиды строят свои жилища – идеально подходит для крепости. Теперь эти мелкие твари роют ходы под нашими укреплениями и мешают нашим планам. Надо выкурить их оттуда!$b$bВозьми вот это ведро пылающей смолы и вылей смолу на жилища силитидов сразу за главными воротами. Они похожи на большие кучи песка. Убивай всех, кто покажется снаружи, но будь $gосторожен:осторожна;, $n, скорее всего их будет очень много.','Вернитесь к Логану Удару Когтя в Форт Триумфа в Южных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Выкурить жуков',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы никогда не узнаем, почему Верховное командование решило, что место, где силитиды строят свои жилища – идеально подходит для крепости. Теперь эти мелкие твари роют ходы под нашими укреплениями и мешают нашим планам. Надо выкурить их оттуда!$b$bВозьми вот это ведро пылающей смолы и вылей смолу на жилища силитидов сразу за главными воротами. Они похожи на большие кучи песка. Убивай всех, кто покажется снаружи, но будь $gосторожен:осторожна;, $n, скорее всего их будет очень много.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Логану Удару Когтя в Форт Триумфа в Южных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25083,'Дрессировка','И еще одна вещь, $gохотник:охотница;. Тебе нужно поговорить в Подгороде с Аполием. Он поделится с тобой еще некоторыми полезными знаниями, необходимыми, чтобы ухаживать за питомцем и обучать его.$b$bТы найдешь Аполия в Квартале Воинов.','Поговорите с Аполием в Квартале Воинов в Подгороде.','Вернитесь к Ганаару на остров Лазурной Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дрессировка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','И еще одна вещь, $gохотник:охотница;. Тебе нужно поговорить в Подгороде с Аполием. Он поделится с тобой еще некоторыми полезными знаниями, необходимыми, чтобы ухаживать за питомцем и обучать его.$b$bТы найдешь Аполия в Квартале Воинов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Аполием в Квартале Воинов в Подгороде.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ганаару на остров Лазурной Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25084,'Растущая угроза','Один момент, |3-6($c).$b$bУ нас тут есть более серьезные проблемы, нежели конец света. Свинобразы напали на наш дозор. Мы были согласны оставить их в покое, когда они поселились в Лабиринтах Иглошкурых, но с каждым днем они подходят все ближе и ближе к лагерю.$b$bМахка, да благословенно будет ее доброе сердце, никогда не простит мне, если я начну их убивать, но если ты поможешь мне прогнать свинобразов, шатающихся возле лагеря, я буду очень тебе благодарен.','Убейте 13 свинобразов из племени Иглогривых.','И я, и Служители Земли благодарны тебе.$B$BМожет быть когда-нибудь мы научимся решать проблемы с этими свиньями словами, но пока что мы вряд ли сможем делать свое дело, если будем убиты в собственной постели.','Вернитесь к Дорну Краснозему в Кремневый лагерь в Южных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Растущая угроза',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Один момент, |3-6($c).$b$bУ нас тут есть более серьезные проблемы, нежели конец света. Свинобразы напали на наш дозор. Мы были согласны оставить их в покое, когда они поселились в Лабиринтах Иглошкурых, но с каждым днем они подходят все ближе и ближе к лагерю.$b$bМахка, да благословенно будет ее доброе сердце, никогда не простит мне, если я начну их убивать, но если ты поможешь мне прогнать свинобразов, шатающихся возле лагеря, я буду очень тебе благодарен.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 13 свинобразов из племени Иглогривых.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','И я, и Служители Земли благодарны тебе.$B$BМожет быть когда-нибудь мы научимся решать проблемы с этими свиньями словами, но пока что мы вряд ли сможем делать свое дело, если будем убиты в собственной постели.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дорну Краснозему в Кремневый лагерь в Южных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25085,'Кривозуб','Уна часто бывала в лагере Таурахо. Она рассказывала мне о пойманном там свинобразе по имени Кривозуб. Для свинобраза он довольно умен.$b$bЯ часто думал, почему свинобразы в последнее время такие злобные, может быть, дело в том, что Кривозуб сумел сбежать из Таурахо. Если это так, то, конечно, именно он ими командует.$b$bНа холме к северо-западу отсюда есть большая хижина. Если ты найдешь Кривозуба там, убей его.','Убейте Кривозуба.','Какое облегчение. Может быть теперь остальные вернутся к своим собственным делам. Чем меньше здесь будет резни, тем лучше.','Вернитесь к Дорну Краснозему в Южные Степи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кривозуб',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Уна часто бывала в лагере Таурахо. Она рассказывала мне о пойманном там свинобразе по имени Кривозуб. Для свинобраза он довольно умен.$b$bЯ часто думал, почему свинобразы в последнее время такие злобные, может быть, дело в том, что Кривозуб сумел сбежать из Таурахо. Если это так, то, конечно, именно он ими командует.$b$bНа холме к северо-западу отсюда есть большая хижина. Если ты найдешь Кривозуба там, убей его.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Кривозуба.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Какое облегчение. Может быть теперь остальные вернутся к своим собственным делам. Чем меньше здесь будет резни, тем лучше.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дорну Краснозему в Южные Степи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (25086,'Кремневый лагерь','Ты можешь оказать мне огромную услугу, $n. Дядя моей золовки – один из Служителей Земли, и сейчас он здесь, в Степях изучает последствия катаклизма в Кремневом лагере. Он говорит, что их лагерь окружен свинобразами, и непонятно, что эти свинобразы собираются предпринять.$b$bНе $gмог:могла; бы ты проверить, все ли там в порядке с Дорном Красноземом? Не могу допустить, чтобы что-нибудь случилось с ним, это член нашей семьи.','Что? Малыш Логан думает, что мне нужна защита?$B$BДа я сам тут всех защищаю!$B$BСвинобразы неистовствуют. Они наводят ужас на весь юг, и только мы в силах им противостоять.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кремневый лагерь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты можешь оказать мне огромную услугу, $n. Дядя моей золовки – один из Служителей Земли, и сейчас он здесь, в Степях изучает последствия катаклизма в Кремневом лагере. Он говорит, что их лагерь окружен свинобразами, и непонятно, что эти свинобразы собираются предпринять.$b$bНе $gмог:могла; бы ты проверить, все ли там в порядке с Дорном Красноземом? Не могу допустить, чтобы что-нибудь случилось с ним, это член нашей семьи.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что? Малыш Логан думает, что мне нужна защита?$B$BДа я сам тут всех защищаю!$B$BСвинобразы неистовствуют. Они наводят ужас на весь юг, и только мы в силах им противостоять.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (25087,'Доклад Двукоссе','Самые первые укрепления в Степях построены дворфами Бейл Модана, Альянс перед ними в долгу.$b$bИх командующий, генерал Двукосса, очень отважен. Один из лучших. С тех пор, как он патрулирует юг, Орда ведет там себя тише воды, ниже травы.$b$bЯ бы очень хотел узнать его мнение об обстановке тут у нас, чтобы мы могли скоординировать наши последующие действия. Не $gмог:могла; бы ты отнести этот отчет ему на передовую?','Доставьте отчет с передовой генералу Двукоссе в Обход Двукоссы в Южных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Доклад Двукоссе',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Самые первые укрепления в Степях построены дворфами Бейл Модана, Альянс перед ними в долгу.$b$bИх командующий, генерал Двукосса, очень отважен. Один из лучших. С тех пор, как он патрулирует юг, Орда ведет там себя тише воды, ниже травы.$b$bЯ бы очень хотел узнать его мнение об обстановке тут у нас, чтобы мы могли скоординировать наши последующие действия. Не $gмог:могла; бы ты отнести этот отчет ему на передовую?',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доставьте отчет с передовой генералу Двукоссе в Обход Двукоссы в Южных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (25089,'По ту сторону могилы','Дарнелл говорил мне, что вы двое уже знакомы. Это хорошо, потому что вас обоих я собираюсь отправить в Похоронный Звон, что к северу отсюда.$b$bПоговори в Похоронном Звоне со стражем смерти Салтеном. Он расскажет все, что тебе нужно знать.','Поговорите со стражем смерти Салтеном в Похоронном Звоне в Тирисфальских лесах.','Валь\'киры уже утомились воскрешать новичков. С сегодняшнего утра я видел уже пару десятков свежих тел, бегущих по этому холму.$b$bВпрочем, ты – самый многообещающий $r из всех, кого я сегодня видел.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','По ту сторону могилы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Дарнелл говорил мне, что вы двое уже знакомы. Это хорошо, потому что вас обоих я собираюсь отправить в Похоронный Звон, что к северу отсюда.$b$bПоговори в Похоронном Звоне со стражем смерти Салтеном. Он расскажет все, что тебе нужно знать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите со стражем смерти Салтеном в Похоронном Звоне в Тирисфальских лесах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Валь\'киры уже утомились воскрешать новичков. С сегодняшнего утра я видел уже пару десятков свежих тел, бегущих по этому холму.$b$bВпрочем, ты – самый многообещающий $r из всех, кого я сегодня видел.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25090,'Грязная работа','Плеть проникла в Тирисфальские леса и заполонила всю местность.$B$BМне нужен кто-то, кто мог бы сразится с гниющими мертвецами и разложившимися трупами, которые обосновались на этой маленькой ферме. Разбросай их кости и принеси их гнилые когти – за них ты получишь награду от стражей смерти.','Принесите 7 гнилых когтей стражу смерти Диллинжеру в поместье "Остывший Очаг".','Очень хорошо! Ты просто мастер по превращению нежити в куски гниющего мяса.','Ты уже справился с тем заданием, которое я тебе поручил? Несешь мне гнилые когти?','Вернитесь к стражу смерти Диллинжеру в поместье "Остывший Очаг", что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Грязная работа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Плеть проникла в Тирисфальские леса и заполонила всю местность.$B$BМне нужен кто-то, кто мог бы сразится с гниющими мертвецами и разложившимися трупами, которые обосновались на этой маленькой ферме. Разбросай их кости и принеси их гнилые когти – за них ты получишь награду от стражей смерти.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 7 гнилых когтей стражу смерти Диллинжеру в поместье "Остывший Очаг".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Очень хорошо! Ты просто мастер по превращению нежити в куски гниющего мяса.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты уже справился с тем заданием, которое я тебе поручил? Несешь мне гнилые когти?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к стражу смерти Диллинжеру в поместье "Остывший Очаг", что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (25091,'Застава Скорбных Песков','Если тебе еще нужна работа, то могу поделиться информацией.$b$bЯ знаю одного эльфа по имени Трентон Молот Света. Вот уже много лет он помешан на здешних песчаных троллях. Он твердо намерен найти какой-то мистический меч, сделанный ими, и буквально недавно собрал наконец-то отряд, чтобы отправиться на Заставу Скорбных Песков и приступить к поискам.$b$bГоворят, он выбросил троллей из их лагерей и основал там лавку. Больше я ничего о нем не слышал, но ты можешь найти его на западе, рядом с Зул\'Фарраком.','Поговорите с Трентоном Молотом Света на Заставе Скорбных Песков.','Тебя прислал Синь? Ценю его участие.$B$BЯ хочу разыскать Сул\'траз. Если желаешь помочь, поговори с Магозой... Он пока что готов сотрудничать.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Застава Скорбных Песков',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если тебе еще нужна работа, то могу поделиться информацией.$b$bЯ знаю одного эльфа по имени Трентон Молот Света. Вот уже много лет он помешан на здешних песчаных троллях. Он твердо намерен найти какой-то мистический меч, сделанный ими, и буквально недавно собрал наконец-то отряд, чтобы отправиться на Заставу Скорбных Песков и приступить к поискам.$b$bГоворят, он выбросил троллей из их лагерей и основал там лавку. Больше я ничего о нем не слышал, но ты можешь найти его на западе, рядом с Зул\'Фарраком.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Трентоном Молотом Света на Заставе Скорбных Песков.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебя прислал Синь? Ценю его участие.$B$BЯ хочу разыскать Сул\'траз. Если желаешь помочь, поговори с Магозой... Он пока что готов сотрудничать.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25092,'Усмирение стихий','Стихии разбушевались, |3-6($c). Землетрясения, от которых мы страдаем, и пожары, грозящие спалить Оргриммар, – не обычные явления природы. Служители Земли пришли к мнению, что мы должны утихомирить стихии, пока они не разорвали Азерот на куски. Нам нужна твоя помощь, $n.$B$BЯ дам тебе мешок с припасами Служителей Земли. В нем ты найдешь две вещи: сапту стихий и тотем очищения. С помощью сапты ты увидишь, что творится в мире элементалей, и затем усмиришь потревоженных духов огня, воспользовавшись тотемом очищения.','Провидица Бахура хочет, чтобы с помощью сапты стихий и тотема очищения из припасов Служителей Земли вы усмирили 20 потревоженных духов огня.','Вернитесь к провидице Бахуре в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Усмирение стихий',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Стихии разбушевались, |3-6($c). Землетрясения, от которых мы страдаем, и пожары, грозящие спалить Оргриммар, – не обычные явления природы. Служители Земли пришли к мнению, что мы должны утихомирить стихии, пока они не разорвали Азерот на куски. Нам нужна твоя помощь, $n.$B$BЯ дам тебе мешок с припасами Служителей Земли. В нем ты найдешь две вещи: сапту стихий и тотем очищения. С помощью сапты ты увидишь, что творится в мире элементалей, и затем усмиришь потревоженных духов огня, воспользовавшись тотемом очищения.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Провидица Бахура хочет, чтобы с помощью сапты стихий и тотема очищения из припасов Служителей Земли вы усмирили 20 потревоженных духов огня.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к провидице Бахуре в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25093,'Обезглавить ШРУ','Этих орков на побережье убили солдаты Альянса. Просто так, ни за что. Мы их не провоцировали. Мы вообще ничего не делали.$B$BНадо отомстить за их смерть, $n. Ты нам поможешь?$B$B<Аггра с трудом сдерживает ярость.>$B$BТам, на берегу, ты найдешь трех лидеров ШРУ. Принеси мне их головы.','Убейте командира Арингтона, Цин Черный Клинок и Алексия Тихого Воя и отрежьте им головы.','Ты отомстила за смерть наших товарищей?','Вернитесь к Аггре на дозорный пункт вождя на Затерянных островах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обезглавить ШРУ',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этих орков на побережье убили солдаты Альянса. Просто так, ни за что. Мы их не провоцировали. Мы вообще ничего не делали.$B$BНадо отомстить за их смерть, $n. Ты нам поможешь?$B$B<Аггра с трудом сдерживает ярость.>$B$BТам, на берегу, ты найдешь трех лидеров ШРУ. Принеси мне их головы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте командира Арингтона, Цин Черный Клинок и Алексия Тихого Воя и отрежьте им головы.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты отомстила за смерть наших товарищей?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аггре на дозорный пункт вождя на Затерянных островах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (25094,'Громодром: Зумонга!','Впечатляет! Но тебе предстоит сразиться не только с обычными людьми!$b$BСо следующим противником справиться будет нелегко... Не пропусти его хук справа! Да и слева. Я бы вообще от его кулаков старался держаться подальше. Всех кулаков.','Победите в бою Зумонгу.','Неплохо. Впрочем, я тебя не держу.','Зумонга побежден','Вернитесь к Катрине Тернер в Прибамбасск, что в Танарисе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Громодром: Зумонга!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Впечатляет! Но тебе предстоит сразиться не только с обычными людьми!$b$BСо следующим противником справиться будет нелегко... Не пропусти его хук справа! Да и слева. Я бы вообще от его кулаков старался держаться подальше. Всех кулаков.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите в бою Зумонгу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Неплохо. Впрочем, я тебя не держу.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Зумонга побежден',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Катрине Тернер в Прибамбасск, что в Танарисе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (25095,'Громодром: Саринекс!','Надеюсь, ты $gготов:готова; к следующему поединку, $n. Одна-единственная ошибка здесь будет стоить тебе жизни. И твою смерть сложно будет назвать легкой! Но ведь именно за это зрелище люди готовы платить деньги, так ведь?$b$bНадеюсь, ты не боишься насекомых...','Победите в бою Саринекса.','Впечатляет. Немногие способны встретиться с силитидом один на один, не говоря уже о том, чтобы одержать победу.','Саринекс побежден','Вернитесь к Катрине Тернер в Прибамбасск, что в Танарисе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Громодром: Саринекс!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Надеюсь, ты $gготов:готова; к следующему поединку, $n. Одна-единственная ошибка здесь будет стоить тебе жизни. И твою смерть сложно будет назвать легкой! Но ведь именно за это зрелище люди готовы платить деньги, так ведь?$b$bНадеюсь, ты не боишься насекомых...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите в бою Саринекса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Впечатляет. Немногие способны встретиться с силитидом один на один, не говоря уже о том, чтобы одержать победу.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Саринекс побежден',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Катрине Тернер в Прибамбасск, что в Танарисе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (25096,'Громодром: Принц Мош!','Нам бы пришлось притащить сюда огромные пушки для того, чтобы победить предыдущего противника!$b$bВпрочем, не беспокойся, друг мой, тебе еще предстоит пролить чужую кровь. Много гоблинов полегло, пытаясь поймать твоего следующего соперника... Он просто гигант!','Одержите победу над принцем Мошем.','Принц Мош побежден','Вернитесь к Катрине Тернер в Прибамбасск, что в Танарисе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Громодром: Принц Мош!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нам бы пришлось притащить сюда огромные пушки для того, чтобы победить предыдущего противника!$b$bВпрочем, не беспокойся, друг мой, тебе еще предстоит пролить чужую кровь. Много гоблинов полегло, пытаясь поймать твоего следующего соперника... Он просто гигант!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Одержите победу над принцем Мошем.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Принц Мош побежден',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Катрине Тернер в Прибамбасск, что в Танарисе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25097,'Тут такое дело...','Слышь, $gприятель:подруга;.$b$bОдин из друзей моего кореша как раз подыскивал |3-1($c), $gкоторый:которая:c; знает толк в драках.$b$bЕсли не боишься замарать руки, отправляйся на юг через горы и разыщи гоблина по имени Верн.$b$bСкажи, что ты от Дразза...','Поговорите с Верном Всякоштукинсом в Тысяче Игл по просьбе Драззита Кранотека.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тут такое дело...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слышь, $gприятель:подруга;.$b$bОдин из друзей моего кореша как раз подыскивал |3-1($c), $gкоторый:которая:c; знает толк в драках.$b$bЕсли не боишься замарать руки, отправляйся на юг через горы и разыщи гоблина по имени Верн.$b$bСкажи, что ты от Дразза...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Верном Всякоштукинсом в Тысяче Игл по просьбе Драззита Кранотека.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25098,'Вождь зовет!','Верный своему слову, Тралл поведет нас спасать наших. Он хотел поговорить с тобой.$B$BУдачи, $n. Мы на тебя рассчитываем.','Поговорите с Траллом на дозорном пункте вождя на Затерянных островах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вождь зовет!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Верный своему слову, Тралл поведет нас спасать наших. Он хотел поговорить с тобой.$B$BУдачи, $n. Мы на тебя рассчитываем.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Траллом на дозорном пункте вождя на Затерянных островах.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (25099,'Одолжить Бастию','Возвращайся на берег и скажи Килагу, что у меня к нему просьба – пусть одолжит тебе Бастию. Она знает дорогу к месту, где держат в заключении твоих друзей.$B$BНе медли. Мы еще встретимся, до того как сделаем свой ход против торгового принца.','Поговорите с Килагом Жутеклыком на Тихом берегу на Затерянных островах','Конечно, можешь одолжить у меня Бастию. Разумеется! Если только она на это согласится.$B$B<Килаг подмигивает.>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Одолжить Бастию',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Возвращайся на берег и скажи Килагу, что у меня к нему просьба – пусть одолжит тебе Бастию. Она знает дорогу к месту, где держат в заключении твоих друзей.$B$BНе медли. Мы еще встретимся, до того как сделаем свой ход против торгового принца.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Килагом Жутеклыком на Тихом берегу на Затерянных островах',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Конечно, можешь одолжить у меня Бастию. Разумеется! Если только она на это согласится.$B$B<Килаг подмигивает.>',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25100,'Покатаемся?','Бастия отвезет тебя туда, куда тебе и нужно попасть, гоблин.','Поговорите с Крадли Дротик у Небесного водопада на Затерянных островах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Покатаемся?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Бастия отвезет тебя туда, куда тебе и нужно попасть, гоблин.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Крадли Дротик у Небесного водопада на Затерянных островах.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25101,'Друг моего друга','Да ты горячая голова!$b$bОдин из друзей моего кореша как раз подыскивал |3-1($c), $gкоторый:которая:c; знает толк в драках.$b$bЕсли не боишься замарать руки, отправляйся на юг через горы и разыщи гоблина по имени Верн.$b$bСкажи, что ты от Улыбки Джима...','Поговорите с Верном Всякоштукинсом в Тысяче Игл по просьбе Улыбки Джима.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Друг моего друга',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Да ты горячая голова!$b$bОдин из друзей моего кореша как раз подыскивал |3-1($c), $gкоторый:которая:c; знает толк в драках.$b$bЕсли не боишься замарать руки, отправляйся на юг через горы и разыщи гоблина по имени Верн.$b$bСкажи, что ты от Улыбки Джима...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Верном Всякоштукинсом в Тысяче Игл по просьбе Улыбки Джима.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25102,'Нет тяжелоногим кодо!','При патрулировании мы всегда попадаем в самое пекло. Если не засады Орды, так значит разъяренные свинобразы.$b$bИ еще эти бесполезные тяжелоногие кодо. Огромные быспорядочно блуждающие и сотрясающие землю стены шерсти... Из-за них мы не видим и не слышим, как сзади приближаются нападающие.$b$bИди и отгони их от наших патрулей. Можно убить некоторых, чтобы направить стадо к югу.','Думаю, эти тучи пыли на востоке – твоя работа. Отлично! Самцы тяжелоногого кодо – это не безобидные маленькие пони.','Вернитесь к Хурлстону Камнешвыру в Обход Двукоссы в Южных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нет тяжелоногим кодо!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','При патрулировании мы всегда попадаем в самое пекло. Если не засады Орды, так значит разъяренные свинобразы.$b$bИ еще эти бесполезные тяжелоногие кодо. Огромные быспорядочно блуждающие и сотрясающие землю стены шерсти... Из-за них мы не видим и не слышим, как сзади приближаются нападающие.$b$bИди и отгони их от наших патрулей. Можно убить некоторых, чтобы направить стадо к югу.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Думаю, эти тучи пыли на востоке – твоя работа. Отлично! Самцы тяжелоногого кодо – это не безобидные маленькие пони.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хурлстону Камнешвыру в Обход Двукоссы в Южных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (25103,'Стоянка бутлегеров','Взрывную работку мы проделали. Я останусь тут ненадолго, чтобы убедиться, что вопрос с этими идиотами окончательно решен, а затем на какое-то время отправлюсь обратно в Прибамбасск.$b$bЕсли хочешь произвести сильное впечатление на наших друзей из Картеля или просто подзаработать, отправляйся на юго-запад. Там, на краю Зияющей бездны, расположена стоянка бутлегеров.$b$bПоговори с Зеке Волочилкинсом. Готова поставить несколько монет, что ему требуется помощь.','Поговорите с Зеке Волочилкинсом на стоянке бутлегеров.','Ты заодно с Мегз, да? Говорят, она сделает все что угодно, лишь бы угодить Гогельмогелю.$B$BНе то, чтобы меня это волновало. Ты готов убить несколько жуков?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Стоянка бутлегеров',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Взрывную работку мы проделали. Я останусь тут ненадолго, чтобы убедиться, что вопрос с этими идиотами окончательно решен, а затем на какое-то время отправлюсь обратно в Прибамбасск.$b$bЕсли хочешь произвести сильное впечатление на наших друзей из Картеля или просто подзаработать, отправляйся на юго-запад. Там, на краю Зияющей бездны, расположена стоянка бутлегеров.$b$bПоговори с Зеке Волочилкинсом. Готова поставить несколько монет, что ему требуется помощь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Зеке Волочилкинсом на стоянке бутлегеров.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты заодно с Мегз, да? Говорят, она сделает все что угодно, лишь бы угодить Гогельмогелю.$B$BНе то, чтобы меня это волновало. Ты готов убить несколько жуков?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (25104,'Состояние раскопок','Как-то сегодня все слишком тихо, и это меня беспокоит, $n.$b$bС тех пор, как Альянс захватил Таурахо, ни про одну из наших позиций нельзя сказать, что она безопасная. Кажется, ты можешь за себя постоять. Поможешь мне с разведкой?$b$bПроверь, что творится у моего сына Марли, за раскопками Бейл Модана, к юго-востоку отсюда. Это незащищенное место, подверженное нападениям, а мой сын слишком горд, чтобы просить о помощи даже в случае необходимости.','Тебя послал отец? Он чересчур беспокоится. Я со всем справляюсь…$B$BНо я буду рад помощи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Состояние раскопок',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как-то сегодня все слишком тихо, и это меня беспокоит, $n.$b$bС тех пор, как Альянс захватил Таурахо, ни про одну из наших позиций нельзя сказать, что она безопасная. Кажется, ты можешь за себя постоять. Поможешь мне с разведкой?$b$bПроверь, что творится у моего сына Марли, за раскопками Бейл Модана, к юго-востоку отсюда. Это незащищенное место, подверженное нападениям, а мой сын слишком горд, чтобы просить о помощи даже в случае необходимости.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебя послал отец? Он чересчур беспокоится. Я со всем справляюсь…$B$BНо я буду рад помощи.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25105,'Грызун! Только не это!','Питомец Лайлы Грызун снова проник в мою мастерскую!$b$bЯ как раз корпела над браслетом, который нужно сегодня доставить. Работа была почти закончена – осталось вставить лишь пару камней. Я провела всю ночь за их огранкой. А утром стоило мне на миг отлучиться позавтракать, как маленький негодник забрался в мастерскую и съел все самоцветы! Поверь мне, он способен сожрать все что угодно, да еще и подчистую.$b$bМне нужно как можно быстрее найти самоцветы на замену: посыльный прибудет за браслетом сегодня вечером. Выручи меня!','О, ты мой спаситель, Пиччо. Спасибо тебе!','Вернитесь к Изабели Джонс в Штормград.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Грызун! Только не это!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Питомец Лайлы Грызун снова проник в мою мастерскую!$b$bЯ как раз корпела над браслетом, который нужно сегодня доставить. Работа была почти закончена – осталось вставить лишь пару камней. Я провела всю ночь за их огранкой. А утром стоило мне на миг отлучиться позавтракать, как маленький негодник забрался в мастерскую и съел все самоцветы! Поверь мне, он способен сожрать все что угодно, да еще и подчистую.$b$bМне нужно как можно быстрее найти самоцветы на замену: посыльный прибудет за браслетом сегодня вечером. Выручи меня!',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, ты мой спаситель, Пиччо. Спасибо тебе!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Изабели Джонс в Штормград.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25106,'Руки прочь от моих раскопок!','Только посмотри на этот разгром, $n! Я дал указание мастерам спасти все артефакты, какие они смогут. Но кто знает, какие сокровища забрали с собой эти твари таурены.$b$bТы можешь помочь? Убей налетчиков и спаси все артефакты, какие сможешь.$b$bЗаодно поищи мои пропавшие инструменты. Мне осталось сделать совсем чуть-чуть, чтобы ветролет снова заработал.','Убейте 8 налетчиков-землекопов, спасите 5 артефактов Бейл Модана и найдите инструменты Двукоссы на раскопках Бейл Модана.','Верните инструменты и артефакты Марли Двукоссе за раскопками Бейл Модана в Южных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Руки прочь от моих раскопок!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Только посмотри на этот разгром, $n! Я дал указание мастерам спасти все артефакты, какие они смогут. Но кто знает, какие сокровища забрали с собой эти твари таурены.$b$bТы можешь помочь? Убей налетчиков и спаси все артефакты, какие сможешь.$b$bЗаодно поищи мои пропавшие инструменты. Мне осталось сделать совсем чуть-чуть, чтобы ветролет снова заработал.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 налетчиков-землекопов, спасите 5 артефактов Бейл Модана и найдите инструменты Двукоссы на раскопках Бейл Модана.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Верните инструменты и артефакты Марли Двукоссе за раскопками Бейл Модана в Южных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (25107,'Великая скрижаль','На дне сундука вы обнаруживаете огромную скрижаль. Сделанная из чего-то, напоминающего безупречно отшлифованный камень, она покрыта странными письменами.$b$BЧасть из них перекликается с иероглифами, которые вы уже видели на стенах, часть же ни имеет с ними ничего общего. Андорен наверняка захочет сам посмотреть на скрижаль.','Принесите Великую скрижаль Андорену Восходу Солнца.','Ты вернулась! Что удалось найти?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Великая скрижаль',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На дне сундука вы обнаруживаете огромную скрижаль. Сделанная из чего-то, напоминающего безупречно отшлифованный камень, она покрыта странными письменами.$b$BЧасть из них перекликается с иероглифами, которые вы уже видели на стенах, часть же ни имеет с ними ничего общего. Андорен наверняка захочет сам посмотреть на скрижаль.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Великую скрижаль Андорену Восходу Солнца.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты вернулась! Что удалось найти?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (25108,'Фиглай Изгнанник','Это самая грустная история, которую я когда-либо слышал, $n. Фиглай был одним из наших лучших землекопов до тех пор, пока не связался с этой вещью. Мы называли ее "Слезой Лун". Она изменила его. Он стал совсем другим. Лучше бы он умер.$b$bФиглаю запретили появляться в Бейл Модане, но мне докладывали, что он продолжает появляться на месте раскопок. Он уже достаточно настрадался. Если ты найдешь Фиглая, закончи его мучения.','Убейте Фиглая Изгнанника на раскопках Бейл Модана.','<Марли мрачно кивает.>$B$BДа, я думаю, это к лучшему.','Вернитесь к Марли Двукоссе за раскопками Бейл Модана в Южных Степях.','Он копает слишком глубоко.','Фиглай Изгнанник') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Фиглай Изгнанник',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это самая грустная история, которую я когда-либо слышал, $n. Фиглай был одним из наших лучших землекопов до тех пор, пока не связался с этой вещью. Мы называли ее "Слезой Лун". Она изменила его. Он стал совсем другим. Лучше бы он умер.$b$bФиглаю запретили появляться в Бейл Модане, но мне докладывали, что он продолжает появляться на месте раскопок. Он уже достаточно настрадался. Если ты найдешь Фиглая, закончи его мучения.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Фиглая Изгнанника на раскопках Бейл Модана.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Марли мрачно кивает.>$B$BДа, я думаю, это к лучшему.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Марли Двукоссе за раскопками Бейл Модана в Южных Степях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Он копает слишком глубоко.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Фиглай Изгнанник',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (25109,'Исправительная шахта Галливикса','Мы едва унесли ноги!$B$BНо многие попали в рабство к торговому принцу. Их заставляют работать в пещере.$B$BГрили помогла семерым нашим бежать, но при этом сама угодила в плен.$B$B$n, ты $gединственный:единственная; у кого хватит смелости войти в извергающийся вулкан! Грили поможет тебе освободить остальных.$B$BПоторопись! Там все может взорваться в любую минуту!','Поговорите с ассистенткой Грили в исправительной шахте Галливикса на Затерянных островах.','<Грили растерянно смотрит на вас.>$B$BЭ... что? Кто ты?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Исправительная шахта Галливикса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы едва унесли ноги!$B$BНо многие попали в рабство к торговому принцу. Их заставляют работать в пещере.$B$BГрили помогла семерым нашим бежать, но при этом сама угодила в плен.$B$B$n, ты $gединственный:единственная; у кого хватит смелости войти в извергающийся вулкан! Грили поможет тебе освободить остальных.$B$BПоторопись! Там все может взорваться в любую минуту!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с ассистенткой Грили в исправительной шахте Галливикса на Затерянных островах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Грили растерянно смотрит на вас.>$B$BЭ... что? Кто ты?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25110,'"Каджа-Кола" ОСЕНЯЕТ! (TM)','Ассистентка Грили обескуражена и напугана. Разве в таком состоянии она способна чем-нибудь помочь тебе?$B$BБыть может, если она выпьет "Каджа-Колу Полулайт", ее осенит?','Добудьте 1 порцию "Каджа-Колы Полулайт".','<Ассистентка Грили замечает банку "Каджа-Колы Полулайт" у вас в руке, и ее взгляд постепенно становится осмысленным.>','А?','Вернитесь к ассистентке Грили в исправительную шахту Галливикса на Затерянных островах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','"Каджа-Кола" ОСЕНЯЕТ! (TM)',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ассистентка Грили обескуражена и напугана. Разве в таком состоянии она способна чем-нибудь помочь тебе?$B$BБыть может, если она выпьет "Каджа-Колу Полулайт", ее осенит?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 1 порцию "Каджа-Колы Полулайт".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Ассистентка Грили замечает банку "Каджа-Колы Полулайт" у вас в руке, и ее взгляд постепенно становится осмысленным.>',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','А?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ассистентке Грили в исправительную шахту Галливикса на Затерянных островах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25112,'Мясорез','Мой источник дохода здесь – продажа частей тел различных животных. Мне удалось разработать собственный метод максимизации прибыли: мясорез, элементарное в обращении устройство!$b$bЭтот малыш запрограммирован собирать любой мало-мальски ценный кусок мяса любого животного из тех, что водятся в округе, на индивидуальной основе. Он делает всю работу, а самое прекрасное то, что лишь я знаю, как вскрыть резервуар и забрать добычу.$b$bЕсли хочешь немного подзаработать, захвати с собой одного из них. Мне нужно немного мяса стеклошкурых василисков, что во множестве водятся на юге.','С помощью мясореза соберите добычу с 10 трупов стеклошкурых василисков.','Отлично справился, детка. Пальчики все на месте? Ну и хорошо, значит, можно приниматься за следующее задание.','Вернитесь к Дризу Согнишвырялкинсу в Прибамбасск, что в Танарисе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мясорез',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мой источник дохода здесь – продажа частей тел различных животных. Мне удалось разработать собственный метод максимизации прибыли: мясорез, элементарное в обращении устройство!$b$bЭтот малыш запрограммирован собирать любой мало-мальски ценный кусок мяса любого животного из тех, что водятся в округе, на индивидуальной основе. Он делает всю работу, а самое прекрасное то, что лишь я знаю, как вскрыть резервуар и забрать добычу.$b$bЕсли хочешь немного подзаработать, захвати с собой одного из них. Мне нужно немного мяса стеклошкурых василисков, что во множестве водятся на юге.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','С помощью мясореза соберите добычу с 10 трупов стеклошкурых василисков.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично справился, детка. Пальчики все на месте? Ну и хорошо, значит, можно приниматься за следующее задание.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дризу Согнишвырялкинсу в Прибамбасск, что в Танарисе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25113,'[DEPRECATED]Scorpid Poaching: Dunestalkers','На юге водятся скорпиды побольше – песчаные охотники. Мясо их хвостов слишком жесткое и сухое, чтобы его можно было продать. Но есть то, что продается всегда – ноги! $b$BНе буду заваливать тебя лишними деталями оценки стоимости разных частей тела скорпидов, достаточно сказать, что их расхватывают, как горячие пирожки. Или клешни краба. Крабовые пирожки?$b$bВ любом случае, мне неважно, что там делают с ними повара после того, как я получаю свои денежки. Принеси мне, хм, около 12 фунтов ног песчаных скорпидов-охотников.','Соберите 12 кило ножек песчаного охотника с песчаных скорпидов-охотников.','Вернитесь к Дризу Согнишвырялкинсу в Прибамбасск, что в Танарисе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]Scorpid Poaching: Dunestalkers',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На юге водятся скорпиды побольше – песчаные охотники. Мясо их хвостов слишком жесткое и сухое, чтобы его можно было продать. Но есть то, что продается всегда – ноги! $b$BНе буду заваливать тебя лишними деталями оценки стоимости разных частей тела скорпидов, достаточно сказать, что их расхватывают, как горячие пирожки. Или клешни краба. Крабовые пирожки?$b$bВ любом случае, мне неважно, что там делают с ними повара после того, как я получаю свои денежки. Принеси мне, хм, около 12 фунтов ног песчаных скорпидов-охотников.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 12 кило ножек песчаного охотника с песчаных скорпидов-охотников.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дризу Согнишвырялкинсу в Прибамбасск, что в Танарисе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25114,'[DEPRECATED]Basilisk Poaching: Gazer Guts','Ты не очень-то $gпривередлив:привередлива;, судя по предыдущим занятиям. Возьмешься за одно дельце?$b$bОгромные василиски на юге, взорени, вырастают до невероятных размеров. Алхимики обычно используют мозги меньшего размера, да, но как насчет других органов?$b$bВ любом случае, я – не алхимик, зато я знаю, вагоны чего Дриз сможет продать. Принеси мне полный мешок внутренностей взореней.','Собери 12 внутренностей взореней со стеклошкурых взореней.','Вернитесь к Джейн Фарнум в Прибамбасск, что в Танарисе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]Basilisk Poaching: Gazer Guts',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты не очень-то $gпривередлив:привередлива;, судя по предыдущим занятиям. Возьмешься за одно дельце?$b$bОгромные василиски на юге, взорени, вырастают до невероятных размеров. Алхимики обычно используют мозги меньшего размера, да, но как насчет других органов?$b$bВ любом случае, я – не алхимик, зато я знаю, вагоны чего Дриз сможет продать. Принеси мне полный мешок внутренностей взореней.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Собери 12 внутренностей взореней со стеклошкурых взореней.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джейн Фарнум в Прибамбасск, что в Танарисе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25115,'Гиенобойня','Гиены, что шныряют по здешним пустошам, выглядят хилыми, однако они обладают невероятно сильными челюстями! Стоит лишь на секунду зазеваться, как гиена мигом откусит ногу целиком. Такие мощные кости определенно являются источником немалой выгоды, друг мой, стоит лишь найти покупателя!$b$bВозьми один из моих мясорезов. Отделить челюсть не так-то просто, а этот малыш специально создан для этого. Принеси мясорез обратно, как только резервуар будет полон.','С помощью мясореза соберите добычу с 10 трупов хромоногих гиен.','Превосходно! Скоро эти малыши будут готовы к продаже.','Вернитесь к Дризу Согнишвырялкинсу в Прибамбасск, что в Танарисе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гиенобойня',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Гиены, что шныряют по здешним пустошам, выглядят хилыми, однако они обладают невероятно сильными челюстями! Стоит лишь на секунду зазеваться, как гиена мигом откусит ногу целиком. Такие мощные кости определенно являются источником немалой выгоды, друг мой, стоит лишь найти покупателя!$b$bВозьми один из моих мясорезов. Отделить челюсть не так-то просто, а этот малыш специально создан для этого. Принеси мясорез обратно, как только резервуар будет полон.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','С помощью мясореза соберите добычу с 10 трупов хромоногих гиен.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Превосходно! Скоро эти малыши будут готовы к продаже.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дризу Согнишвырялкинсу в Прибамбасск, что в Танарисе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25116,'[DEPRECATED]Hyena Poaching: Rabid Livers','Знаю, что Дриз терпеть не может тех, кто относится к охоте как к спорту, а по мне так почему бы и не развлечься? Если, конечно, ты не забываешь о рациональности! Верно?$b$bЯ вот о чем: на севере достаточно гиен, но толку от них никакого. А вот те, что подальше, на юге – сплошь больны бешенством. Чувствуешь остроту? Один достаточно глубокий укус – и ты тоже заболеешь! Зато печень больных гиен невероятно раздувается, а ведь продаем мы ее по весу.$b$bНу вот, опять я сам все придумываю. Принесешь немного печени? Я пока тут посижу, поскучаю. Грустно.','Соберите 12 кусков печени бешеного зверя с хромоногих гиен.','Вернитесь к Алестеру "Варвару" в Прибамбасск, что в Танарисе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]Hyena Poaching: Rabid Livers',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Знаю, что Дриз терпеть не может тех, кто относится к охоте как к спорту, а по мне так почему бы и не развлечься? Если, конечно, ты не забываешь о рациональности! Верно?$b$bЯ вот о чем: на севере достаточно гиен, но толку от них никакого. А вот те, что подальше, на юге – сплошь больны бешенством. Чувствуешь остроту? Один достаточно глубокий укус – и ты тоже заболеешь! Зато печень больных гиен невероятно раздувается, а ведь продаем мы ее по весу.$b$bНу вот, опять я сам все придумываю. Принесешь немного печени? Я пока тут посижу, поскучаю. Грустно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 12 кусков печени бешеного зверя с хромоногих гиен.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Алестеру "Варвару" в Прибамбасск, что в Танарисе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25117,'Позор разведчика','Клан Черного Железа опять за свое. Они ведут себя тихо, но я знаю, что назревает проблема.$b$bНадо присмотреть за ними. Их разведчик бродит в центре того, что раньше было озером Лок, и что-то разнюхивает. Я хочу, чтобы ты $gнашел:нашла; его и забрал все документы, какие при нем окажутся.$b$bЕсли мои подозрения были беспочвенны... я сам приму все упреки Мойры. Обещаю.','Возьмите донесения Черного Железа у разведчика Черного Железа.','Вернитесь к Ашлану Камнехмылу в лагерь Мо\'грош в Лок Модане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Позор разведчика',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Клан Черного Железа опять за свое. Они ведут себя тихо, но я знаю, что назревает проблема.$b$bНадо присмотреть за ними. Их разведчик бродит в центре того, что раньше было озером Лок, и что-то разнюхивает. Я хочу, чтобы ты $gнашел:нашла; его и забрал все документы, какие при нем окажутся.$b$bЕсли мои подозрения были беспочвенны... я сам приму все упреки Мойры. Обещаю.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возьмите донесения Черного Железа у разведчика Черного Железа.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ашлану Камнехмылу в лагерь Мо\'грош в Лок Модане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25118,'В поисках пауков-скрытней','Не знаю, как ты, а я не большой любитель пауков, особенно тех, что больше меня. Лок Модан – прекрасное место, но, мне кажется, он бы вполне обошелся без этих кошмарных созданий, всегда готовых наброситься на тебя.$b$bВот что я тебе скажу, ты выглядишь вполне $gкрепким:крепкой;, а у меня есть несколько монет. Если ты убьешь несколько пауков, я заплачу тебе за работу.','Убейте 8 лесных пауков-скрытней.','Я буду спать гораздо спокойнее, зная, что один из этих пауков не заберется ночью в мою постель… в который раз. Большое спасибо.','Вернитесь к Дакку Мимострелу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В поисках пауков-скрытней',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не знаю, как ты, а я не большой любитель пауков, особенно тех, что больше меня. Лок Модан – прекрасное место, но, мне кажется, он бы вполне обошелся без этих кошмарных созданий, всегда готовых наброситься на тебя.$b$bВот что я тебе скажу, ты выглядишь вполне $gкрепким:крепкой;, а у меня есть несколько монет. Если ты убьешь несколько пауков, я заплачу тебе за работу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 лесных пауков-скрытней.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я буду спать гораздо спокойнее, зная, что один из этих пауков не заберется ночью в мою постель… в который раз. Большое спасибо.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дакку Мимострелу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25119,'Краткая охота','Не сомневаюсь, что Ашлан собирается послать тебя на озеро Лок, чтобы разузнать о бандитах из Черного Железа, о которых он бубнит, не переставая. Раз ты все равно направляешься туда, заодно можешь заработать пару монет.$b$bВысыхание озера Лок стало причиной гибели множества живших в нем существ. Больше негде плавать. Но по ставшей теперь сухой земле до сих пор бродят кроколиски.$b$bЧерез некоторое время они умрут с голову, поэтому лучше поохотимся на них, пока они еще живые. Принеси мне несколько боков кроколисков, и мы поговорим об оплате.','Соберите 6 боков кроколисков, поохотившись на кроколисков с озера Лок.','Вернитесь к Келту Томасину в лагерь Мо\'грош в Лок Модане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Краткая охота',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не сомневаюсь, что Ашлан собирается послать тебя на озеро Лок, чтобы разузнать о бандитах из Черного Железа, о которых он бубнит, не переставая. Раз ты все равно направляешься туда, заодно можешь заработать пару монет.$b$bВысыхание озера Лок стало причиной гибели множества живших в нем существ. Больше негде плавать. Но по ставшей теперь сухой земле до сих пор бродят кроколиски.$b$bЧерез некоторое время они умрут с голову, поэтому лучше поохотимся на них, пока они еще живые. Принеси мне несколько боков кроколисков, и мы поговорим об оплате.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 6 боков кроколисков, поохотившись на кроколисков с озера Лок.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Келту Томасину в лагерь Мо\'грош в Лок Модане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25120,'Последний бой Марли','Окей, $n! Давай передадим моему отцу эти артефакты и отчет из первых рук.$b$bБлагодаря твоей помощи мой ветролет действует. Мы можем отправиться вместе и разделить славу.$b$bСкажи мне, когда будешь $gготов:готова;!','Поговорите с Марли Двукоссой и прокатитесь на его летающей машине.','<Тело израненного дворфа бессильно свисает с рубки. Когда вы приближаетесь к горящим обломкам, он открывает глаза.>$B$B<Марли Двукосса все еще жив!>','Быстрее! Проверьте, выжил ли Марли Двукосса после падения ветролета у Бейл\'данской крепости в Южных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Последний бой Марли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Окей, $n! Давай передадим моему отцу эти артефакты и отчет из первых рук.$b$bБлагодаря твоей помощи мой ветролет действует. Мы можем отправиться вместе и разделить славу.$b$bСкажи мне, когда будешь $gготов:готова;!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Марли Двукоссой и прокатитесь на его летающей машине.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Тело израненного дворфа бессильно свисает с рубки. Когда вы приближаетесь к горящим обломкам, он открывает глаза.>$B$B<Марли Двукосса все еще жив!>',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Быстрее! Проверьте, выжил ли Марли Двукосса после падения ветролета у Бейл\'данской крепости в Южных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (25121,'Время идет!','Встретьтесь с Келси Стализвон в Бухте Сорванных Парусов.','Привет! Веселье уже началось!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Время идет!',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Встретьтесь с Келси Стализвон в Бухте Сорванных Парусов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Привет! Веселье уже началось!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25122,'Для поднятия духа','Тебе нужно собрать всю "Каджа-Колу Полулайт", которую только сумеешь найти, и напоить ею гоблинов, чтобы поднять их боевой дух и освободить их разум!','При помощи "Каджа-Колы Полулайт" освободите разум Туза, Иззи, Гоббера и 6 уцелевших гоблинов или кезанских горожан.','Я ненавижу торгового принца, но будем справедливы – его методы весьма эффективны. "Каджа-Кола Полулайт" гораздо лучше обычной "Каджа-Колы": в два раза меньше калорий и в два раза больше идей!','Поговорите с ассистенткой Грили в исправительной шахте Галливикса на Затерянных островах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Для поднятия духа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе нужно собрать всю "Каджа-Колу Полулайт", которую только сумеешь найти, и напоить ею гоблинов, чтобы поднять их боевой дух и освободить их разум!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','При помощи "Каджа-Колы Полулайт" освободите разум Туза, Иззи, Гоббера и 6 уцелевших гоблинов или кезанских горожан.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я ненавижу торгового принца, но будем справедливы – его методы весьма эффективны. "Каджа-Кола Полулайт" гораздо лучше обычной "Каджа-Колы": в два раза меньше калорий и в два раза больше идей!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с ассистенткой Грили в исправительной шахте Галливикса на Затерянных островах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (25123,'Смерть насовсем!','Этот кошмар никогда не закончится, пока жив Вспыхомрак Глава Громил. Его надо прикончить. Правда, есть некоторые нюансы.$B$BВо-первых, он чернокнижник и обзавелся суккубом по имени Вкуснита Хлестопорка. Если убить Вспыхомрака быстро, демон вернется в то место, откуда его вызывали.$B$BВо-вторых... он чернокнижник! А это значит, что у него есть камень души, с помощью которого можно воскреснуть. Уничтожь этот камень души, чтобы Вспыхомрак умер уже насовсем наконец!','Уничтожьте камень души Вспыхомрака Главы Громил.','Был твой камень души, Вспыхомрак, да весь вышел!','Поговорите с ассистенткой Грили в исправительной шахте Галливикса на Затерянных островах.','Уничтожь камень души!','Вспыхомрак Глава Громил') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Смерть насовсем!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этот кошмар никогда не закончится, пока жив Вспыхомрак Глава Громил. Его надо прикончить. Правда, есть некоторые нюансы.$B$BВо-первых, он чернокнижник и обзавелся суккубом по имени Вкуснита Хлестопорка. Если убить Вспыхомрака быстро, демон вернется в то место, откуда его вызывали.$B$BВо-вторых... он чернокнижник! А это значит, что у него есть камень души, с помощью которого можно воскреснуть. Уничтожь этот камень души, чтобы Вспыхомрак умер уже насовсем наконец!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте камень души Вспыхомрака Главы Громил.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Был твой камень души, Вспыхомрак, да весь вышел!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с ассистенткой Грили в исправительной шахте Галливикса на Затерянных островах.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Уничтожь камень души!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Вспыхомрак Глава Громил',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25124,'Невыносимая жестокость','Я вот что думаю: раз уж ты все равно здесь, так, может, разберешься еще и с громилами-надзирателями?$B$BКак тебе такая мысль?','Убейте 6 громил-надзирателей.','Поговорите с ассистенткой Грили на Затерянных островах в исправительной шахте Галливикса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Невыносимая жестокость',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я вот что думаю: раз уж ты все равно здесь, так, может, разберешься еще и с громилами-надзирателями?$B$BКак тебе такая мысль?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 6 громил-надзирателей.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с ассистенткой Грили на Затерянных островах в исправительной шахте Галливикса.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (25125,'Свет в конце туннеля','Так, нужно убираться отсюда, пока не рвануло!$B$BДавай выйдем через туннель в северной части пещеры. Там мы возьмем вагонетку и быстро скатимся на ней по склону вулкана.','Найдите вагонетку на Затерянных островах у исправительной шахты Галливикса.','Какая-то она скрипучая...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Свет в конце туннеля',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Так, нужно убираться отсюда, пока не рвануло!$B$BДавай выйдем через туннель в северной части пещеры. Там мы возьмем вагонетку и быстро скатимся на ней по склону вулкана.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите вагонетку на Затерянных островах у исправительной шахты Галливикса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Какая-то она скрипучая...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25126,'Кабаньи клыки','Убейте 6 пятнистых вепрей.','Вернитесь к Горнеку в Долину Испытаний в Дуротаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кабаньи клыки',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 6 пятнистых вепрей.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Горнеку в Долину Испытаний в Дуротаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25127,'Жала скорпидов','Добудьте 8 хвостов рабочего скорпида.','Вернитесь к Горнеку в Долину Испытаний в Дуротаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жала скорпидов',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 8 хвостов рабочего скорпида.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Горнеку в Долину Испытаний в Дуротаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (25128,'Хана\'зуа','Найдите Хана\'зуа в Долине Испытаний.','<Хана\'зуа стонет от боли.>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хана\'зуа',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Хана\'зуа в Долине Испытаний.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Хана\'зуа стонет от боли.>',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (25129,'Саркот','Убейте Саркота и принесите его клешню Хана\'зуа.','Пусть я и не сумел прикончить его одним ударом, зато здорово врезал – хоть этим гордиться можно. Но ежели я помру, от меня только эта слава и останется. Больно короткий список подвигов у меня выходит, вот и злюсь...','Ах... Мой папаша всегда говорил, что толку из меня не выйдет, и вот лежу я теперь под деревом, а жизнь-то уходит, и, сдается, прав был папашка.$B$BХоть помереть бы тогда, зная, что мой самый главный враг сдох.','Вернитесь к Хана\'зуа в Дуротар.','Берегись его яда.','Саркот') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Саркот',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Саркота и принесите его клешню Хана\'зуа.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Пусть я и не сумел прикончить его одним ударом, зато здорово врезал – хоть этим гордиться можно. Но ежели я помру, от меня только эта слава и останется. Больно короткий список подвигов у меня выходит, вот и злюсь...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ах... Мой папаша всегда говорил, что толку из меня не выйдет, и вот лежу я теперь под деревом, а жизнь-то уходит, и, сдается, прав был папашка.$B$BХоть помереть бы тогда, зная, что мой самый главный враг сдох.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хана\'зуа в Дуротар.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Берегись его яда.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Саркот',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (25130,'Назад, в Логово','Отправляйтесь в Долину Испытаний и расскажите Горнеку о том, что случилось с Хана\'зуа.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Назад, в Логово',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Долину Испытаний и расскажите Горнеку о том, что случилось с Хана\'зуа.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25131,'Злобные фамилиары','Уничтожьте 8 злобных фамилиаров.','Вернитесь к Зурите Востроглазой в Долину Испытаний в Дуротаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Злобные фамилиары',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 8 злобных фамилиаров.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Зурите Востроглазой в Долину Испытаний в Дуротаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (25132,'Медальон Пылающего Клинка','Вернитесь к Зурите Востроглазой в Долину Испытаний в Дуротаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Медальон Пылающего Клинка',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Зурите Востроглазой в Долину Испытаний в Дуротаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (25133,'Донесение для деревни Сен\'джин','Поговорите с мастером Гадрином в деревне Сен\'джин.','Хм... твое донесение весьма нерадостно. Пылающих Клинков давно уже не видели в Сен\'джин, но мы будем начеку и не позволим им вернуться сюда.$B$BОрки – друзья троллей Черного Копья. Достойные друзья. Мы хотим помочь оркам, но... Нам самим нужна помощь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Донесение для деревни Сен\'джин',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с мастером Гадрином в деревне Сен\'джин.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хм... твое донесение весьма нерадостно. Пылающих Клинков давно уже не видели в Сен\'джин, но мы будем начеку и не позволим им вернуться сюда.$B$BОрки – друзья троллей Черного Копья. Достойные друзья. Мы хотим помочь оркам, но... Нам самим нужна помощь.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25134,'Треклятые лентяи! Они валят лес в долине, но то и дело отлынивают и дрыхнут в тенечке! Надо, чтобы кто-то их построил.$B$BВроде ты, |3-6($r), как раз для этих целей подходишь. Вот, бери дубинку – как увидишь батрака, отлынивающего от работы, всыпь ему хорошенько. Добрая трепка заставит их взяться за работу! Когда сделаешь дело, дубинку верни.$B$BИщи батраков под деревьями в долине. Паршивые сонные лентяи...','Отлупите дубинкой штейгера 4 ленивых батраков, застуканных во время сна.','Вот и отлично. Теперь трижды подумают, прежде чем работу бросать! Спасибо за помощь!','Вернитесь к штейгеру Тазз\'рилу в Дуротар.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Треклятые лентяи! Они валят лес в долине, но то и дело отлынивают и дрыхнут в тенечке! Надо, чтобы кто-то их построил.$B$BВроде ты, |3-6($r), как раз для этих целей подходишь. Вот, бери дубинку – как увидишь батрака, отлынивающего от работы, всыпь ему хорошенько. Добрая трепка заставит их взяться за работу! Когда сделаешь дело, дубинку верни.$B$BИщи батраков под деревьями в долине. Паршивые сонные лентяи...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отлупите дубинкой штейгера 4 ленивых батраков, застуканных во время сна.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот и отлично. Теперь трижды подумают, прежде чем работу бросать! Спасибо за помощь!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к штейгеру Тазз\'рилу в Дуротар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25135,'Кирка Тазз\'рила','Принесите кирку Тазз\'рила штейгеру Тазз\'рилу.','Вернитесь к штейгеру Тазз\'рилу в Дуротар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кирка Тазз\'рила',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите кирку Тазз\'рила штейгеру Тазз\'рилу.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к штейгеру Тазз\'рилу в Дуротар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25136,'Кактусовый десерт Галгара','Добудьте 6 плодов кактуса.','Вернитесь к Галгару в Долину Испытаний в Дуротар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кактусовый десерт Галгара',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 6 плодов кактуса.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Галгару в Долину Испытаний в Дуротар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (25136,'Чудесно, Кастоманыч! Как я и обещал, вот твоя доля кактусового десерта и еще кое-что в придачу.','Ну как, набрал плодов кактуса?') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Чудесно, Кастоманыч! Как я и обещал, вот твоя доля кактусового десерта и еще кое-что в придачу.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как, набрал плодов кактуса?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25137,'Valley of Trials: PRK - H - Warlock Pet Imp','Those warlocks who came before us have earned the distrust of the Horde, and while we are tolerated, we are not loved.$b$bThis has not brought the warlocks closer together, however, as many choose to live reclusively, dabbling in their magics alone. I will not seek to lead you down one path or the other, but only help you in your maturation.$b$bBefore I teach you the art of summoning, bring me six heads of the vile familiars from the cave to the northeast.','Bring 6 Vile Familiar Heads to Ruzan.','Return to Ruzan at Valley of Trials in Durotar.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Valley of Trials: PRK - H - Warlock Pet Imp',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Those warlocks who came before us have earned the distrust of the Horde, and while we are tolerated, we are not loved.$b$bThis has not brought the warlocks closer together, however, as many choose to live reclusively, dabbling in their magics alone. I will not seek to lead you down one path or the other, but only help you in your maturation.$b$bBefore I teach you the art of summoning, bring me six heads of the vile familiars from the cave to the northeast.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Bring 6 Vile Familiar Heads to Ruzan.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Return to Ruzan at Valley of Trials in Durotar.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25140,'Охота на свинью','Прямо к югу от этой деревни ты найдешь поросенка, который отзывается на кличку Ло\'Шалл. Он прячется среди кактусов и деревьев. Хотя он и мал, но умен, чего не скажешь о большинстве свиней.$B$BНайди его, выдерни у него одну щетинку и возвращайся ко мне.$B$BПомни, чему я тебя учил, $n. Выслеживание животных тут весьма пригодится.','Вырвите у Ло\'Шалла щетинку. Вам может понадобиться "Выслеживание животных".','Вернитесь к Карранише в Долину Испытаний в Дуротар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота на свинью',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прямо к югу от этой деревни ты найдешь поросенка, который отзывается на кличку Ло\'Шалл. Он прячется среди кактусов и деревьев. Хотя он и мал, но умен, чего не скажешь о большинстве свиней.$B$BНайди его, выдерни у него одну щетинку и возвращайся ко мне.$B$BПомни, чему я тебя учил, $n. Выслеживание животных тут весьма пригодится.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вырвите у Ло\'Шалла щетинку. Вам может понадобиться "Выслеживание животных".',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Карранише в Долину Испытаний в Дуротар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25142,'Под покровом тени','Посмотрим, удастся ли тебе проскользнуть мимо меня. Я все равно тебя замечу, поскольку ты по-прежнему новичок, так что без глупостей. Просто хочу посмотреть, как ты усваиваешь то, чему тебя учат.','С помощью вашей способности быть незаметным проскользните мимо Руага в Долине Испытаний.','Вернитесь к Руагу в Долину Испытаний в Дуротар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Под покровом тени',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Посмотрим, удастся ли тебе проскользнуть мимо меня. Я все равно тебя замечу, поскольку ты по-прежнему новичок, так что без глупостей. Просто хочу посмотреть, как ты усваиваешь то, чему тебя учат.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','С помощью вашей способности быть незаметным проскользните мимо Руага в Долине Испытаний.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Руагу в Долину Испытаний в Дуротар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25144,'Камень бьет плоть','Наши вожди захватили лазутчиков людей, когда те пытались проникнуть в долину. Их держат в клетках, в пещере на западе.$B$BЯ хочу, чтобы ты $gиспытал:испытала; свое новое умение на ком-то из них, $n. Зачаруй свой клинок силой земли и обрати его против врагов!','Уничтожьте пойманного разведчика Северной Стражи, предварительно наложив на свое вооружение чары оружия камнедробителя.','Вернитесь к Шикрик в Долину Испытаний в Дуротар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Камень бьет плоть',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наши вожди захватили лазутчиков людей, когда те пытались проникнуть в долину. Их держат в клетках, в пещере на западе.$B$BЯ хочу, чтобы ты $gиспытал:испытала; свое новое умение на ком-то из них, $n. Зачаруй свой клинок силой земли и обрати его против врагов!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте пойманного разведчика Северной Стражи, предварительно наложив на свое вооружение чары оружия камнедробителя.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Шикрик в Долину Испытаний в Дуротар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25146,'Демонический огонь','Наши вожди захватили лазутчиков из людей, когда те пытались проникнуть в долину. Их держат в клетках, в пещере на западе.$B$BЯ хочу, чтобы ты $gиспытал:испытала; свое новое умение на ком-то из них, $n. Сожги его силой огненного заклинания. Собаке – собачья смерть!','Уничтожьте пойманного разведчика Северной Стражи, применив заклинание "Жертвенный огонь".','Вернитесь к Нартоку в Долину Испытаний в Дуротаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Демонический огонь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наши вожди захватили лазутчиков из людей, когда те пытались проникнуть в долину. Их держат в клетках, в пещере на западе.$B$BЯ хочу, чтобы ты $gиспытал:испытала; свое новое умение на ком-то из них, $n. Сожги его силой огненного заклинания. Собаке – собачья смерть!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте пойманного разведчика Северной Стражи, применив заклинание "Жертвенный огонь".',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Нартоку в Долину Испытаний в Дуротаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25148,'Всесильный вопль','Наши предводители взяли в плен разведчиков-людей, пытавшихся проникнуть в долину. Их держат в клетках в пещере к западу отсюда.$B$BЯ хочу, чтобы с помощью "Боевого крика" ты $gубил:убила; одного из пойманных разведчиков Северной Стражи, пока твоя способность действует. Возвращайся, когда выполнишь задание, $n.','С помощью способности "Боевой крик" победите пойманного разведчика Северной Стражи до окончания действия способности.','Вернитесь к Франгу в Долину Испытаний в Дуротаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Всесильный вопль',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наши предводители взяли в плен разведчиков-людей, пытавшихся проникнуть в долину. Их держат в клетках в пещере к западу отсюда.$B$BЯ хочу, чтобы с помощью "Боевого крика" ты $gубил:убила; одного из пойманных разведчиков Северной Стражи, пока твоя способность действует. Возвращайся, когда выполнишь задание, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','С помощью способности "Боевой крик" победите пойманного разведчика Северной Стражи до окончания действия способности.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Франгу в Долину Испытаний в Дуротаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25150,'Мозговой штурм','"Чародейский интеллект" – это заклинание, которое ты можешь наложить как на себя, так и своих друзей или даже случайного прохожего. Под временным влиянием этого заклинания ты станешь немного... сообразительнее. А теперь попытайся это проделать.$B$BЯ хочу, чтобы ты $gиспробовал:испробовала; Чародейский интеллект на ком-нибудь. Хотя... нет. Я хочу, чтобы ты $gиспытал:испытала; его на МНЕ.','Испытать действие Чародейского интеллекта на Акрифе.','Вернитесь к Акрифе в Долину Испытаний в Дуротар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мозговой штурм',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','"Чародейский интеллект" – это заклинание, которое ты можешь наложить как на себя, так и своих друзей или даже случайного прохожего. Под временным влиянием этого заклинания ты станешь немного... сообразительнее. А теперь попытайся это проделать.$B$BЯ хочу, чтобы ты $gиспробовал:испробовала; Чародейский интеллект на ком-нибудь. Хотя... нет. Я хочу, чтобы ты $gиспытал:испытала; его на МНЕ.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Испытать действие Чародейского интеллекта на Акрифе.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Акрифе в Долину Испытаний в Дуротар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25151,'Срочно нужен эль!','<Марли притягивает к себе вашу голову дрожащей окровавленной рукой.>$b$bЭль... нужен... эль...$b$bСтарый Баркерстаутский.<Он кашляет.>Он должен помочь.','<Глаза Марли вспыхивают, когда вы приближаетесь к нему с элем. Он хватает кружку обеими трясущимися руками и опрокидывает ее. Белая пена стекает по его окровавленной бороде.>$B$BАх… Вот это то, что надо. Старый Баркерстаутский… Спасибо, друг.$B$BТеперь немного легче.$B$B<Он кашляет в последний раз и резко падает на панель управления, полупустая кружка выскальзывает из его рук на землю, и остатки эля выливаются на песок. Его глаза стекленеют.>$B$B<Марли Двукосса мертв.>','<Дыхание Марли прерывистое, он судорожно хватает воздух.>$B$B<Он смотрит на вас умоляющим взглядом.>','Принесите эль Марли Двукоссе к крепости Бейл\'дан в Южных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Срочно нужен эль!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Марли притягивает к себе вашу голову дрожащей окровавленной рукой.>$b$bЭль... нужен... эль...$b$bСтарый Баркерстаутский.<Он кашляет.>Он должен помочь.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Глаза Марли вспыхивают, когда вы приближаетесь к нему с элем. Он хватает кружку обеими трясущимися руками и опрокидывает ее. Белая пена стекает по его окровавленной бороде.>$B$BАх… Вот это то, что надо. Старый Баркерстаутский… Спасибо, друг.$B$BТеперь немного легче.$B$B<Он кашляет в последний раз и резко падает на панель управления, полупустая кружка выскальзывает из его рук на землю, и остатки эля выливаются на песок. Его глаза стекленеют.>$B$B<Марли Двукосса мертв.>',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Дыхание Марли прерывистое, он судорожно хватает воздух.>$B$B<Он смотрит на вас умоляющим взглядом.>',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите эль Марли Двукоссе к крепости Бейл\'дан в Южных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25152,'Твое место в мире','Поговорите с Горнеком.','Очередной птенец гнезда Калтунка, ага?$B$BБеда Орде, если это лучшее, что у нас есть. Ну, да ладно. К тому времени как мы выпустим тебя из Долины Испытаний, ты станешь гордым воителем Орды.','Поговорите с Горнеком.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Твое место в мире',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Горнеком.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Очередной птенец гнезда Калтунка, ага?$B$BБеда Орде, если это лучшее, что у нас есть. Ну, да ладно. К тому времени как мы выпустим тебя из Долины Испытаний, ты станешь гордым воителем Орды.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Горнеком.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25153,'Спасательная операция в Бейл\'дане','На помощь! Помоги нам! Сделай что-нибудь!$B$BНекоторые дворфы все еще внутри, их там много, они не могут выбраться из-под обломков! Замурованы заживо! Все горит! Это какой-то кошмар... Еще немного, и крыша обвалится!$B$BУмоляю тебя, |3-6($c), ты $gдолжен:должна; спасти их!$B$BПоспеши внутрь. Воспользуйся аварийными пожарными клапанами – они защитят тебя от огня. Ты – наша единственная надежда...','Идите в крепость Бейл\'дан и спасите из-под обломков 10 уцелевших бейл\'данских археологов.$b$bВоспользуйтесь аварийными пожарными клапанами, чтобы защитить себя от огня.','Вернитесь к уцелевшим бейл\'данским археологам к крепости Бейл\'дан в Южных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спасательная операция в Бейл\'дане',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На помощь! Помоги нам! Сделай что-нибудь!$B$BНекоторые дворфы все еще внутри, их там много, они не могут выбраться из-под обломков! Замурованы заживо! Все горит! Это какой-то кошмар... Еще немного, и крыша обвалится!$B$BУмоляю тебя, |3-6($c), ты $gдолжен:должна; спасти их!$B$BПоспеши внутрь. Воспользуйся аварийными пожарными клапанами – они защитят тебя от огня. Ты – наша единственная надежда...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Идите в крепость Бейл\'дан и спасите из-под обломков 10 уцелевших бейл\'данских археологов.$b$bВоспользуйтесь аварийными пожарными клапанами, чтобы защитить себя от огня.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к уцелевшим бейл\'данским археологам к крепости Бейл\'дан в Южных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25154,'Подарок для Лайлы','Я хочу поразить капитана торгового судна Лайлу. Я работала над лиловым ожерельем в тон к ее милой прическе, но требуемые самоцветы куда-то пропали! Я помню, что вчера вечером они были на месте, когда я их демонстрировала своему другу Керверу. Мы пили самогон, и тут меня вырубило... а когда я очнулась, то самоцветов уже не было! Видимо, это были профессионалы, потому что Кервер тоже ничего не заметил.$b$bКапитанский корабль прибывает сегодня вечером, поэтому мне срочно нужны камни ночи, чтобы закончить сюрприз для Лайлы. Помоги мне!','Благодарю! Теперь я уж точно заткну за пояс Марит Лазурию из Оргриммара! Представляю восторг Лайлы, когда преподнесу ей свое ожерелье.','Вернитесь к Изабели Джонс в Штормград.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подарок для Лайлы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я хочу поразить капитана торгового судна Лайлу. Я работала над лиловым ожерельем в тон к ее милой прическе, но требуемые самоцветы куда-то пропали! Я помню, что вчера вечером они были на месте, когда я их демонстрировала своему другу Керверу. Мы пили самогон, и тут меня вырубило... а когда я очнулась, то самоцветов уже не было! Видимо, это были профессионалы, потому что Кервер тоже ничего не заметил.$b$bКапитанский корабль прибывает сегодня вечером, поэтому мне срочно нужны камни ночи, чтобы закончить сюрприз для Лайлы. Помоги мне!',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Благодарю! Теперь я уж точно заткну за пояс Марит Лазурию из Оргриммара! Представляю восторг Лайлы, когда преподнесу ей свое ожерелье.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Изабели Джонс в Штормград.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25155,'Огрезонцы негодуют','Мне должны были доставить посылку c яшмой на корабле компании "Азеротский экспресс", но пришла весть, что судно разбилось вблизи крошечного острова под названием Огрезония. Я очень боюсь за экипаж, так как остров печально известен гигантскими ограми женского пола, что совершают на нем чудовищные ритуалы с потерпевшими кораблекрушение мужчинами. Мне как-то нужно продолжить работу, но без самоцветов это невозможно. Слышала, ты искусный ювелир. Не $gсогласился:согласилась; бы ты доставить мне три экземпляра зазубренной яшмы до конца дня?','Выходит, ты действительно так искусен, как говорят.','Вернитесь к Изабели Джонс в Штормград.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Огрезонцы негодуют',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне должны были доставить посылку c яшмой на корабле компании "Азеротский экспресс", но пришла весть, что судно разбилось вблизи крошечного острова под названием Огрезония. Я очень боюсь за экипаж, так как остров печально известен гигантскими ограми женского пола, что совершают на нем чудовищные ритуалы с потерпевшими кораблекрушение мужчинами. Мне как-то нужно продолжить работу, но без самоцветов это невозможно. Слышала, ты искусный ювелир. Не $gсогласился:согласилась; бы ты доставить мне три экземпляра зазубренной яшмы до конца дня?',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Выходит, ты действительно так искусен, как говорят.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Изабели Джонс в Штормград.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25156,'Клейкая субстанция элементалей','Я практикую новаторский способ вставки самоцветов в кольца и прочие ювелирные изделия вместо избитого древнего метода. Я попросту приклеиваю самоцветы при помощи элементального клея профессора Барнсворта. Недавно у него закончилась клейкая субстанция элементалей, необходимая для изготовления клея, а мне как раз нужно вставить множество самоцветов. Не хочешь принести мне немного субстанции?','Спасибо! Просто положи ее вон там. Мне нужно придумать, как отлепить руку от кувшина.','Вернитесь к Изабели Джонс в Штормград.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Клейкая субстанция элементалей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я практикую новаторский способ вставки самоцветов в кольца и прочие ювелирные изделия вместо избитого древнего метода. Я попросту приклеиваю самоцветы при помощи элементального клея профессора Барнсворта. Недавно у него закончилась клейкая субстанция элементалей, необходимая для изготовления клея, а мне как раз нужно вставить множество самоцветов. Не хочешь принести мне немного субстанции?',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо! Просто положи ее вон там. Мне нужно придумать, как отлепить руку от кувшина.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Изабели Джонс в Штормград.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25157,'Писк моды!','Профессор Барнсворт работает над новой звездной пылью. Сейчас в Штормграде модно носить все блестящее, так что если нам удастся разрекламировать звездную пыль на рынке, она обязательно станет хитом сезона! В свою очередь, Союз ювелиров не позволит нам пустить пыль в продажу, пока та не прошла испытание на людях. Представь себе, они боятся, что магическая пыль может представлять какую-то опасность для здоровья. Давай развеем их сомнения. Возьми-ка эту сумку и опробуй "Звездную пыль № 2" на людях.','Опробуйте "Звездную пыль № 2" на людях.','Что-что?! Все, нам крышка! Хм… Может, профессор найдет пыли новое применение?','Вернитесь к Изабели Джонс в Штормград.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Писк моды!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Профессор Барнсворт работает над новой звездной пылью. Сейчас в Штормграде модно носить все блестящее, так что если нам удастся разрекламировать звездную пыль на рынке, она обязательно станет хитом сезона! В свою очередь, Союз ювелиров не позволит нам пустить пыль в продажу, пока та не прошла испытание на людях. Представь себе, они боятся, что магическая пыль может представлять какую-то опасность для здоровья. Давай развеем их сомнения. Возьми-ка эту сумку и опробуй "Звездную пыль № 2" на людях.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Опробуйте "Звездную пыль № 2" на людях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что-что?! Все, нам крышка! Хм… Может, профессор найдет пыли новое применение?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Изабели Джонс в Штормград.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25158,'Грызун! Только не это!','Грызун – питомец Лайлы – снова проник в мою мастерскую!$b$bЯ как раз корпела над браслетом, который нужно сегодня доставить. Работа была почти закончена – осталось вставить лишь пару камней. Я провела всю ночь за их огранкой. А утром стоило мне на миг отлучиться позавтракать, как маленький негодник забрался в мастерскую и проглотил все самоцветы! Поверь мне, он способен сожрать все что угодно – и ни крошки не останется.$b$bМне нужно как можно быстрее найти самоцветы на замену: посыльный прибудет за браслетом сегодня вечером. Выручи меня!','Ограните три цельных зефирита и отдайте их Марит Лазурии в Оргриммаре.','О, ты мой спаситель, Антихилер. Спасибо тебе!','Вернитесь к Марит Лазурии в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Грызун! Только не это!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Грызун – питомец Лайлы – снова проник в мою мастерскую!$b$bЯ как раз корпела над браслетом, который нужно сегодня доставить. Работа была почти закончена – осталось вставить лишь пару камней. Я провела всю ночь за их огранкой. А утром стоило мне на миг отлучиться позавтракать, как маленький негодник забрался в мастерскую и проглотил все самоцветы! Поверь мне, он способен сожрать все что угодно – и ни крошки не останется.$b$bМне нужно как можно быстрее найти самоцветы на замену: посыльный прибудет за браслетом сегодня вечером. Выручи меня!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Ограните три цельных зефирита и отдайте их Марит Лазурии в Оргриммаре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, ты мой спаситель, Антихилер. Спасибо тебе!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Марит Лазурии в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25159,'Писк моды!','Доктор Вернстром работает над новой звездной пылью. Сейчас в Оргриммаре модно носить все блестящее, так что если нам удастся разрекламировать звездную пыль на рынке, она обязательно станет хитом сезона! В свою очередь, Союз ювелиров не позволит нам пустить пыль в продажу, пока та не прошла "практические" испытания. Представь себе, они боятся, что магическая пыль может представлять какую-то опасность для здоровья. Давай развеем их сомнения. Возьми-ка эту сумку и опробуй "Звездную пыль № 2" на обывателях.','Опробуйте "Звездную пыль № 2" на обывателях.','Что-что?! Все, нам крышка! Хм… Может, доктор найдет пыли новое применение?','Вернитесь к Марит Лазурии в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Писк моды!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Доктор Вернстром работает над новой звездной пылью. Сейчас в Оргриммаре модно носить все блестящее, так что если нам удастся разрекламировать звездную пыль на рынке, она обязательно станет хитом сезона! В свою очередь, Союз ювелиров не позволит нам пустить пыль в продажу, пока та не прошла "практические" испытания. Представь себе, они боятся, что магическая пыль может представлять какую-то опасность для здоровья. Давай развеем их сомнения. Возьми-ка эту сумку и опробуй "Звездную пыль № 2" на обывателях.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Опробуйте "Звездную пыль № 2" на обывателях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что-что?! Все, нам крышка! Хм… Может, доктор найдет пыли новое применение?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Марит Лазурии в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25160,'Подарок для Лайлы','Я хочу поразить капитана торгового судна Лайлу. Я работала над лиловым ожерельем в тон к ее милой прическе, но требуемые самоцветы куда-то пропали! Я помню, что вчера вечером они были на месте, когда я их демонстрировала своему другу Бондеру. Мы пили самогон, и тут меня вырубило... а когда я очнулась, то самоцветов уже не было! Видимо, это были профессионалы, потому что Бондер тоже ничего не заметил.$b$bКапитанский корабль прибывает сегодня вечером, поэтому мне срочно нужны камни ночи, чтобы закончить сюрприз для Лайлы. Помоги мне!','Ограните три вневременных камня ночи и отдайте их Марит Лазурии в Оргриммаре.','Благодарю! Теперь я уж точно заткну за пояс Изабель Джонс из Штормграда! Представляю восторг Лайлы, когда преподнесу ей свое ожерелье.','Вернитесь к Марит Лазурии в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подарок для Лайлы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я хочу поразить капитана торгового судна Лайлу. Я работала над лиловым ожерельем в тон к ее милой прическе, но требуемые самоцветы куда-то пропали! Я помню, что вчера вечером они были на месте, когда я их демонстрировала своему другу Бондеру. Мы пили самогон, и тут меня вырубило... а когда я очнулась, то самоцветов уже не было! Видимо, это были профессионалы, потому что Бондер тоже ничего не заметил.$b$bКапитанский корабль прибывает сегодня вечером, поэтому мне срочно нужны камни ночи, чтобы закончить сюрприз для Лайлы. Помоги мне!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Ограните три вневременных камня ночи и отдайте их Марит Лазурии в Оргриммаре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Благодарю! Теперь я уж точно заткну за пояс Изабель Джонс из Штормграда! Представляю восторг Лайлы, когда преподнесу ей свое ожерелье.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Марит Лазурии в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25161,'Огрезонцы негодуют','Мне должны были доставить посылку c яшмой на корабле компании "Азеротский экспресс", но пришла весть, что судно разбилось вблизи крошечного острова под названием Огрезония. Я очень боюсь за экипаж, так как остров печально известен гигантскими ограми женского пола, что совершают на нем чудовищные ритуалы с потерпевшими кораблекрушение мужчинами. Мне как-то нужно продолжить работу, но без самоцветов это невозможно. Слышала, ты искусный ювелир. Не $gсогласился:согласилась; бы ты доставить мне три экземпляра зазубренной яшмы до конца дня?','Ограньте три экземпляра зазубренной яшмы и отдайте их Марит Лазурии в Оргриммаре.','Выходит, ты действительно так искусен, как говорят.','Вернитесь к Марит Лазурии в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Огрезонцы негодуют',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне должны были доставить посылку c яшмой на корабле компании "Азеротский экспресс", но пришла весть, что судно разбилось вблизи крошечного острова под названием Огрезония. Я очень боюсь за экипаж, так как остров печально известен гигантскими ограми женского пола, что совершают на нем чудовищные ритуалы с потерпевшими кораблекрушение мужчинами. Мне как-то нужно продолжить работу, но без самоцветов это невозможно. Слышала, ты искусный ювелир. Не $gсогласился:согласилась; бы ты доставить мне три экземпляра зазубренной яшмы до конца дня?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Ограньте три экземпляра зазубренной яшмы и отдайте их Марит Лазурии в Оргриммаре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Выходит, ты действительно так искусен, как говорят.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Марит Лазурии в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25162,'Клейкая субстанция элементалей','Я практикую новаторский способ вставки самоцветов в кольца и прочие ювелирные изделия вместо избитого древнего метода. Я попросту приклеиваю самоцветы при помощи элементального клея доктора Вернстрома. Недавно у него закончилась клейкая субстанция элементалей, необходимая для изготовления клея, а мне как раз нужно вставить множество самоцветов. Не хочешь принести мне немного субстанции?','Получите 10 порций клейкой субстанции с любых элементалей территорий Cataclysm и принесите их Марит Лазурии в Оргриммаре.','Спасибо! Просто положи ее вон там. Мне нужно придумать, как отлепить руку от кувшина.','Вернитесь к Марит Лазурии в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Клейкая субстанция элементалей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я практикую новаторский способ вставки самоцветов в кольца и прочие ювелирные изделия вместо избитого древнего метода. Я попросту приклеиваю самоцветы при помощи элементального клея доктора Вернстрома. Недавно у него закончилась клейкая субстанция элементалей, необходимая для изготовления клея, а мне как раз нужно вставить множество самоцветов. Не хочешь принести мне немного субстанции?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Получите 10 порций клейкой субстанции с любых элементалей территорий Cataclysm и принесите их Марит Лазурии в Оргриммаре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо! Просто положи ее вон там. Мне нужно придумать, как отлепить руку от кувшина.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Марит Лазурии в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (25163,'Кто за этим стоит?','Саботаж! Наверняка. Склады боеприпасов взорваны. Похоже, кто-то из Орды пробрался внутрь... $B$B$C, если у тебя хватит смелости отправиться в этот горящий кошмар... поищи указания на то, кто бы мог это сделать. Надо будет доложить генералу! Найди тело ордынского преступника, и мы узнаем, кто причастен к этой катастрофе...','Обследуйте крепость Бейл\'дан и найдите тело ордынца.','<В чудовищную картину обгоревших трупов не вписывается лишь одно тело: мертвый гоблин, сжимающий план крепости в безжизненной руке…>$B$B<Картель гоблинов Трюмных Вод – вот кто виновен!>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кто за этим стоит?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Саботаж! Наверняка. Склады боеприпасов взорваны. Похоже, кто-то из Орды пробрался внутрь... $B$B$C, если у тебя хватит смелости отправиться в этот горящий кошмар... поищи указания на то, кто бы мог это сделать. Надо будет доложить генералу! Найди тело ордынского преступника, и мы узнаем, кто причастен к этой катастрофе...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обследуйте крепость Бейл\'дан и найдите тело ордынца.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<В чудовищную картину обгоревших трупов не вписывается лишь одно тело: мертвый гоблин, сжимающий план крепости в безжизненной руке…>$B$B<Картель гоблинов Трюмных Вод – вот кто виновен!>',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25164,'Загнанные в угол','Наги наступают, |3-6($c). Помоги нам отбиться!','Защищайте лагерь Служителей Земли, пока наги не отступят.','Хорошо, что ты был с нами.$B$BА Тош, кажется, собрался за ними гнаться. Ступай и помоги ему.','Поговорите с предсказателем Гадрой в Гроте Затуманенного Света.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Загнанные в угол',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наги наступают, |3-6($c). Помоги нам отбиться!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Защищайте лагерь Служителей Земли, пока наги не отступят.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо, что ты был с нами.$B$BА Тош, кажется, собрался за ними гнаться. Ступай и помоги ему.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с предсказателем Гадрой в Гроте Затуманенного Света.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25165,'Невинные глаза тоже лгут','Теперь нам нужно достать немного яда скорпидов. Они тут повсюду. Но не бойся, Бом\'бей не хочет навредить тебе!$b$bУ Бом\'бея есть тотем. Поставишь его на землю, и он высосет весь яд, а ты останешься $gцел:цела; и $gневредим:невредима;. Идет?','Получите 6 образцов яда скорпидов, поставив тотем извлечения яда на землю рядом с гремучим скорпидом.','Вернитесь к Бом\'бею в деревню Сен\'джин в Дуротар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Невинные глаза тоже лгут',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь нам нужно достать немного яда скорпидов. Они тут повсюду. Но не бойся, Бом\'бей не хочет навредить тебе!$b$bУ Бом\'бея есть тотем. Поставишь его на землю, и он высосет весь яд, а ты останешься $gцел:цела; и $gневредим:невредима;. Идет?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Получите 6 образцов яда скорпидов, поставив тотем извлечения яда на землю рядом с гремучим скорпидом.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бом\'бею в деревню Сен\'джин в Дуротар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (25166,'Капитан "Борода ужаса"','Убейте капитана "Борода Ужаса"','Говоришь, он управлял морским великаном? Потрясающе! Узнать бы об этом побольше...$B$BТо есть, это совершенно невероятно! Слава добрым духам, что с ним покончено! Гогельмогель будет в восторге, когда узнает.$B$BА вот и твоя награда!','Вернитесь к Келси Стализвон в Бухту Сорванных Парусов, что в Танарисе.','Внуши ему страх.','Капитан "Борода ужаса"') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Капитан "Борода ужаса"',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте капитана "Борода Ужаса"',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Говоришь, он управлял морским великаном? Потрясающе! Узнать бы об этом побольше...$B$BТо есть, это совершенно невероятно! Слава добрым духам, что с ним покончено! Гогельмогель будет в восторге, когда узнает.$B$BА вот и твоя награда!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Келси Стализвон в Бухту Сорванных Парусов, что в Танарисе.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Внуши ему страх.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Капитан "Борода ужаса"',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (25167,'Слабое звено','Вернитесь к мастеру Гадрину в деревню Сен\'джин в Дуротар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Слабое звено',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру Гадрину в деревню Сен\'джин в Дуротар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (25168,'Очистить долину','Вернитесь к мастеру Гадрину в деревню Сен\'джин в Дуротар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Очистить долину',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру Гадрину в деревню Сен\'джин в Дуротар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25169,'Хорошая работа, герой. Ты многое сделал для деревни Сен\'джин сегодня. Нет... То, что ты сделал, многое значит для всего Дуротара.','Вернитесь к Лару Ночной Клык в деревню Сен\'джин в Дуротар.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошая работа, герой. Ты многое сделал для деревни Сен\'джин сегодня. Нет... То, что ты сделал, многое значит для всего Дуротара.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лару Ночной Клык в деревню Сен\'джин в Дуротар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25170,'Зачистка побережья','Эй, $gприятель:подруга;! Бом\'бей работает над новым настоем. Хочешь глотнуть? Только прежде собери кое-какие штучки для Бом\'бея.$b$bПрежде всего, Бом\'бею нужно немного слизи подводных крабов. Покажи-ка мне свои руки!$b$b<Бом\'бей внимательно изучает ваши ладони.>$b$bБом\'бей хочет, чтобы ты $gпринес:принесла; 5 пригоршень. Поторопись!','Добудьте 5 пригоршень слизи крабов.','Да, дружок, то, что нужно. Теперь надо достать остальное.','Принесешь, что нужно – покажу настой.','Вернитесь к Бом\'бею в деревню Сен\'джин в Дуротар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зачистка побережья',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эй, $gприятель:подруга;! Бом\'бей работает над новым настоем. Хочешь глотнуть? Только прежде собери кое-какие штучки для Бом\'бея.$b$bПрежде всего, Бом\'бею нужно немного слизи подводных крабов. Покажи-ка мне свои руки!$b$b<Бом\'бей внимательно изучает ваши ладони.>$b$bБом\'бей хочет, чтобы ты $gпринес:принесла; 5 пригоршень. Поторопись!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 5 пригоршень слизи крабов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, дружок, то, что нужно. Теперь надо достать остальное.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Принесешь, что нужно – покажу настой.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бом\'бею в деревню Сен\'джин в Дуротар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (25171,'Дорога верхом','Этот тролль хочет, чтобы мы прислали ему подмогу? Ха, пусть даже и не думает. Мне самому здесь людей не хватает, и, между прочим, нехватка людей – моя самая незначительная проблема.$B$BДеревня Сен\'джин находится прямо у островов Эха, да еще и рядом с Долиной Испытаний. Старый Гадрин может получить столько новобранцев, сколько захочет для борьбы с этим вторжением людей.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дорога верхом',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Этот тролль хочет, чтобы мы прислали ему подмогу? Ха, пусть даже и не думает. Мне самому здесь людей не хватает, и, между прочим, нехватка людей – моя самая незначительная проблема.$B$BДеревня Сен\'джин находится прямо у островов Эха, да еще и рядом с Долиной Испытаний. Старый Гадрин может получить столько новобранцев, сколько захочет для борьбы с этим вторжением людей.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25172,'Если дорог тебе твой дом','Быстро и решительно. Хорошая работа.','Вернитесь к Горнеку в Долину Испытаний в Дуротаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Если дорог тебе твой дом',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Быстро и решительно. Хорошая работа.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Горнеку в Долину Испытаний в Дуротаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (25173,'От плохого к худшему','Вернитесь к Га\'току на Колючий Холм в Дуротар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','От плохого к худшему',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Га\'току на Колючий Холм в Дуротар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (25174,'Генерал Двукосса желает знать','<Генерал Двукосса захочет узнать подробности этого отчаянного нападения. Соберите нужные улики.>','Что? ЧТО?!$B$BБейл\'дан разрушен? Везде убитые? Нет! $B$B<Вы рассказываете об известных вам подробностях.>$B$BГоблины из Трюмных Вод, говоришь? Они зарываются! Мы покажем им, что значит быть частью Орды! Весь Боевой Шрам будет усеян их трупами. Земля утонет в их крови.$B$B<Двукосса хватает вас за воротник.>$B$BГоблинов. Сотрут. В порошок.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Генерал Двукосса желает знать',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Генерал Двукосса захочет узнать подробности этого отчаянного нападения. Соберите нужные улики.>',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что? ЧТО?!$B$BБейл\'дан разрушен? Везде убитые? Нет! $B$B<Вы рассказываете об известных вам подробностях.>$B$BГоблины из Трюмных Вод, говоришь? Они зарываются! Мы покажем им, что значит быть частью Орды! Весь Боевой Шрам будет усеян их трупами. Земля утонет в их крови.$B$B<Двукосса хватает вас за воротник.>$B$BГоблинов. Сотрут. В порошок.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (25175,'Плохие новости','<Вы аккуратно прикрываете веки Марли.>$B$B<Кому-то придется рассказать генералу Двукоссе, что Орда убила его единственного сына.>$B$B<И этим кем-то будете вы.>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Плохие новости',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Вы аккуратно прикрываете веки Марли.>$B$B<Кому-то придется рассказать генералу Двукоссе, что Орда убила его единственного сына.>$B$B<И этим кем-то будете вы.>',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25176,'Воспользоваться случаем','$gЭй, красавчик! Ты только ступил в город, а я уже глаз не могу отвести от твоих мощных бицепсов.:Ты что тут ищешь, уродина? Видела, ты шныряла вокруг Колючего Холма и пыталась сманить кого-то из МОИХ парней!;$b$bПослушай, у меня есть для тебя дело. Слышала, Го\'ток отправил тебя в Тирагард. Пока будешь там, не $gмог:могла бы; принести мне несколько брошенных людьми Кул-Тираса безделушек?$b$b$gСпасибо, милый!:И не спрашивай, зачем, просто принеси!;','Добудьте 6 кул-тирасских сокровищ.','<Зоря обезоруживающе улыбается вам.>','Вернитесь к Зоре Носопырц на Колючий Холм в Дуротаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Воспользоваться случаем',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$gЭй, красавчик! Ты только ступил в город, а я уже глаз не могу отвести от твоих мощных бицепсов.:Ты что тут ищешь, уродина? Видела, ты шныряла вокруг Колючего Холма и пыталась сманить кого-то из МОИХ парней!;$b$bПослушай, у меня есть для тебя дело. Слышала, Го\'ток отправил тебя в Тирагард. Пока будешь там, не $gмог:могла бы; принести мне несколько брошенных людьми Кул-Тираса безделушек?$b$b$gСпасибо, милый!:И не спрашивай, зачем, просто принеси!;',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 6 кул-тирасских сокровищ.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Зоря обезоруживающе улыбается вам.>',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Зоре Носопырц на Колючий Холм в Дуротаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25177,'Буря на взморье','Теперь, когда по крайней мере какое-то время эти люди не будут копаться у нас прямо под носом, можно заняться более актуальными проблемами.$b$bКатаклизм заметно опустошил восточное побережье Дуротара. Ты $gвидел:видела; руины, оставшиеся от крепости Тирагард. Восточный берег постигло еще большее разорение.$b$bКак только прошла первая волна, морской берег заполнился разъяренными элементалями, что пришли из океана. Я отправил солдат справиться с ними, но их натиск был слишком мощным. Надеюсь, тебе повезет больше, чем им.$b$bОстерегайся волн!','Убейте 11 пенящихся морских элементалей.','Вернитесь к Га\'току на Колючий Холм в Дуротар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Буря на взморье',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда по крайней мере какое-то время эти люди не будут копаться у нас прямо под носом, можно заняться более актуальными проблемами.$b$bКатаклизм заметно опустошил восточное побережье Дуротара. Ты $gвидел:видела; руины, оставшиеся от крепости Тирагард. Восточный берег постигло еще большее разорение.$b$bКак только прошла первая волна, морской берег заполнился разъяренными элементалями, что пришли из океана. Я отправил солдат справиться с ними, но их натиск был слишком мощным. Надеюсь, тебе повезет больше, чем им.$b$bОстерегайся волн!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 11 пенящихся морских элементалей.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Га\'току на Колючий Холм в Дуротар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25178,'В поисках разбитых кораблей','$gЭй, красавчик, я скучала! Ты ведь не против еще одной прогулки, верно? Я буду НЕОБЫЧАЙНО благодарна...:Эй, ты! Куда направилась, бродяжка? Я с тобой еще не закончила!; $B$BСлышала, ты собираешься плыть к восточным берегам. Там полно выброшенных кораблей, а в них – инструменты гномов... которые могли бы мне пригодиться.$B$B$gСкоро увидимся, качок!:Пошевеливайся, детка!;','Раздобудьте 4 набора гномских инструментов.','О, а ты и правда знаешь, как порадовать девушку. Если тебе когда-нибудь что-нибудь понадобится...','Неужели мой рыцарь в сияющих доспехах уже вернулся?','Вернитесь к Зоре Носопырц на Колючий Холм в Дуротар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В поисках разбитых кораблей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$gЭй, красавчик, я скучала! Ты ведь не против еще одной прогулки, верно? Я буду НЕОБЫЧАЙНО благодарна...:Эй, ты! Куда направилась, бродяжка? Я с тобой еще не закончила!; $B$BСлышала, ты собираешься плыть к восточным берегам. Там полно выброшенных кораблей, а в них – инструменты гномов... которые могли бы мне пригодиться.$B$B$gСкоро увидимся, качок!:Пошевеливайся, детка!;',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте 4 набора гномских инструментов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, а ты и правда знаешь, как порадовать девушку. Если тебе когда-нибудь что-нибудь понадобится...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Неужели мой рыцарь в сияющих доспехах уже вернулся?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Зоре Носопырц на Колючий Холм в Дуротар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (25179,'Снижение потерь','Ты $gдолжен:должна; помочь нам. Эти элементали, что приходят с волнами... Они сильнее, чем кажутся. Мы были захвачены врасплох и не смогли справиться с их нашествием.$b$bМногие мои верные солдаты остались умирать там, на побережье. Если бы ты $gмог:могла; спасти их... Я бы отблагодарил тебя, как и Га\'ток из Колючего Холма.','Вернитесь к Га\'току на Колючий Холм в Дуротар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Снижение потерь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gдолжен:должна; помочь нам. Эти элементали, что приходят с волнами... Они сильнее, чем кажутся. Мы были захвачены врасплох и не смогли справиться с их нашествием.$b$bМногие мои верные солдаты остались умирать там, на побережье. Если бы ты $gмог:могла; спасти их... Я бы отблагодарил тебя, как и Га\'ток из Колючего Холма.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Га\'току на Колючий Холм в Дуротар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25180,'Скрижали земли','Не так давно Бранн отправил королю Магни срочное сообщение из Ульдуара. В нем говорилось, что он обнаружил древний тайник титанов с редкими и таинственными предметами. Король Ринн немедленно отправил в Нордскол один из самых быстрых кораблей, чтобы забрать посланника. Я должен был встретить его и осмотреть скрижали, но посланник так и не объявился.$B$BКороль Магни начинает беспокоиться, а я не знаю, что ему сказать. Может быть, ты отправишься в порт Штормграда и узнаешь, не появился ли корабль?','Отнесите скрижали земли советнику Белграму в Стальгорн.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Скрижали земли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не так давно Бранн отправил королю Магни срочное сообщение из Ульдуара. В нем говорилось, что он обнаружил древний тайник титанов с редкими и таинственными предметами. Король Ринн немедленно отправил в Нордскол один из самых быстрых кораблей, чтобы забрать посланника. Я должен был встретить его и осмотреть скрижали, но посланник так и не объявился.$B$BКороль Магни начинает беспокоиться, а я не знаю, что ему сказать. Может быть, ты отправишься в порт Штормграда и узнаешь, не появился ли корабль?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите скрижали земли советнику Белграму в Стальгорн.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25181,'Скрижали огня','Я ожидаю прибытия посланника из Нордскола, который везет с собой коллекцию древних сокровищ титанов. Мне кажется, что некоторые предметы могут пролить свет на мои тревожные видения. Этот шаман должен был прилететь на одном из недавних дирижаблей, но до сих пор о нем ни слуху, ни духу!$B$BЯ начинаю беспокоиться: он должен был встретиться со мной к юго-западу от башни дирижаблей Оргриммара, но я не могу пропустить аудиенцию у вождя. Может быть, ты разыщешь посланника и узнаешь, что его задержало?','Принесите скрижали огня целительнице земли Норсале в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Скрижали огня',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я ожидаю прибытия посланника из Нордскола, который везет с собой коллекцию древних сокровищ титанов. Мне кажется, что некоторые предметы могут пролить свет на мои тревожные видения. Этот шаман должен был прилететь на одном из недавних дирижаблей, но до сих пор о нем ни слуху, ни духу!$B$BЯ начинаю беспокоиться: он должен был встретиться со мной к юго-западу от башни дирижаблей Оргриммара, но я не могу пропустить аудиенцию у вождя. Может быть, ты разыщешь посланника и узнаешь, что его задержало?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите скрижали огня целительнице земли Норсале в Оргриммар.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (25182,'Убить всех!','Я хочу увидеть мертвых гоблинов, $n! К западу отсюда ты найдешь целый муравейник этих мелких тварей, которые буравят гору.$b$bДавай считать, что они роют свою могилу.$b$bУничтожь их. Положи конец их грязным работам. В Бейл\'дане они посеяли свою смерть, |3-6($c), настало время собирать урожай.','Вернитесь к генералу Двукоссе в Обход Двукоссы в Южных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Убить всех!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я хочу увидеть мертвых гоблинов, $n! К западу отсюда ты найдешь целый муравейник этих мелких тварей, которые буравят гору.$b$bДавай считать, что они роют свою могилу.$b$bУничтожь их. Положи конец их грязным работам. В Бейл\'дане они посеяли свою смерть, |3-6($c), настало время собирать урожай.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к генералу Двукоссе в Обход Двукоссы в Южных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25183,'...и закопать остальных!','Заложите 6 частей взрывчатки в шахтерском городке Дранфикса.','<Взрывчатка заложена!>','Используйте большой ужасный поршень у входа в шахтерский городок Дранфикса в Южных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','...и закопать остальных!',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заложите 6 частей взрывчатки в шахтерском городке Дранфикса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Взрывчатка заложена!>',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Используйте большой ужасный поршень у входа в шахтерский городок Дранфикса в Южных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25184,'Головокружительная поездка на тачке','Все, что нужно сделать, – это запрыгнуть в тачку, а как доберешься донизу – поговорить с ассистенткой Грили.','Заберитесь в вагонетку поезжайте на ней до конца маршрута, а потом поговорите с ассистенткой Грили.','Как мы это называем в Союзе механиков, прямо из высокотемпературного металлического варочного устройства да в окисляющуюся энергетическую смесь неинертных газов и твердых частиц!','Поговорите с ассистенткой Грили на вырубках картеля на Затерянных островах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Головокружительная поездка на тачке',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Все, что нужно сделать, – это запрыгнуть в тачку, а как доберешься донизу – поговорить с ассистенткой Грили.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заберитесь в вагонетку поезжайте на ней до конца маршрута, а потом поговорите с ассистенткой Грили.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Как мы это называем в Союзе механиков, прямо из высокотемпературного металлического варочного устройства да в окисляющуюся энергетическую смесь неинертных газов и твердых частиц!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с ассистенткой Грили на вырубках картеля на Затерянных островах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (25185,'Дело сделано','<Шахта взрывается, в воздух взлетают обломки, вы прикрываете глаза рукой.>$b$b<Генерал Двукосса будет доволен, но каким-то образом вы понимаете, что этого будет недостаточно для удовлетворения его жажды мести.>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дело сделано',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Шахта взрывается, в воздух взлетают обломки, вы прикрываете глаза рукой.>$b$b<Генерал Двукосса будет доволен, но каким-то образом вы понимаете, что этого будет недостаточно для удовлетворения его жажды мести.>',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (25186,'Безрезультатное сопротивление','Вернитесь к командиру Одингтону на Заставу Чести в Южных Степях.','Ищи его на границе огромной пропасти.','Кона Шаг Грома') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Безрезультатное сопротивление',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру Одингтону на Заставу Чести в Южных Степях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Ищи его на границе огромной пропасти.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Кона Шаг Грома',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25187,'Жертвы наводнения','Несколько выброшенных на берег лодок – далеко не самые страшные разрушения, что принес нам катаклизм, |3-6($c). Река Строптивая вышла из берегов, и вся западная низина Дуротара оказалась затоплена.$b$bТам еще остались люди. Я искал их, но никого не смог найти. Не $gмог:могла; бы ты взять мой телескоп и посмотреть $gсам:сама;?','Разыщите выживших после разлива реки Строптивой с помощью подзорной трубы Тонка.','Ах вот так... Хитрость заключалась в том, чтобы смотреть с МАЛЕНЬКОГО конца трубы. Надо будет запомнить.','Вернитесь к Тонку на Колючий Холм в Дуротар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жертвы наводнения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Несколько выброшенных на берег лодок – далеко не самые страшные разрушения, что принес нам катаклизм, |3-6($c). Река Строптивая вышла из берегов, и вся западная низина Дуротара оказалась затоплена.$b$bТам еще остались люди. Я искал их, но никого не смог найти. Не $gмог:могла; бы ты взять мой телескоп и посмотреть $gсам:сама;?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите выживших после разлива реки Строптивой с помощью подзорной трубы Тонка.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ах вот так... Хитрость заключалась в том, чтобы смотреть с МАЛЕНЬКОГО конца трубы. Надо будет запомнить.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тонку на Колючий Холм в Дуротар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25188,'Патрулирование Разлива Строптивой','Мой пост здесь, на башне, $n, и я не могу покинуть его. Но мне нужен кто-то, способный помочь тем, кто оказался в зоне наводнения.$b$bМогу ли я на тебя рассчитывать?','Отправляйтесь к Разливу Строптивой и помогите тем, кого вы видели в подзорную трубу.','Я воспользовался той хитростью, которой ты научил меня, так что я все время следил за тобой. Удивительно!$B$BКстати, а как это тебе удалось заставить ту старушку летать?','Вернитесь к Тонку на Колючий Холм в Дуротар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Патрулирование Разлива Строптивой',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мой пост здесь, на башне, $n, и я не могу покинуть его. Но мне нужен кто-то, способный помочь тем, кто оказался в зоне наводнения.$b$bМогу ли я на тебя рассчитывать?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь к Разливу Строптивой и помогите тем, кого вы видели в подзорную трубу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я воспользовался той хитростью, которой ты научил меня, так что я все время следил за тобой. Удивительно!$B$BКстати, а как это тебе удалось заставить ту старушку летать?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тонку на Колючий Холм в Дуротар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (25189,'Хвала духам','Кто ты $gтакой:такая;? Что случилось?$b$bЯ находилась в своей хижине в одиночестве и предавалась размышлением, как...$b$bА-а, теперь вспомнила. Возопили духи, и река вышла из берегов своих. Мне повезло, что ты нашел меня здесь. Я стара и слаба, мне не выдержать такого буйства стихий. Ты поможешь мне выбраться отсюда?','Проводите престарелую Теклу к Ярагану.','Было время, когда могущество моей бабушки-шаманки не вызывало сомнений. Я, признаться, думал, что к своему преклонному возрасту она уже растеряла все умения, но, похоже, есть то, что остается с тобой навсегда.','Проводите престарелую Теклу к Ярагану.','Поговорите с Ярагану на Разливе Строптивой, что в Дуротаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хвала духам',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кто ты $gтакой:такая;? Что случилось?$b$bЯ находилась в своей хижине в одиночестве и предавалась размышлением, как...$b$bА-а, теперь вспомнила. Возопили духи, и река вышла из берегов своих. Мне повезло, что ты нашел меня здесь. Я стара и слаба, мне не выдержать такого буйства стихий. Ты поможешь мне выбраться отсюда?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проводите престарелую Теклу к Ярагану.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Было время, когда могущество моей бабушки-шаманки не вызывало сомнений. Я, признаться, думал, что к своему преклонному возрасту она уже растеряла все умения, но, похоже, есть то, что остается с тобой навсегда.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Проводите престарелую Теклу к Ярагану.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Ярагану на Разливе Строптивой, что в Дуротаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25190,'Ярость Ярагана','Свинобразы – то пятно, которое и разлившейся реке не смыть с нашей земли. Мне сказали спасаться, но моя работа здесь еще не закончена.$b$bХрррраагрх! Ненавижу свинобразов! Поможешь мне уничтожить их?','Убейте 4 свинобразов из племени Иглогривых и 4 разведчиков племени Иглогривых.','<Яраган выглядит несколько более спокойным, нежели во время предыдущей встречи.>$B$BХорошо, хорошо. Вот и еще один шажок на пути к полному уничтожению этих свинобразов... Глазки-бусинки, поклажа за спиной, пятачки-рыльца, два копытца…$B$B<Ярость вновь охватывает Ярагана.>$B$B...Горбатые, визжащие, шипастые... нехорошие... любители гномов... ГРИИИИИАГРХ! Свинобразы!','Вернитесь к Ярагану на Разлив Строптивой, что в Дуротаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ярость Ярагана',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Свинобразы – то пятно, которое и разлившейся реке не смыть с нашей земли. Мне сказали спасаться, но моя работа здесь еще не закончена.$b$bХрррраагрх! Ненавижу свинобразов! Поможешь мне уничтожить их?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 4 свинобразов из племени Иглогривых и 4 разведчиков племени Иглогривых.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Яраган выглядит несколько более спокойным, нежели во время предыдущей встречи.>$B$BХорошо, хорошо. Вот и еще один шажок на пути к полному уничтожению этих свинобразов... Глазки-бусинки, поклажа за спиной, пятачки-рыльца, два копытца…$B$B<Ярость вновь охватывает Ярагана.>$B$B...Горбатые, визжащие, шипастые... нехорошие... любители гномов... ГРИИИИИАГРХ! Свинобразы!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ярагану на Разлив Строптивой, что в Дуротаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`) VALUES (25191,'Исследование разрушений','Поговорите с Нибб Прядулягой на Заставе Чести, чтобы исследовать разрушения, вызванные катаклизмом.','Что-что?! Ты не видишь, нас атакуют!$B$B<Позвончик хватает данные исследований, потом небрежно запихивает их в брезентовую сумку.>$B$BДа, конечно, я внимательно все это изучу. Попозже. Когда буду в безопасности в Восточных королевствах, если, конечно, доберусь туда!','Исследование выполнено') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Исследование разрушений',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Нибб Прядулягой на Заставе Чести, чтобы исследовать разрушения, вызванные катаклизмом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что-что?! Ты не видишь, нас атакуют!$B$B<Позвончик хватает данные исследований, потом небрежно запихивает их в брезентовую сумку.>$B$BДа, конечно, я внимательно все это изучу. Попозже. Когда буду в безопасности в Восточных королевствах, если, конечно, доберусь туда!',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Исследование выполнено',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25192,'Неистовство Ярагана','Убейте 5 пылемутов из племени Иглогривых и 5 боевых стражей племени Иглогривых.','<И вновь, Яраган выглядит спокойнее.>$B$BТы хорошо постарался, незнакомец.$B$BСожалею, что тебе пришлось увидеть меня таким. Спасибо за то, что убил свинобразов, но, пожалуй, тебе стоит покинуть меня прежде, чем очередной приступ ярости возьмет верх надо мной.','Вернитесь к Ярагану в Разлив Строптивой, что в Дуротаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Неистовство Ярагана',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 5 пылемутов из племени Иглогривых и 5 боевых стражей племени Иглогривых.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<И вновь, Яраган выглядит спокойнее.>$B$BТы хорошо постарался, незнакомец.$B$BСожалею, что тебе пришлось увидеть меня таким. Спасибо за то, что убил свинобразов, но, пожалуй, тебе стоит покинуть меня прежде, чем очередной приступ ярости возьмет верх надо мной.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ярагану в Разлив Строптивой, что в Дуротаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (25193,'Пропавший, но не забытый','Сегодня исполняется ровно год со дня смерти моего сына Крона. Я долго отказывалась верить в это, но сейчас осознаю: Крон не вернется со своей охоты на кроколисков.$b$bМне бы хотелось как-то увековечить страсть Крона к охоте. Например, в виде ожерелья из зубов кроколисков... ряды зубов кроколисков, ожерелье, которое подойдет только самому храброму из молодых орков. Я положу его на могилу сына.$b$bКрон был храбрым, но он не был таким сильным, как ты. Не принесешь ли ты мне зубы кроколиска для ожерелья?','Соберите 250 зубов кроколисков.','Крон останется в нашей памяти.','Вернитесь к Майше Тор\'крену на Разлив Строптивой, что в Дуротаре.','Горячо любимый Крон, каким он был при жизни.','Крон') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пропавший, но не забытый',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сегодня исполняется ровно год со дня смерти моего сына Крона. Я долго отказывалась верить в это, но сейчас осознаю: Крон не вернется со своей охоты на кроколисков.$b$bМне бы хотелось как-то увековечить страсть Крона к охоте. Например, в виде ожерелья из зубов кроколисков... ряды зубов кроколисков, ожерелье, которое подойдет только самому храброму из молодых орков. Я положу его на могилу сына.$b$bКрон был храбрым, но он не был таким сильным, как ты. Не принесешь ли ты мне зубы кроколиска для ожерелья?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 250 зубов кроколисков.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Крон останется в нашей памяти.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Майше Тор\'крену на Разлив Строптивой, что в Дуротаре.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Горячо любимый Крон, каким он был при жизни.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Крон',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25194,'Незваные гости','Не беспокойся, с Зен\'Тажем все в порядке. Зен\'Таж изучает, что произошло, когда река вышла из берегов.$b$B$gВидел:Видела; тех высоких птиц, что стоят на речном берегу? Зен\'Таж думает, они попали в беду. Землетрясение и наводнение вынудили долгоногов уйти на тот берег реки. Теперь они боятся переплыть реку, а перелететь сюда просто не могут.$b$BЕсли они останутся там, они погибнут. Зен\'Таж не любит насилие, но может быть, ТЫ сможешь напасть на них там и испугать так, чтобы они перебрались на другой берег? Сможешь?','Заставить трех своенравных долгоногов побежать в сторону Степей.','Я люблю всех маленьких животных, эх. И всех больших тоже люблю. И мне больно смотреть, как ты делаешь это... Но это для их же блага.','Вернитесь к Зен\'Тажу на Разлив Строптивой, что в Дуротаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Незваные гости',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не беспокойся, с Зен\'Тажем все в порядке. Зен\'Таж изучает, что произошло, когда река вышла из берегов.$b$B$gВидел:Видела; тех высоких птиц, что стоят на речном берегу? Зен\'Таж думает, они попали в беду. Землетрясение и наводнение вынудили долгоногов уйти на тот берег реки. Теперь они боятся переплыть реку, а перелететь сюда просто не могут.$b$BЕсли они останутся там, они погибнут. Зен\'Таж не любит насилие, но может быть, ТЫ сможешь напасть на них там и испугать так, чтобы они перебрались на другой берег? Сможешь?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заставить трех своенравных долгоногов побежать в сторону Степей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я люблю всех маленьких животных, эх. И всех больших тоже люблю. И мне больно смотреть, как ты делаешь это... Но это для их же блага.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Зен\'Тажу на Разлив Строптивой, что в Дуротаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (25195,'Вот и пришел конец этому ящеру','Множество живых существ погибло, когда вода хлынула в долину – но только не ящеры. Коварные хищники сумели обратить несчастье других в свою пользу.$b$bОдин из ящеров особенно жесток. Он убивает маленьких животных и оставляет их тела гнить в воде, даже не притрагиваясь к ним! Его называют Живоглотом, и если не позаботиться о нем, он может серьезно нарушить баланс природы.$b$bОтправляйся на север, убей его, и пусть природа позаботится о его теле.','Убей ящера по имени Живоглот.','Зен\'Таж думает, с Живоглотом что-то произошло после того, как наступил катаклизм. Он не был столь безрассудно жесток прежде.$B$BБлагодарю за помощь, Пантяо. Зен\'Таж теперь может вернуться к своим исследованиям.','Вернитесь к Зен\'Тажу на Разлив Строптивой, что в Дуротаре.','Ужас Строптивой.','Живоглот') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вот и пришел конец этому ящеру',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Множество живых существ погибло, когда вода хлынула в долину – но только не ящеры. Коварные хищники сумели обратить несчастье других в свою пользу.$b$bОдин из ящеров особенно жесток. Он убивает маленьких животных и оставляет их тела гнить в воде, даже не притрагиваясь к ним! Его называют Живоглотом, и если не позаботиться о нем, он может серьезно нарушить баланс природы.$b$bОтправляйся на север, убей его, и пусть природа позаботится о его теле.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убей ящера по имени Живоглот.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Зен\'Таж думает, с Живоглотом что-то произошло после того, как наступил катаклизм. Он не был столь безрассудно жесток прежде.$B$BБлагодарю за помощь, Пантяо. Зен\'Таж теперь может вернуться к своим исследованиям.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Зен\'Тажу на Разлив Строптивой, что в Дуротаре.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Ужас Строптивой.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Живоглот',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (25196,'Застава Дранош\'ар','Ты тот, кто справился с Пылающим Клинком в южной части Дуротара? Мои уши повсюду, мальчик, а слухи распространяются быстро.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Застава Дранош\'ар',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты тот, кто справился с Пылающим Клинком в южной части Дуротара? Мои уши повсюду, мальчик, а слухи распространяются быстро.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (25197,'Адмирал не отступит','Ты рискнула проделать весь путь сюда от Заставы Чести? Отлично, твой опыт нам пригодится.$B$BМожет быть они и проломили стены, но Северная Стража не сдастся без борьбы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Адмирал не отступит',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты рискнула проделать весь путь сюда от Заставы Чести? Отлично, твой опыт нам пригодится.$B$BМожет быть они и проломили стены, но Северная Стража не сдастся без борьбы.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25198,'Винноа Сосновый Бор','Мы хорошо поработали здесь, надеюсь, никакая часть этих изменений не ускользнула от нашего внимания. Коридоры Пещеры Стенаний проходят подо всеми Степями, и если вдруг эта дикая энергия нашла где-то другой выход на поверхность...$b$bВпрочем, ты и так уже многое для меня $gсделал:сделала;. Я только прошу, чтобы бы ты $gсообщил:сообщила; о том, что здесь произошло, моей приятельнице, друиду. Ты найдешь Винноа Сосновый Бор в Лагере Вендетты, к юго-западу отсюда.','Поговорите с Винноа Сосновый Бор в Лагере вендетты в Южных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Винноа Сосновый Бор',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы хорошо поработали здесь, надеюсь, никакая часть этих изменений не ускользнула от нашего внимания. Коридоры Пещеры Стенаний проходят подо всеми Степями, и если вдруг эта дикая энергия нашла где-то другой выход на поверхность...$b$bВпрочем, ты и так уже многое для меня $gсделал:сделала;. Я только прошу, чтобы бы ты $gсообщил:сообщила; о том, что здесь произошло, моей приятельнице, друиду. Ты найдешь Винноа Сосновый Бор в Лагере Вендетты, к юго-западу отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Винноа Сосновый Бор в Лагере вендетты в Южных Степях.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25199,'Начальная подготовка','О! Кажется, ты сможешь нам помочь.$B$BНо если ты хочешь послужить нашему делу, тебе придется пройти обучение. Учти, не каждый может выдержать суровую муштру у гномов, так что готовься к тяжелым испытаниям.$B$BОтправляйся к сержанту-инструктору Парогону, он обучит тебя всему, что нужно. Смотри, внимательно исполняй все его указания, иначе никогда не закончишь подготовку.$B$BИ не говори потом, что я тебя не предупреждал. Возвращайся ко мне, если справишься с обучением.','Следуйте командам сержанта-инструктора Парогона, после чего вернитесь к капитану Ступу Искражу.','Вернитесь к капитану Ступу Искражу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Начальная подготовка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','О! Кажется, ты сможешь нам помочь.$B$BНо если ты хочешь послужить нашему делу, тебе придется пройти обучение. Учти, не каждый может выдержать суровую муштру у гномов, так что готовься к тяжелым испытаниям.$B$BОтправляйся к сержанту-инструктору Парогону, он обучит тебя всему, что нужно. Смотри, внимательно исполняй все его указания, иначе никогда не закончишь подготовку.$B$BИ не говори потом, что я тебя не предупреждал. Возвращайся ко мне, если справишься с обучением.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Следуйте командам сержанта-инструктора Парогона, после чего вернитесь к капитану Ступу Искражу.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Ступу Искражу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25200,'Выключение крошшеров','Этому негодяю торговому принцу Галливиксу каким-то образом удалось разместить на борту своей яхты целую футбомбную команду – "Акул Хитрой Шестеренки"! И ведь я даже не заметила!$B$BА теперь они делают за него всю грязную работу на вырубках. $n, ты же $gвыиграл:выиграла; для нас чемпионат на Кезане. И только ты сможешь избавить нас от них!','Убейте 8 акул Хитрой Шестеренки.','Раньше мне не очень нравилась футбомба, но благодаря тебе теперь я пересмотрю свои взгляды на эту игру!','Вернитесь к ассистентке Грили на вырубки картеля на Затерянных островах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Выключение крошшеров',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этому негодяю торговому принцу Галливиксу каким-то образом удалось разместить на борту своей яхты целую футбомбную команду – "Акул Хитрой Шестеренки"! И ведь я даже не заметила!$B$BА теперь они делают за него всю грязную работу на вырубках. $n, ты же $gвыиграл:выиграла; для нас чемпионат на Кезане. И только ты сможешь избавить нас от них!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 акул Хитрой Шестеренки.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Раньше мне не очень нравилась футбомба, но благодаря тебе теперь я пересмотрю свои взгляды на эту игру!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ассистентке Грили на вырубки картеля на Затерянных островах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25201,'Идеальная футбомбная униформа','Слушай, малыш, я здесь затем, чтобы к концу игры у тебя был шанс на победу. Траллу понадобится твоя помощь в борьбе с торговым принцем.$B$BМы с Грили и Хобартом изобрели идеальную футбомбную униформу, но чтобы ее изготовить, нам кое-что потребуется.$B$BК счастью, на этом складе полно запчастей крошшера. Так что двигай туда и поработай на все 110%!','Соберите 8 запчастей крошшера.','Да, это сойдет. Ты молодчина, малыш. Я позабочусь о том, чтобы тебе досталась лучшая футбомбная униформа в мире.$B$BА пока тебе нужно сбросить другие бомбы на прислужников торгового принца.','Вернитесь к тренеру Проверяку на вырубки картеля Трюмных Вод на Затерянных островах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Идеальная футбомбная униформа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слушай, малыш, я здесь затем, чтобы к концу игры у тебя был шанс на победу. Траллу понадобится твоя помощь в борьбе с торговым принцем.$B$BМы с Грили и Хобартом изобрели идеальную футбомбную униформу, но чтобы ее изготовить, нам кое-что потребуется.$B$BК счастью, на этом складе полно запчастей крошшера. Так что двигай туда и поработай на все 110%!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 запчастей крошшера.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, это сойдет. Ты молодчина, малыш. Я позабочусь о том, чтобы тебе досталась лучшая футбомбная униформа в мире.$B$BА пока тебе нужно сбросить другие бомбы на прислужников торгового принца.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к тренеру Проверяку на вырубки картеля Трюмных Вод на Затерянных островах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (25202,'Кратчайший путь к сердцу','Ох, подруга! Ты даже и представить себе не можешь, кто сейчас находится на нефтяной платформе к северу отсюда.$B$B<Иззи печально качает головой.>$B$BТам Чип – и он служит торговому принцу. Эта змея подколодная тебя предал и перешел на другую сторону. Говорят, теперь он гуляет с этой девкой – Конфеткой!$B$BЛично я на твоем месте вырвала бы ему сердце.','Вырвите все еще бьющееся сердце из груди Чипа Идейла.','Ну-ну, не плачь. Он получил по заслугам. Ты еще встретишь мужчину, который будет хорошо к тебе относиться.$B$BДавай, я заберу у тебя это... мы же не хотим, чтобы тебя приняли за сумасшедшую.','Ну, какое решение примешь? Смерть или прощение?','Вернитесь к Иззи на вырубки картеля на Затерянных островах.','Вырви из его груди все еще бьющееся сердце!','Чип Идейл') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кратчайший путь к сердцу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ох, подруга! Ты даже и представить себе не можешь, кто сейчас находится на нефтяной платформе к северу отсюда.$B$B<Иззи печально качает головой.>$B$BТам Чип – и он служит торговому принцу. Эта змея подколодная тебя предал и перешел на другую сторону. Говорят, теперь он гуляет с этой девкой – Конфеткой!$B$BЛично я на твоем месте вырвала бы ему сердце.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вырвите все еще бьющееся сердце из груди Чипа Идейла.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну-ну, не плачь. Он получил по заслугам. Ты еще встретишь мужчину, который будет хорошо к тебе относиться.$B$BДавай, я заберу у тебя это... мы же не хотим, чтобы тебя приняли за сумасшедшую.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, какое решение примешь? Смерть или прощение?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Иззи на вырубки картеля на Затерянных островах.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Вырви из его груди все еще бьющееся сердце!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Чип Идейл',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (25203,'Что за имя такое – Чип?','Дружище! Ни за что не догадаешься, кто появился на нефтяной платформе к северу отсюда.$B$B<Туз недоверчиво качает головой.>$B$BТам Чип, и теперь он работает на торгового принца. Представляешь! Этот предатель работает теперь на другую команду! А что еще хуже – слыхал я, он теперь тусуется с твоей бывшей, с Конфеткой!$B$BНе знаю, как ты... но если бы он гулял с МОЕЙ бывшей, я бы обязательно отреагировал.','Убейте Чипа Идейла.','Что ж, другого пути не было. Что он заслужил, то и получил.','Вернитесь к Тузу на вырубки картеля Трюмных Вод на Затерянных островах.','Долой этого неудачника!','Чип Идейл') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Что за имя такое – Чип?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Дружище! Ни за что не догадаешься, кто появился на нефтяной платформе к северу отсюда.$B$B<Туз недоверчиво качает головой.>$B$BТам Чип, и теперь он работает на торгового принца. Представляешь! Этот предатель работает теперь на другую команду! А что еще хуже – слыхал я, он теперь тусуется с твоей бывшей, с Конфеткой!$B$BНе знаю, как ты... но если бы он гулял с МОЕЙ бывшей, я бы обязательно отреагировал.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Чипа Идейла.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что ж, другого пути не было. Что он заслужил, то и получил.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тузу на вырубки картеля Трюмных Вод на Затерянных островах.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Долой этого неудачника!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Чип Идейл',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25204,'Система охлаждения','Надо лишить торгового принца Галливикса запасов нефти – застопорить работу нефтедобывающих агрегатов.$B$BИ в этом понадобится твоя помощь. Отправляйся на нефтяную платформу ТКК и открой клапаны – это вызовет перегрузку системы охлаждения. А потом разыщи пульт управления и взорви платформу.','Откройте клапаны с 1-го по 4-й.','Индикаторы на панели управления будто с ума посходили!','Активируйте пульт управления на нефтяной платформе ТКК.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Система охлаждения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Надо лишить торгового принца Галливикса запасов нефти – застопорить работу нефтедобывающих агрегатов.$B$BИ в этом понадобится твоя помощь. Отправляйся на нефтяную платформу ТКК и открой клапаны – это вызовет перегрузку системы охлаждения. А потом разыщи пульт управления и взорви платформу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Откройте клапаны с 1-го по 4-й.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Индикаторы на панели управления будто с ума посходили!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Активируйте пульт управления на нефтяной платформе ТКК.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25205,'Волк и кодо','Мой "коллега" рассчитывал, что ты кое-что сделаешь для него, вот только я не согласен с этим. Слишком часто он действует опрометчиво, непродуманно и совершенно безответственно. Рано или поздно за это придется заплатить ценой собственной жизни.$b$bПрежде чем ты согласишься работать на Гора, выслушай мой рассказ. Это притча – легенда, в которой заключена мораль, но я надеюсь, что этот урок окажется для тебя ценным. Обратись ко мне, когда будешь $gготов:готова; выслушать историю.','Выслушайте поучительную притчу Шина Каменостолба.','Мораль этой истории такова: нужно всегда хорошо продумывать свои действия, иначе спешка приведет к печальным последствиям. В работе нужно стремиться достичь результата, пусть даже и затратив больше времени. Я пытался поведать это и "Головорезу", но, боюсь, череп истинного Адского Крика немного толстоват для такой премудрости.','Вернитесь к Шину Каменостолбу на насыпь Драноша в Дуротар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Волк и кодо',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мой "коллега" рассчитывал, что ты кое-что сделаешь для него, вот только я не согласен с этим. Слишком часто он действует опрометчиво, непродуманно и совершенно безответственно. Рано или поздно за это придется заплатить ценой собственной жизни.$b$bПрежде чем ты согласишься работать на Гора, выслушай мой рассказ. Это притча – легенда, в которой заключена мораль, но я надеюсь, что этот урок окажется для тебя ценным. Обратись ко мне, когда будешь $gготов:готова; выслушать историю.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выслушайте поучительную притчу Шина Каменостолба.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мораль этой истории такова: нужно всегда хорошо продумывать свои действия, иначе спешка приведет к печальным последствиям. В работе нужно стремиться достичь результата, пусть даже и затратив больше времени. Я пытался поведать это и "Головорезу", но, боюсь, череп истинного Адского Крика немного толстоват для такой премудрости.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Шину Каменостолбу на насыпь Драноша в Дуротар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25206,'Пустые предостережения','Не обращай внимания на шамана, солдат. Кое-кто из сильных мира сего хочет, чтобы он оставался со мной. Но уверяю тебя, взор этого преданного Траллу провидца не простирается даже за пределы его хижины.$b$bК западу отсюда элементали сражаются друг с другом. Я бы, пожалуй, и не был против, но эта земля нужна мне чистой. Здесь должен проходить безопасный торговый путь в Степи. Обычно элементали довольны сильны, но сейчас они ослаблены враждой между собой. Это знание должно тебе помочь уничтожить их.','Убейте 12 неистовствующих элементалей. Подойдут гневные земляные стражи или бурлящие водяные стражи.','Понимаешь? Россказни шаманов не более, чем... детские сказки на ночь. Обновленная Орда берет то, что хочет, и не тратит время на эти предрассудки.$B$BЕсли тебе выпадет еще шанс, советую сказать Шину... да и другим таким же... чтобы они больше не тратили твое время понапрасну.','Вернитесь к Гору "Головорезу" на Насыпь Драноша в Дуротар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пустые предостережения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не обращай внимания на шамана, солдат. Кое-кто из сильных мира сего хочет, чтобы он оставался со мной. Но уверяю тебя, взор этого преданного Траллу провидца не простирается даже за пределы его хижины.$b$bК западу отсюда элементали сражаются друг с другом. Я бы, пожалуй, и не был против, но эта земля нужна мне чистой. Здесь должен проходить безопасный торговый путь в Степи. Обычно элементали довольны сильны, но сейчас они ослаблены враждой между собой. Это знание должно тебе помочь уничтожить их.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 неистовствующих элементалей. Подойдут гневные земляные стражи или бурлящие водяные стражи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Понимаешь? Россказни шаманов не более, чем... детские сказки на ночь. Обновленная Орда берет то, что хочет, и не тратит время на эти предрассудки.$B$BЕсли тебе выпадет еще шанс, советую сказать Шину... да и другим таким же... чтобы они больше не тратили твое время понапрасну.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гору "Головорезу" на Насыпь Драноша в Дуротар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25207,'Прощай, черное золотце!','Там на платформе, на панели управления, есть такая большая красная кнопка. Вот если нажать эту кнопку, наверняка произойдет большой взрыв!','Нажмите на большую красную кнопку, чтобы уничтожить нефтяную платформу ТКК.','Неплохо так жахнуло! Жар от взрывов аж досюда дошел.','Вернитесь к ассистентке Грили на вырубки картеля Трюмных Вод на Затерянных островах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прощай, черное золотце!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Там на платформе, на панели управления, есть такая большая красная кнопка. Вот если нажать эту кнопку, наверняка произойдет большой взрыв!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Нажмите на большую красную кнопку, чтобы уничтожить нефтяную платформу ТКК.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Неплохо так жахнуло! Жар от взрывов аж досюда дошел.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ассистентке Грили на вырубки картеля Трюмных Вод на Затерянных островах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (25208,'Донесение для Сильвии','Поговорите с Сильвией в башне Эстулана.','Вот и ты. Ну, что сказал Эстулан?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Донесение для Сильвии',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Сильвией в башне Эстулана.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот и ты. Ну, что сказал Эстулан?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25209,'Угроза Гордунни','В Высокогорных дебрях к югу отсюда разбросано бесчисленное множество древних руин. Предки нынешних ночных эльфов баловались в тех местах с тайной магией, а сейчас там бродят огры из клана Гордунни, разыскивая следы былого колдовства.$B$BУвидишь своими глазами, что лес в тех местах совершенно уничтожен: после огров остается лишь мерзость запустения, а еще они отнимают у Орды необходимые ресурсы.$B$BИди и убей тамошних Гордунни, $n. Эта местность должна быть под контролем Орды, и только Орды!','Убейте 16 огров из клана Гордунни в Высокогорных дебрях.','Вернитесь к Орхан Огрский Клинок в крепость Каменного Молота в Фералас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Угроза Гордунни',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В Высокогорных дебрях к югу отсюда разбросано бесчисленное множество древних руин. Предки нынешних ночных эльфов баловались в тех местах с тайной магией, а сейчас там бродят огры из клана Гордунни, разыскивая следы былого колдовства.$B$BУвидишь своими глазами, что лес в тех местах совершенно уничтожен: после огров остается лишь мерзость запустения, а еще они отнимают у Орды необходимые ресурсы.$B$BИди и убей тамошних Гордунни, $n. Эта местность должна быть под контролем Орды, и только Орды!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 16 огров из клана Гордунни в Высокогорных дебрях.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Орхан Огрский Клинок в крепость Каменного Молота в Фералас.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25210,'Знаки перемен','Странная болезнь поразила зверей в этом лесу. Поначалу я надеялся, что она пройдет, но надежды мои были тщетны.$B$BЛесные олени более других существ пострадали от этой странной болезни. Некоторые из них не могут встать от слабости, другие, напротив, впали в бешеную ярость. Если я хочу выяснить причину этой болезни у духов, мне понадобятся рога этих оленей.','Соберите 8 рогов зараженных оленей.','Вернитесь к Кону Руническому Тотему в лагерь Атайа в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Знаки перемен',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Странная болезнь поразила зверей в этом лесу. Поначалу я надеялся, что она пройдет, но надежды мои были тщетны.$B$BЛесные олени более других существ пострадали от этой странной болезни. Некоторые из них не могут встать от слабости, другие, напротив, впали в бешеную ярость. Если я хочу выяснить причину этой болезни у духов, мне понадобятся рога этих оленей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 рогов зараженных оленей.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кону Руническому Тотему в лагерь Атайа в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25211,'Сор из избы!','Не слушай Рарена. Он сразу киснет, как они приходят. Это из-за него у нас эль сперли!$B$BБолее того, тут не только эль сперли, тут кое-чего похуже. Тут целая шайка орков шляется вокруг Дун Альгаза, столько лет спустя-то!$B$BВот что я тебе скажу, |3-6($c). Топай туда и выгони из тех развалин сколько сумеешь орков. Дун Альгаз нам больше не нужен, но разрази меня гром, если мы позволим им там засесть!','Убейте 5 орков из клана Драконьей Пасти в Дун Альгазе.','Так им! Славная работа!','Вернитесь к горному пехотинцу Грюгельму в Дун Альгах, что в Болотине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сор из избы!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не слушай Рарена. Он сразу киснет, как они приходят. Это из-за него у нас эль сперли!$B$BБолее того, тут не только эль сперли, тут кое-чего похуже. Тут целая шайка орков шляется вокруг Дун Альгаза, столько лет спустя-то!$B$BВот что я тебе скажу, |3-6($c). Топай туда и выгони из тех развалин сколько сумеешь орков. Дун Альгаз нам больше не нужен, но разрази меня гром, если мы позволим им там засесть!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 5 орков из клана Драконьей Пасти в Дун Альгазе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так им! Славная работа!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к горному пехотинцу Грюгельму в Дун Альгах, что в Болотине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25212,'Разведать обстановку','Мы думали, что сможем дождаться того момента, когда радиационный фон вокруг Гномрегана снизится, но время идет, а ситуация не улучшается.$B$BЕсли мы хотим отвоевать город, надо обеспечить безопасность солдат.$B$BВозьми эти радиометрозиметры, забирайся в "Молнию" и сбрось устройство в шахту вентиляции на подходах к Гномрегану. Данные об уровне радиации будут поступать непосредственно мне.','Воспользуйтесь летательным аппаратом пилота Винтоуха, чтобы сбросить радиометрозиметры в вентиляционные шахты Гномрегана.','Поговорите с пилотом Винтоухом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разведать обстановку',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы думали, что сможем дождаться того момента, когда радиационный фон вокруг Гномрегана снизится, но время идет, а ситуация не улучшается.$B$BЕсли мы хотим отвоевать город, надо обеспечить безопасность солдат.$B$BВозьми эти радиометрозиметры, забирайся в "Молнию" и сбрось устройство в шахту вентиляции на подходах к Гномрегану. Данные об уровне радиации будут поступать непосредственно мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь летательным аппаратом пилота Винтоуха, чтобы сбросить радиометрозиметры в вентиляционные шахты Гномрегана.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с пилотом Винтоухом.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (25213,'Ямы рабов','Хамми сейчас в Ямах рабов. Они с орками готовятся разыграть последнюю комбинацию в игре с торговым принцем.$B$B$n, возьми эту футбомбную униформу, отправляйся по дороге на юго-запад, найди Хамми. Знаю, она хочет поручить командование тебе!$B$BТьфу ты, я уже начинаю говорить, как тренер!','Поговорите с Хамми Кофельнагель в Ямах рабов.','Интересно, где тебя носило!$B$BНе переживай… мы превратим эту футбомбную униформу в самую классную футбомную униформу, какая только бывает!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ямы рабов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хамми сейчас в Ямах рабов. Они с орками готовятся разыграть последнюю комбинацию в игре с торговым принцем.$B$B$n, возьми эту футбомбную униформу, отправляйся по дороге на юго-запад, найди Хамми. Знаю, она хочет поручить командование тебе!$B$BТьфу ты, я уже начинаю говорить, как тренер!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Хамми Кофельнагель в Ямах рабов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Интересно, где тебя носило!$B$BНе переживай… мы превратим эту футбомбную униформу в самую классную футбомную униформу, какая только бывает!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25214,'Вторая космическая','Вообще-то у нас нет времени спасать тех, кто настолько туп, чтобы попадаться снова и снова. Но так как у меня осталось немного ракет после зарядки твоей идеальной формы для футбомбы, все решаемо.$B$BОттащи эти одноступенчатые ракеты-носители вниз, в Ямы рабов на севере, и прикрепи их к клеткам.$B$BКлетки выйдут на орбиту, и эти идиоты будут свободны.','С помощью одноступенчатых ракет-носителей запустите в полет 8 клеток с кезанскими горожанами или уцелевшими гоблинами.','Ой... Ну да – то, что взлетает, когда-нибудь обязательно упадет...','Вернитесь к Хобарту Дреку к Ямам рабов на Затерянных островах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вторая космическая',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вообще-то у нас нет времени спасать тех, кто настолько туп, чтобы попадаться снова и снова. Но так как у меня осталось немного ракет после зарядки твоей идеальной формы для футбомбы, все решаемо.$B$BОттащи эти одноступенчатые ракеты-носители вниз, в Ямы рабов на севере, и прикрепи их к клеткам.$B$BКлетки выйдут на орбиту, и эти идиоты будут свободны.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','С помощью одноступенчатых ракет-носителей запустите в полет 8 клеток с кезанскими горожанами или уцелевшими гоблинами.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ой... Ну да – то, что взлетает, когда-нибудь обязательно упадет...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хобарту Дреку к Ямам рабов на Затерянных островах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25215,'Генеральная уборка','Хищники за версту учуют запах мертвых наг, и тогда нам придется сражаться, чтобы просто войти или выйти из пещеры. Не поможешь мне прибраться?$B$BК югу отсюда, за обрывом, располагается Теснина Мерцающих Глубин. Оттащи трупы наг с восточного входа в теснину – местные хищники разделаются с ними так быстро, что они даже не успеют опуститься на дно. Главное – держись подальше от акул.','Оттащите троих мертвых налетчиков Зин\'жатара в открытое море за Теснину Мерцающих Глубин.','Думаю, скоро вода очистится. Спасибо за помощь.','Поговорите с Фелорой Огненное Кольцо в Пещере Серебряной Волны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Генеральная уборка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хищники за версту учуют запах мертвых наг, и тогда нам придется сражаться, чтобы просто войти или выйти из пещеры. Не поможешь мне прибраться?$B$BК югу отсюда, за обрывом, располагается Теснина Мерцающих Глубин. Оттащи трупы наг с восточного входа в теснину – местные хищники разделаются с ними так быстро, что они даже не успеют опуститься на дно. Главное – держись подальше от акул.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Оттащите троих мертвых налетчиков Зин\'жатара в открытое море за Теснину Мерцающих Глубин.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Думаю, скоро вода очистится. Спасибо за помощь.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Фелорой Огненное Кольцо в Пещере Серебряной Волны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25216,'Великий Самбино','Если поплывешь дальше по каньону, окажи мне услугу – проведай одного из наших новичков.$B$BЕго зовут Сэм, но он наверняка представится более витиевато. По правде говоря, он слабо представляет себе, чем занимаются Служители Земли, но старается как может, поэтому мы держим его в блаженном неведении.$B$BНо не стоит слишком увлекаться его безумными идеями: просто убедись, что с ним все в порядке, и сообщи мне.','Найдите "Сэма" на западе Котловины Серебряной Волны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Великий Самбино',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если поплывешь дальше по каньону, окажи мне услугу – проведай одного из наших новичков.$B$BЕго зовут Сэм, но он наверняка представится более витиевато. По правде говоря, он слабо представляет себе, чем занимаются Служители Земли, но старается как может, поэтому мы держим его в блаженном неведении.$B$BНо не стоит слишком увлекаться его безумными идеями: просто убедись, что с ним все в порядке, и сообщи мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите "Сэма" на западе Котловины Серебряной Волны.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25217,'Тотемы нового поколения','Ладно, раз уж в твоих глазах столько отчаяния, позволю тебе заняться настоящей работой.$B$BЭта скала – кладезь сокровищ! Королям и принцам такое не снилось! Мне нужны образцы. Много образцов. Отовсюду!$B$BЯ немного модифицировал свои тотемы земли – теперь они могут бурить скалу. Ступай, найди подходящее место и помести туда тотем.$B$BТряска и грохот наверняка привлекут внимание местной фауны, так что заодно и друзей заведешь.','Поместите один из усовершенствованных тотемов Самбино в песок Котловины Серебряной Волны.','Еще один образец. Прекрасно! Все богатства этого моря скоро будут принадлежать только мне!','Вернитесь к Великому Самбино на запад Котловины Серебряной Волны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тотемы нового поколения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ладно, раз уж в твоих глазах столько отчаяния, позволю тебе заняться настоящей работой.$B$BЭта скала – кладезь сокровищ! Королям и принцам такое не снилось! Мне нужны образцы. Много образцов. Отовсюду!$B$BЯ немного модифицировал свои тотемы земли – теперь они могут бурить скалу. Ступай, найди подходящее место и помести туда тотем.$B$BТряска и грохот наверняка привлекут внимание местной фауны, так что заодно и друзей заведешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поместите один из усовершенствованных тотемов Самбино в песок Котловины Серебряной Волны.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Еще один образец. Прекрасно! Все богатства этого моря скоро будут принадлежать только мне!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Великому Самбино на запад Котловины Серебряной Волны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25218,'Подводный воздух','Ладно! Ладно. $GУбедил:Убедила;. Можешь мне помочь.$B$BУ меня утечка воздуха. Дует, как из дирижабля со свинобразами! Видимо, воздушный клапан оторвался.$B$BЯ принес запасные шары для воздуха – сходи и наполни один из них, а? И найди мой клапан! Он где-то в каньоне.$B$BНаверняка его крабы оторвали... Маленькие жадные гаденыши.','Наполните один из воздушных шаров Самбино и найдите его потерянный воздушный клапан.','М-да, надо было обвешать тебя грузами, чтобы не утащило вверх вслед за шаром. Но, к счастью, на тебе был доспех! Ха!','Вот бы воздух не был легче воды! Или заклинания для дыхания под водой поставлялись со стильными шлемами в придачу! Меня устроил бы любой вариант!','Вернитесь к Великому Самбино на запад Котловины Серебряной Волны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подводный воздух',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ладно! Ладно. $GУбедил:Убедила;. Можешь мне помочь.$B$BУ меня утечка воздуха. Дует, как из дирижабля со свинобразами! Видимо, воздушный клапан оторвался.$B$BЯ принес запасные шары для воздуха – сходи и наполни один из них, а? И найди мой клапан! Он где-то в каньоне.$B$BНаверняка его крабы оторвали... Маленькие жадные гаденыши.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Наполните один из воздушных шаров Самбино и найдите его потерянный воздушный клапан.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','М-да, надо было обвешать тебя грузами, чтобы не утащило вверх вслед за шаром. Но, к счастью, на тебе был доспех! Ха!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вот бы воздух не был легче воды! Или заклинания для дыхания под водой поставлялись со стильными шлемами в придачу! Меня устроил бы любой вариант!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Великому Самбино на запад Котловины Серебряной Волны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25219,'Ракушкомания','Я изучаю улиток.$B$BДа, улиток. Когда отсмеешься, я перейду к делу.$B$BДумаю, ты уже $gзаметил:заметила; ту гигантскую ракушку на другой стороне рифа... В ней что-то есть. Я заметил несколько отверстий, через которые мои подопытные протискиваются туда и обратно.$B$BПолагаю, что с помощью улиток мы можем создать проход и для нас. Теоретически.','Соберите 10 улиток c витыми раковинами.','Знаю, это не самое приятное задание, но разве тебе не интересно, что в этой раковине? Она же огромная. Там обязательно должно что-то быть.','Вернитесь к Целителю Земли Дуарну в Пещеру Серебряной Волны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ракушкомания',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я изучаю улиток.$B$BДа, улиток. Когда отсмеешься, я перейду к делу.$B$BДумаю, ты уже $gзаметил:заметила; ту гигантскую ракушку на другой стороне рифа... В ней что-то есть. Я заметил несколько отверстий, через которые мои подопытные протискиваются туда и обратно.$B$BПолагаю, что с помощью улиток мы можем создать проход и для нас. Теоретически.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 улиток c витыми раковинами.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Знаю, это не самое приятное задание, но разве тебе не интересно, что в этой раковине? Она же огромная. Там обязательно должно что-то быть.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Целителю Земли Дуарну в Пещеру Серебряной Волны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25220,'Скользкая угроза','На тебя еще не нападали местные угри? Значит, все впереди. Этим злобным кровожадным тварям, похоже, все равно, кого кусать.$B$BЕсли ты собираешься в котловину, сделай милость – сократи их популяцию. Не все тут так экипированы, как ты, и одними царапинами мы от них не отделаемся.','Убейте 12 шипозубых угрей.','Вернитесь к управляющему Мовре в Пещеру Серебряной Волны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Скользкая угроза',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На тебя еще не нападали местные угри? Значит, все впереди. Этим злобным кровожадным тварям, похоже, все равно, кого кусать.$B$BЕсли ты собираешься в котловину, сделай милость – сократи их популяцию. Не все тут так экипированы, как ты, и одними царапинами мы от них не отделаемся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 шипозубых угрей.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к управляющему Мовре в Пещеру Серебряной Волны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25221,'Погоня','Они отступают!$B$BЭто те самые наги, которые напали на наши корабли и забрали наших друзей. Нельзя дать им уйти!$B$BВозьми эти копья и догони врагов на своем морском коньке... Не слезай с него, просто убей как можно больше наг копьем.$B$BА я постараюсь догнать Повелителя глубин. Встретимся на дальнем краю рифа, когда закончишь.','Пронзите охотничьим копьем Тоша 20 убегающих наг Зин\'жатара.','Ловко сработано. Впечатляет.$B$BПовелитель глубин скрылся... нигде его не видно. А ведь он – ключ к спасению наших друзей.$B$BНо я его найду. Он не сможет прятаться вечно.','Найдите Тоша Приносящего Хаос в южной части Мерцающего грота.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Погоня',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Они отступают!$B$BЭто те самые наги, которые напали на наши корабли и забрали наших друзей. Нельзя дать им уйти!$B$BВозьми эти копья и догони врагов на своем морском коньке... Не слезай с него, просто убей как можно больше наг копьем.$B$BА я постараюсь догнать Повелителя глубин. Встретимся на дальнем краю рифа, когда закончишь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Пронзите охотничьим копьем Тоша 20 убегающих наг Зин\'жатара.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ловко сработано. Впечатляет.$B$BПовелитель глубин скрылся... нигде его не видно. А ведь он – ключ к спасению наших друзей.$B$BНо я его найду. Он не сможет прятаться вечно.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Найдите Тоша Приносящего Хаос в южной части Мерцающего грота.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25222,'Пещера Серебряной Волны','Большинство Служителей Земли, спасшихся от врага на лодках, прячется в пещере неподалеку от рифа. Она находится между огромными скалами к западу от Неспиры, гигантской раковины на горизонте. Нужно, чтобы ты $gотправился:отправилась; туда и $gубедился:убедилась;, что они в порядке. К тому же мы не знаем, сколько наг на них напало.$B$BА я постараюсь выследить Повелителя глубин. Дам знать, когда найду его логово.','Найдите Фелору Огненное Кольцо в Пещере Серебряной Волны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пещера Серебряной Волны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Большинство Служителей Земли, спасшихся от врага на лодках, прячется в пещере неподалеку от рифа. Она находится между огромными скалами к западу от Неспиры, гигантской раковины на горизонте. Нужно, чтобы ты $gотправился:отправилась; туда и $gубедился:убедилась;, что они в порядке. К тому же мы не знаем, сколько наг на них напало.$B$BА я постараюсь выследить Повелителя глубин. Дам знать, когда найду его логово.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Фелору Огненное Кольцо в Пещере Серебряной Волны.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25223,'Испытание огнем','Я могла бы сказать, что поскольку наши дела на Хиджале идут не очень хорошо, нам нужен каждый рекрут и так далее... но если честно, большинство из вас – попросту балласт.$B$BЕсли бы мне за каждого крестьянина, который испугался Катаклизма и решил к нам присоединиться, давали по медяку... скажем так, я бы давно разбогатела.$B$BК счастью, у нас есть способы отделить зерна от плевел. Иди к огненным наставникам и покажи, на что $gспособен:способна;. Надеюсь, ты окажешься лучше остальных.','Победите 8 огненных наставников.','Я думаю, твои способности… нам подходят. Впечатляюще.','Вернитесь к Проклинии Безжалостной к Сумеречному ходу на Хиджале.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Испытание огнем',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я могла бы сказать, что поскольку наши дела на Хиджале идут не очень хорошо, нам нужен каждый рекрут и так далее... но если честно, большинство из вас – попросту балласт.$B$BЕсли бы мне за каждого крестьянина, который испугался Катаклизма и решил к нам присоединиться, давали по медяку... скажем так, я бы давно разбогатела.$B$BК счастью, у нас есть способы отделить зерна от плевел. Иди к огненным наставникам и покажи, на что $gспособен:способна;. Надеюсь, ты окажешься лучше остальных.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите 8 огненных наставников.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я думаю, твои способности… нам подходят. Впечатляюще.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Проклинии Безжалостной к Сумеречному ходу на Хиджале.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25224,'В цвете','Это обыкновенная практика – посылать рекрутов выполнять практически невозможные задания. Меня послали добыть чешуйку черного дракона; в прошлом году наставники требовали перо феникса.$B$BТвое задание будет полегче. Принеси мне горсть огненных цветов.$B$BОни повсюду тут растут. Ах да. Чтобы тебе не было скучно, по полям будет бродить гигантская гончая недр. Не попадись ей!','Добудьте 5 огненных цветков.','Значит, тебе удалось пройти эту часть испытания, Тлетвор тебя не съел, а огненные элементали не поджарили?$B$BДумаю, стоит поздравить тебя с получением низшего ранга.$B$BНу… Поздравляю, рекрут!','Вернитесь к Проклинии Безжалостной к Сумеречному ходу на Хиджале.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В цвете',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это обыкновенная практика – посылать рекрутов выполнять практически невозможные задания. Меня послали добыть чешуйку черного дракона; в прошлом году наставники требовали перо феникса.$B$BТвое задание будет полегче. Принеси мне горсть огненных цветов.$B$BОни повсюду тут растут. Ах да. Чтобы тебе не было скучно, по полям будет бродить гигантская гончая недр. Не попадись ей!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 5 огненных цветков.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Значит, тебе удалось пройти эту часть испытания, Тлетвор тебя не съел, а огненные элементали не поджарили?$B$BДумаю, стоит поздравить тебя с получением низшего ранга.$B$BНу… Поздравляю, рекрут!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Проклинии Безжалостной к Сумеречному ходу на Хиджале.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25225,'Замена смазки','Смазка в этих крошшерах совсем никуда не годится. Старое доброе каджарское масло категории 0В – вот что нам нужно!$B$BА ты знаешь, где оно есть? В нефтяных роботах ТКК! А как их можно найти, думаешь? На северо-западе, на нефтяной платформе ТКК!','Соберите 6 порций каджарского масла категории 0В.','Вернитесь к тренеру Проверяку на вырубки картеля на Затерянных островах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Замена смазки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Смазка в этих крошшерах совсем никуда не годится. Старое доброе каджарское масло категории 0В – вот что нам нужно!$B$BА ты знаешь, где оно есть? В нефтяных роботах ТКК! А как их можно найти, думаешь? На северо-западе, на нефтяной платформе ТКК!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 6 порций каджарского масла категории 0В.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к тренеру Проверяку на вырубки картеля на Затерянных островах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (25226,'Kill Chip Endale Tracking Quest') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Kill Chip Endale Tracking Quest',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (25227,'Тонк','$gОх, сладенький мой, только что вспомнила!:Извини, если отнеслась к тебе с прохладцей. Я не очень-то уверена в себе, так что иногда чуточку ревную к другим женщинам, приходящим в город.;$b$bМой ОЧЕНЬ хороший друг Тонк служит на сторожевой башне тут, в горах, на западе от Колючего Холма. Он вроде бы говорил, что река вышла из берегов, многое необходимо сделать, ну и так далее. Я не очень-то внимательно вслушивалась... У него ведь такие глубокие карие глаза.$b$b$gЧто, мы не можем уже и с другими людьми пообщаться?:Спасибо.;','Найдите Тонка на сторожевой башне, что к северо-западу от Колючего Холма.','Зоря послала тебя? Она... Она что-нибудь говорила обо мне?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тонк',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$gОх, сладенький мой, только что вспомнила!:Извини, если отнеслась к тебе с прохладцей. Я не очень-то уверена в себе, так что иногда чуточку ревную к другим женщинам, приходящим в город.;$b$bМой ОЧЕНЬ хороший друг Тонк служит на сторожевой башне тут, в горах, на западе от Колючего Холма. Он вроде бы говорил, что река вышла из берегов, многое необходимо сделать, ну и так далее. Я не очень-то внимательно вслушивалась... У него ведь такие глубокие карие глаза.$b$b$gЧто, мы не можем уже и с другими людьми пообщаться?:Спасибо.;',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Тонка на сторожевой башне, что к северо-западу от Колючего Холма.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Зоря послала тебя? Она... Она что-нибудь говорила обо мне?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25228,'Пророчества о конце света','Вестники рока довольно часто появляются на улицах Оргриммара, но эта последняя шайка меня беспокоит. Они произвели настоящий переполох в Волоке, и их банда отличается четкой организацией.$B$BЯ было подумал слегка сократить их численность, но боюсь, что это лишь заставит их уйти в подполье. Надо узнать как можно больше об этой шайке! Пожалуйста, отправляйся в Волок, послушай, что они рассказывают и к чему призывают, собери какие-нибудь бумаги, которые могли бы пролить свет на их деятельность.','Выслушайте речь вестника рока в Волоке и найдите копии листовок "Стенания души в пламени первородного огня", "Конец всего сущего – правда и домыслы" и "Мир обречен, но дух мой чист и безмятежен...".','Вернитесь к кровавому стражу Тореку на Аллею Силы Оргриммара.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пророчества о конце света',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вестники рока довольно часто появляются на улицах Оргриммара, но эта последняя шайка меня беспокоит. Они произвели настоящий переполох в Волоке, и их банда отличается четкой организацией.$B$BЯ было подумал слегка сократить их численность, но боюсь, что это лишь заставит их уйти в подполье. Надо узнать как можно больше об этой шайке! Пожалуйста, отправляйся в Волок, послушай, что они рассказывают и к чему призывают, собери какие-нибудь бумаги, которые могли бы пролить свет на их деятельность.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выслушайте речь вестника рока в Волоке и найдите копии листовок "Стенания души в пламени первородного огня", "Конец всего сущего – правда и домыслы" и "Мир обречен, но дух мой чист и безмятежен...".',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к кровавому стражу Тореку на Аллею Силы Оргриммара.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (25229,'Несколько хороших гномов','Обратитесь к капитану Ступу Искражу в Поселке Сталежара.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Несколько хороших гномов',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Обратитесь к капитану Ступу Искражу в Поселке Сталежара.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25230,'Не просто болезнь','Мы нашли стайку дракончиков на дороге к северу отсюда, и они страдают от той же болезни, что и олени.$B$BЗеленые драконы – не просто какие-то звери, а самые настоящие стражи природы. Они – волшебные существа, и раз уж даже они заболели, то, значит, эта угроза и впрямь велика.$B$BНам нужно во что бы то ни стало не дать болезни распространиться дальше. Убей заразных дракончиков, $n, а потом возвращайся ко мне.','Убейте 10 зараженных дракончиков.','Эти события очень тревожат меня. Пока тебя не было, я изучал оленьи рога, впрочем, это мало что дало.$B$BНо мы должны что-то придумать…','Вернитесь к Кону Руническому Тотему в лагерь Атайа в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Не просто болезнь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы нашли стайку дракончиков на дороге к северу отсюда, и они страдают от той же болезни, что и олени.$B$BЗеленые драконы – не просто какие-то звери, а самые настоящие стражи природы. Они – волшебные существа, и раз уж даже они заболели, то, значит, эта угроза и впрямь велика.$B$BНам нужно во что бы то ни стало не дать болезни распространиться дальше. Убей заразных дракончиков, $n, а потом возвращайся ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 зараженных дракончиков.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Эти события очень тревожат меня. Пока тебя не было, я изучал оленьи рога, впрочем, это мало что дало.$B$BНо мы должны что-то придумать…',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кону Руническому Тотему в лагерь Атайа в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25231,'Подонки Южных морей','Прямо сейчас Аггра и Килаг атакуют причал, чтобы расчистить путь Траллу и дать ему возможность вступить в бой с торговым принцем. План состоит в том, чтобы ты $gпомог:помогла; в этой атаке, но для начала нужно сделать так, чтобы наемники Южных морей Галливикса не пришли ему на помощь.$B$BСпустись в Ямы рабов и сделай все необходимое, чтобы наемники оттуда не выбрались!','Убейте 6 наемников Южных морей.','Вернитесь к Чогу к Ямам рабов на Затерянных островах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подонки Южных морей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прямо сейчас Аггра и Килаг атакуют причал, чтобы расчистить путь Траллу и дать ему возможность вступить в бой с торговым принцем. План состоит в том, чтобы ты $gпомог:помогла; в этой атаке, но для начала нужно сделать так, чтобы наемники Южных морей Галливикса не пришли ему на помощь.$B$BСпустись в Ямы рабов и сделай все необходимое, чтобы наемники оттуда не выбрались!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 6 наемников Южных морей.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Чогу к Ямам рабов на Затерянных островах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25232,'Пылающий Клинок','Меня отправили расследовать деятельность агентов Пылающего Клинка здесь, в Дуротаре. К северо-востоку отсюда находится пещера, где проходит обучение новых членов организации. Мне интересно, чему именно там обучают неофитов.$b$bРассказываю тебе это лишь потому, что ты, похоже, ищешь работу. Если хочешь получить несколько звонких монет, обыщи пещеру и принесли мне свитки их заклинаний.$b$bПещера скрыта от глаз посторонних. Отправляйся отсюда на восток и следуй восточному обрыву каньона, пока не найдешь ее.','Отберите у последователей Пылающего Клинка 6 свитков заклинаний Пылающего Клинка в пещере Пыльного Ветра.','Вернитесь к Оргнилу Душегрызу на Колючий Холм в Дуротар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пылающий Клинок',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Меня отправили расследовать деятельность агентов Пылающего Клинка здесь, в Дуротаре. К северо-востоку отсюда находится пещера, где проходит обучение новых членов организации. Мне интересно, чему именно там обучают неофитов.$b$bРассказываю тебе это лишь потому, что ты, похоже, ищешь работу. Если хочешь получить несколько звонких монет, обыщи пещеру и принесли мне свитки их заклинаний.$b$bПещера скрыта от глаз посторонних. Отправляйся отсюда на восток и следуй восточному обрыву каньона, пока не найдешь ее.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отберите у последователей Пылающего Клинка 6 свитков заклинаний Пылающего Клинка в пещере Пыльного Ветра.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Оргнилу Душегрызу на Колючий Холм в Дуротар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25233,'Можно грабить караваны','Сумеречные снабженцы поклялись собственной кровью, что они доставят припасы на фронт, и пообещали отдавать по килограмму собственной плоти за каждый килограмм утерянного провианта. Они скорее умрут, чем отступят.$B$BВпрочем, меня устроит любой из этих двух вариантов.','Убейте 4 сумеречных снабженцев на Волчьей тропе, что на горе Хиджал.','Отлично! Паника распространяется быстро, и скоро она охватит их командование.','Вернитесь к Джади Фаларин на Волчью тропу на Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Можно грабить караваны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сумеречные снабженцы поклялись собственной кровью, что они доставят припасы на фронт, и пообещали отдавать по килограмму собственной плоти за каждый килограмм утерянного провианта. Они скорее умрут, чем отступят.$B$BВпрочем, меня устроит любой из этих двух вариантов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 4 сумеречных снабженцев на Волчьей тропе, что на горе Хиджал.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! Паника распространяется быстро, и скоро она охватит их командование.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джади Фаларин на Волчью тропу на Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25234,'Тыловые припасы','Культ Сумеречного Молота использует пленников в качестве вьючного скота, заставляя несчастных таскать на себе припасы для армии. Мне нужны эти припасы, а если попутно тебе удастся освободить от хватки культа несколько невинных душ, – тем лучше.$B$BУбей погонщиков рабов, и пленники с радостью сбросят с себя оковы.$B$BОбыщи брошенные ими ящики на предмет ценностей и уничтожь все, что не сможешь унести.','Соберите 36 ящиков с припасами Сумеречного Молота, оставленных сумеречными рабами.','Принесите припасы Сумеречного Молота Джади Фаларин на Волчью тропу на Хиджале.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тыловые припасы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Культ Сумеречного Молота использует пленников в качестве вьючного скота, заставляя несчастных таскать на себе припасы для армии. Мне нужны эти припасы, а если попутно тебе удастся освободить от хватки культа несколько невинных душ, – тем лучше.$B$BУбей погонщиков рабов, и пленники с радостью сбросят с себя оковы.$B$BОбыщи брошенные ими ящики на предмет ценностей и уничтожь все, что не сможешь унести.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 36 ящиков с припасами Сумеречного Молота, оставленных сумеречными рабами.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите припасы Сумеречного Молота Джади Фаларин на Волчью тропу на Хиджале.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25235,'Лощина Вул\'Гол','Убейте любых 15 огров из клана Дробящего Кулака.','Вижу, ты прикончил нескольких огров. Неплохая работа.$B$BВот твоя награда, от имени Ночного Дозора.','Вернитесь к дозорному Додсу в Сумеречный лес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лощина Вул\'Гол',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте любых 15 огров из клана Дробящего Кулака.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вижу, ты прикончил нескольких огров. Неплохая работа.$B$BВот твоя награда, от имени Ночного Дозора.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к дозорному Додсу в Сумеречный лес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25237,'Каменные слезы','Как ты $gсам видел:сама видела;, Исондра сказала, что слезы земли могут запечатать портал, из которого распространяется эта зараза.$B$BНесколько недель назад, на поляне к западу отсюда, я видел горных великанов, и они совершенно обезумели. Их снедала ярость, они рыдали, а слезы их падали на камни, будто сияющие кристаллы.$B$BХотя великаны больше и не плачут, но, должно быть, Исондра говорила именно о тех каменных слезах: это источник природной чистоты. Нужно собрать их.','Соберите 7 каменных слез.','Вернитесь к Кону Руническому Тотему в лагерь Атайа, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Каменные слезы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как ты $gсам видел:сама видела;, Исондра сказала, что слезы земли могут запечатать портал, из которого распространяется эта зараза.$B$BНесколько недель назад, на поляне к западу отсюда, я видел горных великанов, и они совершенно обезумели. Их снедала ярость, они рыдали, а слезы их падали на камни, будто сияющие кристаллы.$B$BХотя великаны больше и не плачут, но, должно быть, Исондра говорила именно о тех каменных слезах: это источник природной чистоты. Нужно собрать их.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 7 каменных слез.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кону Руническому Тотему в лагерь Атайа, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (25238,'Strength Ring Flag') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Strength Ring Flag',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25239,'Путь силы','Ты по-прежнему отважно сражаешься на нашей стороне, $n. Прими это кольцо не как дар, но как оружие в войне против Плети.','Ты желаешь и дальше идти путем силы?','Вернитесь к Орму Кающемуся.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путь силы',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты по-прежнему отважно сражаешься на нашей стороне, $n. Прими это кольцо не как дар, но как оружие в войне против Плети.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты желаешь и дальше идти путем силы?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Орму Кающемуся.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25240,'Путь силы','Ты по-прежнему отважно сражаешься на нашей стороне, $n. Прими это кольцо не как дар, но как оружие в войне против Плети.','Ты желаешь и дальше идти путем силы?','Вернитесь к Орму Кающемуся.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путь силы',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты по-прежнему отважно сражаешься на нашей стороне, $n. Прими это кольцо не как дар, но как оружие в войне против Плети.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты желаешь и дальше идти путем силы?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Орму Кающемуся.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25241,'Оскверненная земля','Скальные великаны Фераласа – это продолжение самой земли, $n. Когда природе ничего не угрожает, они ведут себя как добрые защитники и мирные стражи.$B$BНо теперь лес заражен, и они вместе с ним.$B$BОднако если они заражены, то скоро набросятся на фауну и своих же собратьев, неся великие разрушения. Нужно уничтожить всех зараженных великанов, какие тебе только встретятся.','Убейте 7 зараженных скальных великанов.','Вернитесь к Кону Руническому Тотему в лагерь Атайа в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оскверненная земля',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Скальные великаны Фераласа – это продолжение самой земли, $n. Когда природе ничего не угрожает, они ведут себя как добрые защитники и мирные стражи.$B$BНо теперь лес заражен, и они вместе с ним.$B$BОднако если они заражены, то скоро набросятся на фауну и своих же собратьев, неся великие разрушения. Нужно уничтожить всех зараженных великанов, какие тебе только встретятся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 7 зараженных скальных великанов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кону Руническому Тотему в лагерь Атайа в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25242,'Путь силы','Ты настоящий герой, сражающийся за правое дело, $n. Мало кто может сравниться с тобой на поле боя.$B$BВраги произносят твое имя испуганным шепотом, ибо знают, что с тобой нельзя не считаться.$B$BПрими этот скромный дар в благодарность за свершенные подвиги.','Ты желаешь и дальше идти путем силы?','Вернитесь к Орму Кающемуся.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путь силы',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты настоящий герой, сражающийся за правое дело, $n. Мало кто может сравниться с тобой на поле боя.$B$BВраги произносят твое имя испуганным шепотом, ибо знают, что с тобой нельзя не считаться.$B$BПрими этот скромный дар в благодарность за свершенные подвиги.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты желаешь и дальше идти путем силы?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Орму Кающемуся.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (25243,'Любит – не любит','Ах, солнышко! Ни в жисть не догадаешься, кто сейчас в Ямах рабов на севере.$B$B<Хамми смотрит на вас, печально покачивая головой.>$B$BТам Конфетка... и она работает на торгового принца. Она избавилась от тебя, как от дурной привычки... и теперь играет за другую команду. Только на самом деле все еще хуже. С тех пор, как ты "$gразобрался:разобралась;" с Чипом, она закрутила роман с самим торговым принцем!$B$BНе знаю, как ты, но если бы она была МОЕЙ бывшей, я бы... я бы вырвала прямо из груди ее изменчивое сердце!','Вырвите изменчивое сердце из груди Конфетки.','Я уверена, что это заслуженно, Хиловата. Она не должна была предавать тебя.$B$BМеня просто в дрожь бросает от одной мысли, что она ведь, наверное, целовалась с этим чудовищем торговым принцем!','Ну, и как ты собираешься выходить из этой ситуации, лапуля?','Вернитесь к Хамми Кофельнагель к Ямам рабов на Затерянных островах.','Вырви из ее груди изменчивое сердце!','Конфетка') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Любит – не любит',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ах, солнышко! Ни в жисть не догадаешься, кто сейчас в Ямах рабов на севере.$B$B<Хамми смотрит на вас, печально покачивая головой.>$B$BТам Конфетка... и она работает на торгового принца. Она избавилась от тебя, как от дурной привычки... и теперь играет за другую команду. Только на самом деле все еще хуже. С тех пор, как ты "$gразобрался:разобралась;" с Чипом, она закрутила роман с самим торговым принцем!$B$BНе знаю, как ты, но если бы она была МОЕЙ бывшей, я бы... я бы вырвала прямо из груди ее изменчивое сердце!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вырвите изменчивое сердце из груди Конфетки.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я уверена, что это заслуженно, Хиловата. Она не должна была предавать тебя.$B$BМеня просто в дрожь бросает от одной мысли, что она ведь, наверное, целовалась с этим чудовищем торговым принцем!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, и как ты собираешься выходить из этой ситуации, лапуля?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хамми Кофельнагель к Ямам рабов на Затерянных островах.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Вырви из ее груди изменчивое сердце!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Конфетка',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (25244,'И что за имя такое – Конфетка?!','Разве можно верить этой Конфетке! Знаешь, до того как ты "разобралась" с Чипом, она ведь с ним встречалась! А теперь ее кавалер – сам торговый принц!$B$BЯ вот не могу смириться с тем, что она гуляла с твоим бывшим. Может, тебе отправиться в Ямы рабов и... "позаботиться о ней" – раз и навсегда?','Убейте Конфетку.','Так ей и надо – за то, что увела твоего парня.','Вернитесь к Хамми Кофельнагель к Ямам рабов на Затерянных островах.','Пришло время избавиться от мусора!','Конфетка') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','И что за имя такое – Конфетка?!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Разве можно верить этой Конфетке! Знаешь, до того как ты "разобралась" с Чипом, она ведь с ним встречалась! А теперь ее кавалер – сам торговый принц!$B$BЯ вот не могу смириться с тем, что она гуляла с твоим бывшим. Может, тебе отправиться в Ямы рабов и... "позаботиться о ней" – раз и навсегда?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Конфетку.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так ей и надо – за то, что увела твоего парня.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хамми Кофельнагель к Ямам рабов на Затерянных островах.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Пришло время избавиться от мусора!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Конфетка',`questgivertargetname_loc8`);
