INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25250,'Запечатанный сон','Готово. Вот, возьми, $n: это эссенция самой природы, благословленная волей Исондры.$B$BК востоку отсюда, на другой стороне ручья, находится место под названием Сонные Ветви. Там стоит Великое Древо, самое высокое в Фераласе, дитя самого Древа Жизни. В его стволе находится портал в сердце Изумрудного Сна, и тебе нужно будет этот портал запечатать.$B$BПортал охраняется, но ты $gне должен:не должна; отступать. Да хранит тебя Мать-Земля.','При помощи Слезы Исондры закройте портал в Сонных Ветвях.','Заражение остановлено! Теперь лес может начать излечивать себя.$B$BДа благословит тебя Мать-Земля, куда бы ты ни пошел.','Вернитесь к Кону Руническому Тотему в лагерь Атайа в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Запечатанный сон',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Готово. Вот, возьми, $n: это эссенция самой природы, благословленная волей Исондры.$B$BК востоку отсюда, на другой стороне ручья, находится место под названием Сонные Ветви. Там стоит Великое Древо, самое высокое в Фераласе, дитя самого Древа Жизни. В его стволе находится портал в сердце Изумрудного Сна, и тебе нужно будет этот портал запечатать.$B$BПортал охраняется, но ты $gне должен:не должна; отступать. Да хранит тебя Мать-Земля.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','При помощи Слезы Исондры закройте портал в Сонных Ветвях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Заражение остановлено! Теперь лес может начать излечивать себя.$B$BДа благословит тебя Мать-Земля, куда бы ты ни пошел.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кону Руническому Тотему в лагерь Атайа в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (25251,'Решающее противостояние','$n, вот и все! Тралл сейчас на верфи Галливикса сражается с торговым принцем!$B$BДавай, запрыгивай в свою идеальную футбомбную униформу и живо езжай туда!','Забирайтесь в идеальную футбомбную униформу, а потом разберитесь с торговым принцем Галливиксом.','Ура, у тебя все получилось!$B$BМы спасены, Хиловата!','Вернитесь к Хамми Кофельнагель к Ямам рабов на Затерянных островах.','Воспользуйтесь лучшей футбомбной униформой, чтобы спасти Тралла и разобраться с торговым принцем!','Торговый принц Галливикс') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Решающее противостояние',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, вот и все! Тралл сейчас на верфи Галливикса сражается с торговым принцем!$B$BДавай, запрыгивай в свою идеальную футбомбную униформу и живо езжай туда!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Забирайтесь в идеальную футбомбную униформу, а потом разберитесь с торговым принцем Галливиксом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ура, у тебя все получилось!$B$BМы спасены, Хиловата!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хамми Кофельнагель к Ямам рабов на Затерянных островах.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Воспользуйтесь лучшей футбомбной униформой, чтобы спасти Тралла и разобраться с торговым принцем!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Торговый принц Галливикс',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25252,'Правители Забытого города','Убейте 6 головорезов и 6 огров-магов из клана Гордок.','Отлично! Теперь даже до этих дураков дойдет: вредить Орде себе дороже.','Вернитесь к Орхан Огрский Клинок в крепость Каменного Молота.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Правители Забытого города',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 6 головорезов и 6 огров-магов из клана Гордок.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! Теперь даже до этих дураков дойдет: вредить Орде себе дороже.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Орхан Огрский Клинок в крепость Каменного Молота.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25253,'Пророчества о конце света','Вестники рока довольно часто появляются на улицах Штормграда, но эта последняя шайка меня беспокоит. Они произвели настоящий переполох в Старом городе, и их банда отличается четкой организацией.$B$BЯ было подумал слегка сократить их численность, но боюсь, что это только заставит их перейти на нелегальное положение. Надо узнать как можно больше об этой шайке! Пожалуйста, отправляйся в Старый город, послушай, что они рассказывают и к чему призывают, собери какие-нибудь бумаги, которые могли бы пролить свет на их деятельность.','Выслушайте речь вестника рока в Старом городе и найдите копии листовок "Стенания души в пламени первородного огня", "Конец всего сущего – правда и домыслы" и "Мир обречен, но дух мой чист и безмятежен...".','Вернитесь к капитану Антону в крепость Штормграда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пророчества о конце света',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вестники рока довольно часто появляются на улицах Штормграда, но эта последняя шайка меня беспокоит. Они произвели настоящий переполох в Старом городе, и их банда отличается четкой организацией.$B$BЯ было подумал слегка сократить их численность, но боюсь, что это только заставит их перейти на нелегальное положение. Надо узнать как можно больше об этой шайке! Пожалуйста, отправляйся в Старый город, послушай, что они рассказывают и к чему призывают, собери какие-нибудь бумаги, которые могли бы пролить свет на их деятельность.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выслушайте речь вестника рока в Старом городе и найдите копии листовок "Стенания души в пламени первородного огня", "Конец всего сущего – правда и домыслы" и "Мир обречен, но дух мой чист и безмятежен...".',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Антону в крепость Штормграда.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25254,'Знаки времен','Необходимо как-то снизить интерес к этой секте вестников рока, но я опасаюсь предпринимать что-то прежде, чем мы узнаем, кто стоит за ней.$b$bМои люди отметили наиболее оживленные места в Оргриммаре. Возьми эти плакаты и развесь их там, где увидишь отметки. Самых ярых поклонников они не остановят, но все же это первый шаг к изобличению секты. У Орды хватает неприятелей и без этих лгунов, упрямо распространяющих свою ересь.','Расставьте 5 предупредительных плакатов на Аллее Силы, в Волоке или на Алее Чести.','Вернитесь к кровавому стражу Тореку на Аллею Силы Оргриммара.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Знаки времен',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Необходимо как-то снизить интерес к этой секте вестников рока, но я опасаюсь предпринимать что-то прежде, чем мы узнаем, кто стоит за ней.$b$bМои люди отметили наиболее оживленные места в Оргриммаре. Возьми эти плакаты и развесь их там, где увидишь отметки. Самых ярых поклонников они не остановят, но все же это первый шаг к изобличению секты. У Орды хватает неприятелей и без этих лгунов, упрямо распространяющих свою ересь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Расставьте 5 предупредительных плакатов на Аллее Силы, в Волоке или на Алее Чести.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к кровавому стражу Тореку на Аллею Силы Оргриммара.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25255,'Охота на охотников','Сумеречный Молот наконец-то открыл свое истинное лицо. Его армии поднимаются в горы, уничтожая все на своем пути, как саранча.$B$BВ тех участках леса, которые еще не преданы ими огню, они уничтожают все живое, просто чтобы прокормиться.$B$BНеобходимо остановить их охотников, вышедших на Волчью тропу. Во-первых, мы должны спасти оставшихся в живых животных, а во-вторых, с пустым брюхом много не навоюешь.','Убейте 6 охотников Сумеречного Молота на Волчьей тропе, что на горе Хиджал.','Вернитесь к Умле Белый Рог на Волчью Тропу на Хиджале.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота на охотников',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сумеречный Молот наконец-то открыл свое истинное лицо. Его армии поднимаются в горы, уничтожая все на своем пути, как саранча.$B$BВ тех участках леса, которые еще не преданы ими огню, они уничтожают все живое, просто чтобы прокормиться.$B$BНеобходимо остановить их охотников, вышедших на Волчью тропу. Во-первых, мы должны спасти оставшихся в живых животных, а во-вторых, с пустым брюхом много не навоюешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 6 охотников Сумеречного Молота на Волчьей тропе, что на горе Хиджал.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Умле Белый Рог на Волчью Тропу на Хиджале.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (25256,'Послан за подмогой','Ты, |3-6($r), остановись-ка на минутку.$b$bМой шеф Шипозуб отправил меня сюда за помощью и припасами. Ты вроде бы не $gпохож:похожа; на наемника, но может быть, захочешь ему помочь? Сможешь найти его на юго-востоке, рядом с разбитой телегой. Ах да, и скажи ему, что это я прислал тебя... Пусть не сомневается, что я тут не прохлаждаюсь, а работаю в поте лица!','Свяжитесь с Шипозубом на взморье Мертвого Глаза в Дуротаре.','Тебя послал Век\'наг? И не сказал, что мне нужны колеса для повозок, гвозди и провизия? Вот балда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Послан за подмогой',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты, |3-6($r), остановись-ка на минутку.$b$bМой шеф Шипозуб отправил меня сюда за помощью и припасами. Ты вроде бы не $gпохож:похожа; на наемника, но может быть, захочешь ему помочь? Сможешь найти его на юго-востоке, рядом с разбитой телегой. Ах да, и скажи ему, что это я прислал тебя... Пусть не сомневается, что я тут не прохлаждаюсь, а работаю в поте лица!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Свяжитесь с Шипозубом на взморье Мертвого Глаза в Дуротаре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебя послал Век\'наг? И не сказал, что мне нужны колеса для повозок, гвозди и провизия? Вот балда.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25257,'Гислания','У меня есть пара гладиаторов, которые участвуют в состязаниях по всему миру. Вот, оглянись – большинство из них содержатся здесь в цепях... Нам повезло справиться с ними после того, как повозка разбилась.$b$bГислания, вот эта нага... Проиграла последние три схватки. С ней, пожалуй, стоит поработать – или просто хорошенько вздуть ее. Иди, вызови ее на бой. Уверен, даже ТЫ сильнее, чем она.','Победите в бою Гисланию.','Вернитесь к Шипозубу на взморье Мертвого Глаза, что в Дуротаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гислания',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У меня есть пара гладиаторов, которые участвуют в состязаниях по всему миру. Вот, оглянись – большинство из них содержатся здесь в цепях... Нам повезло справиться с ними после того, как повозка разбилась.$b$bГислания, вот эта нага... Проиграла последние три схватки. С ней, пожалуй, стоит поработать – или просто хорошенько вздуть ее. Иди, вызови ее на бой. Уверен, даже ТЫ сильнее, чем она.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите в бою Гисланию.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Шипозубу на взморье Мертвого Глаза, что в Дуротаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25258,'Грисвольд Ханнистон','Победите в бою Грисвольда Ханнистона.','Вернитесь к Шипозубу на взморье Мертвого Глаза, что в Дуротаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Грисвольд Ханнистон',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите в бою Грисвольда Ханнистона.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Шипозубу на взморье Мертвого Глаза, что в Дуротаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25259,'Гаур Ледяной Рог','Победите в бою Гаура Ледяного Рога.','Идет, вот деньги... Но ты бы лучше не попадался больше мне на глаза – я ведь могу изменить своему принципу не брать рабов из Орды.','Вернитесь к Шипозубу на взморье Мертвого Глаза, что в Дуротаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гаур Ледяной Рог',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите в бою Гаура Ледяного Рога.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Идет, вот деньги... Но ты бы лучше не попадался больше мне на глаза – я ведь могу изменить своему принципу не брать рабов из Орды.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Шипозубу на взморье Мертвого Глаза, что в Дуротаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (25260,'Сфера Пшикса','Хлынувшая на юго-запад вода смыла с лица земли один из тех лагерей Пылающего Клинка, что все еще оскверняют землю Дуротара своим присутствием. Тамошних сектантов возглавлял гоблин по имени Пшикс Чернолап, и, поверь мне, без него мир стал гораздо лучше.$b$bЧернолап владел некоей сферой, которая стала необходима Орде. Кто знает, зачем... Пусть в этом разбираются чернокнижники. Мне нужна эта сфера – вот все, что тебе нужно знать.','Отправляйтесь на Громовой хребет и отберите сферу Пшикса у Пшикса Чернолапа.','Вляпываешься во все неприятности по пути?','Вернитесь к Гору "Головорезу" на Насыпь Драноша в Дуротар.','Думаю, когда ты до него доберешься, он еще больше размокнет от воды.','Пшикс Чернолап') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сфера Пшикса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хлынувшая на юго-запад вода смыла с лица земли один из тех лагерей Пылающего Клинка, что все еще оскверняют землю Дуротара своим присутствием. Тамошних сектантов возглавлял гоблин по имени Пшикс Чернолап, и, поверь мне, без него мир стал гораздо лучше.$b$bЧернолап владел некоей сферой, которая стала необходима Орде. Кто знает, зачем... Пусть в этом разбираются чернокнижники. Мне нужна эта сфера – вот все, что тебе нужно знать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь на Громовой хребет и отберите сферу Пшикса у Пшикса Чернолапа.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вляпываешься во все неприятности по пути?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гору "Головорезу" на Насыпь Драноша в Дуротар.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Думаю, когда ты до него доберешься, он еще больше размокнет от воды.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Пшикс Чернолап',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25261,'Маргоз','Один из наших лучших шаманов, Маргоз, многое знает о Пылающем Клинке. Как-то он рассказывал о пещере, которая называется Скала Черепа, в горах у самого Оргриммара. Там окопалась большая шайка сектантов из клана Пылающего Клинка.$b$bПрежде чем отправиться к Скале Черепа, поговори с Маргозом. Он мудр, и к его советам стоит прислушиваться.$b$bТы найдешь его на северо-востоке, между побережьем и Сухой лощиной.$b$bСледуй его советам, $n, но, что бы он ни сказал, я прошу тебя – уничтожь этих сектантов!','Поговорите с Маргозом.','Вернитесь к Маргозу в Дуротар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Маргоз',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Один из наших лучших шаманов, Маргоз, многое знает о Пылающем Клинке. Как-то он рассказывал о пещере, которая называется Скала Черепа, в горах у самого Оргриммара. Там окопалась большая шайка сектантов из клана Пылающего Клинка.$b$bПрежде чем отправиться к Скале Черепа, поговори с Маргозом. Он мудр, и к его советам стоит прислушиваться.$b$bТы найдешь его на северо-востоке, между побережьем и Сухой лощиной.$b$bСледуй его советам, $n, но, что бы он ни сказал, я прошу тебя – уничтожь этих сектантов!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Маргозом.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Маргозу в Дуротар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25262,'Скала Черепа','$n! Пылающий Клинок захватил пещеру к востоку от Оргриммара, известную как Скала Черепа. Сектанты совершают там свои гнусные обряды и сжигают собственную плоть обжигающими ошейниками.$b$bЯ подозреваю, что, нося эти ошейники, фанатики вступают в резонанс с демоническими силами. Но чтобы в этом убедиться, мне необходимо изучить несколько таких ошейников.$b$bСтупай в Скалу Черепа и отбери у фанатиков, которых там найдешь, их ошейники. Принеси их мне, и я раскрою их тайну!','Отберите у фанатиков из Скалы Черепа 6 обжигающих ошейников.','Вернитесь к Маргозу в Дуротар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Скала Черепа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n! Пылающий Клинок захватил пещеру к востоку от Оргриммара, известную как Скала Черепа. Сектанты совершают там свои гнусные обряды и сжигают собственную плоть обжигающими ошейниками.$b$bЯ подозреваю, что, нося эти ошейники, фанатики вступают в резонанс с демоническими силами. Но чтобы в этом убедиться, мне необходимо изучить несколько таких ошейников.$b$bСтупай в Скалу Черепа и отбери у фанатиков, которых там найдешь, их ошейники. Принеси их мне, и я раскрою их тайну!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отберите у фанатиков из Скалы Черепа 6 обжигающих ошейников.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Маргозу в Дуротар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (25263,'О! Откуда у тебя это? Тебя прислал ко мне славный Маргоз из Колючего Холма, верно?$B$BНу-ка, дай взглянуть...') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О! Откуда у тебя это? Тебя прислал ко мне славный Маргоз из Колючего Холма, верно?$B$BНу-ка, дай взглянуть...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (25264,'Ак\'Зелот','Со времен последней великой войны, когда Пылающий Легион потерпел поражение, я ищу источники демонической порчи, что воздействуют на общество орков. И принесенный тобой ошейник подтверждает мои опасения!$b$bОн принадлежит Пылающему Клинку.$b$bВпрочем, твое участие в этом деле подходит к концу, $n. Отправляйся на форпост на границе Степей, к западу, и поговори с моим помощником, Ак\'Зелотом. Передай ему эту информацию.','Не новость для меня. Я, несомненно, ценю твои старания, но Пылающий Клинок подождет. Необходимо сделать кое-что гораздо более важное.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ак\'Зелот',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Со времен последней великой войны, когда Пылающий Легион потерпел поражение, я ищу источники демонической порчи, что воздействуют на общество орков. И принесенный тобой ошейник подтверждает мои опасения!$b$bОн принадлежит Пылающему Клинку.$b$bВпрочем, твое участие в этом деле подходит к концу, $n. Отправляйся на форпост на границе Степей, к западу, и поговори с моим помощником, Ак\'Зелотом. Передай ему эту информацию.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Не новость для меня. Я, несомненно, ценю твои старания, но Пылающий Клинок подождет. Необходимо сделать кое-что гораздо более важное.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (25265,'Победа!','Ты для нас столько $gсделал:сделала;... Мы будем вечно тебе благодарны. А теперь мы все вместе уберемся с этого острова, пока он не взлетел на воздух!$B$BНо сначала Тралл хочет с тобой побеседовать, $n. Я тебя вмиг переправлю к нему на ракете.$B$BУвидимся на корабле!','Поговорите с Траллом на верфи Галливикса на Затерянных островах.','Лок\'тар! Победа, Хиловата!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Победа!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты для нас столько $gсделал:сделала;... Мы будем вечно тебе благодарны. А теперь мы все вместе уберемся с этого острова, пока он не взлетел на воздух!$B$BНо сначала Тралл хочет с тобой побеседовать, $n. Я тебя вмиг переправлю к нему на ракете.$B$BУвидимся на корабле!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Траллом на верфи Галливикса на Затерянных островах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Лок\'тар! Победа, Хиловата!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (25266,'Посланник вождя','<Орк продолжает говорить вполголоса.>$B$BЯ знаю, кто тебя прислал. Он просил тебя передать мне что-нибудь?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Посланник вождя',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Орк продолжает говорить вполголоса.>$B$BЯ знаю, кто тебя прислал. Он просил тебя передать мне что-нибудь?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (25267,'Это от Тралла?$B$B<Вождь вздрагивает и отступает назад.>$B$BЯ очень хорошо понимаю, о чем тут говорится, гоблин. <Гаррош указывает на Гоббера.>$B$BВот этого вонючку мы поймали в городе. Кажется, он узнает тебя.$B$BЯ уже определил многих ваших соотечественников на работы в Азшаре. Возьми и его с собой, когда будешь уходить.$B$BОтныне и впредь ты и весь ваш картель Трюмных Вод будете служить Орде!') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это от Тралла?$B$B<Вождь вздрагивает и отступает назад.>$B$BЯ очень хорошо понимаю, о чем тут говорится, гоблин. <Гаррош указывает на Гоббера.>$B$BВот этого вонючку мы поймали в городе. Кажется, он узнает тебя.$B$BЯ уже определил многих ваших соотечественников на работы в Азшаре. Возьми и его с собой, когда будешь уходить.$B$BОтныне и впредь ты и весь ваш картель Трюмных Вод будете служить Орде!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25268,'Глас Голдринна','К юго-западу отсюда находится Святилище Голдринна. Оно воздвигнуто в честь древнего духа волка и его деяний во время Войны древних.$B$BНаших новых союзников-воргенов привлекла история бога-волка – что вполне естественно – и они приняли участие в очищении святилища.$B$BОт Яна Дюрана, находящегося там, уже давно ничего не слышно. Может быть, слетаешь туда и поищешь его? У меня нехорошие предчувствия, что в святилище что-то не так...','Найдите Дюрана у Святилища Голдринна на горе Хиджал.','Найдите Дюрана у Святилища Голдринна на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Глас Голдринна',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','К юго-западу отсюда находится Святилище Голдринна. Оно воздвигнуто в честь древнего духа волка и его деяний во время Войны древних.$B$BНаших новых союзников-воргенов привлекла история бога-волка – что вполне естественно – и они приняли участие в очищении святилища.$B$BОт Яна Дюрана, находящегося там, уже давно ничего не слышно. Может быть, слетаешь туда и поищешь его? У меня нехорошие предчувствия, что в святилище что-то не так...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Дюрана у Святилища Голдринна на горе Хиджал.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Найдите Дюрана у Святилища Голдринна на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25269,'Глас Ло\'гоша','Доводилось ли тебе слышать о божественном волке Ло\'гоше? О том, кого Альянс называет Голдринном?$B$BЯ не буду объяснять тебе, насколько этот волк важен для Орды, – его сила во времена невзгод вдохновляла всех нас.$B$BК юго-западу отсюда в долине находится святилище Голдринна. Мой друг Такрик Гневный Вой, когда я видела его в последний раз, отправился туда, чтобы вернуть этому святилищу жизнь. Я опасаюсь худшего.$B$BПрошу тебя, найди Такрика и убедись, что со святилищем все в порядке!','Найдите Такрика Гневного Воя возле святилища Голдринна на горе Хиджал.','Найдите Такрика Гневного Воя возле святилища Голдринна на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Глас Ло\'гоша',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Доводилось ли тебе слышать о божественном волке Ло\'гоше? О том, кого Альянс называет Голдринном?$B$BЯ не буду объяснять тебе, насколько этот волк важен для Орды, – его сила во времена невзгод вдохновляла всех нас.$B$BК юго-западу отсюда в долине находится святилище Голдринна. Мой друг Такрик Гневный Вой, когда я видела его в последний раз, отправился туда, чтобы вернуть этому святилищу жизнь. Я опасаюсь худшего.$B$BПрошу тебя, найди Такрика и убедись, что со святилищем все в порядке!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Такрика Гневного Воя возле святилища Голдринна на горе Хиджал.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Найдите Такрика Гневного Воя возле святилища Голдринна на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25270,'Безумный вой','Святилище захвачено, $n. Теперь нам как никогда нужна сила Ло\'гоша.$B$BЭти выродки, эти блохастые волколюди, заполонившие святилище, позорят память бога-волка. Они пришли вместе с Сумеречным Молотом, завывая гимны своей еретической религии. Они оскверняют память Ло\'гоша, причисляя его к собственному еретическому пантеону.$B$BУбей их! Убей их и принеси мне предметы их культа, какие-то отравленные благовония. Я хочу разобраться, что они намереваются сделать с нашим святилищем...','Добудьте 6 отравленных благовоний.','<Такрик изучает благовония.>$B$BНемыслимо. Это вещество похоже на те благовония, что мы используем для общения с духами… но… оно гораздо хуже.','Эти животные когда-то были людьми, но под влиянием Сумеречного Молота они постепенно утратили всякий человеческий облик. Уничтожай их без колебаний.','Вернитесь к Такрику Гневному Вою в Святилище Голдринна на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Безумный вой',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Святилище захвачено, $n. Теперь нам как никогда нужна сила Ло\'гоша.$B$BЭти выродки, эти блохастые волколюди, заполонившие святилище, позорят память бога-волка. Они пришли вместе с Сумеречным Молотом, завывая гимны своей еретической религии. Они оскверняют память Ло\'гоша, причисляя его к собственному еретическому пантеону.$B$BУбей их! Убей их и принеси мне предметы их культа, какие-то отравленные благовония. Я хочу разобраться, что они намереваются сделать с нашим святилищем...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 6 отравленных благовоний.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Такрик изучает благовония.>$B$BНемыслимо. Это вещество похоже на те благовония, что мы используем для общения с духами… но… оно гораздо хуже.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Эти животные когда-то были людьми, но под влиянием Сумеречного Молота они постепенно утратили всякий человеческий облик. Уничтожай их без колебаний.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Такрику Гневному Вою в Святилище Голдринна на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25271,'Свирепость Голдринна','Звери, которых ты видишь, больше не мои братья из Гилнеаса. Их поразило какое-то безумие, и они захватили святилище.$B$BОни пришли тогда, когда и культ Сумеречного Молота появился на Хиджале, и выкрикивают имя ложного божества – кощунственной насмешки над нашим возлюбленным Голдринном. Забудь обо мне; твой долг – уничтожить этих вандалов, чтобы прекратить осквернение святилища.$B$BА когда расправишься с ними, поищи на телах благовония, которые они носят с собой, и принеси мне образцы.','Добудьте 6 экземпляров отравленных благовоний.','<Ян внимательно изучает благовония.>$B$BКак я и предполагал. Это вещество пропитано духом Сумеречного Молота. А вот и имя – "Ликантот". Думаю, эти благовония используются в ритуале призыва…','Воргены вроде меня превозносят Голдринна, его силу и мудрость. Но эти вандалы... они поклоняются совсем другому аспекту бога-волка.','Вернитесь к Яну Дюрану в Святилище Голдринна на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Свирепость Голдринна',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Звери, которых ты видишь, больше не мои братья из Гилнеаса. Их поразило какое-то безумие, и они захватили святилище.$B$BОни пришли тогда, когда и культ Сумеречного Молота появился на Хиджале, и выкрикивают имя ложного божества – кощунственной насмешки над нашим возлюбленным Голдринном. Забудь обо мне; твой долг – уничтожить этих вандалов, чтобы прекратить осквернение святилища.$B$BА когда расправишься с ними, поищи на телах благовония, которые они носят с собой, и принеси мне образцы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 6 экземпляров отравленных благовоний.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Ян внимательно изучает благовония.>$B$BКак я и предполагал. Это вещество пропитано духом Сумеречного Молота. А вот и имя – "Ликантот". Думаю, эти благовония используются в ритуале призыва…',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Воргены вроде меня превозносят Голдринна, его силу и мудрость. Но эти вандалы... они поклоняются совсем другому аспекту бога-волка.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Яну Дюрану в Святилище Голдринна на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (25273,'Ликантот Осквернитель','Кажется, я понимаю, что происходит. В Сумеречном Молоте боятся, что древние хранители могут вступить в противостояние с ними. Они сделают все, чтобы помешать возвращению Голдринна.$B$BЭтот "Ликантот" – извращенная версия нашего возлюбленного бога, призванная Сумеречным Молотом, чтобы заменить его.$B$BХа! У него нет и тени могущества Голдринна! $n, убей этого зверя и сожги его в Утробе Ликантота к востоку отсюда. Убей зверя и освободи Голдринна!','С помощью фимиама Ликантота вызовите его в Утробе Ликантота на Хиджале и убейте.','Поговорите с духом Голдринна перед алтарем Ликантота в Утробе Ликантота на горе Хиджал.','Используйте фимиам в Утробе Ликантота, чтобы призвать чудовище.','Ликантот Осквернитель') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ликантот Осквернитель',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кажется, я понимаю, что происходит. В Сумеречном Молоте боятся, что древние хранители могут вступить в противостояние с ними. Они сделают все, чтобы помешать возвращению Голдринна.$B$BЭтот "Ликантот" – извращенная версия нашего возлюбленного бога, призванная Сумеречным Молотом, чтобы заменить его.$B$BХа! У него нет и тени могущества Голдринна! $n, убей этого зверя и сожги его в Утробе Ликантота к востоку отсюда. Убей зверя и освободи Голдринна!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','С помощью фимиама Ликантота вызовите его в Утробе Ликантота на Хиджале и убейте.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с духом Голдринна перед алтарем Ликантота в Утробе Ликантота на горе Хиджал.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Используйте фимиам в Утробе Ликантота, чтобы призвать чудовище.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Ликантот Осквернитель',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25274,'Подпись кровью','Наконец-то ты тут, $n. И очень вовремя.$B$BВесть о появлении Рагнароса многих толкнула в объятия культа Сумеречного Молота.$B$BЕсли хочешь проникнуть в стан культа, то время пришло. Нам понадобится вербовочный лист, который кровью подписал один из членов Сумеречного Молота. Замани одного из рекрутов подальше от основной группы и ударь его дубинкой.$B$BЕсли тебе повезет, то удастся украсть его вербовочный лист. Принеси мне эту бумажку, и мы ее немножко подправим.','Заманите сумеречного рекрута подальше от остальных и отнимите у него вербовочный лист Сумеречного Молота.','Прекрасно. Я постараюсь подделать эти документы.','Вернитесь к повелителю стихий Ортеллу на Тропу Зловещего Шепота, что на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подпись кровью',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наконец-то ты тут, $n. И очень вовремя.$B$BВесть о появлении Рагнароса многих толкнула в объятия культа Сумеречного Молота.$B$BЕсли хочешь проникнуть в стан культа, то время пришло. Нам понадобится вербовочный лист, который кровью подписал один из членов Сумеречного Молота. Замани одного из рекрутов подальше от основной группы и ударь его дубинкой.$B$BЕсли тебе повезет, то удастся украсть его вербовочный лист. Принеси мне эту бумажку, и мы ее немножко подправим.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заманите сумеречного рекрута подальше от остальных и отнимите у него вербовочный лист Сумеречного Молота.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно. Я постараюсь подделать эти документы.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к повелителю стихий Ортеллу на Тропу Зловещего Шепота, что на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (25275,'Подрядчик Жаднюк','Поговорите с подрядчиком Жаднюком у задних врат Оргриммара в Азшаре.','Хиловата? Тот самый Хиловата?!$B$B<Подрядчик смеривает вас взглядом.>$B$BМолва бежит впереди тебя. Уж и не знаю, радоваться мне тому, что ты здесь, или пугаться. По крайней мере у нас в Азшаре нет вулканов!$B$BЧестно говоря, я даже поверить не могу, что ты почтил нас своим присутствием... Кстати, ваш торговый принц Галливикс уже построил здесь дворец удовольствий! Он находится на вершине горы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подрядчик Жаднюк',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с подрядчиком Жаднюком у задних врат Оргриммара в Азшаре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хиловата? Тот самый Хиловата?!$B$B<Подрядчик смеривает вас взглядом.>$B$BМолва бежит впереди тебя. Уж и не знаю, радоваться мне тому, что ты здесь, или пугаться. По крайней мере у нас в Азшаре нет вулканов!$B$BЧестно говоря, я даже поверить не могу, что ты почтил нас своим присутствием... Кстати, ваш торговый принц Галливикс уже построил здесь дворец удовольствий! Он находится на вершине горы.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25277,'Расчистка территории','Мы собираемся вернуть этому святилищу его былое величие, $n. Но для этого нам всем придется хорошенько потрудиться. На другой стороне луга разбили лагерь несколько отрядов огров под предводительством Гар\'гола.$B$BУбей его прислужников – посмотрим, может, это заставит его убраться отсюда.','Убейте 8 огров – пещерных громил или пещерных темных магов – в схроне Гар\'гола на горе Хиджал.','Ха! У тебя получилось устроить там знатный переполох!$B$BВ легендах, описывающих Войну древних, говорится что Ло\'гош бился с демонам десять дней, не зная отдыха. Надеюсь, тебе не пришлось сражаться так долго…','Вернитесь к Такрику Гневному Вою в Святилище Голдринна на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Расчистка территории',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы собираемся вернуть этому святилищу его былое величие, $n. Но для этого нам всем придется хорошенько потрудиться. На другой стороне луга разбили лагерь несколько отрядов огров под предводительством Гар\'гола.$B$BУбей его прислужников – посмотрим, может, это заставит его убраться отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 огров – пещерных громил или пещерных темных магов – в схроне Гар\'гола на горе Хиджал.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ха! У тебя получилось устроить там знатный переполох!$B$BВ легендах, описывающих Войну древних, говорится что Ло\'гош бился с демонам десять дней, не зная отдыха. Надеюсь, тебе не пришлось сражаться так долго…',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Такрику Гневному Вою в Святилище Голдринна на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25278,'Расчистка территории','Благодаря твоим усилиям мы скоро сможем вернуть святилищу его былое величие. Но сначала нужно занять эту долину. К югу отсюда огры под предводительством Гар\'гола устроили свое вонючее логово.$B$BЯ бы не сказал, что Гар\'гол – это серьезная угроза. Нет, он не более чем гора мяса, которую подкинули, чтобы отвлечь нас от настоящей опасности. Тем не менее, с ним и его тупицами надо разобраться.$B$BВо имя Голдринна, убей огров Гар\'гола!','Убейте 8 огров – пещерных громил или пещерных темных магов – в схроне Гар\'гола на горе Хиджал.','Ты действительно расчистил место, да? Отлично!$B$BНочные эльфы когда-то поведали мне историю о том, как Голдринн сражался и убил повелителя ужаса, хотя еще трое вцепились ему в бока и жгли его плоть. Хотел бы я знать, могло ли у тебя или у меня хватить сил для такого?','Вернитесь к Яну Дюрану в Святилище Голдринна на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Расчистка территории',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Благодаря твоим усилиям мы скоро сможем вернуть святилищу его былое величие. Но сначала нужно занять эту долину. К югу отсюда огры под предводительством Гар\'гола устроили свое вонючее логово.$B$BЯ бы не сказал, что Гар\'гол – это серьезная угроза. Нет, он не более чем гора мяса, которую подкинули, чтобы отвлечь нас от настоящей опасности. Тем не менее, с ним и его тупицами надо разобраться.$B$BВо имя Голдринна, убей огров Гар\'гола!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 огров – пещерных громил или пещерных темных магов – в схроне Гар\'гола на горе Хиджал.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты действительно расчистил место, да? Отлично!$B$BНочные эльфы когда-то поведали мне историю о том, как Голдринн сражался и убил повелителя ужаса, хотя еще трое вцепились ему в бока и жгли его плоть. Хотел бы я знать, могло ли у тебя или у меня хватить сил для такого?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Яну Дюрану в Святилище Голдринна на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25279,'Восстановление святилища','Да, $n. Я Голдринн, которого твои соотечественники называют Ло\'гошем. Твоя храбрость помогла мне вырваться из оков Сумеречного культа.$B$BМое святилище очищено и мои служители вернулись на свое законное место у моей правой лапы.$b$bВернись к Такрику и продолжай помогать Хиджалу. Скоро ты мне понадобишься.','Вернитесь к Такрику Гневному Вою в восстановленное Святилище Голдринна на горе Хиджал.','Вернитесь к Такрику Гневному Вою в восстановленное Святилище Голдринна на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Восстановление святилища',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Да, $n. Я Голдринн, которого твои соотечественники называют Ло\'гошем. Твоя храбрость помогла мне вырваться из оков Сумеречного культа.$B$BМое святилище очищено и мои служители вернулись на свое законное место у моей правой лапы.$b$bВернись к Такрику и продолжай помогать Хиджалу. Скоро ты мне понадобишься.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь к Такрику Гневному Вою в восстановленное Святилище Голдринна на горе Хиджал.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Такрику Гневному Вою в восстановленное Святилище Голдринна на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25280,'Восстановление святилища','Да, $n. Я Голдринн. Твоя храбрость помогла мне вырваться из оков сумеречного культа.$B$BМое святилище очищено и мои служители вернулись на свое законное место у моей правой лапы.$b$bВернись к Яну и продолжай свою работу на благо Хиджала. Очень скоро мне вновь понадобится твоя помощь.','Вернитесь к Яну Дюрану в восстановленное Святилище Голдринна на горе Хиджал.','Вернитесь к Яну Дюрану в восстановленное Святилище Голдринна на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Восстановление святилища',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Да, $n. Я Голдринн. Твоя храбрость помогла мне вырваться из оков сумеречного культа.$B$BМое святилище очищено и мои служители вернулись на свое законное место у моей правой лапы.$b$bВернись к Яну и продолжай свою работу на благо Хиджала. Очень скоро мне вновь понадобится твоя помощь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь к Яну Дюрану в восстановленное Святилище Голдринна на горе Хиджал.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Яну Дюрану в восстановленное Святилище Голдринна на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25281,'Время вернуть должок','Теперь ты можешь свободно перемещаться по этой местности и не бояться утонуть.$B$BТак что приступим к работе.$B$BНачнем с того, что пока мы тут ведем беседы, наши союзники вокруг идут ко дну. Я выручил тебя – а теперь ты помоги им.$B$BЯ наложил чары на раковину, что ты мне $gпринес:принесла;. Воспользуйся ею и выручи наших братьев.$B$BПоторопись!','С помощью зачарованной раковины стромбиды спасите 6 тонущих солдат.','Поговорите с Эрунаком на "Морском Кортике".') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Время вернуть должок',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь ты можешь свободно перемещаться по этой местности и не бояться утонуть.$B$BТак что приступим к работе.$B$BНачнем с того, что пока мы тут ведем беседы, наши союзники вокруг идут ко дну. Я выручил тебя – а теперь ты помоги им.$B$BЯ наложил чары на раковину, что ты мне $gпринес:принесла;. Воспользуйся ею и выручи наших братьев.$B$BПоторопись!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','С помощью зачарованной раковины стромбиды спасите 6 тонущих солдат.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Эрунаком на "Морском Кортике".',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25282,'Знаки времен','Необходимо как-то снизить интерес к этой секте вестников рока, но я опасаюсь предпринимать что-то прежде, чем мы узнаем, кто стоит за ней.$b$bМои люди отметили наиболее оживленные места в городе. Возьми эти плакаты и развесь их там, где увидишь отметки. Самых ярых поклонников секты они не остановят, но все же это первый шаг к изобличению секты. У короля хватает неприятелей и без этих лгунов, настраивающих люд против него.','Расставьте 5 предупредительных плакатов в Торговом квартале, на Соборной площади, в Старом городе или Квартале Магов Штормграда.','Вернитесь к капитану Антону в крепость Штормграда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Знаки времен',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Необходимо как-то снизить интерес к этой секте вестников рока, но я опасаюсь предпринимать что-то прежде, чем мы узнаем, кто стоит за ней.$b$bМои люди отметили наиболее оживленные места в городе. Возьми эти плакаты и развесь их там, где увидишь отметки. Самых ярых поклонников секты они не остановят, но все же это первый шаг к изобличению секты. У короля хватает неприятелей и без этих лгунов, настраивающих люд против него.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Расставьте 5 предупредительных плакатов в Торговом квартале, на Соборной площади, в Старом городе или Квартале Магов Штормграда.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Антону в крепость Штормграда.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25283,'Готовим речь','Главный механик Меггакрут попросил меня написать речь, которую он мог бы произнести перед началом битвы, но я уже не могу отличить хороший текст от никуда не годного.$b$bКак думаешь, сможешь взять несколько образцов и проверить, как они действуют на местных гномов? Я дам тебе устройство, которое создает образ Меггакрута, произносящего несколько строк каждой из моих речей.$b$bСкажи мне, какая из них лучше всего влияет на слушателей, хорошо?','О боже. Их реакции были настолько разными?$B$BНе совсем то, что я ожидал, но думаю, у меня есть подходящая речь.$B$BПросто дай мне найти, куда я его положил...','Дай мне знать, какой из них работает, хорошо?','Вернитесь к Тоби Зимехану в Поселок Сталежара.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Готовим речь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Главный механик Меггакрут попросил меня написать речь, которую он мог бы произнести перед началом битвы, но я уже не могу отличить хороший текст от никуда не годного.$b$bКак думаешь, сможешь взять несколько образцов и проверить, как они действуют на местных гномов? Я дам тебе устройство, которое создает образ Меггакрута, произносящего несколько строк каждой из моих речей.$b$bСкажи мне, какая из них лучше всего влияет на слушателей, хорошо?',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О боже. Их реакции были настолько разными?$B$BНе совсем то, что я ожидал, но думаю, у меня есть подходящая речь.$B$BПросто дай мне найти, куда я его положил...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Дай мне знать, какой из них работает, хорошо?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тоби Зимехану в Поселок Сталежара.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25284,'Питая хаос','Наши ресурсы ограничены, |3-6($c), но это не означает, что мы не можем ничего сделать. Используй веревки, чтобы спуститься с холма, и убей тюремщиков.$b$bУбийство пары тощих людишек не изменит исход битвы, но представь, в каком ужасе будут люди, когда обнаружат изуродованные тела...$b$b<Холгом подмигивает, его глаза сверкают.>','Убейте 5 стражей башни. Используйте веревки Холгома, чтобы быстро забраться и выбраться из Заставы Чести.','Хорошо, хорошо. Немало бессонных ночей им придется провести, чтобы понять, откуда мы пришли, и куда исчезли...','Вернитесь к Холгому на Верхний путь в Южных Cтепях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Питая хаос',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наши ресурсы ограничены, |3-6($c), но это не означает, что мы не можем ничего сделать. Используй веревки, чтобы спуститься с холма, и убей тюремщиков.$b$bУбийство пары тощих людишек не изменит исход битвы, но представь, в каком ужасе будут люди, когда обнаружат изуродованные тела...$b$b<Холгом подмигивает, его глаза сверкают.>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 5 стражей башни. Используйте веревки Холгома, чтобы быстро забраться и выбраться из Заставы Чести.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо, хорошо. Немало бессонных ночей им придется провести, чтобы понять, откуда мы пришли, и куда исчезли...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Холгому на Верхний путь в Южных Cтепях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25285,'Входит и выходит!','Надо подготовить эти новые механотанки для осады города. Ты ведь не откажешься протестировать этих чудовищ? Конечно, нет!$b$bСначала надо убедиться в том, что из них можно выбраться. Знаешь ли, это очень важно, особенно если в бою твой танк подбили, и он вот-вот взорвется. Я знал много отважных гномов, которые оставались в машине до последнего – и погибали вместе с танком.$B$BТак что эти машины я оборудовал креслами с катапультой. Испытай их, ладно?','Испытайте систему катапультирования в механотанке.','Сообщите капитану Ступу Искражу о том, что вы успешно катапультировались.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Входит и выходит!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Надо подготовить эти новые механотанки для осады города. Ты ведь не откажешься протестировать этих чудовищ? Конечно, нет!$b$bСначала надо убедиться в том, что из них можно выбраться. Знаешь ли, это очень важно, особенно если в бою твой танк подбили, и он вот-вот взорвется. Я знал много отважных гномов, которые оставались в машине до последнего – и погибали вместе с танком.$B$BТак что эти машины я оборудовал креслами с катапультой. Испытай их, ладно?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Испытайте систему катапультирования в механотанке.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Сообщите капитану Ступу Искражу о том, что вы успешно катапультировались.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25286,'Слова, что нужно произнести','Готово! Речь написана, $n! То, что надо для начала битвы... вдохновляющая, выразительная, взывающая к самому сердцу каждого гнома! Никогда у меня не получалось речи лучше!$B$BПринеси ее капитану Ступу Искражу, а он уже переправит тебя к главному механику Меггакруту.','Передайте речь капитану Ступу Искражу, который ждет вас в Поселке Сталежара.','Тоби все закончил с речью? Дайте-ка подумать...$B$B<Читает речь> Качаем поршни! Какая фантастическая речь! Я знал, что Тоби хороший писатель, но, пожалуй, это лучшее, что он когда-либо писал.$B$BДумаю, пора вывести тебя в бой.','Поговорите с капитаном Ступом Искражем в Поселке Сталежара.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Слова, что нужно произнести',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Готово! Речь написана, $n! То, что надо для начала битвы... вдохновляющая, выразительная, взывающая к самому сердцу каждого гнома! Никогда у меня не получалось речи лучше!$B$BПринеси ее капитану Ступу Искражу, а он уже переправит тебя к главному механику Меггакруту.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Передайте речь капитану Ступу Искражу, который ждет вас в Поселке Сталежара.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тоби все закончил с речью? Дайте-ка подумать...$B$B<Читает речь> Качаем поршни! Какая фантастическая речь! Я знал, что Тоби хороший писатель, но, пожалуй, это лучшее, что он когда-либо писал.$B$BДумаю, пора вывести тебя в бой.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с капитаном Ступом Искражем в Поселке Сталежара.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25287,'Слова, что нужно произнести','Итак, солдат, настал твой черед проявить себя.$B$BВозьми эту речь и садись на борт "Молнии", что находится рядом со мной. Этот стремительный ветролет доставит тебя прямо к главному механику Меггакруту. Ему не хватает только этой речи, чтобы начать наступление на Гномреган. Торопись!','Отправляйтесь на "Молнии" из Поселка Сталежара к главному механику Меггакруту и передайте ему речь Тоби.','Отдайте речь главному механику Меггакруту.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Слова, что нужно произнести',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Итак, солдат, настал твой черед проявить себя.$B$BВозьми эту речь и садись на борт "Молнии", что находится рядом со мной. Этот стремительный ветролет доставит тебя прямо к главному механику Меггакруту. Ему не хватает только этой речи, чтобы начать наступление на Гномреган. Торопись!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь на "Молнии" из Поселка Сталежара к главному механику Меггакруту и передайте ему речь Тоби.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отдайте речь главному механику Меггакруту.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25288,'Внедрение в секту','Улицы Оргриммара полны слухов о происхождении этой секты и ее ритуалах. Есть только один способ узнать истину, $n.$b$bТы присоединишься к ним.$b$bПодойди к любому из вестников рока и скажи, что хочешь вступить в секту. Если повезет, ты получишь указания явиться к лидеру одной из групп и таким образом узнаешь, где находится их укрытие. Наденешь все, что получишь от вестника рока – иначе не сможешь проникнуть туда.','Поговорите с одним из вестников рока в Волоке Оргриммара либо возьмите одеяние из ящика рядом с вестником рока, чтобы присоединиться к их секте, после чего наденьте одеяние новообращенного.','Поговорите с надзирательницей Джинтак на Свиноферме за пределами Оргриммара.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Внедрение в секту',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Улицы Оргриммара полны слухов о происхождении этой секты и ее ритуалах. Есть только один способ узнать истину, $n.$b$bТы присоединишься к ним.$b$bПодойди к любому из вестников рока и скажи, что хочешь вступить в секту. Если повезет, ты получишь указания явиться к лидеру одной из групп и таким образом узнаешь, где находится их укрытие. Наденешь все, что получишь от вестника рока – иначе не сможешь проникнуть туда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с одним из вестников рока в Волоке Оргриммара либо возьмите одеяние из ящика рядом с вестником рока, чтобы присоединиться к их секте, после чего наденьте одеяние новообращенного.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с надзирательницей Джинтак на Свиноферме за пределами Оргриммара.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25289,'Шаг вперед...','Система катапультирования работает превосходно, так что теперь можно приступить к испытанию ходовых механизмов. В этом танке установлена уникальная система автоматического маневрирования.$b$bТебе надо будет испытать сервоприводы левой и правой ноги танка, а также систему уклонения.$b$bЭто несложно и не должно занять много времени.','Испытайте маневренность танка-паука.','Сообщите капитану Ступу Искражу о результатах испытаний.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Шаг вперед...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Система катапультирования работает превосходно, так что теперь можно приступить к испытанию ходовых механизмов. В этом танке установлена уникальная система автоматического маневрирования.$b$bТебе надо будет испытать сервоприводы левой и правой ноги танка, а также систему уклонения.$b$bЭто несложно и не должно занять много времени.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Испытайте маневренность танка-паука.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Сообщите капитану Ступу Искражу о результатах испытаний.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25290,'Внедрение в секту','Становится все сложнее и сложнее скрывать существование этой секты от общественности – по городу ползут слухи. Я хочу, чтобы ты $gприсоединился:присоединилась; к секте и $gузнал:узнала; о ней как можно больше.$b$bНайди одного из вестников рока в Старом городе и сообщи о своем желании присоединиться к секте. Скорее всего, тебе выдадут одежду и пригласят на встречу с другими сектантами в одном из их укрытий. Следуй этим инструкциям, $n. Это единственный способ втереться к ним в доверие.','Возьмите одеяние новообращенного у вестника рока в Старом городе Штормграда или возьмите одеяние, лежащее в ящике рядом с вестником рока, и облачитесь в него, чтобы вступить в секту Судного дня.','Поговорите с надзирательницей Силандрой в саду у Зеркального озера, что в Элвиннском лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Внедрение в секту',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Становится все сложнее и сложнее скрывать существование этой секты от общественности – по городу ползут слухи. Я хочу, чтобы ты $gприсоединился:присоединилась; к секте и $gузнал:узнала; о ней как можно больше.$b$bНайди одного из вестников рока в Старом городе и сообщи о своем желании присоединиться к секте. Скорее всего, тебе выдадут одежду и пригласят на встречу с другими сектантами в одном из их укрытий. Следуй этим инструкциям, $n. Это единственный способ втереться к ним в доверие.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возьмите одеяние новообращенного у вестника рока в Старом городе Штормграда или возьмите одеяние, лежащее в ящике рядом с вестником рока, и облачитесь в него, чтобы вступить в секту Судного дня.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с надзирательницей Силандрой в саду у Зеркального озера, что в Элвиннском лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25291,'Тренировка Сумеречного Молота','Ты $gдоказал:доказала;, что $gдостоин:достойна; принимать участие хотя бы в наших основных тренировках.$B$BТы найдешь одно из наших поселений на востоке отсюда. Поговори там с наставницей Милвой.','Поговорите с наставницей Милвой на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тренировка Сумеречного Молота',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gдоказал:доказала;, что $gдостоин:достойна; принимать участие хотя бы в наших основных тренировках.$B$BТы найдешь одно из наших поселений на востоке отсюда. Поговори там с наставницей Милвой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с наставницей Милвой на горе Хиджал.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25292,'Ближайшие родственники','<Нато отзывает вас в сторонку и шепчет.>$b$B$n, я удалил пулю из груди Ганна, однако пузырьки в его крови достаточно красноречивы. Его легкие проколоты, у него начинается сепсис. Ему недолго осталось.$b$bВозьми это. Это та самая пуля, что убила его. Наверняка семья захочет узнать, что случилось с самым юным из их воинов.$b$bРазыщи Альто Каменное Копье. Он служит в Пылевых Топях. Отправляйся на северо-восток и следуй по дороге к деревне Гиблотопь.','Отнесите дворфийскую пулю Альто Каменное Копье в деревню Гиблотопь в Пылевых Топях.','Отнесите дворфийскую пулю Альто Каменное Копье в деревню Гиблотопь в Пылевых Топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ближайшие родственники',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Нато отзывает вас в сторонку и шепчет.>$b$B$n, я удалил пулю из груди Ганна, однако пузырьки в его крови достаточно красноречивы. Его легкие проколоты, у него начинается сепсис. Ему недолго осталось.$b$bВозьми это. Это та самая пуля, что убила его. Наверняка семья захочет узнать, что случилось с самым юным из их воинов.$b$bРазыщи Альто Каменное Копье. Он служит в Пылевых Топях. Отправляйся на северо-восток и следуй по дороге к деревне Гиблотопь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите дворфийскую пулю Альто Каменное Копье в деревню Гиблотопь в Пылевых Топях.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите дворфийскую пулю Альто Каменное Копье в деревню Гиблотопь в Пылевых Топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25293,'Пропавшие','Помимо беспорядков и общей паранойи, окружающей секту, есть еще одна проблема – мы завалены сообщениями о пропавших людях. Пропадают чьи-то матери, отцы, братья и сестры, и у меня есть предпололжение, что искать их следует в поселениях сектантов за пределами города. Если я дам тебе имена некоторых из пропавших людей, сможешь ли ты разыскать их в лагере сектантов? Он расположен на свиноферме к югу от Оргриммара. Для того, чтобы проникнуть в него, тебе потребуется специальное одеяние, его можно получить у одного из вестников рока на Волоке.','Надев маскировку под сектанта, поговорите с сектантом Кагарном, сектантом Агтаром, сектантом Токкой и сектантом Рокагой. Все они находятся на Свиноферме в Дуротаре.','Вернитесь к кровавому стражу Тореку в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пропавшие',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Помимо беспорядков и общей паранойи, окружающей секту, есть еще одна проблема – мы завалены сообщениями о пропавших людях. Пропадают чьи-то матери, отцы, братья и сестры, и у меня есть предпололжение, что искать их следует в поселениях сектантов за пределами города. Если я дам тебе имена некоторых из пропавших людей, сможешь ли ты разыскать их в лагере сектантов? Он расположен на свиноферме к югу от Оргриммара. Для того, чтобы проникнуть в него, тебе потребуется специальное одеяние, его можно получить у одного из вестников рока на Волоке.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Надев маскировку под сектанта, поговорите с сектантом Кагарном, сектантом Агтаром, сектантом Токкой и сектантом Рокагой. Все они находятся на Свиноферме в Дуротаре.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к кровавому стражу Тореку в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25294,'Выгулять собачку','Хм-м-м-м... похоже, теперь они набирают кого попало.$B$BЛадно. Ты, конечно же, $gуспел:успела; познакомиться с Тлетвором на тренировочной площадке.$B$BЧто ж, мне поручили заботиться об одном из его щенков. Маленький монстрик. Если он вырастет таким, как его отец, он нам хорошо послужит.$B$BПринеси для него мяса василисков.','Добудьте 5 кусков обугленного мяса василиска и скормите их порождению Тлетвора.','Прекрасно. Этот щенок вырастет столь же сильным и безжалостным, как и его отец.','Вернитесь к наставнику Деворану в Кузню Мольбы на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Выгулять собачку',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хм-м-м-м... похоже, теперь они набирают кого попало.$B$BЛадно. Ты, конечно же, $gуспел:успела; познакомиться с Тлетвором на тренировочной площадке.$B$BЧто ж, мне поручили заботиться об одном из его щенков. Маленький монстрик. Если он вырастет таким, как его отец, он нам хорошо послужит.$B$BПринеси для него мяса василисков.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 5 кусков обугленного мяса василиска и скормите их порождению Тлетвора.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно. Этот щенок вырастет столь же сильным и безжалостным, как и его отец.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к наставнику Деворану в Кузню Мольбы на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25295,'Шквальный огонь','Системы безопасности включены, мотор работает! Теперь осталось только убедиться в том, что пушки выстрелят в нужный момент.$b$bЭто несложное задание я хочу поручить тебе, $n. Вон тот механический танк на холме только что зарядили холостыми ракетами. Выстрели пару раз по ближайшим целям и доложи мне результат.','Испытайте оружейные системы механотанка на ближайших целях.','Сообщите капитану Ступу Искражу о результатах испытаний.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Шквальный огонь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Системы безопасности включены, мотор работает! Теперь осталось только убедиться в том, что пушки выстрелят в нужный момент.$b$bЭто несложное задание я хочу поручить тебе, $n. Вон тот механический танк на холме только что зарядили холостыми ракетами. Выстрели пару раз по ближайшим целям и доложи мне результат.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Испытайте оружейные системы механотанка на ближайших целях.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Сообщите капитану Ступу Искражу о результатах испытаний.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25296,'Сбор информации','Это я, $n, Ортелл!$B$BНе смотри прямо на нужник... ты выдашь мое местоположение.$B$BВсе идет по плану? Прекрасно!$B$BМне понадобится, чтобы ты $gраздобыл:раздобыла; немного информации, пока ты здесь. Может показаться, что мы особо ничего не выиграем, заполучив письмо или карту, но если разузнать следующий шаг противника, то можно спасти сотни жизней наших бойцов.','Заполучите воззвание Сумеречного Молота и планы завоевания Хиджала.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сбор информации',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это я, $n, Ортелл!$B$BНе смотри прямо на нужник... ты выдашь мое местоположение.$B$BВсе идет по плану? Прекрасно!$B$BМне понадобится, чтобы ты $gраздобыл:раздобыла; немного информации, пока ты здесь. Может показаться, что мы особо ничего не выиграем, заполучив письмо или карту, но если разузнать следующий шаг противника, то можно спасти сотни жизней наших бойцов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заполучите воззвание Сумеречного Молота и планы завоевания Хиджала.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25297,'Во власти безумия','Я знаю, как можно вернуть этих несчастных в нормальное состояние. Собери немного камнецвета на скалах возле схрона Гар\'гола, пару цветков горькоцвета с берегов близлежащего озера и уголек черного огня из жаровни возле входа в схрон. Настой не может долго сохранять свои целебные свойства, так что советую смешать ингредиенты в котле Сумеречного Молота у входа в схрон.$B$BОдин глоток этого настоя приведет в чувство любого помешавшегося раба!','Добудьте камнецвет, горькоцвет и уголек черного огня.','<Вы выливаете на землю содержимое котла, и окружающие растения мгновенно погибают.>$B$B<Приготовленное вами варево, пахнущее гнилой капустой, бурлит. Стараясь не дышать, вы переливаете его в бутылку.>','<Омерзительная жидкость в котле начинает бурлить.>','Смешайте ингредиенты в котле Сумеречного Молота у входа в схрон Гар\'гола на Хиджале.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Во власти безумия',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я знаю, как можно вернуть этих несчастных в нормальное состояние. Собери немного камнецвета на скалах возле схрона Гар\'гола, пару цветков горькоцвета с берегов близлежащего озера и уголек черного огня из жаровни возле входа в схрон. Настой не может долго сохранять свои целебные свойства, так что советую смешать ингредиенты в котле Сумеречного Молота у входа в схрон.$B$BОдин глоток этого настоя приведет в чувство любого помешавшегося раба!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте камнецвет, горькоцвет и уголек черного огня.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Вы выливаете на землю содержимое котла, и окружающие растения мгновенно погибают.>$B$B<Приготовленное вами варево, пахнущее гнилой капустой, бурлит. Стараясь не дышать, вы переливаете его в бутылку.>',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Омерзительная жидкость в котле начинает бурлить.>',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Смешайте ингредиенты в котле Сумеречного Молота у входа в схрон Гар\'гола на Хиджале.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25298,'Мы – то, что мы думаем','<Рио сказал, что настой недолго будет сохранять целебные свойства.>$B$B<Лучше поспешить в схрон и напоить им как можно больше сумеречных слуг.>','Поговорите с восемью сумеречными слугами, чтобы предложить им настой и спасти их.','Настой сработал?','Вернитесь к Рио Дюран в Святилище Голдринна на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мы – то, что мы думаем',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Рио сказал, что настой недолго будет сохранять целебные свойства.>$B$B<Лучше поспешить в схрон и напоить им как можно больше сумеречных слуг.>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с восемью сумеречными слугами, чтобы предложить им настой и спасти их.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Настой сработал?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Рио Дюран в Святилище Голдринна на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25299,'Подготовка разума: говорить правду Силе','Ты думаешь, что $gготов:готова; получить знание, которое мы тебе дадим. Но это не так.$B$BПредставь свой разум как коробочку внутри множества коробочек.$B$BКаждый шаг открывает одну из этих коробочек, пока ты не сможешь напрямую общаться со стихиями.$B$BВозьми сферу вознесения и правдиво ответь на все вопросы. Не сможешь – все кончится... трагически.','Используйте сферу вознесения и верно ответьте на 10 вопросов.','Вернитесь к наставнице Милве в Кузню Мольбы на Хиджале.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подготовка разума: говорить правду Силе',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты думаешь, что $gготов:готова; получить знание, которое мы тебе дадим. Но это не так.$B$BПредставь свой разум как коробочку внутри множества коробочек.$B$BКаждый шаг открывает одну из этих коробочек, пока ты не сможешь напрямую общаться со стихиями.$B$BВозьми сферу вознесения и правдиво ответь на все вопросы. Не сможешь – все кончится... трагически.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте сферу вознесения и верно ответьте на 10 вопросов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к наставнице Милве в Кузню Мольбы на Хиджале.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25300,'Око Сумерек','Кланом огров, расположившимся за рекой, руководит Гар\'гол. "Руководит" – это, конечно, сильно сказано: по количеству мозгов Гар\'гола вполне можно сравнить с подметкой моего сапога.$B$BНасколько мне известно, он получает приказы от какого-то магического артефакта – "Ока Сумерек". Он без рассуждений повинуется любым приказам этой вещи.$B$BЕсли нам удастся вывести из строя этот артефакт, паника поднимется невообразимая.$B$BОтправляйся в схрон Гар\'гола и найди Око Сумерек, оно находится недалеко от входа. Внимательно изучи его и найди возможность вывести из строя. Ах какой дивный поднимется шум!..','Найдите Око Сумерек возле входа в схрон Гар\'гола на Хиджале.','<Вы приближаетесь к Оку Сумерек. Как только ваши пальцы касаются его мерцающей поверхности, вы ощущаете присутствие какой-то злобной сущности, внимательно изучающей вас.>$B$B<Вы инстинктивно отступаете.>','Найдите Око Сумерек возле входа в схрон Гар\'гола на Хиджале.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Око Сумерек',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кланом огров, расположившимся за рекой, руководит Гар\'гол. "Руководит" – это, конечно, сильно сказано: по количеству мозгов Гар\'гола вполне можно сравнить с подметкой моего сапога.$B$BНасколько мне известно, он получает приказы от какого-то магического артефакта – "Ока Сумерек". Он без рассуждений повинуется любым приказам этой вещи.$B$BЕсли нам удастся вывести из строя этот артефакт, паника поднимется невообразимая.$B$BОтправляйся в схрон Гар\'гола и найди Око Сумерек, оно находится недалеко от входа. Внимательно изучи его и найди возможность вывести из строя. Ах какой дивный поднимется шум!..',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Око Сумерек возле входа в схрон Гар\'гола на Хиджале.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Вы приближаетесь к Оку Сумерек. Как только ваши пальцы касаются его мерцающей поверхности, вы ощущаете присутствие какой-то злобной сущности, внимательно изучающей вас.>$B$B<Вы инстинктивно отступаете.>',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Найдите Око Сумерек возле входа в схрон Гар\'гола на Хиджале.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25301,'Подчинить себе','<За то мгновение, когда вы взаимодействовали с Оком, вы почувствовали, что источник его силы находится внутри схрона. Вы чувствовали присутствие огромной книги, объединившей в себе все четыре стихии.>$B$B<Если вы хотите подчинить себе Око, необходимо найти эту книгу в схроне.>','Найдите Апокриф сумерек в схроне Гар\'гола на Хиджале.','<Тяжелый том, обтянутый человеческой кожей, лежит распахнутый на столе.>$B$B<Вместо понятного языка в книге используются какие-то пиктограммы, нарисованные отвратительными бурыми чернилами. Расшифровать их вы не можете, но на некоторых страницах обнаруживаются пометки и комментарии. Должно быть, это вы и искали.>','Найдите Апокриф сумерек в схроне Гар\'гола на Хиджале.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подчинить себе',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<За то мгновение, когда вы взаимодействовали с Оком, вы почувствовали, что источник его силы находится внутри схрона. Вы чувствовали присутствие огромной книги, объединившей в себе все четыре стихии.>$B$B<Если вы хотите подчинить себе Око, необходимо найти эту книгу в схроне.>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Апокриф сумерек в схроне Гар\'гола на Хиджале.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Тяжелый том, обтянутый человеческой кожей, лежит распахнутый на столе.>$B$B<Вместо понятного языка в книге используются какие-то пиктограммы, нарисованные отвратительными бурыми чернилами. Расшифровать их вы не можете, но на некоторых страницах обнаруживаются пометки и комментарии. Должно быть, это вы и искали.>',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Найдите Апокриф сумерек в схроне Гар\'гола на Хиджале.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25302,'Remnants of Battle','A great battle took place here. Mixed with the naga skeletons are that of some sort of large humanoids. This might be interesting news to XXX.','Bring the Broken Shard to XXX at XXX.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Remnants of Battle',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','A great battle took place here. Mixed with the naga skeletons are that of some sort of large humanoids. This might be interesting news to XXX.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Bring the Broken Shard to XXX at XXX.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25303,'Стихийное понимание','<Текст вы прочитать не можете, но схемы указывают на то, что устройства вокруг вас необходимо включать в определенном порядке.>$B$B<Один из абзацев Апокрифа оказывается переведенным на понятный вам язык:>$b$bВначале была тень вечная.$bЗатем вспыхнула ненависть – и появился ОГОНЬ.$bРаны затянулись шрамами, так возникла ЗЕМЛЯ.$bКрики боли породили воющий ВЕТЕР.$bНебеса наполнили моря своими СЛЕЗАМИ.$bВсе мы блуждаем в сумерках.$bМир, каким мы его знаем, выстроен на ярости, боли, мучениях и скорби.','Активируйте четыре ближайших тигля в правильном порядке, чтобы получить контроль над Оком Сумерек.','<Переполнившись энергиями плененных стихий, вы стоите перед Апокрифом сумерек. Страницы переворачиваются сами собой.>$B$B<Внезапно вы начинаете видеть все, что видит Око. Теперь оно подчиняется вашим приказам!>','Найдите нужную информацию в Апокрифе сумерек в схроне Гар\'гола на Хиджале.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Стихийное понимание',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Текст вы прочитать не можете, но схемы указывают на то, что устройства вокруг вас необходимо включать в определенном порядке.>$B$B<Один из абзацев Апокрифа оказывается переведенным на понятный вам язык:>$b$bВначале была тень вечная.$bЗатем вспыхнула ненависть – и появился ОГОНЬ.$bРаны затянулись шрамами, так возникла ЗЕМЛЯ.$bКрики боли породили воющий ВЕТЕР.$bНебеса наполнили моря своими СЛЕЗАМИ.$bВсе мы блуждаем в сумерках.$bМир, каким мы его знаем, выстроен на ярости, боли, мучениях и скорби.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Активируйте четыре ближайших тигля в правильном порядке, чтобы получить контроль над Оком Сумерек.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Переполнившись энергиями плененных стихий, вы стоите перед Апокрифом сумерек. Страницы переворачиваются сами собой.>$B$B<Внезапно вы начинаете видеть все, что видит Око. Теперь оно подчиняется вашим приказам!>',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Найдите нужную информацию в Апокрифе сумерек в схроне Гар\'гола на Хиджале.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (25304,'Битва за Сардор','Поговорите с Тамброй на острове Сардор.','Настал час сбросить этих тварей в море, откуда они и выползли. Я надеюсь на тебя!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Битва за Сардор',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Тамброй на острове Сардор.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Настал час сбросить этих тварей в море, откуда они и выползли. Я надеюсь на тебя!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25305,'Без оглядки на прошлое','Наше поселение на острове Сардор захватили наги из клана Гребня Ненависти. Под натиском их превосходящих сил, мы были вынуждены отступить на материк. Пока они пытались закрепиться на песчаных отмелях, мы отошли к крепости Оперенной Луны на побережье и набрали там новую армию.$B$BТеперь мы сможем сбросить отряды Гребня Ненависти обратно в море. Поговори с часовой Ранадаей, чтобы влиться в наши ряды. Перебей наг и ту подлую змею, что отдает им приказы.','Убейте 10 наг из клана Гребня Ненависти и их предводителя.','Вернитесь к Шандрисе Оперенной Луне в крепость Оперенной Луны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Без оглядки на прошлое',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наше поселение на острове Сардор захватили наги из клана Гребня Ненависти. Под натиском их превосходящих сил, мы были вынуждены отступить на материк. Пока они пытались закрепиться на песчаных отмелях, мы отошли к крепости Оперенной Луны на побережье и набрали там новую армию.$B$BТеперь мы сможем сбросить отряды Гребня Ненависти обратно в море. Поговори с часовой Ранадаей, чтобы влиться в наши ряды. Перебей наг и ту подлую змею, что отдает им приказы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 наг из клана Гребня Ненависти и их предводителя.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Шандрисе Оперенной Луне в крепость Оперенной Луны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25306,'Теперь ты в армии, гном!','[ph] War!','[ph] Log Description') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Теперь ты в армии, гном!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','[ph] War!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','[ph] Log Description',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (25307,'Подслушивание') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подслушивание',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (25308,'Зерна раздора','Судя по собранным тобою данным, между ограми и другими членами культа существует сильная неприязнь.$B$BВерховный сектант Азенниос и огр-маг Карр\'гонн собираются встретиться у Совета Избранных и попытаться ослабить напряженность.$B$BУ Совета Избранных есть такой же нужник, как и тут. Пойди туда и надень эту маскировку под огра. Убей Азенниоса, пока он находится на своей миротворческой миссии.$B$BМы должны использовать их разногласия к собственной выгоде!','Отвлеките Карр\'гонна и убейте верховного сектанта Азенниоса у Совета Избранных на Хиджале.','Вернитесь в убежище в туалете возле Кузни Мольбы на Хиджале.','Наша цель – Азенниос. Убейте его!','Верховный сектант Азенниос') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зерна раздора',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Судя по собранным тобою данным, между ограми и другими членами культа существует сильная неприязнь.$B$BВерховный сектант Азенниос и огр-маг Карр\'гонн собираются встретиться у Совета Избранных и попытаться ослабить напряженность.$B$BУ Совета Избранных есть такой же нужник, как и тут. Пойди туда и надень эту маскировку под огра. Убей Азенниоса, пока он находится на своей миротворческой миссии.$B$BМы должны использовать их разногласия к собственной выгоде!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отвлеките Карр\'гонна и убейте верховного сектанта Азенниоса у Совета Избранных на Хиджале.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь в убежище в туалете возле Кузни Мольбы на Хиджале.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Наша цель – Азенниос. Убейте его!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Верховный сектант Азенниос',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25309,'Духовная подготовка: жалость – слово для слабых','Тебе удалось далеко продвинуться. Другие не так преуспели.$B$BИди на Заставу Судьбы, к северу отсюда. Мы там собрали все... результаты провалов. Позаботься о них. Это будет хорошая пища для твоего духовного роста.$B$BЕсли подобный хладнокровный акт тебя беспокоит, считай что ты даешь им второй шанс. Если кто-нибудь из них тебя убьет... он займет твое место.','Убейте 5 ослабевших молельщиков на Заставе Судьбы.','Ты на финишной прямой к успеху. Будем надеяться, что не испортишь свой рекорд такой глупостью, как сочувствие или человечность.$B$BДавай же обсудим твое будущее.','Вернитесь к наставнице Милве в Кузню Мольбы на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Духовная подготовка: жалость – слово для слабых',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе удалось далеко продвинуться. Другие не так преуспели.$B$BИди на Заставу Судьбы, к северу отсюда. Мы там собрали все... результаты провалов. Позаботься о них. Это будет хорошая пища для твоего духовного роста.$B$BЕсли подобный хладнокровный акт тебя беспокоит, считай что ты даешь им второй шанс. Если кто-нибудь из них тебя убьет... он займет твое место.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 5 ослабевших молельщиков на Заставе Судьбы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты на финишной прямой к успеху. Будем надеяться, что не испортишь свой рекорд такой глупостью, как сочувствие или человечность.$B$BДавай же обсудим твое будущее.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к наставнице Милве в Кузню Мольбы на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (25310,'Большее из зол','Мы отбили теснину Темного Шепота у демонов Пылающего легиона. Мы довольно прочно удерживаем эту территорию, за одним исключением.$B$BНедавно мы потеряли Врата Созанна в бою против властителя преисподней и его армии. Нельзя это так оставить.$B$BИспользуй этот талисман, когда окажешься рядом с ним. Ты временно получишь силы перерожденного служителя огня. Не медли.','Используйте талисман огненного господства и убейте Гарнота Кулака Легиона у Врат Созанна на Хиджале.','Вернитесь к наставнице Милве в Кузню Мольбы на горе Хиджал.','Пылающему легиону тут не место. Теперь тут властвует Сумеречный Молот.','Гарнот Кулак Легиона') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Большее из зол',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы отбили теснину Темного Шепота у демонов Пылающего легиона. Мы довольно прочно удерживаем эту территорию, за одним исключением.$B$BНедавно мы потеряли Врата Созанна в бою против властителя преисподней и его армии. Нельзя это так оставить.$B$BИспользуй этот талисман, когда окажешься рядом с ним. Ты временно получишь силы перерожденного служителя огня. Не медли.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте талисман огненного господства и убейте Гарнота Кулака Легиона у Врат Созанна на Хиджале.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к наставнице Милве в Кузню Мольбы на горе Хиджал.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Пылающему легиону тут не место. Теперь тут властвует Сумеречный Молот.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Гарнот Кулак Легиона',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25311,'Сумеречная зона','Демоны Пылающего Легиона думают, что они могут прийти и попросту захватить то, что им понравится. Конечно же, эта территория раньше им принадлежала, но не в том дело.$B$BМы их научим не связываться с Сумеречным Молотом.$B$BИди к Вратам Созанна и уничтожь отряд ужасных стражей, которые там бродят.','Убейте 10 ужасных стражей у Врат Созанна на Хиджале.','Как всегда, блестяще. Ты меня не разочаровал.','Вернитесь к наставнице Милве в Кузню Мольбы на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сумеречная зона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Демоны Пылающего Легиона думают, что они могут прийти и попросту захватить то, что им понравится. Конечно же, эта территория раньше им принадлежала, но не в том дело.$B$BМы их научим не связываться с Сумеречным Молотом.$B$BИди к Вратам Созанна и уничтожь отряд ужасных стражей, которые там бродят.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 ужасных стражей у Врат Созанна на Хиджале.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Как всегда, блестяще. Ты меня не разочаровал.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к наставнице Милве в Кузню Мольбы на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25312,'Возвращение к Шепоту Сумрака','<Вы используете Око, чтобы отдавать ограм различные приказы. Вы чувствуете внутри Ока чужую волю, пробующую вас на вкус, выискивающую ваши уязвимые места. Существо, чье присутствие вы ощущаете, исполнено ярости. Похоже, сегодня вы обзавелись очередным врагом!>$B$B<Ваше задание выполнено. Вернитесь к Ройсу Шепоту Сумрака в святилище Голдринна и расскажите ему, как все прошло.>','Вернитесь к Ройсу Шепоту Сумрака в Святилище Голдринна на горе Хиджал.','Да, что? Кто? Ты? А, ты, наверное, из тех ребят, которых я посылал за Оком Сумерек?$B$BОчень хорошо, молодец. По-моему, это ценный урок:$B$BНикогда не подчиняйся приказам огромного фиолетового шара.','Вернитесь к Ройсу Шепоту Сумрака в Святилище Голдринна на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение к Шепоту Сумрака',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Вы используете Око, чтобы отдавать ограм различные приказы. Вы чувствуете внутри Ока чужую волю, пробующую вас на вкус, выискивающую ваши уязвимые места. Существо, чье присутствие вы ощущаете, исполнено ярости. Похоже, сегодня вы обзавелись очередным врагом!>$B$B<Ваше задание выполнено. Вернитесь к Ройсу Шепоту Сумрака в святилище Голдринна и расскажите ему, как все прошло.>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь к Ройсу Шепоту Сумрака в Святилище Голдринна на горе Хиджал.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, что? Кто? Ты? А, ты, наверное, из тех ребят, которых я посылал за Оком Сумерек?$B$BОчень хорошо, молодец. По-моему, это ценный урок:$B$BНикогда не подчиняйся приказам огромного фиолетового шара.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ройсу Шепоту Сумрака в Святилище Голдринна на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25313,'Отступник','Остановись! Пожалуйста, умоляю!$B$BЯ здесь из-за девушки. Так сладко звучали ее слова... но теперь я понимаю, какое безумие за ними крылось.$B$BВозьми этот конверт. Там есть информация, которая поможет тебе подняться в глазах начальства.$B$BСтражники отвлеклись... я смогу убежать. Пожалуйста. Я не хочу умирать!','Принесите обличающее письмо повелителю стихий Ортеллу в туалет в Кузню Мольбы на Хиджале.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отступник',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Остановись! Пожалуйста, умоляю!$B$BЯ здесь из-за девушки. Так сладко звучали ее слова... но теперь я понимаю, какое безумие за ними крылось.$B$BВозьми этот конверт. Там есть информация, которая поможет тебе подняться в глазах начальства.$B$BСтражники отвлеклись... я смогу убежать. Пожалуйста. Я не хочу умирать!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите обличающее письмо повелителю стихий Ортеллу в туалет в Кузню Мольбы на Хиджале.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (25314,'Ораторское искусство для чайников','Послушай, $n. Я выяснил, зачем им нужен Джерод Песнь Теней. Огры Сумеречного Молота собираются принести его в жертву во время посвящения этого года.$B$BЯ слышал, что посвященный, которому поручили произнести речь перед жертвоприношением, это огр по имени Окрог, но знай: ты $gвторой:вторая; в списке.$B$BЕсли мы хотим освободить Джерода, то тебе нужно произнести эту речь. Не волнуйся, шпаргалки я тебе напишу. Просто подстрой Окрогу "несчастный случай", когда он покинет Совет Избранных.','Убейте Окрога, когда тот покинет Совет Избранных на Хиджале.','Вернитесь к убежищу в туалете возле Кузни Мольбы на Хиджале.','…и под "несчастным случаем" я подразумеваю, что его нужно убить.','Окрог') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ораторское искусство для чайников',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Послушай, $n. Я выяснил, зачем им нужен Джерод Песнь Теней. Огры Сумеречного Молота собираются принести его в жертву во время посвящения этого года.$B$BЯ слышал, что посвященный, которому поручили произнести речь перед жертвоприношением, это огр по имени Окрог, но знай: ты $gвторой:вторая; в списке.$B$BЕсли мы хотим освободить Джерода, то тебе нужно произнести эту речь. Не волнуйся, шпаргалки я тебе напишу. Просто подстрой Окрогу "несчастный случай", когда он покинет Совет Избранных.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Окрога, когда тот покинет Совет Избранных на Хиджале.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к убежищу в туалете возле Кузни Мольбы на Хиджале.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','…и под "несчастным случаем" я подразумеваю, что его нужно убить.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Окрог',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (25316,'Пока горит Хиджал','$n! Мы наслышаны о тебе и о твоих деяниях.$B$BКак хорошо, что ты $gпоявился:появилась; здесь в столь тревожное для всего Азерота время.$B$BПрислужники Смертокрыла напали на Хиджал и хотят вернуть Рагнароса в наш мир.$B$BАроний отнесет тебя на Хиджал, к Малфуриону. Помоги ему, чем сможешь.','Оседлайте Арония и отправляйтесь на Хиджал. По прибытии поговорите с Изерой.','<Изера, кажется, пребывает в трансе.>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пока горит Хиджал',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n! Мы наслышаны о тебе и о твоих деяниях.$B$BКак хорошо, что ты $gпоявился:появилась; здесь в столь тревожное для всего Азерота время.$B$BПрислужники Смертокрыла напали на Хиджал и хотят вернуть Рагнароса в наш мир.$B$BАроний отнесет тебя на Хиджал, к Малфуриону. Помоги ему, чем сможешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Оседлайте Арония и отправляйтесь на Хиджал. По прибытии поговорите с Изерой.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Изера, кажется, пребывает в трансе.>',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (25318,'Военные планы Сумеречного Молота') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Военные планы Сумеречного Молота',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (25320,'Захваченный разведчик','Я о тебе наслышана, $n, а также знаю о новостях, что ты $gпринес:принесла; с юга. Сейчас война застыла в равновесии.$B$BНо, боюсь, что пробуждение Повелителя Огня стало переломным моментом.$B$BМы должны попытаться как-нибудь склонить чаши весов на нашу сторону.$B$BОдного из наших разведчиков захватили в плен сектанты Сумеречного Молота. Я думаю, у нее есть ценная информация. Найди ее в лагерях Сумеречного Молота на западе.','Наконец-то прибыла помощь!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Захваченный разведчик',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я о тебе наслышана, $n, а также знаю о новостях, что ты $gпринес:принесла; с юга. Сейчас война застыла в равновесии.$B$BНо, боюсь, что пробуждение Повелителя Огня стало переломным моментом.$B$BМы должны попытаться как-нибудь склонить чаши весов на нашу сторону.$B$BОдного из наших разведчиков захватили в плен сектанты Сумеречного Молота. Я думаю, у нее есть ценная информация. Найди ее в лагерях Сумеречного Молота на западе.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Наконец-то прибыла помощь!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25321,'В плену у Сумеречного Молота','Я почти целый день разведывала вражеские тылы, когда они меня схватили.$B$BЭта атака – не то, что ты думаешь, $n.$B$BЯ тебе все объясню, но сначала давай отсюда выберемся.$B$BКлючи от клеток есть только у надзирателей.$B$BНасколько я помню, они в центре кратера.$B$BМожет, ты сможешь у одного из них заполучить ключ.','Заберите ключ у сумеречного надзирателя в Командном лагере Сумеречного Молота на горе Хиджал.','Вернитесь к разведчику Ларандии в Командный Лагерь Сумеречного Молота на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В плену у Сумеречного Молота',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я почти целый день разведывала вражеские тылы, когда они меня схватили.$B$BЭта атака – не то, что ты думаешь, $n.$B$BЯ тебе все объясню, но сначала давай отсюда выберемся.$B$BКлючи от клеток есть только у надзирателей.$B$BНасколько я помню, они в центре кратера.$B$BМожет, ты сможешь у одного из них заполучить ключ.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заберите ключ у сумеречного надзирателя в Командном лагере Сумеречного Молота на горе Хиджал.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к разведчику Ларандии в Командный Лагерь Сумеречного Молота на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25322,'Пылающие письмена','<Вы никогда не видели подобного медальона. Его руны пылают в лад с ближайшими элементалями огня.$B$BВозможно, вам стоит рассказать об этом Хамуулу Руническому Тотему.>','Поговорите с Хамуулом Руническим Тотемом на Хиджале.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пылающие письмена',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Вы никогда не видели подобного медальона. Его руны пылают в лад с ближайшими элементалями огня.$B$BВозможно, вам стоит рассказать об этом Хамуулу Руническому Тотему.>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Хамуулом Руническим Тотемом на Хиджале.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25323,'Сокрушающий пламя','Огромные элементали, осаждающие нас, по природе своей не являются единым целым.$B$BЭто слияние малых духов, связанных вместе магией сектантов Сумеречного Молота.$B$BПеределанный посох провидящего в огне даст нам достаточно сил для того, чтобы ослабить эту связь.$B$BЗаймись малыми элементалями, как только уничтожишь больших.','Убейте 30 необузданных духов огня.','Вернитесь к Малфуриону Ярости Бури, находящемуся в Тихой роще на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сокрушающий пламя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Огромные элементали, осаждающие нас, по природе своей не являются единым целым.$B$BЭто слияние малых духов, связанных вместе магией сектантов Сумеречного Молота.$B$BПеределанный посох провидящего в огне даст нам достаточно сил для того, чтобы ослабить эту связь.$B$BЗаймись малыми элементалями, как только уничтожишь больших.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 30 необузданных духов огня.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Малфуриону Ярости Бури, находящемуся в Тихой роще на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (25324,'Важный узник','Поговорите с Сайной Нагоняющей Грозу в Кельях на Хиджале.','Наверное, дракон прав. Культу Сумеречного Молота удалось сломить нашу защиту, а это наш самый опасный заключенный.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Важный узник',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Сайной Нагоняющей Грозу в Кельях на Хиджале.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Наверное, дракон прав. Культу Сумеречного Молота удалось сломить нашу защиту, а это наш самый опасный заключенный.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`endtext_loc8`) VALUES (25325,'Сквозь сон','Доставьте верховного друида Фэндрала Оленьего Шлема к Алисре, ожидающей вас у входа в Кельи на Хиджале.','Верховный друид Фэндрал Олений Шлем доставлен к Алисре') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сквозь сон',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте верховного друида Фэндрала Оленьего Шлема к Алисре, ожидающей вас у входа в Кельи на Хиджале.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Верховный друид Фэндрал Олений Шлем доставлен к Алисре',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (25326,'Блокировать вражеское отступление') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Блокировать вражеское отступление',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (25327,'Пробуждение') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пробуждение',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (25328,'Ключ в ларце, ларец... под охраной','<Кристофф поворачивает голову, пытаясь заглянуть вам в глаза.>$B$BСлушай, вытащи меня отсюда. Я уж не знаю, собираются ли они меня съесть или сделать одним из служителей Сумеречного Молота. Не исключено, что и то, и другое.$B$BОни приковали меня к этой цепи, а ключ Гар\'гол убрал в свой сундук. Убей Гар\'гола, если понадобится, но раздобудь этот ключ!$B$B<Кристофф беспомощно дергается.>','Добудьте ржавый ключ-череп из личного сундука сокровищ Гар\'гола.','<Кристофф нагибается, чтобы схватить ключ.>$B$BТы как раз вовремя!$B$B<Он выгибается, пытаясь нащупать замок у себя за спиной.>$B$B…Не поможешь?','Ключ? Ну? Где же он?','Принесите ключ Кристоффу Мэнхайму, подвешенному на крюке в схроне Гар\'гола на горе Хиджал.','Поищите сундук в огромных грязных ногах Гар\'гола.','Гар\'гол') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ключ в ларце, ларец... под охраной',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Кристофф поворачивает голову, пытаясь заглянуть вам в глаза.>$B$BСлушай, вытащи меня отсюда. Я уж не знаю, собираются ли они меня съесть или сделать одним из служителей Сумеречного Молота. Не исключено, что и то, и другое.$B$BОни приковали меня к этой цепи, а ключ Гар\'гол убрал в свой сундук. Убей Гар\'гола, если понадобится, но раздобудь этот ключ!$B$B<Кристофф беспомощно дергается.>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте ржавый ключ-череп из личного сундука сокровищ Гар\'гола.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Кристофф нагибается, чтобы схватить ключ.>$B$BТы как раз вовремя!$B$B<Он выгибается, пытаясь нащупать замок у себя за спиной.>$B$B…Не поможешь?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ключ? Ну? Где же он?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите ключ Кристоффу Мэнхайму, подвешенному на крюке в схроне Гар\'гола на горе Хиджал.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Поищите сундук в огромных грязных ногах Гар\'гола.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Гар\'гол',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25329,'Мощь Каменного Молота','Так в Сумеречном Молоте думают, что могут запросто поднять здесь собственную армию огров? Здесь, в сердце владений Орды? $B$BЧто ж, посмотрим.$B$BОгры понимают только одно: силу. Проповедь Чо\'Галла надо прервать, $n. Распахни двери Забытого города, ворвись на арену и уничтожь его помощников.','Прервите Сумеречную проповедь Чо\'Галла','Вернитесь к Орхан Огрский Клинок в крепость Каменного Молота в Фералас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мощь Каменного Молота',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Так в Сумеречном Молоте думают, что могут запросто поднять здесь собственную армию огров? Здесь, в сердце владений Орды? $B$BЧто ж, посмотрим.$B$BОгры понимают только одно: силу. Проповедь Чо\'Галла надо прервать, $n. Распахни двери Забытого города, ворвись на арену и уничтожь его помощников.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Прервите Сумеречную проповедь Чо\'Галла',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Орхан Огрский Клинок в крепость Каменного Молота в Фералас.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25330,'Ничтожество','Посмотри на этих дураков. Половина из них даже не пройдут этого испытания.$B$BОни недостойны продвижения. Но, наверное... они будут неплохими слугами.$B$BВозьми этот самоцвет и используй его силу, чтобы спасти одного из не столь многообещающих соискателей. Кого-нибудь, у кого нет шансов на удачу. Лучше того, кто уже горит.','Используйте леденящий кристалл, чтобы потушить огонь, охвативший 4 принесенных в жертву молельщиков.','Вернитесь к наставнику Каргаллу к Сумеречному ходу на Хиджале.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ничтожество',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Посмотри на этих дураков. Половина из них даже не пройдут этого испытания.$B$BОни недостойны продвижения. Но, наверное... они будут неплохими слугами.$B$BВозьми этот самоцвет и используй его силу, чтобы спасти одного из не столь многообещающих соискателей. Кого-нибудь, у кого нет шансов на удачу. Лучше того, кто уже горит.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте леденящий кристалл, чтобы потушить огонь, охвативший 4 принесенных в жертву молельщиков.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к наставнику Каргаллу к Сумеречному ходу на Хиджале.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25331,'Любимый кот бабули','Ах, да! Эвакуация...$B$BНо я не могу бросить здесь моего ненаглядного котика! Он такой рыжий, в полоску...$B$BВсе любит играть в сломанной повозке рядом с деревом к северо-востоку отсюда. Быстрее, сбегай за моим дорогим Шансом, и мы отправимся в путь.','Бабуля Валь просит вас найти кота Шанса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Любимый кот бабули',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ах, да! Эвакуация...$B$BНо я не могу бросить здесь моего ненаглядного котика! Он такой рыжий, в полоску...$B$BВсе любит играть в сломанной повозке рядом с деревом к северо-востоку отсюда. Быстрее, сбегай за моим дорогим Шансом, и мы отправимся в путь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Бабуля Валь просит вас найти кота Шанса.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25332,'Выпустите меня отсюда!','<Вы отпираете замки на цепях Кристоффа.>$B$BОтлично. Теперь давай пробиваться к выходу, я последую за тобой.$B$BЕсли мы разделимся, вернись, чтобы убедиться, что меня не поймали вторично.','Выведите Кристоффа из схрона Гар\'гола.','Кристофф… Кристофф?.. Ах да, я помню. Припоминаю, что поручил ему совершенно самоубийственную миссию.$B$BТак он выжил? Я полагаю, это значит, что задание провалено.$B$BНо, думаю, ты заслужил свою пару монет за беспокойство.','Вернитесь к Ройсу Шепоту Сумрака в Святилище Голдринна на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Выпустите меня отсюда!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Вы отпираете замки на цепях Кристоффа.>$B$BОтлично. Теперь давай пробиваться к выходу, я последую за тобой.$B$BЕсли мы разделимся, вернись, чтобы убедиться, что меня не поймали вторично.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выведите Кристоффа из схрона Гар\'гола.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Кристофф… Кристофф?.. Ах да, я помню. Припоминаю, что поручил ему совершенно самоубийственную миссию.$B$BТак он выжил? Я полагаю, это значит, что задание провалено.$B$BНо, думаю, ты заслужил свою пару монет за беспокойство.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ройсу Шепоту Сумрака в Святилище Голдринна на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25333,'Сила Часовых','Прервите Сумеречную проповедь Чо\'Галла.','С возвращением! Нам удалось дискредитировать Сумеречный Молот в глазах огров Гордунни и вытеснить сектантов из Фераласа.$B$BМы хорошо потрудились во славу Альянса! Гордись!','Вернитесь к Сильвии в башню Эстулана в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сила Часовых',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Прервите Сумеречную проповедь Чо\'Галла.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','С возвращением! Нам удалось дискредитировать Сумеречный Молот в глазах огров Гордунни и вытеснить сектантов из Фераласа.$B$BМы хорошо потрудились во славу Альянса! Гордись!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сильвии в башню Эстулана в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25334,'Смутная угроза','Чуешь, как бушуют стихии? Они желали поглотить нас и уничтожить с того самого момента, как мы сюда явились. Хорошо бы их успокоить, но для этого надо понять, что же их так взволновало.$B$BИди, присядь у костра. Обрати взгляд на пламя... Позволь духу увидеть истинную угрозу.','Поговорите с предсказателем Гадрой, чтобы войти в спиритический транс.','Поговорите с предсказателем Гадрой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Смутная угроза',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чуешь, как бушуют стихии? Они желали поглотить нас и уничтожить с того самого момента, как мы сюда явились. Хорошо бы их успокоить, но для этого надо понять, что же их так взволновало.$B$BИди, присядь у костра. Обрати взгляд на пламя... Позволь духу увидеть истинную угрозу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с предсказателем Гадрой, чтобы войти в спиритический транс.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с предсказателем Гадрой.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25335,'Натуральные ингредиенты','Для выполнения моего замысла мне нужны некоторые материалы... Будешь выполнять другие мои поручения – поищи заодно и то, что я тебя попрошу.$B$BВо-первых, расколотый ствол фераласского древня. Во-вторых, покрытые коркой минералы – эти можно добыть у горных великанов и чудесных дракончиков на западе. Кроме этого, добудь мне упругих сухожилий совухов из Внутренних земель либо гиппогрифов из Фераласа. И, наконец, мне потребуется большое количество металлических фрагментов, какие найдутся у любого из перечисленных созданий.','Принесите 2 расколотых бревна, 6 минералов, покрытых коркой, 20 кусков упругих сухожилий и 40 металлических фрагментов знахарю Узер\'и в лагерь Мохаче.','Вернитесь к знахарю Узер\'и в лагерь Мохаче, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Натуральные ингредиенты',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Для выполнения моего замысла мне нужны некоторые материалы... Будешь выполнять другие мои поручения – поищи заодно и то, что я тебя попрошу.$B$BВо-первых, расколотый ствол фераласского древня. Во-вторых, покрытые коркой минералы – эти можно добыть у горных великанов и чудесных дракончиков на западе. Кроме этого, добудь мне упругих сухожилий совухов из Внутренних земель либо гиппогрифов из Фераласа. И, наконец, мне потребуется большое количество металлических фрагментов, какие найдутся у любого из перечисленных созданий.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 2 расколотых бревна, 6 минералов, покрытых коркой, 20 кусков упругих сухожилий и 40 металлических фрагментов знахарю Узер\'и в лагерь Мохаче.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к знахарю Узер\'и в лагерь Мохаче, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25336,'Испытание сосуда','Мастер Узер\'и научил меня тайнам изготовления оружия духа, обладающего великой силой. Я объясню тебе, как оно делается, а ты дашь мне возможность попрактиковаться в мастерстве.$B$BС помощью этого сосуда ты сможешь уменьшать разных существ и помещать их внутрь него. Для начала нам понадобятся души диких зверей – медведей-сталемехов и волков-длиннозубов. Убивай их и используй сосуд уменьшения, чтобы пленить их дух прежде, чем он ускользнет.','Убейте 10 зверей – медведей-сталемехов или длиннозубов-охотников – и воспользуйтесь сосудом уменьшения, чтобы уменьшить их и пленить их дух.','Как мой учитель и говорил…$B$BДух существа, преданного насильственной смерти, может вырваться на волю и попытаться отомстить. А помещая дух в сосуд уменьшения, мы препятствуем ему вырваться на свободу. И теперь мы можем использовать его, как нам угодно!','Ну что, удалось тебе взять в плен диких зверей?','Вернитесь к Гомбане в крепость Каменного Молота, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Испытание сосуда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мастер Узер\'и научил меня тайнам изготовления оружия духа, обладающего великой силой. Я объясню тебе, как оно делается, а ты дашь мне возможность попрактиковаться в мастерстве.$B$BС помощью этого сосуда ты сможешь уменьшать разных существ и помещать их внутрь него. Для начала нам понадобятся души диких зверей – медведей-сталемехов и волков-длиннозубов. Убивай их и используй сосуд уменьшения, чтобы пленить их дух прежде, чем он ускользнет.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 зверей – медведей-сталемехов или длиннозубов-охотников – и воспользуйтесь сосудом уменьшения, чтобы уменьшить их и пленить их дух.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Как мой учитель и говорил…$B$BДух существа, преданного насильственной смерти, может вырваться на волю и попытаться отомстить. А помещая дух в сосуд уменьшения, мы препятствуем ему вырваться на свободу. И теперь мы можем использовать его, как нам угодно!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, удалось тебе взять в плен диких зверей?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гомбане в крепость Каменного Молота, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25337,'Уменьшенный гиппогриф','Следующий шаг – гиппогрифы.$B$BКак всегда говорил учитель Узер\'и, гиппогрифы долгое время были верными спутниками ночных эльфов, и дух их отличается преданностью.$B$BНе думаю, что они хватятся нескольких гиппогрифов, а если и так, меня это не волнует. Нам нужны души 10 блеклоперых гиппогрифов, обитающих в дебрях к югу отсюда.','Убейте 10 блеклоперых гиппогрифов любого вида, а затем воспользуйтесь сосудом уменьшения, чтобы уменьшить их и пленить их дух.','Учитель всегда говорил: "Если мы убьем существо и позволим его духу ускользнуть, оно может превратиться в куда более могущественное создание!". А это опасно. Спасибо за помощь в моих изысканиях.','Тебе удалось пленить гиппогрифов?','Вернитесь к Гомбане в крепость Каменного Молота, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уменьшенный гиппогриф',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Следующий шаг – гиппогрифы.$B$BКак всегда говорил учитель Узер\'и, гиппогрифы долгое время были верными спутниками ночных эльфов, и дух их отличается преданностью.$B$BНе думаю, что они хватятся нескольких гиппогрифов, а если и так, меня это не волнует. Нам нужны души 10 блеклоперых гиппогрифов, обитающих в дебрях к югу отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 блеклоперых гиппогрифов любого вида, а затем воспользуйтесь сосудом уменьшения, чтобы уменьшить их и пленить их дух.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Учитель всегда говорил: "Если мы убьем существо и позволим его духу ускользнуть, оно может превратиться в куда более могущественное создание!". А это опасно. Спасибо за помощь в моих изысканиях.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось пленить гиппогрифов?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гомбане в крепость Каменного Молота, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25338,'Уменьшенный древень','Следующей нашей добычей, $n, станут бродячие лесные великаны, живые деревья. Ночные эльфы считают древней своими союзниками в борьбе против Орды. Движения древней медлительны, но в качестве защитников они незаменимы!$B$BИ вскоре мы сможем использовать их мощь в своих целях.$B$BОтыщи 3 бродячих лесных древня, убей их и используй этот сосуд уменьшения, чтобы пленить их души!','Убейте 3 бродячих лесных древня. Используйте сосуд уменьшения, чтобы уменьшить и пленить павших древней.','Вернитесь к знахарю Узер\'и в лагерь Мохаче, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уменьшенный древень',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Следующей нашей добычей, $n, станут бродячие лесные великаны, живые деревья. Ночные эльфы считают древней своими союзниками в борьбе против Орды. Движения древней медлительны, но в качестве защитников они незаменимы!$B$BИ вскоре мы сможем использовать их мощь в своих целях.$B$BОтыщи 3 бродячих лесных древня, убей их и используй этот сосуд уменьшения, чтобы пленить их души!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 3 бродячих лесных древня. Используйте сосуд уменьшения, чтобы уменьшить и пленить павших древней.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к знахарю Узер\'и в лагерь Мохаче, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25339,'Месть стае Студеных Ключей','В свое время был я отличным охотником. Не было на всем свете такого существа, которого бы я боялся. Но потом...$B$BЯ был в лесу: сидел и точил клинок после трудной битвы, как вдруг на меня напали из засады. Меня окружила стая гарпий, и я еле-еле сумел вырваться и убраться в безопасное место.$B$BИх вопли до сих пор эхом отдаются у меня в ушах...$B$BПосле этого я стал уже не тот, что прежде. Но ненависть до сих пор клокочет внутри меня – я должен отомстить им, пусть даже через столько лет.$B$BГарпии из стаи Студеных Ключей живут к западу отсюда. Прошу, $n, отомсти за меня.','Убейте 6 гарпий и 6 призывательниц ветров из стаи Студеных Ключей.','Вернитесь к Тало Терновому Копыту в лагерь Атайа, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Месть стае Студеных Ключей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В свое время был я отличным охотником. Не было на всем свете такого существа, которого бы я боялся. Но потом...$B$BЯ был в лесу: сидел и точил клинок после трудной битвы, как вдруг на меня напали из засады. Меня окружила стая гарпий, и я еле-еле сумел вырваться и убраться в безопасное место.$B$BИх вопли до сих пор эхом отдаются у меня в ушах...$B$BПосле этого я стал уже не тот, что прежде. Но ненависть до сих пор клокочет внутри меня – я должен отомстить им, пусть даже через столько лет.$B$BГарпии из стаи Студеных Ключей живут к западу отсюда. Прошу, $n, отомсти за меня.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 6 гарпий и 6 призывательниц ветров из стаи Студеных Ключей.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тало Терновому Копыту в лагерь Атайа, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (25340,'Темное сердце','Эдана Коготь Ненависти – королева стаи гарпий Студеных Ключей; они гнездятся в руинах к западу отсюда. Такой злющей твари не сыскать: мне говорили, что даже само ее сердце сделано из хрусталя, поэтому она не испытывает никаких эмоций, кроме ненависти ко всем остальным. Тебе нужно убить Эдану и принести мне ее темное сердце.$B$BЯ слышал, что некоторые гарпии носят при себе рог; и если подуть в такой рог у камней Когтя Ненависти, что в северной части руин, то королева явится на его звук.$B$BПредставь, как она удивится, увидев, что ее ждут не сородичи, а верная смерть!','Убейте Эдану Коготь Ненависти и вырежьте ее темное сердце.','Вернитесь к Тало Терновому Копыту в лагерь Атайа, что в Фераласе.','Найдите камни Когтя Ненависти, потом протрубите в рог. Она появится.','Эдана Коготь Ненависти') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Темное сердце',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эдана Коготь Ненависти – королева стаи гарпий Студеных Ключей; они гнездятся в руинах к западу отсюда. Такой злющей твари не сыскать: мне говорили, что даже само ее сердце сделано из хрусталя, поэтому она не испытывает никаких эмоций, кроме ненависти ко всем остальным. Тебе нужно убить Эдану и принести мне ее темное сердце.$B$BЯ слышал, что некоторые гарпии носят при себе рог; и если подуть в такой рог у камней Когтя Ненависти, что в северной части руин, то королева явится на его звук.$B$BПредставь, как она удивится, увидев, что ее ждут не сородичи, а верная смерть!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Эдану Коготь Ненависти и вырежьте ее темное сердце.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тало Терновому Копыту в лагерь Атайа, что в Фераласе.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Найдите камни Когтя Ненависти, потом протрубите в рог. Она появится.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Эдана Коготь Ненависти',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25341,'Сфера Гордунни','Пока ты там $gкрушил:крушила; черепа...$B$BЯ получила несколько донесений, из которых следует, что огры угрожают не только нашим лесозаготовкам. Их чернокнижники носят с собой сферы и, возможно, черпают из них силы.$B$BЭти сферы, конечно, могут оказаться и простыми безделушками, но я хочу лично все проверить. Добудь-ка мне одну из таких сфер.','Отберите сферу Гордунни у чернокнижника из клана Гордунни.','Молодец. Дай-ка посмотреть.','Нашлась сфера?','Вернитесь к Орхан Огрский Клинок в крепость Каменного Молота в Фералас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сфера Гордунни',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пока ты там $gкрушил:крушила; черепа...$B$BЯ получила несколько донесений, из которых следует, что огры угрожают не только нашим лесозаготовкам. Их чернокнижники носят с собой сферы и, возможно, черпают из них силы.$B$BЭти сферы, конечно, могут оказаться и простыми безделушками, но я хочу лично все проверить. Добудь-ка мне одну из таких сфер.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отберите сферу Гордунни у чернокнижника из клана Гордунни.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Молодец. Дай-ка посмотреть.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Нашлась сфера?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Орхан Огрский Клинок в крепость Каменного Молота в Фералас.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (25342,'Поговорить со Свар\'джаном','Отнесите сферу Гордунни Свар\'джану в крепость Каменного Молота.','Чего ты там мне притащил? Говоришь, это было у Гордунни?$B$BОтвратительно…','Да?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поговорить со Свар\'джаном',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите сферу Гордунни Свар\'джану в крепость Каменного Молота.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Чего ты там мне притащил? Говоришь, это было у Гордунни?$B$BОтвратительно…',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25343,'Великий план','Я вижу, ты уже $gвлился:влилась; в наше общество, $n, и теперь тебе пора узнать, что наша деятельность не ограничивается проповедями и песнопениями. Полагаю, ты уже $gслышал:слышала; кое-что о нашей миссии, когда $gрешил:решила; присоединиться к нам.$B$BБлизится конец света, и те, кто не будут готовы встретить его, погибнут страшной смертью.$B$BНам был дан великий дар, возможность стать более сильными и могущественными. На восточной границе фермы есть алтарь, возле которого надзиратель Голбаз собирается провести ритуал. Дождись его, и ты узнаешь больше о нашем братстве.','Узнайте больше о планах сектантов, посетив алтарь на востоке Свинофермы.','Вернитесь к надзирательнице Джинтак на Свиноферму.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Великий план',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я вижу, ты уже $gвлился:влилась; в наше общество, $n, и теперь тебе пора узнать, что наша деятельность не ограничивается проповедями и песнопениями. Полагаю, ты уже $gслышал:слышала; кое-что о нашей миссии, когда $gрешил:решила; присоединиться к нам.$B$BБлизится конец света, и те, кто не будут готовы встретить его, погибнут страшной смертью.$B$BНам был дан великий дар, возможность стать более сильными и могущественными. На восточной границе фермы есть алтарь, возле которого надзиратель Голбаз собирается провести ритуал. Дождись его, и ты узнаешь больше о нашем братстве.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Узнайте больше о планах сектантов, посетив алтарь на востоке Свинофермы.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к надзирательнице Джинтак на Свиноферму.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25344,'Похищение огра','Гордунни никогда бы такого не сделали. Кто-то им это поставляет, от кого-то они получают такие мощные подарки, и нам надо узнать, от кого.$B$BОгры из правящего клана Гордок, что охраняют Забытый город, наверняка знают об этом больше остальных. Орхан, наверное, заставляет тебя убивать их, но мне нужен один живьем.$B$BОтнеси эту сферу назад. Она похожа на камень души, так что я ее немного... усовершенствовал. Покажи ее ослабевшему огру из клана Гордок, а когда схватишь его, тащи прямиком сюда.','Поймайте огра из клана Гордок при помощи модифицированного камня души.','Да, вон он, голубчик, внутри… Давай-ка вытащим его и зададим пару вопросов…','Вернитесь к Свар\'джану в Крепость Каменного Молота, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Похищение огра',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Гордунни никогда бы такого не сделали. Кто-то им это поставляет, от кого-то они получают такие мощные подарки, и нам надо узнать, от кого.$B$BОгры из правящего клана Гордок, что охраняют Забытый город, наверняка знают об этом больше остальных. Орхан, наверное, заставляет тебя убивать их, но мне нужен один живьем.$B$BОтнеси эту сферу назад. Она похожа на камень души, так что я ее немного... усовершенствовал. Покажи ее ослабевшему огру из клана Гордок, а когда схватишь его, тащи прямиком сюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поймайте огра из клана Гордок при помощи модифицированного камня души.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, вон он, голубчик, внутри… Давай-ка вытащим его и зададим пару вопросов…',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Свар\'джану в Крепость Каменного Молота, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25345,'Уменьшенный чудесный дракончик','$n, теперь я попрошу тебя отловить существо, которое на вид кажется довольно хилым, но дух его могуч, а это – именно то, что нам надо. Чудесные дракончики, о которых я говорю, были союзниками ночных эльфов. Нам надо поймать такого дракончика, чтобы Орда тоже могла воспользоваться силой его духа.$b$bУбей 8 летучих хамелеонов или радужных дракончиков, и плени их души. Эти существа водятся к западу отсюда.','Убейте 8 летучих хамелеонов или радужных дракончиков. Используйте сосуд уменьшения, чтобы заключить в них духи павшихчудесных дракончиков.','Вернитесь к знахарю Узер\'и в лагерь Мохаче, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уменьшенный чудесный дракончик',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, теперь я попрошу тебя отловить существо, которое на вид кажется довольно хилым, но дух его могуч, а это – именно то, что нам надо. Чудесные дракончики, о которых я говорю, были союзниками ночных эльфов. Нам надо поймать такого дракончика, чтобы Орда тоже могла воспользоваться силой его духа.$b$bУбей 8 летучих хамелеонов или радужных дракончиков, и плени их души. Эти существа водятся к западу отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 летучих хамелеонов или радужных дракончиков. Используйте сосуд уменьшения, чтобы заключить в них духи павшихчудесных дракончиков.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к знахарю Узер\'и в лагерь Мохаче, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25346,'Уменьшенный горный великан','Когда Пылающий Легион явился в мир, горные великаны спустились с гор, чтобы помогать ночным эльфам. Ты без труда обнаружишь их: они огромного роста, и когда они поблизости, земля начинает дрожать под ногами.$B$BЯ жажду подчинить себе подобную мощь! Убей 7 горных великанов и используй сосуд уменьшения, чтобы пленить их могучие души!','Убейте 7 горных великанов, а затем используйте сосуд уменьшения, чтобы уменьшить и пленить павших великанов.','Вернитесь к знахарю Узер\'и в лагерь Мохаче, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уменьшенный горный великан',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда Пылающий Легион явился в мир, горные великаны спустились с гор, чтобы помогать ночным эльфам. Ты без труда обнаружишь их: они огромного роста, и когда они поблизости, земля начинает дрожать под ногами.$B$BЯ жажду подчинить себе подобную мощь! Убей 7 горных великанов и используй сосуд уменьшения, чтобы пленить их могучие души!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 7 горных великанов, а затем используйте сосуд уменьшения, чтобы уменьшить и пленить павших великанов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к знахарю Узер\'и в лагерь Мохаче, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25347,'План вестников рока','Первая партия ловушек с элементалями готова. Тебе поручается спрятать их в Оргриммаре, а они в нужное время выпустят на волю огненных элементалей. Не волнуйся, $n, к тому времени ты будешь уже далеко от города.$B$BПостарайся не привлекать к себе лишнего внимания.$B$B<Надзиратель протягивает вам сверток с несколькими ловушками. Похоже, это именно то доказательство, которое рассчитывал получить Кровавый страж Торек. Вам надо срочно отнести сверток ему.>','Отнесите ловушки с элементалями кровавому стражу Тореку в Долину Силы Оргриммара.','Отнесите ловушки с элементалями кровавому стражу Тореку на Аллею Силы Оргриммара.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','План вестников рока',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Первая партия ловушек с элементалями готова. Тебе поручается спрятать их в Оргриммаре, а они в нужное время выпустят на волю огненных элементалей. Не волнуйся, $n, к тому времени ты будешь уже далеко от города.$B$BПостарайся не привлекать к себе лишнего внимания.$B$B<Надзиратель протягивает вам сверток с несколькими ловушками. Похоже, это именно то доказательство, которое рассчитывал получить Кровавый страж Торек. Вам надо срочно отнести сверток ему.>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите ловушки с элементалями кровавому стражу Тореку в Долину Силы Оргриммара.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите ловушки с элементалями кровавому стражу Тореку на Аллею Силы Оргриммара.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25348,'Расстроить планы','Вряд ли тебе $gодному:одной; поручили разместить эти ловушки в Оргриммаре. Мы должны найти остальные бомбы и обезвредить их прежде, чем они выпустят на волю огненных элементалей, которые спалят город дотла.$B$BТы $gзнаком:знакома; с устройством этих ловушек? Их нужно разбить прежде, чем заключенные элементали наберут силу и выберутся наружу. Не волнуйся, до того момента их будет легко победить. Боюсь только, сектанты разбросали их по всему городу.','Уничтожьте 5 ловушек с элементалями и убейте 5 бушующих духов огня.','Вернитесь к кровавому стражу Тореку на Аллею Силы Оргриммара.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Расстроить планы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вряд ли тебе $gодному:одной; поручили разместить эти ловушки в Оргриммаре. Мы должны найти остальные бомбы и обезвредить их прежде, чем они выпустят на волю огненных элементалей, которые спалят город дотла.$B$BТы $gзнаком:знакома; с устройством этих ловушек? Их нужно разбить прежде, чем заключенные элементали наберут силу и выберутся наружу. Не волнуйся, до того момента их будет легко победить. Боюсь только, сектанты разбросали их по всему городу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 5 ловушек с элементалями и убейте 5 бушующих духов огня.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к кровавому стражу Тореку на Аллею Силы Оргриммара.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25349,'Безумные сестры','Мне рассказывали о твоей битве с обезумевшими драконами, |3-6($c), и я благодарю тебя за подобную смелость... А у меня вновь дурные вести.$B$BДриады из этих лесов, хотя и были всегда на стороне ночных эльфов, и все же никогда не нападали на нас. Но теперь они чем-то заразились, озлобились и бросаются на любого, кто забредет в восточный лес.$B$BЯ боюсь за наших тамошних беженцев, $n. Прошу, останови этих сумасшедших дриад.','Убейте 7 зараженных дриад','Вернитесь к вождю Рогу Духа в лагерь Мохаче, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Безумные сестры',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне рассказывали о твоей битве с обезумевшими драконами, |3-6($c), и я благодарю тебя за подобную смелость... А у меня вновь дурные вести.$B$BДриады из этих лесов, хотя и были всегда на стороне ночных эльфов, и все же никогда не нападали на нас. Но теперь они чем-то заразились, озлобились и бросаются на любого, кто забредет в восточный лес.$B$BЯ боюсь за наших тамошних беженцев, $n. Прошу, останови этих сумасшедших дриад.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 7 зараженных дриад',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к вождю Рогу Духа в лагерь Мохаче, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (25350,'Потерявшийся ученик','Можно тебя на минутку, |3-6($c)?..$B$BОдин из моих учеников в одиночку отправился исследовать довольно опасные руины, к югу отсюда. Я предупреждала его, что это опасно, но когда же сумасшедшая молодежь слушалась старших?! Когда-то я поведала ему об амулете древних, запрятанном в руинах. Боюсь, что он отправился на поиски этого артефакта по моей вине...$B$BЭстулан запретил нам идти по его следу. Если уж ты отправляешься туда, не поищешь ли его заодно?','Найдите потерявшегося ученика в руинах Мглистой пещеры.','<Труп ученика уже успел окоченеть, тот явно умер уже довольно давно.>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Потерявшийся ученик',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Можно тебя на минутку, |3-6($c)?..$B$BОдин из моих учеников в одиночку отправился исследовать довольно опасные руины, к югу отсюда. Я предупреждала его, что это опасно, но когда же сумасшедшая молодежь слушалась старших?! Когда-то я поведала ему об амулете древних, запрятанном в руинах. Боюсь, что он отправился на поиски этого артефакта по моей вине...$B$BЭстулан запретил нам идти по его следу. Если уж ты отправляешься туда, не поищешь ли его заодно?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите потерявшегося ученика в руинах Мглистой пещеры.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Труп ученика уже успел окоченеть, тот явно умер уже довольно давно.>',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25351,'Предупредить правителей','$n, ты $gзащитил:защитила; Оргриммар от угрозы, исходящей от служителей культа Сумеречного Молота, и не $gпозволил:позволила; пролиться крови нашего народа. Но враг не смирится с этим поражением. Сомневаюсь, что Чо\'Галл так легко откажется от своих целей.$B$BГаррош Адский Крик – прославленный герой Орды, так что он поймет, как поступить. Отправляйся на Аллею Мудрости и найди его в крепости Громмаш. Сообщи ему, что наши враги уже проявили себя, и мы должны готовиться к их следующим действиям.','Поговорите с Гаррошем Адским Криком в крепости Громмаш, что в Долине Мудрости Оргриммара.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Предупредить правителей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, ты $gзащитил:защитила; Оргриммар от угрозы, исходящей от служителей культа Сумеречного Молота, и не $gпозволил:позволила; пролиться крови нашего народа. Но враг не смирится с этим поражением. Сомневаюсь, что Чо\'Галл так легко откажется от своих целей.$B$BГаррош Адский Крик – прославленный герой Орды, так что он поймет, как поступить. Отправляйся на Аллею Мудрости и найди его в крепости Громмаш. Сообщи ему, что наши враги уже проявили себя, и мы должны готовиться к их следующим действиям.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Гаррошем Адским Криком в крепости Громмаш, что в Долине Мудрости Оргриммара.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25352,'Подчистую','Ты отлично $gпотрудился:потрудилась; в схроне, $n. В твое отсутствие я молился в святилище, и в моих видениях Голдринн не оставлял тебя своим вниманием.$B$BНо мы слишком долго отсиживались в обороне. Пора нанести прямой удар по Сумеречному Молоту.$B$BЛети на Уступ Молний и прерви их операцию. Убей буревестников и чудовищ, силу которых они хотят выпустить на волю.','Убейте 8 сумеречных буревестников из культа Сумеречного Молота и 5 воющих шатунов.','Отсюда твой бой смотрелся потрясающе! Тела так и падали вниз с уступа. Какое зрелище!..','Вернитесь к Яну Дюрану в Святилище Голдринна на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подчистую',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты отлично $gпотрудился:потрудилась; в схроне, $n. В твое отсутствие я молился в святилище, и в моих видениях Голдринн не оставлял тебя своим вниманием.$B$BНо мы слишком долго отсиживались в обороне. Пора нанести прямой удар по Сумеречному Молоту.$B$BЛети на Уступ Молний и прерви их операцию. Убей буревестников и чудовищ, силу которых они хотят выпустить на волю.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 сумеречных буревестников из культа Сумеречного Молота и 5 воющих шатунов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отсюда твой бой смотрелся потрясающе! Тела так и падали вниз с уступа. Какое зрелище!..',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Яну Дюрану в Святилище Голдринна на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (25356,'К Вершине','Мы организуем лагерь для беженцев со всей Тысячи Игл на Вершине Западного Предела. Шин даст тебе моего ветрокрыла, чтобы ты спокойно туда $gдолетел:долетела;. Когда приземлишься, поговори с Канати Серое Облако.$B$BПоторопись – ради спасения жизней!','Возьмите ветрокрыла у Шина и поговорите с Канати Серое Облако на Вершине Западного Предела в Тысяче Игл.','Тебя послал Джаун? Отлично! Нам как раз нужна твоя помощь!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','К Вершине',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы организуем лагерь для беженцев со всей Тысячи Игл на Вершине Западного Предела. Шин даст тебе моего ветрокрыла, чтобы ты спокойно туда $gдолетел:долетела;. Когда приземлишься, поговори с Канати Серое Облако.$B$BПоторопись – ради спасения жизней!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возьмите ветрокрыла у Шина и поговорите с Канати Серое Облако на Вершине Западного Предела в Тысяче Игл.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебя послал Джаун? Отлично! Нам как раз нужна твоя помощь!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25357,'Выиграть время','Сегодня погибло немало хороших бойцов. Если бы не ты, наши потери были бы еще больше.$B$BПрими нашу искреннюю благодарность.$B$BШаман говорит, нам нельзя терять ни минуты. Наги прочесывают эти воды в поисках уцелевших.$B$BМы еще не готовы к сражению. Нам нужно выиграть время. Разыщи наг, которые нас преследуют, и попытайся их задержать.','Убейте 8 налетчиков Зин\'жатара.','Будем надеяться, нам удалось выиграть время...','Вернитесь к капитану Тейлору на "Морской Кортик".') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Выиграть время',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сегодня погибло немало хороших бойцов. Если бы не ты, наши потери были бы еще больше.$B$BПрими нашу искреннюю благодарность.$B$BШаман говорит, нам нельзя терять ни минуты. Наги прочесывают эти воды в поисках уцелевших.$B$BМы еще не готовы к сражению. Нам нужно выиграть время. Разыщи наг, которые нас преследуют, и попытайся их задержать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 налетчиков Зин\'жатара.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Будем надеяться, нам удалось выиграть время...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Тейлору на "Морской Кортик".',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25358,'Релаксант','Как самочувствие, говоришь?$B$BКак бы это сказать... Учитывая, что меня утащило прямо с палубы нашего судна какое-то огромное морское чудище и бросило в море... бывало и получше!$B$BНервы мои уже на пределе, честно признаться.$B$BЕсли бы ты $gсмог:смогла; притащить кое-какие припасы, которые тут кругом плавают среди обломков судов, мне, быть может, удалось бы нарыть в них что-нибудь для снятия стресса...','Мак просит вас достать 5 ящиков затонувшего груза из леса Келп’тар.','Думаю, не нужно тебе рассказывать, что происходит в этих ящиках...$B$BСовершенно верно... Брр-рожение! Держи-ка. По моему собственному особому рецепту.$B$BТаким тебя больше никто не попотчует!','Отнесите затонувший груз Маку в Пещеру контрабандистов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Релаксант',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как самочувствие, говоришь?$B$BКак бы это сказать... Учитывая, что меня утащило прямо с палубы нашего судна какое-то огромное морское чудище и бросило в море... бывало и получше!$B$BНервы мои уже на пределе, честно признаться.$B$BЕсли бы ты $gсмог:смогла; притащить кое-какие припасы, которые тут кругом плавают среди обломков судов, мне, быть может, удалось бы нарыть в них что-нибудь для снятия стресса...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Мак просит вас достать 5 ящиков затонувшего груза из леса Келп’тар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Думаю, не нужно тебе рассказывать, что происходит в этих ящиках...$B$BСовершенно верно... Брр-рожение! Держи-ка. По моему собственному особому рецепту.$B$BТаким тебя больше никто не попотчует!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите затонувший груз Маку в Пещеру контрабандистов.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25359,'Месть Тоша','Ты $gвстречался:встречалась; с Тошем в гроте Затуманенного Света, верно? Он отправился по следу улепетывающих наг в какие-то руины на востоке и теперь просит помощи.$B$BДавай, плыви в эти руины и найди Тоша как можно скорее. Если узнаешь что-нибудь о цели наг – пожалуйста, дай нам знать.','Поговорите с Тошем Приносящим Хаос в руинах храма Телсерай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Месть Тоша',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gвстречался:встречалась; с Тошем в гроте Затуманенного Света, верно? Он отправился по следу улепетывающих наг в какие-то руины на востоке и теперь просит помощи.$B$BДавай, плыви в эти руины и найди Тоша как можно скорее. Если узнаешь что-нибудь о цели наг – пожалуйста, дай нам знать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Тошем Приносящим Хаос в руинах храма Телсерай.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25360,'Негодующие крабы','Эти крабы совсем не дружелюбны. Совсем. Не. Дружелюбны.$B$BИх выводит из себя бесконечное сверление Сэма. Знаю по опыту, что Сэма остановить не получится. Значит, придется заходить с другой стороны.','Убейте 10 зеленых песчаных крабов.','Интересно, почему тут все такое гигантское? А что, это мысль: может, где-то здесь живут огромные морские гоблины.$B$BСпасибо, кстати.','Вернитесь к Фелиции на запад Котловины Серебряной Волны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Негодующие крабы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти крабы совсем не дружелюбны. Совсем. Не. Дружелюбны.$B$BИх выводит из себя бесконечное сверление Сэма. Знаю по опыту, что Сэма остановить не получится. Значит, придется заходить с другой стороны.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 зеленых песчаных крабов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Интересно, почему тут все такое гигантское? А что, это мысль: может, где-то здесь живут огромные морские гоблины.$B$BСпасибо, кстати.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фелиции на запад Котловины Серебряной Волны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25361,'Новый сверкающий плащ','Здравствуй, |3-6($c). Мы с моими товарищами отправились в Фералас, чтобы выполнить задание, которое нам дали наши командующие из Оргриммара.$B$BМоя спутница Коррин очень любит наряды, поэтому я хочу сшить ей новый плащ, украшенный легчайшими крылышками чудесных дракончиков. Не поможешь ли мне? Мне нужны великолепные крылья летучих хамелеонов, что водятся к западу от лагеря Мохаче.','Принесите 10 радужных крыльев летучих хамелеонов Кригу Головорубу в лагерь Мохаче.','Вернитесь к Кригу Головорубу в Лагерь Мохаче, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новый сверкающий плащ',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Здравствуй, |3-6($c). Мы с моими товарищами отправились в Фералас, чтобы выполнить задание, которое нам дали наши командующие из Оргриммара.$B$BМоя спутница Коррин очень любит наряды, поэтому я хочу сшить ей новый плащ, украшенный легчайшими крылышками чудесных дракончиков. Не поможешь ли мне? Мне нужны великолепные крылья летучих хамелеонов, что водятся к западу от лагеря Мохаче.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 радужных крыльев летучих хамелеонов Кригу Головорубу в лагерь Мохаче.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кригу Головорубу в Лагерь Мохаче, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25362,'Зловещее открытие','Предатели Орды и предатели своего же народа…$B$BХотя, может, не все они так плохи. По крайней мере, фляжки они делают отменные.','Вернитесь к Кригу Головорубу в Лагерь Мохаче, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зловещее открытие',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Предатели Орды и предатели своего же народа…$B$BХотя, может, не все они так плохи. По крайней мере, фляжки они делают отменные.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кригу Головорубу в Лагерь Мохаче, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`completedtext_loc8`) VALUES (25363,'О, эти гноллы... Сказать, что они отравляют нам жизнь, – ничего не сказать! Мы здесь постоянно живем под угрозой нападения! Я не знаю, всегда ли они жили в Фераласе или пришли сюда откуда-то еще, но если мы не будем противостоять им достаточно решительно, нам здесь не жить.$B$BА в последнее время гноллы совершенно озверели! Нам необходима твоя помощь, чтобы сократить их численность. Принеси мне десяток их грив, и я щедро вознагражу тебя за труды.$B$BСтупай!','Вернитесь к Хадокену Быстрому Страннику в Лагерь Мохаче, что в Фераласе.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','О, эти гноллы... Сказать, что они отравляют нам жизнь, – ничего не сказать! Мы здесь постоянно живем под угрозой нападения! Я не знаю, всегда ли они жили в Фераласе или пришли сюда откуда-то еще, но если мы не будем противостоять им достаточно решительно, нам здесь не жить.$B$BА в последнее время гноллы совершенно озверели! Нам необходима твоя помощь, чтобы сократить их численность. Принеси мне десяток их грив, и я щедро вознагражу тебя за труды.$B$BСтупай!',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хадокену Быстрому Страннику в Лагерь Мохаче, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25364,'Истребление вожаков','К несчастью, гноллы столь же живучи, сколь свирепы и тупы. Я раз за разом выбивал их из нашего лагеря, и лишь по милости нашего вождя мы не истребили их полностью.$B$BЗа долгие годы это превратилось в состязание в силе и жестокости. Когда их количество возрастает и они начинают угрожать лагерю, нужно убить самых сильных гноллов, их вожаков.$B$BЭто заставит их отступить обратно в лес и даст нам передышку – до тех пор, пока они не забудут полученный урок.','Убейте 5 вожаков стаи Древолапов','Вернитесь к Хадокену Быстрому Страннику в лагерь Мохаче, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Истребление вожаков',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','К несчастью, гноллы столь же живучи, сколь свирепы и тупы. Я раз за разом выбивал их из нашего лагеря, и лишь по милости нашего вождя мы не истребили их полностью.$B$BЗа долгие годы это превратилось в состязание в силе и жестокости. Когда их количество возрастает и они начинают угрожать лагерю, нужно убить самых сильных гноллов, их вожаков.$B$BЭто заставит их отступить обратно в лес и даст нам передышку – до тех пор, пока они не забудут полученный урок.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 5 вожаков стаи Древолапов',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хадокену Быстрому Страннику в лагерь Мохаче, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (25365,'Гноллы, конечно, умом не блещут, но в последнее время в их деятельности прослеживаются признаки тщательного планирования. Если бы удалось добыть эти планы, возможно, нам было бы проще понять, отчего они так зашевелились в последнее время.$B$BПрошу тебя, вернись в лагеря Древолапов и попытайся найти что-нибудь похожее на военные планы. Наверняка у них есть что-то в этом духе: в последнее время они действуют чересчур согласованно. Отыщи эти планы, и возвращайся ко мне.','Найдите военные планы гноллов в гноллских лагерях к югу от лагеря Мохаче.','Да, это те самые планы, которые просил отыскать Хадокен Быстрый Странник. Множество стрелок, очевидно, обозначают передвижения войск, однако большая часть этих стрелок направлена не на север, к лагерю Мохаче, а на юг.$B$BВ углу карты нарисовано нечто вроде крупного насекомого, окруженного разнообразными значками. Судя по всему, гноллов действительно донимают какие-то насекомые…') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Гноллы, конечно, умом не блещут, но в последнее время в их деятельности прослеживаются признаки тщательного планирования. Если бы удалось добыть эти планы, возможно, нам было бы проще понять, отчего они так зашевелились в последнее время.$B$BПрошу тебя, вернись в лагеря Древолапов и попытайся найти что-нибудь похожее на военные планы. Наверняка у них есть что-то в этом духе: в последнее время они действуют чересчур согласованно. Отыщи эти планы, и возвращайся ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите военные планы гноллов в гноллских лагерях к югу от лагеря Мохаче.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, это те самые планы, которые просил отыскать Хадокен Быстрый Странник. Множество стрелок, очевидно, обозначают передвижения войск, однако большая часть этих стрелок направлена не на север, к лагерю Мохаче, а на юг.$B$BВ углу карты нарисовано нечто вроде крупного насекомого, окруженного разнообразными значками. Судя по всему, гноллов действительно донимают какие-то насекомые…',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25367,'Нападение на улей Зукк\'аш','Судя по сведениям, полученным с помощью разведки, враги, теснящие гноллов с юга, – это раса насекомоподобных существ. Неизвестно, разумны ли они – но, откровенно говоря, это и неважно. Если гноллы их так боятся, что предпочитают переть на нас, значит, эти твари так же опасны, как гноллы, а может, и еще опаснее.$B$BПроникни в те места, где обитают эти насекомые, Зукк\'аш. Это место называется "Гудящая Бездна". Постарайся уменьшить их численность и доложи мне о том, что увидишь. В доказательство своих свершений принеси мне их панцири!','Принесите 20 панцирей Зукк\'аш Хадокену Быстрому Страннику в лагерь Мохаче, что в Фераласе.','Вернитесь к Хадокену Быстрому Страннику в лагерь Мохаче, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нападение на улей Зукк\'аш',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Судя по сведениям, полученным с помощью разведки, враги, теснящие гноллов с юга, – это раса насекомоподобных существ. Неизвестно, разумны ли они – но, откровенно говоря, это и неважно. Если гноллы их так боятся, что предпочитают переть на нас, значит, эти твари так же опасны, как гноллы, а может, и еще опаснее.$B$BПроникни в те места, где обитают эти насекомые, Зукк\'аш. Это место называется "Гудящая Бездна". Постарайся уменьшить их численность и доложи мне о том, что увидишь. В доказательство своих свершений принеси мне их панцири!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 20 панцирей Зукк\'аш Хадокену Быстрому Страннику в лагерь Мохаче, что в Фераласе.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хадокену Быстрому Страннику в лагерь Мохаче, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (25368,'Веринас Порочный','Победите Веринаса Порочного.','Свобода… Наконец-то! Ох, как же хорошо быть на свободе!$B$BО, видишь, да?','Вернитесь к Сенсирии в руины Мглистой пещеры в Фералас.','Разыщи дерево к северу отсюда, призови его и положи конец мучениям моего народа!','Веринас Порочный') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Веринас Порочный',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Веринаса Порочного.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Свобода… Наконец-то! Ох, как же хорошо быть на свободе!$B$BО, видишь, да?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сенсирии в руины Мглистой пещеры в Фералас.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Разыщи дерево к северу отсюда, призови его и положи конец мучениям моего народа!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Веринас Порочный',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (25369,'Жалохвост','Один из разведчиков, исследовавших Гудящую Бездну, доложил о виденном им гигантском насекомом – куда более крупном, чем все остальные замеченные им насекомые. Помимо необычных размеров, оно, по-видимому, окружено какой-то особой аурой, которой у прочих насекомых нет. Мы назвали его жалохвостом.$B$BНам хотелось бы изучить внутренности этой твари, чтобы понять, как лучше бороться с этой новой угрозой. Добудь ядовитые железы жалохвоста и принеси их мне!','Победите Жалохвоста в Гудящей Бездне и принесите его железы Хадокену Быстрому Страннику в лагерь Мохаче, что в Фераласе.','Вернитесь к Хадокену Быстрому Страннику в лагерь Мохаче, что в Фераласе.','Берегись его яда!','Жалохвост') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жалохвост',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Один из разведчиков, исследовавших Гудящую Бездну, доложил о виденном им гигантском насекомом – куда более крупном, чем все остальные замеченные им насекомые. Помимо необычных размеров, оно, по-видимому, окружено какой-то особой аурой, которой у прочих насекомых нет. Мы назвали его жалохвостом.$B$BНам хотелось бы изучить внутренности этой твари, чтобы понять, как лучше бороться с этой новой угрозой. Добудь ядовитые железы жалохвоста и принеси их мне!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Жалохвоста в Гудящей Бездне и принесите его железы Хадокену Быстрому Страннику в лагерь Мохаче, что в Фераласе.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хадокену Быстрому Страннику в лагерь Мохаче, что в Фераласе.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Берегись его яда!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Жалохвост',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (25371,'Глубоководный скакун','Если хочешь свободно передвигаться по этому лесу из водорослей, тебе понадобится надежный скакун. И я подумала о кое-чем получше морской черепахи.$B$BОтвяжи приманку от веревки – она расположена к западу отсюда. А когда появится морской конек – оседлай его.$B$BНо знай: придется постараться, чтобы его приручить.','Поговорите с Моаной Штормовое Копыто в Конце отмели в лесу Келп’тар в Вайш\'ире.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Глубоководный скакун',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если хочешь свободно передвигаться по этому лесу из водорослей, тебе понадобится надежный скакун. И я подумала о кое-чем получше морской черепахи.$B$BОтвяжи приманку от веревки – она расположена к западу отсюда. А когда появится морской конек – оседлай его.$B$BНо знай: придется постараться, чтобы его приручить.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Моаной Штормовое Копыто в Конце отмели в лесу Келп’тар в Вайш\'ире.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (25372,'Чудо в Роще Эссины','<Пальцевидные ветки Норду, прикрывавшие обгорелый бок дерева, раздвигаются, обнажая нетронутое огнем семя.>$B$BЭто Лесное cердце. Семя жизни.$B$BОтнеси его верховному друиду Хамуулу Руническому Тотему в Рощу Эссины. Тот знает, как использовать силу семени. Обещаю, дух рощи явит себя, и на пепелище прошлого зародится новая жизнь.$B$BБлагодарю тебя, |3-6($r). Мое время истекло.','Отнесите Лесное сердце Хамуулу Руническому Тотему в Рощу Эссины на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чудо в Роще Эссины',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Пальцевидные ветки Норду, прикрывавшие обгорелый бок дерева, раздвигаются, обнажая нетронутое огнем семя.>$B$BЭто Лесное cердце. Семя жизни.$B$BОтнеси его верховному друиду Хамуулу Руническому Тотему в Рощу Эссины. Тот знает, как использовать силу семени. Обещаю, дух рощи явит себя, и на пепелище прошлого зародится новая жизнь.$B$BБлагодарю тебя, |3-6($r). Мое время истекло.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите Лесное сердце Хамуулу Руническому Тотему в Рощу Эссины на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25373,'Угроза на холме','Я горжусь тем, что в Фераласе лагерь Мохаче имеет репутацию безопасного места; но все же наш лагерь окружен множеством опасностей. Недалеко отсюда, у подножия северных холмов, собираются огры Гордунни, и они намерены отвоевать свою территорию и уничтожить всю местную фауну.$B$BСюда то и дело прибывают наши братья и сестры в поисках убежища, так что я не могу позволить ограм и дальше творить бесчинства. Иди на север и разберись с ними.','Убейте 5 стражей-лекарей из клана Гордунни','Вернитесь к вождю Рогу Духа в лагерь Мохаче, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Угроза на холме',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я горжусь тем, что в Фераласе лагерь Мохаче имеет репутацию безопасного места; но все же наш лагерь окружен множеством опасностей. Недалеко отсюда, у подножия северных холмов, собираются огры Гордунни, и они намерены отвоевать свою территорию и уничтожить всю местную фауну.$B$BСюда то и дело прибывают наши братья и сестры в поисках убежища, так что я не могу позволить ограм и дальше творить бесчинства. Иди на север и разберись с ними.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 5 стражей-лекарей из клана Гордунни',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к вождю Рогу Духа в лагерь Мохаче, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (25374,'Замечен снежный человек','Убейте Большую Лапу','Вернитесь к вождю Рогу Духа в лагерь Мохаче, что в Фераласе.','Интересно, как он получил свое имя…','Большая Лапа') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Замечен снежный человек',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Большую Лапу',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к вождю Рогу Духа в лагерь Мохаче, что в Фераласе.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Интересно, как он получил свое имя…',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Большая Лапа',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25375,'Ловля звероловов','Гордунни никогда не имели обыкновения приручать животных. Если они стали этому учиться, то это повод для беспокойства. Основной угрозой для нашего лагеря был тот снежный человек, которого они поймали, но нужно разделаться еще и с самими ограми, которые сумели изловить его. Потому что если оставить их в живых, они пойдут и поймают еще одного.$B$BУбей звероловов Гордунни, и пусть эти огры знают, что мы не потерпим от них такого!','Убейте 6 звероловов Гордунни','Хорошо, хорошо. Будем надеяться, что ограм хватит ума понять наше предупреждение.','Вернитесь к вождю Рогу Духа в лагерь Мохаче, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ловля звероловов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Гордунни никогда не имели обыкновения приручать животных. Если они стали этому учиться, то это повод для беспокойства. Основной угрозой для нашего лагеря был тот снежный человек, которого они поймали, но нужно разделаться еще и с самими ограми, которые сумели изловить его. Потому что если оставить их в живых, они пойдут и поймают еще одного.$B$BУбей звероловов Гордунни, и пусть эти огры знают, что мы не потерпим от них такого!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 6 звероловов Гордунни',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо, хорошо. Будем надеяться, что ограм хватит ума понять наше предупреждение.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к вождю Рогу Духа в лагерь Мохаче, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25376,'Кобальт Гордунни','Я только прибыл сюда, в Фералас, но слышал, что у огров клана Гордунни, населяющих дикие земли, есть интересные минералы. Демон знает, что они задумали, но они ревностно защищают это добро! Они не оставляют его валяться просто так; нет, они все закапывают, чтобы ребята вроде меня не смогли ни до чего добраться.$B$BЕсли хочешь, я дам тебе свою лопату. Иди к поселению Гордунни к северу отсюда и накопай мне кобальта. Ищи голубое сияние, а потом начинай копать!','Найдите 12 образцов кобальта Гордунни.','Return to Orwin Gizzmick at Camp Mojache in Feralas.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кобальт Гордунни',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я только прибыл сюда, в Фералас, но слышал, что у огров клана Гордунни, населяющих дикие земли, есть интересные минералы. Демон знает, что они задумали, но они ревностно защищают это добро! Они не оставляют его валяться просто так; нет, они все закапывают, чтобы ребята вроде меня не смогли ни до чего добраться.$B$BЕсли хочешь, я дам тебе свою лопату. Иди к поселению Гордунни к северу отсюда и накопай мне кобальта. Ищи голубое сияние, а потом начинай копать!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите 12 образцов кобальта Гордунни.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Return to Orwin Gizzmick at Camp Mojache in Feralas.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25377,'Сокровище Орды','Неясно, что за существо нацарапало на первый взгляд совершенно беспорядочные метки на этом пергаменте, но при внимательном рассмотрении вы различаете в некоторых каракулях попытки изобразить ориентиры на местности.$B$BОсматривая морское дно, вы, кажется, узнаете некоторые отмеченные места; одно из них – у затонувшего корабля. Если ваша догадка верна, то возле этих обломков должно покоиться некое сокровище.$B$BИ вам остается только гадать, что изображает значок зловещей змееподобной фигуры на карте...','Вы должны одолеть Акашу, чтобы получить ключ, который отпирает затонувший ордынский сундук.','Вы нашли затонувший клад!$B$BВас пьянят мысли о несметных сокровищах, которые таятся в морских глубинах.','Успевший слегка заржаветь замок, вероятно, все еще работает.','Отоприте ордынский сундук с сокровищами.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сокровище Орды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Неясно, что за существо нацарапало на первый взгляд совершенно беспорядочные метки на этом пергаменте, но при внимательном рассмотрении вы различаете в некоторых каракулях попытки изобразить ориентиры на местности.$B$BОсматривая морское дно, вы, кажется, узнаете некоторые отмеченные места; одно из них – у затонувшего корабля. Если ваша догадка верна, то возле этих обломков должно покоиться некое сокровище.$B$BИ вам остается только гадать, что изображает значок зловещей змееподобной фигуры на карте...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вы должны одолеть Акашу, чтобы получить ключ, который отпирает затонувший ордынский сундук.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы нашли затонувший клад!$B$BВас пьянят мысли о несметных сокровищах, которые таятся в морских глубинах.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Успевший слегка заржаветь замок, вероятно, все еще работает.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отоприте ордынский сундук с сокровищами.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25378,'Зов Исондры','Драконы природы... Услышь ее зов, $n. Не мешкай. Если она просит твоей помощи, то это и великая честь, и знак величайшей опасности.$B$BМесто, о котором она говорила, называется Изумрудная вершина. От главной дороги отходит тропа: она идет через Низинные чащобы на высокогорное каменное плато. На его вершине ты найдешь небольшое святилище.$B$BСудьба всего Фераласа зависит от тебя. Да хранит тебя Мать-Земля.','Поговорите с Исондрой на Изумрудной вершине в Низинных чащобах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зов Исондры',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Драконы природы... Услышь ее зов, $n. Не мешкай. Если она просит твоей помощи, то это и великая честь, и знак величайшей опасности.$B$BМесто, о котором она говорила, называется Изумрудная вершина. От главной дороги отходит тропа: она идет через Низинные чащобы на высокогорное каменное плато. На его вершине ты найдешь небольшое святилище.$B$BСудьба всего Фераласа зависит от тебя. Да хранит тебя Мать-Земля.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Исондрой на Изумрудной вершине в Низинных чащобах.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (25379,'Падение Таэрара','Эмерисс и Летон ушли. Теперь остались только мы. Я не могу больше прятаться. Все мои деяния в составе того племени... все причиненные мною страдания... за все придется расплатиться, сегодня же.$B$BУ меня еще мало сил, $n. Даже если попытаюсь, мне не принять моей истинной формы. Но я все равно пойду с тобой на битву.$B$BКак только ты подготовишься, я призову к нам Таэрара. Думаю, он не устоит перед искушением принести мне еще больше мучений.','Победите Таэрара.','Таэрар побежден','Поговорите с Исондрой.','Таэрар, брат мой…','Таэрар') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Падение Таэрара',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эмерисс и Летон ушли. Теперь остались только мы. Я не могу больше прятаться. Все мои деяния в составе того племени... все причиненные мною страдания... за все придется расплатиться, сегодня же.$B$BУ меня еще мало сил, $n. Даже если попытаюсь, мне не принять моей истинной формы. Но я все равно пойду с тобой на битву.$B$BКак только ты подготовишься, я призову к нам Таэрара. Думаю, он не устоит перед искушением принести мне еще больше мучений.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Таэрара.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Таэрар побежден',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Исондрой.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Таэрар, брат мой…',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Таэрар',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25380,'Несущие слово','Добро пожаловать на ферму, $n. У нас здесь общественное хозяйство – кто-то ухаживает за животными, кто-то занят на стройке, а остальные читают проповеди и разносят наше учение по свету. Думаю, ты тоже можешь начать помогать нашему делу.$B$BВозьми этот плакат – на нем перечислены наши основные постулаты. Надень его и посети восточную и западную башни дирижаблей в Оргриммаре, а также городскую площадь Колючего Холма, что к югу отсюда.','Надев на себя Послание о Судном дне, посетите восточную и западную башни дирижаблей в Оргриммаре, а также городскую площадь Колючего Холма.','Вернитесь к надзирательнице Джинтак на Свиноферму.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Несущие слово',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Добро пожаловать на ферму, $n. У нас здесь общественное хозяйство – кто-то ухаживает за животными, кто-то занят на стройке, а остальные читают проповеди и разносят наше учение по свету. Думаю, ты тоже можешь начать помогать нашему делу.$B$BВозьми этот плакат – на нем перечислены наши основные постулаты. Надень его и посети восточную и западную башни дирижаблей в Оргриммаре, а также городскую площадь Колючего Холма, что к югу отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Надев на себя Послание о Судном дне, посетите восточную и западную башни дирижаблей в Оргриммаре, а также городскую площадь Колючего Холма.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к надзирательнице Джинтак на Свиноферму.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25381,'Потушить огонь любой ценой','Огненная буря, бушующая впереди, – это передовая линия, на которой наши войска сражаются с армиями Повелителя огня. Затуши бушующие огненные вихри до того, как они поглотят Рощу Эссины и лишат нас всякой надежды когда-нибудь вернуть эту гору!','Уничтожьте 10 бушующих огненных вихрей.','Вернитесь к Лайне Ночное Небо, которая находится у Рощи Эссины на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Потушить огонь любой ценой',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Огненная буря, бушующая впереди, – это передовая линия, на которой наши войска сражаются с армиями Повелителя огня. Затуши бушующие огненные вихри до того, как они поглотят Рощу Эссины и лишат нас всякой надежды когда-нибудь вернуть эту гору!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 10 бушующих огненных вихрей.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лайне Ночное Небо, которая находится у Рощи Эссины на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25382,'Прервать ритуалы','Огни, горящие впереди, – это неукрощенные элементали огня в своей первозданной форме. Я ни разу не видела, чтобы они покидали свое царство стихий. Лишь самые искусные призыватели могли заставить их появиться тут.$B$B$n, отправляйся в Пекло и отыщи там лордов Преисподней из культа Сумеречного Молота. Полагаю, что в этот самый момент они призывают все новых элементалей. Заставь их замолчать для нашего общего блага!','Убейте 6 лордов Преисподней из культа Сумеречного Молота.','Они мертвы? Чудесно!$B$BОднако нам предстоит еще столько всего сделать... потушить костры, исцелить землю...$B$BНадеюсь, ты будешь рядом и поможешь нам вернуть Хиджал!','Вернитесь к Лайне Ночное Небо, стоящей перед Рощей Эссины на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прервать ритуалы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Огни, горящие впереди, – это неукрощенные элементали огня в своей первозданной форме. Я ни разу не видела, чтобы они покидали свое царство стихий. Лишь самые искусные призыватели могли заставить их появиться тут.$B$B$n, отправляйся в Пекло и отыщи там лордов Преисподней из культа Сумеречного Молота. Полагаю, что в этот самый момент они призывают все новых элементалей. Заставь их замолчать для нашего общего блага!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 6 лордов Преисподней из культа Сумеречного Молота.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Они мертвы? Чудесно!$B$BОднако нам предстоит еще столько всего сделать... потушить костры, исцелить землю...$B$BНадеюсь, ты будешь рядом и поможешь нам вернуть Хиджал!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лайне Ночное Небо, стоящей перед Рощей Эссины на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25383,'Прощание Исондры','Теперь я одна.$B$BДаже если я останусь в этом мире, я не смогу присоединиться к зеленым драконам. Но эта победа дала мне надежду. Быть может, со временем я обрету покой и стану вести простую жизнь среди смертных.$B$BА тебе нужно возвращаться к своим. Скажи им, что с драконами ночных кошмаров покончено и что они больше не будут угрожать этим землям.','Поговорите с вождем Рогом Духа в лагере Мохаче.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прощание Исондры',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь я одна.$B$BДаже если я останусь в этом мире, я не смогу присоединиться к зеленым драконам. Но эта победа дала мне надежду. Быть может, со временем я обрету покой и стану вести простую жизнь среди смертных.$B$BА тебе нужно возвращаться к своим. Скажи им, что с драконами ночных кошмаров покончено и что они больше не будут угрожать этим землям.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с вождем Рогом Духа в лагере Мохаче.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25384,'Сырье-мое','Благодарю тебя, |3-6($c). Мы обязаны тебе жизнью.$B$BНо на поверхность придется прорываться с боем. Стало быть, мне понадобится какое-нибудь оружие и броня.$B$BДо твоего появления я видел, как одного солдата сожрала косатка.$B$BБьюсь об заклад – вспоров брюхо парочке этих рыбин, ты найдешь прорву металлолома, из которого я сумею что-нибудь соорудить.$B$BЕсли не хочешь $gсам:сама; за ними гоняться, косаток можно приманить чьими-нибудь потрохами...','Самир просит принести ему 3 куска металлолома из желудка разъяренных косаток, обитающих в лесу Келп’тар.$B$BКосатку можно приманить потрохами клешневиков.','Вернитесь к Самиру в Пещеру контрабандистов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сырье-мое',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Благодарю тебя, |3-6($c). Мы обязаны тебе жизнью.$B$BНо на поверхность придется прорываться с боем. Стало быть, мне понадобится какое-нибудь оружие и броня.$B$BДо твоего появления я видел, как одного солдата сожрала косатка.$B$BБьюсь об заклад – вспоров брюхо парочке этих рыбин, ты найдешь прорву металлолома, из которого я сумею что-нибудь соорудить.$B$BЕсли не хочешь $gсам:сама; за ними гоняться, косаток можно приманить чьими-нибудь потрохами...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Самир просит принести ему 3 куска металлолома из желудка разъяренных косаток, обитающих в лесу Келп’тар.$B$BКосатку можно приманить потрохами клешневиков.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Самиру в Пещеру контрабандистов.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25385,'Спасение зверушек','Помоги нам, |3-6($c)! Лес охвачен огнем, и дикие звери оказались в ловушке. Они не способны защитить себя при помощи маленьких зубок и мягких лапок. Они такие милые и пушистые!$B$BУ них маленькие влажные носики!$B$BЕсли ты им не поможешь... Даже не хочу об этом думать.$B$B<Она закрывает лицо руками.>$B$BПрочь, мрачные мысли!','Идите в Пекло и спасите 10 растерянных кроликов или перепуганных белок.','Отнесите перепуганных животных Милуне в Рощу Эссины на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спасение зверушек',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Помоги нам, |3-6($c)! Лес охвачен огнем, и дикие звери оказались в ловушке. Они не способны защитить себя при помощи маленьких зубок и мягких лапок. Они такие милые и пушистые!$B$BУ них маленькие влажные носики!$B$BЕсли ты им не поможешь... Даже не хочу об этом думать.$B$B<Она закрывает лицо руками.>$B$BПрочь, мрачные мысли!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Идите в Пекло и спасите 10 растерянных кроликов или перепуганных белок.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите перепуганных животных Милуне в Рощу Эссины на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (25386,'В крепость Каменного Молота','Нужно сообщить о том, что произошло здесь, $n. К югу отсюда находится крепость Каменного Молота. Там наши союзники собрали несколько ордынских огров, чтобы заставить их сражаться с теми, кто разоряет эти леса.$B$BПоговори с Орхан Огрским Клинком. Она – местный лидер клана Каменного Молота, и ей непременно нужно доложить о случившемся. И осторожнее: как знать, может, еще остались незачищенные места...','Поговорите с Орхан Огрским Клинком в крепости Каменного Молота.','Так ты, стало быть, меряешься силами с драконами?$B$BЭто хорошо. Нам как раз нужны те, кто может постоять за себя. Ну так как, будешь сражаться за Орду?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В крепость Каменного Молота',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нужно сообщить о том, что произошло здесь, $n. К югу отсюда находится крепость Каменного Молота. Там наши союзники собрали несколько ордынских огров, чтобы заставить их сражаться с теми, кто разоряет эти леса.$B$BПоговори с Орхан Огрским Клинком. Она – местный лидер клана Каменного Молота, и ей непременно нужно доложить о случившемся. И осторожнее: как знать, может, еще остались незачищенные места...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Орхан Огрским Клинком в крепости Каменного Молота.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так ты, стало быть, меряешься силами с драконами?$B$BЭто хорошо. Нам как раз нужны те, кто может постоять за себя. Ну так как, будешь сражаться за Орду?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25387,'В лагерь Мохаче','Твоя помощь неоценима, $n. Теперь, когда Сумеречный Молот посрамлен, а Гордунни разбиты и зализывают раны, мы можем начать подготовку к настоящей битве с Альянсом на этой земле.$B$BЗдесь кишмя кишат ночные эльфы, и для того чтобы нам собрать армию им под стать, потребуется много времени. Я отправляю тебя в лагерь Мохаче, это к востоку отсюда. У них там полно своих проблем, а мы сейчас не можем уступить ни клочка ордынской территории.$B$BЛок-тар!','Поговорите с вождем Рогом Духа в лагере Мохаче.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В лагерь Мохаче',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Твоя помощь неоценима, $n. Теперь, когда Сумеречный Молот посрамлен, а Гордунни разбиты и зализывают раны, мы можем начать подготовку к настоящей битве с Альянсом на этой земле.$B$BЗдесь кишмя кишат ночные эльфы, и для того чтобы нам собрать армию им под стать, потребуется много времени. Я отправляю тебя в лагерь Мохаче, это к востоку отсюда. У них там полно своих проблем, а мы сейчас не можем уступить ни клочка ордынской территории.$B$BЛок-тар!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с вождем Рогом Духа в лагере Мохаче.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25388,'Ящик крабового мяса','Этот ящик с наклейкой "Крабовое мясо", должно быть, из трюма недавно потопленного грузового корабля.$B$BАдарра несказанно обрадуется такой находке, учитывая, какие невзгоды ей пришлось пережить.','Отнесите ящик крабового мяса Адарре в Пещеру контрабандистов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ящик крабового мяса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этот ящик с наклейкой "Крабовое мясо", должно быть, из трюма недавно потопленного грузового корабля.$B$BАдарра несказанно обрадуется такой находке, учитывая, какие невзгоды ей пришлось пережить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите ящик крабового мяса Адарре в Пещеру контрабандистов.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) VALUES (25388,'Что там у тебя, Гнобс?') ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что там у тебя, Гнобс?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25389,'Пристрастие к хвостам','Неизвестно, когда мы выберемся на поверхность, а я, по правде говоря, уже проголодалась.$B$BВообще я не капризная, но к морепродуктам чрезвычайно придирчива.$B$BЕсли тебе случайно попадутся лобстеры, с радостью заплачу монетку-другую за их хвосты.','Адарра просит вас принести ей 4 хвоста щелкуна.','Вот это да!$B$BСамые большие и самые сочные хвосты из всех, что мне доводилось видеть!','Вернитесь к Адарре в Пещеру контрабандистов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пристрастие к хвостам',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Неизвестно, когда мы выберемся на поверхность, а я, по правде говоря, уже проголодалась.$B$BВообще я не капризная, но к морепродуктам чрезвычайно придирчива.$B$BЕсли тебе случайно попадутся лобстеры, с радостью заплачу монетку-другую за их хвосты.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Адарра просит вас принести ей 4 хвоста щелкуна.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот это да!$B$BСамые большие и самые сочные хвосты из всех, что мне доводилось видеть!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Адарре в Пещеру контрабандистов.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25390,'Бриллианты – лучшие друзья девушек','Давай-ка начистоту. Я не новичок в амурных делах, $n.$B$BИ если что и поняла за свою жизнь, так это то, что вещественные доказательства любви куда долговечнее, чем пламя страсти.$B$BОт обожателей мне досталось немало даров: камни, кольца, ожерелья, много чего еще, и я всегда ношу их с собой, куда бы ни отправилась.$B$BТочнее, носила...$B$BКогда меня смыло с корабля, все мои драгоценности попадали в воду. Помоги мне их вернуть – обещаю, что достойно отблагодарю.','Адарра просит вас разыскать 6 драгоценностей Адарры.','Вернитесь к Адарре в Пещеру контрабандистов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бриллианты – лучшие друзья девушек',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Давай-ка начистоту. Я не новичок в амурных делах, $n.$B$BИ если что и поняла за свою жизнь, так это то, что вещественные доказательства любви куда долговечнее, чем пламя страсти.$B$BОт обожателей мне досталось немало даров: камни, кольца, ожерелья, много чего еще, и я всегда ношу их с собой, куда бы ни отправилась.$B$BТочнее, носила...$B$BКогда меня смыло с корабля, все мои драгоценности попадали в воду. Помоги мне их вернуть – обещаю, что достойно отблагодарю.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Адарра просит вас разыскать 6 драгоценностей Адарры.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Адарре в Пещеру контрабандистов.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (25390,'Вот они, родные мои! Я думала, вы навсегда меня покинули...$B$BВот, возьми, Гнобс. Надеюсь, это достойная плата.','Ну что, $R?$B$BТы нашел мои драгоценности?') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот они, родные мои! Я думала, вы навсегда меня покинули...$B$BВот, возьми, Гнобс. Надеюсь, это достойная плата.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, $R?$B$BТы нашел мои драгоценности?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25391,'Оружие духа','Вселить дух животного в оружие – процесс непростой! Теперь, когда у меня есть все необходимые материалы и души пойманных тобой созданий, я могу приступить к делу. Погоди немного, я скоро вернусь.','Подождите, пока знахарь Узер\'и готовит оружие.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оружие духа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вселить дух животного в оружие – процесс непростой! Теперь, когда у меня есть все необходимые материалы и души пойманных тобой созданий, я могу приступить к делу. Погоди немного, я скоро вернусь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Подождите, пока знахарь Узер\'и готовит оружие.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25392,'Спасение оленей','Ты говоришь по-оленьи? Нос подскажет.$B$B<Она указывает на свой нос.>$B$BОни сбежали от пожаров, но их оленята все еще не могут выбраться из огненной западни!$B$BВозвращайся в Пекло и выведи трех раненых оленят к их мамам, которые стоят рядом со мной.$B$BУмоляю, спаси детенышей, или я посмотрю на тебя большими жалобными глазами!$B$B<Ее глаза становятся большими и влажными.>','Спасите трех раненых оленят из Пекла и сопроводите их к Милуне в Рощу Эссины.','Ура! Счастливые маленькие оленята!$B$BТеперь у них есть будущее.$B$BТы друг животных!','Поговорите с Милуной в Роще Эссины на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спасение оленей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты говоришь по-оленьи? Нос подскажет.$B$B<Она указывает на свой нос.>$B$BОни сбежали от пожаров, но их оленята все еще не могут выбраться из огненной западни!$B$BВозвращайся в Пекло и выведи трех раненых оленят к их мамам, которые стоят рядом со мной.$B$BУмоляю, спаси детенышей, или я посмотрю на тебя большими жалобными глазами!$B$B<Ее глаза становятся большими и влажными.>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Спасите трех раненых оленят из Пекла и сопроводите их к Милуне в Рощу Эссины.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ура! Счастливые маленькие оленята!$B$BТеперь у них есть будущее.$B$BТы друг животных!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Милуной в Роще Эссины на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25393,'Операция "Гномреган"','Через мгновение начнется многофазовая атака на Гномреган, и мы призовем Анжинера Термоштепселя к ответу за его злодеяния! Слишком долго он пировал на руинах нашего возлюбленного дома, оскверненного и загрязненного его армией. $B$BСкоро, очень скоро пробьет наш час! Готовься, рекрут, ибо схватка будет жестокой.','Помогите королю Меггакруту при осаде Гномрегана.','Поговорите с королем Меггакрутом в Городе Механиков.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Операция "Гномреган"',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Через мгновение начнется многофазовая атака на Гномреган, и мы призовем Анжинера Термоштепселя к ответу за его злодеяния! Слишком долго он пировал на руинах нашего возлюбленного дома, оскверненного и загрязненного его армией. $B$BСкоро, очень скоро пробьет наш час! Готовься, рекрут, ибо схватка будет жестокой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Помогите королю Меггакруту при осаде Гномрегана.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с королем Меггакрутом в Городе Механиков.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25394,'Не просто болезнь','К северу от дороги я нашел выводок дракончиков, пораженных той же хворью. Зеленые драконы являют собой живое воплощение природы, и то, что их также затронула эта болезнь, весьма пугает.$B$BЛюбой ценой мы должны прекратить распространение инфекции. Убей зараженных дракончиков и возвращайся сюда, $n.','Убейте 10 зараженных дракончиков.','Меня крайне беспокоят темпы распространения этой болезни. Такое уже случалось…','Вернитесь к Теларону Полету Ветра в Покои Дремлющего в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Не просто болезнь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','К северу от дороги я нашел выводок дракончиков, пораженных той же хворью. Зеленые драконы являют собой живое воплощение природы, и то, что их также затронула эта болезнь, весьма пугает.$B$BЛюбой ценой мы должны прекратить распространение инфекции. Убей зараженных дракончиков и возвращайся сюда, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 зараженных дракончиков.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Меня крайне беспокоят темпы распространения этой болезни. Такое уже случалось…',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Теларону Полету Ветра в Покои Дремлющего в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25396,'Каменные слезы','Как ты уже знаешь, зеленый дракон Исондра считает, что слезы земли могут запечатать портал, сквозь который проникает скверна.$B$BПохоже, она говорит правду; на поляне к западу отсюда я видел смятенных горных великанов. Их слезы падали на землю сияющими кристаллами.$B$BПохоже, именно об этих слезах и говорила Исондра. Мы должны собрать их.','Соберите 7 каменных слез.','Горные великаны – верные союзники нашей расы. Мы должны остановить эту эпидемию прежде, чем она унесет сотни жизней.','Слезы можно найти среди скал, из которых и появились великаны. Посмотри возле вон тех каменных монолитов.','Вернитесь к Теларону Полету Ветра в Покои Дремлющего в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Каменные слезы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как ты уже знаешь, зеленый дракон Исондра считает, что слезы земли могут запечатать портал, сквозь который проникает скверна.$B$BПохоже, она говорит правду; на поляне к западу отсюда я видел смятенных горных великанов. Их слезы падали на землю сияющими кристаллами.$B$BПохоже, именно об этих слезах и говорила Исондра. Мы должны собрать их.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 7 каменных слез.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Горные великаны – верные союзники нашей расы. Мы должны остановить эту эпидемию прежде, чем она унесет сотни жизней.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Слезы можно найти среди скал, из которых и появились великаны. Посмотри возле вон тех каменных монолитов.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Теларону Полету Ветра в Покои Дремлющего в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25397,'Оскверненная земля','Скальные великаны, обитающие в Фераласе, – дети самой земли, $n. Когда на земле царит мир, они верные стражи и лучшие защитники.$B$BНо после того как этот лес затронула скверна, великаны также попали под ее влияние.$B$BПораженные порчей, они обратились против всего живого: деревьев, зверей и даже самих скал, из которых они вышли.$B$BБудь $gосторожен:осторожна;. Если на твоем пути встретится пораженный порчей великан, убей его, этим ты спасешь множество невинных жизней.','Убейте 6 зараженных скальных великанов.','Вернитесь к Теларону Полету Ветра в Покои Дремлющего в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оскверненная земля',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Скальные великаны, обитающие в Фераласе, – дети самой земли, $n. Когда на земле царит мир, они верные стражи и лучшие защитники.$B$BНо после того как этот лес затронула скверна, великаны также попали под ее влияние.$B$BПораженные порчей, они обратились против всего живого: деревьев, зверей и даже самих скал, из которых они вышли.$B$BБудь $gосторожен:осторожна;. Если на твоем пути встретится пораженный порчей великан, убей его, этим ты спасешь множество невинных жизней.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 6 зараженных скальных великанов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Теларону Полету Ветра в Покои Дремлющего в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25398,'Запечатанный сон','Готово. Вот, $n, – это воплощенная сущность самой природы, благословленная волей Исондры.$B$BК северу отсюда на том берегу реки расположены Сонные Ветви. Там стоит великое древо, самое высокое и сильное в Фераласе, потомок самого Древа Жизни. В его корнях находится портал в Изумрудный Сон, и именно его тебе предстоит запечатать.$B$BПортал надежно охраняют, но, я надеюсь, у тебя хватит храбрости пробраться туда.','Используйте слезу Исондры, чтобы запечатать портал в Сонных Ветвях.','Мы спасены благодаря твоей храбрости! Изумрудный кошмар исчез с лица этой земли.$B$BНо меня беспокоит судьба дракона Таэрара… Дело еще не окончено. Я не могу позволить себе расслабиться.','Вернитесь к Теларону Полету Ветра в Покои Дремлющего в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Запечатанный сон',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Готово. Вот, $n, – это воплощенная сущность самой природы, благословленная волей Исондры.$B$BК северу отсюда на том берегу реки расположены Сонные Ветви. Там стоит великое древо, самое высокое и сильное в Фераласе, потомок самого Древа Жизни. В его корнях находится портал в Изумрудный Сон, и именно его тебе предстоит запечатать.$B$BПортал надежно охраняют, но, я надеюсь, у тебя хватит храбрости пробраться туда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте слезу Исондры, чтобы запечатать портал в Сонных Ветвях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мы спасены благодаря твоей храбрости! Изумрудный кошмар исчез с лица этой земли.$B$BНо меня беспокоит судьба дракона Таэрара… Дело еще не окончено. Я не могу позволить себе расслабиться.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Теларону Полету Ветра в Покои Дремлющего в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25399,'Силы клана Гребня Ненависти','Клан Гребня Ненависти бьется жестоко. Их предводитель – главная цель, но и простых наг нужно перебить как можно больше.$B$BИди вперед, встретимся на поле битвы. Никакой пощады врагу!','Убейте 10 наг из клана Гребня Ненависти.','Вернитесь к Шандрисе Оперенной Луне в крепость Оперенной Луны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Силы клана Гребня Ненависти',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Клан Гребня Ненависти бьется жестоко. Их предводитель – главная цель, но и простых наг нужно перебить как можно больше.$B$BИди вперед, встретимся на поле битвы. Никакой пощады врагу!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 наг из клана Гребня Ненависти.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Шандрисе Оперенной Луне в крепость Оперенной Луны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (25399,'Твоя доблесть упомянута в моих донесениях, Алейчанин. Я с похвалой отзываюсь о тебе.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Твоя доблесть упомянута в моих донесениях, Алейчанин. Я с похвалой отзываюсь о тебе.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25400,'Угроза Гордунни','Высокорожденный Эстулан живет в этой башне затворником и особо с ним не пообщаешься. Но, так или иначе, он рассказал мне, что в руинах в Высокогорных дебрях к югу отсюда полным-полно огров Гордунни.$B$BОгры – не просто очередная угроза: они уничтожают все и вся вокруг себя. Эстулан особо предупредил меня, что если в руки Гордунни попадут какие-нибудь артефакты высокорожденных, брошенные среди руин, те способны натворить страшных дел.$B$BОтправляйся на юг, $n, и убей всех огров Гордунни на своем пути!','Убейте 16 огров клана Гордунни в Высокогорных дебрях.','Вернитесь к Сильвии в башню Эстулана в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Угроза Гордунни',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Высокорожденный Эстулан живет в этой башне затворником и особо с ним не пообщаешься. Но, так или иначе, он рассказал мне, что в руинах в Высокогорных дебрях к югу отсюда полным-полно огров Гордунни.$B$BОгры – не просто очередная угроза: они уничтожают все и вся вокруг себя. Эстулан особо предупредил меня, что если в руки Гордунни попадут какие-нибудь артефакты высокорожденных, брошенные среди руин, те способны натворить страшных дел.$B$BОтправляйся на юг, $n, и убей всех огров Гордунни на своем пути!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 16 огров клана Гордунни в Высокогорных дебрях.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сильвии в башню Эстулана в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (25400,'Похоже, их там больше, чем мы рассчитывали! Спасибо тебе, Фоулар.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Похоже, их там больше, чем мы рассчитывали! Спасибо тебе, Фоулар.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25401,'Сфера Гордунни','Отберите сферу Гордунни у чернокнижника из клана Гордунни.','Ну-ка, что тут у нас?','Ты добыл сферу?','Вернитесь к Сильвии в башню Эстулана в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сфера Гордунни',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отберите сферу Гордунни у чернокнижника из клана Гордунни.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну-ка, что тут у нас?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты добыл сферу?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сильвии в башню Эстулана в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (25402,'Исследование Эстулана','Он прав. Мне не довелось тесно общаться с ночными эльфами, но могу тебе сказать: эти письмена не похожи на привычные для калдорай...$B$BЭстулан должен это увидеть. Отнеси это ему наверх. Он не особо жалует гостей, но не бойся: стоит ему увидеть сферу, и он поймет, что это очень важно.','Отнесите сферу Гордунни Эстулану.','А-а-а, это та сфера, о которой я говорил, это вполне простительный повод для того, чтобы беспокоить меня.','Что это у тебя?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Исследование Эстулана',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Он прав. Мне не довелось тесно общаться с ночными эльфами, но могу тебе сказать: эти письмена не похожи на привычные для калдорай...$B$BЭстулан должен это увидеть. Отнеси это ему наверх. Он не особо жалует гостей, но не бойся: стоит ему увидеть сферу, и он поймет, что это очень важно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите сферу Гордунни Эстулану.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А-а-а, это та сфера, о которой я говорил, это вполне простительный повод для того, чтобы беспокоить меня.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что это у тебя?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25403,'Похищение огра','Используйте модифицированный камень души, чтобы захватить огра из клана Гордок.','Так-так, вот и он. И теперь мне придется вынести муки беседы с ним.','Вернитесь к Эстулану в башню Эстулана, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Похищение огра',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте модифицированный камень души, чтобы захватить огра из клана Гордок.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так-так, вот и он. И теперь мне придется вынести муки беседы с ним.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Эстулану в башню Эстулана, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25404,'Кто не против нас...','К югу отсюда находится одиноко стоящая Башня Покаяния Чернорога. Там заточен демон по имени Тирий Чернорог.$B$BТы, должно быть, думаешь, что я сошла с ума, посылая тебя к врагу за помощью, но когда-то Чернорог был простым смертным. Так что он вряд ли желает победы культу Сумеречного Молота. $B$BПоговори с Чернорогом и попробуй убедить его оказать нам помощь в борьбе. Он еще может спасти свою душу.$B$B...только не выпускай его на свободу!','Поговорите с Тирием Чернорогом и убеди его оказать помощь в борьбе с культом Сумеречного Молота.','Поговорите с Тирием Чернорогом у Башни Покаяния Чернорога на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кто не против нас...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','К югу отсюда находится одиноко стоящая Башня Покаяния Чернорога. Там заточен демон по имени Тирий Чернорог.$B$BТы, должно быть, думаешь, что я сошла с ума, посылая тебя к врагу за помощью, но когда-то Чернорог был простым смертным. Так что он вряд ли желает победы культу Сумеречного Молота. $B$BПоговори с Чернорогом и попробуй убедить его оказать нам помощь в борьбе. Он еще может спасти свою душу.$B$B...только не выпускай его на свободу!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Тирием Чернорогом и убеди его оказать помощь в борьбе с культом Сумеречного Молота.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Тирием Чернорогом у Башни Покаяния Чернорога на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25405,'Отдохновение для утомленных','Очень хорошо, |3-6($r), но предстоит еще многое сделать, а силы мои на исходе.$B$BЯ потратил очень много энергии на то, чтобы отправить Служителям Земли сигнал с просьбой о помощи.$B$BЧтобы от меня и дальше был какой-то толк, мне необходим отдых.$B$BПоговори с главным тех, кого ты $gспас:спасла;, и постарайся сделать все от тебя зависящее, чтобы помочь им подготовиться к бою.$B$BНаги прочесывают воды, разыскивая нас. Пройдет немного времени – и они вернутся c подмогой.','Побеседуйте с капитаном Тейлором.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отдохновение для утомленных',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Очень хорошо, |3-6($r), но предстоит еще многое сделать, а силы мои на исходе.$B$BЯ потратил очень много энергии на то, чтобы отправить Служителям Земли сигнал с просьбой о помощи.$B$BЧтобы от меня и дальше был какой-то толк, мне необходим отдых.$B$BПоговори с главным тех, кого ты $gспас:спасла;, и постарайся сделать все от тебя зависящее, чтобы помочь им подготовиться к бою.$B$BНаги прочесывают воды, разыскивая нас. Пройдет немного времени – и они вернутся c подмогой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Побеседуйте с капитаном Тейлором.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25406,'Стражи из клана Гордок','Теперь, когда мы покончили с ограми поблизости, пришло время перейти из защиты в нападение и вторгнуться на их земли.$B$BОгры из клана Гордок возглавляют племя Гордунни, их резиденция находится в руинах Забытого города. Эти огры сильнее остальных Гордунни, но я думаю, ты без труда с ними справишься, $n. Они еще узнают, как угрожать нам.','Убейте 6 головорезов и 6 огров-магов из клана Гордок.','Отлично, все идет согласно нашему плану. Думаю, леди Шандриса будет довольна.','Вернитесь к Сильвии в башню Эстулана в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Стражи из клана Гордок',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда мы покончили с ограми поблизости, пришло время перейти из защиты в нападение и вторгнуться на их земли.$B$BОгры из клана Гордок возглавляют племя Гордунни, их резиденция находится в руинах Забытого города. Эти огры сильнее остальных Гордунни, но я думаю, ты без труда с ними справишься, $n. Они еще узнают, как угрожать нам.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 6 головорезов и 6 огров-магов из клана Гордок.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, все идет согласно нашему плану. Думаю, леди Шандриса будет довольна.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сильвии в башню Эстулана в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25407,'Силы природы: огоньки','Часовые составляют ядро наших сил в этом краю, но армия ночных эльфов никогда не ограничивалась собственно ночными эльфами. Все существа, делящие с нами кров этого леса, издавна являлись нашими верными защитниками. Нам нужно только напомнить им об узах древней дружбы.$B$BВозьми этот свисток – наши союзники знают его звук – и призови их под наши знамена.$B$BПрежде чем ты отправишься собирать их, советую потренироваться в обращении со свистком на огоньках. Найти подходящие объекты для призыва можно в лесу за стенами крепости.','Используйте свисток Тессины, чтобы призвать 3 огонька Оперенной Луны.','Огоньки всегда жили в гармонии с нашим народом, и мы многим им обязаны. Эти крошки, которых ты к нам прислал помогут нам с постройкой и ремонтом крепости.$B$BНу что, готов на подвиги?','Вернитесь к укротительнице Тессине в башню Эстулана, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Силы природы: огоньки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Часовые составляют ядро наших сил в этом краю, но армия ночных эльфов никогда не ограничивалась собственно ночными эльфами. Все существа, делящие с нами кров этого леса, издавна являлись нашими верными защитниками. Нам нужно только напомнить им об узах древней дружбы.$B$BВозьми этот свисток – наши союзники знают его звук – и призови их под наши знамена.$B$BПрежде чем ты отправишься собирать их, советую потренироваться в обращении со свистком на огоньках. Найти подходящие объекты для призыва можно в лесу за стенами крепости.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте свисток Тессины, чтобы призвать 3 огонька Оперенной Луны.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Огоньки всегда жили в гармонии с нашим народом, и мы многим им обязаны. Эти крошки, которых ты к нам прислал помогут нам с постройкой и ремонтом крепости.$B$BНу что, готов на подвиги?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к укротительнице Тессине в башню Эстулана, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25408,'Начало конца','Мы разгромим культ Сумеречного Молота, внеся смуту в ряды его служителей.$B$BЕсли ты не хочешь освободить меня от магических пут, то тебе придется собрать для меня несколько реагентов. Моя демоническая сущность принесла порчу растительности, окружающей башню. Собери для меня немного желчевики c ревун-травы, растущей поблизости.$B$BМои маленькие питомцы попытаются попробовать тебя на вкус. В твоих же интересах не пытаться собрать ягоды сразу с нескольких.','Соберите 8 ягод желчевики.','Очень хорошо. Теперь выжми из ягод сочную мякоть. Чудесный аромат, не правда ли?$B$BДавай-давай, не морщи нос. Веди себя достойно.','Ну, как тебе местная флора?$B$B<Чернорог ехидно улыбается.>','Вернитесь к Тирию Чернорогу у Башни Покаяния Чернорога на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Начало конца',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы разгромим культ Сумеречного Молота, внеся смуту в ряды его служителей.$B$BЕсли ты не хочешь освободить меня от магических пут, то тебе придется собрать для меня несколько реагентов. Моя демоническая сущность принесла порчу растительности, окружающей башню. Собери для меня немного желчевики c ревун-травы, растущей поблизости.$B$BМои маленькие питомцы попытаются попробовать тебя на вкус. В твоих же интересах не пытаться собрать ягоды сразу с нескольких.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 ягод желчевики.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Очень хорошо. Теперь выжми из ягод сочную мякоть. Чудесный аромат, не правда ли?$B$BДавай-давай, не морщи нос. Веди себя достойно.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, как тебе местная флора?$B$B<Чернорог ехидно улыбается.>',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тирию Чернорогу у Башни Покаяния Чернорога на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25409,'Силы природы: гиппогрифы','Гиппогрифы – потрясающие существа. Некоторые говорят, что их создал сам Кенарий, как дар ночным эльфам. Они сторонятся других рас, но достаточно умны, чтобы отличить друга от врага.$B$BМне нужны еще гиппогрифы, чтобы я смогла начать обучение наших молодых лучников верховой езде. Возьми свисток и приведи сюда несколько блеклоперых гиппогрифов, обитающих возле башни Эстулана.','Используйте свисток Тессины, чтобы призвать 10 блеклоперых гиппогрифов.','Хорошо выдрессированный отряд гиппогрифов может справиться практически с любым противником. Теперь, когда эти благородные животные на нашей стороне, крепости Оперенной Луны не страшен никакой враг.','Вернитесь к укротительнице Тессине в башню Эстулана в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Силы природы: гиппогрифы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Гиппогрифы – потрясающие существа. Некоторые говорят, что их создал сам Кенарий, как дар ночным эльфам. Они сторонятся других рас, но достаточно умны, чтобы отличить друга от врага.$B$BМне нужны еще гиппогрифы, чтобы я смогла начать обучение наших молодых лучников верховой езде. Возьми свисток и приведи сюда несколько блеклоперых гиппогрифов, обитающих возле башни Эстулана.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте свисток Тессины, чтобы призвать 10 блеклоперых гиппогрифов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо выдрессированный отряд гиппогрифов может справиться практически с любым противником. Теперь, когда эти благородные животные на нашей стороне, крепости Оперенной Луны не страшен никакой враг.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к укротительнице Тессине в башню Эстулана в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25410,'Силы природы: древни','Используйте свисток Тессины, чтобы призвать 6 бродячих лесных древней.','На вид не скажешь, но из некоторых древней вырастают настоящие сторожевые древа. Нам не помешает тут еще несколько штук.','Вернитесь к укротительнице Тессине в башню Эстулана в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Силы природы: древни',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте свисток Тессины, чтобы призвать 6 бродячих лесных древней.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','На вид не скажешь, но из некоторых древней вырастают настоящие сторожевые древа. Нам не помешает тут еще несколько штук.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к укротительнице Тессине в башню Эстулана в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25411,'Новый повелитель','Созданное тобой зелье настолько сильно, что способно воскрешать мертвых. Для этого оно, собственно, и предназначено.$B$BУбей сумеречного Лорда Преисподней, после чего залей ему это зелье в глотку. Затем он хотя бы ненадолго вернется к жизни и будет полностью подчиняться твоей воле.$B$BЗаговори с ним и узнай истинное имя элементаля огня, которого тот призвал в этот мир, чтобы испепелить твой драгоценный лес.','Примените бутыль отвара желчевики на трупе поверженного лорда Преисподней из культа Сумеречного Молота и поговорите с ним.','<Истерзанное злобное создание, на миг возвращенное к жизни при помощи темного зелья Чернорога, обращается к вам дрожащим голосом>$B$BСлушаю и повинуюсь!','Используйте бутыль отвара желчевики на трупе поверженного лорда Преисподней из культа Сумрачного Молота, после чего поговорите с ним.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новый повелитель',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Созданное тобой зелье настолько сильно, что способно воскрешать мертвых. Для этого оно, собственно, и предназначено.$B$BУбей сумеречного Лорда Преисподней, после чего залей ему это зелье в глотку. Затем он хотя бы ненадолго вернется к жизни и будет полностью подчиняться твоей воле.$B$BЗаговори с ним и узнай истинное имя элементаля огня, которого тот призвал в этот мир, чтобы испепелить твой драгоценный лес.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Примените бутыль отвара желчевики на трупе поверженного лорда Преисподней из культа Сумеречного Молота и поговорите с ним.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Истерзанное злобное создание, на миг возвращенное к жизни при помощи темного зелья Чернорога, обращается к вам дрожащим голосом>$B$BСлушаю и повинуюсь!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Используйте бутыль отвара желчевики на трупе поверженного лорда Преисподней из культа Сумрачного Молота, после чего поговорите с ним.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25412,'Запретное имя','Мы черпали ярость и силу пламени у того, чье имя нельзя называть, нашего прежнего повелителя.$B$BПекло – это плод его стараний.$b$bНикто не произносит его истинное имя, ибо оно таит в себе его неизмеримую силу.$B$BКаждый из нас знал лишь часть имени. Эти части высечены на камнях огня.$B$BЭти камни здесь, в Пекле. Отыщи все три, чтобы узнать истинное имя нашего повелителя...','Составьте истинное имя, осмотрев три камня огня.','Да, да! Покажи мне найденные тобой руны.$B$B"Вол\'тало Тол\'эмбаар." Вот истинное имя нашего врага.$B$BПо-видимому, мы имеем дело с одним из военачальников Рагнароса, посланных сюда, чтобы испепелить нагорье и проложить путь для дальнейшего завоевания.$B$BЯ научу тебя, как сразить его.','Вернитесь к Тирию Чернорогу у Башни Покаяния Чернорога на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Запретное имя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы черпали ярость и силу пламени у того, чье имя нельзя называть, нашего прежнего повелителя.$B$BПекло – это плод его стараний.$b$bНикто не произносит его истинное имя, ибо оно таит в себе его неизмеримую силу.$B$BКаждый из нас знал лишь часть имени. Эти части высечены на камнях огня.$B$BЭти камни здесь, в Пекле. Отыщи все три, чтобы узнать истинное имя нашего повелителя...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Составьте истинное имя, осмотрев три камня огня.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, да! Покажи мне найденные тобой руны.$B$B"Вол\'тало Тол\'эмбаар." Вот истинное имя нашего врага.$B$BПо-видимому, мы имеем дело с одним из военачальников Рагнароса, посланных сюда, чтобы испепелить нагорье и проложить путь для дальнейшего завоевания.$B$BЯ научу тебя, как сразить его.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тирию Чернорогу у Башни Покаяния Чернорога на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25413,'Планы изменились','О\'кей, малыш. Небольшая корректировочка планов...$B$BДумаю, я нашел способ одолеть монстра, и ты мне поможешь.$B$BТы у меня в долгу, пока мы с этим не покончим, а я без добычи не уйду.$B$BСначала нужно отыскать в этих старых обломках какую-нибудь подходящую веревку и пригодный гарпун.$B$BПотом... ну ладно, остальное расскажу после.','Отыщите ржавое гарпунное ружье и 3 мотка веревки.','Вернитесь к Харрисону Джонсу на раскопки Харрисона.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Планы изменились',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','О\'кей, малыш. Небольшая корректировочка планов...$B$BДумаю, я нашел способ одолеть монстра, и ты мне поможешь.$B$BТы у меня в долгу, пока мы с этим не покончим, а я без добычи не уйду.$B$BСначала нужно отыскать в этих старых обломках какую-нибудь подходящую веревку и пригодный гарпун.$B$BПотом... ну ладно, остальное расскажу после.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщите ржавое гарпунное ружье и 3 мотка веревки.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Харрисону Джонсу на раскопки Харрисона.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25414,'Пропавшие','Помимо беспорядков и общей паранойи, окружающей секту, есть еще одна проблема – мы завалены сообщениями о пропавших людях. Пропадают чьи-то матери, отцы, братья и сестры, и у меня есть предпололжение, что искать их следует в поселениях сектантов за пределами города. Если я дам тебе имена некоторых из пропавших людей, сможешь ли ты разыскать их в лагере сектантов? Он расположен в саду у Зеркального озера, к юго-западу от городских ворот. Для того, чтобы проникнуть в секту, тебе потребуется специальное одеяние, которое можно получить у одного из вестников рока в Старом городе.','Надев одеяние новообращенного секты, поговорите с сектантом Летелин, сектантом Каймой, сектантом Вайменом и сектантом Орлунном в саду у Зеркального озера, что в Элвиннском лесу.','Вернитесь к капитану Антону в крепость Штормграда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пропавшие',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Помимо беспорядков и общей паранойи, окружающей секту, есть еще одна проблема – мы завалены сообщениями о пропавших людях. Пропадают чьи-то матери, отцы, братья и сестры, и у меня есть предпололжение, что искать их следует в поселениях сектантов за пределами города. Если я дам тебе имена некоторых из пропавших людей, сможешь ли ты разыскать их в лагере сектантов? Он расположен в саду у Зеркального озера, к юго-западу от городских ворот. Для того, чтобы проникнуть в секту, тебе потребуется специальное одеяние, которое можно получить у одного из вестников рока в Старом городе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Надев одеяние новообращенного секты, поговорите с сектантом Летелин, сектантом Каймой, сектантом Вайменом и сектантом Орлунном в саду у Зеркального озера, что в Элвиннском лесу.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Антону в крепость Штормграда.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25415,'Несущие слово','Добро пожаловать в наш сад, $n. У нас здесь общественное хозяйство: кто-то ухаживает за деревьями, кто-то занят на стройке, а остальные читают проповеди и разносят наше учение по свету. Думаю, ты тоже можешь начать помогать нашему делу.$B$BВозьми этот плакат – на нем перечислены наши основные постулаты. Надень его на себя и посети Гарнизон у Западного ручья, что к юго-западу отсюда, городскую площадь в Златоземье и Аллею Героев в Штормграде.','Надев на себя Послание о Судном дне, посетите Гарнизон у Западного ручья, городскую площадь в Златоземье и Аллею Героев в Штормграде.','Вернитесь к надзирательнице Силандре в Сад у Зеркального озера.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Несущие слово',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Добро пожаловать в наш сад, $n. У нас здесь общественное хозяйство: кто-то ухаживает за деревьями, кто-то занят на стройке, а остальные читают проповеди и разносят наше учение по свету. Думаю, ты тоже можешь начать помогать нашему делу.$B$BВозьми этот плакат – на нем перечислены наши основные постулаты. Надень его на себя и посети Гарнизон у Западного ручья, что к юго-западу отсюда, городскую площадь в Златоземье и Аллею Героев в Штормграде.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Надев на себя Послание о Судном дне, посетите Гарнизон у Западного ручья, городскую площадь в Златоземье и Аллею Героев в Штормграде.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к надзирательнице Силандре в Сад у Зеркального озера.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25416,'Великий план','Я вижу, ты уже $gвлился:влилась; в наше общество, $n, и теперь тебе пора узнать, что наша деятельность не ограничивается проповедями и песнопениями. Полагаю, ты уже $gслышал:слышала; кое-что о нашей миссии, когда $gрешил:решила; присоединиться к нам.$B$BБлизится конец света, и те, кто не будут готовы встретить его, погибнут страшной смертью.$B$BНам был дан великий дар, возможность стать более сильными и могущественными. К западу от сада есть алтарь, возле которого надзиратель Талатор собирается провести ритуал. Дождись его, и ты узнаешь больше о нашем братстве.','Узнайте больше о планах сектантов, посетив алтарь в западной части сада у Зеркального озера','Вернитесь к надзирательнице Силандре в сад у Зеркального озера.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Великий план',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я вижу, ты уже $gвлился:влилась; в наше общество, $n, и теперь тебе пора узнать, что наша деятельность не ограничивается проповедями и песнопениями. Полагаю, ты уже $gслышал:слышала; кое-что о нашей миссии, когда $gрешил:решила; присоединиться к нам.$B$BБлизится конец света, и те, кто не будут готовы встретить его, погибнут страшной смертью.$B$BНам был дан великий дар, возможность стать более сильными и могущественными. К западу от сада есть алтарь, возле которого надзиратель Талатор собирается провести ритуал. Дождись его, и ты узнаешь больше о нашем братстве.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Узнайте больше о планах сектантов, посетив алтарь в западной части сада у Зеркального озера',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к надзирательнице Силандре в сад у Зеркального озера.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25417,'План вестников рока','Первая партия ловушек с элементалями готова. Тебе поручается спрятать их в Штормграде, а они в нужное время выпустят на волю огненных элементалей. Не волнуйся, $n, к тому времени ты будешь уже далеко от города.$B$BПостарайся не привлекать к себе лишнего внимания.$B$B<Надзиратель протягивает вам сверток с несколькими ловушками. Похоже, это именно то доказательство, которое рассчитывал получить капитан Антон. Вам надо срочно отнести сверток ему.>','Отнесите ловушки с элементалями капитану Антону в крепость Штормграда.','Отнесите ловушки с элементалями капитану Антону в крепость Штормграда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','План вестников рока',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Первая партия ловушек с элементалями готова. Тебе поручается спрятать их в Штормграде, а они в нужное время выпустят на волю огненных элементалей. Не волнуйся, $n, к тому времени ты будешь уже далеко от города.$B$BПостарайся не привлекать к себе лишнего внимания.$B$B<Надзиратель протягивает вам сверток с несколькими ловушками. Похоже, это именно то доказательство, которое рассчитывал получить капитан Антон. Вам надо срочно отнести сверток ему.>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите ловушки с элементалями капитану Антону в крепость Штормграда.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите ловушки с элементалями капитану Антону в крепость Штормграда.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25418,'Расстроить планы','Вряд ли тебе $gодному:одной; поручили разместить эти ловушки в Штормграде. Мы должны найти остальные бомбы и обезвредить их прежде, чем они выпустят на волю воздушных элементалей, которые разнесут город в щепки.$B$BТы $gзнаком:знакома; с устройством этих ловушек? Их нужно разбить прежде, чем заключенные элементали наберут силу и выберутся наружу. Не волнуйся, до того момента их будет легко победить. Ищи ловушки в Торговом квартале, на Соборной площади и в Квартале магов.','Уничтожьте 5 ловушек с элементалями и убейте 5 бушующих духов ветра.','Вернитесь к капитану Антону в крепость Штормграда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Расстроить планы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вряд ли тебе $gодному:одной; поручили разместить эти ловушки в Штормграде. Мы должны найти остальные бомбы и обезвредить их прежде, чем они выпустят на волю воздушных элементалей, которые разнесут город в щепки.$B$BТы $gзнаком:знакома; с устройством этих ловушек? Их нужно разбить прежде, чем заключенные элементали наберут силу и выберутся наружу. Не волнуйся, до того момента их будет легко победить. Ищи ловушки в Торговом квартале, на Соборной площади и в Квартале магов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 5 ловушек с элементалями и убейте 5 бушующих духов ветра.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Антону в крепость Штормграда.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25419,'Медальон леди Ла-Ла','Десятки грубо сработанных золотых звеньев скреплены в массивную цепь.$B$BНа центральном ее звене болтается нечто напоминающее фрагмент огромного медальона в форме раковины.$B$BВам любопытно, нет ли где поблизости других фрагментов медальона и нельзя ли их собрать воедино.','Отберите 5 фрагментов медальона у жаблинов-собирателей и составьте из них медальон леди Ла-Ла.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Медальон леди Ла-Ла',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Десятки грубо сработанных золотых звеньев скреплены в массивную цепь.$B$BНа центральном ее звене болтается нечто напоминающее фрагмент огромного медальона в форме раковины.$B$BВам любопытно, нет ли где поблизости других фрагментов медальона и нельзя ли их собрать воедино.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отберите 5 фрагментов медальона у жаблинов-собирателей и составьте из них медальон леди Ла-Ла.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25420,'Преграды древности','Я годами изучал эти врата, пытаясь обнаружить способ проникнуть внутрь таким образом, чтобы не навредить древним строениям. Но стоило случиться нескольким землетрясениям, как весь комплекс оказался искорежен! Но чему быть, того не миновать – врата Ульдума теперь открыты.$b$BОднако вот чего я совершенно не предполагал, так это того, что из руин что-то может выйти наружу. А теперь здесь разгуливает целая толпа големов. Кто-то должен очистить от них долину, если мы собираемся продолжать исследования.','Уничтожьте 6 песчанокаменных големов.','Вернитесь к геологу Ганстену на раскопки Ганстена.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Преграды древности',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я годами изучал эти врата, пытаясь обнаружить способ проникнуть внутрь таким образом, чтобы не навредить древним строениям. Но стоило случиться нескольким землетрясениям, как весь комплекс оказался искорежен! Но чему быть, того не миновать – врата Ульдума теперь открыты.$b$BОднако вот чего я совершенно не предполагал, так это того, что из руин что-то может выйти наружу. А теперь здесь разгуливает целая толпа големов. Кто-то должен очистить от них долину, если мы собираемся продолжать исследования.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 6 песчанокаменных големов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к геологу Ганстену на раскопки Ганстена.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25421,'Великая скрижаль','На крышке сундука вы обнаружили скрижаль, сделанную из безупречно отполированного камня. Поверхность ее покрыта странными письменами.$b$bНекоторые знаки похожи на те, что нанесены на стены вокруг, некоторые выглядят совершенно иначе. Пожалуй, Ганстену будет интересно взглянуть.','Принесите Ганстену Великую скрижаль.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Великая скрижаль',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На крышке сундука вы обнаружили скрижаль, сделанную из безупречно отполированного камня. Поверхность ее покрыта странными письменами.$b$bНекоторые знаки похожи на те, что нанесены на стены вокруг, некоторые выглядят совершенно иначе. Пожалуй, Ганстену будет интересно взглянуть.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Ганстену Великую скрижаль.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25422,'Наследие Мглистой пещеры','Меня приковало к этому месту... Даже говорить с тобой – и то тяжело. Я едва могу поддерживать себя в этой форме.$B$BЕсли тебе нужен амулет, то я тебе помогу, но прошу, помоги мне сперва собрать себя воедино. Как только я закреплюсь здесь, я смогу помочь...$B$BОх, мне бы только выйти из этого склепа... Там, снаружи, земля полна древних магических элементов, они там уже целые столетия. Может, ты принесешь мне немного?','Соберите 6 горстей светящейся земли.','Спасибо! Спасибо…$B$BМне уже намного лучше. Сейчас, еще немного…','Удалось набрать земли? Мне все труднее держаться... Поспеши...','Вернитесь к Сенсирии в руины Мглистой пещеры в Фералас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наследие Мглистой пещеры',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Меня приковало к этому месту... Даже говорить с тобой – и то тяжело. Я едва могу поддерживать себя в этой форме.$B$BЕсли тебе нужен амулет, то я тебе помогу, но прошу, помоги мне сперва собрать себя воедино. Как только я закреплюсь здесь, я смогу помочь...$B$BОх, мне бы только выйти из этого склепа... Там, снаружи, земля полна древних магических элементов, они там уже целые столетия. Может, ты принесешь мне немного?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 6 горстей светящейся земли.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо! Спасибо…$B$BМне уже намного лучше. Сейчас, еще немного…',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось набрать земли? Мне все труднее держаться... Поспеши...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сенсирии в руины Мглистой пещеры в Фералас.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25423,'Древние страдания','Поосторожней там, когда пойдешь вперед. В этом месте заключены другие духи, полные злобы и ненависти. Им выпало очень много страданий.$B$BОт их прошлого не осталось ничего, кроме боли и воли к жизни. Эта воля потребуется нам для того, чтобы призвать господина, который держит меня на этом месте. Прошу, собери субстанции духов и принеси их сюда, ко мне.','Соберите 6 субстанций душ.','Чуешь их боль, да?$B$BМои бедные друзья… Но у нас хотя бы есть ты, и ты можешь все поправить…','Удалось что-нибудь собрать?','Вернитесь к Сенсирии в руины Мглистой пещеры в Фералас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Древние страдания',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Поосторожней там, когда пойдешь вперед. В этом месте заключены другие духи, полные злобы и ненависти. Им выпало очень много страданий.$B$BОт их прошлого не осталось ничего, кроме боли и воли к жизни. Эта воля потребуется нам для того, чтобы призвать господина, который держит меня на этом месте. Прошу, собери субстанции духов и принеси их сюда, ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 6 субстанций душ.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Чуешь их боль, да?$B$BМои бедные друзья… Но у нас хотя бы есть ты, и ты можешь все поправить…',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось что-нибудь собрать?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сенсирии в руины Мглистой пещеры в Фералас.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25424,'Вернуться к Алисре','Спасибо за то, что $gосвободил:освободила; меня, $n. Я расскажу нашим союзникам о том, что обнаружила.$B$BЯ думаю, тебе лучше вернуться к зеленому дракону, пославшему тебя сюда.$B$BСумеречный Молот хочет не просто захватить эту территорию. Им нужен узник.$B$BФэндрал Олений Шлем, который заключен в кельях Хиджала. Атака является отвлекающим маневром для того, чтобы освободить его. Зачем – я не знаю. Возможно, наш союзник-дракон прольет свет на эту тайну.','Вернитесь к Алисре в руины Лар\'донира на Хиджале.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вернуться к Алисре',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Спасибо за то, что $gосвободил:освободила; меня, $n. Я расскажу нашим союзникам о том, что обнаружила.$B$BЯ думаю, тебе лучше вернуться к зеленому дракону, пославшему тебя сюда.$B$BСумеречный Молот хочет не просто захватить эту территорию. Им нужен узник.$B$BФэндрал Олений Шлем, который заключен в кельях Хиджала. Атака является отвлекающим маневром для того, чтобы освободить его. Зачем – я не знаю. Возможно, наш союзник-дракон прольет свет на эту тайну.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь к Алисре в руины Лар\'донира на Хиджале.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25425,'Предупредить короля Ринна','$n, ты $gзащитил:защитила; город от угрозы, исходящей от служителей культа Сумеречного Молота, и не $gпозволил:позволила; пролиться крови нашего народа. Но враг не смирится с этим поражением. Сомневаюсь, что Чо\'Галл так легко откажется от своих целей.$B$BМы должны уведомить короля Вариана Ринна. Отправляйся прямиком в тронный зал крепости Штормграда. Сообщи его величеству, что наши враги уже проявили себя, и мы должны готовиться к их следующим действиям.','Поговорите с королем Варианом Ринном в крепости Штормграда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Предупредить короля Ринна',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, ты $gзащитил:защитила; город от угрозы, исходящей от служителей культа Сумеречного Молота, и не $gпозволил:позволила; пролиться крови нашего народа. Но враг не смирится с этим поражением. Сомневаюсь, что Чо\'Галл так легко откажется от своих целей.$B$BМы должны уведомить короля Вариана Ринна. Отправляйся прямиком в тронный зал крепости Штормграда. Сообщи его величеству, что наши враги уже проявили себя, и мы должны готовиться к их следующим действиям.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с королем Варианом Ринном в крепости Штормграда.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`completedtext_loc8`) VALUES (25426,'Вернитесь к Аделле в Тень Ветвей в Фераласе.') ON DUPLICATE KEY UPDATE `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аделле в Тень Ветвей в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25427,'Истребление вожаков','Убейте 5 вожаков стаи Древолапов','Замечательно. Все оставшиеся гноллы заблудятся в лесу и станут легкой добычей.$B$BХе… Ну что же, рубака, бери свою награду, пока про нее не забыли. Здесь ведь и других врагов еще полно.','Вернитесь к Аделле в Тень Ветвей в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Истребление вожаков',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 5 вожаков стаи Древолапов',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Замечательно. Все оставшиеся гноллы заблудятся в лесу и станут легкой добычей.$B$BХе… Ну что же, рубака, бери свою награду, пока про нее не забыли. Здесь ведь и других врагов еще полно.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аделле в Тень Ветвей в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (25428,'Черное сердце пламени','А теперь воспользуйся обретенным тобой знанием, чтобы призвать Тол\'эмбаара в мир смертных. Затем ты сокрушишь его.$B$BРитуал чрезвычайно прост: возьми ту обугленную ветку, трижды ударь ею оземь, после чего громко произнеси его имя.$B$BРитуал следует проводить в центре Пекла. Уничтожь порождение огня, после чего принеси мне его черное сердце.','Находясь в Пекле, воспользуйтесь обугленной веткой, чтобы призвать Тол\'эмбаара. Убейте его и достаньте из трупа черное сердце Тол\'эмбаара.','Принесите черное сердце Тол\'эмбаара Тирию Чернорогу к Башне Покаяния Чернорога, которая находится на горе Хиджал.','Воспользуйтесь обугленной веткой, находясь в Пекле, чтобы призвать порождение огня.','Тол\'эмбаар') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Черное сердце пламени',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А теперь воспользуйся обретенным тобой знанием, чтобы призвать Тол\'эмбаара в мир смертных. Затем ты сокрушишь его.$B$BРитуал чрезвычайно прост: возьми ту обугленную ветку, трижды ударь ею оземь, после чего громко произнеси его имя.$B$BРитуал следует проводить в центре Пекла. Уничтожь порождение огня, после чего принеси мне его черное сердце.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Находясь в Пекле, воспользуйтесь обугленной веткой, чтобы призвать Тол\'эмбаара. Убейте его и достаньте из трупа черное сердце Тол\'эмбаара.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите черное сердце Тол\'эмбаара Тирию Чернорогу к Башне Покаяния Чернорога, которая находится на горе Хиджал.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Воспользуйтесь обугленной веткой, находясь в Пекле, чтобы призвать порождение огня.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Тол\'эмбаар',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25429,'Нападение на улей Зукк\'аш','Так, с гноллами разобрались, пора приниматься за других врагов. Разведчики нашли поблизости что-то вроде улья, и он уходит глубоко под землю.$B$BНасекомые в этом улье большие и злобные, и, думаю, они намного опаснее гноллов. Сходи-ка в этот улей, но только осторожно. Убей там побольше жуков, а панцири их принеси сюда для изучения.','Добудьте 20 панцирей Зукк\'аш.','Вернитесь к Аделле в Тень Ветвей в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нападение на улей Зукк\'аш',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Так, с гноллами разобрались, пора приниматься за других врагов. Разведчики нашли поблизости что-то вроде улья, и он уходит глубоко под землю.$B$BНасекомые в этом улье большие и злобные, и, думаю, они намного опаснее гноллов. Сходи-ка в этот улей, но только осторожно. Убей там побольше жуков, а панцири их принеси сюда для изучения.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 20 панцирей Зукк\'аш.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аделле в Тень Ветвей в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (25430,'Зеленые союзники','Друиды Хиджала – не единственные, кто поклялся защищать эту землю. Изумрудные драконы вновь стали нашими могучими союзниками.$B$BПоговори с Алисрой в руинах Лар\'донира и узнай, чем ты можешь помочь.','Поговорите с Алисрой в руинах Лар\'донира на горе Хиджал.','Мой долг держит меня здесь. Я наблюдаю за продвижением врага с высоты, командую нашими армиями там, где необходимо.$B$BТвоя помощь пригодится.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зеленые союзники',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Друиды Хиджала – не единственные, кто поклялся защищать эту землю. Изумрудные драконы вновь стали нашими могучими союзниками.$B$BПоговори с Алисрой в руинах Лар\'донира и узнай, чем ты можешь помочь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Алисрой в руинах Лар\'донира на горе Хиджал.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мой долг держит меня здесь. Я наблюдаю за продвижением врага с высоты, командую нашими армиями там, где необходимо.$B$BТвоя помощь пригодится.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (25431,'Жалохвост','Насекомые в этом улье и так огромные, но недавно разведчики обнаружили там одну особенно здоровую тварь. И, судя по всему, она как-то управляет рабочими насекомыми на поверхности.$B$BЯ мало что знаю об этих существах, но раз уж они начали расползаться из своей норы, то нам придется остановить их. Убей эту гигантскую осу и возвращайся ко мне.','Убейте Жалохвоста в Гудящей Бездне.','Вернитесь к Аделле в Тень Ветвей в Фераласе.','Берегись его яда!','Жалохвост') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жалохвост',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Насекомые в этом улье и так огромные, но недавно разведчики обнаружили там одну особенно здоровую тварь. И, судя по всему, она как-то управляет рабочими насекомыми на поверхности.$B$BЯ мало что знаю об этих существах, но раз уж они начали расползаться из своей норы, то нам придется остановить их. Убей эту гигантскую осу и возвращайся ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Жалохвоста в Гудящей Бездне.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аделле в Тень Ветвей в Фераласе.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Берегись его яда!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Жалохвост',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25432,'Не кричи: "Огры!"','Убейте 5 стражей-лекарей из клана Гордунни.','Вернитесь к Аделле в Тень Ветвей в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Не кричи: "Огры!"',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 5 стражей-лекарей из клана Гордунни.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аделле в Тень Ветвей в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (25433,'Замечен снежный человек','Возможно, ты $gвидел и сам:видела и сама;. Разведчики доносят об огромном чудовище, которое удерживают огры. В донесении говорится, что оно похоже на йети, но крупнее всего, что обитает в чащобах Фераласа.$B$BОгры пытаются научить эту тварь выполнять их команды. Звучит смешно, конечно, но я не собираюсь сидеть и ждать, получится у них что-то или нет. Вернись в холмы и убей это чудовище.','Убейте Большую Лапу.','Вернитесь к Аделле в Тень Ветвей в Фераласе.','Интересно, как он получил свое имя…','Большая Лапа') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Замечен снежный человек',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Возможно, ты $gвидел и сам:видела и сама;. Разведчики доносят об огромном чудовище, которое удерживают огры. В донесении говорится, что оно похоже на йети, но крупнее всего, что обитает в чащобах Фераласа.$B$BОгры пытаются научить эту тварь выполнять их команды. Звучит смешно, конечно, но я не собираюсь сидеть и ждать, получится у них что-то или нет. Вернись в холмы и убей это чудовище.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Большую Лапу.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аделле в Тень Ветвей в Фераласе.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Интересно, как он получил свое имя…',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Большая Лапа',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25434,'Ловля звероловов','Этот йети, конечно, серьезная угроза, но надо сделать что-то и с ограми. Гордунни слишком долго испытывали наше терпение, теперь леди Шандриса хочет покончить с ними раз и навсегда. Будем надеяться, это последние представители проклятого племени.$B$BУбей звероловов из клана Гордунни, которые смотрят за этой тварью. Пусть узнают, как совать свой нос в наши дела.','Убейте 6 звероловов из клана Гордунни','Вернитесь к Аделле в Тень Ветвей в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ловля звероловов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этот йети, конечно, серьезная угроза, но надо сделать что-то и с ограми. Гордунни слишком долго испытывали наше терпение, теперь леди Шандриса хочет покончить с ними раз и навсегда. Будем надеяться, это последние представители проклятого племени.$B$BУбей звероловов из клана Гордунни, которые смотрят за этой тварью. Пусть узнают, как совать свой нос в наши дела.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 6 звероловов из клана Гордунни',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аделле в Тень Ветвей в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25435,'Страсти скачут во весь опор','Привет, $gмалой:дорогуша;.$B$BМеня звать Рендел.$B$BПохоже, мы со старушкой Моаной прибыли как раз вовремя, верно говорю?$B$BЭрунак не шутки шутил, когда говорил, что положеньице тут – пан или пропал!$B$BПокуда он ищет укромное местечко, где окопаться, попробуем-ка обеспечить тебе скакуна.$B$BЯ, может быть, в жизни морской мало смыслю, зато наги, кажется, чувствуют себя тут вольготно.$B$BТы давай-ка собери всякую всячину для уздечки, а я покумекаю над чарами.','Раздобудьте 3 жилы прожорливых крепкозубов и 2 заточенные клешни быстролапов с острыми клешнями.$B$BТакже вы можете приманить прожорливых крепкозубов крабьими внутренностями.','Поговорите с Ренделом Огнеязыким в Конце отмели.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Страсти скачут во весь опор',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Привет, $gмалой:дорогуша;.$B$BМеня звать Рендел.$B$BПохоже, мы со старушкой Моаной прибыли как раз вовремя, верно говорю?$B$BЭрунак не шутки шутил, когда говорил, что положеньице тут – пан или пропал!$B$BПокуда он ищет укромное местечко, где окопаться, попробуем-ка обеспечить тебе скакуна.$B$BЯ, может быть, в жизни морской мало смыслю, зато наги, кажется, чувствуют себя тут вольготно.$B$BТы давай-ка собери всякую всячину для уздечки, а я покумекаю над чарами.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте 3 жилы прожорливых крепкозубов и 2 заточенные клешни быстролапов с острыми клешнями.$B$BТакже вы можете приманить прожорливых крепкозубов крабьими внутренностями.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Ренделом Огнеязыким в Конце отмели.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25436,'Злобные сестрицы','Произошло что-то немыслимое! Когда мои разведчики патрулировали территорию, на них неожиданно напали дриады.$B$BДриады, самые преданные союзники ночных эльфов и надежные стражи леса! Сперва я предположила, что они испугались, увидев воргенов, но отряд, который я послала следом за первым, тоже подвергся нападению.$B$BЧто бы там ни происходило, мне это не нравится. Я хочу, чтобы ты $gотправился:отправилась; туда и $gразведал:разведала;, что там творится. И если действительно дриад затронула порча... убей их.','Убейте 8 зараженных дриад.','Вернитесь к Аделле в Тень Ветвей в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Злобные сестрицы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Произошло что-то немыслимое! Когда мои разведчики патрулировали территорию, на них неожиданно напали дриады.$B$BДриады, самые преданные союзники ночных эльфов и надежные стражи леса! Сперва я предположила, что они испугались, увидев воргенов, но отряд, который я послала следом за первым, тоже подвергся нападению.$B$BЧто бы там ни происходило, мне это не нравится. Я хочу, чтобы ты $gотправился:отправилась; туда и $gразведал:разведала;, что там творится. И если действительно дриад затронула порча... убей их.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 зараженных дриад.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аделле в Тень Ветвей в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (25437,'Зов Исондры','Поговорите с Исондрой на Изумрудной вершине в Низинных Чащобах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зов Исондры',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Исондрой на Изумрудной вершине в Низинных Чащобах.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25438,'Прощание Исондры','Я единственная из оставшихся здесь.$B$BДаже если я решу задержаться в этом мире, мне не объединить племя зеленых драконов. Но эта победа вновь заставляет меня надеяться на лучшее. Возможно, когда-нибудь я смогу обрести покой в простых радостях жизни смертных.$B$BВозвращайся к своему народу. Скажи им, что драконы из кошмарных снов исчезли и больше не будут угрожать этим землям.','Поговорите с Аделлой в Тени Ветвей.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прощание Исондры',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я единственная из оставшихся здесь.$B$BДаже если я решу задержаться в этом мире, мне не объединить племя зеленых драконов. Но эта победа вновь заставляет меня надеяться на лучшее. Возможно, когда-нибудь я смогу обрести покой в простых радостях жизни смертных.$B$BВозвращайся к своему народу. Скажи им, что драконы из кошмарных снов исчезли и больше не будут угрожать этим землям.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Аделлой в Тени Ветвей.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25439,'Жажда мести','Это те самые наги, которые забрали наших товарищей. Оставь одну змеюку для допроса, а остальных убей.$B$BИ не щади их, |3-6($c). Они бы точно нас не пощадили.','Убейте 10 опустошителей Зин\'жатара.','Я рад, что со мной настоящий воин. Увы, шаманы не всегда справляются с такой работой в одиночку.','Вернитесь к Тошу Приносящему Хаос на руины храма Телсерай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жажда мести',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это те самые наги, которые забрали наших товарищей. Оставь одну змеюку для допроса, а остальных убей.$B$BИ не щади их, |3-6($c). Они бы точно нас не пощадили.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 опустошителей Зин\'жатара.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я рад, что со мной настоящий воин. Увы, шаманы не всегда справляются с такой работой в одиночку.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тошу Приносящему Хаос на руины храма Телсерай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (25440,'Повелитель глубин Зин\'жатар','Повелитель глубин здесь, на окраине руин. Он еще не оправился от раны, которую получил в последней битве.$B$BПредоставлю удовольствие от охоты тебе. Не дай ему уйти на этот раз.','Убейте Повелителя глубин Зин\'жатара.','Надеюсь, теперь они не скоро решатся на нас напасть.','Вернитесь к Тошу Приносящему Хаос на руины храма Телсерай.','Впервые потерпев поражение в Гроте Затуманенного Света, повелитель глубин Зин\'жатар отступил к руинам, но не слишком далеко.','Повелитель глубин Зин\'жатар') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Повелитель глубин Зин\'жатар',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Повелитель глубин здесь, на окраине руин. Он еще не оправился от раны, которую получил в последней битве.$B$BПредоставлю удовольствие от охоты тебе. Не дай ему уйти на этот раз.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Повелителя глубин Зин\'жатара.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Надеюсь, теперь они не скоро решатся на нас напасть.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тошу Приносящему Хаос на руины храма Телсерай.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Впервые потерпев поражение в Гроте Затуманенного Света, повелитель глубин Зин\'жатар отступил к руинам, но не слишком далеко.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Повелитель глубин Зин\'жатар',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25441,'Вихрь','Я не питаю к змеям особой любви, особенно к здешним. К счастью, стихия воды все еще подчиняется моей воле.$B$BВозьми эти сферы. Брось одну из них на землю, и водоворот затянет в себя всех змей, находящихся в радиусе его действия. Не сомневаюсь, наги хотят напустить этих змей на нас, так что держи сферы наготове.','Поймайте 30 ползучих змей с помощью сфер беспокойной воды.','Нас часто путают с друидами. Возможно, кто-то из шаманов действительно похож на них, но не обманывайся – мы не всегда миролюбивы.$B$BТо, что делаю я, никак не связано с понятием гармонии. Я повелеваю стихиями – и ничего не предлагаю взамен. И так будет всегда.','Вернитесь к Тошу Приносящему Хаос на руины храма Телсерай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вихрь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я не питаю к змеям особой любви, особенно к здешним. К счастью, стихия воды все еще подчиняется моей воле.$B$BВозьми эти сферы. Брось одну из них на землю, и водоворот затянет в себя всех змей, находящихся в радиусе его действия. Не сомневаюсь, наги хотят напустить этих змей на нас, так что держи сферы наготове.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поймайте 30 ползучих змей с помощью сфер беспокойной воды.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Нас часто путают с друидами. Возможно, кто-то из шаманов действительно похож на них, но не обманывайся – мы не всегда миролюбивы.$B$BТо, что делаю я, никак не связано с понятием гармонии. Я повелеваю стихиями – и ничего не предлагаю взамен. И так будет всегда.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тошу Приносящему Хаос на руины храма Телсерай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25442,'Жемчужина мудрости','Эта жемчужина не похожа ни на одну другую. Она излучает свет и, если ты не $gошибся:ошиблась;, мощную магическую энергию.$B$BЦелитель Земли Дуарн из Пещеры Серебряной Волны наверняка заинтересуется этой вещицей.','Отнесите светящуюся жемчужину Целителю Земли Дуарну в Пещеру Серебряной Волны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жемчужина мудрости',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эта жемчужина не похожа ни на одну другую. Она излучает свет и, если ты не $gошибся:ошиблась;, мощную магическую энергию.$B$BЦелитель Земли Дуарн из Пещеры Серебряной Волны наверняка заинтересуется этой вещицей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите светящуюся жемчужину Целителю Земли Дуарну в Пещеру Серебряной Волны.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25443,'Запретное имя','Ну как, сработал мой настой? Ты $gпоговорил:поговорила; с одним из них?$B$BТогда ты знаешь, что делать. Имя повелителя элементалей записано на трех камнях огня, раскиданных по Пеклу. Осмотри эти камни, чтобы узнать это имя.$B$BПоторопись! Твой драгоценный лес все еще объят пламенем!','Составьте истинное имя, осмотрев три камня огня, раскиданных по Пеклу.','Вернитесь к Тирию Чернорогу у Башни Покаяния Чернорога на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Запретное имя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну как, сработал мой настой? Ты $gпоговорил:поговорила; с одним из них?$B$BТогда ты знаешь, что делать. Имя повелителя элементалей записано на трех камнях огня, раскиданных по Пеклу. Осмотри эти камни, чтобы узнать это имя.$B$BПоторопись! Твой драгоценный лес все еще объят пламенем!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Составьте истинное имя, осмотрев три камня огня, раскиданных по Пеклу.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тирию Чернорогу у Башни Покаяния Чернорога на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25444,'Идеальные шпионы','Глупо соваться туда вслепую, так что мы сначала зашлем наших маленьких шпионов собрать кое-какую информацию для Вол\'джина. Он должен знать, что творится на островах.$B$BЕсли хочешь помочь – я не против. Сначала поймай лягушек – они любят сидеть в тени пальм вокруг Сен\'джина.$B$BКак наловишь квакш, тащи к моему сторожевому тотему, мы заговорим их и прикрутим к ним мое зрение.','Поймайте 5 сен\'джинских лягушек и заговорите их, объединив их зрение со зрением Ваниры у сторожевого тотема.','Для наших целей их вполне хватит. Итак, приступим...','Вернитесь к Ванире на побережье Черного Копья.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Идеальные шпионы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Глупо соваться туда вслепую, так что мы сначала зашлем наших маленьких шпионов собрать кое-какую информацию для Вол\'джина. Он должен знать, что творится на островах.$B$BЕсли хочешь помочь – я не против. Сначала поймай лягушек – они любят сидеть в тени пальм вокруг Сен\'джина.$B$BКак наловишь квакш, тащи к моему сторожевому тотему, мы заговорим их и прикрутим к ним мое зрение.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поймайте 5 сен\'джинских лягушек и заговорите их, объединив их зрение со зрением Ваниры у сторожевого тотема.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Для наших целей их вполне хватит. Итак, приступим...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ванире на побережье Черного Копья.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25445,'Падение Залазана','Время битвы пришло! Мы отправляемся на острова, так что не отставай.$B$BНедолго осталось править Залазану...','$N, ты $Gбыл:была; бы могучим воином и яростным товарищем троллям Черного Копья. Острова Де Эхо теперь НАШИ, и мы не смогли бы сделать это без тебя.$B$BВозьми плащ. Носите его с гордостью. Теперь ты стала членом этого племени!$B$BСкоро у троллей снова появится дом и мы должны будем за это поблагодарить.','Вернитесь к Вол\'джину в деревню Сен\'джин.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Падение Залазана',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Время битвы пришло! Мы отправляемся на острова, так что не отставай.$B$BНедолго осталось править Залазану...',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','$N, ты $Gбыл:была; бы могучим воином и яростным товарищем троллям Черного Копья. Острова Де Эхо теперь НАШИ, и мы не смогли бы сделать это без тебя.$B$BВозьми плащ. Носите его с гордостью. Теперь ты стала членом этого племени!$B$BСкоро у троллей снова появится дом и мы должны будем за это поблагодарить.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Вол\'джину в деревню Сен\'джин.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25446,'Лягушачий десант','Ну, раз квакши готовы к высадке, пора десантировать их на острова.$B$BК югу отсюда, в восточной части деревни Сен\'джин, найди дрессировщика нетопырей Марнлека. Он готовит летучих мышей для разведчиков Вол\'джина, так что с удовольствием одолжит тебе нетопыря, знающего путь на острова.$B$BМешок с квакшами бери с собой. Я же буду просить духов направить нас на путь истинный. Они укажут тебе с помощью дыма, в каких местах нужно разместить соглядатаев. Так что тебе останется только найти, откуда поднимается белый дым, и бросить туда квакшу из мешка.','Оседлав летучую мышь, воспользуйтесь мешком лягушек, чтобы сбросить 12 заговоренных лягушек на острова Эха.','Я уже начинаю видеть, что видят лягушки. Я сделал это, $N. Теперь мы с Вол\'джином посмотрим, что планирует Залазан.','Вернитесь к Ванире в деревню Сен\'джин.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лягушачий десант',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну, раз квакши готовы к высадке, пора десантировать их на острова.$B$BК югу отсюда, в восточной части деревни Сен\'джин, найди дрессировщика нетопырей Марнлека. Он готовит летучих мышей для разведчиков Вол\'джина, так что с удовольствием одолжит тебе нетопыря, знающего путь на острова.$B$BМешок с квакшами бери с собой. Я же буду просить духов направить нас на путь истинный. Они укажут тебе с помощью дыма, в каких местах нужно разместить соглядатаев. Так что тебе останется только найти, откуда поднимается белый дым, и бросить туда квакшу из мешка.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Оседлав летучую мышь, воспользуйтесь мешком лягушек, чтобы сбросить 12 заговоренных лягушек на острова Эха.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я уже начинаю видеть, что видят лягушки. Я сделал это, $N. Теперь мы с Вол\'джином посмотрим, что планирует Залазан.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ванире в деревню Сен\'джин.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25447,'Знаки перемен','Странная болезнь поразила зверей в этом лесу. Поначалу я надеялся, что она пройдет, но надежды мои были тщетны.$B$BЛесные олени более других существ пострадали от этой странной болезни. Некоторые из них не могут встать от слабости, другие, напротив, впали в бешеную ярость. Если я хочу выяснить причину этой болезни у духов, мне понадобятся рога этих оленей.','Соберите 8 рогов зараженных оленей.','Вернитесь к Теларону Полету Ветра в Покои Дремлющего в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Знаки перемен',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Странная болезнь поразила зверей в этом лесу. Поначалу я надеялся, что она пройдет, но надежды мои были тщетны.$B$BЛесные олени более других существ пострадали от этой странной болезни. Некоторые из них не могут встать от слабости, другие, напротив, впали в бешеную ярость. Если я хочу выяснить причину этой болезни у духов, мне понадобятся рога этих оленей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 рогов зараженных оленей.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Теларону Полету Ветра в Покои Дремлющего в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25448,'Угроза Студеных Ключей','Я здесь, чтобы присматривать за Телароном. Речь не только о его медитациях, во время которых он беспомощней младенца. Нам и без того постоянно приходится быть настороже – уж слишком много всякой погани водится в этом лесу.$B$BПоэтому меня бесит, что я не могу покинуть лагерь. К северо-западу отсюда все кишит гарпиями... Эти твари любят гнездиться в древних руинах.$B$BОни угрожают лагерю, и я уверена, что гарпиям не место в этих землях. Избавься от них, и я щедро вознагражу тебя.','Убейте 6 гарпий и шесть призывательниц ветра из стаи Студеных Ключей.','Вернитесь к Эрине Дочери Ивы в Покои Дремлющего в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Угроза Студеных Ключей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я здесь, чтобы присматривать за Телароном. Речь не только о его медитациях, во время которых он беспомощней младенца. Нам и без того постоянно приходится быть настороже – уж слишком много всякой погани водится в этом лесу.$B$BПоэтому меня бесит, что я не могу покинуть лагерь. К северо-западу отсюда все кишит гарпиями... Эти твари любят гнездиться в древних руинах.$B$BОни угрожают лагерю, и я уверена, что гарпиям не место в этих землях. Избавься от них, и я щедро вознагражу тебя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 6 гарпий и шесть призывательниц ветра из стаи Студеных Ключей.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Эрине Дочери Ивы в Покои Дремлющего в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25449,'Знак качества','Я придерживаюсь мнения, что кожевенные изделия должны быть наивысшего качества, и никаких компромиссов. А те, кто говорят, будто качество не имеет значения, того и гляди попытаются впарить тебе дом с видом на океан в Дун Мороге!$B$BВ последнее время, разыскивая высококачественные материалы, мне довелось наткнуться на толстые шкуры йети. Эти йети родом из Фераласа, их полно в Пещере Бешеного оврага, это к северо-востоку отсюда. Мне нужны эти шкуры, а за 10 штук я дам тебе на выбор одно из моих изделий. Так что если тебе по душе мое предложение, то давай, займись-ка!','Добудьте 10 толстых шкур йети.','А как тебе текстура этих шкур, а? Если их как следует обработать, то они будут прочнее железа. Про эти шкуры вообще мало кто знает, а если еще учесть все те методы обработки, которые мне известны, то сразу видно: я сделаю по-настоящему качественные вещи… благодаря тебе, конечно же!$B$BНу что ж, а теперь выбери то, что хочешь за свои труды!','Принеси мне десять толстых шкур йети, и за это я дам тебе один из моих товаров. Я высоко ценю качество, так что награда тебе понравится, не сомневайся!','Вернитесь к Пратту МакГруббену в крепость Оперенной Луны в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Знак качества',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я придерживаюсь мнения, что кожевенные изделия должны быть наивысшего качества, и никаких компромиссов. А те, кто говорят, будто качество не имеет значения, того и гляди попытаются впарить тебе дом с видом на океан в Дун Мороге!$B$BВ последнее время, разыскивая высококачественные материалы, мне довелось наткнуться на толстые шкуры йети. Эти йети родом из Фераласа, их полно в Пещере Бешеного оврага, это к северо-востоку отсюда. Мне нужны эти шкуры, а за 10 штук я дам тебе на выбор одно из моих изделий. Так что если тебе по душе мое предложение, то давай, займись-ка!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 10 толстых шкур йети.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А как тебе текстура этих шкур, а? Если их как следует обработать, то они будут прочнее железа. Про эти шкуры вообще мало кто знает, а если еще учесть все те методы обработки, которые мне известны, то сразу видно: я сделаю по-настоящему качественные вещи… благодаря тебе, конечно же!$B$BНу что ж, а теперь выбери то, что хочешь за свои труды!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Принеси мне десять толстых шкур йети, и за это я дам тебе один из моих товаров. Я высоко ценю качество, так что награда тебе понравится, не сомневайся!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Пратту МакГруббену в крепость Оперенной Луны в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25450,'Борьба за качество','Забавно, как все меняется. Северные йети, бывало, снабжали меня самыми лучшими шкурами, но эти... Эти уже совершенно не того качества. Может, их одолела какая-то хворь?$B$BНо, к счастью, йети со Свирепого утеса – это к юго-востоку – живут припеваючи. Я не сомневаюсь, что их шкуры стали еще лучше, чем раньше!$B$BЗа десять таких шкур я дам тебе хорошую награду. Так что принеси их мне, и завершим нашу сделку.','Добудьте 10 шкур йети со Свирепого утеса.','Вернитесь к Пратту МакГруббену в крепость Оперенной Луны в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Борьба за качество',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Забавно, как все меняется. Северные йети, бывало, снабжали меня самыми лучшими шкурами, но эти... Эти уже совершенно не того качества. Может, их одолела какая-то хворь?$B$BНо, к счастью, йети со Свирепого утеса – это к юго-востоку – живут припеваючи. Я не сомневаюсь, что их шкуры стали еще лучше, чем раньше!$B$BЗа десять таких шкур я дам тебе хорошую награду. Так что принеси их мне, и завершим нашу сделку.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 10 шкур йети со Свирепого утеса.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Пратту МакГруббену в крепость Оперенной Луны в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (25451,'Безупречная шкура йети') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Безупречная шкура йети',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25452,'Знак качества','Я горжусь своим мастерством. Мою вещь сразу видно! А кто станет говорить, будто качество не имеет значения, пожалуй, захочет убедить тебя и в том, будто земля не хранит тайн!$B$BИ вот недавно в поисках качественных материалов я обнаружил толстые шкуры йети. Йети – это существа, которые водятся в Фераласе. Особенно много их к западу отсюда, в пещере Бешеного оврага. За каждые десять шкур ты получишь одно из моих кожаных изделий. Ну что, по рукам?','Добудьте 10 толстых шкур йети.','Вернитесь к Джангору Быстрому Страннику в Крепость Каменного Молота, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Знак качества',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я горжусь своим мастерством. Мою вещь сразу видно! А кто станет говорить, будто качество не имеет значения, пожалуй, захочет убедить тебя и в том, будто земля не хранит тайн!$B$BИ вот недавно в поисках качественных материалов я обнаружил толстые шкуры йети. Йети – это существа, которые водятся в Фераласе. Особенно много их к западу отсюда, в пещере Бешеного оврага. За каждые десять шкур ты получишь одно из моих кожаных изделий. Ну что, по рукам?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 10 толстых шкур йети.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джангору Быстрому Страннику в Крепость Каменного Молота, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25453,'Борьба за качество','Я не понимаю... Раньше с йети Бешеного оврага добывались самые лучшие шкуры, но эти... они прямо расползаются, а местами даже гниют. Должно быть, какая-то болезнь.$B$BПридется обратиться к другому источнику сырья. Шкуры йети из долины Свирепого утеса, что к югу отсюда, почти такие же прочные. Правда, сами йети намного опаснее; будь осторожнее на охоте, |3-6($c).','Добудьте 10 шкур йети со Свирепого утеса.','Вернитесь к Джангору Быстрому Страннику в Крепость Каменного Молота, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Борьба за качество',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я не понимаю... Раньше с йети Бешеного оврага добывались самые лучшие шкуры, но эти... они прямо расползаются, а местами даже гниют. Должно быть, какая-то болезнь.$B$BПридется обратиться к другому источнику сырья. Шкуры йети из долины Свирепого утеса, что к югу отсюда, почти такие же прочные. Правда, сами йети намного опаснее; будь осторожнее на охоте, |3-6($c).',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 10 шкур йети со Свирепого утеса.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джангору Быстрому Страннику в Крепость Каменного Молота, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25454,'Безупречная шкура йети','Вы добыли безупречную шкуру йети, особенно толстую и прочную – даже прочнее шкур йети из Пещеры Бешеного оврага.$B$BВам известно, что Джангору Быстрому Страннику в Крепости Каменного Молота всегда нужны шкуры йети, а уж эта его тем более заинтересует!','Отнесите безупречную шкуру йети Джангору Быстрому Страннику в крепость Каменного Молота в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Безупречная шкура йети',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы добыли безупречную шкуру йети, особенно толстую и прочную – даже прочнее шкур йети из Пещеры Бешеного оврага.$B$BВам известно, что Джангору Быстрому Страннику в Крепости Каменного Молота всегда нужны шкуры йети, а уж эта его тем более заинтересует!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите безупречную шкуру йети Джангору Быстрому Страннику в крепость Каменного Молота в Фераласе.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25455,'Проверка силы воли','Значится так, $gмалой:дорогуша;.$B$BТеперь тебе нужно незаметно подобраться поближе к какой-нибудь наге и накинуть на нее узду.$B$BТолько не подходи слишком близко – надо застать эту тварь врасплох.$B$BСделаешь все как положено – и ей придется подчиниться. Вот тогда мы покажем, кто тут главный!$B$BНатягивай удила покрепче, пока нага не сдастся, – и будет у тебя знатный скакун!$B$BИди же! Добудь себе лошадку! Вон, кажется, прямо к северу отсюда одна пасется...','Накиньте уздечку Эрунака на налетчика Зин\'жатара и тяните удила, пока тот не прекратит сопротивление.','Поговорите с Ренделом Огнеязыким в Конце отмели.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Проверка силы воли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Значится так, $gмалой:дорогуша;.$B$BТеперь тебе нужно незаметно подобраться поближе к какой-нибудь наге и накинуть на нее узду.$B$BТолько не подходи слишком близко – надо застать эту тварь врасплох.$B$BСделаешь все как положено – и ей придется подчиниться. Вот тогда мы покажем, кто тут главный!$B$BНатягивай удила покрепче, пока нага не сдастся, – и будет у тебя знатный скакун!$B$BИди же! Добудь себе лошадку! Вон, кажется, прямо к северу отсюда одна пасется...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Накиньте уздечку Эрунака на налетчика Зин\'жатара и тяните удила, пока тот не прекратит сопротивление.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Ренделом Огнеязыким в Конце отмели.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (25456,'Жив-здоров','Да-да, не сомневаюсь, что Фелора хочет, чтобы ты $gвернулся:вернулась;. Никакого уважения к инновациям. Когда я рассказал ей о модификациях, которые готовил для своего элементаля земли, она чуть не лопнула от злости.$B$BИди и расскажи ей, что у меня все супер-пупер. И добавь, что из моих будущих миллионов ей ничего не достанется.$B$BВпрочем, похоже, спать на камнях ее вполне устраивает.','Вернитесь к Фелоре Огненное Кольцо в Пещеру Серебряной Волны.','Значит, с Сэмом все в порядке? А как там его бедная помощница Фелиция? Рада слышать.$B$BНадеюсь, когда-нибудь он научится уважать стихии и относиться к ним не только как к средству для достижения своих целей.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жив-здоров',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Да-да, не сомневаюсь, что Фелора хочет, чтобы ты $gвернулся:вернулась;. Никакого уважения к инновациям. Когда я рассказал ей о модификациях, которые готовил для своего элементаля земли, она чуть не лопнула от злости.$B$BИди и расскажи ей, что у меня все супер-пупер. И добавь, что из моих будущих миллионов ей ничего не достанется.$B$BВпрочем, похоже, спать на камнях ее вполне устраивает.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь к Фелоре Огненное Кольцо в Пещеру Серебряной Волны.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Значит, с Сэмом все в порядке? А как там его бедная помощница Фелиция? Рада слышать.$B$BНадеюсь, когда-нибудь он научится уважать стихии и относиться к ним не только как к средству для достижения своих целей.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (25457,'Ron Targetting Test','Complete this quest.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ron Targetting Test',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Complete this quest.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (25458,'Генерал Скессеш','Убейте генерала Скессеша и заберите его голову.','Вернитесь к Шандрисе Оперенной Луне в Крепость Оперенной Луны в Фераласе.','Справься с Скессешем и одолеешь всю его армию.','Генерал Скессеш') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Генерал Скессеш',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте генерала Скессеша и заберите его голову.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Шандрисе Оперенной Луне в Крепость Оперенной Луны в Фераласе.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Справься с Скессешем и одолеешь всю его армию.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Генерал Скессеш',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (25458,'Поделом этим злобным созданиям. Пусть скользят себе обратно в море и не возвращаются никогда.$B$BА ты отлично проявил себя на поле битвы, Фоулар. Так что я попрошу тебя и дальше помогать нам в защите наших земель.','Так генерал сражен?') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Поделом этим злобным созданиям. Пусть скользят себе обратно в море и не возвращаются никогда.$B$BА ты отлично проявил себя на поле битвы, Фоулар. Так что я попрошу тебя и дальше помогать нам в защите наших земель.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Так генерал сражен?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25459,'Офидиофобия','Если есть что-то, чего я терпеть не могу, так это змеи. Любые змеи, разновидность не имеет значения.$B$BПри осмотре затонувших кораблей мне на глаза попалась стая морских змеев, круживших над обломками.$B$BЯ глаз не смогу сомкнуть, зная, что эти ужасные твари могут сюда проскользнуть.$B$BУмоляю, |3-6($c)! Разделайся с ними!','Убейте 4 солончаковых змей на Кургане Горрока.','Поговорите с Адаррой в Пещеру контрабандистов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Офидиофобия',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если есть что-то, чего я терпеть не могу, так это змеи. Любые змеи, разновидность не имеет значения.$B$BПри осмотре затонувших кораблей мне на глаза попалась стая морских змеев, круживших над обломками.$B$BЯ глаз не смогу сомкнуть, зная, что эти ужасные твари могут сюда проскользнуть.$B$BУмоляю, |3-6($c)! Разделайся с ними!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 4 солончаковых змей на Кургане Горрока.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Адаррой в Пещеру контрабандистов.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25460,'Земля поднимается','Последствия атаки культа Сумеречного Молота ощутимы даже здесь, вблизи Древа жизни.$B$BПока горит лес, сама земля восстает против нас в своем безумии.$B$BМы не можем позволить элементалям свободно разгуливать по нашей земле. Иди и помоги нашим бойцам расправиться с ними.','Убейте 8 раскаленных каменных элементалей.','Вернитесь к Анрену Искателю Теней у Нордрассила на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Земля поднимается',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Последствия атаки культа Сумеречного Молота ощутимы даже здесь, вблизи Древа жизни.$B$BПока горит лес, сама земля восстает против нас в своем безумии.$B$BМы не можем позволить элементалям свободно разгуливать по нашей земле. Иди и помоги нашим бойцам расправиться с ними.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 раскаленных каменных элементалей.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Анрену Искателю Теней у Нордрассила на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25461,'Вербовочный троллинг','Вол\'джин дал мне свои боевые барабаны и поручил заняться подготовкой новых рекрутов. Одна проблема – у нас не хватает добровольцев.$B$BЧто если я одолжу тебе один барабан, а ты донесешь призыв к войне на Колючий Холм? Даже если всего несколько троллей откликнется на зов, это повысит наши шансы на успех. Как только наберешь добровольцев, приводи их ко мне на обучение. Да, если тебе нужен транспорт до Колючего Холма, поговори с укротителем Марнлеком.','Я усердно их тренирую и мы не остановимся, пока не изгоним Залазана с наших островов.','Вернитесь к чемпиону Уру\'зину в деревню Сен\'джин.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вербовочный троллинг',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вол\'джин дал мне свои боевые барабаны и поручил заняться подготовкой новых рекрутов. Одна проблема – у нас не хватает добровольцев.$B$BЧто если я одолжу тебе один барабан, а ты донесешь призыв к войне на Колючий Холм? Даже если всего несколько троллей откликнется на зов, это повысит наши шансы на успех. Как только наберешь добровольцев, приводи их ко мне на обучение. Да, если тебе нужен транспорт до Колючего Холма, поговори с укротителем Марнлеком.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я усердно их тренирую и мы не остановимся, пока не изгоним Залазана с наших островов.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к чемпиону Уру\'зину в деревню Сен\'джин.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25462,'Медведя видно по полету','Не бойся медведей, обитающих в этой роще, |3-6($c), мне удалось немного успокоить их.$B$BНо я тревожусь за медвежат. Пожар загоняет малышей на деревья, а спуститься сами они не в состоянии. Мы должны вернуть их обратно на землю!$B$BЛетающие существа пугают медвежат, так что придется полазить по деревьям. Ищи в корнях опору для ног. Забирайся на деревья, хватай медвежат и скидывай их – НЕЖНО! – вот на этот тент.$B$BНе бойся, все пройдет как по маслу.','Заберитесь на дерево в Роще Трелей, снимайте с ветвей напуганных хиджальских медвежат и бросайте их на натянутый над землей тент. Это абсолютно безопасно.','Вернитесь к хранителю Талдросу в Рощу Трелей на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Медведя видно по полету',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не бойся медведей, обитающих в этой роще, |3-6($c), мне удалось немного успокоить их.$B$BНо я тревожусь за медвежат. Пожар загоняет малышей на деревья, а спуститься сами они не в состоянии. Мы должны вернуть их обратно на землю!$B$BЛетающие существа пугают медвежат, так что придется полазить по деревьям. Ищи в корнях опору для ног. Забирайся на деревья, хватай медвежат и скидывай их – НЕЖНО! – вот на этот тент.$B$BНе бойся, все пройдет как по маслу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заберитесь на дерево в Роще Трелей, снимайте с ветвей напуганных хиджальских медвежат и бросайте их на натянутый над землей тент. Это абсолютно безопасно.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к хранителю Талдросу в Рощу Трелей на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (25463,'Дорога к Сильвии','Поговорите с Сильвией в башне Эстулана.','Хорошо, что ты сюда добрался. Эстулан… в общем, с ним бывает довольно сложно. Нам приходится разбираться с ограми по приказу леди Шандрисы и ждать, пока он снизойдет до общения с нами.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дорога к Сильвии',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Сильвией в башне Эстулана.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо, что ты сюда добрался. Эстулан… в общем, с ним бывает довольно сложно. Нам приходится разбираться с ограми по приказу леди Шандрисы и ждать, пока он снизойдет до общения с нами.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25464,'Возвращение барона Геддона','Рагнарос – не единственный могущественный элементаль, вернувшийся в наш мир.$B$BУжасный барон Геддон возглавляет наступление, и мы должны положить конец его неистовству.$B$BПосох провидящего в огне показал свою силу. Возможно, его силы хватит, чтобы ослабить барона настолько, чтобы архидруиды смогли его обездвижить.$B$BИди, $n, и соблюдай осторожность: барон Геддон – мстительное и вероломное создание.','Используйте посох провидящего в огне, чтобы ослабить барона Геддона.','Вернитесь к Малфуриону Ярости Бури, который находится у Тихой роще на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение барона Геддона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Рагнарос – не единственный могущественный элементаль, вернувшийся в наш мир.$B$BУжасный барон Геддон возглавляет наступление, и мы должны положить конец его неистовству.$B$BПосох провидящего в огне показал свою силу. Возможно, его силы хватит, чтобы ослабить барона настолько, чтобы архидруиды смогли его обездвижить.$B$BИди, $n, и соблюдай осторожность: барон Геддон – мстительное и вероломное создание.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте посох провидящего в огне, чтобы ослабить барона Геддона.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Малфуриону Ярости Бури, который находится у Тихой роще на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25465,'Снова великаны','При помощи ультрасжимателя Зорбина облучите береговых странников и соберите 6 порций остаточного вещества.','Вернитесь к Зорбину Дребезгуну на Забытый берег в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Снова великаны',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','При помощи ультрасжимателя Зорбина облучите береговых странников и соберите 6 порций остаточного вещества.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Зорбину Дребезгуну на Забытый берег в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (25465,'Превосхитительнейше! Я не только благодарен тебе за великанов, но и очень рад видеть, что ты вроде как в целости и добром здравии. Хотя мой Ультрасжиматель всегда был абсолютно безопасен, так ведь?$B$BСпасибо за твои старания, Саонер. Теперь все гоблины будут относиться к тебе, как к другу. Вот, прими это в знак моей признательности!','Пришлось кое-что изменить, чтобы мой прибор больше не действовал на горных великанов. Хоть это и не я бегал там по берегу и облучал их, ночные эльфы выбили из меня всю медную мелочь, когда нашли этих громадин уменьшенными.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Превосхитительнейше! Я не только благодарен тебе за великанов, но и очень рад видеть, что ты вроде как в целости и добром здравии. Хотя мой Ультрасжиматель всегда был абсолютно безопасен, так ведь?$B$BСпасибо за твои старания, Саонер. Теперь все гоблины будут относиться к тебе, как к другу. Вот, прими это в знак моей признательности!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Пришлось кое-что изменить, чтобы мой прибор больше не действовал на горных великанов. Хоть это и не я бегал там по берегу и облучал их, ночные эльфы выбили из меня всю медную мелочь, когда нашли этих громадин уменьшенными.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25466,'Уменьшительного топлива мало не бывает!','Если я пойду наперекор себе, останусь тут и открою на Забытом берегу инженерную мастерскую, то мне придется иметь дело с этими назойливыми элементалями. Будь прокляты эти стихии, ничем их не сдержишь!$B$BК счастью для меня, а теперь и для тебя, мой подающий надежды агент-провокатор, эти элементали представляют собой идеальный источник энергии для доработки моего Ультрасжимателя, так что самое время задать им хорошую трепку! Но когда будешь гонять их, не забудь собрать для меня немного ядер водных элементалей!','Соберите 10 ядер элементалей воды, убивая морских элементалей или морских валов.','Вернитесь к Зорбину Дребезгуну на Забытый берег в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уменьшительного топлива мало не бывает!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если я пойду наперекор себе, останусь тут и открою на Забытом берегу инженерную мастерскую, то мне придется иметь дело с этими назойливыми элементалями. Будь прокляты эти стихии, ничем их не сдержишь!$B$BК счастью для меня, а теперь и для тебя, мой подающий надежды агент-провокатор, эти элементали представляют собой идеальный источник энергии для доработки моего Ультрасжимателя, так что самое время задать им хорошую трепку! Но когда будешь гонять их, не забудь собрать для меня немного ядер водных элементалей!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 ядер элементалей воды, убивая морских элементалей или морских валов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Зорбину Дребезгуну на Забытый берег в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (25466,'Отличнобалденнейше! Уж я с этими ядрами теперь поработаю! Да и элементалей на берегу теперь стало поменьше, так что больше не придется засыпать в слезах от мысли, что я устроил свою лавку в наихудшем месте, какое только можно себе представить!$B$BСпасибо, Румуул, спасибо за все твои старания! Хоть я сейчас и не в самом лучшем финансовом положении, но все же прими от меня понятную и полезную для тебя благодарность: ценности!','Я мог бы долго и нудно разглагольствовать о технических деталях и о том, зачем мне нужны ядра элементалей, но вместо этого я лучше отсыплю тебе звонких монет за труды да дам еще кое-какую награду. Как тебе такое предложение?') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличнобалденнейше! Уж я с этими ядрами теперь поработаю! Да и элементалей на берегу теперь стало поменьше, так что больше не придется засыпать в слезах от мысли, что я устроил свою лавку в наихудшем месте, какое только можно себе представить!$B$BСпасибо, Румуул, спасибо за все твои старания! Хоть я сейчас и не в самом лучшем финансовом положении, но все же прими от меня понятную и полезную для тебя благодарность: ценности!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я мог бы долго и нудно разглагольствовать о технических деталях и о том, зачем мне нужны ядра элементалей, но вместо этого я лучше отсыплю тебе звонких монет за труды да дам еще кое-какую награду. Как тебе такое предложение?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25467,'Зоб Кликлака','Вы с удовольствием отмечаете, что даже несмотря на то, что карта изрядно помята крабьими клешнями, ее вполне можно прочитать.$B$BНа ней отчетливо видно, что в лесу Келп’тар прямо за гигантским моллюском зарыт сейф.$B$BНеплохо нарисованная сюжетная сценка на обороте карты повествует о том, что владельцем сундука, а заодно и ключом от оного, поужинало гигантское ракообразное по имени Кликлак.','Добудьте у Кликлака заржавевший ключ и отоприте полузакопанный сундучок в лесу Келп’тар.','Слух ласкает звук открывающегося сундучка, а взгляд – зрелище некогда спрятанного сокровища.','Замочную скважину сундучка облепили ракушки, но замок, похоже, цел.','Отоприте заржавевшим ключом полузакопанный сундучок в лесу Келп’тар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зоб Кликлака',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы с удовольствием отмечаете, что даже несмотря на то, что карта изрядно помята крабьими клешнями, ее вполне можно прочитать.$B$BНа ней отчетливо видно, что в лесу Келп’тар прямо за гигантским моллюском зарыт сейф.$B$BНеплохо нарисованная сюжетная сценка на обороте карты повествует о том, что владельцем сундука, а заодно и ключом от оного, поужинало гигантское ракообразное по имени Кликлак.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте у Кликлака заржавевший ключ и отоприте полузакопанный сундучок в лесу Келп’тар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Слух ласкает звук открывающегося сундучка, а взгляд – зрелище некогда спрятанного сокровища.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Замочную скважину сундучка облепили ракушки, но замок, похоже, цел.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отоприте заржавевшим ключом полузакопанный сундучок в лесу Келп’тар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25468,'Силы природы: чудесные дракончики','Может, это покажется тебе странным, но чудесные дракончики становятся весьма грозными противниками, если их соответствующим образом обучить. При помощи магии они могут творить на поле боя настоящие чудеса... Впитывать магию, перенаправлять ее потоки или полностью сводить на нет все усилия вражеских колдунов.$B$BПоодиночке они практически беспомощны, зато, собравшись вместе, способны переломить ход битвы. Найти дракончиков можно на лугах к северо-западу отсюда, но берегись, там везде полно воинов Орды.','Используйте манок для чудесных дракончиков Джесаны, чтобы призвать 10 радужных дракончиков или летучих хамелеонов.','Вернитесь к укротительнице Джесане в Тень Ветвей в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Силы природы: чудесные дракончики',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Может, это покажется тебе странным, но чудесные дракончики становятся весьма грозными противниками, если их соответствующим образом обучить. При помощи магии они могут творить на поле боя настоящие чудеса... Впитывать магию, перенаправлять ее потоки или полностью сводить на нет все усилия вражеских колдунов.$B$BПоодиночке они практически беспомощны, зато, собравшись вместе, способны переломить ход битвы. Найти дракончиков можно на лугах к северо-западу отсюда, но берегись, там везде полно воинов Орды.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте манок для чудесных дракончиков Джесаны, чтобы призвать 10 радужных дракончиков или летучих хамелеонов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к укротительнице Джесане в Тень Ветвей в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (25468,'Милашки, правда? Их детеныши еще симпатичнее.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Милашки, правда? Их детеныши еще симпатичнее.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25469,'Силы природы: горные великаны','Горные великаны издавна были самыми могущественными союзниками ночных эльфов. Сами горы приходили к нам на помощь.$B$BРедкие безумцы отваживались вступить в бой с шагающей скалой. Всего несколько великанов могли переломить исход любой битвы.$B$BВ последнее время большинство горных великанов пали жертвами какой-то странной болезни, но несколько еще бродят к юго-западу отсюда.','Используйте манок великанов Джесаны, чтобы призвать 5 горных великанов.','Вернитесь к укротительнице Джесане в Тень Ветвей в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Силы природы: горные великаны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Горные великаны издавна были самыми могущественными союзниками ночных эльфов. Сами горы приходили к нам на помощь.$B$BРедкие безумцы отваживались вступить в бой с шагающей скалой. Всего несколько великанов могли переломить исход любой битвы.$B$BВ последнее время большинство горных великанов пали жертвами какой-то странной болезни, но несколько еще бродят к юго-западу отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте манок великанов Джесаны, чтобы призвать 5 горных великанов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к укротительнице Джесане в Тень Ветвей в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (25469,'Отлично!$B$BРоось, тебе удалось существенно усилить наши отряды здесь, и благодаря твоим усилиям от Орды спасено множество невинных душ. Теперь наша армия готова к бою, и крепость Оперенной Луны устоит перед силами Орды.$B$BПо воле леди Оперенной Луны я вручаю тебе это оружие Часовых.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично!$B$BРоось, тебе удалось существенно усилить наши отряды здесь, и благодаря твоим усилиям от Орды спасено множество невинных душ. Теперь наша армия готова к бою, и крепость Оперенной Луны устоит перед силами Орды.$B$BПо воле леди Оперенной Луны я вручаю тебе это оружие Часовых.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25470,'Повелительница тигров','Помнишь тех лягушек, которых мы сделали моими глазами и ушами? Представляешь, им удалось обнаружить кое-что интересное.$B$BНа юго-восточном острове обитает тигрица, которую обходят стороной остальные кошки. Этот зверь... я никогда не видела ничего подобного.$B$BУ нее звериные повадки, но она явно обладает весьма незаурядным разумом. Это существо может стать нам верным союзником.$B$BЯ вселю в тебя дух тигра, чтобы ты $gсмог:смогла; бросить вызов этой большой кошке. Постарайся завоевать ее доверие и привлечь на нашу сторону в грядущей битве.','Почувствовав в себе дух тигра, выманите тигрицу-матриарха из убежища и победите ее в битве, используя новые умения.','Глаза лягушек не обманули нас. Так эта тигрица на самом деле друид и наш союзник? Мы не могли и наедятся на лучший исход. Это добрый знак.','Вернитесь к Вол\'джину в деревню Сен\'джин.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Повелительница тигров',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Помнишь тех лягушек, которых мы сделали моими глазами и ушами? Представляешь, им удалось обнаружить кое-что интересное.$B$BНа юго-восточном острове обитает тигрица, которую обходят стороной остальные кошки. Этот зверь... я никогда не видела ничего подобного.$B$BУ нее звериные повадки, но она явно обладает весьма незаурядным разумом. Это существо может стать нам верным союзником.$B$BЯ вселю в тебя дух тигра, чтобы ты $gсмог:смогла; бросить вызов этой большой кошке. Постарайся завоевать ее доверие и привлечь на нашу сторону в грядущей битве.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Почувствовав в себе дух тигра, выманите тигрицу-матриарха из убежища и победите ее в битве, используя новые умения.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Глаза лягушек не обманули нас. Так эта тигрица на самом деле друид и наш союзник? Мы не могли и наедятся на лучший исход. Это добрый знак.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Вол\'джину в деревню Сен\'джин.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (25471,'Через пропасть','Чтобы узнать о замыслах наг, нам придется углубиться еще дальше в Вайш\'ир.$B$BОтправляйся в Бездну Кромешной Тьмы – глубокую расщелину на западной границе леса Келп\'тар. За ней ты увидишь вход в Грот Затуманенного Света, окруженный буйной растительностью.$B$BОт входа в пещеру до поверхности – неблизкий путь, но там находится пара моих друзей, они тебе помогут.','Поговорите с предсказателем Гадрой в Гроте Затуманенного Света.','Привет, дружище! Вид у тебя внушительнее, чем у большинства путников.$B$BРасполагайся. Чувствуй себя как дома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Через пропасть',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чтобы узнать о замыслах наг, нам придется углубиться еще дальше в Вайш\'ир.$B$BОтправляйся в Бездну Кромешной Тьмы – глубокую расщелину на западной границе леса Келп\'тар. За ней ты увидишь вход в Грот Затуманенного Света, окруженный буйной растительностью.$B$BОт входа в пещеру до поверхности – неблизкий путь, но там находится пара моих друзей, они тебе помогут.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с предсказателем Гадрой в Гроте Затуманенного Света.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Привет, дружище! Вид у тебя внушительнее, чем у большинства путников.$B$BРасполагайся. Чувствуй себя как дома.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25472,'Посох провидящего в огне','Могущественный артефакт под названием посох провидящего в огне был утрачен во время нападения вражеских войск. Это был древний костяной посох, даровавший своему владельцу огромную власть над стихией огня.$B$BЕго фрагменты усеивают землю вокруг нас. Найди их и принеси Малфуриону. Возможно, сила этого артефакта все еще сможет принести пользу.','Найдите 8 фрагментов костяного посоха.','Вернитесь к Малфуриону Ярости Бури, который находится в Тихой роще на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Посох провидящего в огне',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Могущественный артефакт под названием посох провидящего в огне был утрачен во время нападения вражеских войск. Это был древний костяной посох, даровавший своему владельцу огромную власть над стихией огня.$B$BЕго фрагменты усеивают землю вокруг нас. Найди их и принеси Малфуриону. Возможно, сила этого артефакта все еще сможет принести пользу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите 8 фрагментов костяного посоха.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Малфуриону Ярости Бури, который находится в Тихой роще на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (25473,'"Каджа-Кола"','Хамми сегодня устраивает банкет в твою честь и попросила меня отгрузить ей по этому случаю "Каджа-Колу".$B$BОй... это ведь должен был быть сюрприз! Если что, я тебе ничего не говорил!$B$BЛадно уж, в последнее время производство напитка совсем встало, так что тут все, что мне удалось наскрести. Отнесешь ей "Каджа-Колу"?','Отнесите упаковку "Каджа-Колы" Хамми Кофельнагель, находящейся в штаб-квартире ТКК на Кезане.','Как известно, "Каджа-Колой" торгуют по всему городу. Это самый продаваемый продукт картеля Трюмных Вод за всю историю фирмы!$B$BПросто помни: имидж – это все! Особенно, если мы собираемся получить для тебя повышение.$B$BХотя нет... погоди... все – это прибыль! Взрывы – на втором месте. А на третьем – имидж!','<Хамми смотрит на упаковку "Каджа-Колы", как будто опасаясь, что та вот-вот взорвется.>$B$BЭто что, все?! Нам нужно гораздо больше!$B$BКлянусь, я вышвырну Промокаха вон из компании! Если раньше голову не оторву!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','"Каджа-Кола"',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хамми сегодня устраивает банкет в твою честь и попросила меня отгрузить ей по этому случаю "Каджа-Колу".$B$BОй... это ведь должен был быть сюрприз! Если что, я тебе ничего не говорил!$B$BЛадно уж, в последнее время производство напитка совсем встало, так что тут все, что мне удалось наскрести. Отнесешь ей "Каджа-Колу"?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите упаковку "Каджа-Колы" Хамми Кофельнагель, находящейся в штаб-квартире ТКК на Кезане.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Как известно, "Каджа-Колой" торгуют по всему городу. Это самый продаваемый продукт картеля Трюмных Вод за всю историю фирмы!$B$BПросто помни: имидж – это все! Особенно, если мы собираемся получить для тебя повышение.$B$BХотя нет... погоди... все – это прибыль! Взрывы – на втором месте. А на третьем – имидж!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Хамми смотрит на упаковку "Каджа-Колы", как будто опасаясь, что та вот-вот взорвется.>$B$BЭто что, все?! Нам нужно гораздо больше!$B$BКлянусь, я вышвырну Промокаха вон из компании! Если раньше голову не оторву!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (25474,'Once More, With Eeling [DEPRICATED]','Угри – одни из самых мерзких тварей во всем Азероте.$B$BРазумеется, найдутся те, кто будет заливать, будто ничего не имеют против угрей; есть и те, кто утверждает, будто бы они ЛЮБЯТ угрей.$B$BВсе это вранье.$B$BПравда же в том, что угрей не любит никто. Мало того – даже угри не любят угрей!$B$BЖизнь в Азероте станет прекрасной и удивительной, как только все забудут о том, что такое угорь, выползающий из морской пучины и кусающий тебя.$B$BЗа нос.','Убейте 15 любых угрей в лесу Келп’тар.','<…просто отвратительно>','Угорь') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Once More, With Eeling [DEPRICATED]',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Угри – одни из самых мерзких тварей во всем Азероте.$B$BРазумеется, найдутся те, кто будет заливать, будто ничего не имеют против угрей; есть и те, кто утверждает, будто бы они ЛЮБЯТ угрей.$B$BВсе это вранье.$B$BПравда же в том, что угрей не любит никто. Мало того – даже угри не любят угрей!$B$BЖизнь в Азероте станет прекрасной и удивительной, как только все забудут о том, что такое угорь, выползающий из морской пучины и кусающий тебя.$B$BЗа нос.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 15 любых угрей в лесу Келп’тар.',`objectives_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','<…просто отвратительно>',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Угорь',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (25475,'Отнесите аварийный маяк к самонаводящемуся роботу Карлса, который находится в пещере близ долины Свирепого утеса.','Вы помещаете яйцо… то есть аварийный маячок… в цыпленка… то есть в самонаводящегося робота.$B$BРобот начинает гудеть, жужжать и пытается подняться. Когда он оживает, вы вновь слышите голос Карлса, но на этот раз из самого робота:$B$B"Что ж, по крайней мере, КПХ-22/FE работает, но он требует серьезного ремонта! Нести его, пожалуй, будет тяжеловато, но есть другое предложение! Не присмотришь ли за ним еще некоторое время?"','Вы нашли нечто, напоминающее останки... робота-цыпленка? Из яйца опять раздается трескучий голос:$B$B"Да, отличная работа! Это и есть мой самонаводящийся робот, хотя, судя по моим сенсорам, ему понадобится дать хорошенький разряд – иначе он не долетит до Пиратской Бухты. Давайте-ка поместите в него маячок, а дальше он сам все сделает!"') ON DUPLICATE KEY UPDATE `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите аварийный маяк к самонаводящемуся роботу Карлса, который находится в пещере близ долины Свирепого утеса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы помещаете яйцо… то есть аварийный маячок… в цыпленка… то есть в самонаводящегося робота.$B$BРобот начинает гудеть, жужжать и пытается подняться. Когда он оживает, вы вновь слышите голос Карлса, но на этот раз из самого робота:$B$B"Что ж, по крайней мере, КПХ-22/FE работает, но он требует серьезного ремонта! Нести его, пожалуй, будет тяжеловато, но есть другое предложение! Не присмотришь ли за ним еще некоторое время?"',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы нашли нечто, напоминающее останки... робота-цыпленка? Из яйца опять раздается трескучий голос:$B$B"Да, отличная работа! Это и есть мой самонаводящийся робот, хотя, судя по моим сенсорам, ему понадобится дать хорошенький разряд – иначе он не долетит до Пиратской Бухты. Давайте-ка поместите в него маячок, а дальше он сам все сделает!"',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`completedtext_loc8`) VALUES (25476,'Вернитесь к Карлсу Пропеллерзу в Пиратскую Бухту, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Карлсу Пропеллерзу в Пиратскую Бухту, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25477,'Лучше поздно, чем ногами вперед','Приветствую тебя.$B$BОтрадно видеть, что ты $gвернулся:вернулась; из боя $gцелым и невредимым:целой и невредимой;.$B$BПока Эрунак ищет для нас безопасное место, я помогу тебе освоить более легкий способ передвижения.$B$BВот, приготовила приманку на морскую черепаху. Не бог весть что, но подчинить с ее помощью черепаху можно.$B$BКогда полностью освоишься, возвращайся верхом ко мне.','Подманите пятнистую морскую черепаху при помощи приманки Моаны и возвращайтесь на ней к Моане.','Вот ведь невезенье...$B$BС другой стороны, хорошо хоть, что ты сам не пострадал.','Вернитесь к Моане Штормовое Копыто в Конец отмели.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лучше поздно, чем ногами вперед',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приветствую тебя.$B$BОтрадно видеть, что ты $gвернулся:вернулась; из боя $gцелым и невредимым:целой и невредимой;.$B$BПока Эрунак ищет для нас безопасное место, я помогу тебе освоить более легкий способ передвижения.$B$BВот, приготовила приманку на морскую черепаху. Не бог весть что, но подчинить с ее помощью черепаху можно.$B$BКогда полностью освоишься, возвращайся верхом ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Подманите пятнистую морскую черепаху при помощи приманки Моаны и возвращайтесь на ней к Моане.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот ведь невезенье...$B$BС другой стороны, хорошо хоть, что ты сам не пострадал.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Моане Штормовое Копыто в Конец отмели.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (25478,'К Вершине','Мы организуем лагерь для беженцев со всей Тысячи Игл на Вершине Западного Предела. Гоблин Дизликс Сребросвищ даст тебе моего ветрокрыла, чтобы ты спокойно туда $gдолетел:долетела;. Когда приземлишься, поговори с Канати Серое Облако.$B$BПоторопись – ради спасения жизней!','Возьмите ветрокрыла у Дизликса Сребросвища и поговорите с Канати Серое Облако на Вершине Западного Предела в Тысяче Игл.','Тебя послал Нице? Отлично! Нам как раз нужна твоя помощь!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','К Вершине',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы организуем лагерь для беженцев со всей Тысячи Игл на Вершине Западного Предела. Гоблин Дизликс Сребросвищ даст тебе моего ветрокрыла, чтобы ты спокойно туда $gдолетел:долетела;. Когда приземлишься, поговори с Канати Серое Облако.$B$BПоторопись – ради спасения жизней!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возьмите ветрокрыла у Дизликса Сребросвища и поговорите с Канати Серое Облако на Вершине Западного Предела в Тысяче Игл.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебя послал Нице? Отлично! Нам как раз нужна твоя помощь!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (25479,'В Новый Таланаар','Мы организуем лагерь для беженцев со всей Тысячи Игл в Новом Таланааре. Гоблин Дизликс Сребросвищ даст тебе моего гиппогрифа, чтобы ты спокойно туда $gдолетел:долетела;. Когда приземлишься, поговори с Кариссией Лунной Охотницей.$B$BПоторопись – ради спасения жизней!','Возьмите гиппогрифа у Дизликса Сребросвища и поговорите с Кариссией Лунной Охотницей в Новом Таланааре в Фераласе.','Тебя послала Тиссиана? Отлично! Нам как раз нужна твоя помощь!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В Новый Таланаар',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы организуем лагерь для беженцев со всей Тысячи Игл в Новом Таланааре. Гоблин Дизликс Сребросвищ даст тебе моего гиппогрифа, чтобы ты спокойно туда $gдолетел:долетела;. Когда приземлишься, поговори с Кариссией Лунной Охотницей.$B$BПоторопись – ради спасения жизней!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возьмите гиппогрифа у Дизликса Сребросвища и поговорите с Кариссией Лунной Охотницей в Новом Таланааре в Фераласе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебя послала Тиссиана? Отлично! Нам как раз нужна твоя помощь!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25480,'Танец духов','Самое время подумать о том, когда выступать. Чемпион Уру\'зин сообщил мне, что его бойцы уже готовы. Вы с Ванирой тоже хорошо потрудились – собрали много полезных сведений и нашли новых союзников.$B$BПосоветуйся с духами. Надо узнать, когда настанет время действовать. $B$BНайди знахаря Хез\'тока рядом с кругом ритуальных танцев. Он ждет тебя, чтобы начать ритуал.','Когда вы будете готовы к общению с духами, поговорите с знахарем Хез\'током, который ждет вас рядом с кругом ритуальных танцев.','Что ж, мы поступим так, как советуют духи. С мудростью предков и силой великих духов племени Чёрного Копья мы отвоюем то, что принадлежит нам по праву!','Вернитесь к Вол\'джину в деревню Сен\'джин') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Танец духов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Самое время подумать о том, когда выступать. Чемпион Уру\'зин сообщил мне, что его бойцы уже готовы. Вы с Ванирой тоже хорошо потрудились – собрали много полезных сведений и нашли новых союзников.$B$BПосоветуйся с духами. Надо узнать, когда настанет время действовать. $B$BНайди знахаря Хез\'тока рядом с кругом ритуальных танцев. Он ждет тебя, чтобы начать ритуал.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Когда вы будете готовы к общению с духами, поговорите с знахарем Хез\'током, который ждет вас рядом с кругом ритуальных танцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что ж, мы поступим так, как советуют духи. С мудростью предков и силой великих духов племени Чёрного Копья мы отвоюем то, что принадлежит нам по праву!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Вол\'джину в деревню Сен\'джин',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25481,'В Новый Таланаар','Мы организуем лагерь для беженцев со всей Тысячи Игл в Новом Таланааре. Сейяла Ночной Шорох даст тебе моего гиппогрифа, чтобы ты спокойно туда $gдолетел:долетела;. Когда приземлишься, поговори с Кариссией Лунной Охотницей.$B$BПоторопись – ради спасения жизней!','Возьмите гиппогрифа у Сейялы Ночной Шорох и поговорите с Кариссией Лунной Охотницей в Новом Таланааре в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В Новый Таланаар',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы организуем лагерь для беженцев со всей Тысячи Игл в Новом Таланааре. Сейяла Ночной Шорох даст тебе моего гиппогрифа, чтобы ты спокойно туда $gдолетел:долетела;. Когда приземлишься, поговори с Кариссией Лунной Охотницей.$B$BПоторопись – ради спасения жизней!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возьмите гиппогрифа у Сейялы Ночной Шорох и поговорите с Кариссией Лунной Охотницей в Новом Таланааре в Фераласе.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25487,'Тебе нужно каноэ, чтобы добраться до соляных равнин? Но ведь гоночная трасса наверняка разрушена!$B$BКак бы там ни было, за твою храбрость ты получишь последнее каноэ!','Поговорите с Мотегой Огненной Гривой у Вершины Западного Предела в Тысяче Игл.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебе нужно каноэ, чтобы добраться до соляных равнин? Но ведь гоночная трасса наверняка разрушена!$B$BКак бы там ни было, за твою храбрость ты получишь последнее каноэ!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Мотегой Огненной Гривой у Вершины Западного Предела в Тысяче Игл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (25488,'Двое в лодке','$GГотов:Готова; отправляться, |3-6($c)? Один из стражей доставит тебя к Виражам на Миражах.$B$BЕсли там кто-то уцелел, сделай милость, помоги им.$B$BДа хранит тебя богиня!','Поговорите с Пшиксом Медноштифом на гоночной барже Пшикса и Поззика в Тысяче Игл.','Да?! Я что, прерывал ваш увлекательный спор?$B$BНет-нет, пожалуйста, продолжай. Ты ведь наверняка отвлекаешь меня по очень важному делу. Гораздо более важному, чем спасение всех находящихся тут.$B$B<Пшикс нетерпеливо постукивает ногой.>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Двое в лодке',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$GГотов:Готова; отправляться, |3-6($c)? Один из стражей доставит тебя к Виражам на Миражах.$B$BЕсли там кто-то уцелел, сделай милость, помоги им.$B$BДа хранит тебя богиня!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Пшиксом Медноштифом на гоночной барже Пшикса и Поззика в Тысяче Игл.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да?! Я что, прерывал ваш увлекательный спор?$B$BНет-нет, пожалуйста, продолжай. Ты ведь наверняка отвлекаешь меня по очень важному делу. Гораздо более важному, чем спасение всех находящихся тут.$B$B<Пшикс нетерпеливо постукивает ногой.>',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (25492,'Борьба с огнем','Вернитесь к Райне Песни Пера в Святилище Малорна на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Борьба с огнем',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Райне Песни Пера в Святилище Малорна на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25493,'Свежая наживка','Хорошо. Используем их как наживку, пока внутренности не остыли.$B$BМой план таков...','Ты уже собрал внутренности?$B$BГончие Недр не встречаются в этой части мира, они появились здесь вместе с Сумеречным Молотом, сектанты которого призвали этих чудовищ из-под земли. Как бы мы ни старались, сейчас их число сократить невозможно.','Вернитесь к верховному друиду Хамуулу Руническому Тотему, находящемуся в Святилище Малорна на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Свежая наживка',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо. Используем их как наживку, пока внутренности не остыли.$B$BМой план таков...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты уже собрал внутренности?$B$BГончие Недр не встречаются в этой части мира, они появились здесь вместе с Сумеречным Молотом, сектанты которого призвали этих чудовищ из-под земли. Как бы мы ни старались, сейчас их число сократить невозможно.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному друиду Хамуулу Руническому Тотему, находящемуся в Святилище Малорна на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25494,'Ошейник чемпиона','Какой грозный малыш!$B$BЕсли он собирается сражаться, необходимо снабдить его крепким шипастым ошейником.$B$BМатриарх василисков устроила свое логово на дороге в Зимние Ключи. Принеси мне ее шипастую шкуру, и мы соорудим ошейник для нашего маленького бойца.','Убейте чешуеспинного матриарха и добудьте шипастую шкуру василиска.','Отлично. Теперь этот парень готов к бою.','Удалось достать шкуру?','Вернитесь к наставнику Деворану в Кузню Мольбы на Хиджале.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ошейник чемпиона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Какой грозный малыш!$B$BЕсли он собирается сражаться, необходимо снабдить его крепким шипастым ошейником.$B$BМатриарх василисков устроила свое логово на дороге в Зимние Ключи. Принеси мне ее шипастую шкуру, и мы соорудим ошейник для нашего маленького бойца.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте чешуеспинного матриарха и добудьте шипастую шкуру василиска.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично. Теперь этот парень готов к бою.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось достать шкуру?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к наставнику Деворану в Кузню Мольбы на Хиджале.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (25495,'Подготовка к битве','Вол\'джин уже надевает свои доспехи и готовит воинов к битве. Он велел передать, что ты $Gдолжен:должна; встретиться с ним и Ванирой на восточном острове.$B$BИменно оттуда начнется нападение на Залазана. Да благословят тебя предки, $n. Без твоей помощи нам не удалось бы так хорошо подготовить эту военную кампанию. Да, если тебе нужен транспорт, поговори с укротителем Марнлеком – он стоит на юге отсюда.','Встретьтесь с Вол\'джином на острове к востоку от военного лагеря. Если вам нужен транспорт, поговорите с укротителем Марнлеком.','Наконец, все будет готово. Теперь мы покажем Залазану, что случится с тем, кто бросит вызов Черному Копью!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подготовка к битве',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вол\'джин уже надевает свои доспехи и готовит воинов к битве. Он велел передать, что ты $Gдолжен:должна; встретиться с ним и Ванирой на восточном острове.$B$BИменно оттуда начнется нападение на Залазана. Да благословят тебя предки, $n. Без твоей помощи нам не удалось бы так хорошо подготовить эту военную кампанию. Да, если тебе нужен транспорт, поговори с укротителем Марнлеком – он стоит на юге отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Встретьтесь с Вол\'джином на острове к востоку от военного лагеря. Если вам нужен транспорт, поговорите с укротителем Марнлеком.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Наконец, все будет готово. Теперь мы покажем Залазану, что случится с тем, кто бросит вызов Черному Копью!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25497,'Снова в седле','Наше положение близко к отчаянному, r.$B$BМы должны заняться нагами и их заложниками, но приступать без должной подготовки глупо. В нынешних условиях под должной подготовкой я имею в виду способ передвигаться быстрее.$B$BВон те акулы, очевидно, обожают черепашье мясо. Сдается мне, это нам на руку.','Приготовьте из 6 кусков черепашьего мяса наживку для акул.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Снова в седле',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наше положение близко к отчаянному, r.$B$BМы должны заняться нагами и их заложниками, но приступать без должной подготовки глупо. В нынешних условиях под должной подготовкой я имею в виду способ передвигаться быстрее.$B$BВон те акулы, очевидно, обожают черепашье мясо. Сдается мне, это нам на руку.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Приготовьте из 6 кусков черепашьего мяса наживку для акул.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25498,'Наживка для акулы','<Эрунак говорит, одновременно укладывая черепашье мясо в сетку.>$B$BПриготовься, $n. Понятия не имею, что из этого выйдет, но если мы хотим выручить твоих друзей, то выбирать не приходится.$B$BВозьми эту сетку и брось в воду возле затонувшего якоря к юго-востоку отсюда. Как привлечешь акулу, оседлай ее всеми правдами и неправдами и возвращайся ко мне.$B$BЕсли все получится, в твоем распоряжении будет весьма грозное средство передвижения.','Бросьте наживку для акулы возле затонувшего якоря, оседлайте акулу и возвращайтесь верхом к Эрунаку.','Поговорите с Эрунаком в Конце отмели.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наживка для акулы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Эрунак говорит, одновременно укладывая черепашье мясо в сетку.>$B$BПриготовься, $n. Понятия не имею, что из этого выйдет, но если мы хотим выручить твоих друзей, то выбирать не приходится.$B$BВозьми эту сетку и брось в воду возле затонувшего якоря к юго-востоку отсюда. Как привлечешь акулу, оседлай ее всеми правдами и неправдами и возвращайся ко мне.$B$BЕсли все получится, в твоем распоряжении будет весьма грозное средство передвижения.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Бросьте наживку для акулы возле затонувшего якоря, оседлайте акулу и возвращайтесь верхом к Эрунаку.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Эрунаком в Конце отмели.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25499,'Тренировка ловкости: беги со всех ног!','Перед тем как мы продолжим, нам надо привести тебя в форму.$B$BПреданность древним богам не спасет тебя, когда за тобой будет мчаться какой-нибудь зеленый дракон. Тебе надо быть $gлегким:легкой; на подъем, если ты понимаешь, о чем я.$B$BХватит болтать. Призовем тебе тренера... твоя задача – бегать от него, не покидая лагерь.$B$BВперед!','Бегайте от пылающего тренажера в Кузне Мольбы в течение 1 минуты.','О. Ты все еще жив.$B$BНеплохо.','Вернитесь к наставнице Милве в Кузню Мольбы на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тренировка ловкости: беги со всех ног!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Перед тем как мы продолжим, нам надо привести тебя в форму.$B$BПреданность древним богам не спасет тебя, когда за тобой будет мчаться какой-нибудь зеленый дракон. Тебе надо быть $gлегким:легкой; на подъем, если ты понимаешь, о чем я.$B$BХватит болтать. Призовем тебе тренера... твоя задача – бегать от него, не покидая лагерь.$B$BВперед!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Бегайте от пылающего тренажера в Кузне Мольбы в течение 1 минуты.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О. Ты все еще жив.$B$BНеплохо.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к наставнице Милве в Кузню Мольбы на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25500,'Слова, что нужно произнести','Готово! Речь написана, $n! То, что надо для начала битвы... вдохновляющая, написанная выразительным языком, как будто взывающая к сердцам гномов! Никогда у меня не получалось речи лучше!$B$BПринеси ее капитану Ступу Искражу – пусть он сам скажет, что делать дальше.','Передайте речь капитану Ступу Искражу, который ждет вас в Поселке Сталежара.','Это речь Тоби? Фантастика!$B$BРекрут, вы сделали все, о чем мы могли просить, и армия Гномрегана благодарит вас!$B$BСейчас у нас есть ударная группа, направляющаяся в Гномреган, и без вашей помощи это было бы невозможно. За всю вашу помощь мы хотели бы, чтобы вы присоединились к Гномреганским резервам!$B$BПлатят не очень хорошо, но вы получите этот шикарный шлем. Когда-нибудь вам это может понадобиться!','Отдайте речь главному механику Меггакруту.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Слова, что нужно произнести',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Готово! Речь написана, $n! То, что надо для начала битвы... вдохновляющая, написанная выразительным языком, как будто взывающая к сердцам гномов! Никогда у меня не получалось речи лучше!$B$BПринеси ее капитану Ступу Искражу – пусть он сам скажет, что делать дальше.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Передайте речь капитану Ступу Искражу, который ждет вас в Поселке Сталежара.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это речь Тоби? Фантастика!$B$BРекрут, вы сделали все, о чем мы могли просить, и армия Гномрегана благодарит вас!$B$BСейчас у нас есть ударная группа, направляющаяся в Гномреган, и без вашей помощи это было бы невозможно. За всю вашу помощь мы хотели бы, чтобы вы присоединились к Гномреганским резервам!$B$BПлатят не очень хорошо, но вы получите этот шикарный шлем. Когда-нибудь вам это может понадобиться!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отдайте речь главному механику Меггакруту.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25501,'Ученик браконьера','Я вижу новое лицо, не так ли? Тебе подфартило: здесь, благодаря моему мясорезу, монеты льются рекой. Идешь на охоту, убиваешь несколько скорпидов или гиен, может быть, пару василисков, включаешь мясорез, а дальше он сам делает свою работу! Он специально запрограммирован таким образом, чтобы собирать в выделенный резервуар все ценные части тела твоей добычи.$b$bЕсли предложение заинтересовало тебя, возьми один из них и отправляйся поначалу на северо-запад, к заставе Скорбных Песков. Принеси мясорез с наполненным резервуаром, а я заплачу тебе за содержимое.','С помощью мясореза соберите "урожай" с 20 трупов стеклошкурых василисков, плетохвостых скорпидов или хромоногих гиен.','Вернитесь к Дризу Согнишвырялкинсу в Прибамбасск, что в Танарисе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ученик браконьера',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я вижу новое лицо, не так ли? Тебе подфартило: здесь, благодаря моему мясорезу, монеты льются рекой. Идешь на охоту, убиваешь несколько скорпидов или гиен, может быть, пару василисков, включаешь мясорез, а дальше он сам делает свою работу! Он специально запрограммирован таким образом, чтобы собирать в выделенный резервуар все ценные части тела твоей добычи.$b$bЕсли предложение заинтересовало тебя, возьми один из них и отправляйся поначалу на северо-запад, к заставе Скорбных Песков. Принеси мясорез с наполненным резервуаром, а я заплачу тебе за содержимое.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','С помощью мясореза соберите "урожай" с 20 трупов стеклошкурых василисков, плетохвостых скорпидов или хромоногих гиен.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дризу Согнишвырялкинсу в Прибамбасск, что в Танарисе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25502,'Подготовка почвы','Верховный друид попросил меня расставить огненных стражей по периметру. Когда мы приведем их в действие, то защитим эту область от нападений элементалей огня, принесших разрушение в нашу долину.$B$BСтражи также защитят и подготовят почву, как того хочет Хамуул.$B$BПора браться за дело. Найди одного из пяти стражей огня, отмеченных мною на карте, активируй его и защити от нападений, пока его магия не наберет силу. Это займет не более минуты.','Активируйте и защитите огненного стража.','Чудесно! Благодаря тебе и еще нескольким помощникам долина отныне защищена от контратак.$B$BЯ сделала все, что могла. Теперь все зависит от тебя и верховного друида.','Вернитесь к Райне Песни Пера в Святилище Малорна на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подготовка почвы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Верховный друид попросил меня расставить огненных стражей по периметру. Когда мы приведем их в действие, то защитим эту область от нападений элементалей огня, принесших разрушение в нашу долину.$B$BСтражи также защитят и подготовят почву, как того хочет Хамуул.$B$BПора браться за дело. Найди одного из пяти стражей огня, отмеченных мною на карте, активируй его и защити от нападений, пока его магия не наберет силу. Это займет не более минуты.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Активируйте и защитите огненного стража.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Чудесно! Благодаря тебе и еще нескольким помощникам долина отныне защищена от контратак.$B$BЯ сделала все, что могла. Теперь все зависит от тебя и верховного друида.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Райне Песни Пера в Святилище Малорна на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25503,'Сокровища Каракулы','<Вы переворачиваете порванную страницу и читаете последнюю запись:>$B$BНаш самозваный король не остановится ни перед чем, чтобы захватить богатства моей семьи. Он без конца угрожает мне, запугивает...$B$BСил моих больше нет!$B$BЯ закопал сокровище и скормил карту Каракуле.$B$BТеперь мой двоюродный братец не наложит свои куцые ручонки на наши фамильные реликвии!','Вам нужно убить косатку Каракулу, чтобы получить карту Жабрингла.','Местные жаблины считали эту вещицу очень ценной – сам король Гурбоггл жаждал ее получить!','Вы нашли фамильное сокровище Жабринглов!','Отыщите фамильное сокровище Жабринглов у затонувшего якоря в лесу Келп’тар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сокровища Каракулы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Вы переворачиваете порванную страницу и читаете последнюю запись:>$B$BНаш самозваный король не остановится ни перед чем, чтобы захватить богатства моей семьи. Он без конца угрожает мне, запугивает...$B$BСил моих больше нет!$B$BЯ закопал сокровище и скормил карту Каракуле.$B$BТеперь мой двоюродный братец не наложит свои куцые ручонки на наши фамильные реликвии!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вам нужно убить косатку Каракулу, чтобы получить карту Жабрингла.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Местные жаблины считали эту вещицу очень ценной – сам король Гурбоггл жаждал ее получить!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы нашли фамильное сокровище Жабринглов!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отыщите фамильное сокровище Жабринглов у затонувшего якоря в лесу Келп’тар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (25504,'Сделай одолжение','Привет. Рад знакомству! Я Пшикс Медноштиф. Добро пожаловать на мою гоночную баржу.$B$BЯ, как и ты, хочу помочь Тысяче Игл. И твердо верю, что гоночная баржа – реальная надежда на спасение для всей округи.$B$BМожет, подсобишь нам тут немного? А я позабочусь, чтобы у тебя было снаряжение для дальнейших приключений.$B$BК слову, если забросишь этот список запчастей в мастерскую Джинки Дзыньбламбум, то мы тебя снабдим всем необходимым.','Отнесите список запчастей Джинки Дзыньбламбум на гоночной барже Пшикса и Поззика в Тысяче Игл.','<Джинки проглядывает список запчастей и в сердцах сплевывает!>$B$BДа у меня нет и половины этого барахла!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сделай одолжение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Привет. Рад знакомству! Я Пшикс Медноштиф. Добро пожаловать на мою гоночную баржу.$B$BЯ, как и ты, хочу помочь Тысяче Игл. И твердо верю, что гоночная баржа – реальная надежда на спасение для всей округи.$B$BМожет, подсобишь нам тут немного? А я позабочусь, чтобы у тебя было снаряжение для дальнейших приключений.$B$BК слову, если забросишь этот список запчастей в мастерскую Джинки Дзыньбламбум, то мы тебя снабдим всем необходимым.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите список запчастей Джинки Дзыньбламбум на гоночной барже Пшикса и Поззика в Тысяче Игл.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Джинки проглядывает список запчастей и в сердцах сплевывает!>$B$BДа у меня нет и половины этого барахла!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (25505,'Сделай одолжение','Привет, $n. Я Поззик, всемирно известный пилот болидов. Добро пожаловать на мою гоночную баржу.$B$BЯ, как и ты, хочу помочь Тысяче Игл. И твердо верю, что гоночная баржа – реальная надежда на спасение для всей округи.$B$BМожет, подсобишь нам тут немного? А я позабочусь, чтобы у тебя было снаряжение для дальнейших приключений.$B$BК слову, если забросишь этот список запчастей в мастерскую Раззерика, то мы тебя снабдим всем необходимым.','Отнесите список запчастей Раззерику на гоночной барже Пшикса и Поззика в Тысяче Игл.','Ну-ка, малой, позволь, я посмотрю этот списочек.$B$B<Раззерик едва сдерживается!>$B$BЧего там Поззик себе думает! Знает же, что у меня и половины этого барахла нет!','Это что, список запчастей от Поззика?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сделай одолжение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Привет, $n. Я Поззик, всемирно известный пилот болидов. Добро пожаловать на мою гоночную баржу.$B$BЯ, как и ты, хочу помочь Тысяче Игл. И твердо верю, что гоночная баржа – реальная надежда на спасение для всей округи.$B$BМожет, подсобишь нам тут немного? А я позабочусь, чтобы у тебя было снаряжение для дальнейших приключений.$B$BК слову, если забросишь этот список запчастей в мастерскую Раззерика, то мы тебя снабдим всем необходимым.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите список запчастей Раззерику на гоночной барже Пшикса и Поззика в Тысяче Игл.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну-ка, малой, позволь, я посмотрю этот списочек.$B$B<Раззерик едва сдерживается!>$B$BЧего там Поззик себе думает! Знает же, что у меня и половины этого барахла нет!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Это что, список запчастей от Поззика?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25506,'Морская пищевая цепь','Время нашего здесь пребывания на исходе.$B$BЯ должен найти способ преодолеть разлом и выяснить, что затевают наги.$B$BЕсли хочешь отправиться со мной, тебе сначала стоит все-таки найти себе подходящее ездовое животное.$B$BИсследуй местность к северу отсюда и отыщи малька иглобрюха. Как поймаешь, неси ко рву на западе. К твоему приходу я все подготовлю.','Разыщите малька иглобрюха во Дворе Костеглода и отнесите его к Бездне возле Загонов.','Найдите моток веревки у Бездны возле Загонов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Морская пищевая цепь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Время нашего здесь пребывания на исходе.$B$BЯ должен найти способ преодолеть разлом и выяснить, что затевают наги.$B$BЕсли хочешь отправиться со мной, тебе сначала стоит все-таки найти себе подходящее ездовое животное.$B$BИсследуй местность к северу отсюда и отыщи малька иглобрюха. Как поймаешь, неси ко рву на западе. К твоему приходу я все подготовлю.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите малька иглобрюха во Дворе Костеглода и отнесите его к Бездне возле Загонов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Найдите моток веревки у Бездны возле Загонов.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (25508,'A Brilliant Idea','I have a brilliant idea!$B$BLets stop the playthrough here. There\'s not much more to see at the moment anyway.$B$BThanks for helping!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','A Brilliant Idea',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','I have a brilliant idea!$B$BLets stop the playthrough here. There\'s not much more to see at the moment anyway.$B$BThanks for helping!',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25509,'Физическая подготовка: принудительный труд','Тренировки для вступления в наши ряды – не самая приятная вещь. А почему они должны быть приятными?$B$BПуть служения древним богам отнюдь не краток, он полон боли и терзания души. Считай это твоим первым шагом.$B$BВозьми эту кирку и разломай залежи магнитного железняка в ущелье.$B$BНет, нам не нужна руда. Это только для твоего блага.','Разломайте 5 магнитов Зловещего Шепота.','Очень хорошо. Ты хотя бы отличаешь острый конец кирки от тупого.','Вернитесь к наставнице Милве в Кузню Мольбы на Хиджале.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Физическая подготовка: принудительный труд',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тренировки для вступления в наши ряды – не самая приятная вещь. А почему они должны быть приятными?$B$BПуть служения древним богам отнюдь не краток, он полон боли и терзания души. Считай это твоим первым шагом.$B$BВозьми эту кирку и разломай залежи магнитного железняка в ущелье.$B$BНет, нам не нужна руда. Это только для твоего блага.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разломайте 5 магнитов Зловещего Шепота.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Очень хорошо. Ты хотя бы отличаешь острый конец кирки от тупого.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к наставнице Милве в Кузню Мольбы на Хиджале.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (25513,'Громодром: решающая битва!','Похоже, у нас особая заявка! У меня тут записка от некой Келси Стализвон с требованием открыть ворота и продолжить соревнования.$b$bОна хочет, чтобы ты $gстал:стала; ее противником, $n. Поклонница твоих предыдущих побед? А может быть, о тебе знают и за пределами этого ринга?$b$bЯ бы на твоем месте не стал отступать. Это будет грандиозный финал...','Одержите победу над Мегз Жестекрошшер.','Потрясающе. Однажды я сама вызову тебя на дуэль.','Мегз Жестекрошшер побеждена','Вернитесь к Катрине Тернер в Прибамбасск, что в Танарисе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Громодром: решающая битва!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Похоже, у нас особая заявка! У меня тут записка от некой Келси Стализвон с требованием открыть ворота и продолжить соревнования.$b$bОна хочет, чтобы ты $gстал:стала; ее противником, $n. Поклонница твоих предыдущих побед? А может быть, о тебе знают и за пределами этого ринга?$b$bЯ бы на твоем месте не стал отступать. Это будет грандиозный финал...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Одержите победу над Мегз Жестекрошшер.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Потрясающе. Однажды я сама вызову тебя на дуэль.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Мегз Жестекрошшер побеждена',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Катрине Тернер в Прибамбасск, что в Танарисе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25514,'Освобождение от пут','Из глубин...$BОбители тьмы и огня.$BУдерживают меня в забытьи.$B$BЯ томлюсь в путах, |3-6($r).$B$BТени мелькают в столпах огня рядом со мной. Уничтожь их.$BТогда я вновь обрету свободу.','Выведите из строя два жезла порабощения, удерживающих Тортоллу.','<Тортолла вздрагивает и сбрасывает с себя тину.>$B$BТы...$Bне такой, как другие.$B$BЯ снова свободен.$B$BИх..$B...ждет расплата.','Поговорите с Тортоллой в Пепельном озере на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Освобождение от пут',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Из глубин...$BОбители тьмы и огня.$BУдерживают меня в забытьи.$B$BЯ томлюсь в путах, |3-6($r).$B$BТени мелькают в столпах огня рядом со мной. Уничтожь их.$BТогда я вновь обрету свободу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выведите из строя два жезла порабощения, удерживающих Тортоллу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Тортолла вздрагивает и сбрасывает с себя тину.>$B$BТы...$Bне такой, как другие.$B$BЯ снова свободен.$B$BИх..$B...ждет расплата.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Тортоллой в Пепельном озере на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25515,'Погружение в пучину','<Джинки закатывает рукава и заглаживает назад волосы, меряя вас взглядом.>$B$BЛадно, раз уж Пшиксу так хочется, чтобы у тебя была своя лодка, нам нужны запчасти. Угадай-ка, кого мы за ними отправим?$B$B<Ехидно ухмыляясь, Джинки тычет пальчиком вниз и всучивает вам запасной шлем водолаза и ласты.>$B$BТак точно, $gбратишка:сестричка;. Ныряй-ка под воду и раздобудь мне столько деталей болидов, сколько найдешь на разрушенной гоночной полосе.','Раздобудьте 10 деталей болидов.','Для начала сойдет.','Я тебе рабочее время в табеле не отмечу, пока не притащишь мне все детали из этого списка.','Вернитесь к Джинки Дзыньбламбум на гоночную баржу Пшикса и Поззика в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Погружение в пучину',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Джинки закатывает рукава и заглаживает назад волосы, меряя вас взглядом.>$B$BЛадно, раз уж Пшиксу так хочется, чтобы у тебя была своя лодка, нам нужны запчасти. Угадай-ка, кого мы за ними отправим?$B$B<Ехидно ухмыляясь, Джинки тычет пальчиком вниз и всучивает вам запасной шлем водолаза и ласты.>$B$BТак точно, $gбратишка:сестричка;. Ныряй-ка под воду и раздобудь мне столько деталей болидов, сколько найдешь на разрушенной гоночной полосе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте 10 деталей болидов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Для начала сойдет.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я тебе рабочее время в табеле не отмечу, пока не притащишь мне все детали из этого списка.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джинки Дзыньбламбум на гоночную баржу Пшикса и Поззика в Тысяче Игл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25516,'Погружение в пучину','Ладно, $gдруг:уважаемая;, раз уж Поззик считает, что тебе непременно нужна лодка, то нам не обойтись без запчастей. Угадай-ка, кого мы за ними отправим?$B$B<Ехидно ухмыляясь, Раззерик тычет пальцем вниз и всучивает вам запасной шлем водолаза и ласты.>$B$BУж прости, $n. Ныряй-ка под воду и раздобудь мне столько деталей болидов, сколько найдешь на разрушенной гоночной полосе.','Раздобудьте 10 деталей болидов.','Очень неплохо для начала!','Приступим, как только раздобудешь все, что в этом списке.','Вернитесь к Раззерику на гоночную баржу Пшикса и Поззика в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Погружение в пучину',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ладно, $gдруг:уважаемая;, раз уж Поззик считает, что тебе непременно нужна лодка, то нам не обойтись без запчастей. Угадай-ка, кого мы за ними отправим?$B$B<Ехидно ухмыляясь, Раззерик тычет пальцем вниз и всучивает вам запасной шлем водолаза и ласты.>$B$BУж прости, $n. Ныряй-ка под воду и раздобудь мне столько деталей болидов, сколько найдешь на разрушенной гоночной полосе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте 10 деталей болидов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Очень неплохо для начала!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Приступим, как только раздобудешь все, что в этом списке.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Раззерику на гоночную баржу Пшикса и Поззика в Тысяче Игл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25517,'Драка в баре!','Ну все, эти вонючие жаблины напросились!$B$BОтправляйся-ка в Бар гоночной баржи, закажи бутылку грога и врежь кому-нибудь из них промеж глаз!$B$BОбъясни им, $n, что больше мы их наглость терпеть не намерены!','Начните драку в баре!','Вот это я понимаю! Ты – настоящая гордость Альянса!$B$BЗнаешь, можешь заходить туда когда пожелаешь и начинать все по новой. Даже больше скажу: я всячески тебя к этому призываю!','Вернитесь к Риззлу Медноштифу на гоночную баржу Пшикса и Поззика в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Драка в баре!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну все, эти вонючие жаблины напросились!$B$BОтправляйся-ка в Бар гоночной баржи, закажи бутылку грога и врежь кому-нибудь из них промеж глаз!$B$BОбъясни им, $n, что больше мы их наглость терпеть не намерены!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Начните драку в баре!',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот это я понимаю! Ты – настоящая гордость Альянса!$B$BЗнаешь, можешь заходить туда когда пожелаешь и начинать все по новой. Даже больше скажу: я всячески тебя к этому призываю!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Риззлу Медноштифу на гоночную баржу Пшикса и Поззика в Тысяче Игл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25518,'Драка в баре!','Ну все, эти недотепы-гномы, которых можно за кружку с элем спрятать, напросились!$B$BОтправляйся-ка в Бар гоночной баржи, закажи бутылку грога и врежь кому-нибудь из них промеж глаз!$B$BОбъясни им, $n, что больше мы их высокомерие терпеть не намерены!','Начните драку в баре!','Молодчина! Ты – настоящая гордость Орды!$B$BЗнаешь, можешь заходить туда когда пожелаешь и начинать все по новой. Даже больше скажу: я всячески тебя к этому призываю!','Вернитесь к Замеку на гоночную баржу Пшикса и Поззика в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Драка в баре!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну все, эти недотепы-гномы, которых можно за кружку с элем спрятать, напросились!$B$BОтправляйся-ка в Бар гоночной баржи, закажи бутылку грога и врежь кому-нибудь из них промеж глаз!$B$BОбъясни им, $n, что больше мы их высокомерие терпеть не намерены!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Начните драку в баре!',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Молодчина! Ты – настоящая гордость Орды!$B$BЗнаешь, можешь заходить туда когда пожелаешь и начинать все по новой. Даже больше скажу: я всячески тебя к этому призываю!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Замеку на гоночную баржу Пшикса и Поззика в Тысяче Игл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25519,'Дети Тортоллы','Мои дети...$B...лежат внизу.$BСреди ила и песка.$B$BИх пытаются осквернить.$BЗаполнить их панцири тьмой.$B$BУмертви тех, кто повинен в этом.$BУничтожь осквернителей.$BСпаси моих детей...','Убейте 6 осквернителей глубин, нападающих на яйца Тортоллы в Пепельном озере.','Человек.$BТы не похож на остальных.$B$BОтважнее. Сильнее.$BТы принадлежишь этому миру...$B...а не той тьме, что пришла ранее.$B$BБлагодарю тебя.','Вернитесь к Тортолле на Пепельное озеро на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дети Тортоллы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мои дети...$B...лежат внизу.$BСреди ила и песка.$B$BИх пытаются осквернить.$BЗаполнить их панцири тьмой.$B$BУмертви тех, кто повинен в этом.$BУничтожь осквернителей.$BСпаси моих детей...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 6 осквернителей глубин, нападающих на яйца Тортоллы в Пепельном озере.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Человек.$BТы не похож на остальных.$B$BОтважнее. Сильнее.$BТы принадлежишь этому миру...$B...а не той тьме, что пришла ранее.$B$BБлагодарю тебя.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тортолле на Пепельное озеро на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25520,'Пробуждение древнего бога','Я дремал в целительном иле Хиджала.$BЯ спал до тех пор, пока не открылся разлом.$BПриход осквернителей стал для меня неожиданностью.$B$BТеперь я готов, |3-6($r).$B$BЯ и мои дети. Нас сложно разгневать.$BОднако страшен наш гнев.$B$BСкажи тем, кто прислал тебя, что мы готовы к войне.$B$BМы очистим гору от осквернителей.','Вернитесь к верховному друиду Хамуулу Руническому Тотему, находящемуся в Святилище Малорна на горе Хиджал.','Вернитесь к верховному друиду Хамуулу Руническому Тотему, находящемуся в Святилище Малорна на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пробуждение древнего бога',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я дремал в целительном иле Хиджала.$BЯ спал до тех пор, пока не открылся разлом.$BПриход осквернителей стал для меня неожиданностью.$B$BТеперь я готов, |3-6($r).$B$BЯ и мои дети. Нас сложно разгневать.$BОднако страшен наш гнев.$B$BСкажи тем, кто прислал тебя, что мы готовы к войне.$B$BМы очистим гору от осквернителей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь к верховному друиду Хамуулу Руническому Тотему, находящемуся в Святилище Малорна на горе Хиджал.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному друиду Хамуулу Руническому Тотему, находящемуся в Святилище Малорна на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25521,'Я насчет скорпидов','Ты $gдолжен:должна; помочь мне, просто $gобязан:обязана;! Мы с Челси приехали сюда немного подзаработать, просто кое-что продать, все совершенно законно. А теперь она на смертном одре! Ее жар впечатлил бы даже кузнеца, а еще у нее галлюцинации...$b$BСкорее всего, ее ужалил один из скорпидов, что водятся здесь неподалеку! Я уже видел такое. Мне нужно несколько ядовитых желез для того, чтобы сделать противоядие, но я же не могу покинуть ее!$b$bПожалуйста, помоги мне! Принеси эти железы!','Принеси 6 жал барханных скорпидов.','О, спасибо, спасибо тебе! Я немного разбираюсь в алхимии, так что я не совсем уж бесполезен. Вот и оно...','Вернитесь к Гасу Ржавотрясу на заставу Скорбных Песков.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Я насчет скорпидов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gдолжен:должна; помочь мне, просто $gобязан:обязана;! Мы с Челси приехали сюда немного подзаработать, просто кое-что продать, все совершенно законно. А теперь она на смертном одре! Ее жар впечатлил бы даже кузнеца, а еще у нее галлюцинации...$b$BСкорее всего, ее ужалил один из скорпидов, что водятся здесь неподалеку! Я уже видел такое. Мне нужно несколько ядовитых желез для того, чтобы сделать противоядие, но я же не могу покинуть ее!$b$bПожалуйста, помоги мне! Принеси эти железы!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принеси 6 жал барханных скорпидов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, спасибо, спасибо тебе! Я немного разбираюсь в алхимии, так что я не совсем уж бесполезен. Вот и оно...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гасу Ржавотрясу на заставу Скорбных Песков.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (25522,'Колоссопид','Нет! Не помогло! Не знаю, что еще можно сделать, разве что...$b$BВсе еще хуже, чем я думал! Ее, похоже, ужалил тот, что обычно бродит по пещере. Видел его в самую первую ночь, как только мы прибыли. Челюсти размером с гоблина. Хвост высотой с дерево! Лишь шепотом мы осмеливались говорить о нем у костра... и мы назвали его... КОЛОССОПИДОМ!$b$b... Эй, ты что, смеешься? Ну-ка прекрати! Это серьезно! Челси на краю гибели! Пожалуйста, я сделаю все, что хочешь... только принеси мне ядовитую железу Колоссопида!','Раздобудьте жало Колоссопида.','Поверить не могу! Ты просто чудо! Вот, пожалуйста, возьми свою награду, возьми все, что хочешь! Я должен спасти Челси!','Ты вернулся! Удалось добыть?','Вернитесь к Гасу Ржавотрясу на заставу Скорбных Песков.','Самый большой скорпид в этой части Калимдора.','Колоссопид') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Колоссопид',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нет! Не помогло! Не знаю, что еще можно сделать, разве что...$b$BВсе еще хуже, чем я думал! Ее, похоже, ужалил тот, что обычно бродит по пещере. Видел его в самую первую ночь, как только мы прибыли. Челюсти размером с гоблина. Хвост высотой с дерево! Лишь шепотом мы осмеливались говорить о нем у костра... и мы назвали его... КОЛОССОПИДОМ!$b$b... Эй, ты что, смеешься? Ну-ка прекрати! Это серьезно! Челси на краю гибели! Пожалуйста, я сделаю все, что хочешь... только принеси мне ядовитую железу Колоссопида!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте жало Колоссопида.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Поверить не могу! Ты просто чудо! Вот, пожалуйста, возьми свою награду, возьми все, что хочешь! Я должен спасти Челси!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты вернулся! Удалось добыть?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гасу Ржавотрясу на заставу Скорбных Песков.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Самый большой скорпид в этой части Калимдора.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Колоссопид',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25523,'Полет по Огненным Просторам','$n, наши враги используют эту пещеру на Огненных Просторах для подготовки вторжения. Мы собираемся ударить по ним прямо там, где они живут.$B$BНо сначала тебе нужны крылья. Полет по Огненным Просторам – это тебе не в обычном мире летать. Плотный, перегретый воздух. Нужна тренировка!$B$BВозьми Огненное копье Сумеречного Молота со стойки позади меня, затем заберись на одного из защитников Авианы. И потренируйся – просто хлопай крыльями, да и все! Долети до флага, что я установил на уступе вон там внизу, и возвращайся.','Вооружитесь Огненным копьем Сумеречного Молота, взяв его со стойки позади Фардена. Заберитесь на одного из защитников Авианы и летите к флагу стража, установленному на уступе внизу. Нажмите кнопку "Взмах", чтобы защитник полетел.','Отлично! Как ощущения?$B$BОсвоить полет в этом пылающем пространстве нелегко, но другого пути нет.$B$BНадеюсь, ты готова сражаться, Пихля…','Вернитесь к Фарону Когтекрылу, находящемуся в Инкубаторе Огненных просторов на горе Хиджал. Чтобы лететь, нажмите кнопку "Взмах".') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Полет по Огненным Просторам',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, наши враги используют эту пещеру на Огненных Просторах для подготовки вторжения. Мы собираемся ударить по ним прямо там, где они живут.$B$BНо сначала тебе нужны крылья. Полет по Огненным Просторам – это тебе не в обычном мире летать. Плотный, перегретый воздух. Нужна тренировка!$B$BВозьми Огненное копье Сумеречного Молота со стойки позади меня, затем заберись на одного из защитников Авианы. И потренируйся – просто хлопай крыльями, да и все! Долети до флага, что я установил на уступе вон там внизу, и возвращайся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вооружитесь Огненным копьем Сумеречного Молота, взяв его со стойки позади Фардена. Заберитесь на одного из защитников Авианы и летите к флагу стража, установленному на уступе внизу. Нажмите кнопку "Взмах", чтобы защитник полетел.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! Как ощущения?$B$BОсвоить полет в этом пылающем пространстве нелегко, но другого пути нет.$B$BНадеюсь, ты готова сражаться, Пихля…',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фарону Когтекрылу, находящемуся в Инкубаторе Огненных просторов на горе Хиджал. Чтобы лететь, нажмите кнопку "Взмах".',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25524,'В отхожем месте','Раздобудьте лом пирата и взломайте дверь полузатопленного туалета.','Хвала всему святому! Теперь чуть-чуть подналяжем...','Во имя Света, раздобыл ты лом или нет? Я же тут тону!','Вернитесь к полузатопленному туалету у разрушенной гоночной полосы в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В отхожем месте',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте лом пирата и взломайте дверь полузатопленного туалета.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хвала всему святому! Теперь чуть-чуть подналяжем...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Во имя Света, раздобыл ты лом или нет? Я же тут тону!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к полузатопленному туалету у разрушенной гоночной полосы в Тысяче Игл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25525,'По седлам!','Они приближаются, $n! Всадники из культа Сумеречного Молота, верхом на черных птицах, вскормленных в жгучих серных прудах Огненных Просторов. Победить их можно только в небе.$B$BЕще раз взлетай, $n, и убей их.$B$BВонзайся в ряды вражеских всадников, вооружившись копьем, чтобы уничтожить их.$B$BВперед. Лети же, ну? Лети!','Вооружитесь Огненным копьем Сумеречного Молота и взлетите на одном из защитников Авианы. Убейте 10 сумеречных всадников, налетев на них. Нажимайте кнопку "Взмах", чтобы лететь.','Вернитесь к Фардену Когтекрылу, находящемуся в Инкубаторе Огненных просторов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','По седлам!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Они приближаются, $n! Всадники из культа Сумеречного Молота, верхом на черных птицах, вскормленных в жгучих серных прудах Огненных Просторов. Победить их можно только в небе.$B$BЕще раз взлетай, $n, и убей их.$B$BВонзайся в ряды вражеских всадников, вооружившись копьем, чтобы уничтожить их.$B$BВперед. Лети же, ну? Лети!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вооружитесь Огненным копьем Сумеречного Молота и взлетите на одном из защитников Авианы. Убейте 10 сумеречных всадников, налетев на них. Нажимайте кнопку "Взмах", чтобы лететь.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фардену Когтекрылу, находящемуся в Инкубаторе Огненных просторов.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25526,'В отхожем месте','Раздобудьте лом пирата и взломайте дверь полузатопленного туалета.','Хвала всему святому! Теперь чуть-чуть подналяжем...','Денежки-светы, раздобыл ты лом или нет? Я же тут тону!','Вернитесь к полузатопленному туалету у разрушенной гоночной полосы в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В отхожем месте',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте лом пирата и взломайте дверь полузатопленного туалета.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хвала всему святому! Теперь чуть-чуть подналяжем...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Денежки-светы, раздобыл ты лом или нет? Я же тут тону!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к полузатопленному туалету у разрушенной гоночной полосы в Тысяче Игл.',`completedtext_loc8`);
