INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25531,'Бунт Сумеречного Молота','Спасибо, что $gосвободил:освободила; меня. Надо воспользоваться возникшей благодаря тебе сумятицей и выбраться отсюда.$B$BНам надо поторопиться, пока сектанты не опомнились.$B$BПоговорим, когда покинем это место.','Поговорите с Джеродом Песнью Теней у Врат Созанна.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бунт Сумеречного Молота',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Спасибо, что $gосвободил:освободила; меня. Надо воспользоваться возникшей благодаря тебе сумятицей и выбраться отсюда.$B$BНам надо поторопиться, пока сектанты не опомнились.$B$BПоговорим, когда покинем это место.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Джеродом Песнью Теней у Врат Созанна.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (25532,'Пираты пристрелялись','Возьмите гоночное судно у Маззера Винтодера и потушите при помощи морозной пушки 15 очагов возгорания.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пираты пристрелялись',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возьмите гоночное судно у Маззера Винтодера и потушите при помощи морозной пушки 15 очагов возгорания.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (25533,'Пираты пристрелялись','Возьмите гоночное судно у Гризнака и потушите при помощи морозной пушки 15 очагов возгорания.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пираты пристрелялись',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возьмите гоночное судно у Гризнака и потушите при помощи морозной пушки 15 очагов возгорания.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25534,'Побочная задача','Как ты уже $gзаметил:заметила;, орудия пришвартованного на севере корабля не прекращают изрыгать огонь. Несмотря на то, что смотреть, как свинцовый град обрушивается на гномов, довольно весело, мои костоломы тоже попадают под огонь, а соответственно, сумма накладных расходов взлетает до небес.$b$BЕсли бы ты $gмог:могла; прорваться сквозь огонь и забраться на корабль, то можно было бы добраться и до их командира. Скорее всего, сама команда представляет собой всего лишь кучку безмозглых идиотов, так что стоит справиться с командиром, и все будет в порядке.','Хорошая работа, детка. Не сильно там рисковал? Лишних царапин не появилось?$B$BНет?','Вернитесь к Мегз Жестекрошшер в Бухту Сорванных Парусов, что в Танарисе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Побочная задача',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как ты уже $gзаметил:заметила;, орудия пришвартованного на севере корабля не прекращают изрыгать огонь. Несмотря на то, что смотреть, как свинцовый град обрушивается на гномов, довольно весело, мои костоломы тоже попадают под огонь, а соответственно, сумма накладных расходов взлетает до небес.$b$BЕсли бы ты $gмог:могла; прорваться сквозь огонь и забраться на корабль, то можно было бы добраться и до их командира. Скорее всего, сама команда представляет собой всего лишь кучку безмозглых идиотов, так что стоит справиться с командиром, и все будет в порядке.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошая работа, детка. Не сильно там рисковал? Лишних царапин не появилось?$B$BНет?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мегз Жестекрошшер в Бухту Сорванных Парусов, что в Танарисе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (25535,'Накормить голодных','Бедняги. Они голодают.$B$BУ нас много неотложных дел – не в последнюю очередь надо что-то решать с нагами, но сначала требуется наполнить эти урчащие животы. Не знаю, чем там наги их кормили – если вообще кормили, но вид у них страшно истощенный.$B$BНемало выживших сумело добраться до Теснины Мерцающих Глубин – это на северо-западе. Отправляйся туда и помоги им. Мясо моллюсков быстро поставит уцелевших на ноги.','Поговорите с инструктором ныряльщиков Бирмингемом в Теснине Мерцающих Глубин.','Еще одна помощница! Великолепно! Помощь нам нужна, это уж точно.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Накормить голодных',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Бедняги. Они голодают.$B$BУ нас много неотложных дел – не в последнюю очередь надо что-то решать с нагами, но сначала требуется наполнить эти урчащие животы. Не знаю, чем там наги их кормили – если вообще кормили, но вид у них страшно истощенный.$B$BНемало выживших сумело добраться до Теснины Мерцающих Глубин – это на северо-западе. Отправляйся туда и помоги им. Мясо моллюсков быстро поставит уцелевших на ноги.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с инструктором ныряльщиков Бирмингемом в Теснине Мерцающих Глубин.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Еще одна помощница! Великолепно! Помощь нам нужна, это уж точно.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25536,'Прохладный прием','Многие выжившие отправились в Теснину Мерцающих Глубин собирать моллюсков. И поступили донесения, что на них там постоянно нападают какие-то мурлоки.$B$BАдмирал вынужден оставаться здесь, потому что люди все прибывают, и мне не удается убедить его послать кого-нибудь на подмогу ныряльщикам. Если ты отправишься туда, уверен, ребята будут благодарны тебе за помощь.$B$BКогда там со всем закончишь, дай мне знать.','Убейте 10 волноловов Мерцающих Глубин.','Вернитесь к капитану Тейлору в Тихий залив.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прохладный прием',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Многие выжившие отправились в Теснину Мерцающих Глубин собирать моллюсков. И поступили донесения, что на них там постоянно нападают какие-то мурлоки.$B$BАдмирал вынужден оставаться здесь, потому что люди все прибывают, и мне не удается убедить его послать кого-нибудь на подмогу ныряльщикам. Если ты отправишься туда, уверен, ребята будут благодарны тебе за помощь.$B$BКогда там со всем закончишь, дай мне знать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 волноловов Мерцающих Глубин.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Тейлору в Тихий залив.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25537,'Искусство притяжения','У меня идея. Просто блестящая! Дело в том, что рыбы-клоуны вступили в некий симбиоз с анемонами. А я открыл в анемонах то вещество, которое так притягивает рыб.$B$BВот, держи. Это термо-гироскопический экстрактор, с помощью которого можно собрать с анемонов образцы вещества, привлекающего рыб. Добудь нужные образцы и возвращайся.$B$BИ поторопись! Нас ждет успех!','C помощью пробоотборника для анемонов соберите 8 химических образцов с красных анемонов, растущих вдоль стен Теснины Мерцающих Глубин.','Изумительно! Это все, что нужно!$B$BМой сверхбыстрый химсинтезатор уже протестирован и готов к работе. С его помощью я создам необходимый химикат в мгновение ока!','Вернитесь к инженеру Мегагексу в Теснину Мерцающих Глубин.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Искусство притяжения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У меня идея. Просто блестящая! Дело в том, что рыбы-клоуны вступили в некий симбиоз с анемонами. А я открыл в анемонах то вещество, которое так притягивает рыб.$B$BВот, держи. Это термо-гироскопический экстрактор, с помощью которого можно собрать с анемонов образцы вещества, привлекающего рыб. Добудь нужные образцы и возвращайся.$B$BИ поторопись! Нас ждет успех!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','C помощью пробоотборника для анемонов соберите 8 химических образцов с красных анемонов, растущих вдоль стен Теснины Мерцающих Глубин.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Изумительно! Это все, что нужно!$B$BМой сверхбыстрый химсинтезатор уже протестирован и готов к работе. С его помощью я создам необходимый химикат в мгновение ока!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к инженеру Мегагексу в Теснину Мерцающих Глубин.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25538,'Распылитель','Какое чудесное изобретение! Главное – уже готовое к внедрению!$B$BПросто распыли немного химиката на ныряльщиков, и вскоре к каждому из них присоединится защитник. Можешь немного и на себя побрызгать, если пожелаешь.$B$BКстати, о желаниях... Решительно не рекомендую превышать минимально необходимую дозу химиката. Передозировка может привести к нежелательным последствиям...$B$BНежелательным для тебя, конечно. Не для рыб.$B$BВперед!','Обработайте анемоновым распылителем 8 ныряльщиков.','Великолепно, моя благоухающая коллега. Ты одновременно усердна и быстра. Пусть все твои приключения несут тебе только радость и богатство.','Вернитесь к инженеру Мегагексу в Теснину Мерцающих Глубин.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Распылитель',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Какое чудесное изобретение! Главное – уже готовое к внедрению!$B$BПросто распыли немного химиката на ныряльщиков, и вскоре к каждому из них присоединится защитник. Можешь немного и на себя побрызгать, если пожелаешь.$B$BКстати, о желаниях... Решительно не рекомендую превышать минимально необходимую дозу химиката. Передозировка может привести к нежелательным последствиям...$B$BНежелательным для тебя, конечно. Не для рыб.$B$BВперед!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обработайте анемоновым распылителем 8 ныряльщиков.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Великолепно, моя благоухающая коллега. Ты одновременно усердна и быстра. Пусть все твои приключения несут тебе только радость и богатство.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к инженеру Мегагексу в Теснину Мерцающих Глубин.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25539,'Сбор моллюсков','Хочешь помочь с моллюсками?$B$BТогда приступай к работе – они тут повсюду.','Соберите 16 моллюсков Мерцающих Глубин.','Прекрасно! Количество собранных моллюсков впечатляет. Вот в пещере обрадуются!','Есть успехи в сборе моллюсков?','Вернитесь к инструктору ныряльщиков Бирмингему в Теснину Мерцающих Глубин.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сбор моллюсков',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хочешь помочь с моллюсками?$B$BТогда приступай к работе – они тут повсюду.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 16 моллюсков Мерцающих Глубин.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно! Количество собранных моллюсков впечатляет. Вот в пещере обрадуются!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Есть успехи в сборе моллюсков?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к инструктору ныряльщиков Бирмингему в Теснину Мерцающих Глубин.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (25540,'Голодные рты ждут','Так, моллюсков уже достаточно – надо бы отнести их в пещеру, и я как раз думал, кто же это сделает. Ты однозначно подходишь.$B$BУвы, вероятность того, что столь изысканное лакомство привлечет по дороге внимание хищников, весьма высока, поэтому промедление смерти подобно.$B$BБлагодарю за помощь. Было приятно иметь с тобой дело.','Отнесите огромный мешок моллюсков в Тихий залив.','Замечательно. Прямо сейчас начну готовить. Хорошо, что хотя бы голод можно исключить из списка наших бед.$B$BДумаю, твоя помощь потребуется адмиралу, поэтому на время освобождаю тебя от заданий.','Полагаю, ты вернулась не просто так. Путешествие было удачным?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Голодные рты ждут',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Так, моллюсков уже достаточно – надо бы отнести их в пещеру, и я как раз думал, кто же это сделает. Ты однозначно подходишь.$B$BУвы, вероятность того, что столь изысканное лакомство привлечет по дороге внимание хищников, весьма высока, поэтому промедление смерти подобно.$B$BБлагодарю за помощь. Было приятно иметь с тобой дело.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите огромный мешок моллюсков в Тихий залив.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Замечательно. Прямо сейчас начну готовить. Хорошо, что хотя бы голод можно исключить из списка наших бед.$B$BДумаю, твоя помощь потребуется адмиралу, поэтому на время освобождаю тебя от заданий.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Полагаю, ты вернулась не просто так. Путешествие было удачным?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25541,'Требуются пломбы','Отлично! Запомни, золото есть золото, неважно, в чьем рту, носу или где-либо еще оно находилось.$B$BПереплавка в любом случае очистит его. Или, по крайней мере, продажа.','Не надо теперь говорить мне о брезгливости.','Вернитесь к Мегз Жестекрошшер в Бухту Сорванных Парусов, что в Танарисе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Требуются пломбы',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! Запомни, золото есть золото, неважно, в чьем рту, носу или где-либо еще оно находилось.$B$BПереплавка в любом случае очистит его. Или, по крайней мере, продажа.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Не надо теперь говорить мне о брезгливости.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мегз Жестекрошшер в Бухту Сорванных Парусов, что в Танарисе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (25542,'На оборону дилижанса... то есть лодки!','Вернитесь к Джинки Дзыньбламбум на гоночную баржу Пшикса и Поззика в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На оборону дилижанса... то есть лодки!',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джинки Дзыньбламбум на гоночную баржу Пшикса и Поззика в Тысяче Игл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (25543,'На оборону дилижанса... то есть лодки!','Вернитесь к Раззерику на гоночную баржу Пшикса и Поззика в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На оборону дилижанса... то есть лодки!',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Раззерику на гоночную баржу Пшикса и Поззика в Тысяче Игл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25544,'По копьям!','Похоже, мы разворошили осиное гнездо, $n. Своды пещеры начинают рушиться! А их лучшие бойцы уже оседлали своих птиц, закаленных и оскверненных этим пылающим миром.$B$BВозвращайся обратно и уничтожь их! Только берегись горящих булыжников.','Вооружитесь Огненным копьем Сумеречного Молота и взлетите на одном из защитников Авианы. Убейте 10 сумеречных копейщиков, налетев на них. Нажимайте кнопку "Взмах", чтобы лететь.','Вернитесь к Фардену Когтекрылу, находящемуся в Инкубаторе Огненных просторов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','По копьям!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Похоже, мы разворошили осиное гнездо, $n. Своды пещеры начинают рушиться! А их лучшие бойцы уже оседлали своих птиц, закаленных и оскверненных этим пылающим миром.$B$BВозвращайся обратно и уничтожь их! Только берегись горящих булыжников.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вооружитесь Огненным копьем Сумеречного Молота и взлетите на одном из защитников Авианы. Убейте 10 сумеречных копейщиков, налетев на них. Нажимайте кнопку "Взмах", чтобы лететь.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фардену Когтекрылу, находящемуся в Инкубаторе Огненных просторов.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25545,'Во всеоружии','Чтобы не утонуть, нам пришлось бросить оружие и почти все доспехи.$B$BЭрунак говорит, наги готовят массированную атаку, и у меня нет оснований ему не доверять.$B$BЧтобы выстоять под натиском наг, необходимо вернуть брошенное оружие. Оно должно быть на дне, рядом с нашим погибшим кораблем. Но без твоей помощи нам не справиться.$B$BПоторопись, |3-6($r), а то мы совсем беззащитны.','Подберите со дна 4 копья Штормграда, 4 кирасы Штормграда, 4 щита Штормграда и 4 шлема Штормграда.$B$BСнаряжение также можно забрать у падальщиков жаблинов.','Поговорите с капитаном Тейлором на "Морском Кортике".') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Во всеоружии',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чтобы не утонуть, нам пришлось бросить оружие и почти все доспехи.$B$BЭрунак говорит, наги готовят массированную атаку, и у меня нет оснований ему не доверять.$B$BЧтобы выстоять под натиском наг, необходимо вернуть брошенное оружие. Оно должно быть на дне, рядом с нашим погибшим кораблем. Но без твоей помощи нам не справиться.$B$BПоторопись, |3-6($r), а то мы совсем беззащитны.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Подберите со дна 4 копья Штормграда, 4 кирасы Штормграда, 4 щита Штормграда и 4 шлема Штормграда.$B$BСнаряжение также можно забрать у падальщиков жаблинов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с капитаном Тейлором на "Морском Кортике".',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25546,'Голод не тетка','Мне нужна твоя помощь.$B$BКаждый хороший военачальник знает: воинов надо как следует кормить. На голодный желудок много не навоюешь. Нет еды – нет победы.$B$BМоим солдатам в последнее время пришлось туго. Им нужно пополнить силы. А где взять силу, если есть нечего?!$B$BКстати, я там на дне видел крабов... Ну, в общем, ты понимаешь, что надо делать.','Добудьте 8 кусков сочного мяса крабов c быстролапов с надтреснутой клешней.','Отличный улов. Ты молодец.$B$BМы все очень тебе благодарны.','Вернитесь к капитану Тейлору на "Морской Кортик".') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Голод не тетка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне нужна твоя помощь.$B$BКаждый хороший военачальник знает: воинов надо как следует кормить. На голодный желудок много не навоюешь. Нет еды – нет победы.$B$BМоим солдатам в последнее время пришлось туго. Им нужно пополнить силы. А где взять силу, если есть нечего?!$B$BКстати, я там на дне видел крабов... Ну, в общем, ты понимаешь, что надо делать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 8 кусков сочного мяса крабов c быстролапов с надтреснутой клешней.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличный улов. Ты молодец.$B$BМы все очень тебе благодарны.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Тейлору на "Морской Кортик".',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (25547,'По нашим правилам','Перед смертью все равно не надышишься. Нет смысла сидеть и ждать, когда нас найдут наги.$B$BЯ поговорю с бойцами, мы нападем первыми и сразимся с врагом по нашим правилам. Пусть судьба решит исход битвы.','Поговорите с капитаном Тейлором на "Морском Кортике".','Времени не осталось.$B$BПора действовать. Бойцы знают, что им нужно делать.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','По нашим правилам',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Перед смертью все равно не надышишься. Нет смысла сидеть и ждать, когда нас найдут наги.$B$BЯ поговорю с бойцами, мы нападем первыми и сразимся с врагом по нашим правилам. Пусть судьба решит исход битвы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с капитаном Тейлором на "Морском Кортике".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Времени не осталось.$B$BПора действовать. Бойцы знают, что им нужно делать.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25548,'Мощь Повелителя Огня','Мне было поручено руководить действиями наших войск против врагов. Это довольно простая задача, учитывая, что среди нас есть полубоги.$B$BЯ хочу поручить тебе совершить ряд внезапных рейдов во вражеские тылы. Важно застать врага врасплох и ослабить его перед нашей основной атакой.$B$BТвоя первая цель – Вершина Перерожденных, где наиболее обученные ревностные последователи культа Сумеречного Молота стали наполовину элементалями.','Убейте 4 перерожденных служителей огня и 5 сумеречных поработителей на Вершине Перерожденных на Хиджале.','Вернитесь к командиру Джероду Песни Теней, находящемуся у Врат Созанна на Хиджале.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мощь Повелителя Огня',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне было поручено руководить действиями наших войск против врагов. Это довольно простая задача, учитывая, что среди нас есть полубоги.$B$BЯ хочу поручить тебе совершить ряд внезапных рейдов во вражеские тылы. Важно застать врага врасплох и ослабить его перед нашей основной атакой.$B$BТвоя первая цель – Вершина Перерожденных, где наиболее обученные ревностные последователи культа Сумеречного Молота стали наполовину элементалями.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 4 перерожденных служителей огня и 5 сумеречных поработителей на Вершине Перерожденных на Хиджале.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру Джероду Песни Теней, находящемуся у Врат Созанна на Хиджале.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25549,'Святилище Прорицателей','Безумные прорицатели Сумеречного Молота собираются севернее Вершины Перерожденных.$B$BГоворят, что темные видения посылают им сами древние боги. Правда это или нет, но они имеют огромное духовное влияние на этот культ. Нападение на Святилище Прорицателей станет сокрушительным ударом по боевому духу врага, и если нам повезет, там ты найдешь одного из посланников самого Повелителя Огня.','Убейте 4 сумеречных предсказателей, 4 сумеречных охранителей и 1 посланника пламени в Святилище Прорицателей.','Вернитесь к командиру Джероду Песни Теней, находящемуся у Врат Созанна на Хиджале.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Святилище Прорицателей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Безумные прорицатели Сумеречного Молота собираются севернее Вершины Перерожденных.$B$BГоворят, что темные видения посылают им сами древние боги. Правда это или нет, но они имеют огромное духовное влияние на этот культ. Нападение на Святилище Прорицателей станет сокрушительным ударом по боевому духу врага, и если нам повезет, там ты найдешь одного из посланников самого Повелителя Огня.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 4 сумеречных предсказателей, 4 сумеречных охранителей и 1 посланника пламени в Святилище Прорицателей.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру Джероду Песни Теней, находящемуся у Врат Созанна на Хиджале.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (25550,'Владыка магмы','Владыка магматических великанов, служащих Рагнаросу, держит своих подданных в железной узде. Если мы разделаемся с ним, без руководства они наверняка придут в смятение.$B$BА без гигантов шансы сторон в сражении практически уравняются. Возможно, у нас даже появится преимущество.$B$BНо сокрушить повелителя магмы будет непросто. Используй эти барабаны, чтобы заручиться помощью великого Тортоллы, который способен отражать атаки короля Молтрона до бесконечности. Однако нам нужно не только защититься от него, но и победить – эту задачу я доверяю тебе.','Используйте барабаны бога-черепахи, чтобы одолеть короля Молтрона.','Вернитесь к командиру Джероду Песни Теней, находящемуся у Врат Созанна на Хиджале.','Используйте барабаны, чтобы воспользоваться помощью Тортоллы.','Король Молтрон') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Владыка магмы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Владыка магматических великанов, служащих Рагнаросу, держит своих подданных в железной узде. Если мы разделаемся с ним, без руководства они наверняка придут в смятение.$B$BА без гигантов шансы сторон в сражении практически уравняются. Возможно, у нас даже появится преимущество.$B$BНо сокрушить повелителя магмы будет непросто. Используй эти барабаны, чтобы заручиться помощью великого Тортоллы, который способен отражать атаки короля Молтрона до бесконечности. Однако нам нужно не только защититься от него, но и победить – эту задачу я доверяю тебе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте барабаны бога-черепахи, чтобы одолеть короля Молтрона.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру Джероду Песни Теней, находящемуся у Врат Созанна на Хиджале.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Используйте барабаны, чтобы воспользоваться помощью Тортоллы.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Король Молтрон',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (25551,'Повелитель Огня','Сразив Привратника, вы дали Стражам Хиджала доступ к Шпилю Сульфурона.$B$BУ Рагнароса не будет другого выбора, кроме как самому защищать главный проход на Огненные Просторы.$B$BСтупайте через портал Сумеречного Молота в Святилище Прорицателей и ждите меня там. Малфурион и Хамуул помогут тебе внутри, пока остальные будут сражаться с врагами снаружи.','Пройдите сквозь портал в Святилище Прорицателей и помогите Кенарию одолеть Рагнароса.','Вернитесь к командиру Джероду Песни Теней, находящемуся у Врат Созанна на Хиджале.','Пришел черед Повелителя Огня.','Рагнарос') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Повелитель Огня',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сразив Привратника, вы дали Стражам Хиджала доступ к Шпилю Сульфурона.$B$BУ Рагнароса не будет другого выбора, кроме как самому защищать главный проход на Огненные Просторы.$B$BСтупайте через портал Сумеречного Молота в Святилище Прорицателей и ждите меня там. Малфурион и Хамуул помогут тебе внутри, пока остальные будут сражаться с врагами снаружи.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Пройдите сквозь портал в Святилище Прорицателей и помогите Кенарию одолеть Рагнароса.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру Джероду Песни Теней, находящемуся у Врат Созанна на Хиджале.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Пришел черед Повелителя Огня.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Рагнарос',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25552,'Отродье зла','Принесенное тобой яйцо – тревожный знак, $n. Сумеречные драконы обычно появляются из похищенных у других драконов яиц, которые обрабатывают при помощи темной магии.$B$BЭто яйцо естественного происхождения свидетельствует о том, что одна из их матриархов теперь способна нести яйца. Мы должны уничтожить ее прежде, чем потомство выведется.$B$BСтупай на Вершину Перерожденных, где обитают эти чудовища, и убей одного из молодых драконов. Мы используем его череп, чтобы выманить мать.','Добудьте череп молодого сумеречного дракона на Вершине Перерожденных на Хиджале.','Вернитесь к Аронию, находящемуся у Врат Созанна на Хиджале.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отродье зла',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Принесенное тобой яйцо – тревожный знак, $n. Сумеречные драконы обычно появляются из похищенных у других драконов яиц, которые обрабатывают при помощи темной магии.$B$BЭто яйцо естественного происхождения свидетельствует о том, что одна из их матриархов теперь способна нести яйца. Мы должны уничтожить ее прежде, чем потомство выведется.$B$BСтупай на Вершину Перерожденных, где обитают эти чудовища, и убей одного из молодых драконов. Мы используем его череп, чтобы выманить мать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте череп молодого сумеречного дракона на Вершине Перерожденных на Хиджале.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аронию, находящемуся у Врат Созанна на Хиджале.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (25553,'Смерть праматери!','Мы нашли место кормежки матриарха к югу от Вершины Перерожденных.$B$BОна придет в ярость, узнав о потере одного из своих детей. Положи этот череп рядом с тушами, которые она ест. Если она где-то поблизости, то прилетит и попытается отомстить.$B$BТут-то мы и устроим ей сюрприз.','Положите череп сумеречного дракона на месте кормежки к югу от Вершины Перерожденных и убейте Деспериону.','Все прошло… лучше, чем ожидалось.','Вернитесь к Аронию, находящемуся у Врат Созанна на Хиджале.','Положите череп, чтобы заманить ее.','Деспериона') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Смерть праматери!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы нашли место кормежки матриарха к югу от Вершины Перерожденных.$B$BОна придет в ярость, узнав о потере одного из своих детей. Положи этот череп рядом с тушами, которые она ест. Если она где-то поблизости, то прилетит и попытается отомстить.$B$BТут-то мы и устроим ей сюрприз.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Положите череп сумеречного дракона на месте кормежки к югу от Вершины Перерожденных и убейте Деспериону.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Все прошло… лучше, чем ожидалось.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аронию, находящемуся у Врат Созанна на Хиджале.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Положите череп, чтобы заманить ее.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Деспериона',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25554,'Тайны пламени','Если мы хотим изгнать Рагнароса обратно на Огненные Просторы, нам надо получить доступ к Шпилю Сульфурона.$B$BТолько самые доверенные члены культа Сумеречного Молота могут владеть такой ценной информацией.$B$BИди на Вершину Перерожденных и найди записи – какие сумеешь. Пусть они и нечестивы, нельзя упускать такую возможность узнать о слабых местах нашего врага.','Добудьте Кодекс перерожденных, Горящие литании и фолиант Пламени на Вершине Перерожденных на Хиджале.','Этим нечестивым книгам нельзя позволить существовать. Однако имеющаяся в них информация жизненно необходима нам.','Вернитесь к Кенарию, находящемуся у Врат Созанна на Хиджале.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тайны пламени',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если мы хотим изгнать Рагнароса обратно на Огненные Просторы, нам надо получить доступ к Шпилю Сульфурона.$B$BТолько самые доверенные члены культа Сумеречного Молота могут владеть такой ценной информацией.$B$BИди на Вершину Перерожденных и найди записи – какие сумеешь. Пусть они и нечестивы, нельзя упускать такую возможность узнать о слабых местах нашего врага.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте Кодекс перерожденных, Горящие литании и фолиант Пламени на Вершине Перерожденных на Хиджале.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Этим нечестивым книгам нельзя позволить существовать. Однако имеющаяся в них информация жизненно необходима нам.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кенарию, находящемуся у Врат Созанна на Хиджале.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (25555,'Страж врат','Согласно этим фолиантам, один из наиболее могущественных помощников Рагнароса – единственный страж врат Шпиля Сульфурона.$B$BВ одиночку тебе его не одолеть.$B$BПротруби в этот рог, когда вступишь в бой с Азралоном, и все наши войска, находящиеся поблизости, придут тебе на помощь.$B$BТоропись, $n. Повелитель Огня скоро поймет, что мы затеяли.','Воспользуйтесь рогом Кенария, чтобы одолеть Азралона Привратника.','Дело сделано. До завершения миссии тебе остался только шаг.','Вернитесь к Кенарию, находящемуся у Врат Созанна на Хиджале.','Воспользуйтесь рогом, чтобы позвать войска на помощь.','Азралон Привратник') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Страж врат',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Согласно этим фолиантам, один из наиболее могущественных помощников Рагнароса – единственный страж врат Шпиля Сульфурона.$B$BВ одиночку тебе его не одолеть.$B$BПротруби в этот рог, когда вступишь в бой с Азралоном, и все наши войска, находящиеся поблизости, придут тебе на помощь.$B$BТоропись, $n. Повелитель Огня скоро поймет, что мы затеяли.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь рогом Кенария, чтобы одолеть Азралона Привратника.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Дело сделано. До завершения миссии тебе остался только шаг.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кенарию, находящемуся у Врат Созанна на Хиджале.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Воспользуйтесь рогом, чтобы позвать войска на помощь.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Азралон Привратник',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (25556,'Вглубь Зул\'Фаррака','Что за грязный предатель... Стоило дважды подумать, прежде чем довериться такому, как он. Страстное желание найти Суль\'траз затмило мне глаза.$b$bПрости меня, $n. Мазога сбежал в Зул\'Фаррак, сердце цивилизации песчаных троллей.$b$bЕсли ты и правда хочешь найти меч, тебе необходимо последовать за ним. В одиночку тебе не справиться – за этими стенами сосредоточена вся сила племени Песчаной Бури, и она готова обрушиться на тебя.$b$bЯ останусь здесь. Мои поиски должны закончиться. Если сможешь найти его, сохрани – я же должен остановиться прежде, чем его магия полностью охватит меня.','Найдите Мазогу в Зул\'Фарраке.','<Призрак Магозы улыбается вам окровавленными губами.>$B$BКак поживаешь?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вглубь Зул\'Фаррака',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что за грязный предатель... Стоило дважды подумать, прежде чем довериться такому, как он. Страстное желание найти Суль\'траз затмило мне глаза.$b$bПрости меня, $n. Мазога сбежал в Зул\'Фаррак, сердце цивилизации песчаных троллей.$b$bЕсли ты и правда хочешь найти меч, тебе необходимо последовать за ним. В одиночку тебе не справиться – за этими стенами сосредоточена вся сила племени Песчаной Бури, и она готова обрушиться на тебя.$b$bЯ останусь здесь. Мои поиски должны закончиться. Если сможешь найти его, сохрани – я же должен остановиться прежде, чем его магия полностью охватит меня.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Мазогу в Зул\'Фарраке.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Призрак Магозы улыбается вам окровавленными губами.>$B$BКак поживаешь?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25557,'Take a good look, mon. This is how it goes, betrayal after betrayal. I backstab you for the sword, and then Chief Ukorz go and backstab me even better for it.$B$BThat\'s life, yah! Or was...$B$BNow, I know you don\'t got no love for Mazoga. But I know you goin\' in there anyway. Kill him for me, mon. Spill more blood on the sand, an\' give Chief Ukorz Sandscalp what every one of us in here deserves...a gory death.$B$BMaybe I leave some of my belongin\'s without a curse before passin\' on if you do, yah?','Убейте вождя Укорза Песчаного Черепа.','Return to Mazoga in Zul\'Farrak.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Take a good look, mon. This is how it goes, betrayal after betrayal. I backstab you for the sword, and then Chief Ukorz go and backstab me even better for it.$B$BThat\'s life, yah! Or was...$B$BNow, I know you don\'t got no love for Mazoga. But I know you goin\' in there anyway. Kill him for me, mon. Spill more blood on the sand, an\' give Chief Ukorz Sandscalp what every one of us in here deserves...a gory death.$B$BMaybe I leave some of my belongin\'s without a curse before passin\' on if you do, yah?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте вождя Укорза Песчаного Черепа.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Return to Mazoga in Zul\'Farrak.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25558,'Все или ничего','Момент настал.$B$BЗдесь мы будем держать оборону.$B$BМы должны защищать корабль до последнего вздоха, и пускай эти недоумки в другой раз подумают дважды, прежде чем приблизиться к нему!$B$BДа вселят наши клинки ужас в их сердца!','Помогите капитану Тейлору защитить "Морской Кортик".','Служители Земли получили мой сигнал бедствия и выслали подмогу – очень вовремя, надо заметить.$B$BНадеюсь, вскоре придет еще подкрепление. Нас тут всего лишь горстка против армии врагов.','"Морской Кортик" потерян. Обратитесь к Эрунаку в Конце отмели.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Все или ничего',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Момент настал.$B$BЗдесь мы будем держать оборону.$B$BМы должны защищать корабль до последнего вздоха, и пускай эти недоумки в другой раз подумают дважды, прежде чем приблизиться к нему!$B$BДа вселят наши клинки ужас в их сердца!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Помогите капитану Тейлору защитить "Морской Кортик".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Служители Земли получили мой сигнал бедствия и выслали подмогу – очень вовремя, надо заметить.$B$BНадеюсь, вскоре придет еще подкрепление. Нас тут всего лишь горстка против армии врагов.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','"Морской Кортик" потерян. Обратитесь к Эрунаку в Конце отмели.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25559,'Предъявить права','Похоже, не мы одни интересуемся этими руинами. Ну и ну! И не кто-нибудь, а эльфы крови ошиваются на наших раскопках.$b$bЯ-то предполагал, что они мигом расплавятся на здешнем солнышке, без всех этих своих чудесных фонтанов и кружевных подушек, а получилось иначе. Они силой пытаются вытеснить нас из руин Южной Луны.$b$bПора показать им, кто тут главный. Отправляйся туда и научи их не вмешиваться в наши дела!','Убейте 10 эльфов крови – искателей.','Это вдвойне проучит Орду! Не стоит вмешиваться в историю дворфов, и нечего присылать на войну отряды хрупких лежебок!','Вернитесь к Ганстену на раскопки Ганстена, что в Танарисе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Предъявить права',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Похоже, не мы одни интересуемся этими руинами. Ну и ну! И не кто-нибудь, а эльфы крови ошиваются на наших раскопках.$b$bЯ-то предполагал, что они мигом расплавятся на здешнем солнышке, без всех этих своих чудесных фонтанов и кружевных подушек, а получилось иначе. Они силой пытаются вытеснить нас из руин Южной Луны.$b$bПора показать им, кто тут главный. Отправляйся туда и научи их не вмешиваться в наши дела!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 эльфов крови – искателей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это вдвойне проучит Орду! Не стоит вмешиваться в историю дворфов, и нечего присылать на войну отряды хрупких лежебок!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ганстену на раскопки Ганстена, что в Танарисе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (25561,'На оборону дилижанса... то есть лодки!','Вернитесь к Джинки Дзыньбламбум на гоночную баржу Пшикса и Поззика в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На оборону дилижанса... то есть лодки!',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джинки Дзыньбламбум на гоночную баржу Пшикса и Поззика в Тысяче Игл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (25562,'На оборону дилижанса... то есть лодки!','Вернитесь к Раззерику на гоночную баржу Пшикса и Поззика в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На оборону дилижанса... то есть лодки!',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Раззерику на гоночную баржу Пшикса и Поззика в Тысяче Игл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25563,'Докопаться до истины','На месте разлома осталось это странное устройство – но что это такое?$B$BВозможно, в столице кто-нибудь сумеет разобраться.','Отнесите загадочное устройство в Штормград, Стальгорн, Экзодар или Дарнас и покажите его представителю Служителей Земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Докопаться до истины',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На месте разлома осталось это странное устройство – но что это такое?$B$BВозможно, в столице кто-нибудь сумеет разобраться.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите загадочное устройство в Штормград, Стальгорн, Экзодар или Дарнас и покажите его представителю Служителей Земли.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25564,'Сухопутные и Морские Элитные войска Штормграда','Ты $gпослужил:послужила; нам верой и правдой, |3-6($c), поэтому я посвящу тебя в одну тайну. Люди, которых ты $gспас:спасла; сегодня, – это не регулярная армия Штормграда.$B$BМы – члены особого подразделения элитных войск, посланные сюда не только для оказания сопротивления Орде, но и для изучения значительных геологических возмущений, происходящих здесь на морском дне.$B$BЯ рассказываю тебе все это, поскольку наше сверхсекретное оборудование затонуло вместе с нашими кораблями.$B$BЕго надо вернуть!','Найдите 6 единиц оборудования штормградского СМЭШ.','Похоже, все оборудование в полном порядке.','Вернитесь с докладом к капитану Тейлору на "Морской Кортик".') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сухопутные и Морские Элитные войска Штормграда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gпослужил:послужила; нам верой и правдой, |3-6($c), поэтому я посвящу тебя в одну тайну. Люди, которых ты $gспас:спасла; сегодня, – это не регулярная армия Штормграда.$B$BМы – члены особого подразделения элитных войск, посланные сюда не только для оказания сопротивления Орде, но и для изучения значительных геологических возмущений, происходящих здесь на морском дне.$B$BЯ рассказываю тебе все это, поскольку наше сверхсекретное оборудование затонуло вместе с нашими кораблями.$B$BЕго надо вернуть!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите 6 единиц оборудования штормградского СМЭШ.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Похоже, все оборудование в полном порядке.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь с докладом к капитану Тейлору на "Морской Кортик".',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25565,'Фрагменты языка','Наконец-то за годы раскопок здесь, в руинах Южной Луны, нам удалось найти нечто действительно драгоценное. Мои парни обнаружили каменные скрижали, испещренные древними письменами.$b$BВыгравированные на них символы совершенно незнакомы, но интуиция подсказывает мне, что стоит сравнить их с письменами титанов, найденными на других раскопках. Ты только представь, что это будет за прорыв!$b$BМне нужно, чтобы ты $gотправился:отправилась; в руины Южной Луны и $gпомог:помогла; собрать скрижали. Если я отпущу туда еще кого-то из своих ребят, место раскопок будет немедленно захвачено эльфами крови!','Соберите 5 древних иероглифов.','Ты только посмотри... это не тролльский, и даже не киражский... настоящая загадка.$B$BНельзя выпускать их из рук, пока не соберем все до единой. Пора вернуться обратно в руины!','Вернитесь к Ганстену на раскопки Ганстена, что в Танарисе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Фрагменты языка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наконец-то за годы раскопок здесь, в руинах Южной Луны, нам удалось найти нечто действительно драгоценное. Мои парни обнаружили каменные скрижали, испещренные древними письменами.$b$BВыгравированные на них символы совершенно незнакомы, но интуиция подсказывает мне, что стоит сравнить их с письменами титанов, найденными на других раскопках. Ты только представь, что это будет за прорыв!$b$BМне нужно, чтобы ты $gотправился:отправилась; в руины Южной Луны и $gпомог:помогла; собрать скрижали. Если я отпущу туда еще кого-то из своих ребят, место раскопок будет немедленно захвачено эльфами крови!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 5 древних иероглифов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты только посмотри... это не тролльский, и даже не киражский... настоящая загадка.$B$BНельзя выпускать их из рук, пока не соберем все до единой. Пора вернуться обратно в руины!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ганстену на раскопки Ганстена, что в Танарисе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (25567,'Докопаться до истины') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Докопаться до истины',`title_loc8`);
