INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25571,'Природное явление','Этот осколок – все, что осталось от здешнего разлома. Какая связь между осколком и разломом – не ясно, но, быть может, в этом сумеет разобраться кто-то более сведущий в стихиях.$B$BРазыщи посланника Служителей Земли в любой из столиц. Возможно, это как раз то, что они ищут.','Отнесите осколок духа стихии посланнику Служителей Земли в Оргриммар, Подгород, Громовой Утес или Луносвет.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Природное явление',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этот осколок – все, что осталось от здешнего разлома. Какая связь между осколком и разломом – не ясно, но, быть может, в этом сумеет разобраться кто-то более сведущий в стихиях.$B$BРазыщи посланника Служителей Земли в любой из столиц. Возможно, это как раз то, что они ищут.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите осколок духа стихии посланнику Служителей Земли в Оргриммар, Подгород, Громовой Утес или Луносвет.',`objectives_loc8`);
