INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (25573,'Your Underwater Mount (Temp)','I set up some ropes on the ledge below. Just tie off your lure to one of the ropes and release it into the abyssal stream. If all goes well, one of the rays should come up for it almost immediately.$B$BI don\'t expect this to be even remotely easy, so hold on tight and keep an eye ahead at all times. If you should succeed in subduing one of the rays, bring it back here immediately so that we can feed it and cement the bond.$B$BI have a good feeling this time. I think this is it, $n.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Your Underwater Mount (Temp)',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','I set up some ropes on the ledge below. Just tie off your lure to one of the ropes and release it into the abyssal stream. If all goes well, one of the rays should come up for it almost immediately.$B$BI don\'t expect this to be even remotely easy, so hold on tight and keep an eye ahead at all times. If you should succeed in subduing one of the rays, bring it back here immediately so that we can feed it and cement the bond.$B$BI have a good feeling this time. I think this is it, $n.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25574,'Пламя свыше','Благодаря тебе, нам удалось определить, откуда к нам пробираются шпионы.$B$BТеперь нам надо лишь уничтожить их лагерь и положить конец их операциям по эту сторону Нордрассила.$B$BВозьми этот рог. С его помощью дай знак одному из зеленых драконов подлететь к сектантам Сумеречного Молота и дать им почувствовать жар пламени, которому они так безумно поклоняются.','Найдите лагерь Сумеречного Молота к северу от Нордрассила и используйте рог Толо.','Вернитесь к Толо Белому Копыту к Нордрассилу на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пламя свыше',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Благодаря тебе, нам удалось определить, откуда к нам пробираются шпионы.$B$BТеперь нам надо лишь уничтожить их лагерь и положить конец их операциям по эту сторону Нордрассила.$B$BВозьми этот рог. С его помощью дай знак одному из зеленых драконов подлететь к сектантам Сумеречного Молота и дать им почувствовать жар пламени, которому они так безумно поклоняются.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите лагерь Сумеречного Молота к северу от Нордрассила и используйте рог Толо.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Толо Белому Копыту к Нордрассилу на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25577,'Сокрушение основ','Эти обжигающие стражи просто ужасны! Мы уничтожаем их, а через считанные минуты они вновь разгораются из оставшегося пепла.$B$BЯ думаю, способ избавиться от них насовсем есть, но нам понадобится кто-то, способный прорваться через их авангард.$B$BУбей обжигающих стражей, $n, и отнеси их тлеющие ядра к расположенным рядом наковальням Сумеречного Молота. Разбей их на наковальнях и уничтожь навсегда!','Добудьте 8 тлеющих ядер, убивая обжигающих стражей, а затем разбейте их на наковальне Сумеречного Молота.','Отлично!$B$BБыло время, когда искатели приключений охотились за ядрами, из которых делались способные защитить от огня доспехи. Но сейчас я рад просто избавиться от этих чудовищ раз и навсегда.','Вернитесь к Йордану Олафсону, находящемуся в Кузне Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сокрушение основ',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти обжигающие стражи просто ужасны! Мы уничтожаем их, а через считанные минуты они вновь разгораются из оставшегося пепла.$B$BЯ думаю, способ избавиться от них насовсем есть, но нам понадобится кто-то, способный прорваться через их авангард.$B$BУбей обжигающих стражей, $n, и отнеси их тлеющие ядра к расположенным рядом наковальням Сумеречного Молота. Разбей их на наковальнях и уничтожь навсегда!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 8 тлеющих ядер, убивая обжигающих стражей, а затем разбейте их на наковальне Сумеречного Молота.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично!$B$BБыло время, когда искатели приключений охотились за ядрами, из которых делались способные защитить от огня доспехи. Но сейчас я рад просто избавиться от этих чудовищ раз и навсегда.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Йордану Олафсону, находящемуся в Кузне Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25578,'Возвращение к Нордрассилу','Я доставлю Фэндрала в Лунную поляну. Надеюсь, что успею возвратиться и помочь в бою.$B$BСейчас ступай к Изере и расскажи ей о случившемся.','Поговорите с Изерой у Нордрассила на Хиджале.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение к Нордрассилу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я доставлю Фэндрала в Лунную поляну. Надеюсь, что успею возвратиться и помочь в бою.$B$BСейчас ступай к Изере и расскажи ей о случившемся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Изерой у Нордрассила на Хиджале.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (25579,'Внезапный удар','Наш побег трудно было не заметить, но наги в руинах либо правда не знают об этом, либо не видят в нас никакой угрозы. И этим надо воспользоваться – мы нанесем им удар!$B$BОтправляйся на нижний ярус руин к западу отсюда и уничтожь там как можно больше патрульных. Смотри, чтобы ни один не ушел – враг не должен узнать, что мы поселились в этой пещере.','Вернитесь к адмиралу Двореку в Тихий залив.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Внезапный удар',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наш побег трудно было не заметить, но наги в руинах либо правда не знают об этом, либо не видят в нас никакой угрозы. И этим надо воспользоваться – мы нанесем им удар!$B$BОтправляйся на нижний ярус руин к западу отсюда и уничтожь там как можно больше патрульных. Смотри, чтобы ни один не ушел – враг не должен узнать, что мы поселились в этой пещере.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к адмиралу Двореку в Тихий залив.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (25580,'Быстрый подход','Я взял на себя смелость провести предварительную разведку и вот что выяснил: хотя наги не знают точно нашего расположения, они готовы к нападению.$B$BЗа часовыми наг находятся специальные магические устройства, оповещающие о приходе незваных гостей. К счастью, они пожертвовали качеством в угоду количеству: сигнал тревоги начинает передаваться не сразу после обнаружения вторжения. Этого времени как раз хватит, чтобы уничтожить эти устройства.$B$BДумаю, ты справишься до прибытия других солдат.','Вернитесь к капитану Тейлору в Тихий залив.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Быстрый подход',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я взял на себя смелость провести предварительную разведку и вот что выяснил: хотя наги не знают точно нашего расположения, они готовы к нападению.$B$BЗа часовыми наг находятся специальные магические устройства, оповещающие о приходе незваных гостей. К счастью, они пожертвовали качеством в угоду количеству: сигнал тревоги начинает передаваться не сразу после обнаружения вторжения. Этого времени как раз хватит, чтобы уничтожить эти устройства.$B$BДумаю, ты справишься до прибытия других солдат.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Тейлору в Тихий залив.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25581,'Чтобы занять время','Тебя ведь $n зовут, да? Мне нужна твоя помощь. Знаю, большинство моих сородичей считает, что сейчас главное – спасение наших жизней, но я не могу не думать о памяти предков.$B$BВсе, о чем я прошу, – смотри в оба и обращай внимание на все особенно важные предметы в городе. Больше всего меня интересуют статуи.','Осмотрите 4 неразрушенные статуи в садах Вайш\'ира.','Благодарю за то, что серьезно отнеслась к моей просьбе.$B$BЭто, можно сказать, первое доказательство существования других членов семьи Вайш. Очень интересно. А о двух других личностях я даже и не слышала.$B$BВеликий Раскол уничтожил нашу историю, но теперь появился шанс восстановить хоть какие-то ее страницы.','Вернитесь к Ливии Пробуждающей в Тихий залив.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чтобы занять время',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебя ведь $n зовут, да? Мне нужна твоя помощь. Знаю, большинство моих сородичей считает, что сейчас главное – спасение наших жизней, но я не могу не думать о памяти предков.$B$BВсе, о чем я прошу, – смотри в оба и обращай внимание на все особенно важные предметы в городе. Больше всего меня интересуют статуи.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Осмотрите 4 неразрушенные статуи в садах Вайш\'ира.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Благодарю за то, что серьезно отнеслась к моей просьбе.$B$BЭто, можно сказать, первое доказательство существования других членов семьи Вайш. Очень интересно. А о двух других личностях я даже и не слышала.$B$BВеликий Раскол уничтожил нашу историю, но теперь появился шанс восстановить хоть какие-то ее страницы.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ливии Пробуждающей в Тихий залив.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25582,'Новая база','Эта пещера – наше единственное пристанище. Отступать некуда, и никто не спешит нам на помощь. Что бы ни случилось, нельзя подвергать это место опасности, иначе мы все погибнем.$B$BНеобходим форпост, с которого мы будем проводить атаки.$B$BПосле того как окажешься на нижнем уровне в восточной части руин, осмотри следующие объекты: северную часть садов, проход под главным зданием к западу от садов, а также группу зданий в юго-восточном углу руин, что находится под мостами.$B$BСобери всю доступную информацию об этих местах.','Спуститесь на нижний уровень руин и исследуйте северную часть садов Кель\'Дормир, туннель, проходящий под руинами на западе от садов, и постройки в юго-восточном углу руин, под мостами.','Вернитесь к адмиралу Двореку в Тихий залив.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новая база',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эта пещера – наше единственное пристанище. Отступать некуда, и никто не спешит нам на помощь. Что бы ни случилось, нельзя подвергать это место опасности, иначе мы все погибнем.$B$BНеобходим форпост, с которого мы будем проводить атаки.$B$BПосле того как окажешься на нижнем уровне в восточной части руин, осмотри следующие объекты: северную часть садов, проход под главным зданием к западу от садов, а также группу зданий в юго-восточном углу руин, что находится под мостами.$B$BСобери всю доступную информацию об этих местах.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Спуститесь на нижний уровень руин и исследуйте северную часть садов Кель\'Дормир, туннель, проходящий под руинами на западе от садов, и постройки в юго-восточном углу руин, под мостами.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к адмиралу Двореку в Тихий залив.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25583,'На поле брани','Вокруг вас следы жестокой битвы. Но кроме скелетов наг, которые не представляют никакого интереса, вы видите останки их противников, к которым стоит присмотреться.$B$BВ одном из черепов вы замечаете крупный кусок металла. Сложно сказать, частью какого оружия он когда-то был, но вы решаете забрать его с собой.$B$BВ пещере им обязательно заинтересуются.','Отнесите обломок в Тихий залив.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На поле брани',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вокруг вас следы жестокой битвы. Но кроме скелетов наг, которые не представляют никакого интереса, вы видите останки их противников, к которым стоит присмотреться.$B$BВ одном из черепов вы замечаете крупный кусок металла. Сложно сказать, частью какого оружия он когда-то был, но вы решаете забрать его с собой.$B$BВ пещере им обязательно заинтересуются.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите обломок в Тихий залив.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25585,'Заставь пушки замолчать','Уничтожьте 8 пушек укрепления.','Все еще стреляют, но гораздо слабее, чем прежде! Ура-а-а-а-а!','Вернитесь к Джинки Дзыньбламбум на гоночную баржу Пшикса и Поззика в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Заставь пушки замолчать',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 8 пушек укрепления.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Все еще стреляют, но гораздо слабее, чем прежде! Ура-а-а-а-а!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джинки Дзыньбламбум на гоночную баржу Пшикса и Поззика в Тысяче Игл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25586,'Заставь пушки замолчать','Уничтожьте 8 пушек укрепления.','Все еще стреляют, но гораздо слабее, чем прежде! Ура-а-а-а-а!','Вернитесь к Раззерику на гоночную баржу Пшикса и Поззика в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Заставь пушки замолчать',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 8 пушек укрепления.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Все еще стреляют, но гораздо слабее, чем прежде! Ура-а-а-а-а!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Раззерику на гоночную баржу Пшикса и Поззика в Тысяче Игл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (25587,'Найдите мне убежище!','Прошу тебя, |3-6($r)! Ты $gдолжен:должна; мне помочь!$B$BЯ едва уцелела после той передряги с нагами, акулами и жутким монстром, напавшим на наш корабль.$B$BВон там на вид безопасная пещера, но я боюсь идти туда – вдруг в ней дышать нечем?$B$BНе $gмог:могла; бы ты проверить?','Поговорите с Адаррой в Пещере контрабандистов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Найдите мне убежище!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прошу тебя, |3-6($r)! Ты $gдолжен:должна; мне помочь!$B$BЯ едва уцелела после той передряги с нагами, акулами и жутким монстром, напавшим на наш корабль.$B$BВон там на вид безопасная пещера, но я боюсь идти туда – вдруг в ней дышать нечем?$B$BНе $gмог:могла; бы ты проверить?',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Адаррой в Пещере контрабандистов.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (25588,'Частичная расплата','Вернитесь к опытному гонщику Миглену на гоночную баржу Пшикса и Поззика в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Частичная расплата',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к опытному гонщику Миглену на гоночную баржу Пшикса и Поззика в Тысяче Игл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25589,'Частичная расплата','Поделом этим вшивым псам! Спасибо тебе, Фатбойслим.','Вернитесь к Грубоступу на гоночную баржу Пшикса и Поззика в Тысячу Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Частичная расплата',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Поделом этим вшивым псам! Спасибо тебе, Фатбойслим.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Грубоступу на гоночную баржу Пшикса и Поззика в Тысячу Игл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (25590,'Куда подевался Виззл?','Эй! Вытащи меня отсюда!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Куда подевался Виззл?',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Эй! Вытащи меня отсюда!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (25591,'Громодром: решающая битва!','Похоже, у нас особая заявка! У меня тут записка от некой Мегз Жестекрошшер с требованием открыть ворота и продолжить соревнования.$b$bОна хочет, чтобы ты $gстал:стала; ее противником, $n. Поклонница твоих предыдущих побед? А может быть, о тебе знают и за пределами этого ринга?$b$bЯ бы на твоем месте не стал отступать. Это будет грандиозный финал...','Одержите победу над Келси Стализвон.','Потрясающе. Однажды я сама вызову тебя на дуэль.','Келси Стализвон побеждена','Вернитесь к Катрине Тернер в Прибамбасск, что в Танарисе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Громодром: решающая битва!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Похоже, у нас особая заявка! У меня тут записка от некой Мегз Жестекрошшер с требованием открыть ворота и продолжить соревнования.$b$bОна хочет, чтобы ты $gстал:стала; ее противником, $n. Поклонница твоих предыдущих побед? А может быть, о тебе знают и за пределами этого ринга?$b$bЯ бы на твоем месте не стал отступать. Это будет грандиозный финал...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Одержите победу над Келси Стализвон.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Потрясающе. Однажды я сама вызову тебя на дуэль.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Келси Стализвон побеждена',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Катрине Тернер в Прибамбасск, что в Танарисе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25592,'Глубокая привязанность','Я проводил нескольких выживших к пещере, но вокруг нее стало очень опасно. Помимо всего прочего на нас еще начали нападать светящиеся мурлоки – они вылезают из расселины и атакуют выживших.$B$BТам, наверху, остались настоящие воины – они не сдадутся без боя. Но после пребывания в этой проклятой ракушке у них совсем не осталось сил.$B$BЕсли ты еще можешь сражаться, отправляйся туда и убей нескольких мурлоков. Адский Крик следит за тобой.','Убейте 10 краснобородок-падальщиков.','Вернитесь к легионеру Назгриму на базу Легиона.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Глубокая привязанность',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я проводил нескольких выживших к пещере, но вокруг нее стало очень опасно. Помимо всего прочего на нас еще начали нападать светящиеся мурлоки – они вылезают из расселины и атакуют выживших.$B$BТам, наверху, остались настоящие воины – они не сдадутся без боя. Но после пребывания в этой проклятой ракушке у них совсем не осталось сил.$B$BЕсли ты еще можешь сражаться, отправляйся туда и убей нескольких мурлоков. Адский Крик следит за тобой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 краснобородок-падальщиков.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к легионеру Назгриму на базу Легиона.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25593,'Спасение в ракушке','Многие из наших до сих пор не добрались до пещеры. Думаю, они все еще на рифе над нами.$B$BПо пути сюда мы нашли несколько спиралангов. Они выделяют немного воздуха – как раз достаточно, чтобы добраться до пещеры.$B$BМне нужно остаться здесь, чтобы считать выживших и ставить на ноги вновь прибывших. Окажи услугу – собери несколько спиралангов, отнеси их моим ребятам, оставшимся на рифе, и скажи, чтобы они поторапливались.','Соберите 8 спиралангов и отдайте их спасенным из Неспиры.','Вернитесь к капитану Злобешипу на базу Легиона.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спасение в ракушке',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Многие из наших до сих пор не добрались до пещеры. Думаю, они все еще на рифе над нами.$B$BПо пути сюда мы нашли несколько спиралангов. Они выделяют немного воздуха – как раз достаточно, чтобы добраться до пещеры.$B$BМне нужно остаться здесь, чтобы считать выживших и ставить на ноги вновь прибывших. Окажи услугу – собери несколько спиралангов, отнеси их моим ребятам, оставшимся на рифе, и скажи, чтобы они поторапливались.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 спиралангов и отдайте их спасенным из Неспиры.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Злобешипу на базу Легиона.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25594,'Хитрые крабы','Мерзкий краб!$B$BА я-то думал, что так здорово натренировался по пути сюда – рюкзак казался все легче и легче. Ан, нет! Это краб проделал дырку в рюкзаке, и весь мой скарб потихоньку выпадал по дороге.$B$BПожалуйста, помоги красавчику-гоблину, а? Посмотри вокруг и подбери все, что выпало из рюкзака. Впрочем, эти коварные гаденыши наверняка что-то уже себе стащили.','Соберите 12 потерянных вещей Облина.','Вижу, легкую добычу ты за версту чуешь. Приятно иметь с тобой дело, приятель.','Помни: нельзя недооценивать силу блестящих вещичек.','Вернитесь к Облину Свистозубу на базу Легиона.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хитрые крабы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мерзкий краб!$B$BА я-то думал, что так здорово натренировался по пути сюда – рюкзак казался все легче и легче. Ан, нет! Это краб проделал дырку в рюкзаке, и весь мой скарб потихоньку выпадал по дороге.$B$BПожалуйста, помоги красавчику-гоблину, а? Посмотри вокруг и подбери все, что выпало из рюкзака. Впрочем, эти коварные гаденыши наверняка что-то уже себе стащили.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 12 потерянных вещей Облина.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вижу, легкую добычу ты за версту чуешь. Приятно иметь с тобой дело, приятель.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Помни: нельзя недооценивать силу блестящих вещичек.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Облину Свистозубу на базу Легиона.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25595,'Что-нибудь съестное','Они что, хотели уморить нас голодом?! Не кормить пленников – это просто низко.$B$BНужно накормить солдат, а по дороге сюда я как раз приметила огромного морского окуня. Если добыть несколько таких – ребятам долго есть не захочется.$B$BПринеси мне несколько морских окуней, а я прослежу, чтобы их вкусно приготовили и разделили поровну.','Принесите 8 кусков мяса окуня-хрустогрыза.','Теперь дело за мной – приступлю к готовке и раздаче прямо сейчас.$B$BА потом нам с тобой надо побеседовать. Мне нужна твоя помощь – солдаты в этом деле бессильны.','Из-за бурчания в животах уже кажется, будто здесь рычащее чудовище поселилось. Это действует мне на нервы.','Вернитесь к говорящей с волнами Талре на базу Легиона.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Что-нибудь съестное',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Они что, хотели уморить нас голодом?! Не кормить пленников – это просто низко.$B$BНужно накормить солдат, а по дороге сюда я как раз приметила огромного морского окуня. Если добыть несколько таких – ребятам долго есть не захочется.$B$BПринеси мне несколько морских окуней, а я прослежу, чтобы их вкусно приготовили и разделили поровну.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 8 кусков мяса окуня-хрустогрыза.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь дело за мной – приступлю к готовке и раздаче прямо сейчас.$B$BА потом нам с тобой надо побеседовать. Мне нужна твоя помощь – солдаты в этом деле бессильны.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Из-за бурчания в животах уже кажется, будто здесь рычащее чудовище поселилось. Это действует мне на нервы.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к говорящей с волнами Талре на базу Легиона.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (25596,'Куда подевался Синг?','Эй! Вытащи меня отсюда!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Куда подевался Синг?',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Эй! Вытащи меня отсюда!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25598,'Вопреки гордости','Теперь, когда мы в безопасности, окажи мне еще одну услугу, сделай милость.$B$BСамир, капитан нашего судна, должен быть где-то поблизости. И с ним Мак. Уверена, они добрались до морского дна, но я точно не знаю, что с ними стало.$B$BЕсли бы не они, мне давно пришел бы конец.$B$BЯ потеряла их из виду в зарослях водорослей к западу от того места, где ты меня $gнашел:нашла;.$B$BПожалуйста, поторопись! Они не могли уйти далеко...','Найдите Самира и Мака.','Вернитесь к Адарре в Пещеру контрабандистов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вопреки гордости',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда мы в безопасности, окажи мне еще одну услугу, сделай милость.$B$BСамир, капитан нашего судна, должен быть где-то поблизости. И с ним Мак. Уверена, они добрались до морского дна, но я точно не знаю, что с ними стало.$B$BЕсли бы не они, мне давно пришел бы конец.$B$BЯ потеряла их из виду в зарослях водорослей к западу от того места, где ты меня $gнашел:нашла;.$B$BПожалуйста, поторопись! Они не могли уйти далеко...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Самира и Мака.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Адарре в Пещеру контрабандистов.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (25599,'Мастер порталов Пепельный Молот','В Сумеречном Молоте пользуются этими и подобными проходами для поставки припасов из царства стихий в Азерот. Чтобы закрыть их, нам нужно понять, как они устроены.$B$BНайди и принеси мне фолиант отворения, которым элементали пользуются для открытия врат между мирами.$B$BДолжно быть, фолиант находится у мастера порталов Пепельного Молота. Придется его убить. Будь настороже – сдается мне, у него найдется чем защищаться.','Убейте Пепельного Молота и добудьте фолиант отворения.','Это и есть тот самый фолиант?$B$B<Йордан взвешивает в руках каменную глыбу и осматривает ее.>$B$BЯсно… Хорошо, что я немного разбираюсь в письменности элементалей. Попробую перевести этот текст. А тебе пока придется заняться еще одной, последней проблемой.','Тебе удалось достать фолиант?','Принесите фолиант отворения Йордану Олафсону в Кузню Пламени.','Не забывай об осторожности: Пепельный Молот почти наверняка призовет подкрепление из царства стихий.','Мастер порталов Пепельный Молот') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мастер порталов Пепельный Молот',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В Сумеречном Молоте пользуются этими и подобными проходами для поставки припасов из царства стихий в Азерот. Чтобы закрыть их, нам нужно понять, как они устроены.$B$BНайди и принеси мне фолиант отворения, которым элементали пользуются для открытия врат между мирами.$B$BДолжно быть, фолиант находится у мастера порталов Пепельного Молота. Придется его убить. Будь настороже – сдается мне, у него найдется чем защищаться.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Пепельного Молота и добудьте фолиант отворения.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это и есть тот самый фолиант?$B$B<Йордан взвешивает в руках каменную глыбу и осматривает ее.>$B$BЯсно… Хорошо, что я немного разбираюсь в письменности элементалей. Попробую перевести этот текст. А тебе пока придется заняться еще одной, последней проблемой.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось достать фолиант?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите фолиант отворения Йордану Олафсону в Кузню Пламени.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Не забывай об осторожности: Пепельный Молот почти наверняка призовет подкрепление из царства стихий.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Мастер порталов Пепельный Молот',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (25600,'Начальник кузни Пламий','В сердце этой пещеры таится древнее зло, $n. Начальник кузни Пламий собственноручно выковал множество нечестивых орудий, которые культ Сумеречного Молота использует для завоевания нашего мира.$B$BПеред тем, как покинуть владения огня, нужно убить Пламия.$B$BЕго будет сложно одолеть. Однако если я правильно понял содержание фолианта, мы сможем на мгновенье открыть врата в Бездонную пучину, царство воды. Замани Пламия на руну портала и активируй ее, чтобы лишить его силы.','Убейте начальника кузни Пламия. Заманите его на руны порталов и используйте их, чтобы ослабить его.','Вернитесь к Йордану Олафсону, находящемуся в Кузне Пламени','Воспользуйтесь рунами вокруг Пламия, чтобы его убить. Просто так его не побороть.','Начальник кузни Пламий') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Начальник кузни Пламий',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В сердце этой пещеры таится древнее зло, $n. Начальник кузни Пламий собственноручно выковал множество нечестивых орудий, которые культ Сумеречного Молота использует для завоевания нашего мира.$B$BПеред тем, как покинуть владения огня, нужно убить Пламия.$B$BЕго будет сложно одолеть. Однако если я правильно понял содержание фолианта, мы сможем на мгновенье открыть врата в Бездонную пучину, царство воды. Замани Пламия на руну портала и активируй ее, чтобы лишить его силы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте начальника кузни Пламия. Заманите его на руны порталов и используйте их, чтобы ослабить его.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Йордану Олафсону, находящемуся в Кузне Пламени',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Воспользуйтесь рунами вокруг Пламия, чтобы его убить. Просто так его не побороть.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Начальник кузни Пламий',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25602,'Без бума нет огня','Мак все еще без сознания, и я боюсь, что мы его потеряем, если не разведем костер. Поленья мокрые, надо как-то заставить их разгореться.$B$BТут поблизости в заброшенном лагере я видел бесхозную бочку взрывчатки. Сам я ее не дотащу.$B$BСделай милость, приволоки ее. Ради Мака...','Раздобудьте бочонок с порохом на Раскопках Бадда.','Вернитесь к Самиру в Пещеру контрабандистов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Без бума нет огня',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мак все еще без сознания, и я боюсь, что мы его потеряем, если не разведем костер. Поленья мокрые, надо как-то заставить их разгореться.$B$BТут поблизости в заброшенном лагере я видел бесхозную бочку взрывчатки. Сам я ее не дотащу.$B$BСделай милость, приволоки ее. Ради Мака...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте бочонок с порохом на Раскопках Бадда.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Самиру в Пещеру контрабандистов.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (25602,'Превосходно!$B$BПосмотрим, что из этого выйдет...$B$BОтойди подальше, Гнобс!','Взрывчатка из лагеря у тебя, $C?') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Превосходно!$B$BПосмотрим, что из этого выйдет...$B$BОтойди подальше, Гнобс!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Взрывчатка из лагеря у тебя, $C?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (25603,'Докопаться до истины') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Докопаться до истины',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25604,'Докопаться до истины','На месте разлома осталось это странное устройство – но что это такое?$B$BВозможно, в столице кто-нибудь сумеет разобраться.','Отнесите загадочное устройство в Штормград, Стальгорн, Экзодар или Дарнас и покажите его представителю Служителей Земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Докопаться до истины',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На месте разлома осталось это странное устройство – но что это такое?$B$BВозможно, в столице кто-нибудь сумеет разобраться.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите загадочное устройство в Штормград, Стальгорн, Экзодар или Дарнас и покажите его представителю Служителей Земли.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (25605,'Докопаться до истины') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Докопаться до истины',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (25606,'Докопаться до истины') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Докопаться до истины',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25607,'ГНМ-передатчик','Я этих гоблидов на дух де передошу. Их гряздой гоблидской техдологии до гдомской как до деба. И все же...$B$B<Профессор Закзак вздыхает.>$B$BЭто последдий фрагмедт загадки! Без гряздой гоблидской техдологии нельзя создать ГНМ-передатчик!$B$BСтупай на восток в производстведдый цех и добудь у них гряздый гоблидский хлам! Ты наверняка дайдешь его на гряздых гоблидских техниках.$B$B<Профессор Закзак злобно хихикает.>$B$BГоблид-техдник? Да где это видадо?$B$B<Профессор Закзак пожимает плечами.>$B$BЧушь какая-то!','Добудьте 8 образцов грязной гоблинской технологии.','Вернитесь к профессору Закзаку Атвертку в Башню Звездной Пыли в Ясеневом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','ГНМ-передатчик',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я этих гоблидов на дух де передошу. Их гряздой гоблидской техдологии до гдомской как до деба. И все же...$B$B<Профессор Закзак вздыхает.>$B$BЭто последдий фрагмедт загадки! Без гряздой гоблидской техдологии нельзя создать ГНМ-передатчик!$B$BСтупай на восток в производстведдый цех и добудь у них гряздый гоблидский хлам! Ты наверняка дайдешь его на гряздых гоблидских техниках.$B$B<Профессор Закзак злобно хихикает.>$B$BГоблид-техдник? Да где это видадо?$B$B<Профессор Закзак пожимает плечами.>$B$BЧушь какая-то!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 8 образцов грязной гоблинской технологии.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к профессору Закзаку Атвертку в Башню Звездной Пыли в Ясеневом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25608,'Жги-руби!','Победа возможна, $n.$B$BЭтот портал – не только средство вернуть Кенария из сна. Подумай, $n. Как только врата в Изумрудный Сон будут открыты, наши силы смогут воспользоваться ими, чтобы свободно попасть из Лунной поляны, Нордрассила и даже Драконьего Покоя в это стратегически важное место.$B$BИзере нужно лишь время. На тебя ложится задача не дать силам Сумеречного Молота соединиться в Теснине Зловещего Шепота и напасть на нас с востока.$B$BВозьми одного из изумрудных драконов и нанеси им серьезный удар, $n.','Верхом на изумрудном драконе истребите 40 прислужников Сумеречного Молота и 5 сумеречных драконов.','Вернитесь к командиру Джероду Песни Теней, находящемуся у Врат Созанна.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жги-руби!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Победа возможна, $n.$B$BЭтот портал – не только средство вернуть Кенария из сна. Подумай, $n. Как только врата в Изумрудный Сон будут открыты, наши силы смогут воспользоваться ими, чтобы свободно попасть из Лунной поляны, Нордрассила и даже Драконьего Покоя в это стратегически важное место.$B$BИзере нужно лишь время. На тебя ложится задача не дать силам Сумеречного Молота соединиться в Теснине Зловещего Шепота и напасть на нас с востока.$B$BВозьми одного из изумрудных драконов и нанеси им серьезный удар, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верхом на изумрудном драконе истребите 40 прислужников Сумеречного Молота и 5 сумеречных драконов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру Джероду Песни Теней, находящемуся у Врат Созанна.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25609,'Затонувшее сокровище','Ключ от клетки у Тони Два Клыка, адмирала пиратов, а его охраняют огры, которые тебе точно не по зубам!$B$B<Виззл продолжает хныкать, затем задумчиво смотрит вверх: в его голове явно зреет какая-то мысль.>$B$BЗнаю! Что пираты любят больше всего на свете? Да нет, не ром. Кое-что получше... сокровища!$B$BИх корабль с полным трюмом сокровищ потопила гигантская китовая акула. Сокровище разбросано по всей Бездне миражей к северо-западу отсюда.$B$BПринеси его мне!','Соберите 8 затонувших сундуков с сокровищами.','Вот это да! Только полюбуйтесь на эту добычу.$B$BПостой-ка... а ну-ка поднеси поближе!','Ну и дела, ты уже собрал все эти затонувшие сокровища?','Вернитесь к Виззлу Медноштифу в Укрепление Южных морей в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Затонувшее сокровище',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ключ от клетки у Тони Два Клыка, адмирала пиратов, а его охраняют огры, которые тебе точно не по зубам!$B$B<Виззл продолжает хныкать, затем задумчиво смотрит вверх: в его голове явно зреет какая-то мысль.>$B$BЗнаю! Что пираты любят больше всего на свете? Да нет, не ром. Кое-что получше... сокровища!$B$BИх корабль с полным трюмом сокровищ потопила гигантская китовая акула. Сокровище разбросано по всей Бездне миражей к северо-западу отсюда.$B$BПринеси его мне!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 затонувших сундуков с сокровищами.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот это да! Только полюбуйтесь на эту добычу.$B$BПостой-ка... а ну-ка поднеси поближе!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну и дела, ты уже собрал все эти затонувшие сокровища?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Виззлу Медноштифу в Укрепление Южных морей в Тысяче Игл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25610,'Затонувшее сокровище','Ключ от клетки у Тони Два Клыка, адмирала пиратов, а его охраняют огры, которые тебе точно не по зубам!$B$B<Виззл продолжает хныкать, затем задумчиво смотрит вверх: в его голове явно зреет какая-то мысль.>$B$BЗнаю! Что пираты любят больше всего на свете? Да нет, не ром. Кое-что получше... сокровища!$B$BИх корабль с полным трюмом сокровищ потопила гигантская китовая акула. Сокровище разбросано по всей Бездне миражей к северо-западу отсюда.$B$BПринеси его мне!','Соберите 8 затонувших сундуков с сокровищами.','Вот это да! Только полюбуйтесь на эту добычу.$B$BПостой-ка... а ну-ка поднеси поближе!','Ты достал уже все затонувшее сокровище?','Вернитесь к Сингу в Укрепление Южных морей в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Затонувшее сокровище',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ключ от клетки у Тони Два Клыка, адмирала пиратов, а его охраняют огры, которые тебе точно не по зубам!$B$B<Виззл продолжает хныкать, затем задумчиво смотрит вверх: в его голове явно зреет какая-то мысль.>$B$BЗнаю! Что пираты любят больше всего на свете? Да нет, не ром. Кое-что получше... сокровища!$B$BИх корабль с полным трюмом сокровищ потопила гигантская китовая акула. Сокровище разбросано по всей Бездне миражей к северо-западу отсюда.$B$BПринеси его мне!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 затонувших сундуков с сокровищами.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот это да! Только полюбуйтесь на эту добычу.$B$BПостой-ка... а ну-ка поднеси поближе!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты достал уже все затонувшее сокровище?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сингу в Укрепление Южных морей в Тысяче Игл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25611,'Возвращение с Огненных просторов','Я провожу наружу оставшихся последователей Голдринна и запечатаю за нами портал.$B$BНаши силы на горе Хиджал должны услышать об этой победе. Возвращайся к Яну Дюрану и расскажи ему о нашем триумфе и о том, что мы обнаружили!$B$BЧтобы вернуться на гору Хиджал, просто пройди через портал.','Вернитесь к Яну Дюрану в Святилище Голдринна на горе Хиджал.','Вернитесь к Яну Дюрану в Святилище Голдринна на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение с Огненных просторов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я провожу наружу оставшихся последователей Голдринна и запечатаю за нами портал.$B$BНаши силы на горе Хиджал должны услышать об этой победе. Возвращайся к Яну Дюрану и расскажи ему о нашем триумфе и о том, что мы обнаружили!$B$BЧтобы вернуться на гору Хиджал, просто пройди через портал.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь к Яну Дюрану в Святилище Голдринна на горе Хиджал.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Яну Дюрану в Святилище Голдринна на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25612,'Возвращение с Огненных Просторов','Я провожу наружу оставшихся последователей Ло\'гоша и запечатаю за нами портал.$B$BОстатки наших сил, закрепившиеся на горе Хиджал, захотят услышать о нашей победе. Вернись к Такрику Гневному Вою и расскажи ему о том, что мы открыли, а также какую победу нам довелось одержать!$B$BЧтобы вернуться на гору Хиджал, просто пройди в портал.','Вернитесь к Такрику Гневному Вою в Святилище Голдринна на горе Хиджал.','Вернитесь к Такрику Гневному Вою в Святилище Голдринна на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение с Огненных Просторов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я провожу наружу оставшихся последователей Ло\'гоша и запечатаю за нами портал.$B$BОстатки наших сил, закрепившиеся на горе Хиджал, захотят услышать о нашей победе. Вернись к Такрику Гневному Вою и расскажи ему о том, что мы открыли, а также какую победу нам довелось одержать!$B$BЧтобы вернуться на гору Хиджал, просто пройди в портал.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь к Такрику Гневному Вою в Святилище Голдринна на горе Хиджал.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Такрику Гневному Вою в Святилище Голдринна на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (25613,'Сделай себе одолжение','Эти Ночные эльфы, значит, передали нам отчаянную просьбу о помощи типа такой:$B$B<Гномбус меняет тембр голоса, чтобы тот стал похож на женский.>$B$B"Ой, мамочки, помогите! У большой злой Орды есть гоблины! Ой, мы не умеем драться с гоблинами! Они нам все волосенки повыдергают, ой, мы плакать будем!"$B$BНу ладно, в общем, вот они мы.$B$BПервое, что я хотел сделать, – это укомплектовать их системы воздушной защиты несколькими моими снайперскими ружьями. Только они, видишь ли, не умеют пользоваться ружьями! Так что сделай себе одолжение и помоги им, ладно? Они где-то к югу отсюда.','Поговорите с Каленом Метким Выстрелом в его лагере в Когтистых горах.','<Кален вздыхает.>$B$BДа, с ружьями-то у нас порядок. А вот с ПУШКАМИ – да, с ними у меня проблемы…') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сделай себе одолжение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти Ночные эльфы, значит, передали нам отчаянную просьбу о помощи типа такой:$B$B<Гномбус меняет тембр голоса, чтобы тот стал похож на женский.>$B$B"Ой, мамочки, помогите! У большой злой Орды есть гоблины! Ой, мы не умеем драться с гоблинами! Они нам все волосенки повыдергают, ой, мы плакать будем!"$B$BНу ладно, в общем, вот они мы.$B$BПервое, что я хотел сделать, – это укомплектовать их системы воздушной защиты несколькими моими снайперскими ружьями. Только они, видишь ли, не умеют пользоваться ружьями! Так что сделай себе одолжение и помоги им, ладно? Они где-то к югу отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Каленом Метким Выстрелом в его лагере в Когтистых горах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Кален вздыхает.>$B$BДа, с ружьями-то у нас порядок. А вот с ПУШКАМИ – да, с ними у меня проблемы…',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25614,'Вниз – только мертвыми','В небе полно орков в тяжелых доспехах, которые летают верхом на ветрокрылах в еще более тяжелой броне. Как бы мы ни пытались сбить их – ничего не помогает. Наши стрелы просто отскакивают от этих мерзавцев, а если мы вдруг кого и собьем, то орки преспокойненько опускаются на землю на гоблинских парашютах.$B$BЯ хочу, чтобы ты сперва $gсбил:сбила; из снайперских пушек ветрокрылов Песни Войны, а потом и парашютирующих орков.$B$BЕсли уж они и спустятся вниз, то пусть только мертвыми.','Убейте 8 командиров звена Песни Войны.','Великолепно, $n. Гномские технологии порой жутковаты, но довольно эффективны. Теперь мы можем свободно пройти в крепость Ветрорезов.','Сообщите новости Калену Меткому Выстрелу в его лагере в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вниз – только мертвыми',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В небе полно орков в тяжелых доспехах, которые летают верхом на ветрокрылах в еще более тяжелой броне. Как бы мы ни пытались сбить их – ничего не помогает. Наши стрелы просто отскакивают от этих мерзавцев, а если мы вдруг кого и собьем, то орки преспокойненько опускаются на землю на гоблинских парашютах.$B$BЯ хочу, чтобы ты сперва $gсбил:сбила; из снайперских пушек ветрокрылов Песни Войны, а потом и парашютирующих орков.$B$BЕсли уж они и спустятся вниз, то пусть только мертвыми.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 командиров звена Песни Войны.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Великолепно, $n. Гномские технологии порой жутковаты, но довольно эффективны. Теперь мы можем свободно пройти в крепость Ветрорезов.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Сообщите новости Калену Меткому Выстрелу в его лагере в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (25615,'Обратно в замок Звездной Пыли') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обратно в замок Звездной Пыли',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25616,'Наследие Адского Крика','Ступай в Когтистые горы через Тропу Когтя и иди прямо к дымящимся деревьям. Найди кром\'гарских поджигателей, которые уничтожают лес, и перебей, сколько удастся! Осторожнее: поджигатели – могучие орки. Если нападешь на них с обычным оружием, то, скорее всего, погибнешь. Уничтожай канистры с маслом, что у них на спинах, и их охватит пламя!$B$BДоложись часовому Элиане, если справишься с задачей. Она даст тебе новые поручения.','Убейте 10 кром\'гарских поджигателей.','Теперь, когда покончено с кром\'гарскими поджигателями, лес сможет вырасти снова. Только время залечит раны, нанесенные Ордой.','Обратитесь к часовому Элиане на руднике Ветрорезов в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наследие Адского Крика',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ступай в Когтистые горы через Тропу Когтя и иди прямо к дымящимся деревьям. Найди кром\'гарских поджигателей, которые уничтожают лес, и перебей, сколько удастся! Осторожнее: поджигатели – могучие орки. Если нападешь на них с обычным оружием, то, скорее всего, погибнешь. Уничтожай канистры с маслом, что у них на спинах, и их охватит пламя!$B$BДоложись часовому Элиане, если справишься с задачей. Она даст тебе новые поручения.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 кром\'гарских поджигателей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь, когда покончено с кром\'гарскими поджигателями, лес сможет вырасти снова. Только время залечит раны, нанесенные Ордой.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Обратитесь к часовому Элиане на руднике Ветрорезов в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (25617,'Из огня да в полымя!','На вершине Уступа Молний Сумеречный Молот воздвиг огненные врата. Куда они ведут, мне неизвестно. Я ничего не знаю о мире за вратами и пройти через них не могу. Из посланных туда моих последователей никто не вернулся.$B$BЯ прошу тебя пойти туда и побыть моими глазами и ушами, а если надо, то и клыками.$B$BПройди через огненные врата и поговори с Йорданом Олафсоном, если он, конечно, еще жив. Он даст тебе знак, позволяющий пользоваться там моей силой.$B$BСмелее, $n! Выясни, куда ведут эти врата, и уничтожь то, что лежит за ними.','Да, это о тебе возвещал Ло\'гош. Твои глаза не обманывают тебя: ты оказался на Огненных Просторах, в обители стихий расплавленного камня и огня. Дел у нас здесь просто невпроворот.$B$BЗабудь о разногласиях с Альянсом, здесь и так достаточно жарко.$B$BИ возьми вот это: клык Ло\'гоша позволит тебе привлекать могущество Древнего здесь, на Огненных Просторах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Из огня да в полымя!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На вершине Уступа Молний Сумеречный Молот воздвиг огненные врата. Куда они ведут, мне неизвестно. Я ничего не знаю о мире за вратами и пройти через них не могу. Из посланных туда моих последователей никто не вернулся.$B$BЯ прошу тебя пойти туда и побыть моими глазами и ушами, а если надо, то и клыками.$B$BПройди через огненные врата и поговори с Йорданом Олафсоном, если он, конечно, еще жив. Он даст тебе знак, позволяющий пользоваться там моей силой.$B$BСмелее, $n! Выясни, куда ведут эти врата, и уничтожь то, что лежит за ними.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, это о тебе возвещал Ло\'гош. Твои глаза не обманывают тебя: ты оказался на Огненных Просторах, в обители стихий расплавленного камня и огня. Дел у нас здесь просто невпроворот.$B$BЗабудь о разногласиях с Альянсом, здесь и так достаточно жарко.$B$BИ возьми вот это: клык Ло\'гоша позволит тебе привлекать могущество Древнего здесь, на Огненных Просторах.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (25618,'Из огня да в полымя!','На вершине Уступа Молний Сумеречный Молот воздвиг огненные врата. Куда они ведут, мне неизвестно. Я ничего не знаю о мире за вратами и пройти через них не могу. Из посланных туда моих последователей никто не вернулся.$B$BЯ прошу тебя пойти туда и побыть моими глазами и ушами, а если надо, то и клыками.$B$BПройди через огненные врата и поговори с Йорданом Олафсоном, если он, конечно, еще жив. Он даст тебе знак, позволяющий пользоваться там моей силой.$B$BСмелее, $n! Выясни, куда ведут эти врата, и уничтожь то, что лежит за ними.','Да, Голдринн говорил, что ты придешь. Твои глаза не обманывают тебя: ты оказался на Огненных Просторах, в обители стихий расплавленного камня и огня. Дел у нас здесь просто невпроворот.$B$BЗабудь о разногласиях с Ордой, здесь и так достаточно жарко.$B$BИ возьми вот это: здесь, на Огненных Просторах, клык Голдринна позволит тебе направлять древние силы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Из огня да в полымя!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На вершине Уступа Молний Сумеречный Молот воздвиг огненные врата. Куда они ведут, мне неизвестно. Я ничего не знаю о мире за вратами и пройти через них не могу. Из посланных туда моих последователей никто не вернулся.$B$BЯ прошу тебя пойти туда и побыть моими глазами и ушами, а если надо, то и клыками.$B$BПройди через огненные врата и поговори с Йорданом Олафсоном, если он, конечно, еще жив. Он даст тебе знак, позволяющий пользоваться там моей силой.$B$BСмелее, $n! Выясни, куда ведут эти врата, и уничтожь то, что лежит за ними.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, Голдринн говорил, что ты придешь. Твои глаза не обманывают тебя: ты оказался на Огненных Просторах, в обители стихий расплавленного камня и огня. Дел у нас здесь просто невпроворот.$B$BЗабудь о разногласиях с Ордой, здесь и так достаточно жарко.$B$BИ возьми вот это: здесь, на Огненных Просторах, клык Голдринна позволит тебе направлять древние силы.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25619,'Повторный захват','Квалдиров все еще полно. Но, вероятно, они пока не оправились от нашей атаки. Этот город давно пустует – они не ожидали, что наги осмелятся на них напасть.$B$BГде их предводитель, пока неизвестно. Но если планомерно уничтожать его подчиненных, этот трус рано или поздно проявится.$B$BПродолжим?','Убейте 10 квалдирских защитников в Руинах Вайш\'ира.$B$BЭто задание из цикла "Видения воительницы Леди Наз\'жар". Чтобы вернуться к видению, воспользуйтесь в нужном месте клинком воительницы Леди Наз\'жар.','Ха! Вижу, ты была права. Этот сломанный трезубец хорошо служит. Похоже, голыми руками тебе сегодня убивать не придется.','Вернитесь к подводному ловчему Азжентусу в Руины Вайш\'ира.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Повторный захват',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Квалдиров все еще полно. Но, вероятно, они пока не оправились от нашей атаки. Этот город давно пустует – они не ожидали, что наги осмелятся на них напасть.$B$BГде их предводитель, пока неизвестно. Но если планомерно уничтожать его подчиненных, этот трус рано или поздно проявится.$B$BПродолжим?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 квалдирских защитников в Руинах Вайш\'ира.$B$BЭто задание из цикла "Видения воительницы Леди Наз\'жар". Чтобы вернуться к видению, воспользуйтесь в нужном месте клинком воительницы Леди Наз\'жар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ха! Вижу, ты была права. Этот сломанный трезубец хорошо служит. Похоже, голыми руками тебе сегодня убивать не придется.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к подводному ловчему Азжентусу в Руины Вайш\'ира.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25620,'Моя прекрасная леди','Тебе послание от госпожи. Она ждет на дальней окраине садов храма.$B$BИ если вдруг захочешь упомянуть героические подвиги своего брата по оружию Азжентуса – прошу, не сдерживайся! Я не против.$B$BНе буду тебя задерживать – госпожа ждет.','Поговорите с Леди Наз\'жар в северной части садов Кель\'Дормир.$B$BЭто задание из цикла "Видения воительницы Леди Наз\'жар". Чтобы вернуться к видению, в нужном месте воспользуйтесь клинком воительницы Леди Наз\'жар.','О, моя Воительница, ты здесь. Каста воинов полнится слухами о твоих победах, а мы ведь только начали захватывать город.$B$BТы сослужила мне хорошую службу. Да благословит тебя Королева на дальнейшие подвиги.','Поговорите с Леди Наз\'жар в северной части храмовых садов Вайш\'ира.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Моя прекрасная леди',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе послание от госпожи. Она ждет на дальней окраине садов храма.$B$BИ если вдруг захочешь упомянуть героические подвиги своего брата по оружию Азжентуса – прошу, не сдерживайся! Я не против.$B$BНе буду тебя задерживать – госпожа ждет.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Леди Наз\'жар в северной части садов Кель\'Дормир.$B$BЭто задание из цикла "Видения воительницы Леди Наз\'жар". Чтобы вернуться к видению, в нужном месте воспользуйтесь клинком воительницы Леди Наз\'жар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, моя Воительница, ты здесь. Каста воинов полнится слухами о твоих победах, а мы ведь только начали захватывать город.$B$BТы сослужила мне хорошую службу. Да благословит тебя Королева на дальнейшие подвиги.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Леди Наз\'жар в северной части храмовых садов Вайш\'ира.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (25621,'Полевые испытания: ГНМ-передатчик','ГНМ-передатчик готов! Теперь дадо его испытать!$B$BОтправляйся в Когтистые горы да юго-востоке и спускайся по Тропе Когтя, пока де даткдешься на гряздую гоблячью сверлилку. Когда доберешься до места, я активирую ГНМ-передатчик!','Ступайте в Когтистые горы и идите по Тропе Когтя, пока не наткнетесь на гоблинскую сверлильную машину.','<ГНМ-передатчик трещит и щелкает от электрических разрядов.>$b$bДавай, $n. Ты бедя слышишь? Это профессор Закзак!$b$b*ХЛОП*$b$b*ТРРР*$b$bБЛЕСТЯЩЕ! С ГНМ-передатчиком я смогу даправить тебя в Когтистые горы, а сам буду в безопасности!$b$bТеперь следующее по списку дело!','Работа ГНМ-передатчика проверена','Проходи!','Профессор Закзак Атвертук') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Полевые испытания: ГНМ-передатчик',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','ГНМ-передатчик готов! Теперь дадо его испытать!$B$BОтправляйся в Когтистые горы да юго-востоке и спускайся по Тропе Когтя, пока де даткдешься на гряздую гоблячью сверлилку. Когда доберешься до места, я активирую ГНМ-передатчик!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Ступайте в Когтистые горы и идите по Тропе Когтя, пока не наткнетесь на гоблинскую сверлильную машину.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<ГНМ-передатчик трещит и щелкает от электрических разрядов.>$b$bДавай, $n. Ты бедя слышишь? Это профессор Закзак!$b$b*ХЛОП*$b$b*ТРРР*$b$bБЛЕСТЯЩЕ! С ГНМ-передатчиком я смогу даправить тебя в Когтистые горы, а сам буду в безопасности!$b$bТеперь следующее по списку дело!',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Работа ГНМ-передатчика проверена',`endtext_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Проходи!',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Профессор Закзак Атвертук',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (25622,'Гори-гори ясно!','Эти орки, что пожгли лес, досят с собой мощдое оружие! Перебей их и забери у них огдеметы. Как только их заберешь, обыщи лес, дайди их схроны, а потом сожги их огдеметом!$B$BСожги их, и я тебя дагражу! Да, ГНМ-передатчик может переправлять предметы!$B$BСтой! Ты слышишь?! Тут вроде как орк деподалеку! Будь дачеку!','Добудьте огнемет Песни Войны у кром\'гарских поджигателей и с его помощью сожгите 8 схронов Песни Войны.','Что тагое?','Профессор Закзак Атвертук','Огужие Песни Войны погсюду!','Профессор Закзак Атвертук') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гори-гори ясно!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти орки, что пожгли лес, досят с собой мощдое оружие! Перебей их и забери у них огдеметы. Как только их заберешь, обыщи лес, дайди их схроны, а потом сожги их огдеметом!$B$BСожги их, и я тебя дагражу! Да, ГНМ-передатчик может переправлять предметы!$B$BСтой! Ты слышишь?! Тут вроде как орк деподалеку! Будь дачеку!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте огнемет Песни Войны у кром\'гарских поджигателей и с его помощью сожгите 8 схронов Песни Войны.',`objectives_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Что тагое?',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Профессор Закзак Атвертук',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Огужие Песни Войны погсюду!',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Профессор Закзак Атвертук',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (25623,'Из огня да в полымя!','А вот и ты, $n! У Голдринна есть задание, которое может выполнить только один из его защитников. На вершине Уступа Молний Сумеречный Молот воздвиг огненные врата. Куда они ведут, нам неизвестно, но Голдринн через них пройти не может. Древний просит тебя побыть его когтями и клыками.$B$BВойди в огненные врата и, когда вступишь в них, поговори с Йорданом Олафсоном. Он даст тебе знак, позволяющий пользоваться в другом мире силой Голдринна. Выясни, куда ведут эти врата!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Из огня да в полымя!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А вот и ты, $n! У Голдринна есть задание, которое может выполнить только один из его защитников. На вершине Уступа Молний Сумеречный Молот воздвиг огненные врата. Куда они ведут, нам неизвестно, но Голдринн через них пройти не может. Древний просит тебя побыть его когтями и клыками.$B$BВойди в огненные врата и, когда вступишь в них, поговори с Йорданом Олафсоном. Он даст тебе знак, позволяющий пользоваться в другом мире силой Голдринна. Выясни, куда ведут эти врата!',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (25624,'Из огня да в полымя!','$n! Ты $gнужен:нужна; Ло\'гошу. На вершине Уступа Молний культ Сумеречного Молота открыл огненные врата. Мы не знаем, куда они ведут, но ни один из тех, кто прошел ими, не вернулся назад. Тебе предстоит отправиться туда и стать там глазами, ушами, а если потребуется, то и клыками Ло\'гоша.$B$BПройди в огненные врата и найди Йордана Олафсона. Он даст тебе знак, при помощи которого ты сможешь призывать силу Ло\'гоша даже в ином мире. Выясни, куда ведут огненные врата!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Из огня да в полымя!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n! Ты $gнужен:нужна; Ло\'гошу. На вершине Уступа Молний культ Сумеречного Молота открыл огненные врата. Мы не знаем, куда они ведут, но ни один из тех, кто прошел ими, не вернулся назад. Тебе предстоит отправиться туда и стать там глазами, ушами, а если потребуется, то и клыками Ло\'гоша.$B$BПройди в огненные врата и найди Йордана Олафсона. Он даст тебе знак, при помощи которого ты сможешь призывать силу Ло\'гоша даже в ином мире. Выясни, куда ведут огненные врата!',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (25625,'Piercing the Ruins') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Piercing the Ruins',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25626,'Видения прошлого: подъем из глубин','Я все думаю о том, что ты $gрассказал:рассказала; о нагах. Кто их союзники? Неужели они верят, что смогут победить Хозяина Приливов?$B$BСкоро мы выберемся из этой пещеры, но сначала мы должны достигнуть поставленной цели. Надеюсь, ты согласишься в последний раз узнать что-нибудь у Воительницы.$B$BОсталось только одно место, где мог побывать этот артефакт, – храм над руинами. Но его наверняка хорошо охраняют. Будь $gосторожен:осторожна;.','Воспользуйтесь сломанным клинком Воительницы в храме Кель\'Дормир и посмотрите заключительную часть истории.','Вернитесь к говорящей с волнами Валорен в Тихий залив.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Видения прошлого: подъем из глубин',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я все думаю о том, что ты $gрассказал:рассказала; о нагах. Кто их союзники? Неужели они верят, что смогут победить Хозяина Приливов?$B$BСкоро мы выберемся из этой пещеры, но сначала мы должны достигнуть поставленной цели. Надеюсь, ты согласишься в последний раз узнать что-нибудь у Воительницы.$B$BОсталось только одно место, где мог побывать этот артефакт, – храм над руинами. Но его наверняка хорошо охраняют. Будь $gосторожен:осторожна;.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь сломанным клинком Воительницы в храме Кель\'Дормир и посмотрите заключительную часть истории.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к говорящей с волнами Валорен в Тихий залив.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (25627,'Убрать Тони Два Клыка','Это не сокровище, а груда мусора, но эти безмозглые громилы наверняка не заметят разницы. Недоумки-огры!$B$BВот что мы сделаем... иди в Укрытие адмирала и раскидай это "сокровище" перед ограми, чтобы их отвлечь. А затем сразись с Тони Два Клыка.$B$BПолучишь ключ от клетки легко!','Раздобудьте ржавый ключ от клетки.','Да-да-да... Уверен, твои похождения в пещере были очень увлекательны.$B$BНо, может, обсудим их за стаканчиком чего-нибудь на гоночной барже, когда ты выпустишь меня из этой клетки?','Ну, в чем дело? Ты выпустишь меня отсюда или нет?','Вернитесь к Виззлу Медноштифу в Укрепление Южных морей в Тысяче Игл.','Заберите ржавый ключ от клетки у адмирала пиратов Тони Два Клыка.','Тони Два Клыка') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Убрать Тони Два Клыка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это не сокровище, а груда мусора, но эти безмозглые громилы наверняка не заметят разницы. Недоумки-огры!$B$BВот что мы сделаем... иди в Укрытие адмирала и раскидай это "сокровище" перед ограми, чтобы их отвлечь. А затем сразись с Тони Два Клыка.$B$BПолучишь ключ от клетки легко!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте ржавый ключ от клетки.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да-да-да... Уверен, твои похождения в пещере были очень увлекательны.$B$BНо, может, обсудим их за стаканчиком чего-нибудь на гоночной барже, когда ты выпустишь меня из этой клетки?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, в чем дело? Ты выпустишь меня отсюда или нет?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Виззлу Медноштифу в Укрепление Южных морей в Тысяче Игл.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Заберите ржавый ключ от клетки у адмирала пиратов Тони Два Клыка.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Тони Два Клыка',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (25628,'Убрать Тони Два Клыка','Это не сокровище, а груда мусора, но эти безмозглые громилы наверняка не заметят разницы. Недоумки-огры!$B$BВот что мы сделаем... иди в Укрытие адмирала и раскидай это "сокровище" перед ограми, чтобы их отвлечь. А затем сразись с Тони Два Клыка.$B$BПолучишь ключ от клетки легко!','Раздобудьте ржавый ключ от клетки.','Да-да-да... Уверен, твои похождения в пещере были очень увлекательны.$B$BНо, может, обсудим их за стаканчиком чего-нибудь на гоночной барже, когда ты выпустишь меня из этой клетки?','Ну, в чем дело? Ты выпустишь меня отсюда или нет?','Вернитесь к Сингу в Укрепление Южных морей в Тысяче Игл.','Заберите ржавый ключ от клетки у адмирала пиратов Тони Два Клыка.','Тони Два Клыка') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Убрать Тони Два Клыка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это не сокровище, а груда мусора, но эти безмозглые громилы наверняка не заметят разницы. Недоумки-огры!$B$BВот что мы сделаем... иди в Укрытие адмирала и раскидай это "сокровище" перед ограми, чтобы их отвлечь. А затем сразись с Тони Два Клыка.$B$BПолучишь ключ от клетки легко!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте ржавый ключ от клетки.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да-да-да... Уверен, твои похождения в пещере были очень увлекательны.$B$BНо, может, обсудим их за стаканчиком чего-нибудь на гоночной барже, когда ты выпустишь меня из этой клетки?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, в чем дело? Ты выпустишь меня отсюда или нет?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сингу в Укрепление Южных морей в Тысяче Игл.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Заберите ржавый ключ от клетки у адмирала пиратов Тони Два Клыка.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Тони Два Клыка',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25629,'Указание госпожи','Воительница!$B$BНайди на поле боя моих отважных стражей и убей их противников. Нужно, чтобы они немедленно вернулись сюда и защитили жриц!$B$BЯ постараюсь удержать вход. Не медли!','Найдите на поле боя 8 отважных стражей Леди Наз\'жар, победите их противников и передайте им новые приказы.$B$BЭто задание из цикла "Видения воительницы Леди Наз\'жар". Чтобы вернуться к видению, в нужном месте воспользуйтесь клинком воительницы Леди Наз\'жар.','Отлично, Воительница.$B$BЯ отправлюсь к восточному мосту, а ты следуй в сам храм. Нельзя допустить, чтобы ритуал прервался.','Вернитесь к Леди Наз\'жар в храм Кель\'Дормир.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Указание госпожи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Воительница!$B$BНайди на поле боя моих отважных стражей и убей их противников. Нужно, чтобы они немедленно вернулись сюда и защитили жриц!$B$BЯ постараюсь удержать вход. Не медли!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите на поле боя 8 отважных стражей Леди Наз\'жар, победите их противников и передайте им новые приказы.$B$BЭто задание из цикла "Видения воительницы Леди Наз\'жар". Чтобы вернуться к видению, в нужном месте воспользуйтесь клинком воительницы Леди Наз\'жар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, Воительница.$B$BЯ отправлюсь к восточному мосту, а ты следуй в сам храм. Нельзя допустить, чтобы ритуал прервался.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Леди Наз\'жар в храм Кель\'Дормир.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25630,'Хиджал в огне','Поговорите с Лайной Ночное Небо возле Рощи Эссины на горе Хиджал.','Поговорите с Лайной Ночное Небо возле Рощи Эссины на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хиджал в огне',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Лайной Ночное Небо возле Рощи Эссины на горе Хиджал.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Лайной Ночное Небо возле Рощи Эссины на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25631,'Внезапный удар','I can\'t imagine that our escape from the shell went unnoticed, but either the naga at these ruins were not informed or don\'t consider us a threat. I do not intend to take such opportunities for granted – we must strike now.$B$BI need you to slip into the lower level of the ruins and take out as many of their patrols as you can. We cannot risk any of those patrols finding out about our occupation of this cave – make sure none escape.','Уничтожьте 10 патрульных Азш\'ира.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Внезапный удар',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','I can\'t imagine that our escape from the shell went unnoticed, but either the naga at these ruins were not informed or don\'t consider us a threat. I do not intend to take such opportunities for granted – we must strike now.$B$BI need you to slip into the lower level of the ruins and take out as many of their patrols as you can. We cannot risk any of those patrols finding out about our occupation of this cave – make sure none escape.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 10 патрульных Азш\'ира.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25632,'Шустрый план','Я взял на себя смелость провести предварительную разведку. И вот что выяснил.$B$BЗа часовыми наг находятся специальные магические устройства, оповещающие о приходе незваных гостей. К счастью, они пожертвовали качеством в угоду количеству: между тем, когда ты подойдешь к устройствам, и тем, когда они начнут транслировать сигнал тревоги, есть временной зазор. Его как раз хватит, чтобы их уничтожить.$B$BДумаю, ты справишься до прибытия других солдат.','Уничтожьте 10 часовых Азш\'ира.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Шустрый план',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я взял на себя смелость провести предварительную разведку. И вот что выяснил.$B$BЗа часовыми наг находятся специальные магические устройства, оповещающие о приходе незваных гостей. К счастью, они пожертвовали качеством в угоду количеству: между тем, когда ты подойдешь к устройствам, и тем, когда они начнут транслировать сигнал тревоги, есть временной зазор. Его как раз хватит, чтобы их уничтожить.$B$BДумаю, ты справишься до прибытия других солдат.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 10 часовых Азш\'ира.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25633,'Чтобы занять время','Look--$n is it?--I need your help. I know most everyone in this cave thinks that we\'re not in a position to be worrying about anything but our own hides right now, but we have an amazing opportunity here.$B$BThis was one of the royal cities of the elves in the days when Azshara was queen. In this city lie the keys to lore long lost and artifacts of unimaginable historical value. All I want from you, while you\'re out on your little jaunt, is to keep an eye out for exactly those kinds of things.','Investigate the 6 in-tact statues in the Vashj\'ir Gardens.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чтобы занять время',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Look--$n is it?--I need your help. I know most everyone in this cave thinks that we\'re not in a position to be worrying about anything but our own hides right now, but we have an amazing opportunity here.$B$BThis was one of the royal cities of the elves in the days when Azshara was queen. In this city lie the keys to lore long lost and artifacts of unimaginable historical value. All I want from you, while you\'re out on your little jaunt, is to keep an eye out for exactly those kinds of things.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Investigate the 6 in-tact statues in the Vashj\'ir Gardens.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25634,'A Better Vantage','This cave is our only refuge. There\'s no place to which we can retreat. There\'s no help on the way. Whatever happens, this cave must remain safe or we are all sure to die down here.$B$BI have no intention of standing idle. The best way to keep the naga from finding us is to keep them off-balance, but we can\'t risk them following us back here between strikes. We need a forward post to launch or attacks from.$B$BI\'d like you scout the ruins for a suitable base of operation. Something defensible.','Scout out the Garden Plaza, the Main Road, and the Temple District.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','A Better Vantage',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','This cave is our only refuge. There\'s no place to which we can retreat. There\'s no help on the way. Whatever happens, this cave must remain safe or we are all sure to die down here.$B$BI have no intention of standing idle. The best way to keep the naga from finding us is to keep them off-balance, but we can\'t risk them following us back here between strikes. We need a forward post to launch or attacks from.$B$BI\'d like you scout the ruins for a suitable base of operation. Something defensible.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Scout out the Garden Plaza, the Main Road, and the Temple District.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25635,'Upon the Scene of Battle','All around you lie the remnants of a fierce battle. The naga skeletons are no surprise, but the weapons and remains of their apparent opponents are somewhat more unexpected.$B$BAmidst the bones, you spot a strangely prominent piece of metal jutting out from one of the skulls. It\'s difficult to tell what sort of weapon it might have once been part of, but it stands out sufficiently to prompt you to retrieve it as evidence.$B$BSurely someone back at the cave would be interested in this revelation.','Bring the broken shard back to THE CAVE.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Upon the Scene of Battle',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','All around you lie the remnants of a fierce battle. The naga skeletons are no surprise, but the weapons and remains of their apparent opponents are somewhat more unexpected.$B$BAmidst the bones, you spot a strangely prominent piece of metal jutting out from one of the skulls. It\'s difficult to tell what sort of weapon it might have once been part of, but it stands out sufficiently to prompt you to retrieve it as evidence.$B$BSurely someone back at the cave would be interested in this revelation.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Bring the broken shard back to THE CAVE.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25636,'Холоду суп, а жару – в зуб','Мак то приходит в себя, то снова проваливается в забытье.$B$BЧтобы он выкарабкался, нам придется приложить все силы.$B$BЯ знаю отличный рецепт черепашьего супа, который его согреет.$B$BПринеси мне черепашьего мяса, остальное беру на себя.','Добудьте 4 куска мяса пятнистой морской черепахи.','Поговорите с Самиром в Пещере контрабандистов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Холоду суп, а жару – в зуб',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мак то приходит в себя, то снова проваливается в забытье.$B$BЧтобы он выкарабкался, нам придется приложить все силы.$B$BЯ знаю отличный рецепт черепашьего супа, который его согреет.$B$BПринеси мне черепашьего мяса, остальное беру на себя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 4 куска мяса пятнистой морской черепахи.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Самиром в Пещере контрабандистов.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25637,'Зов Повелителя глубин','Повелитель глубин Зин\'жатар сообщил, что наконец-то объявился предводитель квалдиров. Отправляйся к нему в угол Террасы Нар\'шолы, расположенной над нами в средней части руин.$B$BУбей всех квалдиров, которые встанут у тебя на пути. Пусть хорошенько запомнят, что не стоит с нами связываться, и дважды подумают, прежде чем вернуться и угрожать нашим планам.$B$BТвоя преданность не осталась незамеченной. Я даю тебе свое благословение. А теперь ступай.','Убейте 16 квалдиров на террасе Нар\'шолы.$B$BЭто задание из цикла "Видения воительницы Леди Наз\'жар". Чтобы вернуться к видению, в нужный момент воспользуйтесь клинком воительницы Леди Наз\'жар.','Я рад, что ты со мной, Воительница. Отзвуки твоих побед ласкают наш слух.','Поговорите с Повелителем глубин Зин\'жатаром в южной части террасы Нар\'шолы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зов Повелителя глубин',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Повелитель глубин Зин\'жатар сообщил, что наконец-то объявился предводитель квалдиров. Отправляйся к нему в угол Террасы Нар\'шолы, расположенной над нами в средней части руин.$B$BУбей всех квалдиров, которые встанут у тебя на пути. Пусть хорошенько запомнят, что не стоит с нами связываться, и дважды подумают, прежде чем вернуться и угрожать нашим планам.$B$BТвоя преданность не осталась незамеченной. Я даю тебе свое благословение. А теперь ступай.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 16 квалдиров на террасе Нар\'шолы.$B$BЭто задание из цикла "Видения воительницы Леди Наз\'жар". Чтобы вернуться к видению, в нужный момент воспользуйтесь клинком воительницы Леди Наз\'жар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я рад, что ты со мной, Воительница. Отзвуки твоих побед ласкают наш слух.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Повелителем глубин Зин\'жатаром в южной части террасы Нар\'шолы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (25638,'Мольба о помощи','Записка в бутылке намокла, но ее содержание все еще можно разобрать.$B$BЕе автор утверждает, что ему удалось бежать из некой подводной темницы наг.$B$BЧувствуется, что он пребывает в страхе за свою жизнь, и вы гадаете, не один ли это из ваших недавно плененных товарищей по плаванию.$B$BПоломав голову над тем, как отыскать беглеца, вы решаете поделиться находкой с Эрунаком.','Отнесите промокшую записку Эрунаку на Конец отмели.','Если он еще жив, возможно, я сумею отыскать беднягу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мольба о помощи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Записка в бутылке намокла, но ее содержание все еще можно разобрать.$B$BЕе автор утверждает, что ему удалось бежать из некой подводной темницы наг.$B$BЧувствуется, что он пребывает в страхе за свою жизнь, и вы гадаете, не один ли это из ваших недавно плененных товарищей по плаванию.$B$BПоломав голову над тем, как отыскать беглеца, вы решаете поделиться находкой с Эрунаком.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите промокшую записку Эрунаку на Конец отмели.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Если он еще жив, возможно, я сумею отыскать беднягу.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (25639,'[DND] Test Rifts') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DND] Test Rifts',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25640,'Сбрасывай бомбу: рудник Ветрорезов!','Ми знаем, где спрятана бонба, какую ты $gнашел:нашла; в Приюте Серебряного Ветра.$B$BБуга-то помнишь? Ну гнома, какого ти $gспас:спасла; из орочьего фургона агонии? Ну дак вот, он и Минкс соследили, что бонбу отволокли в рудник Ветрорезов. Иди туда, $n, прям щас иди! Они тоже там, тебя ждут!','Разыщите Буга "Моднявого" в руднике Ветрорезов в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сбрасывай бомбу: рудник Ветрорезов!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ми знаем, где спрятана бонба, какую ты $gнашел:нашла; в Приюте Серебряного Ветра.$B$BБуга-то помнишь? Ну гнома, какого ти $gспас:спасла; из орочьего фургона агонии? Ну дак вот, он и Минкс соследили, что бонбу отволокли в рудник Ветрорезов. Иди туда, $n, прям щас иди! Они тоже там, тебя ждут!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите Буга "Моднявого" в руднике Ветрорезов в Когтистых горах.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (25641,'Поток уменьшения','Я сделала все, что было в моих силах. Я пока еще не умею работать с существами сильнее, чем уменьшенные гиппогрифы. Это привело бы к катастрофе, так что такую сделку мы с тобой заключать не станем.$B$BНо пока ты $gзанимался:занималась; своими делами, у меня было время как следует поработать с уменьшенным гиппогрифом. Отнеси это моему учителю, знахарю Узер\'и в лагерь Мохаче. Он сможет сделать с помощью этого великолепное оружие, и, надеюсь, впечатлится моими успехами.','Принесите сосуд уменьшения знахарю Узер\'и в лагерь Мохаче в Фераласе.','Очень хорошо… От своей дочери я ничего меньше и не ждал. Когда-нибудь она станет отличной знахаркой.','В тебе мне чудится что-то знакомое...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поток уменьшения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я сделала все, что было в моих силах. Я пока еще не умею работать с существами сильнее, чем уменьшенные гиппогрифы. Это привело бы к катастрофе, так что такую сделку мы с тобой заключать не станем.$B$BНо пока ты $gзанимался:занималась; своими делами, у меня было время как следует поработать с уменьшенным гиппогрифом. Отнеси это моему учителю, знахарю Узер\'и в лагерь Мохаче. Он сможет сделать с помощью этого великолепное оружие, и, надеюсь, впечатлится моими успехами.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите сосуд уменьшения знахарю Узер\'и в лагерь Мохаче в Фераласе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Очень хорошо… От своей дочери я ничего меньше и не ждал. Когда-нибудь она станет отличной знахаркой.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','В тебе мне чудится что-то знакомое...',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25642,'Не смотри им в глаза','Пригнись-ка, $n, не надо привлекать внимания.$B$BМне кажется, что орки набивают вон тот шар какой-то рудой из шахты. Сходи-ка туда и набери такой руды. Принеси все, что сможешь собрать, а я отправлю руду профессору для изучения.$B$BИ вот тебе еще совет на дорожку: Кром\'гаров не бойся, потому что они, во-первых, тупые пни, а во-вторых, когда тащат руду, то ничего не видят. Ясное дело, чтобы отобрать у них руду, придется их убить.','Соберите 10 образцов лазурной железной руды.','Надеюсь, это было не слишком трудно. Теперь мы изучим образцы и узнаем, что они собрались делать со всей этой рудой и бомбами.','Давай тащи руду!','Вернитесь к Бугу "Моднявому" в рудник Ветрорезов в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Не смотри им в глаза',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пригнись-ка, $n, не надо привлекать внимания.$B$BМне кажется, что орки набивают вон тот шар какой-то рудой из шахты. Сходи-ка туда и набери такой руды. Принеси все, что сможешь собрать, а я отправлю руду профессору для изучения.$B$BИ вот тебе еще совет на дорожку: Кром\'гаров не бойся, потому что они, во-первых, тупые пни, а во-вторых, когда тащат руду, то ничего не видят. Ясное дело, чтобы отобрать у них руду, придется их убить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 образцов лазурной железной руды.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Надеюсь, это было не слишком трудно. Теперь мы изучим образцы и узнаем, что они собрались делать со всей этой рудой и бомбами.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Давай тащи руду!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бугу "Моднявому" в рудник Ветрорезов в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (25643,'Руины Мглистой пещеры','Меня преследуют видения, |3-6($c). Я вижу артефакт великой силы, попавший в дурные руки. Я вижу амулет в руках древних эльфов... Он забыт, а то место, где он хранится, обращается в руины; а потом он из-за предательства и жестокости окажется во власти демонов...$B$BКаждую ночь эти видения наполняют мои сны. Духи хотят нас предостеречь. Мне уже слишком много лет, а храбрецы из лагеря чрезмерно заняты, охраняя нас. Придется попросить тебя последовать за моими видениями. Ступай на юг, в руины Мглистой пещеры, и отыщи там амулет.','Отыщите в руинах Мглистой пещеры амулет, о котором говорил ведун Легкая Побежка.','<Вы протягиваете руку к пьедесталу, но там пусто. В комнате вдруг становится очень холодно, и вы слышите слабый голос…>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Руины Мглистой пещеры',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Меня преследуют видения, |3-6($c). Я вижу артефакт великой силы, попавший в дурные руки. Я вижу амулет в руках древних эльфов... Он забыт, а то место, где он хранится, обращается в руины; а потом он из-за предательства и жестокости окажется во власти демонов...$B$BКаждую ночь эти видения наполняют мои сны. Духи хотят нас предостеречь. Мне уже слишком много лет, а храбрецы из лагеря чрезмерно заняты, охраняя нас. Придется попросить тебя последовать за моими видениями. Ступай на юг, в руины Мглистой пещеры, и отыщи там амулет.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщите в руинах Мглистой пещеры амулет, о котором говорил ведун Легкая Побежка.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Вы протягиваете руку к пьедесталу, но там пусто. В комнате вдруг становится очень холодно, и вы слышите слабый голос…>',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25644,'Яйцо чистого сумрака','<Это яйцо не похоже на все, что вы видели прежде. Полупрозрачная скорлупа словно искривляет свет, и он обтекает яйцо.>$B$B<Вместе с ним вы находите записку, в которой говорится о прибытии праматери на Вершину Перерожденных.>$B$B<Возможно, вам надо показать свою находку Аронию.>','Отнесите яйцо чистого сумрака Аронию к Вратам Созанна на Хиджале.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Яйцо чистого сумрака',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Это яйцо не похоже на все, что вы видели прежде. Полупрозрачная скорлупа словно искривляет свет, и он обтекает яйцо.>$B$B<Вместе с ним вы находите записку, в которой говорится о прибытии праматери на Вершину Перерожденных.>$B$B<Возможно, вам надо показать свою находку Аронию.>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите яйцо чистого сумрака Аронию к Вратам Созанна на Хиджале.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25645,'Вернуться к ведуну Легкая Побежка','Мягкий свет пьедестала становится ярче, и на нем оказывается простая цепочка. Должно быть, это и есть тот амулет, за которым вас послал ведун Легкая Побежка.','Отнесите амулет Мглистой пещеры ведуну Легкая Побежка.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вернуться к ведуну Легкая Побежка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мягкий свет пьедестала становится ярче, и на нем оказывается простая цепочка. Должно быть, это и есть тот амулет, за которым вас послал ведун Легкая Побежка.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите амулет Мглистой пещеры ведуну Легкая Побежка.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25646,'Зачистка рудника Ветрорезов','Убейте 6 надзирателей долины Ветрорезов.','Молодец, их вопли даже отсюда было слышно. Ты там просто все с ног на голову перевернул!$B$BА больше ничего про операции в шахтах не удалось узнать?','Вернитесь к часовому Элиане на рудник Ветрорезов в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зачистка рудника Ветрорезов',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 6 надзирателей долины Ветрорезов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Молодец, их вопли даже отсюда было слышно. Ты там просто все с ног на голову перевернул!$B$BА больше ничего про операции в шахтах не удалось узнать?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к часовому Элиане на рудник Ветрорезов в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (25647,'Не поддающееся чтению письмо орков','Вы обнаружили кусок пергамента с ордынской печатью, которая выглядит довольно солидно. К сожалению, весь документ написан на орочьем языке, прочитать его невозможно.$B$BНадо отнести письмо Бугу, вдруг он что-нибудь придумает!','Отнесите не поддающееся чтению письмо орков Бугу "Моднявому" в рудник Ветрорезов в Когтистых горах.','<Буг берет у вас письмо и принимается его изучать.>$B$BИнтересно.$B$B<Буг нюхает пергамент.>$B$BХм… Это нехорошо…$B$B<Буг складывает пергамент пополам и смотрит на вас.>$B$BНе могу я разобрать, что тут написано – если это вообще можно назвать письмом. Может, это вообще туалетная бумага. Судя по запаху, так оно и есть.','Чего там у тебя?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Не поддающееся чтению письмо орков',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы обнаружили кусок пергамента с ордынской печатью, которая выглядит довольно солидно. К сожалению, весь документ написан на орочьем языке, прочитать его невозможно.$B$BНадо отнести письмо Бугу, вдруг он что-нибудь придумает!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите не поддающееся чтению письмо орков Бугу "Моднявому" в рудник Ветрорезов в Когтистых горах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Буг берет у вас письмо и принимается его изучать.>$B$BИнтересно.$B$B<Буг нюхает пергамент.>$B$BХм… Это нехорошо…$B$B<Буг складывает пергамент пополам и смотрит на вас.>$B$BНе могу я разобрать, что тут написано – если это вообще можно назвать письмом. Может, это вообще туалетная бумага. Судя по запаху, так оно и есть.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Чего там у тебя?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (25648,'За пределами Дуротара','Хмм... Думаю, твои услуги пригодились бы не только здесь. Аг\'тор Кровопал набирает бойцов для рискованных операций Орды в Азшаре, к северу от Оргриммара.$b$bУверен, у тебя осталось немало работы и здесь, да к тому же понимаю, что в скором времени твоя помощь потребуется в Степях. Я бы на твоем месте не стал заниматься чем-то еще, но если желание прославиться не дает тебе покоя... Азшара ждет.','Свяжитесь с Аг\'тором Кровопалом у задних врат Оргриммара в Азшаре.','Хорошо, что ты прибыл. Добро пожаловать в Азшару, полигон для будущей грандиозной операции Орды. А теперь принимайся за работу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','За пределами Дуротара',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хмм... Думаю, твои услуги пригодились бы не только здесь. Аг\'тор Кровопал набирает бойцов для рискованных операций Орды в Азшаре, к северу от Оргриммара.$b$bУверен, у тебя осталось немало работы и здесь, да к тому же понимаю, что в скором времени твоя помощь потребуется в Степях. Я бы на твоем месте не стал заниматься чем-то еще, но если желание прославиться не дает тебе покоя... Азшара ждет.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Свяжитесь с Аг\'тором Кровопалом у задних врат Оргриммара в Азшаре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо, что ты прибыл. Добро пожаловать в Азшару, полигон для будущей грандиозной операции Орды. А теперь принимайся за работу.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (25649,'Минкс нам все скажет','Нам повезло: Минкс хорошо знает орочий, и она тоже тут. Иди в шахту и найди ее там. Она, поди, забралась куда поглубже, сидит там, пялится по сторонам и ничего не делает.$B$BДа пергамент-то не забудь!','Отнесите не поддающееся чтению письмо орков Минкс в рудник Ветрорезов в Когтистых горах.','<Минкс берет у вас письмо и принимается его читать.>$B$BУгу….$B$B<Минкс нюхает пергамент.>$B$BМерзость какая!$B$B<Минкс складывает пергамент пополам и смотрит на вас.>$B$BМогу тебя порадовать: это не туалетная бумага. Но вот чернила, которыми на ней писали, – это смесь навоза кодо и крови. Хотя это еще не самое худшее.','Чего там у тебя?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Минкс нам все скажет',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нам повезло: Минкс хорошо знает орочий, и она тоже тут. Иди в шахту и найди ее там. Она, поди, забралась куда поглубже, сидит там, пялится по сторонам и ничего не делает.$B$BДа пергамент-то не забудь!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите не поддающееся чтению письмо орков Минкс в рудник Ветрорезов в Когтистых горах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Минкс берет у вас письмо и принимается его читать.>$B$BУгу….$B$B<Минкс нюхает пергамент.>$B$BМерзость какая!$B$B<Минкс складывает пергамент пополам и смотрит на вас.>$B$BМогу тебя порадовать: это не туалетная бумага. Но вот чернила, которыми на ней писали, – это смесь навоза кодо и крови. Хотя это еще не самое худшее.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Чего там у тебя?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (25650,'Приказы верховного командования','В этом письме – приказы верховного командования Орды. Какой-то властитель Кром\'гар приказал выпотрошить шахту и добыть опилки лазурной железной руды. Вроде бы эти опилки получают при переработке руды.$B$BНо это еще не все. Они хотят смешать железные опилки со взрывчаткой, которой начинена большая бомба снаружи, а потом сбросить бомбу на крепость Ветрорезов.$B$BНам нельзя терять ни минуты, $n! Вот перевод письма: возьми его и возвращайся к Бугу. Он придумает, что делать дальше!','Отнесите переведенное письмо орков Бугу "Моднявому" в рудник Ветрорезов в Когтистых горах.','<Буг читает письмо, и его большой лоб покрывается каплями пота.>$B$BЭто плохо. Очень, очень плохо. Тебе надо пойти в крепость Ветрорезов и предупредить лорда Болотную Пахоту.$B$BА это что… Он ЛЕТИТ!!! Гоблинский шар взлетает! Мы опоздали!','Ну? Что там?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приказы верховного командования',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В этом письме – приказы верховного командования Орды. Какой-то властитель Кром\'гар приказал выпотрошить шахту и добыть опилки лазурной железной руды. Вроде бы эти опилки получают при переработке руды.$B$BНо это еще не все. Они хотят смешать железные опилки со взрывчаткой, которой начинена большая бомба снаружи, а потом сбросить бомбу на крепость Ветрорезов.$B$BНам нельзя терять ни минуты, $n! Вот перевод письма: возьми его и возвращайся к Бугу. Он придумает, что делать дальше!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите переведенное письмо орков Бугу "Моднявому" в рудник Ветрорезов в Когтистых горах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Буг читает письмо, и его большой лоб покрывается каплями пота.>$B$BЭто плохо. Очень, очень плохо. Тебе надо пойти в крепость Ветрорезов и предупредить лорда Болотную Пахоту.$B$BА это что… Он ЛЕТИТ!!! Гоблинский шар взлетает! Мы опоздали!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну? Что там?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25651,'Легкая поступь безумия','Я чего думаю...$B$BЕсли кто-то выжил из ума, спятил, слетел с катушек – сам-то он это осознает?$B$BВот тебе наглядный пример: могу поклясться, что я собрал бочонок пороха из пушечных ядер, валяющихся тут кругом, но теперь не могу его найти.$B$BЯ отчетливо помню, как отбирал ядра у жаблинов, что обитают к западу отсюда.$B$BМожет, правду говорят... вдруг я действительно рехнулся...','Соберите на шельфе Гурбоггла 50 ворованных пушечных ядер или отберите их у жаблинов-скопидомов. Насыпьте из ядер полный бочонок пороха.','Поговорите с Баддом у Раскопок Бадда в лесу Келп’тар в Вайш\'ире.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Легкая поступь безумия',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я чего думаю...$B$BЕсли кто-то выжил из ума, спятил, слетел с катушек – сам-то он это осознает?$B$BВот тебе наглядный пример: могу поклясться, что я собрал бочонок пороха из пушечных ядер, валяющихся тут кругом, но теперь не могу его найти.$B$BЯ отчетливо помню, как отбирал ядра у жаблинов, что обитают к западу отсюда.$B$BМожет, правду говорят... вдруг я действительно рехнулся...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите на шельфе Гурбоггла 50 ворованных пушечных ядер или отберите их у жаблинов-скопидомов. Насыпьте из ядер полный бочонок пороха.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Баддом у Раскопок Бадда в лесу Келп’тар в Вайш\'ире.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25652,'Порули воздушным шаром!','Заберитесь в кром\'гарский воздушный шар и попытайтесь остановить его, чтобы он не разрушил крепость Ветрорезов.','Потрясающая история, мужик. В жизни бы не поверил тебе, если бы не видел все собственными глазами. Ты хорошенько так поломал тот шар – они даже решились отступить. Но ты не думай, опасность не миновала. Атаку мы лишь оттянули, но для того чтобы не отдать Когтистые горы Орде, нам надо еще работать и работать!','Обратитесь к лорду Болотной Пахоте в крепости Ветрорезов в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Порули воздушным шаром!',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заберитесь в кром\'гарский воздушный шар и попытайтесь остановить его, чтобы он не разрушил крепость Ветрорезов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Потрясающая история, мужик. В жизни бы не поверил тебе, если бы не видел все собственными глазами. Ты хорошенько так поломал тот шар – они даже решились отступить. Но ты не думай, опасность не миновала. Атаку мы лишь оттянули, но для того чтобы не отдать Когтистые горы Орде, нам надо еще работать и работать!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Обратитесь к лорду Болотной Пахоте в крепости Ветрорезов в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25653,'Древние с нами','Немесис... уничтожен.$B$BЯ чувствую себя вновь молодым.$BСильным.$BБодрым.$B$BПередай Изере, что моя сила находится в ее распоряжении.$B$BСумеречный Молот будет разбит.','Вернитесь к Изере, находящейся у Нордрассила на горе Хиджал.','Вернитесь к Изере, находящейся у Нордрассила на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Древние с нами',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Немесис... уничтожен.$B$BЯ чувствую себя вновь молодым.$BСильным.$BБодрым.$B$BПередай Изере, что моя сила находится в ее распоряжении.$B$BСумеречный Молот будет разбит.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь к Изере, находящейся у Нордрассила на горе Хиджал.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Изере, находящейся у Нордрассила на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (25654,'Темное сердце','Эдана Коготь Ненависти – предводительница гарпий Студеных Ключей, гнездящихся в руинах к западу отсюда. Ведомые ее волей, эти твари оказывают отчаянное сопротивление нашим солдатам.$B$BГарпии призывают ее в бой при помощи особого рога, дуя в него возле камня Когтя Ненависти, на севере этих развалин.$B$BУбей эту мерзкую тварь и принеси мне ее черное сердце.','Убейте Эдану Коготь Ненависти и добудьте Темное сердце Эданы.','Наконец-то эти земли свободны от гарпий. Спасибо тебе огромное.','Мы должны очистить от гарпий бывшие дома наших предков.','Вернитесь к Эрине Дочери Ивы в Покои Дремлющего в Фераласе.','Найди камни Когтя Ненависти, потом протруби в рог. Она появится.','Эдана Коготь Ненависти') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Темное сердце',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эдана Коготь Ненависти – предводительница гарпий Студеных Ключей, гнездящихся в руинах к западу отсюда. Ведомые ее волей, эти твари оказывают отчаянное сопротивление нашим солдатам.$B$BГарпии призывают ее в бой при помощи особого рога, дуя в него возле камня Когтя Ненависти, на севере этих развалин.$B$BУбей эту мерзкую тварь и принеси мне ее черное сердце.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Эдану Коготь Ненависти и добудьте Темное сердце Эданы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Наконец-то эти земли свободны от гарпий. Спасибо тебе огромное.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мы должны очистить от гарпий бывшие дома наших предков.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Эрине Дочери Ивы в Покои Дремлющего в Фераласе.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Найди камни Когтя Ненависти, потом протруби в рог. Она появится.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Эдана Коготь Ненависти',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25655,'Трения с Червивым Крылом','Повелитель небес Омнурон слишком долго смотрел на выходки гарпий из стаи Червивого Крыла сквозь пальцы, позволяя им гнездиться на этой горе. Они ведь тоже летающие создания. И все же, |3-6($c), не все летающие создания равны между собой.$B$BКогда начались нападения на Хиджал, стая Червивого Крыла словно сошла с ума. Сейчас они здесь, атакуют святилище, которое некогда почитали.$B$BНо я не беспокоюсь. У нас появилась причина изгнать их с Хиджала, не так ли?','Убейте 10 гарпий из стаи Червивого Крыла (крикуний либо стремительных когтей).','<Тизали кивает головой в знак согласия, а ее глаза начинают блестеть.>$B$BПорой приятно дать себе волю, не так ли?','Вернитесь к Тизали Вороне в Святилище Авианы на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Трения с Червивым Крылом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Повелитель небес Омнурон слишком долго смотрел на выходки гарпий из стаи Червивого Крыла сквозь пальцы, позволяя им гнездиться на этой горе. Они ведь тоже летающие создания. И все же, |3-6($c), не все летающие создания равны между собой.$B$BКогда начались нападения на Хиджал, стая Червивого Крыла словно сошла с ума. Сейчас они здесь, атакуют святилище, которое некогда почитали.$B$BНо я не беспокоюсь. У нас появилась причина изгнать их с Хиджала, не так ли?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 гарпий из стаи Червивого Крыла (крикуний либо стремительных когтей).',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Тизали кивает головой в знак согласия, а ее глаза начинают блестеть.>$B$BПорой приятно дать себе волю, не так ли?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тизали Вороне в Святилище Авианы на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25656,'Борьба за яйца','В нападениях стаи Червивого Крыла есть логика. Пока некоторые отряды гарпий для виду нападают на святилище, остальные забираются в близлежащие гнезда и воруют яйца всех пернатых созданий, живущих на Хиджале.$B$BЭти существа находятся под нашей защитой. Мы выясним, каковы истинные цели стаи Червивого крыла, но сначала нужно спасти как можно больше яиц от их когтей.','Соберите 8 хиджальских яиц.','Неплохо для начала.$B$BОднако птицы, отложившие эти яйца, никогда не примут их обратно. Так что нам придется вырастить осиротевших птенцов в святилище. Если бы Авиана была тут, она никогда не допустила бы столь противоестественного хода событий.$B$BА теперь о деле...','<Тизали чистит свои ногти кинжалом. Она выжидающе смотрит на вас.>','Принеси яйца Тизали Вороне в святилище Авианы на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Борьба за яйца',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В нападениях стаи Червивого Крыла есть логика. Пока некоторые отряды гарпий для виду нападают на святилище, остальные забираются в близлежащие гнезда и воруют яйца всех пернатых созданий, живущих на Хиджале.$B$BЭти существа находятся под нашей защитой. Мы выясним, каковы истинные цели стаи Червивого крыла, но сначала нужно спасти как можно больше яиц от их когтей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 хиджальских яиц.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Неплохо для начала.$B$BОднако птицы, отложившие эти яйца, никогда не примут их обратно. Так что нам придется вырастить осиротевших птенцов в святилище. Если бы Авиана была тут, она никогда не допустила бы столь противоестественного хода событий.$B$BА теперь о деле...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Тизали чистит свои ногти кинжалом. Она выжидающе смотрит на вас.>',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принеси яйца Тизали Вороне в святилище Авианы на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (25657,'Сундук Костеглода','Раз уж ты ради меня так стараешься, пожалуй, открою тебе один секрет.$B$BЯ нашел самую большую на свете блестяшку – всего в 50 шагах от того места, где мы сейчас стоим! Правда есть некоторое препятствие, отделяющее нас с тобой от большого куша... это Костеглод.$B$BНо ты не дрейфь – у меня созрел план.$B$BКостеглод прожорлив, так что я нашпигую наживку порохом, и у нас получится своего рода ловушка, сечешь?$B$BОстанется только оставить ее плавать поблизости. Как только с акулой будет покончено, мы разбогатеем!','Бадд хочет, чтобы вы выстрелили минированной приманкой из ржавого гарпунного ружья на Проклятом рифе.','Поговорите с Баддом у Раскопок Бадда в лесу Келп’тар.','Эти воды отнюдь не безопасны!','Костеглод') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сундук Костеглода',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Раз уж ты ради меня так стараешься, пожалуй, открою тебе один секрет.$B$BЯ нашел самую большую на свете блестяшку – всего в 50 шагах от того места, где мы сейчас стоим! Правда есть некоторое препятствие, отделяющее нас с тобой от большого куша... это Костеглод.$B$BНо ты не дрейфь – у меня созрел план.$B$BКостеглод прожорлив, так что я нашпигую наживку порохом, и у нас получится своего рода ловушка, сечешь?$B$BОстанется только оставить ее плавать поблизости. Как только с акулой будет покончено, мы разбогатеем!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Бадд хочет, чтобы вы выстрелили минированной приманкой из ржавого гарпунного ружья на Проклятом рифе.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Баддом у Раскопок Бадда в лесу Келп’тар.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Эти воды отнюдь не безопасны!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Костеглод',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (25657,'Amazing!$B$BYou watch the great white beast swim off into the depths and wonder to yourself if anything could ever take him down...') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Amazing!$B$BYou watch the great white beast swim off into the depths and wonder to yourself if anything could ever take him down...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25658,'На века','Моя госпожа, верховная жрица поручила мне передать тебе ее просьбу. Многие защитные сооружения города остались еще с тех времен, когда он был на поверхности. И мы бы с легкостью вернули их в строй, если бы не квалдиры.$B$BНам известно, что скоро ты отправишься в бой на Террасу Нар\'шолы, что находится над нами. Ты очень помогла бы моей госпоже, если бы всего лишь дотронулась до нескольких расположенных там устройств. Думаю, твоя благородная кровь – достаточное условие, чтобы привести их в действие.','Приведите в действие 6 щитов Нар\'шолы.$B$BЭто задание из цикла "Видения воительницы Леди Наз\'жар". Чтобы вернуться к видению, в нужном месте воспользуйтесь клинком воительницы Леди Наз\'жар.','Щиты Нар\'шолы приведены в действие. Я немедленно доложу о твоих успехах Повелительнице приливов.$B$BБлагодарю тебя за помощь, моя госпожа.','Поговорите с жрицей прилива Сира\'кесс в южной части террасы Нар\'шолы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На века',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Моя госпожа, верховная жрица поручила мне передать тебе ее просьбу. Многие защитные сооружения города остались еще с тех времен, когда он был на поверхности. И мы бы с легкостью вернули их в строй, если бы не квалдиры.$B$BНам известно, что скоро ты отправишься в бой на Террасу Нар\'шолы, что находится над нами. Ты очень помогла бы моей госпоже, если бы всего лишь дотронулась до нескольких расположенных там устройств. Думаю, твоя благородная кровь – достаточное условие, чтобы привести их в действие.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Приведите в действие 6 щитов Нар\'шолы.$B$BЭто задание из цикла "Видения воительницы Леди Наз\'жар". Чтобы вернуться к видению, в нужном месте воспользуйтесь клинком воительницы Леди Наз\'жар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Щиты Нар\'шолы приведены в действие. Я немедленно доложу о твоих успехах Повелительнице приливов.$B$BБлагодарю тебя за помощь, моя госпожа.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с жрицей прилива Сира\'кесс в южной части террасы Нар\'шолы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (25659,'Такое не забывается','Предводитель квалдиров показал свою мерзкую физиономию совсем рядом – чуть дальше по этому коридору на западе от нас. Если убьем его сейчас, наш некогда любимый город будет наконец освобожден от захватчиков.$B$BНо будь осторожна, Воительница, он отнюдь не слабак, и у него хватает войск. Мы отправим с тобой нескольких морских ведьм Сира\'кесс, которые попробуют измотать предводителя квалдиров во время твоей атаки, но им придется отвлечься, если на них нападут его приспешники.$B$BВперед, воительница!','Убейте Варкула Безжалостного.$B$BЭто задание из цикла "Видения воительницы Леди Наз\'жары". Чтобы вернуться к видению, в нужном месте воспользуйтесь клинком воительницы Леди Наз\'жар.','Вернитесь к Повелителю глубин Зин\'жатару в южную часть террасы Нар\'шолы.','Предводитель квалдиров в Вайш\'ире Варкул известен своей гордостью и бесстрашием.','Варкул Безжалостный') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Такое не забывается',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Предводитель квалдиров показал свою мерзкую физиономию совсем рядом – чуть дальше по этому коридору на западе от нас. Если убьем его сейчас, наш некогда любимый город будет наконец освобожден от захватчиков.$B$BНо будь осторожна, Воительница, он отнюдь не слабак, и у него хватает войск. Мы отправим с тобой нескольких морских ведьм Сира\'кесс, которые попробуют измотать предводителя квалдиров во время твоей атаки, но им придется отвлечься, если на них нападут его приспешники.$B$BВперед, воительница!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Варкула Безжалостного.$B$BЭто задание из цикла "Видения воительницы Леди Наз\'жары". Чтобы вернуться к видению, в нужном месте воспользуйтесь клинком воительницы Леди Наз\'жар.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Повелителю глубин Зин\'жатару в южную часть террасы Нар\'шолы.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Предводитель квалдиров в Вайш\'ире Варкул известен своей гордостью и бесстрашием.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Варкул Безжалостный',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (25660,'Неупокоенный','Думаешь, я так просто спущу тебе с рук, что ты $gвзял:взяла; и $gубил:убила; меня, $gдруг:подружка;? Ну уж нет! Не для того я создавал пиратскую империю, чтобы ты $gпришел:пришла; и меня не стало.$B$BПоможешь мне воскреснуть. Найди мою бывшую жену Аджамон в северной части Крепи. Иди на запах: где ее вонючий котел – там и она.','Чаво изволишь? Ох нет, шиш. Гляжу, ты притащил с собой дух Тони, а я с ним дел иметь не желаю!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Неупокоенный',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Думаешь, я так просто спущу тебе с рук, что ты $gвзял:взяла; и $gубил:убила; меня, $gдруг:подружка;? Ну уж нет! Не для того я создавал пиратскую империю, чтобы ты $gпришел:пришла; и меня не стало.$B$BПоможешь мне воскреснуть. Найди мою бывшую жену Аджамон в северной части Крепи. Иди на запах: где ее вонючий котел – там и она.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Чаво изволишь? Ох нет, шиш. Гляжу, ты притащил с собой дух Тони, а я с ним дел иметь не желаю!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25662,'Освободить наших сестер','Вчера команде охотниц было выдано задание отправиться на утес Ветрорезов и собрать там информацию о действиях Орды в Когтистых горах. Но разведка сообщила мне, что всех охотниц, включая их командира, Иллиону, захватили в плен.$B$BСтупай на восток, на утес Ветрорезов, убей там всех кром\'гарских пехотинцев, забери у них ключи от клеток и выпусти наших сестер на свободу.$B$BКогда освободишь охотниц, попытайся найти охотницу Иллиону.','Добудьте 5 ключей от клетки Орды и освободите 5 пленных охотниц.','Времени мало. Чтобы выпустить меня отсюда, тебе придется убить полководца Роктрога. Ключ от замка у него.','Найдите охотницу Иллиону на утесе Ветрорезов в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Освободить наших сестер',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вчера команде охотниц было выдано задание отправиться на утес Ветрорезов и собрать там информацию о действиях Орды в Когтистых горах. Но разведка сообщила мне, что всех охотниц, включая их командира, Иллиону, захватили в плен.$B$BСтупай на восток, на утес Ветрорезов, убей там всех кром\'гарских пехотинцев, забери у них ключи от клеток и выпусти наших сестер на свободу.$B$BКогда освободишь охотниц, попытайся найти охотницу Иллиону.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 5 ключей от клетки Орды и освободите 5 пленных охотниц.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Времени мало. Чтобы выпустить меня отсюда, тебе придется убить полководца Роктрога. Ключ от замка у него.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Найдите охотницу Иллиону на утесе Ветрорезов в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25663,'Подношение для Авианы','Несмотря на то, что покровительница всех пернатых созданий физически больше не с нами, я порой слышу ее голос в шелестящей листве.$B$BМы многого требуем от тебя, $n, так как ты $gзадался:задалась; целью спасти Хиджал. Посиди немного перед тем, как отправляться в путь.$B$BОтнеси этот дарственный нектар на Погребальный круг Авианы – круг из камней, выложенный за главным входом в святилище. Возможно, ты обретешь большую ясность ума, побыв наедине с духом Авианы.','Используйте священный нектар на Погребальном круге Авианы.','<Чей-то голос нашептывает просьбу в вашем сознании.>$B$BНовое перерождение во тьме...$B$BМеня похитили.$B$B<Внезапно беспокойный дух замолкает и растворяется в пространстве.>','<Дух то появляется, то исчезает из вида, словно балансируя на стыке двух миров.>','Поговорите с таинственным крылатым духом у Святилища Авианы на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подношение для Авианы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Несмотря на то, что покровительница всех пернатых созданий физически больше не с нами, я порой слышу ее голос в шелестящей листве.$B$BМы многого требуем от тебя, $n, так как ты $gзадался:задалась; целью спасти Хиджал. Посиди немного перед тем, как отправляться в путь.$B$BОтнеси этот дарственный нектар на Погребальный круг Авианы – круг из камней, выложенный за главным входом в святилище. Возможно, ты обретешь большую ясность ума, побыв наедине с духом Авианы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте священный нектар на Погребальном круге Авианы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Чей-то голос нашептывает просьбу в вашем сознании.>$B$BНовое перерождение во тьме...$B$BМеня похитили.$B$B<Внезапно беспокойный дух замолкает и растворяется в пространстве.>',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Дух то появляется, то исчезает из вида, словно балансируя на стыке двух миров.>',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с таинственным крылатым духом у Святилища Авианы на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (25664,'На честном слове и на одном крыле','Крылатое видение? Возможно ли это?..$B$B$n, нам нельзя терять время. Возможно, на пути к нам тебе довелось пообщаться с самой Авианой.$B$BМне нужна какая-нибудь вещь из прошлого Авианы, чтобы дотянуться до нее. Поднимись на горный хребет над этим святилищем. Ты найдешь там гнезда Блейта, древнего пернатого хищника – соправителя Авианы. Десять тысяч лет он упивается своим горем.$B$BДоберись до одного из его гнезд и используй этот манок, чтобы вызвать его. Убей Блейта и принеси мне одно из его перьев.','Используйте манок огромной птицы у одного из гнезд Блейта на Краю света. Убейте Блейта и заберите одно из древних перьев.','Не стоит жалеть Блейта. Горе давно выжгло его изнутри, и теперь он – лишь тень своего былого могущества, пусть и довольно опасная тень.','Отнесите древнее перо Чолуне в Святилище Авианы на горе Хиджал.','Используйте манок огромной птицы, чтобы призвать Блейта.','Блейт') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На честном слове и на одном крыле',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Крылатое видение? Возможно ли это?..$B$B$n, нам нельзя терять время. Возможно, на пути к нам тебе довелось пообщаться с самой Авианой.$B$BМне нужна какая-нибудь вещь из прошлого Авианы, чтобы дотянуться до нее. Поднимись на горный хребет над этим святилищем. Ты найдешь там гнезда Блейта, древнего пернатого хищника – соправителя Авианы. Десять тысяч лет он упивается своим горем.$B$BДоберись до одного из его гнезд и используй этот манок, чтобы вызвать его. Убей Блейта и принеси мне одно из его перьев.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте манок огромной птицы у одного из гнезд Блейта на Краю света. Убейте Блейта и заберите одно из древних перьев.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Не стоит жалеть Блейта. Горе давно выжгло его изнутри, и теперь он – лишь тень своего былого могущества, пусть и довольно опасная тень.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите древнее перо Чолуне в Святилище Авианы на горе Хиджал.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Используйте манок огромной птицы, чтобы призвать Блейта.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Блейт',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25665,'Потусторонний зов','<Вы не можете разобрать ни слова из речи духа, но, возможно, Чолуне удастся расшифровать ее.>$B$B<Вернитесь в святилище и поговорите с Чолуной!>','Вернитесь к Чолуне в святилище Авианы на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Потусторонний зов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Вы не можете разобрать ни слова из речи духа, но, возможно, Чолуне удастся расшифровать ее.>$B$B<Вернитесь в святилище и поговорите с Чолуной!>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь к Чолуне в святилище Авианы на горе Хиджал.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25666,'Грязная работенка','На этот раз не облажайся, |3-6($r), акула башковитая. Ты, в отличие от нее, долго тут не протянешь, если не проявишь смекалку.$B$BЯ хочу сказать, что больше его так просто не одурачить. Нам придется немного изменить подход.$B$BНе хочу пока утомлять тебя деталями. Сперва достань мне внутренности морских червей.$B$BКак думаешь, справишься?','Раздобудьте 5 грязных внутренностей морских червей, охотясь на гигантских морских червей возле Раскопок Харрисона.','Поговорите с Харрисоном на Раскопках Харрисона.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Грязная работенка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На этот раз не облажайся, |3-6($r), акула башковитая. Ты, в отличие от нее, долго тут не протянешь, если не проявишь смекалку.$B$BЯ хочу сказать, что больше его так просто не одурачить. Нам придется немного изменить подход.$B$BНе хочу пока утомлять тебя деталями. Сперва достань мне внутренности морских червей.$B$BКак думаешь, справишься?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте 5 грязных внутренностей морских червей, охотясь на гигантских морских червей возле Раскопок Харрисона.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Харрисоном на Раскопках Харрисона.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25667,'Истребление вендиго','Вендиго из Серой берлоги, что к юго-западу отсюда, долгое время были нашей проблемой. Они недостаточно сильны, чтобы причинить вред Караносу напрямую, но они нападают на путников, на патрули горных пехотинцев и на караваны с припасами.$b$bЯ собираюсь забрать из Серой берлоги своих наблюдателей, потому что они нужнее для борьбы с троллями. Не поможешь ли ты моим людям завершить искоренение популяции вендиго? Когда их численность уменьшится, они не смогут атаковать нас.','Убейте 10 вендиго в Серой берлоге. Молодые вендиго тоже считаются.','Теперь, когда ты закончил с вендиго, мы сможем сосредоточить свои усилия на троллях из племени Мерзлогривов к востоку отсюда.','Вернитесь к капитану Таррану в Каранос.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Истребление вендиго',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вендиго из Серой берлоги, что к юго-западу отсюда, долгое время были нашей проблемой. Они недостаточно сильны, чтобы причинить вред Караносу напрямую, но они нападают на путников, на патрули горных пехотинцев и на караваны с припасами.$b$bЯ собираюсь забрать из Серой берлоги своих наблюдателей, потому что они нужнее для борьбы с троллями. Не поможешь ли ты моим людям завершить искоренение популяции вендиго? Когда их численность уменьшится, они не смогут атаковать нас.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 вендиго в Серой берлоге. Молодые вендиго тоже считаются.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь, когда ты закончил с вендиго, мы сможем сосредоточить свои усилия на троллях из племени Мерзлогривов к востоку отсюда.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Таррану в Каранос.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25668,'Украденные припасы','Мерзлогривы угрожают нам с востока. Вендиго почувствовали нашу слабость, и их налеты становятся все более дерзкими. Из последних четырех телег с припасами только одной удалось добраться до места назначения. Остальные захватили вендиго и утащили их в Серую берлогу, так называется пещера к юго-западу от города. Если ты отправишься туда и вернешь нам украденные припасы, все горожане и все горные пехотинцы, защищающие Каранос, будут благодарны тебе.','Найдите 6 украденных ящиков с припасами в Серой берлоге.','Удалось найти наши пропавшие припасы?','Вернитесь к интенданту Глинне в Каранос.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Украденные припасы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мерзлогривы угрожают нам с востока. Вендиго почувствовали нашу слабость, и их налеты становятся все более дерзкими. Из последних четырех телег с припасами только одной удалось добраться до места назначения. Остальные захватили вендиго и утащили их в Серую берлогу, так называется пещера к юго-западу от города. Если ты отправишься туда и вернешь нам украденные припасы, все горожане и все горные пехотинцы, защищающие Каранос, будут благодарны тебе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите 6 украденных ящиков с припасами в Серой берлоге.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось найти наши пропавшие припасы?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к интенданту Глинне в Каранос.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25669,'Неспокойная лесопилка','Убейте полководца Роктрога, возьмите ключ от клетки охотницы Иллионы и освободите ее.','Обратитесь к лорду Болотной Пахоте в крепости Ветрорезов в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Неспокойная лесопилка',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте полководца Роктрога, возьмите ключ от клетки охотницы Иллионы и освободите ее.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Обратитесь к лорду Болотной Пахоте в крепости Ветрорезов в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (25670,'Гм-гм','Будь у Костеглода ноги, вот бы он нам сейчас пинков надавал...$B$BПо счастью, я мыслю, как акула.$B$BКостеглод зол, как тысяча чертей, и это нам на руку.$B$BГляди, в поисках сокровищ я наткнулся на эту цепь. Прикрепи ее к гарпунному ружью.$B$BКостеглод будет вне себя от ярости, когда тебя увидит, – вот тогда мы и примемся за дело!$B$BТы попробуешь его прикончить, а я подкрадусь и стащу блестяшку.$B$BПоторопись, покуда у него снова зубы не отросли!','Прикрепите цепь Бадда к ржавому гарпунному ружью на Проклятом рифе. Выстрелите, когда Костеглод окажется в зоне поражения.','На деле все не так уж и плохо...','Поговорите с Баддом на Рифе Скелетов в лесу Келп’тар.','Да, в этих водах немного безопаснее, но разве что самую малость...','Костеглод') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гм-гм',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Будь у Костеглода ноги, вот бы он нам сейчас пинков надавал...$B$BПо счастью, я мыслю, как акула.$B$BКостеглод зол, как тысяча чертей, и это нам на руку.$B$BГляди, в поисках сокровищ я наткнулся на эту цепь. Прикрепи ее к гарпунному ружью.$B$BКостеглод будет вне себя от ярости, когда тебя увидит, – вот тогда мы и примемся за дело!$B$BТы попробуешь его прикончить, а я подкрадусь и стащу блестяшку.$B$BПоторопись, покуда у него снова зубы не отросли!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Прикрепите цепь Бадда к ржавому гарпунному ружью на Проклятом рифе. Выстрелите, когда Костеглод окажется в зоне поражения.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','На деле все не так уж и плохо...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Баддом на Рифе Скелетов в лесу Келп’тар.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Да, в этих водах немного безопаснее, но разве что самую малость...',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Костеглод',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25671,'Проредить Орду','Ордынская армия все растет, потому что из Ясеневого леса и Азшары к ним подходят подкрепления. Никаких переговоров с этими животными вести нельзя. Это Орда Адского Крика, и она очень хочет нашей крови! Мы не станем просто сидеть и смотреть, как они захватывают наши земли и убивают людей. Нужно что-то делать!$B$BНужно проредить эту Орду! Так что считай это своим ежедневным долгом.$B$BОтправляйся в Когтистые горы и убей там столько ордынцев, сколько сумеешь. Пусть знают, что Альянс не сдается!','Убейте 20 любых ордынских солдат в Когтистых горах.','Вернитесь к лорду Болотной Пахоте в крепость Ветрорезов в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Проредить Орду',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ордынская армия все растет, потому что из Ясеневого леса и Азшары к ним подходят подкрепления. Никаких переговоров с этими животными вести нельзя. Это Орда Адского Крика, и она очень хочет нашей крови! Мы не станем просто сидеть и смотреть, как они захватывают наши земли и убивают людей. Нужно что-то делать!$B$BНужно проредить эту Орду! Так что считай это своим ежедневным долгом.$B$BОтправляйся в Когтистые горы и убей там столько ордынцев, сколько сумеешь. Пусть знают, что Альянс не сдается!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 20 любых ордынских солдат в Когтистых горах.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лорду Болотной Пахоте в крепость Ветрорезов в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25672,'Анатомический театр','Эти внутренности сгодятся для начала, $gдруг:подруга;, но нам еще нужно раздобыть кучу прочих штук. По идее, хорошо бы сейчас что-нибудь от членов семьи, но это ж только я и сынок моей сестры, а Тони ни шиша не стоит таких жертв!$B$BТак что придется подыскать замену. Куча трупов подойдет!$B$BВ Мерцающих глубинах их вдосталь. Когда хлынула вода, погибли сотни тварей. Принеси-ка мне их останки.','Соберите 10 трупов животных.','Фу, мерзость какая!$B$BПочти закончили, паря. Осталась всего одна безделица!','Ты должен принести мне целую кучу останков, друг! Иначе нам от этого призрака не отделаться!','Вернитесь к Аджамон Призывательнице Духов в Укрепление Южных морей в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Анатомический театр',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти внутренности сгодятся для начала, $gдруг:подруга;, но нам еще нужно раздобыть кучу прочих штук. По идее, хорошо бы сейчас что-нибудь от членов семьи, но это ж только я и сынок моей сестры, а Тони ни шиша не стоит таких жертв!$B$BТак что придется подыскать замену. Куча трупов подойдет!$B$BВ Мерцающих глубинах их вдосталь. Когда хлынула вода, погибли сотни тварей. Принеси-ка мне их останки.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 трупов животных.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Фу, мерзость какая!$B$BПочти закончили, паря. Осталась всего одна безделица!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты должен принести мне целую кучу останков, друг! Иначе нам от этого призрака не отделаться!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аджамон Призывательнице Духов в Укрепление Южных морей в Тысяче Игл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25673,'Просто попроси Алису','Господин П. болен, $gсударь:сударыня;. Вы ему поможете? Надо всего лишь найти его шляпу и батарейки, и ему сразу полегчает. Я бы и сама их нашла, но я не могу оставить господина П. одного!$B$BЕго шляпу украли жадюги из Торговой компании – вон там, у водяного колеса, а батарейки спрятаны где-то возле Утеса Ветрорезов. Вы просто поищите их как следует!$B$BПожалуйста, принесите эти штучки господина П., чтобы он преподал плохим ребятам из Орды урок?','Найдите машину войны БА-64, Механизированный огонь, Механизированный лед и Механизированный воздух.','<Алиса радостно хлопает в ладоши.>$B$BГосподин П., ты поправишься! Ура-а-а-а!$B$B<Алиса умело вставляет все принесенные вами детали в Большого папулю.>$B$BАх, господин П.! Я знала, знала!','Господин П. такой грустный. Надо развеселить его!','Вернитесь к Алисе в крепость Ветрорезов, что в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Просто попроси Алису',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Господин П. болен, $gсударь:сударыня;. Вы ему поможете? Надо всего лишь найти его шляпу и батарейки, и ему сразу полегчает. Я бы и сама их нашла, но я не могу оставить господина П. одного!$B$BЕго шляпу украли жадюги из Торговой компании – вон там, у водяного колеса, а батарейки спрятаны где-то возле Утеса Ветрорезов. Вы просто поищите их как следует!$B$BПожалуйста, принесите эти штучки господина П., чтобы он преподал плохим ребятам из Орды урок?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите машину войны БА-64, Механизированный огонь, Механизированный лед и Механизированный воздух.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Алиса радостно хлопает в ладоши.>$B$BГосподин П., ты поправишься! Ура-а-а-а!$B$B<Алиса умело вставляет все принесенные вами детали в Большого папулю.>$B$BАх, господин П.! Я знала, знала!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Господин П. такой грустный. Надо развеселить его!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Алисе в крепость Ветрорезов, что в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (25674,'Безосновательная гордость','Это старый орочий город, один из старейших в Азероте. Точнее, он был таким, пока нас не вышвырнули оттуда огры.$B$BНо сегодня Орда не станет терпеть притеснения каких-то там огров. Мои войска отбили город силой, а огры, которые раньше жили здесь, теперь прислуживают нам. Вот теперь-то и начинается настоящая работа.$B$BС виду ты достаточно $gсилен:сильна;, но мне хотелось бы увидеть тебя в деле. Некоторые огры до сих пор осаждают нас – иди, убей одного из них, а потом возвращайся ко мне.','Вернитесь к Окрилле в Форт Молота Ужаса, что в Выжженных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Безосновательная гордость',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это старый орочий город, один из старейших в Азероте. Точнее, он был таким, пока нас не вышвырнули оттуда огры.$B$BНо сегодня Орда не станет терпеть притеснения каких-то там огров. Мои войска отбили город силой, а огры, которые раньше жили здесь, теперь прислуживают нам. Вот теперь-то и начинается настоящая работа.$B$BС виду ты достаточно $gсилен:сильна;, но мне хотелось бы увидеть тебя в деле. Некоторые огры до сих пор осаждают нас – иди, убей одного из них, а потом возвращайся ко мне.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Окрилле в Форт Молота Ужаса, что в Выжженных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25675,'Бой с ограми','Убейте 6 извергов и 5 чернокнижников из клана Молота Ужаса.','Вернитесь к магистру Айтокку в Форт Молота Ужаса, что в Выжженных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бой с ограми',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 6 извергов и 5 чернокнижников из клана Молота Ужаса.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к магистру Айтокку в Форт Молота Ужаса, что в Выжженных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (25676,'Удар по карману','Наконец-то прислали еще кого-то. Что ж, я надеюсь, что ты успел хорошенько размяться по дороге, потому что сейчас нам придется как следует потанцевать!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Удар по карману',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Наконец-то прислали еще кого-то. Что ж, я надеюсь, что ты успел хорошенько размяться по дороге, потому что сейчас нам придется как следует потанцевать!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25677,'Ни нашим ни вашим!','Здесь по всей пещере лежат груды руды: только и ждут, чтобы с ними что-нибудь сделали. Конечно, лучше всего было бы руду украсть, но для этого нужны тележки, рабочие и охрана, а ничего этого у нас нет. Поэтому мы устроим в шахте диверсию при помощи чрезвычайно едкого растворителя.$B$BВот, на тебе бутылку, да ПООСТОРОЖНЕЕ с ней! Вылей растворитель на руду – раз ее нам не заполучить, пусть и им тоже не достанется!','Ну, как вам такой хор-р-рошенький удар по казне, а, болваны альянсовские?!','Вернитесь к Рофилию Дейну в Рудники Гарнизона, что в Выжженных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ни нашим ни вашим!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Здесь по всей пещере лежат груды руды: только и ждут, чтобы с ними что-нибудь сделали. Конечно, лучше всего было бы руду украсть, но для этого нужны тележки, рабочие и охрана, а ничего этого у нас нет. Поэтому мы устроим в шахте диверсию при помощи чрезвычайно едкого растворителя.$B$BВот, на тебе бутылку, да ПООСТОРОЖНЕЕ с ней! Вылей растворитель на руду – раз ее нам не заполучить, пусть и им тоже не достанется!',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну, как вам такой хор-р-рошенький удар по казне, а, болваны альянсовские?!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Рофилию Дейну в Рудники Гарнизона, что в Выжженных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25678,'Выбери свою судьбу','Обучение рудокопа обходится Альянсу примерно в 50 золотых, обучение инженера – в 200, а обучение штейгера – в 300 золотых. Так что каждый убитый член Альянса – это не только военная, но и финансовая победа.$B$BДавай, иди туда и убей их работников!','Отлично, друг мой. Вот так и надо вести дела!','Вернитесь к Рофилию Дейну в Рудники Гарнизона, что в Выжженных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Выбери свою судьбу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Обучение рудокопа обходится Альянсу примерно в 50 золотых, обучение инженера – в 200, а обучение штейгера – в 300 золотых. Так что каждый убитый член Альянса – это не только военная, но и финансовая победа.$B$BДавай, иди туда и убей их работников!',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, друг мой. Вот так и надо вести дела!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Рофилию Дейну в Рудники Гарнизона, что в Выжженных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (25679,'В гору!','Следующую фазу операции надо проводить в глубине шахты. Насчет этого поговори с Так\'арили. Просто иди по рельсам на юго-восток и сверни, где они сворачивают. Увидишь его около входа в верхнюю часть шахты.$B$BПриятно было иметь с тобой дело, $n.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В гору!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Следующую фазу операции надо проводить в глубине шахты. Насчет этого поговори с Так\'арили. Просто иди по рельсам на юго-восток и сверни, где они сворачивают. Увидишь его около входа в верхнюю часть шахты.$B$BПриятно было иметь с тобой дело, $n.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25680,'Это не мы!','Начнем сначала... У нас, похоже, проблемы. Эти рудокопы, что работают чуть ниже по дороге, справа – они вдруг все забегали как ошпаренные. Я думаю, они копнули слишком глубоко и наткнулись на что-то страшное... Демона какого или элементаля, или еще какую мерзость с щупальцами.$B$BТак\'арили сюрпризов не любит, так что иди, выясни, что у них там случилось, и утряси все. Тогда мы сможем вернуться к работе.','Так это демон был? Эти рудокопы демонов, что ли, не видели? Мы же как-никак в Выжженных землях! Тут куда ни плюнь, в демона попадешь!$B$B<Так\'арили вздыхает.>$B$BТьфу на них… Давай уже займемся делом, что ли?','Вернитесь к Так\'арили в Рудники Гарнизона, что в Выжженных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Это не мы!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Начнем сначала... У нас, похоже, проблемы. Эти рудокопы, что работают чуть ниже по дороге, справа – они вдруг все забегали как ошпаренные. Я думаю, они копнули слишком глубоко и наткнулись на что-то страшное... Демона какого или элементаля, или еще какую мерзость с щупальцами.$B$BТак\'арили сюрпризов не любит, так что иди, выясни, что у них там случилось, и утряси все. Тогда мы сможем вернуться к работе.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так это демон был? Эти рудокопы демонов, что ли, не видели? Мы же как-никак в Выжженных землях! Тут куда ни плюнь, в демона попадешь!$B$B<Так\'арили вздыхает.>$B$BТьфу на них… Давай уже займемся делом, что ли?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Так\'арили в Рудники Гарнизона, что в Выжженных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (25681,'Кое-кого просто нельзя не убить','По этому туннелю впереди, что ведет на запад, ты придешь прямиком к рабочему месту главного геолога Хондо. Он тут вроде как большая шишка, и Так\'арили слышал, что он обалдеть какой рудокоп. Поэтому надо его убить.$B$BЕсть только одна проблема: путь впереди просто под завязку набит этими мерзкими работничками, так что тебе придется замаскироваться. Залезай вот в эту коробку и пробирайся по туннелю. Надеюсь, лишнего внимания ты к себе не привлечешь.','Убейте главного геолога Хондо. Чтобы пробраться к нему, используйте неприметную коробку.','Молодчина! Без Хондо от этого сброда не будет никакого толку. Скоро эта шахта будет наша!','Вернитесь к Так\'арили на Рудники Гарнизона, что в Выжженных землях.','Хондо часто обижали в детстве из-за маленького роста.','Главный геолог Хондо') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кое-кого просто нельзя не убить',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','По этому туннелю впереди, что ведет на запад, ты придешь прямиком к рабочему месту главного геолога Хондо. Он тут вроде как большая шишка, и Так\'арили слышал, что он обалдеть какой рудокоп. Поэтому надо его убить.$B$BЕсть только одна проблема: путь впереди просто под завязку набит этими мерзкими работничками, так что тебе придется замаскироваться. Залезай вот в эту коробку и пробирайся по туннелю. Надеюсь, лишнего внимания ты к себе не привлечешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте главного геолога Хондо. Чтобы пробраться к нему, используйте неприметную коробку.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Молодчина! Без Хондо от этого сброда не будет никакого толку. Скоро эта шахта будет наша!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Так\'арили на Рудники Гарнизона, что в Выжженных землях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Хондо часто обижали в детстве из-за маленького роста.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Главный геолог Хондо',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (25682,'Задание выполнено','Здесь все, $gприятель:подруга;. Осталось только Окрилле доложить. Ты сейчас не сильно $gзанят:занята;?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Задание выполнено',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Здесь все, $gприятель:подруга;. Осталось только Окрилле доложить. Ты сейчас не сильно $gзанят:занята;?',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (25683,'Горн Молота Ужаса','Я свое слово сдержу, $n. Ты мне $gпомог:помогла;, и теперь я расскажу тебе то, что знаю.$B$BЭтот охотник на демонов, которого ты ищешь, был здесь, но очень недолго. Он все говорил про демонов, а потом отправился на юг. Обычно я убиваю ночных эльфов не раздумывая, но тот вроде бы не был на стороне Альянса, да и истребление демонов мне только на руку.$B$BТы лучше поговори с Линорой и Дразиалом: это два волшебника крови, я отправила их вперед, вон туда. Они обосновались в глубине огрской пещеры.','Поговорите с волшебницей крови Линорой в Горне Молота Ужаса в Выжженных землях.','Тебя прислала Окрилла? Окрилла-громила?$B$B<Линора выслушивает ваш рассказ.>$B$BИ звали его Лорам? Ты прости, конечно, но твоего охотника на демонов мы не встречали… Зато мы знаем, как его можно найти.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Горн Молота Ужаса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я свое слово сдержу, $n. Ты мне $gпомог:помогла;, и теперь я расскажу тебе то, что знаю.$B$BЭтот охотник на демонов, которого ты ищешь, был здесь, но очень недолго. Он все говорил про демонов, а потом отправился на юг. Обычно я убиваю ночных эльфов не раздумывая, но тот вроде бы не был на стороне Альянса, да и истребление демонов мне только на руку.$B$BТы лучше поговори с Линорой и Дразиалом: это два волшебника крови, я отправила их вперед, вон туда. Они обосновались в глубине огрской пещеры.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с волшебницей крови Линорой в Горне Молота Ужаса в Выжженных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебя прислала Окрилла? Окрилла-громила?$B$B<Линора выслушивает ваш рассказ.>$B$BИ звали его Лорам? Ты прости, конечно, но твоего охотника на демонов мы не встречали… Зато мы знаем, как его можно найти.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25684,'Настроиться на кровавый камень','Надо признаться, мы выбрали не самое удобное место для своих исследований. И особенно неподходящее – для любопытных искателей приключений, которые предпочли бы заходить сюда, как к себе домой. Наше с ограми соглашение весьма эфемерно, и, боюсь, мы не сможем убедить их не нападать на тебя.$B$BНо я разрешу тебе использовать наши телепортирующие кровавые камни. Тут все очень просто. Положи руки на камень справа от меня, и окажешься снаружи пещеры. А чтобы телепортироваться обратно, используй камень, который снаружи!','Научитесь использовать телепортирующие кровавые камни в Горне Молота Ужаса.','Замечательно. Теперь, когда с этим разобрались…','Вернитесь к волшебнице крови Линоре в Горн Молота Ужаса, что в Выжженных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Настроиться на кровавый камень',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Надо признаться, мы выбрали не самое удобное место для своих исследований. И особенно неподходящее – для любопытных искателей приключений, которые предпочли бы заходить сюда, как к себе домой. Наше с ограми соглашение весьма эфемерно, и, боюсь, мы не сможем убедить их не нападать на тебя.$B$BНо я разрешу тебе использовать наши телепортирующие кровавые камни. Тут все очень просто. Положи руки на камень справа от меня, и окажешься снаружи пещеры. А чтобы телепортироваться обратно, используй камень, который снаружи!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Научитесь использовать телепортирующие кровавые камни в Горне Молота Ужаса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Замечательно. Теперь, когда с этим разобрались…',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к волшебнице крови Линоре в Горн Молота Ужаса, что в Выжженных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25685,'Первый шаг','Для того, чтобы исполнить нужный ритуал, а, возможно, и несколько ритуалов в будущем, потребуется кровь. В Выжженных землях полно самых разных реагентов для нашей магии крови, нужно только правильно их смешать.$B$B<Линора быстро говорит о чем-то с Дразиалом.>$B$BКровь василисков и гиен, в равном количестве. Крови надо очень много, так что тебе теперь идти на восток, в самый центр Выжженных земель. И не забудь, что теперь ты можешь пользоваться телепортом.','Добудьте 9 флаконов крови хохочущей гиены и 9 флаконов крови краснокаменного василиска.','<Линора жадно рассматривает кровь.>$B$BХватит с лихвой, и она еще даже теплая! Ну что ж, давай начинать ритуал!','Огрская кровь не для всего подходит. Достал, что мы просили?','Вернитесь к волшебнице крови Линоре в Горн Молота Ужаса, что в Выжженных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Первый шаг',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Для того, чтобы исполнить нужный ритуал, а, возможно, и несколько ритуалов в будущем, потребуется кровь. В Выжженных землях полно самых разных реагентов для нашей магии крови, нужно только правильно их смешать.$B$B<Линора быстро говорит о чем-то с Дразиалом.>$B$BКровь василисков и гиен, в равном количестве. Крови надо очень много, так что тебе теперь идти на восток, в самый центр Выжженных земель. И не забудь, что теперь ты можешь пользоваться телепортом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 9 флаконов крови хохочущей гиены и 9 флаконов крови краснокаменного василиска.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Линора жадно рассматривает кровь.>$B$BХватит с лихвой, и она еще даже теплая! Ну что ж, давай начинать ритуал!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Огрская кровь не для всего подходит. Достал, что мы просили?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к волшебнице крови Линоре в Горн Молота Ужаса, что в Выжженных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25686,'Ритуал крови','Нам нужно найти охотника на демонов по имени Лорам Многоног. Скажи, когда ты будешь $gготов:готова; начать ритуал, и я начну ритуал.','Поговорите с волшебницей крови Линорой, чтобы она начала ритуал.','Кровавый ритуал удался, и я теперь отлично вижу Лорама. То есть, гм, я отлично вижу разбросанные части его тела…','Вернитесь к волшебнице крови Линоре в Горн Молота Ужаса, что в Выжженных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ритуал крови',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нам нужно найти охотника на демонов по имени Лорам Многоног. Скажи, когда ты будешь $gготов:готова; начать ритуал, и я начну ритуал.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с волшебницей крови Линорой, чтобы она начала ритуал.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Кровавый ритуал удался, и я теперь отлично вижу Лорама. То есть, гм, я отлично вижу разбросанные части его тела…',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к волшебнице крови Линоре в Горн Молота Ужаса, что в Выжженных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (25687,'По кусочкам','Лорам Многоног погиб. Хотя, дай подумать... Это, конечно, не точно, но мне кажется, что его тело разделено на три части.$B$B<Линора на мгновение задумывается>$B$BЕсли принесешь мне все три части, мы сможем узнать то, что нам нужно. Они не так уж и далеко: огры из клана Молота Ужаса прячут их в пещерах. Одна часть лежит прямо здесь, вон в том сундуке позади меня, внизу.','Найдите голову, туловище и ноги Лорама.','Так… Да, с этим можно работать.$B$B<Линора смотрит на голову ночного эльфа.>$B$BЛорам Многоног, охотник на демонов. С нетерпением жду знакомства с тобой.','Поверь: что бы ни случилось с Лорамом, мы можем это исправить. Пределы магии крови пока непознаны.','Вернитесь к волшебнице крови Линоре в Горн Молота Ужаса, что в Выжженных землях.','Лорам Многоног, охотник на демонов собственной персоной.','Лорам Многоног') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','По кусочкам',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Лорам Многоног погиб. Хотя, дай подумать... Это, конечно, не точно, но мне кажется, что его тело разделено на три части.$B$B<Линора на мгновение задумывается>$B$BЕсли принесешь мне все три части, мы сможем узнать то, что нам нужно. Они не так уж и далеко: огры из клана Молота Ужаса прячут их в пещерах. Одна часть лежит прямо здесь, вон в том сундуке позади меня, внизу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите голову, туловище и ноги Лорама.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так… Да, с этим можно работать.$B$B<Линора смотрит на голову ночного эльфа.>$B$BЛорам Многоног, охотник на демонов. С нетерпением жду знакомства с тобой.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Поверь: что бы ни случилось с Лорамом, мы можем это исправить. Пределы магии крови пока непознаны.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к волшебнице крови Линоре в Горн Молота Ужаса, что в Выжженных землях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Лорам Многоног, охотник на демонов собственной персоной.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Лорам Многоног',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25688,'На утесах над нашей уютной пещеркой есть могущественный алтарь. Могущественный ДЕМОНИЧЕСКИЙ алтарь, который охраняют сектанты. Если ты сумеешь добраться до алтаря, то сумеешь и вернуть Лорама.$B$BСкорее всего, алтарь будет сопротивляться тебе, поэтому придется защищать тело Лорама, пока не закончится ритуал. А когда он закончится, приведи охотника на демонов сюда.','Ах ты… бестолочь! Что ты наделал?!','Вернитесь к Лораму Многоногу в Горн Молота Ужаса, что в Выжженных землях.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На утесах над нашей уютной пещеркой есть могущественный алтарь. Могущественный ДЕМОНИЧЕСКИЙ алтарь, который охраняют сектанты. Если ты сумеешь добраться до алтаря, то сумеешь и вернуть Лорама.$B$BСкорее всего, алтарь будет сопротивляться тебе, поэтому придется защищать тело Лорама, пока не закончится ритуал. А когда он закончится, приведи охотника на демонов сюда.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ах ты… бестолочь! Что ты наделал?!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лораму Многоногу в Горн Молота Ужаса, что в Выжженных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (25689,'Времени нет','Я преследовал демона по имени Разелих, но потом на меня напал его прислужник Грол. Этот огр напал на меня из засады, и я погиб... Но Грол погиб вместе со мной.$B$BРазелих хочет вернуться в Выжженные земли и наводнить их своими демонами. Пока мы говорим, он готовится призвать сюда свои легионы, чтобы они уничтожили нас.$B$B<Охотник на демонов быстро чертит в воздухе руну и дает ее вам.>$B$BОтнеси это Ваззику к Темному порталу, что к юго-востоку. Он скажет тебе, что делать. Скорей! Времени нет!','Отнесите диссонирующую руну дозорному Ваззику к Темному порталу в Выжженных землях.','Что?! ЛОРАМ?!$B$BЧтобы тебя, ну-ка потише! Если мой начальник узнает, что я работал на Лорама, он меня так взгреет, мало не покажется!$B$B<Ваззик берет у вас руну, прижимает ее к груди, закрывает глаза и кивает.>$B$BНу что ж, ты не соврал. За работу!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Времени нет',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я преследовал демона по имени Разелих, но потом на меня напал его прислужник Грол. Этот огр напал на меня из засады, и я погиб... Но Грол погиб вместе со мной.$B$BРазелих хочет вернуться в Выжженные земли и наводнить их своими демонами. Пока мы говорим, он готовится призвать сюда свои легионы, чтобы они уничтожили нас.$B$B<Охотник на демонов быстро чертит в воздухе руну и дает ее вам.>$B$BОтнеси это Ваззику к Темному порталу, что к юго-востоку. Он скажет тебе, что делать. Скорей! Времени нет!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите диссонирующую руну дозорному Ваззику к Темному порталу в Выжженных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что?! ЛОРАМ?!$B$BЧтобы тебя, ну-ка потише! Если мой начальник узнает, что я работал на Лорама, он меня так взгреет, мало не покажется!$B$B<Ваззик берет у вас руну, прижимает ее к груди, закрывает глаза и кивает.>$B$BНу что ж, ты не соврал. За работу!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25690,'Волшебнику крови тоже хочется кушать','Вопреки распространенному мнению, эльфийские волшебники крови кровь не пьют. Мы едим обычную еду, как и все остальные, но ее-то как раз в огрской крепости достать трудно.$B$BА вот в центральной долине Выжженных земель водятся пеплогривые кабаны... очень даже пригодные в пищу, поскольку их мясо не нужно готовить – его можно есть прямо сырым. Не хочешь ли ты поохотиться на кабанов и помочь мне пополнить запасы провизии?','Отправляйтесь в Выжженные земли и раздобудьте 5 кусков мяса пеплогривых кабанов.','Я умираю от голода! Если ты не поторопишься, я, наверное, выпью все наши реактивы.','Вернитесь к волшебнику крови Дразиалу в Горн Молота Ужаса, что в Выжженных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Волшебнику крови тоже хочется кушать',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вопреки распространенному мнению, эльфийские волшебники крови кровь не пьют. Мы едим обычную еду, как и все остальные, но ее-то как раз в огрской крепости достать трудно.$B$BА вот в центральной долине Выжженных земель водятся пеплогривые кабаны... очень даже пригодные в пищу, поскольку их мясо не нужно готовить – его можно есть прямо сырым. Не хочешь ли ты поохотиться на кабанов и помочь мне пополнить запасы провизии?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Выжженные земли и раздобудьте 5 кусков мяса пеплогривых кабанов.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я умираю от голода! Если ты не поторопишься, я, наверное, выпью все наши реактивы.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к волшебнику крови Дразиалу в Горн Молота Ужаса, что в Выжженных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25691,'Обугленный гранит у Темного портала','Лорам хочет, чтобы мы – то есть, ТЫ – $gнабрал:набрала; крошек с камней около Темного портала. Я не знаю, на что ему эти камни, но кое-какие мысли у меня есть, и эти мысли не очень-то приятные.$B$BВот, возьми эту кирку и поищи, где там у Темного портала из-под земли выступают камни. Ищи по краю зоны взрыва.','Соберите 24 обугленные гранитные крошки.','Надеюсь, это ему подойдет. Все равно у нас нет времени на то, чтобы ты возвращался и копал снова.','Давай-ка потише, а?','Вернитесь к дозорному Ваззику в Темный портал, что в Выжженных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обугленный гранит у Темного портала',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Лорам хочет, чтобы мы – то есть, ТЫ – $gнабрал:набрала; крошек с камней около Темного портала. Я не знаю, на что ему эти камни, но кое-какие мысли у меня есть, и эти мысли не очень-то приятные.$B$BВот, возьми эту кирку и поищи, где там у Темного портала из-под земли выступают камни. Ищи по краю зоны взрыва.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 24 обугленные гранитные крошки.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Надеюсь, это ему подойдет. Все равно у нас нет времени на то, чтобы ты возвращался и копал снова.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Давай-ка потише, а?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к дозорному Ваззику в Темный портал, что в Выжженных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25692,'Поганая кровь демонов','Многоногу нужна кровь демонов. Лично я бы эту дрянь и кровью-то не назвал, это какая-то жидкая гниль, ну да неважно.$B$BК счастью для тебя, демонов вокруг Темного портала хватает. Огненные големы, гончие Скверны, стражи Скверны... В них крови – хоть залейся.','Добудьте 7 бутылок жуткой крови демонов.','Сомнений нет: ты и впрямь добыл кровь демонов.$B$BКстати, кроме Лорама тебе будет очень благодарен Дар\'тун: он и его бойцы уже замучились драться с этими демонами.','Фу, ну и запах! Это от тебя или от этой крови такая вонища?','Вернитесь к дозорному Ваззику в Темный портал, что в Выжженных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поганая кровь демонов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Многоногу нужна кровь демонов. Лично я бы эту дрянь и кровью-то не назвал, это какая-то жидкая гниль, ну да неважно.$B$BК счастью для тебя, демонов вокруг Темного портала хватает. Огненные големы, гончие Скверны, стражи Скверны... В них крови – хоть залейся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 7 бутылок жуткой крови демонов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сомнений нет: ты и впрямь добыл кровь демонов.$B$BКстати, кроме Лорама тебе будет очень благодарен Дар\'тун: он и его бойцы уже замучились драться с этими демонами.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Фу, ну и запах! Это от тебя или от этой крови такая вонища?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к дозорному Ваззику в Темный портал, что в Выжженных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (25693,'Дальнейшая подготовка','<Ваззик заканчивает упаковывать материалы в аккуратный сверток.>$B$BЗдесь все, что просил Лорам. Когда встретишься с ним, обязательно скажи, что я помогал. А то, боюсь, сам он об этом не догадается.','Отнесите посылку Ваззика Лораму Многоногу в Горн Молота Ужаса в Выжженных землях.','Этого достаточно. Если еще раз увидишь Ваззика, то скажи ему, что он сработал удовлетворительно. Я велю волшебникам крови приниматься за работу: нужно изготовить каменный нож опечатывания. И никаких вопросов. Все узнаешь в свое время.$B$BПока они работают, я дам тебе еще одно задание. Даже нет – три задания.','Монах... Вот и ты...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дальнейшая подготовка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Ваззик заканчивает упаковывать материалы в аккуратный сверток.>$B$BЗдесь все, что просил Лорам. Когда встретишься с ним, обязательно скажи, что я помогал. А то, боюсь, сам он об этом не догадается.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите посылку Ваззика Лораму Многоногу в Горн Молота Ужаса в Выжженных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Этого достаточно. Если еще раз увидишь Ваззика, то скажи ему, что он сработал удовлетворительно. Я велю волшебникам крови приниматься за работу: нужно изготовить каменный нож опечатывания. И никаких вопросов. Все узнаешь в свое время.$B$BПока они работают, я дам тебе еще одно задание. Даже нет – три задания.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Монах... Вот и ты...',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25694,'Защита тылов','Я сотрудничаю с воинами Альянса исключительно потому, что наше чувство долга превыше вражды... хоть и ненамного. Нам поручили охранять Темный портал, чтобы исключить несанкционированные перемещения. В связи с недавним катаклизмом, сейчас мы особенно уязвимы для атаки извне. Уже есть сообщения о черных драконах, появившихся в этих краях...$B$BМои бойцы исполняют свой долг, но у них тут другие задачи, и нам нужен кто-то, кто помог бы нам с демонами. Рядом с порталом ты найдешь троих демонов-лейтенантов. Их надо прикончить.','Убейте Джаррока Рваное Крыло, Шахандану и Гумгаза.','Вот теперь ты молодец.$B$B<Полководец придвигается ближе и шепчет:>$B$BГоблин… если тебе интересно, у меня есть еще одно маленькое, но ответственное поручение…','Вернитесь к полководцу Дар\'туну в Темный портал, что в Выжженных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Защита тылов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я сотрудничаю с воинами Альянса исключительно потому, что наше чувство долга превыше вражды... хоть и ненамного. Нам поручили охранять Темный портал, чтобы исключить несанкционированные перемещения. В связи с недавним катаклизмом, сейчас мы особенно уязвимы для атаки извне. Уже есть сообщения о черных драконах, появившихся в этих краях...$B$BМои бойцы исполняют свой долг, но у них тут другие задачи, и нам нужен кто-то, кто помог бы нам с демонами. Рядом с порталом ты найдешь троих демонов-лейтенантов. Их надо прикончить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Джаррока Рваное Крыло, Шахандану и Гумгаза.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот теперь ты молодец.$B$B<Полководец придвигается ближе и шепчет:>$B$BГоблин… если тебе интересно, у меня есть еще одно маленькое, но ответственное поручение…',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к полководцу Дар\'туну в Темный портал, что в Выжженных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25695,'Осторожность не помешает','<Полководец Дар\'тун говорит полушепотом.>$B$BУ меня есть приказ... сверху... как раз для тебя. Я не раз замечал, как солдаты Альянса периодически сверяются с какими-то документами... на той бочке, вон там. Было бы очень неплохо узнать, что там, в этих бумагах, и что замышляет Альянс. Мое положение и должность не позволяют мне лично заняться этим сомнительным делом, а ты здесь $gновенький:новенькая;, у тебя, может быть, и получится подойти незаметно...','Изучите планы Альянса у Темного портала и постарайтесь, чтобы вас не поймали за этим занятием.','Тебя точно никто не видел? Вот и славно.$B$B<Дар\'тун случает, как вы пересказываете ему все, что узнали из прочитанных бумаг.>$B$BГм… все вполне безобидно. То ли они там в Альянсе все идиоты и действительно ничего против нас не замышляют… то ли, наоборот, хитрые бестии и скрывают всю важную информацию гораздо лучше, чем думал. Как бы там ни было, ты молодец.','Вернитесь к полководцу Дар\'туну в Темный портал, что в Выжженных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Осторожность не помешает',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Полководец Дар\'тун говорит полушепотом.>$B$BУ меня есть приказ... сверху... как раз для тебя. Я не раз замечал, как солдаты Альянса периодически сверяются с какими-то документами... на той бочке, вон там. Было бы очень неплохо узнать, что там, в этих бумагах, и что замышляет Альянс. Мое положение и должность не позволяют мне лично заняться этим сомнительным делом, а ты здесь $gновенький:новенькая;, у тебя, может быть, и получится подойти незаметно...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Изучите планы Альянса у Темного портала и постарайтесь, чтобы вас не поймали за этим занятием.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебя точно никто не видел? Вот и славно.$B$B<Дар\'тун случает, как вы пересказываете ему все, что узнали из прочитанных бумаг.>$B$BГм… все вполне безобидно. То ли они там в Альянсе все идиоты и действительно ничего против нас не замышляют… то ли, наоборот, хитрые бестии и скрывают всю важную информацию гораздо лучше, чем думал. Как бы там ни было, ты молодец.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к полководцу Дар\'туну в Темный портал, что в Выжженных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (25696,'Экспедиция Солнечного Паруса','Ах да, мне на днях что-то такое говорили. Реликварий, да? Они искали кого-то... чтобы что-то сделать...$B$B<Полководец перебирает какие-то бумаги.>$B$BАга, вот! Рохан Солнечный Парус из Реликвария ищет всех боеспособных искателей приключений для того, чтобы принять участие в его археологической экспедиции на юг.$B$BВот, возьми это. Иди $gсам:сама; поговори с тем эльфом.','Поговорите с Роханом Солнечным Парусом в экспедиции Солнечного Паруса в Выжженных землях.','Добро пожаловать, путешественник. Спасибо, что откликнулся на мой зов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Экспедиция Солнечного Паруса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ах да, мне на днях что-то такое говорили. Реликварий, да? Они искали кого-то... чтобы что-то сделать...$B$B<Полководец перебирает какие-то бумаги.>$B$BАга, вот! Рохан Солнечный Парус из Реликвария ищет всех боеспособных искателей приключений для того, чтобы принять участие в его археологической экспедиции на юг.$B$BВот, возьми это. Иди $gсам:сама; поговори с тем эльфом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Роханом Солнечным Парусом в экспедиции Солнечного Паруса в Выжженных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Добро пожаловать, путешественник. Спасибо, что откликнулся на мой зов.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25697,'Амулет Аллистария','Когда мой господин помог мне лишиться глаз, он даровал мне зрение... Зрение, намного сильнее твоего и даже этих кровожадных эльфов. Мое зрение позволяет мне видеть предметы, наделенные демонической силой, например, амулет Аллистария.$B$BСам Аллистарий мертв, но свой амулет он закопал в Змеиных Кольцах, это к востоку отсюда. Этот амулет, вкупе с другими реликвиями, позволит нам взобраться на пик Разелиха.','Найдите амулет Аллистария в Змеиных Кольцах в Выжженных землях.','<Линора изучает амулет.>$B$BОн был верховным магом, я это чувствую. Я подержу амулет у себя, пока ты будешь собирать остальное.','В этом амулете Аллистарий заключил часть себя. Я до сих пор чую его злобу.','Вернитесь к волшебнице крови Линоре в Горн Молота Ужаса, что в Выжженных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Амулет Аллистария',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда мой господин помог мне лишиться глаз, он даровал мне зрение... Зрение, намного сильнее твоего и даже этих кровожадных эльфов. Мое зрение позволяет мне видеть предметы, наделенные демонической силой, например, амулет Аллистария.$B$BСам Аллистарий мертв, но свой амулет он закопал в Змеиных Кольцах, это к востоку отсюда. Этот амулет, вкупе с другими реликвиями, позволит нам взобраться на пик Разелиха.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите амулет Аллистария в Змеиных Кольцах в Выжженных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Линора изучает амулет.>$B$BОн был верховным магом, я это чувствую. Я подержу амулет у себя, пока ты будешь собирать остальное.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','В этом амулете Аллистарий заключил часть себя. Я до сих пор чую его злобу.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к волшебнице крови Линоре в Горн Молота Ужаса, что в Выжженных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25698,'Амулет Севины','Отнимите амулет Севины у Солюна, который живет близ Берега Обломков в Выжженных землях.','<Линора взвешивает амулет в руке.>$B$BЧернокнижница… И весьма сильная. Я пока что приберегу это, потом отдам.','Амулет Севины... вместе с двумя другими амулетами он поможет нам взобраться на утес Осквернителя.','Вернитесь к волшебнице крови Линоре в Горн Молота Ужаса, что в Выжженных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Амулет Севины',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнимите амулет Севины у Солюна, который живет близ Берега Обломков в Выжженных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Линора взвешивает амулет в руке.>$B$BЧернокнижница… И весьма сильная. Я пока что приберегу это, потом отдам.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Амулет Севины... вместе с двумя другими амулетами он поможет нам взобраться на утес Осквернителя.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к волшебнице крови Линоре в Горн Молота Ужаса, что в Выжженных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25699,'Амулет Грола','Грол... Огр, который порвал меня на части.$B$B<Лорам смеется.>$B$BКажется, с тех пор, как мы умерли вместе, тело Грола кочевало от владельца к владельцу, но сейчас у огров его нет. Его тело, как и амулет, находится на разбитом корабле у Берега Обломков, это к востоку. Его амулет – последний из тех, что нам нужен. Как только мы соберем все три, то сможем добраться до Разелиха и положить конец всему этому безумию.','Найдите амулет Грола на Берегу Обломков в Выжженных землях.','<Линора сжимает третий амулет в кулаке.>$B$Bего хозяин был отважным воином. Я буду хранить этот амулет, пока Лорам не скажет, что можно продолжать.','Третий амулет от третьего приспешника Разелиха.','Вернитесь к волшебнице крови Линоре в Горн Молота Ужаса, что в Выжженных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Амулет Грола',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Грол... Огр, который порвал меня на части.$B$B<Лорам смеется.>$B$BКажется, с тех пор, как мы умерли вместе, тело Грола кочевало от владельца к владельцу, но сейчас у огров его нет. Его тело, как и амулет, находится на разбитом корабле у Берега Обломков, это к востоку. Его амулет – последний из тех, что нам нужен. Как только мы соберем все три, то сможем добраться до Разелиха и положить конец всему этому безумию.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите амулет Грола на Берегу Обломков в Выжженных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Линора сжимает третий амулет в кулаке.>$B$Bего хозяин был отважным воином. Я буду хранить этот амулет, пока Лорам не скажет, что можно продолжать.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Третий амулет от третьего приспешника Разелиха.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к волшебнице крови Линоре в Горн Молота Ужаса, что в Выжженных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (25700,'Лорам Многоног ждет','Чары на этих амулетах были не особо сильные, но вместе они смогут перенести тебя к Разелиху, их создателю.$B$BЯ готова провести ритуал для тебя и Лорама, поэтому скажите, когда оба будете готовы.','Поговорите с волшебницей крови Линорой, когда будете готовы принять участие в ее ритуале.','Принять участие в ритуале','Вернитесь к Лораму Многоногу в Горн Молота Ужаса, что в Выжженных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лорам Многоног ждет',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чары на этих амулетах были не особо сильные, но вместе они смогут перенести тебя к Разелиху, их создателю.$B$BЯ готова провести ритуал для тебя и Лорама, поэтому скажите, когда оба будете готовы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с волшебницей крови Линорой, когда будете готовы принять участие в ее ритуале.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Принять участие в ритуале',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лораму Многоногу в Горн Молота Ужаса, что в Выжженных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (25701,'Демон, имя тебе Рах\'лих','Поговорите с привратником смерти к северу от Утеса Осквернителя. Когда вы окажетесь на утесе, уничтожьте тело Разелиха, а потом захватите его душу при помощи каменного ножа опечатывания.','Понятно. Значит, Лорам планировал все это с самого начала.$B$BЯ так и думал, но боялся в это поверить. Теперь его последнее указание мне понятно. $B$BОн просил меня дать тебе одну из этих вещей на выбор.','Расскажите о судьбе Лорама дозорному Ваззику в Темном портале, что в Выжженных землях.','Тот, кто знает его настоящее имя, владеет его судьбой.','Рах\'лих') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Демон, имя тебе Рах\'лих',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с привратником смерти к северу от Утеса Осквернителя. Когда вы окажетесь на утесе, уничтожьте тело Разелиха, а потом захватите его душу при помощи каменного ножа опечатывания.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Понятно. Значит, Лорам планировал все это с самого начала.$B$BЯ так и думал, но боялся в это поверить. Теперь его последнее указание мне понятно. $B$BОн просил меня дать тебе одну из этих вещей на выбор.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Расскажите о судьбе Лорама дозорному Ваззику в Темном портале, что в Выжженных землях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Тот, кто знает его настоящее имя, владеет его судьбой.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Рах\'лих',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25702,'Наги пришли... деревню сожгли...','<Мурлок пытается говорить на вашем языке.>$B$BКаменистое Озеро... нападали. Наги приходить, захватить деревню, убивать всех.$B$BСолюн спасаться, больше никто не спасаться. Иди на юг, говори с вождем Нептусем. Может, он выживал.','По поручению Солюна поговорите с Нептусем, вождем мурлоков из стаи Каменистого Озера.','<Дух мурлока печально глядит на вас.>$B$BСолюн бежал, спасая свою жизнь. Но это не стыдно и не позорно. Загляни мне за спину, и сам все увидишь.$B$BПротив атаки наг у клана Каменистого Озера не было никаких шансов.','Поговорите с Нептусем на Красных берегах, что в Выжженных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наги пришли... деревню сожгли...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Мурлок пытается говорить на вашем языке.>$B$BКаменистое Озеро... нападали. Наги приходить, захватить деревню, убивать всех.$B$BСолюн спасаться, больше никто не спасаться. Иди на юг, говори с вождем Нептусем. Может, он выживал.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По поручению Солюна поговорите с Нептусем, вождем мурлоков из стаи Каменистого Озера.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Дух мурлока печально глядит на вас.>$B$BСолюн бежал, спасая свою жизнь. Но это не стыдно и не позорно. Загляни мне за спину, и сам все увидишь.$B$BПротив атаки наг у клана Каменистого Озера не было никаких шансов.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Нептусем на Красных берегах, что в Выжженных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25703,'Их надо остановить','<Хотя губы вождя мурлоков не шевелятся, он говорит с вами мысленно.>$B$BНаги Кровавого Прибоя и мурлоки Каменистого Озера испокон веков жили бок о бок. У нас всегда были трения и разногласия, мы вообще очень разные, и однако же мы как-то ладили и уживались. А теперь они вдруг ополчились на нас.$B$B<Нептусь смотрит через плечо на своих бывших подданных.>$B$BВидишь, что они делают? Приносят нас в жертву, порабощают, заставляют сражаться друг с другом. Их надо остановить, |3-6($r)... и ты мне поможешь.','Убейте 10 варваров и 10 чародеек из клана Кровавого Прибоя.','Вернитесь к Нептусю на Красные берега, что в Выжженных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Их надо остановить',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Хотя губы вождя мурлоков не шевелятся, он говорит с вами мысленно.>$B$BНаги Кровавого Прибоя и мурлоки Каменистого Озера испокон веков жили бок о бок. У нас всегда были трения и разногласия, мы вообще очень разные, и однако же мы как-то ладили и уживались. А теперь они вдруг ополчились на нас.$B$B<Нептусь смотрит через плечо на своих бывших подданных.>$B$BВидишь, что они делают? Приносят нас в жертву, порабощают, заставляют сражаться друг с другом. Их надо остановить, |3-6($r)... и ты мне поможешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 варваров и 10 чародеек из клана Кровавого Прибоя.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Нептусю на Красные берега, что в Выжженных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (25704,'Безумный волхв','Осталось сделать еще кое-что. Ты $gдолжен:должна; убить кого-нибудь с вудуистским амулетом на виду у Тони.$B$BНет-нет, только не меня!$B$BСтарина волхв Тирт съехал с катушек, когда пытался остановить воды, хлынувшие во время катаклизма. Блуждает теперь к югу от Крепи...$B$BВот, возьми-ка трость души и воспользуйся ею, когда займешься телом Тирта. Потом возвращайтесь вместе с Тони – и мы вернем его душонку обратно в тело.$B$BМожешь воспользоваться моим порталом духов, чтобы отправиться туда и обратно.','Извлеките душу из тела безумного волхва Тирта.','Теперь вернем Тони Два Клыка к жизни. Готов?','Вернитесь к Аджамон Призывательнице Духов в Укрепление Южных морей в Тысяче Игл.','Извлеки его душу.','Безумный волхв Тирт') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Безумный волхв',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Осталось сделать еще кое-что. Ты $gдолжен:должна; убить кого-нибудь с вудуистским амулетом на виду у Тони.$B$BНет-нет, только не меня!$B$BСтарина волхв Тирт съехал с катушек, когда пытался остановить воды, хлынувшие во время катаклизма. Блуждает теперь к югу от Крепи...$B$BВот, возьми-ка трость души и воспользуйся ею, когда займешься телом Тирта. Потом возвращайтесь вместе с Тони – и мы вернем его душонку обратно в тело.$B$BМожешь воспользоваться моим порталом духов, чтобы отправиться туда и обратно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Извлеките душу из тела безумного волхва Тирта.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь вернем Тони Два Клыка к жизни. Готов?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аджамон Призывательнице Духов в Укрепление Южных морей в Тысяче Игл.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Извлеки его душу.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Безумный волхв Тирт',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (25705,'Ложные идолы','Вернитесь к Нептусю на Красные берега, что в Выжженных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ложные идолы',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Нептусю на Красные берега, что в Выжженных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25706,'Месть Нептуся','Убейте 8 послушников, 8 ревнителей, 4 прохвостов и 4 идолопоклонников из клана Кровавого Прибоя.','Вернитесь к Нептусю на Красные берега, что в Выжженных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Месть Нептуся',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 послушников, 8 ревнителей, 4 прохвостов и 4 идолопоклонников из клана Кровавого Прибоя.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Нептусю на Красные берега, что в Выжженных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25707,'Будущее Каменистого Озера','Головастики Каменистого Озера, которых оставили в этом ящике, напуганы, истощены и почти полностью высохли. Их надо выпустить в воду, и как можно скорее.$B$BМожет быть, если ты выпустишь их в Зловещее море, подальше от Красных берегов, у них будет шанс уцелеть, и тогда мурлоки Каменистого озера не исчезнут...','Оттащите брошенный груз Кровавого Прибоя к Зловещему морю, подальше от Красных берегов, и выпустите головастиков в воду.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Будущее Каменистого Озера',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Головастики Каменистого Озера, которых оставили в этом ящике, напуганы, истощены и почти полностью высохли. Их надо выпустить в воду, и как можно скорее.$B$BМожет быть, если ты выпустишь их в Зловещее море, подальше от Красных берегов, у них будет шанс уцелеть, и тогда мурлоки Каменистого озера не исчезнут...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Оттащите брошенный груз Кровавого Прибоя к Зловещему морю, подальше от Красных берегов, и выпустите головастиков в воду.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25708,'Души погибших товарищей','Если я правильно поняла твои слова, в живых не осталось почти никого... и души погибших так и не обрели покой. Надо помочь им упокоиться с миром. Это – самое меньшее, что мы можем сделать для этих несчастных.$B$B<Еноха делает большой глоток черного эля.>$B$BВозвращайся на Берег Обломков и убей всех призрачных воргенов, которых найдешь. Это освободит их души, которых что-то удерживает в этом мире, и они смогут уйти в царство мертвых.','Убейте 13 утонувших жителей Гилнеаса на Берегу Обломков, чтобы их души упокоились в мире.','<Еноха отпивает из кружки, вновь наполненной элем.>$B$BОтлично, парень. Ты молодец. Сослужил добрую службу Альянсу.','Вернитесь к Енохе Громовар в Крепость Стражей Пустоты, что в Выжженных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Души погибших товарищей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если я правильно поняла твои слова, в живых не осталось почти никого... и души погибших так и не обрели покой. Надо помочь им упокоиться с миром. Это – самое меньшее, что мы можем сделать для этих несчастных.$B$B<Еноха делает большой глоток черного эля.>$B$BВозвращайся на Берег Обломков и убей всех призрачных воргенов, которых найдешь. Это освободит их души, которых что-то удерживает в этом мире, и они смогут уйти в царство мертвых.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 13 утонувших жителей Гилнеаса на Берегу Обломков, чтобы их души упокоились в мире.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Еноха отпивает из кружки, вновь наполненной элем.>$B$BОтлично, парень. Ты молодец. Сослужил добрую службу Альянсу.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Енохе Громовар в Крепость Стражей Пустоты, что в Выжженных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25709,'Отстрел темнохвостых','Меня вот что еще беспокоит... Тела мертвецов привлекают стервятников. Зная, на что эти птички способны, я думаю, они уже обклевали там все до костей, и тем не менее... Нельзя допустить, чтобы они оскверняли тела наших друзей.$B$BПрежде чем стать пивоваром, я была охотницей. Вот, возьми этот лук и, самое главное, эти стрелы. Их наконечники пропитаны необычным составом. Устроим птичкам сюрприз.','Используя взрывные стрелы Енохи, убейте 20 темнохвостых любителей костей на Берегу Обломков.','Вернитесь к Енохе Громовар в Крепость Стражей Пустоты, что в Выжженных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отстрел темнохвостых',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Меня вот что еще беспокоит... Тела мертвецов привлекают стервятников. Зная, на что эти птички способны, я думаю, они уже обклевали там все до костей, и тем не менее... Нельзя допустить, чтобы они оскверняли тела наших друзей.$B$BПрежде чем стать пивоваром, я была охотницей. Вот, возьми этот лук и, самое главное, эти стрелы. Их наконечники пропитаны необычным составом. Устроим птичкам сюрприз.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используя взрывные стрелы Енохи, убейте 20 темнохвостых любителей костей на Берегу Обломков.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Енохе Громовар в Крепость Стражей Пустоты, что в Выжженных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (25710,'Мелкие распри','Крепость Стражей Пустоты не один год защищает эти края от натиска демонов. Наша вахта бессменна, наша решимость непоколебима, наше мужество безгранично.$B$BМы охраняем здешние земли с тех пор, как открылся портал... но теперь эти ничтожества из Орды посмели встать у нас на пути! А ведь мы здесь защищаем не только себя, но и ИХ ТОЖЕ!$B$B<Лунгерц пристально смотрит на вас.>$B$BПосмотрим, какой из тебя боец. Убей одного из ордынских разведчиков Окрил\'лона. Как-то их развелось многовато на подступах к Крепости.','Вернитесь к интенданту Лунгерцу в Крепость Стражей Пустоты, что в Выжженных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мелкие распри',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Крепость Стражей Пустоты не один год защищает эти края от натиска демонов. Наша вахта бессменна, наша решимость непоколебима, наше мужество безгранично.$B$BМы охраняем здешние земли с тех пор, как открылся портал... но теперь эти ничтожества из Орды посмели встать у нас на пути! А ведь мы здесь защищаем не только себя, но и ИХ ТОЖЕ!$B$B<Лунгерц пристально смотрит на вас.>$B$BПосмотрим, какой из тебя боец. Убей одного из ордынских разведчиков Окрил\'лона. Как-то их развелось многовато на подступах к Крепости.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к интенданту Лунгерцу в Крепость Стражей Пустоты, что в Выжженных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (25711,'Уничтожить Окрил\'лон','Вернитесь к интенданту Лунгерцу в Крепость Стражей Пустоты, что в Выжженных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уничтожить Окрил\'лон',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к интенданту Лунгерцу в Крепость Стражей Пустоты, что в Выжженных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (25712,'Крепость Стражей Пустоты','Лунгерц – сильный лидер, однако он слишком самонадеян и не желает признать, что Орда представляет серьезную опасность для наших позиций. Без рудников... наша Крепость останется без гроша.$B$BНам нужно НЕМЕДЛЕННО вытеснить силы Орды из лагеря поддержки Гарнизона, а для этого надо убить их командира, капитана Метлека. Как командующий армией он ничего собой не представляет: прячется за спины своих солдат и выкрикивает приказы из арьергарда. И тем не менее, смерть командира подорвет их моральный дух и, может быть, обеспечит нам победу.','Вернитесь к Леану Стилсону в Крепость Стражей Пустоты, что в Выжженных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Крепость Стражей Пустоты',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Лунгерц – сильный лидер, однако он слишком самонадеян и не желает признать, что Орда представляет серьезную опасность для наших позиций. Без рудников... наша Крепость останется без гроша.$B$BНам нужно НЕМЕДЛЕННО вытеснить силы Орды из лагеря поддержки Гарнизона, а для этого надо убить их командира, капитана Метлека. Как командующий армией он ничего собой не представляет: прячется за спины своих солдат и выкрикивает приказы из арьергарда. И тем не менее, смерть командира подорвет их моральный дух и, может быть, обеспечит нам победу.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Леану Стилсону в Крепость Стражей Пустоты, что в Выжженных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (25713,'Кто же не любит хорошего взрыва?','Эй, как там тебя... $n, если не ошибаюсь? У меня есть для тебя работа. Надо будет немножечко повзрывать. Ну что, возьмешься?$B$BЯ просто случайно подслушала ваш разговор с интендантом. Понимаешь, в чем дело... Я разрабатываю взрывное устройство. Против живой силы оно не особенно эффективно, а вот артиллерию сметает на раз. Ты же, вроде, сейчас возвращаешься на поле... так сказать, в гости к оркам... Если тебе попадется склад вражеских боеприпасов, может быть, заодно испытаешь мое устройство? Кто знает... а вдруг они тоже любят, когда взрывают.','Вернитесь к Ракитни Маккитрик в Крепость Стражей Пустоты, что в Выжженных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кто же не любит хорошего взрыва?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эй, как там тебя... $n, если не ошибаюсь? У меня есть для тебя работа. Надо будет немножечко повзрывать. Ну что, возьмешься?$B$BЯ просто случайно подслушала ваш разговор с интендантом. Понимаешь, в чем дело... Я разрабатываю взрывное устройство. Против живой силы оно не особенно эффективно, а вот артиллерию сметает на раз. Ты же, вроде, сейчас возвращаешься на поле... так сказать, в гости к оркам... Если тебе попадется склад вражеских боеприпасов, может быть, заодно испытаешь мое устройство? Кто знает... а вдруг они тоже любят, когда взрывают.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ракитни Маккитрик в Крепость Стражей Пустоты, что в Выжженных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (25714,'Дозорный Махар Ба','Пора бы тебе навестить дозорного. В последнее время он какой-то смурной, а почему – я не знаю.$B$BПоднимись на самый верх башни и поговори с ним. Здесь для тебя все равно нет работы, а у дозорного наверняка что-то найдется.','Они правильно сделали, что прислали тебя ко мне. У меня тут возникла одна проблема… Крепости может грозить серьезная опасность… В общем, мне нужен кто-то, кто способен на большее, чем большинство здешних бойцов. Прощу прощения за каламбур.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дозорный Махар Ба',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пора бы тебе навестить дозорного. В последнее время он какой-то смурной, а почему – я не знаю.$B$BПоднимись на самый верх башни и поговори с ним. Здесь для тебя все равно нет работы, а у дозорного наверняка что-то найдется.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Они правильно сделали, что прислали тебя ко мне. У меня тут возникла одна проблема… Крепости может грозить серьезная опасность… В общем, мне нужен кто-то, кто способен на большее, чем большинство здешних бойцов. Прощу прощения за каламбур.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (25715,'Обломки кораблекрушения','Мы не раз наблюдали, как мимо этого берега корабли проплывают на юго-восток. Обычно мы не обращаем на них внимания. Плывут себе – и плывут... Но тут на днях была сильная буря, и несколько кораблей выбросило на берег.$B$BЯ бы поспорила на пинту горькой настойки, что это корабли Орды... если бы так не любила горькую настойку. Но я могу заплатить тебе золотом, если ты согласишься проверить, что это за корабли, и предоставишь мне подробный отчет.','Осмотрите обломки кораблекрушения на Берегу Обломков в Выжженных землях.','Корабли на Берегу Обломков обследованы','Вернитесь к Енохе Громовар в Крепость Стражей Пустоты, что в Выжженных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обломки кораблекрушения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы не раз наблюдали, как мимо этого берега корабли проплывают на юго-восток. Обычно мы не обращаем на них внимания. Плывут себе – и плывут... Но тут на днях была сильная буря, и несколько кораблей выбросило на берег.$B$BЯ бы поспорила на пинту горькой настойки, что это корабли Орды... если бы так не любила горькую настойку. Но я могу заплатить тебе золотом, если ты согласишься проверить, что это за корабли, и предоставишь мне подробный отчет.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Осмотрите обломки кораблекрушения на Берегу Обломков в Выжженных землях.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Корабли на Берегу Обломков обследованы',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Енохе Громовар в Крепость Стражей Пустоты, что в Выжженных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25716,'Сектанты у нас на пороге','Тебе, наверное, уже встречался кто-то из этих сектантов культа Приверженцев Тени, что обитают в пещерах на юго-западе от Крепости Хранителей Пустоты. Пока что они не представляют для нас опасности, но у меня есть подозрение, что они замышляют недоброе. Очень-очень недоброе.$B$BСектанты из низшего состава всегда носят с собой волшебные средоточия. Очень хотелось бы их изучить. Принеси мне несколько штук, но обязательно целых и неповрежденных. Ну, если сумеешь их вырвать из рук адептов культа.','Раздобудьте 6 средоточий чар Приверженцев Тени у воинственных чародеев и оккультистов из культа Приверженцев Тени в Выжженных землях.','Сектанты так легко не расстанутся со средоточиями чар. Надо их убивать быстро, пока они не разгадали твоих намерений.','Вернитесь к дозорному Махару Ба в Крепость Стражей Пустоты, что в Выжженных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сектанты у нас на пороге',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе, наверное, уже встречался кто-то из этих сектантов культа Приверженцев Тени, что обитают в пещерах на юго-западе от Крепости Хранителей Пустоты. Пока что они не представляют для нас опасности, но у меня есть подозрение, что они замышляют недоброе. Очень-очень недоброе.$B$BСектанты из низшего состава всегда носят с собой волшебные средоточия. Очень хотелось бы их изучить. Принеси мне несколько штук, но обязательно целых и неповрежденных. Ну, если сумеешь их вырвать из рук адептов культа.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте 6 средоточий чар Приверженцев Тени у воинственных чародеев и оккультистов из культа Приверженцев Тени в Выжженных землях.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Сектанты так легко не расстанутся со средоточиями чар. Надо их убивать быстро, пока они не разгадали твоих намерений.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к дозорному Махару Ба в Крепость Стражей Пустоты, что в Выжженных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25717,'Демоны и друид','Реликварий занимается тем, что разыскивает и хранит магические артефакты. Наша экспедиция занимается демоническими артефактами, которые находятся там, где некогда был Гниющий Шрам.$B$BВ этом месте поселился один ворген-друид, который пытается вырастить там лес, но, похоже, у него ничего не получается, потому что тут до сих пор полно демонов.$B$BВ любом случае, этот лес, как и демоны в нем, стоят у нашей экспедиции на пути. Поэтому сперва убей демонов, а потом возвращайся ко мне и подумаем, что делать с друидом.','Убейте 5 стражей ужаса – разрушителей, 5 повелителей ужаса – осквернителей, 5 оскверненных темностволых древней и 3 скверноспорых болотников в Проклятом лесу.','Вернитесь к Рохану Солнечному Парусу в экспедицию Солнечного Паруса, что в Выжженных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Демоны и друид',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Реликварий занимается тем, что разыскивает и хранит магические артефакты. Наша экспедиция занимается демоническими артефактами, которые находятся там, где некогда был Гниющий Шрам.$B$BВ этом месте поселился один ворген-друид, который пытается вырастить там лес, но, похоже, у него ничего не получается, потому что тут до сих пор полно демонов.$B$BВ любом случае, этот лес, как и демоны в нем, стоят у нашей экспедиции на пути. Поэтому сперва убей демонов, а потом возвращайся ко мне и подумаем, что делать с друидом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 5 стражей ужаса – разрушителей, 5 повелителей ужаса – осквернителей, 5 оскверненных темностволых древней и 3 скверноспорых болотников в Проклятом лесу.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Рохану Солнечному Парусу в экспедицию Солнечного Паруса, что в Выжженных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (25718,'Что делать дальше','Пока ты $gубивал:убивала; демонов, наши разведчики сумели пробраться к этому друиду и посмотреть на него. Они говорят, что его зовут Марл Червоточный... друид недюжинной силы, ушедший из Гилнеаса. Он поселился в Малдразе – это большое испорченное дерево в центре леса, которое защищают какие-то странные силы. Демонические ли это силы или природные, нам еще предстоит узнать.$B$BПоговори с Элайджей. Он, возможно, расскажет тебе кое-что интересное.','Поговорите с Элайджей Рассветным Полетом в экспедиции Солнечного Паруса в Выжженных землях.','Рохан отправил ТЕБЯ убивать этого друида? Ну ладно.$B$BТолько знай: Марл Червоточный насколько друид, настолько и демон. Даже такой умелый друид, как он, не выдержал бы влияния демонической энергии, которой пронизаны все эти земли. Но это отнюдь не делает его слабее.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Что делать дальше',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пока ты $gубивал:убивала; демонов, наши разведчики сумели пробраться к этому друиду и посмотреть на него. Они говорят, что его зовут Марл Червоточный... друид недюжинной силы, ушедший из Гилнеаса. Он поселился в Малдразе – это большое испорченное дерево в центре леса, которое защищают какие-то странные силы. Демонические ли это силы или природные, нам еще предстоит узнать.$B$BПоговори с Элайджей. Он, возможно, расскажет тебе кое-что интересное.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Элайджей Рассветным Полетом в экспедиции Солнечного Паруса в Выжженных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Рохан отправил ТЕБЯ убивать этого друида? Ну ладно.$B$BТолько знай: Марл Червоточный насколько друид, настолько и демон. Даже такой умелый друид, как он, не выдержал бы влияния демонической энергии, которой пронизаны все эти земли. Но это отнюдь не делает его слабее.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25719,'Демонический резервуар','Нужно привлечь внимание Червоточного, как-то вывести его из этого транса, но только чтобы наверняка.$B$BТа немногая живность, которая сумела обосноваться в Проклятом лесу, наверняка подвержена влиянию местной скрытой энергии. Тебе нужно будет собрать части их тел и соединить их в некую емкость. В каком бы трансе ни пребывал Червоточный – в друидском или демоническом – большой резервуар, полный зараженной животной плоти, сможет его нарушить.','Убейте нечистых черных медведей, нечистых ночных ловцов и нечистых крикунов в Проклятом лесу, а потом составьте из их органов демонический резервуар.','Вернитесь к Рохану Солнечному Парусу в экспедицию Солнечного Паруса, что в Выжженных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Демонический резервуар',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нужно привлечь внимание Червоточного, как-то вывести его из этого транса, но только чтобы наверняка.$B$BТа немногая живность, которая сумела обосноваться в Проклятом лесу, наверняка подвержена влиянию местной скрытой энергии. Тебе нужно будет собрать части их тел и соединить их в некую емкость. В каком бы трансе ни пребывал Червоточный – в друидском или демоническом – большой резервуар, полный зараженной животной плоти, сможет его нарушить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте нечистых черных медведей, нечистых ночных ловцов и нечистых крикунов в Проклятом лесу, а потом составьте из их органов демонический резервуар.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Рохану Солнечному Парусу в экспедицию Солнечного Паруса, что в Выжженных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (25720,'Падение Марла Червоточного','Демонический лес Червоточного мешает нашей экспедиции. Корни его деревьев ломают наши кирки, места раскопок тут же зарастают мхом, а животные нападают на моих товарищей. Если бы я мог выбирать, то я бы лучше копал в пустоши, населенной демонами, чем в этом лесу!$B$BВозьми этот демонический резервуар и с его помощью выведи Марла Червоточного из транса. Убей его и возвращайся ко мне.','Убейте Марла Червоточного у дерева Малдраз в Выжженных землях. Для того чтобы вывести Марла из транса, используйте демонический резервуар.','Вернитесь к Рохану Солнечному Парусу в экспедицию Солнечного Паруса, что в Выжженных землях.','Когда его разумом завладели демоны, последняя надежда была утеряна.','Марл Червоточный') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Падение Марла Червоточного',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Демонический лес Червоточного мешает нашей экспедиции. Корни его деревьев ломают наши кирки, места раскопок тут же зарастают мхом, а животные нападают на моих товарищей. Если бы я мог выбирать, то я бы лучше копал в пустоши, населенной демонами, чем в этом лесу!$B$BВозьми этот демонический резервуар и с его помощью выведи Марла Червоточного из транса. Убей его и возвращайся ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Марла Червоточного у дерева Малдраз в Выжженных землях. Для того чтобы вывести Марла из транса, используйте демонический резервуар.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Рохану Солнечному Парусу в экспедицию Солнечного Паруса, что в Выжженных землях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Когда его разумом завладели демоны, последняя надежда была утеряна.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Марл Червоточный',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25721,'Борьба с наводнением','Я здесь, потому что сам Мурадин знал, что за этими фиглярами кто-то должен присматривать. Как же они боятся дикой природы, даже пальцем не смеют пошевельнуть! Чтобы их заставить сдвинуться с места, нужно тут сперва все утрясти.$B$BПерво-наперво, у нас неприятности с элементалями. Наводнение так все перебаламутило, что сама вода взбесилась.$B$BСпорю на что угодно, тебе еще не приходилось приводить в чувство целое озеро? А я тебя как раз о том и прошу. Найди элементалей и взгрей-ка их хорошенько.','Убейте 10 элементалей потока.','Ух, чтоб меня. Наконец-то нашелся хоть кто-то, кто своими деяниями не позорит Магни, благословенно будь его бедное сердце.$B$BТы заслужил право первым испить пива из свежеоткрытой бочки. Но смотри, чтоб оно тебе в голову не ударило! У нас впереди работы – непочатый край, и я не дам тебе сачковать!','Вернитесь к Форбе Крепкой Стамеске на привал Крепкой Стамески, что в Болотине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Борьба с наводнением',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я здесь, потому что сам Мурадин знал, что за этими фиглярами кто-то должен присматривать. Как же они боятся дикой природы, даже пальцем не смеют пошевельнуть! Чтобы их заставить сдвинуться с места, нужно тут сперва все утрясти.$B$BПерво-наперво, у нас неприятности с элементалями. Наводнение так все перебаламутило, что сама вода взбесилась.$B$BСпорю на что угодно, тебе еще не приходилось приводить в чувство целое озеро? А я тебя как раз о том и прошу. Найди элементалей и взгрей-ка их хорошенько.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 элементалей потока.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ух, чтоб меня. Наконец-то нашелся хоть кто-то, кто своими деяниями не позорит Магни, благословенно будь его бедное сердце.$B$BТы заслужил право первым испить пива из свежеоткрытой бочки. Но смотри, чтоб оно тебе в голову не ударило! У нас впереди работы – непочатый край, и я не дам тебе сачковать!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Форбе Крепкой Стамеске на привал Крепкой Стамески, что в Болотине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25722,'Сухой остаток','Разрушение Каменной плотины – настоящая катастрофа, $gдружок:детка;. Теперь нужно выяснить, насколько плохи дела. Здесь пронесся колоссальный поток воды, и если земля пострадала слишком сильно, нам это потом аукнется.$B$BС помощью изучения отложений в затопленной местности можно узнать много полезного. Мне нужно собрать как можно больше образцов почвы, так что если ты отправишься туда и принесешь еще несколько штук, буду очень признателен.','Соберите 8 образцов принесенных наводнением наносов.','Вернитесь к геодезисту Турдану на привал Крепкой Стамески, что в Болотине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сухой остаток',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Разрушение Каменной плотины – настоящая катастрофа, $gдружок:детка;. Теперь нужно выяснить, насколько плохи дела. Здесь пронесся колоссальный поток воды, и если земля пострадала слишком сильно, нам это потом аукнется.$B$BС помощью изучения отложений в затопленной местности можно узнать много полезного. Мне нужно собрать как можно больше образцов почвы, так что если ты отправишься туда и принесешь еще несколько штук, буду очень признателен.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 образцов принесенных наводнением наносов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к геодезисту Турдану на привал Крепкой Стамески, что в Болотине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25724,'Агрессия Мерзлогривов','Из-за катаклизма баланс сил в Дун Мороге изменился, $n. Без всякого предупреждения множество троггов выбрались на поверхность из пещер возле Гномрегана и напали на троллей из племени Мерзлогривов. Тролли мигрировали так далеко на восток, как никогда раньше.$b$bНа Мерцающем хребте, что к северо-западу отсюда, Мерзлогривы были и раньше, но теперь после миграции тролли нас окружают со всех сторон. Мы не можем позволить им воспользоваться ситуацией. Пока мои люди держат оборону на востоке, нанеси удар по Мерцающему хребту.','Убейте 5 ясновидцев из племени Мерзлогривов и 7 снегобродов из племени Мерзлогривов на Мерцающем хребте.','Мы должны иметь возможность бросить все силы на оставшихся на востоке троллей, но еще не все вендиго из Серой берлоги истреблены.','Вернитесь к капитану Таррану в Каранос.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Агрессия Мерзлогривов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Из-за катаклизма баланс сил в Дун Мороге изменился, $n. Без всякого предупреждения множество троггов выбрались на поверхность из пещер возле Гномрегана и напали на троллей из племени Мерзлогривов. Тролли мигрировали так далеко на восток, как никогда раньше.$b$bНа Мерцающем хребте, что к северо-западу отсюда, Мерзлогривы были и раньше, но теперь после миграции тролли нас окружают со всех сторон. Мы не можем позволить им воспользоваться ситуацией. Пока мои люди держат оборону на востоке, нанеси удар по Мерцающему хребту.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 5 ясновидцев из племени Мерзлогривов и 7 снегобродов из племени Мерзлогривов на Мерцающем хребте.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мы должны иметь возможность бросить все силы на оставшихся на востоке троллей, но еще не все вендиго из Серой берлоги истреблены.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Таррану в Каранос.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25725,'Целебная клюква','Провизии у нас в избытке, а вот с лекарствами беда. Пол-лагеря похмельем мучается, надо бы ребятам как-то помочь.$B$BК счастью, маманя у меня знала толк в народной медицине, а я у нее научился. Надо только раздобыть особый ингредиент.$B$BНабери-ка мне клюквы. Она растет обычно в тени рядом с водой – ты пройдись вдоль берега, посмотри там рядом с другими растениями.','Соберите 15 пригоршней клюквы.','Годится. Сейчас отвар сделаю и в два счета парней на ноги поставлю.','Сколько уже насобирал?','Вернитесь к Дунлору Мраморной Бороде на привал Крепкой Стамески, что в Болотине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Целебная клюква',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Провизии у нас в избытке, а вот с лекарствами беда. Пол-лагеря похмельем мучается, надо бы ребятам как-то помочь.$B$BК счастью, маманя у меня знала толк в народной медицине, а я у нее научился. Надо только раздобыть особый ингредиент.$B$BНабери-ка мне клюквы. Она растет обычно в тени рядом с водой – ты пройдись вдоль берега, посмотри там рядом с другими растениями.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 15 пригоршней клюквы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Годится. Сейчас отвар сделаю и в два счета парней на ноги поставлю.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Сколько уже насобирал?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дунлору Мраморной Бороде на привал Крепкой Стамески, что в Болотине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25726,'Нивелирная работа','Так, мне нужно найти мой глухой нивелир.$B$BГлухой нивелир! Что ты $gуставился:уставилась;?! Инструмент такой вообще-то!$B$BЯ не виноват, что он так называется! Иди поищи эту штуковину. Я его оставил на земле на пару мгновений всего, и тут же один из этих слизнюков умудрился мой нивелир слопать! Теперь ползает где-то там, пытаясь его переварить.','Добудьте глухой нивелир из илистого слизнюка.','Какое счастье, он не поврежден! Громадное спасибо тебе.$B$BТы это… слизь-то с одежки стряхни, что ли…','Вернитесь к геодезисту Турдану на привал Крепкой Стамески, что в Болотине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нивелирная работа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Так, мне нужно найти мой глухой нивелир.$B$BГлухой нивелир! Что ты $gуставился:уставилась;?! Инструмент такой вообще-то!$B$BЯ не виноват, что он так называется! Иди поищи эту штуковину. Я его оставил на земле на пару мгновений всего, и тут же один из этих слизнюков умудрился мой нивелир слопать! Теперь ползает где-то там, пытаясь его переварить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте глухой нивелир из илистого слизнюка.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Какое счастье, он не поврежден! Громадное спасибо тебе.$B$BТы это… слизь-то с одежки стряхни, что ли…',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к геодезисту Турдану на привал Крепкой Стамески, что в Болотине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (25727,'Друнгельд Исподлоб','Дворфы из клана Черного Железа здесь только для того, чтобы строить нам козни. Хотя удивляться не приходится – ты-то, я надеюсь, сразу $gпросек:просекла;, что это за народ. В Стальгорне Мурадину, может, и приходится этих черномазых терпеть, но за пределами города действуют иные правила.$B$BПрошлой ночью на лагерь напали, и одного раза более чем достаточно. Их предводитель – здоровенный детина по имени Исподлоб – прячется в пещере на южном берегу реки.$B$BПринеси мне его бороду – тогда я буду знать, что Исподлоб более не угрожает ни нам, ни Стальгорну.','Убейте Друнгельда Исподлоба и заберите его бороду.','Туда ему и дорога! А эту вонючую гадость я потом сожгу где-нибудь подальше от лагеря.','Покажи-ка ее.','Вернитесь к Форбе Крепкой Стамеске на привал Крепкой Стамески, что в Болотине.','Принеси его бороду. Да, его бороду.','Друнгельд Исподлоб') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Друнгельд Исподлоб',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Дворфы из клана Черного Железа здесь только для того, чтобы строить нам козни. Хотя удивляться не приходится – ты-то, я надеюсь, сразу $gпросек:просекла;, что это за народ. В Стальгорне Мурадину, может, и приходится этих черномазых терпеть, но за пределами города действуют иные правила.$B$BПрошлой ночью на лагерь напали, и одного раза более чем достаточно. Их предводитель – здоровенный детина по имени Исподлоб – прячется в пещере на южном берегу реки.$B$BПринеси мне его бороду – тогда я буду знать, что Исподлоб более не угрожает ни нам, ни Стальгорну.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Друнгельда Исподлоба и заберите его бороду.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Туда ему и дорога! А эту вонючую гадость я потом сожгу где-нибудь подальше от лагеря.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Покажи-ка ее.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Форбе Крепкой Стамеске на привал Крепкой Стамески, что в Болотине.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Принеси его бороду. Да, его бороду.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Друнгельд Исподлоб',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25728,'Дикая охота Господина П.','Убейте 20 гоблинов-техников и 5 гоблинских жнецов.','<Лорд Болотная Пахота.>$B$BГлупость какая…$B$BВы тут с роботом хорошо потрудились. Даже врасплох меня застали. Я и не знал, что эта девчонка такая…$B$B<Лорд Болотная Пахота крутит пальцем у виска.>$B$BОсобенная…$B$BЛадно, не пересчитывать же перья дареному гиппогрифу, я прав?$B$BДумаю, да.$B$BЧто ж, вот вам на мороженое.','Поговорите с лордом Болотной Пахотой в крепости Ветрорезов в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дикая охота Господина П.',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 20 гоблинов-техников и 5 гоблинских жнецов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Лорд Болотная Пахота.>$B$BГлупость какая…$B$BВы тут с роботом хорошо потрудились. Даже врасплох меня застали. Я и не знал, что эта девчонка такая…$B$B<Лорд Болотная Пахота крутит пальцем у виска.>$B$BОсобенная…$B$BЛадно, не пересчитывать же перья дареному гиппогрифу, я прав?$B$BДумаю, да.$B$BЧто ж, вот вам на мороженое.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с лордом Болотной Пахотой в крепости Ветрорезов в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (25729,'Предатель Геренцо','<ГНМ-передатчик громко жужжит.>$B$BЭй, $n! Ты здесь? Я тут да карте вижу, что ты типа близко к водядому колесу возле Скалистого озера, да?$B$BЧую я, эти умники из Торговой компании заблокировали колесо. Оглядись-ка, что ли, пока ты там. Если дайдешь гнома-предателя по имени Геренцо Терминатрикс, дай ему как следует под зад от имеди моего и всего Гдомрегада! Я тебе хорошо заплачу!','Убейте Геренцо Терминатрикса.','Ты газбегешься с гоблинами?','Профессор Закзак Атвертук','Ты убиваешь усегдно! Пгевосходно!','Профессор Закзак Атвертук') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Предатель Геренцо',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<ГНМ-передатчик громко жужжит.>$B$BЭй, $n! Ты здесь? Я тут да карте вижу, что ты типа близко к водядому колесу возле Скалистого озера, да?$B$BЧую я, эти умники из Торговой компании заблокировали колесо. Оглядись-ка, что ли, пока ты там. Если дайдешь гнома-предателя по имени Геренцо Терминатрикс, дай ему как следует под зад от имеди моего и всего Гдомрегада! Я тебе хорошо заплачу!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Геренцо Терминатрикса.',`objectives_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Ты газбегешься с гоблинами?',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Профессор Закзак Атвертук',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Ты убиваешь усегдно! Пгевосходно!',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Профессор Закзак Атвертук',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25730,'БЕРЕГИСЬ РИФОГРЫЗА!','По многочисленным просьбам населения, не желающего достаться на обед огромной рыбе, купание в Скалистом озере ЗАПРЕЩЕНО! Кто-то запустил в озеро огромную дворфоядную рыбу.$B$BНастоятельно рекомендуется не приближаться к озеру, но если вы герой и к тому же не один, а с друзьями, то сделайте любезность – убейте проклятую тварь! Может, я тогда хоть порыбачить смогу.$B$BЕсли вы и правда сумеете это сделать, зайдите ко мне в крепость Ветрорезов за наградой.$B$BСтарик Железный Козел','Убейте Рифогрыза и возьмите в качестве доказательства огромный зуб Рифогрыза.','Захлебнись я пивом! Ты и правда прикончил тварюгу? Что же, обещания надо выполнять! Вот твоя награда!','О, это ты прикончил тварь?','Принесите огромный зуб Рифогрыза старику Железному Козлу в крепость Ветрорезов в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','БЕРЕГИСЬ РИФОГРЫЗА!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','По многочисленным просьбам населения, не желающего достаться на обед огромной рыбе, купание в Скалистом озере ЗАПРЕЩЕНО! Кто-то запустил в озеро огромную дворфоядную рыбу.$B$BНастоятельно рекомендуется не приближаться к озеру, но если вы герой и к тому же не один, а с друзьями, то сделайте любезность – убейте проклятую тварь! Может, я тогда хоть порыбачить смогу.$B$BЕсли вы и правда сумеете это сделать, зайдите ко мне в крепость Ветрорезов за наградой.$B$BСтарик Железный Козел',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Рифогрыза и возьмите в качестве доказательства огромный зуб Рифогрыза.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Захлебнись я пивом! Ты и правда прикончил тварюгу? Что же, обещания надо выполнять! Вот твоя награда!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','О, это ты прикончил тварь?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите огромный зуб Рифогрыза старику Железному Козлу в крепость Ветрорезов в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (25732,'Игра в кости','Ура!$B$BМы завалили Костеглода, и блестяшка у меня!$B$BЭто хорошие новости.$B$BТеперь плохие: чертова безделушка проклята – любой, кто ее коснется, превращается в скелет.$B$BПроклятые пираты сказали, что король жаблинов знает, как снять заклятие.$B$BЯ не могу шагу ступить с этого рифа, иначе буду проклят навеки.$B$BИ это тоже плохая новость.','Бадд просит вас забрать крушитель олова у короля Гурбоггла на шельфе Гурбоггла.','Что, и все?$B$BИ как же этим можно снять... постой-ка...','Поговорите с Баддом на Рифе Скелетов в лесу Келп’тар.','Подойди, возьми!','Король Гурбоггл') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Игра в кости',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ура!$B$BМы завалили Костеглода, и блестяшка у меня!$B$BЭто хорошие новости.$B$BТеперь плохие: чертова безделушка проклята – любой, кто ее коснется, превращается в скелет.$B$BПроклятые пираты сказали, что король жаблинов знает, как снять заклятие.$B$BЯ не могу шагу ступить с этого рифа, иначе буду проклят навеки.$B$BИ это тоже плохая новость.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Бадд просит вас забрать крушитель олова у короля Гурбоггла на шельфе Гурбоггла.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что, и все?$B$BИ как же этим можно снять... постой-ка...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Баддом на Рифе Скелетов в лесу Келп’тар.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Подойди, возьми!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Король Гурбоггл',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25733,'Вон из моей пещеры!','Убейте 7 пещерных ловцов и 7 ловцов-кровопийц.','Отлично. Подозреваю, что твари могли отложить где-то в пещере яйца, но это мы уж как-нибудь переживем.','Вернитесь к Форбе Крепкой Стамеске на привал Крепкой Стамески, что в Болотине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вон из моей пещеры!',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 7 пещерных ловцов и 7 ловцов-кровопийц.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично. Подозреваю, что твари могли отложить где-то в пещере яйца, но это мы уж как-нибудь переживем.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Форбе Крепкой Стамеске на привал Крепкой Стамески, что в Болотине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25734,'Дно пещеры Тельгена','Вроде голова у меня кружиться перестала, так что скоро смогу провести последнюю серию замеров. А к тебе у меня осталась одна просьба.$B$BВ глубине пещеры Тельгена я установил сейсмограф, чтобы записать любые колебания почвы. Если после Катаклизма под землей продолжали происходить какие-то процессы, сейсмограф все покажет.$B$BОн установлен на самом дне пещеры; найди его и забери запись.','Заберите сейсмические записи Тельгена из пещеры Тельгена.','Чудненько, дружище. Это все, что нам нужно.','Ну-ка, что у нас там?','Вернитесь к геодезисту Турдану на привал Крепкой Стамески, что в Болотине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дно пещеры Тельгена',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вроде голова у меня кружиться перестала, так что скоро смогу провести последнюю серию замеров. А к тебе у меня осталась одна просьба.$B$BВ глубине пещеры Тельгена я установил сейсмограф, чтобы записать любые колебания почвы. Если после Катаклизма под землей продолжали происходить какие-то процессы, сейсмограф все покажет.$B$BОн установлен на самом дне пещеры; найди его и забери запись.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заберите сейсмические записи Тельгена из пещеры Тельгена.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Чудненько, дружище. Это все, что нам нужно.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну-ка, что у нас там?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к геодезисту Турдану на привал Крепкой Стамески, что в Болотине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25735,'Огневитовая руда','Пещера Тельгена – особое место, настоящее чудо природы. Единственный в мире источник огневита!$B$BЭто очень редкий, очень ценный минерал, который, кроме всего прочего, взрывается на ура. Если ударить стальной киркой, то там такой фейерверк начнется, что любой гоблин удавится от зависти.$B$BК счастью, я изобрел специальную искроустойчивую кирку. Я тебе ее одолжу. Принеси мне немного огневитовой руды, а я поделюсь с тобой прибылью от ее продажи.','Добудьте 8 кусков огневитовой руды.','Великолепно! Обожаю, обожаю эту руду.$B$BТебе, кстати, повезло, что кирку не уронил. Когда я в предыдущий раз послал одного в пещеру, он умудрился тыльной стороной по полу треснуть. А эта сторона у кирки, понимаешь ли, не искроустойчивая.','Смотрю, у тебя все части тела вроде на месте.','Вернитесь к Дунлору Мраморной Бороде на привал Крепкой Стамески, что в Болотине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Огневитовая руда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пещера Тельгена – особое место, настоящее чудо природы. Единственный в мире источник огневита!$B$BЭто очень редкий, очень ценный минерал, который, кроме всего прочего, взрывается на ура. Если ударить стальной киркой, то там такой фейерверк начнется, что любой гоблин удавится от зависти.$B$BК счастью, я изобрел специальную искроустойчивую кирку. Я тебе ее одолжу. Принеси мне немного огневитовой руды, а я поделюсь с тобой прибылью от ее продажи.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 8 кусков огневитовой руды.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Великолепно! Обожаю, обожаю эту руду.$B$BТебе, кстати, повезло, что кирку не уронил. Когда я в предыдущий раз послал одного в пещеру, он умудрился тыльной стороной по полу треснуть. А эта сторона у кирки, понимаешь ли, не искроустойчивая.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Смотрю, у тебя все части тела вроде на месте.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дунлору Мраморной Бороде на привал Крепкой Стамески, что в Болотине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25736,'Центр приливной волны','От огромного элементаля, напавшего на вас, осталась только кипящая водяная сфера, которая так и норовит вырваться из рук.$B$BФорба, наверное, будет рада увидеть доказательство того, что вы отвели от лагеря еще одну напасть.','Отнесите центр приливной волны Форбе Крепкой Стамеске.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Центр приливной волны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','От огромного элементаля, напавшего на вас, осталась только кипящая водяная сфера, которая так и норовит вырваться из рук.$B$BФорба, наверное, будет рада увидеть доказательство того, что вы отвели от лагеря еще одну напасть.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите центр приливной волны Форбе Крепкой Стамеске.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25737,'Радушный прием','Судя по тому, что я узнал о водяных гоблинах, это должно сработать.$B$BЯ смастерил ожерелье из спертых тобой акульих зубов. Это не просто красивая безделушка, это еще и эпитафия Костеглоду. Черт знает, сколько жаблинов сожрал живьем этот монстр.$B$BПредложи ожерелье предводителю жаблинов. В обмен я хочу получить артефакт, называемый крушитель олова.$B$BИ не мешкай, $gмалый:родная;. Я уже соскучился по своему телу...','Обратитесь к королю Гурбогглу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Радушный прием',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Судя по тому, что я узнал о водяных гоблинах, это должно сработать.$B$BЯ смастерил ожерелье из спертых тобой акульих зубов. Это не просто красивая безделушка, это еще и эпитафия Костеглоду. Черт знает, сколько жаблинов сожрал живьем этот монстр.$B$BПредложи ожерелье предводителю жаблинов. В обмен я хочу получить артефакт, называемый крушитель олова.$B$BИ не мешкай, $gмалый:родная;. Я уже соскучился по своему телу...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обратитесь к королю Гурбогглу.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25738,'Кое на ком природа отдыхает','<Гурбоггл изучает ожерелье из зубов Костеглода.>$B$BНедурно, |3-6($r), если, конечно, это не липа. Я все же пошлю одного из своих ребят проверить, не вешаешь ли ты мне лапшу на жабры.$B$BА пока суть да дело, ты мне окажешь услугу, ведь такая безделушка отнюдь не стоит крушителя олова!$B$BМой кузен Жабрингл давно метит на мой трон. Он глуп как коралл, но все же опасен.$B$BСведи с ним счеты – тогда и поговорим.','Король Гурбоггл поручил вам убить Жабрингла на шельфе Гурбоггла.','Обратитесь к королю Гурбогглу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кое на ком природа отдыхает',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Гурбоггл изучает ожерелье из зубов Костеглода.>$B$BНедурно, |3-6($r), если, конечно, это не липа. Я все же пошлю одного из своих ребят проверить, не вешаешь ли ты мне лапшу на жабры.$B$BА пока суть да дело, ты мне окажешь услугу, ведь такая безделушка отнюдь не стоит крушителя олова!$B$BМой кузен Жабрингл давно метит на мой трон. Он глуп как коралл, но все же опасен.$B$BСведи с ним счеты – тогда и поговорим.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Король Гурбоггл поручил вам убить Жабрингла на шельфе Гурбоггла.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Обратитесь к королю Гурбогглу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25739,'Не Орда, так...','Убейте королеву Силит.','<Капитан Косак едва улыбается.>$B$BНе беспокойся за меня. Если королева пауков убита, значит, все будет хорошо.$B$Bребята из подкрепления смогут дойти.','Вернитесь к капитану Северной Стражи Косаку в крепость Ветрорезов в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Не Орда, так...',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте королеву Силит.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Капитан Косак едва улыбается.>$B$BНе беспокойся за меня. Если королева пауков убита, значит, все будет хорошо.$B$Bребята из подкрепления смогут дойти.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Северной Стражи Косаку в крепость Ветрорезов в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25741,'Подготовка на будущее','Соберите 10 ядовитых желез моховых пауков.','Вернитесь к Алитии Болотной Пахоте в крепость Ветрорезов в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подготовка на будущее',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 ядовитых желез моховых пауков.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Алитии Болотной Пахоте в крепость Ветрорезов в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25742,'Опять двадцать пять!','Сделка есть сделка.$B$BДарю тебе, $gнезнакомец:незнакомка;, единственный и неповторимый крушитель олова.$B$BМожешь подойти и принять этот бесценный дар.$B$BНеопытному взору может показаться, что это всего лишь незамысловатый молот, но наверняка в нем много скрытых свойств, которые проявятся только в подходящей ситуации.$B$BБереги это сокровище, $gнезнакомец:незнакомка;. Он пребывает в нашей монаршей собственности уже долгие... ну... дни!','Доставьте крушитель олова Харрисону на Проклятый риф.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Опять двадцать пять!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сделка есть сделка.$B$BДарю тебе, $gнезнакомец:незнакомка;, единственный и неповторимый крушитель олова.$B$BМожешь подойти и принять этот бесценный дар.$B$BНеопытному взору может показаться, что это всего лишь незамысловатый молот, но наверняка в нем много скрытых свойств, которые проявятся только в подходящей ситуации.$B$BБереги это сокровище, $gнезнакомец:незнакомка;. Он пребывает в нашей монаршей собственности уже долгие... ну... дни!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте крушитель олова Харрисону на Проклятый риф.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25743,'Вот ведь незадача','Какое-то ни шиша не волшебное избавление от проклятья! Это же просто молоток!$B$BМожет я и не в себе, но и не полный идиот!$B$BПосле всего, что мне пришлось пережить, чтобы получить блестяшку, я не собираюсь ее ломать!$B$B<На мгновение Бадд умолкает в задумчивости.> $B$BНо это значит, что я застряну здесь навечно...$B$BА я только выучился ходить под парусом, представляешь.$B$BО-о-ох... Выбор не из легких.$B$BЛадно, просто положу блестяшку и отвернусь...','Воспользуйтесь крушителем олова, чтобы разбить оловянного пророка.','Эх, а как было бы...','Побеседуйте с Баддом на Рифе Скелетов в лесу Келп’тар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вот ведь незадача',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Какое-то ни шиша не волшебное избавление от проклятья! Это же просто молоток!$B$BМожет я и не в себе, но и не полный идиот!$B$BПосле всего, что мне пришлось пережить, чтобы получить блестяшку, я не собираюсь ее ломать!$B$B<На мгновение Бадд умолкает в задумчивости.> $B$BНо это значит, что я застряну здесь навечно...$B$BА я только выучился ходить под парусом, представляешь.$B$BО-о-ох... Выбор не из легких.$B$BЛадно, просто положу блестяшку и отвернусь...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь крушителем олова, чтобы разбить оловянного пророка.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Эх, а как было бы...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Побеседуйте с Баддом на Рифе Скелетов в лесу Келп’тар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (25744,'Переговоры','$n, ты отлично $gпоказал:показала; себя в обороне гоночной баржи! Мне пригодится твоя помощь еще в одном дельце.$B$BЯ отправил Краззла Шустреца и Кравела Углеборода на северо-восток вести переговоры с уцелевшими кентаврами. Утес Треснувшего Копыта, где они обитают, прямо-таки сочится нефтью!$B$BУверен, эти немытые полукони понятия не имеют о том, что сидят на куче денег, и мы сумеем выторговать право качать черное золото за бесценок. Однако мне будет спокойнее, если вести переговоры будешь ты.$B$BЧто скажешь?','Поговорите с Краззлом Шустрецом на Утесе Треснувшего Копыта в Тысяче Игл.','<Глаза Краззла заблестели.>$B$BЯ отправил Кравела Углеборода договариваться с одним из вожаков кентавров, но теперь, когда ты тут, мы выцыганим право качать их нефть как пить дать!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Переговоры',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, ты отлично $gпоказал:показала; себя в обороне гоночной баржи! Мне пригодится твоя помощь еще в одном дельце.$B$BЯ отправил Краззла Шустреца и Кравела Углеборода на северо-восток вести переговоры с уцелевшими кентаврами. Утес Треснувшего Копыта, где они обитают, прямо-таки сочится нефтью!$B$BУверен, эти немытые полукони понятия не имеют о том, что сидят на куче денег, и мы сумеем выторговать право качать черное золото за бесценок. Однако мне будет спокойнее, если вести переговоры будешь ты.$B$BЧто скажешь?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Краззлом Шустрецом на Утесе Треснувшего Копыта в Тысяче Игл.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Глаза Краззла заблестели.>$B$BЯ отправил Кравела Углеборода договариваться с одним из вожаков кентавров, но теперь, когда ты тут, мы выцыганим право качать их нефть как пить дать!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (25745,'Переговоры','$n, ты отлично $gпоказал:показала; себя в обороне гоночной баржи! Мне пригодится твоя помощь еще в одном дельце.$B$BЯ отправил Ризнека и начальника трассы Зерина на северо-восток вести переговоры с уцелевшими кентаврами. Утес Треснувшего Копыта, где они обитают, прямо-таки сочится нефтью!$B$BУверен, эти немытые полукони понятия не имеют о том, что сидят на куче денег, и мы сумеем выторговать право качать черное золото за бесценок. Однако мне будет спокойнее, если вести переговоры будешь ты.$B$BЧто скажешь?','Поговорите с Ризнеком на Утесе Треснувшего Копыта в Тысяче Игл.','<Глаза Ризнека заблестели.>$B$BЯ отправил начальника трассы Зерина договариваться с одним из вожаков кентавров, но теперь, когда ты тут, мы выцыганим право качать их нефть как пить дать!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Переговоры',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, ты отлично $gпоказал:показала; себя в обороне гоночной баржи! Мне пригодится твоя помощь еще в одном дельце.$B$BЯ отправил Ризнека и начальника трассы Зерина на северо-восток вести переговоры с уцелевшими кентаврами. Утес Треснувшего Копыта, где они обитают, прямо-таки сочится нефтью!$B$BУверен, эти немытые полукони понятия не имеют о том, что сидят на куче денег, и мы сумеем выторговать право качать черное золото за бесценок. Однако мне будет спокойнее, если вести переговоры будешь ты.$B$BЧто скажешь?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Ризнеком на Утесе Треснувшего Копыта в Тысяче Игл.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Глаза Ризнека заблестели.>$B$BЯ отправил начальника трассы Зерина договариваться с одним из вожаков кентавров, но теперь, когда ты тут, мы выцыганим право качать их нефть как пить дать!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25746,'Род Сетрии','Для начала нужно истребить порождения Сетрии. Это место просто кишит ими.$B$BДавай уничтожим местных драконидов, чтобы потом о них голова не болела.','Убейте 12 приспешников Сетрии: сумеречных драконидов и/или сумеречных драконидов-бронников.','Молодчина.$B$BТы прекрасно справляешься.','Вернитесь к Тизали Вороне в Гнездо Сетрии на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Род Сетрии',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Для начала нужно истребить порождения Сетрии. Это место просто кишит ими.$B$BДавай уничтожим местных драконидов, чтобы потом о них голова не болела.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 приспешников Сетрии: сумеречных драконидов и/или сумеречных драконидов-бронников.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Молодчина.$B$BТы прекрасно справляешься.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тизали Вороне в Гнездо Сетрии на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25747,'Взгляд в будущее','После твоего рассказа адмирал решил устроить форпост под западной террасой. Он планирует нанести оттуда удар по нагам.$B$BТы $gдолжен:должна; немедленно отправиться к нему и рассказать все, что $gвидел:видела;. Нас слишком мало, и страшно подумать, к чему приведет безрассудная атака.$B$BВозьми моего морского конька. Он знает дорогу.','Найдите адмирала Дворека под южной террасой в Руинах Вайш\'ира и поговорите с ним.$B$BВоспользуйтесь морским коньком Валорен Говорящей с волнами, чтобы быстро добраться до форпоста.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Взгляд в будущее',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','После твоего рассказа адмирал решил устроить форпост под западной террасой. Он планирует нанести оттуда удар по нагам.$B$BТы $gдолжен:должна; немедленно отправиться к нему и рассказать все, что $gвидел:видела;. Нас слишком мало, и страшно подумать, к чему приведет безрассудная атака.$B$BВозьми моего морского конька. Он знает дорогу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите адмирала Дворека под южной террасой в Руинах Вайш\'ира и поговорите с ним.$B$BВоспользуйтесь морским коньком Валорен Говорящей с волнами, чтобы быстро добраться до форпоста.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25748,'Ясные цели','Понятно. Да, это скверные новости, но я не исключал такую возможность. Было бы рискованно действовать, не зная точной численности наг, но именно поэтому мы и создали этот форпост.$B$BСкажу тебе прямо, |3-6($c), – если внезапно не напасть на наг, они сами к нам явятся. А у нас нет ни должных укреплений, ни достаточного количества солдат, так что это не вариант.$B$BНам нужно выиграть время. Можешь избавиться от нескольких наг под дальней южной террасой?','Убейте 10 наг на нижнем уровне под юго-западной террасой.','Похоже, численность наг на юге еще выше, чем мы думали. Придется действовать быстро.','Вернитесь к адмиралу Двореку на южную террасу в Руинах Вайш\'ира.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ясные цели',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Понятно. Да, это скверные новости, но я не исключал такую возможность. Было бы рискованно действовать, не зная точной численности наг, но именно поэтому мы и создали этот форпост.$B$BСкажу тебе прямо, |3-6($c), – если внезапно не напасть на наг, они сами к нам явятся. А у нас нет ни должных укреплений, ни достаточного количества солдат, так что это не вариант.$B$BНам нужно выиграть время. Можешь избавиться от нескольких наг под дальней южной террасой?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 наг на нижнем уровне под юго-западной террасой.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Похоже, численность наг на юге еще выше, чем мы думали. Придется действовать быстро.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к адмиралу Двореку на южную террасу в Руинах Вайш\'ира.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25749,'Не так уж безоружны','Я невольно слышал твой разговор с адмиралом. Знаю – то, что мы делаем, похоже на безумие, но другого выхода нет. От нас зависит жизнь всех обитателей пещеры.$B$BЯ разместил вокруг нескольких часовых, но наг-разведчиков так много, что наши боеприпасы тают на глазах. Если ты пополнишь боезапас дозорных, мы выиграем время.','Принесите 8 связок арбалетных болтов дозорным Альянса, расставленным на уступах под южной террасой.','Ты одна из немногих, на кого можно полностью положиться. Если бы все мои бойцы были такими, как ты!','Вернитесь к капитану Тейлору под южную террасу в Руинах Вайш\'ира.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Не так уж безоружны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я невольно слышал твой разговор с адмиралом. Знаю – то, что мы делаем, похоже на безумие, но другого выхода нет. От нас зависит жизнь всех обитателей пещеры.$B$BЯ разместил вокруг нескольких часовых, но наг-разведчиков так много, что наши боеприпасы тают на глазах. Если ты пополнишь боезапас дозорных, мы выиграем время.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 8 связок арбалетных болтов дозорным Альянса, расставленным на уступах под южной террасой.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты одна из немногих, на кого можно полностью положиться. Если бы все мои бойцы были такими, как ты!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Тейлору под южную террасу в Руинах Вайш\'ира.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25750,'Необычное поручение','Хм, ты $gзаметил:заметила;, как неодобрительно адмирал посмотрел на меня, и $gрешил:решила; помочь? Я уж и не надеюсь заставить его понять, что среди этих руин можно найти кое-что полезное.$B$BВот ты, как мне кажется, совсем другое дело. Посмотри-ка, подобные скрижали встречаются в окрестных развалинах, и я уже приготовила специальный набор для копирования надписей с этих каменных плит. Возьмешься за работу?','Скопируйте надписи с 4 скрижалей высокорожденных.','Вернитесь к Ливии Пробуждающей, находящейся под южной террасой в Руинах Вайш\'ира.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Необычное поручение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хм, ты $gзаметил:заметила;, как неодобрительно адмирал посмотрел на меня, и $gрешил:решила; помочь? Я уж и не надеюсь заставить его понять, что среди этих руин можно найти кое-что полезное.$B$BВот ты, как мне кажется, совсем другое дело. Посмотри-ка, подобные скрижали встречаются в окрестных развалинах, и я уже приготовила специальный набор для копирования надписей с этих каменных плит. Возьмешься за работу?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Скопируйте надписи с 4 скрижалей высокорожденных.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ливии Пробуждающей, находящейся под южной террасой в Руинах Вайш\'ира.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25751,'Внезапное озарение','Привет! А я все работаю-работаю – помогаю адмиралу. У него большие планы – хочет, чтобы все тут взлетело на воздух! Э-э... или на воду? Да, так логичнее.$B$BНо чтобы все взорвать, нужна ВЗРЫВЧАТКА. А ее у меня нет. Такое горе, такое горе...$B$BНо я включил мозг – и решение найдено! Шишки на свисающих с руин водорослях наполнены весьма нестабильным газом. Принесешь несколько? Ну, пожа-алуйста!','Соберите 8 раздувшихся шишек водорослей, висящих под юго-западной террасой.','Тик-так, тик-так! Время поджимает, адмирал нажимает... Ах, полжизни – за лабораторию!','Вернитесь к инженеру Мегагексу под южную террасу в Руинах Вайш\'ира.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Внезапное озарение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Привет! А я все работаю-работаю – помогаю адмиралу. У него большие планы – хочет, чтобы все тут взлетело на воздух! Э-э... или на воду? Да, так логичнее.$B$BНо чтобы все взорвать, нужна ВЗРЫВЧАТКА. А ее у меня нет. Такое горе, такое горе...$B$BНо я включил мозг – и решение найдено! Шишки на свисающих с руин водорослях наполнены весьма нестабильным газом. Принесешь несколько? Ну, пожа-алуйста!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 раздувшихся шишек водорослей, висящих под юго-западной террасой.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тик-так, тик-так! Время поджимает, адмирал нажимает... Ах, полжизни – за лабораторию!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к инженеру Мегагексу под южную террасу в Руинах Вайш\'ира.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25752,'Медлить нельзя','Подготовка завершена, пора в бой.$B$BТы вот что – держись крепче на своем морском коньке, пока мы атакуем. Тот, кто останется один на один в воде с нагами, вряд ли сможет уплыть от них.$B$BУбей как можно больше врагов. Встретимся на верхней террасе, как только у нас закончится взрывчатка. Надеюсь, к тому времени наг останется мало, и мы добьем их сами.','Ты прекрасно проявила себя в деле! Ты перебила множество наг, но их оказалось больше, чем мы полагали. Большинство наших бойцов было вовлечено в затяжные бои с этим несметным полчищем.$B$BНужно удерживать данную позицию как можно дольше, чтобы выиграть время. Надеюсь, хоть кто-нибудь из наших прорвется к месту встречи.','Поговорите с адмиралом Двореком на террасе Нар\'шолы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Медлить нельзя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Подготовка завершена, пора в бой.$B$BТы вот что – держись крепче на своем морском коньке, пока мы атакуем. Тот, кто останется один на один в воде с нагами, вряд ли сможет уплыть от них.$B$BУбей как можно больше врагов. Встретимся на верхней террасе, как только у нас закончится взрывчатка. Надеюсь, к тому времени наг останется мало, и мы добьем их сами.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты прекрасно проявила себя в деле! Ты перебила множество наг, но их оказалось больше, чем мы полагали. Большинство наших бойцов было вовлечено в затяжные бои с этим несметным полчищем.$B$BНужно удерживать данную позицию как можно дольше, чтобы выиграть время. Надеюсь, хоть кто-нибудь из наших прорвется к месту встречи.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с адмиралом Двореком на террасе Нар\'шолы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25753,'Повержены, но не забыты','Какая катастрофа! Многие наши бойцы ранены и не могут добраться до места встречи.$B$BДолго нам эту позицию не удержать. Необходимо спасти как можно больше воинов, пока не явились наги. Отправляйся на юго-запад и сделай все, что в твоих силах.$B$BНаши долго не продержатся. Пожалуйста, поторопись!','Спасите 6 раненых добровольцев.','Спасибо тебе. Правда.$B$BНужно выдвигаться как можно скорее. А мы с тобой скоро встретимся на форпосте, я уверен.','Вернитесь к капитану Тейлору на террасу Нар\'шолы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Повержены, но не забыты',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Какая катастрофа! Многие наши бойцы ранены и не могут добраться до места встречи.$B$BДолго нам эту позицию не удержать. Необходимо спасти как можно больше воинов, пока не явились наги. Отправляйся на юго-запад и сделай все, что в твоих силах.$B$BНаши долго не продержатся. Пожалуйста, поторопись!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Спасите 6 раненых добровольцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо тебе. Правда.$B$BНужно выдвигаться как можно скорее. А мы с тобой скоро встретимся на форпосте, я уверен.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Тейлору на террасу Нар\'шолы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25754,'Подсчет','Злобные твари... а их гарпуны... страшная штука.$B$B<Адмирал морщится, коснувшись раны в боку.>$B$BНо мы будем держаться. Сколько сможем. Любой ценой. Мне нужен тот, кто пойдет на разведку и подсчитает, сколько их там осталось. Важно понять, скольких мы уже перебили.$B$BОдна из самых больших групп находится в северо-западной части круглой террасы, другая – в чуть дальше к северу в маленьком тоннеле, а еще одна – на среднем уровне руин.$B$BВозьмешься за это?','Отправляйтесь на разведку в северо-западную часть круглой террасы и в туннель на севере. Они расположены на террасе Нар\'шолы на среднем уровне руин.','Вернитесь к адмиралу Двореку на террасу Нар\'шолы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подсчет',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Злобные твари... а их гарпуны... страшная штука.$B$B<Адмирал морщится, коснувшись раны в боку.>$B$BНо мы будем держаться. Сколько сможем. Любой ценой. Мне нужен тот, кто пойдет на разведку и подсчитает, сколько их там осталось. Важно понять, скольких мы уже перебили.$B$BОдна из самых больших групп находится в северо-западной части круглой террасы, другая – в чуть дальше к северу в маленьком тоннеле, а еще одна – на среднем уровне руин.$B$BВозьмешься за это?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь на разведку в северо-западную часть круглой террасы и в туннель на севере. Они расположены на террасе Нар\'шолы на среднем уровне руин.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к адмиралу Двореку на террасу Нар\'шолы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25755,'Видения прошлого: битва на гряде Бейл\'аран','Понимаю, что прошу слишком многого и сейчас совсем не время для такой просьбы – ведь на счету каждый воин. Но мне нужна твоя помощь.$B$BЯ позабочусь о солдатах... а ты отправляйся на запад и разыщи поле боя с квалдирским генералом, о котором ты мне $gговорил:говорила;. Там ты больше узнаешь о деяниях Воительницы. Шестое чувство подсказывает мне, что ключ к победе над нагами скрывается в прошлом, и он как-то связан с Воительницей.$B$BИ, пожалуйста, поторопись: я постараюсь выиграть для тебя время, но силы мои не беспредельны.','Отправляйтесь на место гибели квалдирского генерала и с помощью сломанного клинка Воительницы призовите видение из прошлого, чтобы узнать продолжение истории о Воительнице.','Вернулась! Как вовремя! Еще немного – и мы бы их не удержали.$B$BАртефакт? Интересно, против наг он действует? Хотя сначала его хорошо бы найти... И мы обязательно этим займемся, но не сейчас.$B$BПока займемся решением безотлагательных вопросов. А как только представится возможность, сразу приступим к поискам.','Поговорите с говорящей с волнами Валорен на террасе Нар\'шолы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Видения прошлого: битва на гряде Бейл\'аран',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Понимаю, что прошу слишком многого и сейчас совсем не время для такой просьбы – ведь на счету каждый воин. Но мне нужна твоя помощь.$B$BЯ позабочусь о солдатах... а ты отправляйся на запад и разыщи поле боя с квалдирским генералом, о котором ты мне $gговорил:говорила;. Там ты больше узнаешь о деяниях Воительницы. Шестое чувство подсказывает мне, что ключ к победе над нагами скрывается в прошлом, и он как-то связан с Воительницей.$B$BИ, пожалуйста, поторопись: я постараюсь выиграть для тебя время, но силы мои не беспредельны.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь на место гибели квалдирского генерала и с помощью сломанного клинка Воительницы призовите видение из прошлого, чтобы узнать продолжение истории о Воительнице.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вернулась! Как вовремя! Еще немного – и мы бы их не удержали.$B$BАртефакт? Интересно, против наг он действует? Хотя сначала его хорошо бы найти... И мы обязательно этим займемся, но не сейчас.$B$BПока займемся решением безотлагательных вопросов. А как только представится возможность, сразу приступим к поискам.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с говорящей с волнами Валорен на террасе Нар\'шолы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (25756,'Хватай Зерина!','Если мы хотим получить права на добычу нефти, нужно узнать, что кентаврам предлагает Орда. Наше предложение непременно должно быть выгоднее!$B$BПосол Орды, начальник трассы Зерин, сейчас ведет переговоры с одним из ханов кентавров. Сходи-ка убеди его отдать нам предложение Орды.$B$BУбивать его не нужно, мы же не звери какие! Так, помни ему бока маленько.','Раздобудьте предложение Орды.','Что?! Да откуда у них столько золота на такое баснословное предложение?$B$BНам не найти столько денег!','Раздобыл предложение Орды? Что там они обещают в обмен на право бурения?','Вернитесь к Краззлу Шустрецу на Утес Треснувшего Копыта в Тысяче Игл.','Отбери у него предложение Орды!','Начальник трассы Зерин') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хватай Зерина!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если мы хотим получить права на добычу нефти, нужно узнать, что кентаврам предлагает Орда. Наше предложение непременно должно быть выгоднее!$B$BПосол Орды, начальник трассы Зерин, сейчас ведет переговоры с одним из ханов кентавров. Сходи-ка убеди его отдать нам предложение Орды.$B$BУбивать его не нужно, мы же не звери какие! Так, помни ему бока маленько.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте предложение Орды.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что?! Да откуда у них столько золота на такое баснословное предложение?$B$BНам не найти столько денег!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Раздобыл предложение Орды? Что там они обещают в обмен на право бурения?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Краззлу Шустрецу на Утес Треснувшего Копыта в Тысяче Игл.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Отбери у него предложение Орды!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Начальник трассы Зерин',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (25757,'Хватай Углеборода!','Если мы хотим получить права на добычу нефти, нужно узнать, что кентаврам предлагает Альянс. Наше предложение непременно должно быть выгоднее!$B$BПосол орды Кравел Углебород сейчас ведет переговоры с одним из ханов кентавров. Сходи-ка убеди его отдать нам предложение Альянса.$B$BУбивать его не нужно, мы же не звери какие! Так, помни ему бока маленько.','Раздобудьте предложение Альянса.','Что?! Да откуда у них столько золота на такое баснословное предложение?$B$BНам не найти столько денег!','Раздобыл предложение Альянса? Что там они обещают в обмен на право бурения?','Вернитесь к Ризнеку на Утес Треснувшего Копыта в Тысяче Игл.','Отбери у него предложение Альянса!','Кравел Углебород') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хватай Углеборода!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если мы хотим получить права на добычу нефти, нужно узнать, что кентаврам предлагает Альянс. Наше предложение непременно должно быть выгоднее!$B$BПосол орды Кравел Углебород сейчас ведет переговоры с одним из ханов кентавров. Сходи-ка убеди его отдать нам предложение Альянса.$B$BУбивать его не нужно, мы же не звери какие! Так, помни ему бока маленько.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте предложение Альянса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что?! Да откуда у них столько золота на такое баснословное предложение?$B$BНам не найти столько денег!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Раздобыл предложение Альянса? Что там они обещают в обмен на право бурения?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ризнеку на Утес Треснувшего Копыта в Тысяче Игл.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Отбери у него предложение Альянса!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Кравел Углебород',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25758,'Изъян в броне','$GВидел:Видела;, что они тут вытворяют? Они заковывают драконидов в латы. По-моему, этим увлекался Смертокрыл.$B$BЭти сумеречные берсерки считают, что они станут непобедимыми по завершении облачения. В этой броне должен быть какой-то изъян!$B$BСбегай туда и принеси несколько образцов брони, которую намеревается использовать культ Сумеречного Молота. Изучив их, мы сможем узнать, как победить этих бронированных чудовищ.','Соберите 8 сумеречных пластин для доспехов.','Посмотри на них. Эти руны вызывают у меня резь в глазах. Вот эта вот призвана выжигать плоть? Неужели это правда? Ох! Погоди-ка...$B$BЭти пластины должны врезаться прямо в тело, вызывая адскую боль!','Ты раздобыл несколько пластин? Пришлось ли тебе кого-то для этого прикончить?$B$BХочется верить, что да.','Отнесите пластины Тизали Вороне в Гнездо Сетрии на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Изъян в броне',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$GВидел:Видела;, что они тут вытворяют? Они заковывают драконидов в латы. По-моему, этим увлекался Смертокрыл.$B$BЭти сумеречные берсерки считают, что они станут непобедимыми по завершении облачения. В этой броне должен быть какой-то изъян!$B$BСбегай туда и принеси несколько образцов брони, которую намеревается использовать культ Сумеречного Молота. Изучив их, мы сможем узнать, как победить этих бронированных чудовищ.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 сумеречных пластин для доспехов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Посмотри на них. Эти руны вызывают у меня резь в глазах. Вот эта вот призвана выжигать плоть? Неужели это правда? Ох! Погоди-ка...$B$BЭти пластины должны врезаться прямо в тело, вызывая адскую боль!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты раздобыл несколько пластин? Пришлось ли тебе кого-то для этого прикончить?$B$BХочется верить, что да.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите пластины Тизали Вороне в Гнездо Сетрии на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25759,'Докопаться до истины','На месте разлома осталось это странное устройство – но что это такое?$B$BВозможно, в столице кто-нибудь сумеет разобраться.','Отнесите загадочное устройство в Оргриммар, Подгород, Луносвет или Громовой Утес и покажите его представителю Служителей Земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Докопаться до истины',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На месте разлома осталось это странное устройство – но что это такое?$B$BВозможно, в столице кто-нибудь сумеет разобраться.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите загадочное устройство в Оргриммар, Подгород, Луносвет или Громовой Утес и покажите его представителю Служителей Земли.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25760,'Видения прошлого: вторжение в Вайш\'ир','Тот осколок, который ты $gпринес:принесла;, принадлежал нагам. Я давно ищу подобный предмет, чтобы закончить особое заклинание – оно позволит нам заглянуть в недалекое прошлое.$B$BИтак, заклинание готово, но теперь нужно отнести этот клинок на место, где бывал его владелец. Отправляйся туда, где ты его $gнашел:нашла;.$B$BВозможно, теперь мы узнаем о намерениях наг – а может, даже нащупаем их слабые места.','Воспользуйтесь клинком воительницы Леди Наз\'жар на поле битвы возле юго-восточной окраины руин.','Воительница? Первый раз слышу.$B$BСудя по твоим рассказам, наг куда больше, чем думал адмирал. Возможно, мы узнаем что-нибудь еще, если найдем другие места, где бывала эта Воительница. Но теперь я уже начинаю опасаться за адмирала и его солдат. Нужно их предупредить.','Поговорите с говорящей с волнами Валорен в Руинах Вайш\'ира.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Видения прошлого: вторжение в Вайш\'ир',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тот осколок, который ты $gпринес:принесла;, принадлежал нагам. Я давно ищу подобный предмет, чтобы закончить особое заклинание – оно позволит нам заглянуть в недалекое прошлое.$B$BИтак, заклинание готово, но теперь нужно отнести этот клинок на место, где бывал его владелец. Отправляйся туда, где ты его $gнашел:нашла;.$B$BВозможно, теперь мы узнаем о намерениях наг – а может, даже нащупаем их слабые места.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь клинком воительницы Леди Наз\'жар на поле битвы возле юго-восточной окраины руин.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Воительница? Первый раз слышу.$B$BСудя по твоим рассказам, наг куда больше, чем думал адмирал. Возможно, мы узнаем что-нибудь еще, если найдем другие места, где бывала эта Воительница. Но теперь я уже начинаю опасаться за адмирала и его солдат. Нужно их предупредить.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с говорящей с волнами Валорен в Руинах Вайш\'ира.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25761,'Сорвать доспехи','Нужно остановить берсерков до того, как их полностью закуют в броню. Пока что они уязвимы, но тебе нужно будет раздвинуть пластины и ударить в скрывающуюся за ними плоть.$B$BВозьми мой кинжал и всади его между пластинами закованных в латы берсерков, чтобы сорвать с них доспехи.$B$BПосле того как они выйдут из оцепенения, тебя ждет жаркая битва. Просто продолжай срывать броню, чтобы остановить берсерков.','Воспользуйтесь кинжалом Тизали, чтобы разбудить и убить 3 сумеречных берсерков. Кинжал можно применять многократно, чтобы полностью сорвать доспех с берсерка.','Великолепно.$B$BТы все еще жива.','Вернитесь к Тизали Вороне в Гнезде Сетрии на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сорвать доспехи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нужно остановить берсерков до того, как их полностью закуют в броню. Пока что они уязвимы, но тебе нужно будет раздвинуть пластины и ударить в скрывающуюся за ними плоть.$B$BВозьми мой кинжал и всади его между пластинами закованных в латы берсерков, чтобы сорвать с них доспехи.$B$BПосле того как они выйдут из оцепенения, тебя ждет жаркая битва. Просто продолжай срывать броню, чтобы остановить берсерков.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь кинжалом Тизали, чтобы разбудить и убить 3 сумеречных берсерков. Кинжал можно применять многократно, чтобы полностью сорвать доспех с берсерка.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Великолепно.$B$BТы все еще жива.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тизали Вороне в Гнезде Сетрии на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (25762,'Древняя жаровня','Кто тут у нас? $R? Пришел выклянчить наши земли сладкими речами да обещаниями?$B$BМеня не проведешь. Не первый год живу – знаю, каково иметь дело с вашим братом. Но ханы больше не прислушиваются к старейшинам, как прежде.$B$BРаз уж ты здесь – будешь пользу приносить. Когда в эти земли хлынули воды, великий дух воды Акварий затушил древнюю жаровню в недрах Оплота Треснувшего Копыта.$B$BВозьми эту головню, зажги жаровню – и Акварий непременно покажется. Принеси мне священное пламя.','Разожгите древнюю жаровню и раздобудьте священное пламя.','Тебе, конечно, хотелось оказать мне услугу и тем самым втереться в доверие, но я под твою дудку плясать не собираюсь.$B$BЯ знаю, что грядет. Где море оказалось бессильно, великий дух ветра поразит тебя и твой народ за ваше бесконечное посягательство на стихии.$B$BПрочь с глаз моих!','Вернитесь к Небоступу Врактрису на Утес Треснувшего Копыта в Тысяче Игл.','Он затушил древнюю жаровню! У него священное пламя!','Акварий') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Древняя жаровня',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кто тут у нас? $R? Пришел выклянчить наши земли сладкими речами да обещаниями?$B$BМеня не проведешь. Не первый год живу – знаю, каково иметь дело с вашим братом. Но ханы больше не прислушиваются к старейшинам, как прежде.$B$BРаз уж ты здесь – будешь пользу приносить. Когда в эти земли хлынули воды, великий дух воды Акварий затушил древнюю жаровню в недрах Оплота Треснувшего Копыта.$B$BВозьми эту головню, зажги жаровню – и Акварий непременно покажется. Принеси мне священное пламя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разожгите древнюю жаровню и раздобудьте священное пламя.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебе, конечно, хотелось оказать мне услугу и тем самым втереться в доверие, но я под твою дудку плясать не собираюсь.$B$BЯ знаю, что грядет. Где море оказалось бессильно, великий дух ветра поразит тебя и твой народ за ваше бесконечное посягательство на стихии.$B$BПрочь с глаз моих!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Небоступу Врактрису на Утес Треснувшего Копыта в Тысяче Игл.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Он затушил древнюю жаровню! У него священное пламя!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Акварий',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (25763,'Кодекс теней','<Вычурная книга в сероватой обложке содержит сотни пергаментных страниц, испещренных текстом. Большая часть текста написана на языках, которые вам неизвестны. На замысловатых иллюстрациях изображены волшебники и даже целые здания, исчезающие в тенях.>$B$B<На многих рисунках – магические устройства, подобные тем, что вы видели вокруг лагеря. Вы приходите к выводу, что Сетрия что-то прячет с их помощью. Стоит рассказать об этом Тизали.>','Чем там они занимаются?$B$BЧто-то прячут? Так вот почему наши воздушные лазутчики не могут ничего разглядеть, несмотря на свое острое зрение.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кодекс теней',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Вычурная книга в сероватой обложке содержит сотни пергаментных страниц, испещренных текстом. Большая часть текста написана на языках, которые вам неизвестны. На замысловатых иллюстрациях изображены волшебники и даже целые здания, исчезающие в тенях.>$B$B<На многих рисунках – магические устройства, подобные тем, что вы видели вокруг лагеря. Вы приходите к выводу, что Сетрия что-то прячет с их помощью. Стоит рассказать об этом Тизали.>',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Чем там они занимаются?$B$BЧто-то прячут? Так вот почему наши воздушные лазутчики не могут ничего разглядеть, несмотря на свое острое зрение.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25764,'Охота за яйцами','Повелитель небес Омнурон попросил нас найти яйцо Авианы. Спорю на что угодно, что Сетрия спрятала его с помощью одного из своих маскировочных устройств, расставленных вокруг лагеря.$B$BОтключай эти устройства, одно за другим, пока не найдешь яйцо Авианы.$B$BКогда оно будет обнаружено, я позову остальных друидов. Защищай яйцо до тех пор, пока мы не будем готовы перенести его в безопасное место.$B$BНужно торопиться, $n!','Отключайте генераторы покрова теней до тех пор, пока не обнаружите яйцо Авианы. Затем охраняйте его до того момента, как друиды-вороны заберут яйцо в безопасное место.','Вернитесь к Тизали Вороне в Гнезде Сетрии на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота за яйцами',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Повелитель небес Омнурон попросил нас найти яйцо Авианы. Спорю на что угодно, что Сетрия спрятала его с помощью одного из своих маскировочных устройств, расставленных вокруг лагеря.$B$BОтключай эти устройства, одно за другим, пока не найдешь яйцо Авианы.$B$BКогда оно будет обнаружено, я позову остальных друидов. Защищай яйцо до тех пор, пока мы не будем готовы перенести его в безопасное место.$B$BНужно торопиться, $n!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отключайте генераторы покрова теней до тех пор, пока не обнаружите яйцо Авианы. Затем охраняйте его до того момента, как друиды-вороны заберут яйцо в безопасное место.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тизали Вороне в Гнезде Сетрии на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (25765,'Скажешь, что ты от Коко','Так тебя прислал Косак? Удивительно. Я думал, он уже давно погиб.$B$BНу что ж, раз ты смог прорваться через заставу, то определенно нам пригодишься.$B$BИтак, что ты знаешь об Орде? Что они делают? Куда направляются? Рассказывай все.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Скажешь, что ты от Коко',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так тебя прислал Косак? Удивительно. Я думал, он уже давно погиб.$B$BНу что ж, раз ты смог прорваться через заставу, то определенно нам пригодишься.$B$BИтак, что ты знаешь об Орде? Что они делают? Куда направляются? Рассказывай все.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25766,'Тайное наследие','Бушующие стихии раскололи землю, под ней, в самом сердце Когтистых гор, обнаружился секретный город высокорожденных.$B$BПрямо к юго-западу отсюда, за Сиширским каньоном, находятся руины Эльдре\'тара. В этих руинах таятся сокровища, которых десять тысяч лет не касались руки смертных!$B$BВозьми вот это устройство и используй его, если встретишь духов высокорожденных, населяющих руины. Оно... упокоит их души, а так же соберет важные данные, которые я потом внимательно изучу.','Используйте тюрьму высокорожденных, чтобы упокоить 5 духов высокорожденных.','Уверяю тебя, дурачок: те духи, которых ты поймал, обрели покой. Не обращай внимания на их протесты.','Вернитесь к чародею Валдуриану в крепость Ветрорезов в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тайное наследие',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Бушующие стихии раскололи землю, под ней, в самом сердце Когтистых гор, обнаружился секретный город высокорожденных.$B$BПрямо к юго-западу отсюда, за Сиширским каньоном, находятся руины Эльдре\'тара. В этих руинах таятся сокровища, которых десять тысяч лет не касались руки смертных!$B$BВозьми вот это устройство и используй его, если встретишь духов высокорожденных, населяющих руины. Оно... упокоит их души, а так же соберет важные данные, которые я потом внимательно изучу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте тюрьму высокорожденных, чтобы упокоить 5 духов высокорожденных.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Уверяю тебя, дурачок: те духи, которых ты поймал, обрели покой. Не обращай внимания на их протесты.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к чародею Валдуриану в крепость Ветрорезов в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25767,'В поисках воспоминаний','В результате великого катаклизма мы обнаружили под землей забытый город высокорожденных в Когтистых горах. Тебе нужно отправиться на юго-запад, к руинам Эльдре\'тара. Когда придешь, поищи там древние реликвии и принеси их мне для изучения, $n.$B$BИди же! А то чародей ждет.','Соберите 8 реликвий Эльдре\'тара.','Чудесно! Чародей Валдуриан будет очень доволен!','Вернитесь к неофиту Звездному Гребню в крепость Ветрорезов в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В поисках воспоминаний',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В результате великого катаклизма мы обнаружили под землей забытый город высокорожденных в Когтистых горах. Тебе нужно отправиться на юго-запад, к руинам Эльдре\'тара. Когда придешь, поищи там древние реликвии и принеси их мне для изучения, $n.$B$BИди же! А то чародей ждет.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 реликвий Эльдре\'тара.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Чудесно! Чародей Валдуриан будет очень доволен!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к неофиту Звездному Гребню в крепость Ветрорезов в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25768,'Сбрасывай бомбу: пост на Мутном озере!','Командир разведчиков Барус, который находится на посту у Туманного озера к северо-западу отсюда, заметил ордынскую бомбу. Кром\'гарский воздушный шар с прикрепленной к нему бомбой сейчас находится на новой гоблинской заправке у Туманного озера. Вот возможность для нас уничтожить эту штуку раз и навсегда.$B$BСобирайся, $n, и в путь! Командир разведчиков Барус ждет твоего прибытия на посту на Туманном озере.$B$BИ, $n, твое упорство – залог силы и крепости Альянса!$B$BДа осияет тебя слава!','Доложитесь командиру разведчиков Барусу на посту на Туманном озере в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сбрасывай бомбу: пост на Мутном озере!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Командир разведчиков Барус, который находится на посту у Туманного озера к северо-западу отсюда, заметил ордынскую бомбу. Кром\'гарский воздушный шар с прикрепленной к нему бомбой сейчас находится на новой гоблинской заправке у Туманного озера. Вот возможность для нас уничтожить эту штуку раз и навсегда.$B$BСобирайся, $n, и в путь! Командир разведчиков Барус ждет твоего прибытия на посту на Туманном озере.$B$BИ, $n, твое упорство – залог силы и крепости Альянса!$B$BДа осияет тебя слава!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доложитесь командиру разведчиков Барусу на посту на Туманном озере в Когтистых горах.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (25770,'Кати бочку!','Ладно. Нам надо доставить этот эль туда, куда надо, и поскорее!$B$BСтальгорн выслал топографическую экспедицию для оценки ущерба, нанесенного Болотине прорывом дамбы. Ее возглавляет Форба Крепкая Стамеска... и поверь мне, лучше не попадаться ей под горячую руку!$B$BЕсли притащишь ей эля, то это поможет уладить дело. Иди и отнеси ей это, и она, может, даже попросит тебя задержаться и сделать какую-нибудь работенку.','Доставьте эль горного пехотинца Форбе Крепкой Стамеске на привал Крепкой Стамески.','Ха! Приятно видеть, что эти тупые горные пехотинцы сообразили передать эль в руки настоящего мужчины, чтобы дело было сделано.$B$BДобро пожаловать в мою топографическую службу. Если ты не против помочь Стальгорну, взяв на себя работу несколько бесполезных, ленивых увальней, что смеют называть себя дворфами, то ты попал куда следует!','Да? Что у тебя за дело ко мне?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кати бочку!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ладно. Нам надо доставить этот эль туда, куда надо, и поскорее!$B$BСтальгорн выслал топографическую экспедицию для оценки ущерба, нанесенного Болотине прорывом дамбы. Ее возглавляет Форба Крепкая Стамеска... и поверь мне, лучше не попадаться ей под горячую руку!$B$BЕсли притащишь ей эля, то это поможет уладить дело. Иди и отнеси ей это, и она, может, даже попросит тебя задержаться и сделать какую-нибудь работенку.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте эль горного пехотинца Форбе Крепкой Стамеске на привал Крепкой Стамески.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ха! Приятно видеть, что эти тупые горные пехотинцы сообразили передать эль в руки настоящего мужчины, чтобы дело было сделано.$B$BДобро пожаловать в мою топографическую службу. Если ты не против помочь Стальгорну, взяв на себя работу несколько бесполезных, ленивых увальней, что смеют называть себя дворфами, то ты попал куда следует!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да? Что у тебя за дело ко мне?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (25771,'Дренейский хлам','<Вы видите сверкающий каменный осколок, и вам кажется, что он может представлять некоторую ценность для кого-то из Выжженных земель.>','Отнесите несовершенный фрагмент дренетиста Кум\'ише Коллекционеру в Выжженных землях.','Что там у тебя? Дренетист?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дренейский хлам',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Вы видите сверкающий каменный осколок, и вам кажется, что он может представлять некоторую ценность для кого-то из Выжженных земель.>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите несовершенный фрагмент дренетиста Кум\'ише Коллекционеру в Выжженных землях.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что там у тебя? Дренетист?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (25772,'Для коллекции Кум\'иши','<Вы видите какой-то сверкающий шар и понимаете, что для кого-то в Выжженных землях этот шар представляет большую ценность.>','Отнесите безупречную сферу из дренетиста Кум\'ише Коллекционеру в Выжженных землях.','Поразительно… Я не верил, что кому-то удастся найти еще одну такую сферу, но вот она здесь, у меня в руках!$B$BСпасибо, Лафроиг!$B$BЕсли найдешь еще – хотя это вряд ли, и тем не менее – сразу неси их сюда, а я уж найду, чем тебя отблагодарить.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Для коллекции Кум\'иши',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Вы видите какой-то сверкающий шар и понимаете, что для кого-то в Выжженных землях этот шар представляет большую ценность.>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите безупречную сферу из дренетиста Кум\'ише Коллекционеру в Выжженных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Поразительно… Я не верил, что кому-то удастся найти еще одну такую сферу, но вот она здесь, у меня в руках!$B$BСпасибо, Лафроиг!$B$BЕсли найдешь еще – хотя это вряд ли, и тем не менее – сразу неси их сюда, а я уж найду, чем тебя отблагодарить.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25773,'Природное явление','Этот осколок – все, что осталось от здешнего разлома. Какая связь между осколком и разломом – не ясно, но, быть может, в этом сумеет разобраться кто-то более сведущий в стихиях.$B$BРазыщи посланника Служителей Земли в любой из столиц. Возможно, это как раз то, что они ищут.','Отнесите осколок элементаля посланнику Служителей Земли в Стальгорн, Штормград, Экзодар или Дарнас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Природное явление',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этот осколок – все, что осталось от здешнего разлома. Какая связь между осколком и разломом – не ясно, но, быть может, в этом сумеет разобраться кто-то более сведущий в стихиях.$B$BРазыщи посланника Служителей Земли в любой из столиц. Возможно, это как раз то, что они ищут.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите осколок элементаля посланнику Служителей Земли в Стальгорн, Штормград, Экзодар или Дарнас.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25774,'Золото дураков','Мы, разумеется, не сможем предложить СТОЛЬКО золота, сколько предлагает Орда. Нужно что-то предпринять, $n, иначе не видать нам этих прав на бурение как гному своих ушей!$B$BПостой-ка... Был же некий отчет подводной экспедиции, которую мы отправляли сразу после того, как приключился катаклизм. Что-то о похожей на золото руде, которую выбросило из земных недр. Эврика!$B$BОтправляйся на запад, к старым пастбищам кентавров, Скале Треснувшего Копыта и Оплоту Треснувшего Копыта и добудь мне этой руды.','Соберите 8 глыб колчедановой руды с Тысячи Игл.','Гениально! Так, где тут у меня позолота? Точно помню, что была где-то здесь.','Когда принесешь достаточно колчедана, мы его подкрасим маленько, сложим на блюдечко – и отправим тебя с ним к их вожаку.','Вернитесь к Краззлу Шустрецу на Утес Треснувшего Копыта в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Золото дураков',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы, разумеется, не сможем предложить СТОЛЬКО золота, сколько предлагает Орда. Нужно что-то предпринять, $n, иначе не видать нам этих прав на бурение как гному своих ушей!$B$BПостой-ка... Был же некий отчет подводной экспедиции, которую мы отправляли сразу после того, как приключился катаклизм. Что-то о похожей на золото руде, которую выбросило из земных недр. Эврика!$B$BОтправляйся на запад, к старым пастбищам кентавров, Скале Треснувшего Копыта и Оплоту Треснувшего Копыта и добудь мне этой руды.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 глыб колчедановой руды с Тысячи Игл.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Гениально! Так, где тут у меня позолота? Точно помню, что была где-то здесь.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Когда принесешь достаточно колчедана, мы его подкрасим маленько, сложим на блюдечко – и отправим тебя с ним к их вожаку.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Краззлу Шустрецу на Утес Треснувшего Копыта в Тысяче Игл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25775,'Золото дураков','Мы, разумеется, не сможем предложить СТОЛЬКО золота, сколько предлагает Альянс. Нужно что-то предпринять, $n, иначе не видать нам этих прав на бурение как гному своих ушей!$B$BПостой-ка... Был же некий отчет подводной экспедиции, которую мы отправляли сразу после того, как приключился катаклизм. Что-то о похожей на золото руде, которую выбросило из земных недр. Эврика!$B$BОтправляйся на запад, к старым пастбищам кентавров, Скале Треснувшего Копыта и Оплоту Треснувшего Копыта и добудь мне этой руды.','Соберите 8 глыб колчедановой руды с Тысячи Игл.','Гениально! Так, где тут у меня позолота? Точно помню, что была где-то здесь.','Когда принесешь достаточно колчедана, мы его подкрасим маленько, сложим на блюдечко – и отправим тебя с ним к их вожаку.','Вернитесь к Ризнеку на Утес Треснувшего Копыта в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Золото дураков',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы, разумеется, не сможем предложить СТОЛЬКО золота, сколько предлагает Альянс. Нужно что-то предпринять, $n, иначе не видать нам этих прав на бурение как гному своих ушей!$B$BПостой-ка... Был же некий отчет подводной экспедиции, которую мы отправляли сразу после того, как приключился катаклизм. Что-то о похожей на золото руде, которую выбросило из земных недр. Эврика!$B$BОтправляйся на запад, к старым пастбищам кентавров, Скале Треснувшего Копыта и Оплоту Треснувшего Копыта и добудь мне этой руды.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 глыб колчедановой руды с Тысячи Игл.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Гениально! Так, где тут у меня позолота? Точно помню, что была где-то здесь.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Когда принесешь достаточно колчедана, мы его подкрасим маленько, сложим на блюдечко – и отправим тебя с ним к их вожаку.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ризнеку на Утес Треснувшего Копыта в Тысяче Игл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (25776,'Гибель Сетрии','Пока ты $gразорял:разоряла; кладку Сетрии, я обсуждала сложившуюся ситуацию с друидами святилища Авианы. Вначале повелитель небес Омнурон противился нашему плану, но нам с друидами удалось убедить его напасть на саму Сетрию.$B$BВсе согласились с моим планом... и ты возглавишь нас!$B$BВозьми сигнальную ракету и напади на Сетрию на дальнем хребте. Когда же она явит свое истинное обличье и превратится в дракона, запусти ракету, и мы придем к тебе на помощь.','Уничтожьте Сетрию. Когда она примет драконье обличье, запустите сигнальную ракету, чтобы позвать подкрепление.','С Сетрией покончено! Я знала, что стоило рискнуть.$B$BЯ пока побуду тут, должен же кто-то присмотреть за оставшимися в живых драконидами. А вот тебя уже ждут в святилище.','Сетрия далеко не самый сильный и опасный дракон, но она доставила нам много хлопот. Боюсь подумать, чем еще нас планирует удивить культ Сумеречного Молота.','Вернитесь к Тизали Вороне в Гнезде Сетрии на горе Хиджал.','Как только она обратится в дракона, зови нас на помощь!','Сетрия') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гибель Сетрии',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пока ты $gразорял:разоряла; кладку Сетрии, я обсуждала сложившуюся ситуацию с друидами святилища Авианы. Вначале повелитель небес Омнурон противился нашему плану, но нам с друидами удалось убедить его напасть на саму Сетрию.$B$BВсе согласились с моим планом... и ты возглавишь нас!$B$BВозьми сигнальную ракету и напади на Сетрию на дальнем хребте. Когда же она явит свое истинное обличье и превратится в дракона, запусти ракету, и мы придем к тебе на помощь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте Сетрию. Когда она примет драконье обличье, запустите сигнальную ракету, чтобы позвать подкрепление.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','С Сетрией покончено! Я знала, что стоило рискнуть.$B$BЯ пока побуду тут, должен же кто-то присмотреть за оставшимися в живых драконидами. А вот тебя уже ждут в святилище.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Сетрия далеко не самый сильный и опасный дракон, но она доставила нам много хлопот. Боюсь подумать, чем еще нас планирует удивить культ Сумеречного Молота.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тизали Вороне в Гнезде Сетрии на горе Хиджал.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Как только она обратится в дракона, зови нас на помощь!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Сетрия',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (25777,'Путь в Гавань Менетилов','В Менетиле должны как можно скорее об этом узнать. Я отправляю тебя туда на моем самом быстром баране, $n.$B$BДорогу он помнит, ты только знай себе держись в седле покрепче.$B$BНе мешкай, в лагере делать нечего. Нужно срочно доставить весть!','Отнесите отчет Крепкой Стамески капитану Крепкому Кулаку в Гавань Менетилов.','Посмотрим.$B$BО, замечательно. "Значительные геологические подвижки"? "Угроза внезапной массивной топологической дестабилизации"?$B$BКак приятно слышать – у нас тут, оказывается, может случиться что-то плохое. Значит, мы просто-напросто вздернем наш затопленный городок в воздух и улетим куда-нибудь в безопасное место!$B$BКак же!','Добро пожаловать в Менетил, чужестранец. Надеюсь, ты несешь с собой добрые вести. Или, по крайней мере, какое-нибудь пойло позабористей.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путь в Гавань Менетилов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В Менетиле должны как можно скорее об этом узнать. Я отправляю тебя туда на моем самом быстром баране, $n.$B$BДорогу он помнит, ты только знай себе держись в седле покрепче.$B$BНе мешкай, в лагере делать нечего. Нужно срочно доставить весть!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите отчет Крепкой Стамески капитану Крепкому Кулаку в Гавань Менетилов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Посмотрим.$B$BО, замечательно. "Значительные геологические подвижки"? "Угроза внезапной массивной топологической дестабилизации"?$B$BКак приятно слышать – у нас тут, оказывается, может случиться что-то плохое. Значит, мы просто-напросто вздернем наш затопленный городок в воздух и улетим куда-нибудь в безопасное место!$B$BКак же!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Добро пожаловать в Менетил, чужестранец. Надеюсь, ты несешь с собой добрые вести. Или, по крайней мере, какое-нибудь пойло позабористей.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25778,'Меняем фальшивое на черное','Ну все, готово "золотишко". Теперь отнеси его хану Аблину. Бьюсь об заклад, он будет так поражен, что сам поможет нам установить оборудование для добычи нефти. Лишние лошадиные силы нам не помешают.$B$BХа-ха-ха! Дошло? "Лошадиные силы"!','Отнесите блюдо "золота" хану Аблину на Утес Треснувшего Копыта в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Меняем фальшивое на черное',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну все, готово "золотишко". Теперь отнеси его хану Аблину. Бьюсь об заклад, он будет так поражен, что сам поможет нам установить оборудование для добычи нефти. Лишние лошадиные силы нам не помешают.$B$BХа-ха-ха! Дошло? "Лошадиные силы"!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите блюдо "золота" хану Аблину на Утес Треснувшего Копыта в Тысяче Игл.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (25779,'Меняем фальшивое на черное','Ну все, готово "золотишко". Теперь отнеси его хану Ближу. Бьюсь об заклад, он будет так поражен, что сам поможет нам установить оборудование для добычи нефти. Лишние лошадиные силы нам не помешают.$B$BХа-ха-ха! Дошло? "Лошадиные силы"!','Отнесите блюдо "золота" хану Ближу на Утес Треснувшего Копыта в Тысяче Игл.','Что это? У тебя целая гора золота, я гляжу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Меняем фальшивое на черное',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну все, готово "золотишко". Теперь отнеси его хану Ближу. Бьюсь об заклад, он будет так поражен, что сам поможет нам установить оборудование для добычи нефти. Лишние лошадиные силы нам не помешают.$B$BХа-ха-ха! Дошло? "Лошадиные силы"!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите блюдо "золота" хану Ближу на Утес Треснувшего Копыта в Тысяче Игл.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что это? У тебя целая гора золота, я гляжу.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (25780,'Штурм крепости Менетилов','Мы только-только начали оправляться после наводнения, и тут случилась новая беда: на город напал клан Черного Железа. Я и мои воины кинулись защищать горожан, но наши полоумные враги отступили – прямиком в крепость.$B$BОни там хорошо укрепились, а разрушить крепость мы не можем. Не теперь, когда полгорода и так в руинах.$B$BЗайми мое место, $n. Я бы сам разобрался с их главарем, но он, как видишь, ранил меня. Проникни в крепость и убей Хоргаста... Положи этому конец!','Убейте Хоргаста Вспышку Безумия.','Он мертв! Хвала Творцам…$B$BОх, не нравится мне их видок. Дворфы из клана Черного Железа, с которыми я в свое время воевал, никогда себя так безумно не вели. Что же им такое нынче в голову взбрело…','Вернитесь к капитану Крепкому Кулаку в Гавань Менетилов, что в Болотине.','Я хочу, чтобы он был мертв!','Хоргаст Вспышка Безумия') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Штурм крепости Менетилов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы только-только начали оправляться после наводнения, и тут случилась новая беда: на город напал клан Черного Железа. Я и мои воины кинулись защищать горожан, но наши полоумные враги отступили – прямиком в крепость.$B$BОни там хорошо укрепились, а разрушить крепость мы не можем. Не теперь, когда полгорода и так в руинах.$B$BЗайми мое место, $n. Я бы сам разобрался с их главарем, но он, как видишь, ранил меня. Проникни в крепость и убей Хоргаста... Положи этому конец!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Хоргаста Вспышку Безумия.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Он мертв! Хвала Творцам…$B$BОх, не нравится мне их видок. Дворфы из клана Черного Железа, с которыми я в свое время воевал, никогда себя так безумно не вели. Что же им такое нынче в голову взбрело…',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Крепкому Кулаку в Гавань Менетилов, что в Болотине.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Я хочу, чтобы он был мертв!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Хоргаст Вспышка Безумия',`questgivertargetname_loc8`);
