INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25789,'Докопаться до истины','На месте разлома осталось это странное устройство – но что это такое?$B$BВозможно, в столице кто-нибудь сумеет разобраться.','Отнесите загадочное устройство в Оргриммар, Подгород, Луносвет или Громовой Утес и покажите его представителю Служителей Земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Докопаться до истины',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На месте разлома осталось это странное устройство – но что это такое?$B$BВозможно, в столице кто-нибудь сумеет разобраться.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите загадочное устройство в Оргриммар, Подгород, Луносвет или Громовой Утес и покажите его представителю Служителей Земли.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (25790,'Назад к Краззлу','Я не дурак!$B$BВернешься к тому, кто тебя послал, и скажешь, что сделки не будет! Если, конечно, сумеешь вернуться к нему живым...','Поговорите с Краззлом Шустрецом на Утесе Треснувшего Копыта в Тысяче Игл.','ОНИ ЧТО?!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Назад к Краззлу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я не дурак!$B$BВернешься к тому, кто тебя послал, и скажешь, что сделки не будет! Если, конечно, сумеешь вернуться к нему живым...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Краззлом Шустрецом на Утесе Треснувшего Копыта в Тысяче Игл.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','ОНИ ЧТО?!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (25791,'Назад к Ризнеку','Я не дурак!$B$BВернешься к тому, кто тебя послал, и скажешь, что сделки не будет! Если, конечно, сумеешь вернуться к нему живым...','Поговорите с Ризнеком на Утесе Треснувшего Копыта в Тысяче Игл.','ОНИ ЧТО?!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Назад к Ризнеку',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я не дурак!$B$BВернешься к тому, кто тебя послал, и скажешь, что сделки не будет! Если, конечно, сумеешь вернуться к нему живым...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Ризнеком на Утесе Треснувшего Копыта в Тысяче Игл.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','ОНИ ЧТО?!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25792,'Наступление','Большая часть горных пехотинцев и паровых танков Дун Морога заняты в бою на передовой Мерзлогривов, которая приближается к нам с юго-востока. У нас едва хватает сил сдерживать троллей, что уж говорить о входе в деревню или захвате их предводителя.$b$bОни перерезали нам все подходы, расставив загадочные тотемы, которые вызывают приступы удушья у всех приближающихся горных пехотинцев, делая их беззащитными перед врагами. На этом камне начертана руна огня. Он должен помочь разрушить эти тотемы и освободить наших горных пехотинцев.','Воспользуйтесь руной огня, чтобы разрушить 4 тотема удушения на передовой Мерзлогривов.','Ну наконец-то хорошие новости с передовой Мерзлогривов. Я прикажу горным пехотинцам немедленно усилить атаку. А теперь надо сообщить нашим союзникам гномам из поселка Сталежара, что они могут начинать наступление.','Вернитесь к капитану Таррану в Каранос.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наступление',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Большая часть горных пехотинцев и паровых танков Дун Морога заняты в бою на передовой Мерзлогривов, которая приближается к нам с юго-востока. У нас едва хватает сил сдерживать троллей, что уж говорить о входе в деревню или захвате их предводителя.$b$bОни перерезали нам все подходы, расставив загадочные тотемы, которые вызывают приступы удушья у всех приближающихся горных пехотинцев, делая их беззащитными перед врагами. На этом камне начертана руна огня. Он должен помочь разрушить эти тотемы и освободить наших горных пехотинцев.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь руной огня, чтобы разрушить 4 тотема удушения на передовой Мерзлогривов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну наконец-то хорошие новости с передовой Мерзлогривов. Я прикажу горным пехотинцам немедленно усилить атаку. А теперь надо сообщить нашим союзникам гномам из поселка Сталежара, что они могут начинать наступление.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Таррану в Каранос.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (25793,'Глубокие плёсы','Эта база нужна была для того, чтобы Терамор закрепился в Когтистых горах и мог поставлять припасы Ночным эльфам. Но, к сожалению, Орда задала нам хорошенькую трепку. Армии Адского Крика сильны и никогда не отступают. Такой яростной Орды я не помню со времен второй войны...$B$BТеперь вот, кажется, Орда использует шахту, выкопанную Лигой исследователей, для того, чтобы напасть на нас с тыла. Эту шахту нужно завалить!','Завалить шахту? Это будет непросто, друг мой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Глубокие плёсы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эта база нужна была для того, чтобы Терамор закрепился в Когтистых горах и мог поставлять припасы Ночным эльфам. Но, к сожалению, Орда задала нам хорошенькую трепку. Армии Адского Крика сильны и никогда не отступают. Такой яростной Орды я не помню со времен второй войны...$B$BТеперь вот, кажется, Орда использует шахту, выкопанную Лигой исследователей, для того, чтобы напасть на нас с тыла. Эту шахту нужно завалить!',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Завалить шахту? Это будет непросто, друг мой.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25794,'Подводное убежище','Я, кажется, выяснил, кто автор этой записки.$B$BПохоже, ему просто необходима чья-то помощь, если он хочет выжить.$B$BСейчас я настрою один из гадальных шаров и ты $gсам:сама; его увидишь.','Загляните в гадальный шар Эрунака, чтобы выяснить, где находится Дымчатый грот.','Нельзя терять ни минуты!$B$BКак ты, должно быть, понял, он недолго протянет.','Поговорите с Эрунаком в Конце отмели.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подводное убежище',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я, кажется, выяснил, кто автор этой записки.$B$BПохоже, ему просто необходима чья-то помощь, если он хочет выжить.$B$BСейчас я настрою один из гадальных шаров и ты $gсам:сама; его увидишь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Загляните в гадальный шар Эрунака, чтобы выяснить, где находится Дымчатый грот.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Нельзя терять ни минуты!$B$BКак ты, должно быть, понял, он недолго протянет.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Эрунаком в Конце отмели.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25795,'Возвращение в святилище','Яйцо Авианы было доставлено в святилище, и сейчас оно находится в безопасности. Чолуна должна знать, что делать дальше.$B$BЯ закончу кое-какие наши дела и присоединюсь к тебе позже.','Вернитесь к Чолуне в святилище Авианы на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение в святилище',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Яйцо Авианы было доставлено в святилище, и сейчас оно находится в безопасности. Чолуна должна знать, что делать дальше.$B$BЯ закончу кое-какие наши дела и присоединюсь к тебе позже.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь к Чолуне в святилище Авианы на горе Хиджал.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25796,'Богатые недра','Эта нефть нужна нам как воздух. Очень жаль, что кентавры ушли от наступающего моря именно сюда.$B$BЖаль для кентавров, разумеется.$B$BОни плюнули нам в лицо, $n. Мы сделали им щедрое предложение, и они поступили неразумно, отвергнув его. Теперь мы... то есть ты – покажешь им, что они были неправы.$B$BОчисти Утес Треснувшего Копыта от кентавров. Да прольется нефть!','Убейте 15 кентавров на Утесе Треснувшего Копыта.','Это послужит им уроком. Ты хорошо проучил кентавров Треснувшего Копыта, так что теперь мы сможем руководить ими с гоночной баржи, держа здесь только минимальный гарнизон.$B$BРазумеется, после того, как мы разделаемся с их предполагаемым вожаком-элементалем воздуха.','Вернитесь к Краззлу Шустрецу на Утес Треснувшего Копыта в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Богатые недра',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эта нефть нужна нам как воздух. Очень жаль, что кентавры ушли от наступающего моря именно сюда.$B$BЖаль для кентавров, разумеется.$B$BОни плюнули нам в лицо, $n. Мы сделали им щедрое предложение, и они поступили неразумно, отвергнув его. Теперь мы... то есть ты – покажешь им, что они были неправы.$B$BОчисти Утес Треснувшего Копыта от кентавров. Да прольется нефть!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 15 кентавров на Утесе Треснувшего Копыта.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это послужит им уроком. Ты хорошо проучил кентавров Треснувшего Копыта, так что теперь мы сможем руководить ими с гоночной баржи, держа здесь только минимальный гарнизон.$B$BРазумеется, после того, как мы разделаемся с их предполагаемым вожаком-элементалем воздуха.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Краззлу Шустрецу на Утес Треснувшего Копыта в Тысяче Игл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25797,'Богатые недра','Эта нефть нужна нам как воздух. Очень жаль, что кентавры ушли от наступающего моря именно сюда.$B$BЖаль для кентавров, разумеется.$B$BОни плюнули нам в лицо, $n. Мы сделали им щедрое предложение, и они поступили неразумно, отвергнув его. Теперь мы... то есть ты – покажешь им, что они были неправы.$B$BОчисти Утес Треснувшего Копыта от кентавров. Да прольется нефть!','Убейте 15 кентавров на Утесе Треснувшего Копыта.','Это послужит им уроком. Ты хорошо проучил кентавров Треснувшего Копыта, так что теперь мы сможем руководить ими с гоночной баржи, держа здесь только минимальный гарнизон.$B$BРазумеется, после того, как мы разделаемся с их предполагаемым вожаком-элементалем воздуха.','Вернитесь к Ризнеку на Утес Треснувшего Копыта в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Богатые недра',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эта нефть нужна нам как воздух. Очень жаль, что кентавры ушли от наступающего моря именно сюда.$B$BЖаль для кентавров, разумеется.$B$BОни плюнули нам в лицо, $n. Мы сделали им щедрое предложение, и они поступили неразумно, отвергнув его. Теперь мы... то есть ты – покажешь им, что они были неправы.$B$BОчисти Утес Треснувшего Копыта от кентавров. Да прольется нефть!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 15 кентавров на Утесе Треснувшего Копыта.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это послужит им уроком. Ты хорошо проучил кентавров Треснувшего Копыта, так что теперь мы сможем руководить ими с гоночной баржи, держа здесь только минимальный гарнизон.$B$BРазумеется, после того, как мы разделаемся с их предполагаемым вожаком-элементалем воздуха.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ризнеку на Утес Треснувшего Копыта в Тысяче Игл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (25798,'На защиту бура','Лично я с пустыми руками отсюда не уйду! Ты со мной?$B$BБьюсь об заклад, тебе не терпится узнать, что вон в том огромном ящике. Что ж, момент истины настал. Доставь одну из наших буровых установок к нефтяным пластам и добудь нам немножко сырца.$B$BКентавры наверняка попытаются на тебя напасть. Так что защищай бур до тех пор, пока тот не выкачает бочку-другую нефти.','Защитите оборудование для добычи нефти.','Нефть! Черное золотце! Чаек из Танариса!$B$BМы богаты! Нужно только куда-нибудь деть оставшихся надоед-кентавров. Думаю, с теми деньжищами, которые мы тут заработаем, мы их переселим на какое-нибудь другое взгорье.','Оборудование для добычи нефти защищено','Вернитесь к Краззлу Шустрецу на Утес Треснувшего Копыта в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На защиту бура',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Лично я с пустыми руками отсюда не уйду! Ты со мной?$B$BБьюсь об заклад, тебе не терпится узнать, что вон в том огромном ящике. Что ж, момент истины настал. Доставь одну из наших буровых установок к нефтяным пластам и добудь нам немножко сырца.$B$BКентавры наверняка попытаются на тебя напасть. Так что защищай бур до тех пор, пока тот не выкачает бочку-другую нефти.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Защитите оборудование для добычи нефти.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Нефть! Черное золотце! Чаек из Танариса!$B$BМы богаты! Нужно только куда-нибудь деть оставшихся надоед-кентавров. Думаю, с теми деньжищами, которые мы тут заработаем, мы их переселим на какое-нибудь другое взгорье.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Оборудование для добычи нефти защищено',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Краззлу Шустрецу на Утес Треснувшего Копыта в Тысяче Игл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (25799,'На защиту бура','Лично я с пустыми руками отсюда не уйду! Ты со мной?$B$BБьюсь об заклад, тебе не терпится узнать, что вон в том огромном ящике. Что ж, момент истины настал. Доставь одну из наших буровых установок к нефтяным пластам и добудь нам немножко сырца.$B$BКентавры наверняка попытаются на тебя напасть. Так что защищай бур до тех пор, пока тот не выкачает бочку-другую нефти.','Защитите оборудование для добычи нефти.','Нефть! Черное золотце! Чаек из Танариса!$B$BМы богаты! Нужно только куда-нибудь деть оставшихся надоед-кентавров. Думаю, с теми деньжищами, которые мы тут заработаем, мы их переселим на какое-нибудь другое взгорье.','Оборудование для добычи нефти защищено','Вернитесь к Ризнеку на Утес Треснувшего Копыта в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На защиту бура',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Лично я с пустыми руками отсюда не уйду! Ты со мной?$B$BБьюсь об заклад, тебе не терпится узнать, что вон в том огромном ящике. Что ж, момент истины настал. Доставь одну из наших буровых установок к нефтяным пластам и добудь нам немножко сырца.$B$BКентавры наверняка попытаются на тебя напасть. Так что защищай бур до тех пор, пока тот не выкачает бочку-другую нефти.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Защитите оборудование для добычи нефти.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Нефть! Черное золотце! Чаек из Танариса!$B$BМы богаты! Нужно только куда-нибудь деть оставшихся надоед-кентавров. Думаю, с теми деньжищами, которые мы тут заработаем, мы их переселим на какое-нибудь другое взгорье.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Оборудование для добычи нефти защищено',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ризнеку на Утес Треснувшего Копыта в Тысяче Игл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25800,'Не было бы счастья, да несчастье помогло','Работы у нас тут, конечно, по горло, |3-6($c), но не следует игнорировать подарки судьбы.$B$BКогда случилось наводнение, беснующиеся потоки занесли к нам немало обитателей океана. Теперь Гавань Менетилов кишит крабами – большими, сочными.$B$BЯ всегда говорил: если корабль разбился на крабовой отмели – хоть крабов наешься досыта! Так что принеси-ка ты мне самые крупные, самые мясистые крабьи клешни, какие только сможешь найти, а я заплачу.','Добудьте 5 мясистых клешней крабов гавани.','Вернитесь к Карлу Борану в Гавань Менетилов, что в Болотине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Не было бы счастья, да несчастье помогло',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Работы у нас тут, конечно, по горло, |3-6($c), но не следует игнорировать подарки судьбы.$B$BКогда случилось наводнение, беснующиеся потоки занесли к нам немало обитателей океана. Теперь Гавань Менетилов кишит крабами – большими, сочными.$B$BЯ всегда говорил: если корабль разбился на крабовой отмели – хоть крабов наешься досыта! Так что принеси-ка ты мне самые крупные, самые мясистые крабьи клешни, какие только сможешь найти, а я заплачу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 5 мясистых клешней крабов гавани.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Карлу Борану в Гавань Менетилов, что в Болотине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (25801,'Угроза из глубин','Мурлоки поднимаются из глубин океана и строят поселения на берегу. Они нападают на наших рыбаков и торговцев, и этому нужно положить конец.$B$BОдин из вожаков, Жрун, повадился со своими родичами из племени Синежабрых устраивать засады на дороге. А после каждого нападения они возвращаются в свои хибары, откуда их уже не достать. Мы хорошо заплатим тому, кто сможет обеспечить безопасность наших торговых путей.$B$BЖрун промышляет в речной бухте к северу отсюда. Найди его, убей гада и всю его свору. И принеси мне его голову.','Добудьте голову Жруна и убейте 12 мурлоков любого вида из племени Синежабрых.','Вернитесь к Карлу Борану в Гавань Менетилов, что в Болотине.','Больше он нас не побеспокоит.','Жрун') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Угроза из глубин',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мурлоки поднимаются из глубин океана и строят поселения на берегу. Они нападают на наших рыбаков и торговцев, и этому нужно положить конец.$B$BОдин из вожаков, Жрун, повадился со своими родичами из племени Синежабрых устраивать засады на дороге. А после каждого нападения они возвращаются в свои хибары, откуда их уже не достать. Мы хорошо заплатим тому, кто сможет обеспечить безопасность наших торговых путей.$B$BЖрун промышляет в речной бухте к северу отсюда. Найди его, убей гада и всю его свору. И принеси мне его голову.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте голову Жруна и убейте 12 мурлоков любого вида из племени Синежабрых.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Карлу Борану в Гавань Менетилов, что в Болотине.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Больше он нас не побеспокоит.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Жрун',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25806,'В такой глубокой... а, ничего.','Ох, Лига исследователей – сборище абсолютных глупцов. Мало нам призраков тауренов вокруг, так эта Лига исследователей умудрилась еще и открыть тайный ход на первоначальную базу Орды в Когтистых горах, она называется крепость Кром\'гар.$B$BТеперь убийцы из крепости шныряют здесь и по-тихому убивают всех в шахте.$B$BЯ хочу, чтобы ты $gпошел:пошла; туда и все там $gзачистил:зачистила;..$B$BОй, да, чуть не забыл: держи-ка эти очки. Надевай смелей. В них ты будешь отлично видеть любого замаскированного убийцу в шахте.','Убейте 12 кром\'гарских убийц.','Обратитесь к лейтенанту Полсону в Глубоких Плесах в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В такой глубокой... а, ничего.',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ох, Лига исследователей – сборище абсолютных глупцов. Мало нам призраков тауренов вокруг, так эта Лига исследователей умудрилась еще и открыть тайный ход на первоначальную базу Орды в Когтистых горах, она называется крепость Кром\'гар.$B$BТеперь убийцы из крепости шныряют здесь и по-тихому убивают всех в шахте.$B$BЯ хочу, чтобы ты $gпошел:пошла; туда и все там $gзачистил:зачистила;..$B$BОй, да, чуть не забыл: держи-ка эти очки. Надевай смелей. В них ты будешь отлично видеть любого замаскированного убийцу в шахте.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 кром\'гарских убийц.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Обратитесь к лейтенанту Полсону в Глубоких Плесах в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25807,'Возрождение древней богини','Уверена, что ты $gвестник:вестница; Авианы, $n! Ведь именно ты впервые $gувидел:увидела; ее и $gспас:спасла; ее сущность из лап дракона.$B$BЯ полагаю, что Авиана скоро вернется в наш мир. И ты $gудостоен:удостоена; чести открыть перед ней врата.$B$BВозьми этот фимиам и воскури его над яйцом Авианы в комнате, что находится выше.$B$BДревняя богиня ждет, $n. Грядет наше спасение!','Примените фимиам вестника на яйце Авианы в святилище Авианы.','Поговорите с Авианой в ее святилище на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возрождение древней богини',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Уверена, что ты $gвестник:вестница; Авианы, $n! Ведь именно ты впервые $gувидел:увидела; ее и $gспас:спасла; ее сущность из лап дракона.$B$BЯ полагаю, что Авиана скоро вернется в наш мир. И ты $gудостоен:удостоена; чести открыть перед ней врата.$B$BВозьми этот фимиам и воскури его над яйцом Авианы в комнате, что находится выше.$B$BДревняя богиня ждет, $n. Грядет наше спасение!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Примените фимиам вестника на яйце Авианы в святилище Авианы.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Авианой в ее святилище на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertargetname_loc8`) VALUES (25808,'Эта штука работает?','<ГНМ-передатчик потрескивает от статических помех, и вы слышите голос лейтенанта Полсона.>$B$BДа что за гномья рухлядь... ЕСТЬ КТО ЖИВОЙ?! $n, ты меня слышишь?$B$BНикак $gпомер:померла; уже?$B$BТак, если ты меня еще слышишь: нам только что донесли про некую главу убийц: она сидит в той же шахте и управляет всеми остальными. Так что найди ее, ликвидируй, а потом доложи мне.$B$BПолсон, отбой.','Ликвидируйте главу убийц Кел\'истру.','Обратитесь к лейтенанту Полсону в Глубоких Плесах в Когтистых горах.','Лейтенант Полсон') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Эта штука работает?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<ГНМ-передатчик потрескивает от статических помех, и вы слышите голос лейтенанта Полсона.>$B$BДа что за гномья рухлядь... ЕСТЬ КТО ЖИВОЙ?! $n, ты меня слышишь?$B$BНикак $gпомер:померла; уже?$B$BТак, если ты меня еще слышишь: нам только что донесли про некую главу убийц: она сидит в той же шахте и управляет всеми остальными. Так что найди ее, ликвидируй, а потом доложи мне.$B$BПолсон, отбой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Ликвидируйте главу убийц Кел\'истру.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Обратитесь к лейтенанту Полсону в Глубоких Плесах в Когтистых горах.',`completedtext_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Лейтенант Полсон',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25809,'Своих не бросать!','Орда – просто звери!$B$B<Капрал Турс плюет на землю.>$B$BТы глянь вокруг! Всех невинных порешили! Гражданских!$B$BСлушай, $n, ты $gдолжен:должна; нам помочь. Отправляйся в Глубокие плёсы и посмотри, не осталось ли там кого из живых шахтеров. Если кто и выжил, то наверняка, до смерти напуганы! Обыщи все закоулки, в каждой трещине пошарь, даже в тележках! Кто-то ведь непременно сумел выжить и спрятаться.','Спасите 8 испуганных шахтеров.','Обратитесь к капралу Турсу в Глубоких Плесах в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Своих не бросать!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Орда – просто звери!$B$B<Капрал Турс плюет на землю.>$B$BТы глянь вокруг! Всех невинных порешили! Гражданских!$B$BСлушай, $n, ты $gдолжен:должна; нам помочь. Отправляйся в Глубокие плёсы и посмотри, не осталось ли там кого из живых шахтеров. Если кто и выжил, то наверняка, до смерти напуганы! Обыщи все закоулки, в каждой трещине пошарь, даже в тележках! Кто-то ведь непременно сумел выжить и спрятаться.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Спасите 8 испуганных шахтеров.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Обратитесь к капралу Турсу в Глубоких Плесах в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (25810,'Разорение инкубатора','$n! Чолуна сказала правду: богиня вернулась! Это какое-то чудо.$B$BНесмотря на то, что ты $gрасправился:расправилась; с драконом Сетрией, нам еще предстоит отыскать все яйца, украденные для нее гарпиями. Мы с Тизали обнаружили их в огромном инкубаторе, расположенном на Огненных Просторах. Это место находится в ином мире, так что Авиана не сможет сопровождать тебя.$B$BВойди в огненные врата в центре долины, что лежит к югу отсюда. Там тебя встретит Фарден Когтекрыл.','Так это правда – Авиана вернулась, и ты ее вестник.$B$BНам предстоит много работы. Мы находимся в самом сердце Огненных Просторов. Сетрия перенесла сюда украденные на горе Хиджал яйца, чтобы тут высидеть хищников, обученных убивать.$B$BЯ надеюсь, ты готов нанести ответный удар!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разорение инкубатора',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n! Чолуна сказала правду: богиня вернулась! Это какое-то чудо.$B$BНесмотря на то, что ты $gрасправился:расправилась; с драконом Сетрией, нам еще предстоит отыскать все яйца, украденные для нее гарпиями. Мы с Тизали обнаружили их в огромном инкубаторе, расположенном на Огненных Просторах. Это место находится в ином мире, так что Авиана не сможет сопровождать тебя.$B$BВойди в огненные врата в центре долины, что лежит к югу отсюда. Там тебя встретит Фарден Когтекрыл.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так это правда – Авиана вернулась, и ты ее вестник.$B$BНам предстоит много работы. Мы находимся в самом сердце Огненных Просторов. Сетрия перенесла сюда украденные на горе Хиджал яйца, чтобы тут высидеть хищников, обученных убивать.$B$BЯ надеюсь, ты готов нанести ответный удар!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25811,'Обвал шахты','Чтобы обвалить шахту, нужно снести ее опорные балки. Взрывчатки-то я тебе дам, этого добра полно; но чтобы обложить ею каждую балку, тебе придется пробиться через Кром\'гарских убийц.$B$BХотя есть и хорошая весть: мы всегда отмечали все опорные балки большим красным крестом. Так что просто ищи отметки и закладывай взрывчатку около них. Когда все заложишь, возвращайся сюда, и я запущу детонатор.$B$BБдыщщщ!','Заложите связку динамита у первой, второй, третьей и четвертой балки.','Ща рванет!','Вернитесь к Железной Лапе Макги в Глубокие Плесы в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обвал шахты',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чтобы обвалить шахту, нужно снести ее опорные балки. Взрывчатки-то я тебе дам, этого добра полно; но чтобы обложить ею каждую балку, тебе придется пробиться через Кром\'гарских убийц.$B$BХотя есть и хорошая весть: мы всегда отмечали все опорные балки большим красным крестом. Так что просто ищи отметки и закладывай взрывчатку около них. Когда все заложишь, возвращайся сюда, и я запущу детонатор.$B$BБдыщщщ!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заложите связку динамита у первой, второй, третьей и четвертой балки.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ща рванет!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Железной Лапе Макги в Глубокие Плесы в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (25812,'Спелеологи','Скорее, $n!$B$BНемедленно плыви к той пещере.$B$BМы тоже туда отправимся и проследим, нет ли за тобой хвоста.','Поговорите с рядовым Поллардом в Дымчатом гроте.','Ворген? Здесь?$B$BЯ, должно быть, рехнулся...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спелеологи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Скорее, $n!$B$BНемедленно плыви к той пещере.$B$BМы тоже туда отправимся и проследим, нет ли за тобой хвоста.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с рядовым Поллардом в Дымчатом гроте.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ворген? Здесь?$B$BЯ, должно быть, рехнулся...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (25813,'Подуй в рог','Тот старый кентавр, Небоступ Врактрис, упоминал некого великого духа ветра, которому поклоняются кентавры. Чтобы вершина окончательно стала нашей, нужно с ним разделаться.$B$BЯ видел, как они дули в огромный рог вон там, на вершине холма, чтобы вызвать элементаля. А он давал им некие распоряжения и исчезал.$B$BПоди и ты вызови его, $n.','Покончите с Вырррлом.','Что ж, пшик они теперь получат, а не волшебный ахалай-махалай, когда мы приступим к захвату!','Вернитесь к Краззлу Шустрецу на Утес Треснувшего Копыта в Тысяче Игл.','Протруби в рог и убей его!','Вырррл') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подуй в рог',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тот старый кентавр, Небоступ Врактрис, упоминал некого великого духа ветра, которому поклоняются кентавры. Чтобы вершина окончательно стала нашей, нужно с ним разделаться.$B$BЯ видел, как они дули в огромный рог вон там, на вершине холма, чтобы вызвать элементаля. А он давал им некие распоряжения и исчезал.$B$BПоди и ты вызови его, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Покончите с Вырррлом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что ж, пшик они теперь получат, а не волшебный ахалай-махалай, когда мы приступим к захвату!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Краззлу Шустрецу на Утес Треснувшего Копыта в Тысяче Игл.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Протруби в рог и убей его!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Вырррл',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (25814,'Подуй в рог','Тот старый кентавр, Небоступ Врактрис, упоминал некого великого духа ветра, которому поклоняются кентавры. Чтобы вершина окончательно стала нашей, нужно разделаться с этим божком.$B$BЯ видел, как они дули в огромный рог вон там, на вершине холма, чтобы вызвать элементаля. А он давал им некие распоряжения и исчезал.$B$BПоди и ты вызови его, $n.','Покончите с Вырррлом.','Что ж, пшик они теперь получат, а не волшебный ахалай-махалай, когда мы приступим к захвату!','Вернитесь к Ризнеку на Утес Треснувшего Копыта в Тысяче Игл.','Протруби в рог и убей его!','Вырррл') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подуй в рог',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тот старый кентавр, Небоступ Врактрис, упоминал некого великого духа ветра, которому поклоняются кентавры. Чтобы вершина окончательно стала нашей, нужно разделаться с этим божком.$B$BЯ видел, как они дули в огромный рог вон там, на вершине холма, чтобы вызвать элементаля. А он давал им некие распоряжения и исчезал.$B$BПоди и ты вызови его, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Покончите с Вырррлом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что ж, пшик они теперь получат, а не волшебный ахалай-махалай, когда мы приступим к захвату!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ризнеку на Утес Треснувшего Копыта в Тысяче Игл.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Протруби в рог и убей его!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgi