INSERT INTO `locales_quest` (`id`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25815,'Заберите медовуху Фитсиммонса из подвала таверны в Гавани Менетилов.','Ах-х! Хорошее пойло утоляет жажду и развязывает язык. Благодарствую, приятель!','Ох, до чего же в горле пересохло! Смилостивись, угости выпивкой меня, бедолагу.','Вернитесь к первому помощнику Фитсиммонсу, находящемуся в Гавани Менетилов, что в Болотине.') ON DUPLICATE KEY UPDATE `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заберите медовуху Фитсиммонса из подвала таверны в Гавани Менетилов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ах-х! Хорошее пойло утоляет жажду и развязывает язык. Благодарствую, приятель!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ох, до чего же в горле пересохло! Смилостивись, угости выпивкой меня, бедолагу.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к первому помощнику Фитсиммонсу, находящемуся в Гавани Менетилов, что в Болотине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (25816,'Обреченные на вечные скитания','Поговорите с призраком первого помощника Снеллига.','Тебя послал Фитсиммонс, ведь так? Столько времени прошло…') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обреченные на вечные скитания',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с призраком первого помощника Снеллига.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебя послал Фитсиммонс, ведь так? Столько времени прошло…',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25817,'Проклятая команда','Убейте 5 проклятых матросов и 5 проклятых стражей бухты у Погибшего Плота.','Крики боли смолкли… но вещь, что наслала на нас это проклятье, по-прежнему здесь.','Вернитесь к первому помощнику Снеллигу у Погибшего Флота, что в Болотине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Проклятая команда',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 5 проклятых матросов и 5 проклятых стражей бухты у Погибшего Плота.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Крики боли смолкли… но вещь, что наслала на нас это проклятье, по-прежнему здесь.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к первому помощнику Снеллигу у Погибшего Флота, что в Болотине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25818,'Очищение','Только свершенная месть поможет снять с нас проклятие. Капитан Халиндор, виновник наших бед, разжег в команде пагубное желание обладать запретным артефактом – Оком Палета. Его дух и поныне сторожит Око, запертое в сейфе на его старом корабле, "Отважном".$B$BУничтожь того, кто обрек нас на такие муки, |3-6($c). Одолей капитана, забери у него ключ и унеси Око Палета прочь из этого места.','Отберите ключ от сейфа на "Отважном" у капитана Халиндора.','Ключ порядком проржавел, но в замке проворачивается легко.','Сундук надежно заперт.','Отыщите ключ от сейфа на "Отважном" в Болотине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Очищение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Только свершенная месть поможет снять с нас проклятие. Капитан Халиндор, виновник наших бед, разжег в команде пагубное желание обладать запретным артефактом – Оком Палета. Его дух и поныне сторожит Око, запертое в сейфе на его старом корабле, "Отважном".$B$BУничтожь того, кто обрек нас на такие муки, |3-6($c). Одолей капитана, забери у него ключ и унеси Око Палета прочь из этого места.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отберите ключ от сейфа на "Отважном" у капитана Халиндора.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ключ порядком проржавел, но в замке проворачивается легко.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Сундук надежно заперт.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отыщите ключ от сейфа на "Отважном" в Болотине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (25819,'Око Палета','Внутри сундука лежит шар из потемневшего стекла, источающий зловещее свечение. Должно быть, это то самое злополучное Око Палета, что наслало проклятие на души моряков.$B$BНеобходимо очистить его от скверны. Быть может, жрец в Гавани Менетилов сумеет помочь.','Отнесите проклятое Око Палета Глорину Стальному Лбу в Гавань Менетилов, что в Болотине.','Чем могу помочь, дружище?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Око Палета',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Внутри сундука лежит шар из потемневшего стекла, источающий зловещее свечение. Должно быть, это то самое злополучное Око Палета, что наслало проклятие на души моряков.$B$BНеобходимо очистить его от скверны. Быть может, жрец в Гавани Менетилов сумеет помочь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите проклятое Око Палета Глорину Стальному Лбу в Гавань Менетилов, что в Болотине.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Чем могу помочь, дружище?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25820,'Материнская тревога','Мой сын Гимлок – свет всей моей жизни. Так отрадно смотреть, как он играет с другими детьми.$B$BНо я все время беспокоюсь за него. В бухте водятся акулы, и плавают они совсем недалеко от берега. Если одна из них сумеет подобраться к детям...$B$BЯ этого не переживу! Пожалуйста, |3-6($r), ты лучше любого из нас $gподготовлен:подготовлена; к таким схваткам. Сможешь убить этих акул ради меня? Если не всех, то хотя бы нескольких?','Убейте 10 режущих плавников гавани.','О, благословенно будь твое сердце за помощь встревоженной матери. Ты так добр ко мне…','Вернитесь к Дерине Рамднул в Гавань Менетилов, что в Болотине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Материнская тревога',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мой сын Гимлок – свет всей моей жизни. Так отрадно смотреть, как он играет с другими детьми.$B$BНо я все время беспокоюсь за него. В бухте водятся акулы, и плавают они совсем недалеко от берега. Если одна из них сумеет подобраться к детям...$B$BЯ этого не переживу! Пожалуйста, |3-6($r), ты лучше любого из нас $gподготовлен:подготовлена; к таким схваткам. Сможешь убить этих акул ради меня? Если не всех, то хотя бы нескольких?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 режущих плавников гавани.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, благословенно будь твое сердце за помощь встревоженной матери. Ты так добр ко мне…',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дерине Рамднул в Гавань Менетилов, что в Болотине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (25821,'Особое задание','Ты на славу $gпотрудился:потрудилась; здесь, $n. Командир армии Вален узнал о твоих заслугах и просит тебя явиться к нему, да немедленно. У него есть для тебя особое задание – возможно, ты $gединственный:единственная;, кто сможет остановить вторжение Орды в Когтистые горы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Особое задание',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты на славу $gпотрудился:потрудилась; здесь, $n. Командир армии Вален узнал о твоих заслугах и просит тебя явиться к нему, да немедленно. У него есть для тебя особое задание – возможно, ты $gединственный:единственная;, кто сможет остановить вторжение Орды в Когтистые горы.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25822,'Оружие для войны','Добудьте 10 ящиков с оружием Альянса.','Этого хватит, чтобы вооружить сотню воинов Зловещего Тотема! Теперь можно показать оружие вождю.','Удалось добыть оружие?','Вернитесь к командиру армии Валену в лагерь экспедиции Северной Стражи в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оружие для войны',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 10 ящиков с оружием Альянса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Этого хватит, чтобы вооружить сотню воинов Зловещего Тотема! Теперь можно показать оружие вождю.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось добыть оружие?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру армии Валену в лагерь экспедиции Северной Стражи в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25823,'Безжалостная Орда','Убейте 12 врагов из Орды на месте раскопок.','Вернитесь к командиру армии Валену в лагерь экспедиции Северной Стражи в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Безжалостная Орда',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 врагов из Орды на месте раскопок.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру армии Валену в лагерь экспедиции Северной Стражи в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (25824,'Отчет','Этот солдат был при смерти, но, боюсь, у нас нет времени ждать, пока он полностью придет в себя. Он располагает информацией, которая позарез нам нужна.$B$BНаберись терпения и выпытай у него все, пока он еще может говорить.$B$BЕсли повезет, удастся выяснить, что нас тут ожидает...','Обратитесь к рядовому Полларду и попросите поведать об испытаниях, которые выпали на его долю.','Что ж, обнадеживает слабо, но это хотя бы что-то...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отчет',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этот солдат был при смерти, но, боюсь, у нас нет времени ждать, пока он полностью придет в себя. Он располагает информацией, которая позарез нам нужна.$B$BНаберись терпения и выпытай у него все, пока он еще может говорить.$B$BЕсли повезет, удастся выяснить, что нас тут ожидает...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обратитесь к рядовому Полларду и попросите поведать об испытаниях, которые выпали на его долю.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что ж, обнадеживает слабо, но это хотя бы что-то...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25825,'Неси добро','Ладно, $n, доставь-ка эту нефть Пшиксу на гоночную баржу и поведай хорошие новости','Доставьте бочку нефти Пшиксу Медноштифу на гоночную баржу Пшикса и Поззика в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Неси добро',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ладно, $n, доставь-ка эту нефть Пшиксу на гоночную баржу и поведай хорошие новости',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте бочку нефти Пшиксу Медноштифу на гоночную баржу Пшикса и Поззика в Тысяче Игл.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (25826,'Неси добро','Ладно, $n, доставь-ка эту нефть Пшиксу на гоночную баржу и поведай хорошие новости!','Доставьте бочку нефти Поззику на гоночную баржу Пшикса и Поззика в Тысяче Игл.','Это еще что? Неужто нефть?!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Неси добро',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ладно, $n, доставь-ка эту нефть Пшиксу на гоночную баржу и поведай хорошие новости!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте бочку нефти Поззику на гоночную баржу Пшикса и Поззика в Тысяче Игл.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Это еще что? Неужто нефть?!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25827,'Ло\'гош готов к бою','Благодаря тебе великий волк вновь ступает по этой земле.$B$BТеперь, |3-6($c), тебе предстоит вернуться к Древу Жизни и передать Изере, что Ло\'гош готов биться в первых рядах ее армии.$B$BСпроси ее, как мы можем помочь освободить других Древних.$B$BЛок\'тар Огар, друг мой. Твоя помощь была неоценимой.','Поговорите с Изерой у Древа Жизни на горе Хиджал.','Поговорите с Изерой у Древа Жизни на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ло\'гош готов к бою',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Благодаря тебе великий волк вновь ступает по этой земле.$B$BТеперь, |3-6($c), тебе предстоит вернуться к Древу Жизни и передать Изере, что Ло\'гош готов биться в первых рядах ее армии.$B$BСпроси ее, как мы можем помочь освободить других Древних.$B$BЛок\'тар Огар, друг мой. Твоя помощь была неоценимой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Изерой у Древа Жизни на горе Хиджал.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Изерой у Древа Жизни на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25828,'Послание к Изере: Голдринн','Голдринн свободен и его дух присоединился к нам! То, что тебе удалось сделать, – практически чудо.$B$BНужно поспешить к Древу Жизни и известить об этом Изеру! Спящая лично координирует наши усилия на Хиджале, и она будет рада узнать, что теперь в ее распоряжении и легендарная сила Голдринна тоже.$B$BМожешь заодно поговорить с Изерой и о том, как освободить других Древних.$B$BПрощай, $n, и спасибо тебе. Ты – пример для всех нас.','Поговорите с Изерой у Древа Жизни на горе Хиджал.','Поговорите с Изерой у Древа Жизни на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Послание к Изере: Голдринн',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Голдринн свободен и его дух присоединился к нам! То, что тебе удалось сделать, – практически чудо.$B$BНужно поспешить к Древу Жизни и известить об этом Изеру! Спящая лично координирует наши усилия на Хиджале, и она будет рада узнать, что теперь в ее распоряжении и легендарная сила Голдринна тоже.$B$BМожешь заодно поговорить с Изерой и о том, как освободить других Древних.$B$BПрощай, $n, и спасибо тебе. Ты – пример для всех нас.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Изерой у Древа Жизни на горе Хиджал.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Изерой у Древа Жизни на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (25829,'Tracking Quest - Goldrinn Hub Complete') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Tracking Quest - Goldrinn Hub Complete',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (25830,'Последний хранитель знаний','Тебе удалось пробудить Древних, $n, но дух Эссины, обитающий в ее роще, по-прежнему безмолвствует. С ее помощью мы могли бы переломить ход сражения и исправить все то, что натворили на этой земле сектанты Сумеречного Молота.$B$BЯ знаю, кто может нам помочь. Старшее из древ – Норду – тысячи лет находится в самом центре того места, которое мы сейчас зовем Негаснущим Пожаром. Он помнит все, что происходило с этим миром с первого дня его появления. Если Норду еще жив, возможно, ему удастся пробудить Эссину. Найди его.','Я… все еще… жив.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Последний хранитель знаний',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе удалось пробудить Древних, $n, но дух Эссины, обитающий в ее роще, по-прежнему безмолвствует. С ее помощью мы могли бы переломить ход сражения и исправить все то, что натворили на этой земле сектанты Сумеречного Молота.$B$BЯ знаю, кто может нам помочь. Старшее из древ – Норду – тысячи лет находится в самом центре того места, которое мы сейчас зовем Негаснущим Пожаром. Он помнит все, что происходило с этим миром с первого дня его появления. Если Норду еще жив, возможно, ему удастся пробудить Эссину. Найди его.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я… все еще… жив.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25831,'Послание к Изере: Хамуул','$n, мы подготовили почву и обратились за помощью к таинственному древнему богу-черепахе.$B$BПрошу тебя, отправляйся к Древу Жизни Нордрассилу и передай Изере, что я готов для дальнейших действий.$B$BМы должны пробудить всех Древних; поговори с Изерой и выясни, где еще на горе Хиджал может понадобиться твоя помощь.','Поговорите с Изерой у Древа Жизни на горе Хиджал.','Поговорите с Изерой у Древа Жизни на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Послание к Изере: Хамуул',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, мы подготовили почву и обратились за помощью к таинственному древнему богу-черепахе.$B$BПрошу тебя, отправляйся к Древу Жизни Нордрассилу и передай Изере, что я готов для дальнейших действий.$B$BМы должны пробудить всех Древних; поговори с Изерой и выясни, где еще на горе Хиджал может понадобиться твоя помощь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Изерой у Древа Жизни на горе Хиджал.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Изерой у Древа Жизни на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (25832,'Возвращение к Авиане','$n, ты $gсделал:сделала; все, что было в твоих силах. Пещера скоро обрушится!$B$BЯ соберу оставшихся крылатых скакунов и запечатаю за собой огненные врата.$B$BА ты отправляйся вперед и дай знать Авиане, что этого отвратительного инкубатора больше не существует!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение к Авиане',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, ты $gсделал:сделала; все, что было в твоих силах. Пещера скоро обрушится!$B$BЯ соберу оставшихся крылатых скакунов и запечатаю за собой огненные врата.$B$BА ты отправляйся вперед и дай знать Авиане, что этого отвратительного инкубатора больше не существует!',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25833,'Послание к Изере: Авиана','Поговорите с Изерой у Древа Жизни на горе Хиджал.','Поговорите с Изерой у Древа Жизни на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Послание к Изере: Авиана',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Изерой у Древа Жизни на горе Хиджал.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Изерой у Древа Жизни на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (25834,'Смерть по доверенности','Меня зовут "Пирожок", лапуля:, я лучший повар во всем Азероте. Командир сказал мне, что от нас требуется. Чтобы добиться встречи с вождем Зловещего Тотема, мы должны приготовить лучшие блюда тауренской кухни.$B$BТы приносишь мне нужное, я беру и делаю угощение, от которого ни один таурен не откажется. Даже очень зловещий, или какие они там бывают.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Смерть по доверенности',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Меня зовут "Пирожок", лапуля:, я лучший повар во всем Азероте. Командир сказал мне, что от нас требуется. Чтобы добиться встречи с вождем Зловещего Тотема, мы должны приготовить лучшие блюда тауренской кухни.$B$BТы приносишь мне нужное, я беру и делаю угощение, от которого ни один таурен не откажется. Даже очень зловещий, или какие они там бывают.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (25835,'Волю заставе Вольного Ветра!','Поговорите с Квентином на заставе Вольного Ветра в Тысяче Игл.','Как хорошо, что Пшикс соблаговолил наконец отправить тебя сюда. Мы помогаем тауренам отбить заставу Вольного Ветра у клана Зловещего Тотема.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Волю заставе Вольного Ветра!',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Квентином на заставе Вольного Ветра в Тысяче Игл.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Как хорошо, что Пшикс соблаговолил наконец отправить тебя сюда. Мы помогаем тауренам отбить заставу Вольного Ветра у клана Зловещего Тотема.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25837,'Достойное угощение','Чтобы приготовить достойное угощение, мне понадобится несколько ингредиентов.$B$BЯйца калимдорских орлов нужно достать из их гнезд, поищи в лесах на западе.$B$BБараний окорок! За этим делом наведайся к баранам Когтистых гор.$B$BПоследнее добыть будет потруднее, но омлета с бараниной без баранины не состряпаешь. Ступай на юго-запад к ущелью Камнепадов и отыщи пещеры кобольдов. Перебей их и забери их особенный сыр.$B$BПринеси все это мне, и я создам настоящий кулинарный шедевр!','Добудьте 6 яиц калимдорских орлов, 8 бараньих окороков и 10 кусков сыра Камнепадов.','Вернитесь к "Пирожку" МакСоусу в лагерь экспедиции Северной Стражи в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Достойное угощение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чтобы приготовить достойное угощение, мне понадобится несколько ингредиентов.$B$BЯйца калимдорских орлов нужно достать из их гнезд, поищи в лесах на западе.$B$BБараний окорок! За этим делом наведайся к баранам Когтистых гор.$B$BПоследнее добыть будет потруднее, но омлета с бараниной без баранины не состряпаешь. Ступай на юго-запад к ущелью Камнепадов и отыщи пещеры кобольдов. Перебей их и забери их особенный сыр.$B$BПринеси все это мне, и я создам настоящий кулинарный шедевр!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 6 яиц калимдорских орлов, 8 бараньих окороков и 10 кусков сыра Камнепадов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к "Пирожку" МакСоусу в лагерь экспедиции Северной Стражи в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25838,'Помощь из поселка Сталежаров','Поговорите с Делбером Кривошипом в поселке Сталежаров.','Поговорите с Делбером Кривошипом в поселке Сталежаров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Помощь из поселка Сталежаров',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Делбером Кривошипом в поселке Сталежаров.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Делбером Кривошипом в поселке Сталежаров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (25839,'Ультрабезопасный переместитель войск','Из-за катаклизма враги оказались ближе к дому, поэтому глава секретной операции "Гномреган" попросил меня сконструировать устройство, которое бы позволяло быстро и незаметно перебрасывать войска в любой уголок Дун Морога.$b$bИ вот перед тобой ультрабезопасный переместитель войск!$b$bНемного электричества и парашют системы ОПР – для вас, непрофессионалов, перевожу: очень позднее раскрытие – и эта штучка доставит тебя на передовую вовремя. Просто запрыгивай и приготовься к полету! Слемп Шестерзуб будет ждать тебя в зоне приземления.','Воспользуйтесь ультрабезопасным переместителем войск, чтобы отправиться в Укрытие Мерзлогривов.','Не беспокойся, чувство, что ты пьян будет длиться только несколько минут. В любом случае, это не такой уж плохой способ добраться туда, куда тебе нужно. Хотя парашют надо бы доработать. Действительно, поздновато он раскрывается. Иногда даже слишком поздно. Ну, неважно, у нас есть дела.','Воспользуйтесь ультрабезопасным переместителем войск, чтобы отправиться в Укрытие Мерзлогривов.','Вернитесь к Слемпу Шестерзубу в Укрытие Мерзлогривов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ультрабезопасный переместитель войск',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Из-за катаклизма враги оказались ближе к дому, поэтому глава секретной операции "Гномреган" попросил меня сконструировать устройство, которое бы позволяло быстро и незаметно перебрасывать войска в любой уголок Дун Морога.$b$bИ вот перед тобой ультрабезопасный переместитель войск!$b$bНемного электричества и парашют системы ОПР – для вас, непрофессионалов, перевожу: очень позднее раскрытие – и эта штучка доставит тебя на передовую вовремя. Просто запрыгивай и приготовься к полету! Слемп Шестерзуб будет ждать тебя в зоне приземления.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь ультрабезопасным переместителем войск, чтобы отправиться в Укрытие Мерзлогривов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Не беспокойся, чувство, что ты пьян будет длиться только несколько минут. В любом случае, это не такой уж плохой способ добраться туда, куда тебе нужно. Хотя парашют надо бы доработать. Действительно, поздновато он раскрывается. Иногда даже слишком поздно. Ну, неважно, у нас есть дела.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Воспользуйтесь ультрабезопасным переместителем войск, чтобы отправиться в Укрытие Мерзлогривов.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Слемпу Шестерзубу в Укрытие Мерзлогривов.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25840,'Сломить сопротивление','Вождь Мерзлогривов погиб при первой атаке троггов, но после этого их возглавляет один из самых уважаемых воинов. Именно Батток Берсерк основал Укрытие Мерзлогривов, строительство нового поселения и стоял во главе атак на Каранос и горных пехотинцев.$b$bЕсли мы убьем Баттока, без предводителя они станут неорганизованными, и горным пехотинцам будет легче справиться с оставшимися в живых. Баттока можно найти в поселении Мерзлогривов, что к востоку отсюда.','Убейте Баттока Берсерка и 5 воинов из племени Мерзлогривов в Укрытии Мерзлогривов.','Вернитесь к Слемпу Шестерзубу в Укрытие Мерзлогривов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сломить сопротивление',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вождь Мерзлогривов погиб при первой атаке троггов, но после этого их возглавляет один из самых уважаемых воинов. Именно Батток Берсерк основал Укрытие Мерзлогривов, строительство нового поселения и стоял во главе атак на Каранос и горных пехотинцев.$b$bЕсли мы убьем Баттока, без предводителя они станут неорганизованными, и горным пехотинцам будет легче справиться с оставшимися в живых. Баттока можно найти в поселении Мерзлогривов, что к востоку отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Баттока Берсерка и 5 воинов из племени Мерзлогривов в Укрытии Мерзлогривов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Слемпу Шестерзубу в Укрытие Мерзлогривов.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25841,'Удар сверху','Техники Делбера день и ночь не смыкали глаз, помогая нам подготовиться к этому удару. Помимо создания и настройки пусковой установки, его люди подготовили авиационное крыло секретной операции для удара по Укрытию Мерзлогривов. Они будут ждать сигнала для начала атаки.$b$bВозьми эту сигнальную ракету установи ее у группы зданий в северной и южной частях поселения. Ветролеты осуществят быстрые удары по обеим мишеням.','Воспользуйтесь сигнальной ракетой, чтобы вызывать воздушные удары по северной и южной сторонам Укрытия Мерзлогривов.','И ты, и авиационное крыло выступили превосходно. Мерзлогривов здесь больше не будет, это определенно. Все, что нам остается, – разделаться с выжившими.','Вернитесь к Слемпу Шестерзубу в Укрытие Мерзлогривов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Удар сверху',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Техники Делбера день и ночь не смыкали глаз, помогая нам подготовиться к этому удару. Помимо создания и настройки пусковой установки, его люди подготовили авиационное крыло секретной операции для удара по Укрытию Мерзлогривов. Они будут ждать сигнала для начала атаки.$b$bВозьми эту сигнальную ракету установи ее у группы зданий в северной и южной частях поселения. Ветролеты осуществят быстрые удары по обеим мишеням.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь сигнальной ракетой, чтобы вызывать воздушные удары по северной и южной сторонам Укрытия Мерзлогривов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','И ты, и авиационное крыло выступили превосходно. Мерзлогривов здесь больше не будет, это определенно. Все, что нам остается, – разделаться с выжившими.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Слемпу Шестерзубу в Укрытие Мерзлогривов.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25842,'Огнеборство','Мое время на исходе. Лишь толика меня уцелела во всепожирающем пламени. Я видел мириады эпох... но собственная кончина всегда приходит так неожиданно.$B$BНовая жизнь может зародиться на останках прежней. Я должен передать свои знания другим. Умоляю, не дай им забрать меня до тех пор, пока я не закончу начатое.$B$BЗадержи мучителей, |3-6($c), пусть даже на мгновение.$B$BПодари мне краткий миг, а взамен я наделю тебя тысячами жизней.','Уничтожьте 5 огненных мучителей, чтобы защитить от них Норду.','Вернитесь к Норду в Негаснущем пожаре на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Огнеборство',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мое время на исходе. Лишь толика меня уцелела во всепожирающем пламени. Я видел мириады эпох... но собственная кончина всегда приходит так неожиданно.$B$BНовая жизнь может зародиться на останках прежней. Я должен передать свои знания другим. Умоляю, не дай им забрать меня до тех пор, пока я не закончу начатое.$B$BЗадержи мучителей, |3-6($c), пусть даже на мгновение.$B$BПодари мне краткий миг, а взамен я наделю тебя тысячами жизней.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 5 огненных мучителей, чтобы защитить от них Норду.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Норду в Негаснущем пожаре на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (25844,'Сколько дикого дверя ни корми','Принесите мясное угощение Тону Поклону Ветра на заставу Зловещего Тотема в Когтистых горах.','<Тон и его телохранители набрасываются на угощение.>$B$BТакой… Такой вкуснятины я в жизни не ел. Вы можете стать хорошими союзниками, но прежде чем клан Зловещего Тотема согласится сотрудничать с Альянсом, вы должны принять наши условия. Я передам их так, как наказал мне наш вождь. Передай их своему командиру и посмотрим, примет ли он их.','<Тон Поклон Ветра принюхивается и поднимает левую руку.>$B$BТы что-то нам принесла?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сколько дикого дверя ни корми',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите мясное угощение Тону Поклону Ветра на заставу Зловещего Тотема в Когтистых горах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Тон и его телохранители набрасываются на угощение.>$B$BТакой… Такой вкуснятины я в жизни не ел. Вы можете стать хорошими союзниками, но прежде чем клан Зловещего Тотема согласится сотрудничать с Альянсом, вы должны принять наши условия. Я передам их так, как наказал мне наш вождь. Передай их своему командиру и посмотрим, примет ли он их.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Тон Поклон Ветра принюхивается и поднимает левую руку.>$B$BТы что-то нам принесла?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (25845,'Условия службы') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Условия службы',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (25846,'Грундиг Темное Облако, вождь клана Зловещего Тотема','Доставьте ящики с оружием Альянса Грундигу Темному Облаку на заставу Зловещего Тотема в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Грундиг Темное Облако, вождь клана Зловещего Тотема',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте ящики с оружием Альянса Грундигу Темному Облаку на заставу Зловещего Тотема в Когтистых горах.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25847,'Превосходство Зловещего Тотема','Используйте оружие из ящика с оружием Альянса, чтобы вооружить 12 воинов клана Зловещего Тотема.','Вернитесь к Грундигу Темному Облаку, находящемуся на заставе Зловещего Тотема в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Превосходство Зловещего Тотема',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте оружие из ящика с оружием Альянса, чтобы вооружить 12 воинов клана Зловещего Тотема.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Грундигу Темному Облаку, находящемуся на заставе Зловещего Тотема в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25848,'Падение','Убейте генералов Орды в лагере Апарахе и добудьте знак различия генерала Орды.','<Грундиг ломает знаки отличия в своем огромном кулаке.>$B$BДа, друг, ты это сделала! От такого удара Адский Крик много недель не оправится. Южная область Когтистых гор принадлежит Зловещему Тотему… И Альянсу, конечно же.','Генералы убиты?','Вернитесь к Грундигу Темному Облаку, находящемуся на заставе Зловещего Тотема в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Падение',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте генералов Орды в лагере Апарахе и добудьте знак различия генерала Орды.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Грундиг ломает знаки отличия в своем огромном кулаке.>$B$BДа, друг, ты это сделала! От такого удара Адский Крик много недель не оправится. Южная область Когтистых гор принадлежит Зловещему Тотему… И Альянсу, конечно же.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Генералы убиты?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Грундигу Темному Облаку, находящемуся на заставе Зловещего Тотема в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (25849,'Ожившие ископаемые','Послушай, $gдружище:подруга;. Любой нормальный археолог знает, что работа у него рискованная. Как осторожно ни копай, все равно хоть раз да разбудишь древнее зло или будешь проклят злыми духами, такое с каждым случается!$B$BНет, настоящие профессионалы знают, что всякая мелочь вроде оживших костей – не повод прерывать раскопки.$B$BНо сами кости мне нужны, поэтому ты займись-ка этими ископаемыми тварями, что бегают вокруг. Разбери их на составные части и принеси мне. Вознаграждение гарантирую.','Вернитесь к геологу Вельгару на Раскопки Вельгара, что в Болотине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ожившие ископаемые',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Послушай, $gдружище:подруга;. Любой нормальный археолог знает, что работа у него рискованная. Как осторожно ни копай, все равно хоть раз да разбудишь древнее зло или будешь проклят злыми духами, такое с каждым случается!$B$BНет, настоящие профессионалы знают, что всякая мелочь вроде оживших костей – не повод прерывать раскопки.$B$BНо сами кости мне нужны, поэтому ты займись-ка этими ископаемыми тварями, что бегают вокруг. Разбери их на составные части и принеси мне. Вознаграждение гарантирую.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к геологу Вельгару на Раскопки Вельгара, что в Болотине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25850,'Бей прямо по земле!','Если ты еще не $gзаметил:заметила;, тут, в Болотине, все вверх тормашками. Наводнения, землетрясения... а теперь еще сама почва стала такие чудеса выкидывать, что диву даешься.$B$BВ жизни бы не подумал, что на меня может напасть моя собственная работа, но вот поди ж ты: здоровенные куски земли так и носятся туда-сюда и норовят расплющить все живое.$B$BВид у тебя внушительный, |3-6($r)... Может, спустишься туда и наведешь порядок?','Убейте 7 палеолитических элементалей.','Во, задал ты им жару! Молодчага.','Вернитесь к Ормеру Сталеплету в Укрытие Вельгара, что в Болотине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бей прямо по земле!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если ты еще не $gзаметил:заметила;, тут, в Болотине, все вверх тормашками. Наводнения, землетрясения... а теперь еще сама почва стала такие чудеса выкидывать, что диву даешься.$B$BВ жизни бы не подумал, что на меня может напасть моя собственная работа, но вот поди ж ты: здоровенные куски земли так и носятся туда-сюда и норовят расплющить все живое.$B$BВид у тебя внушительный, |3-6($r)... Может, спустишься туда и наведешь порядок?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 7 палеолитических элементалей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Во, задал ты им жару! Молодчага.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ормеру Сталеплету в Укрытие Вельгара, что в Болотине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (25851,'Танцы со Зловещим Тотемом','Возвращайся к своему командиру и расскажи ему о том, что ты $gсделал:сделала; для клана Зловещего Тотема. Скажи ему, что Альянс теперь может спокойно ходить по нашим землям.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Танцы со Зловещим Тотемом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Возвращайся к своему командиру и расскажи ему о том, что ты $gсделал:сделала; для клана Зловещего Тотема. Скажи ему, что Альянс теперь может спокойно ходить по нашим землям.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (25852,'Все чисто','Так значит, клан Зловещего Тотема нам больше не враг? Замечательно, но тут и без него Орды выше крыши!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Все чисто',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так значит, клан Зловещего Тотема нам больше не враг? Замечательно, но тут и без него Орды выше крыши!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25853,'Быстро поднятое не считается упавшим','Я здесь отвечаю за снабжение. Я, конечно, все понимаю, но удирать оттуда налегке было не лучшей идеей.$B$BВидишь ли, без инструментов археологу особо не работается. Как прикажешь доставать из земли бесценные находки – голыми руками, что ли? Если вернешься на место раскопок, забери инструменты, которые мы там побросали, ладно?','Соберите 6 инструментов археолога.','Вот это облегчение! Теперь, по крайней мере, сможем копать или не копать, а то до этого могли только не копать.$B$BНе обращай внимания, археологический юмор.','Здесь хоть все? Мы там много чего побросали.','Вернитесь к Меррину Камнепряду в Укрытие Вельгара, что в Болотине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Быстро поднятое не считается упавшим',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я здесь отвечаю за снабжение. Я, конечно, все понимаю, но удирать оттуда налегке было не лучшей идеей.$B$BВидишь ли, без инструментов археологу особо не работается. Как прикажешь доставать из земли бесценные находки – голыми руками, что ли? Если вернешься на место раскопок, забери инструменты, которые мы там побросали, ладно?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 6 инструментов археолога.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот это облегчение! Теперь, по крайней мере, сможем копать или не копать, а то до этого могли только не копать.$B$BНе обращай внимания, археологический юмор.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Здесь хоть все? Мы там много чего побросали.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Меррину Камнепряду в Укрытие Вельгара, что в Болотине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25854,'Домашний Кусандр','Подумать только – оказывается, некоторые ящеры до того умны, что из них может получиться домашний питомец! Серьезно! Я видел, как охотники их приручают.$B$BТут иногда бывает очень одиноко, даже в компании Венны... Питомец – это то, что мне нужно. Крошка-ящерчик – я назову его Кусандром – представляешь, как с ним будет весело!$B$BРаз ты там все равно уничтожаешь взрослых особей, может, принесешь мне несколько яиц? Мне нужны те, из которых детеныши уже готовы вылупиться. Их в два счета отличишь – они аж подпрыгивают.','Соберите 6 подпрыгивающих яиц ящеров.','Великолепно! Эти за день должны вылупиться…$B$BТеперь нужно только соорудить загон для ящеров, пока они все не повылезали одновременно из своих яиц. У меня все продумано. Успех гарантирован!','Ну как, набралось яичек? Одного-то ведь мало – слишком рискованно, вдруг что-то не получится. Шансы на успех надо повысить.','Вернитесь к Фрадду Бынструменту на станцию Бынструмента.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Домашний Кусандр',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Подумать только – оказывается, некоторые ящеры до того умны, что из них может получиться домашний питомец! Серьезно! Я видел, как охотники их приручают.$B$BТут иногда бывает очень одиноко, даже в компании Венны... Питомец – это то, что мне нужно. Крошка-ящерчик – я назову его Кусандром – представляешь, как с ним будет весело!$B$BРаз ты там все равно уничтожаешь взрослых особей, может, принесешь мне несколько яиц? Мне нужны те, из которых детеныши уже готовы вылупиться. Их в два счета отличишь – они аж подпрыгивают.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 6 подпрыгивающих яиц ящеров.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Великолепно! Эти за день должны вылупиться…$B$BТеперь нужно только соорудить загон для ящеров, пока они все не повылезали одновременно из своих яиц. У меня все продумано. Успех гарантирован!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как, набралось яичек? Одного-то ведь мало – слишком рискованно, вдруг что-то не получится. Шансы на успех надо повысить.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фрадду Бынструменту на станцию Бынструмента.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25855,'Плоды инженерной мысли','В последнее время мне стало не хватать деталей для инженерных конструкций, а теперь до меня, наконец, дошло: их воруют гноллы из стаи Мохошкуров!$B$BПонятия не имею, для чего детальки могли понадобиться гноллам, но мне они нужней. Их поди уже по всей топи растащили. Если найдешь что-нибудь, верни мне, ладно?','Найдите 7 механизмов Бынструмента.','О, чудесно! Я прямо сейчас начну их собирать. Спасибо огромное!','Нашлось что-нибудь?','Вернитесь к Фрадду Бынструменту на станцию Бынструмента, что в Болотине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Плоды инженерной мысли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В последнее время мне стало не хватать деталей для инженерных конструкций, а теперь до меня, наконец, дошло: их воруют гноллы из стаи Мохошкуров!$B$BПонятия не имею, для чего детальки могли понадобиться гноллам, но мне они нужней. Их поди уже по всей топи растащили. Если найдешь что-нибудь, верни мне, ладно?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите 7 механизмов Бынструмента.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, чудесно! Я прямо сейчас начну их собирать. Спасибо огромное!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Нашлось что-нибудь?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фрадду Бынструменту на станцию Бынструмента, что в Болотине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25856,'Шкуры кроколисков','Я уже многие годы добываю в этих краях шкуры кроколисков, |3-6($c). Но кое-что изменилось.$B$BНе хочу докучать тебе слезливой историей, но, в общем, когда случился Катаклизм и Гавань Менетилов затопило, мой дом оказался под водой. Теперь жене и детишкам некуда податься, поэтому мне нужно заработать денег на новое жилище.$B$BУ меня уже руки от усталости отваливаются, но шкур все равно не хватает – нужно еще. Принеси мне несколько, я заплачу.','Добудьте 10 шкур болотного кроколиска.','Вернитесь к Джеймсу Халлорану на станцию Бынструмента, что в Болотине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Шкуры кроколисков',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я уже многие годы добываю в этих краях шкуры кроколисков, |3-6($c). Но кое-что изменилось.$B$BНе хочу докучать тебе слезливой историей, но, в общем, когда случился Катаклизм и Гавань Менетилов затопило, мой дом оказался под водой. Теперь жене и детишкам некуда податься, поэтому мне нужно заработать денег на новое жилище.$B$BУ меня уже руки от усталости отваливаются, но шкур все равно не хватает – нужно еще. Принеси мне несколько, я заплачу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 10 шкур болотного кроколиска.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джеймсу Халлорану на станцию Бынструмента, что в Болотине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25857,'Охота на Челюсти Кошмара','Меня давно терзает искушение отправиться на большую охоту... на Челюсти Кошмара – это самый здоровый кроколиск из всех, что я видел. Добыть бы его шкуру – этих денег моей семье с лихвой хватит на то, чтобы выбраться отсюда.$B$BНо я не дурак. Одна ошибка – и я останусь без ноги, а то и вовсе без головы. Кто тогда прокормит мою семью?$B$BДа, гордиться нечем, но я предпочитаю не рисковать понапрасну. Пожалуйста, |3-6($c), помоги... убей Челюсти Кошмара за меня. На севере есть мутный пруд – там ты найдешь этого зверюгу.','Убейте Челюсти Кошмара и заберите его шкуру.','Вернитесь к Джеймсу Халлорану на станцию Бынструмента.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота на Челюсти Кошмара',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Меня давно терзает искушение отправиться на большую охоту... на Челюсти Кошмара – это самый здоровый кроколиск из всех, что я видел. Добыть бы его шкуру – этих денег моей семье с лихвой хватит на то, чтобы выбраться отсюда.$B$BНо я не дурак. Одна ошибка – и я останусь без ноги, а то и вовсе без головы. Кто тогда прокормит мою семью?$B$BДа, гордиться нечем, но я предпочитаю не рисковать понапрасну. Пожалуйста, |3-6($c), помоги... убей Челюсти Кошмара за меня. На севере есть мутный пруд – там ты найдешь этого зверюгу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Челюсти Кошмара и заберите его шкуру.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джеймсу Халлорану на станцию Бынструмента.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25858,'Просьба госпожи','Леди Сира\'кесс уже начала готовиться к ритуалу призыва, но у нас украли тигель Наз\'жар. Очевидно, его прихватили с собой квалдиры, когда бежали на мелководье.$B$BПоговори с лидерами каст, собери отряд и веди его на восток, к гряде Бейл\'аран, чтобы вернуть украденный артефакт.$B$BЯ не сомневаюсь в тебе, Воительница, ибо ты ни разу меня не подводила. Сколь сильно меня почитает Королева, столь сильно почитаю тебя я. Даю тебе свое благословение.','Поговорите с Повелителем глубин Зин\'жатаром, Леди Сира\'кесс и надзирателем Идра\'кессом.$B$BЭто задание из цикла "Видения воительницы Леди Наз\'жар". Чтобы вернуться к видению, в нужном месте воспользуйтесь клинком воительницы Леди Наз\'жар.','Наши воины уже расположились вокруг рифа. Они готовы к атаке и ждут твоих указаний.','Найдите подводного ловчего Азжентуса на гряде Бейл\'аран к востоку от Руин Вайш\'ира и на противоположной стороне Раздробленного надела.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Просьба госпожи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Леди Сира\'кесс уже начала готовиться к ритуалу призыва, но у нас украли тигель Наз\'жар. Очевидно, его прихватили с собой квалдиры, когда бежали на мелководье.$B$BПоговори с лидерами каст, собери отряд и веди его на восток, к гряде Бейл\'аран, чтобы вернуть украденный артефакт.$B$BЯ не сомневаюсь в тебе, Воительница, ибо ты ни разу меня не подводила. Сколь сильно меня почитает Королева, столь сильно почитаю тебя я. Даю тебе свое благословение.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Повелителем глубин Зин\'жатаром, Леди Сира\'кесс и надзирателем Идра\'кессом.$B$BЭто задание из цикла "Видения воительницы Леди Наз\'жар". Чтобы вернуться к видению, в нужном месте воспользуйтесь клинком воительницы Леди Наз\'жар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Наши воины уже расположились вокруг рифа. Они готовы к атаке и ждут твоих указаний.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Найдите подводного ловчего Азжентуса на гряде Бейл\'аран к востоку от Руин Вайш\'ира и на противоположной стороне Раздробленного надела.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25859,'Посторонним вход запрещен','Знаю, что тебя, как и нашу достопочтенную госпожу, порой охватывает жалость и милосердие. Но сегодня я настоятельно советую забыть о доброте: квалдиры – гордый народ, и они обязательно вернутся, чтобы отомстить, если мы их полностью не уничтожим. Так что убей всех, кого встретишь.$B$BУвы, моя задача скучна – следить за тем, чтобы никто из них не вернулся в город. А вот тебе досталось все самое интересное. Я буду болеть за тебя.','Убейте 20 квалдиров на выступе Врайкулов.$B$BЭто задание из цикла "Видения воительницы Леди Наз\'жар". Чтобы вернуться к видению, в нужном месте воспользуйтесь клинком воительницы Леди Наз\'жар.','Никто из них не прорвался к мосту. Ни один квалдир, даже самый захудаленький.$B$BПризнаться, было очень скучно. Надеюсь, в следующий раз ты поделишься со мной работой.','Вернитесь к подводному ловчему Азжентусу на гряду Бейл\'аран.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Посторонним вход запрещен',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Знаю, что тебя, как и нашу достопочтенную госпожу, порой охватывает жалость и милосердие. Но сегодня я настоятельно советую забыть о доброте: квалдиры – гордый народ, и они обязательно вернутся, чтобы отомстить, если мы их полностью не уничтожим. Так что убей всех, кого встретишь.$B$BУвы, моя задача скучна – следить за тем, чтобы никто из них не вернулся в город. А вот тебе досталось все самое интересное. Я буду болеть за тебя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 20 квалдиров на выступе Врайкулов.$B$BЭто задание из цикла "Видения воительницы Леди Наз\'жар". Чтобы вернуться к видению, в нужном месте воспользуйтесь клинком воительницы Леди Наз\'жар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Никто из них не прорвался к мосту. Ни один квалдир, даже самый захудаленький.$B$BПризнаться, было очень скучно. Надеюсь, в следующий раз ты поделишься со мной работой.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к подводному ловчему Азжентусу на гряду Бейл\'аран.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25860,'Любой ценой','Необходимо немедленно приступить к ритуалу, а твоя задача – обеспечить, чтобы никто его не прервал.$B$BУбей всех квалдиров, которые зайдут в храм. Мои жрицы должны выполнить свою задачу любой ценой.','Убейте 20 квалдиров в храме Кель\'Дормир.$B$BЭто задание из цикла "Видения воительницы Леди Наз\'жар". Чтобы вернуться к видению, в нужном месте воспользуйтесь клинком воительницы Леди Наз\'жар.','Азжентус сдержит свое слово. Отважные стражи Леди Наз\'жар должны справиться с охраной. Они не допустят прерывания ритуала.','Вернитесь к Леди Сира\'кесс на верхний ярус храма Кель\'Дормир.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Любой ценой',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Необходимо немедленно приступить к ритуалу, а твоя задача – обеспечить, чтобы никто его не прервал.$B$BУбей всех квалдиров, которые зайдут в храм. Мои жрицы должны выполнить свою задачу любой ценой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 20 квалдиров в храме Кель\'Дормир.$B$BЭто задание из цикла "Видения воительницы Леди Наз\'жар". Чтобы вернуться к видению, в нужном месте воспользуйтесь клинком воительницы Леди Наз\'жар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Азжентус сдержит свое слово. Отважные стражи Леди Наз\'жар должны справиться с охраной. Они не допустят прерывания ритуала.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Леди Сира\'кесс на верхний ярус храма Кель\'Дормир.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25861,'Показательный пример','В соседних постройках обосновались верховные шаманы. Вовсю распевают свои песни и дерзят, но выйти ко мне не решаются. Эти квалдиры храбры и сильны только во мгле – жалкое недоразумение, населившее подводный мир.$B$BУ меня есть некое послание. И если ваша светлость не слишком занята, прошу вас, приведите ко мне одного из верховных шаманов, чтобы я смог лично донести это послание до него и его народа.','Приведите квалдирского верховного шамана к палачу Вератрессу.$B$BЭто задание из цикла "Видения воительницы Леди Наз\'жар". Чтобы вернуться к видению, в нужном месте воспользуйтесь клинком воительницы Леди Наз\'жар.','Моя коса обагрилась кровью. Благодарю, моя госпожа.','Если ваша светлость не слишком занята, прошу вас, приведите ко мне одного из верховных шаманов, чтобы я смог лично донести это послание до него и его народа.','Поговорите с палачом Вератрессом на гряде Бейл\'аран.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Показательный пример',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В соседних постройках обосновались верховные шаманы. Вовсю распевают свои песни и дерзят, но выйти ко мне не решаются. Эти квалдиры храбры и сильны только во мгле – жалкое недоразумение, населившее подводный мир.$B$BУ меня есть некое послание. И если ваша светлость не слишком занята, прошу вас, приведите ко мне одного из верховных шаманов, чтобы я смог лично донести это послание до него и его народа.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Приведите квалдирского верховного шамана к палачу Вератрессу.$B$BЭто задание из цикла "Видения воительницы Леди Наз\'жар". Чтобы вернуться к видению, в нужном месте воспользуйтесь клинком воительницы Леди Наз\'жар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Моя коса обагрилась кровью. Благодарю, моя госпожа.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если ваша светлость не слишком занята, прошу вас, приведите ко мне одного из верховных шаманов, чтобы я смог лично донести это послание до него и его народа.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с палачом Вератрессом на гряде Бейл\'аран.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25862,'Украденное имущество','Достопочтенная госпожа отправила меня к тебе на помощь. Она желает, чтобы ты вернула украденный тигель Наз\'жар как можно скорее.$B$BОна должна приступить к ритуалу призыва – и мы начнем готовиться к войне.','Верните украденный тигель Наз\'жар.$B$BЭто задание из цикла "Видения воительницы Леди Наз\'жар". Чтобы вернуться к видению, в нужный момент воспользуйтесь клинком воительницы Леди Наз\'жар.','Судя по всему, в одиночку вы тигель не дотащите, но здесь достаточно наг – они и могут понести.','Верните тигель Наз\'жар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Украденное имущество',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Достопочтенная госпожа отправила меня к тебе на помощь. Она желает, чтобы ты вернула украденный тигель Наз\'жар как можно скорее.$B$BОна должна приступить к ритуалу призыва – и мы начнем готовиться к войне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните украденный тигель Наз\'жар.$B$BЭто задание из цикла "Видения воительницы Леди Наз\'жар". Чтобы вернуться к видению, в нужный момент воспользуйтесь клинком воительницы Леди Наз\'жар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Судя по всему, в одиночку вы тигель не дотащите, но здесь достаточно наг – они и могут понести.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Верните тигель Наз\'жар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25863,'Избранный груз','Тигель Наз\'жар найден, и теперь осталось лишь доложить Леди Наз\'жар об успехе.','Вернитесь на запад гряды Бейл\'аран и сообщите новости о тигле Наз\'жар.$B$BЭто задание из цикла "Видения воительницы Леди Наз\'жар". Чтобы вернуться к видению, в нужный момент воспользуйтесь клинком воительницы Леди Наз\'жар.','Великолепно, Воительница.$B$BЭтот тигель послужит источником силы для ритуала призыва. С его помощью Сира\'кесс призовет из пучин союзников, которые пополнят и без того немалые ряды наших бойцов.','Вернитесь на запад гряды Бейл\'аран и расскажите новости о тигле Наз\'жар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Избранный груз',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тигель Наз\'жар найден, и теперь осталось лишь доложить Леди Наз\'жар об успехе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь на запад гряды Бейл\'аран и сообщите новости о тигле Наз\'жар.$B$BЭто задание из цикла "Видения воительницы Леди Наз\'жар". Чтобы вернуться к видению, в нужный момент воспользуйтесь клинком воительницы Леди Наз\'жар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Великолепно, Воительница.$B$BЭтот тигель послужит источником силы для ритуала призыва. С его помощью Сира\'кесс призовет из пучин союзников, которые пополнят и без того немалые ряды наших бойцов.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь на запад гряды Бейл\'аран и расскажите новости о тигле Наз\'жар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25864,'Неприятности с динозаврами','Ящеры у нас тут совсем расшалились. Моя задача – следить за тем, чтобы это место оставалось безопасным и привлекательным для новых поселенцев, поэтому я назначила за головы тварей награду.$B$BОт многих мы уже избавились, но вот ящеров нагорья, что обитают на севере, становится все больше. Хотя у нас теперь есть кому с ними разобраться, не так ли?$B$BПеребей этих ящеров и возвращайся за наградой.','Убейте 8 ящеров нагорья любого вида.','Отлично. Считай, что награду свою получаешь не от меня, но от Стальгорна. Спасти Каз Модан – этого хотят все дворфы.','Вернитесь к Шейле Крепкой Стамеске на станцию Бынструмента, что в Болотине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Неприятности с динозаврами',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ящеры у нас тут совсем расшалились. Моя задача – следить за тем, чтобы это место оставалось безопасным и привлекательным для новых поселенцев, поэтому я назначила за головы тварей награду.$B$BОт многих мы уже избавились, но вот ящеров нагорья, что обитают на севере, становится все больше. Хотя у нас теперь есть кому с ними разобраться, не так ли?$B$BПеребей этих ящеров и возвращайся за наградой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 ящеров нагорья любого вида.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично. Считай, что награду свою получаешь не от меня, но от Стальгорна. Спасти Каз Модан – этого хотят все дворфы.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Шейле Крепкой Стамеске на станцию Бынструмента, что в Болотине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25866,'Звероловы из клана Черного Железа','Мне доложили, что к нам в гости нагрянул клан Черного Железа, возможно, ты уже $gвидел:видела; их. У этих дворфов вечно недоброе на уме, а теперь они еще стали зачем-то похищать гноллов из стаи Мохошкуров.$B$BНе понимаю, что они затевают, но этому надо положить конец, пока они еще чего похуже не удумали. Остановить этих дворфов – твоя задача.$B$BА если тебе хочется сделать все по-благородному – попробуй-ка сначала у них вежливо поинтересоваться, что это они замыслили. Увидишь, что получится.','Убейте 10 звероловов из клана Черного Железа.','Смотрю, мирно этот вопрос уладить не получилось? Ага, так я и думала.','Вернитесь к Шейле Крепкой Стамеске на станцию Бынструмента, что в Болотине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Звероловы из клана Черного Железа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне доложили, что к нам в гости нагрянул клан Черного Железа, возможно, ты уже $gвидел:видела; их. У этих дворфов вечно недоброе на уме, а теперь они еще стали зачем-то похищать гноллов из стаи Мохошкуров.$B$BНе понимаю, что они затевают, но этому надо положить конец, пока они еще чего похуже не удумали. Остановить этих дворфов – твоя задача.$B$BА если тебе хочется сделать все по-благородному – попробуй-ка сначала у них вежливо поинтересоваться, что это они замыслили. Увидишь, что получится.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 звероловов из клана Черного Железа.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Смотрю, мирно этот вопрос уладить не получилось? Ага, так я и думала.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Шейле Крепкой Стамеске на станцию Бынструмента, что в Болотине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25867,'Свободу гноллам','Да мы и сами гноллов не больно-то жалуем, но это не значит, что можно позволять Черному Железу делать из них рабов. Понимаешь, гноллы нас обворовали, мы им за это вломили – все по справедливости; а тут их хотят использовать в каких-то злодейских целях. Этого я сделать не позволю.$B$BКороче говоря, гноллов надо освободить. У звероловов должны быть при себе ключи – забери их и отопри клетки.','Заберите ключи зверолова у звероловов из клана Черного Железа, отоприте клетки гноллов и выпустите на волю 6 гноллов.','Отлично! Чем больше гноллов им придется ловить заново, тем легче будет этих дворфов держать в узде.','Вернитесь к Шейле Крепкой Стамеске на станцию Бынструмента, что в Болотине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Свободу гноллам',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Да мы и сами гноллов не больно-то жалуем, но это не значит, что можно позволять Черному Железу делать из них рабов. Понимаешь, гноллы нас обворовали, мы им за это вломили – все по справедливости; а тут их хотят использовать в каких-то злодейских целях. Этого я сделать не позволю.$B$BКороче говоря, гноллов надо освободить. У звероловов должны быть при себе ключи – забери их и отопри клетки.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заберите ключи зверолова у звероловов из клана Черного Железа, отоприте клетки гноллов и выпустите на волю 6 гноллов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! Чем больше гноллов им придется ловить заново, тем легче будет этих дворфов держать в узде.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Шейле Крепкой Стамеске на станцию Бынструмента, что в Болотине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (25868,'Йорла Темная Петля','Я, наконец, выяснила, кто стоит во главе всей этой операции. Приказы дворфам Черного Железа исходят из лагеря на востоке, от Йорлы Темной Петли. Возможно даже, что это именно по ее наущению гноллы и решились украсть золото Стальгорна.$B$BСкажу больше – она известная преступница, и за ее голову назначена награда... Она призывала дворфов восстать против Стальгорна еще в те времена, когда Магни был жив.$B$BТакой шанс нельзя упустить, $n. Иди и прикончи ее!','Убейте Йорлу Темную Петлю.','Вернитесь к Шейле Крепкой Стамеске на станцию Бынструмента, что в Болотине.','Иди и убей ее!','Йорла Темная Петля') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Йорла Темная Петля',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я, наконец, выяснила, кто стоит во главе всей этой операции. Приказы дворфам Черного Железа исходят из лагеря на востоке, от Йорлы Темной Петли. Возможно даже, что это именно по ее наущению гноллы и решились украсть золото Стальгорна.$B$BСкажу больше – она известная преступница, и за ее голову назначена награда... Она призывала дворфов восстать против Стальгорна еще в те времена, когда Магни был жив.$B$BТакой шанс нельзя упустить, $n. Иди и прикончи ее!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Йорлу Темную Петлю.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Шейле Крепкой Стамеске на станцию Бынструмента, что в Болотине.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Иди и убей ее!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Йорла Темная Петля',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25869,'Выдворение Зловещего Тотема','Да, зловещие новости для захватчиков.<Квентин деликатно откашливается.>$B$BПрости за каламбур.','Вернитесь к Квентину на заставу Вольного Ветра в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Выдворение Зловещего Тотема',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, зловещие новости для захватчиков.<Квентин деликатно откашливается.>$B$BПрости за каламбур.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Квентину на заставу Вольного Ветра в Тысяче Игл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25870,'Выдворение Зловещего Тотема','Для начала очень неплохо. В обычное время я не причинила бы вреда никому из детей Матери-Земли.$B$BНо напасть на нас, когда мы были больше всего уязвимы!.. Они заслужили смерть!','Вернитесь с Талией Янтарной Шкурой на Заставе Вольного Ветра в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Выдворение Зловещего Тотема',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Для начала очень неплохо. В обычное время я не причинила бы вреда никому из детей Матери-Земли.$B$BНо напасть на нас, когда мы были больше всего уязвимы!.. Они заслужили смерть!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь с Талией Янтарной Шкурой на Заставе Вольного Ветра в Тысяче Игл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (25871,'Спасение часового','<Бриенна размахивает запиской, испещренной тауренскими письменами.>$B$BЭти чудовища захватили одну из наших часовых! И угрожают убить ее, если мы не отступим!$B$BНо мы не ведем переговоров с трусливыми врагами! Пожалуйста, вызволи ее, пока еще не слишком поздно, |3-6($c).','Освободите часового Фераласа.','Вернитесь к Бриенне Мерцание Звезд на заставу Вольного Ветра в Тысяче Игл.','Освободи ее, пока не стало слишком поздно.','Пойманный часовой Фераласа') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спасение часового',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Бриенна размахивает запиской, испещренной тауренскими письменами.>$B$BЭти чудовища захватили одну из наших часовых! И угрожают убить ее, если мы не отступим!$B$BНо мы не ведем переговоров с трусливыми врагами! Пожалуйста, вызволи ее, пока еще не слишком поздно, |3-6($c).',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Освободите часового Фераласа.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бриенне Мерцание Звезд на заставу Вольного Ветра в Тысяче Игл.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Освободи ее, пока не стало слишком поздно.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Пойманный часовой Фераласа',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (25872,'Без страха и упрека','Выручите храбреца заставы Вольного Ветра.','Вернитесь к Рау Скальному Бегуну на заставу Вольного Ветра в Тысяче Игл.','Освободите его, пока не поздно.','Пойманный храбрец с Заставы Вольного Ветра') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Без страха и упрека',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выручите храбреца заставы Вольного Ветра.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Рау Скальному Бегуну на заставу Вольного Ветра в Тысяче Игл.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Освободите его, пока не поздно.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Пойманный храбрец с Заставы Вольного Ветра',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (25873,'Рог предателя','Вы натыкаетесь на бренное тело Монтарра, сказителя заставы Вольного Ветра. Тело престарелого таурена переломано и лежит в луже его собственной крови.$B$BДорожка из алых капель стелется к дверям таверны...','Добудьте рог Долгорога.','Вернитесь к Квентину на заставу Вольного Ветра в Тысяче Игл.','Предатель! Лишите его оставшегося рога!','Дозорный утесов Долгорог') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рог предателя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы натыкаетесь на бренное тело Монтарра, сказителя заставы Вольного Ветра. Тело престарелого таурена переломано и лежит в луже его собственной крови.$B$BДорожка из алых капель стелется к дверям таверны...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте рог Долгорога.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Квентину на заставу Вольного Ветра в Тысяче Игл.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Предатель! Лишите его оставшегося рога!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Дозорный утесов Долгорог',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (25874,'Рог предателя','Вы натыкаетесь на бренное тело Монтарра, сказителя заставы Вольного Ветра. Тело престарелого таурена переломано и лежит в луже его собственной крови.$B$BДорожка из алых капель стелется к дверям таверны...','Добудьте рог Долгорога.','Дозорный утесов был шпионом Зловещего Тотема?! Неудивительно, что они застали нас врасплох!$B$B<Талия буквально кипит от гнева.>$B$BМне не нужна эта дрянь. Выброси ее в воду, и да будет имя Долгорога навеки забыто!','Вернитесь к Талии Янтарной Шкуре на заставу Вольного Ветра в Тысяче Игл.','Предатель! Лишите его оставшегося рога!','Дозорный утесов Долгорог') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рог предателя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы натыкаетесь на бренное тело Монтарра, сказителя заставы Вольного Ветра. Тело престарелого таурена переломано и лежит в луже его собственной крови.$B$BДорожка из алых капель стелется к дверям таверны...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте рог Долгорога.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Дозорный утесов был шпионом Зловещего Тотема?! Неудивительно, что они застали нас врасплох!$B$B<Талия буквально кипит от гнева.>$B$BМне не нужна эта дрянь. Выброси ее в воду, и да будет имя Долгорога навеки забыто!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Талии Янтарной Шкуре на заставу Вольного Ветра в Тысяче Игл.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Предатель! Лишите его оставшегося рога!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Дозорный утесов Долгорог',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (25875,'Гном с той стороны','Туманное озеро кишит тварями Орды. Гоблины устроили там завод и не собираются оттуда уходить, пока не выкачают всю нефть из Когтистых гор.$B$BПо счастью, на той стороне у меня есть один гном, который собирает для нас информацию. Если кто и знает, что происходит с той бомбой, то это мой засланный гном.$B$BОтправляйся к илоразработкам, что к северу отсюда, и найди Минкс. Она будет переодета в гоблина техника помпы.','Забирайся сюда и прижмись к стене! Я не могу рисковать своим прикрытием!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гном с той стороны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Туманное озеро кишит тварями Орды. Гоблины устроили там завод и не собираются оттуда уходить, пока не выкачают всю нефть из Когтистых гор.$B$BПо счастью, на той стороне у меня есть один гном, который собирает для нас информацию. Если кто и знает, что происходит с той бомбой, то это мой засланный гном.$B$BОтправляйся к илоразработкам, что к северу отсюда, и найди Минкс. Она будет переодета в гоблина техника помпы.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Забирайся сюда и прижмись к стене! Я не могу рисковать своим прикрытием!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25876,'Это там!','Слушай, я отслеживала эту бомбу с тех пор, как ты $gспас:спасла; меня в Ясеневом лесу. Что бы они ни намеревались с ней сделать, это случится скоро.$B$BНа вершине большой буровой вышки находится диспетчерская. В ней ты найдешь Кром\'гарский буровой журнал. В нем ключ к тому, для чего предназначена эта бомба. Ступай туда и добудь журнал! Принеси его сюда, и я его тебе расшифрую.','Украдите Кром\'гарский буровой журнал.','О НЕТ! Они намерены испытать бомбу на Роще Тал\'дара! Там же школа молодых друидов, прямо в сердце долины Боевого Шрама. Возвращайся к Барусу с этими сведениями! Нужно предупредить мастера Тал\'дару!','Удалось достать журнал?','Вернитесь к "гоблину" – смотрителю помпы на Илоразработки в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Это там!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слушай, я отслеживала эту бомбу с тех пор, как ты $gспас:спасла; меня в Ясеневом лесу. Что бы они ни намеревались с ней сделать, это случится скоро.$B$BНа вершине большой буровой вышки находится диспетчерская. В ней ты найдешь Кром\'гарский буровой журнал. В нем ключ к тому, для чего предназначена эта бомба. Ступай туда и добудь журнал! Принеси его сюда, и я его тебе расшифрую.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Украдите Кром\'гарский буровой журнал.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О НЕТ! Они намерены испытать бомбу на Роще Тал\'дара! Там же школа молодых друидов, прямо в сердце долины Боевого Шрама. Возвращайся к Барусу с этими сведениями! Нужно предупредить мастера Тал\'дару!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось достать журнал?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к "гоблину" – смотрителю помпы на Илоразработки в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (25877,'Не время раскланиваться!','Вернитесь к командиру разведчиков Барусу на пост на Мутном озере в Когтистых горах.','Проклятая Орда! У меня друзья там, в роще. Надеюсь, ты умеешь летать на гиппогрифе. Мы отправим тебя к мастеру Тал\'даре на дозорный холм немедленно!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Не время раскланиваться!',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь к командиру разведчиков Барусу на пост на Мутном озере в Когтистых горах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Проклятая Орда! У меня друзья там, в роще. Надеюсь, ты умеешь летать на гиппогрифе. Мы отправим тебя к мастеру Тал\'даре на дозорный холм немедленно!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25878,'План саботажа','Гоблины... Каким был бы этот мир без гоблинов? Я тебе скажу, каким: ЧИСТЫМ!$B$BЭти грязные мелкие грязееды понатыкали нефтяных насосов вокруг озера и высасывают оттуда до капли всю нефть, какая только есть в Когтистых горах. А у каждого насоса они поставили по смотрителю, единственная задача которых – следить за насосами, чтобы ничего не пошло вкривь-вкось.$B$BНо кое-что у них-таки пойдет вкривь-вкось.$B$BПеребей смотрителей гоблинских помп и нарушь им управление насосами. Пусть у них насосы порвет!','Используйте пульты управления гоблинскими помпами, чтобы уничтожить 4 гоблинских нефтяных насоса.','Вернитесь к главе разведчиков Ивонии на пост на Мутном озере в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','План саботажа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Гоблины... Каким был бы этот мир без гоблинов? Я тебе скажу, каким: ЧИСТЫМ!$B$BЭти грязные мелкие грязееды понатыкали нефтяных насосов вокруг озера и высасывают оттуда до капли всю нефть, какая только есть в Когтистых горах. А у каждого насоса они поставили по смотрителю, единственная задача которых – следить за насосами, чтобы ничего не пошло вкривь-вкось.$B$BНо кое-что у них-таки пойдет вкривь-вкось.$B$BПеребей смотрителей гоблинских помп и нарушь им управление насосами. Пусть у них насосы порвет!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте пульты управления гоблинскими помпами, чтобы уничтожить 4 гоблинских нефтяных насоса.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к главе разведчиков Ивонии на пост на Мутном озере в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25879,'Проблема болвана неотесанного','Тебе приходилось видеть хобгоблинов? Это еще одно мерзкое гоблячье создание. Берешь гоблина, делаешь его еще уродливее, толще, больше и тупее – и вот он, хобгоблин. Добавить мерзостности – и вот она, проблема.$B$BЭти дурни неотесанные шатаются по Илоразработкам и у Мутного озера, а гоблины используют их как грубую рабочую силу.$B$BТопай отсюда и истреби их. Раз и навсегда.','Перебейте 10 болванчиков.','Медленно, но верно мы опустошаем ряды Орды. У них тут земля под ногами гореть будет, когда война начнется по-настоящему.','Вернитесь к главе разведчиков Ивонии на пост на Мутном озере в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Проблема болвана неотесанного',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе приходилось видеть хобгоблинов? Это еще одно мерзкое гоблячье создание. Берешь гоблина, делаешь его еще уродливее, толще, больше и тупее – и вот он, хобгоблин. Добавить мерзостности – и вот она, проблема.$B$BЭти дурни неотесанные шатаются по Илоразработкам и у Мутного озера, а гоблины используют их как грубую рабочую силу.$B$BТопай отсюда и истреби их. Раз и навсегда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Перебейте 10 болванчиков.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Медленно, но верно мы опустошаем ряды Орды. У них тут земля под ногами гореть будет, когда война начнется по-настоящему.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к главе разведчиков Ивонии на пост на Мутном озере в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (25880,'Предупредить мастера Тал\'дару') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Предупредить мастера Тал\'дару',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25881,'Выжившие стражи','Мы держались, сколько могли, |3-6($c). В обжигающем огне... изнемогая от жары... Мы потеряли весь город.$B$BКапитан Железный Лес не захотел отступать, когда нас охватило пламя. Наши войска рассеяны. Может, есть выжившие? Мы могли бы предпринять контратаку!$B$BОтправляйся на Выжженную равнину и спаси выживших стражей, которые оказались отрезаны от основного отряда. Затем найди капитана Железного Леса. Он, должно быть, занял укрепленную позицию где-то в гуще битвы.','Найдите и спасите 8 выживших стражей','Ты собрал всех выживших? Прекрасно. А оставшаяся часть горы исцелилась?$B$BРазрази меня гром! Мы снова оказались на передовой!','Отыщите капитана Железного Леса на Выжженной равнине на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Выжившие стражи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы держались, сколько могли, |3-6($c). В обжигающем огне... изнемогая от жары... Мы потеряли весь город.$B$BКапитан Железный Лес не захотел отступать, когда нас охватило пламя. Наши войска рассеяны. Может, есть выжившие? Мы могли бы предпринять контратаку!$B$BОтправляйся на Выжженную равнину и спаси выживших стражей, которые оказались отрезаны от основного отряда. Затем найди капитана Железного Леса. Он, должно быть, занял укрепленную позицию где-то в гуще битвы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите и спасите 8 выживших стражей',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты собрал всех выживших? Прекрасно. А оставшаяся часть горы исцелилась?$B$BРазрази меня гром! Мы снова оказались на передовой!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отыщите капитана Железного Леса на Выжженной равнине на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25882,'Помощь на ферме','Капитан Тарран просил меня передать тебе благодарность за помощь и поздравления с успешным завершением миссии. Он со своими людьми заканчивает борьбу с троллями и направляется к раненым.$b$bОн также просил меня обратиться к тебе за помощью по проверке отчетов о набегах троллей на ферму Янтарленов. Когда прибудешь туда, спроси сержанта Кремнемолота.','Поговорите с сержантом Кремнемолотом на ферме Янтарленов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Помощь на ферме',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Капитан Тарран просил меня передать тебе благодарность за помощь и поздравления с успешным завершением миссии. Он со своими людьми заканчивает борьбу с троллями и направляется к раненым.$b$bОн также просил меня обратиться к тебе за помощью по проверке отчетов о набегах троллей на ферму Янтарленов. Когда прибудешь туда, спроси сержанта Кремнемолота.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с сержантом Кремнемолотом на ферме Янтарленов.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25883,'Найти и обезвредить','Оружие наг...$B$BОсматривая загоны наг, вы видите десятки одинаковых, стратегически расположенных стоек с трезубцами.$B$BУничтожив это оружие, можно сорвать коварные планы врага...','Уничтожьте 6 комплектов трезубцев наг.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Найти и обезвредить',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Оружие наг...$B$BОсматривая загоны наг, вы видите десятки одинаковых, стратегически расположенных стоек с трезубцами.$B$BУничтожив это оружие, можно сорвать коварные планы врага...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 6 комплектов трезубцев наг.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25884,'Будь что будет!','Ох, да чтоб меня...$B$BПонимаю, наш выживший друг нам добра желает, но ты не забывай, что его все же неслабо контузило.$B$BОт этих мерзких тварей может избавить только топор дворфов, по рукоять загнанный в их черепушки.$B$BНавали кучу из их трупов – пускай дважды подумают, стоит ли зариться на твои прелести.$B$BПомяни мое слово, $gпарнишка:милочка;, этим негодяям вид собственной крови доставляет не больше радости, чем мне или тебе.$B$BТеперь иди и задай им!','Убейте 12 наг Зин\'жатара на Жемчужной ферме в лесу Келп’тар.','Поговорите с Ренделом в Дымчатом гроте в лесу Келп’тар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Будь что будет!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ох, да чтоб меня...$B$BПонимаю, наш выживший друг нам добра желает, но ты не забывай, что его все же неслабо контузило.$B$BОт этих мерзких тварей может избавить только топор дворфов, по рукоять загнанный в их черепушки.$B$BНавали кучу из их трупов – пускай дважды подумают, стоит ли зариться на твои прелести.$B$BПомяни мое слово, $gпарнишка:милочка;, этим негодяям вид собственной крови доставляет не больше радости, чем мне или тебе.$B$BТеперь иди и задай им!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 наг Зин\'жатара на Жемчужной ферме в лесу Келп’тар.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Ренделом в Дымчатом гроте в лесу Келп’тар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25885,'Ой-ой – что со мной?','Ох... да что ж такое?!$B$BВнутри все болит... и крутит...$B$BПохоже... эх... Меня отравили!$B$BНас накормили какими-то странными светящимися водорослями, которые выращиваются у крепости.$B$BМне кажется, живот схватит еще сильнее, если не съесть еще маленько...$B$BПрошу тебя, |3-6($r), принеси водорослей!','Соберите 7 побегов вьющихся водорослей у жнецов Мерцающего хребта на Жемчужной ферме.','Обратитесь к рядовому Полларду в Дымчатом гроте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ой-ой – что со мной?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ох... да что ж такое?!$B$BВнутри все болит... и крутит...$B$BПохоже... эх... Меня отравили!$B$BНас накормили какими-то странными светящимися водорослями, которые выращиваются у крепости.$B$BМне кажется, живот схватит еще сильнее, если не съесть еще маленько...$B$BПрошу тебя, |3-6($r), принеси водорослей!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 7 побегов вьющихся водорослей у жнецов Мерцающего хребта на Жемчужной ферме.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Обратитесь к рядовому Полларду в Дымчатом гроте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25886,'Закрепление успехов','Кажется, последователи культа Сумеречного Молота отступили, чтобы перегруппироваться для нового нападения. Наиболее рьяные адепты остались сзади, чтобы прикрыть тыл. У нас есть возможность ударить по их военачальникам.$B$BОбогни Выжженную равнину и истреби сумеречных полевых командиров.','Истребите 4 сумеречных полевых командиров.','Изумительно! Силы культа Сумеречного Молота, конечно же, снова попробуют взять гору, вот только в бой их больше не поведут тугие на голову капитаны.','Вернитесь к капитану Железному Лесу, находящемуся на Выжженной равнине на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Закрепление успехов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кажется, последователи культа Сумеречного Молота отступили, чтобы перегруппироваться для нового нападения. Наиболее рьяные адепты остались сзади, чтобы прикрыть тыл. У нас есть возможность ударить по их военачальникам.$B$BОбогни Выжженную равнину и истреби сумеречных полевых командиров.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Истребите 4 сумеречных полевых командиров.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Изумительно! Силы культа Сумеречного Молота, конечно же, снова попробуют взять гору, вот только в бой их больше не поведут тугие на голову капитаны.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Железному Лесу, находящемуся на Выжженной равнине на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25887,'Волна разрушения','Наше время здесь истекает. Надо бы выяснить, зачем наги берут пленных, раз уж мы хотим понять, что они тут затевают.$B$BНо прежде надо разрушить их планы!$B$BСделать это трудно – наг там тьма-тьмущая, но у меня есть идея.$B$BЗа стенами этой пещеры вытесненные нагами голодные акулы рыщут в поисках пропитания.$B$BСлабых рыб легко подчинить. Возьми эту сферу внушения, подчини акул и натрави на наг.','С помощью сферы внушения укротите изголодавшихся больших акул, затем натравите их на 12 стражей Зин\'жатара на Жемчужной ферме.','Все вышло, как задумывалось.$B$BТеперь ничто не мешает нам нанести нагам сокрушительный удар.','Поговорите с Эрунаком в Дымчатом гроте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Волна разрушения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наше время здесь истекает. Надо бы выяснить, зачем наги берут пленных, раз уж мы хотим понять, что они тут затевают.$B$BНо прежде надо разрушить их планы!$B$BСделать это трудно – наг там тьма-тьмущая, но у меня есть идея.$B$BЗа стенами этой пещеры вытесненные нагами голодные акулы рыщут в поисках пропитания.$B$BСлабых рыб легко подчинить. Возьми эту сферу внушения, подчини акул и натрави на наг.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','С помощью сферы внушения укротите изголодавшихся больших акул, затем натравите их на 12 стражей Зин\'жатара на Жемчужной ферме.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Все вышло, как задумывалось.$B$BТеперь ничто не мешает нам нанести нагам сокрушительный удар.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Эрунаком в Дымчатом гроте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25888,'Декомпрессия','Воспользуйтесь камнем дыхания Моаны, чтобы выручить 10 пленных солдат на Жемчужной ферме.','Будем надеяться, что освобожденные бойцы теперь в безопасности.$B$BВ награду за твою доблесть прошу тебя принять этот дар.','Поговорите с Моаной в Дымчатом гроте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Декомпрессия',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь камнем дыхания Моаны, чтобы выручить 10 пленных солдат на Жемчужной ферме.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Будем надеяться, что освобожденные бойцы теперь в безопасности.$B$BВ награду за твою доблесть прошу тебя принять этот дар.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Моаной в Дымчатом гроте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (25889,'Спасите детей!','Вернитесь к мастеру Тал\'даре на его дозорный холм в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спасите детей!',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру Тал\'даре на его дозорный холм в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (25890,'Неспира','Я прекрасно знаю, что нам надо сейчас делать, $n.$B$BНаги могли добыть эти жемчужины только в одном месте: в Неспире, древнем существе, живущем в раковине неподалеку от этой пещеры. Одно мне совершенно непонятно – как нагам удалось подчинить себе Неспиру?$B$BРядом с выходом из пещеры небольшое отверстие – через него мы сможем попасть в раковину Неспиры. Но сначала мне нужно найти моего хозяина. Встретимся на месте, у северо-западного входа в раковину Неспиры.','Войдите в раковину Неспиры через северо-западный вход и найдите способ с ней поговорить.','Эрунак хочет, чтобы я выполнил это задание? Ну, хорошо, посмотрим, что нам расскажет это древнее существо.','Найдите способ поговорить с Неспирой','Поговорите с Целителем Земли Дуарном в Неспире в Вайш\'ире.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Неспира',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я прекрасно знаю, что нам надо сейчас делать, $n.$B$BНаги могли добыть эти жемчужины только в одном месте: в Неспире, древнем существе, живущем в раковине неподалеку от этой пещеры. Одно мне совершенно непонятно – как нагам удалось подчинить себе Неспиру?$B$BРядом с выходом из пещеры небольшое отверстие – через него мы сможем попасть в раковину Неспиры. Но сначала мне нужно найти моего хозяина. Встретимся на месте, у северо-западного входа в раковину Неспиры.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Войдите в раковину Неспиры через северо-западный вход и найдите способ с ней поговорить.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Эрунак хочет, чтобы я выполнил это задание? Ну, хорошо, посмотрим, что нам расскажет это древнее существо.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Найдите способ поговорить с Неспирой',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Целителем Земли Дуарном в Неспире в Вайш\'ире.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (25891,'Последний заход','Знаешь, почему Орда так любит разрушать? Они ломают и крушат все на своем пути, потому что не могут понять красоты. Орда боится ее и стремится уничтожить то, чего боится. А зачем бы еще им разорять рощу Тал\'дара?$B$BНо мы вместе заставим их понять. Они убедятся, что за все их деяния приходится очень дорого платить.','Поиск последних уцелевших бойцов завершен','Поговорите с мастером Тал\'дарой на его дозорном холме в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Последний заход',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Знаешь, почему Орда так любит разрушать? Они ломают и крушат все на своем пути, потому что не могут понять красоты. Орда боится ее и стремится уничтожить то, чего боится. А зачем бы еще им разорять рощу Тал\'дара?$B$BНо мы вместе заставим их понять. Они убедятся, что за все их деяния приходится очень дорого платить.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Поиск последних уцелевших бойцов завершен',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с мастером Тал\'дарой на его дозорном холме в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25892,'Отступление','Придется подождать с разговором: сейчас нужно уходить, пока наги не прорвались. Постарайся добраться до форпоста ярусом ниже.$B$BВозьми моего морского конька. Встретимся там.','Воспользуйтесь морским коньком говорящей с волнами Валорен, чтобы вернуться к адмиралу Двореку, находящемуся под южной террасой в Руинах Вайш\'ира.','Ты выбралась оттуда! После атаки на форпост я уж было решил, что мы единственные выжившие. Очень рад тебя видеть.','Отступите к Тихому заливу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отступление',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Придется подождать с разговором: сейчас нужно уходить, пока наги не прорвались. Постарайся добраться до форпоста ярусом ниже.$B$BВозьми моего морского конька. Встретимся там.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь морским коньком говорящей с волнами Валорен, чтобы вернуться к адмиралу Двореку, находящемуся под южной террасой в Руинах Вайш\'ира.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты выбралась оттуда! После атаки на форпост я уж было решил, что мы единственные выжившие. Очень рад тебя видеть.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отступите к Тихому заливу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (25893,'Отчаянный план','Джорлан и Мегагекс отправились за помощью. Неподалеку проходят торговые маршруты, и шансы найти подмогу есть, но я бы не стал слишком на это надеяться.$B$BОткровенно говоря, это наша единственная надежда. Долго мы здесь не продержимся: рано или поздно наги найдут нас, и тогда... ну... ты $gсам видел:сама видела;, сколько их там.$B$BОтправляйся на юго-восток к гряде Бейл\'аран и разыщи наших двоих храбрецов. Я постараюсь защитить оставшихся здесь.','Встретьтесь с инженером Мегагексом на гряде Бейл\'аран.','Какая точность. Ты всегда вовремя! Случается беда – приходишь ты – все спасены. Как часы!$B$BПонимаешь, у нас созрел великолепный план! Гениальный в своей простоте! Если не учитывать враждебность местной фауны... А теперь, когда с нами ты, все будет вообще проще пареной репы!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отчаянный план',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Джорлан и Мегагекс отправились за помощью. Неподалеку проходят торговые маршруты, и шансы найти подмогу есть, но я бы не стал слишком на это надеяться.$B$BОткровенно говоря, это наша единственная надежда. Долго мы здесь не продержимся: рано или поздно наги найдут нас, и тогда... ну... ты $gсам видел:сама видела;, сколько их там.$B$BОтправляйся на юго-восток к гряде Бейл\'аран и разыщи наших двоих храбрецов. Я постараюсь защитить оставшихся здесь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Встретьтесь с инженером Мегагексом на гряде Бейл\'аран.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Какая точность. Ты всегда вовремя! Случается беда – приходишь ты – все спасены. Как часы!$B$BПонимаешь, у нас созрел великолепный план! Гениальный в своей простоте! Если не учитывать враждебность местной фауны... А теперь, когда с нами ты, все будет вообще проще пареной репы!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25894,'Опасные воды','С одного из наших кораблей Мегагекс утащил воздушный шар. Он попытался поднять шар на поверхность, но тут откуда ни возьмись появились слизнешкурые хапуги и разодрали шар в клочья.$B$BТеперь Мегагекс хочет запустить второй шар, но история не должна повториться. Уничтожь-ка ты всех этих жаблинов... Или убей столько, чтобы они побоялись снова к нам сунуться.','Уничтожьте 10 слизнешкурых хапуг.','Чем меньше жаблинов, тем лучше.$B$BХорошо, что у них такое примитивное мышление. Сейчас я просто не готов к встрече с водоплавающими вундеркиндами.','Вернитесь к инженеру Мегагексу на гряду Бейл\'аран.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Опасные воды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','С одного из наших кораблей Мегагекс утащил воздушный шар. Он попытался поднять шар на поверхность, но тут откуда ни возьмись появились слизнешкурые хапуги и разодрали шар в клочья.$B$BТеперь Мегагекс хочет запустить второй шар, но история не должна повториться. Уничтожь-ка ты всех этих жаблинов... Или убей столько, чтобы они побоялись снова к нам сунуться.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 10 слизнешкурых хапуг.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Чем меньше жаблинов, тем лучше.$B$BХорошо, что у них такое примитивное мышление. Сейчас я просто не готов к встрече с водоплавающими вундеркиндами.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к инженеру Мегагексу на гряду Бейл\'аран.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25895,'Наготове','Нужно всегда все иметь наготове. Технику. Планы. Планы на технику!$B$BНа каждом корабле Альянса должен быть ящик с набором для выживания. У меня был воздушный шар из старого ящика, но недавно ему пришел быстрый и печальный конец, поэтому мне нужен еще один ящик.$B$BК юго-востоку отсюда ты найдешь корабль. Будем надеяться, что выжившие матросы совсем потеряли головы во время бегства и не догадались забрать с собой этот замечательный ящик. Их промашка может стать нашим спасением.','Достаньте ящик Альянса с предметами первой необходимости.','Давай-ка посмотрим... сигнальное ружье... ага, вот шар... а веревки нет. Как же так, нет веревки?! Если хочешь знать мое мнение, это верх непрактичности. Веревка решительно необходима в любой ситуации!','Коробка с чудесами – вот что такое ящик с предметами первой необходимости! А мне в жизни так не хватает чудес!$B$BНе бойся, я с тобой поделюсь.','Вернитесь к инженеру Мегагексу на гряду Бейл\'аран.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наготове',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нужно всегда все иметь наготове. Технику. Планы. Планы на технику!$B$BНа каждом корабле Альянса должен быть ящик с набором для выживания. У меня был воздушный шар из старого ящика, но недавно ему пришел быстрый и печальный конец, поэтому мне нужен еще один ящик.$B$BК юго-востоку отсюда ты найдешь корабль. Будем надеяться, что выжившие матросы совсем потеряли головы во время бегства и не догадались забрать с собой этот замечательный ящик. Их промашка может стать нашим спасением.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Достаньте ящик Альянса с предметами первой необходимости.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Давай-ка посмотрим... сигнальное ружье... ага, вот шар... а веревки нет. Как же так, нет веревки?! Если хочешь знать мое мнение, это верх непрактичности. Веревка решительно необходима в любой ситуации!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Коробка с чудесами – вот что такое ящик с предметами первой необходимости! А мне в жизни так не хватает чудес!$B$BНе бойся, я с тобой поделюсь.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к инженеру Мегагексу на гряду Бейл\'аран.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25896,'Сбор на ритуал','А, это ты, Воительница. Ты несешь с собой слово и волю госпожи. У меня к тебе просьба...$B$BМне нужно, чтобы сюда вернулись призыватель глубин Азражар и жрицы прилива. Их присутствие необходимо для ритуала. Передашь им мою просьбу? Они где-то на террасе храма. Азражара можно найти на лестнице к северу отсюда.','Найдите призывателя глубин Азражара на полпути вниз по северной лестнице и 6 жриц прилива Сира\'кесс в верхней части руин, после чего попросите их вернуться в храм.$B$BЭто задание из цикла "Видения воительницы Леди Наз\'жар". Чтобы вернуться к видению, в нужном месте воспользуйтесь клинком воительницы Леди Наз\'жар.','Квалдиры куда опаснее, чем мы предполагали, но это никак не помешает нашим планам. Когда прибудут наши союзники, у нас будет достаточно сил, чтобы захватить Хозяина Приливов.$B$BОсталось лишь довести ритуал призыва до конца.','Вернитесь к Леди Сира\'кесс в храм Кель\'Дормир.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сбор на ритуал',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А, это ты, Воительница. Ты несешь с собой слово и волю госпожи. У меня к тебе просьба...$B$BМне нужно, чтобы сюда вернулись призыватель глубин Азражар и жрицы прилива. Их присутствие необходимо для ритуала. Передашь им мою просьбу? Они где-то на террасе храма. Азражара можно найти на лестнице к северу отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите призывателя глубин Азражара на полпути вниз по северной лестнице и 6 жриц прилива Сира\'кесс в верхней части руин, после чего попросите их вернуться в храм.$B$BЭто задание из цикла "Видения воительницы Леди Наз\'жар". Чтобы вернуться к видению, в нужном месте воспользуйтесь клинком воительницы Леди Наз\'жар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Квалдиры куда опаснее, чем мы предполагали, но это никак не помешает нашим планам. Когда прибудут наши союзники, у нас будет достаточно сил, чтобы захватить Хозяина Приливов.$B$BОсталось лишь довести ритуал призыва до конца.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Леди Сира\'кесс в храм Кель\'Дормир.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25897,'Веревочный план','В ящике с предметами первой необходимости нет веревки... Вопиющая халатность!$B$BБьюсь об заклад, у квалдиров должна быть веревка. Они же чуть не живут на лодках, вяжут узлы да одеваются в сети. Иди-ка отбери у них веревку! Без этого наш план яйца выеденного не стоит.','Добудьте 8 мотков квалдирской веревки.','Превосходно! То, что нужно. Она должна выдержать... Футы-нуты! Она что, из волос сплетена?!$B$BЛадно, какая разница. Теперь почти все готово. Как говорится, сколь веревочке ни виться...','На этой веревке весь мой план держится!','Вернитесь к инженеру Мегагексу на гряду Бейл\'аран.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Веревочный план',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В ящике с предметами первой необходимости нет веревки... Вопиющая халатность!$B$BБьюсь об заклад, у квалдиров должна быть веревка. Они же чуть не живут на лодках, вяжут узлы да одеваются в сети. Иди-ка отбери у них веревку! Без этого наш план яйца выеденного не стоит.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 8 мотков квалдирской веревки.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Превосходно! То, что нужно. Она должна выдержать... Футы-нуты! Она что, из волос сплетена?!$B$BЛадно, какая разница. Теперь почти все готово. Как говорится, сколь веревочке ни виться...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','На этой веревке весь мой план держится!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к инженеру Мегагексу на гряду Бейл\'аран.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25898,'Честь и слава','Готово! Я уверен, все получится. И в этот раз никаких слизнешкуров! Какая удача.$B$BДжорлан уже отправился наверх ловить шар, но честь ведения операции предоставил тебе. Вот такой он добрый.$B$BПоднимись к шару, возьми сигнальное ружье и посмотри, нет ли поблизости кораблей Альянса. Если такой увидишь, стреляй сигнальной ракетой. Собственно, и все.$B$BПлывешь. Поднимаешься на поверхность. Запускаешь ракету. И помощь приходит! Последний пункт мне нравится больше всего.','Поднимитесь на поверхность, возьмите сигнальное ружье и запустите сигнальную ракету в направлении кораблей Альянса.','Отлично! Они ее точно заметили. Не могли не заметить.','Поговорите с Джорланом Верным Клинком на поверхности моря над грядой Бейл\'аран.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Честь и слава',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Готово! Я уверен, все получится. И в этот раз никаких слизнешкуров! Какая удача.$B$BДжорлан уже отправился наверх ловить шар, но честь ведения операции предоставил тебе. Вот такой он добрый.$B$BПоднимись к шару, возьми сигнальное ружье и посмотри, нет ли поблизости кораблей Альянса. Если такой увидишь, стреляй сигнальной ракетой. Собственно, и все.$B$BПлывешь. Поднимаешься на поверхность. Запускаешь ракету. И помощь приходит! Последний пункт мне нравится больше всего.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поднимитесь на поверхность, возьмите сигнальное ружье и запустите сигнальную ракету в направлении кораблей Альянса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! Они ее точно заметили. Не могли не заметить.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Джорланом Верным Клинком на поверхности моря над грядой Бейл\'аран.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25899,'Прорыв','Огненная армия, принесшая смерть и разрушение на эту гору, отступила к востоку. Тут остались лишь сумеречные выжигатели. Если пробьемся сквозь их строй, то сможем воссоединиться с силами капитана Железного Леса и остановить их продвижение.$B$BЯ больше не в силах вести бой, |3-6($c), но ты, кажется, находишься в лучшей форме. Уничтожь сумеречных выжигателей и пробейся к капитану Железному Лесу!','Уничтожьте 10 выжигателей из культа Сумеречного Молота.','Скольких ты убил? Неплохо. Очень даже неплохо. Думаю, мои люди больше не найдут никаких отговорок.','Поговорите с капитаном Железным Лесом, находящимся на Выжженной равнине на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прорыв',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Огненная армия, принесшая смерть и разрушение на эту гору, отступила к востоку. Тут остались лишь сумеречные выжигатели. Если пробьемся сквозь их строй, то сможем воссоединиться с силами капитана Железного Леса и остановить их продвижение.$B$BЯ больше не в силах вести бой, |3-6($c), но ты, кажется, находишься в лучшей форме. Уничтожь сумеречных выжигателей и пробейся к капитану Железному Лесу!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 10 выжигателей из культа Сумеречного Молота.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Скольких ты убил? Неплохо. Очень даже неплохо. Думаю, мои люди больше не найдут никаких отговорок.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с капитаном Железным Лесом, находящимся на Выжженной равнине на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (25900,'Контакт','Не верится, что Неспира сама позволила нагам расположиться в своей раковине. Но я вижу только два возможных объяснения: либо наги убедили ее встать на их сторону, либо довели до такого состояния, что она не смогла сопротивляться. В любом случае дело плохо.$B$BВ этой полости я смогу поговорить с самой Неспирой. Нам нужно выяснить, в чем дело. Когда будешь $gготов:готова;, скажи мне.','Проследите за тем, как Целитель Земли Дуарн попытается заговорить с Неспирой.','Не получается. Она почему-то не хочет со мной разговаривать.$B$B<Видно, что Дуарн недоволен.>$B$BПлохо, что с нами нет Эрунака! Он бы подсказал, что делать.','Поговорите с Целителем Земли Дуарном','Вернитесь к Целителю Земли Дуарну в Неспиру в Вайш\'ире.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Контакт',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не верится, что Неспира сама позволила нагам расположиться в своей раковине. Но я вижу только два возможных объяснения: либо наги убедили ее встать на их сторону, либо довели до такого состояния, что она не смогла сопротивляться. В любом случае дело плохо.$B$BВ этой полости я смогу поговорить с самой Неспирой. Нам нужно выяснить, в чем дело. Когда будешь $gготов:готова;, скажи мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проследите за тем, как Целитель Земли Дуарн попытается заговорить с Неспирой.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Не получается. Она почему-то не хочет со мной разговаривать.$B$B<Видно, что Дуарн недоволен.>$B$BПлохо, что с нами нет Эрунака! Он бы подсказал, что делать.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Поговорите с Целителем Земли Дуарном',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Целителю Земли Дуарну в Неспиру в Вайш\'ире.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25901,'План очищения Хиджала','Подкрепление! Я уж думал, что мы погибнем.$B$BВ живых осталось всего несколько защитников Хиджала, и наши запасы иссякают. На поле боя за стенами этого укрепления должно быть разбросано много стрел, пригодных для битвы.$B$BЗнаю, что данная просьба слишком мелочна для тебя, но не $gмог:могла; бы ты помочь нам их собрать? Это единственный путь пополнить наши запасы!','Соберите 15 стрел стража.','Отнесите стрелы Лограму, находящемуся на Выжженой равнине на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','План очищения Хиджала',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Подкрепление! Я уж думал, что мы погибнем.$B$BВ живых осталось всего несколько защитников Хиджала, и наши запасы иссякают. На поле боя за стенами этого укрепления должно быть разбросано много стрел, пригодных для битвы.$B$BЗнаю, что данная просьба слишком мелочна для тебя, но не $gмог:могла; бы ты помочь нам их собрать? Это единственный путь пополнить наши запасы!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 15 стрел стража.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите стрелы Лограму, находящемуся на Выжженой равнине на горе Хиджал.',`completedtext_loc8`);
