INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25904,'Молот и Ключ','Немесис. Он все еще жив.$BСлуги огня продолжают приходить.$BМы должны сами прийти к ним. Прямо в их логово.$B$BОгры знают туда дорогу.$BУбей полевых командиров.$BДобудь символ Открытия.$B$BТы найдешь путь.','Убейте сумеречного полевого командира и добудьте символ Открытия.','Это древняя сила.$BПримитивная.$BПростая.$B$BМы обратим ее против них.','Символ. Покажи.','Отнесите символ Тортолле на Выжженную равнину на Хиджале.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Молот и Ключ',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Немесис. Он все еще жив.$BСлуги огня продолжают приходить.$BМы должны сами прийти к ним. Прямо в их логово.$B$BОгры знают туда дорогу.$BУбей полевых командиров.$BДобудь символ Открытия.$B$BТы найдешь путь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте сумеречного полевого командира и добудьте символ Открытия.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это древняя сила.$BПримитивная.$BПростая.$B$BМы обратим ее против них.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Символ. Покажи.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите символ Тортолле на Выжженную равнину на Хиджале.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25905,'Бараны в бегах','Горные пехотинцы Дун Морога всегда выбирали баранов, которых мы растим и объезжаем на ферме Янтарленов. Да, их еще немного осталось, но недостаточно для того, чтобы обеспечить мою семью и сохранить других животных.$b$bНалетчики Мерзлогривов повадились воровать наших баранов под покровом ночи и переправлять их на юг, в холмы Тандрид. Не можешь ли помочь вернуть их? Нужно подобраться к ним достаточно быстро и резко свистнуть, чтобы привлечь их внимание. Дальше они вспомнят, чему их учили.','Выведите с холмов Тандрид 6 украденных баранов, используя /свист.','Бараны, которых ты спас, уже вернулись в загон. Теперь члены моей семьи будут следить за ними день и ночь. Эти тролли больше не застигнут нас врасплох!','Вернитесь к Верону Янтарлену на ферму Янтарленов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бараны в бегах',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Горные пехотинцы Дун Морога всегда выбирали баранов, которых мы растим и объезжаем на ферме Янтарленов. Да, их еще немного осталось, но недостаточно для того, чтобы обеспечить мою семью и сохранить других животных.$b$bНалетчики Мерзлогривов повадились воровать наших баранов под покровом ночи и переправлять их на юг, в холмы Тандрид. Не можешь ли помочь вернуть их? Нужно подобраться к ним достаточно быстро и резко свистнуть, чтобы привлечь их внимание. Дальше они вспомнят, чему их учили.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выведите с холмов Тандрид 6 украденных баранов, используя /свист.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Бараны, которых ты спас, уже вернулись в загон. Теперь члены моей семьи будут следить за ними день и ночь. Эти тролли больше не застигнут нас врасплох!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Верону Янтарлену на ферму Янтарленов.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25906,'Третьи огненные врата','Хорошенько запомни этот символ.$BЗапечатлей его в своей памяти.$B$BНарисуй его на земле перед огненными вратами.$BК востоку отсюда.$BСтупи на Огненные Просторы.$B$BЯ не смогу пойти с тобой.$BНо мои дети уже ждут тебя. Внутри.$B$BНайди Гарунда Горного Пика в мире пламени.','Пройдите через огненные врата на Огненные Просторы и найдите там Гарунда Горного Пика.','Тебя послал бог-черепаха? Будь благословен его панцирь! Я уж думал, что останусь тут навечно!','Пройдите через огненные врата на Огненные просторы и найдите там Гарунда Горного Пика.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Третьи огненные врата',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хорошенько запомни этот символ.$BЗапечатлей его в своей памяти.$B$BНарисуй его на земле перед огненными вратами.$BК востоку отсюда.$BСтупи на Огненные Просторы.$B$BЯ не смогу пойти с тобой.$BНо мои дети уже ждут тебя. Внутри.$B$BНайди Гарунда Горного Пика в мире пламени.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Пройдите через огненные врата на Огненные Просторы и найдите там Гарунда Горного Пика.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебя послал бог-черепаха? Будь благословен его панцирь! Я уж думал, что останусь тут навечно!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Пройдите через огненные врата на Огненные просторы и найдите там Гарунда Горного Пика.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25907,'Рабский труд','Мне понадобится время, чтобы преодолеть этот барьер и поговорить с Неспирой. А ты пока можешь заняться освобождением людей, которых держат в рабстве наги.$B$B<Дуарн достает веревку из своего балахона.>$B$BВозьми, тебе пригодится.','Воспользуйтесь веревкой Дуарна, чтобы освободить 8 порабощенных добытчиков жемчуга.','Вернитесь к Целителю Земли Дуарну в Неспиру в Вайш\'ире.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рабский труд',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне понадобится время, чтобы преодолеть этот барьер и поговорить с Неспирой. А ты пока можешь заняться освобождением людей, которых держат в рабстве наги.$B$B<Дуарн достает веревку из своего балахона.>$B$BВозьми, тебе пригодится.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь веревкой Дуарна, чтобы освободить 8 порабощенных добытчиков жемчуга.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Целителю Земли Дуарну в Неспиру в Вайш\'ире.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (25907,'Превосходно, Гнобс... Правда, боюсь, что я не могу похвастаться такими же успехами.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Превосходно, Гнобс... Правда, боюсь, что я не могу похвастаться такими же успехами.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25908,'Уничтожить врага','Я никак не могу связаться с Неспирой, но все же кое-что ощущаю – например, ей не нравится, что в ней расположились наги.$B$BКогда мы впервые сюда пришли, я видел, что главную полость стерегут десятки часовых и чародеек. Вполне возможно, что, если ты уничтожишь их, Неспире станет легче.','Убейте по 7 часовых и чародеек Идра\'кесса.','Ты чувствуешь? Если в тебе есть хоть капля шаманской крови, ты должен почувствовать облегчение, которое она испытала.$B$BНеспира довольна. Возможно, теперь она заговорит с нами.','Вернитесь к Целителю Земли Дуарну в Неспиру в Вайш\'ире.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уничтожить врага',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я никак не могу связаться с Неспирой, но все же кое-что ощущаю – например, ей не нравится, что в ней расположились наги.$B$BКогда мы впервые сюда пришли, я видел, что главную полость стерегут десятки часовых и чародеек. Вполне возможно, что, если ты уничтожишь их, Неспире станет легче.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте по 7 часовых и чародеек Идра\'кесса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты чувствуешь? Если в тебе есть хоть капля шаманской крови, ты должен почувствовать облегчение, которое она испытала.$B$BНеспира довольна. Возможно, теперь она заговорит с нами.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Целителю Земли Дуарну в Неспиру в Вайш\'ире.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25909,'Захват краба','Всем своим существом я ощущаю, что Неспира хочет говорить со мной, но я ее не слышу. Видимо, наги как-то препятствуют этому.$B$B<Дуарн какое-то время молча размышляет.>$B$BПохоже, что-то не дает ей говорить... Необходимо найти то, что послужит ей голосом...$B$BПридумал! Известно, что Идра\'кесс приручают глубинных крабов и выращивают из них помощников в бою. Поймай этой сетью одного краба и принеси мне. Они обитают у внешних границ полости.','Поймайте сетью Дуарна глубинного краба в Неспире.','<Дуарн смотрит на краба и еле сдерживает недовольство.>$B$BВыглядит не очень внушительно, да?','Надеюсь, сработает. Мои способности ограничены, боюсь, мы можем не справиться с этой задачей.','Вернитесь к Целителю Земли Дуарну в Неспиру в Вайш\'ире.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Захват краба',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Всем своим существом я ощущаю, что Неспира хочет говорить со мной, но я ее не слышу. Видимо, наги как-то препятствуют этому.$B$B<Дуарн какое-то время молча размышляет.>$B$BПохоже, что-то не дает ей говорить... Необходимо найти то, что послужит ей голосом...$B$BПридумал! Известно, что Идра\'кесс приручают глубинных крабов и выращивают из них помощников в бою. Поймай этой сетью одного краба и принеси мне. Они обитают у внешних границ полости.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поймайте сетью Дуарна глубинного краба в Неспире.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Дуарн смотрит на краба и еле сдерживает недовольство.>$B$BВыглядит не очень внушительно, да?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Надеюсь, сработает. Мои способности ограничены, боюсь, мы можем не справиться с этой задачей.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Целителю Земли Дуарну в Неспиру в Вайш\'ире.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25910,'Пощады больше не будет','Жуткая пещерка, $n, и населяют ее сплошные порождения глубинных кошмаров.$B$BЯ не хочу, чтобы кто-нибудь из них улизнул сквозь портал во внешний мир. Убей всех, кого увидишь!','Убейте 10 раскаленных мучителей и 4 мастеров пламени Тьмы.','Так вот, значит, как.$B$BОт осознания того, с какими жуткими существами вступил в союз Сумеречный Молот, у меня кровь в жилах вскипает и сворачивается.','Вернитесь к Гарунду Горному Пику в Раскаленный тигель.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пощады больше не будет',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Жуткая пещерка, $n, и населяют ее сплошные порождения глубинных кошмаров.$B$BЯ не хочу, чтобы кто-нибудь из них улизнул сквозь портал во внешний мир. Убей всех, кого увидишь!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 раскаленных мучителей и 4 мастеров пламени Тьмы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так вот, значит, как.$B$BОт осознания того, с какими жуткими существами вступил в союз Сумеречный Молот, у меня кровь в жилах вскипает и сворачивается.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гарунду Горному Пику в Раскаленный тигель.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25911,'Добрые вести','Они, наверное, вышлют лодку. Но на это надо время. Я останусь здесь и вступлю в переговоры.$B$BА ты немедленно возвращайся в пещеру и скажи там, что помощь уже на подходе. Будем надеяться, наги их не обнаружили.$B$BДавай, $n. Плыви. И постарайся обернуться побыстрее.','Вернитесь к капитану Тейлору в Тихий залив.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Добрые вести',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Они, наверное, вышлют лодку. Но на это надо время. Я останусь здесь и вступлю в переговоры.$B$BА ты немедленно возвращайся в пещеру и скажи там, что помощь уже на подходе. Будем надеяться, наги их не обнаружили.$B$BДавай, $n. Плыви. И постарайся обернуться побыстрее.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь к капитану Тейлору в Тихий залив.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25912,'Что за времена...','Вокруг нас появляется новый мир, $n. Старые враги пытаются уничтожить нас с одной стороны, а на другой тем временем собираются древние силы.$B$B<Предок Сарет\'на вздыхает.>$B$BЯ помню другие времена, они были куда лучше, и мне их очень не хватает...$B$BНа пике Каменного Когтя остались руины нашей заставы, теперь там одна нечисть. Если тебе вдруг доведется попасть туда, не $gмог:могла; бы ты поискать там мою записную книжку? Там все мои воспоминания... А уж за наградой я не постою.','Найдите записную книжку предка Сарет\'ны.','Вернитесь к предку Сарет\'не на дозорный холм Тал\'дара в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Что за времена...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вокруг нас появляется новый мир, $n. Старые враги пытаются уничтожить нас с одной стороны, а на другой тем временем собираются древние силы.$B$B<Предок Сарет\'на вздыхает.>$B$BЯ помню другие времена, они были куда лучше, и мне их очень не хватает...$B$BНа пике Каменного Когтя остались руины нашей заставы, теперь там одна нечисть. Если тебе вдруг доведется попасть туда, не $gмог:могла; бы ты поискать там мою записную книжку? Там все мои воспоминания... А уж за наградой я не постою.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите записную книжку предка Сарет\'ны.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к предку Сарет\'не на дозорный холм Тал\'дара в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25913,'Даровать им покой','Когда Орда маршировала по Когтистым горам, я заметил, что некоторые часовые будто бы чем-то заболели. Потом они начали странно вести себя, а когда из-под земли показалось первое щупальце, больные часовые набросились на нас, и вскоре после этого мы потеряли заставу...$B$BОт часовых на том пике теперь остались одни оболочки, этакие вместилища для какого-то кошмарного ужаса. Я хочу, чтобы ты $gдаровал:даровала; им покой и $gзабрал:забрала; их глефы. По каждой глефе можно будет опознать павшую сестру.','Принесите 8 глеф часовых.','Вернитесь к главе часовых Геленет на дозорный холм Тал\'дара в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Даровать им покой',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда Орда маршировала по Когтистым горам, я заметил, что некоторые часовые будто бы чем-то заболели. Потом они начали странно вести себя, а когда из-под земли показалось первое щупальце, больные часовые набросились на нас, и вскоре после этого мы потеряли заставу...$B$BОт часовых на том пике теперь остались одни оболочки, этакие вместилища для какого-то кошмарного ужаса. Я хочу, чтобы ты $gдаровал:даровала; им покой и $gзабрал:забрала; их глефы. По каждой глефе можно будет опознать павшую сестру.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 8 глеф часовых.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к главе часовых Геленет на дозорный холм Тал\'дара в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25914,'Назад, в глубины!','Из земли лезут щупальца, и на пике Каменного Когтя царит паника. Мои часовые сражаются с щупальцами, но погоды это практически не делает.$B$BПодозреваю, что под пиком Каменного Когтя обитает некая сила, которая управляет щупальцами. Может, если бы нам удалось уничтожить ее, то и щупальца бы вернулись обратно под землю, откуда они повылезали!','Убейте предвестника Аф\'ласса и 10 щупалец-захватчиков.','Вернитесь к главе часовых Геленет на дозорный холм Тал\'дара в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Назад, в глубины!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Из земли лезут щупальца, и на пике Каменного Когтя царит паника. Мои часовые сражаются с щупальцами, но погоды это практически не делает.$B$BПодозреваю, что под пиком Каменного Когтя обитает некая сила, которая управляет щупальцами. Может, если бы нам удалось уничтожить ее, то и щупальца бы вернулись обратно под землю, откуда они повылезали!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте предвестника Аф\'ласса и 10 щупалец-захватчиков.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к главе часовых Геленет на дозорный холм Тал\'дара в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25915,'Сила Тортоллы','Гнусный захватчик Немесис укрылся здесь, когда нам удалось оттеснить огонь, охвативший Хиджал. У нас пока не хватает сил, чтобы сразиться с Немесисом в открытую, $n, но мы можем обратить против него его же силы.$B$BЯ пошлю с тобой дитя Тортоллы – одного из тех, кого тебе удалось освободить от власти Сумеречного Молота.$B$BОтыщи кристалл Немесиса в глубине пещеры и позволь юной черепахе исследовать его.$B$BНайди меня, если ты потеряешь своего спутника!','Проводите дитя Тортоллы к кристаллу Немесиса. Если вы потеряете своего спутника, вернитесь к Гарунду Горному Пику.','Вернитесь к Гарунду Горному Пику в Раскаленный тигель.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сила Тортоллы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Гнусный захватчик Немесис укрылся здесь, когда нам удалось оттеснить огонь, охвативший Хиджал. У нас пока не хватает сил, чтобы сразиться с Немесисом в открытую, $n, но мы можем обратить против него его же силы.$B$BЯ пошлю с тобой дитя Тортоллы – одного из тех, кого тебе удалось освободить от власти Сумеречного Молота.$B$BОтыщи кристалл Немесиса в глубине пещеры и позволь юной черепахе исследовать его.$B$BНайди меня, если ты потеряешь своего спутника!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проводите дитя Тортоллы к кристаллу Немесиса. Если вы потеряете своего спутника, вернитесь к Гарунду Горному Пику.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гарунду Горному Пику в Раскаленный тигель.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (25916,'Прорыв','Хорошо известно, что опытный шаман умеет взаимодействовать со всеми четырьмя элементами стихий: землей, огнем, водой и воздухом.$B$BОднако далеко не все знают, что существует и пятый элемент. Он не имеет такого же четкого определения, как остальные... О нем можно сказать только то, что он является связующим звеном между всем живым на планете.$B$BЯ пришел к выводу о том, что краб, как морской обитатель, находится ближе всего к Неспире, поэтому с помощью всех элементов можно убедить его взять на себя роль голоса Неспиры.','Проследите за тем, как Целитель Земли Дуарн попытается заговорить с Неспирой.','Я полагал, что наги пришли только за жемчугом, но, похоже, у них есть более серьезная цель. Подчинив себе Неспиру, они смогут действовать здесь абсолютно безнаказанно, и последствия будут катастрофическими!$B$BИх нужно остановить.','Поговорите с Целителем Земли Дуарном','Вернитесь к целителю земли Дуарну в Неспиру в Вайш\'ире.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прорыв',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хорошо известно, что опытный шаман умеет взаимодействовать со всеми четырьмя элементами стихий: землей, огнем, водой и воздухом.$B$BОднако далеко не все знают, что существует и пятый элемент. Он не имеет такого же четкого определения, как остальные... О нем можно сказать только то, что он является связующим звеном между всем живым на планете.$B$BЯ пришел к выводу о том, что краб, как морской обитатель, находится ближе всего к Неспире, поэтому с помощью всех элементов можно убедить его взять на себя роль голоса Неспиры.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проследите за тем, как Целитель Земли Дуарн попытается заговорить с Неспирой.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я полагал, что наги пришли только за жемчугом, но, похоже, у них есть более серьезная цель. Подчинив себе Неспиру, они смогут действовать здесь абсолютно безнаказанно, и последствия будут катастрофическими!$B$BИх нужно остановить.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Поговорите с Целителем Земли Дуарном',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к целителю земли Дуарну в Неспиру в Вайш\'ире.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25917,'Мы не одиноки','<Дуарн закрывает глаза, на мгновение застывает, затем кивает.>$B$BНеспира только что сообщила мне, что мы в этой раковине не одни. Небольшая группа из Альянса сражается с нагами на другой стороне раковины, прямо на возвышенности, что над сердцем Неспиры.$B$BСтупай, отыщи их, $n. Возможно, они смогут нам чем-то помочь. А вместе мы, быть может, выведем Неспиру из оцепенения.$B$BЕсли тебе что-нибудь понадобится, я буду здесь.','Отыщите в Неспире, что в Вайш\'ире, выживших Альянса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мы не одиноки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Дуарн закрывает глаза, на мгновение застывает, затем кивает.>$B$BНеспира только что сообщила мне, что мы в этой раковине не одни. Небольшая группа из Альянса сражается с нагами на другой стороне раковины, прямо на возвышенности, что над сердцем Неспиры.$B$BСтупай, отыщи их, $n. Возможно, они смогут нам чем-то помочь. А вместе мы, быть может, выведем Неспиру из оцепенения.$B$BЕсли тебе что-нибудь понадобится, я буду здесь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщите в Неспире, что в Вайш\'ире, выживших Альянса.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25918,'Безоружные','Честно говоря, я не понимаю, почему мы до сих пор живы. Наги захватили все мое оружие и доспехи. У меня остались только какие-то лохмотья и шахтерская кирка, которая к тому же давным-давно пополам сломалась.$B$BМне нужно хоть какое-то оружие... Да, и моим товарищам тоже, хоть гордость и не позволяет им это признать.$B$BЯ видел стойки с оружием на ближайших складах наг. Мне еще никогда не доводилось сражаться трезубцем, но в любом случае лучше идти в бой с ним, чем с голыми руками.','Принесите 4 похищенных трезубца с оружейных стоек в Неспире.','Вернитесь к адмиралу Двореку в Неспиру в Вайш\'ире.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Безоружные',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Честно говоря, я не понимаю, почему мы до сих пор живы. Наги захватили все мое оружие и доспехи. У меня остались только какие-то лохмотья и шахтерская кирка, которая к тому же давным-давно пополам сломалась.$B$BМне нужно хоть какое-то оружие... Да, и моим товарищам тоже, хоть гордость и не позволяет им это признать.$B$BЯ видел стойки с оружием на ближайших складах наг. Мне еще никогда не доводилось сражаться трезубцем, но в любом случае лучше идти в бой с ним, чем с голыми руками.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 4 похищенных трезубца с оружейных стоек в Неспире.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к адмиралу Двореку в Неспиру в Вайш\'ире.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25919,'Удар по телу','<Капитан Тейлор внимательно слушает ваш пересказ разговора Дуарна с Неспирой.>$B$BПонятно. Значит, она хочет, чтобы мы помогли ей проснуться, так?$B$BЕсли учесть, что сотни рабов уже собирают ее жемчужины, то, похоже, ее из пушки не разбудишь. Но, может, у тебя и получится.$B$BЯ вот что предлагаю: хорошенько ее осмотри и попробуй найти слабое место. Быть может, если ударить в чувствительную точку, она придет в себя.','Ударьте Неспиру в 7 гнойников, расположенных на стенах ее полости.','Надеюсь, получилось. Понятия не имею, как мы узнаем, что она проснулась, но мне почему-то кажется, сразу поймем.','Вернитесь к капитану Тейлору в Неспиру в Вайш\'ире.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Удар по телу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Капитан Тейлор внимательно слушает ваш пересказ разговора Дуарна с Неспирой.>$B$BПонятно. Значит, она хочет, чтобы мы помогли ей проснуться, так?$B$BЕсли учесть, что сотни рабов уже собирают ее жемчужины, то, похоже, ее из пушки не разбудишь. Но, может, у тебя и получится.$B$BЯ вот что предлагаю: хорошенько ее осмотри и попробуй найти слабое место. Быть может, если ударить в чувствительную точку, она придет в себя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Ударьте Неспиру в 7 гнойников, расположенных на стенах ее полости.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Надеюсь, получилось. Понятия не имею, как мы узнаем, что она проснулась, но мне почему-то кажется, сразу поймем.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Тейлору в Неспиру в Вайш\'ире.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25920,'Ценные вещи','Я недолго пробыла на жемчужных полях и так и не поняла, какие же цели преследуют наги. Известно, что они хотят использовать Неспиру в качестве орудия войны, но зачем тогда заставляют рабов добывать ее жемчуг?$B$BЕсли нам удастся отсюда выбраться, я бы хотела хорошенько изучить эти жемчужины. Правда, те, что нашли мы, были слишком большими. Нам их не унести. Но я видела в руках у полководцев и пророков жемчуг помельче.','Добудьте у полководцев и пророков Идра\'кесса в Неспире 5 таинственных жемчужин.','Великолепно!$B$B<Валорен прячет жемчуг.>$B$BСейчас же нужно, чтобы вы с капитаном Тейлором помогли мне выбраться из этого места. Тогда я смогу продолжить исследования.','Похоже, у наг свои причины добывать этот жемчуг. И мне наверняка удалось бы их выяснить, будь у меня возможность изучить жемчужины.','Вернитесь к говорящей с волнами Валорен, находящейся в Неспире, что в Вайш\'ире.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ценные вещи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я недолго пробыла на жемчужных полях и так и не поняла, какие же цели преследуют наги. Известно, что они хотят использовать Неспиру в качестве орудия войны, но зачем тогда заставляют рабов добывать ее жемчуг?$B$BЕсли нам удастся отсюда выбраться, я бы хотела хорошенько изучить эти жемчужины. Правда, те, что нашли мы, были слишком большими. Нам их не унести. Но я видела в руках у полководцев и пророков жемчуг помельче.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте у полководцев и пророков Идра\'кесса в Неспире 5 таинственных жемчужин.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Великолепно!$B$B<Валорен прячет жемчуг.>$B$BСейчас же нужно, чтобы вы с капитаном Тейлором помогли мне выбраться из этого места. Тогда я смогу продолжить исследования.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Похоже, у наг свои причины добывать этот жемчуг. И мне наверняка удалось бы их выяснить, будь у меня возможность изучить жемчужины.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к говорящей с волнами Валорен, находящейся в Неспире, что в Вайш\'ире.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (25921,'Надзиратель Идра\'кесс','Мои воины измождены, $n. Боюсь, мы недолго продержимся против наг. Теперь у нас есть оружие Идра\'кесса и жемчуг Неспиры; пора выбираться отсюда.$b$bДвигайся вдоль стены на юго-восток и ищи подъем в верхнюю полость. Полагаю, их лидер находится где-то там. Возможно, там же скрывается и разгадка к пробуждению Неспиры. Надеюсь, и то, и другое сразу.$b$bЕсли посмеешь отважиться на такое, то ступай в верхнюю полость и попробуй найти ответы на наши вопросы.','Отправляйтесь в верхнюю полость Неспиры и убейте надзирателя Идра\'кесса.','Можешь ничего мне не рассказывать… Неспира поведала мне обо всех твоих странствиях по мере их развития, а капитан Тейлор рассказал мне обо всех остальных подробностях.$B$B<Дуарн закрывает глаза и кивает головой.>$B$BНеспира говорит, что она благодарна тебе и что у нее есть для наг небольшой сюрприз.','Расскажите обо всем Целителю Земли Дуарну у мозга Неспиры в Вайш\'ире.','Осквернитель Неспиры','Надзиратель Идра\'кесс') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Надзиратель Идра\'кесс',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мои воины измождены, $n. Боюсь, мы недолго продержимся против наг. Теперь у нас есть оружие Идра\'кесса и жемчуг Неспиры; пора выбираться отсюда.$b$bДвигайся вдоль стены на юго-восток и ищи подъем в верхнюю полость. Полагаю, их лидер находится где-то там. Возможно, там же скрывается и разгадка к пробуждению Неспиры. Надеюсь, и то, и другое сразу.$b$bЕсли посмеешь отважиться на такое, то ступай в верхнюю полость и попробуй найти ответы на наши вопросы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в верхнюю полость Неспиры и убейте надзирателя Идра\'кесса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Можешь ничего мне не рассказывать… Неспира поведала мне обо всех твоих странствиях по мере их развития, а капитан Тейлор рассказал мне обо всех остальных подробностях.$B$B<Дуарн закрывает глаза и кивает головой.>$B$BНеспира говорит, что она благодарна тебе и что у нее есть для наг небольшой сюрприз.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Расскажите обо всем Целителю Земли Дуарну у мозга Неспиры в Вайш\'ире.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Осквернитель Неспиры',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Надзиратель Идра\'кесс',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25922,'Пробуждение','Благодаря вашей с капитаном помощи Неспира вышла из оцепенения. Но большинству наг это пока неизвестно. Как только мы уйдем, Неспира запустит в своем теле защитные биологические процессы и уничтожит наг.$B$BПриготовься, а я пока скажу Неспире начать обратный отсчет.','Поговорите с Целителем Земли Дуарном в Неспире, чтобы запустить защитные процессы. Затем покиньте тело Неспиры.','Расскажите обо всем капитану Тейлору в Тихом заливе в Вайш\'ире.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пробуждение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Благодаря вашей с капитаном помощи Неспира вышла из оцепенения. Но большинству наг это пока неизвестно. Как только мы уйдем, Неспира запустит в своем теле защитные биологические процессы и уничтожит наг.$B$BПриготовься, а я пока скажу Неспире начать обратный отсчет.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Целителем Земли Дуарном в Неспире, чтобы запустить защитные процессы. Затем покиньте тело Неспиры.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Расскажите обо всем капитану Тейлору в Тихом заливе в Вайш\'ире.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (25923,'Покончить с Немесисом','Черепашка, что сопровождает тебя, может использовать обретенную силу, чтобы на какое-то время сделать вас обоих неуязвимыми. С ее помощью вы сможете пережить самые сильные удары Немесиса. Используйте вот этот тотем.$B$BЭто все, что я могу для тебя сделать. Ты и дитя Тортоллы сокрушите Немесиса раз и навсегда. Покончите с узурпатором!$B$BНайди меня, если ты потеряешь своего спутника.','Используйте тотем Тортоллы и победите Немесиса вместе со своим спутником. Если вы потеряете дитя Тортоллы, вернитесь к Гарунду Горному Пику.','Захватчик пал!$B$BСумеречный Молот мечтал создать собственный пантеон из оскверненных древних, чтобы править землей, водой и воздухом. С твой помощью нам удалось с ними покончить.$B$BТортолла должен узнать об этом!','Вернитесь к Гарунду Горному Пику в Раскаленный тигель.','Воспользуйтесь тотемом и помощью вашего спутника, черепахи, чтобы выжить во время схватки с противником. С лжебогом нужно покончить!','Немесис Узурпатор') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Покончить с Немесисом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Черепашка, что сопровождает тебя, может использовать обретенную силу, чтобы на какое-то время сделать вас обоих неуязвимыми. С ее помощью вы сможете пережить самые сильные удары Немесиса. Используйте вот этот тотем.$B$BЭто все, что я могу для тебя сделать. Ты и дитя Тортоллы сокрушите Немесиса раз и навсегда. Покончите с узурпатором!$B$BНайди меня, если ты потеряешь своего спутника.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте тотем Тортоллы и победите Немесиса вместе со своим спутником. Если вы потеряете дитя Тортоллы, вернитесь к Гарунду Горному Пику.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Захватчик пал!$B$BСумеречный Молот мечтал создать собственный пантеон из оскверненных древних, чтобы править землей, водой и воздухом. С твой помощью нам удалось с ними покончить.$B$BТортолла должен узнать об этом!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гарунду Горному Пику в Раскаленный тигель.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Воспользуйтесь тотемом и помощью вашего спутника, черепахи, чтобы выжить во время схватки с противником. С лжебогом нужно покончить!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Немесис Узурпатор',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (25924,'Зов долга','Послушай-ка, |3-6($r)!$B$BВозле побережья Восточных королевств образовался новый остров – и там идет тяжелая битва за эту землю!$B$BВ случае нашей победы Штормград будет совершенно беззащитен!$B$BПришло время нанести удар!$B$BЯвись с докладом в гавань, чтобы отправиться к месту битвы.$B$BВсе военные суда уже в бою, так что поднимешься на борт корабля наемников, который зафрахтовал сам вождь.','Отправляйтесь в бой на корабле наемников.','Бьюсь об заклад, не такое сражение ты ожидал увидеть. И все же это бой, вскоре сам убедишься...','Отправляйтесь в Вайш\'ир на корабле наемников','Обратитесь к Эрунаку на Серпантине Бессмертного.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зов долга',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Послушай-ка, |3-6($r)!$B$BВозле побережья Восточных королевств образовался новый остров – и там идет тяжелая битва за эту землю!$B$BВ случае нашей победы Штормград будет совершенно беззащитен!$B$BПришло время нанести удар!$B$BЯвись с докладом в гавань, чтобы отправиться к месту битвы.$B$BВсе военные суда уже в бою, так что поднимешься на борт корабля наемников, который зафрахтовал сам вождь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в бой на корабле наемников.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Бьюсь об заклад, не такое сражение ты ожидал увидеть. И все же это бой, вскоре сам убедишься...',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Отправляйтесь в Вайш\'ир на корабле наемников',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Обратитесь к Эрунаку на Серпантине Бессмертного.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25925,'Убейте 20 солдат Орды и уничтожьте 3 кром\'гарских разрушителя в долине Боевого Шрама.','Мы видели, как взорвалась бомба. Она нанесла ужасные разрушения… Хорошо это или нет, только Плато Наблюдателей пока не пострадало. Но, к несчастью, нам некуда бежать.','Найдите иерофанта Малика на Плато Наблюдателей в Когтистых горах.') ON DUPLICATE KEY UPDATE `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 20 солдат Орды и уничтожьте 3 кром\'гарских разрушителя в долине Боевого Шрама.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мы видели, как взорвалась бомба. Она нанесла ужасные разрушения… Хорошо это или нет, только Плато Наблюдателей пока не пострадало. Но, к несчастью, нам некуда бежать.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Найдите иерофанта Малика на Плато Наблюдателей в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25926,'Погрязшие в трясине ненависти','Трясинники, что обитают к западу отсюда, – не братья мне... Они – вопль израненной земли, воплощение мерзостного процесса гниения.$B$BТебе не понять... Кишащие внутри гнилостными спорами, они принимают облик моих сородичей и выдавливают жизнь из болота. Они забирают все, оставляя взамен только разложение. Ничего не осталось, ничего!$B$BПомоги мне обрести покой, |3-6($r). Убей трясинников, очисти землю, и тогда, быть может, душа моя перестанет терзаться.','Убейте 10 тлеющих трясинников.','А-ах… да. Боль болота ослабла.$B$BНо ему по-прежнему угрожает опасность. Хищники не дремлют. Я их вижу!','Вернитесь к Ретилю Стражу Природы в Рощу Стража Природы, что в Болотине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Погрязшие в трясине ненависти',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Трясинники, что обитают к западу отсюда, – не братья мне... Они – вопль израненной земли, воплощение мерзостного процесса гниения.$B$BТебе не понять... Кишащие внутри гнилостными спорами, они принимают облик моих сородичей и выдавливают жизнь из болота. Они забирают все, оставляя взамен только разложение. Ничего не осталось, ничего!$B$BПомоги мне обрести покой, |3-6($r). Убей трясинников, очисти землю, и тогда, быть может, душа моя перестанет терзаться.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 тлеющих трясинников.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А-ах… да. Боль болота ослабла.$B$BНо ему по-прежнему угрожает опасность. Хищники не дремлют. Я их вижу!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ретилю Стражу Природы в Рощу Стража Природы, что в Болотине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25927,'Устрашающее пламя','Слишком долго пламя угрожало мне... Слишком долго... Но теперь страдают уже не мелкие земные твари, не какие-то жалкие букашки...$B$BГорят поля! Холмы и нагорья кричат, |3-6($r), они кричат от боли. Элементали, вызванные сюда, пожирают все живое вокруг себя.$B$BОт них нет спасения. Останови их, ОСТАНОВИ! Уничтожь тех, кто разжигает пламя...','Убейте 8 буйных элементалей огня.','Да… языки пламени угасли. Огонь более не угрожает этой земле. Теперь здесь воцарился покой.','Вернитесь к Ретилю Стражу Природы в Рощу Стража Природы, что в Болотине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Устрашающее пламя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слишком долго пламя угрожало мне... Слишком долго... Но теперь страдают уже не мелкие земные твари, не какие-то жалкие букашки...$B$BГорят поля! Холмы и нагорья кричат, |3-6($r), они кричат от боли. Элементали, вызванные сюда, пожирают все живое вокруг себя.$B$BОт них нет спасения. Останови их, ОСТАНОВИ! Уничтожь тех, кто разжигает пламя...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 буйных элементалей огня.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да… языки пламени угасли. Огонь более не угрожает этой земле. Теперь здесь воцарился покой.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ретилю Стражу Природы в Рощу Стража Природы, что в Болотине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25928,'Триумф Тортоллы','Я выведу отсюда детей Тортоллы и запечатаю оскверненный портал.$B$BА ты отправляйся к Тортолле и расскажи ему о нашей победе. Просто пройди через огненные врата. Древний будет доволен!','Пройдите сквозь огненные врата и вернитесь к Тортолле на Выжженную равнину на Хиджале.','Ты был на Огненных Просторах?$B$BНемесис мертв?$B$BЕще одной угрозой меньше.$B$BБлагодарю тебя.','Пройдите сквозь огненные врата и вернитесь к Тортолле на Выжженную равнину на Хиджале.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Триумф Тортоллы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я выведу отсюда детей Тортоллы и запечатаю оскверненный портал.$B$BА ты отправляйся к Тортолле и расскажи ему о нашей победе. Просто пройди через огненные врата. Древний будет доволен!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Пройдите сквозь огненные врата и вернитесь к Тортолле на Выжженную равнину на Хиджале.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты был на Огненных Просторах?$B$BНемесис мертв?$B$BЕще одной угрозой меньше.$B$BБлагодарю тебя.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Пройдите сквозь огненные врата и вернитесь к Тортолле на Выжженную равнину на Хиджале.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25929,'Морской волк','Приветствую тебя, |3-6($c). Меня зовут Эрунак, мне тоже удалось выжить.$B$BОднако боюсь, неприятности у тебя только начались. В здешних водах рыщут наги, они нападают на все живое.$B$BА ты слишком $gнеприспособлен:неприспособлена; и можешь погибнуть, но я тебе помогу.$B$BРядом с этим кораблем обитает особая разновидность морских звезд. Поймай несколько штук, да раздобудь раковину стромбиды. Я подготовлю заклинание, которое повысит твои шансы на выживание.','Добудьте с морского дна в Судьбе Легиона 3 солоноводных морских звезды и раковину стромбиды.','Поговорите с Эрунаком на Серпантине Бессмертного.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Морской волк',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приветствую тебя, |3-6($c). Меня зовут Эрунак, мне тоже удалось выжить.$B$BОднако боюсь, неприятности у тебя только начались. В здешних водах рыщут наги, они нападают на все живое.$B$BА ты слишком $gнеприспособлен:неприспособлена; и можешь погибнуть, но я тебе помогу.$B$BРядом с этим кораблем обитает особая разновидность морских звезд. Поймай несколько штук, да раздобудь раковину стромбиды. Я подготовлю заклинание, которое повысит твои шансы на выживание.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте с морского дна в Судьбе Легиона 3 солоноводных морских звезды и раковину стромбиды.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Эрунаком на Серпантине Бессмертного.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`) VALUES (25930,'Подъем в долину','Мне сказали, что до большого смещения пластов Обугленная долина была долиной, отрезанной от моря. А теперь стоит только бросить взгляд на юг, чтобы понять, что Обугленная долина вообще не долина, а центр высокой вулканической активности.$B$BСэлсбери тут сваял устройство, которое позволит нам подняться к жерлу вулкана. Используй его, чтобы забраться на вершину и посмотреть, что там да как.$B$BЯ буду на связи при помощи этого ГНМ-передатчика, который Сэлсбери любезно предоставил в мое распоряжение.','Используйте ракетный агрегат Сэлсбери для подъема на вулкан Обугленной долины.','Подъем на вулкан Обугленной долины') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подъем в долину',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне сказали, что до большого смещения пластов Обугленная долина была долиной, отрезанной от моря. А теперь стоит только бросить взгляд на юг, чтобы понять, что Обугленная долина вообще не долина, а центр высокой вулканической активности.$B$BСэлсбери тут сваял устройство, которое позволит нам подняться к жерлу вулкана. Используй его, чтобы забраться на вершину и посмотреть, что там да как.$B$BЯ буду на связи при помощи этого ГНМ-передатчика, который Сэлсбери любезно предоставил в мое распоряжение.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте ракетный агрегат Сэлсбери для подъема на вулкан Обугленной долины.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Подъем на вулкан Обугленной долины',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (25931,'Потомство Селдаррии','<ГНМ-передатчик жужжит.>$B$BОсторожно, $n. Не надо тебе будить этого черного дракона.$B$BТеперь осмотрись по сторонам. Если это гнездо, то тут где-то должны быть яйца черного дракона. Поищи их и уничтожь все, какие увидишь.$B$BВозвращайся, как только найдешь и уничтожишь яйца Селдаррии.$B$BДа пребудет с тобой Голдринн!','Уничтожьте 5 яиц Селдаррии.','Потрясающий успех! Пусть это небольшая победа над отродьями Смертокрыла, но все же победа!','Вернитесь к иерофанту Малику на Плато Наблюдателей в Когтистых горах.','Осторожно. Достаточно одной ошибки, и все пропало.','Иерофант Малик') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Потомство Селдаррии',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<ГНМ-передатчик жужжит.>$B$BОсторожно, $n. Не надо тебе будить этого черного дракона.$B$BТеперь осмотрись по сторонам. Если это гнездо, то тут где-то должны быть яйца черного дракона. Поищи их и уничтожь все, какие увидишь.$B$BВозвращайся, как только найдешь и уничтожишь яйца Селдаррии.$B$BДа пребудет с тобой Голдринн!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 5 яиц Селдаррии.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Потрясающий успех! Пусть это небольшая победа над отродьями Смертокрыла, но все же победа!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к иерофанту Малику на Плато Наблюдателей в Когтистых горах.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Осторожно. Достаточно одной ошибки, и все пропало.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Иерофант Малик',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (25932,'Набеги ночь за ночью','Донесения, которые я отправляю капитану Таррану, не могут передать всего масштаба проблем, которые мы испытываем от Мерзлогривов. Твое нападение на деревню дало небольшую передышку. Набеги троллей по-прежнему часты, но их ряды поредели.$b$bНо даже несмотря на это, мои люди устали и их боевой дух упал. Не можешь ли ты помочь нам в борьбе против налетчиков Мерзлогривов? Они могут вернуться в любое время.','Помогите сержанту Кремнемолоту и его горным пехотинцам защитить ферму Янтарленов от налетчиков из клана Мерзлогривов.','С твоей помощью нам удалось значительно ослабить врагов. В их рядах не было таких потерь с тех самых пор, как начались набеги. Теперь пришло время упрочить наше положение.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Набеги ночь за ночью',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Донесения, которые я отправляю капитану Таррану, не могут передать всего масштаба проблем, которые мы испытываем от Мерзлогривов. Твое нападение на деревню дало небольшую передышку. Набеги троллей по-прежнему часты, но их ряды поредели.$b$bНо даже несмотря на это, мои люди устали и их боевой дух упал. Не можешь ли ты помочь нам в борьбе против налетчиков Мерзлогривов? Они могут вернуться в любое время.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Помогите сержанту Кремнемолоту и его горным пехотинцам защитить ферму Янтарленов от налетчиков из клана Мерзлогривов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','С твоей помощью нам удалось значительно ослабить врагов. В их рядах не было таких потерь с тех самых пор, как начались набеги. Теперь пришло время упрочить наше положение.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (25933,'Помощь карьеру','Спасибо за все, чем ты $gпомог:помогла; нам здесь, $n.$b$bМой двоюродный брат работает на руднике в карьере Гол\'Болар, но с тех пор, как трогги наводнили рудник и контролируют его, работать там стало невозможно. Карьер и лагерь находятся к юго-востоку от фермы. Не поговоришь ли ты со штейгером, чтобы выяснить, что можно сделать?','Поговорите со штейгером Камнелобом в карьере Гол\'Болар.','Сержант Кремнемолот? Я его не помню, но да, среди рудокопов Кремнемолот есть. Он один из тех, кому посчастливилось выбраться из рудника. А большинство моих ребят до сих пор там.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Помощь карьеру',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Спасибо за все, чем ты $gпомог:помогла; нам здесь, $n.$b$bМой двоюродный брат работает на руднике в карьере Гол\'Болар, но с тех пор, как трогги наводнили рудник и контролируют его, работать там стало невозможно. Карьер и лагерь находятся к юго-востоку от фермы. Не поговоришь ли ты со штейгером, чтобы выяснить, что можно сделать?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите со штейгером Камнелобом в карьере Гол\'Болар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сержант Кремнемолот? Я его не помню, но да, среди рудокопов Кремнемолот есть. Он один из тех, кому посчастливилось выбраться из рудника. А большинство моих ребят до сих пор там.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25934,'Первый в мире гнорген','Приветствую, $gгражданин:гражданка; позволь мне представиться. Я Сэлсбери, и скоро я стану первым в мире гноргеном. Малик заверил меня, что как только моя работа здесь будет завершена, он даст мне дар воргенов.$B$BТак, с формальностями покончено, теперь к делу!$B$BВ Обугленной долине, к югу отсюда, бродят недавно созданные огненные элементали. Мне отчаянно нужно редкое пылающее сердце огня с одного из этих духов. Добудь его мне, и я на один шаг стану ближе к моей цели – стать гноргеном!','Добудьте 1 пылающее сердце огня.','Блестяще. Это позволит мне закончить мою последнюю работу и наконец-то научиться обретать волчье обличье!$B$B<Сэлсбери пытается выть.>','Тебе удалось добыть пылающее сердце огня?','Вернитесь к Сэлсбери "На помощь" на Плато Наблюдателей в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Первый в мире гнорген',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приветствую, $gгражданин:гражданка; позволь мне представиться. Я Сэлсбери, и скоро я стану первым в мире гноргеном. Малик заверил меня, что как только моя работа здесь будет завершена, он даст мне дар воргенов.$B$BТак, с формальностями покончено, теперь к делу!$B$BВ Обугленной долине, к югу отсюда, бродят недавно созданные огненные элементали. Мне отчаянно нужно редкое пылающее сердце огня с одного из этих духов. Добудь его мне, и я на один шаг стану ближе к моей цели – стать гноргеном!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 1 пылающее сердце огня.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Блестяще. Это позволит мне закончить мою последнюю работу и наконец-то научиться обретать волчье обличье!$B$B<Сэлсбери пытается выть.>',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось добыть пылающее сердце огня?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сэлсбери "На помощь" на Плато Наблюдателей в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25935,'Голодные щенки','О, новенькие! Это ты удачно $gзашел, парень:зашла, девушка;! Щенки проголодались, а у нас корма вообще не осталось.$B$BПо счастью, они любят драконье мясо, которого полно в Обугленной долине, к югу отсюда.$B$BБудь $gхорошим мальчиком:хорошей девочкой;, раздобудь мне несколько фунтов филе черного дракончика.','Добудьте 6 филе черного дракончика.','Вернитесь к псарю Джонатану на Плато Наблюдателей в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Голодные щенки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','О, новенькие! Это ты удачно $gзашел, парень:зашла, девушка;! Щенки проголодались, а у нас корма вообще не осталось.$B$BПо счастью, они любят драконье мясо, которого полно в Обугленной долине, к югу отсюда.$B$BБудь $gхорошим мальчиком:хорошей девочкой;, раздобудь мне несколько фунтов филе черного дракончика.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 6 филе черного дракончика.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к псарю Джонатану на Плато Наблюдателей в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25936,'Время вернуть должок','Теперь ты можешь свободно перемещаться по этой местности и не бояться потонуть.$B$BТак что приступим к работе.$B$BНачнем с того, что пока мы тут ведем беседы, наши союзники вокруг идут ко дну. Я выручил тебя – а теперь ты помоги им.$B$BЯ наложил чары на раковину, что ты мне $gпринес:принесла;. Воспользуйся ею и выручи наших братьев.$B$BПоторопись!','Воспользуйтесь зачарованной раковиной для спасения 6 тонущих воинов.','Поговорите с Эрунаком на Серпантине Бессмертного.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Время вернуть должок',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь ты можешь свободно перемещаться по этой местности и не бояться потонуть.$B$BТак что приступим к работе.$B$BНачнем с того, что пока мы тут ведем беседы, наши союзники вокруг идут ко дну. Я выручил тебя – а теперь ты помоги им.$B$BЯ наложил чары на раковину, что ты мне $gпринес:принесла;. Воспользуйся ею и выручи наших братьев.$B$BПоторопись!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь зачарованной раковиной для спасения 6 тонущих воинов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Эрунаком на Серпантине Бессмертного.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25937,'Бесценные сокровища','В карьере не только добывали руду. Я возглавлял команду землечерпов Лиги исследователей, которая занималась поиском бесценных древних артефактов.$b$bМне удалось выбраться, но мои коллеги находились гораздо глубже меня и не пережили первой атаки троггов.$b$bОни очень гордились своей работой и рисковали своими жизнями во имя нашей истории. Если ты отправляешься на рудник, возьми с собой эту кирку и постарайся найти что-нибудь на раскопках, начатых землечерпами.','Достаньте из карьера Гол\'Болар 8 замерзших артефактов.','Удалось найти какие-нибудь артефакты?','Вернитесь к геологу Драгану в карьер Гол\'Болар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бесценные сокровища',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В карьере не только добывали руду. Я возглавлял команду землечерпов Лиги исследователей, которая занималась поиском бесценных древних артефактов.$b$bМне удалось выбраться, но мои коллеги находились гораздо глубже меня и не пережили первой атаки троггов.$b$bОни очень гордились своей работой и рисковали своими жизнями во имя нашей истории. Если ты отправляешься на рудник, возьми с собой эту кирку и постарайся найти что-нибудь на раскопках, начатых землечерпами.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Достаньте из карьера Гол\'Болар 8 замерзших артефактов.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось найти какие-нибудь артефакты?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к геологу Драгану в карьер Гол\'Болар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (25938,'Помощь Пустошам','Мы получили тревожное сообщение с Высоты Найджела, что в Пустошах. Похоже, сдвиг пластов создал кучу новых проблем, а для их решения у них оборудования не хватает. Больше никакой информации ко мне не поступало.$B$BДоложись офицеру Дженки в Пустошах. Она направит тебя к Высоте Найджела.$B$BУдачи, $n.','Доложитесь офицеру Дженки, которая находится в Тефрис-Аране в Пустошах.','Стой, кто идет!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Помощь Пустошам',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы получили тревожное сообщение с Высоты Найджела, что в Пустошах. Похоже, сдвиг пластов создал кучу новых проблем, а для их решения у них оборудования не хватает. Больше никакой информации ко мне не поступало.$B$BДоложись офицеру Дженки в Пустошах. Она направит тебя к Высоте Найджела.$B$BУдачи, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доложитесь офицеру Дженки, которая находится в Тефрис-Аране в Пустошах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Стой, кто идет!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25939,'Спасение торфяников','По Зловещему холму рыскают элементали, и сама земля под ними занимается пламенем. В торфяном болоте, подобном этому, огню всегда найдется, чем подкормиться.$B$BТы $gдолжен:должна; погасить очаги, пока огонь не распространился. Возьми этот цветок... В нем – благословение природы, душа дождя. С его помощью ты сможешь справиться с огнем.$B$BОн пригодится и в борьбе с самими элементалями.','С помощью благословенной водяной лилии потушите 7 блуждающих огоньков.','Ферилон Дитя Листвы ждет вас в Роще Стража Природы, что в Болотине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спасение торфяников',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','По Зловещему холму рыскают элементали, и сама земля под ними занимается пламенем. В торфяном болоте, подобном этому, огню всегда найдется, чем подкормиться.$B$BТы $gдолжен:должна; погасить очаги, пока огонь не распространился. Возьми этот цветок... В нем – благословение природы, душа дождя. С его помощью ты сможешь справиться с огнем.$B$BОн пригодится и в борьбе с самими элементалями.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','С помощью благословенной водяной лилии потушите 7 блуждающих огоньков.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Ферилон Дитя Листвы ждет вас в Роще Стража Природы, что в Болотине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (25940,'Помощь в Роще Трелей','Благодаря твоим подвигам в Пекле у нас появилась возможность обуздать огонь.$B$BНо природа все еще в опасности: хранитель Талдрос отправился сквозь пламя на север, к Роще Трелей.$B$BПоспеши туда и помоги ему!','Нашего леса больше нет!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Помощь в Роще Трелей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Благодаря твоим подвигам в Пекле у нас появилась возможность обуздать огонь.$B$BНо природа все еще в опасности: хранитель Талдрос отправился сквозь пламя на север, к Роще Трелей.$B$BПоспеши туда и помоги ему!',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Нашего леса больше нет!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25941,'Отдохновение для утомленных','Превосходно, |3-6($r), но предстоит еще многое сделать, а силы мои на исходе.$B$BЯ потратил очень много энергии на то, чтобы отправить Служителям Земли сигнал с просьбой о помощи.$B$BЧтобы от меня и дальше был какой-то толк, мне необходим отдых.$B$BПоговори с главным тех, кого ты $gспас:спасла;, и постарайся сделать все от тебя зависящее, чтобы помочь им подготовиться к бою.$B$BНаги прочесывают воды, разыскивая нас. Пройдет немного времени – и они вернутся c подмогой.','Поговорите с легионером Назгримом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отдохновение для утомленных',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Превосходно, |3-6($r), но предстоит еще многое сделать, а силы мои на исходе.$B$BЯ потратил очень много энергии на то, чтобы отправить Служителям Земли сигнал с просьбой о помощи.$B$BЧтобы от меня и дальше был какой-то толк, мне необходим отдых.$B$BПоговори с главным тех, кого ты $gспас:спасла;, и постарайся сделать все от тебя зависящее, чтобы помочь им подготовиться к бою.$B$BНаги прочесывают воды, разыскивая нас. Пройдет немного времени – и они вернутся c подмогой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с легионером Назгримом.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25942,'Выиграть время','Сегодня погибло немало хороших бойцов.$B$BШаман говорит, нельзя терять ни минуты, если мы не хотим пополнить ряды павших.$B$BНаги прочесывают эти воды в поисках уцелевших.$B$BА мы еще не готовы к сражению, |3-6($r). Ты $gдолжен:должна; выиграть нам немного времени на подготовку.$B$BРазыщи наг и попытайся их задержать.','Убейте 8 налетчиков Зин\'жатара в Судьбе Легиона.','Будем надеяться, это даст нам немного времени...','Поговорите с легионером Назгримом на Серпантине Бессмертного.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Выиграть время',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сегодня погибло немало хороших бойцов.$B$BШаман говорит, нельзя терять ни минуты, если мы не хотим пополнить ряды павших.$B$BНаги прочесывают эти воды в поисках уцелевших.$B$BА мы еще не готовы к сражению, |3-6($r). Ты $gдолжен:должна; выиграть нам немного времени на подготовку.$B$BРазыщи наг и попытайся их задержать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 налетчиков Зин\'жатара в Судьбе Легиона.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Будем надеяться, это даст нам немного времени...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с легионером Назгримом на Серпантине Бессмертного.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25943,'Голод не тетка','Чтобы подготовить орков к битве, мне понадобится твоя помощь.$B$BКаждый хороший военачальник знает – воинов надо как следует кормить. На голодный желудок много не навоюешь. Нет еды – нет победы.$B$BМоим солдатам в последнее время пришлось туго. Им нужно пополнить силы. А где взять силу, если есть нечего?!$B$BКстати, я там на дне видел крабов... Ну, в общем, ты понимаешь, что надо делать.','Добудьте 8 кусков сочного мяса крабов c быстролапов с надтреснутой клешней.','Отличный улов!$B$BСкоро мы наберемся сил для битвы.','Поговорите с легионером Назгримом на Серпантине Бессмертного.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Голод не тетка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чтобы подготовить орков к битве, мне понадобится твоя помощь.$B$BКаждый хороший военачальник знает – воинов надо как следует кормить. На голодный желудок много не навоюешь. Нет еды – нет победы.$B$BМоим солдатам в последнее время пришлось туго. Им нужно пополнить силы. А где взять силу, если есть нечего?!$B$BКстати, я там на дне видел крабов... Ну, в общем, ты понимаешь, что надо делать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 8 кусков сочного мяса крабов c быстролапов с надтреснутой клешней.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличный улов!$B$BСкоро мы наберемся сил для битвы.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с легионером Назгримом на Серпантине Бессмертного.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (25944,'Во всеоружии','Слушай, нам пришлось бросить оружие и почти все доспехи – иначе мы бы утонули.$B$BЭрунак говорит, наги готовят массированную атаку, и у меня нет оснований ему не доверять.$B$BЧтобы выстоять под натиском наг, надо найти брошенное оружие. Без твоей помощи никак.$B$BОружие должно быть на дне, рядом с нашим затонувшим кораблем и к северу от него.$B$BПоторопись, |3-6($r). Враг может подойти в любую минуту.','Поговорите с легионером Назгримом на Серпантине Бессмертного.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Во всеоружии',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слушай, нам пришлось бросить оружие и почти все доспехи – иначе мы бы утонули.$B$BЭрунак говорит, наги готовят массированную атаку, и у меня нет оснований ему не доверять.$B$BЧтобы выстоять под натиском наг, надо найти брошенное оружие. Без твоей помощи никак.$B$BОружие должно быть на дне, рядом с нашим затонувшим кораблем и к северу от него.$B$BПоторопись, |3-6($r). Враг может подойти в любую минуту.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с легионером Назгримом на Серпантине Бессмертного.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (25945,'Мы все делаем одно дело. Или два...','Теперь ты в армии Адского Крика, $n, а в армии Адского Крика мы радуемся жизни и делаем, что хотим. Прошли те времена, когда наш народ голодал на улицах Оргриммара, а мы подписывали соглашения с эльфами. Сейчас мы просто берем, что нам нужно. Калимдор принадлежит Орде!$B$BАльянс пытается остановить нас. Эти уроды, видите ли, недовольны тем, что им принадлежит большая часть Восточных королевств, им нужно все!$B$BВластитель Кром\'гар созывает войска в Когтистые горы. Присоединяйся к каравану – и вперед!','Доставьте кром\'гарский фургон к Изгибу Когтистых гор.','Пока ты в Когтистых горах и в армии Кром\'гара, будешь одет по форме! Ясно? Ты меня хорошо слышишь?! Увижу тебя без накидки с эмблемой Адского Крика – такого пинка отвешу, что шнурками подавишься.','Кром\'гарский фургон доставлен к Изгибу','Идите к Саурбозу в Изгиб в Когтистые горы, чтобы вступить в армию Кром\'гара.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мы все делаем одно дело. Или два...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь ты в армии Адского Крика, $n, а в армии Адского Крика мы радуемся жизни и делаем, что хотим. Прошли те времена, когда наш народ голодал на улицах Оргриммара, а мы подписывали соглашения с эльфами. Сейчас мы просто берем, что нам нужно. Калимдор принадлежит Орде!$B$BАльянс пытается остановить нас. Эти уроды, видите ли, недовольны тем, что им принадлежит большая часть Восточных королевств, им нужно все!$B$BВластитель Кром\'гар созывает войска в Когтистые горы. Присоединяйся к каравану – и вперед!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте кром\'гарский фургон к Изгибу Когтистых гор.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Пока ты в Когтистых горах и в армии Кром\'гара, будешь одет по форме! Ясно? Ты меня хорошо слышишь?! Увижу тебя без накидки с эмблемой Адского Крика – такого пинка отвешу, что шнурками подавишься.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Кром\'гарский фургон доставлен к Изгибу',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Идите к Саурбозу в Изгиб в Когтистые горы, чтобы вступить в армию Кром\'гара.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25946,'Тайна шлема','На этом шлеме и другом оборудовании стоит печать Штормграда. Наверняка они с корабля Альянса, который постигла та же участь, что и ваше судно.$B$BВидно, что эти вещи слишком сложные и прочные; вряд ли их использовали для обычных погружений. Может, Назгрим что про него знает...','Отнесите оборудование СМЭШ с корабля Альянса легионеру Назгриму на Серпантин Бессмертного.','Поговорите с легионером Назгримом на Серпантине Бессмертного.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тайна шлема',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На этом шлеме и другом оборудовании стоит печать Штормграда. Наверняка они с корабля Альянса, который постигла та же участь, что и ваше судно.$B$BВидно, что эти вещи слишком сложные и прочные; вряд ли их использовали для обычных погружений. Может, Назгрим что про него знает...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите оборудование СМЭШ с корабля Альянса легионеру Назгриму на Серпантин Бессмертного.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с легионером Назгримом на Серпантине Бессмертного.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25947,'Что упало, то пропало','Да, знакомый шлем, |3-6($r). Хорошо, что $gпринес:принесла;.$B$BШлем отряда особого назначения Альянса – подводные боевые действия.$B$BПохоже, кроме стычек с нами у них тут еще какие-то дела.$B$BНа дне, вероятно, находится и другое их снаряжение. Если еще что-нибудь отыщешь, неси – это может изменить ситуацию в пользу Авангарда.','Найдите 5 предметов оборудования штормградского СМЭШ.','Отлично!$B$BМы как никогда готовы к встрече с нагами!','Удалось найти еще что-нибудь из снаряжения Альянса?','Поговорите с легионером Назгримом на Серпантине Бессмертного.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Что упало, то пропало',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Да, знакомый шлем, |3-6($r). Хорошо, что $gпринес:принесла;.$B$BШлем отряда особого назначения Альянса – подводные боевые действия.$B$BПохоже, кроме стычек с нами у них тут еще какие-то дела.$B$BНа дне, вероятно, находится и другое их снаряжение. Если еще что-нибудь отыщешь, неси – это может изменить ситуацию в пользу Авангарда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите 5 предметов оборудования штормградского СМЭШ.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично!$B$BМы как никогда готовы к встрече с нагами!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось найти еще что-нибудь из снаряжения Альянса?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с легионером Назгримом на Серпантине Бессмертного.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25948,'Вперед!','Время пришло, |3-6($c).$b$bМы готовы как никогда!$b$bЯ поговорю с Авангардом, а потом мы отправимся в море навстречу своей судьбе.','Поговорите с легионером Назгримом на Серпантине Бессмертного.','Времени не осталось.$B$BПора действовать…','Поговорите с легионером Назгримом на Серпантине Бессмертного.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вперед!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Время пришло, |3-6($c).$b$bМы готовы как никогда!$b$bЯ поговорю с Авангардом, а потом мы отправимся в море навстречу своей судьбе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с легионером Назгримом на Серпантине Бессмертного.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Времени не осталось.$B$BПора действовать…',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с легионером Назгримом на Серпантине Бессмертного.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25949,'Кровь и гром!','Пора браться за дело, |3-6($r)!$B$BБудем защищать корабль до последнего. Пусть змеюки в следующий раз дважды подумают, прежде чем сюда соваться.$B$BЗа Орду!','Помогите легионеру Назгриму защитить Серпантин Бессмертного.','Служители Земли получили мой сигнал бедствия и выслали подмогу – очень вовремя, надо заметить.$B$BНадеюсь, вскоре придет еще подкрепление. Нас тут всего лишь горстка против целой вражеской армии.','Серпантин Бессмертного захвачен врагом. Поговорите с Эрунаком в Конце отмели.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кровь и гром!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пора браться за дело, |3-6($r)!$B$BБудем защищать корабль до последнего. Пусть змеюки в следующий раз дважды подумают, прежде чем сюда соваться.$B$BЗа Орду!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Помогите легионеру Назгриму защитить Серпантин Бессмертного.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Служители Земли получили мой сигнал бедствия и выслали подмогу – очень вовремя, надо заметить.$B$BНадеюсь, вскоре придет еще подкрепление. Нас тут всего лишь горстка против целой вражеской армии.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Серпантин Бессмертного захвачен врагом. Поговорите с Эрунаком в Конце отмели.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25950,'Истребление Сира\'кесс','Так ты и есть $gэтот:эта; $n, о $gкотором:которой; тут все говорят? Душевно рада знакомству. Как говорится, лучше один раз увидеть...$B$BТак, ладно. Перейдем к делу. Мне нужно, чтобы ты $gотправился:отправилась; на северо-запад к берегу Сира\'кесс и $gпоказал:показала; этим змеюкам, почем фунт лиха.$B$BОни давно нарываются на неприятности, и мы им это устроим. Чтоб впредь неповадно было.','Убейте 10 наг Сира\'кесс.','Вернитесь к лейтенанту Топперу по прозвищу "Лисяра" в Темную пещеру в Вайш\'ире.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Истребление Сира\'кесс',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Так ты и есть $gэтот:эта; $n, о $gкотором:которой; тут все говорят? Душевно рада знакомству. Как говорится, лучше один раз увидеть...$B$BТак, ладно. Перейдем к делу. Мне нужно, чтобы ты $gотправился:отправилась; на северо-запад к берегу Сира\'кесс и $gпоказал:показала; этим змеюкам, почем фунт лиха.$B$BОни давно нарываются на неприятности, и мы им это устроим. Чтоб впредь неповадно было.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 наг Сира\'кесс.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лейтенанту Топперу по прозвищу "Лисяра" в Темную пещеру в Вайш\'ире.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25951,'Приговор','Немедленно отправляйся на восточный мост. Леди Наз\'жар и Повелитель глубин собрали там оставшиеся войска.$B$BСледуй указаниям госпожи и удерживай мост, пока мы не завершим ритуал.$B$BС прибытием наших союзников квалдиры будут обречены на смерть.','Удерживайте мост на террасе Кель\'Дормир, пока не прибудут союзники Леди Сира\'кесс.$B$BЭто задание из цикла "Видения воительницы Леди Наз\'жар". Чтобы вернуться к видению, в нужном месте воспользуйтесь клинком воительницы Леди Наз\'жар.','Ты самая искусная воительница. Сегодня ты заслужила великие почести.','Сражайся, Воительница. Победа будет за нами.','Поговорите с Леди Наз\'жар на террасе Кель\'Дормир.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приговор',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Немедленно отправляйся на восточный мост. Леди Наз\'жар и Повелитель глубин собрали там оставшиеся войска.$B$BСледуй указаниям госпожи и удерживай мост, пока мы не завершим ритуал.$B$BС прибытием наших союзников квалдиры будут обречены на смерть.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Удерживайте мост на террасе Кель\'Дормир, пока не прибудут союзники Леди Сира\'кесс.$B$BЭто задание из цикла "Видения воительницы Леди Наз\'жар". Чтобы вернуться к видению, в нужном месте воспользуйтесь клинком воительницы Леди Наз\'жар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты самая искусная воительница. Сегодня ты заслужила великие почести.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Сражайся, Воительница. Победа будет за нами.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Леди Наз\'жар на террасе Кель\'Дормир.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (25952,'Внезапный удар','Наш побег трудно было не заметить, но наги в руинах либо правда не знают об этом, либо не видят в нас никакой угрозы. И этим надо воспользоваться – мы нанесем им удар!$B$BОтправляйся на нижний ярус руин к западу отсюда и уничтожь там как можно больше патрульных. Смотри, чтобы ни один не ушел – враг не должен узнать, что мы поселились в этой пещере.','Вернитесь к капитану Злобешипу на базу Легиона.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Внезапный удар',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наш побег трудно было не заметить, но наги в руинах либо правда не знают об этом, либо не видят в нас никакой угрозы. И этим надо воспользоваться – мы нанесем им удар!$B$BОтправляйся на нижний ярус руин к западу отсюда и уничтожь там как можно больше патрульных. Смотри, чтобы ни один не ушел – враг не должен узнать, что мы поселились в этой пещере.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Злобешипу на базу Легиона.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25953,'Быстрый подход','Я взял на себя смелость провести предварительную разведку и вот что выяснил: хотя наги не знают точно нашего расположения, они готовы к нападению.$B$BЗа часовыми наг находятся специальные магические устройства, оповещающие о приходе незваных гостей. К счастью, они пожертвовали качеством в угоду количеству: сигнал тревоги начинает передаваться не сразу после обнаружения вторжения. Этого времени как раз хватит, чтобы уничтожить наблюдателей.$B$BДумаю, ты справишься до прибытия других солдат.','Великолепно, Моарана, и как раз вовремя. Капитан только начал посылать туда других солдат. У них сильные руки, но, думаю, им не хватает твоей внимательности и ловкости.$B$BКакая удача, что ты была с нами, когда случилась беда. Думаю, в предстоящих событиях ты тоже сыграешь немалую роль.','Вернитесь к легионеру Назгриму на базу Легиона.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Быстрый подход',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я взял на себя смелость провести предварительную разведку и вот что выяснил: хотя наги не знают точно нашего расположения, они готовы к нападению.$B$BЗа часовыми наг находятся специальные магические устройства, оповещающие о приходе незваных гостей. К счастью, они пожертвовали качеством в угоду количеству: сигнал тревоги начинает передаваться не сразу после обнаружения вторжения. Этого времени как раз хватит, чтобы уничтожить наблюдателей.$B$BДумаю, ты справишься до прибытия других солдат.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Великолепно, Моарана, и как раз вовремя. Капитан только начал посылать туда других солдат. У них сильные руки, но, думаю, им не хватает твоей внимательности и ловкости.$B$BКакая удача, что ты была с нами, когда случилась беда. Думаю, в предстоящих событиях ты тоже сыграешь немалую роль.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к легионеру Назгриму на базу Легиона.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25954,'Чтобы занять время','Тебя ведь $n зовут, да? Мне нужна твоя помощь. Знаю, большинство моих сородичей считает, что сейчас главное – спасение наших жизней, но я не могу не думать о памяти предков.$B$BВо время правления Азшары здесь был один из главных эльфийских городов, в нем полно артефактов величайшего исторического значения. Все, о чем я прошу, – смотри в оба и обращай внимание на все необычные предметы в городе.','Осмотрите 4 неразрушенные статуи в садах Вайш\'ира.','Благодарю за то, что серьезно отнеслась к моей просьбе.$B$BЭто, можно сказать, первое доказательство существования других членов семьи Вайш. Очень интересно. А о двух других личностях я даже и не слышала.$B$BВеликий Раскол уничтожил нашу историю, но теперь появился шанс восстановить хоть какие-то ее страницы.','Вернитесь к Элендри Золотое Чело на базу Легиона.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чтобы занять время',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебя ведь $n зовут, да? Мне нужна твоя помощь. Знаю, большинство моих сородичей считает, что сейчас главное – спасение наших жизней, но я не могу не думать о памяти предков.$B$BВо время правления Азшары здесь был один из главных эльфийских городов, в нем полно артефактов величайшего исторического значения. Все, о чем я прошу, – смотри в оба и обращай внимание на все необычные предметы в городе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Осмотрите 4 неразрушенные статуи в садах Вайш\'ира.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Благодарю за то, что серьезно отнеслась к моей просьбе.$B$BЭто, можно сказать, первое доказательство существования других членов семьи Вайш. Очень интересно. А о двух других личностях я даже и не слышала.$B$BВеликий Раскол уничтожил нашу историю, но теперь появился шанс восстановить хоть какие-то ее страницы.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Элендри Золотое Чело на базу Легиона.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25955,'Новая база','Эта пещера – наше единственное пристанище. Отступать некуда, и никто не спешит нам на помощь. Что бы ни случилось, нельзя подвергать это место опасности, иначе мы все погибнем.$B$BНеобходим форпост, с которого мы будем проводить атаки.$B$BПосле того как окажешься на нижнем уровне в восточной части руин, осмотри следующие объекты: северную часть садов, проход под главным зданием к западу от садов, а также группу зданий в юго-восточном углу руин, что находится под мостами.$B$BСобери всю доступную информацию об этих местах.','Спуститесь на нижний уровень руин и исследуйте северную часть садов Кель\'Дормир, туннель, проходящий под руинами на западе от садов, и постройки в юго-восточном углу руин, под мостами.','Вернитесь к капитану Злобешипу на базу Легиона.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новая база',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эта пещера – наше единственное пристанище. Отступать некуда, и никто не спешит нам на помощь. Что бы ни случилось, нельзя подвергать это место опасности, иначе мы все погибнем.$B$BНеобходим форпост, с которого мы будем проводить атаки.$B$BПосле того как окажешься на нижнем уровне в восточной части руин, осмотри следующие объекты: северную часть садов, проход под главным зданием к западу от садов, а также группу зданий в юго-восточном углу руин, что находится под мостами.$B$BСобери всю доступную информацию об этих местах.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Спуститесь на нижний уровень руин и исследуйте северную часть садов Кель\'Дормир, туннель, проходящий под руинами на западе от садов, и постройки в юго-восточном углу руин, под мостами.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Злобешипу на базу Легиона.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (25956,'На поле брани','Повсюду вокруг видны следы битвы. Скелеты наг не вызывают у меня никакого удивления, но вот оружие и останки их противников – довольно неожиданное открытие.$B$BСреди костей выделяется кусок металла, торчащий из черепа. Сложно сказать, частью какого оружия он был, но его можно забрать в виде доказательства.$B$BМеталлический фрагмент может заинтересовать кого-то из обитателей пещеры.','Принесите обломок на базу Легиона.','Металлический обломок?$B$BСудя по твоему описанию, те останки принадлежали морским врайкулам. Мы встречали их в Нордсколе. Мы никогда не станем заключать с ними союз, но эта информация обязательно пригодится.$B$BЯ подумаю об этом, если у меня будет время. Спасибо, что обратила на это внимание.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На поле брани',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Повсюду вокруг видны следы битвы. Скелеты наг не вызывают у меня никакого удивления, но вот оружие и останки их противников – довольно неожиданное открытие.$B$BСреди костей выделяется кусок металла, торчащий из черепа. Сложно сказать, частью какого оружия он был, но его можно забрать в виде доказательства.$B$BМеталлический фрагмент может заинтересовать кого-то из обитателей пещеры.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите обломок на базу Легиона.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Металлический обломок?$B$BСудя по твоему описанию, те останки принадлежали морским врайкулам. Мы встречали их в Нордсколе. Мы никогда не станем заключать с ними союз, но эта информация обязательно пригодится.$B$BЯ подумаю об этом, если у меня будет время. Спасибо, что обратила на это внимание.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25957,'Видения прошлого: вторжение в Вайш\'ир','Тот осколок, который ты $gпринес:принесла;, принадлежал нагам. Я давно ищу подобный предмет, чтобы закончить особое заклинание – оно позволит нам заглянуть в недалекое прошлое.$B$BИтак, заклинание готово, но теперь нужно отнести этот клинок на то место, где бывал его владелец. Отправляйся туда, где его $gнашел:нашла;.$B$BВозможно, теперь мы узнаем о намерениях наг – а может, даже нащупаем их слабые места.','Воспользуйтесь клинком воительницы Леди Наз\'жар на поле битвы возле юго-восточной окраины руин.','Обратитесь к говорящей с волнами Талре в Руинах Вайш\'ира.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Видения прошлого: вторжение в Вайш\'ир',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тот осколок, который ты $gпринес:принесла;, принадлежал нагам. Я давно ищу подобный предмет, чтобы закончить особое заклинание – оно позволит нам заглянуть в недалекое прошлое.$B$BИтак, заклинание готово, но теперь нужно отнести этот клинок на то место, где бывал его владелец. Отправляйся туда, где его $gнашел:нашла;.$B$BВозможно, теперь мы узнаем о намерениях наг – а может, даже нащупаем их слабые места.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь клинком воительницы Леди Наз\'жар на поле битвы возле юго-восточной окраины руин.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Обратитесь к говорящей с волнами Талре в Руинах Вайш\'ира.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (25957,'Воительница? Первый раз слышу.$B$BСудя по твоим рассказам, наг куда больше, чем думал капитан. Возможно, мы узнаем что-нибудь еще, если найдем другие места, где бывала эта Воительница. Но теперь я уже начинаю опасаться за капитана и его солдат. Нужно их предупредить.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Воительница? Первый раз слышу.$B$BСудя по твоим рассказам, наг куда больше, чем думал капитан. Возможно, мы узнаем что-нибудь еще, если найдем другие места, где бывала эта Воительница. Но теперь я уже начинаю опасаться за капитана и его солдат. Нужно их предупредить.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25958,'Взгляд в будущее','После твоего рассказа капитан решил создать форпост под террасой, что к западу отсюда. Теперь он планирует нанести оттуда удар по нагам.$B$BТы $gдолжен:должна; немедленно отправиться к нему и рассказать все, что $gвидел:видела;. Нас слишком мало, и страшно подумать, к чему приведет безрассудная атака.$B$BВозьми моего морского конька. Он знает дорогу.','Найдите капитана Злобешипа к северу от садов Кель\'Дормир и поговорите с ним.$B$BВоспользуйтесь морским коньком говорящей с волнами Талры, чтобы быстро добраться до форпоста.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Взгляд в будущее',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','После твоего рассказа капитан решил создать форпост под террасой, что к западу отсюда. Теперь он планирует нанести оттуда удар по нагам.$B$BТы $gдолжен:должна; немедленно отправиться к нему и рассказать все, что $gвидел:видела;. Нас слишком мало, и страшно подумать, к чему приведет безрассудная атака.$B$BВозьми моего морского конька. Он знает дорогу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите капитана Злобешипа к северу от садов Кель\'Дормир и поговорите с ним.$B$BВоспользуйтесь морским коньком говорящей с волнами Талры, чтобы быстро добраться до форпоста.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (25958,'Рад снова тебя видеть, $C. Я уже подумал, что мы потеряли тебя из-за глупого поручения Говорящей с волнами.$B$BКстати, чем оно закончилось?') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Рад снова тебя видеть, $C. Я уже подумал, что мы потеряли тебя из-за глупого поручения Говорящей с волнами.$B$BКстати, чем оно закончилось?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25959,'Ясные цели','Понятно. Да, это скверные новости, но я не исключал такую возможность. Было бы рискованно действовать, не зная точной численности наг, но именно поэтому мы и создали этот форпост.$B$BСкажу тебе прямо, |3-6($c), – если внезапно не напасть на наг, они сами к нам явятся. А у нас нет ни должных укреплений, ни достаточного количества солдат, так что это не вариант.$B$BНам нужно выиграть время. Можешь избавиться от нескольких наг под дальней южной террасой?','Убейте 10 наг, собирающихся на нижнем уровне под юго-западной террасой.','Вернитесь к капитану Злобешипу на север от садов Кель\'Дормир.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ясные цели',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Понятно. Да, это скверные новости, но я не исключал такую возможность. Было бы рискованно действовать, не зная точной численности наг, но именно поэтому мы и создали этот форпост.$B$BСкажу тебе прямо, |3-6($c), – если внезапно не напасть на наг, они сами к нам явятся. А у нас нет ни должных укреплений, ни достаточного количества солдат, так что это не вариант.$B$BНам нужно выиграть время. Можешь избавиться от нескольких наг под дальней южной террасой?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 наг, собирающихся на нижнем уровне под юго-западной террасой.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Злобешипу на север от садов Кель\'Дормир.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (25959,'Похоже, численность наг на юге еще выше, чем мы думали. Придется действовать быстро.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Похоже, численность наг на юге еще выше, чем мы думали. Придется действовать быстро.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25960,'Не так уж безоружны','Я невольно подслушал твой разговор с капитаном. Знаю – то, что мы делаем, похоже на безумие, но другого выхода нет. От нас зависит жизнь всех обитателей пещеры.$B$BЯ разместил вокруг нескольких часовых, но наг-разведчиков так много, что наши боеприпасы тают на глазах. Если ты пополнишь боезапас, часовые выиграют нам дополнительное время.','Принесите 8 связок арбалетных болтов дозорным Орды, расставленным на уступах на северном краю Садов Кель\'дормир.','Вернитесь к легионеру Назгриму на север от садов Кель\'Дормир.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Не так уж безоружны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я невольно подслушал твой разговор с капитаном. Знаю – то, что мы делаем, похоже на безумие, но другого выхода нет. От нас зависит жизнь всех обитателей пещеры.$B$BЯ разместил вокруг нескольких часовых, но наг-разведчиков так много, что наши боеприпасы тают на глазах. Если ты пополнишь боезапас, часовые выиграют нам дополнительное время.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 8 связок арбалетных болтов дозорным Орды, расставленным на уступах на северном краю Садов Кель\'дормир.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к легионеру Назгриму на север от садов Кель\'Дормир.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (25960,'Ты один из немногих, на кого можно положиться, $R! Если бы только у меня было больше таких бойцов!') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты один из немногих, на кого можно положиться, $R! Если бы только у меня было больше таких бойцов!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25961,'Необычное поручение','Хм, ты $gзаметил:заметила;, как неодобрительно капитан посмотрел на меня, и $gрешил:решила; помочь? Я уж и не надеюсь заставить его понять, что среди этих руин можно найти кое-что полезное.$B$BВот ты, как мне кажется, совсем другое дело. Посмотри-ка, подобные скрижали встречаются в окрестных развалинах, и я уже приготовила специальный набор для копирования надписей с этих каменных плит. Возьмешься за работу?','Скопируйте надписи с 4 скрижалей высокорожденных.','Вернитесь к Элендри Золотое Чело, находящейся к северу от садов Кель\'Дормир.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Необычное поручение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хм, ты $gзаметил:заметила;, как неодобрительно капитан посмотрел на меня, и $gрешил:решила; помочь? Я уж и не надеюсь заставить его понять, что среди этих руин можно найти кое-что полезное.$B$BВот ты, как мне кажется, совсем другое дело. Посмотри-ка, подобные скрижали встречаются в окрестных развалинах, и я уже приготовила специальный набор для копирования надписей с этих каменных плит. Возьмешься за работу?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Скопируйте надписи с 4 скрижалей высокорожденных.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Элендри Золотое Чело, находящейся к северу от садов Кель\'Дормир.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25962,'Внезапное озарение','Везде бывал, везде взрывал... Боялся, что этой привычке пришел конец – море, как понимаешь... Но оказалось, нужно лишь немного вдохновения.$B$BЯ нашел кое-что настолько нестабильное, что для бомбы в самый раз подойдет! На юго-западной террасе растут водоросли. В обычных водорослях содержится легкий газ, который позволяет тянуться вверх, а эти водоросли свисают вниз. Причина – тяжелый газ, как раз подходящий для моей бомбы.$B$BПринесешь немножко?','Соберите 8 раздувшихся шишек водорослей, висящих под юго-западной террасой.','Вернитесь к Облину Свистозубу на север от садов Кель\'Дормир.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Внезапное озарение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Везде бывал, везде взрывал... Боялся, что этой привычке пришел конец – море, как понимаешь... Но оказалось, нужно лишь немного вдохновения.$B$BЯ нашел кое-что настолько нестабильное, что для бомбы в самый раз подойдет! На юго-западной террасе растут водоросли. В обычных водорослях содержится легкий газ, который позволяет тянуться вверх, а эти водоросли свисают вниз. Причина – тяжелый газ, как раз подходящий для моей бомбы.$B$BПринесешь немножко?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 раздувшихся шишек водорослей, висящих под юго-западной террасой.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Облину Свистозубу на север от садов Кель\'Дормир.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (25962,'Ну, ты даешь! Я видел, как ты сражался с мурлоками, нагами и зубастыми рыбами, но это все ерунда по сравнению с тем, как бесстрашно ты подхватывал эти жуткие раздувшиеся шишки подмышку и тащил... БУМ! Ты же в любой момент мог взорваться.$B$BТакой $R мне по нраву, да.','Тик-так, тик-так! Время поджимает, взрывчатка ожидает... Ах, полжизни – за лабораторию!') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну, ты даешь! Я видел, как ты сражался с мурлоками, нагами и зубастыми рыбами, но это все ерунда по сравнению с тем, как бесстрашно ты подхватывал эти жуткие раздувшиеся шишки подмышку и тащил... БУМ! Ты же в любой момент мог взорваться.$B$BТакой $R мне по нраву, да.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тик-так, тик-так! Время поджимает, взрывчатка ожидает... Ах, полжизни – за лабораторию!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25963,'Медлить нельзя','Подготовка завершена, пора в бой.$B$BТы вот что – держись крепче на своем морском коньке, пока мы атакуем. Тот, кто останется один на один в воде с нагами, вряд ли сможет уплыть от них.$B$BУбей как можно больше врагов. Встретимся на верхней террасе, как только у нас закончится взрывчатка. Надеюсь, к тому времени наг останется мало, и мы добьем их сами.','Ты прекрасно проявил себя в деле, солдат! Ты перебил множество наг, но их оказалось больше, чем мы полагали. Большинство моих бойцов было вовлечено в затяжные бои с этим несметным полчищем.$B$BНужно удерживать данную позицию как можно дольше, чтобы выиграть время. Надеюсь, хоть кто-нибудь из наших прорвется к месту встречи.','Поговорите с капитаном Злобешипом на террасе Нар\'шолы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Медлить нельзя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Подготовка завершена, пора в бой.$B$BТы вот что – держись крепче на своем морском коньке, пока мы атакуем. Тот, кто останется один на один в воде с нагами, вряд ли сможет уплыть от них.$B$BУбей как можно больше врагов. Встретимся на верхней террасе, как только у нас закончится взрывчатка. Надеюсь, к тому времени наг останется мало, и мы добьем их сами.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты прекрасно проявил себя в деле, солдат! Ты перебил множество наг, но их оказалось больше, чем мы полагали. Большинство моих бойцов было вовлечено в затяжные бои с этим несметным полчищем.$B$BНужно удерживать данную позицию как можно дольше, чтобы выиграть время. Надеюсь, хоть кто-нибудь из наших прорвется к месту встречи.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с капитаном Злобешипом на террасе Нар\'шолы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25964,'Повержены, но не забыты','Какая катастрофа! Многие наши бойцы ранены и не могут добраться до места встречи.$B$BДолго нам эту позицию не удержать. Необходимо спасти как можно больше воинов, пока не явились наги. Отправляйся на юго-запад и сделай все, что в твоих силах.$B$BНаши долго не продержатся. Пожалуйста, поторопись!','Спасите 6 раненых добровольцев.','Спасибо тебе. Правда.$B$BНужно поторопить ребят. А мы с тобой скоро встретимся на форпосте, я уверен.','Вернитесь к легионеру Назгриму на террасу Нар\'шолы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Повержены, но не забыты',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Какая катастрофа! Многие наши бойцы ранены и не могут добраться до места встречи.$B$BДолго нам эту позицию не удержать. Необходимо спасти как можно больше воинов, пока не явились наги. Отправляйся на юго-запад и сделай все, что в твоих силах.$B$BНаши долго не продержатся. Пожалуйста, поторопись!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Спасите 6 раненых добровольцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо тебе. Правда.$B$BНужно поторопить ребят. А мы с тобой скоро встретимся на форпосте, я уверен.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к легионеру Назгриму на террасу Нар\'шолы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25965,'Подсчет','Злобные твари... а их гарпуны... страшная, скажу тебе, штука.$B$B<Капитан морщится, коснувшись раны в боку.>$B$BНо мы будем держаться. Сколько сможем. Любой ценой. Мне нужен тот, кто пойдет на разведку и подсчитает, сколько их там осталось. Чтобы понять, скольких мы уже перебили.$b$bОдна из самых больших групп находилась за углом в северо-западной части круглой террасы, а еще одна группа располагалась чуть подальше, в маленьком тоннеле на среднем уровне развалин.$b$bПойдешь, |3-6($c)?','Проведите разведку по краю круглой террасы на северо-западе и в туннеле под главной лестницей на севере. Оба места расположены на террасе Нар\'шолы на среднем уровне развалин.','Вернитесь к капитану Злобешипу на террасу Нар\'шолы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подсчет',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Злобные твари... а их гарпуны... страшная, скажу тебе, штука.$B$B<Капитан морщится, коснувшись раны в боку.>$B$BНо мы будем держаться. Сколько сможем. Любой ценой. Мне нужен тот, кто пойдет на разведку и подсчитает, сколько их там осталось. Чтобы понять, скольких мы уже перебили.$b$bОдна из самых больших групп находилась за углом в северо-западной части круглой террасы, а еще одна группа располагалась чуть подальше, в маленьком тоннеле на среднем уровне развалин.$b$bПойдешь, |3-6($c)?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проведите разведку по краю круглой террасы на северо-западе и в туннеле под главной лестницей на севере. Оба места расположены на террасе Нар\'шолы на среднем уровне развалин.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Злобешипу на террасу Нар\'шолы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (25965,'Так много?! По-прежнему?! Видать, у них тут какое-то важное дело, иначе с чего бы их такая тьма...$B$BСкажу откровенно, Бумагош, – потому что ты заслуживаешь правды, – долго нам не продержаться. Придется убираться отсюда, и уже очень скоро. Но если они нападут, атаки нам не выдержать. И бежать некуда... я не знаю, что делать...$B$BПрости, не стоило мне произносить это вслух. Сделай одолжение: не говори ничего моим воинам. Не хочу, чтобы они пали духом. Я постараюсь что-нибудь придумать.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так много?! По-прежнему?! Видать, у них тут какое-то важное дело, иначе с чего бы их такая тьма...$B$BСкажу откровенно, Бумагош, – потому что ты заслуживаешь правды, – долго нам не продержаться. Придется убираться отсюда, и уже очень скоро. Но если они нападут, атаки нам не выдержать. И бежать некуда... я не знаю, что делать...$B$BПрости, не стоило мне произносить это вслух. Сделай одолжение: не говори ничего моим воинам. Не хочу, чтобы они пали духом. Я постараюсь что-нибудь придумать.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25966,'Видения прошлого: битва на гряде Бейл\'аран','Понимаю, что прошу слишком многого и сейчас совсем не время для такой просьбы – ведь на счету каждый воин. Но мне нужна твоя помощь.$B$BЯ позабочусь о солдатах... а ты отправляйся на запад и разыщи поле боя с квалдирским генералом, о котором ты мне $gговорил:говорила;. Там ты узнаешь больше о деяниях Воительницы. Шестое чувство подсказывает мне, что ключ к победе над нагами скрывается в прошлом, и он как-то связан с Воительницей.$B$BИ, пожалуйста, поторопись: я постараюсь выиграть для тебя время, но силы мои не беспредельны.','Отправляйтесь на место гибели квалдирского генерала и с помощью сломанного клинка Воительницы призовите видение из прошлого, чтобы узнать продолжение истории о Воительнице.','Вернулся! Как вовремя! Еще немного – и мы бы их не удержали.$B$BАртефакт? Интересно, против наг он действует? Хотя сначала его хорошо бы найти... И мы обязательно этим займемся, но не сейчас.$B$BПока займемся решением безотлагательных вопросов. А как только представится возможность, сразу приступим к поискам.','Побеседуйте с говорящей с волнами Талрой на Террасе Нар\'шолы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Видения прошлого: битва на гряде Бейл\'аран',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Понимаю, что прошу слишком многого и сейчас совсем не время для такой просьбы – ведь на счету каждый воин. Но мне нужна твоя помощь.$B$BЯ позабочусь о солдатах... а ты отправляйся на запад и разыщи поле боя с квалдирским генералом, о котором ты мне $gговорил:говорила;. Там ты узнаешь больше о деяниях Воительницы. Шестое чувство подсказывает мне, что ключ к победе над нагами скрывается в прошлом, и он как-то связан с Воительницей.$B$BИ, пожалуйста, поторопись: я постараюсь выиграть для тебя время, но силы мои не беспредельны.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь на место гибели квалдирского генерала и с помощью сломанного клинка Воительницы призовите видение из прошлого, чтобы узнать продолжение истории о Воительнице.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вернулся! Как вовремя! Еще немного – и мы бы их не удержали.$B$BАртефакт? Интересно, против наг он действует? Хотя сначала его хорошо бы найти... И мы обязательно этим займемся, но не сейчас.$B$BПока займемся решением безотлагательных вопросов. А как только представится возможность, сразу приступим к поискам.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Побеседуйте с говорящей с волнами Талрой на Террасе Нар\'шолы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25967,'Отступление','Придется подождать с разговором: сейчас нужно уходить, пока наги не прорвались. Постарайся добраться до форпоста ярусом ниже.$B$BВозьми моего морского конька. Встретимся там.','Воспользуйтесь морским коньком говорящей с волнами Талры, чтобы вернуться к капитану Злобешипу, находящемуся к северу от Садов Кель\'Дормир.','Отступите к базе Легиона.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отступление',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Придется подождать с разговором: сейчас нужно уходить, пока наги не прорвались. Постарайся добраться до форпоста ярусом ниже.$B$BВозьми моего морского конька. Встретимся там.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь морским коньком говорящей с волнами Талры, чтобы вернуться к капитану Злобешипу, находящемуся к северу от Садов Кель\'Дормир.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отступите к базе Легиона.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (25967,'У тебя получилось! Мне казалось, что мы единственные уцелевшие после нападения на форпост. Рад видеть тебя в добром здравии, $C.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','У тебя получилось! Мне казалось, что мы единственные уцелевшие после нападения на форпост. Рад видеть тебя в добром здравии, $C.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (25968,'Отчаянный план','Толдрек с Облином отправились за помощью. Неподалеку проходят торговые маршруты, и шансы найти подмогу есть, но я бы не стал слишком на это надеяться.$B$BЕсли честно, особого выбора нет, и долго мы здесь не продержимся. Рано или поздно наги нас обнаружат и... ты ведь $gсам видел:сама видела;, сколько их там.$B$BОтправляйся на юго-восток к гряде Бейл\'аран и разыщи наших двоих храбрецов. Я постараюсь защитить оставшихся здесь.','Найдите Облина Свистозуба на гряде Бейл\'аран.','Ты гляди, очередной водоплавающий герой! Пришла беда – и ты тут как тут. Спаси всех, и сможешь собой гордиться!$B$BПонимаешь, у нас созрел великолепный план! Гениальный в своей простоте! Ну, если не учитывать враждебность окружающей среды... А теперь, когда с нами ты, все будет вообще проще пареной репы!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отчаянный план',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Толдрек с Облином отправились за помощью. Неподалеку проходят торговые маршруты, и шансы найти подмогу есть, но я бы не стал слишком на это надеяться.$B$BЕсли честно, особого выбора нет, и долго мы здесь не продержимся. Рано или поздно наги нас обнаружат и... ты ведь $gсам видел:сама видела;, сколько их там.$B$BОтправляйся на юго-восток к гряде Бейл\'аран и разыщи наших двоих храбрецов. Я постараюсь защитить оставшихся здесь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Облина Свистозуба на гряде Бейл\'аран.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты гляди, очередной водоплавающий герой! Пришла беда – и ты тут как тут. Спаси всех, и сможешь собой гордиться!$B$BПонимаешь, у нас созрел великолепный план! Гениальный в своей простоте! Ну, если не учитывать враждебность окружающей среды... А теперь, когда с нами ты, все будет вообще проще пареной репы!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25969,'Опасные воды','С одного из наших кораблей Облин утащил воздушный шар. Он попытался поднять шар на поверхность, но тут откуда ни возьмись появились слизнешкурые хапуги и разодрали шар в клочья.$B$BТеперь Облин хочет запустить второй шар, но история не должна повториться. Уничтожь-ка ты всех этих жаблинов... Или убей столько, чтобы они побоялись снова к нам сунуться.','Уничтожьте 10 слизнешкурых хапуг.','Чем меньше жаблинов, тем лучше.$B$BХорошо, что у них такое примитивное мышление. Сейчас я просто не готов к встрече с водоплавающими вундеркиндами.','Вернитесь к Облину Свистозубу на гряду Бейл\'аран.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Опасные воды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','С одного из наших кораблей Облин утащил воздушный шар. Он попытался поднять шар на поверхность, но тут откуда ни возьмись появились слизнешкурые хапуги и разодрали шар в клочья.$B$BТеперь Облин хочет запустить второй шар, но история не должна повториться. Уничтожь-ка ты всех этих жаблинов... Или убей столько, чтобы они побоялись снова к нам сунуться.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 10 слизнешкурых хапуг.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Чем меньше жаблинов, тем лучше.$B$BХорошо, что у них такое примитивное мышление. Сейчас я просто не готов к встрече с водоплавающими вундеркиндами.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Облину Свистозубу на гряду Бейл\'аран.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25970,'Наготове','До поверхности недалеко, а налегке и плыть проще простого. Но с припасами мы намучаемся – больно они тяжелые.$B$BНа каждом корабле Орды должен быть ящик с набором для выживания. У меня был воздушный шар из старого ящика, но недавно ему пришел быстрый и печальный конец, поэтому мне нужен еще один ящик.$B$BК юго-востоку отсюда ты найдешь корабль. Будем надеяться, что выжившие матросы совсем потеряли головы во время бегства и не догадались забрать с собой этот замечательный ящик. Их промашка может стать нашим спасением.','Разыщите ящик Орды с предметами первой необходимости.','Давай-ка посмотрим... сигнальное ружье... ага, вот шар... а веревки нет. Как же так, нет веревки?! Если хочешь знать мое мнение, это верх непрактичности. Веревка решительно необходима в любой ситуации!','Коробка с чудесами – вот что такое ящик с предметами первой необходимости! А мне в жизни так не хватает чудес!$B$BНе бойся, я с тобой поделюсь.','Вернитесь к Облину Свистозубу на гряду Бейл\'аран.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наготове',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','До поверхности недалеко, а налегке и плыть проще простого. Но с припасами мы намучаемся – больно они тяжелые.$B$BНа каждом корабле Орды должен быть ящик с набором для выживания. У меня был воздушный шар из старого ящика, но недавно ему пришел быстрый и печальный конец, поэтому мне нужен еще один ящик.$B$BК юго-востоку отсюда ты найдешь корабль. Будем надеяться, что выжившие матросы совсем потеряли головы во время бегства и не догадались забрать с собой этот замечательный ящик. Их промашка может стать нашим спасением.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите ящик Орды с предметами первой необходимости.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Давай-ка посмотрим... сигнальное ружье... ага, вот шар... а веревки нет. Как же так, нет веревки?! Если хочешь знать мое мнение, это верх непрактичности. Веревка решительно необходима в любой ситуации!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Коробка с чудесами – вот что такое ящик с предметами первой необходимости! А мне в жизни так не хватает чудес!$B$BНе бойся, я с тобой поделюсь.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Облину Свистозубу на гряду Бейл\'аран.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25971,'Веревочный план','В ящике с предметами первой необходимости нет веревки. Вопиющая халатность! Веревка и бомбы – вот что должно быть в этих наборах. Все остальное только место зря занимает.$B$BХотя шар – не такая уж и бесполезная штука. Сейчас, например, он нам очень даже пригодится.$B$BБьюсь об заклад, у квалдиров должна быть веревка. Они же чуть не живут на лодках, вяжут узлы да одеваются в сети. Иди-ка отбери у них веревку! Без этого наш план яйца выеденного не стоит.','Добудьте 8 мотков квалдирской веревки.','Превосходно! То, что нужно. Она должна выдержать... Футы-нуты! Она что, из волос сплетена?!$B$BЛадно, какая разница. Теперь почти все готово. Как говорится, сколь веревочке ни виться...','Эта веревка надежно скрепит наш план!','Вернитесь к Облину Свистозубу на гряду Бейл\'аран.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Веревочный план',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В ящике с предметами первой необходимости нет веревки. Вопиющая халатность! Веревка и бомбы – вот что должно быть в этих наборах. Все остальное только место зря занимает.$B$BХотя шар – не такая уж и бесполезная штука. Сейчас, например, он нам очень даже пригодится.$B$BБьюсь об заклад, у квалдиров должна быть веревка. Они же чуть не живут на лодках, вяжут узлы да одеваются в сети. Иди-ка отбери у них веревку! Без этого наш план яйца выеденного не стоит.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 8 мотков квалдирской веревки.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Превосходно! То, что нужно. Она должна выдержать... Футы-нуты! Она что, из волос сплетена?!$B$BЛадно, какая разница. Теперь почти все готово. Как говорится, сколь веревочке ни виться...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Эта веревка надежно скрепит наш план!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Облину Свистозубу на гряду Бейл\'аран.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25972,'Честь и слава','Вот и все. Я уверен, что все получится. И шар на этот раз никто не проткнул – за что спасибо тебе! Как ты $gрасправился:расправилась; с этими слизнешкурыми хапугами – только клочья летели!$B$BТолдрек уже поплыл ловить его, правда, очень тревожился насчет течений, ну и вообще... Сказал, пусть вся слава достанется тебе. Хороший парень... трудно ему, но держится молодцом.$B$BПоднимись к шару, возьми сигнальное ружье и посмотри, нет ли поблизости кораблей Орды. Если увидишь какой-нибудь, стреляй сигнальной ракетой. Собственно, и все.$B$BПлывешь. Поднимаешься на поверхность. Запускаешь ракету. И помощь приходит! Последний пункт мне нравится больше всего.','Поднимитесь на поверхность, возьмите сигнальное ружье и запустите сигнальную ракету в направлении кораблей Орды.','Поговорите с кровостражем Толдреком в море над грядой Бейл\'аран.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Честь и слава',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот и все. Я уверен, что все получится. И шар на этот раз никто не проткнул – за что спасибо тебе! Как ты $gрасправился:расправилась; с этими слизнешкурыми хапугами – только клочья летели!$B$BТолдрек уже поплыл ловить его, правда, очень тревожился насчет течений, ну и вообще... Сказал, пусть вся слава достанется тебе. Хороший парень... трудно ему, но держится молодцом.$B$BПоднимись к шару, возьми сигнальное ружье и посмотри, нет ли поблизости кораблей Орды. Если увидишь какой-нибудь, стреляй сигнальной ракетой. Собственно, и все.$B$BПлывешь. Поднимаешься на поверхность. Запускаешь ракету. И помощь приходит! Последний пункт мне нравится больше всего.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поднимитесь на поверхность, возьмите сигнальное ружье и запустите сигнальную ракету в направлении кораблей Орды.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с кровостражем Толдреком в море над грядой Бейл\'аран.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (25972,'Отлично! Они ее точно заметили. Не могли не заметить.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! Они ее точно заметили. Не могли не заметить.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25973,'Добрые вести','Они, наверное, вышлют лодку. Но на это надо время. Я останусь здесь и вступлю в переговоры.$B$BА ты немедленно возвращайся в пещеру и скажи там, что помощь уже на подходе. Будем надеяться, наги их не обнаружили.$B$BДавай, $n. Плыви. И постарайся обернуться побыстрее.','Возвращайтесь к легионеру Назгриму на базу Легиона.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Добрые вести',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Они, наверное, вышлют лодку. Но на это надо время. Я останусь здесь и вступлю в переговоры.$B$BА ты немедленно возвращайся в пещеру и скажи там, что помощь уже на подходе. Будем надеяться, наги их не обнаружили.$B$BДавай, $n. Плыви. И постарайся обернуться побыстрее.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возвращайтесь к легионеру Назгриму на базу Легиона.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (25973,'Это действительно добрые вести. Мы постараемся как можно скорее поднять выживших на поверхность. Может быть, через некоторое время этот кошмар забудется, будто его и не было.$B$BСпасибо, Бумагош. Ты всех нас спас. Теперь в Орде тебя всегда ждет уважение и почет.$B$BНадеюсь, мы еще встретимся на корабле. Когда ты насовсем распрощаешься с нагами.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это действительно добрые вести. Мы постараемся как можно скорее поднять выживших на поверхность. Может быть, через некоторое время этот кошмар забудется, будто его и не было.$B$BСпасибо, Бумагош. Ты всех нас спас. Теперь в Орде тебя всегда ждет уважение и почет.$B$BНадеюсь, мы еще встретимся на корабле. Когда ты насовсем распрощаешься с нагами.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25974,'Истребление Сира\'кесс','Так ты и есть $gэтот:эта; $n, о $gкотором:которой; тут все говорят? Ну вот, наконец-то мы с тобой познакомились.$B$BЛадно, давай сразу к делу. Значит, задача такая: отправляйся на северо-запад к берегу Сира\'кесс и перебей змеюк.$B$BОни давно нарываются на неприятности, и мы им это устроим. Ну... вернее, ты устроишь.','Убейте 10 наг Сира\'кесс.','Вернитесь к сержанту Гертруде в Зловещий грот в Вайш\'ире.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Истребление Сира\'кесс',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Так ты и есть $gэтот:эта; $n, о $gкотором:которой; тут все говорят? Ну вот, наконец-то мы с тобой познакомились.$B$BЛадно, давай сразу к делу. Значит, задача такая: отправляйся на северо-запад к берегу Сира\'кесс и перебей змеюк.$B$BОни давно нарываются на неприятности, и мы им это устроим. Ну... вернее, ты устроишь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 наг Сира\'кесс.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к сержанту Гертруде в Зловещий грот в Вайш\'ире.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (25974,'Отлично, Бумагош! Теперь наги подожмут хвосты.$B$BЗа такое не грех и выпить. Тебе вина или рому?') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, Бумагош! Теперь наги подожмут хвосты.$B$BЗа такое не грех и выпить. Тебе вина или рому?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25975,'Экспроприация сокровищ','Подкрепление прибыло, но нам нужно чем-то платить солдатам. Опытные воины нынче недешевы.$B$BПравда, есть одна идея! Эти мерзавцы-жаблины на Гряде Глубинных Плавников, что на северо-западе отсюда, награбили кучу сокровищ. По-моему, самое время туда наведаться и слегка их "потрясти".','Соберите 6 предметов добычи Глубинных Плавников.','Думаю, на первое время этого хватит. А если понадобится еще, мы знаем, где взять.','Вернитесь к Джорлану Верному Клинку в Темную пещеру в Вайш\'ире.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Экспроприация сокровищ',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Подкрепление прибыло, но нам нужно чем-то платить солдатам. Опытные воины нынче недешевы.$B$BПравда, есть одна идея! Эти мерзавцы-жаблины на Гряде Глубинных Плавников, что на северо-западе отсюда, награбили кучу сокровищ. По-моему, самое время туда наведаться и слегка их "потрясти".',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 6 предметов добычи Глубинных Плавников.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Думаю, на первое время этого хватит. А если понадобится еще, мы знаем, где взять.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джорлану Верному Клинку в Темную пещеру в Вайш\'ире.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25976,'Экспроприация сокровищ','Кровь и гром! Подкрепление прибыло, но нам нужно чем-то платить солдатам. А это недешево.$B$BНо у меня есть идея! Мерзавцы-жаблины на Гряде Глубинных Плавников, что на северо-западе отсюда, награбили кучу сокровищ. По-моему, самое время наведаться к ним и слегка "потрясти" в пользу Орды.$B$BАдский Крик следит за тобой, $n!','Соберите 6 предметов добычи Глубинных Плавников.','Вернитесь к кровостражу Толдреку в Зловещий грот в Вайш\'ире.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Экспроприация сокровищ',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кровь и гром! Подкрепление прибыло, но нам нужно чем-то платить солдатам. А это недешево.$B$BНо у меня есть идея! Мерзавцы-жаблины на Гряде Глубинных Плавников, что на северо-западе отсюда, награбили кучу сокровищ. По-моему, самое время наведаться к ним и слегка "потрясти" в пользу Орды.$B$BАдский Крик следит за тобой, $n!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 6 предметов добычи Глубинных Плавников.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к кровостражу Толдреку в Зловещий грот в Вайш\'ире.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (25976,'Думаю, этого хватит. А если понадобится еще, мы знаем, где взять.','Сколько добычи удалось собрать, Бумагош?') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Думаю, этого хватит. А если понадобится еще, мы знаем, где взять.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Сколько добычи удалось собрать, Бумагош?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (25977,'Знаменательный день для Азражара','$n, змеюки снова на нас поперли. Так что давай дуй обратно на северо-запад, к Гряде Глубинных Плавников, и наведи там шороху. Грохни их главного и воткни в его труп наше знамя.$B$BПусть они там от страха обделаются и уберутся куда подальше, поджав хвосты... или щупальца... или что там у них...','Воткните знамя Альянса в труп призывателя глубин Азражара.','Был призыватель, да весь вышел... хе-хе...$B$B<Лейтенант качает головой и ухмыляется.>','Вернитесь к лейтенанту Топперу по прозвищу "Лисяра" в Темную пещеру в Вайш\'ире.','Воткни знамя в его труп!','Призыватель глубин Азражар') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Знаменательный день для Азражара',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, змеюки снова на нас поперли. Так что давай дуй обратно на северо-запад, к Гряде Глубинных Плавников, и наведи там шороху. Грохни их главного и воткни в его труп наше знамя.$B$BПусть они там от страха обделаются и уберутся куда подальше, поджав хвосты... или щупальца... или что там у них...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воткните знамя Альянса в труп призывателя глубин Азражара.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Был призыватель, да весь вышел... хе-хе...$B$B<Лейтенант качает головой и ухмыляется.>',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лейтенанту Топперу по прозвищу "Лисяра" в Темную пещеру в Вайш\'ире.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Воткни знамя в его труп!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Призыватель глубин Азражар',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25978,'Погребенные во льду','Кургорн говорит, что катаклизм нарушил баланс стихий по всему миру. Озеро Хельмово Ложе, которое находится к югу отсюда, всегда было красивым и тихим, но теперь оно захвачено потревоженными водными элементалями. Когда они начали выходить за пределы озера, я отправил туда свои войска, но многие не вернулись, оставшись замороженными в глыбах льда.$b$bЕсли мы сможем освободить их оттуда, у них неплохие шансы выжить. Но у меня не хватает людей для организации второй вылазки к озеру. Не хочешь помочь?','Вскройте 6 ледяных гробниц, чтобы освободить замерзших горных пехотинцев, находящихся в плену озера Хельмово Ложе.','Вернитесь к сержанту Бахруму в Лагерь Бахрума.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Погребенные во льду',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кургорн говорит, что катаклизм нарушил баланс стихий по всему миру. Озеро Хельмово Ложе, которое находится к югу отсюда, всегда было красивым и тихим, но теперь оно захвачено потревоженными водными элементалями. Когда они начали выходить за пределы озера, я отправил туда свои войска, но многие не вернулись, оставшись замороженными в глыбах льда.$b$bЕсли мы сможем освободить их оттуда, у них неплохие шансы выжить. Но у меня не хватает людей для организации второй вылазки к озеру. Не хочешь помочь?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вскройте 6 ледяных гробниц, чтобы освободить замерзших горных пехотинцев, находящихся в плену озера Хельмово Ложе.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к сержанту Бахруму в Лагерь Бахрума.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25979,'Утихомирить волны','Стихии в смятении, |3-6($c). Катаклизм потревожил давно дремлющих духов воды озера Хельмово Ложе, что к югу отсюда. Они злы, растеряны и совершенно не желают внимать моим просьбам.$b$bЯ испробовал все, что знал, чтобы успокоить их и убедить перестать набрасываться на горных пехотинцев сержанта.$b$bМне больно говорить это, но другого выхода нет – мы должны убить элементалей.','Убейте 6 озерных волногонов в озере Хельмово Ложе.','Всегда непросто принимать жестокие решения относительно стихий, силами которых пользуешься. Но иногда просто нет другого выхода. Наш долг по отношению к жителям Дун Морога превыше всего.','Вернитесь к Кургорну Опаленному Перу в Лагерь Бахрума.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Утихомирить волны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Стихии в смятении, |3-6($c). Катаклизм потревожил давно дремлющих духов воды озера Хельмово Ложе, что к югу отсюда. Они злы, растеряны и совершенно не желают внимать моим просьбам.$b$bЯ испробовал все, что знал, чтобы успокоить их и убедить перестать набрасываться на горных пехотинцев сержанта.$b$bМне больно говорить это, но другого выхода нет – мы должны убить элементалей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 6 озерных волногонов в озере Хельмово Ложе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Всегда непросто принимать жестокие решения относительно стихий, силами которых пользуешься. Но иногда просто нет другого выхода. Наш долг по отношению к жителям Дун Морога превыше всего.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кургорну Опаленному Перу в Лагерь Бахрума.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (25980,'Знаменательный день для Азражара','$n, наги снова готовятся к атаке. Возвращайся на северо-запад к Гряде Глубинных Плавников, убей их генерала, призывателя глубин Азражара, и воткни в его труп наше знамя.$B$BЭто устрашит наг, и они уберутся восвояси, поджав хвосты.','Воткните знамя Орды в труп призывателя глубин Азражара.','Вернитесь к сержанту Гертруде в Зловещий грот в Вайш\'ире.','Воткни знамя в его труп!','Призыватель глубин Азражар') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Знаменательный день для Азражара',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, наги снова готовятся к атаке. Возвращайся на северо-запад к Гряде Глубинных Плавников, убей их генерала, призывателя глубин Азражара, и воткни в его труп наше знамя.$B$BЭто устрашит наг, и они уберутся восвояси, поджав хвосты.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воткните знамя Орды в труп призывателя глубин Азражара.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к сержанту Гертруде в Зловещий грот в Вайш\'ире.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Воткни знамя в его труп!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Призыватель глубин Азражар',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (25980,'Проткнул насквозь, говоришь? Жалко, я этого не видела!') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Проткнул насквозь, говоришь? Жалко, я этого не видела!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25981,'Это не маски','$n, эти кальмарообразные демоны... они присасываются к головам жаблинов и превращают их в послушных рабов!$B$BЯ вот думаю... может быть, сплаваешь на северо-запад к Гряде Глубинных Плавников или на берег Сира\'кесс и принесешь мне штук шесть голов этих противных тварей – безжалостных?','Добудьте 6 голов безжалостных.','М-да... уродливые тварюги. Но с виду вроде бы безобидные. Хоть и вонючие.$B$BТак, давай-ка я очищу их от жаблинских остатков. Есть одна идея...','Сколько ты их собрал?','Вернитесь к инженеру Мегагексу в Темную пещеру в Вайш\'ире.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Это не маски',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, эти кальмарообразные демоны... они присасываются к головам жаблинов и превращают их в послушных рабов!$B$BЯ вот думаю... может быть, сплаваешь на северо-запад к Гряде Глубинных Плавников или на берег Сира\'кесс и принесешь мне штук шесть голов этих противных тварей – безжалостных?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 6 голов безжалостных.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','М-да... уродливые тварюги. Но с виду вроде бы безобидные. Хоть и вонючие.$B$BТак, давай-ка я очищу их от жаблинских остатков. Есть одна идея...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Сколько ты их собрал?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к инженеру Мегагексу в Темную пещеру в Вайш\'ире.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25982,'Это не маски','$n, эти кальмарообразные демоны... они присасываются к головам жаблинов и превращают их в послушных рабов! Совсем не хочется, чтобы эти твари добрались сюда!$B$BЯ вот думаю... может быть, сплаваешь на северо-запад к Гряде Глубинных Плавников или на берег Сира\'кесс и принесешь мне штук шесть голов этих безжалостных тварей? Желательно – мертвых.','Добудьте 6 голов безжалостных.','Вернитесь к Облину Свистозубу в Зловещий грот в Вайш\'ире.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Это не маски',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, эти кальмарообразные демоны... они присасываются к головам жаблинов и превращают их в послушных рабов! Совсем не хочется, чтобы эти твари добрались сюда!$B$BЯ вот думаю... может быть, сплаваешь на северо-запад к Гряде Глубинных Плавников или на берег Сира\'кесс и принесешь мне штук шесть голов этих безжалостных тварей? Желательно – мертвых.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 6 голов безжалостных.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Облину Свистозубу в Зловещий грот в Вайш\'ире.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (25982,'М-да... уродливые тварюги. Но с виду вроде бы безобидные. Вроде бы... В каком-то смысле они даже милые. Ну, по-своему...$B$BТак, давай-ка я очищу их от жаблинских остатков. Есть одна идея...','Чем так воняет?') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','М-да... уродливые тварюги. Но с виду вроде бы безобидные. Вроде бы... В каком-то смысле они даже милые. Ну, по-своему...$B$BТак, давай-ка я очищу их от жаблинских остатков. Есть одна идея...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Чем так воняет?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (25983,'Подводный выступ','Необходимо немедленно передать эти сведения капитану Тейлору! Он сейчас на северо-западе, на Подводном выступе, вместе с Эрунаком Говорящим с Камнем и Служителями Земли.','Поговорите с капитаном Тейлором на Подводном выступе в Вайш\'ире.','М-да, тревожные новости. Но я уверен, наши друзья из Служителей Земли знают, что делать.$B$BКстати, раз уж ты здесь...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подводный выступ',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Необходимо немедленно передать эти сведения капитану Тейлору! Он сейчас на северо-западе, на Подводном выступе, вместе с Эрунаком Говорящим с Камнем и Служителями Земли.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с капитаном Тейлором на Подводном выступе в Вайш\'ире.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','М-да, тревожные новости. Но я уверен, наши друзья из Служителей Земли знают, что делать.$B$BКстати, раз уж ты здесь...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25984,'Подводный выступ','$n, нужно немедленно передать эти сведения легионеру Назгриму. Он сейчас на северо-западе, на Подводном выступе, вместе с Эрунаком Говорящим с Камнем и Служителями Земли. Отправляйся немедленно.','Поговорите с легионером Назгримом на Подводном выступе в Вайш\'ире.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подводный выступ',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, нужно немедленно передать эти сведения легионеру Назгриму. Он сейчас на северо-западе, на Подводном выступе, вместе с Эрунаком Говорящим с Камнем и Служителями Земли. Отправляйся немедленно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с легионером Назгримом на Подводном выступе в Вайш\'ире.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (25984,'От этого гоблина одни неприятности. Ни за что не поверил бы его словам, если бы их передал кто-то другой, а не ты. Вести и вправду тревожные, но я уверен – наши друзья из Служителей Земли знают, что делать.$B$BКстати, раз уж ты здесь...') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','От этого гоблина одни неприятности. Ни за что не поверил бы его словам, если бы их передал кто-то другой, а не ты. Вести и вправду тревожные, но я уверен – наши друзья из Служителей Земли знают, что делать.$B$BКстати, раз уж ты здесь...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (25985,'Крылья над Хиджалом','$n, правда ли, что ты собираешься воззвать к Древним?$B$BК юго-западу отсюда находится святилище Авианы, покровительницы всех пернатых созданий. В святилище обитает моя любимая наставница Чолуна. Никогда не встречала кого-либо, кто так сильно соприкасается с духами, населяющими этот мир. Ты бы $gмог:могла; многому у нее научиться!$B$BНедавние нападения отсекли пути в святилище. Однако туда можно легко попасть по воздуху: поищи второе по высоте дерево на горе Хиджал. Доброго пути!','Найдите Чолуну в святилище Авианы на горе Хиджал.','О, тебя прислала Тиала? Чудесная ученица, которая многого добьется.$B$BХотя в тебе я чувствую еще большую силу.$B$BПрошу тебя, погости немного в нашем святилище. Предстоит так много свершений, и лучше все делать на свежую голову.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Крылья над Хиджалом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, правда ли, что ты собираешься воззвать к Древним?$B$BК юго-западу отсюда находится святилище Авианы, покровительницы всех пернатых созданий. В святилище обитает моя любимая наставница Чолуна. Никогда не встречала кого-либо, кто так сильно соприкасается с духами, населяющими этот мир. Ты бы $gмог:могла; многому у нее научиться!$B$BНедавние нападения отсекли пути в святилище. Однако туда можно легко попасть по воздуху: поищи второе по высоте дерево на горе Хиджал. Доброго пути!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Чолуну в святилище Авианы на горе Хиджал.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, тебя прислала Тиала? Чудесная ученица, которая многого добьется.$B$BХотя в тебе я чувствую еще большую силу.$B$BПрошу тебя, погости немного в нашем святилище. Предстоит так много свершений, и лучше все делать на свежую голову.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (25986,'Проблема на озере','Ты $gоказал:оказала; нам большую помощь в обеспечении безопасности рудника и в спасении остававшихся там рабочих. Сенат будет очень рад узнать, что тебе и горным пехотинцам капитана Таррана удалось сделать Дун Морог безопаснее.$b$bНо меня беспокоит отсутствие вестей от сержанта Бахрума и его подразделения. Они отправились на восток, по дороге к озеру Хельмово Ложе, у них был приказ разбить там небольшой лагерь. Не отправишься ли ты туда и не проверишь ли, как дела у сержанта?','Поговорите с сержантом Бахрумом в Лагере Бахрума.','Хорошо, что сенатор не выступил сюда один. Здесь опасно, и нам понадобится любая помощь, чтобы держать ситуацию под контролем.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Проблема на озере',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gоказал:оказала; нам большую помощь в обеспечении безопасности рудника и в спасении остававшихся там рабочих. Сенат будет очень рад узнать, что тебе и горным пехотинцам капитана Таррана удалось сделать Дун Морог безопаснее.$b$bНо меня беспокоит отсутствие вестей от сержанта Бахрума и его подразделения. Они отправились на восток, по дороге к озеру Хельмово Ложе, у них был приказ разбить там небольшой лагерь. Не отправишься ли ты туда и не проверишь ли, как дела у сержанта?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с сержантом Бахрумом в Лагере Бахрума.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо, что сенатор не выступил сюда один. Здесь опасно, и нам понадобится любая помощь, чтобы держать ситуацию под контролем.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (25987,'Прекрасная маскировка','Слушай, $n, у меня идея, как замаскироваться! Отлично выйдет. Берешь безжалостную тварь и надеваешь себе на голову.$B$BА что такого? Она же тебя не укусит!$B$BПопробуем?','Посмотрите, что будет, если надеть на голову мертвого Безжалостного.','Что случилось? Эта тварь была живая! Нет, я все-таки предпочитаю работать с механическими устройствами...$B$BГоворишь, у тебя было видение? Он показал тебе, как нас всех убивают?! Как-то это не радует.$B$BНу, в любом случае, тот парень из Служителей Земли, Эрунак Говорящий с Камнем, хотел забрать себе всех безмозглых тварей, какие только есть. И уж я позабочусь о том, чтобы он их получил. Поскорее бы от этой дряни избавиться, чтобы и духу ее здесь не было.','Безжалостный надет','Поговорите с инженером Мегагексом в Темной пещере в Вайш\'ире.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прекрасная маскировка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слушай, $n, у меня идея, как замаскироваться! Отлично выйдет. Берешь безжалостную тварь и надеваешь себе на голову.$B$BА что такого? Она же тебя не укусит!$B$BПопробуем?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Посмотрите, что будет, если надеть на голову мертвого Безжалостного.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что случилось? Эта тварь была живая! Нет, я все-таки предпочитаю работать с механическими устройствами...$B$BГоворишь, у тебя было видение? Он показал тебе, как нас всех убивают?! Как-то это не радует.$B$BНу, в любом случае, тот парень из Служителей Земли, Эрунак Говорящий с Камнем, хотел забрать себе всех безмозглых тварей, какие только есть. И уж я позабочусь о том, чтобы он их получил. Поскорее бы от этой дряни избавиться, чтобы и духу ее здесь не было.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Безжалостный надет',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с инженером Мегагексом в Темной пещере в Вайш\'ире.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (25988,'Прекрасная маскировка','У меня идея, как замаскироваться. Отлично выйдет, $n! Берешь труп безжалостной твари и надеваешь себе на голову.$B$BДа, я все понимаю... но она же дохлая, так что тебе ничего не будет. Ну, разве что пару дней повоняешь тухлятиной, но для пользы же дела!$B$BПопробуем?','Посмотрите, что будет, если надеть на голову мертвого Безжалостного.','Безжалостный надет','Поговорите с Облином Свистозубом в Зловещем гроте, что в Вайш\'ире.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прекрасная маскировка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У меня идея, как замаскироваться. Отлично выйдет, $n! Берешь труп безжалостной твари и надеваешь себе на голову.$B$BДа, я все понимаю... но она же дохлая, так что тебе ничего не будет. Ну, разве что пару дней повоняешь тухлятиной, но для пользы же дела!$B$BПопробуем?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Посмотрите, что будет, если надеть на голову мертвого Безжалостного.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Безжалостный надет',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Облином Свистозубом в Зловещем гроте, что в Вайш\'ире.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (25988,'Как же я так оплошал... Должен был догадаться, что эта тварь еще не умерла, когда она начала извиваться. Но я решил, что мне показалось.$B$BГоворишь, у тебя было видение? Он показал тебе, как нас всех убивают?! Как-то это не радует.$B$BНу ладно. Тот парень из Служителей Земли, Эрунак Говорящий с Камнем, хотел забрать себе всех безмозглых тварей, какие только есть. И уж я позабочусь о том, чтобы он их получил. Здесь они мне не нужны. И так уже все провоняло.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Как же я так оплошал... Должен был догадаться, что эта тварь еще не умерла, когда она начала извиваться. Но я решил, что мне показалось.$B$BГоворишь, у тебя было видение? Он показал тебе, как нас всех убивают?! Как-то это не радует.$B$BНу ладно. Тот парень из Служителей Земли, Эрунак Говорящий с Камнем, хотел забрать себе всех безмозглых тварей, какие только есть. И уж я позабочусь о том, чтобы он их получил. Здесь они мне не нужны. И так уже все провоняло.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25989,'Захват краба','Всем своим существом я ощущаю, что Неспира хочет связаться со мной, но я ее не слышу. Видимо, наги как-то препятствуют этому.$B$B<Дуарн какое-то время молча размышляет.>$B$BПохоже, что-то не дает ей говорить... Необходимо найти то, что послужит ей голосом...$B$BПридумал! Известно, что Идра\'кесс приручают глубинных крабов и выращивают из них помощников в бою. Поймай этой сетью одного краба и принеси мне. Они обитают у внешних границ полости.','Поймайте сетью Дуарна глубинного краба в Неспире.','<Дуарн смотрит на краба и еле сдерживает недовольство.>$B$BВыглядит не очень внушительно, да?','Надеюсь, сработает. Мои способности ограничены, и я боюсь, что мы можем не справиться...','Вернитесь к Целителю Земли Дуарну в Неспиру в Вайш\'ире.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Захват краба',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Всем своим существом я ощущаю, что Неспира хочет связаться со мной, но я ее не слышу. Видимо, наги как-то препятствуют этому.$B$B<Дуарн какое-то время молча размышляет.>$B$BПохоже, что-то не дает ей говорить... Необходимо найти то, что послужит ей голосом...$B$BПридумал! Известно, что Идра\'кесс приручают глубинных крабов и выращивают из них помощников в бою. Поймай этой сетью одного краба и принеси мне. Они обитают у внешних границ полости.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поймайте сетью Дуарна глубинного краба в Неспире.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Дуарн смотрит на краба и еле сдерживает недовольство.>$B$BВыглядит не очень внушительно, да?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Надеюсь, сработает. Мои способности ограничены, и я боюсь, что мы можем не справиться...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Целителю Земли Дуарну в Неспиру в Вайш\'ире.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (25990,'Прорыв','Хорошо известно, что опытный шаман умеет взаимодействовать со всеми четырьмя элементами стихий: землей, огнем, водой и воздухом.$B$BОднако далеко не все знают, что существует и пятый элемент. Он не имеет такого же четкого определения, как остальные... О нем можно сказать только то, что он является связующим звеном между всем живым на планете.$B$BЯ пришел к выводу о том, что краб, как морской обитатель, находится ближе всего к Неспире, поэтому с помощью всех элементов можно убедить его взять на себя роль голоса Неспиры.','Проследите за тем, как Целитель Земли Дуарн попытается заговорить с Неспирой.','Я полагал, что наги пришли только за жемчугом, но, похоже, у них есть более серьезная цель. Подчинив себе Неспиру, они смогут действовать здесь абсолютно безнаказанно, и последствия будут катастрофическими!$B$BИх нужно остановить.','Поговорите с Целителем Земли Дуарном','Вернитесь к Целителю Земли Дуарну в Неспиру в Вайш\'ире.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прорыв',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хорошо известно, что опытный шаман умеет взаимодействовать со всеми четырьмя элементами стихий: землей, огнем, водой и воздухом.$B$BОднако далеко не все знают, что существует и пятый элемент. Он не имеет такого же четкого определения, как остальные... О нем можно сказать только то, что он является связующим звеном между всем живым на планете.$B$BЯ пришел к выводу о том, что краб, как морской обитатель, находится ближе всего к Неспире, поэтому с помощью всех элементов можно убедить его взять на себя роль голоса Неспиры.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проследите за тем, как Целитель Земли Дуарн попытается заговорить с Неспирой.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я полагал, что наги пришли только за жемчугом, но, похоже, у них есть более серьезная цель. Подчинив себе Неспиру, они смогут действовать здесь абсолютно безнаказанно, и последствия будут катастрофическими!$B$BИх нужно остановить.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Поговорите с Целителем Земли Дуарном',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Целителю Земли Дуарну в Неспиру в Вайш\'ире.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`) VALUES (25991,'<Дуарн закрывает глаза, делает паузу и затем кивает головой.>$b$bНеспира только что-то сообщила мне, что мы не единственные, кто сражается в раковине. На другой ее стороне от наг отбивается группа беглых рабов Орды; они находятся на уступе, нависающем над сердцем Неспиры.$b$bНайди их, $n, и узнай, какую помощь они в силах нам оказать. Возможно, объединившись с рабами, мы сможем пробудить Неспиру ото сна.$b$bЯ останусь тут на случай, если что-нибудь потребуется.','Отыщите выживших представителей Орды в Неспире, что находится в Вайш\'ире.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Дуарн закрывает глаза, делает паузу и затем кивает головой.>$b$bНеспира только что-то сообщила мне, что мы не единственные, кто сражается в раковине. На другой ее стороне от наг отбивается группа беглых рабов Орды; они находятся на уступе, нависающем над сердцем Неспиры.$b$bНайди их, $n, и узнай, какую помощь они в силах нам оказать. Возможно, объединившись с рабами, мы сможем пробудить Неспиру ото сна.$b$bЯ останусь тут на случай, если что-нибудь потребуется.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщите выживших представителей Орды в Неспире, что находится в Вайш\'ире.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (25991,'Гнобс... Это ты?') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Гнобс... Это ты?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25992,'Безоружные','Честно говоря, я не понимаю, почему мы до сих пор живы. Наги захватили все мое оружие и доспехи. У меня остались только какие-то лохмотья и шахтерская кирка, которая к тому же давным-давно пополам сломалась.$B$BМне нужно хоть какое-то оружие... Да, и моим товарищам тоже, хоть гордость и не позволяет им это признать.$B$BЯ видел стойки с оружием на ближайших складах наг. Мне еще никогда не доводилось сражаться трезубцем, но в любом случае лучше идти в бой с ним, чем с голыми руками.','Принесите 4 похищенных трезубца с оружейных стоек в Неспире.','Вернитесь к капитану Злобешипу в Неспиру, что в Вайш\'ире.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Безоружные',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Честно говоря, я не понимаю, почему мы до сих пор живы. Наги захватили все мое оружие и доспехи. У меня остались только какие-то лохмотья и шахтерская кирка, которая к тому же давным-давно пополам сломалась.$B$BМне нужно хоть какое-то оружие... Да, и моим товарищам тоже, хоть гордость и не позволяет им это признать.$B$BЯ видел стойки с оружием на ближайших складах наг. Мне еще никогда не доводилось сражаться трезубцем, но в любом случае лучше идти в бой с ним, чем с голыми руками.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 4 похищенных трезубца с оружейных стоек в Неспире.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Злобешипу в Неспиру, что в Вайш\'ире.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (25992,'<Капитан Злобешип любуется трезубцами, что вы ему доставили.>$B$BПрости. Я просто размечтался, как красиво будут на них смотреться мертвые наги. Благодарю тебя, Гнобс. Мы найдем применение этому оружию.','В молодости я взял пару уроков по ведению боя копьем.$B$BНасколько помню, в теории было так: "Протыкай врага острием копья".') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Капитан Злобешип любуется трезубцами, что вы ему доставили.>$B$BПрости. Я просто размечтался, как красиво будут на них смотреться мертвые наги. Благодарю тебя, Гнобс. Мы найдем применение этому оружию.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','В молодости я взял пару уроков по ведению боя копьем.$B$BНасколько помню, в теории было так: "Протыкай врага острием копья".',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25993,'Удар по телу','<Легионер Назгрим внимательно слушает ваш пересказ разговора Дуарна с Неспирой.>$B$BПонятно. Значит, она хочет, чтобы мы помогли ей проснуться, так?$B$BЕсли учесть, что сотни рабов уже собирают ее жемчужины, то, похоже, ее из пушки не разбудишь. Но, может, у тебя и получится.$B$BЯ вот что могу предложить: хорошо осмотри ее и попробуй найти слабое место. Быть может, если ударить в чувствительную точку, она придет в себя.','Ударьте Неспиру в 7 гнойников, расположенных на стенах ее полости.','Надеюсь, получилось. Понятия не имею, как мы узнаем, что она проснулась, но мне почему-то кажется, сразу поймем.','Вернитесь к легионеру Назгриму в Неспиру в Вайш\'ире.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Удар по телу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Легионер Назгрим внимательно слушает ваш пересказ разговора Дуарна с Неспирой.>$B$BПонятно. Значит, она хочет, чтобы мы помогли ей проснуться, так?$B$BЕсли учесть, что сотни рабов уже собирают ее жемчужины, то, похоже, ее из пушки не разбудишь. Но, может, у тебя и получится.$B$BЯ вот что могу предложить: хорошо осмотри ее и попробуй найти слабое место. Быть может, если ударить в чувствительную точку, она придет в себя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Ударьте Неспиру в 7 гнойников, расположенных на стенах ее полости.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Надеюсь, получилось. Понятия не имею, как мы узнаем, что она проснулась, но мне почему-то кажется, сразу поймем.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к легионеру Назгриму в Неспиру в Вайш\'ире.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25994,'Ценные вещи','Я недолго пробыла на жемчужных полях и так и не поняла, какие же цели преследуют наги. Известно, что они хотят использовать Неспиру как оружие в войне, но зачем тогда заставляют рабов добывать ее жемчуг?$B$BЕсли нам удастся отсюда выбраться, я бы хотела хорошенько изучить эти жемчужины. Правда, те, что нашли мы, были слишком большими. Нам их не унести. Но я видела в руках у полководцев и пророков жемчуг помельче.','Добудьте у полководцев и пророков Идра\'кесса в Неспире 5 таинственных жемчужин.','Отлично!$B$B<Талра прячет жемчуг под одежду.>$B$BТеперь необходимо, чтобы вы с легионером Назгримом отвели меня в безопасное место. Там я смогу начать исследования.','Похоже, у наг свои причины добывать этот жемчуг. И мне наверняка удалось бы их выяснить, будь у меня возможность изучить жемчужины.','Вернитесь к говорящей с волнами Талре в Неспиру в Вайш\'ире.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ценные вещи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я недолго пробыла на жемчужных полях и так и не поняла, какие же цели преследуют наги. Известно, что они хотят использовать Неспиру как оружие в войне, но зачем тогда заставляют рабов добывать ее жемчуг?$B$BЕсли нам удастся отсюда выбраться, я бы хотела хорошенько изучить эти жемчужины. Правда, те, что нашли мы, были слишком большими. Нам их не унести. Но я видела в руках у полководцев и пророков жемчуг помельче.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте у полководцев и пророков Идра\'кесса в Неспире 5 таинственных жемчужин.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично!$B$B<Талра прячет жемчуг под одежду.>$B$BТеперь необходимо, чтобы вы с легионером Назгримом отвели меня в безопасное место. Там я смогу начать исследования.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Похоже, у наг свои причины добывать этот жемчуг. И мне наверняка удалось бы их выяснить, будь у меня возможность изучить жемчужины.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к говорящей с волнами Талре в Неспиру в Вайш\'ире.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (25995,'Надзиратель Идра\'кесс','Мои люди измождены, $n. Боюсь, против наг нам долго не продержаться. Теперь у нас есть оружие Идра\'кесс и жемчуг Неспиры; пора выбираться отсюда.$B$BСтупай вдоль стены на северо-восток, там найдешь проход в верхнюю полость. Полагаю, в ней и скрывается их главный – или ключ к пробуждению Неспиры, а может, и то, и другое вместе.$B$BЕсли у тебя хватит сил, поднимись в верхнюю полость и найди ответы на наши вопросы! Адский Крик следит за тобой!','Отправляйтесь в верхнюю полость Неспиры и убейте надзирателя Идра\'кесса.','Можешь ничего не говорить... Неспира передавала мне все, что там происходило, а в остальные детали посвятил легионер Назгрим.$B$B<Дуарн закрывает глаза и кивает.>$B$BНеспира говорит, что благодарна тебе, а наг ждет небольшой сюрприз от нее.','Расскажите обо всем Целителю Земли Дуарну у мозга Неспиры в Вайш\'ире.','Осквернитель Неспиры','Надзиратель Идра\'кесс') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Надзиратель Идра\'кесс',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мои люди измождены, $n. Боюсь, против наг нам долго не продержаться. Теперь у нас есть оружие Идра\'кесс и жемчуг Неспиры; пора выбираться отсюда.$B$BСтупай вдоль стены на северо-восток, там найдешь проход в верхнюю полость. Полагаю, в ней и скрывается их главный – или ключ к пробуждению Неспиры, а может, и то, и другое вместе.$B$BЕсли у тебя хватит сил, поднимись в верхнюю полость и найди ответы на наши вопросы! Адский Крик следит за тобой!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в верхнюю полость Неспиры и убейте надзирателя Идра\'кесса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Можешь ничего не говорить... Неспира передавала мне все, что там происходило, а в остальные детали посвятил легионер Назгрим.$B$B<Дуарн закрывает глаза и кивает.>$B$BНеспира говорит, что благодарна тебе, а наг ждет небольшой сюрприз от нее.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Расскажите обо всем Целителю Земли Дуарну у мозга Неспиры в Вайш\'ире.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Осквернитель Неспиры',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Надзиратель Идра\'кесс',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25996,'Пробуждение','Благодаря вашей с легионером помощи Неспира вышла из оцепенения. Но большинству наг это пока неизвестно. Как только мы уйдем, Неспира запустит в своем теле защитные биологические процессы и уничтожит наг.$B$BПриготовься, а я пока прикажу Неспире начать обратный отсчет.','Поговорите с Целителем Земли Дуарном в Неспире, чтобы запустить защитные процессы. Затем покиньте тело Неспиры.','Расскажите обо всем легионеру Назгриму на базе Легиона в Вайш\'ире.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пробуждение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Благодаря вашей с легионером помощи Неспира вышла из оцепенения. Но большинству наг это пока неизвестно. Как только мы уйдем, Неспира запустит в своем теле защитные биологические процессы и уничтожит наг.$B$BПриготовься, а я пока прикажу Неспире начать обратный отсчет.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Целителем Земли Дуарном в Неспире, чтобы запустить защитные процессы. Затем покиньте тело Неспиры.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Расскажите обо всем легионеру Назгриму на базе Легиона в Вайш\'ире.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (25997,'Тайные планы Черного Железа','Группа шпионов Черного Железа захватила мастерскую Сталекрута, что к югу отсюда, за озером Хельмово Ложе. Обычно горные пехотинцы не дают им проникнуть в Дун Морог, но сейчас все в смятении.$b$bДворфы Черного Железа будут идиотами, если не воспользуются преимуществами создавшегося хаоса. Нужно узнать, что они замышляют, и остановить их, прежде чем они причинят нам вред.$b$bТы не можешь узнать, что они затевают в мастерской Сталекрута?','Отправляйтесь в мастерскую Сталекрута, убейте 5 шпионов из клана Черного Железа и отберите план нападения Черного Железа у капитана Бельда.','Я знал, что они сюда выбрались не на достопримечательности поглазеть.$B$B<Сержант изучает захваченный вами план, его глаза расширяются.>$B$BЭто серьезнее, чем я думал! Клан Черного Железа собирается нанести урон обороне самого Стальгорна!','Что они затевают?','Вернитесь к сержанту Бахруму в Лагерь Бахрума.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тайные планы Черного Железа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Группа шпионов Черного Железа захватила мастерскую Сталекрута, что к югу отсюда, за озером Хельмово Ложе. Обычно горные пехотинцы не дают им проникнуть в Дун Морог, но сейчас все в смятении.$b$bДворфы Черного Железа будут идиотами, если не воспользуются преимуществами создавшегося хаоса. Нужно узнать, что они замышляют, и остановить их, прежде чем они причинят нам вред.$b$bТы не можешь узнать, что они затевают в мастерской Сталекрута?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в мастерскую Сталекрута, убейте 5 шпионов из клана Черного Железа и отберите план нападения Черного Железа у капитана Бельда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я знал, что они сюда выбрались не на достопримечательности поглазеть.$B$B<Сержант изучает захваченный вами план, его глаза расширяются.>$B$BЭто серьезнее, чем я думал! Клан Черного Железа собирается нанести урон обороне самого Стальгорна!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что они затевают?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к сержанту Бахруму в Лагерь Бахрума.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (25998,'Попасть на аэродром','Согласно захваченным тобой документам клан Черного Железа планирует масштабную атаку на аэродром Стальгорна! Совет перебросил большую часть наших войск в Дун Морог, чтобы бороться с нестабильностью, вызванной Катаклизмом, в связи с чем защита аэродрома ослаблена.$b$bНам нужно быстро отправить тебя на аэродром. Иди на запад по дороге, которая ведет к карьеру Гол\'Болар, и найди Мателя Ржавого Ключа. У него должен быть ветролет, которым ты сможешь воспользоваться. Вперед!','Сядьте на ветролет Мателя в карьере Гол\'Болар.','Поговорите с командиром форта Камнеломов на аэродроме Стальгорна.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Попасть на аэродром',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Согласно захваченным тобой документам клан Черного Железа планирует масштабную атаку на аэродром Стальгорна! Совет перебросил большую часть наших войск в Дун Морог, чтобы бороться с нестабильностью, вызванной Катаклизмом, в связи с чем защита аэродрома ослаблена.$b$bНам нужно быстро отправить тебя на аэродром. Иди на запад по дороге, которая ведет к карьеру Гол\'Болар, и найди Мателя Ржавого Ключа. У него должен быть ветролет, которым ты сможешь воспользоваться. Вперед!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сядьте на ветролет Мателя в карьере Гол\'Болар.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с командиром форта Камнеломов на аэродроме Стальгорна.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (25999,'Вход перекрыт','Грязные никчемные ночные эльфы умудрились обезвредить наше минное поле на Тропе Когтя. Кто-то должен вернуться туда и заново расставить мины! Отличное задание для бесполезного рядового вроде тебя, $n. Надеюсь, у тебя хватит ума не подорваться во время выполнения задания.$B$BНа Тропе Когтя, к северу от нас, ты найдешь разбросанных "Убийц эльфов". Бери инструмент и за работу, салага!','Поставьте 8 кром\'гарских "Убийц эльфов".','<Саурбоз смотрит на вас.>$B$BНадо же, все конечности на месте. Повезло.','Обратитесь к Саурбозу в Изгибе в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вход перекрыт',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Грязные никчемные ночные эльфы умудрились обезвредить наше минное поле на Тропе Когтя. Кто-то должен вернуться туда и заново расставить мины! Отличное задание для бесполезного рядового вроде тебя, $n. Надеюсь, у тебя хватит ума не подорваться во время выполнения задания.$B$BНа Тропе Когтя, к северу от нас, ты найдешь разбросанных "Убийц эльфов". Бери инструмент и за работу, салага!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поставьте 8 кром\'гарских "Убийц эльфов".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Саурбоз смотрит на вас.>$B$BНадо же, все конечности на месте. Повезло.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Обратитесь к Саурбозу в Изгибе в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26000,'Спелеологи','Скорее, $n!$B$BНемедленно плыви к той пещере.$B$BМы тоже туда отправимся и проследим, нет ли за тобой хвоста.','Поговорите с Гурроком в Дымчатом гроте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спелеологи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Скорее, $n!$B$BНемедленно плыви к той пещере.$B$BМы тоже туда отправимся и проследим, нет ли за тобой хвоста.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Гурроком в Дымчатом гроте.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26001,'Пропавший взрынженер','Похоже, ты не совсем $gбесполезен:бесполезна;. Думаю, тебе можно поручить кое-что посложнее.$B$BПару дней назад взрынженер Улюлюк отправился в рудник Ветрорезов. Он должен был добраться туда, убедиться, что с бомбой все идет по плану, и вернуться с отчетом. Два дня прошло, а его все нет...$B$BОтправляйся на юг в леса и найди его. Лучше б он помер, иначе ему сильно не поздоровится.','Найдите взрынженера Улюлюка.','Взрынженер Улюлюк мертв. Может, это и к лучшему.$B$BКажется, у него в руке записка.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пропавший взрынженер',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Похоже, ты не совсем $gбесполезен:бесполезна;. Думаю, тебе можно поручить кое-что посложнее.$B$BПару дней назад взрынженер Улюлюк отправился в рудник Ветрорезов. Он должен был добраться туда, убедиться, что с бомбой все идет по плану, и вернуться с отчетом. Два дня прошло, а его все нет...$B$BОтправляйся на юг в леса и найди его. Лучше б он помер, иначе ему сильно не поздоровится.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите взрынженера Улюлюка.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Взрынженер Улюлюк мертв. Может, это и к лучшему.$B$BКажется, у него в руке записка.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26002,'План нападения Альянса','<Вы вытягиваете записку из руки Улюлюка.>$B$BОни будут атаковать! Они знают все про бомбу. Они хотят напасть на крепость Кром\'гар! Мне кажется, меня ищут. Отвертеться не получится. Придется дать им бой.$B$BЯ слышу их! Глава отряда – охотница из высших эльфов по имени Давиния. Она говорила о плане нападения. Отомстите за меня, убив ее и захватив этот план! Ее палатка недалеко, к востоку отсюда.$B$BАдский Крик следит за вами...','Отнимите план нападения Альянса у охотницы Давинии.','Доставьте план нападения Альянса Саурбозу в Изгиб в Когтистые горы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','План нападения Альянса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Вы вытягиваете записку из руки Улюлюка.>$B$BОни будут атаковать! Они знают все про бомбу. Они хотят напасть на крепость Кром\'гар! Мне кажется, меня ищут. Отвертеться не получится. Придется дать им бой.$B$BЯ слышу их! Глава отряда – охотница из высших эльфов по имени Давиния. Она говорила о плане нападения. Отомстите за меня, убив ее и захватив этот план! Ее палатка недалеко, к востоку отсюда.$B$BАдский Крик следит за вами...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнимите план нападения Альянса у охотницы Давинии.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доставьте план нападения Альянса Саурбозу в Изгиб в Когтистые горы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26003,'Урок с Затерянных островов','В лесах к югу отсюда полно опасностей. Дарнасские разведчики там прямо кишмя кишат – убийцы, которых Дарнас послал, чтобы разделаться с нами. А может, это мы побьем их, а?$B$BКогда я был на Затерянных островах, один гоблин подарил мне инфракрасные теплодетекторы. Тот, кто их носит, видит тепло, исходящее от живых существ. Возьми детекторы и не снимай их, пока будешь в лесу к югу отсюда. Так ты сможешь засечь разведчиков. Убей как можно больше этих гадов! За Орду!','Убейте 12 дарнасских разведчиков.','Очень хорошо, брат! Пусть запомнят, что нечего шпионить за Ордой!','Вернитесь к Килагу Жутеклыку в Изгиб в Когтистые горы') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Урок с Затерянных островов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В лесах к югу отсюда полно опасностей. Дарнасские разведчики там прямо кишмя кишат – убийцы, которых Дарнас послал, чтобы разделаться с нами. А может, это мы побьем их, а?$B$BКогда я был на Затерянных островах, один гоблин подарил мне инфракрасные теплодетекторы. Тот, кто их носит, видит тепло, исходящее от живых существ. Возьми детекторы и не снимай их, пока будешь в лесу к югу отсюда. Так ты сможешь засечь разведчиков. Убей как можно больше этих гадов! За Орду!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 дарнасских разведчиков.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Очень хорошо, брат! Пусть запомнят, что нечего шпионить за Ордой!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Килагу Жутеклыку в Изгиб в Когтистые горы',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (26004,'Крепость Кром\'гар','Наш штаб в Когтистых горах – крепость Кром\'гар. Оттуда властитель Кром\'гар управляет войсками Орды в этих краях. Он рассказывает обо всем, что видит, нашему вождю.$B$BВоенные планы, которые ты $gпринес:принесла;, касаются скорой атаки на крепость Кром\'гар. Тащи планы в крепость, она находится к юго-западу отсюда. Передай документы властителю$B$BДо встречи, $n. Адский Крик следит за тобой.','Доставьте план нападения Альянса властителю Кром\'гару в крепость Кром\'гар в Когтистых горах.','Это еще что такое? Почему эта мелкая сошка мозолит глаза властителю Кром\'гару?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Крепость Кром\'гар',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наш штаб в Когтистых горах – крепость Кром\'гар. Оттуда властитель Кром\'гар управляет войсками Орды в этих краях. Он рассказывает обо всем, что видит, нашему вождю.$B$BВоенные планы, которые ты $gпринес:принесла;, касаются скорой атаки на крепость Кром\'гар. Тащи планы в крепость, она находится к юго-западу отсюда. Передай документы властителю$B$BДо встречи, $n. Адский Крик следит за тобой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте план нападения Альянса властителю Кром\'гару в крепость Кром\'гар в Когтистых горах.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Это еще что такое? Почему эта мелкая сошка мозолит глаза властителю Кром\'гару?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26005,'Глоток свежего воздуха','Капитан Тейлор и многие другие выжившие уже поднялись на поверхность. Наверняка многие из побывавших в глубинах мечтают убраться отсюда подальше и навсегда забыть об этом месте, но нам предстоит еще многое сделать, чтобы не допустить наг в царство воды.$B$BДля начала необходимо расправиться с монстром, потопившим наши корабли по дороге сюда. Я не хочу, чтобы этот кошмар повторился. $B$BЭти сапоги оставил Мегагекс. Они помогут тебе быстрее добраться до места назначения.','Найдите капитана Тейлора на борту "Крепости Волдрина" в море над Руинами Вайш\'ира.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Глоток свежего воздуха',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Капитан Тейлор и многие другие выжившие уже поднялись на поверхность. Наверняка многие из побывавших в глубинах мечтают убраться отсюда подальше и навсегда забыть об этом месте, но нам предстоит еще многое сделать, чтобы не допустить наг в царство воды.$B$BДля начала необходимо расправиться с монстром, потопившим наши корабли по дороге сюда. Я не хочу, чтобы этот кошмар повторился. $B$BЭти сапоги оставил Мегагекс. Они помогут тебе быстрее добраться до места назначения.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите капитана Тейлора на борту "Крепости Волдрина" в море над Руинами Вайш\'ира.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26006,'Глоток свежего воздуха','Легионер Назгрим и многие другие выжившие уже поднялись на поверхность. Наверняка многие из побывавших в глубинах мечтают убраться отсюда подальше и навсегда забыть об этом месте, но нам предстоит еще многое сделать, чтобы не допустить наг в царство воды.$B$BДля начала необходимо расправиться с монстром, потопившим наши корабли по дороге сюда. Я не хочу, чтобы этот кошмар повторился. $B$BЭти сапоги оставил Облин. Они помогут тебе быстрее добраться до места назначения.','Разыщите легионера Назгрима на борту "Стигийской Награды" в море над Руинами Вайш\'ира.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Глоток свежего воздуха',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Легионер Назгрим и многие другие выжившие уже поднялись на поверхность. Наверняка многие из побывавших в глубинах мечтают убраться отсюда подальше и навсегда забыть об этом месте, но нам предстоит еще многое сделать, чтобы не допустить наг в царство воды.$B$BДля начала необходимо расправиться с монстром, потопившим наши корабли по дороге сюда. Я не хочу, чтобы этот кошмар повторился. $B$BЭти сапоги оставил Облин. Они помогут тебе быстрее добраться до места назначения.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите легионера Назгрима на борту "Стигийской Награды" в море над Руинами Вайш\'ира.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (26006,'Я вижу, ты прибыл сюда в целости и сохранности, $C!$B$BКак хорошо, что мы выбрались из этой мерзкой пучины... и немного припасов тут есть. Впрочем, отдыхать еще рано – нам нужно выполнить трудное и неприятное задание.$B$BА ты что скажешь? Тебе хватило на сегодня приключений или хочешь еще разок погрузиться в глубины во славу Адского Крика?') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я вижу, ты прибыл сюда в целости и сохранности, $C!$B$BКак хорошо, что мы выбрались из этой мерзкой пучины... и немного припасов тут есть. Впрочем, отдыхать еще рано – нам нужно выполнить трудное и неприятное задание.$B$BА ты что скажешь? Тебе хватило на сегодня приключений или хочешь еще разок погрузиться в глубины во славу Адского Крика?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26007,'Отчет','Этот солдат был при смерти, но, боюсь, у нас нет времени ждать, пока он полностью придет в себя. У него есть информация, которая позарез нам нужна.$B$BНаберись терпения и выпытай у него все, что нам необходимо знать.$B$BЕсли повезет, удастся выяснить, что нас тут ожидает...','Поговорите с Гурроком и узнайте все, что с ним произошло.','Что ж, обнадеживает слабо, но это хотя бы что-то...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отчет',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этот солдат был при смерти, но, боюсь, у нас нет времени ждать, пока он полностью придет в себя. У него есть информация, которая позарез нам нужна.$B$BНаберись терпения и выпытай у него все, что нам необходимо знать.$B$BЕсли повезет, удастся выяснить, что нас тут ожидает...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Гурроком и узнайте все, что с ним произошло.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что ж, обнадеживает слабо, но это хотя бы что-то...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26008,'Декомпрессия','Для меня невыносима мысль о том, что еще множество подобных этому воину находится в плену у наг.$b$bМы должны что-то предпринять, чтобы их спасти!$b$bПопробуй-ка вот что, $n. Сделай так, чтобы тюремные камеры всплыли на поверхность.$b$bЕсли нам удастся переместить их наверх, то возможно, их спасут.','Воспользуйтесь камнем дыхания Моаны, чтобы выручить 10 пленных воинов на Жемчужной ферме.','Будем надеяться, что освобожденные бойцы теперь в безопасности.$B$BВ награду за твою доблесть прошу тебя принять этот дар.','Поговорите с Моаной в Дымчатом гроте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Декомпрессия',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Для меня невыносима мысль о том, что еще множество подобных этому воину находится в плену у наг.$b$bМы должны что-то предпринять, чтобы их спасти!$b$bПопробуй-ка вот что, $n. Сделай так, чтобы тюремные камеры всплыли на поверхность.$b$bЕсли нам удастся переместить их наверх, то возможно, их спасут.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь камнем дыхания Моаны, чтобы выручить 10 пленных воинов на Жемчужной ферме.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Будем надеяться, что освобожденные бойцы теперь в безопасности.$B$BВ награду за твою доблесть прошу тебя принять этот дар.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Моаной в Дымчатом гроте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26009,'Найти и уничтожить','Убейте 20 солдат Альянса в Когтистых горах.','Много крови впитается в эту землю прежде, чем война закончится. И это будет кровь Альянса…','Вернитесь к властителю Кром\'гару в крепость Кром\'гар в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Найти и уничтожить',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 20 солдат Альянса в Когтистых горах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Много крови впитается в эту землю прежде, чем война закончится. И это будет кровь Альянса…',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к властителю Кром\'гару в крепость Кром\'гар в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26010,'Прах к праху','Лок\'тар! Пусть сгорят вместе с палатками!$B$B<Властитель Кром\'гар плюет на землю.>$B$BРадуйся победе, но недолго. Ты выиграл нам немного времени, только и всего.','Вернитесь к властителю Кром\'гару в крепость Кром\'гар в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прах к праху',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Лок\'тар! Пусть сгорят вместе с палатками!$B$B<Властитель Кром\'гар плюет на землю.>$B$BРадуйся победе, но недолго. Ты выиграл нам немного времени, только и всего.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к властителю Кром\'гару в крепость Кром\'гар в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26011,'Враг Орды: маршал Полтроу','Убейте маршала Полтроу.','В лагере Полтроу не было никаких подозрительных документов? А на его вонючем трупе? Хоть какого-то намека на планы Альянса относительно захвата Когтистых гор?','Вернитесь к главе шпионов Анаре в крепость Кром\'гар в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Враг Орды: маршал Полтроу',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте маршала Полтроу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','В лагере Полтроу не было никаких подозрительных документов? А на его вонючем трупе? Хоть какого-то намека на планы Альянса относительно захвата Когтистых гор?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к главе шпионов Анаре в крепость Кром\'гар в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26012,'Беда в храме Драконьего Покоя','Мой старый друг Крас прислал известие об ужасный событиях в храме Драконьего Покоя, что в Драконьем Погосте. Его сообщение довольно краткое, но из него мне стало понятно, что на Рубиновое святилище, находящееся под храмом, совершено нападение.$B$BК сожалению, неотложные дела не позволяют мне покинуть Даларан и лично разобраться с этим происшествием, но, полагаю, я могу доверить это тебе? Ты так хорошо $Gпроявил:проявила; себя в цитадели Короля-лича... пожалуйста, окажи помощь Красу!','Поговорите с Красом в храме Драконьего Покоя, что в Драконьем Погосте.','Поговорите с Красом в храме Драконьего Покоя, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Беда в храме Драконьего Покоя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мой старый друг Крас прислал известие об ужасный событиях в храме Драконьего Покоя, что в Драконьем Погосте. Его сообщение довольно краткое, но из него мне стало понятно, что на Рубиновое святилище, находящееся под храмом, совершено нападение.$B$BК сожалению, неотложные дела не позволяют мне покинуть Даларан и лично разобраться с этим происшествием, но, полагаю, я могу доверить это тебе? Ты так хорошо $Gпроявил:проявила; себя в цитадели Короля-лича... пожалуйста, окажи помощь Красу!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Красом в храме Драконьего Покоя, что в Драконьем Погосте.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Красом в храме Драконьего Покоя, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26013,'Нападение на святилище','$R, в Рубиновом святилище под храмом произошло нечто ужасное!$B$BГлавный вход разрушен, стражи мертвы... Мы послали туда разведчиков, но никто не вернулся живым. Боюсь, нам надо готовиться к худшему.$B$BОтправляйся в Рубиновое святилище и выясни, кто осмелился поднять руку на дом моего племени. Как только у нас будет больше информации, мы сможем спланировать дальнейшие действия.','Осмотрите Рубиновое святилище под храмом Драконьего Покоя.','Осмотрите Рубиновое святилище под храмом Драконьего Покоя.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нападение на святилище',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$R, в Рубиновом святилище под храмом произошло нечто ужасное!$B$BГлавный вход разрушен, стражи мертвы... Мы послали туда разведчиков, но никто не вернулся живым. Боюсь, нам надо готовиться к худшему.$B$BОтправляйся в Рубиновое святилище и выясни, кто осмелился поднять руку на дом моего племени. Как только у нас будет больше информации, мы сможем спланировать дальнейшие действия.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Осмотрите Рубиновое святилище под храмом Драконьего Покоя.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Осмотрите Рубиновое святилище под храмом Драконьего Покоя.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26014,'Братья Ройпой','Рядовой, стой! У нас небольшая проблема!$B$BМы отправили Хамфри и Оскара Ройпоев в Затемненную впадину на северо-запад, а они все никак не вернутся. Должны были разведку провести, но от них ни слуху, ни духу.$B$BТак что слушай приказ, рядовой $n! Отыщи наших товарищей и, если они живы, доставь сюда.','Поговорите с Хамфри Ройпоем в Затемненной впадине в Вайш\'ире.','Не вернулись, что ж тут удивительного! Мы немало невзгод перенесли за это время... А самое ужасное – я потерял своего дорогого брата Оскара.$B$B<Хамфри громко всхлипывает.>$B$BНе удержался – и его унесло. Бедняга! Ведь он просто хотел поймать пару рыбешек для капитана. Но его подхватило течение, и беднягу проглотил огромный угорь! У-у-у-у-у!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Братья Ройпой',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Рядовой, стой! У нас небольшая проблема!$B$BМы отправили Хамфри и Оскара Ройпоев в Затемненную впадину на северо-запад, а они все никак не вернутся. Должны были разведку провести, но от них ни слуху, ни духу.$B$BТак что слушай приказ, рядовой $n! Отыщи наших товарищей и, если они живы, доставь сюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Хамфри Ройпоем в Затемненной впадине в Вайш\'ире.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Не вернулись, что ж тут удивительного! Мы немало невзгод перенесли за это время... А самое ужасное – я потерял своего дорогого брата Оскара.$B$B<Хамфри громко всхлипывает.>$B$BНе удержался – и его унесло. Бедняга! Ведь он просто хотел поймать пару рыбешек для капитана. Но его подхватило течение, и беднягу проглотил огромный угорь! У-у-у-у-у!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26015,'Охота за фосфориями','Последнее, о чем мечтал Оскар перед отправкой в желудок огромного угря, – это принести капитану немного еды. Мы выполним его волю.$B$BБрат разработал гениальный план. Он видел, как мурлоки выманивают рыб специальной светящейся антенной. И сделал себе такую же. Все, что тебе понадобится, – это какой-нибудь светящийся предмет.$B$BУбей несколько крабов и окуней, обитающих на дне впадины. Сами по себе они несъедобны, но в них ценно не мясо, а фосфории.','Добудьте 6 люминесцентных фосфорий из огнепанцирных крабов и блестящих окуней в Затемненной впадине.','<Хамфри хватает у вас фосфории и прикрепляет их к какому-то необычному устройству.>$B$BНу вот. Красота! Оскар бы нами гордился.','Чтобы свет был достаточно ярким, нужно добыть побольше фосфорий – это очень важно, так как придется соревноваться с мурлоками.','Вернитесь к Хамфри Ройпою на дно Затемненной впадины в Вайш\'ире.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота за фосфориями',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Последнее, о чем мечтал Оскар перед отправкой в желудок огромного угря, – это принести капитану немного еды. Мы выполним его волю.$B$BБрат разработал гениальный план. Он видел, как мурлоки выманивают рыб специальной светящейся антенной. И сделал себе такую же. Все, что тебе понадобится, – это какой-нибудь светящийся предмет.$B$BУбей несколько крабов и окуней, обитающих на дне впадины. Сами по себе они несъедобны, но в них ценно не мясо, а фосфории.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 6 люминесцентных фосфорий из огнепанцирных крабов и блестящих окуней в Затемненной впадине.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Хамфри хватает у вас фосфории и прикрепляет их к какому-то необычному устройству.>$B$BНу вот. Красота! Оскар бы нами гордился.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Чтобы свет был достаточно ярким, нужно добыть побольше фосфорий – это очень важно, так как придется соревноваться с мурлоками.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хамфри Ройпою на дно Затемненной впадины в Вайш\'ире.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (26016,'Распоряжения из главного лагеря','Доставьте распоряжения из главного лагеря властителю Кром\'гару в крепость Кром\'гар в Когтистые горы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Распоряжения из главного лагеря',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте распоряжения из главного лагеря властителю Кром\'гару в крепость Кром\'гар в Когтистые горы.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26017,'Приманка','Прикрепи это к голове и плыви через водоросли и кораллы во впадине. Там полно мелких рыбешек, которые сразу клюнут на твою антенну.$B$BРыбы, которую мы принесем в Темную пещеру, хватит на всех!','Наденьте светошляпу и проплывите через заросли водорослей в Затемненной впадине, чтобы привлечь 30 люминесцентных гирелл.','Много удалось наловить?','Вернитесь к Хамфри Ройпою на дно Затемненной впадины в Вайш\'ире.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приманка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прикрепи это к голове и плыви через водоросли и кораллы во впадине. Там полно мелких рыбешек, которые сразу клюнут на твою антенну.$B$BРыбы, которую мы принесем в Темную пещеру, хватит на всех!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Наденьте светошляпу и проплывите через заросли водорослей в Затемненной впадине, чтобы привлечь 30 люминесцентных гирелл.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Много удалось наловить?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хамфри Ройпою на дно Затемненной впадины в Вайш\'ире.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26018,'Смерть Холодному Сиянию','Ах да! Чуть не забыл! Мне же нужно подготовить отчет.$B$BПохоже, здесь довольно безопасно... Если не считать огромных угрей и нескольких мурлоков. Думаю, капитана гораздо больше заинтересуют мурлоки. $B$BСтупай, напади на парочку – надо узнать, на что они способны в бою. Насколько мне известно, крупные особи охотятся на рыбу среди водорослей, а мелкие прибегают к какой-то магии... Больше я ничего о них не знаю.','Убейте 4 охотников Холодного Сияния и 4 оракулов Холодного Сияния.','<Хамфри выслушивает ваш рассказ о битве с мурлоками.>$B$BХм... Похоже, это наши старые добрые мурлоки... Только живущие под водой. Капитан Гловааль обрадуется.','Вернитесь к Хамфри Ройпою на дно Затемненной впадины в Вайш\'ире.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Смерть Холодному Сиянию',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ах да! Чуть не забыл! Мне же нужно подготовить отчет.$B$BПохоже, здесь довольно безопасно... Если не считать огромных угрей и нескольких мурлоков. Думаю, капитана гораздо больше заинтересуют мурлоки. $B$BСтупай, напади на парочку – надо узнать, на что они способны в бою. Насколько мне известно, крупные особи охотятся на рыбу среди водорослей, а мелкие прибегают к какой-то магии... Больше я ничего о них не знаю.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 4 охотников Холодного Сияния и 4 оракулов Холодного Сияния.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Хамфри выслушивает ваш рассказ о битве с мурлоками.>$B$BХм... Похоже, это наши старые добрые мурлоки... Только живущие под водой. Капитан Гловааль обрадуется.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хамфри Ройпою на дно Затемненной впадины в Вайш\'ире.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26019,'Огромная икринка угря','<Видимо, это икринка одного из ужасных огромных угрей, обитающих во впадине. Вы размышляете над тем, не заинтересуется ли ею Хамфри.>','Отнесите огромную икринку угря Хамфри Ройпою на дно Затемненной впадины в Вайш\'ире.','Что-о? Икринка? Огромного угря?$B$B<Вы прямо-таки видите, как у Хамфри в голове шевелятся мысли.>$B$BДа, мы извлечем из этого пользу! Готовься, пришло время жестокой мести Ройпоев!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Огромная икринка угря',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Видимо, это икринка одного из ужасных огромных угрей, обитающих во впадине. Вы размышляете над тем, не заинтересуется ли ею Хамфри.>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите огромную икринку угря Хамфри Ройпою на дно Затемненной впадины в Вайш\'ире.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что-о? Икринка? Огромного угря?$B$B<Вы прямо-таки видите, как у Хамфри в голове шевелятся мысли.>$B$BДа, мы извлечем из этого пользу! Готовься, пришло время жестокой мести Ройпоев!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26020,'В распоряжение Бомбиглотc','Надо подготовиться к нападению. Наши солдаты подготовят бомбу. А тебе нужно отправиться к взрынженеру Бомбиглотc. Она работает над починкой орудий противовоздушной обороны, но пока безуспешно. Иди и убедись, $n, что она работает с должной мотивацией.','Поступите в распоряжение взрынженера Бомбиглотc в крепости Кром\'гар в Когтистых горах.','С должной моти… что? что это значит? Слушай, сержант, у меня есть встроенный механизм, называется "личный интерес". НЕ УМЕРЕТЬ – точно в моих личных интересах. Ну вот, а проблема в том, что без нужных материалов я пушки не починю.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В распоряжение Бомбиглотc',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Надо подготовиться к нападению. Наши солдаты подготовят бомбу. А тебе нужно отправиться к взрынженеру Бомбиглотc. Она работает над починкой орудий противовоздушной обороны, но пока безуспешно. Иди и убедись, $n, что она работает с должной мотивацией.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поступите в распоряжение взрынженера Бомбиглотc в крепости Кром\'гар в Когтистых горах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','С должной моти… что? что это значит? Слушай, сержант, у меня есть встроенный механизм, называется "личный интерес". НЕ УМЕРЕТЬ – точно в моих личных интересах. Ну вот, а проблема в том, что без нужных материалов я пушки не починю.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26021,'Братья Ройпой – 2: фокус с икринкой угря','Эти угри сожрали моего брата. Брата, слышишь, $n! Пришло время показать им, кто здесь главный.$B$B<Хамфри достает несколько шашек динамита из карманов и вставляет их в икринку.>В одиночку с огромным угрем не справиться, но благодаря этой икринке мы сравняем силы. Оставь ее рядом с одним из угрей и... Ба-бах!$B$BЕсли угорь и не погибнет от взрыва, все равно будет сильно ранен, и ты его легко добьешь.','При помощи угретонатора взорвите ужасного огромного угря в Затемненной впадине, а затем добейте раненого угря.','Вернитесь к Хамфри Ройпою на дно Затемненной впадины в Вайш\'ире.','Бедный мой брат, бедный Оскар Ройпой! Его поглотил угорь.','Оскар Ройпой') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Братья Ройпой – 2: фокус с икринкой угря',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти угри сожрали моего брата. Брата, слышишь, $n! Пришло время показать им, кто здесь главный.$B$B<Хамфри достает несколько шашек динамита из карманов и вставляет их в икринку.>В одиночку с огромным угрем не справиться, но благодаря этой икринке мы сравняем силы. Оставь ее рядом с одним из угрей и... Ба-бах!$B$BЕсли угорь и не погибнет от взрыва, все равно будет сильно ранен, и ты его легко добьешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','При помощи угретонатора взорвите ужасного огромного угря в Затемненной впадине, а затем добейте раненого угря.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хамфри Ройпою на дно Затемненной впадины в Вайш\'ире.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Бедный мой брат, бедный Оскар Ройпой! Его поглотил угорь.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Оскар Ройпой',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26022,'Первая кровь','Будь $gготов:готова;, $n. На этом поле ты прольешь за нас первую кровь.$b$bТе, кто называют себя Синдикатом, на самом деле трусливые людишки, способные предать своих же собственных собратьев. Изоляция делает их легкой добычей.$b$bОтправляйся на север, убей всех наемников Синдиката, какие тебе встретятся, и объяви Северное поместье принадлежащим Отрекшимся. В доказательство своей победы принеси мне амулеты из кровавого камня.','Убейте наемников Синдиката и соберите 10 амулетов из кровавого камня.','Вернитесь к темному следопыту Алине в Удел Галена, что на Нагорье Арати.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Первая кровь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Будь $gготов:готова;, $n. На этом поле ты прольешь за нас первую кровь.$b$bТе, кто называют себя Синдикатом, на самом деле трусливые людишки, способные предать своих же собственных собратьев. Изоляция делает их легкой добычей.$b$bОтправляйся на север, убей всех наемников Синдиката, какие тебе встретятся, и объяви Северное поместье принадлежащим Отрекшимся. В доказательство своей победы принеси мне амулеты из кровавого камня.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте наемников Синдиката и соберите 10 амулетов из кровавого камня.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к темному следопыту Алине в Удел Галена, что на Нагорье Арати.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) VALUES (26022,'Мне недостаточно слов. Ты принес доказательство?') ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мне недостаточно слов. Ты принес доказательство?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26023,'Отрекшийся Троллебой','Я расскажу тебе одну историю.$b$bЖил-был глупый тролль по имени Зенгу. Ему дали задание разыскать меч Трол\'калар, легендарный клинок, принадлежащий человеческому роду Троллебоев. Ему удалось это сделать и, уверенный, что задание выполнено, он решил покинуть Арати. После этого люди зарезали его, а меч просто-напросто отобрали.$b$bМы же не будем столь глупы. Наши аптекари дали нам идеального проводника для того, чтобы снова заполучить Трол\'калар: принца, который когда-то уже обладал этим мечом.$b$bОн готов проводить тебя, $n. Поговори с ним.','Поговорите с Галеном Троллебоем.','Да… Когда-то я был принцем павшего королевства Стромгарда. Тот, кто искал Трол\'калар, сразил меня.$B$BТеперь я сожалею о моей глупой жизни. Я служу… только Сильване.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отрекшийся Троллебой',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я расскажу тебе одну историю.$b$bЖил-был глупый тролль по имени Зенгу. Ему дали задание разыскать меч Трол\'калар, легендарный клинок, принадлежащий человеческому роду Троллебоев. Ему удалось это сделать и, уверенный, что задание выполнено, он решил покинуть Арати. После этого люди зарезали его, а меч просто-напросто отобрали.$b$bМы же не будем столь глупы. Наши аптекари дали нам идеального проводника для того, чтобы снова заполучить Трол\'калар: принца, который когда-то уже обладал этим мечом.$b$bОн готов проводить тебя, $n. Поговори с ним.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Галеном Троллебоем.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да… Когда-то я был принцем павшего королевства Стромгарда. Тот, кто искал Трол\'калар, сразил меня.$B$BТеперь я сожалею о моей глупой жизни. Я служу… только Сильване.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26024,'Разыскивается: Марез Клобук','Назначена награда за голову Марез Клобук, высокопоставленной советницы и деятеля Синдиката. В последний раз ее видели на контролируемой Синдикатом территории Стромгарда.$B$BНаграду можно будет получить у капитана Ниалс.$B$BПредупреждение: Марез – опытная и коварная чернокнижница, замеченная в связях с демонами. При поимке рекомендуется предельная осторожность.','Принесите голову Марез капитану Ниалс в Опорный пункт.','Вернитесь к капитану Ниалс в Опорный пункт на Нагорье Арати.','Принеси мне ее голову!','Марез Клобук') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разыскивается: Марез Клобук',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Назначена награда за голову Марез Клобук, высокопоставленной советницы и деятеля Синдиката. В последний раз ее видели на контролируемой Синдикатом территории Стромгарда.$B$BНаграду можно будет получить у капитана Ниалс.$B$BПредупреждение: Марез – опытная и коварная чернокнижница, замеченная в связях с демонами. При поимке рекомендуется предельная осторожность.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите голову Марез капитану Ниалс в Опорный пункт.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Ниалс в Опорный пункт на Нагорье Арати.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Принеси мне ее голову!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Марез Клобук',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26025,'Орк изменник','Я не сомневаюсь, что в стенах Стромгарда засел могущественный чернокнижник. Время от времени, используя некую святыню, обладающую магической энергией, этот чернокнижник в больших количествах призывал ужасных демонов. Мы должны отнять у него этот источник энергии.$B$BНайди чернокнижника и убей его. Принеси мне магический объект, который при нем найдешь, что бы это ни было. Я сделаю все, что нужно, чтобы разрушить эту святыню, и прослежу, чтобы ее мощь больше не использовалась для осквернения этой земли.','Найдите оскверненную сферу из кровавого камня Марез Клобук.','Вернитесь к темному следопыту Алине в Удел Галена, что на Нагорье Арати.','Добудьте оскверненную сферу Кровавого камня','Марез Клобук') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Орк изменник',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я не сомневаюсь, что в стенах Стромгарда засел могущественный чернокнижник. Время от времени, используя некую святыню, обладающую магической энергией, этот чернокнижник в больших количествах призывал ужасных демонов. Мы должны отнять у него этот источник энергии.$B$BНайди чернокнижника и убей его. Принеси мне магический объект, который при нем найдешь, что бы это ни было. Я сделаю все, что нужно, чтобы разрушить эту святыню, и прослежу, чтобы ее мощь больше не использовалась для осквернения этой земли.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите оскверненную сферу из кровавого камня Марез Клобук.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к темному следопыту Алине в Удел Галена, что на Нагорье Арати.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Добудьте оскверненную сферу Кровавого камня',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Марез Клобук',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26026,'Мечта о будущем','Добудьте машину войны БА-64, механизированный огонь, механизированный лед и механизированный воздух.','<Кларисса радостно хлопает в ладоши.>$B$BГосподин З.П., ты поправишься! Ура-а-а-а!$B$B<Кларисса умело вставляет все принесенные вами детали в Здорового папусю.>$B$BОй, господин З.П.! Я знала, знала!','Господин З.П. такой грустный. Надо развеселить его!','Вернитесь к Клариссе в крепость Кром\'гар в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мечта о будущем',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте машину войны БА-64, механизированный огонь, механизированный лед и механизированный воздух.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Кларисса радостно хлопает в ладоши.>$B$BГосподин З.П., ты поправишься! Ура-а-а-а!$B$B<Кларисса умело вставляет все принесенные вами детали в Здорового папусю.>$B$BОй, господин З.П.! Я знала, знала!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Господин З.П. такой грустный. Надо развеселить его!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Клариссе в крепость Кром\'гар в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26027,'Призыв к оружию','Для нашего следующего удара по ограм тебе нужно будет отправиться дальше на восток от Стромгарда. Оставшиеся в живых считают, что эти опустошенные руины стоят того, чтобы за них цепляться. Их сентиментальность отвратительна!$b$bДля нас весь Стромгард – не более чем еще одно смрадное логово огров, которых надо уничтожить. Отправляйся туда, убей их вождей и шаманов и убедись, что никто из оставшихся огров не сможет стать их предводителем.','Убейте 7 шаманов из клана Тяжелого Кулака и 3 вождей клана Тяжелого Кулака.','Избавился от них? Хорошо. Сомневаюсь, что мы будем тратить время на то, чтобы обыскать Стромгард. Эти полуразвалившиеся лачуги надо просто сровнять с землей.$B$BОсвободившееся место отлично подойдет для нового Подгорода.','Вернитесь темному следопыту Алине в Удел Галена, что на Нагорье Арати.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Призыв к оружию',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Для нашего следующего удара по ограм тебе нужно будет отправиться дальше на восток от Стромгарда. Оставшиеся в живых считают, что эти опустошенные руины стоят того, чтобы за них цепляться. Их сентиментальность отвратительна!$b$bДля нас весь Стромгард – не более чем еще одно смрадное логово огров, которых надо уничтожить. Отправляйся туда, убей их вождей и шаманов и убедись, что никто из оставшихся огров не сможет стать их предводителем.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 7 шаманов из клана Тяжелого Кулака и 3 вождей клана Тяжелого Кулака.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Избавился от них? Хорошо. Сомневаюсь, что мы будем тратить время на то, чтобы обыскать Стромгард. Эти полуразвалившиеся лачуги надо просто сровнять с землей.$B$BОсвободившееся место отлично подойдет для нового Подгорода.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь темному следопыту Алине в Удел Галена, что на Нагорье Арати.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26028,'Дикая охота господина З. П.','Теперь господину З. П. нужен добрый дух, который помог бы ему ориентироваться в пространстве. Вы не поработаете добрым духом, $gсударь:сударыня;? Если вы мне поможете, мы заберемся на эту скалу и перебьем много-много нехороших ребят из Альянса! Что скажете? Пожалуйста, $gсударь:сударыня;! НУ ПОЖАЛУЙСТА!$B$BЕсли мы перебьем много хулиганов из Альянса, господин Кром\'гар купит нам всем мороженое!','Убейте 20 гномских инженеров и 5 гномских патрульных.','<Властитель Кром\'гар кашляет.>$B$BПожалуй… впервые в жизни… у меня нет слов.$B$BЯ понятия не имею, откуда взялась эта Кларисса…','Поговорите с властителем Кром\'гаром в крепости Кром\'гар в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дикая охота господина З. П.',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь господину З. П. нужен добрый дух, который помог бы ему ориентироваться в пространстве. Вы не поработаете добрым духом, $gсударь:сударыня;? Если вы мне поможете, мы заберемся на эту скалу и перебьем много-много нехороших ребят из Альянса! Что скажете? Пожалуйста, $gсударь:сударыня;! НУ ПОЖАЛУЙСТА!$B$BЕсли мы перебьем много хулиганов из Альянса, господин Кром\'гар купит нам всем мороженое!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 20 гномских инженеров и 5 гномских патрульных.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Властитель Кром\'гар кашляет.>$B$BПожалуй… впервые в жизни… у меня нет слов.$B$BЯ понятия не имею, откуда взялась эта Кларисса…',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с властителем Кром\'гаром в крепости Кром\'гар в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26029,'Настоящая угроза','Здешними ограми руководит Ор\'Калар. Годами ему удавалось ускользать от расправы. Само его присутствие – это оскорбление Темной Госпожи. Муг\'тол, предатель Отрекшихся, издалека отдает ему приказы!$b$bНа земле Отрекшихся мы не потерпим ни огров, ни предателей. Принеси мне голову этого огра, а уж я прослежу, чтобы в этот раз ее точно сожгли.','Убейте Ор\'Калара и заберите его голову.','Такова будет судьба всех, кто встанет на нашем пути.','Говори быстро.','Вернитесь к ловчей смерти Маудрии в Удел Галена, что на Нагорье Арати.','Ор\'Калар на голову выше любого из своих соплеменников. Это надо исправить.','Ор\'Калар') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Настоящая угроза',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Здешними ограми руководит Ор\'Калар. Годами ему удавалось ускользать от расправы. Само его присутствие – это оскорбление Темной Госпожи. Муг\'тол, предатель Отрекшихся, издалека отдает ему приказы!$b$bНа земле Отрекшихся мы не потерпим ни огров, ни предателей. Принеси мне голову этого огра, а уж я прослежу, чтобы в этот раз ее точно сожгли.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Ор\'Калара и заберите его голову.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Такова будет судьба всех, кто встанет на нашем пути.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Говори быстро.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ловчей смерти Маудрии в Удел Галена, что на Нагорье Арати.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Ор\'Калар на голову выше любого из своих соплеменников. Это надо исправить.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Ор\'Калар',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26030,'Печать Строма','Заберите печать Строма у членов Синдиката в крепости Стромгард.','При жизни я ненавидел Синдикат ничуть не меньше, чем ненавижу его после смерти. Но вновь обретенная печать служит небольшим утешением.$B$BНо нам еще многое нужно сделать… для Сильваны.','Печать может быть только у агентов Синдиката в Стромгарде. Проливать кровь вне стен крепости – значит просто терять время.','Вернитесь к Галену Троллебою в Удел Галена на Нагорье Арати.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Печать Строма',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заберите печать Строма у членов Синдиката в крепости Стромгард.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','При жизни я ненавидел Синдикат ничуть не меньше, чем ненавижу его после смерти. Но вновь обретенная печать служит небольшим утешением.$B$BНо нам еще многое нужно сделать… для Сильваны.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Печать может быть только у агентов Синдиката в Стромгарде. Проливать кровь вне стен крепости – значит просто терять время.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Галену Троллебою в Удел Галена на Нагорье Арати.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26031,'Печать Торадина','При жизни, чтобы защитить печать Торадина, я разделил ее на пять частей и раздал их моим самым верным соратникам. Это не помогло, но мой преемник сделал то же самое.$b$bЗащитники Стромгарда до сих пор владеют частями печати. Убей их и принеси мне все фрагменты. Я соединю их.','Соберите 5 фрагментов печати, убив стромгардских защитников в крепости Стромгард.','Торадин был основателем Аратора. Как я сейчас соединяю эти фрагменты, так и он объединял разрозненные людские племена в их первую великую нацию.$B$BНо, думаю, все это тебе неинтересно. Извини. Часто бывает сложно расставаться со старыми воспоминаниями.','Чтобы восстановить печать, мне нужны все пять фрагментов...','Вернитесь к Галену Троллебою в Удел Галена на Нагорье Арати.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Печать Торадина',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','При жизни, чтобы защитить печать Торадина, я разделил ее на пять частей и раздал их моим самым верным соратникам. Это не помогло, но мой преемник сделал то же самое.$b$bЗащитники Стромгарда до сих пор владеют частями печати. Убей их и принеси мне все фрагменты. Я соединю их.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 5 фрагментов печати, убив стромгардских защитников в крепости Стромгард.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Торадин был основателем Аратора. Как я сейчас соединяю эти фрагменты, так и он объединял разрозненные людские племена в их первую великую нацию.$B$BНо, думаю, все это тебе неинтересно. Извини. Часто бывает сложно расставаться со старыми воспоминаниями.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Чтобы восстановить печать, мне нужны все пять фрагментов...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Галену Троллебою в Удел Галена на Нагорье Арати.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertargetname_loc8`) VALUES (26032,'Печать Аратора','Я доверил печать Аратора лейтенанту Храброгласу, командиру моих кавалеристов. Он едва не расстался с жизнью, защищая ее, но ему удалось тогда сбежать.$b$bВряд ли это получится у него и во второй раз. Храброглас патрулирует дорогу между крепостью Стромгард и Опорным пунктом. Найди его и снова забери у него печать.','Заберите печать Аратора у лейтенанта Храброгласа.','При жизни Храброглас верно служил мне. Мне будет нелегко пережить его смерть.$B$BНо пережить ее я должен. Я Отрекшийся. Мое прежнее существование ничего не значит.$B$BПечати наши. Трол\'калар ждет.','Забрал печать?','Вернитесь к Галену Троллебою в Удел Галена на Нагорье Арати.','Лейтенант Храброглас') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Печать Аратора',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я доверил печать Аратора лейтенанту Храброгласу, командиру моих кавалеристов. Он едва не расстался с жизнью, защищая ее, но ему удалось тогда сбежать.$b$bВряд ли это получится у него и во второй раз. Храброглас патрулирует дорогу между крепостью Стромгард и Опорным пунктом. Найди его и снова забери у него печать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заберите печать Аратора у лейтенанта Храброгласа.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','При жизни Храброглас верно служил мне. Мне будет нелегко пережить его смерть.$B$BНо пережить ее я должен. Я Отрекшийся. Мое прежнее существование ничего не значит.$B$BПечати наши. Трол\'калар ждет.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Забрал печать?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Галену Троллебою в Удел Галена на Нагорье Арати.',`completedtext_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Лейтенант Храброглас',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26033,'Трол\'калар','Последняя печать моя... и вместе с ней все четыре образуют печать Троллебоя, ключ к могиле. Мы готовы.$b$bТрол\'калар лежит рядом с останками своего владельца, в могиле в катакомбах Стромгарда. Его будут защищать... но тот факт, что я стою перед тобой, говорит о том, что любую защиту можно пробить.$b$bДостань Трол\'калар из могилы и принеси его сюда.','Достаньте Трол\'калар из могилы Троллебоя в Стромгарде.','Трол\'калар, клинок моего отца… кажется, прошла вечность с тех пор, как я последний раз видел его.','Вернитесь к Галену Троллебою в Удел Галена на Нагорье Арати.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Трол\'калар',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Последняя печать моя... и вместе с ней все четыре образуют печать Троллебоя, ключ к могиле. Мы готовы.$b$bТрол\'калар лежит рядом с останками своего владельца, в могиле в катакомбах Стромгарда. Его будут защищать... но тот факт, что я стою перед тобой, говорит о том, что любую защиту можно пробить.$b$bДостань Трол\'калар из могилы и принеси его сюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Достаньте Трол\'калар из могилы Троллебоя в Стромгарде.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Трол\'калар, клинок моего отца… кажется, прошла вечность с тех пор, как я последний раз видел его.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Галену Троллебою в Удел Галена на Нагорье Арати.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26034,'Сумеречный разрушитель','Нет, это было не случайное нападение, а организованная атака на род красных драконов.$B$BЯ вижу Заритриана, наблюдающего за битвой с вершины холма, но истинный лидер захватчиков – могущественный сумеречный дракон Халион. В первый раз после появления Даргонакса мы столкнулись со взрослым отпрыском Зловестины.$B$BУбей его, $n, изгони захватчиков и сообщи Красу обо всем, что ты здесь $Gвидел:видела;.','Победите Халиона и отразите нападение на Рубиновое святилище.','Вернитесь к Красу на вершину храма Драконьего Покоя.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сумеречный разрушитель',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нет, это было не случайное нападение, а организованная атака на род красных драконов.$B$BЯ вижу Заритриана, наблюдающего за битвой с вершины холма, но истинный лидер захватчиков – могущественный сумеречный дракон Халион. В первый раз после появления Даргонакса мы столкнулись со взрослым отпрыском Зловестины.$B$BУбей его, $n, изгони захватчиков и сообщи Красу обо всем, что ты здесь $Gвидел:видела;.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Халиона и отразите нападение на Рубиновое святилище.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Красу на вершину храма Драконьего Покоя.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26035,'На вес золота','Верховный маг Малин послал меня собрать для него реагенты. Я был в полном замешательстве и не знал, как приступить к делу, но теперь, когда ты здесь, думаю, что моя проблема разрешится.$b$bВот что мне нужно: клыки тролля из племени Сухокожих и лекарские сумки племени Сухокожих.$b$bНе $gмог:могла; бы ты раздобыть все это для меня? Племя Сухокожих обитает к юго-востоку от Арати.','Соберите 10 клыков троллей из племени Сухокожих и 4 лекарские сумки племени Сухокожих.','Неплохо. Что ж, похоже, у тебя есть голова на плечах, поэтому я надеюсь, что ты поможешь нам и с более неотложной работой.','Удалось собрать реагенты?','Вернитесь к Скуэрто в Опорный пункт на Нагорье Арати.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На вес золота',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Верховный маг Малин послал меня собрать для него реагенты. Я был в полном замешательстве и не знал, как приступить к делу, но теперь, когда ты здесь, думаю, что моя проблема разрешится.$b$bВот что мне нужно: клыки тролля из племени Сухокожих и лекарские сумки племени Сухокожих.$b$bНе $gмог:могла; бы ты раздобыть все это для меня? Племя Сухокожих обитает к юго-востоку от Арати.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 клыков троллей из племени Сухокожих и 4 лекарские сумки племени Сухокожих.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Неплохо. Что ж, похоже, у тебя есть голова на плечах, поэтому я надеюсь, что ты поможешь нам и с более неотложной работой.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось собрать реагенты?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Скуэрто в Опорный пункт на Нагорье Арати.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26036,'Оружие получше кулаков','Найдите заклинательный жезл Трелана и принесите его Скуэрто в Опорный пункт.','Вернитесь к Скуэрто в Опорный пункт на Нагорье Арати.','Теперь, когда у нас есть жезл, мы можем действовать в соответствии с планом.','Кор\'греш Холодная Ярость') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оружие получше кулаков',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите заклинательный жезл Трелана и принесите его Скуэрто в Опорный пункт.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Скуэрто в Опорный пункт на Нагорье Арати.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Теперь, когда у нас есть жезл, мы можем действовать в соответствии с планом.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Кор\'греш Холодная Ярость',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26037,'Оборона Трелана','$gОтдохнул:Отдохнула;?$B$BВот наш следующий шаг: огры так и кишат вокруг башни Аратора в Стромгарде. Необходимо активировать защитные возможности башни, чтобы иметь хоть малейший шанс выстоять против них. Чтобы это сделать, нам понадобится несколько самоцветов, на которые наложил лапы шаман клана Тяжелого Кулака. Он стянул их из башни, но радость его преждевременна – камни недолго будут в его власти.$B$BДостань один из самоцветов и принеси его Крайтену – он знает заклинание, которое нужно наложить на эти камни, чтобы они работали как ключи.','Найдите лазурный агат и принесите его ученику Крайтену в крепость Стромгард.','Вернитесь к ученику Крайтену в крепость Стромгард, что на Нагорье Арати.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оборона Трелана',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$gОтдохнул:Отдохнула;?$B$BВот наш следующий шаг: огры так и кишат вокруг башни Аратора в Стромгарде. Необходимо активировать защитные возможности башни, чтобы иметь хоть малейший шанс выстоять против них. Чтобы это сделать, нам понадобится несколько самоцветов, на которые наложил лапы шаман клана Тяжелого Кулака. Он стянул их из башни, но радость его преждевременна – камни недолго будут в его власти.$B$BДостань один из самоцветов и принеси его Крайтену – он знает заклинание, которое нужно наложить на эти камни, чтобы они работали как ключи.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите лазурный агат и принесите его ученику Крайтену в крепость Стромгард.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ученику Крайтену в крепость Стромгард, что на Нагорье Арати.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26038,'Атака на башню','Вот что тебе нужно найти: талисман Трелана, сферу Трелана и угольный агат Трелана.$B$BВсе эти три предмета должны быть в сундуках в башне, и ты преспокойно откроешь эти сундуки. Главное – берегись огров.$B$BОружие лучше держать наготове. Эти огры сообразят, что ты там и пытаешься обокрасть их, и, ясное дело, решат задать тебе взбучку.$B$BБудь $gосторожен:осторожна; – и удачи!','Найдите талисман Трелана, сферу Трелана и угольный агат Трелана и принесите их Скуэрто в Опорный пункт.','У тебя все получится, и я уверен, Малин будет более чем доволен тобой.','Вернитесь к Скуэрто в Опорный пункт на Нагорье Арати.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Атака на башню',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот что тебе нужно найти: талисман Трелана, сферу Трелана и угольный агат Трелана.$B$BВсе эти три предмета должны быть в сундуках в башне, и ты преспокойно откроешь эти сундуки. Главное – берегись огров.$B$BОружие лучше держать наготове. Эти огры сообразят, что ты там и пытаешься обокрасть их, и, ясное дело, решат задать тебе взбучку.$B$BБудь $gосторожен:осторожна; – и удачи!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите талисман Трелана, сферу Трелана и угольный агат Трелана и принесите их Скуэрто в Опорный пункт.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У тебя все получится, и я уверен, Малин будет более чем доволен тобой.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Скуэрто в Опорный пункт на Нагорье Арати.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26039,'Плененная принцесса','Отберите 12 частиц Мизраэль у кобольдов из племени Сухоусов.','Ах, тебе удалось активировать эти кристаллы. Я уже чувствую, что начинаю приходить в себя!$B$BНо, увы, до свободы еще далеко…','Группа кристаллов гораздо больше похожа на кристаллы Мизраэль. Но от них не исходит такое же ощущение безопасности.','Найдите частицы Мизраэль в теснине Сухоусов на Нагорье Арати.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Плененная принцесса',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отберите 12 частиц Мизраэль у кобольдов из племени Сухоусов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ах, тебе удалось активировать эти кристаллы. Я уже чувствую, что начинаю приходить в себя!$B$BНо, увы, до свободы еще далеко…',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Группа кристаллов гораздо больше похожа на кристаллы Мизраэль. Но от них не исходит такое же ощущение безопасности.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Найдите частицы Мизраэль в теснине Сухоусов на Нагорье Арати.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26040,'Ой-ой – что со мной?','Ох... да что ж такое?!$B$BВнутри все болит... и крутит...$B$BПохоже... эх... Меня отравили!$B$BНас накормили какими-то странными светящимися водорослями, которые выращиваются у крепости.$B$BМне кажется, живот схватит еще сильнее, если не съесть еще маленько...$B$BПрошу тебя, |3-6($r), принеси водорослей!','Соберите 7 побегов вьющихся водорослей у жнецов Мерцающего хребта на Жемчужной ферме.','Поговорите с Гурроком в Дымчатом гроте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ой-ой – что со мной?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ох... да что ж такое?!$B$BВнутри все болит... и крутит...$B$BПохоже... эх... Меня отравили!$B$BНас накормили какими-то странными светящимися водорослями, которые выращиваются у крепости.$B$BМне кажется, живот схватит еще сильнее, если не съесть еще маленько...$B$BПрошу тебя, |3-6($r), принеси водорослей!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 7 побегов вьющихся водорослей у жнецов Мерцающего хребта на Жемчужной ферме.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Гурроком в Дымчатом гроте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26041,'Связывающие камни','Четыре связывающих камня разбросаны по Нагорью Арати. Эти камни пригвоздили меня к земле.$b$bРазрушить оковы можно, сняв замок с самого мощного из них – внутреннего связывающего камня. А чтобы сделать это, придется собрать ключи с остальных трех камней.$b$bЭти камни охраняют стражи, но если у тебя хватит ума или удачи, тебе удастся найти возможность справиться с ними.','Соберите огненный ключ, резной ключ и громовой ключ с западного, восточного и внешнего связывающих камней.','Это внутренний связывающий камень. Он самый большой из связывающих камней и должен быть открыт первым, чтобы появилась возможность открыть остальные.','Отправляйтесь к внутреннему связывающему камню во Внутреннем Круге Обуздания, что на Нагорье Арати.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Связывающие камни',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Четыре связывающих камня разбросаны по Нагорью Арати. Эти камни пригвоздили меня к земле.$b$bРазрушить оковы можно, сняв замок с самого мощного из них – внутреннего связывающего камня. А чтобы сделать это, придется собрать ключи с остальных трех камней.$b$bЭти камни охраняют стражи, но если у тебя хватит ума или удачи, тебе удастся найти возможность справиться с ними.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите огненный ключ, резной ключ и громовой ключ с западного, восточного и внешнего связывающих камней.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Это внутренний связывающий камень. Он самый большой из связывающих камней и должен быть открыт первым, чтобы появилась возможность открыть остальные.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отправляйтесь к внутреннему связывающему камню во Внутреннем Круге Обуздания, что на Нагорье Арати.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26042,'Разбить краеугольный камень','Открыв камни Обета, ты $gосвободил:освободила; меня от большей части моих оков, но еще кое-что удерживает меня. Это краеугольный камень, который ты видишь среди других камней круга. А ключ от него держит при себе один из моих пленителей, каменный страж Фозрук.$b$bОтбери у Фозрука этот ключ, который каменные стражи называют Жезлом Порядка, и открой им краеугольный камень.$b$b$n, ты так много $gсделал:сделала;, чтобы мне помочь... Еще немного... и моя благодарность не будет знать границ!','Заберите у Фозрука Жезл Порядка.','Вы вставляете жезл в краеугольный камень. И чувствуете, как земля дрожит под ногами…','Краеугольный камень заряжен сильнейшей геомантической энергией.','Вернитесь к краеугольному камню у Внутреннего Круга Обуздания, что на Нагорье Арати.','Заберите Жезл Порядка!','Фозрук') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разбить краеугольный камень',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Открыв камни Обета, ты $gосвободил:освободила; меня от большей части моих оков, но еще кое-что удерживает меня. Это краеугольный камень, который ты видишь среди других камней круга. А ключ от него держит при себе один из моих пленителей, каменный страж Фозрук.$b$bОтбери у Фозрука этот ключ, который каменные стражи называют Жезлом Порядка, и открой им краеугольный камень.$b$b$n, ты так много $gсделал:сделала;, чтобы мне помочь... Еще немного... и моя благодарность не будет знать границ!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заберите у Фозрука Жезл Порядка.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы вставляете жезл в краеугольный камень. И чувствуете, как земля дрожит под ногами…',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Краеугольный камень заряжен сильнейшей геомантической энергией.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к краеугольному камню у Внутреннего Круга Обуздания, что на Нагорье Арати.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Заберите Жезл Порядка!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Фозрук',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26043,'Берегись Рифогрыза!','По приказу властителя Кром\'гара купание в Скалистом озере ЗАПРЕЩЕНО!$B$BЗлобная тварь, известная как Рифогрыз, превратила озеро в смертельную ловушку. Тот, кто разделается с Рифогрызом, должен забрать его огромный зуб и прийти к главе шпионов Анаре для получения награды.','Убейте Рифогрыза и заберите огромный зуб Рифогрыза.','Орда воистину велика!','Чего ты хочешь?','Принесите огромный зуб Рифогрыза главе шпионов Анаре в крепость Кром\'гар в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Берегись Рифогрыза!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','По приказу властителя Кром\'гара купание в Скалистом озере ЗАПРЕЩЕНО!$B$BЗлобная тварь, известная как Рифогрыз, превратила озеро в смертельную ловушку. Тот, кто разделается с Рифогрызом, должен забрать его огромный зуб и прийти к главе шпионов Анаре для получения награды.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Рифогрыза и заберите огромный зуб Рифогрыза.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Орда воистину велика!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Чего ты хочешь?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите огромный зуб Рифогрыза главе шпионов Анаре в крепость Кром\'гар в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (26044,'Ну, и где детали?','Ну… понимаешь… все просто… ЭТА ПЕЩЕРА КИШИТ БЕЗДУШНЫМИ МАШИНАМИ-УБИЙЦАМИ!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ну, и где детали?',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну… понимаешь… все просто… ЭТА ПЕЩЕРА КИШИТ БЕЗДУШНЫМИ МАШИНАМИ-УБИЙЦАМИ!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26045,'Где-то тут были запчасти...','Никак не могу выбрать из двух зол: подохнуть тут, как все остальные, или умереть в крепости Кром\'гар, когда властитель Кром\'гар узнает, что мы потеряли шахту. Есть и третий вариант – не сделать ни того, ни другого. Посмотрим, что выйдет.$B$BТебе нужны запчасти? Их тут полно, они по всей шахте разбросаны. Надо просто их собрать.$B$BУдачи! Может, если ты соберешь эти запчасти, нам не страшно будет показаться в крепости Кром\'гар.','Соберите 10 запчастей.','Чтоб меня! Тебе удалось и запчасти собрать, и в живых остаться! И почему ты еще не генерал?','Как идет охота за запчастями?','Вернитесь к сержанту Донтрагу в Глубокие Плёсы в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Где-то тут были запчасти...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Никак не могу выбрать из двух зол: подохнуть тут, как все остальные, или умереть в крепости Кром\'гар, когда властитель Кром\'гар узнает, что мы потеряли шахту. Есть и третий вариант – не сделать ни того, ни другого. Посмотрим, что выйдет.$B$BТебе нужны запчасти? Их тут полно, они по всей шахте разбросаны. Надо просто их собрать.$B$BУдачи! Может, если ты соберешь эти запчасти, нам не страшно будет показаться в крепости Кром\'гар.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 запчастей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Чтоб меня! Тебе удалось и запчасти собрать, и в живых остаться! И почему ты еще не генерал?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как идет охота за запчастями?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к сержанту Донтрагу в Глубокие Плёсы в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26046,'Между молотом и наковальней','Донтраг объяснит лучше, чем я. Но суть в том, что мы находимся между молотом и наковальней. Тут мы ничего не сможем сделать, потому что нам грозит смерть, а вернуться в лагерь мы не можем, потому что нам грозит смерть, понимаешь?$B$BВот если бы мы объединили усилия, может, что-нибудь из этого и вышло бы. Может, начнешь с истребления элементалей, которые уничтожили все этой шахте, а?','Убейте 12 бушующих духов земли.','Запчасти собрали, элементалей убили, батраков спасли… Все правильно сделали! Не зря нас так хвалили!','Вернитесь к разведчику Утвочу в Глубокие Плёсы в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Между молотом и наковальней',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Донтраг объяснит лучше, чем я. Но суть в том, что мы находимся между молотом и наковальней. Тут мы ничего не сможем сделать, потому что нам грозит смерть, а вернуться в лагерь мы не можем, потому что нам грозит смерть, понимаешь?$B$BВот если бы мы объединили усилия, может, что-нибудь из этого и вышло бы. Может, начнешь с истребления элементалей, которые уничтожили все этой шахте, а?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 бушующих духов земли.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Запчасти собрали, элементалей убили, батраков спасли… Все правильно сделали! Не зря нас так хвалили!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к разведчику Утвочу в Глубокие Плёсы в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26047,'Батраки – они такие...','Эти двое БЕС-ПО-ЛЕЗ-НЫ! Когда они только прибыли, я думал, что мы спасены. Как бы не так! Вместо того чтобы нас спасать, Донтраг и Утвоч глянули разок на шахту и придумали какой-то идиотский план, в котором главное – стоять тут... пока не сдохнем, видимо.$B$BНо ты, вроде, поумнее их выглядишь. Может, ты поможешь? У меня тут куча батраков перепугалась до потери пульса и разбежалась по Глубоким плёсам. Найди их и спаси!','Спасите 10 испуганных батраков.','Я знал, что ты справишься! Если бы на то была моя воля, ты был бы уже легионером!','Вернитесь к взрынженеру Айгору в Глубокие Плёсы в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Батраки – они такие...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти двое БЕС-ПО-ЛЕЗ-НЫ! Когда они только прибыли, я думал, что мы спасены. Как бы не так! Вместо того чтобы нас спасать, Донтраг и Утвоч глянули разок на шахту и придумали какой-то идиотский план, в котором главное – стоять тут... пока не сдохнем, видимо.$B$BНо ты, вроде, поумнее их выглядишь. Может, ты поможешь? У меня тут куча батраков перепугалась до потери пульса и разбежалась по Глубоким плёсам. Найди их и спаси!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Спасите 10 испуганных батраков.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я знал, что ты справишься! Если бы на то была моя воля, ты был бы уже легионером!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к взрынженеру Айгору в Глубокие Плёсы в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (26048,'Запчасти сюда!','Уф, ну и работенка! Я и не думал, что мы справимся, $n. А теперь надо отнести эти запчасти взрынженеру Бомбиглотc. Кажется, я слышу жужжание гномских ветролетов. Нельзя терять ни минуты!','Доставьте ящик с запчастями взрынженеру Бомбиглотc в крепость Кром\'гар в Когтистых горах.','Как раз вовремя! Ветролетов все больше. Скоро они нападут!','Где мои запчасти?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Запчасти сюда!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Уф, ну и работенка! Я и не думал, что мы справимся, $n. А теперь надо отнести эти запчасти взрынженеру Бомбиглотc. Кажется, я слышу жужжание гномских ветролетов. Нельзя терять ни минуты!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте ящик с запчастями взрынженеру Бомбиглотc в крепость Кром\'гар в Когтистых горах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Как раз вовремя! Ветролетов все больше. Скоро они нападут!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Где мои запчасти?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26049,'Освобожденная принцесса','Мизраэль – вовсе не безобидная плененная принцесса. Она обладает смертоносной силой, и великаны имели все основания, чтобы приковать ее здесь. Боюсь, что тебя надули.$b$bПо словам Геррика, тебе нужно призвать ее к кристаллам Мизраэль, при помощи которых ты в первый раз $gразговаривал:разговаривала; с ней. Победи ее, забери ее мистические оковы и присоедини их к кристаллам. Вот свиток, который тебе пригодится. Береги его, чтобы его достать, я лишился нескольких зубов. Удачи тебе, $n.','Призовите к кристаллам Мизраэль и победите ее.','Когда мистические оковы помещены вокруг кристаллов, откуда-то из глубины раздается нечеловеческий вой, переходящий в рычание.$B$BКристаллы Мизраэль больше не излучают тепла и ощущения безопасности, как это было раньше. Теперь в их пульсации чувствуется открытая угроза... как будто существо внизу, под ними, исходит злобой, направленной на поверхность.','Сейчас кристаллы Мизраэль необычно тихие.','Вернитесь к кристаллам Мизраэль на Нагорье Арати.','Освободи ее… и уничтожь.','Мизраэль') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Освобожденная принцесса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мизраэль – вовсе не безобидная плененная принцесса. Она обладает смертоносной силой, и великаны имели все основания, чтобы приковать ее здесь. Боюсь, что тебя надули.$b$bПо словам Геррика, тебе нужно призвать ее к кристаллам Мизраэль, при помощи которых ты в первый раз $gразговаривал:разговаривала; с ней. Победи ее, забери ее мистические оковы и присоедини их к кристаллам. Вот свиток, который тебе пригодится. Береги его, чтобы его достать, я лишился нескольких зубов. Удачи тебе, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Призовите к кристаллам Мизраэль и победите ее.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Когда мистические оковы помещены вокруг кристаллов, откуда-то из глубины раздается нечеловеческий вой, переходящий в рычание.$B$BКристаллы Мизраэль больше не излучают тепла и ощущения безопасности, как это было раньше. Теперь в их пульсации чувствуется открытая угроза... как будто существо внизу, под ними, исходит злобой, направленной на поверхность.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Сейчас кристаллы Мизраэль необычно тихие.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к кристаллам Мизраэль на Нагорье Арати.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Освободи ее… и уничтожь.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Мизраэль',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`) VALUES (26050,'Хитрые очки','Теперь, когда мы настоящие пираты Черноводья, мы должны помочь мистеру О\'Брину разыскать пропавшее эльфийское сокровище.$b$bНайти драгоценные камни в море без посторонней помощи почти невозможно. Доктор сконструировал специальные очки, которые должны помочь. Ему нужно зарядить эти очки энергией, извлеченной из заколдованного камня в пещере, расположенной выше по холму.$b$bНо эта пещера проклята! Когда мы подошли к ней, на нас напали. Защити меня, и тогда я смогу вытянуть энергию из камня и направить ее в очки.','Проводите профессора Физзлторпа в пещеру и обратно.','Защитите профессора Физзлторпа') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хитрые очки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда мы настоящие пираты Черноводья, мы должны помочь мистеру О\'Брину разыскать пропавшее эльфийское сокровище.$b$bНайти драгоценные камни в море без посторонней помощи почти невозможно. Доктор сконструировал специальные очки, которые должны помочь. Ему нужно зарядить эти очки энергией, извлеченной из заколдованного камня в пещере, расположенной выше по холму.$b$bНо эта пещера проклята! Когда мы подошли к ней, на нас напали. Защити меня, и тогда я смогу вытянуть энергию из камня и направить ее в очки.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проводите профессора Физзлторпа в пещеру и обратно.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Защитите профессора Физзлторпа',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26051,'Затонувшее сокровище','Сокровища так долго лежали на дне моря, что покрылись известковым налетом, превратившись в большой камень. Но сила, влитая в эти очки, позволит тебе легко определить их местонахождение.$b$bМаленькая гномская хитрость делает большие дела!$b$bВозьми эти очки Ловца сокровищ, $n, посмотри, может, тебе удастся собрать какие-то из утерянных сокровищ для капитана О\'Брина.$b$bЯ бы и сам поплыл туда, но... гм... ну, у меня есть серьезные научные задачи, требующие срочного решения на надежной, сухой земле... да... вот.','Доктор Драксельмер в бухте Фальдира просит вас собрать 10 эльфийских самоцветов и после этого вернуть ему очки Ловца сокровищ.','Как очки? Все было в порядке? Если нужно, их можно настроить.$B$BАх, да, и не забудь вернуть мне эти очки, когда закончишь. Уверен, что капитану О\'Брину они еще не раз пригодятся.','Вернитесь к доктору Драксельмеру в Бухту Фальдира на Нагорье Арати.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Затонувшее сокровище',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сокровища так долго лежали на дне моря, что покрылись известковым налетом, превратившись в большой камень. Но сила, влитая в эти очки, позволит тебе легко определить их местонахождение.$b$bМаленькая гномская хитрость делает большие дела!$b$bВозьми эти очки Ловца сокровищ, $n, посмотри, может, тебе удастся собрать какие-то из утерянных сокровищ для капитана О\'Брина.$b$bЯ бы и сам поплыл туда, но... гм... ну, у меня есть серьезные научные задачи, требующие срочного решения на надежной, сухой земле... да... вот.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доктор Драксельмер в бухте Фальдира просит вас собрать 10 эльфийских самоцветов и после этого вернуть ему очки Ловца сокровищ.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как очки? Все было в порядке? Если нужно, их можно настроить.$B$BАх, да, и не забудь вернуть мне эти очки, когда закончишь. Уверен, что капитану О\'Брину они еще не раз пригодятся.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к доктору Драксельмеру в Бухту Фальдира на Нагорье Арати.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (26052,'Разговор с Мурашом','Не будем заставлять капитана О\'Брина ждать. Он захочет первым увидеть эти драгоценности. В конце концов, для того мы и здесь!$b$bЧерез несколько недель сотрудничества с этими пиратами мы с профессором отлично поняли, что когда мы придерживаем их сокровища, на нашем здоровье это сказывается самым пагубным образом.$b$bВот, $n, отнеси все это О\'Брину.','Так, значит, малютки-гномы в конце концов оказались полезными? Я знал, что мы не напрасно держим этих коротышек!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разговор с Мурашом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не будем заставлять капитана О\'Брина ждать. Он захочет первым увидеть эти драгоценности. В конце концов, для того мы и здесь!$b$bЧерез несколько недель сотрудничества с этими пиратами мы с профессором отлично поняли, что когда мы придерживаем их сокровища, на нашем здоровье это сказывается самым пагубным образом.$b$bВот, $n, отнеси все это О\'Брину.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так, значит, малютки-гномы в конце концов оказались полезными? Я знал, что мы не напрасно держим этих коротышек!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26053,'Очистить нагорье','Ни одна угроза здесь не останется незамеченной. Если нам нужно защитить земли, где правит Темная Госпожа, значит, мы пройдем их пядь за пядью, пока не уничтожим все живое.$b$bК северо-востоку отсюда, в двух шагах от этого лагеря есть холм, где живут огры из клана Тяжелого Кулака. Нужно истребить их всех до единого, |3-6($c).$b$bОни нам мешают. Будь $gтвердым и безжалостным:твердой и безжалостной;.','Убейте 8 огров из клана Тяжелого Кулака и 10 головорезов из клана Тяжелого Кулака.','Отлично! Нашествие Отрекшихся продолжается.','Вернитесь к ловчей Маудрии в Удел Галена, что на Нагорье Арати.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Очистить нагорье',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ни одна угроза здесь не останется незамеченной. Если нам нужно защитить земли, где правит Темная Госпожа, значит, мы пройдем их пядь за пядью, пока не уничтожим все живое.$b$bК северо-востоку отсюда, в двух шагах от этого лагеря есть холм, где живут огры из клана Тяжелого Кулака. Нужно истребить их всех до единого, |3-6($c).$b$bОни нам мешают. Будь $gтвердым и безжалостным:твердой и безжалостной;.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 огров из клана Тяжелого Кулака и 10 головорезов из клана Тяжелого Кулака.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! Нашествие Отрекшихся продолжается.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ловчей Маудрии в Удел Галена, что на Нагорье Арати.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26054,'Что-то они там мутят','Так тролли из племени Песчаной Бури работают заодно с культом Сумеречного Молота?!$B$BЛадно. Я не позволю этой вонючей ведьме посылать чудовищ в МОЙ город.$B$BСмельчаки, за мной! Мы обагрим песок кровью этих гадов и станем победителями. А когда вернемся, расскажи генералу Маркусу Джонатану обо всем, что здесь произошло. Сам-то я буду занят – кто-то должен присматривать за возвращением горожан, ремонтными работами и прочим.','Убейте Кай\'жу Газ\'риллу и поставьте об этом в известность генерала Маркуса Джонатана в Штормграде.','Сообщите генералу Маркусу Джонатану в Штормграде о смерти Кай\'жу Газ\'риллы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Что-то они там мутят',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Так тролли из племени Песчаной Бури работают заодно с культом Сумеречного Молота?!$B$BЛадно. Я не позволю этой вонючей ведьме посылать чудовищ в МОЙ город.$B$BСмельчаки, за мной! Мы обагрим песок кровью этих гадов и станем победителями. А когда вернемся, расскажи генералу Маркусу Джонатану обо всем, что здесь произошло. Сам-то я буду занят – кто-то должен присматривать за возвращением горожан, ремонтными работами и прочим.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Кай\'жу Газ\'риллу и поставьте об этом в известность генерала Маркуса Джонатана в Штормграде.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Сообщите генералу Маркусу Джонатану в Штормграде о смерти Кай\'жу Газ\'риллы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26055,'Затонувшие печали','Ох, жизнь – ужасная штука. Я должен бы покоиться на дне моря, а не сидеть здесь у огня, наслаждаясь свежим воздухом.$B$BКоманда не жалела сил, чтобы спасти мою прекрасную "Девичью Блажь". Да упокоятся мои ребята в мире, пусть будут благословенны их сердца.$B$BО\'Брину удалось выбраться на берег, а нам не повезло. Море просто опрокинулось на нас, клянусь тебе.$b$bВот мы плывем – и вдруг следующая волна обрушивается на нас. А эти твари! Они убили всех, кто остался в живых. Подлое нагово отродье. Я потерял сознание и пришел в себя уже здесь.$b$bЯ жажду их смерти.','Капитан Стальные Нервы из бухты Фальдира хочет, чтобы вы убили 10 налетчиков и 3 колдуний из клана Пронзающего Гребня.','Вернитесь к капитану Стальные Нервы в Бухту Фальдира, что на Нагорье Арати.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Затонувшие печали',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ох, жизнь – ужасная штука. Я должен бы покоиться на дне моря, а не сидеть здесь у огня, наслаждаясь свежим воздухом.$B$BКоманда не жалела сил, чтобы спасти мою прекрасную "Девичью Блажь". Да упокоятся мои ребята в мире, пусть будут благословенны их сердца.$B$BО\'Брину удалось выбраться на берег, а нам не повезло. Море просто опрокинулось на нас, клянусь тебе.$b$bВот мы плывем – и вдруг следующая волна обрушивается на нас. А эти твари! Они убили всех, кто остался в живых. Подлое нагово отродье. Я потерял сознание и пришел в себя уже здесь.$b$bЯ жажду их смерти.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Капитан Стальные Нервы из бухты Фальдира хочет, чтобы вы убили 10 налетчиков и 3 колдуний из клана Пронзающего Гребня.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Стальные Нервы в Бухту Фальдира, что на Нагорье Арати.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26056,'Говорящая с волнами','Говорящая с волнами Валорен из Служителей Земли уплыла в Глубины Кошмаров, что на северо-востоке, и с тех пор ее больше никто не видел. Боюсь, как бы с ней беды не приключилось...$B$BОтправляйся туда и попробуй ее разыскать.','Разыщите говорящую с волнами Валорен в Глубинах Кошмаров в Вайш\'ире.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Говорящая с волнами',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Говорящая с волнами Валорен из Служителей Земли уплыла в Глубины Кошмаров, что на северо-востоке, и с тех пор ее больше никто не видел. Боюсь, как бы с ней беды не приключилось...$B$BОтправляйся туда и попробуй ее разыскать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите говорящую с волнами Валорен в Глубинах Кошмаров в Вайш\'ире.',`objectives_loc8`);
