INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (26057,'Как я рада, что ты пришел!') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Как я рада, что ты пришел!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26058,'Защита крепости Кром\'гар','Времени нет! Они идут! Становись к пушке и сбивай гномов с неба! Если на эту бомбу придется много попаданий, она взорвется вместе с нами!$B$BЗащищай базу, $n! На тебя вся надежда!$B$BЕсли мы справимся, отправишься с донесением к властителю Кром\'гару лично.','Уничтожьте 15 гномских ветролетов или бомбардировщиков и 25 командиров звена гномов.','Удивительная храбрость! Только благодаря тебе, сержант – вернее, легионер – лагерь спасен! Лок\'тар!','Доложите о произошедшем властителю Кром\'гару в крепости Кром\'гар в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Защита крепости Кром\'гар',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Времени нет! Они идут! Становись к пушке и сбивай гномов с неба! Если на эту бомбу придется много попаданий, она взорвется вместе с нами!$B$BЗащищай базу, $n! На тебя вся надежда!$B$BЕсли мы справимся, отправишься с донесением к властителю Кром\'гару лично.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 15 гномских ветролетов или бомбардировщиков и 25 командиров звена гномов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Удивительная храбрость! Только благодаря тебе, сержант – вернее, легионер – лагерь спасен! Лок\'тар!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доложите о произошедшем властителю Кром\'гару в крепости Кром\'гар в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (26059,'Глаза и уши: Малака\'джин','Застава Чести потеряна. Власть над Степями разлетелась на куски вместе с этой землей. Я получаю сведения о том, что в результате совместной атаки Альянса и Зловещего Тотема мы можем потерять и Малака\'джин. Если Малака\'джин падет, половина Когтистых гор падет с ним!$B$BТы отличный солдат Орды. Станешь моими глазами и ушами в Малака\'джине?$B$BЗнахарь Джин\'Зил ждет тебя.$B$BМалака\'джин находится далеко на юге.','Вижу, Кром\'гар прислал самую что ни на есть элиту!$B$BЭто хорошо, у нас много дел. Гнусный Альянс вступил в союз с кланом Зловещего Тотема. Теперь приходится отбивать атаки сразу с двух сторон.$B$BМы рассеяны по Долине Высокого леса и скоро падем под натиском объединенных сил врагов. Есть только одна надежда: ВУДУ!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Глаза и уши: Малака\'джин',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Застава Чести потеряна. Власть над Степями разлетелась на куски вместе с этой землей. Я получаю сведения о том, что в результате совместной атаки Альянса и Зловещего Тотема мы можем потерять и Малака\'джин. Если Малака\'джин падет, половина Когтистых гор падет с ним!$B$BТы отличный солдат Орды. Станешь моими глазами и ушами в Малака\'джине?$B$BЗнахарь Джин\'Зил ждет тебя.$B$BМалака\'джин находится далеко на юге.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вижу, Кром\'гар прислал самую что ни на есть элиту!$B$BЭто хорошо, у нас много дел. Гнусный Альянс вступил в союз с кланом Зловещего Тотема. Теперь приходится отбивать атаки сразу с двух сторон.$B$BМы рассеяны по Долине Высокого леса и скоро падем под натиском объединенных сил врагов. Есть только одна надежда: ВУДУ!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26060,'Вуду: сердце скалозавра','Добудьте сердце скалозавра.','Прекрасно! Как только у меня окажутся все компоненты, я смешаю их и призову силу вуду! Горе нашим врагам!','Мне нужно сердце скалозавра!','Вернитесь к знахарю Джин\'Зилу в Малака\'джин в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вуду: сердце скалозавра',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте сердце скалозавра.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно! Как только у меня окажутся все компоненты, я смешаю их и призову силу вуду! Горе нашим врагам!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мне нужно сердце скалозавра!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к знахарю Джин\'Зилу в Малака\'джин в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26061,'Вуду: бараний рог','Мне понадобятся некоторые компоненты, чтобы заняться черной магией. Принеси мне рога баранов Когтистых гор, $n! Без них у нас ничего не получится!','Добудьте 6 рогов баранов Когтистых гор.','Прекрасно! Как только у меня окажутся все компоненты, я смешаю их и призову силу вуду! Горе нашим врагам!','Мне нужны рога баранов Когтистых гор!','Вернитесь к знахарю Джин\'Зилу в Малака\'джин в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вуду: бараний рог',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне понадобятся некоторые компоненты, чтобы заняться черной магией. Принеси мне рога баранов Когтистых гор, $n! Без них у нас ничего не получится!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 6 рогов баранов Когтистых гор.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно! Как только у меня окажутся все компоненты, я смешаю их и призову силу вуду! Горе нашим врагам!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мне нужны рога баранов Когтистых гор!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к знахарю Джин\'Зилу в Малака\'джин в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26062,'Вуду: кристалл резонита','Последняя составляющая для ритуала вуду – это особый кристалл, который называется резонитом. Его можно найти только в пещерах Камнепадов, что к западу отсюда. Берегись кобольдов! Они будут защищать резонит до последней капли крови!','Добудьте 8 кристаллов резонита.','Наконец-то! Теперь я создам чары, которые удержат заклинание вуду!','Мне нужны кристаллы резонита!','Вернитесь к знахарю Джин\'Зилу в Малака\'джин в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вуду: кристалл резонита',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Последняя составляющая для ритуала вуду – это особый кристалл, который называется резонитом. Его можно найти только в пещерах Камнепадов, что к западу отсюда. Берегись кобольдов! Они будут защищать резонит до последней капли крови!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 8 кристаллов резонита.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Наконец-то! Теперь я создам чары, которые удержат заклинание вуду!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мне нужны кристаллы резонита!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к знахарю Джин\'Зилу в Малака\'джин в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26063,'Королеву играет свита','<Дарн фыркает.>$B$BХмм!$B$BВсе не так, как должно быть. Дарн недоволен. Подругу Дарна убили пауки, в Паучьей лощине. Дарн требует мести!$B$BПоможешь Дарну? Убьешь королеву Силит и ее паучат? Ради Дарна? За подругу Дарна!$B$BПаучья лощина – к северо-западу отсюда вверх по тропе! Иди!','Убейте королеву Силит и любых 10 пауков в Паучьей лощине.','Дарн все еще не так уж счастлив, но Дарн наградит тебя за работу.','Вернитесь к Дарну Цепкохвату на Ордынскую насыпь в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Королеву играет свита',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Дарн фыркает.>$B$BХмм!$B$BВсе не так, как должно быть. Дарн недоволен. Подругу Дарна убили пауки, в Паучьей лощине. Дарн требует мести!$B$BПоможешь Дарну? Убьешь королеву Силит и ее паучат? Ради Дарна? За подругу Дарна!$B$BПаучья лощина – к северо-западу отсюда вверх по тропе! Иди!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте королеву Силит и любых 10 пауков в Паучьей лощине.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Дарн все еще не так уж счастлив, но Дарн наградит тебя за работу.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дарну Цепкохвату на Ордынскую насыпь в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26064,'Война с голодом','Войска хотят есть, $n. Поставки продовольствия прекратились, а еды у нас остается все меньше. Если ты достанешь мне продукты, я накормлю солдат до отвала.$B$BИди в лес к западу отсюда и поищи гнезда калимдорских орлов. Забери яйца из гнезд и принеси их мне.','Соберите 8 яиц калимдорских орлов.','Мне нужны яйца!','Вернитесь к Денни\'ке в Малака\'джин в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Война с голодом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Войска хотят есть, $n. Поставки продовольствия прекратились, а еды у нас остается все меньше. Если ты достанешь мне продукты, я накормлю солдат до отвала.$B$BИди в лес к западу отсюда и поищи гнезда калимдорских орлов. Забери яйца из гнезд и принеси их мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 яиц калимдорских орлов.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мне нужны яйца!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Денни\'ке в Малака\'джин в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26065,'Освободите Вил\'ле','Поднявшиеся из глубин щупальца ужаса удерживают бедное создание и не дают выбраться. Его надо спасти. Ты сможешь убить этих тварей, $n?$B$BОсвободишь Вил\'ле?$B$BВот, возьми мой тотем и поставь его рядом со щупальцами. От тотема исходит холод, а эти чудовища его не выносят. Они съежатся от холода, и тебе будет легче их уничтожить.','Уничтожьте все щупальца ужаса и освободите Вил\'ле.','Вернитесь к говорящей с волнами Валорен в Глубины Кошмаров в Вайш\'ире.','Освободите Вил\'ле','Вил\'ле') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Освободите Вил\'ле',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Поднявшиеся из глубин щупальца ужаса удерживают бедное создание и не дают выбраться. Его надо спасти. Ты сможешь убить этих тварей, $n?$B$BОсвободишь Вил\'ле?$B$BВот, возьми мой тотем и поставь его рядом со щупальцами. От тотема исходит холод, а эти чудовища его не выносят. Они съежатся от холода, и тебе будет легче их уничтожить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте все щупальца ужаса и освободите Вил\'ле.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к говорящей с волнами Валорен в Глубины Кошмаров в Вайш\'ире.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Освободите Вил\'ле',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Вил\'ле',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26066,'Подкрепление...','Кажется, наш запас здоровенных тупых орков, которых можно послать на врага, на исходе. Это плохо. Но есть у меня одна идея...$B$BВозьми этот хлыст и иди на запад, к пещере Камнепадов. В той пещере обосновались грязные кобольды. С помощью этого хлыста ты сможешь подчинить этих тварей, и они будут делать все, что нам надо.$B$BВозвращайся, когда наберешь целый отряд.','Используйте хлыст поработителя Дэво, чтобы поработить 6 кобольдов из племени Камнепадов.','В трудные времена отчаянная хитрость ничем не хуже отчаянной храбрости. Напустим на врагов стаю кобольдов – враг растеряется, а мы глядишь и победим!','Вернитесь к поработителю Дэво в Малака\'джин в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подкрепление...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кажется, наш запас здоровенных тупых орков, которых можно послать на врага, на исходе. Это плохо. Но есть у меня одна идея...$B$BВозьми этот хлыст и иди на запад, к пещере Камнепадов. В той пещере обосновались грязные кобольды. С помощью этого хлыста ты сможешь подчинить этих тварей, и они будут делать все, что нам надо.$B$BВозвращайся, когда наберешь целый отряд.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте хлыст поработителя Дэво, чтобы поработить 6 кобольдов из племени Камнепадов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','В трудные времена отчаянная хитрость ничем не хуже отчаянной храбрости. Напустим на врагов стаю кобольдов – враг растеряется, а мы глядишь и победим!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к поработителю Дэво в Малака\'джин в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26067,'Магия Джин\'Зила','Готово! Теперь надо проверить, что у нас получилось.$B$BИди на поле битвы в долину Высокого леса и испробуй мою вудуистскую палку на кром\'гарских мародерах, которые сражаются со Зловещим Тотемом. Магия вуду придаст им сил и поможет перебить врагов!$B$BПоторопись, $n!','Используйте вудуистскую палку Джин\'Зила, чтобы наслать на 12 кром\'гарских мародеров магию вуду.','Вернитесь к знахарю Джин\'Зилу в Малака\'джин в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Магия Джин\'Зила',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Готово! Теперь надо проверить, что у нас получилось.$B$BИди на поле битвы в долину Высокого леса и испробуй мою вудуистскую палку на кром\'гарских мародерах, которые сражаются со Зловещим Тотемом. Магия вуду придаст им сил и поможет перебить врагов!$B$BПоторопись, $n!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте вудуистскую палку Джин\'Зила, чтобы наслать на 12 кром\'гарских мародеров магию вуду.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к знахарю Джин\'Зилу в Малака\'джин в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (26068,'Кобольды, вперед!','Теперь мы командуем армией кобольдов Когтистых гор! Впечатляюще звучит! Ну, почти...$B$B<Дэво вздыхает.>$B$BЛагерь Альянса к северу отсюда охраняется очень бдительно. В него можно попасть только через место раскопок к северо-востоку отсюда. Возьми боевой рог кобольдов и иди с ним к месту раскопок. Заходи с востока, $n! Когда окажешься там, поверни на запад и иди, пока не достигнешь зоны, которую я обозначил на карте. Протруби в рог, чтобы натравить кобольдов на Альянс!','Используйте боевой рог кобольдов рядом со знаменем Орды на Месте раскопок, чтобы послать в бой армию кобольдов!','<Дэво смеется.>$B$BКакая смешная история! Кажется, от наших неожиданных союзников-кобольдов может быть польза!','Армия кобольдов начинает атаку!','Вернитесь к поработителю Дэво в Малака\'джин в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кобольды, вперед!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь мы командуем армией кобольдов Когтистых гор! Впечатляюще звучит! Ну, почти...$B$B<Дэво вздыхает.>$B$BЛагерь Альянса к северу отсюда охраняется очень бдительно. В него можно попасть только через место раскопок к северо-востоку отсюда. Возьми боевой рог кобольдов и иди с ним к месту раскопок. Заходи с востока, $n! Когда окажешься там, поверни на запад и иди, пока не достигнешь зоны, которую я обозначил на карте. Протруби в рог, чтобы натравить кобольдов на Альянс!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте боевой рог кобольдов рядом со знаменем Орды на Месте раскопок, чтобы послать в бой армию кобольдов!',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Дэво смеется.>$B$BКакая смешная история! Кажется, от наших неожиданных союзников-кобольдов может быть польза!',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Армия кобольдов начинает атаку!',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к поработителю Дэво в Малака\'джин в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (26069,'Нура Землепроходица') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нура Землепроходица',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26070,'Уничтожение скверны','Наши друзья из Служителей Земли обратились к нам за помощью. Похоже, в Жгучем провале завелись какие-то безликие демоны, которые оскверняют живую природу.$B$BЗаймешься оскверненными существами?','Уничтожьте несколько угрей-сокрушителей, глубоководных прилипал или ловцов провала – в общей сложности 8 тварей.','Вернитесь к капитану Тейлору на вершину Подводного выступа в Вайш\'ире.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уничтожение скверны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наши друзья из Служителей Земли обратились к нам за помощью. Похоже, в Жгучем провале завелись какие-то безликие демоны, которые оскверняют живую природу.$B$BЗаймешься оскверненными существами?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте несколько угрей-сокрушителей, глубоководных прилипал или ловцов провала – в общей сложности 8 тварей.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Тейлору на вершину Подводного выступа в Вайш\'ире.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26071,'Уничтожение скверны','Служители Земли, хотят, чтобы мы поубивали за них. В Жгучем провале завелись какие-то безликие демоны, которые оскверняют природу.$B$BОтправляйся туда и займись оскверненными существами.','Уничтожьте несколько угрей-сокрушителей, глубоководных прилипал или ловцов провала – в общей сложности 8 тварей.','Вернитесь к легионеру Назгриму на вершину Подводного выступа в Вайш\'ире.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уничтожение скверны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Служители Земли, хотят, чтобы мы поубивали за них. В Жгучем провале завелись какие-то безликие демоны, которые оскверняют природу.$B$BОтправляйся туда и займись оскверненными существами.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте несколько угрей-сокрушителей, глубоководных прилипал или ловцов провала – в общей сложности 8 тварей.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к легионеру Назгриму на вершину Подводного выступа в Вайш\'ире.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (26071,'Отлично сработано.$B$BТолько не слишком нос задирай, Бумагош. Самое трудное еще впереди.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично сработано.$B$BТолько не слишком нос задирай, Бумагош. Самое трудное еще впереди.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (26072,'Зарядка тотема','Бери мой тотем и отправляйся в Жгучий провал. Там зарядишь его энергией умирающих безликих. Тотем впитает их энергию и не даст вернуться туда, откуда они появились.$B$BКогда тотем полностью зарядится, возвращайся, и мы с его помощью выманим из глубин их предводителя.','Вернитесь к Эрунаку Говорящему с Камнем на вершину Подводного выступа в Вайш\'ире.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зарядка тотема',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Бери мой тотем и отправляйся в Жгучий провал. Там зарядишь его энергией умирающих безликих. Тотем впитает их энергию и не даст вернуться туда, откуда они появились.$B$BКогда тотем полностью зарядится, возвращайся, и мы с его помощью выманим из глубин их предводителя.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Эрунаку Говорящему с Камнем на вершину Подводного выступа в Вайш\'ире.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26073,'На южном фронте без перемен','Вернись теперь к властителю Кром\'гару, $n. Расскажи ему, как идут наши дела и что ты $gсделал:сделала; для того, чтобы Малака\'джин не пал.$B$BПрими благодарность от всех нас. Может статься, что когда-нибудь ты будешь править собственными владениями.','Поговорите с властителем Кром\'гаром в крепости Кром\'гар в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На южном фронте без перемен',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вернись теперь к властителю Кром\'гару, $n. Расскажи ему, как идут наши дела и что ты $gсделал:сделала; для того, чтобы Малака\'джин не пал.$B$BПрими благодарность от всех нас. Может статься, что когда-нибудь ты будешь править собственными владениями.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с властителем Кром\'гаром в крепости Кром\'гар в Когтистых горах.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26074,'Начало конца','$GГерой:Героиня;, у нас новая цель. Разведчики из долины Боевого Шрама донесли, что ночные эльфы создали оружие массового уничтожения и прячут его в древнем дереве. Нельзя дать им возможность использовать это оружие против нас.$B$BТебе придется сопровождать бомбу до илоразработок, чтобы ее там заправили, а потом на Плато Скалоступов, с которого мы и сбросим бомбу на врагов.$B$BИди, $n. Обязательно встреться с Джиббли Ракитом на илоразработках.','Доставьте кром\'гарский воздушный шар к илоразработкам в Когтистых горах.','Кром\'гар прислал лучшего из лучших! Тебе не о чем беспокоиться, герой. Мы в момент заправим шар. Не хочешь помочь, пока будешь ждать?','Встретьтесь с Джиббли Ракитом на илоразработках в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Начало конца',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$GГерой:Героиня;, у нас новая цель. Разведчики из долины Боевого Шрама донесли, что ночные эльфы создали оружие массового уничтожения и прячут его в древнем дереве. Нельзя дать им возможность использовать это оружие против нас.$B$BТебе придется сопровождать бомбу до илоразработок, чтобы ее там заправили, а потом на Плато Скалоступов, с которого мы и сбросим бомбу на врагов.$B$BИди, $n. Обязательно встреться с Джиббли Ракитом на илоразработках.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте кром\'гарский воздушный шар к илоразработкам в Когтистых горах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Кром\'гар прислал лучшего из лучших! Тебе не о чем беспокоиться, герой. Мы в момент заправим шар. Не хочешь помочь, пока будешь ждать?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Встретьтесь с Джиббли Ракитом на илоразработках в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26075,'Грязь по колено','У нас тут проблемка...$B$B<Джиббли показывает на большие куски фекалий, лежащие на полу.>$B$BИлоразработки построены рядом с гнездом виверн. С самого начала Илоразработки проектировались так, чтобы не тревожить этих тварей, – они, видишь ли, священные для тауренов и орков. А знаешь, что священно для меня? Чистые ноги, и чтоб их не приходилось отчищать от всякой дряни!$B$BМежду нами, надо бы избавиться от этих зверюг!','Убейте 6 величавых виверн любого вида.','Надеюсь, ни одна не выжила. Вряд ли я выдержу продолжение этого кошмара.','Вернитесь к Джиббли Ракиту на илоразработки в Когтистые горы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Грязь по колено',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У нас тут проблемка...$B$B<Джиббли показывает на большие куски фекалий, лежащие на полу.>$B$BИлоразработки построены рядом с гнездом виверн. С самого начала Илоразработки проектировались так, чтобы не тревожить этих тварей, – они, видишь ли, священные для тауренов и орков. А знаешь, что священно для меня? Чистые ноги, и чтоб их не приходилось отчищать от всякой дряни!$B$BМежду нами, надо бы избавиться от этих зверюг!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 6 величавых виверн любого вида.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Надеюсь, ни одна не выжила. Вряд ли я выдержу продолжение этого кошмара.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джиббли Ракиту на илоразработки в Когтистые горы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26076,'Шпионы-паразиты','У нас проблема, $n. Шпионы Альянса повсюду! Ты их не $gвидел:видела;? Это потому что они невидимые! Под прикрытием! Я знаю, что надо делать, но мне нужен помощник вроде тебя, чтобы отправиться туда и осуществить мой план.$B$BИспользуй газовую бомбу, чтобы шпионы проявились. Как только увидишь их, разделайся с ними.$B$BШпиона под прикрытием можно узнать по следу, который он оставляет в воздухе. Смотри внимательней!','Убейте 8 шпионов Альянса. Для разоблачения шпионов используйте газовую бомбу Джиббли.','А говорили, что я параноик! А я знал, что тут полно шпионов. Даже в нечистотах!','Вернитесь к Джиббли Ракиту на илоразработки в Когтистые горы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Шпионы-паразиты',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У нас проблема, $n. Шпионы Альянса повсюду! Ты их не $gвидел:видела;? Это потому что они невидимые! Под прикрытием! Я знаю, что надо делать, но мне нужен помощник вроде тебя, чтобы отправиться туда и осуществить мой план.$B$BИспользуй газовую бомбу, чтобы шпионы проявились. Как только увидишь их, разделайся с ними.$B$BШпиона под прикрытием можно узнать по следу, который он оставляет в воздухе. Смотри внимательней!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 шпионов Альянса. Для разоблачения шпионов используйте газовую бомбу Джиббли.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А говорили, что я параноик! А я знал, что тут полно шпионов. Даже в нечистотах!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джиббли Ракиту на илоразработки в Когтистые горы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26077,'Доставка до места назначения','Властитель Кром\'гар прислал приказ. Тебе надо сесть на кром\'гарский воздушный шар и доставить его на Плато Скалоступов. Оттуда надо сбросить груз на силы Альянса в долине Боевого Шрама.$B$BДавай, $n. Не надо заставлять Кром\'гара ждать.$B$BПоговори с генералом Гребо, когда прибудешь на место назначения. Он скажет, что тебе делать дальше.','Доставьте кром\'гарский воздушный шар на Плато Скалоступов в Когтистых горах.','Верховный вождь Скалоступ и его таурены пытаются предать Орду! Они говорят, что древнее дерево в самом сердце долины Боевого Шрама – это какая-то школа друидов. Они не желают понимать, что в военное время приходится прибегать к крайним мерам. Мои разведчики рассказали мне, что ночные эльфы прячут невероятно сильное оружие внутри этого дерева. С этим надо покончить!','Обратитесь к генералу Гребо на Плато Скалоступов в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Доставка до места назначения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Властитель Кром\'гар прислал приказ. Тебе надо сесть на кром\'гарский воздушный шар и доставить его на Плато Скалоступов. Оттуда надо сбросить груз на силы Альянса в долине Боевого Шрама.$B$BДавай, $n. Не надо заставлять Кром\'гара ждать.$B$BПоговори с генералом Гребо, когда прибудешь на место назначения. Он скажет, что тебе делать дальше.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте кром\'гарский воздушный шар на Плато Скалоступов в Когтистых горах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Верховный вождь Скалоступ и его таурены пытаются предать Орду! Они говорят, что древнее дерево в самом сердце долины Боевого Шрама – это какая-то школа друидов. Они не желают понимать, что в военное время приходится прибегать к крайним мерам. Мои разведчики рассказали мне, что ночные эльфы прячут невероятно сильное оружие внутри этого дерева. С этим надо покончить!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Обратитесь к генералу Гребо на Плато Скалоступов в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26078,'Потушить огонь','Атака Черного Железа застала нас врасплох. Их диверсантам удалось повредить большинство наших летательных аппаратов, паровых танков и припасов. У нас получилось поднять в воздух только несколько наших бомбардировщиков.$b$bВсе техники, рекруты и стражники, которых я могу выделить, пытаются отремонтировать остальные и сделать так, чтобы они могли взлететь. Пехота пока держится. Возьми это оборудование и помоги потушить горящие бомбардировщики.','Воспользуйтесь противопожарным оборудованием, чтобы потушить 6 пожаров на аэродроме Стальгорна.','Прекрасно! Мои ребята работают без остановки, чтобы наши ветролеты и паровые танки можно было использовать в бою.','Вернитесь к капитану форта Камнеломов на аэродром Стальгорна.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Потушить огонь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Атака Черного Железа застала нас врасплох. Их диверсантам удалось повредить большинство наших летательных аппаратов, паровых танков и припасов. У нас получилось поднять в воздух только несколько наших бомбардировщиков.$b$bВсе техники, рекруты и стражники, которых я могу выделить, пытаются отремонтировать остальные и сделать так, чтобы они могли взлететь. Пехота пока держится. Возьми это оборудование и помоги потушить горящие бомбардировщики.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь противопожарным оборудованием, чтобы потушить 6 пожаров на аэродроме Стальгорна.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно! Мои ребята работают без остановки, чтобы наши ветролеты и паровые танки можно было использовать в бою.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану форта Камнеломов на аэродром Стальгорна.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26079,'Разыскивается: Отто и лорд Соколиный Шлем','Принесите головы Отто и Соколиного Шлема капитану Ниалс в Опорный пункт.','Вернитесь к капитану Ниалс в Опорный пункт на Нагорье Арати.','У него хорошая защита. Будь осторожнее.','Лорд Соколиный Шлем') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разыскивается: Отто и лорд Соколиный Шлем',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите головы Отто и Соколиного Шлема капитану Ниалс в Опорный пункт.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Ниалс в Опорный пункт на Нагорье Арати.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','У него хорошая защита. Будь осторожнее.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Лорд Соколиный Шлем',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (26080,'Последняя услуга','$n, мне придется попросить тебя отнести это капитану Гловаалю. В таком состоянии я буду неделю добираться до Темной пещеры, а времени у нас совсем нет.','Отнесите ройпоевскую рыбу в бумаге капитану Гловаалю в Темную пещеру.','Понятно. Да, помнится мне... Хамфри и Оскар всегда были неважными пловцами.$B$BЧто ж, эти сведения нам пригодятся, а от вида рыбы аж слюнки текут. Если увидишь мистера Ройпоя раньше меня, передай ему мою благодарность.','Тебе удалось найти Оскара и Хамфри?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Последняя услуга',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, мне придется попросить тебя отнести это капитану Гловаалю. В таком состоянии я буду неделю добираться до Темной пещеры, а времени у нас совсем нет.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите ройпоевскую рыбу в бумаге капитану Гловаалю в Темную пещеру.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Понятно. Да, помнится мне... Хамфри и Оскар всегда были неважными пловцами.$B$BЧто ж, эти сведения нам пригодятся, а от вида рыбы аж слюнки текут. Если увидишь мистера Ройпоя раньше меня, передай ему мою благодарность.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось найти Оскара и Хамфри?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26081,'Награда Алины','Здесь заканчивается история Трол\'калара. Он будет орудием, во имя Темной Госпожи несущим смерть всему живому.$b$bТеперь оставь меня, $n. Мое дело – хранить этот клинок. Расскажи Алине о своей победе, уверен, она наградит тебя.','Поговорите с темным следопытом Алиной.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Награда Алины',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Здесь заканчивается история Трол\'калара. Он будет орудием, во имя Темной Госпожи несущим смерть всему живому.$b$bТеперь оставь меня, $n. Мое дело – хранить этот клинок. Расскажи Алине о своей победе, уверен, она наградит тебя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с темным следопытом Алиной.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (26082,'К Боевому Шраму!','Пусть этот старый дурень затевает расследование. Он уверял меня, что непременно докажет, будто у ночных эльфов нет оружия массового поражения.$B$BА пока мы ждем его доказательства, ты поможешь моей армии в долине. Мы там подготовили много осадных танков, и разрушители наши только и ждут сигнала к бою.$B$BСадись в лифт, поезжай вниз, в подвал заставы, и выбери там себе кром\'гарского разрушителя. Ну а потом с его помощью задай жару нашим врагам в долине Боевого Шрама.','Обратитесь к генералу Гребо на Плато Скалоступов в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','К Боевому Шраму!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пусть этот старый дурень затевает расследование. Он уверял меня, что непременно докажет, будто у ночных эльфов нет оружия массового поражения.$B$BА пока мы ждем его доказательства, ты поможешь моей армии в долине. Мы там подготовили много осадных танков, и разрушители наши только и ждут сигнала к бою.$B$BСадись в лифт, поезжай вниз, в подвал заставы, и выбери там себе кром\'гарского разрушителя. Ну а потом с его помощью задай жару нашим врагам в долине Боевого Шрама.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Обратитесь к генералу Гребо на Плато Скалоступов в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26083,'Привет, Лоло','Потрохаря прислали следить. Смотреть на разные вещи. Большое приключение!$b$bПотрохарь нашел секретное пиратское судно. Все пираты пугаться, бежать. Но огр Лоло не бежать. Лоло дружить с Потрохарем!$b$bПотрохарь должен идти, но скучать по Лоло. Передай ему привет от Потрохаря.','Найдите дозорного Лоло в бухте Фальдира.','Ты друг Потрохаря! Он чудной огр. Забавно пахнет.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Привет, Лоло',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Потрохаря прислали следить. Смотреть на разные вещи. Большое приключение!$b$bПотрохарь нашел секретное пиратское судно. Все пираты пугаться, бежать. Но огр Лоло не бежать. Лоло дружить с Потрохарем!$b$bПотрохарь должен идти, но скучать по Лоло. Передай ему привет от Потрохаря.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите дозорного Лоло в бухте Фальдира.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты друг Потрохаря! Он чудной огр. Забавно пахнет.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (26084,'Павший Молот','Ты $gсослужил:сослужила; нам отличную службу, $n. Теперь, когда мы заявили здесь о себе, следующий этап завоевания – дело нескольких месяцев, а вовсе не минут.$b$bНам еще многое нужно сделать, и я избавлю тебя от томительного ожидания, когда здесь появятся наши укрепления. Отправляйся на восток, в Павший Молот. Твоя помощь наверняка пригодится тамошним оркам.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Павший Молот',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gсослужил:сослужила; нам отличную службу, $n. Теперь, когда мы заявили здесь о себе, следующий этап завоевания – дело нескольких месяцев, а вовсе не минут.$b$bНам еще многое нужно сделать, и я избавлю тебя от томительного ожидания, когда здесь появятся наши укрепления. Отправляйся на восток, в Павший Молот. Твоя помощь наверняка пригодится тамошним оркам.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26085,'Сплочение защитников','Установите 8 знамен Стальгорна над сугробами из рыхлого снега в разных частях аэродрома Стальгорна.','Защитники воспряли духом и с новыми силами и смелостью противостоят захватчикам Черного Железа. Аэродром не падет на наших глазах!','Вернитесь к капитану Камнеломов на аэродром Стальгорна.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сплочение защитников',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Установите 8 знамен Стальгорна над сугробами из рыхлого снега в разных частях аэродрома Стальгорна.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Защитники воспряли духом и с новыми силами и смелостью противостоят захватчикам Черного Железа. Аэродром не падет на наших глазах!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Камнеломов на аэродром Стальгорна.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26086,'Орако','<Капитан Верн смотрит на часы.>$B$BКуда запропастился этот охотник? Неделю назад отправил Орако на разведку в Затемненную впадину! Я, конечно, не против и вовсе от него избавиться, но мне нужен отчет.$B$BКак тебя зовут? $n? Может, ты его отыщешь? Немного странно отправлять |3-3($c) на поиски охотника, но у меня нет другого выбора.','Поговорите с Орако в Затемненной впадине в Вайш\'ире.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Орако',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Капитан Верн смотрит на часы.>$B$BКуда запропастился этот охотник? Неделю назад отправил Орако на разведку в Затемненную впадину! Я, конечно, не против и вовсе от него избавиться, но мне нужен отчет.$B$BКак тебя зовут? $n? Может, ты его отыщешь? Немного странно отправлять |3-3($c) на поиски охотника, но у меня нет другого выбора.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Орако в Затемненной впадине в Вайш\'ире.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (26086,'Эх! С этими проклятыми рыбами не справиться!$B$B<Орако смотрит на вас.>$B$BМоего волка сожрала какая-то рыбина, и я не вернусь, пока ее не отыщу.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Эх! С этими проклятыми рыбами не справиться!$B$B<Орако смотрит на вас.>$B$BМоего волка сожрала какая-то рыбина, и я не вернусь, пока ее не отыщу.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26087,'"Светящийся сок"','Легко подстрелить рыбу в бочке, а вот сделать это в океане непросто.$B$BТебе во впадине попадались мурлоки, |3-6($c)? Вот им ничего не стоит рыбку поймать! У них на головах такие специальные шарики с флуоресцентным соком, поэтому рыба сама к ним плывет. Нам тоже нужно воспользоваться этим способом!$B$BОтправляйся на юг и убей крабов и окуней. В них много светящегося сока, сам видел!','Добудьте 6 порций светящегося сока из огнепанцирных крабов и блестящих окуней в Затемненной впадине.','Вернитесь к Орако в Затемненную впадину в Вайш\'ире.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','"Светящийся сок"',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Легко подстрелить рыбу в бочке, а вот сделать это в океане непросто.$B$BТебе во впадине попадались мурлоки, |3-6($c)? Вот им ничего не стоит рыбку поймать! У них на головах такие специальные шарики с флуоресцентным соком, поэтому рыба сама к ним плывет. Нам тоже нужно воспользоваться этим способом!$B$BОтправляйся на юг и убей крабов и окуней. В них много светящегося сока, сам видел!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 6 порций светящегося сока из огнепанцирных крабов и блестящих окуней в Затемненной впадине.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Орако в Затемненную впадину в Вайш\'ире.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (26087,'Эй, гляди, как светится!$B$B<Орако устремляет вдаль взгляд полный тоски.>$B$BМой волк любил все, что светится...','Нам нужно очень много светящегося сока.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Эй, гляди, как светится!$B$B<Орако устремляет вдаль взгляд полный тоски.>$B$BМой волк любил все, что светится...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Нам нужно очень много светящегося сока.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26088,'Ловись, рыбка!','<Орако наполняет светящимся соком специальный шарик, а затем прикрепляет его к устройству, над созданием которого он, по-видимому, очень долго трудился.>$B$BВот, я тебе сделал такую шапку. На ней специальный огонек, так что рыба приплывет тебе прямо в руки. Как к мурлокам!$B$BМурлоки, как правило, охотятся в зарослях водорослей и кораллов рядом со впадиной. Надень эту шапку и проплыви через водоросли – надеюсь, тебе удастся наловить рыбы.','Наденьте шляпу рыболова и проплывите через заросли водорослей в Затемненной впадине, чтобы привлечь 30 люминесцентных гирелл.','Вернитесь к Орако в Затемненную впадину в Вайш\'ире.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ловись, рыбка!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Орако наполняет светящимся соком специальный шарик, а затем прикрепляет его к устройству, над созданием которого он, по-видимому, очень долго трудился.>$B$BВот, я тебе сделал такую шапку. На ней специальный огонек, так что рыба приплывет тебе прямо в руки. Как к мурлокам!$B$BМурлоки, как правило, охотятся в зарослях водорослей и кораллов рядом со впадиной. Надень эту шапку и проплыви через водоросли – надеюсь, тебе удастся наловить рыбы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Наденьте шляпу рыболова и проплывите через заросли водорослей в Затемненной впадине, чтобы привлечь 30 люминесцентных гирелл.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Орако в Затемненную впадину в Вайш\'ире.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (26088,'Хм... Рыбы у тебя много, но той, что сожрала моего волка, нет. Она наверняка была покрупнее.','Много удалось наловить?') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хм... Рыбы у тебя много, но той, что сожрала моего волка, нет. Она наверняка была покрупнее.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Много удалось наловить?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26089,'Я убью тебя, рыба','Рыба проглотила моего волка. Мурлоки похожи на рыбу – вот они и заплатят за его смерть!$B$BВозвращайся во впадину и уничтожь этих тварей! Отомсти за моего волка!','Убейте 4 охотников Холодного Сияния и 4 оракулов Холодного Сияния.','Вернитесь к Орако в Затемненную впадину в Вайш\'ире.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Я убью тебя, рыба',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Рыба проглотила моего волка. Мурлоки похожи на рыбу – вот они и заплатят за его смерть!$B$BВозвращайся во впадину и уничтожь этих тварей! Отомсти за моего волка!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 4 охотников Холодного Сияния и 4 оракулов Холодного Сияния.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Орако в Затемненную впадину в Вайш\'ире.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (26089,'Да знаю я, что мурлоки не рыбы. Просто думал, что, если уничтожить парочку, мне станет легче. Отнюдь нет – мне по-прежнему не хватает моего волка.$B$B<Орако вздыхает.>') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да знаю я, что мурлоки не рыбы. Просто думал, что, если уничтожить парочку, мне станет легче. Отнюдь нет – мне по-прежнему не хватает моего волка.$B$B<Орако вздыхает.>',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26090,'Я принес тебе икринку','<Похоже, это икринка одного из ужасных огромных угрей, обитающих во впадине. Вы размышляете над тем, не заинтересуется ли ею Орако.>','Отнесите огромную икринку угря Орако в Затемненную впадину в Вайш\'ире.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Я принес тебе икринку',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Похоже, это икринка одного из ужасных огромных угрей, обитающих во впадине. Вы размышляете над тем, не заинтересуется ли ею Орако.>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите огромную икринку угря Орако в Затемненную впадину в Вайш\'ире.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (26090,'Большая икринка.$B$B<Орако нюхает ее.>$B$BБольшая и пахнет рыбой. Может быть, та большая рыба, которая произвела на свет эту икринку, и съела моего волка!','<Бум!>$B$BТы мне что-то принес?') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Большая икринка.$B$B<Орако нюхает ее.>$B$BБольшая и пахнет рыбой. Может быть, та большая рыба, которая произвела на свет эту икринку, и съела моего волка!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Бум!>$B$BТы мне что-то принес?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26091,'Ловись, рыбка – 2: фокус с икринкой угря','<Орако достает из своего мешка взрывную ловушку и вставляет ее в икринку.>$B$BМы превратим эту икринку в бомбу. Оставь ее неподалеку от огромного угря и подожди, пока тот подплывет поближе. После взрыва рыба будет уже при смерти, и ты легко с ней разделаешься.$B$BСпаси моего волка! С этой икринкой у тебя все получится.','При помощи угретонатора взорвите ужасного огромного угря в Затемненной впадине, а затем добейте раненого угря.','Вернитесь к Орако в Затемненную впадину в Вайш\'ире.','Помоги мне найти волка!','Волк') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ловись, рыбка – 2: фокус с икринкой угря',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Орако достает из своего мешка взрывную ловушку и вставляет ее в икринку.>$B$BМы превратим эту икринку в бомбу. Оставь ее неподалеку от огромного угря и подожди, пока тот подплывет поближе. После взрыва рыба будет уже при смерти, и ты легко с ней разделаешься.$B$BСпаси моего волка! С этой икринкой у тебя все получится.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','При помощи угретонатора взорвите ужасного огромного угря в Затемненной впадине, а затем добейте раненого угря.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Орако в Затемненную впадину в Вайш\'ире.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Помоги мне найти волка!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Волк',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (26091,'<Орако играет со своим волком.>$B$BСпасибо тебе, Светопаладин! Я знал, что мой волк жив!$B$BВот, возьми, мне это больше не понадобится.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Орако играет со своим волком.>$B$BСпасибо тебе, Светопаладин! Я знал, что мой волк жив!$B$BВот, возьми, мне это больше не понадобится.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26092,'Донесение Орако','<Вы напоминаете Орако, что он должен отправить капитану Верну отчет.>$B$BТочно, отчет! Да я здесь, кроме рыбы, и не видел ничего. Громадное количество рыбы.$B$B<Орако смотрит на мешок с рыбой, который вы ему принесли.>$B$BОтнеси это капитану. Вместо отчета.','Отнесите донесение Орако капитану "Жуху" Верну в Зловещий грот.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Донесение Орако',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Вы напоминаете Орако, что он должен отправить капитану Верну отчет.>$B$BТочно, отчет! Да я здесь, кроме рыбы, и не видел ничего. Громадное количество рыбы.$B$B<Орако смотрит на мешок с рыбой, который вы ему принесли.>$B$BОтнеси это капитану. Вместо отчета.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите донесение Орако капитану "Жуху" Верну в Зловещий грот.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (26092,'Это его отчет?! Вот идиот...$B$BНу, хоть поесть можно. Спасибо, Бумагош. Ты отлично справился с заданием. Как обычно.','Где его носило? Что случилось?') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это его отчет?! Вот идиот...$B$BНу, хоть поесть можно. Спасибо, Бумагош. Ты отлично справился с заданием. Как обычно.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Где его носило? Что случилось?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (26093,'Северное поместье','Вернитесь к капитану Ниалс в Опорный пункт на Нагорье Арати.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Северное поместье',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Ниалс в Опорный пункт на Нагорье Арати.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26094,'Ответный удар','Мой главный инженер говорит, что ему удалось отремонтировать один из бомбардировщиков, и теперь он готов к полету. Возьми эти бомбы и отправляйся к отремонтированному бомбардировщику, он стоит в начале взлетно-посадочной полосы.$b$bКогда поднимешься в воздух, сбрасывай бомбы и постарайся нанести атакующим дворфам из Черного Железа как можно больший урон. Ходили слухи, что они собираются воспользоваться новым видом боевого голема. Смотри в оба, если обнаружишь этих боевых големов, они должны стать для тебя целью номер один.','Поднимитесь в воздух на отремонтированном бомбардировщике и при помощи железных штурмовых бомб убейте 30 атакующих Черного Железа. Можно убивать любых дворфов Черного Железа или их союзников на аэродроме Стальгорна.','Вернитесь к капитану форта Камнеломов на аэродром Стальгорна.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ответный удар',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мой главный инженер говорит, что ему удалось отремонтировать один из бомбардировщиков, и теперь он готов к полету. Возьми эти бомбы и отправляйся к отремонтированному бомбардировщику, он стоит в начале взлетно-посадочной полосы.$b$bКогда поднимешься в воздух, сбрасывай бомбы и постарайся нанести атакующим дворфам из Черного Железа как можно больший урон. Ходили слухи, что они собираются воспользоваться новым видом боевого голема. Смотри в оба, если обнаружишь этих боевых големов, они должны стать для тебя целью номер один.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поднимитесь в воздух на отремонтированном бомбардировщике и при помощи железных штурмовых бомб убейте 30 атакующих Черного Железа. Можно убивать любых дворфов Черного Железа или их союзников на аэродроме Стальгорна.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану форта Камнеломов на аэродром Стальгорна.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26095,'Знаки Стромгарда','Синдикат в Стромгарде воюет с силами нашего ополчения. Чтобы побудить толпу биться с нашими более дисциплинированными войсками, руководство Синдиката объявило о награде за убийство наших солдат, предлагая золото за каждый знак Стромгарда, снятый с убитых ополченцев.$B$BМы хотим вернуть себе эти знаки – не можем же мы позволить головорезам брать трофеи с тел наших героически погибших ребят!$B$BОтправляйся в район Стромгарда, контролируемый Синдикатом, и отбери у их бойцов наши знаки.','Отберите 7 знаков Стромгарда у членов Синдиката в крепости Стромгард.','Вернитесь к капитану Ниалс в Опорный пункт на Нагорье Арати.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Знаки Стромгарда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Синдикат в Стромгарде воюет с силами нашего ополчения. Чтобы побудить толпу биться с нашими более дисциплинированными войсками, руководство Синдиката объявило о награде за убийство наших солдат, предлагая золото за каждый знак Стромгарда, снятый с убитых ополченцев.$B$BМы хотим вернуть себе эти знаки – не можем же мы позволить головорезам брать трофеи с тел наших героически погибших ребят!$B$BОтправляйся в район Стромгарда, контролируемый Синдикатом, и отбери у их бойцов наши знаки.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отберите 7 знаков Стромгарда у членов Синдиката в крепости Стромгард.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Ниалс в Опорный пункт на Нагорье Арати.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26096,'Жгучие грибы','Кажется, мы нашли применение Безжалостным, которых принес нам твой друг из пещеры. Но к ним еще требуется консервант.$B$BТам внизу, в Жгучем провале, произрастают особые грибы, обладающие необходимыми мне свойствами. Принеси эти грибы, и я посмотрю, что можно сделать.','Соберите 5 жгучих грибов.','Из этих грибов я приготовлю реактив для консервации трупов безмозглых тварей. Скоро все будет готово. И ты тоже готовься.','Знаю, у тебя был неприятный опыт знакомства с этими тварями, когда ты надел одну из них на голову. Но сейчас можешь не волноваться. Я тебя уверяю: они все мертвы.','Вернитесь к говорящей с волнами Талре на вершину Подводного выступа в Вайш\'ире.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жгучие грибы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кажется, мы нашли применение Безжалостным, которых принес нам твой друг из пещеры. Но к ним еще требуется консервант.$B$BТам внизу, в Жгучем провале, произрастают особые грибы, обладающие необходимыми мне свойствами. Принеси эти грибы, и я посмотрю, что можно сделать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 5 жгучих грибов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Из этих грибов я приготовлю реактив для консервации трупов безмозглых тварей. Скоро все будет готово. И ты тоже готовься.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Знаю, у тебя был неприятный опыт знакомства с этими тварями, когда ты надел одну из них на голову. Но сейчас можешь не волноваться. Я тебя уверяю: они все мертвы.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к говорящей с волнами Талре на вершину Подводного выступа в Вайш\'ире.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (26097,'Доказательство лжи','Ортий мертв. В его руке зажат какой-то предмет.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Доказательство лжи',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ортий мертв. В его руке зажат какой-то предмет.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (26098,'Предательство в чаще','В этой комнате одни мертвые друиды. Здесь явно что-то не так, потому что следов борьбы нет. К двери ведет кровавый след, будто что-то тащили.$B$BВы разжимаете мертвую руку Ортия и с удивлением обнаруживаете в ней знак различия кром\'гарского генерала.$B$BНужно отнести это верховному вождю Скалоступу.','Отнесите знак различия кром\'гарского генерала верховному вождю Скалоступу на Плато Скалоступов в Когтистых горах.','<Верховный вождь Скалоступ берет у вас знак отличия>$B$B<Верховный вождь Скалоступ кричит от ярости.>','Он... Мой ребенок мертв?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Предательство в чаще',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В этой комнате одни мертвые друиды. Здесь явно что-то не так, потому что следов борьбы нет. К двери ведет кровавый след, будто что-то тащили.$B$BВы разжимаете мертвую руку Ортия и с удивлением обнаруживаете в ней знак различия кром\'гарского генерала.$B$BНужно отнести это верховному вождю Скалоступу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите знак различия кром\'гарского генерала верховному вождю Скалоступу на Плато Скалоступов в Когтистых горах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Верховный вождь Скалоступ берет у вас знак отличия>$B$B<Верховный вождь Скалоступ кричит от ярости.>',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Он... Мой ребенок мертв?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (26099,'Это ли правосудие?','Он был таким славным парнишкой, $n. Такой молодой, душевный... Он в жизни бы не поднял руку на молодого друида. Они с ним дружили! Нет... Только не Ортий.$B$BЗа это преступление нужно призвать к ответу генерала! Я добьюсь справедливости!','Защитите себя.','Защитите себя.','Поговорите с Машей Скалоступ на Плато Скалоступов в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Это ли правосудие?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Он был таким славным парнишкой, $n. Такой молодой, душевный... Он в жизни бы не поднял руку на молодого друида. Они с ним дружили! Нет... Только не Ортий.$B$BЗа это преступление нужно призвать к ответу генерала! Я добьюсь справедливости!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Защитите себя.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Защитите себя.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Машей Скалоступ на Плато Скалоступов в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26100,'Генерал мертв','Может, ты поговоришь с властителем Кром\'гаром, $n? Может, к твоим словам он прислушается? В конце концов, ты $gодин из героев:одна из героинь; его армии. И ты $gвидел:видела; все своими глазами. Прошу тебя, помоги нам, $n. Нам ничего не надо, только оставили бы нас в покое!$B$BПоговори с властителем Кром\'гаром и попытайся убедить его, что мы сами не хотели, чтобы все так вышло!','Поговорите с властителем Кром\'гаром в крепости Кром\'гар в Когтистых горах.','ЧТО?! Моего генерала убили таурены? Это измена! ГОСУДАРСТВЕННАЯ ИЗМЕНА! Они дорого заплатят за эту ошибку!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Генерал мертв',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Может, ты поговоришь с властителем Кром\'гаром, $n? Может, к твоим словам он прислушается? В конце концов, ты $gодин из героев:одна из героинь; его армии. И ты $gвидел:видела; все своими глазами. Прошу тебя, помоги нам, $n. Нам ничего не надо, только оставили бы нас в покое!$B$BПоговори с властителем Кром\'гаром и попытайся убедить его, что мы сами не хотели, чтобы все так вышло!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с властителем Кром\'гаром в крепости Кром\'гар в Когтистых горах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','ЧТО?! Моего генерала убили таурены? Это измена! ГОСУДАРСТВЕННАЯ ИЗМЕНА! Они дорого заплатят за эту ошибку!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26101,'Прав сильнейший','Ты правильно $gпоступил, что доложил:поступила, что доложила; об этом преступлении. Виновники этого гнусного преступления будут наказаны. Прольется кровь.$B$BТеперь, когда Гребо мертв, мне понадобится новый генерал, поэтому его место займешь ты.$B$BЯ буду ждать тебя на Плато Скалоступов, генерал. Давай вместе прекратим весь этот бред.','Встретьтесь с властителем Кром\'гаром на Плато Скалоступов в Когтистых горах.','Пусть этот предатель-таурен стоит и смотрит, как мы сровняем его драгоценную рощу с землей, а потом выжжем всю его деревню!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прав сильнейший',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты правильно $gпоступил, что доложил:поступила, что доложила; об этом преступлении. Виновники этого гнусного преступления будут наказаны. Прольется кровь.$B$BТеперь, когда Гребо мертв, мне понадобится новый генерал, поэтому его место займешь ты.$B$BЯ буду ждать тебя на Плато Скалоступов, генерал. Давай вместе прекратим весь этот бред.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Встретьтесь с властителем Кром\'гаром на Плато Скалоступов в Когтистых горах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Пусть этот предатель-таурен стоит и смотрит, как мы сровняем его драгоценную рощу с землей, а потом выжжем всю его деревню!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26102,'Кончина Лютореза','Благодаря твоей инициативе мы наконец получили преимущество в битве с кланом Черного Железа. Генерал Люторез, предводитель Черного Железа, находится в центре их расположения на замерзшем озере, что к югу отсюда, и пытается собрать войска.$b$bОн выкрикивает приказы своим бойцам, забравшись на одного из их новых железных големов. Если у него получится собрать их, они по-прежнему будут в состоянии одержать над нами верх. Ты $gдолжен:должна; предотвратить это, $n. Разрушь голема и убей самого генерала Лютореза. Это ключ к нашей победе.','Убейте генерала Лютореза на аэродроме Стальгорна.','Мы сделали это! Без твоей помощи аэродром Стальгорна наверняка был бы занят врагом, а клан Черного Железа имел бы прямой доступ к Стальгорну.$B$BСовет Трех Кланов должен узнать о том, что здесь произошло.','Вернитесь к капитану форта Камнеломов на аэродром Стальгорна.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кончина Лютореза',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Благодаря твоей инициативе мы наконец получили преимущество в битве с кланом Черного Железа. Генерал Люторез, предводитель Черного Железа, находится в центре их расположения на замерзшем озере, что к югу отсюда, и пытается собрать войска.$b$bОн выкрикивает приказы своим бойцам, забравшись на одного из их новых железных големов. Если у него получится собрать их, они по-прежнему будут в состоянии одержать над нами верх. Ты $gдолжен:должна; предотвратить это, $n. Разрушь голема и убей самого генерала Лютореза. Это ключ к нашей победе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте генерала Лютореза на аэродроме Стальгорна.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мы сделали это! Без твоей помощи аэродром Стальгорна наверняка был бы занят врагом, а клан Черного Железа имел бы прямой доступ к Стальгорну.$B$BСовет Трех Кланов должен узнать о том, что здесь произошло.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану форта Камнеломов на аэродром Стальгорна.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26103,'Биотопливо','Топливо для подводной лодки стоит очень дорого!$B$BВласть имущие Гномрегана расщедрились и выдали нам несколько бочек, но топливо расходуется гораздо быстрее, чем мы ожидали. Значит, придется импровизировать.$B$BНе секрет, что в организмах морских обитателей много разных химических веществ... В том числе жиров. Возьми это устройство и отправляйся в Край Кортуна. Воткни его в трупы черепах, прилипал и акул-молотов. Если мы не получим топлива, их жир может стать для нас единственным выходом.','С помощью жироотсоса добудьте в Краю Кортуна по 4 банки черепашьего жира, жира прилипалы и жира акулы-молота из тел водорослевых черепах, прилипал-чистильщиков и чешуеспинных акул-молотов.','<Инженер Мегагекс окунает палец в каждый образец жира и нюхает его.>$B$BДа, думаю, сойдет.','Вернитесь к инженеру Мегагексу в Темную пещеру в Вайш\'ире.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Биотопливо',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Топливо для подводной лодки стоит очень дорого!$B$BВласть имущие Гномрегана расщедрились и выдали нам несколько бочек, но топливо расходуется гораздо быстрее, чем мы ожидали. Значит, придется импровизировать.$B$BНе секрет, что в организмах морских обитателей много разных химических веществ... В том числе жиров. Возьми это устройство и отправляйся в Край Кортуна. Воткни его в трупы черепах, прилипал и акул-молотов. Если мы не получим топлива, их жир может стать для нас единственным выходом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','С помощью жироотсоса добудьте в Краю Кортуна по 4 банки черепашьего жира, жира прилипалы и жира акулы-молота из тел водорослевых черепах, прилипал-чистильщиков и чешуеспинных акул-молотов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Инженер Мегагекс окунает палец в каждый образец жира и нюхает его.>$B$BДа, думаю, сойдет.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к инженеру Мегагексу в Темную пещеру в Вайш\'ире.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26104,'Подводные соседи','Приветствую, дружище.$B$BПодкрепление прибыло. У нас теперь есть провизия, люди и свежие лошади. Только вот от лошадей под водой мало толку.$B$BСлушай, прямо над этой пещерой стоят высокие башни, на вершинах которых растут густые красные водоросли. Так вот, в этих водорослях водятся морские коньки. Забрось это лассо в заросли и поймай нам несколько скакунов.','С помощью лассо поймайте среди водорослей на вершине башен Края Кортуна 5 испуганных морских коньков.','Вернитесь к капитану Гловаалю в Темную пещеру в Вайш\'ире.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подводные соседи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приветствую, дружище.$B$BПодкрепление прибыло. У нас теперь есть провизия, люди и свежие лошади. Только вот от лошадей под водой мало толку.$B$BСлушай, прямо над этой пещерой стоят высокие башни, на вершинах которых растут густые красные водоросли. Так вот, в этих водорослях водятся морские коньки. Забрось это лассо в заросли и поймай нам несколько скакунов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','С помощью лассо поймайте среди водорослей на вершине башен Края Кортуна 5 испуганных морских коньков.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Гловаалю в Темную пещеру в Вайш\'ире.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26105,'Защита Края Кортуна','Здесь рыщут шпионы Орды? Тут поблизости Темная пещера, а в ней – "Хват X2"! Ни в коем случае нельзя подпускать туда Орду!$B$BНужно будет сообщить об этом кое-кому в пещере... Но для начала разделайся с этими наглыми ищейками Орды.','Убейте 7 морских волков Адского Крика в Краю Кортуна.','Расскажите обо всем Джорлану Верному Клинку в Темной пещере в Вайш\'ире.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Защита Края Кортуна',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Здесь рыщут шпионы Орды? Тут поблизости Темная пещера, а в ней – "Хват X2"! Ни в коем случае нельзя подпускать туда Орду!$B$BНужно будет сообщить об этом кое-кому в пещере... Но для начала разделайся с этими наглыми ищейками Орды.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 7 морских волков Адского Крика в Краю Кортуна.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Расскажите обо всем Джорлану Верному Клинку в Темной пещере в Вайш\'ире.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (26106,'Топливоведение-101','Что тебе известно о топливе, $n? Создание топлива – очень сложный процесс. Нужно учитывать множество различных показателей: временные параметры переокисления, переменные горючепрочности, критерии силицификации горения... Уж не говоря обо всех остальных факторах.$B$BНадеюсь, если те ингредиенты, которые ты мне $gпринес:принесла;, смешать в правильных пропорциях, мы получим идеальное биотопливо. Попробуй приготовить несколько образцов при помощи вон того стола! Потом принеси мне то, что у тебя получится.','Создайте идеальное биотопливо при помощи стола для приготовления топливных образцов в Темной пещере.','Создайте идеальное биотопливо','Вернитесь к инженеру Мегагексу в Темную пещеру в Вайш\'ире.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Топливоведение-101',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что тебе известно о топливе, $n? Создание топлива – очень сложный процесс. Нужно учитывать множество различных показателей: временные параметры переокисления, переменные горючепрочности, критерии силицификации горения... Уж не говоря обо всех остальных факторах.$B$BНадеюсь, если те ингредиенты, которые ты мне $gпринес:принесла;, смешать в правильных пропорциях, мы получим идеальное биотопливо. Попробуй приготовить несколько образцов при помощи вон того стола! Потом принеси мне то, что у тебя получится.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Создайте идеальное биотопливо при помощи стола для приготовления топливных образцов в Темной пещере.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Создайте идеальное биотопливо',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к инженеру Мегагексу в Темную пещеру в Вайш\'ире.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (26107,'Вызов духов','Дар шаманства, присущий нашей расе, вырвал меня из многолетнего летаргического сна. И теперь я совершу для других такое же благодеяние, как то, что позволило мне обрести силы.$b$bЯщеры нагорья хитрые и жестокие твари. Их души могут дать нашим воинам огромную силу. Принеси мне глаза ящеров, чтобы я мог изготовить амулеты, как научил меня Тор\'ган.','Вернитесь к Гор\'мулю в Павший Молот на Нагорье Арати.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вызов духов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Дар шаманства, присущий нашей расе, вырвал меня из многолетнего летаргического сна. И теперь я совершу для других такое же благодеяние, как то, что позволило мне обрести силы.$b$bЯщеры нагорья хитрые и жестокие твари. Их души могут дать нашим воинам огромную силу. Принеси мне глаза ящеров, чтобы я мог изготовить амулеты, как научил меня Тор\'ган.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гор\'мулю в Павший Молот на Нагорье Арати.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26108,'Коварство ящера','Плотоглоты нагорья, которые обитают к югу отсюда, еще более свирепы, чем другие ящеры. Они не только сильны, но и очень коварны.$b$bКогда я лежал в летаргическом сне, даже амулеты силы не могли помочь мне. Но Тор\'ган использовал сердца плотоглотов, чтобы вселить в меня силу духа, и это освободило меня.$b$bНаши воины заслуживают того, чтобы обладать коварством ящера. Принеси мне сердца плотоглотов, $n.','Соберите 12 сердец ящеров, убив плотоглотов нагорья.','Вернитесь к Гор\'мулю в Павший Молот на Нагорье Арати.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Коварство ящера',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Плотоглоты нагорья, которые обитают к югу отсюда, еще более свирепы, чем другие ящеры. Они не только сильны, но и очень коварны.$b$bКогда я лежал в летаргическом сне, даже амулеты силы не могли помочь мне. Но Тор\'ган использовал сердца плотоглотов, чтобы вселить в меня силу духа, и это освободило меня.$b$bНаши воины заслуживают того, чтобы обладать коварством ящера. Принеси мне сердца плотоглотов, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 12 сердец ящеров, убив плотоглотов нагорья.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гор\'мулю в Павший Молот на Нагорье Арати.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26109,'Эй, там!','Лоло видит крошку-|3-1($r)! Лоло всегда начеку!$b$bДобро пожаловать в Бухту Фальдира. Капитан О\'Брин сказал, что мы задержимся тут лишь на несколько часов. Ровно настолько, сколько потребуется, чтобы добыть сокровище и отчалить обратно в Пиратскую Бухту.$b$bНо Лоло думает, что мы тут засели надолго. Мы потеряли два последних корабля из нашей эскадры. Беднягу "Дух Серебряного бора" и несчастную "Девичью Блажь". На дне морском они теперь!$b$bЛоло думает, что тебе стоит переговорить с капитаном О\'Брином, если ты собираешься тут остаться.','Поговорите с капитаном О\'Брином в бухте Фальдира, что на Нагорье Арати.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Эй, там!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Лоло видит крошку-|3-1($r)! Лоло всегда начеку!$b$bДобро пожаловать в Бухту Фальдира. Капитан О\'Брин сказал, что мы задержимся тут лишь на несколько часов. Ровно настолько, сколько потребуется, чтобы добыть сокровище и отчалить обратно в Пиратскую Бухту.$b$bНо Лоло думает, что мы тут засели надолго. Мы потеряли два последних корабля из нашей эскадры. Беднягу "Дух Серебряного бора" и несчастную "Девичью Блажь". На дне морском они теперь!$b$bЛоло думает, что тебе стоит переговорить с капитаном О\'Брином, если ты собираешься тут остаться.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с капитаном О\'Брином в бухте Фальдира, что на Нагорье Арати.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26111,'...И он придет','Я заряжаю тебя энергией безликих осквернителей.$B$BПлыви к моему приманивающему тотему в глубоководной впадине на северо-востоке и освободи через него всю энергию. Принеси мне мозг их предводителя.$B$BПризови Их\'тиса Непостижимого... И он придет!','Раздобудьте мозг Непостижимого.','Сейчас попробуем сделать так, чтобы ты проник в Л\'горека и поговорил с ним, пока он еще жив.','Вернитесь к Эрунаку Говорящему с Камнем на вершину Подводного выступа в Вайш\'ире.','Вам нужен его мозг!','Их\'тис Непостижимый') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','...И он придет',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я заряжаю тебя энергией безликих осквернителей.$B$BПлыви к моему приманивающему тотему в глубоководной впадине на северо-востоке и освободи через него всю энергию. Принеси мне мозг их предводителя.$B$BПризови Их\'тиса Непостижимого... И он придет!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте мозг Непостижимого.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сейчас попробуем сделать так, чтобы ты проник в Л\'горека и поговорил с ним, пока он еще жив.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Эрунаку Говорящему с Камнем на вершину Подводного выступа в Вайш\'ире.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Вам нужен его мозг!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Их\'тис Непостижимый',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26112,'Требование ответа','Отнесите донесение Камнеломов Мойре Тауриссан к Высокому трону Стальгорна.','Это еще что?$B$B<Мойра берет донесение, и краска заливает ее лицо по мере чтения.>$B$BЭто невозможно!','Почему ты заявился сюда без приглашения?','Отнесите донесение Камнеломов Мойре Тауриссан к Высокому трону Стальгорна.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Требование ответа',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите донесение Камнеломов Мойре Тауриссан к Высокому трону Стальгорна.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это еще что?$B$B<Мойра берет донесение, и краска заливает ее лицо по мере чтения.>$B$BЭто невозможно!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Почему ты заявился сюда без приглашения?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите донесение Камнеломов Мойре Тауриссан к Высокому трону Стальгорна.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (26114,'Кви верит тебе','<Кви начинает просматривать папку.>$b$bЗахват... контролирование территории... ничего нового эта нежить не придумала, но планы у них на все Нагорье Арати. Мы должны помешать.$b$bЯ буду наблюдать отсюда. А ты отправляйся с Кин и достань эти планы захвата. Пусть у этих ходячих трупов не будет никакой информации.$b$bИ береги Кин, слышишь?','Нашу семью и наших друзей унесла чума, но Фин на совести Отрекшихся. Они ничем не лучше Плети. Если нужно, я уничтожу каждого из них своими собственными руками.$B$BКогда будешь готов, дай мне знать. Мы начнем немедленно.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кви верит тебе',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Кви начинает просматривать папку.>$b$bЗахват... контролирование территории... ничего нового эта нежить не придумала, но планы у них на все Нагорье Арати. Мы должны помешать.$b$bЯ буду наблюдать отсюда. А ты отправляйся с Кин и достань эти планы захвата. Пусть у этих ходячих трупов не будет никакой информации.$b$bИ береги Кин, слышишь?',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Нашу семью и наших друзей унесла чума, но Фин на совести Отрекшихся. Они ничем не лучше Плети. Если нужно, я уничтожу каждого из них своими собственными руками.$B$BКогда будешь готов, дай мне знать. Мы начнем немедленно.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26115,'Что значит быть Ордой...','Встань рядом, $n, и смотри, как наше мощное оружие крушит наших врагов!$B$BУзнай, что это значит – быть Ордой!','Узнайте, что значит быть Ордой.','Поговорите с верховным вождем Скалоступом на Плато Скалоступов') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Что значит быть Ордой...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Встань рядом, $n, и смотри, как наше мощное оружие крушит наших врагов!$B$BУзнай, что это значит – быть Ордой!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Узнайте, что значит быть Ордой.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с верховным вождем Скалоступом на Плато Скалоступов',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`endtext_loc8`) VALUES (26116,'Удар Кинелори','Хорошо, $n. Если ты $gготов:готова;, то и я тоже. Идем?','Защитите Кинелори во время ее возвращения к Кви.','Лучше держись поближе к Кинелори. Я доверяю тебе, но если что-нибудь с ней случится, я за себя не ручаюсь.','Защитите Кинелори') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Удар Кинелори',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хорошо, $n. Если ты $gготов:готова;, то и я тоже. Идем?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Защитите Кинелори во время ее возвращения к Кви.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Лучше держись поближе к Кинелори. Я доверяю тебе, но если что-нибудь с ней случится, я за себя не ручаюсь.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Защитите Кинелори',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26117,'За Южнобережье','После ночи, проведенной в таверне, Кинелори обычно выглядит заметно хуже, чем сейчас. Ты определенно хорошо о ней $gзаботился:заботилась;.$b$bНадо сообщить в Опорный пункт о нашей удаче. Я останусь здесь с Кин, пока она не переведет дух. А ты отправляйся вперед без нас.','Вернитесь к командиру Амарену в Опорный пункт.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','За Южнобережье',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','После ночи, проведенной в таверне, Кинелори обычно выглядит заметно хуже, чем сейчас. Ты определенно хорошо о ней $gзаботился:заботилась;.$b$bНадо сообщить в Опорный пункт о нашей удаче. Я останусь здесь с Кин, пока она не переведет дух. А ты отправляйся вперед без нас.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь к командиру Амарену в Опорный пункт.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (26118,'Арестовать посла','Мысль о предательстве посла еще долго будет преследовать меня. Ты $gдолжен:должна; арестовать его прежде, чем он снова причинит нам вред, или, что еще хуже, сбежит и начнет планировать следующую атаку. Пока посол Шлакомолот в городе и на свободе, Стальгорн не может быть в безопасности.$b$bВозьми эти наручники и отправляйся в посольство Черного Железа. Оно находится севернее Высокого трона, у границы Великой Кузни. Арестуй посла Шлакомолота и возвращайся вместе с ним.','Отправляйтесь в посольство Черного Железа и воспользуйтесь прочными наручниками, чтобы арестовать посла Шлакомолота.','Посол больше не причинит нам проблем. Он не единственный дворф Черного Железа, чье сердце до сих пор принадлежит Сумеречному Молоту. Мы должны помнить об этом и быть бдительными, иначе моему сыну достанутся в наследство только пепел и руины.','Арестуйте посла Шлакомолота и приведите его к Высокому Трону','Вернитесь к Мойре Бронзобород к Высокому трону в Стальгорне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Арестовать посла',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мысль о предательстве посла еще долго будет преследовать меня. Ты $gдолжен:должна; арестовать его прежде, чем он снова причинит нам вред, или, что еще хуже, сбежит и начнет планировать следующую атаку. Пока посол Шлакомолот в городе и на свободе, Стальгорн не может быть в безопасности.$b$bВозьми эти наручники и отправляйся в посольство Черного Железа. Оно находится севернее Высокого трона, у границы Великой Кузни. Арестуй посла Шлакомолота и возвращайся вместе с ним.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в посольство Черного Железа и воспользуйтесь прочными наручниками, чтобы арестовать посла Шлакомолота.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Посол больше не причинит нам проблем. Он не единственный дворф Черного Железа, чье сердце до сих пор принадлежит Сумеречному Молоту. Мы должны помнить об этом и быть бдительными, иначе моему сыну достанутся в наследство только пепел и руины.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Арестуйте посла Шлакомолота и приведите его к Высокому Трону',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мойре Бронзобород к Высокому трону в Стальгорне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (26119,'FLAG - Claim Our Stake Launched') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','FLAG - Claim Our Stake Launched',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26120,'Драконья Пасть и драконы','Эти орки из клана Драконьей Пасти начинают серьезно мне надоедать. Их самоубийственные вылазки – скорее, повод для раздражения, чем серьезная угроза роще. Единственная польза от них – есть где поднабраться опыта моим часовым.$B$BОднако разведчики докладывают, что орки стали ловить в свои сети черных дракончиков. Вот уж чего этой многострадальной земле не хватает, так это "приручения" драконов. Отправляйся на восток, |3-6($c), и перехвати похитителей драконьих детенышей, чтобы нам не пришлось потом расплачиваться за совершенную этими глупцами непростительную ошибку.','Теперь орки дважды подумают, прежде чем снова соваться на запад. Очень хорошо.','Вернитесь к охотнице Изелии в Рощу Стража Природы, что в Болотине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Драконья Пасть и драконы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти орки из клана Драконьей Пасти начинают серьезно мне надоедать. Их самоубийственные вылазки – скорее, повод для раздражения, чем серьезная угроза роще. Единственная польза от них – есть где поднабраться опыта моим часовым.$B$BОднако разведчики докладывают, что орки стали ловить в свои сети черных дракончиков. Вот уж чего этой многострадальной земле не хватает, так это "приручения" драконов. Отправляйся на восток, |3-6($c), и перехвати похитителей драконьих детенышей, чтобы нам не пришлось потом расплачиваться за совершенную этими глупцами непростительную ошибку.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь орки дважды подумают, прежде чем снова соваться на запад. Очень хорошо.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к охотнице Изелии в Рощу Стража Природы, что в Болотине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26121,'Защита Края Кортуна','Видишь наверху шпионов? Плохо это... Совсем плохо, дружище.$B$BВозвращайся в Край Кортуна и уничтожь их всех.','Убейте 7 морских волков Адского Крика в Краю Кортуна.','Расскажите обо всем Джорлану Верному Клинку в Темной пещере в Вайш\'ире.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Защита Края Кортуна',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Видишь наверху шпионов? Плохо это... Совсем плохо, дружище.$B$BВозвращайся в Край Кортуна и уничтожь их всех.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 7 морских волков Адского Крика в Краю Кортуна.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Расскажите обо всем Джорлану Верному Клинку в Темной пещере в Вайш\'ире.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26122,'Защита окружающей среды','Ты знаешь, как воняет топливо для подводной лодки, $n? Жуть! А мы его жжем – не жалеем, чтоб только "Верн" раскочегарить. Да ладно запах, но оно же убивает все живое вокруг. Нет, вот все-таки надо бережнее относиться к окружающей среде, да.$B$BВ здешних морских животных очень много жира. Возьми это устройство, отправляйся в Донные заросли прямо над этой пещерой и воткни его там в трупы водорослевых черепах, прилипал и акул-молотов – пусть их жир после смерти хозяев спасет жизни другим морским обитателям.','Используйте жироотсос, чтобы добыть в Донных зарослях по 4 банки черепашьего жира, жира прилипалы и жира акулы-молота из тел водорослевых черепах, прилипал-чистильщиков и чешуеспинных акул-молотов.','Вернитесь к Облину Свистозубу в Зловещий грот в Вайш\'ире.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Защита окружающей среды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты знаешь, как воняет топливо для подводной лодки, $n? Жуть! А мы его жжем – не жалеем, чтоб только "Верн" раскочегарить. Да ладно запах, но оно же убивает все живое вокруг. Нет, вот все-таки надо бережнее относиться к окружающей среде, да.$B$BВ здешних морских животных очень много жира. Возьми это устройство, отправляйся в Донные заросли прямо над этой пещерой и воткни его там в трупы водорослевых черепах, прилипал и акул-молотов – пусть их жир после смерти хозяев спасет жизни другим морским обитателям.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте жироотсос, чтобы добыть в Донных зарослях по 4 банки черепашьего жира, жира прилипалы и жира акулы-молота из тел водорослевых черепах, прилипал-чистильщиков и чешуеспинных акул-молотов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Облину Свистозубу в Зловещий грот в Вайш\'ире.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (26122,'<Облин окунает палец в каждый образец жира и нюхает.>$B$BДа, думаю, сойдет.','Только вот что – уж не говори другим гоблинам, что я занимаюсь защитой окружающей среды! А то засмеют.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Облин окунает палец в каждый образец жира и нюхает.>$B$BДа, думаю, сойдет.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Только вот что – уж не говори другим гоблинам, что я занимаюсь защитой окружающей среды! А то засмеют.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26123,'В Вайш\'ире...','Здравствуй, дружище.$B$BПодкрепление прибыло. У нас теперь есть провизия, орки и свежие волки. Постой... Волки?!.$B$BИ как это мы, интересно, будет передвигаться под водой верхом на волках?!$B$B<Капитан Верн вздыхает.>$B$BПрямо над этой пещерой в Донных зарослях стоят высокие башни, на вершинах которых растут густые красные водоросли. Так вот в этих водорослях водятся морские коньки. Забрось это лассо в заросли и поймай нам подходящих скакунов.','С помощью лассо поймайте среди водорослей на вершине башен Донных зарослей 5 испуганных морских коньков.','Вернитесь к капитану "Жуху" Верну в Зловещий грот в Вайш\'ире.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В Вайш\'ире...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Здравствуй, дружище.$B$BПодкрепление прибыло. У нас теперь есть провизия, орки и свежие волки. Постой... Волки?!.$B$BИ как это мы, интересно, будет передвигаться под водой верхом на волках?!$B$B<Капитан Верн вздыхает.>$B$BПрямо над этой пещерой в Донных зарослях стоят высокие башни, на вершинах которых растут густые красные водоросли. Так вот в этих водорослях водятся морские коньки. Забрось это лассо в заросли и поймай нам подходящих скакунов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','С помощью лассо поймайте среди водорослей на вершине башен Донных зарослей 5 испуганных морских коньков.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану "Жуху" Верну в Зловещий грот в Вайш\'ире.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26124,'Защита Донных зарослей','Здесь рыщут шпионы Альянса? Поблизости Зловещий грот, а в нем – "Верн", новая подводная лодка Орды! Ни в коем случае нельзя подпускать Альянс к этому месту!$B$BНужно сообщить об этом кое-кому в гроте... Но для начала разделайся с хитрыми шпионами Альянса.','Убейте 7 морских разведчиков Альянса в Донных зарослях.','Расскажите обо всем кровостражу Толдреку в Зловещем гроте в Вайш\'ире.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Защита Донных зарослей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Здесь рыщут шпионы Альянса? Поблизости Зловещий грот, а в нем – "Верн", новая подводная лодка Орды! Ни в коем случае нельзя подпускать Альянс к этому месту!$B$BНужно сообщить об этом кое-кому в гроте... Но для начала разделайся с хитрыми шпионами Альянса.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 7 морских разведчиков Альянса в Донных зарослях.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Расскажите обо всем кровостражу Толдреку в Зловещем гроте в Вайш\'ире.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26125,'Защита Донных зарослей','Ты $gвидел:видела; наверху шпионов? Это плохо... Такого допускать нельзя!$B$BВозвращайся в Донные заросли и уничтожь их, прежде чем они проникнут в наше убежище.','Убейте 7 морских разведчиков Альянса в Донных зарослях.','Расскажите обо всем кровостражу Толдреку в Зловещем гроте в Вайш\'ире.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Защита Донных зарослей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gвидел:видела; наверху шпионов? Это плохо... Такого допускать нельзя!$B$BВозвращайся в Донные заросли и уничтожь их, прежде чем они проникнут в наше убежище.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 7 морских разведчиков Альянса в Донных зарослях.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Расскажите обо всем кровостражу Толдреку в Зловещем гроте в Вайш\'ире.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (26126,'Идеальное топливо','Что тебе известно о топливе, $n? Создание топлива – очень сложный процесс. Нужно учитывать множество различных показателей: временные параметры переокисления, переменные горючепрочности, критерии силицификации горения... Уж не говоря обо всех остальных факторах.$B$BНадеюсь, если те ингредиенты, которые ты мне $gпринес:принесла;, смешать в правильных пропорциях, мы получим идеальное биотопливо. Попробуй приготовить несколько образцов при помощи вон того стола! Потом принеси мне то, что у тебя получится.','Создайте идеальное биотопливо при помощи стола для приготовления топливных образцов в Зловещем гроте.','Создайте идеальное биотопливо','Вернитесь к Облину Свистозубу в Зловещем гроте, что находится в Вайш\'ире.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Идеальное топливо',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что тебе известно о топливе, $n? Создание топлива – очень сложный процесс. Нужно учитывать множество различных показателей: временные параметры переокисления, переменные горючепрочности, критерии силицификации горения... Уж не говоря обо всех остальных факторах.$B$BНадеюсь, если те ингредиенты, которые ты мне $gпринес:принесла;, смешать в правильных пропорциях, мы получим идеальное биотопливо. Попробуй приготовить несколько образцов при помощи вон того стола! Потом принеси мне то, что у тебя получится.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Создайте идеальное биотопливо при помощи стола для приготовления топливных образцов в Зловещем гроте.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Создайте идеальное биотопливо',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Облину Свистозубу в Зловещем гроте, что находится в Вайш\'ире.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (26126,'Готово. С сегодняшнего дня я перевожу "Верн" на биотопливо. Я пошлю людей собрать еще жира.$B$BПросто задумайся обо всех тех морских созданиях, которым мы спасли сегодня жизнь, Бумагош!') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Готово. С сегодняшнего дня я перевожу "Верн" на биотопливо. Я пошлю людей собрать еще жира.$B$BПросто задумайся обо всех тех морских созданиях, которым мы спасли сегодня жизнь, Бумагош!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26127,'Явление Сумеречного Молота','Я-то, как и все остальные, думал, что это просто ополоумевшие дворфы из клана Черного Железа, а оказалось – это вконец спятившие сектанты!$B$BФанатики из культа Сумеречного Молота хотят – ни много ни мало – уничтожить весь мир. За ними – Смертокрыл и Рагнарос, да и с кланом Черного Железа у них давняя дружба.$B$BНо неважно, кто они, важно другое. Они заняли Дун Модр! Нужно их выбить отсюда. Бери оружие и отправляйся крушить черепа, а я останусь здесь и прослежу, чтобы никто из них не улизнул!','Убейте 12 сектантов из культа Сумеречного Молота.','Отлично справился, дружище. Но праздновать нет времени. Мосту Тандола грозит опасность!','Вернитесь к Таргасу Старой Наковальне, находящемуся в Дун Модре, что в Болотине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Явление Сумеречного Молота',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я-то, как и все остальные, думал, что это просто ополоумевшие дворфы из клана Черного Железа, а оказалось – это вконец спятившие сектанты!$B$BФанатики из культа Сумеречного Молота хотят – ни много ни мало – уничтожить весь мир. За ними – Смертокрыл и Рагнарос, да и с кланом Черного Железа у них давняя дружба.$B$BНо неважно, кто они, важно другое. Они заняли Дун Модр! Нужно их выбить отсюда. Бери оружие и отправляйся крушить черепа, а я останусь здесь и прослежу, чтобы никто из них не улизнул!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 сектантов из культа Сумеречного Молота.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично справился, дружище. Но праздновать нет времени. Мосту Тандола грозит опасность!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Таргасу Старой Наковальне, находящемуся в Дун Модре, что в Болотине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26128,'Битва за мост Тандола','Мне уже доводилось защищать Мост Тандола от врагов. Тогда это был сам клан Черного Железа. И мой отец в свое время дрался с ними здесь, и его отец тоже...$B$BЕдинственный вражина, что сумел проскочить мимо меня, рванул прямиком к мосту. Что-то здесь не так, и я нутром чую, что нас там ждет засада.$B$BМне нужна твоя помощь, $n. Ради Стальгорна. Подсобишь?','Одолейте Каламота Пепельную Бороду на Мосту Тандола.','Вернитесь к Таргасу Старой Наковальне, находящемуся в Дун Модре, что в Болотине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Битва за мост Тандола',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне уже доводилось защищать Мост Тандола от врагов. Тогда это был сам клан Черного Железа. И мой отец в свое время дрался с ними здесь, и его отец тоже...$B$BЕдинственный вражина, что сумел проскочить мимо меня, рванул прямиком к мосту. Что-то здесь не так, и я нутром чую, что нас там ждет засада.$B$BМне нужна твоя помощь, $n. Ради Стальгорна. Подсобишь?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Одолейте Каламота Пепельную Бороду на Мосту Тандола.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Таргасу Старой Наковальне, находящемуся в Дун Модре, что в Болотине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26129,'Братья по оружию','Послушай, $n – я впервые с начала гражданской войны согласен с Седогривом. Пора забыть о наших разногласиях и начать все сначала.$B$BЭтим зверям все равно, мятежник ты или нет. $B$BПередай Седогриву, что мои люди встанут на его сторону.$B$BНеподалеку отсюда, в подвале Джосайи есть склад, где мои люди хранят кое-какое тяжелое вооружение.$B$BСкажи нашему королю, что мой арсенал – в его распоряжении.','Поговорите с королем Генном Седогривом в Военном квартале Гилнеаса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Братья по оружию',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Послушай, $n – я впервые с начала гражданской войны согласен с Седогривом. Пора забыть о наших разногласиях и начать все сначала.$B$BЭтим зверям все равно, мятежник ты или нет. $B$BПередай Седогриву, что мои люди встанут на его сторону.$B$BНеподалеку отсюда, в подвале Джосайи есть склад, где мои люди хранят кое-какое тяжелое вооружение.$B$BСкажи нашему королю, что мой арсенал – в его распоряжении.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с королем Генном Седогривом в Военном квартале Гилнеаса.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26130,'Отсоединение Л\'горека','Л\'горек – древнее существо, возлежащее на скалистом уступе прямо напротив нас. Его держат под строгим наблюдением и выкачивают из него жизненную энергию, которую поглощает некая ненасытная сущность, расположенная где-то под нами.$B$BПод уступом, где лежит Л\'горек, есть пещера, именуемая Донный грот. В этой пещере три сильных мага-огра денно и нощно проводят особые ритуалы, связующие древнего Л\'горека с тварью внизу. Тебе нужно убить эту троицу, чтобы отсоединить Л\'горека.','Убейте Ур\'Гоза, Ску\'Бу и Неф\'Лахима.','Теперь, когда ты отсоединил Л\'горека, мы попробуем сами установить с ним связь. Я чувствую, он еще жив. Но его время уже на исходе.','Вернитесь к Эрунаку Говорящему с Камнем на вершину Подводного выступа в Вайш\'ире.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отсоединение Л\'горека',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Л\'горек – древнее существо, возлежащее на скалистом уступе прямо напротив нас. Его держат под строгим наблюдением и выкачивают из него жизненную энергию, которую поглощает некая ненасытная сущность, расположенная где-то под нами.$B$BПод уступом, где лежит Л\'горек, есть пещера, именуемая Донный грот. В этой пещере три сильных мага-огра денно и нощно проводят особые ритуалы, связующие древнего Л\'горека с тварью внизу. Тебе нужно убить эту троицу, чтобы отсоединить Л\'горека.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Ур\'Гоза, Ску\'Бу и Неф\'Лахима.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь, когда ты отсоединил Л\'горека, мы попробуем сами установить с ним связь. Я чувствую, он еще жив. Но его время уже на исходе.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Эрунаку Говорящему с Камнем на вершину Подводного выступа в Вайш\'ире.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26131,'Подкрепление для Лок Модана','Отправляйтесь в Великую Кузню и поговорите с Гритом Турденом о полете в Лок Модан. Когда прибудете, поговорите с пилотом Большеногом.','Ты и представить себе не можешь, как я рад видеть кого-то из Стальгорна. Похоже, в отправке горного пехотинца Ячменовара все-таки был смысл.','Поговорите с пилотом Большеногом на заставе у Южных Врат.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подкрепление для Лок Модана',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Великую Кузню и поговорите с Гритом Турденом о полете в Лок Модан. Когда прибудете, поговорите с пилотом Большеногом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты и представить себе не можешь, как я рад видеть кого-то из Стальгорна. Похоже, в отправке горного пехотинца Ячменовара все-таки был смысл.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с пилотом Большеногом на заставе у Южных Врат.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26132,'Чудовища Пустоты','Маги-огры из Донного грота вызвали себе защитников – кровожадных чудовищ Пустоты.$B$BА ведь их потом могут натравить на наших солдат... Этого нельзя допустить! Когда будешь там, постарайся уничтожить чудовищ. Чем больше, тем лучше.','Уничтожьте 8 исчадий Пустоты.','Вот уж действительно было бы некстати, если во время последнего штурма эти твари напали бы на наше войско.','Вернитесь к капитану Тейлору на вершину Подводного выступа в Вайш\'ире.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чудовища Пустоты',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Маги-огры из Донного грота вызвали себе защитников – кровожадных чудовищ Пустоты.$B$BА ведь их потом могут натравить на наших солдат... Этого нельзя допустить! Когда будешь там, постарайся уничтожить чудовищ. Чем больше, тем лучше.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 8 исчадий Пустоты.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот уж действительно было бы некстати, если во время последнего штурма эти твари напали бы на наше войско.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Тейлору на вершину Подводного выступа в Вайш\'ире.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26133,'Чудовища Пустоты','Маги-огры из Донного грота вызвали себе защитников – кровожадных исчадий Пустоты.$B$BНе хочется, чтобы потом их напустили на наших солдат. Когда будешь там, постарайся уничтожить всех чудовищ. Всех до единого!','Уничтожьте 8 исчадий Пустоты.','Вернитесь к легионеру Назгриму на вершину Подводного выступа в Вайш\'ире.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чудовища Пустоты',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Маги-огры из Донного грота вызвали себе защитников – кровожадных исчадий Пустоты.$B$BНе хочется, чтобы потом их напустили на наших солдат. Когда будешь там, постарайся уничтожить всех чудовищ. Всех до единого!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 8 исчадий Пустоты.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к легионеру Назгриму на вершину Подводного выступа в Вайш\'ире.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (26133,'Ну вот, одной головной болью меньше. Нам и так будет о чем думать во время последнего штурма.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну вот, одной головной болью меньше. Нам и так будет о чем думать во время последнего штурма.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26134,'Ничего тут для тебя нет','Для тебя тут больше ничего не осталось, $n. А мне еще нужно похоронить тело Маши. Потом я вернусь на место бомбежки и начну ритуал восстановления. Возможно, когда-нибудь там расцветет новая роща, где будут обитать духи юных ночных эльфов и с ними мое дитя.$B$BЕсли вдруг ты $gнаправлялся:направлялась; в Пустоши, то мне говорили, будто бы некий эльф крови по имени Фуриен ищет себе смекалистых помощников. Может, вам с ним стоит переговорить.$B$BПрощай же... Я всегда буду помнить тебя.','Поговорите с Фуриеном в Тефрис-Аране в Пустошах.','<Фуриен стонет.>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ничего тут для тебя нет',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Для тебя тут больше ничего не осталось, $n. А мне еще нужно похоронить тело Маши. Потом я вернусь на место бомбежки и начну ритуал восстановления. Возможно, когда-нибудь там расцветет новая роща, где будут обитать духи юных ночных эльфов и с ними мое дитя.$B$BЕсли вдруг ты $gнаправлялся:направлялась; в Пустоши, то мне говорили, будто бы некий эльф крови по имени Фуриен ищет себе смекалистых помощников. Может, вам с ним стоит переговорить.$B$BПрощай же... Я всегда буду помнить тебя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Фуриеном в Тефрис-Аране в Пустошах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Фуриен стонет.>',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26135,'Видения прошлого: подъем из глубин','Я все думаю о том, что ты $gрассказал:рассказала; о нагах. Кто их союзники? Неужели они верят, что смогут победить Хозяина Приливов?$B$BСкоро мы выберемся из этой пещеры, но сначала мы должны достигнуть поставленной цели. Надеюсь, ты согласишься в последний раз узнать что-нибудь у Воительницы.$B$BОсталось только одно место, где мог побывать этот артефакт, – храм над руинами. Но его наверняка хорошо охраняют. Будь $gосторожен:осторожна;.','Воспользуйтесь сломанным клинком Воительницы в храме Кель\'Дормир и посмотрите заключительную часть истории.','Вернитесь к говорящей с волнами Талре на базе Легиона.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Видения прошлого: подъем из глубин',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я все думаю о том, что ты $gрассказал:рассказала; о нагах. Кто их союзники? Неужели они верят, что смогут победить Хозяина Приливов?$B$BСкоро мы выберемся из этой пещеры, но сначала мы должны достигнуть поставленной цели. Надеюсь, ты согласишься в последний раз узнать что-нибудь у Воительницы.$B$BОсталось только одно место, где мог побывать этот артефакт, – храм над руинами. Но его наверняка хорошо охраняют. Будь $gосторожен:осторожна;.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь сломанным клинком Воительницы в храме Кель\'Дормир и посмотрите заключительную часть истории.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к говорящей с волнами Талре на базе Легиона.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (26135,'Слуги древнего бога? Выходит, два наших врага объединились, и их надежда победить Хозяина Приливов не так беспочвенна, как мне думалось.$B$BБумагош, этого допустить нельзя. Если Азшара одолеет Хозяина Приливов и присвоит его силу, мы никогда не соберем достаточно воинов, чтобы противостоять ей на море.$B$BНаш первый шаг очевиден – нужно выследить монстра, который уничтожил наши корабли. Военные привели новую эскадру – возможно, у них есть план.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Слуги древнего бога? Выходит, два наших врага объединились, и их надежда победить Хозяина Приливов не так беспочвенна, как мне думалось.$B$BБумагош, этого допустить нельзя. Если Азшара одолеет Хозяина Приливов и присвоит его силу, мы никогда не соберем достаточно воинов, чтобы противостоять ей на море.$B$BНаш первый шаг очевиден – нужно выследить монстра, который уничтожил наши корабли. Военные привели новую эскадру – возможно, у них есть план.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (26136,'FLAG - Rigor Mortis Removed') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','FLAG - Rigor Mortis Removed',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`) VALUES (26137,'Уверен, ты $gвидел:видела;, в каком ужасном состоянии озеро Лок сейчас. И, боюсь, этим проблемы не исчерпываются. Вся исчезнувшая вода должна была куда-то деться, и она делась – в Болотину.$b$bТам сейчас много дворфов, которые пытаются помочь, и, конечно, им всем нужны продукты. Поэтому я отправил в Болотину двух моих горных пехотинцев с бочонком эля.$b$bУ меня нет от них никаких известий с тех пор, как они отправились по дороге в Дун Альгаз. Не поищешь их?','Отправляйтесь в Болотину и поговорите с горным пехотинцем Рареном возле Дун Альгаза.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Уверен, ты $gвидел:видела;, в каком ужасном состоянии озеро Лок сейчас. И, боюсь, этим проблемы не исчерпываются. Вся исчезнувшая вода должна была куда-то деться, и она делась – в Болотину.$b$bТам сейчас много дворфов, которые пытаются помочь, и, конечно, им всем нужны продукты. Поэтому я отправил в Болотину двух моих горных пехотинцев с бочонком эля.$b$bУ меня нет от них никаких известий с тех пор, как они отправились по дороге в Дун Альгаз. Не поищешь их?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Болотину и поговорите с горным пехотинцем Рареном возле Дун Альгаза.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26138,'Ферилон Дитя Листвы','Среди ночных эльфов есть те, для кого Болотина стала новым домом. Они прибыли из Калимдора на корабле, чтобы разведать эти земли, изучить здешнюю растительность – и все такое.$B$BНе так давно у нас побывал друид по имени Ферилон. Он помог нам разобраться с ящерами. Помню, он еще жаловался, мол, ему там у себя не хватает помощников.$B$BЕсли будет время, навести его в Роще Стража Природы – это к северо-востоку отсюда.','Найдите Ферилона Дитя Листвы в Роще Стража Природы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ферилон Дитя Листвы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Среди ночных эльфов есть те, для кого Болотина стала новым домом. Они прибыли из Калимдора на корабле, чтобы разведать эти земли, изучить здешнюю растительность – и все такое.$B$BНе так давно у нас побывал друид по имени Ферилон. Он помог нам разобраться с ящерами. Помню, он еще жаловался, мол, ему там у себя не хватает помощников.$B$BЕсли будет время, навести его в Роще Стража Природы – это к северо-востоку отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Ферилона Дитя Листвы в Роще Стража Природы.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (26139,'В Арати','Тебе надо отправляться вперед и предупредить об этом другую сторону, $n.$b$bЗа мостом на севере находится Опорный пункт, крепость Альянса в Арати. Скажи капитану Ниалс, чтобы он приглядывал за этими псами из Сумеречного Молота.','Полагаю, я обязан Таргасу за то, что он прислал ко мне такого отважного героя.$B$BИли, может быть, он хотел, чтобы вся зачистка досталась ему. Неважно, в Альянсе для тебя найдется много работы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В Арати',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе надо отправляться вперед и предупредить об этом другую сторону, $n.$b$bЗа мостом на севере находится Опорный пункт, крепость Альянса в Арати. Скажи капитану Ниалс, чтобы он приглядывал за этими псами из Сумеречного Молота.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Полагаю, я обязан Таргасу за то, что он прислал ко мне такого отважного героя.$B$BИли, может быть, он хотел, чтобы вся зачистка досталась ему. Неважно, в Альянсе для тебя найдется много работы.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (26140,'Беседа с Древним','Наденьте на голову мертвого Безжалостного, чтобы замаскироваться под одного из рабов.$B$BВойдите в Л\'горека. Поговорите с Древним.','Принесите мозг Непостижимого Л\'гореку в Церебриллий в Вайш\'ире.','ВАШ ЭРУНАК... ОН... МУДРО ПРИДУМАЛ... ВЗЯТЬ... МОЗГ БЕЗЛИКОГО. ТЕПЕРЬ... Я ТЕБЯ... ВИЖУ.$B$BЯ УМРУ. ЭТО... НЕОТВРАТИМО. И НИЧЕГО... НЕЛЬЗЯ СДЕЛАТЬ.$B$BНО... ПРЕЖДЕ ЧЕМ ЭТО СЛУЧИТСЯ... ТЫ МНЕ ПОМОЖЕШЬ... РАЗДЕЛАТЬСЯ... С ЭТИМИ ПАРАЗИТАМИ.','Я ЧУВСТВУЮ... Я ЧТО-ТО ЧУВСТВУЮ. ПОДОЙДИ БЛИЖЕ...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Беседа с Древним',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наденьте на голову мертвого Безжалостного, чтобы замаскироваться под одного из рабов.$B$BВойдите в Л\'горека. Поговорите с Древним.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите мозг Непостижимого Л\'гореку в Церебриллий в Вайш\'ире.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','ВАШ ЭРУНАК... ОН... МУДРО ПРИДУМАЛ... ВЗЯТЬ... МОЗГ БЕЗЛИКОГО. ТЕПЕРЬ... Я ТЕБЯ... ВИЖУ.$B$BЯ УМРУ. ЭТО... НЕОТВРАТИМО. И НИЧЕГО... НЕЛЬЗЯ СДЕЛАТЬ.$B$BНО... ПРЕЖДЕ ЧЕМ ЭТО СЛУЧИТСЯ... ТЫ МНЕ ПОМОЖЕШЬ... РАЗДЕЛАТЬСЯ... С ЭТИМИ ПАРАЗИТАМИ.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я ЧУВСТВУЮ... Я ЧТО-ТО ЧУВСТВУЮ. ПОДОЙДИ БЛИЖЕ...',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26141,'С ПОМОЩЬЮ... ЭТИХ... РУННЫХ КАМНЕЙ... ТЫ ЗАВЛАДЕЕШЬ... ОДНИМ ИЗ... ВОДНЫХ ЭЛЕМЕНТАЛЕЙ.','Вернитесь к Л\'гореку в Церебриллий в Вайш\'ире.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','С ПОМОЩЬЮ... ЭТИХ... РУННЫХ КАМНЕЙ... ТЫ ЗАВЛАДЕЕШЬ... ОДНИМ ИЗ... ВОДНЫХ ЭЛЕМЕНТАЛЕЙ.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Л\'гореку в Церебриллий в Вайш\'ире.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26142,'Теперь они не переродятся!','ЧТОБЫ... ИХ ОСТАНОВИТЬ... НАДО УНИЧТОЖИТЬ... ДРЕВНИЕ КАНАЛЫ.$B$BПО НИМ ОНИ ВЫКАЧИВАЮТ... ИЗ МЕНЯ... ЭНЕРГИЮ... И СОЗДАЮТ... ПЕРЕРОЖДЕННЫХ.$B$BСРАЖЕНИЕ С... НЕПТУЛОНОМ... НЕОТВРАТИМО. СУМЕРЕЧНЫЙ МОЛОТ... НЕ ДОЛЖЕН ПОЛУЧИТЬ... ЭТИХ ТВАРЕЙ.','Уничтожьте 5 древних каналов.','ТЕПЕРЬ... ОНИ БОЛЬШЕ НЕ ПЕРЕРОДЯТСЯ! НИКОГДА!','Вернитесь к Л\'гореку в Церебриллий в Вайш\'ире.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Теперь они не переродятся!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','ЧТОБЫ... ИХ ОСТАНОВИТЬ... НАДО УНИЧТОЖИТЬ... ДРЕВНИЕ КАНАЛЫ.$B$BПО НИМ ОНИ ВЫКАЧИВАЮТ... ИЗ МЕНЯ... ЭНЕРГИЮ... И СОЗДАЮТ... ПЕРЕРОЖДЕННЫХ.$B$BСРАЖЕНИЕ С... НЕПТУЛОНОМ... НЕОТВРАТИМО. СУМЕРЕЧНЫЙ МОЛОТ... НЕ ДОЛЖЕН ПОЛУЧИТЬ... ЭТИХ ТВАРЕЙ.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 5 древних каналов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','ТЕПЕРЬ... ОНИ БОЛЬШЕ НЕ ПЕРЕРОДЯТСЯ! НИКОГДА!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Л\'гореку в Церебриллий в Вайш\'ире.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26143,'Халлазил Перерожденный','<Голос Древнего врезается вам в сознание.>$B$BТЕПЕРЬ... КОГДА ТЫ $gЗАБРАЛ:ЗАБРАЛА;... ЭНЕРГИЮ... ЭТИХ ФАНАТИКОВ, ВОЙДИ... В ХРАМ... И УНИЧТОЖЬ... ХАЛЛАЗИЛА ПЕРЕРОЖДЕННОГО!','Уничтожьте Халлазила Перерожденного.','ТЫ СОСЛУЖИЛ... НАМ... ХОРОШУЮ СЛУЖБУ. И МНЕ... И ХОЗЯИНУ ПРИЛИВОВ.','Вернитесь к Л\'гореку в Церебриллий в Вайш\'ире.','Воспользуйтесь потоком, чтобы уничтожить Халлазила Перерожденного.','Халлазил Перерожденный') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Халлазил Перерожденный',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Голос Древнего врезается вам в сознание.>$B$BТЕПЕРЬ... КОГДА ТЫ $gЗАБРАЛ:ЗАБРАЛА;... ЭНЕРГИЮ... ЭТИХ ФАНАТИКОВ, ВОЙДИ... В ХРАМ... И УНИЧТОЖЬ... ХАЛЛАЗИЛА ПЕРЕРОЖДЕННОГО!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте Халлазила Перерожденного.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','ТЫ СОСЛУЖИЛ... НАМ... ХОРОШУЮ СЛУЖБУ. И МНЕ... И ХОЗЯИНУ ПРИЛИВОВ.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Л\'гореку в Церебриллий в Вайш\'ире.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Воспользуйтесь потоком, чтобы уничтожить Халлазила Перерожденного.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Халлазил Перерожденный',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (26144,'Пленники') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пленники',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26145,'Угроза со стороны троггов','$C, не уверен, что ты знаешь об исходящей от троггов опасности, нависшей над дворфийскими землями. Внутренние войска Стальгорна отправлены на фронт Альянса, мы располагаем лишь небольшими оборонительными силами. Мой полк охраняет город, и мы не можем покинуть пост из-за опасности нападения.$b$bНо мы должны усилить натиск на троггов, расселившихся на холмах. Если эта задача тебе по плечу, проведи вылазку в их стан. В доказательство принеси 8 каменных зубов троггов.','Соберите 8 каменных зубов троггов.','Вернитесь к горному пехотинцу Кремневику в Долину Королей, что в Лок Модане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Угроза со стороны троггов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$C, не уверен, что ты знаешь об исходящей от троггов опасности, нависшей над дворфийскими землями. Внутренние войска Стальгорна отправлены на фронт Альянса, мы располагаем лишь небольшими оборонительными силами. Мой полк охраняет город, и мы не можем покинуть пост из-за опасности нападения.$b$bНо мы должны усилить натиск на троггов, расселившихся на холмах. Если эта задача тебе по плечу, проведи вылазку в их стан. В доказательство принеси 8 каменных зубов троггов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 каменных зубов троггов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к горному пехотинцу Кремневику в Долину Королей, что в Лок Модане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (26145,'Я впечатлен, Няммчик. Защитив наши земли, ты оказал дворфам огромную услугу. Сам король Магни Бронзобород будет гордиться тобой!','Ты принес мне 8 каменных зубов троггов? Если нет, тебе придется еще поработать, Няммчик.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я впечатлен, Няммчик. Защитив наши земли, ты оказал дворфам огромную услугу. Сам король Магни Бронзобород будет гордиться тобой!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты принес мне 8 каменных зубов троггов? Если нет, тебе придется еще поработать, Няммчик.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26147,'Больше и страшнее','Горные пехотинцы говорят, что ты довольно $gсилен и отважен:сильна и отважна;, $n. Нам здесь пригодится |3-6($r) вроде тебя. Мы никак не можем справиться с троггами. Все бойцы на фронте, и мы остались тут без всякой помощи. Но раз теперь с нами $gбывалый:бывалая:c; |3-6($c), посмотрим, что мы сможем сделать.$b$bИди и убей 8 шаманов из племени Камнедробов и 8 костегрызов из племени Камнедробов. Их можно найти около и внутри пещер в южных горах.$b$bПосмотрим, не преувеличены ли слухи о твоей отваге, гроза троггов.','Убейте 8 шаманов из племени Камнедробов и 8 костегрызов из племени Камнедробов.','Вернитесь к горному пехотинцу Стенолому в Долину Королей в Лок Модане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Больше и страшнее',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Горные пехотинцы говорят, что ты довольно $gсилен и отважен:сильна и отважна;, $n. Нам здесь пригодится |3-6($r) вроде тебя. Мы никак не можем справиться с троггами. Все бойцы на фронте, и мы остались тут без всякой помощи. Но раз теперь с нами $gбывалый:бывалая:c; |3-6($c), посмотрим, что мы сможем сделать.$b$bИди и убей 8 шаманов из племени Камнедробов и 8 костегрызов из племени Камнедробов. Их можно найти около и внутри пещер в южных горах.$b$bПосмотрим, не преувеличены ли слухи о твоей отваге, гроза троггов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 шаманов из племени Камнедробов и 8 костегрызов из племени Камнедробов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к горному пехотинцу Стенолому в Долину Королей в Лок Модане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (26147,'В ту самую секунду, как я увидел тебя, Стентс, я уже знал, что Стальгорн будет гордиться тобой. Ты оказал большую услугу нашему народу. Я восхищаюсь тобой, Стентс.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','В ту самую секунду, как я увидел тебя, Стентс, я уже знал, что Стальгорн будет гордиться тобой. Ты оказал большую услугу нашему народу. Я восхищаюсь тобой, Стентс.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26148,'Решающий удар','Похоже, этими тварями в Лок Модане руководит вождь по имени Громаг. Это огромный трогг, он прячется в глубине пещер к северу отсюда.$b$bЕсли ты чувствуешь, что справишься с этим, я бы хотел, чтобы ты $gвозглавил:возглавила; нападение на Громага.','Убейте Громага.','Вернитесь к капитану Ругельфассу в Долину Королей в Лок Модане.','Убей его!','Громаг') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Решающий удар',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Похоже, этими тварями в Лок Модане руководит вождь по имени Громаг. Это огромный трогг, он прячется в глубине пещер к северу отсюда.$b$bЕсли ты чувствуешь, что справишься с этим, я бы хотел, чтобы ты $gвозглавил:возглавила; нападение на Громага.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Громага.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Ругельфассу в Долину Королей в Лок Модане.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Убей его!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Громаг',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (26148,'Превосходно, Няммчик! Ты вернул надежду Лок Модану. Громаг мертв, и нам будет проще изгнать троггов из наших земель.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Превосходно, Няммчик! Ты вернул надежду Лок Модану. Громаг мертв, и нам будет проще изгнать троггов из наших земель.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26149,'Пленники','Этот ключ был у одного из сектантов Сумеречного Молота. Возьми ключ и освободи узников из Орды. Их держат в клетках в Л\'гореке.$B$BПоторопись, пока узников не принесли в жертву тому, кто таится в глубине!','Спасите 5 узников из Орды.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пленники',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этот ключ был у одного из сектантов Сумеречного Молота. Возьми ключ и освободи узников из Орды. Их держат в клетках в Л\'гореке.$B$BПоторопись, пока узников не принесли в жертву тому, кто таится в глубине!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Спасите 5 узников из Орды.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26150,'Навестить Мейбелл','Похоже, от тебя будет прок, $n. Как насчет услуги старику?$b$bКогда я последний раз был на виноградниках Маклура, я слышал, как Мейбелл плачет в своем доме. Не будешь ли ты так $gдобр:добра;, чтобы навестить ее? Я немного беспокоюсь.','Поговорите с Мейбелл Маклур на виноградниках Маклур в Элвиннском лесу.','Тебя прислал Вильям? Святая душа. Я… У меня все в порядке… Я просто… В общем…') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Навестить Мейбелл',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Похоже, от тебя будет прок, $n. Как насчет услуги старику?$b$bКогда я последний раз был на виноградниках Маклура, я слышал, как Мейбелл плачет в своем доме. Не будешь ли ты так $gдобр:добра;, чтобы навестить ее? Я немного беспокоюсь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Мейбелл Маклур на виноградниках Маклур в Элвиннском лесу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебя прислал Вильям? Святая душа. Я… У меня все в порядке… Я просто… В общем…',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26151,'Зловещее письмо','Мне было приказано передать это тебе, как только ты вернешься из лагерей кобольдов, $n. Письмо запечатано эмблемой Бездны – вне всяких сомнений, это послание от местного наставника чернокнижников. Другие дела в аббатстве могут подождать – узнай-ка лучше сначала, о чем говорится в этом письме.','Прочитайте зловещее письмо и поговорите с Друзиллой ла Салле на кладбище в долине Североземья.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зловещее письмо',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне было приказано передать это тебе, как только ты вернешься из лагерей кобольдов, $n. Письмо запечатано эмблемой Бездны – вне всяких сомнений, это послание от местного наставника чернокнижников. Другие дела в аббатстве могут подождать – узнай-ка лучше сначала, о чем говорится в этом письме.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Прочитайте зловещее письмо и поговорите с Друзиллой ла Салле на кладбище в долине Североземья.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26152,'Убейте Джеймса Кларка и заберите его голову.','Правосудие свершилось!','Пришел за вознаграждением?','Отнесите голову Джеймса Кларка маршалу Маккри на лесопилку Восточной долины в Элвиннском лесу.') ON DUPLICATE KEY UPDATE `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Джеймса Кларка и заберите его голову.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Правосудие свершилось!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Пришел за вознаграждением?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите голову Джеймса Кларка маршалу Маккри на лесопилку Восточной долины в Элвиннском лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26153,'Тыквенные оладьи Пэнни','Моя дочь Пэнни обожает тыквенные оладьи, однако тыква у нас тут в Элвиннском лесу в этом году не уродилась – заморозки... Зато я слыхал о тыквенной грядке к северу от Штормграда, где тыква, должно быть, как раз поспела. Пойди и раздобудь несколько спелых тыкв, а там поглядим, что у нас получится.','Раздобудьте 6 штормградских тыкв. Принесите их Робби Флею в Штормграде.','Отлично, Лафроиг! Пэнни будет в восторге!','Вернитесь к Робби Флею в Штормград.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тыквенные оладьи Пэнни',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Моя дочь Пэнни обожает тыквенные оладьи, однако тыква у нас тут в Элвиннском лесу в этом году не уродилась – заморозки... Зато я слыхал о тыквенной грядке к северу от Штормграда, где тыква, должно быть, как раз поспела. Пойди и раздобудь несколько спелых тыкв, а там поглядим, что у нас получится.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте 6 штормградских тыкв. Принесите их Робби Флею в Штормграде.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, Лафроиг! Пэнни будет в восторге!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Робби Флею в Штормград.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26154,'Искоренение Сумеречного Молота','ТЕПЕРЬ ВОЗЬМИ... ЗАГОВОРЕННЫЙ РУНИЧЕСКИЙ КАМЕНЬ... И С ЕГО ПОМОЩЬЮ... ПОДЧИНИ... ОДИН ИЗ... СКОВАННЫХ ПОТОКОВ... В ЦЕНТРАЛЬНОМ ХРАМЕ. ОНИ ТЕБЯ... НЕ ЗАМЕТЯТ. ТЫ БУДЕШЬ ДЛЯ НИХ... НЕВИДИМКОЙ.$B$BИСПОЛЬЗУЙ... СИЛУ ЭЛЕМЕНТАЛЯ... ЧТОБЫ УНИЧТОЖИТЬ... ПРИВЕРЖЕНЦЕВ... КУЛЬТА СУМЕРЕЧНОГО МОЛОТА... И... ИХ БЕЗЛИКИХ НАДЗИРАТЕЛЕЙ.','Подчините себе скованный поток и уничтожьте 50 сумеречных энтузиастов и 10 безликих надзирателей.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Искоренение Сумеречного Молота',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','ТЕПЕРЬ ВОЗЬМИ... ЗАГОВОРЕННЫЙ РУНИЧЕСКИЙ КАМЕНЬ... И С ЕГО ПОМОЩЬЮ... ПОДЧИНИ... ОДИН ИЗ... СКОВАННЫХ ПОТОКОВ... В ЦЕНТРАЛЬНОМ ХРАМЕ. ОНИ ТЕБЯ... НЕ ЗАМЕТЯТ. ТЫ БУДЕШЬ ДЛЯ НИХ... НЕВИДИМКОЙ.$B$BИСПОЛЬЗУЙ... СИЛУ ЭЛЕМЕНТАЛЯ... ЧТОБЫ УНИЧТОЖИТЬ... ПРИВЕРЖЕНЦЕВ... КУЛЬТА СУМЕРЕЧНОГО МОЛОТА... И... ИХ БЕЗЛИКИХ НАДЗИРАТЕЛЕЙ.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Подчините себе скованный поток и уничтожьте 50 сумеречных энтузиастов и 10 безликих надзирателей.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26155,'Черная угроза не забыта','Много лет назад Черное Железо пыталось разрушить Каменную Плотину. Мойра, наверное, неплохо устроилась в новом красивом Сенате Стальгорна, но я не собираюсь забывать прошлое, особенно когда они ходят вокруг озера толпами, как будто приехали сюда на экскурсию.$b$bЯ хочу, чтобы ты $gотправился:отправилась; туда и $gвыяснил:выяснила;, что они затевают. Разузнай их планы. Без всяких сомнений их можно найти в центре их лагеря.$b$bПостарайся, чтобы тебя не заметили... но если так случится, защищайся, $n. Я бы не хотел потерять $gхорошего:хорошую:r; |3-1($r).','Раздобудьте чертежи Каменной Плотины в лагере Черного Железа в центре озера Лок.','Вернитесь к Ашлану Камнехмылу в лагерь Мо\'грош в Лок Модане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Черная угроза не забыта',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Много лет назад Черное Железо пыталось разрушить Каменную Плотину. Мойра, наверное, неплохо устроилась в новом красивом Сенате Стальгорна, но я не собираюсь забывать прошлое, особенно когда они ходят вокруг озера толпами, как будто приехали сюда на экскурсию.$b$bЯ хочу, чтобы ты $gотправился:отправилась; туда и $gвыяснил:выяснила;, что они затевают. Разузнай их планы. Без всяких сомнений их можно найти в центре их лагеря.$b$bПостарайся, чтобы тебя не заметили... но если так случится, защищайся, $n. Я бы не хотел потерять $gхорошего:хорошую:r; |3-1($r).',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте чертежи Каменной Плотины в лагере Черного Железа в центре озера Лок.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ашлану Камнехмылу в лагерь Мо\'грош в Лок Модане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26156,'Все люди короля','Возможно, Каменная Плотина уже повреждена, $n, но она не просто сдерживает воду. Теперь все висит на волоске. Равновесие этих земель и так уже нарушено, и если они взорвут оставшуюся часть плотины...$b$b...половина Лок Модана может погибнуть! Последствия будут даже более катастрофическими. Если мы не будем действовать быстро, мы окажемся в гигантской воронке.$b$bОтправляйся на Каменную Плотину и останови этих саперов из клана Черного Железа. Убедись, что никого из них не осталось!','Убейте 6 саперов из клана Черного Железа.','Вернитесь к Ашлану Камнехмылу в лагерь Мо\'грош в Лок Модане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Все люди короля',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Возможно, Каменная Плотина уже повреждена, $n, но она не просто сдерживает воду. Теперь все висит на волоске. Равновесие этих земель и так уже нарушено, и если они взорвут оставшуюся часть плотины...$b$b...половина Лок Модана может погибнуть! Последствия будут даже более катастрофическими. Если мы не будем действовать быстро, мы окажемся в гигантской воронке.$b$bОтправляйся на Каменную Плотину и останови этих саперов из клана Черного Железа. Убедись, что никого из них не осталось!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 6 саперов из клана Черного Железа.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ашлану Камнехмылу в лагерь Мо\'грош в Лок Модане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26157,'Касым Шарим','Мне нужно кое-кому кое-что передать. Возьмешься доставить мое сообщение?$B$BКасым Шарим – старый волшебник крови. Он знает о демонах в Выжженных землях больше, чем кто бы то ни было. Хотя по нему и не скажешь... Он очень старый и очень сильный... правда, чуть-чуть странноватый, так что не пугайся. Ты найдешь его в Змеиных Кольцах, в пещерах неподалеку от того места, где ты $gрасправился:расправилась; с теми cектантами.$B$BПожалуйста, передай ему эту записку. Он поймет, что к чему.','Разыщите Касыма Шарима в пещерах Змеиные Кольца в Выжженных землях.','Я тебя не знаю.','Волшебник крови и эксцентричный отшельник','Касым Шарим') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Касым Шарим',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне нужно кое-кому кое-что передать. Возьмешься доставить мое сообщение?$B$BКасым Шарим – старый волшебник крови. Он знает о демонах в Выжженных землях больше, чем кто бы то ни было. Хотя по нему и не скажешь... Он очень старый и очень сильный... правда, чуть-чуть странноватый, так что не пугайся. Ты найдешь его в Змеиных Кольцах, в пещерах неподалеку от того места, где ты $gрасправился:расправилась; с теми cектантами.$B$BПожалуйста, передай ему эту записку. Он поймет, что к чему.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите Касыма Шарима в пещерах Змеиные Кольца в Выжженных землях.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я тебя не знаю.',`requestitemstext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Волшебник крови и эксцентричный отшельник',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Касым Шарим',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26158,'Настроиться на кровавый камень','Я так понимаю, в пещеру ты $gпробивался:пробивалась; с боем. Надеюсь, тебе было весело. Да, надо признаться, я выбрал не самое... э... подходящее место для своих изысканий. И особенно неподходящее – для любопытных искателей приключений, которые предпочли бы заходить сюда, как к себе домой.$B$BПожалуй, я позволю тебе настроиться на свои телепортирующие кровавые камни. Тут все очень просто. Положи руки на камень в том дальнем углу – и сразу телепортируешься из пещеры. А чтобы телепортироваться обратно, используй камень, который снаружи!','Научитесь использовать телепортирующие кровавые камни в Змеиных Кольцах.','Вот и славно! Тебе удалось выполнить простейшее из заданий и при этом остаться в живых. На такое способен не каждый… далеко не каждый…','Вернитесь к Касыму Шариму в Змеиные Кольца, что в Выжженных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Настроиться на кровавый камень',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я так понимаю, в пещеру ты $gпробивался:пробивалась; с боем. Надеюсь, тебе было весело. Да, надо признаться, я выбрал не самое... э... подходящее место для своих изысканий. И особенно неподходящее – для любопытных искателей приключений, которые предпочли бы заходить сюда, как к себе домой.$B$BПожалуй, я позволю тебе настроиться на свои телепортирующие кровавые камни. Тут все очень просто. Положи руки на камень в том дальнем углу – и сразу телепортируешься из пещеры. А чтобы телепортироваться обратно, используй камень, который снаружи!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Научитесь использовать телепортирующие кровавые камни в Змеиных Кольцах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот и славно! Тебе удалось выполнить простейшее из заданий и при этом остаться в живых. На такое способен не каждый… далеко не каждый…',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Касыму Шариму в Змеиные Кольца, что в Выжженных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26159,'Первый шаг','Как и всякому настоящему волшебнику крови, для сотворения магии мне нужна кровь. Кровь крови рознь, но здесь, в Выжженных землях, есть несколько очень даже пригодных... сортов, скажем так. Главное – знать, где искать.$B$BДля наших целей? Кровь василиска и кровь гиены, в равных пропорциях. Но ее нужно много. Иди на запад, в самый центр Выжженных земель. И не забудь... теперь тебе можно пользоваться телепортом!','Раздобудьте 9 флаконов крови хохочущей гиены и 9 флаконов крови краснокаменного василиска.','<Касым смотрит на кровь голодными глазами.>$B$BДаже более, чем достаточно! И она еще теплая! Ну, что же… начнем ритуал!','Вернитесь к Касыму Шариму в Змеиные Кольца, что в Выжженных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Первый шаг',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как и всякому настоящему волшебнику крови, для сотворения магии мне нужна кровь. Кровь крови рознь, но здесь, в Выжженных землях, есть несколько очень даже пригодных... сортов, скажем так. Главное – знать, где искать.$B$BДля наших целей? Кровь василиска и кровь гиены, в равных пропорциях. Но ее нужно много. Иди на запад, в самый центр Выжженных земель. И не забудь... теперь тебе можно пользоваться телепортом!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте 9 флаконов крови хохочущей гиены и 9 флаконов крови краснокаменного василиска.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Касым смотрит на кровь голодными глазами.>$B$BДаже более, чем достаточно! И она еще теплая! Ну, что же… начнем ритуал!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Касыму Шариму в Змеиные Кольца, что в Выжженных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (26160,'Ритуал крови','Тебе, наверное, интересно, что мы сейчас будем делать. Я тебе расскажу... вкратце. А рассказывать вкратце я мастер.$B$BСектанты культа Приверженцев Тени хотят вызвать демона, Разелиха, и вернуть его в Выжженные земли. Этого нельзя допустить! Поэтому мы вызовем демона сами. Вызовем и убьем. Но ты не думай, что это легко. На словах-то все просто, а вот на деле...$B$BДай мне знать, когда будешь $gготов:готова;, и я начну ритуал.','Поговорите с Касымом Шаримом, чтобы начать ритуал крови.','Ритуал крови прошел успешно. Я уже знаю, что нам делать дальше.$B$BОй, прости. Оговорился. Хотел сказать: я уже знаю, что ТЕБЕ делать дальше…','Поговорите с Касымом Шаримом, чтобы начать ритуал.','Вернитесь к Касыму Шариму в Змеиные Кольца, что в Выжженных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ритуал крови',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе, наверное, интересно, что мы сейчас будем делать. Я тебе расскажу... вкратце. А рассказывать вкратце я мастер.$B$BСектанты культа Приверженцев Тени хотят вызвать демона, Разелиха, и вернуть его в Выжженные земли. Этого нельзя допустить! Поэтому мы вызовем демона сами. Вызовем и убьем. Но ты не думай, что это легко. На словах-то все просто, а вот на деле...$B$BДай мне знать, когда будешь $gготов:готова;, и я начну ритуал.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Касымом Шаримом, чтобы начать ритуал крови.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ритуал крови прошел успешно. Я уже знаю, что нам делать дальше.$B$BОй, прости. Оговорился. Хотел сказать: я уже знаю, что ТЕБЕ делать дальше…',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Поговорите с Касымом Шаримом, чтобы начать ритуал.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Касыму Шариму в Змеиные Кольца, что в Выжженных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26161,'По кусочкам','Нам нужен Лорам Многоног, охотник на демонов. Он знает истинное имя Разелиха, а тебе, я думаю, известно: тот, кто знает настоящее имя демона, получает над ним безграничную власть. Проблема в том, что Лорам убит, а его тело разорвано на куски.$B$BНо если ты соберешь все куски и принесешь их сюда, мы сможем узнать то, что нам нужно. Они все на западе, все три куска... огры Молота Ужаса прячут их у себя в пещерах. Иди прямо сейчас. Кстати, как и за Гримео, за Лорамом остался должок...','Разыщите голову, туловище и ноги Лорама.','Да… Да, с этим можно работать.$B$B<Касым смотрит на голову ночного эльфа.>$B$BЛорам Многоног, охотник на демонов. Очень скоро мы встретимся вновь.','Можешь не сомневаться... то, что случилось с Лорамом, поправимо. Сила магии крови поистине безгранична!','Вернитесь к Касыму Шариму в Змеиные Кольца, что в Выжженных землях.','Охотник на демонов собственной персоной.','Лорам Многоног') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','По кусочкам',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нам нужен Лорам Многоног, охотник на демонов. Он знает истинное имя Разелиха, а тебе, я думаю, известно: тот, кто знает настоящее имя демона, получает над ним безграничную власть. Проблема в том, что Лорам убит, а его тело разорвано на куски.$B$BНо если ты соберешь все куски и принесешь их сюда, мы сможем узнать то, что нам нужно. Они все на западе, все три куска... огры Молота Ужаса прячут их у себя в пещерах. Иди прямо сейчас. Кстати, как и за Гримео, за Лорамом остался должок...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите голову, туловище и ноги Лорама.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да… Да, с этим можно работать.$B$B<Касым смотрит на голову ночного эльфа.>$B$BЛорам Многоног, охотник на демонов. Очень скоро мы встретимся вновь.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Можешь не сомневаться... то, что случилось с Лорамом, поправимо. Сила магии крови поистине безгранична!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Касыму Шариму в Змеиные Кольца, что в Выжженных землях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Охотник на демонов собственной персоной.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Лорам Многоног',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26162,'Высоко в скалах на западе расположен могущественный алтарь. Могущественный ДЕМОНИЧЕСКИЙ алтарь, который охраняют сектанты. Если сможешь добраться до алтаря, ты сумеешь вернуть нам Лорама.$B$BСкорее всего, алтарь станет сопротивляться. Так что тебе надо будет охранять тело Лорама, пока идет ритуал воскрешения. Когда все закончится, приведи охотника на демонов ко мне.','Ах ты… бестолочь! Что ты наделал?!','Вернитесь к Лораму Многоногу в Змеиные Кольца, что в Выжженных землях.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Высоко в скалах на западе расположен могущественный алтарь. Могущественный ДЕМОНИЧЕСКИЙ алтарь, который охраняют сектанты. Если сможешь добраться до алтаря, ты сумеешь вернуть нам Лорама.$B$BСкорее всего, алтарь станет сопротивляться. Так что тебе надо будет охранять тело Лорама, пока идет ритуал воскрешения. Когда все закончится, приведи охотника на демонов ко мне.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ах ты… бестолочь! Что ты наделал?!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лораму Многоногу в Змеиные Кольца, что в Выжженных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26163,'Времени нет','Разелих собирается вернуться в Выжженные земли и захватить Азерот со своей армией демонов. Прямо сейчас, в эту минуту, он готовится призвать свои легионы, чтобы всех нас истребить. Эти три амулета помогут нам вызвать Разелиха... но никак не помогут его уничтожить.$B$B<Гном рисует в воздухе руну, материализует ее и отдает вам.>$B$BВот. Отнеси ее Гримео, его можно найти у Темного портала, на юго-востоке отсюда. Он тебе скажет, что делать дальше. И поторопись! У нас мало времени!','Отнесите диссонирующую руну дозорному Гримео у Темного портала в Выжженных землях.','Нет, только не это! Опять Касым! Это безумие! Нет, нет, нет…$B$BЯ тебя очень прошу, говори тише. Если мой командир узнает, что я по-прежнему работаю на гнома, я полечу с этой должности в тот же час и со свистом!$B$B<Гримео берет у вас руну, прижимает ее к груди, закрывает глаза и вздыхает.>$B$BЯ вижу, ты говоришь правду. Так что давай побыстрее начнем. Знаешь, как говорится: раньше сядешь, раньше выйдешь…','Вернитесь к дозорному Гримео в Темный портал, что в Выжженных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Времени нет',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Разелих собирается вернуться в Выжженные земли и захватить Азерот со своей армией демонов. Прямо сейчас, в эту минуту, он готовится призвать свои легионы, чтобы всех нас истребить. Эти три амулета помогут нам вызвать Разелиха... но никак не помогут его уничтожить.$B$B<Гном рисует в воздухе руну, материализует ее и отдает вам.>$B$BВот. Отнеси ее Гримео, его можно найти у Темного портала, на юго-востоке отсюда. Он тебе скажет, что делать дальше. И поторопись! У нас мало времени!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите диссонирующую руну дозорному Гримео у Темного портала в Выжженных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Нет, только не это! Опять Касым! Это безумие! Нет, нет, нет…$B$BЯ тебя очень прошу, говори тише. Если мой командир узнает, что я по-прежнему работаю на гнома, я полечу с этой должности в тот же час и со свистом!$B$B<Гримео берет у вас руну, прижимает ее к груди, закрывает глаза и вздыхает.>$B$BЯ вижу, ты говоришь правду. Так что давай побыстрее начнем. Знаешь, как говорится: раньше сядешь, раньше выйдешь…',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к дозорному Гримео в Темный портал, что в Выжженных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26164,'Обугленный гранит у Темного портала','Касым хочет, чтобы ты $gнабрал:набрала; гранитных осколков вокруг Темного портала. Уж не знаю, зачем ему эти осколки, но мне что-то подсказывает, что это отнюдь не безобидные камушки.$B$BВот тебе кирка. Иди к порталу и набери мелких осколков по радиусу взрыва.','Соберите 24 обугленных гранитных осколка.','Надеюсь, это именно то, о чем просит гном.','Т-сс, тише. Не надо кричать.','Вернитесь к дозорному Гримео в Темный портал, что в Выжженных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обугленный гранит у Темного портала',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Касым хочет, чтобы ты $gнабрал:набрала; гранитных осколков вокруг Темного портала. Уж не знаю, зачем ему эти осколки, но мне что-то подсказывает, что это отнюдь не безобидные камушки.$B$BВот тебе кирка. Иди к порталу и набери мелких осколков по радиусу взрыва.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 24 обугленных гранитных осколка.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Надеюсь, это именно то, о чем просит гном.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Т-сс, тише. Не надо кричать.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к дозорному Гримео в Темный портал, что в Выжженных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26165,'Поганая кровь демонов','Шариму нужна кровь демонов. Сказать по правде, она и на кровь-то совсем не похожа – жидкий гной, не иначе! Хотя в данном случае это не важно... хочешь – не хочешь, а придется ее собирать.$B$BТебе повезло: здесь, вокруг Темного портала, этих демонов – хоть пруд пруди. Инферналы, гончие Скверны, стражи Скверны... так что ты быстренько соберешь все, что тебе нужно.','Соберите 7 бутылок жуткой крови демонов.','Да, это точно кровь демонов, можно не сомневаться.$B$BДаже безотносительно поручения Касыма, думаю, мой командир будет очень тебе благодарен. В последние время наши только и делают, что сражаются с демонами, а ты вон скольких прибил за раз… Это хорошая помощь стражам.','Фу, ну и запах! Это от тебя или от этой крови такая вонища?','Вернитесь к дозорному Гримео в Темный портал, что в Выжженных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поганая кровь демонов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Шариму нужна кровь демонов. Сказать по правде, она и на кровь-то совсем не похожа – жидкий гной, не иначе! Хотя в данном случае это не важно... хочешь – не хочешь, а придется ее собирать.$B$BТебе повезло: здесь, вокруг Темного портала, этих демонов – хоть пруд пруди. Инферналы, гончие Скверны, стражи Скверны... так что ты быстренько соберешь все, что тебе нужно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 7 бутылок жуткой крови демонов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, это точно кровь демонов, можно не сомневаться.$B$BДаже безотносительно поручения Касыма, думаю, мой командир будет очень тебе благодарен. В последние время наши только и делают, что сражаются с демонами, а ты вон скольких прибил за раз… Это хорошая помощь стражам.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Фу, ну и запах! Это от тебя или от этой крови такая вонища?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к дозорному Гримео в Темный портал, что в Выжженных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26166,'Дальнейшая подготовка','<Гримео заканчивает упаковывать материалы в аккуратный сверток.>$B$BЗдесь все, о чем просил гном. Непременно передай ему, что это последнее поручение, которое я для него выполняю. Да, я был у него в долгу, но теперь расплатился сполна, и больше я с ним никаких дел иметь не хочу.','Отнесите посылку Гримео Касыму Шариму в пещеры Змеиные Кольца в Выжженных землях.','Да, это именно то, что нужно. Если снова встретишь Гримео, передай ему, что я остался доволен его работой, но нет… он еще не расплатился с долгами. Сейчас я займусь изготовлением каменного ножа опечатывания. Все вопросы потом. Придет время – ты все узнаешь.$B$BПока я буду занят, для тебя тоже найдется работа.$B$BИ не делай такое кислое лицо! Будет весело… вот увидишь! Собирать части тела всегда весело.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дальнейшая подготовка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Гримео заканчивает упаковывать материалы в аккуратный сверток.>$B$BЗдесь все, о чем просил гном. Непременно передай ему, что это последнее поручение, которое я для него выполняю. Да, я был у него в долгу, но теперь расплатился сполна, и больше я с ним никаких дел иметь не хочу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите посылку Гримео Касыму Шариму в пещеры Змеиные Кольца в Выжженных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, это именно то, что нужно. Если снова встретишь Гримео, передай ему, что я остался доволен его работой, но нет… он еще не расплатился с долгами. Сейчас я займусь изготовлением каменного ножа опечатывания. Все вопросы потом. Придет время – ты все узнаешь.$B$BПока я буду занят, для тебя тоже найдется работа.$B$BИ не делай такое кислое лицо! Будет весело… вот увидишь! Собирать части тела всегда весело.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26167,'Амулет Аллистария','Для того чтобы вызвать нашего демона, нам нужны три амулета. Первый – это амулет Аллистария.$B$BСамого Аллистария уже нет в живых, но его амулет хранится в сокровищнице в этой самой пещере. Вместе с двумя остальными, этот амулет поможет нам вызвать Разелиха Осквернителя.$B$B<Касым на мгновение задумывается.>$B$BАмулет где-то близко ко входу. Я настоятельно рекомендую воспользоваться телепортом.','Раздобудьте амулет Аллистария в пещерах Змеиные Кольца в Выжженных землях.','<Касым внимательно изучает амулет.>$B$BОн был верховным магом, я это чувствую. Тебе нужно добыть еще два амулета, а этот пока будет здесь, у меня.','Аллистарий заключил в этом амулете частичку себя. Даже сейчас я чувствую его злую волю.','Вернитесь к Касыму Шариму в Змеиные Кольца, что в Выжженных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Амулет Аллистария',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Для того чтобы вызвать нашего демона, нам нужны три амулета. Первый – это амулет Аллистария.$B$BСамого Аллистария уже нет в живых, но его амулет хранится в сокровищнице в этой самой пещере. Вместе с двумя остальными, этот амулет поможет нам вызвать Разелиха Осквернителя.$B$B<Касым на мгновение задумывается.>$B$BАмулет где-то близко ко входу. Я настоятельно рекомендую воспользоваться телепортом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте амулет Аллистария в пещерах Змеиные Кольца в Выжженных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Касым внимательно изучает амулет.>$B$BОн был верховным магом, я это чувствую. Тебе нужно добыть еще два амулета, а этот пока будет здесь, у меня.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Аллистарий заключил в этом амулете частичку себя. Даже сейчас я чувствую его злую волю.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Касыму Шариму в Змеиные Кольца, что в Выжженных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26168,'Амулет Севины','Второй амулет – амулет Севины – сейчас в руках у мурлока, что живет далеко на юге, на скале над Берегом Обломков. Не знаю, как он попал к этому мурлоку, но я точно уверен, что именно там ты его и найдешь.$B$BНайдешь, заберешь и принесешь сюда.','Раздобудьте амулет Севины у Солюна близ Берега Обломков в Выжженных землях.','<Касым взвешивает на руке амулет.>$B$BЧернокнижница… Причем, очень сильная. Осталось добыть последний, третий амулет.','Амулет Севины... вместе с двумя другими амулетами он поможет нам вызвать Осквернителя.','Вернитесь к Касыму Шариму в Змеиные Кольца, что в Выжженных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Амулет Севины',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Второй амулет – амулет Севины – сейчас в руках у мурлока, что живет далеко на юге, на скале над Берегом Обломков. Не знаю, как он попал к этому мурлоку, но я точно уверен, что именно там ты его и найдешь.$B$BНайдешь, заберешь и принесешь сюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте амулет Севины у Солюна близ Берега Обломков в Выжженных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Касым взвешивает на руке амулет.>$B$BЧернокнижница… Причем, очень сильная. Осталось добыть последний, третий амулет.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Амулет Севины... вместе с двумя другими амулетами он поможет нам вызвать Осквернителя.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Касыму Шариму в Змеиные Кольца, что в Выжженных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26169,'Амулет Грола','Грол... огр.$B$B<Касым смеется.>$B$BТело Грола, как я понимаю, не покоится среди других огров. Его тело – а с ним и его амулет силы – находится на погибшем корабле, выброшенном на Берег Обломков, к востоку отсюда. Его амулет будет последним... а все три вместе откроют нам доступ к Разелиху. И у нас будет шанс его остановить.','Раздобудьте амулет Грола на Берегу Обломков в Выжженных землях.','<Касым сжимает в руке третий амулет.>$B$BОн был могучим воином, этот Грол. Все три амулета у нас. Теперь можно готовиться к ритуалу.','Третий амулет, от третьего помощника Разелиха.','Вернитесь к Касыму Шариму в Змеиные Кольца, что в Выжженных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Амулет Грола',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Грол... огр.$B$B<Касым смеется.>$B$BТело Грола, как я понимаю, не покоится среди других огров. Его тело – а с ним и его амулет силы – находится на погибшем корабле, выброшенном на Берег Обломков, к востоку отсюда. Его амулет будет последним... а все три вместе откроют нам доступ к Разелиху. И у нас будет шанс его остановить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте амулет Грола на Берегу Обломков в Выжженных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Касым сжимает в руке третий амулет.>$B$BОн был могучим воином, этот Грол. Все три амулета у нас. Теперь можно готовиться к ритуалу.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Третий амулет, от третьего помощника Разелиха.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Касыму Шариму в Змеиные Кольца, что в Выжженных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (26170,'Завершающий ритуал','Нож готов. Лорам с нами. Он знает, что ему делать. Сейчас я воспользуюсь магией трех амулетов, чтобы открыть вам обоим доступ к их создателю, Разелиху.$B$BСкажи мне, когда вы с Лорамом будете готовы, и я начну ритуал.','Примите участие в ритуале Касыма Шарима.','Примите участие в ритуале Касыма Шарима','Вернитесь к Лораму Многоногу в Змеиные Кольца, что в Выжженных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Завершающий ритуал',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нож готов. Лорам с нами. Он знает, что ему делать. Сейчас я воспользуюсь магией трех амулетов, чтобы открыть вам обоим доступ к их создателю, Разелиху.$B$BСкажи мне, когда вы с Лорамом будете готовы, и я начну ритуал.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Примите участие в ритуале Касыма Шарима.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Примите участие в ритуале Касыма Шарима',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лораму Многоногу в Змеиные Кольца, что в Выжженных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26171,'Демон, имя тебе Рах\'лих','А теперь слушай внимательно.$B$BСейчас мы отправимся к северному подножию утеса Осквернителя, что на северо-западе. Там нас ждет привратник смерти. Он доставит нас на вершину. Там, наверху, ты мне поможешь прикончить Разелиха, потому что мне одному с ним не справиться.$B$BНо самое главное: ты будешь держать каменный нож и используешь его только по моей команде. Нож запечатает душу Разелиха Осквернителя в его новом вечном узилище.$B$BЕсли у нас все получится, тебе надо будет вернуться к дренею Гримео.','Поговорите с привратником смерти у северного подножия утеса Осквернителя. Поднявшись на вершину утеса, уничтожьте тело Разелиха и воспользуйтесь каменным ножом опечатывания, чтобы пленить душу демона.','Лорама воскресили?! А потом он захватил душу демона и запечатал ее в своем собственном теле… ой, батюшки…$B$BТо есть, вот что задумывал Касым. У меня были какие-то подозрения… но я просто отказывался в это верить.$B$BДа, кстати! На той руне было еще одно указание от Касыма. Я поначалу его не понял, но в свете последних событий… в общем, теперь мне все ясно.$B$BОн просил, чтобы я дал тебе что-то из этого – на твой выбор.','Расскажите о судьбе Лорама дозорному Гримео в Темном портале, что в Выжженных землях.','Тот, кто знает его настоящее имя, владеет его судьбой.','Рах\'лих') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Демон, имя тебе Рах\'лих',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А теперь слушай внимательно.$B$BСейчас мы отправимся к северному подножию утеса Осквернителя, что на северо-западе. Там нас ждет привратник смерти. Он доставит нас на вершину. Там, наверху, ты мне поможешь прикончить Разелиха, потому что мне одному с ним не справиться.$B$BНо самое главное: ты будешь держать каменный нож и используешь его только по моей команде. Нож запечатает душу Разелиха Осквернителя в его новом вечном узилище.$B$BЕсли у нас все получится, тебе надо будет вернуться к дренею Гримео.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с привратником смерти у северного подножия утеса Осквернителя. Поднявшись на вершину утеса, уничтожьте тело Разелиха и воспользуйтесь каменным ножом опечатывания, чтобы пленить душу демона.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Лорама воскресили?! А потом он захватил душу демона и запечатал ее в своем собственном теле… ой, батюшки…$B$BТо есть, вот что задумывал Касым. У меня были какие-то подозрения… но я просто отказывался в это верить.$B$BДа, кстати! На той руне было еще одно указание от Касыма. Я поначалу его не понял, но в свете последних событий… в общем, теперь мне все ясно.$B$BОн просил, чтобы я дал тебе что-то из этого – на твой выбор.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Расскажите о судьбе Лорама дозорному Гримео в Темном портале, что в Выжженных землях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Тот, кто знает его настоящее имя, владеет его судьбой.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Рах\'лих',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26172,'Волшебнику крови тоже хочется кушать','Вопреки распространенному мнению, древние и могущественные волшебники крови не пьют кровь. Мы едим обычную еду, как и все остальные, но ее, кстати сказать, сложно добыть во вражеской крепости сектантов.$B$BА вот в центральной долине Выжженных земель водятся пеплогривые кабаны... очень даже пригодные в пищу, поскольку их мясо не нужно готовить – его можно есть прямо сырым. Не хочешь ли ты поохотиться на кабанов и помочь мне пополнить запасы провизии?','Отправляйтесь в Выжженные земли и раздобудьте 5 кусков мяса пеплогривых кабанов.','Я умираю от голода! Если ты не поторопишься, я, наверное, выпью все наши реактивы.','Вернитесь к Касыму Шариму в Змеиные Кольца, что в Выжженных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Волшебнику крови тоже хочется кушать',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вопреки распространенному мнению, древние и могущественные волшебники крови не пьют кровь. Мы едим обычную еду, как и все остальные, но ее, кстати сказать, сложно добыть во вражеской крепости сектантов.$B$BА вот в центральной долине Выжженных земель водятся пеплогривые кабаны... очень даже пригодные в пищу, поскольку их мясо не нужно готовить – его можно есть прямо сырым. Не хочешь ли ты поохотиться на кабанов и помочь мне пополнить запасы провизии?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Выжженные земли и раздобудьте 5 кусков мяса пеплогривых кабанов.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я умираю от голода! Если ты не поторопишься, я, наверное, выпью все наши реактивы.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Касыму Шариму в Змеиные Кольца, что в Выжженных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26173,'Защита тылов','Я сотрудничаю с воинами Орды исключительно потому, что у нас чувство долга превыше вражды... хоть и ненамного. Нам поручено охранять Темный портал, чтобы исключить всякие несанкционированные перемещения. В связи с недавним катаклизмом, сейчас мы особенно уязвимы. Уже есть сообщения о черных драконах, появившихся в этих краях...$B$BМои бойцы исполняют свой долг, но у них тут другие задачи, и нам нужен кто-то, кто помог бы нам с демонами. Рядом с порталом ты найдешь троих демонов-лейтенантов. Их надо прикончить.','Убейте Джаррока Рваное Крыло, Шахандану и Гумгаза.','Вот теперь ты молодец.$B$B<Командир придвигается ближе и шепчет:>$B$BВорген… если тебе интересно, у меня есть еще одно маленькое, но ответственное поручение…','Вернитесь к командиру стражи Релторну Пустомару в Темный портал, что в Выжженных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Защита тылов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я сотрудничаю с воинами Орды исключительно потому, что у нас чувство долга превыше вражды... хоть и ненамного. Нам поручено охранять Темный портал, чтобы исключить всякие несанкционированные перемещения. В связи с недавним катаклизмом, сейчас мы особенно уязвимы. Уже есть сообщения о черных драконах, появившихся в этих краях...$B$BМои бойцы исполняют свой долг, но у них тут другие задачи, и нам нужен кто-то, кто помог бы нам с демонами. Рядом с порталом ты найдешь троих демонов-лейтенантов. Их надо прикончить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Джаррока Рваное Крыло, Шахандану и Гумгаза.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот теперь ты молодец.$B$B<Командир придвигается ближе и шепчет:>$B$BВорген… если тебе интересно, у меня есть еще одно маленькое, но ответственное поручение…',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру стражи Релторну Пустомару в Темный портал, что в Выжженных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26174,'Осторожность не помешает','<Командир стражи Релторн Пустомар говорит полушепотом.>$B$BУ меня есть приказ... сверху... как раз для тебя. Я не раз замечал, как солдаты Орды периодически сверяются с какими-то документами... на той бочке, вон там. Было бы очень неплохо узнать, что там, в этих бумагах, и что замышляет Орда. Мое положение и должность не позволяют мне лично заняться этим сомнительным делом, а ты здесь $gновенький:новенькая;, у тебя, может быть, и получится подойти незаметно...','Изучите планы Орды у Темного портала и постарайтесь, чтобы вас не поймали за этим занятием.','Тебя точно никто не видел? Вот и славно.$B$B<Пустомар слушает, как вы пересказываете ему все, что узнали из документов.>$B$BГм… все вполне безобидно. То ли они там в Орде все идиоты и действительно ничего против нас не замышляют… то ли, наоборот, хитрые бестии и скрывают всю важную информацию гораздо лучше, чем я думал. Как бы там ни было, ты молодец.','Вернитесь к командиру стражи Релторну Пустомару в Темный портал, что в Выжженных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Осторожность не помешает',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Командир стражи Релторн Пустомар говорит полушепотом.>$B$BУ меня есть приказ... сверху... как раз для тебя. Я не раз замечал, как солдаты Орды периодически сверяются с какими-то документами... на той бочке, вон там. Было бы очень неплохо узнать, что там, в этих бумагах, и что замышляет Орда. Мое положение и должность не позволяют мне лично заняться этим сомнительным делом, а ты здесь $gновенький:новенькая;, у тебя, может быть, и получится подойти незаметно...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Изучите планы Орды у Темного портала и постарайтесь, чтобы вас не поймали за этим занятием.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебя точно никто не видел? Вот и славно.$B$B<Пустомар слушает, как вы пересказываете ему все, что узнали из документов.>$B$BГм… все вполне безобидно. То ли они там в Орде все идиоты и действительно ничего против нас не замышляют… то ли, наоборот, хитрые бестии и скрывают всю важную информацию гораздо лучше, чем я думал. Как бы там ни было, ты молодец.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру стражи Релторну Пустомару в Темный портал, что в Выжженных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (26175,'Сурвич','За исключением того, что ты $gвидел:видела;, у портала сейчас наблюдается удивительное затишье. Так что, боюсь, у меня больше нет для тебя работы.$B$BНо если тебе очень хочется приключений, можешь сходить в рыбацкий поселок Гилнеаса на юго-западе. Сурвич, если я правильно помню.$B$BНу да, считается, что мы с Гилнеасом дружим, но если по правде... Дружба с воргенами?! Как-нибудь без меня... Я и дренеев-то с трудом перевариваю...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сурвич',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','За исключением того, что ты $gвидел:видела;, у портала сейчас наблюдается удивительное затишье. Так что, боюсь, у меня больше нет для тебя работы.$B$BНо если тебе очень хочется приключений, можешь сходить в рыбацкий поселок Гилнеаса на юго-западе. Сурвич, если я правильно помню.$B$BНу да, считается, что мы с Гилнеасом дружим, но если по правде... Дружба с воргенами?! Как-нибудь без меня... Я и дренеев-то с трудом перевариваю...',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (26176,'Вперед на Телсамар','Ты $gоказал:оказала; нам здесь немало помощи. Если ты уже покидаешь нас, я бы хотел попросить тебя доставить в Телсамар наш отчет о состоянии дел.$b$bИди по дороге на север и ты не заблудишься. Горный пехотинец Кэдрелл будет рад получить этот отчет.','Доставьте отчет капитана Ругельфасса горному пехотинцу Кэдреллу в Телсамар.','Чем могу помочь?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вперед на Телсамар',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gоказал:оказала; нам здесь немало помощи. Если ты уже покидаешь нас, я бы хотел попросить тебя доставить в Телсамар наш отчет о состоянии дел.$b$bИди по дороге на север и ты не заблудишься. Горный пехотинец Кэдрелл будет рад получить этот отчет.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте отчет капитана Ругельфасса горному пехотинцу Кэдреллу в Телсамар.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Чем могу помочь?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26178,'Планы на будущее','Если мы хотим выжить, нам следует бороться с волчерами. Я только боюсь, как бы мы в своем рвении не истребили слишком многих.$b$bВолчеры Поляны Снегопада имеют такое же право на жизнь, как и мы сами. И мы с тобой позаботимся о том, чтобы они получили свой шанс.$b$bЕсли старейшина Ко\'нани не просил тебя с ними разобраться, значит, еще попросит. Когда будешь на севере, на их поляне, собери, пожалуйста, щенков и принеси их мне.','Соберите 12 щенков Поляны Снегопада. Принесите их зверолову Мау\'и в гавани Моа\'ки.','Вернитесь к зверолову Мау\'и в гавань Моа\'ки, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Планы на будущее',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если мы хотим выжить, нам следует бороться с волчерами. Я только боюсь, как бы мы в своем рвении не истребили слишком многих.$b$bВолчеры Поляны Снегопада имеют такое же право на жизнь, как и мы сами. И мы с тобой позаботимся о том, чтобы они получили свой шанс.$b$bЕсли старейшина Ко\'нани не просил тебя с ними разобраться, значит, еще попросит. Когда будешь на севере, на их поляне, собери, пожалуйста, щенков и принеси их мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 12 щенков Поляны Снегопада. Принесите их зверолову Мау\'и в гавани Моа\'ки.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к зверолову Мау\'и в гавань Моа\'ки, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26179,'Думаю, такой намек невозможно не понять, а? Торговая Компания не будет впредь так легко относиться к тауренам или заносчиво полагать, будто мы без лишних слов позволим похищать наши полезные ископаемые.','Вернитесь к Морину Ловцу Облаков в Мулгор.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Думаю, такой намек невозможно не понять, а? Торговая Компания не будет впредь так легко относиться к тауренам или заносчиво полагать, будто мы без лишних слов позволим похищать наши полезные ископаемые.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Морину Ловцу Облаков в Мулгор.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26180,'Бригадир Шумовик','Убейте бригадира Шумовика и принесите его планшет Морину Ловцу Облаков в деревню Кровавого Копыта.','Вернитесь к Морину Ловцу Облаков в Мулгор.','Достань его планшет.','Бригадир Шумовик') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бригадир Шумовик',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте бригадира Шумовика и принесите его планшет Морину Ловцу Облаков в деревню Кровавого Копыта.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Морину Ловцу Облаков в Мулгор.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Достань его планшет.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Бригадир Шумовик',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26181,'Возвращение в Темную пещеру','ВОЗВРАЩАЙСЯ... В... ТЕМНУЮ ПЕЩЕРУ. ЭРУНАК ГОВОРЯЩИЙ С КАМНЕМ ЖДЕТ... ТЕБЯ ТАМ.$B$BМНЕ ПРИШЕЛ КОНЕЦ...','Поговорите с Эрунаком Говорящим с Камнем в Темной пещере, что в Вайш\'ире.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение в Темную пещеру',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','ВОЗВРАЩАЙСЯ... В... ТЕМНУЮ ПЕЩЕРУ. ЭРУНАК ГОВОРЯЩИЙ С КАМНЕМ ЖДЕТ... ТЕБЯ ТАМ.$B$BМНЕ ПРИШЕЛ КОНЕЦ...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Эрунаком Говорящим с Камнем в Темной пещере, что в Вайш\'ире.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26182,'Возвращение в Зловещий грот','ВОЗВРАЩАЙСЯ... В... ЗЛОВЕЩИЙ ГРОТ. ЭРУНАК ГОВОРЯЩИЙ С КАМНЕМ ЖДЕТ... ТЕБЯ ТАМ.$B$BМНЕ ПРИШЕЛ КОНЕЦ...','Поговорите с Эрунаком Говорящим с Камнем в Зловещем гроте, что в Вайш\'ире.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение в Зловещий грот',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','ВОЗВРАЩАЙСЯ... В... ЗЛОВЕЩИЙ ГРОТ. ЭРУНАК ГОВОРЯЩИЙ С КАМНЕМ ЖДЕТ... ТЕБЯ ТАМ.$B$BМНЕ ПРИШЕЛ КОНЕЦ...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Эрунаком Говорящим с Камнем в Зловещем гроте, что в Вайш\'ире.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (26182,'Приветствую тебя снова, $C.$B$BЯ ощутил кончину Л\'горека. Печально, что такого величественного создания больше нет.$B$BЕсли не помочь Нептулону, нас всех постигнет та же участь.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Приветствую тебя снова, $C.$B$BЯ ощутил кончину Л\'горека. Печально, что такого величественного создания больше нет.$B$BЕсли не помочь Нептулону, нас всех постигнет та же участь.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26183,'Королевский сидр','Я в вечном долгу перед нашим королем за все, что он для нас сделал. И самое малое, чем могу отплатить ему, – это приготовить его любимый напиток! На наше счастье, ингредиенты для этого лакомства можно достать прямо в Штормграде. Яблони растут во всех районах города. Деревья высоковаты, чтобы рвать с них яблоки, но на земле под ними полно упавших.','Соберите 12 сочных яблок. Отнесите их Робби Флею в Штормграде.','Удалось раздобыть сочных яблок?','Вернитесь к Робби Флею в Штормград.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Королевский сидр',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я в вечном долгу перед нашим королем за все, что он для нас сделал. И самое малое, чем могу отплатить ему, – это приготовить его любимый напиток! На наше счастье, ингредиенты для этого лакомства можно достать прямо в Штормграде. Яблони растут во всех районах города. Деревья высоковаты, чтобы рвать с них яблоки, но на земле под ними полно упавших.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 12 сочных яблок. Отнесите их Робби Флею в Штормграде.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось раздобыть сочных яблок?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Робби Флею в Штормград.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26184,'Мечта Червоточного','Большинство жителей Сурвича пришли в Выжженные земли отнюдь не в поисках легкой жизни. Они явились сюда воплотить мечту Марла Червоточного – идеалиста-друида, который верил, что исцелить Гниющий Шрам очень даже возможно, и пытался возродить его к жизни.$B$BНо похоже, Марл ошибался. Да, он вырастил свой лес, но демоны по-прежнему бесчинствуют в этих землях, а его великое дерево – все какое-то скрюченное и кривое.$B$BИ все-таки я не теряю надежды. Может быть, если мы пойдем в Проклятый лес и очистим его от демонов... ну, хотя бы от нескольких...','Убейте 5 стражей ужаса-разрушителей, 5 повелителей ужаса-осквернителей, 5 оскверненных темностволых древней и 3 скверноспорых болотников в Проклятом лесу.','Говоришь, демоны поклонялись дереву?$B$B<Мэр тяжко вздыхает.>$B$BЭтого я и боялся…','Вернитесь к майору Чарлтону Конниспоту в Сурвич, что в Выжженных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мечта Червоточного',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Большинство жителей Сурвича пришли в Выжженные земли отнюдь не в поисках легкой жизни. Они явились сюда воплотить мечту Марла Червоточного – идеалиста-друида, который верил, что исцелить Гниющий Шрам очень даже возможно, и пытался возродить его к жизни.$B$BНо похоже, Марл ошибался. Да, он вырастил свой лес, но демоны по-прежнему бесчинствуют в этих землях, а его великое дерево – все какое-то скрюченное и кривое.$B$BИ все-таки я не теряю надежды. Может быть, если мы пойдем в Проклятый лес и очистим его от демонов... ну, хотя бы от нескольких...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 5 стражей ужаса-разрушителей, 5 повелителей ужаса-осквернителей, 5 оскверненных темностволых древней и 3 скверноспорых болотников в Проклятом лесу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Говоришь, демоны поклонялись дереву?$B$B<Мэр тяжко вздыхает.>$B$BЭтого я и боялся…',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к майору Чарлтону Конниспоту в Сурвич, что в Выжженных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26185,'Спросить совета у Круга Кенария','Боюсь, что порча, поразившая Выжженные земли, в конце концов добралась и до моего друга Марла. Его эксперимент потерпел неудачу, а его великое древо сплотило вокруг себя демонов.$B$BДерево следует уничтожить, а вместе с ним и самого Марла. Поговори с кенарийской наблюдательницей на другом конце города. Я думаю, она подскажет, что делать дальше.$B$BНадеюсь, ты понимаешь, $n, жителям Сурвича вовсе не обязательно знать о том, что мы собираемся сделать. Моральный дух горожан и так подорван, так что незачем усугублять.','Поговорите с кенарийской наблюдательницей Шайаной в Сурвиче в Выжженных землях.','Хотя меня удивляет, что Конниспот все же решился осуществить свои планы, но лично я этому рада. Я знаю, что демоны сплотились вокруг Малдраза, и разделяю его опасения.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спросить совета у Круга Кенария',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Боюсь, что порча, поразившая Выжженные земли, в конце концов добралась и до моего друга Марла. Его эксперимент потерпел неудачу, а его великое древо сплотило вокруг себя демонов.$B$BДерево следует уничтожить, а вместе с ним и самого Марла. Поговори с кенарийской наблюдательницей на другом конце города. Я думаю, она подскажет, что делать дальше.$B$BНадеюсь, ты понимаешь, $n, жителям Сурвича вовсе не обязательно знать о том, что мы собираемся сделать. Моральный дух горожан и так подорван, так что незачем усугублять.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с кенарийской наблюдательницей Шайаной в Сурвиче в Выжженных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хотя меня удивляет, что Конниспот все же решился осуществить свои планы, но лично я этому рада. Я знаю, что демоны сплотились вокруг Малдраза, и разделяю его опасения.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26186,'Демонический резервуар','Нужно привлечь внимание Червоточного, как-то вывести его из этого транса, но только чтобы наверняка.$B$BТа немногая живность, которая сумела обосноваться в Проклятом лесу, наверняка подвержена влиянию местной скрытой энергии. Тебе нужно будет собрать части их тел и соединить их в некую емкость. В каком бы трансе ни пребывал Червоточный – в друидском или демоническом – большой резервуар, полный зараженной животной плоти, сможет его нарушить.','Убейте нечистых черных медведей, нечистых ночных ловцов и нечистых крикунов в Проклятом лесу, а потом составьте из их органов демонический резервуар.','Вернитесь к майору Чарлтону Конниспоту в Сурвич в Выжженных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Демонический резервуар',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нужно привлечь внимание Червоточного, как-то вывести его из этого транса, но только чтобы наверняка.$B$BТа немногая живность, которая сумела обосноваться в Проклятом лесу, наверняка подвержена влиянию местной скрытой энергии. Тебе нужно будет собрать части их тел и соединить их в некую емкость. В каком бы трансе ни пребывал Червоточный – в друидском или демоническом – большой резервуар, полный зараженной животной плоти, сможет его нарушить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте нечистых черных медведей, нечистых ночных ловцов и нечистых крикунов в Проклятом лесу, а потом составьте из их органов демонический резервуар.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к майору Чарлтону Конниспоту в Сурвич в Выжженных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26187,'Падение Марла Червоточного','Когда жители Сурвича узнают о том, что мы сделали... я даже не знаю, что будет. Они так отчаянно держатся за мечту Червоточного... $B$B...и все-таки, мы должны это сделать. У нас нет выбора. Возьми демонический резервуар и с его помощью выведи Марла из транса. Убей его и возвращайся ко мне.','Убейте Марла Червоточного у дерева Малдраз в Выжженных землях. Для того чтобы вывести Марла из транса, используйте демонический резервуар.','Спасибо, Зверство. Весь Сурвич у тебя в долгу.$B$BВыбери что-нибудь себе в награду. Мы не очень богаты, но тех, кто нас защищает, мы все-таки можем отблагодарить.','Вернитесь к майору Чарлтону Конниспоту в Сурвич, что в Выжженных землях.','Когда его разумом завладели демоны, последняя надежда была утеряна.','Марл Червоточный') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Падение Марла Червоточного',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда жители Сурвича узнают о том, что мы сделали... я даже не знаю, что будет. Они так отчаянно держатся за мечту Червоточного... $B$B...и все-таки, мы должны это сделать. У нас нет выбора. Возьми демонический резервуар и с его помощью выведи Марла из транса. Убей его и возвращайся ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Марла Червоточного у дерева Малдраз в Выжженных землях. Для того чтобы вывести Марла из транса, используйте демонический резервуар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо, Зверство. Весь Сурвич у тебя в долгу.$B$BВыбери что-нибудь себе в награду. Мы не очень богаты, но тех, кто нас защищает, мы все-таки можем отблагодарить.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к майору Чарлтону Конниспоту в Сурвич, что в Выжженных землях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Когда его разумом завладели демоны, последняя надежда была утеряна.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Марл Червоточный',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26188,'Маззранач','Дед рассказывал мне истории о своих встречах с долгоногом Маззраначем. О его красных, как у демона, глазах, острых, как бритва, когтях и ядовитых укусах.$b$bИ вот ирония судьбы – мы столкнулись с ним, когда я странствовал по равнинам, и он здорово укусил меня за плечо. Мой дед ничуть не преувеличивал, описывая это жуткое создание. Я собрал почти все части тел разных животных, необходимые, чтобы вылечить воспаленную рану... кроме бедренной кости пумы плоскогорья.$B$BС каждой минутой я становлюсь все слабее... пожалуйста, помоги мне.','Принесите бедренную кость пумы плоскогорья Мауру Заклинателю Дождя в деревню Кровавого Копыта.','Лихорадка не оставляет меня ни днем, ни ночью, уже начинается бред... И зачем я связался со зверем, которого не смог одолеть мой дед...$B$BТы несешь мне ингредиенты для лекарства? Боюсь, если не остановить распространение инфекции, я могу умереть.','Вернитесь к Мауру Заклинателю Дождя в деревню Кровавого Копыта, что в Мулгоре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Маззранач',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Дед рассказывал мне истории о своих встречах с долгоногом Маззраначем. О его красных, как у демона, глазах, острых, как бритва, когтях и ядовитых укусах.$b$bИ вот ирония судьбы – мы столкнулись с ним, когда я странствовал по равнинам, и он здорово укусил меня за плечо. Мой дед ничуть не преувеличивал, описывая это жуткое создание. Я собрал почти все части тел разных животных, необходимые, чтобы вылечить воспаленную рану... кроме бедренной кости пумы плоскогорья.$B$BС каждой минутой я становлюсь все слабее... пожалуйста, помоги мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите бедренную кость пумы плоскогорья Мауру Заклинателю Дождя в деревню Кровавого Копыта.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Лихорадка не оставляет меня ни днем, ни ночью, уже начинается бред... И зачем я связался со зверем, которого не смог одолеть мой дед...$B$BТы несешь мне ингредиенты для лекарства? Боюсь, если не остановить распространение инфекции, я могу умереть.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мауру Заклинателю Дождя в деревню Кровавого Копыта, что в Мулгоре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26189,'Угроза Злого Клыка','Вернитесь к геологу Вельгару в Укрытие Вельгара, что в Болотине.','Горфакс Злой Клык, предводитель орков из клана Драконьей Пасти','Горфакс Злой Клык') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Угроза Злого Клыка',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к геологу Вельгару в Укрытие Вельгара, что в Болотине.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Горфакс Злой Клык, предводитель орков из клана Драконьей Пасти',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Горфакс Злой Клык',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (26191,'Плод стараний') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Плод стараний',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (26191,'С каждым днем под начало Азшары прибывает все больше воинов. Вскоре Нептулон Хозяин Приливов узнает о наших приготовлениях, но он уже не сможет помешать исполнению нашего плана. Нас станет слишком много, а наши союзники будут слишком могущественны. Победа не за горами.$B$BВо имя Азшары!') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','С каждым днем под начало Азшары прибывает все больше воинов. Вскоре Нептулон Хозяин Приливов узнает о наших приготовлениях, но он уже не сможет помешать исполнению нашего плана. Нас станет слишком много, а наши союзники будут слишком могущественны. Победа не за горами.$B$BВо имя Азшары!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26192,'Сиротки тоже любят печенье!','О сиротах Штормграда редко кто вспоминает, но сегодня не такой день, друг мой! Король заказал особую партию печенья специально для сиротского приюта. А я, представь себе, почти допек последнюю порцию и вдруг обнаружил, что у меня закончилась сахарная пудра. Может быть, сходишь и принесешь? Она есть в любой продуктовой лавке и в городских тавернах.','Раздобудьте 4 мешка сахарной пудры и отнесите Робби Флею в Штормград.','Этих мешков должно хватить, Тормунд. Не терпится поглядеть на улыбающиеся рожицы сироток.','Вернитесь к Робби Флею в Штормград.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сиротки тоже любят печенье!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','О сиротах Штормграда редко кто вспоминает, но сегодня не такой день, друг мой! Король заказал особую партию печенья специально для сиротского приюта. А я, представь себе, почти допек последнюю порцию и вдруг обнаружил, что у меня закончилась сахарная пудра. Может быть, сходишь и принесешь? Она есть в любой продуктовой лавке и в городских тавернах.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте 4 мешка сахарной пудры и отнесите Робби Флею в Штормград.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Этих мешков должно хватить, Тормунд. Не терпится поглядеть на улыбающиеся рожицы сироток.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Робби Флею в Штормград.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26193,'Оборона Провала','НЕТ!$B$BЭто еще не конец!','Обратитесь к капитану Тейлору на краю Обрыва над бездной.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оборона Провала',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','НЕТ!$B$BЭто еще не конец!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Обратитесь к капитану Тейлору на краю Обрыва над бездной.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26194,'Оборона Провала','Возможно, они считают, что победа за ними, но мой топор считает по-другому.','Поговорите с легионером Назгримом на краю Обрыва над бездной.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оборона Провала',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Возможно, они считают, что победа за ними, но мой топор считает по-другому.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с легионером Назгримом на краю Обрыва над бездной.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (26196,'Длиннокос Мрачный','Дворфы Дун Модра денно и нощно сражаются с кланом Черного Железа, заполонившим их древний дом. Пока мы еще не можем послать туда наших часовых – слишком опасно, – но мы поддержим бойцов, отправив туда необходимые припасы.$B$BЕсли согласишься, отнеси этот сверток Длиннокосу Мрачному – найти его можно к северу отсюда. Его бойцам наверняка пригодится содержимое этого свертка.','Отнести полевой набор Ферилона Длиннокосу Мрачному в Дун Модре.','Припасы от Ферилона? Да будь он благословен!$B$BЕды нам хватает, а вот пули на исходе!','Итак, что ты принесла?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Длиннокос Мрачный',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Дворфы Дун Модра денно и нощно сражаются с кланом Черного Железа, заполонившим их древний дом. Пока мы еще не можем послать туда наших часовых – слишком опасно, – но мы поддержим бойцов, отправив туда необходимые припасы.$B$BЕсли согласишься, отнеси этот сверток Длиннокосу Мрачному – найти его можно к северу отсюда. Его бойцам наверняка пригодится содержимое этого свертка.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнести полевой набор Ферилона Длиннокосу Мрачному в Дун Модре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Припасы от Ферилона? Да будь он благословен!$B$BЕды нам хватает, а вот пули на исходе!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Итак, что ты принесла?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`completedtext_loc8`) VALUES (26205,'Вернитесь к инженеру Искролязгу в Новый Город Механиков.') ON DUPLICATE KEY UPDATE `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к инженеру Искролязгу в Новый Город Механиков.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26208,'Битва продолжается','Дворфы Стальгорна были весьма добры и приютили нас, когда нападение троггов и радиация заставили нас покинуть Гномреган в первый раз. Но даже доброта друзей не может избавить нас от тоски по дому.$b$bЯ попросил храбрых гномов и других членов Альянса помочь нам вернуть контроль над Гномреганом и победить узурпатора Термоштепселя раз и навсегда.$b$bВсе, что планировалось в операции "Гномреган", нам выполнить не удалось, но Термоштепсель обращен в бегство, и сейчас мы как никогда близки к дому.','Посмотрите на голографическую панель перед главным механиком Меггакрутом, чтобы узнать об операции "Гномреган".','Даже теперь только команды С.П.А.С. осмеливаются пробираться в город и искать выживших. А тем временем Термоштепсель прислал одного из своих приспешников, Шестерямстера, чтобы помешать нам и выиграть время.','Поговорите с главным механиком Меггакрутом в Новом Городе Механиков.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Битва продолжается',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Дворфы Стальгорна были весьма добры и приютили нас, когда нападение троггов и радиация заставили нас покинуть Гномреган в первый раз. Но даже доброта друзей не может избавить нас от тоски по дому.$b$bЯ попросил храбрых гномов и других членов Альянса помочь нам вернуть контроль над Гномреганом и победить узурпатора Термоштепселя раз и навсегда.$b$bВсе, что планировалось в операции "Гномреган", нам выполнить не удалось, но Термоштепсель обращен в бегство, и сейчас мы как никогда близки к дому.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Посмотрите на голографическую панель перед главным механиком Меггакрутом, чтобы узнать об операции "Гномреган".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Даже теперь только команды С.П.А.С. осмеливаются пробираться в город и искать выживших. А тем временем Термоштепсель прислал одного из своих приспешников, Шестерямстера, чтобы помешать нам и выиграть время.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с главным механиком Меггакрутом в Новом Городе Механиков.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26209,'На меня повесили убийство','Вот что, деточка, у нас тут висяк. Двойное человекоубийство... И одно коне... убийство.$B$BЧто хуже всего, мы в Западном крае. Я могу наугад прихлопнуть с десяток бродяг, у которых были основания прикончить этих стариков и несчастную Савраску.$B$BИ вот, я не знаю точно, кто это сделал, и уж конечно, мне совсем неохота тащиться в эту дыру и расследовать смерть парочки поселенцев, но ведь так хочется найти преступника и установить истину! Хочешь помочь? Ступай, поговори с этими лоботрясами. Они уже... в курсе.','Поговорите с несколькими бездомными людьми, населяющими владение Янсена, чтобы найти какие-нибудь указания на то, кто убил Хмуробровов.','Гноллы и мурлоки? Чушь собачья, приятель! Гноллы и мурлоки их не убивали. Видел я, как убивают гноллы и мурлоки, а тутошнее убийство на их дело… не похоже. Слишком чисто. Слишком… изящно.$B$BБолее того, Хмуробровы живут на ферме лет пять. Нет уж, кто бы их ни порешил, у него была на то причина. Это убийство, ясно как день, и мы доберемся до истины…','Пока ничего?','Вернитесь лейтенанту Горацио Лейну во владение Янсена в Западный край.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На меня повесили убийство',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот что, деточка, у нас тут висяк. Двойное человекоубийство... И одно коне... убийство.$B$BЧто хуже всего, мы в Западном крае. Я могу наугад прихлопнуть с десяток бродяг, у которых были основания прикончить этих стариков и несчастную Савраску.$B$BИ вот, я не знаю точно, кто это сделал, и уж конечно, мне совсем неохота тащиться в эту дыру и расследовать смерть парочки поселенцев, но ведь так хочется найти преступника и установить истину! Хочешь помочь? Ступай, поговори с этими лоботрясами. Они уже... в курсе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с несколькими бездомными людьми, населяющими владение Янсена, чтобы найти какие-нибудь указания на то, кто убил Хмуробровов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Гноллы и мурлоки? Чушь собачья, приятель! Гноллы и мурлоки их не убивали. Видел я, как убивают гноллы и мурлоки, а тутошнее убийство на их дело… не похоже. Слишком чисто. Слишком… изящно.$B$BБолее того, Хмуробровы живут на ферме лет пять. Нет уж, кто бы их ни порешил, у него была на то причина. Это убийство, ясно как день, и мы доберемся до истины…',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Пока ничего?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь лейтенанту Горацио Лейну во владение Янсена в Западный край.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26210,'Гаммерита!','Йоу! Тут живет всем черепахам черепаха – звать Гаммерита – предводительница морских хрустогрызов и просто наглая прожорливая рептилия, чтоб ей.$B$BОна слопала мою лучшую блесну! Взяла и откусила прямо с удочки! С тех пор рыба совсем клевать перестала.$B$BНайди Гаммериту и вытащи у нее из брюха мою блесну!','Убейте Гаммериту и верните Катуму Удильщику из деревни Сломанного Клыка его лучшую блесну.$B$BКатум сказал, что Гаммерита ползает по берегу среди остальных черепах.','ДРУЖИЩЕ!!! Ну и дела! Блесна есть, хрустогрызов нет, да я сейчас всю рыбу в море переловлю!','Вернитесь к Катуму Удильщику в Деревню Сломанного Клыка, что во Внутренних землях.','Береговое чудище в панцире.','Гаммерита') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гаммерита!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Йоу! Тут живет всем черепахам черепаха – звать Гаммерита – предводительница морских хрустогрызов и просто наглая прожорливая рептилия, чтоб ей.$B$BОна слопала мою лучшую блесну! Взяла и откусила прямо с удочки! С тех пор рыба совсем клевать перестала.$B$BНайди Гаммериту и вытащи у нее из брюха мою блесну!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Гаммериту и верните Катуму Удильщику из деревни Сломанного Клыка его лучшую блесну.$B$BКатум сказал, что Гаммерита ползает по берегу среди остальных черепах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','ДРУЖИЩЕ!!! Ну и дела! Блесна есть, хрустогрызов нет, да я сейчас всю рыбу в море переловлю!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Катуму Удильщику в Деревню Сломанного Клыка, что во Внутренних землях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Береговое чудище в панцире.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Гаммерита',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26211,'Хрустогрызы, чувак!','Ты не смотри, что у них такие большие красивые глазки! Страшней морского хрустогрыза зверя нет! Только я удочку закину, как приплывают эти черепахи-переростки, жрут мне всю наживку и удилище пополам ломают!$B$BСделай мне и всей нашей деревне одолжение – поубивай их всех.$B$BВ смысле, хрустогрызов.','Убейте 10 морских хрустогрызов по поручению Катума Удильщика из деревни Сломанного Клыка во Внутренних землях.','Вернитесь к Катуму Удильщику в Деревню Сломанного Клыка, что во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хрустогрызы, чувак!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты не смотри, что у них такие большие красивые глазки! Страшней морского хрустогрыза зверя нет! Только я удочку закину, как приплывают эти черепахи-переростки, жрут мне всю наживку и удилище пополам ломают!$B$BСделай мне и всей нашей деревне одолжение – поубивай их всех.$B$BВ смысле, хрустогрызов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 морских хрустогрызов по поручению Катума Удильщика из деревни Сломанного Клыка во Внутренних землях.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Катуму Удильщику в Деревню Сломанного Клыка, что во Внутренних землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26212,'Лярд потерял свой обед','Лярд хотел устроить пикник в секретном месте, а потом пришли злые тролли племени Порочной Ветви и побили Лярда большими палками. Лярд убежал в деревню, но потерял свой обед. Лярд голодный... Может, сходишь в секретное место и найдешь там мой обед? Лярд боится. Это на севере! Остров на севере, там секретное место!','Найдите обед Лярда из деревни Сломанного Клыка во Внутренних землях.$B$BЛярд сказал, что потерял свой обед на острове к северу, где могут встретиться тролли из племени Порочной Ветви.','<Лярд берет у вас огромный кусок мяса и начинает жадно его грызть.>$B$BВот, как хорошо! Спасибо, мелкий.$B$BЛярд даст тебе в подарок эту специальную корзинку для пикника.','<Лярд потирает огромный живот>$B$BЛярд хочет кушать...','Вернитесь к Лярду в Деревню Сломанного Клыка, что во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лярд потерял свой обед',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Лярд хотел устроить пикник в секретном месте, а потом пришли злые тролли племени Порочной Ветви и побили Лярда большими палками. Лярд убежал в деревню, но потерял свой обед. Лярд голодный... Может, сходишь в секретное место и найдешь там мой обед? Лярд боится. Это на севере! Остров на севере, там секретное место!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите обед Лярда из деревни Сломанного Клыка во Внутренних землях.$B$BЛярд сказал, что потерял свой обед на острове к северу, где могут встретиться тролли из племени Порочной Ветви.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Лярд берет у вас огромный кусок мяса и начинает жадно его грызть.>$B$BВот, как хорошо! Спасибо, мелкий.$B$BЛярд даст тебе в подарок эту специальную корзинку для пикника.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Лярд потирает огромный живот>$B$BЛярд хочет кушать...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лярду в Деревню Сломанного Клыка, что во Внутренних землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26213,'Найдите улику против гноллов из стаи Речной Лапы.','Если это шутка, то мне не смешно. Обрывки красной ткани? И что это должно значить?','У гноллов что-нибудь нашлось?','Принесите улику против гноллов из стаи Речной Лапы лейтенанту Горацио Лейну во владение Янсена в Западном крае.') ON DUPLICATE KEY UPDATE `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите улику против гноллов из стаи Речной Лапы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Если это шутка, то мне не смешно. Обрывки красной ткани? И что это должно значить?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У гноллов что-нибудь нашлось?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите улику против гноллов из стаи Речной Лапы лейтенанту Горацио Лейну во владение Янсена в Западном крае.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26214,'По горячему следу: мурлоки','Хотя все это, по-моему, без толку, придется проверять каждую ниточку.$B$BМне нужно, чтобы ты $gотправился:отправилась; в Бескрайний берег, на запад отсюда, на побережье, и $gвытряс:вытрясла; кой-чего из мурлоков. Попытайся найти улику или какую-нибудь информацию, которая помогла бы нам пролить свет на эти убийства.$B$BЕсли повезет – до встречи, новобранец!','Добудьте улику против мурлоков.','Хорошая находка, новобранец! Сдается, что на станции у меня на столе целая стопка таких. Мы обычно квадратные используем. И что нам теперь известно? Кто-то, кто любит писать всякую бредятину о прошлом, посылает Хмуробровам письмо.$B$BПохоже, мы вляпались в настоящую историю… тайную.','Ну, как охота на мурлоков?','Принесите улику против мурлоков лейтенанту Горацио Лейну во владение Янсена в Западном крае.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','По горячему следу: мурлоки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хотя все это, по-моему, без толку, придется проверять каждую ниточку.$B$BМне нужно, чтобы ты $gотправился:отправилась; в Бескрайний берег, на запад отсюда, на побережье, и $gвытряс:вытрясла; кой-чего из мурлоков. Попытайся найти улику или какую-нибудь информацию, которая помогла бы нам пролить свет на эти убийства.$B$BЕсли повезет – до встречи, новобранец!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте улику против мурлоков.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошая находка, новобранец! Сдается, что на станции у меня на столе целая стопка таких. Мы обычно квадратные используем. И что нам теперь известно? Кто-то, кто любит писать всякую бредятину о прошлом, посылает Хмуробровам письмо.$B$BПохоже, мы вляпались в настоящую историю… тайную.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, как охота на мурлоков?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите улику против мурлоков лейтенанту Горацио Лейну во владение Янсена в Западном крае.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26215,'Встреча с Переобутым Лу','Похоже, мы вляпались в настоящую "детективную историю", новобранец. Увы, местные не желают говорить, а улики, которые тебе удалось найти у гноллов и мурлоков, гроша ломаного не стоят. Придется пустить в ход план... придется найти Переобутого Лу.$B$BПереобутый Лу – мой старый и верный информатор, который по иронии судьбы прижился на тыквенной ферме Хмуробровов. Сходи на ферму и узнай, что известно Лу.$B$BЕсли он начнет тебе лапшу на уши вешать, скажи, что тебя прислал Горацио.','Поговорите с Переобутым Лу на тыквенной ферме Хмуроброва в Западном крае.','Слушай, у нас больше места нет…$B$BТак тебя прислал Горацио? Тогда ладно… и чем я могу тебе помочь?$B$BЕго ж тут нету? Так он же знает, что я от него не прячусь, верно? Я просто сижу себе тихонько – и все, понимаешь?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Встреча с Переобутым Лу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Похоже, мы вляпались в настоящую "детективную историю", новобранец. Увы, местные не желают говорить, а улики, которые тебе удалось найти у гноллов и мурлоков, гроша ломаного не стоят. Придется пустить в ход план... придется найти Переобутого Лу.$B$BПереобутый Лу – мой старый и верный информатор, который по иронии судьбы прижился на тыквенной ферме Хмуробровов. Сходи на ферму и узнай, что известно Лу.$B$BЕсли он начнет тебе лапшу на уши вешать, скажи, что тебя прислал Горацио.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Переобутым Лу на тыквенной ферме Хмуроброва в Западном крае.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Слушай, у нас больше места нет…$B$BТак тебя прислал Горацио? Тогда ладно… и чем я могу тебе помочь?$B$BЕго ж тут нету? Так он же знает, что я от него не прячусь, верно? Я просто сижу себе тихонько – и все, понимаешь?',`offerrewardtext_loc8`);
