INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26219,'Замыкая круг','Нам удалось обнаружить чудище, уничтожившее корабли. Его логово расположено в Темной пещере, огромном подводном гроте на краю Обрыва над бездной.$b$bНа этот раз мы подготовились к встрече с ним. Штормградские гномы построили для нас чудо-корабль, огненная мощь которого заставит содрогнуться даже такого монстра. Когда "Хват Х2" причалит, поднимайся на него и помоги, чем сможешь. Мы тебя догоним.','C "Крепости Волдрина" поднимитесь на борт "Хвата Х2" и окажите помощь в операции в Темной пещере.','Поговорите с капитаном Гловаалем в Темной пещере.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Замыкая круг',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нам удалось обнаружить чудище, уничтожившее корабли. Его логово расположено в Темной пещере, огромном подводном гроте на краю Обрыва над бездной.$b$bНа этот раз мы подготовились к встрече с ним. Штормградские гномы построили для нас чудо-корабль, огненная мощь которого заставит содрогнуться даже такого монстра. Когда "Хват Х2" причалит, поднимайся на него и помоги, чем сможешь. Мы тебя догоним.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','C "Крепости Волдрина" поднимитесь на борт "Хвата Х2" и окажите помощь в операции в Темной пещере.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с капитаном Гловаалем в Темной пещере.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26220,'С беконом все потянет','Накормить армию голодных орков – задачка не из простых. Хорошо еще, что у нас много свинины на свинофермах и в окрестностях Оргриммара. Сделай милость, заруби несколько кабанов и принеси мне туши. Я их нашинкую и сделаю отменный бекон солдатам на завтрак.','Заруби взрослых кабанов к югу от Оргриммара и принеси мне 6 туш. Я буду ждать тебя тут, в Волоке.','Превосходно, Коффайох. Тушки что надо.','Ну как, нарубил свининки?','Вернитесь к Мароггу в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','С беконом все потянет',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Накормить армию голодных орков – задачка не из простых. Хорошо еще, что у нас много свинины на свинофермах и в окрестностях Оргриммара. Сделай милость, заруби несколько кабанов и принеси мне туши. Я их нашинкую и сделаю отменный бекон солдатам на завтрак.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заруби взрослых кабанов к югу от Оргриммара и принеси мне 6 туш. Я буду ждать тебя тут, в Волоке.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Превосходно, Коффайох. Тушки что надо.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как, нарубил свининки?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мароггу в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26221,'Замыкая круг','Нам удалось обнаружить чудище, уничтожившее корабли. Его логово расположено в Зловещем гроте, огромной подводной пещере на краю Обрыва над бездной.$B$BНа этот раз мы подготовились к встрече с ним. Гоблины-умельцы построили для нас чудо-корабль, огневая мощь которого заставит содрогнуться даже такого монстра.$B$BКогда "Верн" причалит, поднимайся на него и помоги, чем сможешь. Мы тебя догоним.','Со "Стигийской Награды" поднимитесь на борт "Верна" и окажите помощь в операции в Зловещем гроте.','Поговорите с капитаном Верном по прозвищу "Жух" в Зловещем гроте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Замыкая круг',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нам удалось обнаружить чудище, уничтожившее корабли. Его логово расположено в Зловещем гроте, огромной подводной пещере на краю Обрыва над бездной.$B$BНа этот раз мы подготовились к встрече с ним. Гоблины-умельцы построили для нас чудо-корабль, огневая мощь которого заставит содрогнуться даже такого монстра.$B$BКогда "Верн" причалит, поднимайся на него и помоги, чем сможешь. Мы тебя догоним.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Со "Стигийской Награды" поднимитесь на борт "Верна" и окажите помощь в операции в Зловещем гроте.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с капитаном Верном по прозвищу "Жух" в Зловещем гроте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (26221,'Молодец, $C.$B$BЭтому скользкому чудищу удалось сбежать! Я немного усовершенствую корабль. Так что в следующий раз оно не уйдет.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Молодец, $C.$B$BЭтому скользкому чудищу удалось сбежать! Я немного усовершенствую корабль. Так что в следующий раз оно не уйдет.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26222,'Добыча запчастей','Принесите 7 запчастей инженеру Искролязгу в Новый Город Механиков.','Они превосходные! Давай-ка посмотрим, что с ними можно сделать. Может быть, хочешь принять участие в тестировании прототипа, когда он будет готов?','Вернитесь к инженеру Искролязгу в Новый Город Механиков.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Добыча запчастей',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 7 запчастей инженеру Искролязгу в Новый Город Механиков.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Они превосходные! Давай-ка посмотрим, что с ними можно сделать. Может быть, хочешь принять участие в тестировании прототипа, когда он будет готов?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к инженеру Искролязгу в Новый Город Механиков.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26223,'Охота на бродяг','В диких лесах Внутренних земель погибло много храбрых троллей, |3-6($r). Одни из самых опасных животных там – среброгривые волки. Они прячутся в высокой траве и всегда нападают неожиданно.$B$BНельзя закрывать глаза на такую опасность!$B$BУменьши поголовье среброгривых!','Убейте 8 среброгривых бродяг.','Вернитесь к охотнику Мархору в Деревню Сломанного Клыка, что во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота на бродяг',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В диких лесах Внутренних земель погибло много храбрых троллей, |3-6($r). Одни из самых опасных животных там – среброгривые волки. Они прячутся в высокой траве и всегда нападают неожиданно.$B$BНельзя закрывать глаза на такую опасность!$B$BУменьши поголовье среброгривых!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 среброгривых бродяг.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к охотнику Мархору в Деревню Сломанного Клыка, что во Внутренних землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26224,'Охота на дикарей','Одни из самых мерзких существ во Внутренних землях – дикие совухи. Сколько храбрых воинов Сломанного Клыка они уже разорвали своими когтями и клювами...$B$BУбейте всех диких совухов, которых встретите, |3-6($r). Ваша помощь будет взвешена, измерена и по достоинству оценена.','Убейте 10 диких совух.','Вернитесь к охотнику Мархору в Деревню Сломанного Клыка, что во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота на дикарей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Одни из самых мерзких существ во Внутренних землях – дикие совухи. Сколько храбрых воинов Сломанного Клыка они уже разорвали своими когтями и клювами...$B$BУбейте всех диких совухов, которых встретите, |3-6($r). Ваша помощь будет взвешена, измерена и по достоинству оценена.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 диких совух.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к охотнику Мархору в Деревню Сломанного Клыка, что во Внутренних землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26225,'Портвейн "Пупелливербос"','Соберите 12 бутылок портвейна "Пупелливербос".','Замечательно! Если бы не пьяные люди, то и дело разбивающие тут свои корабли, то я не знаю, где бы я доставал этот алкоголь!$B$BВообще, я бы сейчас сел и принялся бы торговаться с тобой целый час, но тебе повезло: слишком уж я хочу поскорей откупорить эти бутылки! Твое здоровье!','Вернитесь к Грогнарду в Деревню Сломанного Клыка, что во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Портвейн "Пупелливербос"',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 12 бутылок портвейна "Пупелливербос".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Замечательно! Если бы не пьяные люди, то и дело разбивающие тут свои корабли, то я не знаю, где бы я доставал этот алкоголь!$B$BВообще, я бы сейчас сел и принялся бы торговаться с тобой целый час, но тебе повезло: слишком уж я хочу поскорей откупорить эти бутылки! Твое здоровье!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Грогнарду в Деревню Сломанного Клыка, что во Внутренних землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26226,'Раки под креольским соусом','Вокруг Оргриммара видимо-невидимо маленьких озер. В них круглый год кишмя кишат раки. Тут-то ты и пригодишься, $n. Налови-ка мне этих раков. Если вернешься с хорошим уловом, наши вояки сегодня знатно попируют.','Поймайте 10 ильных раков в Оргриммаре. Принесите добычу Мароггу.','Фу-у, никогда особо не любил готовить этих склизких гадов. Но спасибо за помощь, Торгвальд.','Ну как, удалось раздобыть раков?','Вернитесь к Мароггу в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Раки под креольским соусом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вокруг Оргриммара видимо-невидимо маленьких озер. В них круглый год кишмя кишат раки. Тут-то ты и пригодишься, $n. Налови-ка мне этих раков. Если вернешься с хорошим уловом, наши вояки сегодня знатно попируют.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поймайте 10 ильных раков в Оргриммаре. Принесите добычу Мароггу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Фу-у, никогда особо не любил готовить этих склизких гадов. Но спасибо за помощь, Торгвальд.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как, удалось раздобыть раков?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мароггу в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26227,'Осторожно: злые фрукты!','Солдаты порой хотят десерта. Я их редко балую, но в этот раз, пожалуй, сделаю исключение. Думаю, тебе в Оргриммаре попадался кактус, на котором растет местное лакомство – колючая груша. Беда в том, что фрукт... ну весь в колючках! В общем, береги руки, но плодов мне этих принеси.','Сорвите 8 колючих груш. Доставьте их Мароггу в Оргриммар.','Ну-ка, покажи ладошки... Да, похоже, ты собираешь эти чертовы груши ничуть не лучше меня!','Удалось нарвать достаточно фруктов?','Вернитесь к Мароггу в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Осторожно: злые фрукты!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Солдаты порой хотят десерта. Я их редко балую, но в этот раз, пожалуй, сделаю исключение. Думаю, тебе в Оргриммаре попадался кактус, на котором растет местное лакомство – колючая груша. Беда в том, что фрукт... ну весь в колючках! В общем, береги руки, но плодов мне этих принеси.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сорвите 8 колючих груш. Доставьте их Мароггу в Оргриммар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну-ка, покажи ладошки... Да, похоже, ты собираешь эти чертовы груши ничуть не лучше меня!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось нарвать достаточно фруктов?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мароггу в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (26228,'Живи и радуйся','Слушай, я бы те ни слова не сказал, но у меня должок перед Горацио. Если честно, я ничего не знаю насчет Хмуробровов, но могу тебе указать верное направление.$B$B<Лу передает вам большой ящик.>$B$BПрежде я жил в этом ящике, пока мне не подфартило. Теперь у меня такая житуха, о которой любой бродяга мечтает!$B$BЗначит, берешь этот жилой ящик и топаешь к руднику Янго, к юго-западу отсюда. Как доберешься до конца шахты, спрячься там в ящике.','Используйте старый дом Переобутого Лу у заднего входа в рудник Янго в Западном крае.','<Лу подносит руки к ушам и начинает громко говорить.>$B$BСТОП! СТОП! СТОП! Не хочу этого слышать! Не хочу знать, мне все равно! Тебя за такую информацию тут прирежут.$B$BЛадно, скажу еще кое-что, и на этом покончим!','Живи и радуйся!','Вернитесь к Переобутому Лу на тыквенную ферму Хмуроброва в Западном крае.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Живи и радуйся',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слушай, я бы те ни слова не сказал, но у меня должок перед Горацио. Если честно, я ничего не знаю насчет Хмуробровов, но могу тебе указать верное направление.$B$B<Лу передает вам большой ящик.>$B$BПрежде я жил в этом ящике, пока мне не подфартило. Теперь у меня такая житуха, о которой любой бродяга мечтает!$B$BЗначит, берешь этот жилой ящик и топаешь к руднику Янго, к юго-западу отсюда. Как доберешься до конца шахты, спрячься там в ящике.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте старый дом Переобутого Лу у заднего входа в рудник Янго в Западном крае.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Лу подносит руки к ушам и начинает громко говорить.>$B$BСТОП! СТОП! СТОП! Не хочу этого слышать! Не хочу знать, мне все равно! Тебя за такую информацию тут прирежут.$B$BЛадно, скажу еще кое-что, и на этом покончим!',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Живи и радуйся!',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Переобутому Лу на тыквенную ферму Хмуроброва в Западном крае.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26229,'"Свечка МОЯ!"','Прежде чем я охромел из-за этих треклятых кобольдов, я был первым поставщиком свечей для Вильяма Песта. Эх, я даже придумал себе девиз "СВЕЧКА-МОЯ!" Да, таков я был. Кобольды такие говорят: "Не твоя свечка!" а я им гордо отвечаю: "СВЕЧКА – МОЯ!"- и вышибаю им все мозги!$B$B<Джимб на секунду погружается в размышления.>$B$BХорошие были времена... Лучшие.$B$BА теперь? Я даже до сортира без чьей-то помощи не доползу. Хочешь мне помочь? Перебей побольше кобольдов. Ты целую кучу их найдешь у ближайшей шахты.','Убейте 12 кобольдов-землекопов.','О славное правосудие! Конечно, если перебить кобольдов, я хромать не перестану, да и работы снова не получу, но все равно – как же мне хорошо!$B$B<Джимб роется в заскорузлом старом мешке.>$B$BВот, похоже, нашел кой-чего для тебя со времен моей охоты на кобольдов. Авось, сгодится.','Вернитесь к Джимбу "Свечнику" Макханнигану на тыквенную ферму Хмуроброва в Западном крае.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','"Свечка МОЯ!"',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прежде чем я охромел из-за этих треклятых кобольдов, я был первым поставщиком свечей для Вильяма Песта. Эх, я даже придумал себе девиз "СВЕЧКА-МОЯ!" Да, таков я был. Кобольды такие говорят: "Не твоя свечка!" а я им гордо отвечаю: "СВЕЧКА – МОЯ!"- и вышибаю им все мозги!$B$B<Джимб на секунду погружается в размышления.>$B$BХорошие были времена... Лучшие.$B$BА теперь? Я даже до сортира без чьей-то помощи не доползу. Хочешь мне помочь? Перебей побольше кобольдов. Ты целую кучу их найдешь у ближайшей шахты.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 кобольдов-землекопов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О славное правосудие! Конечно, если перебить кобольдов, я хромать не перестану, да и работы снова не получу, но все равно – как же мне хорошо!$B$B<Джимб роется в заскорузлом старом мешке.>$B$BВот, похоже, нашел кой-чего для тебя со времен моей охоты на кобольдов. Авось, сгодится.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джимбу "Свечнику" Макханнигану на тыквенную ферму Хмуроброва в Западном крае.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26230,'Пир во время чумы','Добудьте 6 хвостов койотов и 5 горстей свежей грязи.','У меня от запаха принесенной тобой снеди аж в животе заурчало! Сегодня пожрем как короли!','Песочные куличики сами по себе не пекутся, как правило.','Вернитесь к маме Селесте на тыквенную ферму Хмуроброва в Западном крае.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пир во время чумы',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 6 хвостов койотов и 5 горстей свежей грязи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','У меня от запаха принесенной тобой снеди аж в животе заурчало! Сегодня пожрем как короли!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Песочные куличики сами по себе не пекутся, как правило.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к маме Селесте на тыквенную ферму Хмуроброва в Западном крае.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (26231,'[Deprecated] Boarding Party') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[Deprecated] Boarding Party',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26232,'Прощальные мысли Лу','На ферму недавно заходили пара громил и устроили тут шухер. Я не знаю, откуда они и на кого работают, но они тут точно НЕСПРОСТА. Кажется, я слышал, как они говорили о том, что может тебя заинтересовать.$B$BЕсли интересно, то они на заднем дворе. Но ежели тебя сцапают или прихлопнут – я тебя в первый раз вижу. Сроду не встречал!$B$BУдачи, детка!','Подслушайте лиходеев, спрятавшись за домом на тыквенной ферме Хмуроброва в Западном крае.','Мы тут имеем дело с целой шайкой, новобранец. Не так просто средь бела дня прикончить самого богатого бездельника в Западном крае и не оставить свидетелей. За этими убийствами стоит какая-то шишка. Так что тебе удалось узнать?','Вернитесь к дому Переобутого Лу на тыквенную ферму Хмуроброва в Западном крае.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прощальные мысли Лу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На ферму недавно заходили пара громил и устроили тут шухер. Я не знаю, откуда они и на кого работают, но они тут точно НЕСПРОСТА. Кажется, я слышал, как они говорили о том, что может тебя заинтересовать.$B$BЕсли интересно, то они на заднем дворе. Но ежели тебя сцапают или прихлопнут – я тебя в первый раз вижу. Сроду не встречал!$B$BУдачи, детка!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Подслушайте лиходеев, спрятавшись за домом на тыквенной ферме Хмуроброва в Западном крае.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мы тут имеем дело с целой шайкой, новобранец. Не так просто средь бела дня прикончить самого богатого бездельника в Западном крае и не оставить свидетелей. За этими убийствами стоит какая-то шишка. Так что тебе удалось узнать?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к дому Переобутого Лу на тыквенную ферму Хмуроброва в Западном крае.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26235,'Вор тоже хочет кушать','Уже несколько недель какие-то ворюги таскают пайки у Оргриммарского гарнизона. Недавно мне доложили, где чаще всего происходят кражи. Как увидишь гору ящиков и провизию, знай – воры наверняка неподалеку. Хочу, чтобы ты $gпоймал:поймала; этих воришек и $gвернул:вернула; украденные пайки. Как закончишь, дуй ко мне.','Раздобудьте 3 пайка ордынских пехотинцев. Отнесите их Мароггу в Оргриммар.','Отлично, Торгвальд! Прослежу, чтобы провиант немедленно раздали солдатам.','Ну как, удалось вернуть наши пайки?','Вернитесь к Мароггу в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вор тоже хочет кушать',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Уже несколько недель какие-то ворюги таскают пайки у Оргриммарского гарнизона. Недавно мне доложили, где чаще всего происходят кражи. Как увидишь гору ящиков и провизию, знай – воры наверняка неподалеку. Хочу, чтобы ты $gпоймал:поймала; этих воришек и $gвернул:вернула; украденные пайки. Как закончишь, дуй ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте 3 пайка ордынских пехотинцев. Отнесите их Мароггу в Оргриммар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, Торгвальд! Прослежу, чтобы провиант немедленно раздали солдатам.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как, удалось вернуть наши пайки?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мароггу в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26236,'Обыск у Сальденов','Итак, что нам известно? Нам нужно принять во внимание улики.$B$BВо владении Янсена ты $gнашел:нашла; мокрое письмо и обрывки красной ткани. На ферме Хмуроброва ты $gподслушал:подслушала; разговоры между какой-то темной личностью и магом-огром. Также ты $gполучил:получила; признание в убийстве от банды головорезов – которых потом и $gприкончил:прикончила;.$B$BЧто-то тут не сходится.$B$BК юго-востоку отсюда на ферме Сальдена живет пожилая чета. Ступай туда и поговори с фермером Сальденом. Выясни, что он знает.','Поговорите с фермером Сальденом на ферме Сальдена в Западном крае.','Горацио Лейн? Редкостный гад. Настоящий мешок фекалий.$B$BСлушай, дружок, я не часто даю такие советы, но ты вроде бы приличный человек. УХОДИ ИЗ ЗАПАДНОГО КРАЯ. Ты и так уже далеко зашел. Все, что ты делаешь, приведет тебя в конце концов на плаху.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обыск у Сальденов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Итак, что нам известно? Нам нужно принять во внимание улики.$B$BВо владении Янсена ты $gнашел:нашла; мокрое письмо и обрывки красной ткани. На ферме Хмуроброва ты $gподслушал:подслушала; разговоры между какой-то темной личностью и магом-огром. Также ты $gполучил:получила; признание в убийстве от банды головорезов – которых потом и $gприкончил:прикончила;.$B$BЧто-то тут не сходится.$B$BК юго-востоку отсюда на ферме Сальдена живет пожилая чета. Ступай туда и поговори с фермером Сальденом. Выясни, что он знает.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с фермером Сальденом на ферме Сальдена в Западном крае.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Горацио Лейн? Редкостный гад. Настоящий мешок фекалий.$B$BСлушай, дружок, я не часто даю такие советы, но ты вроде бы приличный человек. УХОДИ ИЗ ЗАПАДНОГО КРАЯ. Ты и так уже далеко зашел. Все, что ты делаешь, приведет тебя в конце концов на плаху.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26237,'Тяжелые времена','Убейте 10 дозорных полей.','Спасибо тебе, брат. Ты сослужил нам с Сальмой большую службу, и я этого не забуду. У меня не так много денег, но все мое – твое.','Вернитесь к фермеру Сальдену на ферму Сальдена в Западном крае.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тяжелые времена',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 дозорных полей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо тебе, брат. Ты сослужил нам с Сальмой большую службу, и я этого не забуду. У меня не так много денег, но все мое – твое.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к фермеру Сальдену на ферму Сальдена в Западном крае.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26238,'Дикие дворфы','Орда сильно помогла нам, а мы не нахлебники. Другие племена лесных троллей отброшены, и мы сможем завоевать новые земли во имя Орды.$B$BНо нам мешают дворфы Громового Молота. Они хотят войны – они ее получат, но я не хочу проигрывать войну существам ростом с полменя.$B$BИди и поубивай этих дворфов.','Вот теперь дворфы Громового Молота поймут, что надо держаться отсюда подальше!$B$BЭтим психам лучше не высовывать носа из своих гор…','Вернитесь к Старейшине Сломанному Клыку в Деревню Сломанного Клыка, что во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дикие дворфы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Орда сильно помогла нам, а мы не нахлебники. Другие племена лесных троллей отброшены, и мы сможем завоевать новые земли во имя Орды.$B$BНо нам мешают дворфы Громового Молота. Они хотят войны – они ее получат, но я не хочу проигрывать войну существам ростом с полменя.$B$BИди и поубивай этих дворфов.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот теперь дворфы Громового Молота поймут, что надо держаться отсюда подальше!$B$BЭтим психам лучше не высовывать носа из своих гор…',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Старейшине Сломанному Клыку в Деревню Сломанного Клыка, что во Внутренних землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (26239,'<PH>Wildhammer Totems') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<PH>Wildhammer Totems',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26240,'Бей в барабаны','Наши воины храбро сражаются с погаными дворфами клана Громового Молота, поэтому тут безопасно. Но нам надо делать все, что в наших силах, чтобы поддержать своих.$B$BДля боя троллям нужны хорошие барабаны. Их ритм призывает на помощь духов, помогающих бить врага сильнее. Возьми мои барабаны с собой на поле битвы. Бей в них, чтобы поддержать наших воинов. Тогда они покажут дворфам, чьи в лесу шишки!','Испробуйте действие боевых барабанов на 6 воинах племени Сломанного Клыка.','Совсем другое дело, верно? Надеюсь, дворфы запомнят этот урок.','Вернитесь к мистику Яо\'джин в Деревню Сломанного Клыка, что во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бей в барабаны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наши воины храбро сражаются с погаными дворфами клана Громового Молота, поэтому тут безопасно. Но нам надо делать все, что в наших силах, чтобы поддержать своих.$B$BДля боя троллям нужны хорошие барабаны. Их ритм призывает на помощь духов, помогающих бить врага сильнее. Возьми мои барабаны с собой на поле битвы. Бей в них, чтобы поддержать наших воинов. Тогда они покажут дворфам, чьи в лесу шишки!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Испробуйте действие боевых барабанов на 6 воинах племени Сломанного Клыка.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Совсем другое дело, верно? Надеюсь, дворфы запомнят этот урок.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мистику Яо\'джин в Деревню Сломанного Клыка, что во Внутренних землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26241,'Похлебка Западного края','Добудьте 6 плодов окры, 6 боков кровоклыка и 6 кусков жилистого мяса шкуродера.','Спасибо тебе, добрая душа. Эти бедные сиротки уже много дней не ели горячего.$B$BПохоже, у нас еще даже останется еда, чтобы накормить многих бездомных в Западном краю.','Как только у меня будет все, я приготовлю ужин! Торопись!','Вернитесь к Сальме Сальден на ферму Сальдена в Западном крае.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Похлебка Западного края',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 6 плодов окры, 6 боков кровоклыка и 6 кусков жилистого мяса шкуродера.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо тебе, добрая душа. Эти бедные сиротки уже много дней не ели горячего.$B$BПохоже, у нас еще даже останется еда, чтобы накормить многих бездомных в Западном краю.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как только у меня будет все, я приготовлю ужин! Торопись!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сальме Сальден на ферму Сальдена в Западном крае.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (26242,'Подземье, мир земли') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подземье, мир земли',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`) VALUES (26243,'Столп в этом зале не только поддерживает Храм Земли.$b$bВся эта реальность может полететь в тартарары, если нам не удастся восстановить его.$b$bСкоро наступит время действовать, $n. Но сначала послушай, что я должен тебе сказать.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Столп в этом зале не только поддерживает Храм Земли.$b$bВся эта реальность может полететь в тартарары, если нам не удастся восстановить его.$b$bСкоро наступит время действовать, $n. Но сначала послушай, что я должен тебе сказать.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26244,'Земля забирает все','Убейте 5 глубинных элементалей.','Вернитесь к провидцу Кормо в Храм Земли, что в Подземье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Земля забирает все',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 5 глубинных элементалей.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к провидцу Кормо в Храм Земли, что в Подземье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26245,'Крушение воздушного судна','Камень перевозили на летающем боевом корабле Орды под названием "Неистовство Бури".$b$bВоздушное судно разбилось к югу отсюда, и при помощи гадания мы установили, что камня среди обломков нет.$b$bОбыщи корабли и найди какие-нибудь улики, которые могут подсказать, где находится камень.','Обыщите место крушения "Неистовства Бури" в Подземье.','Вывод очевиден. Даже слишком очевиден.','Вернитесь к Марууту Камневязу в Храм Земли, что в Подземье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Крушение воздушного судна',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Камень перевозили на летающем боевом корабле Орды под названием "Неистовство Бури".$b$bВоздушное судно разбилось к югу отсюда, и при помощи гадания мы установили, что камня среди обломков нет.$b$bОбыщи корабли и найди какие-нибудь улики, которые могут подсказать, где находится камень.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обыщите место крушения "Неистовства Бури" в Подземье.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вывод очевиден. Даже слишком очевиден.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Марууту Камневязу в Храм Земли, что в Подземье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26246,'Судовой журнал капитана','<Вы перелистываете страницы до последней, прерванной записи.>$b$b...приближаемся к Храму Земли и начинаем посадочные маневры в соответствии с новым маршрутом. На севере мы обнаружили низкое давление в системе и вытащили наш...$b$BКРОВЬ И ГРОМ! МЕРЗАВЦЫ ИЗ АЛЬЯНСА ПРИБЛИЖАЮТСЯ!!!','Отнесите судовой журнал капитана Марууту Камневязу в Храм Земли, что в Подземье.','Зачем Альянсу атаковать Орду, когда они почти принесли нам фрагмент столпа мира?..') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Судовой журнал капитана',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Вы перелистываете страницы до последней, прерванной записи.>$b$b...приближаемся к Храму Земли и начинаем посадочные маневры в соответствии с новым маршрутом. На севере мы обнаружили низкое давление в системе и вытащили наш...$b$BКРОВЬ И ГРОМ! МЕРЗАВЦЫ ИЗ АЛЬЯНСА ПРИБЛИЖАЮТСЯ!!!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите судовой журнал капитана Марууту Камневязу в Храм Земли, что в Подземье.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Зачем Альянсу атаковать Орду, когда они почти принесли нам фрагмент столпа мира?..',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26247,'Дипломатия прежде всего','Служители Земли – это нейтральная организация, $n. Мы не можем принимать чью бы то ни было сторону в войне между Ордой и Альянсом.$b$bПосмотри вокруг – мы все разные. Наша миссия провалится, если расовые предрассудки будут стоять выше наших целей. Но пока у нас не появится больше информации, давай держать это в тайне.$b$bНе стоит делать поспешных выводов. Я отправлю тебя и одного из наших новых служителей на боевой корабль Альянса.$b$bРазузнай все, что сможешь, не втягивая нас в конфликт.','Поговорите с буревестницей Милрой на боевом корабле Альянса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дипломатия прежде всего',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Служители Земли – это нейтральная организация, $n. Мы не можем принимать чью бы то ни было сторону в войне между Ордой и Альянсом.$b$bПосмотри вокруг – мы все разные. Наша миссия провалится, если расовые предрассудки будут стоять выше наших целей. Но пока у нас не появится больше информации, давай держать это в тайне.$b$bНе стоит делать поспешных выводов. Я отправлю тебя и одного из наших новых служителей на боевой корабль Альянса.$b$bРазузнай все, что сможешь, не втягивая нас в конфликт.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с буревестницей Милрой на боевом корабле Альянса.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26248,'Все наши друзья мертвы','Что-то здесь не так, $n.$b$bКоманда корабля была убита. Но при этом следов кровопролития и разрушений нет.$b$bЭто не дело рук Орды.$b$bМы найдем ответы на интересующие нас вопросы, если поговорим с духами погибших. Они еще не покинули этот мир.$b$bВозьми этот тотем и размести его рядом с телами павших. У тебя будет всего несколько секунд, чтобы узнать их последние мысли.$b$bИ все же, будь $gосторожен:осторожна;! Неизвестно, как отреагируют духи на наше вмешательство.','Воспользуйтесь тотемом духов у 6 тел убитых членов команды.','Вернитесь к буревестнице Милре на боевой корабль Альянса в Подземье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Все наши друзья мертвы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что-то здесь не так, $n.$b$bКоманда корабля была убита. Но при этом следов кровопролития и разрушений нет.$b$bЭто не дело рук Орды.$b$bМы найдем ответы на интересующие нас вопросы, если поговорим с духами погибших. Они еще не покинули этот мир.$b$bВозьми этот тотем и размести его рядом с телами павших. У тебя будет всего несколько секунд, чтобы узнать их последние мысли.$b$bИ все же, будь $gосторожен:осторожна;! Неизвестно, как отреагируют духи на наше вмешательство.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь тотемом духов у 6 тел убитых членов команды.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к буревестнице Милре на боевой корабль Альянса в Подземье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26249,'Каюта адмирала','Поищите улики в кабине адмирала на боевом корабле Альянса.','Этот корабль полон крыс…') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Каюта адмирала',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поищите улики в кабине адмирала на боевом корабле Альянса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Этот корабль полон крыс…',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26250,'А впрочем... взять одного пленного','Еще не поздно, $n. Возможно, сектанты все еще там.$b$bСпустись вниз, выясни, кто у них главный, и победи его.$b$bТак или иначе, мы получим ответы на свои вопросы.','Победите Мор\'норока Ненавистного на боевом корабле Альянса в Подземье.','Постарайся не убивать его. Он нужен нам живым.','Мор\'норокк Ненавистный') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','А впрочем... взять одного пленного',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Еще не поздно, $n. Возможно, сектанты все еще там.$b$bСпустись вниз, выясни, кто у них главный, и победи его.$b$bТак или иначе, мы получим ответы на свои вопросы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Мор\'норока Ненавистного на боевом корабле Альянса в Подземье.',`objectives_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Постарайся не убивать его. Он нужен нам живым.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Мор\'норокк Ненавистный',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26251,'Пленных не брать','Похоже, что адепты Сумеречного Молота все еще на корабле. Спустись вниз и разберись с ними.$b$bБудь $gосторожен:осторожна;, $n. У меня есть ощущение, что они тут не с целью провести выездной духовный семинар, если ты понимаешь, о чем я.','Убейте 6 сумеречных саботажников.','Вернитесь к буревестнице Милре на боевой корабль Альянса в Подземье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пленных не брать',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Похоже, что адепты Сумеречного Молота все еще на корабле. Спустись вниз и разберись с ними.$b$bБудь $gосторожен:осторожна;, $n. У меня есть ощущение, что они тут не с целью провести выездной духовный семинар, если ты понимаешь, о чем я.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 6 сумеречных саботажников.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к буревестнице Милре на боевой корабль Альянса в Подземье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (26252,'Сердце дозорного','Вы нашли то, что кажется сердцем дозорного полей.$B$BПо звуку, издаваемому устройством, вы можете сказать, что оно полностью функционально. Возможно, вам надо принести его фермеру Сальдену.','Принесите сердце дозорного полей фермеру Сальдену на ферму Сальдена.','Неужели… Неужели это сердце одного из дозорных? Я слышал рассказы о том, что они использовались для того, чтобы подчинить себе дозорных. Конечно, мне не под силу попытаться сделать это самому.','Что там у тебя, Ролотомаси?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сердце дозорного',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы нашли то, что кажется сердцем дозорного полей.$B$BПо звуку, издаваемому устройством, вы можете сказать, что оно полностью функционально. Возможно, вам надо принести его фермеру Сальдену.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите сердце дозорного полей фермеру Сальдену на ферму Сальдена.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Неужели… Неужели это сердце одного из дозорных? Я слышал рассказы о том, что они использовались для того, чтобы подчинить себе дозорных. Конечно, мне не под силу попытаться сделать это самому.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что там у тебя, Ролотомаси?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (26253,'Сохранить доказательства') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сохранить доказательства',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26254,'Растянуть связки','Запрыгивай, $n. Посмотрим, есть ли что сказать господину огролицему.$b$bДа не бойся, Клюв Бури ронял пассажиров всего пару раз.','Садитесь на Клюва Бури и проследите за допросом Мор\'норокка.','Поговорите с буревестницей Милрой на боевом корабле Альянса в Подземье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Растянуть связки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Запрыгивай, $n. Посмотрим, есть ли что сказать господину огролицему.$b$bДа не бойся, Клюв Бури ронял пассажиров всего пару раз.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Садитесь на Клюва Бури и проследите за допросом Мор\'норокка.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с буревестницей Милрой на боевом корабле Альянса в Подземье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26255,'Вернуться в Храм Земли','Тебе нужно вернуться с известием в храм. Есть шансы, что фрагмент уже на пути в более безопасное место.$b$bРасскажи Марууту о том, что знаешь. А я тем временем постараюсь разузнать об этом Сумеречном Совете.','Поговорите с Маруутом Камневязом в Храме Земли в Подземье.','Нам нужно подробнее изучить твои сведения, но мы не должны терять следы фрагмента.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вернуться в Храм Земли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе нужно вернуться с известием в храм. Есть шансы, что фрагмент уже на пути в более безопасное место.$b$bРасскажи Марууту о том, что знаешь. А я тем временем постараюсь разузнать об этом Сумеречном Совете.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Маруутом Камневязом в Храме Земли в Подземье.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Нам нужно подробнее изучить твои сведения, но мы не должны терять следы фрагмента.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (26256,'Пустить кровь кроводелам','Здесь клан Сумеречного Молота практикует зловещую магию, $n. Они оживляют и заряжают энергией остатки крови Смертокрыла, так что вместо того, чтобы высохнуть и исчезнуть, она становится чересчур живой.$b$bУничтожь одного из кроводелов и проверь, нет ли при них каких-то документов, которые бы помогли найти этого "начальника кузни".','Заберите приказы Сумеречного Молота у одного из Сумеречных кроводелов в Кратере Смертокрыла.','Они держат здесь рабов? Мы в любом случае должны освободить их, но может быть они еще и помогут нам найти начальника кузни.','Один из них должен привести нас к начальнику кузни.','Сумеречный кроводел','Они держат рабов здесь?','Маруут Камневяз') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пустить кровь кроводелам',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Здесь клан Сумеречного Молота практикует зловещую магию, $n. Они оживляют и заряжают энергией остатки крови Смертокрыла, так что вместо того, чтобы высохнуть и исчезнуть, она становится чересчур живой.$b$bУничтожь одного из кроводелов и проверь, нет ли при них каких-то документов, которые бы помогли найти этого "начальника кузни".',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заберите приказы Сумеречного Молота у одного из Сумеречных кроводелов в Кратере Смертокрыла.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Они держат здесь рабов? Мы в любом случае должны освободить их, но может быть они еще и помогут нам найти начальника кузни.',`offerrewardtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Один из них должен привести нас к начальнику кузни.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Сумеречный кроводел',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Они держат рабов здесь?',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Маруут Камневяз',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26257,'Он живой!','Примените сердце дозорного полей к перегруженному уборочному голему и затем используйте перегруженный уборочный голем для уничтожения 25 заряженных уборочных големов.','Вернитесь к фермеру Сальдену на ферму Сальдена в Западном крае.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Он живой!',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Примените сердце дозорного полей к перегруженному уборочному голему и затем используйте перегруженный уборочный голем для уничтожения 25 заряженных уборочных големов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к фермеру Сальдену на ферму Сальдена в Западном крае.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (26258,'Кратер Смертокрыла','Отправляйтесь в Кратер Смертокрыла в Подземье.','Наверное, сюда принесли фрагмент столпа мира. Давай посмотрим.','Вы добрались до Кратера Смертокрыла','Теперь наши души связаны, так что мы сможем общаться, когда ты будешь далеко.','Маруут Камневяз','Они должны были принести фрагмент сюда!','Маруут Камневяз') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кратер Смертокрыла',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Кратер Смертокрыла в Подземье.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Наверное, сюда принесли фрагмент столпа мира. Давай посмотрим.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Вы добрались до Кратера Смертокрыла',`endtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Теперь наши души связаны, так что мы сможем общаться, когда ты будешь далеко.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Маруут Камневяз',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Они должны были принести фрагмент сюда!',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Маруут Камневяз',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26259,'Кровь Хранителя Земли','Когда Смертокрыл скрылся в Подземье, он был очень серьезно ранен, но все-таки жив.$b$bПролитая им кровь осталась в Кратере Смертокрыла. Сектанты собирают ее и превращают в живых существ, чтобы вытягивать из них силу.$b$bА что если в этой крови остались следы сущности Хранителя Земли? В конце концов, до того, как Нелтарион стал Аспектом смерти, он был Аспектом земли.$b$bСобери образцы живой крови, которую создали сектанты, и мы проверим, есть ли в ней следы сущности Хранителя Земли.','Добудьте 5 образцов крови Нелтариона из живой крови в Кратере Смертокрыла.','Вернитесь к провидцу Кормо в Храм Земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кровь Хранителя Земли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда Смертокрыл скрылся в Подземье, он был очень серьезно ранен, но все-таки жив.$b$bПролитая им кровь осталась в Кратере Смертокрыла. Сектанты собирают ее и превращают в живых существ, чтобы вытягивать из них силу.$b$bА что если в этой крови остались следы сущности Хранителя Земли? В конце концов, до того, как Нелтарион стал Аспектом смерти, он был Аспектом земли.$b$bСобери образцы живой крови, которую создали сектанты, и мы проверим, есть ли в ней следы сущности Хранителя Земли.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 5 образцов крови Нелтариона из живой крови в Кратере Смертокрыла.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к провидцу Кормо в Храм Земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26260,'Записи начальника кузни','Отправляйся в башню, о которой говорил раб. Ты найдешь ее на северо-восточном конце лагеря.$b$bЕсли мы сможем действовать достаточно быстро, у нас должно получиться подслушать, что будет говориться на встрече у начальника кузни.','Найдите записи начальника кузни в Кратере Смертокрыла в Подземье.','В записях есть упоминание о предстоящей встрече в Верховье Серебристой топи.$B$BВероятно, именно там находится начальник кузни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Записи начальника кузни',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Отправляйся в башню, о которой говорил раб. Ты найдешь ее на северо-восточном конце лагеря.$b$bЕсли мы сможем действовать достаточно быстро, у нас должно получиться подслушать, что будет говориться на встрече у начальника кузни.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите записи начальника кузни в Кратере Смертокрыла в Подземье.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','В записях есть упоминание о предстоящей встрече в Верховье Серебристой топи.$B$BВероятно, именно там находится начальник кузни.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26261,'Допрос рабов','Судя по найденным тобой приказам, в шатре на юго-восточном краю Кратера Смертокрыла лежит ключ.$b$bНайди его и освободи рабов с каменоломни, что к югу отсюда.','Найдите ключ поработителя из Сумеречного Молота и освободите 6 порабощенных шахтеров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Допрос рабов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Судя по найденным тобой приказам, в шатре на юго-восточном краю Кратера Смертокрыла лежит ключ.$b$bНайди его и освободи рабов с каменоломни, что к югу отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите ключ поработителя из Сумеречного Молота и освободите 6 порабощенных шахтеров.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (26262,'Оружие Сумеречного Молота') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оружие Сумеречного Молота',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26263,'Торнар Громовой Рокот','Мы пытались убрать командира клана Громового Молота, который напал на наши земли, но у нас ничего не вышло.$B$BТорнар Громовой Рокот сидит себе в целости и невредимости в командном пункте, а его голос разносится над полем битвы, посылая дворфов в атаку. Мы так думаем, пришло время ему замолчать.$B$BУбей Торнара, и мы сможем легко разделаться с этими недомерками.','Убейте Торнара Громового Рокота.','Ну что, неплохо, неплохо. Ты прямо-таки героиня Орды.','Вернитесь к Старейшине Сломанному Клыку в Деревню Сломанного Клыка, что во Внутренних землях.','Наши шансы будут гораздо выше, если этот болван умрет.','Торнар Громовой Рокот') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Торнар Громовой Рокот',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы пытались убрать командира клана Громового Молота, который напал на наши земли, но у нас ничего не вышло.$B$BТорнар Громовой Рокот сидит себе в целости и невредимости в командном пункте, а его голос разносится над полем битвы, посылая дворфов в атаку. Мы так думаем, пришло время ему замолчать.$B$BУбей Торнара, и мы сможем легко разделаться с этими недомерками.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Торнара Громового Рокота.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну что, неплохо, неплохо. Ты прямо-таки героиня Орды.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Старейшине Сломанному Клыку в Деревню Сломанного Клыка, что во Внутренних землях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Наши шансы будут гораздо выше, если этот болван умрет.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Торнар Громовой Рокот',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26264,'Что остается потом','Многие из нас видели больных и психически неуравновешенных гномов, страдающих от воздействия ядов и радиации Гномрегана. Это состояние будет прогрессировать, в конце концов они станут совсем безумными, но по большей части безопасными, и превратятся в лужицы токсической слизи.$b$bОсновываясь на своих исследованиях, я считаю, что мы, возможно, даже сможем вернуть их из этого состояния. Отправляйся на зараженный аэродром к югу отсюда, разыщи токсических слякочей, о которых я тебе говорил, и принеси имущество гномов, которое у них найдешь.','Разыщите на зараженном аэродроме токсических слякочей и соберите 6 единиц спасенного имущества.','Мне не терпится испытать эту новую технологию! Из-за радиации мы потеряли столько гномов, что и сосчитать не можем. Пришло время это изменить!','Получилось достать вещи, принадлежащие облученным гномам?','Вернитесь к Току Шустрецу в Новый Город Механиков.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Что остается потом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Многие из нас видели больных и психически неуравновешенных гномов, страдающих от воздействия ядов и радиации Гномрегана. Это состояние будет прогрессировать, в конце концов они станут совсем безумными, но по большей части безопасными, и превратятся в лужицы токсической слизи.$b$bОсновываясь на своих исследованиях, я считаю, что мы, возможно, даже сможем вернуть их из этого состояния. Отправляйся на зараженный аэродром к югу отсюда, разыщи токсических слякочей, о которых я тебе говорил, и принеси имущество гномов, которое у них найдешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите на зараженном аэродроме токсических слякочей и соберите 6 единиц спасенного имущества.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мне не терпится испытать эту новую технологию! Из-за радиации мы потеряли столько гномов, что и сосчитать не можем. Пришло время это изменить!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Получилось достать вещи, принадлежащие облученным гномам?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Току Шустрецу в Новый Город Механиков.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26265,'Уборка грязи','У Тока Шустреца какая-то безумная теория насчет этих токсических слякочей, в которых превратились гномы, поэтому у моих людей есть приказ пока их не трогать.$b$bНо зараженный аэродром к югу от нас просто кишит ожившими загрязнениями. Это элементали, состоящие из загрязненной воды и других токсичных материалов. Если не обращать на них внимания, они захватят весь город. Ты поможешь нам избавиться от них?','Уничтожьте 6 оживших загрязнений на зараженном аэродроме.','Какое облегчение! Спасибо за твою помощь. Надеюсь, прибор, над которым работает инженер Искролязг, поможет очистить аэродром окончательно.','Вернитесь к капралу Свистопшику в Новый Город Механиков.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уборка грязи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У Тока Шустреца какая-то безумная теория насчет этих токсических слякочей, в которых превратились гномы, поэтому у моих людей есть приказ пока их не трогать.$b$bНо зараженный аэродром к югу от нас просто кишит ожившими загрязнениями. Это элементали, состоящие из загрязненной воды и других токсичных материалов. Если не обращать на них внимания, они захватят весь город. Ты поможешь нам избавиться от них?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 6 оживших загрязнений на зараженном аэродроме.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Какое облегчение! Спасибо за твою помощь. Надеюсь, прибор, над которым работает инженер Искролязг, поможет очистить аэродром окончательно.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капралу Свистопшику в Новый Город Механиков.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (26266,'Надежда народа','Около четырех лет назад в глухую ночь в наш дом вошла маленькая девочка и упала прямо на пороге. Никто не знал, кто она. Бедняжка не помнила, кто она и откуда, – воистину, заблудшая душа.$B$BВскоре мы ее удочерили и назвали Надеждой, потому, что она для нас ей и стала.$B$BТеперь это молодая девушка, которая опекает бедных и бездомных Западного края. Отнеси мою похлебку Западного края на Сторожевой холм, к югу отсюда.','Чувствую запах похлебки Западного края! Тебя мама прислала?!','Добрый день, сударь. Чем могу помочь?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Надежда народа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Около четырех лет назад в глухую ночь в наш дом вошла маленькая девочка и упала прямо на пороге. Никто не знал, кто она. Бедняжка не помнила, кто она и откуда, – воистину, заблудшая душа.$B$BВскоре мы ее удочерили и назвали Надеждой, потому, что она для нас ей и стала.$B$BТеперь это молодая девушка, которая опекает бедных и бездомных Западного края. Отнеси мою похлебку Западного края на Сторожевой холм, к югу отсюда.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Чувствую запах похлебки Западного края! Тебя мама прислала?!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Добрый день, сударь. Чем могу помочь?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26267,'Большая уборка на Осклизлой скале','Много лет назад глубоко в недрах Осклизлой скалы была ордынская база. Ее, похоже, давно забросили, но все равно это важная территория, ее стоит отбить.$B$BПроблема в том, что там теперь полно слизнюков, а они мерзкие до жути... Мозгов у них нет, едкие они как незнамо что и жрут все, что видят.$B$BМне нужен кто-то смелый, кто отправился бы на Осклизлую скалу и поубивал там всех слизнюков. Ты как, $gсмелый:смелая;, $n?','Убейте 10 нефритовых слизнюков.','Как хорошо, что ты вернулась! И, главное, все руки-ноги у тебя на месте.','Вернитесь к Старейшине Сломанному Клыку в Деревню Сломанного Клыка, что во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Большая уборка на Осклизлой скале',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Много лет назад глубоко в недрах Осклизлой скалы была ордынская база. Ее, похоже, давно забросили, но все равно это важная территория, ее стоит отбить.$B$BПроблема в том, что там теперь полно слизнюков, а они мерзкие до жути... Мозгов у них нет, едкие они как незнамо что и жрут все, что видят.$B$BМне нужен кто-то смелый, кто отправился бы на Осклизлую скалу и поубивал там всех слизнюков. Ты как, $gсмелый:смелая;, $n?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 нефритовых слизнюков.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Как хорошо, что ты вернулась! И, главное, все руки-ноги у тебя на месте.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Старейшине Сломанному Клыку в Деревню Сломанного Клыка, что во Внутренних землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26268,'Припасы с Осклизлой скалы','Я был на Осклизлой скале во время Второй войны. Тогда я был еще совсем молод, до встречи с моей спутницей еще оставались многие годы, и я до сих пор помню, какая поднялась паника, когда на нас напал Альянс. Мы помчались прочь вместе с орками, даже вещи собрать не успели.$B$BБросили все, что у нас было, так что на Осклизлой скале до сих пор полно наших припасов, а ведь они бы нам тут, в деревне, пригодились. А главное – это чтобы наши припасы не загреб себе клан Громового Молота.','Соберите 5 покрытых слизью ящиков с припасами.','До сих пор нетронутые! Эти ящики о многом мне напоминают. Интересно, что же тут в первом?$B$BОго, банановый хлеб! И все еще свежий!$B$BЗнаешь что: я, пожалуй, возьму этот хлеб, а ты выбери что-нибудь еще.','Сколько ящиков тебе удалось собрать?','Вернитесь к Старейшине Сломанному Клыку в Деревню Сломанного Клыка, что во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Припасы с Осклизлой скалы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я был на Осклизлой скале во время Второй войны. Тогда я был еще совсем молод, до встречи с моей спутницей еще оставались многие годы, и я до сих пор помню, какая поднялась паника, когда на нас напал Альянс. Мы помчались прочь вместе с орками, даже вещи собрать не успели.$B$BБросили все, что у нас было, так что на Осклизлой скале до сих пор полно наших припасов, а ведь они бы нам тут, в деревне, пригодились. А главное – это чтобы наши припасы не загреб себе клан Громового Молота.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 5 покрытых слизью ящиков с припасами.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','До сих пор нетронутые! Эти ящики о многом мне напоминают. Интересно, что же тут в первом?$B$BОго, банановый хлеб! И все еще свежий!$B$BЗнаешь что: я, пожалуй, возьму этот хлеб, а ты выбери что-нибудь еще.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Сколько ящиков тебе удалось собрать?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Старейшине Сломанному Клыку в Деревню Сломанного Клыка, что во Внутренних землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26269,'Зеленые холмы Тернистой долины','Одна страница! Не хватает только одной страницы!$B$BС книгой господина Эрнестуэя кое-что... произошло. <Барнил сердито зыркает на Спэнкса>...и несколько страниц пропало.$B$BЯ всех просил поискать, и меня очень выручили, но одна страница так и не нашлась.$B$BУ тебя, конечно, полно дел, но раз уж ты все равно собираешься бродить по джунглям, может, заодно и страничку поищешь?','Найдите страницу 14 "Зеленых холмов Тернистой долины".','Ты меня очень здорово $gвыручил:выручила;, $n! Не знаю, как тебя и благодарить. Вот увидишь, скоро книга господина Эрнестуэя появится в каждой библиотеке по всему миру!$B$BЕсли когда-нибудь захочешь почитать ее целиком, всегда найдешь тут у меня экземпляр. Спасибо еще раз, $n!','Ну что, $gнашел:нашла;? Не хотелось бы возвращать Хемингу неполную книгу.','Вернитесь к Барнилу Каменному Горшку в лагерь экспедиции Эрнестуэя, что в Северной Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зеленые холмы Тернистой долины',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Одна страница! Не хватает только одной страницы!$B$BС книгой господина Эрнестуэя кое-что... произошло. <Барнил сердито зыркает на Спэнкса>...и несколько страниц пропало.$B$BЯ всех просил поискать, и меня очень выручили, но одна страница так и не нашлась.$B$BУ тебя, конечно, полно дел, но раз уж ты все равно собираешься бродить по джунглям, может, заодно и страничку поищешь?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите страницу 14 "Зеленых холмов Тернистой долины".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты меня очень здорово $gвыручил:выручила;, $n! Не знаю, как тебя и благодарить. Вот увидишь, скоро книга господина Эрнестуэя появится в каждой библиотеке по всему миру!$B$BЕсли когда-нибудь захочешь почитать ее целиком, всегда найдешь тут у меня экземпляр. Спасибо еще раз, $n!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, $gнашел:нашла;? Не хотелось бы возвращать Хемингу неполную книгу.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Барнилу Каменному Горшку в лагерь экспедиции Эрнестуэя, что в Северной Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26270,'Прими нашу благодарность','Много лет нам никто не предлагал помощи, $n. Если бы не ты, нам не пережить бы наступающей зимы. Ты $gпоказал:показала; свою самоотверженность, а таким мы доверяем. Жаль, что у меня нет ничего ценного, чтобы предложить тебе.$B$BИ хотя я не знаю ничего такого, чтобы помочь тебе наказать убийц Хмуроброва, может, тебе поможет моя супруга. Поговори с Сальмой, и она расскажет тебе все, что стоит узнать прежде, чем ты уйдешь.','Поговорите с Сальмой Сальден на ферме Сальдена в Западном крае.','Конечно, дружок. Наша младшенькая работает на Сторожевом холме и очень тесно общается с бездомными жителями Западного края. Возможно, она кое-что слышала. Прежде, чем ты уйдешь, я отолью тебе с собой похлебки Западного края и расскажу кое-что о нашей младшенькой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прими нашу благодарность',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Много лет нам никто не предлагал помощи, $n. Если бы не ты, нам не пережить бы наступающей зимы. Ты $gпоказал:показала; свою самоотверженность, а таким мы доверяем. Жаль, что у меня нет ничего ценного, чтобы предложить тебе.$B$BИ хотя я не знаю ничего такого, чтобы помочь тебе наказать убийц Хмуроброва, может, тебе поможет моя супруга. Поговори с Сальмой, и она расскажет тебе все, что стоит узнать прежде, чем ты уйдешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Сальмой Сальден на ферме Сальдена в Западном крае.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Конечно, дружок. Наша младшенькая работает на Сторожевом холме и очень тесно общается с бездомными жителями Западного края. Возможно, она кое-что слышала. Прежде, чем ты уйдешь, я отолью тебе с собой похлебки Западного края и расскажу кое-что о нашей младшенькой.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26271,'Накормить голодных и отчаявшихся','Накормите похлебкой Западного края 20 бездомных в Сторожевом холме.','Вернитесь к Надежде Сальден на Сторожевой холм в Западном крае.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Накормить голодных и отчаявшихся',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Накормите похлебкой Западного края 20 бездомных в Сторожевом холме.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Надежде Сальден на Сторожевой холм в Западном крае.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26272,'Возрождение Черного Копья','Племя Черного Копья стало жертвой обстоятельств. Мы попали в изгнание. Раз за разом мы были вынуждены покидать свои дома... Однако на сей раз мы не сбежим как трусы.$B$BВол\'джин всегда мудро правил племенем и долгое время оберегал нас от невзгод. Сейчас же его мудрость подсказывает ему, что под началом Гарроша Адского Крика Орду ждет непонятное будущее.$B$BВ этот раз мы не сбежим. Мы будем сражаться за свой дом до конца.$B$BПора начать твое обучение, $n. Отправляйся на восток и поговори с Волдрекой.','Найдите Волдреку на тренировочной площадке Черного Копья.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возрождение Черного Копья',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Племя Черного Копья стало жертвой обстоятельств. Мы попали в изгнание. Раз за разом мы были вынуждены покидать свои дома... Однако на сей раз мы не сбежим как трусы.$B$BВол\'джин всегда мудро правил племенем и долгое время оберегал нас от невзгод. Сейчас же его мудрость подсказывает ему, что под началом Гарроша Адского Крика Орду ждет непонятное будущее.$B$BВ этот раз мы не сбежим. Мы будем сражаться за свой дом до конца.$B$BПора начать твое обучение, $n. Отправляйся на восток и поговори с Волдрекой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Волдреку на тренировочной площадке Черного Копья.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26273,'Азы мастерства: поражение цели','Ну ладно, $gдружище:подруга;. Начнем с самого простого. Хочу убедиться, что ты владеешь азами тайных искусств.$B$BДавай-ка попробуем поразить эти манекены-тики. Не торопись. Делай, как получится. А я посмотрю, насколько ты умеешь творить заклинания.','Уничтожьте 6 манекенов-тики.','Неплохо, подруга. В твоих заклинаниях чувствуется сила. У тебя врожденный талант! $B$BКонечно, придется потрудиться, чтобы овладеть магией по-настоящему. Но я тебя научу.','Вернитесь к Волдреке на тренировочную площадку Черного Копья на островах Эха.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Азы мастерства: поражение цели',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну ладно, $gдружище:подруга;. Начнем с самого простого. Хочу убедиться, что ты владеешь азами тайных искусств.$B$BДавай-ка попробуем поразить эти манекены-тики. Не торопись. Делай, как получится. А я посмотрю, насколько ты умеешь творить заклинания.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 6 манекенов-тики.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Неплохо, подруга. В твоих заклинаниях чувствуется сила. У тебя врожденный талант! $B$BКонечно, придется потрудиться, чтобы овладеть магией по-настоящему. Но я тебя научу.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Волдреке на тренировочную площадку Черного Копья на островах Эха.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26275,'Практическое занятие','Пора применить все эти умения на практике, $gдружище:подруга;. Для начала дам простое задание.$B$BСмотри, рыси убивают кабанов. А кабаны – наш продовольственный запас, и как-то вовсе не хочется им делиться. Если желаешь сегодня поужинать, кабаны должны быть живы. По крайней мере, до вечера.$B$BРыси здесь повсюду. Принеси мне побольше их шкур.','Добудьте 6 шкур буйногривой рыси.','Вернитесь к Волдреке на тренировочную площадку Черного Копья на островах Эха.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Практическое занятие',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пора применить все эти умения на практике, $gдружище:подруга;. Для начала дам простое задание.$B$BСмотри, рыси убивают кабанов. А кабаны – наш продовольственный запас, и как-то вовсе не хочется им делиться. Если желаешь сегодня поужинать, кабаны должны быть живы. По крайней мере, до вечера.$B$BРыси здесь повсюду. Принеси мне побольше их шкур.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 6 шкур буйногривой рыси.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Волдреке на тренировочную площадку Черного Копья на островах Эха.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26276,'Яма испытаний','Ты отлично $gсправился:справилась;, |3-6($c). Может, я и мог бы тебя еще чему-то научить, но глупо тратить время на тренировки.$B$BТебя ждет последний экзамен. Отправляйся в яму испытаний, что в центре этой области, и сразись с настоящим противником – таким, который жаждет тебя растерзать. Когда будешь $gготов:готова;, дай смотрителю знак.','Поговорите с тюремщиком Черного Копья, а затем спуститесь в яму испытаний и убейте пленного разведчика из клана Злобной Чешуи.','Вернитесь к Волдреке на тренировочную площадку Черного Копья на островах Эха.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Яма испытаний',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты отлично $gсправился:справилась;, |3-6($c). Может, я и мог бы тебя еще чему-то научить, но глупо тратить время на тренировки.$B$BТебя ждет последний экзамен. Отправляйся в яму испытаний, что в центре этой области, и сразись с настоящим противником – таким, который жаждет тебя растерзать. Когда будешь $gготов:готова;, дай смотрителю знак.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с тюремщиком Черного Копья, а затем спуститесь в яму испытаний и убейте пленного разведчика из клана Злобной Чешуи.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Волдреке на тренировочную площадку Черного Копья на островах Эха.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26277,'Превосходя ожидания','Ты превосходишь все наши ожидания, так что хватит ходить в новичках – самое время взяться за что-нибудь серьезное.$B$BОтправляйся в деревню, что к юго-востоку отсюда, и начинай выполнять различные поручения. Будь на виду – и тебе быстро предложат серьезную работу.','Поговорите с Вол\'джином в крепости Черного Копья.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Превосходя ожидания',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты превосходишь все наши ожидания, так что хватит ходить в новичках – самое время взяться за что-нибудь серьезное.$B$BОтправляйся в деревню, что к юго-востоку отсюда, и начинай выполнять различные поручения. Будь на виду – и тебе быстро предложат серьезную работу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Вол\'джином в крепости Черного Копья.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26278,'Защита Гром\'гола: угроза ящеров','Тром\'ка, |3-6($c)!$B$BТы очень вовремя $gприбыл:прибыла; в Гром\'гол. Мы должны наладить здесь поставку припасов в Каменор, но некоторые местные жители нам очень мешают.$B$BНазначаю тебя $gответственным:ответственной; за истребление ящеров в северных окрестностях Гром\'гола. Самих ящеров можно не бояться – ненормальные охотники Эрнестуэя о них позаботятся. А вот твоя задача перебить яйца ящеров.','Уничтожьте 12 яиц кнутохвоста.','Вернитесь к командиру Аггро\'гошу в лагерь Гром\'гол, что в Северной Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Защита Гром\'гола: угроза ящеров',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тром\'ка, |3-6($c)!$B$BТы очень вовремя $gприбыл:прибыла; в Гром\'гол. Мы должны наладить здесь поставку припасов в Каменор, но некоторые местные жители нам очень мешают.$B$BНазначаю тебя $gответственным:ответственной; за истребление ящеров в северных окрестностях Гром\'гола. Самих ящеров можно не бояться – ненормальные охотники Эрнестуэя о них позаботятся. А вот твоя задача перебить яйца ящеров.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 12 яиц кнутохвоста.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру Аггро\'гошу в лагерь Гром\'гол, что в Северной Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26279,'Защита Гром\'гола: нападение на огров','Когда мы прибыли в эти джунгли, у нас не было ни малейшего намерения воевать с местными племенами. Нам всего лишь надо было наладить поставку припасов в Каменор, причем как можно скорее. Но у нас возникли затруднения: в руинах Мизжа к юго-востоку от Гром\'гола появилась банда огров. Несмотря на все предупреждения, они постоянно нападают на наши обозы.$B$BНазначаю тебя $gответственным:ответственной; за уничтожение этих назойливых огров.$B$BОтправляйся в руины и попытайся выдворить их оттуда. По меньшей мере, это покажет им, что мы настроены серьезно.','Уничтожьте 4 громил и 4 знахарей из клана Мош\'огг.','Вернитесь к командиру Аггро\'гошу в лагерь Гром\'гол, что в Северной Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Защита Гром\'гола: нападение на огров',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда мы прибыли в эти джунгли, у нас не было ни малейшего намерения воевать с местными племенами. Нам всего лишь надо было наладить поставку припасов в Каменор, причем как можно скорее. Но у нас возникли затруднения: в руинах Мизжа к юго-востоку от Гром\'гола появилась банда огров. Несмотря на все предупреждения, они постоянно нападают на наши обозы.$B$BНазначаю тебя $gответственным:ответственной; за уничтожение этих назойливых огров.$B$BОтправляйся в руины и попытайся выдворить их оттуда. По меньшей мере, это покажет им, что мы настроены серьезно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 4 громил и 4 знахарей из клана Мош\'огг.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру Аггро\'гошу в лагерь Гром\'гол, что в Северной Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26280,'Защита Гром\'гола: угроза мурлоков','Убейте 15 черножабрых мурлоков.','Вернитесь к командиру Аггро\'гошу в лагерь Гром\'гол, что в Северной Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Защита Гром\'гола: угроза мурлоков',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 15 черножабрых мурлоков.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру Аггро\'гошу в лагерь Гром\'гол, что в Северной Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26281,'Защита Гром\'гола: троллье воровство','Тролли довольно много оставили здесь, в Гром\'голе. И большинство из них понимает, что Орда легко их раздавит, если разгневается, и здешние тролли тоже не исключение.$B$BОднако Кровавые Скальпы в последнее время что-то уж больно активизировались. На прошлой неделе они отправили партию в Гром\'гол и украли несколько ящиков с провиантом.$B$BВоровство еды дело простительное, но только не когда я тут командую. Отправляйся на север к руинам Бал\'лал и верни наше имущество.','Добудьте ящики с пайками Гром\'гола на руинах Бал\'лал.','Вернитесь к командиру Аггро\'гошу в лагерь Гром\'гол, что в Северной Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Защита Гром\'гола: троллье воровство',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тролли довольно много оставили здесь, в Гром\'голе. И большинство из них понимает, что Орда легко их раздавит, если разгневается, и здешние тролли тоже не исключение.$B$BОднако Кровавые Скальпы в последнее время что-то уж больно активизировались. На прошлой неделе они отправили партию в Гром\'гол и украли несколько ящиков с провиантом.$B$BВоровство еды дело простительное, но только не когда я тут командую. Отправляйся на север к руинам Бал\'лал и верни наше имущество.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте ящики с пайками Гром\'гола на руинах Бал\'лал.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру Аггро\'гошу в лагерь Гром\'гол, что в Северной Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (26282,'Милость Акил\'дара') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Милость Акил\'дара',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26283,'Жуть-муть','Меня в последнее время очень заинтересовали слизни, обитающие на Осклизлой скале. Сколько бы раз мы их ни истребляли, через какое-то время их там опять полно, при этом не похоже, чтобы они могли воспроизводиться от какого-то одного уцелевшего слизня.$B$BМне кажется, что там что-то растет. Там должен быть какой-то источник слизи, откуда они все и берутся, и я хочу изучить этот источник. Пожалуйста, найди его, и принеси мне оттуда образец.','Возьмите образец Вязкой Мути.','Потрясающе… Какого, говоришь, она была размера? Найти бы еще таких, но нетронутых…$B$BЭто великолепный образец! Я покажу его моим коллегам-исследователям.','Ну как? Что удалось найти?','Вернитесь к Малькольму Вендельсону в Деревню Сломанного Клыка, что во Внутренних землях.','Не подходи слишком близко… неизвестно, чего можно ждать от этой штуки.','Вязкая Муть') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жуть-муть',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Меня в последнее время очень заинтересовали слизни, обитающие на Осклизлой скале. Сколько бы раз мы их ни истребляли, через какое-то время их там опять полно, при этом не похоже, чтобы они могли воспроизводиться от какого-то одного уцелевшего слизня.$B$BМне кажется, что там что-то растет. Там должен быть какой-то источник слизи, откуда они все и берутся, и я хочу изучить этот источник. Пожалуйста, найди его, и принеси мне оттуда образец.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возьмите образец Вязкой Мути.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Потрясающе… Какого, говоришь, она была размера? Найти бы еще таких, но нетронутых…$B$BЭто великолепный образец! Я покажу его моим коллегам-исследователям.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как? Что удалось найти?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Малькольму Вендельсону в Деревню Сломанного Клыка, что во Внутренних землях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Не подходи слишком близко… неизвестно, чего можно ждать от этой штуки.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Вязкая Муть',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26284,'Пропавшие без вести','Для подобной работы мне обычно требуется вся моя команда подрывников. Чем больше людей занимается закладкой пороха, зарядов и остального снаряжения, тем быстрее идет дело.$b$bЭти проклятые трогги держат в форте Мерзлогривов много моих подрывников, а работу заканчивать надо.$b$bНо ты производишь впечатление $gспособного:способной:c; |3-1($c). Не найдешь ли захваченных троггами подрывников и не освободишь ли их?','Освободите 6 захваченных подрывников из клеток вокруг форта Мерзлогривов.','Благодарю тебя от имени спасенных подрывников и от себя лично. Парни уже приступили к работе по закладке взрывчатки внутри пещеры. Скоро все будет готово.','Вернитесь к Джессупу Маккри в форт Мерзлогривов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пропавшие без вести',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Для подобной работы мне обычно требуется вся моя команда подрывников. Чем больше людей занимается закладкой пороха, зарядов и остального снаряжения, тем быстрее идет дело.$b$bЭти проклятые трогги держат в форте Мерзлогривов много моих подрывников, а работу заканчивать надо.$b$bНо ты производишь впечатление $gспособного:способной:c; |3-1($c). Не найдешь ли захваченных троггами подрывников и не освободишь ли их?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Освободите 6 захваченных подрывников из клеток вокруг форта Мерзлогривов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Благодарю тебя от имени спасенных подрывников и от себя лично. Парни уже приступили к работе по закладке взрывчатки внутри пещеры. Скоро все будет готово.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джессупу Маккри в форт Мерзлогривов.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26285,'Верните мне мой порох!','Мне нужно много пороха, чтобы разрушить эти пещеры. Не знаю, думали ли об этом мерзкие трогги, когда воровали мои припасы и захватывали моих подрывников! На результат это не влияет.$b$bНо пока я не получу порох обратно, ничего взорвать не получится.$b$bОтправляйся на юг в форт Мерзлогривов и убивай всех троггов, каких найдешь. У любого из них могут быть мои бочонки с порохом.','Отправляйтесь в форт Мерзлогривов и отберите 7 украденных бочонков с порохом у костегрызов или мародеров из племени Каменной Челюсти.','Ну вот, теперь совсем другое дело. В конце концов у нас получится устроить взрыв.','Вернитесь к Джессупу Маккри в форт Мерзлогривов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Верните мне мой порох!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне нужно много пороха, чтобы разрушить эти пещеры. Не знаю, думали ли об этом мерзкие трогги, когда воровали мои припасы и захватывали моих подрывников! На результат это не влияет.$b$bНо пока я не получу порох обратно, ничего взорвать не получится.$b$bОтправляйся на юг в форт Мерзлогривов и убивай всех троггов, каких найдешь. У любого из них могут быть мои бочонки с порохом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в форт Мерзлогривов и отберите 7 украденных бочонков с порохом у костегрызов или мародеров из племени Каменной Челюсти.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну вот, теперь совсем другое дело. В конце концов у нас получится устроить взрыв.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джессупу Маккри в форт Мерзлогривов.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26286,'На защите Западного края','Добудьте гнолльские приказы атаковать.','Хеликс? Я слышал это имя раньше. Совсем недавно, честно говоря, но кто этот адмирал?','Ты добыл приказы?','Вернитесь к маршалу Гриану Камнегриву на Сторожевой холм в Западном крае.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На защите Западного края',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте гнолльские приказы атаковать.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хеликс? Я слышал это имя раньше. Совсем недавно, честно говоря, но кто этот адмирал?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты добыл приказы?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к маршалу Гриану Камнегриву на Сторожевой холм в Западном крае.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (26287,'Дружина Западного края','Вернитесь к капитану Данувину на Сторожевой холм в Западном крае.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дружина Западного края',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Данувину на Сторожевой холм в Западном крае.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (26288,'Джанго Крапчатый','К югу отсюда находится область Западного края, известная как Пыльные равнины. Насколько мы знаем, здешние гноллы сделали эту область своей неофициальной столицей. И, как в каждой столице, в сердце ее сидит предводитель. Если мы хотим покончить с нападениями, мы должны выследить главного гнолла и прикончить его.$B$BОтправляйся на Пыльные равнины, найди предводителя гнолов, Джанго Крапчатого, и прикончи его. И перебей всех гноллов, что попадутся тебе на пути.','Вернитесь к капитану Данувину на Сторожевой холм в Западном крае.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Джанго Крапчатый',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','К югу отсюда находится область Западного края, известная как Пыльные равнины. Насколько мы знаем, здешние гноллы сделали эту область своей неофициальной столицей. И, как в каждой столице, в сердце ее сидит предводитель. Если мы хотим покончить с нападениями, мы должны выследить главного гнолла и прикончить его.$B$BОтправляйся на Пыльные равнины, найди предводителя гнолов, Джанго Крапчатого, и прикончи его. И перебей всех гноллов, что попадутся тебе на пути.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Данувину на Сторожевой холм в Западном крае.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (26289,'Хеликс наслал на нас гноллов?$B$B<Кеарнен кивает на башню.>$B$BОн внутри. Он там много дней сидит. Я ждала момента, чтобы взять его.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хеликс наслал на нас гноллов?$B$B<Кеарнен кивает на башню.>$B$BОн внутри. Он там много дней сидит. Я ждала момента, чтобы взять его.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`endtext_loc8`) VALUES (26290,'Тайны башни','Войдите в башню Мортвейка и найдите Хеликса Отломчикса.','Тайна Хеликса раскрыта') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тайны башни',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Войдите в башню Мортвейка и найдите Хеликса Отломчикса.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Тайна Хеликса раскрыта',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26291,'Большой переполох в Луноречье.','Я вскоре составлю отчет и вернусь в Штормград. В ШРУ должны узнать о событиях в Западном крае. Рекомендую тебе сделать то же самое и доложить обо всем Гриану.','Доложите о том, что вам удалось обнаружить, маршалу Гриану Камнегриву на Сторожевом холме в Западном крае.','Кто эта таинственная фигура? Нам надо добраться до Луноречья.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Большой переполох в Луноречье.',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я вскоре составлю отчет и вернусь в Штормград. В ШРУ должны узнать о событиях в Западном крае. Рекомендую тебе сделать то же самое и доложить обо всем Гриану.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доложите о том, что вам удалось обнаружить, маршалу Гриану Камнегриву на Сторожевом холме в Западном крае.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Кто эта таинственная фигура? Нам надо добраться до Луноречья.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26292,'В Луноречье!','Некоторое время назад мы разбили лагерь у Луноречья, $n. Один из моих лучших солдат работает в этой округе вместе с отрядом бойцов со Сторожевого холма. Доложись капитану Алперту и узнай, нет ли у него новостей о событиях в Луноречье.$B$BТам находится еще один мой союзник по имени Торелий. Я встретился с ним в Нордсколе, пока был в Валгарде. Он умный и могучий шаман. Возможно, он поможет нам раскрыть эту тайну.','Доложитесь капитану Алперту в Луноречье в Западном крае.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В Луноречье!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Некоторое время назад мы разбили лагерь у Луноречья, $n. Один из моих лучших солдат работает в этой округе вместе с отрядом бойцов со Сторожевого холма. Доложись капитану Алперту и узнай, нет ли у него новостей о событиях в Луноречье.$B$BТам находится еще один мой союзник по имени Торелий. Я встретился с ним в Нордсколе, пока был в Валгарде. Он умный и могучий шаман. Возможно, он поможет нам раскрыть эту тайну.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доложитесь капитану Алперту в Луноречье в Западном крае.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26293,'Боевые машины','Поговорите со штейгером Глиббсом у задних врат Оргриммара в Оргриммаре.','У меня много дел. Уходи.$B$BСтой! Что? Тебя послал Адский Крик? Что... э-э... что я могу сделать для тебя? Для него? Для нас?','Поговорите со штейгером Глиббсом у задних врат Оргриммара в Оргриммаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Боевые машины',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите со штейгером Глиббсом у задних врат Оргриммара в Оргриммаре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','У меня много дел. Уходи.$B$BСтой! Что? Тебя послал Адский Крик? Что... э-э... что я могу сделать для тебя? Для него? Для нас?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите со штейгером Глиббсом у задних врат Оргриммара в Оргриммаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26294,'Оружие массовой дисфункции','Осматривайте "Разрушители Адского Крика", пока не найдете машину с дефектом, а затем проучите главного инженера.','<Гаррош смеется.>$B$BЗначит, тебе удалось внушить им кое-какое представление о дисциплине, да? Отлично, отлично!$B$BВ моей Орде каждый должен вносить свой вклад в общее дело – от чернорабочего до самого прославленного воина. Ничего иного я не потерплю.$B$BПодготовка к вторжению почти завершена.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оружие массовой дисфункции',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Осматривайте "Разрушители Адского Крика", пока не найдете машину с дефектом, а затем проучите главного инженера.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Гаррош смеется.>$B$BЗначит, тебе удалось внушить им кое-какое представление о дисциплине, да? Отлично, отлично!$B$BВ моей Орде каждый должен вносить свой вклад в общее дело – от чернорабочего до самого прославленного воина. Ничего иного я не потерплю.$B$BПодготовка к вторжению почти завершена.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26295,'Пропаганда','Мы заметили рост правонарушений среди бездомных в округе. Что-то – или кто-то – взбудоражило их. Что бы за этим ни стояло, все это стало более организованным. Совсем недавно группа бандитов явилась сюда со своими прокламациями.$B$BОтправляйся в Луноречье и поищи улики. Пропагандистские плакаты, листовки, все что угодно... Что найдешь, принеси мне. Может, по этим писулькам мы узнаем, кто за этим стоит.','Добудьте информационный буклет, тайный дневник, выпуск луноречского вестника и таинственное воззвание.','В? Единственный В, которого я знал, был ван Клиф, Но он умер много лет назад.','Ну, удалось?','Вернитесь к капитану Алперту в Луноречье в Западном крае.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пропаганда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы заметили рост правонарушений среди бездомных в округе. Что-то – или кто-то – взбудоражило их. Что бы за этим ни стояло, все это стало более организованным. Совсем недавно группа бандитов явилась сюда со своими прокламациями.$B$BОтправляйся в Луноречье и поищи улики. Пропагандистские плакаты, листовки, все что угодно... Что найдешь, принеси мне. Может, по этим писулькам мы узнаем, кто за этим стоит.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте информационный буклет, тайный дневник, выпуск луноречского вестника и таинственное воззвание.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','В? Единственный В, которого я знал, был ван Клиф, Но он умер много лет назад.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, удалось?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Алперту в Луноречье в Западном крае.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26296,'Сбор доказательств','Добудьте 6 красных бандан.','Я пять лет не видел красных бандан. Неужто эта таинственная личность пытается вернуть Братству Справедливости былую силу?','Красные банданы?!','Вернитесь к капитану Алперту в Луноречье в Западном крае.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сбор доказательств',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 6 красных бандан.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я пять лет не видел красных бандан. Неужто эта таинственная личность пытается вернуть Братству Справедливости былую силу?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Красные банданы?!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Алперту в Луноречье в Западном крае.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26297,'Заря нового дня','Сдается, встреча, о которой говорила та темная личность, скоро начнется. Бездомные мобилизуются. Я хочу, чтобы ты $gпобывал:побывала; на встрече и $gдобыл:добыла; информацию, $n.$B$BОтправляйся в центр Луноречья и узнай, что там будет говориться. Обо всем, что узнаешь, доложи мне.','Отправляйтесь на условленое место в Луноречье и добудьте необходимую информацию.','Вернитесь к капитану Алперту в Луноречье в Западном крае.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Заря нового дня',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сдается, встреча, о которой говорила та темная личность, скоро начнется. Бездомные мобилизуются. Я хочу, чтобы ты $gпобывал:побывала; на встрече и $gдобыл:добыла; информацию, $n.$B$BОтправляйся в центр Луноречья и узнай, что там будет говориться. Обо всем, что узнаешь, доложи мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь на условленое место в Луноречье и добудьте необходимую информацию.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Алперту в Луноречье в Западном крае.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26298,'Поиски Йеннику','Это рок. Рок преследует младшего сына моего вождя Йеннику. Как у нас заведено, его отдали троллям племени Гурубаши в Зул\'Гуруб, но когда мое племя – племя Черного Копья – ушло вместе с орком Траллом, бедный Йеннику потерялся. Меня послали из далекого Оргриммара обратно в Тернистую долину на поиски сына вождя.$B$BЯ думаю, он у племени Кровавых Скальпов.$B$BЕсли хочешь мне помочь, выследи Кровавых Скальпов – они обитают на севере. Принеси мне их клыки.','Добудьте 6 клыков троллей из племени Кровавого Скальпа в руинах Бал\'лал.','Вернитесь к Нимбойе в лагерь Гром\'гол, что в Северной Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поиски Йеннику',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это рок. Рок преследует младшего сына моего вождя Йеннику. Как у нас заведено, его отдали троллям племени Гурубаши в Зул\'Гуруб, но когда мое племя – племя Черного Копья – ушло вместе с орком Траллом, бедный Йеннику потерялся. Меня послали из далекого Оргриммара обратно в Тернистую долину на поиски сына вождя.$B$BЯ думаю, он у племени Кровавых Скальпов.$B$BЕсли хочешь мне помочь, выследи Кровавых Скальпов – они обитают на севере. Принеси мне их клыки.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 6 клыков троллей из племени Кровавого Скальпа в руинах Бал\'лал.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Нимбойе в лагерь Гром\'гол, что в Северной Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26299,'Охота за головами','Нужно узнать, мертв ли Йеннику.$B$BУбей троллей из племени Кровавого Скальпа в Зуулдая и забери у них сушеные головы. Собрать нужно много, очень много, а я потом их все осмотрю и удостоверюсь, что Йеннику среди них нет.$B$BА если тролли все же убили Йеннику, то пусть на душу их предводителя Ган\'зулаха падет шестисотлетнее проклятие!$B$BСтупай, $n. Головы нужно искать в руинах Зуулдая, это на побережье к северу отсюда.','Раздобудьте 25 сушеных голов, которые носят при себе тролли из племени Кровавого Скальпа, живущие в руинах Зуулдая.','Вернитесь к Нимбойе в лагерь Гром\'гол, что в Северной Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота за головами',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нужно узнать, мертв ли Йеннику.$B$BУбей троллей из племени Кровавого Скальпа в Зуулдая и забери у них сушеные головы. Собрать нужно много, очень много, а я потом их все осмотрю и удостоверюсь, что Йеннику среди них нет.$B$BА если тролли все же убили Йеннику, то пусть на душу их предводителя Ган\'зулаха падет шестисотлетнее проклятие!$B$BСтупай, $n. Головы нужно искать в руинах Зуулдая, это на побережье к северу отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте 25 сушеных голов, которые носят при себе тролли из племени Кровавого Скальпа, живущие в руинах Зуулдая.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Нимбойе в лагерь Гром\'гол, что в Северной Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26300,'Знания Неззилока','Я не обнаружил Йеннику среди голов, хвала Великому Змею! Но мы не сильно продвинулись в наших поисках.$B$BНеобходимо выяснить истину, но боюсь, она известна лишь знахарю племени Кровавого Скальпа. Он враг племени Черного Копья и просто так говорить не будет – поэтому надо вырвать правду из его мертвых губ!$B$BПринеси мне голову Неззилока Зловещего и положи в этот котел.$B$BЭтот тролль живет в глубине Зул\'Кунды. Только доставь голову... а уж говорить мы ее заставим.','Отрубите голову Неззилоку Зловещему в Зул\'Кунде.','Положи голову Неззилока в котел...','Зеленый отвар в котле бурлит.','Вернитесь к бурлящему котлу в лагерь Гром\'гол в Северной Тернистой долине.','Главный знахарь племени Кровавого Скальпа находится в глубине руин Зул\'Кунды.','Неззилок Зловещий') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Знания Неззилока',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я не обнаружил Йеннику среди голов, хвала Великому Змею! Но мы не сильно продвинулись в наших поисках.$B$BНеобходимо выяснить истину, но боюсь, она известна лишь знахарю племени Кровавого Скальпа. Он враг племени Черного Копья и просто так говорить не будет – поэтому надо вырвать правду из его мертвых губ!$B$BПринеси мне голову Неззилока Зловещего и положи в этот котел.$B$BЭтот тролль живет в глубине Зул\'Кунды. Только доставь голову... а уж говорить мы ее заставим.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отрубите голову Неззилоку Зловещему в Зул\'Кунде.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Положи голову Неззилока в котел...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Зеленый отвар в котле бурлит.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к бурлящему котлу в лагерь Гром\'гол в Северной Тернистой долине.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Главный знахарь племени Кровавого Скальпа находится в глубине руин Зул\'Кунды.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Неззилок Зловещий',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26301,'Разговор с Неззилоком','<Голова Неззилока начинает говорить.>$B$BЭто верно. Мне известно, куда забрали дитя Черного Копья. Да, ты $gпобедил:победила; и $gпленил:пленила; мою душу, но я ничего не скажу, если ты не умиротворишь меня!$B$BКровавые Скальпы воюют с Дробителями Черепов. Хочешь заслужить мою благосклонность – укради у Дробителей Черепов, живущих за рекой на востоке, два самых ценных трофейных черепа. Положи их здесь, чтобы у моей души в Пустоте были рабы. Один череп должен быть из груды трофеев в Балиа\'ма, второй – из Зиата\'джай.','Добудьте трофей из Балиа\'ма и Зиата\'джай в руинах Дробителей Черепов в Северной Тернистой долине.','Вернитесь к бурлящему котлу в лагерь Гром\'гол в Северной Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разговор с Неззилоком',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Голова Неззилока начинает говорить.>$B$BЭто верно. Мне известно, куда забрали дитя Черного Копья. Да, ты $gпобедил:победила; и $gпленил:пленила; мою душу, но я ничего не скажу, если ты не умиротворишь меня!$B$BКровавые Скальпы воюют с Дробителями Черепов. Хочешь заслужить мою благосклонность – укради у Дробителей Черепов, живущих за рекой на востоке, два самых ценных трофейных черепа. Положи их здесь, чтобы у моей души в Пустоте были рабы. Один череп должен быть из груды трофеев в Балиа\'ма, второй – из Зиата\'джай.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте трофей из Балиа\'ма и Зиата\'джай в руинах Дробителей Черепов в Северной Тернистой долине.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к бурлящему котлу в лагерь Гром\'гол в Северной Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26302,'Судьба Йеннику','<Неззилок говорит.>$B$BТы $gсослужил:сослужила; мне хорошую службу, и я скажу тебе все, что ты хочешь знать... $B$BЮный Йеннику потерян для своего племени.$B$BЕго забрал к себе знахарь Занзил Отверженный. Теперь Йеннику – полностью в его власти... и душой, и телом... и его может освободить только очень сильная магия.$B$BТы такой магией не владеешь, |3-6($c).$B$BНадежды практически нет. Хотя, может быть, твои союзники из Черного Копья в Бамбале на востоке все-таки сумеют спасти Йеннику. Но я сомневаюсь...','Поговорите с Кин\'вилаем в Бамбале.','Занзил Отверженный?$B$BЕсли Йеннику у этого тролля – подлеца и мерзавца, да к тому же сильного знахаря, – боюсь, что надежды практически нет.$B$BНо есть одна мысль... И если мои подозрения оправдаются, тогда, может быть, нам удастся спасти Йеннику.','Поговорите с Кин\'вилаем в Бамбале в Северной Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Судьба Йеннику',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Неззилок говорит.>$B$BТы $gсослужил:сослужила; мне хорошую службу, и я скажу тебе все, что ты хочешь знать... $B$BЮный Йеннику потерян для своего племени.$B$BЕго забрал к себе знахарь Занзил Отверженный. Теперь Йеннику – полностью в его власти... и душой, и телом... и его может освободить только очень сильная магия.$B$BТы такой магией не владеешь, |3-6($c).$B$BНадежды практически нет. Хотя, может быть, твои союзники из Черного Копья в Бамбале на востоке все-таки сумеют спасти Йеннику. Но я сомневаюсь...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Кин\'вилаем в Бамбале.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Занзил Отверженный?$B$BЕсли Йеннику у этого тролля – подлеца и мерзавца, да к тому же сильного знахаря, – боюсь, что надежды практически нет.$B$BНо есть одна мысль... И если мои подозрения оправдаются, тогда, может быть, нам удастся спасти Йеннику.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Кин\'вилаем в Бамбале в Северной Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26303,'Глаз разума','Глаз разума находится у одного огра-мага, в кургане Мош\'Огга к югу отсюда. Зовут его Май\'Зот. Я знаю его еще с тех пор, как племя Черного Копья жило в Тернистой долине. Он коварен и обладает сильной магией.$B$BЕсли Глаз разума у него, его магия станет еще мощнее.$B$BТебе надо сразиться с Май\'Зотом и отнять у него Глаз разума. Это опасное задание, но только так мы можем спасти Йеннику.','Отнимите Глаз разума у Май\'Зота.','Вернитесь к Кин\'вилаю в Бамбалу, что в Северной Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Глаз разума',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Глаз разума находится у одного огра-мага, в кургане Мош\'Огга к югу отсюда. Зовут его Май\'Зот. Я знаю его еще с тех пор, как племя Черного Копья жило в Тернистой долине. Он коварен и обладает сильной магией.$B$BЕсли Глаз разума у него, его магия станет еще мощнее.$B$BТебе надо сразиться с Май\'Зотом и отнять у него Глаз разума. Это опасное задание, но только так мы можем спасти Йеннику.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнимите Глаз разума у Май\'Зота.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кин\'вилаю в Бамбалу, что в Северной Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26304,'Ночь в джунглях','Год назад мою мать – вернее, тролльскую женщину, которая обо мне заботилась, – похитили Дробители Черепов из Зул\'Мамве. В отчаянии я побежал за ней. Но тут целая дюжина воинов потащила ее к горящей жаровне. Я спрятался за деревом и видел, как они схватили ее и... и...$B$B<Кил\'карил отводит взгляд.>$B$BПо ночам свет этих жаровен отражается от вершин деревьев и не дает мне уснуть... Прошу тебя, $n... сходи на юг в Зул\'Мамве и погаси их.','Потушите 8 жаровен в Зул\'Мамве, что в Северной Тернистой долине.','Этой ночью дух моей матери будет спать спокойно, $n.$b$bИ я тоже.','Вернитесь к Кил\'Карилу в Бамбалу, что в Северной Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ночь в джунглях',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Год назад мою мать – вернее, тролльскую женщину, которая обо мне заботилась, – похитили Дробители Черепов из Зул\'Мамве. В отчаянии я побежал за ней. Но тут целая дюжина воинов потащила ее к горящей жаровне. Я спрятался за деревом и видел, как они схватили ее и... и...$B$B<Кил\'карил отводит взгляд.>$B$BПо ночам свет этих жаровен отражается от вершин деревьев и не дает мне уснуть... Прошу тебя, $n... сходи на юг в Зул\'Мамве и погаси их.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Потушите 8 жаровен в Зул\'Мамве, что в Северной Тернистой долине.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Этой ночью дух моей матери будет спать спокойно, $n.$b$bИ я тоже.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кил\'Карилу в Бамбалу, что в Северной Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26305,'Спасение Йеннику','Я превратил Око разума в самоцвет души. Он послужит двоякой цели: сначала оглуши им Йеннику, а затем помести самоцвет ему на голову и поймай душу.$B$BМои подозрения подтвердились: Йеннику живет не у Занзила Отверженного, а в Руинах Зул\'Мамве, расположенных к юго-западу отсюда. Как только освободишь душу Йеннику, возвращайся в Гром\'гол к Нимбойе.','Отнесите Нимбойе наполненный самоцвет души.','Вернитесь к Нимбойе в лагерь Гром\'гол, что в Северной Тернистой долине.','Ему столько пришлось пережить... Пора освободить его душу.','Йеннику') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спасение Йеннику',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я превратил Око разума в самоцвет души. Он послужит двоякой цели: сначала оглуши им Йеннику, а затем помести самоцвет ему на голову и поймай душу.$B$BМои подозрения подтвердились: Йеннику живет не у Занзила Отверженного, а в Руинах Зул\'Мамве, расположенных к юго-западу отсюда. Как только освободишь душу Йеннику, возвращайся в Гром\'гол к Нимбойе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите Нимбойе наполненный самоцвет души.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Нимбойе в лагерь Гром\'гол, что в Северной Тернистой долине.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Ему столько пришлось пережить... Пора освободить его душу.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Йеннику',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26306,'Начало расправы','Сегодня мы нанесем первый удар в самое сердце гнусного племени Порочной Ветви. Не щади никого, $n, это уже не просто размолвка между троллями. Каждая победа Сломанного Клыка – это победа Орды!$B$BОхотники за головами и знахари племени Порочной Ветви станут нашими первыми жертвами. Займись нижними ярусами и не возвращайся, пока не искупаешь свое оружие во вражеской крови.','Убейте 5 знахарей и 5 охотников за головами из племени Порочной Ветви в Джинта\'Алоре.','Вернитесь к Старейшине Сломанному Клыку в Джинта\'Алор, что во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Начало расправы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сегодня мы нанесем первый удар в самое сердце гнусного племени Порочной Ветви. Не щади никого, $n, это уже не просто размолвка между троллями. Каждая победа Сломанного Клыка – это победа Орды!$B$BОхотники за головами и знахари племени Порочной Ветви станут нашими первыми жертвами. Займись нижними ярусами и не возвращайся, пока не искупаешь свое оружие во вражеской крови.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 5 знахарей и 5 охотников за головами из племени Порочной Ветви в Джинта\'Алоре.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Старейшине Сломанному Клыку в Джинта\'Алор, что во Внутренних землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26307,'Смерть Порочной Ветви!','Не дадим им возможности ответить. Тебе надо пойти в Джинта\'Алор и прорваться на верхние ярусы.$B$BБерсерки и темные чародеи из племени Порочной Ветви – очень опасные враги, $n. Когда остальные увидят, как мы перекидываем их трупы через стены, они поймут, что мы не шутки шутить сюда пришли.$B$BНе оставляй никого в живых!','Убейте 5 берсерков и 5 темных чародеев из племени Порочной Ветви в Джинта\'Алоре.','Скоро мы останемся единственными троллями в этих стенах.','Вернитесь к Старейшине Сломанному Клыку в Джинта\'Алор, что во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Смерть Порочной Ветви!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не дадим им возможности ответить. Тебе надо пойти в Джинта\'Алор и прорваться на верхние ярусы.$B$BБерсерки и темные чародеи из племени Порочной Ветви – очень опасные враги, $n. Когда остальные увидят, как мы перекидываем их трупы через стены, они поймут, что мы не шутки шутить сюда пришли.$B$BНе оставляй никого в живых!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 5 берсерков и 5 темных чародеев из племени Порочной Ветви в Джинта\'Алоре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Скоро мы останемся единственными троллями в этих стенах.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Старейшине Сломанному Клыку в Джинта\'Алор, что во Внутренних землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26308,'Победа наша!','Остались только самые стойкие и злобные из племени Порочной Ветви – кровопийцы и пожиратели душ, поклоняющиеся Хаккару.$B$BОни все ИДИОТЫ! Держатся за старые дурацкие верования. Я не собираюсь больше терпеть их преступления против племени Сломанного Клыка.$B$BНанесем им последний удар. Завоюем Джинта\'Алор для Сломанного Клыка и для Орды!','Убейте 5 кровопийц и 5 пожирателей душ из племени Порочной Ветви в Джинта\'Алоре.','Вернитесь к Старейшине Сломанному Клыку в Джинта\'Алор, что во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Победа наша!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Остались только самые стойкие и злобные из племени Порочной Ветви – кровопийцы и пожиратели душ, поклоняющиеся Хаккару.$B$BОни все ИДИОТЫ! Держатся за старые дурацкие верования. Я не собираюсь больше терпеть их преступления против племени Сломанного Клыка.$B$BНанесем им последний удар. Завоюем Джинта\'Алор для Сломанного Клыка и для Орды!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 5 кровопийц и 5 пожирателей душ из племени Порочной Ветви в Джинта\'Алоре.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Старейшине Сломанному Клыку в Джинта\'Алор, что во Внутренних землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26309,'Темные сосуды','Тролли племени Порочной Ветви пили порченую кровь бога Хаккара, чтобы набраться сил. Они кипятили ее в котлах, и теперь эти сосуды полны нечистой силы.$B$BХаккар давно убит, но вот что странно... я все еще замечаю тут кипящие котлы. Принеси мне несколько, и мы посмотрим, что это такое они тут варят.','Соберите 5 Сосудов с порченой кровью в Джинта\'Алоре.','Вернитесь к Элизе Желчной в Джинта\'Алор, что во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Темные сосуды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тролли племени Порочной Ветви пили порченую кровь бога Хаккара, чтобы набраться сил. Они кипятили ее в котлах, и теперь эти сосуды полны нечистой силы.$B$BХаккар давно убит, но вот что странно... я все еще замечаю тут кипящие котлы. Принеси мне несколько, и мы посмотрим, что это такое они тут варят.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 5 Сосудов с порченой кровью в Джинта\'Алоре.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Элизе Желчной в Джинта\'Алор, что во Внутренних землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26310,'Быстролапые паучата','Иди сюда, |3-6($c)...$B$BЕсть у меня пара знакомых торговцев, очень заинтересованных в сильных ядах. Так вот, заметила я паучат, которые тут бегают. Нет, я не про больших, а про маленьких, которые размером примерно с твою руку.$B$BОни такого необычного для наших краев цвета... Поймай несколько и принеси их мне.','Соберите 8 быстролапых паучков в Джинта\'Алоре.','Да… Не зря я просила тебя их поймать. Как интересно! $B$BИдите сюда, крошки мои, в сумку, вот так…','Сколько их у тебя?','Вернитесь к Элизе Желчной в Джинта\'Алор, что во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Быстролапые паучата',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Иди сюда, |3-6($c)...$B$BЕсть у меня пара знакомых торговцев, очень заинтересованных в сильных ядах. Так вот, заметила я паучат, которые тут бегают. Нет, я не про больших, а про маленьких, которые размером примерно с твою руку.$B$BОни такого необычного для наших краев цвета... Поймай несколько и принеси их мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 быстролапых паучков в Джинта\'Алоре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да… Не зря я просила тебя их поймать. Как интересно! $B$BИдите сюда, крошки мои, в сумку, вот так…',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Сколько их у тебя?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Элизе Желчной в Джинта\'Алор, что во Внутренних землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26311,'Неизведанные воды','<Сауранок слушает ваш рассказ; похоже, карта его совершенно не интересует.>$B$BСумеречные убийцы шли за тобой до самого бара? Здесь, в Оргриммаре?$B$BВождь будет недоволен.$B$BПродолжай готовиться к вторжению, а я расследую это дело.','Вернитесь в Оргриммар, в крепость Громмаш и отдайте карту Саураноку Мистику.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Неизведанные воды',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Сауранок слушает ваш рассказ; похоже, карта его совершенно не интересует.>$B$BСумеречные убийцы шли за тобой до самого бара? Здесь, в Оргриммаре?$B$BВождь будет недоволен.$B$BПродолжай готовиться к вторжению, а я расследую это дело.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь в Оргриммар, в крепость Громмаш и отдайте карту Саураноку Мистику.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26312,'Неравный бой','Когда началась атака, мы сразу же дали отпор врагу, чтобы занять поле. Но вражеские войска были огромны... мы недооценили их силы. И теперь лучшие наши шаманы остались там, без нашей защиты, почти без сил, в весьма затруднительном положении.$b$bОтправляйся туда и выручи наших братьев. Даже короткая передышка в бою поможет им.$b$bТоропись, |3-6($c).','Помогите Тону Зимнему Утесу, буревестнице Милре и Харготу Бледному Пламени победить их противников, чтобы они смогли перевести дух.','Вернитесь к заклинателю земли Торунскару. Его можно найти к западу от Храма Земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Неравный бой',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда началась атака, мы сразу же дали отпор врагу, чтобы занять поле. Но вражеские войска были огромны... мы недооценили их силы. И теперь лучшие наши шаманы остались там, без нашей защиты, почти без сил, в весьма затруднительном положении.$b$bОтправляйся туда и выручи наших братьев. Даже короткая передышка в бою поможет им.$b$bТоропись, |3-6($c).',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Помогите Тону Зимнему Утесу, буревестнице Милре и Харготу Бледному Пламени победить их противников, чтобы они смогли перевести дух.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к заклинателю земли Торунскару. Его можно найти к западу от Храма Земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26313,'Суть наших проблем','Элементали хаотичны по своей природе, но такая направленная агрессия им не свойственна. Особенно здесь, где они постоянно погибают. Подозреваю, что это дело рук Матери-Скалы Теразан, но мне нужно быть абсолютно уверенной.$b$bУбей яростных грохотунов и принеси мне их сердца. И мы решим, действительно ли ненависть Матери-Скалы всему причиной.','Соберите 6 сердец яростных грохотунов.','Они в удивительно хорошем состоянии. Отлично, приятель.','Мы никогда не претендовали на дружбу с повелителями элементалей, но верили, что от них можно не ждать вреда. Они ничем нам не угрожали, пока их силы были разрозненны.$B$BНо если Мать-Скала действительно настраивает силы земли против нас, то нам есть, чего опасаться.','Вернитесь к целительнице земли Норсале. Ее можно найти к западу от Храма Земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Суть наших проблем',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Элементали хаотичны по своей природе, но такая направленная агрессия им не свойственна. Особенно здесь, где они постоянно погибают. Подозреваю, что это дело рук Матери-Скалы Теразан, но мне нужно быть абсолютно уверенной.$b$bУбей яростных грохотунов и принеси мне их сердца. И мы решим, действительно ли ненависть Матери-Скалы всему причиной.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 6 сердец яростных грохотунов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Они в удивительно хорошем состоянии. Отлично, приятель.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мы никогда не претендовали на дружбу с повелителями элементалей, но верили, что от них можно не ждать вреда. Они ничем нам не угрожали, пока их силы были разрозненны.$B$BНо если Мать-Скала действительно настраивает силы земли против нас, то нам есть, чего опасаться.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к целительнице земли Норсале. Ее можно найти к западу от Храма Земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26314,'На ровной земле','Нам повезло, эти великаны – отличные мишени. Надо воспользоваться удачей.$b$bНам нужно убрать их с поля боя, но не думаю, что атаковать их в лоб, будет очень умно.$b$bВозьми вот эти "кошки", хорошенько закрепи их на лодыжках великанов и тяни как следует. Когда они окажутся на земле, прикончить их будет уже очень легко.','Воспользуйтесь элементиевыми "кошками", чтобы сбить с ног 3 слуг Теразан.','Это слегка замедлит их атаку, пока Норсала не найдет способ успокоить их. У нас нет желания оставаться врагами Матери-Скалы Теразан.','Вернитесь к заклинателю земли Торунскару. Его можно найти к западу от Храма Земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На ровной земле',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нам повезло, эти великаны – отличные мишени. Надо воспользоваться удачей.$b$bНам нужно убрать их с поля боя, но не думаю, что атаковать их в лоб, будет очень умно.$b$bВозьми вот эти "кошки", хорошенько закрепи их на лодыжках великанов и тяни как следует. Когда они окажутся на земле, прикончить их будет уже очень легко.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь элементиевыми "кошками", чтобы сбить с ног 3 слуг Теразан.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это слегка замедлит их атаку, пока Норсала не найдет способ успокоить их. У нас нет желания оставаться врагами Матери-Скалы Теразан.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к заклинателю земли Торунскару. Его можно найти к западу от Храма Земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26315,'Впечатляющая встреча','Прочитайте воззвание Служителей Земли Бодену Впечатляющему.','Да, приятель… Другой реакции мы и не ждали.$B$BТак он говорил о Диаманте? Если эти двое не могут ужиться, это может означать, что с этим Диамантом легче иметь дело, чем с Боденом.$B$BПодожди, я узнаю у Земли, где найти Диаманта.','Вернитесь к целительнице земли Норсале. Ее можно найти к западу от Храма Земли.','Не всегда легко избежать взглядов свысока.','Боден Впечатляющий') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Впечатляющая встреча',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Прочитайте воззвание Служителей Земли Бодену Впечатляющему.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, приятель… Другой реакции мы и не ждали.$B$BТак он говорил о Диаманте? Если эти двое не могут ужиться, это может означать, что с этим Диамантом легче иметь дело, чем с Боденом.$B$BПодожди, я узнаю у Земли, где найти Диаманта.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к целительнице земли Норсале. Ее можно найти к западу от Храма Земли.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Не всегда легко избежать взглядов свысока.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Боден Впечатляющий',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (26316,'Взорвать туннели несложно, но чтобы приступить к выполнению задания, мне нужна команда и оборудование.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Взорвать туннели несложно, но чтобы приступить к выполнению задания, мне нужна команда и оборудование.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26317,'Детеныш кнутохвоста','Вы уже приготовились нанести последний удар по кладке яиц кнутохвоста, как вдруг глянули вниз и увидели, что на вас смотрит едва вылупившийся детеныш. Он словно изучал вас, запоминал черты вашего лица и повторял все ваши движения.$B$BМежду вами и детенышем кнутохвоста установилась некая связь.$B$BВам было приказано уменьшить поголовье ящеров, но задание вы уже и так выполнили, а этот детеныш еще ни в чем не провинился. Может, кто-нибудь в лагере Гром\'гол подскажет вам, что с ним делать.','Принесите детеныша кнутохвоста провозвестнику Мок\'тардину в лагерь Гром\'гол.','Поговорите с провозвестником Мок\'тардином в лагере Гром\'гол, что в Северной Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Детеныш кнутохвоста',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы уже приготовились нанести последний удар по кладке яиц кнутохвоста, как вдруг глянули вниз и увидели, что на вас смотрит едва вылупившийся детеныш. Он словно изучал вас, запоминал черты вашего лица и повторял все ваши движения.$B$BМежду вами и детенышем кнутохвоста установилась некая связь.$B$BВам было приказано уменьшить поголовье ящеров, но задание вы уже и так выполнили, а этот детеныш еще ни в чем не провинился. Может, кто-нибудь в лагере Гром\'гол подскажет вам, что с ним делать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите детеныша кнутохвоста провозвестнику Мок\'тардину в лагерь Гром\'гол.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с провозвестником Мок\'тардином в лагере Гром\'гол, что в Северной Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26318,'Окончание работы','Проберитесь в нижнюю часть пещеры, расположенной в форте Мерзлогривов, убейте босса Бруггора и активируйте детонатор, чтобы взорвать туннели троггов.','Взрыв слышен даже здесь! Мои ребята славно потрудились, подготовив этот взрыв, но его бы не было без твоей помощи. Будет только справедливо, если за помощь в этой работе я поделюсь с тобой своим гонораром.','Вернитесь к Джессупу Маккри в форт Мерзлогривов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Окончание работы',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проберитесь в нижнюю часть пещеры, расположенной в форте Мерзлогривов, убейте босса Бруггора и активируйте детонатор, чтобы взорвать туннели троггов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Взрыв слышен даже здесь! Мои ребята славно потрудились, подготовив этот взрыв, но его бы не было без твоей помощи. Будет только справедливо, если за помощь в этой работе я поделюсь с тобой своим гонораром.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джессупу Маккри в форт Мерзлогривов.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26319,'Тайна раскрыта','Здесь есть шаман, Торелий, который сможет помочь нам. Он друг Гриана, который недавно прибыл в Западный край, чтобы изучить стихийные бедствия, обрушившиеся на нас в последнее время.$B$BПоговори с Торелийом и посмотри, не сможет ли он пролить свет на эту таинственную темную личность.','Поговорите с Торелием Мудрым в Луноречье в Западном крае.','Хмм, да, вероятно, я мог бы вам помочь. Когда я был в Нордсколе, то помог народу Валгарда раскрыть несколько тайн врайкулов, погрузившись в мир духов. Возможно, такое удастся сделать и здесь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тайна раскрыта',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Здесь есть шаман, Торелий, который сможет помочь нам. Он друг Гриана, который недавно прибыл в Западный край, чтобы изучить стихийные бедствия, обрушившиеся на нас в последнее время.$B$BПоговори с Торелийом и посмотри, не сможет ли он пролить свет на эту таинственную темную личность.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Торелием Мудрым в Луноречье в Западном крае.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хмм, да, вероятно, я мог бы вам помочь. Когда я был в Нордсколе, то помог народу Валгарда раскрыть несколько тайн врайкулов, погрузившись в мир духов. Возможно, такое удастся сделать и здесь.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (26320,'Видения прошлого','Эти благовония погрузят твое тело и разум в состояние глубокой медитации. Как только начнется транс, тебя увлечет в мир духов. Не сопротивляйся трансу, когда он начнет овладевать тобой, $n. Дай духам показать тебе то, что они знают.$B$BТеперь уходи. Иди к Мертвым копям, к месту, которое, как мне говорили, имеет большое значение в истории Западного края. Как окажешься там, используй благовоние.$B$BТы можешь войти в Мертвые копи через старый фермерский дом к югу отсюда. Следуй за бездомными.$B$BС тем, что обнаружишь, возвращайся к Гриану.','ЧТО? У ван Клифа была дочь?','Видение прошлого открылось','Вернитесь к маршалу Гриану Камнегриву на Сторожевой холм в Западном крае.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Видения прошлого',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти благовония погрузят твое тело и разум в состояние глубокой медитации. Как только начнется транс, тебя увлечет в мир духов. Не сопротивляйся трансу, когда он начнет овладевать тобой, $n. Дай духам показать тебе то, что они знают.$B$BТеперь уходи. Иди к Мертвым копям, к месту, которое, как мне говорили, имеет большое значение в истории Западного края. Как окажешься там, используй благовоние.$B$BТы можешь войти в Мертвые копи через старый фермерский дом к югу отсюда. Следуй за бездомными.$B$BС тем, что обнаружишь, возвращайся к Гриану.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','ЧТО? У ван Клифа была дочь?',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Видение прошлого открылось',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к маршалу Гриану Камнегриву на Сторожевой холм в Западном крае.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26321,'Не покормишь – не вырастишь','Похоже, твой детеныш ящера голоден. Если хочешь позаботиться о зверушке, почему б тебе не принести ей какой-нибудь еды? Кнутохвосты частенько нападают на поселение мурлоков из племени Черножабрых, которые обитают неподалеку, к северу отсюда.$B$BУ этого крошки-ящера силенок пока маловато, чтобы самому охотиться, но ему наверняка придется по вкусу свежее мясо мурлока.','Добывайте мурлоков из племени Черножабрых в Северной Тернистой долине и кормите своего ящера-кнутохвоста их мясом, пока он не съест 40 кусочков.','Вернитесь к провозвестнику Мок\'тардину в лагерь Гром\'гол в Северной Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Не покормишь – не вырастишь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Похоже, твой детеныш ящера голоден. Если хочешь позаботиться о зверушке, почему б тебе не принести ей какой-нибудь еды? Кнутохвосты частенько нападают на поселение мурлоков из племени Черножабрых, которые обитают неподалеку, к северу отсюда.$B$BУ этого крошки-ящера силенок пока маловато, чтобы самому охотиться, но ему наверняка придется по вкусу свежее мясо мурлока.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добывайте мурлоков из племени Черножабрых в Северной Тернистой долине и кормите своего ящера-кнутохвоста их мясом, пока он не съест 40 кусочков.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к провозвестнику Мок\'тардину в лагерь Гром\'гол в Северной Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`) VALUES (26322,'Восстание Братства','Я не знал, что у Ван Клифа была дочь, $n. Если этот человек и обладал каким-то особым умением, так это умением хранить тайны.$B$BКакая трагедия. Бедняжка пережила ужасное. Если бы я только знал.$B$BЧто это? Слышишь? Кажется гноллы возвращаются... где стража?$B$BК ОРУЖИЮ, $n!','Станьте свидетелем восстания Братства.','Я немедленно пошлю в Западный Край батальон солдат! Если Братство Справедливости возродилось, то нашему королевству вновь угрожает опасность!','Восстание Братства засвидетельствовано') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Восстание Братства',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я не знал, что у Ван Клифа была дочь, $n. Если этот человек и обладал каким-то особым умением, так это умением хранить тайны.$B$BКакая трагедия. Бедняжка пережила ужасное. Если бы я только знал.$B$BЧто это? Слышишь? Кажется гноллы возвращаются... где стража?$B$BК ОРУЖИЮ, $n!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Станьте свидетелем восстания Братства.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я немедленно пошлю в Западный Край батальон солдат! Если Братство Справедливости возродилось, то нашему королевству вновь угрожает опасность!',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Восстание Братства засвидетельствовано',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26323,'Особенный череп','Ваш ручной ящер нашел себе новую игрушку – череп из лежащей неподалеку горы черепов троллей.$B$BВы не можете понять, чем этот череп отличается от остальных, но животное не хочет его отдавать.$B$BНимбойя из лагеря Гром\'гол должен неплохо разбираться в черепах, судя по хранящейся у него коллекции. Может быть, он знает, что особенного в этом черепе.','Вернитесь к Нимбойе в лагерь Гром\'гол и покажите ему свежий череп детеныша кнутохвоста.','Вернитесь к Нимбойе в лагерь Гром\'гол, что в Северной Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Особенный череп',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ваш ручной ящер нашел себе новую игрушку – череп из лежащей неподалеку горы черепов троллей.$B$BВы не можете понять, чем этот череп отличается от остальных, но животное не хочет его отдавать.$B$BНимбойя из лагеря Гром\'гол должен неплохо разбираться в черепах, судя по хранящейся у него коллекции. Может быть, он знает, что особенного в этом черепе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь к Нимбойе в лагерь Гром\'гол и покажите ему свежий череп детеныша кнутохвоста.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Нимбойе в лагерь Гром\'гол, что в Северной Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26324,'Где мой боевой флот?','Поговорите с полководцем Кроггом в порту Трюмных Вод в Азшаре.','Что, еще одно сообщение от Адского Крика? Он нетерпелив, как ребенок.$B$BТы когда-нибудь раньше имел дело с орками? Постоянно возникают скрытые расходы! Корабли стоят наполовину собранные, о воздушном флоте я даже не говорю.$B$BЕсли это вторжение и правда планируется, мне понадобится твоя помощь.','Поговорите с полководцем Кроггом в порту Трюмных Вод в Азшаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Где мой боевой флот?',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с полководцем Кроггом в порту Трюмных Вод в Азшаре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что, еще одно сообщение от Адского Крика? Он нетерпелив, как ребенок.$B$BТы когда-нибудь раньше имел дело с орками? Постоянно возникают скрытые расходы! Корабли стоят наполовину собранные, о воздушном флоте я даже не говорю.$B$BЕсли это вторжение и правда планируется, мне понадобится твоя помощь.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с полководцем Кроггом в порту Трюмных Вод в Азшаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26325,'Хороший нюх','<Череп заговаривает с вами.>$B$BЯ жив? Да нет... но могу ожить.$B$BТвой ящер умный, нашел среди многих именно мой череп. В жизни я был сильным, могущественным владыкой у троллей. И с твоей помощью снова стану главным.$B$BКровавые Скальпы из Зуулдая хранят магические штуки, которые помогут мне вернуться. Они прячут их в песках. Возьми своего ящеренка, найди эти фетиши, $n... И кинь их в котел.','C помощью детеныша кнутохвоста найдите 8 зуулдайских фетишей.','Вернитесь к бурлящему котлу в лагерь Гром\'гол в Северной Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хороший нюх',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Череп заговаривает с вами.>$B$BЯ жив? Да нет... но могу ожить.$B$BТвой ящер умный, нашел среди многих именно мой череп. В жизни я был сильным, могущественным владыкой у троллей. И с твоей помощью снова стану главным.$B$BКровавые Скальпы из Зуулдая хранят магические штуки, которые помогут мне вернуться. Они прячут их в песках. Возьми своего ящеренка, найди эти фетиши, $n... И кинь их в котел.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','C помощью детеныша кнутохвоста найдите 8 зуулдайских фетишей.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к бурлящему котлу в лагерь Гром\'гол в Северной Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (26326,'Сама земля под нашими ногами','Найдите заклинателя земли Торунскара северо-западнее храма Земли, в Бугристых пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сама земля под нашими ногами',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите заклинателя земли Торунскара северо-западнее храма Земли, в Бугристых пустошах.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26327,'Герой Старая Наковальня','Поговорите с Таргасом Старой Наковальней.','Привет! Если у тебя есть оружие, то я приму любую помощь, только бы избавиться от этих чокнутых идиотов!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Герой Старая Наковальня',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Таргасом Старой Наковальней.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Привет! Если у тебя есть оружие, то я приму любую помощь, только бы избавиться от этих чокнутых идиотов!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26328,'Крепкие отношения','<Норсала наклоняется к земле, пытаясь узнать, где находится Диамант, но, едва прикоснувшись, отскакивает.>$b$bНичего себе! Это неожиданно. Диамант совсем недалеко. Когда я обратилась к нему, он заговорил со мной и рассказал, где мы можем его найти. Отправляйся на северо-восточный край Бугристых пустошей – Диамант будет ждать тебя там.$b$b$n, будь $gосторожен:осторожна;. Не в их духе устраивать засады, но и осады Храма от них тоже никто не ждал.','Найдите Диаманта Терпеливого на северо-восточном краю Бугристых пустошей.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Крепкие отношения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Норсала наклоняется к земле, пытаясь узнать, где находится Диамант, но, едва прикоснувшись, отскакивает.>$b$bНичего себе! Это неожиданно. Диамант совсем недалеко. Когда я обратилась к нему, он заговорил со мной и рассказал, где мы можем его найти. Отправляйся на северо-восточный край Бугристых пустошей – Диамант будет ждать тебя там.$b$b$n, будь $gосторожен:осторожна;. Не в их духе устраивать засады, но и осады Храма от них тоже никто не ждал.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Диаманта Терпеливого на северо-восточном краю Бугристых пустошей.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26329,'Еще одно дело','Ну что ж, пора собирать вещички и приниматься за новую работу. Здесь всегда найдется, что взорвать. Где-то нужно гору передвинуть, где-то овраг пообтесать, и я всегда готов этим заняться.$b$bНе окажешь мне еще одну услугу? Нужно отнести этот отчет главному механику Меггакруту в Новый Город Механиков. Он должен знать, что трогги больше не будут беспокоить его людей.','<Главный механик читает отчет Джессупа.>$b$bВеликолепные новости! Теперь, раз с троггами покончено, мы сможем переключиться на Шестерямстера.','Отнесите отчет Джессупа главному механику Меггакруту в Новый Город Механиков.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Еще одно дело',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну что ж, пора собирать вещички и приниматься за новую работу. Здесь всегда найдется, что взорвать. Где-то нужно гору передвинуть, где-то овраг пообтесать, и я всегда готов этим заняться.$b$bНе окажешь мне еще одну услугу? Нужно отнести этот отчет главному механику Меггакруту в Новый Город Механиков. Он должен знать, что трогги больше не будут беспокоить его людей.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Главный механик читает отчет Джессупа.>$b$bВеликолепные новости! Теперь, раз с троггами покончено, мы сможем переключиться на Шестерямстера.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите отчет Джессупа главному механику Меггакруту в Новый Город Механиков.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26330,'Кто тут большой тролль?','<Череп снова начинает говорить.>$B$BМоя душа готова, но тело – нет. Кровавые Скальпы давно-давно осквернили мое прежнее тело. Какие ужасные вещи они с ним проделывали... мой дух взирал на то, как раздирали мою плоть и... я не в силах продолжать.$B$BИх вождь Ган\'зулах первым участвовал в этих мерзостях. Если мне не изменяет память, это был сильный, могучий тролль... почти как я. Какое интересное совпадение.$B$BТы понимаешь, как нужно поступить, |3-6($r). Так сделай это побыстрее.','Добудьте тело Ган\'зулаха из Зул\'Кунды.','Вернитесь к бурлящему котлу в лагерь Гром\'гол в Северной Тернистой долине.','Он воистину большой тролль.','Ган\'зулах') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кто тут большой тролль?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Череп снова начинает говорить.>$B$BМоя душа готова, но тело – нет. Кровавые Скальпы давно-давно осквернили мое прежнее тело. Какие ужасные вещи они с ним проделывали... мой дух взирал на то, как раздирали мою плоть и... я не в силах продолжать.$B$BИх вождь Ган\'зулах первым участвовал в этих мерзостях. Если мне не изменяет память, это был сильный, могучий тролль... почти как я. Какое интересное совпадение.$B$BТы понимаешь, как нужно поступить, |3-6($r). Так сделай это побыстрее.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте тело Ган\'зулаха из Зул\'Кунды.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к бурлящему котлу в лагерь Гром\'гол в Северной Тернистой долине.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Он воистину большой тролль.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Ган\'зулах',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26331,'Приспешники Шестерямстера','Наш давний враг, Термоштепсель, старается изо всех сил, чтобы помешать нам закончить восстановление Гномрегана. Он выставил против нас одного из самых верных своих приспешников, Разло Шестерямстера, вместе с отрядом облученных гномов.$b$bОни захватили старый арсенал, который находится по дороге на север, и там приспешники Шестерямстера ремонтируют технику. Мы должны остановить их прежде, чем у них получится завести эти механотанки. Отправляйся в арсенал Шестерямстера и убей так много его техников, как только сможешь.','Убейте 8 приспешников Шестерямстера в арсенале Шестерямстера. Вы можете убивать облученных техников или боевых роботов Шестерямстера.','Это должно несколько остудить Шестерямстера. Но мы не можем отдыхать до тех пор, пока он не побежден окончательно, а безопасность Долины Промозглого Ветра не восстановлена.','Вернитесь к главному механику Меггакруту в Новый Город Механиков.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приспешники Шестерямстера',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наш давний враг, Термоштепсель, старается изо всех сил, чтобы помешать нам закончить восстановление Гномрегана. Он выставил против нас одного из самых верных своих приспешников, Разло Шестерямстера, вместе с отрядом облученных гномов.$b$bОни захватили старый арсенал, который находится по дороге на север, и там приспешники Шестерямстера ремонтируют технику. Мы должны остановить их прежде, чем у них получится завести эти механотанки. Отправляйся в арсенал Шестерямстера и убей так много его техников, как только сможешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 приспешников Шестерямстера в арсенале Шестерямстера. Вы можете убивать облученных техников или боевых роботов Шестерямстера.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это должно несколько остудить Шестерямстера. Но мы не можем отдыхать до тех пор, пока он не побежден окончательно, а безопасность Долины Промозглого Ветра не восстановлена.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к главному механику Меггакруту в Новый Город Механиков.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26332,'Зелье Дробителей Черепов','<Череп заговаривает снова.>$B$BТеперь у меня есть тело благодаря тебе, твоему ящеру и Ган\'зулаху. И если мне не изменяет память, вам с приятелем-знахарем понадобится особый настой, чтобы завершить этот ритуал.$B$BКровавые Скальпы хранят свои зелья в Зул\'Кунде, но они довольно слабые. Твое зелье Черного Копья тоже не поможет. Нет... возьми его у троллей Дробителей Черепов, за рекой на востоке.$B$BВозвращайся скорее, |3-6($r). Я буду ждать...','Добудьте 6 зелий Дробителей Черепов у троллей Дробителей Черепов в руинах Зиата\'джай и в руинах Балиа\'ма.','Вернитесь к бурлящему котлу в лагерь Гром\'гол в Северной Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зелье Дробителей Черепов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Череп заговаривает снова.>$B$BТеперь у меня есть тело благодаря тебе, твоему ящеру и Ган\'зулаху. И если мне не изменяет память, вам с приятелем-знахарем понадобится особый настой, чтобы завершить этот ритуал.$B$BКровавые Скальпы хранят свои зелья в Зул\'Кунде, но они довольно слабые. Твое зелье Черного Копья тоже не поможет. Нет... возьми его у троллей Дробителей Черепов, за рекой на востоке.$B$BВозвращайся скорее, |3-6($r). Я буду ждать...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 6 зелий Дробителей Черепов у троллей Дробителей Черепов в руинах Зиата\'джай и в руинах Балиа\'ма.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к бурлящему котлу в лагерь Гром\'гол в Северной Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26333,'Нет танкам!','Воспользуйтесь техно-гранатой, чтобы разрушить 5 отремонтированных механотанков в арсенале Шестерямстера.','Вернитесь к Хинклсу Жарюгану в Новый Город Механиков.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нет танкам!',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь техно-гранатой, чтобы разрушить 5 отремонтированных механотанков в арсенале Шестерямстера.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хинклсу Жарюгану в Новый Город Механиков.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26334,'Мандокир Повелитель Крови','$R. $R, |3-6($r), |3-6($r)... ты же не $gдумал:думала;, что я тебе друг, а, |3-6($r)? Ха-ха-ха!$B$BТы свое дело $gсделал:сделала;. Благодаря тебе я вернулся в царство живых. Поэтому я тебя не убью, а предложу сделку.$B$BОтдай мне ящера.$B$BТы, наверное, уже знаешь, что она не обычный ящер, а мне нужна замена для Оган. Делай, как я говорю. Иначе вы оба – и ты, и знахарь – испытаете на себе силу моего гнева.','Принесите Осколок яйца ящера-кнутохвоста Мандокиру Повелителю Крови в Лагерь Повстанцев.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мандокир Повелитель Крови',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$R. $R, |3-6($r), |3-6($r)... ты же не $gдумал:думала;, что я тебе друг, а, |3-6($r)? Ха-ха-ха!$B$BТы свое дело $gсделал:сделала;. Благодаря тебе я вернулся в царство живых. Поэтому я тебя не убью, а предложу сделку.$B$BОтдай мне ящера.$B$BТы, наверное, уже знаешь, что она не обычный ящер, а мне нужна замена для Оган. Делай, как я говорю. Иначе вы оба – и ты, и знахарь – испытаете на себе силу моего гнева.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Осколок яйца ящера-кнутохвоста Мандокиру Повелителю Крови в Лагерь Повстанцев.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26335,'Готовность военно-морских сил','Адский Крик ждет, когда будет готова армада для вторжения, но в доках на несколько недель отстают от плана. Затраты огромны, а качество работ очень низкое. Проблема в коррупции, $n! И я хочу, чтобы ты ее $gискоренил:искоренила;.$b$b"Крушитель Врагов", военный корабль, стоящий на якоре у северо-западного причала, должен был быть оснащен еще несколько дней назад. Это плохо пахнет. Отправляйся туда и $gсам:сама; проследи за оснасткой.$b$bУзнай, кто задерживает работу, и разберись с ним!','Исследуйте остов "Крушителя Врагов".','<У вас в руках чертежи "Крушителя Врагов".>$B$B<Вы так и эдак вертите документы, пытаясь разобраться во множестве каракулей, заметок и исправлений.>','Исследуйте остов "Крушителя Врагов".') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Готовность военно-морских сил',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Адский Крик ждет, когда будет готова армада для вторжения, но в доках на несколько недель отстают от плана. Затраты огромны, а качество работ очень низкое. Проблема в коррупции, $n! И я хочу, чтобы ты ее $gискоренил:искоренила;.$b$b"Крушитель Врагов", военный корабль, стоящий на якоре у северо-западного причала, должен был быть оснащен еще несколько дней назад. Это плохо пахнет. Отправляйся туда и $gсам:сама; проследи за оснасткой.$b$bУзнай, кто задерживает работу, и разберись с ним!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Исследуйте остов "Крушителя Врагов".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<У вас в руках чертежи "Крушителя Врагов".>$B$B<Вы так и эдак вертите документы, пытаясь разобраться во множестве каракулей, заметок и исправлений.>',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Исследуйте остов "Крушителя Врагов".',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (26336,'Мураш О\'Брин','Ты совершенно $gправ:права;, $n. Не каждый день встречаешь так называемого героя, который разбирается в том, что происходит, оказавшись так далеко от дома, так что я доверю тебе еще кое-какое дело.$b$bУ меня есть друг по имени Мураш О\'Брин. Он предводитель команды Пиратов Черноводья. Они славные ребята, настоящие пираты. Их судно стоит в бухте Фальдира, в укрытии у южного берега.$b$bУверен, у О\'Брина найдется для тебя прибыльная работенка, если ты в этом $gзаинтересован:заинтересована;.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мураш О\'Брин',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты совершенно $gправ:права;, $n. Не каждый день встречаешь так называемого героя, который разбирается в том, что происходит, оказавшись так далеко от дома, так что я доверю тебе еще кое-какое дело.$b$bУ меня есть друг по имени Мураш О\'Брин. Он предводитель команды Пиратов Черноводья. Они славные ребята, настоящие пираты. Их судно стоит в бухте Фальдира, в укрытии у южного берега.$b$bУверен, у О\'Брина найдется для тебя прибыльная работенка, если ты в этом $gзаинтересован:заинтересована;.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26337,'Снижение издержек','<Понять, почему задерживается оснастка "Крушителя Врагов", несложно. Изо дня в день штейгер вносит изменения в чертежи.>$b$b<Особенно пугающими выглядят недавние правки. Рабочим приказали снять заклепки, чтобы снизить издержки!>$b$b<Стоит разыскать одного из мастеров "Крушителя Врагов" и разобраться с ним, пока никто из Орды не пострадал.>','То есть они пытались снизить производственные затраты? Недопустимо!$B$BЯ рад, что ты вбил в их головы немного здравого смысла. Если этот мастер сдержит слово, наш флот будет полностью готов в срок.','Вернитесь к полководцу Кроггу в Гавань Трюмных Вод в Азшаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Снижение издержек',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Понять, почему задерживается оснастка "Крушителя Врагов", несложно. Изо дня в день штейгер вносит изменения в чертежи.>$b$b<Особенно пугающими выглядят недавние правки. Рабочим приказали снять заклепки, чтобы снизить издержки!>$b$b<Стоит разыскать одного из мастеров "Крушителя Врагов" и разобраться с ним, пока никто из Орды не пострадал.>',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','То есть они пытались снизить производственные затраты? Недопустимо!$B$BЯ рад, что ты вбил в их головы немного здравого смысла. Если этот мастер сдержит слово, наш флот будет полностью готов в срок.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к полководцу Кроггу в Гавань Трюмных Вод в Азшаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26338,'"Кон-тролль" популяции','Насколько понимаю, ты скоро отправляешься в Зул\'Кунду. Но пока ты здесь, у меня для тебя небольшое задание.$B$BВ Тернистой долине развелось слишком много троллей. Западные земли заняло племя Кровавого Скальпа, восточные – Дробители Черепов. Они перебираются из своих руин в джунгли и нарушают равновесие здешней природы. Пора нам его восстановить.$B$BЗул\'Кунда – столица Кровавого Скальпа. Там живут все высокопоставленные члены племени. Убей нескольких, а потом возвращайся ко мне.','Убейте 7 мистиков, 7 охотников, 7 разведчиков и 1 повелителя зверей из племени Кровавого Скальпа.','Вернитесь к провозвестнику Мок\'тардину в лагерь Гром\'гол в Северной Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','"Кон-тролль" популяции',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Насколько понимаю, ты скоро отправляешься в Зул\'Кунду. Но пока ты здесь, у меня для тебя небольшое задание.$B$BВ Тернистой долине развелось слишком много троллей. Западные земли заняло племя Кровавого Скальпа, восточные – Дробители Черепов. Они перебираются из своих руин в джунгли и нарушают равновесие здешней природы. Пора нам его восстановить.$B$BЗул\'Кунда – столица Кровавого Скальпа. Там живут все высокопоставленные члены племени. Убей нескольких, а потом возвращайся ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 7 мистиков, 7 охотников, 7 разведчиков и 1 повелителя зверей из племени Кровавого Скальпа.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к провозвестнику Мок\'тардину в лагерь Гром\'гол в Северной Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26339,'Сбор в Поселке Пивоваров','Пока мы вместе с главным механиком Меггакрутом и его военными советниками заканчиваем планирование нападения на Разло Шестерямстера, я отправила своего помощника в Поселок Пивоваров, чтобы начать приготовления.$b$bЧтобы добраться до Поселка Пивоваров, иди по дороге, выходящей из города на юго-восток. Когда прибудешь, найди Ярви Шаг Сквозь Тень и узнай, не нужна ли ему помощь. Наши братья-дворфы выделили группу горных пехотинцев Стальгорна, которые присоединятся к нам для битвы с Шестерямстером.','Поговорите с Ярви Шагом Сквозь Тень в Поселке Пивоваров.','Ах, да, Келси говорила, что ты придешь. Здесь еще многое нужно сделать, прежде чем мы сможем атаковать Шестерямстера.','Поговорите с Ярви Шагом Сквозь Тень в Поселке Пивоваров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сбор в Поселке Пивоваров',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пока мы вместе с главным механиком Меггакрутом и его военными советниками заканчиваем планирование нападения на Разло Шестерямстера, я отправила своего помощника в Поселок Пивоваров, чтобы начать приготовления.$b$bЧтобы добраться до Поселка Пивоваров, иди по дороге, выходящей из города на юго-восток. Когда прибудешь, найди Ярви Шаг Сквозь Тень и узнай, не нужна ли ему помощь. Наши братья-дворфы выделили группу горных пехотинцев Стальгорна, которые присоединятся к нам для битвы с Шестерямстером.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Ярви Шагом Сквозь Тень в Поселке Пивоваров.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ах, да, Келси говорила, что ты придешь. Здесь еще многое нужно сделать, прежде чем мы сможем атаковать Шестерямстера.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Ярви Шагом Сквозь Тень в Поселке Пивоваров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26340,'Охота','Из всех мест Азерота я застрял именно в Гром\'голе. Здесь полно диких зверей, грабителей караванов, всегда могут напасть тролли – удивляюсь, как я вообще еще жив!$B$BХотя могло быть и хуже. По крайней мере, в Гром\'голе есть стены и стражники. А вот несколько охотников разбили лагерь к северу отсюда – прямо посреди джунглей!$B$BТуда все время кто-то ходит. Так что если ты ищешь себе приключений, туда тоже наведайся. А я, пожалуй, останусь в Гром\'голе.','Поговорите с Барнилом Каменным Горшком в лагере экспедиции Эрнестуэя, что в Северной Тернистой долине.','Хм... Я Барнил. А ты кто?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Из всех мест Азерота я застрял именно в Гром\'голе. Здесь полно диких зверей, грабителей караванов, всегда могут напасть тролли – удивляюсь, как я вообще еще жив!$B$BХотя могло быть и хуже. По крайней мере, в Гром\'голе есть стены и стражники. А вот несколько охотников разбили лагерь к северу отсюда – прямо посреди джунглей!$B$BТуда все время кто-то ходит. Так что если ты ищешь себе приключений, туда тоже наведайся. А я, пожалуй, останусь в Гром\'голе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Барнилом Каменным Горшком в лагере экспедиции Эрнестуэя, что в Северной Тернистой долине.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хм... Я Барнил. А ты кто?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26342,'Закрасить черным','У нас есть проверенная информация о том, что этот Разло Шестерямстер занял оборонительную позицию на острове посреди Заледеневшего озера. Хуже того, он окружил себя сетью из караульных роботов, которые засекут любого атакующего.$b$bЕсли мы хотим победить Шестерямстера, нужно вывести из строя этих караульных роботов. Это устройство стреляет черной липкой краской, которая залепит оптические сенсоры караульных роботов Шестерямстера. Воспользуйся им, чтобы уничтожить его систему заблаговременных оповещений.','Воспользуйтесь краскометом, чтобы ослепить 5 караульных роботов Шестерямстера.','Благодаря тебе в обороне Шестерямстера появилась брешь, и мы сможем напасть на него. Очень хорошо, $n.','Вернитесь к Ярви Шагу Сквозь Тень в Поселок Пивоваров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Закрасить черным',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У нас есть проверенная информация о том, что этот Разло Шестерямстер занял оборонительную позицию на острове посреди Заледеневшего озера. Хуже того, он окружил себя сетью из караульных роботов, которые засекут любого атакующего.$b$bЕсли мы хотим победить Шестерямстера, нужно вывести из строя этих караульных роботов. Это устройство стреляет черной липкой краской, которая залепит оптические сенсоры караульных роботов Шестерямстера. Воспользуйся им, чтобы уничтожить его систему заблаговременных оповещений.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь краскометом, чтобы ослепить 5 караульных роботов Шестерямстера.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Благодаря тебе в обороне Шестерямстера появилась брешь, и мы сможем напасть на него. Очень хорошо, $n.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ярви Шагу Сквозь Тень в Поселок Пивоваров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26343,'Спрос и предложение','"Лучший мастер-кожевник Южных морей, а также Старого и Нового света." Вот как меня называют. Меня! Дриззлика! Лучший мастер-коже... Гм... Ну, в общем, понятно.$B$BМои изделия повсеместно славятся как самые лучшие – для тех, кто знает толк в хороших вещах!$B$BЯ только что получил заказ от директора Ридлвокса из Союза ремонтников на дюжину пар его любимых сапог. "Эксельзиор"! Наша самая ходовая модель.$B$BВ связи с этим мне нужны шкуры кроколисков. Кроколиски водятся у реки в Северной Тернистой долине.','Принесите 2 больших шкуры речного кроколиска Дриззлику в лагерь экспедиции Эрнестуэя.','Да, нормальные шкуры. В общем, их вид не так важен – все равно пойдут на подкладку. Тем не менее – качество прежде всего! Качество и удобство!$B$BЕсли же окажутся жестковаты, размягчим тигриной кровью. Ну, ты ж понимаешь... маленькие профессиональные хитрости есть у каждого мастера!','У меня все готово к работе, $n, не хватает лишь этих шкур. Нельзя заставлять ждать самого Ридлвокса!$B$BМы же не хотим рассердить главного изобретателя Союза ремонтников!','Вернитесь к Дриззлику в лагерь экспедиции Эрнестуэя в Северной Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спрос и предложение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','"Лучший мастер-кожевник Южных морей, а также Старого и Нового света." Вот как меня называют. Меня! Дриззлика! Лучший мастер-коже... Гм... Ну, в общем, понятно.$B$BМои изделия повсеместно славятся как самые лучшие – для тех, кто знает толк в хороших вещах!$B$BЯ только что получил заказ от директора Ридлвокса из Союза ремонтников на дюжину пар его любимых сапог. "Эксельзиор"! Наша самая ходовая модель.$B$BВ связи с этим мне нужны шкуры кроколисков. Кроколиски водятся у реки в Северной Тернистой долине.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 2 больших шкуры речного кроколиска Дриззлику в лагерь экспедиции Эрнестуэя.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, нормальные шкуры. В общем, их вид не так важен – все равно пойдут на подкладку. Тем не менее – качество прежде всего! Качество и удобство!$B$BЕсли же окажутся жестковаты, размягчим тигриной кровью. Ну, ты ж понимаешь... маленькие профессиональные хитрости есть у каждого мастера!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У меня все готово к работе, $n, не хватает лишь этих шкур. Нельзя заставлять ждать самого Ридлвокса!$B$BМы же не хотим рассердить главного изобретателя Союза ремонтников!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дриззлику в лагерь экспедиции Эрнестуэя в Северной Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26344,'Немного разнообразия не помешает','Ну ладно, в целом, сапоги почти готовы, и пока все идет хорошо. Но вот незадача: ты $gпринес:принесла; мало шкур – их на подкладку не хватит.$B$B"И что же нам делать, Дриззлик?" Наверняка этот вопрос уже вертится у тебя на языке. Но тебе повезло. Потому что ты говоришь с Дриззликом, и он знает, что делать!$B$BПодкладка, она не видна снаружи, и на нее можно взять кожу потолще и подешевле. Например, шкуры кроколисков с озера Назферити вполне подойдут. И разницы никто не заметит.','Принесите 5 шкур кроколисков-хрустогрызов Дриззлику в лагерь экспедиции Эрнестуэя.','Вернитесь к Дриззлику в лагерь экспедиции Эрнестуэя в Северной Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Немного разнообразия не помешает',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну ладно, в целом, сапоги почти готовы, и пока все идет хорошо. Но вот незадача: ты $gпринес:принесла; мало шкур – их на подкладку не хватит.$B$B"И что же нам делать, Дриззлик?" Наверняка этот вопрос уже вертится у тебя на языке. Но тебе повезло. Потому что ты говоришь с Дриззликом, и он знает, что делать!$B$BПодкладка, она не видна снаружи, и на нее можно взять кожу потолще и подешевле. Например, шкуры кроколисков с озера Назферити вполне подойдут. И разницы никто не заметит.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 5 шкур кроколисков-хрустогрызов Дриззлику в лагерь экспедиции Эрнестуэя.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дриззлику в лагерь экспедиции Эрнестуэя в Северной Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) VALUES (26344,'Сапоги "Эксцельсиор" от Дриззлика! Лучшая кожа соленоводных кроколисков, максимально удобная модель, стопроцентное качество. Во всем мире не сыщешь лучших сапог!$B$BНу и, конечно же, маленькие секреты мастерства.$B$BЭто к вопросу о нужных мне шкурах, как ты понимаешь.') ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Сапоги "Эксцельсиор" от Дриззлика! Лучшая кожа соленоводных кроколисков, максимально удобная модель, стопроцентное качество. Во всем мире не сыщешь лучших сапог!$B$BНу и, конечно же, маленькие секреты мастерства.$B$BЭто к вопросу о нужных мне шкурах, как ты понимаешь.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26345,'Эксельзиор','Принесите Дриззлику шкуру старого кроколиска в лагерь экспедиции Эрнестуэя.','Отлично! Благодаря тебе я закончу этот заказ и отправлю его со следующей лодкой директору Ридлвоксу в Нижнюю Шахту. Причем раньше срока!$B$BЯ специально для тебя сшил еще одну пару. За счет Дриззлика.$B$BПомни: лучше сапог, чем у Дриззлика, не найдешь, хоть весь белый свет обойди!','Вернитесь к Дриззлику в лагерь экспедиции Эрнестуэя в Северной Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Эксельзиор',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Дриззлику шкуру старого кроколиска в лагерь экспедиции Эрнестуэя.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! Благодаря тебе я закончу этот заказ и отправлю его со следующей лодкой директору Ридлвоксу в Нижнюю Шахту. Причем раньше срока!$B$BЯ специально для тебя сшил еще одну пару. За счет Дриззлика.$B$BПомни: лучше сапог, чем у Дриззлика, не найдешь, хоть весь белый свет обойди!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дриззлику в лагерь экспедиции Эрнестуэя в Северной Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (26346,'История Мизраэль','Когда камень затихает, вы уходите со смутным ощущением тревоги. Что-то не так.$b$bВозможно, о том, что вы уже сделали, следует рассказать Скуэрто.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','История Мизраэль',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда камень затихает, вы уходите со смутным ощущением тревоги. Что-то не так.$b$bВозможно, о том, что вы уже сделали, следует рассказать Скуэрто.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26347,'Хранитель огня','Ночь, когда погибла семья смотрителя маяка, была ужасной. Я беспомощно наблюдал за происходившим, поскольку сам Старый Мрачноглаз вел нападавших. Но что случилось, то случилось, и теперь жизнь моряков, плавающих по Великому морю и близко подходящих к опасным прибрежным рифам, – моя забота. Поддерживать огонь маяка оказалось некому, и эта обязанность легла на мои плечи.$B$BПомоги мне поддерживать огонь – принеси мне слизи из Бушующей пропасти на северо-востоке отсюда.','Принесите 5 образцов слизи из Бушующей пропасти капитану Грейсону на маяк Западного края.','Вернитесь к капитану Грейсону на маяк в Западном крае.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хранитель огня',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ночь, когда погибла семья смотрителя маяка, была ужасной. Я беспомощно наблюдал за происходившим, поскольку сам Старый Мрачноглаз вел нападавших. Но что случилось, то случилось, и теперь жизнь моряков, плавающих по Великому морю и близко подходящих к опасным прибрежным рифам, – моя забота. Поддерживать огонь маяка оказалось некому, и эта обязанность легла на мои плечи.$B$BПомоги мне поддерживать огонь – принеси мне слизи из Бушующей пропасти на северо-востоке отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 5 образцов слизи из Бушующей пропасти капитану Грейсону на маяк Западного края.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Грейсону на маяк в Западном крае.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26348,'Борьба за чистоту берегов','Вероятно, ты $gвидел:видела; эти обломки кораблей на берегу. Великое море коварно. Берег Западного края необходимо расчистить, чтобы моряки находили путь к нашим берегам безопасно. Но мурлоки не дают нам покоя.$B$BПеребей мурлоков-волноловов и оракулов, и я позабочусь о твоей награде.','Убейте 7 мурлоков-волноловов и 7 мурлоков-оракулов.','Вернитесь к капитану Грейсону на маяк в Западном крае.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Борьба за чистоту берегов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вероятно, ты $gвидел:видела; эти обломки кораблей на берегу. Великое море коварно. Берег Западного края необходимо расчистить, чтобы моряки находили путь к нашим берегам безопасно. Но мурлоки не дают нам покоя.$B$BПеребей мурлоков-волноловов и оракулов, и я позабочусь о твоей награде.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 7 мурлоков-волноловов и 7 мурлоков-оракулов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Грейсону на маяк в Западном крае.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26349,'Опасность на побережье','Когда моя жизнь закончилась на этих скалах, я понятия не имел, что мне сулит посмертие. В ту ночь маяк не горел, потому, что Старый Мрачноглаз запугал до смерти семью смотрителя. Они вернулись и зажгли пламя, но Старый Мрачноглаз заставил более слабовольных мурлоков напасть на маяк вместе с ним еще раз. Во второй раз семье не так повезло, и они погибли у меня на глазах.$B$BУбей Старого Мрачноглаза, если найдешь его на берегу, принеси мне одну из его чешуек, и я награжу тебя.','Принесите чешуйку Старого Мрачноглаза капитану Грейсону на маяк Западного края.','Вернитесь к капитану Грейсону на маяк в Западном крае.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Опасность на побережье',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда моя жизнь закончилась на этих скалах, я понятия не имел, что мне сулит посмертие. В ту ночь маяк не горел, потому, что Старый Мрачноглаз запугал до смерти семью смотрителя. Они вернулись и зажгли пламя, но Старый Мрачноглаз заставил более слабовольных мурлоков напасть на маяк вместе с ним еще раз. Во второй раз семье не так повезло, и они погибли у меня на глазах.$B$BУбей Старого Мрачноглаза, если найдешь его на берегу, принеси мне одну из его чешуек, и я награжу тебя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите чешуйку Старого Мрачноглаза капитану Грейсону на маяк Западного края.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Грейсону на маяк в Западном крае.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26350,'Жрица Ху\'рала','Спасибо, $n. Знаю, ты не $gобязан был:обязана была; меня спасать и... В общем, большое спасибо.$B$BВозвращение Мандокира Повелителя Крови – очень дурная новость. Несколько лет назад его убили в Зул\'Гурубе, и мы тогда решили, что больше не увидим ни его, ни ему подобных. Но тролли в Зул\'Гурубе не оставляли попыток провести свой чудовищный ритуал. И если они все же смогли вернуть Мандокира к жизни, то, скорее всего, они воскресили и других.$B$BТролли в Бамбале, что к востоку отсюда, могут знать больше. Поговори с их жрицей.','Найдите жрицу Ху\'ралу в Бамбале в Северной Тернистой долине и поговорите с ней.','Да, Мандокир жив.$B$BДа, это твоя вина.$B$BДа, ты все еще сможешь его остановить.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жрица Ху\'рала',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Спасибо, $n. Знаю, ты не $gобязан был:обязана была; меня спасать и... В общем, большое спасибо.$B$BВозвращение Мандокира Повелителя Крови – очень дурная новость. Несколько лет назад его убили в Зул\'Гурубе, и мы тогда решили, что больше не увидим ни его, ни ему подобных. Но тролли в Зул\'Гурубе не оставляли попыток провести свой чудовищный ритуал. И если они все же смогли вернуть Мандокира к жизни, то, скорее всего, они воскресили и других.$B$BТролли в Бамбале, что к востоку отсюда, могут знать больше. Поговори с их жрицей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите жрицу Ху\'ралу в Бамбале в Северной Тернистой долине и поговорите с ней.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, Мандокир жив.$B$BДа, это твоя вина.$B$BДа, ты все еще сможешь его остановить.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26351,'Внутреннее зрение','Чтобы узнать Мандокира, нужно увидеть Мандокира.$B$BЧтобы увидеть Мандокира, нужны глаза ящера.$B$BМежду тобой и ящером Оган\'ака, дочерью Оган, установилась связь.$B$BЧтобы укрепить ее, нужны перья.$B$BИди на запад, найдешь перья там, да.','Ящер по имени Оган\'ака все еще твой друг.','Вернитесь к жрице Ху\'рале в Бамбалу, что в Северной Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Внутреннее зрение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чтобы узнать Мандокира, нужно увидеть Мандокира.$B$BЧтобы увидеть Мандокира, нужны глаза ящера.$B$BМежду тобой и ящером Оган\'ака, дочерью Оган, установилась связь.$B$BЧтобы укрепить ее, нужны перья.$B$BИди на запад, найдешь перья там, да.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ящер по имени Оган\'ака все еще твой друг.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к жрице Ху\'рале в Бамбалу, что в Северной Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26352,'План Коззла','Возьмите ключ штейгера Коззла, а затем заберите чертежи топливного регулятора.','Вернитесь к Кил\'Карилу в Бамбалу, что в Северной Тернистой долине.','Штейгер Коззл прячется на вершине своей буровой вышки. У него есть ключ, что вам нужен.','Штейгер Коззл') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','План Коззла',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возьмите ключ штейгера Коззла, а затем заберите чертежи топливного регулятора.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кил\'Карилу в Бамбалу, что в Северной Тернистой долине.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Штейгер Коззл прячется на вершине своей буровой вышки. У него есть ключ, что вам нужен.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Штейгер Коззл',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26353,'Спрятанное сокровище капитана Сандерса','Найдите сундучок капитана Сандерса и исследуйте его в поисках следующей подсказки.','Сундучок медленно, со скрипом, открывается. Кажется, ничего в нем нет, кроме песка и воды. Постойте-ка! Проворно выползает маленький крабик, а в клешнях у него – следующая подсказка!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спрятанное сокровище капитана Сандерса',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите сундучок капитана Сандерса и исследуйте его в поисках следующей подсказки.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сундучок медленно, со скрипом, открывается. Кажется, ничего в нем нет, кроме песка и воды. Постойте-ка! Проворно выползает маленький крабик, а в клешнях у него – следующая подсказка!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (26354,'Спрятанное сокровище капитана Сандерса','Записка гласит: "Очень хорошо, дружище! А теперь иди строго на восток. Обойди с востока утесы. Поищи разрушенную старую трубу на обочине. Там будет старый бочонок со следующей подсказкой".','Найдите старый бочонок рядом с разрушенной трубой и исследуйте его в поисках следующей подсказки.','Очень хорошо, охотник за сокровищами!','Это, похоже, правильный бочонок.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спрятанное сокровище капитана Сандерса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Записка гласит: "Очень хорошо, дружище! А теперь иди строго на восток. Обойди с востока утесы. Поищи разрушенную старую трубу на обочине. Там будет старый бочонок со следующей подсказкой".',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите старый бочонок рядом с разрушенной трубой и исследуйте его в поисках следующей подсказки.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Очень хорошо, охотник за сокровищами!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Это, похоже, правильный бочонок.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (26355,'Спрятанное сокровище капитана Сандерса','В бочонке вы находите клочок пергамента. На нем написано: "А отсюда иди на север. Иди прямо и прямо, никуда не сворачивай, пока не увидишь пустой кувшин рядом с одинокой мельницей на прибрежных скалах. Пошаришь там – может, и найдешь то, что ищешь".','Обыщите пустой кувшин рядом с мельницей в поисках следующей подсказки.','Сокровища ждут тебя, охотник за сокровищами!','Из пустого кувшина выглядывает подсказка.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спрятанное сокровище капитана Сандерса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В бочонке вы находите клочок пергамента. На нем написано: "А отсюда иди на север. Иди прямо и прямо, никуда не сворачивай, пока не увидишь пустой кувшин рядом с одинокой мельницей на прибрежных скалах. Пошаришь там – может, и найдешь то, что ищешь".',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обыщите пустой кувшин рядом с мельницей в поисках следующей подсказки.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сокровища ждут тебя, охотник за сокровищами!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Из пустого кувшина выглядывает подсказка.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (26356,'Спрятанное сокровище капитана Сандерса','Конечно же, глубоко внутри старого кувшина лежит еще одна подсказка к поиску сокровища Сандерса. Чернила кое-где расплылись, а бумага отдает виски, но кое-что вам удалось разобрать: "Раз уж ты нашел мой старый кувшин из-под виски, значит, ты близко подобрался к сокровищу! Иди от бутылки на запад и спустись к берегу. Доберешься до воды – не останавливайся! Плыви, пока не найдешь остров, где и находится мой сундук с сокровищем!"','Найдите сундук капитана Сандерса и откройте его, чтобы получить свою награду.','Петли на крышке старого сундука заржавели, но поддаются. Вы с усилием открываете сундук и забираете сокровище.$B$BПоздравляем!','Сокровища капитана Сандерса ждут!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спрятанное сокровище капитана Сандерса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Конечно же, глубоко внутри старого кувшина лежит еще одна подсказка к поиску сокровища Сандерса. Чернила кое-где расплылись, а бумага отдает виски, но кое-что вам удалось разобрать: "Раз уж ты нашел мой старый кувшин из-под виски, значит, ты близко подобрался к сокровищу! Иди от бутылки на запад и спустись к берегу. Доберешься до воды – не останавливайся! Плыви, пока не найдешь остров, где и находится мой сундук с сокровищем!"',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите сундук капитана Сандерса и откройте его, чтобы получить свою награду.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Петли на крышке старого сундука заржавели, но поддаются. Вы с усилием открываете сундук и забираете сокровище.$B$BПоздравляем!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Сокровища капитана Сандерса ждут!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26357,'Лики зла','Клан Порочной Ветви развесил маски тики по стенам крепости Джинта\'Алор. Но эти рожи недолго будут приглядывать за ними!$B$BВозьми факел, |3-6($c). Подожги маски, а я полюбуюсь, как сгорают их стражи и заклятья, а вместе с дымом растворяется черная магия вуду.','Используйте факел тики, чтобы поджечь 8 ритуальных масок тики в Джинта\'Алоре.','Приятно видеть, как сгорают надежды врагов…','Вернитесь к Котонге в Джинта\'Алор, что во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лики зла',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Клан Порочной Ветви развесил маски тики по стенам крепости Джинта\'Алор. Но эти рожи недолго будут приглядывать за ними!$B$BВозьми факел, |3-6($c). Подожги маски, а я полюбуюсь, как сгорают их стражи и заклятья, а вместе с дымом растворяется черная магия вуду.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте факел тики, чтобы поджечь 8 ритуальных масок тики в Джинта\'Алоре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Приятно видеть, как сгорают надежды врагов…',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Котонге в Джинта\'Алор, что во Внутренних землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (26358,'Готовность воздушных сил','Я лично гарантировал Адскому Крику, что на этой неделе его воздушный флот будет готов. Но на флагмане, "Копье Дуротара", до сих пор не установлены основные двигатели.$b$bФлип обещала новенькие блестящие двигатели еще на прошлой неделе. Отправляйся на ее свалку механизмов за банком и узнай, в чем причина задержки.$b$bВоздушный флот не ждет, $n!','<Флип утирает лицо, оставляя на щеке огромное пятно смазки.>$B$BЧто? ЧТО сказал капитан?$B$B<Она угрожающе встряхивает своим трубным ключом.>$B$BЭто ОН виноват в том, что этот монстр инженерной мысли все еще не готов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Готовность воздушных сил',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я лично гарантировал Адскому Крику, что на этой неделе его воздушный флот будет готов. Но на флагмане, "Копье Дуротара", до сих пор не установлены основные двигатели.$b$bФлип обещала новенькие блестящие двигатели еще на прошлой неделе. Отправляйся на ее свалку механизмов за банком и узнай, в чем причина задержки.$b$bВоздушный флот не ждет, $n!',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Флип утирает лицо, оставляя на щеке огромное пятно смазки.>$B$BЧто? ЧТО сказал капитан?$B$B<Она угрожающе встряхивает своим трубным ключом.>$B$BЭто ОН виноват в том, что этот монстр инженерной мысли все еще не готов.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26359,'Увидеть ящера','У тебя есть перья, да.$B$BУ нас есть |3-6($c), да.$B$BПоговори со жрицей, когда будешь $gготов:готова;.','Поговорите со жрицей Ху\'ралой в Бамбале, что в Северной Тернистой долине, чтобы поучаствовать в ритуале внутреннего зрения.','Вернитесь к жрице Ху\'рале в Бамбалу, что в Северной Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Увидеть ящера',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У тебя есть перья, да.$B$BУ нас есть |3-6($c), да.$B$BПоговори со жрицей, когда будешь $gготов:готова;.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите со жрицей Ху\'ралой в Бамбале, что в Северной Тернистой долине, чтобы поучаствовать в ритуале внутреннего зрения.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к жрице Ху\'рале в Бамбалу, что в Северной Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26360,'Контроль над разумом','Внутреннего зрения мало, да.$B$BКонтроль над разумом – эта магия мощнее, да.$B$BА для сильной магии нужны сильные реагенты. Например, мозг тролля – очень сильный реагент.$B$BБрэддок в Зул\'Мамве, он очень умный, да.$B$BИди на юг, найди Брэддока и вышиби из него большой мозг.','Добудьте большой мозг Брэддока, убив последнего в Зул\'Мамве.','Вернитесь к жрице Ху\'рале в Бамбалу, что в Северной Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Контроль над разумом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Внутреннего зрения мало, да.$B$BКонтроль над разумом – эта магия мощнее, да.$B$BА для сильной магии нужны сильные реагенты. Например, мозг тролля – очень сильный реагент.$B$BБрэддок в Зул\'Мамве, он очень умный, да.$B$BИди на юг, найди Брэддока и вышиби из него большой мозг.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте большой мозг Брэддока, убив последнего в Зул\'Мамве.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к жрице Ху\'рале в Бамбалу, что в Северной Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26361,'Самофланж Смута','Прекрасно! Через час у меня будет самофланжированный двигатель.','Смут – отличный инженер.$B$BСамофланж убивает с тридцати метров, если не выравнивать редукционные калифракты.','Отнесите индукционный самофланж Флип в Гавань Трюмных Вод в Азшаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Самофланж Смута',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно! Через час у меня будет самофланжированный двигатель.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Смут – отличный инженер.$B$BСамофланж убивает с тридцати метров, если не выравнивать редукционные калифракты.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите индукционный самофланж Флип в Гавань Трюмных Вод в Азшаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`) VALUES (26362,'Стать ящером','Контроль над разумом. Очень мощный, да.$B$BЕсли повезет, с твоей помощью Оган\'ака сбежит из Зул\'Гуруба.$B$BА потом Оган\'ака опять станет $n\'ака!$B$BПоговори со жрицей, да. И помоги $n\'ака сбежать.','Поговорите со жрицей Ху\'ралой, а потом помогите пойманному детенышу кнутохвоста сбежать из Зул\'Гуруба.','Вернитесь к жрице Ху\'рале в Бамбалу, что в Северной Тернистой долине.','В ловушке в Зул\'Гурубе','Оган\'ака','Вернулся из мертвых?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Стать ящером',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Контроль над разумом. Очень мощный, да.$B$BЕсли повезет, с твоей помощью Оган\'ака сбежит из Зул\'Гуруба.$B$BА потом Оган\'ака опять станет $n\'ака!$B$BПоговори со жрицей, да. И помоги $n\'ака сбежать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите со жрицей Ху\'ралой, а потом помогите пойманному детенышу кнутохвоста сбежать из Зул\'Гуруба.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к жрице Ху\'рале в Бамбалу, что в Северной Тернистой долине.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','В ловушке в Зул\'Гурубе',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Оган\'ака',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Вернулся из мертвых?',`questturntextwindow_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26363,'Судьбоносная вершина','Ты хорошо $gпостарался:постаралась;, сражаясь с их воинами, $n. Теперь я хочу, чтобы ты $gобследовал:обследовала; вершину Джинта\'Алора.$B$BМы подготовились к самой страшной битве, собирались снести их темный алтарь, но что-то там подозрительно тихо, ни звука не слыхать. Они могли устроить нам ловушку, поэтому вместо того, чтобы лезть туда всем сразу, я предпочту отправить кого-то одного, достаточно сильного.$B$BА если ловушки там нет... Что ж, тогда мне очень любопытно было бы узнать, что там у них стряслось. Принеси мне все улики, которые сможешь там найти.','Соберите 8 идолов-пауков, убивая троллей племени Порочной Ветви на вершине Джинта\'Алора.','Умерли? И все вокруг алтаря? И на них были вот эти идолы-пауки?$B$BЭто было коллективное самопожертвование. Они отдали свои жизни Шадре.','Что тебе удалось найти?','Вернитесь к Старейшине Сломанному Клыку в Джинта\'Алор, что во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Судьбоносная вершина',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты хорошо $gпостарался:постаралась;, сражаясь с их воинами, $n. Теперь я хочу, чтобы ты $gобследовал:обследовала; вершину Джинта\'Алора.$B$BМы подготовились к самой страшной битве, собирались снести их темный алтарь, но что-то там подозрительно тихо, ни звука не слыхать. Они могли устроить нам ловушку, поэтому вместо того, чтобы лезть туда всем сразу, я предпочту отправить кого-то одного, достаточно сильного.$B$BА если ловушки там нет... Что ж, тогда мне очень любопытно было бы узнать, что там у них стряслось. Принеси мне все улики, которые сможешь там найти.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 идолов-пауков, убивая троллей племени Порочной Ветви на вершине Джинта\'Алора.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Умерли? И все вокруг алтаря? И на них были вот эти идолы-пауки?$B$BЭто было коллективное самопожертвование. Они отдали свои жизни Шадре.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что тебе удалось найти?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Старейшине Сломанному Клыку в Джинта\'Алор, что во Внутренних землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26364,'Долой Шестерямстера!','Наши друзья, дворфы Стальгорна, согласились помочь нам в битве против Разло Шестерямстера. Горный пехотинец Камнемол – это опытный боец, который хорошо знает Дун Морог. Он и главный механик Меггакрут находятся в полной готовности на небольшом покрытом снегом островке Заледеневшего озера, что к северу отсюда. Встреться там с ними и дай знать главному механику, когда будешь $gготов:готова; выступить против предателя Шестерямстера.$b$bВозьми это орбитальное прицельное устройство и используй его во время боя. Это поможет главному механику применить его спецоружие.','Победите Разло Шестерямстера. Когда будете готовы начать битву, поговорите с главным механиком Меггакрутом на Заледеневшем озере.','Мы наконец избавились от Разло Шестерямстера и его козней! После нашей победы над Шестерямстером и его людьми, Термоштепсель не позволит себе прислать на поверхность других своих приспешников. Не могу дождаться того дня, когда мы одержим над ним окончательную победу!','Вернитесь к Ярви Шагу Сквозь Тень в Поселок Пивоваров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Долой Шестерямстера!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наши друзья, дворфы Стальгорна, согласились помочь нам в битве против Разло Шестерямстера. Горный пехотинец Камнемол – это опытный боец, который хорошо знает Дун Морог. Он и главный механик Меггакрут находятся в полной готовности на небольшом покрытом снегом островке Заледеневшего озера, что к северу отсюда. Встреться там с ними и дай знать главному механику, когда будешь $gготов:готова; выступить против предателя Шестерямстера.$b$bВозьми это орбитальное прицельное устройство и используй его во время боя. Это поможет главному механику применить его спецоружие.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Разло Шестерямстера. Когда будете готовы начать битву, поговорите с главным механиком Меггакрутом на Заледеневшем озере.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мы наконец избавились от Разло Шестерямстера и его козней! После нашей победы над Шестерямстером и его людьми, Термоштепсель не позволит себе прислать на поверхность других своих приспешников. Не могу дождаться того дня, когда мы одержим над ним окончательную победу!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ярви Шагу Сквозь Тень в Поселок Пивоваров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26365,'Воззвание к героям: Красногорье!','Здесь, конечно, дела идут ужасно, но в других частях этих земель начались сильные землетрясения из-за смещения земных пластов.$B$BМне тут пришел отчет от капитана стражи Паркера из Красногорья – это одна из наших территорий к востоку от Элвиннского леса. Он просит, чтобы мы прислали ему какого-нибудь героя на помощь.$B$BНо военных у нас так мало, что я даже не знаю, кого мы можем отправить туда. Может, ты сходишь к Паркеру и узнаешь, чего он хочет? Капитана стражи можно найти на вершине башни в Трех Углах.','Найдите капитана стражи Паркера в Часовой башне в Красногорье.','Говорят, проблем в Западном краю выше крыши.$B$B<Паркер даже не поворачивается к вам.>$B$BНо у нас тут тоже хватает неприятностей. Видишь вон тех гноллов? Похоже, они опять что-то затевают, и мне это не нравится. Ни капельки не нравится.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Воззвание к героям: Красногорье!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Здесь, конечно, дела идут ужасно, но в других частях этих земель начались сильные землетрясения из-за смещения земных пластов.$B$BМне тут пришел отчет от капитана стражи Паркера из Красногорья – это одна из наших территорий к востоку от Элвиннского леса. Он просит, чтобы мы прислали ему какого-нибудь героя на помощь.$B$BНо военных у нас так мало, что я даже не знаю, кого мы можем отправить туда. Может, ты сходишь к Паркеру и узнаешь, чего он хочет? Капитана стражи можно найти на вершине башни в Трех Углах.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите капитана стражи Паркера в Часовой башне в Красногорье.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Говорят, проблем в Западном краю выше крыши.$B$B<Паркер даже не поворачивается к вам.>$B$BНо у нас тут тоже хватает неприятностей. Видишь вон тех гноллов? Похоже, они опять что-то затевают, и мне это не нравится. Ни капельки не нравится.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26366,'Все дело в голове','Умбода из племени Порочной Ветви – один из самых сильных воинов и маньяк-убийца.$B$BОн забирает головы тех, кого убивает, и использует потом как побрякушки, трофеи... даже как оружие! Теперь пришло его время ответить за все!$B$BНайди Умбоду "Три Башки", убей его и принеси мне ЕГО голову! Посмотрим, как будет сражаться племя Порочной Ветви, когда мы кинем в них его башкой!','Убейте Умбоду "Три Башки" и заберите его голову.','Рожа испуганная и растерянная… именно так и должно быть! Хорошо бы остальные тролли племени Порочной Ветви нацепили на морды такое же выражение!','Посмотрим!','Вернитесь к Старейшине Сломанному Клыку в Джинта\'Алор, что во Внутренних землях.','Принеси его голову. Среднюю.','Умбода "Три башки"') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Все дело в голове',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Умбода из племени Порочной Ветви – один из самых сильных воинов и маньяк-убийца.$B$BОн забирает головы тех, кого убивает, и использует потом как побрякушки, трофеи... даже как оружие! Теперь пришло его время ответить за все!$B$BНайди Умбоду "Три Башки", убей его и принеси мне ЕГО голову! Посмотрим, как будет сражаться племя Порочной Ветви, когда мы кинем в них его башкой!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Умбоду "Три Башки" и заберите его голову.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Рожа испуганная и растерянная… именно так и должно быть! Хорошо бы остальные тролли племени Порочной Ветви нацепили на морды такое же выражение!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Посмотрим!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Старейшине Сломанному Клыку в Джинта\'Алор, что во Внутренних землях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Принеси его голову. Среднюю.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Умбода "Три башки"',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26367,'Месть Онго\'лонго','Деритесь с Онго\'лонго, пока он не освободится.','Вернитесь к старейшине племени Сломанного Клыка в Джинта\'Алор, что во Внутренних землях.','Разозли его, а потом отойди!','Онго\'лонго') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Месть Онго\'лонго',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Деритесь с Онго\'лонго, пока он не освободится.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старейшине племени Сломанного Клыка в Джинта\'Алор, что во Внутренних землях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Разозли его, а потом отойди!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Онго\'лонго',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26368,'Ядовитые секреты','Если мы собрались вызывать Шадру, то надо будет собрать побольше этого любопытного яда.$B$BИ нечего на меня так смотреть... Отрекшимся уже доводилось изучать эти земли, и с ядовитой королевой мы встречались по меньшей мере разочек. Ее токсины весьма пригодились нам в прошлом...$B$BПригодятся они Орде и теперь. Так что сделай милость: собери, сколько сумеешь, яда с паучат Шадры – они живут в пещере на вершине... Думаю, ты по-любому перемажешься в нем с головы до ног.','Соберите 6 образцов яда Шадры с паучат Шадры в Джинта\'Алоре.','Вернитесь к Элизе Желчной в Джинта\'Алор, что во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ядовитые секреты',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если мы собрались вызывать Шадру, то надо будет собрать побольше этого любопытного яда.$B$BИ нечего на меня так смотреть... Отрекшимся уже доводилось изучать эти земли, и с ядовитой королевой мы встречались по меньшей мере разочек. Ее токсины весьма пригодились нам в прошлом...$B$BПригодятся они Орде и теперь. Так что сделай милость: собери, сколько сумеешь, яда с паучат Шадры – они живут в пещере на вершине... Думаю, ты по-любому перемажешься в нем с головы до ног.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 6 образцов яда Шадры с паучат Шадры в Джинта\'Алоре.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Элизе Желчной в Джинта\'Алор, что во Внутренних землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26369,'Охота на хранительницу','Котонга рассказал мне про Шадру. Это ядовитая королева, повелительница пауков, почитатели которой затаились во тьме. Если даже тролли из племени Порочной Ветви уже начали свои ритуалы, то закончить я им не дам.$B$BОбследуй пещеру на вершине Джинта\'Алора, сразу за алтарем. Я думаю, что там скрывается одна из хранительниц Шадры, так что убей ее и принеси мне ее вещи – так хоть будем знать, что там у них происходит.','Убейте Морта\'гью Хранительницу и заберите у нее табличку Шадры.','Части разделены, и хранители рассажены по разным местам… Ясно.$B$BОни готовят ритуал вызова Шадры. Но вряд ли они успели далеко продвинуться. Нужно уничтожить эту штуку…','Обыщи ее труп. Не хотелось бы наткнуться на какую-нибудь ловушку, скрытую в мертвом теле...','Вернитесь к Старейшине Сломанному Клыку в Джинта\'Алор, что во Внутренних землях.','Без сомнений, она будет прятаться в глубине пещеры.','Морта\'гья Хранительница') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота на хранительницу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Котонга рассказал мне про Шадру. Это ядовитая королева, повелительница пауков, почитатели которой затаились во тьме. Если даже тролли из племени Порочной Ветви уже начали свои ритуалы, то закончить я им не дам.$B$BОбследуй пещеру на вершине Джинта\'Алора, сразу за алтарем. Я думаю, что там скрывается одна из хранительниц Шадры, так что убей ее и принеси мне ее вещи – так хоть будем знать, что там у них происходит.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Морта\'гью Хранительницу и заберите у нее табличку Шадры.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Части разделены, и хранители рассажены по разным местам… Ясно.$B$BОни готовят ритуал вызова Шадры. Но вряд ли они успели далеко продвинуться. Нужно уничтожить эту штуку…',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Обыщи ее труп. Не хотелось бы наткнуться на какую-нибудь ловушку, скрытую в мертвом теле...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Старейшине Сломанному Клыку в Джинта\'Алор, что во Внутренних землях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Без сомнений, она будет прятаться в глубине пещеры.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Морта\'гья Хранительница',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (26370,'Возвращение на Сторожевой холм') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение на Сторожевой холм',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26371,'Легенда о капитане Грейсоне','Тебе приходилось слышать о капитане Грейсоне? Некоторые говорят, что это пьяный бред матроса, но любой в Западном крае скажет тебе, что Грейсон существует на самом деле! Он призрак, который блуждает по маяку Западного края далеко на западе, на Бескрайнем берегу.$B$BСлабо проверить?','Найдите капитана Грейсона на маяке Западного края.','Да… Когда-то я был из плоти и крови, прям как ты, паренек. А потом в один несчастный день мурлоки напали на маяк…') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Легенда о капитане Грейсоне',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе приходилось слышать о капитане Грейсоне? Некоторые говорят, что это пьяный бред матроса, но любой в Западном крае скажет тебе, что Грейсон существует на самом деле! Он призрак, который блуждает по маяку Западного края далеко на западе, на Бескрайнем берегу.$B$BСлабо проверить?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите капитана Грейсона на маяке Западного края.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да… Когда-то я был из плоти и крови, прям как ты, паренек. А потом в один несчастный день мурлоки напали на маяк…',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (26372,'Предполетная подготовка','Новый двигатель очень быстрый. И опасный. Я бы сказала "капризный".$b$bЭто-то капитану и нравится.$b$bВозвращайся обратно на холм и передай ему, что я сейчас установлю эту штучку, и он должен встретиться со мной на верфи.','Двигатель установлен? Наконец-то!$B$BТеперь мы разорвем небеса!$B$BПоскольку наземные и воздушные силы готовы, пора подсветить небо над Сумеречным нагорьем.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Предполетная подготовка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Новый двигатель очень быстрый. И опасный. Я бы сказала "капризный".$b$bЭто-то капитану и нравится.$b$bВозвращайся обратно на холм и передай ему, что я сейчас установлю эту штучку, и он должен встретиться со мной на верфи.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Двигатель установлен? Наконец-то!$B$BТеперь мы разорвем небеса!$B$BПоскольку наземные и воздушные силы готовы, пора подсветить небо над Сумеречным нагорьем.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26373,'На Каранос','Некоторые горные пехотинцы, находящиеся под командованием Камнемола, рассказывали мне о ситуации в Караносе. Когда трогги захватили форт Мерзлогривов, оставшиеся в живых тролли были вынуждены бежать в западном направлении, забираясь в самое сердце дворфийских земель.$b$bТеперь они создают угрозу для дворфийского города Караноса. Поэтому жителям Караноса пригодится любая помощь. Отправляйся в Каранос и найди капитана Таррана. Иди по дороге, ведущей на восток от Поселка Пивоваров, до тех пор, пока не увидишь город.','Поговорите с капитаном Тарраном в Караносе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На Каранос',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Некоторые горные пехотинцы, находящиеся под командованием Камнемола, рассказывали мне о ситуации в Караносе. Когда трогги захватили форт Мерзлогривов, оставшиеся в живых тролли были вынуждены бежать в западном направлении, забираясь в самое сердце дворфийских земель.$b$bТеперь они создают угрозу для дворфийского города Караноса. Поэтому жителям Караноса пригодится любая помощь. Отправляйся в Каранос и найди капитана Таррана. Иди по дороге, ведущей на восток от Поселка Пивоваров, до тех пор, пока не увидишь город.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с капитаном Тарраном в Караносе.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (26374,'Готовность наземных сил','Собирать войска в этом полном злачных мест гоблинском городе было плохой идеей. За деньги здесь можно предаться всем возможным порокам. Наши бывалые солдаты ведут себя безрассудно и просаживают в этом городе все заработанное в Нордсколе за годы.$b$bМожешь пробежаться по городу и собрать всех бойцов, которые ушли в самоволку?$b$bНа поле битвы мои закаленные воины не имеют себе равных, но я не хочу, чтобы они позорили честь мундира дезертирством.','Вернитесь к полководцу Кроггу в Гавань Трюмных Вод в Азшаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Готовность наземных сил',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Собирать войска в этом полном злачных мест гоблинском городе было плохой идеей. За деньги здесь можно предаться всем возможным порокам. Наши бывалые солдаты ведут себя безрассудно и просаживают в этом городе все заработанное в Нордсколе за годы.$b$bМожешь пробежаться по городу и собрать всех бойцов, которые ушли в самоволку?$b$bНа поле битвы мои закаленные воины не имеют себе равных, но я не хочу, чтобы они позорили честь мундира дезертирством.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к полководцу Кроггу в Гавань Трюмных Вод в Азшаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26375,'Освободить скальчат','Сумеречные сектанты хватают моих скальчат. Мучают их, пытают. Высасывают саму их сущность, которая и отличает малышей от обычных камней.$b$bПожалуйста, |3-6($r), освободи скальчат. У нас с Диамантом не хватит аккуратности, чтобы разбить цепи, которыми их удерживают, не причинив скальчатам вреда. Но у нас есть инструмент, которым ты $gмог:могла; бы воспользоваться.$b$bВозьми это. Разбей цепи и освободи скальчат.','Воспользуйтесь крошечным сокрушителем цепей, чтобы освободить 6 кварцевых скальчат.','Вернитесь к кварцевому камнестражу к Вратам Лортуны в Подземье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Освободить скальчат',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сумеречные сектанты хватают моих скальчат. Мучают их, пытают. Высасывают саму их сущность, которая и отличает малышей от обычных камней.$b$bПожалуйста, |3-6($r), освободи скальчат. У нас с Диамантом не хватит аккуратности, чтобы разбить цепи, которыми их удерживают, не причинив скальчатам вреда. Но у нас есть инструмент, которым ты $gмог:могла; бы воспользоваться.$b$bВозьми это. Разбей цепи и освободи скальчат.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь крошечным сокрушителем цепей, чтобы освободить 6 кварцевых скальчат.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к кварцевому камнестражу к Вратам Лортуны в Подземье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26376,'Глубоко проникающая ненависть','Убейте Драгула Громадоруба и 12 сектантов Сумеречного Молота у Врат Лортуны.','Вернитесь к Диаманту Терпеливому к Вратам Лортуны, что в Подземье.','Лидер сил у врат Лортуны.','Драгул Громадоруб') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Глубоко проникающая ненависть',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Драгула Громадоруба и 12 сектантов Сумеречного Молота у Врат Лортуны.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Диаманту Терпеливому к Вратам Лортуны, что в Подземье.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Лидер сил у врат Лортуны.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Драгул Громадоруб',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26377,'Нетвердая земля','Сектанты Сумеречного Молота собирают кристаллы нефритов возле своего лагеря.$b$bГлупые...$b$bБезрассудные...$b$bСобирать ископаемые кристаллы. Приносить их в лагерь. Разбивать их о землю.$b$bОни привлекут проходчиков.$b$bОни научатся уважать землю...$b$bЧасть за частью...$b$bКамень за камнем...$b$b...со временем.','Соберите 6 друз нефритовых кристаллов, совместите их, а затем разбейте в лагере Врат Лортуны.','Со временем всем воздастся по заслугам.$B$BИ самому маленькому камешку.$B$BИ самой большой горе.$B$BИ самому упрямому сектанту.','Вернитесь к Диаманту Терпеливому к Вратам Лортуны, что в Подземье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нетвердая земля',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сектанты Сумеречного Молота собирают кристаллы нефритов возле своего лагеря.$b$bГлупые...$b$bБезрассудные...$b$bСобирать ископаемые кристаллы. Приносить их в лагерь. Разбивать их о землю.$b$bОни привлекут проходчиков.$b$bОни научатся уважать землю...$b$bЧасть за частью...$b$bКамень за камнем...$b$b...со временем.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 6 друз нефритовых кристаллов, совместите их, а затем разбейте в лагере Врат Лортуны.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Со временем всем воздастся по заслугам.$B$BИ самому маленькому камешку.$B$BИ самой большой горе.$B$BИ самому упрямому сектанту.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Диаманту Терпеливому к Вратам Лортуны, что в Подземье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (26378,'Убийства, новичок. Вот что творится в землях перед нашими глазами.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Убийства, новичок. Вот что творится в землях перед нашими глазами.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26379,'На помощь беженцам','Надеюсь, ты $gпришел:пришла; помочь нам? По-моему, ты даже не в курсе, что нам нужна помощь...$B$BЛадно, у меня нет времени вдаваться в детали, но один из наших городов на Темных берегах довольно сильно пострадал от Катаклизма. Сейчас мы занимаемся спасением выживших, но мне нужна помощь опытного искателя приключений – вроде тебя – чтобы наведаться в лагерь беженцев на юге от Аубердина.$B$BОтправляйся туда и спаси как можно больше выживших.','Часовой Лендра из Лор\'данела просит вас поговорить с жрицей Алинией в Лагере беженцев.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На помощь беженцам',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Надеюсь, ты $gпришел:пришла; помочь нам? По-моему, ты даже не в курсе, что нам нужна помощь...$B$BЛадно, у меня нет времени вдаваться в детали, но один из наших городов на Темных берегах довольно сильно пострадал от Катаклизма. Сейчас мы занимаемся спасением выживших, но мне нужна помощь опытного искателя приключений – вроде тебя – чтобы наведаться в лагерь беженцев на юге от Аубердина.$B$BОтправляйся туда и спаси как можно больше выживших.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Часовой Лендра из Лор\'данела просит вас поговорить с жрицей Алинией в Лагере беженцев.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (26380,'На пути в Каранос','Мне нужно было отнести эти бочонки с элем в трактир в Караносе. Это новый загадочный эль, который производит недавно открывшаяся и быстро достигшая успеха пивоварня в Поселке Пивоваров. Как только я вышла из города, меня атаковала группа налетчиков из клана Мерзлогривов. Мне теперь долго придется ремонтировать свою телегу!$b$bЯ не очень-то рассчитываю, что ты сделаешь мне одолжение... или сделаешь? Эти большие бочки не сдвинешь, но у меня есть и маленькие бочонки с элем на пробу. Не отнесешь ли ты их в Каранос? Просто иди по дороге на юго-восток.','Отнесите бочонки с элем на пробу хозяину таверны "Громоварка" Белму.','Добро пожаловать, путник. Хочешь отдохнуть или тебе нужен новый камень возвращения?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На пути в Каранос',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне нужно было отнести эти бочонки с элем в трактир в Караносе. Это новый загадочный эль, который производит недавно открывшаяся и быстро достигшая успеха пивоварня в Поселке Пивоваров. Как только я вышла из города, меня атаковала группа налетчиков из клана Мерзлогривов. Мне теперь долго придется ремонтировать свою телегу!$b$bЯ не очень-то рассчитываю, что ты сделаешь мне одолжение... или сделаешь? Эти большие бочки не сдвинешь, но у меня есть и маленькие бочонки с элем на пробу. Не отнесешь ли ты их в Каранос? Просто иди по дороге на юго-восток.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите бочонки с элем на пробу хозяину таверны "Громоварка" Белму.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Добро пожаловать, путник. Хочешь отдохнуть или тебе нужен новый камень возвращения?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26381,'Глаз Шадры','Шадру обязательно надо призвать. Упускать такую возможность было бы глупо. Аптекари могут найти достойное применение яду богини, но в ритуалах они полные профаны.$B$BПо счастью, я знаком с призыванием богов. Принеси мне останки Шадры, а я помогу тебе вызвать ее в наш мир.$B$BПервая часть – это глаз Шадры, его хранят в Агол\'ватe к северу отсюда.','Принесите глаз Шадры из Агол\'ваты.','Вернитесь к темному священнику Марналу в исследовательский лагерь Хири\'вата, что во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Глаз Шадры',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Шадру обязательно надо призвать. Упускать такую возможность было бы глупо. Аптекари могут найти достойное применение яду богини, но в ритуалах они полные профаны.$B$BПо счастью, я знаком с призыванием богов. Принеси мне останки Шадры, а я помогу тебе вызвать ее в наш мир.$B$BПервая часть – это глаз Шадры, его хранят в Агол\'ватe к северу отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите глаз Шадры из Агол\'ваты.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к темному священнику Марналу в исследовательский лагерь Хири\'вата, что во Внутренних землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26382,'Без яиц яичницу не сделаешь...','Марнал уже много дней надоедает мне своим планом про эту Шадру. Я даже почти расстроилась, когда узнала, что он действительно нашел эту табличку, уже надеялась, что он заткнется на эту тему.$B$BНо несмотря на его высокомерные отзывы о ритуальной магии, он все еще нужен мне – как и я ему. Мне надо будет смешать основную среду с аналогичным...$B$B...Знаешь что, не хочу утомлять тебя подробностями. Просто иди в Агол\'вату и принеси мне яйца ядоплюя. Их охраняют тролли племени Порочной Ветви.','Соберите 5 яиц порождения Шадры в Агол\'вате.','Вернитесь к аптекарю Сурлису в исследовательский лагерь Хири\'вата, что во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Без яиц яичницу не сделаешь...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Марнал уже много дней надоедает мне своим планом про эту Шадру. Я даже почти расстроилась, когда узнала, что он действительно нашел эту табличку, уже надеялась, что он заткнется на эту тему.$B$BНо несмотря на его высокомерные отзывы о ритуальной магии, он все еще нужен мне – как и я ему. Мне надо будет смешать основную среду с аналогичным...$B$B...Знаешь что, не хочу утомлять тебя подробностями. Просто иди в Агол\'вату и принеси мне яйца ядоплюя. Их охраняют тролли племени Порочной Ветви.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 5 яиц порождения Шадры в Агол\'вате.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к аптекарю Сурлису в исследовательский лагерь Хири\'вата, что во Внутренних землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (26383,'Ветра перемен','Ты! Да, я к тебе обращаюсь! Мне кажется, или ты хочешь нам помочь?$B$BАубердин пал, и хотя большинство жителей покинули его стены еще во время первых проявлений Катаклизма, многие упрямцы все отказывались от эвакуации до последнего. А теперь город захвачен элементалями воды.$B$BМои сестры помогают спасать выживших, и им срочно нужна помощь. Пожалуйста, воспользуйся западным деревом, чтобы добраться до Рут\'Терана, а там поговори с Веспристом, пусть он как можно скорее отправит тебя в Лор\'данел. Не медли ни минуты!','Тебя прислали часовые? Хвала Элуне! Нам нужна вся помощь, которую мы только можем получить.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ветра перемен',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты! Да, я к тебе обращаюсь! Мне кажется, или ты хочешь нам помочь?$B$BАубердин пал, и хотя большинство жителей покинули его стены еще во время первых проявлений Катаклизма, многие упрямцы все отказывались от эвакуации до последнего. А теперь город захвачен элементалями воды.$B$BМои сестры помогают спасать выживших, и им срочно нужна помощь. Пожалуйста, воспользуйся западным деревом, чтобы добраться до Рут\'Терана, а там поговори с Веспристом, пусть он как можно скорее отправит тебя в Лор\'данел. Не медли ни минуты!',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебя прислали часовые? Хвала Элуне! Нам нужна вся помощь, которую мы только можем получить.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26384,'Темный священник Марнал','Нельзя просто так выкидывать эту табличку, $n. Ее можно использовать...$B$BВидишь ли, я разбираюсь с паучьим ядом. Он явно магический и связан с паучьим богом, которому поклоняются тролли. А если эта табличка позволяет его призвать...$B$BВот видишь, куда я клоню, да? Орда не может упустить такую возможность. Отнеси эту табличку к Отрекшимся. Иди на запад к исследовательской станции в руинах Хири\'ваты.','Принесите табличку Шадры темному священнику Марналу.','Так, что это у нас тут…$B$BЗанятно. Очень даже занятно!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Темный священник Марнал',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нельзя просто так выкидывать эту табличку, $n. Ее можно использовать...$B$BВидишь ли, я разбираюсь с паучьим ядом. Он явно магический и связан с паучьим богом, которому поклоняются тролли. А если эта табличка позволяет его призвать...$B$BВот видишь, куда я клоню, да? Орда не может упустить такую возможность. Отнеси эту табличку к Отрекшимся. Иди на запад к исследовательской станции в руинах Хири\'ваты.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите табличку Шадры темному священнику Марналу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так, что это у нас тут…$B$BЗанятно. Очень даже занятно!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (26385,'Ветра перемен','Союзники откликнулись на наш зов о помощи? Хвала Элуне! Будь благословенна мудрость Тиранды, которая приняла вас в наши ряды.$B$BНам нужна вся помощь, которую мы только можем получить.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ветра перемен',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Союзники откликнулись на наш зов о помощи? Хвала Элуне! Будь благословенна мудрость Тиранды, которая приняла вас в наши ряды.$B$BНам нужна вся помощь, которую мы только можем получить.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26386,'Сурхан','Жрица не очень хорошо орочий понимает, да.$B$BМожет, лучше поговорить с Сурханом, он вон в той палатке.$B$BРасскажи ему, что ты $gвидел:видела; в Зул\'Гурубе, да.','Поговорите с Сурханом в Бамбале, что в Северной Тернистой долине.','Поговорите с Сурханом в Бамбале, что в Северной Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сурхан',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Жрица не очень хорошо орочий понимает, да.$B$BМожет, лучше поговорить с Сурханом, он вон в той палатке.$B$BРасскажи ему, что ты $gвидел:видела; в Зул\'Гурубе, да.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Сурханом в Бамбале, что в Северной Тернистой долине.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Сурханом в Бамбале, что в Северной Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26387,'На голодном пайке','Пауки, живущие на востоке Ползучих руин, бесполезны. Мы зовем их ядоплюями, и ясно, что они как-то связаны с паучьм богом, но это не меняет того факта, что от них больше вреда, чем пользы. Будь на то моя воля, я бы избавилась от них раз и навсегда.$B$BКогда пойдешь в Ползучие руины, уничтожай все коконы, которые найдешь. Они ими питаются, поэтому лишить их еды намного эффективнее, чем пытаться перебить по одному.','Уничтожьте 6 оплетенных жертв в Ползучих руинах.','Вернитесь к аптекарю Сурлису в исследовательский лагерь Хири\'вата, что во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На голодном пайке',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пауки, живущие на востоке Ползучих руин, бесполезны. Мы зовем их ядоплюями, и ясно, что они как-то связаны с паучьм богом, но это не меняет того факта, что от них больше вреда, чем пользы. Будь на то моя воля, я бы избавилась от них раз и навсегда.$B$BКогда пойдешь в Ползучие руины, уничтожай все коконы, которые найдешь. Они ими питаются, поэтому лишить их еды намного эффективнее, чем пытаться перебить по одному.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 6 оплетенных жертв в Ползучих руинах.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к аптекарю Сурлису в исследовательский лагерь Хири\'вата, что во Внутренних землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26388,'Сумеречные небеса','Отлично, ты $gприбыл:прибыла;. Подожди здесь прибытия дирижабля капитана Психхо, а затем поднимайся на борт и сопровождай воздушный флот. Адмирал Каменный Кулак будет ждать тебя у порта Драконьей Пасти!','Сопроводите воздушный флот Орды к Сумеречному нагорью. Воспользуйтесь дирижаблем, улетающим от южной конечной станции ракетной дороги в Азшаре.','Поговорите с адмиралом Каменным Кулаком в порту Драконьей Пасти на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сумеречные небеса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Отлично, ты $gприбыл:прибыла;. Подожди здесь прибытия дирижабля капитана Психхо, а затем поднимайся на борт и сопровождай воздушный флот. Адмирал Каменный Кулак будет ждать тебя у порта Драконьей Пасти!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сопроводите воздушный флот Орды к Сумеречному нагорью. Воспользуйтесь дирижаблем, улетающим от южной конечной станции ракетной дороги в Азшаре.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с адмиралом Каменным Кулаком в порту Драконьей Пасти на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26389,'Вторжение клана Черной горы','Теперь оркам Черной горы точно придет конец – их основные силы-то разгромлены! Осталась последняя задача.','Вернитесь к маршалу Макбрайду, находящемуся перед Аббатством Североземья в Элвиннском лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вторжение клана Черной горы',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь оркам Черной горы точно придет конец – их основные силы-то разгромлены! Осталась последняя задача.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к маршалу Макбрайду, находящемуся перед Аббатством Североземья в Элвиннском лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26390,'Оккупанты – вон!','Убейте Куртока Душегуба.','Курток убит, и мы снова обезопасили себя от нападений орков. Я пошлю крестьян к ущелью – нужно попробовать завалить его, чтобы больше ни один орк не смог сюда просочиться.$B$BЭто был настоящий подвиг – прими же благодарность Штормграда и всего Альянса!','Вернитесь к маршалу Макбрайду, находящемуся перед Аббатством Североземья в Элвиннском лесу.','Курток скрывается в дыме и пламени на востоке.','Курток Душегуб') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оккупанты – вон!',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Куртока Душегуба.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Курток убит, и мы снова обезопасили себя от нападений орков. Я пошлю крестьян к ущелью – нужно попробовать завалить его, чтобы больше ни один орк не смог сюда просочиться.$B$BЭто был настоящий подвиг – прими же благодарность Штормграда и всего Альянса!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к маршалу Макбрайду, находящемуся перед Аббатством Североземья в Элвиннском лесу.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Курток скрывается в дыме и пламени на востоке.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Курток Душегуб',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26391,'Еще есть надежда','Воспользуйтесь огнетушителем Милли, чтобы погасить 8 очагов возгорания на винограднике.','Благословенно будь твое сердце, $n. Ты герой Альянса! Земля вся прогорела и от виноградника осталась только куча золы и мусора, но я думаю, его еще можно возродить. Да? Не так уж ведь все и плохо?','Вернитесь к Милли Осворт в долину Североземья в Элвиннском лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Еще есть надежда',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь огнетушителем Милли, чтобы погасить 8 очагов возгорания на винограднике.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Благословенно будь твое сердце, $n. Ты герой Альянса! Земля вся прогорела и от виноградника осталась только куча золы и мусора, но я думаю, его еще можно возродить. Да? Не так уж ведь все и плохо?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Милли Осворт в долину Североземья в Элвиннском лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26392,'Свидетельство о подвигах','Ты $gпрогнал:прогнала; орков Черной горы, и за это мы тебе очень благодарны! К сожалению, виноградники сожжены дотла, но остальное Североземье теперь в безопасности – и это твоя заслуга.$B$BПрошу, прими это свидетельство, в котором перечислены твои подвиги, и покажи его маршалу Макбрайду. Он отвечает за безопасность долины Североземья и будет рад услышать о том, что ты $gсделал:сделала;.','Доставьте свидетельство о подвигах маршалу Макбрайду в долину Североземья в Элвиннском лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Свидетельство о подвигах',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gпрогнал:прогнала; орков Черной горы, и за это мы тебе очень благодарны! К сожалению, виноградники сожжены дотла, но остальное Североземье теперь в безопасности – и это твоя заслуга.$B$BПрошу, прими это свидетельство, в котором перечислены твои подвиги, и покажи его маршалу Макбрайду. Он отвечает за безопасность долины Североземья и будет рад услышать о том, что ты $gсделал:сделала;.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте свидетельство о подвигах маршалу Макбрайду в долину Североземья в Элвиннском лесу.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26393,'Срочное сообщение','Отнесите записку Аргуса укротителю грифонов Бартлетту Храбрецу.','Тебе нужно доставить это письмо в Штормград? Никаких проблем, можешь взять одного из моих грифонов!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Срочное сообщение',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите записку Аргуса укротителю грифонов Бартлетту Храбрецу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебе нужно доставить это письмо в Штормград? Никаких проблем, можешь взять одного из моих грифонов!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26394,'Полет в Штормград','За небольшую плату ты можешь нанять грифона и доставить Озрику записку Аргуса. Нет способа добраться туда быстрее.$b$bЕсли это тебе подходит, вернись ко мне, когда будешь $gготов:готова; к полету. Я, конечно, возьму с тебя немного денег, но поверь, оно того стоит!','Заплатите за полет укротителю грифонов Бартлетту Храбрецу, затем доставьте записку Аргуса Озрику Штрангу в магазин "Ограниченная неуязвимость" в Старом городе Штормграда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Полет в Штормград',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','За небольшую плату ты можешь нанять грифона и доставить Озрику записку Аргуса. Нет способа добраться туда быстрее.$b$bЕсли это тебе подходит, вернись ко мне, когда будешь $gготов:готова; к полету. Я, конечно, возьму с тебя немного денег, но поверь, оно того стоит!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заплатите за полет укротителю грифонов Бартлетту Храбрецу, затем доставьте записку Аргуса Озрику Штрангу в магазин "Ограниченная неуязвимость" в Старом городе Штормграда.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) VALUES (26394,'Путешествуешь, да? Что интересного видел?') ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Путешествуешь, да? Что интересного видел?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (26395,'Дунгар Долгопив','$n, в этом ящике все, что просил Аргус. Доставите это ему?$b$bЕсли вы уже поговорили в Златоземье с Бартлеттом, то можете вернуться к нему на грифоне. В Торговом квартале вы найдете Дунгара Долгопива, это наш укротитель грифонов.$b$bПоговорите с Дунгаром, а затем как можно быстрее доставьте ящик Аргусу. Нельзя оставлять без оружия наших бойцов в Златоземье!','Отнесите ящик Озрика укротителю грифонов Дунгару Долгопиву.','Ящик в Златоземье, да? Люди становятся все ленивее. Вы уже бывали там раньше? Если да, то нет никаких проблем, друг мой. У меня есть много грифонов, обученных летать туда!','Вспотели, друг мой? Видно, слишком много бегаете. В следующий раз берите грифона!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дунгар Долгопив',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, в этом ящике все, что просил Аргус. Доставите это ему?$b$bЕсли вы уже поговорили в Златоземье с Бартлеттом, то можете вернуться к нему на грифоне. В Торговом квартале вы найдете Дунгара Долгопива, это наш укротитель грифонов.$b$bПоговорите с Дунгаром, а затем как можно быстрее доставьте ящик Аргусу. Нельзя оставлять без оружия наших бойцов в Златоземье!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите ящик Озрика укротителю грифонов Дунгару Долгопиву.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ящик в Златоземье, да? Люди становятся все ленивее. Вы уже бывали там раньше? Если да, то нет никаких проблем, друг мой. У меня есть много грифонов, обученных летать туда!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вспотели, друг мой? Видно, слишком много бегаете. В следующий раз берите грифона!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26396,'Возвращение к Аргусу','В Златоземье укротитель грифонов – Бартлетт. Если ты с ним уже $gзнаком:знакома;, ты можешь вернуться туда на одном из моих грифонов.$b$bЭто стоит знать: летать в столицу обучают всех грифонов. Но доставить тебя к какому-то из отдаленных укротителей грифонов он может только в том случае, если ты там уже $gбыл:была;.$b$bТы уже $gбыл:была; у Бартлетта, так что просто скажи мне, когда будешь $gготов:готова; отправиться на грифоне в Златоземье. Там ты сможешь доставить кузнецу Аргусу ящик Озрика.','Заплатите за полет укротителю грифонов Дунгару Долгопиву, затем доставьте ящик Озрика кузнецу Аргусу в Златоземье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение к Аргусу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В Златоземье укротитель грифонов – Бартлетт. Если ты с ним уже $gзнаком:знакома;, ты можешь вернуться туда на одном из моих грифонов.$b$bЭто стоит знать: летать в столицу обучают всех грифонов. Но доставить тебя к какому-то из отдаленных укротителей грифонов он может только в том случае, если ты там уже $gбыл:была;.$b$bТы уже $gбыл:была; у Бартлетта, так что просто скажи мне, когда будешь $gготов:готова; отправиться на грифоне в Златоземье. Там ты сможешь доставить кузнецу Аргусу ящик Озрика.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заплатите за полет укротителю грифонов Дунгару Долгопиву, затем доставьте ящик Озрика кузнецу Аргусу в Златоземье.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (26397,'Да хранит тебя Мать-Земля') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Да хранит тебя Мать-Земля',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (26398,'Да хранит тебя Мать-Земля') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Да хранит тебя Мать-Земля',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26399,'Сокровища клана Мош\'Огг','А ты $gслыхал:слыхала; про огров? Один парень по имени Мок\'тардин говорил, что $gкакой-то уродец:какая-то лахудра:r; |3-6($r), $gодетый как:одетая как:c; |3-6($c), $gнашел:нашла; руку огра и...$B$B<Скизи оглядывает вас и замолкает.>$B$BО чем это я? Ах да! $GКакой-то ВЕЛИЧАЙШИЙ ГЕРОЙ нашел:какая-то ПРЕКРАСНЕЙШАЯ ГЕРОИНЯ нашла; руку огра, а по мнению Мок\'тардина это значит, что у огров есть особый артефакт. Я видел, что они охраняют какой-то сундук в руинах, в своем жилище. Может, сбегаешь да посмотришь?','Добудьте сокровища клана Мош\'Огг в руинах за холмом Мош\'Огг.','<Скизи тщетно пытается открыть коробку.>$B$BДа уж... Что-что, а сундуки с сокровищами эти огры запирать умеют. Я тебе так скажу, дорогой мой: коробка мне и даром не нужна. Ее надо открыть!','И почему все бесценные артефакты всегда находят ОГРЫ?!','Вернитесь к Скизи Крюкоуху в Бамбалу, что в Северной Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сокровища клана Мош\'Огг',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А ты $gслыхал:слыхала; про огров? Один парень по имени Мок\'тардин говорил, что $gкакой-то уродец:какая-то лахудра:r; |3-6($r), $gодетый как:одетая как:c; |3-6($c), $gнашел:нашла; руку огра и...$B$B<Скизи оглядывает вас и замолкает.>$B$BО чем это я? Ах да! $GКакой-то ВЕЛИЧАЙШИЙ ГЕРОЙ нашел:какая-то ПРЕКРАСНЕЙШАЯ ГЕРОИНЯ нашла; руку огра, а по мнению Мок\'тардина это значит, что у огров есть особый артефакт. Я видел, что они охраняют какой-то сундук в руинах, в своем жилище. Может, сбегаешь да посмотришь?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте сокровища клана Мош\'Огг в руинах за холмом Мош\'Огг.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Скизи тщетно пытается открыть коробку.>$B$BДа уж... Что-что, а сундуки с сокровищами эти огры запирать умеют. Я тебе так скажу, дорогой мой: коробка мне и даром не нужна. Ее надо открыть!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','И почему все бесценные артефакты всегда находят ОГРЫ?!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Скизи Крюкоуху в Бамбалу, что в Северной Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26400,'Универсальный ключ','<Гоблин заглядывает внутрь.>$B$BЧего-о?!$B$BЯ... придется мне послать это... Флюму... на юг. Он точно сообразит, что с этим делать.','Ну что, открыл коробку? Мне не терпится узнать, что же там внутри!','Вернитесь к Скизи Крюкоуху в Бамбалу, что в Северной Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Универсальный ключ',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Гоблин заглядывает внутрь.>$B$BЧего-о?!$B$BЯ... придется мне послать это... Флюму... на юг. Он точно сообразит, что с этим делать.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, открыл коробку? Мне не терпится узнать, что же там внутри!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Скизи Крюкоуху в Бамбалу, что в Северной Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26401,'Вернуться к Вестии','Мягкий свет пьедестала становится ярче, и на нем оказывается простая цепочка. Это и есть то, что было нужно ученице?','Отнесите амулет Мглистой пещеры Вестии Лунное Копье в башню Эстулана.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вернуться к Вестии',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мягкий свет пьедестала становится ярче, и на нем оказывается простая цепочка. Это и есть то, что было нужно ученице?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите амулет Мглистой пещеры Вестии Лунное Копье в башню Эстулана.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) VALUES (26401,'Снова ты... И без него...') ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Снова ты... И без него...',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (26402,'Генерал Шандриса Оперенная Луна','Поговорите с Шандрисой Оперенной Луной в Крепости Оперенной луны в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Генерал Шандриса Оперенная Луна',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Шандрисой Оперенной Луной в Крепости Оперенной луны в Фераласе.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26403,'Принесите 5 упавших кристаллов Скизи Крюкоуху в Бамбалу, что в Северной Тернистой долине.','Великолепно! Замечательно! Я за них приличный куш сорву!$B$BТорговая Компания выбрала не те джунгли для своего рудника, не так ли? Всем было бы куда лучше, если бы они убрались отсюда.','Вернитесь к Скизи Крюкоуху в Бамбалу, что в Северной Тернистой долине.') ON DUPLICATE KEY UPDATE `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 5 упавших кристаллов Скизи Крюкоуху в Бамбалу, что в Северной Тернистой долине.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Великолепно! Замечательно! Я за них приличный куш сорву!$B$BТорговая Компания выбрала не те джунгли для своего рудника, не так ли? Всем было бы куда лучше, если бы они убрались отсюда.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Скизи Крюкоуху в Бамбалу, что в Северной Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (26404,'Работенка уровнем повыше','Слушай, а ты $gбывал:бывала; в Укрытии Кофельнагель? О, да ты просто $gОБЯЗАН:ОБЯЗАНА; там побывать. Там есть все, что нужно гоблину.$B$BСлушай-ка... Ты вроде |3-6($c) что надо. Расха – вон она, в куртке и юбке, – может тебя туда подбросить, если ты еще не знаешь дорогу.$B$BЯ оплачу полет.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Работенка уровнем повыше',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слушай, а ты $gбывал:бывала; в Укрытии Кофельнагель? О, да ты просто $gОБЯЗАН:ОБЯЗАНА; там побывать. Там есть все, что нужно гоблину.$B$BСлушай-ка... Ты вроде |3-6($c) что надо. Расха – вон она, в куртке и юбке, – может тебя туда подбросить, если ты еще не знаешь дорогу.$B$BЯ оплачу полет.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26405,'Пляски Зул\'Мамве','Дробители Черепов – сущая напасть для всей империи троллей. Их грызня с Кровавыми Скальпами расколола северную Тернистую долину. Там, где процветают племена Черного Копья и зандалары, Дробители Черепов сражаются за руины.$B$BМне поручено нанять бойцов, способных покарать этих Дробителей Черепов. Я призываю тебя и тех, кого ты знаешь, отправиться на юг в Зул\'Мамве и приструнить воинственное племя.','Убейте 16 троллей из племени Дробителей Черепов в Зул\'Мамве.','Вот обещанная награда. Тролли гордятся тобой.','Вернитесь к Сурхану в Бамбалу, что в Северной Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пляски Зул\'Мамве',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Дробители Черепов – сущая напасть для всей империи троллей. Их грызня с Кровавыми Скальпами расколола северную Тернистую долину. Там, где процветают племена Черного Копья и зандалары, Дробители Черепов сражаются за руины.$B$BМне поручено нанять бойцов, способных покарать этих Дробителей Черепов. Я призываю тебя и тех, кого ты знаешь, отправиться на юг в Зул\'Мамве и приструнить воинственное племя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 16 троллей из племени Дробителей Черепов в Зул\'Мамве.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот обещанная награда. Тролли гордятся тобой.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сурхану в Бамбалу, что в Северной Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26406,'Зуб Шадры','Теперь нам потребуется зуб Шадры.$B$BОн находится в Ползучих руинах к востоку отсюда, и охраняют его дети самой Шадры. Это премерзкие пауки размером с дворфа, и вдвое сильнее. А еще они очень ядовиты, $n... так что осторожнее.','Найдите зуб Шадры в Ползучих руинах.','Вернитесь к темному священнику Марналу на исследовательскую станцию Хири\'вата.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зуб Шадры',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь нам потребуется зуб Шадры.$B$BОн находится в Ползучих руинах к востоку отсюда, и охраняют его дети самой Шадры. Это премерзкие пауки размером с дворфа, и вдвое сильнее. А еще они очень ядовиты, $n... так что осторожнее.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите зуб Шадры в Ползучих руинах.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к темному священнику Марналу на исследовательскую станцию Хири\'вата.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26407,'Ручная работа Мош\'Огга','У этого огра при себе оказался необычный предмет – оторванная рука другого огра на веревочке, чтобы носить на шее. Сама рука вся была в шрамах, светящихся слабым фиолетовым цветом.$B$BСветящиеся после смерти шрамы встречаются редко, а уж увидеть такой предмет у огра странно вдвойне. Может, в Гром\'голе кто подскажет, что делать с подобной штуковиной.','Принесите искалеченную руку огра клана Мош\'Огг провозвестнику Мок\'тардину в лагерь Гром\'Гол, что в Северной Тернистой долине.','Рука, говоришь?','Принесите искалеченную руку огра клана Мош\'Огг провозвестнику Мок\'тардину в лагерь Гром\'Гол, что в Северной Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ручная работа Мош\'Огга',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У этого огра при себе оказался необычный предмет – оторванная рука другого огра на веревочке, чтобы носить на шее. Сама рука вся была в шрамах, светящихся слабым фиолетовым цветом.$B$BСветящиеся после смерти шрамы встречаются редко, а уж увидеть такой предмет у огра странно вдвойне. Может, в Гром\'голе кто подскажет, что делать с подобной штуковиной.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите искалеченную руку огра клана Мош\'Огг провозвестнику Мок\'тардину в лагерь Гром\'Гол, что в Северной Тернистой долине.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Рука, говоришь?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите искалеченную руку огра клана Мош\'Огг провозвестнику Мок\'тардину в лагерь Гром\'Гол, что в Северной Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (26408,'Пепел и ясень','Ох, как же приятно видеть здесь новые лица!$B$BЭти леса кишат ордынцами, а мне приказали охранять заставу. Мне не помешал бы соратник, готовый устроить хорошую драку.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пепел и ясень',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ох, как же приятно видеть здесь новые лица!$B$BЭти леса кишат ордынцами, а мне приказали охранять заставу. Мне не помешал бы соратник, готовый устроить хорошую драку.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26409,'Где Клондацк?','Мой посвященный гоблин ушел некоторое время назад. Его зовут Клондацк.$b$bЯ отправила его наблюдать за камнедерами к юго-западу от Кварцитовой впадины. Может быть, ты $gмог:могла; бы разыскать его? А когда сделаешь это, пожалуйста, попроси его вернуться обратно в Храм.','Найдите посвященного Клондацка в Кварцитовой впадине, что в Подземье.','Привет, парнишка! Не мог бы ты мне помочь?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Где Клондацк?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мой посвященный гоблин ушел некоторое время назад. Его зовут Клондацк.$b$bЯ отправила его наблюдать за камнедерами к юго-западу от Кварцитовой впадины. Может быть, ты $gмог:могла; бы разыскать его? А когда сделаешь это, пожалуйста, попроси его вернуться обратно в Храм.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите посвященного Клондацка в Кварцитовой впадине, что в Подземье.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Привет, парнишка! Не мог бы ты мне помочь?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26410,'Заживляющее взрывчатое вещество','Соберите 5 порций кварцитовой смолы.','Какое везение, что я – большой знаток всех гремучих алхимических веществ.$B$BВпрочем, сами по себе они не загорятся.','Смолы нужно немного. Но эти камнедеры довольно опасны.','Вернитесь к посвященному Клондацку в Кварцитовую впадину, что в Подземье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Заживляющее взрывчатое вещество',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 5 порций кварцитовой смолы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Какое везение, что я – большой знаток всех гремучих алхимических веществ.$B$BВпрочем, сами по себе они не загорятся.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Смолы нужно немного. Но эти камнедеры довольно опасны.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к посвященному Клондацку в Кварцитовую впадину, что в Подземье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26411,'Приложить и прижечь','Ну вот, приложи это вещество к его ранам. Если он сможет пережить прижигающий эффект заживляющего взрывчатого вещества, то излечится.$b$bДумаю так.','Воспользуйтесь заживляющим взрывчатым веществом, чтобы вылечить Флинта Железную Мантию.','Похоже, что помогло. Он вот-вот должен прийти в себя.$B$BЯ же говорил тебе, что в алхимии мне равных нет!$B$BСмола у меня еще есть. Могу добавить ее в любой взрывчатый состав. Чего бы тебе хотелось?','Поговорите с посвященным Клондацком в Кварцитовой впадине, что в Подземье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приложить и прижечь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну вот, приложи это вещество к его ранам. Если он сможет пережить прижигающий эффект заживляющего взрывчатого вещества, то излечится.$b$bДумаю так.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь заживляющим взрывчатым веществом, чтобы вылечить Флинта Железную Мантию.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Похоже, что помогло. Он вот-вот должен прийти в себя.$B$BЯ же говорил тебе, что в алхимии мне равных нет!$B$BСмола у меня еще есть. Могу добавить ее в любой взрывчатый состав. Чего бы тебе хотелось?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с посвященным Клондацком в Кварцитовой впадине, что в Подземье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26412,'Сокровища клана Мош\'Огг','Скажи, тебе доводилось слыхать про огров? Один мой знакомый по имени Мок\'тардин шепнул тут, что в их в пещере хранится особо ценный магический артефакт. И сдается мне, что эта побрякушка стоит целое состояние. Скизи об этом больше знает, но и я запах денег за версту чую!$B$BСлушай внимательно: за огрским холмом есть какие-то развалины, вот там-то огры и сторожат сундук с сокровищем. Добудешь его?','Добудьте сокровище огров, хранящееся в руинах за холмом Мош\'Огг.','Вернитесь к Скизи Крюкоуху в Бамбалу, что в Северной Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сокровища клана Мош\'Огг',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Скажи, тебе доводилось слыхать про огров? Один мой знакомый по имени Мок\'тардин шепнул тут, что в их в пещере хранится особо ценный магический артефакт. И сдается мне, что эта побрякушка стоит целое состояние. Скизи об этом больше знает, но и я запах денег за версту чую!$B$BСлушай внимательно: за огрским холмом есть какие-то развалины, вот там-то огры и сторожат сундук с сокровищем. Добудешь его?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте сокровище огров, хранящееся в руинах за холмом Мош\'Огг.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Скизи Крюкоуху в Бамбалу, что в Северной Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26413,'Отведи его к заклинательнице земли','Он по-прежнему производит на меня впечатление чокнутого. В голове у него до сих пор должно звенеть.$b$bЛучше всего отвести его в Храм, может быть, заклинательница земли сможет что-то сделать для него.$b$bА я останусь здесь еще ненадолго и "понаблюдаю" за этими камнедерами.','Представьте Флинта Железную Мантию заклинательнице земли Еве в Храме Земли.','Какая честь для нас видеть здесь Флинта Железную Мантию. Я узнала, центральный фрагмент столпа мира находится у Отца-Скалы.$B$BМы обязаны найти все фрагменты. Разлом между нашими мирами все менее стабилен. Скоро он может стать настолько большим, справиться с ним станет не под силу даже могущественному Траллу.','Поговорите с заклинательницей земли Евой в Храме Земли в Подземье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отведи его к заклинательнице земли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Он по-прежнему производит на меня впечатление чокнутого. В голове у него до сих пор должно звенеть.$b$bЛучше всего отвести его в Храм, может быть, заклинательница земли сможет что-то сделать для него.$b$bА я останусь здесь еще ненадолго и "понаблюдаю" за этими камнедерами.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Представьте Флинта Железную Мантию заклинательнице земли Еве в Храме Земли.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Какая честь для нас видеть здесь Флинта Железную Мантию. Я узнала, центральный фрагмент столпа мира находится у Отца-Скалы.$B$BМы обязаны найти все фрагменты. Разлом между нашими мирами все менее стабилен. Скоро он может стать настолько большим, справиться с ним станет не под силу даже могущественному Траллу.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с заклинательницей земли Евой в Храме Земли в Подземье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26414,'Ловля светлоперого судака','Иногда я рыбачу просто для удовольствия. Обычно чтобы расслабиться, иногда – чтобы размяться. А для этого лучше всего подходит задеревенелый светлоперый судак. Эту рыбу ловят не для готовки, а чтобы показать свое мастерство. Светлоперый судак водится в Штормградском озере к северу от города. Ну что, попытаешь счастья?','Катрин Лиланд в Штормграде просит вас принести ей 8 задеревенелых светлоперых судаков.','Ну как, по силам была задачка?','Вернитесь к Робби Флею в Штормград.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ловля светлоперого судака',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Иногда я рыбачу просто для удовольствия. Обычно чтобы расслабиться, иногда – чтобы размяться. А для этого лучше всего подходит задеревенелый светлоперый судак. Эту рыбу ловят не для готовки, а чтобы показать свое мастерство. Светлоперый судак водится в Штормградском озере к северу от города. Ну что, попытаешь счастья?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Катрин Лиланд в Штормграде просит вас принести ей 8 задеревенелых светлоперых судаков.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как, по силам была задачка?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Робби Флею в Штормград.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (26415,'Questflag for Captain\'s Log') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Questflag for Captain\'s Log',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26416,'Вперед, в джунгли!','Командир отправил меня на поиски рекрутов, которые могли бы помочь в обороне лагеря Гром\'гол в Северной Тернистой долине. Ты знаешь, где это? Далеко-далеко, за Великим морем, на самом востоке Восточных королевств. Ты, кстати, вполне подходишь под описание наемника... Не хочешь ли на время покинуть эти края?$b$bЕсли да, то поговори с моим напарником Бортом в Оргриммаре. Он посадит тебя на дирижабль.$b$bДа, и передай ему пару слов от меня: "Воззль воззль". Именно так; он знает, о чем идет речь.','Разыщите Борта в Оргриммаре.','Ха! Подколола меня Кромула!$B$BКуда там тебе надо, в Тернистую долину? Ты правда туда собираешься?','Разыщите Борта в Оргриммаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вперед, в джунгли!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Командир отправил меня на поиски рекрутов, которые могли бы помочь в обороне лагеря Гром\'гол в Северной Тернистой долине. Ты знаешь, где это? Далеко-далеко, за Великим морем, на самом востоке Восточных королевств. Ты, кстати, вполне подходишь под описание наемника... Не хочешь ли на время покинуть эти края?$b$bЕсли да, то поговори с моим напарником Бортом в Оргриммаре. Он посадит тебя на дирижабль.$b$bДа, и передай ему пару слов от меня: "Воззль воззль". Именно так; он знает, о чем идет речь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите Борта в Оргриммаре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ха! Подколола меня Кромула!$B$BКуда там тебе надо, в Тернистую долину? Ты правда туда собираешься?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Разыщите Борта в Оргриммаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26417,'Северная Тернистая долина: павшая империя','Командующий Аггро\'гош ищет преданных воинов Орды для выполнения задания в Гром\'голе. Если ты $gготов:готова;, взбирайся на башню дирижаблей и садись в дирижабль до Гром\'гола. Да, все легче легкого!$B$BКроме шуток, в Тернистой долине сейчас есть чем заняться... там много чего творится, а катаклизм не так набедокурил, как, скажем... в Когтистых горах. Жаль, не могу с тобой пойти.','Явитесь с докладом к командиру Аггро\'гошу в лагерь Гром\'гол в Северной Тернистой долине.','Рад, что ты благополучно добрался! Ну что, займемся делом?','Явитесь с докладом к командиру Аггро\'гошу в лагерь Гром\'гол в Северной Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Северная Тернистая долина: павшая империя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Командующий Аггро\'гош ищет преданных воинов Орды для выполнения задания в Гром\'голе. Если ты $gготов:готова;, взбирайся на башню дирижаблей и садись в дирижабль до Гром\'гола. Да, все легче легкого!$B$BКроме шуток, в Тернистой долине сейчас есть чем заняться... там много чего творится, а катаклизм не так набедокурил, как, скажем... в Когтистых горах. Жаль, не могу с тобой пойти.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Явитесь с докладом к командиру Аггро\'гошу в лагерь Гром\'гол в Северной Тернистой долине.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Рад, что ты благополучно добрался! Ну что, займемся делом?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Явитесь с докладом к командиру Аггро\'гошу в лагерь Гром\'гол в Северной Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26418,'Панцирь Шадры','Надо добыть еще одну часть, и тогда у нас будет все необходимое.$B$BПанцирь Шадры хранится у последней ее верховной жрицы, Квиаги Хранительницы. Она стоит на вершине алтаря Зула, и ее охраняют ревнители-фанатики.$B$BВсе просто и ясно, да? Поднимись на вершину алтаря и отсеки ей голову. А потом принеси мне панцирь, и мы наконец-то сможем призвать Шадру.','Убейте Квиагу Хранительницу и заберите панцирь Шадры.','Вернитесь к темному священнику Марналу на исследовательскую станцию Хири\'вата, что во Внутренних землях.','Квиага – преданная ученица Шадры. Она не расстанется с панцирем без боя.','Квиага Хранительница') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Панцирь Шадры',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Надо добыть еще одну часть, и тогда у нас будет все необходимое.$B$BПанцирь Шадры хранится у последней ее верховной жрицы, Квиаги Хранительницы. Она стоит на вершине алтаря Зула, и ее охраняют ревнители-фанатики.$B$BВсе просто и ясно, да? Поднимись на вершину алтаря и отсеки ей голову. А потом принеси мне панцирь, и мы наконец-то сможем призвать Шадру.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Квиагу Хранительницу и заберите панцирь Шадры.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к темному священнику Марналу на исследовательскую станцию Хири\'вата, что во Внутренних землях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Квиага – преданная ученица Шадры. Она не расстанется с панцирем без боя.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Квиага Хранительница',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26419,'Шадра – королева пауков','<Земля начинает трястись, а озеро – волноваться, когда идол оказывается на алтаре. Шадра приходит в этот мир!>','Убейте Шадру – королеву пауков.','Вернитесь к темному священнику Марналу в исследовательский лагерь Хири\'вата, что во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Шадра – королева пауков',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Земля начинает трястись, а озеро – волноваться, когда идол оказывается на алтаре. Шадра приходит в этот мир!>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Шадру – королеву пауков.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к темному священнику Марналу в исследовательский лагерь Хири\'вата, что во Внутренних землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26420,'Накопаем червей','Рыбакам привет! Мне тут Арнольд сказал, ты ищешь рыбное место, могу присоветовать. К северу от Штормграда есть прекрасное местечко – Пруд Оливии.$B$BВ пруду круглый год видимо-невидимо хрустального окуня, но поймать его не так-то просто. Он клюет только на особую приманку... земляных червей-переростков. Поищи на берегу возле пруда – там вдосталь этой наживки.','Отыщите земляного червя-переростка возле Пруда Оливии и поймайте на эту наживку хрустального окуня. Хрустальный окунь водится в Пруду Оливии к северу от Штормграда.','Ну как клев? Хороша наживка?','Вернитесь с уловом в Штормград к Катрин Лиланд.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Накопаем червей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Рыбакам привет! Мне тут Арнольд сказал, ты ищешь рыбное место, могу присоветовать. К северу от Штормграда есть прекрасное местечко – Пруд Оливии.$B$BВ пруду круглый год видимо-невидимо хрустального окуня, но поймать его не так-то просто. Он клюет только на особую приманку... земляных червей-переростков. Поищи на берегу возле пруда – там вдосталь этой наживки.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщите земляного червя-переростка возле Пруда Оливии и поймайте на эту наживку хрустального окуня. Хрустальный окунь водится в Пруду Оливии к северу от Штормграда.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как клев? Хороша наживка?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь с уловом в Штормград к Катрин Лиланд.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26421,'Встретиться с главным механиком','Представьтесь главному механику Меггакруту в Новом Городе Механиков.','Представьтесь главному механику Меггакруту в Новом Городе Механиков.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Встретиться с главным механиком',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Представьтесь главному механику Меггакруту в Новом Городе Механиков.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Представьтесь главному механику Меггакруту в Новом Городе Механиков.',`completedtext_loc8`);
