INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26426,'Жестокий ветер','Найдите Фелсена Выносливого и следуйте его указаниям, чтобы добраться до входа в Гремящие глубины.','Найдите вход в Гремящие глубины.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жестокий ветер',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Фелсена Выносливого и следуйте его указаниям, чтобы добраться до входа в Гремящие глубины.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Найдите вход в Гремящие глубины.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26427,'Ни команды, ни капитана','Не знаю, на чьей ты стороне, но ты не выглядишь, как $gодин:одна; из... них.$b$bЯ не очень хорошо понимаю, что произошло. Я проспал ужин, а когда проснулся, на корабле было полно мертвецов и убийц.$b$bНе знаю, собираешься ли ты убить меня, но я не буду создавать тебе проблем.$b$b<Мади показывает на рану в животе. Его внутренности не на месте.>$b$bЯ больше не могу управлять кораблем. От ранения в живот моментально не умирают. Принеси мне веревок и немного рома... нет, виски.','Принесите первому помощнику Мади бутылку виски и моток веревки.','Хорошо, помоги мне, привяжи меня к рулю.$B$B<Мади делает глоток из бутылки.>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ни команды, ни капитана',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не знаю, на чьей ты стороне, но ты не выглядишь, как $gодин:одна; из... них.$b$bЯ не очень хорошо понимаю, что произошло. Я проспал ужин, а когда проснулся, на корабле было полно мертвецов и убийц.$b$bНе знаю, собираешься ли ты убить меня, но я не буду создавать тебе проблем.$b$b<Мади показывает на рану в животе. Его внутренности не на месте.>$b$bЯ больше не могу управлять кораблем. От ранения в живот моментально не умирают. Принеси мне веревок и немного рома... нет, виски.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите первому помощнику Мади бутылку виски и моток веревки.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо, помоги мне, привяжи меня к рулю.$B$B<Мади делает глоток из бутылки.>',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26428,'Грабь награбленное','Воровка! Свинья! Кената все еще жива, ее семья живет и процветает, а я страдаю. Вот уж действительно Отрекшаяся!$B$BВсю мою семью забрала чума. Все наше имение тоже разорили во время войны. А теперь она и ее мерзкие дети имели наглость похитить у меня последние ценные вещи.$B$BСами вещи мне уже не нужны. Теперь я жажду мести!$B$BУбей этих проходимцев! Ступай в усадьбу Дабири в Арати, это на северо-востоке от Опорного пункта.','Добудьте головы Кенаты Дабири, Фарбела Дабири и Марселя Дабири.','Я кланяюсь тебе до земли в знак признательности за то, что ты совершил акт возмездия.$B$BЗная, что эта корова мертва, а ее потомки не будут топтать землю Азерота, могу потратить свои силы на что-нибудь более продуктивное. Надеюсь, прикончив их, ты ограбил усадьбу.','Убей их всех и принеси мне их головы!','Вернитесь к Генви Кэллоу в Удел Галена на Нагорье Арати.','Она заплатит своей головой!','Кената Дабири') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Грабь награбленное',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Воровка! Свинья! Кената все еще жива, ее семья живет и процветает, а я страдаю. Вот уж действительно Отрекшаяся!$B$BВсю мою семью забрала чума. Все наше имение тоже разорили во время войны. А теперь она и ее мерзкие дети имели наглость похитить у меня последние ценные вещи.$B$BСами вещи мне уже не нужны. Теперь я жажду мести!$B$BУбей этих проходимцев! Ступай в усадьбу Дабири в Арати, это на северо-востоке от Опорного пункта.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте головы Кенаты Дабири, Фарбела Дабири и Марселя Дабири.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я кланяюсь тебе до земли в знак признательности за то, что ты совершил акт возмездия.$B$BЗная, что эта корова мертва, а ее потомки не будут топтать землю Азерота, могу потратить свои силы на что-нибудь более продуктивное. Надеюсь, прикончив их, ты ограбил усадьбу.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Убей их всех и принеси мне их головы!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Генви Кэллоу в Удел Галена на Нагорье Арати.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Она заплатит своей головой!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Кената Дабири',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26429,'Сокрушить Сухокожих','Тролли из племени Сухокожих и огры из клана Тяжелого Кулака объединились, чтобы изгнать нас из этих земель, но мы не собираемся подчиняться ни им, ни кому-то другому. Мы убьем их и тем самым покажем им, что здесь и наш дом тоже.$b$bТролли от нас бежали. Огры были бы рады сожрать нас и спать на наших шкурах, если бы мы им только позволили, – но этому не бывать.$b$bМы атакуем троллей из племени Сухокожих к югу отсюда. Убей их столько, сколько сможешь, и возвращайся только тогда, когда их поселения будут залиты кровью.','Убейте 10 метателей топоров из племени Сухокожих, 10 охотников за головами из племени Сухокожих и 8 знахарей из племени Сухокожих.','Вернитесь к Драму Желчному в Павший Молот на Нагорье Арати.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сокрушить Сухокожих',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тролли из племени Сухокожих и огры из клана Тяжелого Кулака объединились, чтобы изгнать нас из этих земель, но мы не собираемся подчиняться ни им, ни кому-то другому. Мы убьем их и тем самым покажем им, что здесь и наш дом тоже.$b$bТролли от нас бежали. Огры были бы рады сожрать нас и спать на наших шкурах, если бы мы им только позволили, – но этому не бывать.$b$bМы атакуем троллей из племени Сухокожих к югу отсюда. Убей их столько, сколько сможешь, и возвращайся только тогда, когда их поселения будут залиты кровью.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 метателей топоров из племени Сухокожих, 10 охотников за головами из племени Сухокожих и 8 знахарей из племени Сухокожих.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Драму Желчному в Павший Молот на Нагорье Арати.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (26430,'Деревня Сломанного Клыка','Отправляйтесь в деревню Сломанного Клыка во Внутренних Землях и поговорите со старейшиной Сломанным Клыком.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Деревня Сломанного Клыка',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в деревню Сломанного Клыка во Внутренних Землях и поговорите со старейшиной Сломанным Клыком.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26431,'Археология','Accept this quest to find archaeology points on your map!','Accept this quest to find archaeology points on your map!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Археология',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Accept this quest to find archaeology points on your map!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Accept this quest to find archaeology points on your map!',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26432,'Падение Джинта\'Алора','Нам не только дворфы мешают, $gбратишка:сестренка;. Я присматриваю за деревней, а моя подруга, старейшина племени Сломанного Клыка, повела наших воинов против племени Порочной Ветви.$B$BОни убили наших братьев, а меня даже в плен забрали! Такое не должно повториться! На этот раз Джинта\'Алор падет под нашим натиском.$B$BИди в Джинта\'Алор и поговори с моей подругой. Она в лагере возле входа в город.','Найдите старейшину племени Сломанного Клыка у Джинта\'Алора во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Падение Джинта\'Алора',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нам не только дворфы мешают, $gбратишка:сестренка;. Я присматриваю за деревней, а моя подруга, старейшина племени Сломанного Клыка, повела наших воинов против племени Порочной Ветви.$B$BОни убили наших братьев, а меня даже в плен забрали! Такое не должно повториться! На этот раз Джинта\'Алор падет под нашим натиском.$B$BИди в Джинта\'Алор и поговори с моей подругой. Она в лагере возле входа в город.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите старейшину племени Сломанного Клыка у Джинта\'Алора во Внутренних землях.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26433,'Святая вода ясности','Скизи предупредил меня о твоем приходе. Ладно, сейчас посмотрим, что ты тут $gнашел:нашла;.$B$BДля начала мне нужно, чтобы ты $gдобыл:добыла; святую воду ясности. На юго-востоке от нас находится святилище наг, в котором святая вода столь чиста, свежа и сладка на вкус, что когда делаешь хоть глоточек, ум проясняется и становится виден путь.$B$BПравда, здорово?$B$BНабери ее в роднике Нек\'мани у подножия горы в лагере наг. Удачи!','Наберите святой воды ясности из родника Нек\'мани на мысе Тернистой долины.','<Гоблин залпом выпивает воду.>$B$BАх!.. Знаешь, как трудно добыть свежую водичку в Тернистой долине? Понятно, почему наги так рьяно охраняют свое святилище!$B$BА, да... Твой артефакт и ясность. Ясность...$B$BМеня вштырило!','<Флюм поднимает уши при вашем приближении.>$B$BСвятая вода ясности? Здесь?!','Вернитесь к Флюму Гряззиксу в Укрытие Кофельнагель на мысе Тернистой долины.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Святая вода ясности',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Скизи предупредил меня о твоем приходе. Ладно, сейчас посмотрим, что ты тут $gнашел:нашла;.$B$BДля начала мне нужно, чтобы ты $gдобыл:добыла; святую воду ясности. На юго-востоке от нас находится святилище наг, в котором святая вода столь чиста, свежа и сладка на вкус, что когда делаешь хоть глоточек, ум проясняется и становится виден путь.$B$BПравда, здорово?$B$BНабери ее в роднике Нек\'мани у подножия горы в лагере наг. Удачи!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Наберите святой воды ясности из родника Нек\'мани на мысе Тернистой долины.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Гоблин залпом выпивает воду.>$B$BАх!.. Знаешь, как трудно добыть свежую водичку в Тернистой долине? Понятно, почему наги так рьяно охраняют свое святилище!$B$BА, да... Твой артефакт и ясность. Ясность...$B$BМеня вштырило!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Флюм поднимает уши при вашем приближении.>$B$BСвятая вода ясности? Здесь?!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Флюму Гряззиксу в Укрытие Кофельнагель на мысе Тернистой долины.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26434,'Изначальные реагенты силы','Теперь все понятно... чтобы распознать этот таинственный талисман, нужно получить некие редкие и ценные предметы. Эти изначальные реагенты силы, собранные вместе, откроют нам происхождение сокровища.$b$bОтправляйся на север, к западной части арены Гурубаши, и поохоться на кошек, которые рыщут в джунглях. Их пушистые шкурки помогут нам узнать правду!','Добудьте 4 мягкие тигриные шкуры и 4 бархатистые шкуры пантеры.','Вернитесь к Флюму Гряззиксу в Укрытие Кофельнагель на мысе Тернистой долины.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Изначальные реагенты силы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь все понятно... чтобы распознать этот таинственный талисман, нужно получить некие редкие и ценные предметы. Эти изначальные реагенты силы, собранные вместе, откроют нам происхождение сокровища.$b$bОтправляйся на север, к западной части арены Гурубаши, и поохоться на кошек, которые рыщут в джунглях. Их пушистые шкурки помогут нам узнать правду!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 4 мягкие тигриные шкуры и 4 бархатистые шкуры пантеры.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Флюму Гряззиксу в Укрытие Кофельнагель на мысе Тернистой долины.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26435,'Лжец и отпетый мошенник','Понятия не имею, что это такое. Даже больше скажу – не представляю, где это можно узнать!$B$BИ вообще – почему именно ко мне обратились с этим вопросом?$B$BМне хотелось пить, я попросил воды. А потом поинтересовался драгоценностями и мехами для... для своей девушки.$B$BОднако я, по крайней мере, могу указать вам, в каком направлении двигаться. Гарли Легкая Наездница из Пиратской Бухты работает в Реликварии. Может, чем и пособит.','Отнесите открытый сундук сокровищ клана Мош\'Огг Гарли Легкой Наезднице в Пиратскую Бухту у мыса Тернистой долины.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лжец и отпетый мошенник',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Понятия не имею, что это такое. Даже больше скажу – не представляю, где это можно узнать!$B$BИ вообще – почему именно ко мне обратились с этим вопросом?$B$BМне хотелось пить, я попросил воды. А потом поинтересовался драгоценностями и мехами для... для своей девушки.$B$BОднако я, по крайней мере, могу указать вам, в каком направлении двигаться. Гарли Легкая Наездница из Пиратской Бухты работает в Реликварии. Может, чем и пособит.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите открытый сундук сокровищ клана Мош\'Огг Гарли Легкой Наезднице в Пиратскую Бухту у мыса Тернистой долины.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26436,'Вросший в землю','Разыщите Кора Невозмутимого в Дрожащих Вершинах.','Диамант говорит, что тебе можно доверять. Диамант мудр и терпелив, так что я позволю тебе показать, на что ты способен.$B$BМне бы пригодилась пара… подвижных рук.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вросший в землю',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите Кора Невозмутимого в Дрожащих Вершинах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Диамант говорит, что тебе можно доверять. Диамант мудр и терпелив, так что я позволю тебе показать, на что ты способен.$B$BМне бы пригодилась пара… подвижных рук.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26437,'Кристальная чистота','В Дрожащих Вершинах есть кристаллы. Белые, меловые кристаллы. Мы втираем их в кожу. Для очищения.$b$bЯ больше не могу шагать по горам. Я стал единым целым с землей. В этом много преимуществ, но теперь я больше не могу добывать для себя эти кристаллы.$b$bПринеси их мне, я стану сильнее. Береги кристаллы от камнедеров. И от моих сыновей. Они должны быть только для меня.','Соберите 8 меловых кристалловидных образований.','Ах… живительная энергия. Спасибо тебе, смертный.','Вернитесь к Кору Невозмутимому в Дрожащие Вершины, что в Подземье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кристальная чистота',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В Дрожащих Вершинах есть кристаллы. Белые, меловые кристаллы. Мы втираем их в кожу. Для очищения.$b$bЯ больше не могу шагать по горам. Я стал единым целым с землей. В этом много преимуществ, но теперь я больше не могу добывать для себя эти кристаллы.$b$bПринеси их мне, я стану сильнее. Береги кристаллы от камнедеров. И от моих сыновей. Они должны быть только для меня.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 меловых кристалловидных образований.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ах… живительная энергия. Спасибо тебе, смертный.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кору Невозмутимому в Дрожащие Вершины, что в Подземье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26438,'Угроза','Камнедеры беснуются от голода. Раньше они тихо и спокойно рылись в земле. Теперь им не утолить свой голод. Они стали смертельно опасными.$b$bКамнедеры атакуют моих сыновей. Набрасываются на них. Убивают их. Это нужно прекратить.$b$bУбей камнедеров. Земле от них никакой пользы. Никто и не заметит, если они исчезнут. Спаси моих сыновей. Уничтожай всех камнедеров, какие тебе встретятся.','Убейте 12 яшмоголовых камнедеров.','Вернитесь к Кору Невозмутимому в Дрожащие Вершины, что в Подземье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Угроза',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Камнедеры беснуются от голода. Раньше они тихо и спокойно рылись в земле. Теперь им не утолить свой голод. Они стали смертельно опасными.$b$bКамнедеры атакуют моих сыновей. Набрасываются на них. Убивают их. Это нужно прекратить.$b$bУбей камнедеров. Земле от них никакой пользы. Никто и не заметит, если они исчезнут. Спаси моих сыновей. Уничтожай всех камнедеров, какие тебе встретятся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 яшмоголовых камнедеров.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кору Невозмутимому в Дрожащие Вершины, что в Подземье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26439,'Сформировать заново','Помогите 6 спящим каменным элементалям заново сформироваться.','Вернитесь к Беррациту в Дрожащие Вершины, что в Подземье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сформировать заново',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Помогите 6 спящим каменным элементалям заново сформироваться.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Беррациту в Дрожащие Вершины, что в Подземье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26440,'Приставучий','<Похоже, вы понравились одному крошечному элементалю.>$b$bКарис... карстр... кристалл?<Камешек выжидательно смотрит на вас.>$b$b<Вы действительно видели большие скопления кристаллов в Дрожащих Вершинах. Может быть, надо отвести его туда?>','Отведите Камешка к большому скоплению кристаллов в Дрожащих Вершинах.','<Камни в теле Камешка весело подпрыгивают. Похоже, он очень признателен.>','<Камешек выжидательно смотрит на вас снизу вверх.>','Поговорите с Камешком. В последний раз вы видели его в Дрожащих Вершинах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приставучий',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Похоже, вы понравились одному крошечному элементалю.>$b$bКарис... карстр... кристалл?<Камешек выжидательно смотрит на вас.>$b$b<Вы действительно видели большие скопления кристаллов в Дрожащих Вершинах. Может быть, надо отвести его туда?>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отведите Камешка к большому скоплению кристаллов в Дрожащих Вершинах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Камни в теле Камешка весело подпрыгивают. Похоже, он очень признателен.>',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Камешек выжидательно смотрит на вас снизу вверх.>',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Камешком. В последний раз вы видели его в Дрожащих Вершинах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26441,'Такой большой, такой круглый...','<Чем-то взволнованный, Камешек озирается по сторонам. После нескольких секунд замешательства он останавливает на вас взгляд своих больших сияющих глаз-самоцветов.>$b$bГоло... голодный...$b$b<Он так смотрит, что невозможно оставаться $gравнодушным:равнодушной;. Может быть, Кор знает, что любят есть такие маленькие элементали?>','Поговорите с Кором, чтобы узнать, чем можно накормить Камешка.','У тебя появился друг, да?$B$BТы уверен, что хочешь покормить его? После этого он может к тебе привязаться.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Такой большой, такой круглый...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Чем-то взволнованный, Камешек озирается по сторонам. После нескольких секунд замешательства он останавливает на вас взгляд своих больших сияющих глаз-самоцветов.>$b$bГоло... голодный...$b$b<Он так смотрит, что невозможно оставаться $gравнодушным:равнодушной;. Может быть, Кор знает, что любят есть такие маленькие элементали?>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Кором, чтобы узнать, чем можно накормить Камешка.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','У тебя появился друг, да?$B$BТы уверен, что хочешь покормить его? После этого он может к тебе привязаться.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26442,'Скальный омар','Если бы перед смертью я могла заказать какой-нибудь деликатес, я бы непременно выбрала свежие хвосты омара. Прямо не могу устоять перед ними! Мы тут недавно расставили ловушки на омаров в порту Штормграда. Не сходишь проверить?$B$BДа, вот еще что: остерегайся акул. Они там злобные...','Соберите 6 скальных омаров из ловушек под пристанью в порту Штормграда. Остерегайтесь акул!','Акулам ты явно не попался. А омары в ловушках были?','Принесите омаров Катрин Лиланд в Штормград.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Скальный омар',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если бы перед смертью я могла заказать какой-нибудь деликатес, я бы непременно выбрала свежие хвосты омара. Прямо не могу устоять перед ними! Мы тут недавно расставили ловушки на омаров в порту Штормграда. Не сходишь проверить?$B$BДа, вот еще что: остерегайся акул. Они там злобные...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 6 скальных омаров из ловушек под пристанью в порту Штормграда. Остерегайтесь акул!',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Акулам ты явно не попался. А омары в ловушках были?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите омаров Катрин Лиланд в Штормград.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26443,'Демонические планы','Этот пергамент выронил демон, но что странно – он написан на Всеобщем! В нем упоминаются два имени – Диатор и Горганнон. Эти два повелителя Ужаса, пользующиеся дурной репутацией даже среди себе подобных, управляют демонами в здешних местах.$B$BВ плане подробно описывается подготовка нападения демонов на Лесную Песнь на севере отсюда – место, где основали свое поселение дренеи.$B$BВозможно, это заинтересует воздаятеля Ведаара с лесозаготовок Песни Войны?','Доставьте демонические планы воздаятелю Ведаару на лесозаготовки Песни Войны в Ясеневый лес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Демонические планы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этот пергамент выронил демон, но что странно – он написан на Всеобщем! В нем упоминаются два имени – Диатор и Горганнон. Эти два повелителя Ужаса, пользующиеся дурной репутацией даже среди себе подобных, управляют демонами в здешних местах.$B$BВ плане подробно описывается подготовка нападения демонов на Лесную Песнь на севере отсюда – место, где основали свое поселение дренеи.$B$BВозможно, это заинтересует воздаятеля Ведаара с лесозаготовок Песни Войны?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте демонические планы воздаятелю Ведаару на лесозаготовки Песни Войны в Ясеневый лес.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26444,'Уничтожить Легион!','Я не потерплю их присутствия в нашем мире! Пылающий Легион чуть не уничтожил нашу расу, и мы бежали сюда, чтобы построить себе новый дом в новом мире. Теперь они снова пришли. И мы снова отступили, и снова, и снова!$B$BДовольно! $B$BОстатки Легиона затаились к югу от холма Демонического Огня, Каньона Гибели Демона и Гряды Гибели Демона. Это все, что осталось от полчищ, что некогда вторглись в этот мир.$B$BСтупай же и перебей сколько сможешь, пока еще не поздно!','Убейте 15 демонов на холме Демонического Огня, в каньоне Гибели Демона и гряде Гибели Демона.','Вернитесь к воздаятелю Ведаару на лесопилку Песни Войны, что в Ясеневом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уничтожить Легион!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я не потерплю их присутствия в нашем мире! Пылающий Легион чуть не уничтожил нашу расу, и мы бежали сюда, чтобы построить себе новый дом в новом мире. Теперь они снова пришли. И мы снова отступили, и снова, и снова!$B$BДовольно! $B$BОстатки Легиона затаились к югу от холма Демонического Огня, Каньона Гибели Демона и Гряды Гибели Демона. Это все, что осталось от полчищ, что некогда вторглись в этот мир.$B$BСтупай же и перебей сколько сможешь, пока еще не поздно!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 15 демонов на холме Демонического Огня, в каньоне Гибели Демона и гряде Гибели Демона.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к воздаятелю Ведаару на лесопилку Песни Войны, что в Ясеневом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26445,'Больше никогда!','$n, на твои плечи ложится обязанность сорвать нападение Пылающего Легиона! Ты $Gдолжен:должна; уничтожить их предводителей. Остальные демоны, по большей части, – безмозглые твари. $B$BГорганнона ты найдешь в Каньоне Гибели демона к югу за Холмом Демонического Огня, близ сломанного, парящего копья Маннорота.$B$BДиатор Ищейка засел где-то в логове в холме над Грядой Гибели Демона. Чтобы найти эту гряду, отыщи уступ, по которому можно подняться из Каньона Гибели демона близ памятника Грому Адскому Крику.$B$BПринеси мне их оружие.','Добудьте пламенеющее лезвие Горганнона и желчное копье Ищейки.','Вернитесь к воздаятелю Ведаару на лесопилку Песни Войны, что в Ясеневом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Больше никогда!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, на твои плечи ложится обязанность сорвать нападение Пылающего Легиона! Ты $Gдолжен:должна; уничтожить их предводителей. Остальные демоны, по большей части, – безмозглые твари. $B$BГорганнона ты найдешь в Каньоне Гибели демона к югу за Холмом Демонического Огня, близ сломанного, парящего копья Маннорота.$B$BДиатор Ищейка засел где-то в логове в холме над Грядой Гибели Демона. Чтобы найти эту гряду, отыщи уступ, по которому можно подняться из Каньона Гибели демона близ памятника Грому Адскому Крику.$B$BПринеси мне их оружие.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте пламенеющее лезвие Горганнона и желчное копье Ищейки.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к воздаятелю Ведаару на лесопилку Песни Войны, что в Ясеневом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26446,'Возрождение Холма Демонического Огня','Посадите 8 древесных саженцев в кучи плодородной земли.','Добро. Хотя много твоих годов утечет прежде, чем эти саженцы превратятся в Древних, но со временем они помогут нам в борьбе против врагов Ясеневого леса.','Вернитесь к Кривокрону на лесопилку Песни Войны, что в Ясеневом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возрождение Холма Демонического Огня',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Посадите 8 древесных саженцев в кучи плодородной земли.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Добро. Хотя много твоих годов утечет прежде, чем эти саженцы превратятся в Древних, но со временем они помогут нам в борьбе против врагов Ясеневого леса.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кривокрону на лесопилку Песни Войны, что в Ясеневом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (26447,'Демонические планы') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Демонические планы',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26448,'Уничтожить Легион!','Остатки демонического Пылающего Легиона слишком долго надоедали нам.$B$BХватит!$B$BЭти демоны лезут от Холма Демонического Огня, Каньона Гибели Демона и Гряды Гибели Демона на востоке.$B$BСтупай и уничтожь их сколько сумеешь – и покроешь славой и себя, и Орду!','Убейте 15 любых демонов на холме Демонического Огня, в каньоне Гибели Демона и гряде Гибели Демона.','Это куда лучше! Нет ничего достойнее, чем очищать наш мир от демонов. Да и противники они стоящие, не то что эти дохляки из Альянса.','Поговорите с Валушей на Заставе Расщепленного Дерева.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уничтожить Легион!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Остатки демонического Пылающего Легиона слишком долго надоедали нам.$B$BХватит!$B$BЭти демоны лезут от Холма Демонического Огня, Каньона Гибели Демона и Гряды Гибели Демона на востоке.$B$BСтупай и уничтожь их сколько сумеешь – и покроешь славой и себя, и Орду!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 15 любых демонов на холме Демонического Огня, в каньоне Гибели Демона и гряде Гибели Демона.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это куда лучше! Нет ничего достойнее, чем очищать наш мир от демонов. Да и противники они стоящие, не то что эти дохляки из Альянса.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Валушей на Заставе Расщепленного Дерева.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26449,'Больше никогда!','$n, сделай так, чтобы эта атака Пылающего Легиона сорвалась! Иди и убей этих повелителей Ужаса! Остальные демоны, кроме них – по большей части безмозглые твари. $B$BГорганнона ты найдешь в Каньоне Гибели Демона к югу за Холмом Демонического Огня, близ сломанного, парящего копья Маннорота.$B$BДиатор Ищейка засел где-то в логове в холме над Грядой Гибели Демона. Принеси мне их оружие в доказательство твоей победы.','Добудьте пламенеющее лезвие Горганнона и желчное копье Ищейки.','Вернитесь к Валуше на Заставу Расщепленного Дерева, что в Ясеневом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Больше никогда!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, сделай так, чтобы эта атака Пылающего Легиона сорвалась! Иди и убей этих повелителей Ужаса! Остальные демоны, кроме них – по большей части безмозглые твари. $B$BГорганнона ты найдешь в Каньоне Гибели Демона к югу за Холмом Демонического Огня, близ сломанного, парящего копья Маннорота.$B$BДиатор Ищейка засел где-то в логове в холме над Грядой Гибели Демона. Принеси мне их оружие в доказательство твоей победы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте пламенеющее лезвие Горганнона и желчное копье Ищейки.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Валуше на Заставу Расщепленного Дерева, что в Ясеневом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26450,'Если они собираются просто оставить это на земле...','Я тут вот о чем подумала, $n. Эти наги... у них ведь не только водорослей полно. Вокруг святилищ, в песке, под деревьями валяется множество статуэток. И они им совсем НЕ НУЖНЫ!$B$BА мне бы пригодились!.. Я бы... скажем, расставила их по лагерю, чтобы стало уютнее. Все лучше, чем вонючие останки динозавров. Можно пустить на сувениры.$B$BМожно их опять тем же нагам продать, в конце концов!$B$BПочему б тебе не пойти и не подобрать пару-другую статуэток, пока я тут придумываю, как ими лучше распорядиться?','Добудьте 6 нагских идолов с Южного Гибельного Берега на мысе Тернистой долины.','Вернитесь к Хамми Кофельнагель в Укрытие Кофельнагель на мысе Тернистой долины.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Если они собираются просто оставить это на земле...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я тут вот о чем подумала, $n. Эти наги... у них ведь не только водорослей полно. Вокруг святилищ, в песке, под деревьями валяется множество статуэток. И они им совсем НЕ НУЖНЫ!$B$BА мне бы пригодились!.. Я бы... скажем, расставила их по лагерю, чтобы стало уютнее. Все лучше, чем вонючие останки динозавров. Можно пустить на сувениры.$B$BМожно их опять тем же нагам продать, в конце концов!$B$BПочему б тебе не пойти и не подобрать пару-другую статуэток, пока я тут придумываю, как ими лучше распорядиться?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 6 нагских идолов с Южного Гибельного Берега на мысе Тернистой долины.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хамми Кофельнагель в Укрытие Кофельнагель на мысе Тернистой долины.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26451,'Арена Гурубаши: все против всех!','Эта арена не похожа на другие. Тут не бывает друзей. Союзы создаются и распадаются в мгновение ока. Орда против Альянса, Альянс против Альянса, Орда против Орды... Тут возможно все.$B$BВозьми этот боевой штандарт, |3-6($r), и водрузи его на середине арены, чтобы начать бой. Победи противника и возвращайся ко мне.$B$BДержи ухо востро, |3-6($r). На арене Гурубаши может случиться что угодно.','Установите на ринге Арены флаг вызова Гурубаши и победите соперника, вышедшего на бой.','Вернитесь к каменному стражу Кудлатой Шкуре на Большую арену на мысе Тернистой долины.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Арена Гурубаши: все против всех!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эта арена не похожа на другие. Тут не бывает друзей. Союзы создаются и распадаются в мгновение ока. Орда против Альянса, Альянс против Альянса, Орда против Орды... Тут возможно все.$B$BВозьми этот боевой штандарт, |3-6($r), и водрузи его на середине арены, чтобы начать бой. Победи противника и возвращайся ко мне.$B$BДержи ухо востро, |3-6($r). На арене Гурубаши может случиться что угодно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Установите на ринге Арены флаг вызова Гурубаши и победите соперника, вышедшего на бой.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к каменному стражу Кудлатой Шкуре на Большую арену на мысе Тернистой долины.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26452,'Вызов Гурубаши','$GВернулся:Вернулась;? Значит, тебя снова потянуло на арену. Что ж, отлично.$B$BВозьми этот боевой штандарт и установи на арене. Когда одолеешь вызванного на бой соперника, возвращайся ко мне.$B$BБудь начеку, |3-6($r). На Арене Гурубаши может случиться все что угодно.','Установите на ринге Арены флаг вызова Гурубаши и победите соперника, вышедшего на бой.','Вернитесь к каменному стражу Кудлатой Шкуре на Большую арену на мысе Тернистой долины.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вызов Гурубаши',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$GВернулся:Вернулась;? Значит, тебя снова потянуло на арену. Что ж, отлично.$B$BВозьми этот боевой штандарт и установи на арене. Когда одолеешь вызванного на бой соперника, возвращайся ко мне.$B$BБудь начеку, |3-6($r). На Арене Гурубаши может случиться все что угодно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Установите на ринге Арены флаг вызова Гурубаши и победите соперника, вышедшего на бой.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к каменному стражу Кудлатой Шкуре на Большую арену на мысе Тернистой долины.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26453,'Рука помощи','Мой народ принялся за важное дело в восточной части Ясеневого леса при поддержке и помощи калдорай.$B$BПод руководством архитектора Немоса и воздаятеля Ведаара они восстанавливают древний форт ночных эльфов. Это непростая задача, $n, ибо кругом много врагов. Я знаю, что архитектор Немос и его сторонники в Лесной Песни будут благодарны любой помощи, и он просил меня присылать к нему всякого, кого это заинтересует.$B$BЕсли хочешь отправиться туда, окликни меня еще раз, и я организую тебе транспорт.','Отправляйтесь в Лесную Песнь и поговорите с архитектором Немосом.$B$BОбратитесь к воздаятельнице Паланааре, если вам требуется транспорт.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рука помощи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мой народ принялся за важное дело в восточной части Ясеневого леса при поддержке и помощи калдорай.$B$BПод руководством архитектора Немоса и воздаятеля Ведаара они восстанавливают древний форт ночных эльфов. Это непростая задача, $n, ибо кругом много врагов. Я знаю, что архитектор Немос и его сторонники в Лесной Песни будут благодарны любой помощи, и он просил меня присылать к нему всякого, кого это заинтересует.$B$BЕсли хочешь отправиться туда, окликни меня еще раз, и я организую тебе транспорт.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Лесную Песнь и поговорите с архитектором Немосом.$B$BОбратитесь к воздаятельнице Паланааре, если вам требуется транспорт.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26454,'Напрасные усилия','Добро пожаловать в Лесную Песнь, |3-6($c). Там, где ныне стоят палатки, однажды вырастут дома, но для этого необходимы постоянные поставки строительных материалов. Я не посмею просить никого из наших рабочих рубить древние деревья этой рощи, но наши соседи на западе не столь трепетно относятся к лесу.$B$BМы заберем немного оскверненного дерева из цитадели сатиров на западе. Доставь древесину Кривокрону на Лесозаготовки Песни Войны. Он один из Древних, и может очистить ее от порчи.','Добудьте 5 связок оскверненной древесины Сатирнаара.','Дерево, искореженное нечестивой магией демонов, непригодно дренеям Лесной Песни. Из него ничего путного не построишь, но я очищу его от порчи и верну архитектору Немосу и его работникам. Хоть какое-то добро выйдет из этого лиха, в конце концов.','<Древний со скрипом поворачивается к вам.>$B$BАрхитектор Немос сказал, что ты можешь доставить древесину, спасенную из лагеря лесогубов и мерзостного Сатирнаара?','Поговорите с Кривокроном на лесопилке Песни Войны, что в Ясеневом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Напрасные усилия',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Добро пожаловать в Лесную Песнь, |3-6($c). Там, где ныне стоят палатки, однажды вырастут дома, но для этого необходимы постоянные поставки строительных материалов. Я не посмею просить никого из наших рабочих рубить древние деревья этой рощи, но наши соседи на западе не столь трепетно относятся к лесу.$B$BМы заберем немного оскверненного дерева из цитадели сатиров на западе. Доставь древесину Кривокрону на Лесозаготовки Песни Войны. Он один из Древних, и может очистить ее от порчи.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 5 связок оскверненной древесины Сатирнаара.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Дерево, искореженное нечестивой магией демонов, непригодно дренеям Лесной Песни. Из него ничего путного не построишь, но я очищу его от порчи и верну архитектору Немосу и его работникам. Хоть какое-то добро выйдет из этого лиха, в конце концов.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Древний со скрипом поворачивается к вам.>$B$BАрхитектор Немос сказал, что ты можешь доставить древесину, спасенную из лагеря лесогубов и мерзостного Сатирнаара?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Кривокроном на лесопилке Песни Войны, что в Ясеневом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26455,'Потерянная чаша','В области к западу отсюда, что нынче зовется Сатирнаар, некогда было прославленное святилище, которое возвел мой народ. В нем хранилась бесценная реликвия, чаша Элуны, доверенная хранителям святилища жрецами Элуны. Некогда к святилищу стекались паломники, дабы испытать целительную силу чаши, которой она, как говорят, обладала.$B$BМожет, это просто байки, но если в них есть доля правды, то эта святыня может стать ключом к возрождению нашего истерзанного леса. Мне надо точно это выяснить, $n.','Добудьте чашу Элуны.','Вернитесь к Кайнет Штиль в Лесную Песнь, что в Ясеневом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Потерянная чаша',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В области к западу отсюда, что нынче зовется Сатирнаар, некогда было прославленное святилище, которое возвел мой народ. В нем хранилась бесценная реликвия, чаша Элуны, доверенная хранителям святилища жрецами Элуны. Некогда к святилищу стекались паломники, дабы испытать целительную силу чаши, которой она, как говорят, обладала.$B$BМожет, это просто байки, но если в них есть доля правды, то эта святыня может стать ключом к возрождению нашего истерзанного леса. Мне надо точно это выяснить, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте чашу Элуны.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кайнет Штиль в Лесную Песнь, что в Ясеневом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26456,'Донесение с северного фронта','Борьбу с Ордой ведет не только Башня в Ночных лесах, $n. К юго-востоку, на границе со Степями, в роще Среброкрылых, находятся Часовые Среброкрылых. Часовой Дальняя Песня из этой рощи направляет наши действия против тех, кто готов разорить наши земли.$B$BЯ немного припозднилась с отправлением моего последнего донесения часовому Дальней Песне, но боюсь оставить башню без охраны.$B$BМне крайне необходима твоя помощь в доставке этого отчета!','Доставьте донесение часового Мелирии часовому Дальней Песне в рощу Среброкрылых, что в Ясеневом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Донесение с северного фронта',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Борьбу с Ордой ведет не только Башня в Ночных лесах, $n. К юго-востоку, на границе со Степями, в роще Среброкрылых, находятся Часовые Среброкрылых. Часовой Дальняя Песня из этой рощи направляет наши действия против тех, кто готов разорить наши земли.$B$BЯ немного припозднилась с отправлением моего последнего донесения часовому Дальней Песне, но боюсь оставить башню без охраны.$B$BМне крайне необходима твоя помощь в доставке этого отчета!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте донесение часового Мелирии часовому Дальней Песне в рощу Среброкрылых, что в Ясеневом лесу.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26457,'Пособники разрушения','Лесозаготовки Песни Войны – нарыв на теле нашей истерзанной земли. Каждый раз, как нам удается пресечь их работу, надзиратель Гортак приказывает своим лесорубам удвоить усилия!$B$BТеперь орки валят столько леса, что даже использовать весь не могут, рубят живые стволы, когда у них бревна гниют за ненадобностью! Это плевок нам в душу, $n, и мы покажем им, что не потерпим дальнейшего разорения наших земель!$B$BСтупай и не ведай покоя, пока этот надзиратель Гортак и его пособники не будут мертвы!','Убейте надзирателя Гортака и 12 других сторонников Орды на лесозаготовках Песни Войны.','Вернитесь к часовому Люсьели Шепоту Звезд на лесопилку Песни Войны, что в Ясеневом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пособники разрушения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Лесозаготовки Песни Войны – нарыв на теле нашей истерзанной земли. Каждый раз, как нам удается пресечь их работу, надзиратель Гортак приказывает своим лесорубам удвоить усилия!$B$BТеперь орки валят столько леса, что даже использовать весь не могут, рубят живые стволы, когда у них бревна гниют за ненадобностью! Это плевок нам в душу, $n, и мы покажем им, что не потерпим дальнейшего разорения наших земель!$B$BСтупай и не ведай покоя, пока этот надзиратель Гортак и его пособники не будут мертвы!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте надзирателя Гортака и 12 других сторонников Орды на лесозаготовках Песни Войны.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к часовому Люсьели Шепоту Звезд на лесопилку Песни Войны, что в Ясеневом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26458,'Наступление сумерек','Черпая силу из старинных обрядов, посвященных древним богам Хаоса, Сумеречный Молот пытается вернуть своих темных покровителей и распространить смерть и ужас по всему миру.$b$bМы думаем, что Сумеречный Молот вступил в союз с нагами, и теперь они накапливают силы в Непроглядной Пучине на западе.$b$bЧто бы ни затевалось в глубинах древнего храма, этим планам нельзя дать осуществиться.$b$bОбъяви же войну Молоту и вернись с доказательствами своих подвигов! Твои труды будут достойно вознаграждены.','Принесите 10 подвесок Сумерек часовому Алувин в лагерь у Непроглядной Пучины.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наступление сумерек',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Черпая силу из старинных обрядов, посвященных древним богам Хаоса, Сумеречный Молот пытается вернуть своих темных покровителей и распространить смерть и ужас по всему миру.$b$bМы думаем, что Сумеречный Молот вступил в союз с нагами, и теперь они накапливают силы в Непроглядной Пучине на западе.$b$bЧто бы ни затевалось в глубинах древнего храма, этим планам нельзя дать осуществиться.$b$bОбъяви же войну Молоту и вернись с доказательствами своих подвигов! Твои труды будут достойно вознаграждены.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 подвесок Сумерек часовому Алувин в лагерь у Непроглядной Пучины.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26459,'Исследование порчи','Безрассудные эльфы крови попали в западню демонической магии. Разве они не видели, что случилось с нагами и сатирами Калимдора?$b$bЯ боюсь, что эльфы крови могут претерпеть такую же трансформацию. Азерот не может позволить себе породить еще одну расу злобных монстров.$B$BЯ хотел бы изучить ствол мозга сатиров и наг, чтобы понять, на что обрекают себя Син\'дорай. И сатиров, и наг можно найти в Непроглядной Пучине, на западе.','Релвин Тень Звезды в лагере у Непроглядной Пучины хочет, чтобы вы принесли ему 8 оскверненных стволов мозга.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Исследование порчи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Безрассудные эльфы крови попали в западню демонической магии. Разве они не видели, что случилось с нагами и сатирами Калимдора?$b$bЯ боюсь, что эльфы крови могут претерпеть такую же трансформацию. Азерот не может позволить себе породить еще одну расу злобных монстров.$B$BЯ хотел бы изучить ствол мозга сатиров и наг, чтобы понять, на что обрекают себя Син\'дорай. И сатиров, и наг можно найти в Непроглядной Пучине, на западе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Релвин Тень Звезды в лагере у Непроглядной Пучины хочет, чтобы вы принесли ему 8 оскверненных стволов мозга.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26460,'В поисках Талрида','В нынешние дни много слухов ходит о союзе Сумеречного Молота и наг в Непроглядной Пучине на побережье Ясеневого леса.$b$bЯ должен собрать как можно больше сведений для Серебряного Рассвета, чтобы мы могли понять, где и когда нужна наша помощь.$b$bУже много недель прошло, как я отправил разведчика выяснить, что происходит в Непроглядной Пучине. Разведчик Талрид из ордена Серебряного Рассвета до сих пор не вернулся.$b$bДругие мои разведчики заняты насущными делами.$b$bПомоги мне найти Талрида, $n.','Найдите разведчика Талрида из ордена Серебряного Рассвета в Непроглядной Пучине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В поисках Талрида',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В нынешние дни много слухов ходит о союзе Сумеречного Молота и наг в Непроглядной Пучине на побережье Ясеневого леса.$b$bЯ должен собрать как можно больше сведений для Серебряного Рассвета, чтобы мы могли понять, где и когда нужна наша помощь.$b$bУже много недель прошло, как я отправил разведчика выяснить, что происходит в Непроглядной Пучине. Разведчик Талрид из ордена Серебряного Рассвета до сих пор не вернулся.$b$bДругие мои разведчики заняты насущными делами.$b$bПомоги мне найти Талрида, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите разведчика Талрида из ордена Серебряного Рассвета в Непроглядной Пучине.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26461,'Blackfathom Villainy','Strength has left me. Your help is needed!$b$bLong ago this site was a great temple of Elune. But misfortune led to ruin when the corruption of an Old God seeped up from below and tainted the sacred moonwell.$b$bAku\'Mai, servant of the Old God, rose from the waters.$b$bThe Twilight\'s Hammer cultists have allied with the naga to occupy these grounds. The cultists, led by Kelris, sacrifice innocents to Aku\'Mai for power.$b$bSlay Kelris and bring his head to Ashelan at the Blackfathom Camp, $n, please.','Bring the head of Twilight Lord Kelris to Ashelan Northwood at the Blackfathom Camp.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Blackfathom Villainy',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Strength has left me. Your help is needed!$b$bLong ago this site was a great temple of Elune. But misfortune led to ruin when the corruption of an Old God seeped up from below and tainted the sacred moonwell.$b$bAku\'Mai, servant of the Old God, rose from the waters.$b$bThe Twilight\'s Hammer cultists have allied with the naga to occupy these grounds. The cultists, led by Kelris, sacrifice innocents to Aku\'Mai for power.$b$bSlay Kelris and bring his head to Ashelan at the Blackfathom Camp, $n, please.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Bring the head of Twilight Lord Kelris to Ashelan Northwood at the Blackfathom Camp.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26462,'Мерзкий Сломанный Клык','Эти тролли Сломанного Клыка думают, что они особенные, потому что служат Орде. Помереть со смеху можно!$B$BПонимаешь, плевать нам на то, служат ли они Орде, или тролльской империи, или вообще Пылающему Легиону. Мы тут уже несколько столетий троллей убивали и убивать будем.$B$BВообще-то я добрая, так что разрешаю тебе, $gприятель:подруга;, помочь. Бери оружие и топай на поле битвы. Поможешь там нашим ребятам!','Убейте 10 ловчих или мастеров проклятий из племени Сломанного Клыка.','Вернитесь к Керр Суровый Взгляд в Лагерь Грозового Крыла, что во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мерзкий Сломанный Клык',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти тролли Сломанного Клыка думают, что они особенные, потому что служат Орде. Помереть со смеху можно!$B$BПонимаешь, плевать нам на то, служат ли они Орде, или тролльской империи, или вообще Пылающему Легиону. Мы тут уже несколько столетий троллей убивали и убивать будем.$B$BВообще-то я добрая, так что разрешаю тебе, $gприятель:подруга;, помочь. Бери оружие и топай на поле битвы. Поможешь там нашим ребятам!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 ловчих или мастеров проклятий из племени Сломанного Клыка.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Керр Суровый Взгляд в Лагерь Грозового Крыла, что во Внутренних землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26463,'В поисках Терониса','Раэна Волкопас, моя подруга из Астранаара, попросила меня послать разведчика на запад к озеру Фалатим. Теронис ушел несколько дней назад, еще до нападения Орды.$B$BОн думает отыскать один предмет, который, по его мнению, ослабит нападения фурболгов на наш народ – это жезл, сделанный ныне покойным злым волшебником. $B$BПрежде чем уйти, он упомянул, что будет искать драгоценный камень для жезла.$B$BК несчастью, теперь мы знаем, что озеро является источником некоей зловещей силы. Прошу тебя, $n, найди моего друга!','Найдите Терониса у озера Фалатим, что в Ясеневом лесу.','Окровавленное тело Терониса лежит на небольшом холме рядом с Хранителем. $B$BЕго тело покрыто глубокими ранами.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В поисках Терониса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Раэна Волкопас, моя подруга из Астранаара, попросила меня послать разведчика на запад к озеру Фалатим. Теронис ушел несколько дней назад, еще до нападения Орды.$B$BОн думает отыскать один предмет, который, по его мнению, ослабит нападения фурболгов на наш народ – это жезл, сделанный ныне покойным злым волшебником. $B$BПрежде чем уйти, он упомянул, что будет искать драгоценный камень для жезла.$B$BК несчастью, теперь мы знаем, что озеро является источником некоей зловещей силы. Прошу тебя, $n, найди моего друга!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Терониса у озера Фалатим, что в Ясеневом лесу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Окровавленное тело Терониса лежит на небольшом холме рядом с Хранителем. $B$BЕго тело покрыто глубокими ранами.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26464,'Пропавший камень','Осматривая вещи Терониса, вы находите дневник, который все еще в неплохом состоянии.$B$BБыстро пролистав его до конца, вы находите упоминание о некоем драгоценном камне, который он нашел, а потом потерял в районе озера Фалатим.$B$BОстается только найти камень, который искал Теронис. Возможно, его забрали эти щупальца...','Найдите светящийся самоцвет.','Вернитесь к Орендилу Широколисту на заставу Мейстры, что в Ясеневом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пропавший камень',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Осматривая вещи Терониса, вы находите дневник, который все еще в неплохом состоянии.$B$BБыстро пролистав его до конца, вы находите упоминание о некоем драгоценном камне, который он нашел, а потом потерял в районе озера Фалатим.$B$BОстается только найти камень, который искал Теронис. Возможно, его забрали эти щупальца...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите светящийся самоцвет.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Орендилу Широколисту на заставу Мейстры, что в Ясеневом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26465,'Древние статуэтки','Я хотел бы дать тебе поручение, |3-6($c).$B$BЯ на своей маленькой лодочке плыл над затопленными руинами Зорама, когда на меня напали наги. Они выныривали из воды и вцеплялись в меня когтями! Остальное неважно – главное, что мне удалось сбежать.$B$BБеда в том, что я археолог, и прибыл сюда для того, чтобы раздобыть кое-какие артефакты затопленного города.$B$BМожет быть, ты отправишься вместо меня на юго-запад, к Зорамскому взморью, и отыщешь какие-нибудь древности? Они-то и являются причиной моего прибытия сюда.','Добудьте 10 древних статуэток.','Вернитесь к Талену в лагерь у Непроглядной Пучины, что в Ясеневом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Древние статуэтки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я хотел бы дать тебе поручение, |3-6($c).$B$BЯ на своей маленькой лодочке плыл над затопленными руинами Зорама, когда на меня напали наги. Они выныривали из воды и вцеплялись в меня когтями! Остальное неважно – главное, что мне удалось сбежать.$B$BБеда в том, что я археолог, и прибыл сюда для того, чтобы раздобыть кое-какие артефакты затопленного города.$B$BМожет быть, ты отправишься вместо меня на юго-запад, к Зорамскому взморью, и отыщешь какие-нибудь древности? Они-то и являются причиной моего прибытия сюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 10 древних статуэток.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Талену в лагерь у Непроглядной Пучины, что в Ясеневом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26466,'Руузель','Боюсь, тайна этой древней статуэтки так и останется нераскрытой, если не найти ключа к этому древнему замку.$B$BЭтим ключом является кольцо – кольцо Зорама. Оно принадлежало правителям этого города до того, как волны Раскола поглотили его.$B$BДолгие годы кольцо считалось утраченным, пока наги недавно не нашли его.$B$BИх предводительница, Руузель, живет на острове на северной окраине Зорама. Прошу тебя, $n, добудь мне это кольцо!','Добудьте кольцо Зорама.','Вернитесь к Талену в лагерь у Непроглядной Пучины, что в Ясеневом лесу.','У нее кольцо Зорама!','Руузель') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Руузель',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Боюсь, тайна этой древней статуэтки так и останется нераскрытой, если не найти ключа к этому древнему замку.$B$BЭтим ключом является кольцо – кольцо Зорама. Оно принадлежало правителям этого города до того, как волны Раскола поглотили его.$B$BДолгие годы кольцо считалось утраченным, пока наги недавно не нашли его.$B$BИх предводительница, Руузель, живет на острове на северной окраине Зорама. Прошу тебя, $n, добудь мне это кольцо!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте кольцо Зорама.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Талену в лагерь у Непроглядной Пучины, что в Ясеневом лесу.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','У нее кольцо Зорама!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Руузель',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26467,'Сатиры коварны! Дриады в опасности!','Послушай, я не знаю, кто ты, но мне нужна помощь. Мои сестры отправились отнять у одного сатира Ветвь Кенария. Они сказали, что скоро вернутся, но уже целых два дня прошло!$B$B$n, ты $Gдолжен:должна; найти их! Они искали развалины храма ночных эльфов в Ксавиане на северо-западе. Не знаю, что и думать. Найди Анилию, это она повела их на поиски.','Найдите в Ксавиане Анилию.','Судя по зияющей в боку ране, Анилия на грани смерти.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сатиры коварны! Дриады в опасности!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Послушай, я не знаю, кто ты, но мне нужна помощь. Мои сестры отправились отнять у одного сатира Ветвь Кенария. Они сказали, что скоро вернутся, но уже целых два дня прошло!$B$B$n, ты $Gдолжен:должна; найти их! Они искали развалины храма ночных эльфов в Ксавиане на северо-западе. Не знаю, что и думать. Найди Анилию, это она повела их на поиски.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите в Ксавиане Анилию.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Судя по зияющей в боку ране, Анилия на грани смерти.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26468,'Ветвь Кенария','Анилия кладет руки вам на плечи и привлекает вас к себе. Задыхаясь, она показывает на находящуюся на севере арку, затем глаза ее закрываются, и из последних сил она шепчет: "Он забрал ее... Гелтарис..." И в душе вы понимаете, что Анилия умирает, жаждая, чтобы Ветвь Кенария была возвращена дриадам.','Добудьте Ветвь Кенария.','Анилия умерла? Нет, этого не может быть! Кажется, только вчера мы вместе бегали и играли в лесах!$B$BСчастливые дни теперь миновали...','Вернитесь к Иллиане в Лесную Песнь, что в Ясеневом лесу.','Добудь ветвь Кенария!','Гелтарис') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ветвь Кенария',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Анилия кладет руки вам на плечи и привлекает вас к себе. Задыхаясь, она показывает на находящуюся на севере арку, затем глаза ее закрываются, и из последних сил она шепчет: "Он забрал ее... Гелтарис..." И в душе вы понимаете, что Анилия умирает, жаждая, чтобы Ветвь Кенария была возвращена дриадам.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте Ветвь Кенария.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Анилия умерла? Нет, этого не может быть! Кажется, только вчера мы вместе бегали и играли в лесах!$B$BСчастливые дни теперь миновали...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Иллиане в Лесную Песнь, что в Ясеневом лесу.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Добудь ветвь Кенария!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Гелтарис',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26469,'Убийство сатиров!','Поверить не могу – Анилии нет! Как часто мы вместе резвились в лесах... Я почти ощущаю... печаль.$B$BЯ знаю, от чего мне станет легче на душе. Пожалуйста, убей сатиров, что отняли у меня Анилию! Принеси мне их рога в доказательство своего деяния, и я буду навек тебе благодарна.','Добудьте 16 рогов сатиров.','Пожалуйста, помоги мне отомстить за смерть Анилии.','Вернитесь к Иллиане в Лесную Песнь, что в Ясеневом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Убийство сатиров!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Поверить не могу – Анилии нет! Как часто мы вместе резвились в лесах... Я почти ощущаю... печаль.$B$BЯ знаю, от чего мне станет легче на душе. Пожалуйста, убей сатиров, что отняли у меня Анилию! Принеси мне их рога в доказательство своего деяния, и я буду навек тебе благодарна.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 16 рогов сатиров.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Пожалуйста, помоги мне отомстить за смерть Анилии.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Иллиане в Лесную Песнь, что в Ясеневом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26470,'Отвоевать озеро','Убейте 12 злобных элементалей воды и Приливницу.','Вернитесь к часовой Велене Звездный Всполох в башню Звездной Пыли, что в Ясеневом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отвоевать озеро',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 злобных элементалей воды и Приливницу.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к часовой Велене Звездный Всполох в башню Звездной Пыли, что в Ясеневом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26471,'Знание в пучине','Насколько тебе известно, я собираю знания. Древние знания. Могучие знания. Знания, что отворяют пути, знания, что могут пробудить Тех-Что-Спят. Главное – правильно ими распорядиться.$B$BХодят слухи о старинном манускрипте Лоргалиса, будто бы он покоится в Непроглядной Пучине на западе. Некогда там жили наши предки, но они давно уже мертвы. Некогда это место было средоточием великого знания, ныне же город превратился в руины.$B$BНайди манускрипт в Непроглядной Пучине. Сделай это, и я не забуду твоей услуги. Даже после... скончания дней.','Принесите манускрипт Лоргалиса курсанту-часовому Иссаре в лагерь у Непроглядной Пучины.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Знание в пучине',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Насколько тебе известно, я собираю знания. Древние знания. Могучие знания. Знания, что отворяют пути, знания, что могут пробудить Тех-Что-Спят. Главное – правильно ими распорядиться.$B$BХодят слухи о старинном манускрипте Лоргалиса, будто бы он покоится в Непроглядной Пучине на западе. Некогда там жили наши предки, но они давно уже мертвы. Некогда это место было средоточием великого знания, ныне же город превратился в руины.$B$BНайди манускрипт в Непроглядной Пучине. Сделай это, и я не забуду твоей услуги. Даже после... скончания дней.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите манускрипт Лоргалиса курсанту-часовому Иссаре в лагерь у Непроглядной Пучины.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26472,'Безумные друиды','Друиды мертвы! Они были убиты своими же предводителями, которые сошли с ума в результате осквернения Сердца леса проклятыми ордынцами! Даже здесь я чувствую тень разложения, и потому не осмеливаюсь идти дальше.$B$BЯ слишком привязан к Ясеневому лесу и Сердцу леса, но ты... ты $Gмог:могла; бы спуститься в Обитель и сделать то, что должно быть сделано. Ты не заблудишься – я оставил для тебя след из хлебных крошек.$B$BЭто разрывает мне сердце, но я вынужден просить тебя убить некогда великих предводителей друидов – Таниэля Темный Лес, Этиля Зов Луны и Мавориса Проблеск Солнца.','Убейте обезумевших друидов: Таниэля Темный Лес, Этиля Зов Луны и Мавориса Проблеск Солнца.','Покойтесь с миром, друзья. $B$B<Вы видите печаль в кошачьих глазах друида.>$B$BЯ ощутил, как утихает боль Обители Дор\'Данил, и понял, что ты выполнил свою задачу.$B$BТяжелое дело выпало тебе, Проклятус, ибо духи, которых ты уничтожил, всего лишь жертвы Орды. Но с их погибелью, будем надеяться, и другие безумные духи обретут покой.','Вернитесь к Гайвану Бредущему Тенью, который бродит возле Обители Дор\'Данил, что в Ясеневом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Безумные друиды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Друиды мертвы! Они были убиты своими же предводителями, которые сошли с ума в результате осквернения Сердца леса проклятыми ордынцами! Даже здесь я чувствую тень разложения, и потому не осмеливаюсь идти дальше.$B$BЯ слишком привязан к Ясеневому лесу и Сердцу леса, но ты... ты $Gмог:могла; бы спуститься в Обитель и сделать то, что должно быть сделано. Ты не заблудишься – я оставил для тебя след из хлебных крошек.$B$BЭто разрывает мне сердце, но я вынужден просить тебя убить некогда великих предводителей друидов – Таниэля Темный Лес, Этиля Зов Луны и Мавориса Проблеск Солнца.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте обезумевших друидов: Таниэля Темный Лес, Этиля Зов Луны и Мавориса Проблеск Солнца.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Покойтесь с миром, друзья. $B$B<Вы видите печаль в кошачьих глазах друида.>$B$BЯ ощутил, как утихает боль Обители Дор\'Данил, и понял, что ты выполнил свою задачу.$B$BТяжелое дело выпало тебе, Проклятус, ибо духи, которых ты уничтожил, всего лишь жертвы Орды. Но с их погибелью, будем надеяться, и другие безумные духи обретут покой.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гайвану Бредущему Тенью, который бродит возле Обители Дор\'Данил, что в Ясеневом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26473,'Батранов волос','Есть одна травка, что росла некогда в древних руинах Убежища Батрана, что вдоль дороги на востоке. Звалась эта травка Батранов волос и славилась тем, что лечила болезни души.$B$BУвы, теперь ее собирают прислужники Орды для своих зловещих целей.$B$BВ Астранааре болеет ребенок, и сдается мне, что это болезнь не телесная. Я обещал своему наставнику найти лекарство, но мне не под силу сражаться с воинами.$B$BНе сходишь ли ты в Убежище Батрана и не поищешь ли Батранов волос?','Соберите 8 стеблей Батранова волоса.','Ах, ты принесла волос! Первый шаг сделан. Нам, конечно, понадобятся и другие ингредиенты, но волос павшего Древнего – один из самых редких компонентов.$B$BХочется надеяться, что Отрекшимся не удастся обратить останки этого дерева в оружие. У нас просто не хватит сил, чтобы справиться с ними – все наши войска брошены на защиту заставы Мейстры.','Вернитесь к Эвенар Тихий Шелест в Укрытие Орендила, что в Ясеневом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Батранов волос',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Есть одна травка, что росла некогда в древних руинах Убежища Батрана, что вдоль дороги на востоке. Звалась эта травка Батранов волос и славилась тем, что лечила болезни души.$B$BУвы, теперь ее собирают прислужники Орды для своих зловещих целей.$B$BВ Астранааре болеет ребенок, и сдается мне, что это болезнь не телесная. Я обещал своему наставнику найти лекарство, но мне не под силу сражаться с воинами.$B$BНе сходишь ли ты в Убежище Батрана и не поищешь ли Батранов волос?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 стеблей Батранова волоса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ах, ты принесла волос! Первый шаг сделан. Нам, конечно, понадобятся и другие ингредиенты, но волос павшего Древнего – один из самых редких компонентов.$B$BХочется надеяться, что Отрекшимся не удастся обратить останки этого дерева в оружие. У нас просто не хватит сил, чтобы справиться с ними – все наши войска брошены на защиту заставы Мейстры.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Эвенар Тихий Шелест в Укрытие Орендила, что в Ясеневом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (26474,'Лекарство Орендила','$n, это лекарство, благословенное светом Элуны, должно помочь больному ребенку. Отнеси его в Астранаар отцу ребенка, Пельтуру Белой Луне.$B$BЧтобы добраться до Астранаара, ступай по дороге сначала на юг, потом на восток. Но если хочешь добраться туда побыстрее – поговори с часовым Аваной.','Принесите лекарство Орендила Пельтуру Белой Луне в Астранаар, что в Ясеневом лесу.','Это от Орендила?$B$BОн славен знанием трав и лекарским искусством. Это лекарство вселяет в меня надежду, которой прежде у меня почти не было...','Прошу прощения, но у меня нет времени на разговоры. Мое дитя, моя Релара смертельно больна!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лекарство Орендила',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, это лекарство, благословенное светом Элуны, должно помочь больному ребенку. Отнеси его в Астранаар отцу ребенка, Пельтуру Белой Луне.$B$BЧтобы добраться до Астранаара, ступай по дороге сначала на юг, потом на восток. Но если хочешь добраться туда побыстрее – поговори с часовым Аваной.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите лекарство Орендила Пельтуру Белой Луне в Астранаар, что в Ясеневом лесу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это от Орендила?$B$BОн славен знанием трав и лекарским искусством. Это лекарство вселяет в меня надежду, которой прежде у меня почти не было...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Прошу прощения, но у меня нет времени на разговоры. Мое дитя, моя Релара смертельно больна!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26475,'Слеза Элуны','Я надеялся, что лекарство Орендила спасет Релару, но, боюсь, оно лишь немного ослабило болезнь, поселившуюся в теле моей дочери. Мы должны найти более мощное средство! К счастью, Орендил говорил мне, какие еще он попытается применить лекарства, если первое не поможет.$B$BСлеза Элуны – это такой камень, который можно найти только в одном месте – у обмелевшего озера Ирис, уничтоженном при извержении вулкана Громовой Вершины. Оно находится к востоку от Астранаара. Орендил сказал, что этот камень снимает порчу... прошу тебя, $n, принеси мне Слезу Элуны, и да покончит она с болезнью моей дочери!','Найдите Слезу Элуны.','Вернитесь к Пельтуру Белой Луне в Астранаар, что в Ясеневом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Слеза Элуны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я надеялся, что лекарство Орендила спасет Релару, но, боюсь, оно лишь немного ослабило болезнь, поселившуюся в теле моей дочери. Мы должны найти более мощное средство! К счастью, Орендил говорил мне, какие еще он попытается применить лекарства, если первое не поможет.$B$BСлеза Элуны – это такой камень, который можно найти только в одном месте – у обмелевшего озера Ирис, уничтоженном при извержении вулкана Громовой Вершины. Оно находится к востоку от Астранаара. Орендил сказал, что этот камень снимает порчу... прошу тебя, $n, принеси мне Слезу Элуны, и да покончит она с болезнью моей дочери!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Слезу Элуны.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Пельтуру Белой Луне в Астранаар, что в Ясеневом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (26476,'Посылка для дриад','А, вот и ты, $n. Я изучила записи Терониса, и пришла к выводу, что твоим следующим действием будет поиск остальных фрагментов созданного Дартолом жезла.$B$BЯ бы для начала пошла на восток вдоль дороги, ведущей к башне в Ночных лесах.$B$BДриада Шаэл\'дрин будет тебе лучшим проводником. Найди ее.$B$BВозьми с собой этот самоцвет – он может понадобиться Шаэл\'дрин, если она решит помочь тебе восстановить жезл.','Отнесите светящийся самоцвет Шаэлдрин у башни в Ночных лесах, что в Ясеневом лесу.','О, так тебя послала Раэна? Тогда это и правда серьезное дело. Чем я могу тебе помочь?','Здравствуй. Как поживаешь?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Посылка для дриад',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А, вот и ты, $n. Я изучила записи Терониса, и пришла к выводу, что твоим следующим действием будет поиск остальных фрагментов созданного Дартолом жезла.$B$BЯ бы для начала пошла на восток вдоль дороги, ведущей к башне в Ночных лесах.$B$BДриада Шаэл\'дрин будет тебе лучшим проводником. Найди ее.$B$BВозьми с собой этот самоцвет – он может понадобиться Шаэл\'дрин, если она решит помочь тебе восстановить жезл.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите светящийся самоцвет Шаэлдрин у башни в Ночных лесах, что в Ясеневом лесу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, так тебя послала Раэна? Тогда это и правда серьезное дело. Чем я могу тебе помочь?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Здравствуй. Как поживаешь?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26477,'Поиски древка','Хотелось бы мне, чтобы у тебя были более хорошие новости.$B$BРаэна права, мне многое известно о творении Дартола и древнях этих краев – или было известно прежде. Теперь все они осквернены, их природа искажена.$B$BЕсли твоя цель – найти еще один фрагмент жезла, то тебе придется найти ключ, чтобы отпереть сундук, в котором он лежит.$B$BДеревянный ключ – на одном из древней к северо-востоку отсюда, близ Оскверненного леса в Воющей долине. Как только добудешь его, ищи небольшую лощинку в долине... Сундук должен быть спрятан где-то там.','Найдите деревянный ключ и с его помощью получите железное древко жезла Дартола.','Меня беспокоит то, что древни подверглись порче. Хотелось бы мне побольше сделать для них.','Вернитесь к Шаэл\'дрин к башне в Ночных лесах, что в Ясеневом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поиски древка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хотелось бы мне, чтобы у тебя были более хорошие новости.$B$BРаэна права, мне многое известно о творении Дартола и древнях этих краев – или было известно прежде. Теперь все они осквернены, их природа искажена.$B$BЕсли твоя цель – найти еще один фрагмент жезла, то тебе придется найти ключ, чтобы отпереть сундук, в котором он лежит.$B$BДеревянный ключ – на одном из древней к северо-востоку отсюда, близ Оскверненного леса в Воющей долине. Как только добудешь его, ищи небольшую лощинку в долине... Сундук должен быть спрятан где-то там.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите деревянный ключ и с его помощью получите железное древко жезла Дартола.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Меня беспокоит то, что древни подверглись порче. Хотелось бы мне побольше сделать для них.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Шаэл\'дрин к башне в Ночных лесах, что в Ясеневом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26478,'Притвориться мертвым','Найдите последний фрагмент жезла Дартола, Железное навершие.','Вернитесь к Шаэл\'дрин к башне в Ночных лесах, что в Ясеневом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Притвориться мертвым',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите последний фрагмент жезла Дартола, Железное навершие.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Шаэл\'дрин к башне в Ночных лесах, что в Ясеневом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26479,'Возвращение к Раэне','Советую тебе найти Раэну и сказать ей, что жезл воссоздан. Я уверена, она знает, куда тебе направиться дальше. $B$BБудь $gосторожен:осторожна;... сила, заключенная в этом жезле, может послужить как добру, так и злу. Надеюсь, вы с Раэной знаете, что делаете.$B$BУдачи, $n.','Вернитесь к Раэне Волкопас в Астранаар, что в Ясеневом лесу, и передайте ей жезл Дартола.','Ты собрала жезл, который должен был отыскать Теронис? Это приятно слышать.$B$BТеронис был бы счастлив, узнав, что его задание выполнено даже после его трагической гибели.$B$B<Раэна с одобрением смотрит на жезл, но в глазах ее бушует ярость.>$B$BНастало время воспользоваться его силой, чтобы изгнать врагов из Ясеневого леса!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение к Раэне',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Советую тебе найти Раэну и сказать ей, что жезл воссоздан. Я уверена, она знает, куда тебе направиться дальше. $B$BБудь $gосторожен:осторожна;... сила, заключенная в этом жезле, может послужить как добру, так и злу. Надеюсь, вы с Раэной знаете, что делаете.$B$BУдачи, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь к Раэне Волкопас в Астранаар, что в Ясеневом лесу, и передайте ей жезл Дартола.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты собрала жезл, который должен был отыскать Теронис? Это приятно слышать.$B$BТеронис был бы счастлив, узнав, что его задание выполнено даже после его трагической гибели.$B$B<Раэна с одобрением смотрит на жезл, но в глазах ее бушует ярость.>$B$BНастало время воспользоваться его силой, чтобы изгнать врагов из Ясеневого леса!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26480,'Жезл Дартола','Увы, я не могу точно знать, что Теронис собирался делать дальше, но если он сказал правду о силе жезла, то ты можешь с его помощью изменить облик, притворившись фурболгом.$B$BПолагаю, он намеревался использовать его мощь, чтобы подобраться поближе к этим мерзостным тварям, но даже не затронутые порчей существа убили бы его, не будь он осторожен. Изменив облик, Дартол намеревался поговорить с фурболгом, которого не коснулась рука скверны.$B$BЯ бы начала с существа по имени Кролг. Ищи его к юго-востоку от озера Мистраль.','Найдите Кролга в его хижине в Ясеневом лесу и поговорите с ним при помощи жезла Дартола.','Да-да... ты выглядишь как мой сородич, но мне все равно, кто ты такой на самом деле. Главное – спасти фурболгов.$B$BСперва ночные эльфы, а теперь и орки обрушили великие беды на наш народ.$B$BНынче порча бежит в жилах наших сородичей, малыш, порча, насланная на нас спесивыми ночными эльфами и безжалостными орками. Это они с нами такое сделали... Они виноваты в том, что меня изгнали из племени.$B$BПо ночам я по-прежнему вижу костры в темноте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жезл Дартола',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Увы, я не могу точно знать, что Теронис собирался делать дальше, но если он сказал правду о силе жезла, то ты можешь с его помощью изменить облик, притворившись фурболгом.$B$BПолагаю, он намеревался использовать его мощь, чтобы подобраться поближе к этим мерзостным тварям, но даже не затронутые порчей существа убили бы его, не будь он осторожен. Изменив облик, Дартол намеревался поговорить с фурболгом, которого не коснулась рука скверны.$B$BЯ бы начала с существа по имени Кролг. Ищи его к юго-востоку от озера Мистраль.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Кролга в его хижине в Ясеневом лесу и поговорите с ним при помощи жезла Дартола.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да-да... ты выглядишь как мой сородич, но мне все равно, кто ты такой на самом деле. Главное – спасти фурболгов.$B$BСперва ночные эльфы, а теперь и орки обрушили великие беды на наш народ.$B$BНынче порча бежит в жилах наших сородичей, малыш, порча, насланная на нас спесивыми ночными эльфами и безжалостными орками. Это они с нами такое сделали... Они виноваты в том, что меня изгнали из племени.$B$BПо ночам я по-прежнему вижу костры в темноте.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26481,'Новое украшение','Я уверен, что этот погибший волшебник, Дартол, намеревался использовать силу жезла для того, чтобы подчинить и уничтожить нас – точно так же, как ночные эльфы и орки. Но теперь у нас появился шанс использовать эту штуку по другому назначению.$B$BРэн Кровавый Клык – король всех фурболгов Ясеневого леса. Его племя обладает огромной силой и обитает в лагере на востоке.$B$BУбей их всех и принеси мне череп вождя. Пусть эта вещь хоть раз послужит благому делу.','Добудьте череп Рэна Кровавого Клыка и жезл Дартола.','Хорошая работа.$B$BЛес все еще осквернен, но мы по крайней мере знаем, что сделали хоть немного для того, чтобы вернуть его прежнюю красоту. Если пожелаешь снова вернуться ко мне, я буду рад обществу сородича.$B$BУдачи тебе. Возможно, наши племена снова встретятся в не столь жестокие времена.','Ты еще не убил Рэна?$B$BЕсли мы хотим освободить моих людей от рабских цепей, нам нужен его череп.','Вернитесь к Кролгу в его хижину, что в Ясеневом лесу.','Добудь череп Рэна.','Рэн Кровавый Клык') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новое украшение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я уверен, что этот погибший волшебник, Дартол, намеревался использовать силу жезла для того, чтобы подчинить и уничтожить нас – точно так же, как ночные эльфы и орки. Но теперь у нас появился шанс использовать эту штуку по другому назначению.$B$BРэн Кровавый Клык – король всех фурболгов Ясеневого леса. Его племя обладает огромной силой и обитает в лагере на востоке.$B$BУбей их всех и принеси мне череп вождя. Пусть эта вещь хоть раз послужит благому делу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте череп Рэна Кровавого Клыка и жезл Дартола.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошая работа.$B$BЛес все еще осквернен, но мы по крайней мере знаем, что сделали хоть немного для того, чтобы вернуть его прежнюю красоту. Если пожелаешь снова вернуться ко мне, я буду рад обществу сородича.$B$BУдачи тебе. Возможно, наши племена снова встретятся в не столь жестокие времена.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты еще не убил Рэна?$B$BЕсли мы хотим освободить моих людей от рабских цепей, нам нужен его череп.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кролгу в его хижину, что в Ясеневом лесу.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Добудь череп Рэна.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Рэн Кровавый Клык',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (26482,'Истинная сила жезла','Используя жезл Дартола, поговорите с Ота Веном и уговорите его поднять восстание против ордынских захватчиков. Затем отнесите жезл Раэне Волкопас.','Восстание поднято.','Отнесите жезл Дартола Раэне Волкопас в Астранаар, что в Ясеневом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Истинная сила жезла',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используя жезл Дартола, поговорите с Ота Веном и уговорите его поднять восстание против ордынских захватчиков. Затем отнесите жезл Раэне Волкопас.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Восстание поднято.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите жезл Дартола Раэне Волкопас в Астранаар, что в Ясеневом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26483,'Ган\'дранда','Кроме рубки голов этим троллям, у нас еще полон рот хлопот. Хорошо бы закончить хоть эту битву, да?$B$BИх командир Ган\'дранда засел на разрушенной стене к юго-востоку от поля битвы. Наши ребята сейчас сильно заняты, поэтому тебе придется туда проникнуть и изничтожить Ган\'дранду. Когда они увидят, что их величайший герой сражен, многие наверняка просто бросят оружие!','Убейте Ган\'дранду.','Вот, это я и хотел услышать. Молодчина!','Вернитесь к Керр Суровый Взгляд в Лагерь Грозового Крыла, что во Внутренних землях.','Наши шансы будут гораздо выше, если этот негодяй умрет.','Ган\'дранда') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ган\'дранда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кроме рубки голов этим троллям, у нас еще полон рот хлопот. Хорошо бы закончить хоть эту битву, да?$B$BИх командир Ган\'дранда засел на разрушенной стене к юго-востоку от поля битвы. Наши ребята сейчас сильно заняты, поэтому тебе придется туда проникнуть и изничтожить Ган\'дранду. Когда они увидят, что их величайший герой сражен, многие наверняка просто бросят оружие!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Ган\'дранду.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот, это я и хотел услышать. Молодчина!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Керр Суровый Взгляд в Лагерь Грозового Крыла, что во Внутренних землях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Наши шансы будут гораздо выше, если этот негодяй умрет.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Ган\'дранда',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26484,'На помощь Каменному очагу','Поговорите с Крегом Крушителем Скал в Каменном очаге в Подземье.','Тебя прислал Флинт, сын Отца-Скалы? Нет времени на разговоры.$B$BНужно победить их до того, как они получат подкрепление!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На помощь Каменному очагу',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Крегом Крушителем Скал в Каменном очаге в Подземье.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебя прислал Флинт, сын Отца-Скалы? Нет времени на разговоры.$B$BНужно победить их до того, как они получат подкрепление!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26485,'Хрустогрызы, сэр!','Хочу сварить что-то особенное для этих надоедливых троллей. Да-да, для них. Они никогда не забудут мое угощение! Они от него землю клыками рыть будут!$B$BНекоторые ингредиенты у меня уже есть, но мне все же понадобится твоя помощь. На востоке, на побережье у Отвесных скал полно хрустогрызов. Для моего восхитительного пойла мне нужны их свежие потроха.','Соберите 8 кучек потрохов морских хрустогрызов.','Свеженькие, то что надо! Займусь ими, пока ты бегаешь за следующими компонентами.','Где потроха?','Вернитесь к Дрону Первачу в лагерь Штормокрылой, что во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хрустогрызы, сэр!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хочу сварить что-то особенное для этих надоедливых троллей. Да-да, для них. Они никогда не забудут мое угощение! Они от него землю клыками рыть будут!$B$BНекоторые ингредиенты у меня уже есть, но мне все же понадобится твоя помощь. На востоке, на побережье у Отвесных скал полно хрустогрызов. Для моего восхитительного пойла мне нужны их свежие потроха.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 кучек потрохов морских хрустогрызов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Свеженькие, то что надо! Займусь ими, пока ты бегаешь за следующими компонентами.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Где потроха?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дрону Первачу в лагерь Штормокрылой, что во Внутренних землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26486,'Игра в бутылочку','Да-да, я помню, что у нас тут бои идут, но там на побережье возле Отвесных скал лежат разбросанные бутылки. Не хочу, чтобы славный напиток попал в грязные лапы Орды!$B$BЕсли не трудно, собери там бутылки и принеси их мне. Я тебе заплачу сполна, как будто это твоего собственного разлива бутылки!','Соберите 12 бутылок портвейна "Пупелливербос".','Вот оно! Троллям и гоблинам этот славный напиток не достался, зато мы получим от него удовольствие!$B$BМожет, добавить немного, когда пиво буду варить вдругорядь?..','12 будет в самый раз!','Вернитесь к Дрону Первачу во Внутренние земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Игра в бутылочку',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Да-да, я помню, что у нас тут бои идут, но там на побережье возле Отвесных скал лежат разбросанные бутылки. Не хочу, чтобы славный напиток попал в грязные лапы Орды!$B$BЕсли не трудно, собери там бутылки и принеси их мне. Я тебе заплачу сполна, как будто это твоего собственного разлива бутылки!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 12 бутылок портвейна "Пупелливербос".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот оно! Троллям и гоблинам этот славный напиток не достался, зато мы получим от него удовольствие!$B$BМожет, добавить немного, когда пиво буду варить вдругорядь?..',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','12 будет в самый раз!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дрону Первачу во Внутренние земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26487,'Вязанка акириса','Не так-то просто одновременно управлять пятизвездочным отелем и заводом по переработке вторсырья! Ну то есть было бы непросто, если бы я не владела навыками личного помощника торгового принца!$B$BГлавный фокус – многозадачность. К примеру, на юге наги-исследователи носят с собой ценные морские водоросли – стебли акириса. Мы можем продавать эти водоросли заморским клиентам, а можем набивать ими тюфяки для наших гостей! Если подумать, партия этих водорослей нам совсем не помешает.','Отберите 6 стеблей акириса у наг-исследователей.','Ух ты! Неплохо, совсем неплохо! У тебя неплохие перспективы в добывающей отрасли. Ну, или в гостиничном бизнесе.','Ну-ка, посмотрим... Понадобятся дробовики для сафари, гребные лодки для однодневной экскурсии на буровую вышку и...$B$BО, ты уже вернулся?','Вернитесь к Хамми Кофельнагель в Укрытие Кофельнагель на мысе Тернистой долины.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вязанка акириса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не так-то просто одновременно управлять пятизвездочным отелем и заводом по переработке вторсырья! Ну то есть было бы непросто, если бы я не владела навыками личного помощника торгового принца!$B$BГлавный фокус – многозадачность. К примеру, на юге наги-исследователи носят с собой ценные морские водоросли – стебли акириса. Мы можем продавать эти водоросли заморским клиентам, а можем набивать ими тюфяки для наших гостей! Если подумать, партия этих водорослей нам совсем не помешает.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отберите 6 стеблей акириса у наг-исследователей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ух ты! Неплохо, совсем неплохо! У тебя неплохие перспективы в добывающей отрасли. Ну, или в гостиничном бизнесе.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну-ка, посмотрим... Понадобятся дробовики для сафари, гребные лодки для однодневной экскурсии на буровую вышку и...$B$BО, ты уже вернулся?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хамми Кофельнагель в Укрытие Кофельнагель на мысе Тернистой долины.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26489,'Ты!','Чем я могу... $B$B<Хамми открывает рот в глубоком изумлении.>$B$B$n! Неужели это ты?! Как $gвырос:выросла;, $gвозмужал:окрепла;! Вот это мышцы, дай-ка пощупать!$B$BКак я? Пытаюсь заработать в этих джунглях. Мы в основном занимаемся добычей материалов, ну и туризмом понемногу.$B$BЗдорово придумано, знаю.$B$BСлушай-ка, мне тут одна мысль в голову пришла... У наг-исследователей на юге произрастают стебли акириса. Мы бы могли их выгодно продать и набить ими матрацы наших клиентов. Не хочешь разделаться с парой наг? Как в старые добрые времена.','Добудьте 6 стеблей акириса у наг-исследователей.','Вернитесь к Хамми Кофельнагель в Укрытие Кофельнагель на мысе Тернистой долины.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ты!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чем я могу... $B$B<Хамми открывает рот в глубоком изумлении.>$B$B$n! Неужели это ты?! Как $gвырос:выросла;, $gвозмужал:окрепла;! Вот это мышцы, дай-ка пощупать!$B$BКак я? Пытаюсь заработать в этих джунглях. Мы в основном занимаемся добычей материалов, ну и туризмом понемногу.$B$BЗдорово придумано, знаю.$B$BСлушай-ка, мне тут одна мысль в голову пришла... У наг-исследователей на юге произрастают стебли акириса. Мы бы могли их выгодно продать и набить ими матрацы наших клиентов. Не хочешь разделаться с парой наг? Как в старые добрые времена.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 6 стеблей акириса у наг-исследователей.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хамми Кофельнагель в Укрытие Кофельнагель на мысе Тернистой долины.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26490,'Жуть-муть','Немногие дворфы в курсе, но чтобы мое пойло РЕАЛЬНО вышибало мозги, я добавляю в него чуть-чуть слизнятины. Ага, прям вот от дворфоядных слизнюков, зеленых таких.$B$BА сейчас нам нужен просто СНОГСШИБАТЕЛЬНЫЙ эффект, так что нам нужен большой слизень! На Осклизлой скале как раз есть один, огромный такой... наверное, это их матка. Мы этого слизня зовем Вязкая Муть.$B$BТак что, если не дрейфишь, сходи туда и принеси мне кусочек этой Вязкой Мути.','Заберите кусочек вязкой мути у Вязкой Мути.','Вот это да! Какой роскошный получится букет! А уж эффект…','Вернитесь к Дрону Первачу в лагерь Штормокрылой, что во Внутренних землях.','Не подходи слишком близко… неизвестно, чего можно ждать от этой штуки.','Вязкая Муть') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жуть-муть',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Немногие дворфы в курсе, но чтобы мое пойло РЕАЛЬНО вышибало мозги, я добавляю в него чуть-чуть слизнятины. Ага, прям вот от дворфоядных слизнюков, зеленых таких.$B$BА сейчас нам нужен просто СНОГСШИБАТЕЛЬНЫЙ эффект, так что нам нужен большой слизень! На Осклизлой скале как раз есть один, огромный такой... наверное, это их матка. Мы этого слизня зовем Вязкая Муть.$B$BТак что, если не дрейфишь, сходи туда и принеси мне кусочек этой Вязкой Мути.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заберите кусочек вязкой мути у Вязкой Мути.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот это да! Какой роскошный получится букет! А уж эффект…',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дрону Первачу в лагерь Штормокрылой, что во Внутренних землях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Не подходи слишком близко… неизвестно, чего можно ждать от этой штуки.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Вязкая Муть',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26491,'Большая уборка на Осклизлой скале','Много лет назад на Осклизлой скале был лагерь Орды. Он много лет пустовал, но все еще является желанной целью для наших союзников.$B$BДело в том, что там полно дворфоядных слизнюков и прочей ядовитой дряни. Они не так отвратительны, как тролли, но не намного лучше.$B$BНаши ребята заняты сражением со Сломанным Клыком, так что отправиться на Осклизлую скалу и очистить ее придется тебе.','Убейте 10 нефритовых слизнюков.','Как я рад, что ты вернулся… да еще и со всеми конечностями в полном комплекте.','Вернитесь к Керр Суровый Взгляд в Лагерь Грозового Крыла, что во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Большая уборка на Осклизлой скале',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Много лет назад на Осклизлой скале был лагерь Орды. Он много лет пустовал, но все еще является желанной целью для наших союзников.$B$BДело в том, что там полно дворфоядных слизнюков и прочей ядовитой дряни. Они не так отвратительны, как тролли, но не намного лучше.$B$BНаши ребята заняты сражением со Сломанным Клыком, так что отправиться на Осклизлую скалу и очистить ее придется тебе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 нефритовых слизнюков.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Как я рад, что ты вернулся… да еще и со всеми конечностями в полном комплекте.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Керр Суровый Взгляд в Лагерь Грозового Крыла, что во Внутренних землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26492,'Припасы с Осклизлой скалы','А вот мой двоюродный брат был на Второй войне. Он рассказывал, как они воевали на Осклизлой скале. Напали они тогда на нее и всех троллей оттуда поганой метлой вымели. А потом еще и гнали их до самого Альтерака!$B$BПотом сюда очень быстро наползли слизни, а ведь здесь еще полно припасов Орды. Нельзя позволить троллям забрать их!$B$BПринеси мне несколько ящиков с северо-запада Осклизлой скалы.','Соберите 5 покрытых слизью ящиков с припасами.','Кажется, они еще полные! Хм.. Это что? Банановый хлеб? Надо же! Еще мягкий!$B$BВот, приятель, возьми свою долю.','Ящики у тебя?','Вернитесь к Керр Суровый Взгляд в Лагерь Грозового Крыла, что во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Припасы с Осклизлой скалы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А вот мой двоюродный брат был на Второй войне. Он рассказывал, как они воевали на Осклизлой скале. Напали они тогда на нее и всех троллей оттуда поганой метлой вымели. А потом еще и гнали их до самого Альтерака!$B$BПотом сюда очень быстро наползли слизни, а ведь здесь еще полно припасов Орды. Нельзя позволить троллям забрать их!$B$BПринеси мне несколько ящиков с северо-запада Осклизлой скалы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 5 покрытых слизью ящиков с припасами.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Кажется, они еще полные! Хм.. Это что? Банановый хлеб? Надо же! Еще мягкий!$B$BВот, приятель, возьми свою долю.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ящики у тебя?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Керр Суровый Взгляд в Лагерь Грозового Крыла, что во Внутренних землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26493,'Есть желающие!','Добудьте 7 секретных ингредиентов Хамми у василисков-хвостохлестов и железозубых василисков в Хрустальной шахте.','Отлично! Какая... гадость. Но гадость ценная. Теперь разделим добычу. Это мне, это Джасперу, это Шабалу...','Надеюсь, ты извлекал ингредиенты так, как я сказала.','Вернитесь к Хамми Кофельнагель в Укрытие Кофельнагель на мысе Тернистой долины.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Есть желающие!',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 7 секретных ингредиентов Хамми у василисков-хвостохлестов и железозубых василисков в Хрустальной шахте.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! Какая... гадость. Но гадость ценная. Теперь разделим добычу. Это мне, это Джасперу, это Шабалу...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Надеюсь, ты извлекал ингредиенты так, как я сказала.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хамми Кофельнагель в Укрытие Кофельнагель на мысе Тернистой долины.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (26494,'Смешиватель Джаспер','Ты не передашь это Джасперу? Он там, у богатых квартир. Ему это очень пригодится.$B$BСпасибо, $n!','Отнесите образцы Хамми смешивателю Джасперу в Укрытие Кофельнагель.','Я это пока приберу. Может, позже проведем эксперимент.$B$B<Джаспер смеривает вас взглядом>$B$BДа, ты вполне сгодишься.','Это для меня, да? Из магазина?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Смешиватель Джаспер',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты не передашь это Джасперу? Он там, у богатых квартир. Ему это очень пригодится.$B$BСпасибо, $n!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите образцы Хамми смешивателю Джасперу в Укрытие Кофельнагель.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я это пока приберу. Может, позже проведем эксперимент.$B$B<Джаспер смеривает вас взглядом>$B$BДа, ты вполне сгодишься.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Это для меня, да? Из магазина?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26495,'Шабал','Тролль у ботанического сада (одновременно лаборатории по производству биологического оружия) – Шабал, наш особый гость. Это один из зандаларов, он проделал неблизкий путь, чтобы сюда добраться.$B$B<Хамми кладет несколько принесенных вами вещиц в небольшой мешок и отдает вам.>$B$BВот, отнеси ему. Скажи, что зандаларов всегда рады видеть в Укрытии Кофельнагель! И не забудь упомянуть, что в нашем деле главное – это рекомендации!','Отнесите щедрый дар Хамми Шабалу в Укрытие Кофельнагель.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Шабал',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тролль у ботанического сада (одновременно лаборатории по производству биологического оружия) – Шабал, наш особый гость. Это один из зандаларов, он проделал неблизкий путь, чтобы сюда добраться.$B$B<Хамми кладет несколько принесенных вами вещиц в небольшой мешок и отдает вам.>$B$BВот, отнеси ему. Скажи, что зандаларов всегда рады видеть в Укрытии Кофельнагель! И не забудь упомянуть, что в нашем деле главное – это рекомендации!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите щедрый дар Хамми Шабалу в Укрытие Кофельнагель.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26496,'Сломай Порочную Ветвь','Племя Сломанного Клыка – не единственные тролли, с которыми надо разделаться! Тролли из племени Порочной Ветви пачкают эту землю уже долгие годы, обосновавшись в своей крепости Джинта\'Алор.$B$BА нам уже надоело сидеть на Заоблачном пике и ножками болтать. Доран Сталекрылый ведет войско на племя Порочной Ветви из лагеря на юге. Поговори с ним и присоединяйся к войску!','Найдите Дорана Сталекрылого у Джинта\'Алора во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сломай Порочную Ветвь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Племя Сломанного Клыка – не единственные тролли, с которыми надо разделаться! Тролли из племени Порочной Ветви пачкают эту землю уже долгие годы, обосновавшись в своей крепости Джинта\'Алор.$B$BА нам уже надоело сидеть на Заоблачном пике и ножками болтать. Доран Сталекрылый ведет войско на племя Порочной Ветви из лагеря на юге. Поговори с ним и присоединяйся к войску!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Дорана Сталекрылого у Джинта\'Алора во Внутренних землях.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26497,'Гнилые плоды Порочной Ветви','Племя Порочной Ветви отличается от племени Сломанного Клыка, но эта разница не имеет значения: мы уже давно поняли, что хороший тролль – это мертвый тролль.$B$BПлемя Порочной Ветви отвратительно само по себе, даже без хомута Орды на шее. Если мы не избавимся от них, они испоганят всю эту землю.$B$BМожешь начать с их знахарей и охотников за головами на нижних ярусах. Как перебьешь троллей побольше – возвращайся ко мне.','Убейте 5 знахарей и 5 охотников за головами из племени Порочной Ветви в Джинта\'Алоре.','Мы им, всем этим троллям, покажем!','Вернитесь к Дорану Сталекрылому в Джинта\'Алор, что во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гнилые плоды Порочной Ветви',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Племя Порочной Ветви отличается от племени Сломанного Клыка, но эта разница не имеет значения: мы уже давно поняли, что хороший тролль – это мертвый тролль.$B$BПлемя Порочной Ветви отвратительно само по себе, даже без хомута Орды на шее. Если мы не избавимся от них, они испоганят всю эту землю.$B$BМожешь начать с их знахарей и охотников за головами на нижних ярусах. Как перебьешь троллей побольше – возвращайся ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 5 знахарей и 5 охотников за головами из племени Порочной Ветви в Джинта\'Алоре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мы им, всем этим троллям, покажем!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дорану Сталекрылому в Джинта\'Алор, что во Внутренних землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26498,'Смерть Порочной Ветви!','Дела идут отлично. Продолжай в том же духе и не сбрасывай обороты!$B$BБерсерки из племени Порочной Ветви сражаются как дикие звери, благодаря боевой ярости. Их темные чародеи призывают духов из иного мира! Поэтому нам надо избавиться от этих гнусных существ как можно скорее, $n, не забывай это.$B$BИди на средний ярус и убей берсерков и темных чародеев.','Убейте 5 берсерков и 5 темных чародеев из племени Порочной Ветви в Джинта\'Алоре.','Скоро мы останемся единственными дворфами в этих стенах.','Вернитесь к Дорану Сталекрылому в Джинта\'Алор, что во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Смерть Порочной Ветви!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Дела идут отлично. Продолжай в том же духе и не сбрасывай обороты!$B$BБерсерки из племени Порочной Ветви сражаются как дикие звери, благодаря боевой ярости. Их темные чародеи призывают духов из иного мира! Поэтому нам надо избавиться от этих гнусных существ как можно скорее, $n, не забывай это.$B$BИди на средний ярус и убей берсерков и темных чародеев.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 5 берсерков и 5 темных чародеев из племени Порочной Ветви в Джинта\'Алоре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Скоро мы останемся единственными дворфами в этих стенах.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дорану Сталекрылому в Джинта\'Алор, что во Внутренних землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26499,'Дар Отца-Скалы','После того как Отца-Скалу захватили в плен, мои воины деморализованы. Обычно любой из них может одолеть пятерых каменных троггов. Но сейчас...$b$bЯ хочу, чтобы ты $gотправился:отправилась; на поле, окружающее город. Установи возле расположения защитников знамя короля Железной Мантии. Передай им его добрые слова и напомни о том, за что они борются.','Передайте слова Отца-Скалы 12 земельникам-защитникам.','Вернитесь к Крегу Крушителю Скал в Каменный очаг, что в Подземье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дар Отца-Скалы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','После того как Отца-Скалу захватили в плен, мои воины деморализованы. Обычно любой из них может одолеть пятерых каменных троггов. Но сейчас...$b$bЯ хочу, чтобы ты $gотправился:отправилась; на поле, окружающее город. Установи возле расположения защитников знамя короля Железной Мантии. Передай им его добрые слова и напомни о том, за что они борются.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Передайте слова Отца-Скалы 12 земельникам-защитникам.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Крегу Крушителю Скал в Каменный очаг, что в Подземье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26500,'Мы окружены','Нашей войне лет больше, чем вашему племени. Посмотрим, сможешь ли ты сделать хоть что-нибудь, |3-6($r).$b$bКаменные трогги – это ошибка титанов. В вашем мире они стали жертвами проклятия плоти. Но здесь, в Подземье, ты можешь видеть их истинную сущность.$b$bМы окружены. Ты не $gмог:могла; бы пойти и убить нескольких троггов для нас? Увидишь, из чего они на самом деле сделаны.','Убейте 12 каменных троггов – душителей.','Неплохое начало, хотя если ты собираешься спасти Отца-Скалу, тебе придется убить больше.$B$BГораздо больше.','Вернитесь к землелому Доломиту в Каменный очаг, что в Подземье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мы окружены',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нашей войне лет больше, чем вашему племени. Посмотрим, сможешь ли ты сделать хоть что-нибудь, |3-6($r).$b$bКаменные трогги – это ошибка титанов. В вашем мире они стали жертвами проклятия плоти. Но здесь, в Подземье, ты можешь видеть их истинную сущность.$b$bМы окружены. Ты не $gмог:могла; бы пойти и убить нескольких троггов для нас? Увидишь, из чего они на самом деле сделаны.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 каменных троггов – душителей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Неплохое начало, хотя если ты собираешься спасти Отца-Скалу, тебе придется убить больше.$B$BГораздо больше.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к землелому Доломиту в Каменный очаг, что в Подземье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26501,'Закрыть все выходы','Каменные трогги нашли способ вылезать на поверхность из-под наших домов!$b$bЯ приказал нашим геомантам заблокировать выходы из всех зданий, но чтобы завершить свои ритуалы по вызову оползней, им нужны реагенты и возможность не участвовать в битве.$b$bКогда будешь $gготов:готова;, поговори с генералом Гравием Долгопластом. Его можно найти к северу от Разбитой передовой.','Помогите земельникам-геомантам прекратить битву и дайте им оползневые реагенты, чтобы они смогли заблокировать выходы из оружейной, таверны, казарм и святилища.','Это хорошо. Теперь нам больше не нужно беспокоиться о том, что каменные трогги нападут на нас со спины.$B$BПосмотрим, чем ты сможешь помочь нам на передовой.','Поговорите с Гравием Долгопластом на Разбитой передовой в Подземье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Закрыть все выходы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Каменные трогги нашли способ вылезать на поверхность из-под наших домов!$b$bЯ приказал нашим геомантам заблокировать выходы из всех зданий, но чтобы завершить свои ритуалы по вызову оползней, им нужны реагенты и возможность не участвовать в битве.$b$bКогда будешь $gготов:готова;, поговори с генералом Гравием Долгопластом. Его можно найти к северу от Разбитой передовой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Помогите земельникам-геомантам прекратить битву и дайте им оползневые реагенты, чтобы они смогли заблокировать выходы из оружейной, таверны, казарм и святилища.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это хорошо. Теперь нам больше не нужно беспокоиться о том, что каменные трогги нападут на нас со спины.$B$BПосмотрим, чем ты сможешь помочь нам на передовой.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Гравием Долгопластом на Разбитой передовой в Подземье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26502,'Громокамни','К северу отсюда находится Разбитая передовая. Там идут самые тяжелые бои.$b$bОтправляйся в Каменный очаг и возьми столько громокамней, сколько сможешь. Они нужны нашим инженерам для катапульт.$b$bКогда наберешь достаточно, отнеси их Глину Грязновалу. На то, что он говорит, не обращай внимания. Он стар и сумасброден и должен был вернуться обратно в землю еще тысячи лет назад.','Соберите 12 громокамней.','<Глин бурчит себе под нос.>$B$BЭти подойдут. Положи их туда.$B$B<Земельник осматривает вас с головы до ног своим единственным глазом, а затем сплевывает грязь на землю.>$B$BУ меня найдется для тебя работка. Возможно.','<Старый земельник весь покрыт трещинами, очевидно, что ему очень много лет.>$B$BТы кто такой? Какое-то недоразумение из плоти? Проклятый – вот кто ты!$B$B<Глин плюет грязью.>$B$BИли сделай что-нибудь полезное, или убирайся с передовой.','Отнесите громокамни Глину Грязновалу на Разбитую передовую, что в Подземье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Громокамни',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','К северу отсюда находится Разбитая передовая. Там идут самые тяжелые бои.$b$bОтправляйся в Каменный очаг и возьми столько громокамней, сколько сможешь. Они нужны нашим инженерам для катапульт.$b$bКогда наберешь достаточно, отнеси их Глину Грязновалу. На то, что он говорит, не обращай внимания. Он стар и сумасброден и должен был вернуться обратно в землю еще тысячи лет назад.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 12 громокамней.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Глин бурчит себе под нос.>$B$BЭти подойдут. Положи их туда.$B$B<Земельник осматривает вас с головы до ног своим единственным глазом, а затем сплевывает грязь на землю.>$B$BУ меня найдется для тебя работка. Возможно.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Старый земельник весь покрыт трещинами, очевидно, что ему очень много лет.>$B$BТы кто такой? Какое-то недоразумение из плоти? Проклятый – вот кто ты!$B$B<Глин плюет грязью.>$B$BИли сделай что-нибудь полезное, или убирайся с передовой.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите громокамни Глину Грязновалу на Разбитую передовую, что в Подземье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26503,'Оценка угрозы','Эти жалкие ничтожные гноллы опять затевают какую-то пакость, я нутром чую! За последние две недели они развели тут прямо-таки небывалую возню! Боюсь, они собираются напасть на Приозерье.$B$BПрошу тебя: сходи в каждый из местных гнолльих лагерей и собери всю информацию, какую только сможешь найти. Лагеря есть к северу, востоку и юго-востоку отсюда. Все, что найдешь, – тащи сюда','Украдите военные планы гноллов, приказы гноллов и стратегическое руководство гноллов.','Так я и знал! Это Изувой затеял всю эту возню, но смешней всего то, что мы регулярно убиваем гноллов с таким именем. Не знаю уж, сколько там сыновей было у самого первого Изувоя, но, видно, не меньше сотни.$B$BНу что ж, придется еще одного Изувоя убить.$B$BПотом надо будет доложить мировому судье Соломону.','Вернитесь к капитану стражи Паркеру в Часовую башню, что в Красногорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оценка угрозы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти жалкие ничтожные гноллы опять затевают какую-то пакость, я нутром чую! За последние две недели они развели тут прямо-таки небывалую возню! Боюсь, они собираются напасть на Приозерье.$B$BПрошу тебя: сходи в каждый из местных гнолльих лагерей и собери всю информацию, какую только сможешь найти. Лагеря есть к северу, востоку и юго-востоку отсюда. Все, что найдешь, – тащи сюда',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Украдите военные планы гноллов, приказы гноллов и стратегическое руководство гноллов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так я и знал! Это Изувой затеял всю эту возню, но смешней всего то, что мы регулярно убиваем гноллов с таким именем. Не знаю уж, сколько там сыновей было у самого первого Изувоя, но, видно, не меньше сотни.$B$BНу что ж, придется еще одного Изувоя убить.$B$BПотом надо будет доложить мировому судье Соломону.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану стражи Паркеру в Часовую башню, что в Красногорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26504,'Разыскиваются: гноллы Красногорья','Именем королевской стражи Штормграда, все гноллы из юго-западного района Красногорья, также известного как Три Угла, подлежат истреблению.$B$BЕсли вы избавите эту местность от гноллов, доложите об этом капитану стражи Паркеру в Часовой башне.','Убейте 15 любых гноллов Красногорья на Трех Углах в Красногорье.','Вернитесь к капитану стражи Паркеру в Часовую башню, что в Красногорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разыскиваются: гноллы Красногорья',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Именем королевской стражи Штормграда, все гноллы из юго-западного района Красногорья, также известного как Три Угла, подлежат истреблению.$B$BЕсли вы избавите эту местность от гноллов, доложите об этом капитану стражи Паркеру в Часовой башне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 15 любых гноллов Красногорья на Трех Углах в Красногорье.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану стражи Паркеру в Часовую башню, что в Красногорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (26505,'Донесение Паркера','<Капитан стражи Паркер вручает вам донесение.>$B$BВот, $n. Отнеси мое донесение в Приозерье – это к северу от этой башни. Отдай его мировому судье Соломону и скажи ему: для того чтобы разобраться с гноллами, надо что-нибудь попроще. Взрывчатка, например, да побольше.$B$BДа, и на твоем месте я не сходил бы с дороги.$B$BЦелее будешь. А то вдруг ты этого не $gзнал:знала;. Теперь зато знаешь... Ладно, проехали!','Отправляйтесь в Красногорье и отдайте донесение Паркера мировому судье Соломону в Приозерье.','<Мировой судья Соломон надевает монокль.>$B$BА, ты не Конах. Что там у тебя?$B$B<Мировой судья Соломон берет у вас донесение Паркера.>$B$BДа чтоб ему лопнуть… Изувой? Еще ОДИН?!','Куда я подевал монокль?! Конах, это ты, что ли?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Донесение Паркера',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Капитан стражи Паркер вручает вам донесение.>$B$BВот, $n. Отнеси мое донесение в Приозерье – это к северу от этой башни. Отдай его мировому судье Соломону и скажи ему: для того чтобы разобраться с гноллами, надо что-нибудь попроще. Взрывчатка, например, да побольше.$B$BДа, и на твоем месте я не сходил бы с дороги.$B$BЦелее будешь. А то вдруг ты этого не $gзнал:знала;. Теперь зато знаешь... Ладно, проехали!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Красногорье и отдайте донесение Паркера мировому судье Соломону в Приозерье.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Мировой судья Соломон надевает монокль.>$B$BА, ты не Конах. Что там у тебя?$B$B<Мировой судья Соломон берет у вас донесение Паркера.>$B$BДа чтоб ему лопнуть… Изувой? Еще ОДИН?!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Куда я подевал монокль?! Конах, это ты, что ли?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26506,'Мясное рагу','Эй, |3-6($r), помоги мне! Стражники проголодались, а еда у нас вся кончилась! Они требуют моего знаменитого мясного рагу, но у меня совершенно нет продуктов. Не поможешь ли мне, а?$B$BМне нужны почки кровоклыка, потроха кондора и глаза тарантула. Вся эта живность водится прямехонько у этой вот башни, только осмотрись!','Соберите 4 глаза тарантула, потроха 4 кондоров и 4 почки кровоклыка.','ОТЛИЧНО!!! Прямо сейчас отправлю все это в кастрюлю, и скоро будет готов обед.$B$BСпасибо тебе,душечка!','Ну что, где там мои продукты?','Вернитесь к Дарси Паркеру в Часовую башню, что в Красногорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мясное рагу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эй, |3-6($r), помоги мне! Стражники проголодались, а еда у нас вся кончилась! Они требуют моего знаменитого мясного рагу, но у меня совершенно нет продуктов. Не поможешь ли мне, а?$B$BМне нужны почки кровоклыка, потроха кондора и глаза тарантула. Вся эта живность водится прямехонько у этой вот башни, только осмотрись!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 4 глаза тарантула, потроха 4 кондоров и 4 почки кровоклыка.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','ОТЛИЧНО!!! Прямо сейчас отправлю все это в кастрюлю, и скоро будет готов обед.$B$BСпасибо тебе,душечка!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, где там мои продукты?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дарси Паркеру в Часовую башню, что в Красногорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26507,'Окаменевшие лакомства','Окаменевшие летучие мыши.$b$bЭлементали такого размера разборчивы в еде. Но что-то лучшее ты вряд ли найдешь.$b$bК востоку отсюда водятся василиски. Подлетающих слишком близко летучих мышей они превращают в камень, а затем перекусывают ими, когда проголодаются. Так что окаменевшие мыши разбросаны там повсюду.$b$bНо я должен предупредить тебя... Если ты будешь уделять этому элементалю слишком много внимания, потом уже вряд ли от него отделаешься. Он очень сильно привяжется к тебе.','Соберите 12 окаменевших летучих мышей для Камешка.','<Камешек бросается на кучу окаменевших летучих мышей, зарывается в нее, кажется, он даже забыл о вашем существовании. Может быть, оно и к лучшему, если слова Кора правдивы.>','<Камешек смотрит на вас, его глаза сияют, с каждой минутой становясь все больше и круглее.>','Поговорите с Камешком. В последний раз вы видели его в Дрожащих Вершинах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Окаменевшие лакомства',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Окаменевшие летучие мыши.$b$bЭлементали такого размера разборчивы в еде. Но что-то лучшее ты вряд ли найдешь.$b$bК востоку отсюда водятся василиски. Подлетающих слишком близко летучих мышей они превращают в камень, а затем перекусывают ими, когда проголодаются. Так что окаменевшие мыши разбросаны там повсюду.$b$bНо я должен предупредить тебя... Если ты будешь уделять этому элементалю слишком много внимания, потом уже вряд ли от него отделаешься. Он очень сильно привяжется к тебе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 12 окаменевших летучих мышей для Камешка.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Камешек бросается на кучу окаменевших летучих мышей, зарывается в нее, кажется, он даже забыл о вашем существовании. Может быть, оно и к лучшему, если слова Кора правдивы.>',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Камешек смотрит на вас, его глаза сияют, с каждой минутой становясь все больше и круглее.>',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Камешком. В последний раз вы видели его в Дрожащих Вершинах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26508,'Ожерелье Ниды','Моя подруга Нида потеряла ожерелье, и мы никак не можем его отыскать. Мы весь день рыбачили на одном месте и уже обыскали все вокруг. Должно быть, оно упало в озеро, не иначе. Нам не разрешают купаться в озере: мама говорит, что там под водой живет какая-то злая зверюга... Но ты вроде бы не боишься злых зверюг, а?$B$BМожет, ты найдешь ее ожерелье?','Найдите ожерелье Ниды.','Привет. Мне так жалко моего ожерелья... Мне его папа подарил. Он говорит, что в озере живут чудовища. Ты с ними справишься?','Вернитесь к Ниде в Приозерье, что в Красногорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ожерелье Ниды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Моя подруга Нида потеряла ожерелье, и мы никак не можем его отыскать. Мы весь день рыбачили на одном месте и уже обыскали все вокруг. Должно быть, оно упало в озеро, не иначе. Нам не разрешают купаться в озере: мама говорит, что там под водой живет какая-то злая зверюга... Но ты вроде бы не боишься злых зверюг, а?$B$BМожет, ты найдешь ее ожерелье?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите ожерелье Ниды.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Привет. Мне так жалко моего ожерелья... Мне его папа подарил. Он говорит, что в озере живут чудовища. Ты с ними справишься?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ниде в Приозерье, что в Красногорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26509,'Незваный гость','Мой сад снова затоптан и разорен. И я знаю, что за скотина это сделала! Это проклятущий кабан, которого маршал Маррис прозвал Грубобрюхом.$B$BЯ теперь до следующего сезона не смогу посадить желтые нарциссы! Все, что нажито непосильным трудом, все погибло! Прикончи его! Прикончи и покажи мне его клык, тогда я с радостью награжу тебя. Говорят, эта свинина часто пасется в поле к юго-западу от Приозерья, но иногда вот, как видишь, забредает и в мой сад.','Убейте Грубобрюха и вырвите у него клык.','Вернитесь к Марти Джанроз в Приозерье, что в Красногорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Незваный гость',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мой сад снова затоптан и разорен. И я знаю, что за скотина это сделала! Это проклятущий кабан, которого маршал Маррис прозвал Грубобрюхом.$B$BЯ теперь до следующего сезона не смогу посадить желтые нарциссы! Все, что нажито непосильным трудом, все погибло! Прикончи его! Прикончи и покажи мне его клык, тогда я с радостью награжу тебя. Говорят, эта свинина часто пасется в поле к юго-западу от Приозерья, но иногда вот, как видишь, забредает и в мой сад.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Грубобрюха и вырвите у него клык.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Марти Джанроз в Приозерье, что в Красногорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26510,'Нужно готовиться!','У нас каждый день пропадают люди. Мы думаем, что их похищают гноллы, но никто не имеет ни малейшего понятия о том, куда они могут прятать пленников! Если ты хочешь помочь нам победить гноллов и разыскать наших людей, то тебе потребуется хорошая экипировка. Увы, у нас закончились ГНМ-передатчики, а без него мы никак не сможем связаться с тобой, пока ты будешь на задании.$B$BНаш последний рабочий ГНМ-передатчик на прошлой неделе уволокли мурлоки. Придется тебе пойти на озеро Безмолвия, что к востоку отсюда, и отыскать его там!','Отыщите ГНМ-передатчик.','Превосходно! Давай-ка сейчас тут кое-что подправим, и можно будет приниматься за дело.','Удалось найти ГНМ-передатчик?','Вернитесь к мировому судье Соломону в Приозерье, что в Красногорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нужно готовиться!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У нас каждый день пропадают люди. Мы думаем, что их похищают гноллы, но никто не имеет ни малейшего понятия о том, куда они могут прятать пленников! Если ты хочешь помочь нам победить гноллов и разыскать наших людей, то тебе потребуется хорошая экипировка. Увы, у нас закончились ГНМ-передатчики, а без него мы никак не сможем связаться с тобой, пока ты будешь на задании.$B$BНаш последний рабочий ГНМ-передатчик на прошлой неделе уволокли мурлоки. Придется тебе пойти на озеро Безмолвия, что к востоку отсюда, и отыскать его там!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщите ГНМ-передатчик.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Превосходно! Давай-ка сейчас тут кое-что подправим, и можно будет приниматься за дело.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось найти ГНМ-передатчик?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мировому судье Соломону в Приозерье, что в Красногорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26511,'Зачистка озера Безмолвия','Ты идешь в сторону озера Безмолвия? Тогда тебе, должно быть, любопытно будет узнать, что мы назначили награду за мурлочьи головы. Убей, сколько сможешь, а мы тебе заплатим. Любой мурлок сойдет – ты, главное, знай себе убивай без разбору.$B$BОзеро Безмолвия, кстати, находится прямо к востоку от Приозерья. Озеро. Вода там еще. Понимаешь?','Убейте 10 мурлоков на озере Безмолвия.','Наконец-то кто-то проучил этих мурлоков. Надеюсь, в следующий раз, когда они решат напасть на наш город, они передумают.$B$BУж мы-то с тобой знаем, что такого больше не случится, да?','Вернитесь к помощнику судьи Конаху в Приозерье, что в Красногорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зачистка озера Безмолвия',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты идешь в сторону озера Безмолвия? Тогда тебе, должно быть, любопытно будет узнать, что мы назначили награду за мурлочьи головы. Убей, сколько сможешь, а мы тебе заплатим. Любой мурлок сойдет – ты, главное, знай себе убивай без разбору.$B$BОзеро Безмолвия, кстати, находится прямо к востоку от Приозерья. Озеро. Вода там еще. Понимаешь?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 мурлоков на озере Безмолвия.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Наконец-то кто-то проучил этих мурлоков. Надеюсь, в следующий раз, когда они решат напасть на наш город, они передумают.$B$BУж мы-то с тобой знаем, что такого больше не случится, да?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к помощнику судьи Конаху в Приозерье, что в Красногорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (26512,'Настройка ГНМ-передатчика','ГНМ-передатчик, похоже, работает. Я его подключил, осталось только настроить на прием.$B$BТы выйди из Приозерья и иди по дороге на кладбище. Когда дойдешь дотуда, я попробую с тобой связаться.','Отправляйтесь на Приозерское кладбище, чтобы начать настройку ГНМ-передатчика.','<ГНМ-передатчик потрескивает и гудит.>$b$bСлышишь меня, $n? Он у тебя включен? А, вот, теперь я тебя вижу.$b$bЗа работу!','Работа ГНМ-передатчика на кладбище Приозерья проверена','Входящий сигнал чистый, слышимость отличная!','Мировой судья Соломон') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Настройка ГНМ-передатчика',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','ГНМ-передатчик, похоже, работает. Я его подключил, осталось только настроить на прием.$B$BТы выйди из Приозерья и иди по дороге на кладбище. Когда дойдешь дотуда, я попробую с тобой связаться.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь на Приозерское кладбище, чтобы начать настройку ГНМ-передатчика.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<ГНМ-передатчик потрескивает и гудит.>$b$bСлышишь меня, $n? Он у тебя включен? А, вот, теперь я тебя вижу.$b$bЗа работу!',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Работа ГНМ-передатчика на кладбище Приозерья проверена',`endtext_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Входящий сигнал чистый, слышимость отличная!',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Мировой судья Соломон',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26513,'Как ветром сдуло','На нас напали прошлой ночью, или позапрошлой... Не могу точно сказать, когда это было, потому что я не смыкаю глаз вот уже три дня и у меня уже ум за разум зашел.$B$BТак вот, значит, на нас напали гноллы и уволокли решительно все припасы! Как ветром сдуло: вроде было что-то, и вот уже ничего не осталось! Солдаты видели, как они побежали к каньонам, на северо-запад отсюда. Верни нам наши припасы, |3-6($c)!','Верните 8 ящиков с припасами Красногорья.','Большое тебе спасибо! Без тебя бы мы померли с голоду, или того хуже, нам пришлось бы идти и самим добывать себе пропитание.','Нашлись наши припасы?','Вернитесь к маршалу Маррису в Приозерье, что в Красногорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Как ветром сдуло',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На нас напали прошлой ночью, или позапрошлой... Не могу точно сказать, когда это было, потому что я не смыкаю глаз вот уже три дня и у меня уже ум за разум зашел.$B$BТак вот, значит, на нас напали гноллы и уволокли решительно все припасы! Как ветром сдуло: вроде было что-то, и вот уже ничего не осталось! Солдаты видели, как они побежали к каньонам, на северо-запад отсюда. Верни нам наши припасы, |3-6($c)!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните 8 ящиков с припасами Красногорья.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Большое тебе спасибо! Без тебя бы мы померли с голоду, или того хуже, нам пришлось бы идти и самим добывать себе пропитание.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Нашлись наши припасы?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к маршалу Маррису в Приозерье, что в Красногорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (26514,'Зачистка каньона','<ГНМ-передатчик гудит.>$B$BПервым твоим заданием будет пройтись по каньонам Красногорья, это к северу от Приозерья, и навести там хорошего шороху. Убивай каждого гнома, которого встретишь. Ой, я сказал гнома? Гнолла, конечно же. А в доказательство собирай гнолльи ошейники.$B$BНо должен предупредить тебя, $n: там могут быть еще и эттины. Мои разведчики в последнее время не раз встречали в каньонах больших кровожадных эттинов, так что если хочешь остаться $gжив:жива;, не попадайся им на пути.$B$BСоломон, отбой. Я буду на связи.','Соберите 10 ошейников гноллов Красногорья.','Осторожнее с каньонными эттинами!','Мировой судья Соломон','Эти гноллы, кажется, поумнели!','Мировой судья Соломон') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зачистка каньона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<ГНМ-передатчик гудит.>$B$BПервым твоим заданием будет пройтись по каньонам Красногорья, это к северу от Приозерья, и навести там хорошего шороху. Убивай каждого гнома, которого встретишь. Ой, я сказал гнома? Гнолла, конечно же. А в доказательство собирай гнолльи ошейники.$B$BНо должен предупредить тебя, $n: там могут быть еще и эттины. Мои разведчики в последнее время не раз встречали в каньонах больших кровожадных эттинов, так что если хочешь остаться $gжив:жива;, не попадайся им на пути.$B$BСоломон, отбой. Я буду на связи.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 ошейников гноллов Красногорья.',`objectives_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Осторожнее с каньонными эттинами!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Мировой судья Соломон',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Эти гноллы, кажется, поумнели!',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Мировой судья Соломон',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26515,'Месть Онго\'лонго','Деритесь с Онго\'лонго, пока он не освободится.','Вот это красота! Жаль, я этого не видел.','Вернитесь к Дорану Сталекрылому в Джинта\'Алор, что во Внутренних землях.','Разозли его, а потом отойди!','Онго\'лонго') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Месть Онго\'лонго',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Деритесь с Онго\'лонго, пока он не освободится.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот это красота! Жаль, я этого не видел.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дорану Сталекрылому в Джинта\'Алор, что во Внутренних землях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Разозли его, а потом отойди!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Онго\'лонго',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26516,'Победа наша!','Остались только самые стойкие и злобные из племени Порочной Ветви – кровопийцы и пожиратели душ, поклоняющиеся Хаккару.$B$BНе забывай, ты не просто сражаешься с троллями, $n. Ты выступаешь против темных сил, которые уничтожат эти земли, если мы их не остановим!$B$BНе давай им пощады!','Убейте 5 кровопийц и 5 пожирателей душ из племени Порочной Ветви в Джинта\'Алоре.','Мы вычистили эту дрянь! В Джинта\'Алоре теперь чистота и красота!','Вернитесь к Дорану Сталекрылому в Джинта\'Алор, что во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Победа наша!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Остались только самые стойкие и злобные из племени Порочной Ветви – кровопийцы и пожиратели душ, поклоняющиеся Хаккару.$B$BНе забывай, ты не просто сражаешься с троллями, $n. Ты выступаешь против темных сил, которые уничтожат эти земли, если мы их не остановим!$B$BНе давай им пощады!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 5 кровопийц и 5 пожирателей душ из племени Порочной Ветви в Джинта\'Алоре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мы вычистили эту дрянь! В Джинта\'Алоре теперь чистота и красота!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дорану Сталекрылому в Джинта\'Алор, что во Внутренних землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26517,'Судьбоносная вершина','Тебе придется идти на вершину, $n. Наши воины не пройдут через последние ворота. Они говорят, там как в могиле – ни звука, ни движения, никаких признаков жизни.$B$BОни думают, что это ловушка, но принимая во внимание то, что ты мне $gпринес:принесла;, я опасаюсь, что там скрыто что-то более мерзкое. Иди к алтарю и разузнай, что там творится. И принеси мне ЛЮБОЙ магический артефакт или идола, которого ты там найдешь. Понятно?','Соберите 8 идолов-пауков, убивая троллей племени Порочной Ветви на вершине Джинта\'Алора.','Мертвы? Все? Лежат вокруг алтаря? А на них лежали эти идолы-пауки?$B$BЭто Шадра. Королева пауков! Они призывают ее на помощь!','Вернитесь к Фраггару Громовой Мантии в Джинта\'Алор, что во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Судьбоносная вершина',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе придется идти на вершину, $n. Наши воины не пройдут через последние ворота. Они говорят, там как в могиле – ни звука, ни движения, никаких признаков жизни.$B$BОни думают, что это ловушка, но принимая во внимание то, что ты мне $gпринес:принесла;, я опасаюсь, что там скрыто что-то более мерзкое. Иди к алтарю и разузнай, что там творится. И принеси мне ЛЮБОЙ магический артефакт или идола, которого ты там найдешь. Понятно?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 идолов-пауков, убивая троллей племени Порочной Ветви на вершине Джинта\'Алора.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мертвы? Все? Лежат вокруг алтаря? А на них лежали эти идолы-пауки?$B$BЭто Шадра. Королева пауков! Они призывают ее на помощь!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фраггару Громовой Мантии в Джинта\'Алор, что во Внутренних землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26518,'Все дело в голове','Умбода Три Башки – это один из самых огромных троллей. Он ужасно жестокий, а еще он коллекционирует головы – что троллей, что дворфов! Пора ему ответить за все.$B$BРазыщи громилу на нижних ярусах и принеси мне его собственную голову!','Убейте Умбоду Три Башки и заберите его голову.','Ну и урод! Может, он отрезал головы, чтобы найти себе новую, посимпатичнее этой?','Ну, и где голова?','Вернитесь к Дорану Сталекрылому в Джинта\'Алор, что во Внутренних землях.','Принеси его башку Среднюю.','Умбода "Три башки"') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Все дело в голове',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Умбода Три Башки – это один из самых огромных троллей. Он ужасно жестокий, а еще он коллекционирует головы – что троллей, что дворфов! Пора ему ответить за все.$B$BРазыщи громилу на нижних ярусах и принеси мне его собственную голову!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Умбоду Три Башки и заберите его голову.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну и урод! Может, он отрезал головы, чтобы найти себе новую, посимпатичнее этой?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, и где голова?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дорану Сталекрылому в Джинта\'Алор, что во Внутренних землях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Принеси его башку Среднюю.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Умбода "Три башки"',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26519,'Тот, кто командует эттинами','Вы обнаружили некий документ, написанный полуграмотным гноллом:$B$BБРАТЫ ИСУВОЯ, СЛУШОЙТИ ГРИЗНАЛАПА! ГРИЗНАЛАПУ ДАЛИ ОРКИ СФЕРУ! ГРИЗНАЛАП УПРОВЛЯИТ ЭТТИНАМИ! ГРИЗНАЛАП УБЙОТ ЛЮДИШКАВ! ПРИХАДИТИ, ПАЛУЧИТИ ОТ ГРИЗНАЛАПА ФПИЩЕРИ РЕТБАНА. ПИЩЕРА НАЗАПАДИ, СПРЯТАНА ФКАНЙОНИ!$B$B<В качестве подписи стоит отпечаток лапы.>$B$B<Еще у этого свитка, кажется, оторван кусок.>$B$BВозможно, вам стоит этим заняться.','Убейте Ардо Грязнолапа.','<Вы касаетесь сферы, и она шипит.>','Воспользуйтесь сферой контроля эттина.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тот, кто командует эттинами',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы обнаружили некий документ, написанный полуграмотным гноллом:$B$BБРАТЫ ИСУВОЯ, СЛУШОЙТИ ГРИЗНАЛАПА! ГРИЗНАЛАПУ ДАЛИ ОРКИ СФЕРУ! ГРИЗНАЛАП УПРОВЛЯИТ ЭТТИНАМИ! ГРИЗНАЛАП УБЙОТ ЛЮДИШКАВ! ПРИХАДИТИ, ПАЛУЧИТИ ОТ ГРИЗНАЛАПА ФПИЩЕРИ РЕТБАНА. ПИЩЕРА НАЗАПАДИ, СПРЯТАНА ФКАНЙОНИ!$B$B<В качестве подписи стоит отпечаток лапы.>$B$B<Еще у этого свитка, кажется, оторван кусок.>$B$BВозможно, вам стоит этим заняться.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Ардо Грязнолапа.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Вы касаетесь сферы, и она шипит.>',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Воспользуйтесь сферой контроля эттина.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26520,'Спасение штейгера Ослоу','Подчините себе каньонного эттина при помощи сферы контроля эттина, а потом заставьте его убрать огромный булыжник со штейгера Ослоу в Приозерье.','Вернитесь с докладом к маршалу Маррису в Приозерье, что в Красногорье.','Каньонные эттины злые и ужасные.','Каньонный эттин') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спасение штейгера Ослоу',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Подчините себе каньонного эттина при помощи сферы контроля эттина, а потом заставьте его убрать огромный булыжник со штейгера Ослоу в Приозерье.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь с докладом к маршалу Маррису в Приозерье, что в Красногорье.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Каньонные эттины злые и ужасные.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Каньонный эттин',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26521,'Лики зла','Тролли из клана Порочной Ветви развесили маски тики по стенам Джинта\'Алора. Мы не потерпим их черной магии и злобной ворожбы!$B$BНастало время послать им сообщение и снять защиту одновременно! Возьми факел, |3-6($c). Подожги маски и полюбуйся, как они горят. Когда они увидят поверженных идолов, то сразу поймут, что Громовой Молот не намерен мириться их присутствием!','Используйте факел тики, чтобы поджечь 8 ритуальных масок тики в Джинта\'Алоре.','Как хорошо разгорелось. Пусть огонь покажет им истинную цену их злобы и жестокости!','Вернитесь к Фраггару Громовой Мантии в Джинта\'Алор, что во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лики зла',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тролли из клана Порочной Ветви развесили маски тики по стенам Джинта\'Алора. Мы не потерпим их черной магии и злобной ворожбы!$B$BНастало время послать им сообщение и снять защиту одновременно! Возьми факел, |3-6($c). Подожги маски и полюбуйся, как они горят. Когда они увидят поверженных идолов, то сразу поймут, что Громовой Молот не намерен мириться их присутствием!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте факел тики, чтобы поджечь 8 ритуальных масок тики в Джинта\'Алоре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Как хорошо разгорелось. Пусть огонь покажет им истинную цену их злобы и жестокости!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фраггару Громовой Мантии в Джинта\'Алор, что во Внутренних землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26522,'Лики зла','Клан Порочной Ветви развесил маски тики по стенам крепости Джинта\'Алор. Но эти рожи недолго будут приглядывать за ними!$B$BВозьми факел, |3-6($c). Подожги маски, а я полюбуюсь, как сгорают их стражи и заклятья, а вместе с дымом растворяется черная магия вуду.','Используйте факел тики, чтобы поджечь 8 ритуальных масок тики в Джинта\'Алоре.','Вернитесь к Котонге в Джинта\'Алор, что во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лики зла',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Клан Порочной Ветви развесил маски тики по стенам крепости Джинта\'Алор. Но эти рожи недолго будут приглядывать за ними!$B$BВозьми факел, |3-6($c). Подожги маски, а я полюбуюсь, как сгорают их стражи и заклятья, а вместе с дымом растворяется черная магия вуду.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте факел тики, чтобы поджечь 8 ритуальных масок тики в Джинта\'Алоре.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Котонге в Джинта\'Алор, что во Внутренних землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26523,'Быстролапые паучата','Знаешь, что я заметил? Джинта\'Алор просто кишит пауками. Самые маленькие из них – размером с твою руку. Не то чтобы это было необычным для Внутренних земель, но что-то тут не так.$B$BЕсли честно, то я не верю в то, что тролли держат у себя домашних любимцев. Они явно что-то замышляют. Принеси мне этих пауков. Живьем. Посмотрим, что скажут духи...','Соберите 8 быстролапых паучков в Джинта\'Алоре.','Клянусь бородой Кудрана! Они не похожи на обычных пауков. Тут явно поработала черная магия.','Посмотрим, что у тебя...','Вернитесь к Фраггару Громовой Мантии в Джинта\'Алор, что во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Быстролапые паучата',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Знаешь, что я заметил? Джинта\'Алор просто кишит пауками. Самые маленькие из них – размером с твою руку. Не то чтобы это было необычным для Внутренних земель, но что-то тут не так.$B$BЕсли честно, то я не верю в то, что тролли держат у себя домашних любимцев. Они явно что-то замышляют. Принеси мне этих пауков. Живьем. Посмотрим, что скажут духи...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 быстролапых паучков в Джинта\'Алоре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Клянусь бородой Кудрана! Они не похожи на обычных пауков. Тут явно поработала черная магия.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Посмотрим, что у тебя...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фраггару Громовой Мантии в Джинта\'Алор, что во Внутренних землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26524,'Темные сосуды','Тролли племени Порочной Ветви поклоняются темному и кровавому богу Хаккару. Он был мерзкой и вредоносной сущностью, которая когда-то давно почти прорвалась в наш мир, но была побеждена.$B$BПлемя Порочной Ветви все еще кипятит свои котлы, которые были наполнены кровью много лет назад. То ли они так поклоняются давно погибшему духу, то ли замыслили какую-то новую подлость.$B$BПринеси мне эти сосуды, $n. Нам надо исследовать их с помощью пауков и узнать, что здесь происходит!','Соберите 5 Сосудов с порченой кровью в Джинта\'Алоре.','Вернитесь к Фраггару Громовой Мантии в Джинта\'Алор, что во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Темные сосуды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тролли племени Порочной Ветви поклоняются темному и кровавому богу Хаккару. Он был мерзкой и вредоносной сущностью, которая когда-то давно почти прорвалась в наш мир, но была побеждена.$B$BПлемя Порочной Ветви все еще кипятит свои котлы, которые были наполнены кровью много лет назад. То ли они так поклоняются давно погибшему духу, то ли замыслили какую-то новую подлость.$B$BПринеси мне эти сосуды, $n. Нам надо исследовать их с помощью пауков и узнать, что здесь происходит!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 5 Сосудов с порченой кровью в Джинта\'Алоре.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фраггару Громовой Мантии в Джинта\'Алор, что во Внутренних землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26525,'Ядовитые секреты','Если жертвы уже принесены, то скоро Шадра начнет перебираться в наш мир. Та пещера, наверное, уже полна ее отродьями.$B$BНе давай им расползтись, $n. Убивай всех мерзких пауков, которых встретишь на пути!','Убейте 8 паучат Шадры.','Отлично поработали. Надеюсь, эта гадость никогда больше не будет ползать по нашей земле.','Вернитесь к Фраггару Громовой Мантии в Джинта\'Алор, что во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ядовитые секреты',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если жертвы уже принесены, то скоро Шадра начнет перебираться в наш мир. Та пещера, наверное, уже полна ее отродьями.$B$BНе давай им расползтись, $n. Убивай всех мерзких пауков, которых встретишь на пути!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 паучат Шадры.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично поработали. Надеюсь, эта гадость никогда больше не будет ползать по нашей земле.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фраггару Громовой Мантии в Джинта\'Алор, что во Внутренних землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26526,'Охота на хранительницу','Шадра, королева пауков... Дух тьмы и смерти! Если они принесли жертвы, значит, пытаются призвать ее в наш мир.$B$BЕсли племя Порочной Ветви проводит ритуалы, я не потерплю, чтобы они спокойно их завершили!$B$BПроверь пещеру под алтарем на вершине Джинта\'Алора. Там может прятаться одна из хранительниц Шадры. Убей ее и принеси то, что она охраняет, мне, чтобы мы могли понять, что тут происходит.','Убейте Морта\'гью Хранительницу и заберите Табличку Шадры.','Вернитесь к Фраггару Громовой Мантии в Джинта\'Алор, что во Внутренних землях.','Без сомнений, она будет прятаться в глубине пещеры.','Морта\'гья Хранительница') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота на хранительницу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Шадра, королева пауков... Дух тьмы и смерти! Если они принесли жертвы, значит, пытаются призвать ее в наш мир.$B$BЕсли племя Порочной Ветви проводит ритуалы, я не потерплю, чтобы они спокойно их завершили!$B$BПроверь пещеру под алтарем на вершине Джинта\'Алора. Там может прятаться одна из хранительниц Шадры. Убей ее и принеси то, что она охраняет, мне, чтобы мы могли понять, что тут происходит.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Морта\'гью Хранительницу и заберите Табличку Шадры.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фраггару Громовой Мантии в Джинта\'Алор, что во Внутренних землях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Без сомнений, она будет прятаться в глубине пещеры.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Морта\'гья Хранительница',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26527,'Укротитель грифонов Разящий Коготь','Если бы у меня было право, я бы разбил эту табличку в щепки, но это не мне решать. Надо показать это укротителю грифонов Разящему Когтю.$B$BВозвращайся с этой табличкой на Заоблачный пик. Укротителя грифонов найдешь в вольере, он там занимается с грифонами.$B$BПоспеши, и ни на минуту не выпускай табличку из рук!','Отнесите табличку Шадры укротителю грифонов Разящему Когтю.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Укротитель грифонов Разящий Коготь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если бы у меня было право, я бы разбил эту табличку в щепки, но это не мне решать. Надо показать это укротителю грифонов Разящему Когтю.$B$BВозвращайся с этой табличкой на Заоблачный пик. Укротителя грифонов найдешь в вольере, он там занимается с грифонами.$B$BПоспеши, и ни на минуту не выпускай табличку из рук!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите табличку Шадры укротителю грифонов Разящему Когтю.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26528,'Глаз Шадры','Укротитель грифонов Разящий Коготь отправил меня сюда, чтобы разделаться с Шадрой, королевой пауков. Захватить Джинта\'Алор недостаточно... тролли могут перегруппироваться и призвать это существо еще раз, когда мы не будем этого ожидать. Помоги мне: собери артефакты и убей троллей, которые встанут у тебя на пути.$B$BСначала мы соберем артефакты, затем сами призовем Шадру в этот мир, а потом забьем эту тварь нашими молотками.$B$BПервое, что нам понадобится – это глаз Шадры, его держат под охраной в Агол\'вате, это к северу отсюда.','Найдите в Агол\'вате глаз Шадры.','Ну что, табличка оказалась верной? Нашелся тот глаз?','Вернитесь к Гилде Призывающей Облака в Сторожку Кель\'Данил, что во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Глаз Шадры',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Укротитель грифонов Разящий Коготь отправил меня сюда, чтобы разделаться с Шадрой, королевой пауков. Захватить Джинта\'Алор недостаточно... тролли могут перегруппироваться и призвать это существо еще раз, когда мы не будем этого ожидать. Помоги мне: собери артефакты и убей троллей, которые встанут у тебя на пути.$B$BСначала мы соберем артефакты, затем сами призовем Шадру в этот мир, а потом забьем эту тварь нашими молотками.$B$BПервое, что нам понадобится – это глаз Шадры, его держат под охраной в Агол\'вате, это к северу отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите в Агол\'вате глаз Шадры.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, табличка оказалась верной? Нашелся тот глаз?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гилде Призывающей Облака в Сторожку Кель\'Данил, что во Внутренних землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26529,'Зуб Шадры','Теперь нам потребуется зуб Шадры.$B$BОн находится в Ползучих руинах к востоку отсюда, и охраняют его дети самой Шадры. Это премерзкие пауки размером с дворфа, и вдвое сильнее. А еще они очень ядовиты, $n... так что осторожнее.','Найдите зуб Шадры в Ползучих руинах.','Ну вот… Осталось последнее, парень.','Вернитесь к Гилде Призывающей Облака в Сторожку Кель\'Данил.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зуб Шадры',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь нам потребуется зуб Шадры.$B$BОн находится в Ползучих руинах к востоку отсюда, и охраняют его дети самой Шадры. Это премерзкие пауки размером с дворфа, и вдвое сильнее. А еще они очень ядовиты, $n... так что осторожнее.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите зуб Шадры в Ползучих руинах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну вот… Осталось последнее, парень.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гилде Призывающей Облака в Сторожку Кель\'Данил.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26530,'Панцирь Шадры','Чтобы раз и навсегда покончить с Шадрой, нам нужен еще один предмет.$B$BПанцирь Шадры хранится у последней живущей ныне верховной жрицы паучьего бога, зовут ее Квиага Хранительница. Ее можно найти на вершине алтаря Зула, под охраной фанатиков.$B$BТебе нужно будет забраться на самый верх алтаря и убить ее! Потом заберешь у нее панцирь и принесешь мне.','Убейте Квиагу Хранительницу и заберите у нее панцирь Шадры.','Молодец, девчушка! Теперь все готово!','Вернитесь к Гилде Призывающей Облака в Сторожку Кель\'Данил, что во Внутренних землях.','Квиага – преданная ученица Шадры. Она не расстанется с панцирем без боя.','Квиага Хранительница') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Панцирь Шадры',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чтобы раз и навсегда покончить с Шадрой, нам нужен еще один предмет.$B$BПанцирь Шадры хранится у последней живущей ныне верховной жрицы паучьего бога, зовут ее Квиага Хранительница. Ее можно найти на вершине алтаря Зула, под охраной фанатиков.$B$BТебе нужно будет забраться на самый верх алтаря и убить ее! Потом заберешь у нее панцирь и принесешь мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Квиагу Хранительницу и заберите у нее панцирь Шадры.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Молодец, девчушка! Теперь все готово!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гилде Призывающей Облака в Сторожку Кель\'Данил, что во Внутренних землях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Квиага – преданная ученица Шадры. Она не расстанется с панцирем без боя.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Квиага Хранительница',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26531,'Призыв Шадры','Наши лучшие воины готовы, идол собран... Пора, $n.$B$BВот как мы поступим. Ты $gпервым:первой; отправишься на юго-запад, в Шадра\'Алор, и возьмешь с собой идола. С этим идолом тебе надо будет по очереди пробраться в каждый из трех храмов, перебив всех троллей-стражников.$B$BКогда ты закончишь, Шадра придет в наш мир, и мы будем поджидать ее, с пылающей в наших сердцах яростью. Поговори с моими ребятами на месте, как только закончишь ритуал!','Используйте идол Шадры в северо-западном, юго-западном и восточном храмах в Шадра\'Алоре.','Разящий Коготь и его ребята c тобой! Вперед же!','Вернитесь к дозорному клана Громового Молота в Шадра\'Алор, что во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Призыв Шадры',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наши лучшие воины готовы, идол собран... Пора, $n.$B$BВот как мы поступим. Ты $gпервым:первой; отправишься на юго-запад, в Шадра\'Алор, и возьмешь с собой идола. С этим идолом тебе надо будет по очереди пробраться в каждый из трех храмов, перебив всех троллей-стражников.$B$BКогда ты закончишь, Шадра придет в наш мир, и мы будем поджидать ее, с пылающей в наших сердцах яростью. Поговори с моими ребятами на месте, как только закончишь ритуал!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте идол Шадры в северо-западном, юго-западном и восточном храмах в Шадра\'Алоре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Разящий Коготь и его ребята c тобой! Вперед же!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к дозорному клана Громового Молота в Шадра\'Алор, что во Внутренних землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26532,'Шадра – королева пауков','Не теряй времени, $n! Сейчас она вылезет из воды!$B$BУкротитель грифонов Разящий Коготь сейчас подойдет вместе со своими ребятами. Покажем этой букашке небо в алмазах!','Убейте Шадру – королеву пауков.','Вернитесь к укротителю грифонов Разящему Когтю в Заоблачный пик, что во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Шадра – королева пауков',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не теряй времени, $n! Сейчас она вылезет из воды!$B$BУкротитель грифонов Разящий Коготь сейчас подойдет вместе со своими ребятами. Покажем этой букашке небо в алмазах!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Шадру – королеву пауков.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к укротителю грифонов Разящему Когтю в Заоблачный пик, что во Внутренних землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26533,'Тайна Занзила','Давным-давно Гурубаши изгнали из Зул\'Гуруба своего соплеменника – тролля по имени Занзил. По какой причине – неизвестно, но могу предположить, что это было связано с его привычкой давать всем подряд свои сильнодействующие лекарства, влияющие на поведение. Вскоре жрецы Гурубаши и их кровожадный бог были свергнуты, а Занзил Отверженный жив до сих пор.$B$BА с ним и его лекарства.$B$BЯ бы хотел их получить. Отправляйся на юго-восток к зомби.','Добудьте 5 сосудов со смесью Занзила.','<Джаспер внимательно рассматривает содержимое сосуда.>$B$BЭта смесь просто... Не пойму, что это. Видимо, придется провести кое-какие химические опыты.','Замечательно... И ты не стал зомби. Это хорошо.$B$BА, ну-у... Ладно. Просто... Есть риск заражения. Я разве тебя не предупредил?','Вернитесь к смешивателю Джасперу в Укрытие Кофельнагель на мысе Тернистой долины.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тайна Занзила',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Давным-давно Гурубаши изгнали из Зул\'Гуруба своего соплеменника – тролля по имени Занзил. По какой причине – неизвестно, но могу предположить, что это было связано с его привычкой давать всем подряд свои сильнодействующие лекарства, влияющие на поведение. Вскоре жрецы Гурубаши и их кровожадный бог были свергнуты, а Занзил Отверженный жив до сих пор.$B$BА с ним и его лекарства.$B$BЯ бы хотел их получить. Отправляйся на юго-восток к зомби.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 5 сосудов со смесью Занзила.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Джаспер внимательно рассматривает содержимое сосуда.>$B$BЭта смесь просто... Не пойму, что это. Видимо, придется провести кое-какие химические опыты.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Замечательно... И ты не стал зомби. Это хорошо.$B$BА, ну-у... Ладно. Просто... Есть риск заражения. Я разве тебя не предупредил?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к смешивателю Джасперу в Укрытие Кофельнагель на мысе Тернистой долины.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26534,'Убойный напиток','Прибывающие в Укрытие Кофельнагель подписывают документы об отказе от всяческих прав, и поэтому мы на законных основаниях можем производить над ними базовые эксперименты. Чем мы сейчас и займемся.$B$BНа этот раз травить постояльцев не будем. Оно, знаешь ли, и для бизнеса лучше...$B$B<Джаспер наполняет кувшин смесью Занзила и колотым льдом.>$B$BЮго-восточная башня Укрытия временно служит тюрьмой. Мы ее называем "Кофельнагельской кутузкой". Угости этим пойлом арестантов, а потом расскажи мне, что с ними сталось.','Угостите "Джангл-айсом" Джаспера Гмургла, Оргуса и капитана Бартоломью Мягкоборода.','Да что ты говоришь! Интересно... Очень интересно. В таком случае...$B$BУж не знаю, как оно действует, хотя это, в общем-то, и неважно. Но мне нужен этот рецепт!','Вернитесь к смешивателю Джасперу в Укрытие Кофельнагель на мысе Тернистой долины.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Убойный напиток',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прибывающие в Укрытие Кофельнагель подписывают документы об отказе от всяческих прав, и поэтому мы на законных основаниях можем производить над ними базовые эксперименты. Чем мы сейчас и займемся.$B$BНа этот раз травить постояльцев не будем. Оно, знаешь ли, и для бизнеса лучше...$B$B<Джаспер наполняет кувшин смесью Занзила и колотым льдом.>$B$BЮго-восточная башня Укрытия временно служит тюрьмой. Мы ее называем "Кофельнагельской кутузкой". Угости этим пойлом арестантов, а потом расскажи мне, что с ними сталось.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Угостите "Джангл-айсом" Джаспера Гмургла, Оргуса и капитана Бартоломью Мягкоборода.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да что ты говоришь! Интересно... Очень интересно. В таком случае...$B$BУж не знаю, как оно действует, хотя это, в общем-то, и неважно. Но мне нужен этот рецепт!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к смешивателю Джасперу в Укрытие Кофельнагель на мысе Тернистой долины.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26535,'Рецепт катастрофы','Рецепт Занзила нужен мне сейчас больше, чем когда-либо. Он должен быть у одного из прислужников Занзила в руинах Абораза. Отправляйся на восток, на другую сторону мыса и достань мне этот рецепт!','Добудьте рецептуру Занзила у одного из прислужников Занзила в руинах Абораза.','Потрясающе! Только подумай обо всех возможных применениях!$B$BЧтобы внести ясность, я не собираюсь использовать этот рецепт для создания армии рабов или чего-то вроде этого. Нет, нет… Я гораздо больше заинтересован в экспериментах с ограми!','Он использовал звездолист? Мне кажется, звездолист.$B$BНет, погоди... янтарные желуди! Должно быть, это янтарные желуди.','Вернитесь к смешивателю Джасперу в Укрытие Кофельнагель на мысе Тернистой долины.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рецепт катастрофы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Рецепт Занзила нужен мне сейчас больше, чем когда-либо. Он должен быть у одного из прислужников Занзила в руинах Абораза. Отправляйся на восток, на другую сторону мыса и достань мне этот рецепт!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте рецептуру Занзила у одного из прислужников Занзила в руинах Абораза.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Потрясающе! Только подумай обо всех возможных применениях!$B$BЧтобы внести ясность, я не собираюсь использовать этот рецепт для создания армии рабов или чего-то вроде этого. Нет, нет… Я гораздо больше заинтересован в экспериментах с ограми!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Он использовал звездолист? Мне кажется, звездолист.$B$BНет, погоди... янтарные желуди! Должно быть, это янтарные желуди.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к смешивателю Джасперу в Укрытие Кофельнагель на мысе Тернистой долины.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26536,'Ревущий водопад','Мы с Арнольдом рыбачим в Штормграде и окрестностях уже долгие годы – конечно, у нас есть любимые места. Лично я предпочитаю Ревущий водопад.$B$BЭто в Элвиннском лесу, к югу от Штормграда. Ревущий водопад – лучшее место для ловли лилового окуня. Мне он нигде больше и не встречался, только в этом водопаде. Правда, нам с Арнольдом нынче туда не выбраться. Может, ты сходишь туда и наловишь таких окушков?','Поймайте 4 лиловых окуней в Ревущем водопаде к югу от Штормграда. Возвращайтесь с уловом к Катрин Лиланд.','Водопад отыскал?','Отнесите лиловых окушков Катрин Лиланд в Штормград.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ревущий водопад',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы с Арнольдом рыбачим в Штормграде и окрестностях уже долгие годы – конечно, у нас есть любимые места. Лично я предпочитаю Ревущий водопад.$B$BЭто в Элвиннском лесу, к югу от Штормграда. Ревущий водопад – лучшее место для ловли лилового окуня. Мне он нигде больше и не встречался, только в этом водопаде. Правда, нам с Арнольдом нынче туда не выбраться. Может, ты сходишь туда и наловишь таких окушков?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поймайте 4 лиловых окуней в Ревущем водопаде к югу от Штормграда. Возвращайтесь с уловом к Катрин Лиланд.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Водопад отыскал?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите лиловых окушков Катрин Лиланд в Штормград.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26537,'Убей их!','Я хочу, чтобы ты $gпошел:пошла; туда и $gприкончил:прикончила; их.$b$bБерсерков, земледробителей, наездников-убийц – неважно! Я хочу, чтобы эти каменные трогги были раздроблены!','Убейте 12 любых каменных троггов на Разбитой передовой.','Неплохая работа, но теперь мне ясно, что придется решать эту проблему немного другим путем.','Вернитесь к Гравию Долгопласту на Разбитую передовую в Подземье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Убей их!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я хочу, чтобы ты $gпошел:пошла; туда и $gприкончил:прикончила; их.$b$bБерсерков, земледробителей, наездников-убийц – неважно! Я хочу, чтобы эти каменные трогги были раздроблены!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 любых каменных троггов на Разбитой передовой.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Неплохая работа, но теперь мне ясно, что придется решать эту проблему немного другим путем.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гравию Долгопласту на Разбитую передовую в Подземье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26538,'Предметы первой помощи','Когда Сумеречные войска атаковали наш воздушный флот, мы потеряли многих воинов. А те, кто выжил, израненные и обожженные, сейчас плывут к тому, что осталось от флота. Им нужна поддержка с берега!$B$BВ порту Драконьей Пасти должен быть какой-нибудь знахарь или шаман, готовый протянуть руку помощи сородичам. Иди на берег и постарайся добыть лекарства!','Найдите лекаря на побережье в порту Драконьей Пасти.','<Грегор почтительно кланяется Зеле.>$B$BЕсли этого хочет Зела, ты получишь свои припасы. Только не говори вождю Драконьей Пасти...','Вернитесь в порт Драконьей Пасти на Сумеречном нагорье и еще раз поговорите с Грегором.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Предметы первой помощи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда Сумеречные войска атаковали наш воздушный флот, мы потеряли многих воинов. А те, кто выжил, израненные и обожженные, сейчас плывут к тому, что осталось от флота. Им нужна поддержка с берега!$B$BВ порту Драконьей Пасти должен быть какой-нибудь знахарь или шаман, готовый протянуть руку помощи сородичам. Иди на берег и постарайся добыть лекарства!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите лекаря на побережье в порту Драконьей Пасти.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Грегор почтительно кланяется Зеле.>$B$BЕсли этого хочет Зела, ты получишь свои припасы. Только не говори вождю Драконьей Пасти...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь в порт Драконьей Пасти на Сумеречном нагорье и еще раз поговорите с Грегором.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26539,'Затянувшиеся переговоры','Поговорите с Орнаком в порту Драконьей Пасти. Хорзог может быстро доставить вас на побережье.','Поговорите с Орнаком в порту Драконьей Пасти. Хорзог может быстро доставить вас на побережье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Затянувшиеся переговоры',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Орнаком в порту Драконьей Пасти. Хорзог может быстро доставить вас на побережье.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Орнаком в порту Драконьей Пасти. Хорзог может быстро доставить вас на побережье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26540,'Опасное сострадание','Кровь дракона?! Не стоит говорить нашим союзникам, красным драконам, о том, что мы ее использовали.$B$BИ все-таки это мощная магическая штука... Скоро мы поставим наших бойцов на ноги.','Ты ведь поможешь нашим раненым?','Отнесите ящик бинтов Драконьей Пасти полководцу Кроггу, который находится в море рядом с портом Драконьей Пасти.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Опасное сострадание',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Кровь дракона?! Не стоит говорить нашим союзникам, красным драконам, о том, что мы ее использовали.$B$BИ все-таки это мощная магическая штука... Скоро мы поставим наших бойцов на ноги.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты ведь поможешь нашим раненым?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите ящик бинтов Драконьей Пасти полководцу Кроггу, который находится в море рядом с портом Драконьей Пасти.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (26542,'Воззвание к героям: Внутренние земли!','Отправляйтесь в Заоблачный пик во Внутренних землях и поговорите с укротителем грифонов Разящим Когтем.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Воззвание к героям: Внутренние земли!',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Заоблачный пик во Внутренних землях и поговорите с укротителем грифонов Разящим Когтем.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26543,'Шустрые моллюски','Нет ничего вкуснее, чем мясо чудовищного моллюска, $n. А у меня столько работы в эти дни, что я никак не могу выбраться на их нерестилище. Может быть, сходишь туда и принесешь мне этой вкуснятины?$B$BМоллюски водятся у берега на восточном побережье Дуротара. В самой гавани Оргриммара их должно быть вдосталь.','Добудьте 10 кусков мяса чудовищного моллюска на восточном побережье к югу от Оргриммара. Возвращайтесь к Разгару с добычей.','Отнесите мясо чудовищного моллюска Разгару в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Шустрые моллюски',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нет ничего вкуснее, чем мясо чудовищного моллюска, $n. А у меня столько работы в эти дни, что я никак не могу выбраться на их нерестилище. Может быть, сходишь туда и принесешь мне этой вкуснятины?$B$BМоллюски водятся у берега на восточном побережье Дуротара. В самой гавани Оргриммара их должно быть вдосталь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 10 кусков мяса чудовищного моллюска на восточном побережье к югу от Оргриммара. Возвращайтесь к Разгару с добычей.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите мясо чудовищного моллюска Разгару в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (26544,'Они поумнели...','<ГНМ-передатчик потрескивает и щелкает.>$B$BКажется, орки из клана Черной горы наконец-то поумнели. Мне сообщили, что они решили объединиться с гноллами для совместного нападения. Мне нужны детали, $n!$B$BСтупай проверь пещеры Ретбана, это в западной части каньонов Красногорья. Ищи орков с темной кожей, убивай всякого, что тебе встретится, а потом обыщи их тела на предмет информации.$B$BСоломон, отбой.','Разыщите послание орков Черной горы.','Вернитесь к мировому судье Соломону в Приозерье, что в Красногорье.','Орки Черной горы – это беда.','Мировой судья Соломон','Соломон, безупречно владею оркским.','Мировой судья Соломон') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Они поумнели...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<ГНМ-передатчик потрескивает и щелкает.>$B$BКажется, орки из клана Черной горы наконец-то поумнели. Мне сообщили, что они решили объединиться с гноллами для совместного нападения. Мне нужны детали, $n!$B$BСтупай проверь пещеры Ретбана, это в западной части каньонов Красногорья. Ищи орков с темной кожей, убивай всякого, что тебе встретится, а потом обыщи их тела на предмет информации.$B$BСоломон, отбой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите послание орков Черной горы.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мировому судье Соломону в Приозерье, что в Красногорье.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Орки Черной горы – это беда.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Мировой судья Соломон',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Соломон, безупречно владею оркским.',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Мировой судья Соломон',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26545,'Изувой должен умереть!','<ГНМ-передатчик гудит.>$B$BТебе надо найти Изувоя, $n. Он должен ошиваться где-то в северной части каньонов Красногорья. Убей это животное и посмотри, нет ли у него при себе планов вторжения орков Черной горы. Если найдешь – неси их мне в Приозерскую ратушу.$B$BСоломон связь закончил.','Убейте Изувоя и найдите у него планы вторжения орков Черной горы.','<Мировой судья Соломон берет у вас планы и принимается их читать.?$B$BАрмия Темношкуров?! Да чтоб их разорвало, этих орков! В этих планах говорится о том, что гноллы и орки стягивают свои силы на восток. Видно, Гат\'Илзогг, вождь орков Черной горы, хочет провести свою армию через Приозерье и напасть сразу на Штормград!','Вернитесь к мировому судье Соломону в Приозерье, что в Красногорье.','Изувой, сын Изувоя','Изувой') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Изувой должен умереть!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<ГНМ-передатчик гудит.>$B$BТебе надо найти Изувоя, $n. Он должен ошиваться где-то в северной части каньонов Красногорья. Убей это животное и посмотри, нет ли у него при себе планов вторжения орков Черной горы. Если найдешь – неси их мне в Приозерскую ратушу.$B$BСоломон связь закончил.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Изувоя и найдите у него планы вторжения орков Черной горы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Мировой судья Соломон берет у вас планы и принимается их читать.?$B$BАрмия Темношкуров?! Да чтоб их разорвало, этих орков! В этих планах говорится о том, что гноллы и орки стягивают свои силы на восток. Видно, Гат\'Илзогг, вождь орков Черной горы, хочет провести свою армию через Приозерье и напасть сразу на Штормград!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мировому судье Соломону в Приозерье, что в Красногорье.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Изувой, сын Изувоя',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Изувой',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26546,'Друзья-остроклювы','Наш клан почитает грифонов как священных животных. Они – волшебные создания небес, и намного больше, чем животные; они умные и хитрые.$B$BГоворят, что мы "держим" их, но на самом деле это больше похоже на дружбу. Если ты хочешь подружиться с кланом Громового Молота, то сперва тебе надо будет подружиться с нашими грифонами. Вот, возьми этот мешок корма, он очень вкусный и свежий. В лесу, к югу от птичника, пасутся наши обученные остроклювы. Иди и покорми там нескольких за меня, ладно?','Покормите 7 обученных остроклювов из мешка с пищей грифона.','Обращайся с ними уважительно, и они ответят тебе тем же.$B$BА будешь плохо себя с ними вести, окажешься без глаза!','Вернитесь к укротителю грифонов Разящему Когтю в Заоблачный пик, что во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Друзья-остроклювы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наш клан почитает грифонов как священных животных. Они – волшебные создания небес, и намного больше, чем животные; они умные и хитрые.$B$BГоворят, что мы "держим" их, но на самом деле это больше похоже на дружбу. Если ты хочешь подружиться с кланом Громового Молота, то сперва тебе надо будет подружиться с нашими грифонами. Вот, возьми этот мешок корма, он очень вкусный и свежий. В лесу, к югу от птичника, пасутся наши обученные остроклювы. Иди и покорми там нескольких за меня, ладно?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Покормите 7 обученных остроклювов из мешка с пищей грифона.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Обращайся с ними уважительно, и они ответят тебе тем же.$B$BА будешь плохо себя с ними вести, окажешься без глаза!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к укротителю грифонов Разящему Когтю в Заоблачный пик, что во Внутренних землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26547,'Грифон волку не товарищ... и не еда!','Мы делаем все, что в наших силах, чтобы охранять наших собратьев и грифонов. К этому относится и охота на хищников, неважно, из леса они или из Орды.$B$BОт двуногих чудовищ нас пока спасать не надо, но в лесах к югу отсюда рыщет довольно много облезлых среброгривов. Там же летают и наши грифоны, и если они летят слишком низко, то звери хватают их. Поэтому убей несколько среброгривов, и пусть знают, что наши грифоны – не еда!','Убейте 8 облезлых среброгривов.','Вернитесь к укротителю грифонов Разящему Когтю в Заоблачный пик, что во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Грифон волку не товарищ... и не еда!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы делаем все, что в наших силах, чтобы охранять наших собратьев и грифонов. К этому относится и охота на хищников, неважно, из леса они или из Орды.$B$BОт двуногих чудовищ нас пока спасать не надо, но в лесах к югу отсюда рыщет довольно много облезлых среброгривов. Там же летают и наши грифоны, и если они летят слишком низко, то звери хватают их. Поэтому убей несколько среброгривов, и пусть знают, что наши грифоны – не еда!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 облезлых среброгривов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к укротителю грифонов Разящему Когтю в Заоблачный пик, что во Внутренних землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (26548,'На фронт','Рада тебя видеть! Давай сразу к делу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На фронт',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Рада тебя видеть! Давай сразу к делу.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (26549,'Безумие','Поговорите с Зелой в порту Драконьей Пасти на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Безумие',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Зелой в порту Драконьей Пасти на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) VALUES (26549,'Маруус, насколько я понимаю, ты будешь говорить с нашим "вождем" о том, чтобы мы присоединились к твоей Орде.$B$BНе забывай об осторожности, $C.$B$BИ разыщи меня потом, когда все закончится...') ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Маруус, насколько я понимаю, ты будешь говорить с нашим "вождем" о том, чтобы мы присоединились к твоей Орде.$B$BНе забывай об осторожности, $C.$B$BИ разыщи меня потом, когда все закончится...',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26550,'Тайные сделки','Занзил Отверженный, изгнанник племени Гурубаши, сейчас в моей каменоломне. Братья с севера сказали мне, что Занзил хочет вернуться и уже отправил своего посланника к Дробителям Черепов. Плохая новость.$B$BВыведай планы Занзила. Возьми эти благовония и положи напротив тотема летучей мыши в руинах Жубуваля на востоке. Далее тебе все расскажет Хир\'ик.','Положите благовония Гурубаши напротив тотема Хир\'ика и выведайте планы Занзила.','Так я и думал. Занзил слишком высокого о себе мнения, чтобы впутываться в дрязги между Кровавым Скальпом и Дробителями черепов. Нет, у него планы помасштабнее... Мастер проклятий Джин\'до хочет с его помощью вернуть Хаккара в Зул\'Гуруб.$B$BХорошо, что мы узнали об этом сейчас. Теперь ясно, как нужно действовать.','Вернитесь к Шабалу в Укрытие Кофельнагель на мысе Тернистой долины.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тайные сделки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Занзил Отверженный, изгнанник племени Гурубаши, сейчас в моей каменоломне. Братья с севера сказали мне, что Занзил хочет вернуться и уже отправил своего посланника к Дробителям Черепов. Плохая новость.$B$BВыведай планы Занзила. Возьми эти благовония и положи напротив тотема летучей мыши в руинах Жубуваля на востоке. Далее тебе все расскажет Хир\'ик.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Положите благовония Гурубаши напротив тотема Хир\'ика и выведайте планы Занзила.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так я и думал. Занзил слишком высокого о себе мнения, чтобы впутываться в дрязги между Кровавым Скальпом и Дробителями черепов. Нет, у него планы помасштабнее... Мастер проклятий Джин\'до хочет с его помощью вернуть Хаккара в Зул\'Гуруб.$B$BХорошо, что мы узнали об этом сейчас. Теперь ясно, как нужно действовать.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Шабалу в Укрытие Кофельнагель на мысе Тернистой долины.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (26551,'Убить Отверженного','Ты $gдолжен:должна; убить Занзила. Ты $gлетал:летала; на крыльях Хир\'ика и $gсмотрел:смотрела; его глазами, значит, тебе известно, где именно в руинах Абораза укрывается Занзил. Отправляйся туда и убей его.$B$BДа, и еще: если мы потеряемся, воспользуйся этим фетишем. Он действует только в Тернистой долине, но если понадобится, то мгновенно перенесет тебя сюда.$B$BУдачи, |3-6($r). Занзил сильный соперник.','Отправляйтесь в руины Абораза, что на мысе Тернистой долины, и убейте Занзила Отверженного.','Время, когда он занимался зельями, подходит к концу.','Занзил Отверженный','Куда он исчез?','Занзил Отверженный') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Убить Отверженного',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gдолжен:должна; убить Занзила. Ты $gлетал:летала; на крыльях Хир\'ика и $gсмотрел:смотрела; его глазами, значит, тебе известно, где именно в руинах Абораза укрывается Занзил. Отправляйся туда и убей его.$B$BДа, и еще: если мы потеряемся, воспользуйся этим фетишем. Он действует только в Тернистой долине, но если понадобится, то мгновенно перенесет тебя сюда.$B$BУдачи, |3-6($r). Занзил сильный соперник.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в руины Абораза, что на мысе Тернистой долины, и убейте Занзила Отверженного.',`objectives_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Время, когда он занимался зельями, подходит к концу.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Занзил Отверженный',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Куда он исчез?',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Занзил Отверженный',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26552,'Троллья дыра','Похоже, портал Занзила в Зул\'Гуруб до сих пор открыт. Зул\'Гуруб – место очень опасное, но Шабал доверил это задание именно тебе.$B$BПортал расположен прямо перед тобой.','Воспользуйтесь порталом Занзила и отправляйтесь в Зул\'Гуруб.$B$BЕсли заблудитесь или вам потребуется вернуться в Зул\'Гуруб, поговорите с Шабалом в Укрытии Кофельнагель.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Троллья дыра',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Похоже, портал Занзила в Зул\'Гуруб до сих пор открыт. Зул\'Гуруб – место очень опасное, но Шабал доверил это задание именно тебе.$B$BПортал расположен прямо перед тобой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь порталом Занзила и отправляйтесь в Зул\'Гуруб.$B$BЕсли заблудитесь или вам потребуется вернуться в Зул\'Гуруб, поговорите с Шабалом в Укрытии Кофельнагель.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26553,'Верховная жрица Джеклик','Перед вами возвышается пандус, ведущий на одну из множества городских террас. Виднеющиеся впереди тотемы-нетопыри указывают, что это владения верховной жрицы Джеклик, поклонницы Хир\'ика.$B$BДжеклик была одной из жриц, поклонявшихся Хаккару, которых хотел воскресить Занзил. Возможно, если вы поспешите, то сумеете этому помешать!','Уничтожьте тело верховной жрицы Джеклик, прежде чем Занзил ее воскресит.$B$BЕсли вы заблудитесь или вам понадобится вернуться в Зул\'Гуруб, поговорите с Шабалом в Укрытии Кофельнагель.','Верховная жрица Джеклик, последовательница Хир\'ика, покровителя летучих мышей','Верховная жрица Джеклик') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Верховная жрица Джеклик',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Перед вами возвышается пандус, ведущий на одну из множества городских террас. Виднеющиеся впереди тотемы-нетопыри указывают, что это владения верховной жрицы Джеклик, поклонницы Хир\'ика.$B$BДжеклик была одной из жриц, поклонявшихся Хаккару, которых хотел воскресить Занзил. Возможно, если вы поспешите, то сумеете этому помешать!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте тело верховной жрицы Джеклик, прежде чем Занзил ее воскресит.$B$BЕсли вы заблудитесь или вам понадобится вернуться в Зул\'Гуруб, поговорите с Шабалом в Укрытии Кофельнагель.',`objectives_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Верховная жрица Джеклик, последовательница Хир\'ика, покровителя летучих мышей',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Верховная жрица Джеклик',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26554,'Путешествие в Зул\'Гуруб','Занзил Отверженный снова скрылся. Видимо, не без помощи одного из своих порталов. Ступай за ним!','Пройдите через портал Занзила.$B$BЕсли потеряетесь или захотите вернуться в Зул\'Гуруб, поговорите с Шабалом в Укрытии Кофельнагель.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путешествие в Зул\'Гуруб',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Занзил Отверженный снова скрылся. Видимо, не без помощи одного из своих порталов. Ступай за ним!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Пройдите через портал Занзила.$B$BЕсли потеряетесь или захотите вернуться в Зул\'Гуруб, поговорите с Шабалом в Укрытии Кофельнагель.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26556,'Нет вредным отходам','С тех пор как гоблинов приютили в Оргриммаре, они сбрасывают кучу отходов прямиком в наши водоемы.$B$BТрудно сказать, как это сказывается на наших рыбных угодьях, но не думаю, что положительно. Слышал, например, что в зараженном пруду возле их лагеря уже завелись рыбы-мутанты. Несколько образцов здорово помогли бы мне понять, что там на самом деле происходит.$B$BПоможешь мне?','Отлично, Ориент. Образцы помогут нам понять, что делается в этой токсичной луже.','Удалось наловить рыбы на образцы?','Отнесите ядовитых луженниц Разгару в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нет вредным отходам',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','С тех пор как гоблинов приютили в Оргриммаре, они сбрасывают кучу отходов прямиком в наши водоемы.$B$BТрудно сказать, как это сказывается на наших рыбных угодьях, но не думаю, что положительно. Слышал, например, что в зараженном пруду возле их лагеря уже завелись рыбы-мутанты. Несколько образцов здорово помогли бы мне понять, что там на самом деле происходит.$B$BПоможешь мне?',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, Ориент. Образцы помогут нам понять, что делается в этой токсичной луже.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось наловить рыбы на образцы?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите ядовитых луженниц Разгару в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26557,'Невероятное усилие','Годами я ловлю в водоемах Оргриммара песчаного карпа. И недавно заметил, что он уже не клюет так хорошо, как раньше, на обычную наживку. Сдается мне, это как-то связано с тауренами, которые переехали на Аллею Мудрости.$B$BЯ беседовал с одним из их рыболовов, и оказалось, что вкусы карпа изменились. И будто нынче карп клюет на олений глаз. К северу от Оргриммара, прямо за северными вратами, обитает много оленей.','Превосходно! А эти карпы – настоящие гурманы, да?','Ну что, глаз сгодился для приманки?','Отнесите песчаного карпа Разгару в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Невероятное усилие',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Годами я ловлю в водоемах Оргриммара песчаного карпа. И недавно заметил, что он уже не клюет так хорошо, как раньше, на обычную наживку. Сдается мне, это как-то связано с тауренами, которые переехали на Аллею Мудрости.$B$BЯ беседовал с одним из их рыболовов, и оказалось, что вкусы карпа изменились. И будто нынче карп клюет на олений глаз. К северу от Оргриммара, прямо за северными вратами, обитает много оленей.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Превосходно! А эти карпы – настоящие гурманы, да?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, глаз сгодился для приманки?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите песчаного карпа Разгару в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26558,'Призыв Шадры','Идол готов, $n. Надеюсь, ты тоже?$B$BТы пойдешь на юго-запад в Шадра\'Алор впереди нас с идолом. Тебе надо будет пустить идола в дело в каждом из трех храмов.$B$BКогда ты это сделаешь, Шадра придет в наш мир. Мы с ловчими смерти пойдем за тобой, чтобы подчинить и забрать ее тело. Поговори с передовым отрядом, который я послал раньше, как только проведешь ритуал, и жди моего прибытия.','Используйте идол Шадры в северо-западном, юго-западном и восточном храмах в Шадра\'Алоре.','Вернитесь к ловчему смерти – дозорному в Шадра\'Алор, что во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Призыв Шадры',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Идол готов, $n. Надеюсь, ты тоже?$B$BТы пойдешь на юго-запад в Шадра\'Алор впереди нас с идолом. Тебе надо будет пустить идола в дело в каждом из трех храмов.$B$BКогда ты это сделаешь, Шадра придет в наш мир. Мы с ловчими смерти пойдем за тобой, чтобы подчинить и забрать ее тело. Поговори с передовым отрядом, который я послал раньше, как только проведешь ритуал, и жди моего прибытия.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте идол Шадры в северо-западном, юго-западном и восточном храмах в Шадра\'Алоре.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ловчему смерти – дозорному в Шадра\'Алор, что во Внутренних землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (26559,'[NYI] Побег – штука сложная') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[NYI] Побег – штука сложная',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26560,'Йоргенсен','Понятия не имею, где искать Кракауера и Данфорта, а вот Йоргенсена держали в лагере Ренда, это к северо-западу отсюда. Мы с ним сидели в одной клетке, полной нечистот, но потом меня перетащили на лесопилку Альтера.$B$BЧтобы выпустить его, нужен будет ключ, а он находится в цепких лапах одной ведьмы. Она холодная, что твой камень, а зовут ее Утрока Хранящая Ключи. Ключ от клетки Йоргенсена она не отдаст, так что придется убить ее. Она ошивается в долине, ведущей в Пылающие степи, это на север отсюда.$B$BПошли, $gприятель:подруга;.','Добудьте ключ от клетки Йоргенсена.','Я знаю, где они держат Кракауера и Данфорта. Пошли скорей, а то они собирались принести их в жертву!','Найдите Йоргенсена в Лагере Ренда в Красногорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Йоргенсен',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Понятия не имею, где искать Кракауера и Данфорта, а вот Йоргенсена держали в лагере Ренда, это к северо-западу отсюда. Мы с ним сидели в одной клетке, полной нечистот, но потом меня перетащили на лесопилку Альтера.$B$BЧтобы выпустить его, нужен будет ключ, а он находится в цепких лапах одной ведьмы. Она холодная, что твой камень, а зовут ее Утрока Хранящая Ключи. Ключ от клетки Йоргенсена она не отдаст, так что придется убить ее. Она ошивается в долине, ведущей в Пылающие степи, это на север отсюда.$B$BПошли, $gприятель:подруга;.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте ключ от клетки Йоргенсена.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я знаю, где они держат Кракауера и Данфорта. Пошли скорей, а то они собирались принести их в жертву!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Найдите Йоргенсена в Лагере Ренда в Красногорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26561,'Кракауер','Пока мы тут говорим, Кракауера отволокут на плаху! Орки привезли знахаря из племени Гурубаши, чтобы тот совершил над Кракауером какой-то темный ритуал. Надо убить этого тролля!$B$BПойдемте! Он вон там, в пещере. На первой развилке надо свернуть направо.','Убейте ритуалиста Тарака.','Что… Где я? Что случилось? Месснер? Йоргенсен?$B$BДА ЧТОБ Я СДОХ!!! Надо скорее бежать за Данфортом! Может, уже поздно!','Поговорите с Кракауером у Скалы Ренда, что в Красногорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кракауер',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пока мы тут говорим, Кракауера отволокут на плаху! Орки привезли знахаря из племени Гурубаши, чтобы тот совершил над Кракауером какой-то темный ритуал. Надо убить этого тролля!$B$BПойдемте! Он вон там, в пещере. На первой развилке надо свернуть направо.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте ритуалиста Тарака.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что… Где я? Что случилось? Месснер? Йоргенсен?$B$BДА ЧТОБ Я СДОХ!!! Надо скорее бежать за Данфортом! Может, уже поздно!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Кракауером у Скалы Ренда, что в Красногорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (26562,'Последний, но не менее важный: Данфорт','Данфорта пытают на другой стороне пещеры. Подумать страшно, что теперь с ним стало! Нужно скорее пойти туда и спасти его!$B$BДанфорта удерживает рычаг, ключ от которого у властителя Барбария. Нам надо держаться всем вместе и убить его, потом возьмем ключ и поможем Данфорту спуститься, а потом все вместе убежим.$B$BГотовы?','Убейте властителя Барбария и возьмите у него тумблер Черной горы. Потом при помощи этого тумблера освободите Данфорта.','Вовремя же вы появились! У меня уже руки начали затекать.','Вы только посмотрите! Вся команда в сборе, одного Кишана не хватает.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Последний, но не менее важный: Данфорт',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Данфорта пытают на другой стороне пещеры. Подумать страшно, что теперь с ним стало! Нужно скорее пойти туда и спасти его!$B$BДанфорта удерживает рычаг, ключ от которого у властителя Барбария. Нам надо держаться всем вместе и убить его, потом возьмем ключ и поможем Данфорту спуститься, а потом все вместе убежим.$B$BГотовы?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте властителя Барбария и возьмите у него тумблер Черной горы. Потом при помощи этого тумблера освободите Данфорта.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вовремя же вы появились! У меня уже руки начали затекать.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы только посмотрите! Вся команда в сборе, одного Кишана не хватает.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26563,'Возвращение компании "Браво"','Я уж не знаю, кто ты, $gприятель:подружка;, но ты честно $gзаслужил:заслужила; всяческий почет и восхищение команды "Браво". Ты $gсумел:сумела; спасти наши шкуры, а по пути еще и уложить кучу орков. Теперь мы должны отблагодарить тебя.$B$BВернись в Приозерье и доложи обо всем полковнику Тротману, а мы найдем Джонни и лично сообщим ему хорошие новости. Теперь, когда команда "Браво" снова в сборе, этим оркам ничего не поможет.','Поговорите с полковником Тротманом в Приозерье, что в Красногорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение компании "Браво"',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я уж не знаю, кто ты, $gприятель:подружка;, но ты честно $gзаслужил:заслужила; всяческий почет и восхищение команды "Браво". Ты $gсумел:сумела; спасти наши шкуры, а по пути еще и уложить кучу орков. Теперь мы должны отблагодарить тебя.$B$BВернись в Приозерье и доложи обо всем полковнику Тротману, а мы найдем Джонни и лично сообщим ему хорошие новости. Теперь, когда команда "Браво" снова в сборе, этим оркам ничего не поможет.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с полковником Тротманом в Приозерье, что в Красногорье.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26564,'На все руки мастер','<Глин усмехается вам и издает звук, похожий на трение двух камней друг о друга.>$b$bОни вдребезги разбили все наши катапульты. Вот эту я пытался починить, но далеко не продвинулся.$b$bВозможно, тебе хочется побыть $gполезным:полезной;. Отправляйся на передовую и принеси мне все запчасти, на какие наткнешься.$b$bС этим-то ты справишься, мешок мяса?','Соберите 6 деталей катапульты.','Ну хорошо. Может быть ты не так уж и бесполезен.$B$BЛадно, ладно… не кривись. Дай мне пару минут, и я разберусь с этими запчастями.','Ну? Я целый день буду ждать?','Вернитесь к Глину Грязновалу на Разбитую передовую в Подземье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На все руки мастер',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Глин усмехается вам и издает звук, похожий на трение двух камней друг о друга.>$b$bОни вдребезги разбили все наши катапульты. Вот эту я пытался починить, но далеко не продвинулся.$b$bВозможно, тебе хочется побыть $gполезным:полезной;. Отправляйся на передовую и принеси мне все запчасти, на какие наткнешься.$b$bС этим-то ты справишься, мешок мяса?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 6 деталей катапульты.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну хорошо. Может быть ты не так уж и бесполезен.$B$BЛадно, ладно… не кривись. Дай мне пару минут, и я разберусь с этими запчастями.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну? Я целый день буду ждать?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Глину Грязновалу на Разбитую передовую в Подземье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26565,'Строптивый улов (УДАЛЕН)','$GГотов:Готова; к серьезному заданию, $n? Отлично, я на тебя рассчитывал. Река Строптивая протекает на западе от Оргриммара. В ее водах твое задание и обитает.$B$BНам нужна разъяренная щука. Эта редкая рыбина раньше преобладала в этих водах, но после наводнений крупные особи встречаются редко. Иди на реку – поглядим, какой из тебя рыболов.','Поймайте разъяренную щуку в реке Строптивой. Выйти к реке можно через западные ворота Оргриммара. Возвращайтесь с уловом к Разгару на Аллею Чести.','Отнесите разъяренную щуку Разгару в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Строптивый улов (УДАЛЕН)',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$GГотов:Готова; к серьезному заданию, $n? Отлично, я на тебя рассчитывал. Река Строптивая протекает на западе от Оргриммара. В ее водах твое задание и обитает.$B$BНам нужна разъяренная щука. Эта редкая рыбина раньше преобладала в этих водах, но после наводнений крупные особи встречаются редко. Иди на реку – поглядим, какой из тебя рыболов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поймайте разъяренную щуку в реке Строптивой. Выйти к реке можно через западные ворота Оргриммара. Возвращайтесь с уловом к Разгару на Аллею Чести.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите разъяренную щуку Разгару в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26566,'Поговорите с инженером Искролязгом в Новом Городе Механиков.','Так значит, сам главный механик прослышал о моем скромном проекте? Потрясающе! Я почти закончил мой последний прототип, но, наверное, ты можешь мне помочь и разыскать оставшиеся несколько деталей.','Поговорите с инженером Искролязгом в Новом Городе Механиков.') ON DUPLICATE KEY UPDATE `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с инженером Искролязгом в Новом Городе Механиков.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так значит, сам главный механик прослышал о моем скромном проекте? Потрясающе! Я почти закончил мой последний прототип, но, наверное, ты можешь мне помочь и разыскать оставшиеся несколько деталей.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с инженером Искролязгом в Новом Городе Механиков.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26567,'Джон Джей Кишан','Найдите в Приозерской таверне Джона Джея Кишана и попросите его о помощи.','Помочь тебе? Помочь этим вот? Да они скорей плюнули бы в меня, чем улыбнулись бы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Джон Джей Кишан',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите в Приозерской таверне Джона Джея Кишана и попросите его о помощи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Помочь тебе? Помочь этим вот? Да они скорей плюнули бы в меня, чем улыбнулись бы.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26568,'Не моя война','Это они просили меня сражаться на этих войнах. А я никого не просил! Я сделал все, что мог, чтобы победить. А потом меня похитили эти грязные орки, эти ничтожные пожиратели фекалий, и пять лет они всячески измывались надо мной! Наконец мне удалось сбежать и добраться до родного города, и что же я встретил там? Люди плевали в меня, гнали меня, называли убийцей маленьких орчонков и всячески поносили!$B$BНет, не стану я тебе помогать. Иди назад к своему Тротману и скажи ему, что это не моя война.','Вернитесь к полковнику Тротману.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Не моя война',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это они просили меня сражаться на этих войнах. А я никого не просил! Я сделал все, что мог, чтобы победить. А потом меня похитили эти грязные орки, эти ничтожные пожиратели фекалий, и пять лет они всячески измывались надо мной! Наконец мне удалось сбежать и добраться до родного города, и что же я встретил там? Люди плевали в меня, гнали меня, называли убийцей маленьких орчонков и всячески поносили!$B$BНет, не стану я тебе помогать. Иди назад к своему Тротману и скажи ему, что это не моя война.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь к полковнику Тротману.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (26569,'Геодезическое снаряжение','О, $gмой спаситель:моя спасительница;! Мне сказали, что ты придешь и спасешь все Приозерье, а заодно и мой мост. Да, слишком много в него вложено трудов, чтобы вот так взять и позволить армии орков-мародеров разнести его в щепки.$B$BПослушай, если ты вдруг пойдешь к северу, в направлении лагеря Ренда, то не сделаешь ли милость: не украдешь ли у тамошних следопытов из клана Черной горы несколько подзорных труб? Они весьма кстати придутся для моего нового геодезического оборудования.','Вернитесь к штейгеру Ослоу в Приозерье, что в Красногорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Геодезическое снаряжение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','О, $gмой спаситель:моя спасительница;! Мне сказали, что ты придешь и спасешь все Приозерье, а заодно и мой мост. Да, слишком много в него вложено трудов, чтобы вот так взять и позволить армии орков-мародеров разнести его в щепки.$B$BПослушай, если ты вдруг пойдешь к северу, в направлении лагеря Ренда, то не сделаешь ли милость: не украдешь ли у тамошних следопытов из клана Черной горы несколько подзорных труб? Они весьма кстати придутся для моего нового геодезического оборудования.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к штейгеру Ослоу в Приозерье, что в Красногорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26570,'Армия Ренда','На север отправляешься? Может, повоюешь там немного с этими зверями из клана Черной горы? А, $n, что скажешь?$B$BПросто убивай любых орков из клана Черной горы, какие встретятся тебе на лесопилке Альтера или в лагере Ренда. Убивай их до тех пор, пока твоя кожа не покраснеет от их крови, а тогда возвращайся ко мне за честной наградой!$B$BМожет, вторжения мы так и не остановим, но планы им немного подпортим, это уж точно.','Убейте 25 любых орков из клана Черной горы на лесопилке Альтера или в лагере Ренда.','Вернитесь к маршалу Маррису в Приозерье, что в Красногорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Армия Ренда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На север отправляешься? Может, повоюешь там немного с этими зверями из клана Черной горы? А, $n, что скажешь?$B$BПросто убивай любых орков из клана Черной горы, какие встретятся тебе на лесопилке Альтера или в лагере Ренда. Убивай их до тех пор, пока твоя кожа не покраснеет от их крови, а тогда возвращайся ко мне за честной наградой!$B$BМожет, вторжения мы так и не остановим, но планы им немного подпортим, это уж точно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 25 любых орков из клана Черной горы на лесопилке Альтера или в лагере Ренда.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к маршалу Маррису в Приозерье, что в Красногорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (26571,'Орудия войны','То, о чем я собираюсь попросить тебя, будет нелегко выполнить, $n. Кишан оставил в той орочьей тюрьме все, что у него было, не только свою душу и волю к жизни.$B$BЕсли мы хотим, чтобы Джонни достойно сражался на войне, нужно вернуть его ценные вещи. У орков остался лук Кишана и его нож для выживания.$B$BСтупай на лесопилку Альтера, к востоку отсюда, и найди там двух орков-лейтенантов, их зовут Мурдунк и Хомурк. Вещи Кишана у них, отбери все.$B$BЯ буду держать связь по ГНМ-передатчику.','Верните лук Кишана и нож выживания Кишана.','Вернитесь к полковнику Тротману в Приозерье, что в Красногорье.','Так много всего. Не забудь выслать мешки для трупов!','Полковник Тротман') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Орудия войны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','То, о чем я собираюсь попросить тебя, будет нелегко выполнить, $n. Кишан оставил в той орочьей тюрьме все, что у него было, не только свою душу и волю к жизни.$B$BЕсли мы хотим, чтобы Джонни достойно сражался на войне, нужно вернуть его ценные вещи. У орков остался лук Кишана и его нож для выживания.$B$BСтупай на лесопилку Альтера, к востоку отсюда, и найди там двух орков-лейтенантов, их зовут Мурдунк и Хомурк. Вещи Кишана у них, отбери все.$B$BЯ буду держать связь по ГНМ-передатчику.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните лук Кишана и нож выживания Кишана.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к полковнику Тротману в Приозерье, что в Красногорье.',`completedtext_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Так много всего. Не забудь выслать мешки для трупов!',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Полковник Тротман',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26573,'Всем сердцем с нами','<ГНМ-передатчик щелкает.>$B$BОдних вещей будет мало, $n. Он должен всем своим сердцем быть с нами, на поле боя. Для этого надо вернуть ему предметы, которые много для него значат. Орки из клана Черной горы из лагеря Ренда, который на севере, украли у Кишана два таких предмета.$B$BПроберись в тот лагерь и поищи у них в сундуках головную повязку Кишана и нефритовый амулет, подаренный ему женой. Жену его, кстати, жестоко убили орки из клана Черной горы во время своего нашествия.$B$BЕсли найдешь –неси мне.','Отыщите красную головную повязку Кишана и нефритовый амулет Кишана.','Надеюсь, что эти вещи и вся его команда, которая счастливо спаслась, поднимут ему настроение. Нам не выиграть эту битву без Кишана.','Вернитесь к полковнику Тротману в Приозерье, что в Красногорье.','Они обрили его… наголо.','Полковник Тротман') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Всем сердцем с нами',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<ГНМ-передатчик щелкает.>$B$BОдних вещей будет мало, $n. Он должен всем своим сердцем быть с нами, на поле боя. Для этого надо вернуть ему предметы, которые много для него значат. Орки из клана Черной горы из лагеря Ренда, который на севере, украли у Кишана два таких предмета.$B$BПроберись в тот лагерь и поищи у них в сундуках головную повязку Кишана и нефритовый амулет, подаренный ему женой. Жену его, кстати, жестоко убили орки из клана Черной горы во время своего нашествия.$B$BЕсли найдешь –неси мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщите красную головную повязку Кишана и нефритовый амулет Кишана.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Надеюсь, что эти вещи и вся его команда, которая счастливо спаслась, поднимут ему настроение. Нам не выиграть эту битву без Кишана.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к полковнику Тротману в Приозерье, что в Красногорье.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Они обрили его… наголо.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Полковник Тротман',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (26574,'Убежище Аделлы','Доберитесь до Аделлы в Тень Ветвей в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Убежище Аделлы',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доберитесь до Аделлы в Тень Ветвей в Фераласе.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26575,'Последняя капля','Я хочу попросить тебя еще об одной услуге, смертный.$b$bЕсть один василиск, крупнее и старше других. Обычно мы не боимся их племени, но этот стал таким сильным, что смог обратить в камень некоторых моих сыновей. Этого нельзя стерпеть.$b$bОтправляйся на восток, найди Горгонита и убей его. Он и так уже живет слишком долго.','Убейте Горгонита.','Вернитесь к Кору Невозмутимому в Дрожащие Вершины, что в Подземье.','Проклятье сыновей Кора.','Горгонит') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Последняя капля',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я хочу попросить тебя еще об одной услуге, смертный.$b$bЕсть один василиск, крупнее и старше других. Обычно мы не боимся их племени, но этот стал таким сильным, что смог обратить в камень некоторых моих сыновей. Этого нельзя стерпеть.$b$bОтправляйся на восток, найди Горгонита и убей его. Он и так уже живет слишком долго.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Горгонита.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кору Невозмутимому в Дрожащие Вершины, что в Подземье.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Проклятье сыновей Кора.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Горгонит',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26576,'Твердая рука','Неподалеку, к северу отсюда, ты найдешь Террата Непоколебимого. Он взялся загнать каменных драконов обратно в гнездовье. Нам приходится заниматься этим каждые несколько сотен лет... Каменные драконы – непостоянные создания, покоряются только силе.$b$bТеррат ведет себя разумно и спокойно, но то, чем он занимается, не так-то просто выполнить. Отправляйся к нему. Обратись к более уравновешенному сыну Матери-Скалы.','Поговорите с Терратом Непоколебимым у Белого гнездовья.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Твердая рука',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Неподалеку, к северу отсюда, ты найдешь Террата Непоколебимого. Он взялся загнать каменных драконов обратно в гнездовье. Нам приходится заниматься этим каждые несколько сотен лет... Каменные драконы – непостоянные создания, покоряются только силе.$b$bТеррат ведет себя разумно и спокойно, но то, чем он занимается, не так-то просто выполнить. Отправляйся к нему. Обратись к более уравновешенному сыну Матери-Скалы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Терратом Непоколебимым у Белого гнездовья.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26577,'Тернистый путь','К востоку отсюда, в Багровом зале, ты найдешь Горсика. Из нашего племени он самый непостоянный и самый жестокий. Его не назвать дружелюбным или вызывающим доверие, но его слова имеют вес.$b$bЕсли ты покажешь Горсику, на что $gспособен:способна;, то это намного приблизит тебя к тому, чтобы завоевать доверие Матери-Скалы.','Поговорите с Горсиком Беспокойным в Багровом зале.','Значит, тебя выбрал Диамант.$B$BТакой маленький. Такой хрупкий.$B$BТы отдаешь себе отчет в том, что по твоим действиям будут судить обо всех "Служителях Земли"? Ты действительно думаешь, что сможешь выстоять против стольких противников?$B$BТы глупец. Самонадеянный глупец. Посмотрим, способен ли ты при этом на что-нибудь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тернистый путь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','К востоку отсюда, в Багровом зале, ты найдешь Горсика. Из нашего племени он самый непостоянный и самый жестокий. Его не назвать дружелюбным или вызывающим доверие, но его слова имеют вес.$b$bЕсли ты покажешь Горсику, на что $gспособен:способна;, то это намного приблизит тебя к тому, чтобы завоевать доверие Матери-Скалы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Горсиком Беспокойным в Багровом зале.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Значит, тебя выбрал Диамант.$B$BТакой маленький. Такой хрупкий.$B$BТы отдаешь себе отчет в том, что по твоим действиям будут судить обо всех "Служителях Земли"? Ты действительно думаешь, что сможешь выстоять против стольких противников?$B$BТы глупец. Самонадеянный глупец. Посмотрим, способен ли ты при этом на что-нибудь.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26578,'Гиблогрибы','Разлом в ваш мир отравил наш дом. Испортил его. Осквернил.$b$bИ рана растет и гноится. Под этой грязью все труднее разглядеть чистоту скал.$b$bЕсли ты здесь, чтобы помочь нам, тогда начни с расчистки этих зарослей. Ищи сияющие грибы, растущие быстрее остальных. Они хуже всего.','Уничтожьте 10 гиблогрибов.','Вернитесь к Горсику Беспокойному в Багровый зал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гиблогрибы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Разлом в ваш мир отравил наш дом. Испортил его. Осквернил.$b$bИ рана растет и гноится. Под этой грязью все труднее разглядеть чистоту скал.$b$bЕсли ты здесь, чтобы помочь нам, тогда начни с расчистки этих зарослей. Ищи сияющие грибы, растущие быстрее остальных. Они хуже всего.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 10 гиблогрибов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Горсику Беспокойному в Багровый зал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26579,'Проявить слабость','Грибные чудища, которые окружают нас, стали жертвами некой слабости, очень похожей на ту, что действует и на твоих сородичей. Их кожа стала слишком мягкой. Они больше не связаны с камнями.$b$bУбей их. Мы не хотим, чтобы инфекция распространилась.','Убейте 8 грибных чудищ.','В тебе есть определенная сила. За это ты достоин некоторого уважения, особенно на фоне своих собратьев.$B$BНо мои заботы еще не уменьшились. Как связанные с чрезмерной растительностью, так и с тобой.','Вернитесь к Горсику Беспокойному в Багровый зал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Проявить слабость',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Грибные чудища, которые окружают нас, стали жертвами некой слабости, очень похожей на ту, что действует и на твоих сородичей. Их кожа стала слишком мягкой. Они больше не связаны с камнями.$b$bУбей их. Мы не хотим, чтобы инфекция распространилась.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 грибных чудищ.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','В тебе есть определенная сила. За это ты достоин некоторого уважения, особенно на фоне своих собратьев.$B$BНо мои заботы еще не уменьшились. Как связанные с чрезмерной растительностью, так и с тобой.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Горсику Беспокойному в Багровый зал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26580,'Знакомые незваные гости','$gСмертный:Смертная;. Там по горам бегают твои соплеменники. Они слишком трусливы, чтобы подойти поближе, и слишком быстры, чтобы их можно было раздавить.$b$bЕсли хочешь моего покровительства, разберись с ними. Я устал от этих игр.','Поговорите с "незваными смертными" в Багровом зале.','Рад снова видеть тебя, брат. Вижу, твои усилия приносят плоды. Кажется, каменные лорды начинают тебе доверять.$B$BМы пришли, чтобы помочь. Возможно, нам удастся установить причины внезапного появления этой буйной растительности. У меня есть большие подозрения, что гнев твоих друзей великанов направлен не на истинных виновников.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Знакомые незваные гости',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$gСмертный:Смертная;. Там по горам бегают твои соплеменники. Они слишком трусливы, чтобы подойти поближе, и слишком быстры, чтобы их можно было раздавить.$b$bЕсли хочешь моего покровительства, разберись с ними. Я устал от этих игр.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с "незваными смертными" в Багровом зале.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Рад снова видеть тебя, брат. Вижу, твои усилия приносят плоды. Кажется, каменные лорды начинают тебе доверять.$B$BМы пришли, чтобы помочь. Возможно, нам удастся установить причины внезапного появления этой буйной растительности. У меня есть большие подозрения, что гнев твоих друзей великанов направлен не на истинных виновников.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26581,'Ветер в голове','Возьмите ветробеса Лорвариуса, отправляйтесь к облакам красного тумана, которые находятся у воды в Багровом зале, и возвращайтесь с образцом.','Туман коснулся твоей кожи? Надеюсь, не будет никаких неблагоприятных последствий.','Отнесите образец говорящему с ветром Лорвариусу в Багровый зал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ветер в голове',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возьмите ветробеса Лорвариуса, отправляйтесь к облакам красного тумана, которые находятся у воды в Багровом зале, и возвращайтесь с образцом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Туман коснулся твоей кожи? Надеюсь, не будет никаких неблагоприятных последствий.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите образец говорящему с ветром Лорвариусу в Багровый зал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26582,'Неестественные причины','Это бесспорно магия в чистом виде. Даже не друидская магия. Я подозреваю одного из каменных троггов с севера.$b$bОтправляйся к Горсику Беспокойному и расскажи ему о них. Будем надеяться, что это поможет завоевать его расположение.','Поговорите с Горсиком Беспокойным в Багровом зале.','Каменные трогги? И я должен поверить тебе на слово?$B$BВ любом случае, мне не нравятся верлоки. Подозрения – более чем достаточная причина для того, чтобы задать им жару. Посмотрим, правдивы ли твои слова.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Неестественные причины',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это бесспорно магия в чистом виде. Даже не друидская магия. Я подозреваю одного из каменных троггов с севера.$b$bОтправляйся к Горсику Беспокойному и расскажи ему о них. Будем надеяться, что это поможет завоевать его расположение.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Горсиком Беспокойным в Багровом зале.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Каменные трогги? И я должен поверить тебе на слово?$B$BВ любом случае, мне не нравятся верлоки. Подозрения – более чем достаточная причина для того, чтобы задать им жару. Посмотрим, правдивы ли твои слова.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26583,'Гнев грибоманта','Их вожак скрывается вон в той дыре впереди. Он-то и принес чуму в Багровый зал.$b$bЕго нужно убить.$b$bОдна из служительниц земли уже там внутри. Поговори с ней.','Поговорите с целительницей земли Норсалой, а затем убейте грибоманта Глопа.','Мне не пробраться внутрь. Нашим элементалям с этой задачей не справиться.$B$BА у тебя должно получиться.','Вернитесь к Руберику в нижнюю часть Верлока.','Грибомант собственной персоной.','Грибомант Глоп') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гнев грибоманта',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Их вожак скрывается вон в той дыре впереди. Он-то и принес чуму в Багровый зал.$b$bЕго нужно убить.$b$bОдна из служительниц земли уже там внутри. Поговори с ней.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с целительницей земли Норсалой, а затем убейте грибоманта Глопа.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мне не пробраться внутрь. Нашим элементалям с этой задачей не справиться.$B$BА у тебя должно получиться.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Руберику в нижнюю часть Верлока.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Грибомант собственной персоной.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Грибомант Глоп',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26584,'Встряхнуть и смешать','Мои братья должны атаковать Верлок снизу. Чтобы спастись от нас, верлокцы как обычно полезут наверх. Надо сделать так, чтобы сама земля затряслась и сбросила их нам под ноги.$b$bИ тогда дело за тобой. Когда они упадут на землю, сделай так, чтобы больше они не поднялись.','Убейте 8 скалолазов из Верлока в нижней части Верлока.','Молодец, смертный. Мои братья рады, что ты здесь.','Вернитесь к Горсику Беспокойному в Багровый зал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Встряхнуть и смешать',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мои братья должны атаковать Верлок снизу. Чтобы спастись от нас, верлокцы как обычно полезут наверх. Надо сделать так, чтобы сама земля затряслась и сбросила их нам под ноги.$b$bИ тогда дело за тобой. Когда они упадут на землю, сделай так, чтобы больше они не поднялись.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 скалолазов из Верлока в нижней части Верлока.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Молодец, смертный. Мои братья рады, что ты здесь.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Горсику Беспокойному в Багровый зал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26585,'Борьба с порчей','Если причина этого отвратительного роста и правда в Верлоке, то запасы должны находиться где-то в их деревне, что к северу отсюда. Принеси их мне, тогда я смогу убедиться, что мы нашли то, что нужно.','Добудьте 8 мешочков верлокской чудоросли.','Вернитесь к Горсику Беспокойному в Багровый зал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Борьба с порчей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если причина этого отвратительного роста и правда в Верлоке, то запасы должны находиться где-то в их деревне, что к северу отсюда. Принеси их мне, тогда я смогу убедиться, что мы нашли то, что нужно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 8 мешочков верлокской чудоросли.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Горсику Беспокойному в Багровый зал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26586,'Поиски компании "Браво"','Для того чтобы вы с Кишаном могли защитить Приозерье, нужно найти его старых боевых товарищей. Их зовут Месснер, Йоргенсен, Кракауер и Данфорт. Последнее, что я слышал о них, – будто их похитили орки из клана Черной горы. Не знаю, где они теперь, и живы ли вообще, но я был бы полнейшим ослом, если бы не попросил тебя поискать их.$B$BК востоку есть лесопилка Альтера – поищи там... Вдруг что-то найдется?','Поищите на лесопилке Альтера кого-нибудь из команды "Браво".','Кишан?! ДЖОННИ ЖИВОЙ?! Помогу, как пить дать помогу, но сперва тебе надо будет вытащить меня из этой проклятущей клетки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поиски компании "Браво"',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Для того чтобы вы с Кишаном могли защитить Приозерье, нужно найти его старых боевых товарищей. Их зовут Месснер, Йоргенсен, Кракауер и Данфорт. Последнее, что я слышал о них, – будто их похитили орки из клана Черной горы. Не знаю, где они теперь, и живы ли вообще, но я был бы полнейшим ослом, если бы не попросил тебя поискать их.$B$BК востоку есть лесопилка Альтера – поищи там... Вдруг что-то найдется?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поищите на лесопилке Альтера кого-нибудь из команды "Браво".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Кишан?! ДЖОННИ ЖИВОЙ?! Помогу, как пить дать помогу, но сперва тебе надо будет вытащить меня из этой проклятущей клетки.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26587,'Побег – штука сложная','Найдите ключ от клетки Месснера.','Ну, держите меня семеро!!!','Вернитесь к Месснеру на лесопилку Альтера, что в Красногорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Побег – штука сложная',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите ключ от клетки Месснера.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну, держите меня семеро!!!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Месснеру на лесопилку Альтера, что в Красногорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26589,'В дебрях Фераласа','Ты храбро $gсражался:сражалась;, охраняя покой этих земель вместе с нами. Если ты не против, здесь есть и другие, кому твоя помощь придется весьма кстати.$B$BК югу отсюда лежат нетронутые леса Фераласа. Там, под сенью Двух Колоссов, ты найдешь Кону Рунического Тотема. Он обнаружил признаки страшного заболевания.$B$BОтправляйся на запад к Двум Колоссам, где расположен лагерь Атайа. Поспеши туда, $n, и да пребудет с тобой Мать-Земля.','Отправляйтесь в Фералас и поговорите с Кону Руническим Тотемом в лагере Атайа.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В дебрях Фераласа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты храбро $gсражался:сражалась;, охраняя покой этих земель вместе с нами. Если ты не против, здесь есть и другие, кому твоя помощь придется весьма кстати.$B$BК югу отсюда лежат нетронутые леса Фераласа. Там, под сенью Двух Колоссов, ты найдешь Кону Рунического Тотема. Он обнаружил признаки страшного заболевания.$B$BОтправляйся на запад к Двум Колоссам, где расположен лагерь Атайа. Поспеши туда, $n, и да пребудет с тобой Мать-Земля.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Фералас и поговорите с Кону Руническим Тотемом в лагере Атайа.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26590,'Святая вода ясности','Слушай. Ты вроде как тертый калач. Помоги-ка мне. Мой кузен с севера прислал вот этот необычный артефакт, и мне нужна твоя помощь, чтобы... э-э... разобраться, что это такое.$B$BДля начала тебе нужно найти Святую воду ясности. Поговаривают, всякий, кто выпьет из этого источника, обретает ясность взора.$B$BЗвучит многообещающе, а?$B$BРаздобудь этой водицы из родника Нек\'Мани, что расположен на вершине лагеря наг. Удачи тебе!','Добудьте святую воду ясности из родника Нек\'Мани, расположенного на мысе Тернистой долины.','<Гоблин выпивает всю воду одним глотком.>$B$BА-ах... Знаешь, до чего трудно раздобыть свежую воду здесь, на мысе? Неудивительно, что наги столь ревностно оберегают свою святыню!$B$BА, да... артефакт. Ну-ка, ясность взора, ясность взора...$B$BЕсть, я понял!','<Когда Флюм замечает вас, уши у него встают торчком.>$B$BСвятая вода ясности? Неужели это она?','Вернитесь к Флюму Гряззиксу в Укрытие Кофельнагель на мысе Тернистой долины.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Святая вода ясности',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слушай. Ты вроде как тертый калач. Помоги-ка мне. Мой кузен с севера прислал вот этот необычный артефакт, и мне нужна твоя помощь, чтобы... э-э... разобраться, что это такое.$B$BДля начала тебе нужно найти Святую воду ясности. Поговаривают, всякий, кто выпьет из этого источника, обретает ясность взора.$B$BЗвучит многообещающе, а?$B$BРаздобудь этой водицы из родника Нек\'Мани, что расположен на вершине лагеря наг. Удачи тебе!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте святую воду ясности из родника Нек\'Мани, расположенного на мысе Тернистой долины.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Гоблин выпивает всю воду одним глотком.>$B$BА-ах... Знаешь, до чего трудно раздобыть свежую воду здесь, на мысе? Неудивительно, что наги столь ревностно оберегают свою святыню!$B$BА, да... артефакт. Ну-ка, ясность взора, ясность взора...$B$BЕсть, я понял!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Когда Флюм замечает вас, уши у него встают торчком.>$B$BСвятая вода ясности? Неужели это она?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Флюму Гряззиксу в Укрытие Кофельнагель на мысе Тернистой долины.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26591,'Медобслуживание на передовой','Похоже, у тебя резвые ноги, |3-6($r). Мне нужен кто-то, кто бы отправился на передовую и оказал там первую помощь нашим раненым.$b$bВозьми мой набор для оказания первой помощи. Им легко пользоваться.$b$bПомоги раненым, пока каменные трогги их не прикончили.','Окажите первую помощь 10 раненым земельникам.','Вернитесь к целителю земли Глубокому Пласту на разбитую передовую, что в Подземье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Медобслуживание на передовой',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Похоже, у тебя резвые ноги, |3-6($r). Мне нужен кто-то, кто бы отправился на передовую и оказал там первую помощь нашим раненым.$b$bВозьми мой набор для оказания первой помощи. Им легко пользоваться.$b$bПомоги раненым, пока каменные трогги их не прикончили.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Окажите первую помощь 10 раненым земельникам.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к целителю земли Глубокому Пласту на разбитую передовую, что в Подземье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26592,'Дифракционный хромоскоп','Чтобы точно опознать этот артефакт, мне понадобятся инструменты для анализа. Думаю, тут нужен дифракционный хромоскоп.$B$BМифриловая обшивка у меня уже есть, хотя эту-то штуку как раз труднее всего найти. Еще необходимы две детали: рубин и сапфир.$B$BПоблизости ошиваются пираты – на юге и чуть подальше на востоке. Пираты любят сокровища... Может, у них и добудешь мне камни?','Раздобудьте рубин Кровавого Паруса и сапфир Кровавого Паруса.','<Флюм взвешивает камни в руке и одобрительно кивает.>$B$BДа, отлично подойдут. Теперь проведем анализ...$B$B<Гоблин несколько раз постукивает камнями друг об друга, а потом смотрит на вас.>$B$BО, ты еще тут? Ты же не думаешь, что я какой-нибудь мошенник, а?','<Глаза Флюма сверкают.>$B$BЭто что, мои камушки?','Вернитесь к Флюму Гряззиксу в Укрытие Кофельнагель на мысе Тернистой долины.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дифракционный хромоскоп',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чтобы точно опознать этот артефакт, мне понадобятся инструменты для анализа. Думаю, тут нужен дифракционный хромоскоп.$B$BМифриловая обшивка у меня уже есть, хотя эту-то штуку как раз труднее всего найти. Еще необходимы две детали: рубин и сапфир.$B$BПоблизости ошиваются пираты – на юге и чуть подальше на востоке. Пираты любят сокровища... Может, у них и добудешь мне камни?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте рубин Кровавого Паруса и сапфир Кровавого Паруса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Флюм взвешивает камни в руке и одобрительно кивает.>$B$BДа, отлично подойдут. Теперь проведем анализ...$B$B<Гоблин несколько раз постукивает камнями друг об друга, а потом смотрит на вас.>$B$BО, ты еще тут? Ты же не думаешь, что я какой-нибудь мошенник, а?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Глаза Флюма сверкают.>$B$BЭто что, мои камушки?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Флюму Гряззиксу в Укрытие Кофельнагель на мысе Тернистой долины.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26593,'Напугать Трусишку','Ой! Это у тебя откуда? Нет, не рассказывай. Не хочу ничего знать!$B$BТебя кто прислал? Морской волк?','Эй, ты чего?! Как-то ты нехорошо смотришь, господин хороший.','Отправляйтесь в Пиратскую Бухту на мысе Тернистой долины и покажите потроха Филиппу по прозвищу "Трусишка".') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Напугать Трусишку',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ой! Это у тебя откуда? Нет, не рассказывай. Не хочу ничего знать!$B$BТебя кто прислал? Морской волк?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Эй, ты чего?! Как-то ты нехорошо смотришь, господин хороший.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отправляйтесь в Пиратскую Бухту на мысе Тернистой долины и покажите потроха Филиппу по прозвищу "Трусишка".',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26594,'Возвращение к Маккинли','Вот, возьми кошелек и отдай его "Морскому волку". Скажи, что я собирался заплатить, клянусь!!$B$BЯ просто слегка перепил и заблудился, и... ну, знаешь, как оно бывает. Он поймет. Ни к чему кулаками махать!','Отнесите плату Трусишки "Морскому волку" Маккинли.','Явитесь с рапортом к "Морскому волку" Маккинли в Пиратской Бухте на мысе Тернистой долины.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение к Маккинли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот, возьми кошелек и отдай его "Морскому волку". Скажи, что я собирался заплатить, клянусь!!$B$BЯ просто слегка перепил и заблудился, и... ну, знаешь, как оно бывает. Он поймет. Ни к чему кулаками махать!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите плату Трусишки "Морскому волку" Маккинли.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Явитесь с рапортом к "Морскому волку" Маккинли в Пиратской Бухте на мысе Тернистой долины.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) VALUES (26594,'Так-так, Шаурмасмерти. Принес Трусишкин должок?') ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Так-так, Шаурмасмерти. Принес Трусишкин должок?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26595,'Долг платежом красен','Существует три этапа взыскания долгов: попросить вежливо, попросить с применением силы... и последний этап, который я без затей так и называю "третьим этапом".$B$BК несчастью, наш старикан больше не занимается такими вещами. Что поделаешь, годы... Вот почему мне приходится прибегать к помощи друзей и знакомых, наемников, головорезов и благородных искателей приключений типа тебя!$B$BДжунц Фитцтютель, Эфрам Лунопад и Моури Уилкинс – все трое скрываются где-то на восточном побережье. Так что тебе не составит труда убить трех зайцев одним выстрелом... ну, и взыскать с них должок. Забери у них все, что есть ценного.','Добудьте деревянную ногу Моури, гаечный ключ Фитцтютеля и драгоценное зеркало Эфрама.','Вот и славно! Все эти вещи можно продать по хорошей цене, и особенно то, что было в деревянной ноге Моури! Большое спасибо, $n!$B$BНадеюсь, теперь эти трое усвоили урок: делая ставки, не рискуй тем, что не можешь позволить себе потерять.$B$BМожет быть, им эта мудрость уже не впрок... но всегда надо знать, с кем играешь!','Ну что, как там мои должники?','Вернитесь к "Морскому волку" Маккинли в Пиратскую Бухту на мыс Тернистой долины.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Долг платежом красен',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Существует три этапа взыскания долгов: попросить вежливо, попросить с применением силы... и последний этап, который я без затей так и называю "третьим этапом".$B$BК несчастью, наш старикан больше не занимается такими вещами. Что поделаешь, годы... Вот почему мне приходится прибегать к помощи друзей и знакомых, наемников, головорезов и благородных искателей приключений типа тебя!$B$BДжунц Фитцтютель, Эфрам Лунопад и Моури Уилкинс – все трое скрываются где-то на восточном побережье. Так что тебе не составит труда убить трех зайцев одним выстрелом... ну, и взыскать с них должок. Забери у них все, что есть ценного.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте деревянную ногу Моури, гаечный ключ Фитцтютеля и драгоценное зеркало Эфрама.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот и славно! Все эти вещи можно продать по хорошей цене, и особенно то, что было в деревянной ноге Моури! Большое спасибо, $n!$B$BНадеюсь, теперь эти трое усвоили урок: делая ставки, не рискуй тем, что не можешь позволить себе потерять.$B$BМожет быть, им эта мудрость уже не впрок... но всегда надо знать, с кем играешь!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, как там мои должники?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к "Морскому волку" Маккинли в Пиратскую Бухту на мыс Тернистой долины.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26596,'Зов Калимдора','Меня прислали сюда добрые жители Терамора с тем, чтобы я нашла преданных членов Альянса, желающих помочь леди Джайне в решении проблемы в Пылевых топях.$b$bТы же в действительности не $gработал:работала; на гоблинов?$b$bДорога в Пылевые топи лежит через Кабестан; ты сможешь добраться дотуда на корабле, отходящем от этой пристани. В Кабестане поговори с Газлоу. Он тебе укажет правильный путь.$b$bАй! Я наступила на рыбину, и она, кажется, дернулась!','Отправляйтесь на корабле из Пиратской Бухты в Кабестан, где вам следует поговорить с Газлоу.','Чего изволите?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зов Калимдора',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Меня прислали сюда добрые жители Терамора с тем, чтобы я нашла преданных членов Альянса, желающих помочь леди Джайне в решении проблемы в Пылевых топях.$b$bТы же в действительности не $gработал:работала; на гоблинов?$b$bДорога в Пылевые топи лежит через Кабестан; ты сможешь добраться дотуда на корабле, отходящем от этой пристани. В Кабестане поговори с Газлоу. Он тебе укажет правильный путь.$b$bАй! Я наступила на рыбину, и она, кажется, дернулась!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь на корабле из Пиратской Бухты в Кабестан, где вам следует поговорить с Газлоу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Чего изволите?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26597,'Лихорадка Тернистой долины','Плохо... Мне... т-так п-плохо... Я п-подцепил... лихорадку Тернистой д-долины...$B$BТ-точнее, МЫСА Тернистой д-долины...$B$BЭто смертельный вирус...$B$BЕдинственное лекарство... съесть сердце М-мок-ка Д-дикаря... неуловимой... белой гориллы...$B$BЕе может вызвать... только знахарь Унбагва...$B$BИщи знахаря Унбагву в с-скрытой пещере на южном мысу...$B$BПоспеши... я... умираю...','Найдите знахаря Унбагву и попросите его вызвать Мокка Дикаря. Принесите сердце Мокка Фину Горемыку.','Силы возвращаются...$B$BГде же я? В Пиратской Бухте? Вот дела! Мне приснился такой странный сон...$B$BНо слабость пока не отпускает...','...Мама?$B$BХолод-дно...$B$BМеня забирает... Круговерть Пустоты... Мм-мамочка!..','Вернитесь к Фину Горемыку в Пиратскую Бухту у мыса Тернистой долины.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лихорадка Тернистой долины',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Плохо... Мне... т-так п-плохо... Я п-подцепил... лихорадку Тернистой д-долины...$B$BТ-точнее, МЫСА Тернистой д-долины...$B$BЭто смертельный вирус...$B$BЕдинственное лекарство... съесть сердце М-мок-ка Д-дикаря... неуловимой... белой гориллы...$B$BЕе может вызвать... только знахарь Унбагва...$B$BИщи знахаря Унбагву в с-скрытой пещере на южном мысу...$B$BПоспеши... я... умираю...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите знахаря Унбагву и попросите его вызвать Мокка Дикаря. Принесите сердце Мокка Фину Горемыку.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Силы возвращаются...$B$BГде же я? В Пиратской Бухте? Вот дела! Мне приснился такой странный сон...$B$BНо слабость пока не отпускает...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','...Мама?$B$BХолод-дно...$B$BМеня забирает... Круговерть Пустоты... Мм-мамочка!..',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фину Горемыку в Пиратскую Бухту у мыса Тернистой долины.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26598,'Сердце Мокка','врем текст 02 – описание','врем текст 02 – протокол','Знахарь Унбагва любить клык горилла! Моя будет говорить с духи. Пусть придет Мокк Дикарь.$B$BТвоя защищать знахарь Унбагва от других горилл-зверей, или никакой Мокк не быть!','Знахарь Унбагва знать, что нравится Мокка Дикарь. Да, да!$B$BЯ общаться с духами и заставить его прийти!$B$BНо другие горилла-звери тоже говорить с духами. Защити знахарь Унбагва, и я заставить его прийти к тебе.$B$BЗнахарь Унбагва вначале что-то хотеть. Принеси мне клык горилла, чтобы я начать общаться с духами.','Вернитесь к знахарю Унбагве на мыс Тернистой долины.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сердце Мокка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','врем текст 02 – описание',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','врем текст 02 – протокол',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Знахарь Унбагва любить клык горилла! Моя будет говорить с духи. Пусть придет Мокк Дикарь.$B$BТвоя защищать знахарь Унбагва от других горилл-зверей, или никакой Мокк не быть!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Знахарь Унбагва знать, что нравится Мокка Дикарь. Да, да!$B$BЯ общаться с духами и заставить его прийти!$B$BНо другие горилла-звери тоже говорить с духами. Защити знахарь Унбагва, и я заставить его прийти к тебе.$B$BЗнахарь Унбагва вначале что-то хотеть. Принеси мне клык горилла, чтобы я начать общаться с духами.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к знахарю Унбагве на мыс Тернистой долины.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26599,'Сундук капитана','Я ходил на своем корабле отсюда до самого Кабестана, что в Калимдоре. Опытным капитаном был, уважали меня.$B$BПока...$B$BЭти проклятые морские великаны все у меня отобрали! Они разбили мой корабль, погубили всю команду, а меня в спасательной шлюпке отправили в Пиратскую Бухту. Не успокоюсь, пока не кину их трупы на дно морское!$B$BК тому же один из великанов по имени Горлаш украл мой сундук. Я слышал, Горлаш слоняется где-то у побережья к востоку отсюда. Найди его и верни мой сундук. Если все сделаешь, узнаешь, что такое благодарность капитана.','Заберите сундук Смоттса у Горлаша на мысе Тернистой долины.','Вернитесь к капитану Гекельбери Смотсу в Пиратскую Бухту на мыс Тернистой долины.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сундук капитана',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я ходил на своем корабле отсюда до самого Кабестана, что в Калимдоре. Опытным капитаном был, уважали меня.$B$BПока...$B$BЭти проклятые морские великаны все у меня отобрали! Они разбили мой корабль, погубили всю команду, а меня в спасательной шлюпке отправили в Пиратскую Бухту. Не успокоюсь, пока не кину их трупы на дно морское!$B$BК тому же один из великанов по имени Горлаш украл мой сундук. Я слышал, Горлаш слоняется где-то у побережья к востоку отсюда. Найди его и верни мой сундук. Если все сделаешь, узнаешь, что такое благодарность капитана.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заберите сундук Смоттса у Горлаша на мысе Тернистой долины.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Гекельбери Смотсу в Пиратскую Бухту на мыс Тернистой долины.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26600,'Великанское пиршество','Следующего по списку великана зовут Неголаш. Как сейчас вижу – выныривает он из пены морской и хватает беднягу юнгу Поля.$B$BПроглотил в один присест. И еще бизань-мачту мне сломал.$B$BНи один человек из моей команды не заслуживает такой поганой смерти. А потому мы возьмем Неголаша на его прожорливости. Келси Янс пришлет тебе кой-какого мяска, а у Алкача Виски выпивки хватит, чтобы море стало по колено... даже морскому великану. Обоих ты найдешь в городе.','Купите ящик третьесортного мяса у Келси Янса и ящик портвейна "Пупелливербос" у Алкача Виски.','Вернитесь к капитану Гекельбери Смотсу в Пиратскую Бухту на мыс Тернистой долины.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Великанское пиршество',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Следующего по списку великана зовут Неголаш. Как сейчас вижу – выныривает он из пены морской и хватает беднягу юнгу Поля.$B$BПроглотил в один присест. И еще бизань-мачту мне сломал.$B$BНи один человек из моей команды не заслуживает такой поганой смерти. А потому мы возьмем Неголаша на его прожорливости. Келси Янс пришлет тебе кой-какого мяска, а у Алкача Виски выпивки хватит, чтобы море стало по колено... даже морскому великану. Обоих ты найдешь в городе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Купите ящик третьесортного мяса у Келси Янса и ящик портвейна "Пупелливербос" у Алкача Виски.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Гекельбери Смотсу в Пиратскую Бухту на мыс Тернистой долины.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26601,'Мок\'раш Колун','Остался последний – Мок\'раш. Самый большой. Рост – выше штормовой волны, борода – будто лес из водорослей, а молот подобен дубовому дереву.$B$BОн сейчас на маленьком острове Жанейро неподалеку от пристани, сидит и насмехается надо мной. Из-за него я не могу убраться отсюда и вынужден влачить жалкое существование на суше.$B$BЕсли умеешь плавать, доберись до острова Жанейро и убей Мок\'раша.$B$BБереги себя, $n. Справиться Мок\'рашем не так легко, как с его братьями.','Убейте Мок\'раша на острове Жанейро.','Мок\'раш... Неголаш... Горлаш... их больше нет.$B$BТеперь меня ничто не держит, я могу вернуться в море, к любимым грабежам и сокровищам. И все это благодаря тебе!$B$BОсталось вот только судно раздобыть…','Вернитесь к капитану Гекельбери Смотсу в Пиратскую Бухту на мыс Тернистой долины.','Самый здоровый из всех.','Мок\'раш Колун') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мок\'раш Колун',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Остался последний – Мок\'раш. Самый большой. Рост – выше штормовой волны, борода – будто лес из водорослей, а молот подобен дубовому дереву.$B$BОн сейчас на маленьком острове Жанейро неподалеку от пристани, сидит и насмехается надо мной. Из-за него я не могу убраться отсюда и вынужден влачить жалкое существование на суше.$B$BЕсли умеешь плавать, доберись до острова Жанейро и убей Мок\'раша.$B$BБереги себя, $n. Справиться Мок\'рашем не так легко, как с его братьями.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Мок\'раша на острове Жанейро.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мок\'раш... Неголаш... Горлаш... их больше нет.$B$BТеперь меня ничто не держит, я могу вернуться в море, к любимым грабежам и сокровищам. И все это благодаря тебе!$B$BОсталось вот только судно раздобыть…',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Гекельбери Смотсу в Пиратскую Бухту на мыс Тернистой долины.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Самый здоровый из всех.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Мок\'раш Колун',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26602,'Блюдо подается ящиками','Возьми эту провизию, отправляйся на юг вдоль побережья, найди нашу старую спасательную шлюпку и погрузи в нее поклажу. Как только Неголаш почует запах вкусного, он тут же прибежит со всех ног.$B$BКак раз туда, где поджидает $gхрабрый:храбрая:c; |3-6($c), чтобы закинуть его труп подальше в морскую пучину.','Отнесите гигантский ящик еды для великанов в спасательную шлюпку капитана Смоттса, затем приманите с ее помощью Неголаша и убейте его.','Вернитесь к капитану Гекельбери Смотсу в Пиратскую Бухту на мыс Тернистой долины.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Блюдо подается ящиками',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Возьми эту провизию, отправляйся на юг вдоль побережья, найди нашу старую спасательную шлюпку и погрузи в нее поклажу. Как только Неголаш почует запах вкусного, он тут же прибежит со всех ног.$B$BКак раз туда, где поджидает $gхрабрый:храбрая:c; |3-6($c), чтобы закинуть его труп подальше в морскую пучину.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите гигантский ящик еды для великанов в спасательную шлюпку капитана Смоттса, затем приманите с ее помощью Неголаша и убейте его.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Гекельбери Смотсу в Пиратскую Бухту на мыс Тернистой долины.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26603,'Послание в бутылке','В бутылке оказалась записка, написанная красивым почерком. В ней говорится:$B$B<Любому, кто в силах помочь.>$B$B<Прошу, не оставь меня в нужде. Могучий зверь держит меня в плену на острове в Южных морях.>$B$B<По ночам я смотрю на чужие звезды, полускрытые листвой деревьев, но в ясную погоду я вижу линию побережья на северо-западе и большие корабли на юго-западе.>$B$B<Молю тебя, мой будущий спаситель, помоги мне.>','Найдите автора записки на острове Жагуаро в районе мыса Тернистой долины.','Ты здесь, чтобы освободить меня?','Найдите автора записки на острове Жагуаро в районе мыса Тернистой долины.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Послание в бутылке',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В бутылке оказалась записка, написанная красивым почерком. В ней говорится:$B$B<Любому, кто в силах помочь.>$B$B<Прошу, не оставь меня в нужде. Могучий зверь держит меня в плену на острове в Южных морях.>$B$B<По ночам я смотрю на чужие звезды, полускрытые листвой деревьев, но в ясную погоду я вижу линию побережья на северо-западе и большие корабли на юго-западе.>$B$B<Молю тебя, мой будущий спаситель, помоги мне.>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите автора записки на острове Жагуаро в районе мыса Тернистой долины.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты здесь, чтобы освободить меня?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Найдите автора записки на острове Жагуаро в районе мыса Тернистой долины.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26604,'Защита Ее Королевского величества Пубы','Эти злобные кошки из джунглей давно вокруг меня рыщут. Я уж слежу за ними, как могу, но они будто... растворяются в траве.$B$BА как они шипят и рычат!$B$BНе пойми меня неправильно, я хочу, чтобы ты меня $gспас:спасла;, но сначала уничтожь несколько этих кошек. Тем более если меня сожрут на обед, то спасать уже будет некого.','Убейте 5 жагуаров.','Где тебя носило? Я уж думала, сожрут меня тут, пока ты там охотился.$B$BКошке на обед принцессу... Не жирно ли?','Вернитесь к принцессе Пубе на остров Жагуаро у мыса Тернистой долины.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Защита Ее Королевского величества Пубы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти злобные кошки из джунглей давно вокруг меня рыщут. Я уж слежу за ними, как могу, но они будто... растворяются в траве.$B$BА как они шипят и рычат!$B$BНе пойми меня неправильно, я хочу, чтобы ты меня $gспас:спасла;, но сначала уничтожь несколько этих кошек. Тем более если меня сожрут на обед, то спасать уже будет некого.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 5 жагуаров.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Где тебя носило? Я уж думала, сожрут меня тут, пока ты там охотился.$B$BКошке на обед принцессу... Не жирно ли?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к принцессе Пубе на остров Жагуаро у мыса Тернистой долины.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26605,'Загребущие лапки','Понимаю, тебе как можно скорее хочется меня спасти, но еще не время. Для начала я хотела бы вернуть кое-какие свои вещи.$B$BГориллы и мартышки, живущие на другой стороне острова, стащили почти весь мой скарб. Прежде чем уйти, я хочу получить обратно свою тиару, скипетр, туфельки и дневник.$B$BНу что? Не смотри на меня как на сумасшедшую. Ты понятия не имеешь, как трудно быть принцессой.','Заберите у обезьян острова Жагуаро тиару, скипетр, туфли и дневник Пубы.','<Пуба осматривает свои вещи.>$B$BВроде бы все цело. Отлично, теперь можно меня спасать.','В дрожь бросает от одной мысли о том, что со мной хочет сделать Мукла.','Вернитесь к принцессе Пубе на остров Жагуаро у мыса Тернистой долины.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Загребущие лапки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Понимаю, тебе как можно скорее хочется меня спасти, но еще не время. Для начала я хотела бы вернуть кое-какие свои вещи.$B$BГориллы и мартышки, живущие на другой стороне острова, стащили почти весь мой скарб. Прежде чем уйти, я хочу получить обратно свою тиару, скипетр, туфельки и дневник.$B$BНу что? Не смотри на меня как на сумасшедшую. Ты понятия не имеешь, как трудно быть принцессой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заберите у обезьян острова Жагуаро тиару, скипетр, туфли и дневник Пубы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Пуба осматривает свои вещи.>$B$BВроде бы все цело. Отлично, теперь можно меня спасать.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','В дрожь бросает от одной мысли о том, что со мной хочет сделать Мукла.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к принцессе Пубе на остров Жагуаро у мыса Тернистой долины.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26606,'Гибель Муклы','$n, я надеюсь только на тебя. Ты поможешь мне освободиться. Меня держит в плену великий седогривый король Мукла. Он повелевает здешними зверями, и они насильно держат меня на острове. Звери – и эта цепь. Если сумеешь убить Муклу и забрать ключ от моих оков, я буду твоим должником по гроб жизни.$B$BЯ скажу, где найти Муклу. Его голос часто доносится с юго-востока. Но прошу тебя, будь $gосторожен:осторожна;: с ним шутки плохи.','Убейте короля Муклу и заберите ключ от кандалов.','Вернитесь к принцессе Пубе на остров Жагуаро у мыса Тернистой долины.','Могучему небогриву не страшны никакие хищники… кроме вас.','Король Мукла') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гибель Муклы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, я надеюсь только на тебя. Ты поможешь мне освободиться. Меня держит в плену великий седогривый король Мукла. Он повелевает здешними зверями, и они насильно держат меня на острове. Звери – и эта цепь. Если сумеешь убить Муклу и забрать ключ от моих оков, я буду твоим должником по гроб жизни.$B$BЯ скажу, где найти Муклу. Его голос часто доносится с юго-востока. Но прошу тебя, будь $gосторожен:осторожна;: с ним шутки плохи.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте короля Муклу и заберите ключ от кандалов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к принцессе Пубе на остров Жагуаро у мыса Тернистой долины.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Могучему небогриву не страшны никакие хищники… кроме вас.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Король Мукла',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (26606,'Горсмог, ты спас меня от великого позора. Будь на то моя власть, я предложила бы тебе место среди моего народа. Но пока могу предложить тебе только это... в знак благодарности за твои мужество и благородство.','Спасибо предкам, они послали мне помощь в твоем лице! Ты принес ключ?') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Горсмог, ты спас меня от великого позора. Будь на то моя власть, я предложила бы тебе место среди моего народа. Но пока могу предложить тебе только это... в знак благодарности за твои мужество и благородство.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Спасибо предкам, они послали мне помощь в твоем лице! Ты принес ключ?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (26607,'Они первые пролили кровь','Возьми вот эти вещи Кишана и иди обратно в подвал Приозерской таверны. Команда "Браво" уже там, они говорят с Кишаном. Напомни ему о том, кто первым пролил кровь, $n. Кишан очень нужен и Приозерью, и всему Альянсу.$B$BВольно, солдат!','Отнесите Джону Джею Кишану его имущество. Джон находится в таверне Приозерья, в Красногорье.','<Кишан берет у вас сверток и открывает его.>$B$BМой лук… И нож! Где ты…$B$BАмулет Джейд… Моей дорогой Джейд.$B$B<Кишан берет свою красную головную повязку.>$B$BПора бить орков!','Опять ты?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Они первые пролили кровь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Возьми вот эти вещи Кишана и иди обратно в подвал Приозерской таверны. Команда "Браво" уже там, они говорят с Кишаном. Напомни ему о том, кто первым пролил кровь, $n. Кишан очень нужен и Приозерью, и всему Альянсу.$B$BВольно, солдат!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите Джону Джею Кишану его имущество. Джон находится в таверне Приозерья, в Красногорье.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Кишан берет у вас сверток и открывает его.>$B$BМой лук… И нож! Где ты…$B$BАмулет Джейд… Моей дорогой Джейд.$B$B<Кишан берет свою красную головную повязку.>$B$BПора бить орков!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Опять ты?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26608,'Сорванные переговоры','Вернитесь к адмиралу Каменному Кулаку, который находится в море рядом с портом Драконьей Пасти на Сумеречном нагорье.','Орки Запределья предъявляют права на Драконью Пасть? Это немыслимо!$B$BЕсли бы Адский Крик знал, что здесь происходит, он бы сжег их город дотла...','Вернитесь к адмиралу Каменному Кулаку, который находится в море рядом с портом Драконьей Пасти на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сорванные переговоры',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь к адмиралу Каменному Кулаку, который находится в море рядом с портом Драконьей Пасти на Сумеречном нагорье.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Орки Запределья предъявляют права на Драконью Пасть? Это немыслимо!$B$BЕсли бы Адский Крик знал, что здесь происходит, он бы сжег их город дотла...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к адмиралу Каменному Кулаку, который находится в море рядом с портом Драконьей Пасти на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26609,'Пираты Кровавого Паруса','Значит, ты не прочь поработать, дружище? Понять не могу, зачем сухопутной крысе вроде тебя понадобилось помогать Пиратам Черноводья, но не гнать же тебя в шею!$B$BМы только что бросили якорь в Пиратской Бухте и уже прослышали, что у пиратов Кровавого Паруса созрел какой-то план. Все мои ребята слишком увлеклись грогом и девками! А мне нужен разведчик.$B$BОсмотри залив на севере от Пиратской Бухты рядом с Гибельным берегом и расскажи мне, что там происходит.','Первый помощник Кразз попросил вас осмотреть залив на севере от Пиратской Бухты.','На крышке бочки лежат карта, на которой торопливо нацарапано несколько слов, и несколько монет.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пираты Кровавого Паруса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Значит, ты не прочь поработать, дружище? Понять не могу, зачем сухопутной крысе вроде тебя понадобилось помогать Пиратам Черноводья, но не гнать же тебя в шею!$B$BМы только что бросили якорь в Пиратской Бухте и уже прослышали, что у пиратов Кровавого Паруса созрел какой-то план. Все мои ребята слишком увлеклись грогом и девками! А мне нужен разведчик.$B$BОсмотри залив на севере от Пиратской Бухты рядом с Гибельным берегом и расскажи мне, что там происходит.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Первый помощник Кразз попросил вас осмотреть залив на севере от Пиратской Бухты.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','На крышке бочки лежат карта, на которой торопливо нацарапано несколько слов, и несколько монет.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26610,'Вероломство пиратов Кровавого Паруса','Вы видите карту Пиратской Бухты с красным крестиком на том самом месте, где сейчас стоите.$B$BВы читаете рукописное пояснение:$B$B"Установите здесь командный пост и ждите дальнейших распоряжений. Командир флота известит вас, когда придет время действовать."$B$B"Главным здесь я назначаю лейтенанта Брюса. На этот раз все будет иначе. Мы захватим город раз и навсегда."$B$BКарта пришпилена кинжалом, вонзенным прямо в изображение Пиратской Бухты.','Доложите о своей находке первому помощнику Краззу в Пиратской Бухте.','Вернитесь к первому помощнику Краззу в Пиратскую Бухту на мысе Тернистой долины.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вероломство пиратов Кровавого Паруса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы видите карту Пиратской Бухты с красным крестиком на том самом месте, где сейчас стоите.$B$BВы читаете рукописное пояснение:$B$B"Установите здесь командный пост и ждите дальнейших распоряжений. Командир флота известит вас, когда придет время действовать."$B$B"Главным здесь я назначаю лейтенанта Брюса. На этот раз все будет иначе. Мы захватим город раз и навсегда."$B$BКарта пришпилена кинжалом, вонзенным прямо в изображение Пиратской Бухты.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доложите о своей находке первому помощнику Краззу в Пиратской Бухте.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к первому помощнику Краззу в Пиратскую Бухту на мысе Тернистой долины.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26611,'Предупредить барона','Разрази меня гром! Неужто пираты Кровавого Паруса задумали налет на Пиратскую Бухту? Какая дерзость. Это территория Пиратов Черноводья, и так будет всегда!$B$BВижу, дело серьезное. Немедленно отправляйся к барону Ревилгазу и сообщи ему эти новости! Найти его можно здесь же, в Пиратской Бухте.','Сообщите барону Ревилгазу о готовящемся нападении пиратов Кровавого Паруса.','Пираты Кровавого Паруса готовят налет на Пиратскую Бухту? Опять эти мерзавцы взялись за старое! Но наша Бухта неприступна.$B$BВпрочем, кто знает, может, в этот раз они устроят вообще какое-нибудь безумство. С Фираллона станется. Ладно, поживем – увидим.','Отправляйтесь к барону Ревилгазу в Пиратскую Бухту у мыса Тернистой долины.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Предупредить барона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Разрази меня гром! Неужто пираты Кровавого Паруса задумали налет на Пиратскую Бухту? Какая дерзость. Это территория Пиратов Черноводья, и так будет всегда!$B$BВижу, дело серьезное. Немедленно отправляйся к барону Ревилгазу и сообщи ему эти новости! Найти его можно здесь же, в Пиратской Бухте.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сообщите барону Ревилгазу о готовящемся нападении пиратов Кровавого Паруса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Пираты Кровавого Паруса готовят налет на Пиратскую Бухту? Опять эти мерзавцы взялись за старое! Но наша Бухта неприступна.$B$BВпрочем, кто знает, может, в этот раз они устроят вообще какое-нибудь безумство. С Фираллона станется. Ладно, поживем – увидим.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отправляйтесь к барону Ревилгазу в Пиратскую Бухту у мыса Тернистой долины.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26612,'На разведку','Необходимы наиподробнейшие сведения, $n. Мы держим в узде Пиратов Кровавого Паруса прежде всего благодаря нашей крепости в Пиратской Бухте, но и разведка играет немалую роль. Знаешь, как говорится: "Кто владеет информацией, тот владеет миром".$B$BУ Пиратов Кровавого Паруса на юге несколько лагерей, которые они называют своим "Южным командованием". Отправляйся туда, собери информацию, вызнай все планы и перебей пиратов – ну, сколько сможешь. А потом возвращайся с докладом ко мне.','Убейте 8 морских волков из шайки Кровавого Паруса и 8 старших волхвов из шайки Кровавого Паруса и раздобудьте секретные карты и приказы пиратов Кровавого Паруса.','Вернитесь к барону Ревилгазу в Пиратскую Бухту на мысе Тернистой долины.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На разведку',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Необходимы наиподробнейшие сведения, $n. Мы держим в узде Пиратов Кровавого Паруса прежде всего благодаря нашей крепости в Пиратской Бухте, но и разведка играет немалую роль. Знаешь, как говорится: "Кто владеет информацией, тот владеет миром".$B$BУ Пиратов Кровавого Паруса на юге несколько лагерей, которые они называют своим "Южным командованием". Отправляйся туда, собери информацию, вызнай все планы и перебей пиратов – ну, сколько сможешь. А потом возвращайся с докладом ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 морских волков из шайки Кровавого Паруса и 8 старших волхвов из шайки Кровавого Паруса и раздобудьте секретные карты и приказы пиратов Кровавого Паруса.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к барону Ревилгазу в Пиратскую Бухту на мысе Тернистой долины.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26613,'Понюшка табака','Эх, жизнь моряцкая! Не скажу, что сладкая, но это моя жизнь.$B$BКогда я пришел в порт, всего-то хотел найти бутылочку доброго грога и славного табачку. Да, дурные привычки, но что за пират без пороков, верно?$B$BПредставь себе, как же я обломался, когда узнал, что городской травник ушел и еще, к тому же, распродал весь табак. Сказал, что его груз умыкнули эти самые проклятые Кровавые Паруса.$B$BЗуб даю – $gтакой бесстрашный:такая бесстрашная:c; |3-6($c) как ты сумеет объяснить им, что надо делиться?','Диг из Пиратской Бухты хочет, чтобы вы принесли ему 15 понюшек табаку.','Вернитесь к Дигу в Пиратскую Бухту на мысе Тернистой долины.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Понюшка табака',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эх, жизнь моряцкая! Не скажу, что сладкая, но это моя жизнь.$B$BКогда я пришел в порт, всего-то хотел найти бутылочку доброго грога и славного табачку. Да, дурные привычки, но что за пират без пороков, верно?$B$BПредставь себе, как же я обломался, когда узнал, что городской травник ушел и еще, к тому же, распродал весь табак. Сказал, что его груз умыкнули эти самые проклятые Кровавые Паруса.$B$BЗуб даю – $gтакой бесстрашный:такая бесстрашная:c; |3-6($c) как ты сумеет объяснить им, что надо делиться?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Диг из Пиратской Бухты хочет, чтобы вы принесли ему 15 понюшек табаку.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дигу в Пиратскую Бухту на мысе Тернистой долины.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26614,'Смотри в оба','Стой! Кто идет?$B$BРр-р-р, от меня, считай, и толку-то нет без моего особого волшебного глаза. Эх, беда, что я потерял в сражениях глаза, а не что-нибудь другое! Но, по счастью, мы причалили в Менетиле – странствующий колдун сделал мне волшебный стеклянный глаз, и я стал снова видеть.$B$BНо прошлой ночью на меня напали какие-то пираты Кровавого Паруса и отобрали мой глаз! Сдается, эти псы направились в Пиратскую Бухту.$B$BПомоги старому морскому волку, верни мне глаз, а?','Отнимите глаз Диззи у пиратов Кровавого Паруса.','Вернитесь к Диззи Одноглазому в Пиратскую Бухту на мысе Тернистой долины.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Смотри в оба',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Стой! Кто идет?$B$BРр-р-р, от меня, считай, и толку-то нет без моего особого волшебного глаза. Эх, беда, что я потерял в сражениях глаза, а не что-нибудь другое! Но, по счастью, мы причалили в Менетиле – странствующий колдун сделал мне волшебный стеклянный глаз, и я стал снова видеть.$B$BНо прошлой ночью на меня напали какие-то пираты Кровавого Паруса и отобрали мой глаз! Сдается, эти псы направились в Пиратскую Бухту.$B$BПомоги старому морскому волку, верни мне глаз, а?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнимите глаз Диззи у пиратов Кровавого Паруса.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Диззи Одноглазому в Пиратскую Бухту на мысе Тернистой долины.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (26616,'Ни конца ни края','Для того чтобы справиться с тобой и командой "Браво", $n, этим оркам из Черной горы понадобится целая армия, не меньше! Когда будешь $gготов:готова;, приходи к нам в док у Озера Безмолвия, и мы отправимся на лодке в лагерь на другой стороне озера.$B$BНу, до встречи, $n!','Отправьтесь на лодке Кишана в Лагерь Безмолвия в Красногорье.','Пора убивать орков.','Поездка на лодке Кишана закончена','Поговорите с Джоном Джеем Кишан в Лагере Безмолвия, что в Красногорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ни конца ни края',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Для того чтобы справиться с тобой и командой "Браво", $n, этим оркам из Черной горы понадобится целая армия, не меньше! Когда будешь $gготов:готова;, приходи к нам в док у Озера Безмолвия, и мы отправимся на лодке в лагерь на другой стороне озера.$B$BНу, до встречи, $n!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправьтесь на лодке Кишана в Лагерь Безмолвия в Красногорье.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Пора убивать орков.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Поездка на лодке Кишана закончена',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Джоном Джеем Кишан в Лагере Безмолвия, что в Красногорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (26617,'Старый пират','Эту старую потертую монету нашли у мертвого пирата Брюса по прозвищу "Славный парень". Видишь, с одной стороны отчеканен какой-то большой, неизвестный пиратский корабль, а с другой – надпись: "Крушащая Волна".$B$BНадо бы расспросить тех, кто давно имеет дело с пиратами, что это за монета.','Покажите истертую монету командиру флота Морскому Рогу в Пиратской Бухте.','Ого! Где ты взял эту монету?$B$BБрюс... да, понятно. Когда-то он был одним пиратов Черноводья. До того, как Седогрив закрыл порты Гилнеаса и взял в плен всю его команду.$B$BЯ знаю, что происходящее в Гилнеасе меняет людей... и не в лучшую сторону. Но не думал, что кто-то из наших станет предателем. И особенно Брюс.$B$BЕсли не возражаешь, я оставлю монету себе. А взамен дам тебе золото.','Отправьтесь к командиру флота Морскому Рогу в Пиратскую Бухту на мысе Тернистой долины.','Брюс Кэллоус, до приступа морской болезни','Брюс Кэллоус') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Старый пират',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эту старую потертую монету нашли у мертвого пирата Брюса по прозвищу "Славный парень". Видишь, с одной стороны отчеканен какой-то большой, неизвестный пиратский корабль, а с другой – надпись: "Крушащая Волна".$B$BНадо бы расспросить тех, кто давно имеет дело с пиратами, что это за монета.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Покажите истертую монету командиру флота Морскому Рогу в Пиратской Бухте.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ого! Где ты взял эту монету?$B$BБрюс... да, понятно. Когда-то он был одним пиратов Черноводья. До того, как Седогрив закрыл порты Гилнеаса и взял в плен всю его команду.$B$BЯ знаю, что происходящее в Гилнеасе меняет людей... и не в лучшую сторону. Но не думал, что кто-то из наших станет предателем. И особенно Брюс.$B$BЕсли не возражаешь, я оставлю монету себе. А взамен дам тебе золото.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отправьтесь к командиру флота Морскому Рогу в Пиратскую Бухту на мысе Тернистой долины.',`completedtext_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Брюс Кэллоус, до приступа морской болезни',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Брюс Кэллоус',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26618,'Волки идут по пятам','Лютые волки – самая распространенная угроза для местных горожан. Опасен весь лес вокруг нас, но больше всего волков вдоль северного берега реки.$b$bИ это не те полудохлые псы, которых ты $gвидел:видела; в Элвиннском лесу или откуда ты там $gпришел:пришла;. Они в два раза более злобные и размером с человека.$b$bЕсли хочешь помочь жителям Темнолесья, поохоться на лютых волков, чтобы мы могли спокойнее ходить по улицам.','Убейте 12 лютых волков.','Не думай, что легко отделался. В лесах таятся и куда более серьезные опасности.','Вернитесь к командиру Алтее Чернодрев в Темнолесье, что в Сумеречном лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Волки идут по пятам',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Лютые волки – самая распространенная угроза для местных горожан. Опасен весь лес вокруг нас, но больше всего волков вдоль северного берега реки.$b$bИ это не те полудохлые псы, которых ты $gвидел:видела; в Элвиннском лесу или откуда ты там $gпришел:пришла;. Они в два раза более злобные и размером с человека.$b$bЕсли хочешь помочь жителям Темнолесья, поохоться на лютых волков, чтобы мы могли спокойнее ходить по улицам.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 лютых волков.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Не думай, что легко отделался. В лесах таятся и куда более серьезные опасности.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру Алтее Чернодрев в Темнолесье, что в Сумеречном лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26619,'Значит, ты за революцию?','Проникните в порт Драконьей Пасти и поговорите с Зелой.','Проникните в порт Драконьей Пасти и поговорите с Зелой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Значит, ты за революцию?',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проникните в порт Драконьей Пасти и поговорите с Зелой.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Проникните в порт Драконьей Пасти и поговорите с Зелой.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26620,'Пряные котлеты из волчатины','Мое коронное блюдо – пряные котлеты из волчатины! Разумеется, я могу тебе их пожарить. Но для этого мне понадобятся кое-какие продукты.$b$bПринеси 5 стейков из волчьей грудинки. Лютые волки, которые водятся у реки, что к северу от города, отлично подойдут. Но на твоем месте я бы не заходил глубоко в лес...','Добудьте 5 стейков из волчьей грудинки, убивая лютых волков.','Ммм-ммм! Грудинка – это лучшая часть туши волка. Хотя это и не традиционный способ готовить эти котлеты.$B$BВот, держи рецепт. Он немного отличается, но когда тебе действительно потребуется еда, мясо с волчьих боков будет достать проще.','Удалось достать 5 стейков из волчьей грудинки?','Вернитесь к шеф-повару Груалю в Темнолесье, что в Сумеречном лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пряные котлеты из волчатины',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мое коронное блюдо – пряные котлеты из волчатины! Разумеется, я могу тебе их пожарить. Но для этого мне понадобятся кое-какие продукты.$b$bПринеси 5 стейков из волчьей грудинки. Лютые волки, которые водятся у реки, что к северу от города, отлично подойдут. Но на твоем месте я бы не заходил глубоко в лес...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 5 стейков из волчьей грудинки, убивая лютых волков.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ммм-ммм! Грудинка – это лучшая часть туши волка. Хотя это и не традиционный способ готовить эти котлеты.$B$BВот, держи рецепт. Он немного отличается, но когда тебе действительно потребуется еда, мясо с волчьих боков будет достать проще.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось достать 5 стейков из волчьей грудинки?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к шеф-повару Груалю в Темнолесье, что в Сумеречном лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26621,'Восстание','Вооружите 3 рабочих или торговцев из клана Драконьей Пасти, а затем убейте 10 головорезов из клана Драконьей Пасти и 4 чернокнижника из клана Драконьей Пасти.','Вернитесь в порт Драконьей Пасти на Сумеречном нагорье и поговорите с Зелой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Восстание',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вооружите 3 рабочих или торговцев из клана Драконьей Пасти, а затем убейте 10 головорезов из клана Драконьей Пасти и 4 чернокнижника из клана Драконьей Пасти.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь в порт Драконьей Пасти на Сумеречном нагорье и поговорите с Зелой.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26622,'Смерть Мор\'гору!','Вернитесь в порт Драконьей Пасти на Сумеречном нагорье и поговорите с Гаррошем Адским Криком.','Мор\'гор выжил в Запределье. Но сегодня он умрет.','Полководец Мор\'гор') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Смерть Мор\'гору!',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь в порт Драконьей Пасти на Сумеречном нагорье и поговорите с Гаррошем Адским Криком.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Мор\'гор выжил в Запределье. Но сегодня он умрет.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Полководец Мор\'гор',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26623,'Темные пирожки с крабами','Открою тебе тайну: темные пирожки с "крабами" на самом деле пекутся с паучьим мясом! Понимаю, это может звучать не совсем приятно, но пирожки получаются вкусные и ароматные – отличная закуска!$b$bЕсли хочешь их попробовать, то, боюсь, у меня кончилось мясо. Чтобы я смог испечь еще, мне нужны кусочки темного паучьего мяса.$b$bМясо ядовитых кругопрядов отлично подойдет. Их можно найти к северу отсюда, между предгорьями и рекой.','Добудьте 6 кусочков темного паучьего мяса ядовитых кругопрядов.','О, отличные кусочки! Дай-ка я замариную их особым составом, – не подсматривай! – потом хорошенько подрумяню на сковородке…$B$BТемные пирожки с крабами – мое коронное блюдо, и рецептом я делиться не готов, но вот тебе рецепт другого кушанья, не хуже.','Вернитесь к шеф-повару Груалю в Темнолесье, что в Сумеречном лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Темные пирожки с крабами',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Открою тебе тайну: темные пирожки с "крабами" на самом деле пекутся с паучьим мясом! Понимаю, это может звучать не совсем приятно, но пирожки получаются вкусные и ароматные – отличная закуска!$b$bЕсли хочешь их попробовать, то, боюсь, у меня кончилось мясо. Чтобы я смог испечь еще, мне нужны кусочки темного паучьего мяса.$b$bМясо ядовитых кругопрядов отлично подойдет. Их можно найти к северу отсюда, между предгорьями и рекой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 6 кусочков темного паучьего мяса ядовитых кругопрядов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, отличные кусочки! Дай-ка я замариную их особым составом, – не подсматривай! – потом хорошенько подрумяню на сковородке…$B$BТемные пирожки с крабами – мое коронное блюдо, и рецептом я делиться не готов, но вот тебе рецепт другого кушанья, не хуже.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к шеф-повару Груалю в Темнолесье, что в Сумеречном лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (26624,'Связи с Кровавым Парусом','Да, это ты правильно решил!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Связи с Кровавым Парусом',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, это ты правильно решил!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26625,'Троггзор Терранатор','Ты $gдолжен:должна; положить этому конец!$b$bВозвращайся на северо-запад, на передовую и убей их генерала, Троггзора Терранатора. В качестве доказательства принеси мне его дубинку.','Добудьте дубинку Терранатора.','<Генерал торжественно кивает.>$B$BНаконец-то мы можем двигаться дальше и спасти Отца-Скалу.','Вернитесь к Гравию Долгопласту на Разбитую передовую в Подземье.','Останови его, пока не поздно!','Троггзор Терранатор') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Троггзор Терранатор',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gдолжен:должна; положить этому конец!$b$bВозвращайся на северо-запад, на передовую и убей их генерала, Троггзора Терранатора. В качестве доказательства принеси мне его дубинку.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте дубинку Терранатора.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Генерал торжественно кивает.>$B$BНаконец-то мы можем двигаться дальше и спасти Отца-Скалу.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гравию Долгопласту на Разбитую передовую в Подземье.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Останови его, пока не поздно!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Троггзор Терранатор',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26626,'У нас проблема','Одна из катапульт Глина сломалась прямо на линии фронта. Возьми у него запчасти и верни ее в строй.','[Deprecated] Speak with Clay Mudaxle on the Fractured Front in Deepholm.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','У нас проблема',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Одна из катапульт Глина сломалась прямо на линии фронта. Возьми у него запчасти и верни ее в строй.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','[Deprecated] Speak with Clay Mudaxle on the Fractured Front in Deepholm.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26627,'Отшельник','Разыщите обитателей башни в Приюте Бродяги.','Добро пожаловать, странник. Я бы предложил тебе что-нибудь, но тут шаром покати…$B$BМожешь выполнить одно поручение бедного старого отшельника?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отшельник',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите обитателей башни в Приюте Бродяги.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Добро пожаловать, странник. Я бы предложил тебе что-нибудь, но тут шаром покати…$B$BМожешь выполнить одно поручение бедного старого отшельника?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`) VALUES (26628,'Смерть со дна морского','Это плохо. Похоже, клан Пронзающего Гребня готовится к нападению.$B$BНаги известны своей жестокостью в бою. Они не остановятся, пока я не буду мертв.$B$BНе то чтобы я ценил свою жизнь выше, чем жизни членов команды, но ты $gдолжен:должна; помочь защитить меня. Я единственный, кто знает морские пути, команда просто не сможет вернуться в Пиратскую Бухту без меня.$B$BНаги придут с моря. Мне нужно, чтобы ты $gоставался:оставалась; здесь, со мной, чтобы отразить их атаку. Орудия к бою! Надо оттеснить их.$B$BТы $gготов:готова;, $n?','Защитите Мураша О\'Брина во время атаки.','Защитите Мураша О\'Брина') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Смерть со дна морского',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это плохо. Похоже, клан Пронзающего Гребня готовится к нападению.$B$BНаги известны своей жестокостью в бою. Они не остановятся, пока я не буду мертв.$B$BНе то чтобы я ценил свою жизнь выше, чем жизни членов команды, но ты $gдолжен:должна; помочь защитить меня. Я единственный, кто знает морские пути, команда просто не сможет вернуться в Пиратскую Бухту без меня.$B$BНаги придут с моря. Мне нужно, чтобы ты $gоставался:оставалась; здесь, со мной, чтобы отразить их атаку. Орудия к бою! Надо оттеснить их.$B$BТы $gготов:готова;, $n?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Защитите Мураша О\'Брина во время атаки.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Защитите Мураша О\'Брина',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26629,'Вопрос лояльности','Добудьте голову командира флота Морского Рога.','Якорь мне в глотку! Такое не каждый день увидишь.$B$B<Янси пожимает вам руку.>$B$BДобро пожаловать на борт, $n. Несметные сокровища ждут тебя.','Фираллон лично отдал этот приказ. Говорит, много проблем от этого таурена.','Вернитесь к Йенси Гриллсену на мысе Тернистой долины.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вопрос лояльности',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте голову командира флота Морского Рога.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Якорь мне в глотку! Такое не каждый день увидишь.$B$B<Янси пожимает вам руку.>$B$BДобро пожаловать на борт, $n. Несметные сокровища ждут тебя.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Фираллон лично отдал этот приказ. Говорит, много проблем от этого таурена.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Йенси Гриллсену на мысе Тернистой долины.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (26630,'Вполне похоже на таурена-пирата','Раздобудьте коровью голову и огромную пиратскую шляпу, а затем отнесите их командиру флота Морскому Рогу.','Этот тупица из Кровавого Паруса точно купится.$B$BНу и веселуха, $n.','Тебе следует знать: большинство тауренов сочли бы такой поступок постыдным. А по-моему... это забавно.','Вернитесь к командиру флота Морскому Рогу в Пиратскую Бухту на мысе Тернистой долины.','Спи спокойно, милая королева. Твоя жертва не будет забыта.','Бодунья') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вполне похоже на таурена-пирата',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте коровью голову и огромную пиратскую шляпу, а затем отнесите их командиру флота Морскому Рогу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Этот тупица из Кровавого Паруса точно купится.$B$BНу и веселуха, $n.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе следует знать: большинство тауренов сочли бы такой поступок постыдным. А по-моему... это забавно.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру флота Морскому Рогу в Пиратскую Бухту на мысе Тернистой долины.',`completedtext_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Спи спокойно, милая королева. Твоя жертва не будет забыта.',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Бодунья',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26631,'Пират-новичок','Может быть, от твоей руки и принимали смерть командиры флотов, но правила есть правила, а приказы есть приказы. У меня такой порядок: все новички работают юнгами. Это закон.$B$BТы будешь служить у капитана Кильвателя на "Буруне". Это крайний к западу корабль, пришвартованный к югу от мыса.$B$BНайдешь Кильвателя в капитанской каюте. Покажи ему свои бумаги.','Покажите свои бумаги капитану Кильвателю.','Да-да... Понятно... Что ж, видимо, все в порядке.$B$BЗначит, великого Морского Рога убил ты? Так вот, на моем корабле это не имеет никакого значения. Здесь ты будешь убивать только бактерии на палубах. Бери швабру.','Надеюсь, бумаги при тебе, юнга. Не хотелось бы отправлять тебя обратно к Йенси.','Доложите о своем прибытии капитану Кильвателю на "Буруне", стоящем у мыса Тернистой долины.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пират-новичок',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Может быть, от твоей руки и принимали смерть командиры флотов, но правила есть правила, а приказы есть приказы. У меня такой порядок: все новички работают юнгами. Это закон.$B$BТы будешь служить у капитана Кильвателя на "Буруне". Это крайний к западу корабль, пришвартованный к югу от мыса.$B$BНайдешь Кильвателя в капитанской каюте. Покажи ему свои бумаги.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Покажите свои бумаги капитану Кильвателю.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да-да... Понятно... Что ж, видимо, все в порядке.$B$BЗначит, великого Морского Рога убил ты? Так вот, на моем корабле это не имеет никакого значения. Здесь ты будешь убивать только бактерии на палубах. Бери швабру.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Надеюсь, бумаги при тебе, юнга. Не хотелось бы отправлять тебя обратно к Йенси.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доложите о своем прибытии капитану Кильвателю на "Буруне", стоящем у мыса Тернистой долины.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26632,'Сопровождение','Ну ладно, думаю, теперь она работает. Тебе нужно доставить катапульту в место обитания каменных троггов, Шлаковый зал, это к северу от передовой.$b$bВодитель отправится с тобой. А я вернусь назад и дам знать Гравию.$b$bКаменные трогги наверняка попытаются помешать тебе. Будут приближаться – открывай огонь. Стреляет она будь здоров.$b$bДай мне знать, когда будешь $gготов:готова;, $n.','Доставьте катапульту земельников в целости и сохранности в Шлаковый зал.','Поговорите с Колчеданом Магнетием в Шлаковом зале, что в Подземье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сопровождение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну ладно, думаю, теперь она работает. Тебе нужно доставить катапульту в место обитания каменных троггов, Шлаковый зал, это к северу от передовой.$b$bВодитель отправится с тобой. А я вернусь назад и дам знать Гравию.$b$bКаменные трогги наверняка попытаются помешать тебе. Будут приближаться – открывай огонь. Стреляет она будь здоров.$b$bДай мне знать, когда будешь $gготов:готова;, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте катапульту земельников в целости и сохранности в Шлаковый зал.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Колчеданом Магнетием в Шлаковом зале, что в Подземье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26633,'Обязанности уборщика','Так! Чтобы палуба "Буруна" сияла, как звездный рубин, юнга $n. Я слежу за порядком на этом судне, а наводить его должны такие бездельники, как ты!$B$BНу, чего ты ждешь, бестолочь? А ну, живо драить палубу!','Возьмите на палубе "Буруна" швабру юнги и мойте пол в течение 2 минут.','Слышал, кто-то здесь усердно натирает пол. Да, приятель, это именно то, что хотел услышать капитан.','Вернитесь к капитану Кильвателю на "Бурун" у мыса Тернистой долины.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обязанности уборщика',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Так! Чтобы палуба "Буруна" сияла, как звездный рубин, юнга $n. Я слежу за порядком на этом судне, а наводить его должны такие бездельники, как ты!$B$BНу, чего ты ждешь, бестолочь? А ну, живо драить палубу!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возьмите на палубе "Буруна" швабру юнги и мойте пол в течение 2 минут.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Слышал, кто-то здесь усердно натирает пол. Да, приятель, это именно то, что хотел услышать капитан.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Кильвателю на "Бурун" у мыса Тернистой долины.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26634,'Бич пиратов','Болезнь десен. Это настоящая беда, |3-6($r).$B$BЯ знаю, ты тут недавно и у тебя наверняка еще не возникало необходимости резать десны. А вот нам, бывалым пиратам, приходится иметь дело с такой штукой как ЦИНГА. Вот почему здесь столько лаймов.$B$BВ смысле... раньше мы их здесь хранили. Кто-то умыкнул у нас последнюю партию, но далеко воры уйти не могли – может, они на одном из ближайших островов? Верни лаймы, а уж я поратую за твое повышение, юнга.','Раздобудьте 5 бушелей лаймов.','Вернитесь к Гарру Просоленному Копыту на "Бурун" у мыса Тернистой долины.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бич пиратов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Болезнь десен. Это настоящая беда, |3-6($r).$B$BЯ знаю, ты тут недавно и у тебя наверняка еще не возникало необходимости резать десны. А вот нам, бывалым пиратам, приходится иметь дело с такой штукой как ЦИНГА. Вот почему здесь столько лаймов.$B$BВ смысле... раньше мы их здесь хранили. Кто-то умыкнул у нас последнюю партию, но далеко воры уйти не могли – может, они на одном из ближайших островов? Верни лаймы, а уж я поратую за твое повышение, юнга.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте 5 бушелей лаймов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гарру Просоленному Копыту на "Бурун" у мыса Тернистой долины.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26635,'Ныряние за ядрами','Поможешь несчастному юнге?$B$BКильватель велел мне подобрать несколько пушечных ядер со дна океана. Давай объясню, почему эта задача для меня непосильна.$B$BПервое: у меня маленькие руки. $GСам:Сама; посмотри! Думаешь, я этими ручонками сумею подобрать тяжеленное пушечное ядро? Даже под водой...$B$BВторое: у меня слабая дыхательная система. Не могу задержать дыхание дольше чем на десять секунд.$B$BТретье: там акулы.$B$BПомоги мне, $n! Я и так теперь всего лишь юнга... Не хочу, чтобы меня опять понизили!','Добудьте 6 пушечных ядер Кровавого Паруса из-под "Буруна".','Вернитесь к "Красавчику" Дункану на "Бурун" у мыса Тернистой долины.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ныряние за ядрами',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Поможешь несчастному юнге?$B$BКильватель велел мне подобрать несколько пушечных ядер со дна океана. Давай объясню, почему эта задача для меня непосильна.$B$BПервое: у меня маленькие руки. $GСам:Сама; посмотри! Думаешь, я этими ручонками сумею подобрать тяжеленное пушечное ядро? Даже под водой...$B$BВторое: у меня слабая дыхательная система. Не могу задержать дыхание дольше чем на десять секунд.$B$BТретье: там акулы.$B$BПомоги мне, $n! Я и так теперь всего лишь юнга... Не хочу, чтобы меня опять понизили!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 6 пушечных ядер Кровавого Паруса из-под "Буруна".',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к "Красавчику" Дункану на "Бурун" у мыса Тернистой долины.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26636,'Полевой набор компании "Браво": Маскировка','Для того чтобы разобраться с армией Черной горы и спасти Красногорье, нам нужны припасы. С этим-то ты нам и поможешь, $gновичок:новенькая;.$B$BКишан велел мне собрать маскировку для полевого набора команды "Браво", поэтому тебе нужно будет отправиться на юг и немного там "посадовничать". Для маскировки нужны листья и лисьи экскременты.$B$BНет, а ты как $gдумал:думала;, из чего, по-твоему, делают камуфляж?$B$BТак что иди на юг и собери то, что я просил, $gприятель:подруга;.','Соберите 5 охапок листьев и 5 кучек лисьих экскрементов.','Молодец, салага. Пойду положу всю эту маскировку в ящик. Скоро все будет готово.','Экскременты и листья, – вот все, что мне нужно.','Вернитесь к Кракауеру в Лагерь Безмолвия, что в Красногорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Полевой набор компании "Браво": Маскировка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Для того чтобы разобраться с армией Черной горы и спасти Красногорье, нам нужны припасы. С этим-то ты нам и поможешь, $gновичок:новенькая;.$B$BКишан велел мне собрать маскировку для полевого набора команды "Браво", поэтому тебе нужно будет отправиться на юг и немного там "посадовничать". Для маскировки нужны листья и лисьи экскременты.$B$BНет, а ты как $gдумал:думала;, из чего, по-твоему, делают камуфляж?$B$BТак что иди на юг и собери то, что я просил, $gприятель:подруга;.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 5 охапок листьев и 5 кучек лисьих экскрементов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Молодец, салага. Пойду положу всю эту маскировку в ящик. Скоро все будет готово.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Экскременты и листья, – вот все, что мне нужно.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кракауеру в Лагерь Безмолвия, что в Красногорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26637,'Полевой набор компании "Браво": Хлороформ','Первая часть нашего задания – это только тайные операции, $n. Поэтому нам нужно лишить врагов дееспособности, и чтоб ни звука, а для этого потребуется хлороформ.$B$BХлороформ можно извлечь из гланд грязекопов, которые живут на дне озера Безмолвия, но для этого придется нырять и сражаться под водой. Как думаешь, у тебя получится?$B$BКогда соберешь достаточно гланд, неси их сюда.$B$BЧто? Где озеро? Глаза разуй, чучело! Прямо к западу отсюда.','Соберите 8 гланд грязекопов.','Отлично. Орки теперь и пикнуть не успеют. Так, сейчас я подготовлю тут все, что нужно, а потом сложу все в полевой набор.','Удалось добыть гланды?','Вернитесь к Месснеру в Лагерь Безмолвия, что в Красногорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Полевой набор компании "Браво": Хлороформ',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Первая часть нашего задания – это только тайные операции, $n. Поэтому нам нужно лишить врагов дееспособности, и чтоб ни звука, а для этого потребуется хлороформ.$B$BХлороформ можно извлечь из гланд грязекопов, которые живут на дне озера Безмолвия, но для этого придется нырять и сражаться под водой. Как думаешь, у тебя получится?$B$BКогда соберешь достаточно гланд, неси их сюда.$B$BЧто? Где озеро? Глаза разуй, чучело! Прямо к западу отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 гланд грязекопов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично. Орки теперь и пикнуть не успеют. Так, сейчас я подготовлю тут все, что нужно, а потом сложу все в полевой набор.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось добыть гланды?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Месснеру в Лагерь Безмолвия, что в Красногорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26638,'Охота на охотников','К югу отсюда, на Озерном тракте, орудует банда орков Черной горы. Они бродят по лесам и в темноте нападают на прохожих. Эта банда – первая линия защиты армии Черной горы. Они разведчики, доносят обо всем, что видят, своему верховному командованию. Нужно уничтожить их, или вся наша деятельность здесь окажется под угрозой.$B$BВперед: отправляйся на юг и убей всякого охотника из клана Черной горы, кого встретишь.','Убейте 8 охотников из клана Черной горы.','Вернитесь к Данфорту в Лагерь Безмолвия, что в Красногорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота на охотников',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','К югу отсюда, на Озерном тракте, орудует банда орков Черной горы. Они бродят по лесам и в темноте нападают на прохожих. Эта банда – первая линия защиты армии Черной горы. Они разведчики, доносят обо всем, что видят, своему верховному командованию. Нужно уничтожить их, или вся наша деятельность здесь окажется под угрозой.$B$BВперед: отправляйся на юг и убей всякого охотника из клана Черной горы, кого встретишь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 охотников из клана Черной горы.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Данфорту в Лагерь Безмолвия, что в Красногорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26639,'Информатор Сухопек','Нужно собрать весь набор, без него мы ничего не сможем сделать. Помоги нам еще раз, $n. Кое-какие данные можно получить только от разведчика, и, к счастью, нам помогает кое-кто из Штормграда. ШРУ прислало сюда моего старинного боевого товарища по имени Сухопек, и он все для нас вынюхивает. Тебе надо будет встретиться с ним в поле, это к югу отсюда.$B$BИди, найди его и узнай, что он там успел разведать.','Найдите Сухопека.','Сухопек мертв. Судя по всему, таким жутким образом орки пытались передать некое предупреждение. Осмотрев тело Сухопека, вы замечаете что-то в его сумке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Информатор Сухопек',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нужно собрать весь набор, без него мы ничего не сможем сделать. Помоги нам еще раз, $n. Кое-какие данные можно получить только от разведчика, и, к счастью, нам помогает кое-кто из Штормграда. ШРУ прислало сюда моего старинного боевого товарища по имени Сухопек, и он все для нас вынюхивает. Тебе надо будет встретиться с ним в поле, это к югу отсюда.$B$BИди, найди его и узнай, что он там успел разведать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Сухопека.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сухопек мертв. Судя по всему, таким жутким образом орки пытались передать некое предупреждение. Осмотрев тело Сухопека, вы замечаете что-то в его сумке.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26640,'Немыслимые зверства','<Вы разворачиваете записку и принимаетесь читать.>$B$BКишан, если ты это читаешь, значит, я мертв. Скорее всего, меня кто-то выдал.$B$BОрки чинят над своими пленниками немыслимые зверства. Да, Кишан, у них полны клетки военнопленных. Если вы хотите взорвать эту долину, то сперва придется освободить их.$B$BПередай жене, что я ее люблю, и чтобы она сама вынесла проклятущий мусор.$B$B– Сухопек$B$BP.S. У них есть черные драконы.$B$BОтнесите донесение Сухопека Кишану.','Отнесите донесение Сухопека Джону Джею Кишану в Лагерь Безмолвия в Красногорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Немыслимые зверства',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Вы разворачиваете записку и принимаетесь читать.>$B$BКишан, если ты это читаешь, значит, я мертв. Скорее всего, меня кто-то выдал.$B$BОрки чинят над своими пленниками немыслимые зверства. Да, Кишан, у них полны клетки военнопленных. Если вы хотите взорвать эту долину, то сперва придется освободить их.$B$BПередай жене, что я ее люблю, и чтобы она сама вынесла проклятущий мусор.$B$B– Сухопек$B$BP.S. У них есть черные драконы.$B$BОтнесите донесение Сухопека Кишану.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите донесение Сухопека Джону Джею Кишану в Лагерь Безмолвия в Красногорье.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26641,'Без яиц яичницу не сделаешь...','За кладкой Шадры следят смотрители выводка из племени Порочной Ветви, они обосновались к северу отсюда. Даже если мы перебьем все это троллье племя, кладка останется на месте, и в один прекрасный день из нее вылупятся жуткие твари и разбегутся по лесам.$B$BТакого допускать нельзя. Вытащи все яйца, которые увидишь, из кладки и принеси мне. $GСам:Сама; их уничтожить не пытайся, еще упустишь эту мелюзгу!$B$BТащи все мне, а я уж позабочусь о яйцах.','Соберите 5 яиц порождения Шадры в Агол\'вате.','Я прослежу, чтобы их немедленно сожгли дотла, а пепел развеяли по ветру.','Вернитесь к Гилде Призывающей Облака в Сторожку Кель\'Данил, что во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Без яиц яичницу не сделаешь...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','За кладкой Шадры следят смотрители выводка из племени Порочной Ветви, они обосновались к северу отсюда. Даже если мы перебьем все это троллье племя, кладка останется на месте, и в один прекрасный день из нее вылупятся жуткие твари и разбегутся по лесам.$B$BТакого допускать нельзя. Вытащи все яйца, которые увидишь, из кладки и принеси мне. $GСам:Сама; их уничтожить не пытайся, еще упустишь эту мелюзгу!$B$BТащи все мне, а я уж позабочусь о яйцах.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 5 яиц порождения Шадры в Агол\'вате.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я прослежу, чтобы их немедленно сожгли дотла, а пепел развеяли по ветру.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гилде Призывающей Облака в Сторожку Кель\'Данил, что во Внутренних землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (26642,'Во спасение Степей.','А, новичок из Оргриммара?$B$B<Каргал оценивающе окидывает вас взглядом.>$B$BЛадно, придется тебя взять на работу. Кому же еще охранять дорогу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Во спасение Степей.',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, новичок из Оргриммара?$B$B<Каргал оценивающе окидывает вас взглядом.>$B$BЛадно, придется тебя взять на работу. Кому же еще охранять дорогу.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26643,'На голодном пайке','Ползучие руины, что к востоку отсюда, кишат здоровенными паучищами, отродьями Шадры. Они настолько огромные, что могут утащить целого дворфа под покровом темной ночи, и когда ты придешь туда, то увидишь тому немало доказательств. Там по всем руинам разбросаны тела и оплетенные жертвы.$B$BДолго они им жить не дают, $n, но одним телом они могут питаться несколько дней. Спасать пленников уже поздно, но нельзя позволять этим паукам жиреть. Поэтому уничтожь тамошние коконы.','Уничтожьте 6 оплетенных жертв в Ползучих руинах.','Вернитесь к Гилде Призывающей Облака в Сторожку Кель\'Данил, что во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На голодном пайке',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ползучие руины, что к востоку отсюда, кишат здоровенными паучищами, отродьями Шадры. Они настолько огромные, что могут утащить целого дворфа под покровом темной ночи, и когда ты придешь туда, то увидишь тому немало доказательств. Там по всем руинам разбросаны тела и оплетенные жертвы.$B$BДолго они им жить не дают, $n, но одним телом они могут питаться несколько дней. Спасать пленников уже поздно, но нельзя позволять этим паукам жиреть. Поэтому уничтожь тамошние коконы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 6 оплетенных жертв в Ползучих руинах.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гилде Призывающей Облака в Сторожку Кель\'Данил, что во Внутренних землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26644,'Новые горизонты','Дружище $n! Печальный день сегодня выдался для старика Кильвателя... выходит, мы расстаемся.$B$BПришло письмо от командира флота Фираллона. Узнал он про твои успехи и хочет взять помощником на свою "Кровавую завесу". Они с "Буруном" рядом пришвартованы.$B$BЭто для тебя отличный шанс, дружище $n. Ты лучше соглашайся.$B$B$GСвободен:Свободна;!','Отправляйтесь к командиру флота Фираллону на "Кровавую завесу", швартующуюся у мыса Тернистой долины.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новые горизонты',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Дружище $n! Печальный день сегодня выдался для старика Кильвателя... выходит, мы расстаемся.$B$BПришло письмо от командира флота Фираллона. Узнал он про твои успехи и хочет взять помощником на свою "Кровавую завесу". Они с "Буруном" рядом пришвартованы.$B$BЭто для тебя отличный шанс, дружище $n. Ты лучше соглашайся.$B$B$GСвободен:Свободна;!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь к командиру флота Фираллону на "Кровавую завесу", швартующуюся у мыса Тернистой долины.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`objectives_loc8`,`completedtext_loc8`) VALUES (26645,'Убейте 8 гниющих ужасов возле фермы Слепой Мэри, что к юго-востоку от Темнолесья.','Вернитесь к командиру Алтее Чернодрев в Темнолесье, что в Сумеречном лесу.') ON DUPLICATE KEY UPDATE `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 гниющих ужасов возле фермы Слепой Мэри, что к юго-востоку от Темнолесья.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру Алтее Чернодрев в Темнолесье, что в Сумеречном лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (26646,'Военнопленные','Освободите военнопленных, запертых в клетке в долине Ренда.','Вернитесь к Джону Джею Кишану в Лагерь Безмолвия, что в Красногорье.','Война у меня в крови.','Джон Джей Кишан') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Военнопленные',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Освободите военнопленных, запертых в клетке в долине Ренда.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джону Джею Кишану в Лагерь Безмолвия, что в Красногорье.',`completedtext_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Война у меня в крови.',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Джон Джей Кишан',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26647,'Пушка-старушка','Есть тут у нас одна работенка. Ты как с пушками, а? Хм... правда? А как насчет древних, рассыпающихся на глазах пиратских пушек?$B$BНа верхней палубе стоит несколько старых пушек, в которые надо заряжать по одному ядру, потом проталкивать и поджигать фитиль. Из таких пушек хорошо стрелять по бортам трехмачтовых кораблей, а не по гребным лодкам.$B$BПочему бы тебе не пойти наверх и не пальнуть разок-другой по Веселому Тимми?','Научитесь стрелять из пушки и 5 раз попадите ядром в изображение Веселого Тимми.','Вернитесь к Многоглазу на "Кровавую завесу" на мысе Тернистой долины.','Настоящий вояка.','Манекен Веселого Тимми') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пушка-старушка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Есть тут у нас одна работенка. Ты как с пушками, а? Хм... правда? А как насчет древних, рассыпающихся на глазах пиратских пушек?$B$BНа верхней палубе стоит несколько старых пушек, в которые надо заряжать по одному ядру, потом проталкивать и поджигать фитиль. Из таких пушек хорошо стрелять по бортам трехмачтовых кораблей, а не по гребным лодкам.$B$BПочему бы тебе не пойти наверх и не пальнуть разок-другой по Веселому Тимми?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Научитесь стрелять из пушки и 5 раз попадите ядром в изображение Веселого Тимми.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Многоглазу на "Кровавую завесу" на мысе Тернистой долины.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Настоящий вояка.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Манекен Веселого Тимми',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26648,'Наши смертельные враги','Эй, $gновичок:новенькая;, взгляни-ка сюда!$B$B<Дворф убирает повязку – под ней нормальный зрячий глаз.>$B$BЯ ношу повязку не потому, что у меня нет глаза, просто другой настолько остер, что тот ему только мешает.$B$BОт этого глаза ничего не скроется – даже преследующие нас разбойники в масках. Командир флота говорит, их заметили у острова Жагуаро. Как туда доберешься, стрельни из этого сигнального ружья – вместе с ними расправимся.','Убейте 15 ниндзя на острове Жагуаро.','Вернитесь к Дредерику "Мертвому глазу" Макгумму на "Кровавую завесу" у мыса Тернистой долины.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наши смертельные враги',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эй, $gновичок:новенькая;, взгляни-ка сюда!$B$B<Дворф убирает повязку – под ней нормальный зрячий глаз.>$B$BЯ ношу повязку не потому, что у меня нет глаза, просто другой настолько остер, что тот ему только мешает.$B$BОт этого глаза ничего не скроется – даже преследующие нас разбойники в масках. Командир флота говорит, их заметили у острова Жагуаро. Как туда доберешься, стрельни из этого сигнального ружья – вместе с ними расправимся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 15 ниндзя на острове Жагуаро.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дредерику "Мертвому глазу" Макгумму на "Кровавую завесу" у мыса Тернистой долины.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26649,'Черное золото','Ха-ха-ха! Смело всех подчистую! За это не грех и выпить!$B$BА ты молодец! Далеко пойдешь!','Вернитесь к Многоглазу на "Кровавую завесу" у мыса Тернистой долины.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Черное золото',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ха-ха-ха! Смело всех подчистую! За это не грех и выпить!$B$BА ты молодец! Далеко пойдешь!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Многоглазу на "Кровавую завесу" у мыса Тернистой долины.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26650,'Госпожа Удача','Знаю, ты только что $gприбыл:прибыла; на "Кровавую завесу", но мне придется отправить тебя на очередное задание. Мой третий корабль под названием "Госпожа Удача" стоит на якоре к востоку отсюда. Его шкипер, капитан Штиллец, погиб. $B$BПроклятые разбойники в масках!$B$BВ общем, Многоглаз рассказал о всех твоих подвигах на море, а мне не хватает опытных головорезов. Думаю, ты идеально подходишь на эту должность.$B$BТак что поздравляю, дружище. Теперь ты новый капитан "Госпожи Удачи"!','Отправляйтесь в капитанскую каюту "Госпожи Удачи", стоящей у мыса Тернистой долины.','На столе лежат бумаги со всеми нашими планами. Там все сказано!$B$BДетально описаны наша предстоящая атака на Пиратскую Бухту, боевой порядок, планы нападений и кое-какие сведения о группировке под названием "Крушащая Волна".') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Госпожа Удача',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Знаю, ты только что $gприбыл:прибыла; на "Кровавую завесу", но мне придется отправить тебя на очередное задание. Мой третий корабль под названием "Госпожа Удача" стоит на якоре к востоку отсюда. Его шкипер, капитан Штиллец, погиб. $B$BПроклятые разбойники в масках!$B$BВ общем, Многоглаз рассказал о всех твоих подвигах на море, а мне не хватает опытных головорезов. Думаю, ты идеально подходишь на эту должность.$B$BТак что поздравляю, дружище. Теперь ты новый капитан "Госпожи Удачи"!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в капитанскую каюту "Госпожи Удачи", стоящей у мыса Тернистой долины.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','На столе лежат бумаги со всеми нашими планами. Там все сказано!$B$BДетально описаны наша предстоящая атака на Пиратскую Бухту, боевой порядок, планы нападений и кое-какие сведения о группировке под названием "Крушащая Волна".',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26651,'Чтобы выиграть войну, нужно ею стать','<Полевой набор команды "Браво" пищит.>$B$BТеперь-то $gпонял:поняла;, $n? $GПонял:Поняла;, на что нам нужно пускаться, чтобы выиграть войну у этих чудовищ? МЫ ДОЛЖНЫ САМИ СТАТЬ ВОЙНОЙ! И НИКАКОЙ ПОЩАДЫ!!!$B$BТеперь, когда пленные на свободе, ты можешь заложить сефорий. Осторожно проберись в каждое тамошнее здание и оставь там по одному заряду.$B$BЗаложи взрывчатку в склад снаряжения и в башню Черной горы. Когда закончишь, найди меня и всех остальных из команды "Браво" в Каньоне Глинистого Ветра, это к востоку от Долины Ренда.','Воспользуйтесь полевым набором команды "Браво", чтобы заложить сефориевый заряд в башню и в склад снаряжения Черной горы.','А теперь пусть все тут взлетит на воздух.','Поговорите с Джоном Джеем Кишан в Каньоне Глинистого Ветра, что в Красногорье.','Чтобы выиграть войну, нужно ею стать.','Джон Джей Кишан') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чтобы выиграть войну, нужно ею стать',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Полевой набор команды "Браво" пищит.>$B$BТеперь-то $gпонял:поняла;, $n? $GПонял:Поняла;, на что нам нужно пускаться, чтобы выиграть войну у этих чудовищ? МЫ ДОЛЖНЫ САМИ СТАТЬ ВОЙНОЙ! И НИКАКОЙ ПОЩАДЫ!!!$B$BТеперь, когда пленные на свободе, ты можешь заложить сефорий. Осторожно проберись в каждое тамошнее здание и оставь там по одному заряду.$B$BЗаложи взрывчатку в склад снаряжения и в башню Черной горы. Когда закончишь, найди меня и всех остальных из команды "Браво" в Каньоне Глинистого Ветра, это к востоку от Долины Ренда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь полевым набором команды "Браво", чтобы заложить сефориевый заряд в башню и в склад снаряжения Черной горы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А теперь пусть все тут взлетит на воздух.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Джоном Джеем Кишан в Каньоне Глинистого Ветра, что в Красногорье.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Чтобы выиграть войну, нужно ею стать.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Джон Джей Кишан',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (26652,'Нить из призрачных волос','На старой ферме, в холмах к югу от Темнолесья, живет несчастное привидение по имени Слепая Мэри.$B$BВозьми этот призрачный гребень и попроси Слепую Мэри расчесать волосы. Потом принеси гребень обратно, и я сниму с него призрачные волосы, необходимые для нити.$B$BБудь $gосторожен:осторожна;, рядом с домом бродит множество темных тварей...','Отнесите Слепой Мэри призрачный гребень.','Что это? Гребень? Какая прелесть! И он спокойно скользит по моим волосам, хотя они давно сбились в ужасный слипшийся колтун.$B$BАх, мне бы в зеркало посмотреться...','<Всхлипывает> Пожалуйста, не смотри на меня! Я вырвала глаза собственными руками, но все равно чувствую твой взгляд!$B$BЯ уродина! Уродина! Прошу тебя, отвернись!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нить из призрачных волос',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На старой ферме, в холмах к югу от Темнолесья, живет несчастное привидение по имени Слепая Мэри.$B$BВозьми этот призрачный гребень и попроси Слепую Мэри расчесать волосы. Потом принеси гребень обратно, и я сниму с него призрачные волосы, необходимые для нити.$B$BБудь $gосторожен:осторожна;, рядом с домом бродит множество темных тварей...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите Слепой Мэри призрачный гребень.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что это? Гребень? Какая прелесть! И он спокойно скользит по моим волосам, хотя они давно сбились в ужасный слипшийся колтун.$B$BАх, мне бы в зеркало посмотреться...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Всхлипывает> Пожалуйста, не смотри на меня! Я вырвала глаза собственными руками, но все равно чувствую твой взгляд!$B$BЯ уродина! Уродина! Прошу тебя, отвернись!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26653,'Припасы из Темнолесья','Как же быть несчастному старику?.. Мне нужно привезти кое-что из Темнолесья, но деревня так далеко, а я стар и слаб... мне не осилить дорогу.$B$BНе $gмог:могла; бы ты отправиться в Темнолесье и привезти мне нить из призрачных волос? Ее можно приобрести у мадам Евы, которая живет на центральной площади города.','Поговорите с мадам Евой в Темнолесье.','А, так тебе нужна нить из призрачных волос? Боюсь, мои запасы иссякли, но я могу сделать еще... Если ты принесешь мне призрачные волосы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Припасы из Темнолесья',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как же быть несчастному старику?.. Мне нужно привезти кое-что из Темнолесья, но деревня так далеко, а я стар и слаб... мне не осилить дорогу.$B$BНе $gмог:могла; бы ты отправиться в Темнолесье и привезти мне нить из призрачных волос? Ее можно приобрести у мадам Евы, которая живет на центральной площади города.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с мадам Евой в Темнолесье.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, так тебе нужна нить из призрачных волос? Боюсь, мои запасы иссякли, но я могу сделать еще... Если ты принесешь мне призрачные волосы.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26654,'Гребень для Евы','НЕТ!!!$B$BУбери его, убери от меня этот гребень!$B$BЯ чудовище, меня больше никто не назовет прекрасной!','Верните гребень для призрачных волос мадам Еве в Темнолесье.','Ну, из этого выйдет целая катушка нити из призрачных волос, да еще и останется несколько прядей. Прими эти монеты в уплату за лишние пряди.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гребень для Евы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','НЕТ!!!$B$BУбери его, убери от меня этот гребень!$B$BЯ чудовище, меня больше никто не назовет прекрасной!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните гребень для призрачных волос мадам Еве в Темнолесье.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну, из этого выйдет целая катушка нити из призрачных волос, да еще и останется несколько прядей. Прими эти монеты в уплату за лишние пряди.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26655,'Доставка ниток','Вот твоя нить, $n. Ей можно найти тысячи способов применения – от связывания злых духов до зашивания жизни в бездушные предметы.','Принесите Аберкромби нить из призрачных волос. Его можно найти в башне в Приюте Бродяги.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Доставка ниток',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот твоя нить, $n. Ей можно найти тысячи способов применения – от связывания злых духов до зашивания жизни в бездушные предметы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Аберкромби нить из призрачных волос. Его можно найти в башне в Приюте Бродяги.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26656,'Только. Не. Останавливайся.','Отлично. Быстрота не входит в число моих достоинств.','Вернитесь к Террату Непоколебимому в Белое гнездовье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Только. Не. Останавливайся.',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично. Быстрота не входит в число моих достоинств.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Террату Непоколебимому в Белое гнездовье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26657,'Жесткое приземление','Каменные драконы признают только силу. Если мы покажем им, кто главный, они снова будут нам подчиняться.$b$bЯ отправил много самых сильных своих великанов в поля, что на западе. Они заставят драконов опуститься на землю. А ты позаботишься о том, чтобы они больше уже не взлетели.','Убейте 6 каменных драконов.','Вернитесь к Террату Непоколебимому в Белое гнездовье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жесткое приземление',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Каменные драконы признают только силу. Если мы покажем им, кто главный, они снова будут нам подчиняться.$b$bЯ отправил много самых сильных своих великанов в поля, что на западе. Они заставят драконов опуститься на землю. А ты позаботишься о том, чтобы они больше уже не взлетели.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 6 каменных драконов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Террату Непоколебимому в Белое гнездовье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26658,'Хрупкие ценности','Пришло время привлечь внимание Праматери. Для этого нам понадобится киянка, которой пользуются трогги, когда делают подношения для нее.$b$bРазыщи каменных троггов-укротителей, которые пытаются обуздать василисков в южной части Белого гнездовья. На каком-нибудь из тел найдешь киянку.','Найдите каменную киянку.','Великолепно.$B$BТеперь мы нанесем каменным драконам такой удар, что они будут вспоминать о нем следующие сто лет.','Вернитесь к Террату Непоколебимому в Белое гнездовье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хрупкие ценности',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пришло время привлечь внимание Праматери. Для этого нам понадобится киянка, которой пользуются трогги, когда делают подношения для нее.$b$bРазыщи каменных троггов-укротителей, которые пытаются обуздать василисков в южной части Белого гнездовья. На каком-нибудь из тел найдешь киянку.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите каменную киянку.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Великолепно.$B$BТеперь мы нанесем каменным драконам такой удар, что они будут вспоминать о нем следующие сто лет.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Террату Непоколебимому в Белое гнездовье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26659,'Резонирующий удар','На западном краю Белого гнездовья ты найдешь резонирующий кристалл. Ударь по нему киянкой и появится праматерь.$b$bБудь $gготов:готова; к бою. Я помогу тебе, но одолеть ее не так-то просто.','Победите Эозеру.','Впечатляет, смертный. Ты способен на большее, чем я думал.$B$BЯ расскажу об этом Матери-Скале.','Вернитесь к Террату Непоколебимому в Белое гнездовье.','Праматерь каменных драконов.','Эозера') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Резонирующий удар',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На западном краю Белого гнездовья ты найдешь резонирующий кристалл. Ударь по нему киянкой и появится праматерь.$b$bБудь $gготов:готова; к бою. Я помогу тебе, но одолеть ее не так-то просто.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Эозеру.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Впечатляет, смертный. Ты способен на большее, чем я думал.$B$BЯ расскажу об этом Матери-Скале.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Террату Непоколебимому в Белое гнездовье.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Праматерь каменных драконов.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Эозера',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26660,'Сок зомби','Мне нужна бутылка определенного напитка – сока зомби. У Смиттса, хозяина таверны "Алый ворон", он найдется.$b$bИ, пожалуйста, поторопись, $n. Ночи становятся холоднее, мне нужен этот напиток, чтобы разогреть кровь!','Поговорите с хозяином таверны Смиттсом.','Тебе нужен сок зомби, да? Хмм… это сильная штука, ее не часто спрашивают.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сок зомби',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне нужна бутылка определенного напитка – сока зомби. У Смиттса, хозяина таверны "Алый ворон", он найдется.$b$bИ, пожалуйста, поторопись, $n. Ночи становятся холоднее, мне нужен этот напиток, чтобы разогреть кровь!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с хозяином таверны Смиттсом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебе нужен сок зомби, да? Хмм… это сильная штука, ее не часто спрашивают.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26661,'Сбор цветков гнили','Если ты принесешь мне несколько цветков гнили, я приготовлю для тебя сок зомби.$B$BЦветки гнили растут в самых странных местах. Например, на телах мертвых, которых в Сумеречном лесу предостаточно!$b$bЯ недавно видел цветки гнили на Безмятежном кладбище. Поищи у могил... но опасайся нежити, которая там бродит.','Соберите 5 цветков гнили на Безмятежном кладбище.','Отлично, ты сумел добыть цветки гнили.$B$BЯ быстро приготовлю для тебя сок зомби… предупреждаю, он очень крепкий.','Вернитесь к хозяину таверны Смиттсу в Темнолесье, что в Сумеречном лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сбор цветков гнили',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если ты принесешь мне несколько цветков гнили, я приготовлю для тебя сок зомби.$B$BЦветки гнили растут в самых странных местах. Например, на телах мертвых, которых в Сумеречном лесу предостаточно!$b$bЯ недавно видел цветки гнили на Безмятежном кладбище. Поищи у могил... но опасайся нежити, которая там бродит.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 5 цветков гнили на Безмятежном кладбище.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, ты сумел добыть цветки гнили.$B$BЯ быстро приготовлю для тебя сок зомби… предупреждаю, он очень крепкий.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к хозяину таверны Смиттсу в Темнолесье, что в Сумеречном лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`objectives_loc8`,`completedtext_loc8`) VALUES (26662,'Поговорите с долговязым Джоном Медяком на "Госпоже Удаче", громилой Шоном Стукером на "Кровавой завесе" и Плаксой Мэри Смиттс на "Буруне".','Вернитесь в капитанскую каюту "Госпожи Удачи" у мыса Тернистой долины.') ON DUPLICATE KEY UPDATE `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с долговязым Джоном Медяком на "Госпоже Удаче", громилой Шоном Стукером на "Кровавой завесе" и Плаксой Мэри Смиттс на "Буруне".',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь в капитанскую каюту "Госпожи Удачи" у мыса Тернистой долины.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26663,'Саботаж','Атака на Пиратскую Бухту вот-вот начнется. Нужно немедленно туда вернуться и предупредить барона.$B$BНо пока есть возможность, стоит уничтожить некоторые припасы пиратов. Они хранятся в трюмах большинства пиратских кораблей.','Уничтожьте бочонок грога, бочонок пороха и ящик пушечных ядер.','Вернитесь в капитанскую каюту "Госпожи Удачи" у мыса Тернистой долины.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Саботаж',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Атака на Пиратскую Бухту вот-вот начнется. Нужно немедленно туда вернуться и предупредить барона.$B$BНо пока есть возможность, стоит уничтожить некоторые припасы пиратов. Они хранятся в трюмах большинства пиратских кораблей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте бочонок грога, бочонок пороха и ящик пушечных ядер.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь в капитанскую каюту "Госпожи Удачи" у мыса Тернистой долины.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26664,'Обвинение в мятеже','Перед возвращением в Пиратскую Бухту вы должны сделать все, чтобы ослабить пиратов Кровавого Паруса. Увы, даже при капитанских полномочиях вы не имеете права хладнокровно убивать других пиратов. Это разрешается только флотоводцам.$B$BОднако вы можете предать мечу мятежников... а факт мятежа очень трудно опровергнуть.$B$BКстати, эти корсары из шайки Кровавого Паруса, толкущиеся по трюмам, ведут себя уж как-то очень подозрительно...','Обвините 9 корсаров из шайки Кровавого Паруса в мятеже и убейте их.','Вернитесь в капитанскую каюту "Госпожи Удачи" у мыса Тернистой долины.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обвинение в мятеже',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Перед возвращением в Пиратскую Бухту вы должны сделать все, чтобы ослабить пиратов Кровавого Паруса. Увы, даже при капитанских полномочиях вы не имеете права хладнокровно убивать других пиратов. Это разрешается только флотоводцам.$B$BОднако вы можете предать мечу мятежников... а факт мятежа очень трудно опровергнуть.$B$BКстати, эти корсары из шайки Кровавого Паруса, толкущиеся по трюмам, ведут себя уж как-то очень подозрительно...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обвините 9 корсаров из шайки Кровавого Паруса в мятеже и убейте их.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь в капитанскую каюту "Госпожи Удачи" у мыса Тернистой долины.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26665,'Зов пиратов','Тебе известны планы Кровавого Паруса, и, похоже, тебе удалось довольно сильно им навредить. Все, что просил барон Ревилгаз, выполнено.$B$BТеперь пора передохнуть и вернуться в Пиратскую Бухту. Скоро начнется битва.','Расскажите обо всем барону Ревилгазу в Пиратской Бухте у мыса Тернистой долины.','Крушащая Волна?! Я думал, от них уже давно ничего не осталось!$B$B<Ревилгаз внимательно вас слушает.>$B$BДа, похоже, это правда. Плохая новость. Крушащая Волна – серьезный противник, а если их численность такова, какой была раньше, то нас ждет жестокая битва.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зов пиратов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе известны планы Кровавого Паруса, и, похоже, тебе удалось довольно сильно им навредить. Все, что просил барон Ревилгаз, выполнено.$B$BТеперь пора передохнуть и вернуться в Пиратскую Бухту. Скоро начнется битва.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Расскажите обо всем барону Ревилгазу в Пиратской Бухте у мыса Тернистой долины.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Крушащая Волна?! Я думал, от них уже давно ничего не осталось!$B$B<Ревилгаз внимательно вас слушает.>$B$BДа, похоже, это правда. Плохая новость. Крушащая Волна – серьезный противник, а если их численность такова, какой была раньше, то нас ждет жестокая битва.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26666,'Легенда о Сталване','Я здесь, потому что получил от моего брата Сталвана, которого я не видел долгие годы, письмо. Когда я только прибыл сюда, мне сказали, что он умер...$b$bИ никто в целом городе не может мне дать дальнейших объяснений. Одно лишь упоминание его имени вызывает у людей страх и подозрения. Как будто бы меня самого не переполняют эти чувства!$b$bНе знаю, что произойдет, если я буду натыкаться на это и дальше. Прошу тебя, помоги мне разобраться во всем этом. Упроси клерка Далтри поделиться любой информацией о моем брате.','Найдите клерка Далтри в ратуше Темнолесья.','Чем я могу помочь?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Легенда о Сталване',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я здесь, потому что получил от моего брата Сталвана, которого я не видел долгие годы, письмо. Когда я только прибыл сюда, мне сказали, что он умер...$b$bИ никто в целом городе не может мне дать дальнейших объяснений. Одно лишь упоминание его имени вызывает у людей страх и подозрения. Как будто бы меня самого не переполняют эти чувства!$b$bНе знаю, что произойдет, если я буду натыкаться на это и дальше. Прошу тебя, помоги мне разобраться во всем этом. Упроси клерка Далтри поделиться любой информацией о моем брате.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите клерка Далтри в ратуше Темнолесья.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Чем я могу помочь?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26667,'Украденные письма','Ты хочешь знать о Сталване...$b$bЗнаешь, не ты $gпервый:первая;. О нем спрашивают довольно часто. И всегда кто-то нездешний. Местные-то жители обычно в курсе.$b$bНо тебе в любом случае не повезло. Я лишился половины архива. Несколько дней назад дикие воргены ворвались в городскую ратушу и разгромили там все в пух и прах.$b$bИнтересующие тебя документы скорее всего разбросаны по Светлой роще, далеко в лесах к западу отсюда. Если тебе интересно мое мнение, оно того не стоит.','Соберите пачку изрезанных писем в Светлой роще.','Послушай, приятель, мне не нужны проблемы...','Вернитесь к клерку Далтри в Темнолесье, что в Сумеречном лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Украденные письма',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты хочешь знать о Сталване...$b$bЗнаешь, не ты $gпервый:первая;. О нем спрашивают довольно часто. И всегда кто-то нездешний. Местные-то жители обычно в курсе.$b$bНо тебе в любом случае не повезло. Я лишился половины архива. Несколько дней назад дикие воргены ворвались в городскую ратушу и разгромили там все в пух и прах.$b$bИнтересующие тебя документы скорее всего разбросаны по Светлой роще, далеко в лесах к западу отсюда. Если тебе интересно мое мнение, оно того не стоит.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите пачку изрезанных писем в Светлой роще.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Послушай, приятель, мне не нужны проблемы...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к клерку Далтри в Темнолесье, что в Сумеречном лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (26668,'Мгновенный взрыв','Взрывчатка, которую ты $gзаложил:заложила;, была очень ядреная, $n. Теперь, если нажать кнопку на полевом наборе команды "Браво", вся эта долина превратится в огромный огненный шар смерти.$B$BЗнаешь что, $n... Думаю, эту честь надо предоставить тебе. В конце концов, это ведь ты $gсделал:сделала; всю тяжелую работу.$B$B$GГотов:Готова;?','Взорвите долину Ренда.','Взорвите Долину Ренда.','Поговорите с Джоном Джеем Кишан в Лагере Безмолвия, что в Красногорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мгновенный взрыв',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Взрывчатка, которую ты $gзаложил:заложила;, была очень ядреная, $n. Теперь, если нажать кнопку на полевом наборе команды "Браво", вся эта долина превратится в огромный огненный шар смерти.$B$BЗнаешь что, $n... Думаю, эту честь надо предоставить тебе. В конце концов, это ведь ты $gсделал:сделала; всю тяжелую работу.$B$B$GГотов:Готова;?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Взорвите долину Ренда.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Взорвите Долину Ренда.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Джоном Джеем Кишан в Лагере Безмолвия, что в Красногорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26669,'В темном углу','Если ты $gнастроен:настроена; решительно, я помогу тебе, $n. Мне известно, где должны быть остальные документы. Я просто слишком боюсь что-либо предпринимать.$b$bЕсть всего несколько мест, где собираются эти ужасные твари из стаи Ночной Погибели тогда, когда не рыщут по лесу. Одно из них – Гниющий сад, что к югу отсюда. Тамошние здания они используют в качестве своих логовищ, так что, если они еще не сожрали остальные документы, ты $gдолжен:должна; найти их там... но бьюсь об заклад, тебе придется попотеть.','Обыщите Гниющий сад и найдите вырванную страницу дневника.','Я смотрю, ты вернулся целым и невредимым.','Вернитесь к клерку Далтри в Темнолесье, что в Сумеречном лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В темном углу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если ты $gнастроен:настроена; решительно, я помогу тебе, $n. Мне известно, где должны быть остальные документы. Я просто слишком боюсь что-либо предпринимать.$b$bЕсть всего несколько мест, где собираются эти ужасные твари из стаи Ночной Погибели тогда, когда не рыщут по лесу. Одно из них – Гниющий сад, что к югу отсюда. Тамошние здания они используют в качестве своих логовищ, так что, если они еще не сожрали остальные документы, ты $gдолжен:должна; найти их там... но бьюсь об заклад, тебе придется попотеть.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обыщите Гниющий сад и найдите вырванную страницу дневника.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я смотрю, ты вернулся целым и невредимым.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к клерку Далтри в Темнолесье, что в Сумеречном лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26670,'Погибель Роланда','Это еще не все...$b$bНо вряд ли имеет смысл еще что-то предпринимать, $n. Единственное оставшееся место, в котором еще можно поискать, это Погибель Роланда. Это рудник к югу от города, там самое большое логово воргенов в Сумеречном лесу. Никому в Темнолесье еще не удавалось выбраться оттуда живым. На самом деле, некоторые из имеющихся записей указывают на то, что как раз оттуда и приходят монстры... кто знает, какое зло таится в этом руднике?$b$bПожалуйста, $n, оставь это. Давай лучше забудем обо всем и никогда больше не будем поднимать эту тему.','Обыщите Погибель Роланда и найдите оставшиеся страницы дневника Сталвана.','Вернитесь к клерку Далтри в Темнолесье, что в Сумеречном лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Погибель Роланда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это еще не все...$b$bНо вряд ли имеет смысл еще что-то предпринимать, $n. Единственное оставшееся место, в котором еще можно поискать, это Погибель Роланда. Это рудник к югу от города, там самое большое логово воргенов в Сумеречном лесу. Никому в Темнолесье еще не удавалось выбраться оттуда живым. На самом деле, некоторые из имеющихся записей указывают на то, что как раз оттуда и приходят монстры... кто знает, какое зло таится в этом руднике?$b$bПожалуйста, $n, оставь это. Давай лучше забудем обо всем и никогда больше не будем поднимать эту тему.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обыщите Погибель Роланда и найдите оставшиеся страницы дневника Сталвана.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к клерку Далтри в Темнолесье, что в Сумеречном лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (26671,'Судьба Сталвана Мистмантла','Ты $gнашел:нашла; все. Все, кроме последней страницы...$b$b...которая находится у меня. Не смотри на меня так. Ты поймешь, когда прочтешь. Знаешь, некоторые даже считают, что на ней проклятье. На самом деле, я испытал облегчение, когда воргены ворвались сюда и захватили дневник!$b$bБери. Бери целиком. Я благодарен тебе за восстановление моего архива, но я не хочу больше иметь с этим ничего общего. Пожалуйста, просто оставь меня.','Отнесите легенду о Сталване Тобиасу Мистмантлу.','Не знаю, как и благодарить тебя… Я надеялся на радостное воссоединение, но чем больше я узнаю, тем меньше я рад, что стал спрашивать.$B$BНо мне нужно было знать.','Ты вернулся! Удалось найти что-нибудь, связанное с моим братом?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Судьба Сталвана Мистмантла',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gнашел:нашла; все. Все, кроме последней страницы...$b$b...которая находится у меня. Не смотри на меня так. Ты поймешь, когда прочтешь. Знаешь, некоторые даже считают, что на ней проклятье. На самом деле, я испытал облегчение, когда воргены ворвались сюда и захватили дневник!$b$bБери. Бери целиком. Я благодарен тебе за восстановление моего архива, но я не хочу больше иметь с этим ничего общего. Пожалуйста, просто оставь меня.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите легенду о Сталване Тобиасу Мистмантлу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Не знаю, как и благодарить тебя… Я надеялся на радостное воссоединение, но чем больше я узнаю, тем меньше я рад, что стал спрашивать.$B$BНо мне нужно было знать.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты вернулся! Удалось найти что-нибудь, связанное с моим братом?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26672,'Узнать правду','Этого не может быть. Мой брат был упрям, но такая подлость... такая слабость и кровавая жестокость, такое зло...$b$b<Тобиас подносит руку к лицу, отводя взгляд.>$b$bЯ хочу знать правду. Мне нужно знать, как я получил это письмо. Я хочу знать, действительно ли Сталван это сделал.$b$bМне нужно понять, почему...$b$bВозьми мое кольцо, $n. Отнеси его мадам Еве. Эта женщина приверженна древним искусствам и не скрывает этого... называй это безумием, но я должен испробовать все.','Отнесите фамильное кольцо Мистмантла мадам Еве.','Как интересно. Давненько я не видела такого кольца…') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Узнать правду',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этого не может быть. Мой брат был упрям, но такая подлость... такая слабость и кровавая жестокость, такое зло...$b$b<Тобиас подносит руку к лицу, отводя взгляд.>$b$bЯ хочу знать правду. Мне нужно знать, как я получил это письмо. Я хочу знать, действительно ли Сталван это сделал.$b$bМне нужно понять, почему...$b$bВозьми мое кольцо, $n. Отнеси его мадам Еве. Эта женщина приверженна древним искусствам и не скрывает этого... называй это безумием, но я должен испробовать все.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите фамильное кольцо Мистмантла мадам Еве.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Как интересно. Давненько я не видела такого кольца…',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26673,'REUSE - BREADCRUMB','Этого не может быть. Мой брат был упрям, но такая подлость... такая слабость и кровавая жестокость, такое зло...$b$b<Тобиас подносит руку к лицу, отводя взгляд.>$b$bЯ хочу знать правду. Мне нужно знать, как я получил это письмо. Я хочу знать, действительно ли Сталван это сделал.$b$bМне нужно понять, почему...$b$bВозьми мое кольцо, $n. Отнеси его мадам Еве. Эта женщина приверженна древним искусствам и не скрывает этого... называй это безумием, но я должен испробовать все.','Отнесите фамильное кольцо Мистмантла мадам Еве.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','REUSE - BREADCRUMB',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этого не может быть. Мой брат был упрям, но такая подлость... такая слабость и кровавая жестокость, такое зло...$b$b<Тобиас подносит руку к лицу, отводя взгляд.>$b$bЯ хочу знать правду. Мне нужно знать, как я получил это письмо. Я хочу знать, действительно ли Сталван это сделал.$b$bМне нужно понять, почему...$b$bВозьми мое кольцо, $n. Отнеси его мадам Еве. Эта женщина приверженна древним искусствам и не скрывает этого... называй это безумием, но я должен испробовать все.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите фамильное кольцо Мистмантла мадам Еве.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26674,'Месть Мистмантла','Вероятно, мастер Харрис прав. Лучше было не тревожить прошлое.$B$BТеперь у меня новая жизнь. А будет это жизнь монстра или человека – зависит только от меня.$B$BЧто касается тебя, я преисполнен благодарности за твою помощь, вне зависимости от результата. Пожалуйста, прими это.','Вернитесь к Тобиасу Мистмантлу в Темнолесье, что в Сумеречном лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Месть Мистмантла',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вероятно, мастер Харрис прав. Лучше было не тревожить прошлое.$B$BТеперь у меня новая жизнь. А будет это жизнь монстра или человека – зависит только от меня.$B$BЧто касается тебя, я преисполнен благодарности за твою помощь, вне зависимости от результата. Пожалуйста, прими это.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тобиасу Мистмантлу в Темнолесье, что в Сумеречном лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (26675,'Цена доверия','Беды этого мира, похоже, никогда не закончатся. Они меняются, но не исчезают.$B$BВетер донес слухи о предателе в наших рядах. Мы послали на расследование лучшую из часовых, но она погибла. Зря я надеялся, что предатель останется в неведении... Я был опрометчив, а она пала жертвой моей глупости.$B$BМне нужен тот, кто выйдет на след изменника. И кого не знают в городе. Это опасное дело, но... ты поможешь?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Цена доверия',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Беды этого мира, похоже, никогда не закончатся. Они меняются, но не исчезают.$B$BВетер донес слухи о предателе в наших рядах. Мы послали на расследование лучшую из часовых, но она погибла. Зря я надеялся, что предатель останется в неведении... Я был опрометчив, а она пала жертвой моей глупости.$B$BМне нужен тот, кто выйдет на след изменника. И кого не знают в городе. Это опасное дело, но... ты поможешь?',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26676,'Доставка сока','А вот твой сок зомби...$B$BБудь с ним $gосторожен:осторожна;. Он такой крепкий, что мертвого поднимет!','Отнесите сок зомби в хижину Аберкромби, что в Приюте Бродяги.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Доставка сока',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А вот твой сок зомби...$B$BБудь с ним $gосторожен:осторожна;. Он такой крепкий, что мертвого поднимет!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите сок зомби в хижину Аберкромби, что в Приюте Бродяги.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26677,'Чучело вурдалака','Здесь, на окраинах города можно считать чудом, если тебя не съедят ходячие мертвецы! Не далее, как вчера, группа вурдалаков билась в стены моей башни!$b$bЯ хочу сделать чучело, что-то вроде "пугала" для вурдалаков. Для этого мне нужно несколько ребер вурдалака. Севернее Темнолесья, у поместья Мистмантла бродят зловонные трупы, ребер у них полно...$b$bПринеси мне эти ребра, а я тебе за них заплачу.','Достаньте 7 ребер вурдалаков у зловонных трупов в поместье Мистмантла.','О, спасибо. Они отлично подойдут!','На Вороньем Холме тоже полным-полно ребер, но я не уверен, что тебе захочется идти туда ночью...','Вернитесь к Аберкромби в Приют Бродяги, что в Сумеречном лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чучело вурдалака',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Здесь, на окраинах города можно считать чудом, если тебя не съедят ходячие мертвецы! Не далее, как вчера, группа вурдалаков билась в стены моей башни!$b$bЯ хочу сделать чучело, что-то вроде "пугала" для вурдалаков. Для этого мне нужно несколько ребер вурдалака. Севернее Темнолесья, у поместья Мистмантла бродят зловонные трупы, ребер у них полно...$b$bПринеси мне эти ребра, а я тебе за них заплачу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Достаньте 7 ребер вурдалаков у зловонных трупов в поместье Мистмантла.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, спасибо. Они отлично подойдут!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','На Вороньем Холме тоже полным-полно ребер, но я не уверен, что тебе захочется идти туда ночью...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аберкромби в Приют Бродяги, что в Сумеречном лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26678,'Крепленый ром','Разыщите бочонок крепленого рома барона Ревилгаза в Пиратской Бухте.','Да, это он, крепленый ром. Налей-ка стаканчик Ревилгазу. И сам угощайся...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Крепленый ром',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите бочонок крепленого рома барона Ревилгаза в Пиратской Бухте.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, это он, крепленый ром. Налей-ка стаканчик Ревилгазу. И сам угощайся...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26679,'Возвращение к Ревилгазу','Снаружи что-то происходит. Неужели пираты Кровавого Паруса уже здесь?$B$BСрочно отнеси Ревилгазу крепленый ром. Не медли!','Доставьте крепленый ром барону Ревилгазу в Пиратскую Бухту.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение к Ревилгазу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Снаружи что-то происходит. Неужели пираты Кровавого Паруса уже здесь?$B$BСрочно отнеси Ревилгазу крепленый ром. Не медли!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте крепленый ром барону Ревилгазу в Пиратскую Бухту.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26680,'Нападение огров','Несколько недель назад я собирал травы вдали от дома, и на меня напал отряд огров! Я сбежал, бросив свой ящик с ценными инструментами и травами.$B$BПрогнав меня, они вернулись к своему кургану в южной части Сумеречного леса. Думаю, они оставили мой ящик неподалеку от кургана.$B$BПрошу тебя, $n, верни мне ящик, без него я как без рук.','Верните ящик Аберкромби владельцу.','Вернитесь к Аберкромби в Приют Бродяги, что в Сумеречном лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нападение огров',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Несколько недель назад я собирал травы вдали от дома, и на меня напал отряд огров! Я сбежал, бросив свой ящик с ценными инструментами и травами.$B$BПрогнав меня, они вернулись к своему кургану в южной части Сумеречного леса. Думаю, они оставили мой ящик неподалеку от кургана.$B$BПрошу тебя, $n, верни мне ящик, без него я как без рук.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните ящик Аберкромби владельцу.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аберкромби в Приют Бродяги, что в Сумеречном лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (26681,'Письмо для мэра','Отнеси это письмо Элло Чернодреву, мэру Темнолесья.$b$bМы с ним старые друзья... и когда он прочтет и узнает, что ты для меня $gсделал:сделала;... уверен, он будет так же счастлив, как и я! Ха-ха-ха!','Отнесите письмо Аберкромби мэру Темнолесья, Элло Чернодреву.','<Элло пробегает глазами письмо и мгновенно бледнеет.>$B$BГлупец! Ты погубил всех нас!','Письмо? Какое письмо?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Письмо для мэра',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Отнеси это письмо Элло Чернодреву, мэру Темнолесья.$b$bМы с ним старые друзья... и когда он прочтет и узнает, что ты для меня $gсделал:сделала;... уверен, он будет так же счастлив, как и я! Ха-ха-ха!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите письмо Аберкромби мэру Темнолесья, Элло Чернодреву.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Элло пробегает глазами письмо и мгновенно бледнеет.>$B$BГлупец! Ты погубил всех нас!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Письмо? Какое письмо?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26682,'Неуклюжая угроза','Пылевые топи – это земля Орды, $n. Люди пусть ютятся на своем островке и на песчаной отмели, а топь принадлежит нам.$B$BСо временем мы вытесним отсюда всех людишек, а пока нужно разобраться тут со своими делами. На севере из недр земли вылезают болотные твари и нападают на всех, кто к ним приблизится. Нельзя допустить, чтобы наша собственная земля восставала против нас!$B$BЕсли хочешь послужить Орде – уничтожь болотных тварей. А мы тебя наградим.','Уничтожьте 7 сухолистых ползунов или сухолистых яростеней в топи к северу от деревни Гиблотопь.','Вернитесь к Крогу в деревню Гиблотопь в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Неуклюжая угроза',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пылевые топи – это земля Орды, $n. Люди пусть ютятся на своем островке и на песчаной отмели, а топь принадлежит нам.$B$BСо временем мы вытесним отсюда всех людишек, а пока нужно разобраться тут со своими делами. На севере из недр земли вылезают болотные твари и нападают на всех, кто к ним приблизится. Нельзя допустить, чтобы наша собственная земля восставала против нас!$B$BЕсли хочешь послужить Орде – уничтожь болотных тварей. А мы тебя наградим.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 7 сухолистых ползунов или сухолистых яростеней в топи к северу от деревни Гиблотопь.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Крогу в деревню Гиблотопь в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26683,'Взгляни на звезды','Один мой друг, гном по имени Зубец, обещал мне помочь создать устройство, которое позволит изучать звезды. Согласно его чертежам первое, что нужно сделать, это найти способ отражать свет.$b$bЯ припоминаю, что слышал о женщине, о которой все говорят, что она всегда носит с собой зеркало. Может быть, ты разыщешь Мэри и узнаешь, не одолжит ли она нам эту отражающую поверхность для использования в данном проекте? Кажется, раньше она жила в южной части Сумеречного леса...','Найдите Мэри и уговорите ее пожертвовать зеркало для проекта Виктора.','Все верно, когда-то у меня было зеркальце.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Взгляни на звезды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Один мой друг, гном по имени Зубец, обещал мне помочь создать устройство, которое позволит изучать звезды. Согласно его чертежам первое, что нужно сделать, это найти способ отражать свет.$b$bЯ припоминаю, что слышал о женщине, о которой все говорят, что она всегда носит с собой зеркало. Может быть, ты разыщешь Мэри и узнаешь, не одолжит ли она нам эту отражающую поверхность для использования в данном проекте? Кажется, раньше она жила в южной части Сумеречного леса...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Мэри и уговорите ее пожертвовать зеркало для проекта Виктора.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Все верно, когда-то у меня было зеркальце.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26684,'Невменяемый вурдалак','Зеркальце было одним из моих главных сокровищ... но потом со мной случилось несчастье. После этого я зашвырнула его за амбар. Одно время там бродил невменяемый вурдалак. Наверное, он подобрал его. Говорят, что теперь эта тварь живет на Безмятежном кладбище.','Заберите зеркало Слепой Мэри у невменяемого вурдалака.','Прекрасно! Это идеально подойдет. Я глубоко признателен!','Я показал Зубцу наш прибор для изучения звезд. Он был впечатлен. Ты не добыл отражающее устройство?','Вернитесь к Виктору Призм’Антрасу в Темнолесье, что в Сумеречном лесу.','У него зеркало. И он невменяемый.','Невменяемый вурдалак') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Невменяемый вурдалак',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Зеркальце было одним из моих главных сокровищ... но потом со мной случилось несчастье. После этого я зашвырнула его за амбар. Одно время там бродил невменяемый вурдалак. Наверное, он подобрал его. Говорят, что теперь эта тварь живет на Безмятежном кладбище.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заберите зеркало Слепой Мэри у невменяемого вурдалака.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно! Это идеально подойдет. Я глубоко признателен!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я показал Зубцу наш прибор для изучения звезд. Он был впечатлен. Ты не добыл отражающее устройство?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Виктору Призм’Антрасу в Темнолесье, что в Сумеречном лесу.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','У него зеркало. И он невменяемый.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Невменяемый вурдалак',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26685,'Отличное стекло','Для завершения работы не хватает только одного предмета. Согласно чертежам Зубца, нам нужна линза с определенными характеристиками. Мне известно только об одной подходящей линзе достаточно большого размера, но достать ее будет не так легко.$B$BВ кургане на юге Сумеречного леса живет огр по имени Ззарк\'Вул. Если сможешь, принеси мне его монокль, и я использую его вместо линзы!','Убейте огра Ззарк\'Вула, живущего в самом южном кургане Сумеречного леса и возьмите его монокль.','Вернитесь к Виктору Призм’Антрасу в Темнолесье, что в Сумеречном лесу.','Чемпион из клана Каменного кулака.','Ззарк\'Вул') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отличное стекло',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Для завершения работы не хватает только одного предмета. Согласно чертежам Зубца, нам нужна линза с определенными характеристиками. Мне известно только об одной подходящей линзе достаточно большого размера, но достать ее будет не так легко.$B$BВ кургане на юге Сумеречного леса живет огр по имени Ззарк\'Вул. Если сможешь, принеси мне его монокль, и я использую его вместо линзы!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте огра Ззарк\'Вула, живущего в самом южном кургане Сумеречного леса и возьмите его монокль.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Виктору Призм’Антрасу в Темнолесье, что в Сумеречном лесу.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Чемпион из клана Каменного кулака.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Ззарк\'Вул',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26686,'Ходячие кости','Убейте 5 воинов-скелетов и 5 магов-скелетов по просьбе командира Алтеи Чернодрев.','Вернитесь к командиру Алтее Чернодрев в Темнолесье, что в Сумеречном лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ходячие кости',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 5 воинов-скелетов и 5 магов-скелетов по просьбе командира Алтеи Чернодрев.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру Алтее Чернодрев в Темнолесье, что в Сумеречном лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26687,'Подкрепления из Терамора','Отправляйтесь на остров Терамор в Пылевые топи и поговорите с капитаном Гарраном Ваймсом.','Отправляйтесь в Пылевые топи на Остров Терамор и поговорите с капитаном Гарраном Ваймсом в главных казармах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подкрепления из Терамора',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь на остров Терамор в Пылевые топи и поговорите с капитаном Гарраном Ваймсом.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отправляйтесь в Пылевые топи на Остров Терамор и поговорите с капитаном Гарраном Ваймсом в главных казармах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26688,'Воргены в лесу','На Сумеречный лес неотвратимо надвигаются силы тьмы, и цель мастера Карвина – борьба с этим злом. Благодаря нашим усилиям народ Темнолесья живет в безопасности.$b$bТы считаешь, что $gдостоин:достойна; вступить в наши ряды?$b$bКогда-то я был таким же, как ты. Меня раздражало самодовольство Дозора, и я стал соратником мастера Карвина. Если ты хочешь показать, на что $gспособен:способна;, то не трать время на слова.$b$bВыступи против воргенов из стаи Ночной Погибели в Светлой роще. Посмотрим, есть ли у тебя силы, чтобы одолеть этих монстров.','Убейте 7 воргенов из стаи Ночной Погибели в Светлой роще.','Вернитесь к Калору в Темнолесье, что в Сумеречном лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Воргены в лесу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На Сумеречный лес неотвратимо надвигаются силы тьмы, и цель мастера Карвина – борьба с этим злом. Благодаря нашим усилиям народ Темнолесья живет в безопасности.$b$bТы считаешь, что $gдостоин:достойна; вступить в наши ряды?$b$bКогда-то я был таким же, как ты. Меня раздражало самодовольство Дозора, и я стал соратником мастера Карвина. Если ты хочешь показать, на что $gспособен:способна;, то не трать время на слова.$b$bВыступи против воргенов из стаи Ночной Погибели в Светлой роще. Посмотрим, есть ли у тебя силы, чтобы одолеть этих монстров.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 7 воргенов из стаи Ночной Погибели в Светлой роще.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Калору в Темнолесье, что в Сумеречном лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (26689,'Гниющий сад','Территория, охваченная нашествием воргенов, простирается уже за Светлую рощу. На юге, на самой границе Темнолесья есть Гниющий сад, в котором обитают даже более свирепые твари.$b$bТамошние воргены так же злы и жестоки, $n, но куда более хитры. Они уничтожают врага на расстоянии при помощи сотканных теней. Отправляйся в Гниющий сад и убей тенеткачей, чтобы обезопасить город!','Вернитесь к Калору в Темнолесье, что в Сумеречном лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гниющий сад',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Территория, охваченная нашествием воргенов, простирается уже за Светлую рощу. На юге, на самой границе Темнолесья есть Гниющий сад, в котором обитают даже более свирепые твари.$b$bТамошние воргены так же злы и жестоки, $n, но куда более хитры. Они уничтожают врага на расстоянии при помощи сотканных теней. Отправляйся в Гниющий сад и убей тенеткачей, чтобы обезопасить город!',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Калору в Темнолесье, что в Сумеречном лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26690,'Ярые и Нечистые','Твои предыдущие свершения убедили меня в том, что ты $gготов:готова; сразиться с самыми сильными воргенами в этих лесах.$b$bИз всех воргенов, которые поселились в этих местах, Ярые Клыки и Нечистые Воргены – самые опасные. Они селятся возле некоторых пещер и в руднике, что к югу отсюда.$b$bТы издалека увидишь огни их костров...','Убейте 8 Ярых Клыков и 8 Нечистых Воргенов из стаи Ночной Погибели в Погибели Роланда.','Вернитесь к Калору в Темнолесье, что в Сумеречном лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ярые и Нечистые',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Твои предыдущие свершения убедили меня в том, что ты $gготов:готова; сразиться с самыми сильными воргенами в этих лесах.$b$bИз всех воргенов, которые поселились в этих местах, Ярые Клыки и Нечистые Воргены – самые опасные. Они селятся возле некоторых пещер и в руднике, что к югу отсюда.$b$bТы издалека увидишь огни их костров...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 Ярых Клыков и 8 Нечистых Воргенов из стаи Ночной Погибели в Погибели Роланда.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Калору в Темнолесье, что в Сумеречном лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (26691,'Воргены в лесу','Отнесите письмо Калора Джонатану Карвину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Воргены в лесу',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите письмо Калора Джонатану Карвину.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (26692,'Истребление Темношкуров','От орков, что находились к югу от озера Безмолвия, остался лишь пепел да зола. Самое время обратить внимание на армию гноллов из стаи Темношкуров, которая обосновалась в долине Галарделл, прямо к северу отсюда.$B$BСтупай туда и убей их всех, $n! Начинаем операцию "Истребление". За команду "Браво" и за Альянс!','Убейте 20 любых гноллов из стаи Темношкуров.','Вернитесь к Данфорту в Каньон Глинистого Ветра, что в Красногорье.','Уничтожь их всех.','Данфорт') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Истребление Темношкуров',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','От орков, что находились к югу от озера Безмолвия, остался лишь пепел да зола. Самое время обратить внимание на армию гноллов из стаи Темношкуров, которая обосновалась в долине Галарделл, прямо к северу отсюда.$B$BСтупай туда и убей их всех, $n! Начинаем операцию "Истребление". За команду "Браво" и за Альянс!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 20 любых гноллов из стаи Темношкуров.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Данфорту в Каньон Глинистого Ветра, что в Красногорье.',`completedtext_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Уничтожь их всех.',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Данфорт',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (26693,'Темная башня','Жители этой долины сообщили нам кое-какую чрезвычайно важную информацию. Вот эти двое из семьи Рантал сказали, что гноллами в долине Галарделл командует талантливый волшебник, живущий в башне Илгалара. Но проблема в том, что башня защищена магическим силовым полем.$B$BДля начала нам придется найти ключ, чтобы отпереть башню, а для этого надо обратиться к генералу гноллов по имени Фангор. Просто убей этого Фангора и забери у него ключ.$B$BЯ буду держать с тобой связь.','Раздобудьте ключ от башни Илгалара.','Поговорите с Джоном Джеем Кишан в Каньоне Глинистого Ветра, что в Красногорье.','Фангор был идиотом.','Джон Джей Кишан') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Темная башня',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Жители этой долины сообщили нам кое-какую чрезвычайно важную информацию. Вот эти двое из семьи Рантал сказали, что гноллами в долине Галарделл командует талантливый волшебник, живущий в башне Илгалара. Но проблема в том, что башня защищена магическим силовым полем.$B$BДля начала нам придется найти ключ, чтобы отпереть башню, а для этого надо обратиться к генералу гноллов по имени Фангор. Просто убей этого Фангора и забери у него ключ.$B$BЯ буду держать с тобой связь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте ключ от башни Илгалара.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Джоном Джеем Кишан в Каньоне Глинистого Ветра, что в Красногорье.',`completedtext_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Фангор был идиотом.',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Джон Джей Кишан',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26694,'Великий волхв Доан','<Полевой набор команды "Браво" вибрирует.>$B$BОчень хорошо. Сейчас я скажу тебе кое-что очень важное. Волшебник из этой башни – человек, звать его Доан. Этот гнусный предатель работает на орков Черной горы, поэтому надо его прихлопнуть.$B$BОтопри дверь ключом Илгалара и пробирайся в башню; потом заберись на самый верх и покажи этому Доану, как команда "Браво" поступает с предателями.$B$BКогда закончишь, встретимся в Каньоне Глинистого Ветра.$B$BКишан, отбой.','Убейте великого волхва Доана.','Телепортировался? Сказал про Темное Пламя? Да что ж это творится-то…$B$BДумаю, пора мне самому взяться за дело и прекратить это, наконец уже.','Поговорите с Джоном Джеем Кишан в Каньоне Глинистого Ветра, что в Красногорье.','Волхв будет плакать, как маленькая девчонка – а он и есть девчонка. Только не говори Месснеру, что я о нем такого мнения.','Джон Джей Кишан') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Великий волхв Доан',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Полевой набор команды "Браво" вибрирует.>$B$BОчень хорошо. Сейчас я скажу тебе кое-что очень важное. Волшебник из этой башни – человек, звать его Доан. Этот гнусный предатель работает на орков Черной горы, поэтому надо его прихлопнуть.$B$BОтопри дверь ключом Илгалара и пробирайся в башню; потом заберись на самый верх и покажи этому Доану, как команда "Браво" поступает с предателями.$B$BКогда закончишь, встретимся в Каньоне Глинистого Ветра.$B$BКишан, отбой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте великого волхва Доана.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Телепортировался? Сказал про Темное Пламя? Да что ж это творится-то…$B$BДумаю, пора мне самому взяться за дело и прекратить это, наконец уже.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Джоном Джеем Кишан в Каньоне Глинистого Ветра, что в Красногорье.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Волхв будет плакать, как маленькая девчонка – а он и есть девчонка. Только не говори Месснеру, что я о нем такого мнения.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Джон Джей Кишан',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26695,'Приготовиться к взлету!','У меня идея, но для ее реализации тебе придется немного побегать. Как любой гоблинский картель, Пираты Черноводья располагают кучей взрывчатки. На самом деле я точно знаю, что у нашего старого приятеля Наркка есть контейнер в задней части магазина – это который в здании портовой инспекции.$B$BИди возьми эту взрывчатку и принеси сюда, если она еще не взорвалась.','Добудьте ручные гранаты Наркка в здании портовой инспекции в Пиратской Бухте.','Вернитесь к барону Ревилгазу в Пиратскую Бухту на мысе Тернистой долины.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приготовиться к взлету!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У меня идея, но для ее реализации тебе придется немного побегать. Как любой гоблинский картель, Пираты Черноводья располагают кучей взрывчатки. На самом деле я точно знаю, что у нашего старого приятеля Наркка есть контейнер в задней части магазина – это который в здании портовой инспекции.$B$BИди возьми эту взрывчатку и принеси сюда, если она еще не взорвалась.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте ручные гранаты Наркка в здании портовой инспекции в Пиратской Бухте.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к барону Ревилгазу в Пиратскую Бухту на мысе Тернистой долины.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26696,'Зов Калимдора','Отправляйтесь на корабле из Пиратской Бухты в Кабестан, где вам следует поговорить с Газлоу.','Чем могу помочь?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зов Калимдора',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь на корабле из Пиратской Бухты в Кабестан, где вам следует поговорить с Газлоу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Чем могу помочь?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26697,'Последнее путешествие Крушащей Волны','Нам ни за что не выдержать атаку, если все воргены-пираты так и будут нападать на бухту с севера. К счастью, у них вроде бы нет пушек, поэтому если мы сумеем как-то вытащить тебя из порта, ты сможешь атаковать их с воздуха.$B$BКебок, ордынский распорядитель полетов, стоит прямо за углом. Поговори с ним и скажи, что тебе нужен самый смелый ветрокрыл.$B$BДа гранат с собой возьми, сколько унесешь: они понадобятся, чтобы бомбить вон те лодки!','Надеюсь, эти недоумки умеют плавать по-собачьи!$B$BХотя, конечно, это я сейчас чушь сморозил.','Вернитесь к барону Ревилгазу в Пиратскую Бухту на мысе Тернистой долины.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Последнее путешествие Крушащей Волны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нам ни за что не выдержать атаку, если все воргены-пираты так и будут нападать на бухту с севера. К счастью, у них вроде бы нет пушек, поэтому если мы сумеем как-то вытащить тебя из порта, ты сможешь атаковать их с воздуха.$B$BКебок, ордынский распорядитель полетов, стоит прямо за углом. Поговори с ним и скажи, что тебе нужен самый смелый ветрокрыл.$B$BДа гранат с собой возьми, сколько унесешь: они понадобятся, чтобы бомбить вон те лодки!',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Надеюсь, эти недоумки умеют плавать по-собачьи!$B$BХотя, конечно, это я сейчас чушь сморозил.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к барону Ревилгазу в Пиратскую Бухту на мысе Тернистой долины.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26698,'В поисках Морского Рога','Поговорите с командиром флота Морским Рогом в Пиратской Бухте.','Надо было догадаться, что эти подонки из Крушащей Волны живы и замышляют недоброе. Я бы еще несколько лет назад всех их перерезал!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В поисках Морского Рога',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с командиром флота Морским Рогом в Пиратской Бухте.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Надо было догадаться, что эти подонки из Крушащей Волны живы и замышляют недоброе. Я бы еще несколько лет назад всех их перерезал!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (26699,'Борьба с Крушащей Волной','Эта Крушащая Волна повсюду! Боюсь, костоломы барона не справятся с такой многочисленной армией.$B$BНо раз уж ты здесь, помоги мне уничтожить хотя бы нескольких.$B$BНо не возвращайся, когда закончишь, мне будет не до тебя.','Вернитесь к барону Ревилгазу в Пиратскую Бухту на мысе Тернистой долины.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Борьба с Крушащей Волной',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эта Крушащая Волна повсюду! Боюсь, костоломы барона не справятся с такой многочисленной армией.$B$BНо раз уж ты здесь, помоги мне уничтожить хотя бы нескольких.$B$BНо не возвращайся, когда закончишь, мне будет не до тебя.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к барону Ревилгазу в Пиратскую Бухту на мысе Тернистой долины.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26700,'Госпожа не-Удача','Слыхал, корабль этот называется "Госпожа Удача". А ты случайно не был его капитаном? Если так, тебе должно быть там все хорошо знакомо.$B$BНаша главная головная боль – это Крушащая Волна, но мы все же не жаждем вызывать на себя огонь их пушек. Так что хватайся за канат, и давай разберемся с этими грозными пиратами. Как закончишь, расскажи обо всем барону.','Убейте 8 корсаров из шайки Кровавого Паруса в Пиратской Бухте.','Вернитесь к барону Ревилгазу в Пиратскую Бухту на мысе Тернистой долины.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Госпожа не-Удача',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слыхал, корабль этот называется "Госпожа Удача". А ты случайно не был его капитаном? Если так, тебе должно быть там все хорошо знакомо.$B$BНаша главная головная боль – это Крушащая Волна, но мы все же не жаждем вызывать на себя огонь их пушек. Так что хватайся за канат, и давай разберемся с этими грозными пиратами. Как закончишь, расскажи обо всем барону.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 корсаров из шайки Кровавого Паруса в Пиратской Бухте.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к барону Ревилгазу в Пиратскую Бухту на мысе Тернистой долины.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26701,'Полет в Гиблотопь','Обратитесь к Брагоку в Кабестане, чтобы перелететь в Гиблотопь. Затем явитесь к Крогу.','Обратитесь к Крогу в Гиблотопи, что находится в Пылевых степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Полет в Гиблотопь',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обратитесь к Брагоку в Кабестане, чтобы перелететь в Гиблотопь. Затем явитесь к Крогу.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Обратитесь к Крогу в Гиблотопи, что находится в Пылевых степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26702,'Полет в Терамор','Обратитесь к Брагоку в Кабестане, чтобы перелететь в Терамор. Затем явитесь к Калии Гастингс.','Добро пожаловать в Терамор.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Полет в Терамор',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обратитесь к Брагоку в Кабестане, чтобы перелететь в Терамор. Затем явитесь к Калии Гастингс.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Добро пожаловать в Терамор.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertargetname_loc8`) VALUES (26703,'Конец Кровавому Парусу!','Мы почти победили, и все благодаря тебе! Однако осталось еще одно задание... Надо устранить командира флота Фираллона.$B$BСудя по всему, большая часть команды Фираллона уже мертва, но я слишком хорошо знаю этого морского волка – поверь на слово, он жив. Небось заперся у себя в каюте и думает потонуть вместе со своим кораблем.$B$BПоговори с Кебоком еще раз, пусть выдаст тебе ветрокрыла. Я приостановлю пальбу из пушек, пока ты будешь на борту.','Поговорите с Кебоком в Пиратской Бухте, получите ветрокрыла, а потом уничтожьте командира флота Фираллона.','Вернитесь к барону Ревилгазу в Пиратскую Бухту на мысе Тернистой долины.','Командир флота Фираллон') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Конец Кровавому Парусу!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы почти победили, и все благодаря тебе! Однако осталось еще одно задание... Надо устранить командира флота Фираллона.$B$BСудя по всему, большая часть команды Фираллона уже мертва, но я слишком хорошо знаю этого морского волка – поверь на слово, он жив. Небось заперся у себя в каюте и думает потонуть вместе со своим кораблем.$B$BПоговори с Кебоком еще раз, пусть выдаст тебе ветрокрыла. Я приостановлю пальбу из пушек, пока ты будешь на борту.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Кебоком в Пиратской Бухте, получите ветрокрыла, а потом уничтожьте командира флота Фираллона.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к барону Ревилгазу в Пиратскую Бухту на мысе Тернистой долины.',`completedtext_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Командир флота Фираллон',`questgivertargetname_loc8`);
