INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (26705,'It\'s a Town-In-A-Box Tracking Event') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','It\'s a Town-In-A-Box Tracking Event',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26707,'Смертоносная лоза','Мне нужно много трупоросли для зелий мастера Харриса. Добыть ее трудно, но сократить поставки мы не можем.$b$bС трупорослью совладать нелегко... если ты недостаточно $gосторожен:осторожна;, растение одолеет тебя, ты и пикнуть не успеешь! Но если ты $gготов:готова; помочь, я охотно заплачу тебе за каждое собранное растение.$b$bИх много в усадьбе Йоргена, что к юго-востоку отсюда.','Соберите 5 растений трупоросли.','Вернитесь к ученику Фессу в Сумеречный лес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Смертоносная лоза',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне нужно много трупоросли для зелий мастера Харриса. Добыть ее трудно, но сократить поставки мы не можем.$b$bС трупорослью совладать нелегко... если ты недостаточно $gосторожен:осторожна;, растение одолеет тебя, ты и пикнуть не успеешь! Но если ты $gготов:готова; помочь, я охотно заплачу тебе за каждое собранное растение.$b$bИх много в усадьбе Йоргена, что к юго-востоку отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 5 растений трупоросли.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ученику Фессу в Сумеречный лес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26708,'А-А-А-А-А-А-А!!! А-А-А-А-А!!!','Я здесь, чтобы помочь тебе и команде "Браво". Полезай в осадный танк и расчисть путь до Лагеря Кишана: он на другой стороне долины, к северу отсюда.$B$BСделать это будет очень непросто, потому что орки Черной горы теперь знают, где ты, и высылают тебе навстречу довольно много солдат. Уничтожь их всех, и прояви как можно больше жестокости!$B$BВстретимся на той стороне. Да хранит Свет твою душу.','Убейте 200 солдат Черной горы при помощи осадного танка команды "Браво".','Теперь осталось разобраться только с орками, захватившими крепость Каменной Стражи.','Поговорите с полковником Тротманом в Лагере Кишана, что в Красногорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','А-А-А-А-А-А-А!!! А-А-А-А-А!!!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я здесь, чтобы помочь тебе и команде "Браво". Полезай в осадный танк и расчисть путь до Лагеря Кишана: он на другой стороне долины, к северу отсюда.$B$BСделать это будет очень непросто, потому что орки Черной горы теперь знают, где ты, и высылают тебе навстречу довольно много солдат. Уничтожь их всех, и прояви как можно больше жестокости!$B$BВстретимся на той стороне. Да хранит Свет твою душу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 200 солдат Черной горы при помощи осадного танка команды "Браво".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь осталось разобраться только с орками, захватившими крепость Каменной Стражи.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с полковником Тротманом в Лагере Кишана, что в Красногорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (26709,'Каменный трон','Я возвращаюсь к своему трону. У меня больше нет желания видеть кого бы то ни было из этих Служителей Земли, но тебе здесь всегда будут рады, |3-6($r). Если ты хочешь помочь нам в восстановлении нашего мира, возможно, мы тоже сможем помочь тебе.$b$bВсему свое время.','Ты вернулся. Это хорошо. Каменные лорды спрашивали о тебе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Каменный трон',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я возвращаюсь к своему трону. У меня больше нет желания видеть кого бы то ни было из этих Служителей Земли, но тебе здесь всегда будут рады, |3-6($r). Если ты хочешь помочь нам в восстановлении нашего мира, возможно, мы тоже сможем помочь тебе.$b$bВсему свое время.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты вернулся. Это хорошо. Каменные лорды спрашивали о тебе.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26710,'Потерявшийся в глубинах','Камешек заблудился где-то в Гремящих глубинах.$b$bК счастью, из-за своего маленького размера он не привлекает внимание червинтов. Но рано или поздно кто-нибудь из них случайно наткнется на него и съест.$b$bКажется, ты ему нравишься. Пожалуйста, найди его и выведи из этих туннелей, пусть он играет в более безопасных местах.','Найдите Камешка в Гремящих глубинах и выведите его из туннелей в целости и сохранности.','Прекрасно. Теперь эти скальчата смогут расти и учиться, они станут большими и сильными.$B$BКогда-нибудь мы справимся с нашествием червинтов, и детство скальчат перестанет быть таким трудным.','Вернитесь к колчедановому камнестражу к Трону Теразан.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Потерявшийся в глубинах',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Камешек заблудился где-то в Гремящих глубинах.$b$bК счастью, из-за своего маленького размера он не привлекает внимание червинтов. Но рано или поздно кто-нибудь из них случайно наткнется на него и съест.$b$bКажется, ты ему нравишься. Пожалуйста, найди его и выведи из этих туннелей, пусть он играет в более безопасных местах.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Камешка в Гремящих глубинах и выведите его из туннелей в целости и сохранности.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно. Теперь эти скальчата смогут расти и учиться, они станут большими и сильными.$B$BКогда-нибудь мы справимся с нашествием червинтов, и детство скальчат перестанет быть таким трудным.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к колчедановому камнестражу к Трону Теразан.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26711,'Сначала – в банк','Привет, малышка. Готова к банкету?$B$BНет?! Знаешь, я тебя очень люблю, поэтому даже не знаю, как и сказать... но, по-моему, тебе надо быстренько сгонять в город и купить новый прикид... ну, чтобы прийти на банкет при параде.$B$BИ не надо так на меня смотреть... Ты должна выглядеть на все сто! Верно я говорю? В общем, как ни крути, тебе следует приодеться. В конце концов, я же твой парень!$B$BНо сперва зайди в банк и возьми побольше деревянных. Чтобы купить самые лучшие вещи, а не какое-то дешевое барахло!','Поговорите с кассиром Первого банка Кезана.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сначала – в банк',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Привет, малышка. Готова к банкету?$B$BНет?! Знаешь, я тебя очень люблю, поэтому даже не знаю, как и сказать... но, по-моему, тебе надо быстренько сгонять в город и купить новый прикид... ну, чтобы прийти на банкет при параде.$B$BИ не надо так на меня смотреть... Ты должна выглядеть на все сто! Верно я говорю? В общем, как ни крути, тебе следует приодеться. В конце концов, я же твой парень!$B$BНо сперва зайди в банк и возьми побольше деревянных. Чтобы купить самые лучшие вещи, а не какое-то дешевое барахло!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с кассиром Первого банка Кезана.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26712,'Сначала – в банк','Привет, милый. Готов к банкету?$B$BНет?! Знаешь, я тебя очень люблю, поэтому даже не знаю, как и сказать... но, по-моему, тебе надо быстренько сгонять в город и купить новый прикид... ну, чтобы прийти на банкет при параде.$B$BИ не надо так на меня смотреть... Ты должен выглядеть на все сто! Верно я говорю? В общем, как ни крути, тебе следует приодеться. В конце концов, я же твоя девушка!$B$BНо сперва заскочи в банк и возьми побольше деревянных. Чтобы купить самые лучшие вещи, а не какое-то дешевое барахло!','Поговорите с кассиром Первого банка Кезана.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сначала – в банк',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Привет, милый. Готов к банкету?$B$BНет?! Знаешь, я тебя очень люблю, поэтому даже не знаю, как и сказать... но, по-моему, тебе надо быстренько сгонять в город и купить новый прикид... ну, чтобы прийти на банкет при параде.$B$BИ не надо так на меня смотреть... Ты должен выглядеть на все сто! Верно я говорю? В общем, как ни крути, тебе следует приодеться. В конце концов, я же твоя девушка!$B$BНо сперва заскочи в банк и возьми побольше деревянных. Чтобы купить самые лучшие вещи, а не какое-то дешевое барахло!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с кассиром Первого банка Кезана.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (26713,'Решающее сражение в крепости Каменной Стражи','Осталось лишь верховное командование клана Черной горы, $n. Все они засели в крепости Каменной Стражи, это к югу от занимаемых нами позиций здесь в Лагере Кишана. Я хочу, чтобы ты вместе с командой "Браво" $gпроник:проникла; в крепость и $gположил:положила; конец армии орков Черной горы.$b$bВ живых никого не оставлять, $n.','Убейте Тарил\'зуна и Гат\'Илзогга.','Поговорите с полковником Тротманом в Лагере Кишана, что в Красногорье.','Это ловушка! Скорее отсюда!','Полковник Тротман') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Решающее сражение в крепости Каменной Стражи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Осталось лишь верховное командование клана Черной горы, $n. Все они засели в крепости Каменной Стражи, это к югу от занимаемых нами позиций здесь в Лагере Кишана. Я хочу, чтобы ты вместе с командой "Браво" $gпроник:проникла; в крепость и $gположил:положила; конец армии орков Черной горы.$b$bВ живых никого не оставлять, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Тарил\'зуна и Гат\'Илзогга.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с полковником Тротманом в Лагере Кишана, что в Красногорье.',`completedtext_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Это ловушка! Скорее отсюда!',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Полковник Тротман',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26714,'Темное Пламя, потомок разрушителя миров','После того как голос Тротмана обрывается, наступает пугающая тишина. Вдали вы видите большого черного дракона!','Воспользуйтесь рогом призыва, чтобы вызвать Темное Пламя, и победите его.','<Скупая слеза скатывается по щеке Тротмана.>$B$BОни умерли, защищая Альянс. Защищая наше королевство! Все они герои и будут похоронены с почестями.','Вернитесь с докладом к полковонику Тротману в Лагерь Кишана, что в Красногорье.','Темное Пламя должен умереть!','Полковник Тротман') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Темное Пламя, потомок разрушителя миров',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','После того как голос Тротмана обрывается, наступает пугающая тишина. Вдали вы видите большого черного дракона!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь рогом призыва, чтобы вызвать Темное Пламя, и победите его.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Скупая слеза скатывается по щеке Тротмана.>$B$BОни умерли, защищая Альянс. Защищая наше королевство! Все они герои и будут похоронены с почестями.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь с докладом к полковонику Тротману в Лагерь Кишана, что в Красногорье.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Темное Пламя должен умереть!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Полковник Тротман',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26715,'Малфурион Ярость Бури','Малфурион знает, что ты придешь, и очень заинтересован в личной встрече с тобой.$B$BОн в храме Луны, рядом с нашей возлюбленной Тирандой Шелест Ветра. Малфурион находится при ней неотлучно со времени своего возвращения.$B$BОднако следует тебя предупредить... Малфурион сам решает, с кем ему говорить, а с кем – нет. Не трать его время попусту, если от тебя не зависит судьба твоего народа.','Поговорите с Малфурионом Яростью Бури в храме Луны в Дарнасе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Малфурион Ярость Бури',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Малфурион знает, что ты придешь, и очень заинтересован в личной встрече с тобой.$B$BОн в храме Луны, рядом с нашей возлюбленной Тирандой Шелест Ветра. Малфурион находится при ней неотлучно со времени своего возвращения.$B$BОднако следует тебя предупредить... Малфурион сам решает, с кем ему говорить, а с кем – нет. Не трать его время попусту, если от тебя не зависит судьба твоего народа.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Малфурионом Яростью Бури в храме Луны в Дарнасе.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26716,'Конфиденциальный разговор','Я действительно очень хочу побеседовать с тобой, но предпочел бы более спокойную обстановку – место, где мы сможем не опасаться любопытных ушей.$B$BЕсли ты не против, давай через минуту встретимся в Храмовых садах.','Придите на встречу с Малфурионом Яростью Бури в Храмовые сады в Дарнасе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Конфиденциальный разговор',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я действительно очень хочу побеседовать с тобой, но предпочел бы более спокойную обстановку – место, где мы сможем не опасаться любопытных ушей.$B$BЕсли ты не против, давай через минуту встретимся в Храмовых садах.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Придите на встречу с Малфурионом Яростью Бури в Храмовые сады в Дарнасе.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26717,'Ворген Йоргена','Мои сородичи с Вороньего Холма занимаются исцелением диких воргенов в здешних лесах. С внешним обликом ничего не сделать, но постараться вернуть разум можно, особенно тем из них, кто еще не зашел слишком далеко.$b$bХотя большинству из них уже не поможешь, мы приглядываем за теми, кто еще сохранил остатки разума... из их прошлых жизней.$b$bЯ видел одинокого воргена, рыщущего по усадьбе Йоргена, копающегося в куче земли между зданиями... не $gмог:могла; бы ты проверить, что там за куча и что в ней?','Изучите кучу рыхлой земли в усадьбе Йоргена.','Ты был на волосок от смерти! Но он сбежал, не причинив тебе дальнейшего вреда…$B$BМожет быть, он еще борется. Мастер Харрис должен узнать об этом!','Вернитесь к ученику Фессу в Сумеречный лес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ворген Йоргена',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мои сородичи с Вороньего Холма занимаются исцелением диких воргенов в здешних лесах. С внешним обликом ничего не сделать, но постараться вернуть разум можно, особенно тем из них, кто еще не зашел слишком далеко.$b$bХотя большинству из них уже не поможешь, мы приглядываем за теми, кто еще сохранил остатки разума... из их прошлых жизней.$b$bЯ видел одинокого воргена, рыщущего по усадьбе Йоргена, копающегося в куче земли между зданиями... не $gмог:могла; бы ты проверить, что там за куча и что в ней?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Изучите кучу рыхлой земли в усадьбе Йоргена.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты был на волосок от смерти! Но он сбежал, не причинив тебе дальнейшего вреда…$B$BМожет быть, он еще борется. Мастер Харрис должен узнать об этом!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ученику Фессу в Сумеречный лес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (26718,'К Бесплодным землям','Случилось что-то плохое.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','К Бесплодным землям',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Случилось что-то плохое.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (26719,'Доставка мастеру Харрису','Мастер Харрис захочет узнать об этом немедленно.$b$bВот, возьми этот сверток с трупорослью и отнеси его в лагерь на Вороньем Холме. Расскажи мастеру Харрису, что мы видели в усадьбе Йоргена.','Отнесите сверток с трупорослью Оливеру Харрису на Вороний Холм.','Добро пожаловать в наш скромный лагерь. Приятным его не назовешь, но все-таки какое-то укрытие.$B$BЧто ты говоришь? Ворген на ферме?','Что привело тебя сюда, мой дорогой друг?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Доставка мастеру Харрису',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мастер Харрис захочет узнать об этом немедленно.$b$bВот, возьми этот сверток с трупорослью и отнеси его в лагерь на Вороньем Холме. Расскажи мастеру Харрису, что мы видели в усадьбе Йоргена.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите сверток с трупорослью Оливеру Харрису на Вороний Холм.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Добро пожаловать в наш скромный лагерь. Приятным его не назовешь, но все-таки какое-то укрытие.$B$BЧто ты говоришь? Ворген на ферме?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что привело тебя сюда, мой дорогой друг?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26720,'Проклятие, которое не снять','То, чем мы здесь занимаемся, это не лечение. Ранее наложенное заклинание преображения уже не может быть отменено. Но вот разум...$b$bРазум восстановить при помощи алхимии можно, если он не был затронут. Похоже, что ворген, которого ты $gвстретил:встретила;, борется за это, $n. Мы должны снова найти его.$b$bЕсли в усадьбе Йоргена его уже нет, поищи в усадьбе Эддла, что к югу отсюда. Возможно, он прячется в каком-то из зданий.$b$bВпрысни ему то, что находится в этой ампуле, чтобы его усмирить. Для этого нужно подойти к нему достаточно близко.','Обыщите усадьбу Эддла, найдите крадущегося воргена и впрысните ему содержимое ампулы Харриса, чтобы усмирить его.','Вернитесь к Оливеру Харрису на Вороний Холм, что в Сумеречном лесу.','Воспользуйтесь ампулой Харриса, чтобы усмирить его.','Крадущийся ворген') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Проклятие, которое не снять',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','То, чем мы здесь занимаемся, это не лечение. Ранее наложенное заклинание преображения уже не может быть отменено. Но вот разум...$b$bРазум восстановить при помощи алхимии можно, если он не был затронут. Похоже, что ворген, которого ты $gвстретил:встретила;, борется за это, $n. Мы должны снова найти его.$b$bЕсли в усадьбе Йоргена его уже нет, поищи в усадьбе Эддла, что к югу отсюда. Возможно, он прячется в каком-то из зданий.$b$bВпрысни ему то, что находится в этой ампуле, чтобы его усмирить. Для этого нужно подойти к нему достаточно близко.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обыщите усадьбу Эддла, найдите крадущегося воргена и впрысните ему содержимое ампулы Харриса, чтобы усмирить его.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Оливеру Харрису на Вороний Холм, что в Сумеречном лесу.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Воспользуйтесь ампулой Харриса, чтобы усмирить его.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Крадущийся ворген',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26721,'Реагенты для Трясунчика','М-мастеру Харрису требуется много реагентов для его сывороток. Я должен собирать их для него.$b$bМногие из них не так уж ужасны... я хочу сказать, трупоросль ужасна, но все-таки не настолько, как ядовитые железы черной вдовы. Ты $gвидел:видела; черных вдов в округе? Их детеныши размером с человека. Даже имея оружие, я не могу заставить себя охотиться на них!$b$bПросто это слишком страшно. Если ты сделаешь это за меня, я с радостью заплачу тебе! Просто принеси мне несколько ядовитых желез! Черных вдов можно найти в лесах к востоку отсюда, севернее дороги.','Добудьте 8 ядовитых желез черной вдовы.','О, спасибо, спасибо тебе! Ты избавил меня от необходимости идти в лес, полный таких ужасных существ!$B$BПо крайней мере сегодня…','Ты достал их? Пожалуйста, скажи, что да...','Вернитесь к Трясунчику на Вороний Холм, что в Сумеречном лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Реагенты для Трясунчика',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','М-мастеру Харрису требуется много реагентов для его сывороток. Я должен собирать их для него.$b$bМногие из них не так уж ужасны... я хочу сказать, трупоросль ужасна, но все-таки не настолько, как ядовитые железы черной вдовы. Ты $gвидел:видела; черных вдов в округе? Их детеныши размером с человека. Даже имея оружие, я не могу заставить себя охотиться на них!$b$bПросто это слишком страшно. Если ты сделаешь это за меня, я с радостью заплачу тебе! Просто принеси мне несколько ядовитых желез! Черных вдов можно найти в лесах к востоку отсюда, севернее дороги.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 8 ядовитых желез черной вдовы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, спасибо, спасибо тебе! Ты избавил меня от необходимости идти в лес, полный таких ужасных существ!$B$BПо крайней мере сегодня…',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты достал их? Пожалуйста, скажи, что да...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Трясунчику на Вороний Холм, что в Сумеречном лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26722,'Сокрытый под землей','<Вы присоединяете дужку к жезлу и артефакт почти готов. Но большое отверстие по-прежнему остается в центре передней части святого символа.>$b$b<Вы опять чувствуете, как артефакт пульсирует в вашей руке, заставляя вас двигаться к дыре в стене и извилистому тоннелю за ней. Последняя часть артефакта должна быть там.>','Обыщите туннель под катакомбами Утреннего леса, чтобы найти рыцарский щит из светостали.','<В темных глубинах этого земляного туннеля вы видите слабое свечение. Последняя часть найдена!>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сокрытый под землей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Вы присоединяете дужку к жезлу и артефакт почти готов. Но большое отверстие по-прежнему остается в центре передней части святого символа.>$b$b<Вы опять чувствуете, как артефакт пульсирует в вашей руке, заставляя вас двигаться к дыре в стене и извилистому тоннелю за ней. Последняя часть артефакта должна быть там.>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обыщите туннель под катакомбами Утреннего леса, чтобы найти рыцарский щит из светостали.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<В темных глубинах этого земляного туннеля вы видите слабое свечение. Последняя часть найдена!>',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26723,'Судьба Морбента Скверна','Последний, кого я видел перед тем, как ушел в леса, был Морбент Скверн. Он был мерзким некромантом и это из-за него здесь так много отвратительной нежити.$b$bЯ просил появляющихся здесь путешественников помочь мне покончить с ним. Я думал, они это сделали! Но сестра Элсингтон говорит, что эта местность по-прежнему кишит вурдалаками и восставшими из могил призраками.$b$bВероятно, Морбент Скверн испустил свой последний вздох в Покинутой усадьбе, к северу от Кладбища Вороньего Холма. Отправляйся туда и узнай, что с ним стало...','Найдите в Покинутой усадьбе что-нибудь, имеющее отношение к Морбенту Скверну.','Его одежда и пятна крови? Если это не бутафория, то, значит, кое-что похуже...','Вернитесь к Свену Йоргену на Вороний Холм, что в Сумеречном лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Судьба Морбента Скверна',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Последний, кого я видел перед тем, как ушел в леса, был Морбент Скверн. Он был мерзким некромантом и это из-за него здесь так много отвратительной нежити.$b$bЯ просил появляющихся здесь путешественников помочь мне покончить с ним. Я думал, они это сделали! Но сестра Элсингтон говорит, что эта местность по-прежнему кишит вурдалаками и восставшими из могил призраками.$b$bВероятно, Морбент Скверн испустил свой последний вздох в Покинутой усадьбе, к северу от Кладбища Вороньего Холма. Отправляйся туда и узнай, что с ним стало...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите в Покинутой усадьбе что-нибудь, имеющее отношение к Морбенту Скверну.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Его одежда и пятна крови? Если это не бутафория, то, значит, кое-что похуже...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Свену Йоргену на Вороний Холм, что в Сумеречном лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26724,'Скрывающийся лич','Все остальные разделяют мои подозрения. Морбент Скверн стал нежитью... и теперь он, может быть, еще могущественнее, чем раньше. Некромант был убит, но вместо него появился лич. И он продолжает разрушать эту землю.$b$bЯ помню, каким было Темнолесье раньше, $n. Я помню светлое небо и тихие леса. Так не может продолжаться! Нужно остановить Морбента Скверна раз и навсегда.$b$bПоговори с сестрой Элсингтон. Может быть, она скажет тебе, где найти Морбента Скверна и как победить его.','Поговорите с сестрой Элсингтон.','Приятно видеть, что кто-то, совсем недавно спасенный, так обеспокоен бедами других. Свен предпочитает избавить себя от страданий и не думать слишком часто о своем несчастье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Скрывающийся лич',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Все остальные разделяют мои подозрения. Морбент Скверн стал нежитью... и теперь он, может быть, еще могущественнее, чем раньше. Некромант был убит, но вместо него появился лич. И он продолжает разрушать эту землю.$b$bЯ помню, каким было Темнолесье раньше, $n. Я помню светлое небо и тихие леса. Так не может продолжаться! Нужно остановить Морбента Скверна раз и навсегда.$b$bПоговори с сестрой Элсингтон. Может быть, она скажет тебе, где найти Морбента Скверна и как победить его.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с сестрой Элсингтон.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Приятно видеть, что кто-то, совсем недавно спасенный, так обеспокоен бедами других. Свен предпочитает избавить себя от страданий и не думать слишком часто о своем несчастье.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26725,'Ведомый Светом','Свен прав. Я чувствую присутствие могущественного зла в глубинах Кладбища Вороньего Холма. Зло таится в его катакомбах, и исходит оно наверняка от Морбента Скверна.$b$bЧтобы справиться с ним, тебе понадобится сила Света, $n. Свен говорил, что герои, которые убили Морбента Скверна в первый раз, владели артефактом, изготовленным из светостали и насыщенным святой силой. Этот артефакт все еще здесь!$b$bЯ чувствую его, это мерцание света во тьме. Найди его на Вороньем Холме и пусть Свет ведет тебя.','Найдите жезл из светостали на Кладбище Вороньего Холма.','<В грязи вы находите блестящую металлическую рукоятку. Но отверстия в ней свидетельствуют о том, что некоторых частей артефакта недостает.>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ведомый Светом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Свен прав. Я чувствую присутствие могущественного зла в глубинах Кладбища Вороньего Холма. Зло таится в его катакомбах, и исходит оно наверняка от Морбента Скверна.$b$bЧтобы справиться с ним, тебе понадобится сила Света, $n. Свен говорил, что герои, которые убили Морбента Скверна в первый раз, владели артефактом, изготовленным из светостали и насыщенным святой силой. Этот артефакт все еще здесь!$b$bЯ чувствую его, это мерцание света во тьме. Найди его на Вороньем Холме и пусть Свет ведет тебя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите жезл из светостали на Кладбище Вороньего Холма.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<В грязи вы находите блестящую металлическую рукоятку. Но отверстия в ней свидетельствуют о том, что некоторых частей артефакта недостает.>',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26726,'Триумфальное возвращение','Возвращайся в Приозерье и сообщи Соломону, что орки Черной горы разбиты. Постарайся, чтобы он понял, какой высокой была цена за пришедшую свободу – мы потеряли пятерых из наших самых лучших бойцов, чтобы спасти Красногорье и, в конечном счете, Штормград.$b$bТы – $gединственный, кто выжил:единственная, кто выжила; из команды "Браво", $n. Тебе и продолжать ее дело.$b$b$gСвободен:Свободна;.','Отчитайтесь мировому судье Соломону в Приозерье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Триумфальное возвращение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Возвращайся в Приозерье и сообщи Соломону, что орки Черной горы разбиты. Постарайся, чтобы он понял, какой высокой была цена за пришедшую свободу – мы потеряли пятерых из наших самых лучших бойцов, чтобы спасти Красногорье и, в конечном счете, Штормград.$b$bТы – $gединственный, кто выжил:единственная, кто выжила; из команды "Браво", $n. Тебе и продолжать ее дело.$b$b$gСвободен:Свободна;.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отчитайтесь мировому судье Соломону в Приозерье.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26727,'Месть Бальзамировщика','Убейте Стежка в Темнолесье.','Вернитесь к лорду Элло Чернодреву в городскую ратушу Темнолесья, что в Сумеречном лесу.','Дар Бальзамировщика','Стежок') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Месть Бальзамировщика',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Стежка в Темнолесье.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лорду Элло Чернодреву в городскую ратушу Темнолесья, что в Сумеречном лесу.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Дар Бальзамировщика',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Стежок',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26728,'Воззвание к героям: Темнолесье!','Поговорите с командиром Алтеей Чернодрев в Темнолесье, что в Сумеречном лесу.','Они прислали нам на подмогу тебя?$B$B<Алтея вздыхает.>$B$BНадеюсь, у тебя получится.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Воззвание к героям: Темнолесье!',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с командиром Алтеей Чернодрев в Темнолесье, что в Сумеречном лесу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Они прислали нам на подмогу тебя?$B$B<Алтея вздыхает.>$B$BНадеюсь, у тебя получится.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26729,'Элементали воды','Я прибыла в Тернистую долину для изучения так называемого Алтаря Найаса, но совершила большую ошибку, отвергнув все предложения полковника Курцена, в результате чего и провела несколько лет за решеткой. Теперь я свободна и могу продолжать исследования.$B$BАлтарь находится на острове к западу отсюда и к югу от Зул\'Кунды. Добудь несколько браслетов элементалей воды.$B$BИ кстати, когда закончишь, можешь воспользоваться вот этим устройством. Не возвращаться же тебе обратно пешком.','Добудьте 6 браслетов элементалей воды.','Активируйте говорящую сферу Эмерины в Северной Тернистой долине, чтобы вызвать Эмерину Юнис.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Элементали воды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я прибыла в Тернистую долину для изучения так называемого Алтаря Найаса, но совершила большую ошибку, отвергнув все предложения полковника Курцена, в результате чего и провела несколько лет за решеткой. Теперь я свободна и могу продолжать исследования.$B$BАлтарь находится на острове к западу отсюда и к югу от Зул\'Кунды. Добудь несколько браслетов элементалей воды.$B$BИ кстати, когда закончишь, можешь воспользоваться вот этим устройством. Не возвращаться же тебе обратно пешком.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 6 браслетов элементалей воды.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Активируйте говорящую сферу Эмерины в Северной Тернистой долине, чтобы вызвать Эмерину Юнис.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26730,'Можно вывести мурлока из воды...','К естественной силе этих браслетов явно надо что-то добавить... обладающее неимоверной мощью и в то же время связанное с морем.$B$BЧерножабрые мурлоки давно перебрались из моря на сушу, но до сих пор носят с собой сосуды с морской солью. Я точно не знаю, зачем они им нужны, но в моих исследованиях очень пригодятся. Черножабрые обитают к югу от Лагеря Повстанцев и на востоке от руин Бал\'лал.','Добудьте 6 сосудов с морской солью у черножабрых мурлоков в Северной Тернистой долине.','Теперь у нас есть все что нужно. Готов включить Алтарь Найаса?','Соль?','Активируйте говорящую сферу Эмерины в Северной Тернистой долине, чтобы вызвать Эмерину Юнис.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Можно вывести мурлока из воды...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','К естественной силе этих браслетов явно надо что-то добавить... обладающее неимоверной мощью и в то же время связанное с морем.$B$BЧерножабрые мурлоки давно перебрались из моря на сушу, но до сих пор носят с собой сосуды с морской солью. Я точно не знаю, зачем они им нужны, но в моих исследованиях очень пригодятся. Черножабрые обитают к югу от Лагеря Повстанцев и на востоке от руин Бал\'лал.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 6 сосудов с морской солью у черножабрых мурлоков в Северной Тернистой долине.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь у нас есть все что нужно. Готов включить Алтарь Найаса?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Соль?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Активируйте говорящую сферу Эмерины в Северной Тернистой долине, чтобы вызвать Эмерину Юнис.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26731,'Алтарь Найаса','Соли, которую ты $gпринес:принесла;, достаточно, чтобы активировать заключенные в наручах чары. Я вложила эти чары в амулет призывания... или можешь называть его даром.$B$BВозвращайся на остров Найаса и возложи дар на Алтарь Найаса. Когда у тебя в руках будет сердце Найаса, обратись ко мне.','Используйте дар Найаса, чтобы призвать Найаса, затем добудьте сердце Найаса.','Активируйте говорящую сферу Эмерины в Северной Тернистой долине, чтобы вызвать Эмерину Юнис.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Алтарь Найаса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Соли, которую ты $gпринес:принесла;, достаточно, чтобы активировать заключенные в наручах чары. Я вложила эти чары в амулет призывания... или можешь называть его даром.$B$BВозвращайся на остров Найаса и возложи дар на Алтарь Найаса. Когда у тебя в руках будет сердце Найаса, обратись ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте дар Найаса, чтобы призвать Найаса, затем добудьте сердце Найаса.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Активируйте говорящую сферу Эмерины в Северной Тернистой долине, чтобы вызвать Эмерину Юнис.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26732,'Дурное лекарство','Есть у меня подозрение, что целители Курцена распространяют не только лекарственные снадобья. Курцен не из тех, кто беспрекословно подчиняется приказам. Думаю, под видом "лекарства" скрывается какой-нибудь запрещенный эликсир.$B$BНам нужны образцы этого снадобья. Отправляйся в Лагерь Курцена на юго-востоке – его целители и партизаны, должно быть, носят снадобье с собой.','Отправляйтесь в Лагерь Курцена и раздобудьте 7 склянок зелья из джунглей.','Я, знаешь ли, тоже немного алхимик. В свободное время.','Вернитесь к брату Нимезу в Лагерь Повстанцев в Северной Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дурное лекарство',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Есть у меня подозрение, что целители Курцена распространяют не только лекарственные снадобья. Курцен не из тех, кто беспрекословно подчиняется приказам. Думаю, под видом "лекарства" скрывается какой-нибудь запрещенный эликсир.$B$BНам нужны образцы этого снадобья. Отправляйся в Лагерь Курцена на юго-востоке – его целители и партизаны, должно быть, носят снадобье с собой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Лагерь Курцена и раздобудьте 7 склянок зелья из джунглей.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я, знаешь ли, тоже немного алхимик. В свободное время.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к брату Нимезу в Лагерь Повстанцев в Северной Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26733,'Контрольный образец','<Брат Нимез изучает принесенные вами образцы.>$B$BЭто... так... просто кровь василиска!$B$BХотя нет, не просто. В нее что-то добавили. Мне нужен контрольный образец – для сравнения.$B$BСкорее всего, они брали кровь хрустального василиска, обитающего к востоку от их поселения. Принеси мне чистые образцы, и я попробую разобраться, что это за эликсир.','Соберите 7 образцов крови хрустального василиска.','Вернитесь к брату Нимезу в Лагерь Повстанцев в Северной Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Контрольный образец',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Брат Нимез изучает принесенные вами образцы.>$B$BЭто... так... просто кровь василиска!$B$BХотя нет, не просто. В нее что-то добавили. Мне нужен контрольный образец – для сравнения.$B$BСкорее всего, они брали кровь хрустального василиска, обитающего к востоку от их поселения. Принеси мне чистые образцы, и я попробую разобраться, что это за эликсир.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 7 образцов крови хрустального василиска.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к брату Нимезу в Лагерь Повстанцев в Северной Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26734,'Источник безумия','Снизив содержание крови василиска в эликсире, я обнаружил в нем необычный осадок. Это были какие-то голубые кристаллы...$B$B<Брат Нимез сверяется со своими заметками.>$B$BЭто не синий поющий кристалл... не пульсирующий синий осколок...$B$B<Он перелистывает несколько страниц.>$B$B... не частичка Ока разума. Нет, мы в Тернистой долине никогда такого не видели. Мне необходима еще хоть толика такого вещества. Поищи-ка у элитных войск Курцена, в глубине их пещеры.','Добудьте шепчущий синий камень у войск Курцена в Схроне.','Вернитесь к брату Нимезу в Лагерь Повстанцев в Северной Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Источник безумия',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Снизив содержание крови василиска в эликсире, я обнаружил в нем необычный осадок. Это были какие-то голубые кристаллы...$B$B<Брат Нимез сверяется со своими заметками.>$B$BЭто не синий поющий кристалл... не пульсирующий синий осколок...$B$B<Он перелистывает несколько страниц.>$B$B... не частичка Ока разума. Нет, мы в Тернистой долине никогда такого не видели. Мне необходима еще хоть толика такого вещества. Поищи-ка у элитных войск Курцена, в глубине их пещеры.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте шепчущий синий камень у войск Курцена в Схроне.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к брату Нимезу в Лагерь Повстанцев в Северной Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26735,'Участь Курцена','Здравствуй, |3-6($c).$B$BМы солдаты Штормграда и ренегаты из лагеря Курцена, крупного форпоста к юго-востоку отсюда. Мы служили под командованием полковника Курцена, пока он со своими офицерами не начал постепенно сходить с ума...$B$BМы взбунтовались, разбили здесь лагерь и вступили в противостояние с Курценом. Сейчас ходят слухи, что Курцен куда-то исчез. Я своим источникам доверяю, но неплохо бы эту информацию проверить. Пожалуйста, сходи в лагерь Курцена и узнай, что сталось с полковником.','Раздобудьте тюремные дела лагеря Курцена и досье офицеров лагеря Курцена.','Вернитесь к лейтенанту Дорену в Лагерь Повстанцев в Северной Тернистой долине.','Нужно выяснить, что сталось с Курценом.','Полковник Курцен') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Участь Курцена',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Здравствуй, |3-6($c).$B$BМы солдаты Штормграда и ренегаты из лагеря Курцена, крупного форпоста к юго-востоку отсюда. Мы служили под командованием полковника Курцена, пока он со своими офицерами не начал постепенно сходить с ума...$B$BМы взбунтовались, разбили здесь лагерь и вступили в противостояние с Курценом. Сейчас ходят слухи, что Курцен куда-то исчез. Я своим источникам доверяю, но неплохо бы эту информацию проверить. Пожалуйста, сходи в лагерь Курцена и узнай, что сталось с полковником.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте тюремные дела лагеря Курцена и досье офицеров лагеря Курцена.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лейтенанту Дорену в Лагерь Повстанцев в Северной Тернистой долине.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Нужно выяснить, что сталось с Курценом.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Полковник Курцен',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26736,'Вменяемые заключенные','Смерть Курцена – хорошая новость, но есть еще одно дело, требующее нашего пристального внимания. Возможно, в лагере остались наши потенциальные союзники.$B$BМне все равно, что говорится в тюремных записях, я ЗНАЮ, за что именно их взяли под стражу – за отказ подчиняться приказам. Должно быть, как и моих братьев-повстанцев, безумие их не коснулось, зато они угодили за решетку.$B$BНайди их, $n. Найди и приведи их сюда.','Спасите Беррина Горишпинделя, Эмерину Юнис и Осборна Пропеллерза, находящихся в лагере Курцена.','Вернитесь к лейтенанту Дорену в Лагерь Повстанцев на севере Тернистой долины.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вменяемые заключенные',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Смерть Курцена – хорошая новость, но есть еще одно дело, требующее нашего пристального внимания. Возможно, в лагере остались наши потенциальные союзники.$B$BМне все равно, что говорится в тюремных записях, я ЗНАЮ, за что именно их взяли под стражу – за отказ подчиняться приказам. Должно быть, как и моих братьев-повстанцев, безумие их не коснулось, зато они угодили за решетку.$B$BНайди их, $n. Найди и приведи их сюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Спасите Беррина Горишпинделя, Эмерину Юнис и Осборна Пропеллерза, находящихся в лагере Курцена.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лейтенанту Дорену в Лагерь Повстанцев на севере Тернистой долины.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26737,'Положить конец наследию Курцена','Итак, наши союзники эвакуированы, и мы можем совершить последний рейд в лагерь Курцена. Сейчас они слабы как никогда, а с твоей помощью мы можем ослабить их настолько, что они уже ни за что не оправятся.$B$BВ офицерском досье были вот эти четыре имени – Андерс, Гаул, Миранда и Эскивел. Это самые высокопоставленные чины, что там остались. Поищи их в пещере за поселком. Уничтожение всех четверых станет сокрушительным ударом по силам Курцена.$B$BВперед, $n.','Убейте следующих командиров в Схроне: Андерса, Гаула, Миранду и Эскивела.','Вернитесь к лейтенанту Дорену в Лагерь Повстанцев на севере Тернистой долины.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Положить конец наследию Курцена',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Итак, наши союзники эвакуированы, и мы можем совершить последний рейд в лагерь Курцена. Сейчас они слабы как никогда, а с твоей помощью мы можем ослабить их настолько, что они уже ни за что не оправятся.$B$BВ офицерском досье были вот эти четыре имени – Андерс, Гаул, Миранда и Эскивел. Это самые высокопоставленные чины, что там остались. Поищи их в пещере за поселком. Уничтожение всех четверых станет сокрушительным ударом по силам Курцена.$B$BВперед, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте следующих командиров в Схроне: Андерса, Гаула, Миранду и Эскивела.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лейтенанту Дорену в Лагерь Повстанцев на севере Тернистой долины.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (26738,'Новорожденный','Копаясь в вещах солдата, вы глянули вниз и вдруг увидели новорожденного детеныша ящера, смотрящего на вас. Он что же, все это время шел за этим солдатом Курцена?$B$BДетеныш вас изучает, запоминает черты вашего лица и следит за всеми вашими движениями.$B$BМежду вами и этим детенышем кнутохвоста явно установилась некая связь.$B$BВозможно, кто-нибудь в Лагере Повстанцев подскажет, что делать с ним дальше.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новорожденный',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Копаясь в вещах солдата, вы глянули вниз и вдруг увидели новорожденного детеныша ящера, смотрящего на вас. Он что же, все это время шел за этим солдатом Курцена?$B$BДетеныш вас изучает, запоминает черты вашего лица и следит за всеми вашими движениями.$B$BМежду вами и этим детенышем кнутохвоста явно установилась некая связь.$B$BВозможно, кто-нибудь в Лагере Повстанцев подскажет, что делать с ним дальше.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26739,'Не покормишь – не вырастишь','Похоже, твой детеныш ящера голоден. Если хочешь позаботиться о зверушке, почему б тебе не принести ей какой-нибудь еды? Кнутохвосты частенько нападают на василисков Тернистой долины, которые водятся к востоку отсюда, выше Лагеря Курцена.$B$BУ этого крошки-ящера силенок пока маловато, чтобы самому охотиться, но ему наверняка придется по вкусу свежее мясо василиска.','Убивайте хрустальных василисков в Северной Тернистой долине и кормите своего ящера-кнутохвоста их мясом, пока он не съест 40 кусочков.','Вернитесь к капралу Сетману в Лагерь Повстанцев, что в Северной Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Не покормишь – не вырастишь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Похоже, твой детеныш ящера голоден. Если хочешь позаботиться о зверушке, почему б тебе не принести ей какой-нибудь еды? Кнутохвосты частенько нападают на василисков Тернистой долины, которые водятся к востоку отсюда, выше Лагеря Курцена.$B$BУ этого крошки-ящера силенок пока маловато, чтобы самому охотиться, но ему наверняка придется по вкусу свежее мясо василиска.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убивайте хрустальных василисков в Северной Тернистой долине и кормите своего ящера-кнутохвоста их мясом, пока он не съест 40 кусочков.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капралу Сетману в Лагерь Повстанцев, что в Северной Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26740,'Горшок Кразека','Готовка в лагере по большей части лежит на мне. Ох, и хлопот она доставляла! Но потом я купил у одного гоблина механический горшок. Это чудо какое-то! Он сэкономил мне столько времени... Пока не сломался!$B$BМожет, ты отнесешь его назад продавцу, в ремонт? Продавца зовут Кразек. Я слышал, он остановился у Эрнестуэя в лагере охотников к югу отсюда.','Отнесите неисправный горшок Кразеку.','А, вижу – неисправный горшок Кразека! Отличное устройство, но иногда выходят из строя пружины или шестерни. Посмотрим, что случилось с этой штукой...$B$BАга! Заржавел паровой агрегат, полетел сальник, а у надувателя отломились зубья. Странно, как тут умудрялись хотя бы варить репу!$B$BМогу ли я это починить? Разумеется!$B$BНо не бесплатно. Бесплатным бывает только сыр в мышеловке...','Поговорите с Кразеком в лагере экспедиции Эрнестуэя, который находится в Северной Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Горшок Кразека',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Готовка в лагере по большей части лежит на мне. Ох, и хлопот она доставляла! Но потом я купил у одного гоблина механический горшок. Это чудо какое-то! Он сэкономил мне столько времени... Пока не сломался!$B$BМожет, ты отнесешь его назад продавцу, в ремонт? Продавца зовут Кразек. Я слышал, он остановился у Эрнестуэя в лагере охотников к югу отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите неисправный горшок Кразеку.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, вижу – неисправный горшок Кразека! Отличное устройство, но иногда выходят из строя пружины или шестерни. Посмотрим, что случилось с этой штукой...$B$BАга! Заржавел паровой агрегат, полетел сальник, а у надувателя отломились зубья. Странно, как тут умудрялись хотя бы варить репу!$B$BМогу ли я это починить? Разумеется!$B$BНо не бесплатно. Бесплатным бывает только сыр в мышеловке...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Кразеком в лагере экспедиции Эрнестуэя, который находится в Северной Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (26741,'REUSE') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','REUSE',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26742,'Изучение Кровавого Скальпа','Я ведь так толком и не поблагодарил тебя за свое спасение.$B$BСпасибо, $n.$B$BЯ еще не восстановил силы после долгого плена... не будешь так добр, не поможешь ли мне в исследованиях? Как шамана клана Громового Молота меня очень интересуют шаманские знания племени Кровавого Скальпа.$B$BПохоже, их магия развивалась каким-то особым путем. Если бы у меня был один из тотемов шамана этого племени, я мог бы начать работу. Тотемы можно найти на руинах Бал\'лал, на юго-западном побережье.','Добудьте тотем Кровавого Скальпа у шамана этого племени.','<Беррин рассматривает надписи на тотеме.>$B$BКажется, я понимаю, что тут написано... Потрясающе!$B$BЦул\'Калу, Махамба, Погеан... Чьи это имена?','Осторожно: они могут напасть.','Вернитесь к Беррину Горишпинделю в Лагерь Повстанцев, что в Северной Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Изучение Кровавого Скальпа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я ведь так толком и не поблагодарил тебя за свое спасение.$B$BСпасибо, $n.$B$BЯ еще не восстановил силы после долгого плена... не будешь так добр, не поможешь ли мне в исследованиях? Как шамана клана Громового Молота меня очень интересуют шаманские знания племени Кровавого Скальпа.$B$BПохоже, их магия развивалась каким-то особым путем. Если бы у меня был один из тотемов шамана этого племени, я мог бы начать работу. Тотемы можно найти на руинах Бал\'лал, на юго-западном побережье.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте тотем Кровавого Скальпа у шамана этого племени.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Беррин рассматривает надписи на тотеме.>$B$BКажется, я понимаю, что тут написано... Потрясающе!$B$BЦул\'Калу, Махамба, Погеан... Чьи это имена?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Осторожно: они могут напасть.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Беррину Горишпинделю в Лагерь Повстанцев, что в Северной Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26743,'Реликвия Кровавых Скальпов','А-а... это, наверное, имена тотемических тварей – зверей, которых они соотносят с разными духами. Посмотрим... Махамба – это вода, Цул\'Калу – земля, Погеан... воздух? Огонь? Не могу прочитать эту часть.$B$BХотелось бы мне получить побольше сведений об этих духах. Тут неподалеку – в руинах Ткаши – лагерь Кровавых Скальпов. Может, там ты что-нибудь найдешь.','Добудьте у Кровавых Скальпов в руинах Ткаши идола Цул\'калу, идола Махамбы и идола Погеана.','Вернитесь к Беррину Горишпинделю в Лагерь Повстанцев, что в Северной Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Реликвия Кровавых Скальпов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А-а... это, наверное, имена тотемических тварей – зверей, которых они соотносят с разными духами. Посмотрим... Махамба – это вода, Цул\'Калу – земля, Погеан... воздух? Огонь? Не могу прочитать эту часть.$B$BХотелось бы мне получить побольше сведений об этих духах. Тут неподалеку – в руинах Ткаши – лагерь Кровавых Скальпов. Может, там ты что-нибудь найдешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте у Кровавых Скальпов в руинах Ткаши идола Цул\'калу, идола Махамбы и идола Погеана.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Беррину Горишпинделю в Лагерь Повстанцев, что в Северной Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26744,'Глубокие корни','Кстати, я коллекционирую тролльи истории и легенды для... личного интереса. Вот и подумал, может, ты сумеешь мне в этом помочь?$B$BУ троллей из племени Кровавого Скальпа, живущих в руинах Бал\'лал – это на берегу к юго-западу отсюда, – есть каменные таблички, на которых высечены их предания. Принесешь мне такую табличку, я тебе очень хорошо заплачу.','Отыщите "Легенды и предания племени Кровавого Скальпа" в руинах Бал\'лал, что в Северной Тернистой долине.','Вернитесь к капралу Сетману в Лагерь Повстанцев, что в Северной Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Глубокие корни',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кстати, я коллекционирую тролльи истории и легенды для... личного интереса. Вот и подумал, может, ты сумеешь мне в этом помочь?$B$BУ троллей из племени Кровавого Скальпа, живущих в руинах Бал\'лал – это на берегу к юго-западу отсюда, – есть каменные таблички, на которых высечены их предания. Принесешь мне такую табличку, я тебе очень хорошо заплачу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщите "Легенды и предания племени Кровавого Скальпа" в руинах Бал\'лал, что в Северной Тернистой долине.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капралу Сетману в Лагерь Повстанцев, что в Северной Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26745,'Особенный череп','Ваш ручной ящер нашел себе новую игрушку – череп из лежащей неподалеку горы черепов троллей.$B$BВы не можете понять, чем этот череп отличается от остальных, но животное не хочет его отдавать.$B$BОсборн Пропеллерз, гном, которого вы освободили из Лагеря Курцена, отлично разбирается как в истории троллей, так и в их физиологии. Может быть, он поймет, чем этот череп отличается от остальных.','Поговорите с Осборном Пропеллерзом в Лагере Повстанцев и покажите ему свежий череп детеныша кнутохвоста.','Поговорите с Осборном Пропеллерзом в Лагере Повстанцев в Северной Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Особенный череп',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ваш ручной ящер нашел себе новую игрушку – череп из лежащей неподалеку горы черепов троллей.$B$BВы не можете понять, чем этот череп отличается от остальных, но животное не хочет его отдавать.$B$BОсборн Пропеллерз, гном, которого вы освободили из Лагеря Курцена, отлично разбирается как в истории троллей, так и в их физиологии. Может быть, он поймет, чем этот череп отличается от остальных.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Осборном Пропеллерзом в Лагере Повстанцев и покажите ему свежий череп детеныша кнутохвоста.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Осборном Пропеллерзом в Лагере Повстанцев в Северной Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26746,'Хороший нюх','<Осборн еще раз осматривает череп.>$B$BПри жизни он был могучим и сильным вождем, настоящим владыкой троллей. И с нашей помощью снова станет владыкой.$B$BУ падальщиков из племени Кровавого Скальпа, обитающих в руинах на юго-западе, есть магические фетиши, которые могут нам пригодится. Падальщики прячут эти артефакты под землей. Твой ящеренок найдет их по запаху, $n... собери, сколько найдешь, и неси их сюда.','С помощью детеныша кнутохвоста разыщите 8 фетишей Ткаши.','Сейчас мы займемся... как там это у них называется, у троллей? Вуду? И-го-го? Мумба-юмба?$B$BЛадно, короче! Если мы собираемся воскресить тролля, нам нужна тролльская магия, а в этих штуках ее полно.','Сколько там штук?','Вернитесь к Осборну Пропеллерзу в Лагерь Повстанцев, что в Северной Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хороший нюх',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Осборн еще раз осматривает череп.>$B$BПри жизни он был могучим и сильным вождем, настоящим владыкой троллей. И с нашей помощью снова станет владыкой.$B$BУ падальщиков из племени Кровавого Скальпа, обитающих в руинах на юго-западе, есть магические фетиши, которые могут нам пригодится. Падальщики прячут эти артефакты под землей. Твой ящеренок найдет их по запаху, $n... собери, сколько найдешь, и неси их сюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','С помощью детеныша кнутохвоста разыщите 8 фетишей Ткаши.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сейчас мы займемся... как там это у них называется, у троллей? Вуду? И-го-го? Мумба-юмба?$B$BЛадно, короче! Если мы собираемся воскресить тролля, нам нужна тролльская магия, а в этих штуках ее полно.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Сколько там штук?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Осборну Пропеллерзу в Лагерь Повстанцев, что в Северной Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26747,'Отборный экземпляр','Душа готова, но не тело. Для столь прекрасно сформированного черепа, такого чудесного, такого красивого, нужно подходящее тело.$B$BВождь Кровавых Скальпов Ган\'зулах захватил трон силой. Если он еще не умер, найдешь его на западе, в Зул\'Кунде.$B$BПолучить его тело не так просто, но $gтакой стойкий:такая стойкая:c; |3-6($c) все сможет. Когда закончишь – неси его сюда.','Добудьте тело Ган\'зулаха в Зул\'Кунде.','Вернитесь к Осборну Пропеллерзу в Лагерь Повстанцев, что в Северной Тернистой долине.','Только глянь, какая мускулатура!','Ган\'зулах') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отборный экземпляр',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Душа готова, но не тело. Для столь прекрасно сформированного черепа, такого чудесного, такого красивого, нужно подходящее тело.$B$BВождь Кровавых Скальпов Ган\'зулах захватил трон силой. Если он еще не умер, найдешь его на западе, в Зул\'Кунде.$B$BПолучить его тело не так просто, но $gтакой стойкий:такая стойкая:c; |3-6($c) все сможет. Когда закончишь – неси его сюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте тело Ган\'зулаха в Зул\'Кунде.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Осборну Пропеллерзу в Лагерь Повстанцев, что в Северной Тернистой долине.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Только глянь, какая мускулатура!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Ган\'зулах',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26748,'Мандокир Повелитель Крови','Я – твой самый страшный кошмар, |3-6($r). Ты же не $gдумал:думала;, что я тебе друг, а, |3-6($r)? Ха-ха-ха!$B$BТы свое дело $gсделал:сделала;. Благодаря тебе я вернулся в царство живых. Поэтому я тебя не убью, а предложу сделку.$B$BОтдай мне ящера.$B$BТы, наверное, уже знаешь, что она не обычный ящер, а мне нужна замена для Оган. Делай, как я говорю. Иначе вы оба – и ты, и гном – испытаете на себе силу моего гнева.','Принесите осколок яйца ящера-кнутохвоста Мандокиру Повелителю Крови в Лагерь Повстанцев.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мандокир Повелитель Крови',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я – твой самый страшный кошмар, |3-6($r). Ты же не $gдумал:думала;, что я тебе друг, а, |3-6($r)? Ха-ха-ха!$B$BТы свое дело $gсделал:сделала;. Благодаря тебе я вернулся в царство живых. Поэтому я тебя не убью, а предложу сделку.$B$BОтдай мне ящера.$B$BТы, наверное, уже знаешь, что она не обычный ящер, а мне нужна замена для Оган. Делай, как я говорю. Иначе вы оба – и ты, и гном – испытаете на себе силу моего гнева.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите осколок яйца ящера-кнутохвоста Мандокиру Повелителю Крови в Лагерь Повстанцев.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26749,'Жрица Тхаалия','Спасибо, $n. Знаю, ты не $gобязан был:обязана была; меня спасать.$B$BВозвращение Мандокира Повелителя Крови – очень дурная новость. Несколько лет назад его убили в Зул\'Гурубе, и мы тогда решили, что больше не увидим ни его, ни ему подобных. Но тролли в Зул\'Гурубе не оставляли попыток провести свой чудовищный ритуал. И если они все же смогли вернуть Мандокира к жизни, то, скорее всего, они воскресили и других.$B$BИсследователи из форта Ливингстон, что далеко на юге, могут знать больше. Поговори с их жрицей.','Найдите жрицу Тхаалию в форте Ливингстон в Северной Тернистой долине и поговорите с ней.','Да, Мандокир жив.$B$BДа, это твоя вина.$B$BДа, ты все еще сможешь его остановить.','Найдите жрицу Тхаалию в форте Ливингстон в Северной Тернистой долине и поговорите с ней.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жрица Тхаалия',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Спасибо, $n. Знаю, ты не $gобязан был:обязана была; меня спасать.$B$BВозвращение Мандокира Повелителя Крови – очень дурная новость. Несколько лет назад его убили в Зул\'Гурубе, и мы тогда решили, что больше не увидим ни его, ни ему подобных. Но тролли в Зул\'Гурубе не оставляли попыток провести свой чудовищный ритуал. И если они все же смогли вернуть Мандокира к жизни, то, скорее всего, они воскресили и других.$B$BИсследователи из форта Ливингстон, что далеко на юге, могут знать больше. Поговори с их жрицей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите жрицу Тхаалию в форте Ливингстон в Северной Тернистой долине и поговорите с ней.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, Мандокир жив.$B$BДа, это твоя вина.$B$BДа, ты все еще сможешь его остановить.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Найдите жрицу Тхаалию в форте Ливингстон в Северной Тернистой долине и поговорите с ней.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (26750,'Мать-Скала зовет','Поговорите с Теразан, Матерью-Скалой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мать-Скала зовет',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Теразан, Матерью-Скалой.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26751,'"Кон-тролль" популяции','Насколько понимаю, ты скоро отправляешься в Зул\'Кунду. Но пока ты здесь, у меня для тебя небольшое задание.$B$BВ Тернистой долине развелось слишком много троллей. Западные земли заняло племя Кровавого Скальпа, восточные – Дробители Черепов. Они перебираются из своих руин в джунгли и нарушают равновесие здешней природы. Пора нам его восстановить.$B$BЗул\'Кунда – столица Кровавого Скальпа. Там живут все высокопоставленные члены племени. Убей нескольких, а потом возвращайся ко мне.','Убейте 7 мистиков, 7 охотников, 7 разведчиков и 1 повелителя зверей из племени Кровавого Скальпа.','Вернитесь к сержанту Йохве в Лагерь Повстанцев, что в Северной Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','"Кон-тролль" популяции',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Насколько понимаю, ты скоро отправляешься в Зул\'Кунду. Но пока ты здесь, у меня для тебя небольшое задание.$B$BВ Тернистой долине развелось слишком много троллей. Западные земли заняло племя Кровавого Скальпа, восточные – Дробители Черепов. Они перебираются из своих руин в джунгли и нарушают равновесие здешней природы. Пора нам его восстановить.$B$BЗул\'Кунда – столица Кровавого Скальпа. Там живут все высокопоставленные члены племени. Убей нескольких, а потом возвращайся ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 7 мистиков, 7 охотников, 7 разведчиков и 1 повелителя зверей из племени Кровавого Скальпа.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к сержанту Йохве в Лагерь Повстанцев, что в Северной Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26752,'Аудиенция у Матери-Скалы','Стой, где стоишь, $gзащитник:защитница;. Я еще не решила, что делать с тобой или твоими Служителями Земли.','Выслушайте Мать-Скалу.','Ты отлично справился. Мать-Скала выслушала нас, и столп мира уже почти в наших руках.','Поговорите с заклинателем земли Торунскаром у Трона Теразан.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Аудиенция у Матери-Скалы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Стой, где стоишь, $gзащитник:защитница;. Я еще не решила, что делать с тобой или твоими Служителями Земли.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выслушайте Мать-Скалу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты отлично справился. Мать-Скала выслушала нас, и столп мира уже почти в наших руках.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с заклинателем земли Торунскаром у Трона Теразан.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26753,'Чертоги мертвых','<Земляной откос перед вами спускается к темному входу в гробницы.>$b$b<Вы чувствуете пульсацию артефакта из светостали, который притягивает вас к себе. Может быть, там находится недостающая часть?>','Найдите дужку из светостали в катакомбах Утреннего леса.','<В грязи алькова вы замечаете что-то из блестящего металла. Вы нашли еще одну часть артефакта!>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чертоги мертвых',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Земляной откос перед вами спускается к темному входу в гробницы.>$b$b<Вы чувствуете пульсацию артефакта из светостали, который притягивает вас к себе. Может быть, там находится недостающая часть?>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите дужку из светостали в катакомбах Утреннего леса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<В грязи алькова вы замечаете что-то из блестящего металла. Вы нашли еще одну часть артефакта!>',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26754,'Погибель Морбента','<Части подходят друг к другу и святой артефакт восстановлен и светится священным светом. Он должен помочь вам противостоять темной магии Морбента Скверна.>$b$b<Глубоко в туннеле, вдали от того места, откуда вы пришли, раздается омерзительный гогот. Это громкий хохот лича. Морбент Скверн впереди!>','Воспользуйтесь артефактом Погибель Морбента, чтобы победить его.','Пусть на этот раз отвратительный монстр останется мертв!$B$BЯ пойду туда и сам превращу его останки в пепел, который развею по ветру. И, может быть, через некоторое время Сумеречный лес станет таким же спокойным местом, как и раньше.','Вернитесь к Свену Йоргену на Вороний Холм, что в Сумеречном лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Погибель Морбента',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Части подходят друг к другу и святой артефакт восстановлен и светится священным светом. Он должен помочь вам противостоять темной магии Морбента Скверна.>$b$b<Глубоко в туннеле, вдали от того места, откуда вы пришли, раздается омерзительный гогот. Это громкий хохот лича. Морбент Скверн впереди!>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь артефактом Погибель Морбента, чтобы победить его.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Пусть на этот раз отвратительный монстр останется мертв!$B$BЯ пойду туда и сам превращу его останки в пепел, который развею по ветру. И, может быть, через некоторое время Сумеречный лес станет таким же спокойным местом, как и раньше.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Свену Йоргену на Вороний Холм, что в Сумеречном лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26755,'Отражение атаки','О, прекрасно, еще одна катапульта! Может быть из Глина уже и сыпется песок, но боевые машины он делает знатные.$b$bНу, мясной мешок, ты не просто так $gтащил:тащила; сюда эту штуку. Забирайся на одну из них и лупи по грибным ужасням и по подкреплению, которое прибывает из Шлакового зала.$b$bОтбросим их от передовой!','Уничтожьте 30 грибных ужасней или каменных троггов из подкрепления.','Вернитесь к Колчедану Магнетию к Остроконечной скале в Подземье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отражение атаки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','О, прекрасно, еще одна катапульта! Может быть из Глина уже и сыпется песок, но боевые машины он делает знатные.$b$bНу, мясной мешок, ты не просто так $gтащил:тащила; сюда эту штуку. Забирайся на одну из них и лупи по грибным ужасням и по подкреплению, которое прибывает из Шлакового зала.$b$bОтбросим их от передовой!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 30 грибных ужасней или каменных троггов из подкрепления.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Колчедану Магнетию к Остроконечной скале в Подземье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26756,'Nessa Shadowsong','A friend of mine, Nessa Shadowsong, is a fishing merchant in Rut\'theran Village. She needs a parcel taken to Darkshore, and is looking for someone to help her.$B$BIf you\'re interested, then to reach Nessa you must take the portal in Darnassus to Rut\'theran Village. You will find the portal west of the Temple Gardens.','[Deprecated] Speak with Nessa Shadowsong.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Nessa Shadowsong',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','A friend of mine, Nessa Shadowsong, is a fishing merchant in Rut\'theran Village. She needs a parcel taken to Darkshore, and is looking for someone to help her.$B$BIf you\'re interested, then to reach Nessa you must take the portal in Darnassus to Rut\'theran Village. You will find the portal west of the Temple Gardens.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','[Deprecated] Speak with Nessa Shadowsong.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26757,'The Bounty of Teldrassil','The fishermen of Rut\'theran village do very well, for the fish here are extremely large and abundant. I would like to compare the bounty here with that of the mainland.$B$BI have a collection of fish bones and scales that I would like taken to a colleague of mine in Darkshore. His name is Laird, he is a fish vendor in the village of Auberdine.$B$BBring my collection to our hippogryph master, Vesprystus, and speak to him about traveling to Auberdine.','Отнесите коллекцию Нессы к Веспристу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','The Bounty of Teldrassil',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','The fishermen of Rut\'theran village do very well, for the fish here are extremely large and abundant. I would like to compare the bounty here with that of the mainland.$B$BI have a collection of fish bones and scales that I would like taken to a colleague of mine in Darkshore. His name is Laird, he is a fish vendor in the village of Auberdine.$B$BBring my collection to our hippogryph master, Vesprystus, and speak to him about traveling to Auberdine.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите коллекцию Нессы к Веспристу.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26758,'Flight to Auberdine','From Rut\'theran, there are two methods of travel to Auberdine: by ferry and by hippogryph. Both are quick and reliable, but if you have not yet flown to Auberdine by hippogryph, then I suggest you do.$B$BIt is sound advice to speak with the hippogryph master in every town that has one. Once you speak to the master, you can then fly there from other towns.$B$BHere is Nessa\'s collection. Speak with me again when you are ready to fly to Auberdine and deliver Nessa\'s collection to Laird.','[Deprecated] Ride a hippogryph to Auberdine from the hippogryph master Vesprystus, then bring Nessa\'s Collection to Laird.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Flight to Auberdine',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','From Rut\'theran, there are two methods of travel to Auberdine: by ferry and by hippogryph. Both are quick and reliable, but if you have not yet flown to Auberdine by hippogryph, then I suggest you do.$B$BIt is sound advice to speak with the hippogryph master in every town that has one. Once you speak to the master, you can then fly there from other towns.$B$BHere is Nessa\'s collection. Speak with me again when you are ready to fly to Auberdine and deliver Nessa\'s collection to Laird.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','[Deprecated] Ride a hippogryph to Auberdine from the hippogryph master Vesprystus, then bring Nessa\'s Collection to Laird.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26759,'Вовращение к Нессе','Надо рассказать об этом Нессе. Она, несомненно, заинтересуется, чем отличаются местные рыбы от тех, что обитают вдоль побережья Тельдрассила. Конечно, мы можем только гадать, чем вызваны эти изменения, но мне кажется, что это само мировое древо влияет на окружающую природу!$B$BПожалуйста, отнеси Нессе мой ответ. Если хочешь, можешь сначала отправиться на гиппогрифе в Рут\'теран, а там поговорить с мастером полетов Кайлаис Лунное Перо. А если желаешь воспользоваться переправой, то с доков регулярно уходит паром на северо-запад.','Отнесите ответ Лайрда Нессе Песня Теней.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вовращение к Нессе',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Надо рассказать об этом Нессе. Она, несомненно, заинтересуется, чем отличаются местные рыбы от тех, что обитают вдоль побережья Тельдрассила. Конечно, мы можем только гадать, чем вызваны эти изменения, но мне кажется, что это само мировое древо влияет на окружающую природу!$B$BПожалуйста, отнеси Нессе мой ответ. Если хочешь, можешь сначала отправиться на гиппогрифе в Рут\'теран, а там поговорить с мастером полетов Кайлаис Лунное Перо. А если желаешь воспользоваться переправой, то с доков регулярно уходит паром на северо-запад.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите ответ Лайрда Нессе Песня Теней.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26760,'Вой на луну','Я не теряю надежды, но давай все же оставаться профессионалами. С ним нужно поступить так, как обычно.$b$bОн пойдет на гильотину... и если алхимия не поможет, ему оттуда никуда не деться. Мы с Трясунчиком будем присутствовать при этом. Пожалуйста, стой позади и смотри с безопасного расстояния.','Понаблюдайте за попыткой Оливера Харриса и Трясунчика вылечить крадущегося воргена.','Получилось… Наконец-то! Не знаю, как и благодарить тебя за то, что дал мне шанс осуществить исцеление.$B$BНаверное, нашему другу не помешает помощь. Возможно, тебе стоит поговорить с ним.','Вернитесь к Оливеру Харрису на Вороний Холм, что в Сумеречном лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вой на луну',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я не теряю надежды, но давай все же оставаться профессионалами. С ним нужно поступить так, как обычно.$b$bОн пойдет на гильотину... и если алхимия не поможет, ему оттуда никуда не деться. Мы с Трясунчиком будем присутствовать при этом. Пожалуйста, стой позади и смотри с безопасного расстояния.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Понаблюдайте за попыткой Оливера Харриса и Трясунчика вылечить крадущегося воргена.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Получилось… Наконец-то! Не знаю, как и благодарить тебя за то, что дал мне шанс осуществить исцеление.$B$BНаверное, нашему другу не помешает помощь. Возможно, тебе стоит поговорить с ним.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Оливеру Харрису на Вороний Холм, что в Сумеречном лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26761,'Угроза королевству','Отчитайтесь мировому судье Соломону в Приозерье.','Я слышал о том, что Братство Справедливости снова активировалось. Я надеялся на новости получше, но оказалось, что Приозерье атакуют! Мы то и дело теряем жителей. Наши собственные войска рассредоточены и не могут взять ситуацию в свои руки. Нам нужен герой, который бы нам помог!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Угроза королевству',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отчитайтесь мировому судье Соломону в Приозерье.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я слышал о том, что Братство Справедливости снова активировалось. Я надеялся на новости получше, но оказалось, что Приозерье атакуют! Мы то и дело теряем жителей. Наши собственные войска рассредоточены и не могут взять ситуацию в свои руки. Нам нужен герой, который бы нам помог!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26762,'Реактивировать боевые создания','Мы отправили к Шлаковому залу много наших боевых созданий, но ни одно из них не вернулось. Мы знаем, что это дело рук каменных троггов.$b$bНас беспокоит то, что мистики будут контролировать создания, используя их против нас, как они уже поступили с грибными великанами.$b$b$n, отправляйся в город каменных троггов и реактивируй создания.','Реактивируйте 5 деактивированных боевых созданий.','Вернитесь к Колчедану Магнетию в Шлаковый зал, что в Подземье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Реактивировать боевые создания',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы отправили к Шлаковому залу много наших боевых созданий, но ни одно из них не вернулось. Мы знаем, что это дело рук каменных троггов.$b$bНас беспокоит то, что мистики будут контролировать создания, используя их против нас, как они уже поступили с грибными великанами.$b$b$n, отправляйся в город каменных троггов и реактивируй создания.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Реактивируйте 5 деактивированных боевых созданий.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Колчедану Магнетию в Шлаковый зал, что в Подземье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26763,'Отлично, эти подойдут. Погоди-ка минутку.$B$B<Кразек бросает камни в котел и трясет его некоторое время.>$B$BНу, вот и готово!','Ну как, удалось добыть кристаллы?','Вернитесь к Кразеку в лагерь экспедиции Эрнестуэя, что в Северной Тернистой долине.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, эти подойдут. Погоди-ка минутку.$B$B<Кразек бросает камни в котел и трясет его некоторое время.>$B$BНу, вот и готово!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как, удалось добыть кристаллы?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кразеку в лагерь экспедиции Эрнестуэя, что в Северной Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (26764,'Новое унижение','Вернитесь к Кразеку в лагерь экспедиции Эрнестуэя, что в Северной Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новое унижение',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кразеку в лагерь экспедиции Эрнестуэя, что в Северной Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26765,'Возвращение к капралу Калебу','Все готово, горшок как новенький. Я еще приспособил к нему свисток, как у чайника, а на дне теперь специальный нож, который режет даже кости!$B$BДа-а, горшки от Кразека – лучшее, о чем могут мечтать повара! Уверен, владельцу все понравится.','Принесите исправный горшок Кразека капралу Калебу в Лагерь Повстанцев в Северной Тернистой долине.','Принесите исправный горшок Кразека капралу Калебу в Лагерь Повстанцев, что в Северной Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение к капралу Калебу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Все готово, горшок как новенький. Я еще приспособил к нему свисток, как у чайника, а на дне теперь специальный нож, который режет даже кости!$B$BДа-а, горшки от Кразека – лучшее, о чем могут мечтать повара! Уверен, владельцу все понравится.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите исправный горшок Кразека капралу Калебу в Лагерь Повстанцев в Северной Тернистой долине.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите исправный горшок Кразека капралу Калебу в Лагерь Повстанцев, что в Северной Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26766,'Большой рыбке большая наживка','У нас будет только одна возможность поймать Абиссия, $n. Давай же не упустим ее.$b$bМы испытаем ловушку на самом большом каменном драконе Алебастрового шельфа.$b$bЧтобы заманить в ловушку каменного матриарха, нам понадобится достаточно большая наживка.$b$bВозьми этот нож и нарежь 5 кусков мяса василиска. Это будет как раз по ее аппетитам.','Воспользуйтесь ножом Милры, чтобы отрезать 5 кусков мяса мертвых нефритобоких василисков.','Ты принесла мясо?','Вернитесь к буревестнице Милре на дозорный холм Сумеречного Молота, что в Подземье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Большой рыбке большая наживка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У нас будет только одна возможность поймать Абиссия, $n. Давай же не упустим ее.$b$bМы испытаем ловушку на самом большом каменном драконе Алебастрового шельфа.$b$bЧтобы заманить в ловушку каменного матриарха, нам понадобится достаточно большая наживка.$b$bВозьми этот нож и нарежь 5 кусков мяса василиска. Это будет как раз по ее аппетитам.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь ножом Милры, чтобы отрезать 5 кусков мяса мертвых нефритобоких василисков.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты принесла мясо?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к буревестнице Милре на дозорный холм Сумеречного Молота, что в Подземье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26767,'Научиться проходить задания','Ура! Ты выполнил задание о хлебных крошках! Теперь разберись, что делать дальше.','Выполнить задание о хлебных крошках.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Научиться проходить задания',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ура! Ты выполнил задание о хлебных крошках! Теперь разберись, что делать дальше.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выполнить задание о хлебных крошках.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`) VALUES (26768,'Поймать дракона','Назначить хранителем фрагмента дракона было неглупым решением со стороны врага. Они могут сделать так, что всякий раз, когда мы приближаемся к фрагменту, он будет от нас удаляться.$b$bИзловить Абиссия будет очень сложно, но у меня есть план, который может помочь.$b$bСектанты Сумеречного Молота используют магические ловушки, чтобы удерживать драконов у земли, пока они забирают их энергию.$b$bЕсли мы сможем заполучить одну из таких ловушек, то у нас получится удерживать дракона столько, сколько нужно.$b$bОтправляйся на восток, на Алебастровый шельф и раздобудь ловушку.','Раздобудьте ловушку для драконов у сумеречных ловцов драконов.','Давай посмотрим, вместит ли эта ловушка что-нибудь покрупнее дракона.','Если эти ловушки подходят для каменных драконов, то и в случае с Абиссием они могут сработать.','Вернитесь к буревестнице Милре на дозорный холм Сумеречного Молота, что в Подземье.','Они пользуются ловушками для поимки каменных драконов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поймать дракона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Назначить хранителем фрагмента дракона было неглупым решением со стороны врага. Они могут сделать так, что всякий раз, когда мы приближаемся к фрагменту, он будет от нас удаляться.$b$bИзловить Абиссия будет очень сложно, но у меня есть план, который может помочь.$b$bСектанты Сумеречного Молота используют магические ловушки, чтобы удерживать драконов у земли, пока они забирают их энергию.$b$bЕсли мы сможем заполучить одну из таких ловушек, то у нас получится удерживать дракона столько, сколько нужно.$b$bОтправляйся на восток, на Алебастровый шельф и раздобудь ловушку.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте ловушку для драконов у сумеречных ловцов драконов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Давай посмотрим, вместит ли эта ловушка что-нибудь покрупнее дракона.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если эти ловушки подходят для каменных драконов, то и в случае с Абиссием они могут сработать.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к буревестнице Милре на дозорный холм Сумеречного Молота, что в Подземье.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Они пользуются ловушками для поимки каменных драконов.',`questgivertextwindow_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26769,'Речная прогулка','Держи свою часть добычи, $n!$B$BНенавижу делиться, но бизнес есть бизнес. Да еще и этот двурушник Котельник заберет 10% сокровища. Кстати, не занесешь ли ему эту посылочку?$B$BОн разбил свой исследовательский лагерь выше по течению реки. Иди на северо-восток от города и найди Хортона Звучного Рога. Скажи ему, что я просил подвезти тебя до места на лодке.','<Котельник выхватывает у вас из рук мешочек с драгоценными камнями.>$B$BИ Газлоу считает, что это мои 10%? Скажи ему, я взвешу все до грамма!$B$BНебось он еще хочет, чтобы я тебе заплатил за доставку? Ладно, ладно... Держи свою долю.','Поговорите с Котельником в Лагере Котельника в Северных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Речная прогулка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Держи свою часть добычи, $n!$B$BНенавижу делиться, но бизнес есть бизнес. Да еще и этот двурушник Котельник заберет 10% сокровища. Кстати, не занесешь ли ему эту посылочку?$B$BОн разбил свой исследовательский лагерь выше по течению реки. Иди на северо-восток от города и найди Хортона Звучного Рога. Скажи ему, что я просил подвезти тебя до места на лодке.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Котельник выхватывает у вас из рук мешочек с драгоценными камнями.>$B$BИ Газлоу считает, что это мои 10%? Скажи ему, я взвешу все до грамма!$B$BНебось он еще хочет, чтобы я тебе заплатил за доставку? Ладно, ладно... Держи свою долю.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Котельником в Лагере Котельника в Северных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26770,'Мистики-властители','Мистики Каменных Игл подчинили себе грибных великанов, выросших в пропасти, там, внизу. А теперь они хотят контролировать и наших боевых созданий.$b$bОтправляйся в Шлаковый зал и сделай что-нибудь! Разве не для этого ты здесь?','Убейте 5 мистиков Каменных Игл.','Вернитесь к Флинту Железной Мантии в Шлаковый зал, что в Подземье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мистики-властители',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мистики Каменных Игл подчинили себе грибных великанов, выросших в пропасти, там, внизу. А теперь они хотят контролировать и наших боевых созданий.$b$bОтправляйся в Шлаковый зал и сделай что-нибудь! Разве не для этого ты здесь?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 5 мистиков Каменных Игл.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Флинту Железной Мантии в Шлаковый зал, что в Подземье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26771,'Испытание ловушки','Теперь тебе нужно установить ловушку для матриарха.$b$bОтправляйся на западный край Алебастрового шельфа и положи мясо василиска в место кормежки.','Положите мясо в западной части Алебастрового шельфа.','Вернитесь к буревестнице Милре на дозорный холм Сумеречного Молота, что в Подземье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Испытание ловушки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь тебе нужно установить ловушку для матриарха.$b$bОтправляйся на западный край Алебастрового шельфа и положи мясо василиска в место кормежки.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Положите мясо в западной части Алебастрового шельфа.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к буревестнице Милре на дозорный холм Сумеречного Молота, что в Подземье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (26772,'Внутреннее зрение','Чтобы узнать Мандокира, нужно увидеть Мандокира.$B$BЧтобы увидеть Мандокира, нужны глаза ящера.$B$BМежду тобой и ящером Оган\'ака, дочерью Оган, установилась связь.$B$BЧтобы укрепить ее, нужны перья.$B$BИди на северо-восток, найдешь перья там, да.','Вернитесь к жрице Тхаалии в форт Ливингстон, что в Северной Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Внутреннее зрение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чтобы узнать Мандокира, нужно увидеть Мандокира.$B$BЧтобы увидеть Мандокира, нужны глаза ящера.$B$BМежду тобой и ящером Оган\'ака, дочерью Оган, установилась связь.$B$BЧтобы укрепить ее, нужны перья.$B$BИди на северо-восток, найдешь перья там, да.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к жрице Тхаалии в форт Ливингстон, что в Северной Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26773,'Увидеть ящера','У тебя есть перья, да.$B$BУ нас есть |3-6($c), да.$B$BПоговори со жрицей, когда будешь $gготов:готова;.','Поговорите со жрицей Тхаалией в форте Ливингстон, чтобы принять участие в ритуале внутреннего зрения.','Вернитесь к жрице Тхаалии в форт Ливингстон, что в Северной Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Увидеть ящера',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У тебя есть перья, да.$B$BУ нас есть |3-6($c), да.$B$BПоговори со жрицей, когда будешь $gготов:готова;.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите со жрицей Тхаалией в форте Ливингстон, чтобы принять участие в ритуале внутреннего зрения.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к жрице Тхаалии в форт Ливингстон, что в Северной Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26774,'Контроль над разумом','Внутреннего зрения мало, да.$B$BКонтроль над разумом – эта магия мощнее, да.$B$BА для сильной магии нужны сильные реагенты. Например, мозг тролля – очень сильный реагент.$B$BБрэддок в Зул\'Мамве, он очень умный, да.$B$BИди на юг, найди Брэддока и вышиби из него большой мозг.','Добудьте большой мозг Брэддока, убив последнего в Зул\'Мамве.','Вернитесь к жрице Тхаалии в форт Ливингстон, что в Северной Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Контроль над разумом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Внутреннего зрения мало, да.$B$BКонтроль над разумом – эта магия мощнее, да.$B$BА для сильной магии нужны сильные реагенты. Например, мозг тролля – очень сильный реагент.$B$BБрэддок в Зул\'Мамве, он очень умный, да.$B$BИди на юг, найди Брэддока и вышиби из него большой мозг.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте большой мозг Брэддока, убив последнего в Зул\'Мамве.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к жрице Тхаалии в форт Ливингстон, что в Северной Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`) VALUES (26775,'Стать ящером','Контроль над разумом. Очень мощный, да.$B$BЕсли повезет, с твоей помощью Оган\'ака сбежит из Зул\'Гуруба.$B$BА потом Оган\'ака опять станет $n\'ака!$B$BПоговори со жрицей, да. И помоги $n\'ака сбежать.','Поговорите со жрицей Тхаалией, а затем помогите пойманному детенышу кнутохвоста сбежать из Зул\'Гуруба.','Вернитесь к жрице Тхаалии в форт Ливингстон, что в Северной Тернистой долине.','В ловушке в Зул\'Гурубе','Оган\'ака','Вернулся из мертвых?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Стать ящером',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Контроль над разумом. Очень мощный, да.$B$BЕсли повезет, с твоей помощью Оган\'ака сбежит из Зул\'Гуруба.$B$BА потом Оган\'ака опять станет $n\'ака!$B$BПоговори со жрицей, да. И помоги $n\'ака сбежать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите со жрицей Тхаалией, а затем помогите пойманному детенышу кнутохвоста сбежать из Зул\'Гуруба.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к жрице Тхаалии в форт Ливингстон, что в Северной Тернистой долине.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','В ловушке в Зул\'Гурубе',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Оган\'ака',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Вернулся из мертвых?',`questturntextwindow_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26776,'Галири','Жрица не очень хорошо всеобщий понимает, да.$B$BМожет, лучше поговорить с Галири, он вон в той палатке.$B$BРасскажи ему, что ты $gвидел:видела; в Зул\'Гурубе, да.','Поговорите с Галири в форте Ливингстон в Северной Тернистой долине.','Вернитесь к Галири в форт Ливингстон, что в Северной Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Галири',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Жрица не очень хорошо всеобщий понимает, да.$B$BМожет, лучше поговорить с Галири, он вон в той палатке.$B$BРасскажи ему, что ты $gвидел:видела; в Зул\'Гурубе, да.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Галири в форте Ливингстон в Северной Тернистой долине.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Галири в форт Ливингстон, что в Северной Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26777,'Успокоение духов','Это печальные земли, их история полна жестокости и отчаяния. Здесь много ходячих мертвецов, но некоторые из них – просто потерянные души, которые бродят в смятении.$b$bОни заслуживают успокоения.$b$bМногие из таких душ собираются в усадьбе Эддла, что к югу отсюда, являясь путникам. Возьми эту святую курильницу. Помаши ею перед неприкаянными духами, и пусть нежный аромат благовоний вернет им покой.','Воспользуйтесь священной курильницей, чтобы успокоить 5 неприкаянных духов в усадьбе Эддла.','Вернитесь к сестре Элсингтон на Вороний Холм, что в Сумеречном лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Успокоение духов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это печальные земли, их история полна жестокости и отчаяния. Здесь много ходячих мертвецов, но некоторые из них – просто потерянные души, которые бродят в смятении.$b$bОни заслуживают успокоения.$b$bМногие из таких душ собираются в усадьбе Эддла, что к югу отсюда, являясь путникам. Возьми эту святую курильницу. Помаши ею перед неприкаянными духами, и пусть нежный аромат благовоний вернет им покой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь священной курильницей, чтобы успокоить 5 неприкаянных духов в усадьбе Эддла.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к сестре Элсингтон на Вороний Холм, что в Сумеречном лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26778,'Крики мертвых','Ты слышишь, $n? Их так много. Они бродят среди могил, шаркая гниющими конечностями по холодной земле.$b$bКрики мертвых раздаются в неподвижном воздухе. Они страдают, будучи в плену у своей собственной плоти, вырванные из сна! Каждую ночь я пробираюсь на кладбище, чтобы успокоить еще кого-то из них, но много ли я могу сделать одна.$b$bПомоги мне, $n. Избавь от страданий вурдалаков, блуждающих по Кладбищу Вороньего Холма. Убей столько, сколько сможешь.','Убейте 20 любых вурдалаков на Кладбище Вороньего Холма.','Вернитесь к сестре Элсингтон на Вороний Холм, что в Сумеречном лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Крики мертвых',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты слышишь, $n? Их так много. Они бродят среди могил, шаркая гниющими конечностями по холодной земле.$b$bКрики мертвых раздаются в неподвижном воздухе. Они страдают, будучи в плену у своей собственной плоти, вырванные из сна! Каждую ночь я пробираюсь на кладбище, чтобы успокоить еще кого-то из них, но много ли я могу сделать одна.$b$bПомоги мне, $n. Избавь от страданий вурдалаков, блуждающих по Кладбищу Вороньего Холма. Убей столько, сколько сможешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 20 любых вурдалаков на Кладбище Вороньего Холма.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к сестре Элсингтон на Вороний Холм, что в Сумеречном лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26779,'Пляски Зул\'Мамве','Дробители Черепов – сущая напасть для всей империи троллей. Их грызня с Кровавыми Скальпами расколола Северную Тернистую долину. Там, где процветают племена Черного Копья и зандалары, Дробители Черепов сражаются за руины.$B$BМне поручено нанять бойцов, способных покарать этих Дробителей Черепов. Я призываю тебя и тех, кого ты знаешь, отправиться на восток в Зул\'Мамве и приструнить воинственное племя.','Убейте 16 троллей из племени Дробителей Черепов в Зул\'Мамве.','Вернитесь к Галири в лагерь Ливингстон, что в Северной Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пляски Зул\'Мамве',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Дробители Черепов – сущая напасть для всей империи троллей. Их грызня с Кровавыми Скальпами расколола Северную Тернистую долину. Там, где процветают племена Черного Копья и зандалары, Дробители Черепов сражаются за руины.$B$BМне поручено нанять бойцов, способных покарать этих Дробителей Черепов. Я призываю тебя и тех, кого ты знаешь, отправиться на восток в Зул\'Мамве и приструнить воинственное племя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 16 троллей из племени Дробителей Черепов в Зул\'Мамве.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Галири в лагерь Ливингстон, что в Северной Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26780,'Ночь в джунглях','Ночь в Тернистой долине – это нечто необыкновенное. В небе полно звезд, а луна светит сквозь листву, прямо сюда... Я могу любоваться этим небом всю ночь напролет.$B$BК сожалению, моему увлечению астрономией мешают тролли, обосновавшиеся в руинах Зул\'Мамве. Они зажигают огни, причем и днем, и ночью, и разгоняют всю темноту.$B$BПрошу тебя, $n... сходи в Зул\'Мамве, это на востоке отсюда, и потуши там огни.','Потушите 8 жаровен в Зул\'Мамве, что в Северной Тернистой долине.','Вот, совсем другое дело. Жду не дождусь ночи, когда я снова смогу вести свои наблюдения!','Вернитесь к Киннелу в форт Ливингстон, что в Северной Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ночь в джунглях',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ночь в Тернистой долине – это нечто необыкновенное. В небе полно звезд, а луна светит сквозь листву, прямо сюда... Я могу любоваться этим небом всю ночь напролет.$B$BК сожалению, моему увлечению астрономией мешают тролли, обосновавшиеся в руинах Зул\'Мамве. Они зажигают огни, причем и днем, и ночью, и разгоняют всю темноту.$B$BПрошу тебя, $n... сходи в Зул\'Мамве, это на востоке отсюда, и потуши там огни.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Потушите 8 жаровен в Зул\'Мамве, что в Северной Тернистой долине.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот, совсем другое дело. Жду не дождусь ночи, когда я снова смогу вести свои наблюдения!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Киннелу в форт Ливингстон, что в Северной Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26781,'Глаз разума','Одно из величайших сокровищ долины совсем близко – на НАШЕЙ стороне водоворота. Огр-маг, живущий на холме Мош\'Огг – это на северо-востоке, – раздобыл где-то Глаз разума. Зовут этого огра Май\'Зот. Насколько мне известно, он довольно злобный и сильный маг.$B$BА если к нему попал Глаз разума, то станет еще могущественнее.$B$BНам никак не удается до него добраться и отнять артефакт. Может, ты попробуешь?','Отберите у Май\'Зота Глаз разума.','Вернитесь к маршалу Ливингстону в форт Ливингстон, что в Северной Тернистой долине.','Май\'Зот хоть и сильный, да трусливый, поэтому он, скорее всего, прячется в самой дальней части пещеры.','Май\'Зот') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Глаз разума',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Одно из величайших сокровищ долины совсем близко – на НАШЕЙ стороне водоворота. Огр-маг, живущий на холме Мош\'Огг – это на северо-востоке, – раздобыл где-то Глаз разума. Зовут этого огра Май\'Зот. Насколько мне известно, он довольно злобный и сильный маг.$B$BА если к нему попал Глаз разума, то станет еще могущественнее.$B$BНам никак не удается до него добраться и отнять артефакт. Может, ты попробуешь?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отберите у Май\'Зота Глаз разума.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к маршалу Ливингстону в форт Ливингстон, что в Северной Тернистой долине.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Май\'Зот хоть и сильный, да трусливый, поэтому он, скорее всего, прячется в самой дальней части пещеры.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Май\'Зот',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26782,'Сокровища клана Мош\'Огг','В лагере мятежников на севере наблюдается оживление. Я сейчас слышал от солдата по имени Нимеза, что $gкакой-то:какая-то:r; |3-6($r)-|3-6($c) $gвыяснил:выяснила;, что так их заботило. Часом не ты?$B$BКак бы то ни было, он прислал мне один образец, по виду камень, каких полно на кургане Мош\'Огг на северо-востоке.$B$BЯ слышал, огры хранят некий ларец в руинах за своим курганом. Мне кажется, тут есть какая-то связь. Не принесешь мне его?','Добудьте сокровища клана Мош\'Огг из руин за курганом.','<Вольфред заглядывает в ларец.>$B$BЭто... это не то, что я ожидал увидеть. Я думал, там будет... будет...$B$B<У него соловеет взгляд.>$B$BКхм! Прости. Не понимаю, что на меня нашло. Отправлю это на юг, на Раскопки Лиги исследователей на мысе. Может, они сообразят, что с этим делать...','Вот почему всегда именно ОГРЫ находят бесценные артефакты?','Вернитесь к Вольфреду Харрису в форт Ливингстон, что в Северной Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сокровища клана Мош\'Огг',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В лагере мятежников на севере наблюдается оживление. Я сейчас слышал от солдата по имени Нимеза, что $gкакой-то:какая-то:r; |3-6($r)-|3-6($c) $gвыяснил:выяснила;, что так их заботило. Часом не ты?$B$BКак бы то ни было, он прислал мне один образец, по виду камень, каких полно на кургане Мош\'Огг на северо-востоке.$B$BЯ слышал, огры хранят некий ларец в руинах за своим курганом. Мне кажется, тут есть какая-то связь. Не принесешь мне его?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте сокровища клана Мош\'Огг из руин за курганом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Вольфред заглядывает в ларец.>$B$BЭто... это не то, что я ожидал увидеть. Я думал, там будет... будет...$B$B<У него соловеет взгляд.>$B$BКхм! Прости. Не понимаю, что на меня нашло. Отправлю это на юг, на Раскопки Лиги исследователей на мысе. Может, они сообразят, что с этим делать...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вот почему всегда именно ОГРЫ находят бесценные артефакты?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Вольфреду Харрису в форт Ливингстон, что в Северной Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26783,'Сокровища клана Мош\'Огг','В лагере мятежников на севере наблюдается оживление. Я сейчас слышал от солдата по имени Нимеза, что $gкакой-то:какая-то:r; |3-6($r)-|3-6($c) $gвыяснил:выяснила;, что так их заботило. Часом не ты?$B$BКак бы то ни было, он прислал мне один образец, по виду камень, каких полно на кургане Мош\'Огг на северо-востоке.$B$BЯ слышал, огры хранят некий ларец в руинах за своим курганом. Мне кажется, тут есть какая-то связь. Не принесешь мне его?','Добудьте сокровища клана Мош\'Огг из руин за курганом.','<Вольфред заглядывает в ларец.>$B$BЭто... это не то, что я ожидал увидеть. Я думал, там будет... будет...$B$B<У него соловеет взгляд.>$B$BКхм! Прости. Не понимаю, что на меня нашло. Отправлю это на юг, на Раскопки Лиги исследователей на мысе. Может, они сообразят, что с этим делать...','И почему именно ограм всегда везет на ценные находки?','Вернитесь к Вольфреду Харрису в форт Ливингстон, что в Северной Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сокровища клана Мош\'Огг',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В лагере мятежников на севере наблюдается оживление. Я сейчас слышал от солдата по имени Нимеза, что $gкакой-то:какая-то:r; |3-6($r)-|3-6($c) $gвыяснил:выяснила;, что так их заботило. Часом не ты?$B$BКак бы то ни было, он прислал мне один образец, по виду камень, каких полно на кургане Мош\'Огг на северо-востоке.$B$BЯ слышал, огры хранят некий ларец в руинах за своим курганом. Мне кажется, тут есть какая-то связь. Не принесешь мне его?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте сокровища клана Мош\'Огг из руин за курганом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Вольфред заглядывает в ларец.>$B$BЭто... это не то, что я ожидал увидеть. Я думал, там будет... будет...$B$B<У него соловеет взгляд.>$B$BКхм! Прости. Не понимаю, что на меня нашло. Отправлю это на юг, на Раскопки Лиги исследователей на мысе. Может, они сообразят, что с этим делать...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','И почему именно ограм всегда везет на ценные находки?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Вольфреду Харрису в форт Ливингстон, что в Северной Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26784,'Мутные воды','$n, на Сумеречном нагорье сильны стихии. Вот почему Сумеречный Молот решил построить свою крепость именно здесь.$B$BМы бы могли направить эту энергию на что-нибудь полезное... например, создать портал, ведущий прямо в Оргриммар.$B$BК северо-западу отсюда, в дельте реки Вералл своими действиями враги пробудили элементалей воды. Уничтожь их и собери 5 сердцевин водоворотов. Этим ты не только успокоишь реку, но и получишь энергию для создания нашего портала.','Убивайте илистых элементалей воды, пока не соберете 5 сердцевин водоворота.','Отлично! Беспокойные воды этой реки могут не только переносить с места на место ил и камни... Они способны перенести и тебя на другой континент!$B$BЗакончи дела в Драконьей Пасти, и тогда мы этим займемся.','Надеюсь, сражаться посреди реки было не слишком опасно.','Отправляйтесь в порт Драконьей Пасти на Сумеречном нагорье и отдайте сердцевины круговоротов Артеш.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мутные воды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, на Сумеречном нагорье сильны стихии. Вот почему Сумеречный Молот решил построить свою крепость именно здесь.$B$BМы бы могли направить эту энергию на что-нибудь полезное... например, создать портал, ведущий прямо в Оргриммар.$B$BК северо-западу отсюда, в дельте реки Вералл своими действиями враги пробудили элементалей воды. Уничтожь их и собери 5 сердцевин водоворотов. Этим ты не только успокоишь реку, но и получишь энергию для создания нашего портала.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убивайте илистых элементалей воды, пока не соберете 5 сердцевин водоворота.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! Беспокойные воды этой реки могут не только переносить с места на место ил и камни... Они способны перенести и тебя на другой континент!$B$BЗакончи дела в Драконьей Пасти, и тогда мы этим займемся.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Надеюсь, сражаться посреди реки было не слишком опасно.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отправляйтесь в порт Драконьей Пасти на Сумеречном нагорье и отдайте сердцевины круговоротов Артеш.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26785,'Часть стаи','Я пытался скрыть свою сущность от жителей Темнолесья... они не жалуют воргенов. Хотя нас здесь, за пределами города, все больше.$b$bМои спутники по первому путешествию ищут в лесах диких воргенов. Они верят, что некоторым из них, отмеченным специальными знаками, еще можно вернуть разум.$b$bЯ не чувствую себя готовым присоединиться к ним. Пожалуйста, извести ученика Фесса о том, что я еще немного побуду в Темнолесье.','Поговорите с учеником Фессом на перекрестке дорог к западу от Темнолесья, что в Сумеречном лесу.','Тобиас хладнокровно остался в городе?$B$BМастер Харрис предостерегал его от повторения судьбы его брата. Сейчас у всех нас в конце концов началась новая жизнь. Но забыть прошлое не так-то просто…') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Часть стаи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я пытался скрыть свою сущность от жителей Темнолесья... они не жалуют воргенов. Хотя нас здесь, за пределами города, все больше.$b$bМои спутники по первому путешествию ищут в лесах диких воргенов. Они верят, что некоторым из них, отмеченным специальными знаками, еще можно вернуть разум.$b$bЯ не чувствую себя готовым присоединиться к ним. Пожалуйста, извести ученика Фесса о том, что я еще немного побуду в Темнолесье.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с учеником Фессом на перекрестке дорог к западу от Темнолесья, что в Сумеречном лесу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тобиас хладнокровно остался в городе?$B$BМастер Харрис предостерегал его от повторения судьбы его брата. Сейчас у всех нас в конце концов началась новая жизнь. Но забыть прошлое не так-то просто…',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26787,'Медвежьи мозги','Боюсь, что... хорошо, я просто боюсь, но я также с сожалением вынужден просить тебя о еще одной услуге.$b$bМастеру Харрису нужны мозги. Медвежьи мозги. Они являются нужным ингредиентом сыворотки, ну или по крайней мере вполне подходящим заменителем.$b$bВ лесах к западу отсюда много черных медведей и вдоль берега реки тоже, но... я не могу сделать это сам! Я слишком боюсь идти туда и противостоять этим огромным зверям, даже с ружьем. Пожалуйста, давай лучше я заплачу тебе, а ты сделаешь это за меня!','Добудьте 8 мозгов черного медведя.','Спасибо. О, спасибо! Никогда не думал, что испытаю такое счастье, почувствовав запах мозгов, но да, я счастлив, что мне не пришлось самому добывать их!$B$BВот твоя награда, как и обещал…','Вернитесь к Трясунчику на Вороний Холм, что в Сумеречном лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Медвежьи мозги',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Боюсь, что... хорошо, я просто боюсь, но я также с сожалением вынужден просить тебя о еще одной услуге.$b$bМастеру Харрису нужны мозги. Медвежьи мозги. Они являются нужным ингредиентом сыворотки, ну или по крайней мере вполне подходящим заменителем.$b$bВ лесах к западу отсюда много черных медведей и вдоль берега реки тоже, но... я не могу сделать это сам! Я слишком боюсь идти туда и противостоять этим огромным зверям, даже с ружьем. Пожалуйста, давай лучше я заплачу тебе, а ты сделаешь это за меня!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 8 мозгов черного медведя.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо. О, спасибо! Никогда не думал, что испытаю такое счастье, почувствовав запах мозгов, но да, я счастлив, что мне не пришлось самому добывать их!$B$BВот твоя награда, как и обещал…',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Трясунчику на Вороний Холм, что в Сумеречном лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26788,'Закрепление успехов','Соберите 10 порций ила из Вералла.','Ил у тебя? Строительство новых стен уже началось!','Отправляйтесь в порт Драконьей Пасти на Сумеречном нагорье и отдайте ил Орнаку.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Закрепление успехов',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 порций ила из Вералла.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ил у тебя? Строительство новых стен уже началось!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отправляйтесь в порт Драконьей Пасти на Сумеречном нагорье и отдайте ил Орнаку.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26789,'You no take axe!','<Name>, we have a problem! I\'ve tracked down the demon-hound Magmadar to this clearing, but when we resting a band of kobolds took our battle axes! I need you to retrieve them, lest Magmadar catch us off guard! Hurry, he could awaken at any moment!','Kill 5 Test Kobolds.','Вернитесь к Траллу в Когтистые горы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','You no take axe!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Name>, we have a problem! I\'ve tracked down the demon-hound Magmadar to this clearing, but when we resting a band of kobolds took our battle axes! I need you to retrieve them, lest Magmadar catch us off guard! Hurry, he could awaken at any moment!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Kill 5 Test Kobolds.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Траллу в Когтистые горы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26790,'Magmadar Must Die!','There he is, <name>. The foolish beast fell asleep right out in the open! Good news for us, eh? Come, hero, we fight now! You can even have the honor of severing his head from his massive body. What\'s that? Too big for your bags? Why, carry it, of course! <Thrall grins.>','Bring Magmadar\'s head to Thrall in Stonetalon Mountains.','Вернитесь к Траллу в Когтистые горы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Magmadar Must Die!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','There he is, <name>. The foolish beast fell asleep right out in the open! Good news for us, eh? Come, hero, we fight now! You can even have the honor of severing his head from his massive body. What\'s that? Too big for your bags? Why, carry it, of course! <Thrall grins.>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Bring Magmadar\'s head to Thrall in Stonetalon Mountains.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Траллу в Когтистые горы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26791,'Больше никакой растительности','Этих грибных чудовищ мистики каменных троггов создают из гигантских грибов, выросших к северу отсюда.$b$bВозьми с собой боевого стража, он поможет тебе разобраться и с грибами, и с каменными троггами. Доберись до гигантских грибов и пометь их. Мы вместе с геомантами сделаем так, что земля поглотит их прежде, чем мистикам удастся завершить свои ритуалы.','Получите боевого стража и уничтожьте с его помощью 5 гигантских грибов.','Больше у них не будет грибных чудовищ, которых они могли бы натравить на нас!','Вернитесь к Сланцу Плывуну в Провал Каменных Игл в Подземье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Больше никакой растительности',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этих грибных чудовищ мистики каменных троггов создают из гигантских грибов, выросших к северу отсюда.$b$bВозьми с собой боевого стража, он поможет тебе разобраться и с грибами, и с каменными троггами. Доберись до гигантских грибов и пометь их. Мы вместе с геомантами сделаем так, что земля поглотит их прежде, чем мистикам удастся завершить свои ритуалы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Получите боевого стража и уничтожьте с его помощью 5 гигантских грибов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Больше у них не будет грибных чудовищ, которых они могли бы натравить на нас!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сланцу Плывуну в Провал Каменных Игл в Подземье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26792,'Грибные чудовища','Возьми боевого стража и уничтожь этих грибных чудовищ.','Уничтожьте 5 грибных чудовищ.','Вернитесь к Сланцу Плывуну в Провал Каменных Игл в Подземье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Грибные чудовища',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Возьми боевого стража и уничтожь этих грибных чудовищ.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 5 грибных чудовищ.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сланцу Плывуну в Провал Каменных Игл в Подземье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26793,'Заброшенная могила','Надпись на замшелом могильном камне гласит:$B$BМОРГАН ЛАДИМОР$b$b<При внимательном рассмотрении вы замечаете, что могилу недавно раскапывали, и большая часть земли насыпана заново...>','Поговорите с Широй Фон-Инди в Темнолесье.','Морган Ладимор?$B$BА-а-а, да, разумеется. У него долгая и печальная история. Я знал его до того, как он ушел на войну, но с тех пор ни разу не видел. Он был добрым и благородным человеком, но окончил свою жизнь плохо.$B$BПодожди-ка, я дам тебе вещь, которая поведает его историю лучше, чем я...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Заброшенная могила',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Надпись на замшелом могильном камне гласит:$B$BМОРГАН ЛАДИМОР$b$b<При внимательном рассмотрении вы замечаете, что могилу недавно раскапывали, и большая часть земли насыпана заново...>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Широй Фон-Инди в Темнолесье.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Морган Ладимор?$B$BА-а-а, да, разумеется. У него долгая и печальная история. Я знал его до того, как он ушел на войну, но с тех пор ни разу не видел. Он был добрым и благородным человеком, но окончил свою жизнь плохо.$B$BПодожди-ка, я дам тебе вещь, которая поведает его историю лучше, чем я...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26794,'Морган Ладимор','<Он роется на полках и вытаскивает книгу в кожаном переплете.>$b$bЕсли хочешь узнать побольше, спроси Алтею, она занималась... проблемами... возникшими с ним в последнее время.','Поговорите с командиром Алтеей Чернодрев в Темнолесье.','Морган Ладимор? Никогда о нем не слышала...$B$BА, ты о Мор\'Ладиме! Ты не знаешь его историю?$B$BЧто ж, я расскажу тебе вкратце. По Сумеречному лесу бродит неупокоенный мертвец, зовущий себя Мор\'Ладимом. Судя по всему, это восставшее из могилы тело Моргана Ладимора, о котором ты, очевидно, уже слышал. Он доставил нам массу неприятностей – начиная от нападения на патрульных и заканчивая убийствами простых людей.$B$B<Она смотрит на вас изучающе.>$B$BКажется, ты смог бы помочь ему упокоиться с миром.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Морган Ладимор',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Он роется на полках и вытаскивает книгу в кожаном переплете.>$b$bЕсли хочешь узнать побольше, спроси Алтею, она занималась... проблемами... возникшими с ним в последнее время.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с командиром Алтеей Чернодрев в Темнолесье.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Морган Ладимор? Никогда о нем не слышала...$B$BА, ты о Мор\'Ладиме! Ты не знаешь его историю?$B$BЧто ж, я расскажу тебе вкратце. По Сумеречному лесу бродит неупокоенный мертвец, зовущий себя Мор\'Ладимом. Судя по всему, это восставшее из могилы тело Моргана Ладимора, о котором ты, очевидно, уже слышал. Он доставил нам массу неприятностей – начиная от нападения на патрульных и заканчивая убийствами простых людей.$B$B<Она смотрит на вас изучающе.>$B$BКажется, ты смог бы помочь ему упокоиться с миром.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (26795,'Мор\'Ладим','Разведчики сообщают, что Мор\'Ладим бродит по Темнолесью, извилистым путем через кладбище. Мы похоронили его за домом на холме, знаешь, где это?$b$bБольше я тебе ничем помочь не могу... Разве что пожелать удачи.','Вернитесь к командиру Алтее Чернодрев в Темнолесье, что в Сумеречном лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мор\'Ладим',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Разведчики сообщают, что Мор\'Ладим бродит по Темнолесью, извилистым путем через кладбище. Мы похоронили его за домом на холме, знаешь, где это?$b$bБольше я тебе ничем помочь не могу... Разве что пожелать удачи.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру Алтее Чернодрев в Темнолесье, что в Сумеречном лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26796,'Выжившая дочь','Надо было рассказать тебе раньше...$b$bКак бы тебе сказать...$b$bМорган думал, что вся его семья погибла, но его дочь, Сара Ладимор, жива и служит дозорным. Ее всегда беспокоили... обстоятельства... связанные с гибелью ее отца. Быть может, ты сообщишь ей о случившемся.','Поговорите с дозорным Сарой Ладимор в Темнолесье.','Да? Мой отец…$B$B<Она опускает глаза.>$B$BЖаль... что я не могу ничего для него сделать... Ах, если бы я поговорила с ним до того, как...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Выжившая дочь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Надо было рассказать тебе раньше...$b$bКак бы тебе сказать...$b$bМорган думал, что вся его семья погибла, но его дочь, Сара Ладимор, жива и служит дозорным. Ее всегда беспокоили... обстоятельства... связанные с гибелью ее отца. Быть может, ты сообщишь ей о случившемся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с дозорным Сарой Ладимор в Темнолесье.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да? Мой отец…$B$B<Она опускает глаза.>$B$BЖаль... что я не могу ничего для него сделать... Ах, если бы я поговорила с ним до того, как...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26797,'Дочерняя любовь','Возьми это кольцо и отнеси на его могилу. Может быть... может быть, он поймет, что я жива и что никто не винит его в случившемся.$b$b<Со слезами на глазах она снимает кольцо с правой руки и вкладывает его вам в руки.>$b$bИ... спасибо, $n.','Отнесите кольцо Сары Ладимор на могилу Моргана Ладимора.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дочерняя любовь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Возьми это кольцо и отнеси на его могилу. Может быть... может быть, он поймет, что я жива и что никто не винит его в случившемся.$b$b<Со слезами на глазах она снимает кольцо с правой руки и вкладывает его вам в руки.>$b$bИ... спасибо, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите кольцо Сары Ладимор на могилу Моргана Ладимора.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (26798,'Разбойник, ты только что из Драконьей Пасти. Значит, портал открыт? Отлично.$B$BНо прежде чем ты вернешься к работе, нам нужно разобраться с одним грязным делом...') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Разбойник, ты только что из Драконьей Пасти. Значит, портал открыт? Отлично.$B$BНо прежде чем ты вернешься к работе, нам нужно разобраться с одним грязным делом...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26799,'Те, кого уже не спасти','Каждый день валь\'киры поднимают из могил сотни тел. Агата только что оживила тебя. Но не всем так повезло.$b$bНекоторым удается сохранить свободу воли, но они живут в постоянном страхе и смятении. Обычно они убегают в леса, боясь даже собственной тени.$b$bДругие полностью теряют разум и бесцельно слоняются по округе. Они часто начинают вести себя жестоко и поэтому должны быть уничтожены.$b$bЭто и есть твое задание, $n. Убей их, даже несмотря на то, что это твои бывшие собратья.','Убейте 6 безмозглых зомби.','Даже силы валь\'кир недостаточно для того, чтобы спасти их. Они были обречены с самого начала.$b$bУ меня кое-что есть для тебя, $n. Тут немного, но это тебе пригодится.','Вернитесь к гробовщику Мордо в Похоронный Звон, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Те, кого уже не спасти',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Каждый день валь\'киры поднимают из могил сотни тел. Агата только что оживила тебя. Но не всем так повезло.$b$bНекоторым удается сохранить свободу воли, но они живут в постоянном страхе и смятении. Обычно они убегают в леса, боясь даже собственной тени.$b$bДругие полностью теряют разум и бесцельно слоняются по округе. Они часто начинают вести себя жестоко и поэтому должны быть уничтожены.$b$bЭто и есть твое задание, $n. Убей их, даже несмотря на то, что это твои бывшие собратья.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 6 безмозглых зомби.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Даже силы валь\'кир недостаточно для того, чтобы спасти их. Они были обречены с самого начала.$b$bУ меня кое-что есть для тебя, $n. Тут немного, но это тебе пригодится.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к гробовщику Мордо в Похоронный Звон, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26800,'Вербовка','Мы доставляем мертвые тела из Серебряного бора, Хилсбрада... да отовсюду, где их можно достать. Мы не собираемся проходить мимо тел, которые так и просятся в наши руки.$b$bПо Тирисфальским лесами бродят те, кто остался от Алого ордена. Хоть мы и выбили их из Похоронного Звона, в некоторых домах к северной и южной части деревни все еще остались тела.$b$bИди туда, найди эти тела. И возьми с собой Дарнелла. С виду он крепкий, сможет донести несколько тел.','Обыщите Похоронный Звон и его окрестности, найдите 6 тел рыцарей Алого ордена и укажите на них Дарнеллу, чтобы он мог их собрать.','Очень хорошо, $n, я так и думал, что ты не совсем бесполезное существо.$b$bА это тебе – одна из лучших вещичек среди тех, что мы собрали.','Вернитесь к стражу смерти Салтену в Похоронный Звон, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вербовка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы доставляем мертвые тела из Серебряного бора, Хилсбрада... да отовсюду, где их можно достать. Мы не собираемся проходить мимо тел, которые так и просятся в наши руки.$b$bПо Тирисфальским лесами бродят те, кто остался от Алого ордена. Хоть мы и выбили их из Похоронного Звона, в некоторых домах к северной и южной части деревни все еще остались тела.$b$bИди туда, найди эти тела. И возьми с собой Дарнелла. С виду он крепкий, сможет донести несколько тел.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обыщите Похоронный Звон и его окрестности, найдите 6 тел рыцарей Алого ордена и укажите на них Дарнеллу, чтобы он мог их собрать.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Очень хорошо, $n, я так и думал, что ты не совсем бесполезное существо.$b$bА это тебе – одна из лучших вещичек среди тех, что мы собрали.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к стражу смерти Салтену в Похоронный Звон, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26801,'Плеть вокруг','Если ты хочешь показать Отрекшимся, что чего-то стоишь, тебе нужно научиться драться. И нет для этого лучшей цели, чем приспешники Плети, которые продолжают донимать нас.$b$bНапример, презренные вурдалаки и скелеты-костетрясы, в прошлом составлявшие войска Плети, которые бродят к северу и востоку отсюда. Это отличная тренировка для $gнеопытного:неопытной:c; |3-1($c) вроде тебя.$b$bНе мешкай. А когда закончишь, снова поговори со мной.','Убейте 8 скелетов-костетрясов или презренных вурдалаков в Похоронном Звоне.','Вернитесь к жрецу Тени Сарвису в Похоронный Звон, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Плеть вокруг',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если ты хочешь показать Отрекшимся, что чего-то стоишь, тебе нужно научиться драться. И нет для этого лучшей цели, чем приспешники Плети, которые продолжают донимать нас.$b$bНапример, презренные вурдалаки и скелеты-костетрясы, в прошлом составлявшие войска Плети, которые бродят к северу и востоку отсюда. Это отличная тренировка для $gнеопытного:неопытной:c; |3-1($c) вроде тебя.$b$bНе мешкай. А когда закончишь, снова поговори со мной.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 скелетов-костетрясов или презренных вурдалаков в Похоронном Звоне.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к жрецу Тени Сарвису в Похоронный Звон, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26802,'Проклятые','Во-первых, посмотри на свои доспехи. Ну на кого ты $gпохож:похожа:c;, |3-6($c).$b$bЕсли хочешь остаться $gцелым и невредимым:целой и невредимой; – а ты, думаю, хочешь – возможно, я смогу тебе помочь. У меня заканчиваются запасы лап и крыльев, и если ты принесешь мне немного, я найду для тебя какой-нибудь доспех. К северу и западу отсюда волков и летучих мышей предостаточно.','Раздобудьте 4 лапы падальщика и 4 крыла сумеречницы.','Спасибо, $n. Держи этот доспех.$b$bНадеюсь, тебе он послужит лучше, чем тому бедолаге, что носил его последним…','Постарайся остаться $gневредимым:невредимой;, пока я не найду для тебя каких-нибудь доспехов.','Вернитесь к новобранцу Элрет в Похоронный Звон в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Проклятые',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Во-первых, посмотри на свои доспехи. Ну на кого ты $gпохож:похожа:c;, |3-6($c).$b$bЕсли хочешь остаться $gцелым и невредимым:целой и невредимой; – а ты, думаю, хочешь – возможно, я смогу тебе помочь. У меня заканчиваются запасы лап и крыльев, и если ты принесешь мне немного, я найду для тебя какой-нибудь доспех. К северу и западу отсюда волков и летучих мышей предостаточно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте 4 лапы падальщика и 4 крыла сумеречницы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо, $n. Держи этот доспех.$b$bНадеюсь, тебе он послужит лучше, чем тому бедолаге, что носил его последним…',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Постарайся остаться $gневредимым:невредимой;, пока я не найду для тебя каких-нибудь доспехов.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к новобранцу Элрет в Похоронный Звон в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26803,'Недостающие рапорты','Поговорите с Дорасом, хозяином ветрокрылов в Оргриммаре.','Спешишь к Колючему Холму, значит? Проще простого. Мой ветрокрыл доставит туда в два счета, и обойдется это тебе всего в несколько монет.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Недостающие рапорты',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Дорасом, хозяином ветрокрылов в Оргриммаре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спешишь к Колючему Холму, значит? Проще простого. Мой ветрокрыл доставит туда в два счета, и обойдется это тебе всего в несколько монет.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26804,'Перелет в Колючий Холм','Обратитесь к Дорасу, чтобы добраться на ветрокрыле до Колючего Холма. По прибытии разыщите Га\'тока.','Тебя послал Эйтригг? Вождю, видно, не терпится получить мои рапорты. Я бы давным-давно их отправил, но каждый день поступают новые сведения о планах Альянса по вторжению в Дуротар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Перелет в Колючий Холм',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обратитесь к Дорасу, чтобы добраться на ветрокрыле до Колючего Холма. По прибытии разыщите Га\'тока.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебя послал Эйтригг? Вождю, видно, не терпится получить мои рапорты. Я бы давным-давно их отправил, но каждый день поступают новые сведения о планах Альянса по вторжению в Дуротар.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (26805,'На мыс!','Лига исследователей растет, $n. Они не только принимают в свои ряды воргенов вроде меня, но и постоянно расширяют ареал поисков артефактов. Один из наших лучших товарищей, Бронвин Зарубай, разбил лагерь на юге, где, как он думает, может находиться предмет, созданный еще титанами.$B$BБронвин попросил меня тут на севере выполнять кое-какие обязанности – например, подбирать для него новобранцев. Мне кажется, ты отлично подойдешь. Поговори с распорядителем полетов Робертом Родсом, и он отправит тебя туда. Бронвин обрадуется.','У Вольфреда острый глаз. Мне кажется, тебе самое место в нашем лагере.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На мыс!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Лига исследователей растет, $n. Они не только принимают в свои ряды воргенов вроде меня, но и постоянно расширяют ареал поисков артефактов. Один из наших лучших товарищей, Бронвин Зарубай, разбил лагерь на юге, где, как он думает, может находиться предмет, созданный еще титанами.$B$BБронвин попросил меня тут на севере выполнять кое-какие обязанности – например, подбирать для него новобранцев. Мне кажется, ты отлично подойдешь. Поговори с распорядителем полетов Робертом Родсом, и он отправит тебя туда. Бронвин обрадуется.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','У Вольфреда острый глаз. Мне кажется, тебе самое место в нашем лагере.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (26806,'Рапорты в Оргриммар','Придется Эйтриггу довольствоваться той частью рапорта, которую я успел подготовить. Скажи ему, что скоро будет еще.$B$B<Га\'ток вручает вам кипу небрежно сложенных листов.>$B$BЗдесь изложены ключевые сведения об усилении группировки Альянса в Северной Страже. Передай Эйтриггу мои извинения и скажи, что мы тут из кожи вон лезем, чтобы защитить Колючий Холм и обеспечить снабжение. Когда будешь $gготов:готова; отправиться обратно в Оргриммар, поговори с Буроком – он даст тебе ветрокрыла.','Готов доставить в Оргриммар это донесение? Могу организовать перелет в любую минуту.','Готов к возвращению в Оргриммар?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рапорты в Оргриммар',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Придется Эйтриггу довольствоваться той частью рапорта, которую я успел подготовить. Скажи ему, что скоро будет еще.$B$B<Га\'ток вручает вам кипу небрежно сложенных листов.>$B$BЗдесь изложены ключевые сведения об усилении группировки Альянса в Северной Страже. Передай Эйтриггу мои извинения и скажи, что мы тут из кожи вон лезем, чтобы защитить Колючий Холм и обеспечить снабжение. Когда будешь $gготов:готова; отправиться обратно в Оргриммар, поговори с Буроком – он даст тебе ветрокрыла.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Готов доставить в Оргриммар это донесение? Могу организовать перелет в любую минуту.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Готов к возвращению в Оргриммар?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (26807,'Назад к Эйтриггу','<Эйтригг внимательно изучает рапорт.>$B$BАльянс совсем зарвался! Я немедленно обсужу с вождем отправку подкрепления. Спасибо за такую быструю доставку рапорта. Надеюсь, этого хватит, чтобы покрыть транспортные издержки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Назад к Эйтриггу',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Эйтригг внимательно изучает рапорт.>$B$BАльянс совсем зарвался! Я немедленно обсужу с вождем отправку подкрепления. Спасибо за такую быструю доставку рапорта. Надеюсь, этого хватит, чтобы покрыть транспортные издержки.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (26808,'Мейвики','<Линзи явно встревожена.>$B$BЗнаешь, там тролльша. Прячется за той грудой коробок. Похоже, она очень сильно расстроена. Не выходит, не хочет ни с кем разговаривать.$B$B<Линзи заворачивает в платок несколько стеблей акириса.>$B$BВот, передай ей. Они очень мягкие. Может быть, это хоть чуточку ее утешит.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мейвики',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Линзи явно встревожена.>$B$BЗнаешь, там тролльша. Прячется за той грудой коробок. Похоже, она очень сильно расстроена. Не выходит, не хочет ни с кем разговаривать.$B$B<Линзи заворачивает в платок несколько стеблей акириса.>$B$BВот, передай ей. Они очень мягкие. Может быть, это хоть чуточку ее утешит.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26809,'Тайные сделки','Занзил Отверженный, изгнанник племени Гурубаши, сейчас в моей каменоломне. Братья с севера сказали мне, что Занзил хочет вернуться и уже отправил своего посланника к Дробителям Черепов. Плохая новость.$B$BВыведай планы Занзила. Возьми эти благовония и положи напротив тотема летучей мыши в Руинах Жубуваля на севере. Далее тебе все расскажет Хир\'ик.','Положите благовония Гурубаши напротив тотема Хир\'ика и выведайте планы Занзила.','Так я и думала. Занзил слишком высокого о себе мнения, чтобы впутываться в дрязги между Кровавым Скальпом и Дробителями черепов. Нет, у него планы помасштабнее... Мастер проклятий Джин\'до хочет с его помощью вернуть Хаккара в Зул\'Гуруб.$B$BХорошо, что мы узнали об этом сейчас. Теперь ясно, как нужно действовать.','Вернитесь к Мейвики, находящейся на Раскопках Лиги исследователей на мысе Тернистой долины.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тайные сделки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Занзил Отверженный, изгнанник племени Гурубаши, сейчас в моей каменоломне. Братья с севера сказали мне, что Занзил хочет вернуться и уже отправил своего посланника к Дробителям Черепов. Плохая новость.$B$BВыведай планы Занзила. Возьми эти благовония и положи напротив тотема летучей мыши в Руинах Жубуваля на севере. Далее тебе все расскажет Хир\'ик.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Положите благовония Гурубаши напротив тотема Хир\'ика и выведайте планы Занзила.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так я и думала. Занзил слишком высокого о себе мнения, чтобы впутываться в дрязги между Кровавым Скальпом и Дробителями черепов. Нет, у него планы помасштабнее... Мастер проклятий Джин\'до хочет с его помощью вернуть Хаккара в Зул\'Гуруб.$B$BХорошо, что мы узнали об этом сейчас. Теперь ясно, как нужно действовать.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мейвики, находящейся на Раскопках Лиги исследователей на мысе Тернистой долины.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (26810,'Убить Отверженного','Ты $gдолжен:должна; убить Занзила. Ты $gлетал:летала; на крыльях Хир\'ика и $gсмотрел:смотрела; его глазами, значит, тебе известно, где именно в руинах Абораза укрывается Занзил. Отправляйся туда и убей его.$B$BДа, и еще: если мы потеряемся, воспользуйся этим фетишем. Он действует только в Тернистой долине, но если понадобится, то мгновенно перенесет тебя сюда.$B$BУдачи, |3-6($r). Занзил сильный соперник.','Отправляйтесь в руины Абораза, что на мысе Тернистой долины, и убейте Занзила Отверженного.','Время, когда он занимался зельями, подходит к концу.','Занзил Отверженный','Куда он исчез?','Занзил Отверженный') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Убить Отверженного',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gдолжен:должна; убить Занзила. Ты $gлетал:летала; на крыльях Хир\'ика и $gсмотрел:смотрела; его глазами, значит, тебе известно, где именно в руинах Абораза укрывается Занзил. Отправляйся туда и убей его.$B$BДа, и еще: если мы потеряемся, воспользуйся этим фетишем. Он действует только в Тернистой долине, но если понадобится, то мгновенно перенесет тебя сюда.$B$BУдачи, |3-6($r). Занзил сильный соперник.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в руины Абораза, что на мысе Тернистой долины, и убейте Занзила Отверженного.',`objectives_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Время, когда он занимался зельями, подходит к концу.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Занзил Отверженный',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Куда он исчез?',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Занзил Отверженный',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (26811,'Троллья дыра','Похоже, портал Занзила в Зул\'Гуруб до сих пор открыт. Зул\'Гуруб – место очень опасное, но Мейвики доверила это задание именно тебе.$B$BПортал расположен прямо перед тобой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Троллья дыра',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Похоже, портал Занзила в Зул\'Гуруб до сих пор открыт. Зул\'Гуруб – место очень опасное, но Мейвики доверила это задание именно тебе.$B$BПортал расположен прямо перед тобой.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26812,'Верховная жрица Джеклик','Перед вами возвышается пандус, ведущий на одну из множества городских террас. Виднеющиеся впереди тотемы-нетопыри указывают, что это владения верховной жрицы Джеклик, поклонницы Хир\'ика.$B$BДжеклик была одной из жриц, поклонявшихся Хаккару, которых хотел воскресить Занзил. Возможно, если вы поспешите, то сумеете этому помешать!','Последовательница Хир\'ика, покровителя летучих мышей.','Верховная жрица Джеклик') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Верховная жрица Джеклик',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Перед вами возвышается пандус, ведущий на одну из множества городских террас. Виднеющиеся впереди тотемы-нетопыри указывают, что это владения верховной жрицы Джеклик, поклонницы Хир\'ика.$B$BДжеклик была одной из жриц, поклонявшихся Хаккару, которых хотел воскресить Занзил. Возможно, если вы поспешите, то сумеете этому помешать!',`details_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Последовательница Хир\'ика, покровителя летучих мышей.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Верховная жрица Джеклик',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (26813,'Путешествие в Зул\'Гуруб','Занзил Отверженный снова скрылся. Видимо, не без помощи одного из своих порталов. Ступай за ним!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путешествие в Зул\'Гуруб',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Занзил Отверженный снова скрылся. Видимо, не без помощи одного из своих порталов. Ступай за ним!',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26815,'Тайна Занзила','Давным-давно Гурубаши изгнали из Зул\'Гуруба своего соплеменника – тролля по имени Занзил. По какой причине – неизвестно, но могу предположить, что это было связано с его привычкой давать всем подряд свои сильнодействующие лекарства, влияющие на поведение. Вскоре жрецы Гурубаши и их кровожадный бог были свергнуты, а Занзил Отверженный жив до сих пор.$B$BА с ним и его лекарства.$B$BМне для дальнейшей работы нужна смесь Занзила. Отправляйся на север к зомби.','Добудьте 5 сосудов со смесью Занзила.','<Даск внимательно рассматривает содержимое сосуда.>$B$BЭта смесь просто... великолепна! Посмотрим, что она сделает с этим артефактом Титанов!','Замечательно... И ты не стал зомби. Это хорошо.$B$BА, ну-у... Ладно. Просто... Есть риск заражения. Я разве тебя не предупредил?','Вернитесь к Даску "Пузырю" Гоблопшику на Раскопки Лиги исследователей, что на мысу Тернистой долины.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тайна Занзила',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Давным-давно Гурубаши изгнали из Зул\'Гуруба своего соплеменника – тролля по имени Занзил. По какой причине – неизвестно, но могу предположить, что это было связано с его привычкой давать всем подряд свои сильнодействующие лекарства, влияющие на поведение. Вскоре жрецы Гурубаши и их кровожадный бог были свергнуты, а Занзил Отверженный жив до сих пор.$B$BА с ним и его лекарства.$B$BМне для дальнейшей работы нужна смесь Занзила. Отправляйся на север к зомби.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 5 сосудов со смесью Занзила.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Даск внимательно рассматривает содержимое сосуда.>$B$BЭта смесь просто... великолепна! Посмотрим, что она сделает с этим артефактом Титанов!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Замечательно... И ты не стал зомби. Это хорошо.$B$BА, ну-у... Ладно. Просто... Есть риск заражения. Я разве тебя не предупредил?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Даску "Пузырю" Гоблопшику на Раскопки Лиги исследователей, что на мысу Тернистой долины.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26816,'Рецепт катастрофы','$GВидал:Видала;, какой был взрыв? Меня дюймов на десять над землей подбросило!$B$BТак, нужно взглянуть на рецепт Занзила и разобраться, почему это произошло. Наверняка у кого-нибудь из Занзиловых лакеев в руинах Абораза есть рецепт. Отправляйся на восток, к побережью, и добудь его мне!','Раздобудьте рецептуру Занзила у одного из приспешников Занзила в руинах Абораза.','Поразительно! Только представь, сколько еще этому можно найти применений!$B$BЕще раз спасибо, Турбомажка. Если тебе нужно будет что-нибудь смешать – ЧТО УГОДНО – ты всегда можешь обратиться к Склянке.','Неужели он добавил звездолист? Точно ведь... $B$BНет, погоди... Янтарные желуди! Наверняка все дело в них.','Вернитесь к Даску "Пузырю" Гоблопшику на Раскопки Лиги исследователей, что на мысу Тернистой долины.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рецепт катастрофы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$GВидал:Видала;, какой был взрыв? Меня дюймов на десять над землей подбросило!$B$BТак, нужно взглянуть на рецепт Занзила и разобраться, почему это произошло. Наверняка у кого-нибудь из Занзиловых лакеев в руинах Абораза есть рецепт. Отправляйся на восток, к побережью, и добудь его мне!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте рецептуру Занзила у одного из приспешников Занзила в руинах Абораза.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Поразительно! Только представь, сколько еще этому можно найти применений!$B$BЕще раз спасибо, Турбомажка. Если тебе нужно будет что-нибудь смешать – ЧТО УГОДНО – ты всегда можешь обратиться к Склянке.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Неужели он добавил звездолист? Точно ведь... $B$BНет, погоди... Янтарные желуди! Наверняка все дело в них.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Даску "Пузырю" Гоблопшику на Раскопки Лиги исследователей, что на мысу Тернистой долины.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26817,'Идеальная чистота','Одной телесной жидкости не хватит. Слишком уж она густая, СЛИШКОМ.$B$BНа западе живут наги, там у них есть святилище, откуда поступает единственная в Сумеречном лесу чистая вода. Для большинства зелий мне хватает и речной воды, но Бронвин, видишь ли, требует точности!$B$BТак что набери мне воды из родника Нек\'мани, он в самом верху лагеря наг. Удачи тебе!','Наберите святой воды ясности из родника Нек\'мани на мысе Тернистой долины.','Ты не представляешь, как трудно найти пресную воду в Тернистой долине! Неудивительно, что наги так ревностно охраняют свое святилище!$B$BТак, ладно, начнем кашеварить!','<Даск с нетерпением смотрит на вашу сумку.>','Вернитесь к Даску "Пузырю" Гоблопшику на Раскопки Лиги исследователей, что на мысу Тернистой долины.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Идеальная чистота',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Одной телесной жидкости не хватит. Слишком уж она густая, СЛИШКОМ.$B$BНа западе живут наги, там у них есть святилище, откуда поступает единственная в Сумеречном лесу чистая вода. Для большинства зелий мне хватает и речной воды, но Бронвин, видишь ли, требует точности!$B$BТак что набери мне воды из родника Нек\'мани, он в самом верху лагеря наг. Удачи тебе!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Наберите святой воды ясности из родника Нек\'мани на мысе Тернистой долины.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты не представляешь, как трудно найти пресную воду в Тернистой долине! Неудивительно, что наги так ревностно охраняют свое святилище!$B$BТак, ладно, начнем кашеварить!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Даск с нетерпением смотрит на вашу сумку.>',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Даску "Пузырю" Гоблопшику на Раскопки Лиги исследователей, что на мысу Тернистой долины.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26818,'Мягкие шкуры','Здравствуй, я местная торговка, дочь Бронвина!$B$BПрости, конечно, нельзя быть такой эмоциональной – отец говорит, это непрофессионально.$B$BЛюди покупают у меня жесткую кожу и грубые шкуры, а по-моему, им пришлись бы по душе и более нежные материалы... Такие, как тигриный мех, к примеру! Может, добудешь его мне?$B$BЗдесь неподалеку водятся пантеры, а если захочешь поохотиться на крупных тигров, придется отправиться на северо-запад... На север от этой огромной арены троллей.','Добудьте 4 мягких тигриных шкуры и 4 бархатистых шкуры пантеры.','<Линзи ощупывает шкуры и улыбается.>$B$BКакие мягкие и пушистые! Покупатели придут в восторг!','О-о... Надеюсь, они достаточно мягкие!','Вернитесь к Линзи Зарубай на Раскопках Лиги исследователей, что на мысу Тернистой долины.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мягкие шкуры',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Здравствуй, я местная торговка, дочь Бронвина!$B$BПрости, конечно, нельзя быть такой эмоциональной – отец говорит, это непрофессионально.$B$BЛюди покупают у меня жесткую кожу и грубые шкуры, а по-моему, им пришлись бы по душе и более нежные материалы... Такие, как тигриный мех, к примеру! Может, добудешь его мне?$B$BЗдесь неподалеку водятся пантеры, а если захочешь поохотиться на крупных тигров, придется отправиться на северо-запад... На север от этой огромной арены троллей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 4 мягких тигриных шкуры и 4 бархатистых шкуры пантеры.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Линзи ощупывает шкуры и улыбается.>$B$BКакие мягкие и пушистые! Покупатели придут в восторг!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','О-о... Надеюсь, они достаточно мягкие!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Линзи Зарубай на Раскопках Лиги исследователей, что на мысу Тернистой долины.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26819,'Вязанка акириса','К западу от нас наги-исследователи добывают ценные океанские водоросли – акирис. Из них делают лекарства и припарки, а мастера подбивают ими доспехи или даже крутят из них сигары!$B$BПо вечерам, когда мы заканчивали копку, отец учил меня работать с акирисом... но, увы, он у нас весь вышел. Ты не добудешь нам еще немного?','Добыть 6 стеблей акириса у наг-исследователей.','Ура! Мы так давно не видели акириса!','С возвращением!','Вернитесь к Линзи Зарубай в лагерь Лиги исследователей на мыс Тернистой долины.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вязанка акириса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','К западу от нас наги-исследователи добывают ценные океанские водоросли – акирис. Из них делают лекарства и припарки, а мастера подбивают ими доспехи или даже крутят из них сигары!$B$BПо вечерам, когда мы заканчивали копку, отец учил меня работать с акирисом... но, увы, он у нас весь вышел. Ты не добудешь нам еще немного?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добыть 6 стеблей акириса у наг-исследователей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ура! Мы так давно не видели акириса!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','С возвращением!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Линзи Зарубай в лагерь Лиги исследователей на мыс Тернистой долины.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26820,'Если они собираются просто оставить это на земле...','Отец говорит, ответственный торговец тот, кто всегда ищет способ заключить новую выгодную сделку. Я чуть голову не сломала в поисках новой возможности обогатиться – и, кажется, нашла!$B$BНа западе обитают наги. Рядом со своими жилищами они устанавливают статуи. Десятки статуй. Наверняка им далеко не все нужны... Поэтому, я думаю, мы несколько штук вполне можем себе забрать!$B$BБесплатные статуи! Дело выгоднее некуда, скажи?','Добудьте 6 нагских идолов с Южного Гибельного Берега на мысе Тернистой долины.','Эти статуи прекрасны...$B$BНу и ну, а я и не знала, что эти наги такие мастера! Спасибо, Турбомажка!','Покажи-ка их!','Вернитесь к Линзи Зарубай на Раскопках Лиги исследователей, что на мысу Тернистой долины.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Если они собираются просто оставить это на земле...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Отец говорит, ответственный торговец тот, кто всегда ищет способ заключить новую выгодную сделку. Я чуть голову не сломала в поисках новой возможности обогатиться – и, кажется, нашла!$B$BНа западе обитают наги. Рядом со своими жилищами они устанавливают статуи. Десятки статуй. Наверняка им далеко не все нужны... Поэтому, я думаю, мы несколько штук вполне можем себе забрать!$B$BБесплатные статуи! Дело выгоднее некуда, скажи?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 6 нагских идолов с Южного Гибельного Берега на мысе Тернистой долины.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Эти статуи прекрасны...$B$BНу и ну, а я и не знала, что эти наги такие мастера! Спасибо, Турбомажка!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Покажи-ка их!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Линзи Зарубай на Раскопках Лиги исследователей, что на мысу Тернистой долины.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26821,'Айрвин Куропуша','Не имеем ни малейшего понятия, что это за артефакт. Он старый, даже древний, но сработан не титанами. Просто ума не приложу...$B$BАйрвин Куропуша в Пиратской Бухте – моя непосредственная начальница. Нужно известить ее об этой находке. Ты не $gмог:могла; бы отнести это ей?','Отнесите открытый сундук сокровищ клана Мош\'Огг Айрвин Куропуше в Пиратскую Бухту, находящуюся на мысе Тернистой долины.','Потрясающе!$B$BМне потребуется время, чтобы это изучить. Ты, может, пойдешь прогуляешься по Пиратской Бухте и зайдешь попозже?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Айрвин Куропуша',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не имеем ни малейшего понятия, что это за артефакт. Он старый, даже древний, но сработан не титанами. Просто ума не приложу...$B$BАйрвин Куропуша в Пиратской Бухте – моя непосредственная начальница. Нужно известить ее об этой находке. Ты не $gмог:могла; бы отнести это ей?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите открытый сундук сокровищ клана Мош\'Огг Айрвин Куропуше в Пиратскую Бухту, находящуюся на мысе Тернистой долины.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Потрясающе!$B$BМне потребуется время, чтобы это изучить. Ты, может, пойдешь прогуляешься по Пиратской Бухте и зайдешь попозже?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26822,'Шавки паршивые','Кхм!.. Хм-хм...$B$B<Дворф несколько секунд прокашливается.>$B$BТы работенку ищешь, да? И спрашиваешь про это МЕНЯ? Бедного старикашку Гориса?!$B$BНу, гм... это ж в первый раз такое. Ага, вот!$B$BТута долина есть на севере, так там кишмя кишат гнусные, брюхастые василиски. От них толку никакого, а еще говорят, они всех в каменюки превращают.$B$BЕжели ты их перебьешь, я тебе от щедрот своих отвалю.','Уничтожьте 12 василисков-хвостохлестов или железозубых василисков.','Кхм! А-а-а... ну...$B$BХорошая работа! Поздравляю, то есть спасибо, что всех перебил.$B$BВот, держи.','Вернитесь к Горису на Раскопки Лиги исследователей на мысе Тернистой долины.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Шавки паршивые',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кхм!.. Хм-хм...$B$B<Дворф несколько секунд прокашливается.>$B$BТы работенку ищешь, да? И спрашиваешь про это МЕНЯ? Бедного старикашку Гориса?!$B$BНу, гм... это ж в первый раз такое. Ага, вот!$B$BТута долина есть на севере, так там кишмя кишат гнусные, брюхастые василиски. От них толку никакого, а еще говорят, они всех в каменюки превращают.$B$BЕжели ты их перебьешь, я тебе от щедрот своих отвалю.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 12 василисков-хвостохлестов или железозубых василисков.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Кхм! А-а-а... ну...$B$BХорошая работа! Поздравляю, то есть спасибо, что всех перебил.$B$BВот, держи.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Горису на Раскопки Лиги исследователей на мысе Тернистой долины.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26823,'Слишком большой для своих штанов','Что бы ты ни $gзахотел:захотела; сделать, у меня найдется рецепт! Нужно взрывчатое зелье? БУМ!!! Нужно зелье, бьющее молниями? ПЫЩ!! Нужно уменьшающее зелье? Пиу!$B$BТак значит, Бронвину требуется зелье для углеродного анализа? Это легко, я хоть во сне такое сделаю. Но если уж точно следовать рецепту, то понадобятся очень качественные ингредиенты.$B$BПерво-наперво – телесная жидкость василисков, которые живут на севере. И василиск нужен покрупнее...','Наберите флакон телесной жидкости железнозуба у железнозубого чудища в Хрустальной шахте.','Вернитесь к Даску "Пузырю" Гоблопшику на Раскопки Лиги исследователей, что на мысу Тернистой долины.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Слишком большой для своих штанов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что бы ты ни $gзахотел:захотела; сделать, у меня найдется рецепт! Нужно взрывчатое зелье? БУМ!!! Нужно зелье, бьющее молниями? ПЫЩ!! Нужно уменьшающее зелье? Пиу!$B$BТак значит, Бронвину требуется зелье для углеродного анализа? Это легко, я хоть во сне такое сделаю. Но если уж точно следовать рецепту, то понадобятся очень качественные ингредиенты.$B$BПерво-наперво – телесная жидкость василисков, которые живут на севере. И василиск нужен покрупнее...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Наберите флакон телесной жидкости железнозуба у железнозубого чудища в Хрустальной шахте.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Даску "Пузырю" Гоблопшику на Раскопки Лиги исследователей, что на мысу Тернистой долины.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26824,'Неопределенные результаты','Я все сделал как надо, $n. У меня были необходимые зелья... и рецепты правильные... И все равно не понимаю, что это такое. Этой вещи десятки тысяч лет, но к титанам она не имеет ни малейшего отношения. Это не саронит, достаточно просто посмотреть на нее. Так... Во имя Бранна, ну что же это?$B$BПередай Бронвину мои извинения, скажи, что я сделал все, что только было в моих силах.','Верните открытый сундук сокровищ клана Мош\'Огг Бронвину в лагерь Лиги исследователей на мысе Тернистой долины.','Так и знал, что от алхимика никакого толку. Все равно спасибо за помощь, Турбомажка. Ты сделала все, что могла.','Я видел дым. Все в порядке?','Верните открытый сундук сокровищ клана Мош\'Огг Бронвину в лагерь Лиги исследователей на мысе Тернистой долины.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Неопределенные результаты',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я все сделал как надо, $n. У меня были необходимые зелья... и рецепты правильные... И все равно не понимаю, что это такое. Этой вещи десятки тысяч лет, но к титанам она не имеет ни малейшего отношения. Это не саронит, достаточно просто посмотреть на нее. Так... Во имя Бранна, ну что же это?$B$BПередай Бронвину мои извинения, скажи, что я сделал все, что только было в моих силах.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните открытый сундук сокровищ клана Мош\'Огг Бронвину в лагерь Лиги исследователей на мысе Тернистой долины.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так и знал, что от алхимика никакого толку. Все равно спасибо за помощь, Турбомажка. Ты сделала все, что могла.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я видел дым. Все в порядке?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Верните открытый сундук сокровищ клана Мош\'Огг Бронвину в лагерь Лиги исследователей на мысе Тернистой долины.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26825,'Даск "Пузырь" Гоблопшик','Эй, да ты, наверно, $gтот самый паренек:та самая деваха;, о ком Вольфред толковал! Это же ты $gнашел:нашла; артефакт огров и $gпомог:помогла; ему испытать в деле те чудные камни с севера? Добро пожаловать в карьер, $n!$B$BМы тут как раз пытаемся идентифицировать вот эти образцы. Отнесешь один Даску? Нужно, чтобы он помог мне определить возраст этой штуки.','И снова, как и всегда, малыш Даск должен выполнить за Лигу исследователей всю работу! Ладно... Давай посмотрим, что там у тебя.','Тебе нужно что-то смешать?','Отнесите открытый сундук сокровищ клана Мош\'Огг Даску "Пузырю" Гоблопшику на Раскопки Лиги исследователей, что на мысу Тернистой долины.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Даск "Пузырь" Гоблопшик',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эй, да ты, наверно, $gтот самый паренек:та самая деваха;, о ком Вольфред толковал! Это же ты $gнашел:нашла; артефакт огров и $gпомог:помогла; ему испытать в деле те чудные камни с севера? Добро пожаловать в карьер, $n!$B$BМы тут как раз пытаемся идентифицировать вот эти образцы. Отнесешь один Даску? Нужно, чтобы он помог мне определить возраст этой штуки.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','И снова, как и всегда, малыш Даск должен выполнить за Лигу исследователей всю работу! Ладно... Давай посмотрим, что там у тебя.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе нужно что-то смешать?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите открытый сундук сокровищ клана Мош\'Огг Даску "Пузырю" Гоблопшику на Раскопки Лиги исследователей, что на мысу Тернистой долины.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26826,'Даск "Пузырь" Гоблопшик','Эй, да ты, наверно, $gтот самый паренек:та самая деваха;, о ком Вольфред толковал! Добро пожаловать в карьер, $n!$B$BА мы тут как раз начали работу над новым проектом. Отнесешь вот этот образец Даску? Нужно, чтобы он помог мне определить возраст этой штуки.','И снова, как и всегда, малыш Даск должен выполнить за Лигу исследователей всю работу! Ладно... Давай посмотрим, что там у тебя.','Тебе нужно что-то смешать?','Отнесите открытый сундук сокровищ клана Мош\'Огг Даску "Пузырю" Гоблопшику на Раскопках Лиги исследователей, что на мысе Тернистой долины.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Даск "Пузырь" Гоблопшик',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эй, да ты, наверно, $gтот самый паренек:та самая деваха;, о ком Вольфред толковал! Добро пожаловать в карьер, $n!$B$BА мы тут как раз начали работу над новым проектом. Отнесешь вот этот образец Даску? Нужно, чтобы он помог мне определить возраст этой штуки.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','И снова, как и всегда, малыш Даск должен выполнить за Лигу исследователей всю работу! Ладно... Давай посмотрим, что там у тебя.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе нужно что-то смешать?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите открытый сундук сокровищ клана Мош\'Огг Даску "Пузырю" Гоблопшику на Раскопках Лиги исследователей, что на мысе Тернистой долины.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26827,'Сбор Служителей Земли','Мы должны собрать Служителей Земли для этой битвы. Недостаток воинов мы восполним своей силой.$b$bОтправляйся в храм и собери оставшихся шаманов из дальних комнат. Норсала, Лорвариус и я встретим их у Врат Лортуны.','Соберите 5 шаманов в дальней части Храма Земли, а затем поговорите с Маруутом Камневязом.','Поговорите с Маруутом Камневязом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сбор Служителей Земли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы должны собрать Служителей Земли для этой битвы. Недостаток воинов мы восполним своей силой.$b$bОтправляйся в храм и собери оставшихся шаманов из дальних комнат. Норсала, Лорвариус и я встретим их у Врат Лортуны.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 5 шаманов в дальней части Храма Земли, а затем поговорите с Маруутом Камневязом.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Маруутом Камневязом.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (26828,'Наша часть сделки','Поговорите с Теразан в Пределе Безмятежности.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наша часть сделки',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Теразан в Пределе Безмятежности.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26829,'Каменный марш','Мои войска уже начали атаку. Присоединяйся к ним. Пусть кровь сектантов прольется на землю, чтобы я могла почувствовать, как они страдают.','Убейте 15 сектантов Сумеречной пропасти.','Как приятно видеть их пролитую кровь. Я буду наслаждаться каждым мгновением, уничтожая тех, кто еще остался.','Вернитесь к Теразан в Предел Безмятежности.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Каменный марш',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мои войска уже начали атаку. Присоединяйся к ним. Пусть кровь сектантов прольется на землю, чтобы я могла почувствовать, как они страдают.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 15 сектантов Сумеречной пропасти.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Как приятно видеть их пролитую кровь. Я буду наслаждаться каждым мгновением, уничтожая тех, кто еще остался.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Теразан в Предел Безмятежности.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26830,'Приманка для предателя','Идите к башням для дирижаблей. Допросите работников Оргриммарских доков. Ищите тех, кто вызывает подозрения. Постарайтесь разоблачить Сауранока Мистика и убить его.','Сауранок, Сауранок... Он пал жертвой собственных видений... Вероятно, Сумеречный Молот наслал на него порчу. Тьфу, слабак! Отныне мы навсегда забудем его имя.$B$BСилнор, я сказал ему, что тебе поручено провести расследование в доках. Да, я использовал тебя в качестве приманки. С твоей помощью мы вычислили эту гадюку, и за это ты заслуживаешь награды.','Найди доказательства предательства Сауронока. А затем убей его.','Сауранок Мистик') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приманка для предателя',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Идите к башням для дирижаблей. Допросите работников Оргриммарских доков. Ищите тех, кто вызывает подозрения. Постарайтесь разоблачить Сауранока Мистика и убить его.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сауранок, Сауранок... Он пал жертвой собственных видений... Вероятно, Сумеречный Молот наслал на него порчу. Тьфу, слабак! Отныне мы навсегда забудем его имя.$B$BСилнор, я сказал ему, что тебе поручено провести расследование в доках. Да, я использовал тебя в качестве приманки. С твоей помощью мы вычислили эту гадюку, и за это ты заслуживаешь награды.',`offerrewardtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Найди доказательства предательства Сауронока. А затем убей его.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Сауранок Мистик',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26831,'Сумеречный полет','Террат хочет, чтобы ты $gотправился:отправилась; на другой край пропасти и $gсразился:сразилась; с Золтриком Драконьером. Он и сам направляется туда, но боится, что Золтрик ускользнет.$b$bПохоже, ты $gпроизвел:произвела; на него впечатление, $gмалыш:малышка;. Ты когда-нибудь $gдумал:думала;, что ничего бы этого не было, если бы при нашей первой встрече я просто наступил на тебя? Странная штука – судьба.','Победите Золтрика Драконьера.','Хорошо, что ты здесь. Странно, но когда заходит речь о езде на драконах, я нахожу, что мой рост мне мешает.','Приятно снова видеть тебя на поле боя.','Поговорите с Терратом Непоколебимым у Сумеречной пропасти.','Лидер сумеречных наездников на драконах Подземья.','Золтрик Драконьер') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сумеречный полет',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Террат хочет, чтобы ты $gотправился:отправилась; на другой край пропасти и $gсразился:сразилась; с Золтриком Драконьером. Он и сам направляется туда, но боится, что Золтрик ускользнет.$b$bПохоже, ты $gпроизвел:произвела; на него впечатление, $gмалыш:малышка;. Ты когда-нибудь $gдумал:думала;, что ничего бы этого не было, если бы при нашей первой встрече я просто наступил на тебя? Странная штука – судьба.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Золтрика Драконьера.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо, что ты здесь. Странно, но когда заходит речь о езде на драконах, я нахожу, что мой рост мне мешает.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Приятно снова видеть тебя на поле боя.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Терратом Непоколебимым у Сумеречной пропасти.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Лидер сумеречных наездников на драконах Подземья.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Золтрик Драконьер',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26832,'Милость Теразан','В Сумеречном Молоте есть два лидера, которых нужно убить.$b$bОдин из них человек по имени Болдрик. Маленький, как ты. Но, тем не менее, опасный. Тоже как ты.$b$bВторая – жрица по имени Лортуна. Она хитра и провести ее нелегко. Постарайся убить ее быстро и не дай ей сбежать, иначе потом ты об этом пожалеешь, это я тебе гарантирую.','Победите Болдрика Стоунрендера и верховную жрицу Лортуну.','Ты позволил Лортуне сбежать? Я предостерегала тебя.$B$BВпрочем, их силы разрозненны, а их ресурсы истощены. Они мало чем могут навредить мне или моим союзникам.','Вернитесь к Теразан в Предел Безмятежности.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Милость Теразан',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В Сумеречном Молоте есть два лидера, которых нужно убить.$b$bОдин из них человек по имени Болдрик. Маленький, как ты. Но, тем не менее, опасный. Тоже как ты.$b$bВторая – жрица по имени Лортуна. Она хитра и провести ее нелегко. Постарайся убить ее быстро и не дай ей сбежать, иначе потом ты об этом пожалеешь, это я тебе гарантирую.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Болдрика Стоунрендера и верховную жрицу Лортуну.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты позволил Лортуне сбежать? Я предостерегала тебя.$B$BВпрочем, их силы разрозненны, а их ресурсы истощены. Они мало чем могут навредить мне или моим союзникам.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Теразан в Предел Безмятежности.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26833,'Каменное слово','Поговорите с Маруутом Камневязом в Храме Земли.','Горсик прибыл. Благодаря тебе все части столпа мира здесь.$B$BТо, что ты сделал, неоценимо! Эти последние мгновения будут наиболее важными. Мне неловко просить тебя о большем, но все же я бы хотел, чтобы ты остался до конца.$B$BСумеречный Молот серьезно пострадал от твоих атак, но все же не истреблен. Наверняка они постараются помешать нам завершить ритуал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Каменное слово',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Маруутом Камневязом в Храме Земли.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Горсик прибыл. Благодаря тебе все части столпа мира здесь.$B$BТо, что ты сделал, неоценимо! Эти последние мгновения будут наиболее важными. Мне неловко просить тебя о большем, но все же я бы хотел, чтобы ты остался до конца.$B$BСумеречный Молот серьезно пострадал от твоих атак, но все же не истреблен. Наверняка они постараются помешать нам завершить ритуал.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26834,'В расщелину','Внизу, на дне Провала Каменных Игл мистики выращивают всех этих грибных чудовищ.$b$bЯ отправил туда Сланца Плывуна с небольшим отрядом, но они наткнулись на препятствие.$b$bПомнишь верховного геоманта? Не согласишься слетать на северо-восток и помочь ему?','Поговорите со Сланцем Плывуном у Провала Каменных Игл в Подземье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В расщелину',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Внизу, на дне Провала Каменных Игл мистики выращивают всех этих грибных чудовищ.$b$bЯ отправил туда Сланца Плывуна с небольшим отрядом, но они наткнулись на препятствие.$b$bПомнишь верховного геоманта? Не согласишься слетать на северо-восток и помочь ему?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите со Сланцем Плывуном у Провала Каменных Игл в Подземье.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26835,'Небольшая проблема','Пока тебя здесь не было, ко мне обращался Колчедан Магнетий. Он сказал, что есть одно неотложное дело, в котором требуется твоя помощь. Разыщи его у входа в Шлаковый зал, что к юго-западу отсюда.$b$bЯ желаю тебе удачи в спасении Отца-Скалы и в поисках центрального фрагмента.','Вернитесь к Колчедану Магнетию в Шлаковый зал, что в Подземье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Небольшая проблема',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пока тебя здесь не было, ко мне обращался Колчедан Магнетий. Он сказал, что есть одно неотложное дело, в котором требуется твоя помощь. Разыщи его у входа в Шлаковый зал, что к юго-западу отсюда.$b$bЯ желаю тебе удачи в спасении Отца-Скалы и в поисках центрального фрагмента.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь к Колчедану Магнетию в Шлаковый зал, что в Подземье.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26836,'Спасите Отца-Скалу... и Флинта','Мы узнали, где держат Отца-Скалу, и молодой Флинт один помчался его спасать!$b$bМне не нужно объяснять тебе, как это плохо. Флинта схватят точно так же, как и его отца!$b$bВождя каменных троггов, Камнебрюха можно найти у Провала Каменных Игл, к северу отсюда.$b$bПожалуйста, $n, отправляйся вслед за Флинтом и освободи Отца-Скалу, пока мы не потеряли их обоих!','Освободите Отца-Скалу Железную Мантию.','Вернитесь к Колчедану Магнетию в Шлаковый зал, что в Подземье.','Убейте Камнебрюха и спасите Отца-Скалу… и Флинта!','Камнебрюх') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спасите Отца-Скалу... и Флинта',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы узнали, где держат Отца-Скалу, и молодой Флинт один помчался его спасать!$b$bМне не нужно объяснять тебе, как это плохо. Флинта схватят точно так же, как и его отца!$b$bВождя каменных троггов, Камнебрюха можно найти у Провала Каменных Игл, к северу отсюда.$b$bПожалуйста, $n, отправляйся вслед за Флинтом и освободи Отца-Скалу, пока мы не потеряли их обоих!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Освободите Отца-Скалу Железную Мантию.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Колчедану Магнетию в Шлаковый зал, что в Подземье.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Убейте Камнебрюха и спасите Отца-Скалу… и Флинта!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Камнебрюх',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (26837,'Раскопки Лиги исследователей','А знаешь, $n... ты нам как раз подойдешь.$B$BБронвин Зарубай из Лиги исследователей ищет работников на раскопки на мысе Тернистой долины. Лично я не понимаю, почему он не отправится в Пиратскую Бухту и не наймет копальщиков там – пираты за пару золотых в очередь выстроятся.$B$BНу да ладно. Говорят, что-то в тех джунглях он все-таки откопал. Интересно, что...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Раскопки Лиги исследователей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А знаешь, $n... ты нам как раз подойдешь.$B$BБронвин Зарубай из Лиги исследователей ищет работников на раскопки на мысе Тернистой долины. Лично я не понимаю, почему он не отправится в Пиратскую Бухту и не наймет копальщиков там – пираты за пару золотых в очередь выстроятся.$B$BНу да ладно. Говорят, что-то в тех джунглях он все-таки откопал. Интересно, что...',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26838,'Безыдейные повстанцы','Несколько лет назад капитан Курцен из Штормграда явился со своими людьми в Тернистую долину, причем неизвестно, с какими целями. Со временем Курцен погрузился в пучину безумия, как и многие его подчиненные... Но некоторые взбунтовались и решили исправить все, что сделал их капитан.$B$BС тех пор прошло немало времени. Курцен мертв, а слухи о повстанцах все множатся. Если хочешь разобраться, в чем дело, отправляйся в их лагерь на северной границе Тернистой долины.','Отправляйтесь к лейтенанту Дорену в Лагерь Повстанцев в Северной Тернистой долине.','Отправляйтесь с докладом к лейтенанту Дорену в Лагерь Повстанцев в Северной Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Безыдейные повстанцы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Несколько лет назад капитан Курцен из Штормграда явился со своими людьми в Тернистую долину, причем неизвестно, с какими целями. Со временем Курцен погрузился в пучину безумия, как и многие его подчиненные... Но некоторые взбунтовались и решили исправить все, что сделал их капитан.$B$BС тех пор прошло немало времени. Курцен мертв, а слухи о повстанцах все множатся. Если хочешь разобраться, в чем дело, отправляйся в их лагерь на северной границе Тернистой долины.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь к лейтенанту Дорену в Лагерь Повстанцев в Северной Тернистой долине.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отправляйтесь с докладом к лейтенанту Дорену в Лагерь Повстанцев в Северной Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (26839,'Пусть весь мир подождет!','$GКакой-то ты усталый:Какая-то ты усталая:c;, |3-6($c). Хотя конечно – таскать повсюду такой тяжелый кошелек... гм, то есть снаряжение... Тяжко, поди, да и спина наверняка болит.$B$BНедавно Хамми Кофельнагель открыла первоклассный пятизвездочный отель на живописном берегу мыса Тернистой долины. Там катают на воздушных шарах и гребных лодках, возят на экскурсии в Пиратскую Бухту... все там есть, чего только душа пожелает.$B$BОчень советую туда заглянуть. После всех опасных и прибыльных приключений обязательно нужен хороший отдых.','Навестите Хамми Кофельнагель в Укрытии Кофельнагель на мысе Тернистой долины.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пусть весь мир подождет!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$GКакой-то ты усталый:Какая-то ты усталая:c;, |3-6($c). Хотя конечно – таскать повсюду такой тяжелый кошелек... гм, то есть снаряжение... Тяжко, поди, да и спина наверняка болит.$B$BНедавно Хамми Кофельнагель открыла первоклассный пятизвездочный отель на живописном берегу мыса Тернистой долины. Там катают на воздушных шарах и гребных лодках, возят на экскурсии в Пиратскую Бухту... все там есть, чего только душа пожелает.$B$BОчень советую туда заглянуть. После всех опасных и прибыльных приключений обязательно нужен хороший отдых.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Навестите Хамми Кофельнагель в Укрытии Кофельнагель на мысе Тернистой долины.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26840,'Возвращение на нагорье','Вернитесь в порт Драконьей Пасти через портал на Сумеречное нагорье в Оргриммаре и поговорите с Зелой.','Вернитесь в порт Драконьей Пасти через портал на Сумеречное нагорье в Оргриммаре и поговорите с Зелой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение на нагорье',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь в порт Драконьей Пасти через портал на Сумеречное нагорье в Оргриммаре и поговорите с Зелой.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь в порт Драконьей Пасти через портал на Сумеречное нагорье в Оргриммаре и поговорите с Зелой.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26842,'Откуда ни возьмись – гноллы','Рад встрече, |3-6($c). У нас тут проблема, и я бы хотел попросить тебя о помощи.$b$bГноллы. Их целые толпы на холмах к западу от города. Не то чтобы мы были сильно обеспокоены, но все же обычно в Лок Модане их не бывает.$b$bМне, конечно, любопытно, откуда они взялись, но не настолько, чтобы вступать в диалог с этими шелудивыми тварями. Поэтому просто убей их. Принеси мне что-нибудь в доказательство и получишь хорошее вознаграждение.','Соберите 12 ушей гноллов, убив разведчиков из племени Мохошкуров или губителей из племени Мохошкуров.','Вернитесь к горному пехотинцу Кэдреллу в Лок Модан.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Откуда ни возьмись – гноллы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Рад встрече, |3-6($c). У нас тут проблема, и я бы хотел попросить тебя о помощи.$b$bГноллы. Их целые толпы на холмах к западу от города. Не то чтобы мы были сильно обеспокоены, но все же обычно в Лок Модане их не бывает.$b$bМне, конечно, любопытно, откуда они взялись, но не настолько, чтобы вступать в диалог с этими шелудивыми тварями. Поэтому просто убей их. Принеси мне что-нибудь в доказательство и получишь хорошее вознаграждение.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 12 ушей гноллов, убив разведчиков из племени Мохошкуров или губителей из племени Мохошкуров.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к горному пехотинцу Кэдреллу в Лок Модан.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26843,'Маленький смышленый командир','Вот уже многие годы мы имеем дело с кобольдами в этих землях. Просто неприятные твари, не более того. Но в последнее время они становятся все изобретательнее в своих кражах.$b$bДумаю, среди них появился один, который заметно умнее остальных. Впрочем, долго это не продлится!$b$bЯ хочу, чтобы ты $gотправился:отправилась; в лагерь к югу отсюда и $gпоискал:поискала; там "большую шишку", которая ими командует. Обязательно проверь пещеру, это наиболее вероятное место.$b$bИ не стесняйся убивать тех кобольдов, что встретятся на твоем пути.','Убейте командира Назрима.','Так я был прав! Теперь хорошо бы узнать, что замышляли эти маленькие негодяи…','Вернитесь к горному пехотинцу Грозовой Вершине на станцию Альгаз в Лок Модане.','Ищи кобольда с самой длинной свечой.','"Командир" Назрим') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Маленький смышленый командир',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот уже многие годы мы имеем дело с кобольдами в этих землях. Просто неприятные твари, не более того. Но в последнее время они становятся все изобретательнее в своих кражах.$b$bДумаю, среди них появился один, который заметно умнее остальных. Впрочем, долго это не продлится!$b$bЯ хочу, чтобы ты $gотправился:отправилась; в лагерь к югу отсюда и $gпоискал:поискала; там "большую шишку", которая ими командует. Обязательно проверь пещеру, это наиболее вероятное место.$b$bИ не стесняйся убивать тех кобольдов, что встретятся на твоем пути.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте командира Назрима.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так я был прав! Теперь хорошо бы узнать, что замышляли эти маленькие негодяи…',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к горному пехотинцу Грозовой Вершине на станцию Альгаз в Лок Модане.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Ищи кобольда с самой длинной свечой.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','"Командир" Назрим',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26844,'Кобольд... Еще кобольд','Теперь, когда с этими мелкими гадами покончено, у нас есть и другие заботы.$b$bСеребряные копи кишмя кишат туннельщиками. Они разбивают там лагеря и с каждым днем проникают все глубже и глубже. Полагаю, эти маленькие жадные зверюшки ищут наживы.$b$bВсе имеют право на поиски и собирательство, если это происходит не в дворфийских землях! Займись этими туннельщиками и потом отчитайся мне.','Убейте 5 геодезистов-туннельщиков и 5 добытчиков-туннельщиков.','Хорошо, хорошо. Теперь мы можем увидеть, что происходит внутри рудника.','Вернитесь к горному пехотинцу Грозовой Вершине на станцию Альгаз, что в Лок Модане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кобольд... Еще кобольд',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда с этими мелкими гадами покончено, у нас есть и другие заботы.$b$bСеребряные копи кишмя кишат туннельщиками. Они разбивают там лагеря и с каждым днем проникают все глубже и глубже. Полагаю, эти маленькие жадные зверюшки ищут наживы.$b$bВсе имеют право на поиски и собирательство, если это происходит не в дворфийских землях! Займись этими туннельщиками и потом отчитайся мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 5 геодезистов-туннельщиков и 5 добытчиков-туннельщиков.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо, хорошо. Теперь мы можем увидеть, что происходит внутри рудника.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к горному пехотинцу Грозовой Вершине на станцию Альгаз, что в Лок Модане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26845,'Кто за всем этим стоит?','Дорли проинформировала меня насчет этой безумной операции по порабощению троггов, которую проворачивают кобольды. Если ты еще не $gговорил:говорила; с ней, советую это сделать.$b$bВ этой истории нужно дойти до самого дна. Буквально! Кто бы ни стоял за всем этим, он однозначно скрывается в глубине рудника, отдавая оттуда приказы. Я хочу, чтобы он был найден.$b$bРазыщи этого умельца, который руководит геомантами и землекопами, и принеси мне его голову.','Добудьте голову штейгера Острослова.','Полагаю, это была не Мойра? Бывают же чудеса.','Вернитесь к горному пехотинцу Грозовой Вершине на станцию Альгаз, что в Лок Модане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кто за всем этим стоит?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Дорли проинформировала меня насчет этой безумной операции по порабощению троггов, которую проворачивают кобольды. Если ты еще не $gговорил:говорила; с ней, советую это сделать.$b$bВ этой истории нужно дойти до самого дна. Буквально! Кто бы ни стоял за всем этим, он однозначно скрывается в глубине рудника, отдавая оттуда приказы. Я хочу, чтобы он был найден.$b$bРазыщи этого умельца, который руководит геомантами и землекопами, и принеси мне его голову.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте голову штейгера Острослова.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Полагаю, это была не Мойра? Бывают же чудеса.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к горному пехотинцу Грозовой Вершине на станцию Альгаз, что в Лок Модане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26846,'Грязная эксплуатация','Я узнала, что затевают эти крысы. Их так много вокруг, потому что в руднике на них работают трогги!$b$bГеоманты туннельщиков знают какой-то фокус, благодаря которому они управляют троггами.$b$bПотрясающе, но не означает, что мы позволим им практиковать это и дальше. Разберись с этими геомантами.','Убейте 5 геомантов-туннельщиков.','Уверена, им это удалось только потому, что трогги умом не блещут. Хотя мы, дворфы, тоже когда-то были существами приземленными.$B$BНе очень-то приятно, когда тобой командуют кобольды, и я рада, что нам не пришлось выяснять, удастся им это или нет.','Вернитесь к разведчике Дорли на станцию Альгаз, что в Лок Модане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Грязная эксплуатация',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я узнала, что затевают эти крысы. Их так много вокруг, потому что в руднике на них работают трогги!$b$bГеоманты туннельщиков знают какой-то фокус, благодаря которому они управляют троггами.$b$bПотрясающе, но не означает, что мы позволим им практиковать это и дальше. Разберись с этими геомантами.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 5 геомантов-туннельщиков.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Уверена, им это удалось только потому, что трогги умом не блещут. Хотя мы, дворфы, тоже когда-то были существами приземленными.$B$BНе очень-то приятно, когда тобой командуют кобольды, и я рада, что нам не пришлось выяснять, удастся им это или нет.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к разведчике Дорли на станцию Альгаз, что в Лок Модане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26847,'Грот Обвалов','[Deprecated] The king has moved south, just past Stonehearth, to the Quaking Fields.$B$BGood luck in retrieving the middle fragment of the World Pillar, but beware the giants and other creatures of the field, $n.','[Deprecated] Speak with King Oremantle at the Quaking Fields in Deepholm.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Грот Обвалов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','[Deprecated] The king has moved south, just past Stonehearth, to the Quaking Fields.$B$BGood luck in retrieving the middle fragment of the World Pillar, but beware the giants and other creatures of the field, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','[Deprecated] Speak with King Oremantle at the Quaking Fields in Deepholm.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26848,'Место отмечено','<Король отмечает место на вашей карте.>$b$bВот здесь я закопал его. Отправляйся туда и выкопай его для меня.$b$bГлавное, сторонись великанов. По своему опыту могу сказать, что бьют они, как... ну, как великаны!','Отправляйтесь туда, где король Железная Мантия закопал второй фрагмент столпа мира.','[Deprecated] Return to King Oremantle at the Quaking Fields in Deepholm.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Место отмечено',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Король отмечает место на вашей карте.>$b$bВот здесь я закопал его. Отправляйся туда и выкопай его для меня.$b$bГлавное, сторонись великанов. По своему опыту могу сказать, что бьют они, как... ну, как великаны!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь туда, где король Железная Мантия закопал второй фрагмент столпа мира.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','[Deprecated] Return to King Oremantle at the Quaking Fields in Deepholm.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26849,'Топор раскола земли','[Deprecated] The emerald colossi need to be removed from the field. It\'s conceivable that one of them has the fragment. Regardless, Therzane has moved her forces too close to Stonehearth and they pose a threat.$B$BSunder the giants with my axe. That should bring them down to a more manageable size so that you can finish them off.','Убейте 5 потрескавшихся изумрудных колоссов.','[Deprecated] Return to King Oremantle at the Quaking Fields in Deepholm.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Топор раскола земли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','[Deprecated] The emerald colossi need to be removed from the field. It\'s conceivable that one of them has the fragment. Regardless, Therzane has moved her forces too close to Stonehearth and they pose a threat.$B$BSunder the giants with my axe. That should bring them down to a more manageable size so that you can finish them off.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 5 потрескавшихся изумрудных колоссов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','[Deprecated] Return to King Oremantle at the Quaking Fields in Deepholm.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26850,'Элементиевая руда','Чтобы определить точное местонахождение фрагмента столпа мира, мы должны произвести ритуал.$b$bОтправляйся на поле и забери у яростней элементиевую руду. Когда ее будет достаточно, ты сможешь узнать все, что нам нужно.','Соберите 6 кусков элементиевой руды.','[Deprecated] Return to King Oremantle at the Quaking Fields in Deepholm.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Элементиевая руда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чтобы определить точное местонахождение фрагмента столпа мира, мы должны произвести ритуал.$b$bОтправляйся на поле и забери у яростней элементиевую руду. Когда ее будет достаточно, ты сможешь узнать все, что нам нужно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 6 кусков элементиевой руды.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','[Deprecated] Return to King Oremantle at the Quaking Fields in Deepholm.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questturntextwindow_loc8`) VALUES (26851,'Единое целое с землей','Я знаю ритуал, благодаря которому ты станешь единым целым с землей. Поскольку я уже отдал фрагмент, духи земли приведут тебя к нему.$b$bСконцентрируй свои мысли на столпе мира и дай мне знать, когда будешь $gготов:готова;.','При помощи ритуала единения с землей узнайте, где находится центральный фрагмент столпа мира.','Ага!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Единое целое с землей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я знаю ритуал, благодаря которому ты станешь единым целым с землей. Поскольку я уже отдал фрагмент, духи земли приведут тебя к нему.$b$bСконцентрируй свои мысли на столпе мира и дай мне знать, когда будешь $gготов:готова;.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','При помощи ритуала единения с землей узнайте, где находится центральный фрагмент столпа мира.',`objectives_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Ага!',`questturntextwindow_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26852,'Фрагмент внутри','Центральный фрагмент столпа мира находится внутри Пещеры Лавиниона. Войди и возьми его.','Возьмите центральный фрагмент столпа мира.','[Deprecated] Return to King Oremantle at the Quaking Fields in Deepholm.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Фрагмент внутри',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Центральный фрагмент столпа мира находится внутри Пещеры Лавиниона. Войди и возьми его.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возьмите центральный фрагмент столпа мира.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','[Deprecated] Return to King Oremantle at the Quaking Fields in Deepholm.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26853,'Центральный фрагмент','Спеши. Беги так быстро, как только можешь, $n!Доставь центральный фрагмент к Храму Земли, что в центре Подземья!','Отнесите центральный фрагмент столпа мира заклинательнице земли Еве в Храм Земли, что в Подземье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Центральный фрагмент',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Спеши. Беги так быстро, как только можешь, $n!Доставь центральный фрагмент к Храму Земли, что в центре Подземья!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите центральный фрагмент столпа мира заклинательнице земли Еве в Храм Земли, что в Подземье.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26854,'Пропавший пилот','Мой друг и напарник, пилот осадной машины Мори Хилдельв, пропал в этих холмах. Мы искали там редкую руду, необходимую для высококачественного пороха, и во время поисков загнали его машину на крутой холм, а там она сломалась!$B$BХилдельв, по-прежнему уверенный, что руда в этих горах есть, оставил меня охранять наши машины, а сам пошел дальше пешком.$B$BНо прошло уже несколько дней, а ночью я слышал какой-то звериный вой севернее озера Хельмово Ложе, к западу от туннеля. Мори – парень-кремень, но мне тревожно.$B$BПрошу тебя, $n, найди его.','Найдите пилота Хилдельва к северу от озера Хельмово Ложе.','Перед вами труп дворфа – изуродованный, застывший и сильно обглоданный горными хищниками. В руке он сжимает записную книжку с грубо нацарапанными записями Мори Хилдельва. Жилет бригадира, в который был одет дворф, сохранился превосходно.$B$BСудя по этой мрачной картине, именно здесь пилот осадной машины встретил свою кончину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пропавший пилот',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мой друг и напарник, пилот осадной машины Мори Хилдельв, пропал в этих холмах. Мы искали там редкую руду, необходимую для высококачественного пороха, и во время поисков загнали его машину на крутой холм, а там она сломалась!$B$BХилдельв, по-прежнему уверенный, что руда в этих горах есть, оставил меня охранять наши машины, а сам пошел дальше пешком.$B$BНо прошло уже несколько дней, а ночью я слышал какой-то звериный вой севернее озера Хельмово Ложе, к западу от туннеля. Мори – парень-кремень, но мне тревожно.$B$BПрошу тебя, $n, найди его.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите пилота Хилдельва к северу от озера Хельмово Ложе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Перед вами труп дворфа – изуродованный, застывший и сильно обглоданный горными хищниками. В руке он сжимает записную книжку с грубо нацарапанными записями Мори Хилдельва. Жилет бригадира, в который был одет дворф, сохранился превосходно.$B$BСудя по этой мрачной картине, именно здесь пилот осадной машины встретил свою кончину.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26855,'Месть пилота','Хилдельв пишет в своем дневнике, что подвергся нападению Паршивого Когтя, "огромного медведя-ледолапа". Он отогнал тварь, но та успела страшно изранить его.$B$BСудя по состоянию трупа Хилдельва, Паршивый Коготь, видимо, вернулся и добил его.$B$BВ своих записях Хилдельв записал свое последнее желание:$B$B"Отомстить Паршивому Когтю".','Убейте Паршивого Когтя.$b$bПринесите его грязный коготь и записи Хилдельва пилоту Большеногу к заставе у Южных врат.','Вернитесь к пилоту Большеногу на Заставу у Южных врат, что в Дун Мороге.','Посмотрите вокруг. Медведь наверняка где-то неподалеку от тела Хилдельва.','Паршивый Коготь') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Месть пилота',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хилдельв пишет в своем дневнике, что подвергся нападению Паршивого Когтя, "огромного медведя-ледолапа". Он отогнал тварь, но та успела страшно изранить его.$B$BСудя по состоянию трупа Хилдельва, Паршивый Коготь, видимо, вернулся и добил его.$B$BВ своих записях Хилдельв записал свое последнее желание:$B$B"Отомстить Паршивому Когтю".',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Паршивого Когтя.$b$bПринесите его грязный коготь и записи Хилдельва пилоту Большеногу к заставе у Южных врат.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к пилоту Большеногу на Заставу у Южных врат, что в Дун Мороге.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Посмотрите вокруг. Медведь наверняка где-то неподалеку от тела Хилдельва.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Паршивый Коготь',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26856,'Отражение атаки','Эта пещера некогда была почитаемым местом. Молодых воинов отправляли сюда сражаться с червем-землеедом, проливать первую кровь. Такие моменты мы, орки, помним до конца своих дней.$B$BШпионы Пламенеющего Клинка поработили обитателей пещеры и собираются перейти в полномасштабное наступление на Оргриммар вместе со своими союзниками-троггами.$B$BНо если ты устранишь вражеских командиров, то атака может захлебнуться, не начавшись.','Устраните Огглфлинта, Баззалана и Жергоша Призывателя Духов.','Вернитесь к каменному стражу Курджаку в Огненную Пропасть.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отражение атаки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эта пещера некогда была почитаемым местом. Молодых воинов отправляли сюда сражаться с червем-землеедом, проливать первую кровь. Такие моменты мы, орки, помним до конца своих дней.$B$BШпионы Пламенеющего Клинка поработили обитателей пещеры и собираются перейти в полномасштабное наступление на Оргриммар вместе со своими союзниками-троггами.$B$BНо если ты устранишь вражеских командиров, то атака может захлебнуться, не начавшись.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Устраните Огглфлинта, Баззалана и Жергоша Призывателя Духов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к каменному стражу Курджаку в Огненную Пропасть.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26857,'Приспешники Абиссия','Победите 8 сумеречных доминаторов у Логова Абиссия.','Вернитесь к буревестнице Милре на дозорный холм Сумеречного Молота, что в Подземье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приспешники Абиссия',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите 8 сумеречных доминаторов у Логова Абиссия.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к буревестнице Милре на дозорный холм Сумеречного Молота, что в Подземье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26858,'Тарагаман Ненасытный','Пламенеющему Клинку удалось призвать омерзительного демона, Тарагамана Ненасытного, чтобы он возглавил первую атаку на Оргриммар!$B$BСкорее избавь нас от Тарагамана, именем Вождя! Лок\'тар огар!','Добудьте сердце Тарагамана Ненасытного.','Вернитесь к каменному стражу Курджаку в Огненной Пропасти.','Пора задать ему по первое число.','Тарагаман Ненасытный') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тарагаман Ненасытный',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пламенеющему Клинку удалось призвать омерзительного демона, Тарагамана Ненасытного, чтобы он возглавил первую атаку на Оргриммар!$B$BСкорее избавь нас от Тарагамана, именем Вождя! Лок\'тар огар!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте сердце Тарагамана Ненасытного.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к каменному стражу Курджаку в Огненной Пропасти.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Пора задать ему по первое число.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Тарагаман Ненасытный',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26859,'Searching for the Lost Satchel','The troggs are not the only thing that interested Magatha in Ragefire Chasm. She has heard word that one of her servants, a Maur Grimtotem, found something peculiar while in the Chasm, but he never made it out to show her what. She\'d like Maur\'s body found--if it still exists--and any signs of what he found while attempting to speak to the troggs.$B$BReturn to Magatha any items of interest, and I\'m sure she would be very generous in her reward.$B$BAgain, seek the Chasm in the darkest areas of Orgrimmar.','Search Ragefire Chasm for Maur Grimtotem\'s corpse and search it for any items of interest.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Searching for the Lost Satchel',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','The troggs are not the only thing that interested Magatha in Ragefire Chasm. She has heard word that one of her servants, a Maur Grimtotem, found something peculiar while in the Chasm, but he never made it out to show her what. She\'d like Maur\'s body found--if it still exists--and any signs of what he found while attempting to speak to the troggs.$B$BReturn to Magatha any items of interest, and I\'m sure she would be very generous in her reward.$B$BAgain, seek the Chasm in the darkest areas of Orgrimmar.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Search Ragefire Chasm for Maur Grimtotem\'s corpse and search it for any items of interest.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26860,'Телcамарские кровяные колбаски','Едоки в Телcамаре не переводятся – еще бы, детей полным-полно, рабочие возвращаются вечером с раскопок голодными. Мы славимся кровяными колбасками. Но ты ведь их еще не $gпробовал:пробовала;?$b$bНет? Что же, у нас принято отрабатывать еду, и не думай, что за красивые глазки тебе сделают исключение, |3-6($c).$b$bМне нужны медвежьи огузки. Принеси мне их, а уж я приготовлю все в лучшем виде!','Добудьте 8 медвежьих огузков, охотясь на черных медведей в Лок Модане.','Весьма признательна! Использование медвежьих огузков – это мой собственный секрет. Но вот тебе рецепт, там сказано, как приготовить колбаски из любой части медвежьей туши.$B$BА вот и связка колбасок с пылу с жару. Ешь, пока свежие!','Я уже давно собираюсь начать готовить, где же медвежье мясо?','Вернитесь к Видре Жаркий Очаг в Телсамар, что в Лок Модане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Телcамарские кровяные колбаски',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Едоки в Телcамаре не переводятся – еще бы, детей полным-полно, рабочие возвращаются вечером с раскопок голодными. Мы славимся кровяными колбасками. Но ты ведь их еще не $gпробовал:пробовала;?$b$bНет? Что же, у нас принято отрабатывать еду, и не думай, что за красивые глазки тебе сделают исключение, |3-6($c).$b$bМне нужны медвежьи огузки. Принеси мне их, а уж я приготовлю все в лучшем виде!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 8 медвежьих огузков, охотясь на черных медведей в Лок Модане.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Весьма признательна! Использование медвежьих огузков – это мой собственный секрет. Но вот тебе рецепт, там сказано, как приготовить колбаски из любой части медвежьей туши.$B$BА вот и связка колбасок с пылу с жару. Ешь, пока свежие!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я уже давно собираюсь начать готовить, где же медвежье мясо?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Видре Жаркий Очаг в Телсамар, что в Лок Модане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26861,'Заблокировать врата','Если мы намереваемся попытаться выступить против Абиссия, мы должны быть уверены, что он не получит подкрепления.$b$bВ его логово, расположенное к востоку отсюда, ведут двое врат. Заблокируй их, воспользовавшись этим камнем бури.$b$bЕсли все пойдет по плану, Абиссий окажется в ловушке и не сможет получить помощь.','Воспользуйтесь грозовым камнем у Сумеречных и Стихийных врат в Логово Абиссия.','Великолепно. Когда мы выйдем против Абиссия, он не получит подкрепления, и у нас должно получиться одолеть его.','Вернитесь к провидцу Гэлекку на дозорный холм Сумеречного Молота, что в Подземье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Заблокировать врата',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если мы намереваемся попытаться выступить против Абиссия, мы должны быть уверены, что он не получит подкрепления.$b$bВ его логово, расположенное к востоку отсюда, ведут двое врат. Заблокируй их, воспользовавшись этим камнем бури.$b$bЕсли все пойдет по плану, Абиссий окажется в ловушке и не сможет получить помощь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь грозовым камнем у Сумеречных и Стихийных врат в Логово Абиссия.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Великолепно. Когда мы выйдем против Абиссия, он не получит подкрепления, и у нас должно получиться одолеть его.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к провидцу Гэлекку на дозорный холм Сумеречного Молота, что в Подземье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26862,'Освобождение элементалей','$n, чернокнижники Пламенеющего Клинка поработили духов элементалей Огненной Пропасти. Пока мои чары сдерживают их, и они не представляют городу угрозы. Однако силы мои на исходе.$B$BПринеси мне шесть тлеющих оков – с их помощью управляют духами. Я освобожу несчастных и отпущу обратно в пропасть.','Раздобудьте 6 тлеющих оков.','Вернитесь к Боваалу Белому Рогу в Огненной Пропасти.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Освобождение элементалей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, чернокнижники Пламенеющего Клинка поработили духов элементалей Огненной Пропасти. Пока мои чары сдерживают их, и они не представляют городу угрозы. Однако силы мои на исходе.$B$BПринеси мне шесть тлеющих оков – с их помощью управляют духами. Я освобожу несчастных и отпущу обратно в пропасть.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте 6 тлеющих оков.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Боваалу Белому Рогу в Огненной Пропасти.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26863,'Грязные лапы','Серебряные копи к востоку отсюда давно уже выработаны. Лига рудокопов превратила их в склад, но теперь туда забрались кобольды и наложили свои грязные лапы на прекрасные дворфийские инструменты!$B$BРано или поздно мы искореним этих паразитов, но Лига хочет спасти оборудование, пока в копи не спустились воины и не разнесли все к демонам. Задача твоя не из простых, помощники тебе не помешают.$B$BОборудование находится в ящиках лиги Рудокопов, разбросанных по копям. Удачи.','Соберите 6 ящиков с инструментами шахтеров в Серебряных копях.','Там много кобольдов? Когда я думаю, что они копаются своими грязными лапами в нашем руднике, я просто вскипаю!','Вернитесь к горному пехотинцу Грозовой Вершине на станцию Альгаз в Лок Модане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Грязные лапы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Серебряные копи к востоку отсюда давно уже выработаны. Лига рудокопов превратила их в склад, но теперь туда забрались кобольды и наложили свои грязные лапы на прекрасные дворфийские инструменты!$B$BРано или поздно мы искореним этих паразитов, но Лига хочет спасти оборудование, пока в копи не спустились воины и не разнесли все к демонам. Задача твоя не из простых, помощники тебе не помешают.$B$BОборудование находится в ящиках лиги Рудокопов, разбросанных по копям. Удачи.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 6 ящиков с инструментами шахтеров в Серебряных копях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Там много кобольдов? Когда я думаю, что они копаются своими грязными лапами в нашем руднике, я просто вскипаю!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к горному пехотинцу Грозовой Вершине на станцию Альгаз в Лок Модане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (26864,'Доставка головы','Мне нужно, чтобы ты $gотнес:отнесла; это горному пехотинцу Кэдреллу. Покажи это ему и скажи, что гадкие местные зверьки, похоже, объединяются.','Отнесите голову штейгера Острослова горному пехотинцу Кэдреллу.','Гноллы, кобольды и трогги? Ничего себе.$B$BЕсли у этой истории не было обратной стороны, я бы просто посмеялся.','Какие-то новости со станции Альгаз?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Доставка головы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне нужно, чтобы ты $gотнес:отнесла; это горному пехотинцу Кэдреллу. Покажи это ему и скажи, что гадкие местные зверьки, похоже, объединяются.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите голову штейгера Острослова горному пехотинцу Кэдреллу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Гноллы, кобольды и трогги? Ничего себе.$B$BЕсли у этой истории не было обратной стороны, я бы просто посмеялся.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Какие-то новости со станции Альгаз?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26865,'Враг из глубин','Враги Орды обосновались прямо под городом, |3-6($c).$B$BПламенеющий Клинок хочет захватить Оргриммар, и им уже удалось занять Огненную Пропасть! Мы должны пойти на штурм и отвоевать наши владения!$B$BКогда спустишься в пропасть, найди каменного стража Курджака. Он скажет, что делать дальше.','Поговорите с каменным стражем Курджаком.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Враг из глубин',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Враги Орды обосновались прямо под городом, |3-6($c).$B$BПламенеющий Клинок хочет захватить Оргриммар, и им уже удалось занять Огненную Пропасть! Мы должны пойти на штурм и отвоевать наши владения!$B$BКогда спустишься в пропасть, найди каменного стража Курджака. Он скажет, что делать дальше.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с каменным стражем Курджаком.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26866,'Враг из глубин','Огненная Пропасть в Оргриммаре захвачена Пламенеющим Клинком. $n, нельзя оставить это безнаказанным, иначе вскоре они обратят взор на Громовой Утес.$B$BОтправляйся в пропасть и поговори с каменным стражем Курджаком прямо возле входа. Помоги ему чем можешь, ибо судьбы наши связаны.','Поговорите с каменным стражем Курджаком.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Враг из глубин',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Огненная Пропасть в Оргриммаре захвачена Пламенеющим Клинком. $n, нельзя оставить это безнаказанным, иначе вскоре они обратят взор на Громовой Утес.$B$BОтправляйся в пропасть и поговори с каменным стражем Курджаком прямо возле входа. Помоги ему чем можешь, ибо судьбы наши связаны.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с каменным стражем Курджаком.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26867,'Враг из глубин','С присущей ему учтивостью вождь Гаррош любезно затребовал твоего присутствия в Огненной Пропасти – ты $gдолжен:должна; помочь нам отбить ее у Пламенеющего Клинка. Видимо, его укрепленный город Гарроша оказался не таким уж и неприступным, как он полагал.$B$BПоговори с каменным стражем Курджаком в Огненной Пропасти – уверена, он обрадуется квалифицированной помощи.','Поговорите с каменным стражем Курджаком.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Враг из глубин',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','С присущей ему учтивостью вождь Гаррош любезно затребовал твоего присутствия в Огненной Пропасти – ты $gдолжен:должна; помочь нам отбить ее у Пламенеющего Клинка. Видимо, его укрепленный город Гарроша оказался не таким уж и неприступным, как он полагал.$B$BПоговори с каменным стражем Курджаком в Огненной Пропасти – уверена, он обрадуется квалифицированной помощи.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с каменным стражем Курджаком.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26868,'Ось ужаса','А теперь просто захлопни пасть и помолчи, говорить буду я. Вот какой у меня план.$b$bВероятно гноллы с мурлоками устроят встречу где-то в этих краях. Так что воспользуйся этой моей искусной маскировкой под растение. Наденешь ее – будешь выглядеть, как растение. Потом подберись к Мохошкурам, союзничающим с мурлоками, и брось в них пахучий феромон, который ты $gдобыл:добыла;.$b$bПосле этого мурлоки начнут плеваться, а Мохошкуры еще дважды подумают о том, чтобы союзничать с этими ненормальными маленькими тварями!','Воспользуйтесь набором для искусной маскировки под растение, чтобы подобраться к представителю Мохошкуров и применить к нему мощные феромоны мурлоков.','Чудесно сработало, да? Может быть, теперь Кэдрелл оставит меня в покое, раз уж я спасла ему целый город и все такое!$B$BПолагаю, ты не осталась без награды.','Вернитесь к Каннари Пивной Бочке в Телсамар, что в Лок Модане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ось ужаса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А теперь просто захлопни пасть и помолчи, говорить буду я. Вот какой у меня план.$b$bВероятно гноллы с мурлоками устроят встречу где-то в этих краях. Так что воспользуйся этой моей искусной маскировкой под растение. Наденешь ее – будешь выглядеть, как растение. Потом подберись к Мохошкурам, союзничающим с мурлоками, и брось в них пахучий феромон, который ты $gдобыл:добыла;.$b$bПосле этого мурлоки начнут плеваться, а Мохошкуры еще дважды подумают о том, чтобы союзничать с этими ненормальными маленькими тварями!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь набором для искусной маскировки под растение, чтобы подобраться к представителю Мохошкуров и применить к нему мощные феромоны мурлоков.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Чудесно сработало, да? Может быть, теперь Кэдрелл оставит меня в покое, раз уж я спасла ему целый город и все такое!$B$BПолагаю, ты не осталась без награды.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Каннари Пивной Бочке в Телсамар, что в Лок Модане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26869,'Глубины глубин','Найдите пейнит в Гремящих глубинах.','<Вот он. Вот камень, за которым послал вас Диамант.>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Глубины глубин',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите пейнит в Гремящих глубинах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Вот он. Вот камень, за которым послал вас Диамант.>',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26870,'Очищение пещер','У Наралекса была благородная цель.$B$BОн хотел войти в Изумрудный Сон и превратить эту бесплодную землю в цветущий сад, каким она была прежде.$B$BНо его предали...$B$BПредали союзники – друиды-змеи, которым он доверял безраздельно. Как оказалось, эти друиды хотели не исцелить Степи, а подчинить их своей власти.$B$B$n, прежде чем пробудить Наралекса и вернуть покой в это священное место, мы должны истребить Повелителей змей. Их влияние распространилось уже слишком широко, и если их не убить, то у нас ничего не получится.','Я уже чувствую, как равновесие восстанавливается! Быстрее! Иди к Муйону и помоги ему пробудить Наралекса!','Вернитесь к Эбру.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Очищение пещер',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У Наралекса была благородная цель.$B$BОн хотел войти в Изумрудный Сон и превратить эту бесплодную землю в цветущий сад, каким она была прежде.$B$BНо его предали...$B$BПредали союзники – друиды-змеи, которым он доверял безраздельно. Как оказалось, эти друиды хотели не исцелить Степи, а подчинить их своей власти.$B$B$n, прежде чем пробудить Наралекса и вернуть покой в это священное место, мы должны истребить Повелителей змей. Их влияние распространилось уже слишком широко, и если их не убить, то у нас ничего не получится.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я уже чувствую, как равновесие восстанавливается! Быстрее! Иди к Муйону и помоги ему пробудить Наралекса!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Эбру.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (26871,'Один камень из многих','<Земля слегка дрожит, и знакомый тихий голос Диаманта раздается как будто бы из самого камня.>$b$bМолодец, |3-6($r).$b$bТы $gсделал:сделала; то, о чем я просил.$b$bБеги из пещеры, пока $gцел:цела;.$b$bНе забудь самоцвет.','Вернитесь с куском пейнита к Диаманту к Вратам Лортуны.','Отлично, смертный!$B$BЧервинты – одни из самых опасных наших врагов.$B$BДругим каменным лордам не стоит тебя недооценивать.','Ты жив. Это хорошо.$B$BСамоцвет с тобой?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Один камень из многих',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Земля слегка дрожит, и знакомый тихий голос Диаманта раздается как будто бы из самого камня.>$b$bМолодец, |3-6($r).$b$bТы $gсделал:сделала; то, о чем я просил.$b$bБеги из пещеры, пока $gцел:цела;.$b$bНе забудь самоцвет.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь с куском пейнита к Диаманту к Вратам Лортуны.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, смертный!$B$BЧервинты – одни из самых опасных наших врагов.$B$BДругим каменным лордам не стоит тебя недооценивать.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты жив. Это хорошо.$B$BСамоцвет с тобой?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26872,'Шкуры загадочных существ','Сколько бестий ты убил?','Вернитесь к Налпаку.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Шкуры загадочных существ',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Сколько бестий ты убил?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Налпаку.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26873,'Превентивные меры','В здешних пещерах растет один интересный цветок. Он обладает великой силой. Может найдешь его, $n?$B$BЭто достаточно редкий цветок. Называется змеецвет. Уверен, если собрать побольше, силы этих цветов хватит, чтобы прогнать кошмары Наралекса.$B$BК сожалению, змеецвет растет только в самых темных уголках в глубине пещер.','По поручению Налпака соберите 5 цветков змеецвета.','Замечательно, Гимндар. Надеюсь, этого хватит, чтобы прогнать кошмары.','Вернитесь к Налпаку.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Превентивные меры',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В здешних пещерах растет один интересный цветок. Он обладает великой силой. Может найдешь его, $n?$B$BЭто достаточно редкий цветок. Называется змеецвет. Уверен, если собрать побольше, силы этих цветов хватит, чтобы прогнать кошмары Наралекса.$B$BК сожалению, змеецвет растет только в самых темных уголках в глубине пещер.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По поручению Налпака соберите 5 цветков змеецвета.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Замечательно, Гимндар. Надеюсь, этого хватит, чтобы прогнать кошмары.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Налпаку.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26874,'Пробуждение Наралекса','Теперь, когда Повелители змей мертвы, поговорите с Муйоном. Он поможет вам пробудить Наралекса и покончить с этим кошмаром раз и навсегда.','Поговорите с Муйоном.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пробуждение Наралекса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда Повелители змей мертвы, поговорите с Муйоном. Он поможет вам пробудить Наралекса и покончить с этим кошмаром раз и навсегда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Муйоном.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26875,'Неумирающие сумерки','Здесь сумеречные сектанты! Они пытаются помешать ритуалу! Иди в дальние комнаты и помоги выбить их оттуда!','Убейте 12 захватчиков из Сумеречного Молота и 1 оскверненного землегнева.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Неумирающие сумерки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Здесь сумеречные сектанты! Они пытаются помешать ритуалу! Иди в дальние комнаты и помоги выбить их оттуда!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 захватчиков из Сумеречного Молота и 1 оскверненного землегнева.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`completedtext_loc8`) VALUES (26876,'Принесите верхний фрагмент столпа мира Марууту Камневязу в Храм Земли.') ON DUPLICATE KEY UPDATE `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите верхний фрагмент столпа мира Марууту Камневязу в Храм Земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26877,'Фрагмент внутри','$n, тебе нужно проникнуть в Пещеру Лавиниона, что на юго-востоке отсюда, и добыть центральный фрагмент столпа мира!','Найдите центральный фрагмент столпа мира.','[Deprecated] Return to King Oremantle at the Quaking Fields in Deepholm.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Фрагмент внутри',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, тебе нужно проникнуть в Пещеру Лавиниона, что на юго-востоке отсюда, и добыть центральный фрагмент столпа мира!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите центральный фрагмент столпа мира.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','[Deprecated] Return to King Oremantle at the Quaking Fields in Deepholm.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (26878,'Послушники Наралекса') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Послушники Наралекса',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26879,'Послушники Наралекса','$C, должен сказать, что это место не очень хорошо подходит для моих дел. Было бы оно поживее, я бы сумел стать самым богатым гоблином в истории!$b$b$gТакой:Такая:c; |3-6($c), как ты, $gдолжен:должна; видеть, какой у этих земель потенциал, ну или хотя бы тебе не должно быть безразлично состояние окружающей среды.$b$bПоговори с Налпаком, его можно найти в Пещерах Стенаний. Он ученик Наралекса, и мне кажется, что они – только это между нами – собираются навести порядок в этом проклятом месте! Это большой успех для меня!','Поговорите с Налпаком в Пещерах Стенаний.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Послушники Наралекса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$C, должен сказать, что это место не очень хорошо подходит для моих дел. Было бы оно поживее, я бы сумел стать самым богатым гоблином в истории!$b$b$gТакой:Такая:c; |3-6($c), как ты, $gдолжен:должна; видеть, какой у этих земель потенциал, ну или хотя бы тебе не должно быть безразлично состояние окружающей среды.$b$bПоговори с Налпаком, его можно найти в Пещерах Стенаний. Он ученик Наралекса, и мне кажется, что они – только это между нами – собираются навести порядок в этом проклятом месте! Это большой успех для меня!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Налпаком в Пещерах Стенаний.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (26880,'Gilneas City Unphase Cheat') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Gilneas City Unphase Cheat',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (26881,'Эшлан сделал доброе дело, прислав тебя. В этом пропитанном порчей месте и вправду замышляется что-то ужасное.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Эшлан сделал доброе дело, прислав тебя. В этом пропитанном порчей месте и вправду замышляется что-то ужасное.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26882,'Злодейство в Непроглядной Пучине','Добудьте голову Повелителя Сумрака Келриса.','Вернитесь к Эшлану.','Келриса нужно остановить!','Повелитель сумрака Келрис') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Злодейство в Непроглядной Пучине',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте голову Повелителя Сумрака Келриса.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Эшлану.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Келриса нужно остановить!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Повелитель сумрака Келрис',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26883,'Наступление сумерек','Черпая силу из старинных обрядов, посвященных древним богам Хаоса, Сумеречный Молот пытается вернуть своих темных покровителей и распространить смерть и ужас по всему миру.$b$bМы думаем, что Сумеречный Молот вступил в союз с нагами, и теперь они наращивают здесь свои силы.$b$bЧто бы ни затевалось в глубинах древнего храма, этим планам нельзя дать осуществиться.$b$bОбъяви же войну Молоту и вернись с доказательствами своих подвигов! Твои труды будут достойно вознаграждены.','Раздобудьте 3 подвески Сумерек.','Нынешняя Непроглядная Пучина когда-то в древности была храмом ночных эльфов. Там располагался лунный колодец невероятной силы. Кто знает, какое зло там теперь таится под властью Сумеречного Молота...$B$BТебе удалось хоть немного очистить храм от присутствия сектантов?','Вернитесь к Алувин.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наступление сумерек',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Черпая силу из старинных обрядов, посвященных древним богам Хаоса, Сумеречный Молот пытается вернуть своих темных покровителей и распространить смерть и ужас по всему миру.$b$bМы думаем, что Сумеречный Молот вступил в союз с нагами, и теперь они наращивают здесь свои силы.$b$bЧто бы ни затевалось в глубинах древнего храма, этим планам нельзя дать осуществиться.$b$bОбъяви же войну Молоту и вернись с доказательствами своих подвигов! Твои труды будут достойно вознаграждены.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте 3 подвески Сумерек.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Нынешняя Непроглядная Пучина когда-то в древности была храмом ночных эльфов. Там располагался лунный колодец невероятной силы. Кто знает, какое зло там теперь таится под властью Сумеречного Молота...$B$BТебе удалось хоть немного очистить храм от присутствия сектантов?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Алувин.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26884,'Исследование порчи','Эти глупцы, эльфы Крови, заигрывают с демонической магией. Разве они не видели, что случилось с нагами и сатирами Калимдора?$B$BБоюсь, эльфов Крови ждет аналогичная деформация. Азерот не должен породить еще одну расу ужасных монстров.$B$BЯ хочу изучить стволы головного мозга сатиров и наг, чтобы спрогнозировать судьбу син\'дорай. Постарайся не повредить стволы – мне нужны только идеальные образцы.','Соберите 8 оскверненных стволов мозга.','Как только у меня будет достаточно образцов, я сразу приступлю к работе. Изучив оскверненные стволы мозга сатиров и наг из Непроглядной Пучины, я постараюсь определить корреляцию между имеющимися мутациями.$B$BМожет быть, добытые знания помогут нам предотвратить схождение эльфов Крови к еще большему злу.','Вернитесь к Релвин.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Исследование порчи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти глупцы, эльфы Крови, заигрывают с демонической магией. Разве они не видели, что случилось с нагами и сатирами Калимдора?$B$BБоюсь, эльфов Крови ждет аналогичная деформация. Азерот не должен породить еще одну расу ужасных монстров.$B$BЯ хочу изучить стволы головного мозга сатиров и наг, чтобы спрогнозировать судьбу син\'дорай. Постарайся не повредить стволы – мне нужны только идеальные образцы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 оскверненных стволов мозга.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как только у меня будет достаточно образцов, я сразу приступлю к работе. Изучив оскверненные стволы мозга сатиров и наг из Непроглядной Пучины, я постараюсь определить корреляцию между имеющимися мутациями.$B$BМожет быть, добытые знания помогут нам предотвратить схождение эльфов Крови к еще большему злу.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Релвин.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26885,'Знание в пучине','Как курсант, я обязана собирать знания. Древние знания, могучие знания. Знания, открывающие пути. Знания, способные пробудить Тех-Что-Спят.$B$BХодят слухи о старинном манускрипте Лоргалиса, хранящемся на дне пруда Аск\'ара в ржавом железном сундуке. Это прежнее обиталище наших давно почивших предков. До того как их город обратился в руины, они обладали великими знаниями.$B$BПрошу тебя, поищи манускрипт. У меня не хватает сноровки идти дальше.','Отыщите манускрипт Лоргалиса.','Вернитесь к курсанту-часовому Иссаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Знание в пучине',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как курсант, я обязана собирать знания. Древние знания, могучие знания. Знания, открывающие пути. Знания, способные пробудить Тех-Что-Спят.$B$BХодят слухи о старинном манускрипте Лоргалиса, хранящемся на дне пруда Аск\'ара в ржавом железном сундуке. Это прежнее обиталище наших давно почивших предков. До того как их город обратился в руины, они обладали великими знаниями.$B$BПрошу тебя, поищи манускрипт. У меня не хватает сноровки идти дальше.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщите манускрипт Лоргалиса.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к курсанту-часовому Иссаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26886,'Побочная задача','Как ты уже $gзаметил:заметила;, орудия пришвартованного с восточной стороны корабля не прекращают пальбу. Несмотря на то, что смотреть, как свинцовый град обрушивается на гоблинов, довольно весело, мои друзья-гномы тоже попадают под огонь!$b$BЕсли бы ты $gмог:могла; прорваться сквозь огонь и забраться на корабль, то можно было бы добраться и до их командира. Скорее всего, сама команда представляет собой всего лишь кучку безмозглых идиотов, так что стоит справиться с командиром, и все будет в порядке.','Ну и отлично. Надеюсь, в тебя попало не слишком много пушечных ядер.','Вернитесь к Келси Стализвон в Бухту Сорванных Парусов, что в Танарисе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Побочная задача',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как ты уже $gзаметил:заметила;, орудия пришвартованного с восточной стороны корабля не прекращают пальбу. Несмотря на то, что смотреть, как свинцовый град обрушивается на гоблинов, довольно весело, мои друзья-гномы тоже попадают под огонь!$b$BЕсли бы ты $gмог:могла; прорваться сквозь огонь и забраться на корабль, то можно было бы добраться и до их командира. Скорее всего, сама команда представляет собой всего лишь кучку безмозглых идиотов, так что стоит справиться с командиром, и все будет в порядке.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну и отлично. Надеюсь, в тебя попало не слишком много пушечных ядер.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Келси Стализвон в Бухту Сорванных Парусов, что в Танарисе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26887,'Требуются пломбы','Больше золота! Мы же должны выразить свою признательность мистеру Гогельмогелю.$B$BИ только малая часть этого драгоценного металла отправится в Гномреган на разработку экспериментального оружия!','Пломбы у тебя?','Вернитесь к Келси Стализвон в Бухту Сорванных Парусов, что в Танарисе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Требуются пломбы',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Больше золота! Мы же должны выразить свою признательность мистеру Гогельмогелю.$B$BИ только малая часть этого драгоценного металла отправится в Гномреган на разработку экспериментального оружия!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Пломбы у тебя?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Келси Стализвон в Бухту Сорванных Парусов, что в Танарисе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26888,'Ужас из глубин','В самых темных закоулках Непроглядной Пучины обитает чудовище, порожденное древними богами. Нам он известен под именем Аку\'май.$B$BДревние боги и их слуги – серьезная угроза для нашего мира. Когда-то давным-давно они правили Азеротом и, боюсь, снова жаждут либо власти, либо разрушения мира в процессе ее захвата.$B$BАку\'май, $n, внушает невыразимый ужас. Нельзя позволить ему существовать. Уничтожь эту тварь.','Это чудовище наконец убито. Я чувствую, как его темное присутствие исчезает... навсегда.','Вернитесь к Дже\'неу Санкри.','Уродливый любимец древних богов.','Аку\'май') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ужас из глубин',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В самых темных закоулках Непроглядной Пучины обитает чудовище, порожденное древними богами. Нам он известен под именем Аку\'май.$B$BДревние боги и их слуги – серьезная угроза для нашего мира. Когда-то давным-давно они правили Азеротом и, боюсь, снова жаждут либо власти, либо разрушения мира в процессе ее захвата.$B$BАку\'май, $n, внушает невыразимый ужас. Нельзя позволить ему существовать. Уничтожь эту тварь.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это чудовище наконец убито. Я чувствую, как его темное присутствие исчезает... навсегда.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дже\'неу Санкри.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Уродливый любимец древних богов.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Аку\'май',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26889,'Вопли радости','Ох боженьки, хорошо же мы тут поработали!$B$B<Келси откашливается.>$B$BСлушай, $n, я хочу наконец-то очистить эту душегубку и с воплем радости убраться подальше от гоблинов. Если ты все еще защищаешь интересы Гномрегана и всего Альянса, отправляйся на стоянку бутлегеров к югу отсюда.$B$BПоговорит там с Зеке Волочилкинсом – и помни, любая помощь Хитрой Шестеренке приблизит нас к тому, чтобы навсегда изгнать картель Трюмных Вод из Танариса.','Поговорите с Зеке Волочилкинсом на стоянке бутлегеров.','Знаешь, обычно я предпочитаю не иметь дело с такими, как ты, но до меня дошли слухи о том, как много всего ты сделал для Хитрой Шестеренки. Ты мне нравишься, малыш.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вопли радости',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ох боженьки, хорошо же мы тут поработали!$B$B<Келси откашливается.>$B$BСлушай, $n, я хочу наконец-то очистить эту душегубку и с воплем радости убраться подальше от гоблинов. Если ты все еще защищаешь интересы Гномрегана и всего Альянса, отправляйся на стоянку бутлегеров к югу отсюда.$B$BПоговорит там с Зеке Волочилкинсом – и помни, любая помощь Хитрой Шестеренке приблизит нас к тому, чтобы навсегда изгнать картель Трюмных Вод из Танариса.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Зеке Волочилкинсом на стоянке бутлегеров.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Знаешь, обычно я предпочитаю не иметь дело с такими, как ты, но до меня дошли слухи о том, как много всего ты сделал для Хитрой Шестеренки. Ты мне нравишься, малыш.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`completedtext_loc8`) VALUES (26890,'В начале туннелей Непроглядной Пучины по стенам пещер можно найти большие сапфировые друзы. Мы заметили, что наги собирают эти кристаллы, и одновременно с этим их оружие становится необычайно мощным.$b$bПохоже, в этих кристаллах содержится великая сила стихий, и если их применить не как должно, то они могут стать мощным чародейским ингредиентом.$B$BТы мне не поможешь, $n? Непроглядная Пучина находится на Зорамском взморье к северу от нашей заставы.','Вернитесь к Дагруну Бушующему Молоту.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В начале туннелей Непроглядной Пучины по стенам пещер можно найти большие сапфировые друзы. Мы заметили, что наги собирают эти кристаллы, и одновременно с этим их оружие становится необычайно мощным.$b$bПохоже, в этих кристаллах содержится великая сила стихий, и если их применить не как должно, то они могут стать мощным чародейским ингредиентом.$B$BТы мне не поможешь, $n? Непроглядная Пучина находится на Зорамском взморье к северу от нашей заставы.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дагруну Бушующему Молоту.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26891,'Среди руин','Эти негодяи из Сумеречного Молота пробрались в Руины святилища Луны. Их присутствие приведет лишь к тому, что Стихии озлобятся на нас. $B$B$n, найди служителей культа Сумеречного Молота и отыщи в руинах глубинный камень. Он должен быть где-то поблизости в воде. В нем находится глубинный сердечник – устройство, которое при надлежащем считывании излагает историю всей деятельности Стихий. Если я его получу, мы со Служителями Земли, возможно, сумеем как-нибудь остановить их!','Извлеките глубинный сердечник.','Это именно то, что мне было нужно! Глубинный сердечник – неиссякаемый кладезь информации, которую мы сможем оттуда извлечь. Что бы ни затевал Сумеречный Молот – и уж поверь мне, ничего хорошего – мы с моими товарищами сумеем это выяснить.$B$BТы сегодня хорошо потрудился, и Служители Земли весьма благодарны тебе за помощь. Ты и всей Орде помог, и имеешь право гордиться собой.','Удалось ли тебе отыскать глубинный сердечник? Без него нам не понять, что именно затевает Сумеречный Молот.','Вернитесь к Дже\'неу Санкри.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Среди руин',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти негодяи из Сумеречного Молота пробрались в Руины святилища Луны. Их присутствие приведет лишь к тому, что Стихии озлобятся на нас. $B$B$n, найди служителей культа Сумеречного Молота и отыщи в руинах глубинный камень. Он должен быть где-то поблизости в воде. В нем находится глубинный сердечник – устройство, которое при надлежащем считывании излагает историю всей деятельности Стихий. Если я его получу, мы со Служителями Земли, возможно, сумеем как-нибудь остановить их!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Извлеките глубинный сердечник.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это именно то, что мне было нужно! Глубинный сердечник – неиссякаемый кладезь информации, которую мы сможем оттуда извлечь. Что бы ни затевал Сумеречный Молот – и уж поверь мне, ничего хорошего – мы с моими товарищами сумеем это выяснить.$B$BТы сегодня хорошо потрудился, и Служители Земли весьма благодарны тебе за помощь. Ты и всей Орде помог, и имеешь право гордиться собой.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось ли тебе отыскать глубинный сердечник? Без него нам не понять, что именно затевает Сумеречный Молот.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дже\'неу Санкри.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26892,'Во глубине глубин','Наги и культ Сумеречного Молота совместно работают над разрушением всего, чего мы здесь добились. Но хуже того – Дже\'неу уверяет, что чувствует присутствие древнего бога, ворочающегося где-то глубоко под нами.$B$BЕсли они хотят посеяв хаос, пожать бурю – они получат бурю.$B$BПослушай, $n. Срази их самых сильных воинов, посмотрим, как им это понравится.$B$BНо будь $gосторожен:осторожна;: Непроглядная Пучина полна затопленных проходов и боковых ответвлений, ведущих в пещеры. В них могут скрываться те, кого ты $gдолжен:должна; убить.','Убейте Гхаму-ра, леди Саревесс и Гелихаста.','Я даже отсюда слышу их крики! Может быть, они поймут, какая это глупость – желать возвращения древнего бога.','Вернитесь к Зейе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Во глубине глубин',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наги и культ Сумеречного Молота совместно работают над разрушением всего, чего мы здесь добились. Но хуже того – Дже\'неу уверяет, что чувствует присутствие древнего бога, ворочающегося где-то глубоко под нами.$B$BЕсли они хотят посеяв хаос, пожать бурю – они получат бурю.$B$BПослушай, $n. Срази их самых сильных воинов, посмотрим, как им это понравится.$B$BНо будь $gосторожен:осторожна;: Непроглядная Пучина полна затопленных проходов и боковых ответвлений, ведущих в пещеры. В них могут скрываться те, кого ты $gдолжен:должна; убить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Гхаму-ра, леди Саревесс и Гелихаста.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я даже отсюда слышу их крики! Может быть, они поймут, какая это глупость – желать возвращения древнего бога.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Зейе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (26893,'Непроглядная Пучина','Поговорите с Дже\'неу Санкри.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Непроглядная Пучина',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Дже\'неу Санкри.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26895,'Громодром!','Эй, дружище, что тебя интересует? Приключения, деньги, жестокость?$B$BЕсли последнее, то у меня есть для тебя отличная новость – в Прибамбасске только что вновь открылся Громодром! Да, много же им времени потребовалось на то, чтобы уладить все эти судебные тяжбы с пострадавшими, расплатиться с рэкетирами и комиссией по авторским правам... Но теперь Громодром снова распахнул свои двери перед самыми кровожадными и беспощадными бойцами вроде тебя!$B$BОтправляйся в Прибамбасск и скажи доктору Верняку, что ты хочешь участвовать. И друзей приводи!','Поговорите с доктором Верняком в Прибамбасске.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Громодром!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эй, дружище, что тебя интересует? Приключения, деньги, жестокость?$B$BЕсли последнее, то у меня есть для тебя отличная новость – в Прибамбасске только что вновь открылся Громодром! Да, много же им времени потребовалось на то, чтобы уладить все эти судебные тяжбы с пострадавшими, расплатиться с рэкетирами и комиссией по авторским правам... Но теперь Громодром снова распахнул свои двери перед самыми кровожадными и беспощадными бойцами вроде тебя!$B$BОтправляйся в Прибамбасск и скажи доктору Верняку, что ты хочешь участвовать. И друзей приводи!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с доктором Верняком в Прибамбасске.',`objectives_loc8`);
