INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26898,'Непроглядная Пучина','Меня очень волнует судьба этих лесов, |3-6($c). Здесь все кажется ужасным, но я лучше встречусь с бойцами Орды лицом к лицу, чем буду смотреть, как они безжалостно уничтожают деревья, прорубая себе дорогу.$B$BОтправляйся на запад, в Непроглядную Пучину. Когда попадешь туда, найди часового Алувин. Она добрый друг и поможет в трудную минуту.$B$BСейчас ей угрожают орки с заставы Зорам\'гар. Если они займут Пучину, то в своем безумии уничтожат каждое дерево.','Поговорите с часовым Алувин.','Слава Элуне, ты здесь! Мы будем рады любой помощи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Непроглядная Пучина',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Меня очень волнует судьба этих лесов, |3-6($c). Здесь все кажется ужасным, но я лучше встречусь с бойцами Орды лицом к лицу, чем буду смотреть, как они безжалостно уничтожают деревья, прорубая себе дорогу.$B$BОтправляйся на запад, в Непроглядную Пучину. Когда попадешь туда, найди часового Алувин. Она добрый друг и поможет в трудную минуту.$B$BСейчас ей угрожают орки с заставы Зорам\'гар. Если они займут Пучину, то в своем безумии уничтожат каждое дерево.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с часовым Алувин.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Слава Элуне, ты здесь! Мы будем рады любой помощи.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26899,'Месть... награда...','Вернитесь к пылающему искоренителю.') ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Месть... награда...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к пылающему искоренителю.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26900,'Agamaggan','I sense a being of immense power within these twisted thorns, $n. The entire area has come alive at its presence.$B$BIt must be the Spirit of Agamaggan! He was one of the first and most powerful beings to ever live – the Quilboar worship him fervently.$B$BAll the vines you see across the land are a result of his blood; of his sacrifice to save Azeroth in the War of the Ancients.$B$BIf there\'s any being that could steer the Quilboar towards their noble roots, it would be him.$B$BYou must seek him out.','Find the Spirit of Agamaggan.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Agamaggan',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','I sense a being of immense power within these twisted thorns, $n. The entire area has come alive at its presence.$B$BIt must be the Spirit of Agamaggan! He was one of the first and most powerful beings to ever live – the Quilboar worship him fervently.$B$BAll the vines you see across the land are a result of his blood; of his sacrifice to save Azeroth in the War of the Ancients.$B$BIf there\'s any being that could steer the Quilboar towards their noble roots, it would be him.$B$BYou must seek him out.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Find the Spirit of Agamaggan.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26901,'Груды гуано','Разыщите 1 кучу гуано летучих мышей Лабиринтов.','Отлично, Виндфурик! Это именно то, что нужно!','Вернитесь к Ольду Каменному Копью.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Груды гуано',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите 1 кучу гуано летучих мышей Лабиринтов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, Виндфурик! Это именно то, что нужно!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ольду Каменному Копью.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (26902,'Get Back to Town Accepted Tracking Event') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Get Back to Town Accepted Tracking Event',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (26903,'Импортер Вилликс','А вот и помощь пришла! Лучше поздно, чем никогда!$B$BТы даже не представляешь, сколько времени я здесь сижу. Уже и не помню, как там на воле.$B$BЯ, знаешь ли, предприниматель. А для предпринимателя главное – прибыль. И вот я узнал, что свиные рыльца изрядно поднялись в цене. И подумал – тут можно сделать хорошие деньги, причем легкие деньги. Как видишь, это была не самая удачная моя идея!$B$BКак бы там ни было, если поможешь мне выбраться отсюда, я в долгу не останусь.','Помогите импортеру Вилликсу выбраться из Лабиринтов Иглошкурых.','Еще раз спасибо, дружище! Я говорил, что в долгу не останусь, и слово свое держу.','Помочь импортеру Вилликсу сбежать из Лабиринтов Иглошкурых','Поговорите с импортером Вилликсом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Импортер Вилликс',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А вот и помощь пришла! Лучше поздно, чем никогда!$B$BТы даже не представляешь, сколько времени я здесь сижу. Уже и не помню, как там на воле.$B$BЯ, знаешь ли, предприниматель. А для предпринимателя главное – прибыль. И вот я узнал, что свиные рыльца изрядно поднялись в цене. И подумал – тут можно сделать хорошие деньги, причем легкие деньги. Как видишь, это была не самая удачная моя идея!$B$BКак бы там ни было, если поможешь мне выбраться отсюда, я в долгу не останусь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Помогите импортеру Вилликсу выбраться из Лабиринтов Иглошкурых.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Еще раз спасибо, дружище! Я говорил, что в долгу не останусь, и слово свое держу.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Помочь импортеру Вилликсу сбежать из Лабиринтов Иглошкурых',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с импортером Вилликсом.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26905,'Благословение Агамаггана','Убейте Чарлгу Остробок и вырежьте у нее сердце.','Прими от меня этот дар. Сегодня ты заслужил мое благословение.','<Дух Агамаггана пристально смотрит на вас и ждет, что вы скажете.>','Вернитесь к духу Агамаггана.','Принеси мне ее сердце!!!','Чарлга Остробок') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Благословение Агамаггана',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Чарлгу Остробок и вырежьте у нее сердце.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прими от меня этот дар. Сегодня ты заслужил мое благословение.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Дух Агамаггана пристально смотрит на вас и ждет, что вы скажете.>',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к духу Агамаггана.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Принеси мне ее сердце!!!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Чарлга Остробок',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26906,'Агамагган','В этих зарослях скрывается какое-то могучее существо. Я его чувствую... Здесь все им пропитано, $n.$B$BЭто, должно быть, дух Агамаггана – одного из первых существ, населявших Азерот! Свинобразы поклонялись ему, как богу.$B$BВсе эти виноградные лозы – они выросли из его крови, пролившейся на землю. То была его жертва во имя спасения Азерота в Войне древних.$B$BЕсли кто-то и напомнит свинобразам об их благородных корнях, так это он, легендарный Древний Боров.$B$BТебе нужно его разыскать.','Поговорите с духом Агамаггана.','<Дух Агамаггана смотрит на вас. У вас в голове звучит его голос.>$B$BЯ ждал тебя. Ждал, что ты придешь.','Test','Разыщите его.','Дух Агамаггана') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Агамагган',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В этих зарослях скрывается какое-то могучее существо. Я его чувствую... Здесь все им пропитано, $n.$B$BЭто, должно быть, дух Агамаггана – одного из первых существ, населявших Азерот! Свинобразы поклонялись ему, как богу.$B$BВсе эти виноградные лозы – они выросли из его крови, пролившейся на землю. То была его жертва во имя спасения Азерота в Войне древних.$B$BЕсли кто-то и напомнит свинобразам об их благородных корнях, так это он, легендарный Древний Боров.$B$BТебе нужно его разыскать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с духом Агамаггана.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Дух Агамаггана смотрит на вас. У вас в голове звучит его голос.>$B$BЯ ждал тебя. Ждал, что ты придешь.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Test',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Разыщите его.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Дух Агамаггана',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26907,'Их надо остановить!','Отлично сработано. Впавший в ярость Агателос загубил бы немало невинных жизней.','Вернитесь к Ольду Каменному Копью.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Их надо остановить!',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично сработано. Впавший в ярость Агателос загубил бы немало невинных жизней.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ольду Каменному Копью.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26908,'Тернистые трудности','Поговорите с Ольдом Каменным Копьем.','Только такой бравый воин, как ты, может храбро отправиться навстречу любой опасности.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тернистые трудности',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Ольдом Каменным Копьем.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Только такой бравый воин, как ты, может храбро отправиться навстречу любой опасности.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26909,'Осколки камня','Древние камни разбросаны в этих землях. Стихии, стекающиеся к камням, оберегают их.$b$bЭто места огромной силы, самое большое из них находится к западу от Павшего Молота. Ни одна душа туда не попадает, но если отправиться туда в одиночестве, можно услышать шепот самой земли.$b$bЯ уже давно там не был... но наши бойцы говорили мне, что шепот снова стал слышен. Ты не посмотришь? Узнай, действительно ли камни снова говорят.','Исследуйте кристаллы Мизраэль.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Осколки камня',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Древние камни разбросаны в этих землях. Стихии, стекающиеся к камням, оберегают их.$b$bЭто места огромной силы, самое большое из них находится к западу от Павшего Молота. Ни одна душа туда не попадает, но если отправиться туда в одиночестве, можно услышать шепот самой земли.$b$bЯ уже давно там не был... но наши бойцы говорили мне, что шепот снова стал слышен. Ты не посмотришь? Узнай, действительно ли камни снова говорят.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Исследуйте кристаллы Мизраэль.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (26911,'История Мизраэль','Когда камень затихает, вы уходите со смутным ощущением тревоги. Что-то не так.$b$bВозможно, о том, что вы уже сделали, следует рассказать Заруку.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','История Мизраэль',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда камень затихает, вы уходите со смутным ощущением тревоги. Что-то не так.$b$bВозможно, о том, что вы уже сделали, следует рассказать Заруку.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26912,'Выпущенная принцесса','Мизраэль мошенница. С давних времен она находится в плену, поскольку обладает огромной силой, так должно оставаться и впредь.$b$bТы $gдолжен:должна; встретиться с ней лицом к лицу у кристаллов Мизраэль, там, где вы впервые разговаривали. Призови ее при помощи этого свитка, и когда она выйдет на поверхность, победи ее. Потом возьми с ее тела мистические оковы и помести их на кристаллы, чтобы она больше не вырвалась.$b$bУдачи, $n... и пусть мое прошлое больше не тревожит тебя.','Призовите к кристаллам Мизраэль и победите ее.','Когда мистические оковы помещены вокруг кристаллов, откуда-то из глубины раздается нечеловеческий вой, переходящий в рычание.$B$BКристаллы Мизраэль больше не излучают тепла и ощущения безопасности, как это было раньше. Теперь в их пульсации чувствуется открытая угроза... как будто существо внизу, под ними, исходит злобой, направленной на поверхность.','Сейчас кристаллы Мизраэль необычно тихие.','Вернитесь к кристаллам Мизраэль на Нагорье Арати.','Освободи ее… и уничтожь.','Мизраэль') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Выпущенная принцесса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мизраэль мошенница. С давних времен она находится в плену, поскольку обладает огромной силой, так должно оставаться и впредь.$b$bТы $gдолжен:должна; встретиться с ней лицом к лицу у кристаллов Мизраэль, там, где вы впервые разговаривали. Призови ее при помощи этого свитка, и когда она выйдет на поверхность, победи ее. Потом возьми с ее тела мистические оковы и помести их на кристаллы, чтобы она больше не вырвалась.$b$bУдачи, $n... и пусть мое прошлое больше не тревожит тебя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Призовите к кристаллам Мизраэль и победите ее.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Когда мистические оковы помещены вокруг кристаллов, откуда-то из глубины раздается нечеловеческий вой, переходящий в рычание.$B$BКристаллы Мизраэль больше не излучают тепла и ощущения безопасности, как это было раньше. Теперь в их пульсации чувствуется открытая угроза... как будто существо внизу, под ними, исходит злобой, направленной на поверхность.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Сейчас кристаллы Мизраэль необычно тихие.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к кристаллам Мизраэль на Нагорье Арати.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Освободи ее… и уничтожь.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Мизраэль',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26920,'Битва за Андорал','Скорее, $n... У нас совсем нет времени.$B$BАндорал в самом эпицентре войны между Отрекшимися, Альянсом и Плетью. Леди Сильвана поставила во главе войск одного из своих лучших рыцарей смерти, но я уверен, она не откажется от любой помощи. Теперь, когда Артас мертв, Отрекшиеся получили шанс захватить Андорал.$B$BПоговори с дрессировщиком нетопырей Тимоти Каннингхемом, когда будешь $gготов:готова;, и он отправит тебя в первую битву.','Отчитайтесь перед Кольтирой Ткачом Смерти в Андорале в Западных Чумных землях.','Поговорите с Кольтирой Ткачом Смерти в Андорале в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Битва за Андорал',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Скорее, $n... У нас совсем нет времени.$B$BАндорал в самом эпицентре войны между Отрекшимися, Альянсом и Плетью. Леди Сильвана поставила во главе войск одного из своих лучших рыцарей смерти, но я уверен, она не откажется от любой помощи. Теперь, когда Артас мертв, Отрекшиеся получили шанс захватить Андорал.$B$BПоговори с дрессировщиком нетопырей Тимоти Каннингхемом, когда будешь $gготов:готова;, и он отправит тебя в первую битву.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отчитайтесь перед Кольтирой Ткачом Смерти в Андорале в Западных Чумных землях.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Кольтирой Ткачом Смерти в Андорале в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26921,'Сначала Плеть... Потом Альянс','Армию Плети здесь, в Андорале, ведет в атаку Темный магистр Гандлинг из культа Проклятых. Войска Альянса возглавляет мой давний знакомый – Тассариан. Если мы хотим выиграть битву за Андорал, нужно победить обоих – только по очереди.$B$BЯ хорошо знаю Тассариана и уверен, что первым делом он возьмется за Плеть. Мы поступим так же.$B$BРасправься с теми воинами Плети, что послабее. Нужно проредить их ряды. А потом придет очередь Альянса.','Уничтожьте 15 иссохших воинов Плети в Андорале.','Вернитесь к Кольтире Ткачу Смерти в Андорал в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сначала Плеть... Потом Альянс',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Армию Плети здесь, в Андорале, ведет в атаку Темный магистр Гандлинг из культа Проклятых. Войска Альянса возглавляет мой давний знакомый – Тассариан. Если мы хотим выиграть битву за Андорал, нужно победить обоих – только по очереди.$B$BЯ хорошо знаю Тассариана и уверен, что первым делом он возьмется за Плеть. Мы поступим так же.$B$BРасправься с теми воинами Плети, что послабее. Нужно проредить их ряды. А потом придет очередь Альянса.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 15 иссохших воинов Плети в Андорале.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кольтире Ткачу Смерти в Андорал в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26922,'Бесконечный поток','Араж Призыватель усиливает оборону Плети простыми скелетами... эта армия слабаков задавит если не силой, так числом. Он созывает души в северных башнях Андорала, и оттуда скелеты извергаются в чудовищных количествах. Но я знаю, как выйти из ситуации!$B$B<Джерл передает вам несколько гранат.>$B$BДействуют они просто. Бросаешь в костяного стража Плети... ну или в толпу скелетов... и они разлетаются на мелкие косточки.','Подорвите 5 костяных берсерков и уничтожьте костяного стража Плети ручными гранатами Джерла.','Эти гранаты просто взрывчатка, не более. Хотя я и член Королевского фармацевтического общества, но понимаю, что некоторые проблемы не решить, насылая чуму.','Вернитесь к Джерлу Дональду в Андорал в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бесконечный поток',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Араж Призыватель усиливает оборону Плети простыми скелетами... эта армия слабаков задавит если не силой, так числом. Он созывает души в северных башнях Андорала, и оттуда скелеты извергаются в чудовищных количествах. Но я знаю, как выйти из ситуации!$B$B<Джерл передает вам несколько гранат.>$B$BДействуют они просто. Бросаешь в костяного стража Плети... ну или в толпу скелетов... и они разлетаются на мелкие косточки.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Подорвите 5 костяных берсерков и уничтожьте костяного стража Плети ручными гранатами Джерла.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Эти гранаты просто взрывчатка, не более. Хотя я и член Королевского фармацевтического общества, но понимаю, что некоторые проблемы не решить, насылая чуму.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джерлу Дональду в Андорал в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26923,'Боевые машины','Пока здесь орудуют эти чудовища, вам Плети не одолеть. Кольтира все кричит, что их стало меньше, но в Андорале это лучшее оружие Плети разбрасывает моих стражей смерти, как тряпичных кукол.$B$BТакого я не потерплю. $n, отправляйся на поле боя и уничтожь этих тварей.','Уничтожьте 6 пустобрюхих громадин в Андорале.','Теперь, когда нам не угрожают громадины, победить Плеть ничего не стоит.$B$BПравда, того же нельзя сказать об Альянсе... Но тебя это не касается. По крайней мере, пока.','Вернитесь к Линдси Черное Солнце в Андорал в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Боевые машины',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пока здесь орудуют эти чудовища, вам Плети не одолеть. Кольтира все кричит, что их стало меньше, но в Андорале это лучшее оружие Плети разбрасывает моих стражей смерти, как тряпичных кукол.$B$BТакого я не потерплю. $n, отправляйся на поле боя и уничтожь этих тварей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 6 пустобрюхих громадин в Андорале.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь, когда нам не угрожают громадины, победить Плеть ничего не стоит.$B$BПравда, того же нельзя сказать об Альянсе... Но тебя это не касается. По крайней мере, пока.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Линдси Черное Солнце в Андорал в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26924,'Некроректор','Некроситет – одна из немногих цитаделей Плети, оставшихся к западу от Тондрорила. Ректор Некроситета, сектант по имени темный магистр Гандлинг, появился на поле боя.$B$BЭто станет его последней ошибкой.$B$BТы найдешь этого самого Гандлинга на площади возле южной окраины города. Сразись с ним и измотай до крайности. А я помогу его прикончить.','Убейте в Андорале темного магистра Гандлинга.','Вернитесь к Кольтире Ткачу Смерти в Андорал в Западных Чумных землях.','Ректор Некроситета, предводитель Плети в Андорале.','Темный магистр Гандлинг') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Некроректор',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Некроситет – одна из немногих цитаделей Плети, оставшихся к западу от Тондрорила. Ректор Некроситета, сектант по имени темный магистр Гандлинг, появился на поле боя.$B$BЭто станет его последней ошибкой.$B$BТы найдешь этого самого Гандлинга на площади возле южной окраины города. Сразись с ним и измотай до крайности. А я помогу его прикончить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте в Андорале темного магистра Гандлинга.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кольтире Ткачу Смерти в Андорал в Западных Чумных землях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Ректор Некроситета, предводитель Плети в Андорале.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Темный магистр Гандлинг',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26925,'Араж Призыватель','Теперь, когда с врагом покончено, пришло время разобраться с самим Аражем и воспользоваться его оберегом. Ты, наверное, его уже $gвидел:видела; где-нибудь у фонтана в центре города.$B$BПрихвати с собой мои гранаты. С Аражем справиться они не помогут, но весьма пригодятся, если он вызовет своих скелетов.','Убейте Аража Призывателя. С костяными берсерками справляйтесь с помощью ручных гранат Джерла.','Вернитесь к Кольтире Ткачу Смерти в Андорал в Западных Чумных землях.','Не забудь, мои гранаты помогут справиться с этими скелетами!','Араж Призыватель') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Араж Призыватель',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда с врагом покончено, пришло время разобраться с самим Аражем и воспользоваться его оберегом. Ты, наверное, его уже $gвидел:видела; где-нибудь у фонтана в центре города.$B$BПрихвати с собой мои гранаты. С Аражем справиться они не помогут, но весьма пригодятся, если он вызовет своих скелетов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Аража Призывателя. С костяными берсерками справляйтесь с помощью ручных гранат Джерла.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кольтире Ткачу Смерти в Андорал в Западных Чумных землях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Не забудь, мои гранаты помогут справиться с этими скелетами!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Араж Призыватель',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26926,'Сиюминутная победа','Отрекшиеся победили, и наши войска до сих пор сильны. Военная стратегия предписывает немедленно нанести удар Альянсу, пока они зализывают раны и не ждут нападения. Но у меня другой план...$B$BМы выждем. Атакуем Тассариана и его войска, когда пробьет нужный час. А пока поговори с Рондой Молвер и лети в Бастион, что на западной границе Чумных земель. Верховный палач Деррингтон даст тебе следующее назначение.$B$BКогда снова понадобишься в Андорале, я сообщу.','Доложитесь верховному палачу Деррингтону в Бастионе в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сиюминутная победа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Отрекшиеся победили, и наши войска до сих пор сильны. Военная стратегия предписывает немедленно нанести удар Альянсу, пока они зализывают раны и не ждут нападения. Но у меня другой план...$B$BМы выждем. Атакуем Тассариана и его войска, когда пробьет нужный час. А пока поговори с Рондой Молвер и лети в Бастион, что на западной границе Чумных земель. Верховный палач Деррингтон даст тебе следующее назначение.$B$BКогда снова понадобишься в Андорале, я сообщу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доложитесь верховному палачу Деррингтону в Бастионе в Тирисфальских лесах.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26927,'Откуда ни возьмись – мурлоки!','Так, значит, трогги работают на кобольдов, а кобольды работают на гноллов. Должно быть, гноллы перебрались сюда из Болотины.$b$bОткуда я знаю? Ну, они захватили с собой друзей. Мурлоки из племени Синежабрых кишмя кишат на месте бывшего озера Лок, а раньше их там никогда не бывало.$b$bВредители есть вредители, но то, что они объединились, настораживает. Я хочу, чтобы ты $gпоговорил:поговорила; с Каннари Пивной Бочкой. В этих местах она одна из наших лучших охотниц. Она расскажет, как управиться с мурлоками, если, конечно, ты сможешь оторвать ее от кружки на достаточно долгое время.','Поговорите с Каннари Пивной Бочкой.','Мурлоки? Конечно, я охочусь на мурлоков.$B$BИ каждая из этих вонючих тварей получила по заслугам! Слышишь меня?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Откуда ни возьмись – мурлоки!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Так, значит, трогги работают на кобольдов, а кобольды работают на гноллов. Должно быть, гноллы перебрались сюда из Болотины.$b$bОткуда я знаю? Ну, они захватили с собой друзей. Мурлоки из племени Синежабрых кишмя кишат на месте бывшего озера Лок, а раньше их там никогда не бывало.$b$bВредители есть вредители, но то, что они объединились, настораживает. Я хочу, чтобы ты $gпоговорил:поговорила; с Каннари Пивной Бочкой. В этих местах она одна из наших лучших охотниц. Она расскажет, как управиться с мурлоками, если, конечно, ты сможешь оторвать ее от кружки на достаточно долгое время.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Каннари Пивной Бочкой.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мурлоки? Конечно, я охочусь на мурлоков.$B$BИ каждая из этих вонючих тварей получила по заслугам! Слышишь меня?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26928,'Запахло новыми идеями','Мурлоки работают с гноллами? Обхохочешься! Ну, если их просто убивать – это не сильно поможет. Слишком уж их много.$b$bНо у меня есть план, котелок-то у меня варит. Эти мурлоки – они пахнут. Они метят предметы, и когда другой мурлок чувствует этот запах, он ужасно бесится! Это для них отличная наживка.$b$bВ общем, у них есть небольшие ароматические железы, которые испускают такой запах. Иди и принеси мне связку этих желез.','Добудьте 7 ароматических желез мурлоков из племени Синежабрых.','Фу! Какое зловоние.$B$BА теперь приготовься, потому что я собираюсь поразить тебя тем, что осталось от моих мозгов.','Вернитесь к Каннари Пивной Бочке в Телсамар, что в Лок Модане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Запахло новыми идеями',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мурлоки работают с гноллами? Обхохочешься! Ну, если их просто убивать – это не сильно поможет. Слишком уж их много.$b$bНо у меня есть план, котелок-то у меня варит. Эти мурлоки – они пахнут. Они метят предметы, и когда другой мурлок чувствует этот запах, он ужасно бесится! Это для них отличная наживка.$b$bВ общем, у них есть небольшие ароматические железы, которые испускают такой запах. Иди и принеси мне связку этих желез.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 7 ароматических желез мурлоков из племени Синежабрых.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Фу! Какое зловоние.$B$BА теперь приготовься, потому что я собираюсь поразить тебя тем, что осталось от моих мозгов.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Каннари Пивной Бочке в Телсамар, что в Лок Модане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26929,'Партия кроколисков','Пока ты носишься тут вокруг, занимаясь всякой ерундой, не поможешь ли заодно и мне?$b$bОбычно я ловлю кроколисков в озере, но в свете определенных событий посижу-ка лучше здесь. Надеюсь, ты проявишь вежливость и не станешь меня за это осуждать.$b$bТак что, если ты будешь так $gлюбезен:любезна; принести мне немного челюстей кроколисков, я тебе за это заплачу. Практически чистыми деньгами.','Соберите 6 челюстей кроколисков.','Вернитесь к Каннари Пивной Бочке в Телсамар, что в Лок Модане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Партия кроколисков',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пока ты носишься тут вокруг, занимаясь всякой ерундой, не поможешь ли заодно и мне?$b$bОбычно я ловлю кроколисков в озере, но в свете определенных событий посижу-ка лучше здесь. Надеюсь, ты проявишь вежливость и не станешь меня за это осуждать.$b$bТак что, если ты будешь так $gлюбезен:любезна; принести мне немного челюстей кроколисков, я тебе за это заплачу. Практически чистыми деньгами.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 6 челюстей кроколисков.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Каннари Пивной Бочке в Телсамар, что в Лок Модане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (26930,'После ордена','Мы одерживаем победу за победой, $n. От Алого ордена, который житья не давал Отрекшимся, уже почти ничего не осталось. Пока еще они сидят в своем монастыре в Тирисфале, но мы уже выкурили их из Дольного Очага и Длани Тира, а это далеко на востоке.$B$BНа прошлой неделе нам донесли о небольшом лагере Алого ордена на востоке от поля Джанис. Меня терзают смутные сомнения – а его точно уничтожили? Так что отправляйся туда и проверь.','Разведайте лагерь Алого ордена, расположенный к востоку от поля Джанис в Западных Чумных землях.','Лагерь Алого ордена обследован','Вернитесь к верховному палачу Деррингтону в Бастион в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','После ордена',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы одерживаем победу за победой, $n. От Алого ордена, который житья не давал Отрекшимся, уже почти ничего не осталось. Пока еще они сидят в своем монастыре в Тирисфале, но мы уже выкурили их из Дольного Очага и Длани Тира, а это далеко на востоке.$B$BНа прошлой неделе нам донесли о небольшом лагере Алого ордена на востоке от поля Джанис. Меня терзают смутные сомнения – а его точно уничтожили? Так что отправляйся туда и проверь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разведайте лагерь Алого ордена, расположенный к востоку от поля Джанис в Западных Чумных землях.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Лагерь Алого ордена обследован',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному палачу Деррингтону в Бастион в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26931,'Лисы и гончие','Мерзавцы из Альянса ходят по Чумным землям как у себя дома. Но мы не позволим им это! Эта страна по праву принадлежит Темной Госпоже!$B$BБитва за Андорал близится к концу, и силы Альянса, захватившие Чумные земли, рассеиваются. Некоторых из них ты можешь найти прямо на востоке отсюда – на лис охотятся. Покажи им, что это – земля Отрекшихся!$B$BУничтожь охотников. Прикончи их охотничьих псов. Ну и для полноты картины перебей и лис, на которых они охотились.','Убейте 4 альянсовых охотников на лис, 4 бульмастифов и 4 белохвостых лисиц в Чумных землях.','Приятно сознавать, что этих охотников здесь больше нет. Но с Альянсом мы еще не покончили...','Вернитесь к жрице тени Вандис в Бастион в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лисы и гончие',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мерзавцы из Альянса ходят по Чумным землям как у себя дома. Но мы не позволим им это! Эта страна по праву принадлежит Темной Госпоже!$B$BБитва за Андорал близится к концу, и силы Альянса, захватившие Чумные земли, рассеиваются. Некоторых из них ты можешь найти прямо на востоке отсюда – на лис охотятся. Покажи им, что это – земля Отрекшихся!$B$BУничтожь охотников. Прикончи их охотничьих псов. Ну и для полноты картины перебей и лис, на которых они охотились.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 4 альянсовых охотников на лис, 4 бульмастифов и 4 белохвостых лисиц в Чумных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Приятно сознавать, что этих охотников здесь больше нет. Но с Альянсом мы еще не покончили...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к жрице тени Вандис в Бастион в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26932,'Конец канюкам','Из-за взрыва Каменной Плотины пересохло почти все озеро Лок. Произошла ужасная экологическая катастрофа.$b$bИ не думай, что это не затронуло и нас, дворфов! У нас не только кончилась рыба. Большая территория покрыта телами погибших жесткозубов, которые лежат на солнце и разлагаются. Их находят канюки, которые потом распространяют грязь и заразу по окрестностям города.$b$bЯ не могу просить тебя убрать все это, но не займешься ли ты канюками? Даже если убить всего нескольких, это уже поможет.','Убейте 8 озерных канюков.','Вернитесь к горному пехотинцу Кэдреллу в Телсамар, что в Лок Модане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Конец канюкам',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Из-за взрыва Каменной Плотины пересохло почти все озеро Лок. Произошла ужасная экологическая катастрофа.$b$bИ не думай, что это не затронуло и нас, дворфов! У нас не только кончилась рыба. Большая территория покрыта телами погибших жесткозубов, которые лежат на солнце и разлагаются. Их находят канюки, которые потом распространяют грязь и заразу по окрестностям города.$b$bЯ не могу просить тебя убрать все это, но не займешься ли ты канюками? Даже если убить всего нескольких, это уже поможет.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 озерных канюков.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к горному пехотинцу Кэдреллу в Телсамар, что в Лок Модане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26933,'Мечи и орала','Люди, возделывающие поле Джанис, вовсе не фермеры. Это солдаты.$B$BВойскам Тассариана нужен провиант, вот он и отправил часть сил Альянса к северу от Андорала обрабатывать поле Джанис. Хотя битва при Андорале уже отгремела, грядет другая... в которой Отрекшиеся будут сражаться с людьми. Если перебить этих солдат, то силы Темной Госпожи получат решительное преимущество.','Убейте 9 работников Альянса на поле Джанис.','Ха-ха! Надеюсь, они вернутся к работе – уже как зомби.','Вернитесь к жрице тени Вандис в Бастион в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мечи и орала',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Люди, возделывающие поле Джанис, вовсе не фермеры. Это солдаты.$B$BВойскам Тассариана нужен провиант, вот он и отправил часть сил Альянса к северу от Андорала обрабатывать поле Джанис. Хотя битва при Андорале уже отгремела, грядет другая... в которой Отрекшиеся будут сражаться с людьми. Если перебить этих солдат, то силы Темной Госпожи получат решительное преимущество.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 9 работников Альянса на поле Джанис.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ха-ха! Надеюсь, они вернутся к работе – уже как зомби.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к жрице тени Вандис в Бастион в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26934,'Скрытая болезнь','Мне нужна чумная трава для... одного эксперимента. Члены Серебряного Авангарда и друиды Кенария чересчур хорошо потрудились, очищая эти земли. И вот теперь я не могу найти поблизости необходимых реагентов.$B$BПравда, следы болезни еще остались в здешней природе. Убей больного черного медведя, а потом сорви траву, на которой он будет лежать. Не лучший вариант, но, как говорится, на безрыбье...','Убейте больных черных медведей в Западных Чумных землях, а затем сорвите 20 пучков чумной поросли, на которой они лежали.','Вернитесь к аптекарю Дитерсу в Бастион в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Скрытая болезнь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне нужна чумная трава для... одного эксперимента. Члены Серебряного Авангарда и друиды Кенария чересчур хорошо потрудились, очищая эти земли. И вот теперь я не могу найти поблизости необходимых реагентов.$B$BПравда, следы болезни еще остались в здешней природе. Убей больного черного медведя, а потом сорви траву, на которой он будет лежать. Не лучший вариант, но, как говорится, на безрыбье...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте больных черных медведей в Западных Чумных землях, а затем сорвите 20 пучков чумной поросли, на которой они лежали.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к аптекарю Дитерсу в Бастион в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26935,'Лесопилка Северного Кряжа','Здесь, в Чумных Землях, мы не единственные агенты священной войны. Наша штаб-квартира, Дольный Очаг, находится к северу отсюда. А еще дальше к северу есть небольшая лесопилка, тоже наша.$B$BНа лесопилке я в основном держу связь с Натаниэлем Дамахом. Советую тебе поговорить с ним, если вдруг окажешься в той части леса.','Поговорите с Натаниэлем Дамахом на лесопилке Северного Кряжа в Западных Чумных землях.','Поговорите с Натаниэлем Дамахом на лесопилке Северного Кряжа в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лесопилка Северного Кряжа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Здесь, в Чумных Землях, мы не единственные агенты священной войны. Наша штаб-квартира, Дольный Очаг, находится к северу отсюда. А еще дальше к северу есть небольшая лесопилка, тоже наша.$B$BНа лесопилке я в основном держу связь с Натаниэлем Дамахом. Советую тебе поговорить с ним, если вдруг окажешься в той части леса.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Натаниэлем Дамахом на лесопилке Северного Кряжа в Западных Чумных землях.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Натаниэлем Дамахом на лесопилке Северного Кряжа в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (26936,'Поехали!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поехали!',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (26937,'Когда смерть еще не конец','Вернитесь к Линдси Черное Солнце на Обуглившуюся заставу, что в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Когда смерть еще не конец',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Линдси Черное Солнце на Обуглившуюся заставу, что в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26938,'Боевые учения','Единственная цель валь\'киры – служить. И эта служит тебе – дарую власть над всеми ее способностями, $n.$B$BВ окрестностях фермы найдешь нескольких Отрекшихся, которых ты только что $gсоздал:создала;. Я хочу, чтобы с помощью своей валь\'киры ты $gзачаровал:зачаровала; по меньшей мере пятерых из них. Как только это будет сделано, бери своих новых солдат, веди их к хлеву Фелстоунов и перебей там весь скот. Пусть поймут, каково идти против Темной Госпожи.','С помощью способностей вашей порабощенной валь\'киры подчините 5 солдат-Отрекшихся на Поле Джанис. Затем уничтожьте пустобрюхое поганище в хлеву Фелстоунов.','Когда Кольтира даст слово, я отведу эту валь\'киру в Андорал. Мы победим. И еще одна часть Лордерона попадет под власть Отрекшихся.','Вернитесь к Линдси Черное Солнце на Обуглившуюся заставу, что в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Боевые учения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Единственная цель валь\'киры – служить. И эта служит тебе – дарую власть над всеми ее способностями, $n.$B$BВ окрестностях фермы найдешь нескольких Отрекшихся, которых ты только что $gсоздал:создала;. Я хочу, чтобы с помощью своей валь\'киры ты $gзачаровал:зачаровала; по меньшей мере пятерых из них. Как только это будет сделано, бери своих новых солдат, веди их к хлеву Фелстоунов и перебей там весь скот. Пусть поймут, каково идти против Темной Госпожи.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','С помощью способностей вашей порабощенной валь\'киры подчините 5 солдат-Отрекшихся на Поле Джанис. Затем уничтожьте пустобрюхое поганище в хлеву Фелстоунов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Когда Кольтира даст слово, я отведу эту валь\'киру в Андорал. Мы победим. И еще одна часть Лордерона попадет под власть Отрекшихся.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Линдси Черное Солнце на Обуглившуюся заставу, что в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26939,'Команда "Г"','Уничтожьте Липкую муть.','Надеюсь, ты еще не совсем выдохся. У нас впереди еще много работы!','Поговорите с десантником Б.Е. Барекусом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Команда "Г"',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте Липкую муть.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Надеюсь, ты еще не совсем выдохся. У нас впереди еще много работы!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с десантником Б.Е. Барекусом.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26941,'Команда "Г"','Что-то ты долго возился. Иди ко мне, за колонну. А то засветишь укрытие, и хана нам обоим!','Поговорите с десантником Фэйсом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Команда "Г"',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что-то ты долго возился. Иди ко мне, за колонну. А то засветишь укрытие, и хана нам обоим!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с десантником Фэйсом.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26942,'Команда "Г"','Убейте Анжинера Термоштепселя.','Я бы и рад пригласить тебя остаться в команде "Г", но тебя ведь ждут другие приключения.$B$BУверен, мы еще встретимся – тогда и поговорим на эту тему. Вот тебе награда за труды.','Поговорите с десантником Ганни Балом.','Осторожнее, у него бомбы!','Анжинер Термоштепсель') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Команда "Г"',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Анжинера Термоштепселя.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я бы и рад пригласить тебя остаться в команде "Г", но тебя ведь ждут другие приключения.$B$BУверен, мы еще встретимся – тогда и поговорим на эту тему. Вот тебе награда за труды.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с десантником Ганни Балом.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Осторожнее, у него бомбы!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Анжинер Термоштепсель',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26950,'Темная сторона света','Алый орден завлекает молодых воинов обещанием истребить нежить. Однако юным рекрутам не видна изнанка этого вроде бы благородного дела.$B$BДознаватель Вишас – самый жестокий мерзавец из всех, с кем мне доводилось встречаться. Он занимался "допросом" моей мамы еще в самом начале чумы. Безжалостный Талнос, волшебник крови, надзирает за их кладбищем.$B$BЧлены ордена – настоящие фанатики. "Священная ярость" ослепляет их, они не видят своей собственной тьмы. Они должны заплатить за лицемерие. И ты станешь орудием возмездия.','Убейте дознавателя Вишаса и волшебника крови Талноса.','Вернитесь к темному следопыту Велонаре.','Проклятое чудовище.','Дознаватель Вишас') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Темная сторона света',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Алый орден завлекает молодых воинов обещанием истребить нежить. Однако юным рекрутам не видна изнанка этого вроде бы благородного дела.$B$BДознаватель Вишас – самый жестокий мерзавец из всех, с кем мне доводилось встречаться. Он занимался "допросом" моей мамы еще в самом начале чумы. Безжалостный Талнос, волшебник крови, надзирает за их кладбищем.$B$BЧлены ордена – настоящие фанатики. "Священная ярость" ослепляет их, они не видят своей собственной тьмы. Они должны заплатить за лицемерие. И ты станешь орудием возмездия.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте дознавателя Вишаса и волшебника крови Талноса.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к темному следопыту Велонаре.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Проклятое чудовище.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Дознаватель Вишас',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (26951,'Зачистка островов Э.','Битва за острова Эха дорого нам стоила, но результат оправдал ожидания, |3-6($c). Великий дух Бвонсамди призвал духов острова на защиту наших воинов, но некоторые духи пали в бою. Помоги им упокоиться с миром! Побродив по островам Эха, ты найдешь лежащие на земле маски. Собери их и принеси сюда.','Вернитесь к мастеру Гадрину в деревню Сен\'джин.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зачистка островов Э.',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Битва за острова Эха дорого нам стоила, но результат оправдал ожидания, |3-6($c). Великий дух Бвонсамди призвал духов острова на защиту наших воинов, но некоторые духи пали в бою. Помоги им упокоиться с миром! Побродив по островам Эха, ты найдешь лежащие на земле маски. Собери их и принеси сюда.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру Гадрину в деревню Сен\'джин.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26952,'Участок Целителей Земли','Не нравится мне, чем занимаются Отрекшиеся в Бастионе. Все эти бомбы, взрывы, бессмысленное кровопролитие... Не за это борется Серебряный Авангард! К тому же я против того, что они принимают на работу наемников вроде тебя.$B$BНичего личного, |3-6($c). Просто ты ведь можешь найти себе занятие и получше. Вот если действительно хочешь спасти, а не погубить эти земли, поговори с агентом ШРУ Каартишем на Участке Целителей Земли, что к востоку отсюда.','Отчитайтесь перед агентом ШРУ Каартишем на Участке Целителей Земли, что в Западных Чумных землях.','Поговорите с агентом ШРУ Каартишем на Участке Целителей Земли в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Участок Целителей Земли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не нравится мне, чем занимаются Отрекшиеся в Бастионе. Все эти бомбы, взрывы, бессмысленное кровопролитие... Не за это борется Серебряный Авангард! К тому же я против того, что они принимают на работу наемников вроде тебя.$B$BНичего личного, |3-6($c). Просто ты ведь можешь найти себе занятие и получше. Вот если действительно хочешь спасти, а не погубить эти земли, поговори с агентом ШРУ Каартишем на Участке Целителей Земли, что к востоку отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отчитайтесь перед агентом ШРУ Каартишем на Участке Целителей Земли, что в Западных Чумных землях.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с агентом ШРУ Каартишем на Участке Целителей Земли в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26953,'Друид Зен\'Кики','Меня зовут Адрина Крепкошкур, я друид Круга Кенария. Это мы исцелили земли, в которых до нас царила лишь смерть.$B$BМы принимаем каждого, кто хочет стать друидом, независимо от расы, политических предпочтений и способностей. Это означает, что некоторые друиды нуждаются в особом подходе.$B$BПознакомься с Зен\'Кики. Он у нас новенький, еще только учится. Может, возьмешь его с собой и потренируешь технике ведения боя на здешних зараженных животных.','Убейте вместе с Зен\'Кики 20 зараженных животных. Вы можете охотиться на неповоротливых чумных медведей, зараженных волков, воронковых пауков Ядовитого Тумана и чумных воронковых пауков.$B$BЕсли вы с Зен\'Кики потеряетесь, возвращайтесь на Участок Целителей Земли.','Похоже, Зен\'Кики еще не совсем освоил превращения.','Вернитесь к Адрине Крепкошкур на Участок Целителей Земли в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Друид Зен\'Кики',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Меня зовут Адрина Крепкошкур, я друид Круга Кенария. Это мы исцелили земли, в которых до нас царила лишь смерть.$B$BМы принимаем каждого, кто хочет стать друидом, независимо от расы, политических предпочтений и способностей. Это означает, что некоторые друиды нуждаются в особом подходе.$B$BПознакомься с Зен\'Кики. Он у нас новенький, еще только учится. Может, возьмешь его с собой и потренируешь технике ведения боя на здешних зараженных животных.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте вместе с Зен\'Кики 20 зараженных животных. Вы можете охотиться на неповоротливых чумных медведей, зараженных волков, воронковых пауков Ядовитого Тумана и чумных воронковых пауков.$B$BЕсли вы с Зен\'Кики потеряетесь, возвращайтесь на Участок Целителей Земли.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Похоже, Зен\'Кики еще не совсем освоил превращения.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Адрине Крепкошкур на Участок Целителей Земли в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26954,'Разный подход','Среди прочего, Зен\'Кики нужно особо тщательно работать над точностью заклинания. Я даже отсюда вижу, что его заклинания гнева выходят из-под контроля! Вообще-то мне они были нужны как метки для отслеживания вашего передвижения через леса.$B$BДумаю, мы сможем использовать Зен\'Кики по-другому. Отведи его на вершину холма прямо к востоку от нас. Надо уничтожить кружащих над ним больных ястребов. Попроси Зен\'Кики их перестрелять. Если он не сможет попасть в ястребов, то хоть отвлечет их, а ты тогда и перебьешь.','Отведите Зен\'Кики на вершину холма к востоку от Участка Целителей Земли, затем заставьте его призвать и уничтожить 7 больных ястребов.','Ну, хоть что-то. Сколько птиц уничтожил Зен\'Кики?$B$BНи одной? Ты сам всех убил?$B$BЛадно, думаю, мы сумеем приспособить его к чему-нибудь другому. Дам тебе знать, как придет время.','Вернитесь к Адрине Крепкошкур на Участок Целителей Земли в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разный подход',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Среди прочего, Зен\'Кики нужно особо тщательно работать над точностью заклинания. Я даже отсюда вижу, что его заклинания гнева выходят из-под контроля! Вообще-то мне они были нужны как метки для отслеживания вашего передвижения через леса.$B$BДумаю, мы сможем использовать Зен\'Кики по-другому. Отведи его на вершину холма прямо к востоку от нас. Надо уничтожить кружащих над ним больных ястребов. Попроси Зен\'Кики их перестрелять. Если он не сможет попасть в ястребов, то хоть отвлечет их, а ты тогда и перебьешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отведите Зен\'Кики на вершину холма к востоку от Участка Целителей Земли, затем заставьте его призвать и уничтожить 7 больных ястребов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну, хоть что-то. Сколько птиц уничтожил Зен\'Кики?$B$BНи одной? Ты сам всех убил?$B$BЛадно, думаю, мы сумеем приспособить его к чему-нибудь другому. Дам тебе знать, как придет время.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Адрине Крепкошкур на Участок Целителей Земли в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26955,'Зен\'Кики и служители культа','В твое отсутствие я попробовала изменить подход к нашему другу Зен\'Кики. Думаю, он может стать неплохим лекарем. В основном потому, что целительные заклинания действуют всегда.$B$BАгент ШРУ Каартиш сказал, что зараженные животные приходят из лагеря сектантов на востоке. Надеюсь, ты не откажешься проводить туда Зен\'Кики. Вдруг ему удастся вылечить животных в лагере.','Отведите Зен\'Кики к Заставе Коварнессы в Западных Чумных землях, а затем выпустите из клеток 4 пойманных чумных медведей и дайте Зен\'Кики их вылечить.','Вернитесь к Адрине Крепкошкур на Участок Целителей Земли в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зен\'Кики и служители культа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В твое отсутствие я попробовала изменить подход к нашему другу Зен\'Кики. Думаю, он может стать неплохим лекарем. В основном потому, что целительные заклинания действуют всегда.$B$BАгент ШРУ Каартиш сказал, что зараженные животные приходят из лагеря сектантов на востоке. Надеюсь, ты не откажешься проводить туда Зен\'Кики. Вдруг ему удастся вылечить животных в лагере.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отведите Зен\'Кики к Заставе Коварнессы в Западных Чумных землях, а затем выпустите из клеток 4 пойманных чумных медведей и дайте Зен\'Кики их вылечить.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Адрине Крепкошкур на Участок Целителей Земли в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26956,'Прополка','$R! Хорошо, что ты здесь. Мне как раз нужна помощь.$B$BМы, друиды из Круга Кенария, заново возделали землю на Ферме Далсона. Земля приняла нашу заботу, посевы дали обильные всходы... по большей части.$B$BИ все-таки, видимо, некоторые растения еще не исцелились от чумы, опустошившей здешние края. Может, их корни ушли слишком глубоко в землю... или были слабые семена... я не знаю. Знаю другое – мне $gнужен крепкий здоровый:нужна крепкая сильная:c; |3-6($c), чтобы убрать все испорченные растения.','Избавьтесь от 6 испорченных кукурузных стеблей, 4 гнилых яблока и 3 пораженных болезнью тыкв на Ферме Далсона в Западных Чумных землях.','Вернитесь к Селирии Гренфельд на Участок Целителей Земли в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прополка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$R! Хорошо, что ты здесь. Мне как раз нужна помощь.$B$BМы, друиды из Круга Кенария, заново возделали землю на Ферме Далсона. Земля приняла нашу заботу, посевы дали обильные всходы... по большей части.$B$BИ все-таки, видимо, некоторые растения еще не исцелились от чумы, опустошившей здешние края. Может, их корни ушли слишком глубоко в землю... или были слабые семена... я не знаю. Знаю другое – мне $gнужен крепкий здоровый:нужна крепкая сильная:c; |3-6($c), чтобы убрать все испорченные растения.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Избавьтесь от 6 испорченных кукурузных стеблей, 4 гнилых яблока и 3 пораженных болезнью тыкв на Ферме Далсона в Западных Чумных землях.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Селирии Гренфельд на Участок Целителей Земли в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26957,'Долгая дорога домой','За свою жизнь я повидал много мест, $gдобрый:добрая:c; |3-6($c). Участвовал в битве за Ан\'Кираж, проходил через Темный портал в Запределье, вместе с Серебряным Авангардом сражался с Плетью в ледяном Нордсколе.$B$BНо еще раньше я был простым фермером в Лордероне. И теперь я тут, в Дольном Очаге, всего в нескольких милях от дома. Пора почтить мой прежний дом.$B$BЯ навещу Участок Целителей Земли перед отправлением в путь. Буду рад вновь там с тобой встретиться.','Встретьтесь с Дель Гарроном на Участке Целителей Земли в Западных Чумных землях.','Встретьтесь с Дель Гарроном на Участке Целителей Земли в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Долгая дорога домой',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','За свою жизнь я повидал много мест, $gдобрый:добрая:c; |3-6($c). Участвовал в битве за Ан\'Кираж, проходил через Темный портал в Запределье, вместе с Серебряным Авангардом сражался с Плетью в ледяном Нордсколе.$B$BНо еще раньше я был простым фермером в Лордероне. И теперь я тут, в Дольном Очаге, всего в нескольких милях от дома. Пора почтить мой прежний дом.$B$BЯ навещу Участок Целителей Земли перед отправлением в путь. Буду рад вновь там с тобой встретиться.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Встретьтесь с Дель Гарроном на Участке Целителей Земли в Западных Чумных землях.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Встретьтесь с Дель Гарроном на Участке Целителей Земли в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26959,'Ослабить защиту','Прежде чем начинать полномасштабную атаку на Монастырь Алого ордена, необходимо ослабить его защиту. Тебе нужно пробраться в библиотеку и прикончить псаря Локси и чародея Доана. Эти двое обеспечивают основную защиту Монастыря.$B$BЯ сотворю заклинание, чтобы твоих действий не заметили остальные обитатели Монастыря. А когда избавимся от Локси и Доана, я смогу вызвать подкрепление.$B$BУ нас нет права на поражение, $n. Темная Госпожа не потерпит ошибок и неудач.','Убейте псаря Локси и чародея Доана.','Вернитесь к темному следопыту Велонаре.','Покончи с ним побыстрее.','Чародей Доан') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ослабить защиту',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прежде чем начинать полномасштабную атаку на Монастырь Алого ордена, необходимо ослабить его защиту. Тебе нужно пробраться в библиотеку и прикончить псаря Локси и чародея Доана. Эти двое обеспечивают основную защиту Монастыря.$B$BЯ сотворю заклинание, чтобы твоих действий не заметили остальные обитатели Монастыря. А когда избавимся от Локси и Доана, я смогу вызвать подкрепление.$B$BУ нас нет права на поражение, $n. Темная Госпожа не потерпит ошибок и неудач.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте псаря Локси и чародея Доана.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к темному следопыту Велонаре.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Покончи с ним побыстрее.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Чародей Доан',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26960,'Мой сын, принц','Мой сын еще совсем молод, но на его плечи уже легло тяжелое бремя, и боюсь, что со временем этот груз будет только увеличиваться.$B$BОн никогда не станет хорошим правителем, если так и останется сидеть в крепости, но мне невыносима сама мысль о том, чтобы отправить его в путешествие одного. $B$B$n, твои подвиги уже вошли в историю. Ты будешь лучшим наставником для юного принца Андуина.$B$BПожалуйста, познакомься с ним. Я хочу поручить вам двоим одно дело в городе.','Познакомьтесь с принцем Андуином в крепости Штормграда. После этого поговорите с королем Ринном.','Отлично. Андуину есть чему у тебя поучиться.$B$BНо не забывай: вы не должны выходить из города. Не подвергай его жизнь опасности, а если что-то все же случится, защищай его до последней капли крови.$B$B<Король Ринн поворачивается к сыну.>$B$BНикаких приключений, Андуин! Если почувствуешь, что тебе грозит опасность, возвращайся в крепость.','Поговорите с королем Ринном в крепости Штормграда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мой сын, принц',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мой сын еще совсем молод, но на его плечи уже легло тяжелое бремя, и боюсь, что со временем этот груз будет только увеличиваться.$B$BОн никогда не станет хорошим правителем, если так и останется сидеть в крепости, но мне невыносима сама мысль о том, чтобы отправить его в путешествие одного. $B$B$n, твои подвиги уже вошли в историю. Ты будешь лучшим наставником для юного принца Андуина.$B$BПожалуйста, познакомься с ним. Я хочу поручить вам двоим одно дело в городе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Познакомьтесь с принцем Андуином в крепости Штормграда. После этого поговорите с королем Ринном.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично. Андуину есть чему у тебя поучиться.$B$BНо не забывай: вы не должны выходить из города. Не подвергай его жизнь опасности, а если что-то все же случится, защищай его до последней капли крови.$B$B<Король Ринн поворачивается к сыну.>$B$BНикаких приключений, Андуин! Если почувствуешь, что тебе грозит опасность, возвращайся в крепость.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с королем Ринном в крепости Штормграда.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26961,'Сбор идолов','Недавно, как раз перед тем, как появились трогги, мы обнаружили здесь много странных резных идолов. Но у нас не было времени изучить их, потому что вскоре после того, как мы их нашли, трогги вынудили нас покинуть руины! А эти идолы оказывают на троггов необычное воздействие. Трогги от них звереют!$b$bПринеси мне 8 идолов – я хочу изучить их, и я хочу, чтобы они были у меня! Ты найдешь их у троггов, кишащих в этом месте.','Принесите 8 резных каменных идолов Магмару Рудоколу на раскопки Сталекрута.','Вернитесь к Магмару Рудоколу на Раскопки Сталекрута.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сбор идолов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Недавно, как раз перед тем, как появились трогги, мы обнаружили здесь много странных резных идолов. Но у нас не было времени изучить их, потому что вскоре после того, как мы их нашли, трогги вынудили нас покинуть руины! А эти идолы оказывают на троггов необычное воздействие. Трогги от них звереют!$b$bПринеси мне 8 идолов – я хочу изучить их, и я хочу, чтобы они были у меня! Ты найдешь их у троггов, кишащих в этом месте.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 8 резных каменных идолов Магмару Рудоколу на раскопки Сталекрута.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Магмару Рудоколу на Раскопки Сталекрута.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26962,'Атака на Оружейную','Как видишь, $n, наша первая атака на Оружейную провалилась. Мы уже было захватили внутренний двор, но тут появился Ирод, герой Алого ордена.$B$BОднако мы не должны отступать. Нельзя допустить, чтобы Алый орден обучал здесь своих воинов, и уж тем более занимался подготовкой атаки на Подгород.$B$BТак что твоя задача должна быть тебе предельно ясна: нужно уничтожить героя Алого ордена.','Убейте Ирода.','Вернитесь к темному следопыту Велонаре.','Герой Алого ордена','Ирод') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Атака на Оружейную',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как видишь, $n, наша первая атака на Оружейную провалилась. Мы уже было захватили внутренний двор, но тут появился Ирод, герой Алого ордена.$B$BОднако мы не должны отступать. Нельзя допустить, чтобы Алый орден обучал здесь своих воинов, и уж тем более занимался подготовкой атаки на Подгород.$B$BТак что твоя задача должна быть тебе предельно ясна: нужно уничтожить героя Алого ордена.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Ирода.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к темному следопыту Велонаре.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Герой Алого ордена',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Ирод',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26964,'Приказ вождя: на Серебряный бор!','Явитесь к главному палачу Мортию в Ставку Отрекшихся в Серебряном бору.','Превосходно! Еще один новобранец. Дел у нас много... Много дел, говорю.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приказ вождя: на Серебряный бор!',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Явитесь к главному палачу Мортию в Ставку Отрекшихся в Серебряном бору.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Превосходно! Еще один новобранец. Дел у нас много... Много дел, говорю.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26967,'Битва за Монастырь Алого ордена','Узри мощь Отрекшихся! Неодолимая воля Темной Госпожи поддерживает нас! $B$BПочти все оставшиеся воины Алого ордена бежали. Однако считанные единицы проявили героическую твердость и все еще сопротивляются.$B$BВ этой кампании ты $gпоказал:показала; себя очень достойно. Сильвана оказывает тебе честь и позволяет убить ее последних врагов, $n.$B$BНе щади никого.','Убейте командира Алого ордена Могрейна и верховного инквизитора Вайтмейн.','Вернитесь к темному следопыту Велонаре.','Заставь ее помучиться!','Верховный инквизитор Вайтмейн') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Битва за Монастырь Алого ордена',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Узри мощь Отрекшихся! Неодолимая воля Темной Госпожи поддерживает нас! $B$BПочти все оставшиеся воины Алого ордена бежали. Однако считанные единицы проявили героическую твердость и все еще сопротивляются.$B$BВ этой кампании ты $gпоказал:показала; себя очень достойно. Сильвана оказывает тебе честь и позволяет убить ее последних врагов, $n.$B$BНе щади никого.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте командира Алого ордена Могрейна и верховного инквизитора Вайтмейн.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к темному следопыту Велонаре.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Заставь ее помучиться!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Верховный инквизитор Вайтмейн',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26971,'Закрытие разлома','Ваше внимание привлекает шум в главном зале Храма. Вы слышите знакомый смех... это Лортуна. Она вернулась, чтобы помешать ритуалу. Нужно остановить ее!','Убейте верховную жрицу Лортуну.','Когда все это началось, Маруут говорил, что с радостью отдал бы свою жизнь, лишь бы наша задача была выполнена. Он бы порадовался нашему успеху… и этой смерти.$B$BС нашей стороны разлом закрыт. Теперь в Подземье станет немного спокойнее. Траллу понадобится время, чтобы залечить раны Азерота, и пока он не закончит, нам нужно будет оставаться здесь.$B$BБлагодарю тебя за все, что ты сделал. Не думаю, что мы бы смогли закончить это дело так быстро без твоей помощи.','Поговорите с заклинателем земли Торунскаром в Храме Земли.','Лидер оставшихся в Подземье сил Сумеречного Молота.','Верховная жрица Лортуна') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Закрытие разлома',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ваше внимание привлекает шум в главном зале Храма. Вы слышите знакомый смех... это Лортуна. Она вернулась, чтобы помешать ритуалу. Нужно остановить ее!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте верховную жрицу Лортуну.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Когда все это началось, Маруут говорил, что с радостью отдал бы свою жизнь, лишь бы наша задача была выполнена. Он бы порадовался нашему успеху… и этой смерти.$B$BС нашей стороны разлом закрыт. Теперь в Подземье станет немного спокойнее. Траллу понадобится время, чтобы залечить раны Азерота, и пока он не закончит, нам нужно будет оставаться здесь.$B$BБлагодарю тебя за все, что ты сделал. Не думаю, что мы бы смогли закончить это дело так быстро без твоей помощи.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с заклинателем земли Торунскаром в Храме Земли.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Лидер оставшихся в Подземье сил Сумеречного Молота.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Верховная жрица Лортуна',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26972,'Темная сторона света','Я вступил в Алый орден еще совсем юным паладином с пламенным сердцем и горячим желанием очистить мир от зла. Тогда я не знал мрачной правды об этих фанатиках.$B$BДознаватель Вишас и волшебник крови Талнос надзирают за этим кладбищем. Они неустанно истязают молоденьких рекрутов, проверяя, насколько те "чисты". Это садизм в чистом виде и поругание света, |3-6($c)!$B$BЯ отрекаюсь от верности ордену. Не желаю больше участвовать в делах этой порочной организации. Убей Вишаса и Талноса, чтобы никому не пришлось вытерпеть столько боли, сколько вытерпел я.','Убейте дознавателя Вишаса и волшебника крови Талноса.','Вернитесь к Джозефу Беспокойному.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Темная сторона света',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я вступил в Алый орден еще совсем юным паладином с пламенным сердцем и горячим желанием очистить мир от зла. Тогда я не знал мрачной правды об этих фанатиках.$B$BДознаватель Вишас и волшебник крови Талнос надзирают за этим кладбищем. Они неустанно истязают молоденьких рекрутов, проверяя, насколько те "чисты". Это садизм в чистом виде и поругание света, |3-6($c)!$B$BЯ отрекаюсь от верности ордену. Не желаю больше участвовать в делах этой порочной организации. Убей Вишаса и Талноса, чтобы никому не пришлось вытерпеть столько боли, сколько вытерпел я.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте дознавателя Вишаса и волшебника крови Талноса.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джозефу Беспокойному.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26973,'Единственно верный путь','По-моему, я знаю, в чем причина упадка ордена. Чародей Доан руководит здешней библиотекой и учит молодых рекрутов тайным искусствам.$B$BПуть Света – единственно верный путь! Убей Доана,|3-6($c), и тогда орден очистится от скверны, и к нему вернется былое святое величие!$B$B<Джозеф Беспокойный переминается с ноги на ногу.>$B$BИ еще надо избавиться от Локси. Его гончие, кажется, не одобряют наших благородных намерений.','Убейте псаря Локси и чародея Доана.','Вернитесь к Джозефу Беспокойному.','Он заведует Библиотекой Алого ордена "железной рукой".','Чародей Доан') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Единственно верный путь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','По-моему, я знаю, в чем причина упадка ордена. Чародей Доан руководит здешней библиотекой и учит молодых рекрутов тайным искусствам.$B$BПуть Света – единственно верный путь! Убей Доана,|3-6($c), и тогда орден очистится от скверны, и к нему вернется былое святое величие!$B$B<Джозеф Беспокойный переминается с ноги на ногу.>$B$BИ еще надо избавиться от Локси. Его гончие, кажется, не одобряют наших благородных намерений.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте псаря Локси и чародея Доана.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джозефу Беспокойному.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Он заведует Библиотекой Алого ордена "железной рукой".',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Чародей Доан',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26974,'Ложный герой','Нам... пришлось убить их, они напали на нас!$B$BТы мне веришь, да, $n?$B$BИрод – не настоящий герой Алого ордена. Я – настоящий герой! Он отобрал у меня принадлежащее мне по праву!$B$BУбей его. Он... опасен! Он натаскивает солдат на уничтожение всех подряд, не только нежити!$B$BЯ тебя щедро вознагражу...','Убейте Ирода.','Вернитесь к Джозефу Безумному.','Грязный вор!','Ирод') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ложный герой',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нам... пришлось убить их, они напали на нас!$B$BТы мне веришь, да, $n?$B$BИрод – не настоящий герой Алого ордена. Я – настоящий герой! Он отобрал у меня принадлежащее мне по праву!$B$BУбей его. Он... опасен! Он натаскивает солдат на уничтожение всех подряд, не только нежити!$B$BЯ тебя щедро вознагражу...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Ирода.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джозефу Безумному.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Грязный вор!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Ирод',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (26975,'Подготовка флота','Я собираю флот, чтобы напасть на Сумеречное нагорье и раз и навсегда покончить с лакеями Смертокрыла. Солдаты рвутся в бой, но корабли еще не готовы.$B$BМне нужно, чтобы кто-то вдохновил докеров на трудовые подвиги. Думаю, что визит принца поднимет их боевой дух и напомнит им о том, что они сражаются за свое светлое будущее.$B$BОтведи принца Андуина в доки и поговори с ответственным за закупки сержантом Грейвсом. Я хочу, чтобы Андуин увидел, как в подобных ситуациях действует прирожденный лидер.','Проводите принца Андуина в доки Штормграда и поговорите с ответственным за закупки Грейвсом. Если вы потеряете принца, то сможете найти его в тронном зале Штормграда.','<Грейвс почтительно кланяется принцу.>$B$BВаше высочество, прошу вас, поймите – мои люди работают круглые сутки, но этот проект просто огромен!$B$BТем не менее мы постараемся закончить его как можно быстрее. Даю вам слово.','Принц Андуин успешно сопровожден к Грейвсу','Отправляйтесь в порт Штормграда и поговорите с ответственным за закупки Грейвсом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подготовка флота',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я собираю флот, чтобы напасть на Сумеречное нагорье и раз и навсегда покончить с лакеями Смертокрыла. Солдаты рвутся в бой, но корабли еще не готовы.$B$BМне нужно, чтобы кто-то вдохновил докеров на трудовые подвиги. Думаю, что визит принца поднимет их боевой дух и напомнит им о том, что они сражаются за свое светлое будущее.$B$BОтведи принца Андуина в доки и поговори с ответственным за закупки сержантом Грейвсом. Я хочу, чтобы Андуин увидел, как в подобных ситуациях действует прирожденный лидер.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проводите принца Андуина в доки Штормграда и поговорите с ответственным за закупки Грейвсом. Если вы потеряете принца, то сможете найти его в тронном зале Штормграда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Грейвс почтительно кланяется принцу.>$B$BВаше высочество, прошу вас, поймите – мои люди работают круглые сутки, но этот проект просто огромен!$B$BТем не менее мы постараемся закончить его как можно быстрее. Даю вам слово.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Принц Андуин успешно сопровожден к Грейвсу',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отправляйтесь в порт Штормграда и поговорите с ответственным за закупки Грейвсом.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (26976,'Битва за Монастырь Алого ордена','Приятно вновь тебя видеть, $n! Ты очень вовремя. Мне как раз нужна помощь.$B$BПонимаешь, какое дело, командир Могрейн и верховный инквизитор Вайтмейн... они все пытаются меня убедить, что я никакой не новый герой Алого ордена! Как-то мне это не нравится. И моим бойцам тоже!$B$BМы установим в Монастыре новый порядок и сделаем Алый орден таким, каким ему надлежит быть, – под моим руководством! Я разберусь и с Отрекшимися, и с Плетью раз и навсегда!$B$BИ ты мне поможешь, правда? Не в службу, а в дружбу.','Убейте командира Алого ордена Могрейна и верховного инквизитора Вайтмейн.','Вернитесь к Джозефу Чокнутому.','Убей ее!','Верховный инквизитор Вайтмейн') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Битва за Монастырь Алого ордена',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приятно вновь тебя видеть, $n! Ты очень вовремя. Мне как раз нужна помощь.$B$BПонимаешь, какое дело, командир Могрейн и верховный инквизитор Вайтмейн... они все пытаются меня убедить, что я никакой не новый герой Алого ордена! Как-то мне это не нравится. И моим бойцам тоже!$B$BМы установим в Монастыре новый порядок и сделаем Алый орден таким, каким ему надлежит быть, – под моим руководством! Я разберусь и с Отрекшимися, и с Плетью раз и навсегда!$B$BИ ты мне поможешь, правда? Не в службу, а в дружбу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте командира Алого ордена Могрейна и верховного инквизитора Вайтмейн.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джозефу Чокнутому.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Убей ее!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Верховный инквизитор Вайтмейн',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26977,'Расследование','Горожане взбудоражены проделками последователей культа Сумеречного Молота в последние месяцы. Сектанты умело пользуются крестьянскими суевериями и привлекают на свою сторону важных граждан нашего города. Нужно установить, как организован весь заговор.$B$BРасследование этого дела я поручил майору городской стражи Штормграда Самуэльсону. Он здесь, в тронном зале. Предложи ему свою помощь.','Поговорите с майором Самуэльсоном в крепости Штормграда.','Мм-м... Да? Ах да, конечно – расследование действий Сумеречного Молота.$B$BТы можешь мне помочь.','Поговорите в крепости Штормграда с майором Самуэльсоном.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Расследование',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Горожане взбудоражены проделками последователей культа Сумеречного Молота в последние месяцы. Сектанты умело пользуются крестьянскими суевериями и привлекают на свою сторону важных граждан нашего города. Нужно установить, как организован весь заговор.$B$BРасследование этого дела я поручил майору городской стражи Штормграда Самуэльсону. Он здесь, в тронном зале. Предложи ему свою помощь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с майором Самуэльсоном в крепости Штормграда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мм-м... Да? Ах да, конечно – расследование действий Сумеречного Молота.$B$BТы можешь мне помочь.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите в крепости Штормграда с майором Самуэльсоном.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (26978,'Кому нужны котлы?','Ты видел, что происходит на поле Джанис? Войска Альянса в Андорале забрали эту землю себе и на ней... они... выращивают ЗЕРНОВЫЕ!$B$BЭто едва ли не хуже, чем то, что с ним делала Плеть. У тех-то, по крайней мере, хватило ума водрузить посередь поля гигантский чумной котел.$B$BМы отберем эту ферму у людишек, $n. Возьми бочонки и установи их в обозначенных местах на поле. Я буду ждать здесь, у Бастиона.','Установите бочонки с чумой Дитерса на поле Джанис: у ветряной мельницы, у амбара, в доме и в хлеву Фелстоунов.','<Дитерс просто дрожит от возбуждения.>$B$BВсе бочонки на своих местах? Все до одного установил?$B$BОчень хорошо, тогда я сообщу верховному палачу. Когда придет время, именно ему предстоит нажать на кнопку.','Вернитесь к аптекарю Дитерсу в Бастион в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кому нужны котлы?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты видел, что происходит на поле Джанис? Войска Альянса в Андорале забрали эту землю себе и на ней... они... выращивают ЗЕРНОВЫЕ!$B$BЭто едва ли не хуже, чем то, что с ним делала Плеть. У тех-то, по крайней мере, хватило ума водрузить посередь поля гигантский чумной котел.$B$BМы отберем эту ферму у людишек, $n. Возьми бочонки и установи их в обозначенных местах на поле. Я буду ждать здесь, у Бастиона.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Установите бочонки с чумой Дитерса на поле Джанис: у ветряной мельницы, у амбара, в доме и в хлеву Фелстоунов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Дитерс просто дрожит от возбуждения.>$B$BВсе бочонки на своих местах? Все до одного установил?$B$BОчень хорошо, тогда я сообщу верховному палачу. Когда придет время, именно ему предстоит нажать на кнопку.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к аптекарю Дитерсу в Бастион в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26979,'Странные новые лица','Поговорите с Линдси Черное Солнце на Обуглившейся заставе, что в Западных Чумных землях.','Поговорите с Линдси Черное Солнце на Обуглившейся заставе, что в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Странные новые лица',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Линдси Черное Солнце на Обуглившейся заставе, что в Западных Чумных землях.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Линдси Черное Солнце на Обуглившейся заставе, что в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26980,'Станция Бынструмента','Ты отлично $gпотрудился:потрудилась; здесь, $n. Честно говоря, просить тебя таскать мешки с песком было бы несправедливо; я лучше пошлю тебя туда, где твой опыт действительно пригодится.$b$bК северу отсюда, в болотах у нас есть небольшая застава. Ее построил гном по имени Бынструмент, но тебе надо поговорить с Шейлой Крепкой Стамеской и помочь ей в делах со Стальгорном.$b$bЗнаю, она красотка... но на твоем месте я бы с ней не кокетничал. Крепкой Стамеской ее прозывают не просто так.','Поговорите с Шейлой Крепкой Стамеской на станции Бынструмента, к северу от Гавани Менетилов.','Тебя прислал Крепкий Кулак, да? Капитан он отличный, вояками своими управляет как надо. Вот бы он еще прекратил пялиться на мои округлости.$B$BНадеюсь, ты этого делать не будешь. Нам надо работать!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Станция Бынструмента',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты отлично $gпотрудился:потрудилась; здесь, $n. Честно говоря, просить тебя таскать мешки с песком было бы несправедливо; я лучше пошлю тебя туда, где твой опыт действительно пригодится.$b$bК северу отсюда, в болотах у нас есть небольшая застава. Ее построил гном по имени Бынструмент, но тебе надо поговорить с Шейлой Крепкой Стамеской и помочь ей в делах со Стальгорном.$b$bЗнаю, она красотка... но на твоем месте я бы с ней не кокетничал. Крепкой Стамеской ее прозывают не просто так.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Шейлой Крепкой Стамеской на станции Бынструмента, к северу от Гавани Менетилов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебя прислал Крепкий Кулак, да? Капитан он отличный, вояками своими управляет как надо. Вот бы он еще прекратил пялиться на мои округлости.$B$BНадеюсь, ты этого делать не будешь. Нам надо работать!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (26981,'Укрытие Вельгара','Геолог Вельгар уже некоторое время ведет раскопки в горах к юго-востоку отсюда. У него были какие-то проблемы с ящерами, но в последнее время вроде бы все наладилось.$b$bА на днях мы узнали, что ему снова пришлось свернуть все работы. Я не очень точно знаю, что там происходит, но вряд ли после катаклизма карьер стал безопаснее, чем раньше.$b$bТам работают отличные дворфы, $n. Не сходишь ли туда узнать, в чем дело, и, может быть, помочь?','Поговорите с геологом Вельгаром в Укрытии Вельгара, которое находится к юго-востоку от станции Бынструмента.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Укрытие Вельгара',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Геолог Вельгар уже некоторое время ведет раскопки в горах к юго-востоку отсюда. У него были какие-то проблемы с ящерами, но в последнее время вроде бы все наладилось.$b$bА на днях мы узнали, что ему снова пришлось свернуть все работы. Я не очень точно знаю, что там происходит, но вряд ли после катаклизма карьер стал безопаснее, чем раньше.$b$bТам работают отличные дворфы, $n. Не сходишь ли туда узнать, в чем дело, и, может быть, помочь?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с геологом Вельгаром в Укрытии Вельгара, которое находится к юго-востоку от станции Бынструмента.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26982,'Монастырь Алого ордена','Монастырь в Тирисфальских лесах, теперь занятый Алым орденом, раньше был главным тренировочным лагерем наших паладинов. Теперь монастырь оказался совсем рядом с оплотом Отрекшихся, а из-за Алого ордена мы не можем использовать Монастырь для подготовки воинов!$B$BДжозеф Беспокойный ждет на кладбище... Вообще-то я ему не доверяю, но других вариантов нет. Поговори с ним. Хотя сам он из ордена, но утверждает, что порвал с ним и вообще собирается поднять восстание. Может быть, это даст нам возможность вернуть себе то, что всегда было нашим.','Поговорите с Джозефом Беспокойным.','Поговорите с Джозефом Беспокойным.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Монастырь Алого ордена',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Монастырь в Тирисфальских лесах, теперь занятый Алым орденом, раньше был главным тренировочным лагерем наших паладинов. Теперь монастырь оказался совсем рядом с оплотом Отрекшихся, а из-за Алого ордена мы не можем использовать Монастырь для подготовки воинов!$B$BДжозеф Беспокойный ждет на кладбище... Вообще-то я ему не доверяю, но других вариантов нет. Поговори с ним. Хотя сам он из ордена, но утверждает, что порвал с ним и вообще собирается поднять восстание. Может быть, это даст нам возможность вернуть себе то, что всегда было нашим.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Джозефом Беспокойным.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Джозефом Беспокойным.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26983,'Удачное расположение','Только не думай, что все уже в порядке. Здесь еще многое надо сделать. Кроме того, нам еще нужно разобраться с Отрекшимися. Монастырь Алого ордена в Тирисфальских лесах располагается очень удачно – на идеальном расстоянии от Подгорода и Брилла.$B$BОтправляйся туда и поговори с Джозефом Беспокойным в тамошней библиотеке. Он поднимает восстание среди членов ордена. Надо этим воспользоваться и превратить Монастырь в наш форпост в этом регионе. А заодно, может быть, и прикончить чародея Доана, одного из сильнейших магов ордена.','Поговорите с Джозефом Беспокойным.','Вернитесь к Джозефу Беспокойному.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Удачное расположение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Только не думай, что все уже в порядке. Здесь еще многое надо сделать. Кроме того, нам еще нужно разобраться с Отрекшимися. Монастырь Алого ордена в Тирисфальских лесах располагается очень удачно – на идеальном расстоянии от Подгорода и Брилла.$B$BОтправляйся туда и поговори с Джозефом Беспокойным в тамошней библиотеке. Он поднимает восстание среди членов ордена. Надо этим воспользоваться и превратить Монастырь в наш форпост в этом регионе. А заодно, может быть, и прикончить чародея Доана, одного из сильнейших магов ордена.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Джозефом Беспокойным.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джозефу Беспокойному.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26984,'Старый друг','Мы с Джозефом Безумным были большими друзьями. Это было давно, еще до его вступления в Алый орден в Монастыре в Тирисфальских лесах. Я слышал, он теперь в Оружейной и пытается оспорить у Ирода звание героя Алого ордена.$B$BИдти против Ирода – это форменное самоубийство! Отправляйся к Джозефу и попытайся отговорить его от этой безумной затеи.','Поговорите с Джозефом Безумным.','Вернитесь к Джозефу Беспокойному.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Старый друг',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы с Джозефом Безумным были большими друзьями. Это было давно, еще до его вступления в Алый орден в Монастыре в Тирисфальских лесах. Я слышал, он теперь в Оружейной и пытается оспорить у Ирода звание героя Алого ордена.$B$BИдти против Ирода – это форменное самоубийство! Отправляйся к Джозефу и попытайся отговорить его от этой безумной затеи.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Джозефом Безумным.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джозефу Беспокойному.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26985,'Безумие против безумия','Думаю, некоторое время мы тут без тебя справимся. Мне донесли, что Джозеф Чокнутый, бывший офицер Алого ордена, находится в монастырском соборе ордена со своими ренегатами и собирается выступить против командира Могрейна.$B$BТакую возможность нельзя упустить! Отправляйся туда и помоги Джозефу в его безумной затее. И тогда, возможно, нам удастся превратить Монастырь в опорный пункт прямо под носом у Сильваны!','Отправляйтесь к Джозефу Чокнутому.','Вернитесь к Джозефу Чокнутому.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Безумие против безумия',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Думаю, некоторое время мы тут без тебя справимся. Мне донесли, что Джозеф Чокнутый, бывший офицер Алого ордена, находится в монастырском соборе ордена со своими ренегатами и собирается выступить против командира Могрейна.$B$BТакую возможность нельзя упустить! Отправляйся туда и помоги Джозефу в его безумной затее. И тогда, возможно, нам удастся превратить Монастырь в опорный пункт прямо под носом у Сильваны!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь к Джозефу Чокнутому.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джозефу Чокнутому.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26986,'В Монастырь Алого ордена','Зачастую наилучший способ защитить собственный народ – это нанести врагу наибольший урон с наименьшими собственными потерями. Нужно ударить в самый центр вражеских владений и, таким образом, избежать столкновений в будущем.$B$BОтправляйся на Кладбище Монастыря Алого ордена и обратись там к темному следопыту Велонаре. Она стоит во главе военного похода Отрекшихся, и ей может пригодиться помощь столь $gопытного:опытной:c; |3-1($c) как ты.','Поговорите с темным следопытом Велонарой.','Вернитесь к Джозефу Беспокойному.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В Монастырь Алого ордена',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Зачастую наилучший способ защитить собственный народ – это нанести врагу наибольший урон с наименьшими собственными потерями. Нужно ударить в самый центр вражеских владений и, таким образом, избежать столкновений в будущем.$B$BОтправляйся на Кладбище Монастыря Алого ордена и обратись там к темному следопыту Велонаре. Она стоит во главе военного похода Отрекшихся, и ей может пригодиться помощь столь $gопытного:опытной:c; |3-1($c) как ты.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с темным следопытом Велонарой.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джозефу Беспокойному.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26987,'Благородное дело','В отличие от множества других рас мой народ не особо восторгается тайной магией. Хорошо еще, эти волшебники из Монастыря Алого ордена находятся от нас на приличном расстоянии. Однако нас сильно беспокоит их способность проникать за границы физического мира, которая может угрожать самому существованию нашего рода.$B$BОтправляйся далеко на запад в Библиотеку Монастыря Алого ордена и обратись там к темному следопыту Велонаре. Ее войско задалось целью покончить с самим чародеем Доаном, главой магов Алого ордена!','Поговорите с темным следопытом Велонарой.','Вернитесь к Джозефу Беспокойному.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Благородное дело',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В отличие от множества других рас мой народ не особо восторгается тайной магией. Хорошо еще, эти волшебники из Монастыря Алого ордена находятся от нас на приличном расстоянии. Однако нас сильно беспокоит их способность проникать за границы физического мира, которая может угрожать самому существованию нашего рода.$B$BОтправляйся далеко на запад в Библиотеку Монастыря Алого ордена и обратись там к темному следопыту Велонаре. Ее войско задалось целью покончить с самим чародеем Доаном, главой магов Алого ордена!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с темным следопытом Велонарой.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джозефу Беспокойному.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26988,'Задержка заказа','Недавно я заказала в Подгороде кое-какие реагенты и теперь жду, когда их доставят. Но мне сказали, что доставка задерживается, так как воины из Монастыря Алого ордена перекрыли дорогу. Очень досадно! И все из-за этого Ирода, героя Алого ордена... $B$BПрошу, поговори с темным следопытом Велонарой в Оружейной Монастыря. Она "позаботится" об Ироде, и я наконец-то получу свой заказ!','Поговорите с темным следопытом Велонарой.','Вернитесь к Джозефу Беспокойному.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Задержка заказа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Недавно я заказала в Подгороде кое-какие реагенты и теперь жду, когда их доставят. Но мне сказали, что доставка задерживается, так как воины из Монастыря Алого ордена перекрыли дорогу. Очень досадно! И все из-за этого Ирода, героя Алого ордена... $B$BПрошу, поговори с темным следопытом Велонарой в Оружейной Монастыря. Она "позаботится" об Ироде, и я наконец-то получу свой заказ!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с темным следопытом Велонарой.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джозефу Беспокойному.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26990,'Что-то они там мутят','Похоже, тролли из племени Песчаной Бури работают заодно с культом Сумеречного Молота.$B$BЛадно. Я не позволю этой вонючей ведьме посылать чудовищ в МОЙ город.$B$BСмельчаки, за мной! Мы обагрим песок кровью этих гадов и станем победителями. А когда вернемся, расскажи Хамуулу Руническому Тотему обо всем, что здесь произошло. Сам-то я буду занят – кто-то должен присматривать за возвращением горожан, ремонтными работами и прочим.','Убейте Кай\'джу Газ\'риллу и поставьте об этом в известность Хамуула Рунического Тотема в Громовом Утесе.','Сообщите Хамуулу Руническому Тотему в Громовом Утесе о кончине Кай\'жу Газ\'риллы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Что-то они там мутят',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Похоже, тролли из племени Песчаной Бури работают заодно с культом Сумеречного Молота.$B$BЛадно. Я не позволю этой вонючей ведьме посылать чудовищ в МОЙ город.$B$BСмельчаки, за мной! Мы обагрим песок кровью этих гадов и станем победителями. А когда вернемся, расскажи Хамуулу Руническому Тотему обо всем, что здесь произошло. Сам-то я буду занят – кто-то должен присматривать за возвращением горожан, ремонтными работами и прочим.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Кай\'джу Газ\'риллу и поставьте об этом в известность Хамуула Рунического Тотема в Громовом Утесе.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Сообщите Хамуулу Руническому Тотему в Громовом Утесе о кончине Кай\'жу Газ\'риллы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26991,'Враги наших врагов...','В жизни всякое случается, и иногда нужно забыть о себе и оказать помощь союзникам, чтобы в будущем рассчитывать на их помощь. Сейчас как раз такой случай, |3-6($r).$B$BОтправляйся в Монастырь Алого ордена рядом с Подгородом в Тирисфальских лесах. По прибытии иди в Собор и поговори с темным следопытом Велонарой. Она возглавляет войска, сражающиеся с Алым орденом, и нам всем будет выгодно, если наши союзники из нежити отобьют монастырь прежде, чем у ордена появится возможность атаковать их столицу.','Разыщите темного следопыта Велонару.','Вернитесь к Джозефу Беспокойному.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Враги наших врагов...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В жизни всякое случается, и иногда нужно забыть о себе и оказать помощь союзникам, чтобы в будущем рассчитывать на их помощь. Сейчас как раз такой случай, |3-6($r).$B$BОтправляйся в Монастырь Алого ордена рядом с Подгородом в Тирисфальских лесах. По прибытии иди в Собор и поговори с темным следопытом Велонарой. Она возглавляет войска, сражающиеся с Алым орденом, и нам всем будет выгодно, если наши союзники из нежити отобьют монастырь прежде, чем у ордена появится возможность атаковать их столицу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите темного следопыта Велонару.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джозефу Беспокойному.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26992,'Агония','Тебе, конечно, уже рассказали об инциденте, который произошел в Нордсколе, во Вратах гнева? После этого нам строго-настрого запретили использовать штамм разрушающей живую материю гнили, которую мы наконец создали. Будь прокляты правила, предписания и прочая чепуха!$B$BОни дают нам какую-то кастрированную версию идеальной гнили и рассчитывают на то, что мы превратим ее в оружие!$B$BЧтобы эта дрянь заработала, нам понадобится несколько мешков свирепого погибельника. Принеси их мне. Погибельник растет по всему Серебряному бору.','Соберите 8 свирепых погибельников.','Какая агония, друг! Сама земля угрожает поглотить нас, и все-таки мы не сдаемся. Интересно, почему? Но ничего – теперь, когда у нас есть погибельник, кишки и кровь, которые нужны Т\'Вин, мы создадим что-нибудь для фронта.','Тебе удалось набрать свирепого погибельника?','Поговорите с аптекарем Сухоцветом в Ставке Отрекшихся в Серебряном бору.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Агония',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе, конечно, уже рассказали об инциденте, который произошел в Нордсколе, во Вратах гнева? После этого нам строго-настрого запретили использовать штамм разрушающей живую материю гнили, которую мы наконец создали. Будь прокляты правила, предписания и прочая чепуха!$B$BОни дают нам какую-то кастрированную версию идеальной гнили и рассчитывают на то, что мы превратим ее в оружие!$B$BЧтобы эта дрянь заработала, нам понадобится несколько мешков свирепого погибельника. Принеси их мне. Погибельник растет по всему Серебряному бору.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 свирепых погибельников.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Какая агония, друг! Сама земля угрожает поглотить нас, и все-таки мы не сдаемся. Интересно, почему? Но ничего – теперь, когда у нас есть погибельник, кишки и кровь, которые нужны Т\'Вин, мы создадим что-нибудь для фронта.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось набрать свирепого погибельника?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с аптекарем Сухоцветом в Ставке Отрекшихся в Серебряном бору.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26993,'"Компендиум павших"','Не бойся, |3-6($r), я никому не служу. Сам себе господин. Где-то здесь, в этих залах хранится книга под названием "Компендиум павших." В ней заключена вся информация Алого ордена о моем народе, собиравшаяся на протяжении многих лет.$B$BЕсли коротко, я хочу, чтобы ты $gнашел:нашла; эту книгу и $gпринес:принесла; ее мне. Без лишних вопросов.','Разыщите "Компендиум павших".','Вернитесь к Доминику.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','"Компендиум павших"',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не бойся, |3-6($r), я никому не служу. Сам себе господин. Где-то здесь, в этих залах хранится книга под названием "Компендиум павших." В ней заключена вся информация Алого ордена о моем народе, собиравшаяся на протяжении многих лет.$B$BЕсли коротко, я хочу, чтобы ты $gнашел:нашла; эту книгу и $gпринес:принесла; ее мне. Без лишних вопросов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите "Компендиум павших".',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Доминику.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26994,'Без лишних вопросов','Я слышал, Джозеф Безумный хочет, чтобы ты $gубил:убила; Ирода. Может быть, заодно прикончишь и его лучших солдат? Я тебе хорошо заплачу.$B$BТолько не спрашивай, почему. Это не твоя забота. Твоя задача – сделать дело и получить награду.','Убейте 3 мирмидонов Алого ордена, 3 заступников Алого ордена, 3 стражников Алого ордена и 3 вызывателей Алого ордена.','Вернитесь к Доминику.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Без лишних вопросов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я слышал, Джозеф Безумный хочет, чтобы ты $gубил:убила; Ирода. Может быть, заодно прикончишь и его лучших солдат? Я тебе хорошо заплачу.$B$BТолько не спрашивай, почему. Это не твоя забота. Твоя задача – сделать дело и получить награду.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 3 мирмидонов Алого ордена, 3 заступников Алого ордена, 3 стражников Алого ордена и 3 вызывателей Алого ордена.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Доминику.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26995,'Кровь и кишки','Если мы хотим привести эту новую гниль в рабочее состояние, нам понадобятся чистые внутренности животных. Но в Серебряном бору почти не осталось животных с чистыми внутренностями – ведь большинство живности заболело.$B$BПрочеши лес к востоку отсюда и убивай только здоровых воргов и медведей. Вырви их внутренности и принеси мне все чистые кишки, которые сможешь унести!','Найдите 6 "чистых" внутренностей.','Отлично! Теперь, когда у нас есть кишки и свирепый погибельник, мы сможем испытать новый штамм гнили. Осталось выбрать подходящую цель...','Запомни, мне нужны только чистые внутренности.','Поговорите со старшим аптекарем Шаной Т\'вин в Ставке Отрекшихся в Серебряном бору.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кровь и кишки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если мы хотим привести эту новую гниль в рабочее состояние, нам понадобятся чистые внутренности животных. Но в Серебряном бору почти не осталось животных с чистыми внутренностями – ведь большинство живности заболело.$B$BПрочеши лес к востоку отсюда и убивай только здоровых воргов и медведей. Вырви их внутренности и принеси мне все чистые кишки, которые сможешь унести!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите 6 "чистых" внутренностей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! Теперь, когда у нас есть кишки и свирепый погибельник, мы сможем испытать новый штамм гнили. Осталось выбрать подходящую цель...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Запомни, мне нужны только чистые внутренности.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите со старшим аптекарем Шаной Т\'вин в Ставке Отрекшихся в Серебряном бору.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertargetname_loc8`) VALUES (26996,'Прямо под носом','В правом крыле этого проклятого собора на стене висит факел. Сдвинь его – откроется потайная дверь в комнату верховного инквизитора Фэйрбанкса. Он теперь нежить.$B$BОт него надо избавиться. Если получится, убей его прямо там. Не хочу, чтобы его видели члены Алого ордена. Уговор простой: ты убиваешь Фэйрбанкса, я тебя вознаграждаю. И ни к чему лишняя болтовня.','Убейте верховного инквизитора Фэйрбанкса.','Вернитесь к Доминику.','Верховный инквизитор Фэйрбанкс') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прямо под носом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В правом крыле этого проклятого собора на стене висит факел. Сдвинь его – откроется потайная дверь в комнату верховного инквизитора Фэйрбанкса. Он теперь нежить.$B$BОт него надо избавиться. Если получится, убей его прямо там. Не хочу, чтобы его видели члены Алого ордена. Уговор простой: ты убиваешь Фэйрбанкса, я тебя вознаграждаю. И ни к чему лишняя болтовня.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте верховного инквизитора Фэйрбанкса.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Доминику.',`completedtext_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Верховный инквизитор Фэйрбанкс',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (26997,'Обычные подозреваемые','<Самуэльсон задумчиво чешет подбородок.>$B$BВ ходе расследования... э-э... выяснилось, что заговор, скорее всего, зреет среди штормградских портовых рабочих. Скользкие типы эти докеры. Не доверяй им.$B$BОтправляйся в доки и переверни там все вверх дном. Возьми докеров за жабры. Это может потребовать много времени и усилий, но результат того стоит.$B$BДавай, действуй! Выведем предателей на чистую воду!','Допросите 6 штормградских портовых рабочих в порту Штормграда.','Поговорите с Андуином Ринном о том, что вам удалось узнать. Если принц не с вами, вы можете найти его в крепости Штормграда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обычные подозреваемые',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Самуэльсон задумчиво чешет подбородок.>$B$BВ ходе расследования... э-э... выяснилось, что заговор, скорее всего, зреет среди штормградских портовых рабочих. Скользкие типы эти докеры. Не доверяй им.$B$BОтправляйся в доки и переверни там все вверх дном. Возьми докеров за жабры. Это может потребовать много времени и усилий, но результат того стоит.$B$BДавай, действуй! Выведем предателей на чистую воду!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Допросите 6 штормградских портовых рабочих в порту Штормграда.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Андуином Ринном о том, что вам удалось узнать. Если принц не с вами, вы можете найти его в крепости Штормграда.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26998,'Закрепление успехов','Зелье наконец-то готово, но теперь нужно испытать его в деле.$B$BПоговори с дрессировщиком нетопырей и попроси у него нетопыря – тот перенесет тебя через озеро Лордамер на Рассветные острова, что к востоку отсюда. Там ты попадешь в настоящий оплот зла – логово мурлоков из племени Злобного Плавника!$B$BУгости зельем мурлоков и возвращайся ко мне с сообщением о результате.$B$BРезультатом считается только гибель всех мурлоков!','Уничтожьте 50 мурлоков из племени Злобного Плавника.','Ты уже уничтожила мурлоков из племени Злобного Плавника на Рассветных островах?','Вернитесь к старшему аптекарю Шане Т\'вин в Ставку Отрекшихся в Серебряном бору.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Закрепление успехов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Зелье наконец-то готово, но теперь нужно испытать его в деле.$B$BПоговори с дрессировщиком нетопырей и попроси у него нетопыря – тот перенесет тебя через озеро Лордамер на Рассветные острова, что к востоку отсюда. Там ты попадешь в настоящий оплот зла – логово мурлоков из племени Злобного Плавника!$B$BУгости зельем мурлоков и возвращайся ко мне с сообщением о результате.$B$BРезультатом считается только гибель всех мурлоков!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 50 мурлоков из племени Злобного Плавника.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты уже уничтожила мурлоков из племени Злобного Плавника на Рассветных островах?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старшему аптекарю Шане Т\'вин в Ставку Отрекшихся в Серебряном бору.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (26999,'Новая эра Чумных земель','Эти земли больше не принадлежат Плети. Мы, живые, возвращаем себе Лордерон.$B$BИ, как видишь, неплохо в этом преуспели. Земля цветет, деревья высоки и зелены, животные возвращаются. Однако нежить здесь все еще встречается.$B$BРастения чувствуют себя хорошо, а вот животным приходится туго. Что-то не дает им исцеляться, и мне надо узнать, что именно. Принеси мне несколько образцов тканей зараженных животных, а я их хорошенько исследую.','Раздобудьте по 4 образца следующих тканей: чумного воронкового паука, воронкового паука Ядовитого Тумана, неповоротливого чумного медведя и зараженного волка.','Как только животные вылечатся, можно будет считать, что свой долг мы здесь выполнили.','Вернитесь к агенту ШРУ Каартишу на Участок Целителей Земли в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новая эра Чумных земель',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти земли больше не принадлежат Плети. Мы, живые, возвращаем себе Лордерон.$B$BИ, как видишь, неплохо в этом преуспели. Земля цветет, деревья высоки и зелены, животные возвращаются. Однако нежить здесь все еще встречается.$B$BРастения чувствуют себя хорошо, а вот животным приходится туго. Что-то не дает им исцеляться, и мне надо узнать, что именно. Принеси мне несколько образцов тканей зараженных животных, а я их хорошенько исследую.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте по 4 образца следующих тканей: чумного воронкового паука, воронкового паука Ядовитого Тумана, неповоротливого чумного медведя и зараженного волка.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как только животные вылечатся, можно будет считать, что свой долг мы здесь выполнили.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к агенту ШРУ Каартишу на Участок Целителей Земли в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27000,'Разобраться досконально','Как же хорошо вернуться на Северный Кряж! У меня тут лесопилка, красивая жена, резвый мальчонка... я даже отметился в Серебряном Авангарде. Мы будем снабжать силы Тириона древесиной.$B$BМои дровосеки трудились не покладая рук... до тех пор, пока не понабежали эти пауки. Теперь они отказываются углубляться в лес.$B$BВозможно, ты сумеешь мне помочь. Бери одного из моих коняшек, прыгай в седло да распугай пауков. Может, мы обойдемся и без кровопролития, а просто их прогоним.','Садитесь на мустанга Дольнего Очага у лесопилки Северного Кряжа и при помощи его способности "Ржание" напугайте 25 пауков Северного Кряжа.','Что ж, сдается, они и правда боятся мустангов, но все равно так просто не уйдут. Я не могу заставить тебя все время гонять на лошади вокруг лесопилки. Да ты и не станешь.$B$BОтлично! Значит, без кровопускания не обойтись.','Вернитесь к Натаниэлю Дамаху на лесопилку Северного Кряжа в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разобраться досконально',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как же хорошо вернуться на Северный Кряж! У меня тут лесопилка, красивая жена, резвый мальчонка... я даже отметился в Серебряном Авангарде. Мы будем снабжать силы Тириона древесиной.$B$BМои дровосеки трудились не покладая рук... до тех пор, пока не понабежали эти пауки. Теперь они отказываются углубляться в лес.$B$BВозможно, ты сумеешь мне помочь. Бери одного из моих коняшек, прыгай в седло да распугай пауков. Может, мы обойдемся и без кровопролития, а просто их прогоним.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Садитесь на мустанга Дольнего Очага у лесопилки Северного Кряжа и при помощи его способности "Ржание" напугайте 25 пауков Северного Кряжа.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что ж, сдается, они и правда боятся мустангов, но все равно так просто не уйдут. Я не могу заставить тебя все время гонять на лошади вокруг лесопилки. Да ты и не станешь.$B$BОтлично! Значит, без кровопускания не обойтись.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Натаниэлю Дамаху на лесопилку Северного Кряжа в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27001,'Охота на пауков','Лорд оказал мне любезность, послав сюда нескольких новобранцев для защиты лесопилки. При твоем умении ездить верхом и их боевом мастерстве мы быстренько справимся с пауками.$B$BДавай снова прыгай на мустанга и пугай этих тварей – гони прямо к лесопилке. А уж новобранцы из Дольного Очага их тут приветят.','Садитесь на мустанга Дольнего Очага у лесопилки Северного Кряжа и с помощью его способности "Ржание" выгоните 10 пауков Северного Кряжа на новобранцев Дольного Очага у лесопилки Северного Кряжа. Одновременно вы можете гнать несколько пауков.','Вернитесь к Натаниэлю Дамаху на лесопилку Северного Кряжа в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота на пауков',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Лорд оказал мне любезность, послав сюда нескольких новобранцев для защиты лесопилки. При твоем умении ездить верхом и их боевом мастерстве мы быстренько справимся с пауками.$B$BДавай снова прыгай на мустанга и пугай этих тварей – гони прямо к лесопилке. А уж новобранцы из Дольного Очага их тут приветят.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Садитесь на мустанга Дольнего Очага у лесопилки Северного Кряжа и с помощью его способности "Ржание" выгоните 10 пауков Северного Кряжа на новобранцев Дольного Очага у лесопилки Северного Кряжа. Одновременно вы можете гнать несколько пауков.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Натаниэлю Дамаху на лесопилку Северного Кряжа в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27002,'Аудиенция у верховного лорда','Да, кстати, $n, пока ты не $gушел:ушла;... Меня тут просили передать, что с тобой хотят встретиться. Кое-кто в Дольном Очаге. Скажем так, он не раз слышал, как о тебе говорили, и заинтересовался твоей персоной.$B$BСчитай, повезло, $n. Далеко не каждый удостаивается личной аудиенции у верховного лорда Тириона Фордринга.$B$BТак что давай, отправляйся. И можешь взять одного из моих мустангов. Быстрее коней ты нигде не найдешь, можешь не сомневаться.','Отправляйтесь в Дольный Очаг, что в Западных Чумных землях, и доложите о своем прибытии верховному лорду Тириону Фордрингу.','Отправляйтесь к верховному лорду Тириону Фордрингу в Дольный Очаг в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Аудиенция у верховного лорда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Да, кстати, $n, пока ты не $gушел:ушла;... Меня тут просили передать, что с тобой хотят встретиться. Кое-кто в Дольном Очаге. Скажем так, он не раз слышал, как о тебе говорили, и заинтересовался твоей персоной.$B$BСчитай, повезло, $n. Далеко не каждый удостаивается личной аудиенции у верховного лорда Тириона Фордринга.$B$BТак что давай, отправляйся. И можешь взять одного из моих мустангов. Быстрее коней ты нигде не найдешь, можешь не сомневаться.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Дольный Очаг, что в Западных Чумных землях, и доложите о своем прибытии верховному лорду Тириону Фордрингу.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отправляйтесь к верховному лорду Тириону Фордрингу в Дольный Очаг в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27003,'Легкие деньги','Приветствую!$B$BЧто бы тебя ни привело, хорошо, что ты здесь! Мои друзья с этим, конечно, ни за что не согласятся, но нам бы совсем не помешала помощь.$B$BОткрыт доселе неизведанный древний регион – Ульдум! Сокровища, о которых ты и мечтать не $gсмел:смела;, сами просятся в руки!$B$BНам бы только провожатого, а то мало ли – бандиты, все такое...$B$BТы ведь составишь нам компанию, правда?$B$BВсе, что сумеешь унести, – твое без разговоров!','Сопроводите караван Адарры в Ульдум.','Такое чувство, что в этой камере недавно кто-то уже был.$B$BМерзость какая!','Обратитесь к Адарре в затерянном городе Тол\'вир.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Легкие деньги',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приветствую!$B$BЧто бы тебя ни привело, хорошо, что ты здесь! Мои друзья с этим, конечно, ни за что не согласятся, но нам бы совсем не помешала помощь.$B$BОткрыт доселе неизведанный древний регион – Ульдум! Сокровища, о которых ты и мечтать не $gсмел:смела;, сами просятся в руки!$B$BНам бы только провожатого, а то мало ли – бандиты, все такое...$B$BТы ведь составишь нам компанию, правда?$B$BВсе, что сумеешь унести, – твое без разговоров!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сопроводите караван Адарры в Ульдум.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Такое чувство, что в этой камере недавно кто-то уже был.$B$BМерзость какая!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Обратитесь к Адарре в затерянном городе Тол\'вир.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27004,'Заговор Сумеречного Молота','Мы прибыли сюда, чтобы проверить слухи об артефакте титанов у Врат Мастеров, что к юго-западу отсюда.$b$bУ одного из сектантов Сумеречного Молота должны быть планы того, что они затевают. И ты достанешь их нам, $n.$b$bОтправляйся к Вратам Мастеров и убивай сектантов до тех пор, пока не найдешь планы.','Достаньте планы Врат Мастеров.','<Мови смотрит на принесенные вами планы.>$B$BНо… но это просто какая-то тарабарщина!$B$BО чем тут говорится? На каком это вообще языке?','Эти планы – ключ ко всему.','Вернитесь к исследовательнице Мови в Храм Земли, что в Подземье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Заговор Сумеречного Молота',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы прибыли сюда, чтобы проверить слухи об артефакте титанов у Врат Мастеров, что к юго-западу отсюда.$b$bУ одного из сектантов Сумеречного Молота должны быть планы того, что они затевают. И ты достанешь их нам, $n.$b$bОтправляйся к Вратам Мастеров и убивай сектантов до тех пор, пока не найдешь планы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Достаньте планы Врат Мастеров.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Мови смотрит на принесенные вами планы.>$B$BНо… но это просто какая-то тарабарщина!$B$BО чем тут говорится? На каком это вообще языке?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Эти планы – ключ ко всему.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к исследовательнице Мови в Храм Земли, что в Подземье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27005,'Заговор Сумеречного Молота','Мы прибыли сюда, чтобы проверить слухи об артефакте титанов у Врат Мастеров, что к юго-западу отсюда.$b$bУ одного из сектантов Сумеречного Молота должны быть планы того, что они затевают. И ты достанешь их нам, $n.$b$bОтправляйся к Вратам Мастеров и убивай сектантов до тех пор, пока не найдешь планы.','Достаньте планы Врат Мастеров.','<Исследователь смотрит на принесенные вами планы.>$B$BЭто просто какая-то тарабарщина!$B$BО чем тут говорится? На каком это вообще языке?','Эти планы – ключ ко всему.','Вернитесь к исследователю Роу в Храм Земли, что в Подземье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Заговор Сумеречного Молота',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы прибыли сюда, чтобы проверить слухи об артефакте титанов у Врат Мастеров, что к юго-западу отсюда.$b$bУ одного из сектантов Сумеречного Молота должны быть планы того, что они затевают. И ты достанешь их нам, $n.$b$bОтправляйся к Вратам Мастеров и убивай сектантов до тех пор, пока не найдешь планы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Достаньте планы Врат Мастеров.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Исследователь смотрит на принесенные вами планы.>$B$BЭто просто какая-то тарабарщина!$B$BО чем тут говорится? На каком это вообще языке?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Эти планы – ключ ко всему.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к исследователю Роу в Храм Земли, что в Подземье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27006,'Воздушная разведка','Я пыталась пролететь над террасой и посмотреть, что там происходит, но эти жалкие создания принялись стрелять в меня, и я не смогла приблизиться.$b$bНа мой взгляд ты умеешь держать поводья в руках. Почему бы тебе не оседлать свою зверушку и не слетать на юго-запад, чтобы узнать, что там за суета?','Узнайте, что происходит за Вратами Мастеров.','Связующая спираль?! Они роют связующую спираль титанов?','Вернитесь к геологу Браге в Храм Земли, что в Подземье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Воздушная разведка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я пыталась пролететь над террасой и посмотреть, что там происходит, но эти жалкие создания принялись стрелять в меня, и я не смогла приблизиться.$b$bНа мой взгляд ты умеешь держать поводья в руках. Почему бы тебе не оседлать свою зверушку и не слетать на юго-запад, чтобы узнать, что там за суета?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Узнайте, что происходит за Вратами Мастеров.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Связующая спираль?! Они роют связующую спираль титанов?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к геологу Браге в Храм Земли, что в Подземье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (27007,'Встреча в Серебристой топи','Отлично, $n. Мы теперь точно знаем, где место встречи.$b$bВерховье Серебристой топи – это ртутное болото, которое находится к востоку отсюда. Обычно оно населено только элементалями и случайно забредшими туда каменными троггами, но наши разведчики обнаружили в этой области признаки активности Сумеречного Молота.$b$bОтправляйся туда и давай найдем способ подслушать, что будет говориться на встрече у начальника кузни.','Отправляйтесь в Верховье Серебристой топи в Подземье.','Вы достигли Верховья Серебристой топи','Нам известно место встречи.','Маруут Камневяз','Мы прибыли.','Маруут Камневяз') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Встреча в Серебристой топи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Отлично, $n. Мы теперь точно знаем, где место встречи.$b$bВерховье Серебристой топи – это ртутное болото, которое находится к востоку отсюда. Обычно оно населено только элементалями и случайно забредшими туда каменными троггами, но наши разведчики обнаружили в этой области признаки активности Сумеречного Молота.$b$bОтправляйся туда и давай найдем способ подслушать, что будет говориться на встрече у начальника кузни.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Верховье Серебристой топи в Подземье.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Вы достигли Верховья Серебристой топи',`endtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Нам известно место встречи.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Маруут Камневяз',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Мы прибыли.',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Маруут Камневяз',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27008,'Воздушная разведка','Я прекрасно управляюсь с ковром-самолетом. Но, к сожалению, когда я пыталась выяснить, чем заняты сектанты у Врат Мастеров, меня едва не сбили.$b$bПо твоему виду не скажешь, что тебя страшат полеты. Почему бы тебе не слетать на юго-запад и не посмотреть, что они там раскапывают?','Узнайте, что происходит за Вратами Мастеров.','Связующая спираль?! Они откопали связующую спираль титанов.$B$BЭто очень интересно и, возможно, очень плохо.','Вернитесь к хранителю реликвий Джес\'ке Темному Солнцу в Храм Земли в Подземье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Воздушная разведка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я прекрасно управляюсь с ковром-самолетом. Но, к сожалению, когда я пыталась выяснить, чем заняты сектанты у Врат Мастеров, меня едва не сбили.$b$bПо твоему виду не скажешь, что тебя страшат полеты. Почему бы тебе не слетать на юго-запад и не посмотреть, что они там раскапывают?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Узнайте, что происходит за Вратами Мастеров.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Связующая спираль?! Они откопали связующую спираль титанов.$B$BЭто очень интересно и, возможно, очень плохо.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к хранителю реликвий Джес\'ке Темному Солнцу в Храм Земли в Подземье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27009,'Хладовей','Амненнар Хладовей правит в Курганах Иглошкурых с помощью темной магии Плети. Мне удалось пробить отверстие в плотном сплетении ветвей над местом, где он сидит, но магия мешает мне начать атаку.$B$BЕсли ты поднимешься по Тернистому серпантину и нападешь на него, я смогу нанести удар и ослабить Амненнара до того, как он использует свои самые сильные заклинания.','Убейте Амненнара Хладовея.','Вернитесь к Користразе.','Опасайся его мощной магии!','Амненнар Хладовей') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хладовей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Амненнар Хладовей правит в Курганах Иглошкурых с помощью темной магии Плети. Мне удалось пробить отверстие в плотном сплетении ветвей над местом, где он сидит, но магия мешает мне начать атаку.$B$BЕсли ты поднимешься по Тернистому серпантину и нападешь на него, я смогу нанести удар и ослабить Амненнара до того, как он использует свои самые сильные заклинания.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Амненнара Хладовея.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Користразе.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Опасайся его мощной магии!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Амненнар Хладовей',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27010,'Ртутное погружение','Трогги Подземья в агрессивности не уступают троггам Азерота. И тем не менее, возможно, что их присутствие окажется для нас полезным.$b$bЯщики, которые они используют для добычи ртути, на болоте будут для тебя отличной маскировкой.$b$bВоспользуйся ими, чтобы $gнезамеченным:незамеченной; подобраться к лагерю Сумеречного Молота в восточной части Верховья Серебристой топи.','Добудьте ящик трогга и воспользуйтесь им, чтобы незаметно подплыть к лагерю Сумеречного Молота на востоке и подслушать.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ртутное погружение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Трогги Подземья в агрессивности не уступают троггам Азерота. И тем не менее, возможно, что их присутствие окажется для нас полезным.$b$bЯщики, которые они используют для добычи ртути, на болоте будут для тебя отличной маскировкой.$b$bВоспользуйся ими, чтобы $gнезамеченным:незамеченной; подобраться к лагерю Сумеречного Молота в восточной части Верховья Серебристой топи.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте ящик трогга и воспользуйтесь им, чтобы незаметно подплыть к лагерю Сумеречного Молота на востоке и подслушать.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27011,'Вороватая Красная Сосна','На юге расположились гноллы Красной Сосны... наши новые гости. По пути сюда ты $gмог:могла; кого-нибудь из них видеть. Натаниэль делает вид, что они не опасны, но я так не считаю.$B$BСама видела, как по ночам они таскают у нас бревна. Зачем гноллам нужна древесина, непонятно – строить-то они все равно ничего не умеют, но факт остается фактом: они нас обворовывают. Отправляйся в их лагерь и укради бревна обратно.','Соберите 10 штабелей древесины лесопилки Северного Кряжа в лагере Красной Сосны в Западных Чумных землях.','Я положу это обратно, к остальным бревнам. А Натаниэль, наверно, даже и не узнает про кражу.','Лесорубы постарше рассказывают, будто бы гноллы Красной Сосны жили здесь раньше, но покинули эти места, когда разразилась чума. Но это, конечно, никак не оправдывает их вороватые повадки.','Вернитесь к Келли Дамах на лесопилку Северного Кряжа в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вороватая Красная Сосна',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На юге расположились гноллы Красной Сосны... наши новые гости. По пути сюда ты $gмог:могла; кого-нибудь из них видеть. Натаниэль делает вид, что они не опасны, но я так не считаю.$B$BСама видела, как по ночам они таскают у нас бревна. Зачем гноллам нужна древесина, непонятно – строить-то они все равно ничего не умеют, но факт остается фактом: они нас обворовывают. Отправляйся в их лагерь и укради бревна обратно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 штабелей древесины лесопилки Северного Кряжа в лагере Красной Сосны в Западных Чумных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я положу это обратно, к остальным бревнам. А Натаниэль, наверно, даже и не узнает про кражу.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Лесорубы постарше рассказывают, будто бы гноллы Красной Сосны жили здесь раньше, но покинули эти места, когда разразилась чума. Но это, конечно, никак не оправдывает их вороватые повадки.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Келли Дамах на лесопилку Северного Кряжа в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27012,'Угроза гноллов','Даже и не знаю, что задумали эти гноллы. Они на нас пока не нападают, но их становится все больше, и похоже, оружие у них всегда наготове. Хоть я и не специалист по военным делам, но мне это кажется подозрительным.$B$BМожет, если их немного разоружить, они не будут представлять большой угрозы для нашей лесопилки? Мне станет гораздо спокойнее, если ты сходишь туда и принесешь часть их вооружения.','Соберите 6 посохов и 6 дубин гноллов из стаи Красной Сосны.','Я, конечно, не предлагаю из-за своих подозрений устроить массовое истребление гноллов. Просто хочется чувствовать себя спокойно в собственном доме.','Вернитесь к Келли Дамах на лесопилку Северного Кряжа в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Угроза гноллов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Даже и не знаю, что задумали эти гноллы. Они на нас пока не нападают, но их становится все больше, и похоже, оружие у них всегда наготове. Хоть я и не специалист по военным делам, но мне это кажется подозрительным.$B$BМожет, если их немного разоружить, они не будут представлять большой угрозы для нашей лесопилки? Мне станет гораздо спокойнее, если ты сходишь туда и принесешь часть их вооружения.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 6 посохов и 6 дубин гноллов из стаи Красной Сосны.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я, конечно, не предлагаю из-за своих подозрений устроить массовое истребление гноллов. Просто хочется чувствовать себя спокойно в собственном доме.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Келли Дамах на лесопилку Северного Кряжа в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27013,'Переживания на грани','Я рада за Натаниэля, он столько времени добирался до Северного Кряжа, а теперь, когда Алый орден убрался с дороги, он может наконец вернуться домой. Только... даже в такой милой обстановке... это не самое лучшее место для семейной жизни.$B$BВот, например, по краям этой долины шныряют бешеные лисы в поисках ничего не подозревающих жертв. То и дело я ловлю взгляд одной из них на себе.$B$BПрошу тебя, |3-6($c), избавь меня хотя бы от нескольких лис. Я не чувствую себя в безопасности, пока они здесь хозяйничают.','Убейте 12 бешеных лисиц у лесопилки Северного Кряжа в Западных Чумных землях.','Вернитесь к Келли Дамах на лесопилку Северного Кряжа в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Переживания на грани',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я рада за Натаниэля, он столько времени добирался до Северного Кряжа, а теперь, когда Алый орден убрался с дороги, он может наконец вернуться домой. Только... даже в такой милой обстановке... это не самое лучшее место для семейной жизни.$B$BВот, например, по краям этой долины шныряют бешеные лисы в поисках ничего не подозревающих жертв. То и дело я ловлю взгляд одной из них на себе.$B$BПрошу тебя, |3-6($c), избавь меня хотя бы от нескольких лис. Я не чувствую себя в безопасности, пока они здесь хозяйничают.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 бешеных лисиц у лесопилки Северного Кряжа в Западных Чумных землях.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Келли Дамах на лесопилку Северного Кряжа в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27016,'Удовольствие от охоты на вепрей','Постарайся умерить свой пыл, $n, ты стоишь перед самым великим охотником на вепрей в Азероте!$b$bВепри с их коварством, быстротой, свирепостью и толстой шкурой – добыча только для самых сильных охотников. Любителям тут не место!$b$bБьюсь об заклад, ты никогда не $gохотился:охотилась; на таких экзотических тварей. Готов поспорить на серебряный, что ты не сможешь меня переплюнуть, я убил десять вепрей. Впрочем, попытайся, вепри водятся на восточном берегу озера Лок... Только смотри, не поранься, салага!','Убейте 10 грязнобрюхих вепрей.','Вернитесь к Дерилу Юному в Приют Странников, что в Лок Модане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Удовольствие от охоты на вепрей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Постарайся умерить свой пыл, $n, ты стоишь перед самым великим охотником на вепрей в Азероте!$b$bВепри с их коварством, быстротой, свирепостью и толстой шкурой – добыча только для самых сильных охотников. Любителям тут не место!$b$bБьюсь об заклад, ты никогда не $gохотился:охотилась; на таких экзотических тварей. Готов поспорить на серебряный, что ты не сможешь меня переплюнуть, я убил десять вепрей. Впрочем, попытайся, вепри водятся на восточном берегу озера Лок... Только смотри, не поранься, салага!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 грязнобрюхих вепрей.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дерилу Юному в Приют Странников, что в Лок Модане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27017,'Воспоминания о далеком прошлом','Какие забавные воспоминания бывают. Я по шестнадцать часов в день вкалывал на поле, а раз в семь дней отправлялся в многолюдный Андорал – продать то, что вырастил. Тяжелая жизнь была, но мы справлялись.$B$BХотя о трудностях как-то и не помнится. Мысленно возвращаясь к тем дням, я вижу улыбку Глории... Андреа, приветственно машущую мне из окна...$B$BФерма совсем рядом, чуть на восток пройти, но не уверен, что мне хочется туда вернуться, $n. Я просто желаю сохранить воспоминания.','Отправляйтесь к фермерскому дому на пустошь Гаррона и соберите памятные предметы, какие сумеете найти.','Вернитесь к Дель Гаррону на Участок Целителей Земли в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Воспоминания о далеком прошлом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Какие забавные воспоминания бывают. Я по шестнадцать часов в день вкалывал на поле, а раз в семь дней отправлялся в многолюдный Андорал – продать то, что вырастил. Тяжелая жизнь была, но мы справлялись.$B$BХотя о трудностях как-то и не помнится. Мысленно возвращаясь к тем дням, я вижу улыбку Глории... Андреа, приветственно машущую мне из окна...$B$BФерма совсем рядом, чуть на восток пройти, но не уверен, что мне хочется туда вернуться, $n. Я просто желаю сохранить воспоминания.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь к фермерскому дому на пустошь Гаррона и соберите памятные предметы, какие сумеете найти.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дель Гаррону на Участок Целителей Земли в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (27018,'Вестник') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вестник',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (27019,'Плеть и Курганы','Потрясающе! Меня зовут Белнистраз, и я очень благодарен тебе за спасение. Я уже смирился с тем, что мне суждено погибнуть... Или еще хуже – стать обедом для оскверненных Плетью зверей.$B$BНо мне не хочется просто бежать, я желаю внести свой вклад в борьбу с Плетью. Ты поможешь мне? Да, это очень опасно, но кто-то должен на это пойти, а я сомневаюсь, что кто-нибудь, кроме тебя, забредет в это проклятое место.','Если вы решите помочь Белнистразу, поговорите с ним еще раз и верните ему Камень клятвы.','Я не интересуюсь политикой. Мне не важно, за Орду ты или за Альянс. Но я хочу избавить мир от зла, угрожающего всем расам... И это зло укоренилось здесь.$B$BЕсли хочешь стать настоящим героем, верни мне Камень клятвы, который я тебе дал. Там, откуда я родом, это знак согласия.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Плеть и Курганы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Потрясающе! Меня зовут Белнистраз, и я очень благодарен тебе за спасение. Я уже смирился с тем, что мне суждено погибнуть... Или еще хуже – стать обедом для оскверненных Плетью зверей.$B$BНо мне не хочется просто бежать, я желаю внести свой вклад в борьбу с Плетью. Ты поможешь мне? Да, это очень опасно, но кто-то должен на это пойти, а я сомневаюсь, что кто-нибудь, кроме тебя, забредет в это проклятое место.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Если вы решите помочь Белнистразу, поговорите с ним еще раз и верните ему Камень клятвы.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я не интересуюсь политикой. Мне не важно, за Орду ты или за Альянс. Но я хочу избавить мир от зла, угрожающего всем расам... И это зло укоренилось здесь.$B$BЕсли хочешь стать настоящим героем, верни мне Камень клятвы, который я тебе дал. Там, откуда я родом, это знак согласия.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (27022,'Уничтожить идол','Около входа стоит идол, который служит свинобразам адской жаровней. Они ведь пожирают всех своих пленников из Степей... Я могу лишить этот идол силы, но тут мне понадобится твоя помощь. Вот мой план: ты отведешь меня к идолу, я начну специальный ритуал, но в это время не смогу не то что обороняться – говорить внятно, поэтому тебе придется меня защищать.$B$BВместе мы положим конец этому кошмару. Ты поможешь мне, |3-6($r)?','Защитите Белнистраза.','Белнистраз внезапно исчезает, оставив за собой полыхающую жаровню. Вы вглядываетесь в языки пламени и видите образ красного дракона. Голос Белнистраза, более твердый, чем обычно, обращается к вам:$B$B"Мои надежды оправдались: смертные и вправду заслужили звание героев. Благодаря вам безумная жестокость этих тварей осталась в прошлом. Вы возродили мою веру в ваш народ. Возьмите эту награду – она достойна того, кто совершил такой геройский поступок.','Защитить Белнистраза, пока он проводит ритуал','Вернитесь к жаровне Белнистраза.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уничтожить идол',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Около входа стоит идол, который служит свинобразам адской жаровней. Они ведь пожирают всех своих пленников из Степей... Я могу лишить этот идол силы, но тут мне понадобится твоя помощь. Вот мой план: ты отведешь меня к идолу, я начну специальный ритуал, но в это время не смогу не то что обороняться – говорить внятно, поэтому тебе придется меня защищать.$B$BВместе мы положим конец этому кошмару. Ты поможешь мне, |3-6($r)?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Защитите Белнистраза.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Белнистраз внезапно исчезает, оставив за собой полыхающую жаровню. Вы вглядываетесь в языки пламени и видите образ красного дракона. Голос Белнистраза, более твердый, чем обычно, обращается к вам:$B$B"Мои надежды оправдались: смертные и вправду заслужили звание героев. Благодаря вам безумная жестокость этих тварей осталась в прошлом. Вы возродили мою веру в ваш народ. Возьмите эту награду – она достойна того, кто совершил такой геройский поступок.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Защитить Белнистраза, пока он проводит ритуал',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к жаровне Белнистраза.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27024,'Соучастники','Амненнар – главная, но не единственная угроза. Чтобы отвоевать Курганы Иглошкурых, нужно уничтожить его лейтенантов.$B$BОбжора охраняет подход к Тернистому серпантину.$B$BМордреш стоит на груде костей и приказывает воинам Плети совершать еще более жестокие вещи.$B$BТутен\'каш обитает под землей. Чтобы вызвать его, нужно трижды ударить в гонг в зале Призыва.$B$BУдачи, $gхрабрый герой:храбрая героиня;.','Убейте Обжору, Мордреша Огненного Глаза и Тутен\'каша.','Отлично! Теперь, когда Плеть лишилась своих главарей, она не представляет значительной угрозы.','Вернитесь к Користразе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Соучастники',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Амненнар – главная, но не единственная угроза. Чтобы отвоевать Курганы Иглошкурых, нужно уничтожить его лейтенантов.$B$BОбжора охраняет подход к Тернистому серпантину.$B$BМордреш стоит на груде костей и приказывает воинам Плети совершать еще более жестокие вещи.$B$BТутен\'каш обитает под землей. Чтобы вызвать его, нужно трижды ударить в гонг в зале Призыва.$B$BУдачи, $gхрабрый герой:храбрая героиня;.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Обжору, Мордреша Огненного Глаза и Тутен\'каша.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! Теперь, когда Плеть лишилась своих главарей, она не представляет значительной угрозы.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Користразе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27025,'Колючая работа','Начался сезон колкополоха! 89% травм, связанных с семенами, получены от семян колкополоха.$b$bТы найдешь эти семена в лесных низинах, к северу от Приюта. Чаще всего их можно обнаружить у корней деревьев, они будут колоть и ранить тебя.$b$bЯ бы рекомендовала держаться от них подальше, но на самом деле мне $gнужен помощник, который:нужна помощница, которая; соберет их во имя всеобщей безопасности! Принеси мне семена колкополоха, чтобы мы могли быть уверенными, что никто не поранится.','Соберите 6 семян колкополоха.','Мне поступило также предупреждение о повышенной активности медведей в лесах! Им нравятся эти семена колкополоха.$B$BХорошо, что ты собрала эти семена, таким образом, они не смогут привлечь еще больше медведей!','Обращайся с ними осторожно, слышишь!','Вернитесь к смотрителю Пипси в Приют Странников, что в Лок Модане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Колючая работа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Начался сезон колкополоха! 89% травм, связанных с семенами, получены от семян колкополоха.$b$bТы найдешь эти семена в лесных низинах, к северу от Приюта. Чаще всего их можно обнаружить у корней деревьев, они будут колоть и ранить тебя.$b$bЯ бы рекомендовала держаться от них подальше, но на самом деле мне $gнужен помощник, который:нужна помощница, которая; соберет их во имя всеобщей безопасности! Принеси мне семена колкополоха, чтобы мы могли быть уверенными, что никто не поранится.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 6 семян колкополоха.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мне поступило также предупреждение о повышенной активности медведей в лесах! Им нравятся эти семена колкополоха.$B$BХорошо, что ты собрала эти семена, таким образом, они не смогут привлечь еще больше медведей!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Обращайся с ними осторожно, слышишь!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к смотрителю Пипси в Приют Странников, что в Лок Модане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27026,'Повышенная боевая готовность: рыси','Остановитесь! Мне стало известно, что возле приюта видели рысей. Рысей!$b$bПредставьте себе, мне никогда не доводилось видеть рысей, но нет никаких сомнений, что они опасны. Как горные львы или вроде того. Никто не должен выходить, пока окрестности не станут безопасными!$b$bНикто, кроме тебя. Я заплачу тебе, если ты нам поможешь, |3-6($c). Но смотри, чтобы тебе не расцарапали лицо.','Убейте 8 рысей.','Вернитесь к смотрителю Пипси в Приют Странников, что в Лок Модане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Повышенная боевая готовность: рыси',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Остановитесь! Мне стало известно, что возле приюта видели рысей. Рысей!$b$bПредставьте себе, мне никогда не доводилось видеть рысей, но нет никаких сомнений, что они опасны. Как горные львы или вроде того. Никто не должен выходить, пока окрестности не станут безопасными!$b$bНикто, кроме тебя. Я заплачу тебе, если ты нам поможешь, |3-6($c). Но смотри, чтобы тебе не расцарапали лицо.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 рысей.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к смотрителю Пипси в Приют Странников, что в Лок Модане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27028,'Охота на ос','Добудьте 6 прозрачных крыльев болотной осы.','Прекрасные образцы! Держи свой выигрыш, девочка.','Как там наши осы?','Вернитесь к Мареку Железносерду в Приют Странников, что в Лок Модане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота на ос',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 6 прозрачных крыльев болотной осы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасные образцы! Держи свой выигрыш, девочка.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как там наши осы?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мареку Железносерду в Приют Странников, что в Лок Модане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27029,'Лекарство от Плети','Вместо того чтобы убивать один выводок Плети за другим, нужно найти способ остановить превращение живых в нежить. Я уже разработала рецепт специального порошка: один вдох – и процесс перерождения прекратится!$B$BДля приготовления этого препарата мне понадобятся тусклые клыки свинобразов-нежити. Принеси их мне, и тогда мы сможем навсегда остановить экспансию Плети.','Соберите 20 тусклых клыков.','Вернитесь к Користразе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лекарство от Плети',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вместо того чтобы убивать один выводок Плети за другим, нужно найти способ остановить превращение живых в нежить. Я уже разработала рецепт специального порошка: один вдох – и процесс перерождения прекратится!$B$BДля приготовления этого препарата мне понадобятся тусклые клыки свинобразов-нежити. Принеси их мне, и тогда мы сможем навсегда остановить экспансию Плети.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 20 тусклых клыков.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Користразе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27030,'Связка лисьих хвостов','В последнее время в холмах стало больше лис. Хитрые бестии, эти лисы. Отличная проверка охотничьих навыков и к тому же неплохая добыча!$b$bГлавное – их хвосты, $gпарень:девочка;. Пушистые, превосходного качества – они будут так же отлично смотреться на твоем поясе, отпугивая блох, как и в качестве отделки для перчаток какого-нибудь модника благородного происхождения.$b$bСлушай, что я говорю. Главное удовольствие – от самой охоты! Но если ты принесешь мне еще и несколько лисьих хвостов, я с удовольствием заплачу тебе за них. Лис можно найти к северу от Приюта, в нижних лесах.','Добудьте 7 пушистых лисьих хвостов.','Ага, видишь? Товары отличного качества. Ты славно поработала.','Вернитесь к Мареку Железносерду в Приют Охотников, что в Лок Модане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Связка лисьих хвостов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В последнее время в холмах стало больше лис. Хитрые бестии, эти лисы. Отличная проверка охотничьих навыков и к тому же неплохая добыча!$b$bГлавное – их хвосты, $gпарень:девочка;. Пушистые, превосходного качества – они будут так же отлично смотреться на твоем поясе, отпугивая блох, как и в качестве отделки для перчаток какого-нибудь модника благородного происхождения.$b$bСлушай, что я говорю. Главное удовольствие – от самой охоты! Но если ты принесешь мне еще и несколько лисьих хвостов, я с удовольствием заплачу тебе за них. Лис можно найти к северу от Приюта, в нижних лесах.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 7 пушистых лисьих хвостов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ага, видишь? Товары отличного качества. Ты славно поработала.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мареку Железносерду в Приют Охотников, что в Лок Модане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27031,'Основа крыла','С гирокоптерами я закончил. Все в порядке, они работают. Но разве настоящему гному этого достаточно? Я хочу настоящего полета, с КРЫЛЬЯМИ!$b$BВ течение нескольких лет я изучал птиц, пытаясь понять, как сконструировать машину, которая бы летала, как птица. Это элегантное парение и стремительное пикирование, этот рассекаемый крыльями воздух... ах.$b$bТы! Ты можешь мне помочь. Мне нужны самые лучше маховые перья, какие ты сможешь найти. Золотистые орлы, обитающие вблизи Приюта, прекрасно подойдут...','Соберите 3 безупречных маховых пера золотистого орла.','Прекрасно. Ты знаешь толк в качестве!$B$BВеликие умы думают одинаково! Очевидно, у тебя есть страсть к полетам и охоте, так что, может быть, ты сможешь помочь мне и в дальнейшем…','Мне нужны только самые лучше маховые перья!','Вернитесь к Бинглзу Подрывайстеру в Приют Охотников, что в Лок Модане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Основа крыла',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','С гирокоптерами я закончил. Все в порядке, они работают. Но разве настоящему гному этого достаточно? Я хочу настоящего полета, с КРЫЛЬЯМИ!$b$BВ течение нескольких лет я изучал птиц, пытаясь понять, как сконструировать машину, которая бы летала, как птица. Это элегантное парение и стремительное пикирование, этот рассекаемый крыльями воздух... ах.$b$bТы! Ты можешь мне помочь. Мне нужны самые лучше маховые перья, какие ты сможешь найти. Золотистые орлы, обитающие вблизи Приюта, прекрасно подойдут...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 3 безупречных маховых пера золотистого орла.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно. Ты знаешь толк в качестве!$B$BВеликие умы думают одинаково! Очевидно, у тебя есть страсть к полетам и охоте, так что, может быть, ты сможешь помочь мне и в дальнейшем…',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мне нужны только самые лучше маховые перья!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бинглзу Подрывайстеру в Приют Охотников, что в Лок Модане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27033,'Сердце небесного долгонога','Открыв крышку, вы видите внушительное механическое устройство с кучей проводов, шестеренок и черт знает чем еще.$b$bВы без труда вынимаете его. Теперь нужно отнести устройство Бинглзу.','Отнесите супермеханический управляющий модуль Бинглзу Подрывайстеру в Приют Странников.','Прекрасно! Я подправил баланс крыльев, все, что нужно, у меня есть, осталось найти пилота.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сердце небесного долгонога',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Открыв крышку, вы видите внушительное механическое устройство с кучей проводов, шестеренок и черт знает чем еще.$b$bВы без труда вынимаете его. Теперь нужно отнести устройство Бинглзу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите супермеханический управляющий модуль Бинглзу Подрывайстеру в Приют Странников.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно! Я подправил баланс крыльев, все, что нужно, у меня есть, осталось найти пилота.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27034,'Переходный возраст','Небесного долгонога я делал не для себя, $n. И даже не для соплеменников гномов. Я хочу, чтобы на нем летал только мой сын.$b$bЯ стар, скорость реакции у меня уже не та, что раньше. Но мой мальчик Андо мог бы стать лучшим пилотом, какого только знал Азерот. Если бы только он преодолел свои подростковые переменчивые настроения!$b$bЦелыми днями он сидит на берегу озера и смотрит в небо. Что-то его беспокоит, но он отказывается поговорить об этом со мной, с родным отцом. Я в растерянности!$b$bПожалуйста, $n, не $gмог:могла; бы ты поговорить с ним? Скажи ему, что он мне нужен, чтобы пилотировать небесного долгонога!','Поговорите с Андо Подрывайстером на восточном берегу озера Лок.','Мне плевать на моего отца и его глупые изобретения! Все это полная чушь!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Переходный возраст',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Небесного долгонога я делал не для себя, $n. И даже не для соплеменников гномов. Я хочу, чтобы на нем летал только мой сын.$b$bЯ стар, скорость реакции у меня уже не та, что раньше. Но мой мальчик Андо мог бы стать лучшим пилотом, какого только знал Азерот. Если бы только он преодолел свои подростковые переменчивые настроения!$b$bЦелыми днями он сидит на берегу озера и смотрит в небо. Что-то его беспокоит, но он отказывается поговорить об этом со мной, с родным отцом. Я в растерянности!$b$bПожалуйста, $n, не $gмог:могла; бы ты поговорить с ним? Скажи ему, что он мне нужен, чтобы пилотировать небесного долгонога!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Андо Подрывайстером на восточном берегу озера Лок.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мне плевать на моего отца и его глупые изобретения! Все это полная чушь!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27035,'Выстоять','Посмотри на них. Служители культа Сумеречного Молота превратили эту землю в руины!$b$bИз-за их культа произошел весь этот катаклизм, разрушилась Каменная Плотина и пересохло озеро Лок. А теперь они бродят среди руин, как будто они здесь у себя дома!$b$bЕсли бы в мире была хоть капля справедливости, кто-нибудь отправился бы в их лагерь и разбил этот их артефакт. Но я слишком слаб, чтобы даже пытаться.$b$bИ ни у кого из остальных не хватает для этого смелости! Даже у тебя! Понимаешь? Все это так глупо...','Уничтожьте сумеречный ваятель земли в центре лагеря Сумеречного Молота.','Ты сделала это? Ты сделала это! Ты сразилась с ними и победила!$B$BВсе-таки есть какая-то надежда…','Вернитесь к Андо Подрывайстеру в Лок Модан.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Выстоять',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Посмотри на них. Служители культа Сумеречного Молота превратили эту землю в руины!$b$bИз-за их культа произошел весь этот катаклизм, разрушилась Каменная Плотина и пересохло озеро Лок. А теперь они бродят среди руин, как будто они здесь у себя дома!$b$bЕсли бы в мире была хоть капля справедливости, кто-нибудь отправился бы в их лагерь и разбил этот их артефакт. Но я слишком слаб, чтобы даже пытаться.$b$bИ ни у кого из остальных не хватает для этого смелости! Даже у тебя! Понимаешь? Все это так глупо...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте сумеречный ваятель земли в центре лагеря Сумеречного Молота.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты сделала это? Ты сделала это! Ты сразилась с ними и победила!$B$BВсе-таки есть какая-то надежда…',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Андо Подрывайстеру в Лок Модан.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27036,'Месть Вайрины','Убейте старого Черношкура и добудьте его голову.','Принесите голову Старины Черношкура Дерилу Юному в Приют Охотников, что в Лок Модане.','Сделай это для Дерила.','Черношкур-старший') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Месть Вайрины',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте старого Черношкура и добудьте его голову.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите голову Старины Черношкура Дерилу Юному в Приют Охотников, что в Лок Модане.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Сделай это для Дерила.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Черношкур-старший',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (27037,'Месть Вайрины','Ради всего святого! Не приноси в Приют такое... это негигиенично, неприлично, не... не... негигиенично!$b$BСкорее убери ее отсюда! Никому здесь не нужны твои жуткие трофеи!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Месть Вайрины',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ради всего святого! Не приноси в Приют такое... это негигиенично, неприлично, не... не... негигиенично!$b$BСкорее убери ее отсюда! Никому здесь не нужны твои жуткие трофеи!',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27038,'Недостающие детали','<Сержант обращает внимание на вас.>$B$BСлушай, если хочешь помочь, скажи Кремневому Затвору, чтобы он от меня отстал. Дело вот в чем: целую партию деталей для осадных машин отправили куда-то не туда, и теперь они разбросаны по всему порту.$B$BСобери недостающие детали и доставь их Кремневому Затвору, чтобы он мог закончить работу. Он ждет рядом, через дорогу.','Найдите 5 недостающих деталей в окрестностях порта Штормграда.','<Кремневый Затвор алчно перебирает детали, бросая через плечо отобранные.>$B$BО да, это самое оно.$B$B<Он засовывает голову в один из ящиков.>$B$BНо где же мой порох? Тут есть все, кроме пороха. Мне нужна взрывчатка, парень!$B$BТак и передай своему королю: нет пороха – до свидания. Если мне не дадут тут что-нибудь взорвать, я не двинусь с места.','А? Че?$B$BМои детали! Где они?! Нельзя построить танк без деталей!$B$BА если и можно, то маленький. И совсем нефе... нефективный.','Доставьте детали Фарго Кремневому Затвору, который находится в порту Штормграда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Недостающие детали',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Сержант обращает внимание на вас.>$B$BСлушай, если хочешь помочь, скажи Кремневому Затвору, чтобы он от меня отстал. Дело вот в чем: целую партию деталей для осадных машин отправили куда-то не туда, и теперь они разбросаны по всему порту.$B$BСобери недостающие детали и доставь их Кремневому Затвору, чтобы он мог закончить работу. Он ждет рядом, через дорогу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите 5 недостающих деталей в окрестностях порта Штормграда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Кремневый Затвор алчно перебирает детали, бросая через плечо отобранные.>$B$BО да, это самое оно.$B$B<Он засовывает голову в один из ящиков.>$B$BНо где же мой порох? Тут есть все, кроме пороха. Мне нужна взрывчатка, парень!$B$BТак и передай своему королю: нет пороха – до свидания. Если мне не дадут тут что-нибудь взорвать, я не двинусь с места.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','А? Че?$B$BМои детали! Где они?! Нельзя построить танк без деталей!$B$BА если и можно, то маленький. И совсем нефе... нефективный.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доставьте детали Фарго Кремневому Затвору, который находится в порту Штормграда.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27039,'Опасные намерения','Знаешь, почему Мортий к твоему имени прибавляет "нуб", $n? Потому что он невежественный подхалим, которому выбранный не по размеру шлем сползает на глаза. "НУБ" – твое новое звание. Ты теперь часть НОВОПОДГОРОДСКОГО УДАРНОГО БАТАЛЬОНА.$B$BНо хватит шуток, поговорим о серьезном. Два дня назад я отправил ловчую смерти Йорик на тайное задание. Она должна была собрать сведения об Освободительном фронте Гилнеаса и вернуться. Прошло три дня, а от нее ни слуху ни духу.$B$BОтправляйся на юго-запад, в Делянку Ивара, и разыщи Йорик, $n.','Разыщите ловчую смерти Йорик в Делянке Ивара в Серебряном бору.','Что, Бельмонт занервничал и решил послать за мной новичка? Слушай, я уже третьи сутки веду наблюдение за домом Ивара. Твое присутствие здесь ставит под угрозу успех всей операции!$B$BНекогда объяснять. Нужно действовать незамедлительно, иначе задание будет провалено.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Опасные намерения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Знаешь, почему Мортий к твоему имени прибавляет "нуб", $n? Потому что он невежественный подхалим, которому выбранный не по размеру шлем сползает на глаза. "НУБ" – твое новое звание. Ты теперь часть НОВОПОДГОРОДСКОГО УДАРНОГО БАТАЛЬОНА.$B$BНо хватит шуток, поговорим о серьезном. Два дня назад я отправил ловчую смерти Йорик на тайное задание. Она должна была собрать сведения об Освободительном фронте Гилнеаса и вернуться. Прошло три дня, а от нее ни слуху ни духу.$B$BОтправляйся на юго-запад, в Делянку Ивара, и разыщи Йорик, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите ловчую смерти Йорик в Делянке Ивара в Серебряном бору.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что, Бельмонт занервничал и решил послать за мной новичка? Слушай, я уже третьи сутки веду наблюдение за домом Ивара. Твое присутствие здесь ставит под угрозу успех всей операции!$B$BНекогда объяснять. Нужно действовать незамедлительно, иначе задание будет провалено.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27040,'Простая дешифровка','У нас нет инструментов, чтобы расшифровать эти планы. А у Сумеречного Молота есть.$b$bНе будешь ли так $gлюбезен:любезна; отнести планы туда и пропустить их через одноразовые дешифровальные устройства?','Расшифруйте 6 планов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Простая дешифровка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У нас нет инструментов, чтобы расшифровать эти планы. А у Сумеречного Молота есть.$b$bНе будешь ли так $gлюбезен:любезна; отнести планы туда и пропустить их через одноразовые дешифровальные устройства?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Расшифруйте 6 планов.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27041,'Простая дешифровка','У нас нет инструментов, чтобы расшифровать эти планы. А вот у Сумеречного Молота наверняка есть.$b$bНе будешь ли так $gлюбезен:любезна; отнести планы туда и пропустить их через одноразовые дешифровальные устройства?','Расшифруйте 6 планов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Простая дешифровка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У нас нет инструментов, чтобы расшифровать эти планы. А вот у Сумеречного Молота наверняка есть.$b$bНе будешь ли так $gлюбезен:любезна; отнести планы туда и пропустить их через одноразовые дешифровальные устройства?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Расшифруйте 6 планов.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27042,'Победить огонь, воду и воздух при помощи...','$gВидал:Видала; там одного незатыкающегося кретина? Это не кто иной, как Хазен Каул, их предводитель.$b$bЧеловек, у которого крыша поехала от силы, которую он тянет из элементалей. Из-за этой силы победить его почти невозможно.$b$bДумаю, в борьбе с ним тебе поможет только одно – сначала убить всех элементалей, взять их обереги и получить защиту от магии разных стихий. Они защитят тебя от заклинаний Хазена.$b$bНу, по крайней мере от многих.','Получите обереги огня, воды и воздуха, а затем убейте Хазена Каула.','Отлично! У детишек теперь будет одним ночным страхом меньше.$B$BДа и у нас больше не будет болеть о нем голова!$B$BНу а теперь давай посмотрим в этих ящиках, думаю, в них найдется награда для тебя.','Вернитесь к геологу Браге в Храм Земли, что в Подземье.','Сначала получи обереги огня, воды и воздуха. Потом убей его!','Хазен Каул') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Победить огонь, воду и воздух при помощи...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$gВидал:Видала; там одного незатыкающегося кретина? Это не кто иной, как Хазен Каул, их предводитель.$b$bЧеловек, у которого крыша поехала от силы, которую он тянет из элементалей. Из-за этой силы победить его почти невозможно.$b$bДумаю, в борьбе с ним тебе поможет только одно – сначала убить всех элементалей, взять их обереги и получить защиту от магии разных стихий. Они защитят тебя от заклинаний Хазена.$b$bНу, по крайней мере от многих.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Получите обереги огня, воды и воздуха, а затем убейте Хазена Каула.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! У детишек теперь будет одним ночным страхом меньше.$B$BДа и у нас больше не будет болеть о нем голова!$B$BНу а теперь давай посмотрим в этих ящиках, думаю, в них найдется награда для тебя.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к геологу Браге в Храм Земли, что в Подземье.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Сначала получи обереги огня, воды и воздуха. Потом убей его!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Хазен Каул',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27043,'Победить огонь, воду и воздух при помощи...','$gВидел:Видела; ли ты там человека, который, не переставая, орет? Это не кто иной, как Хазен Каул, их предводитель.$b$bДоподлинно известно, что он вытягивает силу из элементалей, что и нарушило его психику. Но, к сожалению, это же его сделало практически неуязвимым.$b$bЕсли ты собираешься биться с ним, прежде всего тебе нужно убить всех элементалей, взять их обереги и получить защиту от магии их стихий. Это должно защитить тебя от заклинаний Хазена.$b$bНу, по крайней мере от большей их части.','Получите обереги огня, воды и воздуха, а затем убейте Хазена Каула.','Небывалая отвага.$B$B<Хранитель реликвий окидывает вас взглядом с головы до ног.>$B$BНаграда будет соответствующей. Что-нибудь достойное такого мужественного воина.','Вернитесь к хранителю реликвий Джес\'ке Темному Солнцу в Храм Земли в Подземье.','Сначала получи обереги огня, воды и воздуха. Потом убей его!','Хазен Каул') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Победить огонь, воду и воздух при помощи...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$gВидел:Видела; ли ты там человека, который, не переставая, орет? Это не кто иной, как Хазен Каул, их предводитель.$b$bДоподлинно известно, что он вытягивает силу из элементалей, что и нарушило его психику. Но, к сожалению, это же его сделало практически неуязвимым.$b$bЕсли ты собираешься биться с ним, прежде всего тебе нужно убить всех элементалей, взять их обереги и получить защиту от магии их стихий. Это должно защитить тебя от заклинаний Хазена.$b$bНу, по крайней мере от большей их части.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Получите обереги огня, воды и воздуха, а затем убейте Хазена Каула.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Небывалая отвага.$B$B<Хранитель реликвий окидывает вас взглядом с головы до ног.>$B$BНаграда будет соответствующей. Что-нибудь достойное такого мужественного воина.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к хранителю реликвий Джес\'ке Темному Солнцу в Храм Земли в Подземье.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Сначала получи обереги огня, воды и воздуха. Потом убей его!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Хазен Каул',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (27044,'Крестьянские заботы','Я пока не готов к возвращению в крепость. Не хочешь помочь мне еще в одном деле?$B$BНедавно один фермер пожаловался королю на то, что у него пропадают коровы. Отец обещал провести расследование, но у стражи сейчас столько дел, что на это уйдет несколько недель!$B$BМожет, ты этим займешься? Крестьяне будут счастливы, что королевская семья о них заботится. Кроме того, это же всего лишь пропавшие коровы. Ничего серьезного.$B$BОтведи меня к фермеру Уоллертону. Он здесь, в городе!','Проводите принца Андуина к фермеру Уоллертону, который находится в Штормграде, на ферме Уоллертона. Если вы потеряете принца, то сможете найти его в крепости Штормграда.','<Завидев принца, фермер Уоллертон неуклюже падает на одно колено.>$B$BВ-ваше высочество!','Принц Андуин успешно сопровожден к фермеру Уоллертону','Поговорите с фермером Уоллертоном, который находится на ферме Уоллертона в Штормграде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Крестьянские заботы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я пока не готов к возвращению в крепость. Не хочешь помочь мне еще в одном деле?$B$BНедавно один фермер пожаловался королю на то, что у него пропадают коровы. Отец обещал провести расследование, но у стражи сейчас столько дел, что на это уйдет несколько недель!$B$BМожет, ты этим займешься? Крестьяне будут счастливы, что королевская семья о них заботится. Кроме того, это же всего лишь пропавшие коровы. Ничего серьезного.$B$BОтведи меня к фермеру Уоллертону. Он здесь, в городе!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проводите принца Андуина к фермеру Уоллертону, который находится в Штормграде, на ферме Уоллертона. Если вы потеряете принца, то сможете найти его в крепости Штормграда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Завидев принца, фермер Уоллертон неуклюже падает на одно колено.>$B$BВ-ваше высочество!',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Принц Андуин успешно сопровожден к фермеру Уоллертону',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с фермером Уоллертоном, который находится на ферме Уоллертона в Штормграде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27045,'В ожидании кровопускания','Лидер фронта освобождения Гилнеаса Дарий Краули встречался еще с одним воргеном в этом доме за последние три дня. Не знаю, что там затевается, но нам надо проникнуть в дом и найти укрытие, чтобы подслушать их разговор.$B$BИ сделать это нужно сейчас – или никогда, |3-6($r). Другого шанса может не представиться.$B$BТолько обещай, что если у меня ничего не выйдет, ты вернешься в Ставку Отрекшихся и расскажешь Бельмонту обо всем, что мы узнали.','Проникните в дом Ивара и найдите подходящее местечко наверху, чтобы спрятаться. Затем подслушайте, что будет говорить лорд Дарий Краули.','Вернитесь к командиру ловчих смерти Бельмонту в Ставку Отрекшихся в Серебряном бору.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В ожидании кровопускания',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Лидер фронта освобождения Гилнеаса Дарий Краули встречался еще с одним воргеном в этом доме за последние три дня. Не знаю, что там затевается, но нам надо проникнуть в дом и найти укрытие, чтобы подслушать их разговор.$B$BИ сделать это нужно сейчас – или никогда, |3-6($r). Другого шанса может не представиться.$B$BТолько обещай, что если у меня ничего не выйдет, ты вернешься в Ставку Отрекшихся и расскажешь Бельмонту обо всем, что мы узнали.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проникните в дом Ивара и найдите подходящее местечко наверху, чтобы спрятаться. Затем подслушайте, что будет говорить лорд Дарий Краули.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру ловчих смерти Бельмонту в Ставку Отрекшихся в Серебряном бору.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27046,'Червинтовая угроза','Червинты, поедая камни, так портят наш дом, что когда-нибудь он может обрушиться. Мы убиваем одного – появляются еще два. Но нельзя опускать руки. Они должны быть истреблены.$b$bОтправляйся в Гремящие глубины и убей столько червинтов, сколько сможешь.','Убейте 10 червинтов.','Ты справился с врагом, казавшимся нам непобедимым. Спасибо тебе за помощь.','Вернитесь к Фелсену Выносливому к Трону Теразан.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Червинтовая угроза',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Червинты, поедая камни, так портят наш дом, что когда-нибудь он может обрушиться. Мы убиваем одного – появляются еще два. Но нельзя опускать руки. Они должны быть истреблены.$b$bОтправляйся в Гремящие глубины и убей столько червинтов, сколько сможешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 червинтов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты справился с врагом, казавшимся нам непобедимым. Спасибо тебе за помощь.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фелсену Выносливому к Трону Теразан.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27047,'Пейнит','Некоторые редкие кристаллы растут в наиболее опасных местах. В Гремящих глубинах ты найдешь формирования пейнита, который гораздо лучше золота, столь ценимого твоими собратьями.$b$bПоскольку ты из плоти и крови и $gневелик:невелика; ростом, ты сможешь пробраться в Гремящие глубины и достать для меня кусочки пейнита. $gГотов:Готова; ли ты подвергнуться такой опасности?','Соберите 10 кусочков пейнита.','Пейнит – это очень ценный для нас материал. Отчасти из-за того, что мы неспособны добыть его самостоятельно.','Вернитесь к Фелсену Выносливому к Трону Теразан.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пейнит',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Некоторые редкие кристаллы растут в наиболее опасных местах. В Гремящих глубинах ты найдешь формирования пейнита, который гораздо лучше золота, столь ценимого твоими собратьями.$b$bПоскольку ты из плоти и крови и $gневелик:невелика; ростом, ты сможешь пробраться в Гремящие глубины и достать для меня кусочки пейнита. $gГотов:Готова; ли ты подвергнуться такой опасности?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 кусочков пейнита.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Пейнит – это очень ценный для нас материал. Отчасти из-за того, что мы неспособны добыть его самостоятельно.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фелсену Выносливому к Трону Теразан.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27048,'Подземная экономика','Привет! Я пытаюсь вывезти некоторое количество этих кристаллов, элементали хорошо за них платят... Если поможешь мне собрать кристаллы всех видов, я поделюсь с тобой прибылью.$b$bВоспользуйся вот этими бомбами, чтобы откалывать кристаллы от крупных образований.$b$bУ меня есть дурная привычка очень плотно набивать взрывчатку в сумку. Постарайся не трясти ее.','Воспользуйтесь бомбами Рикет, чтобы собрать 3 кристалла насыщенного алебастра, 3 кристалла насыщенного аметиста, 3 кристалла насыщенного целестина и 3 кристалла насыщенного граната.','Классно!$B$BТеперь я проверну это дельце. Кучка тупиц придет к Трону Теразан и отдаст все свое золото Д\'лому за мусор непонятного происхождения. А он отдаст это золото мне за кристаллы. И на этих каменных обломках я разбогатею.$B$BНикому не говори об этом. Мне не нужна конкуренция.$B$BМожет, потом ты придешь еще раз и снова поможешь мне наломать кристаллов?','Бум?','Поговорите с Рикет в Гремящих глубинах, что в Подземье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подземная экономика',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Привет! Я пытаюсь вывезти некоторое количество этих кристаллов, элементали хорошо за них платят... Если поможешь мне собрать кристаллы всех видов, я поделюсь с тобой прибылью.$b$bВоспользуйся вот этими бомбами, чтобы откалывать кристаллы от крупных образований.$b$bУ меня есть дурная привычка очень плотно набивать взрывчатку в сумку. Постарайся не трясти ее.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь бомбами Рикет, чтобы собрать 3 кристалла насыщенного алебастра, 3 кристалла насыщенного аметиста, 3 кристалла насыщенного целестина и 3 кристалла насыщенного граната.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Классно!$B$BТеперь я проверну это дельце. Кучка тупиц придет к Трону Теразан и отдаст все свое золото Д\'лому за мусор непонятного происхождения. А он отдаст это золото мне за кристаллы. И на этих каменных обломках я разбогатею.$B$BНикому не говори об этом. Мне не нужна конкуренция.$B$BМожет, потом ты придешь еще раз и снова поможешь мне наломать кристаллов?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Бум?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Рикет в Гремящих глубинах, что в Подземье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27049,'Рыхлая порода','Багровый зал все еще не очищен. Уничтожь грибных чудищ, которые вносят грязь в наш мир. Мы будем убивать их, пока они не перестанут расти.','Убейте 8 грибных чудищ.','Очень сложно справиться с однажды начавшимся ростом этих чудищ. Но если мы будем настойчивы, в один прекрасный день наш мир будет очищен от грязи.','Вернитесь к Горсику Беспокойному к Трону Теразан.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рыхлая порода',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Багровый зал все еще не очищен. Уничтожь грибных чудищ, которые вносят грязь в наш мир. Мы будем убивать их, пока они не перестанут расти.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 грибных чудищ.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Очень сложно справиться с однажды начавшимся ростом этих чудищ. Но если мы будем настойчивы, в один прекрасный день наш мир будет очищен от грязи.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Горсику Беспокойному к Трону Теразан.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27050,'Грибная ярость','В Багровом зале есть что-то, что служит стимулом для появления на скале отвратительных ростков. Появляются все новые грибы, их нужно уничтожить, прежде чем они распространятся.','Уничтожьте 10 выросших грибов в Багровом зале.','У тебя отлично получается наступать на разные вещи. Из тебя бы вышел неплохой великан.','Вернитесь к Горсику Беспокойному к Трону Теразан.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Грибная ярость',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В Багровом зале есть что-то, что служит стимулом для появления на скале отвратительных ростков. Появляются все новые грибы, их нужно уничтожить, прежде чем они распространятся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 10 выросших грибов в Багровом зале.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','У тебя отлично получается наступать на разные вещи. Из тебя бы вышел неплохой великан.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Горсику Беспокойному к Трону Теразан.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27051,'Настойчивость','Ты $gубил:убила; Глопа, но с троггами еще не покончено. Их прислужники оставили после себя реагент роста, который продолжает распространять семена порчи в Багровом зале.$b$bВыследи их и собери все остатки верлокской чудоросли, сколько найдешь. Мы должны окончательно от нее избавиться.','Отберите мешочек чудоросли у обитателей Верлока у Багрового зала.','Вернитесь к Руберику к Трону Теразан.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Настойчивость',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gубил:убила; Глопа, но с троггами еще не покончено. Их прислужники оставили после себя реагент роста, который продолжает распространять семена порчи в Багровом зале.$b$bВыследи их и собери все остатки верлокской чудоросли, сколько найдешь. Мы должны окончательно от нее избавиться.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отберите мешочек чудоросли у обитателей Верлока у Багрового зала.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Руберику к Трону Теразан.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27052,'Последние из Сумеречного Молота','В Подземье все еще есть сумеречные наездники на драконах. Их мало. Они слабы. Но все же они есть.$b$bЛети с Эозерой и найди их. Со временем мы уничтожим их всех до единого. Во имя Матери-Скалы.','Выследите сумеречного наездника на хрустальнокрылом каменном драконе.','Вернитесь к Террату Непоколебимому к Трону Теразан, что в Подземье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Последние из Сумеречного Молота',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В Подземье все еще есть сумеречные наездники на драконах. Их мало. Они слабы. Но все же они есть.$b$bЛети с Эозерой и найди их. Со временем мы уничтожим их всех до единого. Во имя Матери-Скалы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выследите сумеречного наездника на хрустальнокрылом каменном драконе.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Террату Непоколебимому к Трону Теразан, что в Подземье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27053,'Котел в пустоши Гаррона','Так, анализ проведен. Чума, которой болеют здешние животные, – вовсе не остаточное явление. Нет, это совершенно новый штамм... И кажется, я знаю, откуда ветер дует.$B$BНа пустоши Гаррона стоит большой котел с заразной субстанцией, принадлежащий Культу Проклятых.$B$BЭто к юго-востоку отсюда, на самой границе Восточных Чумных земель. Необходим образец содержимого этого котла, чтобы подтвердить мои догадки.$B$BКотел на замке, поэтому тебе придется убить охранника и забрать у него ключ. Потом откроешь крышку и возьмешь оттуда пробу.','Отправляйтесь на пустошь Гаррона в Западных Чумных землях, сразитесь там с хранителем котла, отберите у него ключ и отоприте котел.','Ключ хранителя котла Душегнева рассыпается, как только вы отпираете замок. Крышка с лязгом откидывается, и вы видите жуткую токсичную жидкость.$B$BВ котел вмонтирован кран, под который как раз подходит ваша бутылка, так что вы можете взять пробу для агента ШРУ Каартиша, дожидающегося на Участке Целителей Земли.','Котел надежно заперт. Чтобы его открыть, нужен ключ.','Осмотрите котел Плети на пустоши Гаррона в Западных Чумных землях.','Заберите ключ у хранителя котла и откройте котел.','Хранитель котла Душегнев') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Котел в пустоши Гаррона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Так, анализ проведен. Чума, которой болеют здешние животные, – вовсе не остаточное явление. Нет, это совершенно новый штамм... И кажется, я знаю, откуда ветер дует.$B$BНа пустоши Гаррона стоит большой котел с заразной субстанцией, принадлежащий Культу Проклятых.$B$BЭто к юго-востоку отсюда, на самой границе Восточных Чумных земель. Необходим образец содержимого этого котла, чтобы подтвердить мои догадки.$B$BКотел на замке, поэтому тебе придется убить охранника и забрать у него ключ. Потом откроешь крышку и возьмешь оттуда пробу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь на пустошь Гаррона в Западных Чумных землях, сразитесь там с хранителем котла, отберите у него ключ и отоприте котел.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ключ хранителя котла Душегнева рассыпается, как только вы отпираете замок. Крышка с лязгом откидывается, и вы видите жуткую токсичную жидкость.$B$BВ котел вмонтирован кран, под который как раз подходит ваша бутылка, так что вы можете взять пробу для агента ШРУ Каартиша, дожидающегося на Участке Целителей Земли.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Котел надежно заперт. Чтобы его открыть, нужен ключ.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Осмотрите котел Плети на пустоши Гаррона в Западных Чумных землях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Заберите ключ у хранителя котла и откройте котел.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Хранитель котла Душегнев',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27054,'Акт отчаяния','На востоке отсюда Культ Проклятых разбил небольшой лагерь – это так называемая Застава Коварнессы, которая необходима для полевой практики Некроситета. Мы слишком долго смотрели на все это сквозь пальцы.$B$BЕсли сектанты и правда инфицируют фауну, то Застава Коварнессы должна находиться там же, где и очаг чумы.$B$BНа заставе командует инструктор Коварнесса. Найди ее и убей, но сначала выясни, от кого она получала приказы.','Убейте инструктора Коварнессу и добудьте приказы Культа.','Вернитесь к агенту ШРУ Каартишу на Участок Целителей Земли в Западных Чумных землях.','Она утверждает, что проводит полевую практику среди сектантов, но как-то это подозрительно.','Инструктор Коварнесса') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Акт отчаяния',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На востоке отсюда Культ Проклятых разбил небольшой лагерь – это так называемая Застава Коварнессы, которая необходима для полевой практики Некроситета. Мы слишком долго смотрели на все это сквозь пальцы.$B$BЕсли сектанты и правда инфицируют фауну, то Застава Коварнессы должна находиться там же, где и очаг чумы.$B$BНа заставе командует инструктор Коварнесса. Найди ее и убей, но сначала выясни, от кого она получала приказы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте инструктора Коварнессу и добудьте приказы Культа.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к агенту ШРУ Каартишу на Участок Целителей Земли в Западных Чумных землях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Она утверждает, что проводит полевую практику среди сектантов, но как-то это подозрительно.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Инструктор Коварнесса',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27055,'Студенты Крастинова','Приказы Культа утверждают, что чума из котла с пустоши Гаррона на самом деле использовалась с ДВОЯКОЙ целью. В первую очередь для распространения заразы среди животных Чумных земель, о чем вы уже знаете.$B$BДругая же часть была отправлена в Грот Слез – пещеру к северу от Заставы Коварнессы – для каких-то мрачных экспериментов. Студенты Некроситета с помощью этой чумы оживляют мертвых!$B$BИх непременно надо остановить.','Убейте 2 учеников Крастинова, 2 грубо сварганенных громил, 2 грубо сварганенных потрошителей и 4 нечестени в Гроте Слез в Западных Чумных землях.','Вернитесь к агенту ШРУ Каартишу на Участок Целителей Земли в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Студенты Крастинова',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приказы Культа утверждают, что чума из котла с пустоши Гаррона на самом деле использовалась с ДВОЯКОЙ целью. В первую очередь для распространения заразы среди животных Чумных земель, о чем вы уже знаете.$B$BДругая же часть была отправлена в Грот Слез – пещеру к северу от Заставы Коварнессы – для каких-то мрачных экспериментов. Студенты Некроситета с помощью этой чумы оживляют мертвых!$B$BИх непременно надо остановить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 2 учеников Крастинова, 2 грубо сварганенных громил, 2 грубо сварганенных потрошителей и 4 нечестени в Гроте Слез в Западных Чумных землях.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к агенту ШРУ Каартишу на Участок Целителей Земли в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27056,'Доклад Бельмонта','<Бельмонт вручает вам запечатанный конверт.>$B$BПередай мой доклад Сильване Ветрокрылой. Это оценка ситуации в Серебряном бору на основе тех данных, что добыли вы с Йорик.$B$BЕсли мы не справимся с мятежными воргенами, они нас задавят. Действовать надо уже сейчас! Без промедления!','Передайте доклад Бельмонта Сильване Ветрокрылой в Ставке Отрекшихся в Серебряном бору.','Краули... Жалкий червяк. Давно надо было его раздавить.$B$BЗначит, он хочет подбить на мятеж диких воргенов из Серебряного бора? Ну, ничего. Скоро он на себе испытает всю мощь Отрекшихся!$B$BОднако сначала нам нужно привести в порядок флот. Нам понадобится их помощь. Иначе мы можем и проиграть эту войну.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Доклад Бельмонта',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Бельмонт вручает вам запечатанный конверт.>$B$BПередай мой доклад Сильване Ветрокрылой. Это оценка ситуации в Серебряном бору на основе тех данных, что добыли вы с Йорик.$B$BЕсли мы не справимся с мятежными воргенами, они нас задавят. Действовать надо уже сейчас! Без промедления!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Передайте доклад Бельмонта Сильване Ветрокрылой в Ставке Отрекшихся в Серебряном бору.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Краули... Жалкий червяк. Давно надо было его раздавить.$B$BЗначит, он хочет подбить на мятеж диких воргенов из Серебряного бора? Ну, ничего. Скоро он на себе испытает всю мощь Отрекшихся!$B$BОднако сначала нам нужно привести в порядок флот. Нам понадобится их помощь. Иначе мы можем и проиграть эту войну.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27057,'Возвращение на площадку','Осторожно закрывая кран на панели управления, вы наблюдаете, как из котла в пустую бутылку капает ядовитая жидкость.$B$BЯд добыт, пора возвращаться к агенту ШРУ Каартишу на Участок Целителей Земли.','Отнесите полную бутылку с пустоши Гаррона агенту ШРУ Каартишу на Участок Целителей Земли в Западных Чумных землях.','Очень хорошо. Подожди секунду...$B$B<Дреней сравнивает ваш образец со своим.>$B$BДа, похоже, это та же самая болезнь. Теперь, зная это, мы сможем воспользоваться твоей помощью в битве и положить всему этому конец.','В пустоши Гаррона находится очень мощный чумной котел. Получив образцы заразы, которую он вырабатывает, мы сумеем установить, действительно ли служители Культа Проклятых продолжают отравлять эти земли.','Отнесите полную бутылку с пустоши Гаррона агенту ШРУ Каартишу на Участок Целителей Земли в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение на площадку',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Осторожно закрывая кран на панели управления, вы наблюдаете, как из котла в пустую бутылку капает ядовитая жидкость.$B$BЯд добыт, пора возвращаться к агенту ШРУ Каартишу на Участок Целителей Земли.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите полную бутылку с пустоши Гаррона агенту ШРУ Каартишу на Участок Целителей Земли в Западных Чумных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Очень хорошо. Подожди секунду...$B$B<Дреней сравнивает ваш образец со своим.>$B$BДа, похоже, это та же самая болезнь. Теперь, зная это, мы сможем воспользоваться твоей помощью в битве и положить всему этому конец.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','В пустоши Гаррона находится очень мощный чумной котел. Получив образцы заразы, которую он вырабатывает, мы сумеем установить, действительно ли служители Культа Проклятых продолжают отравлять эти земли.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите полную бутылку с пустоши Гаррона агенту ШРУ Каартишу на Участок Целителей Земли в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27058,'Неверная последовательность','Наша цель – не допустить, чтобы сектанты Сумеречного Молота пользовались связующей спиралью. Это можно сделать только одним способом.$b$bВведи неверную последовательность активации и разрушь спираль.$b$bТак-так, посмотрим. Вот, есть такая, с ней спираль откроется на Огненные Просторы, в огненный мир элементалей. Это отлично сработает.','Воспользуйтесь контроллером связующей спирали и введите неверную активирующую последовательность, которая разрушит связующую спираль.','Вернитесь к исследовательнице Мови в Храм Земли, что в Подземье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Неверная последовательность',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наша цель – не допустить, чтобы сектанты Сумеречного Молота пользовались связующей спиралью. Это можно сделать только одним способом.$b$bВведи неверную последовательность активации и разрушь спираль.$b$bТак-так, посмотрим. Вот, есть такая, с ней спираль откроется на Огненные Просторы, в огненный мир элементалей. Это отлично сработает.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь контроллером связующей спирали и введите неверную активирующую последовательность, которая разрушит связующую спираль.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к исследовательнице Мови в Храм Земли, что в Подземье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27059,'Неверная последовательность','Наша цель – не допустить, чтобы сектанты Сумеречного Молота пользовались связующей спиралью. Это можно сделать только одним способом.$b$bВведи неверную последовательность активации и разрушь спираль.$b$bТак-так, посмотрим. Вот, есть такая, с ней спираль откроется на Огненные Просторы, в огненный мир элементалей. Это отлично сработает.','Воспользуйтесь контроллером связующей спирали и введите неверную активирующую последовательность, которая разрушит связующую спираль.','Вернитесь к исследователю Роу в Храм Земли, что в Подземье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Неверная последовательность',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наша цель – не допустить, чтобы сектанты Сумеречного Молота пользовались связующей спиралью. Это можно сделать только одним способом.$b$bВведи неверную последовательность активации и разрушь спираль.$b$bТак-так, посмотрим. Вот, есть такая, с ней спираль откроется на Огненные Просторы, в огненный мир элементалей. Это отлично сработает.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь контроллером связующей спирали и введите неверную активирующую последовательность, которая разрушит связующую спираль.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к исследователю Роу в Храм Земли, что в Подземье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27060,'Адская корова','<Фермер Уоллертон пытается успокоиться.>$B$BКоровы? Пропавшие коровы?$B$BОбычно я просто выпускаю коров пастись рядом с домом, к северу отсюда. Время от времени кто-то похищает одну из них. Похитителей легко выследить – за ними остается след из коровьих внутренностей. Кто это делает?$B$BЯ сам боюсь идти по следу... Похоже, в Штормграде творится что-то жуткое!','Вместе с Андуином Ринном идите по жуткому следу, который тянется от фермы Уоллертона. Защищайте принца. Если вы потеряете принца, то сможете найти его в крепости Штормграда.','Ух ты! Еще бы немного, и нам конец! До сих пор не могу поверить в то, что тебе удалось одолеть столько противников.$B$BПохоже, здесь проводился какой-то жуткий ритуал Сумеречного Молота. Очевидно, что его агенты действуют в Штормграде. О, что это?$B$B<Андуин подбирает с алтаря какой-то медальон.>$B$BНа медальоне изображены перекрещенные топор и молот. Похоже, это древняя вещь. Если мы продолжим расследование, то, возможно, нам удастся выяснить, что все это означает...','Поговорите с принцем Андуином Ринном. Если вы потеряете принца, то сможете найти его в крепости Штормграда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Адская корова',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Фермер Уоллертон пытается успокоиться.>$B$BКоровы? Пропавшие коровы?$B$BОбычно я просто выпускаю коров пастись рядом с домом, к северу отсюда. Время от времени кто-то похищает одну из них. Похитителей легко выследить – за ними остается след из коровьих внутренностей. Кто это делает?$B$BЯ сам боюсь идти по следу... Похоже, в Штормграде творится что-то жуткое!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вместе с Андуином Ринном идите по жуткому следу, который тянется от фермы Уоллертона. Защищайте принца. Если вы потеряете принца, то сможете найти его в крепости Штормграда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ух ты! Еще бы немного, и нам конец! До сих пор не могу поверить в то, что тебе удалось одолеть столько противников.$B$BПохоже, здесь проводился какой-то жуткий ритуал Сумеречного Молота. Очевидно, что его агенты действуют в Штормграде. О, что это?$B$B<Андуин подбирает с алтаря какой-то медальон.>$B$BНа медальоне изображены перекрещенные топор и молот. Похоже, это древняя вещь. Если мы продолжим расследование, то, возможно, нам удастся выяснить, что все это означает...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с принцем Андуином Ринном. Если вы потеряете принца, то сможете найти его в крепости Штормграда.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27061,'Дозорный холм Сумеречного Молота','Дракон, о котором они говорили, – это Абиссий, $n. Отобрать у него фрагмент будет не так-то просто.$b$bВстреться еще раз с Милрой. Ее можно найти возле дозорного холма Сумеречного Молота.$b$bОна скажет тебе, что делать дальше.','Поговорите с буревестницей Милрой у дозорного холма Сумеречного Молота в Подземье.','Так ты собираешься выступить против Абиссия, чтобы получить фрагмент? Это дело внезапно стало гораздо более трудным.','Милра на дозорном холме Сумеречного Молота. Встретьтесь с ней.','Буревестница Милра') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дозорный холм Сумеречного Молота',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Дракон, о котором они говорили, – это Абиссий, $n. Отобрать у него фрагмент будет не так-то просто.$b$bВстреться еще раз с Милрой. Ее можно найти возле дозорного холма Сумеречного Молота.$b$bОна скажет тебе, что делать дальше.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с буревестницей Милрой у дозорного холма Сумеречного Молота в Подземье.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так ты собираешься выступить против Абиссия, чтобы получить фрагмент? Это дело внезапно стало гораздо более трудным.',`offerrewardtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Милра на дозорном холме Сумеречного Молота. Встретьтесь с ней.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Буревестница Милра',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27062,'Смутная угроза','Похоже, свинобразы из курганов Иглошкурых присоединились к Плети. Это очень скверные новости, |3-6($c). Нам хватает хлопот со Зловещим Тотемом, и нападение Плети мы просто не выдержим. Отправляйся в курганы Иглошкурых, что к востоку отсюда, и постарайся найти там того, кто сумеет предотвратить атаку Плети.','Найдите помощь в курганах Иглошкурых.','Вижу, ты умелый воин. Надеюсь, ты поможешь мне остановить зло в этих краях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Смутная угроза',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Похоже, свинобразы из курганов Иглошкурых присоединились к Плети. Это очень скверные новости, |3-6($c). Нам хватает хлопот со Зловещим Тотемом, и нападение Плети мы просто не выдержим. Отправляйся в курганы Иглошкурых, что к востоку отсюда, и постарайся найти там того, кто сумеет предотвратить атаку Плети.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите помощь в курганах Иглошкурых.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вижу, ты умелый воин. Надеюсь, ты поможешь мне остановить зло в этих краях.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27063,'Смутная угроза','Плеть бросает вызов самой природе. Они уже осквернили свинобразов в курганах Иглошкурых, теперь хотят добраться до Тысячи Игл – а в итоге и до Фераласа. Отправляйся туда и сделай все, чтобы сдержать их наступление. Ветер шепчет, что в этих краях обитает некто очень могущественный. Разыщи его – вдруг он поможет тебе в борьбе против Плети.','Получите помощь в курганах Иглошкурых.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Смутная угроза',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Плеть бросает вызов самой природе. Они уже осквернили свинобразов в курганах Иглошкурых, теперь хотят добраться до Тысячи Игл – а в итоге и до Фераласа. Отправляйся туда и сделай все, чтобы сдержать их наступление. Ветер шепчет, что в этих краях обитает некто очень могущественный. Разыщи его – вдруг он поможет тебе в борьбе против Плети.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Получите помощь в курганах Иглошкурых.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (27063,'Ты производишь впечатление умелого воина. Возможно ты способен помочь мне положить конец этому ужасному злу.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты производишь впечатление умелого воина. Возможно ты способен помочь мне положить конец этому ужасному злу.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27064,'Он что-то скрывает','$n, мне кажется, что Самуэльсон намеренно пытается затормозить ход расследования. Портовые рабочие ничего не знают, и, что более важно, из Штормградского порта пропала партия взрывчатки!$B$BЗнаешь, что? Я думаю, Самуэльсон что-то скрывает. Возможно, он что-то знает про Сумеречный Молот и не хочет ни с кем делиться славой.$B$BНужно зайти в штаб-квартиру ШРУ и просмотреть его досье. Отведи меня туда – у меня есть допуск ко всем архивам. Мы выясним, что ему известно.','Вместе с Андуином Ринном отправляйтесь на третий этаж штаб-квартиры ШРУ, которая находится в Штормграде в Старом городе. Если вы потеряете принца, то сможете найти его в крепости Штормграда.','Поговорите с принцем Андуином Ринном. Если вы потеряете принца, то сможете найти его в крепости Штормграда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Он что-то скрывает',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, мне кажется, что Самуэльсон намеренно пытается затормозить ход расследования. Портовые рабочие ничего не знают, и, что более важно, из Штормградского порта пропала партия взрывчатки!$B$BЗнаешь, что? Я думаю, Самуэльсон что-то скрывает. Возможно, он что-то знает про Сумеречный Молот и не хочет ни с кем делиться славой.$B$BНужно зайти в штаб-квартиру ШРУ и просмотреть его досье. Отведи меня туда – у меня есть допуск ко всем архивам. Мы выясним, что ему известно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вместе с Андуином Ринном отправляйтесь на третий этаж штаб-квартиры ШРУ, которая находится в Штормграде в Старом городе. Если вы потеряете принца, то сможете найти его в крепости Штормграда.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с принцем Андуином Ринном. Если вы потеряете принца, то сможете найти его в крепости Штормграда.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (27065,'Флот вождя','Это поражение может стать одной из самых позорных страниц в истории военно-морского флота. Как это произошло? Из-за пьяни – вот как.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Флот вождя',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это поражение может стать одной из самых позорных страниц в истории военно-морского флота. Как это произошло? Из-за пьяни – вот как.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27068,'Вождь Укорз Песчаный Череп','Смотри сюда. Так все и идет – одно предательство влечет за собой другое. Я пыряю тебя из-за твоего меча, а потом вождь Укорз из-за этого пыряет меня в спину, да еще похлеще.$B$BТакова жизнь! Или такова была жизнь...$B$BЛадно, я знаю теперь, что ты не любишь Мазогу. Но ты все равно туда пойдешь. Так прикончи его ради меня. Пролей еще крови на песок и дай вождю Укорзу Песчаному Черепу то, что заслуживают все гады из племени Песчаной Бури... кровавую смерть.$B$BМожет, я за это даже и не наложу проклятия на свои пожитки прежде, чем они перейдут к тебе.','Убейте вождя Укорза Песчаного Черепа.','Он помер? Меч при нем был?$B$BНет...молчи. Это уже все равно. Мазоге все равно.$B$BПомираю я. И воздастся мне за мои дела. Забирай все мое добро... Там, куда я ухожу, оно мне незачем...','Вернитесь к духу Мазоги в Зул\'Фаррак.','Убей его ради меня.','Вождь Укорз Песчаный Череп') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вождь Укорз Песчаный Череп',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Смотри сюда. Так все и идет – одно предательство влечет за собой другое. Я пыряю тебя из-за твоего меча, а потом вождь Укорз из-за этого пыряет меня в спину, да еще похлеще.$B$BТакова жизнь! Или такова была жизнь...$B$BЛадно, я знаю теперь, что ты не любишь Мазогу. Но ты все равно туда пойдешь. Так прикончи его ради меня. Пролей еще крови на песок и дай вождю Укорзу Песчаному Черепу то, что заслуживают все гады из племени Песчаной Бури... кровавую смерть.$B$BМожет, я за это даже и не наложу проклятия на свои пожитки прежде, чем они перейдут к тебе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте вождя Укорза Песчаного Черепа.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Он помер? Меч при нем был?$B$BНет...молчи. Это уже все равно. Мазоге все равно.$B$BПомираю я. И воздастся мне за мои дела. Забирай все мое добро... Там, куда я ухожу, оно мне незачем...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к духу Мазоги в Зул\'Фаррак.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Убей его ради меня.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Вождь Укорз Песчаный Череп',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (27071,'Гнев племени Песчаной Бури','Это племя Песчаной Бури – упорные ребята. Выдерживают и песчаные бури, и то, что сидит в недрах песков. Глупо думать, что в пустыне никого, кроме троллей, нет. Мы приручаем скарабеев, разводим сул\'литузов, поднимаем наших мертвых, чтобы те бесконечно сражались за нас, как зомби.$B$BРуузлу, правая рука вождя Укорза Песчаного Черепа, хочет с их помощью захватить Танарис и сделать его частью империи племени Песчаной Бури. Ежели хочешь жить, так лучше тебе этих троллей перебить.','Вернитесь к духу Мазоги.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гнев племени Песчаной Бури',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это племя Песчаной Бури – упорные ребята. Выдерживают и песчаные бури, и то, что сидит в недрах песков. Глупо думать, что в пустыне никого, кроме троллей, нет. Мы приручаем скарабеев, разводим сул\'литузов, поднимаем наших мертвых, чтобы те бесконечно сражались за нас, как зомби.$B$BРуузлу, правая рука вождя Укорза Песчаного Черепа, хочет с их помощью захватить Танарис и сделать его частью империи племени Песчаной Бури. Ежели хочешь жить, так лучше тебе этих троллей перебить.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к духу Мазоги.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27072,'Старые казармы','Я видел этот символ на знаках отличия еще до того, как Смертокрыл напал на город. Такие знаки носили солдаты, жившие в старых казармах, к западу от города, над гаванью. Иди к руинам казарм и постарайся найти там следы деятельности приверженцев культа.$B$BСейчас самое время. Один из агентов по имени Джек Боден пытался по моему поручению внедриться в культ Сумеречного Молота. Прошлой ночью он исчез. Если вы с Андуином правы, то сектанты обосновались в Старых казармах. У нас нет времени! Нужно немедленно напасть на казармы, уничтожить сектантов и спасти Джека Бодена.','Отправляйтесь в Старые казармы и убейте 6 безумных сектантов, а затем найдите Джека Бодена.','Поговорите с Джеком Боденом в Старых казармах Штормграда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Старые казармы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я видел этот символ на знаках отличия еще до того, как Смертокрыл напал на город. Такие знаки носили солдаты, жившие в старых казармах, к западу от города, над гаванью. Иди к руинам казарм и постарайся найти там следы деятельности приверженцев культа.$B$BСейчас самое время. Один из агентов по имени Джек Боден пытался по моему поручению внедриться в культ Сумеречного Молота. Прошлой ночью он исчез. Если вы с Андуином правы, то сектанты обосновались в Старых казармах. У нас нет времени! Нужно немедленно напасть на казармы, уничтожить сектантов и спасти Джека Бодена.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Старые казармы и убейте 6 безумных сектантов, а затем найдите Джека Бодена.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Джеком Боденом в Старых казармах Штормграда.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27073,'Задай им жару!','Убейте 10 падальщиков из стаи Кровавых Клыков.','Похоже, ты неплохо отделал воргенов, а заодно и смыл с нас пятно позора. Возможно, морские волки теперь перестанут пить.$B$BХотя кого я обманываю?$B$BХа!','Вернитесь к полководцу Тороку в Арьергард Отрекшихся в Серебряном бору.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Задай им жару!',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 падальщиков из стаи Кровавых Клыков.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Похоже, ты неплохо отделал воргенов, а заодно и смыл с нас пятно позора. Возможно, морские волки теперь перестанут пить.$B$BХотя кого я обманываю?$B$BХа!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к полководцу Тороку в Арьергард Отрекшихся в Серебряном бору.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27074,'Битва с Молотом','Ты $gсделал:сделала; то, что мне казалось невыполнимым! Хватит мне уже бесцельно сидеть тут. Настало время приняться за дело.$b$bМне нужно разыскать моего отца. Но ты! Не трать больше свое время на меня. Ты $gдолжен:должна; продолжать борьбу с этими сектантами.$b$bПоговори с Ашланом Камнехмылом, его можно найти к востоку отсюда. Он пытается остановить Сумеречный Молот, но он один, ему не от кого ждать помощи. Ты – его единственная надежда!$b$bНе отступайся, $n. И я не буду.','Поговорите с Ашланом Камнехмылом у Оплота Мо\'гроша, что в Лок Модане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Битва с Молотом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gсделал:сделала; то, что мне казалось невыполнимым! Хватит мне уже бесцельно сидеть тут. Настало время приняться за дело.$b$bМне нужно разыскать моего отца. Но ты! Не трать больше свое время на меня. Ты $gдолжен:должна; продолжать борьбу с этими сектантами.$b$bПоговори с Ашланом Камнехмылом, его можно найти к востоку отсюда. Он пытается остановить Сумеречный Молот, но он один, ему не от кого ждать помощи. Ты – его единственная надежда!$b$bНе отступайся, $n. И я не буду.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Ашланом Камнехмылом у Оплота Мо\'гроша, что в Лок Модане.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27075,'Служители Чо\'Галла','Изначально Сумеречный Молот был кланом дикой Орды. Мало-помалу их предводитель, Чо\'Галл превратил банду огров в секту Смерти, принимая туда всех, кто был достаточно безумен, чтобы желать конца своих дней. Как ты видишь, в их рядах и сейчас много огров – психически ненормальных, фанатичных и таких же сильных, как и раньше.$b$bЭти жестокие чудовища имели наглость прийти сюда и осквернять наши земли. Чем больше ты убьешь, тем лучше будет для Лок Модана, $n.','Убейте 7 огров из клана Мо\'грош в Оплоте Мо\'гроша.','Вернитесь к Ашлану Камнехмылу, его можно найти у лагеря Мо\'грош в Лок Модане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Служители Чо\'Галла',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Изначально Сумеречный Молот был кланом дикой Орды. Мало-помалу их предводитель, Чо\'Галл превратил банду огров в секту Смерти, принимая туда всех, кто был достаточно безумен, чтобы желать конца своих дней. Как ты видишь, в их рядах и сейчас много огров – психически ненормальных, фанатичных и таких же сильных, как и раньше.$b$bЭти жестокие чудовища имели наглость прийти сюда и осквернять наши земли. Чем больше ты убьешь, тем лучше будет для Лок Модана, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 7 огров из клана Мо\'грош в Оплоте Мо\'гроша.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ашлану Камнехмылу, его можно найти у лагеря Мо\'грош в Лок Модане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27076,'Взломай и входи','Блеск! Я знал, что могу на тебя рассчитывать! Вот тебе за труды.','Вернитесь к Тран\'реку.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Взломай и входи',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Блеск! Я знал, что могу на тебя рассчитывать! Вот тебе за труды.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тран\'реку.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27077,'Остановить хаос','Сектанты Сумеречного Молота пользуются своей силой для того, чтобы вытягивать из недр земли металл элементий. Они делают из него скрученные зубцы, вбивая их глубоко в оскверненную землю в качестве каркаса для своих зданиий.$b$bЗдешние огры еще не успели закончить с этой работой, и мы должны их остановить.$b$bВырви зубцы из земли, пока они еще гибкие, и принеси их мне! Мы не уступим этим негодяям ни пяди нашей земли.','Выдерните 10 формирующихся элементиевых зубцов из земли Оплота Мо\'гроша.','Жаль, что эти наполовину сформированные штуки слишком хрупкие и деформированные, чтобы использовать их для нашего оружия. Но благодаря тому, что ты сделала, мы сможем выдворить сектантов из наших землей, пока они здесь не осели. Так что я не жалуюсь.','Ты выдернула зубцы из земли?','Вернитесь к Ашлану Камнехмылу, его можно найти у лагеря Мо\'грош в Лок Модане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Остановить хаос',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сектанты Сумеречного Молота пользуются своей силой для того, чтобы вытягивать из недр земли металл элементий. Они делают из него скрученные зубцы, вбивая их глубоко в оскверненную землю в качестве каркаса для своих зданиий.$b$bЗдешние огры еще не успели закончить с этой работой, и мы должны их остановить.$b$bВырви зубцы из земли, пока они еще гибкие, и принеси их мне! Мы не уступим этим негодяям ни пяди нашей земли.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выдерните 10 формирующихся элементиевых зубцов из земли Оплота Мо\'гроша.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Жаль, что эти наполовину сформированные штуки слишком хрупкие и деформированные, чтобы использовать их для нашего оружия. Но благодаря тому, что ты сделала, мы сможем выдворить сектантов из наших землей, пока они здесь не осели. Так что я не жалуюсь.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты выдернула зубцы из земли?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ашлану Камнехмылу, его можно найти у лагеря Мо\'грош в Лок Модане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27078,'Гор\'креш','Победите Гор\'креша.','Ты это сделала! Может быть, мы и не уничтожили секту Смерти, но мы ясно дали им понять, что не годимся на роль легкой добычи.$B$BПрими это в знак моей благодарности и не заливайся краской, когда кто-либо в Телсамаре будет называть тебя героиней!','Вернитесь к Ашлану Камнехмылу, его можно найти у лагеря Мо\'грош в Лок Модане.','Сумеречному Молоту нечего делать у нашего озера.','Гор\'креш') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гор\'креш',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Гор\'креша.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты это сделала! Может быть, мы и не уничтожили секту Смерти, но мы ясно дали им понять, что не годимся на роль легкой добычи.$B$BПрими это в знак моей благодарности и не заливайся краской, когда кто-либо в Телсамаре будет называть тебя героиней!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ашлану Камнехмылу, его можно найти у лагеря Мо\'грош в Лок Модане.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Сумеречному Молоту нечего делать у нашего озера.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Гор\'креш',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (27079,'Поиски Сумеречных врат') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поиски Сумеречных врат',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (27080,'Поиски Сумеречных врат') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поиски Сумеречных врат',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27081,'[DEPRECATED]Trusting the Traitor','These two are useless. Can I at least count on you to get some work done around here, young adventurer? We\'ve come into contact with Mazoga, a traitor to the Sandfury. He says he can help us find the legendary blade Sul\'thraze so we can use it to kick out the Sandfury forever!$B$BWe\'ll probably sell it afterward to the highest bidder, honestly. This place doesn\'t pay for itself. Go do what he wants...just keep an eye on him. A traitor\'s a traitor all the same. He\'s at our camp just east of Zul\'Farrak.','Speak with Mazoga.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]Trusting the Traitor',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','These two are useless. Can I at least count on you to get some work done around here, young adventurer? We\'ve come into contact with Mazoga, a traitor to the Sandfury. He says he can help us find the legendary blade Sul\'thraze so we can use it to kick out the Sandfury forever!$B$BWe\'ll probably sell it afterward to the highest bidder, honestly. This place doesn\'t pay for itself. Go do what he wants...just keep an eye on him. A traitor\'s a traitor all the same. He\'s at our camp just east of Zul\'Farrak.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Speak with Mazoga.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27082,'Грязная игра','Ты $gвидал:видала; рыскающих по лесу здоровенных эттинов? Проклятые твари притащились сюда из Гилнеаса. А теперь бродят повсюду, ищут себе добычу посочнее. Нам удалось укротить несколько особей и запрячь их в вагоны, но остальные... В общем, их нужно уничтожить!$B$BК несчастью, у нас нет свободных солдат, чтобы выполнить эту задачу. Вот тут-то нам и пригодишься ты, |3-6($c)!$B$BУ меня есть план, только сначала необходимо собрать расходные материалы. Отправляйся в лес и добудь мне органы зараженных зверей.','Добудьте 8 зараженных органов гигантских бешеных медведей и бешеных воргов.','Отлично! А теперь займемся готовкой "еды".','Вернитесь к аптекарю Червомразу в Арьергард Отрекшихся в Серебряном бору.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Грязная игра',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gвидал:видала; рыскающих по лесу здоровенных эттинов? Проклятые твари притащились сюда из Гилнеаса. А теперь бродят повсюду, ищут себе добычу посочнее. Нам удалось укротить несколько особей и запрячь их в вагоны, но остальные... В общем, их нужно уничтожить!$B$BК несчастью, у нас нет свободных солдат, чтобы выполнить эту задачу. Вот тут-то нам и пригодишься ты, |3-6($c)!$B$BУ меня есть план, только сначала необходимо собрать расходные материалы. Отправляйся в лес и добудь мне органы зараженных зверей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 8 зараженных органов гигантских бешеных медведей и бешеных воргов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! А теперь займемся готовкой "еды".',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к аптекарю Червомразу в Арьергард Отрекшихся в Серебряном бору.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27083,'Борьба возобновляется!','Пришли вести из Андорала, $n. Борьба возобновилась.$B$BКаким-то образом Отрекшимся стало известно, какую роль ты $gсыграл:сыграла; в первой битве Андорала. Кольтира потребовал, чтобы ты к нему немедленно $gявился:явилась;.','Поговорите с Кольтирой Ткачом Смерти в Андорале в Западных Чумных землях.','Тассариан со своими людьми начал действовать. Мне казалось, что мы с ним договорились... Впрочем, ладно.','Поговорите с Кольтирой Ткачом Смерти в Андорале в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Борьба возобновляется!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пришли вести из Андорала, $n. Борьба возобновилась.$B$BКаким-то образом Отрекшимся стало известно, какую роль ты $gсыграл:сыграла; в первой битве Андорала. Кольтира потребовал, чтобы ты к нему немедленно $gявился:явилась;.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Кольтирой Ткачом Смерти в Андорале в Западных Чумных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тассариан со своими людьми начал действовать. Мне казалось, что мы с ним договорились... Впрочем, ладно.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Кольтирой Ткачом Смерти в Андорале в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27084,'Крестьянское ополчение','Они напали с тыла. Я потерял бдительность, и группа плохо вооруженных крестьян и ополченцев ворвалась со стороны Удела Страданий.$B$BПусть они слабые, но если вовремя не давать отпора, мы проиграем, так их слишком много.$B$BДля рукопашного боя сгодятся поганища Линдси. А ты отправляйся в тыл с этим ошейником и натрави на крестьян мою вороную горгулью.','С помощью ошейника вороной горгульи затравите 6 местных ополченцев в Андорале.','Пусть они понесли несущественные потери, но главное – нам удалось подорвать их боевой дух.','Вернитесь к Кольтире Ткачу Смерти в Андорал в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Крестьянское ополчение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Они напали с тыла. Я потерял бдительность, и группа плохо вооруженных крестьян и ополченцев ворвалась со стороны Удела Страданий.$B$BПусть они слабые, но если вовремя не давать отпора, мы проиграем, так их слишком много.$B$BДля рукопашного боя сгодятся поганища Линдси. А ты отправляйся в тыл с этим ошейником и натрави на крестьян мою вороную горгулью.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','С помощью ошейника вороной горгульи затравите 6 местных ополченцев в Андорале.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Пусть они понесли несущественные потери, но главное – нам удалось подорвать их боевой дух.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кольтире Ткачу Смерти в Андорал в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27085,'Поддержка войск','Хоть фермеры и угрожают нам нападением, нельзя забывать и об основных силах Альянса.$B$BОтправляйся на запад, в Андорал, и убей всех людей, с которыми сражаются наши стражи смерти. Сейчас нам позарез нужна любая помощь.','Убейте 15 защитников Андорала.','Вернитесь к Джерлу Дональду в Андорал в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поддержка войск',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хоть фермеры и угрожают нам нападением, нельзя забывать и об основных силах Альянса.$B$BОтправляйся на запад, в Андорал, и убей всех людей, с которыми сражаются наши стражи смерти. Сейчас нам позарез нужна любая помощь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 15 защитников Андорала.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джерлу Дональду в Андорал в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27086,'Прах к праху','На западе, в самой глубине Андорала, занятого Альянсом, скрываются их командиры. В боях они не участвуют, лишь отдают приказы, сидя верхом.$B$BВыследи и убей этих командиров, $n. Не оставим людям ни единого шанса.','Убейте 3 военачальников Андорала.','Молодец! Теперь, когда их больше нет, меня ничто не держит.$B$BСкоро я выйду на бой с Тассарианом и буду драться за честь и Андорал.','Вернитесь к Кольтире Ткачу Смерти в Андорал в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прах к праху',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На западе, в самой глубине Андорала, занятого Альянсом, скрываются их командиры. В боях они не участвуют, лишь отдают приказы, сидя верхом.$B$BВыследи и убей этих командиров, $n. Не оставим людям ни единого шанса.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 3 военачальников Андорала.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Молодец! Теперь, когда их больше нет, меня ничто не держит.$B$BСкоро я выйду на бой с Тассарианом и буду драться за честь и Андорал.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кольтире Ткачу Смерти в Андорал в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27087,'Разоблачение Линдси Черное Солнце','Тут сообщили, что эта никчемная дамочка Линдси Черное Солнце будет помогать мне в битве. Пока она отличилась только тем, что отсиживалась в подвале под главным залом. Правда, тем лучше, я думаю. Она хоть как-то меня развлекала.$B$BВ любом случае, я не могу и не буду ослушиваться приказа. Найди ее и приведи ко мне.','Поговорите с Линдси Черное Солнце в Андорале в Западных Чумных землях.','Поговорите с Линдси Черное Солнце в Андорале в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разоблачение Линдси Черное Солнце',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тут сообщили, что эта никчемная дамочка Линдси Черное Солнце будет помогать мне в битве. Пока она отличилась только тем, что отсиживалась в подвале под главным залом. Правда, тем лучше, я думаю. Она хоть как-то меня развлекала.$B$BВ любом случае, я не могу и не буду ослушиваться приказа. Найди ее и приведи ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Линдси Черное Солнце в Андорале в Западных Чумных землях.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Линдси Черное Солнце в Андорале в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27088,'В пищу не употреблять!','Вот тебе клетка, |3-6($c). В ней – мои фирменные мутировавшие цыплята-бройлеры, разве что с парой изменений. И в каждом цыпленке – шашка динамита с добавлением вытяжки из прогнивших внутренностей.$B$BВозьми клетку, отправляйся в наш лес и найди блуждающего по нему лесного эттина. А как найдешь – выпускай цыплят, отходи подальше и наслаждайся фейерверком. От взрыва эттин либо погибнет сразу, либо ослабнет настолько, что тебе не составит труда его добить.','Уничтожьте лесного эттина с помощью мутировавших цыплят-бройлеров.','<Аптекарь Червомраз заходится безумным смехом.>$B$BВсе, как ожидалось. Йотун – ничто против науки!','Вернитесь к аптекарю Червомразу в Арьергард Отрекшихся в Серебряном бору.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В пищу не употреблять!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот тебе клетка, |3-6($c). В ней – мои фирменные мутировавшие цыплята-бройлеры, разве что с парой изменений. И в каждом цыпленке – шашка динамита с добавлением вытяжки из прогнивших внутренностей.$B$BВозьми клетку, отправляйся в наш лес и найди блуждающего по нему лесного эттина. А как найдешь – выпускай цыплят, отходи подальше и наслаждайся фейерверком. От взрыва эттин либо погибнет сразу, либо ослабнет настолько, что тебе не составит труда его добить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте лесного эттина с помощью мутировавших цыплят-бройлеров.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Аптекарь Червомраз заходится безумным смехом.>$B$BВсе, как ожидалось. Йотун – ничто против науки!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к аптекарю Червомразу в Арьергард Отрекшихся в Серебряном бору.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27089,'Козырь в рукаве','Даже не представляешь, до чего трудно было себя не выдать, наблюдая за тем, как Кольтира упустил наш шанс на успех в этой войне. До сих пор нам угрожают эти ужасные фермеры, а все потому, что он отказался поднять руку на друга.$B$BВозьми с собой мою валь\'киру. Уничтожь фермеров, обрати их в Отрекшихся и зачаруй. Потом отведи их в управляемый Альянсом западный Андорал и разберись с рыцарем смерти Тассарианом.$B$BМы все равно выиграем эту войну.','Это тело Лурида, одного из рыцарей Тассариана. Самого Тассариана нигде нет – похоже, Альянс вывел свои войска.$B$BОтрекшиеся выиграли битву за Андорал.','Осмотрите тело Лурида в Андорале в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Козырь в рукаве',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Даже не представляешь, до чего трудно было себя не выдать, наблюдая за тем, как Кольтира упустил наш шанс на успех в этой войне. До сих пор нам угрожают эти ужасные фермеры, а все потому, что он отказался поднять руку на друга.$B$BВозьми с собой мою валь\'киру. Уничтожь фермеров, обрати их в Отрекшихся и зачаруй. Потом отведи их в управляемый Альянсом западный Андорал и разберись с рыцарем смерти Тассарианом.$B$BМы все равно выиграем эту войну.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это тело Лурида, одного из рыцарей Тассариана. Самого Тассариана нигде нет – похоже, Альянс вывел свои войска.$B$BОтрекшиеся выиграли битву за Андорал.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Осмотрите тело Лурида в Андорале в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (27090,'Андорал – раз и навсегда','Нужно рассказать Сильване об отбытии Тассариана из Андорала. Придется вернуться в захваченную Отрекшимися часть города.','Видишь? А всего-то потребовалась небольшая помощь валь\'кир. Эти существа куда полезнее, чем я думала.$B$BА теперь к другим делам.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Андорал – раз и навсегда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нужно рассказать Сильване об отбытии Тассариана из Андорала. Придется вернуться в захваченную Отрекшимися часть города.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Видишь? А всего-то потребовалась небольшая помощь валь\'кир. Эти существа куда полезнее, чем я думала.$B$BА теперь к другим делам.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27092,'Катаклизм в катакомбах','Не беспокойся обо мне, |3-6($c). Я раскрыл заговор последователей культа Сумеречного Молота. Они крадут взрывчатку, поступающую в порт Штормграда, и складируют ее впрок. Им как-то удалось пробраться в подземелья, расположенные под Собором Света. В их разговорах упоминался некий "темный епископ".$B$BНа то, чтобы предупредить стражу, нет времени, $n! У тебя остались считанные минуты на то, чтобы спуститься в подземелья и обезвредить взрывное устройство. Иди же! Быстрее! ИЛИ ПОГИБНУТ ТЫСЯЧИ ЛЮДЕЙ!','Войдите в Собор Света и спуститесь в катакомбы под ним. Убейте темного епископа и обезвредьте гору взрывчатки, которая находится рядом.','<3... 2... 1...>$B$B<Вы смачиваете пальцы и тушите фитиль. Собор спасен!>$B$B<Под бочками с порохом лежит груда бумаг. Похоже, сектанты пытались уничтожить улики.>','Доберитесь до взрывчатки, которая лежит в катакомбах под Собором Света!','Я заметил здесь одного из лидеров культа. Осторожнее, он передвигается таинственным образом.','Темный епископ') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Катаклизм в катакомбах',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не беспокойся обо мне, |3-6($c). Я раскрыл заговор последователей культа Сумеречного Молота. Они крадут взрывчатку, поступающую в порт Штормграда, и складируют ее впрок. Им как-то удалось пробраться в подземелья, расположенные под Собором Света. В их разговорах упоминался некий "темный епископ".$B$BНа то, чтобы предупредить стражу, нет времени, $n! У тебя остались считанные минуты на то, чтобы спуститься в подземелья и обезвредить взрывное устройство. Иди же! Быстрее! ИЛИ ПОГИБНУТ ТЫСЯЧИ ЛЮДЕЙ!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Войдите в Собор Света и спуститесь в катакомбы под ним. Убейте темного епископа и обезвредьте гору взрывчатки, которая находится рядом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<3... 2... 1...>$B$B<Вы смачиваете пальцы и тушите фитиль. Собор спасен!>$B$B<Под бочками с порохом лежит груда бумаг. Похоже, сектанты пытались уничтожить улики.>',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доберитесь до взрывчатки, которая лежит в катакомбах под Собором Света!',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Я заметил здесь одного из лидеров культа. Осторожнее, он передвигается таинственным образом.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Темный епископ',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27093,'Затерянные во тьме','Некоторые говорят: "Надо радоваться тому, что мы хотя бы живы". Идиоты! Ведь смерть избавила бы нас от гнева Вождя. Увы, что сделано, то сделано, и теперь нам надо вернуть утраченную честь.$B$BУже третий корабль нашего флота затонул у берегов Оплетающей Тьмы, что к северо-западу отсюда. А те, кому удалось выбраться из воды, подверглись нападению гигантских пауков на суше.$B$BМы должны их спасти! Вперед, $n! В Оплетающую Тьму!','Спасите 6 орков-морских волков в Оплетающей Тьме.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Затерянные во тьме',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Некоторые говорят: "Надо радоваться тому, что мы хотя бы живы". Идиоты! Ведь смерть избавила бы нас от гнева Вождя. Увы, что сделано, то сделано, и теперь нам надо вернуть утраченную честь.$B$BУже третий корабль нашего флота затонул у берегов Оплетающей Тьмы, что к северо-западу отсюда. А те, кому удалось выбраться из воды, подверглись нападению гигантских пауков на суше.$B$BМы должны их спасти! Вперед, $n! В Оплетающую Тьму!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Спасите 6 орков-морских волков в Оплетающей Тьме.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27094,'Во тьму','Матриарх мшистых пауков находится рядом с нами! Ты можешь убить ее и тем самым положить конец паучьей угрозе!$B$BНайди матриарха в пещере Оплетающей Тьмы и уничтожь!','Убейте матриарха мшистых пауков.','Поговорите с полководцем Тороком в Арьергарде Отрекшихся в Серебряном бору.','Воплощение смерти!','Матриарх мшистых пауков') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Во тьму',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Матриарх мшистых пауков находится рядом с нами! Ты можешь убить ее и тем самым положить конец паучьей угрозе!$B$BНайди матриарха в пещере Оплетающей Тьмы и уничтожь!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте матриарха мшистых пауков.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с полководцем Тороком в Арьергарде Отрекшихся в Серебряном бору.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Воплощение смерти!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Матриарх мшистых пауков',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27095,'Паучья угроза','Пришло время мстить, $n! Уже третий наш корабль затонул на северо-западе у Оплетающей Тьмы. Спасшихся на шлюпке либо похитили, либо убили местные мшистые пауки. И за это пауки должны умереть! ВСЕ ДО ОДНОГО!$B$BОтправляйся в Оплетающую Тьму и перебей всех этих насекомых!$B$BЗаодно поищи там их матку: вполне вероятно, если прикончить ее, то можно раз и навсегда избавиться от этой угрозы!','Убейте 12 мшистых пауков.','Вернитесь к полководцу Тороку в Арьергард Отрекшихся в Серебряном бору.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Паучья угроза',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пришло время мстить, $n! Уже третий наш корабль затонул на северо-западе у Оплетающей Тьмы. Спасшихся на шлюпке либо похитили, либо убили местные мшистые пауки. И за это пауки должны умереть! ВСЕ ДО ОДНОГО!$B$BОтправляйся в Оплетающую Тьму и перебей всех этих насекомых!$B$BЗаодно поищи там их матку: вполне вероятно, если прикончить ее, то можно раз и навсегда избавиться от этой угрозы!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 мшистых пауков.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к полководцу Тороку в Арьергард Отрекшихся в Серебряном бору.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (27096,'У орков все прекрасно','Передайте рекомендательное письмо адмирала леди Сильване Ветрокрылой в Ставке Отрекшихся в Серебряном бору.','Так что там у орков?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','У орков все прекрасно',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Передайте рекомендательное письмо адмирала леди Сильване Ветрокрылой в Ставке Отрекшихся в Серебряном бору.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Так что там у орков?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (27097,'Восстань, Отрекшийся','Остров Фенриса расположен в самом сердце озера Лордамер – жестокое напоминание о давно ушедших временах.$B$BПаразитов-гноллов на нем больше не осталось, но теперь возникла новая угроза. Люди – беженцы из Хилсбрада – приплыли на остров в надежде спастись там от нас. Фатальная ошибка.$B$BОтправляйтесь с Агатой на остров Фенриса и уничтожьте всех людишек. Она обратит мертвых в Отрекшихся и пополнит ряды нашей армии.$B$BНе подведи меня, $n.','Убейте людей на острове и поднимите 15 Отрекшихся.','Поговорите с леди Сильваной Ветрокрылой в Ставке Отрекшихся в Серебряном бору.','Эти люди больше преуспеют в загробной жизни, став Отрекшимися.','Леди Сильвана Ветрокрылая') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Восстань, Отрекшийся',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Остров Фенриса расположен в самом сердце озера Лордамер – жестокое напоминание о давно ушедших временах.$B$BПаразитов-гноллов на нем больше не осталось, но теперь возникла новая угроза. Люди – беженцы из Хилсбрада – приплыли на остров в надежде спастись там от нас. Фатальная ошибка.$B$BОтправляйтесь с Агатой на остров Фенриса и уничтожьте всех людишек. Она обратит мертвых в Отрекшихся и пополнит ряды нашей армии.$B$BНе подведи меня, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте людей на острове и поднимите 15 Отрекшихся.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с леди Сильваной Ветрокрылой в Ставке Отрекшихся в Серебряном бору.',`completedtext_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Эти люди больше преуспеют в загробной жизни, став Отрекшимися.',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Леди Сильвана Ветрокрылая',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27098,'Лордерон','Сопроводи меня в Гробницу, $n. Нам с тобой очень многое надо обсудить. Очень важно, чтобы ты $gзнал:знала; историю Лордерона и чумы Отрекшихся.','Отправляйтесь с леди Сильваной Ветрокрылой в Гробницу в Серебряном бору.','Теперь ты понимаешь, как много от нас зависит? Надо остановить Краули и его альянсовских псов!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лордерон',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сопроводи меня в Гробницу, $n. Нам с тобой очень многое надо обсудить. Очень важно, чтобы ты $gзнал:знала; историю Лордерона и чумы Отрекшихся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь с леди Сильваной Ветрокрылой в Гробницу в Серебряном бору.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь ты понимаешь, как много от нас зависит? Надо остановить Краули и его альянсовских псов!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27099,'Спасенья нет','Тебе нужно нанести удар по их лидерам, $n. Они сейчас отсиживаются в старой крепости. Прорвись туда и найди лидеров беженцев! Заставь их подчиниться королеве!$B$BНикому не уйти от гнева Отрекшихся!','Отыщите лидеров беженцев в Крепости Фенриса.','Похоже, Краули еще опаснее, чем я предполагала. И все же он простой человек из плоти и крови, и у него есть свои тайны. А тайны эти мне известны...$B$BТы хорошо мне послужил, Стэлио. Кроме того, твоя помощь пригодилась бы мне и в Гробнице. У меня есть план, как раз и навсегда избавиться от Краули и его мятежников. Ты поможешь?','Поговорите с леди Сильваной Ветрокрылой в Ставке Отрекшихся в Серебряном бору.','Найдите на втором этаже комнату лидеров.','Леди Сильвана Ветрокрылая') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спасенья нет',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе нужно нанести удар по их лидерам, $n. Они сейчас отсиживаются в старой крепости. Прорвись туда и найди лидеров беженцев! Заставь их подчиниться королеве!$B$BНикому не уйти от гнева Отрекшихся!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщите лидеров беженцев в Крепости Фенриса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Похоже, Краули еще опаснее, чем я предполагала. И все же он простой человек из плоти и крови, и у него есть свои тайны. А тайны эти мне известны...$B$BТы хорошо мне послужил, Стэлио. Кроме того, твоя помощь пригодилась бы мне и в Гробнице. У меня есть план, как раз и навсегда избавиться от Краули и его мятежников. Ты поможешь?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с леди Сильваной Ветрокрылой в Ставке Отрекшихся в Серебряном бору.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Найдите на втором этаже комнату лидеров.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Леди Сильвана Ветрокрылая',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27100,'Исследование Сумеречного Молота','Кажется, книга, которую вы обнаружили, содержит подробные записи о некоем исследовании, проводимом кем-то из Сумеречного Молота.$b$bВ ней что-то говорится о слизняках, но многих страниц не хватает.$b$bВозможно, если вы отыщете дополнительные страницы, вам удастся понять, о чем идет речь.','Добудьте 4 страницы исследовательских записей Сумеречного Молота у переливчатых слизнюков в Верховье Серебристой топи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Исследование Сумеречного Молота',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кажется, книга, которую вы обнаружили, содержит подробные записи о некоем исследовании, проводимом кем-то из Сумеречного Молота.$b$bВ ней что-то говорится о слизняках, но многих страниц не хватает.$b$bВозможно, если вы отыщете дополнительные страницы, вам удастся понять, о чем идет речь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 4 страницы исследовательских записей Сумеречного Молота у переливчатых слизнюков в Верховье Серебристой топи.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27101,'Откровение Мазиела','Записи содержат продолжение бессвязного исследования Мазиела об особенностях ртутных и переливчатых слизнюков.$b$bПохоже, он совершил большое открытие. Он упоминает о том, что спрятал свой дневник в Низине Серебристой топи, к юго-западу отсюда.','Найдите дневник Мазиела в Низине Серебристой топи в Подземье.','Похоже, ртуть не испортила дневник Мазиела.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Откровение Мазиела',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Записи содержат продолжение бессвязного исследования Мазиела об особенностях ртутных и переливчатых слизнюков.$b$bПохоже, он совершил большое открытие. Он упоминает о том, что спрятал свой дневник в Низине Серебристой топи, к юго-западу отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите дневник Мазиела в Низине Серебристой топи в Подземье.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Похоже, ртуть не испортила дневник Мазиела.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27102,'Сила Мазиела','В дневнике Мазиела описан ритуал, который сделает его тело состоящим из чистой ртути.$b$bРитуал будет проводиться в пещере возле Низины Серебристой топи, где Мазиел будет есть переливчатых слизнюков до тех пор, пока не наберет полную силу.$b$bМожет быть, еще не слишком поздно положить конец его безумию.','Убейте Мазиела в Пещере Серебряного Света в Подземье.','Положи конец его безумию.','Мазиел') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сила Мазиела',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В дневнике Мазиела описан ритуал, который сделает его тело состоящим из чистой ртути.$b$bРитуал будет проводиться в пещере возле Низины Серебристой топи, где Мазиел будет есть переливчатых слизнюков до тех пор, пока не наберет полную силу.$b$bМожет быть, еще не слишком поздно положить конец его безумию.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Мазиела в Пещере Серебряного Света в Подземье.',`objectives_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Положи конец его безумию.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Мазиел',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27103,'Осколки сквернита','Эта часть Эльдре\'Таласа подверглась тлетворному влиянию сатира Алззина Перевертеня. Плод Изобилия, теперь превращенный в сквернит, должен быть у Алззина. Быть может, именно с помощью этого предмета мы сумеем очистить нашу землю.$B$BКогда великий сатир падет, захвати какую-нибудь часть сквернита. Запечатай ее в этом реликварии Чистоты и принеси мне.$B$BУдачи! И да благословит тебя Кенарий.','Воспользуйтесь реликварием Чистоты, чтобы захватить осколок сквернита.','Обладая запечатанным реликварием Чистоты, мы сможем не только защитить мир от этой погани, но и изучить ее. Может статься, нам даже удастся разработать новые средства борьбы с этой мерзостной заразой, вечно угрожающей Азероту.','Вернитесь к Фургусу Криводреву.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Осколки сквернита',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эта часть Эльдре\'Таласа подверглась тлетворному влиянию сатира Алззина Перевертеня. Плод Изобилия, теперь превращенный в сквернит, должен быть у Алззина. Быть может, именно с помощью этого предмета мы сумеем очистить нашу землю.$B$BКогда великий сатир падет, захвати какую-нибудь часть сквернита. Запечатай ее в этом реликварии Чистоты и принеси мне.$B$BУдачи! И да благословит тебя Кенарий.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь реликварием Чистоты, чтобы захватить осколок сквернита.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Обладая запечатанным реликварием Чистоты, мы сможем не только защитить мир от этой погани, но и изучить ее. Может статься, нам даже удастся разработать новые средства борьбы с этой мерзостной заразой, вечно угрожающей Азероту.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фургусу Криводреву.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27104,'Алззин Перевертень','Чудовище, которое обратило все это в руины, зовут Алззин Перевертень. Но чтобы добраться до него, тебе придется также убить Зеврима Терновое Копыто, сатира, который держит в плену Древня Железную Кору.$B$BКогда Железная Кора будет освобожден, он поможет тебе пробраться во владения Алззина. Отправляйся туда и убей Алззина безо всякой пощады – другого пути нет.','Убейте Зеврима Терновое Копыто и Алззина Перевертеня.','А, очень, очень хорошо. Сегодня ты осчастливил старого духа. Ты заслуживаешь всяческой благодарности за свой подвиг.','Вернитесь к Фургусу Криводреву.','Алззин – грязный плут.','Алззин Перевертень') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Алззин Перевертень',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чудовище, которое обратило все это в руины, зовут Алззин Перевертень. Но чтобы добраться до него, тебе придется также убить Зеврима Терновое Копыто, сатира, который держит в плену Древня Железную Кору.$B$BКогда Железная Кора будет освобожден, он поможет тебе пробраться во владения Алззина. Отправляйся туда и убей Алззина безо всякой пощады – другого пути нет.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Зеврима Терновое Копыто и Алззина Перевертеня.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, очень, очень хорошо. Сегодня ты осчастливил старого духа. Ты заслуживаешь всяческой благодарности за свой подвиг.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фургусу Криводреву.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Алззин – грязный плут.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Алззин Перевертень',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27105,'Незваный гость','В Забытом городе много природных и волшебных элементалей, но недавно там появился один элементаль воды. Пожалуйста, добудь его сущность и принеси мне. Я хочу знать, как такой элементаль попал в Забытый город и не опасен ли он для элементалей природы Эльдре\'Талас.','Добудьте сущность Гидротвари.','Меня тревожит, что в этих краях появился элементаль воды, да еще и такой сильный. Вот награда за твои услуги. А я займусь исследованием его сущности.','Вернитесь к Фургусу Криводреву.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Незваный гость',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В Забытом городе много природных и волшебных элементалей, но недавно там появился один элементаль воды. Пожалуйста, добудь его сущность и принеси мне. Я хочу знать, как такой элементаль попал в Забытый город и не опасен ли он для элементалей природы Эльдре\'Талас.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте сущность Гидротвари.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Меня тревожит, что в этих краях появился элементаль воды, да еще и такой сильный. Вот награда за твои услуги. А я займусь исследованием его сущности.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фургусу Криводреву.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27106,'Разоблачение злодея','<Вы нашли список всех сторонников Сумеречного Молота в Штормграде.>$B$B<Более того – обнаружили письмо, в котором майор Самуэльсон подробно излагает своим единоверцам весь план действий. Принц был прав: предатель – Самуэльсон; он использует свое положение командира стражи, чтобы выгораживать заговорщиков.>$B$B<Пора вернуться в крепость Штормграда и свершить правосудие над Самуэльсоном!>','Разоблачите и убейте майора Самуэльсона в тронном зале крепости Штормграда.','Поговорите с королем Варианом Ринном в крепости Штормграда в Штормграде.','Все это время он находился в тронном зале Штормграда. Прямо рядом с королем!','Майор Самуэльсон') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разоблачение злодея',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Вы нашли список всех сторонников Сумеречного Молота в Штормграде.>$B$B<Более того – обнаружили письмо, в котором майор Самуэльсон подробно излагает своим единоверцам весь план действий. Принц был прав: предатель – Самуэльсон; он использует свое положение командира стражи, чтобы выгораживать заговорщиков.>$B$B<Пора вернуться в крепость Штормграда и свершить правосудие над Самуэльсоном!>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разоблачите и убейте майора Самуэльсона в тронном зале крепости Штормграда.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с королем Варианом Ринном в крепости Штормграда в Штормграде.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Все это время он находился в тронном зале Штормграда. Прямо рядом с королем!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Майор Самуэльсон',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27107,'Воришка Пузиллин','Я немного вздремнуть, а этот глупый проворный бес стащить моя книга! Без книги Дагг\'тол не выполнять приказы, а хозяин не завоевать мир!$B$BЕсли ты, |3-6($r), помочь мне вернуть книгу, я дать тебе что-то ценное. Вперед, этот бес – там, слева! УБИТЬ!!!','Убедите Пузиллина отдать книгу магических формул.','Книга вернуться! Теперь хозяин убивать глупые деревья и рогатых! ХА!','Гном, где книга?','Вернитесь к "посланнику" Дагг\'толу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Воришка Пузиллин',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я немного вздремнуть, а этот глупый проворный бес стащить моя книга! Без книги Дагг\'тол не выполнять приказы, а хозяин не завоевать мир!$B$BЕсли ты, |3-6($r), помочь мне вернуть книгу, я дать тебе что-то ценное. Вперед, этот бес – там, слева! УБИТЬ!!!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убедите Пузиллина отдать книгу магических формул.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Книга вернуться! Теперь хозяин убивать глупые деревья и рогатых! ХА!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Гном, где книга?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к "посланнику" Дагг\'толу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27108,'Сеть Лефтендрис','Эльфийка крови Лефтендрис поставить здесь сеть, чтобы ловить магию. Она все брать себе, но хозяин бы использовать эту магию на благо всего мир! Помоги забрать сеть у глупой эльфийки, и Дагг\'тол наградить тебя. А еще ты увидеть, как мудро станет использовать ее хозяин!','Добудьте сеть Лефтендрис.','Теролекс, ты забрать сеть глупой эльфийки?','Вернитесь к "посланнику" Дагг\'толу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сеть Лефтендрис',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эльфийка крови Лефтендрис поставить здесь сеть, чтобы ловить магию. Она все брать себе, но хозяин бы использовать эту магию на благо всего мир! Помоги забрать сеть у глупой эльфийки, и Дагг\'тол наградить тебя. А еще ты увидеть, как мудро станет использовать ее хозяин!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте сеть Лефтендрис.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Теролекс, ты забрать сеть глупой эльфийки?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к "посланнику" Дагг\'толу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27109,'Криводрев-защитник','Когда-то древни Железная Кора и Криводрев были бравыми защитниками Эльдре\'Талас. И как же низко они пали! Их судьба в руках у нас, двоих высокорожденных. Но мы слишком безрассудно распорядились своей силой, |3-6($r).$B$BНо ты можешь исправить нашу ошибку! Ступай и помоги Тендрису Криводреву обрести вечный покой. Он был последним и самым сильным защитником этих земель, и его дух достоин освобождения. Но знай: если ты не одолеешь древня Железную Кору до боя с Тендрисом, он может позвать его на подмогу.','Убейте Тендриса Криводрева.','Ты совершил благородный поступок. Поверь, душа Тендриса молила об освобождении. Он благодарен тебе.','Вернитесь к шен\'драларскому дозорному.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Криводрев-защитник',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда-то древни Железная Кора и Криводрев были бравыми защитниками Эльдре\'Талас. И как же низко они пали! Их судьба в руках у нас, двоих высокорожденных. Но мы слишком безрассудно распорядились своей силой, |3-6($r).$B$BНо ты можешь исправить нашу ошибку! Ступай и помоги Тендрису Криводреву обрести вечный покой. Он был последним и самым сильным защитником этих земель, и его дух достоин освобождения. Но знай: если ты не одолеешь древня Железную Кору до боя с Тендрисом, он может позвать его на подмогу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Тендриса Криводрева.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты совершил благородный поступок. Поверь, душа Тендриса молила об освобождении. Он благодарен тебе.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к шен\'драларскому дозорному.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27110,'Древнее безумие','Пришло время положить конец этому безумию. Эра бессмертных давно минула. Уничтожь стражей, охраняющих пять пилонов. Силовое поле рассеется, и ты сможешь уничтожить Бессмер\'тера. А затем убей самого принца – гибель демона здорово подорвет его силы. Пусть принц заплатит за свои злодеяния, а духи этого города упокоятся с миром.','Благодарим тебя, герой.','Вернитесь к прародительнице Шен\'дралар.','Источник сил принца.','Бессмер\'тер') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Древнее безумие',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пришло время положить конец этому безумию. Эра бессмертных давно минула. Уничтожь стражей, охраняющих пять пилонов. Силовое поле рассеется, и ты сможешь уничтожить Бессмер\'тера. А затем убей самого принца – гибель демона здорово подорвет его силы. Пусть принц заплатит за свои злодеяния, а духи этого города упокоятся с миром.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Благодарим тебя, герой.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к прародительнице Шен\'дралар.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Источник сил принца.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Бессмер\'тер',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`offerrewardtext_loc8`) VALUES (27111,'Под лестницей читальни спрятан древний сундук. Можешь взять оттуда то, что пожелаешь.','Вы открываете сундук, а в нем...') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Под лестницей читальни спрятан древний сундук. Можешь взять оттуда то, что пожелаешь.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы открываете сундук, а в нем...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27112,'Проклятые призраки','Кое-кто из обитателей Забытого города может помешать нам отвоевать этот священный город. Я говорю о магистре Календрисе и Иллиане Вороний Дуб. Они чрезвычайно опасны, поэтому необходимо устранить их как можно скорее.$B$BБудь $gосторожен:осторожна;: теперь, когда поборников энергии Бессмер\'тера осталось так мало, они могут оказаться сильнее, чем при первой встрече.','Убейте магистра Календриса и Иллиану Вороний Дуб.','Благодаря тебе нам стало гораздо легче.','Вернитесь к Эстулану.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Проклятые призраки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кое-кто из обитателей Забытого города может помешать нам отвоевать этот священный город. Я говорю о магистре Календрисе и Иллиане Вороний Дуб. Они чрезвычайно опасны, поэтому необходимо устранить их как можно скорее.$B$BБудь $gосторожен:осторожна;: теперь, когда поборников энергии Бессмер\'тера осталось так мало, они могут оказаться сильнее, чем при первой встрече.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте магистра Календриса и Иллиану Вороний Дуб.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Благодаря тебе нам стало гораздо легче.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Эстулану.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (27113,'Наша встреча не случайна, Пивобород.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Наша встреча не случайна, Пивобород.',`offerrewardtext_loc8`);
