INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27115,'Зов Андо','Поговорите с Андо Подрывайстером.','Она работает! Мой отец привез ее.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зов Андо',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Андо Подрывайстером.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Она работает! Мой отец привез ее.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27116,'Ветра Лок Модана','Отец завершил работу над небесным долгоногом. Он потрясающий! Когда мы закончим со всеми мелочами, он поможет мне в борьбе за справедливость, так же, как это $gделал:делала; ты.$b$bЯ знаю, тебе нужно двигаться дальше, помогать другим людям, вести себя геройски и все такое, но не хочешь ли прокатиться? Вот-вот небесный долгоног впервые поднимется в небо, и я почту за честь, если ты присоединишься ко мне. Подброшу тебя до станции Альгаз.$b$bЧто скажешь?','Отправляйтесь на небесном долгоноге на станцию Альгаз и поговорите там с горным пехотинцем Грозовой Вершиной.','Что, черт возьми, ЭТО было? Летающий механодолгоног?$B$BЗнаешь что, я не хочу ничего об этом знать. Я собираюсь притвориться, что ничего не видел, и мы тихо-мирно вернемся к делам.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ветра Лок Модана',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Отец завершил работу над небесным долгоногом. Он потрясающий! Когда мы закончим со всеми мелочами, он поможет мне в борьбе за справедливость, так же, как это $gделал:делала; ты.$b$bЯ знаю, тебе нужно двигаться дальше, помогать другим людям, вести себя геройски и все такое, но не хочешь ли прокатиться? Вот-вот небесный долгоног впервые поднимется в небо, и я почту за честь, если ты присоединишься ко мне. Подброшу тебя до станции Альгаз.$b$bЧто скажешь?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь на небесном долгоноге на станцию Альгаз и поговорите там с горным пехотинцем Грозовой Вершиной.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что, черт возьми, ЭТО было? Летающий механодолгоног?$B$BЗнаешь что, я не хочу ничего об этом знать. Я собираюсь притвориться, что ничего не видел, и мы тихо-мирно вернемся к делам.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27117,'Грубая сила','Гандлинг привел с собой своего лейтенанта, Равениана. Этот зверюга куда опаснее, чем любой из воинов Плети, что встретятся тебе на поле боя... даже опаснее, чем поганища.$B$BТы найдешь Равениана в башне на юге города. Советую хорошенько подготовиться к схватке,$n. Этого нахрапом не возьмешь.','Убейте Равениана в Андорале.','Вернитесь к Кольтире Ткачу Смерти в Андорал в Западных Чумных землях.','За границами Некроситета слабнет Равениан… но сила его все еще велика.','Равениан') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Грубая сила',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Гандлинг привел с собой своего лейтенанта, Равениана. Этот зверюга куда опаснее, чем любой из воинов Плети, что встретятся тебе на поле боя... даже опаснее, чем поганища.$B$BТы найдешь Равениана в башне на юге города. Советую хорошенько подготовиться к схватке,$n. Этого нахрапом не возьмешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Равениана в Андорале.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кольтире Ткачу Смерти в Андорал в Западных Чумных землях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','За границами Некроситета слабнет Равениан… но сила его все еще велика.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Равениан',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27118,'Сломанная западня','Перед вами лежит большая сломанная ловушка. Судя по ее виду, огры пытались починить ее, но у них ничего не вышло. Рядом с ловушка лежит второпях нацарапанная записка, и, что удивительно, в ней говорится о том, как починить западню. Нужно произвести всего лишь несколько простых манипуляций. Если западню починить, то любой проходящий мимо огр может в нее попасть и тогда его можно будет благополучно миновать.$b$bОчевидно, мало кто из огров умеет читать.','Вернитесь к сломанной ловушке в Альтеракских горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сломанная западня',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Перед вами лежит большая сломанная ловушка. Судя по ее виду, огры пытались починить ее, но у них ничего не вышло. Рядом с ловушка лежит второпях нацарапанная записка, и, что удивительно, в ней говорится о том, как починить западню. Нужно произвести всего лишь несколько простых манипуляций. Если западню починить, то любой проходящий мимо огр может в нее попасть и тогда его можно будет благополучно миновать.$b$bОчевидно, мало кто из огров умеет читать.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к сломанной ловушке в Альтеракских горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27119,'Броня огров Гордока','Если ты $gсобрался:собралась; убить короля, то сперва тебе придется пройти мимо капитана Давигрома. Да, можно просто его убить, но будет лучше, если ты обойдешься без этого.$B$BКак, спрашиваешь? Ну, я тут давно, и успел придумать, как сделать настоящий огрский костюм. Найди огрскую дубильную кислоту этажом выше и принеси мне. Сам я сходить не могу, как видишь...','Принесите огрскую дубильную кислоту Уззлу Наперстяку.','Да, теперь все получится. Так, подвернем здесь, подтянем тут... Готово!<Гоблин-невольник расплывается в улыбке.>$B$BТеперь можешь идти. Но помни: это не самый надежный костюм в мире. У тебя есть десять минут, а потом он просто развалится, и тогда тебя сразу раскроют! Так что надевай его прямо перед тем, как подойти к капитану, чтобы времени хватило наверняка.','Вернитесь к Уззлу Наперстяку.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Броня огров Гордока',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если ты $gсобрался:собралась; убить короля, то сперва тебе придется пройти мимо капитана Давигрома. Да, можно просто его убить, но будет лучше, если ты обойдешься без этого.$B$BКак, спрашиваешь? Ну, я тут давно, и успел придумать, как сделать настоящий огрский костюм. Найди огрскую дубильную кислоту этажом выше и принеси мне. Сам я сходить не могу, как видишь...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите огрскую дубильную кислоту Уззлу Наперстяку.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, теперь все получится. Так, подвернем здесь, подтянем тут... Готово!<Гоблин-невольник расплывается в улыбке.>$B$BТеперь можешь идти. Но помни: это не самый надежный костюм в мире. У тебя есть десять минут, а потом он просто развалится, и тогда тебя сразу раскроют! Так что надевай его прямо перед тем, как подойти к капитану, чтобы времени хватило наверняка.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Уззлу Наперстяку.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27120,'Броня огров Гордока','Вот, пожалуйста, Секарт: после того, как ты его наденешь, у тебя в запасе будет десять минут. Удачи!$B$BДа, и если сумеешь найти ключ, чтобы выпустить меня отсюда, непременно мне скажи, слышишь?','Тебе нужен костюм, да? В ближайшее время я вряд ли отсюда выберусь, так что принеси мне огрскую дубильную кислоту, и я соображу тебе костюм огра.','Вернитесь к Уззлу Наперстяку.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Броня огров Гордока',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот, пожалуйста, Секарт: после того, как ты его наденешь, у тебя в запасе будет десять минут. Удачи!$B$BДа, и если сумеешь найти ключ, чтобы выпустить меня отсюда, непременно мне скажи, слышишь?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе нужен костюм, да? В ближайшее время я вряд ли отсюда выберусь, так что принеси мне огрскую дубильную кислоту, и я соображу тебе костюм огра.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Уззлу Наперстяку.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (27121,'Free Knot!','[Deprecated] Return to Knot Thimblejack in Alterac Mountains.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Free Knot!',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','[Deprecated] Return to Knot Thimblejack in Alterac Mountains.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27122,'С огоньком','Пусть дворфы из клана Черного Железа якшаются с прихвостнями и пособниками Рагнароса. Бьюсь об заклад, культ Сумеречного Молота стоит за всем происходящим!$B$BПора раз и навсегда положить конец нападениям на Стальгорн. Да, и не забудь передать комадиру Грузному Кулаку о том, что тут произошло, когда мы вернемся. Сам-то я буду занят – кто-то должен присматривать за возвращением горожан, ремонтными работами и прочим.','Убейте великого посла Огнехлыста и поставьте об этом в известность командира Грузного Кулака в Стальгорне.','Сообщите командиру Грузному Кулаку в Стальгорне о смерти великого посла Огнехлыста.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','С огоньком',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пусть дворфы из клана Черного Железа якшаются с прихвостнями и пособниками Рагнароса. Бьюсь об заклад, культ Сумеречного Молота стоит за всем происходящим!$B$BПора раз и навсегда положить конец нападениям на Стальгорн. Да, и не забудь передать комадиру Грузному Кулаку о том, что тут произошло, когда мы вернемся. Сам-то я буду занят – кто-то должен присматривать за возвращением горожан, ремонтными работами и прочим.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте великого посла Огнехлыста и поставьте об этом в известность командира Грузного Кулака в Стальгорне.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Сообщите командиру Грузному Кулаку в Стальгорне о смерти великого посла Огнехлыста.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27123,'Подземье, мир земли','Я знал, что ты придешь на наш зов, $n. Когда Аспекты драконов в первый раз одержали верх над Смертокрылом, он скрылся в Подземье, мир земли.$b$bПосле возвращения Смертокрыла в наш мир разлом между Азеротом и Подземьем остался открытым.$b$bМы делаем все, что в наших силах, чтобы ликвидировать разрушения с этой стороны разлома. Аггра проведет тебя через него, и ты сможешь помочь справиться с разрушениями с другой стороны.$b$bКогда будешь $gготов:готова;, садись на ее виверну.','Садитесь на виверну Аггры и летите к разлому в Водовороте. Когда окажетесь на другой стороне, поговорите с Маруутом Камневязом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подземье, мир земли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я знал, что ты придешь на наш зов, $n. Когда Аспекты драконов в первый раз одержали верх над Смертокрылом, он скрылся в Подземье, мир земли.$b$bПосле возвращения Смертокрыла в наш мир разлом между Азеротом и Подземьем остался открытым.$b$bМы делаем все, что в наших силах, чтобы ликвидировать разрушения с этой стороны разлома. Аггра проведет тебя через него, и ты сможешь помочь справиться с разрушениями с другой стороны.$b$bКогда будешь $gготов:готова;, садись на ее виверну.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Садитесь на виверну Аггры и летите к разлому в Водовороте. Когда окажетесь на другой стороне, поговорите с Маруутом Камневязом.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27124,'Неоконченное дело Гордоков','Теперь ты быть король, так может, ты отобрать один ценный артефакт огров Гордока у стражника Мол\'дара? Тот, что до тебя быть король, не слушал, да и другие короли тоже – все, даже до первый король Гордока!$B$BАртефакт называться латная рукавица Мощи Гордока. В старых преданиях говорить, что отобрать его может только настоящий король Гордока. Если ты найти его, он прослужить тебе вечно! А я показать тебе дорогу!','Ого... ты и впрямь настоящий король! Старый король о рукавице даже не спрашивать.$B$BВидеть эту печать? Это магический знак, очень-очень-ОЧЕНЬ древний. Поговаривать, даже древнее, чем Гордок. Но когда я быть маленький, меня научить снимать эту печать и возвращать рукавице силу.$B$BИ сейчас я это делать для тебя, король! Вот твоя рукавица, теперь ты править ВЕЧНО!','Вернитесь к капитану Давигрому к трону Гордока, что в Забытом Городе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Неоконченное дело Гордоков',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь ты быть король, так может, ты отобрать один ценный артефакт огров Гордока у стражника Мол\'дара? Тот, что до тебя быть король, не слушал, да и другие короли тоже – все, даже до первый король Гордока!$B$BАртефакт называться латная рукавица Мощи Гордока. В старых преданиях говорить, что отобрать его может только настоящий король Гордока. Если ты найти его, он прослужить тебе вечно! А я показать тебе дорогу!',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ого... ты и впрямь настоящий король! Старый король о рукавице даже не спрашивать.$B$BВидеть эту печать? Это магический знак, очень-очень-ОЧЕНЬ древний. Поговаривать, даже древнее, чем Гордок. Но когда я быть маленький, меня научить снимать эту печать и возвращать рукавице силу.$B$BИ сейчас я это делать для тебя, король! Вот твоя рукавица, теперь ты править ВЕЧНО!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Давигрому к трону Гордока, что в Забытом Городе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27125,'Король Гордока','В иерархии огров племени Гордока королем является самый сильный воин. Если огр или любое другое существо убивает действующего короля, его самого нарекают новым правителем.$B$BКороль получает подношения от всех живых стражей, Топотуна Крига и капитана Давигрома. Найди и убей короля Гордока, но постарайся оставить в живых как можно больше других главарей. Тогда ты получишь не только награду, но и возможность остановить нашествие огров Гордока мирным путем!','Убейте короля Гордока.','Вернитесь к друиду-ворону.','Лиши его трона!','Король Гордок') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Король Гордока',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В иерархии огров племени Гордока королем является самый сильный воин. Если огр или любое другое существо убивает действующего короля, его самого нарекают новым правителем.$B$BКороль получает подношения от всех живых стражей, Топотуна Крига и капитана Давигрома. Найди и убей короля Гордока, но постарайся оставить в живых как можно больше других главарей. Тогда ты получишь не только награду, но и возможность остановить нашествие огров Гордока мирным путем!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте короля Гордока.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к друиду-ворону.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Лиши его трона!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Король Гордок',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (27126,'Срочная доставка','У команды Пика Камнемола сломалась катапульта. Их можно найти к западу отсюда.$b$bДумаю, для разнообразия ты можешь сделать что-нибудь полезное, не так ли, |3-6($r)? Отнеси им запчасти для катапульты.','Доставьте детали катапульты Пику Камнемолу на Разбитую передовую, что в Подземье.','Это запчасти там у тебя?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Срочная доставка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У команды Пика Камнемола сломалась катапульта. Их можно найти к западу отсюда.$b$bДумаю, для разнообразия ты можешь сделать что-нибудь полезное, не так ли, |3-6($r)? Отнеси им запчасти для катапульты.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте детали катапульты Пику Камнемолу на Разбитую передовую, что в Подземье.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Это запчасти там у тебя?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27127,'С огоньком','Клан Черного Железа? Чо\'Галл?! Сейчас они узнают, какая судьба ждет тех, кто покушается на Оргриммар.$B$BК оружию! Мы окунем их трупы в лаву, которую они так любят.$B$BНе сомневаемся, что вы расскажете кровавому стражу Кангу обо всем, что здесь произошло. Сам-то я буду занят – кто-то должен присматривать за городскими ремонтными работами...','Убейте великого посла Огнехлыста и поставьте об этом в известность кровавого стража Канга в Оргриммаре.','Сообщите кровавому стражу Кангу в Оргриммаре о смерти великого посла Огнехлыста.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','С огоньком',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Клан Черного Железа? Чо\'Галл?! Сейчас они узнают, какая судьба ждет тех, кто покушается на Оргриммар.$B$BК оружию! Мы окунем их трупы в лаву, которую они так любят.$B$BНе сомневаемся, что вы расскажете кровавому стражу Кангу обо всем, что здесь произошло. Сам-то я буду занят – кто-то должен присматривать за городскими ремонтными работами...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте великого посла Огнехлыста и поставьте об этом в известность кровавого стража Канга в Оргриммаре.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Сообщите кровавому стражу Кангу в Оргриммаре о смерти великого посла Огнехлыста.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27128,'Король Гордока','Если ты убить короля Гордока – ты $gсам:сама; стать король. А если ты стать король, то остановить огров Гордока, а Давигром, Криг и другие вожаки заплатить тебе большую дань, если сами выжить. Тогда я стать очень счастливый огр, и мы захватить Забытый город ДЛЯ ОРДЫ!!!$B$BВперед, $gмаленький:маленькая:r; |3-6($r)! Убить мерзкий король Гордока, а мы построить тут новый крепость Каменного Молота!','Убейте короля Гордока.','Вернитесь к огру Каменного Молота.','Лиши его трона!','Король Гордок') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Король Гордока',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если ты убить короля Гордока – ты $gсам:сама; стать король. А если ты стать король, то остановить огров Гордока, а Давигром, Криг и другие вожаки заплатить тебе большую дань, если сами выжить. Тогда я стать очень счастливый огр, и мы захватить Забытый город ДЛЯ ОРДЫ!!!$B$BВперед, $gмаленький:маленькая:r; |3-6($r)! Убить мерзкий король Гордока, а мы построить тут новый крепость Каменного Молота!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте короля Гордока.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к огру Каменного Молота.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Лиши его трона!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Король Гордок',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (27129,'Спасение Криводрева','Поговорите с Фургусом Криводревом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спасение Криводрева',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Фургусом Криводревом.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27130,'Спасение Криводрева','В восточной части Забытого города живет почтенный древень Фургус Криводрев – один из немногих, до кого не добрались демоны. Отправляйся туда и помоги ему прогнать этих жутких тварей, пока они не пошли на лагерь Мохаче. Может быть, он и дальше станет помогать нам держать оборону в Фераласе.','Поговорите с Фургусом Криводревом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спасение Криводрева',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В восточной части Забытого города живет почтенный древень Фургус Криводрев – один из немногих, до кого не добрались демоны. Отправляйся туда и помоги ему прогнать этих жутких тварей, пока они не пошли на лагерь Мохаче. Может быть, он и дальше станет помогать нам держать оборону в Фераласе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Фургусом Криводревом.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (27131,'Высокорожденный','Поговорите с Эстуланом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Высокорожденный',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Эстуланом.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27132,'Высокорожденный','Один из высокорожденных, могущественный Эстулан, проник в западную часть Забытого города. Его душа не осквернена, и он просит нашей помощи в борьбе за город. Сейчас мы должны забыть все разногласия и присоединиться к нему ради общего блага. Поторопись, нам важна любая победа в Фераласе.$B$BЗабытый город находится к западу отсюда.','Поговорите с Эстуланом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Высокорожденный',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Один из высокорожденных, могущественный Эстулан, проник в западную часть Забытого города. Его душа не осквернена, и он просит нашей помощи в борьбе за город. Сейчас мы должны забыть все разногласия и присоединиться к нему ради общего блага. Поторопись, нам важна любая победа в Фераласе.$B$BЗабытый город находится к западу отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Эстуланом.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (27133,'Небесные очи','Поговорите с друидом-вороном.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Небесные очи',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с друидом-вороном.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27134,'Огр на поле боя','Самая страшная угроза для Фераласа – огры племени Гордока, обитающие в северной части Забытого города. Если мы уничтожим их и захватим Забытый город, Орда еще больше укрепится в этом регионе и к тому же получит в свое распоряжение множество артефактов. Я заранее направила в Забытый город небольшой отряд огров Каменного Молота. Если найдешь кого из них живого, переговори с ним.$B$BЭто приказ, |3-6($c).','Поговорите с огром Каменного Молота.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Огр на поле боя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Самая страшная угроза для Фераласа – огры племени Гордока, обитающие в северной части Забытого города. Если мы уничтожим их и захватим Забытый город, Орда еще больше укрепится в этом регионе и к тому же получит в свое распоряжение множество артефактов. Я заранее направила в Забытый город небольшой отряд огров Каменного Молота. Если найдешь кого из них живого, переговори с ним.$B$BЭто приказ, |3-6($c).',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с огром Каменного Молота.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27135,'Что-то пылающее','Ну вот, а теперь нам нужно что-то, что придаст этому веществу гремучести!$b$bПорох у меня закончился, но я знаю, чем его можно заменить... сердцем огненного элементаля!$b$bВот, установи мой тотем огня восточнее Кровавой тропы, возле какого-нибудь озера лавы. Просто поверни переключатель, чтобы призвать Магмазуба. Принеси мне его сердце, и мы примемся за работу.','Добудьте пылающее сердце.','Гм-гм. Похоже, сложившаяся ситуация его не слишком обрадовала. Откуда я знаю? Ну, я же все-таки посвященный как никак.$B$BВпрочем, с Магмазубом разберемся позже.','Вернитесь к посвященному Клондацку в Кварцитовую впадину, что в Подземье.','Если Клондацк говорит, что пылающее сердце взять можно, значит, можно…','Магмазуб') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Что-то пылающее',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну вот, а теперь нам нужно что-то, что придаст этому веществу гремучести!$b$bПорох у меня закончился, но я знаю, чем его можно заменить... сердцем огненного элементаля!$b$bВот, установи мой тотем огня восточнее Кровавой тропы, возле какого-нибудь озера лавы. Просто поверни переключатель, чтобы призвать Магмазуба. Принеси мне его сердце, и мы примемся за работу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте пылающее сердце.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Гм-гм. Похоже, сложившаяся ситуация его не слишком обрадовала. Откуда я знаю? Ну, я же все-таки посвященный как никак.$B$BВпрочем, с Магмазубом разберемся позже.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к посвященному Клондацку в Кварцитовую впадину, что в Подземье.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Если Клондацк говорит, что пылающее сердце взять можно, значит, можно…',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Магмазуб',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27136,'Энергия элементалей','Уничтожьте 8 заряженных жеод или магнитных элементалей вблизи опустошенного тотема.','Вернитесь к провидцу Кормо в Храм Земли, что в Подземье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Энергия элементалей',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 8 заряженных жеод или магнитных элементалей вблизи опустошенного тотема.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к провидцу Кормо в Храм Земли, что в Подземье.',`completedtext_loc8`);
