INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (27138,'С земными девушками не совладать') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','С земными девушками не совладать',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27139,'Хобарту нужна твоя помощь','Привет, босс, тут Хобарт Дрек хочет с тобой побеседовать. Говорит, дело не терпит отлагательства.','Поговорите с Хобартом Дреком в Городке-из-табакерки на Затерянных островах.','А вот и ты, мой мальчик. У меня к тебе одно немаловажное дельце!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хобарту нужна твоя помощь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Привет, босс, тут Хобарт Дрек хочет с тобой побеседовать. Говорит, дело не терпит отлагательства.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Хобартом Дреком в Городке-из-табакерки на Затерянных островах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А вот и ты, мой мальчик. У меня к тебе одно немаловажное дельце!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27140,'Ловушка Алексия','Мне нужна твоя помощь, |3-6($c). Найди Вектуса, мага-нежить, и воина Мардука. Они должны быть где-то здесь. Эти двое руководят операцией Плети по зачумлению драконов, и их следует уничтожить.$B$BПоложи эту ловушку в демонстрационной комнате, где они постоянно бывают. Будем надеяться, это поможет тебе избавиться от значительного количества их помощников.$B$BА уж потом тебе не составит труда прикончить и Вектуса, и Мардука. Верно?','Положите ловушку в демонстрационной комнате и уничтожьте Вектуса и Мардука.','Вернитесь к Алексию Барову.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ловушка Алексия',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне нужна твоя помощь, |3-6($c). Найди Вектуса, мага-нежить, и воина Мардука. Они должны быть где-то здесь. Эти двое руководят операцией Плети по зачумлению драконов, и их следует уничтожить.$B$BПоложи эту ловушку в демонстрационной комнате, где они постоянно бывают. Будем надеяться, это поможет тебе избавиться от значительного количества их помощников.$B$BА уж потом тебе не составит труда прикончить и Вектуса, и Мардука. Верно?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Положите ловушку в демонстрационной комнате и уничтожьте Вектуса и Мардука.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Алексию Барову.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (27140,'You did it! They are defeated! And the Gambit... did it work?$B$BVery interesting. You\'ve done well, $n.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','You did it! They are defeated! And the Gambit... did it work?$B$BVery interesting. You\'ve done well, $n.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27141,'Преждевременный взрыв','Вот это находка!$B$BПрямо здесь... точно в том месте, как было записано в моих заметках.$B$BЕсли нам повезет, в этой комнате мы обнаружим подсказки, где искать легендарный саркофаг Предвестья.$B$BДа, $n. Он существует на самом деле. Это не миф. Он реален!$B$BЯ тебе все расскажу, но чуть позже. А сейчас помоги мне с взрывчаткой.','Помогите Харрисону Джонсу войти в гробницу Хартута.','Ну вот...$B$BИ так каждый раз...','Поговорите с Харрисоном Джонсом у Обелиска Звезд.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Преждевременный взрыв',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот это находка!$B$BПрямо здесь... точно в том месте, как было записано в моих заметках.$B$BЕсли нам повезет, в этой комнате мы обнаружим подсказки, где искать легендарный саркофаг Предвестья.$B$BДа, $n. Он существует на самом деле. Это не миф. Он реален!$B$BЯ тебе все расскажу, но чуть позже. А сейчас помоги мне с взрывчаткой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Помогите Харрисону Джонсу войти в гробницу Хартута.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну вот...$B$BИ так каждый раз...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Харрисоном Джонсом у Обелиска Звезд.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27142,'Рас Ледяной Шепот – лич','Один из самых доверенных учеников Кел\'Тузада следит за операциями в Некроситете. Тебе придется сразиться с личом Расом Ледяным Шепотом в его логове. Дверь в его лабораторию находится рядом с демонстрационной комнатой.$B$BУничтожь его, $n. Преврати в пыль – чтобы никогда боле не мог он творить в нашем мире такие ужасы.','Уничтожьте Раса Ледяного Шепота.','Вернитесь к Алексию Барову.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рас Ледяной Шепот – лич',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Один из самых доверенных учеников Кел\'Тузада следит за операциями в Некроситете. Тебе придется сразиться с личом Расом Ледяным Шепотом в его логове. Дверь в его лабораторию находится рядом с демонстрационной комнатой.$B$BУничтожь его, $n. Преврати в пыль – чтобы никогда боле не мог он творить в нашем мире такие ужасы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте Раса Ледяного Шепота.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Алексию Барову.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (27142,'Ten thousand souls cry out in unison, $n! You have struck a mortal blow to the Scourge and their masters.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ten thousand souls cry out in unison, $n! You have struck a mortal blow to the Scourge and their masters.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27143,'Сокровище Баровых','В стенах Некроситета хранится сокровище Баровых. Мы с Алексием последние представители этой семьи.$B$BОднако я – последний живой Баров, так что вся империя нашей семьи принадлежит мне! Найди мне документы на Каэр Дарроу, Брилл, мельницу Таррен и Южнобережье, и я щедро награжу тебя. Имение Баровых в конце концов будет восстановлено!','Добудьте документы на Каэр Дэрроу, Брилл, мельницу Таррен и Южнобережье.','Вернитесь к Вэлдону Барову.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сокровище Баровых',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В стенах Некроситета хранится сокровище Баровых. Мы с Алексием последние представители этой семьи.$B$BОднако я – последний живой Баров, так что вся империя нашей семьи принадлежит мне! Найди мне документы на Каэр Дарроу, Брилл, мельницу Таррен и Южнобережье, и я щедро награжу тебя. Имение Баровых в конце концов будет восстановлено!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте документы на Каэр Дэрроу, Брилл, мельницу Таррен и Южнобережье.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Вэлдону Барову.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (27143,'Excellent work, $R. Alexi deserves nothing for his foolishness.','Bow your head in my presence, $R. I am a noble, after all, and you are a copperless peasant.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Excellent work, $R. Alexi deserves nothing for his foolishness.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Bow your head in my presence, $R. I am a noble, after all, and you are a copperless peasant.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27144,'Расплата','Ты отлично $gпотрудился:потрудилась;. Отрекшиеся гордятся тобой. Чего не скажешь о нашем генерале Кольтире Ткаче Смерти.$B$BЯ собираюсь поговорить с этим рыцарем смерти. Он себя опозорил.','Поприсутствуйте при разговоре леди Сильваны Ветрокрылой с Кольтирой Ткачом Смерти.','Я ничего не имею против Рыцарей Черного Клинка, однако Кольтире нужно напомнить, на кого он работает. Он обязан хранить верность Орде.$B$BИ в частности Отрекшимся.$B$BНе думаю, что скоро захочу с ним увидеться. Теперь, когда он у меня в руках... Можно не беспокоиться о его связях с Альянсом.','Вернитесь к леди Сильване Ветрокрылой в Андорал в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Расплата',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты отлично $gпотрудился:потрудилась;. Отрекшиеся гордятся тобой. Чего не скажешь о нашем генерале Кольтире Ткаче Смерти.$B$BЯ собираюсь поговорить с этим рыцарем смерти. Он себя опозорил.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поприсутствуйте при разговоре леди Сильваны Ветрокрылой с Кольтирой Ткачом Смерти.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я ничего не имею против Рыцарей Черного Клинка, однако Кольтире нужно напомнить, на кого он работает. Он обязан хранить верность Орде.$B$BИ в частности Отрекшимся.$B$BНе думаю, что скоро захочу с ним увидеться. Теперь, когда он у меня в руках... Можно не беспокоиться о его связях с Альянсом.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к леди Сильване Ветрокрылой в Андорал в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27145,'Зачумленные детеныши драконов','Один из "проектов", над которым работают наши недруги, заключается в зачумлении драконов. Пока это всего лишь детеныши, но когда они вырастут, станут мощнейшим оружием Плети, серьезной угрозой всему Азероту – и особенно моим родным землям! Надо немедленно принимать меры!$B$BУбей десятерых зачумленных детенышей. И самое главное – уничтожь Громоклина. Ты найдешь его в маленькой комнате под помещением, где содержат детенышей драконов, – он готовит какие-то добавки для стимуляции их роста. И поторопись... чем старше дракончики, тем сложнее с ними справиться.','Убейте Громоклина и 10 зачумленных детенышей драконов.','Вернитесь к Вэлдону Барову.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зачумленные детеныши драконов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Один из "проектов", над которым работают наши недруги, заключается в зачумлении драконов. Пока это всего лишь детеныши, но когда они вырастут, станут мощнейшим оружием Плети, серьезной угрозой всему Азероту – и особенно моим родным землям! Надо немедленно принимать меры!$B$BУбей десятерых зачумленных детенышей. И самое главное – уничтожь Громоклина. Ты найдешь его в маленькой комнате под помещением, где содержат детенышей драконов, – он готовит какие-то добавки для стимуляции их роста. И поторопись... чем старше дракончики, тем сложнее с ними справиться.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Громоклина и 10 зачумленных детенышей драконов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Вэлдону Барову.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (27145,'Well done, $n! It\'ll be a long time before they can grow another clutch of dragons.$B$B...At least, I hope it will!') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Well done, $n! It\'ll be a long time before they can grow another clutch of dragons.$B$B...At least, I hope it will!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27146,'Доктор Теолен Крастинов по прозвищу Мясник','На совести доктора Теолена Крастинова тысячи смертей. Он вполне заслужил свое прозвище – Мясник, ибо испытывает удовольствие от мучений других. Его необходимо наказать, правосудие должно свершиться.$B$BНайди его, и пусть он на себе испытает те муки, которым подвергал тысячи невинных, включая нас с супругом. Как только он погибнет, сожги наши останки. Преврати их в пепел, $n. Освободи наши страдающие души.','Уничтожьте доктора Теолена Крастинова, затем сожгите останки Евы и Люсьена Саркоффов.','Вернитесь к Еве Саркофф.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Доктор Теолен Крастинов по прозвищу Мясник',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На совести доктора Теолена Крастинова тысячи смертей. Он вполне заслужил свое прозвище – Мясник, ибо испытывает удовольствие от мучений других. Его необходимо наказать, правосудие должно свершиться.$B$BНайди его, и пусть он на себе испытает те муки, которым подвергал тысячи невинных, включая нас с супругом. Как только он погибнет, сожги наши останки. Преврати их в пепел, $n. Освободи наши страдающие души.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте доктора Теолена Крастинова, затем сожгите останки Евы и Люсьена Саркоффов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Еве Саркофф.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (27146,'I can feel my spirit healing, $n. You have done my husband and I a great service.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','I can feel my spirit healing, $n. You have done my husband and I a great service.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27147,'Киртонос Глашатай','Киртоноса можно вызвать с помощью крови. И она же поможет его уничтожить.$B$BВ Чертоге Призыва ты найдешь жаровню. Капни на нее каплю своей собственной крови. Придет Киртонос – устоять не сможет. И вот когда он появится, напусти на него гнев и ярость тысячи безвинно погибших.$B$BЕсли ты уничтожишь Киртоноса, мы будем безмерно тебе благодарны.','Уничтожьте Киртоноса.','Вернитесь к Еве Саркофф.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Киртонос Глашатай',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Киртоноса можно вызвать с помощью крови. И она же поможет его уничтожить.$B$BВ Чертоге Призыва ты найдешь жаровню. Капни на нее каплю своей собственной крови. Придет Киртонос – устоять не сможет. И вот когда он появится, напусти на него гнев и ярость тысячи безвинно погибших.$B$BЕсли ты уничтожишь Киртоноса, мы будем безмерно тебе благодарны.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте Киртоноса.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Еве Саркофф.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27148,'Последний звонок','Темный магистр Гандлинг – ректор Некроситета, и именно он отвечает за все те бессчетные смерти и зло, которое творят студенты этой проклятой школы. То, что он делает, – преступно. И должен понести наказание.$B$BПросто так он не выйдет. Его надо выманить. Для этого тебе придется убить шестерых профессоров, чьи классы находятся рядом с его кабинетом. Но будь $gосторожен:осторожна;: когда прикончишь последнего профессора, Гандлинг придет в ярость и обрушит на тебя всю силу своей темной магии. Не дай ему уйти живым.','Уничтожьте темного магистра Гандлинга.','Вернитесь к Люсьену Саркоффу.','Не жалей его.','Темный магистр Гандлинг') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Последний звонок',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Темный магистр Гандлинг – ректор Некроситета, и именно он отвечает за все те бессчетные смерти и зло, которое творят студенты этой проклятой школы. То, что он делает, – преступно. И должен понести наказание.$B$BПросто так он не выйдет. Его надо выманить. Для этого тебе придется убить шестерых профессоров, чьи классы находятся рядом с его кабинетом. Но будь $gосторожен:осторожна;: когда прикончишь последнего профессора, Гандлинг придет в ярость и обрушит на тебя всю силу своей темной магии. Не дай ему уйти живым.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте темного магистра Гандлинга.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Люсьену Саркоффу.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Не жалей его.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Темный магистр Гандлинг',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27149,'Школа проклятых','Мое почтение! Как видишь, Западные Чумные земли уже почти освободились от Плети. Однако здесь до сих пор функционирует Некроситет, школа некромантов, где юные заблудшие души изучают темные искусства и готовятся стать чародеями Плети! Мы уже многое сделали для спасения этого края, но все наши старания будут напрасны, если не остановить приток новых сил некромантии – причем сил достаточно мощных.$B$BОтправляйся на юго-восток, в Некроситет, и разыщи Вэлдона Барова. Он последний из рода Баровых, бывших владельцев этих земель, а в данный момент – наш связной.','Поговорите с Вэлдоном Баровым в Некроситете.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Школа проклятых',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мое почтение! Как видишь, Западные Чумные земли уже почти освободились от Плети. Однако здесь до сих пор функционирует Некроситет, школа некромантов, где юные заблудшие души изучают темные искусства и готовятся стать чародеями Плети! Мы уже многое сделали для спасения этого края, но все наши старания будут напрасны, если не остановить приток новых сил некромантии – причем сил достаточно мощных.$B$BОтправляйся на юго-восток, в Некроситет, и разыщи Вэлдона Барова. Он последний из рода Баровых, бывших владельцев этих земель, а в данный момент – наш связной.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Вэлдоном Баровым в Некроситете.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27150,'Участок Целителей Земли','Вероятно, битва за Андорал скоро снова разгорится. А ты тем временем, может быть, захочешь остаться здесь и отточить свои классовые навыки, |3-6($c).$B$BК востоку отсюда расположена большая ферма, которую заняли представители Серебряного Рассвета и Круга Кенария. Не сомневаюсь, у них найдется для тебя работа.','Сообщите о своем прибытии агенту ШРУ Каартишу на Участке Целителей Земли в Западных Чумных землях.','Поговорите с агентом ШРУ Каартишем на Участке Целителей Земли в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Участок Целителей Земли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вероятно, битва за Андорал скоро снова разгорится. А ты тем временем, может быть, захочешь остаться здесь и отточить свои классовые навыки, |3-6($c).$B$BК востоку отсюда расположена большая ферма, которую заняли представители Серебряного Рассвета и Круга Кенария. Не сомневаюсь, у них найдется для тебя работа.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сообщите о своем прибытии агенту ШРУ Каартишу на Участке Целителей Земли в Западных Чумных землях.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с агентом ШРУ Каартишем на Участке Целителей Земли в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (27151,'Наследство Телана Фордринга','Приветствую. Как дела? Меня зовут Дария.$B$BЯ одна из жриц, ответственных за сохранение мира в Дольном Очаге. В мои обязанности входит уход за башней, что расположена вниз по дороге, к юго-востоку от Дольного Очага. Эта башня имеет большое значение для верховного лорда. Это место, где погиб его сын.$B$BНо после недавнего набега гноллов попасть в башню затруднительно. Ты поможешь мне очистить дорогу от этих вандалов, чтобы я смогла выполнить свои обязанности?','Убейте 10 мародеров из племени Красной Сосны.','Вернитесь к Дарии Ла Рейн в Дольный Очаг в Западных Чумных землях.','Надеюсь, ты не станешь возражать, если я буду следить за тобой с помощью заклинания внутреннего зрения.','Дария Ла Рейн') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наследство Телана Фордринга',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приветствую. Как дела? Меня зовут Дария.$B$BЯ одна из жриц, ответственных за сохранение мира в Дольном Очаге. В мои обязанности входит уход за башней, что расположена вниз по дороге, к юго-востоку от Дольного Очага. Эта башня имеет большое значение для верховного лорда. Это место, где погиб его сын.$B$BНо после недавнего набега гноллов попасть в башню затруднительно. Ты поможешь мне очистить дорогу от этих вандалов, чтобы я смогла выполнить свои обязанности?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 мародеров из племени Красной Сосны.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дарии Ла Рейн в Дольный Очаг в Западных Чумных землях.',`completedtext_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Надеюсь, ты не станешь возражать, если я буду следить за тобой с помощью заклинания внутреннего зрения.',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Дария Ла Рейн',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (27152,'Необычное поведение... Даже для гноллов','Дай мне минутку собраться с мыслями.$B$B<Вы ощущаете, что разум Дарии блуждает где-то, а затем снова возвращается к вам.>$B$BДальше по следу, к югу от Башни Телана, к востоку от главной дороги гноллы устроили местечко для своих сборищ. И там что-то происходит... не могу сказать, что именно. Надо разведать. Я буду высматривать все необычное... а ты... просто защищайся.','Исследуйте укрытие гноллов возле пути на Дольный Очаг в западных Чумных землях.','Лагерь гноллов обследован','Вернитесь к Дарии Ла Рейн в Дольный Очаг в Западных Чумных землях.','Гноллы – такое бельмо на глазу...','Дария Ла Рейн','Видишь это? Эта бутылка, припасы, все на земле!','Дария Ла Рейн') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Необычное поведение... Даже для гноллов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Дай мне минутку собраться с мыслями.$B$B<Вы ощущаете, что разум Дарии блуждает где-то, а затем снова возвращается к вам.>$B$BДальше по следу, к югу от Башни Телана, к востоку от главной дороги гноллы устроили местечко для своих сборищ. И там что-то происходит... не могу сказать, что именно. Надо разведать. Я буду высматривать все необычное... а ты... просто защищайся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Исследуйте укрытие гноллов возле пути на Дольный Очаг в западных Чумных землях.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Лагерь гноллов обследован',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дарии Ла Рейн в Дольный Очаг в Западных Чумных землях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Гноллы – такое бельмо на глазу...',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Дария Ла Рейн',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Видишь это? Эта бутылка, припасы, все на земле!',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Дария Ла Рейн',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (27153,'Цвет Дольного Очага','Видишь эти реагенты? А те припасы? Все это – собственность Серебряного Авангарда.$B$BГноллы известные воришки, но, насколько я знаю, после появления в Дольном Очаге Красной Сосны краж не наблюдалось.$B$BУ меня в Дольном Очаге несколько хороших знакомых: Моррис Вант, галантерейщик Менделев, Бри Железняк и верховный священник Альфус. Они в курсе всего происходящего и вполне заслуживают доверия. Поговори с ними и попытайся разузнать что-нибудь о пропавших запасах.','Поговорите с Моррисом Вантом, галантерейщиком Менделевым, Бри Железняк и верховным священником Альфусом в Дольном Очаге.','Вернитесь к Дарии Ла Рейн в Дольный Очаг в Западных Чумных землях.','Вернись в город и добудь сведения.','Дария Ла Рейн','Бисп – наше все.','Дария Ла Рейн') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Цвет Дольного Очага',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Видишь эти реагенты? А те припасы? Все это – собственность Серебряного Авангарда.$B$BГноллы известные воришки, но, насколько я знаю, после появления в Дольном Очаге Красной Сосны краж не наблюдалось.$B$BУ меня в Дольном Очаге несколько хороших знакомых: Моррис Вант, галантерейщик Менделев, Бри Железняк и верховный священник Альфус. Они в курсе всего происходящего и вполне заслуживают доверия. Поговори с ними и попытайся разузнать что-нибудь о пропавших запасах.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Моррисом Вантом, галантерейщиком Менделевым, Бри Железняк и верховным священником Альфусом в Дольном Очаге.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дарии Ла Рейн в Дольный Очаг в Западных Чумных землях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Вернись в город и добудь сведения.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Дария Ла Рейн',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Бисп – наше все.',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Дария Ла Рейн',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (27154,'Разборка с Биспом','Волхв Бисп – один из величайших чародеев Дольного Очага. Представь себе, он якшается с гноллами... Да еще и увлекается некромантией. Невообразимо.$B$BТы найдешь его на вершине башни магов рядом с главными воротами Дольного Очага. Надеюсь, он объяснит все это. А если нет, что ж... И... я бы не ходила на вершину этой башни, не подготовившись как следует, $n.','Поговорите с волхвом Биспом на вершине башни магов в Дольном Очаге.','Вернитесь к Дарии Ла Рейн в Дольный Очаг в Западных Чумных землях.','Надеюсь, можно избежать схватки с Биспом. Он чрезвычайно сильный противник.','Дария Ла Рейн','Бисп, гноллы, некромантия... Кошмар!','Дария Ла Рейн') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разборка с Биспом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Волхв Бисп – один из величайших чародеев Дольного Очага. Представь себе, он якшается с гноллами... Да еще и увлекается некромантией. Невообразимо.$B$BТы найдешь его на вершине башни магов рядом с главными воротами Дольного Очага. Надеюсь, он объяснит все это. А если нет, что ж... И... я бы не ходила на вершину этой башни, не подготовившись как следует, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с волхвом Биспом на вершине башни магов в Дольном Очаге.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дарии Ла Рейн в Дольный Очаг в Западных Чумных землях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Надеюсь, можно избежать схватки с Биспом. Он чрезвычайно сильный противник.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Дария Ла Рейн',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Бисп, гноллы, некромантия... Кошмар!',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Дария Ла Рейн',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27155,'Явка с повинной','Что ж... Ты $gубил:убила; в Дольном Очаге представителя Серебряного Авангарда. А такое не прощается, даже если это была самозащита.$B$BСоветую тебе пойти в крепость Марденхольд с повинной – обратись к верховному лорду Фордрингу. Возможно, выслушав твое объяснение, он проявит милосердие. Надеюсь, все это не обернется для тебя серьезными неприятностями...','Отправляйтесь к верховному лорду Тириону Фордрингу в Дольный Очаг в Западных Чумных землях.','Отправляйтесь к верховному лорду Тириону Фордрингу в Дольный Очаг в Западных Чумных землях.','Тебе лучше лично поговорить с Тирионом, пока он не узнал обо всем от других.','Дария Ла Рейн') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Явка с повинной',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что ж... Ты $gубил:убила; в Дольном Очаге представителя Серебряного Авангарда. А такое не прощается, даже если это была самозащита.$B$BСоветую тебе пойти в крепость Марденхольд с повинной – обратись к верховному лорду Фордрингу. Возможно, выслушав твое объяснение, он проявит милосердие. Надеюсь, все это не обернется для тебя серьезными неприятностями...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь к верховному лорду Тириону Фордрингу в Дольный Очаг в Западных Чумных землях.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отправляйтесь к верховному лорду Тириону Фордрингу в Дольный Очаг в Западных Чумных землях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Тебе лучше лично поговорить с Тирионом, пока он не узнал обо всем от других.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Дария Ла Рейн',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27156,'Самое время!','Наконец-то! Ты здесь! Берись за дело!$B$BСлишком долго мои бойцы тренировались на этих деревянных манекенах. Пора им узнать, каково драться в настоящем бою с настоящим противником.$B$BХм... Я просил, чтобы прислали кого-нибудь повнушительней. Ладно, думаю, сойдет и такой задохлик |3-6($r) |3-6($c), как ты.$B$BИди туда и научи моих солдат сражаться!','Бросьте вызов 7 рекрутами Дольного Очага и победите их.','Вернитесь к лейтенанту Майнеру в Дольный Очаг в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Самое время!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наконец-то! Ты здесь! Берись за дело!$B$BСлишком долго мои бойцы тренировались на этих деревянных манекенах. Пора им узнать, каково драться в настоящем бою с настоящим противником.$B$BХм... Я просил, чтобы прислали кого-нибудь повнушительней. Ладно, думаю, сойдет и такой задохлик |3-6($r) |3-6($c), как ты.$B$BИди туда и научи моих солдат сражаться!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Бросьте вызов 7 рекрутами Дольного Очага и победите их.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лейтенанту Майнеру в Дольный Очаг в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27157,'Помеха рудокопам','Эй, как там тебя... Всегда забываю, как тебя зовут. $n? Душевно рад встрече, $n.$B$BУ меня тут возникла некая заковыка... а на тебя посмотришь – сразу ясно, что умеешь находить выход из всяких ситуевин.$B$BНа северной окраине Дольного Очага есть один небольшой рудник – там добывают почти всю руду для городских нужд. Мои рудокопы хорошие работники, свое дело знают.$B$BНо вот незадача: в руднике, кажется, поселилась огромная паучиха. Очень, знаешь ли, мешает работе. Сможешь убить эту тварь?','Убейте Шадрил в руднике в Дольном Очаге.','Славно сработано! Как удачно ты тут оказался... даже не знаю, что бы я без тебя делал.','Вернитесь к лейтенанту Майнеру в Дольный Очаг в Западных Чумных землях.','Я им плачу не за то, чтобы они пауков боялись... а за работу!','Шадрил') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Помеха рудокопам',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эй, как там тебя... Всегда забываю, как тебя зовут. $n? Душевно рад встрече, $n.$B$BУ меня тут возникла некая заковыка... а на тебя посмотришь – сразу ясно, что умеешь находить выход из всяких ситуевин.$B$BНа северной окраине Дольного Очага есть один небольшой рудник – там добывают почти всю руду для городских нужд. Мои рудокопы хорошие работники, свое дело знают.$B$BНо вот незадача: в руднике, кажется, поселилась огромная паучиха. Очень, знаешь ли, мешает работе. Сможешь убить эту тварь?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Шадрил в руднике в Дольном Очаге.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Славно сработано! Как удачно ты тут оказался... даже не знаю, что бы я без тебя делал.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лейтенанту Майнеру в Дольный Очаг в Западных Чумных землях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Я им плачу не за то, чтобы они пауков боялись... а за работу!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Шадрил',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27158,'Битва за Андорал','Скорее, $n... У нас совсем нет времени.$B$BАндорал в самом эпицентре войны между Отрекшимися, Альянсом и Плетью. Король Ринн рискнул и поставил во главе своих войск рыцаря смерти. Однако я уверен, что он не откажется от любой помощи. Теперь, когда Артас мертв, Альянс пойдет на Лордерон.$B$BКогда будешь $gготов:готова;, поговори с укротителем грифонов Бибильфасом Перосвистом, чтобы тот отправил тебя в первую битву.','Отчитайтесь перед Тассарианом в Андорале в Западных Чумных землях.','Поговорите с Тассарианом в Андорале в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Битва за Андорал',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Скорее, $n... У нас совсем нет времени.$B$BАндорал в самом эпицентре войны между Отрекшимися, Альянсом и Плетью. Король Ринн рискнул и поставил во главе своих войск рыцаря смерти. Однако я уверен, что он не откажется от любой помощи. Теперь, когда Артас мертв, Альянс пойдет на Лордерон.$B$BКогда будешь $gготов:готова;, поговори с укротителем грифонов Бибильфасом Перосвистом, чтобы тот отправил тебя в первую битву.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отчитайтесь перед Тассарианом в Андорале в Западных Чумных землях.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Тассарианом в Андорале в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27159,'Сначала Плеть... Потом Орда','Армию Плети здесь, в Андорале, ведет в атаку Темный магистр Гандлинг из культа Проклятых. Войска Отрекшихся возглавляет мой давний знакомый – Кольтира. Если мы хотим выиграть битву за Андорал, нужно победить обоих – только по очереди.$B$BЯ хорошо знаю Кольтиру и уверен, что первым делом он возьмется за Плеть. Мы поступим так же.$B$BРасправься с теми воинами Плети, что послабее. Нужно проредить их ряды. А потом придет очередь Отрекшихся.','Уничтожьте 15 иссохших воинов Плети в Андорале.','Ты не особо прыток, но, по крайней мере, с делом справился.$B$BОчень хорошо. У меня для тебя, Теролекс, потом будет еще одно задание, уже поважнее.','Вернитесь к Тассариану в Андорал, что в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сначала Плеть... Потом Орда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Армию Плети здесь, в Андорале, ведет в атаку Темный магистр Гандлинг из культа Проклятых. Войска Отрекшихся возглавляет мой давний знакомый – Кольтира. Если мы хотим выиграть битву за Андорал, нужно победить обоих – только по очереди.$B$BЯ хорошо знаю Кольтиру и уверен, что первым делом он возьмется за Плеть. Мы поступим так же.$B$BРасправься с теми воинами Плети, что послабее. Нужно проредить их ряды. А потом придет очередь Отрекшихся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 15 иссохших воинов Плети в Андорале.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты не особо прыток, но, по крайней мере, с делом справился.$B$BОчень хорошо. У меня для тебя, Теролекс, потом будет еще одно задание, уже поважнее.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тассариану в Андорал, что в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27160,'Боевые машины','Иссохшие воины Плети... слабы. Чудовища... сильны.$B$BПобедим чудовищ... выиграем войну.','Уничтожьте 6 пустобрюхих громадин в Андорале.','Чудовища... сильны.$B$BТеролекс... сильнее.','Вернитесь к Луриду в Андорал в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Боевые машины',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Иссохшие воины Плети... слабы. Чудовища... сильны.$B$BПобедим чудовищ... выиграем войну.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 6 пустобрюхих громадин в Андорале.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Чудовища... сильны.$B$BТеролекс... сильнее.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Луриду в Андорал в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27161,'Бесконечный поток','Араж Призыватель усиливает оборону Плети простыми скелетами... эта армия слабаков задавит если не силой, так числом. Он созывает души в северных башнях Андорала, и оттуда скелеты извергаются в чудовищных количествах. Но я знаю, как выйти из ситуации!$B$B<Ланг передает вам несколько гранат.>$B$BДействуют они просто. Бросаешь в костяного стража Плети... ну или в толпу скелетов... и они разлетаются на мелкие косточки.','Подорвите 5 костяных берсерков и уничтожьте костяного стража Плети ручными гранатами Ланга.','Эти гранаты просто взрывчатка, не более. Может, я и не гоблинский инженер... но понимаю, как важно уметь время от времени взрывать всякие вещи.','Вернитесь к Лангу Разболтайлу в Андорал в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бесконечный поток',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Араж Призыватель усиливает оборону Плети простыми скелетами... эта армия слабаков задавит если не силой, так числом. Он созывает души в северных башнях Андорала, и оттуда скелеты извергаются в чудовищных количествах. Но я знаю, как выйти из ситуации!$B$B<Ланг передает вам несколько гранат.>$B$BДействуют они просто. Бросаешь в костяного стража Плети... ну или в толпу скелетов... и они разлетаются на мелкие косточки.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Подорвите 5 костяных берсерков и уничтожьте костяного стража Плети ручными гранатами Ланга.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Эти гранаты просто взрывчатка, не более. Может, я и не гоблинский инженер... но понимаю, как важно уметь время от времени взрывать всякие вещи.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лангу Разболтайлу в Андорал в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27162,'Некроректор','Некроситет – одна из немногих цитаделей Плети, оставшихся к западу от Тондрорила. Ректор Некроситета, сектант по имени темный магистр Гандлинг, появился на поле боя.$B$BЭто станет его последней ошибкой.$B$BТы найдешь этого самого Гандлинга на площади возле южной окраины города. Сразись с ним и измотай до крайности. А я помогу его прикончить.','Убейте в Андорале темного магистра Гандлинга.','Блестящая работа, Теролекс. А теперь, когда предводитель Плети изгнан из Андорала, мы будем ждать подходящего момента.','Вернитесь к Тассариану в Андорал, что в Западных Чумных землях.','Ректор Некроситета, предводитель Плети в Андорале','Темный магистр Гандлинг') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Некроректор',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Некроситет – одна из немногих цитаделей Плети, оставшихся к западу от Тондрорила. Ректор Некроситета, сектант по имени темный магистр Гандлинг, появился на поле боя.$B$BЭто станет его последней ошибкой.$B$BТы найдешь этого самого Гандлинга на площади возле южной окраины города. Сразись с ним и измотай до крайности. А я помогу его прикончить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте в Андорале темного магистра Гандлинга.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Блестящая работа, Теролекс. А теперь, когда предводитель Плети изгнан из Андорала, мы будем ждать подходящего момента.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тассариану в Андорал, что в Западных Чумных землях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Ректор Некроситета, предводитель Плети в Андорале',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Темный магистр Гандлинг',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27163,'Грубая сила','Гандлинг привел с собой своего лейтенанта, Громоклина. Этот лязгающий кошмар куда опаснее, чем любой из воинов Плети, что встретятся тебе на поле боя... даже опаснее, чем поганища.$B$BТы найдешь Громоклина в старом здании ратуши неподалеку от центра города. Советую хорошенько подготовиться к схватке,$n. Этого нахрапом не возьмешь.','Убейте Громоклина в Андорале.','Прекрасно, Теролекс.','Вернитесь к Тассариану в Андорал, что в Западных Чумных землях.','За пределами Некроситета Громоклин слабее... но он по-прежнему могуч.','Громоклин') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Грубая сила',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Гандлинг привел с собой своего лейтенанта, Громоклина. Этот лязгающий кошмар куда опаснее, чем любой из воинов Плети, что встретятся тебе на поле боя... даже опаснее, чем поганища.$B$BТы найдешь Громоклина в старом здании ратуши неподалеку от центра города. Советую хорошенько подготовиться к схватке,$n. Этого нахрапом не возьмешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Громоклина в Андорале.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно, Теролекс.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тассариану в Андорал, что в Западных Чумных землях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','За пределами Некроситета Громоклин слабее... но он по-прежнему могуч.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Громоклин',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27164,'Араж Призыватель','Теперь, когда с врагом покончено, пришло время разобраться с самим Аражем и воспользоваться его оберегом. Ты, наверное, его уже $gвидел:видела; где-нибудь у фонтана в центре города.$B$BПрихвати с собой мои гранаты. С Аражем справиться они не помогут, но весьма пригодятся, если он вызовет своих скелетов.','Убейте Аража Призывателя. С костяными берсерками справляйтесь с помощью ручных гранат Ланга.','Араж мертв... Отличная новость. Этот гном внес свой вклад в наш успех в этой войне. Так же, как и ты, Теролекс.','Араж очень сильный соперник. Так что приготовься.','Вернитесь к Тассариану в Андорал, что в Западных Чумных землях.','Не забудь, мои гранаты помогут справиться с этими скелетами!','Араж Призыватель') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Араж Призыватель',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда с врагом покончено, пришло время разобраться с самим Аражем и воспользоваться его оберегом. Ты, наверное, его уже $gвидел:видела; где-нибудь у фонтана в центре города.$B$BПрихвати с собой мои гранаты. С Аражем справиться они не помогут, но весьма пригодятся, если он вызовет своих скелетов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Аража Призывателя. С костяными берсерками справляйтесь с помощью ручных гранат Ланга.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Араж мертв... Отличная новость. Этот гном внес свой вклад в наш успех в этой войне. Так же, как и ты, Теролекс.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Араж очень сильный соперник. Так что приготовься.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тассариану в Андорал, что в Западных Чумных землях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Не забудь, мои гранаты помогут справиться с этими скелетами!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Араж Призыватель',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27165,'Сиюминутная победа','Альянс одержал победу, наши позиции крепки. И теперь, когда Отрекшиеся ослабли и потеряли бдительность, нам нужно нанести удар. Но я заключил сделку...$B$BМы подождем. Атакуем войско Кольтиры в свое время. Поговори с Джинни Гудвин, а потом лети в Лагерь Промозглого Ветра, что к югу отсюда. Следующее задание тебе даст командир Ашлам Неутомимый.$B$BЯ сообщу, когда вновь понадобится вернуться в Андорал.','Доберитесь до командира Ашлама Неутомимого в лагере Промозглого Ветра в Западных Чумных землях.','Вести прибыли чуть раньше тебя, Турбомажка. Теперь, когда Плеть изгнана из Андорала, мы стали на шаг ближе к возвращению Лордерона.','Доберитесь до командира Ашлама Неутомимого в лагере Промозглого Ветра в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сиюминутная победа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Альянс одержал победу, наши позиции крепки. И теперь, когда Отрекшиеся ослабли и потеряли бдительность, нам нужно нанести удар. Но я заключил сделку...$B$BМы подождем. Атакуем войско Кольтиры в свое время. Поговори с Джинни Гудвин, а потом лети в Лагерь Промозглого Ветра, что к югу отсюда. Следующее задание тебе даст командир Ашлам Неутомимый.$B$BЯ сообщу, когда вновь понадобится вернуться в Андорал.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доберитесь до командира Ашлама Неутомимого в лагере Промозглого Ветра в Западных Чумных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вести прибыли чуть раньше тебя, Турбомажка. Теперь, когда Плеть изгнана из Андорала, мы стали на шаг ближе к возвращению Лордерона.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доберитесь до командира Ашлама Неутомимого в лагере Промозглого Ветра в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27166,'Перышки!','Мы всегда должны быть готовы к бою, $n. И не важно, битва это с Отрекшимися в Андорале, Плетью на востоке или с каким-то неизвестным врагом. Точно известно одно: надо быть наготове.$B$BНо сейчас у нас не хватает стрел. Древки и наконечники я достать могу, но вот перьев у меня нет. В это время года как раз линяют птицы, обитающие на северо-западе. Не $gмог:могла; бы ты прогуляться в те места и собрать немного перьев для нашего лагеря?','Раздобудьте 9 перьев бурокрылого ястреба.','Я велю нашим мастерам приниматься за работу.$B$BМне очень приятно, что ты так быстро согласился выполнить это задание, Теролекс. Возможно, потом я найду тебе дело поинтереснее.','Приятно снова видеть тебя, Теролекс.','Вернитесь к Ашламу Неутомимому в лагерь Промозглого Ветра в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Перышки!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы всегда должны быть готовы к бою, $n. И не важно, битва это с Отрекшимися в Андорале, Плетью на востоке или с каким-то неизвестным врагом. Точно известно одно: надо быть наготове.$B$BНо сейчас у нас не хватает стрел. Древки и наконечники я достать могу, но вот перьев у меня нет. В это время года как раз линяют птицы, обитающие на северо-западе. Не $gмог:могла; бы ты прогуляться в те места и собрать немного перьев для нашего лагеря?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте 9 перьев бурокрылого ястреба.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я велю нашим мастерам приниматься за работу.$B$BМне очень приятно, что ты так быстро согласился выполнить это задание, Теролекс. Возможно, потом я найду тебе дело поинтереснее.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Приятно снова видеть тебя, Теролекс.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ашламу Неутомимому в лагерь Промозглого Ветра в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27167,'Угроза голодной смерти','Раздобудьте 5 кусков мяса косматых черных медведей в Западных Чумных землях.','Мы проделали долгий путь. Мы вовсе не привередливы и будем рады всему, что ты сумеешь для нас раздобыть.','Вернитесь к Турману Гранту в лагерь Промозглого Ветра в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Угроза голодной смерти',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте 5 кусков мяса косматых черных медведей в Западных Чумных землях.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мы проделали долгий путь. Мы вовсе не привередливы и будем рады всему, что ты сумеешь для нас раздобыть.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Турману Гранту в лагерь Промозглого Ветра в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27168,'Неприкаянные','Надеюсь, большинство из них ушло с миром. Благодарю тебя, Теролекс.','Вернитесь к верховной жрице Макдонелл в лагерь Промозглого Ветра в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Неприкаянные',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Надеюсь, большинство из них ушло с миром. Благодарю тебя, Теролекс.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховной жрице Макдонелл в лагерь Промозглого Ветра в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27169,'Благословение Утера','Крестьяне с юга хотят занять эти фермы, но я не могу позволить войти им в Чумные земли без подготовки. Хоть Плеть и ушла отсюда, опасность осталась – в лице Отрекшихся. Нет, мы должны готовиться к сражению... и наши новые гости тоже.$B$BНо прежде чем за что-то браться, советую тебе сходить к гробнице Утера на восток, преподнести подношение его статуе и попросить благословения. Когда закончишь – поговори со жрецом в гробнице.','Войдите в гробницу Утера и положите подношения лагеря Промозглого Ветра у его статуи.','Значит, вы с людьми из лагеря Промозглого Ветра хотите вернуть себе Андорал? Желаю вам удачи.','Явитесь к верховному жрецу Тель\'данису в гробницу Утера в Западных Чумных землях.','Он был одним из величайших паладинов Лордерона.','Утер Светоносный') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Благословение Утера',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Крестьяне с юга хотят занять эти фермы, но я не могу позволить войти им в Чумные земли без подготовки. Хоть Плеть и ушла отсюда, опасность осталась – в лице Отрекшихся. Нет, мы должны готовиться к сражению... и наши новые гости тоже.$B$BНо прежде чем за что-то браться, советую тебе сходить к гробнице Утера на восток, преподнести подношение его статуе и попросить благословения. Когда закончишь – поговори со жрецом в гробнице.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Войдите в гробницу Утера и положите подношения лагеря Промозглого Ветра у его статуи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Значит, вы с людьми из лагеря Промозглого Ветра хотите вернуть себе Андорал? Желаю вам удачи.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Явитесь к верховному жрецу Тель\'данису в гробницу Утера в Западных Чумных землях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Он был одним из величайших паладинов Лордерона.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Утер Светоносный',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27170,'Покинутая крипта','Если ты и впрямь хочешь поучаствовать в битве за Андорал... думаю, смогу помочь.$B$BК востоку отсюда есть большая крипта. Ее нижний уровень когда-то был складом оружия и доспехов... пока не пришла Плеть. Теперь, когда нежить оттуда ушла, до вооружения можно добраться.$B$BНаверняка по большей части все там проржавело и прогнило, но все лучше, чем рубахи и вилы.','Найдите ящик с оружием на нижнем уровне крипты в Западных Чумных землях.','Вы видите разбросанные там и сям по нижнему уровню крипты поломанные ящики, в которых когда-то хранились оружие и доспехи.$B$BПохоже, кто-то успел добраться сюда раньше вас.','Найдите ящик с оружием на нижнем уровне крипты в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Покинутая крипта',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если ты и впрямь хочешь поучаствовать в битве за Андорал... думаю, смогу помочь.$B$BК востоку отсюда есть большая крипта. Ее нижний уровень когда-то был складом оружия и доспехов... пока не пришла Плеть. Теперь, когда нежить оттуда ушла, до вооружения можно добраться.$B$BНаверняка по большей части все там проржавело и прогнило, но все лучше, чем рубахи и вилы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите ящик с оружием на нижнем уровне крипты в Западных Чумных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы видите разбросанные там и сям по нижнему уровню крипты поломанные ящики, в которых когда-то хранились оружие и доспехи.$B$BПохоже, кто-то успел добраться сюда раньше вас.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Найдите ящик с оружием на нижнем уровне крипты в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27171,'Засада!','Вы оборачиваетесь и видите на лестнице силуэты скелетов.$B$BНежить не ушла из этого склепа – просто затаилась и ждала! Более того, скелеты вооружены тем самым оружием, которое вы искали.$B$BВам придется выбираться из склепа, а по пути прихватить как можно больше деталей снаряжения.','Добудьте 4 износившихся кирасы и 4 ржавых меча.','Призраки напали? Странно. Вообще-то я предполагал, что этот склеп не до конца зачищен.$B$BТы едва не застал Турмана Гранта... помнишь, того неуклюжего фермера, что и прежде сюда приходил. Он взял своих ребят и отправился на ближайшую ферму... вопреки моим приказам.','Вернитесь к командиру Ашламу Неутомимому на берег Промозглого Ветра в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Засада!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы оборачиваетесь и видите на лестнице силуэты скелетов.$B$BНежить не ушла из этого склепа – просто затаилась и ждала! Более того, скелеты вооружены тем самым оружием, которое вы искали.$B$BВам придется выбираться из склепа, а по пути прихватить как можно больше деталей снаряжения.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 4 износившихся кирасы и 4 ржавых меча.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Призраки напали? Странно. Вообще-то я предполагал, что этот склеп не до конца зачищен.$B$BТы едва не застал Турмана Гранта... помнишь, того неуклюжего фермера, что и прежде сюда приходил. Он взял своих ребят и отправился на ближайшую ферму... вопреки моим приказам.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру Ашламу Неутомимому на берег Промозглого Ветра в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27172,'Удел Страданий','Эти фермеры перебрались в Удел Страданий – на старую ферму на северо-востоке за рекой. За ними надо присматривать.$B$BОтнеси им найденное тобой ржавое оружие и доспехи. Не вилами же им воевать.','Доставьте изношенное оружие и доспехи Турману Гранту в Удел Страданий в Западных Чумных землях.','Ладно, раз уж ты здесь, мы с радостью возьмем у тебя эти доспехи.$B$BА оружие можешь оставить себе. Эти люди не знают, за какой конец браться.','Тебя Неутомимый послал? Все ему неймется?','Поговорите с Турманом Грантом в Уделе Страданий в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Удел Страданий',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти фермеры перебрались в Удел Страданий – на старую ферму на северо-востоке за рекой. За ними надо присматривать.$B$BОтнеси им найденное тобой ржавое оружие и доспехи. Не вилами же им воевать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте изношенное оружие и доспехи Турману Гранту в Удел Страданий в Западных Чумных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ладно, раз уж ты здесь, мы с радостью возьмем у тебя эти доспехи.$B$BА оружие можешь оставить себе. Эти люди не знают, за какой конец браться.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебя Неутомимый послал? Все ему неймется?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Турманом Грантом в Уделе Страданий в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27173,'Это наша армия','Я сказал командиру Неутомимому, что мы твердо намерены удержать позиции. К тому же по пути сюда я перекинулся парой слов с генералом рыцарей смерти Тассарианом. Мы, фермеры, собираемся оказать им посильную помощь.$B$BЗаймем эту ферму и сделаем вид, что работаем. А когда начнется битва за Андорал, нападем на Отрекшихся с тыла. Такого они точно не ожидают.$B$BНо для начала нужно избавиться от всадников-Отрекшихся. Убей их и возвращайся ко мне.','Уничтожьте 10 всадников-Отрекшихся.','Вернитесь к Турману Гранту в Удел Страданий в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Это наша армия',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я сказал командиру Неутомимому, что мы твердо намерены удержать позиции. К тому же по пути сюда я перекинулся парой слов с генералом рыцарей смерти Тассарианом. Мы, фермеры, собираемся оказать им посильную помощь.$B$BЗаймем эту ферму и сделаем вид, что работаем. А когда начнется битва за Андорал, нападем на Отрекшихся с тыла. Такого они точно не ожидают.$B$BНо для начала нужно избавиться от всадников-Отрекшихся. Убей их и возвращайся ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 10 всадников-Отрекшихся.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Турману Гранту в Удел Страданий в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27174,'Боевые учения','Вообще-то ты можешь обучить несколько моих людей. Ведь $gзаметил:заметила; поганище? Мы пытались с ним драться, да только никакой реакции не дождались. Похоже, желает помогать на ферме.$B$BВозьми с собой четверых крестьян и заставь поганище вступить в драку. На первый взгляд страшно, конечно, но поганище одно, а вас будет пятеро – думаю, у вас есть шанс с ним справиться.','Поговорите с Жутким Рылом в Уделе Страданий и заставьте его драться.','Вернитесь к Турману Гранту в Удел Страданий в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Боевые учения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вообще-то ты можешь обучить несколько моих людей. Ведь $gзаметил:заметила; поганище? Мы пытались с ним драться, да только никакой реакции не дождались. Похоже, желает помогать на ферме.$B$BВозьми с собой четверых крестьян и заставь поганище вступить в драку. На первый взгляд страшно, конечно, но поганище одно, а вас будет пятеро – думаю, у вас есть шанс с ним справиться.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Жутким Рылом в Уделе Страданий и заставьте его драться.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Турману Гранту в Удел Страданий в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27175,'Участок Целителей Земли','У мужчин и женщин лагеря Промозглого Ветра благородные цели, но их конечная цель – война. Я же хочу предложить тебе возможность совершить более мирное деяние.$B$BНа Участке Целителей Земли, за пределами истерзанного войной Андорала, на севере вместе с Кругом Кенария собирает силы Серебряный Авангард. Все мы скоро начнем работу по исцелению этой земли от чумы, царившей здесь.$B$B$GГотов:Готова; ли ты присоединиться к нам, |3-6($c)?','Поговорите с агентом ШРУ Каартишем на Участке Целителей Земли в Чумных землях.','Поговорите с агентом ШРУ Каартишем на Участке Целителей Земли в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Участок Целителей Земли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У мужчин и женщин лагеря Промозглого Ветра благородные цели, но их конечная цель – война. Я же хочу предложить тебе возможность совершить более мирное деяние.$B$BНа Участке Целителей Земли, за пределами истерзанного войной Андорала, на севере вместе с Кругом Кенария собирает силы Серебряный Авангард. Все мы скоро начнем работу по исцелению этой земли от чумы, царившей здесь.$B$B$GГотов:Готова; ли ты присоединиться к нам, |3-6($c)?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с агентом ШРУ Каартишем на Участке Целителей Земли в Чумных землях.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с агентом ШРУ Каартишем на Участке Целителей Земли в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertargetname_loc8`) VALUES (27176,'Разыщите посох Султана и с помощью замысловатого диска превратите его в древко Звезд.','<Доктор Джонс надевает очки.>$B$BДавай-ка посмотрим, что это такое.','Да, Михалкен?','Отнесите посох Звезд Харрисону Джонсу к Обелиску Звезд.','Султан Уга') ON DUPLICATE KEY UPDATE `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите посох Султана и с помощью замысловатого диска превратите его в древко Звезд.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Доктор Джонс надевает очки.>$B$BДавай-ка посмотрим, что это такое.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да, Михалкен?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите посох Звезд Харрисону Джонсу к Обелиску Звезд.',`completedtext_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Султан Уга',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27177,'Спасательная операция','Орда и наги практически уничтожили наш флот. Мы не сможем вернуть воинов, утонувших в море, но пусть меня утопят, если я позволю погибнуть нашим припасам.$B$BПлыви на юго-запад от Высокого берега, к Обсидиановым рифам, и собери припасы с разбитых кораблей и со дна океана.','Найдите сохранившиеся припасы в Обсидиановых рифах. Достаньте 8 таких грузов из промокших ящиков.','Вот это да! Тебе удалось собрать гораздо больше, чем я думал. Этого хватит на целый отряд морских пехотинцев!$B$BСнаряжение у нас есть. Вот если бы нам удалось увеличить нашу численность здесь, на нагорье...','Сколько тебе удалось спасти?','Вернитесь на Высокий берег на Сумеречном нагорье и отдайте припасы Саймону Чендлеру.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спасательная операция',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Орда и наги практически уничтожили наш флот. Мы не сможем вернуть воинов, утонувших в море, но пусть меня утопят, если я позволю погибнуть нашим припасам.$B$BПлыви на юго-запад от Высокого берега, к Обсидиановым рифам, и собери припасы с разбитых кораблей и со дна океана.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите сохранившиеся припасы в Обсидиановых рифах. Достаньте 8 таких грузов из промокших ящиков.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот это да! Тебе удалось собрать гораздо больше, чем я думал. Этого хватит на целый отряд морских пехотинцев!$B$BСнаряжение у нас есть. Вот если бы нам удалось увеличить нашу численность здесь, на нагорье...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Сколько тебе удалось спасти?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь на Высокий берег на Сумеречном нагорье и отдайте припасы Саймону Чендлеру.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27178,'Наги спешат на помощь','Они поднялись из океанских глубин, $n. Наги. Кажется, они идут на помощь Сумеречному бастиону. Возможно, двинутся вверх по течению реки Вералл. Этого нельзя допустить!$B$BЗаставь их раз и навсегда понять, что теперь это наши земли, и загони обратно в мрачные глубины.$B$BУбей наг Черной Чешуи, которые идут через Обсидиановые рифы!','Убейте 10 мирмидонов из клана Черной Чешуи или зовущих море из клана Черной Чешуи.','Вернитесь к Саймону Чендлеру на Высокий берег на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наги спешат на помощь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Они поднялись из океанских глубин, $n. Наги. Кажется, они идут на помощь Сумеречному бастиону. Возможно, двинутся вверх по течению реки Вералл. Этого нельзя допустить!$B$BЗаставь их раз и навсегда понять, что теперь это наши земли, и загони обратно в мрачные глубины.$B$BУбей наг Черной Чешуи, которые идут через Обсидиановые рифы!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 мирмидонов из клана Черной Чешуи или зовущих море из клана Черной Чешуи.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Саймону Чендлеру на Высокий берег на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27179,'Еще одна интересная находка','Этому пигмею просто не повезло. Оказался, бедняга, не в то время и не в том месте.$B$BА пока вы размышляли о его злосчастной судьбе, вы обратили внимание на символы на его щите. Непохоже, чтобы это была мазня пигмея.$B$BНаверняка доктору Джонсу будет интересно на это взглянуть. Постарайтесь разыскать побольше таких фрагментов.','Соберите 10 фрагментов древней таблички.','Это таблички с письменами титанов! Потрясающая находка! Впервые в новейшей истории найдены памятники древней письменности титанов!$B$BДавно утерянный ключ к разгадке тайн древности...$B$BКакой же ты молодец!','Поговорите с Харрисоном Джонсом у Обелиска Звезд.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Еще одна интересная находка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этому пигмею просто не повезло. Оказался, бедняга, не в то время и не в том месте.$B$BА пока вы размышляли о его злосчастной судьбе, вы обратили внимание на символы на его щите. Непохоже, чтобы это была мазня пигмея.$B$BНаверняка доктору Джонсу будет интересно на это взглянуть. Постарайтесь разыскать побольше таких фрагментов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 фрагментов древней таблички.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это таблички с письменами титанов! Потрясающая находка! Впервые в новейшей истории найдены памятники древней письменности титанов!$B$BДавно утерянный ключ к разгадке тайн древности...$B$BКакой же ты молодец!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Харрисоном Джонсом у Обелиска Звезд.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27180,'Поминовение усопших','Катапульты Отрекшихся, конвоируемые ветеранами-бойцами, сегодня утром подверглись нападению при попытке пересечь Удел Ольсена, это к югу отсюда. Все солдаты перебиты, катапульты уничтожены, одним словом, полный разгром.$B$BЗасаду устроила стая Кровавых Клыков, хотя, сдается, они сбежали в холмы, готовясь к очередному предательскому нападению. Мы еще посчитаемся с ними, но сейчас я хочу, чтобы ты $gотправился:отправилась; в Удел Ольсена и с почестями $gпохоронил:похоронила; наших павших.$B$BПринеси их знаки различия.','Принесите 6 знаков различия Отрекшихся, снятых с тел ветеранов Отрекшихся.','Я позабочусь о том, чтобы эти знаки немедленно отправили в Подгород. Архивариус внесет имена героев в наши анналы, чтобы их самопожертвование никогда не было забыто.','Удалось добыть знаки различия?','Поговорите с леди Сильваной Ветрокрылой в Гробнице в Серебряном бору.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поминовение усопших',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Катапульты Отрекшихся, конвоируемые ветеранами-бойцами, сегодня утром подверглись нападению при попытке пересечь Удел Ольсена, это к югу отсюда. Все солдаты перебиты, катапульты уничтожены, одним словом, полный разгром.$B$BЗасаду устроила стая Кровавых Клыков, хотя, сдается, они сбежали в холмы, готовясь к очередному предательскому нападению. Мы еще посчитаемся с ними, но сейчас я хочу, чтобы ты $gотправился:отправилась; в Удел Ольсена и с почестями $gпохоронил:похоронила; наших павших.$B$BПринеси их знаки различия.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 6 знаков различия Отрекшихся, снятых с тел ветеранов Отрекшихся.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я позабочусь о том, чтобы эти знаки немедленно отправили в Подгород. Архивариус внесет имена героев в наши анналы, чтобы их самопожертвование никогда не было забыто.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось добыть знаки различия?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с леди Сильваной Ветрокрылой в Гробнице в Серебряном бору.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (27181,'Снятие порчи','Поговорите с леди Сильваной Ветрокрылой в Гробнице в Серебряном бору.','Эти псы скоро узнают цену своему высокомерию!','Леди Сильвана Ветрокрылая') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Снятие порчи',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с леди Сильваной Ветрокрылой в Гробнице в Серебряном бору.',`completedtext_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Эти псы скоро узнают цену своему высокомерию!',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Леди Сильвана Ветрокрылая',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27182,'Болото как-то странно влияет на тамошних жителей. Многие трогаются умом.$B$BА те, кто селится в сторожке "Болотный огонек", просто съезжают с катушек, да еще как! Все как один. Последний хозяин, некто Ярл по прозвищу "Болотный глаз", уже проявляет все признаки безумия.$B$BЯ не до конца понимаю, что там происходит, и буду очень тебе благодарен, если ты сходишь и разберешься.$B$BПоместье находится на восточном краю болота. Иди на восток через Синюю топь, мимо Северной башни. Дом стоит на Ведьмином холме, где водятся призраки.','Поговорите с Ярлом "Болотным глазом" в сторожке "Болотный огонек".','Пришел шпионить за мной? Нет?$B$BТогда, может, откушаешь вкусненького? Вот и славно, а то я как раз собирался добыть еды и мне нужна помощь!') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Болото как-то странно влияет на тамошних жителей. Многие трогаются умом.$B$BА те, кто селится в сторожке "Болотный огонек", просто съезжают с катушек, да еще как! Все как один. Последний хозяин, некто Ярл по прозвищу "Болотный глаз", уже проявляет все признаки безумия.$B$BЯ не до конца понимаю, что там происходит, и буду очень тебе благодарен, если ты сходишь и разберешься.$B$BПоместье находится на восточном краю болота. Иди на восток через Синюю топь, мимо Северной башни. Дом стоит на Ведьмином холме, где водятся призраки.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Ярлом "Болотным глазом" в сторожке "Болотный огонек".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Пришел шпионить за мной? Нет?$B$BТогда, может, откушаешь вкусненького? Вот и славно, а то я как раз собирался добыть еды и мне нужна помощь!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27183,'Лягушачьи лапки','Обожаю готовить! Аппетитные болотные блюда, жареные лягушачьи лапки и все в этом роде...$B$BТолько вот лапки у меня закончились. А в поместье лягушек как раз полно. Причем огромных. Может, принесешь мне их лапок? Ничего сложного, правда. Просто хорошенько дай лягушке по голове и неси мне лапки.$B$BА я их тут потушу, поперчу и с тобой поделюсь.$B$BЛюбишь лягушачьи лапки?','Добудьте 10 лапок гигантских болотных лягушек.','Вот так вкуснятина! Аппетитные тушеные лапки готовы.','Поперчим. Неплохо сделать жизнь маленько поострее, правда?','Вернитесь к Ярлу "Болотному глазу" в сторожку "Болотный огонек" в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лягушачьи лапки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Обожаю готовить! Аппетитные болотные блюда, жареные лягушачьи лапки и все в этом роде...$B$BТолько вот лапки у меня закончились. А в поместье лягушек как раз полно. Причем огромных. Может, принесешь мне их лапок? Ничего сложного, правда. Просто хорошенько дай лягушке по голове и неси мне лапки.$B$BА я их тут потушу, поперчу и с тобой поделюсь.$B$BЛюбишь лягушачьи лапки?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 10 лапок гигантских болотных лягушек.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот так вкуснятина! Аппетитные тушеные лапки готовы.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Поперчим. Неплохо сделать жизнь маленько поострее, правда?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ярлу "Болотному глазу" в сторожку "Болотный огонек" в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27184,'Ярлу нужны глаза','Глазной сок – вкусный сок. Жаль, у большинства зверей всего по два глаза.$B$BА вот у пауков глаз много. Просто тьма. И сок из глаз паука Мглистой пещеры – такая вкуснятина. Солененький! Мм-м... паучьи глаза... Уже чувствую их вкус на языке.$B$BПауки Мглистой пещеры водятся в Мглистой пещере, что к западу отсюда. Наверно, пауки в честь пещеры и названы... или наоборот?','Соберите 20 целых глаз паука Мглистой пещеры.','Ну, и где глаза?','Вернитесь к Ярлу "Болотному глазу" в сторожку "Болотный огонек" в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ярлу нужны глаза',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Глазной сок – вкусный сок. Жаль, у большинства зверей всего по два глаза.$B$BА вот у пауков глаз много. Просто тьма. И сок из глаз паука Мглистой пещеры – такая вкуснятина. Солененький! Мм-м... паучьи глаза... Уже чувствую их вкус на языке.$B$BПауки Мглистой пещеры водятся в Мглистой пещере, что к западу отсюда. Наверно, пауки в честь пещеры и названы... или наоборот?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 20 целых глаз паука Мглистой пещеры.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, и где глаза?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ярлу "Болотному глазу" в сторожку "Болотный огонек" в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27185,'Конкурентное преимущество','Слушай-ка, мы тут с тобой не в бирюльки играем. Молотобоец из Алого ордена прежде выеденного яйца не стоил, но со времени обращения в Восставших треклятый Повелитель Ужаса научил его делать всевозможное демоническое оружие, невероятно мощное.$B$BВсе просто. Разыщи их кузнечные чертежи и, как только молотобоец Багрового Легиона выйдет за ними, прикончи его, чтобы их армия не получила оружие демонов. Они и так сильны как черти!','Убейте молотобойца Багрового Легиона.','Ай да молодчина! Без нового оружия они такая же легкая добыча, как были при жизни!','Вернитесь к мастеру-ремесленнику Вильгельму.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Конкурентное преимущество',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слушай-ка, мы тут с тобой не в бирюльки играем. Молотобоец из Алого ордена прежде выеденного яйца не стоил, но со времени обращения в Восставших треклятый Повелитель Ужаса научил его делать всевозможное демоническое оружие, невероятно мощное.$B$BВсе просто. Разыщи их кузнечные чертежи и, как только молотобоец Багрового Легиона выйдет за ними, прикончи его, чтобы их армия не получила оружие демонов. Они и так сильны как черти!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте молотобойца Багрового Легиона.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ай да молодчина! Без нового оружия они такая же легкая добыча, как были при жизни!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру-ремесленнику Вильгельму.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27186,'Ярлу нужен клинок','Мне предстоит жестокая рубка. С кем, я тебе сказать не могу, но вот то, что мне для этого просто необходим добрый клинок, это к гадалке не ходи. Некоторые называют его меч, а я зову пляшущий клинок.$b$bПоможешь мне, а? Эти рыболюди, мурлоки или как их там... ну те, что живут к северу отсюда на побережье. Среди них есть один, они зовут его Костяная Чешуя, так вот он носит неплохой клинок. Он-то мне и нужен!$b$bГлавное, поторопись, то что я собираюсь рубить, ждать не станет...','Добудьте меч Костяной Чешуи.','Это хороший клинок... Он хорошо танцует, – стал быть, это – хороший танцующий клинок! Спасибо-спасибо-спасибо!!! Таак. Теперь я его испробую...$B$BПозже. Я испробую его позже. Но все равно спасибо тебе!','Ты достал клинок?','Вернитесь к Ярлу "Болотному глазу" в сторожку "Болотный огонек" в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ярлу нужен клинок',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне предстоит жестокая рубка. С кем, я тебе сказать не могу, но вот то, что мне для этого просто необходим добрый клинок, это к гадалке не ходи. Некоторые называют его меч, а я зову пляшущий клинок.$b$bПоможешь мне, а? Эти рыболюди, мурлоки или как их там... ну те, что живут к северу отсюда на побережье. Среди них есть один, они зовут его Костяная Чешуя, так вот он носит неплохой клинок. Он-то мне и нужен!$b$bГлавное, поторопись, то что я собираюсь рубить, ждать не станет...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте меч Костяной Чешуи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это хороший клинок... Он хорошо танцует, – стал быть, это – хороший танцующий клинок! Спасибо-спасибо-спасибо!!! Таак. Теперь я его испробую...$B$BПозже. Я испробую его позже. Но все равно спасибо тебе!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты достал клинок?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ярлу "Болотному глазу" в сторожку "Болотный огонек" в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questgivertargetname_loc8`) VALUES (27187,'Сделай миру одолжение','От обычных гиен и то сплошные неприятности.$B$BУ этих же мерзких особей и вовсе отвратительный нрав, они чем только ни болеют... и вообще это просто бельмо на глазу собачьего рода.$B$BСделай всему миру одолжение – избавь пустыни Ульдума от этой шелудивой напасти.','Убейте 12 облезлых гиен.','Облезлая гиена') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сделай миру одолжение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','От обычных гиен и то сплошные неприятности.$B$BУ этих же мерзких особей и вовсе отвратительный нрав, они чем только ни болеют... и вообще это просто бельмо на глазу собачьего рода.$B$BСделай всему миру одолжение – избавь пустыни Ульдума от этой шелудивой напасти.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 облезлых гиен.',`objectives_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Облезлая гиена',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27188,'Что таится на Ведьмином холме?','Получите нужные сведения, уничтожив 10 восставших мертвецов или духов.','Вернитесь к Морданту Мрачнику в сторожку "Болотный огонек" в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Что таится на Ведьмином холме?',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Получите нужные сведения, уничтожив 10 восставших мертвецов или духов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Морданту Мрачнику в сторожку "Болотный огонек" в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27189,'Ведьмина погибель','<Мордант принимает у вас пучок травы.>$B$BЭто растение в точности соответствует описанию! Я подготовил факел, пока тебя не было. Осталось только прикрепить траву вот сюда.','Ну как, удалось набрать травы? Действовать нужно быстро, пока зло окончательно не завладело этим местом.','Вернитесь к Морданту Мрачнику в сторожку "Болотный огонек" в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ведьмина погибель',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Мордант принимает у вас пучок травы.>$B$BЭто растение в точности соответствует описанию! Я подготовил факел, пока тебя не было. Осталось только прикрепить траву вот сюда.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как, удалось набрать травы? Действовать нужно быстро, пока зло окончательно не завладело этим местом.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Морданту Мрачнику в сторожку "Болотный огонек" в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27190,'Факел готов. Установи его в конце доков и готовься к сражению со всем, что на тебя полезет.$B$BПонятия не имею, кого именно вспугнет дым факела... если вообще хоть что-то появится. Короче, я не очень верю в эту народную магию, но ни на что другое у нас просто времени нет. Желаю удачи и тебе, и Ярлу.','Установите факел Ведьминой погибели в конце доков и сразитесь с нечистью, населяющей Ведьмин холм.','Дело сделано?','Вернитесь к Морданту Мрачнику в сторожку "Болотный огонек" в Пылевых топях.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Факел готов. Установи его в конце доков и готовься к сражению со всем, что на тебя полезет.$B$BПонятия не имею, кого именно вспугнет дым факела... если вообще хоть что-то появится. Короче, я не очень верю в эту народную магию, но ни на что другое у нас просто времени нет. Желаю удачи и тебе, и Ярлу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Установите факел Ведьминой погибели в конце доков и сразитесь с нечистью, населяющей Ведьмин холм.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Дело сделано?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Морданту Мрачнику в сторожку "Болотный огонек" в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27191,'Голодный как огр!','Тут встречается разный народ. Бывает, и очень даже приятный. Как-то раз я встретил огра. Огры, они любят покушать. Прямо как я.$B$BИ вот этот огр говорит... Никогда не забуду его слова: "Сляк – большой огр. Очень голодный. Принеси Сляк еды. Принеси рыбы. Или ты кормить Сляк, или Сляк съесть тебя."$B$BТак что пришлось принести ему рыбы, и он ее съел. Рыбу я тоже люблю. И особенно – головы. Они самые вкусные, такие нажористые и сочные...$B$BТолько не надо давить рыбам головы. Им от этого грустно. Грустные головы, они невкусные. Принеси мне довольные головы, я их съем – и тоже буду доволен.','Соберите 8 голов мурлоков из племени Болотного Плавника.','Каково, интересно, быть огром? Чем крупнее человек, тем больше он ест.$B$BА огры, наверное, едят еще больше. Они вечно голодные. Это, должно быть, невесело.','Ярл страшно голоден. Просто как огр.','Вернитесь к Ярлу "Болотному глазу" в сторожку "Болотный огонек" в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Голодный как огр!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тут встречается разный народ. Бывает, и очень даже приятный. Как-то раз я встретил огра. Огры, они любят покушать. Прямо как я.$B$BИ вот этот огр говорит... Никогда не забуду его слова: "Сляк – большой огр. Очень голодный. Принеси Сляк еды. Принеси рыбы. Или ты кормить Сляк, или Сляк съесть тебя."$B$BТак что пришлось принести ему рыбы, и он ее съел. Рыбу я тоже люблю. И особенно – головы. Они самые вкусные, такие нажористые и сочные...$B$BТолько не надо давить рыбам головы. Им от этого грустно. Грустные головы, они невкусные. Принеси мне довольные головы, я их съем – и тоже буду доволен.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 голов мурлоков из племени Болотного Плавника.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Каково, интересно, быть огром? Чем крупнее человек, тем больше он ест.$B$BА огры, наверное, едят еще больше. Они вечно голодные. Это, должно быть, невесело.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ярл страшно голоден. Просто как огр.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ярлу "Болотному глазу" в сторожку "Болотный огонек" в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27192,'Воистину, прямиком из былин. Этому историческому табаку просто нет цены.$B$BВот, держи несколько монет.','Вернитесь к караванщику Камнетесу.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Воистину, прямиком из былин. Этому историческому табаку просто нет цены.$B$BВот, держи несколько монет.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к караванщику Камнетесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (27193,'Найти и уничтожить','Обыскать фермы в Уделе Ольсена.','Поговорите с леди Сильваной Ветрокрылой в Гробнице в Серебряном бору.','Обыщи фермы!','Леди Сильвана Ветрокрылая','Они будут найдены и устранены!','Леди Сильвана Ветрокрылая') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Найти и уничтожить',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обыскать фермы в Уделе Ольсена.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с леди Сильваной Ветрокрылой в Гробнице в Серебряном бору.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Обыщи фермы!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Леди Сильвана Ветрокрылая',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Они будут найдены и устранены!',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Леди Сильвана Ветрокрылая',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27194,'Загнать и уничтожить!','Явитесь к мастеру Фортески на Серебряный рудник в Серебряном бору.','Полагаю, сначала нам надо загнать их в угол, а потом замесить, ага?','Ступай на Серебряный рудник.','Леди Сильвана Ветрокрылая') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Загнать и уничтожить!',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Явитесь к мастеру Фортески на Серебряный рудник в Серебряном бору.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Полагаю, сначала нам надо загнать их в угол, а потом замесить, ага?',`offerrewardtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Ступай на Серебряный рудник.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Леди Сильвана Ветрокрылая',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (27195,'Бежать некуда','Госпожа поручила мне разобраться с этим делом. Наша первостепенная задача – войти туда, припереть этих крыс к стенке и перебить всех, включая Кровавого Клыка.$B$BТы $gоказал:оказала; нам неоценимую услугу при сборе сведений, $n. Не упусти же свою долю славы и помоги нам мечом сокрушить их жалкие черепа!$B$BСообщи, когда будешь $gготов:готова;, и я отдам приказ.','Сопроводите мастера Фортески на Серебряный рудник.','Что?!$B$B<Сильвана визжит.>$B$BКРАУЛИ!!!!!!!!!$B$BУблюдки! Это были наши сильнейшие солдаты! Я недооценила Краули и Кровавого Клыка, но это в последний раз. Никогда мы не сталкивались с такими врагами – они готовы пожертвовать своими, чтобы устроить нам такую ловушку... никогда Альянс так не поступал.','Мастер Фортески сопровожден на Серебряный рудник','Вернитесь к леди Сильване Ветрокрылой в Гробницу в Серебряный бор.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бежать некуда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Госпожа поручила мне разобраться с этим делом. Наша первостепенная задача – войти туда, припереть этих крыс к стенке и перебить всех, включая Кровавого Клыка.$B$BТы $gоказал:оказала; нам неоценимую услугу при сборе сведений, $n. Не упусти же свою долю славы и помоги нам мечом сокрушить их жалкие черепа!$B$BСообщи, когда будешь $gготов:готова;, и я отдам приказ.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сопроводите мастера Фортески на Серебряный рудник.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что?!$B$B<Сильвана визжит.>$B$BКРАУЛИ!!!!!!!!!$B$BУблюдки! Это были наши сильнейшие солдаты! Я недооценила Краули и Кровавого Клыка, но это в последний раз. Никогда мы не сталкивались с такими врагами – они готовы пожертвовать своими, чтобы устроить нам такую ловушку... никогда Альянс так не поступал.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Мастер Фортески сопровожден на Серебряный рудник',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к леди Сильване Ветрокрылой в Гробницу в Серебряный бор.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27196,'Исторический момент','Ты молодец! Просто отличная работа! И особенно – для того, кто никогда не учился археологии.$B$BВ этих табличках содержится поистине бесценная информация.$B$BЗдесь говорится, что эти обелиски – часть гигантского древнего механизма, который когда-то создавал маскирующий покров, так что весь этот край оставался невидимым для остального мира.$B$BТакже здесь объясняется, как перезарядить маскирующий механизм. И вот тут нам как раз и понадобится твое древко Звезд...$B$BПриготовься, $n. Сейчас мы будем творить историю!','Сопроводите Харрисона Джонса в Зал Звезд.','Да, здесь есть на что посмотреть!','Поговорите с Харрисоном Джонсом в Зале Звезд.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Исторический момент',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты молодец! Просто отличная работа! И особенно – для того, кто никогда не учился археологии.$B$BВ этих табличках содержится поистине бесценная информация.$B$BЗдесь говорится, что эти обелиски – часть гигантского древнего механизма, который когда-то создавал маскирующий покров, так что весь этот край оставался невидимым для остального мира.$B$BТакже здесь объясняется, как перезарядить маскирующий механизм. И вот тут нам как раз и понадобится твое древко Звезд...$B$BПриготовься, $n. Сейчас мы будем творить историю!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сопроводите Харрисона Джонса в Зал Звезд.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, здесь есть на что посмотреть!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Харрисоном Джонсом в Зале Звезд.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27197,'Борьба возобновляется!','Пришли вести из Андорала, $n. Борьба возобновилась.$B$BКаким-то образом силам Альянса стало известно, какую роль ты $gсыграл:сыграла; в первой битве Андорала. Тассариан потребовал, чтобы ты к нему немедленно $gявился:явилась;.','Поговорите с Тассарианом в Андорале в Западных Чумных землях.','Поговорите с Тассарианом в Андорале в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Борьба возобновляется!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пришли вести из Андорала, $n. Борьба возобновилась.$B$BКаким-то образом силам Альянса стало известно, какую роль ты $gсыграл:сыграла; в первой битве Андорала. Тассариан потребовал, чтобы ты к нему немедленно $gявился:явилась;.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Тассарианом в Андорале в Западных Чумных землях.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Тассарианом в Андорале в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27198,'Поддержка войск','Я не эксперт в военном деле, но эта битва, похоже, складывается в нашу пользу. Наши защитники равны по силам их стражам смерти, но крестьянское ополчение застало их врасплох, атаковав с тыла. За Альянс!$B$BНо мы по-прежнему должны делать все для победы. Отправляйся на восток, в Андорал, убивать стражей смерти Отрекшихся, бьющихся с нашими людьми. Чем быстрее они сгинут, тем скорее мы вернем себе Андорал!','Убейте 15 стражей смерти из Андорала.','Вернитесь к Лангу Разболтайлу в Андорал в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поддержка войск',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я не эксперт в военном деле, но эта битва, похоже, складывается в нашу пользу. Наши защитники равны по силам их стражам смерти, но крестьянское ополчение застало их врасплох, атаковав с тыла. За Альянс!$B$BНо мы по-прежнему должны делать все для победы. Отправляйся на восток, в Андорал, убивать стражей смерти Отрекшихся, бьющихся с нашими людьми. Чем быстрее они сгинут, тем скорее мы вернем себе Андорал!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 15 стражей смерти из Андорала.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лангу Разболтайлу в Андорал в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27199,'Прах к праху','На востоке, в самой глубине Андорала, занятого Отрекшимися, скрываются их командиры. В боях они не участвуют, лишь отдают приказы, сидя верхом.$B$BВыследи и уничтожь этих командиров, $n. Не оставим Отрекшимся ни одного шанса.','Уничтожьте 3 военачальников стражей смерти.','Молодец! Теперь, когда их больше нет, меня ничто не держит.$B$BСкоро я выйду на бой с Кольтирой и буду драться за честь и Андорал.','Вернитесь к Тассариану в Андорал, что в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прах к праху',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На востоке, в самой глубине Андорала, занятого Отрекшимися, скрываются их командиры. В боях они не участвуют, лишь отдают приказы, сидя верхом.$B$BВыследи и уничтожь этих командиров, $n. Не оставим Отрекшимся ни одного шанса.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 3 военачальников стражей смерти.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Молодец! Теперь, когда их больше нет, меня ничто не держит.$B$BСкоро я выйду на бой с Кольтирой и буду драться за честь и Андорал.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тассариану в Андорал, что в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (27200,'Зов сирены','Она все еще где-то здесь... Офелия, сирена нагорья! Ее ужасная песня заманит тебя в самые глубины. $C, я поклялся остаться здесь и отомстить за погибших товарищей. Если хочешь присоединиться, просто дай мне знать.$B$BМы привяжем себя к мачте. Закроем глаза. Залепим уши воском. А когда ее ослепительная иллюзия рассеется... мы нанесем удар.$B$BНу что, ты со мной?','Убейте Офелию, сирену нагорья.','Убейте Офелию и защитите Эфрама','Поговорите с Эфрамом Тяжелым Валуном в Обсидиановых рифах на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зов сирены',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Она все еще где-то здесь... Офелия, сирена нагорья! Ее ужасная песня заманит тебя в самые глубины. $C, я поклялся остаться здесь и отомстить за погибших товарищей. Если хочешь присоединиться, просто дай мне знать.$B$BМы привяжем себя к мачте. Закроем глаза. Залепим уши воском. А когда ее ослепительная иллюзия рассеется... мы нанесем удар.$B$BНу что, ты со мной?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Офелию, сирену нагорья.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Убейте Офелию и защитите Эфрама',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Эфрамом Тяжелым Валуном в Обсидиановых рифах на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27201,'Вторжение валь\'кир','Валь\'киры служили одним из главных видов оружия Плети. Не только потому, что были искусны в бою, – они могли превращать павших в приспешников Плети. Но думать, что Сильвана пошла на такую низость ради Отрекшихся...$B$BНам надо остановить валь\'кир, прежде чем они уничтожат и обратят против нас наши же армии. Перебей их сколько сумеешь. И возьми с собой нескольких ополченцев. Если они так долго протянули, стало быть, в бою чего-то да стоят.','Убейте 9 низших валь\'кир в Андорале.','Убивая валь\'киру, ты спасаешь десятки наших бойцов... И не даешь увеличиваться силам Отрекшихся.$B$BИ все же они теснят нас. Мы можем и не выиграть этой битвы.','Вернитесь к Тассариану в Андорал, что в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вторжение валь\'кир',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Валь\'киры служили одним из главных видов оружия Плети. Не только потому, что были искусны в бою, – они могли превращать павших в приспешников Плети. Но думать, что Сильвана пошла на такую низость ради Отрекшихся...$B$BНам надо остановить валь\'кир, прежде чем они уничтожат и обратят против нас наши же армии. Перебей их сколько сумеешь. И возьми с собой нескольких ополченцев. Если они так долго протянули, стало быть, в бою чего-то да стоят.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 9 низших валь\'кир в Андорале.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Убивая валь\'киру, ты спасаешь десятки наших бойцов... И не даешь увеличиваться силам Отрекшихся.$B$BИ все же они теснят нас. Мы можем и не выиграть этой битвы.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тассариану в Андорал, что в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27202,'Брат против брата','Ополчение почти все полегло, остались только я да вот фермеры.$B$BЭти крылатые твари... они брали тела наших и... и превращали в ходячие трупы, в нежить! И каждый, кто погибал, присоединялся к ним!$B$BТрудно такое произнести, но тебе придется сражаться с ними – так же, как со стражами смерти и валь\'кирами. Как и при жизни, они охотятся группами, поэтому пусть с тобой пойдет один из моих ополченцев.','Убейте 20 солдат-Отрекшихся в Андорале.','Ты храбро сражался, но это нам не помогло. Каждый павший лишь пополняет их ряды.','Вернитесь к Турману Гранту в Андорал в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Брат против брата',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ополчение почти все полегло, остались только я да вот фермеры.$B$BЭти крылатые твари... они брали тела наших и... и превращали в ходячие трупы, в нежить! И каждый, кто погибал, присоединялся к ним!$B$BТрудно такое произнести, но тебе придется сражаться с ними – так же, как со стражами смерти и валь\'кирами. Как и при жизни, они охотятся группами, поэтому пусть с тобой пойдет один из моих ополченцев.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 20 солдат-Отрекшихся в Андорале.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты храбро сражался, но это нам не помогло. Каждый павший лишь пополняет их ряды.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Турману Гранту в Андорал в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27203,'Водоворот','Слава духам, ты здесь, $n.$b$bНе знаю, как долго мы еще сможем удерживать разлом в Водовороте.$b$bНаши самые могущественные шаманы под предводительством Тралла лишь не дают ему расти.$b$bПо последним данным наша единственная надежда в том, чтобы пройти через разлом и попытаться стабилизировать его с другой стороны.$b$bЯ открою портал. Пройди через него и поговори с Траллом как можно скорее.','Пройдите через портал в Водоворот и поговорите с Траллом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Водоворот',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слава духам, ты здесь, $n.$b$bНе знаю, как долго мы еще сможем удерживать разлом в Водовороте.$b$bНаши самые могущественные шаманы под предводительством Тралла лишь не дают ему расти.$b$bПо последним данным наша единственная надежда в том, чтобы пройти через разлом и попытаться стабилизировать его с другой стороны.$b$bЯ открою портал. Пройди через него и поговори с Траллом как можно скорее.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Пройдите через портал в Водоворот и поговорите с Траллом.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`) VALUES (27204,'Наша последняя надежда на победу – это уничтожение валь\'кир. До сих пор ты $gсправлялся:справлялась; неплохо... Но ты лишь $gодин мужчина:одна женщина;, а их там многие десятки – носятся по полю брани, сея сплошное разрушение...$B$BОдна огромная валь\'кира сидит на вершине башни на юге... вон она, отсюда видно. Может, если ее убрать, то и все остальные сгинут?$B$BОстается только на это надеяться. Возьми с собой ребят Гранта, в этом бою тебе точно понадобится их помощь.','Я наблюдал снизу, как ты сражался. Хороший был бой, жаль только, в итоге не принесет нам никакой пользы.$B$BВаль\'киры и Отрекшиеся наступают, скоро они нас раздавят. Мы все-таки потеряли Андорал.','Вернитесь к Тассариану в Андорал, что в Западных Чумных землях.','Повелительница валь\'кир в Андорале. Она наша последняя надежда…') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наша последняя надежда на победу – это уничтожение валь\'кир. До сих пор ты $gсправлялся:справлялась; неплохо... Но ты лишь $gодин мужчина:одна женщина;, а их там многие десятки – носятся по полю брани, сея сплошное разрушение...$B$BОдна огромная валь\'кира сидит на вершине башни на юге... вон она, отсюда видно. Может, если ее убрать, то и все остальные сгинут?$B$BОстается только на это надеяться. Возьми с собой ребят Гранта, в этом бою тебе точно понадобится их помощь.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я наблюдал снизу, как ты сражался. Хороший был бой, жаль только, в итоге не принесет нам никакой пользы.$B$BВаль\'киры и Отрекшиеся наступают, скоро они нас раздавят. Мы все-таки потеряли Андорал.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тассариану в Андорал, что в Западных Чумных землях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Повелительница валь\'кир в Андорале. Она наша последняя надежда…',`questgivertextwindow_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27205,'Коварство Отрекшихся','Мы почти выиграли этот бой, $n. Я уже чувствую победу. У Отрекшихся с самого начала не было ни...$B$BА это что еще такое?!','Узнайте, что привлекло внимание Тассариана.','Валь\'киры? Кольтира позвал на этот бой валь\'кир? Он что, с ума сошел?$B$BНет, это почерк не Кольтиры. Это дело рук Сильваны.','Поговорите с Тассарианом о том, что вы только что видели.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Коварство Отрекшихся',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы почти выиграли этот бой, $n. Я уже чувствую победу. У Отрекшихся с самого начала не было ни...$B$BА это что еще такое?!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Узнайте, что привлекло внимание Тассариана.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Валь\'киры? Кольтира позвал на этот бой валь\'кир? Он что, с ума сошел?$B$BНет, это почерк не Кольтиры. Это дело рук Сильваны.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Тассарианом о том, что вы только что видели.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27206,'Увы тебе, Андорал','Расскажите командиру Ашламу Неутомимому о ходе битвы за Андорал.','Поражение? В следующий раз они заявятся уже сюда, к нам в лагерь. Да, это серьезный удар по планам Альянса на Лордерон.$B$BЧто ж, я доложу королю Ринну. Уж он не обрадуется.','Доберитесь до командира Ашлама Неутомимого в лагере Промозглого Ветра в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Увы тебе, Андорал',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Расскажите командиру Ашламу Неутомимому о ходе битвы за Андорал.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Поражение? В следующий раз они заявятся уже сюда, к нам в лагерь. Да, это серьезный удар по планам Альянса на Лордерон.$B$BЧто ж, я доложу королю Ринну. Уж он не обрадуется.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доберитесь до командира Ашлама Неутомимого в лагере Промозглого Ветра в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27207,'Такого ветром не сдует','Так вот кто виноват в бурях, поразившими мой город!$B$BЧто ж. Этот тщедушный громовержец скоро перестанет вытворять свои трюки. Когда вернемся, расскажи генералу Маркусу Джонатану о том, что здесь произошло. Сам-то я буду занят – кто-то же должен присматривать за возвращением горожан, ремонтными работами и прочим.','Убейте принца Сарсаруна и поставьте об этом в известность генерала Маркуса Джонсона в Штормграде.','Сообщите генералу Маркусу Джонатану в Штормграде о смерти принца Сарсаруна.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Такого ветром не сдует',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Так вот кто виноват в бурях, поразившими мой город!$B$BЧто ж. Этот тщедушный громовержец скоро перестанет вытворять свои трюки. Когда вернемся, расскажи генералу Маркусу Джонатану о том, что здесь произошло. Сам-то я буду занят – кто-то же должен присматривать за возвращением горожан, ремонтными работами и прочим.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте принца Сарсаруна и поставьте об этом в известность генерала Маркуса Джонсона в Штормграде.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Сообщите генералу Маркусу Джонатану в Штормграде о смерти принца Сарсаруна.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27208,'Повелитель Ужаса Бальназар','Убейте Бальназара.','Хорошо, что мы успели остановить Бальназара. Мы бы оглянуться не успели, как его армия заняла бы Стратхольм и он превратился бы в неприступную столицу его дьявольской империи.','Вернитесь к командиру Элигору Вестнику Рассвета.','Повелитель Восставших','Бальназар') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Повелитель Ужаса Бальназар',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Бальназара.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо, что мы успели остановить Бальназара. Мы бы оглянуться не успели, как его армия заняла бы Стратхольм и он превратился бы в неприступную столицу его дьявольской империи.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру Элигору Вестнику Рассвета.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Повелитель Восставших',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Бальназар',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27209,'Такого ветром не сдует','Так вот что за напасть скрывается за нападениями на Громовой Утес.$B$BДавайте отправляться в путь. Нужно положить конец этой скверне.$B$BКогда вернемся, расскажи Хамуулу Руническому Тотему обо всем, что здесь произошло. Сам-то я буду занят – кто-то же должен присматривать за возвращением горожан, ремонтными работами и прочим.','Убейте принца Сарсаруна и поставьте об этом в известность Хамуула Рунического Тотема в Громовом Утесе.','Сообщите Хамуулу Руническому Тотему в Громовом Утесе о кончине принца Сарсаруна.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Такого ветром не сдует',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Так вот что за напасть скрывается за нападениями на Громовой Утес.$B$BДавайте отправляться в путь. Нужно положить конец этой скверне.$B$BКогда вернемся, расскажи Хамуулу Руническому Тотему обо всем, что здесь произошло. Сам-то я буду занят – кто-то же должен присматривать за возвращением горожан, ремонтными работами и прочим.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте принца Сарсаруна и поставьте об этом в известность Хамуула Рунического Тотема в Громовом Утесе.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Сообщите Хамуулу Руническому Тотему в Громовом Утесе о кончине принца Сарсаруна.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27210,'Чужой среди своих','Хорошо, что я тебя встретила, |3-6($c). Вот, прибыла в Терамор, чтобы разобраться с дезертирством. Солдаты покидают свои посты, вражеские агенты проникают в город!$B$BОни распространяют лживую пропаганду, надеясь, что и другие к ним присоединятся!$B$BАгенты буквально повсюду – у всех сторожевых постов в городе и доках. Необходимо выявить их и дискредитировать! Пока ничего больше и сделать нельзя, иначе только вызовешь к ним еще больше доверия.','Прогоните 5 дезертиров-подстрекателей в Тераморе.','Вернитесь к Калии Гастингс на остров Терамор в Пылевой топи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чужой среди своих',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хорошо, что я тебя встретила, |3-6($c). Вот, прибыла в Терамор, чтобы разобраться с дезертирством. Солдаты покидают свои посты, вражеские агенты проникают в город!$B$BОни распространяют лживую пропаганду, надеясь, что и другие к ним присоединятся!$B$BАгенты буквально повсюду – у всех сторожевых постов в городе и доках. Необходимо выявить их и дискредитировать! Пока ничего больше и сделать нельзя, иначе только вызовешь к ним еще больше доверия.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Прогоните 5 дезертиров-подстрекателей в Тераморе.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Калии Гастингс на остров Терамор в Пылевой топи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27211,'Пропагандистская война','Вражеские агенты не просто так заводят беседы со стражниками. Мы обнаружили множество листовок с призывом к дезертирству – каким-то образом их умудрились доставить в доки.$B$BКорабль, что привез листовки, еще стоит в Тераморе, в дальнем доке. Если тебе удастся проникнуть на борт и выкрасть оставшиеся пропагандистские листовки, то вражеские агенты утратят свое самое мощное оружие. Только осторожнее! Команда – опытные каперы. Груз, скорее всего, держат в капитанской каюте.','Добудьте листовки дезертиров с корабля в дальнем конце доков Терамора.','<Агент ШРУ одобрительно кивает.>$B$BБлестяще. Остается только дискредитировать дезертиров так, чтобы они больше носу не сунули в Терамор, и у меня на этот счет есть план.','Тебе удалось найти и захватить оставшиеся пропагандистские листовки?','Вернитесь к Калии Гастингс на остров Терамор в Пылевой топи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пропагандистская война',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вражеские агенты не просто так заводят беседы со стражниками. Мы обнаружили множество листовок с призывом к дезертирству – каким-то образом их умудрились доставить в доки.$B$BКорабль, что привез листовки, еще стоит в Тераморе, в дальнем доке. Если тебе удастся проникнуть на борт и выкрасть оставшиеся пропагандистские листовки, то вражеские агенты утратят свое самое мощное оружие. Только осторожнее! Команда – опытные каперы. Груз, скорее всего, держат в капитанской каюте.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте листовки дезертиров с корабля в дальнем конце доков Терамора.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Агент ШРУ одобрительно кивает.>$B$BБлестяще. Остается только дискредитировать дезертиров так, чтобы они больше носу не сунули в Терамор, и у меня на этот счет есть план.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось найти и захватить оставшиеся пропагандистские листовки?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Калии Гастингс на остров Терамор в Пылевой топи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27212,'Дискредитация вражеской агентуры','Я кое-что изменила в листовках, которые ты $gпохитил:похитила; у наших заклятых друзей в доках. Теперь они пропагандируют совсем другое!$B$BЕсли мы подкинем побольше этих листовок страже, врагам вряд ли удастся так легко снова угнездиться в наших стенах.$B$B<Калия вручает вам стопку подправленных листовок.>$B$BНе займешься этим, пока я обдумываю наш очередной шаг?','Всучите подправленные листовки 6 тераморским стражникам.','<Калия прищелкивает языком, когда вы описываете ей реакцию стражников на листовки.>$B$BКак я и надеялась! Думаю, теперь-то уж точно любого вражеского агента, который попытается сунуться в Терамор, просто высмеют.','Мне показалось, что я слышала смех из казарм. Ты раздал мои листовки?','Вернитесь к Калии Гастингс на остров Терамор в Пылевой топи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дискредитация вражеской агентуры',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я кое-что изменила в листовках, которые ты $gпохитил:похитила; у наших заклятых друзей в доках. Теперь они пропагандируют совсем другое!$B$BЕсли мы подкинем побольше этих листовок страже, врагам вряд ли удастся так легко снова угнездиться в наших стенах.$B$B<Калия вручает вам стопку подправленных листовок.>$B$BНе займешься этим, пока я обдумываю наш очередной шаг?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Всучите подправленные листовки 6 тераморским стражникам.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Калия прищелкивает языком, когда вы описываете ей реакцию стражников на листовки.>$B$BКак я и надеялась! Думаю, теперь-то уж точно любого вражеского агента, который попытается сунуться в Терамор, просто высмеют.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мне показалось, что я слышала смех из казарм. Ты раздал мои листовки?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Калии Гастингс на остров Терамор в Пылевой топи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27213,'Конец вражеской пропаганде','С дезертирами из Терамора мы разобрались, операцию пора завершать. Местные осведомители сообщили, что база дезертиров – на корабле, который швартуется у небольшого острова к юго-востоку от пристани.$B$BЕсли арестовать их главаря Гависа Серого Щита, то у остальных отпадет всякая охота сражаться. Найди его на том корабле и заставь сдаться. Не удивлюсь, если сначала он набросится на тебя, но когда поймет, что ему не победить, то успокоится.','Победите Гависа Серого Щита на борту корабля к юго-востоку от Терамора.','Вернитесь к Калии Гастингс на остров Терамор в Пылевой топи.','Бывший лейтенант народного ополчения Терамора','Гавис Серый Щит') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Конец вражеской пропаганде',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','С дезертирами из Терамора мы разобрались, операцию пора завершать. Местные осведомители сообщили, что база дезертиров – на корабле, который швартуется у небольшого острова к юго-востоку от пристани.$B$BЕсли арестовать их главаря Гависа Серого Щита, то у остальных отпадет всякая охота сражаться. Найди его на том корабле и заставь сдаться. Не удивлюсь, если сначала он набросится на тебя, но когда поймет, что ему не победить, то успокоится.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Гависа Серого Щита на борту корабля к юго-востоку от Терамора.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Калии Гастингс на остров Терамор в Пылевой топи.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Бывший лейтенант народного ополчения Терамора',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Гавис Серый Щит',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (27214,'Тревожные события','Поговорите с капитаном Ваймором на Сторожевом посту.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тревожные события',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с капитаном Ваймором на Сторожевом посту.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27215,'Отшельник из сторожки "Болотный огонек"','Есть тут один старикашка по имени Ярл. Его называют "Болотный глаз." Живет на болоте. Не так давно он "унаследовал" сторожку "Болотный огонек", когда ее предыдущий хозяин пропал при таинственных обстоятельствах.$B$BМне нужен тот, кто будет периодически проверять, что там происходит у этого "Болотного глаза". Знаешь, он мне чем-то напоминает моего деда. Тоже чуток не в себе, мягко говоря.$B$BИди на северо-запад по дороге из Терамора. "Болотный огонек" стоит на Ведьмином холме, как раз перед тем поворотом, где дорога уходит на запад.','Поговорите с Ярлом "Болотным глазом" в сторожке "Болотный огонек".','Убирайся с моей лужайки... хотя нет, погоди... Может, поможешь старому "Болотному глазу" приготовить обед? Ну как, согласен?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отшельник из сторожки "Болотный огонек"',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Есть тут один старикашка по имени Ярл. Его называют "Болотный глаз." Живет на болоте. Не так давно он "унаследовал" сторожку "Болотный огонек", когда ее предыдущий хозяин пропал при таинственных обстоятельствах.$B$BМне нужен тот, кто будет периодически проверять, что там происходит у этого "Болотного глаза". Знаешь, он мне чем-то напоминает моего деда. Тоже чуток не в себе, мягко говоря.$B$BИди на северо-запад по дороге из Терамора. "Болотный огонек" стоит на Ведьмином холме, как раз перед тем поворотом, где дорога уходит на запад.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Ярлом "Болотным глазом" в сторожке "Болотный огонек".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Убирайся с моей лужайки... хотя нет, погоди... Может, поможешь старому "Болотному глазу" приготовить обед? Ну как, согласен?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27216,'Этот старый маяк','Старый маяк к востоку отсюда некоторое время не работал, но Бабс Шипокрутка вбила себе в голову, что надо туда залезть и снова его зажечь.$B$BНе знаю, как у нее это выйдет, но она говорит, что от этого судам будет легче входить в гавань и доставлять товары с борта на склады, поэтому я не против. Дежурить в доках – работенка непыльная, особенно по сравнению с передовой, не так ли?','Поговорите с Бабс Шипокруткой на маяке на острове к востоку от Терамора.','Хорошо. Мне понадобится твоя помощь. Первым делом необходимо снова зажечь фонарь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Этот старый маяк',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Старый маяк к востоку отсюда некоторое время не работал, но Бабс Шипокрутка вбила себе в голову, что надо туда залезть и снова его зажечь.$B$BНе знаю, как у нее это выйдет, но она говорит, что от этого судам будет легче входить в гавань и доставлять товары с борта на склады, поэтому я не против. Дежурить в доках – работенка непыльная, особенно по сравнению с передовой, не так ли?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Бабс Шипокруткой на маяке на острове к востоку от Терамора.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо. Мне понадобится твоя помощь. Первым делом необходимо снова зажечь фонарь.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27217,'Жир крепкозуба','Старый журнал, найденный на маяке, указывает, что фонарь заправляли жиром крепкозубов, обитающих вдоль здешнего побережья.$B$B<Бабс морщит нос от одного упоминания о такой устаревшей технологии.>$B$BНу, решение практичное, хотя и неизящное. В журнале говорится, что лучше всего брать жир самых молодых черных крепкозубов, а они обитают прямо в доках Терамора.$B$BЕсли ты не против, может, добудешь топливо для маяка?','Добудьте 4 контейнера жира черных крепкозубов, живущих в доках Терамора.','Ну, хотя у меня и есть сомнения на этот счет, но сейчас это лучшее решение. Как только мы зажжем маяк, у нас наверняка найдется время подыскать другое топливо для фонаря.','Тебе удалось добыть жир крепкозуба?','Вернитесь к Бабс Шипокрутке на остров Терамор в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жир крепкозуба',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Старый журнал, найденный на маяке, указывает, что фонарь заправляли жиром крепкозубов, обитающих вдоль здешнего побережья.$B$B<Бабс морщит нос от одного упоминания о такой устаревшей технологии.>$B$BНу, решение практичное, хотя и неизящное. В журнале говорится, что лучше всего брать жир самых молодых черных крепкозубов, а они обитают прямо в доках Терамора.$B$BЕсли ты не против, может, добудешь топливо для маяка?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 4 контейнера жира черных крепкозубов, живущих в доках Терамора.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну, хотя у меня и есть сомнения на этот счет, но сейчас это лучшее решение. Как только мы зажжем маяк, у нас наверняка найдется время подыскать другое топливо для фонаря.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось добыть жир крепкозуба?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бабс Шипокрутке на остров Терамор в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27218,'Подлые обитатели глубин','Этот старый маяк – просто сокровищница! Чего здесь только ни найдешь! Вот, например, эта книга. Лежала в одном из старых сундуков.$B$B<Бабс берет книгу и читает название.>$B$B"Подлые обитатели глубин"!$B$BЯ, наверное, просто умру от восторга, если увижу воочию хотя бы одного. Да и книжица, думается, забавная. Но у меня сейчас просто нет времени читать.$B$BОднако я знаю, кого она может порадовать... Торговца рыбой из доков, Ленни Полечуда по прозвищу "Весельчак." Он коллекционирует старые книги.','Отнесите книгу "Подлые обитатели глубин" в доки Терамора и отдайте "Весельчаку" Ленни Полечуду.','Какая Бабс заботливая... помнит, что я собираю книги. Да и книга отличная. Ты сам-то ее пролистал? Там, кстати, немало правдивых историй. Да, моряки любят приврать, но не все их рассказы – выдумки.','Что сегодня берем? Рекомендую морскую щуку.','Поговорите с "Весельчаком" Ленни Полечудом на острове Терамор в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подлые обитатели глубин',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этот старый маяк – просто сокровищница! Чего здесь только ни найдешь! Вот, например, эта книга. Лежала в одном из старых сундуков.$B$B<Бабс берет книгу и читает название.>$B$B"Подлые обитатели глубин"!$B$BЯ, наверное, просто умру от восторга, если увижу воочию хотя бы одного. Да и книжица, думается, забавная. Но у меня сейчас просто нет времени читать.$B$BОднако я знаю, кого она может порадовать... Торговца рыбой из доков, Ленни Полечуда по прозвищу "Весельчак." Он коллекционирует старые книги.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите книгу "Подлые обитатели глубин" в доки Терамора и отдайте "Весельчаку" Ленни Полечуду.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Какая Бабс заботливая... помнит, что я собираю книги. Да и книга отличная. Ты сам-то ее пролистал? Там, кстати, немало правдивых историй. Да, моряки любят приврать, но не все их рассказы – выдумки.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что сегодня берем? Рекомендую морскую щуку.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с "Весельчаком" Ленни Полечудом на острове Терамор в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27219,'Так это правда?','О, да я уверен, что вы с Бабс животики себе надорвали, читая эти чужеземные описания да разглядывая картинки в книге. А вы не подумали о том, что в легендах есть доля истины?$B$BТы удивишься, но моряки на полном серьезе говорят о Тетуре, морском существе, которое, как написано в книге, живет прямо здесь. Ну, а если ты хочешь точно знать, то всегда можно спросить старину Ната Пэгла.$B$BОн живет в маленьком рыбацком лагере на островке в заливе Яростных волн, это если плыть на юго-запад через Пылевую бухту.','Поговорите с Натом Пэглом в лагере Ната, что в Пылевых топях.','Так ты хочешь послушать о морских монстрах? Хм... Ну что ж, хорошо, но для этого потребуется море выпивки, а тебе потом будет немного стыдно.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Так это правда?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','О, да я уверен, что вы с Бабс животики себе надорвали, читая эти чужеземные описания да разглядывая картинки в книге. А вы не подумали о том, что в легендах есть доля истины?$B$BТы удивишься, но моряки на полном серьезе говорят о Тетуре, морском существе, которое, как написано в книге, живет прямо здесь. Ну, а если ты хочешь точно знать, то всегда можно спросить старину Ната Пэгла.$B$BОн живет в маленьком рыбацком лагере на островке в заливе Яростных волн, это если плыть на юго-запад через Пылевую бухту.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Натом Пэглом в лагере Ната, что в Пылевых топях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так ты хочешь послушать о морских монстрах? Хм... Ну что ж, хорошо, но для этого потребуется море выпивки, а тебе потом будет немного стыдно.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27220,'Сделка Ната','Значит, ты $gнашел:нашла; экземпляр "Подлых обитателей глубин"? Что ж, скажу по собственному опыту – все, что там написано, правда. Кое-кого я и собственными глазами видел.$B$BНо ты спрашиваешь про Тетура... Давай так договоримся. Я тут разрабатываю новую линейку наживок, и одну еще не испытывал.$B$BВозьми эту пасту – да, запашок у нее не из приятных, – намажься и плыви на юго-запад в глубокую часть Залива Яростных Волн. Выживешь – расскажешь, как все прошло!','Испытайте особую рыбную пасту Пэгла на себе, после чего плывите в Залив Яростных Волн.','Что ж, неплохо, неплохо, но на твоем месте я бы срочно отправился в душ.$B$BА теперь о том морском чудище...$B$BПропусти пока кружку-другую.','Уговор такой – без улова не возвращаться!','Вернитесь к Нату Пэглу в его лагерь в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сделка Ната',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Значит, ты $gнашел:нашла; экземпляр "Подлых обитателей глубин"? Что ж, скажу по собственному опыту – все, что там написано, правда. Кое-кого я и собственными глазами видел.$B$BНо ты спрашиваешь про Тетура... Давай так договоримся. Я тут разрабатываю новую линейку наживок, и одну еще не испытывал.$B$BВозьми эту пасту – да, запашок у нее не из приятных, – намажься и плыви на юго-запад в глубокую часть Залива Яростных Волн. Выживешь – расскажешь, как все прошло!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Испытайте особую рыбную пасту Пэгла на себе, после чего плывите в Залив Яростных Волн.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что ж, неплохо, неплохо, но на твоем месте я бы срочно отправился в душ.$B$BА теперь о том морском чудище...$B$BПропусти пока кружку-другую.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Уговор такой – без улова не возвращаться!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Нату Пэглу в его лагерь в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27221,'Он настоящий!','Да, Тетур вполне настоящий, живет он в тераморских водах.$B$BПриходит на яркий огонь. Именно поэтому маяк там не работает...$B$BСтоит его зажечь, как чудище вернется. Но в здравом уме никто на это не пойдет.$B$BСоответственно, это работка для тебя. Приятно было с тобой выпить, но не обижайся на Ната, если Тетур на самом деле примет тебя за наживку. Если намереваешься с ним повидаться, поговори сначала с майором Миллзом из доков Терамора.','Поговорите с майором Миллзом в доках Терамора.','<Вы рассказываете о вашем разговоре с Натом, тщательно обходя тему испытания наживки.>$B$BЧто ж, видимо, работка как раз для нас. Я все подготовлю.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Он настоящий!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Да, Тетур вполне настоящий, живет он в тераморских водах.$B$BПриходит на яркий огонь. Именно поэтому маяк там не работает...$B$BСтоит его зажечь, как чудище вернется. Но в здравом уме никто на это не пойдет.$B$BСоответственно, это работка для тебя. Приятно было с тобой выпить, но не обижайся на Ната, если Тетур на самом деле примет тебя за наживку. Если намереваешься с ним повидаться, поговори сначала с майором Миллзом из доков Терамора.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с майором Миллзом в доках Терамора.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Вы рассказываете о вашем разговоре с Натом, тщательно обходя тему испытания наживки.>$B$BЧто ж, видимо, работка как раз для нас. Я все подготовлю.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (27222,'Сразить Тетура!','Чудовище, не чудовище – мы не можем рисковать безопасностью морских перевозок. Я приказал лучшим стрелкам приготовиться к бою с Тетуром. Артиллеристы усилили оборону доков тремя мортирами.$B$BЯ готов отдать приказ зажечь маяк. Если Тетур пойдет в атаку, твоя задача стрелять из мортир и прикончить тварь, прежде чем она уничтожит всех наших стрелков. При этом я не советовал бы долго стоять на одном месте. Стрельба из мортир обязательно привлечет его внимание.','Сразите Тетура с помощью мортир.','Защитить доки Терамора от Тетура','Вернитесь к майору Миллзу на остров Терамор в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сразить Тетура!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чудовище, не чудовище – мы не можем рисковать безопасностью морских перевозок. Я приказал лучшим стрелкам приготовиться к бою с Тетуром. Артиллеристы усилили оборону доков тремя мортирами.$B$BЯ готов отдать приказ зажечь маяк. Если Тетур пойдет в атаку, твоя задача стрелять из мортир и прикончить тварь, прежде чем она уничтожит всех наших стрелков. При этом я не советовал бы долго стоять на одном месте. Стрельба из мортир обязательно привлечет его внимание.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сразите Тетура с помощью мортир.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Защитить доки Терамора от Тетура',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к майору Миллзу на остров Терамор в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27223,'Воздаяние','Убейте Непрощенного и Тимми Беспощадного.','Думаю, это станет тебе достойной наградой. Нашел тут в броне одного из воинов Плети.','Вернитесь к командиру Элигору Вестнику Рассвета.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Воздаяние',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Непрощенного и Тимми Беспощадного.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Думаю, это станет тебе достойной наградой. Нашел тут в броне одного из воинов Плети.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру Элигору Вестнику Рассвета.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (27224,'Знамя Андорала') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Знамя Андорала',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27225,'Я рад, что ты получил мое послание. Нам нужно обсудить кое-что важное.','Поговорите с Сигнильдой Твердогорн в тренировочном зале Штормграда.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я рад, что ты получил мое послание. Нам нужно обсудить кое-что важное.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Сигнильдой Твердогорн в тренировочном зале Штормграда.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27226,'Живительная влага','Слава Вождю, что ты здесь, $n. Я совершил ужасную ошибку, и мне нужна твоя помощь, чтобы все исправить.$B$BВидишь ли, я отправил своих вояк сражаться с воргенами острова Фенрис трезвыми как стеклышко. И что в итоге? Многие погибли... только единицы еще цепляются за жизнь.$B$BВозьми эту бочку эля и отнеси ее на Старую переправу к востоку отсюда, а там заставь сраженных моряков выпить как следует.','Приведите в чувство 8 орков-морских волков.','АГА! Я так и знал! Что ж, урок усвоен: больше таких ошибок не будет. Теперь без эля – на фронт ни шагу!','Вернитесь к полководцу Тороку в Гробницу в Серебряном бору.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Живительная влага',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слава Вождю, что ты здесь, $n. Я совершил ужасную ошибку, и мне нужна твоя помощь, чтобы все исправить.$B$BВидишь ли, я отправил своих вояк сражаться с воргенами острова Фенрис трезвыми как стеклышко. И что в итоге? Многие погибли... только единицы еще цепляются за жизнь.$B$BВозьми эту бочку эля и отнеси ее на Старую переправу к востоку отсюда, а там заставь сраженных моряков выпить как следует.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Приведите в чувство 8 орков-морских волков.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','АГА! Я так и знал! Что ж, урок усвоен: больше таких ошибок не будет. Теперь без эля – на фронт ни шагу!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к полководцу Тороку в Гробницу в Серебряном бору.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27227,'Лорд Аурий Ривендер','Убейте лорда Аурия Ривендера.','Вернитесь к командиру Элигору Вестнику Рассвета.','Он слишком низко пал, чтобы позволить ему подняться.','Лорд Аурий Ривендер') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лорд Аурий Ривендер',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте лорда Аурия Ривендера.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру Элигору Вестнику Рассвета.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Он слишком низко пал, чтобы позволить ему подняться.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Лорд Аурий Ривендер',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27228,'Человек против чудовища','В городе ты встретишь Рамштайна Ненасытного. Мне не хватит духа описать тебе все зверства, которые совершил этот монстр. Знай лишь одно: он заслуживает того, чтобы испытать весь гнев несчетных загубленных душ, который ты на него обрушишь.$B$BНикакой пощады. Дай волю своей ярости.','Прикончите Рамштайна Ненасытного.','Вернитесь к командиру рыцарей Корфаксу.','Резня!','Рамштайн Ненасытный') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Человек против чудовища',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В городе ты встретишь Рамштайна Ненасытного. Мне не хватит духа описать тебе все зверства, которые совершил этот монстр. Знай лишь одно: он заслуживает того, чтобы испытать весь гнев несчетных загубленных душ, который ты на него обрушишь.$B$BНикакой пощады. Дай волю своей ярости.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Прикончите Рамштайна Ненасытного.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру рыцарей Корфаксу.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Резня!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Рамштайн Ненасытный',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`) VALUES (27229,'ГРОХНИ КОРОЛЕВУ','<Следующее сообщение написано очень большими буквами.>$B$BПАУКИ В СЕВЕРНОЙ ПЕЩЕРЕ ПЛОХИЕ. КУСАТЬ ОГРЫ. ОГРЫ БОЛЕТЬ. ПЛОХИЕ!$B$BБОЛЬШОЙ ПАУК В ПЕЩЕРЕ ДЕЛАЕТ ЕЩЕ ПАУКИ. ЕЩЕ ПАУКИ ПЛОХО!$B$BУБИТЬ БОЛЬШИЕ ПАУКИ, НЕ НАДО ЕЩЕ ПАУКИ. КТО УБИТЬ БОЛЬШОЙ ПАУК, ПОЛУЧАТЬ БОЛЬШАЯ НАГРАДА! ХОРОШАЯ!$B$B<Ниже – грубый рисунок.>','Добудьте педипальпу королевы.','Ты здесь из-за вывески?$B$BНе буду с тобой говорить, пока не покажешь, что умеешь убивать.','Вернитесь к Крогу в деревню Гиблотопь в Пылевых топях.','НУЖНО С НЕЙ ПОКОНЧИТЬ','Королева пауков Мглистой пещеры','ПЛОХАЯ ПАУЧИХА!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','ГРОХНИ КОРОЛЕВУ',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Следующее сообщение написано очень большими буквами.>$B$BПАУКИ В СЕВЕРНОЙ ПЕЩЕРЕ ПЛОХИЕ. КУСАТЬ ОГРЫ. ОГРЫ БОЛЕТЬ. ПЛОХИЕ!$B$BБОЛЬШОЙ ПАУК В ПЕЩЕРЕ ДЕЛАЕТ ЕЩЕ ПАУКИ. ЕЩЕ ПАУКИ ПЛОХО!$B$BУБИТЬ БОЛЬШИЕ ПАУКИ, НЕ НАДО ЕЩЕ ПАУКИ. КТО УБИТЬ БОЛЬШОЙ ПАУК, ПОЛУЧАТЬ БОЛЬШАЯ НАГРАДА! ХОРОШАЯ!$B$B<Ниже – грубый рисунок.>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте педипальпу королевы.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты здесь из-за вывески?$B$BНе буду с тобой говорить, пока не покажешь, что умеешь убивать.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Крогу в деревню Гиблотопь в Пылевых топях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','НУЖНО С НЕЙ ПОКОНЧИТЬ',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Королева пауков Мглистой пещеры',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','ПЛОХАЯ ПАУЧИХА!',`questturntextwindow_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27230,'Вооружение','Плеть изрядно поднаторела в ковке смертоносного оружия для своих воинов. Нашим солдатам все труднее их одолеть! Возле зиккурата баронессы Анастари хранятся чертежи, по которым их главный оружейник изготовит невероятно мощное оружие для барона Ривендера.$B$BМы не дадим этому случиться и прервем поставки оружия Плети одним махом! Похить чертежи, а когда явится оружейник Черной Стражи, чтобы помешать, срази его. Этим ты здорово нам поможешь.','Убейте оружейника Черной Стражи.','Прекрасно! Раз они лишены бесперебойных поставок оружия, мы без труда победим!','Вернитесь к мастеру-ремесленнику Вильгельму.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вооружение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Плеть изрядно поднаторела в ковке смертоносного оружия для своих воинов. Нашим солдатам все труднее их одолеть! Возле зиккурата баронессы Анастари хранятся чертежи, по которым их главный оружейник изготовит невероятно мощное оружие для барона Ривендера.$B$BМы не дадим этому случиться и прервем поставки оружия Плети одним махом! Похить чертежи, а когда явится оружейник Черной Стражи, чтобы помешать, срази его. Этим ты здорово нам поможешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте оружейника Черной Стражи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно! Раз они лишены бесперебойных поставок оружия, мы без труда победим!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру-ремесленнику Вильгельму.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questgivertextwindow_loc8`) VALUES (27232,'И вода обратилась в кровь...','<Пульт связи гудит.>$B$BУбитые тобой воргены были разведывательным отрядом. За ними идут сотни! Похоже, Краули и Кровавый Клык принесли в жертву всех людей Лордерона.$B$BЗалезай на одну из этих пушек Орды и отправь всех врагов назад – к их создателям. Пусть воды озера Лордамер станут багровыми от их крови!','Уничтожьте 50 хилсбрадских воргенов при помощи пушки Орды.','Воды озера Лордамер обагрятся кровью воргенов!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','И вода обратилась в кровь...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Пульт связи гудит.>$B$BУбитые тобой воргены были разведывательным отрядом. За ними идут сотни! Похоже, Краули и Кровавый Клык принесли в жертву всех людей Лордерона.$B$BЗалезай на одну из этих пушек Орды и отправь всех врагов назад – к их создателям. Пусть воды озера Лордамер станут багровыми от их крови!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 50 хилсбрадских воргенов при помощи пушки Орды.',`objectives_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Воды озера Лордамер обагрятся кровью воргенов!',`questgivertextwindow_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27233,'Участок Целителей Земли','Теперь я и сам с тренировками справлюсь. А ты, если ищешь чем заняться, отправляйся прямиком на северо-запад – друиды Кенария и члены Серебряного Авангарда разбили у старой Фермы Далсона небольшой лагерь. Может, они тебя чем-нибудь займут до тех пор, пока нам снова не понадобится твоя помощь.','Отчитайтесь перед агентом ШРУ Каартишем на Участке Целителей Земли в Западных Чумных землях.','Поговорите с агентом ШРУ Каартишем на Участке Целителей Земли в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Участок Целителей Земли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь я и сам с тренировками справлюсь. А ты, если ищешь чем заняться, отправляйся прямиком на северо-запад – друиды Кенария и члены Серебряного Авангарда разбили у старой Фермы Далсона небольшой лагерь. Может, они тебя чем-нибудь займут до тех пор, пока нам снова не понадобится твоя помощь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отчитайтесь перед агентом ШРУ Каартишем на Участке Целителей Земли в Западных Чумных землях.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с агентом ШРУ Каартишем на Участке Целителей Земли в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertargetname_loc8`) VALUES (27234,'Братство Справедливости в Пылевых топях?','<Капитан Ваймор берет у вас приказы и внимательно их просматривает.>$B$BИ что за "ценный груз" такой? Братство Справедливости помаленьку занималось контрабандой еще в Штормграде, но это что-то из ряда вон выходящее. Судя по этим документам, ими руководит кто-то из богатых и благородных.','Удалось выследить главаря?','Вернитесь к капитану Ваймору на Сторожевой пост в Пылевых топях.','Гарн Маферс') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Братство Справедливости в Пылевых топях?',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Капитан Ваймор берет у вас приказы и внимательно их просматривает.>$B$BИ что за "ценный груз" такой? Братство Справедливости помаленьку занималось контрабандой еще в Штормграде, но это что-то из ряда вон выходящее. Судя по этим документам, ими руководит кто-то из богатых и благородных.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось выследить главаря?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Ваймору на Сторожевой пост в Пылевых топях.',`completedtext_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Гарн Маферс',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (27235,'Ренн Макжабр','Вернитесь к Ренну МакЖабру на Зловещий берег в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ренн Макжабр',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ренну МакЖабру на Зловещий берег в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27236,'Старое водолазное снаряжение','М-да... состояние плачевное... Я думал, что будет получше. И инструменты... ну ладно.$B$BЯ обещал починить снаряжение, и я его починю. Вот прямо сейчас и займусь.','Ну-ка, посмотрим, что тебе удалось "позаимствовать" у Братства.','Вернитесь к Ренну МакЖабру на Зловещий берег в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Старое водолазное снаряжение',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','М-да... состояние плачевное... Я думал, что будет получше. И инструменты... ну ладно.$B$BЯ обещал починить снаряжение, и я его починю. Вот прямо сейчас и займусь.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну-ка, посмотрим, что тебе удалось "позаимствовать" у Братства.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ренну МакЖабру на Зловещий берег в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27237,'Вернуть груз!','Ну что ж, я кое-как заштопал снаряжение, так что немного понырять ты сможешь. Но особо долго сидеть под водой не советую.$B$BОбломки корабля разбросаны по дну, начиная от восточного побережья этого острова и до самого острова Алькац. Пока шлем держится, походи по дну между островами и поищи обломки, а потом попытайся извлечь из них груз с помощью этого набора спасателя. Но слишком близко к Алькацу не подходи, а то тебя там гидры сожрут.','<Ренн копается в содержимом сейфов, которые вы нашли.>$B$BТы молодец. Посмотрим, что это за ценный груз такой...','Ну что, нашлось какое-нибудь добро Братства Справедливости?','Вернитесь к Ренну МакЖабру на Зловещий берег в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вернуть груз!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну что ж, я кое-как заштопал снаряжение, так что немного понырять ты сможешь. Но особо долго сидеть под водой не советую.$B$BОбломки корабля разбросаны по дну, начиная от восточного побережья этого острова и до самого острова Алькац. Пока шлем держится, походи по дну между островами и поищи обломки, а потом попытайся извлечь из них груз с помощью этого набора спасателя. Но слишком близко к Алькацу не подходи, а то тебя там гидры сожрут.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Ренн копается в содержимом сейфов, которые вы нашли.>$B$BТы молодец. Посмотрим, что это за ценный груз такой...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, нашлось какое-нибудь добро Братства Справедливости?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ренну МакЖабру на Зловещий берег в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27238,'Джайна должна быть в курсе','Ты $gдолжен:должна; как можно скорее сообщить леди Джайне то, что нам удалось узнать! Бандиты перевозили пленника – неизвестно, кто это был и жив ли он сейчас!$B$BНо в одном нет сомнений, $n. Эти бандюги в петлю по мелочам не полезут. Наверняка пленник очень важная персона. Леди Джайна должна знать об этом больше, чем кто-либо другой. Найди ее на вершине башни магов в центре Терамора.','Поговорите с леди Джайной Праудмур в Тераморе.','Вы с Ренном просто молодцы – раскопали такие сведения и тотчас доложили мне. Теперь мы должны найти подтверждение этой информации. Ставки слишком высоки, мы не имеем права на ошибку.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Джайна должна быть в курсе',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gдолжен:должна; как можно скорее сообщить леди Джайне то, что нам удалось узнать! Бандиты перевозили пленника – неизвестно, кто это был и жив ли он сейчас!$B$BНо в одном нет сомнений, $n. Эти бандюги в петлю по мелочам не полезут. Наверняка пленник очень важная персона. Леди Джайна должна знать об этом больше, чем кто-либо другой. Найди ее на вершине башни магов в центре Терамора.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с леди Джайной Праудмур в Тераморе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы с Ренном просто молодцы – раскопали такие сведения и тотчас доложили мне. Теперь мы должны найти подтверждение этой информации. Ставки слишком высоки, мы не имеем права на ошибку.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (27239,'Исследование острова Алькац','Поговорите с Коссой Багровое Крыло и возьмите одного из ее грифонов, чтобы исследовать остров Алькац.','<Леди Джайна внимательно слушает ваш рассказ о результатах воздушной разведки.>$B$BРунический круг, драконоры? Так Братство Справедливости сотрудничало С НЕЙ? С предательницей?$B$B<Леди Джайна собирается с духом и готовится разъяснить вам ситуацию.>','Остров Алькац исследован','Вернитесь к леди Джайне Праудмур на остров Терамор в Пылевые топи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Исследование острова Алькац',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Коссой Багровое Крыло и возьмите одного из ее грифонов, чтобы исследовать остров Алькац.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Леди Джайна внимательно слушает ваш рассказ о результатах воздушной разведки.>$B$BРунический круг, драконоры? Так Братство Справедливости сотрудничало С НЕЙ? С предательницей?$B$B<Леди Джайна собирается с духом и готовится разъяснить вам ситуацию.>',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Остров Алькац исследован',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к леди Джайне Праудмур на остров Терамор в Пылевые топи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (27240,'Доказательство предательства','Значит, это Братство Справедливости вершило волю Ониксии?$B$B<Лицо короля багровеет от гнева, он стискивает кулаки.>$B$BВы с леди Джайной сослужили великую службу Штормграду. Предатели не успеют даже пожалеть о своих преступлениях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Доказательство предательства',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Значит, это Братство Справедливости вершило волю Ониксии?$B$B<Лицо короля багровеет от гнева, он стискивает кулаки.>$B$BВы с леди Джайной сослужили великую службу Штормграду. Предатели не успеют даже пожалеть о своих преступлениях.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27241,'Возвращение к Джайне','Вернитесь к леди Джайне Праудмур в Терамор.','Я не сомневалась, что король раз и навсегда расправится с Братством Справедливости. Он слов на ветер не бросает, о чем всегда стоит помнить врагам Штормграда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение к Джайне',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь к леди Джайне Праудмур в Терамор.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я не сомневалась, что король раз и навсегда расправится с Братством Справедливости. Он слов на ветер не бросает, о чем всегда стоит помнить врагам Штормграда.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27243,'Боевые ящеры','Так, у нас есть ящеры, теперь их нужно как-то "воодушевить" на бой, чтобы они атаковали тауренов из племени Зловещего Тотема в деревне Черного Копыта на северо-западе.$B$BВот тут у меня остатки мяса... э-э... в общем, не важно, чье это мясо. Главное, что оно будет хорошей приманкой. Положи его на землю в деревне Черного копыта, рядом с мельницей в центре поселка. А об остальном позаботятся ящеры.','Положите приманку для ящеров рядом с мельницей в деревне Черного Копыта.','<Сержант не скрывает довольной усмешки.>$B$BВот и славно. Теперь они дважды подумают, прежде чем совершить очередной набег.','Вернитесь к сержанту Лукасу в Северную башню в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Боевые ящеры',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Так, у нас есть ящеры, теперь их нужно как-то "воодушевить" на бой, чтобы они атаковали тауренов из племени Зловещего Тотема в деревне Черного Копыта на северо-западе.$B$BВот тут у меня остатки мяса... э-э... в общем, не важно, чье это мясо. Главное, что оно будет хорошей приманкой. Положи его на землю в деревне Черного копыта, рядом с мельницей в центре поселка. А об остальном позаботятся ящеры.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Положите приманку для ящеров рядом с мельницей в деревне Черного Копыта.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Сержант не скрывает довольной усмешки.>$B$BВот и славно. Теперь они дважды подумают, прежде чем совершить очередной набег.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к сержанту Лукасу в Северную башню в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`) VALUES (27244,'Потерянный рапорт','Мы просеивали землю и нашли в ней отрубленную руку орка, сжимающую резную костяную трубку. А в трубке был заляпанный грязью пергамент.$B$BЭто донесение шпиона, который провел многие недели в Тераморе.$B$BРасшифровав записи, мы выяснили, что это донесение предназначалось командиру орков-разведчиков в деревне Гиблотопь.','Ты хочешь мне что-то отдать?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Потерянный рапорт',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы просеивали землю и нашли в ней отрубленную руку орка, сжимающую резную костяную трубку. А в трубке был заляпанный грязью пергамент.$B$BЭто донесение шпиона, который провел многие недели в Тераморе.$B$BРасшифровав записи, мы выяснили, что это донесение предназначалось командиру орков-разведчиков в деревне Гиблотопь.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты хочешь мне что-то отдать?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (27246,'Орочий рапорт','Мы просеивали землю и нашли в ней отрубленную руку орка, сжимающую резную костяную трубку. А в трубке был заляпанный грязью пергамент.$B$BДонесение написано на орочьем... И, похоже, важное...','Доставьте донесение шпиона лейтенанту Адену в Терамор.','Хм... Я плохо знаю орочий, но это похоже на рапорт орочьего шпиона!','Ты хочешь что-то сообщить?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Орочий рапорт',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы просеивали землю и нашли в ней отрубленную руку орка, сжимающую резную костяную трубку. А в трубке был заляпанный грязью пергамент.$B$BДонесение написано на орочьем... И, похоже, важное...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте донесение шпиона лейтенанту Адену в Терамор.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хм... Я плохо знаю орочий, но это похоже на рапорт орочьего шпиона!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты хочешь что-то сообщить?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27247,'Капитан Ваймс','Донесение, которое ты $gнашел:нашла;, надо показать капитану Ваймсу, $n. Он лучше всех знает язык орков. И нужно поставить его в известность, что у Терамора рыскают шпионы Орды!$B$BКапитан сейчас в казармах на северо-восточной стороне острова Терамор.','Отнесите шпионское донесение капитану Гаррану Ваймсу.','Это донесение шпиона орков! Как оно у тебя оказалось? Хотя ладно – давай посмотрим, что там говорится...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Капитан Ваймс',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Донесение, которое ты $gнашел:нашла;, надо показать капитану Ваймсу, $n. Он лучше всех знает язык орков. И нужно поставить его в известность, что у Терамора рыскают шпионы Орды!$B$BКапитан сейчас в казармах на северо-восточной стороне острова Терамор.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите шпионское донесение капитану Гаррану Ваймсу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это донесение шпиона орков! Как оно у тебя оказалось? Хотя ладно – давай посмотрим, что там говорится...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27248,'Миссия в Шестермуть','Картель Хитрой Шестеренки недавно построил новый форпост в южной части Пылевых топей. Называется он вроде Шестермуть и расположен на главной дороге к югу от домика Табеты и руин деревни Каменного Молота.$B$BЭто прекрасная возможность завести новые торговые отношения, и леди Джайна хочет, чтобы я отправил туда представителя для налаживания контактов. Возьмешься?','Поговорите с Драззитом Кранотеком в Шестермути.','Значит, Терамор хочет наладить с нами деловые отношения? Ну, от такого предложения не отказываются. Сейчас у нас как раз жутко не хватает провианта, так что мы рады любым бизнес-контактам!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Миссия в Шестермуть',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Картель Хитрой Шестеренки недавно построил новый форпост в южной части Пылевых топей. Называется он вроде Шестермуть и расположен на главной дороге к югу от домика Табеты и руин деревни Каменного Молота.$B$BЭто прекрасная возможность завести новые торговые отношения, и леди Джайна хочет, чтобы я отправил туда представителя для налаживания контактов. Возьмешься?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Драззитом Кранотеком в Шестермути.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Значит, Терамор хочет наладить с нами деловые отношения? Ну, от такого предложения не отказываются. Сейчас у нас как раз жутко не хватает провианта, так что мы рады любым бизнес-контактам!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27249,'Исследование пепелища','Поговорите с инспектором Таремом у трактира "Последний привал".','Я рад, что капитан Ваймс наконец-то и других привлек к этому делу.$B$BЯ здесь все посыпал отражательным порошком – с его помощью можно увидеть подозрительные предметы и знаки и здорово сэкономить время. Иди и собери все, что светится от этой пыли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Исследование пепелища',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с инспектором Таремом у трактира "Последний привал".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я рад, что капитан Ваймс наконец-то и других привлек к этому делу.$B$BЯ здесь все посыпал отражательным порошком – с его помощью можно увидеть подозрительные предметы и знаки и здорово сэкономить время. Иди и собери все, что светится от этой пыли.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27250,'REUSE - BAD COPY','Перед тем, как перебраться сюда, в "Печальный отшельник", я обучался, у одного из лучших поваров которых я когда-либо встречал. Его звали Джеймс Хьяль, и все чего я добился в этой жизни, это только благодаря ему.$B$BИнтересно, как-то он там сейчас? Они вместе со своим братом Винсентом работали в таверне, в Гавани Менетилов, но я давно о нем ничего не слышал.$B$BЕсли вдруг ненароком встретишь его, кланяйся от меня.','Поговорите с Винсентом Хьялем в Гавани Менетилов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','REUSE - BAD COPY',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Перед тем, как перебраться сюда, в "Печальный отшельник", я обучался, у одного из лучших поваров которых я когда-либо встречал. Его звали Джеймс Хьяль, и все чего я добился в этой жизни, это только благодаря ему.$B$BИнтересно, как-то он там сейчас? Они вместе со своим братом Винсентом работали в таверне, в Гавани Менетилов, но я давно о нем ничего не слышал.$B$BЕсли вдруг ненароком встретишь его, кланяйся от меня.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Винсентом Хьялем в Гавани Менетилов.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (27251,'Его зовут Улыбка Джим','Его настоящее имя – Джеймс Хьяль. Он открыл таверну на самой окраине Степей, чтобы там могли останавливаться путешественники. $B$BНаверное, слишком широко замахнулся, хотя поначалу дела в таверне шли хорошо. Потом мы потеряли контроль над дорогами через болота, и здесь появились огры.$B$BУпрямый Джеймс отказался бросить свою мечту ради безопасности. Таверна "Последний привал" сгорела дотла. Мы пытались разобраться в этом деле, но ничего не вышло. Если хочешь помочь, посмотри, вдруг найдешь что-нибудь на развалинах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Его зовут Улыбка Джим',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Его настоящее имя – Джеймс Хьяль. Он открыл таверну на самой окраине Степей, чтобы там могли останавливаться путешественники. $B$BНаверное, слишком широко замахнулся, хотя поначалу дела в таверне шли хорошо. Потом мы потеряли контроль над дорогами через болота, и здесь появились огры.$B$BУпрямый Джеймс отказался бросить свою мечту ради безопасности. Таверна "Последний привал" сгорела дотла. Мы пытались разобраться в этом деле, но ничего не вышло. Если хочешь помочь, посмотри, вдруг найдешь что-нибудь на развалинах.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (27252,'Черный щит','Железный щит, почерневший от бушевавшего в гостинице пламени, висит на треснувшей трубе – это почти все, что уцелело от "Последнего привала".$B$BЩит можно снять с кирпичного дымохода.','Отнесите почерневший железный щит капитану Гаррану Ваймсу в Терамор.','Хм, я не слишком разбираюсь в оружии и доспехах. То есть, конечно, знаю, как с ними обращаться, но в ковке полный профан.$B$BПо мне, этот щит совсем обычный, разве что от пожара почернел.','Тебе удалось найти какие-нибудь улики в развалинах "Последнего приюта"?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Черный щит',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Железный щит, почерневший от бушевавшего в гостинице пламени, висит на треснувшей трубе – это почти все, что уцелело от "Последнего привала".$B$BЩит можно снять с кирпичного дымохода.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите почерневший железный щит капитану Гаррану Ваймсу в Терамор.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хм, я не слишком разбираюсь в оружии и доспехах. То есть, конечно, знаю, как с ними обращаться, но в ковке полный профан.$B$BПо мне, этот щит совсем обычный, разве что от пожара почернел.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось найти какие-нибудь улики в развалинах "Последнего приюта"?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27253,'Исследование пепелища','Если отправишься из деревни по дороге на юг, а затем свернешь на запад к Степям, выйдешь на пепелище таверны "Последний привал".$B$BТерамор направил туда следователя разобраться, с чего это вдруг сгорела таверна. Посылал я туда шпиона... Не верю, что людишки могут там все выяснить.$B$BЗначит так! Что бы ты там ни $gобнаружил:обнаружила;, ни слова следователю. Мы сами во всем разберемся.','Исследуйте пепелище таверны "Последний привал" на границе Степей и Пылевых топей.','<Следователь смотрит на вас недоверчиво и высокомерно.>$B$BПокинь это место, мальчик на побегушках, иначе в следующий раз возьму с собой отряд стражников, чтобы до тебя дошло.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Исследование пепелища',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если отправишься из деревни по дороге на юг, а затем свернешь на запад к Степям, выйдешь на пепелище таверны "Последний привал".$B$BТерамор направил туда следователя разобраться, с чего это вдруг сгорела таверна. Посылал я туда шпиона... Не верю, что людишки могут там все выяснить.$B$BЗначит так! Что бы ты там ни $gобнаружил:обнаружила;, ни слова следователю. Мы сами во всем разберемся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Исследуйте пепелище таверны "Последний привал" на границе Степей и Пылевых топей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Следователь смотрит на вас недоверчиво и высокомерно.>$B$BПокинь это место, мальчик на побегушках, иначе в следующий раз возьму с собой отряд стражников, чтобы до тебя дошло.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27254,'Черный щит','Железный щит, почерневший от бушевавшего в гостинице пламени, висит на треснувшей трубе – это почти все, что уцелело от "Последнего привала".$B$BЩит можно снять с кирпичного дымохода.','Отнесите почерневший железный щит Крогу в деревню Гиблотопь.','Люди всегда отличались странными вкусами в области украшательства. Но на кой вешать над камином простой металлический щит? Может, его повесили туда те, кто спалил таверну?$B$BПредупреждение? Угроза?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Черный щит',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Железный щит, почерневший от бушевавшего в гостинице пламени, висит на треснувшей трубе – это почти все, что уцелело от "Последнего привала".$B$BЩит можно снять с кирпичного дымохода.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите почерневший железный щит Крогу в деревню Гиблотопь.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Люди всегда отличались странными вкусами в области украшательства. Но на кой вешать над камином простой металлический щит? Может, его повесили туда те, кто спалил таверну?$B$BПредупреждение? Угроза?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27255,'Черный щит','Хм... Не вижу в этом щите ничего необычного. Нужно попросить взглянуть на него До\'гола, нашего кузнеца. Может быть, До\'гол что-нибудь скажет, хотя я бы не надеялся на это...','Покажите потемневший железный щит До\'голу из деревни Гиблотопь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Черный щит',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хм... Не вижу в этом щите ничего необычного. Нужно попросить взглянуть на него До\'гола, нашего кузнеца. Может быть, До\'гол что-нибудь скажет, хотя я бы не надеялся на это...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Покажите потемневший железный щит До\'голу из деревни Гиблотопь.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27256,'Черный щит','Хм... А на ободе щита, оказывается, что-то написано, но прочитать трудно, все обгорело.$B$BЧтобы отчистить надпись, мне нужна кислота – подойдет яд пауков Мглистой пещеры. Эти пауки водятся в старых копях – Мглистой пещере к северо-западу от деревни. Принеси немного их ядовитых желез, и я почищу щит.','Добудьте 5 ядовитых желез паука Мглистой пещеры для До\'гола из деревни Гиблотопь.','Ты добыла яд этих пауков?','Вернитесь к До\'голу в деревню Гиблотопь в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Черный щит',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хм... А на ободе щита, оказывается, что-то написано, но прочитать трудно, все обгорело.$B$BЧтобы отчистить надпись, мне нужна кислота – подойдет яд пауков Мглистой пещеры. Эти пауки водятся в старых копях – Мглистой пещере к северо-западу от деревни. Принеси немного их ядовитых желез, и я почищу щит.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 5 ядовитых желез паука Мглистой пещеры для До\'гола из деревни Гиблотопь.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты добыла яд этих пауков?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к До\'голу в деревню Гиблотопь в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27257,'Черный щит','Ох, кажется, я налил на щит слишком много кислоты. Так, а если потереть...$B$BХм, плохо видно, но вроде тут написано имя – Мозарн. Первый раз слышу. Может, Крог знает. Крог вообще много кого знает.','Поговорите с Крогом в деревне Гиблотопь.','Мозарн? Вроде что-то знакомое... Может, потом вспомню.$B$BДа вполне возможно, что это вообще ерунда какая-то. Щит мог взяться откуда угодно.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Черный щит',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ох, кажется, я налил на щит слишком много кислоты. Так, а если потереть...$B$BХм, плохо видно, но вроде тут написано имя – Мозарн. Первый раз слышу. Может, Крог знает. Крог вообще много кого знает.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Крогом в деревне Гиблотопь.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мозарн? Вроде что-то знакомое... Может, потом вспомню.$B$BДа вполне возможно, что это вообще ерунда какая-то. Щит мог взяться откуда угодно.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27258,'Черный щит','А, теперь вспомнил! Мозарн – весьма почтенный кузнец из Громового Утеса. Ведь помню, что уже слышал где-то это имя.$B$BВ благодарность Служители Земли наградили меня комплектом доспехов работы Мозарна. Отличная, доложу, работа.$B$BВозможно, он расскажет тебе побольше о щите, который сам и сделал.$B$BНе слишком большая зацепка, но раз уж мы ничего полезного не узнали от Рита, то другой у нас и нет.','Покажите почерневший железный щит Мозарну в Громовом Утесе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Черный щит',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А, теперь вспомнил! Мозарн – весьма почтенный кузнец из Громового Утеса. Ведь помню, что уже слышал где-то это имя.$B$BВ благодарность Служители Земли наградили меня комплектом доспехов работы Мозарна. Отличная, доложу, работа.$B$BВозможно, он расскажет тебе побольше о щите, который сам и сделал.$B$BНе слишком большая зацепка, но раз уж мы ничего полезного не узнали от Рита, то другой у нас и нет.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Покажите почерневший железный щит Мозарну в Громовом Утесе.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (27259,'Подозрительные отпечатки копыт','Следы копыт... Это мог быть свинобраз, а может, даже кентавр. В Степях их водится довольно много, думаю, стоит признать это как факт.$B$BТы, кстати, знаешь, что одним сгоревшим трактиром дело не обошлось? Еще убили жену хозяина и его отпрыска. Это очень плохо.$B$BНо как бы то ни было, я отправлю Кагоро узнать, куда ведут те следы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подозрительные отпечатки копыт',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Следы копыт... Это мог быть свинобраз, а может, даже кентавр. В Степях их водится довольно много, думаю, стоит признать это как факт.$B$BТы, кстати, знаешь, что одним сгоревшим трактиром дело не обошлось? Еще убили жену хозяина и его отпрыска. Это очень плохо.$B$BНо как бы то ни было, я отправлю Кагоро узнать, куда ведут те следы.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (27260,'Лейтенант Павал Рит','Ваш взгляд привлекает какой-то блестящий предмет среди обломков на земле. Вы разгребаете камни и золу и находите значок с изображением золотого якоря на белом поле – это герб Терамора.$B$BПод якорем вытиснено имя "Лейтенант Павал Рит".','Отнесите значок Рита Крогу в деревню Гиблотопь.','Так, так... интересно.','Нашлась там в таверне "Последний привал" хоть какая-нибудь зацепка?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лейтенант Павал Рит',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ваш взгляд привлекает какой-то блестящий предмет среди обломков на земле. Вы разгребаете камни и золу и находите значок с изображением золотого якоря на белом поле – это герб Терамора.$B$BПод якорем вытиснено имя "Лейтенант Павал Рит".',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите значок Рита Крогу в деревню Гиблотопь.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так, так... интересно.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Нашлась там в таверне "Последний привал" хоть какая-нибудь зацепка?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27261,'Допрос Рита','Это было непросто, но я все-таки нашел этот Рит. Неплохо он прятаться... Для человек.$B$BОгрон боится, человек свихнуться – много время на болоте. Твоя идти с Огрон и спрашивать человек.','Пойдите с Огроном и поговорите с Ритом.','Хм-хм... Хорошо, что Рит больше не будет шнырять по болоту, но какой позор для людей – от пустякового ранения стрелой не удалось оправиться!$B$BПохоже, эта ниточка никуда не привела, и надо искать разгадку в другом месте.','Вернитесь к Крогу в деревню Гиблотопь в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Допрос Рита',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это было непросто, но я все-таки нашел этот Рит. Неплохо он прятаться... Для человек.$B$BОгрон боится, человек свихнуться – много время на болоте. Твоя идти с Огрон и спрашивать человек.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Пойдите с Огроном и поговорите с Ритом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хм-хм... Хорошо, что Рит больше не будет шнырять по болоту, но какой позор для людей – от пустякового ранения стрелой не удалось оправиться!$B$BПохоже, эта ниточка никуда не привела, и надо искать разгадку в другом месте.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Крогу в деревню Гиблотопь в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (27262,'Подозрительные отпечатки копыт','Следы копыт, говоришь? В последнее время в этих краях оживились кентавры. Наши разведчики во время вылазки в Степи заметили несколько их лагерей и поселений.$B$BЯ пошлю одного из наших охотников, Фальграна Гастила, посмотреть, куда ведут эти следы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подозрительные отпечатки копыт',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Следы копыт, говоришь? В последнее время в этих краях оживились кентавры. Наши разведчики во время вылазки в Степи заметили несколько их лагерей и поселений.$B$BЯ пошлю одного из наших охотников, Фальграна Гастила, посмотреть, куда ведут эти следы.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (27263,'Лейтенант Павал Рит','Ваш взгляд привлекает какой-то блестящий предмет среди обломков на земле. Вы разгребаете камни и золу и находите значок с изображением золотого якоря на белом поле – это герб Терамора.$B$BПод якорем вытиснено имя "Лейтенант Павал Рит".','Отнесите значок Рита капитану Гаррану Ваймсу в Терамор.','Когда мне приносят значок кого-то из стражей – это всегда печальная весть.$B$BИногда это значит, что кто-то из наших пал в битве, и мне нужно как-то сказать об этом его семье. Иногда нам вообще не удается узнать, что случилось. А иной раз бывает еще хуже...','Нашлось там в таверне "Последний привал" что-нибудь интересное?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лейтенант Павал Рит',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ваш взгляд привлекает какой-то блестящий предмет среди обломков на земле. Вы разгребаете камни и золу и находите значок с изображением золотого якоря на белом поле – это герб Терамора.$B$BПод якорем вытиснено имя "Лейтенант Павал Рит".',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите значок Рита капитану Гаррану Ваймсу в Терамор.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Когда мне приносят значок кого-то из стражей – это всегда печальная весть.$B$BИногда это значит, что кто-то из наших пал в битве, и мне нужно как-то сказать об этом его семье. Иногда нам вообще не удается узнать, что случилось. А иной раз бывает еще хуже...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Нашлось там в таверне "Последний привал" что-нибудь интересное?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27264,'Лейтенант Павал Рит','Лейтенант Павал Рит? Что-то не припоминаю. Поговори лучше с адъютантом Тезораном. У него хранятся все сведения о тераморской страже – от имен стражников до описи их вооружения.$B$BОн быстренько заглянет в архив и расскажет тебе об этом Рите.','Поговорите о Рите с адъютантом Тезораном в Тераморе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лейтенант Павал Рит',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Лейтенант Павал Рит? Что-то не припоминаю. Поговори лучше с адъютантом Тезораном. У него хранятся все сведения о тераморской страже – от имен стражников до описи их вооружения.$B$BОн быстренько заглянет в архив и расскажет тебе об этом Рите.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите о Рите с адъютантом Тезораном в Тераморе.',`objectives_loc8`);
