INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27269,'Храм Луны','У меня срочное сообщение из Дарнаса. Сама Тиранда Шелест Ветра, верховная жрица Элуны, просит тебя о встрече! Посланник не сказал, что конкретно она хочет обсудить, но тебе нужно отправиться в Храм Луны Дарнаса как можно скорее.','Поговорите с Тирандой Шелест Ветра в Храме Луны в Дарнасе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Храм Луны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У меня срочное сообщение из Дарнаса. Сама Тиранда Шелест Ветра, верховная жрица Элуны, просит тебя о встрече! Посланник не сказал, что конкретно она хочет обсудить, но тебе нужно отправиться в Храм Луны Дарнаса как можно скорее.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Тирандой Шелест Ветра в Храме Луны в Дарнасе.',`objectives_loc8`);
