INSERT INTO `locales_quest` (`id`,`completedtext_loc8`) VALUES (27282,'Поговорите с Казаком Темным Криком в казармах Оргриммара.') ON DUPLICATE KEY UPDATE `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Казаком Темным Криком в казармах Оргриммара.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27283,'Путешествие в Лунную поляну','Как ты наверняка $gслышал:слышала;, Лунная поляна – пристанище братства друидов Круга Кенария. Все обитатели Лунной поляны находятся под их защитой. Один из наставников Круга, Логанаар, попросил тебя о встрече.$B$BНайти его можно в деревне Ночная Гавань.','Поговорите с Логанааром в деревне Ночная Гавань.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путешествие в Лунную поляну',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как ты наверняка $gслышал:слышала;, Лунная поляна – пристанище братства друидов Круга Кенария. Все обитатели Лунной поляны находятся под их защитой. Один из наставников Круга, Логанаар, попросил тебя о встрече.$B$BНайти его можно в деревне Ночная Гавань.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Логанааром в деревне Ночная Гавань.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (27284,'Черный щит','Увы, не смогу помочь тебе, $n. Впрочем, я знаю, кто в силах это сделать. Каз Дваждыдвац – один из наших лучших кузнецов. Его можно найти в кузне.$B$BПокажи ему щит и послушай, что он скажет.','Покажите почерневший железный щит Казу Дваждыдвацу в Тераморе.','Хм... интересный кусок железа. Работа кузнеца явно не по эту сторону моря и уж точно не моя.','Хочешь мне что-то показать?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Черный щит',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Увы, не смогу помочь тебе, $n. Впрочем, я знаю, кто в силах это сделать. Каз Дваждыдвац – один из наших лучших кузнецов. Его можно найти в кузне.$B$BПокажи ему щит и послушай, что он скажет.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Покажите почерневший железный щит Казу Дваждыдвацу в Тераморе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хм... интересный кусок железа. Работа кузнеца явно не по эту сторону моря и уж точно не моя.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Хочешь мне что-то показать?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27285,'Черный щит','А, чуть не забыл... Кожаный ремешок внутри, наверное, отгорел, но, похоже, сделан он был на большую руку. Думаю, для таурена.$B$BПожалуй, это все, что я могу тебе сообщить. Скажи капитану Ваймсу, что мне жаль, но больше помочь ему нечем.','Поговорите с капитаном Гарраном Ваймсом в Тераморе.','Не так много сведений, но мы их учтем. Будем надеяться, остальные части головоломки встанут на место – и мы поймем, что случилось.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Черный щит',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А, чуть не забыл... Кожаный ремешок внутри, наверное, отгорел, но, похоже, сделан он был на большую руку. Думаю, для таурена.$B$BПожалуй, это все, что я могу тебе сообщить. Скажи капитану Ваймсу, что мне жаль, но больше помочь ему нечем.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с капитаном Гарраном Ваймсом в Тераморе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Не так много сведений, но мы их учтем. Будем надеяться, остальные части головоломки встанут на место – и мы поймем, что случилось.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27286,'Реддон... Редпат... Ага, вот! Лейтенант Павал Рит.$B$BЗачислен в стражу Терамора вместе с большинством рекрутов, прибывших из-за моря с госпожой Праудмур. Поступил на флот Кул-Тираса в возрасте шестнадцати лет. Нес службу исправно... несколько повышений...$B$BПропал без вести.','Сообщите информацию о Рите капитану Гаррану Ваймсу в Тераморе.','Пропал без вести? Это так Тезоран говорит о предателях!$B$BНе сомневаюсь, что он был среди тех идиотов, которые слепо присягнули адмиралу Даэлину, который сам всех предал. Ну разве не смешно? Дезертиры обвиняют нас в том, что мы предали Альянс.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Реддон... Редпат... Ага, вот! Лейтенант Павал Рит.$B$BЗачислен в стражу Терамора вместе с большинством рекрутов, прибывших из-за моря с госпожой Праудмур. Поступил на флот Кул-Тираса в возрасте шестнадцати лет. Нес службу исправно... несколько повышений...$B$BПропал без вести.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сообщите информацию о Рите капитану Гаррану Ваймсу в Тераморе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Пропал без вести? Это так Тезоран говорит о предателях!$B$BНе сомневаюсь, что он был среди тех идиотов, которые слепо присягнули адмиралу Даэлину, который сам всех предал. Ну разве не смешно? Дезертиры обвиняют нас в том, что мы предали Альянс.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27287,'Дезертиры','Удержаться на болотах было нелегко. Но все же мы возвели несколько оборонительных сторожевых башен в округе.$B$BПо последним донесениям разведчиков, группа дезертиров обосновалась в Разрушенной башне к юго-востоку от таверны. $B$BЗа главного у них, кажется, Балос Хакен. Посмотрим, получится ли вытянуть у него какие-нибудь сведения.$B$BНо будь с ним осторожнее, $n, он тертый вояка.','Расспросите о Рите Балоса Хакена и его дезертиров в Пылевых топях.','Тебя Ваймс прислал? Вечно он грязную работу на других перекладывает...','Балос Хакен, предводитель дезертиров','Балос Хакен') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дезертиры',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Удержаться на болотах было нелегко. Но все же мы возвели несколько оборонительных сторожевых башен в округе.$B$BПо последним донесениям разведчиков, группа дезертиров обосновалась в Разрушенной башне к юго-востоку от таверны. $B$BЗа главного у них, кажется, Балос Хакен. Посмотрим, получится ли вытянуть у него какие-нибудь сведения.$B$BНо будь с ним осторожнее, $n, он тертый вояка.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Расспросите о Рите Балоса Хакена и его дезертиров в Пылевых топях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебя Ваймс прислал? Вечно он грязную работу на других перекладывает...',`offerrewardtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Балос Хакен, предводитель дезертиров',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Балос Хакен',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27288,'Дезертиры','Рит? Этот трус?$B$BМы вышвырнули его из лагеря, потому что он настаивал на том, чтобы отправиться в деревню Гиблотопь и отнять у огров все припасы. Нас слишком мало, мы бы ни за что не справились с этими безмозглыми громилами.$B$BОн слишком часто зарывался, вот мы и отправили его восвояси.$B$BВидишь, я тебе помог. Может, ты нам тоже услугу окажешь – забудь, что вообще нас $gвидел:видела;.','Поговорите о Рите с капитаном Гарраном Ваймсом в Тераморе.','Я пошлю лейтенанта Келдвелла, пусть разберется с дезертирами в Разрушенной башне. А кроме того прикажу ему найти Рита. Болота не такие уж большие, там полно следов – думаю, он его отыщет.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дезертиры',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Рит? Этот трус?$B$BМы вышвырнули его из лагеря, потому что он настаивал на том, чтобы отправиться в деревню Гиблотопь и отнять у огров все припасы. Нас слишком мало, мы бы ни за что не справились с этими безмозглыми громилами.$B$BОн слишком часто зарывался, вот мы и отправили его восвояси.$B$BВидишь, я тебе помог. Может, ты нам тоже услугу окажешь – забудь, что вообще нас $gвидел:видела;.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите о Рите с капитаном Гарраном Ваймсом в Тераморе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я пошлю лейтенанта Келдвелла, пусть разберется с дезертирами в Разрушенной башне. А кроме того прикажу ему найти Рита. Болота не такие уж большие, там полно следов – думаю, он его отыщет.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27289,'Донесение Ваймса','Хорошая работа, $n. Для любителя просто отличная. $B$BЛеди Праудмур просила, чтобы я держал ее в курсе, но у меня некоторое время не было возможности с ней общаться.$B$BЯ собирался отправить ей рапорт позже, но, думаю, уместнее вместо этого послать к ней тебя. Ты куда лучше меня ответишь на все ее вопросы.','Отнесите донесение Ваймса леди Джайне Праудмур в Терамор.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Донесение Ваймса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хорошая работа, $n. Для любителя просто отличная. $B$BЛеди Праудмур просила, чтобы я держал ее в курсе, но у меня некоторое время не было возможности с ней общаться.$B$BЯ собирался отправить ей рапорт позже, но, думаю, уместнее вместо этого послать к ней тебя. Ты куда лучше меня ответишь на все ее вопросы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите донесение Ваймса леди Джайне Праудмур в Терамор.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27290,'Передовой отряд Отрекшихся','Пришло время покончить с Краули, Кровавым Клыком и всей их песьей сворой. Но для этого, конечно, нам потребуется такой хитрый план, который они никогда не сумеют разгадать!$B$BРаз ты, $n, один из самых доверенных моих солдат, я пошлю тебя в передовой отряд Отрекшихся в Гилнеасе. Там ты доложишься командиру ловчих смерти Бельмонту. Я отправила его вперед, и о моих планах ему известно. Он ждет.$B$BАртура проводит тебя до передового отряда. Сообщи, когда будешь $gготов:готова;, и я скажу, куда идти.','Доложитесь командиру ловчих смерти Бельмонту в передовом отряде Отрекшихся в Гилнеасе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Передовой отряд Отрекшихся',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пришло время покончить с Краули, Кровавым Клыком и всей их песьей сворой. Но для этого, конечно, нам потребуется такой хитрый план, который они никогда не сумеют разгадать!$B$BРаз ты, $n, один из самых доверенных моих солдат, я пошлю тебя в передовой отряд Отрекшихся в Гилнеасе. Там ты доложишься командиру ловчих смерти Бельмонту. Я отправила его вперед, и о моих планах ему известно. Он ждет.$B$BАртура проводит тебя до передового отряда. Сообщи, когда будешь $gготов:готова;, и я скажу, куда идти.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доложитесь командиру ловчих смерти Бельмонту в передовом отряде Отрекшихся в Гилнеасе.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27291,'Обрести покой','Как бы сообщить жене и сыну Джеймса Хьяля, что мы отомстили их убийцам?$B$B<Капитан Ваймс достает маленький венок.>$B$BГоворят, души все видят, хоть и не могут сказать об этом. Конечно, это такая малость, но если вы возложите этот венок на могилу семейства Хьяль, я буду вам очень благодарен. У них один из самых больших памятников на кладбище к северу от ворот Терамора.','<Капитан Ваймс мягко улыбается, слушая ваш рассказ о событиях, произошедших у памятника семейству Хьяль.>$B$BПриятно знать, что они все видят. Ты же не рассказала им о Джеймсе, правда?$B$BЯ отправлю ему послание жены, хотя сомневаюсь, что он поймет.','Вернитесь к капитану Гаррану Ваймсу в Цитадель в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обрести покой',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как бы сообщить жене и сыну Джеймса Хьяля, что мы отомстили их убийцам?$B$B<Капитан Ваймс достает маленький венок.>$B$BГоворят, души все видят, хоть и не могут сказать об этом. Конечно, это такая малость, но если вы возложите этот венок на могилу семейства Хьяль, я буду вам очень благодарен. У них один из самых больших памятников на кладбище к северу от ворот Терамора.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Капитан Ваймс мягко улыбается, слушая ваш рассказ о событиях, произошедших у памятника семейству Хьяль.>$B$BПриятно знать, что они все видят. Ты же не рассказала им о Джеймсе, правда?$B$BЯ отправлю ему послание жены, хотя сомневаюсь, что он поймет.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Гаррану Ваймсу в Цитадель в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27292,'Возвращение к Крогу','Надеюсь, хоть чем-то тебе помог. Жаль, больше ничего не могу рассказать. Я со своими учениками делаю столько оружия, что вспомнить одну какую-то вещь уже просто невозможно.$B$BМы поставляем вооружение не только славным защитникам земель тауренов. Моими услугами пользуются и члены клана Зловещий Тотем. Опытным воинам достаточно одного взгляда, чтобы оценить качество моей работы.','Поговорите с Крогом в деревне Гиблотопь.','Он сказал, что члены Зловещего Тотема – его основные покупатели? Мозарн помог нам гораздо больше, чем ему кажется. Думаю, благодаря ему у нас появились главные подозреваемые.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение к Крогу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Надеюсь, хоть чем-то тебе помог. Жаль, больше ничего не могу рассказать. Я со своими учениками делаю столько оружия, что вспомнить одну какую-то вещь уже просто невозможно.$B$BМы поставляем вооружение не только славным защитникам земель тауренов. Моими услугами пользуются и члены клана Зловещий Тотем. Опытным воинам достаточно одного взгляда, чтобы оценить качество моей работы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Крогом в деревне Гиблотопь.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Он сказал, что члены Зловещего Тотема – его основные покупатели? Мозарн помог нам гораздо больше, чем ему кажется. Думаю, благодаря ему у нас появились главные подозреваемые.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27293,'<Крог изучает боевые планы.>$B$BВ том, что Зловещий Тотем двинется на людей, сомнений нет. Но что он замышляет против нас? Нас никто не посвятил в эти планы и из-за этого мы потеряли хорошего бойца. И возможно, мы следующие.','Тебе удалось перехватить приказы?','Вернитесь к Крогу в Пылевые топи.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Крог изучает боевые планы.>$B$BВ том, что Зловещий Тотем двинется на людей, сомнений нет. Но что он замышляет против нас? Нас никто не посвятил в эти планы и из-за этого мы потеряли хорошего бойца. И возможно, мы следующие.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось перехватить приказы?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Крогу в Пылевые топи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27294,'Не просто совпадение','Мы забрали с пепелища таверны все, что смогли. Мне страшно думать о том, куда приведет нас это расследование, но мы должны знать правду.$B$BОтпечатки копыт, еще и щит со знаком Мозарна – я думаю, тут не обошлось без племени Зловещего Тотема. Они недавно поселились на болотах, их деревня Черного Копыта находится на северо-востоке. Сходи туда и поищи оружие с фабрики Мозарна.','Соберите 7 образцов вооружения Черного Копыта в деревне Черного Копыта.','<Крог разглядывает оружие, которое вы принесли из деревни Черного Копыта.>$B$BЭто, несомненно, работа Мозарна. Если мы учиним ему допрос, это привлечет слишком много внимания, но вот с кланом Зловещего Тотема мы можем вести себя посвободнее.','Что тебе удалось найти в деревне Черного Копыта?','Вернитесь к Крогу в деревню Гиблотопь в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Не просто совпадение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы забрали с пепелища таверны все, что смогли. Мне страшно думать о том, куда приведет нас это расследование, но мы должны знать правду.$B$BОтпечатки копыт, еще и щит со знаком Мозарна – я думаю, тут не обошлось без племени Зловещего Тотема. Они недавно поселились на болотах, их деревня Черного Копыта находится на северо-востоке. Сходи туда и поищи оружие с фабрики Мозарна.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 7 образцов вооружения Черного Копыта в деревне Черного Копыта.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Крог разглядывает оружие, которое вы принесли из деревни Черного Копыта.>$B$BЭто, несомненно, работа Мозарна. Если мы учиним ему допрос, это привлечет слишком много внимания, но вот с кланом Зловещего Тотема мы можем вести себя посвободнее.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что тебе удалось найти в деревне Черного Копыта?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Крогу в деревню Гиблотопь в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27295,'Найти Табету','Поговорите с Табетой в ее доме на Трясине.','<Табета улыбается.>$B$BЗначит, Крог хочет знать, где сейчас клан Зловещего Тотема? Что ж, магия для этого не понадобится.$B$BПохоже, это наш общий враг. Воины Зловещего Тотема построили неподалеку отсюда форпост и стали постоянной угрозой для меня и моих учеников.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Найти Табету',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Табетой в ее доме на Трясине.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Табета улыбается.>$B$BЗначит, Крог хочет знать, где сейчас клан Зловещего Тотема? Что ж, магия для этого не понадобится.$B$BПохоже, это наш общий враг. Воины Зловещего Тотема построили неподалеку отсюда форпост и стали постоянной угрозой для меня и моих учеников.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27297,'Акт правосудия','Сомневаюсь, что Зловещий Тотем оставит планы выжить людей с болот. Хотя ты, я смотрю, $gбыл:была; бы не против. Но, по крайней мере, мы выявили виновных в поджоге "Последнего привала".$B$BИди и передай своему предводителю, что правосудие свершилось.','Вернитесь к Крогу в деревню Гиблотопь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Акт правосудия',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сомневаюсь, что Зловещий Тотем оставит планы выжить людей с болот. Хотя ты, я смотрю, $gбыл:была; бы не против. Но, по крайней мере, мы выявили виновных в поджоге "Последнего привала".$B$BИди и передай своему предводителю, что правосудие свершилось.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь к Крогу в деревню Гиблотопь.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`completedtext_loc8`) VALUES (27298,'Поговорите с Аваросом Клинком Рассвета в казармах Оргриммара.') ON DUPLICATE KEY UPDATE `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Аваросом Клинком Рассвета в казармах Оргриммара.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27299,'Расколотая земля','Если ты хочешь, чтоб мы пошли против Сумрака, то за нами дело не станет. Правда, мы тут уже попали в переделку, так что тебе придется нам подсобить – а уж потом мы пойдем на крепость.$B$BНа юге Сумеречный Молот уже призвал наверх Изо\'рата – да ты, наверно, про это знаешь. Его щупальца так и лезут из-под земли. Помоги нам с ними разобраться, сделай милость.','Уничтожьте 3 щупальца Изо\'рата.','Вернитесь в Круг Стихий на Сумеречном нагорье и поговорите с Заклинателем земли Торунскаром.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Расколотая земля',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если ты хочешь, чтоб мы пошли против Сумрака, то за нами дело не станет. Правда, мы тут уже попали в переделку, так что тебе придется нам подсобить – а уж потом мы пойдем на крепость.$B$BНа юге Сумеречный Молот уже призвал наверх Изо\'рата – да ты, наверно, про это знаешь. Его щупальца так и лезут из-под земли. Помоги нам с ними разобраться, сделай милость.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 3 щупальца Изо\'рата.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь в Круг Стихий на Сумеречном нагорье и поговорите с Заклинателем земли Торунскаром.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27300,'Контрудар','Убейте 12 последователей культа Сумеречного Молота в руинах Дракгора.','Месть – и сладкая, и горькая штука. Но я рад, что с нами будешь ты.','Вернитесь в Круг Стихий на Сумеречном нагорье и поговорите с Заклинателем земли Торунскаром.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Контрудар',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 последователей культа Сумеречного Молота в руинах Дракгора.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Месть – и сладкая, и горькая штука. Но я рад, что с нами будешь ты.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь в Круг Стихий на Сумеречном нагорье и поговорите с Заклинателем земли Торунскаром.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27301,'Несломленная','Мы готовимся к ритуалу, который, возможно, поможет уничтожить Изо\'рата – древнее чудовище, которое Сумеречный Молот вызвал из-под земли. Но мы не можем начать, так как сильнейшая из нас попала в плен при нападении на их лагерь.$B$BЗаклинательница земли Ева находится в руинах, к югу отсюда. Она жива, я точно знаю. И если кто-то и заслужил твоей помощи, так это она.','Найдите заклинательницу земли Еву в руинах Дракгора.','Слава стихиям, ты здесь! Тебя прислали мои братья?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Несломленная',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы готовимся к ритуалу, который, возможно, поможет уничтожить Изо\'рата – древнее чудовище, которое Сумеречный Молот вызвал из-под земли. Но мы не можем начать, так как сильнейшая из нас попала в плен при нападении на их лагерь.$B$BЗаклинательница земли Ева находится в руинах, к югу отсюда. Она жива, я точно знаю. И если кто-то и заслужил твоей помощи, так это она.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите заклинательницу земли Еву в руинах Дракгора.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Слава стихиям, ты здесь! Тебя прислали мои братья?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27302,'Простые решения','Я тут недавно. Совсем недавно. Но это даже преимущество, я смотрю на вещи свежим взглядом!$B$BМои братья-шаманы затеяли что-то нереально великое, но подходят ко всему слишком однобоко! Они имеют дело со стихиями, а обычные материалы – это не для них.$B$BТак вот, в руинах на юге я видел, как громилы Сумеречного Молота перетаскивали бочки с горючим маслом! Они пустили их в ход, когда напали на город. Так давай мы тоже так сделаем – когда нападем на них!','Соберите 10 бочек с зажигательным маслом.','Вот это то, что нужно! Ты представляешь, сколько применений можно найти этой штуке? Я – точно нет. Но парочка идей у меня есть, и они мне очень по душе.','Интересно, что будет, если облить этой штукой элементаля? Суперкрутой огненный элементаль? Думаю, да. Нужно попробовать.','Вернитесь в Круг Стихий на Сумеречном нагорье и поговорите с посвященным Клондацком.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Простые решения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я тут недавно. Совсем недавно. Но это даже преимущество, я смотрю на вещи свежим взглядом!$B$BМои братья-шаманы затеяли что-то нереально великое, но подходят ко всему слишком однобоко! Они имеют дело со стихиями, а обычные материалы – это не для них.$B$BТак вот, в руинах на юге я видел, как громилы Сумеречного Молота перетаскивали бочки с горючим маслом! Они пустили их в ход, когда напали на город. Так давай мы тоже так сделаем – когда нападем на них!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 бочек с зажигательным маслом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот это то, что нужно! Ты представляешь, сколько применений можно найти этой штуке? Я – точно нет. Но парочка идей у меня есть, и они мне очень по душе.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Интересно, что будет, если облить этой штукой элементаля? Суперкрутой огненный элементаль? Думаю, да. Нужно попробовать.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь в Круг Стихий на Сумеречном нагорье и поговорите с посвященным Клондацком.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27303,'Сострадание к пленным','О том, что у меня не было никакого желания тут оставаться, можно даже не говорить. Но здесь были материалы, которые нужны нам для ритуала... Я задержалась, чтобы добыть их, поэтому и попала в плен.$B$BЯ вернусь в Круг – но прежде хочу попросить тебя об услуге. Я буду в вечном долгу перед тобой, если ты сделаешь то, что не удалось мне. Нам нужны сердца пленных элементалей огня, которых Сумеречный Молот заточил в западной части лагеря.$B$BИх уже не спасти – но после смерти они будут отомщены.$B$BВстретимся в лагере.','Соберите 5 сердец сжигателей плоти.','Вернитесь в Круг Стихий на Сумеречном нагорье и поговорите с заклинательницей земли Евой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сострадание к пленным',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','О том, что у меня не было никакого желания тут оставаться, можно даже не говорить. Но здесь были материалы, которые нужны нам для ритуала... Я задержалась, чтобы добыть их, поэтому и попала в плен.$B$BЯ вернусь в Круг – но прежде хочу попросить тебя об услуге. Я буду в вечном долгу перед тобой, если ты сделаешь то, что не удалось мне. Нам нужны сердца пленных элементалей огня, которых Сумеречный Молот заточил в западной части лагеря.$B$BИх уже не спасти – но после смерти они будут отомщены.$B$BВстретимся в лагере.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 5 сердец сжигателей плоти.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь в Круг Стихий на Сумеречном нагорье и поговорите с заклинательницей земли Евой.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) VALUES (27303,'Тебе удалось добыть сердца?') ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось добыть сердца?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`completedtext_loc8`) VALUES (27304,'Поговорите с Аваросом Клинком Рассвета в казармах Оргриммара.') ON DUPLICATE KEY UPDATE `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Аваросом Клинком Рассвета в казармах Оргриммара.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27305,'Символ семейной любви','В Бастионе Алого ордена находится полотно, которое очень дорого самому верховному лорду Тириону Фордрингу. Найди картину с изображением двух лун. Сними верхний слой краски, и под ним окажется шедевр – "Символ семейной любви".$B$BДа направит тебя Свет, и, пожалуйста, поаккуратнее с картиной...','Разыщите картину "Символ семейной любви".','Лорд Фордринг будет безмерно рад снова увидеть это полотно.','Картина, Гимндар! Картина у тебя?','Вернитесь к командиру Элигору Вестнику Рассвета.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Символ семейной любви',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В Бастионе Алого ордена находится полотно, которое очень дорого самому верховному лорду Тириону Фордрингу. Найди картину с изображением двух лун. Сними верхний слой краски, и под ним окажется шедевр – "Символ семейной любви".$B$BДа направит тебя Свет, и, пожалуйста, поаккуратнее с картиной...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите картину "Символ семейной любви".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Лорд Фордринг будет безмерно рад снова увидеть это полотно.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Картина, Гимндар! Картина у тебя?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру Элигору Вестнику Рассвета.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27306,'Разговор с Огроном','Знаю я этого Павала Рита. Ничтожество. Дезертировал и теперь прячется в лесах.$B$BЯ отправил на его поиски Огрона. Некоторые подозревают, что Рит воровал наши запасы. По-моему, Огрон пошел на юго-восток.','Отыщите Огрона на юго-востоке от деревни Гиблотопь.','Огрон? Да, это я.$B$BТсс... Говори тише. Тебя крокодилы услышат.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разговор с Огроном',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Знаю я этого Павала Рита. Ничтожество. Дезертировал и теперь прячется в лесах.$B$BЯ отправил на его поиски Огрона. Некоторые подозревают, что Рит воровал наши запасы. По-моему, Огрон пошел на юго-восток.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщите Огрона на юго-востоке от деревни Гиблотопь.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Огрон? Да, это я.$B$BТсс... Говори тише. Тебя крокодилы услышат.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27309,'Замысел клана Зловещего Тотема','Теперь, когда дела племени Зловещего Тотема в Тысяче Игл стали известны всем, многие таурены начали косо на них поглядывать. Мы знаем, что вожди племени замешаны в убийстве и похищениях ради своих целей, и я опасаюсь, что следующей их мишенью станем именно мы.$B$BДеревня Черного Копыта, что на северо-востоке рядом с Синей топью, новое крупное поселение племени Зловещий Тотем. Их старейшины получают приказы из Громового Утеса. Сумеешь перехватить приказы и выяснить, что они задумывают?','Заберите у старейшин племени 4 записки Зловещего Тотема, чтобы выведать боевые планы племени Зловещий Тотем.','Вернитесь к Крогу в Пылевые топи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Замысел клана Зловещего Тотема',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда дела племени Зловещего Тотема в Тысяче Игл стали известны всем, многие таурены начали косо на них поглядывать. Мы знаем, что вожди племени замешаны в убийстве и похищениях ради своих целей, и я опасаюсь, что следующей их мишенью станем именно мы.$B$BДеревня Черного Копыта, что на северо-востоке рядом с Синей топью, новое крупное поселение племени Зловещий Тотем. Их старейшины получают приказы из Громового Утеса. Сумеешь перехватить приказы и выяснить, что они задумывают?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заберите у старейшин племени 4 записки Зловещего Тотема, чтобы выведать боевые планы племени Зловещий Тотем.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Крогу в Пылевые топи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27310,'Обойдетесь без оружия!','Эти трусы рвутся в бой, значит? Что ж, поглядим, на что они способны безоружными!$B$BНаверняка у тебя есть факел или что-то в этом роде. Сожги их оружейные стойки.$B$BСпали их все!','Посмотрим, как они теперь повоюют!','Обратитесь к часовому Фераласа на Пике Темного Облака в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обойдетесь без оружия!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти трусы рвутся в бой, значит? Что ж, поглядим, на что они способны безоружными!$B$BНаверняка у тебя есть факел или что-то в этом роде. Сожги их оружейные стойки.$B$BСпали их все!',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Посмотрим, как они теперь повоюют!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Обратитесь к часовому Фераласа на Пике Темного Облака в Тысяче Игл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27311,'Обойдетесь без оружия!','Посмотрим, как они теперь повоюют!','Обратитесь к храбрецу заставы Вольного Ветра на Пике Темного Облака в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обойдетесь без оружия!',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Посмотрим, как они теперь повоюют!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Обратитесь к храбрецу заставы Вольного Ветра на Пике Темного Облака в Тысяче Игл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27314,'Покончите с Ишей Сумрачной Секирой.','Она оказалась сильнее, чем я предполагала. Мы отлично сработали в паре, но нам, очевидно, не стоит недооценивать вождей Зловещего Тотема.','Обратитесь к часовому Фераласа на Пике Темного Облака в Тысяче Игл.','Ее ждет наказание за все преступления против Заставы Вольного Ветра!','Иша Сумрачная Секира') ON DUPLICATE KEY UPDATE `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Покончите с Ишей Сумрачной Секирой.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Она оказалась сильнее, чем я предполагала. Мы отлично сработали в паре, но нам, очевидно, не стоит недооценивать вождей Зловещего Тотема.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Обратитесь к часовому Фераласа на Пике Темного Облака в Тысяче Игл.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Ее ждет наказание за все преступления против Заставы Вольного Ветра!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Иша Сумрачная Секира',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27315,'Покончите с Ишей Сумрачной Секирой.','А она оказалась куда грознее, чем можно было подумать... Мы отлично сработали в паре, но нам, очевидно, не стоит недооценивать вождей Зловещего Тотема.','Обратитесь к храбрецу заставы Вольного Ветра на Пике Темного Облака в Тысяче Игл.','Ее ждет наказание за все преступления против Заставы Вольного Ветра!','Иша Сумрачная Секира') ON DUPLICATE KEY UPDATE `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Покончите с Ишей Сумрачной Секирой.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А она оказалась куда грознее, чем можно было подумать... Мы отлично сработали в паре, но нам, очевидно, не стоит недооценивать вождей Зловещего Тотема.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Обратитесь к храбрецу заставы Вольного Ветра на Пике Темного Облака в Тысяче Игл.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Ее ждет наказание за все преступления против Заставы Вольного Ветра!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Иша Сумрачная Секира',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (27316,'Костяная погремушка','Там лежит тауренская погремушка, от которой исходит сверхъестественная аура. Ее владельцы мертвы, и артефакт лишился защитника.$B$BНаверняка часовой сумеет определить, есть ли от нее толк.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Костяная погремушка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Там лежит тауренская погремушка, от которой исходит сверхъестественная аура. Ее владельцы мертвы, и артефакт лишился защитника.$B$BНаверняка часовой сумеет определить, есть ли от нее толк.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (27317,'Костяная погремушка','Там лежит тауренская погремушка, от которой исходит сверхъестественная аура. Ее владельцы мертвы, и артефакт лишился защитника.$B$BБыть может, храбрец заставы Вольного Ветра сумеет определить, есть ли от нее толк?','Стало быть, она существует! Что же она тут делает? А если она здесь, то писание и барабаны тоже наверняка поблизости!$B$BВозможно, есть связь между ними и крылатым змеем, которого мы только что видели? Я, кажется, начинаю догадываться, что это на самом деле за существо.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Костяная погремушка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Там лежит тауренская погремушка, от которой исходит сверхъестественная аура. Ее владельцы мертвы, и артефакт лишился защитника.$B$BБыть может, храбрец заставы Вольного Ветра сумеет определить, есть ли от нее толк?',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Стало быть, она существует! Что же она тут делает? А если она здесь, то писание и барабаны тоже наверняка поблизости!$B$BВозможно, есть связь между ними и крылатым змеем, которого мы только что видели? Я, кажется, начинаю догадываться, что это на самом деле за существо.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertargetname_loc8`) VALUES (27318,'Убейте старейшину Штормовое Копыто.','С двумя разобрались. Остались еще двое.$B$BЛюбопытно, с чего это он назвал тебя "избранным"...','Обратитесь к часовому Фераласа на Пике Темного Облака в Тысяче Игл.','Старейшина Штормовое Копыто') ON DUPLICATE KEY UPDATE `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте старейшину Штормовое Копыто.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','С двумя разобрались. Остались еще двое.$B$BЛюбопытно, с чего это он назвал тебя "избранным"...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Обратитесь к часовому Фераласа на Пике Темного Облака в Тысяче Игл.',`completedtext_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Старейшина Штормовое Копыто',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertargetname_loc8`) VALUES (27319,'Убейте старейшину Штормовое Копыто.','Да, работенка не сахар. И что он имел в виду, говоря, что ты "избранный"?','Обратитесь к храбрецу заставы Вольного Ветра на Пике Темного Облака в Тысяче Игл.','Старейшина Штормовое Копыто') ON DUPLICATE KEY UPDATE `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте старейшину Штормовое Копыто.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, работенка не сахар. И что он имел в виду, говоря, что ты "избранный"?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Обратитесь к храбрецу заставы Вольного Ветра на Пике Темного Облака в Тысяче Игл.',`completedtext_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Старейшина Штормовое Копыто',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27320,'Старинный манускрипт','По легенде шу\'хало, костяная погремушка как-то связана со старинным манускриптом и барабанами войны. Думаю, это могущественные артефакты тауренов.$B$BНужно смотреть во все глаза, если мы хотим найти манускрипт и барабан. Если верить легенде, манускрипт выглядит просто как свиток с рисунками.','Отыщите старинный манускрипт.','Передайте старинный манускрипт часовому Фераласа на Пике Темного Облака в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Старинный манускрипт',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','По легенде шу\'хало, костяная погремушка как-то связана со старинным манускриптом и барабанами войны. Думаю, это могущественные артефакты тауренов.$B$BНужно смотреть во все глаза, если мы хотим найти манускрипт и барабан. Если верить легенде, манускрипт выглядит просто как свиток с рисунками.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщите старинный манускрипт.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Передайте старинный манускрипт часовому Фераласа на Пике Темного Облака в Тысяче Игл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27321,'Старинный манускрипт','Костяная погремушка упоминается в древнем шу\'хальском мифе и всегда вместе со старинным манускриптом и барабанами войны. Предположительно, это могущественные артефакты тауренов – дары Матери-Земли. Правда, с трудом верится, что и с барабаном она как-то связана.$B$BМы должны удвоить бдительность, чтобы найти два оставшихся артефакта. Манускрипт должен выглядеть просто как свиток с рисунками, если мне не изменяет память.','Отыщите старинный манускрипт.','Нам нужен именно манускрипт, а не абы какой свиток с письменами тауренов.','Передайте старинный манускрипт храбрецу заставы Вольного Ветра на Пике Темного Облака в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Старинный манускрипт',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Костяная погремушка упоминается в древнем шу\'хальском мифе и всегда вместе со старинным манускриптом и барабанами войны. Предположительно, это могущественные артефакты тауренов – дары Матери-Земли. Правда, с трудом верится, что и с барабаном она как-то связана.$B$BМы должны удвоить бдительность, чтобы найти два оставшихся артефакта. Манускрипт должен выглядеть просто как свиток с рисунками, если мне не изменяет память.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщите старинный манускрипт.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Нам нужен именно манускрипт, а не абы какой свиток с письменами тауренов.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Передайте старинный манускрипт храбрецу заставы Вольного Ветра на Пике Темного Облака в Тысяче Игл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27322,'Корок Великан','Чудовище пало, и это дало небольшую передышку солдатам Отрекшихся на передовой.$B$BВозьмите вторую голову Корока и отнесите ее командиру Штурму в передовой отряд Отрекшихся.','Отнесите вторую голову Корока передовому командиру Штурму в передовой отряд Отрекшихся в руинах Гилнеаса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Корок Великан',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чудовище пало, и это дало небольшую передышку солдатам Отрекшихся на передовой.$B$BВозьмите вторую голову Корока и отнесите ее командиру Штурму в передовой отряд Отрекшихся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите вторую голову Корока передовому командиру Штурму в передовой отряд Отрекшихся в руинах Гилнеаса.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertargetname_loc8`) VALUES (27323,'Прикончите Грундига Темное Облако.','<Часовой пристально глядит на вас.>$B$BЧто это с тобой? И почему их так пугает твое присутствие?','Обратитесь к часовому Фераласа на Пике Темного Облака в Тысяче Игл.','Грундиг Темное Облако') ON DUPLICATE KEY UPDATE `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Прикончите Грундига Темное Облако.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Часовой пристально глядит на вас.>$B$BЧто это с тобой? И почему их так пугает твое присутствие?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Обратитесь к часовому Фераласа на Пике Темного Облака в Тысяче Игл.',`completedtext_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Грундиг Темное Облако',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`objectives_loc8`,`completedtext_loc8`,`questgivertargetname_loc8`) VALUES (27324,'Прикончите Грундига Темное Облако.','Обратитесь к храбрецу заставы Вольного Ветра на Пике Темного Облака в Тысяче Игл.','Грундиг Темное Облако') ON DUPLICATE KEY UPDATE `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Прикончите Грундига Темное Облако.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Обратитесь к храбрецу заставы Вольного Ветра на Пике Темного Облака в Тысяче Игл.',`completedtext_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Грундиг Темное Облако',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27325,'Барабаны войны','Разыщите барабаны войны.','Передайте барабаны войны часовому Фераласа на Пике Темного Облака в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Барабаны войны',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите барабаны войны.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Передайте барабаны войны часовому Фераласа на Пике Темного Облака в Тысяче Игл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27326,'Барабаны войны','Разыщите барабаны войны.','Война – не то занятие, которому посвящают себя те, кто верен учениям Матери-Земли.','Передайте барабаны войны храбрецу заставы Вольного Ветра на Пике Темного Облака в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Барабаны войны',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите барабаны войны.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Война – не то занятие, которому посвящают себя те, кто верен учениям Матери-Земли.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Передайте барабаны войны храбрецу заставы Вольного Ветра на Пике Темного Облака в Тысяче Игл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27327,'Расправьтесь с Арнаком Зловещим Тотемом.','Они все почему-то уверены, что тебя прислала Магата Зловещий Тотем. Наверняка это как-то связано с крылатым змеем, который все время кружит поблизости.$B$BВпрочем, это не главное. Вождь клана мертв. Через некоторое время таурены с заставы Вольного Ветра отвоюют свой дом.$B$BБудь я на их месте, я бы напоследок как следует проучила клан Зловещего Тотема, но они вряд ли станут. Это же таурены.','Обратитесь к часовому Фераласа на Пике Темного Облака в Тысяче Игл.','Племянник мудрой старицы, верховный вождь. Уничтожь его!','Арнак Зловещий Тотем') ON DUPLICATE KEY UPDATE `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Расправьтесь с Арнаком Зловещим Тотемом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Они все почему-то уверены, что тебя прислала Магата Зловещий Тотем. Наверняка это как-то связано с крылатым змеем, который все время кружит поблизости.$B$BВпрочем, это не главное. Вождь клана мертв. Через некоторое время таурены с заставы Вольного Ветра отвоюют свой дом.$B$BБудь я на их месте, я бы напоследок как следует проучила клан Зловещего Тотема, но они вряд ли станут. Это же таурены.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Обратитесь к часовому Фераласа на Пике Темного Облака в Тысяче Игл.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Племянник мудрой старицы, верховный вождь. Уничтожь его!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Арнак Зловещий Тотем',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27328,'Расправьтесь с Арнаком Зловещим Тотемом.','Они все уверены, что тебя прислала Магата Зловещий Тотем. Ведь это ее питомец, Арикара, все время шнырял тут поблизости.$B$B<Храбрец долго и внимательно на вас смотрит.>$B$BНо это уже не имеет значения. Арнак мертв. Когда мы отвоюем заставу Вольного Ветра – лишь вопрос времени.$B$BМожет быть, теперь мы будем жить со Зловещим Тотемом в мире и согласии?','Обратитесь к храбрецу заставы Вольного Ветра на Пике Темного Облака в Тысяче Игл.','Племянник мудрой старицы, верховный вождь. Уничтожь его!','Арнак Зловещий Тотем') ON DUPLICATE KEY UPDATE `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Расправьтесь с Арнаком Зловещим Тотемом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Они все уверены, что тебя прислала Магата Зловещий Тотем. Ведь это ее питомец, Арикара, все время шнырял тут поблизости.$B$B<Храбрец долго и внимательно на вас смотрит.>$B$BНо это уже не имеет значения. Арнак мертв. Когда мы отвоюем заставу Вольного Ветра – лишь вопрос времени.$B$BМожет быть, теперь мы будем жить со Зловещим Тотемом в мире и согласии?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Обратитесь к храбрецу заставы Вольного Ветра на Пике Темного Облака в Тысяче Игл.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Племянник мудрой старицы, верховный вождь. Уничтожь его!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Арнак Зловещий Тотем',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertargetname_loc8`) VALUES (27329,'Призыв змея','Эти артефакты мне знакомы. Думаю, их принесла сюда сама Магата Зловещий Тотем. Но самой ее здесь, среди членов клана, нет. Она исчезла сразу после своего прихода, и никто не знает, где ее теперь искать.$B$BВозможно, нам удастся ее найти.$B$BОтнеси погремушку, писание и барабаны на Шпиль Арикары. Если моя догадка верна, крылатый змей явится снова. Одолей его – и мы узнаем, где скрывается Магата.','Одолейте Арикару.','Стало быть, ее захватил в плен клан Сумеречного Молота. Не могу сказать, что ее судьба сильно меня печалит, однако в их руках, она может представлять еще большую опасность.','Вернитесь к Лакоте Песне Ветра на Пик Темного Облака в Тысяче Игл.','Арикара') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Призыв змея',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти артефакты мне знакомы. Думаю, их принесла сюда сама Магата Зловещий Тотем. Но самой ее здесь, среди членов клана, нет. Она исчезла сразу после своего прихода, и никто не знает, где ее теперь искать.$B$BВозможно, нам удастся ее найти.$B$BОтнеси погремушку, писание и барабаны на Шпиль Арикары. Если моя догадка верна, крылатый змей явится снова. Одолей его – и мы узнаем, где скрывается Магата.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Одолейте Арикару.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Стало быть, ее захватил в плен клан Сумеречного Молота. Не могу сказать, что ее судьба сильно меня печалит, однако в их руках, она может представлять еще большую опасность.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лакоте Песне Ветра на Пик Темного Облака в Тысяче Игл.',`completedtext_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Арикара',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertargetname_loc8`) VALUES (27330,'Призыв змея','Эти артефакты мне знакомы. Думаю, их принесла сюда сама Магата Зловещий Тотем. Но самой ее здесь, среди членов клана, нет. Она исчезла сразу после своего прихода, и никто не знает, где ее теперь искать.$B$BВозможно, нам удастся ее найти.$B$BОтнеси погремушку, писание и барабаны на Шпиль Арикары. Если моя догадка верна, крылатый змей явится снова. Одолей его – и мы узнаем, где скрывается Магата.','Одолейте Арикару.','Стало быть, ее захватил в плен клан Сумеречного Молота. Не могу сказать, что ее судьба сильно меня печалит, однако в их руках, она может представлять еще большую опасность.','Вернитесь к Лакоте Песне Ветра на Пик Темного Облака в Тысяче Игл.','Арикара') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Призыв змея',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти артефакты мне знакомы. Думаю, их принесла сюда сама Магата Зловещий Тотем. Но самой ее здесь, среди членов клана, нет. Она исчезла сразу после своего прихода, и никто не знает, где ее теперь искать.$B$BВозможно, нам удастся ее найти.$B$BОтнеси погремушку, писание и барабаны на Шпиль Арикары. Если моя догадка верна, крылатый змей явится снова. Одолей его – и мы узнаем, где скрывается Магата.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Одолейте Арикару.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Стало быть, ее захватил в плен клан Сумеречного Молота. Не могу сказать, что ее судьба сильно меня печалит, однако в их руках, она может представлять еще большую опасность.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лакоте Песне Ветра на Пик Темного Облака в Тысяче Игл.',`completedtext_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Арикара',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27333,'Теряя силы','Не знаю, сколько еще мы продержимся, $n. Краули и воргенам из стаи Кровавых Клыков известен в Гилнеасе каждый камень. Вот перед тобой стоит противник, а через секунду его уж и след простыл! Мы проиграем эту войну, несмотря на наше численное преимущество, из-за их внезапных нападений.$B$BНо среди нас трусов нет! Отрекшиеся не сдаются, друг мой.$B$BОтправляйся на запад на Каменистый мыс и помоги нашим солдатам на передовой. Уничтожь повстанцев-воргенов!','Уничтожьте 12 воргенов-повстанцев.','Вернитесь к командиру передовой Штурму в передовом отряде Отрекшихся, расположенном в руинах Гилнеаса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Теряя силы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не знаю, сколько еще мы продержимся, $n. Краули и воргенам из стаи Кровавых Клыков известен в Гилнеасе каждый камень. Вот перед тобой стоит противник, а через секунду его уж и след простыл! Мы проиграем эту войну, несмотря на наше численное преимущество, из-за их внезапных нападений.$B$BНо среди нас трусов нет! Отрекшиеся не сдаются, друг мой.$B$BОтправляйся на запад на Каменистый мыс и помоги нашим солдатам на передовой. Уничтожь повстанцев-воргенов!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 12 воргенов-повстанцев.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру передовой Штурму в передовом отряде Отрекшихся, расположенном в руинах Гилнеаса.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (27335,'Путешествие в Оргриммар') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путешествие в Оргриммар',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27336,'Установите на земле захваченный тотем и убейте рядом с ним 10 крапчатых кроколисков-грязекупов или грязекупов-острозубов, чтобы исследовать свойства тотема.','<Вы подробно рассказываете о ходе эксперимента.>$B$BТуман и молния? И все? Но ведь этот тотем должен вызывать еще какие-то эффекты! Тотем бы не стали нести на поле брани, не будь у него каких-то полезных свойств.','Какие успехи в изучении тотема?','Вернитесь к ученику Гариону в домик Табеты в Пылевых топях.') ON DUPLICATE KEY UPDATE `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Установите на земле захваченный тотем и убейте рядом с ним 10 крапчатых кроколисков-грязекупов или грязекупов-острозубов, чтобы исследовать свойства тотема.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Вы подробно рассказываете о ходе эксперимента.>$B$BТуман и молния? И все? Но ведь этот тотем должен вызывать еще какие-то эффекты! Тотем бы не стали нести на поле брани, не будь у него каких-то полезных свойств.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Какие успехи в изучении тотема?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ученику Гариону в домик Табеты в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27337,'Достойное оружие','Наставники сразу распознали в тебе природный талант, $n. Твои успехи и преданность могут служить примером для других.$B$BЧтобы поощрить тебя за труды, король Ринн приказал придворному кузнецу изготовить тебе специальное оружие.$B$BНо прежде нужно собрать материалы для этого оружия, а найти их можно только в проклятой крепости Темного Клыка, что в Серебряном бору. Отправляйся туда и добудь потерянный меч семьи Сильверлейнов, слитки лунной стали и жилы вурдалаков и упырей, обитающих в крепости.','Отправляйтесь в крепость Темного Клыка, добудьте у барона Сильверлейна меч семьи Сильверлейнов, а также 5 слитков лунной стали и 5 жил нежити.','Ты раздобыл материалы для оружия?','Поговорите с Терумом Подземная Кузня в квартале дворфов Штормграда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Достойное оружие',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наставники сразу распознали в тебе природный талант, $n. Твои успехи и преданность могут служить примером для других.$B$BЧтобы поощрить тебя за труды, король Ринн приказал придворному кузнецу изготовить тебе специальное оружие.$B$BНо прежде нужно собрать материалы для этого оружия, а найти их можно только в проклятой крепости Темного Клыка, что в Серебряном бору. Отправляйся туда и добудь потерянный меч семьи Сильверлейнов, слитки лунной стали и жилы вурдалаков и упырей, обитающих в крепости.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в крепость Темного Клыка, добудьте у барона Сильверлейна меч семьи Сильверлейнов, а также 5 слитков лунной стали и 5 жил нежити.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты раздобыл материалы для оружия?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Терумом Подземная Кузня в квартале дворфов Штормграда.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27338,'Наши парни на берегу','Положение на нагорье меняется каждую минуту. Наша задача – взять Сумеречный бастион, но из-за проклятой Орды я не могу даже обустроить плацдарм для высадки десанта!$B$BМне нужно, чтобы кто-то сделал это, пока я собираю остатки флота.$B$BРазыщи на берегу лейтенанта Эмри и помоги его морским пехотинцам отбросить войска Орды!','Отправляйтесь на Сумеречный берег на Сумеречном нагорье и поговорите с лейтенантом Эмри.','Отправляйтесь на Сумеречный берег на Сумеречном нагорье и поговорите с лейтенантом Эмри.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наши парни на берегу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Положение на нагорье меняется каждую минуту. Наша задача – взять Сумеречный бастион, но из-за проклятой Орды я не могу даже обустроить плацдарм для высадки десанта!$B$BМне нужно, чтобы кто-то сделал это, пока я собираю остатки флота.$B$BРазыщи на берегу лейтенанта Эмри и помоги его морским пехотинцам отбросить войска Орды!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь на Сумеречный берег на Сумеречном нагорье и поговорите с лейтенантом Эмри.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отправляйтесь на Сумеречный берег на Сумеречном нагорье и поговорите с лейтенантом Эмри.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27339,'Подмена реактива','<Ученик Гарион изучает яд.>$B$BПросто прекрасные образцы! Он и не отличит.','Удалось добыть яд? Морланн в любую минуту может спохватиться, что его не хватает...','Вернитесь к ученику Гариону в домик Табеты в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подмена реактива',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Ученик Гарион изучает яд.>$B$BПросто прекрасные образцы! Он и не отличит.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось добыть яд? Морланн в любую минуту может спохватиться, что его не хватает...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ученику Гариону в домик Табеты в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27340,'Налетчики Дикого Рога','<Ученик Морланн кивает.>$B$BЭто хорошо. И не могу сказать, что буду страдать без их общества. А то даже в сердце трясин уединения не найдешь!','Вернитесь к ученику Морланну в домик Табеты в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Налетчики Дикого Рога',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Ученик Морланн кивает.>$B$BЭто хорошо. И не могу сказать, что буду страдать без их общества. А то даже в сердце трясин уединения не найдешь!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ученику Морланну в домик Табеты в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (27341,'Разведка на побережье','$C, тут либо мы, либо они. Только одна из сторон будет владеть этим берегом.$B$BК северу отсюда находится небольшой холм, с которого прекрасно просматривается все побережье. Тот, кто завладеет холмом, получит преимущество в бою!$B$BМне нужно знать, что сейчас там происходит. Проведи разведку, двигаясь к контрольному пункту берегового плацдарма – он отмечен огромным флагом. Затем возвращайся ко мне.$B$BСам пункт захватывать не нужно – ну, разве что тебе хочется подраться...','Проведите разведку на Сумеречном берегу в окрестностях контрольного пункта берегового плацдарма. Вам не нужно его захватывать, но если вы это сделаете, то ваша сторона получит преимущество в бою, а вы перейдете в режим PvP.','Вот так обстоят дела, солдат. Так что если тебе сложно сражаться здесь, на берегу, можешь поддержать нас в битве вон за тот холм.','Разведка окрестностей проведена','Вернитесь на Сумеречный берег на Сумеречном нагорье и поговорите с лейтенантом Эмри.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разведка на побережье',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$C, тут либо мы, либо они. Только одна из сторон будет владеть этим берегом.$B$BК северу отсюда находится небольшой холм, с которого прекрасно просматривается все побережье. Тот, кто завладеет холмом, получит преимущество в бою!$B$BМне нужно знать, что сейчас там происходит. Проведи разведку, двигаясь к контрольному пункту берегового плацдарма – он отмечен огромным флагом. Затем возвращайся ко мне.$B$BСам пункт захватывать не нужно – ну, разве что тебе хочется подраться...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проведите разведку на Сумеречном берегу в окрестностях контрольного пункта берегового плацдарма. Вам не нужно его захватывать, но если вы это сделаете, то ваша сторона получит преимущество в бою, а вы перейдете в режим PvP.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот так обстоят дела, солдат. Так что если тебе сложно сражаться здесь, на берегу, можешь поддержать нас в битве вон за тот холм.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Разведка окрестностей проведена',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь на Сумеречный берег на Сумеречном нагорье и поговорите с лейтенантом Эмри.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27342,'Со временем все раскроется','Темная Госпожа послала сюда вас с Артурой с весьма необычной целью. Прежде чем я расскажу, с какой, необходимо кое-что подготовить.$B$BСтупай на восток в лес Гилнеаса и поищи среди камней и деревьев особенное растение, называемое аконит. Нарви столько, сколько сумеешь унести, и возвращайся ко мне.$B$BНаша задача здесь не ограничивается лишь полем боя, $n. Со временем ты все узнаешь.','Собрать 6 растений аконита.','<Бельмонт забирает у вас аконит.>$B$BХорошо. Теперь выполняй приказ командира передовой Штурма. Постарайся ничем не отличаться от остальных солдат. Мы не хотим, чтобы освободительный фронт Гилнеаса что-нибудь заподозрил.$B$BО, ты не знал, что они следят за нами? Прямо сейчас пять разведчиков-воргенов рыщут у наших позиций. Просто веди себя спокойно и выполняй приказы. Я сообщу тебе, когда все будет готово для дальнейших действий.','Ты набрал аконита?','Найдите командира ловчих смерти Бельмонта в передовом отряде Отрекшихся в руинах Гилнеаса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Со временем все раскроется',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Темная Госпожа послала сюда вас с Артурой с весьма необычной целью. Прежде чем я расскажу, с какой, необходимо кое-что подготовить.$B$BСтупай на восток в лес Гилнеаса и поищи среди камней и деревьев особенное растение, называемое аконит. Нарви столько, сколько сумеешь унести, и возвращайся ко мне.$B$BНаша задача здесь не ограничивается лишь полем боя, $n. Со временем ты все узнаешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Собрать 6 растений аконита.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Бельмонт забирает у вас аконит.>$B$BХорошо. Теперь выполняй приказ командира передовой Штурма. Постарайся ничем не отличаться от остальных солдат. Мы не хотим, чтобы освободительный фронт Гилнеаса что-нибудь заподозрил.$B$BО, ты не знал, что они следят за нами? Прямо сейчас пять разведчиков-воргенов рыщут у наших позиций. Просто веди себя спокойно и выполняй приказы. Я сообщу тебе, когда все будет готово для дальнейших действий.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты набрал аконита?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Найдите командира ловчих смерти Бельмонта в передовом отряде Отрекшихся в руинах Гилнеаса.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27343,'Длань Света','Я внимательно слежу за твоими успехами, $n, и могу сказать, что Свет сопровождает тебя. Теперь ты $gнастоящий:настоящая:c; |3-6($c).$B$BЧтобы поощрить тебя за хорошую службу, король приказал своему кузнецу изготовить тебе специальное оружие.$B$BНо прежде нужно собрать материалы для этого оружия, а найти их можно только в проклятой крепости Темного Клыка, что в Серебряном бору. Отправляйся туда и добудь святой символ командира Спрингвейла, слитки лунной стали и жилы воргов, обитающих в крепости.','Отправляйтесь в крепость Темного Клыка и добудьте святой символ командира Спрингвейла, 5 ящиков слитков лунной стали и 5 жил нежити.','Поговорите с Терумом Подземная Кузня в квартале дворфов Штормграда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Длань Света',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я внимательно слежу за твоими успехами, $n, и могу сказать, что Свет сопровождает тебя. Теперь ты $gнастоящий:настоящая:c; |3-6($c).$B$BЧтобы поощрить тебя за хорошую службу, король приказал своему кузнецу изготовить тебе специальное оружие.$B$BНо прежде нужно собрать материалы для этого оружия, а найти их можно только в проклятой крепости Темного Клыка, что в Серебряном бору. Отправляйся туда и добудь святой символ командира Спрингвейла, слитки лунной стали и жилы воргов, обитающих в крепости.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в крепость Темного Клыка и добудьте святой символ командира Спрингвейла, 5 ящиков слитков лунной стали и 5 жил нежити.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Терумом Подземная Кузня в квартале дворфов Штормграда.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27344,'Заслуженная награда','Рассказы о твоих успехах дошли не только до меня, $n. О твоем умении обращаться с оружием и питомцами, а также о преданности Альянсу услышал сам король Ринн.$B$BЧтобы поощрить тебя за хорошую службу, король приказал своему мастеру луков изготовить тебе именное оружие.$B$BНо прежде нужно собрать материалы для этого оружия, а найти их можно только в проклятой крепости Темного Клыка, что в Серебряном бору. Отправляйся туда и добудь хрустальный прицел Годфри, осененное луной дерево и жилы вурдалаков и упырей, обитающих в крепости.','Отправляйтесь в крепость Темного Клыка и добудьте хрустальный прицел Годфри, 5 вязанок осененного луной дерева и 5 жил нежити.','Кто бы мог подумать, что в этой старой крепости можно найти такие ценные предметы? Я почту за честь изготовить тебе из них оружие.','Ты раздобыл материалы для оружия?','Поговорите с Фредериком Стовером в торговом квартале Штормграда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Заслуженная награда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Рассказы о твоих успехах дошли не только до меня, $n. О твоем умении обращаться с оружием и питомцами, а также о преданности Альянсу услышал сам король Ринн.$B$BЧтобы поощрить тебя за хорошую службу, король приказал своему мастеру луков изготовить тебе именное оружие.$B$BНо прежде нужно собрать материалы для этого оружия, а найти их можно только в проклятой крепости Темного Клыка, что в Серебряном бору. Отправляйся туда и добудь хрустальный прицел Годфри, осененное луной дерево и жилы вурдалаков и упырей, обитающих в крепости.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в крепость Темного Клыка и добудьте хрустальный прицел Годфри, 5 вязанок осененного луной дерева и 5 жил нежити.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Кто бы мог подумать, что в этой старой крепости можно найти такие ценные предметы? Я почту за честь изготовить тебе из них оружие.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты раздобыл материалы для оружия?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Фредериком Стовером в торговом квартале Штормграда.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27345,'ПУО','У нас прервано сообщение со всеми передовыми заставами, $n. И сейчас я понятия не имею, что происходит с нашими солдатами в Гилнеасе. Нужно заново наладить связь.$B$BОтправляйся на запад, к Каменистому мысу. Там, на побережье, расположена наша застава. К этому времени все солдаты на заставе уже наверняка погибли, но их ПУО еще может работать. Добудь устройство и доставь мне.','Разыщите переговорное устройство Отрекшихся.','С помощью этого устройства я смогу связываться с тобой. Теперь нужно выяснить, какова ситуация на остальных заставах.','Добудь ПУО','Вернитесь к командиру передовой Штурму в передовом отряде Отрекшихся, расположенном в руинах Гилнеаса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','ПУО',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У нас прервано сообщение со всеми передовыми заставами, $n. И сейчас я понятия не имею, что происходит с нашими солдатами в Гилнеасе. Нужно заново наладить связь.$B$BОтправляйся на запад, к Каменистому мысу. Там, на побережье, расположена наша застава. К этому времени все солдаты на заставе уже наверняка погибли, но их ПУО еще может работать. Добудь устройство и доставь мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите переговорное устройство Отрекшихся.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','С помощью этого устройства я смогу связываться с тобой. Теперь нужно выяснить, какова ситуация на остальных заставах.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Добудь ПУО',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру передовой Штурму в передовом отряде Отрекшихся, расположенном в руинах Гилнеаса.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27347,'Профилактика коррозии','Ты только посмотри! Слизнюки прям кишмя кишат. Если с ними не покончить, сожрут и обломки, и груз с дирижабля!$B$BА я не могу вернуться ни с чем, |3-6($c)! Помоги мне разогнать этих слизнюков, пока они тут все не понадкусывали!$B$BЕсли включить это устройство, оно направит энергию на слизнюков, и они начнут взрываться. Разбитый энергетический сердечник дирижабля подпитает устройство. Тот кусок, что рядом с местом крушения, работает стабильно, остальные – не особенно.','Мокси Сталегриль хочет, чтобы вы уничтожили 10 слизнюков и доложили ей о выполнении задания на месте крушения дирижабля Бизила.','Ну, похоже, там и правда стало немного почище...$B$BПолагаю, пора заняться делом и основательно порыться в обломках.','Ну как, тебе уже удалось покончить со слизнюками?','Вернитесь к Мокси Сталегриль на место крушения дирижабля Бизила, что в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Профилактика коррозии',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты только посмотри! Слизнюки прям кишмя кишат. Если с ними не покончить, сожрут и обломки, и груз с дирижабля!$B$BА я не могу вернуться ни с чем, |3-6($c)! Помоги мне разогнать этих слизнюков, пока они тут все не понадкусывали!$B$BЕсли включить это устройство, оно направит энергию на слизнюков, и они начнут взрываться. Разбитый энергетический сердечник дирижабля подпитает устройство. Тот кусок, что рядом с местом крушения, работает стабильно, остальные – не особенно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Мокси Сталегриль хочет, чтобы вы уничтожили 10 слизнюков и доложили ей о выполнении задания на месте крушения дирижабля Бизила.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну, похоже, там и правда стало немного почище...$B$BПолагаю, пора заняться делом и основательно порыться в обломках.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как, тебе уже удалось покончить со слизнюками?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мокси Сталегриль на место крушения дирижабля Бизила, что в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27348,'Защитить груз!','Этот дирижабль вез в Шестермуть припасов на полгода! Они там, конечно, что-то на что-то выменивают, но на обмене долго не протянешь.$B$BМеня отправили сюда собрать все оставшееся от груза, да вот только обломки разбросало по всему болоту. Большая часть, конечно, аварии не пережила, но, может, поищем то, что еще на что-то годится?','Мокси Сталегриль попросила вас собрать 8 контейнеров груза с дирижабля и принести ей на место крушения Бизиля.','Вернитесь к Мокси Сталегриль на место крушения дирижабля Бизила в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Защитить груз!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этот дирижабль вез в Шестермуть припасов на полгода! Они там, конечно, что-то на что-то выменивают, но на обмене долго не протянешь.$B$BМеня отправили сюда собрать все оставшееся от груза, да вот только обломки разбросало по всему болоту. Большая часть, конечно, аварии не пережила, но, может, поищем то, что еще на что-то годится?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Мокси Сталегриль попросила вас собрать 8 контейнеров груза с дирижабля и принести ей на место крушения Бизиля.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мокси Сталегриль на место крушения дирижабля Бизила в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27350,'Перебои со связью: Сторожка Рутсака','<ПУО жужжит.>$B$BНаш другой форпост – Сторожка Рутсака – расположен на востоке от Злой заставы. Отправляйся к Рутсаку, но избегай встреч с воргенами-захватчиками, $n. Не стоит лезть на рожон и сражаться с этими тварями в одиночку.$B$BЕсли доберешься $gцелым и невредимым:целой и невредимой;, ищи капитана Рутсака.$B$BНо готовься к худшему.','Найдите капитана Рутсака в Сторожке Рутсака в руинах Гилнеаса.','Да... К... когда мы потеряли Гилнеас, порт пал.$B$BЗдесь... л... ЛЮДИ! Подкрепление из Штормграда! Они перебили моих солдат. Оставили меня в живых как свидетеля их силы. Передай верховному командованию... Скажи – 7-й легион остался здесь...','Сторожка Рутсака защищала наш правый фланг.','Командир передовой Штурм') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Перебои со связью: Сторожка Рутсака',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<ПУО жужжит.>$B$BНаш другой форпост – Сторожка Рутсака – расположен на востоке от Злой заставы. Отправляйся к Рутсаку, но избегай встреч с воргенами-захватчиками, $n. Не стоит лезть на рожон и сражаться с этими тварями в одиночку.$B$BЕсли доберешься $gцелым и невредимым:целой и невредимой;, ищи капитана Рутсака.$B$BНо готовься к худшему.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите капитана Рутсака в Сторожке Рутсака в руинах Гилнеаса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да... К... когда мы потеряли Гилнеас, порт пал.$B$BЗдесь... л... ЛЮДИ! Подкрепление из Штормграда! Они перебили моих солдат. Оставили меня в живых как свидетеля их силы. Передай верховному командованию... Скажи – 7-й легион остался здесь...',`offerrewardtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Сторожка Рутсака защищала наш правый фланг.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Командир передовой Штурм',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27351,'Королевская награда','ШРУ с интересом следило за твоими успехами. Твоя преданность Альянсу известна всем нашим лидерам, а рассказы о твоих подвигах дошли до самого короля.$B$BЧтобы поощрить тебя за успехи, король Ринн приказал придворному кузнецу изготовить оружие специально для тебя.$B$BНо прежде нужно собрать материалы для этого оружия, а найти их можно только в проклятой крепости Темного Клыка, что в Серебряном бору. Отправляйся туда и добудь точило командира Спрингвейла, слитки лунной стали и жилы вурдалаков и упырей, обитающих в крепости.','Отправляйтесь в крепость Темного Клыка и добудьте точило командира Спрингвейла, 5 слитков лунной стали и 5 жил нежити.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Королевская награда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','ШРУ с интересом следило за твоими успехами. Твоя преданность Альянсу известна всем нашим лидерам, а рассказы о твоих подвигах дошли до самого короля.$B$BЧтобы поощрить тебя за успехи, король Ринн приказал придворному кузнецу изготовить оружие специально для тебя.$B$BНо прежде нужно собрать материалы для этого оружия, а найти их можно только в проклятой крепости Темного Клыка, что в Серебряном бору. Отправляйся туда и добудь точило командира Спрингвейла, слитки лунной стали и жилы вурдалаков и упырей, обитающих в крепости.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в крепость Темного Клыка и добудьте точило командира Спрингвейла, 5 слитков лунной стали и 5 жил нежити.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27352,'Жидкое золото','Когда силы Плети, словно чума, наводнили Стратхольм, рыцари ордена Серебряной Длани обратили против захватчиков святую воду. Они уложили ее в небольшие ящики вместе с другими важными припасами по всему городу. К сожалению, Плеть сделала из горожан своих приспешников, прежде чем те смогли воспользоваться святой водой!$B$BЭти ящики весьма нам пригодятся. Принеси мне сосуд со святой водой Стратхольма, нам нужно сделать еще много подобных.','Найдите сосуд со святой водой Стратхольма.','Превосходно! Когда у нас будет много святой воды, мы зададим этой Плети!','Это сосуд со святой водой Стратхольма?$B$BПостой, да это же обычная вода! Ты со стариком Камнетесом не шути!','Вернитесь к караванщику Камнетесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жидкое золото',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда силы Плети, словно чума, наводнили Стратхольм, рыцари ордена Серебряной Длани обратили против захватчиков святую воду. Они уложили ее в небольшие ящики вместе с другими важными припасами по всему городу. К сожалению, Плеть сделала из горожан своих приспешников, прежде чем те смогли воспользоваться святой водой!$B$BЭти ящики весьма нам пригодятся. Принеси мне сосуд со святой водой Стратхольма, нам нужно сделать еще много подобных.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите сосуд со святой водой Стратхольма.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Превосходно! Когда у нас будет много святой воды, мы зададим этой Плети!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Это сосуд со святой водой Стратхольма?$B$BПостой, да это же обычная вода! Ты со стариком Камнетесом не шути!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к караванщику Камнетесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27353,'Благословение стихий','Твои таланты привлекли внимание других шаманов, $n. Рассказы о твоей преданности Альянсу и успехах в приручении стихий дошли даже до королевского дворца.$B$BЧтобы поощрить за успехи, король приказал придворному кузнецу изготовить оружие специально для тебя.$B$BНо прежде нужно собрать материалы для этого оружия, а найти их можно только в проклятой крепости Темного Клыка, что в Серебряном бору. Отправляйся туда и добудь талисман лорда Вальдена, книгу Потерянных Душ и сущность призраков, обитающих в крепости.','Отправляйтесь в крепость Темного Клыка и добудьте талисман Вальдена, книгу Потерянных Душ и 5 призрачных субстанций.','Поговорите с Терумом Подземная Кузня в квартале дворфов Штормграда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Благословение стихий',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Твои таланты привлекли внимание других шаманов, $n. Рассказы о твоей преданности Альянсу и успехах в приручении стихий дошли даже до королевского дворца.$B$BЧтобы поощрить за успехи, король приказал придворному кузнецу изготовить оружие специально для тебя.$B$BНо прежде нужно собрать материалы для этого оружия, а найти их можно только в проклятой крепости Темного Клыка, что в Серебряном бору. Отправляйся туда и добудь талисман лорда Вальдена, книгу Потерянных Душ и сущность призраков, обитающих в крепости.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в крепость Темного Клыка и добудьте талисман Вальдена, книгу Потерянных Душ и 5 призрачных субстанций.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Терумом Подземная Кузня в квартале дворфов Штормграда.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27354,'Постижение тайной магии','Ты $gдоказал:доказала;, что ты $gпрекрасный ученик:прекрасная ученица; и $gпреданный:преданная; слуга Альянса. Рассказы о твоих успехах дошли до самого короля.$B$BЧтобы поощрить тебя за хорошую службу, король приказал своему чаротворцу изготовить тебе специальное оружие.$B$BНо прежде нужно собрать для него материалы, а найти их можно только в проклятой крепости Темного Клыка, что в Серебряном бору. Отправляйся туда и добудь потерянное наследие семьи Сильверлейнов, осененное луной дерево и сущность призраков, обитающих в крепости.','Отправляйтесь в крепость Темного Клыка и добудьте зачарованный кристалл Сильверлейна у барона Сильверлейна, 5 вязанок осененного луной дерева и 5 призрачных субстанций.','Поговорите с Луканом Корделлом в квартале магов Штормграда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Постижение тайной магии',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gдоказал:доказала;, что ты $gпрекрасный ученик:прекрасная ученица; и $gпреданный:преданная; слуга Альянса. Рассказы о твоих успехах дошли до самого короля.$B$BЧтобы поощрить тебя за хорошую службу, король приказал своему чаротворцу изготовить тебе специальное оружие.$B$BНо прежде нужно собрать для него материалы, а найти их можно только в проклятой крепости Темного Клыка, что в Серебряном бору. Отправляйся туда и добудь потерянное наследие семьи Сильверлейнов, осененное луной дерево и сущность призраков, обитающих в крепости.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в крепость Темного Клыка и добудьте зачарованный кристалл Сильверлейна у барона Сильверлейна, 5 вязанок осененного луной дерева и 5 призрачных субстанций.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Луканом Корделлом в квартале магов Штормграда.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27355,'Уважение силы','Благодаря твоим подвигам король наконец-то заметил нашу мощь и значимость для Альянса. Возможно, он даже готов признать наш народ.$B$BЧтобы поощрить за успехи, король Ринн приказал придворному чаротворцу изготовить мощное оружие специально для тебя.$B$BНо прежде нужно собрать материалы для этого оружия, а найти их можно только в проклятой крепости Темного Клыка, что в Серебряном бору. Отправляйся туда и добудь зловещее око, известного как Слепой Страж, книгу Потерянных Душ и сущности духов, обитающих в замке.','Отправляйтесь к крепость Темного Клыка и добудьте зловещее око, книгу Потерянных Душ и 5 призрачных субстанций.','Не буду спрашивать, на что тебе пришлось пойти, чтобы достать такие редкие материалы, но я благодарен тебе за возможность поработать с ними. Я изготовлю для тебя великолепное оружие!','Ты раздобыла материалы для оружия?','Поговорите с Луканом Корделлом в квартале магов Штормграда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уважение силы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Благодаря твоим подвигам король наконец-то заметил нашу мощь и значимость для Альянса. Возможно, он даже готов признать наш народ.$B$BЧтобы поощрить за успехи, король Ринн приказал придворному чаротворцу изготовить мощное оружие специально для тебя.$B$BНо прежде нужно собрать материалы для этого оружия, а найти их можно только в проклятой крепости Темного Клыка, что в Серебряном бору. Отправляйся туда и добудь зловещее око, известного как Слепой Страж, книгу Потерянных Душ и сущности духов, обитающих в замке.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь к крепость Темного Клыка и добудьте зловещее око, книгу Потерянных Душ и 5 призрачных субстанций.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Не буду спрашивать, на что тебе пришлось пойти, чтобы достать такие редкие материалы, но я благодарен тебе за возможность поработать с ними. Я изготовлю для тебя великолепное оружие!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты раздобыла материалы для оружия?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Луканом Корделлом в квартале магов Штормграда.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27356,'Будущее Круга','Друиды Круга Кенария довольны твоими достижениями, $n. Ты $gзаслужил:заслужила; наше уважение. В тебе и твоих соратниках мы видим будущее нашего братства.$B$BВ награду за труды мы решили смастерить для тебя уникальный посох.$B$BДля него нужны очень редкие материалы, найти которые можно только в крепости Темного Клыка, что в Серебряном бору. Отправляйся туда и добудь эликсиры лорда Вальдена, осененное луной дерево и жилы вурдалаков и упырей, обитающих в крепости.','Отправляйтесь в крепость Темного Клыка и добудьте эликсиры Вальдена, 5 связок осененного луной дерева и 5 жил нежити.','Ну вот… Осталось последнее, $gпарень:девушка;.','$gНашел:Нашла; зуб?','Поговорите с Нарианной в Ночной Гавани на Лунной поляне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Будущее Круга',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Друиды Круга Кенария довольны твоими достижениями, $n. Ты $gзаслужил:заслужила; наше уважение. В тебе и твоих соратниках мы видим будущее нашего братства.$B$BВ награду за труды мы решили смастерить для тебя уникальный посох.$B$BДля него нужны очень редкие материалы, найти которые можно только в крепости Темного Клыка, что в Серебряном бору. Отправляйся туда и добудь эликсиры лорда Вальдена, осененное луной дерево и жилы вурдалаков и упырей, обитающих в крепости.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в крепость Темного Клыка и добудьте эликсиры Вальдена, 5 связок осененного луной дерева и 5 жил нежити.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну вот… Осталось последнее, $gпарень:девушка;.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$gНашел:Нашла; зуб?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Нарианной в Ночной Гавани на Лунной поляне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (27357,'Невеста поневоле','Ну конечно! Лакота Песня Ветра! И почему я не подумала об этом раньше!$B$BАрнак похитил Лакоту много лет назад и пытался насильно на ней жениться. Она сумела сбежать, но в суматохе недавней атаки на заставу Вольного Ветра он снова пленил ее.$B$BДолжно быть, она где-то здесь. За прошедшие годы она изрядно поднаторела в мистицизме и наверняка знает, что делать с этими артефактами тауренов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Невеста поневоле',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну конечно! Лакота Песня Ветра! И почему я не подумала об этом раньше!$B$BАрнак похитил Лакоту много лет назад и пытался насильно на ней жениться. Она сумела сбежать, но в суматохе недавней атаки на заставу Вольного Ветра он снова пленил ее.$B$BДолжно быть, она где-то здесь. За прошедшие годы она изрядно поднаторела в мистицизме и наверняка знает, что делать с этими артефактами тауренов.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (27358,'Невеста поневоле','Лакота Песня Ветра! И как я раньше не подумал!$B$BАрнак похитил Лакоту много лет назад и пытался насильно на ней жениться. Ей помогли бежать, но в суматохе недавней атаки на заставу Вольного Ветра он снова пленил ее.$B$BНаверняка она где-то здесь. За прошедшие годы она стала мудрым шаманом. Уверен, она знает, что делать с погремушкой, сказанием и барабанами.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Невеста поневоле',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Лакота Песня Ветра! И как я раньше не подумал!$B$BАрнак похитил Лакоту много лет назад и пытался насильно на ней жениться. Ей помогли бежать, но в суматохе недавней атаки на заставу Вольного Ветра он снова пленил ее.$B$BНаверняка она где-то здесь. За прошедшие годы она стала мудрым шаманом. Уверен, она знает, что делать с погремушкой, сказанием и барабанами.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27359,'Алое подкрепление','Плеть наложила какой-то заговор... не дающий мне открыть портал для наших сил, которые помогли бы нам отвоевать город! У меня в ушах будто визг сотен кошек! Ай! $B$BЯ изо всех сил спасаю свой разум от крика с помощью этого барьера. Могу лишь догадываться, что защитные чары поддерживают банши. Если ты принесешь мне их сущности, думаю, смогу пробить защитные чары и переместить наших бойцов!','Раздобудьте 4 сущности банши.','Чудовищно... банши и впрямь терзаемые души. Даже когда просто держишь в руках их сущности, это причиняет неимоверную душевную боль...$B$BНу все, довольно. Я поработаю над противодействием их магии, а затем мы быстро наладим портал. Стратхольм скоро снова будет нашим.','Тебе удалось добыть сущности? Имей в виду – банши смертоносные колдуньи.','Вернитесь к верховному магу Анжеле Досантос.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Алое подкрепление',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Плеть наложила какой-то заговор... не дающий мне открыть портал для наших сил, которые помогли бы нам отвоевать город! У меня в ушах будто визг сотен кошек! Ай! $B$BЯ изо всех сил спасаю свой разум от крика с помощью этого барьера. Могу лишь догадываться, что защитные чары поддерживают банши. Если ты принесешь мне их сущности, думаю, смогу пробить защитные чары и переместить наших бойцов!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте 4 сущности банши.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Чудовищно... банши и впрямь терзаемые души. Даже когда просто держишь в руках их сущности, это причиняет неимоверную душевную боль...$B$BНу все, довольно. Я поработаю над противодействием их магии, а затем мы быстро наладим портал. Стратхольм скоро снова будет нашим.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось добыть сущности? Имей в виду – банши смертоносные колдуньи.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному магу Анжеле Досантос.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27360,'Месть за наших','Седьмой легион... Они напали посреди ночи. Подводники перебили моих солдат, а их капитан подошел ко мне вплотную и сказал... Я никогда не забуду его слова:$B$B"Я старший сержант Пьетро Зарен из Седьмого легиона. Когда тебе будет сниться, как убивают твоих солдат – если ты вообще сможешь заснуть после сегодняшней ночи, – вспоминай мое имя и трепещи".$B$BОтомсти за моих солдат! Перебей этих мерзавцев из Легиона. Они сейчас расположились в Гилнеасе в Соборном квартале, на юго-западе отсюда.','Уничтожьте 10 подводников 7-го легиона.','Вернитесь к капитану Рутсаку в Сторожку Рутсака в руинах Гилнеаса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Месть за наших',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Седьмой легион... Они напали посреди ночи. Подводники перебили моих солдат, а их капитан подошел ко мне вплотную и сказал... Я никогда не забуду его слова:$B$B"Я старший сержант Пьетро Зарен из Седьмого легиона. Когда тебе будет сниться, как убивают твоих солдат – если ты вообще сможешь заснуть после сегодняшней ночи, – вспоминай мое имя и трепещи".$B$BОтомсти за моих солдат! Перебей этих мерзавцев из Легиона. Они сейчас расположились в Гилнеасе в Соборном квартале, на юго-западе отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 10 подводников 7-го легиона.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Рутсаку в Сторожку Рутсака в руинах Гилнеаса.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27361,'Избранник Света','Свет озаряет твой путь и преданность Альянсу, $n. Ты отличный пример для других жрецов и братьев по оружию.$B$BЧтобы поощрить тебя за успехи, король Ринн приказал придворному чаротворцу изготовить тебе специальный посох.$B$BНо прежде нужно собрать материалы для этого оружия, а найти их можно только в проклятой крепости Темного Клыка, что в Серебряном бору. Отправляйся туда и добудь затерянный святой символ командира Спрингвейла, осененное луной дерево и сущность духов, обитающих в крепости.','Отправляйтесь в крепость Темного Клыка и добудьте святой символ командира у командира Спрингвейла, 5 вязанок осененного луной дерева и 5 призрачных субстанций.','Поговорите с Луканом Корделлом в квартале магов Штормграда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Избранник Света',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Свет озаряет твой путь и преданность Альянсу, $n. Ты отличный пример для других жрецов и братьев по оружию.$B$BЧтобы поощрить тебя за успехи, король Ринн приказал придворному чаротворцу изготовить тебе специальный посох.$B$BНо прежде нужно собрать материалы для этого оружия, а найти их можно только в проклятой крепости Темного Клыка, что в Серебряном бору. Отправляйся туда и добудь затерянный святой символ командира Спрингвейла, осененное луной дерево и сущность духов, обитающих в крепости.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в крепость Темного Клыка и добудьте святой символ командира у командира Спрингвейла, 5 вязанок осененного луной дерева и 5 призрачных субстанций.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Луканом Корделлом в квартале магов Штормграда.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27362,'Избранник Элуны','Ты $gистинный почитатель:истинная почитательница; Элуны, пример для нашего народа и $gпреданный поборник:преданная поборница; Альянса. Храм Луны и королевский двор Штормграда решили поощрить тебя за успехи.$B$BМы приказали придворному чаротворцу изготовить тебе специальный посох.$B$BНо прежде нужно собрать материалы для этого оружия, а найти их можно только в проклятой крепости Темного Клыка, что в Серебряном бору. Отправляйся туда и добудь затерянный святой символ командира Спрингвейла, осененное луной дерево и сущность духов, обитающих в крепости.','Отправляйтесь в крепость Темного Клыка и добудьте святой символ командира у командира Спрингвейла, 5 вязанок осененного луной дерева и 5 призрачных субстанций.','Поговорите с Луканом Корделлом в квартале магов Штормграда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Избранник Элуны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gистинный почитатель:истинная почитательница; Элуны, пример для нашего народа и $gпреданный поборник:преданная поборница; Альянса. Храм Луны и королевский двор Штормграда решили поощрить тебя за успехи.$B$BМы приказали придворному чаротворцу изготовить тебе специальный посох.$B$BНо прежде нужно собрать материалы для этого оружия, а найти их можно только в проклятой крепости Темного Клыка, что в Серебряном бору. Отправляйся туда и добудь затерянный святой символ командира Спрингвейла, осененное луной дерево и сущность духов, обитающих в крепости.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в крепость Темного Клыка и добудьте святой символ командира у командира Спрингвейла, 5 вязанок осененного луной дерева и 5 призрачных субстанций.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Луканом Корделлом в квартале магов Штормграда.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27363,'Талантливый молодой хирург','Ты $gпоказал:показала; себя $gотличным жрецом:отличной жрицей; и $gзаслужил:заслужила; уважение народа Гномрегана. Главный механик вместе с королем Штромграда решили вознаградить тебя за преданность Альянсу.$B$BОни приказали придворному чаротворцу изготовить тебе специальный посох.$B$BНо прежде нужно собрать материалы для этого оружия, а найти их можно только в проклятой крепости Темного Клыка, что в Серебряном бору. Отправляйся туда и добудь затерянный святой символ командира Спрингвейла, осененное луной дерево и сущность духов, обитающих в крепости.','Отправляйтесь в крепость Темного Клыка и добудьте святой символ командира у командира Спрингвейла, 5 вязанок осененного луной дерева и 5 призрачных субстанций.','Поговорите с Луканом Корделлом в квартале магов Штормграда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Талантливый молодой хирург',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gпоказал:показала; себя $gотличным жрецом:отличной жрицей; и $gзаслужил:заслужила; уважение народа Гномрегана. Главный механик вместе с королем Штромграда решили вознаградить тебя за преданность Альянсу.$B$BОни приказали придворному чаротворцу изготовить тебе специальный посох.$B$BНо прежде нужно собрать материалы для этого оружия, а найти их можно только в проклятой крепости Темного Клыка, что в Серебряном бору. Отправляйся туда и добудь затерянный святой символ командира Спрингвейла, осененное луной дерево и сущность духов, обитающих в крепости.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в крепость Темного Клыка и добудьте святой символ командира у командира Спрингвейла, 5 вязанок осененного луной дерева и 5 призрачных субстанций.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Луканом Корделлом в квартале магов Штормграда.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (27364,'По чьему приказу?','<ПУО жужжит.>$B$B7-й легион – элитное подразделение. Почти за всеми основными диверсионными и наступательными операциями Альянса стоят именно они! Это плохая новость. Как они проскользнули мимо наших боевых кораблей? И по чьему распоряжению?$B$BМы должны добыть их приказы. Этот тип, Пьетро, наверняка владел важной информацией. Найди его в Соборном квартале в Гилнеасе, уничтожь и обыщи тело.','Добудьте приказы верховного командования.','Поговорите с командиром передовой Штурмом в передовом отряде Отрекшихся в руинах Гилнеаса.','Твоя следующая цель – Зарен.','Старший сержант Пьетро Зарен','Мы теряем передовой отряд Отрекшихся.','Командир передовой Штурм') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','По чьему приказу?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<ПУО жужжит.>$B$B7-й легион – элитное подразделение. Почти за всеми основными диверсионными и наступательными операциями Альянса стоят именно они! Это плохая новость. Как они проскользнули мимо наших боевых кораблей? И по чьему распоряжению?$B$BМы должны добыть их приказы. Этот тип, Пьетро, наверняка владел важной информацией. Найди его в Соборном квартале в Гилнеасе, уничтожь и обыщи тело.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте приказы верховного командования.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с командиром передовой Штурмом в передовом отряде Отрекшихся в руинах Гилнеаса.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Твоя следующая цель – Зарен.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Старший сержант Пьетро Зарен',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Мы теряем передовой отряд Отрекшихся.',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Командир передовой Штурм',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27365,'Достойное оружие','С самого начала наставники видели, что ты принесешь славу Орде. Ты отважно $gстражался:сражалась;, враги недаром тебя боятся.$B$BВ награду за твою самоотверженность Вождь велел своему личному кузнецу выковать тебе особое оружие.$B$BМатериалы для него можно добыть только в проклятой крепости Темного Клыка в Серебряном бору. Отправляйся туда и отыщи потерянный меч семьи Сильверлейнов, слитки лунной стали и жилы вурдалаков и упырей, которых полно в крепости.','Отправляйтесь в крепость Темного Клыка, добудьте у барона Сильверлейна меч семьи Сильверлейнов, а также 5 слитков лунной стали и 5 жил нежити.','Поговорите с Сару Холодной Яростью на Аллее Чести в Оргриммаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Достойное оружие',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','С самого начала наставники видели, что ты принесешь славу Орде. Ты отважно $gстражался:сражалась;, враги недаром тебя боятся.$B$BВ награду за твою самоотверженность Вождь велел своему личному кузнецу выковать тебе особое оружие.$B$BМатериалы для него можно добыть только в проклятой крепости Темного Клыка в Серебряном бору. Отправляйся туда и отыщи потерянный меч семьи Сильверлейнов, слитки лунной стали и жилы вурдалаков и упырей, которых полно в крепости.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в крепость Темного Клыка, добудьте у барона Сильверлейна меч семьи Сильверлейнов, а также 5 слитков лунной стали и 5 жил нежити.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Сару Холодной Яростью на Аллее Чести в Оргриммаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27366,'Захват земель','Мой чудесный, прекрасный берег заполонили закаленные стражи Орды.$B$B<Лейтенант указывает на север.>$B$BУбей их.','Убейте 12 закаленных стражей на Сумеречном берегу на Сумеречном нагорье.','Вернитесь на Сумеречный берег на Сумеречном нагорье и доложите о своем успехе лейтенанту Эмри.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Захват земель',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мой чудесный, прекрасный берег заполонили закаленные стражи Орды.$B$B<Лейтенант указывает на север.>$B$BУбей их.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 закаленных стражей на Сумеречном берегу на Сумеречном нагорье.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь на Сумеречный берег на Сумеречном нагорье и доложите о своем успехе лейтенанту Эмри.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27367,'Гидвин Златокос','Ты не думай, я души не чаю в своих мальчиках. Но я же ЧЕТКО И ЯСНО СКАЗАЛА им, что мне нужно всего ПЯТЬ МИНУТ на то, чтобы почистить и напоить лошадей! И что? Они придумали какое-то дурацкое пари и умчались! И так происходит постоянно...$B$BМаленький – это Гидвин. Он побежал на север, вдоль реки. Если ты встретишь его, пожалуйста, скажи, чтобы он возвращался сюда. Нам нужно как можно скорее добраться до часовни Последней Надежды, но без него я не уеду.','Найдите Гидвина Златокоса в Восточных Чумных землях.','Таренар?! Это ты?$B$BКто бы то ни был, помоги мне!','Помоги мне найти Гидвина!','Гидвин Златокос') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гидвин Златокос',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты не думай, я души не чаю в своих мальчиках. Но я же ЧЕТКО И ЯСНО СКАЗАЛА им, что мне нужно всего ПЯТЬ МИНУТ на то, чтобы почистить и напоить лошадей! И что? Они придумали какое-то дурацкое пари и умчались! И так происходит постоянно...$B$BМаленький – это Гидвин. Он побежал на север, вдоль реки. Если ты встретишь его, пожалуйста, скажи, чтобы он возвращался сюда. Нам нужно как можно скорее добраться до часовни Последней Надежды, но без него я не уеду.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Гидвина Златокоса в Восточных Чумных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Таренар?! Это ты?$B$BКто бы то ни был, помоги мне!',`offerrewardtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Помоги мне найти Гидвина!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Гидвин Златокос',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27368,'В сети','$GВидел:Видела; бы ты, как я дерусь! Штук шесть этих тварей убил, когда...$B$BА, стой, ты же трупы можешь посчитать, да? Ну, ладно. Я уже с четырьмя разобрался, и тут пятый пускает в меня свою паутину. А хуже всего то, что когда он в меня ее запустил, у меня рот был открыт!$B$BНикак не могу порвать эту проклятую паутину. У тебя это тоже вряд ли получится. Придется тебе добыть желудочного сока этих паукообразных тварей. Только так можно освободиться от пут.','Наберите 8 сосудов кишечной слизи нерубов в Туннеле Ужаса.','Уже вернулся? Прежде чем плеснуть на меня этой кислотой, ответь на один вопрос: ты случайно не из этих восьминогих мерзавцев? Надо же мне знать – благодарить тебя или бить, когда освобожусь.','Боже... Фиона будет рвать и метать. Лучше бы тебе поторопиться.','Вернитесь к Гидвину Златокосу на реку Тондрорил в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В сети',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$GВидел:Видела; бы ты, как я дерусь! Штук шесть этих тварей убил, когда...$B$BА, стой, ты же трупы можешь посчитать, да? Ну, ладно. Я уже с четырьмя разобрался, и тут пятый пускает в меня свою паутину. А хуже всего то, что когда он в меня ее запустил, у меня рот был открыт!$B$BНикак не могу порвать эту проклятую паутину. У тебя это тоже вряд ли получится. Придется тебе добыть желудочного сока этих паукообразных тварей. Только так можно освободиться от пут.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Наберите 8 сосудов кишечной слизи нерубов в Туннеле Ужаса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Уже вернулся? Прежде чем плеснуть на меня этой кислотой, ответь на один вопрос: ты случайно не из этих восьминогих мерзавцев? Надо же мне знать – благодарить тебя или бить, когда освобожусь.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Боже... Фиона будет рвать и метать. Лучше бы тебе поторопиться.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гидвину Златокосу на реку Тондрорил в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27369,'Не подмажешь – не поедешь','Извини. Мне показалось, что ты жуткий огромный паук, который пытается сделать вид, что он – |3-6($r).$B$BКак поживаешь? Гидвин Златокос к твоим услугам. Вообще-то я спешу – мне нужно вернуться в караван. Но, может, ты окажешь мне одну услугу? Моя подруга Фиона торгует всякой всячиной и, возможно, ей бы пригодились травы, которые растут здесь на берегу реки.$B$BЕсли мы наберем для нее разных травок, то тогда она не станет меня убивать. По крайней мере, я на это надеюсь.','Соберите 10 колокольчиков банши на берегу реки Тондрорил.','Я порву этого паладина-недоростка в клочья еще до того, как он... минутку! Это колокольчики банши? Мне?$B$BО, Гидвин попросил тебя передать? Он такой милый! Ладно, я его прощаю.','Что, Гидди и тебя втянул в это дело?','Поговорите с Фионой на берегу реки Тондрорил в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Не подмажешь – не поедешь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Извини. Мне показалось, что ты жуткий огромный паук, который пытается сделать вид, что он – |3-6($r).$B$BКак поживаешь? Гидвин Златокос к твоим услугам. Вообще-то я спешу – мне нужно вернуться в караван. Но, может, ты окажешь мне одну услугу? Моя подруга Фиона торгует всякой всячиной и, возможно, ей бы пригодились травы, которые растут здесь на берегу реки.$B$BЕсли мы наберем для нее разных травок, то тогда она не станет меня убивать. По крайней мере, я на это надеюсь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 колокольчиков банши на берегу реки Тондрорил.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я порву этого паладина-недоростка в клочья еще до того, как он... минутку! Это колокольчики банши? Мне?$B$BО, Гидвин попросил тебя передать? Он такой милый! Ладно, я его прощаю.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что, Гидди и тебя втянул в это дело?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Фионой на берегу реки Тондрорил в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27370,'Таренар Удар Солнца','Как только мы остановились, они поспорили о том, кто убьет больше нежити за пять минут.$B$BПрошел уже целый час, а они все еще не вернулись.$B$BЯ видела, что Таренар побежал на юго-восток. Но, к сожалению, никак не могу бросить караван. Если вдруг встретишь его, пожалуйста, отправь сюда.','Найдите Таренара Удар Солнца в Ступенях Смерти в Восточных Чумных землях.','Помоги мне найти Таренара!','Таренар Удар Солнца') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Таренар Удар Солнца',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как только мы остановились, они поспорили о том, кто убьет больше нежити за пять минут.$B$BПрошел уже целый час, а они все еще не вернулись.$B$BЯ видела, что Таренар побежал на юго-восток. Но, к сожалению, никак не могу бросить караван. Если вдруг встретишь его, пожалуйста, отправь сюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Таренара Удар Солнца в Ступенях Смерти в Восточных Чумных землях.',`objectives_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Помоги мне найти Таренара!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Таренар Удар Солнца',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27371,'Мои таланты','Помнится, в молодости я пробирался в Призрачные земли и часами напролет рубил там зомби. Причем никто мне за это не платил. Я это делал просто так.$B$BТеперь посмотри вперед. С этими зомби шутки плохи. Я как раз собирался ими заняться. Не хочешь присоединиться?','Уничтожьте 5 зомби в Ступенях Смерти, что в Восточных Чумных землях.','Вернитесь к Таренару Удару Солнца в Ступени Смерти, что в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мои таланты',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Помнится, в молодости я пробирался в Призрачные земли и часами напролет рубил там зомби. Причем никто мне за это не платил. Я это делал просто так.$B$BТеперь посмотри вперед. С этими зомби шутки плохи. Я как раз собирался ими заняться. Не хочешь присоединиться?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 5 зомби в Ступенях Смерти, что в Восточных Чумных землях.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Таренару Удару Солнца в Ступени Смерти, что в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27372,'Подарок для Фионы','У моей спутницы Фионы небольшая лавка. Мы с ней и моим другом Гидвином едем в часовню Последней Надежды. Если хочешь, можешь к нам присоединиться... Правда, сейчас Фиона на меня злится.$B$BНо у нее есть одно хорошее свойство: если сделать ей подарок, она тут же забывает, на что злилась. Иди на север и убей несколько чумных псов, набери их крови и отнеси Фионе. Вот увидишь, она обрадуется. Сейчас Фиона у реки, рядом с караваном. Там и поговорим.','Соберите 10 образцов крови чумных псов.','Это именно то, что нужно! Ладно, я прощаю Таренара.$B$BТюлип, можешь присоединиться к нам, если хочешь.','Таренар заставил тебя сделать мне подарок? Я так и знала! Идиот!$B$BМм-м... так что там за подарок?','Поговорите с Фионой на берегу реки Тондрорил в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подарок для Фионы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У моей спутницы Фионы небольшая лавка. Мы с ней и моим другом Гидвином едем в часовню Последней Надежды. Если хочешь, можешь к нам присоединиться... Правда, сейчас Фиона на меня злится.$B$BНо у нее есть одно хорошее свойство: если сделать ей подарок, она тут же забывает, на что злилась. Иди на север и убей несколько чумных псов, набери их крови и отнеси Фионе. Вот увидишь, она обрадуется. Сейчас Фиона у реки, рядом с караваном. Там и поговорим.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 образцов крови чумных псов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это именно то, что нужно! Ладно, я прощаю Таренара.$B$BТюлип, можешь присоединиться к нам, если хочешь.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Таренар заставил тебя сделать мне подарок? Я так и знала! Идиот!$B$BМм-м... так что там за подарок?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Фионой на берегу реки Тондрорил в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27373,'Вперед, к часовне Последней Надежды!','Ну вот, ребята вернулись – и можно ехать. Ты куда направляешься? На восток?$B$BПоехали с нами! Прошу! Нет, настаиваю! Вчера мы были на Участке Целителей Земли, и я как раз говорила Таренару: "У нас есть два паладина, один торговец, но вот кто нам действительно нужен, так это |3-6($c)!"$B$BТы что, не веришь? Я не шучу! Давай, забирайся в повозку.','Присоединяйтесь к каравану Фионы у реки Тондрорил в Восточных Чумных землях.','Надеюсь, тебя не слишком укачало в дороге.$B$BПока лошади отдыхают, можешь осмотреть башню. Это, конечно, не Часовня Последней Надежды, но, думаю, ты все же найдешь, чем заняться.','Поговорите с Фионой в Башне королевской стражи в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вперед, к часовне Последней Надежды!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну вот, ребята вернулись – и можно ехать. Ты куда направляешься? На восток?$B$BПоехали с нами! Прошу! Нет, настаиваю! Вчера мы были на Участке Целителей Земли, и я как раз говорила Таренару: "У нас есть два паладина, один торговец, но вот кто нам действительно нужен, так это |3-6($c)!"$B$BТы что, не веришь? Я не шучу! Давай, забирайся в повозку.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Присоединяйтесь к каравану Фионы у реки Тондрорил в Восточных Чумных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Надеюсь, тебя не слишком укачало в дороге.$B$BПока лошади отдыхают, можешь осмотреть башню. Это, конечно, не Часовня Последней Надежды, но, думаю, ты все же найдешь, чем заняться.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Фионой в Башне королевской стражи в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27374,'Бездна безумия','Не могу поверить, $n. Мой собственный сын, моя плоть и кровь, cвязался с этими фанатиками из культа Сумеречного Молота! $gВидел:Видела;, во что он превратился, когда попробовал помешать свадьбе? Ну, почему? Почему он?$B$BЭто все чудовище, $n. Оно во всем виновато. Эта зияющая пасть, торчащая из земли к западу отсюда. "Бездна безумия", как называл ее мой сын. Он рассказывал, что она говорила с ним, но я думал, это всего лишь его ночные кошмары.$B$BИди на запад, найди заклинателя земли Торунскара и предложи ему свою помощь!','Поговорите с Заклинателем земли Торунскаром в Круге Стихий.','Добро пожаловать, сестренка. Времена сейчас тяжелые, но мы рады, что ты с нами. Помощь нам не помешает.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бездна безумия',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не могу поверить, $n. Мой собственный сын, моя плоть и кровь, cвязался с этими фанатиками из культа Сумеречного Молота! $gВидел:Видела;, во что он превратился, когда попробовал помешать свадьбе? Ну, почему? Почему он?$B$BЭто все чудовище, $n. Оно во всем виновато. Эта зияющая пасть, торчащая из земли к западу отсюда. "Бездна безумия", как называл ее мой сын. Он рассказывал, что она говорила с ним, но я думал, это всего лишь его ночные кошмары.$B$BИди на запад, найди заклинателя земли Торунскара и предложи ему свою помощь!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Заклинателем земли Торунскаром в Круге Стихий.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Добро пожаловать, сестренка. Времена сейчас тяжелые, но мы рады, что ты с нами. Помощь нам не помешает.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27375,'Кровоточащая рана','Монстр, $n! Я видела зверя – голодного, с огромной пастью! Они даже не представляют, кого выпустили на свободу.$B$BЭта тварь здесь. Ее ужасное бесформенное тело извергается прямо на нагорье.$B$BВ своем сне я видела и тебя, $n. Вместе со Служителями Земли ты борешься против зверя. Тебе предстоит сойтись в схватке с Тьмой.$B$BИди, пока монстр не набрался сил. Следуй на северо-запад – там, в горах, за разрушенным лагерем дракгоров, в Круге Стихий, тебя ждет Заклинатель земли Торунскар. Поторопись!','Поговорите с Заклинателем земли Торунскаром в Круге Стихий.','Добро пожаловать, братишка. Времена сейчас тяжелые, но мы рады, что ты с нами. Помощь нам не помешает.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кровоточащая рана',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Монстр, $n! Я видела зверя – голодного, с огромной пастью! Они даже не представляют, кого выпустили на свободу.$B$BЭта тварь здесь. Ее ужасное бесформенное тело извергается прямо на нагорье.$B$BВ своем сне я видела и тебя, $n. Вместе со Служителями Земли ты борешься против зверя. Тебе предстоит сойтись в схватке с Тьмой.$B$BИди, пока монстр не набрался сил. Следуй на северо-запад – там, в горах, за разрушенным лагерем дракгоров, в Круге Стихий, тебя ждет Заклинатель земли Торунскар. Поторопись!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Заклинателем земли Торунскаром в Круге Стихий.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Добро пожаловать, братишка. Времена сейчас тяжелые, но мы рады, что ты с нами. Помощь нам не помешает.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27376,'Пасть Изо\'рата','Мы готовы напасть на зверя. Сначала нужно уничтожить щупальца; потом Ева проведет ритуал и вызовет могущественного элементаля огня, которого мы бросим в пасть чудовища.$B$BЛети туда с первой ударной группой. Дождись подходящего момента и помоги шаманам рубить щупальца.$B$BКогда решишь, что можешь идти в бой, возьми одного из грифонов.','Садитесь на грифона и присоединяйтесь к атаке на Изо\'рата.','Эти щупальца стащили нас с грифонов! Оказалось, что они гораздо ловчее, чем мы предполагали.$B$BНо это уже не важно. Мы предусмотрели такую возможность. Если ты защитишь меня, я смогу вызвать элементаля.','Поговорите с заклинательницей земли Евой в чреве Изо\'рата, который находится на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пасть Изо\'рата',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы готовы напасть на зверя. Сначала нужно уничтожить щупальца; потом Ева проведет ритуал и вызовет могущественного элементаля огня, которого мы бросим в пасть чудовища.$B$BЛети туда с первой ударной группой. Дождись подходящего момента и помоги шаманам рубить щупальца.$B$BКогда решишь, что можешь идти в бой, возьми одного из грифонов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Садитесь на грифона и присоединяйтесь к атаке на Изо\'рата.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Эти щупальца стащили нас с грифонов! Оказалось, что они гораздо ловчее, чем мы предполагали.$B$BНо это уже не важно. Мы предусмотрели такую возможность. Если ты защитишь меня, я смогу вызвать элементаля.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с заклинательницей земли Евой в чреве Изо\'рата, который находится на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (27377,'Пожиратель','Мы знали, что это возможно, но и понятия не имели, как именно этот зверь будет защищаться. Тело Изо\'рата слишком быстро реагирует на опасность.$B$BЯ могу завершить ритуал, но только если ты защитишь меня от Изо\'рата. Действуй! Мы победим!','Защитите себя и заклинательницу земли Еву от атак Изо\'рата.','Мне удалось вырвать тебя из объятий смерти!$B$BСмертокрыл уже здесь! Нам нужна твоя помощь!','Поговорите с Траллом в Водовороте.','В самое пекло.','Тралл') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пожиратель',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы знали, что это возможно, но и понятия не имели, как именно этот зверь будет защищаться. Тело Изо\'рата слишком быстро реагирует на опасность.$B$BЯ могу завершить ритуал, но только если ты защитишь меня от Изо\'рата. Действуй! Мы победим!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Защитите себя и заклинательницу земли Еву от атак Изо\'рата.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мне удалось вырвать тебя из объятий смерти!$B$BСмертокрыл уже здесь! Нам нужна твоя помощь!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Траллом в Водовороте.',`completedtext_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','В самое пекло.',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Тралл',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (27378,'Разрушитель миров','У нас нет времени! Смертокрыл нанес удар раньше, чем мы успели приготовиться. Если ты не остановишь его, этот день станет последним для Служителей Земли!','Победите Смертокрыла, Аспекта смерти.','Поговорите с заклинательницей земли Евой в чреве Изо\'рата, который находится на Сумеречном нагорье.','Только ты можешь противостоять Разрушителю Миров. Если ты потерпишь поражение, Азерот обречен.','Смертокрыл','Кошмары грозят поглотить нас всех и ввергнуть во власть Н\'Зота.','Ева') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разрушитель миров',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У нас нет времени! Смертокрыл нанес удар раньше, чем мы успели приготовиться. Если ты не остановишь его, этот день станет последним для Служителей Земли!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Смертокрыла, Аспекта смерти.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с заклинательницей земли Евой в чреве Изо\'рата, который находится на Сумеречном нагорье.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Только ты можешь противостоять Разрушителю Миров. Если ты потерпишь поражение, Азерот обречен.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Смертокрыл',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Кошмары грозят поглотить нас всех и ввергнуть во власть Н\'Зота.',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Ева',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27379,'Ужас Изо\'рата','Вернись, нам нужна твоя помощь! Похоже, тебя, как и многих других шаманов, поглотил какой-то кошмар.$B$BНаш план рушится. Некоторые наши шаманы создают защитные ауры, чтобы защитить тебя от пищеварительного сока и спасти твою жизнь. Однако нужно высвободить из щупалец остальных шаманов. Мы не сможем побороть Изо\'рата без их помощи! Не оставайся в чреве чудовища слишком долго, если рядом нет другого шамана, иначе ты будешь $gпереварен:переварена; заживо!','Спасите Харгота Бледное Пламя, целителя земли Дуарна, буревестницу Джалару и буревестницу Милру.$B$BВозвращайтесь под защиту ауры шамана, если Изо\'рат начнет вас переваривать.','Вместе со Служителями Земли мы оказались способны пережить ужасы Изо\'рата. Теперь же настало время покарать чудовище.','Поговорите с заклинательницей земли Евой в чреве Изо\'рата, который находится на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ужас Изо\'рата',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вернись, нам нужна твоя помощь! Похоже, тебя, как и многих других шаманов, поглотил какой-то кошмар.$B$BНаш план рушится. Некоторые наши шаманы создают защитные ауры, чтобы защитить тебя от пищеварительного сока и спасти твою жизнь. Однако нужно высвободить из щупалец остальных шаманов. Мы не сможем побороть Изо\'рата без их помощи! Не оставайся в чреве чудовища слишком долго, если рядом нет другого шамана, иначе ты будешь $gпереварен:переварена; заживо!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Спасите Харгота Бледное Пламя, целителя земли Дуарна, буревестницу Джалару и буревестницу Милру.$B$BВозвращайтесь под защиту ауры шамана, если Изо\'рат начнет вас переваривать.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вместе со Служителями Земли мы оказались способны пережить ужасы Изо\'рата. Теперь же настало время покарать чудовище.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с заклинательницей земли Евой в чреве Изо\'рата, который находится на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27380,'Кошмар','Мы нашли мозг Изо\'рата! Шаманы, которых ты $gспас:спасла;, будут держать тебя под своей защитой.$B$BПорази мозг Изо\'рата и сокруши чудовище!','Уничтожьте мозг Изо\'рата.','Поговорите с Заклинателем земли Торунскаром в Круге Стихий на Сумеречном нагорье.','Вместилище Кошмаров.','Изо\'рат') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кошмар',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы нашли мозг Изо\'рата! Шаманы, которых ты $gспас:спасла;, будут держать тебя под своей защитой.$B$BПорази мозг Изо\'рата и сокруши чудовище!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте мозг Изо\'рата.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Заклинателем земли Торунскаром в Круге Стихий на Сумеречном нагорье.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Вместилище Кошмаров.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Изо\'рат',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27381,'Попутчики','Найдите в Башне королевской стражи того, кто захочет присоединиться к вашему каравану.','Аргус Путеводный... Этот старик на вершине башни? Отлично!$B$BСудя по возрасту, он уже давно служит Серебряному Авангарду. Может, он замолвит за нас словечко в Часовне.','Вернитесь к Таренару в Башню королевской стражи в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Попутчики',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите в Башне королевской стражи того, кто захочет присоединиться к вашему каравану.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Аргус Путеводный... Этот старик на вершине башни? Отлично!$B$BСудя по возрасту, он уже давно служит Серебряному Авангарду. Может, он замолвит за нас словечко в Часовне.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Таренару в Башню королевской стражи в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27382,'Плохие дороги','Серебряный Авангард построил эти башни, чтобы они стали источниками света во тьме Чумных земель. Я ремонтирую и защищаю эти башни.$B$BПравда, в последнее время связывающие их дороги стали опасными – на неосторожных путников нападают дикие звери и жуткие летучие мыши. Мне было бы гораздо проще, если бы тебе удалось расчистить дорогу.','Убейте 13 чумных нетопырей на тропе, ведущей в Башню Защиты Света.','Поговорите с Аргусом Путеводным на Башне королевской стражи в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Плохие дороги',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Серебряный Авангард построил эти башни, чтобы они стали источниками света во тьме Чумных земель. Я ремонтирую и защищаю эти башни.$B$BПравда, в последнее время связывающие их дороги стали опасными – на неосторожных путников нападают дикие звери и жуткие летучие мыши. Мне было бы гораздо проще, если бы тебе удалось расчистить дорогу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 13 чумных нетопырей на тропе, ведущей в Башню Защиты Света.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Аргусом Путеводным на Башне королевской стражи в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27383,'Малышка Памела','Я никак не могу забыть битву за Дарроушир, |3-6($r). Просыпаюсь в холодном поту, и мне кажется, что я все еще там, что все повторяется.$B$BЯ пережил потерю боевых товарищей, но боль от утраты родных слишком велика. Одна из них, моя юная племянница Памела, пропала без вести в самый разгар сражения.$B$BЕсли тебе хватит храбрости, отправляйся в Дарроушир и попробуй отыскать Памелу. Руины Дарроушира находятся к югу отсюда.','Найдите Памелу Редпат в Дарроушире.','Привет, я Памела. А как тебя зовут?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Малышка Памела',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я никак не могу забыть битву за Дарроушир, |3-6($r). Просыпаюсь в холодном поту, и мне кажется, что я все еще там, что все повторяется.$B$BЯ пережил потерю боевых товарищей, но боль от утраты родных слишком велика. Одна из них, моя юная племянница Памела, пропала без вести в самый разгар сражения.$B$BЕсли тебе хватит храбрости, отправляйся в Дарроушир и попробуй отыскать Памелу. Руины Дарроушира находятся к югу отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Памелу Редпат в Дарроушире.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Привет, я Памела. А как тебя зовут?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27384,'Кукла Памелы','Тетушка Марлен велела мне сидеть дома, потому что папа ушел на войну. Мой папа – самый смелый на свете!$B$BНо я сижу здесь уже очень долго, а его все нету. Иногда приходят злые люди и что-то шепчут, а без папы их никто не прогонит!$B$BА когда темнеет, мне очень хочется поиграть с моей куклой, но ее тоже нет, она осталась в городе.$B$BМожет, ты ее поищешь?','Найдите куклу Памелы.','Нашлась! Нашлась моя куколка! О, спасибо тебе!','Вернитесь к Памеле Редпат в Дарроушир в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кукла Памелы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тетушка Марлен велела мне сидеть дома, потому что папа ушел на войну. Мой папа – самый смелый на свете!$B$BНо я сижу здесь уже очень долго, а его все нету. Иногда приходят злые люди и что-то шепчут, а без папы их никто не прогонит!$B$BА когда темнеет, мне очень хочется поиграть с моей куклой, но ее тоже нет, она осталась в городе.$B$BМожет, ты ее поищешь?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите куклу Памелы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Нашлась! Нашлась моя куколка! О, спасибо тебе!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Памеле Редпат в Дарроушир в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27385,'Дядюшка Карлин','С куклой я с удовольствием поиграю, а вот с папиным мечом совсем не хочется. Возьми его себе.$B$BА еще лучше – отнеси меч моему дяде Карлину! Я не знаю точно, где он... но иногда слышу, как он рыдает... к северу отсюда... совсем близко.$B$BНадеюсь, он плачет не по мне. $n, ты ведь найдешь дядю и скажешь, что со мной все хорошо?$B$BСкажи ему, что я его жду и очень хочу услышать историю, которую он часто рассказывал... ту, о кроликах и варенье! Такая смешная история!','Вернитесь к Карлину Редпату к башне Королевской Стражи в Восточных Чумных землях.','Есть новости о моей малышке Памеле?','Вернитесь к Карлину Редпату, находящемуся у башни Королевской Стражи в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дядюшка Карлин',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','С куклой я с удовольствием поиграю, а вот с папиным мечом совсем не хочется. Возьми его себе.$B$BА еще лучше – отнеси меч моему дяде Карлину! Я не знаю точно, где он... но иногда слышу, как он рыдает... к северу отсюда... совсем близко.$B$BНадеюсь, он плачет не по мне. $n, ты ведь найдешь дядю и скажешь, что со мной все хорошо?$B$BСкажи ему, что я его жду и очень хочу услышать историю, которую он часто рассказывал... ту, о кроликах и варенье! Такая смешная история!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь к Карлину Редпату к башне Королевской Стражи в Восточных Чумных землях.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Есть новости о моей малышке Памеле?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Карлину Редпату, находящемуся у башни Королевской Стражи в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27386,'Странный историк','Этот меч принадлежал Джозефу Редпату, отцу Памелы – но ты наверняка все это знаешь. Жаль, Джозефу не доведется больше встретиться с дочерью – его душу осквернила Плеть, и теперь он стал чудовищем.$B$BСудьбу Памелы уже не изменить, но участь Джозефа облегчить можно.$B$BНе так давно в нашу башню прибыла необычная гномиха. Ее зовут Хроми. Отнеси ей этот меч – у меня такое чувство, что она сможет помочь.','Отнесите охотничий клинок Джозефа Хроми.','Что это? Меч? Или кухонный нож? Я ничего не смыслю в оружии. Дай-ка посмотреть...$B$BКогда-то этим мечом владел великий воин, но в его прошлом была ужасная трагедия.$B$BТы здесь, чтобы ему помочь? Уже слишком поздно... Хотя, возможно, мы и сумеем исправить его прошлое!','Как вовремя ты прибыл. Уж не из будущего ли ты?','Вернитесь к Хроми в Башню королевской стражи в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Странный историк',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этот меч принадлежал Джозефу Редпату, отцу Памелы – но ты наверняка все это знаешь. Жаль, Джозефу не доведется больше встретиться с дочерью – его душу осквернила Плеть, и теперь он стал чудовищем.$B$BСудьбу Памелы уже не изменить, но участь Джозефа облегчить можно.$B$BНе так давно в нашу башню прибыла необычная гномиха. Ее зовут Хроми. Отнеси ей этот меч – у меня такое чувство, что она сможет помочь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите охотничий клинок Джозефа Хроми.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что это? Меч? Или кухонный нож? Я ничего не смыслю в оружии. Дай-ка посмотреть...$B$BКогда-то этим мечом владел великий воин, но в его прошлом была ужасная трагедия.$B$BТы здесь, чтобы ему помочь? Уже слишком поздно... Хотя, возможно, мы и сумеем исправить его прошлое!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как вовремя ты прибыл. Уж не из будущего ли ты?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хроми в Башню королевской стражи в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27387,'Негодяи Дарроушира','В Анналах Дарроушира упоминается о самых мерзких воинах, участвовавших в том сражении. Там рассказывается, как Альянс разбил силы лорда Хоргуса Опустошителя. Лорда убили в холмах к северу отсюда, и череп его остался там.$B$BМардука Черного так и не одолели, но его легендарный меч остался без хозяина и наверняка уже покрылся ржавчиной... Он лежит где-то у дороги к юго-востоку отсюда.$B$BПринеси мне эти предметы, $n. Не знаю почему, но твоя судьба связана с ними.','Принесите череп Хоргуса и сломанный меч Мардука Хроми в Башню королевской стражи в Восточных Чумных землях.','Поговорите с Хроми в Башне королевской стражи в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Негодяи Дарроушира',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В Анналах Дарроушира упоминается о самых мерзких воинах, участвовавших в том сражении. Там рассказывается, как Альянс разбил силы лорда Хоргуса Опустошителя. Лорда убили в холмах к северу отсюда, и череп его остался там.$B$BМардука Черного так и не одолели, но его легендарный меч остался без хозяина и наверняка уже покрылся ржавчиной... Он лежит где-то у дороги к юго-востоку отсюда.$B$BПринеси мне эти предметы, $n. Не знаю почему, но твоя судьба связана с ними.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите череп Хоргуса и сломанный меч Мардука Хроми в Башню королевской стражи в Восточных Чумных землях.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Хроми в Башне королевской стражи в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27388,'Герои Дарроушира','У героев Дарроушира есть свои реликвии, а в них – драгоценная память.$B$BДля начала поговори с Карлином и добудь дополненные анналы Дарроушира. В этой книге содержится повесть, которая проведет нас сквозь прошлое.$B$BЗатем отправляйся на запад в поместье Маррисов. Покойный владелец фермы Маррисов собирал реликвии битвы при Дарроушире – зачем, не знаю.$B$BЗабери эти реликвии и возвращайся ко мне.','Добудьте дополненные анналы Дарроушира у Карлин Редпат и заберите в поместье Маррисов манускрипт Дейвила и щит Редпата.','Реликвии у тебя? Хорошо. Я вернусь к работе по устранению временных неоднородностей.$B$BИ ни о чем не беспокойся... Твое дело – реактивы доставлять.','Вернитесь к Хроми в Башню королевской стражи в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Герои Дарроушира',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У героев Дарроушира есть свои реликвии, а в них – драгоценная память.$B$BДля начала поговори с Карлином и добудь дополненные анналы Дарроушира. В этой книге содержится повесть, которая проведет нас сквозь прошлое.$B$BЗатем отправляйся на запад в поместье Маррисов. Покойный владелец фермы Маррисов собирал реликвии битвы при Дарроушире – зачем, не знаю.$B$BЗабери эти реликвии и возвращайся ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте дополненные анналы Дарроушира у Карлин Редпат и заберите в поместье Маррисов манускрипт Дейвила и щит Редпата.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Реликвии у тебя? Хорошо. Я вернусь к работе по устранению временных неоднородностей.$B$BИ ни о чем не беспокойся... Твое дело – реактивы доставлять.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хроми в Башню королевской стражи в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27389,'Мародеры Дарроушира','Собранные тобою реликвии необходимы для создания заклятия великой силы, но надо достать еще одну вещь – черепа воинов Плети, принимавших участие в битве при Дарроушире.$B$BВозьми вот этот кристалл и ищи воителей Плети. Кристалл зачарован: если воитель принимал участие в битве, то – когда над его черепом пронесешь кристалл – череп издаст звук. Добудь мне такие черепа.$B$BСтупай, $n. Ты найдешь воителей Плети в Грибной долине на севере. Иди же.','Принесите 5 резонирующих черепов Хроми в Башню королевской стражи в Восточных Чумных землях.','Черепа удалось добыть? Они необходимы для моего заклинания, а оно даст нам шанс спасти Дарроушир. Возможно...','Поговорите с Хроми в Башне королевской стражи в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мародеры Дарроушира',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Собранные тобою реликвии необходимы для создания заклятия великой силы, но надо достать еще одну вещь – черепа воинов Плети, принимавших участие в битве при Дарроушире.$B$BВозьми вот этот кристалл и ищи воителей Плети. Кристалл зачарован: если воитель принимал участие в битве, то – когда над его черепом пронесешь кристалл – череп издаст звук. Добудь мне такие черепа.$B$BСтупай, $n. Ты найдешь воителей Плети в Грибной долине на севере. Иди же.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 5 резонирующих черепов Хроми в Башню королевской стражи в Восточных Чумных землях.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Черепа удалось добыть? Они необходимы для моего заклинания, а оно даст нам шанс спасти Дарроушир. Возможно...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Хроми в Башне королевской стражи в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27390,'Битва при Дарроушире','А теперь, $n, тебе следует принять участие в битве за Дарроушир и спасти Джозефа Редпата.$B$BПоложи этот сверток с реликвиями на городской площади Дарроушира, и обитающие там духи вернутся. Присоединись к их битве и проследи за двумя моментами: Дейвил должен остаться в живых после гибели Хоргуса, a Редпат – заразиться и умереть.$B$BКогда победишь зараженного Редпата, душа его будет спасена. Поговори с духом и вернись к его дочери Памеле.','Положите сверток с реликвиями на городскую площадь Дарроушира.$B$BНе дайте Дейвилу Яркосвету умереть, пока не погибнет Хоргус.$B$BНе дайте умереть капитану Редпату, пока он не превратится в Редпата Оскверненного.$B$BУбейте Редпата Оскверненного.$B$BПоговорите с духом Джозефа Редпата, когда он появится на городской площади.','Война кончилась! Я слышала шепот моего папы. Он сказал, что прогнал все привидения и скоро придет домой. Я так рада!$B$BА еще он сказал, что мне надо быть с тобой повежливее, поэтому я заварила чай!$B$BНадеюсь, тебе нравится, когда в нем побольше сахара?','Вернитесь к Памеле Редпат в Дарроушир в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Битва при Дарроушире',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А теперь, $n, тебе следует принять участие в битве за Дарроушир и спасти Джозефа Редпата.$B$BПоложи этот сверток с реликвиями на городской площади Дарроушира, и обитающие там духи вернутся. Присоединись к их битве и проследи за двумя моментами: Дейвил должен остаться в живых после гибели Хоргуса, a Редпат – заразиться и умереть.$B$BКогда победишь зараженного Редпата, душа его будет спасена. Поговори с духом и вернись к его дочери Памеле.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Положите сверток с реликвиями на городскую площадь Дарроушира.$B$BНе дайте Дейвилу Яркосвету умереть, пока не погибнет Хоргус.$B$BНе дайте умереть капитану Редпату, пока он не превратится в Редпата Оскверненного.$B$BУбейте Редпата Оскверненного.$B$BПоговорите с духом Джозефа Редпата, когда он появится на городской площади.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Война кончилась! Я слышала шепот моего папы. Он сказал, что прогнал все привидения и скоро придет домой. Я так рада!$B$BА еще он сказал, что мне надо быть с тобой повежливее, поэтому я заварила чай!$B$BНадеюсь, тебе нравится, когда в нем побольше сахара?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Памеле Редпат в Дарроушир в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (27391,'Спрятанные сокровища','Отец велел передать тебе этот ключ. Сказал, он отпирает сундук, спрятанный за домом.$B$BИ еще просил поблагодарить тебя. Ты ему чем-то $gпомог:помогла;? Ты $gговорил:говорила; ему, что $gнашел:нашла; мою куклу?$B$BВот этот ключ. И спасибо тебе, $n. Большое спасибо! Ты очень $gдобрый:добрая;!','Отнесите ключ Джозефа к сундуку Джозефа.','Ключ проворачивается в замке, и сундук распахивается...','Сундук весь покрыт застарелой грязью.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спрятанные сокровища',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Отец велел передать тебе этот ключ. Сказал, он отпирает сундук, спрятанный за домом.$B$BИ еще просил поблагодарить тебя. Ты ему чем-то $gпомог:помогла;? Ты $gговорил:говорила; ему, что $gнашел:нашла; мою куклу?$B$BВот этот ключ. И спасибо тебе, $n. Большое спасибо! Ты очень $gдобрый:добрая;!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите ключ Джозефа к сундуку Джозефа.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ключ проворачивается в замке, и сундук распахивается...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Сундук весь покрыт застарелой грязью.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27392,'Я не должна тебе этого говорить','У моего папы было два меча: один для людей, другой – для зверей. Он не разрешал мне их трогать, но я знала, где они лежат.$B$BОднажды отец сказал маме, что идет в холмы на востоке драться с "одиноким охотником", но почему-то взял меч для охоты! Звериный меч! А когда папа вернулся, то был без меча.$B$BВот было бы здорово: он возвращается домой, а я отдаю ему звериный меч! Папа ужасно обрадуется, я знаю. Сможешь найти мне этот меч?','Заберите охотничий клинок Джозефа у Одинокого охотника в Восточных Чумных землях.','Папа любил свой звериный меч. И очень расстроился, когда его потерял.','Поговорите с Памелой Редпат в Дарроушире в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Я не должна тебе этого говорить',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У моего папы было два меча: один для людей, другой – для зверей. Он не разрешал мне их трогать, но я знала, где они лежат.$B$BОднажды отец сказал маме, что идет в холмы на востоке драться с "одиноким охотником", но почему-то взял меч для охоты! Звериный меч! А когда папа вернулся, то был без меча.$B$BВот было бы здорово: он возвращается домой, а я отдаю ему звериный меч! Папа ужасно обрадуется, я знаю. Сможешь найти мне этот меч?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заберите охотничий клинок Джозефа у Одинокого охотника в Восточных Чумных землях.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Папа любил свой звериный меч. И очень расстроился, когда его потерял.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Памелой Редпат в Дарроушире в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27393,'Зов клинка','Я чувствую, что некая сила взывает ко мне из руин. Может, вернешься на то поле боя, что к югу отсюда? Нет сомнений – там что-то есть.','Исследуйте поле битвы на южной окраине Руин Вайш\'ира.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зов клинка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я чувствую, что некая сила взывает ко мне из руин. Может, вернешься на то поле боя, что к югу отсюда? Нет сомнений – там что-то есть.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Исследуйте поле битвы на южной окраине Руин Вайш\'ира.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27394,'Зов клинка','Я чувствую, что некая сила взывает ко мне из руин. Может, вернешься на то поле боя, что к югу отсюда? Нет сомнений – там что-то есть.','Исследуйте поле битвы на южной окраине Руин Вайш\'ира.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зов клинка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я чувствую, что некая сила взывает ко мне из руин. Может, вернешься на то поле боя, что к югу отсюда? Нет сомнений – там что-то есть.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Исследуйте поле битвы на южной окраине Руин Вайш\'ира.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27395,'Оружие стрелка','Ты быстро осваиваешь мастерство охотника, $n. Твои способности вызывают уважение Орды и восхищение других новичков.$B$BЧтобы поощрить тебя за успехи, вождь приказал своему личному мастеру изготовить оружие специально для тебя.$B$BНо прежде нужно собрать материалы для этого оружия, а найти их можно только в проклятой Крепости Темного Клыка, что в Серебряном бору. Отправляйся туда и добудь хрустальный прицел Годфри, осененное луной дерево и жилы вурдалаков и упырей, обитающих в крепости.','Отправляйтесь в крепость Темного Клыка и добудьте хрустальный прицел Годфри, 5 связок осененного луной дерева и 5 жил нежити.','Для меня большая честь, что вождь попросил именно меня изготовить тебе оружие, Вопастрел. Из таких компонентов получится отличный лук.','Ты раздобыл материалы для оружия?','Поговорите с Сару Холодной Яростью на Аллее Чести в Оргриммаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оружие стрелка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты быстро осваиваешь мастерство охотника, $n. Твои способности вызывают уважение Орды и восхищение других новичков.$B$BЧтобы поощрить тебя за успехи, вождь приказал своему личному мастеру изготовить оружие специально для тебя.$B$BНо прежде нужно собрать материалы для этого оружия, а найти их можно только в проклятой Крепости Темного Клыка, что в Серебряном бору. Отправляйся туда и добудь хрустальный прицел Годфри, осененное луной дерево и жилы вурдалаков и упырей, обитающих в крепости.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в крепость Темного Клыка и добудьте хрустальный прицел Годфри, 5 связок осененного луной дерева и 5 жил нежити.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Для меня большая честь, что вождь попросил именно меня изготовить тебе оружие, Вопастрел. Из таких компонентов получится отличный лук.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты раздобыл материалы для оружия?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Сару Холодной Яростью на Аллее Чести в Оргриммаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27396,'Клинок Изувеченной Длани','Многие члены Изувеченной Длани не доживают до конца обучения, $n. Ты не только $gуцелел:уцелела;, но и скоро $gсам:сама; станешь опасным клинком в руках Орды.$B$BВ награду за твои успехи Вождь приказал своему личному кузнецу изготовить для тебя особое оружие.$B$BПроклятая крепость Темного Клыка в Серебряном бору – единственное место, где можно найти нужные для него материалы. Отправляйся туда и найди точило командира Спрингвейла, слитки лунной стали и жилы вурдалаков и упырей, обитающих в крепости.','Отправляйтесь в крепость Темного Клыка и добудьте точило командира Спрингвейла, 5 слитков лунной стали и 5 жил нежити.','Поговорите с Сару Холодной Яростью на Аллее Чести в Оргриммаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Клинок Изувеченной Длани',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Многие члены Изувеченной Длани не доживают до конца обучения, $n. Ты не только $gуцелел:уцелела;, но и скоро $gсам:сама; станешь опасным клинком в руках Орды.$B$BВ награду за твои успехи Вождь приказал своему личному кузнецу изготовить для тебя особое оружие.$B$BПроклятая крепость Темного Клыка в Серебряном бору – единственное место, где можно найти нужные для него материалы. Отправляйся туда и найди точило командира Спрингвейла, слитки лунной стали и жилы вурдалаков и упырей, обитающих в крепости.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в крепость Темного Клыка и добудьте точило командира Спрингвейла, 5 слитков лунной стали и 5 жил нежити.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Сару Холодной Яростью на Аллее Чести в Оргриммаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27397,'Стихии и духи взывают к тебе ясными голосами, $n. Ты $gстал сильным шаманом:ты стала сильной шаманкой; и примером для других желающих служить Орде.$B$BСлово о тебе дошло до слуха Вождя, и он повелел своему личному кузнецу выковать тебе особое оружие.$B$BЕдинственное место, где ты можешь добыть материалы для него, – проклятая крепость Темного Клыка в Серебряном бору. Отправляйся туда и принеси талисман командира воргенов Нандоса, книгу Потерянных Душ и сущность призраков, навещающих крепость.','Ступайте в крепость Темного Клыка и добудьте талисман Вальдена, книгу Потерянных Душ и 5 призрачных субстанций.','Поговорите с Сару Холодной Яростью на Аллее Чести в Оргриммаре.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Стихии и духи взывают к тебе ясными голосами, $n. Ты $gстал сильным шаманом:ты стала сильной шаманкой; и примером для других желающих служить Орде.$B$BСлово о тебе дошло до слуха Вождя, и он повелел своему личному кузнецу выковать тебе особое оружие.$B$BЕдинственное место, где ты можешь добыть материалы для него, – проклятая крепость Темного Клыка в Серебряном бору. Отправляйся туда и принеси талисман командира воргенов Нандоса, книгу Потерянных Душ и сущность призраков, навещающих крепость.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Ступайте в крепость Темного Клыка и добудьте талисман Вальдена, книгу Потерянных Душ и 5 призрачных субстанций.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Сару Холодной Яростью на Аллее Чести в Оргриммаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27398,'Битва выиграна, но война продолжается','Мы смогли выстоять и разгромить врага, $n! Однако Хиджал – не единственное место, где нам угрожает противник.$B$BМне доложили, что нашим союзникам, Служителям Земли, срочно нужна помощь в деле крайней важности.$B$BОбратись к Нараату Говорящему с Землей в Восточном Святилище Земли в Штормграде. Он расскажет тебе, чем ты можешь помочь.','Поговорите с Нараатом Говорящим с Землей в Восточном Святилище Земли в Штормграде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Битва выиграна, но война продолжается',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы смогли выстоять и разгромить врага, $n! Однако Хиджал – не единственное место, где нам угрожает противник.$B$BМне доложили, что нашим союзникам, Служителям Земли, срочно нужна помощь в деле крайней важности.$B$BОбратись к Нараату Говорящему с Землей в Восточном Святилище Земли в Штормграде. Он расскажет тебе, чем ты можешь помочь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Нараатом Говорящим с Землей в Восточном Святилище Земли в Штормграде.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27399,'Битва выиграна, но война продолжается','Мы смогли выстоять и разгромить врага, $n! Однако Хиджал – не единственное место, где нам угрожает противник.$B$BМне доложили, что нашим союзникам, Служителям Земли, срочно нужна помощь в деле крайней важности.$B$BОбратись к предсказателю Крогару в Западном святилище Земли в Оргриммаре. Он расскажет тебе, чем ты можешь помочь.','Поговорите с предсказателем Крогаром в Западном Святилище Земли в Оргриммаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Битва выиграна, но война продолжается',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы смогли выстоять и разгромить врага, $n! Однако Хиджал – не единственное место, где нам угрожает противник.$B$BМне доложили, что нашим союзникам, Служителям Земли, срочно нужна помощь в деле крайней важности.$B$BОбратись к предсказателю Крогару в Западном святилище Земли в Оргриммаре. Он расскажет тебе, чем ты можешь помочь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с предсказателем Крогаром в Западном Святилище Земли в Оргриммаре.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27400,'Постижение тайной магии','Все твои наставники считают, что ты поразительно $gталантлив:талантлива; для $gпутешественника:путешественницы;, $n. Рассказы о твоих успехах дошли до самого вождя.$B$BЧтобы поощрить тебя за успехи, вождь приказал своему чаротворцу изготовить тебе специальный посох.$B$BНо прежде нужно собрать материалы для этого оружия, а найти их можно только в проклятой крепости Темного Клыка, что в Серебряном бору. Отправляйся туда и добудь магическое наследие семьи Сильверлейнов, осененное луной дерево и сущности духов, обитающих в крепости.','Отправляйтесь в крепость Темного Клыка и добудьте зачарованный кристалл Сильверлейна у барона Сильверлейна, 5 вязанок осененного луной дерева и 5 призрачных субстанций.','Поговорите с Годаном в квартале Волока в Оргриммаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Постижение тайной магии',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Все твои наставники считают, что ты поразительно $gталантлив:талантлива; для $gпутешественника:путешественницы;, $n. Рассказы о твоих успехах дошли до самого вождя.$B$BЧтобы поощрить тебя за успехи, вождь приказал своему чаротворцу изготовить тебе специальный посох.$B$BНо прежде нужно собрать материалы для этого оружия, а найти их можно только в проклятой крепости Темного Клыка, что в Серебряном бору. Отправляйся туда и добудь магическое наследие семьи Сильверлейнов, осененное луной дерево и сущности духов, обитающих в крепости.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в крепость Темного Клыка и добудьте зачарованный кристалл Сильверлейна у барона Сильверлейна, 5 вязанок осененного луной дерева и 5 призрачных субстанций.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Годаном в квартале Волока в Оргриммаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (27401,'Что день грядущий нам готовит','<ПУО жужжит.>$B$BОсмотрись в Соборном квартале. Там где-то должна быть подзорная труба, она служит 7-ому легиону для наблюдения за врагом. Найди ее и обследуй гавань. Необходимо выяснить, как 7-й легион проскользнул мимо нашего флота.$B$BТоропись, $n! Мы не сможем долго удерживать этих тварей.$B$BЧто будет завтра – неведомо.','Осмотрите гавань при помощи подзорной трубы 7-го легиона.','Поговорите с командиром передовой Штурмом в передовом отряде Отрекшихся в руинах Гилнеаса.','Обыщите окрестности и найдите подзорную трубу 7-го легиона.','Командир передовой Штурм','Нас торпедировали!','Командир передовой Штурм') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Что день грядущий нам готовит',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<ПУО жужжит.>$B$BОсмотрись в Соборном квартале. Там где-то должна быть подзорная труба, она служит 7-ому легиону для наблюдения за врагом. Найди ее и обследуй гавань. Необходимо выяснить, как 7-й легион проскользнул мимо нашего флота.$B$BТоропись, $n! Мы не сможем долго удерживать этих тварей.$B$BЧто будет завтра – неведомо.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Осмотрите гавань при помощи подзорной трубы 7-го легиона.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с командиром передовой Штурмом в передовом отряде Отрекшихся в руинах Гилнеаса.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Обыщите окрестности и найдите подзорную трубу 7-го легиона.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Командир передовой Штурм',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Нас торпедировали!',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Командир передовой Штурм',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27402,'Знак силы','Твое мастерство в овладении нашим искусством быстро растет, $n, и не только меня впечатляют твои успехи. Даже Вождь обратил внимание на твои подвиги.$B$BВ награду за целеустремленность он приказал своему личному зачаровывателю сделать тебе посох.$B$BПроклятая Крепость Темного Клыка в Серебряном бору – единственное место, где ты можешь добыть необходимые для этого материалы. Отправляйся туда и принеси зловещее око, которым владеет лорд Годфри, книгу Потерянных Душ и сущность призраков, населяющих крепость.','Отправляйтесь к крепость Темного Клыка и добудьте у лорда Годфри зловещее око, а также книгу Потерянных Душ и 5 призрачных субстанций.','Значит, ты и есть тот чернокнижник, что получит это посох. Это будет достойная награда за целеустремленность. Ты обретешь великую силу и займешь высокое положение в Орде.','Ты добыл все материалы, необходимые мне для создания твоего оружия?','Поговорите с Годаном в квартале Волока в Оргриммаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Знак силы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Твое мастерство в овладении нашим искусством быстро растет, $n, и не только меня впечатляют твои успехи. Даже Вождь обратил внимание на твои подвиги.$B$BВ награду за целеустремленность он приказал своему личному зачаровывателю сделать тебе посох.$B$BПроклятая Крепость Темного Клыка в Серебряном бору – единственное место, где ты можешь добыть необходимые для этого материалы. Отправляйся туда и принеси зловещее око, которым владеет лорд Годфри, книгу Потерянных Душ и сущность призраков, населяющих крепость.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь к крепость Темного Клыка и добудьте у лорда Годфри зловещее око, а также книгу Потерянных Душ и 5 призрачных субстанций.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Значит, ты и есть тот чернокнижник, что получит это посох. Это будет достойная награда за целеустремленность. Ты обретешь великую силу и займешь высокое положение в Орде.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты добыл все материалы, необходимые мне для создания твоего оружия?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Годаном в квартале Волока в Оргриммаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`objectives_loc8`,`completedtext_loc8`) VALUES (27403,'Отправляйтесь в крепость Темного Клыка и добудьте святой символ командира Спрингвейла, 5 ящиков слитков лунной стали и 5 жил нежити.','Поговорите с Сару Холодной Яростью на Аллее Чести в Оргриммаре.') ON DUPLICATE KEY UPDATE `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в крепость Темного Клыка и добудьте святой символ командира Спрингвейла, 5 ящиков слитков лунной стали и 5 жил нежити.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Сару Холодной Яростью на Аллее Чести в Оргриммаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27404,'Будущее Круга','Друиды Круга Кенария довольны твоими достижениями, $n. Ты $gзаслужил:заслужила; наше уважение. В тебе и твоих соратниках мы видим будущее нашего братства.$B$BВ награду за твои труды мы решили смастерить тебе уникальный посох.$B$BДля него нужны очень редкие материалы, найти которые можно только в крепости Темного Клыка, что в Серебряном бору. Отправляйся туда и добудь эликсиры лорда Вальдена, осененное луной дерево и жилы вурдалаков и упырей, поселившихся в крепости.','Отправляйтесь в крепость Темного Клыка и добудьте эликсиры Вальдена, 5 вязанок осененного луной дерева и 5 жил нежити.','Поговорите с Нарианной в Ночной Гавани на Лунной поляне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Будущее Круга',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Друиды Круга Кенария довольны твоими достижениями, $n. Ты $gзаслужил:заслужила; наше уважение. В тебе и твоих соратниках мы видим будущее нашего братства.$B$BВ награду за твои труды мы решили смастерить тебе уникальный посох.$B$BДля него нужны очень редкие материалы, найти которые можно только в крепости Темного Клыка, что в Серебряном бору. Отправляйся туда и добудь эликсиры лорда Вальдена, осененное луной дерево и жилы вурдалаков и упырей, поселившихся в крепости.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в крепость Темного Клыка и добудьте эликсиры Вальдена, 5 вязанок осененного луной дерева и 5 жил нежити.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Нарианной в Ночной Гавани на Лунной поляне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27405,'Назад!','Это моя последняя передача.','Командир передовой Штурм') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Назад!',`title_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Это моя последняя передача.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Командир передовой Штурм',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27406,'Человек по имени Годфри','Лорд Винсент Годфри всю свою жизнь защищал королевство Гилнеас. Когда проклятье воргенов прокатилось по этим землям, Годфри одним из первых взялся за оружие. Говорят, узнав о том, что его короля поразило проклятье, Годфри покончил с собой. Он предпочел умереть, чем служить тем созданиям, с которыми сражался, защищая свой дом.$B$BМы дадим ему второй шанс, $n. Вместе мы попробуем прорваться к его останкам – на юго-восток, в сторону Предела Бури.','Найдите останки лорда Винсента Годфри.','Поговорите с командиром ловчих смерти Бельмонтом в руинах Гилнеаса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Человек по имени Годфри',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Лорд Винсент Годфри всю свою жизнь защищал королевство Гилнеас. Когда проклятье воргенов прокатилось по этим землям, Годфри одним из первых взялся за оружие. Говорят, узнав о том, что его короля поразило проклятье, Годфри покончил с собой. Он предпочел умереть, чем служить тем созданиям, с которыми сражался, защищая свой дом.$B$BМы дадим ему второй шанс, $n. Вместе мы попробуем прорваться к его останкам – на юго-восток, в сторону Предела Бури.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите останки лорда Винсента Годфри.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с командиром ловчих смерти Бельмонтом в руинах Гилнеаса.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27407,'Перья Кровавой Топи','Твоя что, Брогг испугался, крошка |3-6($r)? Не боись. Гоблины Шестермути Броггу друзья, и твоя может быть друг.$B$BБрогг ушел из Гиблотопи, когда наша новый властитель не стал делать мстю черным драконам за то, что они сломали наш старый дом и убили много друзей Брогга. Брогг сюда пришел упокоить души друзей и отомстить, но Броггу надо помогать подготовиться. Для ритуала Броггу надо перья с сильной магией, как у ящеров логова Кровавой Топи на западе от города.','Добудьте 5 перьев Кровавой Топи у ящеров Кровавой Топи.','<Брогг берет перья.>$B$BБрогг довольный этими перьями. Очень сильная магия. Брогг не знает, что делать ящеры, чтобы перья были сильные, но перья ящеров всегда лучшие для ритуала.','<Брогг с надеждой смотрит на вас.>$B$BТвоя приносить Броггу перья?','Вернитесь к Броггу в Шестермуть в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Перья Кровавой Топи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Твоя что, Брогг испугался, крошка |3-6($r)? Не боись. Гоблины Шестермути Броггу друзья, и твоя может быть друг.$B$BБрогг ушел из Гиблотопи, когда наша новый властитель не стал делать мстю черным драконам за то, что они сломали наш старый дом и убили много друзей Брогга. Брогг сюда пришел упокоить души друзей и отомстить, но Броггу надо помогать подготовиться. Для ритуала Броггу надо перья с сильной магией, как у ящеров логова Кровавой Топи на западе от города.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 5 перьев Кровавой Топи у ящеров Кровавой Топи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Брогг берет перья.>$B$BБрогг довольный этими перьями. Очень сильная магия. Брогг не знает, что делать ящеры, чтобы перья были сильные, но перья ящеров всегда лучшие для ритуала.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Брогг с надеждой смотрит на вас.>$B$BТвоя приносить Броггу перья?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Броггу в Шестермуть в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27408,'Знамя Каменного Молота','Когда пришли драконы и отобрали у Брогга его старый дом, огры Каменного Молота бежали, побросав все, даже знамя нашего клана.$B$BБрогг знает, что знамя прятали в деревне Каменного Молота, но теперь она называется Огненное логово. Броггу нужно знамя его клана, чтобы отомстить драконам, которые убили его друзей.$B$BДеревня старого клана Брогга, то есть Огненное логово, находится к северо-западу от Шестермути, и там полно драконов. Знамя глубоко в пещере. Осторожней там, $n.','Принесите из Огненного логова знамя Каменного Молота.','Принесла знамя Каменного Молота?','Вернитесь к Броггу в Шестермуть в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Знамя Каменного Молота',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда пришли драконы и отобрали у Брогга его старый дом, огры Каменного Молота бежали, побросав все, даже знамя нашего клана.$B$BБрогг знает, что знамя прятали в деревне Каменного Молота, но теперь она называется Огненное логово. Броггу нужно знамя его клана, чтобы отомстить драконам, которые убили его друзей.$B$BДеревня старого клана Брогга, то есть Огненное логово, находится к северо-западу от Шестермути, и там полно драконов. Знамя глубоко в пещере. Осторожней там, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите из Огненного логова знамя Каменного Молота.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Принесла знамя Каменного Молота?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Броггу в Шестермуть в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27409,'Сущность вражды','Чтобы сделать тотем для своего ритуала, Броггу понадобятся сущности тех, кто убил его друзей. Ненависть и ярость врагов Брогга придаст мстительной магии еще больше сил.$B$BВыследи огнегривых пеплохвостов, разведчиков или чешуйчатых губителей и поставь тотем Брогга рядом с их телами. Драконы отдают свои сущности только когда умирают.$B$BЛучше всего искать их в Огненном логове на северо-западе или в руинах деревни Каменного Молота на севере.','Принесите 10 сущностей черного дракона Броггу в Шестермуть.','Принесла сущности? Они нужны Броггу, чтобы отомстить за друзей!','Вернитесь к Броггу в Шестермуть в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сущность вражды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чтобы сделать тотем для своего ритуала, Броггу понадобятся сущности тех, кто убил его друзей. Ненависть и ярость врагов Брогга придаст мстительной магии еще больше сил.$B$BВыследи огнегривых пеплохвостов, разведчиков или чешуйчатых губителей и поставь тотем Брогга рядом с их телами. Драконы отдают свои сущности только когда умирают.$B$BЛучше всего искать их в Огненном логове на северо-западе или в руинах деревни Каменного Молота на севере.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 сущностей черного дракона Броггу в Шестермуть.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Принесла сущности? Они нужны Броггу, чтобы отомстить за друзей!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Броггу в Шестермуть в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27410,'Духи в руинах деревни Каменного Молота','Брогг закончил мастерить тотем, который поможет душам его друзей обрести покой. Когда драконоры напали на деревню Каменного Молота, они убили всех, кто не спасся бегством. Брогг бежал вместе с владыкой Мок\'Морокком, надеясь повести выживших жителей деревни в контратаку.$B$BДо этого дело так и не дошло, а души убитых с тех пор не дают Броггу и всем остальным покоя. Отнеси этот тотем на север, в руины деревни Каменного Молота, и установи там рядом со скелетами огров, чтобы привлечь духов. Побежденный в бою дух сможет наконец упокоиться с миром.','Упокойте 10 духов Каменного Молота в руинах деревни Каменного Молота.','Брогг должен знать, принес ли ты покой свирепым духам Каменного Молота?','Вернитесь к Броггу в Шестермуть в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Духи в руинах деревни Каменного Молота',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Брогг закончил мастерить тотем, который поможет душам его друзей обрести покой. Когда драконоры напали на деревню Каменного Молота, они убили всех, кто не спасся бегством. Брогг бежал вместе с владыкой Мок\'Морокком, надеясь повести выживших жителей деревни в контратаку.$B$BДо этого дело так и не дошло, а души убитых с тех пор не дают Броггу и всем остальным покоя. Отнеси этот тотем на север, в руины деревни Каменного Молота, и установи там рядом со скелетами огров, чтобы привлечь духов. Побежденный в бою дух сможет наконец упокоиться с миром.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Упокойте 10 духов Каменного Молота в руинах деревни Каменного Молота.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Брогг должен знать, принес ли ты покой свирепым духам Каменного Молота?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Броггу в Шестермуть в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27411,'Брогга греет мысль о том, как он будет мстить драконьему отродью из топей. $n, час возмездия пробил! До сих пор ты хорошо со всем $gсправлялся:справлялась;. А сейчас поможешь?$B$BВозьми знамя клана Брогга и иди на восток, пока не увидишь пещеру, похожую на драконью пасть. Водрузи знамя у входа – так ты объявишь Ониксии, что Брогг вызывает ее на бой.$B$BБрогг и клан Каменного Молота вернут себе свою землю!','Установите знамя Каменного Молота у входа в логово Ониксии и одолейте всех, кто примет этот вызов.','Брогг свершит свою месть!','Вернитесь к Броггу в Шестермуть в Пылевых топях.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Брогга греет мысль о том, как он будет мстить драконьему отродью из топей. $n, час возмездия пробил! До сих пор ты хорошо со всем $gсправлялся:справлялась;. А сейчас поможешь?$B$BВозьми знамя клана Брогга и иди на восток, пока не увидишь пещеру, похожую на драконью пасть. Водрузи знамя у входа – так ты объявишь Ониксии, что Брогг вызывает ее на бой.$B$BБрогг и клан Каменного Молота вернут себе свою землю!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Установите знамя Каменного Молота у входа в логово Ониксии и одолейте всех, кто примет этот вызов.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Брогг свершит свою месть!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Броггу в Шестермуть в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27412,'РАЗЫСКИВАЕТСЯ: Кровокоготь Ненасытный','Путешественникам и персоналу Хитрой Шестеренки, работающему в поле, рекомендуется держаться подальше от логова Кровавой Топи, что к западу от города.$B$BМестность кишит ящерами, а верховодит ими очень злой и хитрый Кровокоготь Ненасытный – он уже убил по меньшей мере двух инженеров Хитрой Шестеренки.$B$BДраззит Кранотек назначил щедрое вознаграждение тому, кто избавит Шестермуть от этой напасти.','Уничтожьте Кровокогтя Ненасытного и сообщите об этом Драззиту Кранотеку, который находится в Шестермути.','Хвала небесам, наконец кто-то откликнулся на это объявление! Я уж думал, что придется утроить награду за голову этого дурацкого ящера, а наш бюджет такого не потянет!','Вернитесь к Драззиту Кранотеку в Шестермуть в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','РАЗЫСКИВАЕТСЯ: Кровокоготь Ненасытный',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Путешественникам и персоналу Хитрой Шестеренки, работающему в поле, рекомендуется держаться подальше от логова Кровавой Топи, что к западу от города.$B$BМестность кишит ящерами, а верховодит ими очень злой и хитрый Кровокоготь Ненасытный – он уже убил по меньшей мере двух инженеров Хитрой Шестеренки.$B$BДраззит Кранотек назначил щедрое вознаграждение тому, кто избавит Шестермуть от этой напасти.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте Кровокогтя Ненасытного и сообщите об этом Драззиту Кранотеку, который находится в Шестермути.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хвала небесам, наконец кто-то откликнулся на это объявление! Я уж думал, что придется утроить награду за голову этого дурацкого ящера, а наш бюджет такого не потянет!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Драззиту Кранотеку в Шестермуть в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27413,'Тяни змею за хвост!','Поскольку дирижабль разбился, поставка задерживается, и мы остались без медикаментов и бинтов.$B$BКонечно, выручают подручные средства, но среди всех этих насекомых, отбиваясь от врагов и неся потери, мы вряд ли долго продержимся! Я нашел тут одну травку, которая, сдается, помогает при лечении любых ран и притупляет боль, но и ее мало.$B$BОна называется змейкин хвост, в Земле Драконов и Драконьих топях к востоку от города ее целые заросли. Сами растения представляют собой свившиеся кольцами стебли. Когда смотришь на них, кажется, будто они пульсируют.','Соберите в Земле Драконов или в Драконьих топях 8 стеблей змейкиного хвоста.','Спасибо тебе! Теперь наши парни продержатся в поле, пока Мокси не доставит груз, оставшийся после крушения дирижабля.','Вернитесь к Гиззиксу Грязебульку в Шестермуть в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тяни змею за хвост!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Поскольку дирижабль разбился, поставка задерживается, и мы остались без медикаментов и бинтов.$B$BКонечно, выручают подручные средства, но среди всех этих насекомых, отбиваясь от врагов и неся потери, мы вряд ли долго продержимся! Я нашел тут одну травку, которая, сдается, помогает при лечении любых ран и притупляет боль, но и ее мало.$B$BОна называется змейкин хвост, в Земле Драконов и Драконьих топях к востоку от города ее целые заросли. Сами растения представляют собой свившиеся кольцами стебли. Когда смотришь на них, кажется, будто они пульсируют.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите в Земле Драконов или в Драконьих топях 8 стеблей змейкиного хвоста.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо тебе! Теперь наши парни продержатся в поле, пока Мокси не доставит груз, оставшийся после крушения дирижабля.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гиззиксу Грязебульку в Шестермуть в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27414,'Поиск источника','Пока этот трусливый глупец Мок\'Морокк упивается положением, а Тарг борется с тоской и жаждой мести и оспаривает его власть над кланом, я, кажется, единственный, кто хочет установить источник обрушившихся на нас бед.$B$BПочему ты так озадаченно на меня смотришь, $n? $GДумал:Думала;, я буду говорить как неотесанный чурбан только потому, что я – огр?$B$BНо к делу. Принеси мне сердца и языки дракончиков, только что вылупившихся из яиц, и я найду корни этого зла.','Принесите Драз\'Зилбу в деревню Гиблотопь 7 огненных языков и 7 пылающих сердец.','Рискованно было добывать все эти сердца и языки, а? Теперь я проникну в глубины тайн и выясню, откуда на наш прежний дом свалилась такая напасть.','Теперь я смогу выяснить, что за тварь напустила на нас свои отродья. Возможно, зная больше о захватчике, мы поймем, как уничтожить его раз и навсегда и поднять деревню Каменного Молота из руин.$B$BКонечно, заставить Мок\'Морокка оторвать свой толстый зад от земли – уже само по себе героический поступок...','Вернитесь к Драз\'Зилбу в деревню Гиблотопь в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поиск источника',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пока этот трусливый глупец Мок\'Морокк упивается положением, а Тарг борется с тоской и жаждой мести и оспаривает его власть над кланом, я, кажется, единственный, кто хочет установить источник обрушившихся на нас бед.$B$BПочему ты так озадаченно на меня смотришь, $n? $GДумал:Думала;, я буду говорить как неотесанный чурбан только потому, что я – огр?$B$BНо к делу. Принеси мне сердца и языки дракончиков, только что вылупившихся из яиц, и я найду корни этого зла.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Драз\'Зилбу в деревню Гиблотопь 7 огненных языков и 7 пылающих сердец.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Рискованно было добывать все эти сердца и языки, а? Теперь я проникну в глубины тайн и выясню, откуда на наш прежний дом свалилась такая напасть.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Теперь я смогу выяснить, что за тварь напустила на нас свои отродья. Возможно, зная больше о захватчике, мы поймем, как уничтожить его раз и навсегда и поднять деревню Каменного Молота из руин.$B$BКонечно, заставить Мок\'Морокка оторвать свой толстый зад от земли – уже само по себе героический поступок...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Драз\'Зилбу в деревню Гиблотопь в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27415,'Выводок Ониксии','Детеныши Ониксии заполонили всю Землю Драконов. Нельзя допустить, чтобы их вылупилось еще больше.$B$BПоскорее отправляйся в Драконьи топи – это на юге Пылевых топей, наверняка логово дракона где-то там. Найди яйца и перебей.$B$BЕсли эти рептилии будут так плодиться, и думать нечего о том, чтобы отвоевать деревню Каменного Молота.$B$BА что до Мок\'Морокка... На этого идиота у меня другие планы.','Разбейте 5 яиц Ониксии.','Вернитесь к Драз\'Зилбу в деревню Гиблотопь в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Выводок Ониксии',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Детеныши Ониксии заполонили всю Землю Драконов. Нельзя допустить, чтобы их вылупилось еще больше.$B$BПоскорее отправляйся в Драконьи топи – это на юге Пылевых топей, наверняка логово дракона где-то там. Найди яйца и перебей.$B$BЕсли эти рептилии будут так плодиться, и думать нечего о том, чтобы отвоевать деревню Каменного Молота.$B$BА что до Мок\'Морокка... На этого идиота у меня другие планы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разбейте 5 яиц Ониксии.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Драз\'Зилбу в деревню Гиблотопь в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27416,'Выводок Ониксии','Поговорите с властителем Мок\'Морокком в деревне Гиблотопь.','Зачем ты говорить про драконы? Моя драконы не любить. Здесь – хорошо. Здесь драконы не водиться.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Выводок Ониксии',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с властителем Мок\'Морокком в деревне Гиблотопь.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Зачем ты говорить про драконы? Моя драконы не любить. Здесь – хорошо. Здесь драконы не водиться.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27417,'Выводок Ониксии','Оставь меня в покое. Иди и скажи Драз\'Зилбу, что мы остаемся здесь. Тут нет никакого черного дракона.','Поговорите с Драз\'Зилбом в деревне Гиблотопь.','Жалкий трус!$B$BМок\'Морокк сверг нашего вождя Рексара. Но после его ухода Мок\'Морокк сам стал жертвой неограниченной власти. Вместо того чтобы руководить, стал только потреблять. Он не служит своему народу – хочет, чтобы служили ему.$B$BС этим надо что-то делать!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Выводок Ониксии',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Оставь меня в покое. Иди и скажи Драз\'Зилбу, что мы остаемся здесь. Тут нет никакого черного дракона.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Драз\'Зилбом в деревне Гиблотопь.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Жалкий трус!$B$BМок\'Морокк сверг нашего вождя Рексара. Но после его ухода Мок\'Морокк сам стал жертвой неограниченной власти. Вместо того чтобы руководить, стал только потреблять. Он не служит своему народу – хочет, чтобы служили ему.$B$BС этим надо что-то делать!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27419,'Армия черных драконов','Рексар сделал Мок\'Морокка властителем. Но власть ему милее огров.$B$BЧерные драконы убили много огров. Убили жену Тхарга. Мок\'Морокк велел бежать. Заставил прийти сюда.$B$BНо ограм надо сражаться. Огры не умеют бегать. А Мок\'Морокк думает только о Мок\'Морокке.$B$BРуины деревни Каменного Молота – мой дом. Я люблю жить там, на юге. Это место – не дом.$B$BПомоги ограм биться с армией черных драконов. Я хочу отомстить. Я хочу вернуться домой.','Тхарг из деревни Гиблотопь хочет, чтобы вы уничтожили 10 огнегривых разведчиков, 10 огнегривых пеплохвостов и 5 огнегривых чешуйчатых губителей.','Вернитесь к Таргу в деревню Гиблотопь в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Армия черных драконов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Рексар сделал Мок\'Морокка властителем. Но власть ему милее огров.$B$BЧерные драконы убили много огров. Убили жену Тхарга. Мок\'Морокк велел бежать. Заставил прийти сюда.$B$BНо ограм надо сражаться. Огры не умеют бегать. А Мок\'Морокк думает только о Мок\'Морокке.$B$BРуины деревни Каменного Молота – мой дом. Я люблю жить там, на юге. Это место – не дом.$B$BПомоги ограм биться с армией черных драконов. Я хочу отомстить. Я хочу вернуться домой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Тхарг из деревни Гиблотопь хочет, чтобы вы уничтожили 10 огнегривых разведчиков, 10 огнегривых пеплохвостов и 5 огнегривых чешуйчатых губителей.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Таргу в деревню Гиблотопь в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27420,'Отсрочка неизбежного','У тебя очень острое зрение, раз тебе удалось разглядеть меня в траве.$B$BПеред нами простирается Грибная долина, с ней тесно связана деятельность Плети. С помощью специальных сооружений они постоянно заражают эти земли.$B$BСами сооружения управляются при помощи рун, которые хранятся у темных адептов и темных магов. Забери у этих сектантов руны управления, направь их на разносчиков чумы и перезаряди этой частицей. Должно выйти нечто потрясающее.','Добудьте у темных адептов и темных магов руны управления, а затем с помощью избыточно заряженной частицы уничтожьте 3 разносчиков чумы.','Вернитесь к Райне. Она ждет у входа в Грибную долину в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отсрочка неизбежного',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У тебя очень острое зрение, раз тебе удалось разглядеть меня в траве.$B$BПеред нами простирается Грибная долина, с ней тесно связана деятельность Плети. С помощью специальных сооружений они постоянно заражают эти земли.$B$BСами сооружения управляются при помощи рун, которые хранятся у темных адептов и темных магов. Забери у этих сектантов руны управления, направь их на разносчиков чумы и перезаряди этой частицей. Должно выйти нечто потрясающее.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте у темных адептов и темных магов руны управления, а затем с помощью избыточно заряженной частицы уничтожьте 3 разносчиков чумы.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Райне. Она ждет у входа в Грибную долину в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27421,'Жизнь среди смерти','Воины Плети сделали все, чтобы Грибная долина превратилась в безжизненную пустыню – теперь на ее просторах встречаются лишь сгнившие грибы и выжженная трава. В каждом из трех окончаний долины находится по зиккурату – там ряды солдат Плети пополняются ожившими мертвецами.$B$BНо даже в этом оплоте зла может зародиться жизнь! Возьми эти семена и посади их в самом центре каждого зиккурата. Докажи им, что жизнь не победить.','Посадите семена Райны в центре каждого из трех зиккуратов Грибной долины.','Пусть наши цветы быстро увяли, но мы доказали Плети, что победа будет за нами.$B$BСпасибо за помощь.','Вернитесь к Райне. Она ждет у входа в Грибную долину в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жизнь среди смерти',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Воины Плети сделали все, чтобы Грибная долина превратилась в безжизненную пустыню – теперь на ее просторах встречаются лишь сгнившие грибы и выжженная трава. В каждом из трех окончаний долины находится по зиккурату – там ряды солдат Плети пополняются ожившими мертвецами.$B$BНо даже в этом оплоте зла может зародиться жизнь! Возьми эти семена и посади их в самом центре каждого зиккурата. Докажи им, что жизнь не победить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Посадите семена Райны в центре каждого из трех зиккуратов Грибной долины.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Пусть наши цветы быстро увяли, но мы доказали Плети, что победа будет за нами.$B$BСпасибо за помощь.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Райне. Она ждет у входа в Грибную долину в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27422,'Осажденный город','Нам не удержать Восточные Чумные земли, пока мы не займем Стратхольм. Этот город не только ключевой стратегический объект, но и оплот вражеских генералов – Бальназара и лорда Ривендера. Армии Восставших и Плети угрожают всему, чего мы с таким трудом добились.$B$BСеребряный Авангард послужит нам отличным подспорьем. Следуй на запад через главные ворота Стратхольма и поговори с караванщиком Камнетесом. Он скажет, что делать дальше.','Поговорите с караванщиком Камнетесом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Осажденный город',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нам не удержать Восточные Чумные земли, пока мы не займем Стратхольм. Этот город не только ключевой стратегический объект, но и оплот вражеских генералов – Бальназара и лорда Ривендера. Армии Восставших и Плети угрожают всему, чего мы с таким трудом добились.$B$BСеребряный Авангард послужит нам отличным подспорьем. Следуй на запад через главные ворота Стратхольма и поговори с караванщиком Камнетесом. Он скажет, что делать дальше.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с караванщиком Камнетесом.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`) VALUES (27423,'Сопротивление бесполезно','Уничтожьте 20 боевых воргенов.','Поговорите с командиром ловчих смерти Бельмонтом в руинах Гилнеаса.','Дочь лорда Дария Краули.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сопротивление бесполезно',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 20 боевых воргенов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с командиром ловчих смерти Бельмонтом в руинах Гилнеаса.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Дочь лорда Дария Краули.',`questgivertextwindow_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27424,'Склонись перед владыка Мок\'Морокк!$B$BРексар сделать моя вождь клана Каменный Молот!$B$BМоя хороший вождь. Моя клан беречь.$B$BБольшие драконы старый дом спалить. Моя умный огр. Здесь новый дом для клан находить.$B$BНо когда мы с того места бежать, я забыть кой-чего. Кроха |3-6($r), твоя мои вещи собери. Твоя иди на юг и тащи сюда мой ням-ням грог, понюшку табаку, сундук. Моя твоя после этого любить как родной. Твоя смотри в Огненное логово и в руины деревни Каменный Молот... Там они лежать, моя уверен!','Моя жажда мучить, хотеть грог страшно. И понюшку табак хотеть. А где сундук? Твоя давай тащи сюда все.$B$BИди на юг, смотри в старый дом. А моя слишком занят сейчас, моя ограми повелевать надо.','Вернитесь к владыке Мок\'Морокку в деревню Гиблотопь в Пылевых топях.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Склонись перед владыка Мок\'Морокк!$B$BРексар сделать моя вождь клана Каменный Молот!$B$BМоя хороший вождь. Моя клан беречь.$B$BБольшие драконы старый дом спалить. Моя умный огр. Здесь новый дом для клан находить.$B$BНо когда мы с того места бежать, я забыть кой-чего. Кроха |3-6($r), твоя мои вещи собери. Твоя иди на юг и тащи сюда мой ням-ням грог, понюшку табаку, сундук. Моя твоя после этого любить как родной. Твоя смотри в Огненное логово и в руины деревни Каменный Молот... Там они лежать, моя уверен!',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Моя жажда мучить, хотеть грог страшно. И понюшку табак хотеть. А где сундук? Твоя давай тащи сюда все.$B$BИди на юг, смотри в старый дом. А моя слишком занят сейчас, моя ограми повелевать надо.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к владыке Мок\'Морокку в деревню Гиблотопь в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27425,'Мрачные выводы','Доложитесь капитану Дариллу в Северной башне.','Капитан Ваймс считает, что клан Зловещего Тотема повинен в преступлении, совершенном в таверне "Последний привал"? Я бы не ставил его первым в списке подозреваемых, но раз капитан Ваймс прислал тебя для дальнейшего расследования, должно быть, у него были на то причины. В любом случае, клан Зловещего Тотема давно у нас как заноза в пятке, и мы всегда рады принять любую помощь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мрачные выводы',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доложитесь капитану Дариллу в Северной башне.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Капитан Ваймс считает, что клан Зловещего Тотема повинен в преступлении, совершенном в таверне "Последний привал"? Я бы не ставил его первым в списке подозреваемых, но раз капитан Ваймс прислал тебя для дальнейшего расследования, должно быть, у него были на то причины. В любом случае, клан Зловещего Тотема давно у нас как заноза в пятке, и мы всегда рады принять любую помощь.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27426,'Подтвержденные подозрения','Возможно, Зловещий Тотем – самое воинственное из тауренских племен, но они весьма организованы. Если это они подожгли "Последний привал", значит, действовали по приказу одного из своих старейшин.$B$BБольшое селение племени – деревня Черного Копыта – находится на северо-западе отсюда. Там и была база для нападений на башню. Могу поклясться – в деревне ты найдешь те самые приказы, которые тебе нужны. Поищи их у старейшин.','<Капитан Дарилл просматривает боевой план.>$B$BЯ бы сказал, что все яснее ясного. Они берут на себя уничтожение людских поселений в этих краях, и я не сомневаюсь, что следующим в списке будет Терамор.','Удалось найти какие-нибудь следы приказов?','Вернитесь к капитану Дариллу в Северную башню в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подтвержденные подозрения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Возможно, Зловещий Тотем – самое воинственное из тауренских племен, но они весьма организованы. Если это они подожгли "Последний привал", значит, действовали по приказу одного из своих старейшин.$B$BБольшое селение племени – деревня Черного Копыта – находится на северо-западе отсюда. Там и была база для нападений на башню. Могу поклясться – в деревне ты найдешь те самые приказы, которые тебе нужны. Поищи их у старейшин.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Капитан Дарилл просматривает боевой план.>$B$BЯ бы сказал, что все яснее ясного. Они берут на себя уничтожение людских поселений в этих краях, и я не сомневаюсь, что следующим в списке будет Терамор.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось найти какие-нибудь следы приказов?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Дариллу в Северную башню в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27427,'Оружие клана Зловещего Тотема','По просьбе капитана Дарилла из Северной башни принесите ему 7 предметов вооружения из деревни Черного Копыта.','<Капитан Дарилл осматривает принесенное вами из деревни Черного Копыта вооружение.>$B$BСомневаться не приходится – вооружение в точности соответствует описанию. Но дело в том, что оно ни разу не побывало в бою. Должно быть, деревня Черного Копыта – не единственный аванпост Зловещего Тотема в Топях.','Ты принесла вооружение из деревни Черного Копыта?','Вернитесь к капитану Дариллу в Северную башню в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оружие клана Зловещего Тотема',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По просьбе капитана Дарилла из Северной башни принесите ему 7 предметов вооружения из деревни Черного Копыта.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Капитан Дарилл осматривает принесенное вами из деревни Черного Копыта вооружение.>$B$BСомневаться не приходится – вооружение в точности соответствует описанию. Но дело в том, что оно ни разу не побывало в бою. Должно быть, деревня Черного Копыта – не единственный аванпост Зловещего Тотема в Топях.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты принесла вооружение из деревни Черного Копыта?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Дариллу в Северную башню в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27428,'Помощь Табеты','Поговорите с Табетой в ее доме.','Значит, ты хочешь, чтобы я предсказала будущее клана Зловещий Тотем? А если скажу, что нужды в том нет?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Помощь Табеты',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Табетой в ее доме.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Значит, ты хочешь, чтобы я предсказала будущее клана Зловещий Тотем? А если скажу, что нужды в том нет?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27429,'Уничтожение заставы Дикого Рога','От этих новых "соседей" одни неприятности. А если это, как ты говоришь, та самая банда, что сожгла таверну "Последний привал", тогда нужно скорее избавляться от такого "соседства".$B$BВозьми факел и сожги их лагерь! Застава Дикого Рога стоит близ дороги, к северу от моей фермы. Ты его не пропустишь, сразу увидишь. Таурены из Зловещего Тотема постарались, чтобы все знали об их присутствии – понатыкали всюду свои тотемы, их только слепой не заметит!','Факелом Табеты подожгите северный, восточный и северо-восточный шатры на заставе Дикого Рога.','Надеюсь, клан Зловещего Тотема усвоил урок. Попытаются вернуться – мы их встретим не только факелом. Мои ученики помогут мне дать отпор.','Ну что, хорошо разгорелось?','Вернитесь к Табете на ферму, что в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уничтожение заставы Дикого Рога',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','От этих новых "соседей" одни неприятности. А если это, как ты говоришь, та самая банда, что сожгла таверну "Последний привал", тогда нужно скорее избавляться от такого "соседства".$B$BВозьми факел и сожги их лагерь! Застава Дикого Рога стоит близ дороги, к северу от моей фермы. Ты его не пропустишь, сразу увидишь. Таурены из Зловещего Тотема постарались, чтобы все знали об их присутствии – понатыкали всюду свои тотемы, их только слепой не заметит!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Факелом Табеты подожгите северный, восточный и северо-восточный шатры на заставе Дикого Рога.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Надеюсь, клан Зловещего Тотема усвоил урок. Попытаются вернуться – мы их встретим не только факелом. Мои ученики помогут мне дать отпор.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, хорошо разгорелось?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Табете на ферму, что в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (27430,'Справедливая месть за Хьялей','Пусть Зловещие тотемы досаждали мне немногим, но капитан Ваймс захочет послушать о твоих свершениях. Доложи ему, что тебе удалось выследить и уничтожить тех, кто спалил таверну "Последний привал".$B$BХоть это и не воскресит семью Джима Хьяля, но, может, Зловещие тотемы теперь дважды подумают, перед тем как нападать на тех, кто связан с Терамором.','<Капитан внимательно выслушивает ваш доклад.>$B$BМы отомстили за Джеймса и его семью, но это их не вернет.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Справедливая месть за Хьялей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пусть Зловещие тотемы досаждали мне немногим, но капитан Ваймс захочет послушать о твоих свершениях. Доложи ему, что тебе удалось выследить и уничтожить тех, кто спалил таверну "Последний привал".$B$BХоть это и не воскресит семью Джима Хьяля, но, может, Зловещие тотемы теперь дважды подумают, перед тем как нападать на тех, кто связан с Терамором.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Капитан внимательно выслушивает ваш доклад.>$B$BМы отомстили за Джеймса и его семью, но это их не вернет.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27431,'Чуток подтолкнуть...','<Харрисон улыбается.>$B$BЯ понял, $n! Нужные нам детали спрятаны в этих статуях!$B$BОни с виду не очень устойчивые. Может быть, если их чуточку подтолкнуть...$B$BКстати, должен заметить, ты отлично справляешься. Из тебя получился бы очень хороший археолог. Тебе бы только немножечко подучиться...','Поговорите с Харрисоном Джонсом в Зале Звезд.','Ты все же подумай о том, чтобы стать археологом. Я даже не сомневаюсь, что тебя ждет блестящее будущее!','Поговорите с Харрисоном Джонсом в Зале Звезд.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чуток подтолкнуть...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Харрисон улыбается.>$B$BЯ понял, $n! Нужные нам детали спрятаны в этих статуях!$B$BОни с виду не очень устойчивые. Может быть, если их чуточку подтолкнуть...$B$BКстати, должен заметить, ты отлично справляешься. Из тебя получился бы очень хороший археолог. Тебе бы только немножечко подучиться...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Харрисоном Джонсом в Зале Звезд.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты все же подумай о том, чтобы стать археологом. Я даже не сомневаюсь, что тебя ждет блестящее будущее!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Харрисоном Джонсом в Зале Звезд.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27432,'Зельдарр Изгой','Можешь поверить? После всех напастей, обрушившихся на Чумные земли, у нас теперь еще и воры завелись! Да причем не обычные воры, а тролли.$B$BИ не просто тролли-воры. Мертвые тролли-воры!$B$BИх вожак – здоровенный мертвый детина по имени Зельдарр Изгой. Они приходят каждую ночь, выкапывают тела из наших могил и тащат их к себе в троллье логово – Крипту. Это к юго-западу отсюда.$B$BОтправляйся туда, $n, и разберись с этим Зельдарром. Я сыт по горло его проделками!','Убейте Зельдарра Изгоя и заберите его голову.','Отлично, ты с ним расправился! Надеюсь, и банде его тоже хороший урок преподнес!','Поговорите с Урком Газбазом в Башне королевской стражи в Восточных Чумных землях.','В глубине, под Криптой, гниет изгой.','Зельдарр Изгой') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зельдарр Изгой',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Можешь поверить? После всех напастей, обрушившихся на Чумные земли, у нас теперь еще и воры завелись! Да причем не обычные воры, а тролли.$B$BИ не просто тролли-воры. Мертвые тролли-воры!$B$BИх вожак – здоровенный мертвый детина по имени Зельдарр Изгой. Они приходят каждую ночь, выкапывают тела из наших могил и тащат их к себе в троллье логово – Крипту. Это к юго-западу отсюда.$B$BОтправляйся туда, $n, и разберись с этим Зельдарром. Я сыт по горло его проделками!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Зельдарра Изгоя и заберите его голову.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, ты с ним расправился! Надеюсь, и банде его тоже хороший урок преподнес!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Урком Газбазом в Башне королевской стражи в Восточных Чумных землях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','В глубине, под Криптой, гниет изгой.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Зельдарр Изгой',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27433,'Крошшероктомия','Наши танки были вынуждены отступить, а это значит, что нас ждут ремонтные работы в полевых условиях.$B$BРазбей парочку крошшеров с алмазными лезвиями – тех, которыми эти зеленые уродцы валили деревья на берегу. Набери кучу деталей этих крошшеров и принеси мне. Тогда мы как-нибудь залатаем наши танки.','Уничтожайте крошшеры с алмазными лезвиями, чтобы собрать 5 изношенных деталей крошшера.','О да, это самое оно! Из этого хороший инженер может сделать практически все что угодно.$B$BЭтот ду-джикер можно соединить с цилиндрической гильзой... Ой! Это же донгл! Просто мечта!.. А вот этот джобби можно превратить в... нечто.$B$B<Кремневый Затвор засовывает в рот одну из деталей двигателя, покрытую толстым слоем смазки.>$B$BДа, отлично.','Доставьте детали Фарго Кремневому Затвору на Сумеречный берег на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Крошшероктомия',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наши танки были вынуждены отступить, а это значит, что нас ждут ремонтные работы в полевых условиях.$B$BРазбей парочку крошшеров с алмазными лезвиями – тех, которыми эти зеленые уродцы валили деревья на берегу. Набери кучу деталей этих крошшеров и принеси мне. Тогда мы как-нибудь залатаем наши танки.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожайте крошшеры с алмазными лезвиями, чтобы собрать 5 изношенных деталей крошшера.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О да, это самое оно! Из этого хороший инженер может сделать практически все что угодно.$B$BЭтот ду-джикер можно соединить с цилиндрической гильзой... Ой! Это же донгл! Просто мечта!.. А вот этот джобби можно превратить в... нечто.$B$B<Кремневый Затвор засовывает в рот одну из деталей двигателя, покрытую толстым слоем смазки.>$B$BДа, отлично.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доставьте детали Фарго Кремневому Затвору на Сумеречный берег на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27434,'Путь адепта','Пришло время распрощаться со званием $gученика:ученицы;, $n. Теперь тебя будут называть адептом, и ты станешь настоящим рыцарем Крови на службе Луносвета.$B$BЧтобы поощрить тебя за твои успехи, вождь приказал своему кузнецу изготовить оружие специально для тебя.$B$BНо прежде нужно собрать материалы для этого оружия, а найти их можно только в проклятой крепости Темного Клыка, что в Серебряном бору. Отправляйся туда и добудь святой символ командира Спрингвейла, слитки лунной стали и жилы вурдалаков и упырей, обитающих в крепости.','Отправляйтесь в крепость Темного Клыка и добудьте святой символ командира Спрингвейла, 5 слитков лунной стали и 5 жил нежити.','Поговорите с Сару Холодной Яростью на Аллее Чести в Оргриммаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путь адепта',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пришло время распрощаться со званием $gученика:ученицы;, $n. Теперь тебя будут называть адептом, и ты станешь настоящим рыцарем Крови на службе Луносвета.$B$BЧтобы поощрить тебя за твои успехи, вождь приказал своему кузнецу изготовить оружие специально для тебя.$B$BНо прежде нужно собрать материалы для этого оружия, а найти их можно только в проклятой крепости Темного Клыка, что в Серебряном бору. Отправляйся туда и добудь святой символ командира Спрингвейла, слитки лунной стали и жилы вурдалаков и упырей, обитающих в крепости.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в крепость Темного Клыка и добудьте святой символ командира Спрингвейла, 5 слитков лунной стали и 5 жил нежити.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Сару Холодной Яростью на Аллее Чести в Оргриммаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27435,'Посох ясновидца','Отправляйтесь в крепость Темного Клыка и добудьте святой символ командира Спрингвейла, 5 вязанок осененного луной дерева и 5 призрачных субстанций.','Поговорите с Годаном в квартале Волока в Оргриммаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Посох ясновидца',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в крепость Темного Клыка и добудьте святой символ командира Спрингвейла, 5 вязанок осененного луной дерева и 5 призрачных субстанций.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Годаном в квартале Волока в Оргриммаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`objectives_loc8`,`completedtext_loc8`) VALUES (27436,'Отправляйтесь в крепость Темного Клыка и добудьте святой символ командира Спрингвейла, 5 вязанок осененного луной дерева и 5 призрачных субстанций.','Поговорите с Годаном в квартале Волока в Оргриммаре.') ON DUPLICATE KEY UPDATE `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в крепость Темного Клыка и добудьте святой символ командира Спрингвейла, 5 вязанок осененного луной дерева и 5 призрачных субстанций.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Годаном в квартале Волока в Оргриммаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27437,'Ты $gприлежный ученик:прилежная ученица; и $gверный:верная; слуга для нас. Делай то, что велит тебе леди Сильвана, и Тень будет благосклонна к тебе.$B$BЧтобы поощрить тебя за хорошую службу, наша королева приказала своему чаротворцу в Оргриммаре изготовить оружие специально для тебя.$B$BНо прежде нужно собрать материалы для этого оружия, а найти их можно только в проклятой Крепости Темного Клыка, что в Серебряном бору. Отправляйся туда и добудь затерянный святой символ командира Спрингвейла, осененное луной дерево и сущности духов, обитающих в крепости.','Отправляйтесь в крепость Темного Клыка и добудьте святой символ командира у командира Спрингвейла, 5 вязанок осененного луной дерева и 5 образцов призрачной субстанции.','Темная жрица Сесиль сказала мне, что ты отправился за материалами для оружия в Крепость Темного Клыка. Теперь я вижу, почему: даже могущественная магия, которой окутана эта крепость, не смогла уничтожить силу, заключенную в этих предметах.','Ты раздобыл материалы для оружия?','Поговорите с Годаном в квартале Волока в Оргриммаре.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gприлежный ученик:прилежная ученица; и $gверный:верная; слуга для нас. Делай то, что велит тебе леди Сильвана, и Тень будет благосклонна к тебе.$B$BЧтобы поощрить тебя за хорошую службу, наша королева приказала своему чаротворцу в Оргриммаре изготовить оружие специально для тебя.$B$BНо прежде нужно собрать материалы для этого оружия, а найти их можно только в проклятой Крепости Темного Клыка, что в Серебряном бору. Отправляйся туда и добудь затерянный святой символ командира Спрингвейла, осененное луной дерево и сущности духов, обитающих в крепости.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в крепость Темного Клыка и добудьте святой символ командира у командира Спрингвейла, 5 вязанок осененного луной дерева и 5 образцов призрачной субстанции.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Темная жрица Сесиль сказала мне, что ты отправился за материалами для оружия в Крепость Темного Клыка. Теперь я вижу, почему: даже могущественная магия, которой окутана эта крепость, не смогла уничтожить силу, заключенную в этих предметах.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты раздобыл материалы для оружия?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Годаном в квартале Волока в Оргриммаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (27438,'Великое возвращение','Покиньте руины Гилнеаса вместе с Артурой и телом лорда Годфри.','Сбежать из руин Гилнеаса','Поговорите с леди Сильваной Ветрокрылой на Рубеже Отрекшихся в Серебряном бору.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Великое возвращение',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Покиньте руины Гилнеаса вместе с Артурой и телом лорда Годфри.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Сбежать из руин Гилнеаса',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с леди Сильваной Ветрокрылой на Рубеже Отрекшихся в Серебряном бору.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27439,'Посох Света','Ты становишься $gпреданным:преданной; слугой Света и Луносвета, $n. Твоя лояльность Орде и нашему народу может служить примером для других.$B$BЧтобы поощрить тебя за хорошую службу, вождь приказал своему чаротворцу изготовить для тебя специальный посох.$B$BНо прежде нужно собрать материалы для этого посоха, а найти их можно только в проклятой крепости Темного Клыка, что в Серебряном бору. Отправляйся туда и добудь затерянный святой символ командира Спрингвейла, осененное луной дерево и сущности духов, обитающих в крепости.','Отправляйтесь в крепость Темного Клыка и добудьте святой символ командира у командира Спрингвейла, 5 вязанок осененного луной дерева и 5 призрачных субстанций.','Поговорите с Годаном в квартале Волока в Оргриммаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Посох Света',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты становишься $gпреданным:преданной; слугой Света и Луносвета, $n. Твоя лояльность Орде и нашему народу может служить примером для других.$B$BЧтобы поощрить тебя за хорошую службу, вождь приказал своему чаротворцу изготовить для тебя специальный посох.$B$BНо прежде нужно собрать материалы для этого посоха, а найти их можно только в проклятой крепости Темного Клыка, что в Серебряном бору. Отправляйся туда и добудь затерянный святой символ командира Спрингвейла, осененное луной дерево и сущности духов, обитающих в крепости.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в крепость Темного Клыка и добудьте святой символ командира у командира Спрингвейла, 5 вязанок осененного луной дерева и 5 призрачных субстанций.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Годаном в квартале Волока в Оргриммаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27440,'Ничего себе – тролли, огры и орки!','Властитель черных драконов Змейталак командует войсками на Нижнем шпиле, практически готовыми к полномасштабному нападению на дворфов Черного Железа, расположенных ниже. Мы просто не можем позволить черным драконам захватить гору!$B$BУничтожь воеводу Вуна, вождя Омокка и властителя Змейталака. Их гибель внесет смятение в войска, что позволит нам выиграть драгоценное время.','Убейте воеводу Вуна, вождя Омокка и властителя Змейталака.','Вернитесь к Акрайду.','Злобный вражеский лидер.','Властитель Змейталак') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ничего себе – тролли, огры и орки!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Властитель черных драконов Змейталак командует войсками на Нижнем шпиле, практически готовыми к полномасштабному нападению на дворфов Черного Железа, расположенных ниже. Мы просто не можем позволить черным драконам захватить гору!$B$BУничтожь воеводу Вуна, вождя Омокка и властителя Змейталака. Их гибель внесет смятение в войска, что позволит нам выиграть драгоценное время.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте воеводу Вуна, вождя Омокка и властителя Змейталака.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Акрайду.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Злобный вражеский лидер.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Властитель Змейталак',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27441,'Посох ясновидца','Отправляйтесь в крепость Темного Клыка и добудьте святой символ командира Спрингвейла, 5 вязанок осененного луной дерева и 5 призрачных субстанций.','Поговорите с Годаном в квартале Волока в Оргриммаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Посох ясновидца',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в крепость Темного Клыка и добудьте святой символ командира Спрингвейла, 5 вязанок осененного луной дерева и 5 призрачных субстанций.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Годаном в квартале Волока в Оргриммаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27442,'По всем фронтам','Теперешнее состояние дел в Вайш\'ире гораздо лучше, чем до твоего приезда. Не пойми меня превратно: твоя помощь все еще нужна, просто на других фронтах ситуация еще хуже.$B$BМне доложили, что наши союзники Служители Земли пустили зов о помощи, находясь в критической ситуации.$B$BОбратись к предсказателю Крогару в Западном святилище Земли в Оргриммаре за дополнительными указаниями.','Переговори с предсказателем Крогаром в Западном святилище Земли в Оргриммаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','По всем фронтам',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперешнее состояние дел в Вайш\'ире гораздо лучше, чем до твоего приезда. Не пойми меня превратно: твоя помощь все еще нужна, просто на других фронтах ситуация еще хуже.$B$BМне доложили, что наши союзники Служители Земли пустили зов о помощи, находясь в критической ситуации.$B$BОбратись к предсказателю Крогару в Западном святилище Земли в Оргриммаре за дополнительными указаниями.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Переговори с предсказателем Крогаром в Западном святилище Земли в Оргриммаре.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27443,'По всем фронтам','Сейчас наши дела в Вайш\'ире идут значительно лучше, чем до твоего приезда. Не пойми меня превратно, нам все равно пригодилась бы твоя помощь, но, может статься, на других фронтах ситуация еще сложнее.$B$BМне сообщили, что наши союзники Служители Земли сейчас находятся в критическом положении и просят о помощи.$B$BЗа дальнейшими инструкциями обратись к Нараату Говорящему с Землей в Восточном святилище Земли в Штормграде.','Поговорите с Нараатом Говорящим с Землей в Восточном святилище Земли в Штормграде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','По всем фронтам',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сейчас наши дела в Вайш\'ире идут значительно лучше, чем до твоего приезда. Не пойми меня превратно, нам все равно пригодилась бы твоя помощь, но, может статься, на других фронтах ситуация еще сложнее.$B$BМне сообщили, что наши союзники Служители Земли сейчас находятся в критическом положении и просят о помощи.$B$BЗа дальнейшими инструкциями обратись к Нараату Говорящему с Землей в Восточном святилище Земли в Штормграде.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Нараатом Говорящим с Землей в Восточном святилище Земли в Штормграде.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27444,'Лжевождь','Ренд Чернорук – сын вождя орков. Его отец погиб от рук Оргрима Молота Рока, ставшего новым вождем над юным орком. В настоящий момент Ренд возглавляет лжеорду орков Черной горы, в чем его поддерживает Нефариан со своей драконьей армией.$B$BЭтот болван заявляет, что Орда принадлежит ему по праву рождения и угрожает вернуть себе власть силой! Мы не можем допустить этого в свете того, каким влиянием располагает его повелитель. Разыщи Ренда в Верхнем пике и положи конец его лживому правлению, |3-6($r).','Ликвидируйте вождя Ренда Чернорука.','Вернитесь к Акрайду.','Убейте лжевождя!','Вождь Ренд Чернорук') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лжевождь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ренд Чернорук – сын вождя орков. Его отец погиб от рук Оргрима Молота Рока, ставшего новым вождем над юным орком. В настоящий момент Ренд возглавляет лжеорду орков Черной горы, в чем его поддерживает Нефариан со своей драконьей армией.$B$BЭтот болван заявляет, что Орда принадлежит ему по праву рождения и угрожает вернуть себе власть силой! Мы не можем допустить этого в свете того, каким влиянием располагает его повелитель. Разыщи Ренда в Верхнем пике и положи конец его лживому правлению, |3-6($r).',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Ликвидируйте вождя Ренда Чернорука.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Акрайду.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Убейте лжевождя!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Вождь Ренд Чернорук',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27445,'Генерал Драккисат, правая рука Нефариана','Нефариан обосновался выше по горе, в Логове Крыла Тьмы. Хотя туда можно попасть и через Верхний пик, мы сможем провести гораздо больше солдат, воспользовавшись сферой телепортации, расположенной поблизости. Однако мы не сможем переместиться, пока овладеем еще одной сферой.$B$BГенерал Драккисат, командующий войском Нефариана, лично охраняет вторую сферу. Устрани его и забери сферу, чтобы мы могли ее воспользоваться. Генерал находится в Верховном троне, что в Верхнем пике.','Убейте генерала Драккисата.','Чудесно! Теперь это лишь вопрос времени, когда я расправлюсь с сыном Смертокрыла.','Вернитесь к Акрайду.','Его нужно устранить, чтобы проникнуть к Нефариану.','Генерал Драккисат') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Генерал Драккисат, правая рука Нефариана',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нефариан обосновался выше по горе, в Логове Крыла Тьмы. Хотя туда можно попасть и через Верхний пик, мы сможем провести гораздо больше солдат, воспользовавшись сферой телепортации, расположенной поблизости. Однако мы не сможем переместиться, пока овладеем еще одной сферой.$B$BГенерал Драккисат, командующий войском Нефариана, лично охраняет вторую сферу. Устрани его и забери сферу, чтобы мы могли ее воспользоваться. Генерал находится в Верховном троне, что в Верхнем пике.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте генерала Драккисата.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Чудесно! Теперь это лишь вопрос времени, когда я расправлюсь с сыном Смертокрыла.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Акрайду.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Его нужно устранить, чтобы проникнуть к Нефариану.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Генерал Драккисат',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27446,'Танарис вызывает','Эй, $n! Келси Стализвон из Танариса просила передать тебе кое-что. Она говорит, что гномы из Прибамбасска узнали о твоем присутствии здесь.$B$BИх, знаешь ли, тоже крепко потрепало этим Катаклизмом. Не так сурово, как нас, но они все равно вряд ли откажутся от помощи.','Поговорите с Келси Стализвон в Прибамбасске.','Приветствую тебя, друг. Добро пожаловать в Танарис!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Танарис вызывает',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эй, $n! Келси Стализвон из Танариса просила передать тебе кое-что. Она говорит, что гномы из Прибамбасска узнали о твоем присутствии здесь.$B$BИх, знаешь ли, тоже крепко потрепало этим Катаклизмом. Не так сурово, как нас, но они все равно вряд ли откажутся от помощи.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Келси Стализвон в Прибамбасске.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Приветствую тебя, друг. Добро пожаловать в Танарис!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27447,'Танарис вызывает','Эй, $n! Мегз Жестекрошшер из Танариса просила передать тебе кое-что. Она говорит, что гномы из Прибамбасска узнали о твоем присутствии здесь.$B$BИх, знаешь ли, тоже крепко потрепало этим Катаклизмом. Не так сурово, как нас, но они все равно вряд ли откажутся от помощи.$B$BДа, кстати, эта Мегз – горячая штучка!','Поговорите с Мегз Жестекрошшер в Прибамбасске.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Танарис вызывает',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эй, $n! Мегз Жестекрошшер из Танариса просила передать тебе кое-что. Она говорит, что гномы из Прибамбасска узнали о твоем присутствии здесь.$B$BИх, знаешь ли, тоже крепко потрепало этим Катаклизмом. Не так сурово, как нас, но они все равно вряд ли откажутся от помощи.$B$BДа, кстати, эта Мегз – горячая штучка!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Мегз Жестекрошшер в Прибамбасске.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27448,'Путешествие продолжается','Думаю, лошади уже готовы. Со мной говорил Аргус Путеводный, работающий на Серебряный Авангард. Насколько понимаю, он отправляется с нами. Я найду ему место.$B$BВероятно, у тебя еще есть дела, так что не торопись. Присоединяйся к каравану, как только подготовишься, и мы отправимся к следующей башне.','Займите место в караване Фионы, как только будете готовы отправиться к следующей башне.','Поговорите с Фионой в Башне Защиты Света, что в Восточных Чумных Землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путешествие продолжается',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Думаю, лошади уже готовы. Со мной говорил Аргус Путеводный, работающий на Серебряный Авангард. Насколько понимаю, он отправляется с нами. Я найду ему место.$B$BВероятно, у тебя еще есть дела, так что не торопись. Присоединяйся к каравану, как только подготовишься, и мы отправимся к следующей башне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Займите место в караване Фионы, как только будете готовы отправиться к следующей башне.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Фионой в Башне Защиты Света, что в Восточных Чумных Землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27449,'Честь и сила','Меня зовут Векс\'тул, я видел, как ты сражаешься, |3-6($r). Сил тебе не занимать.$B$BТы $gубил:убила; моего господина, Зельдарра, но я не скорблю. Для меня сила важнее преданности. Да и вообще сила важнее всего на свете.$B$BПокажи мне свою силу еще раз, |3-6($r). Тогда я предоставлю в твое распоряжение МОЮ силу – для любых целей, которые ты сочтешь нужными.','Пройдите испытание силы Векс\'тула.','Да, ты и правда силен... И я подчинюсь тебе.$B$BЯ присоединюсь к тебе и твоему другу воргену. Моя сила теперь твоя!','Поговорите с Векс\'тулом в Башне Защиты Света, что в Восточных Чумных Землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Честь и сила',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Меня зовут Векс\'тул, я видел, как ты сражаешься, |3-6($r). Сил тебе не занимать.$B$BТы $gубил:убила; моего господина, Зельдарра, но я не скорблю. Для меня сила важнее преданности. Да и вообще сила важнее всего на свете.$B$BПокажи мне свою силу еще раз, |3-6($r). Тогда я предоставлю в твое распоряжение МОЮ силу – для любых целей, которые ты сочтешь нужными.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Пройдите испытание силы Векс\'тула.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, ты и правда силен... И я подчинюсь тебе.$B$BЯ присоединюсь к тебе и твоему другу воргену. Моя сила теперь твоя!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Векс\'тулом в Башне Защиты Света, что в Восточных Чумных Землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27450,'Фредерик, любитель рыбы','Я обожаю море. Да, это я, Фредерик Калстон, поселил морскую живность в том озере на юго-западе. Таким образом я надеялся создать для Авангарда источник пищи в Чумных землях.$B$BНо некоторые рыбы оказались хищниками, и теперь они терроризируют остальных. И если мы будем сидеть сложа руки, они всех съедят!$B$BНырни на самое дно и добудь несколько ползецов, бегунов и иглобрюхов, пока не поздно.','Добудьте 8 чумных иглобрюхов, 8 зараженных ползецов и 8 зараженных бегунов из Чумного оврага.','Хм... они продержались без воды гораздо меньше, чем я рассчитывал.$B$BНу да ладно! Сегодня вечером у Фредерика будет салат с морепродуктами!','Рыба... рыба у тебя?','Поговорите с Фредериком Калстоном в Башне Защиты Света в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Фредерик, любитель рыбы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я обожаю море. Да, это я, Фредерик Калстон, поселил морскую живность в том озере на юго-западе. Таким образом я надеялся создать для Авангарда источник пищи в Чумных землях.$B$BНо некоторые рыбы оказались хищниками, и теперь они терроризируют остальных. И если мы будем сидеть сложа руки, они всех съедят!$B$BНырни на самое дно и добудь несколько ползецов, бегунов и иглобрюхов, пока не поздно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 8 чумных иглобрюхов, 8 зараженных ползецов и 8 зараженных бегунов из Чумного оврага.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хм... они продержались без воды гораздо меньше, чем я рассчитывал.$B$BНу да ладно! Сегодня вечером у Фредерика будет салат с морепродуктами!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Рыба... рыба у тебя?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Фредериком Калстоном в Башне Защиты Света в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (27451,'Убийство во благо','Приветствую, $gчужестранец:чужестранка;! Ты в самом сердце Чумных земель. Надеюсь, ты $gпринес:принесла; с собой снаряжение для уничтожения нежити.$B$BЗараза нынче распространяется медленнее, поэтому культ Проклятых повысил свою активность, чтобы земля оставалась бурой и мертвой, как они любят. Я знаю, как их остановить. Возьми мою ступку и пестик, иди в Перекресток Корина, что к юго-востоку отсюда, и перемели живую гниль, которая сочится из этих тварей. Мы приготовим подарочек служителям культа!','Отправляйтесь в Перекресток Корина на юге и расправьтесь с воинами Плети. Соберите 7 кусков живой гнили. Воспользуйтесь ступкой и пестиком, чтобы перемолоть живую гниль в сгущенную гниль.','Поговорите с Бетиной Биггльцинк в Башне Защиты Света в Восточных Чумных землях.','Поосторожней с этой гнилью!','Бетина Биггльцинк') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Убийство во благо',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приветствую, $gчужестранец:чужестранка;! Ты в самом сердце Чумных земель. Надеюсь, ты $gпринес:принесла; с собой снаряжение для уничтожения нежити.$B$BЗараза нынче распространяется медленнее, поэтому культ Проклятых повысил свою активность, чтобы земля оставалась бурой и мертвой, как они любят. Я знаю, как их остановить. Возьми мою ступку и пестик, иди в Перекресток Корина, что к юго-востоку отсюда, и перемели живую гниль, которая сочится из этих тварей. Мы приготовим подарочек служителям культа!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Перекресток Корина на юге и расправьтесь с воинами Плети. Соберите 7 кусков живой гнили. Воспользуйтесь ступкой и пестиком, чтобы перемолоть живую гниль в сгущенную гниль.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Бетиной Биггльцинк в Башне Защиты Света в Восточных Чумных землях.',`completedtext_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Поосторожней с этой гнилью!',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Бетина Биггльцинк',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (27452,'Темные одеяния','До меня не раз доходили разговоры о том, что наша земля жаждет исцеления, но этому мешает нежить вместе с Культом Проклятых. Их надо остановить! У меня есть план, но перво-наперво тебе нужно раздобыть сектантскую одежду.$B$BОтправляйся на юго-восток в Перекресток Корина и достань одежду у местных сектантов. Когда все сделаешь, я сама выйду на связь.','Добудьте головной убор сектанта Смерти и одеяния сектанта Смерти у сектантов в Перекрестке Корина.','Поговорите с Бетиной Биггльцинк в Башне Защиты Света, что в Восточных Чумных Землях.','Все будет отлично!','Бетина Биггльцинк') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Темные одеяния',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','До меня не раз доходили разговоры о том, что наша земля жаждет исцеления, но этому мешает нежить вместе с Культом Проклятых. Их надо остановить! У меня есть план, но перво-наперво тебе нужно раздобыть сектантскую одежду.$B$BОтправляйся на юго-восток в Перекресток Корина и достань одежду у местных сектантов. Когда все сделаешь, я сама выйду на связь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте головной убор сектанта Смерти и одеяния сектанта Смерти у сектантов в Перекрестке Корина.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Бетиной Биггльцинк в Башне Защиты Света, что в Восточных Чумных Землях.',`completedtext_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Все будет отлично!',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Бетина Биггльцинк',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (27453,'Катализатор','Сгущенная гниль – сама по себе мощная штука, но нам надо полностью раскрыть ее потенциал... А для этого необходим катализатор. Как раз подходящий можно найти в озере Мерельдар.$B$BЕсли ты опустишь взгляд, увидишь, что я незаметно для тебя распихала по твоим котомкам несколько склянок. Это для водяных элементалей, которые водятся в озере. Живая оскверненная вода, наполняющая их тела, – вот самый лучший катализатор!','Возьмите склянки Бетины и получите 8 активных жидких вирусов чумы у живых элементалей озера Мерельдар.','Поговорите с Бетиной Биггльцинк в Башне Защиты Света, что в Восточных Чумных Землях.','О-ой... Кажется, мы переборщили с крепостью раствора.','Бетина Биггльцинк') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Катализатор',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сгущенная гниль – сама по себе мощная штука, но нам надо полностью раскрыть ее потенциал... А для этого необходим катализатор. Как раз подходящий можно найти в озере Мерельдар.$B$BЕсли ты опустишь взгляд, увидишь, что я незаметно для тебя распихала по твоим котомкам несколько склянок. Это для водяных элементалей, которые водятся в озере. Живая оскверненная вода, наполняющая их тела, – вот самый лучший катализатор!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возьмите склянки Бетины и получите 8 активных жидких вирусов чумы у живых элементалей озера Мерельдар.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Бетиной Биггльцинк в Башне Защиты Света, что в Восточных Чумных Землях.',`completedtext_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','О-ой... Кажется, мы переборщили с крепостью раствора.',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Бетина Биггльцинк',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (27454,'Капля в море','Теперь добавим немного в воду и тщательно перемешаем. Вот так. Раствор сильнодействующий, поэтому нам потребуется совсем немного.$B$BНа юго-восточном берегу озера ты найдешь чумной котел, который охраняют несколько сектантов. Замаскируйся под них, подойди к котлу и капни туда ОДНУ КАПЛЮ раствора. Ни в коем случае не больше, а то можешь и жизни лишиться!','Используйте маскировку под сектанта Смерти, проберитесь в лагерь сектантов Смерти, а затем добавьте смесь Бетины в Мерельдарский чумной котел.','Раствор в мерельдарский чумной котел добавлен','Поговорите с Бетиной Биггльцинк в Башне Защиты Света, что в Восточных Чумных Землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Капля в море',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь добавим немного в воду и тщательно перемешаем. Вот так. Раствор сильнодействующий, поэтому нам потребуется совсем немного.$B$BНа юго-восточном берегу озера ты найдешь чумной котел, который охраняют несколько сектантов. Замаскируйся под них, подойди к котлу и капни туда ОДНУ КАПЛЮ раствора. Ни в коем случае не больше, а то можешь и жизни лишиться!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте маскировку под сектанта Смерти, проберитесь в лагерь сектантов Смерти, а затем добавьте смесь Бетины в Мерельдарский чумной котел.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Раствор в мерельдарский чумной котел добавлен',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Бетиной Биггльцинк в Башне Защиты Света, что в Восточных Чумных Землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27455,'Ох уж эти мальчики','Как только мы прибыли в Башню Защиты Света, эти чурбаны-паладины убежали в часовню Последней Надежды. До нее еще далеко, но если мы двинемся вслед за Аргусом, то хотя бы приблизимся к ней.$B$BПожалуйста, найди их и убедись, что у них все в порядке. Знаю, они могут постоять за себя, но мне станет легче на душе, если я буду знать, что ты их охраняешь, пока я застряла здесь со своим караваном.','Найдите Гидвина Златокоса в часовне Последней Надежды в Восточных Чумных землях.','Невероятно. Мы были в нескольких ФУТАХ от вступления в Серебряный Авангард.$B$BЕсли бы не Таренар, мы бы уже принесли присягу. Если он сейчас же не перестанет болтать с местными, я поеду без него.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ох уж эти мальчики',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как только мы прибыли в Башню Защиты Света, эти чурбаны-паладины убежали в часовню Последней Надежды. До нее еще далеко, но если мы двинемся вслед за Аргусом, то хотя бы приблизимся к ней.$B$BПожалуйста, найди их и убедись, что у них все в порядке. Знаю, они могут постоять за себя, но мне станет легче на душе, если я буду знать, что ты их охраняешь, пока я застряла здесь со своим караваном.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Гидвина Златокоса в часовне Последней Надежды в Восточных Чумных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Невероятно. Мы были в нескольких ФУТАХ от вступления в Серебряный Авангард.$B$BЕсли бы не Таренар, мы бы уже принесли присягу. Если он сейчас же не перестанет болтать с местными, я поеду без него.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27456,'Личинокос','Здесь, на дальнем востоке, у нас возникли сложности с пополнением запасов продовольствия. $B$BВ этих краях чумой не поражены только черви-трупоеды. У них мясо совсем безвкусное, зато хранится несколько месяцев. Нам нужно пополнить запасы – а значит, нам понадобится несколько сотен фунтов этого мяса.$B$BЧервей-трупоедов можно найти повсюду в Чумных землях, но особенно много их к югу от часовни. И помни: чем крупнее червь, тем больше в нем мяса.','Убивайте личинок-падальщиков и пожирателей. Соберите 15 кусков мяса червя-трупоеда.','Храни тебя Мать-Земля, малыш!','Ты привыкнешь к вкусу этого мяса, |3-6(Гном). Я же привык.','Поговорите с Римблатом Землекрушителем в часовне Последней Надежды в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Личинокос',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Здесь, на дальнем востоке, у нас возникли сложности с пополнением запасов продовольствия. $B$BВ этих краях чумой не поражены только черви-трупоеды. У них мясо совсем безвкусное, зато хранится несколько месяцев. Нам нужно пополнить запасы – а значит, нам понадобится несколько сотен фунтов этого мяса.$B$BЧервей-трупоедов можно найти повсюду в Чумных землях, но особенно много их к югу от часовни. И помни: чем крупнее червь, тем больше в нем мяса.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убивайте личинок-падальщиков и пожирателей. Соберите 15 кусков мяса червя-трупоеда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Храни тебя Мать-Земля, малыш!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты привыкнешь к вкусу этого мяса, |3-6(Гном). Я же привык.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Римблатом Землекрушителем в часовне Последней Надежды в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27457,'Случайный попутчик','Тебе удалось добыть для нас столько пищи, что мое задание, считай, уже выполнено.$B$BТеперь мне надо на север, в Чумной лес. Насколько понимаю, тебе тоже в ту сторону.$B$BНе возражаешь, если вместе пойдем?$B$BЯ отправлюсь на северо-восток, к Восточной башне. Если хочешь пойти со мной, ищи меня там.','Поговорите с Фионой в Восточной башне в Восточных Чумных землях.','Тебе удалось привести сюда шамана! Шамана из Служителей Земли!$B$BПравда, у нас в караване мало места... Ну ладно, что-нибудь придумаем. Добро пожаловать, Римблат Землекрушитель!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Случайный попутчик',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе удалось добыть для нас столько пищи, что мое задание, считай, уже выполнено.$B$BТеперь мне надо на север, в Чумной лес. Насколько понимаю, тебе тоже в ту сторону.$B$BНе возражаешь, если вместе пойдем?$B$BЯ отправлюсь на северо-восток, к Восточной башне. Если хочешь пойти со мной, ищи меня там.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Фионой в Восточной башне в Восточных Чумных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебе удалось привести сюда шамана! Шамана из Служителей Земли!$B$BПравда, у нас в караване мало места... Ну ладно, что-нибудь придумаем. Добро пожаловать, Римблат Землекрушитель!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27458,'Дымок и бинты','Эй! Хочешь подработать?$B$BМне нужны бинты. Ну, точнее, у меня есть друг, которому нужны бинты. Ну, если честно... скажем так, это довольно запутанная история. Но если тебе удастся добыть бинты, ты на этом заработаешь. И я тоже. И мой друг. И, быть может, и другие.$B$BСтивен Бровач раньше владел мельницей на севере, но теперь он мертв. Стал зомби. А мой начальник хочет получить обмотки, в которые завернуто тело Бровача.$B$BНу? За чем дело стало? Тебе деньги, что ли, не нужны?','Зайдите на лесопилку Бровача и возьмите перевязь Бровача у Стивена Бровача.','Так-так-так! Похоже, дело сделано! Вот твоя доля, вождь. До скорого.','Похоже, тебе пришлось сражаться с нежитью. А Бровача там не было?','Поговорите с Дымком ЛаРу в часовне Последней Надежды в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дымок и бинты',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эй! Хочешь подработать?$B$BМне нужны бинты. Ну, точнее, у меня есть друг, которому нужны бинты. Ну, если честно... скажем так, это довольно запутанная история. Но если тебе удастся добыть бинты, ты на этом заработаешь. И я тоже. И мой друг. И, быть может, и другие.$B$BСтивен Бровач раньше владел мельницей на севере, но теперь он мертв. Стал зомби. А мой начальник хочет получить обмотки, в которые завернуто тело Бровача.$B$BНу? За чем дело стало? Тебе деньги, что ли, не нужны?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Зайдите на лесопилку Бровача и возьмите перевязь Бровача у Стивена Бровача.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так-так-так! Похоже, дело сделано! Вот твоя доля, вождь. До скорого.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Похоже, тебе пришлось сражаться с нежитью. А Бровача там не было?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Дымком ЛаРу в часовне Последней Надежды в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27459,'Братство Света','В своей истории Братство Света неоднократно принимало поспешные, необдуманные решения. Они восстановили отношения между Алым орденом и Серебряным Рассветом. Они одними из первых отправились в Нордскол – а многие из нас остались дома.$B$BОднако они умеют добиваться своего, и за это я их уважаю. Сейчас они ведут войну сразу на два фронта: одна битва идет в Стратхольме, а вторая, более важная, на юге, в Длани Тира.$B$BСоветую тебе отправиться в Длань Тира и поговорить с Анжелой Досантос. Возможно, ей нужна твоя помощь.','Явитесь с докладом к верховному магу Анжеле Досантос в Длань Тира в Восточных Чумных землях.','Разбойник! Это именно то, что нам нужно. Ты как раз вовремя.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Братство Света',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В своей истории Братство Света неоднократно принимало поспешные, необдуманные решения. Они восстановили отношения между Алым орденом и Серебряным Рассветом. Они одними из первых отправились в Нордскол – а многие из нас остались дома.$B$BОднако они умеют добиваться своего, и за это я их уважаю. Сейчас они ведут войну сразу на два фронта: одна битва идет в Стратхольме, а вторая, более важная, на юге, в Длани Тира.$B$BСоветую тебе отправиться в Длань Тира и поговорить с Анжелой Досантос. Возможно, ей нужна твоя помощь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Явитесь с докладом к верховному магу Анжеле Досантос в Длань Тира в Восточных Чумных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Разбойник! Это именно то, что нам нужно. Ты как раз вовремя.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27460,'Мягкая посадка','На это задание отправили отряд всего из ста воинов, и один из них уже погиб. Мы послали разведчика во вражескую крепость, чтобы он снял часовых и запустил осветительную ракету – сигнал к атаке. Остальные девяносто девять готовы к бою и ждут сигнала. И поэтому я прошу тебя проскользнуть в Длань Тира, перебить как можно больше стражников, а затем запустить ту осветительную ракету.$B$BНу что? Справишься?','Убейте 10 любых представителей Алого ордена в Длани Тира.','Осветительная ракета уже собрана, спички лежат рядом с фитилем.$B$BПохоже, погибшему центуриону Серебряных почти удалось запустить эту ракету.','Запустите осветительную ракету, которая находится за часовней в Длани Тира.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мягкая посадка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На это задание отправили отряд всего из ста воинов, и один из них уже погиб. Мы послали разведчика во вражескую крепость, чтобы он снял часовых и запустил осветительную ракету – сигнал к атаке. Остальные девяносто девять готовы к бою и ждут сигнала. И поэтому я прошу тебя проскользнуть в Длань Тира, перебить как можно больше стражников, а затем запустить ту осветительную ракету.$B$BНу что? Справишься?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 любых представителей Алого ордена в Длани Тира.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Осветительная ракета уже собрана, спички лежат рядом с фитилем.$B$BПохоже, погибшему центуриону Серебряных почти удалось запустить эту ракету.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Запустите осветительную ракету, которая находится за часовней в Длани Тира.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27461,'Штурм аббатства','На нижнем уровне Длани Тира, в ее западной части находится хорошо укрепленное аббатство Алого ордена. Это аббатство нужно захватить, иначе мы не сможем двинуться дальше.','Явитесь с докладом к командиру Элигору Вестнику Рассвета к аббатству Длани Тира в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Штурм аббатства',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На нижнем уровне Длани Тира, в ее западной части находится хорошо укрепленное аббатство Алого ордена. Это аббатство нужно захватить, иначе мы не сможем двинуться дальше.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Явитесь с докладом к командиру Элигору Вестнику Рассвета к аббатству Длани Тира в Восточных Чумных землях.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27462,'Штурм казармы','Там, где лежит осветительная ракета, находится казарма – одно из ключевых укреплений Длани Тира. Центурионы Братства Света пытаются захватить ее, и им нужна твоя помощь.','Явитесь с докладом к командиру рыцарей Корфаксу к казарме Длани Тира в Восточных Чумных землях.','Разбойник, остальное сделаю я.$B$BМожет, тебе нужно новое задание? Думаю, у меня найдется пара поручений.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Штурм казармы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Там, где лежит осветительная ракета, находится казарма – одно из ключевых укреплений Длани Тира. Центурионы Братства Света пытаются захватить ее, и им нужна твоя помощь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Явитесь с докладом к командиру рыцарей Корфаксу к казарме Длани Тира в Восточных Чумных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Разбойник, остальное сделаю я.$B$BМожет, тебе нужно новое задание? Думаю, у меня найдется пара поручений.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27463,'Мечта детства','Я всегда хотел вступить в Авангард. Именно поэтому и стал паладином. Долгие годы тренировок... и вот я готов.$B$BТаренар тоже считает, что готов, но я в этом не уверен. Он хвастун и всегда учился спустя рукава. Но мы дали клятву друг другу, что пойдем на войну вместе, и вот мы здесь.$B$BНу что, идем в часовню?','Зайдите в часовню Последней Надежды и поговорите с лордом Максвеллом Тироссом.','Добро пожаловать в часовню Последней Надежды.$B$BТы хочешь к нам присоединиться? Отлично. У нас много заданий для новичков.$B$BНо сначала тебе нужно пройти испытание.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мечта детства',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я всегда хотел вступить в Авангард. Именно поэтому и стал паладином. Долгие годы тренировок... и вот я готов.$B$BТаренар тоже считает, что готов, но я в этом не уверен. Он хвастун и всегда учился спустя рукава. Но мы дали клятву друг другу, что пойдем на войну вместе, и вот мы здесь.$B$BНу что, идем в часовню?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Зайдите в часовню Последней Надежды и поговорите с лордом Максвеллом Тироссом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Добро пожаловать в часовню Последней Надежды.$B$BТы хочешь к нам присоединиться? Отлично. У нас много заданий для новичков.$B$BНо сначала тебе нужно пройти испытание.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27464,'Серебряный зов: испытание в склепе','За нашей часовней находится небольшой склеп. В нем похоронены герои – те, кто отдал свою жизнь в борьбе с Плетью.$B$BИх души обрели покой, но время от времени они возвращаются, чтобы испытать неофитов.$B$BВы трое можете пройти испытание вместе. Войдите в склеп, а затем прочитайте этот свиток. Руководить испытанием будет мой предшественник, лорд Реймонд Джордж.','Войдите в склеп за часовней Последней Надежды, прочитайте Серебряный свиток, а затем пройдите испытание.','Вернитесь к лорду Максвеллу Тироссу в Часовню Последней Надежды в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Серебряный зов: испытание в склепе',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','За нашей часовней находится небольшой склеп. В нем похоронены герои – те, кто отдал свою жизнь в борьбе с Плетью.$B$BИх души обрели покой, но время от времени они возвращаются, чтобы испытать неофитов.$B$BВы трое можете пройти испытание вместе. Войдите в склеп, а затем прочитайте этот свиток. Руководить испытанием будет мой предшественник, лорд Реймонд Джордж.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Войдите в склеп за часовней Последней Надежды, прочитайте Серебряный свиток, а затем пройдите испытание.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лорду Максвеллу Тироссу в Часовню Последней Надежды в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27465,'Серебряный зов: Ядовитая поляна','Лесопилка Бровача, что к северу отсюда, кишит нежитью. А Ядовитая поляна за ней – и того пуще. Да, наша часовня рядом, но нам так и не удалось избавиться от всей нечисти в округе.$B$BБудь начеку. Отправляйся в Ядовитую долину и истреби как можно больше нежити... а заодно и сектантов, если вдруг повстречаешь.$B$BВ долине остерегайся великана Гаргинокса. Ты вряд ли с ним справишься.','Убейте 16 воинов Плети и 8 сектантов на лесопилке Бровача и Ядовитой поляне. Если Таренар или Гидвин погибнут, возвращайтесь в часовню Последней Надежды.','Я не ожидал, что ты вернешься так скоро. Отлично.$B$BМы двинемся дальше на север, а потом тебя ждет похожая работа – но на этот раз в Северном Доле.','Поговорите с лордом Максвеллом Тироссом в часовне Последней Надежды в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Серебряный зов: Ядовитая поляна',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Лесопилка Бровача, что к северу отсюда, кишит нежитью. А Ядовитая поляна за ней – и того пуще. Да, наша часовня рядом, но нам так и не удалось избавиться от всей нечисти в округе.$B$BБудь начеку. Отправляйся в Ядовитую долину и истреби как можно больше нежити... а заодно и сектантов, если вдруг повстречаешь.$B$BВ долине остерегайся великана Гаргинокса. Ты вряд ли с ним справишься.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 16 воинов Плети и 8 сектантов на лесопилке Бровача и Ядовитой поляне. Если Таренар или Гидвин погибнут, возвращайтесь в часовню Последней Надежды.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я не ожидал, что ты вернешься так скоро. Отлично.$B$BМы двинемся дальше на север, а потом тебя ждет похожая работа – но на этот раз в Северном Доле.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с лордом Максвеллом Тироссом в часовне Последней Надежды в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27466,'Серебряный зов: Северный Дол','Тиросс выдал новое задание: уничтожить как можно больше нежити в Северном Доле. Гидвину не терпится двинуться вперед, но мне кажется, что нам нужно проявить осторожность.$B$BДавай поговорим с Фионой – сейчас она должна быть у следующей башни... Кажется, ее называют "Восточной". Она недалеко, к северо-западу от часовни Последней Надежды. Там мы сможем отдохнуть и разработать план наступления на Северный Дол.','Поговорите с Фионой в Восточной башне в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Серебряный зов: Северный Дол',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тиросс выдал новое задание: уничтожить как можно больше нежити в Северном Доле. Гидвину не терпится двинуться вперед, но мне кажется, что нам нужно проявить осторожность.$B$BДавай поговорим с Фионой – сейчас она должна быть у следующей башни... Кажется, ее называют "Восточной". Она недалеко, к северо-западу от часовни Последней Надежды. Там мы сможем отдохнуть и разработать план наступления на Северный Дол.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Фионой в Восточной башне в Восточных Чумных землях.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27467,'Похоронные клинки','Ядовитая поляна настоящее болото – и в прямом, и в переносном смысле. Войск Плети здесь столько, что хватит на остаток наших обеих жизней.$B$BИ, $n, они умеют оживлять своих погибших – к счастью, только слабых. Так что если мы ничего не предпримем, их потоку не будет конца.$B$BВозьми эти клинки и втыкай во все трупы воинов Плети, которые найдешь. Сами клинки простые, но чары на них помешают врагу воскрешать погибших воинов.','Воткните осененные Светом клинки в тела десяти убитых штурмовиков Плети.','Сейчас наша работа закончена.$B$BЕще немного, и мы разгромим силы Плети. Сегодня мы сделали еще один шаг к победе.','Поговорите с мастером-ремесленником Омарионом в часовне Последней Надежды в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Похоронные клинки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ядовитая поляна настоящее болото – и в прямом, и в переносном смысле. Войск Плети здесь столько, что хватит на остаток наших обеих жизней.$B$BИ, $n, они умеют оживлять своих погибших – к счастью, только слабых. Так что если мы ничего не предпримем, их потоку не будет конца.$B$BВозьми эти клинки и втыкай во все трупы воинов Плети, которые найдешь. Сами клинки простые, но чары на них помешают врагу воскрешать погибших воинов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воткните осененные Светом клинки в тела десяти убитых штурмовиков Плети.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сейчас наша работа закончена.$B$BЕще немного, и мы разгромим силы Плети. Сегодня мы сделали еще один шаг к победе.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с мастером-ремесленником Омарионом в часовне Последней Надежды в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27468,'Спасение осадного танка','Нам придется вытаскивать наши осадные танки из ила по одному. Возьми собранные тобой детали и отнеси их командиру осадного танка, который стоит на своей подбитой машине. $B$BЗатем защищай танк, пока инженеры его чинят.$B$BНе подведи меня, |3-6($c)!','Поговорите с командиром осадного танка, который стоит на своем подбитом осадном танке Высокого берега. Защищайте танк, пока инженеры его ремонтируют.','Еще один танк ползет на базу для ремонта.$B$BТут сплошные деревья, пни, камни и трясина – в гольф нельзя играть, не то что на танке ездить.$B$BНам нужен новый подход.','Камни, пни, кочки, грязь... Тьфу.$B$BНенавижу природу.','Поговорите с Фарго Кремневым Затвором на Сумеречном берегу на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спасение осадного танка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нам придется вытаскивать наши осадные танки из ила по одному. Возьми собранные тобой детали и отнеси их командиру осадного танка, который стоит на своей подбитой машине. $B$BЗатем защищай танк, пока инженеры его чинят.$B$BНе подведи меня, |3-6($c)!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с командиром осадного танка, который стоит на своем подбитом осадном танке Высокого берега. Защищайте танк, пока инженеры его ремонтируют.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Еще один танк ползет на базу для ремонта.$B$BТут сплошные деревья, пни, камни и трясина – в гольф нельзя играть, не то что на танке ездить.$B$BНам нужен новый подход.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Камни, пни, кочки, грязь... Тьфу.$B$BНенавижу природу.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Фарго Кремневым Затвором на Сумеречном берегу на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27470,'Потенциальный союзник','Не секрет, что мы не особо любим орков Черной горы, однако мы пристально следим за каждым их шагом. На этой горе ничто не ускользнет от моего взора, |3-6($c).$B$BНедавно на Черную гору проник необычный орк. Он обитает прямо в Верхнем пике, и по моим сведениям он также желает разгромить Нефариана с его армией орков. В обычных обстоятельствах я бы не решился довериться орку, но сейчас у нас есть общая цель. Отыщи орка по имени Акрайд.','Разыщите Акрайда.','Приветствую тебя! С чем пожаловал?$B$BТебя прислал надзиратель Скользорук? Слушай меня внимательно, у нас мало времени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Потенциальный союзник',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не секрет, что мы не особо любим орков Черной горы, однако мы пристально следим за каждым их шагом. На этой горе ничто не ускользнет от моего взора, |3-6($c).$B$BНедавно на Черную гору проник необычный орк. Он обитает прямо в Верхнем пике, и по моим сведениям он также желает разгромить Нефариана с его армией орков. В обычных обстоятельствах я бы не решился довериться орку, но сейчас у нас есть общая цель. Отыщи орка по имени Акрайд.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите Акрайда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Приветствую тебя! С чем пожаловал?$B$BТебя прислал надзиратель Скользорук? Слушай меня внимательно, у нас мало времени.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27471,'Странный орк Черной горы','У Пика Черной горы обитает орк, абсолютно не похожий на других. В его словах звучит голос разума и удивительная для его лет мудрость; кроме того, в отличие от других орков он никогда не нападает на наших воинов.$B$BСледуй на северо-запад к Пику Черной горы и разыщи этого диковинного орка по имени Акрайд. Он может сыграть ключевую роль в сражении с орочьей армией. Может статься, что мы успеем остановить Нефариана, пока еще не слишком поздно...','Разыщите Акрайда.','Здравствуй! Что это ты позабыл в таком странном месте?$B$BТак ты тут поручению госпожи Светлое Крыло? Чрезвычайно интересно.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Странный орк Черной горы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У Пика Черной горы обитает орк, абсолютно не похожий на других. В его словах звучит голос разума и удивительная для его лет мудрость; кроме того, в отличие от других орков он никогда не нападает на наших воинов.$B$BСледуй на северо-запад к Пику Черной горы и разыщи этого диковинного орка по имени Акрайд. Он может сыграть ключевую роль в сражении с орочьей армией. Может статься, что мы успеем остановить Нефариана, пока еще не слишком поздно...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите Акрайда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Здравствуй! Что это ты позабыл в таком странном месте?$B$BТак ты тут поручению госпожи Светлое Крыло? Чрезвычайно интересно.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27472,'Восстань, Годфри','Ты $gпродемонстрировал:продемонстрировала; твердую верность Отрекшимся, $n. Знай, твоя помощь Орде не будет забыта. Когда лорд Годфри и его люди восстанут, у нас появится огромное преимущество перед фронтом освобождения Гилнеаса и остальными прихвостнями Альянса.$B$BТеперь стань рядом со мной, сейчас лорд Годфри воскреснет и пополнит наши ряды. Мы поможем ему в этом.','Встаньте рядом с леди Сильваной Ветрокрылой во время оживления лорда Годфри и его людей.','Сегодняшний день станет началом торжества Отрекшихся и концом господства Альянса в Лордероне!','Поговорите с леди Сильваной Ветрокрылой на Рубеже Отрекшихся в Серебряном бору.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Восстань, Годфри',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gпродемонстрировал:продемонстрировала; твердую верность Отрекшимся, $n. Знай, твоя помощь Орде не будет забыта. Когда лорд Годфри и его люди восстанут, у нас появится огромное преимущество перед фронтом освобождения Гилнеаса и остальными прихвостнями Альянса.$B$BТеперь стань рядом со мной, сейчас лорд Годфри воскреснет и пополнит наши ряды. Мы поможем ему в этом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Встаньте рядом с леди Сильваной Ветрокрылой во время оживления лорда Годфри и его людей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сегодняшний день станет началом торжества Отрекшихся и концом господства Альянса в Лордероне!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с леди Сильваной Ветрокрылой на Рубеже Отрекшихся в Серебряном бору.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27474,'Убрать барьер','Пока мы с Годфри готовимся к атаке на Гилнеас, ты $gдолжен:должна; руководить нападением на Янтарную мельницу, это к востоку отсюда.$B$BБывшие даларанские маги, обосновавшиеся там, создали защитный барьер, который как-то скрывает их из виду. Сейчас они живут в некоем кармане измерений и ждут приказа Альянса. Мы должны нанести удар раньше, чем это сделают они. Так что ступай к Янтарной мельнице и выясни, как можно подобраться к этим магам.','Найдите кодекс Янтарной мельницы.','Умные они, эти маги. Кодекс запечатан магическим заклятьем.$B$BЖаль, им ума не хватило понять, что бывшие верховные маги из Даларана теперь в рядах Отрекшихся.','Удалось что-нибудь отыскать?','Вернитесь к леди Сильване Ветрокрылой на Рубеж Отрекшихся в Серебряном бору.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Убрать барьер',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пока мы с Годфри готовимся к атаке на Гилнеас, ты $gдолжен:должна; руководить нападением на Янтарную мельницу, это к востоку отсюда.$B$BБывшие даларанские маги, обосновавшиеся там, создали защитный барьер, который как-то скрывает их из виду. Сейчас они живут в некоем кармане измерений и ждут приказа Альянса. Мы должны нанести удар раньше, чем это сделают они. Так что ступай к Янтарной мельнице и выясни, как можно подобраться к этим магам.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите кодекс Янтарной мельницы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Умные они, эти маги. Кодекс запечатан магическим заклятьем.$B$BЖаль, им ума не хватило понять, что бывшие верховные маги из Даларана теперь в рядах Отрекшихся.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось что-нибудь отыскать?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к леди Сильване Ветрокрылой на Рубеж Отрекшихся в Серебряном бору.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27475,'Упорные защитники','С помощью своих грязных приемов маги Янтарной мельницы не позволяют нам подобраться поближе. Мы никак не можем прорваться на эту территорию сквозь нерушимую защиту элементалей-служителей.$B$BСтупай на восток к Янтарной мельнице, перебей упорных элементалей-служителей, охраняющих этот город, и принеси мне их ядра – попробую найти способ всех их уничтожить!','Добудьте 6 ядер элементалей-служителей.','Вернитесь к Дашле на Рубеж Отрекшихся в Серебряном бору.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Упорные защитники',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','С помощью своих грязных приемов маги Янтарной мельницы не позволяют нам подобраться поближе. Мы никак не можем прорваться на эту территорию сквозь нерушимую защиту элементалей-служителей.$B$BСтупай на восток к Янтарной мельнице, перебей упорных элементалей-служителей, охраняющих этот город, и принеси мне их ядра – попробую найти способ всех их уничтожить!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 6 ядер элементалей-служителей.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дашле на Рубеж Отрекшихся в Серебряном бору.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (27476,'Далар Ткач Рассвета','Возьми этот кодекс, отправляйся на север, к Гробнице, и найди там Далара Ткача Рассвета. Когда-то Далар был верховным магом Кирин-Тора. Он наверняка сумеет снять защитные чары с кодекса и открыть нам все его секреты.$B$BПоспеши, $n.','Отнесите кодекс Янтарной мельницы Далару Ткачу Рассвета в Гробницу в Серебряном бору.','Темная Госпожа ищет моей помощи? Разумеется, я помогу! Передай мне кодекс, мальчик.','Да? В чем дело?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Далар Ткач Рассвета',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Возьми этот кодекс, отправляйся на север, к Гробнице, и найди там Далара Ткача Рассвета. Когда-то Далар был верховным магом Кирин-Тора. Он наверняка сумеет снять защитные чары с кодекса и открыть нам все его секреты.$B$BПоспеши, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите кодекс Янтарной мельницы Далару Ткачу Рассвета в Гробницу в Серебряном бору.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Темная Госпожа ищет моей помощи? Разумеется, я помогу! Передай мне кодекс, мальчик.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да? В чем дело?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27477,'Огромный червь','К северу отсюда и к западу от Северного Дола обитает огромный червь Мерзкослиз.$B$BЭто чудовище уничтожило уже несколько наших отрядов. Он уже вырос до невероятных размеров... И чем больше он ест, тем больше становится...$B$BЕсли эта тварь сожрет и тебя, я плакать не стану, но лучше ты все-таки прикончи его.','Идите в северные пустоши Восточных Чумных земель, найдите там Мерзкослиза и убейте.','Поговорите с Гамеллой Шарабан в Восточной башне в Восточных Чумных землях.','Ты – мой ужин.','Мерзкослиз') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Огромный червь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','К северу отсюда и к западу от Северного Дола обитает огромный червь Мерзкослиз.$B$BЭто чудовище уничтожило уже несколько наших отрядов. Он уже вырос до невероятных размеров... И чем больше он ест, тем больше становится...$B$BЕсли эта тварь сожрет и тебя, я плакать не стану, но лучше ты все-таки прикончи его.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Идите в северные пустоши Восточных Чумных земель, найдите там Мерзкослиза и убейте.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Гамеллой Шарабан в Восточной башне в Восточных Чумных землях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Ты – мой ужин.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Мерзкослиз',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27478,'Хранитель реликвий Релиос','Темная Госпожа знает, что говорит. Я действительно могу открыть кодекс. К несчастью, для этого необходим перстень-печатка верховного мага Даларана. У меня был свой собственный перстень, но его давным-давно забрали – когда я умер. Однако не будем терять надежды.$B$BХотя Даларан поднялся в небеса, предместья города остались на прежнем месте. Далеко на востоке до сих пор сохранились руины Даларана. Там ты найдешь верховного мага по имени Релиос. "Забери" его перстень-печатку и принеси мне.$B$BК кратеру доберешься через портал у меня за спиной.','Разыщите перстень-печатку верховного мага Даларана.','Вернитесь к Далару Ткачу Рассвета в Гробницу в Серебряном бору через портал в кратере Даларана.','У Релиоса есть перстень-печатка.','Хранитель реликвий Релиос') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хранитель реликвий Релиос',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Темная Госпожа знает, что говорит. Я действительно могу открыть кодекс. К несчастью, для этого необходим перстень-печатка верховного мага Даларана. У меня был свой собственный перстень, но его давным-давно забрали – когда я умер. Однако не будем терять надежды.$B$BХотя Даларан поднялся в небеса, предместья города остались на прежнем месте. Далеко на востоке до сих пор сохранились руины Даларана. Там ты найдешь верховного мага по имени Релиос. "Забери" его перстень-печатку и принеси мне.$B$BК кратеру доберешься через портал у меня за спиной.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите перстень-печатку верховного мага Даларана.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Далару Ткачу Рассвета в Гробницу в Серебряном бору через портал в кратере Даларана.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','У Релиоса есть перстень-печатка.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Хранитель реликвий Релиос',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27479,'Праведный гнев','Моходеры Зул\'Машар плюют в лицо Света! Они каннибалы, вандалы – от них одни лишь беды и горести! Тебе следует лишить их глаз, дабы настал их смертный час!$B$BИди на север, обрушь на них праведный гнев, верши над ними правосудие. $n, тебе надлежит стать карающей дланью Света.','Идите в Зул\'Машар и наберите 30 глаз троллей из племени Моходеров.','О, аллилуйя! Славь свет, брат!','<Служитель Андаал поглощен молитвой.>','Поговорите со служителем Андаалом в Восточной башне в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Праведный гнев',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Моходеры Зул\'Машар плюют в лицо Света! Они каннибалы, вандалы – от них одни лишь беды и горести! Тебе следует лишить их глаз, дабы настал их смертный час!$B$BИди на север, обрушь на них праведный гнев, верши над ними правосудие. $n, тебе надлежит стать карающей дланью Света.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Идите в Зул\'Машар и наберите 30 глаз троллей из племени Моходеров.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, аллилуйя! Славь свет, брат!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Служитель Андаал поглощен молитвой.>',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите со служителем Андаалом в Восточной башне в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27480,'Подземная энергия','Этот сгусток тайной магии источает странную энергию. Надо бы поискать еще. Далар наверняка заинтересуется такой находкой.','Найдите 8 сгустков тайной магии.','Вернитесь к Далару Ткачу Рассвета в Гробницу в Серебряном бору через портал в кратере Даларана.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подземная энергия',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этот сгусток тайной магии источает странную энергию. Надо бы поискать еще. Далар наверняка заинтересуется такой находкой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите 8 сгустков тайной магии.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Далару Ткачу Рассвета в Гробницу в Серебряном бору через портал в кратере Даларана.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27481,'Прочь из зиккурата!','$n, я хочу попросить тебя об услуге.$B$BК северу от Восточной башни, среди холмов спрятался город Зул\'Машар, столица Моходеров. Там я родился, там и умер.$B$BНа зиккурате Зул\'Машара засел предатель Молот\'джин. Это я должен был быть там, я должен был править городом – но он отнял у меня власть с помощью козней и лжи. Но у него мало сил. Он слаб.$B$BМы с тобой встретимся в Зул\'Машаре и убьем его. Ты и я. Вместе.','Добудьте тело полководца Молот\'джина.','Поговорите с Векс\'тулом в Восточной башне в Восточных Чумных землях.','Молот\'джин – настоящее чудовище. Ради забавы он убивает даже своих сородичей.','Полководец Молот\'джин') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прочь из зиккурата!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, я хочу попросить тебя об услуге.$B$BК северу от Восточной башни, среди холмов спрятался город Зул\'Машар, столица Моходеров. Там я родился, там и умер.$B$BНа зиккурате Зул\'Машара засел предатель Молот\'джин. Это я должен был быть там, я должен был править городом – но он отнял у меня власть с помощью козней и лжи. Но у него мало сил. Он слаб.$B$BМы с тобой встретимся в Зул\'Машаре и убьем его. Ты и я. Вместе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте тело полководца Молот\'джина.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Векс\'тулом в Восточной башне в Восточных Чумных землях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Молот\'джин – настоящее чудовище. Ради забавы он убивает даже своих сородичей.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Полководец Молот\'джин',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27482,'В самое пекло','$n, ты видишь меня в последний раз. Я покидаю караван.$B$BЕсли хочешь и дальше сражаться вместе со мной, сохрани тело Молот\'джина. Я подожду. А когда решишь, что пора прощаться, брось тело в огонь, который горит на вершине зиккурата Зул\'Машара.$B$BСпасибо, $n. Ты прекрасный союзник.','Когда вы будете готовы расстаться с Векс\'тулом, бросьте тело полководца Молот\'джина в огонь, горящий на вершине зиккурата Зул\'Машара.','Вернитесь к Фионе в Восточную башню в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В самое пекло',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, ты видишь меня в последний раз. Я покидаю караван.$B$BЕсли хочешь и дальше сражаться вместе со мной, сохрани тело Молот\'джина. Я подожду. А когда решишь, что пора прощаться, брось тело в огонь, который горит на вершине зиккурата Зул\'Машара.$B$BСпасибо, $n. Ты прекрасный союзник.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Когда вы будете готовы расстаться с Векс\'тулом, бросьте тело полководца Молот\'джина в огонь, горящий на вершине зиккурата Зул\'Машара.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фионе в Восточную башню в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27483,'Практичная месть','По натуре я не мстителен. И вообще, можно сказать, прагматик. А практичность, знаешь ли, никак не вяжется с мстительностью. Все планы мести, как правило, на удивление непрактичны.$B$BНО... в данном случае, раз ты и так направляешься к руинам Даларана, по пути можешь прикончить всех, кто тебе там встретится. Причины, по которым я желаю им смерти, самые разные: гнев, ненависть, предательство... И уверяю, все эти причины довольно весомые. Выполни мою просьбу, и я хорошо тебе заплачу.','Убейте 12 любых людей из Даларана.','Я был уверен, что когда умрет дюжина злейших врагов, моя душа избавится от тяжкого бремени. Но, увы, я ничего не чувствую. Возможно, я психопат.','Вернитесь к Далару Ткачу Рассвета в Гробницу в Серебряном бору через портал в кратере Даларана.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Практичная месть',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','По натуре я не мстителен. И вообще, можно сказать, прагматик. А практичность, знаешь ли, никак не вяжется с мстительностью. Все планы мести, как правило, на удивление непрактичны.$B$BНО... в данном случае, раз ты и так направляешься к руинам Даларана, по пути можешь прикончить всех, кто тебе там встретится. Причины, по которым я желаю им смерти, самые разные: гнев, ненависть, предательство... И уверяю, все эти причины довольно весомые. Выполни мою просьбу, и я хорошо тебе заплачу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 любых людей из Даларана.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я был уверен, что когда умрет дюжина злейших врагов, моя душа избавится от тяжкого бремени. Но, увы, я ничего не чувствую. Возможно, я психопат.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Далару Ткачу Рассвета в Гробницу в Серебряном бору через портал в кратере Даларана.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (27484,'Войти сможет только один','<Далар листает кодекс.>$B$BХа-ха-ха!$B$BТак... уже хуже.$B$B<Далар закрывает кодекс и пристально смотрит на вас.>$B$BС этим перстнем только ОДИН индивид сможет войти в карман измерений у Янтарной мельницы. А тому, кто войдет, надо будет сразиться с целой армией магов – и убить верховного мага, генерирующего поле изнутри. Только тогда измерение свернется и извергнет всех магов.$B$BПортал находится в дальнем конце пещеры в Погибели Берена.$B$BЭто все, что я знаю. А теперь верни перстень Сильване.','Возвращайтесь на Передовую Отрекшихся в Серебряном бору и отдайте леди Сильване Ветрокрылой перстень-печатку верховного мага Даларана.','Войти сможет только один? Ну что же... у меня как раз на примете подходящая кандидатура.$B$B<Сильвана кивком указывает на вас.>$B$BА я займусь подготовкой войска. Моя армия может ударить в любую минуту.','Что тебе удалось узнать?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Войти сможет только один',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Далар листает кодекс.>$B$BХа-ха-ха!$B$BТак... уже хуже.$B$B<Далар закрывает кодекс и пристально смотрит на вас.>$B$BС этим перстнем только ОДИН индивид сможет войти в карман измерений у Янтарной мельницы. А тому, кто войдет, надо будет сразиться с целой армией магов – и убить верховного мага, генерирующего поле изнутри. Только тогда измерение свернется и извергнет всех магов.$B$BПортал находится в дальнем конце пещеры в Погибели Берена.$B$BЭто все, что я знаю. А теперь верни перстень Сильване.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возвращайтесь на Передовую Отрекшихся в Серебряном бору и отдайте леди Сильване Ветрокрылой перстень-печатку верховного мага Даларана.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Войти сможет только один? Ну что же... у меня как раз на примете подходящая кандидатура.$B$B<Сильвана кивком указывает на вас.>$B$BА я займусь подготовкой войска. Моя армия может ударить в любую минуту.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что тебе удалось узнать?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27485,'Теплый прием','Я рад, что Лира тебя не напугала. В общем, она права: ее страхи не беспочвенны, но, возможно, она преувеличивает. Ведь, в конце концов, у нас общий враг.','Поговорите с Каленом на Гранатовом редуте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Теплый прием',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я рад, что Лира тебя не напугала. В общем, она права: ее страхи не беспочвенны, но, возможно, она преувеличивает. Ведь, в конце концов, у нас общий враг.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Каленом на Гранатовом редуте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27486,'Теплый прием','Я рад, что Лира тебя не напугала. В общем, она права: ее страхи не беспочвенны, но, возможно, она преувеличивает. Ведь, в конце концов, у нас общий враг.','Поговорите с Каленом на Гранатовом редуте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Теплый прием',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я рад, что Лира тебя не напугала. В общем, она права: ее страхи не беспочвенны, но, возможно, она преувеличивает. Ведь, в конце концов, у нас общий враг.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Каленом на Гранатовом редуте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27487,'Икс\'лар Владыка Подземелий','Я знаю, что мы должны отправиться в Северный Дол, но ведь это может подождать, верно? Кроме того, этот симпатичный маленький гоблин только что сказал, что воинов Плети можно встретить и гораздо ближе.$B$BПохоже, тут обитает какой-то владыка подземелий по имени Икс\'лар, который пытается утвердиться здесь с тех пор, как погиб Король-лич. Этот Икс\'лар со своей нежитью разбил лагерь к северу отсюда.$B$BДа, конечно, Тиросс хочет, чтобы мы уничтожали банши в Северном Доле. И мы непременно этим займемся. Но давай сначала ликвидируем этого нерубийца, раз уж он поблизости!','Убейте Икс\'лара Владыку Подземелий и 10 его приспешников.','Мне не удалось его остановить. Пока вас с Таренаром не было, Гидди отправился на север – один!$B$BТаренар, ты должен был предусмотреть это! Гидвин такой нетерпеливый, а ты еще все время его подзадориваешь! Если он попал в беду, это все твоя вина.','Поговорите с Фионой в Восточной башне в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Икс\'лар Владыка Подземелий',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я знаю, что мы должны отправиться в Северный Дол, но ведь это может подождать, верно? Кроме того, этот симпатичный маленький гоблин только что сказал, что воинов Плети можно встретить и гораздо ближе.$B$BПохоже, тут обитает какой-то владыка подземелий по имени Икс\'лар, который пытается утвердиться здесь с тех пор, как погиб Король-лич. Этот Икс\'лар со своей нежитью разбил лагерь к северу отсюда.$B$BДа, конечно, Тиросс хочет, чтобы мы уничтожали банши в Северном Доле. И мы непременно этим займемся. Но давай сначала ликвидируем этого нерубийца, раз уж он поблизости!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Икс\'лара Владыку Подземелий и 10 его приспешников.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мне не удалось его остановить. Пока вас с Таренаром не было, Гидди отправился на север – один!$B$BТаренар, ты должен был предусмотреть это! Гидвин такой нетерпеливый, а ты еще все время его подзадориваешь! Если он попал в беду, это все твоя вина.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Фионой в Восточной башне в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27488,'Нетерпение','Будь проклят этот дворф. Вечно он настраивает Фиону против меня. Ты только посмотри на нее! Она со мной даже не желает разговаривать!$B$BЯ останусь здесь и постараюсь восстановить дружеские отношения с нашей подругой-воргеном. Может, ты пока найдешь Гидвина и убедишься, что с ним все в порядке? Я почти уверен, что это так, ведь он может постоять за себя. Он отправился на север и, наверно, еще не ушел слишком далеко.','Найдите Гидвина Златокоса в Северном Доле.','Тебе не удалось его найти? Куда же он мог подеваться?$B$BЕго... его молитвенник! Почему он его оставил?$B$BОй...$B$BСвет милосердный, что же я наделал?','В Северном Доле обитает всего лишь пара призраков и банши. Старина Гидди легко с ними справится.','Поговорите с Таренаром Ударом Солнца в Восточной башне в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нетерпение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Будь проклят этот дворф. Вечно он настраивает Фиону против меня. Ты только посмотри на нее! Она со мной даже не желает разговаривать!$B$BЯ останусь здесь и постараюсь восстановить дружеские отношения с нашей подругой-воргеном. Может, ты пока найдешь Гидвина и убедишься, что с ним все в порядке? Я почти уверен, что это так, ведь он может постоять за себя. Он отправился на север и, наверно, еще не ушел слишком далеко.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Гидвина Златокоса в Северном Доле.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебе не удалось его найти? Куда же он мог подеваться?$B$BЕго... его молитвенник! Почему он его оставил?$B$BОй...$B$BСвет милосердный, что же я наделал?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','В Северном Доле обитает всего лишь пара призраков и банши. Старина Гидди легко с ними справится.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Таренаром Ударом Солнца в Восточной башне в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27489,'Это моя вина','Это моя вина. Я... Я не обращал внимания на его предупреждения, на жалобы, на все остальное. Я ничего не мог поделать – воины Плети были совсем рядом с башней, и я... ДОЛЖЕН был убить их.$B$BАргус говорит, что Гидвина повели на северо-запад. Это наша единственная зацепка, так что туда мы и отправимся.$B$BБудь прокляты Северный Дол и Серебряный Авангард! Ничего, мы вырвем Гидвина из лап этого отребья.','Присоединяйтесь к каравану Фионы и отправляйтесь в башню Северного перевала.','Поговорите с Таренаром Ударом Солнца в башне Северного перевала в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Это моя вина',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это моя вина. Я... Я не обращал внимания на его предупреждения, на жалобы, на все остальное. Я ничего не мог поделать – воины Плети были совсем рядом с башней, и я... ДОЛЖЕН был убить их.$B$BАргус говорит, что Гидвина повели на северо-запад. Это наша единственная зацепка, так что туда мы и отправимся.$B$BБудь прокляты Северный Дол и Серебряный Авангард! Ничего, мы вырвем Гидвина из лап этого отребья.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Присоединяйтесь к каравану Фионы и отправляйтесь в башню Северного перевала.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Таренаром Ударом Солнца в башне Северного перевала в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27490,'Высадка ШРУ','Сюда прибыли Матиас Шоу и агенты ШРУ, чтобы помочь нам проводить операции на Сумеречной крепости. А твоя задача – сопроводить их туда.$B$BГромовой Молот оказал нам большую услугу, согласившись предоставить нам своих грифонов. Правда, сначала агенты ШРУ должны разобраться кое с какими делами в районе Сумеречных врат. $B$BПоговори с Ангусом Тихой Горой и возьми отряд. Затем доставь отряд к месту высадки – оно отмечено большим синим крестом.','Попросите грифонов Громового Молота у Ангуса Тихой Горы и сопроводите агентов ШРУ к точке высадки у Сумеречных врат.','Жутковатая, должно быть, была работенка.$B$BЯ не одобряю методы ШРУ, но мастер Матиас Шоу и его агенты действуют очень эффективно, это у них не отнимешь. Не говоря уже о том, что ты тоже здесь. Теперь победа нам практически гарантирована.','Вернитесь в Лагерь Победителя на Сумеречном нагорье и поговорите с Кассием Белым.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Высадка ШРУ',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сюда прибыли Матиас Шоу и агенты ШРУ, чтобы помочь нам проводить операции на Сумеречной крепости. А твоя задача – сопроводить их туда.$B$BГромовой Молот оказал нам большую услугу, согласившись предоставить нам своих грифонов. Правда, сначала агенты ШРУ должны разобраться кое с какими делами в районе Сумеречных врат. $B$BПоговори с Ангусом Тихой Горой и возьми отряд. Затем доставь отряд к месту высадки – оно отмечено большим синим крестом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Попросите грифонов Громового Молота у Ангуса Тихой Горы и сопроводите агентов ШРУ к точке высадки у Сумеречных врат.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Жутковатая, должно быть, была работенка.$B$BЯ не одобряю методы ШРУ, но мастер Матиас Шоу и его агенты действуют очень эффективно, это у них не отнимешь. Не говоря уже о том, что ты тоже здесь. Теперь победа нам практически гарантирована.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь в Лагерь Победителя на Сумеречном нагорье и поговорите с Кассием Белым.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27491,'Высадка кор\'кронов','Сюда прибыли Гарона и отряд кор\'кронов, чтобы помочь нам проводить операции у Сумеречной крепости. А твоя задача – проводить их сюда.$B$BЯ обратилась за помощью к местному племени троллей, и они согласились подбросить нас. Правда, сначала убийцы должны разобраться кое с какими делами в районе Сумеречных врат. $B$BПоговори с вождем троллей, Джоном-Джоном Холодцом, и возьми отряд кор\'кронов. Затем доставь отряд к месту высадки – оно отмечено большим красным крестом.','Это, наверное, было просто захватывающе!$B$BДаже если какие-то кор\'кроны и погибли в пути, оставшиеся будут действовать быстро и эффективно, как и Гарона. Не говоря уже о том, что ты тоже здесь. Теперь победа нам практически гарантирована.','Вернитесь в Тукмак, что на Сумеречном нагорье, и поговорите с леди Козвинн.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Высадка кор\'кронов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сюда прибыли Гарона и отряд кор\'кронов, чтобы помочь нам проводить операции у Сумеречной крепости. А твоя задача – проводить их сюда.$B$BЯ обратилась за помощью к местному племени троллей, и они согласились подбросить нас. Правда, сначала убийцы должны разобраться кое с какими делами в районе Сумеречных врат. $B$BПоговори с вождем троллей, Джоном-Джоном Холодцом, и возьми отряд кор\'кронов. Затем доставь отряд к месту высадки – оно отмечено большим красным крестом.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это, наверное, было просто захватывающе!$B$BДаже если какие-то кор\'кроны и погибли в пути, оставшиеся будут действовать быстро и эффективно, как и Гарона. Не говоря уже о том, что ты тоже здесь. Теперь победа нам практически гарантирована.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь в Тукмак, что на Сумеречном нагорье, и поговорите с леди Козвинн.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27492,'Огры и эттины','Перед началом наступления нужно немного уменьшить численность войск противника. Правда, нам никак не удается подобраться к ним, но вот ты... ну, скажу лишь, что ты можешь пойти на юго-запад, проникнуть к Сумеречным вратам и проучить огров и эттинов из клана Кровавого Глаза!','Убейте 10 огров или эттинов у Сумеречных врат.','Молодчина, девочка! Похоже, сегодня будет хороший день.','Вернитесь в Лагерь Победителя на Сумеречном нагорье и поговорите с Курдраном Громовым Молотом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Огры и эттины',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Перед началом наступления нужно немного уменьшить численность войск противника. Правда, нам никак не удается подобраться к ним, но вот ты... ну, скажу лишь, что ты можешь пойти на юго-запад, проникнуть к Сумеречным вратам и проучить огров и эттинов из клана Кровавого Глаза!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 огров или эттинов у Сумеречных врат.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Молодчина, девочка! Похоже, сегодня будет хороший день.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь в Лагерь Победителя на Сумеречном нагорье и поговорите с Курдраном Громовым Молотом.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27493,'Огры и эттины','Твоя задача – пробраться за эти валуны на северо-западе и попасть к Сумеречным вратам. Убей всех огров и эттинов из клана Кровавого Глаза, которых встретишь. Ну что, это тебе по плечу, а, $n?','Убейте 10 огров или эттинов из клана Кровавого Глаза у Сумеречных врат.','А я-то думала, что хорошие новости на сегодня закончились.$B$BИногда мне даже нравится ошибаться!','Вернитесь в Тукмак, что на Сумеречном нагорье, и поговорите с полководцем Зелой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Огры и эттины',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Твоя задача – пробраться за эти валуны на северо-западе и попасть к Сумеречным вратам. Убей всех огров и эттинов из клана Кровавого Глаза, которых встретишь. Ну что, это тебе по плечу, а, $n?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 огров или эттинов из клана Кровавого Глаза у Сумеречных врат.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А я-то думала, что хорошие новости на сегодня закончились.$B$BИногда мне даже нравится ошибаться!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь в Тукмак, что на Сумеречном нагорье, и поговорите с полководцем Зелой.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27494,'Двигая горы','Если мы хотим взять Сумеречные врата, нам нужно убрать оттуда Дробителя Черепов Горобраза!$B$BЯ видел, что агенты ШРУ прихватили с собой ящик со знаками Сумеречного Молота. В нем находилась взрывчатка. Думаю, они уже положили ее на лестницу, ведущую на вершину крепости.$B$BТвоя задача – взорвать заряд и подать нам сигнал, что монстр вышел из игры.$B$BТогда мы нападем и перебьем всех остальных врагов!','Взорвите спрятанную взрывчатку, чтобы выманить Дробителя Черепов Горобраза из Сумеречных врат.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Двигая горы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если мы хотим взять Сумеречные врата, нам нужно убрать оттуда Дробителя Черепов Горобраза!$B$BЯ видел, что агенты ШРУ прихватили с собой ящик со знаками Сумеречного Молота. В нем находилась взрывчатка. Думаю, они уже положили ее на лестницу, ведущую на вершину крепости.$B$BТвоя задача – взорвать заряд и подать нам сигнал, что монстр вышел из игры.$B$BТогда мы нападем и перебьем всех остальных врагов!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Взорвите спрятанную взрывчатку, чтобы выманить Дробителя Черепов Горобраза из Сумеречных врат.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27495,'Двигая горы','Если мы хотим взять Сумеречные врата, нам нужно убрать оттуда Дробителя Черепов Горобраза!$B$BПеред уходом кор\'кронов я вручила им взрывчатку, спрятанную в ящике со знаками Сумеречного Молота. Думаю, они уже положили ее на лестницу, ведущую на вершину крепости.$B$BТвоя задача – взорвать заряд и подать нам сигнал, что монстр вышел из игры.$B$BТогда мы нападем и перебьем всех остальных врагов!','Взорвите спрятанную взрывчатку, чтобы выманить Дробителя Черепов Горобраза из Сумеречных врат.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Двигая горы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если мы хотим взять Сумеречные врата, нам нужно убрать оттуда Дробителя Черепов Горобраза!$B$BПеред уходом кор\'кронов я вручила им взрывчатку, спрятанную в ящике со знаками Сумеречного Молота. Думаю, они уже положили ее на лестницу, ведущую на вершину крепости.$B$BТвоя задача – взорвать заряд и подать нам сигнал, что монстр вышел из игры.$B$BТогда мы нападем и перебьем всех остальных врагов!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Взорвите спрятанную взрывчатку, чтобы выманить Дробителя Черепов Горобраза из Сумеречных врат.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27496,'Работа для артиллеристов','Я предпочитаю сражаться честно. Эти чудовища заслужили гибель под ударами наших мечей. Однако данная ситуация требует особых мер.$B$BВозьми эту сигнальную ракету и отметь каждое из четырех зданий Сумеречных врат, находящихся к юго-западу отсюда. Об остальном позаботятся наши пушки.','С помощью артиллерийской сигнальной ракеты отметьте северное, северо-восточное, юго-западное и южное здание Сумеречных врат.','Благодаря тебе наши канониры поразили цели. А теперь расскажи мне о том, как обстоят дела у Сумеречных врат.','Вернитесь в Лагерь Победителя на Сумеречном нагорье и поговорите с Кассием Белым.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Работа для артиллеристов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я предпочитаю сражаться честно. Эти чудовища заслужили гибель под ударами наших мечей. Однако данная ситуация требует особых мер.$B$BВозьми эту сигнальную ракету и отметь каждое из четырех зданий Сумеречных врат, находящихся к юго-западу отсюда. Об остальном позаботятся наши пушки.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','С помощью артиллерийской сигнальной ракеты отметьте северное, северо-восточное, юго-западное и южное здание Сумеречных врат.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Благодаря тебе наши канониры поразили цели. А теперь расскажи мне о том, как обстоят дела у Сумеречных врат.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь в Лагерь Победителя на Сумеречном нагорье и поговорите с Кассием Белым.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27497,'Работа для артиллеристов','Какая жалость, что нам больше не разрешают забрасывать врагов чумными бомбами. Ну да ладно. По крайней мере, у нас есть боевые машины.$B$BВозьми эту сигнальную ракету и подсвети каждое из четырех зданий Сумеречных врат, находящихся к северо-западу отсюда. Об остальном позаботятся наши боевые машины.','С помощью артиллерийской сигнальной ракеты отметьте северное, северо-восточное, юго-западное и южное здание Сумеречных врат.','Признаться, мне было приятно наблюдать за тем, как рушатся их здания.','Вернитесь в Тукмак, что на Сумеречном нагорье, и поговорите с леди Козвинн.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Работа для артиллеристов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Какая жалость, что нам больше не разрешают забрасывать врагов чумными бомбами. Ну да ладно. По крайней мере, у нас есть боевые машины.$B$BВозьми эту сигнальную ракету и подсвети каждое из четырех зданий Сумеречных врат, находящихся к северо-западу отсюда. Об остальном позаботятся наши боевые машины.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','С помощью артиллерийской сигнальной ракеты отметьте северное, северо-восточное, юго-западное и южное здание Сумеречных врат.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Признаться, мне было приятно наблюдать за тем, как рушатся их здания.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь в Тукмак, что на Сумеречном нагорье, и поговорите с леди Козвинн.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27498,'Сигнал к атаке','Теперь, когда вам удалось выманить Дробителя Черепов Горобраза из Сумеречных врат, пора подать сигнал для наступления войск!','Подайте сигнал к атаке с вершины одной из башен Сумеречных врат.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сигнал к атаке',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда вам удалось выманить Дробителя Черепов Горобраза из Сумеречных врат, пора подать сигнал для наступления войск!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Подайте сигнал к атаке с вершины одной из башен Сумеречных врат.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27499,'Сигнал к атаке','Теперь, когда вам удалось выманить Дробителя Черепов Горобраза из Сумеречных врат, пора подать сигнал для наступления войск!','Подайте сигнал к атаке с вершины одной из башен Сумеречных врат.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сигнал к атаке',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда вам удалось выманить Дробителя Черепов Горобраза из Сумеречных врат, пора подать сигнал для наступления войск!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Подайте сигнал к атаке с вершины одной из башен Сумеречных врат.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27500,'Без головы хорошо, а с четырьмя – лучше','Теперь, когда атака на Сумеречные врата началась, осталось разобраться с За\'броксом и Библи\'фодом, учениками Чо\'Галла.$B$BПо данным разведки, они находятся в Пещере учеников, небольшом логове, принадлежащем ограм, которое расположено на юго-западе Сумеречных врат.$B$BОчень вероятно, что Кассий и Курдран захотят получить доказательства их смерти.','Добудьте четыре головы За\'брокса и Библи\'фода.','<Паладин хмурится.>$B$BКакая жуткая коллекция трофеев! Тебе не нужно было доказывать, что они мертвы, я бы поверил тебе на слово. Но, как бы то ни было, спасибо тебе.$B$BСкоро Сумеречные врата станут нашими. Пора идти на Сумеречную крепость!','Что это течет из твоего мешка? Кровь?','Вернитесь в Лагерь Победителя на Сумеречном нагорье и поговорите с Кассием Белым.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Без головы хорошо, а с четырьмя – лучше',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда атака на Сумеречные врата началась, осталось разобраться с За\'броксом и Библи\'фодом, учениками Чо\'Галла.$B$BПо данным разведки, они находятся в Пещере учеников, небольшом логове, принадлежащем ограм, которое расположено на юго-западе Сумеречных врат.$B$BОчень вероятно, что Кассий и Курдран захотят получить доказательства их смерти.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте четыре головы За\'брокса и Библи\'фода.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Паладин хмурится.>$B$BКакая жуткая коллекция трофеев! Тебе не нужно было доказывать, что они мертвы, я бы поверил тебе на слово. Но, как бы то ни было, спасибо тебе.$B$BСкоро Сумеречные врата станут нашими. Пора идти на Сумеречную крепость!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что это течет из твоего мешка? Кровь?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь в Лагерь Победителя на Сумеречном нагорье и поговорите с Кассием Белым.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27501,'Без головы хорошо, а с четырьмя – лучше','Теперь, когда атака на Сумеречные врата началась, осталось разобраться с За\'броксом и Библи\'фодом, учениками Чо\'Галла.$B$BПо данным разведки, они находятся в Пещере учеников, небольшом логове, принадлежащем ограм, которое расположено на юго-западе Сумеречных врат.$B$BОчень вероятно, что Леди Козвинн и Зела захотят получить доказательства их смерти.','Добудьте четыре головы За\'брокса и Библи\'фода.','<Леди усмехается.>$B$BКакая жуткая коллекция трофеев! Тебе не нужно было доказывать, что они мертвы, я бы поверила тебе на слово. Но, как бы то ни было, спасибо тебе.$B$BСкоро Сумеречные врата станут нашими. Пора идти на Сумеречную крепость!','Что это течет из твоего мешка? Кровь? Надеюсь, она не твоя.','Вернитесь в Тукмак, что на Сумеречном нагорье, и поговорите с леди Козвинн.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Без головы хорошо, а с четырьмя – лучше',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда атака на Сумеречные врата началась, осталось разобраться с За\'броксом и Библи\'фодом, учениками Чо\'Галла.$B$BПо данным разведки, они находятся в Пещере учеников, небольшом логове, принадлежащем ограм, которое расположено на юго-западе Сумеречных врат.$B$BОчень вероятно, что Леди Козвинн и Зела захотят получить доказательства их смерти.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте четыре головы За\'брокса и Библи\'фода.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Леди усмехается.>$B$BКакая жуткая коллекция трофеев! Тебе не нужно было доказывать, что они мертвы, я бы поверила тебе на слово. Но, как бы то ни было, спасибо тебе.$B$BСкоро Сумеречные врата станут нашими. Пора идти на Сумеречную крепость!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что это течет из твоего мешка? Кровь? Надеюсь, она не твоя.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь в Тукмак, что на Сумеречном нагорье, и поговорите с леди Козвинн.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27502,'Штурм крепости','Теперь, когда атака началась, пришло время разобраться с Сумеречной крепостью. Если ты не против, то я попрошу тебя отвести агентов ШРУ к мастеру Матиасу Шоу.$B$BОн прячется где-то наверху. О его местонахождении тебе сообщит командир отряда ШРУ.$B$BСпасибо, $n. Встретимся во время штурма!','Поговорите с командиром отряда ШРУ, а затем сопровождайте отряд ШРУ.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Штурм крепости',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда атака началась, пришло время разобраться с Сумеречной крепостью. Если ты не против, то я попрошу тебя отвести агентов ШРУ к мастеру Матиасу Шоу.$B$BОн прячется где-то наверху. О его местонахождении тебе сообщит командир отряда ШРУ.$B$BСпасибо, $n. Встретимся во время штурма!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с командиром отряда ШРУ, а затем сопровождайте отряд ШРУ.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27503,'Штурм крепости','Теперь, когда атака началась, пришло время разобраться с Сумеречной крепостью. Если ты не против, то я попрошу тебя отвести воинов-кор\'кронов к Гароне.$B$BОна прячется где-то наверху. О ее местонахождении тебе сообщит кор\'кронский командир взвода.$B$BСпасибо, $n. Встретимся во время штурма!','Поговорите с кор\'кронским командиром взвода, а затем сопровождайте отряд кор\'кронов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Штурм крепости',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда атака началась, пришло время разобраться с Сумеречной крепостью. Если ты не против, то я попрошу тебя отвести воинов-кор\'кронов к Гароне.$B$BОна прячется где-то наверху. О ее местонахождении тебе сообщит кор\'кронский командир взвода.$B$BСпасибо, $n. Встретимся во время штурма!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с кор\'кронским командиром взвода, а затем сопровождайте отряд кор\'кронов.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (27504,'Драконам тоже больно','Если ты предлагаешь мне помощь, я не оскорблю тебя отказом.$B$BНа юге мы ведем бесконечную битву с сумеречными драконами. Нам удалось добиться некоторых успехов, но драконы Грим Батола дышат на нас какой-то порчей, и на очищение от нее уходит много времени.$B$BВеластраза и Пламегон ухаживают за нашими ранеными братьями. Предложи им свою помощь.','Кален стал очень доверчивым. Чужаков не часто пускают на редут.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Драконам тоже больно',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если ты предлагаешь мне помощь, я не оскорблю тебя отказом.$B$BНа юге мы ведем бесконечную битву с сумеречными драконами. Нам удалось добиться некоторых успехов, но драконы Грим Батола дышат на нас какой-то порчей, и на очищение от нее уходит много времени.$B$BВеластраза и Пламегон ухаживают за нашими ранеными братьями. Предложи им свою помощь.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Кален стал очень доверчивым. Чужаков не часто пускают на редут.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27505,'Исцеление драконов','Наши драконы возвращаются из боя, пораженные порчей дыхания сумеречных драконов и преследуемые ими.$B$BМои лекари могут исцелить драконов, но кто-то должен их защищать. Не дай драконам подобраться к лекарям. А если можешь, тоже принимай участие в лечении драконов.$B$BСпасибо за помощь. Битва за Грим Батол все не кончается, и поэтому нам нужно как можно быстрее вернуть в строй наших сильнейших драконов.','Охраняйте 5 гранатовых целителей, пока они лечат раненых драконов.','Мы отобьем Грим Батол у Сумеречного Молота и его союзников. На это понадобится время, но мы настроены чрезвычайно решительно.','Вернитесь на Гранатовый редут и поговорите с Веластразой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Исцеление драконов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наши драконы возвращаются из боя, пораженные порчей дыхания сумеречных драконов и преследуемые ими.$B$BМои лекари могут исцелить драконов, но кто-то должен их защищать. Не дай драконам подобраться к лекарям. А если можешь, тоже принимай участие в лечении драконов.$B$BСпасибо за помощь. Битва за Грим Батол все не кончается, и поэтому нам нужно как можно быстрее вернуть в строй наших сильнейших драконов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Охраняйте 5 гранатовых целителей, пока они лечат раненых драконов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мы отобьем Грим Батол у Сумеречного Молота и его союзников. На это понадобится время, но мы настроены чрезвычайно решительно.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь на Гранатовый редут и поговорите с Веластразой.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27506,'Круговорот жизни и смерти','$R, у меня к тебе дело.$B$BВозьми эти рубиновые семена и посади их в теле каждого мертвого дракона, которого найдешь. Сумеречного или гранатового, юного или взрослого – неважно. Нужно позаботиться о том, чтобы их тела вернулись в землю, чтобы жизнь продолжалась.$B$BПосле смерти начинается новая жизнь. Возможно, для кого-то это станет утешением в это время войн и больших трагедий.','Вернув прах драконов в землю, мы разрушим планы Смертокрыла, стремящегося сеять лишь смерть и разрушение. На этих останках зародится новая жизнь.','Вернитесь на Гранатовый редут и поговорите с Пламегоном.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Круговорот жизни и смерти',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$R, у меня к тебе дело.$B$BВозьми эти рубиновые семена и посади их в теле каждого мертвого дракона, которого найдешь. Сумеречного или гранатового, юного или взрослого – неважно. Нужно позаботиться о том, чтобы их тела вернулись в землю, чтобы жизнь продолжалась.$B$BПосле смерти начинается новая жизнь. Возможно, для кого-то это станет утешением в это время войн и больших трагедий.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вернув прах драконов в землю, мы разрушим планы Смертокрыла, стремящегося сеять лишь смерть и разрушение. На этих останках зародится новая жизнь.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь на Гранатовый редут и поговорите с Пламегоном.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27507,'Сумерки сгущаются','Редут штурмуют сумеречные драконы – захватчики. Они приходят откуда-то с запада.$B$BНельзя допустить, чтобы они захватили это святое место. Не щади их.','Я вижу, что ты умеешь убивать. В наше время твоим талантам найдется применение.','Вернитесь на Гранатовый редут и поговорите с Каленом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сумерки сгущаются',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Редут штурмуют сумеречные драконы – захватчики. Они приходят откуда-то с запада.$B$BНельзя допустить, чтобы они захватили это святое место. Не щади их.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я вижу, что ты умеешь убивать. В наше время твоим талантам найдется применение.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь на Гранатовый редут и поговорите с Каленом.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27508,'Далеко от гнезда','Послушай... Я знаю, у нас есть причины не любить друг друга – но сейчас мне нужна твоя помощь.$B$BСумеречные драконы – захватчики крадут наши яйца. Не сомневаюсь в том, что они хотят доставить их в Грим Батол для своих жутких экспериментов. Я НЕ ПОЗВОЛЮ этому произойти!$B$BЕсли ты в самом деле хочешь нам помочь, останови захватчиков! Забери яйца и принеси их мне.','Соберите 6 гранатовых яиц.','Я не знаю, ты делаешь это ради меня или ради малышей, сидящих в этих яйцах, но в конце концов – какая разница. Очевидно, что ты хочешь быть нашим союзником. Это мне по душе.$B$BЯ не могу простить твоих союзников, которые нападали на мой выводок, но сейчас ты сражаешься за правое дело.','В результате их отвратительных экспериментов на свет появились сумеречные драконы. Сумеречный Молот зашел слишком далеко. Смертокрыл зашел слишком далеко.','Вернитесь на Гранатовый редут и поговорите с Лирастразой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Далеко от гнезда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Послушай... Я знаю, у нас есть причины не любить друг друга – но сейчас мне нужна твоя помощь.$B$BСумеречные драконы – захватчики крадут наши яйца. Не сомневаюсь в том, что они хотят доставить их в Грим Батол для своих жутких экспериментов. Я НЕ ПОЗВОЛЮ этому произойти!$B$BЕсли ты в самом деле хочешь нам помочь, останови захватчиков! Забери яйца и принеси их мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 6 гранатовых яиц.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я не знаю, ты делаешь это ради меня или ради малышей, сидящих в этих яйцах, но в конце концов – какая разница. Очевидно, что ты хочешь быть нашим союзником. Это мне по душе.$B$BЯ не могу простить твоих союзников, которые нападали на мой выводок, но сейчас ты сражаешься за правое дело.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','В результате их отвратительных экспериментов на свет появились сумеречные драконы. Сумеречный Молот зашел слишком далеко. Смертокрыл зашел слишком далеко.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь на Гранатовый редут и поговорите с Лирастразой.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (27509,'Брешь в обороне','Драконы Лиры внимательно следят за тем, что происходит в воздухе и на холмах, окружающих редут. Должно быть, они пробрались в святилище под землей.$B$BВозьми эту пылинку быстрого роста. Ее должно с избытком хватить для того, чтобы закрыть любую дыру, туннель или портал.$B$BНайди брешь в нашей обороне и заделай ее.','Вернитесь на Гранатовый редут и поговорите с Каленом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Брешь в обороне',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Драконы Лиры внимательно следят за тем, что происходит в воздухе и на холмах, окружающих редут. Должно быть, они пробрались в святилище под землей.$B$BВозьми эту пылинку быстрого роста. Ее должно с избытком хватить для того, чтобы закрыть любую дыру, туннель или портал.$B$BНайди брешь в нашей обороне и заделай ее.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь на Гранатовый редут и поговорите с Каленом.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27510,'Волк в медвежьей шкуре','Воргены нас за дураков держат, что ли! Казалось бы, только идиот не сможет отличить друида в форме медведя от настоящего медведя; но, к сожалению, здесь, на Рубеже Отрекшихся, идиотов хватает. Уже несколько батальонов погибло в схватках с организованными группами воргенов. Да, это еще больший идиотизм, чем кажется.$B$BПрямо на восток отсюда, если идти к Хилсбраду, в лесах ошиваются воргены-друиды, притворяющиеся медведями. Убей их, чтобы нашей южной линии припасов больше ничто не угрожало.','Убейте 10 подозрительных медведей.','Будем надеяться, что их не начнут убивать неприметные птицы, кошки, деревья или тюлени. И откуда только такие усмешища берутся?','Вернитесь к верховному полководцу Кромушу на Рубеж Отрекшихся в Серебряном бору.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Волк в медвежьей шкуре',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Воргены нас за дураков держат, что ли! Казалось бы, только идиот не сможет отличить друида в форме медведя от настоящего медведя; но, к сожалению, здесь, на Рубеже Отрекшихся, идиотов хватает. Уже несколько батальонов погибло в схватках с организованными группами воргенов. Да, это еще больший идиотизм, чем кажется.$B$BПрямо на восток отсюда, если идти к Хилсбраду, в лесах ошиваются воргены-друиды, притворяющиеся медведями. Убей их, чтобы нашей южной линии припасов больше ничто не угрожало.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 подозрительных медведей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Будем надеяться, что их не начнут убивать неприметные птицы, кошки, деревья или тюлени. И откуда только такие усмешища берутся?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному полководцу Кромушу на Рубеж Отрекшихся в Серебряном бору.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27511,'Дрожь предвкушения','Вот это да! Всем находкам находка! И грабители сюда не добрались... все осталось нетронутым.$B$BСлушай, $n. Прежде чем мы тут сдвинем хотя бы один предмет, я хочу задокументировать это место таким, каким мы увидели его, как только вошли. Ты пока походи, осмотрись...$B$BУвидишь что-нибудь необычное, запоминай. Потом мне покажешь.$B$BИ пожалуйста... Я тебя очень прошу, постарайся ничего не сломать, хорошо?','Исследуйте Зал Звезд.','Поговорите с Харрисоном Джонсом в Зале Звезд.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дрожь предвкушения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот это да! Всем находкам находка! И грабители сюда не добрались... все осталось нетронутым.$B$BСлушай, $n. Прежде чем мы тут сдвинем хотя бы один предмет, я хочу задокументировать это место таким, каким мы увидели его, как только вошли. Ты пока походи, осмотрись...$B$BУвидишь что-нибудь необычное, запоминай. Потом мне покажешь.$B$BИ пожалуйста... Я тебя очень прошу, постарайся ничего не сломать, хорошо?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Исследуйте Зал Звезд.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Харрисоном Джонсом в Зале Звезд.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (27512,'<Сильвана вручает вам перстень.>$B$BВозьми перстень и отправляйся в Погибель Берена. Это на юго-востоке отсюда, в пещере в холмах. Когда прибудешь на место, обыщи пещеру и найди портал в карман измерений, где скрываются маги Янтарной мельницы.$B$BБудем держать с тобой мысленную связь, $n. Когда разыщешь портал, я скажу, что делать дальше.','Разыщите портал в другое измерение в Янтарной мельнице.','<У вас в голове звучит голос королевы банши.>$B$BДа, это он. Теперь проведи перстнем по рунам. Таким образом ты настроишься на переход между измерениями.','<Портал гудит.>','Поговорите с леди Сильваной Ветрокрылой на Рубеже Отрекшихся в Серебряном бору.','Перед вами возвышаются ворота.','Леди Сильвана Ветрокрылая') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Сильвана вручает вам перстень.>$B$BВозьми перстень и отправляйся в Погибель Берена. Это на юго-востоке отсюда, в пещере в холмах. Когда прибудешь на место, обыщи пещеру и найди портал в карман измерений, где скрываются маги Янтарной мельницы.$B$BБудем держать с тобой мысленную связь, $n. Когда разыщешь портал, я скажу, что делать дальше.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите портал в другое измерение в Янтарной мельнице.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<У вас в голове звучит голос королевы банши.>$B$BДа, это он. Теперь проведи перстнем по рунам. Таким образом ты настроишься на переход между измерениями.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Портал гудит.>',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с леди Сильваной Ветрокрылой на Рубеже Отрекшихся в Серебряном бору.',`completedtext_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Перед вами возвышаются ворота.',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Леди Сильвана Ветрокрылая',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (27513,'Уничтожьте 20 магов Янтарной мельницы.','Поговорите с леди Сильваной Ветрокрылой на Рубеже Отрекшихся в Серебряном бору.','Готовься к прыжку!','Леди Сильвана Ветрокрылая','Их трупы будут брошены в топку военной машины Отрекшихся!','Леди Сильвана Ветрокрылая') ON DUPLICATE KEY UPDATE `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 20 магов Янтарной мельницы.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с леди Сильваной Ветрокрылой на Рубеже Отрекшихся в Серебряном бору.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Готовься к прыжку!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Леди Сильвана Ветрокрылая',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Их трупы будут брошены в топку военной машины Отрекшихся!',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Леди Сильвана Ветрокрылая',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27514,'Птица подбита! Птица подбита!','Пока шел бой на берегу, к западу отсюда из-за облаков спустился грифон.$B$BИ он не был одним из наших.$B$BСкорее всего, принадлежал кому-то из Громового Молота. Мне известно, что Курдран очень хотел установить контакт с пропавшими кланами Громового Молота.$B$BЯ не могу отправить на разведку никого – никого, кроме тебя. Найди этого сбитого всадника на грифоне Громового Молота!','Найдите Тордуна Размаха Топора, сбитого всадника на грифоне Громового Молота, на Сумеречном берегу, что на Сумеречном нагорье.','Найдите Тордуна Размаха Топора, сбитого всадника на грифоне Громового Молота, в Сумеречной излучине, что на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Птица подбита! Птица подбита!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пока шел бой на берегу, к западу отсюда из-за облаков спустился грифон.$B$BИ он не был одним из наших.$B$BСкорее всего, принадлежал кому-то из Громового Молота. Мне известно, что Курдран очень хотел установить контакт с пропавшими кланами Громового Молота.$B$BЯ не могу отправить на разведку никого – никого, кроме тебя. Найди этого сбитого всадника на грифоне Громового Молота!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Тордуна Размаха Топора, сбитого всадника на грифоне Громового Молота, на Сумеречном берегу, что на Сумеречном нагорье.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Найдите Тордуна Размаха Топора, сбитого всадника на грифоне Громового Молота, в Сумеречной излучине, что на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27515,'Корешки ей помогут','Слушай, $gприятель:подруга;, она на последнем издыхании! А если умрет – мне конец.$B$BТак что давай, помогай. Здесь, на полуострове растет шипастый смердокорень. Запах у него такой, что с ног сшибает, но отвари его – и получишь отличное средство от любой хвори.$B$BСобери немного смердокорня, а я буду охранять птицу. И поторопись! Вы, клоуны из Альянса, любите тянуть кота за хвост, верно?','Соберите 8 шипастых смердокорней на Сумеречном берегу.','О да, это то, что нужно! Надеюсь, тебе не пришло в голову полакомиться этой штукой. От нее кишки болят – мама дорогая! А вот птичкам сильно помогает.','Вернитесь на Сумеречный берег на Сумеречном нагорье и отдайте корни Тордуну Размаху Топора.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Корешки ей помогут',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слушай, $gприятель:подруга;, она на последнем издыхании! А если умрет – мне конец.$B$BТак что давай, помогай. Здесь, на полуострове растет шипастый смердокорень. Запах у него такой, что с ног сшибает, но отвари его – и получишь отличное средство от любой хвори.$B$BСобери немного смердокорня, а я буду охранять птицу. И поторопись! Вы, клоуны из Альянса, любите тянуть кота за хвост, верно?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 шипастых смердокорней на Сумеречном берегу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О да, это то, что нужно! Надеюсь, тебе не пришло в голову полакомиться этой штукой. От нее кишки болят – мама дорогая! А вот птичкам сильно помогает.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь на Сумеречный берег на Сумеречном нагорье и отдайте корни Тордуну Размаху Топора.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27516,'Крылья над Высоким берегом','Смотри, смотри! Ей уже лучше.$B$BНу ладно, $gкрасавчик:красотка; из Альянса. Это твоя база вон там? Высокий берег, говоришь? Мы с моей птичкой можем переждать там, пока она не поправится?$B$BПрыгай! Полетим на Высокий берег вместе!','Поговорите с Тордуном Размахом Топора и полетите вместе с ним на Высокий берег.','Вернитесь на Высокий берег на Сумеречном нагорье и поговорите с Курдраном Громовым Молотом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Крылья над Высоким берегом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Смотри, смотри! Ей уже лучше.$B$BНу ладно, $gкрасавчик:красотка; из Альянса. Это твоя база вон там? Высокий берег, говоришь? Мы с моей птичкой можем переждать там, пока она не поправится?$B$BПрыгай! Полетим на Высокий берег вместе!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Тордуном Размахом Топора и полетите вместе с ним на Высокий берег.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь на Высокий берег на Сумеречном нагорье и поговорите с Курдраном Громовым Молотом.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27517,'Будь готов ко всему','Ни один уважающий себя путешественник – равно как и благоразумный искатель приключений – никогда не войдет в пещеру, подземелье или гробницу без мотка длинной крепкой веревки...$B$BВеревки много не бывает!$B$BВы решаете обыскать скелеты и собрать все обрывки веревки, какие найдутся.','Соберите 6 обрывков веревки.','А, веревка! Спасибо, малыш.$B$BЧто-то подсказывает, она мне скоро понадобится.','Что нашла, Михалкен?','Поговорите с Харрисоном Джонсом в Зале Звезд.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Будь готов ко всему',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ни один уважающий себя путешественник – равно как и благоразумный искатель приключений – никогда не войдет в пещеру, подземелье или гробницу без мотка длинной крепкой веревки...$B$BВеревки много не бывает!$B$BВы решаете обыскать скелеты и собрать все обрывки веревки, какие найдутся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 6 обрывков веревки.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, веревка! Спасибо, малыш.$B$BЧто-то подсказывает, она мне скоро понадобится.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что нашла, Михалкен?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Харрисоном Джонсом в Зале Звезд.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`completedtext_loc8`,`questgivertargetname_loc8`) VALUES (27518,'Вернитесь к леди Сильване Ветрокрылой на Рубеж Отрекшихся в Серебряном бору.','Леди Сильвана Ветрокрылая') ON DUPLICATE KEY UPDATE `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к леди Сильване Ветрокрылой на Рубеж Отрекшихся в Серебряном бору.',`completedtext_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Леди Сильвана Ветрокрылая',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27519,'Под зыбучими песками','Нет... Это невозможно.$B$BОрсис почти полностью погребен под зыбучими песками.$B$BНаш враг дорого заплатит за это.$B$BНо это потом – сначала нужно помочь моим людям. Поспеши, $n. Нельзя ждать, пока пески поглотят моих последних выживших товарищей!','Спасите 8 выживших горожан Орсиса.','Вернитесь к Аммантепу в Орсис в Ульдуме.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Под зыбучими песками',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нет... Это невозможно.$B$BОрсис почти полностью погребен под зыбучими песками.$B$BНаш враг дорого заплатит за это.$B$BНо это потом – сначала нужно помочь моим людям. Поспеши, $n. Нельзя ждать, пока пески поглотят моих последних выживших товарищей!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Спасите 8 выживших горожан Орсиса.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аммантепу в Орсис в Ульдуме.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27520,'Слуги Ал\'акира','Ал\'акир отдал своих приспешников в услужение Смертокрылу.$B$BНамек ясен. Либо мы с ними, либо нам конец.$B$BЯ пока не очень хорошо тебя знаю, |3-6($r). Но мне известно одно: если ты докажешь, что ты враг Ал\'акиру, тебе это зачтется.$B$BЧто скажешь, |3-6($c)?','Убейте 6 потомков Ал\'акира.','Вернитесь к принцу Надуну в Орсис, что в Удьдуме.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Слуги Ал\'акира',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ал\'акир отдал своих приспешников в услужение Смертокрылу.$B$BНамек ясен. Либо мы с ними, либо нам конец.$B$BЯ пока не очень хорошо тебя знаю, |3-6($r). Но мне известно одно: если ты докажешь, что ты враг Ал\'акиру, тебе это зачтется.$B$BЧто скажешь, |3-6($c)?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 6 потомков Ал\'акира.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к принцу Надуну в Орсис, что в Удьдуме.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27521,'Проклятое гнездо мерзавцев и негодяев','$R... пожалуйста, помоги мне.$B$BЧто-то случилось с моими родичами. Наш командир, предводитель следопытов Ястребиное Копье, нашел одну вещь, полную магической энергии, и мои друзья, моя семья... они все подпали под ее власть.$B$BЭта вещь наполнила их скверной, |3-6($r). Всех.$B$BМоя Эллария предпочла бы смерть такому существованию – да и братья тоже. Пожалуйста, избавь их от мучений. Сторожка Кель\'Литиен недалеко отсюда – сразу за холмом, к северо-западу.','Убейте 9 презренных в сторожке Кель\'Литиен в Восточных Чумных землях.','Не нужно меня жалеть. Те существа в сторожке Кель\'Литиен когда-то были моими друзьями – но это было очень давно.','Поговорите с Киркианом Рассветным Щитом в башне Северного перевала в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Проклятое гнездо мерзавцев и негодяев',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$R... пожалуйста, помоги мне.$B$BЧто-то случилось с моими родичами. Наш командир, предводитель следопытов Ястребиное Копье, нашел одну вещь, полную магической энергии, и мои друзья, моя семья... они все подпали под ее власть.$B$BЭта вещь наполнила их скверной, |3-6($r). Всех.$B$BМоя Эллария предпочла бы смерть такому существованию – да и братья тоже. Пожалуйста, избавь их от мучений. Сторожка Кель\'Литиен недалеко отсюда – сразу за холмом, к северо-западу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 9 презренных в сторожке Кель\'Литиен в Восточных Чумных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Не нужно меня жалеть. Те существа в сторожке Кель\'Литиен когда-то были моими друзьями – но это было очень давно.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Киркианом Рассветным Щитом в башне Северного перевала в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27522,'Выбей из них дурь','Нас, паладинов, учат держать себя в руках и сохранять хладнокровие в бою, но это особый случай – и, кроме того, я никогда не слушал учителей.$B$BЯ пойду в Чумной лес и выясню, что стало с Гидди. А ты разберись со слугами Плети, которые находятся к северо-востоку отсюда, за этой башней. Нежить не боится смерти, но если избить этих мертвяков как следует, то они могут проболтаться, где сейчас находится Гидвин.','Избейте не менее 6 инженеров Плети, чтобы выяснить, кто похитил Гидвина и где он сейчас находится.','Надеюсь, тебе удалось добыть сведения, которые помогут нам найти Гидвина.','Поговорите с Фионой в башне Северного перевала в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Выбей из них дурь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нас, паладинов, учат держать себя в руках и сохранять хладнокровие в бою, но это особый случай – и, кроме того, я никогда не слушал учителей.$B$BЯ пойду в Чумной лес и выясню, что стало с Гидди. А ты разберись со слугами Плети, которые находятся к северо-востоку отсюда, за этой башней. Нежить не боится смерти, но если избить этих мертвяков как следует, то они могут проболтаться, где сейчас находится Гидвин.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Избейте не менее 6 инженеров Плети, чтобы выяснить, кто похитил Гидвина и где он сейчас находится.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Надеюсь, тебе удалось добыть сведения, которые помогут нам найти Гидвина.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Фионой в башне Северного перевала в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27523,'Проклятый Тенекрыл','Мне многое пришлось повидать на своем веку, |3-6($r). Горы Хиджала... странности Запределья... стену солдат Плети, идущих на войну. Но я никогда еще не видел таких больших и таких невероятно белых летучих мышей, как Тенекрыл.$B$BКак он смеется надо мной со своего насеста!$B$BЭтот демон, эта летучая мышь-альбинос кружит к юго-западу отсюда, прямо на севере от озера Чернолесья. Выследи и убей его. Если он будет летать слишком высоко, примани его с помощью моей осветительной ракеты.','Добудьте полоску меха Тенекрыла.','Отлично. Теперь эта огромная белая тварь не помешает мне.$B$BЯ сошью из ее шкуры что-нибудь полезное для тебя.','Надеюсь, тебе удалось разобраться с этой тварью.','Поговорите с крематором Тимом в башне Северного перевала в Восточных Чумных землях.','Как он смеется надо мной со своего насеста!','Тенекрыл') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Проклятый Тенекрыл',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне многое пришлось повидать на своем веку, |3-6($r). Горы Хиджала... странности Запределья... стену солдат Плети, идущих на войну. Но я никогда еще не видел таких больших и таких невероятно белых летучих мышей, как Тенекрыл.$B$BКак он смеется надо мной со своего насеста!$B$BЭтот демон, эта летучая мышь-альбинос кружит к юго-западу отсюда, прямо на севере от озера Чернолесья. Выследи и убей его. Если он будет летать слишком высоко, примани его с помощью моей осветительной ракеты.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте полоску меха Тенекрыла.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично. Теперь эта огромная белая тварь не помешает мне.$B$BЯ сошью из ее шкуры что-нибудь полезное для тебя.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Надеюсь, тебе удалось разобраться с этой тварью.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с крематором Тимом в башне Северного перевала в Восточных Чумных землях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Как он смеется надо мной со своего насеста!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Тенекрыл',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27524,'Слепая ярость','Таренар не шутил, когда сказал, что ему наплевать на осторожность и здравомыслие. Когда он бросился в Чумной лес на поиски Гидвина, то чуть не оторвал голову тому эльфу. Тебе нужно пойти вслед за ним.$B$BЧумной лес велик, $n. Так что удачи тебе. Надеюсь увидеть всех вас в добром здравии.','Найдите Таренара Удар Солнца в Чумном лесу в Восточных Чумных землях.','Все, что я нашел, только толпу безмозглой нежити. Я уже собирался проложить себе дорогу в Стратхольм своим мечом.$B$BА как твои успехи?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Слепая ярость',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Таренар не шутил, когда сказал, что ему наплевать на осторожность и здравомыслие. Когда он бросился в Чумной лес на поиски Гидвина, то чуть не оторвал голову тому эльфу. Тебе нужно пойти вслед за ним.$B$BЧумной лес велик, $n. Так что удачи тебе. Надеюсь увидеть всех вас в добром здравии.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Таренара Удар Солнца в Чумном лесу в Восточных Чумных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Все, что я нашел, только толпу безмозглой нежити. Я уже собирался проложить себе дорогу в Стратхольм своим мечом.$B$BА как твои успехи?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27525,'Стражи Стратхольма','Его схватила баронесса Анастари? Здесь, в Чумном лесу?$B$BЧумной лес велик... но мы обязательно найдем Гидвина. Мы НАЙДЕМ его.$B$BСовсем недалеко отсюда, на северо-западе находятся два некрополя, стоящие по обеим сторонам от входа в Стратхольм. В них ты найдешь пару рыцарей смерти – помощников Ривендера. Я сомневаюсь в том, чтобы кому-то из них пригодился бы заложник-паладин – но, возможно, им известно, где он сейчас.','Убейте Омасума Гнилое Копыто и Картиса Темную Руну.','Мы должны идти дальше! Цель уже совсем близко!','Вернитесь к Таренару Удару Солнца в Чумной лес, что в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Стражи Стратхольма',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Его схватила баронесса Анастари? Здесь, в Чумном лесу?$B$BЧумной лес велик... но мы обязательно найдем Гидвина. Мы НАЙДЕМ его.$B$BСовсем недалеко отсюда, на северо-западе находятся два некрополя, стоящие по обеим сторонам от входа в Стратхольм. В них ты найдешь пару рыцарей смерти – помощников Ривендера. Я сомневаюсь в том, чтобы кому-то из них пригодился бы заложник-паладин – но, возможно, им известно, где он сейчас.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Омасума Гнилое Копыто и Картиса Темную Руну.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мы должны идти дальше! Цель уже совсем близко!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Таренару Удару Солнца в Чумной лес, что в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27526,'Судьба Гидвина','Быстрее найди вход в бойню, которая расположена к югу отсюда! Встретимся там.$B$BИ приготовься к бою!','Найдите Гидвина Златокоса в здании бойни в центральной части Чумного леса.','Вы даже не представляете, насколько я рад вас видеть! Вы настоящая отрада для глаз... глаз, которые слишком долго смотрели на банши.$B$BПростите за то, что так осложнил вам жизнь. Вы отведете меня к каравану?','Поговорите с Гидвином Златокосом в Чумном лесу в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Судьба Гидвина',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Быстрее найди вход в бойню, которая расположена к югу отсюда! Встретимся там.$B$BИ приготовься к бою!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Гидвина Златокоса в здании бойни в центральной части Чумного леса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы даже не представляете, насколько я рад вас видеть! Вы настоящая отрада для глаз... глаз, которые слишком долго смотрели на банши.$B$BПростите за то, что так осложнил вам жизнь. Вы отведете меня к каравану?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Гидвином Златокосом в Чумном лесу в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27527,'Конец пути','Меня уже тошнит от этого места. Нежить и сама по себе воняет – а если добавить к этой вони еще и запах грибов?! Ненавижу грибы!$B$B$n, я пойду к часовне Последней Надежды... и возьму с собой Таренара и Фиону. Мы достаточно натерпелись, и теперь нам нужно отдохнуть от приключений.$B$BЯ хочу отдать тебе вот это. Это мой камень возвращения – с его помощью ты можешь мгновенно вернуться в часовню Последней Надежды. Мне он не понадобится, ведь я пойду с караваном.$B$BТочнее, поеду – НА ПЕРЕДНЕМ СИДЕНЬЕ.','Поговорите с Фионой в часовне Последней Надежды в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Конец пути',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Меня уже тошнит от этого места. Нежить и сама по себе воняет – а если добавить к этой вони еще и запах грибов?! Ненавижу грибы!$B$B$n, я пойду к часовне Последней Надежды... и возьму с собой Таренара и Фиону. Мы достаточно натерпелись, и теперь нам нужно отдохнуть от приключений.$B$BЯ хочу отдать тебе вот это. Это мой камень возвращения – с его помощью ты можешь мгновенно вернуться в часовню Последней Надежды. Мне он не понадобится, ведь я пойду с караваном.$B$BТочнее, поеду – НА ПЕРЕДНЕМ СИДЕНЬЕ.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Фионой в часовне Последней Надежды в Восточных Чумных землях.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27528,'Жуткая масса','Слуг Плети просто так не убьешь. Они возвращаются. Нет, нужно уничтожить злую сущность, из которой они состоят... хотя и после этого они возвращаются – но в форме призраков.$B$BТаких огромных чудовищ, как эта нежить, еще поискать. Сначала убей, а затем сожги их тела. Они бродят по всему Чумному лесу.$B$BИ пусть твой гнев не угасает, |3-6($r). Помни: эти твари составлены из останков хороших людей. Они виноваты уже просто в том, что существуют на этом свете.','Убейте 8 перегруженных големов, а затем подожгите их факелом рыцаря.','Благословенный огонь очищает даже самую оскверненную плоть.$B$BПротив Света у них не было ни единого шанса.','Поговорите с рыцарем Кевином Фростом в Чумном лесу в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жуткая масса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слуг Плети просто так не убьешь. Они возвращаются. Нет, нужно уничтожить злую сущность, из которой они состоят... хотя и после этого они возвращаются – но в форме призраков.$B$BТаких огромных чудовищ, как эта нежить, еще поискать. Сначала убей, а затем сожги их тела. Они бродят по всему Чумному лесу.$B$BИ пусть твой гнев не угасает, |3-6($r). Помни: эти твари составлены из останков хороших людей. Они виноваты уже просто в том, что существуют на этом свете.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 перегруженных големов, а затем подожгите их факелом рыцаря.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Благословенный огонь очищает даже самую оскверненную плоть.$B$BПротив Света у них не было ни единого шанса.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с рыцарем Кевином Фростом в Чумном лесу в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27529,'Защитники Дарроушира','Битва в Дарроушире – это всего лишь одна из многих трагедий, которые людям пришлось пережить по вине Плети. И последствия мы чувствуем на своей шкуре до сих пор.$B$BМногие храбрые защитники города теперь стали жуткими слугами Плети. Но мы избавим их от страданий.$B$BУбивай каннибалов-вурдалаков, которые бродят по Чумному лесу. Многие из этих тварей когда-то были добрыми жителями Дарроушира и, уничтожая их тела, ты освободишь их души.','Освободите 8 духов Дарроушира из тел каннибалов-вурдалаков, а затем поговорите с ними.','Как хорошо, что тебе удалось освободить измученные души моих братьев. Мне придает сил одна лишь мысль о том, что хотя бы несколько защитников Дарроушира больше не являются рабами Плети.','Поговорите с рыцарем Кевином Фростом в Чумном лесу в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Защитники Дарроушира',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Битва в Дарроушире – это всего лишь одна из многих трагедий, которые людям пришлось пережить по вине Плети. И последствия мы чувствуем на своей шкуре до сих пор.$B$BМногие храбрые защитники города теперь стали жуткими слугами Плети. Но мы избавим их от страданий.$B$BУбивай каннибалов-вурдалаков, которые бродят по Чумному лесу. Многие из этих тварей когда-то были добрыми жителями Дарроушира и, уничтожая их тела, ты освободишь их души.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Освободите 8 духов Дарроушира из тел каннибалов-вурдалаков, а затем поговорите с ними.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Как хорошо, что тебе удалось освободить измученные души моих братьев. Мне придает сил одна лишь мысль о том, что хотя бы несколько защитников Дарроушира больше не являются рабами Плети.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с рыцарем Кевином Фростом в Чумном лесу в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27530,'Трупозвери','На юге сектанты продолжают заниматься своим жутким делом: они оживляют огромные куски плоти, превращая их в великанов – трупозверей. К счастью, эти трупозвери еще слабые и не могут двигаться.$B$BВозьми этот амулет – он создает на земле источник священной энергии. Если ты сможешь создать три таких источника рядом с одним из трупозверей, священная энергия уничтожит его раз и навсегда.','Уничтожьте тела трех трупозверей, поставив рядом с ними три или более серебряных оберегов колодца Света. Обереги нельзя ставить во время боя, а расстояние между ними должно быть не менее десяти ярдов.','Вернитесь к рыцарю Кевину Фросту в Чумной лес, что в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Трупозвери',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На юге сектанты продолжают заниматься своим жутким делом: они оживляют огромные куски плоти, превращая их в великанов – трупозверей. К счастью, эти трупозвери еще слабые и не могут двигаться.$B$BВозьми этот амулет – он создает на земле источник священной энергии. Если ты сможешь создать три таких источника рядом с одним из трупозверей, священная энергия уничтожит его раз и навсегда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте тела трех трупозверей, поставив рядом с ними три или более серебряных оберегов колодца Света. Обереги нельзя ставить во время боя, а расстояние между ними должно быть не менее десяти ярдов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к рыцарю Кевину Фросту в Чумной лес, что в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27531,'Борьба с чумой','Когда-то я был аптекарем Сильваны, так называемой "Королевы банши". Раньше я восхищался ею, но потом что-то в ней изменилось. Теперь она не похожа сама на себя.$B$BТогда я нарушил данные обеты и вступил в Авангард. И теперь обратил свои познания в алхимии на поиски средства от чумы. И где же еще искать это средство, как не в Чумном лесу.$B$BМне нужно пополнить запасы нескольких ингредиентов – и все из них можно найти в Чумном лесу. Принеси их мне, и я тебя награжу.','Соберите 20 ягод гниленики, 5 бестелесных рук и 1 кучу струганных пяток мясистого великана.','Я обожаю запах свежих струганных пяток! А ты?$B$BТак! Если мы собираемся создать лекарство от чумы, придется изобрести какую-нибудь необычную смесь из этих ингредиентов. Прости, но мне пора приниматься за работу.','Все это добро у тебя?','Поговорите с аптекарем Юдкинсом в башне Чумного леса в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Борьба с чумой',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда-то я был аптекарем Сильваны, так называемой "Королевы банши". Раньше я восхищался ею, но потом что-то в ней изменилось. Теперь она не похожа сама на себя.$B$BТогда я нарушил данные обеты и вступил в Авангард. И теперь обратил свои познания в алхимии на поиски средства от чумы. И где же еще искать это средство, как не в Чумном лесу.$B$BМне нужно пополнить запасы нескольких ингредиентов – и все из них можно найти в Чумном лесу. Принеси их мне, и я тебя награжу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 20 ягод гниленики, 5 бестелесных рук и 1 кучу струганных пяток мясистого великана.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я обожаю запах свежих струганных пяток! А ты?$B$BТак! Если мы собираемся создать лекарство от чумы, придется изобрести какую-нибудь необычную смесь из этих ингредиентов. Прости, но мне пора приниматься за работу.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Все это добро у тебя?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с аптекарем Юдкинсом в башне Чумного леса в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27532,'Башня Чумного леса','Если вспомнить о недавнем неприятном инциденте с Гидвином, то, возможно, мужчине моего возраста не стоит сейчас разгуливать по Чумному лесу. Я не против – в конце концов, могу заглянуть в башню Чумного леса в следующий раз.$B$BОднако мне нужно доставить кое-что Юдкинсу. Ты моложе меня и сильнее – может, отнесешь ему эту посылку?','Отнесите посылку Аргуса Путеводного аптекарю Юдкинсу в башню Чумного леса в Восточных Чумных землях.','Уф... Когда Аргус уходит в Чумной лес, я боюсь, что вижу его в последний раз. Как хорошо, что он поумнел и послал вместо себя кого помоложе.','Посылка Аргуса Путеводного... Он в безопасности? С ним ничего не случилось?','Поговорите с аптекарем Юдкинсом в башне Чумного леса в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Башня Чумного леса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если вспомнить о недавнем неприятном инциденте с Гидвином, то, возможно, мужчине моего возраста не стоит сейчас разгуливать по Чумному лесу. Я не против – в конце концов, могу заглянуть в башню Чумного леса в следующий раз.$B$BОднако мне нужно доставить кое-что Юдкинсу. Ты моложе меня и сильнее – может, отнесешь ему эту посылку?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите посылку Аргуса Путеводного аптекарю Юдкинсу в башню Чумного леса в Восточных Чумных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Уф... Когда Аргус уходит в Чумной лес, я боюсь, что вижу его в последний раз. Как хорошо, что он поумнел и послал вместо себя кого помоложе.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Посылка Аргуса Путеводного... Он в безопасности? С ним ничего не случилось?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с аптекарем Юдкинсом в башне Чумного леса в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27533,'Хуже, чем попасть на прилавок к мяснику','Сначала люди в Долине Ужаса заболели, а потом испортились. Окончательно испортились.$B$BА вот свиньи... они тоже заболели! А свиньи-то тут при чем? Ха-ха-ха! Они ведь ни в чем не виноваты!$B$BПро людей-то я могу забыть, но вот свиньи меня расстраивают. Вот если бы тебе удалось убить их... тогда, возможно, я бы повеселел.','Убейте 9 чумных кабанов.','Я их вижу! А ты? Видишь эти крошечные души свиней, летящие в великий хлев на небесах?..','Поговорите с Августом Помешанным в Долине Ужаса в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хуже, чем попасть на прилавок к мяснику',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сначала люди в Долине Ужаса заболели, а потом испортились. Окончательно испортились.$B$BА вот свиньи... они тоже заболели! А свиньи-то тут при чем? Ха-ха-ха! Они ведь ни в чем не виноваты!$B$BПро людей-то я могу забыть, но вот свиньи меня расстраивают. Вот если бы тебе удалось убить их... тогда, возможно, я бы повеселел.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 9 чумных кабанов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я их вижу! А ты? Видишь эти крошечные души свиней, летящие в великий хлев на небесах?..',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Августом Помешанным в Долине Ужаса в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27534,'Книга рецептов Августа','Пожалуй, я готов открыть лавку...$B$BО нет! Моя книга рецептов! Мне не обойтись без нее!$B$BКажется, я оставил ее где-то в городе... Да, видимо, в таверне, в которой останавливался!$B$BПринеси мне мою книгу, умоляю! А когда открою лавку, ты увидишь, что цены у меня просто БЕЗУМНЫЕ!','Найдите книгу рецептов Августа Помешанного в таверне в Долине Ужаса.','Поговорите с Августом Помешанным в Долине Ужаса в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Книга рецептов Августа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пожалуй, я готов открыть лавку...$B$BО нет! Моя книга рецептов! Мне не обойтись без нее!$B$BКажется, я оставил ее где-то в городе... Да, видимо, в таверне, в которой останавливался!$B$BПринеси мне мою книгу, умоляю! А когда открою лавку, ты увидишь, что цены у меня просто БЕЗУМНЫЕ!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите книгу рецептов Августа Помешанного в таверне в Долине Ужаса.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Августом Помешанным в Долине Ужаса в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27535,'Совсем чуть-чуть порчи','Время от времени я навещаю Августа в Долине Ужаса – просто для того, чтобы убедиться в том, что с ним все в порядке. Похоже, что некоторые из нас, мертвяков, переживают чуму лучше остальных.$B$BДолина Ужаса находится к западу отсюда. Может, проведаешь его вместо меня?','Идите в Долину Ужаса и поговорите с Августом Помешанным.','Да, господин, вы пришли туда, куда нужно! Ничто не сравнится со старой доброй Долиной Ужаса! Это же жемчужина Лордерона!','Поговорите с Августом Помешанным в Долине Ужаса в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Совсем чуть-чуть порчи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Время от времени я навещаю Августа в Долине Ужаса – просто для того, чтобы убедиться в том, что с ним все в порядке. Похоже, что некоторые из нас, мертвяков, переживают чуму лучше остальных.$B$BДолина Ужаса находится к западу отсюда. Может, проведаешь его вместо меня?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Идите в Долину Ужаса и поговорите с Августом Помешанным.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, господин, вы пришли туда, куда нужно! Ничто не сравнится со старой доброй Долиной Ужаса! Это же жемчужина Лордерона!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Августом Помешанным в Долине Ужаса в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27536,'Абсолютно безопасно','Попрошу тебя еще кое о чем, $gприятель:подруга;.$B$BНамедни из Пиратской Бухты пришел груз с минами. А ночью их кто-то украл!$B$BКто бы то ни был, он крайне неуклюж, потому что мины разбросаны теперь по всему болоту на востоке. Ни один мой знакомый гоблин так бы не опростоволосился.$B$BЯ хочу, чтобы ты $gвернул:вернула; эти мины мне. Уверен, они без взрывателей и совершенно безопасны. Все до единой. Точно.','Ну, что я говорил? Совершенно безопасно!$B$BЯ прослежу, чтобы некоторые из них достались твоим друзьям. Со скидкой, разумеется.','Вернитесь к торговому барону Сереблексу в Веслотопи на Болоте Печали.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Абсолютно безопасно',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Попрошу тебя еще кое о чем, $gприятель:подруга;.$B$BНамедни из Пиратской Бухты пришел груз с минами. А ночью их кто-то украл!$B$BКто бы то ни был, он крайне неуклюж, потому что мины разбросаны теперь по всему болоту на востоке. Ни один мой знакомый гоблин так бы не опростоволосился.$B$BЯ хочу, чтобы ты $gвернул:вернула; эти мины мне. Уверен, они без взрывателей и совершенно безопасны. Все до единой. Точно.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну, что я говорил? Совершенно безопасно!$B$BЯ прослежу, чтобы некоторые из них достались твоим друзьям. Со скидкой, разумеется.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к торговому барону Сереблексу в Веслотопи на Болоте Печали.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27537,'Любой портал в Шторм','Наши друзья, Служители Земли, пытались открыть портал в Штормград, но безуспешно. А вот Тордун утверждает, что все сделает.$B$BКто-то вывел из себя элементалей воды в реке Вералл, и Тордун говорит, что мы можем направить их энергию на создание портала.$B$BЯ ничего не понимаю в этой элементалистике, но одно мне ясно: нужно убивать элементалей и забирать сердцевины водоворота. Отнеси их Талаа – она во дворе!','Убивайте илистых элементалей воды, пока не соберете 5 сердцевин водоворота.','Вернитесь на Высокий берег на Сумеречном нагорье и отдайте сердцевины водоворота Талаа.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Любой портал в Шторм',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наши друзья, Служители Земли, пытались открыть портал в Штормград, но безуспешно. А вот Тордун утверждает, что все сделает.$B$BКто-то вывел из себя элементалей воды в реке Вералл, и Тордун говорит, что мы можем направить их энергию на создание портала.$B$BЯ ничего не понимаю в этой элементалистике, но одно мне ясно: нужно убивать элементалей и забирать сердцевины водоворота. Отнеси их Талаа – она во дворе!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убивайте илистых элементалей воды, пока не соберете 5 сердцевин водоворота.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь на Высокий берег на Сумеречном нагорье и отдайте сердцевины водоворота Талаа.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27538,'Идеальная припарка','Ты держишь путь к дельте Вералла? Тогда я дам тебе один совет... он поможет твоим людям и моей птичке!$B$BКогда элементали воды прокладывают себе путь через камень, они создают особый ил. Засыхая, он становится невероятно твердым, но при этом еще обладает целебной силой воды. В лубке из такого ила любая сломанная кость мигом срастется.$B$BПринеси этот ил Талаа, вашей шаманке – она внизу. Талаа знает, что с ним делать!','Соберите 10 порций ила из Вералла.','А... ил. Это ил?$B$BОго, да ведь в нем полно энергии! Теперь я понимаю, о чем говорил Тордун. Я немедленно раздам его всем целителям. Наши раненые скоро снова встанут в строй!','Что это там говорят про ил из Вералла?','Вернитесь на Высокий берег на Сумеречном нагорье и отдайте ил Талаа.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Идеальная припарка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты держишь путь к дельте Вералла? Тогда я дам тебе один совет... он поможет твоим людям и моей птичке!$B$BКогда элементали воды прокладывают себе путь через камень, они создают особый ил. Засыхая, он становится невероятно твердым, но при этом еще обладает целебной силой воды. В лубке из такого ила любая сломанная кость мигом срастется.$B$BПринеси этот ил Талаа, вашей шаманке – она внизу. Талаа знает, что с ним делать!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 порций ила из Вералла.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А... ил. Это ил?$B$BОго, да ведь в нем полно энергии! Теперь я понимаю, о чем говорил Тордун. Я немедленно раздам его всем целителям. Наши раненые скоро снова встанут в строй!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что это там говорят про ил из Вералла?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь на Высокий берег на Сумеречном нагорье и отдайте ил Талаа.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27539,'Бросай их в кучу!','Я собираю черепа побежденных мною скелетов – из них уже образовалась небольшая куча.$B$BЕсли найдешь еще черепа, можешь добавить туда. Кажется, один их вид отпугивает нежить... и, кроме того, мне просто приятно на это смотреть.','Идите в Чумной лес и добудьте 16 вонючих черепов, убивая проклятых магов и солдат Плети.','Пусть моя куча растет и высится.','Похоже, у тебя все руки заняты. Это что, черепа?','Вернитесь к рыцарю Кевину Фросту в Чумной лес, что в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бросай их в кучу!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я собираю черепа побежденных мною скелетов – из них уже образовалась небольшая куча.$B$BЕсли найдешь еще черепа, можешь добавить туда. Кажется, один их вид отпугивает нежить... и, кроме того, мне просто приятно на это смотреть.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Идите в Чумной лес и добудьте 16 вонючих черепов, убивая проклятых магов и солдат Плети.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Пусть моя куча растет и высится.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Похоже, у тебя все руки заняты. Это что, черепа?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к рыцарю Кевину Фросту в Чумной лес, что в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27541,'Благоразумный подход','Этому бедняге явно не повезло!$B$BСтоит обыскать хладный труп, это будет только благоразумно. Конечно, приятного мало. Но это может помочь пролить свет на происшедшее.','Найдите разбитые очки.','Странно...$B$BПохоже, тут линзы – из драгоценных камней.$B$BДумаю, я смогу их починить. Как раз-два!','Какие новости, Михалкен?','Отнесите разбитые очки Харрисону Джонсу в Зал Звезд.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Благоразумный подход',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этому бедняге явно не повезло!$B$BСтоит обыскать хладный труп, это будет только благоразумно. Конечно, приятного мало. Но это может помочь пролить свет на происшедшее.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите разбитые очки.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Странно...$B$BПохоже, тут линзы – из драгоценных камней.$B$BДумаю, я смогу их починить. Как раз-два!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Какие новости, Михалкен?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите разбитые очки Харрисону Джонсу в Зал Звезд.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (27542,'Контрудар') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Контрудар',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (27543,'[TEMP PH] What We Have Done') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[TEMP PH] What We Have Done',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27544,'Упрямые друиды','Клянусь, эти друиды упрямы, как ослы. Я уже много лет как забыл про Чумные земли, но эти парни из Круга Кенария все твердят, что эту местность еще можно спасти.$B$BВ последний раз ко мне приходила какая-то ночная эльфийка. Она направлялась на север, в Грибную долину. И сказала, что если мы постараемся, то эта земля станет такой же, как прежде. Что-то я сомневаюсь.$B$BА ты веришь в эту муть? Возможно, тебе стоит поговорить с ней. Наверно, она все еще где-то там.','Поговорите с Райн в начале Грибной долины.','Раз тебе удалось меня разыскать, то, похоже, мне нужно поработать над своей маскировкой.$B$BХочешь помочь исцелить эти земли?','Поговорите с Райн в начале Грибной долины в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Упрямые друиды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Клянусь, эти друиды упрямы, как ослы. Я уже много лет как забыл про Чумные земли, но эти парни из Круга Кенария все твердят, что эту местность еще можно спасти.$B$BВ последний раз ко мне приходила какая-то ночная эльфийка. Она направлялась на север, в Грибную долину. И сказала, что если мы постараемся, то эта земля станет такой же, как прежде. Что-то я сомневаюсь.$B$BА ты веришь в эту муть? Возможно, тебе стоит поговорить с ней. Наверно, она все еще где-то там.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Райн в начале Грибной долины.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Раз тебе удалось меня разыскать, то, похоже, мне нужно поработать над своей маскировкой.$B$BХочешь помочь исцелить эти земли?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Райн в начале Грибной долины в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27545,'Путь открыт','Мы с шаманом останемся здесь, чтобы держать портал открытым.$B$BА ты иди наверх и сообщи Курдрану, что дело сделано. Ему будет приятно наконец-то услышать хоть что-то хорошее.','Поговорите с Курдраном Громовым Молотом на Высоком берегу на Сумеречном нагорье.','Поговорите с Курдраном Громовым Молотом на Высоком берегу на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путь открыт',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы с шаманом останемся здесь, чтобы держать портал открытым.$B$BА ты иди наверх и сообщи Курдрану, что дело сделано. Ему будет приятно наконец-то услышать хоть что-то хорошее.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Курдраном Громовым Молотом на Высоком берегу на Сумеречном нагорье.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Курдраном Громовым Молотом на Высоком берегу на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27547,'Пустяки','7-му легиону удалось наводнить город своими агентами, и они застали наших воинов врасплох и перебили почти всех.$B$BТемная Госпожа поручила нам провести спасательную операцию. Нам нужно найти тех, кто выжил, и вывести их из Погребальных Костров. Я не думаю, что эти солдаты представляют хоть какую-либо ценность, однако приказы Темной Госпожи обсуждению не подлежат.$B$BДавай побыстрее разберемся с этим делом, $n. Погребальные Костры находятся к юго-западу от Рубежа Отрекшихся.','Спасите 8 дрожащих бойцов.','То, что произошло здесь сегодня, останется между нами. Если проболтаешься, окажешься в яме вместе с этими несчастными глупцами.','Поговорите с бароном Эшбери в Серебряном бору.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пустяки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','7-му легиону удалось наводнить город своими агентами, и они застали наших воинов врасплох и перебили почти всех.$B$BТемная Госпожа поручила нам провести спасательную операцию. Нам нужно найти тех, кто выжил, и вывести их из Погребальных Костров. Я не думаю, что эти солдаты представляют хоть какую-либо ценность, однако приказы Темной Госпожи обсуждению не подлежат.$B$BДавай побыстрее разберемся с этим делом, $n. Погребальные Костры находятся к юго-западу от Рубежа Отрекшихся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Спасите 8 дрожащих бойцов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','То, что произошло здесь сегодня, останется между нами. Если проболтаешься, окажешься в яме вместе с этими несчастными глупцами.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с бароном Эшбери в Серебряном бору.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27548,'Урок страха','Враги становятся умнее – и приспосабливаются к нашей тактике. Недавно они напали на нас в деревне Погребальных Костров, что на юго-западе. Наших воинов почти всех перебили, но самое главное не это. Главное – расовый состав нападавших. Среди них не было ни одного человека.$B$B<Вальден смеется.>$B$BОни боятся – вполне резонно – что их оживят и превратят в Отрекшихся.$B$BДавай нагоним страху на этих нелюдей. Покажем им, что происходит с трупами, которые мы не можем использовать.','Убейте 12 разведчиков 7-го легиона.','Полагаю, теперь на фронте будет еще меньше людей. Эти трусы считают, что риск для них слишком высок.','Поговорите с лордом Вальденом в Серебряном бору.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Урок страха',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Враги становятся умнее – и приспосабливаются к нашей тактике. Недавно они напали на нас в деревне Погребальных Костров, что на юго-западе. Наших воинов почти всех перебили, но самое главное не это. Главное – расовый состав нападавших. Среди них не было ни одного человека.$B$B<Вальден смеется.>$B$BОни боятся – вполне резонно – что их оживят и превратят в Отрекшихся.$B$BДавай нагоним страху на этих нелюдей. Покажем им, что происходит с трупами, которые мы не можем использовать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 разведчиков 7-го легиона.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Полагаю, теперь на фронте будет еще меньше людей. Эти трусы считают, что риск для них слишком высок.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с лордом Вальденом в Серебряном бору.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27549,'Звездный свет','Смотри, $n.$B$B<Харрисон показывает вам очки мертвого разведчика.>$B$BЯ подтянул крепеж в середине и обжал провода по краям. Их теперь неудобно носить, но зато они будут держаться.$B$BЕсли я правильно перевел записи на табличках, тут где-то должна быть последняя подсказка. Недостающий ключ к разгадке.$B$BНадеюсь, эти очки помогут нам его разыскать.$B$BДавай-ка попробуем.','Соберите 7 порций взвеси звездного света.','Превосходно, малыш! Что бы я без тебя делал?!$B$B<Харрисон показывает рисунок на табличке.>$B$BВот чего нам не хватало! Этого звездного света!$B$BА теперь – за работу!','Ну что?$B$BНашлось что-нибудь интересное?','Поговорите с Харрисоном Джонсом в Зале Звезд.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Звездный свет',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Смотри, $n.$B$B<Харрисон показывает вам очки мертвого разведчика.>$B$BЯ подтянул крепеж в середине и обжал провода по краям. Их теперь неудобно носить, но зато они будут держаться.$B$BЕсли я правильно перевел записи на табличках, тут где-то должна быть последняя подсказка. Недостающий ключ к разгадке.$B$BНадеюсь, эти очки помогут нам его разыскать.$B$BДавай-ка попробуем.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 7 порций взвеси звездного света.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Превосходно, малыш! Что бы я без тебя делал?!$B$B<Харрисон показывает рисунок на табличке.>$B$BВот чего нам не хватало! Этого звездного света!$B$BА теперь – за работу!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что?$B$BНашлось что-нибудь интересное?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Харрисоном Джонсом в Зале Звезд.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27550,'Гибель Погребальных Костров','Наступление на нашем фронте – это всего лишь отвлекающий маневр. Альянс воспользовался тем, что мы заняты отражением атаки воргенов, и захватил деревню Погребальных Костров. $B$B<Годфри протягивает вам охапку факелов.>$B$BМы должны очистить ее.$B$BЭти факелы спалят деревню Погребальных Костров дотла. Пусть противник прячется в кучках пепла.$B$BНе будем терять ни минуты. Деревня Погребальных Костров находится к юго-западу от Передовой Отрекшихся. Веди нас туда, $n.','Используйте охапку факелов, чтобы поджечь ратушу, таверну и часовню Погребальных Костров.','Гилнеаcец во мне умер в Пределе бури. Теперь во мне живет только месть. И поэтому нам нужно многое сделать. Так что избавь меня от бессмысленных вопросов.','Поговорите с лордом Годфри в Серебряном бору.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гибель Погребальных Костров',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наступление на нашем фронте – это всего лишь отвлекающий маневр. Альянс воспользовался тем, что мы заняты отражением атаки воргенов, и захватил деревню Погребальных Костров. $B$B<Годфри протягивает вам охапку факелов.>$B$BМы должны очистить ее.$B$BЭти факелы спалят деревню Погребальных Костров дотла. Пусть противник прячется в кучках пепла.$B$BНе будем терять ни минуты. Деревня Погребальных Костров находится к юго-западу от Передовой Отрекшихся. Веди нас туда, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте охапку факелов, чтобы поджечь ратушу, таверну и часовню Погребальных Костров.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Гилнеаcец во мне умер в Пределе бури. Теперь во мне живет только месть. И поэтому нам нужно многое сделать. Так что избавь меня от бессмысленных вопросов.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с лордом Годфри в Серебряном бору.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27551,'Послание баронессы','Это записка от баронессы Анастари, в ней описан ритуал, который должен пройти в бойне – в самом центре Чумного леса, к югу от того места, где находится Таренар. Возможно, именно там они держат Гидвина!$B$BНужно сообщить об этом Таренару... и как можно быстрее!','Отнесите послание баронессы Таренару.','Поговорите с Таренаром Ударом Солнца в Чумном лесу в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Послание баронессы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это записка от баронессы Анастари, в ней описан ритуал, который должен пройти в бойне – в самом центре Чумного леса, к югу от того места, где находится Таренар. Возможно, именно там они держат Гидвина!$B$BНужно сообщить об этом Таренару... и как можно быстрее!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите послание баронессы Таренару.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Таренаром Ударом Солнца в Чумном лесу в Восточных Чумных землях.',`completedtext_loc8`);
