INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (27564,'Защита редута','Пришло сообщение от Калена – Сумеречные войска проникли на редут!$B$BНастало время, когда ты можешь заслужить его расположение!','Надеюсь, твое снаряжение соответствует твоим способностям. Войска Сумеречного Молота пробрались на редут – и кто-то должен их уничтожить.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Защита редута',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пришло сообщение от Калена – Сумеречные войска проникли на редут!$B$BНастало время, когда ты можешь заслужить его расположение!',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Надеюсь, твое снаряжение соответствует твоим способностям. Войска Сумеречного Молота пробрались на редут – и кто-то должен их уничтожить.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27565,'В тюрьму','Нам удалось проникнуть в тюрьму дворфов Черного Железа!$B$BТочнее, мы надеемся, что удалось.$B$BКевин Доусон отправился туда, чтобы лично поучаствовать в операции, и с тех пор от него ни слуху, ни духу. Ты же еще не собираешься отдавать концы? Вот и сходи туда да проверь, все ли с ним в порядке!$B$BОн должен находиться внутри зала в южном краю пещеры, что начинается впереди... хотя что-то мне подсказывает, что ему не удалось забраться так далеко.','Отыщите Кевина Доусона.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В тюрьму',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нам удалось проникнуть в тюрьму дворфов Черного Железа!$B$BТочнее, мы надеемся, что удалось.$B$BКевин Доусон отправился туда, чтобы лично поучаствовать в операции, и с тех пор от него ни слуху, ни духу. Ты же еще не собираешься отдавать концы? Вот и сходи туда да проверь, все ли с ним в порядке!$B$BОн должен находиться внутри зала в южном краю пещеры, что начинается впереди... хотя что-то мне подсказывает, что ему не удалось забраться так далеко.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщите Кевина Доусона.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27566,'Собрание в Запределье','Приветствую, |3-6($c). Стихии все свирепствуют, усмирить их пока не в наших силах. У Трона стихий в Награнде собрались мудрейшие шаманы, чтобы общими усилиями найти способ исцелить нашу землю.$B$BОтправляйся к Трону стихий и поговори с Гаваном Серым Пером – у него наверняка найдется для тебя задание.','Поговорите с Гаваном Серым Пером у Трона стихий в Награнде.','Поговорите с Гаваном Серым Пером у Трона стихий в Награнде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Собрание в Запределье',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приветствую, |3-6($c). Стихии все свирепствуют, усмирить их пока не в наших силах. У Трона стихий в Награнде собрались мудрейшие шаманы, чтобы общими усилиями найти способ исцелить нашу землю.$B$BОтправляйся к Трону стихий и поговори с Гаваном Серым Пером – у него наверняка найдется для тебя задание.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Гаваном Серым Пером у Трона стихий в Награнде.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Гаваном Серым Пером у Трона стихий в Награнде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27567,'Культ Сумеречного Молота?! О, нет!','Сложно поверить, но в глубинах Черной горы скрываются сектанты из культа Сумеречного Молота! Не знаю, сколько именно адептов культа проникло в это место, но мне донесли, что верховный дознаватель Герштан находится в этом проходе среди прочих.$B$BМне неведомо, кого они тут допрашивают с пристрастием, но, может быть, тебе удастся выпытать это у Герштан?','"Дознайте" правду у верховного дознавателя Герштан.','Значит, она не захотела сотрудничать. Надеюсь, мы успеем их остановить до того, как произойдет нечто ужасное.','Вернитесь к Кевину Доусону.','Эмиссар Сумеречного Молота.','Верховный дознаватель Герштан') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Культ Сумеречного Молота?! О, нет!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сложно поверить, но в глубинах Черной горы скрываются сектанты из культа Сумеречного Молота! Не знаю, сколько именно адептов культа проникло в это место, но мне донесли, что верховный дознаватель Герштан находится в этом проходе среди прочих.$B$BМне неведомо, кого они тут допрашивают с пристрастием, но, может быть, тебе удастся выпытать это у Герштан?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','"Дознайте" правду у верховного дознавателя Герштан.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Значит, она не захотела сотрудничать. Надеюсь, мы успеем их остановить до того, как произойдет нечто ужасное.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кевину Доусону.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Эмиссар Сумеречного Молота.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Верховный дознаватель Герштан',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27568,'Проникновение в Тенегорн','Ты умеешь хранить секреты? Я хочу поделиться с тобой одной тайной.$B$BТут все ЧОКНУТЫЕ!$B$BТут повсюду гоблины, справа все заняли дворфы Черного Железа, а за этими воротами обитает гигантская огненная тварь! И вся эта живность теснится в маленькой пещерке!$B$BА ты что тут $gпозабыл:позабыла;?$B$BПонятно. Ты от Винки, не так ли? Он послал тебя переговорить с геологом Сеймуром, что находится за воротами направо? Ну, давай! Орелию до тебя нет никакого дела.$B$B...ВИНКИ, ТЫ МНЕ ЗА ЭТО ЗАПЛАТИШЬ!$B$B<Орелий рыдает.>','Поговорите с геологом Сеймуром.','Я бы на твоем месте держался подальше от Орелия. За версту. Он не дружит с головой.$B$BА теперь перейдем к делу!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Проникновение в Тенегорн',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты умеешь хранить секреты? Я хочу поделиться с тобой одной тайной.$B$BТут все ЧОКНУТЫЕ!$B$BТут повсюду гоблины, справа все заняли дворфы Черного Железа, а за этими воротами обитает гигантская огненная тварь! И вся эта живность теснится в маленькой пещерке!$B$BА ты что тут $gпозабыл:позабыла;?$B$BПонятно. Ты от Винки, не так ли? Он послал тебя переговорить с геологом Сеймуром, что находится за воротами направо? Ну, давай! Орелию до тебя нет никакого дела.$B$B...ВИНКИ, ТЫ МНЕ ЗА ЭТО ЗАПЛАТИШЬ!$B$B<Орелий рыдает.>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с геологом Сеймуром.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я бы на твоем месте держался подальше от Орелия. За версту. Он не дружит с головой.$B$BА теперь перейдем к делу!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27569,'Тактики из клана Черного Железа','Генерал Кузня Гнева и повелитель големов Аргелмах ведут на нас свои войска вместе с големами. Если мы действительно хотим остановить их нападение, то для начала следует расправиться с этими военачальниками.$B$BВойди в эту дверь и открой замок Тенегорн, что отделяет Восточный гарнизон от Западного. Затем поднимайся по лестнице и, поднявшись, держись левой стороны пока не дойдешь до Западного гарнизона. Там ты и найдешь генерала и повелителя големов.$B$BБудь осторожен, они оба закаленные вояки. Если справишься с заданием, переговори с Майрой Светлое Крыло.','Убейте генерала Кузню Гнева и повелителя големов Аргелмаха.','Уверена, что справившийся так быстро с этим заданием готов к моему следующему поручению.$B$B<Майра Светлое Крыло начинает говорить шепотом>.$B$BТолько между нами, тебе следует заглянуть в "Угрюмого обжору", когда доберешься до места. Может статься, что это будет твой последний глоток выпивки.','Поговорите с Майрой Светлое Крыло.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тактики из клана Черного Железа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Генерал Кузня Гнева и повелитель големов Аргелмах ведут на нас свои войска вместе с големами. Если мы действительно хотим остановить их нападение, то для начала следует расправиться с этими военачальниками.$B$BВойди в эту дверь и открой замок Тенегорн, что отделяет Восточный гарнизон от Западного. Затем поднимайся по лестнице и, поднявшись, держись левой стороны пока не дойдешь до Западного гарнизона. Там ты и найдешь генерала и повелителя големов.$B$BБудь осторожен, они оба закаленные вояки. Если справишься с заданием, переговори с Майрой Светлое Крыло.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте генерала Кузню Гнева и повелителя големов Аргелмаха.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Уверена, что справившийся так быстро с этим заданием готов к моему следующему поручению.$B$B<Майра Светлое Крыло начинает говорить шепотом>.$B$BТолько между нами, тебе следует заглянуть в "Угрюмого обжору", когда доберешься до места. Может статься, что это будет твой последний глоток выпивки.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Майрой Светлое Крыло.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27571,'Трактир "Угрюмый обжора"','Кое-кто поговаривает, что "Угрюмый обжора" – залог успеха военных операций дворфов из клана Черного Железа. Уставшие воины восстанавливают там свои силы, чтобы снова отправиться на ратные подвиги. Думаю, мы могли бы серьезно насолить дворфам, внеся хаос в это заведение.$B$BЯ хочу, чтоб ты $gввязался:ввязалась; в перепалку с тремя завсегдатаями трактира. Повреди бочки, чтобы привлечь внимание Харли Чернопыха. Укради вещи, лежащие на столах, чтобы ввязаться в драку со Штоппором Наливалсом. Наконец, просто заговори с Риббли Крутипробом, и тот полезет к тебе с кулаками. Переговори с Орфусом, когда начистишь им рыльца.','Подеритесь с Харли Чернопыхом, Штоппором Наливалсом и Риббли Крутипробом.','Дфорфы из клана Черного Железа покусились на наш громоварский эль. Я никогда не прощу им подобного. Придушил бы их своими руками!$B$BОднако в данный момент у нас есть более срочные дела.','Поговорите с горным пехотинцем Орфусом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Трактир "Угрюмый обжора"',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кое-кто поговаривает, что "Угрюмый обжора" – залог успеха военных операций дворфов из клана Черного Железа. Уставшие воины восстанавливают там свои силы, чтобы снова отправиться на ратные подвиги. Думаю, мы могли бы серьезно насолить дворфам, внеся хаос в это заведение.$B$BЯ хочу, чтоб ты $gввязался:ввязалась; в перепалку с тремя завсегдатаями трактира. Повреди бочки, чтобы привлечь внимание Харли Чернопыха. Укради вещи, лежащие на столах, чтобы ввязаться в драку со Штоппором Наливалсом. Наконец, просто заговори с Риббли Крутипробом, и тот полезет к тебе с кулаками. Переговори с Орфусом, когда начистишь им рыльца.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Подеритесь с Харли Чернопыхом, Штоппором Наливалсом и Риббли Крутипробом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Дфорфы из клана Черного Железа покусились на наш громоварский эль. Я никогда не прощу им подобного. Придушил бы их своими руками!$B$BОднако в данный момент у нас есть более срочные дела.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с горным пехотинцем Орфусом.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27572,'Собрание в Запределье','Приветствую, |3-6($c). Стихии все свирепствуют, усмирить их пока не в наших силах. У Трона стихий в Награнде собрались мудрейшие шаманы, чтобы общими усилиями найти способ исцелить нашу землю.$B$BОтправляйся к Трону стихий и поговори с нашим вождем – у него наверняка найдется для тебя задание.','Поговорите с Траллом у Трона стихий в Награнде.','Поговорите с Траллом у Трона стихий в Награнде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Собрание в Запределье',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приветствую, |3-6($c). Стихии все свирепствуют, усмирить их пока не в наших силах. У Трона стихий в Награнде собрались мудрейшие шаманы, чтобы общими усилиями найти способ исцелить нашу землю.$B$BОтправляйся к Трону стихий и поговори с нашим вождем – у него наверняка найдется для тебя задание.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Траллом у Трона стихий в Награнде.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Траллом у Трона стихий в Награнде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27573,'Узы Черного Железа','Убейте посла Огнехлыста и Рок\'рела.','Мне не по силам продолжить путь в одиночку, несмотря на весь свой боевой опыт. Лицей оказался для меня непреодолимым препятствием. Твоя помощь может оказаться незаменимой.','Явитесь к маршалу Максвеллу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Узы Черного Железа',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте посла Огнехлыста и Рок\'рела.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мне не по силам продолжить путь в одиночку, несмотря на весь свой боевой опыт. Лицей оказался для меня непреодолимым препятствием. Твоя помощь может оказаться незаменимой.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Явитесь к маршалу Максвеллу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27574,'У меня отличная память на лица','Вы нашли полупереваренную голову. Лорд Годфри настораживается, заметив ее. Возможно, вам следует отдать голову ему.','Идите в Серебряный бор и отдайте полупереваренную голову лорду Годфри.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','У меня отличная память на лица',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы нашли полупереваренную голову. Лорд Годфри настораживается, заметив ее. Возможно, вам следует отдать голову ему.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Идите в Серебряный бор и отдайте полупереваренную голову лорду Годфри.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27575,'Из брюха зверя','Думаю, нам удастся его восстановить. И если мы это сделаем, то, возможно, он сообщит нам что-нибудь о Краули.$B$BМы должны убивать каждого кроколиска, которого встретим на этом болоте, пока не найдем остальные части Шона Демпси. Из брюха зверя возродится человек!','Найдите туловище Демпси, конечности Демпси и внутренности Демпси.','Поговорите с лордом Годфри в Серебряном бору.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Из брюха зверя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Думаю, нам удастся его восстановить. И если мы это сделаем, то, возможно, он сообщит нам что-нибудь о Краули.$B$BМы должны убивать каждого кроколиска, которого встретим на этом болоте, пока не найдем остальные части Шона Демпси. Из брюха зверя возродится человек!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите туловище Демпси, конечности Демпси и внутренности Демпси.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с лордом Годфри в Серебряном бору.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27576,'Разброд и шатание','Поговорите с Патчем в ущелье Драконьей Пасти.','Тебе удалось привлечь драконов! Молодчина!$B$BМы уже подготовили засаду, как вдруг к нам обратились драконы. Они нам помогут – отрежут врагу путь к отступлению.$B$BНо, если хочешь, можешь присоединиться к общему веселью. Тут на всех хватит.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разброд и шатание',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Патчем в ущелье Драконьей Пасти.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебе удалось привлечь драконов! Молодчина!$B$BМы уже подготовили засаду, как вдруг к нам обратились драконы. Они нам помогут – отрежут врагу путь к отступлению.$B$BНо, если хочешь, можешь присоединиться к общему веселью. Тут на всех хватит.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27577,'Планы 7-го легиона','Уничтожение Погребальных Костров, несомненно, даст нам преимущество в бою, но наша главная задача – нанести непоправимый урон войскам Альянса.$B$BК юго-западу отсюда, у Стены Седогрива, находится Лагерь 7-го легиона. Мы должны обыскать лагерь и найти планы битвы. Если нам это удастся, тогда мы будем знать обо всех перемещениях войск Альянса в Серебряном бору.','Найдите военные планы 7-го легиона.','<Вальден пролистывает план боя.>$B$BПохоже, что скоро должно высадиться подкрепление с кораблей, которые стоят в Гилнеасе. Краули и Кровавый Клык уже построили на юго-востоке лагерь для воинов Освободительного фронта Гилнеаса.','Обыщите труп каждого грязного дворфа.','Поговорите с лордом Вальденом в Серебряном бору.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Планы 7-го легиона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Уничтожение Погребальных Костров, несомненно, даст нам преимущество в бою, но наша главная задача – нанести непоправимый урон войскам Альянса.$B$BК юго-западу отсюда, у Стены Седогрива, находится Лагерь 7-го легиона. Мы должны обыскать лагерь и найти планы битвы. Если нам это удастся, тогда мы будем знать обо всех перемещениях войск Альянса в Серебряном бору.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите военные планы 7-го легиона.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Вальден пролистывает план боя.>$B$BПохоже, что скоро должно высадиться подкрепление с кораблей, которые стоят в Гилнеасе. Краули и Кровавый Клык уже построили на юго-востоке лагерь для воинов Освободительного фронта Гилнеаса.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Обыщите труп каждого грязного дворфа.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с лордом Вальденом в Серебряном бору.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27578,'Плоды ожиданий Морганы','Император Дагран Тауриссан полностью держит город в своих руках, управляя им со своего трона. Чтобы остановить войска дворфов, нам нужно вначале покончить с их императором.$B$BДобраться до него непросто: вначале придется пройти мимо охраны, включая великана Магмуса. Старайся идти как можно быстрее; если тебя заметят раньше, чем выполнишь задание, то весь город встанет на защиту трона.$B$BЗапомни, что двери вблизи Лицея откроются лишь тогда, когда ты зажжешь светильники при помощи факелов, взятых у хранителей пламени. Удачи!','Ликвидируйте императора Даграна Тауриссана.','У тебя получилось! У тебя действительно все получилось! Моргана столько лет ждала этого и строила планы расправы с императором.$B$BКогда Рагнарос искромсал эту местность, она потеряла свою семью и земли. Теперь же, когда с дворфами Черного Железа покончено, мы спокойно сможем отстроить новое королевство в Пылающих степях. Даже сам Повелитель Огня не сможет сокрушить стены новой столицы!$B$BПожалуйста, загляни к нам, когда все будет построено, ты станешь нашим почетным гостем. От всей души благодарю тебя, Сустабол.','Вернитесь к маршалу Максвеллу.','Пришел и его черед.','Император Дагран Тауриссан') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Плоды ожиданий Морганы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Император Дагран Тауриссан полностью держит город в своих руках, управляя им со своего трона. Чтобы остановить войска дворфов, нам нужно вначале покончить с их императором.$B$BДобраться до него непросто: вначале придется пройти мимо охраны, включая великана Магмуса. Старайся идти как можно быстрее; если тебя заметят раньше, чем выполнишь задание, то весь город встанет на защиту трона.$B$BЗапомни, что двери вблизи Лицея откроются лишь тогда, когда ты зажжешь светильники при помощи факелов, взятых у хранителей пламени. Удачи!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Ликвидируйте императора Даграна Тауриссана.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','У тебя получилось! У тебя действительно все получилось! Моргана столько лет ждала этого и строила планы расправы с императором.$B$BКогда Рагнарос искромсал эту местность, она потеряла свою семью и земли. Теперь же, когда с дворфами Черного Железа покончено, мы спокойно сможем отстроить новое королевство в Пылающих степях. Даже сам Повелитель Огня не сможет сокрушить стены новой столицы!$B$BПожалуйста, загляни к нам, когда все будет построено, ты станешь нашим почетным гостем. От всей души благодарю тебя, Сустабол.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к маршалу Максвеллу.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Пришел и его черед.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Император Дагран Тауриссан',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27579,'В тюрьму','Культ Сумеречного Молота тут трется неспроста. Мы не знаем почему, но Тал\'трак решил поведать тебе один наш секрет: у зала, где находится верховный дознаватель Герштан, прячется наш разбойник по имени Лекслорт, готовый прикончить ее, как только представится возможность.$B$BНо она слишком умна, чтобы дать ему этот шанс, так что тебе придется помочь нам. Ты же не откажешься? Иди, поговори с Лекслортом на этот счет. Я думаю, он не будет возражать.','Найдите Лекслорта.','Уходи отсюда. Если меня обнаружат, то, клянусь, я тебя зарежу на месте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В тюрьму',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Культ Сумеречного Молота тут трется неспроста. Мы не знаем почему, но Тал\'трак решил поведать тебе один наш секрет: у зала, где находится верховный дознаватель Герштан, прячется наш разбойник по имени Лекслорт, готовый прикончить ее, как только представится возможность.$B$BНо она слишком умна, чтобы дать ему этот шанс, так что тебе придется помочь нам. Ты же не откажешься? Иди, поговори с Лекслортом на этот счет. Я думаю, он не будет возражать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Лекслорта.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Уходи отсюда. Если меня обнаружат, то, клянусь, я тебя зарежу на месте.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertargetname_loc8`) VALUES (27580,'Семена раздора','Войска Альянса закрепились в юго-западной части Серебряного бора – они называют это Лагерем 7-го легиона. Наша основная задача – посеять семена раздора среди вражеских солдат. Поэтому мы должны стремительно ворваться в лагерь и убить командира, генерала Марстоуна. Его смерть не остановит продвижение войск Альянса, но подорвет боевой дух.','Убейте генерала Марстоуна.','Флот Альянса скоро прибудет сюда – и обнаружит, что его база уничтожена. Теперь переходим ко второй и самой важной части нашего плана.','Поговорите с лордом Годфри в Серебряном бору.','Генерал Марстон') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Семена раздора',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Войска Альянса закрепились в юго-западной части Серебряного бора – они называют это Лагерем 7-го легиона. Наша основная задача – посеять семена раздора среди вражеских солдат. Поэтому мы должны стремительно ворваться в лагерь и убить командира, генерала Марстоуна. Его смерть не остановит продвижение войск Альянса, но подорвет боевой дух.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте генерала Марстоуна.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Флот Альянса скоро прибудет сюда – и обнаружит, что его база уничтожена. Теперь переходим ко второй и самой важной части нашего плана.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с лордом Годфри в Серебряном бору.',`completedtext_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Генерал Марстон',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27581,'Культ Сумеречного Молота?! О, нет!','Герштан слишком хорошо охраняют, и она не так глупа, чтобы покинуть свое место, так что мне ее не прикончить.$B$BА вот тебе это по рукам.$B$BЯ тебя отблагодарю кое-чем, что я отнял у охранника.','Убейте верховного дознавателя Герштан.','Присутствие сектантов из культа Сумеречного Молота лишь осложняет нашу задачу, но ты сделал то, что от тебя требовалось. Ты заслужил награду за свою работу… и немного отдыха. Давай выбираться отсюда.','Вернитесь к Лекслорту.','Выпытайте правду у дознавателя.','Верховный дознаватель Герштан') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Культ Сумеречного Молота?! О, нет!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Герштан слишком хорошо охраняют, и она не так глупа, чтобы покинуть свое место, так что мне ее не прикончить.$B$BА вот тебе это по рукам.$B$BЯ тебя отблагодарю кое-чем, что я отнял у охранника.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте верховного дознавателя Герштан.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Присутствие сектантов из культа Сумеречного Молота лишь осложняет нашу задачу, но ты сделал то, что от тебя требовалось. Ты заслужил награду за свою работу… и немного отдыха. Давай выбираться отсюда.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лекслорту.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Выпытайте правду у дознавателя.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Верховный дознаватель Герштан',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27582,'Проникновение в Тенегорн','Боюсь, что мы бьемся напрасно. С дворфами из клана Черного Железа и так не совладать, так на их стороне еще и элементали, дающие им значительное военное преимущество.$B$BЯ хочу, чтобы ты $gпроник:проникла; в город дворфов и $gуничтожил:уничтожила; как можно больше их ключевых руководителей. Надеюсь, что это внесет смуту в их войска и переломит ход боевых действий. Обратись к Разал\'мечу за дополнительными указаниями. Он стоит справа за воротами.','Поговорите с Разал\'мечом.','За этой дверью отдыхает командующий армией Темногорна в окружении многочисленных солдат. Ты готов к операции по уничтожению?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Проникновение в Тенегорн',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Боюсь, что мы бьемся напрасно. С дворфами из клана Черного Железа и так не совладать, так на их стороне еще и элементали, дающие им значительное военное преимущество.$B$BЯ хочу, чтобы ты $gпроник:проникла; в город дворфов и $gуничтожил:уничтожила; как можно больше их ключевых руководителей. Надеюсь, что это внесет смуту в их войска и переломит ход боевых действий. Обратись к Разал\'мечу за дополнительными указаниями. Он стоит справа за воротами.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Разал\'мечом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','За этой дверью отдыхает командующий армией Темногорна в окружении многочисленных солдат. Ты готов к операции по уничтожению?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27583,'Северный фланг','Я приказала создать оборонительный периметр на северном берегу, в Скользкой бухте. Разведчики сообщают, что наги пытаются выбраться на берег именно там.$B$BКомандует операцией Гралок. Явись к нему и помоги зачистить берег!','Поговорите с Гралоком в Скользкой бухте на Сумеречном нагорье.','Тебя прислала Зела? Отлично.$B$BЕсли твоя Орда так сильна, как говорит твой вождь, ты обагришь этот берег кровью врагов.','Поговорите с Гралоком в Скользкой бухте на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Северный фланг',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я приказала создать оборонительный периметр на северном берегу, в Скользкой бухте. Разведчики сообщают, что наги пытаются выбраться на берег именно там.$B$BКомандует операцией Гралок. Явись к нему и помоги зачистить берег!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Гралоком в Скользкой бухте на Сумеречном нагорье.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебя прислала Зела? Отлично.$B$BЕсли твоя Орда так сильна, как говорит твой вождь, ты обагришь этот берег кровью врагов.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Гралоком в Скользкой бухте на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27584,'Кровь и пена','Эти проклятые наги собираются подняться вверх по реке и прийти на помощь защитникам Сумеречного бастиона. Но мы ОТОРВЕМ их рыбьи головы и СЛОМАЕМ им хребты.$B$B<Гралок втыкает свой палаш в землю.>$B$BУбей наг Черной Чешуи!','Уничтожайте налетчиков из клана Черной Чешуи и прелестниц из клана Черной Чешуи, пока не убьете 15 любых из них.','Поговорите с Гралоком в Скользкой бухте на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кровь и пена',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти проклятые наги собираются подняться вверх по реке и прийти на помощь защитникам Сумеречного бастиона. Но мы ОТОРВЕМ их рыбьи головы и СЛОМАЕМ им хребты.$B$B<Гралок втыкает свой палаш в землю.>$B$BУбей наг Черной Чешуи!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожайте налетчиков из клана Черной Чешуи и прелестниц из клана Черной Чешуи, пока не убьете 15 любых из них.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Гралоком в Скользкой бухте на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27585,'109-е подразделение','Генерал Кузня Гнева и повелитель големов Аргелмах повинны в чудовищной резне, когда было уничтожено 109-е подразделение Каргатского экспедиционного корпуса. В этом подразделении было много стоящих троллей и орков, среди которых были и мои друзья.$B$BИтак, $gюный:юная:r; |3-6($r), настало время отплатить за гибель наших собратьев.$B$BОткрой замок Тенегорна. Затем поднимайся по лестнице и, поднявшись, держись левой стороны пока не дойдешь до Западного гарнизона. Расквитайся с Кузней Гнева и Аргелмахом, не яви к ним ни капли сострадания!','Убейте генерала Кузню Гнева и повелителя големов Аргелмаха.','Выше по дороге находится таверна "Угрюмый обжора", отвратное место и скопище наших врагов, в силу своей нетрезвости непригодных к битве.$B$B<Верховная жрица Мальвадания хмурится>.$B$BВот там-то мы их и перебьем.','Вернитесь к верховной жрице Теодоре Мальвадании.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','109-е подразделение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Генерал Кузня Гнева и повелитель големов Аргелмах повинны в чудовищной резне, когда было уничтожено 109-е подразделение Каргатского экспедиционного корпуса. В этом подразделении было много стоящих троллей и орков, среди которых были и мои друзья.$B$BИтак, $gюный:юная:r; |3-6($r), настало время отплатить за гибель наших собратьев.$B$BОткрой замок Тенегорна. Затем поднимайся по лестнице и, поднявшись, держись левой стороны пока не дойдешь до Западного гарнизона. Расквитайся с Кузней Гнева и Аргелмахом, не яви к ним ни капли сострадания!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте генерала Кузню Гнева и повелителя големов Аргелмаха.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Выше по дороге находится таверна "Угрюмый обжора", отвратное место и скопище наших врагов, в силу своей нетрезвости непригодных к битве.$B$B<Верховная жрица Мальвадания хмурится>.$B$BВот там-то мы их и перебьем.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховной жрице Теодоре Мальвадании.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27586,'Ракушки на морском берегу','Когда наш корабль взорвался над портом Драконьей Пасти, я лично вытащил эти мортиры из-под обломков. Но у нас очень мало боеприпасов!$B$BИ раз уж ты все равно бегаешь по берегу, то сделай милость, набери неразорвавшихся снарядов.$B$BЭти снаряды самые лучшие – ведь ты не знаешь КОГДА ИМЕННО они взорвутся. Великолепный сюрприз для противника!','Соберите 8 невзорвавшихся снарядов мортиры на берегу Скользкой бухты.','О, да. ДА! Эти штуки ТОЧНО кого-нибудь убьют.$B$BВероятно, наг.','Снаряды у тебя? Давай их сюда!$B$BОсторожно!..','Отдайте снаряды Фергусу Агрегансу в Скользкой бухте на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ракушки на морском берегу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда наш корабль взорвался над портом Драконьей Пасти, я лично вытащил эти мортиры из-под обломков. Но у нас очень мало боеприпасов!$B$BИ раз уж ты все равно бегаешь по берегу, то сделай милость, набери неразорвавшихся снарядов.$B$BЭти снаряды самые лучшие – ведь ты не знаешь КОГДА ИМЕННО они взорвутся. Великолепный сюрприз для противника!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 невзорвавшихся снарядов мортиры на берегу Скользкой бухты.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, да. ДА! Эти штуки ТОЧНО кого-нибудь убьют.$B$BВероятно, наг.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Снаряды у тебя? Давай их сюда!$B$BОсторожно!..',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отдайте снаряды Фергусу Агрегансу в Скользкой бухте на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27587,'Зловещая вкуснятина','Знаешь, мне пригодилась бы твоя помощь.$B$BДело в том, что помимо торговли оружием я тут в Веслотопи пытаюсь организовать кое-какие развлечения. Но в водоемах на севере водятся некие "макруры", которым не по душе наши пляжные вечеринки.$B$BК лешему их! Я не позволю креветкам-переросткам мною помыкать. Более того, собираюсь нажиться на них! Принеси мне несколько хвостов макрур, и мы превратим неприятности в деньги.','Соберите 6 неповрежденных хвостов береговых макрур.','Я прямо вижу: наш собственный веслотопский лобстер-корн! Свежепойманный! Реклама прямо сама сочиняется, да? $B$BТвоя помощь неоценима, дружок. Я уже начинаю подумывать, не сделать ли твоему народу хорошие скидки...','Ты собрал хвосты? Только нецелыми их ко мне не волоки!','Вернитесь к торговому барону Сереблексу в Веслотопи на Болоте Печали.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зловещая вкуснятина',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Знаешь, мне пригодилась бы твоя помощь.$B$BДело в том, что помимо торговли оружием я тут в Веслотопи пытаюсь организовать кое-какие развлечения. Но в водоемах на севере водятся некие "макруры", которым не по душе наши пляжные вечеринки.$B$BК лешему их! Я не позволю креветкам-переросткам мною помыкать. Более того, собираюсь нажиться на них! Принеси мне несколько хвостов макрур, и мы превратим неприятности в деньги.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 6 неповрежденных хвостов береговых макрур.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я прямо вижу: наш собственный веслотопский лобстер-корн! Свежепойманный! Реклама прямо сама сочиняется, да? $B$BТвоя помощь неоценима, дружок. Я уже начинаю подумывать, не сделать ли твоему народу хорошие скидки...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты собрал хвосты? Только нецелыми их ко мне не волоки!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к торговому барону Сереблексу в Веслотопи на Болоте Печали.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27588,'Сигнал к атаке','Теперь, когда вам удалось выманить Дробителя Черепов Горобраза из Сумеречных врат, пора подать сигнал для наступления войск!','Подайте сигнал к атаке с вершины одной из башен Сумеречных врат.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сигнал к атаке',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда вам удалось выманить Дробителя Черепов Горобраза из Сумеречных врат, пора подать сигнал для наступления войск!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Подайте сигнал к атаке с вершины одной из башен Сумеречных врат.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27589,'Трактир "Угрюмый обжора"','Все посетители трактира "Угрюмый обжора" согреваются спиртным, так что они постоянно на взводе. Думаю, мы могли бы серьезно насолить дворфам, внеся хаос в это заведение.$B$BЯ хочу, чтоб ты $gввязался:ввязалась; в перепалку с тремя завсегдатаями бара. Повреди бочки, чтобы привлечь внимание Харли Чернопыха. Укради вещи, лежащие на столах, чтобы ввязаться в драку со Штоппором Наливалсом. Наконец, просто заговори с Риббли Крутипробом, и тот полезет к тебе с кулаками. Переговори с Громосердом, когда начистишь им мордахи.','Подеритесь с Харли Чернопыхом, Штоппором Наливалсом и Риббли Крутипробом.','Слышал, в "Угрюмом обжоре" нынче большой кавардак. Похоже, ты старательно подошел к делу.$B$BОднако у нас есть заботы поважнее, чем перепалки с пьяницами.','Поговорите с Громосердом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Трактир "Угрюмый обжора"',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Все посетители трактира "Угрюмый обжора" согреваются спиртным, так что они постоянно на взводе. Думаю, мы могли бы серьезно насолить дворфам, внеся хаос в это заведение.$B$BЯ хочу, чтоб ты $gввязался:ввязалась; в перепалку с тремя завсегдатаями бара. Повреди бочки, чтобы привлечь внимание Харли Чернопыха. Укради вещи, лежащие на столах, чтобы ввязаться в драку со Штоппором Наливалсом. Наконец, просто заговори с Риббли Крутипробом, и тот полезет к тебе с кулаками. Переговори с Громосердом, когда начистишь им мордахи.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Подеритесь с Харли Чернопыхом, Штоппором Наливалсом и Риббли Крутипробом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Слышал, в "Угрюмом обжоре" нынче большой кавардак. Похоже, ты старательно подошел к делу.$B$BОднако у нас есть заботы поважнее, чем перепалки с пьяницами.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Громосердом.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27590,'Сигнал к атаке','Теперь, когда вам удалось выманить Дробителя Черепов Горобраза из Сумеречных врат, пора подать сигнал для наступления войск!','Подайте сигнал к атаке с вершины одной из башен Сумеречных врат.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сигнал к атаке',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда вам удалось выманить Дробителя Черепов Горобраза из Сумеречных врат, пора подать сигнал для наступления войск!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Подайте сигнал к атаке с вершины одной из башен Сумеречных врат.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27591,'Узы Черного Железа','Расправьтесь с послом Огнехлыстом и Рок\'релом.','Мне не по силам продолжить путь в одиночку, несмотря на весь свой боевой опыт. Лицей оказался для меня непреодолимым препятствием. Твоя помощь может оказаться незаменимой.','Поговорите с полководцем Клинозубом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Узы Черного Железа',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Расправьтесь с послом Огнехлыстом и Рок\'релом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мне не по силам продолжить путь в одиночку, несмотря на весь свой боевой опыт. Лицей оказался для меня непреодолимым препятствием. Твоя помощь может оказаться незаменимой.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с полководцем Клинозубом.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27592,'Прохладительные напитки','Как оно, "$gбратан:сестренка;"? Прикинь, у нас в самом разгаре спонтанной вечеринки приключилась катастрофа!$B$BУ меня был целый ящик "Льда Сереблекса" – любимого напитка самого барона. А эти крабы взяли его и стибрили! Никогда не видел, чтобы они прикладывались к бутылке, но они уволокли этот ящик прямо под воду. Нам нужен супергерой, который бы смог вернуть наше любимое марочное бухло!$B$B<Броно многозначительно на вас смотрит.>$B$BЯ вообще-то о тебе говорю, $gбратан:сестренка;!','Принесите 10 бутылок "Льда Сереблекса", украденного иловыми крабами.','Ура, наш прохладный освежающий "Лед Сереблекса"! Даже не знаю, как тебя благодарить, дружище, за это спонтанное героическое деяние!$B$BВот тебе бутылочка в качестве искренней признательности! И не забудь сказать ВСЕМ СВОИМ ДРУЗЬЯМ, какой это отличный напиток.','Ну что, "братан", товар у тебя?','Вернитесь к Броно Калибралю на Болото Печали.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прохладительные напитки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как оно, "$gбратан:сестренка;"? Прикинь, у нас в самом разгаре спонтанной вечеринки приключилась катастрофа!$B$BУ меня был целый ящик "Льда Сереблекса" – любимого напитка самого барона. А эти крабы взяли его и стибрили! Никогда не видел, чтобы они прикладывались к бутылке, но они уволокли этот ящик прямо под воду. Нам нужен супергерой, который бы смог вернуть наше любимое марочное бухло!$B$B<Броно многозначительно на вас смотрит.>$B$BЯ вообще-то о тебе говорю, $gбратан:сестренка;!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 бутылок "Льда Сереблекса", украденного иловыми крабами.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ура, наш прохладный освежающий "Лед Сереблекса"! Даже не знаю, как тебя благодарить, дружище, за это спонтанное героическое деяние!$B$BВот тебе бутылочка в качестве искренней признательности! И не забудь сказать ВСЕМ СВОИМ ДРУЗЬЯМ, какой это отличный напиток.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, "братан", товар у тебя?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Броно Калибралю на Болото Печали.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27593,'Возрождение Коргатского экспедиционного корпуса','Император Дагран Тауриссан полностью держит город в своих руках, управляя им со своего трона. Чтобы остановить войска дворфов, нам нужно вначале покончить с их императором.$B$BДобраться до него непросто: вначале придется пройти мимо охраны, включая великана Магмуса. Старайся идти как можно быстрее; если тебя заметят раньше, чем выполнишь задание, то весь город встанет на защиту трона.$B$BЗапомни, что двери вблизи Лицея откроются лишь тогда, когда ты зажжешь светильники при помощи факелов, взятых у хранителей пламени. Удачи!','Ликвидируйте императора Даграна Тауриссана.','Вернитесь к полководцу Клинозубу.','Пришел и его черед.','Император Дагран Тауриссан') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возрождение Коргатского экспедиционного корпуса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Император Дагран Тауриссан полностью держит город в своих руках, управляя им со своего трона. Чтобы остановить войска дворфов, нам нужно вначале покончить с их императором.$B$BДобраться до него непросто: вначале придется пройти мимо охраны, включая великана Магмуса. Старайся идти как можно быстрее; если тебя заметят раньше, чем выполнишь задание, то весь город встанет на защиту трона.$B$BЗапомни, что двери вблизи Лицея откроются лишь тогда, когда ты зажжешь светильники при помощи факелов, взятых у хранителей пламени. Удачи!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Ликвидируйте императора Даграна Тауриссана.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к полководцу Клинозубу.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Пришел и его черед.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Император Дагран Тауриссан',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`) VALUES (27594,'Секретная служба Ее величества','Лорна Краули, дочь лорда Дария Краули, сейчас находится рядом со Стеной Седогрива, в лагере Освободительного фронта Гилнеаса. $B$BНаша основная задача – проникнуть в лагерь и схватить Лорну. Темная Госпожа полагает, что Лорна станет козырной картой на переговорах с Краули. Лично я считаю, что нам нужно ее убить и превратить в Отрекшуюся, но приказы Темной Госпожи обсуждению не подлежат.$B$BМы должны поторопиться, пока не прибыли основные силы Альянса.','Тебе это удалось! Наконец-то все приготовления завершены. Если Краули не примет наши условия, мы превратим его дочь в нежить.','Отведите командира Лорну Краули к леди Сильване Ветрокрылой на Рубеж Отрекшихся в Серебряном бору.','Наш козырь на переговорах') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Секретная служба Ее величества',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Лорна Краули, дочь лорда Дария Краули, сейчас находится рядом со Стеной Седогрива, в лагере Освободительного фронта Гилнеаса. $B$BНаша основная задача – проникнуть в лагерь и схватить Лорну. Темная Госпожа полагает, что Лорна станет козырной картой на переговорах с Краули. Лично я считаю, что нам нужно ее убить и превратить в Отрекшуюся, но приказы Темной Госпожи обсуждению не подлежат.$B$BМы должны поторопиться, пока не прибыли основные силы Альянса.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебе это удалось! Наконец-то все приготовления завершены. Если Краули не примет наши условия, мы превратим его дочь в нежить.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отведите командира Лорну Краули к леди Сильване Ветрокрылой на Рубеж Отрекшихся в Серебряном бору.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Наш козырь на переговорах',`questgivertextwindow_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27595,'Пророк Хадасси','Пророк Хадасси – старейший и мудрейший член племени Орсиса.$B$BОн пропал без вести, меж тем его доброе здравие – наша первейшая забота.$B$BИди в Орсис и найди его. Прислужники Ал\'акира дорого заплатят, если с Хадасси что-то случилось...','Разыщите пророка Хадасси в Орсисе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пророк Хадасси',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пророк Хадасси – старейший и мудрейший член племени Орсиса.$B$BОн пропал без вести, меж тем его доброе здравие – наша первейшая забота.$B$BИди в Орсис и найди его. Прислужники Ал\'акира дорого заплатят, если с Хадасси что-то случилось...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите пророка Хадасси в Орсисе.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27596,'Сердце горы','Добудьте "Сердце Горы".','Вернитесь к Максворту Суперблеску.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сердце горы',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте "Сердце Горы".',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Максворту Суперблеску.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27597,'Безумный Ларри','Я смотрю, ты врубаешься, $n. Ты мне спину почешешь – я тебе. Ну, точнее, не тебе, а всей вашей армии, и всего капельку тщательнее, чем вражеской! Ну, не сложно, так ведь?$B$BТак что я хочу сказать – спин ваших много. Поэтому придется тебе поскрести мою еще, и не раз. Тот, кто украл те мины, наверняка метил в наших парней на восточном берегу.$B$BОтправляйся в наш лагерь на юго-востоке и найди Безумного Ларри; он тебя введет в курс дел.','Разыщите Безумного Ларри на юго-востоке от Веслотопи.','Тебя послал Сереблекс?! Мне КОНЕЦ!$B$BАх, он велел тебе мне помочь! Ха-ха, другое дело!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Безумный Ларри',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я смотрю, ты врубаешься, $n. Ты мне спину почешешь – я тебе. Ну, точнее, не тебе, а всей вашей армии, и всего капельку тщательнее, чем вражеской! Ну, не сложно, так ведь?$B$BТак что я хочу сказать – спин ваших много. Поэтому придется тебе поскрести мою еще, и не раз. Тот, кто украл те мины, наверняка метил в наших парней на восточном берегу.$B$BОтправляйся в наш лагерь на юго-востоке и найди Безумного Ларри; он тебя введет в курс дел.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите Безумного Ларри на юго-востоке от Веслотопи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебя послал Сереблекс?! Мне КОНЕЦ!$B$BАх, он велел тебе мне помочь! Ха-ха, другое дело!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27598,'Взять за жабры','Жаблины!$B$B<Ларри в молчании уставился на вас.>$B$BНикогда не $gвидел:видела; их, что ли? Они чокнутые! Еще больше, чем я! Я взрываю все подряд за деньги, но эти ребята просто ПСИХИ!$B$BУж не знаю, откуда они, но похожи они на мерзких рыбогоблинов! Жабры, все такое! Они перебили всех моих ребят на берегу и захватили наш грузовой корабль!$B$BВыручай! Они к востоку отсюда. Пойди и избавься от этих жаблинов!','Убейте 7 жаблинов-ловцов.','Это проучит рыболицых уродцев! Отлично!','Вернитесь к Безумному Ларри в Горемрак на Болоте Печали.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Взять за жабры',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Жаблины!$B$B<Ларри в молчании уставился на вас.>$B$BНикогда не $gвидел:видела; их, что ли? Они чокнутые! Еще больше, чем я! Я взрываю все подряд за деньги, но эти ребята просто ПСИХИ!$B$BУж не знаю, откуда они, но похожи они на мерзких рыбогоблинов! Жабры, все такое! Они перебили всех моих ребят на берегу и захватили наш грузовой корабль!$B$BВыручай! Они к востоку отсюда. Пойди и избавься от этих жаблинов!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 7 жаблинов-ловцов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это проучит рыболицых уродцев! Отлично!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Безумному Ларри в Горемрак на Болоте Печали.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27599,'Все с собой не заберешь','Вся моя команда, которой, как видишь, в лагере нет, МЕРТВА! Это были добрые гоблины, но что еще хуже, так это то, что они все еще там, под водой! Это ТРАГЕДИЯ!$B$BВ смысле, печально то, что их пожитки все еще с ними! Страшно подумать: все эти материалы и монеты лежат там, бедненькие, в воде...$B$BВот что! Окажи мне услугу! Раз уж ты пойдешь сражаться с жаблинами, собери заодно и кошели моих матросов!$B$BДа ладно тебе, все равно им они ни к чему! Больше здорового прагматизма!','Соберите 6 кошелей мертвых каперов Веслотопи.','УХ ТЫ!$B$BНе знаю, к чему это я. Я легковозбудимый! Но батюшки-светы, сколько у этих ребят было добра!$B$BСмотри, хочешь вот это?','Вернитесь к Безумному Ларри в Горемрак на Болоте Печали.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Все с собой не заберешь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вся моя команда, которой, как видишь, в лагере нет, МЕРТВА! Это были добрые гоблины, но что еще хуже, так это то, что они все еще там, под водой! Это ТРАГЕДИЯ!$B$BВ смысле, печально то, что их пожитки все еще с ними! Страшно подумать: все эти материалы и монеты лежат там, бедненькие, в воде...$B$BВот что! Окажи мне услугу! Раз уж ты пойдешь сражаться с жаблинами, собери заодно и кошели моих матросов!$B$BДа ладно тебе, все равно им они ни к чему! Больше здорового прагматизма!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 6 кошелей мертвых каперов Веслотопи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','УХ ТЫ!$B$BНе знаю, к чему это я. Я легковозбудимый! Но батюшки-светы, сколько у этих ребят было добра!$B$BСмотри, хочешь вот это?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Безумному Ларри в Горемрак на Болоте Печали.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27600,'С шумом и гамом','Наш торговый фрегат все еще в море и кишит жаблинами! А-А-А!$B$BПардон. И все же! Нам нужно как-то отправить тебя туда за нашим хабаром. На корабле остался ценный груз! ЦЕННЫЙ! КАК МОЕ ОТЧЕСТВО!$B$BНа твое счастье, у меня родился отличный план! Как выйдешь из лагеря, иди вдоль северной стены... мой сынишка Джерри забросит тебя туда из нашей пушки! Если, конечно, он практиковался, а не баклуши бил!','Поговорите с Чудиком Джерри, чтобы попасть на корабль, затем разыщите все три ценных груза Безумного Ларри.','Мой первоклассный взрыватель! Мой импортный порох!$B$BИ моя... приветик! Это я просто заберу!$B$BЭто все стоит больше золота, чем на тебе надето, знаешь ли! Спасибо за помощь!','Раздобыл? Они у тебя? Из пушки тебя запускали? Гляди-ка, и целехонек!','Вернитесь к Безумному Ларри на Болото Печали.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','С шумом и гамом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наш торговый фрегат все еще в море и кишит жаблинами! А-А-А!$B$BПардон. И все же! Нам нужно как-то отправить тебя туда за нашим хабаром. На корабле остался ценный груз! ЦЕННЫЙ! КАК МОЕ ОТЧЕСТВО!$B$BНа твое счастье, у меня родился отличный план! Как выйдешь из лагеря, иди вдоль северной стены... мой сынишка Джерри забросит тебя туда из нашей пушки! Если, конечно, он практиковался, а не баклуши бил!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Чудиком Джерри, чтобы попасть на корабль, затем разыщите все три ценных груза Безумного Ларри.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мой первоклассный взрыватель! Мой импортный порох!$B$BИ моя... приветик! Это я просто заберу!$B$BЭто все стоит больше золота, чем на тебе надето, знаешь ли! Спасибо за помощь!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Раздобыл? Они у тебя? Из пушки тебя запускали? Гляди-ка, и целехонек!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Безумному Ларри на Болото Печали.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27601,'Стереть в порошок','Наши армии сошлись. Войска Краули отступают – и они еще не знают, что стало с Лорной Краули. Мы встретимся с Краули на поле боя, и я изложу ему условия капитуляции. Либо они будут приняты, либо мы перебьем их всех и разрушим их города.$B$BТы мой самый преданный солдат, и поэтому во время переговоров будешь рядом со мной. Только дай мне знать, и мы отправимся в путь.','Отправляйтесь вместе с леди Сильваной Ветрокрылой на поле боя и разгромите войска Альянса!','<Леди Сильвана Ветрокрылая морщится от боли.>$B$BЭто... еще не конец. Годфри и его союзники заплатят за свои злодеяния – как и оставшиеся войска Альянса, захватившие Лордерон.$B$BНаша работа только начинается.','Поговорите с леди Сильваной Ветрокрылой в Серебряном бору.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Стереть в порошок',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наши армии сошлись. Войска Краули отступают – и они еще не знают, что стало с Лорной Краули. Мы встретимся с Краули на поле боя, и я изложу ему условия капитуляции. Либо они будут приняты, либо мы перебьем их всех и разрушим их города.$B$BТы мой самый преданный солдат, и поэтому во время переговоров будешь рядом со мной. Только дай мне знать, и мы отправимся в путь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь вместе с леди Сильваной Ветрокрылой на поле боя и разгромите войска Альянса!',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Леди Сильвана Ветрокрылая морщится от боли.>$B$BЭто... еще не конец. Годфри и его союзники заплатят за свои злодеяния – как и оставшиеся войска Альянса, захватившие Лордерон.$B$BНаша работа только начинается.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с леди Сильваной Ветрокрылой в Серебряном бору.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27602,'Последние слова пророка','Мы все... связаны клятвой... жизнью своей защищать скипетр Орсиса.$B$BПослушай, |3-6($c), мне осталось... недолго.$B$BНайди священный ларец... на южной окраине города.$B$BНе дай им... захватить его...','Разыщите священный ларец.','Ларец заперт, а над ним прикреплена табличка с любопытными иероглифами.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Последние слова пророка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы все... связаны клятвой... жизнью своей защищать скипетр Орсиса.$B$BПослушай, |3-6($c), мне осталось... недолго.$B$BНайди священный ларец... на южной окраине города.$B$BНе дай им... захватить его...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите священный ларец.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ларец заперт, а над ним прикреплена табличка с любопытными иероглифами.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27603,'Закрытые врата','В конце зала, возведенного дворфами Черного Железа, стоят массивные врата, подобные тем, что закрывают вход в Тенегорн с другой стороны. Однако мы понятия не имеем, что скрывается за ними!$B$BНам лишь известно, что врата усиленно патрулируют дворфы из клана Ярости Горна вместе с великаном Бейл\'гором. Просто избавься от них и попробуй открыть ворота!$B$BСтрашно даже подумать о том, что находится за ними... может, это еще одна часть города, о которой мы даже не ведали! А может, и вообще ничего! Точно не знает никто.$B$BМне хочется верить, что там что-то есть...','Убейте Бейл\'гора.','Проклятье! Я просто обязана знать, что за ними скрывается! Это открытие может круто изменить мою карьеру!$B$BХм… может, стоит их подорвать…','Вернитесь к Тинки Кипеллеру','Что за этими вратами?','Бейл\'Гор') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Закрытые врата',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В конце зала, возведенного дворфами Черного Железа, стоят массивные врата, подобные тем, что закрывают вход в Тенегорн с другой стороны. Однако мы понятия не имеем, что скрывается за ними!$B$BНам лишь известно, что врата усиленно патрулируют дворфы из клана Ярости Горна вместе с великаном Бейл\'гором. Просто избавься от них и попробуй открыть ворота!$B$BСтрашно даже подумать о том, что находится за ними... может, это еще одна часть города, о которой мы даже не ведали! А может, и вообще ничего! Точно не знает никто.$B$BМне хочется верить, что там что-то есть...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Бейл\'гора.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Проклятье! Я просто обязана знать, что за ними скрывается! Это открытие может круто изменить мою карьеру!$B$BХм… может, стоит их подорвать…',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тинки Кипеллеру',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Что за этими вратами?',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Бейл\'Гор',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27604,'Джаммал\'ан Пророк','Отсеките голову пророка Джаммал\'ана.','Превосходно! Думаю, без предводительства Джаммал\'ана тролли погрязнут в междоусобицах, и Хаккар никогда не явится в наш мир.','Сумел ли ты расправиться с Джаммал\'аном? Представь доказательство его смерти.','Вернитесь к лорду Итару.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Джаммал\'ан Пророк',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отсеките голову пророка Джаммал\'ана.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Превосходно! Думаю, без предводительства Джаммал\'ана тролли погрязнут в междоусобицах, и Хаккар никогда не явится в наш мир.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Сумел ли ты расправиться с Джаммал\'аном? Представь доказательство его смерти.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лорду Итару.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27605,'Эраникус','Прикончите Эраникуса.','Вернитесь к лорду Итару.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Эраникус',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Прикончите Эраникуса.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лорду Итару.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27606,'Взорви его!','$n, идем на рыбалку! Мортиры готовы к бою, так что теперь мы сможем уничтожить командира захватчиков.$B$BКастой воинов Черной Чешуи правит Повелитель глубин Хет\'Жатар. Иди на северо-восток, к его знаменам. Когда прибудешь на место, протруби вот в эту раковину – это все равно что собачий свисток. Только для рыб.$B$BКогда появится Хет\'Жатар, я прикажу вдарить по нему из мортир. Ты увидишь цели, по которым будут стрелять орудия.$B$BЗамани Хет\'Жатара под огонь мортир и вбей его в землю!','Подуйте в раковину Хет\'Жатара, находясь рядом со знаменем Хет\'Жатара. Убейте Повелителя Глубин Хет\'Жатара. Сделать это будет легче, если вы заманите его под огонь мортир.','Бум! Бабах!$B$BЧто? Повелитель глубин уже мертв?$B$BНу, значит, можно уже перестать обстреливать его труп.','Поговорите с Фергусом Агрегансом в Скользкой бухте на Сумеречном нагорье.','Убей Хет\'Жатара! А мы поддержим тебя огнем наших пушек.','Повелитель глубин Хет\'Жатар') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Взорви его!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, идем на рыбалку! Мортиры готовы к бою, так что теперь мы сможем уничтожить командира захватчиков.$B$BКастой воинов Черной Чешуи правит Повелитель глубин Хет\'Жатар. Иди на северо-восток, к его знаменам. Когда прибудешь на место, протруби вот в эту раковину – это все равно что собачий свисток. Только для рыб.$B$BКогда появится Хет\'Жатар, я прикажу вдарить по нему из мортир. Ты увидишь цели, по которым будут стрелять орудия.$B$BЗамани Хет\'Жатара под огонь мортир и вбей его в землю!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Подуйте в раковину Хет\'Жатара, находясь рядом со знаменем Хет\'Жатара. Убейте Повелителя Глубин Хет\'Жатара. Сделать это будет легче, если вы заманите его под огонь мортир.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Бум! Бабах!$B$BЧто? Повелитель глубин уже мертв?$B$BНу, значит, можно уже перестать обстреливать его труп.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Фергусом Агрегансом в Скользкой бухте на Сумеречном нагорье.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Убей Хет\'Жатара! А мы поддержим тебя огнем наших пушек.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Повелитель глубин Хет\'Жатар',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27607,'Южный фланг','В результате заключения договора с Ордой мой народ вступит в открытое противостояние с Альянсом.$B$BОни. У нас. Получат.$B$BУже сейчас войска Альянса маршируют по полуострову, угрожая порту Драконьей Пасти.$B$BОтправляйся на юг и найди Рок\'тара – кажется, он устроил свой командный пункт на одном из разбитых кораблей. Позаботься о том, чтобы побережье осталось в наших руках.','Поговорите с Рок\'таром на Сумеречном берегу на Сумеречном нагорье.','Поговорите с Рок\'таром на Сумеречном берегу на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Южный фланг',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В результате заключения договора с Ордой мой народ вступит в открытое противостояние с Альянсом.$B$BОни. У нас. Получат.$B$BУже сейчас войска Альянса маршируют по полуострову, угрожая порту Драконьей Пасти.$B$BОтправляйся на юг и найди Рок\'тара – кажется, он устроил свой командный пункт на одном из разбитых кораблей. Позаботься о том, чтобы побережье осталось в наших руках.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Рок\'таром на Сумеречном берегу на Сумеречном нагорье.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Рок\'таром на Сумеречном берегу на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27608,'Без головы хорошо, а с четырьмя – лучше','Теперь, когда атака на Сумеречные врата началась, осталось разобраться с За\'броксом и Библи\'фодом, учениками Чо\'Галла.$B$BПо данным разведки, они находятся в Пещере учеников, небольшом логове, принадлежащем ограм, которое расположено на юго-западе Сумеречных врат.$B$BИди туда и убей их.','Добудьте четыре головы За\'брокса и Библи\'фода.','Вернитесь в Лагерь Победителя на Сумеречном нагорье и поговорите с Кассием Белым.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Без головы хорошо, а с четырьмя – лучше',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда атака на Сумеречные врата началась, осталось разобраться с За\'броксом и Библи\'фодом, учениками Чо\'Галла.$B$BПо данным разведки, они находятся в Пещере учеников, небольшом логове, принадлежащем ограм, которое расположено на юго-западе Сумеречных врат.$B$BИди туда и убей их.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте четыре головы За\'брокса и Библи\'фода.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь в Лагерь Победителя на Сумеречном нагорье и поговорите с Кассием Белым.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27609,'Без головы хорошо, а с четырьмя – лучше','Теперь, когда атака на Сумеречные врата началась, осталось разобраться с За\'броксом и Библи\'фодом, учениками Чо\'Галла.$B$BПо данным разведки, они находятся в Пещере учеников, небольшом логове, принадлежащем ограм, которое расположено на юго-западе Сумеречных врат.$B$BИди туда и убей их.','Добудьте четыре головы За\'брокса и Библи\'фода.','Вернитесь в Тукмак, что на Сумеречном нагорье, и поговорите с леди Козвинн.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Без головы хорошо, а с четырьмя – лучше',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда атака на Сумеречные врата началась, осталось разобраться с За\'броксом и Библи\'фодом, учениками Чо\'Галла.$B$BПо данным разведки, они находятся в Пещере учеников, небольшом логове, принадлежащем ограм, которое расположено на юго-западе Сумеречных врат.$B$BИди туда и убей их.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте четыре головы За\'брокса и Библи\'фода.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь в Тукмак, что на Сумеречном нагорье, и поговорите с леди Козвинн.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (27610,'Разведка на побережье','Если Альянс овладеет этим полуостровом, его войска будут угрожать порту Драконьей Пасти. Мы не должны этого допустить.$B$BНа юге есть небольшой холм, с которого прекрасно просматривается все побережье. Тот, кто завладеет холмом, получит преимущество в бою!$B$BМне нужно знать, что сейчас там происходит. Проведи разведку, двигаясь к контрольному пункту берегового плацдарма – он отмечен огромным флагом. Затем возвращайся ко мне.$B$BСам пункт захватывать не нужно – ну, разве что тебе хочется подраться.','Проведите разведку на Сумеречном берегу в окрестностях контрольного пункта берегового плацдарма. Вам не нужно его захватывать, но если вы это сделаете, то ваша сторона получит преимущество в бою, а вы – флаг PvP.','Разведка окрестностей контрольного пункта берегового плацдарма проведена','Поговорите с Рок\'таром на Сумеречном берегу на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разведка на побережье',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если Альянс овладеет этим полуостровом, его войска будут угрожать порту Драконьей Пасти. Мы не должны этого допустить.$B$BНа юге есть небольшой холм, с которого прекрасно просматривается все побережье. Тот, кто завладеет холмом, получит преимущество в бою!$B$BМне нужно знать, что сейчас там происходит. Проведи разведку, двигаясь к контрольному пункту берегового плацдарма – он отмечен огромным флагом. Затем возвращайся ко мне.$B$BСам пункт захватывать не нужно – ну, разве что тебе хочется подраться.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проведите разведку на Сумеречном берегу в окрестностях контрольного пункта берегового плацдарма. Вам не нужно его захватывать, но если вы это сделаете, то ваша сторона получит преимущество в бою, а вы – флаг PvP.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Разведка окрестностей контрольного пункта берегового плацдарма проведена',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Рок\'таром на Сумеречном берегу на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27611,'Кровь на песке','Наша цель на Сумеречном нагорье – взятие Сумеречного бастиона. Однако Альянс решил оказать сопротивление.$B$BНу что ж, значит, будем воевать!$B$BУбивай их морских пехотинцев, пока остальные не усвоят урок.','Убейте 12 пехотинцев Высокого берега на Сумеречном берегу на Сумеречном нагорье.','Отлично, отлично! Они получат по заслугам!','Поговорите с Рок\'таром на Сумеречном берегу на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кровь на песке',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наша цель на Сумеречном нагорье – взятие Сумеречного бастиона. Однако Альянс решил оказать сопротивление.$B$BНу что ж, значит, будем воевать!$B$BУбивай их морских пехотинцев, пока остальные не усвоят урок.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 пехотинцев Высокого берега на Сумеречном берегу на Сумеречном нагорье.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, отлично! Они получат по заслугам!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Рок\'таром на Сумеречном берегу на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27612,'Триумф воли','Несколько наших людей не прошли через порталы, которые должны были открыться прямо в аббатстве. И поэтому мне снова нужна твоя помощь... ведь я знаю, что ты можешь действовать скрытно и при этом не боишься вступить в бой.$B$BУ этого аббатства два крыла: в одном библиотека, а во втором – оружейная. В каждом крыле портал.$B$BОткрой портал этим ключом; тогда оставшиеся воины смогут попасть в аббатство.','Зайдите в аббатство Длани Тира и откройте Серебряные порталы в библиотечном крыле и оружейной.','Аббатство скоро падет, и тогда мы сможем двинуться дальше, к центру Длани Тира.','Поговорите с командиром рыцарей Элигором Вестником Рассвета в Длани Тира в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Триумф воли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Несколько наших людей не прошли через порталы, которые должны были открыться прямо в аббатстве. И поэтому мне снова нужна твоя помощь... ведь я знаю, что ты можешь действовать скрытно и при этом не боишься вступить в бой.$B$BУ этого аббатства два крыла: в одном библиотека, а во втором – оружейная. В каждом крыле портал.$B$BОткрой портал этим ключом; тогда оставшиеся воины смогут попасть в аббатство.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Зайдите в аббатство Длани Тира и откройте Серебряные порталы в библиотечном крыле и оружейной.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Аббатство скоро падет, и тогда мы сможем двинуться дальше, к центру Длани Тира.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с командиром рыцарей Элигором Вестником Рассвета в Длани Тира в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27613,'Убийца','История Алого ордена довольно трагична, хотя в чем-то и забавна. Когда-то Орден вел людей на войну с нежитью. А сейчас его рыцари сами напоминают оживших мертвецов, которых раньше истребляли. Что превратило их в нежить, мы не знаем, но от этого они не становятся менее опасными.$B$BИ одним из самых опасных из них является убийца по имени Рохан. По данным наших агентов, сейчас он находится на колокольне этого аббатства. Найди и убей его, $n. И постарайся при этом не погибнуть.','Убейте Рохана Убийцу на колокольне аббатства в Длани Тира.','Смерть Рохана меня немного развеселила.$B$BЗнаешь, когда-то мы с ним сражались плечом к плечу. Он был посланником Алого ордена, одним из немногих, кто много лет назад присоединился к нам в битве против Кел\'Тузада. Как быстро меняются люди...','Поговорите с командиром рыцарей Элигором Вестником Рассвета в Длани Тира в Восточных Чумных землях.','Закоренелый разбойник, беспринципный негодяй.','Рохан Убийца') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Убийца',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','История Алого ордена довольно трагична, хотя в чем-то и забавна. Когда-то Орден вел людей на войну с нежитью. А сейчас его рыцари сами напоминают оживших мертвецов, которых раньше истребляли. Что превратило их в нежить, мы не знаем, но от этого они не становятся менее опасными.$B$BИ одним из самых опасных из них является убийца по имени Рохан. По данным наших агентов, сейчас он находится на колокольне этого аббатства. Найди и убей его, $n. И постарайся при этом не погибнуть.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Рохана Убийцу на колокольне аббатства в Длани Тира.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Смерть Рохана меня немного развеселила.$B$BЗнаешь, когда-то мы с ним сражались плечом к плечу. Он был посланником Алого ордена, одним из немногих, кто много лет назад присоединился к нам в битве против Кел\'Тузада. Как быстро меняются люди...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с командиром рыцарей Элигором Вестником Рассвета в Длани Тира в Восточных Чумных землях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Закоренелый разбойник, беспринципный негодяй.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Рохан Убийца',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27614,'Спасение артефактов','Добудьте багрового кабанчика, бусы Лианны, саван Утера и печать Гавинрада.','Надеюсь, они получили хорошую трепку.','Вернитесь к командиру рыцарей Корфаксу в Длань Тира, что в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спасение артефактов',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте багрового кабанчика, бусы Лианны, саван Утера и печать Гавинрада.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Надеюсь, они получили хорошую трепку.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру рыцарей Корфаксу в Длань Тира, что в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27615,'Обрушивающий гнев','В подземельях этой казармы находится один из наиболее злобных членов Алого ордена – Матеус Обрушивающий Гнев. Его мерзкий характер отлично сочетается с обликом нежити.$B$BБыл бы я помоложе, сам бы его проткнул. Но, к сожалению, мне приходится сидеть в тылу и командовать войсками. Так что я предоставляю это удовольствие тебе.','Убейте Матеуса Обрушивающего Гнев.','Вернитесь к командиру рыцарей Корфаксу в Длань Тира, что в Восточных Чумных землях.','Жалкая, черная душонка.','Матеус Обрушивающий Гнев') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обрушивающий гнев',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В подземельях этой казармы находится один из наиболее злобных членов Алого ордена – Матеус Обрушивающий Гнев. Его мерзкий характер отлично сочетается с обликом нежити.$B$BБыл бы я помоложе, сам бы его проткнул. Но, к сожалению, мне приходится сидеть в тылу и командовать войсками. Так что я предоставляю это удовольствие тебе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Матеуса Обрушивающего Гнев.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру рыцарей Корфаксу в Длань Тира, что в Восточных Чумных землях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Жалкая, черная душонка.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Матеус Обрушивающий Гнев',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27616,'Охотник','Стрелы и пули защитников уже унесли жизни полдюжины наших людей. Я не видел лица стрелков, но мне это и не нужно. Известно, кто укрылся там, наверху.$B$BЭто Леопольд.$B$BДа, все верно, наших воинов убивает один человек. Один. И, насколько я понимаю, ты здесь тоже в одиночестве.$B$BДумаю, это будет честный бой.','Убейте Охотника Леопольда.','Одним врагом меньше. Отлично.','Поговорите с командиром рыцарей Корфаксом в Длани Тира в Восточных Чумных землях.','Умеет обращаться с любым стрелковым оружием.','Охотник Леопольд') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охотник',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Стрелы и пули защитников уже унесли жизни полдюжины наших людей. Я не видел лица стрелков, но мне это и не нужно. Известно, кто укрылся там, наверху.$B$BЭто Леопольд.$B$BДа, все верно, наших воинов убивает один человек. Один. И, насколько я понимаю, ты здесь тоже в одиночестве.$B$BДумаю, это будет честный бой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Охотника Леопольда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Одним врагом меньше. Отлично.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с командиром рыцарей Корфаксом в Длани Тира в Восточных Чумных землях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Умеет обращаться с любым стрелковым оружием.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Охотник Леопольд',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27617,'Очищение','Ты чувствуешь это? Здание уже начало очищаться от порчи!$B$BСвятое здание хочет быть святым, а Рохан и прочее отребье Алого ордена только мешают ему.$B$BТеперь, после захвата аббатства, мы еще на шаг приблизились к освобождению Длани Тира. Сообщи о результатах нашей операции Анжеле. Сейчас она, наверное, где-то в центре города, руководит штурмом собора.','Явитесь с докладом к верховному магу Анжеле Досантос в Длань Тира в Восточных Чумных землях.','Отлично. Аббатство в наших руках. Элигор не подвел.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Очищение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты чувствуешь это? Здание уже начало очищаться от порчи!$B$BСвятое здание хочет быть святым, а Рохан и прочее отребье Алого ордена только мешают ему.$B$BТеперь, после захвата аббатства, мы еще на шаг приблизились к освобождению Длани Тира. Сообщи о результатах нашей операции Анжеле. Сейчас она, наверное, где-то в центре города, руководит штурмом собора.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Явитесь с докладом к верховному магу Анжеле Досантос в Длань Тира в Восточных Чумных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично. Аббатство в наших руках. Элигор не подвел.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27618,'Победа Серебряных','Я думаю, мы нанесли достаточный урон казарме, и можно считать, что одержали победу. Командир, охотник, чернокнижник... все они убиты... не говоря уже о том, что мы захватили артефакты. Точнее... ТЕБЕ удалось их добыть.$B$BСобор пока стоит, но скоро мы это изменим. Поговори с верховным магом Анжелой Досантос – она в центральном дворе. Судьба собора – в ее руках.','Явитесь с докладом к верховному магу Анжеле Досантос в Длань Тира в Восточных Чумных землях.','Похоже, Корфакс уже выбил врага из казармы. Вечно он любит покрасоваться.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Победа Серебряных',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я думаю, мы нанесли достаточный урон казарме, и можно считать, что одержали победу. Командир, охотник, чернокнижник... все они убиты... не говоря уже о том, что мы захватили артефакты. Точнее... ТЕБЕ удалось их добыть.$B$BСобор пока стоит, но скоро мы это изменим. Поговори с верховным магом Анжелой Досантос – она в центральном дворе. Судьба собора – в ее руках.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Явитесь с докладом к верховному магу Анжеле Досантос в Длань Тира в Восточных Чумных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Похоже, Корфакс уже выбил врага из казармы. Вечно он любит покрасоваться.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27619,'Командир','Командир Маржан из Алого ордена хитра и умна, и ради победы она готова на все. Но самое главное – то, что она никогда не предаст Алый орден.$B$BДумаю, ты найдешь ее в центральной комнате казарм, под алым знаменем. Она будет сражаться до тех пор, пока не одержит победу или не умрет.$B$BПозаботься о том, чтобы она умерла.','Убейте командира Маржан из Алого ордена.','Отлично, отлично. Мы уже практически захватили казарму.','Вернитесь к командиру рыцарей Корфаксу в Длань Тира, что в Восточных Чумных землях.','Ей нечего терять.','Командир Алого ордена Маржан') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Командир',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Командир Маржан из Алого ордена хитра и умна, и ради победы она готова на все. Но самое главное – то, что она никогда не предаст Алый орден.$B$BДумаю, ты найдешь ее в центральной комнате казарм, под алым знаменем. Она будет сражаться до тех пор, пока не одержит победу или не умрет.$B$BПозаботься о том, чтобы она умерла.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте командира Маржан из Алого ордена.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, отлично. Мы уже практически захватили казарму.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру рыцарей Корфаксу в Длань Тира, что в Восточных Чумных землях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Ей нечего терять.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Командир Алого ордена Маржан',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`) VALUES (27620,'Словно крысы','Хотя я и не разделяю их методы, но не буду отрицать, что я доволен результатами. Намерения Алого ордена благие, но их фанатизм перешел всякие границы, их ослепляет ненависть.$B$BНадеюсь, то же самое не случится с нашим Братством Света.','Поговорите с Леонидом Барталомеем Чтимым в часовне Последней Надежды в Восточных Чумных землях.','О, как низко пали великие герои.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Словно крысы',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хотя я и не разделяю их методы, но не буду отрицать, что я доволен результатами. Намерения Алого ордена благие, но их фанатизм перешел всякие границы, их ослепляет ненависть.$B$BНадеюсь, то же самое не случится с нашим Братством Света.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Леонидом Барталомеем Чтимым в часовне Последней Надежды в Восточных Чумных землях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','О, как низко пали великие герои.',`questgivertextwindow_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27621,'Дозор Огнебородов','Я собирался в Дозор Огнебородов, когда подстрелили мою птицу.$B$BСумеречный Молот пошел в наступление по всему нагорью. Иногда их здания вырастали из-под земли прямо в центре наших деревень. Это был кошмар!$B$BИ в этом хаосе Огнебород один из немногих сохранял хладнокровие. Сейчас он пытается собрать эскадрилью грифонов из тех, кто остался в живых.$B$BЕсли ты хочешь, чтобы Громовой Молот стал союзником Альянса, для начала выручи Огнеборода. Он находится к западу отсюда.','Найдите Кигана Огнеборода в Дозоре Огнебородов на Сумеречном нагорье.','Хочешь присоединиться к нам, парень? Замечательно.$B$BМне нужны воины для обороны наших позиций. Помоги мне, и тогда я постараюсь найти для тебя более престижную работу.','Найдите Кигана Огнеборода в Дозоре Огнебородов на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дозор Огнебородов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я собирался в Дозор Огнебородов, когда подстрелили мою птицу.$B$BСумеречный Молот пошел в наступление по всему нагорью. Иногда их здания вырастали из-под земли прямо в центре наших деревень. Это был кошмар!$B$BИ в этом хаосе Огнебород один из немногих сохранял хладнокровие. Сейчас он пытается собрать эскадрилью грифонов из тех, кто остался в живых.$B$BЕсли ты хочешь, чтобы Громовой Молот стал союзником Альянса, для начала выручи Огнеборода. Он находится к западу отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Кигана Огнеборода в Дозоре Огнебородов на Сумеречном нагорье.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хочешь присоединиться к нам, парень? Замечательно.$B$BМне нужны воины для обороны наших позиций. Помоги мне, и тогда я постараюсь найти для тебя более престижную работу.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Найдите Кигана Огнеборода в Дозоре Огнебородов на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27622,'Большой, улучшенный крошшер','$n, я собираюсь создать улучшенный крошшер. Но мои инженеры не могут идти в зону боевых действий в одиночку.$B$BНайди сломанный крошшер на Сумеречном берегу и с его помощью подай сигнал: тогда к тебе присоединится один из моих экспертов. Затем защищай крошшер, пока мы будем им заниматься.$B$BАльянс даже ничего не сообразит! По крайней мере, пока не начнется моя маркетинговая кампания!','Найдите на Сумеречном берегу сломанный крошшер и с его помощью вызовите эксперта по металлолому из картеля Трюмных Вод. Защищайте крошшер, пока его не приведут в рабочее состояние.','Поговорите с Согом Нугатом на Сумеречном берегу на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Большой, улучшенный крошшер',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, я собираюсь создать улучшенный крошшер. Но мои инженеры не могут идти в зону боевых действий в одиночку.$B$BНайди сломанный крошшер на Сумеречном берегу и с его помощью подай сигнал: тогда к тебе присоединится один из моих экспертов. Затем защищай крошшер, пока мы будем им заниматься.$B$BАльянс даже ничего не сообразит! По крайней мере, пока не начнется моя маркетинговая кампания!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите на Сумеречном берегу сломанный крошшер и с его помощью вызовите эксперта по металлолому из картеля Трюмных Вод. Защищайте крошшер, пока его не приведут в рабочее состояние.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Согом Нугатом на Сумеречном берегу на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27623,'Колоссы-стражи','Ларец со скипетром, судя по всему, опечатан с помощью магии, так что его даже с места не сдвинуть.$B$BНа табличке над сундуком изображены две гигантские статуи с гнездами для камней – в форме звезды и полумесяца.$B$BСудя по рисунку, статуи сторожат пирамиды вроде тех, что вы видели снаружи.$B$BВозможно, стоит выйти и как следует осмотреться.','Извлеките камень луны и камень солнца из колоссов-стражей.','Вы помещаете камни в гнезда в стене.','Вы стряхиваете песок с иероглифов, но их моментально засыпает снова. Лучше поспешить.','Вернитесь к засыпанным песком иероглифам в Орсис, что в Ульдуме.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Колоссы-стражи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ларец со скипетром, судя по всему, опечатан с помощью магии, так что его даже с места не сдвинуть.$B$BНа табличке над сундуком изображены две гигантские статуи с гнездами для камней – в форме звезды и полумесяца.$B$BСудя по рисунку, статуи сторожат пирамиды вроде тех, что вы видели снаружи.$B$BВозможно, стоит выйти и как следует осмотреться.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Извлеките камень луны и камень солнца из колоссов-стражей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы помещаете камни в гнезда в стене.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы стряхиваете песок с иероглифов, но их моментально засыпает снова. Лучше поспешить.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к засыпанным песком иероглифам в Орсис, что в Ульдуме.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27624,'Упавшие статуи','Ну, вот. Даже не пришлось напрягаться.$B$BСтатуи держались на честном слове. Посильнее ткнул пальцем – они и попадали.$B$BВ общем, я их повалил, а ты давай разгребай обломки.$B$BМне что-то подсказывает, мы уже близки к разгадке.','Соберите четыре сферы: сферу утренней звезды, сферу вечерней звезды, сферу северной звезды и сферу падающей звезды.','Отлично сработано, Михалкен.$B$B<Харрисон изучает таблички.>$B$BПохоже, мы и вправду близки к разгадке.','Нашлось что-нибудь интересное, Михалкен?','Поговорите с Харрисоном Джонсом в Зале Звезд.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Упавшие статуи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну, вот. Даже не пришлось напрягаться.$B$BСтатуи держались на честном слове. Посильнее ткнул пальцем – они и попадали.$B$BВ общем, я их повалил, а ты давай разгребай обломки.$B$BМне что-то подсказывает, мы уже близки к разгадке.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите четыре сферы: сферу утренней звезды, сферу вечерней звезды, сферу северной звезды и сферу падающей звезды.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично сработано, Михалкен.$B$B<Харрисон изучает таблички.>$B$BПохоже, мы и вправду близки к разгадке.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Нашлось что-нибудь интересное, Михалкен?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Харрисоном Джонсом в Зале Звезд.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27625,'Защита Сторожки Кель\'Данил','Здесь нежить! Отрекшиеся! Они подходят все ближе и ближе и вот-вот нападут на нас... эти отвратительные существа!$b$bНаходящиеся на моем попечении юные дренеи отлично показали себя в битве с эльфами Высокодолья. Они могут себя защитить, но им нужна помощь!$b$bПожалуйста, $n, помоги им! Помоги отбросить Отрекшихся!','Убейте 16 ловчих смерти – захватчиков у Сторожки Кель\'Данил.','Такие чудовища перед лицом Света… Ты очень смелый, раз не побоялся выйти против них.','Вернитесь к Анахорету Траске к Сторожке Кель\'Данил, что во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Защита Сторожки Кель\'Данил',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Здесь нежить! Отрекшиеся! Они подходят все ближе и ближе и вот-вот нападут на нас... эти отвратительные существа!$b$bНаходящиеся на моем попечении юные дренеи отлично показали себя в битве с эльфами Высокодолья. Они могут себя защитить, но им нужна помощь!$b$bПожалуйста, $n, помоги им! Помоги отбросить Отрекшихся!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 16 ловчих смерти – захватчиков у Сторожки Кель\'Данил.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Такие чудовища перед лицом Света… Ты очень смелый, раз не побоялся выйти против них.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Анахорету Траске к Сторожке Кель\'Данил, что во Внутренних землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27626,'Документы Высокодолья','В течение долгих лет эльфы Высокодолья вели подробный архив записей. Смерти, рождения, времена года... а кроме этого важнейшие разведданные и способы связи с остальными членами Альянса.$b$bВсе документы будут разбросаны в беспорядке. Если они попадут в руки Отрекшихся, многие жизни подвергнутся риску! Прошу тебя, ты $gдолжен:должна; спасти эти документы, прежде чем их не захватила Орда...','Найдите отчет Высокодолья, записи Высокодолья и заметки Высокодолья.','Слава Свету! Мы не позволим Отрекшимся получить ни малейшей частицы информации, которую бы можно было обернуть против нас.','Вернитесь к Анахорету Траске к Сторожке Кель\'Данил, что во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Документы Высокодолья',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В течение долгих лет эльфы Высокодолья вели подробный архив записей. Смерти, рождения, времена года... а кроме этого важнейшие разведданные и способы связи с остальными членами Альянса.$b$bВсе документы будут разбросаны в беспорядке. Если они попадут в руки Отрекшихся, многие жизни подвергнутся риску! Прошу тебя, ты $gдолжен:должна; спасти эти документы, прежде чем их не захватила Орда...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите отчет Высокодолья, записи Высокодолья и заметки Высокодолья.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Слава Свету! Мы не позволим Отрекшимся получить ни малейшей частицы информации, которую бы можно было обернуть против нас.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Анахорету Траске к Сторожке Кель\'Данил, что во Внутренних землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27627,'Разноцветные тараканы','Из обломков полезли жуки-скарабеи. Очевидно, у них были гнезда в статуях.$B$BВам почему-то не хочется, чтобы эти "разноцветные тараканы" расползались по комнате, и вы решаете перебить всех скарабеев.','Убейте 5 аметистовых скарабеев, 5 сапфировых скарабеев, 5 бирюзовых скарабеев и 5 изумрудных скарабеев.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разноцветные тараканы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Из обломков полезли жуки-скарабеи. Очевидно, у них были гнезда в статуях.$B$BВам почему-то не хочется, чтобы эти "разноцветные тараканы" расползались по комнате, и вы решаете перебить всех скарабеев.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 5 аметистовых скарабеев, 5 сапфировых скарабеев, 5 бирюзовых скарабеев и 5 изумрудных скарабеев.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27628,'Доклад Фаорису','Поспешим, $n. Нужно все рассказать моему брату, королю.$B$BОн хочет остановить войну с Ал\'акиром и неферсетами. Наивно полагает, что конфликт можно разрешить дипломатическим путем...$B$BНадеюсь, когда он узнает, что здесь произошло, он передумает.','Поговорите с королем Фаорисом в Рамкахене в Ульдуме.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Доклад Фаорису',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Поспешим, $n. Нужно все рассказать моему брату, королю.$B$BОн хочет остановить войну с Ал\'акиром и неферсетами. Наивно полагает, что конфликт можно разрешить дипломатическим путем...$B$BНадеюсь, когда он узнает, что здесь произошло, он передумает.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с королем Фаорисом в Рамкахене в Ульдуме.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27629,'Голос визиря','Убедить визиря Танотепа перечить моему братцу будет ой как непросто... Его собственное положение зиждется на том, что он беспрекословно исполняет волю Фаориса.$B$BЯ мало преуспел, настаивая на открытой войне с Неферсетом.$B$BТем не менее, тебе следует с ним поговорить. Возможно, к мнению стороннего наблюдателя он и прислушается.$B$BТы найдешь визиря в Полях Ахенет, он отправился туда с деловым визитом.','Поговорите с визирем Танотепом в Полях Ахенет в Ульдуме.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Голос визиря',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Убедить визиря Танотепа перечить моему братцу будет ой как непросто... Его собственное положение зиждется на том, что он беспрекословно исполняет волю Фаориса.$B$BЯ мало преуспел, настаивая на открытой войне с Неферсетом.$B$BТем не менее, тебе следует с ним поговорить. Возможно, к мнению стороннего наблюдателя он и прислушается.$B$BТы найдешь визиря в Полях Ахенет, он отправился туда с деловым визитом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с визирем Танотепом в Полях Ахенет в Ульдуме.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27630,'Голос верховного жреца','Верховный жрец Амет – единственный, на кого мы не можем повлиять.$B$BОн проголосует в соответствии с результатами своей ворожбы, и переубедить его мы вряд ли сможем.$B$BСкажем так, либо он проголосует "за", либо "против", шансы равны.$B$BЕдинственное – как только произошло падение барьеров вокруг Ульдума, у него с предвидением стало из рук вон плохо.$B$BОн не согласится голосовать до тех пор, пока не восстановит свои способности ворожить.$B$BПоговори с ним и выясни, чем ему можно помочь.','Поговорите с верховным жрецом Аметом внутри запруды Вир\'наал в Ульдуме.','Война, говоришь...$B$BВорожба для войны – дело всегда трудное. Некоторые войны не следует начинать, даже если победа гарантирована. А в иные нужно вступать даже тогда, когда поражение представляется неизбежным.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Голос верховного жреца',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Верховный жрец Амет – единственный, на кого мы не можем повлиять.$B$BОн проголосует в соответствии с результатами своей ворожбы, и переубедить его мы вряд ли сможем.$B$BСкажем так, либо он проголосует "за", либо "против", шансы равны.$B$BЕдинственное – как только произошло падение барьеров вокруг Ульдума, у него с предвидением стало из рук вон плохо.$B$BОн не согласится голосовать до тех пор, пока не восстановит свои способности ворожить.$B$BПоговори с ним и выясни, чем ему можно помочь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с верховным жрецом Аметом внутри запруды Вир\'наал в Ульдуме.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Война, говоришь...$B$BВорожба для войны – дело всегда трудное. Некоторые войны не следует начинать, даже если победа гарантирована. А в иные нужно вступать даже тогда, когда поражение представляется неизбежным.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27631,'Голос главнокомандующего','Если мы хотим принять резолюцию о войне, решение Верховного совета должно быть единогласным.$B$BУверен, главнокомандующий Камзес согласится поддержать нас, когда узнает о том, что произошло в Орсисе.$B$BПожалуйста, поговори с ним на заставе рамкахенов и убедись, что он с нами. А мне нужно заняться подготовкой другого плана на тот случай, если наш не сработает.','Поговорите с главнокомандующим Камзесом на заставе рамкахенов в Ульдуме.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Голос главнокомандующего',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если мы хотим принять резолюцию о войне, решение Верховного совета должно быть единогласным.$B$BУверен, главнокомандующий Камзес согласится поддержать нас, когда узнает о том, что произошло в Орсисе.$B$BПожалуйста, поговори с ним на заставе рамкахенов и убедись, что он с нами. А мне нужно заняться подготовкой другого плана на тот случай, если наш не сработает.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с главнокомандующим Камзесом на заставе рамкахенов в Ульдуме.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27632,'Сын Танотепа','Всю свою жизнь я посвятил служению королю. Этот долг для меня превыше всего на свете... кроме заботы о моем сыне.$B$BТахета схватили часовые Неферсета.$B$BОни заявляют, будто мой сын вторгся в их владения. Фаорис ведет переговоры о его освобождении... однако я опасаюсь худшего.$B$BЕсли ты разыщешь моего сына, я поддержу вас.$B$BНе знаю, где они держат пленных, но я видел, как стражи сверялись с картой, собираясь идти через густую растительность.','Отберите карту дельты Вир\'наала у стражника Неферсета.','У стражников Неферсета может быть при себе карта, где сказано, куда увели Тахета.','Стражник Неферсета') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сын Танотепа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Всю свою жизнь я посвятил служению королю. Этот долг для меня превыше всего на свете... кроме заботы о моем сыне.$B$BТахета схватили часовые Неферсета.$B$BОни заявляют, будто мой сын вторгся в их владения. Фаорис ведет переговоры о его освобождении... однако я опасаюсь худшего.$B$BЕсли ты разыщешь моего сына, я поддержу вас.$B$BНе знаю, где они держат пленных, но я видел, как стражи сверялись с картой, собираясь идти через густую растительность.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отберите карту дельты Вир\'наала у стражника Неферсета.',`objectives_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','У стражников Неферсета может быть при себе карта, где сказано, куда увели Тахета.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Стражник Неферсета',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`objectives_loc8`,`completedtext_loc8`) VALUES (27633,'Уничтожьте Аватару Хаккара.','Вернитесь к лорду Итару.') ON DUPLICATE KEY UPDATE `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте Аватару Хаккара.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лорду Итару.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27634,'Бог Хаккар','Пришло время брать в плен сущность аватары Хаккара.$b$bОтнеси яйцо Хаккара в святилище Падшего Бога в Затонувшем храме Азерота. Призови силу яйца и разбуди мертвого бога.$b$bОн пошлет против тебя своих прислужников. Одолей их и нацеди из них крови Хаккари. Угаси при помощи этой крови вечный огонь, в котором заключен дух Хаккара. Когда пламя погаснет, в мир войдет аватара Хаккара.$b$BПобеди его и помести его сущность в яйцо Хаккара.','Отнесите заполненное яйцо Хаккара Йе\'кинье в Танарис.','[Deprecated] Return to Yeh\'kinya at Steamwheedle Port in Tanaris.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бог Хаккар',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пришло время брать в плен сущность аватары Хаккара.$b$bОтнеси яйцо Хаккара в святилище Падшего Бога в Затонувшем храме Азерота. Призови силу яйца и разбуди мертвого бога.$b$bОн пошлет против тебя своих прислужников. Одолей их и нацеди из них крови Хаккари. Угаси при помощи этой крови вечный огонь, в котором заключен дух Хаккара. Когда пламя погаснет, в мир войдет аватара Хаккара.$b$BПобеди его и помести его сущность в яйцо Хаккара.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите заполненное яйцо Хаккара Йе\'кинье в Танарис.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','[Deprecated] Return to Yeh\'kinya at Steamwheedle Port in Tanaris.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (27635,'Санобработка','Ну вот, теперь ты $gготов:готова; подняться на поверхность и начать новую жизнь. Главный механик с удовольствием узнает о твоем прибытии.','Завершите процедуру очищения от радиоактивных загрязнений','Поговорите с техником Брегглом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Санобработка',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну вот, теперь ты $gготов:готова; подняться на поверхность и начать новую жизнь. Главный механик с удовольствием узнает о твоем прибытии.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Завершите процедуру очищения от радиоактивных загрязнений',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с техником Брегглом.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27636,'Только ты и Матиас','Агенты ШРУ мертвы. Теперь пора разыскать мастера Матиаса Шоу.$B$BХорошо, что командир отряда сказал, где его можно найти.','Найдите мастера Матиаса Шоу в Сумеречной крепости в Сумеречном нагорье.','А где остальные?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Только ты и Матиас',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Агенты ШРУ мертвы. Теперь пора разыскать мастера Матиаса Шоу.$B$BХорошо, что командир отряда сказал, где его можно найти.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите мастера Матиаса Шоу в Сумеречной крепости в Сумеречном нагорье.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А где остальные?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27637,'Только ты и Матиас','Это серьезный удар по нашим планам. Будь проклят этот Чо\'Галл!$B$BХорошо, что командир отряда подсказал тебе, где искать мастера Шоу.','Найдите мастера Матиаса Шоу в Сумеречной крепости в Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Только ты и Матиас',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это серьезный удар по нашим планам. Будь проклят этот Чо\'Галл!$B$BХорошо, что командир отряда подсказал тебе, где искать мастера Шоу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите мастера Матиаса Шоу в Сумеречной крепости в Сумеречном нагорье.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27638,'Только ты и Гарона','Кор\'кроны мертвы. Теперь пора разыскать Гарону Полуорчиху.$B$BХорошо, что у вас есть подсказка командира отряда, где ее можно найти.','Найдите Гарону Полуорчиху в Сумеречной крепости в Сумеречном нагорье.','Где кор\'кроны?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Только ты и Гарона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кор\'кроны мертвы. Теперь пора разыскать Гарону Полуорчиху.$B$BХорошо, что у вас есть подсказка командира отряда, где ее можно найти.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Гарону Полуорчиху в Сумеречной крепости в Сумеречном нагорье.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Где кор\'кроны?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27639,'Только ты и Гарона','Это серьезный удар по нашим планам. Будь проклят этот Чо\'Галл!$B$BХорошо, у тебя есть подсказка командира отряда, где искать Гарону.','Найдите Гарону Полуорчиху в Сумеречной крепости в Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Только ты и Гарона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это серьезный удар по нашим планам. Будь проклят этот Чо\'Галл!$B$BХорошо, у тебя есть подсказка командира отряда, где искать Гарону.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Гарону Полуорчиху в Сумеречной крепости в Сумеречном нагорье.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27640,'Дунвальды не умирают','Насколько я понимаю, ты хочешь, чтобы кланы Громового Молота вступили в войну на стороне Альянса. Похоже, ты не понимаешь, во что ввязываешься.$B$BНу, а если готовишься к бою, то есть один клан, который тебе точно нужно привлечь на свою сторону. Иди на юго-запад, на другую сторону Горнила Крови, там находятся развалины Дунвальда. Селение разрушено почти до основания, но Дунвальдов это не остановит. Остается лишь найти их...','Найдите в развалинах Дунвальда оставшихся в живых членов клана Дунвальд.','Если тебе нужны Дунвальды, то можешь больше не искать. Дунвальды – это мы. По крайней мере, пара из них. Так как братьев я нигде не могу найти.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дунвальды не умирают',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Насколько я понимаю, ты хочешь, чтобы кланы Громового Молота вступили в войну на стороне Альянса. Похоже, ты не понимаешь, во что ввязываешься.$B$BНу, а если готовишься к бою, то есть один клан, который тебе точно нужно привлечь на свою сторону. Иди на юго-запад, на другую сторону Горнила Крови, там находятся развалины Дунвальда. Селение разрушено почти до основания, но Дунвальдов это не остановит. Остается лишь найти их...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите в развалинах Дунвальда оставшихся в живых членов клана Дунвальд.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Если тебе нужны Дунвальды, то можешь больше не искать. Дунвальды – это мы. По крайней мере, пара из них. Так как братьев я нигде не могу найти.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27641,'По пути к родственникам','Эй, $gпарень:девочка;! Я уверен, что Кили уже встревожила тебя рассказом про наших братьев, но они сами о себе позаботятся. Рано или поздно они вернутся сюда.$B$BНо раз уж ты собираешься встретиться с семьей, то, может, окажешь мне одну услугу?.. На землях Дунвальдов до сих пор полно слуг Сумеречного Молота. Я буду в большом долгу перед тобой, если ты напомнишь им о том, что здесь им не рады.','Убейте 20 приспешников Сумеречного Молота на земле Дунвальдов.','Вот это мне нравится, девочка.','Вернитесь в Укрытие Дунвальда на Сумеречном нагорье и поговорите с Флинном Дунвальдом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','По пути к родственникам',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эй, $gпарень:девочка;! Я уверен, что Кили уже встревожила тебя рассказом про наших братьев, но они сами о себе позаботятся. Рано или поздно они вернутся сюда.$B$BНо раз уж ты собираешься встретиться с семьей, то, может, окажешь мне одну услугу?.. На землях Дунвальдов до сих пор полно слуг Сумеречного Молота. Я буду в большом долгу перед тобой, если ты напомнишь им о том, что здесь им не рады.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 20 приспешников Сумеречного Молота на земле Дунвальдов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот это мне нравится, девочка.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь в Укрытие Дунвальда на Сумеречном нагорье и поговорите с Флинном Дунвальдом.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27642,'Разбирая обломки','Проклятые слуги Сумеречного Молота разоряли наш город с удивительным упорством. И, возможно, только нам с братьями удалось хоть как-то их сдержать. Но это нужно проверить.$B$BКогда будешь осматривать руины, ищи тела моих родичей. Я хочу знать, выжил ли кто-нибудь... или, может, кому-то удалось бежать.','Найдите 12 тел погибших Дунвальдов.','Столько погибших, да? Похоже, выжил только я с братьями. В общем, я так и думал.$B$BСпасибо за помощь.','Вернитесь в Укрытие Дунвальда на Сумеречном нагорье и поговорите с Флинном Дунвальдом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разбирая обломки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Проклятые слуги Сумеречного Молота разоряли наш город с удивительным упорством. И, возможно, только нам с братьями удалось хоть как-то их сдержать. Но это нужно проверить.$B$BКогда будешь осматривать руины, ищи тела моих родичей. Я хочу знать, выжил ли кто-нибудь... или, может, кому-то удалось бежать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите 12 тел погибших Дунвальдов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Столько погибших, да? Похоже, выжил только я с братьями. В общем, я так и думал.$B$BСпасибо за помощь.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь в Укрытие Дунвальда на Сумеречном нагорье и поговорите с Флинном Дунвальдом.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27643,'Доннели Дунвальд','Значит, ты ищешь нас. Ну, а я разыскиваю братьев. Похоже, у нас общие интересы.$B$BДоннели – это наш старший. Но хоть рост у него соответствующий, то мозги точно нет. Обычно он околачивается в руинах на севере. Может, ты его разыщешь? Мне будет очень тепло на душе, если я буду знать, что он в безопасности.','Найдите Доннели Дунвальда.','Привет! Я тебя не знаю!.. Я Доннели Дунвальд.$B$BА тебя как зовут? Кажется, я тебя не знаю... Или знаю?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Доннели Дунвальд',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Значит, ты ищешь нас. Ну, а я разыскиваю братьев. Похоже, у нас общие интересы.$B$BДоннели – это наш старший. Но хоть рост у него соответствующий, то мозги точно нет. Обычно он околачивается в руинах на севере. Может, ты его разыщешь? Мне будет очень тепло на душе, если я буду знать, что он в безопасности.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Доннели Дунвальда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Привет! Я тебя не знаю!.. Я Доннели Дунвальд.$B$BА тебя как зовут? Кажется, я тебя не знаю... Или знаю?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27644,'Эоин Дунвальд','Эоин – это один из близнецов. Очень любит выпить. Скорее всего, он где-то рядом со старым колодцем – в соседнем здании хранились запасы эля.$B$BПожалуйста, попроси его навестить сестру, которая о нем беспокоится. Если доберешься до эля раньше, чем он, то долго убеждать братца не придется.','Найдите Эоина Дунвальда.','В мире столько городов, а в них столько зданий – так почему же обрушилось именно это?!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Эоин Дунвальд',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эоин – это один из близнецов. Очень любит выпить. Скорее всего, он где-то рядом со старым колодцем – в соседнем здании хранились запасы эля.$B$BПожалуйста, попроси его навестить сестру, которая о нем беспокоится. Если доберешься до эля раньше, чем он, то долго убеждать братца не придется.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Эоина Дунвальда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','В мире столько городов, а в них столько зданий – так почему же обрушилось именно это?!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27645,'Кайден Дунвальд','Кайден – это второй близнец. Он тоже вечно томится жаждой, но отнюдь не по элю. В некотором смысле он был только рад, когда сюда заявились служители культа Сумеречного Молота – нашел выход своей агрессивности. Оно, может, и правильно. Надо же парню куда-то девать энергию!$B$BДумаю, его надо искать у торговых рядов, что неподалеку от старой кузницы. Он и раньше-то вечно там ошивался, а теперь, когда пришли эти сектанты, он там вообще поселился.$B$BНайди его и приведи ко мне. Желательно целым и невредимым.','Разыщите Кайдена Дунвальда.','Вы гляньте, кто к нам пожаловал, вся такая красивая! Тебя, что ли, Кили прислала приглядывать за стариной Кайденом? А я тут и сам неплохо справляюсь. Они же все как один недоумки.$B$BХа-ха! Здорово они прокололись, устроив засаду. Не на того дворфа нарвались, ага. Ха-ха-ха!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кайден Дунвальд',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кайден – это второй близнец. Он тоже вечно томится жаждой, но отнюдь не по элю. В некотором смысле он был только рад, когда сюда заявились служители культа Сумеречного Молота – нашел выход своей агрессивности. Оно, может, и правильно. Надо же парню куда-то девать энергию!$B$BДумаю, его надо искать у торговых рядов, что неподалеку от старой кузницы. Он и раньше-то вечно там ошивался, а теперь, когда пришли эти сектанты, он там вообще поселился.$B$BНайди его и приведи ко мне. Желательно целым и невредимым.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите Кайдена Дунвальда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы гляньте, кто к нам пожаловал, вся такая красивая! Тебя, что ли, Кили прислала приглядывать за стариной Кайденом? А я тут и сам неплохо справляюсь. Они же все как один недоумки.$B$BХа-ха! Здорово они прокололись, устроив засаду. Не на того дворфа нарвались, ага. Ха-ха-ха!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27646,'Где ты, Клювик?','Вот ведь какая беда... потерял своего грифона... Клювик! Клювик, ты где?!$B$BПоможешь найти моего грифончика? Он где-то в сарае, я знаю. Где ж ему еще быть?!$B$BКлювик?! Где ты?$B$BНадеюсь, с ним все хорошо.','Помогите Доннелли найти Клювика на Складах Дунвальда.','Вернитесь к Доннели Дунвальду на Склады Дунвальда, что на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Где ты, Клювик?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот ведь какая беда... потерял своего грифона... Клювик! Клювик, ты где?!$B$BПоможешь найти моего грифончика? Он где-то в сарае, я знаю. Где ж ему еще быть?!$B$BКлювик?! Где ты?$B$BНадеюсь, с ним все хорошо.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Помогите Доннелли найти Клювика на Складах Дунвальда.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Доннели Дунвальду на Склады Дунвальда, что на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27647,'Чем бы промочить горло','Слушай, $gдружище:милая;, либо ты мне помогаешь найти чем бы промочить горло, либо мы с тобой нежно простимся.$B$BМожет быть, сходишь на старый склад и заглянешь в подвал? Есть у меня подозрение, что старина счетовод очень даже позволял себе пропустить за работой стаканчик-другой. Наверняка у него там в подвале припрятан бочонок.$B$BЕсли чего-то найдешь, сразу же рысью – ко мне. Прямо вот сразу... не мешкая. Это срочно!','Обыщите подвал, где, по мнению Эоина Дунвальда, припрятан бочонок с выпивкой.','Клянусь пузом Доннелли! Вот это дело! А то я уже думал, что сдохну от жажды.$B$BВот, ты тоже глотни. Старина Эоин никогда не зажмет выпивку для друзей!','Трезвость – не норма жизни! Найди мне чего-нибудь выпить!','Поговорите с Эоином Дунвальдом в развалинах Дунвальда, что на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чем бы промочить горло',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слушай, $gдружище:милая;, либо ты мне помогаешь найти чем бы промочить горло, либо мы с тобой нежно простимся.$B$BМожет быть, сходишь на старый склад и заглянешь в подвал? Есть у меня подозрение, что старина счетовод очень даже позволял себе пропустить за работой стаканчик-другой. Наверняка у него там в подвале припрятан бочонок.$B$BЕсли чего-то найдешь, сразу же рысью – ко мне. Прямо вот сразу... не мешкая. Это срочно!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обыщите подвал, где, по мнению Эоина Дунвальда, припрятан бочонок с выпивкой.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Клянусь пузом Доннелли! Вот это дело! А то я уже думал, что сдохну от жажды.$B$BВот, ты тоже глотни. Старина Эоин никогда не зажмет выпивку для друзей!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Трезвость – не норма жизни! Найди мне чего-нибудь выпить!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Эоином Дунвальдом в развалинах Дунвальда, что на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27648,'И вновь за дело','Отлично, отлично. Так ты, стало быть, маешься от безделья. Я найду тебе дело.$B$BКогда будешь $gготов:готова;, скажи – и пойдем.','Отправляйтесь вместе с Кайденом Дунвальдом туда, где вас явно поджидает засада.','Здорово, правда? Вот это, я понимаю, веселье! Сколько их не колошмать, они все равно нарываются на добавку. Как же мне это нравится, страшное дело!$B$BПойду разыщу Кили, ну, чтобы она не волновалась. Но сначала еще разок пройдусь по рынку.','Вернитесь к Кайдену Дунвальду в развалины Дунвальда, что на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','И вновь за дело',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Отлично, отлично. Так ты, стало быть, маешься от безделья. Я найду тебе дело.$B$BКогда будешь $gготов:готова;, скажи – и пойдем.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь вместе с Кайденом Дунвальдом туда, где вас явно поджидает засада.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Здорово, правда? Вот это, я понимаю, веселье! Сколько их не колошмать, они все равно нарываются на добавку. Как же мне это нравится, страшное дело!$B$BПойду разыщу Кили, ну, чтобы она не волновалась. Но сначала еще разок пройдусь по рынку.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кайдену Дунвальду в развалины Дунвальда, что на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27649,'Чем больше, тем лучше','Слушай, $gприятель:милая;, раз мы такие большие друзья, может быть, сделаешь доброе дело? Уважишь старого дворфа, а?$B$BЭто развалины Дунвальда... здесь НАВЕРНЯКА есть запасы хорошего эля. Надо только пошарить по зданиям... Если вдруг что найдешь, сразу тащи ко мне, договорились? Чем больше, тем лучше. Хорошего эля, его никогда не бывает много. Доброму дворфу – доброе пойло!$B$BЯ пойду вернусь к Кили, так что тебе, вероятно, придется меня поискать. Но уж я постараюсь, чтобы ты не $gпожалел:пожалела; о потраченном времени.','Соберите 6 бочонков эля Громового Молота.','Да! Вот чего мне не хватало для счастья!$B$BСпасибо, уважила.','Где мой эль?','Вернитесь к Эоину Дунвальду в развалины Дунвальда, что на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чем больше, тем лучше',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слушай, $gприятель:милая;, раз мы такие большие друзья, может быть, сделаешь доброе дело? Уважишь старого дворфа, а?$B$BЭто развалины Дунвальда... здесь НАВЕРНЯКА есть запасы хорошего эля. Надо только пошарить по зданиям... Если вдруг что найдешь, сразу тащи ко мне, договорились? Чем больше, тем лучше. Хорошего эля, его никогда не бывает много. Доброму дворфу – доброе пойло!$B$BЯ пойду вернусь к Кили, так что тебе, вероятно, придется меня поискать. Но уж я постараюсь, чтобы ты не $gпожалел:пожалела; о потраченном времени.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 6 бочонков эля Громового Молота.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да! Вот чего мне не хватало для счастья!$B$BСпасибо, уважила.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Где мой эль?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Эоину Дунвальду в развалины Дунвальда, что на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27650,'Снова дома','Скорее разыщи Кили. Ну, чтобы она не волновалась...','Поговорите с Кили Дунвальд в Укрытии Дунвальда.','Спасибо, что собрала вместе моих братцев. С ними и так лучше не связываться, особенно когда они действуют сообща, а тут еще и сектанты Сумеречного Молота.$B$BНо теперь ты меня успокоила, и за это большое тебе спасибо. А то я ведь вся извелась.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Снова дома',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Скорее разыщи Кили. Ну, чтобы она не волновалась...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Кили Дунвальд в Укрытии Дунвальда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо, что собрала вместе моих братцев. С ними и так лучше не связываться, особенно когда они действуют сообща, а тут еще и сектанты Сумеречного Молота.$B$BНо теперь ты меня успокоила, и за это большое тебе спасибо. А то я ведь вся извелась.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27651,'Веселье по-дунвальдски','Они опять ушли. Убежали вдогонку за эттином, который возглавлял атаку на Дунвальд. Я их просила подождать. Ну, чтобы ты $gуспел:успела; догнать, но куда там! Умчались как ветер.$B$BОни побежали в ту сторону. На городскую площадь, это в самом центре руин. Так что если не хочешь пропустить веселье – ноги в руки и бегом туда!','Поговорите с Флинном Дунвальдом и помогите братьям Дунвальдам убить Дарунгу.','Спасибо за помощь. Ты – настоящий боец. Я бы приняла тебя за кого-то из Громового Молота, если бы не твои... ну, ты понимаешь...$B$BЯ знаю, тебя прислал Огнебород. Вообще-то я не питаю особой любви к этому дворфу, но когда есть общий враг, о личных симпатиях и антипатиях уже речь не идет. Если увидишь его, передай, что, когда начнется сражение, он может рассчитывать на поддержку клана Дунвальдов.','Поговорите с Флинном Дунвальдом или Кили Дунвальд в развалинах Дунвальда, что на Сумеречном нагорье.','Когда Дунвальды вместе, никому мало не покажется.','Дарунга') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Веселье по-дунвальдски',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Они опять ушли. Убежали вдогонку за эттином, который возглавлял атаку на Дунвальд. Я их просила подождать. Ну, чтобы ты $gуспел:успела; догнать, но куда там! Умчались как ветер.$B$BОни побежали в ту сторону. На городскую площадь, это в самом центре руин. Так что если не хочешь пропустить веселье – ноги в руки и бегом туда!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Флинном Дунвальдом и помогите братьям Дунвальдам убить Дарунгу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо за помощь. Ты – настоящий боец. Я бы приняла тебя за кого-то из Громового Молота, если бы не твои... ну, ты понимаешь...$B$BЯ знаю, тебя прислал Огнебород. Вообще-то я не питаю особой любви к этому дворфу, но когда есть общий враг, о личных симпатиях и антипатиях уже речь не идет. Если увидишь его, передай, что, когда начнется сражение, он может рассчитывать на поддержку клана Дунвальдов.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Флинном Дунвальдом или Кили Дунвальд в развалинах Дунвальда, что на Сумеречном нагорье.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Когда Дунвальды вместе, никому мало не покажется.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Дарунга',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27652,'Темные убийцы','Даже я стал жертвой охоты. Но это риск, на который приходится идти, когда прячешься среди овец.$B$B<Матиас пристально смотрит на вас.>$B$BСектанты Сумеречного Молота подослали ко мне своих темных убийц. Кстати, неплохие ребята. Только жалко, что мертвые. Их создают из душ самых умелых и ловких убийц.$B$BСделай мне одолжение. Разыщи этих темных и принеси мне подвески, в которых запаяны их души.','Соберите 5 подвесок темных убийц.','Даже не знаю, что мне с ними делать. Наверное, продам и пожертвую деньги в штормградский сиротский приют.$B$BТеперь остается найти извращенца, который их купит. Скорее всего, это будет какой-нибудь гоблин. Или гном-чернокнижник.','Сколько там у тебя подвесок?','Вернитесь к мастеру Матиасу Шоу к Сумеречной крепости на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Темные убийцы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Даже я стал жертвой охоты. Но это риск, на который приходится идти, когда прячешься среди овец.$B$B<Матиас пристально смотрит на вас.>$B$BСектанты Сумеречного Молота подослали ко мне своих темных убийц. Кстати, неплохие ребята. Только жалко, что мертвые. Их создают из душ самых умелых и ловких убийц.$B$BСделай мне одолжение. Разыщи этих темных и принеси мне подвески, в которых запаяны их души.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 5 подвесок темных убийц.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Даже не знаю, что мне с ними делать. Наверное, продам и пожертвую деньги в штормградский сиротский приют.$B$BТеперь остается найти извращенца, который их купит. Скорее всего, это будет какой-нибудь гоблин. Или гном-чернокнижник.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Сколько там у тебя подвесок?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру Матиасу Шоу к Сумеречной крепости на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27653,'Темные убийцы','Даже я стала жертвой охоты, |3-6($c). Но это часть игры, когда прячешься среди овец.$B$B<Гарона пристально смотрит на вас.>$B$BСумеречный Молот подослал ко мне своих темных убийц. Кстати, вполне себе милые ребята, особенно для мертвецов. Их создают из душ самых умелых и ловких убийц.$B$BСделай мне одолжение. Разыщи этих темных убийц.$B$BОни носят на шее подвески, в которых запаяны их души. Души мне как-то без надобности, а вот сами подвески, наверное, на что-нибудь да сгодятся. Принеси их мне.','Соберите 5 подвесок темных убийц.','И что же мне с ними делать? Наверное, я их расплавлю и сделаю новый кинжал, который потом всажу Чо\'Галлу в сердце.$B$BКак тебе такая идея?','Сколько там у тебя подвесок?','Вернитесь к Гароне Полуорчихе к Сумеречной крепости на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Темные убийцы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Даже я стала жертвой охоты, |3-6($c). Но это часть игры, когда прячешься среди овец.$B$B<Гарона пристально смотрит на вас.>$B$BСумеречный Молот подослал ко мне своих темных убийц. Кстати, вполне себе милые ребята, особенно для мертвецов. Их создают из душ самых умелых и ловких убийц.$B$BСделай мне одолжение. Разыщи этих темных убийц.$B$BОни носят на шее подвески, в которых запаяны их души. Души мне как-то без надобности, а вот сами подвески, наверное, на что-нибудь да сгодятся. Принеси их мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 5 подвесок темных убийц.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','И что же мне с ними делать? Наверное, я их расплавлю и сделаю новый кинжал, который потом всажу Чо\'Галлу в сердце.$B$BКак тебе такая идея?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Сколько там у тебя подвесок?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гароне Полуорчихе к Сумеречной крепости на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27654,'Истребление Сумеречного Молота','Ни одна вылазка не может считаться законченной без старинной забавы под названием "А ну-ка замочим плохих парней".$B$BА уж плохих-то парней тут в избытке: ветераны цитадели, порочные повелители стихий, сумеречные защитники... Как говорится, выбирай на свой вкус.$B$BА уж как именно их прикончить, это ты решай $gсам:сама;.','Убейте 10 ветеранов цитадели, порочных повелителей стихий и/или сумеречных защитников.','Мы не побрезгуем запачкать руки в грязи. Ну, или в крови…','Вернитесь к мастеру Матиасу Шоу к Сумеречной крепости на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Истребление Сумеречного Молота',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ни одна вылазка не может считаться законченной без старинной забавы под названием "А ну-ка замочим плохих парней".$B$BА уж плохих-то парней тут в избытке: ветераны цитадели, порочные повелители стихий, сумеречные защитники... Как говорится, выбирай на свой вкус.$B$BА уж как именно их прикончить, это ты решай $gсам:сама;.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 ветеранов цитадели, порочных повелителей стихий и/или сумеречных защитников.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мы не побрезгуем запачкать руки в грязи. Ну, или в крови…',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру Матиасу Шоу к Сумеречной крепости на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27655,'Истребление Сумеречного Молота','Нет ничего хуже, чем эти убогие недоумки из Сумеречного Молота. Ничего! Они всерьез собрались учинить конец света.$B$BВсе беды в мире – от дураков, а посему в моем личном списке кандидатов на истребление они стоят номером первым.$B$BВ общем, задачу ты $gпонял:поняла;. Тебе будет где развернуться: ветераны цитадели, порочные повелители стихий, сумеречные защитники... $B$BМеня не волнует, как именно ты их прикончишь. Мне важен результат.','Убейте 10 ветеранов цитадели, порочных повелителей стихий и/или сумеречных защитников.','Обагрить руки в крови – это даже приятно, согласен? И особенно – в крови недоумков, погрязших в самообмане и беспросветном идиотизме.','Вернитесь к Гароне Полуорчихе к Сумеречной крепости на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Истребление Сумеречного Молота',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нет ничего хуже, чем эти убогие недоумки из Сумеречного Молота. Ничего! Они всерьез собрались учинить конец света.$B$BВсе беды в мире – от дураков, а посему в моем личном списке кандидатов на истребление они стоят номером первым.$B$BВ общем, задачу ты $gпонял:поняла;. Тебе будет где развернуться: ветераны цитадели, порочные повелители стихий, сумеречные защитники... $B$BМеня не волнует, как именно ты их прикончишь. Мне важен результат.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 ветеранов цитадели, порочных повелителей стихий и/или сумеречных защитников.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Обагрить руки в крови – это даже приятно, согласен? И особенно – в крови недоумков, погрязших в самообмане и беспросветном идиотизме.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гароне Полуорчихе к Сумеречной крепости на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27656,'Крокобой','Вязкая топь просто кишит кроколисками. Кишит, слышишь? Я торговал всем, что только можно добыть из кроколиска.$B$BШкуры, зубы, хвосты, языки, глаза – всем. Я что говорю-то: ничего больше не берут. Их тут слишком много! Запасов навалом, а спроса нет.$B$BТак что раз проку от них никакого, а к тому же они порой едят моих гостей, то ты просто поубивай этих тварей, сделай одолжение. А я тут пока обсужу кое-что с твоими людьми.','Убейте 8 острозубых кроколисков.','Дело сделано? Отлично! Гора с плеч.$B$BТеперь я могу сосредоточиться на нормальном бизнесе на благо народа Болотных Волн и Каменора, уставшего от войны... и на прочей ерунде.','Вернитесь к торговому барону Сереблексу в Веслотопи на Болоте Печали.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Крокобой',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вязкая топь просто кишит кроколисками. Кишит, слышишь? Я торговал всем, что только можно добыть из кроколиска.$B$BШкуры, зубы, хвосты, языки, глаза – всем. Я что говорю-то: ничего больше не берут. Их тут слишком много! Запасов навалом, а спроса нет.$B$BТак что раз проку от них никакого, а к тому же они порой едят моих гостей, то ты просто поубивай этих тварей, сделай одолжение. А я тут пока обсужу кое-что с твоими людьми.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 острозубых кроколисков.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Дело сделано? Отлично! Гора с плеч.$B$BТеперь я могу сосредоточиться на нормальном бизнесе на благо народа Болотных Волн и Каменора, уставшего от войны... и на прочей ерунде.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к торговому барону Сереблексу в Веслотопи на Болоте Печали.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27657,'Помощь Заклинательницы земли','Я пытался исследовать артефакт Чо\'Галла, но, похоже, мои изыскания зашли в тупик. Служители культа Сумеречного Молота угнали в рабство нескольких кузнецов Громового Молота, а потом утопили их в озере, когда те закончили работу, которую их заставляли выполнять.$B$B<Матиас сплевывает.>$B$BНам нужна помощь. Есть один дреней из Служителей Земли – заклинательница земли Ева. Она сейчас на юго-западе, у рудника элементия, со своим помощником-гоблином.$B$BОни пытаются закрыть порталы элементалей, и им нужна помощь. Вот я и подумал: если мы им поможем, потом Ева тоже нас выручит.','Поговорите с заклинательницей земли Евой у входа в Элементиевые глубины в Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Помощь Заклинательницы земли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я пытался исследовать артефакт Чо\'Галла, но, похоже, мои изыскания зашли в тупик. Служители культа Сумеречного Молота угнали в рабство нескольких кузнецов Громового Молота, а потом утопили их в озере, когда те закончили работу, которую их заставляли выполнять.$B$B<Матиас сплевывает.>$B$BНам нужна помощь. Есть один дреней из Служителей Земли – заклинательница земли Ева. Она сейчас на юго-западе, у рудника элементия, со своим помощником-гоблином.$B$BОни пытаются закрыть порталы элементалей, и им нужна помощь. Вот я и подумал: если мы им поможем, потом Ева тоже нас выручит.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с заклинательницей земли Евой у входа в Элементиевые глубины в Сумеречном нагорье.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27658,'Помощь Заклинательницы земли','Я пыталась что-нибудь выяснить об артефакте Чо\'Галла, но, похоже, мои изыскания зашли в тупик. Сектанты Сумеречного Молота угнали в рабство нескольких кузнецов Громового Молота, а потом утопили их в озере, когда те закончили работу, которую их заставляли выполнять.$B$B<Гарона сплевывает.>$B$BМне претит произносить эти слова, но нам нужна помощь. Есть один дреней из Служителей Земли – заклинательница земли Ева. Она сейчас на юго-западе, у элементиевого рудника, со своим ручным гоблином.$B$BОни пытаются закрыть порталы элементалей, и им нужна помощь. Вот я и подумала: если мы им поможем, потом эта Ева и нас выручит.','Поговорите с заклинательницей земли Евой у входа в Элементиевые глубины в Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Помощь Заклинательницы земли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я пыталась что-нибудь выяснить об артефакте Чо\'Галла, но, похоже, мои изыскания зашли в тупик. Сектанты Сумеречного Молота угнали в рабство нескольких кузнецов Громового Молота, а потом утопили их в озере, когда те закончили работу, которую их заставляли выполнять.$B$B<Гарона сплевывает.>$B$BМне претит произносить эти слова, но нам нужна помощь. Есть один дреней из Служителей Земли – заклинательница земли Ева. Она сейчас на юго-западе, у элементиевого рудника, со своим ручным гоблином.$B$BОни пытаются закрыть порталы элементалей, и им нужна помощь. Вот я и подумала: если мы им поможем, потом эта Ева и нас выручит.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с заклинательницей земли Евой у входа в Элементиевые глубины в Сумеречном нагорье.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27659,'Перегрузка портала','Раньше я была смотрительницей здешних порталов Служителей Земли. Но в наше отсутствие – когда мы помогали спасать Подземье – сюда пришли служители культа Сумеречного Молота.$B$BДля охраны порталов они используют могучих Перерожденных. Но тут они здорово просчитались.$B$BИди к порталам и устрой перегрузку с пультов управления. Таким образом ты высвободишь всю энергию порталов, и это ослабит Перерожденных. Убей их всех.','Убейте ослабленного Апексара, ослабленного Эферона и ослабленного Эдемантия.','Последний портал расположен в самой глубокой шахте, но чуть позже мы разберемся и с ним.','Вернитесь к заклинательнице земли Еве в Элементиевые глубины, что на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Перегрузка портала',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Раньше я была смотрительницей здешних порталов Служителей Земли. Но в наше отсутствие – когда мы помогали спасать Подземье – сюда пришли служители культа Сумеречного Молота.$B$BДля охраны порталов они используют могучих Перерожденных. Но тут они здорово просчитались.$B$BИди к порталам и устрой перегрузку с пультов управления. Таким образом ты высвободишь всю энергию порталов, и это ослабит Перерожденных. Убей их всех.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте ослабленного Апексара, ослабленного Эферона и ослабленного Эдемантия.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Последний портал расположен в самой глубокой шахте, но чуть позже мы разберемся и с ним.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к заклинательнице земли Еве в Элементиевые глубины, что на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27660,'Дух озера','Я ничего не знаю об артефакте Чо\'Галла, но знаю, кто сможет тебе помочь.$B$BТебе нужен древний дух озера Лок Вералл, что к северу отсюда, графиня Вералл. Она ненавидит Сумеречный Молот, загрязнивший ее воды.$B$BРазыщи духа и спроси совета.','Поговорите с графиней Вералл в озере Лок Вералл в Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дух озера',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я ничего не знаю об артефакте Чо\'Галла, но знаю, кто сможет тебе помочь.$B$BТебе нужен древний дух озера Лок Вералл, что к северу отсюда, графиня Вералл. Она ненавидит Сумеречный Молот, загрязнивший ее воды.$B$BРазыщи духа и спроси совета.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с графиней Вералл в озере Лок Вералл в Сумеречном нагорье.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27661,'Повелитель Прожар','Мой давний враг, Повелитель Прожар, видимо, от большого ума решил присягнуть на верность Сумеречному Молоту.$B$BРаньше мы с ним еще как-то сосуществовали – в состоянии шаткого перемирия, – но теперь, когда он переметнулся к врагам, у меня просто нет выбора, кроме как прикончить предателя. Тебе нужна информация от мертвого дворфа? Ты получишь ее, если убьешь Повелителя Прожара.$B$BИщи его в Преисподней Прожара на юго-востоке отсюда.','Убейте Повелителя Прожара.','Вернитесь к графине Вералл в озеро Лок Вералл на Сумеречном нагорье.','Убейте его, чтобы графиня Вералл была довольна.','Повелитель Прожар') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Повелитель Прожар',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мой давний враг, Повелитель Прожар, видимо, от большого ума решил присягнуть на верность Сумеречному Молоту.$B$BРаньше мы с ним еще как-то сосуществовали – в состоянии шаткого перемирия, – но теперь, когда он переметнулся к врагам, у меня просто нет выбора, кроме как прикончить предателя. Тебе нужна информация от мертвого дворфа? Ты получишь ее, если убьешь Повелителя Прожара.$B$BИщи его в Преисподней Прожара на юго-востоке отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Повелителя Прожара.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к графине Вералл в озеро Лок Вералл на Сумеречном нагорье.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Убейте его, чтобы графиня Вералл была довольна.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Повелитель Прожар',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27662,'Освобождение элементалей','Слушай, если я в чем-нибудь и разбираюсь, так это в элементалях. Я их действительно понимаю. Знаю, как они чувствуют. И могу сказать определенно: им не нравится быть рабами! Совершенно не нравится!$B$BСобственно, я вот о чем... Если ты освободишь порабощенных элементалей, они, скорее всего, тут же набросятся на своих бывших хозяев. А элементали страшны в гневе, уж поверь мне на слово.$B$BПо-моему, это хороший план. А ты как думаешь, $n?','Убейте и тем самым освободите 10 порабощенных элементалей на Сумеречной крепости.','Ну, что я тебе говорил! Элементали, они не такие уж и плохие, а?','Вернитесь к посвященному Клондацку в Элементиевые глубины, что на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Освобождение элементалей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слушай, если я в чем-нибудь и разбираюсь, так это в элементалях. Я их действительно понимаю. Знаю, как они чувствуют. И могу сказать определенно: им не нравится быть рабами! Совершенно не нравится!$B$BСобственно, я вот о чем... Если ты освободишь порабощенных элементалей, они, скорее всего, тут же набросятся на своих бывших хозяев. А элементали страшны в гневе, уж поверь мне на слово.$B$BПо-моему, это хороший план. А ты как думаешь, $n?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте и тем самым освободите 10 порабощенных элементалей на Сумеречной крепости.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну, что я тебе говорил! Элементали, они не такие уж и плохие, а?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к посвященному Клондацку в Элементиевые глубины, что на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27663,'На вкус как бегун','Эй ты! Да, ты! Хочешь, замолвлю за тебя словечко торговому барону? Тогда выручай!$B$BСлыхал, это ты $gраздобыл:раздобыла; хвосты макрур. Они вкусны, не спорю, но для приготовления настоящего болотного блюда их мало. Для моего супа нужны птичьи ноги!$B$BВ Горемраке недалеко от города обитают болотолюбивые долгоноги. Мне нужны самые жирные ножки, какие только сможешь добыть!','Соберите 9 огромных ножек болотолюбивых долгоногов.','О, отлично, отлично! То, что нужно.','Вернитесь к Пьеру Рыбачелло в Веслотопи на Болоте Печали.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На вкус как бегун',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эй ты! Да, ты! Хочешь, замолвлю за тебя словечко торговому барону? Тогда выручай!$B$BСлыхал, это ты $gраздобыл:раздобыла; хвосты макрур. Они вкусны, не спорю, но для приготовления настоящего болотного блюда их мало. Для моего супа нужны птичьи ноги!$B$BВ Горемраке недалеко от города обитают болотолюбивые долгоноги. Мне нужны самые жирные ножки, какие только сможешь добыть!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 9 огромных ножек болотолюбивых долгоногов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, отлично, отлично! То, что нужно.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Пьеру Рыбачелло в Веслотопи на Болоте Печали.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27668,'Будь внимательнее!','Слушай, |3-6($r)... Ты не думай, я тебе за все очень благодарен, но сейчас дела у нас идут неважно.$B$BТебе надо быть внимательнее!$B$BТы только что спокойно $gпроплыл:проплыла; мимо разбитого ящика Альянса. А в нем наверняка полно всякой полезной всячины.$B$BДавай-ка ты вернешься и посмотришь повнимательнее, а?','Назгрим хочет, чтобы вы проверили содержимое разбитого ящика Альянса, лежащего к северу от Серпантина Бессмертного.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Будь внимательнее!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слушай, |3-6($r)... Ты не думай, я тебе за все очень благодарен, но сейчас дела у нас идут неважно.$B$BТебе надо быть внимательнее!$B$BТы только что спокойно $gпроплыл:проплыла; мимо разбитого ящика Альянса. А в нем наверняка полно всякой полезной всячины.$B$BДавай-ка ты вернешься и посмотришь повнимательнее, а?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Назгрим хочет, чтобы вы проверили содержимое разбитого ящика Альянса, лежащего к северу от Серпантина Бессмертного.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27669,'Почетная миссия','Похоже, теперь остается лишь разместить сферы на пьедесталах по четырем углам этого механизма.$B$BТы хоть понимаешь, ЧТО мы нашли?! Это же величайшее археологическое открытие во всей новейшей истории!$B$B<Харрисон внимательно смотрит на вас, а потом отдает вам сферы.>$B$BДавай, $n. Ты $gзаслужил:заслужила;.$B$BБез тебя мы бы не совершили это открытие.','Разложите сферы Звезд по углам механизма в Зале Звезд.','Только посмотри, как красиво!$B$BНо в данном случае красота – это дело десятое. Нас ждет еще много открытий…$B$BОчень много.','Поговорите с Харрисоном Джонсом у Обелиска Звезд.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Почетная миссия',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Похоже, теперь остается лишь разместить сферы на пьедесталах по четырем углам этого механизма.$B$BТы хоть понимаешь, ЧТО мы нашли?! Это же величайшее археологическое открытие во всей новейшей истории!$B$B<Харрисон внимательно смотрит на вас, а потом отдает вам сферы.>$B$BДавай, $n. Ты $gзаслужил:заслужила;.$B$BБез тебя мы бы не совершили это открытие.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разложите сферы Звезд по углам механизма в Зале Звезд.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Только посмотри, как красиво!$B$BНо в данном случае красота – это дело десятое. Нас ждет еще много открытий…$B$BОчень много.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Харрисоном Джонсом у Обелиска Звезд.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27670,'В плену обстоятельств','Убейте 6 безумных лепрогномов.','Поговорите с Невином Крутилкинсом в Гномрегане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В плену обстоятельств',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 6 безумных лепрогномов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Невином Крутилкинсом в Гномрегане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27671,'Позаботиться о выживших','Если мы будем медлить, ни мои люди, ни спасенные не выберутся отсюда живыми. Я дам тебе наш аварийный маяк для телепортации. Сил и боеприпасов у нас достаточно, мы сможем пробиться наверх, но вот этим выжившим это не по плечу.$b$bВоспользуйся маяком, чтобы обеспечить им возможность телепортироваться в безопасное место, обустроенное моими людьми. Когда сделаешь это, сообщи мне, и мы примем меры для переправки тебя на поверхность.','Воспользуйтесь маяком телепортации, чтобы телепортировать в безопасное место 6 выживших.','Поговорите с Карво Рвизасовом в Гномрегане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Позаботиться о выживших',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если мы будем медлить, ни мои люди, ни спасенные не выберутся отсюда живыми. Я дам тебе наш аварийный маяк для телепортации. Сил и боеприпасов у нас достаточно, мы сможем пробиться наверх, но вот этим выжившим это не по плечу.$b$bВоспользуйся маяком, чтобы обеспечить им возможность телепортироваться в безопасное место, обустроенное моими людьми. Когда сделаешь это, сообщи мне, и мы примем меры для переправки тебя на поверхность.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь маяком телепортации, чтобы телепортировать в безопасное место 6 выживших.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Карво Рвизасовом в Гномрегане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (27672,'Чертог Хаз\'Мула','В Зале Карт есть одна дверь... Как я понимаю, она как раз и ведет в легендарный чертог Хаз\'Мула. Кто знает, какие секреты там сокрыты!$B$BОднако известно, что вход охраняет Иронайа, Страж Титанов, наделенная действительно титанической силой. Если ты собираешься разгадать секреты Ульдамана, тебе придется убить ее!','Уничтожьте Иронайю.','За чертог можешь не волноваться, мои ребята там все проверят! А у тебя есть дела поважнее!','Вернитесь к старшему геологу Дардину.','Да!','Старший геолог Дардин') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чертог Хаз\'Мула',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В Зале Карт есть одна дверь... Как я понимаю, она как раз и ведет в легендарный чертог Хаз\'Мула. Кто знает, какие секреты там сокрыты!$B$BОднако известно, что вход охраняет Иронайа, Страж Титанов, наделенная действительно титанической силой. Если ты собираешься разгадать секреты Ульдамана, тебе придется убить ее!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте Иронайю.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','За чертог можешь не волноваться, мои ребята там все проверят! А у тебя есть дела поважнее!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старшему геологу Дардину.',`completedtext_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Да!',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Старший геолог Дардин',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27673,'Важно то, что внутри','Творцы создали двух древних каменных хранителей для защиты Ульдамана от возможных вторжений и наблюдения за текущей работой системы, пока Иронайа и Аркедас спят. Один – тот, что в Храмовом зале – работает исправно, но второй – в пещере Эхомок – испорчен.$B$BБоюсь, что его специально вывели из строя. Скорее всего, кто-то из Древних Богов. Помоги мне разобраться. Разбей Хранителей и принеси мне их энергетические сердечники. И тогда мы поймем, в чем тут дело.','Раздобудьте обсидиановый энергетический сердечник и энергетический сердечник титанов.','Ну что, где сердечники? Где эти треклятые сердечники?!$B$B<Канд делает глубокий вдох.>$B$BПрошу прощения. Просто я весь на взводе... Тебе удалось добыть энергетические сердечники стражей?','Вернитесь к Канду Искателю Песков.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Важно то, что внутри',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Творцы создали двух древних каменных хранителей для защиты Ульдамана от возможных вторжений и наблюдения за текущей работой системы, пока Иронайа и Аркедас спят. Один – тот, что в Храмовом зале – работает исправно, но второй – в пещере Эхомок – испорчен.$B$BБоюсь, что его специально вывели из строя. Скорее всего, кто-то из Древних Богов. Помоги мне разобраться. Разбей Хранителей и принеси мне их энергетические сердечники. И тогда мы поймем, в чем тут дело.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте обсидиановый энергетический сердечник и энергетический сердечник титанов.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, где сердечники? Где эти треклятые сердечники?!$B$B<Канд делает глубокий вдох.>$B$BПрошу прощения. Просто я весь на взводе... Тебе удалось добыть энергетические сердечники стражей?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Канду Искателю Песков.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (27674,'На поверхность','Приятно снова видеть тебя, $n. Без твоей помощи в этот раз у нас бы не было столько спасенных из Гномрегана. Все будут ужасно рады познакомиться с тобой и услышать твою историю.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На поверхность',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Приятно снова видеть тебя, $n. Без твоей помощи в этот раз у нас бы не было столько спасенных из Гномрегана. Все будут ужасно рады познакомиться с тобой и услышать твою историю.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (27675,'Поддельные документы','Найдите жителя Штормграда, который примет ваши поддельные документы.','Найдите жителя Штормграда, который примет ваши поддельные документы.','<Вы отдаете поддельные документы и обмениваетесь буквально парой слов; ваше мастерство говорит само за себя.>','У тебя есть что-нибудь для меня?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поддельные документы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Найдите жителя Штормграда, который примет ваши поддельные документы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите жителя Штормграда, который примет ваши поддельные документы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Вы отдаете поддельные документы и обмениваетесь буквально парой слов; ваше мастерство говорит само за себя.>',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У тебя есть что-нибудь для меня?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27676,'За закрытыми дверьми','Галганн Огнемолот и его банда дворфов из клана Черного Железа заняли третий раскоп и охраняют какую-то дверь, о которой мы ничего не знаем! Они мешают нам работать. Причем их здесь вообще быть не должно. Только у Лиги исследователей есть официальное разрешение на изучение артефактов на территории Ульдамана!$B$BИди на третий раскоп и разгони эту шайку, чтобы мы могли спокойно работать. Я хочу знать, что скрывается за той дверью!','Убейте Галганна Огнемолота.','Замечательно! Ты молодец! Сейчас мы узнаем, какие тайны хранит третий раскоп!','Вернитесь к Ольге Преданной Рунам.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','За закрытыми дверьми',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Галганн Огнемолот и его банда дворфов из клана Черного Железа заняли третий раскоп и охраняют какую-то дверь, о которой мы ничего не знаем! Они мешают нам работать. Причем их здесь вообще быть не должно. Только у Лиги исследователей есть официальное разрешение на изучение артефактов на территории Ульдамана!$B$BИди на третий раскоп и разгони эту шайку, чтобы мы могли спокойно работать. Я хочу знать, что скрывается за той дверью!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Галганна Огнемолота.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Замечательно! Ты молодец! Сейчас мы узнаем, какие тайны хранит третий раскоп!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ольге Преданной Рунам.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (27677,'Аркедас, древний Каменный Страж','Поиск сокровищ – это не главная цель похода в Ульдаман. Диски Норганнона – вот что мы ищем на самом деле! Они ценнее любых сокровищ, потому что хранят великие тайны древних Творцов. Тайны, которые могут совершить радикальный переворот в наших взглядах на мир...$B$BНо вот в чем загвоздка: просто так эти диски не взять. Они под надежной охраной. Их стережет Аркедас, древнее и могучее существо, созданное Творцами. Причем в его распоряжении целое войско. И все равно я хочу, чтобы ты $gуничтожил:уничтожила; Аркедаса и $gдобыл:добыла; эти древние диски для Лиги исследователей.','Убейте Аркедаса.','Ты молодец! А теперь прочитай эти диски и собери максимум данных!','Вернитесь к старшему геологу Дардину.','Все дело в дисках!','Аркедас','У тебя получилось!','Старший геолог Дардин') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Аркедас, древний Каменный Страж',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Поиск сокровищ – это не главная цель похода в Ульдаман. Диски Норганнона – вот что мы ищем на самом деле! Они ценнее любых сокровищ, потому что хранят великие тайны древних Творцов. Тайны, которые могут совершить радикальный переворот в наших взглядах на мир...$B$BНо вот в чем загвоздка: просто так эти диски не взять. Они под надежной охраной. Их стережет Аркедас, древнее и могучее существо, созданное Творцами. Причем в его распоряжении целое войско. И все равно я хочу, чтобы ты $gуничтожил:уничтожила; Аркедаса и $gдобыл:добыла; эти древние диски для Лиги исследователей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Аркедаса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты молодец! А теперь прочитай эти диски и собери максимум данных!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старшему геологу Дардину.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Все дело в дисках!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Аркедас',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','У тебя получилось!',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Старший геолог Дардин',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`) VALUES (27678,'Платиновые диски','Главные сокровища этого чертога – четыре огромных платиновых диска, каждый из которых украшен многочисленными символами неизвестного происхождения. Когда вы касаетесь их, у вас покалывает пальцы, и перед вами возникает каменный страж.$B$B"Приветствую! Я – хранитель знаний. Создание земельников было подробно описано и сохранено на Дисках Норганнона."$B$BВы проникли в сокровищницу никому прежде неизвестных знаний!','Поговорите с каменным стражем и запомните все, что он расскажем вам. Затем расскажите старшему геологу Дардину о том, что вы узнали.','Выслушайте каменного стража') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Платиновые диски',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Главные сокровища этого чертога – четыре огромных платиновых диска, каждый из которых украшен многочисленными символами неизвестного происхождения. Когда вы касаетесь их, у вас покалывает пальцы, и перед вами возникает каменный страж.$B$B"Приветствую! Я – хранитель знаний. Создание земельников было подробно описано и сохранено на Дисках Норганнона."$B$BВы проникли в сокровищницу никому прежде неизвестных знаний!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с каменным стражем и запомните все, что он расскажем вам. Затем расскажите старшему геологу Дардину о том, что вы узнали.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Выслушайте каменного стража',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questturntextwindow_loc8`) VALUES (27679,'Чертог Хаз\'Мула','В Зале Карт есть одна дверь... Как я понимаю, она как раз и ведет в легендарный чертог Хаз\'Мула. Кто знает, какие секреты там сокрыты.$B$BОднако известно, что вход охраняет Иронайа, Страж Титанов, наделенная действительно титанической силой. Чтобы попасть туда, тебе придется убить ее.','Уничтожьте Иронайю.','Вернитесь к главному дознавателю Тей\'телану Кровавому Взору.','Очень даже неплохо.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чертог Хаз\'Мула',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В Зале Карт есть одна дверь... Как я понимаю, она как раз и ведет в легендарный чертог Хаз\'Мула. Кто знает, какие секреты там сокрыты.$B$BОднако известно, что вход охраняет Иронайа, Страж Титанов, наделенная действительно титанической силой. Чтобы попасть туда, тебе придется убить ее.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте Иронайю.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к главному дознавателю Тей\'телану Кровавому Взору.',`completedtext_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Очень даже неплохо.',`questturntextwindow_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`) VALUES (27680,'Аркедас, древний Каменный Страж','Поиск сокровищ – это не главная цель похода в Ульдаман. Диски Норганнона, вот что мы ищем на самом деле! Эти диски – ценнее любых сокровищ. И не потому, что они из платины. На них хранятся великие тайны древних Творцов. Тайны, которые могут даровать нам небывалую силу и мощь.$B$BНо просто так эти диски не достать. Они под надежной охраной. Их стережет Аркедас, древнее и могучее существо, созданное Творцами. И он там не один. В его распоряжении – целое войско. Но все равно я хочу, чтобы ты $gуничтожил:уничтожила; Аркедаса и $gдобыл:добыла; эти древние диски для Реликвария.','Уничтожьте Аркедаса.','Вернитесь к старшему геологу Дардину.','Диски – это ключ к разгадке.','Аркедас','Прекрасно.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Аркедас, древний Каменный Страж',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Поиск сокровищ – это не главная цель похода в Ульдаман. Диски Норганнона, вот что мы ищем на самом деле! Эти диски – ценнее любых сокровищ. И не потому, что они из платины. На них хранятся великие тайны древних Творцов. Тайны, которые могут даровать нам небывалую силу и мощь.$B$BНо просто так эти диски не достать. Они под надежной охраной. Их стережет Аркедас, древнее и могучее существо, созданное Творцами. И он там не один. В его распоряжении – целое войско. Но все равно я хочу, чтобы ты $gуничтожил:уничтожила; Аркедаса и $gдобыл:добыла; эти древние диски для Реликвария.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте Аркедаса.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старшему геологу Дардину.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Диски – это ключ к разгадке.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Аркедас',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Прекрасно.',`questturntextwindow_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27681,'За закрытыми дверьми','Галганн Огнемолот и его банда дворфов из клана Черного Железа заняли третий раскоп и охраняют какую-то дверь, о которой мы ничего не знаем! Они мешают нам работать. Причем их здесь вообще быть не должно. Только у Реликвария есть официальное разрешение на изучение артефактов на территории Ульдамана!$B$BИди на третий раскоп и разгони эту шайку, чтобы мы могли спокойно работать. Я хочу знать, что скрывается за той дверью!','Убейте Галганна Огнемолота.','Отлично сработано. Теперь мы узнаем, какие тайны хранит этот третий раскоп! И нам никто не помешает!','Вернитесь к Лидии Солнечное Сияние.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','За закрытыми дверьми',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Галганн Огнемолот и его банда дворфов из клана Черного Железа заняли третий раскоп и охраняют какую-то дверь, о которой мы ничего не знаем! Они мешают нам работать. Причем их здесь вообще быть не должно. Только у Реликвария есть официальное разрешение на изучение артефактов на территории Ульдамана!$B$BИди на третий раскоп и разгони эту шайку, чтобы мы могли спокойно работать. Я хочу знать, что скрывается за той дверью!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Галганна Огнемолота.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично сработано. Теперь мы узнаем, какие тайны хранит этот третий раскоп! И нам никто не помешает!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лидии Солнечное Сияние.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27682,'Душа просит минералов!','Титаны создали двух древних каменных хранителей для защиты Ульдамана от возможных вторжений и наблюдения за текущей работой системы, пока Иронайа и Аркедас спят. Один – тот, что в Храмовом зале – работает исправно, но второй – в пещере Эхомок – испорчен.$B$BПодозреваю, что его специально вывели из строя. Скорее всего, кто-то из Древних Богов. Сейчас и проверим мою догадку. Разбей этих хранителей и принеси мне их энергетические сердечники. И мы все узнаем.','Раздобудьте обсидиановый энергетический сердечник и энергетический сердечник титанов.','В этих древних сердечниках больше энергии, чем в большинстве батарей, на которых работают наши собственные стражи. За столько веков они даже не разрядились!$B$BСпасибо. Это действительно ценная находка.','Вернитесь к Аорену Солнечному Сиянию.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Душа просит минералов!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Титаны создали двух древних каменных хранителей для защиты Ульдамана от возможных вторжений и наблюдения за текущей работой системы, пока Иронайа и Аркедас спят. Один – тот, что в Храмовом зале – работает исправно, но второй – в пещере Эхомок – испорчен.$B$BПодозреваю, что его специально вывели из строя. Скорее всего, кто-то из Древних Богов. Сейчас и проверим мою догадку. Разбей этих хранителей и принеси мне их энергетические сердечники. И мы все узнаем.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте обсидиановый энергетический сердечник и энергетический сердечник титанов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','В этих древних сердечниках больше энергии, чем в большинстве батарей, на которых работают наши собственные стражи. За столько веков они даже не разрядились!$B$BСпасибо. Это действительно ценная находка.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аорену Солнечному Сиянию.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27683,'В лесу','Сегодня по городу прошла удивительно странная компания. Женщина-ворген на телеге, полной сундуков и ящиков, рядом с ней кровавый эльф, а за ними бежал дворф-паладин, выкрикивавший самые цветистые ругательства, которые мне когда-либо приходилось слышать.$B$BКажется, они направлялись в Восточные Чумные земли, но, думаю, сейчас только-только добрались до реки Тондрорил. Интересно, куда они шли? И зачем?','Найдите женщину-воргена на берегу реки Тондрорил в Восточных Чумных землях.','Да?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В лесу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сегодня по городу прошла удивительно странная компания. Женщина-ворген на телеге, полной сундуков и ящиков, рядом с ней кровавый эльф, а за ними бежал дворф-паладин, выкрикивавший самые цветистые ругательства, которые мне когда-либо приходилось слышать.$B$BКажется, они направлялись в Восточные Чумные земли, но, думаю, сейчас только-только добрались до реки Тондрорил. Интересно, куда они шли? И зачем?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите женщину-воргена на берегу реки Тондрорил в Восточных Чумных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27684,'Гости','Мои агенты на участке Целителей Земли сообщают, что скоро к нам прибудут гости – отряд паладинов, который возглавляет не кто-нибудь, а купец-ворген. Более того – женщина-ворген. Я с нетерпением жду встречи с ними. Особенно с одним.$B$BНе проведаешь их? Точно не знаю, но думаю, их можно встретить к западу отсюда, у реки Тондрорил.','Найдите женщину-воргена на берегу реки Тондрорил в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гости',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мои агенты на участке Целителей Земли сообщают, что скоро к нам прибудут гости – отряд паладинов, который возглавляет не кто-нибудь, а купец-ворген. Более того – женщина-ворген. Я с нетерпением жду встречи с ними. Особенно с одним.$B$BНе проведаешь их? Точно не знаю, но думаю, их можно встретить к западу отсюда, у реки Тондрорил.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите женщину-воргена на берегу реки Тондрорил в Восточных Чумных землях.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27685,'Добрые дела не бросают','Привет, $gмалой:дорогуша;.$B$BМеня звать Рендел.$B$BПохоже, мы со старушкой Моаной прибыли как раз вовремя, верно говорю?$B$BЭрунак не шутки шутил, когда говорил, что положеньице тут – пан или пропал!$B$BНу вот... мы так спешили, что вынуждены были бросить одно дельце на востоке.$B$BПонимаешь, там одна дамочка в смертельной опасности. Нам пришлось ее оставить возле небольшого источника воздуха, чтобы поскорее прийти к вам на выручку.$B$BСходи помоги ей, покуда еще не поздно.','Поговорите с Адаррой в лесу Келп’тар.','Наконец-то...$B$BНе знаю, сколько бы я еще продержалась!','Помогите!','Адарра') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Добрые дела не бросают',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Привет, $gмалой:дорогуша;.$B$BМеня звать Рендел.$B$BПохоже, мы со старушкой Моаной прибыли как раз вовремя, верно говорю?$B$BЭрунак не шутки шутил, когда говорил, что положеньице тут – пан или пропал!$B$BНу вот... мы так спешили, что вынуждены были бросить одно дельце на востоке.$B$BПонимаешь, там одна дамочка в смертельной опасности. Нам пришлось ее оставить возле небольшого источника воздуха, чтобы поскорее прийти к вам на выручку.$B$BСходи помоги ей, покуда еще не поздно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Адаррой в лесу Келп’тар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Наконец-то...$B$BНе знаю, сколько бы я еще продержалась!',`offerrewardtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Помогите!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Адарра',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (27686,'Поддельные документы','Найдите жителя Оргриммара, который примет ваши поддельные документы.','Найдите жителя Оргриммара, который примет ваши поддельные документы.','<Вы отдаете поддельные документы и обмениваетесь буквально парой слов; ваше искусное умение говорит само за себя.>','У тебя ко мне какое-то дело?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поддельные документы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Найдите жителя Оргриммара, который примет ваши поддельные документы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите жителя Оргриммара, который примет ваши поддельные документы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Вы отдаете поддельные документы и обмениваетесь буквально парой слов; ваше искусное умение говорит само за себя.>',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У тебя ко мне какое-то дело?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27687,'Скреж, да не наш','Вот это подвиг – одолеть могучего морского гиганта!$B$BНовые обитатели Пещере контрабандистов будут чувствовать себя гораздо спокойнее, зная, что это чудище не шатается где-то поблизости.','Принесите голову Скрежа Самиру в Пещеру контрабандистов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Скреж, да не наш',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот это подвиг – одолеть могучего морского гиганта!$B$BНовые обитатели Пещере контрабандистов будут чувствовать себя гораздо спокойнее, зная, что это чудище не шатается где-то поблизости.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите голову Скрежа Самиру в Пещеру контрабандистов.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27688,'Отвлекающий маневр','Необходимо уничтожить троих: госпожу Элис Финнссон, мастера Клема и Мию Цветущую.$B$BМне нужно, чтобы ты их $gотвлек:отвлекла;. А я выберу подходящий момент, подберусь к ним со спины и прикончу.$B$BТолько будь $gосторожен:осторожна;, $n. Не стоит их недооценивать. Они опасные соперники, сильные и безжалостные.','Убейте госпожу Элис Финнссон, мастера Клема и Мию Цветущую.','Вернитесь к мастеру Матиасу Шоу к Сумеречной крепости на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отвлекающий маневр',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Необходимо уничтожить троих: госпожу Элис Финнссон, мастера Клема и Мию Цветущую.$B$BМне нужно, чтобы ты их $gотвлек:отвлекла;. А я выберу подходящий момент, подберусь к ним со спины и прикончу.$B$BТолько будь $gосторожен:осторожна;, $n. Не стоит их недооценивать. Они опасные соперники, сильные и безжалостные.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте госпожу Элис Финнссон, мастера Клема и Мию Цветущую.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру Матиасу Шоу к Сумеречной крепости на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27689,'Отвлекающий маневр','Необходимо уничтожить троих: госпожу Элис Финнссон, мастера Клема и Мию Цветущую.$B$BМне нужно, чтобы ты их $gотвлек:отвлекла;. А я выберу подходящий момент, подберусь к ним со спины и прикончу.$B$BТолько, прошу тебя, будь $gосторожен:осторожна;, $n. Не стоит их недооценивать. Они опасные соперники, сильные и безжалостные. И при этом – форменные психопаты.','Убейте госпожу Элис Финнссон, мастера Клема и Мию Цветущую.','Вернитесь к Гароне Полуорчихе к Сумеречной крепости на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отвлекающий маневр',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Необходимо уничтожить троих: госпожу Элис Финнссон, мастера Клема и Мию Цветущую.$B$BМне нужно, чтобы ты их $gотвлек:отвлекла;. А я выберу подходящий момент, подберусь к ним со спины и прикончу.$B$BТолько, прошу тебя, будь $gосторожен:осторожна;, $n. Не стоит их недооценивать. Они опасные соперники, сильные и безжалостные. И при этом – форменные психопаты.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте госпожу Элис Финнссон, мастера Клема и Мию Цветущую.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гароне Полуорчихе к Сумеречной крепости на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27690,'Наркралл, Укротитель Драконов','Отправляйтесь к Наркраллу Кривому Когтю в Кровавое ущелье в Сумеречном нагорье.','Поговорите с Наркраллом Кривым Когтем в Кровавом ущелье в Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наркралл, Укротитель Драконов',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь к Наркраллу Кривому Когтю в Кровавое ущелье в Сумеречном нагорье.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Наркраллом Кривым Когтем в Кровавом ущелье в Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27691,'Болотноплавниковый беспредел','Боюсь, из хитрошестеренкинцев здесь уже никого не осталось. Вся молодежь в лагере на востоке пропала, когда пришли мурлоки.$B$BДа, мурлоки всегда обитали на этих берегах... но не в таких количествах. Они стаями повалили из моря под покровом ночи, воя и пуская слюну, собираясь на суше для атаки!$B$BМы не можем им позволить просто так тут расхаживать! Может быть, выручишь пожилую гоблиншу и пойдешь затолкаешь их обратно в море?','Убейте 12 мурлоков Болотных Плавников.','Остается только догадываться, что там творится. Это же побережье Зловещего моря, за ним ничего нет... Но эти рыбоподобные твари просто взяли и вышли из него.$B$BБолее того, я видела, куда они направляются...','Вернитесь к Бабе Тиночерп в Вязкую топь на Болоте Печали.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Болотноплавниковый беспредел',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Боюсь, из хитрошестеренкинцев здесь уже никого не осталось. Вся молодежь в лагере на востоке пропала, когда пришли мурлоки.$B$BДа, мурлоки всегда обитали на этих берегах... но не в таких количествах. Они стаями повалили из моря под покровом ночи, воя и пуская слюну, собираясь на суше для атаки!$B$BМы не можем им позволить просто так тут расхаживать! Может быть, выручишь пожилую гоблиншу и пойдешь затолкаешь их обратно в море?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 мурлоков Болотных Плавников.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Остается только догадываться, что там творится. Это же побережье Зловещего моря, за ним ничего нет... Но эти рыбоподобные твари просто взяли и вышли из него.$B$BБолее того, я видела, куда они направляются...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бабе Тиночерп в Вязкую топь на Болоте Печали.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27692,'Принцесса Терадрас','Не волнуйся, $gюный:юная:r; |3-6($r). Я Зейтар, сын Кенария, и я прибыл, чтобы тебе помочь.$B$BДавным-давно я совершил ошибку, вступив в связь с принцессой Терадрас, могущественным элементалем земли из рода древних богов. Родившись, наши дети ханы-кентавры сразу же напали на меня и жестоко убили. Тлетворное влияние Терадрас простирается гораздо дальше Мародона.$B$BСрази ее и освободи мой дух, чтобы мы смогли вернуть Пустоши к жизни, как завещал нам Кенарий.','Сразите принцессу Терадрас.','Спасибо тебе, $n. Как видишь, мое присутствие тут благотоворно сказалось на растительности, которая превозмогла даже темные силы Терадрас. Надеюсь, однажды ты вернешься в Пустоши и обнаружишь тут цветущий оазис, полный жизни и позабывший об истязаниях древних богов.','Ее нужно остановить!','Принцесса Терадрас') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Принцесса Терадрас',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не волнуйся, $gюный:юная:r; |3-6($r). Я Зейтар, сын Кенария, и я прибыл, чтобы тебе помочь.$B$BДавным-давно я совершил ошибку, вступив в связь с принцессой Терадрас, могущественным элементалем земли из рода древних богов. Родившись, наши дети ханы-кентавры сразу же напали на меня и жестоко убили. Тлетворное влияние Терадрас простирается гораздо дальше Мародона.$B$BСрази ее и освободи мой дух, чтобы мы смогли вернуть Пустоши к жизни, как завещал нам Кенарий.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сразите принцессу Терадрас.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо тебе, $n. Как видишь, мое присутствие тут благотоворно сказалось на растительности, которая превозмогла даже темные силы Терадрас. Надеюсь, однажды ты вернешься в Пустоши и обнаружишь тут цветущий оазис, полный жизни и позабывший об истязаниях древних богов.',`offerrewardtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Ее нужно остановить!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Принцесса Терадрас',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27693,'Игра стражей','Вы видите, как статуэтка сначала раздваивается, затем делится на четыре, а затем на восемь одинаковых статуэток, которые выстраиваются в квадрат.$B$BПрямо в вашем сознании раздается голос:$B$B"Настоящий страж не смотрит ВОВНЕ, отыскивая признаки опасности.$B$BНастоящий страж обращает свой взгляд ВОВНУТРЬ, сосредоточенно оберегая свою добычу".$B$BДолжно быть, это какая-то загадка.','Завершите игру стражей, переместив пешек-стражей так, чтобы они смотрели внутрь квадрата.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Игра стражей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы видите, как статуэтка сначала раздваивается, затем делится на четыре, а затем на восемь одинаковых статуэток, которые выстраиваются в квадрат.$B$BПрямо в вашем сознании раздается голос:$B$B"Настоящий страж не смотрит ВОВНЕ, отыскивая признаки опасности.$B$BНастоящий страж обращает свой взгляд ВОВНУТРЬ, сосредоточенно оберегая свою добычу".$B$BДолжно быть, это какая-то загадка.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Завершите игру стражей, переместив пешек-стражей так, чтобы они смотрели внутрь квадрата.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27694,'Озеро Слез','В этих артефактах сущность рода зеленых драконов – частицы душ моих порабощенных собратьев. Очистив их, я установлю связь между нами.$B$BПодойди, Декарим, и прими Камень клятвы драконьего рода Изеры.','Сбор артефактов – это жест доброй воли с твоей стороны. Без них провести ритуал невозможно.','Вернитесь к лорду Итару к входу в храм Атал\'Хаккара на Болоте Печали.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Озеро Слез',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','В этих артефактах сущность рода зеленых драконов – частицы душ моих порабощенных собратьев. Очистив их, я установлю связь между нами.$B$BПодойди, Декарим, и прими Камень клятвы драконьего рода Изеры.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Сбор артефактов – это жест доброй воли с твоей стороны. Без них провести ритуал невозможно.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лорду Итару к входу в храм Атал\'Хаккара на Болоте Печали.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27695,'Топор из элементия','Эти презренные трусы из Сумеречного Молота перебили почти всех красных драконов, но один все же остался. Вернее, одна. Помнишь Лирастразу? Ее держат в оковах. Тут, неподалеку. И мы ее освободим.$B$BНо сначала нам нужно добыть самый острый и крепкий клинок, чтобы перерубить ее цепи.$B$BОтправляйся на юг, к Алтарю Перерожденных. Его охраняет старый эттин по имени Слепой Страж.$B$BУ этого Стража боевой топор из чистейшего элементия. Я вот думаю... может быть, это и есть пресловутое "совершенное оружие" Чо\'Галла?','Раздобудьте топор из элементия.','Да, острая штука. Цепь-то он точно разрубит.$B$BНо если я что-нибудь понимаю в оружии, это явно не то, что пытается создать Чо\'Галл.','Ну что, где топор? Нам надо поторопиться, иначе они убьют Лирастразу.','Вернитесь к мастеру Матиасу Шоу к Сумеречной крепости на Сумеречном нагорье.','У него топор из элементия!','Слепой Страж') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Топор из элементия',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти презренные трусы из Сумеречного Молота перебили почти всех красных драконов, но один все же остался. Вернее, одна. Помнишь Лирастразу? Ее держат в оковах. Тут, неподалеку. И мы ее освободим.$B$BНо сначала нам нужно добыть самый острый и крепкий клинок, чтобы перерубить ее цепи.$B$BОтправляйся на юг, к Алтарю Перерожденных. Его охраняет старый эттин по имени Слепой Страж.$B$BУ этого Стража боевой топор из чистейшего элементия. Я вот думаю... может быть, это и есть пресловутое "совершенное оружие" Чо\'Галла?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте топор из элементия.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, острая штука. Цепь-то он точно разрубит.$B$BНо если я что-нибудь понимаю в оружии, это явно не то, что пытается создать Чо\'Галл.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, где топор? Нам надо поторопиться, иначе они убьют Лирастразу.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру Матиасу Шоу к Сумеречной крепости на Сумеречном нагорье.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','У него топор из элементия!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Слепой Страж',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27696,'Топор из элементия','Эти презренные трусы из Сумеречного Молота перебили почти всех красных драконов, но один все же остался. Вернее, одна. Помнишь Лирастразу? Ее держат в оковах. Тут, неподалеку. И мы ее освободим.$B$BНо сначала нам нужно добыть самый острый и крепкий клинок, чтобы перерубить ее цепи.$B$BОтправляйся на юг, к Алтарю Перерожденных. Его охраняет старый эттин по имени Слепой Страж.$B$BУ этого Стража настоящий боевой топор из чистейшего элементия. Я вот думаю... может, это и есть пресловутое "совершенное оружие" Чо\'Галла?','Раздобудьте топор из элементия.','Да, хороший топорик, острый. Цепь перерубит, как нечего делать. Но если я что-нибудь понимаю в оружии, это явно не то, что пытается создать Чо\'Галл.','Ну что, где топор?','Вернитесь к Гароне Полуорчихе к Сумеречной крепости на Сумеречном нагорье.','У него топор из элементия!','Слепой Страж') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Топор из элементия',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти презренные трусы из Сумеречного Молота перебили почти всех красных драконов, но один все же остался. Вернее, одна. Помнишь Лирастразу? Ее держат в оковах. Тут, неподалеку. И мы ее освободим.$B$BНо сначала нам нужно добыть самый острый и крепкий клинок, чтобы перерубить ее цепи.$B$BОтправляйся на юг, к Алтарю Перерожденных. Его охраняет старый эттин по имени Слепой Страж.$B$BУ этого Стража настоящий боевой топор из чистейшего элементия. Я вот думаю... может, это и есть пресловутое "совершенное оружие" Чо\'Галла?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте топор из элементия.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, хороший топорик, острый. Цепь перерубит, как нечего делать. Но если я что-нибудь понимаю в оружии, это явно не то, что пытается создать Чо\'Галл.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, где топор?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гароне Полуорчихе к Сумеречной крепости на Сумеречном нагорье.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','У него топор из элементия!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Слепой Страж',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (27697,'Скверна в Мародоне','$n, мне срочно нужна твоя помощь! Я Зейтар, сын Кенария. Вследствие череды событий, я оказался заточен этом подземелье! Однако прежде чем выручать меня, нужно избавить Мародон от скверны, поразившей это место.$B$BЛорд Злоязыкий – правитель сатиров из Пещеры лиловых кристаллов. Это коварный агент Пылающего Легиона, поэтому его присутствие способно принести лишь смерть и разрушение. С ним нужно покончить!','Покончите с лордом Злоязыким.','Отлично, $n! Гибель лорда Злоязыкого – ключ к моему освобождению и, в конечном счете, к спасению этих земель от поразившей их скверны. Прими этот скромный дар в знак моей благодарности за твое рвение.$B$B<Вы чувствуете, что ваша сумка стала тяжелее.>','Пришел и его черед!','Лорд Злоязыкий','Твоя миссия еще не выполнена!','Зейтар') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Скверна в Мародоне',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, мне срочно нужна твоя помощь! Я Зейтар, сын Кенария. Вследствие череды событий, я оказался заточен этом подземелье! Однако прежде чем выручать меня, нужно избавить Мародон от скверны, поразившей это место.$B$BЛорд Злоязыкий – правитель сатиров из Пещеры лиловых кристаллов. Это коварный агент Пылающего Легиона, поэтому его присутствие способно принести лишь смерть и разрушение. С ним нужно покончить!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Покончите с лордом Злоязыким.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, $n! Гибель лорда Злоязыкого – ключ к моему освобождению и, в конечном счете, к спасению этих земель от поразившей их скверны. Прими этот скромный дар в знак моей благодарности за твое рвение.$B$B<Вы чувствуете, что ваша сумка стала тяжелее.>',`offerrewardtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Пришел и его черед!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Лорд Злоязыкий',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Твоя миссия еще не выполнена!',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Зейтар',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (27698,'Прислужники Терадрас','Моя бывшая возлюбленная, принцесса Терадрас, воспользовалась своей невиданной силой, чтобы поразить самую суть Мародона. Даже теперь ее создания бродят по округе, угрожая вырваться за пределы этого места и сеять смерть и разрушения.$B$BОтправляйся в путь, $n, и заставь ее страдать, убив Ноксиона и Бритвохлеста, сильнейших служителей Терадрас. Возможно, тогда ты сможешь вырвать мой дух из ее плена.','Уничтожьте Ноксиона и Бритвохлеста.','Самое их существование противно природе.','Бритвохлест','Благодарю тебя за старания.','Зейтар') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прислужники Терадрас',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Моя бывшая возлюбленная, принцесса Терадрас, воспользовалась своей невиданной силой, чтобы поразить самую суть Мародона. Даже теперь ее создания бродят по округе, угрожая вырваться за пределы этого места и сеять смерть и разрушения.$B$BОтправляйся в путь, $n, и заставь ее страдать, убив Ноксиона и Бритвохлеста, сильнейших служителей Терадрас. Возможно, тогда ты сможешь вырвать мой дух из ее плена.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте Ноксиона и Бритвохлеста.',`objectives_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Самое их существование противно природе.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Бритвохлест',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Благодарю тебя за старания.',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Зейтар',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27699,'Крепкий орешек','Добудьте 5 зубов Костеглода на Рифе Скелетов.','Что?!$B$BКостогрыз не сдох?$B$BПохоже, из моего плана "быстро нажиться" постепенно выпадает слово "быстро"... Зубы гигантской акулы весьма недурны – кто бы спорил, но мы не сдадимся, пока не добудем блестяшку!','Что там у тебя, дружище?','Доставьте зубы Костеглода на Раскопки Бадда в лесу Келп’тар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Крепкий орешек',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 5 зубов Костеглода на Рифе Скелетов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что?!$B$BКостогрыз не сдох?$B$BПохоже, из моего плана "быстро нажиться" постепенно выпадает слово "быстро"... Зубы гигантской акулы весьма недурны – кто бы спорил, но мы не сдадимся, пока не добудем блестяшку!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что там у тебя, дружище?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доставьте зубы Костеглода на Раскопки Бадда в лесу Келп’тар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27700,'Освобождение дракона','Лирастраза – последняя и величайшая из красных драконов, которых захватил Сумеречный Молот. Они намерены ее убить.$B$BВозьми топор из элементия и освободи ее от оков.','Топором из элементия разрубите цепи, которыми скована Лирастраза.','Какая красавица, правда?$B$BТеперь она свободна, и у меня есть подозрение, что ее обидчикам не поздоровится.','Вернитесь к мастеру Матиасу Шоу к Сумеречной крепости на Сумеречном нагорье.','Освободите ее с помощью топора из элементия!','Лирастраза') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Освобождение дракона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Лирастраза – последняя и величайшая из красных драконов, которых захватил Сумеречный Молот. Они намерены ее убить.$B$BВозьми топор из элементия и освободи ее от оков.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Топором из элементия разрубите цепи, которыми скована Лирастраза.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Какая красавица, правда?$B$BТеперь она свободна, и у меня есть подозрение, что ее обидчикам не поздоровится.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру Матиасу Шоу к Сумеречной крепости на Сумеречном нагорье.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Освободите ее с помощью топора из элементия!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Лирастраза',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27701,'Освобождение дракона','Лирастраза – последняя и величайшая из красных драконов, которых захватил Сумеречный Молот. Они собираются убить ее, |3-6($c).$B$BВозьми топор из элементия и освободи ее от оков.','Топором из элементия разрубите цепи, которыми скована Лирастраза.','Она такая красивая и грациозная...$B$BНадеюсь, она отомстит своим обидчикам.','Вернитесь к Гароне Полуорчихе к Сумеречной крепости на Сумеречном нагорье.','Освободите ее с помощью топора из элементия!','Лирастраза') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Освобождение дракона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Лирастраза – последняя и величайшая из красных драконов, которых захватил Сумеречный Молот. Они собираются убить ее, |3-6($c).$B$BВозьми топор из элементия и освободи ее от оков.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Топором из элементия разрубите цепи, которыми скована Лирастраза.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Она такая красивая и грациозная...$B$BНадеюсь, она отомстит своим обидчикам.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гароне Полуорчихе к Сумеречной крепости на Сумеречном нагорье.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Освободите ее с помощью топора из элементия!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Лирастраза',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27702,'Удар милосердия','Смотри! Лирастраза сражается с ними!$B$BМы должны добить тех драконов, которых она сбила, но не прикончила, $n. Мы же не хотим, чтобы целители Сумеречного Молота вновь подняли их в воздух.$B$BНазовем это проявлением милосердия к проигравшим.','Добейте 5 сумеречных ужасов небес.','Вернитесь к мастеру Матиасу Шоу к Сумеречной крепости на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Удар милосердия',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Смотри! Лирастраза сражается с ними!$B$BМы должны добить тех драконов, которых она сбила, но не прикончила, $n. Мы же не хотим, чтобы целители Сумеречного Молота вновь подняли их в воздух.$B$BНазовем это проявлением милосердия к проигравшим.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добейте 5 сумеречных ужасов небес.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру Матиасу Шоу к Сумеречной крепости на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27703,'Удар милосердия','Ты гляди, что творится! Лирастраза сражается с ними!$B$BНекоторых драконов она сбила, но не прикончила. Мы должны завершить начатое ею, $n. Мы же не хотим, чтобы поганые целители Сумеречного Молота вновь подняли их в воздух.$B$BНазовем это проявлением милосердия к проигравшим.','Добейте 5 сумеречных ужасов небес.','Это очень хорошо, что вам с полководцем Кроггом удалось подружиться с красными драконами.','Вернитесь к Гароне Полуорчихе к Сумеречной крепости на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Удар милосердия',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты гляди, что творится! Лирастраза сражается с ними!$B$BНекоторых драконов она сбила, но не прикончила. Мы должны завершить начатое ею, $n. Мы же не хотим, чтобы поганые целители Сумеречного Молота вновь подняли их в воздух.$B$BНазовем это проявлением милосердия к проигравшим.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добейте 5 сумеречных ужасов небес.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это очень хорошо, что вам с полководцем Кроггом удалось подружиться с красными драконами.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гароне Полуорчихе к Сумеречной крепости на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (27704,'Легенды Затонувшего храма','Сначала в храм $gдолжен:должна; пойти ты, $n. Я присоединюсь к тебе, когда это будет безопасно, но не хочу действовать вслепую. Обращенный против своих собратьев, я стану грозным противником.$B$BСперва спустись по лестнице позади меня. Затем проплыви через Разрушенный зал. Дальше иди по коридору, и, повернув направо, ты окажешься в зале Масок.$B$BОстерегайся стражей храма. Когда окажешься в Зале Масок, я свяжусь с тобой через Камень клятвы.','Доберитесь до Зала Масок через вестибюль храма.','Зал Масок найден','Ты в Зале Масок!','Лорд Итар') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Легенды Затонувшего храма',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сначала в храм $gдолжен:должна; пойти ты, $n. Я присоединюсь к тебе, когда это будет безопасно, но не хочу действовать вслепую. Обращенный против своих собратьев, я стану грозным противником.$B$BСперва спустись по лестнице позади меня. Затем проплыви через Разрушенный зал. Дальше иди по коридору, и, повернув направо, ты окажешься в зале Масок.$B$BОстерегайся стражей храма. Когда окажешься в Зале Масок, я свяжусь с тобой через Камень клятвы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доберитесь до Зала Масок через вестибюль храма.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Зал Масок найден',`endtext_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Ты в Зале Масок!',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Лорд Итар',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (27705,'Шаг первый: жрица','Убейте жрицу Удум\'бру в Чертоге Крови.','Проповедница Чертога Крови','Жрица Удум\'бра','Камень клятвы связывает нас.','Лорд Итар') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Шаг первый: жрица',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте жрицу Удум\'бру в Чертоге Крови.',`objectives_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Проповедница Чертога Крови',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Жрица Удум\'бра',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Камень клятвы связывает нас.',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Лорд Итар',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27706,'Скипетр Орсиса','Едва вы вставляете камни в гнезда на табличке, как ларец с громким щелчком открывается.$B$BВозьмите скипетр и отнесите его генералу Аммантепу.','Возьмите скипетр Орсиса из священного ларца.','Так вот за чем Ал\'акир охотится все это время...','Отнесите скипетр Орсиса генералу Аммантепу в пригород Орсиса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Скипетр Орсиса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Едва вы вставляете камни в гнезда на табличке, как ларец с громким щелчком открывается.$B$BВозьмите скипетр и отнесите его генералу Аммантепу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возьмите скипетр Орсиса из священного ларца.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так вот за чем Ал\'акир охотится все это время...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите скипетр Орсиса генералу Аммантепу в пригород Орсиса.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27707,'Тюрьма неферсетов','Иероглифы, изображающие закованного в цепи тол\'вира, нанесены в юго-восточном уголке карты.$B$BВозможно, именно туда отвели пленного Тахета.','Отправляйтесь в тюрьму Неферсета и выясните, что сталось с Тахетом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тюрьма неферсетов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Иероглифы, изображающие закованного в цепи тол\'вира, нанесены в юго-восточном уголке карты.$B$BВозможно, именно туда отвели пленного Тахета.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в тюрьму Неферсета и выясните, что сталось с Тахетом.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27708,'Последний дозор','<Образ Эрунака возникает в вашем сознании.>$B$BХорошая работа, $n, но многое еще предстоит сделать.$B$BПрежде чем уйти, нужно напоследок учинить здесь изрядный погром.$B$BРазыщи предводителя наг и покарай за все его злодеяния.','Эрунак Говорящий с Камнем хочет, чтобы вы убили стража Азжакира на Жемчужной ферме.','Ну что ж, мы хорошенько попортили жизнь этим нагам.$B$BМне пора отправляться в путь...','Обратитесь к Эрунаку Говорящему с Камнем в Дымчатом гроте, что в лесу Келп’тар.','Образ Эрунака возникает в вашем сознании.','Эрунак Говорящий с Камнем') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Последний дозор',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Образ Эрунака возникает в вашем сознании.>$B$BХорошая работа, $n, но многое еще предстоит сделать.$B$BПрежде чем уйти, нужно напоследок учинить здесь изрядный погром.$B$BРазыщи предводителя наг и покарай за все его злодеяния.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Эрунак Говорящий с Камнем хочет, чтобы вы убили стража Азжакира на Жемчужной ферме.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну что ж, мы хорошенько попортили жизнь этим нагам.$B$BМне пора отправляться в путь...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Обратитесь к Эрунаку Говорящему с Камнем в Дымчатом гроте, что в лесу Келп’тар.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Образ Эрунака возникает в вашем сознании.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Эрунак Говорящий с Камнем',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27709,'Игра часовых','Как только статуэтка оказывается на месте, в комнате появляется еще несколько каменных статуэток. В нише в дальнем конце комнаты вы видите еще одну рубиновую фигурку. Вы слышите голос:$B$B"Страж наблюдает.$BСтраж защищает.$BСтраж никогда не смежает очей".$B$BКрасная статуэтка на другом конце комнаты наверняка для чего-то нужна. Может быть, попробовать соединить две красные статуэтки?','Завершите игру часовых, соединив две красные статуэтки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Игра часовых',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как только статуэтка оказывается на месте, в комнате появляется еще несколько каменных статуэток. В нише в дальнем конце комнаты вы видите еще одну рубиновую фигурку. Вы слышите голос:$B$B"Страж наблюдает.$BСтраж защищает.$BСтраж никогда не смежает очей".$B$BКрасная статуэтка на другом конце комнаты наверняка для чего-то нужна. Может быть, попробовать соединить две красные статуэтки?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Завершите игру часовых, соединив две красные статуэтки.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27711,'Возвращение в Элементиевые глубины','Посвященному Клондацку, помощнику Заклинательницы земли, в свою очередь, нужна твоя помощь.$B$BУ них там какие-то сложности в шахте. Какие именно – я не в курсе. Придешь на место, узнаешь.','Поговорите с посвященным Клондацком в Элементиевых глубинах, что в Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение в Элементиевые глубины',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Посвященному Клондацку, помощнику Заклинательницы земли, в свою очередь, нужна твоя помощь.$B$BУ них там какие-то сложности в шахте. Какие именно – я не в курсе. Придешь на место, узнаешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с посвященным Клондацком в Элементиевых глубинах, что в Сумеречном нагорье.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27712,'Возвращение в Элементиевые глубины','У Заклинательницы Земли есть помощник-гоблин? Посвященный Клондацк – его имя? Ему нужна твоя помощь.$B$BУж не знаю, что у них там стряслось в этой шахте, но они явно не прочь скинуть на кого-нибудь всю грязную работенку.','Поговорите с посвященным Клондацком в Элементиевых глубинах, что в Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение в Элементиевые глубины',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У Заклинательницы Земли есть помощник-гоблин? Посвященный Клондацк – его имя? Ему нужна твоя помощь.$B$BУж не знаю, что у них там стряслось в этой шахте, но они явно не прочь скинуть на кого-нибудь всю грязную работенку.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с посвященным Клондацком в Элементиевых глубинах, что в Сумеречном нагорье.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27713,'День, когда пришел Смертокрыл','Смертокрыл натворил немало бед, пролетая через эти земли. Если бы не я, он бы по-прежнему тут хозяйничал, сея смерть среди добрых жителей Бесплодных земель.$B$BЧто, не веришь? Ладно, я тебе расскажу, как все было.','Выслушайте рассказ Тельдарина.','История что надо, не так ли? Теперь ты понимаешь, почему Смертокрыл с тех пор не возвращался.','Вернитесь к Тельдарину Заблудшему в Молот Агграмара в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','День, когда пришел Смертокрыл',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Смертокрыл натворил немало бед, пролетая через эти земли. Если бы не я, он бы по-прежнему тут хозяйничал, сея смерть среди добрых жителей Бесплодных земель.$B$BЧто, не веришь? Ладно, я тебе расскажу, как все было.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выслушайте рассказ Тельдарина.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','История что надо, не так ли? Теперь ты понимаешь, почему Смертокрыл с тех пор не возвращался.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тельдарину Заблудшему в Молот Агграмара в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27714,'День, когда пришел Смертокрыл: вся правда','Тельдарин не просто все переврал – его история скучна и напрочь лишена воображения и динамики.$B$BСейчас я тебе расскажу, как все было на самом деле.','Послушайте версию событий в изложении Люсьена Подай-Ключ.','Конец! Морали у басни нет никакой.','Поговорите с Люсьеном Подай-Ключ в Разломе разрушителя миров в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','День, когда пришел Смертокрыл: вся правда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тельдарин не просто все переврал – его история скучна и напрочь лишена воображения и динамики.$B$BСейчас я тебе расскажу, как все было на самом деле.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Послушайте версию событий в изложении Люсьена Подай-Ключ.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Конец! Морали у басни нет никакой.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Люсьеном Подай-Ключ в Разломе разрушителя миров в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27715,'День, когда пришел Смертокрыл: все было совсем иначе...','Послушайте рассказ в изложении Мартека Изгоя.','Уму непостижимо, как эти олухи вот так меня оборвали на полуслове! Такой рассказ...$B$BКак бы то ни было, спасибо, что слушал так долго. Хорошо, когда есть кому рассказать историю-другую. Думаю, Люсьен с Тельдарином чувствуют то же самое.$B$BМожет, и ты нам что-нибудь расскажешь?','Поговорите с Мартеком Изгоем в Разломе разрушителя миров в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','День, когда пришел Смертокрыл: все было совсем иначе...',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Послушайте рассказ в изложении Мартека Изгоя.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Уму непостижимо, как эти олухи вот так меня оборвали на полуслове! Такой рассказ...$B$BКак бы то ни было, спасибо, что слушал так долго. Хорошо, когда есть кому рассказать историю-другую. Думаю, Люсьен с Тельдарином чувствуют то же самое.$B$BМожет, и ты нам что-нибудь расскажешь?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Мартеком Изгоем в Разломе разрушителя миров в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27716,'Частица прошлого','<Обломок треснувшей древней плиты весь покрыт какими-то надписями. Язык вам незнаком, но текст и сам вид обломка наводят на мысли о том, что это очень ценный предмет.>$B$B<Ливия Пробуждающая, живущая в лагере спасенных из Неспиры, искала нечто подобное.>','Принесите обломок с древними эльфийскими письменами Ливии Пробуждающей. Найти ее можно в лагере спасенных Альянса из Неспиры.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Частица прошлого',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Обломок треснувшей древней плиты весь покрыт какими-то надписями. Язык вам незнаком, но текст и сам вид обломка наводят на мысли о том, что это очень ценный предмет.>$B$B<Ливия Пробуждающая, живущая в лагере спасенных из Неспиры, искала нечто подобное.>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите обломок с древними эльфийскими письменами Ливии Пробуждающей. Найти ее можно в лагере спасенных Альянса из Неспиры.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27717,'Частица прошлого','<Обломок треснувшей древней плиты весь покрыт какими-то надписями. Язык вам незнаком, но текст и сам вид обломка наводят на мысли о том, что это очень ценный предмет.>$B$B<Элендри Золотое Чело, живущая в лагере спасенных из Неспиры, искала нечто подобное.>','Принесите обломок с древними эльфийскими письменами Элендре Золотое Чело. Ее можно найти в лагере ордынцев, спасенных из Неспиры.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Частица прошлого',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Обломок треснувшей древней плиты весь покрыт какими-то надписями. Язык вам незнаком, но текст и сам вид обломка наводят на мысли о том, что это очень ценный предмет.>$B$B<Элендри Золотое Чело, живущая в лагере спасенных из Неспиры, искала нечто подобное.>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите обломок с древними эльфийскими письменами Элендре Золотое Чело. Ее можно найти в лагере ордынцев, спасенных из Неспиры.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27718,'Приказ вождя: Вайш\'ир!','Всем годным к военной службе ордынцам приказано явиться к командиру Тораку в бухту Острорука в Дуротаре.$B$BСейчас нам как никогда прежде необходима твоя помощь в борьбе с нашим заклятым врагом Альянсом!$B$BЧтобы добраться до бухты Острорука, отправляйся через главные ворота Оргриммара на юг, в Дуротар. Оттуда следуй по тропе на восток, к побережью. Торак будет ждать возле доков.$B$BВперед, $gбрат:сестра;! Судьба зовет!','Явитесь с рапортом к командиру Тораку в бухте Острорука в Дуротаре.','Лок\'тар, брат! Ты прибыл как раз вовремя.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приказ вождя: Вайш\'ир!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Всем годным к военной службе ордынцам приказано явиться к командиру Тораку в бухту Острорука в Дуротаре.$B$BСейчас нам как никогда прежде необходима твоя помощь в борьбе с нашим заклятым врагом Альянсом!$B$BЧтобы добраться до бухты Острорука, отправляйся через главные ворота Оргриммара на юг, в Дуротар. Оттуда следуй по тропе на восток, к побережью. Торак будет ждать возле доков.$B$BВперед, $gбрат:сестра;! Судьба зовет!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Явитесь с рапортом к командиру Тораку в бухте Острорука в Дуротаре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Лок\'тар, брат! Ты прибыл как раз вовремя.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27719,'Живая вода','Возьми мою живую воду и влей в рот утонувшего дворфа.$B$BПри жизни тот был кузнецом и работал с металлом, и хотя уже мертв, вода вернет ему на время подобие жизни, и ты сможешь его расспросить и узнать, что тебе нужно.$B$BА потом уходи из моих владений.','Расспросите труп начальника кузни Финлея, вернув ему подобие жизни с помощью живой воды.','Молот Сумерек? Говоришь, ты добыла эти сведения у утонувшего дворфа из клана Громового Молота?$B$BТы, наверное, шутишь!','Поговорите с мастером Матиасом Шоу на Сумеречной крепости на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Живая вода',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Возьми мою живую воду и влей в рот утонувшего дворфа.$B$BПри жизни тот был кузнецом и работал с металлом, и хотя уже мертв, вода вернет ему на время подобие жизни, и ты сможешь его расспросить и узнать, что тебе нужно.$B$BА потом уходи из моих владений.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Расспросите труп начальника кузни Финлея, вернув ему подобие жизни с помощью живой воды.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Молот Сумерек? Говоришь, ты добыла эти сведения у утонувшего дворфа из клана Громового Молота?$B$BТы, наверное, шутишь!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с мастером Матиасом Шоу на Сумеречной крепости на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27720,'Прокатимся с ветерком','Значит, так, $n. Нам надо добраться до портала земли в самом дальнем конце пещеры.$B$BЯ сделал умно – "раздобыл" транспорт. Зачем трудить ноги, когда можно проехаться с ветерком? Надеюсь, твоя религия не запрещает кататься на шахтерских тачках?$B$BВ общем, как будешь $gготов:готова;, скажи – и поедем.','Вместе с посвященным Клондацком прокатитесь на вагонетке до конца маршрута.','О, нет! Мое оружие и тотемы!$B$BОни уничтожены!!!','Поговорите с посвященным Клондацком в Элементиевых глубинах, что на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прокатимся с ветерком',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Значит, так, $n. Нам надо добраться до портала земли в самом дальнем конце пещеры.$B$BЯ сделал умно – "раздобыл" транспорт. Зачем трудить ноги, когда можно проехаться с ветерком? Надеюсь, твоя религия не запрещает кататься на шахтерских тачках?$B$BВ общем, как будешь $gготов:готова;, скажи – и поедем.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вместе с посвященным Клондацком прокатитесь на вагонетке до конца маршрута.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, нет! Мое оружие и тотемы!$B$BОни уничтожены!!!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с посвященным Клондацком в Элементиевых глубинах, что на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`) VALUES (27721,'Приказ вождя: гора Хиджал!','Поговорите с кенарийским посланником Черным Копытом, чтобы он отправил вас на Лунную поляну.','Мы знали, что Орда сразу же придет нам на подмогу.','Путешествие на Лунную поляну обеспечено') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приказ вождя: гора Хиджал!',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с кенарийским посланником Черным Копытом, чтобы он отправил вас на Лунную поляну.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мы знали, что Орда сразу же придет нам на подмогу.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Путешествие на Лунную поляну обеспечено',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27722,'Приказ вождя: Подземье!','Всем годным к военной службе ордынцам приказано явиться к предсказателю Крогару в Западное святилище Земли в Оргиммар.$b$bСлужителям Земли, возглавляемым нашим бывшим вождем Траллом, необходима ваша помощь! Они сообщают о том, что обитель стихии Подземья угрожает захватить наш мир!$b$bЗападное святилище Земли находится к северу от Аллеи Мудрости.$b$bВперед, $gбрат:сестра;! Судьба зовет!','Поговорите с предсказателем Крогаром в Западном Святилище Земли в Оргриммаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приказ вождя: Подземье!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Всем годным к военной службе ордынцам приказано явиться к предсказателю Крогару в Западное святилище Земли в Оргиммар.$b$bСлужителям Земли, возглавляемым нашим бывшим вождем Траллом, необходима ваша помощь! Они сообщают о том, что обитель стихии Подземья угрожает захватить наш мир!$b$bЗападное святилище Земли находится к северу от Аллеи Мудрости.$b$bВперед, $gбрат:сестра;! Судьба зовет!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с предсказателем Крогаром в Западном Святилище Земли в Оргриммаре.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (27723,'Kyle\'s Test Quest') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Kyle\'s Test Quest',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27724,'Воззвание к героям: Вайш\'ир!','Поговорите с вербовщиком Бернсом в порту Штормграда.','Все наши боевые корабли сейчас в море, сражаются с Ордой. Тебе придется отправиться на корабле наемников.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Воззвание к героям: Вайш\'ир!',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с вербовщиком Бернсом в порту Штормграда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Все наши боевые корабли сейчас в море, сражаются с Ордой. Тебе придется отправиться на корабле наемников.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27725,'Сторожка Кель\'Данил','Тебе может казаться, что я пришел очень издалека, |3-6($c). Посол Руалет привел сюда достаточно много моих собратьев. Мы поселились вместе с высшими эльфами в Сторожке Кель\'Данил, что к северо-западу отсюда, чтобы узнать больше об учении Света и насладиться красотой этих земель.$b$bНо такой покой не может длиться долго. Мы видели войска Орды, которые продвигаются все дальше к западу отсюда. Не $gмог:могла; бы ты отправиться в Кель\'Данил и предупредить анахорета Траску? Ее хижина находится севернее самой Сторожки.','Поговорите с анахоретом Траской в Сторожке Кель\'Данил.','Йоро предупреждает о войсках Орды? Нам нужно остерегаться атак Орды. На самом деле мы…$B$B<С юга слышны крики и звон металла.>$B$BСвета ради… они здесь!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сторожка Кель\'Данил',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе может казаться, что я пришел очень издалека, |3-6($c). Посол Руалет привел сюда достаточно много моих собратьев. Мы поселились вместе с высшими эльфами в Сторожке Кель\'Данил, что к северо-западу отсюда, чтобы узнать больше об учении Света и насладиться красотой этих земель.$b$bНо такой покой не может длиться долго. Мы видели войска Орды, которые продвигаются все дальше к западу отсюда. Не $gмог:могла; бы ты отправиться в Кель\'Данил и предупредить анахорета Траску? Ее хижина находится севернее самой Сторожки.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с анахоретом Траской в Сторожке Кель\'Данил.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Йоро предупреждает о войсках Орды? Нам нужно остерегаться атак Орды. На самом деле мы…$B$B<С юга слышны крики и звон металла.>$B$BСвета ради… они здесь!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`) VALUES (27726,'Воззвание к героям: гора Хиджал!','Поговорите с кенарийской посланницей Нефритовой Луной, чтобы та отправила тебя на Лунную поляну.','Мы знали, что Альянс сразу же придет нам на подмогу.','Путешествие на Лунную поляну обеспечено') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Воззвание к героям: гора Хиджал!',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с кенарийской посланницей Нефритовой Луной, чтобы та отправила тебя на Лунную поляну.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мы знали, что Альянс сразу же придет нам на подмогу.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Путешествие на Лунную поляну обеспечено',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27727,'Воззвание к героям: Подземье!','Поговорите с Нараатом Говорящим с Землей в Восточном Святилище Земли в Штормграде.','Наш мир в опасности, Исамотолор! Чтобы спасти его, нам нужна помощь великих героев, таких, как ты!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Воззвание к героям: Подземье!',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Нараатом Говорящим с Землей в Восточном Святилище Земли в Штормграде.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Наш мир в опасности, Исамотолор! Чтобы спасти его, нам нужна помощь великих героев, таких, как ты!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27729,'Угревая зыбь','Угри – одни из самых мерзких тварей во всем Азероте.$B$BРазумеется, найдутся те, кто будет заливать, будто ничего не имеют против угрей; есть и те, кто утверждает, будто бы они ЛЮБЯТ угрей.$B$BВсе это вранье.$B$BПравда же в том, что угрей не любит никто. Мало того – даже угри не любят угрей!$B$BЖизнь в Азероте станет прекрасной и удивительной, как только все забудут о том, что такое угорь, выползающий из морской пучины и кусающий тебя.$B$BЗа нос.','Убейте 8 любых угрей в лесу Келп’тар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Угревая зыбь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Угри – одни из самых мерзких тварей во всем Азероте.$B$BРазумеется, найдутся те, кто будет заливать, будто ничего не имеют против угрей; есть и те, кто утверждает, будто бы они ЛЮБЯТ угрей.$B$BВсе это вранье.$B$BПравда же в том, что угрей не любит никто. Мало того – даже угри не любят угрей!$B$BЖизнь в Азероте станет прекрасной и удивительной, как только все забудут о том, что такое угорь, выползающий из морской пучины и кусающий тебя.$B$BЗа нос.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 любых угрей в лесу Келп’тар.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27733,'Старый добрый подлог','Послушай, я бы с радостью отдал приказ взорвать всех заключенных к лешему прямо сейчас, но не могу. Тюрьмой Штормграда распоряжается тюремщик Телвотер, а он пока просто хочет сдержать бандитов.$B$BВместо прямого неподчинения приказу мы пойдем на военную хитрость! Нам удалось сдружиться с Мортимером Молохом, который по счастливой случайности оказался братом-близнецом зачинщика восстания Рендольфа Молоха. Убей Рендольфа – мы поставим вместо него Мортимера, и тот без крови покончит с восстанием!','Убейте Рендольфа Молоха.','Да, Мортимер разыграл собственную смерть. Наверное, он возьмет имя брата и продолжит его "грандиозные планы". Мы с этим разберемся, но со временем.','Вернитесь к командиру стрелков Коу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Старый добрый подлог',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Послушай, я бы с радостью отдал приказ взорвать всех заключенных к лешему прямо сейчас, но не могу. Тюрьмой Штормграда распоряжается тюремщик Телвотер, а он пока просто хочет сдержать бандитов.$B$BВместо прямого неподчинения приказу мы пойдем на военную хитрость! Нам удалось сдружиться с Мортимером Молохом, который по счастливой случайности оказался братом-близнецом зачинщика восстания Рендольфа Молоха. Убей Рендольфа – мы поставим вместо него Мортимера, и тот без крови покончит с восстанием!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Рендольфа Молоха.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, Мортимер разыграл собственную смерть. Наверное, он возьмет имя брата и продолжит его "грандиозные планы". Мы с этим разберемся, но со временем.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру стрелков Коу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27737,'Пламя во спасение!','Я прекрасно разбираюсь в первой помощи и других видах лечения, и при наличии Колодца Света мне удалось полностью исцелить многих наших людей. Но здесь, внизу, так холодно и сыро, что они все равно гибнут, несмотря на то, что я лечу их раны!$B$BЗемлетрясения разозлили элементалей в темнице... выйдя из толщи земли, они погубили половину узников. Если ты уничтожишь их вождя, лорда Пережара, и принесешь мне его сердце, я согрею им наших людей!','Раздобудьте пламенное сердце лорда Пережара.','Вернитесь к медсестре Лилиан.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пламя во спасение!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я прекрасно разбираюсь в первой помощи и других видах лечения, и при наличии Колодца Света мне удалось полностью исцелить многих наших людей. Но здесь, внизу, так холодно и сыро, что они все равно гибнут, несмотря на то, что я лечу их раны!$B$BЗемлетрясения разозлили элементалей в темнице... выйдя из толщи земли, они погубили половину узников. Если ты уничтожишь их вождя, лорда Пережара, и принесешь мне его сердце, я согрею им наших людей!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте пламенное сердце лорда Пережара.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к медсестре Лилиан.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27738,'Ров Чешуи','Точка в южной оконечности карты была отмечена иероглифами, изображающими дерущихся крокодилов.$B$BДолжно быть, туда Каимас увел Тахета.$B$BОтправляйтесь в Ров Чешуи и попытайтесь спасти сына визиря.','Спасите Тахета возле у Рва Чешуи в Ульдуме.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ров Чешуи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Точка в южной оконечности карты была отмечена иероглифами, изображающими дерущихся крокодилов.$B$BДолжно быть, туда Каимас увел Тахета.$B$BОтправляйтесь в Ров Чешуи и попытайтесь спасти сына визиря.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Спасите Тахета возле у Рва Чешуи в Ульдуме.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27739,'Король гноллов','Боюсь, $n, что мне придется просить тебя о невозможном.$B$BВот эту повязку на глаз я получил из-за него. Тысячи тысяч пали жертвами его гнева. Лишь чудом его удалось здесь заточить.$B$BНо это было роковой ошибкой. Мы держались, сколько было сил, потом пришли они. Выступив из тьмы, гноллы, слуги Дробителя, разорвали лучших моих людей в клочья.$B$BТы $gдолжен:должна; одолеть короля гноллов, пока он снова не напал и не перебил всех нас в кровожадной ярости.','Убейте Дробителя.','Сегодня тобою совершено такое, чего я не видывал за всю свою жизнь. Смерть Дробителя надолго останется грозным предупреждением для стаи Речной Лапы и, надеюсь, положит конец их нападениям на наш народ.$B$BПрими это в знак моей бесконечной благодарности.','Вернитесь к тюремщику Телвотеру.','Его никому не одолеть.','Дробитель') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Король гноллов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Боюсь, $n, что мне придется просить тебя о невозможном.$B$BВот эту повязку на глаз я получил из-за него. Тысячи тысяч пали жертвами его гнева. Лишь чудом его удалось здесь заточить.$B$BНо это было роковой ошибкой. Мы держались, сколько было сил, потом пришли они. Выступив из тьмы, гноллы, слуги Дробителя, разорвали лучших моих людей в клочья.$B$BТы $gдолжен:должна; одолеть короля гноллов, пока он снова не напал и не перебил всех нас в кровожадной ярости.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Дробителя.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сегодня тобою совершено такое, чего я не видывал за всю свою жизнь. Смерть Дробителя надолго останется грозным предупреждением для стаи Речной Лапы и, надеюсь, положит конец их нападениям на наш народ.$B$BПрими это в знак моей бесконечной благодарности.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к тюремщику Телвотеру.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Его никому не одолеть.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Дробитель',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27740,'Баба Тиночерп','Эй, пока тебя не было, заглядывал барон! Колошматил меня, пока деньги не посыпались!$B$BВпрочем, он всегда так делает. Но в этот раз он еще просил кое-что тебе передать! Он хочет, чтобы ты $gотправился:отправилась; на юг на помощь нашей травнице Бабе Тиночерп.$B$BК ней далековато плыть! Но ты просто загляни к моей девочке Дейзи возле лагеря – она тебя туда мигом доставит, по-нашему!','Поговорите с Чудачкой Дейзи, чтобы вылететь из пушки в сторону Бабы Тиночерп.','Ах, как хорошо, что помощь прилетела!$B$BСовременная техника... Никак не нарадуюсь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Баба Тиночерп',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эй, пока тебя не было, заглядывал барон! Колошматил меня, пока деньги не посыпались!$B$BВпрочем, он всегда так делает. Но в этот раз он еще просил кое-что тебе передать! Он хочет, чтобы ты $gотправился:отправилась; на юг на помощь нашей травнице Бабе Тиночерп.$B$BК ней далековато плыть! Но ты просто загляни к моей девочке Дейзи возле лагеря – она тебя туда мигом доставит, по-нашему!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Чудачкой Дейзи, чтобы вылететь из пушки в сторону Бабы Тиночерп.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ах, как хорошо, что помощь прилетела!$B$BСовременная техника... Никак не нарадуюсь.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27741,'Предъявите документы!','В свете твоих успехов в борьбе с культом Сумеречного Молота капитан Антон рекомендовал тебя для деликатного задания.$B$BМои люди недавно выявили группу сектантов, пытающихся проникнуть в город. Король издал указ, чтобы всех прибывающих осматривали перед городскими воротами. На входе в Штормград образовался огромный затор. Возьми копию высочайшего обращения, зачитай его люду, собравшемуся у главных врат, после чего помоги страже в обыске прибывающих.','Направляйтесь к главным вратам Штормграда, зачитайте там обращение короля Ринна и обыщите 5 жителей Штормграда. Оставляйте у себя все подозрительные предметы, что обнаружите при обыске.','Вернитесь к Жюстине Демалье в Торговом квартале Штормграда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Предъявите документы!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В свете твоих успехов в борьбе с культом Сумеречного Молота капитан Антон рекомендовал тебя для деликатного задания.$B$BМои люди недавно выявили группу сектантов, пытающихся проникнуть в город. Король издал указ, чтобы всех прибывающих осматривали перед городскими воротами. На входе в Штормград образовался огромный затор. Возьми копию высочайшего обращения, зачитай его люду, собравшемуся у главных врат, после чего помоги страже в обыске прибывающих.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Направляйтесь к главным вратам Штормграда, зачитайте там обращение короля Ринна и обыщите 5 жителей Штормграда. Оставляйте у себя все подозрительные предметы, что обнаружите при обыске.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Жюстине Демалье в Торговом квартале Штормграда.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27742,'Сколько добра пропадает!','Знаешь, тут развелось столько сланцевых пауков... и они пожирают элементий. Его надо спасать. Это наш моральный долг!$B$BСтолько добра пропадает зря, страшно подумать!$B$BНу что, займемся? И честно поделим спасенный элементий. Одну десятую долю – тебе, девять – мне.','Соберите 6 осколков элементия.','<Клондацк хитро поглядывает на кучу осколков элементия.>$B$BМ-да... думаю, если мы соберемся его продавать, много нам за него не дадут. Давай ты сразу возьмешь свою долю. Ну, чтобы не чувствовать себя обделенным.','Как думаешь, сколько ты унесешь?','Поговорите с посвященным Клондацком в Элементиевых глубинах, что на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сколько добра пропадает!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Знаешь, тут развелось столько сланцевых пауков... и они пожирают элементий. Его надо спасать. Это наш моральный долг!$B$BСтолько добра пропадает зря, страшно подумать!$B$BНу что, займемся? И честно поделим спасенный элементий. Одну десятую долю – тебе, девять – мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 6 осколков элементия.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Клондацк хитро поглядывает на кучу осколков элементия.>$B$BМ-да... думаю, если мы соберемся его продавать, много нам за него не дадут. Давай ты сразу возьмешь свою долю. Ну, чтобы не чувствовать себя обделенным.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как думаешь, сколько ты унесешь?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с посвященным Клондацком в Элементиевых глубинах, что на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27743,'Чтобы два раза не бегать','Знаешь, раз уж мы здесь... Может быть, зададим жару этим паршивцам из Сумеречного Молота? Ну, чтобы два раза не бегать... Надо же восстановить справедливость! Когда-то этот рудник был нашим, а они здесь чужие! Подлые захватчики!$B$BНу что, займешься? Я бы помог, только что я могу без оружия и тотемов?','Убейте в Элементиевых глубинах 12 служителей культа Сумеречного Молота – инспекторов глубин или сумеречных шахтеров.','Они сами напросились.','Поговорите с посвященным Клондацком в Элементиевых глубинах на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чтобы два раза не бегать',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Знаешь, раз уж мы здесь... Может быть, зададим жару этим паршивцам из Сумеречного Молота? Ну, чтобы два раза не бегать... Надо же восстановить справедливость! Когда-то этот рудник был нашим, а они здесь чужие! Подлые захватчики!$B$BНу что, займешься? Я бы помог, только что я могу без оружия и тотемов?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте в Элементиевых глубинах 12 служителей культа Сумеречного Молота – инспекторов глубин или сумеречных шахтеров.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Они сами напросились.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с посвященным Клондацком в Элементиевых глубинах на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27744,'Уничтожение рун','Изучая сумеречную руну земли, вы почти ощущаете, как ее сила устремляется на самое дно Элементиевых глубин.$B$BВероятно, она тесно связана с другими рунами. Посвященный Клондацк считает, что их следует уничтожить. Все до одной.','Уничтожьте сумеречную руну земли, руну воды, руну воздуха и руну огня.','Ну вот, будут знать, как вторгаться на нашу исконную территорию!$B$BОй, а там что такое?! Смотри!','Поговорите с посвященным Клондацком в Элементиевых глубинах, что на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уничтожение рун',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Изучая сумеречную руну земли, вы почти ощущаете, как ее сила устремляется на самое дно Элементиевых глубин.$B$BВероятно, она тесно связана с другими рунами. Посвященный Клондацк считает, что их следует уничтожить. Все до одной.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте сумеречную руну земли, руну воды, руну воздуха и руну огня.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну вот, будут знать, как вторгаться на нашу исконную территорию!$B$BОй, а там что такое?! Смотри!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с посвященным Клондацком в Элементиевых глубинах, что на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27745,'Пламенная встреча','Это же Магмазуб, мой бывший элементаль огня. $n, я тебя умоляю, убей его. Иначе он меня прикончит!$B$BЭто было всего лишь недоразумение... Мы просто друг друга не поняли. Откуда мне было знать, что он так разъярится, когда я "позаимствовал" его сердце в Подземье? Все равно он не может умереть... во всяком случае, не навсегда!$B$BПульт управления порталом наверняка у него. Отбери у него пульт и активируй портал огня. И мы спокойненько перенесемся обратно к входу.','Отдайте пульт посвященному Клондацку у входа в Элементиевые глубины, что на Сумеречном нагорье.','Бывший элементаль огня посвященного Клондацка. Теперь между ними вражда.','Магмазуб') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пламенная встреча',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это же Магмазуб, мой бывший элементаль огня. $n, я тебя умоляю, убей его. Иначе он меня прикончит!$B$BЭто было всего лишь недоразумение... Мы просто друг друга не поняли. Откуда мне было знать, что он так разъярится, когда я "позаимствовал" его сердце в Подземье? Все равно он не может умереть... во всяком случае, не навсегда!$B$BПульт управления порталом наверняка у него. Отбери у него пульт и активируй портал огня. И мы спокойненько перенесемся обратно к входу.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отдайте пульт посвященному Клондацку у входа в Элементиевые глубины, что на Сумеречном нагорье.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Бывший элементаль огня посвященного Клондацка. Теперь между ними вражда.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Магмазуб',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (27746,'Империя грязи') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Империя грязи',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27747,'Дотла','Большинство дворфов клана Громового Молота уже сбежали отсюда, бросив дома и имущество. И сейчас самое время стереть их деревню с лица земли.$B$BОтправляйся на север. Там, в горах, ты найдешь брошенное поселение в руинах Громтара. В домах осталось немало бочонков с крепчайшим элем.$B$BЭль Громтара. Крепость – аж 220 градусов! Уж не знаю, как такое возможно.$B$BРазбей эти бочонки и подожги их содержимое. Сожги там все дотла! Чтобы дворфам было некуда возвращаться!','Отправляйтесь в руины Громтара и разбейте 10 бочонков громтарского эля.','Вернитесь к Харккану в Кровавое ущелье на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дотла',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Большинство дворфов клана Громового Молота уже сбежали отсюда, бросив дома и имущество. И сейчас самое время стереть их деревню с лица земли.$B$BОтправляйся на север. Там, в горах, ты найдешь брошенное поселение в руинах Громтара. В домах осталось немало бочонков с крепчайшим элем.$B$BЭль Громтара. Крепость – аж 220 градусов! Уж не знаю, как такое возможно.$B$BРазбей эти бочонки и подожги их содержимое. Сожги там все дотла! Чтобы дворфам было некуда возвращаться!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в руины Громтара и разбейте 10 бочонков громтарского эля.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Харккану в Кровавое ущелье на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27748,'Удача и слава','Нужно продолжать наступление, $n. Через некоторое время вражеские войска перегруппируются.$B$BСаркофаг должен быть прямо за этими руинами.$B$BИ держи ухо востро. Что-то мне подсказывает – далеко не все наши приключения позади...','Уничтожьте обсидианового колосса.','Обратитесь к Харрисону Джонсу на Возвышение Творца.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Удача и слава',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нужно продолжать наступление, $n. Через некоторое время вражеские войска перегруппируются.$B$BСаркофаг должен быть прямо за этими руинами.$B$BИ держи ухо востро. Что-то мне подсказывает – далеко не все наши приключения позади...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте обсидианового колосса.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Обратитесь к Харрисону Джонсу на Возвышение Творца.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27749,'Арест агентов','Ты правильно $gпоступил:поступила;, что $gпринес:принесла; мне эту записку, $n. Обращение короля запоздало: город наводнили вражеские агенты.$B$BВ записке содержатся указания к действию и места сбора сектантов, но в ней не написано, чем именно они занимаются. Наши враги стали умнее. Сложно будет выявить всех диверсантов, но попробуем захватить тех, кого сможем. Используй эти оковы, чтобы пленить агентов и приведи их ко входу в тюрьму, после чего доложи мне о выполнении задания.','Используйте тяжелые оковы, чтобы арестовать 5 секретных агентов сектантов, после чего приведите их к тюремщику Телвотеру в тюрьму. После заключения пленников под стражу допросите в тюрьме одного из задержанных сектантов.','Вернитесь к Жюстине Демалье в Торговом квартале Штормграда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Арест агентов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты правильно $gпоступил:поступила;, что $gпринес:принесла; мне эту записку, $n. Обращение короля запоздало: город наводнили вражеские агенты.$B$BВ записке содержатся указания к действию и места сбора сектантов, но в ней не написано, чем именно они занимаются. Наши враги стали умнее. Сложно будет выявить всех диверсантов, но попробуем захватить тех, кого сможем. Используй эти оковы, чтобы пленить агентов и приведи их ко входу в тюрьму, после чего доложи мне о выполнении задания.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте тяжелые оковы, чтобы арестовать 5 секретных агентов сектантов, после чего приведите их к тюремщику Телвотеру в тюрьму. После заключения пленников под стражу допросите в тюрьме одного из задержанных сектантов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Жюстине Демалье в Торговом квартале Штормграда.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27750,'Пища, отнятая у врага','Соберите 10 единиц съестных припасов Громового Молота в руинах Громтара.','<Грифф жадно хватает гору еды, которой хватило бы, чтобы накормить несколько дюжин человек.>$B$BОтлично! А ты сам-то поел?','Что-то я проголодался.','Принесите еду Гриффу в Кровавое ущелье на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пища, отнятая у врага',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 единиц съестных припасов Громового Молота в руинах Громтара.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Грифф жадно хватает гору еды, которой хватило бы, чтобы накормить несколько дюжин человек.>$B$BОтлично! А ты сам-то поел?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что-то я проголодался.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите еду Гриффу в Кровавое ущелье на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27751,'Сокрушение Громового Молота','С тех пор, как мы пришли на нагорье, дворфы из клана Громового Молота были и остаются нашими злейшими врагами. Эта война все никак не закончится! Мы дрались с ними в Грим Батоле, мы дрались с ними в Болотине и даже сейчас сражаемся – на севере, за рекой, в руинах Громтара.$B$BДокажи свою доблесть! Отыщи и сокруши передовых бойцов Громового Молота. Лучшие среди них носят знаки различия – мои бойцы собирают их дюжинами.$B$BХочу посмотреть, сколько соберешь ты.','Отправляйтесь в руины Громтара, убейте нескольких передовых бойцов Громового Молота и соберите 8 знаков Громового Молота. Персонажи, у которых есть имена, тоже носят знаки различия.','Принесите знаки Громового Молота Наркраллу Укротителю Драконов в Кровавое ущелье на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сокрушение Громового Молота',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','С тех пор, как мы пришли на нагорье, дворфы из клана Громового Молота были и остаются нашими злейшими врагами. Эта война все никак не закончится! Мы дрались с ними в Грим Батоле, мы дрались с ними в Болотине и даже сейчас сражаемся – на севере, за рекой, в руинах Громтара.$B$BДокажи свою доблесть! Отыщи и сокруши передовых бойцов Громового Молота. Лучшие среди них носят знаки различия – мои бойцы собирают их дюжинами.$B$BХочу посмотреть, сколько соберешь ты.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в руины Громтара, убейте нескольких передовых бойцов Громового Молота и соберите 8 знаков Громового Молота. Персонажи, у которых есть имена, тоже носят знаки различия.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите знаки Громового Молота Наркраллу Укротителю Драконов в Кровавое ущелье на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27752,'Боевой эль','Скажу тебе без ложной скромности – наши мастера-пивовары из Громтара варят просто волшебный эль! Лучший эль во всех Восточных королевствах! Крепость – аж 220 процентов. Да, ты не $gослышался:ослышалась;!$B$BКогда жители южных предместий бежали в город, им пришлось бросить свои дома, где у них были немалые запасы эля.$B$B<Бланди на миг умолкает, давая вам время осознать всю серьезность ситуации.>$B$BЕГО НАДО ВЕРНУТЬ! Одна кружка этого эля – и даже самый робкий солдат превращается в свирепого бешеного бойца, который сметает все на своем пути. Принеси мне побольше бочонков с элем! Это наша единственная надежда.','Отправляйтесь в руины Громтара и принесите 10 бочонков эля. И не вздумайте пробовать этот эль – с непривычки он валит с ног с двух глотков!','Принесите бочонки с элем младшему шаману Бланди в Громтар, что на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Боевой эль',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Скажу тебе без ложной скромности – наши мастера-пивовары из Громтара варят просто волшебный эль! Лучший эль во всех Восточных королевствах! Крепость – аж 220 процентов. Да, ты не $gослышался:ослышалась;!$B$BКогда жители южных предместий бежали в город, им пришлось бросить свои дома, где у них были немалые запасы эля.$B$B<Бланди на миг умолкает, давая вам время осознать всю серьезность ситуации.>$B$BЕГО НАДО ВЕРНУТЬ! Одна кружка этого эля – и даже самый робкий солдат превращается в свирепого бешеного бойца, который сметает все на своем пути. Принеси мне побольше бочонков с элем! Это наша единственная надежда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в руины Громтара и принесите 10 бочонков эля. И не вздумайте пробовать этот эль – с непривычки он валит с ног с двух глотков!',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите бочонки с элем младшему шаману Бланди в Громтар, что на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27753,'Вылазка за продовольствием','Наш запас продовольствия подходит к концу, $n. В Громтар стекаются беженцы со всего горного кряжа – нам просто не прокормить столько ртов!$B$BА ведь в брошенных беженцами домах осталось немало продуктов. Нужно забрать их сюда!$B$BОтправляйся в руины Громтара и поищи там еду – в южной, восточной и юго-западной части руин.$B$BТолько будь $gосторожен:осторожна;, |3-6($c)! Там повсюду идут напряженные бои. Смотри, чтоб тебя не пришибло.','Соберите 10 единиц съестных припасов Громового Молота в руинах Громтара.','Все замечательно сохранилось! Ничего не испортилось! Никаких червячков и жучков!$B$BТеперь у нас есть чем кормить беженцев.','Ну что? Добыл продовольствие?','Принесите продукты Фанни Громтар в Громтар, что на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вылазка за продовольствием',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наш запас продовольствия подходит к концу, $n. В Громтар стекаются беженцы со всего горного кряжа – нам просто не прокормить столько ртов!$B$BА ведь в брошенных беженцами домах осталось немало продуктов. Нужно забрать их сюда!$B$BОтправляйся в руины Громтара и поищи там еду – в южной, восточной и юго-западной части руин.$B$BТолько будь $gосторожен:осторожна;, |3-6($c)! Там повсюду идут напряженные бои. Смотри, чтоб тебя не пришибло.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 единиц съестных припасов Громового Молота в руинах Громтара.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Все замечательно сохранилось! Ничего не испортилось! Никаких червячков и жучков!$B$BТеперь у нас есть чем кормить беженцев.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что? Добыл продовольствие?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите продукты Фанни Громтар в Громтар, что на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`completedtext_loc8`) VALUES (27754,'Принесите знаки различия Колину Громтару в Громтар, что на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите знаки различия Колину Громтару в Громтар, что на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27755,'Проклятие гробниц','Убейте 6 безумных землекопов и Анжинера Злобекромса.','Вернитесь к пророку Солнца Тумету в Нахом в Ульдуме.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Проклятие гробниц',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 6 безумных землекопов и Анжинера Злобекромса.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к пророку Солнца Тумету в Нахом в Ульдуме.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (27756,'Штейгер','Если мы хотим понять, что тут творится, нам, похоже, придется прорубаться через Мертвые Копи! Первым твоим серьезным противником станет штейгер Глубток, могучий огр-маг. Берегись: он не только силен, как всякий огр, но и колдовством может изрядно вдарить!$B$BВозьми эту рацию для связи, пока ты там внизу. И будь $gосторожен:осторожна;.','Убейте Глубтока.','<Пшш-ш-ш...>$B$BПрекрасно! Чистая победа. Теперь иди дальше – посмотрим, что еще найдешь! Раз ты на нашей стороне, мы это дело щелкнем как орех, я уверен.','Что тебе?','Поговорите с лейтенантом Горацио Лейном в Мертвых копях.','Так просто он не сдастся.','Глубток','Страсти накаляются.','Лейтенант Горацио Лейн') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Штейгер',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если мы хотим понять, что тут творится, нам, похоже, придется прорубаться через Мертвые Копи! Первым твоим серьезным противником станет штейгер Глубток, могучий огр-маг. Берегись: он не только силен, как всякий огр, но и колдовством может изрядно вдарить!$B$BВозьми эту рацию для связи, пока ты там внизу. И будь $gосторожен:осторожна;.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Глубтока.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Пшш-ш-ш...>$B$BПрекрасно! Чистая победа. Теперь иди дальше – посмотрим, что еще найдешь! Раз ты на нашей стороне, мы это дело щелкнем как орех, я уверен.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что тебе?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с лейтенантом Горацио Лейном в Мертвых копях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Так просто он не сдастся.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Глубток',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Страсти накаляются.',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Лейтенант Горацио Лейн',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27757,'Непроглядная глубь','Я вижу, что по всему болоту морские жители ведут себя странно. Ну, с мурлоками понятно, но были ведь еще жаблины и макруры... На днях я даже видела на берегу наг.$B$BЧто-то притягивает их сюда и доводит до исступления. Оно манит их сюда все неотвратимее с каждым днем... Там что-то есть, теперь я абсолютно уверена, и если так будет продолжаться, мы сами вскоре туда безвольно поплетемся...$B$BТы $gдолжен:должна; положить этому конец – что бы это ни было.','Убейте Хр\'нглса Заблудшего.','Батюшки! Похоже, ты наткнулся на жутко зловещее создание. Интересно, зачем оно вообще сюда забралось...','Вернитесь к Бабе Тиночерп в Вязкую топь на Болоте Печали.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Непроглядная глубь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я вижу, что по всему болоту морские жители ведут себя странно. Ну, с мурлоками понятно, но были ведь еще жаблины и макруры... На днях я даже видела на берегу наг.$B$BЧто-то притягивает их сюда и доводит до исступления. Оно манит их сюда все неотвратимее с каждым днем... Там что-то есть, теперь я абсолютно уверена, и если так будет продолжаться, мы сами вскоре туда безвольно поплетемся...$B$BТы $gдолжен:должна; положить этому конец – что бы это ни было.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Хр\'нглса Заблудшего.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Батюшки! Похоже, ты наткнулся на жутко зловещее создание. Интересно, зачем оно вообще сюда забралось...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бабе Тиночерп в Вязкую топь на Болоте Печали.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (27758,'Плотник','Одолейте Хеликса Отломчикса.','Поговорите с лейтенантом Горацио Лейном в Мертвых копях.','Он часто разъезжает на свирепом Болванчике.','Хеликс Отломчикс','Наконец картинка начинает складываться.','Лейтенант Горацио Лейн') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Плотник',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Одолейте Хеликса Отломчикса.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с лейтенантом Горацио Лейном в Мертвых копях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Он часто разъезжает на свирепом Болванчике.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Хеликс Отломчикс',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Наконец картинка начинает складываться.',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Лейтенант Горацио Лейн',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (27760,'Искусственный интеллект','<Из портативного терминала раздается женский голос.>$B$BАварийный код: 55-729.$B$BУ членов экспедиции нарушено нормальное функционирование коры головного мозга.$B$BПроследуйте к ближайшей к вам терминальной установке, расположенной к юго-востоку от Террасы Солнечного Камня, для проведения дальнейших анализов.','Поговорите с терминалом АИДА на Заставе исследователей в Ульдуме.','Сканирование субъекта...$B$BДиагностика коры головного мозга не выявила присутствия феномена под названием "Проклятие гробницы".$B$BОднако диагностика показала, что субъект часто получает черепно-мозговые травмы. В будущем пользователю следует быть более внимательным при взаимодействии с тупыми предметами.','<Раздается жужжание – это заработали механизмы терминала.>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Искусственный интеллект',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Из портативного терминала раздается женский голос.>$B$BАварийный код: 55-729.$B$BУ членов экспедиции нарушено нормальное функционирование коры головного мозга.$B$BПроследуйте к ближайшей к вам терминальной установке, расположенной к юго-востоку от Террасы Солнечного Камня, для проведения дальнейших анализов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с терминалом АИДА на Заставе исследователей в Ульдуме.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сканирование субъекта...$B$BДиагностика коры головного мозга не выявила присутствия феномена под названием "Проклятие гробницы".$B$BОднако диагностика показала, что субъект часто получает черепно-мозговые травмы. В будущем пользователю следует быть более внимательным при взаимодействии с тупыми предметами.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Раздается жужжание – это заработали механизмы терминала.>',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (27761,'Отвлечь и обезвредить','Вернитесь к терминалу АИДА.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отвлечь и обезвредить',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к терминалу АИДА.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27762,'Фюзель, йо-хо-хо!','Эй, |3-6($r)! У меня для тебя есть работенка, от которой невозможно отказаться.$b$bНас сюда прислали из Фюзеля, что в Бесплодных землях. Там можно нереально разбогатеть. Именно так, $gдруг мой:душа моя;. Да и зомби там не так много, и заносчивые рыцари Серебряного Авангарда не мельтешат перед глазами.$b$bЭто просто дикое место, и мы ищем кого-то, кто поможет нам его обустроить. Как будешь $gготов:готова; отправиться, дай нам знать.','Долетите на ракете "Безупречность" до Бесплодных земель, после чего поговорите с Эдди Выпшиком.','Удачное приземление!','Поговорите с Эдди Выпшиком в Фюзеле-на-водах, в что в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Фюзель, йо-хо-хо!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эй, |3-6($r)! У меня для тебя есть работенка, от которой невозможно отказаться.$b$bНас сюда прислали из Фюзеля, что в Бесплодных землях. Там можно нереально разбогатеть. Именно так, $gдруг мой:душа моя;. Да и зомби там не так много, и заносчивые рыцари Серебряного Авангарда не мельтешат перед глазами.$b$bЭто просто дикое место, и мы ищем кого-то, кто поможет нам его обустроить. Как будешь $gготов:готова; отправиться, дай нам знать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Долетите на ракете "Безупречность" до Бесплодных земель, после чего поговорите с Эдди Выпшиком.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Удачное приземление!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Эдди Выпшиком в Фюзеле-на-водах, в что в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27764,'Необычная просьба','Теперь о других делах. Мне тут нужно доставить кое-что.$B$BНе так давно в нашем городе появилась одна юная дама, она искала прессованный порох, закаленную мифриловую оболочку для бомбы и защитные очки. Конечно, пороха и оболочек для бомбы у нас было сколько хочешь, а вот отыскать защитные очки оказалось сложнее.$B$BКороче говоря, очки у меня, но дамочка уже вернулась к своим изысканиям в долине Летлор. Отнесешь ей посылку?','Доставьте посылку Дольфа Рее в долину Летлор в Бесплодных землях.','Поговорите с Реей в долине Летлор в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Необычная просьба',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь о других делах. Мне тут нужно доставить кое-что.$B$BНе так давно в нашем городе появилась одна юная дама, она искала прессованный порох, закаленную мифриловую оболочку для бомбы и защитные очки. Конечно, пороха и оболочек для бомбы у нас было сколько хочешь, а вот отыскать защитные очки оказалось сложнее.$B$BКороче говоря, очки у меня, но дамочка уже вернулась к своим изысканиям в долине Летлор. Отнесешь ей посылку?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте посылку Дольфа Рее в долину Летлор в Бесплодных землях.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Реей в долине Летлор в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27765,'Первый образец: украденные яйца','Я экспериментирую с черными драконами. А конкретно – меня интересует, как они размножаются.$B$BМои нынешние опыты требуют множества драконьих яиц, потому я и нахожусь здесь, в долине Летлор. Я бы и сама занялась сбором яиц, но, думаю, ты извлечешь пользу из помощи мне.$B$BКладок много на краю долины. Однако остерегайся стражей, кружащих в небе, – им очень не нравится, когда воруют яйца.','Добудьте 6 яиц дикого черного дракона.','Вернитесь к Реа в долину Летлор в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Первый образец: украденные яйца',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я экспериментирую с черными драконами. А конкретно – меня интересует, как они размножаются.$B$BМои нынешние опыты требуют множества драконьих яиц, потому я и нахожусь здесь, в долине Летлор. Я бы и сама занялась сбором яиц, но, думаю, ты извлечешь пользу из помощи мне.$B$BКладок много на краю долины. Однако остерегайся стражей, кружащих в небе, – им очень не нравится, когда воруют яйца.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 6 яиц дикого черного дракона.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Реа в долину Летлор в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27766,'Второй образец: детеныши драконов','Хочу попросить тебя еще об одном одолжении. Мне нужны тела черных дракончиков, летающих тут неподалеку. Убей их, а трупики принеси мне.','Добудьте 10 тел обжигающих дракончиков.','Вернитесь к Реа в долину Летлор в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Второй образец: детеныши драконов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хочу попросить тебя еще об одном одолжении. Мне нужны тела черных дракончиков, летающих тут неподалеку. Убей их, а трупики принеси мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 10 тел обжигающих дракончиков.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Реа в долину Летлор в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27767,'Очередная шпионская миссия','Сектанты уверены в своей победе, несмотря на то, что мы арестовываем все больше и больше адептов культа. Нужно узнать побольше о ритуале, упомянутом сектантом, которого ты допрашивал.$B$BПо-видимому, эти ритуалы лежат в основе плана захвата Штормграда, разработанного культом. Я выдам тебе одеяния одного из арестованных сектантов. Надень их и вернись в их лагерь в Саду у Зеркального озера, что находится в Элвиннском лесу, после чего попробуй разузнать подробнее о планах последователей культа.','Наденьте одеяние рекрута, отправьтесь в Сад у Зеркального озера и достаньте книгу магических формул у надзирательницы Силандры. Прочтите книгу магических формул у алтаря сектантов, чтобы провести пробный ритуал.','Вернитесь к надзирательнице Силандре в Саду у Зеркального озера, что находится в Элвиннском лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Очередная шпионская миссия',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сектанты уверены в своей победе, несмотря на то, что мы арестовываем все больше и больше адептов культа. Нужно узнать побольше о ритуале, упомянутом сектантом, которого ты допрашивал.$B$BПо-видимому, эти ритуалы лежат в основе плана захвата Штормграда, разработанного культом. Я выдам тебе одеяния одного из арестованных сектантов. Надень их и вернись в их лагерь в Саду у Зеркального озера, что находится в Элвиннском лесу, после чего попробуй разузнать подробнее о планах последователей культа.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Наденьте одеяние рекрута, отправьтесь в Сад у Зеркального озера и достаньте книгу магических формул у надзирательницы Силандры. Прочтите книгу магических формул у алтаря сектантов, чтобы провести пробный ритуал.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к надзирательнице Силандре в Саду у Зеркального озера, что находится в Элвиннском лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (27768,'Шаг второй: кровопускатель','По вине троллей мои братья гибнут в непрекращающихся кошмарах. Тролли отравляют и порабощают зеленых драконов кровью своего мерзкого божества, а затем пожинают плоды того зла, что проросло в них. Моих собратьев разводят, как скот...$B$BЭта дичайшая мерзость должна прекратиться. Возвращайся к выходу из Зала Масок и следуй другим коридором в сторону бойни. Там Гомора Кровопускатель собирает трупы для отвратительных темных ритуалов. Возьми его жизнь – он ее не заслуживает!','Убейте Гомору Кровопускателя на бойне.','Когда он решил вредить моим собратьям, он подписал себе смертный приговор.','Гомора Кровопускатель','Камень клятвы связывает нас.','Лорд Итар') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Шаг второй: кровопускатель',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','По вине троллей мои братья гибнут в непрекращающихся кошмарах. Тролли отравляют и порабощают зеленых драконов кровью своего мерзкого божества, а затем пожинают плоды того зла, что проросло в них. Моих собратьев разводят, как скот...$B$BЭта дичайшая мерзость должна прекратиться. Возвращайся к выходу из Зала Масок и следуй другим коридором в сторону бойни. Там Гомора Кровопускатель собирает трупы для отвратительных темных ритуалов. Возьми его жизнь – он ее не заслуживает!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Гомору Кровопускателя на бойне.',`objectives_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Когда он решил вредить моим собратьям, он подписал себе смертный приговор.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Гомора Кровопускатель',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Камень клятвы связывает нас.',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Лорд Итар',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27769,'Рея срывает маску','Как я уже говорила, я не обычный гоблин. Может быть, ты уже $gдогадался:догадалась;, каков мой истинный облик.$B$BПозволь показать тебе мое настоящее лицо. Поскольку ты $gдоказал:доказала;, что тебе можно доверять, я поделюсь с тобой и подробностями своего плана.','Узнайте, кто такая Рея на самом деле.','Поговорите с Реастразой в долине Летлор в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рея срывает маску',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как я уже говорила, я не обычный гоблин. Может быть, ты уже $gдогадался:догадалась;, каков мой истинный облик.$B$BПозволь показать тебе мое настоящее лицо. Поскольку ты $gдоказал:доказала;, что тебе можно доверять, я поделюсь с тобой и подробностями своего плана.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Узнайте, кто такая Рея на самом деле.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Реастразой в долине Летлор в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27770,'Откровение','Узрите последний предмет исследований Реа.','Поговорите с Реа в долине Летлор в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Откровение',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Узрите последний предмет исследований Реа.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Реа в долине Летлор в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27771,'Третий образец: яйца Никсондры','Никсондру удерживают против ее воли. Она скрыта от своего потомства в самом центре гнезда. Она откладывает яйца, но их отбирают у нее прежде, чем вылупляются дракончики.$B$BЖестоко? Возможно. Но даже и наполовину не так жестоко, как обошелся ее род с моей повелительницей.$B$BДокажи, что я могу доверять тебе, $n. Возьми яйца Никсондры и принеси мне. Чтобы отобрать яйца, тебе придется силой заставить Никсондру подчиниться.','Добудьте 3 яйца Никсондры.','Вернитесь к Реа в долину Летлор в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Третий образец: яйца Никсондры',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Никсондру удерживают против ее воли. Она скрыта от своего потомства в самом центре гнезда. Она откладывает яйца, но их отбирают у нее прежде, чем вылупляются дракончики.$B$BЖестоко? Возможно. Но даже и наполовину не так жестоко, как обошелся ее род с моей повелительницей.$B$BДокажи, что я могу доверять тебе, $n. Возьми яйца Никсондры и принеси мне. Чтобы отобрать яйца, тебе придется силой заставить Никсондру подчиниться.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 3 яйца Никсондры.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Реа в долину Летлор в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27772,'Почтенный доктор Блам','Я неспроста открыла тебе правду о себе, $n. Мне нужно было завоевать твое доверие, но больше я не могу оставаться в долине Летлор, поскольку мое инкогнито раскрыто.$B$BОднако тебе, возможно, удастся ускользнуть незаметно. Вот, возьми результаты наших исследований и отнеси их на запад. В Уделе Эгмонда найди гнома, который знает, что делать с этими образцами.$B$BИ поторопись, $n! Не стоит задерживаться здесь дольше необходимого.','Принесите биологический материал черных драконов доктору Иерониму Бламу в Удел Эгмонда в Бесплодные земли.','О-о! Дела научные! Ну-ка, ну-ка, что тут у нас?..$B$BЯйца дичков? Какая дрянь. Совершенно бесполезны. Ни одного хорошего никогда не найдешь.$B$BУх ты, а это что? Какое-то... особо обработанное яйцо? Выглядит многообещающе, но не желаю даже знать, что Рея с ним творила.$B$BХм... да, несколько чудесных трупиков. Очень мило, правда.$B$BЛадно, посмотрим, что я смогу сделать.','Доктор Иеронимус Блам к вашим услугам. Чем могу помочь?','Поговорите с доктором Иеронимом Бламом в Уделе Эгмонда в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Почтенный доктор Блам',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я неспроста открыла тебе правду о себе, $n. Мне нужно было завоевать твое доверие, но больше я не могу оставаться в долине Летлор, поскольку мое инкогнито раскрыто.$B$BОднако тебе, возможно, удастся ускользнуть незаметно. Вот, возьми результаты наших исследований и отнеси их на запад. В Уделе Эгмонда найди гнома, который знает, что делать с этими образцами.$B$BИ поторопись, $n! Не стоит задерживаться здесь дольше необходимого.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите биологический материал черных драконов доктору Иерониму Бламу в Удел Эгмонда в Бесплодные земли.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О-о! Дела научные! Ну-ка, ну-ка, что тут у нас?..$B$BЯйца дичков? Какая дрянь. Совершенно бесполезны. Ни одного хорошего никогда не найдешь.$B$BУх ты, а это что? Какое-то... особо обработанное яйцо? Выглядит многообещающе, но не желаю даже знать, что Рея с ним творила.$B$BХм... да, несколько чудесных трупиков. Очень мило, правда.$B$BЛадно, посмотрим, что я смогу сделать.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Доктор Иеронимус Блам к вашим услугам. Чем могу помочь?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с доктором Иеронимом Бламом в Уделе Эгмонда в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (27773,'Шаг третий: пророк','Победите Джаммал\'ана Пророка.','Джаммал\'ан Пророк','Камень клятвы связывает нас.','Лорд Итар') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Шаг третий: пророк',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Джаммал\'ана Пророка.',`objectives_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Джаммал\'ан Пророк',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Камень клятвы связывает нас.',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Лорд Итар',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27774,'Легко поддающиеся внушению','Самую непосредственную угрозу для Фюзеля представляет, бесспорно, колония огров на северо-западе.$B$BБольшинство этих огров некогда были обычными воинами, но теперь многие из них занимаются магией. А мне не нужны огры-маги прямо под боком.$B$BПойди и грохни нескольких Гнилобрюхих. Думаю, они сообразят, что к чему, и не станут испытывать силу Фюзеля.','Убейте 9 огров из клана Гнилобрюхих в лагере Кош.','Любопытно, откуда вообще появились эти огры-маги. В интересные времена живем, однако...','Вернитесь к Дольфу Дымсту в Фюзель, что в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Легко поддающиеся внушению',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Самую непосредственную угрозу для Фюзеля представляет, бесспорно, колония огров на северо-западе.$B$BБольшинство этих огров некогда были обычными воинами, но теперь многие из них занимаются магией. А мне не нужны огры-маги прямо под боком.$B$BПойди и грохни нескольких Гнилобрюхих. Думаю, они сообразят, что к чему, и не станут испытывать силу Фюзеля.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 9 огров из клана Гнилобрюхих в лагере Кош.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Любопытно, откуда вообще появились эти огры-маги. В интересные времена живем, однако...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дольфу Дымсту в Фюзель, что в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27775,'Когда прижмет, можно и схитрить','Я уже целую вечность работаю над этим изобретением! А все никак не получается!$B$BВот оно, решение, – подумалось мне. Схитрю и прибегну к магии.$B$BДля моего изобретения требуется поршень, достаточно тонкий, чтобы влезть в узкую медную трубу, но в то же время крепкий, чтобы не ломался. Трости, которыми вооружены огры-маги, обитающие к северу отсюда, отлично подойдут.$B$BИ, по-моему, только у наставников достаточно крепкие экземпляры.','Добудьте трость у наставника магов из клана Гнилобрюхих в лагере Кош.','Классно получилось! Мой шокер для козлов наконец-то готов!','Терпеть не могу опускаться до магии в своих изобретениях... но дело не терпит отлагательств.','Вернитесь к Гарианне Вырпитук в Фюзель, что в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Когда прижмет, можно и схитрить',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я уже целую вечность работаю над этим изобретением! А все никак не получается!$B$BВот оно, решение, – подумалось мне. Схитрю и прибегну к магии.$B$BДля моего изобретения требуется поршень, достаточно тонкий, чтобы влезть в узкую медную трубу, но в то же время крепкий, чтобы не ломался. Трости, которыми вооружены огры-маги, обитающие к северу отсюда, отлично подойдут.$B$BИ, по-моему, только у наставников достаточно крепкие экземпляры.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте трость у наставника магов из клана Гнилобрюхих в лагере Кош.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Классно получилось! Мой шокер для козлов наконец-то готов!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Терпеть не могу опускаться до магии в своих изобретениях... но дело не терпит отлагательств.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гарианне Вырпитук в Фюзель, что в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27776,'Пусти козла в город...','У нас тут неприятности... с козлами, если ты еще не $gзаметил:заметила;. Они жрут все подряд и повадились, кажется, закусывать шестеренками и всякими детальками, которые мы тут грудами сваливаем.$B$BНадоело уже, знаешь ли.$B$BБольшинство козлов бродит на окраине городка, возле края утеса. Дай им небольшого "тычка"... вот этим приспособлением.','Ткните 12 козлов шокером Гарианны в Фюзеле.','Отлично! Не сомневаюсь – козлы вернутся, но, надеюсь, у них хватит мозгов, чтобы понять: мои шестеренки им жевать не стоит!','Вернитесь к Гарианне Вырпитук в Фюзель, что в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пусти козла в город...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У нас тут неприятности... с козлами, если ты еще не $gзаметил:заметила;. Они жрут все подряд и повадились, кажется, закусывать шестеренками и всякими детальками, которые мы тут грудами сваливаем.$B$BНадоело уже, знаешь ли.$B$BБольшинство козлов бродит на окраине городка, возле края утеса. Дай им небольшого "тычка"... вот этим приспособлением.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Ткните 12 козлов шокером Гарианны в Фюзеле.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! Не сомневаюсь – козлы вернутся, но, надеюсь, у них хватит мозгов, чтобы понять: мои шестеренки им жевать не стоит!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гарианне Вырпитук в Фюзель, что в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27777,'Коды доступа к ядру','Число членов экспедиции весьма велико, пользователь $n.$B$BЧтобы справиться с ними обычными методами, тебе понадобится приблизительно 2700136 с половиной часов.$B$BМы можем воспользоваться мощным источником энергии, содержащимся в машине-крабе из арсенала самой экспедиции.$B$BДля этого нам понадобятся коды доступа к ядру синтеза.$B$BУ Анжинера Торсиона есть эти коды. Его можно найти у башни Звездного Дозора, что к юго-востоку отсюда.$B$BВ это шифровальное устройство загружен вирус. С помощью него ты сможешь на время отключить систему защиты Торсиона.','Раздобудьте коды доступа к ядру у Торсиона Безумного.','Вернитесь к терминалу АИДА.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Коды доступа к ядру',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Число членов экспедиции весьма велико, пользователь $n.$B$BЧтобы справиться с ними обычными методами, тебе понадобится приблизительно 2700136 с половиной часов.$B$BМы можем воспользоваться мощным источником энергии, содержащимся в машине-крабе из арсенала самой экспедиции.$B$BДля этого нам понадобятся коды доступа к ядру синтеза.$B$BУ Анжинера Торсиона есть эти коды. Его можно найти у башни Звездного Дозора, что к юго-востоку отсюда.$B$BВ это шифровальное устройство загружен вирус. С помощью него ты сможешь на время отключить систему защиты Торсиона.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте коды доступа к ядру у Торсиона Безумного.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к терминалу АИДА.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) VALUES (27777,'Удалось ли тебе справиться с заданием, Лакот? Твои шансы на выживание я оценила как 68,5%.') ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось ли тебе справиться с заданием, Лакот? Твои шансы на выживание я оценила как 68,5%.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27778,'Взлом "Вибсона"','Это правда. Морем прибыли новые экспедиционные отряды.$B$BМои сканеры показывают, что они уже подпали под действие феномена проклятия.$B$BТебе нужно как можно скорее попасть на борт МАК "Водолаз". Коды доступа позволят нам получить контроль над функциями ядра синтеза, но перед этим придется взломать систему безопасности.$B$BПользователь $n, я должна попросить тебя провести взлом вычислителя с очень сложной структурой – он известен под названием "Вибсон".$B$BНе волнуйся, я снабжу тебя подробными инструкциями.','Взломайте вычислитель "Вибсон", установленный на борту "Водолаза".','Отправляйтесь к ядру синтеза, что наверху МАК "Водолаз" в Ульдуме.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Взлом "Вибсона"',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это правда. Морем прибыли новые экспедиционные отряды.$B$BМои сканеры показывают, что они уже подпали под действие феномена проклятия.$B$BТебе нужно как можно скорее попасть на борт МАК "Водолаз". Коды доступа позволят нам получить контроль над функциями ядра синтеза, но перед этим придется взломать систему безопасности.$B$BПользователь $n, я должна попросить тебя провести взлом вычислителя с очень сложной структурой – он известен под названием "Вибсон".$B$BНе волнуйся, я снабжу тебя подробными инструкциями.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Взломайте вычислитель "Вибсон", установленный на борту "Водолаза".',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отправляйтесь к ядру синтеза, что наверху МАК "Водолаз" в Ульдуме.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (27779,'Гномоцид','Я загрузила программу в ядро синтеза, и сейчас оно полностью под моим контролем.$B$BТам я создала небольшой воздушный карман, чтобы пользователь $n не $gизжарился:изжарилась;.$B$BЯ обездвижу себя, чтобы можно было посвятить мою тактовую частоту поддержанию ядра в стабильном состоянии.$B$BОтправляйся вниз по склону и нейтрализуй как можно большее число членов экспедиции.$B$BМои анализаторы показывают, что ты можешь начать испытывать чувство... "вины" из-за столь многочисленных жертв.$B$BПользователь $n, заверяю тебя, все члены экспедиции абсолютно безнадежны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гномоцид',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я загрузила программу в ядро синтеза, и сейчас оно полностью под моим контролем.$B$BТам я создала небольшой воздушный карман, чтобы пользователь $n не $gизжарился:изжарилась;.$B$BЯ обездвижу себя, чтобы можно было посвятить мою тактовую частоту поддержанию ядра в стабильном состоянии.$B$BОтправляйся вниз по склону и нейтрализуй как можно большее число членов экспедиции.$B$BМои анализаторы показывают, что ты можешь начать испытывать чувство... "вины" из-за столь многочисленных жертв.$B$BПользователь $n, заверяю тебя, все члены экспедиции абсолютно безнадежны.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27780,'Сначала было слово...','Теперь, когда ты $gизучил:изучила; ритуал, настала пора провести его в самом городе. Десятки наших собратьев уже на месте и ожидают часа, когда они смогут исполнить ритуал.$B$BЯ хочу, чтобы $gпосетил:посетила; места проведения ритуала в Квартале Дворфов, в парке Штормграда и на Соборной площади. Отряды, что мы посылали ранее, уже провели необходимую подготовку, так что тебе остается зачитать последнюю часть заклинания, записанного в книге.$B$BСкоро Штормград поглотят ветра и водная пучина, $n.','Расстройте планы сектантов в Квартале Дворфов, в парке Штормграда и в Соборном квартале, неверно зачитав заклинание из книги магических формул.','Вернитесь к Жюстине Демалье в Торговом квартале Штормграда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сначала было слово...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда ты $gизучил:изучила; ритуал, настала пора провести его в самом городе. Десятки наших собратьев уже на месте и ожидают часа, когда они смогут исполнить ритуал.$B$BЯ хочу, чтобы $gпосетил:посетила; места проведения ритуала в Квартале Дворфов, в парке Штормграда и на Соборной площади. Отряды, что мы посылали ранее, уже провели необходимую подготовку, так что тебе остается зачитать последнюю часть заклинания, записанного в книге.$B$BСкоро Штормград поглотят ветра и водная пучина, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Расстройте планы сектантов в Квартале Дворфов, в парке Штормграда и в Соборном квартале, неверно зачитав заклинание из книги магических формул.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Жюстине Демалье в Торговом квартале Штормграда.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (27781,'Машинации','<Пшш-ш-ш...>$B$B<Пшш-ш-ш...>Прие-ем! $n, ты на связи? $GЦел:Цела;? Прием!$B$BХвала богам, ты на связи! Какого, во имя Лордерона, они там строят?! Это же механическое чудище какое-то! Не дай им доделать эту... эту... штуку!$B$BВсе правила долой, делай все, что считаешь нужным, только помешай им!','Уничтожьте Врагорез-5000.','Поговорите с лейтенантом Горацио Лейном в Мертвых копях.','Не дай им достроить эту... штуковину!','Врагорез-5000','Лучше действуй исподтишка!','Лейтенант Горацио Лейн') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Машинации',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Пшш-ш-ш...>$B$B<Пшш-ш-ш...>Прие-ем! $n, ты на связи? $GЦел:Цела;? Прием!$B$BХвала богам, ты на связи! Какого, во имя Лордерона, они там строят?! Это же механическое чудище какое-то! Не дай им доделать эту... эту... штуку!$B$BВсе правила долой, делай все, что считаешь нужным, только помешай им!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте Врагорез-5000.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с лейтенантом Горацио Лейном в Мертвых копях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Не дай им достроить эту... штуковину!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Врагорез-5000',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Лучше действуй исподтишка!',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Лейтенант Горацио Лейн',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (27781,'<Пшш-ш-ш...>$B$BТы приближаешься к их логову. Скорее всего, путь к последнему убежищу братства преграждает особо крепкая дверь. Поищи что-нибудь, что заставит ее распахнуться!$B$BПредлагаю действовать скрытно!') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Пшш-ш-ш...>$B$BТы приближаешься к их логову. Скорее всего, путь к последнему убежищу братства преграждает особо крепкая дверь. Поищи что-нибудь, что заставит ее распахнуться!$B$BПредлагаю действовать скрытно!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27782,'К Матиасу! Срочно!','Мы с тобой замечательно повеселились. Жаль, что тебе пора уходить. Но Матиас сказал, ты ему $gнужен:нужна;.$B$BОн говорит, это срочно!$B$BВозьмешь с собой что-нибудь на дорожку? Ну, там выпить-закусить...','Поговорите с мастером Матиасом Шоу в Сумеречной крепости в Сумеречном нагорье.','А я все ждал, когда ты вернешься. Мы знаем, где надо искать совершенное оружие Чо\'Галла!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','К Матиасу! Срочно!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы с тобой замечательно повеселились. Жаль, что тебе пора уходить. Но Матиас сказал, ты ему $gнужен:нужна;.$B$BОн говорит, это срочно!$B$BВозьмешь с собой что-нибудь на дорожку? Ну, там выпить-закусить...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с мастером Матиасом Шоу в Сумеречной крепости в Сумеречном нагорье.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А я все ждал, когда ты вернешься. Мы знаем, где надо искать совершенное оружие Чо\'Галла!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27783,'К Гароне! Срочно!','Мы с тобой замечательно повеселились. Жаль, что тебе пора уходить. Но Гарона сказала, что ты ей $gнужен:нужна;.$B$BГоворит, это срочно!$B$BВозьмешь с собой что-нибудь на дорожку? Ну, там выпить-закусить...','Поговорите с Гароной Полуорчихой в Сумеречной крепости в Сумеречном нагорье.','А я все ждала, когда ты вернешься. У нас мало времени. Мы знаем, где надо искать совершенное оружие Чо\'Галла!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','К Гароне! Срочно!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы с тобой замечательно повеселились. Жаль, что тебе пора уходить. Но Гарона сказала, что ты ей $gнужен:нужна;.$B$BГоворит, это срочно!$B$BВозьмешь с собой что-нибудь на дорожку? Ну, там выпить-закусить...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Гароной Полуорчихой в Сумеречной крепости в Сумеречном нагорье.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А я все ждала, когда ты вернешься. У нас мало времени. Мы знаем, где надо искать совершенное оружие Чо\'Галла!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27784,'Молот Сумерек','Пока тебя не было, я все-таки вычислил, где находится Молот Сумерек. Его выковали на Сумеречном алтаре, что к югу отсюда.$B$BПричем они совершили ошибку – я бы даже сказал, роковую ошибку: Чо\'Галл лично присутствовал при создании Молота на последнем этапе.$B$BЭти сведения достались нам дорогой ценой. Многие наши разведчики погибли.','Доберитесь до Молота Сумерек.','Молот Сумерек как бы парит в воздухе над алтарем, и его никто не охраняет...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Молот Сумерек',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пока тебя не было, я все-таки вычислил, где находится Молот Сумерек. Его выковали на Сумеречном алтаре, что к югу отсюда.$B$BПричем они совершили ошибку – я бы даже сказал, роковую ошибку: Чо\'Галл лично присутствовал при создании Молота на последнем этапе.$B$BЭти сведения достались нам дорогой ценой. Многие наши разведчики погибли.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доберитесь до Молота Сумерек.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Молот Сумерек как бы парит в воздухе над алтарем, и его никто не охраняет...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (27785,'Адмирал','<Пшш-ш-ш...>$B$BНевероятно... Они его почти отстроили заново! Времени в обрез, $n.$B$BАдмирал Терзающий Рев – правая рука Ванессы – должен быть на палубе. Нам ни за что до нее не добраться, пока он жив. Тебе придется взойти на недостроенный корабль-исполин, найти Терзающего Рева и избавиться от него, чтобы мы могли проникнуть на верхнюю палубу в каюту Ванессы.$B$BБудь $gосторожен:осторожна;: на адмирале лежит проклятье воргенов, и он с удовольствием проверит на тебе остроту своих клыков!','Убейте адмирала Терзающего Рева.','Поговорите с лейтенантом Горацио Лейном в Мертвых копях.','Приближайся с осторожностью!','Адмирал Терзающий Рев','Ну, вот и все.','Лейтенант Горацио Лейн') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Адмирал',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Пшш-ш-ш...>$B$BНевероятно... Они его почти отстроили заново! Времени в обрез, $n.$B$BАдмирал Терзающий Рев – правая рука Ванессы – должен быть на палубе. Нам ни за что до нее не добраться, пока он жив. Тебе придется взойти на недостроенный корабль-исполин, найти Терзающего Рева и избавиться от него, чтобы мы могли проникнуть на верхнюю палубу в каюту Ванессы.$B$BБудь $gосторожен:осторожна;: на адмирале лежит проклятье воргенов, и он с удовольствием проверит на тебе остроту своих клыков!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте адмирала Терзающего Рева.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с лейтенантом Горацио Лейном в Мертвых копях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Приближайся с осторожностью!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Адмирал Терзающий Рев',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Ну, вот и все.',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Лейтенант Горацио Лейн',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (27785,'<Пшш-ш-ш...>$B$BТвои изыскания нашли много сочувствующих среди разведчиков, Воидус. Многие ветераны ШРУ внимательно следили за твоим проникновением в Мертвые копи по своим штормградским переговорным устройствам.$B$BСам Матиас Шоу хочет с тобой побеседовать! Секундочку, переключаю на него.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Пшш-ш-ш...>$B$BТвои изыскания нашли много сочувствующих среди разведчиков, Воидус. Многие ветераны ШРУ внимательно следили за твоим проникновением в Мертвые копи по своим штормградским переговорным устройствам.$B$BСам Матиас Шоу хочет с тобой побеседовать! Секундочку, переключаю на него.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27786,'Молот Сумерек','Пока тебя не было, я все-таки вычислила, где находится Молот Сумерек. Его создали на Сумеречном алтаре, что к югу отсюда.$B$BПричем они совершили ошибку – я бы даже сказала, роковую ошибку: Чо\'Галл лично присутствовал при создании Молота на последнем этапе.$B$B<Гарона начинает точить мечи.>$B$BМногие кор\'кроны расстались с жизнью, чтобы добыть эти сведения.','Доберитесь до Молота Сумерек.','Молот Сумерек как бы парит в воздухе над алтарем, и его никто не охраняет...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Молот Сумерек',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пока тебя не было, я все-таки вычислила, где находится Молот Сумерек. Его создали на Сумеречном алтаре, что к югу отсюда.$B$BПричем они совершили ошибку – я бы даже сказала, роковую ошибку: Чо\'Галл лично присутствовал при создании Молота на последнем этапе.$B$B<Гарона начинает точить мечи.>$B$BМногие кор\'кроны расстались с жизнью, чтобы добыть эти сведения.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доберитесь до Молота Сумерек.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Молот Сумерек как бы парит в воздухе над алтарем, и его никто не охраняет...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27787,'Дробитель Черепов Горобраз','Это была ловушка! Чо\'Галл заманил вас сюда, используя Молот Сумерек как приманку. Он был уверен, что гронн прикончит вас с первого же удара.$B$BВы должны уцелеть и убить Дробителя Черепов Горобраза!','Постарайтесь уцелеть и убейте Дробителя Черепов Горобраза.','У тебя все вышло, малышка! Ты разделалась с этим проклятым гронном, и Чо\'Галлу пришлось бежать в бастион Сумрака.$B$BНо ты не волнуйся. С твоей помощью мы проникнем туда и покончим с Чо\'Галлом раз и навсегда!','Поговорите с Курдраном Громовым Молотом в Лагере Победителя на Сумеречном нагорье.','Его нужно уничтожить','Дробитель Черепов Горобраз') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дробитель Черепов Горобраз',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это была ловушка! Чо\'Галл заманил вас сюда, используя Молот Сумерек как приманку. Он был уверен, что гронн прикончит вас с первого же удара.$B$BВы должны уцелеть и убить Дробителя Черепов Горобраза!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Постарайтесь уцелеть и убейте Дробителя Черепов Горобраза.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','У тебя все вышло, малышка! Ты разделалась с этим проклятым гронном, и Чо\'Галлу пришлось бежать в бастион Сумрака.$B$BНо ты не волнуйся. С твоей помощью мы проникнем туда и покончим с Чо\'Галлом раз и навсегда!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Курдраном Громовым Молотом в Лагере Победителя на Сумеречном нагорье.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Его нужно уничтожить',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Дробитель Черепов Горобраз',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27788,'Дробитель Черепов Горобраз','Это была ловушка! Чо\'Галл заманил тебя сюда, используя Молот Сумерек как приманку. Он был уверен, что гронн прикончит тебя с первого же удара.$B$BТы $gдолжен:должна; уцелеть и убить Дробителя Черепов Горобраза!','Постарайтесь уцелеть и убейте Дробителя Черепов Горобраза.','Поговорите с полководцем Зелой у Тукмака, что на Сумеречном нагорье.','Вали его!','Дробитель Черепов Горобраз') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дробитель Черепов Горобраз',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это была ловушка! Чо\'Галл заманил тебя сюда, используя Молот Сумерек как приманку. Он был уверен, что гронн прикончит тебя с первого же удара.$B$BТы $gдолжен:должна; уцелеть и убить Дробителя Черепов Горобраза!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Постарайтесь уцелеть и убейте Дробителя Черепов Горобраза.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с полководцем Зелой у Тукмака, что на Сумеречном нагорье.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Вали его!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Дробитель Черепов Горобраз',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27789,'По троггам – из турели','Мне потребуется немного времени для анализа образцов, а также отдых от утомительного отстрела троггов. Давай, вставай за одну из турелей и убей троггов, сколько сможешь. А я тут пока поработаю.$B$BТурель действует двояко: есть обычный выстрел, а есть с электроперегрузкой, когда враги наваливаются кучей. Хе-хе... Ну, удачи тебе.$B$BИ, кстати, берегись больших и неповоротливых троггов. Если они окажутся поблизости, тебе, пожалуй, не поздоровится.','Займите место за уничтожающей турелью и сумейте пережить 4 атаки троггов.','Вот результаты. Я идентифицировал следы порчи во всех трех предоставленных образцах. Рея будет сильно разочарована.','Вернитесь к доктору Иерониму Бламу в Удел Эгмонда в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','По троггам – из турели',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне потребуется немного времени для анализа образцов, а также отдых от утомительного отстрела троггов. Давай, вставай за одну из турелей и убей троггов, сколько сможешь. А я тут пока поработаю.$B$BТурель действует двояко: есть обычный выстрел, а есть с электроперегрузкой, когда враги наваливаются кучей. Хе-хе... Ну, удачи тебе.$B$BИ, кстати, берегись больших и неповоротливых троггов. Если они окажутся поблизости, тебе, пожалуй, не поздоровится.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Займите место за уничтожающей турелью и сумейте пережить 4 атаки троггов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот результаты. Я идентифицировал следы порчи во всех трех предоставленных образцах. Рея будет сильно разочарована.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к доктору Иерониму Бламу в Удел Эгмонда в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27790,'Поговорите с лейтенантом Горацио Лейном в Мертвых копях.','Братству конец.','Мастер Матиас Шоу') ON DUPLICATE KEY UPDATE `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с лейтенантом Горацио Лейном в Мертвых копях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Братству конец.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Мастер Матиас Шоу',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27791,'Раскопки Пыльного Ветра','Есть у меня одна мысль... но это явный выстрел наудачу. К счастью, выстрелы наудачу – мой конек.$B$BК северу отсюда Лига исследователей обнаружила еще один комплекс руин титанов. Если на этом свете и есть кто старше и мудрее драконов, так именно титаны. Слыхал я даже, будто титаны-то и СОЗДАЛИ драконов!$B$BПоговори со старшим геологом Дардином в его лагере к северу отсюда. У него информации о титанах больше, чем у меня.$B$BНу, что я тебе говорил? Стреляй наудачу, и удача придет!','Поговорите со старшим геологом Дардином у Раскопок Пыльного Ветра, что в Бесплодных землях.','Доложите о своем прибытии старшему геологу Дардину на Раскопках Пыльного Ветра, что в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Раскопки Пыльного Ветра',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Есть у меня одна мысль... но это явный выстрел наудачу. К счастью, выстрелы наудачу – мой конек.$B$BК северу отсюда Лига исследователей обнаружила еще один комплекс руин титанов. Если на этом свете и есть кто старше и мудрее драконов, так именно титаны. Слыхал я даже, будто титаны-то и СОЗДАЛИ драконов!$B$BПоговори со старшим геологом Дардином в его лагере к северу отсюда. У него информации о титанах больше, чем у меня.$B$BНу, что я тебе говорил? Стреляй наудачу, и удача придет!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите со старшим геологом Дардином у Раскопок Пыльного Ветра, что в Бесплодных землях.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доложите о своем прибытии старшему геологу Дардину на Раскопках Пыльного Ветра, что в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27792,'На войне, в любви и археологии все средства хороши!','Так-так, давай-ка обо всем по порядку. Я не собираюсь рассиживаться тут и рассказывать обо всем, что мы обнаружили в этих руинах. У нас тут полно неприятностей!$B$BХуже всего – эти выскочки, хулиганы из Реликвария, орудующие на той стороне гробницы. Они утаскивают все наши находки! Как будто не знают, что копаться в руинах – призвание дворфов.$B$BПотряси-ка их "археологов" – как по мне, так имя "бандиты" им бы больше подошло – и верни мне драгоценные артефакты.$B$BА уж ПОТОМ поговорим о титанах.','Добудьте разбитую чашу, пыльную вазу, иероглиф земли и орудие троггов.','Вернитесь к старшему геологу Дардину на Раскопки Пыльного Ветра, что в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На войне, в любви и археологии все средства хороши!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Так-так, давай-ка обо всем по порядку. Я не собираюсь рассиживаться тут и рассказывать обо всем, что мы обнаружили в этих руинах. У нас тут полно неприятностей!$B$BХуже всего – эти выскочки, хулиганы из Реликвария, орудующие на той стороне гробницы. Они утаскивают все наши находки! Как будто не знают, что копаться в руинах – призвание дворфов.$B$BПотряси-ка их "археологов" – как по мне, так имя "бандиты" им бы больше подошло – и верни мне драгоценные артефакты.$B$BА уж ПОТОМ поговорим о титанах.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте разбитую чашу, пыльную вазу, иероглиф земли и орудие троггов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старшему геологу Дардину на Раскопки Пыльного Ветра, что в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27793,'Древние защитники','В центральном зале гробницы раздается нешуточный грохот. Все-таки что-то с теми огромными статуями неладно...','Внимательно осмотрите Стража и Часового.','Осмотрите сокровище титанов в Гробнице Стражей в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Древние защитники',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В центральном зале гробницы раздается нешуточный грохот. Все-таки что-то с теми огромными статуями неладно...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Внимательно осмотрите Стража и Часового.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Осмотрите сокровище титанов в Гробнице Стражей в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27794,'Возвращение к Бламу','В сундуке на подушечке лежит небольшой округлый предмет.$B$BЕсли в этой гробнице и есть артефакты титанов, то это точно один из них. Вы решаете отнести его доктору Бламу.','Отнесите Око стражей доктору Иерониму Бламу в Удел Эгмонда в Бесплодных землях.','Одно-единственное крошечное устройство?!$B$BНикогда не понимал я этих титанов...$B$BНу ладно! Давай-ка поглядим, что умеет этот глазик.','Поговорите с доктором Иеронимом Бламом в Уделе Эгмонда в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение к Бламу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В сундуке на подушечке лежит небольшой округлый предмет.$B$BЕсли в этой гробнице и есть артефакты титанов, то это точно один из них. Вы решаете отнести его доктору Бламу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите Око стражей доктору Иерониму Бламу в Удел Эгмонда в Бесплодных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Одно-единственное крошечное устройство?!$B$BНикогда не понимал я этих титанов...$B$BНу ладно! Давай-ка поглядим, что умеет этот глазик.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с доктором Иеронимом Бламом в Уделе Эгмонда в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (27795,'Силы тьмы','Все идет по плану. Их воины на грани истощения, и я послала в бой кавалерию.$B$BНо вот кого я не ждала, так это огров. Наши рыцари по силе не уступают этим дикарям, однако помощь им не помешает.$B$BТы снова $gнужен:нужна; мне на поле боя, $n. Немногие способны одолеть здорового огра, но на тебя я могу рассчитывать. Не подведи.','Вернитесь к Джоанне Блухарт на Заставу Болотной Воды на Болоте Печали.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Силы тьмы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Все идет по плану. Их воины на грани истощения, и я послала в бой кавалерию.$B$BНо вот кого я не ждала, так это огров. Наши рыцари по силе не уступают этим дикарям, однако помощь им не помешает.$B$BТы снова $gнужен:нужна; мне на поле боя, $n. Немногие способны одолеть здорового огра, но на тебя я могу рассчитывать. Не подведи.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джоанне Блухарт на Заставу Болотной Воды на Болоте Печали.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27796,'Пешка-страж','Когда эти деятели из Реликвария сюда заявились, мы задергались и стали выкапывать все без разбора.$B$BПечальный это был день для археологии.$B$BК счастью, Ольге удалось наткнуться вот на эту нефритовую статуэтку. Нам кажется, это своего рода ключ, но мы не можем понять, что он открывает. Может быть, тебе повезет больше?','Выясните, для чего нужна пешка-страж в Гробнице Стражей в Бесплодных землях.','<С легким щелчком статуэтка входит в углубление на большой каменной плите.>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пешка-страж',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда эти деятели из Реликвария сюда заявились, мы задергались и стали выкапывать все без разбора.$B$BПечальный это был день для археологии.$B$BК счастью, Ольге удалось наткнуться вот на эту нефритовую статуэтку. Нам кажется, это своего рода ключ, но мы не можем понять, что он открывает. Может быть, тебе повезет больше?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выясните, для чего нужна пешка-страж в Гробнице Стражей в Бесплодных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<С легким щелчком статуэтка входит в углубление на большой каменной плите.>',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27797,'Пешка-часовой','Статуэтку чуть было не стащили у нас эти бездельники из Реликвария Кровавого Взора. Нам удалось поймать их с поличным, мы вернули статуэтку, но это мало чем помогло.$B$BПохоже, статуэтка является своеобразным ключом, но никаких замков я в этих руинах не вижу. Не хочешь попробовать поискать?','Выясните, для чего нужна пешка-часовой в Гробнице Стражей в Бесплодных землях.','<Статуэтка легко входит в углубление в холодной мраморной плите.>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пешка-часовой',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Статуэтку чуть было не стащили у нас эти бездельники из Реликвария Кровавого Взора. Нам удалось поймать их с поличным, мы вернули статуэтку, но это мало чем помогло.$B$BПохоже, статуэтка является своеобразным ключом, но никаких замков я в этих руинах не вижу. Не хочешь попробовать поискать?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выясните, для чего нужна пешка-часовой в Гробнице Стражей в Бесплодных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Статуэтка легко входит в углубление в холодной мраморной плите.>',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27798,'Живая вода','Возьми мою живую воду и влей ее в рот утонувшего дворфа.$B$BПри жизни он был кузнецом и работал с металлом, и хотя он уже мертв, вода вернет ему на время подобие жизни, и ты сможешь его расспросить и узнать все, что тебе нужно.$B$BА потом уходи из моих владений.','Расспросите труп начальника кузни Финлея, вернув ему подобие жизни с помощью живой воды.','Молот Сумерек? Говоришь, ты добыл эти сведения у утонувшего дворфа из клана Громового Молота?$B$BТы, наверное, шутишь!','Поговорите с Гароной Полуорчихой на Сумеречной крепости на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Живая вода',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Возьми мою живую воду и влей ее в рот утонувшего дворфа.$B$BПри жизни он был кузнецом и работал с металлом, и хотя он уже мертв, вода вернет ему на время подобие жизни, и ты сможешь его расспросить и узнать все, что тебе нужно.$B$BА потом уходи из моих владений.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Расспросите труп начальника кузни Финлея, вернув ему подобие жизни с помощью живой воды.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Молот Сумерек? Говоришь, ты добыл эти сведения у утонувшего дворфа из клана Громового Молота?$B$BТы, наверное, шутишь!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Гароной Полуорчихой на Сумеречной крепости на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27799,'Сначала было слово...','Теперь, когда ты $gизучил:изучила; ритуал, настала пора провести его в самом городе. Десятки наших собратьев уже находятся на месте в ожидании часа, когда они смогут исполнить ритуал.$B$BЯ хочу, чтобы $gпосетил:посетила; места проведения ритуала в Волоке, на Аллее Чести рядом с Залом Отважных, а также у западных врат Оргриммара. Отряды, что мы посылали ранее, уже провели необходимую подготовку, так что тебе остается зачитать последнюю часть заклинания, записанного в книге.$B$BСкоро город будет объят огнем.','Расстройте планы сектантов в Волоке, на Аллее Чести и у западных городских врат, неверно зачитав заклинание из книги магических формул.','Вернитесь к кровавому стражу Тореку на Аллею Силы Оргриммара.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сначала было слово...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда ты $gизучил:изучила; ритуал, настала пора провести его в самом городе. Десятки наших собратьев уже находятся на месте в ожидании часа, когда они смогут исполнить ритуал.$B$BЯ хочу, чтобы $gпосетил:посетила; места проведения ритуала в Волоке, на Аллее Чести рядом с Залом Отважных, а также у западных врат Оргриммара. Отряды, что мы посылали ранее, уже провели необходимую подготовку, так что тебе остается зачитать последнюю часть заклинания, записанного в книге.$B$BСкоро город будет объят огнем.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Расстройте планы сектантов в Волоке, на Аллее Чести и у западных городских врат, неверно зачитав заклинание из книги магических формул.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к кровавому стражу Тореку на Аллею Силы Оргриммара.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27800,'Очередная шпионская миссия','Сектанты уверены в своей победе, несмотря на то, что мы арестовываем все больше и больше адептов культа. Нужно узнать побольше о ритуале, упомянутом сектантом, которого ты допрашивал.$B$BПо-видимому, эти ритуалы лежат в основе плана захвата Оргриммара, разработанного культом. Я выдам тебе одеяние одного из арестованных сектантов, оно ему навряд ли пригодится. Облачись в него и вернись в лагерь сектантов на Свиноферме, что находится в Дуротаре, после чего попробуй разузнать подробнее о ритуалах и планах последователей культа.','Наденьте одеяние рекрута, отправьтесь на Свиноферму и достаньте книгу магических формул у надзирательницы Джинтак. Прочтите книгу магических формул у алтаря сектантов, чтобы провести пробный ритуал.','Вернитесь к надзирательнице Джинтак на Свиноферму, что в Дуротаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Очередная шпионская миссия',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сектанты уверены в своей победе, несмотря на то, что мы арестовываем все больше и больше адептов культа. Нужно узнать побольше о ритуале, упомянутом сектантом, которого ты допрашивал.$B$BПо-видимому, эти ритуалы лежат в основе плана захвата Оргриммара, разработанного культом. Я выдам тебе одеяние одного из арестованных сектантов, оно ему навряд ли пригодится. Облачись в него и вернись в лагерь сектантов на Свиноферме, что находится в Дуротаре, после чего попробуй разузнать подробнее о ритуалах и планах последователей культа.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Наденьте одеяние рекрута, отправьтесь на Свиноферму и достаньте книгу магических формул у надзирательницы Джинтак. Прочтите книгу магических формул у алтаря сектантов, чтобы провести пробный ритуал.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к надзирательнице Джинтак на Свиноферму, что в Дуротаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27801,'Предъявите документы!','Стражники недавно обнаружили группу сектантов, пытающихся проникнуть в город. На входе в Оргриммар образовался огромный затор. Вождь приказал, чтобы всех прибывающих осматривали перед городскими воротами. Возьми копию его обращения и зачитай его собравшимся у главных врат, после чего помоги стражу в обыске прибывающих.','Направляйтесь к главным вратам Оргриммара, зачитайте там обращение вождя и обыщите 5 горожан Оргриммара. Оставляйте у себя все подозрительные предметы, что обнаружите при обыске.','Вернитесь к кровавому стражу Тореку на Аллею Силы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Предъявите документы!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Стражники недавно обнаружили группу сектантов, пытающихся проникнуть в город. На входе в Оргриммар образовался огромный затор. Вождь приказал, чтобы всех прибывающих осматривали перед городскими воротами. Возьми копию его обращения и зачитай его собравшимся у главных врат, после чего помоги стражу в обыске прибывающих.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Направляйтесь к главным вратам Оргриммара, зачитайте там обращение вождя и обыщите 5 горожан Оргриммара. Оставляйте у себя все подозрительные предметы, что обнаружите при обыске.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к кровавому стражу Тореку на Аллею Силы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27802,'Арест агентов','Обнаруженная тобой записка может значить лишь одно: обращение вождя запоздало и город наводнили вражеские агенты.$B$BВ записке содержатся указания к действию и места сбора сектантов, но в ней не написано, чем именно они занимаются. Наши враги стали умнее. Сложно будет выявить всех диверсантов, но попробуем захватить тех, кого сможем. Используй эти оковы, чтобы пленить агентов и приведи их к стражу Гартоку Деснице Гнева на Арене Доблести, что находится на Аллее Чести.','Используйте тяжелые оковы, чтобы арестовать 5 секретных агентов сектантов, после чего приведите их к стражу Гартоку Деснице Гнева, находящемуся на Арене Доблести, что на Аллее Чести. После заключения пленников под стражу допросите в тюрьме одного из задержанных сектантов.','Вернитесь к кровавому стражу Тореку на Аллею Силы Оргриммара.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Арест агентов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Обнаруженная тобой записка может значить лишь одно: обращение вождя запоздало и город наводнили вражеские агенты.$B$BВ записке содержатся указания к действию и места сбора сектантов, но в ней не написано, чем именно они занимаются. Наши враги стали умнее. Сложно будет выявить всех диверсантов, но попробуем захватить тех, кого сможем. Используй эти оковы, чтобы пленить агентов и приведи их к стражу Гартоку Деснице Гнева на Арене Доблести, что находится на Аллее Чести.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте тяжелые оковы, чтобы арестовать 5 секретных агентов сектантов, после чего приведите их к стражу Гартоку Деснице Гнева, находящемуся на Арене Доблести, что на Аллее Чести. После заключения пленников под стражу допросите в тюрьме одного из задержанных сектантов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к кровавому стражу Тореку на Аллею Силы Оргриммара.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27803,'Им надо выспаться','Мои ребята держат линию обороны по всему периметру поселка, отбивая атаки элементалей, которые все прут и прут из развороченной земли. Они хорошие воины, сильные и выносливые. И пока что они еще держатся. Но даже самого крепкого дворфа со временем одолевает усталость.$B$BИх разделили на смены: один час на боевом посту, затем один час сна. Я понимаю, что этого мало. Но у нас не хватает бойцов.$B$BЕсли хочешь помочь, отправляйся на линию обороны и смени там кого-то из наших. Пусть хоть кто-нибудь поспит подольше. Возвращайся с докладом, когда убьешь... ну, хотя бы несколько элементалей.','Убейте 8 порабощенных поджигателей.','Отлично сработано. Ты молодец. У нас на счету каждый воин, и лишние руки, способные держать оружие, сейчас очень пригодятся.','Вернитесь к Кигану Огнебороду в Дозор Огнебородов на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Им надо выспаться',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мои ребята держат линию обороны по всему периметру поселка, отбивая атаки элементалей, которые все прут и прут из развороченной земли. Они хорошие воины, сильные и выносливые. И пока что они еще держатся. Но даже самого крепкого дворфа со временем одолевает усталость.$B$BИх разделили на смены: один час на боевом посту, затем один час сна. Я понимаю, что этого мало. Но у нас не хватает бойцов.$B$BЕсли хочешь помочь, отправляйся на линию обороны и смени там кого-то из наших. Пусть хоть кто-нибудь поспит подольше. Возвращайся с докладом, когда убьешь... ну, хотя бы несколько элементалей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 порабощенных поджигателей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично сработано. Ты молодец. У нас на счету каждый воин, и лишние руки, способные держать оружие, сейчас очень пригодятся.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кигану Огнебороду в Дозор Огнебородов на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27804,'Это наш дом','Нас уже оттеснили гораздо дальше, чем я мог предвидеть, но это не значит, что мы отдадим этим мерзавцам свои дома. Их могут жечь, ломать и грабить... Но даже если от них не останется камня на камне, мы все равно будем сражаться. Это наш дом, и мы никому его не отдадим!$B$BКстати, раз мы об этом заговорили... все-таки очень не хочется, чтобы наши дома сгорели. Мои парни сейчас как раз тушат пожары. Если захочешь помочь, они могут передавать тебе ведра по цепочке, и тебе не придется бегать к колодцу.','Потушите 50 очагов возгорания в Дозоре Огнебородов.','Спасибо за помощь. У нас сейчас на счету каждая пара рук.$B$BМы будем следить, чтобы у нас постоянно была вода – пока не прогоним отсюда этих сумеречных гадов.','Вернитесь к Кигану Огнебороду в Дозор Огнебородов на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Это наш дом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нас уже оттеснили гораздо дальше, чем я мог предвидеть, но это не значит, что мы отдадим этим мерзавцам свои дома. Их могут жечь, ломать и грабить... Но даже если от них не останется камня на камне, мы все равно будем сражаться. Это наш дом, и мы никому его не отдадим!$B$BКстати, раз мы об этом заговорили... все-таки очень не хочется, чтобы наши дома сгорели. Мои парни сейчас как раз тушат пожары. Если захочешь помочь, они могут передавать тебе ведра по цепочке, и тебе не придется бегать к колодцу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Потушите 50 очагов возгорания в Дозоре Огнебородов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо за помощь. У нас сейчас на счету каждая пара рук.$B$BМы будем следить, чтобы у нас постоянно была вода – пока не прогоним отсюда этих сумеречных гадов.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кигану Огнебороду в Дозор Огнебородов на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27805,'Хоть какое-то утешение','А ты, как я понимаю, и есть $gтот самый новенький:та самая новенькая;, кто помогает Кигану? Очень рада с тобой познакомиться. А можно тебя попросить сделать доброе дело для наших беженцев?$B$BНам пришлось быстро сниматься с места, бросить дома и имущество, в том числе разные дорогие сердцу мелочи. Ты все равно отправляешься в те края... Может, когда соберешься обратно, захватишь с собой наши вещи? И нам будет хотя бы какое-то утешение.','Разыщите засохшие розы Меары, молот Парлана из бивневой кости и куклу Априки, а затем верните все вещи их владельцам.','Ты такой добрый, такой отзывчивый. Огромное тебе спасибо!$B$BВ эти жестокие темные времена каждый маленький лучик света дарит надежду и радость. А ты и есть такой лучик.','Тебе удалось разыскать эти вещи? Я понимаю, сейчас не время думать о таких пустяках, но когда людям плохо, даже самая мелкая, самая крошечная радость имеет огромное значение.','Вернитесь к Кайлин Лонгфелло в Дозор Огнебородов на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хоть какое-то утешение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А ты, как я понимаю, и есть $gтот самый новенький:та самая новенькая;, кто помогает Кигану? Очень рада с тобой познакомиться. А можно тебя попросить сделать доброе дело для наших беженцев?$B$BНам пришлось быстро сниматься с места, бросить дома и имущество, в том числе разные дорогие сердцу мелочи. Ты все равно отправляешься в те края... Может, когда соберешься обратно, захватишь с собой наши вещи? И нам будет хотя бы какое-то утешение.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите засохшие розы Меары, молот Парлана из бивневой кости и куклу Априки, а затем верните все вещи их владельцам.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты такой добрый, такой отзывчивый. Огромное тебе спасибо!$B$BВ эти жестокие темные времена каждый маленький лучик света дарит надежду и радость. А ты и есть такой лучик.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось разыскать эти вещи? Я понимаю, сейчас не время думать о таких пустяках, но когда людям плохо, даже самая мелкая, самая крошечная радость имеет огромное значение.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кайлин Лонгфелло в Дозор Огнебородов на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (27806,'Почетная ноша','Поговорите с Иэном Огнебородом на Кладбище Огнебородов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Почетная ноша',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Иэном Огнебородом на Кладбище Огнебородов.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27807,'Клан Муллана','Если мы хотим сформировать отряд всадников на грифонах, нам надо быстрее собирать уцелевших бойцов, пока они не погибли или не покинули эти края. У меня уже есть на примете несколько групп всадников, наших давних союзников. В ближайшее время я отправляюсь на поиски всадников Громтара и всадников Мура.$B$BКогда я в последний раз видел воинов клана Муллана, они направлялись на запад, к Горнилу Крови. Следуй туда и попробуй уговорить Дугласа Муллана поступить на службу к Кигану. А уж Киган в долгу не останется.','Поговорите с Дугласом Мулланом у Горнила Крови.','Иэн тебя прислал, значит?$B$BКак-то ты не похож на Огнеборода. Ходят тут всякие... С какой такой радости мне тебя слушать?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Клан Муллана',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если мы хотим сформировать отряд всадников на грифонах, нам надо быстрее собирать уцелевших бойцов, пока они не погибли или не покинули эти края. У меня уже есть на примете несколько групп всадников, наших давних союзников. В ближайшее время я отправляюсь на поиски всадников Громтара и всадников Мура.$B$BКогда я в последний раз видел воинов клана Муллана, они направлялись на запад, к Горнилу Крови. Следуй туда и попробуй уговорить Дугласа Муллана поступить на службу к Кигану. А уж Киган в долгу не останется.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Дугласом Мулланом у Горнила Крови.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Иэн тебя прислал, значит?$B$BКак-то ты не похож на Огнеборода. Ходят тут всякие... С какой такой радости мне тебя слушать?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27808,'Упрямый, как Дойл','В последний раз всадников Дойла видели на юге, на краю Обсидианового леса. Воины Дойла – упрямые и несговорчивые ребята, так что тебе надо будет как следует постараться, чтобы уговорить их присоединиться к нам.$B$BНо я, кажется, знаю один убедительный аргумент. Скажи Киланду Дойлу, что среди беженцев, укрывшихся в городе, есть и Кайлин Лонгфелло. Киланд давно по ней сохнет, и, быть может, присутствие Кайлин сподвигнет его привести к нам своих бойцов.','Поговорите с Киландом Дойлом в лесу Нагорья.','Похоже, что всадникам Дойла крепко досталось в бою с сумеречными драконами.$B$BОни сражались до последнего. Если судить по следам, ни один наездник не отошел от своего грифона дальше, чем на два-три шага. Вряд ли кто-то из них уцелел в этом бою.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Упрямый, как Дойл',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В последний раз всадников Дойла видели на юге, на краю Обсидианового леса. Воины Дойла – упрямые и несговорчивые ребята, так что тебе надо будет как следует постараться, чтобы уговорить их присоединиться к нам.$B$BНо я, кажется, знаю один убедительный аргумент. Скажи Киланду Дойлу, что среди беженцев, укрывшихся в городе, есть и Кайлин Лонгфелло. Киланд давно по ней сохнет, и, быть может, присутствие Кайлин сподвигнет его привести к нам своих бойцов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Киландом Дойлом в лесу Нагорья.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Похоже, что всадникам Дойла крепко досталось в бою с сумеречными драконами.$B$BОни сражались до последнего. Если судить по следам, ни один наездник не отошел от своего грифона дальше, чем на два-три шага. Вряд ли кто-то из них уцелел в этом бою.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27809,'Надо их поторопить','Поговорите с Маккеем Огнебородом в военном лагере Горшака.','Говоришь, надо поторопиться? Тогда давай помогай упаковывать вcе это добро.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Надо их поторопить',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Маккеем Огнебородом в военном лагере Горшака.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Говоришь, надо поторопиться? Тогда давай помогай упаковывать вcе это добро.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27810,'Испытание боем','Киган хочет, чтобы всадники Муллана присоединились к его отряду? Ну, что ж... Если в мире есть дворф, ради которого я согласен подняться в воздух, так это он и никто другой! Мне только одно непонятно – с какой такой радости он прислал ко мне для таких важных переговоров $gкакого-то чужака:какую-то постороннюю барышню;. Это не очень-то вежливо, мне кажется.$B$BУверен, любой из моих ребят уделает тебя за 20 секунд, что за чаркой вина, что на поле брани. Давай вот как поступим: если ты победишь в драке кого-то из моих парней, я подумаю над предложением Кигана.','Вызовите на бой и победите одного из наездников на грифоне Муллана.','А что, очень даже неплохо! Выходит, ты настоящий боец. А так вот с виду не скажешь.','Поговорите с Дугласом Мулланом у Горнила Крови на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Испытание боем',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Киган хочет, чтобы всадники Муллана присоединились к его отряду? Ну, что ж... Если в мире есть дворф, ради которого я согласен подняться в воздух, так это он и никто другой! Мне только одно непонятно – с какой такой радости он прислал ко мне для таких важных переговоров $gкакого-то чужака:какую-то постороннюю барышню;. Это не очень-то вежливо, мне кажется.$B$BУверен, любой из моих ребят уделает тебя за 20 секунд, что за чаркой вина, что на поле брани. Давай вот как поступим: если ты победишь в драке кого-то из моих парней, я подумаю над предложением Кигана.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вызовите на бой и победите одного из наездников на грифоне Муллана.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А что, очень даже неплохо! Выходит, ты настоящий боец. А так вот с виду не скажешь.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Дугласом Мулланом у Горнила Крови на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27811,'Запах битвы','Пусть тебя не обманывает несговорчивость Дугласа. Наездники Муллана истосковались по полетам и рвутся в бой, и если есть в мире кто-то, ради кого мы поднимемся в воздух, так это Огнебород.$B$BМы оставили наших грифонов в лесу нагорья к югу отсюда, чтобы они поохотились и отдохнули от грохота битвы. Они заслужили отдых.$B$BЕсли хочешь, чтобы мы быстрее вступили в сражение, помоги привести наших грифонов обратно.$B$BВот возьми – это обуглившаяся высокогорная береза. Нужна для тренировки грифонов. Как только грифоны почуют этот запах, то сразу вернутся.','Разыщите 8 грифонов Муллана и отправьте их обратно к наездникам.','Отлично сработано. Знаешь, я себя чувствую неуютно, если моего грифона нет рядом. Плохо мне без него и тоскливо. Не могу, конечно, говорить за Дугласа и всех остальных, но я лично согласна вступить в отряд Огнеборода.','Вернитесь к Эдане Муллан к Горнилу Крови на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Запах битвы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пусть тебя не обманывает несговорчивость Дугласа. Наездники Муллана истосковались по полетам и рвутся в бой, и если есть в мире кто-то, ради кого мы поднимемся в воздух, так это Огнебород.$B$BМы оставили наших грифонов в лесу нагорья к югу отсюда, чтобы они поохотились и отдохнули от грохота битвы. Они заслужили отдых.$B$BЕсли хочешь, чтобы мы быстрее вступили в сражение, помоги привести наших грифонов обратно.$B$BВот возьми – это обуглившаяся высокогорная береза. Нужна для тренировки грифонов. Как только грифоны почуют этот запах, то сразу вернутся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите 8 грифонов Муллана и отправьте их обратно к наездникам.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично сработано. Знаешь, я себя чувствую неуютно, если моего грифона нет рядом. Плохо мне без него и тоскливо. Не могу, конечно, говорить за Дугласа и всех остальных, но я лично согласна вступить в отряд Огнеборода.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Эдане Муллан к Горнилу Крови на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27812,'Верность клана Муллана','Ты нас $gубедил:убедила;. Передай Кигану, что он может на нас рассчитывать. Мы придем в город сразу, как все соберутся.$B$BА ты молодец. $GСилен:Сильна; – почти как бойцы Громового Молота. Уж не знаю, откуда ты родом, но, похоже, народ у вас крепкий.$B$BВпрочем, я еще не видел, как ты пьешь. Вот это будет уже настоящее испытание.','Возвращайтесь к Иэну Огнебороду на Кладбище Огнебородов с известием о решении клана Муллана.','Значит, Мулланы с нами? Отличная новость! В бою эти ребята ценнее, чем их собственный вес в золоте. А они явно не тощие, да!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Верность клана Муллана',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты нас $gубедил:убедила;. Передай Кигану, что он может на нас рассчитывать. Мы придем в город сразу, как все соберутся.$B$BА ты молодец. $GСилен:Сильна; – почти как бойцы Громового Молота. Уж не знаю, откуда ты родом, но, похоже, народ у вас крепкий.$B$BВпрочем, я еще не видел, как ты пьешь. Вот это будет уже настоящее испытание.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возвращайтесь к Иэну Огнебороду на Кладбище Огнебородов с известием о решении клана Муллана.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Значит, Мулланы с нами? Отличная новость! В бою эти ребята ценнее, чем их собственный вес в золоте. А они явно не тощие, да!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27813,'Смерть Драконьей Пасти!','Бойцы Сумеречного Молота взяли город и перебили почти всех представителей клана Драконьей Пасти, которые здесь жили. Но кое-кто все-таки уцелел. И они недовольны, что мы забираем себе их припасы.$B$BСобственно, это не слишком большое горе.$B$BНо я все равно не хочу, чтобы они нападали на наших ребят. Сделай так, чтобы их здесь не было! Меня не волнует, убьешь ты их или прогонишь. Мне важен результат.','Убейте 6 бойцов из клана Драконьей Пасти.','А вот это дело! Давай-ка по-быстрому дособираем припасы и вернемся к Кигану.','Вернитесь к Маккею Огнебороду в военный лагерь Горшака на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Смерть Драконьей Пасти!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Бойцы Сумеречного Молота взяли город и перебили почти всех представителей клана Драконьей Пасти, которые здесь жили. Но кое-кто все-таки уцелел. И они недовольны, что мы забираем себе их припасы.$B$BСобственно, это не слишком большое горе.$B$BНо я все равно не хочу, чтобы они нападали на наших ребят. Сделай так, чтобы их здесь не было! Меня не волнует, убьешь ты их или прогонишь. Мне важен результат.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 6 бойцов из клана Драконьей Пасти.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А вот это дело! Давай-ка по-быстрому дособираем припасы и вернемся к Кигану.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Маккею Огнебороду в военный лагерь Горшака на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27814,'Перекованные мечи','Вот и славно. Большое спасибо! И вот еще чуток золота за труды.','Ну что, сколько насобирала?','Вернитесь к Брому Кузнецкому Молоту.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Перекованные мечи',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот и славно. Большое спасибо! И вот еще чуток золота за труды.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, сколько насобирала?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Брому Кузнецкому Молоту.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (27815,'Подарок для Иэна Огнеборода','$GПомог:Помогла; ребятам в лагере Горшака и $gвыполнил:выполнила; поручение Кузнецкого Молота? Очень даже неплохо для $gхудосочного:хиленькой:c; |3-1($c). Вот, отнеси эти мечи Иэну на Кладбище Огнебородов. Он тебя наградит за хорошую службу.','Отнесите оружие Кузнецкого Молота Иэну Огнебороду на Кладбище Огнебородов.','Ха! Похоже, их рейд прошел очень даже успешно! Когда мы наведем здесь порядок, непременно поставлю Кузнецкому Молоту бочонок эля.','Что там у тебя?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подарок для Иэна Огнеборода',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$GПомог:Помогла; ребятам в лагере Горшака и $gвыполнил:выполнила; поручение Кузнецкого Молота? Очень даже неплохо для $gхудосочного:хиленькой:c; |3-1($c). Вот, отнеси эти мечи Иэну на Кладбище Огнебородов. Он тебя наградит за хорошую службу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите оружие Кузнецкого Молота Иэну Огнебороду на Кладбище Огнебородов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ха! Похоже, их рейд прошел очень даже успешно! Когда мы наведем здесь порядок, непременно поставлю Кузнецкому Молоту бочонок эля.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что там у тебя?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27816,'Личный отчет','Жалко Дойла. И ребят его жалко. Хорошие были бойцы. Мы и сами-то уцелели лишь чудом. А им, видишь, не повезло.$B$BА эти жалкие трусы из Громтара поджали хвосты и сидят у себя в городишке, носа оттуда не кажут. Даже когда им сказали, что их призывает Киган, они все равно не пошли. Зато с нами Муры, а они одни стоят трех кланов.$B$BКиган хотел переговорить с тобой лично, когда ты вернешься. Так что давай отправляйся к нему. Он где-то в городе.','Поговорите с Киганом Огнебородом в Дозоре Огнебородов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Личный отчет',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Жалко Дойла. И ребят его жалко. Хорошие были бойцы. Мы и сами-то уцелели лишь чудом. А им, видишь, не повезло.$B$BА эти жалкие трусы из Громтара поджали хвосты и сидят у себя в городишке, носа оттуда не кажут. Даже когда им сказали, что их призывает Киган, они все равно не пошли. Зато с нами Муры, а они одни стоят трех кланов.$B$BКиган хотел переговорить с тобой лично, когда ты вернешься. Так что давай отправляйся к нему. Он где-то в городе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Киганом Огнебородом в Дозоре Огнебородов.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27817,'Удар Молота','Благодаря тебе и Иэну у нас набралось столько всадников, что теперь мы уж точно сможем дать отпор Сумеречному Молоту.$B$BМы умеем сражаться в полете, но когда второй всадник использует Молот бури, бой идет эффективнее. Я тут подумал... ты ведь наверняка рвешься в битву.$B$BДавай выбирай себе грифона – и вперед. И тебе лучше поторопиться. В ближайший час-полтора мы рассчитываем перебить всех сумеречных на этих летающих скалах.','Садитесь на одного из грифонов в Дозоре Огнебродов и убейте 12 сумеречных штормовержцев и Сервиаса Ветряного Ужаса.','Вот как оно делается, малышка.$B$BПолностью укомплектованный отряд всадников на грифонах – это реальная сила. Теперь мы разобьем этих Сумеречных в пух и прах. А ты молодец. Мы всегда рады такому соратнику.','Вернитесь к Кигану Огнебороду в Дозор Огнебородов на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Удар Молота',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Благодаря тебе и Иэну у нас набралось столько всадников, что теперь мы уж точно сможем дать отпор Сумеречному Молоту.$B$BМы умеем сражаться в полете, но когда второй всадник использует Молот бури, бой идет эффективнее. Я тут подумал... ты ведь наверняка рвешься в битву.$B$BДавай выбирай себе грифона – и вперед. И тебе лучше поторопиться. В ближайший час-полтора мы рассчитываем перебить всех сумеречных на этих летающих скалах.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Садитесь на одного из грифонов в Дозоре Огнебродов и убейте 12 сумеречных штормовержцев и Сервиаса Ветряного Ужаса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот как оно делается, малышка.$B$BПолностью укомплектованный отряд всадников на грифонах – это реальная сила. Теперь мы разобьем этих Сумеречных в пух и прах. А ты молодец. Мы всегда рады такому соратнику.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кигану Огнебороду в Дозор Огнебородов на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27818,'Скользкие знаки','Я здесь обосновалась задолго до появления Веслотопи – хотела варить свои настои в мире и покое. Знаю эту трясину как три своих старых сморщенных пальца.$B$BСо здешней фауной недавно произошли перемены. Пресмыкающиеся, которые тебе, должно быть, встречались под Вязкой топью, – это крылатые змеи, таких здесь не было испокон веков.$B$BИз них можно добыть отменные ингредиенты, если это те самые змеи. Будь душкой, набери мне их сердец.','Соберите 5 нетронутых сердец змеев в Вязкой топи.','Ну-ка, поглядим...$B$BОх, батюшки... Да, это точно они. От них, конечно, будет прок, однако боязно, когда поблизости водятся такие твари.','И не строй из себя брезгливого.','Вернитесь к Бабе Тиночерп в Вязкую топь на Болоте Печали.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Скользкие знаки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я здесь обосновалась задолго до появления Веслотопи – хотела варить свои настои в мире и покое. Знаю эту трясину как три своих старых сморщенных пальца.$B$BСо здешней фауной недавно произошли перемены. Пресмыкающиеся, которые тебе, должно быть, встречались под Вязкой топью, – это крылатые змеи, таких здесь не было испокон веков.$B$BИз них можно добыть отменные ингредиенты, если это те самые змеи. Будь душкой, набери мне их сердец.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 5 нетронутых сердец змеев в Вязкой топи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну-ка, поглядим...$B$BОх, батюшки... Да, это точно они. От них, конечно, будет прок, однако боязно, когда поблизости водятся такие твари.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','И не строй из себя брезгливого.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бабе Тиночерп в Вязкую топь на Болоте Печали.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (27819,'TEST - RVM') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','TEST - RVM',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (27821,'Орки и люди','С учетом того, что весь мир погряз в войне, меньше всего хотелось бы иметь поселение орков прямо у нас под боком. Красногорье, Сумеречный лес, даже Элвиннский лес – в дневном переходе отсюда.$B$BМы уже нанесли первый удар, и я не собираюсь позволять Орде перевести дух. Поэтому считай, что ты уже на задании. Хватай оружие, присоединяйся к основным силам в Кровавой топи и начинай охоту на орков.$B$BДоложи, когда нанесешь им достаточный ущерб. И возвращайся $gживым:живой;... это приказ. Вольно!','Вернитесь к Джоанне Блухарт на Заставу Болотной Воды на Болоте Печали.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Орки и люди',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','С учетом того, что весь мир погряз в войне, меньше всего хотелось бы иметь поселение орков прямо у нас под боком. Красногорье, Сумеречный лес, даже Элвиннский лес – в дневном переходе отсюда.$B$BМы уже нанесли первый удар, и я не собираюсь позволять Орде перевести дух. Поэтому считай, что ты уже на задании. Хватай оружие, присоединяйся к основным силам в Кровавой топи и начинай охоту на орков.$B$BДоложи, когда нанесешь им достаточный ущерб. И возвращайся $gживым:живой;... это приказ. Вольно!',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джоанне Блухарт на Заставу Болотной Воды на Болоте Печали.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (27822,'Лес рубят – щепки летят','Я хочу обеспечить полную победу. Иметь перевес в ресурсах недостаточно – нужно сделать так, чтобы врагу не досталось вообще ничего.$B$BКаменор зависит от древесины, которую добывают в окрестных лесах. Орочьи батраки на лесопилке, может быть, и не воины, но ненавидят людей не меньше.$B$BНе щади никого. Нужно перебить батраков и прервать поставки древесины в Каменор.','Вернитесь к Джоанне Блухарт на Заставу Болотной Воды на Болоте Печали.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лес рубят – щепки летят',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я хочу обеспечить полную победу. Иметь перевес в ресурсах недостаточно – нужно сделать так, чтобы врагу не досталось вообще ничего.$B$BКаменор зависит от древесины, которую добывают в окрестных лесах. Орочьи батраки на лесопилке, может быть, и не воины, но ненавидят людей не меньше.$B$BНе щади никого. Нужно перебить батраков и прервать поставки древесины в Каменор.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джоанне Блухарт на Заставу Болотной Воды на Болоте Печали.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27823,'У дворфов – свои нужды','Поверь, мне хорошие раскопки по душе, как и любому дворфу. Просто... мы тут так много копаем и так мало пьем, что иногда я подумываю: а не поставить ли лопату в угол и не вернуться ли в старый добрый Стальгорн?$B$BНо только не сегодня. У меня здесь еще дельце осталось.$B$BДворфы из клана Черного Железа с карьера Тяжелоступа – неподалеку, к северу отсюда – варят крепкое и славное пиво, да-да, прямо здесь, в пустыне. Не принесешь мне кружечку-другую?','Раздобудьте 15 кружек "Сумеречного крепкого".','<Сигрун тут же залпом выпивает пыльную кружку.>$B$BУф, вот же крепкое пойло! Я знал, что у них есть пиво, но никак не рассчитывал на "Сумеречное крепкое"! Это ж мое любимое!','<Сигрун облизывает губы в предвкушении.>','Вернитесь к Сигруну Рудотесу на Раскопки Пыльного Ветра, что в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','У дворфов – свои нужды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Поверь, мне хорошие раскопки по душе, как и любому дворфу. Просто... мы тут так много копаем и так мало пьем, что иногда я подумываю: а не поставить ли лопату в угол и не вернуться ли в старый добрый Стальгорн?$B$BНо только не сегодня. У меня здесь еще дельце осталось.$B$BДворфы из клана Черного Железа с карьера Тяжелоступа – неподалеку, к северу отсюда – варят крепкое и славное пиво, да-да, прямо здесь, в пустыне. Не принесешь мне кружечку-другую?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте 15 кружек "Сумеречного крепкого".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Сигрун тут же залпом выпивает пыльную кружку.>$B$BУф, вот же крепкое пойло! Я знал, что у них есть пиво, но никак не рассчитывал на "Сумеречное крепкое"! Это ж мое любимое!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Сигрун облизывает губы в предвкушении.>',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сигруну Рудотесу на Раскопки Пыльного Ветра, что в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27824,'За сокровищем – с кулаками','Есть у меня к тебе одно предложеньице – если ты, конечно, не против.$B$BДворфы Черного Железа ошивались тут еще до того, как прибыл Дардин со своими ребятами. А значит, как только руины титанов открылись, они – оба-на, тут как тут! – и все самое ценное сразу заграбастали. Бьюсь об заклад, в крепости Ангор на северо-западе у них еще полно сокровищ.$B$BТы уже $gдоказал, что способен:доказала, что способна; задать перцу дворфу. Вот и иди в крепость – проложи путь к сокровищу титанов.$B$BЯ бы и сам с тобой пошел, да вот пьян что-то сильно...','Поищите сокровище на нижнем уровне крепости Ангор.','Как, ты уже вернулась?','Вернитесь к Сигруну Рудотесу на Раскопки Пыльного Ветра, что в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','За сокровищем – с кулаками',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Есть у меня к тебе одно предложеньице – если ты, конечно, не против.$B$BДворфы Черного Железа ошивались тут еще до того, как прибыл Дардин со своими ребятами. А значит, как только руины титанов открылись, они – оба-на, тут как тут! – и все самое ценное сразу заграбастали. Бьюсь об заклад, в крепости Ангор на северо-западе у них еще полно сокровищ.$B$BТы уже $gдоказал, что способен:доказала, что способна; задать перцу дворфу. Вот и иди в крепость – проложи путь к сокровищу титанов.$B$BЯ бы и сам с тобой пошел, да вот пьян что-то сильно...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поищите сокровище на нижнем уровне крепости Ангор.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как, ты уже вернулась?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сигруну Рудотесу на Раскопки Пыльного Ветра, что в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27825,'Выживает жирнейший','Припасов у нас – кот наплакал... Черные драконы разоряют наши охотничьи угодья, и нам негде раздобыть пропитание.$B$BЗато у огров на юге есть все, что нам нужно. В их пещере ты найдешь вдоволь запасов мяса и ремесленного сырья.$B$BОгры наверняка так просто все это не отдадут, поэтому будь начеку.','Добудьте 6 порций мясного провианта и 10 отрезов шелка клана Гнилобрюхих.','Вижу, общение с ограми не доставило тебе особых хлопот. Держи – пара монет за труды.','Рада твоему возвращению.','Вернитесь к Виктории Долен, ожидающей у Драконьей Пасти, что в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Выживает жирнейший',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Припасов у нас – кот наплакал... Черные драконы разоряют наши охотничьи угодья, и нам негде раздобыть пропитание.$B$BЗато у огров на юге есть все, что нам нужно. В их пещере ты найдешь вдоволь запасов мяса и ремесленного сырья.$B$BОгры наверняка так просто все это не отдадут, поэтому будь начеку.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 6 порций мясного провианта и 10 отрезов шелка клана Гнилобрюхих.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вижу, общение с ограми не доставило тебе особых хлопот. Держи – пара монет за труды.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Рада твоему возвращению.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Виктории Долен, ожидающей у Драконьей Пасти, что в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27826,'Дорога в Драконью Пасть','<Доктор Блам смотрит на яйцевидный предмет в немом изумлении, моргает, словно не веря своим глазам, затем переводит взгляд на вас.>$B$BТы... ты это $gвидел:видела;? Невероятно! Мои догадки о титанах подтвердились! С твоей помощью, конечно.$B$BНадо отнести все это Рее. Она покинула долину Летлор. Еще бы! Пришлось – когда она трансформировалась в свою истинную форму прямо на глазах у дракончиков. Рея остановилась на западе, в лагере Альянса под названием Драконья Пасть.$B$BОна будет ждать тебя. Да, вместе с яйцом.','Отнесите очищенное от скверны яйцо черного дракона Рее в Драконью Пасть, что в Бесплодных землях.','Сообщите Рее о своем прибытии в Драконью Пасть, что в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дорога в Драконью Пасть',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Доктор Блам смотрит на яйцевидный предмет в немом изумлении, моргает, словно не веря своим глазам, затем переводит взгляд на вас.>$B$BТы... ты это $gвидел:видела;? Невероятно! Мои догадки о титанах подтвердились! С твоей помощью, конечно.$B$BНадо отнести все это Рее. Она покинула долину Летлор. Еще бы! Пришлось – когда она трансформировалась в свою истинную форму прямо на глазах у дракончиков. Рея остановилась на западе, в лагере Альянса под названием Драконья Пасть.$B$BОна будет ждать тебя. Да, вместе с яйцом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите очищенное от скверны яйцо черного дракона Рее в Драконью Пасть, что в Бесплодных землях.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Сообщите Рее о своем прибытии в Драконью Пасть, что в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27827,'Резвый, Лютый и Крепкий','В спешке покидая долину Летлор, я забыла завершить одно дело. Это касается Никсондры. Она на свободе и бросила тревожный клич среди черных драконов. Половина крыла здесь, на западе Бесплодных земель, прочесывает местность в поисках этого яйца.$B$BЯ позабочусь о том, чтобы его спрятать. А ты, пожалуйста, займись самыми опасными драконами. Не без помощи, конечно.$B$BПоговори с Эриком – вон там, на другой стороне лагеря. Он вместе с братьями пойдет с тобой.','Поговорите с Эриком "Резвым" в Драконьей Пасти, что в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Резвый, Лютый и Крепкий',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В спешке покидая долину Летлор, я забыла завершить одно дело. Это касается Никсондры. Она на свободе и бросила тревожный клич среди черных драконов. Половина крыла здесь, на западе Бесплодных земель, прочесывает местность в поисках этого яйца.$B$BЯ позабочусь о том, чтобы его спрятать. А ты, пожалуйста, займись самыми опасными драконами. Не без помощи, конечно.$B$BПоговори с Эриком – вон там, на другой стороне лагеря. Он вместе с братьями пойдет с тобой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Эриком "Резвым" в Драконьей Пасти, что в Бесплодных землях.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27828,'Эрик, капитан Необходимость','Прежде чем мы съедем с катушек и займемся уничтожением драконов, давай-ка я расскажу тебе немного, как я обычно дерусь.$B$BМеня называют "Резвый", и вот почему: я врубаюсь прямиком во врагов – шлемом вперед, прошу заметить – и оглушаю их на несколько секунд. Для особо сложных ситуаций у меня всегда припасено несколько склянок с зельями$B$BПочему бы нам не попрактиковаться? Давай, выйди в поле и попробуй.','Испытайте "Рывок Эрика" и карманное зелье Эрика.','Поговорите с Эриком "Резвым" в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Эрик, капитан Необходимость',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прежде чем мы съедем с катушек и займемся уничтожением драконов, давай-ка я расскажу тебе немного, как я обычно дерусь.$B$BМеня называют "Резвый", и вот почему: я врубаюсь прямиком во врагов – шлемом вперед, прошу заметить – и оглушаю их на несколько секунд. Для особо сложных ситуаций у меня всегда припасено несколько склянок с зельями$B$BПочему бы нам не попрактиковаться? Давай, выйди в поле и попробуй.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Испытайте "Рывок Эрика" и карманное зелье Эрика.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Эриком "Резвым" в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (27829,'Поход на дракона','Приветствую тебя, $n. Я смотрю, вы четверо уже успели познакомиться.$B$BВот тебе первое задание. Каларан, древний и могучий черный дракон, присоединился к охотникам за яйцом, которое мы оберегаем. Его необходимо остановить, прежде чем он подберется слишком близко.$B$BТы найдешь дракона и его приспешников в Знойных Песках, к северо-востоку от Драконьей Пасти. Выследи его и убей. Скорее всего, тебе понадобится помощь твоих новых союзников-дворфов.','Одолейте Каларана Уничтожителя и четверых солдат Летящей Тьмы.','Нужно сразить черного дракона, пока яйцо все еще уязвимо.','Реастраза','Дело еще не закончено.','Реастраза') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поход на дракона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приветствую тебя, $n. Я смотрю, вы четверо уже успели познакомиться.$B$BВот тебе первое задание. Каларан, древний и могучий черный дракон, присоединился к охотникам за яйцом, которое мы оберегаем. Его необходимо остановить, прежде чем он подберется слишком близко.$B$BТы найдешь дракона и его приспешников в Знойных Песках, к северо-востоку от Драконьей Пасти. Выследи его и убей. Скорее всего, тебе понадобится помощь твоих новых союзников-дворфов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Одолейте Каларана Уничтожителя и четверых солдат Летящей Тьмы.',`objectives_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Нужно сразить черного дракона, пока яйцо все еще уязвимо.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Реастраза',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Дело еще не закончено.',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Реастраза',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (27830,'Охота продолжается!','Черная драконья стая знает свое дело. Они заняли большую часть Нового Каргата, крупного поселения Орды к северо-западу от Драконьей Пасти. Войсками командуют генерал Жиракка и его правая рука, Молдарр. Их надо остановить.$B$BМы, драконы, не принимаем участия в этой вашей разборке между Ордой и Альянсом, но я понимаю, чем вы рискуете, отправляясь в Новый Каргат. Прошу вас, герои... будьте осторожны.','Победите генерала Жиракку, Молдарра и 6 черных драконоидов.','Молдарр и Жиракка командуют основной группировкой черных драконов.','Реастраза','Главное испытание еще впереди…','Реастраза') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота продолжается!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Черная драконья стая знает свое дело. Они заняли большую часть Нового Каргата, крупного поселения Орды к северо-западу от Драконьей Пасти. Войсками командуют генерал Жиракка и его правая рука, Молдарр. Их надо остановить.$B$BМы, драконы, не принимаем участия в этой вашей разборке между Ордой и Альянсом, но я понимаю, чем вы рискуете, отправляясь в Новый Каргат. Прошу вас, герои... будьте осторожны.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите генерала Жиракку, Молдарра и 6 черных драконоидов.',`objectives_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Молдарр и Жиракка командуют основной группировкой черных драконов.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Реастраза',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Главное испытание еще впереди…',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Реастраза',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (27831,'Печаль и гнев','Я бесконечно сожалею о том, как мы... нет, как я обращалась с Никсондрой. Я заставляла ее откладывать яйца и ставила над ними опыты. Снова и снова – без конца.$B$BДаже сама будучи матерью, я с трудом могу представить себе ее горе.$B$BНет... Мне нужно быть сильной. В конце концов, мы стараемся на благо будущих поколений черных драконов. Ее жертва не была напрасной.$B$BОна кружит над руинами Каргата, к северо-западу от Нового Каргата, обезумевшая от ярости. Пожалуйста, герои... избавьте Никсондру от страданий.','Убейте Никсондру и 12 ее детенышей.','Прости меня, Никсондра…','Реастраза','Почти готово.','Реастраза') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Печаль и гнев',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я бесконечно сожалею о том, как мы... нет, как я обращалась с Никсондрой. Я заставляла ее откладывать яйца и ставила над ними опыты. Снова и снова – без конца.$B$BДаже сама будучи матерью, я с трудом могу представить себе ее горе.$B$BНет... Мне нужно быть сильной. В конце концов, мы стараемся на благо будущих поколений черных драконов. Ее жертва не была напрасной.$B$BОна кружит над руинами Каргата, к северо-западу от Нового Каргата, обезумевшая от ярости. Пожалуйста, герои... избавьте Никсондру от страданий.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Никсондру и 12 ее детенышей.',`objectives_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Прости меня, Никсондра…',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Реастраза',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Почти готово.',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Реастраза',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27832,'Потайная кладка','Теперь, когда большинство черных драконов покинуло Бесплодные земли, переносить яйцо стало безопасно. Я буду на небольшом плато, к северу от Нового Каргата.$B$BИщи меня там.','Поговорите с Реей у Потайной кладки в Бесплодных землях.','Яйцо не может оставаться на одном месте. Опасность подстерегает повсюду.$B$BСмертокрыл, даже потеряв разум, все равно знает все укромные места в этом мире. Яйцо нужно все время перепрятывать.','Встретимся на севере.','Реастраза') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Потайная кладка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда большинство черных драконов покинуло Бесплодные земли, переносить яйцо стало безопасно. Я буду на небольшом плато, к северу от Нового Каргата.$B$BИщи меня там.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Реей у Потайной кладки в Бесплодных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Яйцо не может оставаться на одном месте. Опасность подстерегает повсюду.$B$BСмертокрыл, даже потеряв разум, все равно знает все укромные места в этом мире. Яйцо нужно все время перепрятывать.',`offerrewardtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Встретимся на севере.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Реастраза',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27833,'Затяжная оборона','Я бы сказал, что у нас тут сложности с драконами, хотя их, похоже, больше интересует Новый Каргат, чем наш скромный лагерь. И все же я отрядил наших лучших ребят сдерживать драконов.$b$bЕсть, правда, кое-что, оставшееся без внимания, – это лагерь огров к юго-западу отсюда. Похоже, из их логова вышла небольшая армия.$b$bМы не можем просто сидеть и ждать, пока они зайдут к нам в тыл, солдат. Сократи их численность – пока они не сократили нашу.','Уничтожьте 12 бойцов клана Гнилобрюхих. Можно убивать как извергов, так и шаманов этого клана.','Вернитесь к Террансу Шторму, ожидающему у Драконьей Пасти, что в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Затяжная оборона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я бы сказал, что у нас тут сложности с драконами, хотя их, похоже, больше интересует Новый Каргат, чем наш скромный лагерь. И все же я отрядил наших лучших ребят сдерживать драконов.$b$bЕсть, правда, кое-что, оставшееся без внимания, – это лагерь огров к юго-западу отсюда. Похоже, из их логова вышла небольшая армия.$b$bМы не можем просто сидеть и ждать, пока они зайдут к нам в тыл, солдат. Сократи их численность – пока они не сократили нашу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 12 бойцов клана Гнилобрюхих. Можно убивать как извергов, так и шаманов этого клана.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Террансу Шторму, ожидающему у Драконьей Пасти, что в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27834,'Бейлог, капитан Стеклянная Пушка','Прежде чем я начну забрасывать стрелами этих драконов, позволь представиться.$B$BЯ Бейлог, основная боевая сила этой группы. Мой меч острее зуба кроколиска, а стрелы поют как банши. Правда, мои силы быстро иссякают, я не могу выдержать столько урона, сколько двое моих братьев.$B$BОдно твое слово – и я прицельным выстрелом поражу сердце врага. Также я могу воодушевить своих братьев и дать им силу боевого безумия.$B$BПочему бы нам с тобой не попрактиковаться?','Испытайте выстрел Бейлога и боевой крик Бейлога.','Поговорите с Бейлогом в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бейлог, капитан Стеклянная Пушка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прежде чем я начну забрасывать стрелами этих драконов, позволь представиться.$B$BЯ Бейлог, основная боевая сила этой группы. Мой меч острее зуба кроколиска, а стрелы поют как банши. Правда, мои силы быстро иссякают, я не могу выдержать столько урона, сколько двое моих братьев.$B$BОдно твое слово – и я прицельным выстрелом поражу сердце врага. Также я могу воодушевить своих братьев и дать им силу боевого безумия.$B$BПочему бы нам с тобой не попрактиковаться?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Испытайте выстрел Бейлога и боевой крик Бейлога.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Бейлогом в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27835,'Олаф, капитан Громадина','Ты, может, не $gзаметил:заметила;, но для дворфа я довольно велик.$B$BИ обеспечиваю прикрытие своим братьям, чтобы они не попали в беду. Они мелковаты, и таких здоровых щитов, как у меня, у них нет. А я большой и запросто выдержу удары сразу нескольких чудовищ! К тому же, если не зевать, всегда можно подставить вместо себя щит!$B$BЯ и тебя могу защитить. Давай немного попрактикуемся. Уж я позабочусь, чтобы враги нападали на меня, а не на тебя.','Испытайте "Глухую защиту Олафа" и могучий рев Олафа.','Видишь? Не о чем беспокоиться, коли Олаф рядом. Одно твое слово – и я защищу тебя от любых чудовищ!','Поговорите с Олафом в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Олаф, капитан Громадина',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты, может, не $gзаметил:заметила;, но для дворфа я довольно велик.$B$BИ обеспечиваю прикрытие своим братьям, чтобы они не попали в беду. Они мелковаты, и таких здоровых щитов, как у меня, у них нет. А я большой и запросто выдержу удары сразу нескольких чудовищ! К тому же, если не зевать, всегда можно подставить вместо себя щит!$B$BЯ и тебя могу защитить. Давай немного попрактикуемся. Уж я позабочусь, чтобы враги нападали на меня, а не на тебя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Испытайте "Глухую защиту Олафа" и могучий рев Олафа.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Видишь? Не о чем беспокоиться, коли Олаф рядом. Одно твое слово – и я защищу тебя от любых чудовищ!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Олафом в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27836,'Остановить заразу','Недостаточно просто уничтожить тварей, осквернивших воды нашей реки, $n.$B$BВ ее священных водах вот-вот родится новое поколение этих гнусных созданий.$B$BНайди их яйца и тоже уничтожь.','Уничтожьте 6 яиц ползуна.','Вернитесь к верховному жрецу Амету на запруду Вир\'наал, что в Ульдуме.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Остановить заразу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Недостаточно просто уничтожить тварей, осквернивших воды нашей реки, $n.$B$BВ ее священных водах вот-вот родится новое поколение этих гнусных созданий.$B$BНайди их яйца и тоже уничтожь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 6 яиц ползуна.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному жрецу Амету на запруду Вир\'наал, что в Ульдуме.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (27837,'Чужаки в воде','Вернитесь к верховному жрецу Амету на запруду Вир\'наал, что в Ульдуме.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чужаки в воде',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному жрецу Амету на запруду Вир\'наал, что в Ульдуме.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27838,'Источник заражения','Тебе удалось устранить внешние признаки нашей проблемы, $n. Но я изучил этих тварей и пришел к выводу, что яйца отложены не ими.$B$BВода выносит яйца к запруде, но то существо, которое их откладывает, находится выше по течению.$B$BСтупай на северо-восток к истоку реки и устрани подлинный источник заражения.','Вернитесь к верховному жрецу Амету на запруду Нилоса.','Не будет чешуйчатой прародительницы, не будет яиц.','Чешуйчатая прародительница Хевна') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Источник заражения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе удалось устранить внешние признаки нашей проблемы, $n. Но я изучил этих тварей и пришел к выводу, что яйца отложены не ими.$B$BВода выносит яйца к запруде, но то существо, которое их откладывает, находится выше по течению.$B$BСтупай на северо-восток к истоку реки и устрани подлинный источник заражения.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному жрецу Амету на запруду Нилоса.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Не будет чешуйчатой прародительницы, не будет яиц.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Чешуйчатая прародительница Хевна',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27839,'Древнее оружие','Хотя формально война еще не объявлена, неферсеты без колебаний захватывают в плен и убивают всех, кто осмеливается зайти на их землю.$B$BКороль Фаорис запрещает нам отплатить той же монетой, даже несмотря на то что они тайком вывозят украденные реликвии из гробниц наших предков.$B$BМои разведчики доложили, что неферсеты готовятся перевезти большую партию украденного оружия. Сейчас они к югу отсюда.$B$BЯ приказал работникам, которых ты $gзавербовал:завербовала;, помочь тебе. Вызови их, подув в этот рожок, когда обнаружишь контрабандистов. Вместе вам предстоит вернуть украденное оружие.','Верните древнее оружие Тол\'вир.','Очень вовремя. Я раздам это оружие моим лучшим солдатам и работникам, которых ты завербовала.$B$BЧто-то подсказывает мне – с ним эти бойцы будут драться столь же яростно, как мои самые опытные капитаны.','Вернитесь к главнокомандующему Камзесу на заставу рамкахенов в Ульдуме.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Древнее оружие',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хотя формально война еще не объявлена, неферсеты без колебаний захватывают в плен и убивают всех, кто осмеливается зайти на их землю.$B$BКороль Фаорис запрещает нам отплатить той же монетой, даже несмотря на то что они тайком вывозят украденные реликвии из гробниц наших предков.$B$BМои разведчики доложили, что неферсеты готовятся перевезти большую партию украденного оружия. Сейчас они к югу отсюда.$B$BЯ приказал работникам, которых ты $gзавербовал:завербовала;, помочь тебе. Вызови их, подув в этот рожок, когда обнаружишь контрабандистов. Вместе вам предстоит вернуть украденное оружие.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните древнее оружие Тол\'вир.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Очень вовремя. Я раздам это оружие моим лучшим солдатам и работникам, которых ты завербовала.$B$BЧто-то подсказывает мне – с ним эти бойцы будут драться столь же яростно, как мои самые опытные капитаны.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к главнокомандующему Камзесу на заставу рамкахенов в Ульдуме.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27840,'Кристаллы дренетиста','Заблудшие, обитающие в Болотном пристанище, на вид как мы, однако они чудовища... лишившиеся разума из-за тягот нашего странствия в Азерот. Некогда наши братья, теперь они живут в Болотном пристанище на западе и нападают на всех, кто окажется поблизости.$B$BЕще они похитили нечто священное для нас – кристаллы дренетиста.$B$BУ нас недостаточно сил, чтобы напасть в Пристанище и вернуть кристаллы. Они лежат вокруг их хижин и костров. Без этих кристаллов... мы тоже можем сбиться с пути.','Отыщите 5 кристаллов дренетиста в Болотном Пристанище.','Вернитесь к Холаару на Заставу Болотной Воды на Болоте Печали.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кристаллы дренетиста',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Заблудшие, обитающие в Болотном пристанище, на вид как мы, однако они чудовища... лишившиеся разума из-за тягот нашего странствия в Азерот. Некогда наши братья, теперь они живут в Болотном пристанище на западе и нападают на всех, кто окажется поблизости.$B$BЕще они похитили нечто священное для нас – кристаллы дренетиста.$B$BУ нас недостаточно сил, чтобы напасть в Пристанище и вернуть кристаллы. Они лежат вокруг их хижин и костров. Без этих кристаллов... мы тоже можем сбиться с пути.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщите 5 кристаллов дренетиста в Болотном Пристанище.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Холаару на Заставу Болотной Воды на Болоте Печали.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27841,'Благодарный покойник','Как приятно было навестить друзей и родных! Только, кажется, я немного перестарался... и съел все, что они приготовили для меня! Даже крошки подмел!$B$BМогу ли я попросить тебя принести мне еще вкусного поминального хлеба? Я бы был очень благодарен!$B$BКажется, рецепт можно купить у Чепмана.','Принесите поминальный хлеб веселому духу гоблина на кладбище Оргриммара.$B$BЧтобы увидеть дух, используйте оранжевые бархатцы.','Какой же все-таки вкусный этот поминальный хлеб!$B$BПрошу, прими вот это в знак моей благодарности... Веселого тебе праздника!','Вернитесь к веселому духу гоблина в Дуротар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Благодарный покойник',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как приятно было навестить друзей и родных! Только, кажется, я немного перестарался... и съел все, что они приготовили для меня! Даже крошки подмел!$B$BМогу ли я попросить тебя принести мне еще вкусного поминального хлеба? Я бы был очень благодарен!$B$BКажется, рецепт можно купить у Чепмана.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите поминальный хлеб веселому духу гоблина на кладбище Оргриммара.$B$BЧтобы увидеть дух, используйте оранжевые бархатцы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Какой же все-таки вкусный этот поминальный хлеб!$B$BПрошу, прими вот это в знак моей благодарности... Веселого тебе праздника!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к веселому духу гоблина в Дуротар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (27842,'Это только начало','Убейте Глубтока.','Поговорите с Кагтой в Мертвых копях.','Так просто он не сдастся.','Глубток','Враг еще жив!','Кагта') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Это только начало',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Глубтока.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Кагтой в Мертвых копях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Так просто он не сдастся.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Глубток',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Враг еще жив!',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Кагта',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (27842,'Не пугайся, Галата. Я всегда рядом, скрываюсь в тени. Превосходно.$B$BТы должна идти дальше, а моя жизнь слишком ценна, чтобы рисковать ею среди этих жалких злоумышленников.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Не пугайся, Галата. Я всегда рядом, скрываюсь в тени. Превосходно.$B$BТы должна идти дальше, а моя жизнь слишком ценна, чтобы рисковать ею среди этих жалких злоумышленников.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27843,'Никакого подкрепления','Просто перебить огров недостаточно. На поле боя слишком быстро появляются новые.$B$BТы $gдолжен:должна; проникнуть вглубь за линию фронта и отыскать призывающих. Орки получают подкрепление с помощью чернокнижников.$B$BПеребей чернокнижников – и порталы закроются. Их немного; быстрый и точный удар подорвет силы врага.','Отлично, как всегда. Еще немного – и мы победим.','Вернитесь к Джоанне Блухарт на Заставу Болотной Воды на Болоте Печали.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Никакого подкрепления',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Просто перебить огров недостаточно. На поле боя слишком быстро появляются новые.$B$BТы $gдолжен:должна; проникнуть вглубь за линию фронта и отыскать призывающих. Орки получают подкрепление с помощью чернокнижников.$B$BПеребей чернокнижников – и порталы закроются. Их немного; быстрый и точный удар подорвет силы врага.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, как всегда. Еще немного – и мы победим.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джоанне Блухарт на Заставу Болотной Воды на Болоте Печали.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27844,'Предатели!!!','Одолейте Хеликса Отломчикса.','Мои наниматели не щадят предателей.$B$BС другой стороны, они щедры к тем, кто на их стороне! Ты заслужил награду!','Вернитесь к Крадли Дротик в Мертвых копях.','Часто видели верхом на свирепом Болванчике.','Хеликс Отломчикс') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Предатели!!!',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Одолейте Хеликса Отломчикса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мои наниматели не щадят предателей.$B$BС другой стороны, они щедры к тем, кто на их стороне! Ты заслужил награду!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Крадли Дротик в Мертвых копях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Часто видели верхом на свирепом Болванчике.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Хеликс Отломчикс',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27846,'Благодарный покойник','Как приятно было навестить друзей и родных! Только, кажется, я немного перестарался... и съел все, что они приготовили для меня! Даже крошки подмел!$B$BМогу ли я попросить тебя принести мне еще вкусного поминального хлеба? Я бы был очень благодарен!$B$BКажется, рецепт можно купить у Чепмана.','Принесите поминальный хлеб веселому духу воргена на кладбище Оргриммара.$B$BЧтобы увидеть дух, используйте оранжевые бархатцы.','Какой же все-таки вкусный этот поминальный хлеб!$B$BПрошу, прими вот это в знак моей благодарности... Веселого тебе праздника!','Вернитесь к веселому духу воргена на кладбище Дарнаса, что в Тельдрассиле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Благодарный покойник',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как приятно было навестить друзей и родных! Только, кажется, я немного перестарался... и съел все, что они приготовили для меня! Даже крошки подмел!$B$BМогу ли я попросить тебя принести мне еще вкусного поминального хлеба? Я бы был очень благодарен!$B$BКажется, рецепт можно купить у Чепмана.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите поминальный хлеб веселому духу воргена на кладбище Оргриммара.$B$BЧтобы увидеть дух, используйте оранжевые бархатцы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Какой же все-таки вкусный этот поминальный хлеб!$B$BПрошу, прими вот это в знак моей благодарности... Веселого тебе праздника!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к веселому духу воргена на кладбище Дарнаса, что в Тельдрассиле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27847,'Немного не то','Уничтожьте Врагорез-5000.','Превосходно! Теперь я могу спокойно закончить работу, и мои кровавые жнецы учинят... хаос... на всех фронтах!$B$BИ выскочки из Братства не получат барыши вместо меня!','Вернитесь к мисс Кавардак в Мертвые копи.','Уничтожь его! Не дай им переманить моих клиентов!','Врагорез-5000') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Немного не то',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте Врагорез-5000.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Превосходно! Теперь я могу спокойно закончить работу, и мои кровавые жнецы учинят... хаос... на всех фронтах!$B$BИ выскочки из Братства не получат барыши вместо меня!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мисс Кавардак в Мертвые копи.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Уничтожь его! Не дай им переманить моих клиентов!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Врагорез-5000',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (27848,'Хотели как лучше, а получилось как всегда','Братство Справедливости хочет достроить корабль-исполин и основательно потрепать Штормград. Достойная задача, за которую без лишних раздумий взялся бы любой орк!$B$BНо план Ванессы провалился. Корабль построен небрежно, команда неопытная, а хуже всего то, что среди них ворген!$B$BЕго зовут адмирал Терзающий Рев, и во имя нашего вождя его необходимо беспощадно покарать. Лок\'тар огар!','Убейте адмирала Терзающего Рева.','Поговорите с Кагтой в Мертвых копях.','Приближайся с осторожностью!','Адмирал Терзающий Рев','Достойный противник.','Кагта') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хотели как лучше, а получилось как всегда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Братство Справедливости хочет достроить корабль-исполин и основательно потрепать Штормград. Достойная задача, за которую без лишних раздумий взялся бы любой орк!$B$BНо план Ванессы провалился. Корабль построен небрежно, команда неопытная, а хуже всего то, что среди них ворген!$B$BЕго зовут адмирал Терзающий Рев, и во имя нашего вождя его необходимо беспощадно покарать. Лок\'тар огар!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте адмирала Терзающего Рева.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Кагтой в Мертвых копях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Приближайся с осторожностью!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Адмирал Терзающий Рев',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Достойный противник.',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Кагта',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (27848,'Какая жалость, что он был и воргеном, и человеком. Будь он гордым воином-орком, вместе пошли бы в бой плечом к плечу.$B$BНо оставим тщетные сожаления на потом. Пора отобрать у врага то, что нам нужно.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Какая жалость, что он был и воргеном, и человеком. Будь он гордым воином-орком, вместе пошли бы в бой плечом к плечу.$B$BНо оставим тщетные сожаления на потом. Пора отобрать у врага то, что нам нужно.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27849,'Штурм Каменора','Все готово, $n. Мы подошли вплотную к самому Каменору.$B$BДумаю, никому не нужно напоминать об этом, и все же я скажу: мы не орки и не уподобимся им из мести и злобы. Мы не спалим Каменор дотла, чтобы станцевать на пепелище.$B$BНет, поступим по чести. Пусть удар будет точечным. Выше головы – и никакой пощады любому орку, который посмеет взяться за оружие.','Убейте 6 защитников Каменора.','Вернитесь к Джоанне Блухарт на Заставу Болотной Воды.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Штурм Каменора',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Все готово, $n. Мы подошли вплотную к самому Каменору.$B$BДумаю, никому не нужно напоминать об этом, и все же я скажу: мы не орки и не уподобимся им из мести и злобы. Мы не спалим Каменор дотла, чтобы станцевать на пепелище.$B$BНет, поступим по чести. Пусть удар будет точечным. Выше головы – и никакой пощады любому орку, который посмеет взяться за оружие.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 6 защитников Каменора.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джоанне Блухарт на Заставу Болотной Воды.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27850,'Трусливая дрянь!!! Ванесса ван Клиф – грязная трусливая самка человека! Как смеет она бежать от битвы с Ордой!$B$B<Кагта берет себя в руки.>$B$BЛадно. Ее корабль – знатный трофей. Жители Штормграда первыми испытают на себе устрашающую мощь нашего корабля, руку к постройке которого приложил их собственный городской архитектор!','Поговорите с Кагтой в Мертвых копях.','Слава Изувеченной Длани!','Кагта') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Трусливая дрянь!!! Ванесса ван Клиф – грязная трусливая самка человека! Как смеет она бежать от битвы с Ордой!$B$B<Кагта берет себя в руки.>$B$BЛадно. Ее корабль – знатный трофей. Жители Штормграда первыми испытают на себе устрашающую мощь нашего корабля, руку к постройке которого приложил их собственный городской архитектор!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Кагтой в Мертвых копях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Слава Изувеченной Длани!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Кагта',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27851,'Отобрать пайки','Мы не стерли Каменор в пыль, но я не желаю туда возвращаться.$B$BСобери весь провиант, который найдешь в городе, пока там будешь. Не пройдет и дня, как в отсутствие продовольствия они останутся без бойцов.$B$BЯщики наверняка разбросаны по всему городу.','Захватите 5 ящиков провианта Каменора.','Доложи обстановку.','Вернитесь к Джоанне Блухарт на Заставу Болотной Воды на Болоте Печали.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отобрать пайки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы не стерли Каменор в пыль, но я не желаю туда возвращаться.$B$BСобери весь провиант, который найдешь в городе, пока там будешь. Не пройдет и дня, как в отсутствие продовольствия они останутся без бойцов.$B$BЯщики наверняка разбросаны по всему городу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Захватите 5 ящиков провианта Каменора.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Доложи обстановку.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джоанне Блухарт на Заставу Болотной Воды на Болоте Печали.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (27852,'Орки и люди','В топях бушует война, $n. Злобные людишки обосновались к северу от города и привели свою армию прямо к нашему порогу.$B$BВ этих болотах им делать нечего. Они пришли сюда, только чтобы напасть на нас без повода. Но мы не подарим им радость победы!$B$BНам не хватает воинов, и мне на поле боя нужен каждый боеспособный орк. Иди и перебей столько человек, сколько сможешь.','Вернитесь к командиру разведотряда Руагу в Каменор на Болоте Печали.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Орки и люди',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В топях бушует война, $n. Злобные людишки обосновались к северу от города и привели свою армию прямо к нашему порогу.$B$BВ этих болотах им делать нечего. Они пришли сюда, только чтобы напасть на нас без повода. Но мы не подарим им радость победы!$B$BНам не хватает воинов, и мне на поле боя нужен каждый боеспособный орк. Иди и перебей столько человек, сколько сможешь.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру разведотряда Руагу в Каменор на Болоте Печали.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27853,'Лес рубят – щепки летят','У Альянса численное превосходство. По своей трусости они прислали целую армию, чтобы разгромить одно поселение. Но мы не сдадимся без боя!$B$BНе имея ресурсов, их войска потеряют преимущество. Человечьи крестьяне ковыряются в лесу возле Заставы Болотной Воды, заготавливая лес для постройки своих шатких стен.$B$BЛиши их древесины, а заодно и жизни.','Ни один настоящий воин Орды не испытал бы радости от убийства перепуганных слабаков... Победа без сопротивления не дарует истинного удовлетворения.$B$BНо эта грязная работенка позволила оттеснить Альянс и защитить наши дома. Гордись своей службой на благо Орды.','Вернитесь к командиру разведотряда Руагу в Каменор на Болоте Печали.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лес рубят – щепки летят',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У Альянса численное превосходство. По своей трусости они прислали целую армию, чтобы разгромить одно поселение. Но мы не сдадимся без боя!$B$BНе имея ресурсов, их войска потеряют преимущество. Человечьи крестьяне ковыряются в лесу возле Заставы Болотной Воды, заготавливая лес для постройки своих шатких стен.$B$BЛиши их древесины, а заодно и жизни.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ни один настоящий воин Орды не испытал бы радости от убийства перепуганных слабаков... Победа без сопротивления не дарует истинного удовлетворения.$B$BНо эта грязная работенка позволила оттеснить Альянс и защитить наши дома. Гордись своей службой на благо Орды.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру разведотряда Руагу в Каменор на Болоте Печали.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (27854,'Силы тьмы','Вернитесь к командиру разведотряда Руагу в Каменор на Болоте Печали.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Силы тьмы',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру разведотряда Руагу в Каменор на Болоте Печали.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27855,'Никакого подкрепления','Альянс прислал сюда магов, чтобы те, сидя в крепости, телепортировали подкрепление прямо на поле боя. Мы должны это прекратить!$B$BМагов немного, но один-единственный портал может переломить ход битвы. Напади на их магов и закрой порталы!','Лишившись связи с тылом, Альянс теперь может полагаться только на те силы, которые привел в болота. Посмотрим, как они освоятся в привычных нам условиях.','Вернитесь к командиру разведотряда Руагу в Каменор на Болоте Печали.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Никакого подкрепления',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Альянс прислал сюда магов, чтобы те, сидя в крепости, телепортировали подкрепление прямо на поле боя. Мы должны это прекратить!$B$BМагов немного, но один-единственный портал может переломить ход битвы. Напади на их магов и закрой порталы!',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Лишившись связи с тылом, Альянс теперь может полагаться только на те силы, которые привел в болота. Посмотрим, как они освоятся в привычных нам условиях.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру разведотряда Руагу в Каменор на Болоте Печали.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27856,'Отметить павших','Немало воинов полегло во имя нашей победы, $n. Такова судьба истинного орка.$B$BЯ видел, как солдаты Альянса собирают трофеи у наших ушедших бойцов – хватают все подряд, словно крысы. Мы не позволим им осквернять тела павших на поле брани.$B$BВозьми эти заговоренные флаги, когда пойдешь в Кровавую топь. Установи их возле погибших воинов. Я увижу, скольких мы потеряли, и воздам почести их жертве. Да помогут нам духи, которых мы чтим.','Своей отвагой ты воздаешь почести и мертвым, и живым, $n.','Вернитесь к командиру разведотряда Руагу в Каменор на Болоте Печали.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отметить павших',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Немало воинов полегло во имя нашей победы, $n. Такова судьба истинного орка.$B$BЯ видел, как солдаты Альянса собирают трофеи у наших ушедших бойцов – хватают все подряд, словно крысы. Мы не позволим им осквернять тела павших на поле брани.$B$BВозьми эти заговоренные флаги, когда пойдешь в Кровавую топь. Установи их возле погибших воинов. Я увижу, скольких мы потеряли, и воздам почести их жертве. Да помогут нам духи, которых мы чтим.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Своей отвагой ты воздаешь почести и мертвым, и живым, $n.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру разведотряда Руагу в Каменор на Болоте Печали.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27857,'На нас напали!','Войска Альянса у наших стен!$B$BТвои действия их задержали и ослабили, $n, но все-таки мы в меньшинстве. Это наш последний бой. Победа – или смерть...$B$BСражайся с честью, $n. В данную минуту враг уже проник в город. Выдворим человечишек из Каменора! За Орду!','Атака Альянса отбита! Благодаря твоей ярости в бою город в безопасности. Лок\'тар огар!','Вернитесь к командиру разведотряда Руагу в Каменор на Болоте Печали.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На нас напали!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Войска Альянса у наших стен!$B$BТвои действия их задержали и ослабили, $n, но все-таки мы в меньшинстве. Это наш последний бой. Победа – или смерть...$B$BСражайся с честью, $n. В данную минуту враг уже проник в город. Выдворим человечишек из Каменора! За Орду!',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Атака Альянса отбита! Благодаря твоей ярости в бою город в безопасности. Лок\'тар огар!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру разведотряда Руагу в Каменор на Болоте Печали.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27858,'Дар Реастразы','Подожди здесь. Я достану яйцо.','Подождите, пока Реа достанет яйцо из Потайной кладки.','Прочтите записи Реа в Потайной кладке в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дар Реастразы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Подожди здесь. Я достану яйцо.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Подождите, пока Реа достанет яйцо из Потайной кладки.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Прочтите записи Реа в Потайной кладке в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27859,'Яйцо в безопасности','Подождите, пока Реа достанет яйцо из Потайной кладки.','Ты не единственный из смертных, кому удалось завоевать доверие Реастразы. Я тоже сумел.$B$BИ уже отправил очищенное от скверны яйцо в безопасное место, подальше от Бесплодных земель. Зародыш продолжит развиваться, не попав в поле зрения Смертокрыла.$B$BРод красных драконов столь же великодушен, сколь и могуществен. Реастраза просила передать тебе вот это.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Яйцо в безопасности',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Подождите, пока Реа достанет яйцо из Потайной кладки.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты не единственный из смертных, кому удалось завоевать доверие Реастразы. Я тоже сумел.$B$BИ уже отправил очищенное от скверны яйцо в безопасное место, подальше от Бесплодных земель. Зародыш продолжит развиваться, не попав в поле зрения Смертокрыла.$B$BРод красных драконов столь же великодушен, сколь и могуществен. Реастраза просила передать тебе вот это.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27860,'Заблудшие','Когда закрылся Темный портал, страх и сожаление охватили многих из тех, кто пришел в эти земли. В отчаянии они прокляли имя Света и погрязли в пучине насилия и ненависти.$B$BЭти падшие души – ныне Заблудшие, немногим отличные от чудовищ, которые нападают на всякого. С каждым днем они все глубже утопают во тьме, а поскольку вымирают, то стали заниматься хищениями из Убежища...$B$BИх уже не спасти, $n. Но мучениям нужно положить конец. Ты можешь избавить их от страданий?','Перебейте 12 Заблудших в Болотном пристанище.','Вернитесь к Холаару на Заставу Болотной Воды на Болоте Печали.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Заблудшие',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда закрылся Темный портал, страх и сожаление охватили многих из тех, кто пришел в эти земли. В отчаянии они прокляли имя Света и погрязли в пучине насилия и ненависти.$B$BЭти падшие души – ныне Заблудшие, немногим отличные от чудовищ, которые нападают на всякого. С каждым днем они все глубже утопают во тьме, а поскольку вымирают, то стали заниматься хищениями из Убежища...$B$BИх уже не спасти, $n. Но мучениям нужно положить конец. Ты можешь избавить их от страданий?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Перебейте 12 Заблудших в Болотном пристанище.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Холаару на Заставу Болотной Воды на Болоте Печали.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`) VALUES (27861,'Горнило Крови: боец из клана Кровавого Глаза!','А я все думал, когда ж ты объявишься, $n! Заполучить к нам сюда $gбывшего чемпиона:бывшую чемпионку; Кольца Крови – это ж прямо мечта! Народ валом повалит! Мы разбогатеем, $gдружище:подруга;! СКАЗОЧНО РАЗБОГАТЕЕМ!$B$BЭто старая бойцовская площадка Драконьей Пасти. Мы ее только чуток подновили. А потом я уж подсуетился, поговорил кое с кем – закинул удочки, так сказать – и набрал очень даже неслабых бойцов со всего Азерота. Так что пора зарабатывать деньги!$B$BТы знаешь, что делать, $n. Когда будешь $gготов:готова;, свисти. И мы сразу начнем!','Выйдите на арену Горнила Крови и одержите победу над Хурп\'дерпом!','Хурп\'дерп побежден','Вернитесь к троллю-прислужнику Водину в Горнило Крови на Сумеречном нагорье.','Хурп\'дерп побежден') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Горнило Крови: боец из клана Кровавого Глаза!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А я все думал, когда ж ты объявишься, $n! Заполучить к нам сюда $gбывшего чемпиона:бывшую чемпионку; Кольца Крови – это ж прямо мечта! Народ валом повалит! Мы разбогатеем, $gдружище:подруга;! СКАЗОЧНО РАЗБОГАТЕЕМ!$B$BЭто старая бойцовская площадка Драконьей Пасти. Мы ее только чуток подновили. А потом я уж подсуетился, поговорил кое с кем – закинул удочки, так сказать – и набрал очень даже неслабых бойцов со всего Азерота. Так что пора зарабатывать деньги!$B$BТы знаешь, что делать, $n. Когда будешь $gготов:готова;, свисти. И мы сразу начнем!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выйдите на арену Горнила Крови и одержите победу над Хурп\'дерпом!',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Хурп\'дерп побежден',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к троллю-прислужнику Водину в Горнило Крови на Сумеречном нагорье.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Хурп\'дерп побежден',`questgivertextwindow_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`) VALUES (27862,'Горнило Крови: боец из клана Кровавого Глаза!','Глазам не верю! Это же $n! $GБывший чемпион:Бывшая чемпионка; амфитеатра Страданий! Это ты очень удачно $gзашел:зашла;. Заполучить такого бойца – это же о-го-го! Народ валом повалит! Мы разбогатеем, $gдружище:подруга;! Как сыры в масле будем кататься, помяни мое слово.$B$BЭто старая бойцовская площадка Драконьей Пасти. Мы ее только чуток подновили. А потом я уж подсуетился, поговорил кое с кем – закинул удочки, так сказать – и набрал очень даже неслабых бойцов со всего Азерота. Так что пора зарабатывать деньги!$B$BТы знаешь, что делать, $n. Когда будешь $gготов:готова;, свисти. И мы сразу начнем!','Выйдите на арену Горнила Крови и одержите победу над Хурп\'дерпом!','Хурп\'дерп побежден','Вернитесь к троллю-прислужнику Водину в Горнило Крови на Сумеречном нагорье.','Хурп\'дерп побежден') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Горнило Крови: боец из клана Кровавого Глаза!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Глазам не верю! Это же $n! $GБывший чемпион:Бывшая чемпионка; амфитеатра Страданий! Это ты очень удачно $gзашел:зашла;. Заполучить такого бойца – это же о-го-го! Народ валом повалит! Мы разбогатеем, $gдружище:подруга;! Как сыры в масле будем кататься, помяни мое слово.$B$BЭто старая бойцовская площадка Драконьей Пасти. Мы ее только чуток подновили. А потом я уж подсуетился, поговорил кое с кем – закинул удочки, так сказать – и набрал очень даже неслабых бойцов со всего Азерота. Так что пора зарабатывать деньги!$B$BТы знаешь, что делать, $n. Когда будешь $gготов:готова;, свисти. И мы сразу начнем!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выйдите на арену Горнила Крови и одержите победу над Хурп\'дерпом!',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Хурп\'дерп побежден',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к троллю-прислужнику Водину в Горнило Крови на Сумеречном нагорье.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Хурп\'дерп побежден',`questgivertextwindow_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (27863,'Горнило Крови: боец из клана Кровавого Глаза!','Да, я не спорю. Этот край – то еще место, уж никак не Награнд и даже не Зул\'Драк, но знаешь, $gдружище:подруга;, я тебе вот что скажу: я просто двигаю туда, где можно заработать! Поэтому – добро пожаловать на Сумеречное нагорье!$B$BТы тут новичок, и я тебе объясню в двух словах, что здесь и как. Я организатор боев, этот сварливый тролль – мой телохранитель Водин. Ну а ты, стало быть, боец на потеху почтеннейшей публике. У нас тут все по желанию. Захочешь сражаться – собери друзей и скажи мне, а уж у меня найдутся для вас достойные противники.$B$BМожно и прямо сейчас, если хочешь. Ну что, будешь сражаться?','Выйдите на арену Горнила Крови и одержите победу над Хурп\'дерпом!','Неплохо, приятель. У тебя есть все данные, чтобы хорошо заработать на этом деле – если сумеешь остаться в живых.','Награда – по окончании боя, приятель.','Хурп\'дерп побежден','Вернитесь к троллю-прислужнику Водину в Горнило Крови на Сумеречном нагорье.','Участник боев из клана Кровавого Глаза.','Хурп\'дерп','Правая рука Гурга.','Водин') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Горнило Крови: боец из клана Кровавого Глаза!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Да, я не спорю. Этот край – то еще место, уж никак не Награнд и даже не Зул\'Драк, но знаешь, $gдружище:подруга;, я тебе вот что скажу: я просто двигаю туда, где можно заработать! Поэтому – добро пожаловать на Сумеречное нагорье!$B$BТы тут новичок, и я тебе объясню в двух словах, что здесь и как. Я организатор боев, этот сварливый тролль – мой телохранитель Водин. Ну а ты, стало быть, боец на потеху почтеннейшей публике. У нас тут все по желанию. Захочешь сражаться – собери друзей и скажи мне, а уж у меня найдутся для вас достойные противники.$B$BМожно и прямо сейчас, если хочешь. Ну что, будешь сражаться?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выйдите на арену Горнила Крови и одержите победу над Хурп\'дерпом!',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Неплохо, приятель. У тебя есть все данные, чтобы хорошо заработать на этом деле – если сумеешь остаться в живых.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Награда – по окончании боя, приятель.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Хурп\'дерп побежден',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к троллю-прислужнику Водину в Горнило Крови на Сумеречном нагорье.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Участник боев из клана Кровавого Глаза.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Хурп\'дерп',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Правая рука Гурга.',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Водин',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (27864,'Горнило Крови: смертоносная Драконья Пасть.','Выйдите на арену Горнила Крови и одержите победу над Торгом Свежевателем Драконов!','Я смотрю, ты не очень-то жалуешь орков. Ты его всего искромсал!','Торг Свежеватель Драконов побежден','Вернитесь к троллю-прислужнику Водину в Горнило Крови на Сумеречном нагорье.','Торг Свежеватель Драконов','Что может сравниться с любовью троллей.','Водин') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Горнило Крови: смертоносная Драконья Пасть.',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выйдите на арену Горнила Крови и одержите победу над Торгом Свежевателем Драконов!',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я смотрю, ты не очень-то жалуешь орков. Ты его всего искромсал!',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Торг Свежеватель Драконов побежден',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к троллю-прислужнику Водину в Горнило Крови на Сумеречном нагорье.',`completedtext_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Торг Свежеватель Драконов',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Что может сравниться с любовью троллей.',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Водин',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (27865,'Горнило Крови: грозный Грозовой Молот.','Слушай, тут такое дело... Тебе понравится! Бойцы Громового Молота узнали, что ты сражаешься на арене, и прямо-таки озверели. Говорят, сделают все, чтобы тебя вынесли с этой арены вперед ногами.$B$BЧто скажешь? Покажем им старую добрую драку |3-1($r) с дворфом? Начнем сразу, как будешь $gготов:готова;.','Выйдите на арену Горнила Крови и одержите победу над Суллом Коленодробом!','Сулл Коленодроб побежден','Вернитесь к троллю-прислужнику Водину в Горнило Крови на Сумеречном нагорье.','Береги пальцы ног.','Сулл Коленодроб','Что может сравниться с любовью троллей.','Водин') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Горнило Крови: грозный Грозовой Молот.',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слушай, тут такое дело... Тебе понравится! Бойцы Громового Молота узнали, что ты сражаешься на арене, и прямо-таки озверели. Говорят, сделают все, чтобы тебя вынесли с этой арены вперед ногами.$B$BЧто скажешь? Покажем им старую добрую драку |3-1($r) с дворфом? Начнем сразу, как будешь $gготов:готова;.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выйдите на арену Горнила Крови и одержите победу над Суллом Коленодробом!',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Сулл Коленодроб побежден',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к троллю-прислужнику Водину в Горнило Крови на Сумеречном нагорье.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Береги пальцы ног.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Сулл Коленодроб',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Что может сравниться с любовью троллей.',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Водин',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (27865,'Я смотрю, ты не очень-то жалуешь дворфов. Ты его всего искромсала!') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я смотрю, ты не очень-то жалуешь дворфов. Ты его всего искромсала!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (27866,'Горнило Крови: чудовище Колдера','Жестокий и кровопролитный, следующий бой – я уверен – понравится публике. Зрители будут вопить от восторга! Ну, или с досады... это уж кто за кого болеет. Колдер Грей собрал части тел побежденных бойцов и составил из них идеального воина. Прямо-таки боевую машину.$B$BЯ его видел... Потом три ночи не спал. Настоящее чудовище, даром что кадавр. И он рвется в бой. Ну что? Рискнешь сразиться? Как будешь $gготов:готова;, скажи, и мы сразу начнем.','Выйдите на арену Горнила Крови и одержите победу над составным кадавром!','Ну, ты силен! Когда это чудовище вывалилось на арену, знаешь, как я за тебя испугался?! Думал, все – тебе конец. Но ты порвал его в клочья!$B$BЛюбо-дорого было смотреть!','Составной кадавр побежден','Вернитесь к троллю-прислужнику Водину в Горнило Крови на Сумеречном нагорье.','Чудовищный плод всех предыдущих битв.','Составной кадавр','Это прямо как ты любишь, уж Водин знает.','Водин') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Горнило Крови: чудовище Колдера',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Жестокий и кровопролитный, следующий бой – я уверен – понравится публике. Зрители будут вопить от восторга! Ну, или с досады... это уж кто за кого болеет. Колдер Грей собрал части тел побежденных бойцов и составил из них идеального воина. Прямо-таки боевую машину.$B$BЯ его видел... Потом три ночи не спал. Настоящее чудовище, даром что кадавр. И он рвется в бой. Ну что? Рискнешь сразиться? Как будешь $gготов:готова;, скажи, и мы сразу начнем.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выйдите на арену Горнила Крови и одержите победу над составным кадавром!',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну, ты силен! Когда это чудовище вывалилось на арену, знаешь, как я за тебя испугался?! Думал, все – тебе конец. Но ты порвал его в клочья!$B$BЛюбо-дорого было смотреть!',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Составной кадавр побежден',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к троллю-прислужнику Водину в Горнило Крови на Сумеречном нагорье.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Чудовищный плод всех предыдущих битв.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Составной кадавр',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Это прямо как ты любишь, уж Водин знает.',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Водин',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (27867,'Горнило Крови: лорд-Потрошитель','В следующей схватке тебе придется туго. К нам специально приехал один знаменитый боец благородных кровей, очень опытный воин. Родом из Гилнеаса, полон решимости доказать, что он – лучший боец на этом материке Азерота.$B$BСразу предупреждаю: этот бой не на жизнь, а на смерть. В общем, как будешь $gготов:готова;, скажи, и мы сразу начнем.','Выйдите на арену Горнила Крови и одержите победу над лордом Джеффри Талваном!','Ты его сделал! А то я уж испугался... Когда он набросился на тебя, словно бешеный зверь, я подумал, что все – ты уже не отобьешься. Но ты победил! Хотя чему удивляться?! Давно можно было понять, что ты – крепкий орешек.','Лорд Джеффри Талван побежден','Вернитесь к троллю-прислужнику Водину в Горнило Крови на Сумеречном нагорье.','Действующий чемпион Горнила Крови, непобедимый лорд Джеффри Талван.','Лорд Джеффри Талван','Ни разу не переодевался за четыре года.','Водин') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Горнило Крови: лорд-Потрошитель',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В следующей схватке тебе придется туго. К нам специально приехал один знаменитый боец благородных кровей, очень опытный воин. Родом из Гилнеаса, полон решимости доказать, что он – лучший боец на этом материке Азерота.$B$BСразу предупреждаю: этот бой не на жизнь, а на смерть. В общем, как будешь $gготов:готова;, скажи, и мы сразу начнем.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выйдите на арену Горнила Крови и одержите победу над лордом Джеффри Талваном!',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты его сделал! А то я уж испугался... Когда он набросился на тебя, словно бешеный зверь, я подумал, что все – ты уже не отобьешься. Но ты победил! Хотя чему удивляться?! Давно можно было понять, что ты – крепкий орешек.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Лорд Джеффри Талван побежден',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к троллю-прислужнику Водину в Горнило Крови на Сумеречном нагорье.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Действующий чемпион Горнила Крови, непобедимый лорд Джеффри Талван.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Лорд Джеффри Талван',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Ни разу не переодевался за четыре года.',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Водин',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (27868,'Горнило Крови: Сумеречный ужас','У меня тут припасен противник, который сразу разбудит в тебе боевой задор. Как только увидишь, сразу рванешься его убивать. Я сперва сомневался, выпускать ли его на арену, но бой есть бой! И кто я такой, чтобы отказываться от притока наличности?! А уж он будет неслабый, поверь мне на слово.$B$BЭтот парень, он не откуда-нибудь, а из Сумеречной крепости! Говорят, очень коварный боец. Так что почаще смотри под ноги и не зевай. В общем, как будешь $gготов:готова; к поединку, мы сразу начнем.','Выйдите на арену Горнила Крови и одержите победу над Углеколом Пожирателем!','Ну ты и задал ему жару! Похоже, что ты – чемпион.$B$BМои поздравления. Надеюсь, ты знаешь, как распорядиться призовыми деньгами.','Углекол Пожиратель побежден','Вернитесь к троллю-прислужнику Водину в Горнило Крови, что на Сумеречном нагорье.','Шутки в сторону. Если Уклекола не остановить, вся арена сгорит в пламени его гнева.','Углекол Пожиратель','Троллья тоска.','Водин') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Горнило Крови: Сумеречный ужас',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У меня тут припасен противник, который сразу разбудит в тебе боевой задор. Как только увидишь, сразу рванешься его убивать. Я сперва сомневался, выпускать ли его на арену, но бой есть бой! И кто я такой, чтобы отказываться от притока наличности?! А уж он будет неслабый, поверь мне на слово.$B$BЭтот парень, он не откуда-нибудь, а из Сумеречной крепости! Говорят, очень коварный боец. Так что почаще смотри под ноги и не зевай. В общем, как будешь $gготов:готова; к поединку, мы сразу начнем.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выйдите на арену Горнила Крови и одержите победу над Углеколом Пожирателем!',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну ты и задал ему жару! Похоже, что ты – чемпион.$B$BМои поздравления. Надеюсь, ты знаешь, как распорядиться призовыми деньгами.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Углекол Пожиратель побежден',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к троллю-прислужнику Водину в Горнило Крови, что на Сумеречном нагорье.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Шутки в сторону. Если Уклекола не остановить, вся арена сгорит в пламени его гнева.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Углекол Пожиратель',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Троллья тоска.',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Водин',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (27869,'Дракон и храм','Тебя послала гоблинша? А у нее зоркий глаз...$B$BОна права. Я хочу прервать поток тлена, исходящий из храма. Если желаешь спасти свой народ от тяжкой участи, Декарим, мне понадобится твоя помощь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дракон и храм',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебя послала гоблинша? А у нее зоркий глаз...$B$BОна права. Я хочу прервать поток тлена, исходящий из храма. Если желаешь спасти свой народ от тяжкой участи, Декарим, мне понадобится твоя помощь.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27870,'Возвращение на Заставу Болотной Воды','Вне зависимости от того, поможешь ли ты мне в храме, твой народ должен знать, что тут творится.$B$BК северу от храма люди из вашего Альянса смертных построили то, что они называют Заставой Болотной Воды. Они вступили в открытое противостояние с Ордой на болотах, и я предвижу, что конфликт будет только усугубляться.$B$BНе мне вмешиваться в дела смертных, $n. Я просто прошу тебя предупредить твой народ о том, какое зло затаилось в храме.','Поговорите с Джоанной Блухарт на Заставе Болотной Воды.','Неприятности в храме... Жаль, что у нас нет дополнительных сил, чтобы отрядить их туда. Война с Каменором в самом разгаре, и нам нужен каждый человек.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение на Заставу Болотной Воды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вне зависимости от того, поможешь ли ты мне в храме, твой народ должен знать, что тут творится.$B$BК северу от храма люди из вашего Альянса смертных построили то, что они называют Заставой Болотной Воды. Они вступили в открытое противостояние с Ордой на болотах, и я предвижу, что конфликт будет только усугубляться.$B$BНе мне вмешиваться в дела смертных, $n. Я просто прошу тебя предупредить твой народ о том, какое зло затаилось в храме.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Джоанной Блухарт на Заставе Болотной Воды.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Неприятности в храме... Жаль, что у нас нет дополнительных сил, чтобы отрядить их туда. Война с Каменором в самом разгаре, и нам нужен каждый человек.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (27871,'Возвращение в Каменор','Вне зависимости от того, поможешь ли ты мне в храме, твой народ должен знать, что здесь происходит.$B$BК юго-западу от храма – ордынский город Каменор. Живущие там орки ведут войну с недавно прибывшими в топи людьми. Это яростный конфликт, который, я думаю, только усилится.$B$BНе мне вмешиваться в дела смертных, $n. Я просто прошу тебя предупредить твой народ о том, какое зло затаилось в храме.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение в Каменор',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вне зависимости от того, поможешь ли ты мне в храме, твой народ должен знать, что здесь происходит.$B$BК юго-западу от храма – ордынский город Каменор. Живущие там орки ведут войну с недавно прибывшими в топи людьми. Это яростный конфликт, который, я думаю, только усилится.$B$BНе мне вмешиваться в дела смертных, $n. Я просто прошу тебя предупредить твой народ о том, какое зло затаилось в храме.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (27872,'Tortolla Hub Complete') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Tortolla Hub Complete',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (27873,'Контрольная точка Авианы пройдена') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Контрольная точка Авианы пройдена',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (27874,'Наследие Авианы','Еще одно святилище нуждается в твоей помощи, $n!$B$BК юго-западу от Древа Жизни находится святилище Авианы, пристанище друидов-воронов. 10 000 лет назад Авиана, покровительница всех пернатых созданий, пожертвовала собой ради спасения этого мира.$B$BЧувствую, что ее святилище находится в опасности, равно как и охраняющие его друиды. Разыщи Чолуну, одну из мудрейших представительниц друидов-воронов, обитающую в стенах святилища.','Сама Изера послала тебя ко мне? Для меня огромная честь беседовать с представителем Аспектов драконов.$B$BЭто правда, что наше святилище подвергается опасности. Гарпии, которым мы некогда давали приют в святилище, обратились против нас.$B$BЯ прошу тебя не вступать в бой, пока ты к этому не готов. Наше святилище – не поле брани. Здесь ты можешь отдохнуть и собраться с силами.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наследие Авианы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Еще одно святилище нуждается в твоей помощи, $n!$B$BК юго-западу от Древа Жизни находится святилище Авианы, пристанище друидов-воронов. 10 000 лет назад Авиана, покровительница всех пернатых созданий, пожертвовала собой ради спасения этого мира.$B$BЧувствую, что ее святилище находится в опасности, равно как и охраняющие его друиды. Разыщи Чолуну, одну из мудрейших представительниц друидов-воронов, обитающую в стенах святилища.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сама Изера послала тебя ко мне? Для меня огромная честь беседовать с представителем Аспектов драконов.$B$BЭто правда, что наше святилище подвергается опасности. Гарпии, которым мы некогда давали приют в святилище, обратились против нас.$B$BЯ прошу тебя не вступать в бой, пока ты к этому не готов. Наше святилище – не поле брани. Здесь ты можешь отдохнуть и собраться с силами.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27875,'Молитвоцвет','Годами я пытался смягчить страдания Сломленных. Поработившие их силы не просто изменили их облик – они отняли утешение Света. Свет больше не согревает их души.$B$BЯ не могу позволить Магтуру погрязнуть во тьме, $n. До того как его состояние ухудшилось, я изучал молитвоцвет – цветок, растущий в Ползучей трясине. Он умудряется прорастать даже в самой глубокой тени. Умоляю, собери эти цветы – ради Магтура.','Соберите 10 побегов молитвоцвета в Ползучей трясине.','Сломленные используют молитвоцвет как лекарство с тех пор, как обосновались в топях. Если он излечивает тело, вероятно, годится и для более эффективного лечения...','Вернитесь к Анахорету Авууну в Убежище на Болото Печали.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Молитвоцвет',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Годами я пытался смягчить страдания Сломленных. Поработившие их силы не просто изменили их облик – они отняли утешение Света. Свет больше не согревает их души.$B$BЯ не могу позволить Магтуру погрязнуть во тьме, $n. До того как его состояние ухудшилось, я изучал молитвоцвет – цветок, растущий в Ползучей трясине. Он умудряется прорастать даже в самой глубокой тени. Умоляю, собери эти цветы – ради Магтура.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 побегов молитвоцвета в Ползучей трясине.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сломленные используют молитвоцвет как лекарство с тех пор, как обосновались в топях. Если он излечивает тело, вероятно, годится и для более эффективного лечения...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Анахорету Авууну в Убежище на Болото Печали.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27876,'Тайны Ползучей Трясины','Ползучая трясина получила свое название благодаря удивительному явлению. Движимый некой силой, отборный ил накапливается и, словно живой, перемещается сам по себе.$B$BПоначалу я опасался, что это какая-то губительная сила, но в ходе наблюдений выяснилось обратное; какая бы энергия ни двигала им, по природе своей она положительная. Возможно, жизненную силу такого рода можно передать и Сломленным, чтобы пробудить их прежнюю сущность.$B$BИлу вряд ли придутся по душе твои попытки его собрать, $n. И все же прошу тебя – сделай это.','Соберите 10 образцов укрепляющего ила в Ползучей трясине.','Нужно будет его очистить – и все же это самое действенное средство. Благодарю тебя.','Удалось достать образцы?','Вернитесь к Анахорету Авууну в Убежище на Болото Печали.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тайны Ползучей Трясины',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ползучая трясина получила свое название благодаря удивительному явлению. Движимый некой силой, отборный ил накапливается и, словно живой, перемещается сам по себе.$B$BПоначалу я опасался, что это какая-то губительная сила, но в ходе наблюдений выяснилось обратное; какая бы энергия ни двигала им, по природе своей она положительная. Возможно, жизненную силу такого рода можно передать и Сломленным, чтобы пробудить их прежнюю сущность.$B$BИлу вряд ли придутся по душе твои попытки его собрать, $n. И все же прошу тебя – сделай это.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 образцов укрепляющего ила в Ползучей трясине.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Нужно будет его очистить – и все же это самое действенное средство. Благодарю тебя.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось достать образцы?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Анахорету Авууну в Убежище на Болото Печали.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27877,'Цирк непуганых идиотов','Мне нужна твоя помощь в одной затее, $n. Она подпадает под определение "превентивная археология".$B$BЯ развлекаюсь, закапывая обычные предметы на видном месте, чтобы кретины из Альянса думали, будто нашли что ценное.$B$BИтак... Дворфы из клана Черного Железа обитают на карьере Тяжелоступа в крепости Ангор, на севере. Принеси мне их головы. Да, ты не $gослышался:ослышалась; – головы. После того как удалим с них плоть, черепа нам пригодятся, чтобы вмешаться в работу дворфов.','Раздобудьте 15 голов дворфов клана Черного Железа.','Превосходно! Мы зароем их немедленно. Эти недоумки из Лиги исследователей ни за что нас не заподозрят!','<Лидия явно ждет вашего возвращения.>','Вернитесь к Лидии Солнечное Сияние в лагерь Кровавого Взора, что в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Цирк непуганых идиотов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне нужна твоя помощь в одной затее, $n. Она подпадает под определение "превентивная археология".$B$BЯ развлекаюсь, закапывая обычные предметы на видном месте, чтобы кретины из Альянса думали, будто нашли что ценное.$B$BИтак... Дворфы из клана Черного Железа обитают на карьере Тяжелоступа в крепости Ангор, на севере. Принеси мне их головы. Да, ты не $gослышался:ослышалась; – головы. После того как удалим с них плоть, черепа нам пригодятся, чтобы вмешаться в работу дворфов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте 15 голов дворфов клана Черного Железа.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Превосходно! Мы зароем их немедленно. Эти недоумки из Лиги исследователей ни за что нас не заподозрят!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Лидия явно ждет вашего возвращения.>',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лидии Солнечное Сияние в лагерь Кровавого Взора, что в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27878,'Насильственный захват','У меня есть предложение, которое, возможно, тебя заинтересует.$B$BДворфы из клана Черного Железа пришли сюда задолго до нас. А это значит, что, когда показались руины титанов, клан Черного Железа первым добрался до прорвы артефактов. Бьюсь об заклад, они до сих пор держат сокровище в крепости Ангор к северо-западу отсюда.$B$BРазыщи все самое ценное... и стащи.','Поищите сокровище на самом нижнем уровне крепости Ангор.','Вернитесь к Аорену Солнечному Сиянию в лагерь Кровавого Взора, что в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Насильственный захват',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У меня есть предложение, которое, возможно, тебя заинтересует.$B$BДворфы из клана Черного Железа пришли сюда задолго до нас. А это значит, что, когда показались руины титанов, клан Черного Железа первым добрался до прорвы артефактов. Бьюсь об заклад, они до сих пор держат сокровище в крепости Ангор к северо-западу отсюда.$B$BРазыщи все самое ценное... и стащи.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поищите сокровище на самом нижнем уровне крепости Ангор.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аорену Солнечному Сиянию в лагерь Кровавого Взора, что в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27879,'Выживает жирнейший','Припасов у нас – кот наплакал... Черные драконы разоряют наши охотничьи угодья, и нам негде раздобыть пропитание.$B$BЗато у огров на юге есть все, что нам нужно. В их пещере ты найдешь вдоволь запасов мяса и ремесленного сырья.$B$BОгры наверняка так просто все это не отдадут, поэтому будь начеку.','Добудьте 6 порций мяса и 10 отрезов шелка клана Гнилобрюхих.','Вижу, общение с ограми не доставило тебе особых хлопот. Держи – пара монет за труды.','С возвращением.','Вернитесь к Айдану Летнему Ветру в Новый Каргат в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Выживает жирнейший',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Припасов у нас – кот наплакал... Черные драконы разоряют наши охотничьи угодья, и нам негде раздобыть пропитание.$B$BЗато у огров на юге есть все, что нам нужно. В их пещере ты найдешь вдоволь запасов мяса и ремесленного сырья.$B$BОгры наверняка так просто все это не отдадут, поэтому будь начеку.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 6 порций мяса и 10 отрезов шелка клана Гнилобрюхих.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вижу, общение с ограми не доставило тебе особых хлопот. Держи – пара монет за труды.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','С возвращением.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Айдану Летнему Ветру в Новый Каргат в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27880,'Затяжная оборона','Мои воины сами вполне справляются с драконами. К тому же я не могу позволить $gначинающему:начинающей:c; |3-2($c) вроде тебя вмешиваться в наши военные планы и губить их на корню.$B$BХочешь работу? Будет тебе работа. Разведай лагерь огров на юго-западе. До меня дошли слухи, что возле их логова видели небольшой отряд бойцов.$B$BНельзя сидеть сложа руки и ждать, пока они зайдут к нам с фланга... особенно когда у нас и без того забот полон рот. Прореди-ка ряды этих огров, покуда они нас в этом не опередили.','Уничтожьте 12 бойцов клана Гнилобрюхих. Можно убивать как извергов, так и шаманов этого клана.','Вернитесь к Горну в Новый Каргат в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Затяжная оборона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мои воины сами вполне справляются с драконами. К тому же я не могу позволить $gначинающему:начинающей:c; |3-2($c) вроде тебя вмешиваться в наши военные планы и губить их на корню.$B$BХочешь работу? Будет тебе работа. Разведай лагерь огров на юго-западе. До меня дошли слухи, что возле их логова видели небольшой отряд бойцов.$B$BНельзя сидеть сложа руки и ждать, пока они зайдут к нам с фланга... особенно когда у нас и без того забот полон рот. Прореди-ка ряды этих огров, покуда они нас в этом не опередили.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 12 бойцов клана Гнилобрюхих. Можно убивать как извергов, так и шаманов этого клана.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Горну в Новый Каргат в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (27881,'Лагерь Кровавого Взора','Титаны? Ты хочешь спросить у меня о титанах?$B$BЧто ж, это ты удачно зашел. Мы тут на пороге грандиозного открытия. Но тебе сначала придется заслужить наше доверие.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лагерь Кровавого Взора',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Титаны? Ты хочешь спросить у меня о титанах?$B$BЧто ж, это ты удачно зашел. Мы тут на пороге грандиозного открытия. Но тебе сначала придется заслужить наше доверие.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27882,'Вопрос не истории, а силы','Лига исследователей, может, и поднаторела в пролетарском умении откапывать всякую всячину, но вот чего им действительно не хватает – ума и воображения по использованию находок. Они маринуют все найденное на музейных полках, вместо того чтобы применить силу этих могучих артефактов по назначению.$B$BДворфы – глупцы. Хорошо хоть, убивать таких легче легкого.$B$BТы найдешь их на раскопках стен каньона к северу отсюда. Вырви, что сможешь, из их короткопалых ручонок, и принеси мне.','Добудьте разбитую чашу, пыльную вазу, иероглиф земли и орудие троггов.','Вернитесь к главному дознавателю Тей\'телану Кровавому Взору в лагерь Кровавого Взора, что в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вопрос не истории, а силы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Лига исследователей, может, и поднаторела в пролетарском умении откапывать всякую всячину, но вот чего им действительно не хватает – ума и воображения по использованию находок. Они маринуют все найденное на музейных полках, вместо того чтобы применить силу этих могучих артефактов по назначению.$B$BДворфы – глупцы. Хорошо хоть, убивать таких легче легкого.$B$BТы найдешь их на раскопках стен каньона к северу отсюда. Вырви, что сможешь, из их короткопалых ручонок, и принеси мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте разбитую чашу, пыльную вазу, иероглиф земли и орудие троггов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к главному дознавателю Тей\'телану Кровавому Взору в лагерь Кровавого Взора, что в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27883,'Пешка-страж','Одной из немногих ценных находок, обнаруженных в руинах, была эта маленькая нефритовая статуэтка.$B$BМы считаем, это своего рода ключ, но не знаем, что он открывает. Поэтому мне статуэтка без надобности.$B$BЗато, может быть, тебе пригодится.','Выясните, для чего нужна пешка-страж в Гробнице Стражей в Бесплодных землях.','<С легким щелчком статуэтка заняла свое место на большой каменной плите.>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пешка-страж',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Одной из немногих ценных находок, обнаруженных в руинах, была эта маленькая нефритовая статуэтка.$B$BМы считаем, это своего рода ключ, но не знаем, что он открывает. Поэтому мне статуэтка без надобности.$B$BЗато, может быть, тебе пригодится.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выясните, для чего нужна пешка-страж в Гробнице Стражей в Бесплодных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<С легким щелчком статуэтка заняла свое место на большой каменной плите.>',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27884,'Пешка-часовой','Мы нашли эту миниатюрную красную статуэтку у одного из погибших археологов Лиги исследователей. Убили его, к сожалению, не мы. Местная фауна постаралась.$B$BСтатуэтка искусно изготовлена, но, похоже, магии в ней ни на пшик. Делай с ней что заблагорассудится.','Выясните, для чего нужна пешка-часовой в Гробнице Стражей в Бесплодных землях.','<Статуэтка встает на свое место на холодной мраморной плите.>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пешка-часовой',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы нашли эту миниатюрную красную статуэтку у одного из погибших археологов Лиги исследователей. Убили его, к сожалению, не мы. Местная фауна постаралась.$B$BСтатуэтка искусно изготовлена, но, похоже, магии в ней ни на пшик. Делай с ней что заблагорассудится.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выясните, для чего нужна пешка-часовой в Гробнице Стражей в Бесплодных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Статуэтка встает на свое место на холодной мраморной плите.>',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27885,'Игра стражей','Вы видите, как статуэтка сначала раздваивается, затем делится на четыре, а затем на восемь одинаковых статуэток, которые выстраиваются в квадрат.$B$BПрямо в вашем сознании раздается голос:$B$B"Настоящий страж не смотрит ВОВНЕ, отыскивая признаки опасности.$B$BНастоящий страж обращает свой взгляд ВОВНУТРЬ, сосредоточенно оберегая свою добычу".$B$BДолжно быть, это какая-то загадка.','Завершите игру стражей, переместив пешек-стражей так, чтобы они смотрели внутрь квадрата.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Игра стражей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы видите, как статуэтка сначала раздваивается, затем делится на четыре, а затем на восемь одинаковых статуэток, которые выстраиваются в квадрат.$B$BПрямо в вашем сознании раздается голос:$B$B"Настоящий страж не смотрит ВОВНЕ, отыскивая признаки опасности.$B$BНастоящий страж обращает свой взгляд ВОВНУТРЬ, сосредоточенно оберегая свою добычу".$B$BДолжно быть, это какая-то загадка.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Завершите игру стражей, переместив пешек-стражей так, чтобы они смотрели внутрь квадрата.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27886,'Игра часовых','Как только статуэтка оказывается на месте, в комнате появляется еще несколько каменных статуэток. В нише в дальнем конце комнаты вы видите еще одну рубиновую фигурку. Вы слышите голос:$B$B"Страж наблюдает.$BСтраж защищает.$BСтраж никогда не смежает очей".$B$BКрасная статуэтка на другом конце комнаты наверняка для чего-то нужна. Может быть, попробовать соединить две красные статуэтки?','Завершите игру часовых, соединив две красные статуэтки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Игра часовых',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как только статуэтка оказывается на месте, в комнате появляется еще несколько каменных статуэток. В нише в дальнем конце комнаты вы видите еще одну рубиновую фигурку. Вы слышите голос:$B$B"Страж наблюдает.$BСтраж защищает.$BСтраж никогда не смежает очей".$B$BКрасная статуэтка на другом конце комнаты наверняка для чего-то нужна. Может быть, попробовать соединить две красные статуэтки?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Завершите игру часовых, соединив две красные статуэтки.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27887,'Древние защитники','В центральном зале гробницы раздается нешуточный грохот. Все-таки что-то с теми огромными статуями неладно...','Внимательно осмотрите Стража и Часового.','Осмотрите сокровище титанов в Гробнице Стражей в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Древние защитники',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В центральном зале гробницы раздается нешуточный грохот. Все-таки что-то с теми огромными статуями неладно...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Внимательно осмотрите Стража и Часового.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Осмотрите сокровище титанов в Гробнице Стражей в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27888,'Возвращение к Бламу','В сундуке на подушечке лежит небольшой округлый предмет.$B$BЕсли в этой гробнице и есть артефакты титанов, то это точно один из них. Вы решаете отнести его доктору Бламу.','Отнесите Око стражей доктору Иерониму Бламу в Удел Эгмонда в Бесплодных землях.','Что, всего-навсего какой-то крошечный механизм?$B$BНикогда мне не понять этих титанов...$B$BЛадно, поглядим, что умеет это глазик.','Поговорите с доктором Иеронимом Бламом в Уделе Эгмонда в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение к Бламу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В сундуке на подушечке лежит небольшой округлый предмет.$B$BЕсли в этой гробнице и есть артефакты титанов, то это точно один из них. Вы решаете отнести его доктору Бламу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите Око стражей доктору Иерониму Бламу в Удел Эгмонда в Бесплодных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что, всего-навсего какой-то крошечный механизм?$B$BНикогда мне не понять этих титанов...$B$BЛадно, поглядим, что умеет это глазик.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с доктором Иеронимом Бламом в Уделе Эгмонда в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27889,'Новый Каргат','<Доктор Блам в ошеломленном молчании не сводит глаз с яйца, протирает глаза, затем переводит взгляд на вас.>$B$BТы... ты это $gвидел:видела;?! Потрясающе! Моя ставка на титанов была верна! И спасибо тебе за помощь, конечно.$B$BНам следует отнести это Реа. Реа покинула долину Летлор; после того, как она перевоплотилась в свое истинное обличье прямо на глазах у дракончиков, ей больше не удалось бы скрываться. Теперь она живет на западе, в большом ордынском поселении под названием "Новый Каргат".$B$BОна будет ждать тебя с этим яйцом.','Отнесите очищенное от скверны яйцо черного дракона Реа в Новый Каргат в Бесплодных землях.','Сообщите Реа о своем прибытии в Новый Каргат в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новый Каргат',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Доктор Блам в ошеломленном молчании не сводит глаз с яйца, протирает глаза, затем переводит взгляд на вас.>$B$BТы... ты это $gвидел:видела;?! Потрясающе! Моя ставка на титанов была верна! И спасибо тебе за помощь, конечно.$B$BНам следует отнести это Реа. Реа покинула долину Летлор; после того, как она перевоплотилась в свое истинное обличье прямо на глазах у дракончиков, ей больше не удалось бы скрываться. Теперь она живет на западе, в большом ордынском поселении под названием "Новый Каргат".$B$BОна будет ждать тебя с этим яйцом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите очищенное от скверны яйцо черного дракона Реа в Новый Каргат в Бесплодных землях.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Сообщите Реа о своем прибытии в Новый Каргат в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27890,'Плохие парни','Из-за спешки, в которой я покидала долину Летлор, я совсем позабыла о Никсондре. А она на свободе и подняла переполох в стае черных драконов. Добрая половина драконов уже здесь, прочесывает западные Бесплодные земли в поисках яйца.$b$bО яйце я позабочусь. А ты займись самыми опасными драконами. Не волнуйся, ты будешь не $gодин:одна;.$B$BЯ заплатила паре наемников, они тебе помогут. Они здесь, в таверне.','Поговорите с Амаккаром в Новом Каргате в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Плохие парни',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Из-за спешки, в которой я покидала долину Летлор, я совсем позабыла о Никсондре. А она на свободе и подняла переполох в стае черных драконов. Добрая половина драконов уже здесь, прочесывает западные Бесплодные земли в поисках яйца.$b$bО яйце я позабочусь. А ты займись самыми опасными драконами. Не волнуйся, ты будешь не $gодин:одна;.$B$BЯ заплатила паре наемников, они тебе помогут. Они здесь, в таверне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Амаккаром в Новом Каргате в Бесплодных землях.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27891,'Амаккар, мастер на все руки','Прежде чем мы ринемся убивать этих драконов, я посвящу тебя в свою тактику боя.$B$BЯ не такой могучий и рослый, как эти двое, но и у меня есть пара козырей в рукаве. Ты только свистни, и я оглушу твоего противника и прослежу, чтоб он не дергался. Еще у меня всегда при себе зелье-другое на случай форс-мажора.$B$BВот что, давай-ка отработаем совместный бой. Иди в поле, и я тебе покажу, каково это – сражаться с настоящим орком.','Испытайте удар Амаккара по почкам и карманное зелье Амаккара.','Не терпится повоевать плечом к плечу с тобой.','Поговорите с Амаккаром в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Амаккар, мастер на все руки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прежде чем мы ринемся убивать этих драконов, я посвящу тебя в свою тактику боя.$B$BЯ не такой могучий и рослый, как эти двое, но и у меня есть пара козырей в рукаве. Ты только свистни, и я оглушу твоего противника и прослежу, чтоб он не дергался. Еще у меня всегда при себе зелье-другое на случай форс-мажора.$B$BВот что, давай-ка отработаем совместный бой. Иди в поле, и я тебе покажу, каково это – сражаться с настоящим орком.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Испытайте удар Амаккара по почкам и карманное зелье Амаккара.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Не терпится повоевать плечом к плечу с тобой.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Амаккаром в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27892,'Джаррикс-истребитель','Хочешь поболтать чутка? Не вопрос.$B$BЯ Джаррикс, единственный наемник тут, который хоть немного соображает. А также единственный, чьи атаки причиняют хоть какой-то вред. Этим двум тушам я позволяю бегать со мной, только чтобы меня самого не зашибло ненароком.$B$BСлушай, ты в этой операции вроде как за главного. По твоей команде я запущу огненный шар прямиком в твоего врага. А если станет жарковато, я даже время могу замедлить, чтобы ты $gуспел:успела; нанести пару-тройку лишних ударов.$B$BПойдем-ка порепетируем будущий бой.','Испытайте огневую вспышку Джаррикса и искажение времени Джаррикса.','Поговорите с Джарриксом Белой Гривой в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Джаррикс-истребитель',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хочешь поболтать чутка? Не вопрос.$B$BЯ Джаррикс, единственный наемник тут, который хоть немного соображает. А также единственный, чьи атаки причиняют хоть какой-то вред. Этим двум тушам я позволяю бегать со мной, только чтобы меня самого не зашибло ненароком.$B$BСлушай, ты в этой операции вроде как за главного. По твоей команде я запущу огненный шар прямиком в твоего врага. А если станет жарковато, я даже время могу замедлить, чтобы ты $gуспел:успела; нанести пару-тройку лишних ударов.$B$BПойдем-ка порепетируем будущий бой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Испытайте огневую вспышку Джаррикса и искажение времени Джаррикса.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Джарриксом Белой Гривой в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27893,'Гаргал-чудище','Может, это и не заметно, но вообще-то по орочьим меркам я крупный малый.$B$BЯ тут затем, чтобы оба моих приятеля выбрались из любой переделки целыми и невредимыми. Они мелковаты, и таких здоровых щитов, как у меня, у них нет. А я большой и запросто выдержу удары сразу нескольких монстров! К тому же, если не зевать, всегда можно подставить вместо себя свой щит!$B$BТебя я тоже смогу защитить. Пойдем потренируемся. Я буду следить за тем, чтобы враг атаковал меня, а не тебя.','Испытайте осадный щит Гаргала и могучий рев Гаргала.','Видишь? Когда Гаргал рядом, беспокоиться не о чем. Только скажи – и я защищу тебя от монстров.','Поговорите с Гаргалом в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гаргал-чудище',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Может, это и не заметно, но вообще-то по орочьим меркам я крупный малый.$B$BЯ тут затем, чтобы оба моих приятеля выбрались из любой переделки целыми и невредимыми. Они мелковаты, и таких здоровых щитов, как у меня, у них нет. А я большой и запросто выдержу удары сразу нескольких монстров! К тому же, если не зевать, всегда можно подставить вместо себя свой щит!$B$BТебя я тоже смогу защитить. Пойдем потренируемся. Я буду следить за тем, чтобы враг атаковал меня, а не тебя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Испытайте осадный щит Гаргала и могучий рев Гаргала.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Видишь? Когда Гаргал рядом, беспокоиться не о чем. Только скажи – и я защищу тебя от монстров.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Гаргалом в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (27894,'Поход на дракона','Приветствую, $n. Я смотрю, вы четверо уже успели познакомиться.$B$BВот тебе первое задание. Каларан, древний и могучий черный дракон, присоединился к охотникам за яйцом, которое мы оберегаем. Его необходимо остановить, прежде чем он подберется слишком близко.$B$BТы найдешь дракона и его приспешников в Знойных Песках к востоку от Нового Каргата. Выследи его и убей. Помощь твоих новых друзей-наемников придется как нельзя кстати.','Одолейте Каларана Уничтожителя и четверых солдат Летящей Тьмы.','Нужно сразить черного дракона, пока яйцо все еще уязвимо.','Реастраза','Дело еще не закончено.','Реастраза') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поход на дракона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приветствую, $n. Я смотрю, вы четверо уже успели познакомиться.$B$BВот тебе первое задание. Каларан, древний и могучий черный дракон, присоединился к охотникам за яйцом, которое мы оберегаем. Его необходимо остановить, прежде чем он подберется слишком близко.$B$BТы найдешь дракона и его приспешников в Знойных Песках к востоку от Нового Каргата. Выследи его и убей. Помощь твоих новых друзей-наемников придется как нельзя кстати.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Одолейте Каларана Уничтожителя и четверых солдат Летящей Тьмы.',`objectives_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Нужно сразить черного дракона, пока яйцо все еще уязвимо.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Реастраза',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Дело еще не закончено.',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Реастраза',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (27895,'Охота продолжается!','Род черных драконов знает свое дело. Как тебе должно быть известно, они захватили значительную часть Нового Каргата. Этими войсками командуют генерал Жиракка и его правая рука – Молдарр. Их нужно остановить...','Одолейте генерала Жиракку, Молдарра и 6 черных драконоидов.','Молдарр и Жиракка командуют основной группировкой черных драконов.','Реастраза','Главное испытание еще впереди…','Реастраза') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота продолжается!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Род черных драконов знает свое дело. Как тебе должно быть известно, они захватили значительную часть Нового Каргата. Этими войсками командуют генерал Жиракка и его правая рука – Молдарр. Их нужно остановить...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Одолейте генерала Жиракку, Молдарра и 6 черных драконоидов.',`objectives_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Молдарр и Жиракка командуют основной группировкой черных драконов.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Реастраза',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Главное испытание еще впереди…',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Реастраза',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (27896,'Печаль и гнев','Я бесконечно сожалею о том, как мы... нет, как я обращалась с Никсондрой. Я заставляла ее откладывать яйца и ставила над ними опыты. Снова и снова – без конца.$B$BДаже сама будучи матерью, я с трудом могу представить себе ее горе.$B$BНет... Мне нужно быть сильной. В конце концов, мы стараемся на благо будущих поколений черных драконов. Ее жертва не была напрасной.$B$BОна кружит над руинами Каргата, к северо-западу от Нового Каргата, обезумевшая от ярости. Пожалуйста, герой... избавь Никсондру от страданий.','Убейте Никсондру и 12 ее детенышей.','Прости меня, Никсондра…','Реастраза','Почти готово.','Реастраза') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Печаль и гнев',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я бесконечно сожалею о том, как мы... нет, как я обращалась с Никсондрой. Я заставляла ее откладывать яйца и ставила над ними опыты. Снова и снова – без конца.$B$BДаже сама будучи матерью, я с трудом могу представить себе ее горе.$B$BНет... Мне нужно быть сильной. В конце концов, мы стараемся на благо будущих поколений черных драконов. Ее жертва не была напрасной.$B$BОна кружит над руинами Каргата, к северо-западу от Нового Каргата, обезумевшая от ярости. Пожалуйста, герой... избавь Никсондру от страданий.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Никсондру и 12 ее детенышей.',`objectives_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Прости меня, Никсондра…',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Реастраза',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Почти готово.',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Реастраза',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27897,'Потайная кладка','Теперь, когда большинство черных драконов покинуло Бесплодные земли, переносить яйцо стало безопасно. Я буду на небольшом плато, к северу от Нового Каргата.$B$BИщи меня там.','Поговорите с Реей у Потайной кладки в Бесплодных землях.','Яйцо необходимо постоянно переносить с места на место. Опасность угрожает нам повсюду.$B$BДаже в своем безумии Смертокрыл помнит обо всех потаенных местах в этом мире. Яйцу нельзя подолгу оставаться на одном месте.','Встретимся на севере.','Реастраза') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Потайная кладка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда большинство черных драконов покинуло Бесплодные земли, переносить яйцо стало безопасно. Я буду на небольшом плато, к северу от Нового Каргата.$B$BИщи меня там.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Реей у Потайной кладки в Бесплодных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Яйцо необходимо постоянно переносить с места на место. Опасность угрожает нам повсюду.$B$BДаже в своем безумии Смертокрыл помнит обо всех потаенных местах в этом мире. Яйцу нельзя подолгу оставаться на одном месте.',`offerrewardtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Встретимся на севере.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Реастраза',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27898,'Дар Реастразы','Подожди здесь. Я достану яйцо.','Подождите, пока Реа достанет яйцо из Потайной кладки.','Прочтите записи Реа в Потайной кладке в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дар Реастразы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Подожди здесь. Я достану яйцо.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Подождите, пока Реа достанет яйцо из Потайной кладки.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Прочтите записи Реа в Потайной кладке в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27899,'Глаза горят, мозг кипит...','Ты ищешь Харрисона? Он только что ушел.$B$BВсе твердил о каком-то недавнем открытии. Мол, теперь все наконец проясняется.$B$BУж не знаю, чего у него проясняется... Я так вообще ничего не поняла.$B$BЯ ему говорила, мол, побудь с нами хоть пару дней, отдохни, полюбуйся закатами... но куда там! Когда он в таком состоянии, с ним вообще невозможно разговаривать. Глаза горят, мозг кипит...$B$BКак-то мне за него неспокойно. Может, догонишь его и составишь ему компанию?$B$BОн умчался на юг, к тому огромному монолиту.','Поговорите с Харрисоном Джонсом у Обелиска Солнца.','Похоже, я не единственный, кто проявляет интерес к этим обелискам...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Глаза горят, мозг кипит...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты ищешь Харрисона? Он только что ушел.$B$BВсе твердил о каком-то недавнем открытии. Мол, теперь все наконец проясняется.$B$BУж не знаю, чего у него проясняется... Я так вообще ничего не поняла.$B$BЯ ему говорила, мол, побудь с нами хоть пару дней, отдохни, полюбуйся закатами... но куда там! Когда он в таком состоянии, с ним вообще невозможно разговаривать. Глаза горят, мозг кипит...$B$BКак-то мне за него неспокойно. Может, догонишь его и составишь ему компанию?$B$BОн умчался на юг, к тому огромному монолиту.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Харрисоном Джонсом у Обелиска Солнца.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Похоже, я не единственный, кто проявляет интерес к этим обелискам...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27900,'С одним я справлюсь','Как удачно, что ты $gпришел:пришла;, $n.$B$BПохоже, я не единственный, кто проявляет интерес к обелискам, и эти ребята явно не склонны к плодотворной научной дискуссии...$B$BДумаю, с этим парнем я справлюсь.$B$BА ты, может быть, разберешься с его друзьями, пока они сюда не добрались?','Убейте 10 воздушных пехотинцев Шнотца.','Уф, что бы я без тебя делал?! Спасибо, Михалкен.$B$BКак оказалось, у нас тут небольшие неприятности.','Поговорите с Харрисоном Джонсом у Обелиска Солнца.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','С одним я справлюсь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как удачно, что ты $gпришел:пришла;, $n.$B$BПохоже, я не единственный, кто проявляет интерес к обелискам, и эти ребята явно не склонны к плодотворной научной дискуссии...$B$BДумаю, с этим парнем я справлюсь.$B$BА ты, может быть, разберешься с его друзьями, пока они сюда не добрались?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 воздушных пехотинцев Шнотца.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Уф, что бы я без тебя делал?! Спасибо, Михалкен.$B$BКак оказалось, у нас тут небольшие неприятности.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Харрисоном Джонсом у Обелиска Солнца.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27901,'Они даже не знают, что это такое','Слушай, $n. На разговоры нет времени, так что я буду краток.$B$BЭти ребята, как я понимаю, хватают все без разбора и похоже, уже растащили на части нужный нам аппарат.$B$BОбыщи их ящики и собери все детали древнего активирующего устройства. У офицеров должен быть шифр, открывающий крышки.$B$BПоторопись!$B$BПока они не загрузили награбленное в самолеты!','Соберите активирующее устройство титанов.','Да!$B$BОтлично сработано, Михалкен!','Ну что, Михалкен? Собрала активирующее устройство титанов?','Поговорите с Харрисоном Джонсом у Обелиска Солнца.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Они даже не знают, что это такое',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слушай, $n. На разговоры нет времени, так что я буду краток.$B$BЭти ребята, как я понимаю, хватают все без разбора и похоже, уже растащили на части нужный нам аппарат.$B$BОбыщи их ящики и собери все детали древнего активирующего устройства. У офицеров должен быть шифр, открывающий крышки.$B$BПоторопись!$B$BПока они не загрузили награбленное в самолеты!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите активирующее устройство титанов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да!$B$BОтлично сработано, Михалкен!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, Михалкен? Собрала активирующее устройство титанов?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Харрисоном Джонсом у Обелиска Солнца.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27902,'Чистый источник','Магтур рассказывал мне о шаманстве Сломленных. Великий Нобундо однажды произнес, что путем стихии, в принципе, можно вернуться к Свету.$B$BОстается надеяться, что в его словах была доля истины. Духи, которые обитают возле пещеры Чистого Источника к югу отсюда, состоят из кристально чистой воды. Возможно, они неорганизованы и агрессивны, но чистейшая вода, заключенная в них, будет лучшим проводником для благословенного Света.$B$BПрошу тебя, принеси мне эту воду, $n.','Соберите 6 частиц духов Чистого источника.','О, какая безупречная чистота... будем надеяться, это поможет несчастному Магтуру.','Раздобыл ли ты частицы духов?','Вернитесь к Анахорету Авууну в Убежище на Болото Печали.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чистый источник',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Магтур рассказывал мне о шаманстве Сломленных. Великий Нобундо однажды произнес, что путем стихии, в принципе, можно вернуться к Свету.$B$BОстается надеяться, что в его словах была доля истины. Духи, которые обитают возле пещеры Чистого Источника к югу отсюда, состоят из кристально чистой воды. Возможно, они неорганизованы и агрессивны, но чистейшая вода, заключенная в них, будет лучшим проводником для благословенного Света.$B$BПрошу тебя, принеси мне эту воду, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 6 частиц духов Чистого источника.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, какая безупречная чистота... будем надеяться, это поможет несчастному Магтуру.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Раздобыл ли ты частицы духов?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Анахорету Авууну в Убежище на Болото Печали.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27903,'Зажигание','Крепкий попался товарищ!$B$BВ который раз ты меня выручаешь, $gмалыш:малышка;. Мы почти у цели. Осталось всего ничего.$B$BСогласно моим изысканиям, там внизу должна быть статуя титана. Активируй ее с помощью этого устройства, а потом разбей.$B$BЕсли моя теория верна, в статуе должен быть ключ к активации обелиска.','Раздобудьте линзу солнца.','Согласно догадкам Харрисона, для активации обелиска нужно положить линзу на это возвышение.$B$BДальше все произойдет само собой...','Надеюсь, этот механизм не испортился за давностью лет...','Положите линзу солнца на возвышение в Зале Солнца.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зажигание',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Крепкий попался товарищ!$B$BВ который раз ты меня выручаешь, $gмалыш:малышка;. Мы почти у цели. Осталось всего ничего.$B$BСогласно моим изысканиям, там внизу должна быть статуя титана. Активируй ее с помощью этого устройства, а потом разбей.$B$BЕсли моя теория верна, в статуе должен быть ключ к активации обелиска.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте линзу солнца.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Согласно догадкам Харрисона, для активации обелиска нужно положить линзу на это возвышение.$B$BДальше все произойдет само собой...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Надеюсь, этот механизм не испортился за давностью лет...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Положите линзу солнца на возвышение в Зале Солнца.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27904,'Дуновение тумана','Добудьте 5 туманных кристаллов туманных греллей.','Вернитесь к Анахорету Авууну в Убежище на Болото Печали.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дуновение тумана',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 5 туманных кристаллов туманных греллей.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Анахорету Авууну в Убежище на Болото Печали.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27905,'Стрелок хвостовой пушки','Ну вот, я его обработал. А теперь остается его добить. Надеюсь, ты мне поможешь.$B$BУ меня есть план, как нам отсюда сбежать. Он требует немалого мужества... и чуть-чуть везения.$B$BНу что, $n? $GГотов:Готова;?$B$BТогда следуй за мной...','Отлично сработано, Михалкен.$B$BКажется, оторвались.','Отстреливайтесь от бомбистов Шнотца, пока Харрисон не приземлится.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Стрелок хвостовой пушки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну вот, я его обработал. А теперь остается его добить. Надеюсь, ты мне поможешь.$B$BУ меня есть план, как нам отсюда сбежать. Он требует немалого мужества... и чуть-чуть везения.$B$BНу что, $n? $GГотов:Готова;?$B$BТогда следуй за мной...',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично сработано, Михалкен.$B$BКажется, оторвались.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отстреливайтесь от бомбистов Шнотца, пока Харрисон не приземлится.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (27906,'Ника Алый Шрам','Поговорите с Никой Алый Шрам у Развилки Расщепленного Копья.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ника Алый Шрам',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Никой Алый Шрам у Развилки Расщепленного Копья.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27907,'Молитвоцвет','Я раздавлена, |3-6($c). Я вложила всю свою силу в Хелгрума, но она вытекает с кровью из его открытых ран. Они слишком глубоки, чтобы затянуться, его плоть отказывается заживать.$B$BОн бредит, охваченный лихорадкой и болью. Я не могу оставить его ни на минуту. Мне неловко просить тебя об этом, но не $gмог:могла; бы ты собрать травы?$B$BМолитвоцвет, растущий в этих топях, – издревле известное средство, облегчающее боль. Будь у меня это снадобье, я облегчила бы страдания Хелгрума.','Принесите 10 побегов молитвоцвета из Ползучей трясины.','Я разотру травы и постараюсь дать ему. Благодарю тебя.','Вернитесь к Нике Алый Шрам на Развилку Расщепленного Копья на Болоте Печали.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Молитвоцвет',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я раздавлена, |3-6($c). Я вложила всю свою силу в Хелгрума, но она вытекает с кровью из его открытых ран. Они слишком глубоки, чтобы затянуться, его плоть отказывается заживать.$B$BОн бредит, охваченный лихорадкой и болью. Я не могу оставить его ни на минуту. Мне неловко просить тебя об этом, но не $gмог:могла; бы ты собрать травы?$B$BМолитвоцвет, растущий в этих топях, – издревле известное средство, облегчающее боль. Будь у меня это снадобье, я облегчила бы страдания Хелгрума.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 побегов молитвоцвета из Ползучей трясины.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я разотру травы и постараюсь дать ему. Благодарю тебя.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Нике Алый Шрам на Развилку Расщепленного Копья на Болоте Печали.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27908,'Тайны Ползучей трясины','Раны Хелгрума гноятся на влажном болотном воздухе. Они вздуваются и сочатся, делая невыносимыми последние минуты его жизни. Мне нужно их чем-нибудь обработать.$B$BВ этой трясине обитают духи. Они населяют даже тину, собирая ее в горсти целебного ила, которые будто оживают.$B$BДухи прохладной, чистой трясины облегчат страдания Хелгрума. Сделай милость, собери их, ибо я не могу покинуть больного.','Соберите 10 образцов укрепляющего ила в Ползучей трясине.','Вернитесь к Нике Алый Шрам на Развилку Расщепленного Копья на Болоте Печали.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тайны Ползучей трясины',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Раны Хелгрума гноятся на влажном болотном воздухе. Они вздуваются и сочатся, делая невыносимыми последние минуты его жизни. Мне нужно их чем-нибудь обработать.$B$BВ этой трясине обитают духи. Они населяют даже тину, собирая ее в горсти целебного ила, которые будто оживают.$B$BДухи прохладной, чистой трясины облегчат страдания Хелгрума. Сделай милость, собери их, ибо я не могу покинуть больного.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 образцов укрепляющего ила в Ползучей трясине.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Нике Алый Шрам на Развилку Расщепленного Копья на Болоте Печали.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27909,'Чистый источник','Хелгрум уже еле дышит. Его время почти вышло.$B$BНужна вода. В прудах в пещере Чистого Источника обитают водные духи. Они состоят из наичистейшей воды, во всех этих болотах не найти такой.$B$BДаже если я рискнула бы оставить Хелгрума, у меня сейчас не хватит сил держать топор. Снова молю тебя, смилуйся надо мной ради утешения Хелгрума. Принеси мне частицы духов, чтобы он напоследок испил свежей чистой водицы.','Раздобудьте 8 частиц духов Чистого источника.','Он едва отпил. Остальным можно омыть тело, когда...$B$B<Взгляд Ники исполнен печали. Она отворачивается, и плечи ее предательски вздрагивают.>','О, ты вернулся.','Вернитесь к Нике Алый Шрам на Развилку Расщепленного Копья на Болоте Печали.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чистый источник',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хелгрум уже еле дышит. Его время почти вышло.$B$BНужна вода. В прудах в пещере Чистого Источника обитают водные духи. Они состоят из наичистейшей воды, во всех этих болотах не найти такой.$B$BДаже если я рискнула бы оставить Хелгрума, у меня сейчас не хватит сил держать топор. Снова молю тебя, смилуйся надо мной ради утешения Хелгрума. Принеси мне частицы духов, чтобы он напоследок испил свежей чистой водицы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте 8 частиц духов Чистого источника.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Он едва отпил. Остальным можно омыть тело, когда...$B$B<Взгляд Ники исполнен печали. Она отворачивается, и плечи ее предательски вздрагивают.>',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','О, ты вернулся.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Нике Алый Шрам на Развилку Расщепленного Копья на Болоте Печали.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27910,'Сожаления об ушедшем','Коли уж я снизошла до униженной мольбы, то терять мне уже нечего. Обращаюсь к тебе с последней просьбой, последним одолжением для меня, недостойного орка.$B$BХелгрум лелеял мечту об одной добыче. Сумеречный Клык, великая пантера из Туманной долины, пожиратель огров... Хелгрум весь извелся, но не давал себе воли поохотиться на него: наша разведмиссия была слишком важна.$B$BРаз уж Хелгруму не суждено добыть Сумеречного Клыка при жизни, пусть он встретится со своей мечтой в лучшем мире. Отправляйся на охоту вместо Хелгрума; принеси мне шкуру Сумеречного Клыка.','Добудьте шкуру Сумеречного Клыка.','Раз Сумеречный Клык расстался со своим телом, Хелгрум сможет увести его дух за собой в загробную жизнь.$B$BВы только послушайте меня, суеверную старуху. Прости, Хелгрум...','Удалось найти Сумеречного Клыка?','Вернитесь к Нике Алый Шрам на Развилку Расщепленного Копья на Болоте Печали.','Сумеречный Клык из Туманной долины, пожиратель огров','Сумеречный Клык') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сожаления об ушедшем',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Коли уж я снизошла до униженной мольбы, то терять мне уже нечего. Обращаюсь к тебе с последней просьбой, последним одолжением для меня, недостойного орка.$B$BХелгрум лелеял мечту об одной добыче. Сумеречный Клык, великая пантера из Туманной долины, пожиратель огров... Хелгрум весь извелся, но не давал себе воли поохотиться на него: наша разведмиссия была слишком важна.$B$BРаз уж Хелгруму не суждено добыть Сумеречного Клыка при жизни, пусть он встретится со своей мечтой в лучшем мире. Отправляйся на охоту вместо Хелгрума; принеси мне шкуру Сумеречного Клыка.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте шкуру Сумеречного Клыка.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Раз Сумеречный Клык расстался со своим телом, Хелгрум сможет увести его дух за собой в загробную жизнь.$B$BВы только послушайте меня, суеверную старуху. Прости, Хелгрум...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось найти Сумеречного Клыка?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Нике Алый Шрам на Развилку Расщепленного Копья на Болоте Печали.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Сумеречный Клык из Туманной долины, пожиратель огров',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Сумеречный Клык',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27911,'На последнем издыхании','Он покидает нас...$B$BНе уходи, $n. Пожалуйста, воздай Хелгруму последние почести вместе со мной. Ты столько $gсделал:сделала; для него.','Останьтесь рядом с Хелгрумом в его последние минуты.','Его не стало.$B$BОн прав. Ради него я должна быть сильной.','Поговорите с Никой Алый Шрам.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На последнем издыхании',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Он покидает нас...$B$BНе уходи, $n. Пожалуйста, воздай Хелгруму последние почести вместе со мной. Ты столько $gсделал:сделала; для него.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Останьтесь рядом с Хелгрумом в его последние минуты.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Его не стало.$B$BОн прав. Ради него я должна быть сильной.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Никой Алый Шрам.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27912,'Сокровище титанов','Второй защитник падает замертво, и у задней стены зала появляется сундук. Быть может, это как раз то, что они охраняли?','Осмотрите сокровище стражей.','Вы смотрите в сундук...','Осмотрите сокровище в Гробнице Стражей в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сокровище титанов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Второй защитник падает замертво, и у задней стены зала появляется сундук. Быть может, это как раз то, что они охраняли?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Осмотрите сокровище стражей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы смотрите в сундук...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Осмотрите сокровище в Гробнице Стражей в Бесплодных землях.',`completedtext_loc8`);
