INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27914,'Благословение рода зеленых драконов','Отлично, $n. Пусть Джаммал\'ану удалось ускользнуть от нас, но теперь его нет, и я могу войти в храм когда пожелаю.$B$BСтой как стоишь, не шевелись. Я сокращу твой путь обратно, призвав к себе твой дух через Изумрудный Сон.$B$BНе пугайся, если почувствуешь легкую сонливость.','Возвратись ко мне за наградой.','Лорд Итар') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Благословение рода зеленых драконов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Отлично, $n. Пусть Джаммал\'ану удалось ускользнуть от нас, но теперь его нет, и я могу войти в храм когда пожелаю.$B$BСтой как стоишь, не шевелись. Я сокращу твой путь обратно, призвав к себе твой дух через Изумрудный Сон.$B$BНе пугайся, если почувствуешь легкую сонливость.',`details_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Возвратись ко мне за наградой.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Лорд Итар',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (27915,'Сердце храма','Должен признаться, что у меня есть личная заинтересованность в происходящем здесь. Одним их первых порабощенных здесь зеленых драконов был мой брат Эраникус.$B$BЯ думал, его больше нет, был уверен – он окончательно пропал в мрачном лабиринте кошмара, однако до меня дошли слухи, что в храме появился его призрак. Не знаю, действительно это он или лишь отдаленное тоскливое эхо.$B$BЕсли ты все еще желаешь мне помочь, возвращайся в Зал Масок и следуй через сводчатый коридор в самое сердце храма. Мы встретимся там.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сердце храма',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Должен признаться, что у меня есть личная заинтересованность в происходящем здесь. Одним их первых порабощенных здесь зеленых драконов был мой брат Эраникус.$B$BЯ думал, его больше нет, был уверен – он окончательно пропал в мрачном лабиринте кошмара, однако до меня дошли слухи, что в храме появился его призрак. Не знаю, действительно это он или лишь отдаленное тоскливое эхо.$B$BЕсли ты все еще желаешь мне помочь, возвращайся в Зал Масок и следуй через сводчатый коридор в самое сердце храма. Мы встретимся там.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27916,'Отчет Руага','Это донесение Руага, $n. Дай ему знать, что его разведчик все еще здесь.$b$bНи слова о Хелгруме. Я не буду никого расстраивать известиями о трагедии.$b$bМне нужно быть сильной. Всем нам нужно быть сильными.','Доставьте рапорт Расщепленного Копья командиру разведотряда Руагу в Каменор.','Поговорите с командиром разведотряда Руагом в Каменоре, что в Болоте Печали.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отчет Руага',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это донесение Руага, $n. Дай ему знать, что его разведчик все еще здесь.$b$bНи слова о Хелгруме. Я не буду никого расстраивать известиями о трагедии.$b$bМне нужно быть сильной. Всем нам нужно быть сильными.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте рапорт Расщепленного Копья командиру разведотряда Руагу в Каменор.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с командиром разведотряда Руагом в Каменоре, что в Болоте Печали.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27917,'Я чую их за милю','Я чую Годфри и его приспешников. Они где-то рядом – примерно в миле отсюда. Пытались запутать следы, но как-то уж очень убого. Мы этим воспользуемся и – в прямом смысле слова – загоним их в гроб.$B$BОдин из них совсем близко. Хотя у нежити запах слегка изменяется, я уверен, что это Эшбери. Иди и разорви его в клочья. Пусть Отрекшиеся знают, что с нами лучше не связываться.','Убейте барона Эшбери.','Мне в ноздри бьет восхитительный запах свежепролитой крови предателя. Это так бодрит! Однако я еще не утолил жажду крови. Это может сделать только смерть Годфри!$B$BОн считает, что полчище безмозглых трупов одолеет ярость Кровавого Клыка? Мы еще добела обглодаем их кости!','Давай уже убивай Эшбери, пока я не разозлился. А меня лучше не злить. В гневе я неприятен...','Вернитесь к вожаку стаи Ивару Кровавому Клыку.','Он рядом.','Барон Эшбери') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Я чую их за милю',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я чую Годфри и его приспешников. Они где-то рядом – примерно в миле отсюда. Пытались запутать следы, но как-то уж очень убого. Мы этим воспользуемся и – в прямом смысле слова – загоним их в гроб.$B$BОдин из них совсем близко. Хотя у нежити запах слегка изменяется, я уверен, что это Эшбери. Иди и разорви его в клочья. Пусть Отрекшиеся знают, что с нами лучше не связываться.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте барона Эшбери.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мне в ноздри бьет восхитительный запах свежепролитой крови предателя. Это так бодрит! Однако я еще не утолил жажду крови. Это может сделать только смерть Годфри!$B$BОн считает, что полчище безмозглых трупов одолеет ярость Кровавого Клыка? Мы еще добела обглодаем их кости!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Давай уже убивай Эшбери, пока я не разозлился. А меня лучше не злить. В гневе я неприятен...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к вожаку стаи Ивару Кровавому Клыку.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Он рядом.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Барон Эшбери',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (27918,'Убежище') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Убежище',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27920,'Вооруженные до зубов','Убейте барона Сильверлейна и командира Спрингвейла.','Нет никакой радости в уничтожении этих призрачных солдат, которые лишь выполняют чужую волю. Но у нас просто нет выбора. Годфри и вправду хитер и коварен.','Вернитесь к вожаку стаи Ивару Кровавому Клыку.','Этого мы никак не ожидали.','Командир Спрингвейл') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вооруженные до зубов',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте барона Сильверлейна и командира Спрингвейла.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Нет никакой радости в уничтожении этих призрачных солдат, которые лишь выполняют чужую волю. Но у нас просто нет выбора. Годфри и вправду хитер и коварен.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к вожаку стаи Ивару Кровавому Клыку.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Этого мы никак не ожидали.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Командир Спрингвейл',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27921,'Не на жизнь, а на смерть','Похоже, лорд Вальден наконец соизволил заметить, что мы атакуем, и укрепил оборону. Хотя это ему не поможет... нас ничто не остановит!$B$BДорогу к нему преграждают полчища сильных воинов Плети, но я уверен, что ты сумеешь расчистить нам путь. Мы разделаемся с Вальденом, а потом придет очередь его трусливого господина.','Убейте лорда Вальдена.','<Вожак стаи Ивар Кровавый Клык усмехается, обнажая острые зубы.>$B$BБлагодаря твоей доблести уже совсем скоро вся крепость будет нашей.','Вперед, $n. Мы – за тобой!','Вернитесь к вожаку стаи Ивару Кровавому Клыку.','Враг хитер и коварен.','Лорд Вальден') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Не на жизнь, а на смерть',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Похоже, лорд Вальден наконец соизволил заметить, что мы атакуем, и укрепил оборону. Хотя это ему не поможет... нас ничто не остановит!$B$BДорогу к нему преграждают полчища сильных воинов Плети, но я уверен, что ты сумеешь расчистить нам путь. Мы разделаемся с Вальденом, а потом придет очередь его трусливого господина.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте лорда Вальдена.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Вожак стаи Ивар Кровавый Клык усмехается, обнажая острые зубы.>$B$BБлагодаря твоей доблести уже совсем скоро вся крепость будет нашей.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вперед, $n. Мы – за тобой!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к вожаку стаи Ивару Кровавому Клыку.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Враг хитер и коварен.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Лорд Вальден',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27922,'Предатели!','Прошу тебя, $gнезнакомец – ты должен:незнакомка – ты должна; мне помочь.$B$BЯ прибыл сюда, чтобы выяснить, что за могучий союзник пришел на помощь Неферсету – но мои же товарищи предали меня и сдали врагу.$B$BПроберись на расположенную над нами террасу, что к востоку отсюда, и раздобудь сведения, которые я собрать, увы, так и не смог. Но имей в виду, что тебе нужно будет скрываться от неферсетов. Возможно, у тебя получится укрыться за одним из этих больших растений на платформе.$B$BСделай это, пожалуйста, а я помогу твоим друзьям найти дорогу к безопасному месту.','Спрячьтесь за неферсетским папоротником и выведайте секрет Неферсета.','Джинн! Мы должны бежать отсюда как можно скорее.$B$BАльянс Неферсета с прислужниками Смертокрыла не сулит нам ничего хорошего.','Вернитесь к принцу Надуну в Затерянный город Тол\'вир в Ульдуме.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Предатели!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прошу тебя, $gнезнакомец – ты должен:незнакомка – ты должна; мне помочь.$B$BЯ прибыл сюда, чтобы выяснить, что за могучий союзник пришел на помощь Неферсету – но мои же товарищи предали меня и сдали врагу.$B$BПроберись на расположенную над нами террасу, что к востоку отсюда, и раздобудь сведения, которые я собрать, увы, так и не смог. Но имей в виду, что тебе нужно будет скрываться от неферсетов. Возможно, у тебя получится укрыться за одним из этих больших растений на платформе.$B$BСделай это, пожалуйста, а я помогу твоим друзьям найти дорогу к безопасному месту.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Спрячьтесь за неферсетским папоротником и выведайте секрет Неферсета.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Джинн! Мы должны бежать отсюда как можно скорее.$B$BАльянс Неферсета с прислужниками Смертокрыла не сулит нам ничего хорошего.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к принцу Надуну в Затерянный город Тол\'вир в Ульдуме.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27923,'Дым, застилающий глаза','Не знаю, что за план придумал твой странный приятель, но если мы хотим унести отсюда ноги, нам нужно как-то отвлечь наших врагов.$B$BВот, возьми из той жаровни факел и подожги что-нибудь.$B$BВозможно, если мы отвлечем внимание неферсетов хотя бы на несколько минут, у нас будет шанс.','Подожгите стога сена в Затерянном городе Тол\'вире в Ульдуме.','Да. Я слышу крики неферсетов с востока. Возможно, наш план сработает.','Вернитесь к принцу Надуну в Затерянный город Тол\'вир в Ульдуме.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дым, застилающий глаза',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не знаю, что за план придумал твой странный приятель, но если мы хотим унести отсюда ноги, нам нужно как-то отвлечь наших врагов.$B$BВот, возьми из той жаровни факел и подожги что-нибудь.$B$BВозможно, если мы отвлечем внимание неферсетов хотя бы на несколько минут, у нас будет шанс.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Подожгите стога сена в Затерянном городе Тол\'вире в Ульдуме.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да. Я слышу крики неферсетов с востока. Возможно, наш план сработает.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к принцу Надуну в Затерянный город Тол\'вир в Ульдуме.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27924,'План Бадда','У меня есть идея! И можешь не сомневаться, что на этот раз хорошая!$B$BДостань мне блестящие доспехи, которые носят эти люди-кошки.$B$BВ этот раз все будет в ажуре. Просто доверься мне.','Добудьте 6 частей брони Неферсета.','Отлично! Вот увидишь, в этот раз все пройдет как надо!','Вернитесь к Бадду в Затерянный город Тол\'вир в Ульдуме.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','План Бадда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У меня есть идея! И можешь не сомневаться, что на этот раз хорошая!$B$BДостань мне блестящие доспехи, которые носят эти люди-кошки.$B$BВ этот раз все будет в ажуре. Просто доверься мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 6 частей брони Неферсета.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! Вот увидишь, в этот раз все пройдет как надо!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бадду в Затерянный город Тол\'вир в Ульдуме.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27926,'Восточное гостеприимство','Боюсь, у командующего сейчас и без того дел по горло.$B$BОперация, подобная этой, на текущий момент требует практически ста процентов его внимания.$B$BПока ты ожидаешь аудиенции, не желаешь ли пообщаться с нашими гостями?$B$BУ нас тут сливки всего азеротского общества ожидают, когда мы раскроем перед ними тайны этой местности.$B$BУверен, ваша беседа будет весьма захватывающей.','Беллок Сияющий Клинок предлагает вам пообщаться с гостями лагеря Шнотца.','Полагаю, тебе было несложно влиться в общество наших гостей, верно?','Поговорите с Беллоком Сияющим Клинком в лагере Шнотца.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Восточное гостеприимство',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Боюсь, у командующего сейчас и без того дел по горло.$B$BОперация, подобная этой, на текущий момент требует практически ста процентов его внимания.$B$BПока ты ожидаешь аудиенции, не желаешь ли пообщаться с нашими гостями?$B$BУ нас тут сливки всего азеротского общества ожидают, когда мы раскроем перед ними тайны этой местности.$B$BУверен, ваша беседа будет весьма захватывающей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Беллок Сияющий Клинок предлагает вам пообщаться с гостями лагеря Шнотца.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Полагаю, тебе было несложно влиться в общество наших гостей, верно?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Беллоком Сияющим Клинком в лагере Шнотца.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27927,'Погружение в бездну','В Бесплодных землях обитает довольно необычный народец, многие – довольно давно.$B$BВот, например, останавливались тут в городе три джентльмена. Не могу припомнить их имена... дворфа, кажется, звали Тельдарин. Так или иначе, пару дней назад они отправились отсюда на юг с полным рюкзаком эля, и с тех пор от них никаких вестей. Думаю, они пошли к тому большому разлому.$B$BНе $gмог:могла; бы ты сходить за ними? Хотелось бы убедиться, что с ними все в порядке.','Отыщите Тельдарина Заблудшего в Разломе разрушителя миров в Бесплодных землях.','Тебя послали убедиться, что с нами все в порядке? Пф-ф... Да я эту пустыню знал как облупленную, когда эти дурни еще пешком под стол ходили. Мы просто сюда пришли потравить байки о старых добрых временах, очень уж место для этого подходящее.$B$BЛюбишь рассказывать всякие истории?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Погружение в бездну',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В Бесплодных землях обитает довольно необычный народец, многие – довольно давно.$B$BВот, например, останавливались тут в городе три джентльмена. Не могу припомнить их имена... дворфа, кажется, звали Тельдарин. Так или иначе, пару дней назад они отправились отсюда на юг с полным рюкзаком эля, и с тех пор от них никаких вестей. Думаю, они пошли к тому большому разлому.$B$BНе $gмог:могла; бы ты сходить за ними? Хотелось бы убедиться, что с ними все в порядке.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщите Тельдарина Заблудшего в Разломе разрушителя миров в Бесплодных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебя послали убедиться, что с нами все в порядке? Пф-ф... Да я эту пустыню знал как облупленную, когда эти дурни еще пешком под стол ходили. Мы просто сюда пришли потравить байки о старых добрых временах, очень уж место для этого подходящее.$B$BЛюбишь рассказывать всякие истории?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27928,'С мехом по жизни','Раздобудьте 5 шкур пустынного койота.','О, исключительные меха!$B$BКомандующий сможет сделать из них зимний мундир.','Ну как, задалась охота?','Поговорите с Беллоком Сияющим Клинком в лагере Шнотца.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','С мехом по жизни',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте 5 шкур пустынного койота.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, исключительные меха!$B$BКомандующий сможет сделать из них зимний мундир.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как, задалась охота?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Беллоком Сияющим Клинком в лагере Шнотца.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27929,'Сначала сбить, потом прибить','А ты молодец. Эти дворфы, конечно, не самые сильные противники...$B$BНо все равно. Зрелище было достойное.','Вернитесь к Наркраллу Укротителю Драконов в Кровавое ущелье на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сначала сбить, потом прибить',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А ты молодец. Эти дворфы, конечно, не самые сильные противники...$B$BНо все равно. Зрелище было достойное.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Наркраллу Укротителю Драконов в Кровавое ущелье на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27930,'Сокрушение','На горизонте чисто. Если Реастразе с яйцом чудом удалось избежать пламени Смертокрыла, возможно, она отчаянно нуждается в твоей помощи.','Найдите Реастразу.','Герои!$B$BЕсли вы это читаете, значит, мои опасения оправдались. Смертокрыл нашел нас. Яйцо уничтожено, я погибла вместе с ним.$B$BТаков и был изначальный план. Дело в том, что Смертокрыл уничтожил не то яйцо, которое искал.$B$BЭто было моим.','Обыщите Потайную кладку в Бесплодных землях и выясните, была ли здесь Реастраза.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сокрушение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На горизонте чисто. Если Реастразе с яйцом чудом удалось избежать пламени Смертокрыла, возможно, она отчаянно нуждается в твоей помощи.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Реастразу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Герои!$B$BЕсли вы это читаете, значит, мои опасения оправдались. Смертокрыл нашел нас. Яйцо уничтожено, я погибла вместе с ним.$B$BТаков и был изначальный план. Дело в том, что Смертокрыл уничтожил не то яйцо, которое искал.$B$BЭто было моим.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Обыщите Потайную кладку в Бесплодных землях и выясните, была ли здесь Реастраза.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (27931,'Грот Обвалов','Поговорите со Сланцем Плывуном в Гроте Обвалов в Подземье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Грот Обвалов',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите со Сланцем Плывуном в Гроте Обвалов в Подземье.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27932,'Топор раскола земли','Изумрудные колоссы – самые большие детища Матери-Скалы. Их не должно быть на поле. Как раз для этого я принес топор Отца-Скалы Железной Мантии. Воспользуйся им, чтобы раздробить великанов.$b$bКогда они станут меньше, тебе будет легче их прикончить.','Убейте 5 потрескавшихся изумрудных колоссов.','Вернитесь к Сланцу Плывуну в Грот Обвалов, что в Подземье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Топор раскола земли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Изумрудные колоссы – самые большие детища Матери-Скалы. Их не должно быть на поле. Как раз для этого я принес топор Отца-Скалы Железной Мантии. Воспользуйся им, чтобы раздробить великанов.$b$bКогда они станут меньше, тебе будет легче их прикончить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 5 потрескавшихся изумрудных колоссов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сланцу Плывуну в Грот Обвалов, что в Подземье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27933,'Элементиевая руда','Тебе предстоит сразиться с лидером сил Теразан. Чтобы перенести тебя к нему быстро и безопасно, мне нужно совершить ритуал.$b$bОтправляйся на поле и добудь у яростней элементиевую руду. Когда ее будет достаточно, я смогу сделать так, что ты станешь единым целым с землей и перенесешься туда, куда тебе нужно.','Соберите 6 кусков элементиевой руды.','Отлично. Теперь мне нужна пара минут, чтобы подготовить ритуал.','Вернитесь к Сланцу Плывуну в Грот Обвалов, что в Подземье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Элементиевая руда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе предстоит сразиться с лидером сил Теразан. Чтобы перенести тебя к нему быстро и безопасно, мне нужно совершить ритуал.$b$bОтправляйся на поле и добудь у яростней элементиевую руду. Когда ее будет достаточно, я смогу сделать так, что ты станешь единым целым с землей и перенесешься туда, куда тебе нужно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 6 кусков элементиевой руды.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично. Теперь мне нужна пара минут, чтобы подготовить ритуал.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сланцу Плывуну в Грот Обвалов, что в Подземье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (27934,'Единое целое с землей','Войсками Матери-Скалы руководит огромный повелитель элементалей земли Лавинион. К счастью для нас сектанты Сумеречного Молота решили напасть на его логово. Они хотят подчинить его элементалей своей воле.$b$bМы воспользуемся этим. Ритуал земли, который я совершу, сделает тебя единым целым с землей. Ты окажешься недалеко от Лавиниона, ничем не выдав своего присутствия.$b$bПрикончи его.','Завершите ритуал единения с землей.','Лавинион прямо перед тобой. Ты знаешь, что нужно делать.','Сланц Плывун') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Единое целое с землей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Войсками Матери-Скалы руководит огромный повелитель элементалей земли Лавинион. К счастью для нас сектанты Сумеречного Молота решили напасть на его логово. Они хотят подчинить его элементалей своей воле.$b$bМы воспользуемся этим. Ритуал земли, который я совершу, сделает тебя единым целым с землей. Ты окажешься недалеко от Лавиниона, ничем не выдав своего присутствия.$b$bПрикончи его.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Завершите ритуал единения с землей.',`objectives_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Лавинион прямо перед тобой. Ты знаешь, что нужно делать.',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Сланц Плывун',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27935,'Победить Лавиниона','Лавинион стоит прямо перед тобой. Убей его, чтобы помешать войскам Теразан напасть на Каменный очаг.','Убейте Лавиниона.','Вернитесь с докладом к Крегу Крушителю Скал в Каменный очаг, что в Подземье.','Убей его, чтобы предотвратить нападение на Каменный очаг!','Лавинион') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Победить Лавиниона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Лавинион стоит прямо перед тобой. Убей его, чтобы помешать войскам Теразан напасть на Каменный очаг.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Лавиниона.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь с докладом к Крегу Крушителю Скал в Каменный очаг, что в Подземье.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Убей его, чтобы предотвратить нападение на Каменный очаг!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Лавинион',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27936,'Победить Лавиниона','Тебе нужно вернуться и убить Лавиниона, чтобы помешать войскам Теразан напасть на Каменный очаг!','Убейте Лавиниона.','Вернитесь с докладом к Крегу Крушителю Скал в Каменный очаг, что в Подземье.','Убей его, чтобы предотвратить нападение на Каменный очаг!','Лавинион') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Победить Лавиниона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе нужно вернуться и убить Лавиниона, чтобы помешать войскам Теразан напасть на Каменный очаг!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Лавиниона.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь с докладом к Крегу Крушителю Скал в Каменный очаг, что в Подземье.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Убей его, чтобы предотвратить нападение на Каменный очаг!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Лавинион',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27938,'Центральный фрагмент','Ты вернулся. Фрагмент у тебя?','Принесите центральный фрагмент столпа мира заклинательнице земли Еве в Храм Земли, что в Подземье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Центральный фрагмент',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты вернулся. Фрагмент у тебя?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите центральный фрагмент столпа мира заклинательнице земли Еве в Храм Земли, что в Подземье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27939,'Пустынная лиса','Работ в этой местность хоть отбавляйт, |3-6($r).$B$BМы с тобой двое иметь горячий страсть, не так ли? К технология древних, я имей в виду.$B$BМожет, объединяйт усилья?$B$BДафай оставлять позади наши прошлый распри.$B$BК делу: на восток обитай некая неуловимый зверье, на который я уже устать охота. Принести мне его в знак искренность твой намерений.$B$BИ я позволять тебе присоединяться к наш операция.','Шнотц желает, чтобы вы раздобыли ему пустынную лису.','Ты молодец!$B$BВозможен больший квота доверий тебе...','Обратитесь к Шнотцу в лагере Шнотца.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пустынная лиса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Работ в этой местность хоть отбавляйт, |3-6($r).$B$BМы с тобой двое иметь горячий страсть, не так ли? К технология древних, я имей в виду.$B$BМожет, объединяйт усилья?$B$BДафай оставлять позади наши прошлый распри.$B$BК делу: на восток обитай некая неуловимый зверье, на который я уже устать охота. Принести мне его в знак искренность твой намерений.$B$BИ я позволять тебе присоединяться к наш операция.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Шнотц желает, чтобы вы раздобыли ему пустынную лису.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты молодец!$B$BВозможен больший квота доверий тебе...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Обратитесь к Шнотцу в лагере Шнотца.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questgivertargetname_loc8`) VALUES (27940,'Грязные пташки','Небо над Высохшим оазисом кишит больными падальщиками.$B$BОни как зараженные грызуны – приносят только беду.$B$BОчисти небеса от этого недоразумения – сделай этот край лучше, чем он был до твоего прихода.','Перебейте 8 больных падальщиков.','Больной падальщик') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Грязные пташки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Небо над Высохшим оазисом кишит больными падальщиками.$B$BОни как зараженные грызуны – приносят только беду.$B$BОчисти небеса от этого недоразумения – сделай этот край лучше, чем он был до твоего прихода.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Перебейте 8 больных падальщиков.',`objectives_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Больной падальщик',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27941,'Дресс-код','В нашем уставе есть один пункт, к которому нужно отнестись со всей серьезностью.$B$BНаши бойцы должны носить официальную униформу не снимая. Это повышает организованность, снижает риск пальбы по своим, к тому же войска смотрятся потрясающе!$B$BМы это называем корпоративным дресс-кодом.$B$BУ нас понемногу заканчивается обмундирование. Вынужден просить тебя принести мне униформу наших соратников, павших на поле боя.$B$BМногие наши бойцы покоятся в руинах Аммона, к востоку отсюда.','Беллок Сияющий Клинок просит вас собрать 10 комплектов военной формы.','Удалось ли тебе раздобыть мундиры?','Поговорите с Беллоком Сияющим Клинком в лагере Шнотца.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дресс-код',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В нашем уставе есть один пункт, к которому нужно отнестись со всей серьезностью.$B$BНаши бойцы должны носить официальную униформу не снимая. Это повышает организованность, снижает риск пальбы по своим, к тому же войска смотрятся потрясающе!$B$BМы это называем корпоративным дресс-кодом.$B$BУ нас понемногу заканчивается обмундирование. Вынужден просить тебя принести мне униформу наших соратников, павших на поле боя.$B$BМногие наши бойцы покоятся в руинах Аммона, к востоку отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Беллок Сияющий Клинок просит вас собрать 10 комплектов военной формы.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось ли тебе раздобыть мундиры?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Беллоком Сияющим Клинком в лагере Шнотца.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27942,'Идолотерапия','Хотеть давайт тебе поручений, |3-6($r).$B$BМой самый доверяйт советник стать жертва древний проклятье. Проклятье, который превращать человек в индюшка!$B$BДни напрочь я искать средство против – и наконец готовый осуществляйт ритуал.$B$BДля этот цель надо идолы с близко руинов. Приноси их быстро-быстро!$B$BФольно!','Принесите командиру Шнотцу 8 хорошо сохранившихся идолов.','Состояние гут..$B$BЭто есть нам первый шаги к ритуал очищивания.','Обратитесь к командиру Шнотцу в лагере Шнотца.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Идолотерапия',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хотеть давайт тебе поручений, |3-6($r).$B$BМой самый доверяйт советник стать жертва древний проклятье. Проклятье, который превращать человек в индюшка!$B$BДни напрочь я искать средство против – и наконец готовый осуществляйт ритуал.$B$BДля этот цель надо идолы с близко руинов. Приноси их быстро-быстро!$B$BФольно!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите командиру Шнотцу 8 хорошо сохранившихся идолов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Состояние гут..$B$BЭто есть нам первый шаги к ритуал очищивания.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Обратитесь к командиру Шнотцу в лагере Шнотца.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27943,'Разгневанные духи','Док Венкман быть числом лучших работникофф наука, пока время не прийти от него избавляйся.$B$BОднако он оставить мне величайший изобретений. Орудие борьба сверхъестественным. Его надо настройт и он выкачивайт из духа жизненный сила.$B$BЭтот оружий – ключевая роль мой ритуал.$B$BЗачем есть ты? Ты добывайт нужный ингредиент.$B$BЯ калибровать орудий на работа против бешеный призрак – их много-много в храм на восток.','Командир Шнотц велит вам с помощью ЛППУ добыть 5 экстрактов взбешенного призрака.','Отшень гуд!$B$BТы заработайт право участвовайт ритуал.$B$BТы будешь один первый, кто поприветствовайт Кулдык, когда он обретайт... привычный облик.','Ну что, маленький человек? Ты это сделайт?','Поговорите с командиром Шнотцем в лагере Шнотца.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разгневанные духи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Док Венкман быть числом лучших работникофф наука, пока время не прийти от него избавляйся.$B$BОднако он оставить мне величайший изобретений. Орудие борьба сверхъестественным. Его надо настройт и он выкачивайт из духа жизненный сила.$B$BЭтот оружий – ключевая роль мой ритуал.$B$BЗачем есть ты? Ты добывайт нужный ингредиент.$B$BЯ калибровать орудий на работа против бешеный призрак – их много-много в храм на восток.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Командир Шнотц велит вам с помощью ЛППУ добыть 5 экстрактов взбешенного призрака.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отшень гуд!$B$BТы заработайт право участвовайт ритуал.$B$BТы будешь один первый, кто поприветствовайт Кулдык, когда он обретайт... привычный облик.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, маленький человек? Ты это сделайт?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с командиром Шнотцем в лагере Шнотца.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27944,'Очищение леса','Мы неделями пытаемся зацепиться в Мрачном лесу, но лес просто кишит пауками. Окажи мне услугу, перебей эту гадость, чтобы мы могли подготовиться к нападению.$b$bБудь $gбдителен:бдительна;, когда доберешься до леса, а то мне тут на неделе доложили, что поблизости орудует Орда.','Убейте 12 скрытней Мрачного леса. Мрачный лес находится за мостом, к западу отсюда, в центральной части острова.','Когда закончите, доложите о своих успехах начальнику лагеря Брэку в Лагере Барадин.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Очищение леса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы неделями пытаемся зацепиться в Мрачном лесу, но лес просто кишит пауками. Окажи мне услугу, перебей эту гадость, чтобы мы могли подготовиться к нападению.$b$bБудь $gбдителен:бдительна;, когда доберешься до леса, а то мне тут на неделе доложили, что поблизости орудует Орда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 скрытней Мрачного леса. Мрачный лес находится за мостом, к западу отсюда, в центральной части острова.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Когда закончите, доложите о своих успехах начальнику лагеря Брэку в Лагере Барадин.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27945,'Закрасить черным','Земля истекает кровью, |3-6($c). Они вспороли ее, как клинок вспарывает кожу.$B$BСектанты вершат свои темные дела с помощью элементалей – глупцы, они даже не подозревают о том, что элементали могут предать их. Иди на северо-восток – в то место, которое мы зовем Черный разлом. Там ты найдешь обсидиановых рабов камня.$B$BРаздроби их тела и найди идеальное сердце из черного алмаза. Я загляну в это сердце и увижу душу раба.','Добудьте черное алмазное сердце.','<Маллия снимает с глаза повязку и подносит черный алмаз к пустой глазнице.>$B$BТак-так... Что тут у нас... проломы, проломы числом три. Две головы, одна полностью подчинена своему хозяину. Я вижу будущее. Молоты объединились. Гора раскололась. Ой... ОЙ!$B$B<Маллия роняет алмаз на пол и закрывает лицо руками.>','Сердце. Каменное сердце, совершенно черное. Тебе удалось его найти?','Отнесите сердце Маллии в Кровавое ущелье на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Закрасить черным',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Земля истекает кровью, |3-6($c). Они вспороли ее, как клинок вспарывает кожу.$B$BСектанты вершат свои темные дела с помощью элементалей – глупцы, они даже не подозревают о том, что элементали могут предать их. Иди на северо-восток – в то место, которое мы зовем Черный разлом. Там ты найдешь обсидиановых рабов камня.$B$BРаздроби их тела и найди идеальное сердце из черного алмаза. Я загляну в это сердце и увижу душу раба.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте черное алмазное сердце.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Маллия снимает с глаза повязку и подносит черный алмаз к пустой глазнице.>$B$BТак-так... Что тут у нас... проломы, проломы числом три. Две головы, одна полностью подчинена своему хозяину. Я вижу будущее. Молоты объединились. Гора раскололась. Ой... ОЙ!$B$B<Маллия роняет алмаз на пол и закрывает лицо руками.>',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Сердце. Каменное сердце, совершенно черное. Тебе удалось его найти?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите сердце Маллии в Кровавое ущелье на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27947,'Видение Сумерек','Чо\'Галл следит за своими слугами с помощью волшебных шаров, "Очей Сумерек".$B$BСтражам Хиджала удалось найти один такой шар и понять, как он действует. То же надлежит сделать и нам. Мне нужен такой шар – тогда я смогу заглянуть в логово Чо\'Галла!$B$BПереправься через реку и иди на северо-восток. Обыщи Черный разлом и найди Око Сумерек. Делай что хочешь, но найди его!','Найдите Око Сумерек в Черном разломе.','<Око стоит перед вами, издавая зловещий гул.>$B$B<Внезапно оно поворачивается, словно хочет посмотреть на вас. Вам кажется, что Око – живое и в нем заключена какая-то злобная сущность.>','Найдите Око Сумерек в Черном разломе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Видение Сумерек',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чо\'Галл следит за своими слугами с помощью волшебных шаров, "Очей Сумерек".$B$BСтражам Хиджала удалось найти один такой шар и понять, как он действует. То же надлежит сделать и нам. Мне нужен такой шар – тогда я смогу заглянуть в логово Чо\'Галла!$B$BПереправься через реку и иди на северо-восток. Обыщи Черный разлом и найди Око Сумерек. Делай что хочешь, но найди его!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Око Сумерек в Черном разломе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Око стоит перед вами, издавая зловещий гул.>$B$B<Внезапно оно поворачивается, словно хочет посмотреть на вас. Вам кажется, что Око – живое и в нем заключена какая-то злобная сущность.>',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Найдите Око Сумерек в Черном разломе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27948,'Липкая работа','Непросто было найти припасы на острове, скажу я тебе.$b$bК счастью, к западу отсюда, в Мрачном лесу, нам удалось обнаружить хороший источник шелка. Плохая новость – это то, что шелк производят паучихи-праматери. Достань мне 4 паутинных железы праматерей.$b$bЭтого хватит, чтобы дошить последний комплект рубашек.','Соберите 4 липких паутинных железы праматерей Мрачного леса. Чтобы попасть в лес, находящийся в центральной части острова, пересеките мост к западу от лагеря.','Тебе удалось достать липкие паутинные железы?','Когда закончите, доложите о своих успехах начальнику лагеря Брэку в Лагере Барадин.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Липкая работа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Непросто было найти припасы на острове, скажу я тебе.$b$bК счастью, к западу отсюда, в Мрачном лесу, нам удалось обнаружить хороший источник шелка. Плохая новость – это то, что шелк производят паучихи-праматери. Достань мне 4 паутинных железы праматерей.$b$bЭтого хватит, чтобы дошить последний комплект рубашек.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 4 липких паутинных железы праматерей Мрачного леса. Чтобы попасть в лес, находящийся в центральной части острова, пересеките мост к западу от лагеря.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось достать липкие паутинные железы?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Когда закончите, доложите о своих успехах начальнику лагеря Брэку в Лагере Барадин.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27949,'Позабытые','На этом острове погибло много солдат, $n. Наш долг – почтить их память.$b$bОтправляйся на Забытый холм, что к западу отсюда, и освободи души наших братьев по оружию, томящиеся там. Будь $gосторожен:осторожна;, по донесениям в тех местах бесчинствует нежить.','Освободите 6 истерзанных душ на Забытом холме. Душу можно высвободить, дотронувшись до могильного камня. Забытый холм расположен к западу отсюда, за Мрачным лесом и Передовой Неупокоенных.','Да обретут их души вечный покой.','Доложите лейтенанту Фарнсворту в Лагере Барадин о завершении задания.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Позабытые',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На этом острове погибло много солдат, $n. Наш долг – почтить их память.$b$bОтправляйся на Забытый холм, что к западу отсюда, и освободи души наших братьев по оружию, томящиеся там. Будь $gосторожен:осторожна;, по донесениям в тех местах бесчинствует нежить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Освободите 6 истерзанных душ на Забытом холме. Душу можно высвободить, дотронувшись до могильного камня. Забытый холм расположен к западу отсюда, за Мрачным лесом и Передовой Неупокоенных.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да обретут их души вечный покой.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доложите лейтенанту Фарнсворту в Лагере Барадин о завершении задания.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27950,'Кулдык!','Аллес! Время снимайт с мой Кулдыка мерзкий проклятье!$B$BБыть начеку, |3-6($r), смотреть два глаз. Никто не помешайт мне проводить ритуал.$B$BЗнайт, все есть чисто, давать знайт мне!$B$BФорвартс!','Шнотц хочет, чтобы вы поговорили с ним, когда будете готовы узреть ритуал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кулдык!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Аллес! Время снимайт с мой Кулдыка мерзкий проклятье!$B$BБыть начеку, |3-6($r), смотреть два глаз. Никто не помешайт мне проводить ритуал.$B$BЗнайт, все есть чисто, давать знайт мне!$B$BФорвартс!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Шнотц хочет, чтобы вы поговорили с ним, когда будете готовы узреть ритуал.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27952,'Исследователи','Поговорите с исследовательницей Мови в Храме Земли в Подземье.','Боже! Поможет нам кто-нибудь наконец?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Исследователи',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с исследовательницей Мови в Храме Земли в Подземье.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Боже! Поможет нам кто-нибудь наконец?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27953,'Реликварий','В зале в северо-восточной части Храма появились сотрудники Реликвария.$b$bОни все больше кричат о том, что Сумеречный Молот что-то затевает.$b$b$n, не будешь ли ты так $gдобр:добра; узнать, что им нужно?','Поговорите с исследователем Роу в Храме Земли в Подземье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Реликварий',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В зале в северо-восточной части Храма появились сотрудники Реликвария.$b$bОни все больше кричат о том, что Сумеречный Молот что-то затевает.$b$b$n, не будешь ли ты так $gдобр:добра; узнать, что им нужно?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с исследователем Роу в Храме Земли в Подземье.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27954,'Всевидящее Око','Ну хорошо, |3-6($r). Мои услуги оплачены кровью. Отнеси меня Гароне Полуорчихе.$B$BО да, я уже знаю, куда ты меня понесешь. Ни для кого не секрет, что Гарона мечтает о мести. Я с удовольствием буду следить за развитием событий.','Отдайте Око Сумерек Гароне Полуорчихе в Кровавом ущелье на Сумеречном нагорье.','Тебе удалось найти Око? Я искала его повсюду! Давай его сюда!$B$BК каждому из них нужен особый подход. Некоторым достаточно стихов и загадок, к другим необходимо применить магию. А что потребовало от тебя это? А, не важно. Око в наших руках, и это самое главное.','Ну, что? Твой поход в Черный разлом был успешным?','Отдайте Око Сумерек Гароне Полуорчихе в Кровавом ущелье на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Всевидящее Око',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну хорошо, |3-6($r). Мои услуги оплачены кровью. Отнеси меня Гароне Полуорчихе.$B$BО да, я уже знаю, куда ты меня понесешь. Ни для кого не секрет, что Гарона мечтает о мести. Я с удовольствием буду следить за развитием событий.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отдайте Око Сумерек Гароне Полуорчихе в Кровавом ущелье на Сумеречном нагорье.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебе удалось найти Око? Я искала его повсюду! Давай его сюда!$B$BК каждому из них нужен особый подход. Некоторым достаточно стихов и загадок, к другим необходимо применить магию. А что потребовало от тебя это? А, не важно. Око в наших руках, и это самое главное.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, что? Твой поход в Черный разлом был успешным?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отдайте Око Сумерек Гароне Полуорчихе в Кровавом ущелье на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27955,'Глаз-шпион','От одного вида этой ужасной штуки у меня мороз по коже. С их помощью Чо\'Галл правит своими миньонами – что ж, а мы обратим это Око против него.$B$BТак, посмотрим... хм... тут все мутное. Я вижу только тебя. Почему глаз показывает мне тебя?$B$B<Гарона ставит Око перед собой.>$B$BЗагляни в глаз и расскажи мне, что ты в нем видишь. Загляни в логово Чо\'Галла! Что он делает? Много ли с ним стражи? Отвечай!','Загляните в Око Сумерек.','Разбойник, твое лицо побледнело. Что показало тебе Око?$B$BЧо\'Галла? Постой... Чо\'Галл увидел тебя? Он следит за нами? Он следит за нами прямо сейчас?!$B$BПроклятая черная магия! Нет, я лучше проникну в крепость Чо\'Галла и все разведаю.','Поговорите с Гароной Полуорчихой в Кровавом ущелье на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Глаз-шпион',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','От одного вида этой ужасной штуки у меня мороз по коже. С их помощью Чо\'Галл правит своими миньонами – что ж, а мы обратим это Око против него.$B$BТак, посмотрим... хм... тут все мутное. Я вижу только тебя. Почему глаз показывает мне тебя?$B$B<Гарона ставит Око перед собой.>$B$BЗагляни в глаз и расскажи мне, что ты в нем видишь. Загляни в логово Чо\'Галла! Что он делает? Много ли с ним стражи? Отвечай!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Загляните в Око Сумерек.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Разбойник, твое лицо побледнело. Что показало тебе Око?$B$BЧо\'Галла? Постой... Чо\'Галл увидел тебя? Он следит за нами? Он следит за нами прямо сейчас?!$B$BПроклятая черная магия! Нет, я лучше проникну в крепость Чо\'Галла и все разведаю.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Гароной Полуорчихой в Кровавом ущелье на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27956,'Задача Чурбана','Чурбан пришел из Бесплодных земель. Другие огры дерутся с Чурбаном.$b$bЧурбан ненавидит драться. Чурбан хочет учиться.$b$bЧурбан видел машины на юге. У машин есть детали. Может быть, если вежливо попросить, машины дадут детали? Может быть, если у Чурбана будут детали, он узнает больше и о машинах.','Получите 15 закаленных маховиков из закаленных боевых големов.','Но ты же не… УБИЛ их, нет?$B$B<Чурбан выглядит расстроенным.>$B$BВедь нет?','Вернитесь к Чурбану на Передовую Братства Тория в Тлеющее ущелье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Задача Чурбана',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чурбан пришел из Бесплодных земель. Другие огры дерутся с Чурбаном.$b$bЧурбан ненавидит драться. Чурбан хочет учиться.$b$bЧурбан видел машины на юге. У машин есть детали. Может быть, если вежливо попросить, машины дадут детали? Может быть, если у Чурбана будут детали, он узнает больше и о машинах.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Получите 15 закаленных маховиков из закаленных боевых големов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Но ты же не… УБИЛ их, нет?$B$B<Чурбан выглядит расстроенным.>$B$BВедь нет?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Чурбану на Передовую Братства Тория в Тлеющее ущелье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (27957,'Чурбан не убивать') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чурбан не убивать',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27958,'Правильное противоядие','Жаль, что Чурбан ушел. Мне уже начала нравиться его компания.$b$bОх, ладно, пора возвращаться к работе!$b$bЯ в этой экспедиции лучше всех разбираюсь в медицине, и у меня заканчивается противоядие. А нам его понадобится много.$b$bСоздание хорошего противоядия всегда начинается с добычи яда. Можем начать со стеклопутых пауков, что водятся неподалеку. Если убьешь их, то, наверное, сможешь достать некоторое количество яда из желез под их зубами.','Добудьте 14 порций яда стеклопутого паука.','Да тут… гораздо больше, чем я ожидала. У нас теперь будет запас на месяцы вперед!','Что ж, ты действительно быстр! Добыл яд?','Вернитесь к Призанне Пылеглот на Передовую Братства Тория, что в Тлеющем ущелье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Правильное противоядие',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Жаль, что Чурбан ушел. Мне уже начала нравиться его компания.$b$bОх, ладно, пора возвращаться к работе!$b$bЯ в этой экспедиции лучше всех разбираюсь в медицине, и у меня заканчивается противоядие. А нам его понадобится много.$b$bСоздание хорошего противоядия всегда начинается с добычи яда. Можем начать со стеклопутых пауков, что водятся неподалеку. Если убьешь их, то, наверное, сможешь достать некоторое количество яда из желез под их зубами.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 14 порций яда стеклопутого паука.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да тут… гораздо больше, чем я ожидала. У нас теперь будет запас на месяцы вперед!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что ж, ты действительно быстр! Добыл яд?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Призанне Пылеглот на Передовую Братства Тория, что в Тлеющем ущелье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27959,'Приключения Чурбана: верхом на пауках','Чурбан видит, что тебе нравится убивать. Давай Чурбан научит тебя, как можно по-другому.$b$bЧурбану всегда хотелось покататься на пауках. Это должно быть забавно. Хотя пауки бегают слишком быстро. И всегда соскальзываешь.$b$bНо мы попробуем вместе. Ты будешь драться с пауком, пока он не станет усталым и слабым. Потом Чурбан запрыгнет на паука и покатается.$b$bМожет быть, Чурбан даже соберет для тебя немного яда! Но не надо убивать!','Добейтесь того, чтобы 7 стеклопутных пауков ослабли и Чурбан смог покататься на них.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приключения Чурбана: верхом на пауках',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чурбан видит, что тебе нравится убивать. Давай Чурбан научит тебя, как можно по-другому.$b$bЧурбану всегда хотелось покататься на пауках. Это должно быть забавно. Хотя пауки бегают слишком быстро. И всегда соскальзываешь.$b$bНо мы попробуем вместе. Ты будешь драться с пауком, пока он не станет усталым и слабым. Потом Чурбан запрыгнет на паука и покатается.$b$bМожет быть, Чурбан даже соберет для тебя немного яда! Но не надо убивать!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добейтесь того, чтобы 7 стеклопутных пауков ослабли и Чурбан смог покататься на них.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27960,'Чем меньше, тем лучше','Я не ахти какой боец... мне интереснее копаться в земле. И Джек, и Приз такие же. И Чурбан... По его виду можно предположить, что он драчун, но на самом деле он самый большой тюфяк из всех нас.$b$bЯ хочу сказать, что хорошо, что ты $gпришел:пришла; тогда, когда $gпришел:пришла;.$b$bПохоже, что скоро нашему Братству Тория придется драться с дворфами Черного Железа. Думаю, надо вывести из строя самых сильных их бойцов, пока и в самом деле не началась война. Начни с тех геологов и сторожей, что на юге.','Убейте 10 геологов или сторожей из клана Черного Железа.','Спасибо.','Вернитесь к Копению Угледробу на Передовую Братства Тория, что в Тлеющем ущелье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чем меньше, тем лучше',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я не ахти какой боец... мне интереснее копаться в земле. И Джек, и Приз такие же. И Чурбан... По его виду можно предположить, что он драчун, но на самом деле он самый большой тюфяк из всех нас.$b$bЯ хочу сказать, что хорошо, что ты $gпришел:пришла; тогда, когда $gпришел:пришла;.$b$bПохоже, что скоро нашему Братству Тория придется драться с дворфами Черного Железа. Думаю, надо вывести из строя самых сильных их бойцов, пока и в самом деле не началась война. Начни с тех геологов и сторожей, что на юге.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 геологов или сторожей из клана Черного Железа.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Копению Угледробу на Передовую Братства Тория, что в Тлеющем ущелье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27961,'Не на своем месте','Ущелье беспощадно. Нельзя сказать, что оно изобилует дичью.$b$bМы пытались завести кое-каких животных, но они здесь плохо себя чувствуют. Здесь просто нет пищи. А теперь пауки, которые водятся поблизости, питаясь мясом цыплят, становятся большими и толстыми, а ведь они и без этого опасны.$b$bОт пауков мы вряд ли когда-то избавимся, но мы можем спасти оставшихся цыплят. Тем самым ты не только обеспечишь Братство пищей, но и избавишь цыплят от болезненной смерти от паучьих укусов.','Добудьте 8 пепельных цыплят.','Бедные создания.','Вернитесь к Копению Угледробу на Передовую Братства Тория, что в Тлеющем ущелье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Не на своем месте',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ущелье беспощадно. Нельзя сказать, что оно изобилует дичью.$b$bМы пытались завести кое-каких животных, но они здесь плохо себя чувствуют. Здесь просто нет пищи. А теперь пауки, которые водятся поблизости, питаясь мясом цыплят, становятся большими и толстыми, а ведь они и без этого опасны.$b$bОт пауков мы вряд ли когда-то избавимся, но мы можем спасти оставшихся цыплят. Тем самым ты не только обеспечишь Братство пищей, но и избавишь цыплят от болезненной смерти от паучьих укусов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 8 пепельных цыплят.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Бедные создания.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Копению Угледробу на Передовую Братства Тория, что в Тлеющем ущелье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27962,'Рокочущие останки','Добудьте гигантский рог Маргульи.','Да, это действительно рог Маргульи. Нет никаких сомнений.$B$BБарнабас, как и я, был простым землекопом. У него не было никаких шансов в битве с таким чудовищем. Я очень рад, что ты оказался здесь, чтобы расставить все по своим местам.','Вернитесь к Копению Угледробу на Передовую Братства Тория, что в Тлеющем ущелье.','Древний страж Тлеющего ущелья.','Маргулья Свирепая') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рокочущие останки',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте гигантский рог Маргульи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, это действительно рог Маргульи. Нет никаких сомнений.$B$BБарнабас, как и я, был простым землекопом. У него не было никаких шансов в битве с таким чудовищем. Я очень рад, что ты оказался здесь, чтобы расставить все по своим местам.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Копению Угледробу на Передовую Братства Тория, что в Тлеющем ущелье.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Древний страж Тлеющего ущелья.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Маргулья Свирепая',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27963,'Новый хозяин... Но кто?','Ты как раз вовремя.$b$bИзлагаю факты: дворфы Черного Железа, которые обитают в ущелье, ведут себя странно, и Братство Тория намеревается выяснить, почему. Надзиратель Скользорук не любит сюрпризов.$b$bМы подозреваем, что у них появился новый командир, он и отдает приказы. У меня есть все основания считать, что Гравиус Грязнуля в курсе, кто бы это мог быть. Гравиуса можно найти к югу отсюда.$b$bДаже сюда, в Тлеющее ущелье дошли слухи о твоих подвигах, $n. Ты легко справишься с Грязнулей.','Найдите Гравиуса Грязнулю на строительной площадке Грязнули и отберите у него докладную записку Черного Железа.','Посмотрим… Надзиратель Мальторий… Нам известно о нем и его деяниях.$B$BА это что? "Эрцгерцог"? Звучит многообещающе.','Есть новости?','Вернитесь к Джеку Глыбоногу на Передовую Братства Тория, что в Тлеющем ущелье.','Этот дворф должен лучше знать, что происходит с Черным Железом.','Гравиус Грязнуля') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новый хозяин... Но кто?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты как раз вовремя.$b$bИзлагаю факты: дворфы Черного Железа, которые обитают в ущелье, ведут себя странно, и Братство Тория намеревается выяснить, почему. Надзиратель Скользорук не любит сюрпризов.$b$bМы подозреваем, что у них появился новый командир, он и отдает приказы. У меня есть все основания считать, что Гравиус Грязнуля в курсе, кто бы это мог быть. Гравиуса можно найти к югу отсюда.$b$bДаже сюда, в Тлеющее ущелье дошли слухи о твоих подвигах, $n. Ты легко справишься с Грязнулей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Гравиуса Грязнулю на строительной площадке Грязнули и отберите у него докладную записку Черного Железа.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Посмотрим… Надзиратель Мальторий… Нам известно о нем и его деяниях.$B$BА это что? "Эрцгерцог"? Звучит многообещающе.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Есть новости?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джеку Глыбоногу на Передовую Братства Тория, что в Тлеющем ущелье.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Этот дворф должен лучше знать, что происходит с Черным Железом.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Гравиус Грязнуля',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27964,'Главный землекоп Звоноус','Оказывается, Грязнуля занимал не такое высокое положение, как я думал. Мы должны устранить того, кому он подчиняется, предварительно узнав, что ему известно.$b$bЭто главный землекоп Звоноус, и он руководит земельными работами в Котловане, к северо-западу отсюда. Его землечерпы и пехотинцы надзирают за восточной частью Котлована, день и ночь копая ямы.$b$bОн не слишком часто показывается на поверхности, но если ты убьешь побольше его людей, он будет вынужден выйти и разобраться с тобой.','Отправляйтесь в Котлован и убивайте землечерпов и пехотинцев из клана Черного Железа до тех пор, пока не появится главный землекоп Звоноус. Затем убейте Звоноуса и заберите у него темный тлеющий уголь.','У… уголь? А что в нем такого?','Если у Звоноуса нет того, что мы ищем, я даже и не знаю, что нам делать дальше.','Вернитесь к Джеку Глыбоногу на Передовую Братства Тория, что в Тлеющем ущелье.','Начальник Грязнули – Звоноус. Возможно, у него больше информации.','Главный землекоп Звоноус') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Главный землекоп Звоноус',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Оказывается, Грязнуля занимал не такое высокое положение, как я думал. Мы должны устранить того, кому он подчиняется, предварительно узнав, что ему известно.$b$bЭто главный землекоп Звоноус, и он руководит земельными работами в Котловане, к северо-западу отсюда. Его землечерпы и пехотинцы надзирают за восточной частью Котлована, день и ночь копая ямы.$b$bОн не слишком часто показывается на поверхности, но если ты убьешь побольше его людей, он будет вынужден выйти и разобраться с тобой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Котлован и убивайте землечерпов и пехотинцев из клана Черного Железа до тех пор, пока не появится главный землекоп Звоноус. Затем убейте Звоноуса и заберите у него темный тлеющий уголь.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','У… уголь? А что в нем такого?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если у Звоноуса нет того, что мы ищем, я даже и не знаю, что нам делать дальше.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джеку Глыбоногу на Передовую Братства Тория, что в Тлеющем ущелье.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Начальник Грязнули – Звоноус. Возможно, у него больше информации.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Главный землекоп Звоноус',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27965,'Лагерь Братства Тория: трон Братства','Ты... ты $gвидел:видела; это? Вот же недостающий элемент, который мы искали! Нужно передать эту информацию кому-нибудь из лагеря Братства Тория.$b$bИзвестно, что в прошлом дворфы Черного Железа имели дело с Повелителем Огня, но никогда раньше они не проникали так далеко в Тлеющее ущелье.$b$bЧтобы добраться до лагеря Братства Тория, надо двигаться на запад, а потом на север. Лагерь находится в скалах, которые возвышаются над северным плато Пироксовых равнин. Передай эту информацию лично надзирателю Скользоруку.','Отправляйтесь с докладом к надзирателю Скользоруку в лагере Братства Тория, что в Тлеющем ущелье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лагерь Братства Тория: трон Братства',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты... ты $gвидел:видела; это? Вот же недостающий элемент, который мы искали! Нужно передать эту информацию кому-нибудь из лагеря Братства Тория.$b$bИзвестно, что в прошлом дворфы Черного Железа имели дело с Повелителем Огня, но никогда раньше они не проникали так далеко в Тлеющее ущелье.$b$bЧтобы добраться до лагеря Братства Тория, надо двигаться на запад, а потом на север. Лагерь находится в скалах, которые возвышаются над северным плато Пироксовых равнин. Передай эту информацию лично надзирателю Скользоруку.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь с докладом к надзирателю Скользоруку в лагере Братства Тория, что в Тлеющем ущелье.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27966,'Спасение останков','На Забытый холм покушаются зомби и вурдалаки c тех самых пор, как мы обосновались на этом проклятом острове. Мы многократно пытались очистить его от нежити, но безуспешно.$b$bОдин офицер посоветовал нам собирать кости вурдалаков, чтобы те еженощно не восставали из мертвых. Не подсобишь?','От вас требуется собрать 9 проклятых бедренных костей вурдалаков, населяющих Забытый холм. Это место расположено на западной стороне острова за Передовой Неупокоенных.','Собрал бедренные кости? Ты справишься с этим лучше меня.','Доложите лейтенанту Фарнсворту в Лагере Барадин о завершении задания.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спасение останков',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На Забытый холм покушаются зомби и вурдалаки c тех самых пор, как мы обосновались на этом проклятом острове. Мы многократно пытались очистить его от нежити, но безуспешно.$b$bОдин офицер посоветовал нам собирать кости вурдалаков, чтобы те еженощно не восставали из мертвых. Не подсобишь?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','От вас требуется собрать 9 проклятых бедренных костей вурдалаков, населяющих Забытый холм. Это место расположено на западной стороне острова за Передовой Неупокоенных.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Собрал бедренные кости? Ты справишься с этим лучше меня.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доложите лейтенанту Фарнсворту в Лагере Барадин о завершении задания.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27967,'Старший лейтенант Коннор','Я впервые услышал о лейтенанте Конноре, когда был новобранцем в тюрьме Штормграда. Никто бы не поверил, что он очутится здесь, на Тол Бараде. К сожалению, он все еще бродит по этим проклятым островам, сея смуту в наших войсках.$b$bПоложи конец его страданиям, а заодно и нашим.','Обнаружьте и убейте старшего лейтенанта Коннора на Забытом холме. Это место расположено в западной стороне острова.','Ты выжил! Ты не первый, кто пытался справиться с этим заданием, но первый, кто унес оттуда ноги.','Доложите лейтенанту Фарнсворту в Лагере Барадин о завершении задания.','Никто не хочет заканчивать тут свои дни, но жизнь порой складывается помимо нашей воли.','Старший лейтенант Коннор') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Старший лейтенант Коннор',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я впервые услышал о лейтенанте Конноре, когда был новобранцем в тюрьме Штормграда. Никто бы не поверил, что он очутится здесь, на Тол Бараде. К сожалению, он все еще бродит по этим проклятым островам, сея смуту в наших войсках.$b$bПоложи конец его страданиям, а заодно и нашим.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обнаружьте и убейте старшего лейтенанта Коннора на Забытом холме. Это место расположено в западной стороне острова.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты выжил! Ты не первый, кто пытался справиться с этим заданием, но первый, кто унес оттуда ноги.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доложите лейтенанту Фарнсворту в Лагере Барадин о завершении задания.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Никто не хочет заканчивать тут свои дни, но жизнь порой складывается помимо нашей воли.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Старший лейтенант Коннор',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27968,'Ярость стаи','О, сладкий запах победы! Должно быть, прямо сейчас, пока мы с тобой говорим, мои бойцы рвут Годфри в клочья. Отправляйся в его владения и получи свою долю останков – ты это $gзаслужил:заслужила;!$B$BКак мы с ним быстро разделались! Даже не думал, что все будет так просто...','Убейте лорда Годфри.','Вернитесь к вожаку стаи Ивару Кровавому Клыку.','За Кровавые Клыки!','Лорд Годфри') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ярость стаи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','О, сладкий запах победы! Должно быть, прямо сейчас, пока мы с тобой говорим, мои бойцы рвут Годфри в клочья. Отправляйся в его владения и получи свою долю останков – ты это $gзаслужил:заслужила;!$B$BКак мы с ним быстро разделались! Даже не думал, что все будет так просто...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте лорда Годфри.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к вожаку стаи Ивару Кровавому Клыку.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','За Кровавые Клыки!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Лорд Годфри',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27969,'Займись чем-нибудь полезным','Мы скорбеть Кулдыка, но приказ выполняйт, битте.$B$BТы вину искупляйт смочь.$B$BНадевайт форма ты добывайт. Мой работник видеть тебя эта форма и стать... не так агрессия.$B$BПоследний время их боевой настроений невысока. Отказывай выполняйт прямой обязанность.$B$BШайзе!$B$BТы разыскать эти ленивый олух и объясняйт – арбайтен... Или капут!','Командир Шнотц хочет, чтобы вы заставили 6 ленивых работников приняться за дело.','Поговорите с командиром Шнотцем в лагере Шнотца.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Займись чем-нибудь полезным',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы скорбеть Кулдыка, но приказ выполняйт, битте.$B$BТы вину искупляйт смочь.$B$BНадевайт форма ты добывайт. Мой работник видеть тебя эта форма и стать... не так агрессия.$B$BПоследний время их боевой настроений невысока. Отказывай выполняйт прямой обязанность.$B$BШайзе!$B$BТы разыскать эти ленивый олух и объясняйт – арбайтен... Или капут!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Командир Шнотц хочет, чтобы вы заставили 6 ленивых работников приняться за дело.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с командиром Шнотцем в лагере Шнотца.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27970,'Капитан П. Харрис','Мыс Потерянной Надежды уже долгое время стоит у нас как кость в горле. Половина кораблей с провиантом для Тол Барада разбивается внизу о скалы.$b$bЧто еще хуже, так это неупокоенные моряки, докучающие нам. Мы пробовали расправиться с ними, да только они приходят все снова и снова. Последняя надежда – убить капитана, которому они подчиняются. Ты найдешь его на корабле, причалившем к берегу.$b$bНадеюсь, ты не очень боишься акул?','Вас просят убить капитана П. Харриса на мысе Потерянной Надежды. Мыс расположен к северо-западу, если идти вдоль береговой линии. Ищите обломки корабля.','Когда закончите, доложите о своих успехах начальнику лагеря Брэку в Лагере Барадин.','Убей капитана, и его подчиненные отступят.','Капитан П. Харрис') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Капитан П. Харрис',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мыс Потерянной Надежды уже долгое время стоит у нас как кость в горле. Половина кораблей с провиантом для Тол Барада разбивается внизу о скалы.$b$bЧто еще хуже, так это неупокоенные моряки, докучающие нам. Мы пробовали расправиться с ними, да только они приходят все снова и снова. Последняя надежда – убить капитана, которому они подчиняются. Ты найдешь его на корабле, причалившем к берегу.$b$bНадеюсь, ты не очень боишься акул?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вас просят убить капитана П. Харриса на мысе Потерянной Надежды. Мыс расположен к северо-западу, если идти вдоль береговой линии. Ищите обломки корабля.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Когда закончите, доложите о своих успехах начальнику лагеря Брэку в Лагере Барадин.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Убей капитана, и его подчиненные отступят.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Капитан П. Харрис',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27971,'Раздробить косточки','Уже долгое время нас беспокоит нежить с мыса Потерянной Надежды. Всякий раз, как разбивается корабль, ее воинство пополняется новыми душами.$b$bТы не $gмог:могла; бы оказать нам услугу, уничтожив несколько неупокоенных врагов? Знаю, что всех их истребить невозможно, но так ты хоть немного облегчишь нашу задачу.$b$bОстерегайся солдат Орды. Поступают донесения о том, что они устраивают засады вдоль береговой линии.','Начальник лагеря Брэк поручил вам уничтожить 8 моряков-утопленников на мысе Потерянной Надежды. Мыс расположен к северо-западу, если идти вдоль береговой линии.','Когда закончите, доложите о своих успехах начальнику лагеря Брэку в Лагере Барадин.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Раздробить косточки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Уже долгое время нас беспокоит нежить с мыса Потерянной Надежды. Всякий раз, как разбивается корабль, ее воинство пополняется новыми душами.$b$bТы не $gмог:могла; бы оказать нам услугу, уничтожив несколько неупокоенных врагов? Знаю, что всех их истребить невозможно, но так ты хоть немного облегчишь нашу задачу.$b$bОстерегайся солдат Орды. Поступают донесения о том, что они устраивают засады вдоль береговой линии.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Начальник лагеря Брэк поручил вам уничтожить 8 моряков-утопленников на мысе Потерянной Надежды. Мыс расположен к северо-западу, если идти вдоль береговой линии.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Когда закончите, доложите о своих успехах начальнику лагеря Брэку в Лагере Барадин.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27972,'Поддержание боевого духа','Наши войска деморализованы, $n. Мы прилагаем все усилия, чтобы поддерживать в солдатах боевой дух, вот только главная составляющая успеха – ром – подходит к концу.$b$bПехотинцы с южного побережья докладывают, что в трюмах кораблей, затонувших у мыса Потерянной Надежды, хранится хороший запас рома. Не $gмог:могла; бы ты проверить, так ли это?$b$bПринеси весь ром, что сможешь найти.','Вас попросили доставить 6 бочонков южноморского рома с кораблей, затонувших у мыса Потерянной Надежды. Мыс расположен севернее на береговой линии.','Ты достал ром? Я бы и сам сходил, да только панически боюсь воды. Не говоря уж о бешеной акуле...','Когда закончите, доложите о своих успехах начальнику лагеря Брэку в Лагере Барадин.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поддержание боевого духа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наши войска деморализованы, $n. Мы прилагаем все усилия, чтобы поддерживать в солдатах боевой дух, вот только главная составляющая успеха – ром – подходит к концу.$b$bПехотинцы с южного побережья докладывают, что в трюмах кораблей, затонувших у мыса Потерянной Надежды, хранится хороший запас рома. Не $gмог:могла; бы ты проверить, так ли это?$b$bПринеси весь ром, что сможешь найти.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вас попросили доставить 6 бочонков южноморского рома с кораблей, затонувших у мыса Потерянной Надежды. Мыс расположен севернее на береговой линии.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты достал ром? Я бы и сам сходил, да только панически боюсь воды. Не говоря уж о бешеной акуле...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Когда закончите, доложите о своих успехах начальнику лагеря Брэку в Лагере Барадин.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27973,'Щепки летят!','Ты уже $gбывал:бывала; на Верфи Веллсона, $n? Без особой нужды лучше держаться от нее подальше. К сожалению, именно туда тебе и придется пойти.$b$bВидишь ли, мы испытываем нехватку припасов с тех самых пор, как высадились на острове. На верфи находится много лесоматериалов, но обжившие ее призраки всякий раз мешают нам забрать их оттуда.$b$bТы не $gмог:могла; бы нам помочь?','Сержант Грей хочет, чтобы вы принесли 15 единиц лесоматериалов с Верфи Веллсона. Доски можно отнять у призраков, обитающих на верфи, или поднять с земли. Верфь находится на берегу к северо-западу отсюда.','Призраки отпугнули тебя?','Когда закончите, вернитесь к сержанту Грею в Лагерь Барадин.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Щепки летят!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты уже $gбывал:бывала; на Верфи Веллсона, $n? Без особой нужды лучше держаться от нее подальше. К сожалению, именно туда тебе и придется пойти.$b$bВидишь ли, мы испытываем нехватку припасов с тех самых пор, как высадились на острове. На верфи находится много лесоматериалов, но обжившие ее призраки всякий раз мешают нам забрать их оттуда.$b$bТы не $gмог:могла; бы нам помочь?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сержант Грей хочет, чтобы вы принесли 15 единиц лесоматериалов с Верфи Веллсона. Доски можно отнять у призраков, обитающих на верфи, или поднять с земли. Верфь находится на берегу к северо-западу отсюда.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Призраки отпугнули тебя?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Когда закончите, вернитесь к сержанту Грею в Лагерь Барадин.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27974,'Это наша земля','Неужели ты думаешь, что какая-то жалкая горстка воргенов сможет меня остановить?! Ха!$B$BКрепость Темного Клыка была владением Лордерона при жизни, так что, думаю, будет лишь справедливо, если в посмертии она перейдет во владение Отрекшихся. Годфри и его сообщники не представляют реальной угрозы. Это просто досадная помеха, которую мы без труда устраним. Они предали Темную Госпожу – и заплатят за это!$B$BЭшбери расположился на подступах к крепости – как будто специально напрашивается на то, чтобы его атаковали. Вот с него мы и начнем.','Убейте барона Эшбери.','Вернитесь к командиру ловчих смерти Бельмонту.','Первое задание было легким.','Барон Эшбери') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Это наша земля',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Неужели ты думаешь, что какая-то жалкая горстка воргенов сможет меня остановить?! Ха!$B$BКрепость Темного Клыка была владением Лордерона при жизни, так что, думаю, будет лишь справедливо, если в посмертии она перейдет во владение Отрекшихся. Годфри и его сообщники не представляют реальной угрозы. Это просто досадная помеха, которую мы без труда устраним. Они предали Темную Госпожу – и заплатят за это!$B$BЭшбери расположился на подступах к крепости – как будто специально напрашивается на то, чтобы его атаковали. Вот с него мы и начнем.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте барона Эшбери.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру ловчих смерти Бельмонту.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Первое задание было легким.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Барон Эшбери',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27975,'Разыскивается: начальник верфи Веллсон','Начальник верфи Веллсон докучает нам с тех самых пор, как мы попали на остров. На его верфи находится масса припасов, которые бы нам пригодились... если бы мы до них добрались.$b$bОн бдительно следит за своими подчиненными, что осложняет нашу задачу. Итак, я хочу, чтобы ты $gпокончил:покончила; с Веллсоном. Остерегайся солдат Орды, бесчинствующих в округе, $n.','Вам предстоит прикончить начальника верфи Веллсона. Верфь расположена к северо-западу отсюда, на западном побережье острова.','Когда закончите, вернитесь к сержанту Грею в Лагерь Барадин.','Когда-то великий человек, а нынче падший начальник пристани Веллсон.','Начальник верфи Веллсон') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разыскивается: начальник верфи Веллсон',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Начальник верфи Веллсон докучает нам с тех самых пор, как мы попали на остров. На его верфи находится масса припасов, которые бы нам пригодились... если бы мы до них добрались.$b$bОн бдительно следит за своими подчиненными, что осложняет нашу задачу. Итак, я хочу, чтобы ты $gпокончил:покончила; с Веллсоном. Остерегайся солдат Орды, бесчинствующих в округе, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вам предстоит прикончить начальника верфи Веллсона. Верфь расположена к северо-западу отсюда, на западном побережье острова.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Когда закончите, вернитесь к сержанту Грею в Лагерь Барадин.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Когда-то великий человек, а нынче падший начальник пристани Веллсон.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Начальник верфи Веллсон',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27976,'Будь прокляты эти толстые пальцы','К несчастью, из-за проблем с пальцами я уже не способен на столь меткие удары, как раньше. Виноват местный климат и низкое атмосферное давление – пальцы здесь отекают и становятся похожими на гигантские телcамарские кровяные колбаски... $b$bТак что придется тебе побегать по моим делам.$b$bПервое на повестке дня: вышибить дух из тяжелых боевых големов ущелья. Не задерживайся.','Убейте 12 тяжелых боевых големов.','Да ты отличный парень. У меня для тебя есть небольшой подарок.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Будь прокляты эти толстые пальцы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','К несчастью, из-за проблем с пальцами я уже не способен на столь меткие удары, как раньше. Виноват местный климат и низкое атмосферное давление – пальцы здесь отекают и становятся похожими на гигантские телcамарские кровяные колбаски... $b$bТак что придется тебе побегать по моим делам.$b$bПервое на повестке дня: вышибить дух из тяжелых боевых големов ущелья. Не задерживайся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 тяжелых боевых големов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да ты отличный парень. У меня для тебя есть небольшой подарок.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27977,'Самое важное','Найдите и верните фурму и подзорную трубу наблюдателя.','Фантастика!','Вернитесь к надсмотрщику Скренджу в Лагерь Братства Тория, что в Тлеющем ущелье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Самое важное',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите и верните фурму и подзорную трубу наблюдателя.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Фантастика!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к надсмотрщику Скренджу в Лагерь Братства Тория, что в Тлеющем ущелье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27978,'Охота за привидениями','Видишь гору за нашим лагерем? На ней находится Дозорный пункт Ларго, так что мы выбрали не лучшее место для пристанища. Мы отбиваемся от духов и призраков с того времени, как разбили тут лагерь.$b$bНе $gмог:могла; бы ты наведаться туда и дать им понять, что мы не собираемся никуда уходить? Убей несколько врагов, чтобы донести до них наше послание.$b$bБлагодарю за услугу, $n.','Вам нужно убить 14 любых призраков на Дозорном пункте Ларго к северо-востоку от лагеря.','Когда закончите, вернитесь к сержанту Грею в Лагерь Барадин.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота за привидениями',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Видишь гору за нашим лагерем? На ней находится Дозорный пункт Ларго, так что мы выбрали не лучшее место для пристанища. Мы отбиваемся от духов и призраков с того времени, как разбили тут лагерь.$b$bНе $gмог:могла; бы ты наведаться туда и дать им понять, что мы не собираемся никуда уходить? Убей несколько врагов, чтобы донести до них наше послание.$b$bБлагодарю за услугу, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вам нужно убить 14 любых призраков на Дозорном пункте Ларго к северо-востоку от лагеря.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Когда закончите, вернитесь к сержанту Грею в Лагерь Барадин.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (27979,'Темное министерство','Добудьте шар Киюби, шар Летерио и шар Финистра, а затем объедините их в сумеречный триоцит.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Темное министерство',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте шар Киюби, шар Летерио и шар Финистра, а затем объедините их в сумеречный триоцит.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27980,'Пауки должны уйти','С обычными пауками я могу справиться.$b$bГигантские стеклопутые пауки нравятся мне меньше, но они достаточно далеко, так что о них можно сильно не беспокоиться.$b$bНо лавовые пауки? <Лоло вздрагивает.> Лавовые пауки страшны... Это огромные пауки. Которые живут в лаве.$b$bМне только что заплатили за работу на прошлой неделе, и я охотно заплачу тебе, если ты убьешь этих чудовищ. Их полно по всему Тлеющему ущелью.','Убейте 9 лавовых пауков в Тлеющем ущелье.','Всех пауков, конечно, не истребишь, но ты определенно уменьшил их численность.$B$BПрекрасно. Вот то, что я тебе обещал. Не трать все сразу в одном месте. Если, конечно, это место не лагерь Братства Тория.','Вернитесь к капитану дозорных Лоло Долгобою в лагерь Братства Тория в Тлеющем ущелье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пауки должны уйти',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','С обычными пауками я могу справиться.$b$bГигантские стеклопутые пауки нравятся мне меньше, но они достаточно далеко, так что о них можно сильно не беспокоиться.$b$bНо лавовые пауки? <Лоло вздрагивает.> Лавовые пауки страшны... Это огромные пауки. Которые живут в лаве.$b$bМне только что заплатили за работу на прошлой неделе, и я охотно заплачу тебе, если ты убьешь этих чудовищ. Их полно по всему Тлеющему ущелью.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 9 лавовых пауков в Тлеющем ущелье.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Всех пауков, конечно, не истребишь, но ты определенно уменьшил их численность.$B$BПрекрасно. Вот то, что я тебе обещал. Не трать все сразу в одном месте. Если, конечно, это место не лагерь Братства Тория.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану дозорных Лоло Долгобою в лагерь Братства Тория в Тлеющем ущелье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (27981,'Непроходящий жар','Мы куем, плавим, прокаливаем все паучье мясо, какое у нас есть. И цыплят еще, если повезет. Я имею в виду, что вся эта работа требует очень много огня.$b$bХорошо, что мы тут прямо в центре огненного города.$b$bКонечно, самый лучший огонь – у элементалей. Их легко найти по всему Тлеющему ущелью, обычно недалеко от скоплений лавы. Вот, возьми вот эти колбы и наполни их огнем элементалей.$b$bАх, да, я сказал, что элементали при этом должны быть живыми?','Соберите 10 наполненных огнеупорных колб. Вы должны наполнять огнеупорные колбы из живых элементалей в Тлеющем ущелье.','Уууййй! Никогда не давай дворфу прямо в руки такое. Это же чистый огонь!$B$BТеперь мои руки распухнут еще больше…','Скользорук говорит, что скоро мы начнем делать из них огнебомбы. Еще одна причина, по которой нам нужны эти колбы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Непроходящий жар',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы куем, плавим, прокаливаем все паучье мясо, какое у нас есть. И цыплят еще, если повезет. Я имею в виду, что вся эта работа требует очень много огня.$b$bХорошо, что мы тут прямо в центре огненного города.$b$bКонечно, самый лучший огонь – у элементалей. Их легко найти по всему Тлеющему ущелью, обычно недалеко от скоплений лавы. Вот, возьми вот эти колбы и наполни их огнем элементалей.$b$bАх, да, я сказал, что элементали при этом должны быть живыми?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 наполненных огнеупорных колб. Вы должны наполнять огнеупорные колбы из живых элементалей в Тлеющем ущелье.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Уууййй! Никогда не давай дворфу прямо в руки такое. Это же чистый огонь!$B$BТеперь мои руки распухнут еще больше…',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Скользорук говорит, что скоро мы начнем делать из них огнебомбы. Еще одна причина, по которой нам нужны эти колбы.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27982,'Сумеречные ожерелья','Добудьте 20 сумеречных ожерелий.','Хм… издали эти драгоценные камни казались ярче. А при ближайшем рассмотрении оказались довольно тусклыми.$B$BА, ладно! Поплевать, потереть и все будет в порядке, а если нет, попрактикую на них распыление.','Заведу молот с рубиновой рукояткой... неплохая идея.','Вернитесь к мастеру-кузнецу Закалону в лагерь Братства Тория, что в Тлеющем ущелье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сумеречные ожерелья',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 20 сумеречных ожерелий.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хм… издали эти драгоценные камни казались ярче. А при ближайшем рассмотрении оказались довольно тусклыми.$B$BА, ладно! Поплевать, потереть и все будет в порядке, а если нет, попрактикую на них распыление.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Заведу молот с рубиновой рукояткой... неплохая идея.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру-кузнецу Закалону в лагерь Братства Тория, что в Тлеющем ущелье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27983,'Приключения Чурбана: маленькие злобные дворфы','Ну что ты делаешь? Зачем убиваешь?$b$bТебе нужно забрать у дворфов вещи? Чурбан понимает. Чурбан придумал лучше.$b$bСлушай: дерись с дворфом, но не убивай! Просто дерись, пока он не устанет. А потом Чурбан усыпит дворфа. Наверное, дворфы такие злые, потому что не спят.$b$bДавай! Доверься Чурбану.','Добейтесь того, чтобы 7 дворфов из клана Черного Железа ослабли и Чурбан смог их усыпить.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приключения Чурбана: маленькие злобные дворфы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну что ты делаешь? Зачем убиваешь?$b$bТебе нужно забрать у дворфов вещи? Чурбан понимает. Чурбан придумал лучше.$b$bСлушай: дерись с дворфом, но не убивай! Просто дерись, пока он не устанет. А потом Чурбан усыпит дворфа. Наверное, дворфы такие злые, потому что не спят.$b$bДавай! Доверься Чурбану.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добейтесь того, чтобы 7 дворфов из клана Черного Железа ослабли и Чурбан смог их усыпить.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (27984,'История Лунного Репья','Ты поможешь мне, $gсмертный:смертная;? Выслушай мою историю.','Послушайте историю Замеля.','Я примирился со своей судьбой здесь, в этой клетке. Но молитва должна быть найдена.','История Замеля','Вернитесь к Замелю Лунному Репью на Гряду Огненной стражи в Тлеющее ущелье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','История Лунного Репья',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты поможешь мне, $gсмертный:смертная;? Выслушай мою историю.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Послушайте историю Замеля.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я примирился со своей судьбой здесь, в этой клетке. Но молитва должна быть найдена.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','История Замеля',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Замелю Лунному Репью на Гряду Огненной стражи в Тлеющее ущелье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (27985,'Молитва к Элуне','Ты поможешь мне, $gсмертный:смертная;? Ты отыщешь молитву к Элуне?$B$BКак я говорил, молитва выгравирована на золотой табличке. Думаю, они спрятали ее в одном из своих отвратительных сундуков, которые стоят у входа в пещеру, в нижней части гряды.$b$bЕсли ты найдешь мою молитву, не приноси ее мне. Лучше прочитай ее.$b$bЯ совершил столько грехов, что, возможно, просить отпущения – это слишком с моей стороны. Но я не перестану надеяться.','Найдите и прочитайте молитву к Элуне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Молитва к Элуне',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты поможешь мне, $gсмертный:смертная;? Ты отыщешь молитву к Элуне?$B$BКак я говорил, молитва выгравирована на золотой табличке. Думаю, они спрятали ее в одном из своих отвратительных сундуков, которые стоят у входа в пещеру, в нижней части гряды.$b$bЕсли ты найдешь мою молитву, не приноси ее мне. Лучше прочитай ее.$b$bЯ совершил столько грехов, что, возможно, просить отпущения – это слишком с моей стороны. Но я не перестану надеяться.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите и прочитайте молитву к Элуне.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27986,'У горного владыки','У Братства Тория нет ополчения – только я да несколько стражников, вот и все. И если мы собираемся победить клан Черного Железа здесь в ущелье, нам понадобится помощь.$b$bГорный владыка Рендан засел наверху вон той башни на другой стороне ущелья, к югу отсюда. Сектантов Сумеречного Молота или огненных элементалей он не поддерживает, но и к нашему Братству не присоединился. Возможно, настало время нанести ему визит. С его помощью у нас будет больше возможностей.','Поговорите с горным владыкой Ренданом на Железной вершине, что в Тлеющем ущелье.','А ты кто такой?$B$BАх, да, посланник Братства Тория. Им нужна моя поддержка? Ладно, возможно, я и помогу…$B$B…за вознаграждение.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','У горного владыки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У Братства Тория нет ополчения – только я да несколько стражников, вот и все. И если мы собираемся победить клан Черного Железа здесь в ущелье, нам понадобится помощь.$b$bГорный владыка Рендан засел наверху вон той башни на другой стороне ущелья, к югу отсюда. Сектантов Сумеречного Молота или огненных элементалей он не поддерживает, но и к нашему Братству не присоединился. Возможно, настало время нанести ему визит. С его помощью у нас будет больше возможностей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с горным владыкой Ренданом на Железной вершине, что в Тлеющем ущелье.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А ты кто такой?$B$BАх, да, посланник Братства Тория. Им нужна моя поддержка? Ладно, возможно, я и помогу…$B$B…за вознаграждение.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27987,'Пушечное ядро!','Ларго со своими проходимцами воруют наши боеприпасы с тех самых пор, как мы разбили тут лагерь. Это крайне раздражает.$b$bНам донесли, что Ларго складирует пушечные ядра в башнях, стоящих над водой на его Дозорном пункте. Достанешь нам немного ядер?$b$b$n, остерегайся представителей Орды.','Соберите для сержанта Грея 4 груды пушечных ядер, хранящихся на Дозорном пункте Ларго. Он находится к северо-востоку от лагеря.','Когда закончите, вернитесь к сержанту Грею в Лагерь Барадин.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пушечное ядро!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ларго со своими проходимцами воруют наши боеприпасы с тех самых пор, как мы разбили тут лагерь. Это крайне раздражает.$b$bНам донесли, что Ларго складирует пушечные ядра в башнях, стоящих над водой на его Дозорном пункте. Достанешь нам немного ядер?$b$b$n, остерегайся представителей Орды.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите для сержанта Грея 4 груды пушечных ядер, хранящихся на Дозорном пункте Ларго. Он находится к северо-востоку от лагеря.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Когда закончите, вернитесь к сержанту Грею в Лагерь Барадин.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27988,'Чума... Чума повсюду!','У этой чумы есть одно замечательное свойство – даже если она вроде бы отступает, все равно остается скрытая зараза, обладающая немалой губительной силой. Но кое с кем придется разбираться без помощи чумы: я говорю о прихвостнях Годфри.$B$BПохоже, духи, служившие барону Сильверлейну и командиру Спрингвейлу при жизни, теперь охраняют хозяев и после смерти, а Годфри использует их против нас. Покажи этим мерзавцам, что такое железная воля Отрекшихся!','Убейте барона Сильверлейна и командира Спрингвейла.','У Кромуша крепкий череп без мозгов – как говорится, сплошная кость, и нам это на руку. К тому времени, когда все поймут, насколько губительная чума, будет уже слишком поздно.$B$BКстати, спасибо, что молчал пока он разглагольствовал. Тебе это зачтется.','Вернитесь к командиру ловчих смерти Бельмонту.','Этого мы никак не ожидали.','Командир Спрингвейл') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чума... Чума повсюду!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У этой чумы есть одно замечательное свойство – даже если она вроде бы отступает, все равно остается скрытая зараза, обладающая немалой губительной силой. Но кое с кем придется разбираться без помощи чумы: я говорю о прихвостнях Годфри.$B$BПохоже, духи, служившие барону Сильверлейну и командиру Спрингвейлу при жизни, теперь охраняют хозяев и после смерти, а Годфри использует их против нас. Покажи этим мерзавцам, что такое железная воля Отрекшихся!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте барона Сильверлейна и командира Спрингвейла.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','У Кромуша крепкий череп без мозгов – как говорится, сплошная кость, и нам это на руку. К тому времени, когда все поймут, насколько губительная чума, будет уже слишком поздно.$B$BКстати, спасибо, что молчал пока он разглагольствовал. Тебе это зачтется.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру ловчих смерти Бельмонту.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Этого мы никак не ожидали.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Командир Спрингвейл',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27989,'Роумбо просит меда','Роумбо голодный!$b$bНегодяи из Оскверненного леса украли весь мед племени Древобрюхов! Мы видели... ээ... Роумбо видел, как они это делали! А теперь Роумбо нужен этот мед!$b$bВозьми эту... эту палку! Да, эту палку. Возьми эту палку и с ее помощью укради мед из их ульев в Деревне Мертвого Леса.$b$bРоумбо нужно как можно больше меда. Это очень важно.','Соберите 10 порций меда Деревни Мертвого Леса из ульев Деревни Мертвого Леса, используя медовую палочку Роумбо.','Вернитесь к тотему Роумбо в Деревню Мертвого Леса, что в Оскверненном лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Роумбо просит меда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Роумбо голодный!$b$bНегодяи из Оскверненного леса украли весь мед племени Древобрюхов! Мы видели... ээ... Роумбо видел, как они это делали! А теперь Роумбо нужен этот мед!$b$bВозьми эту... эту палку! Да, эту палку. Возьми эту палку и с ее помощью укради мед из их ульев в Деревне Мертвого Леса.$b$bРоумбо нужно как можно больше меда. Это очень важно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 порций меда Деревни Мертвого Леса из ульев Деревни Мертвого Леса, используя медовую палочку Роумбо.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к тотему Роумбо в Деревню Мертвого Леса, что в Оскверненном лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27990,'Зона боевых действий','Ты еще один возможность доказывайт свой польза, |3-6($r).$B$BРезультат этот швах мы остаться без раз-два-три канонир.$B$BТы мочь заменяйт один?$B$BМои танк стоять запад лагерь. Марш-марш там и делать порядок!','Командир Шнотц приказывает вам занять место канонира в одном из осадных танков и разобраться с 7 дряхлыми стражами, а затем вернуться к нему.','Ай-ай-ай!$B$BМне дюйм-два высота выше – капут!','Поговорите с командиром Шнотцем в лагере Шнотца.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зона боевых действий',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты еще один возможность доказывайт свой польза, |3-6($r).$B$BРезультат этот швах мы остаться без раз-два-три канонир.$B$BТы мочь заменяйт один?$B$BМои танк стоять запад лагерь. Марш-марш там и делать порядок!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Командир Шнотц приказывает вам занять место канонира в одном из осадных танков и разобраться с 7 дряхлыми стражами, а затем вернуться к нему.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ай-ай-ай!$B$BМне дюйм-два высота выше – капут!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с командиром Шнотцем в лагере Шнотца.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27991,'Освобождение дозорной башни','Существует единственный вариант захватить Дозорный пункт Ларго.$b$bВ последнее время парень окончательно спятил: стоит себе на вершине башни и ждет, когда приплывет воображаемый флот. Так что найти его не составит труда.','Сержант Грей поручил вам ликвидировать Командира Ларго на Дозорном пункте Ларго. Это место находится к северо-востоку от лагеря.','Когда закончите, вернитесь к сержанту Грею в Лагерь Барадин.','Попробуй с ним справиться!','Командир Ларго') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Освобождение дозорной башни',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Существует единственный вариант захватить Дозорный пункт Ларго.$b$bВ последнее время парень окончательно спятил: стоит себе на вершине башни и ждет, когда приплывет воображаемый флот. Так что найти его не составит труда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сержант Грей поручил вам ликвидировать Командира Ларго на Дозорном пункте Ларго. Это место находится к северо-востоку от лагеря.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Когда закончите, вернитесь к сержанту Грею в Лагерь Барадин.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Попробуй с ним справиться!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Командир Ларго',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (27992,'Как работают магниты?','На остров сложно доставить полезные запчасти, $n. Мы пытались на месте починить сломанные осадные машины, но у нас закончились необходимые детали.$b$bИз второго полка доложили об искореженных осадных машинах, стоящих на заброшенном поле боя к западу отсюда. Может быть, там остались какие-то пригодные запчасти?$b$bСложно будет отыскать что-то в груде обломков, так что возьми-ка этот намагниченный сборщик металлолома и воспользуйся им.','Вам поручили собрать 7 фрагментов осадных машин. Используйте намагниченный сборщик металлолома на Передовой Неупокоенных, расположенной на западе за вторым мостом.','Ну что, помог ли тебе намагниченный сборщик металлолома?','Доложите лейтенанту Фарнсворту в Лагере Барадин о завершении задания.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Как работают магниты?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На остров сложно доставить полезные запчасти, $n. Мы пытались на месте починить сломанные осадные машины, но у нас закончились необходимые детали.$b$bИз второго полка доложили об искореженных осадных машинах, стоящих на заброшенном поле боя к западу отсюда. Может быть, там остались какие-то пригодные запчасти?$b$bСложно будет отыскать что-то в груде обломков, так что возьми-ка этот намагниченный сборщик металлолома и воспользуйся им.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вам поручили собрать 7 фрагментов осадных машин. Используйте намагниченный сборщик металлолома на Передовой Неупокоенных, расположенной на западе за вторым мостом.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, помог ли тебе намагниченный сборщик металлолома?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доложите лейтенанту Фарнсворту в Лагере Барадин о завершении задания.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27993,'Задай им перцу!','Едва ушли, |3-6($c)... Ох, душа у меня будет не на месте, если мы не зададим этим налетчикам по первое число!$B$BВозвращайся-ка к гробнице Хартута и покажи этим засланцам, где раки зимуют!$B$BЭто на северо-востоке прямо за входом в Ульдум, если мне память не изменяет.$B$BЧего смотришь-то? Мне сейчас такое точно не сдюжить!','Мак отправляет вас исследовать гробницу Хартута.','Обратитесь к Харрисону Джонсу у гробницы Хартута.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Задай им перцу!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Едва ушли, |3-6($c)... Ох, душа у меня будет не на месте, если мы не зададим этим налетчикам по первое число!$B$BВозвращайся-ка к гробнице Хартута и покажи этим засланцам, где раки зимуют!$B$BЭто на северо-востоке прямо за входом в Ульдум, если мне память не изменяет.$B$BЧего смотришь-то? Мне сейчас такое точно не сдюжить!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Мак отправляет вас исследовать гробницу Хартута.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Обратитесь к Харрисону Джонсу у гробницы Хартута.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (27995,'Танец для Роумбо!','Ты отлично $gсправился:справилась;, |3-6($r)! Роумбо доволен твоей храбростью и тем вкусным медом, который ты $gпринес:принесла;.$b$bА теперь ты $gдолжен:должна;... $gдолжен:должна; танцевать! Да!$b$bТанцуй для Роумбо! Танцуй!','Исполните для Роумбо глупый танец.','Эти ребятишки… я должен был догадаться! Они были достаточно сообразительными, чтобы прятаться всякий раз, когда я приходил проверить тотем.$B$BНайду – притащу их в Крепость Древобрюхов за уши! Спасибо, что заглянул в тотем…','Вернитесь к Гразлу в Изумрудное святилище и расскажите ему о том, что произошло.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Танец для Роумбо!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты отлично $gсправился:справилась;, |3-6($r)! Роумбо доволен твоей храбростью и тем вкусным медом, который ты $gпринес:принесла;.$b$bА теперь ты $gдолжен:должна;... $gдолжен:должна; танцевать! Да!$b$bТанцуй для Роумбо! Танцуй!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Исполните для Роумбо глупый танец.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Эти ребятишки… я должен был догадаться! Они были достаточно сообразительными, чтобы прятаться всякий раз, когда я приходил проверить тотем.$B$BНайду – притащу их в Крепость Древобрюхов за уши! Спасибо, что заглянул в тотем…',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гразлу в Изумрудное святилище и расскажите ему о том, что произошло.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27996,'Твое время вышло!','Как ты понимаешь, мы вовсе не собираемся слушать, что Кромуш говорит о чуме. Но его грубая сила очень нам пригодится, когда придется сражаться с Годфри и его многочисленными приспешниками. Самый сильный из них, лорд Вальден, первый помощник Годфри, его правая рука.$B$BТвоя задача – прикончить Вальдена. Когда все сделаешь, встретимся в его покоях. И вот тогда крепость Темного Клыка наконец перейдет в руки Отрекшихся!','Убейте лорда Вальдена.','Ну все, Годфри, твое время вышло!','Вернитесь к командиру ловчих смерти Бельмонту.','Он даже не успеет понять, что его погубило.','Лорд Вальден') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Твое время вышло!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как ты понимаешь, мы вовсе не собираемся слушать, что Кромуш говорит о чуме. Но его грубая сила очень нам пригодится, когда придется сражаться с Годфри и его многочисленными приспешниками. Самый сильный из них, лорд Вальден, первый помощник Годфри, его правая рука.$B$BТвоя задача – прикончить Вальдена. Когда все сделаешь, встретимся в его покоях. И вот тогда крепость Темного Клыка наконец перейдет в руки Отрекшихся!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте лорда Вальдена.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну все, Годфри, твое время вышло!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру ловчих смерти Бельмонту.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Он даже не успеет понять, что его погубило.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Лорд Вальден',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (27997,'Вред Нефритового Пламени','Очищение этого леса – нелегкая работа. Стоит нам в чем-то добиться успеха, как появляются новые проблемы.$b$bСатиры из племени Нефритового Пламени – это сущее наказание. Как мы хотим очистить этот лес, так они хотят его осквернить. Сейчас мы предпринимаем некоторые шаги для того, чтобы окончательно изгнать их из Оскверненного леса.$b$bОтправляйся на запад, в Долину Нефритового Пламени и очисти лес от их присутствия. Вход в Долину находится севернее стен Деревни Мертвого Леса. Ищи их мерзкие знамена.','Убейте 12 сатиров или скверноподданных из племени Нефритового Пламени в Долине Нефритового Пламени.','Вернитесь к Тенеллу Листогону в Изумрудное святилище, что в Оскверненном лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вред Нефритового Пламени',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Очищение этого леса – нелегкая работа. Стоит нам в чем-то добиться успеха, как появляются новые проблемы.$b$bСатиры из племени Нефритового Пламени – это сущее наказание. Как мы хотим очистить этот лес, так они хотят его осквернить. Сейчас мы предпринимаем некоторые шаги для того, чтобы окончательно изгнать их из Оскверненного леса.$b$bОтправляйся на запад, в Долину Нефритового Пламени и очисти лес от их присутствия. Вход в Долину находится севернее стен Деревни Мертвого Леса. Ищи их мерзкие знамена.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 сатиров или скверноподданных из племени Нефритового Пламени в Долине Нефритового Пламени.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тенеллу Листогону в Изумрудное святилище, что в Оскверненном лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (27998,'Сладкая, беспощадная месть','Если все будет нормально, ты сможешь войти прямо в личные владения Годфри и взять награду, достойную $gстоль отважного и рьяного:столь отважной и рьяной:c; |3-1($c).$B$BОднако Годфри хитер и коварен, так что тебе лучше поторопиться. На всякий случай. Вдруг твоя помощь понадобится где-то еще! Он дорого заплатит за то, что сделал с Темной Госпожой!','Убейте лорда Годфри.','Вернитесь к командиру ловчих смерти Бельмонту.','За Сильвану!','Лорд Годфри') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сладкая, беспощадная месть',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если все будет нормально, ты сможешь войти прямо в личные владения Годфри и взять награду, достойную $gстоль отважного и рьяного:столь отважной и рьяной:c; |3-1($c).$B$BОднако Годфри хитер и коварен, так что тебе лучше поторопиться. На всякий случай. Вдруг твоя помощь понадобится где-то еще! Он дорого заплатит за то, что сделал с Темной Госпожой!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте лорда Годфри.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру ловчих смерти Бельмонту.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','За Сильвану!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Лорд Годфри',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27999,'Судьба Дойлов','Похоже, этот бой стал последним для Дойлов. Нужно сообщить Иэну об их судьбе.','Вернитесь на Кладбище Огнебородов и сообщите Иэну Огнебороду о судьбе клана Дойлов.','Так жаль. Эти ребята были страшно упрямые – но в бою их упрямство превращается в упорство. От таких союзников я бы не отказался.$B$BКогда все закончится, нужно будет послать за ними наших ребят, чтобы устроить подобающие похороны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Судьба Дойлов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Похоже, этот бой стал последним для Дойлов. Нужно сообщить Иэну об их судьбе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь на Кладбище Огнебородов и сообщите Иэну Огнебороду о судьбе клана Дойлов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так жаль. Эти ребята были страшно упрямые – но в бою их упрямство превращается в упорство. От таких союзников я бы не отказался.$B$BКогда все закончится, нужно будет послать за ними наших ребят, чтобы устроить подобающие похороны.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28000,'Сделать невозможное','Сатиры окружают свои лунные колодцы барьерами из демонического огня, сквозь которые невозможно пройти. Но им наверняка известен способ, как пробраться через этот огонь.$b$bСпрашивать у сатиров бесполезно, а вот с бесами, которые имеют с ними дело, договориться гораздо проще. Я тут подумала об одном из них...$b$bВ предгорьях к востоку отсюда, отдельно от остальных демонов бродит одинокий бес. Его одолеть несложно. Напади на него, дождись, когда он ослабеет, а потом воспользуйся заколдованным мешком, чтобы его схватить. Затем я его допрошу...','Сделайте так, чтобы Бесенок ослаб, а затем поймайте его при помощи заколдованного бесовского мешка.','Бесы – хитрые создания. Раз их появилось так много на Гряде Затаившейся Тьмы, то я уверена, что там что-то есть.$B$BНаш маленький друг расскажет нам, где это искать… Если, конечно, он не хочет обратно в мешок.','Вернитесь к чародейке Деларис в руины Констелласа, что в Оскверненном лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сделать невозможное',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сатиры окружают свои лунные колодцы барьерами из демонического огня, сквозь которые невозможно пройти. Но им наверняка известен способ, как пробраться через этот огонь.$b$bСпрашивать у сатиров бесполезно, а вот с бесами, которые имеют с ними дело, договориться гораздо проще. Я тут подумала об одном из них...$b$bВ предгорьях к востоку отсюда, отдельно от остальных демонов бродит одинокий бес. Его одолеть несложно. Напади на него, дождись, когда он ослабеет, а потом воспользуйся заколдованным мешком, чтобы его схватить. Затем я его допрошу...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сделайте так, чтобы Бесенок ослаб, а затем поймайте его при помощи заколдованного бесовского мешка.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Бесы – хитрые создания. Раз их появилось так много на Гряде Затаившейся Тьмы, то я уверена, что там что-то есть.$B$BНаш маленький друг расскажет нам, где это искать… Если, конечно, он не хочет обратно в мешок.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к чародейке Деларис в руины Констелласа, что в Оскверненном лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (28001,'Удел труса','Здесь мы в безопасности – однако множество кланов Громового Молота нуждается в помощи. Наш отряд всадников на грифонах мог бы поддержать их, однако если мы хотим окончательно уничтожить Сумеречный Молот, нам понадобится подкрепление.$B$BЯ собираюсь потолковать об этом с Колином Громтаром. Думаю, он не откажет мне в помощи – ведь только трус может отвернуться от своего народа, особенно в такую тяжелую минуту.$B$BИди в Громтар, разыщи Колина и потребуй от него объяснений. Я не потерплю, чтобы кланами Громового Молота командовали трусы.','Идите в Громтар и поговорите с Колином Громтаром.','ЧТО?! ОН НАЗВАЛ МЕНЯ ТРУСОМ?!$B$BКак это похоже на Огнебородов – сплошное бахвальство и ни капли здравого смысла. С юга напирает Драконья Пасть, я один отражаю набеги орков, Громтар лежит в руинах – и что? Хоть один клан пришел мне на выручку? Нет! Старина Громтар действует в одиночку, и уж поверь мне, я выбиваюсь из сил, пытаясь сдержать натиск врага.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Удел труса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Здесь мы в безопасности – однако множество кланов Громового Молота нуждается в помощи. Наш отряд всадников на грифонах мог бы поддержать их, однако если мы хотим окончательно уничтожить Сумеречный Молот, нам понадобится подкрепление.$B$BЯ собираюсь потолковать об этом с Колином Громтаром. Думаю, он не откажет мне в помощи – ведь только трус может отвернуться от своего народа, особенно в такую тяжелую минуту.$B$BИди в Громтар, разыщи Колина и потребуй от него объяснений. Я не потерплю, чтобы кланами Громового Молота командовали трусы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Идите в Громтар и поговорите с Колином Громтаром.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','ЧТО?! ОН НАЗВАЛ МЕНЯ ТРУСОМ?!$B$BКак это похоже на Огнебородов – сплошное бахвальство и ни капли здравого смысла. С юга напирает Драконья Пасть, я один отражаю набеги орков, Громтар лежит в руинах – и что? Хоть один клан пришел мне на выручку? Нет! Старина Громтар действует в одиночку, и уж поверь мне, я выбиваюсь из сил, пытаясь сдержать натиск врага.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28002,'Антикризисное управление','Возникла деликатная ситуация, необходим... объективный взгляд со стороны.$B$BНекоторые гости несколько обеспокоены произошедшим инцидентом. Правда, этим уже занялись наши лучшие бойцы.$B$BА ты пока успокой наших самых щепетильных визитеров.$B$BЕсли справишься, я доложу о тебе на самый верх!','Беллок Сияющий Клинок хочет, чтобы вы успокоили гостей в лагере Шнотца.','Хм, все никак не придут в себя, да?$B$BНу, как говорится, время лечит любые раны.$B$BХотя посланника-то уже не вылечишь, конечно...','Поговорите с Беллоком Сияющим Клинком в лагере Шнотца.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Антикризисное управление',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Возникла деликатная ситуация, необходим... объективный взгляд со стороны.$B$BНекоторые гости несколько обеспокоены произошедшим инцидентом. Правда, этим уже занялись наши лучшие бойцы.$B$BА ты пока успокой наших самых щепетильных визитеров.$B$BЕсли справишься, я доложу о тебе на самый верх!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Беллок Сияющий Клинок хочет, чтобы вы успокоили гостей в лагере Шнотца.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хм, все никак не придут в себя, да?$B$BНу, как говорится, время лечит любые раны.$B$BХотя посланника-то уже не вылечишь, конечно...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Беллоком Сияющим Клинком в лагере Шнотца.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (28003,'Требуются герои: Огненная Пропасть','По повелению вождя всем отважным искателям приключений надлежит явиться в Огненную Пропасть, что под Оргриммаром!$B$BПламенеющий Клинок может напасть на город в любую минуту, и городская стража долго не выстоит! Всем, кто отважится, велено спуститься в Огненную Пропасть и доложить командующему силами сопротивления каменному стражу Курджаку. Устраните угрозу Оргриммару раз и навсегда!','Поговорите с каменным стражем Курджаком.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Требуются герои: Огненная Пропасть',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','По повелению вождя всем отважным искателям приключений надлежит явиться в Огненную Пропасть, что под Оргриммаром!$B$BПламенеющий Клинок может напасть на город в любую минуту, и городская стража долго не выстоит! Всем, кто отважится, велено спуститься в Огненную Пропасть и доложить командующему силами сопротивления каменному стражу Курджаку. Устраните угрозу Оргриммару раз и навсегда!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с каменным стражем Курджаком.',`objectives_loc8`);
