INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (28010,'Требуются герои: Непроглядная Пучина','По повелению вождя всем отважным искателям приключений надлежит явиться в Непроглядную Пучину, что к северу от заставы Зорам\'гар!$b$bТам собрались служители культа Сумеречного Молота, действия которых угрожают всему миру! Если вы решите откликнуться на этот призыв, отправляйтесь в Непроглядную Пучину и поговорите с Дже\'неу Санкри, одним из Служителей Земли. Помогите справиться с угрозой Сумеречного Молота.','Поговорите с Дже\'неу Санкри.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Требуются герои: Непроглядная Пучина',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','По повелению вождя всем отважным искателям приключений надлежит явиться в Непроглядную Пучину, что к северу от заставы Зорам\'гар!$b$bТам собрались служители культа Сумеречного Молота, действия которых угрожают всему миру! Если вы решите откликнуться на этот призыв, отправляйтесь в Непроглядную Пучину и поговорите с Дже\'неу Санкри, одним из Служителей Земли. Помогите справиться с угрозой Сумеречного Молота.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Дже\'неу Санкри.',`objectives_loc8`);
