INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (28016,'Требуются герои: Кладбище Монастыря Алого Ордена','По повелению вождя всем отважным искателям приключений надлежит явиться на Кладбище Монастыря Алого ордена, что находится к северо-востоку от Подгорода!$B$BТемный следопыт Велонара просит о подкреплении, чтобы начать штурм! Если вы решите откликнуться на этот призыв, отправляйтесь на Кладбище Монастыря Алого ордена и обратитесь к темному следопыту Велонаре, зарекомендовавшей себя как умелого стратега, чтобы сыграть свою роль в противоборстве с орденом.','Поговорите с темным следопытом Велонарой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Требуются герои: Кладбище Монастыря Алого Ордена',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','По повелению вождя всем отважным искателям приключений надлежит явиться на Кладбище Монастыря Алого ордена, что находится к северо-востоку от Подгорода!$B$BТемный следопыт Велонара просит о подкреплении, чтобы начать штурм! Если вы решите откликнуться на этот призыв, отправляйтесь на Кладбище Монастыря Алого ордена и обратитесь к темному следопыту Велонаре, зарекомендовавшей себя как умелого стратега, чтобы сыграть свою роль в противоборстве с орденом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с темным следопытом Велонарой.',`objectives_loc8`);
