INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (28020,'Требуются герои: Кладбище Монастыря Алого ордена','По повелению короля Вариана Ринна всем отважным искателям приключений надлежит явиться на Кладбище Монастыря Алого ордена, что находится к северо-востоку от Подгорода!$B$BБывший рыцарь Джозеф Беспокойный просит о помощи в борьбе с лидерами Алого ордена и преобразовании последнего! Если вы решите откликнуться на этот призыв, отправляйтесь на Кладбище Монастыря Алого ордена, обратитесь к Джозефу Беспокойному и сыграйте свою роль в судьбе ордена.','Поговорите с Джозефом Беспокойным.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Требуются герои: Кладбище Монастыря Алого ордена',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','По повелению короля Вариана Ринна всем отважным искателям приключений надлежит явиться на Кладбище Монастыря Алого ордена, что находится к северо-востоку от Подгорода!$B$BБывший рыцарь Джозеф Беспокойный просит о помощи в борьбе с лидерами Алого ордена и преобразовании последнего! Если вы решите откликнуться на этот призыв, отправляйтесь на Кладбище Монастыря Алого ордена, обратитесь к Джозефу Беспокойному и сыграйте свою роль в судьбе ордена.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Джозефом Беспокойным.',`objectives_loc8`);
