INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (28022,'Требуются герои: Оружейная Монастыря Алого ордена','По повелению короля Вариана Ринна всем отважным искателям приключений надлежит явиться в Оружейную Монастыря Алого ордена, что находится к северо-востоку от Подгорода!$B$BДжозеф Безумный просит о помощи в расправе с Иродом, героем Алого ордена! Если вы решите откликнуться на этот призыв, отправляйтесь в Оружейную Монастыря Алого ордена и обратитесь к Джозефу Безумному, чтобы оказать ему помощь.','Поговорите с Джозефом Безумным.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Требуются герои: Оружейная Монастыря Алого ордена',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','По повелению короля Вариана Ринна всем отважным искателям приключений надлежит явиться в Оружейную Монастыря Алого ордена, что находится к северо-востоку от Подгорода!$B$BДжозеф Безумный просит о помощи в расправе с Иродом, героем Алого ордена! Если вы решите откликнуться на этот призыв, отправляйтесь в Оружейную Монастыря Алого ордена и обратитесь к Джозефу Безумному, чтобы оказать ему помощь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Джозефом Безумным.',`objectives_loc8`);
