INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (28024,'Требуются герои: Курганы Иглошкурых','По повелению короля Вариана Ринна всем отважным искателям приключений надлежит явиться к Курганам Иглошкурых в Тысяче Игл!$B$BПремудрой Користразе нужна помощь, чтобы остановить нечистый альянс Плети и свинобразов! Если вы решите откликнуться на этот призыв, отправляйтесь к Курганам Иглошкурых и окажите Користразе всемерную поддержку.','Поговорите с Користразой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Требуются герои: Курганы Иглошкурых',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','По повелению короля Вариана Ринна всем отважным искателям приключений надлежит явиться к Курганам Иглошкурых в Тысяче Игл!$B$BПремудрой Користразе нужна помощь, чтобы остановить нечистый альянс Плети и свинобразов! Если вы решите откликнуться на этот призыв, отправляйтесь к Курганам Иглошкурых и окажите Користразе всемерную поддержку.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Користразой.',`objectives_loc8`);
