INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (28026,'Требуются герои: Ульдаман','Поговорите с главным дознавателем Тей\'теланом Кровавым Взором.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Требуются герои: Ульдаман',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с главным дознавателем Тей\'теланом Кровавым Взором.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (28027,'Требуются герои: Ульдаман','По повелению короля Вариана Ринна всем отважным искателям приключений надлежит явиться в Ульдаман, что в Бесплодных землях!$B$BЛиге исследователей под руководством старшего геолога Дардина нужна помощь бесстрашных и умелых воинов. Погоня за знаниями нередко сопровождается опасностями! Подчас смертельными... Если вы решите откликнуться на этот призыв, отправляйтесь в Ульдаман и поговорите со старшим геологом Дардином. Думаю, он найдет вам работу.','Поговорите со старшим геологом Дардином.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Требуются герои: Ульдаман',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','По повелению короля Вариана Ринна всем отважным искателям приключений надлежит явиться в Ульдаман, что в Бесплодных землях!$B$BЛиге исследователей под руководством старшего геолога Дардина нужна помощь бесстрашных и умелых воинов. Погоня за знаниями нередко сопровождается опасностями! Подчас смертельными... Если вы решите откликнуться на этот призыв, отправляйтесь в Ульдаман и поговорите со старшим геологом Дардином. Думаю, он найдет вам работу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите со старшим геологом Дардином.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (28028,'Осада!','Худшего времени, чтобы попросить меня вступить в бой, надзиратель Скользорук выбрать не мог. Эту вершину и так уже осаждает неприятель!$b$bМои ребята справятся с чем угодно, но все же мне будет нелегко вот так взять и послать несколько дворфов в это дьявольское ущелье.$b$bВот что я тебе скажу: если справишься со стрелками, которые окружили нашу крепость, я рассмотрю твое предложение. Их целая уйма на равнине к востоку отсюда.','Убейте 9 стрелков из клана Черного Железа.','Вернитесь к горному владыке Рендану на Железную вершину в Тлеющем ущелье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Осада!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Худшего времени, чтобы попросить меня вступить в бой, надзиратель Скользорук выбрать не мог. Эту вершину и так уже осаждает неприятель!$b$bМои ребята справятся с чем угодно, но все же мне будет нелегко вот так взять и послать несколько дворфов в это дьявольское ущелье.$b$bВот что я тебе скажу: если справишься со стрелками, которые окружили нашу крепость, я рассмотрю твое предложение. Их целая уйма на равнине к востоку отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 9 стрелков из клана Черного Железа.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к горному владыке Рендану на Железную вершину в Тлеющем ущелье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (28029,'Задай им жару!','Не знаю, $gзаметил:заметила; ли ты, но мои башни гораздо выше любых других башен ущелья. Некоторые дворфы гордятся тем, как глубоко они копают, но только не я. Иногда мне кажется, что я должен был родиться в клане Громового Молота.$b$bТем не менее, мне не очень нравится, как выглядят те, другие башни. Растут, понимаешь ли, догоняют мои. Вот, возьми этот факел и подожги с его помощью жаровни наверху тех башен. Они еще пожалеют, что вообще построили их.','При помощи факела воздаяния подожгите четыре башни, окружающие Котлован.','Вернитесь к горному владыке Рендану на Железную вершину в Тлеющем ущелье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Задай им жару!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не знаю, $gзаметил:заметила; ли ты, но мои башни гораздо выше любых других башен ущелья. Некоторые дворфы гордятся тем, как глубоко они копают, но только не я. Иногда мне кажется, что я должен был родиться в клане Громового Молота.$b$bТем не менее, мне не очень нравится, как выглядят те, другие башни. Растут, понимаешь ли, догоняют мои. Вот, возьми этот факел и подожги с его помощью жаровни наверху тех башен. Они еще пожалеют, что вообще построили их.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','При помощи факела воздаяния подожгите четыре башни, окружающие Котлован.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к горному владыке Рендану на Железную вершину в Тлеющем ущелье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28030,'Пули у них отменные','По крайней мере одну вещь эти роющиеся в ущелье дворфы делают правильно: пули у них превосходные. У меня не получается добиться такого же качества, поэтому я привык воровать их пули, все, какие найду.$b$bХочешь, чтобы я помог тебе? Принеси мне пару сотен пуль от этих стрелков внизу.$b$bУверен, они охотно поделятся с тобой пулями, отдавая их по одной, но если ты найдешь целые ящики – получится быстрее.','Соберите 200 пуль Черного Железа.','Раздам их стражникам. Премного благодарен.','Вернитесь к горному владыке Рендану на Железную вершину в Тлеющем ущелье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пули у них отменные',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','По крайней мере одну вещь эти роющиеся в ущелье дворфы делают правильно: пули у них превосходные. У меня не получается добиться такого же качества, поэтому я привык воровать их пули, все, какие найду.$b$bХочешь, чтобы я помог тебе? Принеси мне пару сотен пуль от этих стрелков внизу.$b$bУверен, они охотно поделятся с тобой пулями, отдавая их по одной, но если ты найдешь целые ящики – получится быстрее.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 200 пуль Черного Железа.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Раздам их стражникам. Премного благодарен.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к горному владыке Рендану на Железную вершину в Тлеющем ущелье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (28031,'Особая посылка для Бривельверпа','У меня новый деловой партнер – мой лучший друг Бривельверп. Пока мы тут лясы точим, он закладывает фундамент нашей новой империи мороженого!$B$BБривельверп отвел наш холодильный буксир, оборудование и рабочих на юго-запад, к Затопленным раскопкам. К сожалению, у меня нет возможности отправить ему кое-что... кое-что очень важное: нашу сверхсекретную криопушку "Морозко"!$B$BТы не $gмог:могла; бы отнести ее Бривельверпу, $n?','Отнесите криопушку "Морозко" Бривельверпу на Затопленные раскопки в Тысяче Игл.','Не иначе это криопушка "Морозко"! Ну не красавица ли!$B$B<Бривельверп смеряет вас пронзительным взглядом.>$B$BОткрою тебе большой секрет, приятель: прямо тут закладывается фундамент грандиозной торговой империи!$B$BВот скажи, ты любишь мороженое?','Это то, что я думаю?! Батюшки-светы!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Особая посылка для Бривельверпа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У меня новый деловой партнер – мой лучший друг Бривельверп. Пока мы тут лясы точим, он закладывает фундамент нашей новой империи мороженого!$B$BБривельверп отвел наш холодильный буксир, оборудование и рабочих на юго-запад, к Затопленным раскопкам. К сожалению, у меня нет возможности отправить ему кое-что... кое-что очень важное: нашу сверхсекретную криопушку "Морозко"!$B$BТы не $gмог:могла; бы отнести ее Бривельверпу, $n?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите криопушку "Морозко" Бривельверпу на Затопленные раскопки в Тысяче Игл.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Не иначе это криопушка "Морозко"! Ну не красавица ли!$B$B<Бривельверп смеряет вас пронзительным взглядом.>$B$BОткрою тебе большой секрет, приятель: прямо тут закладывается фундамент грандиозной торговой империи!$B$BВот скажи, ты любишь мороженое?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Это то, что я думаю?! Батюшки-светы!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (28032,'Тайны пламенной кишки','Мы очень многого не знаем о пламезаврах. Откуда они взялись? Как они выживают на этих равнинах? И почему они такие мерзкие на вкус?$b$bДумаю, что ключ к секрету этих доисторических животных – в их пламенных кишках. Они есть у всех пламезавров. И я бы хотела иметь несколько для изучения.$b$bПламезавров можно найти у Железной вершины, в основном в западной части.','Добудьте 6 пламенных кишок.','О, эти превосходны. А теперь оставь меня наедине с этими кишками. Мне надо заняться исследованиями!$B$B<Агнес начинает тыкать в кишки палочкой.>$B$BОчень интересно. В самом деле очень интересно…','Когда же я наконец получу эти потроха!','Вернитесь к Агнес Длиннохолке на Железную вершину в Тлеющем ущелье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тайны пламенной кишки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы очень многого не знаем о пламезаврах. Откуда они взялись? Как они выживают на этих равнинах? И почему они такие мерзкие на вкус?$b$bДумаю, что ключ к секрету этих доисторических животных – в их пламенных кишках. Они есть у всех пламезавров. И я бы хотела иметь несколько для изучения.$b$bПламезавров можно найти у Железной вершины, в основном в западной части.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 6 пламенных кишок.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, эти превосходны. А теперь оставь меня наедине с этими кишками. Мне надо заняться исследованиями!$B$B<Агнес начинает тыкать в кишки палочкой.>$B$BОчень интересно. В самом деле очень интересно…',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Когда же я наконец получу эти потроха!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Агнес Длиннохолке на Железную вершину в Тлеющем ущелье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28033,'Обман','Что? Почему ты все еще здесь? А, я обещал, что помогу тебе и Братству Тория в вашей битве?$b$bЯ врал.$b$bЯ просто не могу выделить бойцов. Знаю, я обещал помочь, но вы никак не убедите меня покинуть сейчас Железную вершину. Абсолютно никак.','Найдите способ убедить горного владыку Рендана присоединиться к Братству Тория.','Так, так, так… Посмотрите, кто пришел к Чурбану!$B$BПохоже, для этого случая отлично подойдет уникальная антиубийственная методика Чурбана.','Поговорите с Чурбаном на Железной вершине в Тлеющем ущелье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обман',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что? Почему ты все еще здесь? А, я обещал, что помогу тебе и Братству Тория в вашей битве?$b$bЯ врал.$b$bЯ просто не могу выделить бойцов. Знаю, я обещал помочь, но вы никак не убедите меня покинуть сейчас Железную вершину. Абсолютно никак.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите способ убедить горного владыку Рендана присоединиться к Братству Тория.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так, так, так… Посмотрите, кто пришел к Чурбану!$B$BПохоже, для этого случая отлично подойдет уникальная антиубийственная методика Чурбана.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Чурбаном на Железной вершине в Тлеющем ущелье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28034,'Приключения Чурбана: слабость Рендана','Чурбан не очень умный, но зато наблюдательный. Сегодня Чурбан заметил, что этому горному дворфу нравится смотреть, как танцуют.$b$bЧурбан любит танцевать! $n любит танцевать!$b$bМожет быть, мы найдем еще дворфов, которые любят танцевать. А потом пойдем к этому горному дворфу, и он послушается |3-1($n).','Поговорите с тремя стражами Железной вершины и попросите их присоединиться к танцу.','Я что, говорил как-то невнятно? Мне казалось, я ясно выразил свою… позицию…$B$BУх ты, как вы здорово танцуете! Мне нравится!','Поговорите с горным владыкой Ренданом на Железной вершине, что в Тлеющем ущелье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приключения Чурбана: слабость Рендана',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чурбан не очень умный, но зато наблюдательный. Сегодня Чурбан заметил, что этому горному дворфу нравится смотреть, как танцуют.$b$bЧурбан любит танцевать! $n любит танцевать!$b$bМожет быть, мы найдем еще дворфов, которые любят танцевать. А потом пойдем к этому горному дворфу, и он послушается |3-1($n).',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с тремя стражами Железной вершины и попросите их присоединиться к танцу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я что, говорил как-то невнятно? Мне казалось, я ясно выразил свою… позицию…$B$BУх ты, как вы здорово танцуете! Мне нравится!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с горным владыкой Ренданом на Железной вершине, что в Тлеющем ущелье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28035,'Поддержка горного владыки','Ладно, ладно! Если бы я знал, что вы так танцуете, я бы не стал вас просить делать все остальное.$b$bСкажите надзирателю Скользоруку, что я присоединюсь. Встретимся в Шлаковой яме! Когда Братство Тория объединится с Железной вершиной, эти дворфы из ущелья вообще не поймут, кто на них напал!','Отчитайтесь о вашем успехе надзирателю Скользоруку в лагере Братства Тория в Тлеющем ущелье.','Так Рендан с нами? Наконец-то этот олух согласился.$B$BТогда вперед.','Поговорите с надзирателем Скользоруком в Братстве Тория, что в Тлеющем ущелье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поддержка горного владыки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ладно, ладно! Если бы я знал, что вы так танцуете, я бы не стал вас просить делать все остальное.$b$bСкажите надзирателю Скользоруку, что я присоединюсь. Встретимся в Шлаковой яме! Когда Братство Тория объединится с Железной вершиной, эти дворфы из ущелья вообще не поймут, кто на них напал!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отчитайтесь о вашем успехе надзирателю Скользоруку в лагере Братства Тория в Тлеющем ущелье.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так Рендан с нами? Наконец-то этот олух согласился.$B$BТогда вперед.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с надзирателем Скользоруком в Братстве Тория, что в Тлеющем ущелье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (28036,'Требуются герои: Зул\'Фаррак','По повелению короля Вариана Ринна всем отважным искателям приключений надлежит явиться в Зул\'Фаррак, к западу от Прибамбасска.$B$BАрмия троллей из племени Песчаной Бури грозит захватить Прибамбасск. Если вы решите откликнуться на этот призыв, отправляйтесь в Зул\'Фаррак и поговорите с Тран\'реком. Он скажет, что делать.','Поговорите с Тран\'реком.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Требуются герои: Зул\'Фаррак',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','По повелению короля Вариана Ринна всем отважным искателям приключений надлежит явиться в Зул\'Фаррак, к западу от Прибамбасска.$B$BАрмия троллей из племени Песчаной Бури грозит захватить Прибамбасск. Если вы решите откликнуться на этот призыв, отправляйтесь в Зул\'Фаррак и поговорите с Тран\'реком. Он скажет, что делать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Тран\'реком.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (28037,'Требуются герои: Зул\'Фаррак','По повелению вождя всем отважным искателям приключений надлежит явиться в Зул\'Фаррак, к западу от Прибамбасска.$B$BАрмия троллей из племени Песчаной Бури грозит захватить Прибамбасск. Если хочешь помочь гоблинам, отправляйся в Зул\'Фаррак и поговори с Тран\'реком. Он скажет, что делать.','Поговорите с Тран\'реком.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Требуются герои: Зул\'Фаррак',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','По повелению вождя всем отважным искателям приключений надлежит явиться в Зул\'Фаррак, к западу от Прибамбасска.$B$BАрмия троллей из племени Песчаной Бури грозит захватить Прибамбасск. Если хочешь помочь гоблинам, отправляйся в Зул\'Фаррак и поговори с Тран\'реком. Он скажет, что делать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Тран\'реком.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (28039,'Требуются герои: Мародон','По повелению вождя всем отважным искателям приключений надлежит явиться в Мародон, расположенный в западных Пустошах!$B$BИсцеление Мародона от поразившей его скверны положительно повлияло бы на Пустоши в целом! Если вы решите откликнуться на этот призыв, отправляйтесь в Мародон и обратитесь к духу Зейтара, который даст вам дальнейшие указания.','Поговорите с духом Зейтара.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Требуются герои: Мародон',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','По повелению вождя всем отважным искателям приключений надлежит явиться в Мародон, расположенный в западных Пустошах!$B$BИсцеление Мародона от поразившей его скверны положительно повлияло бы на Пустоши в целом! Если вы решите откликнуться на этот призыв, отправляйтесь в Мародон и обратитесь к духу Зейтара, который даст вам дальнейшие указания.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с духом Зейтара.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (28040,'Требуются герои: Мародон','Поговорите с духом Зейтара.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Требуются герои: Мародон',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с духом Зейтара.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (28041,'Наживка для грифона','Добудьте свежую грифонью тушу.','Добудьте свежую грифонью тушу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наживка для грифона',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте свежую грифонью тушу.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Добудьте свежую грифонью тушу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (28042,'Особая посылка для Бривельверпа','Мне тут по случаю досталось кое-что, что должны были доставить некому гному, Бривельверпу. По мне – так он скорее Дуреньверп.$B$BКак бы там ни было, хочу, чтобы ты $gотнес:отнесла; это на юго-запад, к Затопленным раскопкам. Он что-то замыслил, и дельце пахнет бабками – я прямо чую!$B$BПрисмотрись там, что он затевает, $n, и покумекай, как можно отхватить долю. Знатную долю!','Отнесите криопушку "Морозко" Бривельверпу на Затопленные раскопки в Тысяче Игл.','<Бривельверп смеряет вас подозрительным взглядом, но, едва завидев посылку, расплывается в улыбке.>$B$BДобро пожаловать, уважаемый, рад, премного рад! Я дам тебе шанс встать у истоков проекта, который не имеет аналогов.$B$BПредпринимательскому духу неведомы различия между Альянсом и Ордой.$B$BВот скажи, ты любишь мороженое?','Это то, что я думаю?! Батюшки-светы!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Особая посылка для Бривельверпа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне тут по случаю досталось кое-что, что должны были доставить некому гному, Бривельверпу. По мне – так он скорее Дуреньверп.$B$BКак бы там ни было, хочу, чтобы ты $gотнес:отнесла; это на юго-запад, к Затопленным раскопкам. Он что-то замыслил, и дельце пахнет бабками – я прямо чую!$B$BПрисмотрись там, что он затевает, $n, и покумекай, как можно отхватить долю. Знатную долю!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите криопушку "Морозко" Бривельверпу на Затопленные раскопки в Тысяче Игл.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Бривельверп смеряет вас подозрительным взглядом, но, едва завидев посылку, расплывается в улыбке.>$B$BДобро пожаловать, уважаемый, рад, премного рад! Я дам тебе шанс встать у истоков проекта, который не имеет аналогов.$B$BПредпринимательскому духу неведомы различия между Альянсом и Ордой.$B$BВот скажи, ты любишь мороженое?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Это то, что я думаю?! Батюшки-светы!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (28043,'Как искалечить своего дракона','<Вы вскидываете на плечо окровавленную тушу грифона; его длинные крылья волочатся за вами по земле.>$B$B<Черные драконы селятся к юго-западу от Горнила Крови, вокруг невысоких гор, образующих кольцо.>$B$B<Если бросить тушу грифона там, она непременно привлечет какого-нибудь дракона. Когда его внимание будет поглощено едой, вы сможете напасть на него и ослабить настолько, что он позволит себя оседлать.>','Завлеките приманенного черного дракона, бейте его до тех пор, пока он не ослабнет, а затем летите на нем в Кровавое ущелье.','Поговорите с Зелой в Кровавом ущелье на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Как искалечить своего дракона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Вы вскидываете на плечо окровавленную тушу грифона; его длинные крылья волочатся за вами по земле.>$B$B<Черные драконы селятся к юго-западу от Горнила Крови, вокруг невысоких гор, образующих кольцо.>$B$B<Если бросить тушу грифона там, она непременно привлечет какого-нибудь дракона. Когда его внимание будет поглощено едой, вы сможете напасть на него и ослабить настолько, что он позволит себя оседлать.>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Завлеките приманенного черного дракона, бейте его до тех пор, пока он не ослабнет, а затем летите на нем в Кровавое ущелье.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Зелой в Кровавом ущелье на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (28044,'Дотронуться до недосягаемого','Я добавил в зелье частицу моего собственного естества. Видишь мерцающий знак у Гряды Затаившейся Тьмы, к западу отсюда? Встань на него, сосредоточься и вылей зелье на себя. Этого должно быть достаточно для того, чтобы перенестись в Пустоту и увидеть, что там НА САМОМ ДЕЛЕ.$b$bТы будешь не $gодин:одна;... сокровище сатиров охраняет самый большой страж Пустоты, какого они только смогли призвать. Одолей его, и сокровище твое.$b$bИ возвращайся $gцелым и невредимым:целой и невредимой;, иначе эта ненормальная меня зажарит!','Встаньте на знак Тихондрия, воспользуйтесь межфазовым зельем крови, чтобы перенестись в Пустоту и найти коготь Тихондрия.','Вернитесь к чародейке Деларис в руины Констелласа, что в Оскверненном лесу.','Страж Пустоты, в его руках то, что вы ищете.','Ворл','Теперь не двигайся.','Чародейка Деларис') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дотронуться до недосягаемого',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я добавил в зелье частицу моего собственного естества. Видишь мерцающий знак у Гряды Затаившейся Тьмы, к западу отсюда? Встань на него, сосредоточься и вылей зелье на себя. Этого должно быть достаточно для того, чтобы перенестись в Пустоту и увидеть, что там НА САМОМ ДЕЛЕ.$b$bТы будешь не $gодин:одна;... сокровище сатиров охраняет самый большой страж Пустоты, какого они только смогли призвать. Одолей его, и сокровище твое.$b$bИ возвращайся $gцелым и невредимым:целой и невредимой;, иначе эта ненормальная меня зажарит!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Встаньте на знак Тихондрия, воспользуйтесь межфазовым зельем крови, чтобы перенестись в Пустоту и найти коготь Тихондрия.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к чародейке Деларис в руины Констелласа, что в Оскверненном лесу.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Страж Пустоты, в его руках то, что вы ищете.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Ворл',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Теперь не двигайся.',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Чародейка Деларис',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (28045,'Лучший в мире вкус!','Прямо под нами – пещера. Огромная! Прекрасное место для нашего нового хладобункера. И достаточно большое, чтобы разместить все наше оборудование и иметь запас для расширения производства.$B$BК сожалению, когда мы провели почти все трубы, откуда ни возьмись полезли насекомые и перебили рабочих!$B$BНу, а откуда мне было знать?$B$BЗато у меня родилась гениальная идея: мороженое со вкусом силитидов! Это будет мега-хит!$B$BВсе, что мне нужно сейчас, – это ингредиенты.','Соберите 8 пригоршней слизи силитида.','Отлично! Это будет самый лучший вкус на свете!$B$BБерегитесь, Тигуль и Форор!!!','Удалось собрать достаточно жучиной массы для первой партии?','Вернитесь к Бривельверпу на Затопленные раскопки, что в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лучший в мире вкус!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прямо под нами – пещера. Огромная! Прекрасное место для нашего нового хладобункера. И достаточно большое, чтобы разместить все наше оборудование и иметь запас для расширения производства.$B$BК сожалению, когда мы провели почти все трубы, откуда ни возьмись полезли насекомые и перебили рабочих!$B$BНу, а откуда мне было знать?$B$BЗато у меня родилась гениальная идея: мороженое со вкусом силитидов! Это будет мега-хит!$B$BВсе, что мне нужно сейчас, – это ингредиенты.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 пригоршней слизи силитида.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! Это будет самый лучший вкус на свете!$B$BБерегитесь, Тигуль и Форор!!!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось собрать достаточно жучиной массы для первой партии?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бривельверпу на Затопленные раскопки, что в Тысяче Игл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28046,'Завершение работы','Всю неделю мы пытались принести пригодные запчасти с Передовой. И всякий раз, когда мы несли детали в лагерь, на нас нападали неупокоенные солдаты. Ты бы не $gсогласился:согласилась; расчистить наш путь?','От вас требуется уничтожить 5 неупокоенных пехотинцев на Передовой Неупокоенных. Это место расположено на западной стороне острова на подступах к Забытому холму.','Давно было пора расправиться с ними.','Доложите лейтенанту Фарнсворту в Лагере Барадин о завершении задания.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Завершение работы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Всю неделю мы пытались принести пригодные запчасти с Передовой. И всякий раз, когда мы несли детали в лагерь, на нас нападали неупокоенные солдаты. Ты бы не $gсогласился:согласилась; расчистить наш путь?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','От вас требуется уничтожить 5 неупокоенных пехотинцев на Передовой Неупокоенных. Это место расположено на западной стороне острова на подступах к Забытому холму.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Давно было пора расправиться с ними.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доложите лейтенанту Фарнсворту в Лагере Барадин о завершении задания.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28047,'Заморозка труб','Что ж, пора распечатать нашу криопушку "Морозко"!$B$BМы скопировали технологию морозных пушек с гоночных судов. В чем нам, гномам, нет равных– так это в миниатюризации за счет делания всего окружающего во-о-от таким громадным!$B$BТы $gдолжен:должна; спуститься с пушкой в пещеру и заморозить трубы, вмонтированные в стены. Это запустит процесс.','С помощью криопушки "Морозко" заморозьте 4 трубы в пещере.','Слышишь, Цифеида? Это сладкий шум начавшегося охлаждения.$B$BСовсем скоро мы сможем хранить в пещере сырье. Спасибо тебе!','Вернитесь к Бривельверпу на Затопленные раскопки, что в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Заморозка труб',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что ж, пора распечатать нашу криопушку "Морозко"!$B$BМы скопировали технологию морозных пушек с гоночных судов. В чем нам, гномам, нет равных– так это в миниатюризации за счет делания всего окружающего во-о-от таким громадным!$B$BТы $gдолжен:должна; спуститься с пушкой в пещеру и заморозить трубы, вмонтированные в стены. Это запустит процесс.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','С помощью криопушки "Морозко" заморозьте 4 трубы в пещере.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Слышишь, Цифеида? Это сладкий шум начавшегося охлаждения.$B$BСовсем скоро мы сможем хранить в пещере сырье. Спасибо тебе!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бривельверпу на Затопленные раскопки, что в Тысяче Игл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (28048,'Умникам здесь не место','Глубоко в пещере засел какой-то шибко умный жучила. И заправляет всеми силитидами, которые там развелись.$B$BУ меня мороженое тает! Как я, по-твоему, построю империю мороженого и сберегу свои запасы, если там хозяйничает эта тварь?!','Уничтожьте надсмотрщика улья.','Великолепно! Теперь мы будем крупнейшими поставщиками мороженого во всем Азероте!','Вернитесь к Бривельверпу на Затопленные раскопки, что в Тысяче Игл.','Уничтожьте его во имя будущего процветания империи мороженого!','Надсмотрщик улья') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Умникам здесь не место',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Глубоко в пещере засел какой-то шибко умный жучила. И заправляет всеми силитидами, которые там развелись.$B$BУ меня мороженое тает! Как я, по-твоему, построю империю мороженого и сберегу свои запасы, если там хозяйничает эта тварь?!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте надсмотрщика улья.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Великолепно! Теперь мы будем крупнейшими поставщиками мороженого во всем Азероте!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бривельверпу на Затопленные раскопки, что в Тысяче Игл.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Уничтожьте его во имя будущего процветания империи мороженого!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Надсмотрщик улья',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28049,'Увидеть невидимое','Да, да, твоя заносчивая подружка-магичка все правильно поняла. Бесы Гряды Затаившейся Тьмы прячут ключ от барьера сатиров, преграждающего путь в Пустоту. Он есть, но пока ты не $gоказался:оказалась; там, нельзя ни увидеть его, ни прикоснуться к нему.$b$bВ общем, думаю, вам не повезло, потому что только бесам доступны подобные перемещения. Так что тебе стоит просто закрыть глаза, отвернуться и дать мне уйти восвояси...$b$bШутка! Не бей меня! Мне нужна слизь проклятых слизнюков, которых полно в этих руинах. Принеси мне столько, чтобы хватило, чтобы покрыть тебя с головы до ног!','Соберите 8 порций слизи проклятых слизнюков в руинах Констелласа.','Как хорошо, что ты вернулся! Больше не оставляй меня с ней наедине! Она же ненормальная!$B$BДавай это сюда, и ты в два счета увидишь невидимое!','Вернитесь к Бесенку в руины Констелласа, что в Оскверненном лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Увидеть невидимое',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Да, да, твоя заносчивая подружка-магичка все правильно поняла. Бесы Гряды Затаившейся Тьмы прячут ключ от барьера сатиров, преграждающего путь в Пустоту. Он есть, но пока ты не $gоказался:оказалась; там, нельзя ни увидеть его, ни прикоснуться к нему.$b$bВ общем, думаю, вам не повезло, потому что только бесам доступны подобные перемещения. Так что тебе стоит просто закрыть глаза, отвернуться и дать мне уйти восвояси...$b$bШутка! Не бей меня! Мне нужна слизь проклятых слизнюков, которых полно в этих руинах. Принеси мне столько, чтобы хватило, чтобы покрыть тебя с головы до ног!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 порций слизи проклятых слизнюков в руинах Констелласа.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Как хорошо, что ты вернулся! Больше не оставляй меня с ней наедине! Она же ненормальная!$B$BДавай это сюда, и ты в два счета увидишь невидимое!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бесенку в руины Констелласа, что в Оскверненном лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (28050,'Акула Амбал','Ненавижу акул. И все мои солдаты тоже. Тут-то ты нам и пригодишься, $n.$b$bПоднимись к мысу Потерянной Надежды и убей гигантскую акулу по имени Амбал. Ее не стоит недооценивать, так что лучше прихвати с собой на подмогу парочку друзей.','Вам поручено убить Амбала, гигантскую акулу, плавающую в водах у мыса Потерянной Надежды. Мыс расположен севернее, если идти вдоль береговой линии.','Не может быть! Ты действительно покончил с ней? Значит у нас сегодня акулятина на ужин!','Когда закончите, доложите о своих успехах начальнику лагеря Брэку в Лагере Барадин.','У этой рыбины действительно огромные челюсти.','Амбал') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Акула Амбал',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ненавижу акул. И все мои солдаты тоже. Тут-то ты нам и пригодишься, $n.$b$bПоднимись к мысу Потерянной Надежды и убей гигантскую акулу по имени Амбал. Ее не стоит недооценивать, так что лучше прихвати с собой на подмогу парочку друзей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вам поручено убить Амбала, гигантскую акулу, плавающую в водах у мыса Потерянной Надежды. Мыс расположен севернее, если идти вдоль береговой линии.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Не может быть! Ты действительно покончил с ней? Значит у нас сегодня акулятина на ужин!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Когда закончите, доложите о своих успехах начальнику лагеря Брэку в Лагере Барадин.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','У этой рыбины действительно огромные челюсти.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Амбал',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28051,'Мы положили жизни за мороженое!','Ты не думай... Это я внешне такой веселый, но внутри душа на части рвется. Все мои друзья, мои работники – мертвы...$B$BСделай одолжение: сплавай вниз и прицепи к телам моих рабочих этот буксирный трос. А я вытяну их на поверхность.','Прицепите буксирный трос к телам 10 погибших рабочих.','Спасибо тебе, Цифеида. Они отдали свои жизни за мороженое...','Вернитесь к Бривельверпу на Затопленные раскопки, что в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мы положили жизни за мороженое!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты не думай... Это я внешне такой веселый, но внутри душа на части рвется. Все мои друзья, мои работники – мертвы...$B$BСделай одолжение: сплавай вниз и прицепи к телам моих рабочих этот буксирный трос. А я вытяну их на поверхность.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Прицепите буксирный трос к телам 10 погибших рабочих.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо тебе, Цифеида. Они отдали свои жизни за мороженое...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бривельверпу на Затопленные раскопки, что в Тысяче Игл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (28052,'Операция: переполох в Котловане','Я посажу тебя на ветролет, $n.$b$bБудешь отвечать за мягкость нашей посадки в Шлаковой Яме. Поговори с распорядителем полетов здесь в Братстве Тория, а затем лети в ущелье.$b$bКогда приблизишься к точке посадки, там тебя наверняка будут ждать толпы дворфов Черного Железа. Воспользуйся орудиями на борту ветролета, чтобы уложить как можно больше, а затем приземляйся у входа в пещеру. К тому моменту Рендан должен уже ждать тебя.','Поговорите с распорядителем полетов Братства Тория, а затем воспользуйтесь орудиями ветролета Братства, чтобы убивать защитников Котлована, пока место посадки не станет безопасным.','Поговорите с горным владыкой Ренданом у входа в Шлаковую Яму, что в Тлеющем ущелье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Операция: переполох в Котловане',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я посажу тебя на ветролет, $n.$b$bБудешь отвечать за мягкость нашей посадки в Шлаковой Яме. Поговори с распорядителем полетов здесь в Братстве Тория, а затем лети в ущелье.$b$bКогда приблизишься к точке посадки, там тебя наверняка будут ждать толпы дворфов Черного Железа. Воспользуйся орудиями на борту ветролета, чтобы уложить как можно больше, а затем приземляйся у входа в пещеру. К тому моменту Рендан должен уже ждать тебя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с распорядителем полетов Братства Тория, а затем воспользуйтесь орудиями ветролета Братства, чтобы убивать защитников Котлована, пока место посадки не станет безопасным.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с горным владыкой Ренданом у входа в Шлаковую Яму, что в Тлеющем ущелье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (28053,'Чурбану нравится, что ты делаешь') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чурбану нравится, что ты делаешь',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28054,'Рабство – это плохо','Как и надзиратель Мальторий, я богат. Я достиг этого, принимая мудрые решения и упорно работая, а не занимаясь работорговлей.$b$bНу, ладно, почти не занимаясь работорговлей. Почти совсем.$b$bВ любом случае, первое, что бросается в глаза в этих пещерах – это надзиратели и надсмотрщики за рабами. Я не собираюсь это поддерживать! По мере продвижения вглубь пещеры убивай всех, кого сможешь. О результатах сообщи Эвонис Сажекурке, ее можно найти в глубине Шлаковой Ямы.','Убейте 10 надсмотрщиков или поработителей из клана Черного Железа.','Отлично. Вижу, ты тоже против рабства.','Поговорите с Эвонис Сажекуркой в Шлаковой Яме, что в Тлеющем ущелье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рабство – это плохо',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как и надзиратель Мальторий, я богат. Я достиг этого, принимая мудрые решения и упорно работая, а не занимаясь работорговлей.$b$bНу, ладно, почти не занимаясь работорговлей. Почти совсем.$b$bВ любом случае, первое, что бросается в глаза в этих пещерах – это надзиратели и надсмотрщики за рабами. Я не собираюсь это поддерживать! По мере продвижения вглубь пещеры убивай всех, кого сможешь. О результатах сообщи Эвонис Сажекурке, ее можно найти в глубине Шлаковой Ямы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 надсмотрщиков или поработителей из клана Черного Железа.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично. Вижу, ты тоже против рабства.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Эвонис Сажекуркой в Шлаковой Яме, что в Тлеющем ущелье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28055,'Сладкая горечь свободы','Раз уж мы здесь, нужно освободить как можно больше рабов. Скорее всего многие из них присоединятся к нам, сгорая от желания отомстить своим поработителям.$b$bНо в то же время некоторые рабы не пожелают вновь обрести свободу. Это удивительный феномен, его еще часто называют "Дарнхольдским синдромом".$b$bТак или иначе, ты $gдолжен:должна; попытаться освободить их. Если они будут сопротивляться, относись к ним, как к врагам. О результатах сообщи Эвонис Сажекурке, ее ты найдешь в глубине Шлаковой Ямы.','Освободите 12 рабов-трудяг. Если они будут сопротивляться, убивайте их.','Удивительно, как много рабов не желают быть свободными. Стыдно делать то, что мы делаем, но таково истинное лицо войны.$B$BА теперь мы должны двигаться дальше и решать более важные задачи.','Поговорите с Эвонис Сажекуркой в Шлаковой Яме, что в Тлеющем ущелье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сладкая горечь свободы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Раз уж мы здесь, нужно освободить как можно больше рабов. Скорее всего многие из них присоединятся к нам, сгорая от желания отомстить своим поработителям.$b$bНо в то же время некоторые рабы не пожелают вновь обрести свободу. Это удивительный феномен, его еще часто называют "Дарнхольдским синдромом".$b$bТак или иначе, ты $gдолжен:должна; попытаться освободить их. Если они будут сопротивляться, относись к ним, как к врагам. О результатах сообщи Эвонис Сажекурке, ее ты найдешь в глубине Шлаковой Ямы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Освободите 12 рабов-трудяг. Если они будут сопротивляться, убивайте их.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Удивительно, как много рабов не желают быть свободными. Стыдно делать то, что мы делаем, но таково истинное лицо войны.$B$BА теперь мы должны двигаться дальше и решать более важные задачи.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Эвонис Сажекуркой в Шлаковой Яме, что в Тлеющем ущелье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (28056,'Восстань, Обсидион','Здесь всем заправляет надзиратель Мальторий, но он не единственный могущественный дворф в Шлаковой Яме. В глубине этого коридора обитают Латорик Черный и его ужасающий голем, Обсидион.$b$bПризвать обоих можно при помощи алтаря Латорика. Найди алтарь, призови Латорика и убей его. Когда закончишь, отчитайся Эвонис Сажекурке.','Воспользуйтесь алтарем Сунтары, а затем убейте Латорика Черного и Обсидиона.','Поговорите с Эвонис Сажекуркой в Шлаковой Яме, что в Тлеющем ущелье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Восстань, Обсидион',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Здесь всем заправляет надзиратель Мальторий, но он не единственный могущественный дворф в Шлаковой Яме. В глубине этого коридора обитают Латорик Черный и его ужасающий голем, Обсидион.$b$bПризвать обоих можно при помощи алтаря Латорика. Найди алтарь, призови Латорика и убей его. Когда закончишь, отчитайся Эвонис Сажекурке.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь алтарем Сунтары, а затем убейте Латорика Черного и Обсидиона.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Эвонис Сажекуркой в Шлаковой Яме, что в Тлеющем ущелье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (28057,'Казнь через лишение сна','Вижу, Эвонис снова взялась за свои старые шутки. Думаю, я просто… гм… подержу эти подушки тут некоторое время.$B$BСамое главное, что ты здесь. Нам понадобится твоя помощь.','Что? Подушки?$B$BКакие подушки?','Поговорите с надсмотрщиком Скренджем в Шлаковой Яме, что в Тлеющем ущелье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Казнь через лишение сна',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вижу, Эвонис снова взялась за свои старые шутки. Думаю, я просто… гм… подержу эти подушки тут некоторое время.$B$BСамое главное, что ты здесь. Нам понадобится твоя помощь.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что? Подушки?$B$BКакие подушки?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с надсмотрщиком Скренджем в Шлаковой Яме, что в Тлеющем ущелье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (28058,'Размер имеет значение') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Размер имеет значение',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (28059,'Взятие крепости','$gВидел:Видела; крепость в северной части острова, $n? Там обосновался некий Фарсон.$b$bФарсон со своими немногочисленными приспешниками докучают нам с тех пор, как мы пришли в эти места. Мы отправили в разведку небольшой отряд, который установил точное местоположение Фарсона в крепости.$b$bТы поможешь нам покончить с ним?','Вас просят убить начальника крепости Фарсона. Его крепость находится на северной стороне острова.','Когда закончите, явитесь к командиру Марку Джонсону в Лагерь Барадин.','У него преданные подчиненные. Не нужно их недооценивать.','Начальник крепости Фарсон') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Взятие крепости',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$gВидел:Видела; крепость в северной части острова, $n? Там обосновался некий Фарсон.$b$bФарсон со своими немногочисленными приспешниками докучают нам с тех пор, как мы пришли в эти места. Мы отправили в разведку небольшой отряд, который установил точное местоположение Фарсона в крепости.$b$bТы поможешь нам покончить с ним?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вас просят убить начальника крепости Фарсона. Его крепость находится на северной стороне острова.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Когда закончите, явитесь к командиру Марку Джонсону в Лагерь Барадин.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','У него преданные подчиненные. Не нужно их недооценивать.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Начальник крепости Фарсон',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (28060,'Запутанные связи Сумрака','Поговорите с надзирателем Скользоруком в Шлаковой Яме, что в Тлеющем ущелье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Запутанные связи Сумрака',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с надзирателем Скользоруком в Шлаковой Яме, что в Тлеющем ущелье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (28061,'Приспешники Кальциндера','Чем глубже копаешь, тем больше нюансов, $n. Бывает, найдешь богатейшие залежи минералов глубоко под землей, но одновременно наткнешься и на самых злобных существ.$b$bНапример, огненных элементалей.$b$bВ пещере, что перед нами, полно приспешников Кальциндера. И в каждом из них заключена частица его злой сущности. Убей, скольких сможешь, никого не щади.','Убейте 6 пламенных призраков.','Останки приспешников Кальциндера тлеют у ваших ног. Скользорук будет рад узнать о вашем успехе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приспешники Кальциндера',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чем глубже копаешь, тем больше нюансов, $n. Бывает, найдешь богатейшие залежи минералов глубоко под землей, но одновременно наткнешься и на самых злобных существ.$b$bНапример, огненных элементалей.$b$bВ пещере, что перед нами, полно приспешников Кальциндера. И в каждом из них заключена частица его злой сущности. Убей, скольких сможешь, никого не щади.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 6 пламенных призраков.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Останки приспешников Кальциндера тлеют у ваших ног. Скользорук будет рад узнать о вашем успехе.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (28062,'Туда, откуда он пришел','Эрцгерцог Кальциндер укрылся в глубине этой самой пещеры. Мы близки к тому, чтобы убить его... но мы поступим по-другому.$b$bУбийство Кальциндера ничего не решит. Его пособники легко смогут оживить его. Вместо этого мы его изгоним.$b$bРаньше я просил тебя достать один ценный камень Сумеречного Молота. Теперь ты используешь его против Кальциндера. Напади на него, добейся того, чтобы он ослаб, а затем используй камень. И он будет изгнан в свой мир.$b$bУдачи тебе, $gхрабрый:храбрая; $n.','Добейтесь того, чтобы эрцгерцог Кальциндер ослаб, а затем воспользуйтесь освященным триоцитом, чтобы изгнать его.','Я не потреплю никаких приспешников Рагнароса вблизи лагеря Братства Тория. Отправьте его туда, откуда он пришел.','Эрцгерцог Кальциндер') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Туда, откуда он пришел',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эрцгерцог Кальциндер укрылся в глубине этой самой пещеры. Мы близки к тому, чтобы убить его... но мы поступим по-другому.$b$bУбийство Кальциндера ничего не решит. Его пособники легко смогут оживить его. Вместо этого мы его изгоним.$b$bРаньше я просил тебя достать один ценный камень Сумеречного Молота. Теперь ты используешь его против Кальциндера. Напади на него, добейся того, чтобы он ослаб, а затем используй камень. И он будет изгнан в свой мир.$b$bУдачи тебе, $gхрабрый:храбрая; $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добейтесь того, чтобы эрцгерцог Кальциндер ослаб, а затем воспользуйтесь освященным триоцитом, чтобы изгнать его.',`objectives_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Я не потреплю никаких приспешников Рагнароса вблизи лагеря Братства Тория. Отправьте его туда, откуда он пришел.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Эрцгерцог Кальциндер',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (28063,'Забрать все оружие','На этом острове сложно достать боеприпасы. Всякий раз, как на нас нападает Орда, создается ощущение, что мы сражаемся с помощью камней и палок.$B$BМне доложили, что в Крепости Фарсона на северной стороне острова есть винтовки, которые мы могли бы использовать. Ты не $gмог:могла; бы туда наведаться?$b$bБудь $gосторожен:осторожна;, $n, приспешники Фарсона сделают все, чтобы защитить его.','Вам поручили забрать 12 ржавых винтовок из Крепости Фарсона, расположенной в северной части полуострова Тол Барад.','Ты достал ружья?','Когда закончите, явитесь к командиру Марку Джонсону в Лагерь Барадин.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Забрать все оружие',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На этом острове сложно достать боеприпасы. Всякий раз, как на нас нападает Орда, создается ощущение, что мы сражаемся с помощью камней и палок.$B$BМне доложили, что в Крепости Фарсона на северной стороне острова есть винтовки, которые мы могли бы использовать. Ты не $gмог:могла; бы туда наведаться?$b$bБудь $gосторожен:осторожна;, $n, приспешники Фарсона сделают все, чтобы защитить его.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вам поручили забрать 12 ржавых винтовок из Крепости Фарсона, расположенной в северной части полуострова Тол Барад.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты достал ружья?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Когда закончите, явитесь к командиру Марку Джонсону в Лагерь Барадин.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (28064,'Добро пожаловать в Братство','Тебе нужно возвращаться в Братство Тория. Надзирателю Скользоруку и остальным членам Братства будет интересно узнать, как ты $gсправился:справилась; с Кальциндером.','Отчитайтесь надзирателю Скользоруку в Братстве Тория, что в Тлеющем ущелье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Добро пожаловать в Братство',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе нужно возвращаться в Братство Тория. Надзирателю Скользоруку и остальным членам Братства будет интересно узнать, как ты $gсправился:справилась; с Кальциндером.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отчитайтесь надзирателю Скользоруку в Братстве Тория, что в Тлеющем ущелье.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (28065,'По вражеским тропам','За несколько недель мы послали уже три группы на разведку обстановки в Крепости Фарсона. К сожалению, ни одна из них не принесла никаких сведений.$B$BВ данный момент мы можем только уповать на то, что они живы и просто находятся в заключении. Я хочу, чтобы ты $gотправился:отправилась; в крепость и $gпомог:помогла; в освобождении наших солдат. Это будет непросто, $n, но именно ты в силах нам помочь.','Сопроводите заключенного Крепости Фарсона в безопасное место. Данная крепость расположена в северо-западной части острова.','Узник крепости Фарсона сопровожден','Когда закончите, явитесь к командиру Марку Джонсону в Лагерь Барадин.','Кажется, ему нужна помощь.','Узник Крепости Фарсона') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','По вражеским тропам',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','За несколько недель мы послали уже три группы на разведку обстановки в Крепости Фарсона. К сожалению, ни одна из них не принесла никаких сведений.$B$BВ данный момент мы можем только уповать на то, что они живы и просто находятся в заключении. Я хочу, чтобы ты $gотправился:отправилась; в крепость и $gпомог:помогла; в освобождении наших солдат. Это будет непросто, $n, но именно ты в силах нам помочь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сопроводите заключенного Крепости Фарсона в безопасное место. Данная крепость расположена в северо-западной части острова.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Узник крепости Фарсона сопровожден',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Когда закончите, явитесь к командиру Марку Джонсону в Лагерь Барадин.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Кажется, ему нужна помощь.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Узник Крепости Фарсона',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (28066,'Требуются герои: Затонувший храм','Обратитесь к лорду Итару.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Требуются герои: Затонувший храм',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обратитесь к лорду Итару.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (28067,'Требуются герои: Затонувший храм','По повелению короля Вариана Ринна всем отважным искателям приключений надлежит явиться в Затонувший храм неподалеку от Заставы Болотной Воды!$B$BВ храме тролли Атал\'ай пытаются призвать Хаккара Свежевателя Душ! Если вы решите откликнуться на этот призыв, отправляйтесь к Затонувшему храму и поговорите с лордом Итаром из рода зеленых драконов. Он знает, как покончить со злонамеренными троллями.','Обратитесь к лорду Итару.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Требуются герои: Затонувший храм',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','По повелению короля Вариана Ринна всем отважным искателям приключений надлежит явиться в Затонувший храм неподалеку от Заставы Болотной Воды!$B$BВ храме тролли Атал\'ай пытаются призвать Хаккара Свежевателя Душ! Если вы решите откликнуться на этот призыв, отправляйтесь к Затонувшему храму и поговорите с лордом Итаром из рода зеленых драконов. Он знает, как покончить со злонамеренными троллями.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обратитесь к лорду Итару.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (28068,'Требуются герои: Глубины Черной горы','Поговорите с Морганой.','Похоже, ты готов истребить сотню-другую дфорфов Черного Железа во имя справедливости.$B$BПросто великолепно.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Требуются герои: Глубины Черной горы',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Морганой.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Похоже, ты готов истребить сотню-другую дфорфов Черного Железа во имя справедливости.$B$BПросто великолепно.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (28069,'Требуются герои: Глубины Черной горы','По повелению вождя всем отважным искателям приключений надлежит явиться в Глубины Черной горы, что находятся к западу от Пламенеющего Стяга!$B$BДворфы Черного Железа уже нападали на принадлежащее Альянсу Красногорье. Если ничего не предпринять, то вскоре они могут начать угрожать и владениям Орды на юге Азерота.$b$BЕсли вы решите откликнуться на этот призыв, отправляйтесь в Глубины Черной горы, где вам надлежит обратиться к верховному палачу Нузраку, который занимается перегруппировкой сил Каргатского экспедиционного корпуса, чтобы раз и навсегда покончить с дворфами Черного Железа.','Поговорите с верховным палачом Нузраком.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Требуются герои: Глубины Черной горы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','По повелению вождя всем отважным искателям приключений надлежит явиться в Глубины Черной горы, что находятся к западу от Пламенеющего Стяга!$B$BДворфы Черного Железа уже нападали на принадлежащее Альянсу Красногорье. Если ничего не предпринять, то вскоре они могут начать угрожать и владениям Орды на юге Азерота.$b$BЕсли вы решите откликнуться на этот призыв, отправляйтесь в Глубины Черной горы, где вам надлежит обратиться к верховному палачу Нузраку, который занимается перегруппировкой сил Каргатского экспедиционного корпуса, чтобы раз и навсегда покончить с дворфами Черного Железа.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с верховным палачом Нузраком.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (28070,'Требуются герои: Пик Черной горы','По повелению вождя всем отважным искателям приключений надлежит явиться на Пик Черной горы, что находятся к западу от Пламенеющего Стяга!$B$BВойско Нефариана и приспешники Ренда Чернорука угрожают самому существованию Орды! Если вы чувствуете в себе силы, отправляйтесь на Пик Черной горы и обратитесь там к Акрайду, нашему единственному связному, который может помочь остановить неминуемое нападение.','Поговорите с Акрайдом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Требуются герои: Пик Черной горы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','По повелению вождя всем отважным искателям приключений надлежит явиться на Пик Черной горы, что находятся к западу от Пламенеющего Стяга!$B$BВойско Нефариана и приспешники Ренда Чернорука угрожают самому существованию Орды! Если вы чувствуете в себе силы, отправляйтесь на Пик Черной горы и обратитесь там к Акрайду, нашему единственному связному, который может помочь остановить неминуемое нападение.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Акрайдом.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (28071,'Требуются герои: Пик Черной горы','По повелению короля Вариана Ринна всем отважным искателям приключений надлежит явиться на Пик Черной горы, что находятся к северо-западу от Дозора Морганы!$B$BВойско Нефариана и приспешники Ренда Чернорука представляют серьезную угрозу для владений Его Величества! Если вы решите откликнуться на этот призыв, отправляйтесь на Пик Черной горы и обратитесь там к Акрайду, нашему единственному связному, который может помочь остановить неминуемое нападение.','Поговорите с Акрайдом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Требуются герои: Пик Черной горы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','По повелению короля Вариана Ринна всем отважным искателям приключений надлежит явиться на Пик Черной горы, что находятся к северо-западу от Дозора Морганы!$B$BВойско Нефариана и приспешники Ренда Чернорука представляют серьезную угрозу для владений Его Величества! Если вы решите откликнуться на этот призыв, отправляйтесь на Пик Черной горы и обратитесь там к Акрайду, нашему единственному связному, который может помочь остановить неминуемое нападение.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Акрайдом.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (28072,'Требуются герои: Квартал Криводревов Забытого Города','По повелению короля Вариана Ринна всем отважным искателям приключений надлежит явиться в Квартал Криводревов Забытого Города, что к востоку от Крепости Оперенной Луны!$b$bВся тамошняя область осквернена Алззином Перевертенем, который может захватить и Город! Если вы решите откликнуться на этот призыв, отправляйтесь в Квартал Криводревов и поговорите с Фургусом Криводревом, одним из немногих, кого не затронула порча и кто еще остался в живых.','Поговорите с Фургусом Криводревом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Требуются герои: Квартал Криводревов Забытого Города',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','По повелению короля Вариана Ринна всем отважным искателям приключений надлежит явиться в Квартал Криводревов Забытого Города, что к востоку от Крепости Оперенной Луны!$b$bВся тамошняя область осквернена Алззином Перевертенем, который может захватить и Город! Если вы решите откликнуться на этот призыв, отправляйтесь в Квартал Криводревов и поговорите с Фургусом Криводревом, одним из немногих, кого не затронула порча и кто еще остался в живых.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Фургусом Криводревом.',`objectives_loc8`);
