INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (28075,'Требуются герои: центральный сад Забытого Города','По повелению короля Вариана Ринна всем отважным искателям приключений надлежит явиться в центральный сад Забытого Города, что к востоку от Крепости Оперенной Луны!$b$bПавший высокорожденный принц Тортелдрин при помощи могущественного демона Бессмер\'тера контролирует эту область! Если вы решите откликнуться на этот призыв, отправляйтесь в центральный сад и поговорите с Эстуланом, чистокровным высокорожденным, который хочет вернуть город его жителям.','Поговорите с Эстуланом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Требуются герои: центральный сад Забытого Города',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','По повелению короля Вариана Ринна всем отважным искателям приключений надлежит явиться в центральный сад Забытого Города, что к востоку от Крепости Оперенной Луны!$b$bПавший высокорожденный принц Тортелдрин при помощи могущественного демона Бессмер\'тера контролирует эту область! Если вы решите откликнуться на этот призыв, отправляйтесь в центральный сад и поговорите с Эстуланом, чистокровным высокорожденным, который хочет вернуть город его жителям.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Эстуланом.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (28076,'Требуются герои: север Забытого Города','По повелению короля Вариана Ринна всем отважным искателям приключений надлежит явиться в северную часть Забытого Города, что к востоку от Крепости Оперенной Луны!$b$bКороль Гордок вместе со своей армией огров Гордока представляют для нас серьезную угрозу! Если вы решите откликнуться на этот призыв, отправляйтесь в северную часть Забытого Города и поговорите с друидом-вороном, которого отправили туда в качестве разведчика.','Поговорите с друидом-вороном.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Требуются герои: север Забытого Города',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','По повелению короля Вариана Ринна всем отважным искателям приключений надлежит явиться в северную часть Забытого Города, что к востоку от Крепости Оперенной Луны!$b$bКороль Гордок вместе со своей армией огров Гордока представляют для нас серьезную угрозу! Если вы решите откликнуться на этот призыв, отправляйтесь в северную часть Забытого Города и поговорите с друидом-вороном, которого отправили туда в качестве разведчика.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с друидом-вороном.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`objectives_loc8`) VALUES (28077,'Поговорите с огром из клана Каменного Молота.') ON DUPLICATE KEY UPDATE `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с огром из клана Каменного Молота.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (28078,'Требуются герои: Стратхольм, главные врата','По повелению вождя всем отважным искателям приключений надлежит немедленно явиться к главным вратам Стратхольма, к северу от Чумного леса.$B$BПовелитель Ужаса Бальназар лишил жизни рыцарей Алого ордена и обратил их в Восставших – своих неупокоенных слуг! Если вы решите откликнуться на этот призыв, отправляйтесь к главным вратам и поговорите с командиром Элигором Вестником Рассвета, предводителем Серебряного Авангарда, который делает все, чтобы вернуть Стратхольм его истинным хозяевам.','Поговорите с командиром Элигором Вестником Рассвета.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Требуются герои: Стратхольм, главные врата',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','По повелению вождя всем отважным искателям приключений надлежит немедленно явиться к главным вратам Стратхольма, к северу от Чумного леса.$B$BПовелитель Ужаса Бальназар лишил жизни рыцарей Алого ордена и обратил их в Восставших – своих неупокоенных слуг! Если вы решите откликнуться на этот призыв, отправляйтесь к главным вратам и поговорите с командиром Элигором Вестником Рассвета, предводителем Серебряного Авангарда, который делает все, чтобы вернуть Стратхольм его истинным хозяевам.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с командиром Элигором Вестником Рассвета.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (28079,'Требуются герои: Стратхольм, главные врата','По повелению короля Вариана Ринна всем отважным искателям приключений надлежит явиться к вратам Стратхольма, что на севере Чумного леса!$B$BПовелитель Ужаса Бальназар перебил рыцарей Алого Ордена и обратил их в Восставших – своих неупокоенных слуг! Если вы решите откликнуться на этот призыв, отправляйтесь к главным воротам Стратхольма к командиру рыцарей Элигору Вестнику Рассвета из Серебряного Авангарда, лидеру освободителей Стратхольма.','Поговорите с командиром Элигором Вестником Рассвета.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Требуются герои: Стратхольм, главные врата',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','По повелению короля Вариана Ринна всем отважным искателям приключений надлежит явиться к вратам Стратхольма, что на севере Чумного леса!$B$BПовелитель Ужаса Бальназар перебил рыцарей Алого Ордена и обратил их в Восставших – своих неупокоенных слуг! Если вы решите откликнуться на этот призыв, отправляйтесь к главным воротам Стратхольма к командиру рыцарей Элигору Вестнику Рассвета из Серебряного Авангарда, лидеру освободителей Стратхольма.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с командиром Элигором Вестником Рассвета.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (28080,'Требуются герои: Стратхольм, боковые врата','По повелению короля Вариана Ринна всем отважным искателям приключений надлежит немедленно явиться к боковым вратам Стратхольма, к северу-западу от башни Северного перевала.$B$BЛорд Аурий Ривендер, cын самого барона Ривендера, некогда паладин, недавно восставший из мертвых, возглавил остатки армии Плети! Если вы решите откликнуться на этот призыв, отправляйтесь к боковым вратам и поговорите с командиром Элигором Вестником Рассвета, предводителем Серебряного Авангарда, который делает все, чтобы вернуть Стратхольм его истинным хозяевам.','Поговорите с командиром Элигором Вестником Рассвета.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Требуются герои: Стратхольм, боковые врата',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','По повелению короля Вариана Ринна всем отважным искателям приключений надлежит немедленно явиться к боковым вратам Стратхольма, к северу-западу от башни Северного перевала.$B$BЛорд Аурий Ривендер, cын самого барона Ривендера, некогда паладин, недавно восставший из мертвых, возглавил остатки армии Плети! Если вы решите откликнуться на этот призыв, отправляйтесь к боковым вратам и поговорите с командиром Элигором Вестником Рассвета, предводителем Серебряного Авангарда, который делает все, чтобы вернуть Стратхольм его истинным хозяевам.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с командиром Элигором Вестником Рассвета.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (28081,'Требуются герои: Стратхольм, боковые врата','По повелению вождя всем отважным искателям приключений надлежит явиться к боковым вратам Стратхольма на северо-западе от башни Северного перевала!$B$BЛорд Аурий Ривендер, cын самого барона Ривендера, некогда паладин, недавно восставший из мертвых, возглавил остатки армии Плети! Всем, кто отважится, велено держать путь к боковым вратам Стратхольма и явиться к командиру рыцарей Элигору Вестнику Рассвета из Серебряного Авангарда, лидеру освободителей Стратхольма.','Поговорите с командиром Элигором Вестником Рассвета.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Требуются герои: Стратхольм, боковые врата',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','По повелению вождя всем отважным искателям приключений надлежит явиться к боковым вратам Стратхольма на северо-западе от башни Северного перевала!$B$BЛорд Аурий Ривендер, cын самого барона Ривендера, некогда паладин, недавно восставший из мертвых, возглавил остатки армии Плети! Всем, кто отважится, велено держать путь к боковым вратам Стратхольма и явиться к командиру рыцарей Элигору Вестнику Рассвета из Серебряного Авангарда, лидеру освободителей Стратхольма.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с командиром Элигором Вестником Рассвета.',`objectives_loc8`);
