INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (28085,'Беда в Скальном гнездовье','Благодарю тебя за помощь, $n. Поговори с Паокой Ходячей Горой в Скальном гнездовье к юго-западу отсюда.$B$BБыть может, он знает, где скрывается мудрая старица.','Поговорите с Паокой Ходячей Горой в Скальном гнездовье в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Беда в Скальном гнездовье',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Благодарю тебя за помощь, $n. Поговори с Паокой Ходячей Горой в Скальном гнездовье к юго-западу отсюда.$B$BБыть может, он знает, где скрывается мудрая старица.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Паокой Ходячей Горой в Скальном гнездовье в Тысяче Игл.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28086,'Свободу гордокрылам!','Ловчие загоняют всех молодых ветрокрылов. Будь $gдобр:добра;, $n, освободи детенышей гордокрылов.','Освободите 12 детенышей гордокрыла Скального гнездовья.','Они прекрасны. Наступит день – и они вырастут в могучих животных, но до тех пор их нужно защищать.','Вернитесь к Паоке Ходячей Горе в Скальное гнездовье в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Свободу гордокрылам!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ловчие загоняют всех молодых ветрокрылов. Будь $gдобр:добра;, $n, освободи детенышей гордокрылов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Освободите 12 детенышей гордокрыла Скального гнездовья.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Они прекрасны. Наступит день – и они вырастут в могучих животных, но до тех пор их нужно защищать.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Паоке Ходячей Горе в Скальное гнездовье в Тысяче Игл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (28087,'Смерть ловчим!','Только одного достойны эти мерзкие ловчие из клана Сумеречного Молота! Смерти!$B$BПринеси мне их сети, $n.','Раздобудьте 8 ловчих сетей.','Никаких больше пойманных птенцов сегодня!','Что за безумие овладело теми, кто творит такие жуткие вещи!','Вернитесь к Паоке Ходячей Горе в Скальное гнездовье в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Смерть ловчим!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Только одного достойны эти мерзкие ловчие из клана Сумеречного Молота! Смерти!$B$BПринеси мне их сети, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте 8 ловчих сетей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Никаких больше пойманных птенцов сегодня!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что за безумие овладело теми, кто творит такие жуткие вещи!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Паоке Ходячей Горе в Скальное гнездовье в Тысяче Игл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (28090,'Ценный груз','Врата, открывающие проход дальше, заперты. Разведчики сообщают, что караванщики открывают их с помощью особых камней, которые возят в сундуках.$B$BСпустись в ущелье и постарайся раздобыть ключ от такого сундука у одного из убитых охранников. Потом найди фургон с сундуком, открой сундук и принеси мне камень-ключ.','Найдите камень-ключ Сумеречного каравана. Ключи от сундуков с камнями-ключами должны быть у сумеречных копьеносцев.','Неплохо.$B$BВид у этой штуки довольно невзрачный, верно?','Знаешь, мы могли бы просто уничтожить врата. Однако у нас такой взрывник, что лучше не рисковать.','Вернитесь к Патчу на Тропу Драконьей Пасти на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ценный груз',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Врата, открывающие проход дальше, заперты. Разведчики сообщают, что караванщики открывают их с помощью особых камней, которые возят в сундуках.$B$BСпустись в ущелье и постарайся раздобыть ключ от такого сундука у одного из убитых охранников. Потом найди фургон с сундуком, открой сундук и принеси мне камень-ключ.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите камень-ключ Сумеречного каравана. Ключи от сундуков с камнями-ключами должны быть у сумеречных копьеносцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Неплохо.$B$BВид у этой штуки довольно невзрачный, верно?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Знаешь, мы могли бы просто уничтожить врата. Однако у нас такой взрывник, что лучше не рисковать.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Патчу на Тропу Драконьей Пасти на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28091,'Легкая добыча','Нападение из засады прошло, как и было задумано. Мы перебили почти всех охранников, но несколько осталось за фургонами.$B$BОни находятся в ущелье, к западу отсюда. Уничтожь их, чтобы мы могли двинуться дальше.','Убейте 8 сумеречных копьеносцев.','Отлично. Теперь можно начинать наступление на Грим Батол.','Вернитесь к Патчу на Тропу Драконьей Пасти, что на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Легкая добыча',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нападение из засады прошло, как и было задумано. Мы перебили почти всех охранников, но несколько осталось за фургонами.$B$BОни находятся в ущелье, к западу отсюда. Уничтожь их, чтобы мы могли двинуться дальше.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 сумеречных копьеносцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично. Теперь можно начинать наступление на Грим Батол.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Патчу на Тропу Драконьей Пасти, что на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28092,'Если ключ подходит...','Эта штука работает безупречно.','Отправляйтесь на Сумеречное нагорье, в Излучину Змея, и поговорите с Патчем.$B$BЕсли Патч уже не с вами, поговорите с полководцем Кроггом в Излучине Змея.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Если ключ подходит...',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Эта штука работает безупречно.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отправляйтесь на Сумеречное нагорье, в Излучину Змея, и поговорите с Патчем.$B$BЕсли Патч уже не с вами, поговорите с полководцем Кроггом в Излучине Змея.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28093,'Наступление','Врата захвачены. Когда закончите зачистку каньона, мы обсудим с вашими вождями наши дальнейшие действия.','Поговорите с Каленом у входа в Грим Батол на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наступление',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Врата захвачены. Когда закончите зачистку каньона, мы обсудим с вашими вождями наши дальнейшие действия.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Каленом у входа в Грим Батол на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28094,'Прокладывая путь','Мне приказано отправиться вместе с тобой на юг – через врата Драконьей Пасти к входу в Грим Батол. Нам нужно расчистить путь для основных сил, которые и захватят врата.$B$BПеревожу: убивай все, что движется, а если тебе это нравится – тем лучше.$B$BПарни уже рвутся в бой, так что идем.','Пробиваясь к входу в Грим Батол, убейте 30 служителей культа Сумеречного Молота в Излучине Змея.','У нас это ловко получается.','Отправляйтесь на Сумеречное нагорье, в Излучину Змея, и поговорите с Патчем.$B$BЕсли Патч уже не с вами, поговорите с полководцем Кроггом в Излучине Змея.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прокладывая путь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне приказано отправиться вместе с тобой на юг – через врата Драконьей Пасти к входу в Грим Батол. Нам нужно расчистить путь для основных сил, которые и захватят врата.$B$BПеревожу: убивай все, что движется, а если тебе это нравится – тем лучше.$B$BПарни уже рвутся в бой, так что идем.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Пробиваясь к входу в Грим Батол, убейте 30 служителей культа Сумеречного Молота в Излучине Змея.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','У нас это ловко получается.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отправляйтесь на Сумеречное нагорье, в Излучину Змея, и поговорите с Патчем.$B$BЕсли Патч уже не с вами, поговорите с полководцем Кроггом в Излучине Змея.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (28095,'Breadcrumb Out') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Breadcrumb Out',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28096,'Добро пожаловать в систему','Вручите 3 задания.','Ну, как это было? Сбылись твои самые заветные мечты? Впечатляет, не так ли?$B$BНет?$B$B<Дарталия вздыхает.>$B$BДа, вижу, ты боевой, любишь действовать. Наверное, канцелярская работа тебе не очень подходит.','Поговорите с верховным палачом Дарталией у Южных врат в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Добро пожаловать в систему',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вручите 3 задания.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну, как это было? Сбылись твои самые заветные мечты? Впечатляет, не так ли?$B$BНет?$B$B<Дарталия вздыхает.>$B$BДа, вижу, ты боевой, любишь действовать. Наверное, канцелярская работа тебе не очень подходит.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с верховным палачом Дарталией у Южных врат в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (28097,'Врата Грим Батола','Крогг уже пошел в атаку. Он к юго-востоку отсюда, сразу за вратами.$B$BЯ соберу отряд и поведу его в наступление. Увидимся там.','Отправляйтесь в Излучину Змея и поговорите с полководцем Кроггом.','Каньон хорошо укреплен, но ведь с нами драконы. Они отвлекут внимание противника, и это даст нам возможность прорвать линию обороны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Врата Грим Батола',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Крогг уже пошел в атаку. Он к юго-востоку отсюда, сразу за вратами.$B$BЯ соберу отряд и поведу его в наступление. Увидимся там.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Излучину Змея и поговорите с полководцем Кроггом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Каньон хорошо укреплен, но ведь с нами драконы. Они отвлекут внимание противника, и это даст нам возможность прорвать линию обороны.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (28098,'Распорядитель полетов Сумеречного Молота','Наверху на юго-востоке, в Сумеречном гнездилище, расположился сумеречный повелитель небес Рихтофен. Если мы с ним не разделаемся – все наши усилия здесь внизу напрасны, надежды для Скального гнездовья нет.$B$BХоть Сердцерез пока еще слишком слаб, чтобы помочь тебе в бою, он сможет отнести тебя на вершину. Остальное я вверяю тебе, $n.$B$BУдачи.','Летите на Сердцерезе в Сумеречное гнездилище и покончите с сумеречным повелителем небес Рихтофеном.','Вернитесь к Паоке Ходячей Горе в Скальное гнездовье в Тысяче Игл.','Подстрели его с воздуха!','Сумеречный повелитель небес Рихтофен') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Распорядитель полетов Сумеречного Молота',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наверху на юго-востоке, в Сумеречном гнездилище, расположился сумеречный повелитель небес Рихтофен. Если мы с ним не разделаемся – все наши усилия здесь внизу напрасны, надежды для Скального гнездовья нет.$B$BХоть Сердцерез пока еще слишком слаб, чтобы помочь тебе в бою, он сможет отнести тебя на вершину. Остальное я вверяю тебе, $n.$B$BУдачи.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Летите на Сердцерезе в Сумеречное гнездилище и покончите с сумеречным повелителем небес Рихтофеном.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Паоке Ходячей Горе в Скальное гнездовье в Тысяче Игл.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Подстрели его с воздуха!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Сумеречный повелитель небес Рихтофен',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (28099,'Раша\'крак','Из найденной тобой информации можно заключить, что один из приспешников этого "эрцгерцога" уже обратил свое внимание на лагерь Братства Тория.$b$bЕго зовут Раша\'крак, он обитает у озер лавы к югу отсюда. Он похож на тех огненных элементалей, что свирепствуют неподалеку, за одним лишь небольшим исключением: на запястьях у него сковывающие браслеты.$b$bНайди его и принеси мне эти браслеты, $n. Прежде чем мы позволим втянуть себя в войны с элементалями, я хочу быть уверенным, что нам действительно угрожает опасность.','Добудьте сковывающие браслеты Раша\'крака.','Я не стану воевать с элементалями до тех пор, пока не буду уверен, что они представляют для нас угрозу.','Вернитесь к надзирателю Скользоруку в лагерь Братства Тория, что в Тлеющем ущелье.','Он наблюдает за входом в лагерь Братства Тория. Чего он хочет?','Раша\'крак') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Раша\'крак',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Из найденной тобой информации можно заключить, что один из приспешников этого "эрцгерцога" уже обратил свое внимание на лагерь Братства Тория.$b$bЕго зовут Раша\'крак, он обитает у озер лавы к югу отсюда. Он похож на тех огненных элементалей, что свирепствуют неподалеку, за одним лишь небольшим исключением: на запястьях у него сковывающие браслеты.$b$bНайди его и принеси мне эти браслеты, $n. Прежде чем мы позволим втянуть себя в войны с элементалями, я хочу быть уверенным, что нам действительно угрожает опасность.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте сковывающие браслеты Раша\'крака.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я не стану воевать с элементалями до тех пор, пока не буду уверен, что они представляют для нас угрозу.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к надзирателю Скользоруку в лагерь Братства Тория, что в Тлеющем ущелье.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Он наблюдает за входом в лагерь Братства Тория. Чего он хочет?',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Раша\'крак',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (28100,'Говорящий тотем','Деревня фурболгов, что к югу отсюда, – это дом племени Мертвого Леса, заклятых врагов племени Древобрюхов. Как и на многих других, на них тоже подействовала порча этих лесов, приведя их к безумию.$b$bВозле этой деревни происходит что-то необычное. Проходившие там путники рассказывали, что видели у дороги тотем, который разговаривал с ними.$b$bНо я ничего не слышал, хотя много раз проходил мимо. Может быть, этот тотем захочет поговорить с тобой, $n? Может быть, тебе удастся выяснить, в чем дело?','Поговорите с тотемом Роумбо у Деревни Мертвого Леса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Говорящий тотем',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Деревня фурболгов, что к югу отсюда, – это дом племени Мертвого Леса, заклятых врагов племени Древобрюхов. Как и на многих других, на них тоже подействовала порча этих лесов, приведя их к безумию.$b$bВозле этой деревни происходит что-то необычное. Проходившие там путники рассказывали, что видели у дороги тотем, который разговаривал с ними.$b$bНо я ничего не слышал, хотя много раз проходил мимо. Может быть, этот тотем захочет поговорить с тобой, $n? Может быть, тебе удастся выяснить, в чем дело?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с тотемом Роумбо у Деревни Мертвого Леса.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (28101,'Под началом Матиаса','Отправляйтесь в ущелье Драконьей Пасти и поговорите с мастером Матиасом Шоу.','Красные драконы согласились нам помочь! Похоже, тебе пришлось немало потрудиться. От имени Альянса благодарю тебя за помощь.$B$BМы уже подготовили засаду, как вдруг к нам обратились драконы – они отрежут врагу путь к отступлению.$B$BБитва в самом разгаре, и ты можешь в ней поучаствовать.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Под началом Матиаса',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в ущелье Драконьей Пасти и поговорите с мастером Матиасом Шоу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Красные драконы согласились нам помочь! Похоже, тебе пришлось немало потрудиться. От имени Альянса благодарю тебя за помощь.$B$BМы уже подготовили засаду, как вдруг к нам обратились драконы – они отрежут врагу путь к отступлению.$B$BБитва в самом разгаре, и ты можешь в ней поучаствовать.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (28102,'Пришло время для заключительного удара по племени Нефритового Пламени!$b$bЕсли ты $gготов:готова; пройти через их грязный барьер и сразиться с их вожаком, я хочу попросить тебя заодно убить и их младших сатиров. Наши друиды яростно сражаются, но твоя сила не будет лишней.$b$bДай сатирам понять, что им больше не придется властвовать в этих землях!','Убейте 8 разбойников или тенеловов из племени Нефритового Пламени в руинах Констелласа.','Вернитесь к Эридане Грусть Ветра в руины Констелласа, что в Оскверненном лесу.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пришло время для заключительного удара по племени Нефритового Пламени!$b$bЕсли ты $gготов:готова; пройти через их грязный барьер и сразиться с их вожаком, я хочу попросить тебя заодно убить и их младших сатиров. Наши друиды яростно сражаются, но твоя сила не будет лишней.$b$bДай сатирам понять, что им больше не придется властвовать в этих землях!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 разбойников или тенеловов из племени Нефритового Пламени в руинах Констелласа.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Эридане Грусть Ветра в руины Констелласа, что в Оскверненном лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28103,'Легкая добыча','Нападение из засады прошло, как и было задумано. Мы перебили почти всех охранников, но несколько осталось за фургонами.$B$BУничтожь их, чтобы мы могли двинуться дальше.','Убейте 8 сумеречных копьеносцев.','Отлично. Теперь можно начинать наступление на Грим Батол.','Вернитесь к мастеру Матиасу Шоу на Тропу Драконьей Пасти на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Легкая добыча',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нападение из засады прошло, как и было задумано. Мы перебили почти всех охранников, но несколько осталось за фургонами.$B$BУничтожь их, чтобы мы могли двинуться дальше.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 сумеречных копьеносцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично. Теперь можно начинать наступление на Грим Батол.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру Матиасу Шоу на Тропу Драконьей Пасти на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (28104,'Ценный груз','Врата, открывающие проход дальше, заперты. Разведчики сообщают, что караванщики открывают их с помощью особых камней, которые возят в сундуках.$B$BСпустись в ущелье и постарайся раздобыть ключ от такого сундука у одного из убитых охранников. Потом найди фургон с сундуком, открой сундук и принеси мне камень-ключ.','Найдите камень-ключ Сумеречного каравана. Ключи от сундуков с камнями-ключами должны быть у сумеречных копьеносцев.','Неплохо.$B$BВид у этой штуки довольно невзрачный, верно?','Они становятся все самоувереннее. А ведь это погубило множество великих армий.','Вернитесь к мастеру Матиасу Шоу на Тропу Драконьей Пасти, что на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ценный груз',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Врата, открывающие проход дальше, заперты. Разведчики сообщают, что караванщики открывают их с помощью особых камней, которые возят в сундуках.$B$BСпустись в ущелье и постарайся раздобыть ключ от такого сундука у одного из убитых охранников. Потом найди фургон с сундуком, открой сундук и принеси мне камень-ключ.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите камень-ключ Сумеречного каравана. Ключи от сундуков с камнями-ключами должны быть у сумеречных копьеносцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Неплохо.$B$BВид у этой штуки довольно невзрачный, верно?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Они становятся все самоувереннее. А ведь это погубило множество великих армий.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру Матиасу Шоу на Тропу Драконьей Пасти, что на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (28105,'Кавем Бессердечный','Кавем отличался жестокостью еще до объединения неферсетов со Смертокрылом – теперь же его садизм граничит с безумием.$B$BЭто он хранит ключи от наших оков.$B$BНайти его можно в соседнем здании, справа.$B$BРазыщи его и забери у него ключ. Не колеблись и не проявляй сострадания – он при первом удобном случае перерезал бы тебе горло без каких-либо раздумий.','Заберите неферсетский ключ у Кавема Бессердечного.','Ты вернулся. Ключ у тебя?','Вернитесь к принцу Надуну в Затерянный город Тол\'вир в Ульдуме.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кавем Бессердечный',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кавем отличался жестокостью еще до объединения неферсетов со Смертокрылом – теперь же его садизм граничит с безумием.$B$BЭто он хранит ключи от наших оков.$B$BНайти его можно в соседнем здании, справа.$B$BРазыщи его и забери у него ключ. Не колеблись и не проявляй сострадания – он при первом удобном случае перерезал бы тебе горло без каких-либо раздумий.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заберите неферсетский ключ у Кавема Бессердечного.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты вернулся. Ключ у тебя?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к принцу Надуну в Затерянный город Тол\'вир в Ульдуме.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28107,'Прокладывая путь','Мне приказано отправиться вместе с тобой на юг – через врата Драконьей Пасти к входу в Грим Батол. Нам нужно расчистить путь для основных сил, которые и захватят врата.$B$BПеревожу: убивай все, что движется, а если тебе это нравится – тем лучше.$B$BУ парней уже шило в одном месте, так что идем.','Пробиваясь к входу в Грим Батол, убейте 30 служителей культа Сумеречного Молота в Излучине Змея.','У нас это ловко получается.','Поговорите с лейтенантом Высокого берега у Излучины Змея на Сумеречном нагорье.$b$bЕсли потеряете свой отряд, поговорите с мастером Матиасом Шоу на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прокладывая путь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне приказано отправиться вместе с тобой на юг – через врата Драконьей Пасти к входу в Грим Батол. Нам нужно расчистить путь для основных сил, которые и захватят врата.$B$BПеревожу: убивай все, что движется, а если тебе это нравится – тем лучше.$B$BУ парней уже шило в одном месте, так что идем.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Пробиваясь к входу в Грим Батол, убейте 30 служителей культа Сумеречного Молота в Излучине Змея.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','У нас это ловко получается.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с лейтенантом Высокого берега у Излучины Змея на Сумеречном нагорье.$b$bЕсли потеряете свой отряд, поговорите с мастером Матиасом Шоу на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28108,'Если ключ подходит...','Драконы уже вступили в бой в небе над Грим Батолом. Пришло время нам пойти вперед и захватить врата.$B$B$C, знай: ставки очень высоки. Из Грим Батола Сумеречный Молот отправляет подкрепления во все уголки нагорья. Если мы не возьмем город, победы в войне нам не видать.$B$BЯ дам тебе отряд из Высокого берега. Иди на юго-восток, к вратам, и захвати их. За дальнейшими распоряжениями обращайся к своему лейтенанту.','Ведите отряд Высокого берега к закрытым вратам Драконьей Пасти.$B$BЕсли вы потеряете отряд, возвращайтесь к мастеру Матиасу Шоу за новым заданием.','Работает, словно хорошо смазанная машина.','Поговорите с лейтенантом Высокого берега в Излучине Змея на Сумеречное нагорье.$B$BЕсли лейтенант уже не с вами, поговорите с мастером Матиасом Шоу в Излучине Змея.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Если ключ подходит...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Драконы уже вступили в бой в небе над Грим Батолом. Пришло время нам пойти вперед и захватить врата.$B$B$C, знай: ставки очень высоки. Из Грим Батола Сумеречный Молот отправляет подкрепления во все уголки нагорья. Если мы не возьмем город, победы в войне нам не видать.$B$BЯ дам тебе отряд из Высокого берега. Иди на юго-восток, к вратам, и захвати их. За дальнейшими распоряжениями обращайся к своему лейтенанту.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Ведите отряд Высокого берега к закрытым вратам Драконьей Пасти.$B$BЕсли вы потеряете отряд, возвращайтесь к мастеру Матиасу Шоу за новым заданием.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Работает, словно хорошо смазанная машина.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с лейтенантом Высокого берега в Излучине Змея на Сумеречное нагорье.$B$BЕсли лейтенант уже не с вами, поговорите с мастером Матиасом Шоу в Излучине Змея.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28109,'Наступление','Пока ты действуешь неплохо.$B$BЗа следующими вратами должен быть вход в Грим Батол. Мне приказали захватить этот вход и удерживать до подхода основных сил.$B$BИдем по ущелью на юго-запад. Врата должны быть где-то недалеко.','Проведите ваш отряд через северные врата Драконьей Пасти к входу в Грим Батол.$B$BЕсли вы потеряете отряд, возвращайтесь в Излучину Змея к мастеру Матиасу Шоу.','Врата захвачены. Когда закончите зачистку ущелья, мы обсудим с вашими командирами наши дальнейшие действия.','Поговорите с Каленом у входа в Грим Батол на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наступление',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пока ты действуешь неплохо.$B$BЗа следующими вратами должен быть вход в Грим Батол. Мне приказали захватить этот вход и удерживать до подхода основных сил.$B$BИдем по ущелью на юго-запад. Врата должны быть где-то недалеко.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проведите ваш отряд через северные врата Драконьей Пасти к входу в Грим Батол.$B$BЕсли вы потеряете отряд, возвращайтесь в Излучину Змея к мастеру Матиасу Шоу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Врата захвачены. Когда закончите зачистку ущелья, мы обсудим с вашими командирами наши дальнейшие действия.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Каленом у входа в Грим Батол на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (28110,'Breadcrumb Out') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Breadcrumb Out',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`) VALUES (28111,'На нашей паучьей ферме у Лазуритового рудника застой. Капитан Кейтон потребовал, чтобы мы немедленно прислали помощь. Кейтон жалуется на то, что рудниковые пауки отказываются подчиняться и разбегаются. Кроме того, группа береговых мурлоков ворует наши припасы. Я хочу, чтобы ты $gотправился:отправилась; туда и $gразобрался:разобралась;, в чем дело. Помоги Кейтону и укротителю пауков, $n.$b$bЛазуритовый рудник находится на берегу, к юго-востоку отсюда.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На нашей паучьей ферме у Лазуритового рудника застой. Капитан Кейтон потребовал, чтобы мы немедленно прислали помощь. Кейтон жалуется на то, что рудниковые пауки отказываются подчиняться и разбегаются. Кроме того, группа береговых мурлоков ворует наши припасы. Я хочу, чтобы ты $gотправился:отправилась; туда и $gразобрался:разобралась;, в чем дело. Помоги Кейтону и укротителю пауков, $n.$b$bЛазуритовый рудник находится на берегу, к юго-востоку отсюда.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (28112,'Бегство из Затерянного города','Все готово! Сними с меня цепи и освободи своих друзей.$B$BМы должны действовать быстро, пока неферсеты не догадались, что мы затеяли!$B$BЕсли у нас все получится, загляни потом к моему брату, королю Фаорису, за наградой.','Освободите принца Надуна и поговорите с королем Фаорисом в Рамкахене в Ульдуме.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бегство из Затерянного города',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Все готово! Сними с меня цепи и освободи своих друзей.$B$BМы должны действовать быстро, пока неферсеты не догадались, что мы затеяли!$B$BЕсли у нас все получится, загляни потом к моему брату, королю Фаорису, за наградой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Освободите принца Надуна и поговорите с королем Фаорисом в Рамкахене в Ульдуме.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (28113,'Пройти через непроходимое','Теперь, когда у нас есть этот коготь, мы готовы прорвать оборону племени Нефритового Пламени.$b$bОтправляйся в руины, что к северо-западу от нас. Ты найдешь узкий проход в линии обороны сатиров, который ведет к их оскверненному лунному колодцу. Путь к нему преграждает огромная стена демонического пламени, но коготь Тихондрия поможет тебе рассеять его.$b$bЗа барьером ты увидишь их вожака, Ксаватраса, который охраняет оскверненный лунный колодец. Убей его!','Убейте Ксаватраса.','Вот видишь, что значит работать в команде?$B$BКоготь я передам тем, у кого достаточно ответственности для обладания такими вещами… учитывая то, что уничтожить его невозможно.','Вернитесь к чародейке Деларис в руины Констелласа, что в Оскверненном лесу.','Герцог племени Нефритового Пламени','Ксаватрас') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пройти через непроходимое',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда у нас есть этот коготь, мы готовы прорвать оборону племени Нефритового Пламени.$b$bОтправляйся в руины, что к северо-западу от нас. Ты найдешь узкий проход в линии обороны сатиров, который ведет к их оскверненному лунному колодцу. Путь к нему преграждает огромная стена демонического пламени, но коготь Тихондрия поможет тебе рассеять его.$b$bЗа барьером ты увидишь их вожака, Ксаватраса, который охраняет оскверненный лунный колодец. Убей его!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Ксаватраса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот видишь, что значит работать в команде?$B$BКоготь я передам тем, у кого достаточно ответственности для обладания такими вещами… учитывая то, что уничтожить его невозможно.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к чародейке Деларис в руины Констелласа, что в Оскверненном лесу.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Герцог племени Нефритового Пламени',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Ксаватрас',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (28114,'Славный урожай','Соберите 60 яиц ползунов.','Чудесно! А теперь положи эти яйца в уютную темную нишу в глубине рудника и дай свершиться чуду!','Как урожай?','Принесите яйца ползунов укротительнице пауков Сарус в Лазуритовый рудник, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Славный урожай',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 60 яиц ползунов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Чудесно! А теперь положи эти яйца в уютную темную нишу в глубине рудника и дай свершиться чуду!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как урожай?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите яйца ползунов укротительнице пауков Сарус в Лазуритовый рудник, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28115,'Они свое отжили','Медведи – бездушные твари, как будто бы созданные лишь для того, чтобы мучить нас. Только благодаря нашей изобретательности мы научились извлекать из них какую-то пользу! Мы используем медведей, как ходячую паучью ферму. Наши пауки откладывают яйца под шкуру медведей, и яйца растут, получая питание из медвежьей плоти и крови.$b$bА после того, как медведи выполнили свое предназначение, от них надо избавиться. Отправляйся на юго-восток и убей зараженных медведей, которые нам уже не пригодятся.','Убейте 8 зараженных медведей.','Боги, создающие медведей, – жестоки. Они не перестанут населять этот мир медведями до самого конца света. И у нас, как у цивилизованных людей, есть право по крайней мере получить пользу от этих ничтожных созданий – для блага всех нас!','Поговорите с укротительницей пауков Сарус в Лазуритовом руднике, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Они свое отжили',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Медведи – бездушные твари, как будто бы созданные лишь для того, чтобы мучить нас. Только благодаря нашей изобретательности мы научились извлекать из них какую-то пользу! Мы используем медведей, как ходячую паучью ферму. Наши пауки откладывают яйца под шкуру медведей, и яйца растут, получая питание из медвежьей плоти и крови.$b$bА после того, как медведи выполнили свое предназначение, от них надо избавиться. Отправляйся на юго-восток и убей зараженных медведей, которые нам уже не пригодятся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 зараженных медведей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Боги, создающие медведей, – жестоки. Они не перестанут населять этот мир медведями до самого конца света. И у нас, как у цивилизованных людей, есть право по крайней мере получить пользу от этих ничтожных созданий – для блага всех нас!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с укротительницей пауков Сарус в Лазуритовом руднике, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28116,'Плачущие фиалки','Мы должны тщательно подготовиться к нападению на Джеденар. Чернокнижники и демоны Джеденара сильны, и прежде чем мы попадем туда, нам нужно обзавестись стражами.$b$bЯ собрала много трав, мне не хватает всего лишь одного ингредиента: плачущей фиалки, которая растет на холмах к северо-западу отсюда.$b$bСобери для меня плачущие фиалки, а потом разыщи в поле моего помощника. Он знает, что делать дальше.','Соберите 8 плачущих фиалок.','Чудесно. Грета правильно сделала, что поручила тебе это задание. Я сейчас же займусь травами…','Отнесите плачущие фиалки Андалару Дольной Тени в Джеденар, что в Оскверненном лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Плачущие фиалки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы должны тщательно подготовиться к нападению на Джеденар. Чернокнижники и демоны Джеденара сильны, и прежде чем мы попадем туда, нам нужно обзавестись стражами.$b$bЯ собрала много трав, мне не хватает всего лишь одного ингредиента: плачущей фиалки, которая растет на холмах к северо-западу отсюда.$b$bСобери для меня плачущие фиалки, а потом разыщи в поле моего помощника. Он знает, что делать дальше.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 плачущих фиалок.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Чудесно. Грета правильно сделала, что поручила тебе это задание. Я сейчас же займусь травами…',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите плачущие фиалки Андалару Дольной Тени в Джеденар, что в Оскверненном лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (28117,'Очищение Проклятых глубин','Твое присутствие воодушевляет нас, $n. Битва за Тол Барад только началась.$B$BК востоку отсюда мы обнаружили темницу, которую следует освободить от нечисти. В ней находится множество призраков, которые томятся там уже долгое время.$b$bУбей столько нечисти, сколько сможешь, и доложи мне о выполненном задании.','Вам поручено убить 9 любых призраков в Проклятых глубинах, расположенных к востоку от крепости Барадин.','Доложите командиру Стивенсу в крепости Барадин о выполнении задания.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Очищение Проклятых глубин',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Твое присутствие воодушевляет нас, $n. Битва за Тол Барад только началась.$B$BК востоку отсюда мы обнаружили темницу, которую следует освободить от нечисти. В ней находится множество призраков, которые томятся там уже долгое время.$b$bУбей столько нечисти, сколько сможешь, и доложи мне о выполненном задании.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вам поручено убить 9 любых призраков в Проклятых глубинах, расположенных к востоку от крепости Барадин.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доложите командиру Стивенсу в крепости Барадин о выполнении задания.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (28118,'Верховный маг в заточении','Мы пытались зачистить тюремный блок в Проклятых глубинах со времен высадки на Тол Бараде. Всякий раз, как мы приближаемся к этой цели, появляется верховный маг, который рушит все наши планы.$B$BСейчас же, когда остров в наших руках, стоит попробовать снова. Направляйся вниз и доставь мне его посох в доказательство выполнения задания.','Убейте верховного мага Галия в Проклятых глубинах к востоку от крепости Барадин и заберите его посох.','Тебе удалось одолеть верховного мага?','Доложите командиру Стивенсу в крепости Барадин о выполнении задания.','Недолго ему осталось владеть этим посохом.','Верховный маг Галий') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Верховный маг в заточении',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы пытались зачистить тюремный блок в Проклятых глубинах со времен высадки на Тол Бараде. Всякий раз, как мы приближаемся к этой цели, появляется верховный маг, который рушит все наши планы.$B$BСейчас же, когда остров в наших руках, стоит попробовать снова. Направляйся вниз и доставь мне его посох в доказательство выполнения задания.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте верховного мага Галия в Проклятых глубинах к востоку от крепости Барадин и заберите его посох.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось одолеть верховного мага?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доложите командиру Стивенсу в крепости Барадин о выполнении задания.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Недолго ему осталось владеть этим посохом.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Верховный маг Галий',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (28120,'Уроки прошлого','Теперь, когда мы закрепились на этом проклятом острове, нужно попытаться установить, что его привело к нынешнему состоянию. Наши воины обнаружили несколько журналов с записями, разбросанных вблизи входа в тюремный блок в Проклятых глубинах к востоку отсюда.$B$BЭти журналы представляют особый интерес для наших старейшин. Как можно быстрее отыщи четыре журнала и доставь их в лагерь.$B$BБудь $gосторожен:осторожна;, $n: в той местности бродит много нежити.','Найдите 4 пыльных тюремных журнала в Проклятых глубинах к востоку от крепости Барадин.','Тебе удалось отыскать журналы? Мне доложили, что они находятся как внутри, так и снаружи тюремных камер.','Доложите командиру Стивенсу в крепости Барадин о выполнении задания.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уроки прошлого',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда мы закрепились на этом проклятом острове, нужно попытаться установить, что его привело к нынешнему состоянию. Наши воины обнаружили несколько журналов с записями, разбросанных вблизи входа в тюремный блок в Проклятых глубинах к востоку отсюда.$B$BЭти журналы представляют особый интерес для наших старейшин. Как можно быстрее отыщи четыре журнала и доставь их в лагерь.$B$BБудь $gосторожен:осторожна;, $n: в той местности бродит много нежити.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите 4 пыльных тюремных журнала в Проклятых глубинах к востоку от крепости Барадин.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось отыскать журналы? Мне доложили, что они находятся как внутри, так и снаружи тюремных камер.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доложите командиру Стивенсу в крепости Барадин о выполнении задания.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (28121,'Силы Джеденара','В порче, охватившей эти земли, виновен Совет Теней. В Джеденаре, что к северо-западу отсюда, члены Совета Теней поклоняются демонам Пылающего Легиона и пытаются помочь своим хозяевам вернуться в этот мир.$b$bЗемли Джеденара охраняются джеденарскими гончими, стражами, адептами и сектантами, за которыми стоят еще более злые силы. Их нужно убить в первую очередь, чтобы прекратить мучения здешних лесов.','Убейте 12 любых джеденарских прислужников.','Встретьте Андалара Дольную Тень в Джеденаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Силы Джеденара',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В порче, охватившей эти земли, виновен Совет Теней. В Джеденаре, что к северо-западу отсюда, члены Совета Теней поклоняются демонам Пылающего Легиона и пытаются помочь своим хозяевам вернуться в этот мир.$b$bЗемли Джеденара охраняются джеденарскими гончими, стражами, адептами и сектантами, за которыми стоят еще более злые силы. Их нужно убить в первую очередь, чтобы прекратить мучения здешних лесов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 любых джеденарских прислужников.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Встретьте Андалара Дольную Тень в Джеденаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (28122,'Гигантская проблема','Стоило нам захватить этот проклятый остров, как в окрестностях тут же обнаружился гигантский эттин, который стал нападать на наши патрули!$B$B$n, договорись с друзьями и подкарауль этого громилу. Нельзя допустить, чтоб такое чудище разгуливало на свободе и сеяло разрушения.$B$BБудь $gосторожен:осторожна;, мне донесли, что он вооружен огромным поленом, которое любит пускать в дело.','Избавьтесь от Проблима, гигантского эттина, бродящего по тропам Тол Барада.','Неужели ты и вправду прикончил его? Даже не верится.','Доложите сержанту Паркеру в крепости Барадин о выполнении задания.','Ну и зверюга.','Проблим') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гигантская проблема',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Стоило нам захватить этот проклятый остров, как в окрестностях тут же обнаружился гигантский эттин, который стал нападать на наши патрули!$B$B$n, договорись с друзьями и подкарауль этого громилу. Нельзя допустить, чтоб такое чудище разгуливало на свободе и сеяло разрушения.$B$BБудь $gосторожен:осторожна;, мне донесли, что он вооружен огромным поленом, которое любит пускать в дело.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Избавьтесь от Проблима, гигантского эттина, бродящего по тропам Тол Барада.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Неужели ты и вправду прикончил его? Даже не верится.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доложите сержанту Паркеру в крепости Барадин о выполнении задания.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Ну и зверюга.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Проблим',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (28123,'Демоническая цепь','Добудьте демоническую цепь.','<Зела берет окровавленную цепь и наматывает ее на запястье.>$B$BСилнор, если легенды не врут, то именно к этой цепи Смертокрыл когда-то прицепил душу демона. С помощью души демона он собирался управлять всеми остальными драконами. Душа демона уже давно уничтожена, но, возможно, частица ее силы сохранилась в этом кусочке элементия...$B$BСегодня тебе удалось совершить великий подвиг.','Цепь у тебя? Да? Ведь от нее зависит судьба Драконьей Пасти!','Отнесите демоническую цепь Зеле в Кровавое ущелье на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Демоническая цепь',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте демоническую цепь.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Зела берет окровавленную цепь и наматывает ее на запястье.>$B$BСилнор, если легенды не врут, то именно к этой цепи Смертокрыл когда-то прицепил душу демона. С помощью души демона он собирался управлять всеми остальными драконами. Душа демона уже давно уничтожена, но, возможно, частица ее силы сохранилась в этом кусочке элементия...$B$BСегодня тебе удалось совершить великий подвиг.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Цепь у тебя? Да? Ведь от нее зависит судьба Драконьей Пасти!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите демоническую цепь Зеле в Кровавое ущелье на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (28124,'К бастиону','$n, пока вы с детенышами гордокрылов разбирались с Сумеречным повелителем небес Рихтофеном, заходила Лакота Песня Ветра. Она передала, что будет ждать тебя на востоке, возле бастиона Сумрака.$B$BДолжно быть, именно там они держат Магату Зловещий Тотем.','Обратитесь к Лакоте Песне Ветра возле бастиона Сумрака в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','К бастиону',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, пока вы с детенышами гордокрылов разбирались с Сумеречным повелителем небес Рихтофеном, заходила Лакота Песня Ветра. Она передала, что будет ждать тебя на востоке, возле бастиона Сумрака.$B$BДолжно быть, именно там они держат Магату Зловещий Тотем.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обратитесь к Лакоте Песне Ветра возле бастиона Сумрака в Тысяче Игл.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (28125,'Неприметная одежка','Я, кажется, знаю, как тебе подобраться к их главарям, не рискуя жизнью. Но сначала нужно переодеться.$B$BИди и отними у кого-нибудь из них доспехи.','Раздобудьте 10 частей доспеха Сумеречного Молота.','Вернитесь к Лакоте Песне Ветра к бастиону Сумрака в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Неприметная одежка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я, кажется, знаю, как тебе подобраться к их главарям, не рискуя жизнью. Но сначала нужно переодеться.$B$BИди и отними у кого-нибудь из них доспехи.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте 10 частей доспеха Сумеречного Молота.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лакоте Песне Ветра к бастиону Сумрака в Тысяче Игл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (28127,'Вызволи их','Магата не единственная, кого пленил клан Сумеречного Молота.$B$BКогда окажешься там, на юге, постарайся вызволить как можно больше пленников.','Отбейте 5 узников бастиона у сумеречных тюремщиков.','Вернитесь к Лакоте Песне Ветра к бастиону Сумрака в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вызволи их',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Магата не единственная, кого пленил клан Сумеречного Молота.$B$BКогда окажешься там, на юге, постарайся вызволить как можно больше пленников.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отбейте 5 узников бастиона у сумеречных тюремщиков.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лакоте Песне Ветра к бастиону Сумрака в Тысяче Игл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (28128,'Внутренний круг','Теперь, когда мы избавились от стражей, на очереди более значимые члены Совета Теней.$b$bВ глубине оскверненной обители ты встретишь могущественных джеденарских чернокнижников, охотников, головорезов, темноплетов и легионеров.$b$bЕсли мы хотим спасти эти земли, они должны быть убиты!','Убейте 12 защитников Оплота Теней.','Вернитесь к Джессире Лунной Радуге в Лагерь Дикого Сердца, что в Оскверненном лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Внутренний круг',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда мы избавились от стражей, на очереди более значимые члены Совета Теней.$b$bВ глубине оскверненной обители ты встретишь могущественных джеденарских чернокнижников, охотников, головорезов, темноплетов и легионеров.$b$bЕсли мы хотим спасти эти земли, они должны быть убиты!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 защитников Оплота Теней.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джессире Лунной Радуге в Лагерь Дикого Сердца, что в Оскверненном лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (28129,'Демонический принц','Убейте принца Ксавалиуса.','Вожак сатиров племени Нефритового Пламени','Принц Ксавалис','Легион будет изгнан из этих мест!','Андалар Дольная Тень') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Демонический принц',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте принца Ксавалиуса.',`objectives_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Вожак сатиров племени Нефритового Пламени',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Принц Ксавалис',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Легион будет изгнан из этих мест!',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Андалар Дольная Тень',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (28130,'Неприветливый город','Ты уже $gбывал:бывала; в Растберге, $n? Советую припасти нож за пазухой, если пойдешь в те края.$b$bТамошние жители вроде бы не доставляют хлопот, вот только что-то странное там творится. Мне докладывают о том, что там периодически пропадают наши солдаты. Нам это порядком поднадоело, поэтому тебе следует отправиться в этот вертеп и навести там порядок.$B$BПеребей там столько народу, сколько сможешь, и отчитайся передо мной о проделанной работе.','Командир Марк Джонсон поручил вам расправиться с 14 жителями Растберга. Растберг расположен в правой части острова, к северу от лагеря.','Когда закончите, явитесь к командиру Марку Джонсону в Лагерь Барадин.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Неприветливый город',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты уже $gбывал:бывала; в Растберге, $n? Советую припасти нож за пазухой, если пойдешь в те края.$b$bТамошние жители вроде бы не доставляют хлопот, вот только что-то странное там творится. Мне докладывают о том, что там периодически пропадают наши солдаты. Нам это порядком поднадоело, поэтому тебе следует отправиться в этот вертеп и навести там порядок.$B$BПеребей там столько народу, сколько сможешь, и отчитайся передо мной о проделанной работе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Командир Марк Джонсон поручил вам расправиться с 14 жителями Растберга. Растберг расположен в правой части острова, к северу от лагеря.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Когда закончите, явитесь к командиру Марку Джонсону в Лагерь Барадин.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (28131,'Две искусительницы','Моора и Салия – личные прислужницы Владыки теней Скверн\'дана. Не позволяй им обмануть себя!$b$bЭти грязные суккубы пользуются своим коварством и магией, чтобы заманивать смертных в Оплот Теней. Тех, кто попал в их западню, подвергают промывке мозгов или приносят в жертву демоническим хозяевам Скверн\'дана.$b$bМоора и Салия никогда не расстаются, поэтому поодиночке с ними не справиться, что делает твою задачу гораздо сложнее. Продвигайся дальше в Оплот Теней и убей их.','Убейте Моору и Салию.','Тебе нужно устоять перед этим гибельным соблазном.','Моора и Салия','Скверн\'дан должен пасть!','Андалар Дольная Тень') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Две искусительницы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Моора и Салия – личные прислужницы Владыки теней Скверн\'дана. Не позволяй им обмануть себя!$b$bЭти грязные суккубы пользуются своим коварством и магией, чтобы заманивать смертных в Оплот Теней. Тех, кто попал в их западню, подвергают промывке мозгов или приносят в жертву демоническим хозяевам Скверн\'дана.$b$bМоора и Салия никогда не расстаются, поэтому поодиночке с ними не справиться, что делает твою задачу гораздо сложнее. Продвигайся дальше в Оплот Теней и убей их.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Моору и Салию.',`objectives_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Тебе нужно устоять перед этим гибельным соблазном.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Моора и Салия',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Скверн\'дан должен пасть!',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Андалар Дольная Тень',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (28132,'"Эффективные раскопки"','В руководстве описаны нелепые теории о том, как эффективно управлять большим рабочим коллективом при осуществлении крупномасштабных проектов по раскопке.$B$BПробежав глазами текст, вы понимаете, что автор книги, скорее всего, и заправляет здешними не в меру агрессивными мародерами.$B$BКарта на обороте книги показывает некий бункер на юго-западе Ульдума, где скрывается автор.$B$BВозможно, выпадет шанс взять автограф.','Принесите "Эффективные раскопки" Беллоку Сияющему Клинку в лагерь Шнотца.','Поглядите, это же карикатура на малютку Шнотци.$B$BЯ это у тебя заберу, если не возражаешь.','Вам остается предполагать, что на обложке изображен ушедший в себя автор.','Шнотц') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','"Эффективные раскопки"',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В руководстве описаны нелепые теории о том, как эффективно управлять большим рабочим коллективом при осуществлении крупномасштабных проектов по раскопке.$B$BПробежав глазами текст, вы понимаете, что автор книги, скорее всего, и заправляет здешними не в меру агрессивными мародерами.$B$BКарта на обороте книги показывает некий бункер на юго-западе Ульдума, где скрывается автор.$B$BВозможно, выпадет шанс взять автограф.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите "Эффективные раскопки" Беллоку Сияющему Клинку в лагерь Шнотца.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Поглядите, это же карикатура на малютку Шнотци.$B$BЯ это у тебя заберу, если не возражаешь.',`offerrewardtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Вам остается предполагать, что на обложке изображен ушедший в себя автор.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Шнотц',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (28133,'Освобожденная ярость','Доберитесь до Глотки и поговорите с Зелой. Убейте Торза.','Освободившись от этой цепи, Торз предпочел смерть рабству. Я восхищаюсь этим существом. И прикажу сделать доспехи из его шкуры.$B$BМне стало понятно одно: Драконья Пасть не выстоит в борьбе против Громового Молота и Альянса. Наркралл доказал это. А тебе удалось неоднократно продемонстрировать мощь Орды. $B$BЯ восстановлю наши отряды драконов и займу позиции за Сумеречным бастионом. А тебе нужно и дальше помогать нам – как в Глотке, так и в других частях нагорья.','Поговорите с Зелой в Глотке на Сумеречном нагорье.','Встретимся в Глотке и вместе прикончим Торза.','Торз Прожорливый') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Освобожденная ярость',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доберитесь до Глотки и поговорите с Зелой. Убейте Торза.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Освободившись от этой цепи, Торз предпочел смерть рабству. Я восхищаюсь этим существом. И прикажу сделать доспехи из его шкуры.$B$BМне стало понятно одно: Драконья Пасть не выстоит в борьбе против Громового Молота и Альянса. Наркралл доказал это. А тебе удалось неоднократно продемонстрировать мощь Орды. $B$BЯ восстановлю наши отряды драконов и займу позиции за Сумеречным бастионом. А тебе нужно и дальше помогать нам – как в Глотке, так и в других частях нагорья.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Зелой в Глотке на Сумеречном нагорье.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Встретимся в Глотке и вместе прикончим Торза.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Торз Прожорливый',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28134,'Неминуемая расплата','Теперь, когда тебя достойно наградили, хочу поговорить начистоту, без обиняков.$B$BТы $gсослужил:сослужила; моему королевству великую службу, но вместе с этим $gнарушил:нарушила; хрупкий процесс мирных переговоров.$B$BЯ добивался освобождения моего брата всецело дипломатическими методами в попытке избежать кровопролития.$B$BТеперь же наш враг наверняка захочет с нами поквитаться.$B$BПоговори с Номарком Тенетом в Угодьях Тарет на востоке, жрецом Солнца Асарисом на севере, у Печати Солнечного короля, и с Асаком возле Мар\'ата, что на западе. Выясни, куда противник собирается нанести удар.','Побеседуйте с Номарком Тенетом в Угодьях Тарет, жрецом Солнца Асарисом у Печати Солнечного короля и с Асаком возле Мар\'ата.','Орсис! Ну конечно!$B$BКак я мог не догадаться?!','Вернитесь к королю Фаорису в Рамкахен, что в Ульдуме.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Неминуемая расплата',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда тебя достойно наградили, хочу поговорить начистоту, без обиняков.$B$BТы $gсослужил:сослужила; моему королевству великую службу, но вместе с этим $gнарушил:нарушила; хрупкий процесс мирных переговоров.$B$BЯ добивался освобождения моего брата всецело дипломатическими методами в попытке избежать кровопролития.$B$BТеперь же наш враг наверняка захочет с нами поквитаться.$B$BПоговори с Номарком Тенетом в Угодьях Тарет на востоке, жрецом Солнца Асарисом на севере, у Печати Солнечного короля, и с Асаком возле Мар\'ата, что на западе. Выясни, куда противник собирается нанести удар.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Побеседуйте с Номарком Тенетом в Угодьях Тарет, жрецом Солнца Асарисом у Печати Солнечного короля и с Асаком возле Мар\'ата.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Орсис! Ну конечно!$B$BКак я мог не догадаться?!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к королю Фаорису в Рамкахен, что в Ульдуме.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (28135,'Месть Ал\'акира','Послушай, $n. На Орсис налетела не обычная песчаная буря. То было нападение слуг Ал\'акира.$B$BЭлементаль – повелитель воздуха – верный союзник Смертокрыла, и то, что когда-нибудь он натравит своих слуг на мой народ, было лишь вопросом времени.$B$BНападение на Орсис было предупреждением для нас. Нужно скорее помочь нашим братьям.$B$BРазыщи Надуна у торговой лавки Арсад около Мар\'ата. А я начну хлопотать о беженцах и раненых.','Поговорите с принцем Надуном у торговой лавки Арсад возле Мар\'ата в Ульдуме.','Смотри, что натворили прислужники Смертокрыла! Великий Орсис почти целиком погребен в песках!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Месть Ал\'акира',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Послушай, $n. На Орсис налетела не обычная песчаная буря. То было нападение слуг Ал\'акира.$B$BЭлементаль – повелитель воздуха – верный союзник Смертокрыла, и то, что когда-нибудь он натравит своих слуг на мой народ, было лишь вопросом времени.$B$BНападение на Орсис было предупреждением для нас. Нужно скорее помочь нашим братьям.$B$BРазыщи Надуна у торговой лавки Арсад около Мар\'ата. А я начну хлопотать о беженцах и раненых.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с принцем Надуном у торговой лавки Арсад возле Мар\'ата в Ульдуме.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Смотри, что натворили прислужники Смертокрыла! Великий Орсис почти целиком погребен в песках!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28136,'Осторожно, сзади!','Теперь, когда эти трое мертвы, объединенные силы заставы Вольного Ветра сумеют расправиться с оставшимися здесь сектантами.','Вернитесь к Лакоте Песне Ветра к бастиону Сумрака в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Осторожно, сзади!',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь, когда эти трое мертвы, объединенные силы заставы Вольного Ветра сумеют расправиться с оставшимися здесь сектантами.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лакоте Песне Ветра к бастиону Сумрака в Тысяче Игл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (28137,'Научи человека ловить рыбу... Или красть ее!','Растберг. Это место – одновременно наше проклятье и благословение, $n. Понятия не имею, где эти разбойники научились ловить рыбу, но это и не важно.$B$BОтправляйся к ним в логово и укради столько рыбы, сколько сможешь. Мы питаемся всякими отбросами с тех пор, как вновь заняли этот остров, поэтому было бы неплохо пополнить запасы провизии.$B$BБудь $gосторожен:осторожна;, мне доложили, что в деревне нас может поджидать засада.','Вам нужно украсть 22 растбергских окуня. Рыба сушится на нитях на специальных стойках у причала за деревней. Растберг расположен на северо-востоке острова, к северу от лагеря.','Получилось пробраться туда и украсть рыбешки?','Когда закончите, явитесь к командиру Марку Джонсону в Лагерь Барадин.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Научи человека ловить рыбу... Или красть ее!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Растберг. Это место – одновременно наше проклятье и благословение, $n. Понятия не имею, где эти разбойники научились ловить рыбу, но это и не важно.$B$BОтправляйся к ним в логово и укради столько рыбы, сколько сможешь. Мы питаемся всякими отбросами с тех пор, как вновь заняли этот остров, поэтому было бы неплохо пополнить запасы провизии.$B$BБудь $gосторожен:осторожна;, мне доложили, что в деревне нас может поджидать засада.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вам нужно украсть 22 растбергских окуня. Рыба сушится на нитях на специальных стойках у причала за деревней. Растберг расположен на северо-востоке острова, к северу от лагеря.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Получилось пробраться туда и украсть рыбешки?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Когда закончите, явитесь к командиру Марку Джонсону в Лагерь Барадин.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28138,'Заражение людьми','Возьмите в плен 8 жителей Хилсбрада.','Эти прекрасно подойдут. Интересно, какие на них планы у надзирателя. Последнее, что я слышал о Топких полях, – это что там творится что-то очень нехорошее.','Вернитесь к капитану Кейтону в Лазуритовый рудник, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Заражение людьми',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возьмите в плен 8 жителей Хилсбрада.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Эти прекрасно подойдут. Интересно, какие на них планы у надзирателя. Последнее, что я слышал о Топких полях, – это что там творится что-то очень нехорошее.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Кейтону в Лазуритовый рудник, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (28139,'Код шифровальщика','$n, оковы, в которые заточена Магата, закодированы. Мы сможем ее вызволить, только если раздобудем коды.$B$BНа юго-востоке бастиона подле шифровальщика Дитака стоит некое устройство. В нем содержатся коды.$B$BРаздобудь их, сделай милость.','Раздобудьте коды шифровальщика.','Отлично. Осталось сделать только одно.','Ты раздобыл коды от оков мудрой старицы?','Вернитесь к Лакоте Песне Ветра к бастиону Сумрака в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Код шифровальщика',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, оковы, в которые заточена Магата, закодированы. Мы сможем ее вызволить, только если раздобудем коды.$B$BНа юго-востоке бастиона подле шифровальщика Дитака стоит некое устройство. В нем содержатся коды.$B$BРаздобудь их, сделай милость.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте коды шифровальщика.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично. Осталось сделать только одно.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты раздобыл коды от оков мудрой старицы?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лакоте Песне Ветра к бастиону Сумрака в Тысяче Игл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (28140,'Мудрая старица','У тебя есть код. Отправляйся же в восточную часть бастиона и освободи мудрую старицу.$B$BУдачи, $n. И спасибо тебе за все.','Отключите контроллер оков Магаты.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мудрая старица',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У тебя есть код. Отправляйся же в восточную часть бастиона и освободи мудрую старицу.$B$BУдачи, $n. И спасибо тебе за все.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отключите контроллер оков Магаты.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (28141,'Реликвии Солнечного короля','Раздобудьте 4 реликвии Солнечного короля.','Благодарю тебя. Похоже, молва о тебе и в самом деле правдива.','Улыбнулась ли тебе удача?','Вернитесь к жрецу Солнца Асарису в Ульдуме.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Реликвии Солнечного короля',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте 4 реликвии Солнечного короля.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Благодарю тебя. Похоже, молва о тебе и в самом деле правдива.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Улыбнулась ли тебе удача?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к жрецу Солнца Асарису в Ульдуме.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (28142,'Дорога в пустошь','Магата сказала, что будет ждать тебя возле Сумеречной пустоши, что к востоку отсюда.','Обратитесь к Магате Зловещий Тотем в Сумеречной пустоши в Тысяче Игл.','Долго же ты шел... Думаешь, мы тут в бирюльки играем?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дорога в пустошь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Магата сказала, что будет ждать тебя возле Сумеречной пустоши, что к востоку отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обратитесь к Магате Зловещий Тотем в Сумеречной пустоши в Тысяче Игл.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Долго же ты шел... Думаешь, мы тут в бирюльки играем?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (28143,'Дорога в пустошь','Не заставляй мудрую старицу ждать, $n.$B$BОна сказала, что пойдет к вершине и будет ждать возле Сумеречной пустоши, что к востоку отсюда.','Обратитесь к Магате Зловещий Тотем в Сумеречной пустоши в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дорога в пустошь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не заставляй мудрую старицу ждать, $n.$B$BОна сказала, что пойдет к вершине и будет ждать возле Сумеречной пустоши, что к востоку отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обратитесь к Магате Зловещий Тотем в Сумеречной пустоши в Тысяче Игл.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (28144,'Маленькие грязные воришки!','Верните 6 "припасов" из лагеря Отрекшихся.','Вернитесь к капитану Кейтону в Лазуритовый рудник, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Маленькие грязные воришки!',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните 6 "припасов" из лагеря Отрекшихся.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Кейтону в Лазуритовый рудник, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (28145,'Противоядие','Наполните колбу для антидота ядом 8 трупов ядокровых скорпидов.','Вернитесь к служителю Солнца Асарису к Печати Солнечного короля в Ульдуме.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Противоядие',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Наполните колбу для антидота ядом 8 трупов ядокровых скорпидов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к служителю Солнца Асарису к Печати Солнечного короля в Ульдуме.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (28146,'Деликатесы с побережья','Мои пауки голодны и нервничают! Они не ели уже несколько дней и начинают подбираться к людям, которых мы держим в плену. С этим нельзя смириться. Люди нам еще пригодятся в Топких полях.$b$bЯ хочу, чтобы ты $gвыпустил:выпустила; одного из моих голодных рудниковых пауков и $gнакормил:накормила; его мурлоками с Западного побережья, что к югу отсюда. Сколько ни убьешь – он все съест! Чем больше, тем лучше!','Убейте 12 мурлоков на Западном побережье, чтобы накормить голодного рудникового паука.','Вернитесь к укротительнице пауков Сарус в Лазуритовый рудник, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Деликатесы с побережья',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мои пауки голодны и нервничают! Они не ели уже несколько дней и начинают подбираться к людям, которых мы держим в плену. С этим нельзя смириться. Люди нам еще пригодятся в Топких полях.$b$bЯ хочу, чтобы ты $gвыпустил:выпустила; одного из моих голодных рудниковых пауков и $gнакормил:накормила; его мурлоками с Западного побережья, что к югу отсюда. Сколько ни убьешь – он все съест! Чем больше, тем лучше!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 мурлоков на Западном побережье, чтобы накормить голодного рудникового паука.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к укротительнице пауков Сарус в Лазуритовый рудник, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (28147,'Твой цвет – фиолетовый','Насколько я могу судить, местные огры из клана Помойных Потрохов еще не присоединились к Сумеречному Молоту. Так что если мы правильно разыграем наши карты, то сможем натравить наших врагов друг на друга.$B$BДавай устроим небольшой трюк, которому меня научили в Силитусе. Для начала нам понадобится одежда сектанта.$B$BИди на юг, на Сумеречный разлом, и убей несколько сумеречных заветренников. Так ты помешаешь их планам и, кроме того, сможешь добыть себе одежду.','Соберите 8 лоскутов сумеречного облачения.','Отнесите лоскуты облачения Ротгруму в Глотку на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Твой цвет – фиолетовый',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Насколько я могу судить, местные огры из клана Помойных Потрохов еще не присоединились к Сумеречному Молоту. Так что если мы правильно разыграем наши карты, то сможем натравить наших врагов друг на друга.$B$BДавай устроим небольшой трюк, которому меня научили в Силитусе. Для начала нам понадобится одежда сектанта.$B$BИди на юг, на Сумеречный разлом, и убей несколько сумеречных заветренников. Так ты помешаешь их планам и, кроме того, сможешь добыть себе одежду.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 лоскутов сумеречного облачения.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите лоскуты облачения Ротгруму в Глотку на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) VALUES (28147,'Отлично, Кузеньказ. Если такие герои, как ты, отвлекут внимание сектантов на себя, удар наших главных сил застанет их врасплох.$B$BМаскировочный костюм у тебя?') ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Отлично, Кузеньказ. Если такие герои, как ты, отвлекут внимание сектантов на себя, удар наших главных сил застанет их врасплох.$B$BМаскировочный костюм у тебя?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (28148,'Истребление заразы','Эта отвратительная порча, в ответе за которую демоны, охватила весь лес. Земля, деревья, животные... все раздулось от их грязной магии.$b$bМы, друиды Изумрудного Круга, поклялись очистить этот лес, а это требует непрекращающейся битвы. И хотя многих существ еще можно вылечить, с медведями и волками, которые бродят поблизости, все зашло слишком далеко.$b$bМы должны прекратить их страдания и удостовериться, что их тела не станут причиной дальнейшего распространения заразы. Убей медведей и волков и возвращайся ко мне с их шкурами.','Соберите 10 зараженных шкур медведей злобных когтей или волков-сквернолапов.','Мне нужны эти шкуры, чтобы я мог очистить их от остатков демонической сущности.','Вернитесь к Таруну Красному Перу в Изумрудное святилище, что в Оскверненном лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Истребление заразы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эта отвратительная порча, в ответе за которую демоны, охватила весь лес. Земля, деревья, животные... все раздулось от их грязной магии.$b$bМы, друиды Изумрудного Круга, поклялись очистить этот лес, а это требует непрекращающейся битвы. И хотя многих существ еще можно вылечить, с медведями и волками, которые бродят поблизости, все зашло слишком далеко.$b$bМы должны прекратить их страдания и удостовериться, что их тела не станут причиной дальнейшего распространения заразы. Убей медведей и волков и возвращайся ко мне с их шкурами.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 зараженных шкур медведей злобных когтей или волков-сквернолапов.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мне нужны эти шкуры, чтобы я мог очистить их от остатков демонической сущности.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Таруну Красному Перу в Изумрудное святилище, что в Оскверненном лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (28149,'Шепот ветра','Ты слышишь их, |3-6($c)? Голоса из пещеры. Они хотят говорить, но им не хватает дыхания.$B$BДавай найдем способ послушать их. Сумеречный Молот, вот кто разговаривает с ветром. Иди на юг, к Сумеречному разлому, и найди в лагере амулет говорящего с ветром. Он должен лежать на каменной колонне.$B$BИ дыхание элементалей нам тоже пригодится! Так что убивай штормовые завихрения и бери то, что тебе нужно.','Добудьте амулет говорящего с ветром и 5 дыханий шторма.','Вернитесь к Бууну в Глотку на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Шепот ветра',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты слышишь их, |3-6($c)? Голоса из пещеры. Они хотят говорить, но им не хватает дыхания.$B$BДавай найдем способ послушать их. Сумеречный Молот, вот кто разговаривает с ветром. Иди на юг, к Сумеречному разлому, и найди в лагере амулет говорящего с ветром. Он должен лежать на каменной колонне.$B$BИ дыхание элементалей нам тоже пригодится! Так что убивай штормовые завихрения и бери то, что тебе нужно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте амулет говорящего с ветром и 5 дыханий шторма.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бууну в Глотку на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) VALUES (28149,'Тсс, Кузеньказ! Слушай. Слушай...') ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тсс, Кузеньказ! Слушай. Слушай...',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (28150,'Союзница-чародей','Изумрудный Круг поклялся принимать помощь от всех, кто желает сразиться с демонами Оскверненного леса. Хотя наш народ и избегает тайной магии, мы не имеем права лишать себя тех преимуществ, которые она дает.$b$bЧародейка Деларис, одна из выживших магов высокорожденных, помогает нам в борьбе с сатирами племени Нефритового Пламени. Отправляйся по дороге, ведущей на север, и ты найдешь ее в нашем лагере, разбитом в руинах Констелласа.$b$bЕсли ты желаешь помочь нам в очищении Оскверненного леса, выполняй ее просьбы так же, как выполняешь мои.','Поговорите с чародейкой Деларис в руинах Констелласа.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Союзница-чародей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Изумрудный Круг поклялся принимать помощь от всех, кто желает сразиться с демонами Оскверненного леса. Хотя наш народ и избегает тайной магии, мы не имеем права лишать себя тех преимуществ, которые она дает.$b$bЧародейка Деларис, одна из выживших магов высокорожденных, помогает нам в борьбе с сатирами племени Нефритового Пламени. Отправляйся по дороге, ведущей на север, и ты найдешь ее в нашем лагере, разбитом в руинах Констелласа.$b$bЕсли ты желаешь помочь нам в очищении Оскверненного леса, выполняй ее просьбы так же, как выполняешь мои.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с чародейкой Деларис в руинах Констелласа.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (28151,'Костюм убийцы','$n, твое облачение служителя культа Сумеречного Молота готово. Надень его, когда пойдешь на север, в Ложбину клана Помойных Потрохов, и он введет в заблуждение огров.$B$BВсе остальное очень просто: ты убиваешь кучу огров Помойных Потрохов, а они винят во всем культ. Ну что, наведешь шороху в лагере огров? Я так и думал.','Убейте 10 огров из клана Помойных Потрохов. Маскировочный костюм Сумеречного Молота изменяет ваш облик автоматически, когда вы находитесь в Ложбине клана Помойных Потрохов.','Вернитесь к Ротгруму в Глотку на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Костюм убийцы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, твое облачение служителя культа Сумеречного Молота готово. Надень его, когда пойдешь на север, в Ложбину клана Помойных Потрохов, и он введет в заблуждение огров.$B$BВсе остальное очень просто: ты убиваешь кучу огров Помойных Потрохов, а они винят во всем культ. Ну что, наведешь шороху в лагере огров? Я так и думал.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 огров из клана Помойных Потрохов. Маскировочный костюм Сумеречного Молота изменяет ваш облик автоматически, когда вы находитесь в Ложбине клана Помойных Потрохов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ротгруму в Глотку на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (28152,'Джеденар ждет','Сектанты, которых ты $gвидел:видела;, когда $gискал:искала; коготь, раньше были членами Совета Теней. Грязные чернокнижники, которые стоят почти за каждой попыткой вернуть демонов в Азерот.$b$bК северу отсюда располагается Джеденар, названный так в честь самого Кил\'джедена. В глубине Джеденара находится Оплот Теней, бывшая обитель, а теперь – крепость Совета Теней в Азероте.$b$bВозьми эти травы и отнеси их в Лагерь Дикого Сердца, что к востоку от дороги. Они понадобятся Грете Замшелое Копыто для реализации ее плана по очищению Оплота Теней.','Доставьте чародейские травы Грете Замшелое Копыто в Лагерь Дикого Сердца.','Это как раз то, чего я ждала. Теперь, когда у меня есть эти травы, мы почти готовы к очищению Джеденара.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Джеденар ждет',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сектанты, которых ты $gвидел:видела;, когда $gискал:искала; коготь, раньше были членами Совета Теней. Грязные чернокнижники, которые стоят почти за каждой попыткой вернуть демонов в Азерот.$b$bК северу отсюда располагается Джеденар, названный так в честь самого Кил\'джедена. В глубине Джеденара находится Оплот Теней, бывшая обитель, а теперь – крепость Совета Теней в Азероте.$b$bВозьми эти травы и отнеси их в Лагерь Дикого Сердца, что к востоку от дороги. Они понадобятся Грете Замшелое Копыто для реализации ее плана по очищению Оплота Теней.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте чародейские травы Грете Замшелое Копыто в Лагерь Дикого Сердца.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это как раз то, чего я ждала. Теперь, когда у меня есть эти травы, мы почти готовы к очищению Джеденара.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (28153,'Владыка теней Скверн\'дан','Владыка теней Скверн\'дан ждет тебя там, в глубине, $n.$B$BТы $gубил:убила; его любимых слуг, и гнев его будет страшен. Даже без поддержки Мооры и Салии, он остается страшнейшим противником.$b$bОпасайся его темной магии, сейчас он куда ближе к демону, чем к орку.','Убейте Владыку теней Скверн\'дана.','Мерзкий лидер Совета Теней','Владыка теней Скверн\'дан','Наша задача почти выполнена. Мы вернем Оплот Теней.','Андалар Дольная Тень') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Владыка теней Скверн\'дан',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Владыка теней Скверн\'дан ждет тебя там, в глубине, $n.$B$BТы $gубил:убила; его любимых слуг, и гнев его будет страшен. Даже без поддержки Мооры и Салии, он остается страшнейшим противником.$b$bОпасайся его темной магии, сейчас он куда ближе к демону, чем к орку.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Владыку теней Скверн\'дана.',`objectives_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Мерзкий лидер Совета Теней',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Владыка теней Скверн\'дан',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Наша задача почти выполнена. Мы вернем Оплот Теней.',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Андалар Дольная Тень',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (28154,'Плавник Грязехлюпа или что-то в таком духе...','Это похоже на плавник Грязехлюпа или что-то подобное. Возможно, в Лазуритовом руднике кому-нибудь будет интересно узнать, что вы убили этого мурлока. Возможно и нет, но почему бы не проверить?$b$bВозьмите плавник Грязехлюпа и отнесите его капитану Кейтону в Лазуритовый рудник, что к юго-западу от Хилсбрада.','Грязехлюп, говоришь? Никогда о таком не слышал. И что это вообще? Плавник или что-то другое?','Я что, похож на специалиста по анатомии мурлоков?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Плавник Грязехлюпа или что-то в таком духе...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это похоже на плавник Грязехлюпа или что-то подобное. Возможно, в Лазуритовом руднике кому-нибудь будет интересно узнать, что вы убили этого мурлока. Возможно и нет, но почему бы не проверить?$b$bВозьмите плавник Грязехлюпа и отнесите его капитану Кейтону в Лазуритовый рудник, что к юго-западу от Хилсбрада.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Грязехлюп, говоришь? Никогда о таком не слышал. И что это вообще? Плавник или что-то другое?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я что, похож на специалиста по анатомии мурлоков?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (28155,'Лорд Гиблопуст','Осталось справиться с последней опасностью, которая таится в глубине Оплота Теней: лордом Гиблопустом.$b$bСовет Теней служит его прихотям, и даже Скверн\'дан — лишь его орудие в подготовке этих земель для следующего вторжения Пылающего Легиона.$b$bБудь $gосторожен:осторожна;, $n. Повелитель ужаса – страшный противник. Приготовься и добейся победы!','Убейте лорда Гиблопуста.','Вернитесь к Фарлусу Дикому Сердцу в Лагерь Дикого Сердца, что в Оскверненном лесу.','Он ждет в самом дальнем углу Оплота Теней.','Лорд Гиблопуст') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лорд Гиблопуст',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Осталось справиться с последней опасностью, которая таится в глубине Оплота Теней: лордом Гиблопустом.$b$bСовет Теней служит его прихотям, и даже Скверн\'дан — лишь его орудие в подготовке этих земель для следующего вторжения Пылающего Легиона.$b$bБудь $gосторожен:осторожна;, $n. Повелитель ужаса – страшный противник. Приготовься и добейся победы!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте лорда Гиблопуста.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фарлусу Дикому Сердцу в Лагерь Дикого Сердца, что в Оскверненном лесу.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Он ждет в самом дальнем углу Оплота Теней.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Лорд Гиблопуст',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`) VALUES (28156,'Спасение из глубин рудника','<Сквозь паутину вы слышите голос Дюмлона.>$b$BЭЙ! ТУТ ВЕЗДЕ ПАУКИ! КАПИТАН ОТПРАВИЛ МЕНЯ СПАСАТЬ МИР И БРАТЬ В ПЛЕН ЛЮДЕЙ! А ТУТ ЧТО ТАКОЕ? ЗДЕСЬ ТАК ЖАРКО! Я...$b$b<Дюмлон все жалуется и жалуется на ситуацию, в которой он оказался.>$b$bВозможно, стоит освободить его и проводить в безопасное место. Ну или оставить его здесь, ведь не вы же виноваты, что он застрял в этом руднике.','Проводите Дюмлона в безопасное место!','Проводите Дюмлона в безопасное место!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спасение из глубин рудника',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Сквозь паутину вы слышите голос Дюмлона.>$b$BЭЙ! ТУТ ВЕЗДЕ ПАУКИ! КАПИТАН ОТПРАВИЛ МЕНЯ СПАСАТЬ МИР И БРАТЬ В ПЛЕН ЛЮДЕЙ! А ТУТ ЧТО ТАКОЕ? ЗДЕСЬ ТАК ЖАРКО! Я...$b$b<Дюмлон все жалуется и жалуется на ситуацию, в которой он оказался.>$b$bВозможно, стоит освободить его и проводить в безопасное место. Ну или оставить его здесь, ведь не вы же виноваты, что он застрял в этом руднике.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проводите Дюмлона в безопасное место!',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Проводите Дюмлона в безопасное место!',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28157,'Четыре сумеречные стихии','Клан Сумеречного Молота призвал чудовище. Оно сочетает в себе четыре стихии, усиленные мощью их особой руды – элементия.$B$BЕсли хочешь спасти свою драгоценную Тысячу Игл от полного уничтожения, тебе придется одолеть эту тварь. Но сначала понадобится кое-что, чтобы пробиться сквозь ее защиту.$B$BОтправляйся на восток пустоши и принеси мне четыре сумеречные стихии.','Раздобудьте четыре сумеречные стихии: воздух, землю, огонь и воду.','<Магата смотрит на вас с откровенным презрением.>$B$BЯ соединю их в подходящую форму. Сделаю так, чтобы тебе хватило мозгов сообразить, как с ними поступить.','Вернитесь к Магате Зловещий Тотем на Сумеречную пустошь в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Четыре сумеречные стихии',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Клан Сумеречного Молота призвал чудовище. Оно сочетает в себе четыре стихии, усиленные мощью их особой руды – элементия.$B$BЕсли хочешь спасти свою драгоценную Тысячу Игл от полного уничтожения, тебе придется одолеть эту тварь. Но сначала понадобится кое-что, чтобы пробиться сквозь ее защиту.$B$BОтправляйся на восток пустоши и принеси мне четыре сумеречные стихии.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте четыре сумеречные стихии: воздух, землю, огонь и воду.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Магата смотрит на вас с откровенным презрением.>$B$BЯ соединю их в подходящую форму. Сделаю так, чтобы тебе хватило мозгов сообразить, как с ними поступить.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Магате Зловещий Тотем на Сумеречную пустошь в Тысяче Игл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28158,'Непокорные','Клан Сумеречного Молота подчинил себе двух очень могущественных элементалей. Через покоренных Неистового и Вихря они передают Анимусу огромное количество энергии.$B$BКак только Анимус вберет в себя достаточно силы, он взорвется. Тысячу Игл и окрестные земли сметет с лица Азерота.','Освободите покоренного Неистового и покоренного Вихря.','Простое задание для простого паренька. Посмотрим, все ли у тебя есть, чтобы покончить с Анимусом.','Вернитесь к Магате Зловещий Тотем на Сумеречную пустошь в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Непокорные',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Клан Сумеречного Молота подчинил себе двух очень могущественных элементалей. Через покоренных Неистового и Вихря они передают Анимусу огромное количество энергии.$B$BКак только Анимус вберет в себя достаточно силы, он взорвется. Тысячу Игл и окрестные земли сметет с лица Азерота.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Освободите покоренного Неистового и покоренного Вихря.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Простое задание для простого паренька. Посмотрим, все ли у тебя есть, чтобы покончить с Анимусом.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Магате Зловещий Тотем на Сумеречную пустошь в Тысяче Игл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`completedtext_loc8`,`questgivertargetname_loc8`) VALUES (28159,'Вернитесь к Магате Зловещий Тотем на Сумеречную пустошь в Тысяче Игл.','Анимус') ON DUPLICATE KEY UPDATE `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Магате Зловещий Тотем на Сумеречную пустошь в Тысяче Игл.',`completedtext_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Анимус',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (28160,'Поведай всем','За твою верную службу я дарю тебе жизнь. Забирай ее – и поди прочь с моих глаз. И расскажи своему народу обо всем, что случилось здесь.$B$BИ еще, $n: если я еще хоть раз встречу тебя, ты умрешь.','Обратитесь к Пшиксу Медноштифу на гоночной барже Пшикса и Поззика в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поведай всем',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','За твою верную службу я дарю тебе жизнь. Забирай ее – и поди прочь с моих глаз. И расскажи своему народу обо всем, что случилось здесь.$B$BИ еще, $n: если я еще хоть раз встречу тебя, ты умрешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обратитесь к Пшиксу Медноштифу на гоночной барже Пшикса и Поззика в Тысяче Игл.',`objectives_loc8`);
