INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (28162,'Припасы на болоте','В подобном месте сложно пополнить припасы, |3-6($c). Мы безуспешно пытались найти что-либо пригодное с тех пор, как попали на этот остров.$B$BК счастью, только что лазутчики доложили, что на болоте к западу от лагеря водится много кроколисков. Их шкуры, несомненно, пригодятся нашим кожевникам. Принеси столько шкур, сколько сможешь.','Вам нужно собрать 8 шкур толбарадских кроколисков. Кроколиски обитают на болоте к западу от крепости Барадин.','Доложите сержанту Паркеру в крепости Барадин о выполнении задания.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Припасы на болоте',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В подобном месте сложно пополнить припасы, |3-6($c). Мы безуспешно пытались найти что-либо пригодное с тех пор, как попали на этот остров.$B$BК счастью, только что лазутчики доложили, что на болоте к западу от лагеря водится много кроколисков. Их шкуры, несомненно, пригодятся нашим кожевникам. Принеси столько шкур, сколько сможешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вам нужно собрать 8 шкур толбарадских кроколисков. Кроколиски обитают на болоте к западу от крепости Барадин.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доложите сержанту Паркеру в крепости Барадин о выполнении задания.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (28163,'Окончательная зачистка','Мы стойко сражались, чтобы захватить этот остров, |3-6($r). Нам удалось уничтожить большую часть ордынских паскудников, но я все еще чую их мерзкий дух в окрестностях.$b$bПоручаю тебе провести разведку на Шлакозаводе, на Посту Стража и в Железном гарнизоне. Убей всех представителей Орды, которых обнаружишь.$b$bКак гласит народная мудрость, хороший ордынец – мертвый ордынец.','От вас требуется убить 12 пехотинцев Орды на Тол Бараде. Укрепления Орды на Тол Бараде расположены на Шлакозаводе, Посту Стража и в Железном гарнизоне.','Доложите сержанту Паркеру в крепости Барадин о выполнении задания.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Окончательная зачистка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы стойко сражались, чтобы захватить этот остров, |3-6($r). Нам удалось уничтожить большую часть ордынских паскудников, но я все еще чую их мерзкий дух в окрестностях.$b$bПоручаю тебе провести разведку на Шлакозаводе, на Посту Стража и в Железном гарнизоне. Убей всех представителей Орды, которых обнаружишь.$b$bКак гласит народная мудрость, хороший ордынец – мертвый ордынец.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','От вас требуется убить 12 пехотинцев Орды на Тол Бараде. Укрепления Орды на Тол Бараде расположены на Шлакозаводе, Посту Стража и в Железном гарнизоне.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доложите сержанту Паркеру в крепости Барадин о выполнении задания.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (28165,'Блок Д','Ты уже $gслышал:слышала; о блоке Д, $n? Это один из старых тюремных блоков, находящихся на острове. Дело в том, что его заселили демоны. Мы рассчитывали разместить там пленных из Орды, захваченных на острове, но при текущем раскладе это невозможно.$B$BЯ хочу, чтобы ты $gпомог:помогла; нам очистить блок от демонов. Отрапортуй мне о выполнении приказа.','Вам поручено уничтожить 10 любых демонов, обитающих в блоке Д, что находится к северо-западу от крепости Барадин.','Доложите второму лейтенанту Вансворту в крепости Барадин о выполнении задания.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Блок Д',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты уже $gслышал:слышала; о блоке Д, $n? Это один из старых тюремных блоков, находящихся на острове. Дело в том, что его заселили демоны. Мы рассчитывали разместить там пленных из Орды, захваченных на острове, но при текущем раскладе это невозможно.$B$BЯ хочу, чтобы ты $gпомог:помогла; нам очистить блок от демонов. Отрапортуй мне о выполнении приказа.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вам поручено уничтожить 10 любых демонов, обитающих в блоке Д, что находится к северо-западу от крепости Барадин.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доложите второму лейтенанту Вансворту в крепости Барадин о выполнении задания.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (28166,'Ночник Тога','Чтобы увидеть духов, нам нужен особый свет. Свет, который подсвечивает самое нутро. Свет души.$B$BПосле того что мы сделали с ними на Хиджале, Сумеречный Молот стал выявлять с их помощью предателей. И один из них они подарили Помойным Потрохам.$B$BНа севере, в Ложбине Помойных Потрохов, живет огромный громила по имени Тог. У него есть Свет души. По крайней мере, до тех пор, пока ты его не отберешь.','Добудьте Свет души в Ложбине клана Помойных Потрохов.','О да, это то, что нужно.$B$B<Линза ярко вспыхивает в руках Бууну, озаряя пещеру неземным светом.>$B$BТеперь мы готовы вывести духов из тени.','Свет души у тебя?','Отнесите Свет души Бууну в Глотку на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ночник Тога',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чтобы увидеть духов, нам нужен особый свет. Свет, который подсвечивает самое нутро. Свет души.$B$BПосле того что мы сделали с ними на Хиджале, Сумеречный Молот стал выявлять с их помощью предателей. И один из них они подарили Помойным Потрохам.$B$BНа севере, в Ложбине Помойных Потрохов, живет огромный громила по имени Тог. У него есть Свет души. По крайней мере, до тех пор, пока ты его не отберешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте Свет души в Ложбине клана Помойных Потрохов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О да, это то, что нужно.$B$B<Линза ярко вспыхивает в руках Бууну, озаряя пещеру неземным светом.>$B$BТеперь мы готовы вывести духов из тени.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Свет души у тебя?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите Свет души Бууну в Глотку на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28167,'Отчет Карво Рвизасову','Я собираюсь начать приготовления к тому, чтобы вывести своих гномов из этого места. Мы больше не можем здесь оставаться. Я хочу, чтобы ты $gзанял:заняла; позицию в центре большого зала, что впереди нас.$b$bНайди там Карво Рвизасова. Он даст тебе остальные инструкции. Удачи, $n, и увидимся на поверхности.','Поговорите с Карво Рвизасовом в Гномрегане.','Невин отправил тебя вперед? Значит, он уже готов к окончанию миссии. Но здесь еще много выживших, которых нужно спасти. Мы должны помочь им!','Поговорите с Карво Рвизасовом в Гномрегане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отчет Карво Рвизасову',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я собираюсь начать приготовления к тому, чтобы вывести своих гномов из этого места. Мы больше не можем здесь оставаться. Я хочу, чтобы ты $gзанял:заняла; позицию в центре большого зала, что впереди нас.$b$bНайди там Карво Рвизасова. Он даст тебе остальные инструкции. Удачи, $n, и увидимся на поверхности.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Карво Рвизасовом в Гномрегане.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Невин отправил тебя вперед? Значит, он уже готов к окончанию миссии. Но здесь еще много выживших, которых нужно спасти. Мы должны помочь им!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Карво Рвизасовом в Гномрегане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (28168,'Проблемы в Топких полях') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Проблемы в Топких полях',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (28169,'В Погрузочную!','Приятно познакомиться, $c. Мы редко встречаем таких крепких выживших, как ты. Я помогу тебе пройти очищение от радиоактивных загрязнений и выбраться отсюда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В Погрузочную!',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Приятно познакомиться, $c. Мы редко встречаем таких крепких выживших, как ты. Я помогу тебе пройти очищение от радиоактивных загрязнений и выбраться отсюда.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (28170,'Ночные кошмары','Мой друг Учек уже в пещере. Там мы поставили три алтаря. И твоя задача – очистить все три от скверны.$B$BИди в пещеру и поговори с Учеком. Он введет тебя в транс, отправит в мир духов. Когда окажешься там, действуй осторожно! Если увидишь призрачное чудовище, не паникуй. Посвети на него Светом души пару секунд, и с тварью будет покончено. Свет защитит тебя. Иди и очисти три алтаря!','Поговорите с Учеком в Глотке. Находясь в мире духов, защищайте себя с помощью Света души, и посетите три алтаря, которые находятся в пещере.','Поговорите с Бууну в Глотке на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ночные кошмары',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мой друг Учек уже в пещере. Там мы поставили три алтаря. И твоя задача – очистить все три от скверны.$B$BИди в пещеру и поговори с Учеком. Он введет тебя в транс, отправит в мир духов. Когда окажешься там, действуй осторожно! Если увидишь призрачное чудовище, не паникуй. Посвети на него Светом души пару секунд, и с тварью будет покончено. Свет защитит тебя. Иди и очисти три алтаря!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Учеком в Глотке. Находясь в мире духов, защищайте себя с помощью Света души, и посетите три алтаря, которые находятся в пещере.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Бууну в Глотке на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28171,'И небо окрасилось в красный цвет','Пока Смертокрылу не до нагорья, королева поручила нам одно весьма сложное и опасное дело. Мы должны истребить черных драконов.$B$BЕсли ты решишь помочь нам в этом, мы будем весьма благодарны. Когда будешь $gготов:готова;, поговори со мной, и я дам тебе дракона, чтобы ты $gсмог:смогла; присоединиться к атаке.','Примите участие в бою с черными драконами.','Похоже, что ты все еще с нами. Я даже в некотором роде благодарна тебе за это.$B$BСпасибо.','Поговорите с Лирастразой на Сумеречном нагорье, на северо-западе от Обсидианового леса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','И небо окрасилось в красный цвет',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пока Смертокрылу не до нагорья, королева поручила нам одно весьма сложное и опасное дело. Мы должны истребить черных драконов.$B$BЕсли ты решишь помочь нам в этом, мы будем весьма благодарны. Когда будешь $gготов:готова;, поговори со мной, и я дам тебе дракона, чтобы ты $gсмог:смогла; присоединиться к атаке.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Примите участие в бою с черными драконами.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Похоже, что ты все еще с нами. Я даже в некотором роде благодарна тебе за это.$B$BСпасибо.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Лирастразой на Сумеречном нагорье, на северо-западе от Обсидианового леса.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (28172,'Безвинные создания','Орки Черной горы из Пылающих степей служат темному повелителю, который проводит изощренные эксперименты над живыми созданиями, превращая их в полчище чудовищ. Многие из подопытных существ были осквернены своим создателем, однако же, некоторые из них сохранили внутреннюю чистоту.$b$bВ Ясельных холмах к югу отсюда орки приковывают к земле детенышей дракона, чтобы подготовить тех к последующим опытам. Я не потерплю подобного издевательства. Сбрось с них оковы и приведи детенышей ко мне... в безопасное место.','Освободите красного дракончика, зеленого дракончика, синего дракончика и бронзового дракончика.','Я позабочусь, чтобы дракончикам обеспечили надлежащий уход.','Надеюсь, ты еще не опоздал.','Вернитесь к Мутону Пламени Звезд в Лагерь Пламени Звезд, что в Пылающих степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Безвинные создания',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Орки Черной горы из Пылающих степей служат темному повелителю, который проводит изощренные эксперименты над живыми созданиями, превращая их в полчище чудовищ. Многие из подопытных существ были осквернены своим создателем, однако же, некоторые из них сохранили внутреннюю чистоту.$b$bВ Ясельных холмах к югу отсюда орки приковывают к земле детенышей дракона, чтобы подготовить тех к последующим опытам. Я не потерплю подобного издевательства. Сбрось с них оковы и приведи детенышей ко мне... в безопасное место.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Освободите красного дракончика, зеленого дракончика, синего дракончика и бронзового дракончика.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я позабочусь, чтобы дракончикам обеспечили надлежащий уход.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Надеюсь, ты еще не опоздал.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мутону Пламени Звезд в Лагерь Пламени Звезд, что в Пылающих степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28173,'Затмение','Сумеречные охотники на драконов используют жуткие инструменты для борьбы с нашими драконами – крючья, канаты и прочее.$B$BПримирение с ними невозможно – мы в силах лишь помочь им обрести вечный покой, который они ищут. $B$BОтправляйся на юг и убей обсидиановых огнекрылов. Возьми эти крюки: они помогут тебе лучше маневрировать в воздухе.','Зацепите 8 обсидиановых огнекрылов с помощью крюков охотников на драконов, а затем убейте.','Кажется, тебе удалось научиться пользоваться этими жуткими инструментами.$B$BЯ утешаю себя мыслью о том, что эти орудия зла защищают жизнь. В этом мире у всего есть свое предназначение.','Поговорите с Лирастразой на Сумеречном нагорье, на северо-западе от Обсидианового леса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Затмение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сумеречные охотники на драконов используют жуткие инструменты для борьбы с нашими драконами – крючья, канаты и прочее.$B$BПримирение с ними невозможно – мы в силах лишь помочь им обрести вечный покой, который они ищут. $B$BОтправляйся на юг и убей обсидиановых огнекрылов. Возьми эти крюки: они помогут тебе лучше маневрировать в воздухе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Зацепите 8 обсидиановых огнекрылов с помощью крюков охотников на драконов, а затем убейте.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Кажется, тебе удалось научиться пользоваться этими жуткими инструментами.$B$BЯ утешаю себя мыслью о том, что эти орудия зла защищают жизнь. В этом мире у всего есть свое предназначение.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Лирастразой на Сумеречном нагорье, на северо-западе от Обсидианового леса.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28174,'Настигающая кара','Орки Черной горы все не угомонятся. Они собираются у полей сражений к востоку отсюда, готовые ударить в любой момент.$b$bОднажды они уже напали на мою родину. Я здесь, чтобы не допустить этого вновь.$b$bЕсли тебе хоть немного дорого человечество, ты поступишь так же. Прояви себя в деле. Отправляйся на юг, к Ясельным холмам, и уничтожь взращивателей маленьких дракончиков, а также опекаемых ими детенышей черного дракона. Докажи мне, что ты $gготов:готова; к войне.','Уничтожьте 5 взращивателей из клана Черной горы и 5 огнечешуйчатых дракончиков.','Итак, ты в деле?$B$BЧудесно.','Вернитесь к Джону Джею Кишану в Лагерь Пламени Звезд, что в Пылающих степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Настигающая кара',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Орки Черной горы все не угомонятся. Они собираются у полей сражений к востоку отсюда, готовые ударить в любой момент.$b$bОднажды они уже напали на мою родину. Я здесь, чтобы не допустить этого вновь.$b$bЕсли тебе хоть немного дорого человечество, ты поступишь так же. Прояви себя в деле. Отправляйся на юг, к Ясельным холмам, и уничтожь взращивателей маленьких дракончиков, а также опекаемых ими детенышей черного дракона. Докажи мне, что ты $gготов:готова; к войне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 5 взращивателей из клана Черной горы и 5 огнечешуйчатых дракончиков.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Итак, ты в деле?$B$BЧудесно.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джону Джею Кишану в Лагерь Пламени Звезд, что в Пылающих степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28175,'Свет во тьме','К югу отсюда находится огромное окаменевшее дерево. Когда-то это был великий источник жизни. Наш источник. Черные драконы отняли у нас этот лес, и с тех пор он переполнился скверной и окаменел.$B$BНо мы еще надеемся его спасти. У меня есть одно сильное средство, с которого можно начать лечение. Возможно, нам удастся исцелить дерево – но для этого нам понадобится время, удача и, быть может, твоя помощь.$B$BВозьми вот это, слезу Алекстразы, и исцели сердцевину дерева.','Поместите слезу Алекстразы в нору под обсидиановым деревом.','Да, сегодня пролилось много крови, но тебе удалось совершить чудо. Этот день станет началом новой эры.$B$BЭта земля возродится, пусть и через много лет. Она снова станет прекрасной.','Поговорите с Веластразой на Сумеречном нагорье, на северо-западе от Обсидианового леса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Свет во тьме',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','К югу отсюда находится огромное окаменевшее дерево. Когда-то это был великий источник жизни. Наш источник. Черные драконы отняли у нас этот лес, и с тех пор он переполнился скверной и окаменел.$B$BНо мы еще надеемся его спасти. У меня есть одно сильное средство, с которого можно начать лечение. Возможно, нам удастся исцелить дерево – но для этого нам понадобится время, удача и, быть может, твоя помощь.$B$BВозьми вот это, слезу Алекстразы, и исцели сердцевину дерева.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поместите слезу Алекстразы в нору под обсидиановым деревом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, сегодня пролилось много крови, но тебе удалось совершить чудо. Этот день станет началом новой эры.$B$BЭта земля возродится, пусть и через много лет. Она снова станет прекрасной.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Веластразой на Сумеречном нагорье, на северо-западе от Обсидианового леса.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28176,'Юные драконы идут в логово','В юго-западной части Обсидианового леса ты найдешь яйца черных драконов. Если как следует их поджарить, из них вылупятся дракончики и с воплем помчатся к матери.$B$BНе волнуйся, детенышей я тебя убивать не заставлю. Тебе просто нужно проследить за ними – они приведут тебя к своей матери. Нам нужно разобраться с ней.','Используйте материнское пламя, чтобы из обсидиановых яиц вылупились молодые драконы. Идите за детенышами к логову их матери.','Лирастраза отправила меня в логово. Она полагает, что черный дракон, которого мы ищем, все еще здесь. И, судя по всему, она не ошиблась.','Поговорите с Пламегоном в Обсидиановом логове на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Юные драконы идут в логово',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В юго-западной части Обсидианового леса ты найдешь яйца черных драконов. Если как следует их поджарить, из них вылупятся дракончики и с воплем помчатся к матери.$B$BНе волнуйся, детенышей я тебя убивать не заставлю. Тебе просто нужно проследить за ними – они приведут тебя к своей матери. Нам нужно разобраться с ней.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте материнское пламя, чтобы из обсидиановых яиц вылупились молодые драконы. Идите за детенышами к логову их матери.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Лирастраза отправила меня в логово. Она полагает, что черный дракон, которого мы ищем, все еще здесь. И, судя по всему, она не ошиблась.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Пламегоном в Обсидиановом логове на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (28177,'Запасаемся','Если мы намерены тягаться с кланом Черной горы, то нам нужно разработать план военных действий. Полковник уже сделал кое-какие наброски, так что пришло время действовать.$b$bМне потребуются жала скорпидов... самые острые, какие сможешь найти. Скорпиды обитают на всей территории степей, но больше всего их можно найти в ущелье на западе.$b$bНе спрашивай, зачем они мне. Скоро все узнаешь.','Добудьте 5 бритвенно-острых жал скорпида.','Уже вернулся?','Вернитесь к Джону Джею Кишану в Лагерь Пламени Звезд, что в Пылающих степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Запасаемся',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если мы намерены тягаться с кланом Черной горы, то нам нужно разработать план военных действий. Полковник уже сделал кое-какие наброски, так что пришло время действовать.$b$bМне потребуются жала скорпидов... самые острые, какие сможешь найти. Скорпиды обитают на всей территории степей, но больше всего их можно найти в ущелье на западе.$b$bНе спрашивай, зачем они мне. Скоро все узнаешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 5 бритвенно-острых жал скорпида.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Уже вернулся?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джону Джею Кишану в Лагерь Пламени Звезд, что в Пылающих степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (28178,'Планы на будущее','Нам потребуется множество шкур воргов. Не важно, в каком они будут состоянии: изорванные, обгоревшие или запятнанные кровью. Нам подойдут любые и в большом количестве.$b$bПожалуй, неплохо будет их для начала немного истрепать.$b$bВорги обитают к востоку и к западу отсюда.','Добудьте 11 шкур пепельного ворга.','Поверь мне, Хуманн… Я так же как и ты рвусь в бой, но нам нужно следовать плану. Наш час скоро настанет.$B$BПока что я сложу шкуры на склад.','Посмотрим на эти шкуры.','Вернитесь к Джону Джею Кишану в Лагерь Пламени Звезд, что в Пылающих степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Планы на будущее',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нам потребуется множество шкур воргов. Не важно, в каком они будут состоянии: изорванные, обгоревшие или запятнанные кровью. Нам подойдут любые и в большом количестве.$b$bПожалуй, неплохо будет их для начала немного истрепать.$b$bВорги обитают к востоку и к западу отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 11 шкур пепельного ворга.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Поверь мне, Хуманн… Я так же как и ты рвусь в бой, но нам нужно следовать плану. Наш час скоро настанет.$B$BПока что я сложу шкуры на склад.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Посмотрим на эти шкуры.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джону Джею Кишану в Лагерь Пламени Звезд, что в Пылающих степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (28179,'Сборщик грязи','Надеюсь, ты не боишься испачкаться. Судя по твоему виду, по крайней мере.$b$bК северу отсюда, там, где кончается застывшая лава, лежат кучи темной грязи. Она мне нужна.$b$bЛучше не задавай лишних вопросов и просто сосредоточься на задании, $n.','Соберите 9 кучек насыщенной обсидианом грязи.','Да, это как раз то, что нужно.$B$BНе волнуйся, Хуманн… скоро придет время расправы над орками.','Следи за обсидиановыми элементалями. Они любят подкрадываться незаметно.','Вернитесь к Джону Джею Кишану в Лагерь Пламени Звезд, что в Пылающих степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сборщик грязи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Надеюсь, ты не боишься испачкаться. Судя по твоему виду, по крайней мере.$b$bК северу отсюда, там, где кончается застывшая лава, лежат кучи темной грязи. Она мне нужна.$b$bЛучше не задавай лишних вопросов и просто сосредоточься на задании, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 9 кучек насыщенной обсидианом грязи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, это как раз то, что нужно.$B$BНе волнуйся, Хуманн… скоро придет время расправы над орками.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Следи за обсидиановыми элементалями. Они любят подкрадываться незаметно.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джону Джею Кишану в Лагерь Пламени Звезд, что в Пылающих степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (28180,'Песок, сидр и сфера','Эй! Ты кто?$B$BАх, так ты от Кишана? Не хочешь тут маленько задержаться? Ничего особенного… просто надо убить парочку чернокнижников для меня.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Песок, сидр и сфера',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Эй! Ты кто?$B$BАх, так ты от Кишана? Не хочешь тут маленько задержаться? Ничего особенного… просто надо убить парочку чернокнижников для меня.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28181,'Лучшие вещи – это к чернокнижникам','Кишан сказал, что ему нужны припасы? У меня куча припасов! Проблема в том, что они хранятся у меня дома, откуда меня выдворили чернокнижники и не пускают обратно.$b$b<Горзиеки оценивающе осматривает тебя.>$b$bВот ты, наверное, сможешь туда пробраться. Направляйся на север, только прихвати немного сонного песку, прокисшего сидра и сферу из прозрачного стекла. Уверен, это то, что он хочет.$b$bАх да, и если ты мимоходом укокошишь несколько тамошних орков, я не сильно расстроюсь.','Добудьте горсть сонного песка, кувшин прокисшего сидра и сферу из прозрачного стекла.','Надеюсь, это то, что искал Кишан. Для меня это все равно хлам.','Вернитесь к Горзиеки Дикоглазу у Алтаря Бурь в Пылающих степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лучшие вещи – это к чернокнижникам',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кишан сказал, что ему нужны припасы? У меня куча припасов! Проблема в том, что они хранятся у меня дома, откуда меня выдворили чернокнижники и не пускают обратно.$b$b<Горзиеки оценивающе осматривает тебя.>$b$bВот ты, наверное, сможешь туда пробраться. Направляйся на север, только прихвати немного сонного песку, прокисшего сидра и сферу из прозрачного стекла. Уверен, это то, что он хочет.$b$bАх да, и если ты мимоходом укокошишь несколько тамошних орков, я не сильно расстроюсь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте горсть сонного песка, кувшин прокисшего сидра и сферу из прозрачного стекла.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Надеюсь, это то, что искал Кишан. Для меня это все равно хлам.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Горзиеки Дикоглазу у Алтаря Бурь в Пылающих степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28182,'Развеять мрак','Нер\'гош Мрак – предводитель чернокнижников к северу отсюда; именно он вышвырнул меня из дому, когда в эти края пришли орки Черной горы.$b$bЕсли мне когда-нибудь суждено вернуться к Алтарю, то следует вначале избавиться от Нер\'гоша.','Ликвидируйте Нер\'гоша Мрака.','Зная уклад жизни орков, полагаю, что скоро его место займет кто-то еще. Надеюсь, я проникну в Алтарь Бурь до того, как это произойдет.$B$BСпасибо, приятель.','Вернитесь к Горзиеки Дикоглазу у Алтаря Бурь в Пылающих степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Развеять мрак',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нер\'гош Мрак – предводитель чернокнижников к северу отсюда; именно он вышвырнул меня из дому, когда в эти края пришли орки Черной горы.$b$bЕсли мне когда-нибудь суждено вернуться к Алтарю, то следует вначале избавиться от Нер\'гоша.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Ликвидируйте Нер\'гоша Мрака.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Зная уклад жизни орков, полагаю, что скоро его место займет кто-то еще. Надеюсь, я проникну в Алтарь Бурь до того, как это произойдет.$B$BСпасибо, приятель.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Горзиеки Дикоглазу у Алтаря Бурь в Пылающих степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28183,'Возвращение к Кишану','Думаю, пока это все. Когда наберусь смелости, пойду сам разберусь с остальными чернокнижниками.$b$bНе забудь припасы.','Отнесите припасы чернокнижника Джону Джею Кишану в Лагерь Пламени Звезд в Пылающих степях.','<Кишан осматривает содержимое ящика.>$B$BТак-так, хорошо. Теперь мы отправимся на восток и забудем о Черной горе... на время.','Доложите Джону Джею Кишану в Лагерь Пламени Звезд, что в Пылающих степях, о выполнении задания.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение к Кишану',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Думаю, пока это все. Когда наберусь смелости, пойду сам разберусь с остальными чернокнижниками.$b$bНе забудь припасы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите припасы чернокнижника Джону Джею Кишану в Лагерь Пламени Звезд в Пылающих степях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Кишан осматривает содержимое ящика.>$B$BТак-так, хорошо. Теперь мы отправимся на восток и забудем о Черной горе... на время.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доложите Джону Джею Кишану в Лагерь Пламени Звезд, что в Пылающих степях, о выполнении задания.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28184,'Узкоклинье – сердце Пылающих степей','Мы направляемся в Узкоклинье, лежащее прямо в центре степей. Там мы повстречаемся братством Тория и ожидающим нас Тротманом.$b$bТы уже $gзнаком:знакома; с братством? Это дворфы из клана Черного Железа, уже не раз выручавшие меня в беде. Теперь нам снова нужна их помощь.$b$bНаш путь проходит мимо Загона Черного Зуба. Ты не возражаешь, если по пути убьем парочку орков? А то мне что-то становится беспокойно в этом лагере.','Убейте 15 орков Черной горы по пути в Узкоклинье.','Извини, но сейчас не время для приема гостей. Выйди из Узкоклинья так же, как и зашел$B$BО, Кишан… это ты?.','Доложи Стеббену Рудохвату в Узкоклинье, расположенном в Пылающих степях, о выполненном задании.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Узкоклинье – сердце Пылающих степей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы направляемся в Узкоклинье, лежащее прямо в центре степей. Там мы повстречаемся братством Тория и ожидающим нас Тротманом.$b$bТы уже $gзнаком:знакома; с братством? Это дворфы из клана Черного Железа, уже не раз выручавшие меня в беде. Теперь нам снова нужна их помощь.$b$bНаш путь проходит мимо Загона Черного Зуба. Ты не возражаешь, если по пути убьем парочку орков? А то мне что-то становится беспокойно в этом лагере.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 15 орков Черной горы по пути в Узкоклинье.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Извини, но сейчас не время для приема гостей. Выйди из Узкоклинья так же, как и зашел$B$BО, Кишан… это ты?.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доложи Стеббену Рудохвату в Узкоклинье, расположенном в Пылающих степях, о выполненном задании.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (28185,'Сварнос','Ты отлично $gпотрудился:потрудилась; при захвате острова, |3-6($c). Теперь, когда он в наших руках, предстоит подготовить камеры к приему заключенных. Блок Д доставляет нам особенно много проблем в плане зачистки. К сожалению, его заполонили демоны всех мастей.$B$BНам удалось совладать с большинством, но из одной камеры сбежала большая гончая недр, которая теперь бесчинствует в тюремном блоке. Я хочу, чтобы ты $gубил:убила; ее и $gдоставил:доставила; мне ее ошейник.','Расправьтесь со Сварносом в Блоке Д и заберите проклятый ошейник Сварноса. Монстр находится в Блоке Д к северо-западу от крепости Барадин.','С гончей недр покончено?','Доложите второму лейтенанту Вансворту в крепости Барадин о выполнении задания.','Мне никогда не нравился зеленый цвет.','Сварнос') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сварнос',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты отлично $gпотрудился:потрудилась; при захвате острова, |3-6($c). Теперь, когда он в наших руках, предстоит подготовить камеры к приему заключенных. Блок Д доставляет нам особенно много проблем в плане зачистки. К сожалению, его заполонили демоны всех мастей.$B$BНам удалось совладать с большинством, но из одной камеры сбежала большая гончая недр, которая теперь бесчинствует в тюремном блоке. Я хочу, чтобы ты $gубил:убила; ее и $gдоставил:доставила; мне ее ошейник.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Расправьтесь со Сварносом в Блоке Д и заберите проклятый ошейник Сварноса. Монстр находится в Блоке Д к северо-западу от крепости Барадин.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','С гончей недр покончено?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доложите второму лейтенанту Вансворту в крепости Барадин о выполнении задания.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Мне никогда не нравился зеленый цвет.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Сварнос',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (28186,'Проклятые кандалы','Ты уже $gбывал:бывала; в Блоке Д, $n? Всякий раз как мы зачищаем этот блок, демоны быстро заселяют его снова. Мы установили, что они возрождаются за счет проклятых кандалов, разбросанных по блоку. Вот тут-то ты нам и пригодишься, $n.$B$BСобери столько кандалов, сколько сможешь, и принеси их мне. Мы их немедленно уничтожим.','Соберите 8 проклятых кандалов в Блоке Д, что находится к северо-западу от крепости Барадин.','Доложите второму лейтенанту Вансворту в крепости Барадин о выполнении задания.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Проклятые кандалы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты уже $gбывал:бывала; в Блоке Д, $n? Всякий раз как мы зачищаем этот блок, демоны быстро заселяют его снова. Мы установили, что они возрождаются за счет проклятых кандалов, разбросанных по блоку. Вот тут-то ты нам и пригодишься, $n.$B$BСобери столько кандалов, сколько сможешь, и принеси их мне. Мы их немедленно уничтожим.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 проклятых кандалов в Блоке Д, что находится к северо-западу от крепости Барадин.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доложите второму лейтенанту Вансворту в крепости Барадин о выполнении задания.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28187,'Мимо!','Такой дело, |3-6($r)! Отшень серьезный!$B$BКто-то решайт избавляйт от я и думайт, это просто парный репка.$B$BНу-с, посмотреть! Майн арбайтен не смочь мешать! Нихт!$B$B<Шнотц оглядывается по сторонам, видит приближающиеся языки пламени.>$B$BМне думайт, польза идти вон.$B$BШнель! Время ценен!','Поговорите с командиром Шнотцем, когда будете готовы вывести его из пылающего здания.','В такой время понимайт, кто есть дружить, а кто против...','Поговорите с командиром Шнотцем в лагере Шнотца.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мимо!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Такой дело, |3-6($r)! Отшень серьезный!$B$BКто-то решайт избавляйт от я и думайт, это просто парный репка.$B$BНу-с, посмотреть! Майн арбайтен не смочь мешать! Нихт!$B$B<Шнотц оглядывается по сторонам, видит приближающиеся языки пламени.>$B$BМне думайт, польза идти вон.$B$BШнель! Время ценен!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с командиром Шнотцем, когда будете готовы вывести его из пылающего здания.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','В такой время понимайт, кто есть дружить, а кто против...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с командиром Шнотцем в лагере Шнотца.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (28188,'Тюремный бунт','Теперь, когда остров находится в наших руках, предстоит тяжкая работа. Нам удалось обнаружить заброшенный тюремный блок к юго-западу отсюда, который нужно проверить, $n.$B$BПо донесениям разведки заключенные, томившиеся в заточении годами, захватили блок. Прими все необходимые меры по зачистке этого места. Доложи мне о результатах операции.','Вам поручено убить 10 любых узников в Яме, расположенной к юго-западу от крепости Барадин.','Доложите маршалу Фэллоусу из крепости Барадин о выполнении задания.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тюремный бунт',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда остров находится в наших руках, предстоит тяжкая работа. Нам удалось обнаружить заброшенный тюремный блок к юго-западу отсюда, который нужно проверить, $n.$B$BПо донесениям разведки заключенные, томившиеся в заточении годами, захватили блок. Прими все необходимые меры по зачистке этого места. Доложи мне о результатах операции.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вам поручено убить 10 любых узников в Яме, расположенной к юго-западу от крепости Барадин.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доложите маршалу Фэллоусу из крепости Барадин о выполнении задания.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (28189,'Благое дело','Вашим глазам предстает ужасная картина. Кто-то закопал всех людей в землю по шею, как если бы сажал растения. Вурдалаки, которые бродят по полю, периодически набрасываются на человеческие головы и пожирают их!$b$bВы можете положить этому конец прямо сейчас! Возьмите лопату и "спасите" людей.$b$bСделайте благое дело.','"Спасите" 15 прорастающих людей.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Благое дело',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вашим глазам предстает ужасная картина. Кто-то закопал всех людей в землю по шею, как если бы сажал растения. Вурдалаки, которые бродят по полю, периодически набрасываются на человеческие головы и пожирают их!$b$bВы можете положить этому конец прямо сейчас! Возьмите лопату и "спасите" людей.$b$bСделайте благое дело.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','"Спасите" 15 прорастающих людей.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28190,'Нечистые слизнюки','Убейте 8 нечистых слизнюков.','Это утешительные новости… возможно, теперь мне будет легче отдохнуть и прийти в себя.$B$BМожет быть и желудок мой тоже придет в норму. Фу…','Вернитесь к Альтсобе Тотему Ярости на Заставу Отравленной Крови, что в Оскверненном Лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нечистые слизнюки',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 нечистых слизнюков.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это утешительные новости… возможно, теперь мне будет легче отдохнуть и прийти в себя.$B$BМожет быть и желудок мой тоже придет в норму. Фу…',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Альтсобе Тотему Ярости на Заставу Отравленной Крови, что в Оскверненном Лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28191,'Заслуженная участь','Земли на юге заполонили обсидиановые дракониды. Сейчас они не могут нас потеснить, но в военное время нельзя недооценивать ни одного врага. $B$BТак что твоя задача – нанести упреждающий удар. Уничтожь их, чтобы мы могли и дальше очищать наши земли от черных драконов.','Убейте 10 обсидиановых драконидов.','Во время нашей первой встречи я и подумать не могла, что ты станешь таким хорошим союзником.','Поговорите с Лирастразой на Сумеречном нагорье, на северо-западе от Обсидианового леса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Заслуженная участь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Земли на юге заполонили обсидиановые дракониды. Сейчас они не могут нас потеснить, но в военное время нельзя недооценивать ни одного врага. $B$BТак что твоя задача – нанести упреждающий удар. Уничтожь их, чтобы мы могли и дальше очищать наши земли от черных драконов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 обсидиановых драконидов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Во время нашей первой встречи я и подумать не могла, что ты станешь таким хорошим союзником.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Лирастразой на Сумеречном нагорье, на северо-западе от Обсидианового леса.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`) VALUES (28192,'Никто не уйдет живым','Наша ферма находится в полной изоляции! Никакой связи с внешним миром! Мы до сих пор пытаемся разобраться, что же произошло на самом деле, но у меня есть такая теория: работники наелись грибов и каким-то образом мутировали в ужасную нежить. Я хочу сказать, что других объяснений я не вижу. Ведь это же обычная ферма! Мы выращиваем тут грибы! И слизней!$b$bОсмотрись вокруг, |3-6($c), потому что раз уж ты здесь, ты не можешь уйти, не решив проблемы.$b$bИ будь осторожнее!','Оцените ситуацию в Топких полях.','Как видишь, все они стали монстрами! Почти все мои стражи убиты, а те, кому удалось спастись, следят за баррикадами, чтобы этим ужасным существам не удалось выйти наружу.$B$BНам нужна твоя помощь!','Оцените ситуацию в Топких полях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Никто не уйдет живым',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наша ферма находится в полной изоляции! Никакой связи с внешним миром! Мы до сих пор пытаемся разобраться, что же произошло на самом деле, но у меня есть такая теория: работники наелись грибов и каким-то образом мутировали в ужасную нежить. Я хочу сказать, что других объяснений я не вижу. Ведь это же обычная ферма! Мы выращиваем тут грибы! И слизней!$b$bОсмотрись вокруг, |3-6($c), потому что раз уж ты здесь, ты не можешь уйти, не решив проблемы.$b$bИ будь осторожнее!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Оцените ситуацию в Топких полях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Как видишь, все они стали монстрами! Почти все мои стражи убиты, а те, кому удалось спастись, следят за баррикадами, чтобы этим ужасным существам не удалось выйти наружу.$B$BНам нужна твоя помощь!',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Оцените ситуацию в Топких полях.',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28193,'Здание не есть само взрывайт!$B$BМеня желание прикончать, я выяснить, кто есть это!$B$BИдти к наш гости. Смотреть их и мне докладать.$B$BИм что знайт, я выбивайт сведения!$B$BФольно! Идти!','Командир Шнотц хочет, чтобы вы понаблюдали за гостями в лагере Шнотца.','Они нихт знайт?$B$BГут... Поискать продолжайт...','Поговорите с командиром Шнотцем в лагере Шнотца.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Здание не есть само взрывайт!$B$BМеня желание прикончать, я выяснить, кто есть это!$B$BИдти к наш гости. Смотреть их и мне докладать.$B$BИм что знайт, я выбивайт сведения!$B$BФольно! Идти!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Командир Шнотц хочет, чтобы вы понаблюдали за гостями в лагере Шнотца.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Они нихт знайт?$B$BГут... Поискать продолжайт...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с командиром Шнотцем в лагере Шнотца.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (28194,'Побег','Пожалуйста, |3-6($c)! Нам нужна твоя помощь!$B$BНас здесь держат против нашей воли. И еще неизвестно, что этот командир с нами теперь сделает!$B$BБыть может, если ты добудешь нам их форму, мы сумеем ускользнуть.$B$BНе следовало сюда вообще соваться, теперь я это понимаю.$B$BЕсли ты поможешь нам бежать, я напишу всю правду о том, что здесь произошло.$B$BДобыть бы только одежду моряков с тех кораблей.','Плодовитый писатель из лагеря Шнотца хочет, чтобы вы раздобыли 6 комплектов униформы моряков Шнотца.','Поговорите с плодовитым писателем в лагере Шнотца.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Побег',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пожалуйста, |3-6($c)! Нам нужна твоя помощь!$B$BНас здесь держат против нашей воли. И еще неизвестно, что этот командир с нами теперь сделает!$B$BБыть может, если ты добудешь нам их форму, мы сумеем ускользнуть.$B$BНе следовало сюда вообще соваться, теперь я это понимаю.$B$BЕсли ты поможешь нам бежать, я напишу всю правду о том, что здесь произошло.$B$BДобыть бы только одежду моряков с тех кораблей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Плодовитый писатель из лагеря Шнотца хочет, чтобы вы раздобыли 6 комплектов униформы моряков Шнотца.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с плодовитым писателем в лагере Шнотца.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) VALUES (28194,'Ну как, получилось раздобыть для нас форму, $R?') ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как, получилось раздобыть для нас форму, $R?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (28195,'Послание всем остальным','Я имейт мой шпион всюда, |3-6($r).$B$BИ знайт, что шептать солдаты. Я терпеть их выходка долго, больше терпеть нет!$B$BЯ показывайт мои люди, такое поведенье запрещайт!$B$BТы наказать официрен корабли в гавань. Эти были громче всех.$B$BТы заканчивайт, я смотреть донесений и решать, что делайт.$B$BФольно!','Командир Шнотц приказывает вам убить капитана Маргана, капитана Корка и капитана Кронха.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Послание всем остальным',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я имейт мой шпион всюда, |3-6($r).$B$BИ знайт, что шептать солдаты. Я терпеть их выходка долго, больше терпеть нет!$B$BЯ показывайт мои люди, такое поведенье запрещайт!$B$BТы наказать официрен корабли в гавань. Эти были громче всех.$B$BТы заканчивайт, я смотреть донесений и решать, что делайт.$B$BФольно!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Командир Шнотц приказывает вам убить капитана Маргана, капитана Корка и капитана Кронха.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (28196,'Битва за Хилсбрад') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Битва за Хилсбрад',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28197,'Осторожность – ключ к успеху','Мы должны уничтожить доказательства, $n! Ой, я сказал "доказательства"? Я имел в виду эту сумасшедшую нежить! В общем, осторожность – это ключ к успеху. Нельзя допустить, чтобы эти буйствующие ходячие мертвецы выбрались за пределы Топких полей. И никто из посторонних не должен знать об этом!$b$bК юго-востоку отсюда, там, где раньше была старая грибная ферма, ты найдешь ожившего монстра, известного под именем горожанина Вилкса, и его пособника, клерка Горация Белоконя. Они создают большие проблемы для моей охраны. Найди их и убей!','Убейте горожанина Вилкса и клерка Горация Белоконя.','Молодец! После того как Вилкс сожрал огромное количество грибов и других токсичных веществ, мы его повесили. Но после смерти он очнулся, переродившись в нежить. Он положил много моих стражей, прежде чем не забрался в укрытие.$B$BПочему они все это ели? Понятия не имею! Здесь же просто ферма, парень, обычная ферма!','Вернитесь к надзирателю Штиллецу в Топкие поля, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Осторожность – ключ к успеху',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы должны уничтожить доказательства, $n! Ой, я сказал "доказательства"? Я имел в виду эту сумасшедшую нежить! В общем, осторожность – это ключ к успеху. Нельзя допустить, чтобы эти буйствующие ходячие мертвецы выбрались за пределы Топких полей. И никто из посторонних не должен знать об этом!$b$bК юго-востоку отсюда, там, где раньше была старая грибная ферма, ты найдешь ожившего монстра, известного под именем горожанина Вилкса, и его пособника, клерка Горация Белоконя. Они создают большие проблемы для моей охраны. Найди их и убей!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте горожанина Вилкса и клерка Горация Белоконя.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Молодец! После того как Вилкс сожрал огромное количество грибов и других токсичных веществ, мы его повесили. Но после смерти он очнулся, переродившись в нежить. Он положил много моих стражей, прежде чем не забрался в укрытие.$B$BПочему они все это ели? Понятия не имею! Здесь же просто ферма, парень, обычная ферма!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к надзирателю Штиллецу в Топкие поля, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (28198,'Слабое звено','Говорят, крепость цепи определяется крепостью ее самого слабого звена.$B$BЯ всецело поддерживаю эту теорию и даже готов ее дополнить.$B$BВместо того чтобы удалять из цепи слабое звено, его необходимо... усилить.$B$BИ тогда другие станут из кожи вон лезть, лишь бы самим не оказаться на месте самого слабого звена.$B$BВ случае с моей армией у слабого звена есть имя – Салхет.$B$BОн тренируется у подножия той лестницы.$B$BДля начала придумай для него что-нибудь полегче. Например, пусть начнет с гиен на западных холмах.','Поговорите с Салхетом на заставе рамкахенов в Ульдуме.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Слабое звено',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Говорят, крепость цепи определяется крепостью ее самого слабого звена.$B$BЯ всецело поддерживаю эту теорию и даже готов ее дополнить.$B$BВместо того чтобы удалять из цепи слабое звено, его необходимо... усилить.$B$BИ тогда другие станут из кожи вон лезть, лишь бы самим не оказаться на месте самого слабого звена.$B$BВ случае с моей армией у слабого звена есть имя – Салхет.$B$BОн тренируется у подножия той лестницы.$B$BДля начала придумай для него что-нибудь полегче. Например, пусть начнет с гиен на западных холмах.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Салхетом на заставе рамкахенов в Ульдуме.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (28199,'Во имя науки!','Образцы... да... нужны образцы! Нужно изучить этих подопытных кроликов... ээ... я имею в виду, этих несчастных рабочих.$b$bОтправляйся на юго-восток и на первой же ферме убей восставших вурдалаков. А из их разлагающихся тел возьми образцы плоти. И принеси их мне!$b$b<Арно потирает руки и безумно хихикает без видимых на то причин.>$b$bНадо изучить!','Достаньте 6 образцов плоти.','Эти образцы позволят нам лучше понять безумную нежить. Вот тебе за труды.','Наука ждет!','Принесите образцы плоти ваятелю плоти Арно в Топкие поля, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Во имя науки!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Образцы... да... нужны образцы! Нужно изучить этих подопытных кроликов... ээ... я имею в виду, этих несчастных рабочих.$b$bОтправляйся на юго-восток и на первой же ферме убей восставших вурдалаков. А из их разлагающихся тел возьми образцы плоти. И принеси их мне!$b$b<Арно потирает руки и безумно хихикает без видимых на то причин.>$b$bНадо изучить!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Достаньте 6 образцов плоти.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Эти образцы позволят нам лучше понять безумную нежить. Вот тебе за труды.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Наука ждет!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите образцы плоти ваятелю плоти Арно в Топкие поля, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (28200,'Жизненно необходимые припасы','Как ты понимаешь, мы сейчас не вполне готовы к бою.$B$BПлеменам тол\'виров уже тысячу лет не доводилось вступать в войну.$B$BОднако все те боевые протоколы, что титаны вложили в наших предков, никуда не делись. Часть из них превратилась в инстинкты, другие мы передаем от поколения к поколению в виде обрядов.$B$BНо все это не в силах компенсировать недостаток припасов. Нам нужно оружие. И доспехи.$B$BЛучшие доспехи получаются из шкур речных кроколисков, что водятся в реке неподалеку. Помоги нам добыть несколько шкур.','Раздобудьте 20 затвердевших шкур кроколисков.','Хорошо, что ты не считаешь такое занятие чем-то неподобающим для себя.','Вернитесь к сержанту Мехату на заставу рамкахенов в Ульдуме.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жизненно необходимые припасы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как ты понимаешь, мы сейчас не вполне готовы к бою.$B$BПлеменам тол\'виров уже тысячу лет не доводилось вступать в войну.$B$BОднако все те боевые протоколы, что титаны вложили в наших предков, никуда не делись. Часть из них превратилась в инстинкты, другие мы передаем от поколения к поколению в виде обрядов.$B$BНо все это не в силах компенсировать недостаток припасов. Нам нужно оружие. И доспехи.$B$BЛучшие доспехи получаются из шкур речных кроколисков, что водятся в реке неподалеку. Помоги нам добыть несколько шкур.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте 20 затвердевших шкур кроколисков.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Хорошо, что ты не считаешь такое занятие чем-то неподобающим для себя.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к сержанту Мехату на заставу рамкахенов в Ульдуме.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (28201,'От лемехов – к мечам','Армия у нас немаленькая, но, боюсь, для предстоящего решающего сражения с ордами неферсетов нам понадобится собрать всех годных к военной службе тол\'виров из Рамкахена и Орсиса.$B$BЯ хочу, чтобы вербовкой новых солдат $gзанялся:занялась; ты.$B$BОтправляйся на ту сторону реки, на Поля Ахенет, и завербуй работников, что там трудятся.','Завербуйте 8 рамкахенов-работников.','Вернитесь к главнокомандующему Камзесу на заставу рамкахенов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','От лемехов – к мечам',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Армия у нас немаленькая, но, боюсь, для предстоящего решающего сражения с ордами неферсетов нам понадобится собрать всех годных к военной службе тол\'виров из Рамкахена и Орсиса.$B$BЯ хочу, чтобы вербовкой новых солдат $gзанялся:занялась; ты.$B$BОтправляйся на ту сторону реки, на Поля Ахенет, и завербуй работников, что там трудятся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Завербуйте 8 рамкахенов-работников.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к главнокомандующему Камзесу на заставу рамкахенов.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28202,'Идеальный костюм','Основываясь на твоем весе, комплекции и размере, мы тебя нарядим в орка. Вражеская армия в основном состоит из орков, так что ты прекрасно впишешься в их ряды.$b$bТебе что-то известно о пошиве одежды? Если нет, то вот тебе мой первый урок. Вон стоит мой рабочий стол со всеми необходимыми материалами.$b$bПодойди к нему, возьми все, что сочтешь необходимым, и возвращайся обратно.','Возьмите необходимые материалы с портняжного стола и передайте их Теларону Крутоиглу в Узкоклинье.','Что это? Это и есть твой маскировочный костюм?.$B$BНадо признаться, моя уверенность в успехе операции тает на глазах. Рад был познакомиться с тобой, приятель.','Вернитесь к Джону Джею Кишану в Узкоклинье, что находится в Пылающих степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Идеальный костюм',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Основываясь на твоем весе, комплекции и размере, мы тебя нарядим в орка. Вражеская армия в основном состоит из орков, так что ты прекрасно впишешься в их ряды.$b$bТебе что-то известно о пошиве одежды? Если нет, то вот тебе мой первый урок. Вон стоит мой рабочий стол со всеми необходимыми материалами.$b$bПодойди к нему, возьми все, что сочтешь необходимым, и возвращайся обратно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возьмите необходимые материалы с портняжного стола и передайте их Теларону Крутоиглу в Узкоклинье.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что это? Это и есть твой маскировочный костюм?.$B$BНадо признаться, моя уверенность в успехе операции тает на глазах. Рад был познакомиться с тобой, приятель.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джону Джею Кишану в Узкоклинье, что находится в Пылающих степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28203,'Идеальный костюм','Основываясь на твоем весе, комплекции и размере, мы тебя нарядим в огра. Огры из клана Огненного Чрева всегда работали на клан Черной горы, так что ты прекрасно впишешься в их ряды.$b$bТебе что-то известно о пошиве одежды? Если нет, то вот тебе мой первый урок. Вон стоит мой рабочий стол со всеми необходимыми материалами.$b$bПодойди к нему, возьми все, что сочтешь необходимым, и возвращайся обратно. Теларон тебя быстро приоденет.','Возьмите необходимые материалы с портняжного стола и передайте их Теларону Крутоиглу в Узкоклинье.','Что это? Это и есть твой маскировочный костюм?.$B$BНадо признаться, моя уверенность в успехе операции тает на глазах. Рад был познакомиться с тобой, приятель.','Вернитесь к Джону Джею Кишану в Узкоклинье, что находится в Пылающих степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Идеальный костюм',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Основываясь на твоем весе, комплекции и размере, мы тебя нарядим в огра. Огры из клана Огненного Чрева всегда работали на клан Черной горы, так что ты прекрасно впишешься в их ряды.$b$bТебе что-то известно о пошиве одежды? Если нет, то вот тебе мой первый урок. Вон стоит мой рабочий стол со всеми необходимыми материалами.$b$bПодойди к нему, возьми все, что сочтешь необходимым, и возвращайся обратно. Теларон тебя быстро приоденет.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возьмите необходимые материалы с портняжного стола и передайте их Теларону Крутоиглу в Узкоклинье.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что это? Это и есть твой маскировочный костюм?.$B$BНадо признаться, моя уверенность в успехе операции тает на глазах. Рад был познакомиться с тобой, приятель.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джону Джею Кишану в Узкоклинье, что находится в Пылающих степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (28204,'Идеальный костюм','Основываясь на твоем весе, комплекции и размере, мы тебя нарядим в гоблина. Орки Черной горы часто нанимают гоблинов-торговцев, так что ты прекрасно впишешься в их ряды.$b$bТебе что-то известно о пошиве одежды? Если нет, то вот тебе мой первый урок. Вон стоит мой рабочий стол со всеми необходимыми материалами.$b$bПодойди к нему, возьми все, что сочтешь необходимым, и возвращайся обратно. Теларон тебя быстро приоденет.','Возьмите необходимые материалы с портняжного стола и передайте их Теларону Крутоиглу в Узкоклинье.','Вернитесь к Джону Джею Кишану в Узкоклинье, что находится в Пылающих степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Идеальный костюм',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Основываясь на твоем весе, комплекции и размере, мы тебя нарядим в гоблина. Орки Черной горы часто нанимают гоблинов-торговцев, так что ты прекрасно впишешься в их ряды.$b$bТебе что-то известно о пошиве одежды? Если нет, то вот тебе мой первый урок. Вон стоит мой рабочий стол со всеми необходимыми материалами.$b$bПодойди к нему, возьми все, что сочтешь необходимым, и возвращайся обратно. Теларон тебя быстро приоденет.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возьмите необходимые материалы с портняжного стола и передайте их Теларону Крутоиглу в Узкоклинье.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джону Джею Кишану в Узкоклинье, что находится в Пылающих степях.',`completedtext_loc8`);
