INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (28581,'Приказ вождя: Тлеющее ущелье','Всем годным к военной службе ордынцам надлежит явиться к Джеку Глыбоногу в Братство Тория.$b$bКлан Изувеченной Длани сообщает о том, что дворфы Черного Железа из Тлеющего ущелья к чему-то готовятся. Твоим заданием будет разведать об этом все, что сможешь, и помешать их действиям.$b$bЧтобы попасть в Тлеющее ущелье, иди по дороге, что ведет из Бесплодных земель на запад.$b$bСудьба зовет!','Доложите о своем прибытии Джеку Глыбоногу в Братстве Тория, что в Тлеющем ущелье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приказ вождя: Тлеющее ущелье',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Всем годным к военной службе ордынцам надлежит явиться к Джеку Глыбоногу в Братство Тория.$b$bКлан Изувеченной Длани сообщает о том, что дворфы Черного Железа из Тлеющего ущелья к чему-то готовятся. Твоим заданием будет разведать об этом все, что сможешь, и помешать их действиям.$b$bЧтобы попасть в Тлеющее ущелье, иди по дороге, что ведет из Бесплодных земель на запад.$b$bСудьба зовет!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доложите о своем прибытии Джеку Глыбоногу в Братстве Тория, что в Тлеющем ущелье.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (28582,'Воззвание к героям: Тлеющее ущелье!','Доложите о своем прибытии Джеку Глыбоногу в Братстве Тория, что в Тлеющем ущелье.','Нам тоже кажутся подозрительными действия Черного Железа в последнее время.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Воззвание к героям: Тлеющее ущелье!',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доложите о своем прибытии Джеку Глыбоногу в Братстве Тория, что в Тлеющем ущелье.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Нам тоже кажутся подозрительными действия Черного Железа в последнее время.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (28583,'Психходельня','Мой проект нового крошшера крут, $n. Реально крут! Теперь важно защитить свою интеллектуальную собственность. Запатентовать, выбрать дилеров, засудить плагиаторов... Ах да, и взятки раздать, конечно!$B$BВот, отнеси-ка эту заявку на патент капитану Психхо в Психходельню. Он пережил крушение своего дирижабля, так что теперь наверняка ищет новые идеи для бизнеса.$B$BПсихходельня на севере отсюда, на абсолютно надежной горной вершине. Давай-ка, $gдружок:подружка;, одна нога здесь, другая там!','Отнесите заявку на патент капитану Психхо в Психходельню на Сумеречном нагорье.','Я тебя помню! Мы с тобой вместе летели сюда на дирижабле.','Отнесите заявку на патент капитану Психхо в Психходельню на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Психходельня',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мой проект нового крошшера крут, $n. Реально крут! Теперь важно защитить свою интеллектуальную собственность. Запатентовать, выбрать дилеров, засудить плагиаторов... Ах да, и взятки раздать, конечно!$B$BВот, отнеси-ка эту заявку на патент капитану Психхо в Психходельню. Он пережил крушение своего дирижабля, так что теперь наверняка ищет новые идеи для бизнеса.$B$BПсихходельня на севере отсюда, на абсолютно надежной горной вершине. Давай-ка, $gдружок:подружка;, одна нога здесь, другая там!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите заявку на патент капитану Психхо в Психходельню на Сумеречном нагорье.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я тебя помню! Мы с тобой вместе летели сюда на дирижабле.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите заявку на патент капитану Психхо в Психходельню на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28584,'Сработано на совесть','Я тебе так скажу, $gкомандир:дорогуша;: если бы не эта ошибка природы вон там напротив, Психходельня сейчас стояла бы себе и горя не знала.$B$BК несчастью для всех нас, товарища Ротмана "Несуразные Штаны" угораздило развернуть город на вершине горы! Нет, ну в самом деле, кому такое в голову-то взбредет?!$B$BНу и теперь у нас, разумеется, утечка на утечке сидит и утечкой погоняет из-за неисправных вентилей... Может, поможешь мне их замотать вот этой термолентой?','Замотайте термолентой 10 неисправных вентилей.','Ну вот и славненько. А теперь не замотать ли нам этой термолентой Ротману рот...','Вернитесь к Бретту в Психходельню, что на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сработано на совесть',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я тебе так скажу, $gкомандир:дорогуша;: если бы не эта ошибка природы вон там напротив, Психходельня сейчас стояла бы себе и горя не знала.$B$BК несчастью для всех нас, товарища Ротмана "Несуразные Штаны" угораздило развернуть город на вершине горы! Нет, ну в самом деле, кому такое в голову-то взбредет?!$B$BНу и теперь у нас, разумеется, утечка на утечке сидит и утечкой погоняет из-за неисправных вентилей... Может, поможешь мне их замотать вот этой термолентой?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Замотайте термолентой 10 неисправных вентилей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну вот и славненько. А теперь не замотать ли нам этой термолентой Ротману рот...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бретту в Психходельню, что на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (28585,'[Deprecated] Polished') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[Deprecated] Polished',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (28586,'Надувные пони спешат на помощь','Из-за этого кретина – вон напротив стоит – наши гибнут!$B$BЭтот Бретт "Криворучко" развернул Психходельню черт знает где, теперь тут все на честном слове держится... Взрывами, вызванными неустойчивостью, наших рабочих сметает с платформ прямо в воду.$B$B$n, может быть, слетаешь вниз и сбросишь им на подмогу надувных пони?','Сбросьте надувных пони 10 работникам Психходельни, свалившимся в воду.','Вернитесь к Светобуму Ротману в Психходельню на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Надувные пони спешат на помощь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Из-за этого кретина – вон напротив стоит – наши гибнут!$B$BЭтот Бретт "Криворучко" развернул Психходельню черт знает где, теперь тут все на честном слове держится... Взрывами, вызванными неустойчивостью, наших рабочих сметает с платформ прямо в воду.$B$B$n, может быть, слетаешь вниз и сбросишь им на подмогу надувных пони?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сбросьте надувных пони 10 работникам Психходельни, свалившимся в воду.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Светобуму Ротману в Психходельню на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (28587,'Помощь клана Северного Волка','Я изучу военные планы Грозовой Вершины и спланирую нападение. Мне нужно, чтобы ты $gотправился:отправилась; в Альтеракскую долину и $gзаручился:заручилась; поддержкой клана Северного Волка, это клан самого нашего бывшего вождя Тралла. Они помогут нам сразиться с дворфами Грозовой Вершины! Вместе мы сокрушим их и выдворим из Лордерона навсегда!$b$bИди, $n. Альтеракская долина находится к северо-востоку от Мельницы Таррен. Найди Воггу Смертобоя и скажи ему, что Орда нуждается в помощи клана Северного Волка!$b$bЛок\'тар!','Ты с Мельницы Таррен? От тебя пахнет смертью…') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Помощь клана Северного Волка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я изучу военные планы Грозовой Вершины и спланирую нападение. Мне нужно, чтобы ты $gотправился:отправилась; в Альтеракскую долину и $gзаручился:заручилась; поддержкой клана Северного Волка, это клан самого нашего бывшего вождя Тралла. Они помогут нам сразиться с дворфами Грозовой Вершины! Вместе мы сокрушим их и выдворим из Лордерона навсегда!$b$bИди, $n. Альтеракская долина находится к северо-востоку от Мельницы Таррен. Найди Воггу Смертобоя и скажи ему, что Орда нуждается в помощи клана Северного Волка!$b$bЛок\'тар!',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты с Мельницы Таррен? От тебя пахнет смертью…',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (28588,'Засилье Громового Молота','Эти двое придурков все спорят, кто из них больше виноват, а Психходельня, между тем, уже кишмя кишит врагами!$B$BКуда ни плюнь – всюду эти ничтожества из Громового Молота! Выдвори этих вонючих выпивох прочь из Психходельни!','Убейте 10 налетчиков из клана Громового Молота.','Вернитесь к капитану Психхо в Психходельню на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Засилье Громового Молота',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти двое придурков все спорят, кто из них больше виноват, а Психходельня, между тем, уже кишмя кишит врагами!$B$BКуда ни плюнь – всюду эти ничтожества из Громового Молота! Выдвори этих вонючих выпивох прочь из Психходельни!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 налетчиков из клана Громового Молота.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Психхо в Психходельню на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28589,'Всякая всячина','Сбейте 15 штормокрылов из клана Громового Молота.','Вот это по-нашему! А им, наверное, обидно, что их посшибали каким-то мусором.','Вернитесь к капитану Психхо в Психходельню на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Всякая всячина',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сбейте 15 штормокрылов из клана Громового Молота.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот это по-нашему! А им, наверное, обидно, что их посшибали каким-то мусором.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Психхо в Психходельню на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (28590,'Карательные меры','Я, кажется, знаю, кому из альянсовского отребья сегодня не поздоровится. У них, кстати, есть кое-что из наших вещей. Я распорядился начать полномасштабное наступление на Высокий берег.$B$BСадись на "Небокрошшер" и присоединяйся к атаке. Патч расскажет тебе что к чему, когда доберешься до места.','Поговорите с Патчем на борту "Небокрошшера", кружащего над Высоким берегом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Карательные меры',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я, кажется, знаю, кому из альянсовского отребья сегодня не поздоровится. У них, кстати, есть кое-что из наших вещей. Я распорядился начать полномасштабное наступление на Высокий берег.$B$BСадись на "Небокрошшер" и присоединяйся к атаке. Патч расскажет тебе что к чему, когда доберешься до места.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Патчем на борту "Небокрошшера", кружащего над Высоким берегом.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28591,'Зенитчик-лимитчик сидел на стене...','Ты, похоже, любишь пострелять, $n. Занимай любую из тех вон пушек и задай жару их зенитчикам на стенах.$B$BИ поживее, ладно? Пока наш корабль не превратили в огромного цыпленка табака.','Убейте 80 стрелков Высокого берега, 12 канониров Высокого берега и разрушьте 4 зенитные пушки Высокого берега из пушки "Небокрошшера".','Чудеса современной гоблинской военной техники, скажи? Обожаю этих крошек.','Доложите Патчу на борту "Небокрошшера", кружащего над Высоким берегом на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зенитчик-лимитчик сидел на стене...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты, похоже, любишь пострелять, $n. Занимай любую из тех вон пушек и задай жару их зенитчикам на стенах.$B$BИ поживее, ладно? Пока наш корабль не превратили в огромного цыпленка табака.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 80 стрелков Высокого берега, 12 канониров Высокого берега и разрушьте 4 зенитные пушки Высокого берега из пушки "Небокрошшера".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Чудеса современной гоблинской военной техники, скажи? Обожаю этих крошек.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доложите Патчу на борту "Небокрошшера", кружащего над Высоким берегом на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28592,'Прощальные дары','Уверен, у Патча в голове грандиозный план, но какая же это осада, если мы напоследок чего-нибудь не заминируем!$B$BСпускайся-ка вниз и заложи взрывчатку на корабле, у ворот крепости и в одной из тех северных башен. Этого хватит, чтобы их как следует тряхнуло.$B$BМы тоже собираемся садиться. Как закончишь, подходи к восточной башне – там и встретимся.','Заминируйте корабль, вход в крепость и одну из северных башен.','Хо-хо! Шоу что надо.$B$BОтличный салют на радость всему нагорью.','Разыщите Тиккера возле восточной башни Высокого берега на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прощальные дары',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Уверен, у Патча в голове грандиозный план, но какая же это осада, если мы напоследок чего-нибудь не заминируем!$B$BСпускайся-ка вниз и заложи взрывчатку на корабле, у ворот крепости и в одной из тех северных башен. Этого хватит, чтобы их как следует тряхнуло.$B$BМы тоже собираемся садиться. Как закончишь, подходи к восточной башне – там и встретимся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заминируйте корабль, вход в крепость и одну из северных башен.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хо-хо! Шоу что надо.$B$BОтличный салют на радость всему нагорью.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Разыщите Тиккера возле восточной башни Высокого берега на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (28593,'Дело на миллион золотых','Вместе с дирижаблем Гарроша на землю рухнул и индукционный самофланж, который ты для нас $gраздобыл:раздобыла; в Азшаре. Альянс держит его где-то в этой крепости. Психхо хочет его вернуть.$B$BДумаю, он спрятан в подвале, так что начни искать оттуда. Как отыщешь, принеси его мне, к восточной башне.','Отыщите индукционный самофланж.','Великолепно! Психхо тебя озолотит за то, что ты вернул ему эту игрушку. Ай да молодчина!','Поторопись, Психхо ждет.','Разыщите Патча возле восточной башни Высокого берега на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дело на миллион золотых',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вместе с дирижаблем Гарроша на землю рухнул и индукционный самофланж, который ты для нас $gраздобыл:раздобыла; в Азшаре. Альянс держит его где-то в этой крепости. Психхо хочет его вернуть.$B$BДумаю, он спрятан в подвале, так что начни искать оттуда. Как отыщешь, принеси его мне, к восточной башне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщите индукционный самофланж.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Великолепно! Психхо тебя озолотит за то, что ты вернул ему эту игрушку. Ай да молодчина!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Поторопись, Психхо ждет.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Разыщите Патча возле восточной башни Высокого берега на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28594,'Слезная река, Высокие берега','Поди и сделай отбивную из этих отбросов Альянса! Из кого хочешь – на твой вкус. Хочу, чтобы ты там $gустроил:устроила; переполох, пока будешь выполнять основное задание.$B$BКак закончишь, возвращайся к нам, к восточной башне.','Убейте 10 защитников Высокого берега.','Вот так-то лучше. Разлетелись как листья по ветру. Не такие уж они и бравые вояки, когда до дела доходит, верно?','Разыщите Патча возле восточной башни Высокого берега на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Слезная река, Высокие берега',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Поди и сделай отбивную из этих отбросов Альянса! Из кого хочешь – на твой вкус. Хочу, чтобы ты там $gустроил:устроила; переполох, пока будешь выполнять основное задание.$B$BКак закончишь, возвращайся к нам, к восточной башне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 защитников Высокого берега.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот так-то лучше. Разлетелись как листья по ветру. Не такие уж они и бравые вояки, когда до дела доходит, верно?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Разыщите Патча возле восточной башни Высокого берега на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (28595,'Психходелишки','Ну вот, мы тут почти закончили. Пора выдвигаться.$B$BНа вершине башни Трит держит под парами несколько гирокоптеров. Поговори с ней – и долетишь до Психходельни с ветерком. А мы тепло попрощаемся с местными и догоним тебя.','Обратитесь к Трит, чтобы она отправила вас в Психходельню. По прибытии отдайте индукционный самофланж капитану Психхо.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Психходелишки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну вот, мы тут почти закончили. Пора выдвигаться.$B$BНа вершине башни Трит держит под парами несколько гирокоптеров. Поговори с ней – и долетишь до Психходельни с ветерком. А мы тепло попрощаемся с местными и догоним тебя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обратитесь к Трит, чтобы она отправила вас в Психходельню. По прибытии отдайте индукционный самофланж капитану Психхо.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (28595,'Ох, гляжу – и не нарадуюсь. С этой лапотулей мой флот снова будет в небе – и глазом не успеешь моргнуть!$B$BТы знаешь, что нравится мне, Кузеньказ. Но и я знаю, что тебе придется по вкусу. Вот, держи.','Ну скажи, что все прошло удачно! Ты ведь всегда во всем преуспеваешь. Где там моя красавица?') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ох, гляжу – и не нарадуюсь. С этой лапотулей мой флот снова будет в небе – и глазом не успеешь моргнуть!$B$BТы знаешь, что нравится мне, Кузеньказ. Но и я знаю, что тебе придется по вкусу. Вот, держи.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну скажи, что все прошло удачно! Ты ведь всегда во всем преуспеваешь. Где там моя красавица?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28596,'Добро пожаловать на Высокий берег!','Добро пожаловать на нагорье, солдат. Ты как раз вовремя.$B$BВойска Орды только что начали атаку с воздуха. Вступай в бой и разберись с ними. Всех перебей!','Уничтожьте 10 воинов Орды на Высоком берегу.','Так-то лучше. Думаю, теперь мы тут и с остальным разберемся.','Вернитесь к лейтенанту Фоксу на Высокий берег, что на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Добро пожаловать на Высокий берег!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Добро пожаловать на нагорье, солдат. Ты как раз вовремя.$B$BВойска Орды только что начали атаку с воздуха. Вступай в бой и разберись с ними. Всех перебей!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 10 воинов Орды на Высоком берегу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так-то лучше. Думаю, теперь мы тут и с остальным разберемся.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лейтенанту Фоксу на Высокий берег, что на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (28597,'Меж двух огней','Здорово! Придется нам сломя голову кидаться в бой, $n. Похоже, у Высокого берега есть одна проблема с дирижаблем: вон тот аппарат поливает крепостные стены почем зря.$B$BСлушай, мне тут пришла идейка настолько бредовая – аж до гениальности! И нужен мне всего-навсего порох.$B$BРаздобудь сколько сможешь пороха – обшарь весь Высокий берег! Встретимся в торговых рядах.','Соберите 10 мешков оружейного пороха.','Нужно еще пороха! Тащи еще пороха! Еще, еще, еще!..','Обратитесь к Фарго Кремневому Затвору в западной части Высокого берега на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Меж двух огней',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Здорово! Придется нам сломя голову кидаться в бой, $n. Похоже, у Высокого берега есть одна проблема с дирижаблем: вон тот аппарат поливает крепостные стены почем зря.$B$BСлушай, мне тут пришла идейка настолько бредовая – аж до гениальности! И нужен мне всего-навсего порох.$B$BРаздобудь сколько сможешь пороха – обшарь весь Высокий берег! Встретимся в торговых рядах.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 мешков оружейного пороха.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Нужно еще пороха! Тащи еще пороха! Еще, еще, еще!..',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Обратитесь к Фарго Кремневому Затвору в западной части Высокого берега на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (28598,'Целясь ввысь','Слушай сюда, $n. Я нашел самую большую пушку на Высоком берегу! Сейчас опробуем трюк, о котором поведал мне мой батя, а ему – его батя, а тому – его папашка, как раз перед тем, как его разнесло в клочки.$B$BНазывается "|3-6($c)-снаряд".$B$BБерется, значит, |3-6($r) |3-6($c), заряжается в пушку покрупнее, а потом... да успокойся! Обычно все обходится.$B$BПодержи-ка вот взрывчатку и далеко не уходи. Когда эта дирижабель подлетит поближе, я запулю тебя прямо к ним на палубу. Заложи взрывчатку в трюме, а дальше... ну не знаю, что-нибудь по ходу сообразишь.','Дайте Фарго Кремневому Затвору выстрелить вами в дирижабль, а затем заложите взрывчатку в трюме воздушного судна.','Нет такой проблемы, которую не решить бомбой.','Вернитесь к Фарго Кремневому Затвору на Высокий берег, что на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Целясь ввысь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слушай сюда, $n. Я нашел самую большую пушку на Высоком берегу! Сейчас опробуем трюк, о котором поведал мне мой батя, а ему – его батя, а тому – его папашка, как раз перед тем, как его разнесло в клочки.$B$BНазывается "|3-6($c)-снаряд".$B$BБерется, значит, |3-6($r) |3-6($c), заряжается в пушку покрупнее, а потом... да успокойся! Обычно все обходится.$B$BПодержи-ка вот взрывчатку и далеко не уходи. Когда эта дирижабель подлетит поближе, я запулю тебя прямо к ним на палубу. Заложи взрывчатку в трюме, а дальше... ну не знаю, что-нибудь по ходу сообразишь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Дайте Фарго Кремневому Затвору выстрелить вами в дирижабль, а затем заложите взрывчатку в трюме воздушного судна.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Нет такой проблемы, которую не решить бомбой.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фарго Кремневому Затвору на Высокий берег, что на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (28599,'Курдран ждет','Кажется, наступление прекратилось, $n. Жаль, конечно, ведь мы так и не попробовали |3-6($c)-ракету...$B$BКак бы там ни было, Курдран Громовой Молот ждет тебя в крепости с распростертыми объятиями, чтобы как следует отблагодарить. Ты $gзаслужил:заслужила; награду! Отправляйся к нему.$B$BА я пойду разведаю, что там на берегу.','Поговорите с Курдраном Громовым Молотом в Крепости Высокого берега на Сумеречном нагорье.','Тебя сам король послал, говоришь? Рад слышать, что Штормград вне опасности.$B$BЯ, признаться, ждал более солидного подкрепления, но поговаривают, что флот Альянса попал в ордынскую засаду по пути сюда. Парни, конечно, без боя не сдались, но вся флотилия – в труху...$B$BТак что без помощи героев вроде тебя у нас тут на нагорье руки связаны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Курдран ждет',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кажется, наступление прекратилось, $n. Жаль, конечно, ведь мы так и не попробовали |3-6($c)-ракету...$B$BКак бы там ни было, Курдран Громовой Молот ждет тебя в крепости с распростертыми объятиями, чтобы как следует отблагодарить. Ты $gзаслужил:заслужила; награду! Отправляйся к нему.$B$BА я пойду разведаю, что там на берегу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Курдраном Громовым Молотом в Крепости Высокого берега на Сумеречном нагорье.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебя сам король послал, говоришь? Рад слышать, что Штормград вне опасности.$B$BЯ, признаться, ждал более солидного подкрепления, но поговаривают, что флот Альянса попал в ордынскую засаду по пути сюда. Парни, конечно, без боя не сдались, но вся флотилия – в труху...$B$BТак что без помощи героев вроде тебя у нас тут на нагорье руки связаны.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`) VALUES (28600,'Суть верности','Я не уполномочен принимать подобные решения. Тебе нужно поговорить с нашим предводителем, Дрек\'Таром. Я уже отправил сообщение о твоем прибытии в крепость Северного Волка. Дрек\'Тар выйдет, чтобы лично поговорить с тобой.','Поговорите с Дрек\'Таром.','<Верховный полководец Кромуш бледнеет.>$B$BОни отреклись от нас? Они отреклись от Орды? Этого не может быть!$B$BЯ…$B$B<Кромуш падает на колени.>Я… со мной все будет в порядке. Мы справимся и без них. К черту клан Северного Волка!','Узнайте истинную суть верности.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Суть верности',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я не уполномочен принимать подобные решения. Тебе нужно поговорить с нашим предводителем, Дрек\'Таром. Я уже отправил сообщение о твоем прибытии в крепость Северного Волка. Дрек\'Тар выйдет, чтобы лично поговорить с тобой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Дрек\'Таром.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Верховный полководец Кромуш бледнеет.>$B$BОни отреклись от нас? Они отреклись от Орды? Этого не может быть!$B$BЯ…$B$B<Кромуш падает на колени.>Я… со мной все будет в порядке. Мы справимся и без них. К черту клан Северного Волка!',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Узнайте истинную суть верности.',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (28601,'Старое корыто') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Старое корыто',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (28602,'Будь готов ко всему','Ни один уважающий себя путешественник – равно как и благоразумный искатель приключений – никогда не войдет в пещеру, подземелье или гробницу без мотка длинной крепкой веревки... верно я говорю?$B$BМоя веревка осталась в вагончике со взрывчаткой, которую ты так бодро $gрванул:рванула;.$B$BТак что, может, поищешь в окрестностях... вдруг и найдется веревочка...','Соберите 6 обрывков веревки.','Поговорите с Харрисоном Джонсом в Зале Звезд.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Будь готов ко всему',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ни один уважающий себя путешественник – равно как и благоразумный искатель приключений – никогда не войдет в пещеру, подземелье или гробницу без мотка длинной крепкой веревки... верно я говорю?$B$BМоя веревка осталась в вагончике со взрывчаткой, которую ты так бодро $gрванул:рванула;.$B$BТак что, может, поищешь в окрестностях... вдруг и найдется веревочка...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 6 обрывков веревки.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Харрисоном Джонсом в Зале Звезд.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (28603,'Проникновение','Твое следующее задание будет заключаться в том, чтобы отправиться на запад на Высокий отрог и проникнуть на тренировочную площадку Грозовой Вершины. Одна из моих банши замаскирует тебя, и несмотря на то, что там сотни новобранцев Грозовой Вершины, ты сможешь свободно перемещаться среди наших врагов.$b$bОтправляйся на Высокий отрог и разыщи там инструкторов Грозовой Вершины. После этого сделай так, чтобы они напали на тебя! А когда нападут – убей их. Если инструкторы будут мертвы, некому будет обучать новобранцев Грозовой Вершины!','Убейте инструктора Руфуса, сержанта-инструктора Магнуса и капитана Грязноборода.','Поговорите с Мелизарой на Мельнице Таррен, что в Предгорьях Хилсбрада.','Натрави их друг на друга.','Мелизара','От сумятицы рукой подать до хаоса.','Мелизара') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Проникновение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Твое следующее задание будет заключаться в том, чтобы отправиться на запад на Высокий отрог и проникнуть на тренировочную площадку Грозовой Вершины. Одна из моих банши замаскирует тебя, и несмотря на то, что там сотни новобранцев Грозовой Вершины, ты сможешь свободно перемещаться среди наших врагов.$b$bОтправляйся на Высокий отрог и разыщи там инструкторов Грозовой Вершины. После этого сделай так, чтобы они напали на тебя! А когда нападут – убей их. Если инструкторы будут мертвы, некому будет обучать новобранцев Грозовой Вершины!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте инструктора Руфуса, сержанта-инструктора Магнуса и капитана Грязноборода.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Мелизарой на Мельнице Таррен, что в Предгорьях Хилсбрада.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Натрави их друг на друга.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Мелизара',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','От сумятицы рукой подать до хаоса.',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Мелизара',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28604,'Хитрость и мошенничество','Благодаря моей маскировке враги будут считать тебя $gодним:одной; из своих. И все же не ударяйся в безумства. Если ты привлечешь к себе внимание, дворфы могут что-то заподозрить и напасть на тебя!$b$bС учетом всего этого у меня есть план. Возьми эту бочку с отравленной водой и предложи утомленным новобранцам Грозовой Вершины утолить из нее жажду. Стоит им выпить этой воды, как они обречены. В конечном итоге они умрут от действия яда.','При помощи бочки с водой отравите 30 новобранцев Грозовой Вершины.','Умрут они не сразу, но умрут наверняка! А когда они наконец догадаются, кто в этом виноват, ты будешь уже далеко!','Поговорите с Лилит в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хитрость и мошенничество',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Благодаря моей маскировке враги будут считать тебя $gодним:одной; из своих. И все же не ударяйся в безумства. Если ты привлечешь к себе внимание, дворфы могут что-то заподозрить и напасть на тебя!$b$bС учетом всего этого у меня есть план. Возьми эту бочку с отравленной водой и предложи утомленным новобранцам Грозовой Вершины утолить из нее жажду. Стоит им выпить этой воды, как они обречены. В конечном итоге они умрут от действия яда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','При помощи бочки с водой отравите 30 новобранцев Грозовой Вершины.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Умрут они не сразу, но умрут наверняка! А когда они наконец догадаются, кто в этом виноват, ты будешь уже далеко!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Лилит в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (28605,'Власть','<Мысли Мелизары переплетаются с вашими мыслями.>$b$bПоследним твоим заданием будет разобраться с осадными машинами на Возвышенности Гэвина, которая находится к западу от Высокого отрога. Проберись туда и уничтожь дворфов и гномов инженеров, которые конструируют и укрепляют боевые машины Грозовой Вершины. И не забудь заложить там гоблинскую взрывчатку Кромуша.','Убейте 10 инженеров Грозовой Вершины.','Теперь, когда силам Грозовой Вершины нанесен урон, настало время для взрыва!','Вернитесь к Мелизаре на Мельницу Таррен, что в Предгорьях Хилсбрада.','Превосходство ведет к победе!','Мелизара') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Власть',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Мысли Мелизары переплетаются с вашими мыслями.>$b$bПоследним твоим заданием будет разобраться с осадными машинами на Возвышенности Гэвина, которая находится к западу от Высокого отрога. Проберись туда и уничтожь дворфов и гномов инженеров, которые конструируют и укрепляют боевые машины Грозовой Вершины. И не забудь заложить там гоблинскую взрывчатку Кромуша.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 инженеров Грозовой Вершины.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь, когда силам Грозовой Вершины нанесен урон, настало время для взрыва!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мелизаре на Мельницу Таррен, что в Предгорьях Хилсбрада.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Превосходство ведет к победе!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Мелизара',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (28606,'Ключи от хотрода') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ключи от хотрода',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (28607,'Ключи от хотрода') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ключи от хотрода',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (28608,'Мрачный склеп','Я рад видеть, что ты на ногах, $n. Неплохо выглядишь, особенно с учетом того, что ты так долго $gбыл мертв:была мертва;!$b$bНе всем так повезло. Если ты не против, я бы хотел попросить тебя сбегать за моим бальзамировочным составом и нитью для сшивания трупов, чтобы я мог подштопать эти тела. И то, и другое можно найти в Мрачном склепе – здании, что прямо позади меня.$b$bДарнелл сходит с тобой. Он знает дорогу.','Принесите из Мрачного склепа, что в Похоронном Звоне, густой бальзамировочный состав и нить для сшивания трупов.','То что надо. Ты – находка для Отрекшихся, $n.$b$bГоворят, что в прошлой жизни ты $gбыл:была; неплохим $cом. Наверное, надо дать тебе задание поинтересней.','И то, и другое можно найти в Мрачном склепе. Кажется, я оставил их на своем рабочем столе.','Вернитесь к гробовщику Мордо на кладбище Похоронного Звона.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мрачный склеп',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я рад видеть, что ты на ногах, $n. Неплохо выглядишь, особенно с учетом того, что ты так долго $gбыл мертв:была мертва;!$b$bНе всем так повезло. Если ты не против, я бы хотел попросить тебя сбегать за моим бальзамировочным составом и нитью для сшивания трупов, чтобы я мог подштопать эти тела. И то, и другое можно найти в Мрачном склепе – здании, что прямо позади меня.$b$bДарнелл сходит с тобой. Он знает дорогу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите из Мрачного склепа, что в Похоронном Звоне, густой бальзамировочный состав и нить для сшивания трупов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','То что надо. Ты – находка для Отрекшихся, $n.$b$bГоворят, что в прошлой жизни ты $gбыл:была; неплохим $cом. Наверное, надо дать тебе задание поинтересней.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','И то, и другое можно найти в Мрачном склепе. Кажется, я оставил их на своем рабочем столе.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к гробовщику Мордо на кладбище Похоронного Звона.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (28609,'Молотилка','Мы трое уже несколько недель спорим о том, чье оружие лучше.$B$BИ я никому не позволю утверждать, что какое-то оружие лучше моих булав. Ни топоры Килрама, ни мечи Сирила не могут сравниться с моими творениями.$B$BМне надоело спорить. Пришло время на деле доказать свою правоту! Если не сложно, $gдорогой:дорогая;, выйди на улицу и передай Дизу Дятло, что мне нужен самый большой валун, какой он сможет найти!','Поговорите с Дизом Дятло.','Лилит хочет, чтобы в обсерваторию принесли валун? Твердые материалы – это как раз моя специальность. Обычно я не работаю с частными клиентами, но от заказов не отказываюсь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Молотилка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы трое уже несколько недель спорим о том, чье оружие лучше.$B$BИ я никому не позволю утверждать, что какое-то оружие лучше моих булав. Ни топоры Килрама, ни мечи Сирила не могут сравниться с моими творениями.$B$BМне надоело спорить. Пришло время на деле доказать свою правоту! Если не сложно, $gдорогой:дорогая;, выйди на улицу и передай Дизу Дятло, что мне нужен самый большой валун, какой он сможет найти!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Дизом Дятло.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Лилит хочет, чтобы в обсерваторию принесли валун? Твердые материалы – это как раз моя специальность. Обычно я не работаю с частными клиентами, но от заказов не отказываюсь.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (28610,'Беда с этими обломками','Если хочешь затащить туда валун, воспользуйся моим патентованным валуном-в-коробке! Я бы продал тебе его, но у меня закончились материалы.$B$BТам, на горе к югу от города, водятся элементали земли. Они – хороший источник обломков. Принеси мне немного обломков – я заплачу тебе за них и дам в придачу валун-в-коробке!','Соберите 6 первосортных обломков, убивая ледяных грохотунов.','Неплохо! Вот, держи заработанное...','Обломки у тебя?','Поговорите с Дизом Дятло в Круговзоре, в Зимних Ключах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Беда с этими обломками',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если хочешь затащить туда валун, воспользуйся моим патентованным валуном-в-коробке! Я бы продал тебе его, но у меня закончились материалы.$B$BТам, на горе к югу от города, водятся элементали земли. Они – хороший источник обломков. Принеси мне немного обломков – я заплачу тебе за них и дам в придачу валун-в-коробке!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 6 первосортных обломков, убивая ледяных грохотунов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Неплохо! Вот, держи заработанное...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Обломки у тебя?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Дизом Дятло в Круговзоре, в Зимних Ключах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28611,'Ритуал осквернителей','Мое зрение уже стало яснее, $n.$B$BНе зря мы опасались этих злодеев-неферсетов. Я чувствую, что именно они стоят за теми силами, которые отравили реку.$B$BТебе снова придется отправиться под воду. Отыщи пещеру Глубомрака – там ты встретишь неферсетов, проводящих ритуал осквернения.$B$BНе дай им завершить его – тогда река наконец-то очистится.','Прервите ритуал неферсетов в пещере Глубомрака.','Воды реки очистились почти полностью. Совсем скоро к нам вернутся пророческие видения.','Вернитесь к верховному жрецу Амету на запруду Вир\'Наал в Ульдуме.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ритуал осквернителей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мое зрение уже стало яснее, $n.$B$BНе зря мы опасались этих злодеев-неферсетов. Я чувствую, что именно они стоят за теми силами, которые отравили реку.$B$BТебе снова придется отправиться под воду. Отыщи пещеру Глубомрака – там ты встретишь неферсетов, проводящих ритуал осквернения.$B$BНе дай им завершить его – тогда река наконец-то очистится.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Прервите ритуал неферсетов в пещере Глубомрака.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Воды реки очистились почти полностью. Совсем скоро к нам вернутся пророческие видения.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному жрецу Амету на запруду Вир\'Наал в Ульдуме.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28612,'Харрисон Джонс и храм Ульдума','После всего, что с нами стряслось, картинка наконец складывается воедино!$B$BДо саркофага рукой подать... Я вычислил коды, чтобы его обнаружить... Шнотц думает, мы уже покойники.$B$BА знаешь, может статься, что у нас в конце концов все получится!','Доберитесь до саркофага Предвестья.','На ваше счастье, у старины-дворфа остались еще тузы в рукаве!$B$BХе-хе! ...видали бы вы сейчас свои физиономии!','Обратитесь к Бранну Бронзобороду возле храма Ульдума.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Харрисон Джонс и храм Ульдума',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','После всего, что с нами стряслось, картинка наконец складывается воедино!$B$BДо саркофага рукой подать... Я вычислил коды, чтобы его обнаружить... Шнотц думает, мы уже покойники.$B$BА знаешь, может статься, что у нас в конце концов все получится!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доберитесь до саркофага Предвестья.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','На ваше счастье, у старины-дворфа остались еще тузы в рукаве!$B$BХе-хе! ...видали бы вы сейчас свои физиономии!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Обратитесь к Бранну Бронзобороду возле храма Ульдума.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (28613,'Увидимся по ту сторону!','Что ж, $n, руки у нас теперь вроде как развязаны, но времени в обрез.$B$BЗа мной!','Обратитесь к Харрисону Джонсу, его можно найти на вершине Возвышения Творца в Ульдуме.','Пока все в порядке…') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Увидимся по ту сторону!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что ж, $n, руки у нас теперь вроде как развязаны, но времени в обрез.$B$BЗа мной!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обратитесь к Харрисону Джонсу, его можно найти на вершине Возвышения Творца в Ульдуме.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Пока все в порядке…',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (28614,'Берсерк','Племя Зимней Спячки лишилось верховного вождя, но осталось таким же яростным – только теперь его возглавляет их самый могучий воин, Гролнар Берсерк.$B$BОн живет в пещере, над деревней Зимней Спячки. Огненной воды, которую он выпивает, хватило бы на то, чтобы убить десяток обычных фурболгов!$B$BОн превратился в огромное чудовище, и наши воины не смеют бросить ему вызов... А ты сможешь победить его, |3-6($c)?','Убейте Гролнара Берсерка.','Своими действиями тебе удалось доказать свою доблесть – и мне, и всем остальным древобрюхам!$B$BОстается надеяться на то, что племя Зимней Спячки окончательно разгромлено...','Поговорите с Бурндлом в Зимних Ключах, у деревни Зимней Спячки.','Напившись отравленной огненной воды, он повелевает всеми фурболгами.','Гролнар') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Берсерк',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Племя Зимней Спячки лишилось верховного вождя, но осталось таким же яростным – только теперь его возглавляет их самый могучий воин, Гролнар Берсерк.$B$BОн живет в пещере, над деревней Зимней Спячки. Огненной воды, которую он выпивает, хватило бы на то, чтобы убить десяток обычных фурболгов!$B$BОн превратился в огромное чудовище, и наши воины не смеют бросить ему вызов... А ты сможешь победить его, |3-6($c)?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Гролнара Берсерка.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Своими действиями тебе удалось доказать свою доблесть – и мне, и всем остальным древобрюхам!$B$BОстается надеяться на то, что племя Зимней Спячки окончательно разгромлено...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Бурндлом в Зимних Ключах, у деревни Зимней Спячки.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Напившись отравленной огненной воды, он повелевает всеми фурболгами.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Гролнар',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (28615,'Гнев Земли','Несмотря на порчу и безумие, фурболги Зимней Спячки все еще могут шаманить. И мне больно видеть, как они пускают силу стихий на причинение вреда моему племени и всем остальным.$B$BНо мы обратим против них их же тотемы! Возьми мой тотем и отправляйся в деревню Зимней Спячки. Поставь его напротив тотемов Зимней Спячки, при этом к ним не приближайся, – тогда на всех, кто стоит рядом с ними, обрушится вся ярость земли!$B$BПовторяю: не подходи к этим тотемам!','С помощью заряженного тотема Танрира уничтожьте 4 тотема земли Зимней Спячки.','Поговорите с Танриром в Зимних Ключах, у деревни Зимней Спячки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гнев Земли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Несмотря на порчу и безумие, фурболги Зимней Спячки все еще могут шаманить. И мне больно видеть, как они пускают силу стихий на причинение вреда моему племени и всем остальным.$B$BНо мы обратим против них их же тотемы! Возьми мой тотем и отправляйся в деревню Зимней Спячки. Поставь его напротив тотемов Зимней Спячки, при этом к ним не приближайся, – тогда на всех, кто стоит рядом с ними, обрушится вся ярость земли!$B$BПовторяю: не подходи к этим тотемам!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','С помощью заряженного тотема Танрира уничтожьте 4 тотема земли Зимней Спячки.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Танриром в Зимних Ключах, у деревни Зимней Спячки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`) VALUES (28616,'Конец клану Грозовой Вершины','Прежде чем мы продолжим, давай почтим минутой молчания память нашего павшего собрата Оркуса. Без него мы бы ни за что не смогли выстоять против натиска Грозовой Вершины. Это в твою честь, брат!$b$b<Кромуш становится на одно колено.>$b$bНо не думай, что я забыл о твоем участии, $n! Именно поэтому тебе и выпала честь взорвать гоблинскую ядерную бомбу.$b$bТы $gготов:готова;? За Орду!','Станьте свидетелем гибели клана Грозовой Вершины.','Станьте свидетелем гибели клана Грозовой Вершины.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Конец клану Грозовой Вершины',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прежде чем мы продолжим, давай почтим минутой молчания память нашего павшего собрата Оркуса. Без него мы бы ни за что не смогли выстоять против натиска Грозовой Вершины. Это в твою честь, брат!$b$b<Кромуш становится на одно колено.>$b$bНо не думай, что я забыл о твоем участии, $n! Именно поэтому тебе и выпала честь взорвать гоблинскую ядерную бомбу.$b$bТы $gготов:готова;? За Орду!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Станьте свидетелем гибели клана Грозовой Вершины.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Станьте свидетелем гибели клана Грозовой Вершины.',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28617,'Цветочная сила','Выдержите 1 внушительную волну наступления зомби.','Думаю, это только начало, парень! Они наступают!','Поговорите с ботаником Брейзи в усадьбе Брейзи, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Цветочная сила',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выдержите 1 внушительную волну наступления зомби.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Думаю, это только начало, парень! Они наступают!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с ботаником Брейзи в усадьбе Брейзи, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (28618,'Доставка валунов','Вот, держи! Один валун-в-коробке, как и было обещано.$B$BТебя ведь Лилит за ним послала? Она – мой единственный покупатель!','Доставьте валун-в-коробке Лилит Гибкой в Круговзор.','А, это снова ты. Ну, где тот валун?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Доставка валунов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот, держи! Один валун-в-коробке, как и было обещано.$B$BТебя ведь Лилит за ним послала? Она – мой единственный покупатель!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте валун-в-коробке Лилит Гибкой в Круговзор.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','А, это снова ты. Ну, где тот валун?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (28619,'Наконец-то по приказу вождя прибыло подкрепление. У Темной Госпожи есть на тебя планы, так же, как и на нас.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Наконец-то по приказу вождя прибыло подкрепление. У Темной Госпожи есть на тебя планы, так же, как и на нас.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (28620,'Восточная башня','Ну что, этот придурок наконец-то прислал помощь? С этими двумя орками плохо дело. Они страдают тем, что я называю "Дарнхольдским синдромом". Они так долго пробыли в заключении, что начали испытывать привязанность к тем, кто их схватил. И вот теперь они сидят на моем диване и рыдают.$B$BНадеюсь, от тебя будет больше пользы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Восточная башня',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну что, этот придурок наконец-то прислал помощь? С этими двумя орками плохо дело. Они страдают тем, что я называю "Дарнхольдским синдромом". Они так долго пробыли в заключении, что начали испытывать привязанность к тем, кто их схватил. И вот теперь они сидят на моем диване и рыдают.$B$BНадеюсь, от тебя будет больше пользы.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (28621,'Каждой малютке – по колыбельке','Ага!$B$BВы вместе с мальцом ковыляли себе сюда да в ус не дули, так ведь?$B$B$GЭль потягивали:За ручки держались;, небось видами любовались.$B$BВы там орденами-то обмениваться не спешите, настоящая работа вся впереди!$B$BАртефакт этот древний – не абы какая безделица, как вы думаете. Но чтобы вытрясти из него все тайны, нужно отнести его в Колыбель Древних!$B$BНу, и как нам это обтяпать?$B$BМожет, младшой идейку какую подкинет дельную, а?','Поговорите с Харрисоном Джонсом возле храма Ульдума.','Разумеется, я продумал, как унести саркофаг.$B$BМожет быть, когда-нибудь эта старая калоша научится мне доверять...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Каждой малютке – по колыбельке',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ага!$B$BВы вместе с мальцом ковыляли себе сюда да в ус не дули, так ведь?$B$B$GЭль потягивали:За ручки держались;, небось видами любовались.$B$BВы там орденами-то обмениваться не спешите, настоящая работа вся впереди!$B$BАртефакт этот древний – не абы какая безделица, как вы думаете. Но чтобы вытрясти из него все тайны, нужно отнести его в Колыбель Древних!$B$BНу, и как нам это обтяпать?$B$BМожет, младшой идейку какую подкинет дельную, а?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Харрисоном Джонсом возле храма Ульдума.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Разумеется, я продумал, как унести саркофаг.$B$BМожет быть, когда-нибудь эта старая калоша научится мне доверять...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28622,'Трое в воздухе, не считая саркофага','Вообще-то я планировал доставить саркофаг к себе в лабораторию для изучения, но похоже, у Бранна на него свои виды.$B$BЕму кажется, он знает, как воспрепятствовать планам Смертокрыла здесь, в Ульдуме.$B$BУ моего приятеля Джока транспорт наготове, он ждет только нашего сигнала.$B$BВот сигнальные ракеты – расставь их по периметру. Сообщим ему, что у нас все готово.','Расставьте сигнальные ракеты возле храма Ульдума.','Хорошая работа, подруга.$B$BПохоже, все довезли в целости и сохранности.$B$BНачинаю понимать, зачем малец тебя при себе держит.','Обратитесь к Бранну Бронзобороду возле Колыбели Древних.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Трое в воздухе, не считая саркофага',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вообще-то я планировал доставить саркофаг к себе в лабораторию для изучения, но похоже, у Бранна на него свои виды.$B$BЕму кажется, он знает, как воспрепятствовать планам Смертокрыла здесь, в Ульдуме.$B$BУ моего приятеля Джока транспорт наготове, он ждет только нашего сигнала.$B$BВот сигнальные ракеты – расставь их по периметру. Сообщим ему, что у нас все готово.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Расставьте сигнальные ракеты возле храма Ульдума.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошая работа, подруга.$B$BПохоже, все довезли в целости и сохранности.$B$BНачинаю понимать, зачем малец тебя при себе держит.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Обратитесь к Бранну Бронзобороду возле Колыбели Древних.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (28623,'Поход на запад','Наша работа здесь закончена, $n. Вопреки судьбе мы сумели остановить нашествие Неферсета на Нахом.$B$BДавай же присоединимся к нашим войскам, продвигающимся на запад, пока вся слава не досталась только им.$B$BСейчас они уже должны подходить к окраинам Неферсета.','Встретьтесь с королем Фаорисом на окраине города Неферсет в Ульдуме.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поход на запад',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наша работа здесь закончена, $n. Вопреки судьбе мы сумели остановить нашествие Неферсета на Нахом.$B$BДавай же присоединимся к нашим войскам, продвигающимся на запад, пока вся слава не досталась только им.$B$BСейчас они уже должны подходить к окраинам Неферсета.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Встретьтесь с королем Фаорисом на окраине города Неферсет в Ульдуме.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (28624,'Похвальба Килрама','Ха! Какая неуклюжесть!$B$BТебе нужна не только сила. Мои топоры не менее прочные, чем булавы Лилит, но при этом они такие острые, что валят дерево с одного удара!$B$BДа-да, с одного удара! И я докажу это – здесь, на виду у всех! Иди к Дизу и попроси его притащить сюда дерево!','Поговорите с Дизом Дятло.','Теперь им нужно дерево? Посмотрим, что там у меня есть...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Похвальба Килрама',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ха! Какая неуклюжесть!$B$BТебе нужна не только сила. Мои топоры не менее прочные, чем булавы Лилит, но при этом они такие острые, что валят дерево с одного удара!$B$BДа-да, с одного удара! И я докажу это – здесь, на виду у всех! Иди к Дизу и попроси его притащить сюда дерево!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Дизом Дятло.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь им нужно дерево? Посмотрим, что там у меня есть...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (28625,'Лесозаготовки','Целое дерево? Я торгую досками, а деревья – это что-то новенькое. Как и те валуны.$B$BМожет, окажешь мне еще одну услугу? К западу от города, над озером Кел\'Терил есть роща. Не знаю, или там нечисть завелась, или эльфы все испортили своей вонючей магией, но вот что-то в последнее время там развелось много древеней и плеточников.$B$BОни здорово мешают рубить лес – так почему бы тебе не срубить парочку из них? И принеси мне древесину этих древней.','Соберите 10 кусков свежей ледяной древесины, убивая древней с морозными листьями.','Неплохой улов. Возможно, нам стоит заняться разведением древеней...','Покажи мне древесину!','Вернитесь к Дизу Дятло в Круговзор, что в Зимних Ключах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лесозаготовки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Целое дерево? Я торгую досками, а деревья – это что-то новенькое. Как и те валуны.$B$BМожет, окажешь мне еще одну услугу? К западу от города, над озером Кел\'Терил есть роща. Не знаю, или там нечисть завелась, или эльфы все испортили своей вонючей магией, но вот что-то в последнее время там развелось много древеней и плеточников.$B$BОни здорово мешают рубить лес – так почему бы тебе не срубить парочку из них? И принеси мне древесину этих древней.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 кусков свежей ледяной древесины, убивая древней с морозными листьями.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Неплохой улов. Возможно, нам стоит заняться разведением древеней...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Покажи мне древесину!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дизу Дятло в Круговзор, что в Зимних Ключах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (28626,'Доставка деревьев','Вот, держи, суперростовое Быстродерево, на 80% состоит из натуральных ингредиентов!$B$BНет корней, нет и... мигреней. Отдай его Килраму и скажи, чтобы отошел от него ко всем чертям, когда поставит.','Доставьте суперростовое быстродерево Килраму в таверну Круговзора.','Отлично! Теперь отойди в сторону и смотри, что можно сделать настоящим оружием!','Принимайся за дело!','Поговорите с Килрамом в Круговзоре, в Зимних Ключах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Доставка деревьев',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот, держи, суперростовое Быстродерево, на 80% состоит из натуральных ингредиентов!$B$BНет корней, нет и... мигреней. Отдай его Килраму и скажи, чтобы отошел от него ко всем чертям, когда поставит.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте суперростовое быстродерево Килраму в таверну Круговзора.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! Теперь отойди в сторону и смотри, что можно сделать настоящим оружием!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Принимайся за дело!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Килрамом в Круговзоре, в Зимних Ключах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (28627,'Похвальба Сирила','Неумехи и любители, вот вы кто!$B$BЕсли ты хочешь просто зарубить своего врага, словно огр, то не важно, насколько остро и тяжело твое оружие. Я мог бы часами говорить об изяществе оружия, о скорости, о балансе... но лучше просто показать.$B$BПередай Дизу, что мне нужна ледяная глыба.','Поговорите с Дизом Дятло.','А, это снова ты! Невероятно!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Похвальба Сирила',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Неумехи и любители, вот вы кто!$B$BЕсли ты хочешь просто зарубить своего врага, словно огр, то не важно, насколько остро и тяжело твое оружие. Я мог бы часами говорить об изяществе оружия, о скорости, о балансе... но лучше просто показать.$B$BПередай Дизу, что мне нужна ледяная глыба.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Дизом Дятло.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, это снова ты! Невероятно!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (28628,'Доставка льда','Вот, держи, высококачественная, чистейшая ледяная глыба быстрой заморозки!$B$BЯ пытался продавать их как средство защиты. Ну, ты ведь знаешь этот трюк – его еще фокусники показывают? Правда, мне так и не удалось понять, как они там дышат.','Доставьте ледяную глыбу быстрой заморозки Сирилу Плетебою в Круговзоре.','Отлично. Теперь ты увидишь, что главное в оружии – это изящество.','А, ты снова здесь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Доставка льда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот, держи, высококачественная, чистейшая ледяная глыба быстрой заморозки!$B$BЯ пытался продавать их как средство защиты. Ну, ты ведь знаешь этот трюк – его еще фокусники показывают? Правда, мне так и не удалось понять, как они там дышат.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте ледяную глыбу быстрой заморозки Сирилу Плетебою в Круговзоре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично. Теперь ты увидишь, что главное в оружии – это изящество.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','А, ты снова здесь.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (28629,'Йети где-то рядом...','Добудьте 10 толстых шкур йети, убивая йети с холмов Ледополоха.','Мне так много нужно всего собрать, чтобы начать! Пожалуйста, принеси мне эти меха как можно скорее!','Вернитесь к Уми Румпельшникер в Круговзор, что в Зимних Ключах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Йети где-то рядом...',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 10 толстых шкур йети, убивая йети с холмов Ледополоха.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мне так много нужно всего собрать, чтобы начать! Пожалуйста, принеси мне эти меха как можно скорее!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Уми Румпельшникер в Круговзор, что в Зимних Ключах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (28630,'"Эхо-3"','В последнее время в холмах Ледополоха пропало много гоблинов. И я чуть было не стала одной из них! $B$BМне в голову пришла мысль о том, что нужно бы поставить сенсор, оповещающий о приближении йети к Круговзору. Но, разумеется, сенсор почему-то не работает. Тут, в холмах полным-полно йети, а он ни разу даже не пискнул!$B$BМожет, ты его проверишь? Кто знает, вдруг еще починить можно... "Эхо-3" находится на юго-востоке, на краю холмов Ледополоха. Только не спрашивай, что стало с "Эхо-1" и "Эхо-2".','Найдите "Эхо-3".','Часть этой машины еще движется, но при ближайшем рассмотрении выясняется, что устройство сильно повреждено. Металлический корпус покрыт вмятинами и трещинами, а на снегу вокруг видны чьи-то огромные следы.$B$BБолее того, похоже, что кто-то подбирается к машине прямо сейчас...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','"Эхо-3"',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В последнее время в холмах Ледополоха пропало много гоблинов. И я чуть было не стала одной из них! $B$BМне в голову пришла мысль о том, что нужно бы поставить сенсор, оповещающий о приближении йети к Круговзору. Но, разумеется, сенсор почему-то не работает. Тут, в холмах полным-полно йети, а он ни разу даже не пискнул!$B$BМожет, ты его проверишь? Кто знает, вдруг еще починить можно... "Эхо-3" находится на юго-востоке, на краю холмов Ледополоха. Только не спрашивай, что стало с "Эхо-1" и "Эхо-2".',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите "Эхо-3".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Часть этой машины еще движется, но при ближайшем рассмотрении выясняется, что устройство сильно повреждено. Металлический корпус покрыт вмятинами и трещинами, а на снегу вокруг видны чьи-то огромные следы.$B$BБолее того, похоже, что кто-то подбирается к машине прямо сейчас...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (28631,'Идеальные рога','Какой же йети без рогов!$B$BЯ уже целую вечность подыскиваю идеальную пару рогов для своего йети... и все без толку! Но вчера довелось увидеть невероятно крупного йети – самого большого из тех, что живут в Зимних Ключах.$B$BПочему-то захотелось назвать его Ледобумом. Его рога – это именно то, что мне нужно! Он бродит где-то в пещере, а вход в нее на восточной гряде холмов Ледополоха.$B$BПринеси мне его рога... Но обязательно по дороге зайди к "Эхо-3"!','Добудьте безупречные рога Ледобума.','Они идеальные? Мне нужны только идеальные!','Поговорите с Уми Румпельшникер в Зимних Ключах, в Круговзоре.','Ты только посмотри на эти прекрасные рога!','Ледобум') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Идеальные рога',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Какой же йети без рогов!$B$BЯ уже целую вечность подыскиваю идеальную пару рогов для своего йети... и все без толку! Но вчера довелось увидеть невероятно крупного йети – самого большого из тех, что живут в Зимних Ключах.$B$BПочему-то захотелось назвать его Ледобумом. Его рога – это именно то, что мне нужно! Он бродит где-то в пещере, а вход в нее на восточной гряде холмов Ледополоха.$B$BПринеси мне его рога... Но обязательно по дороге зайди к "Эхо-3"!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте безупречные рога Ледобума.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Они идеальные? Мне нужны только идеальные!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Уми Румпельшникер в Зимних Ключах, в Круговзоре.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Ты только посмотри на эти прекрасные рога!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Ледобум',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (28632,'Чистый ледниковый лед','Лед? Ох, ты ж... То есть да, конечно. У меня для тебя есть две новости: хорошая и плохая.$B$BХорошая заключается в том, что отличный чистый лед есть в пещере на холмах Ледополоха, к востоку от Круговзора. А плохая – в этой пещере полно злобных йети.$B$BНо если ты справишься с йети, то добыть лед плевое дело! Просто выбери кусок побольше и расколи его своим оружием. Принеси лед, а все остальное я сделаю.','Соберите 7 кусков чистого ледникового льда в пещере на холмах Ледополоха.','Неплохо! Будем надеяться, что в следующий раз им не понадобится лава, верно?','А, это снова ты. Ну, как тебе йети?','Вернитесь к Дизу Дятло в Круговзор, что в Зимних Ключах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чистый ледниковый лед',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Лед? Ох, ты ж... То есть да, конечно. У меня для тебя есть две новости: хорошая и плохая.$B$BХорошая заключается в том, что отличный чистый лед есть в пещере на холмах Ледополоха, к востоку от Круговзора. А плохая – в этой пещере полно злобных йети.$B$BНо если ты справишься с йети, то добыть лед плевое дело! Просто выбери кусок побольше и расколи его своим оружием. Принеси лед, а все остальное я сделаю.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 7 кусков чистого ледникового льда в пещере на холмах Ледополоха.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Неплохо! Будем надеяться, что в следующий раз им не понадобится лава, верно?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','А, это снова ты. Ну, как тебе йети?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дизу Дятло в Круговзор, что в Зимних Ключах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (28633,'Саркофаг Предвестья','Не знаю, чего нам следует ожидать, так что глядите в оба, ладно?$B$BС помощью этих кодов мы выясним истинное предназначение саркофага и узнаем способ раз и навсегда отвадить Смертокрыла от Ульдума!$B$BА ну назад!','Передайте Бранну Бронзобороду содержимое саркофага Предвестья.','Ну конечно! Я так и думал, что мы найдем что-то в этом роде.$B$BПравда, об органических преобразованиях я и не подозревал, признаю.$B$BЭта древняя реликвия – нечто такое, что мне и во сне не снилось...','Так, что тут у нас...$B$BНичего себе, ты только глянь на это!','Поговорите с Бранном Бронзобородом в Колыбели Древних.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Саркофаг Предвестья',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не знаю, чего нам следует ожидать, так что глядите в оба, ладно?$B$BС помощью этих кодов мы выясним истинное предназначение саркофага и узнаем способ раз и навсегда отвадить Смертокрыла от Ульдума!$B$BА ну назад!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Передайте Бранну Бронзобороду содержимое саркофага Предвестья.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну конечно! Я так и думал, что мы найдем что-то в этом роде.$B$BПравда, об органических преобразованиях я и не подозревал, признаю.$B$BЭта древняя реликвия – нечто такое, что мне и во сне не снилось...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Так, что тут у нас...$B$BНичего себе, ты только глянь на это!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Бранном Бронзобородом в Колыбели Древних.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28634,'Истребление','Совухи... Бездушные монстры в перьях из самых темных глубин Круговерти Пустоты, которые преследуют тех, кто послабее.$b$b<Нильс указывает на леса, окружающие Восточную башню.>Они окружают нас со всех сторон и планируют нападение. Я чувствую это. Ты $gдолжен:должна; остановить их прежде, чем они смогут организоваться.$b$bОтправляйся в лес и убей всех совухов, каких увидишь. Ни один из них не должен выжить!','Убейте 12 озлобленных совухов.','Мой зуд прекратился – но это до поры до времени. Они вернутся.$B$BО, да, они вернутся…','Вернитесь к Нильсу Гнилопчелу в Восточную башню, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Истребление',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Совухи... Бездушные монстры в перьях из самых темных глубин Круговерти Пустоты, которые преследуют тех, кто послабее.$b$b<Нильс указывает на леса, окружающие Восточную башню.>Они окружают нас со всех сторон и планируют нападение. Я чувствую это. Ты $gдолжен:должна; остановить их прежде, чем они смогут организоваться.$b$bОтправляйся в лес и убей всех совухов, каких увидишь. Ни один из них не должен выжить!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 озлобленных совухов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мой зуд прекратился – но это до поры до времени. Они вернутся.$B$BО, да, они вернутся…',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Нильсу Гнилопчелу в Восточную башню, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (28635,'Призраки Хилсбрада','Битва за Дун Гарок была самой кровавой за всю историю Хилсбрада. Дворфы сражались до последнего, хотя противник и превышал их численностью в десять раз. Все они погибли, защищая вот эту самую землю.$b$bА теперь я слышу жалобы на то, что в этих местах появились призраки. Все боятся даже просто пройти мимо! К сожалению, мне нужно подготовить Дун Гарок к будущему заселению.$b$bНе можешь ли оказать мне услугу и посмотреть, что там творится в Дун Гароке? Это к юго-востоку отсюда.','Узнайте, есть ли в Дун Гароке призраки.','Узнайте, есть ли в Дун Гароке призраки.','Поговорите с капитаном Железным Холмом в Дун Гароке, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Призраки Хилсбрада',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Битва за Дун Гарок была самой кровавой за всю историю Хилсбрада. Дворфы сражались до последнего, хотя противник и превышал их численностью в десять раз. Все они погибли, защищая вот эту самую землю.$b$bА теперь я слышу жалобы на то, что в этих местах появились призраки. Все боятся даже просто пройти мимо! К сожалению, мне нужно подготовить Дун Гарок к будущему заселению.$b$bНе можешь ли оказать мне услугу и посмотреть, что там творится в Дун Гароке? Это к юго-востоку отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Узнайте, есть ли в Дун Гароке призраки.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Узнайте, есть ли в Дун Гароке призраки.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с капитаном Железным Холмом в Дун Гароке, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28636,'Тишина дворфов','Теперь в этой крепости витают духи моих погибших солдат, $n. Их души не могут покинуть это место. Даже после смерти они продолжают защищать его. Все это очень печально.$b$bИзбавь их от мучений, и, может быть, ты прославишь свой народ.','Убейте 10 духов Дун Гарока.','Даже после смерти они дерутся за свою землю. Как и Отрекшиеся. Я сообщу командованию, что Дун Гарок не пригоден для жизни. Оставим им то, чем они так дорожат.','Вернитесь к капитану Джекиллу в Восточную башню, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тишина дворфов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь в этой крепости витают духи моих погибших солдат, $n. Их души не могут покинуть это место. Даже после смерти они продолжают защищать его. Все это очень печально.$b$bИзбавь их от мучений, и, может быть, ты прославишь свой народ.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 духов Дун Гарока.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Даже после смерти они дерутся за свою землю. Как и Отрекшиеся. Я сообщу командованию, что Дун Гарок не пригоден для жизни. Оставим им то, чем они так дорожат.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Джекиллу в Восточную башню, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (28637,'Любовь к медвежатине','Тебе когда-нибудь доводилось есть медвежатину? В Гилнеасе я так и не смог ее попробовать – а вот у местных медведей мясо просто восхитительное.$B$BПогода здесь холодная, так что у медведей-щербозубов, которые живут к югу отсюда, мясо мраморное, с прожилками жира. Я и сам охотился на них и, честно сказать, это очень весело! Однако я предпочитаю их есть!$B$BСоветую тебе поохотиться на них. Постарайся убивать только белых щербозубов. Всех убитых тобой медведей капитан принесет в лагерь.','Убейте 15 медведей-щербозубов.','Вернитесь к Фрэнсису Моркотту в коптильню Скороцапа, что в Зимних Ключах.','Мм-м... медвежатина...','Фрэнсис Моркотт') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Любовь к медвежатине',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе когда-нибудь доводилось есть медвежатину? В Гилнеасе я так и не смог ее попробовать – а вот у местных медведей мясо просто восхитительное.$B$BПогода здесь холодная, так что у медведей-щербозубов, которые живут к югу отсюда, мясо мраморное, с прожилками жира. Я и сам охотился на них и, честно сказать, это очень весело! Однако я предпочитаю их есть!$B$BСоветую тебе поохотиться на них. Постарайся убивать только белых щербозубов. Всех убитых тобой медведей капитан принесет в лагерь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 15 медведей-щербозубов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фрэнсису Моркотту в коптильню Скороцапа, что в Зимних Ключах.',`completedtext_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Мм-м... медвежатина...',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Фрэнсис Моркотт',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (28638,'Сочные совы','Я всю жизнь ем сов. Совы – хорошая еда, и мой друг Джез со мной согласен. Я первый присоветовал ему продавать сов!$B$BВот этот вот красавчик-ворген говорит, что медведи вкуснее, но ты его не слушай. Иди охотиться на сов. На юге они кишмя кишат. Пока что бей только серых, а когда завалишь пару-другую, пожужжи мне на этой говорильной штуке, которую тебе дал Джез.','Убейте 15 сов Зимних Ключей.','От этой говорильной штуки у меня ум за разум заходит.','Джеб Гутри') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сочные совы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я всю жизнь ем сов. Совы – хорошая еда, и мой друг Джез со мной согласен. Я первый присоветовал ему продавать сов!$B$BВот этот вот красавчик-ворген говорит, что медведи вкуснее, но ты его не слушай. Иди охотиться на сов. На юге они кишмя кишат. Пока что бей только серых, а когда завалишь пару-другую, пожужжи мне на этой говорильной штуке, которую тебе дал Джез.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 15 сов Зимних Ключей.',`objectives_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','От этой говорильной штуки у меня ум за разум заходит.',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Джеб Гутри',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (28639,'Урсиус','Говорят, ты – это то, что ты ешь. Я в этом не уверен, но если это правда... Лично я предпочитаю мясо самого сильного зверя, которого мне удается найти.$B$BСамый большой медведь в Зимних Ключах – это Урсиус. Когда его стая щербозубов убивает химеру или совомедведя, он ест первым. Он живет в самой уютной пещере и обладает... большим влиянием на самок щербозубов.$B$BКороче говоря, это мой медведь.$B$BЯ хочу его съесть.$B$BЕго пещера находится рядом с территорией могучих щербозубов. Удачи!','Убейте Урсиуса.','Урсиус... невкусный. По вкусу похоже на смесь сосновых шишек с простоквашей, только... только он более маслянистый.$B$BА это точно Урсиус? Огромный медведь? Который жил в пещере?$B$BКакой ужас! Такое ощущение, что кто-то вымачивал это мясо в моче.$B$BИ никаких сил во мне не прибавляется.$B$BТьфу. Гадость. Хочешь попробовать?','Вернитесь к Фрэнсису Моркотту в коптильню Скороцапа, что в Зимних Ключах.','Урсиус должен стать моим.','Фрэнсис Моркотт') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Урсиус',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Говорят, ты – это то, что ты ешь. Я в этом не уверен, но если это правда... Лично я предпочитаю мясо самого сильного зверя, которого мне удается найти.$B$BСамый большой медведь в Зимних Ключах – это Урсиус. Когда его стая щербозубов убивает химеру или совомедведя, он ест первым. Он живет в самой уютной пещере и обладает... большим влиянием на самок щербозубов.$B$BКороче говоря, это мой медведь.$B$BЯ хочу его съесть.$B$BЕго пещера находится рядом с территорией могучих щербозубов. Удачи!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Урсиуса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Урсиус... невкусный. По вкусу похоже на смесь сосновых шишек с простоквашей, только... только он более маслянистый.$B$BА это точно Урсиус? Огромный медведь? Который жил в пещере?$B$BКакой ужас! Такое ощущение, что кто-то вымачивал это мясо в моче.$B$BИ никаких сил во мне не прибавляется.$B$BТьфу. Гадость. Хочешь попробовать?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фрэнсису Моркотту в коптильню Скороцапа, что в Зимних Ключах.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Урсиус должен стать моим.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Фрэнсис Моркотт',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (28640,'Свежие ледопарды','Убейте 15 ледопардов или ледопардов-разведчиков.','Отлично! Только не останавливайся! Нас ждет крупная добыча!','Ты охотишься, я копчу мясо! Это называется "разделение труда"!','Джез Скороцап') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Свежие ледопарды',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 15 ледопардов или ледопардов-разведчиков.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! Только не останавливайся! Нас ждет крупная добыча!',`offerrewardtext_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Ты охотишься, я копчу мясо! Это называется "разделение труда"!',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Джез Скороцап',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (28641,'Украшение стола','Ну, малыш, на этот раз тебе придется отправиться еще дальше!$B$BДа, тебе удалось добыть отличную дичь, но там на западе живут кошечки побольше. У дозорных и охотниц гораздо больше мяса, и из него получаются УДИВИТЕЛЬНЫЕ котлеты. Они расходятся как горячие пирожки!$B$BКогда разберешься с ними, звякни мне. Тогда мы подумаем и о главном блюде.','Убейте 15 ледопардов-охотниц или дозорных прайда ледопардов.','Охота – это весело!','Джез Скороцап','Остался еще один!','Джез Скороцап') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Украшение стола',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну, малыш, на этот раз тебе придется отправиться еще дальше!$B$BДа, тебе удалось добыть отличную дичь, но там на западе живут кошечки побольше. У дозорных и охотниц гораздо больше мяса, и из него получаются УДИВИТЕЛЬНЫЕ котлеты. Они расходятся как горячие пирожки!$B$BКогда разберешься с ними, звякни мне. Тогда мы подумаем и о главном блюде.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 15 ледопардов-охотниц или дозорных прайда ледопардов.',`objectives_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Охота – это весело!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Джез Скороцап',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Остался еще один!',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Джез Скороцап',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (28642,'Ши-Ротам','На севере Зимних Ключей, в районе, который называют Уступ Ледопардов, обитают огромные кошки. Их предводительница известна под именем Ши-Ротам. Если тебе удастся сразить матриарха ледопардов, ты завоюешь уважение в глазах своих сородичей.$b$bОтправляйся обратно в глушь. Придя на место, добудь священного мяса ледопардов. Найди камень Ши-Ротам и помести мясо на него. Мясо растерзанных подданных заставит их предводительницу Ши-Ротам явиться в гневе.$b$bБудь $gготов:готова; встретиться с ней лицом к лицу и сразить ее.','Убейте Ши-Ротам для Шторма Призрачное Копыто.','[Deprecated] Return to Storm Shadowhoof at Everlook in Winterspring.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ши-Ротам',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На севере Зимних Ключей, в районе, который называют Уступ Ледопардов, обитают огромные кошки. Их предводительница известна под именем Ши-Ротам. Если тебе удастся сразить матриарха ледопардов, ты завоюешь уважение в глазах своих сородичей.$b$bОтправляйся обратно в глушь. Придя на место, добудь священного мяса ледопардов. Найди камень Ши-Ротам и помести мясо на него. Мясо растерзанных подданных заставит их предводительницу Ши-Ротам явиться в гневе.$b$bБудь $gготов:готова; встретиться с ней лицом к лицу и сразить ее.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Ши-Ротам для Шторма Призрачное Копыто.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','[Deprecated] Return to Storm Shadowhoof at Everlook in Winterspring.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertargetname_loc8`) VALUES (28643,'Вызов Дарнхольда: Зефирий','Крепость Дарнхольд всегда была местом стычек и распрей. В течение многих лет люди пользовались ею, как тюрьмой и лагерем для орков. Потом ее захватил Синдикат. Что сейчас? Сейчас в ее стенах находятся могущественные элементали, захваченные Темной Госпожой. По ее приказу я занимаюсь управлением состязаниями "Вызов Дарнхольда". Любой, кто сможет победить всех элементалей, получит главный приз! Возьми это руководство и приступай к своему первому испытанию: Зефирий!$b$bДарнхольд располагается к северо-востоку от нас.','Убейте Зефирия.','Отправляйтесь с докладом к капитану Джекиллу в Восточную башню, что в Предгорьях Хилсбрада.','Зефирий') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вызов Дарнхольда: Зефирий',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Крепость Дарнхольд всегда была местом стычек и распрей. В течение многих лет люди пользовались ею, как тюрьмой и лагерем для орков. Потом ее захватил Синдикат. Что сейчас? Сейчас в ее стенах находятся могущественные элементали, захваченные Темной Госпожой. По ее приказу я занимаюсь управлением состязаниями "Вызов Дарнхольда". Любой, кто сможет победить всех элементалей, получит главный приз! Возьми это руководство и приступай к своему первому испытанию: Зефирий!$b$bДарнхольд располагается к северо-востоку от нас.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Зефирия.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отправляйтесь с докладом к капитану Джекиллу в Восточную башню, что в Предгорьях Хилсбрада.',`completedtext_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Зефирий',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (28644,'Вызов Дарнхольда: Теракула','В соответствии с руководством твоим следующим противником будет Теракула. Он бродит по тропе возле логова Зефирия.','Убейте Теракулу.','Отправляйтесь с докладом к капитану Джекиллу в Восточную башню, что в Предгорьях Хилсбрада.','Приспешник Теразан','Теракула') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вызов Дарнхольда: Теракула',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В соответствии с руководством твоим следующим противником будет Теракула. Он бродит по тропе возле логова Зефирия.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Теракулу.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отправляйтесь с докладом к капитану Джекиллу в Восточную башню, что в Предгорьях Хилсбрада.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Приспешник Теразан',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Теракула',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (28645,'Вызов Дарнхольда: Кровояд','В соответствии с руководством твоим следующим противником будет Кровояд. Найти этого ужасного элементаля можно на нижнем этаже крепости Дарнхольд, возле западных темниц.','Убейте Кровояда.','Отправляйтесь с докладом к капитану Джекиллу в Восточную башню, что в Предгорьях Хилсбрада.','Приспешник Нептулона','Кровояд') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вызов Дарнхольда: Кровояд',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В соответствии с руководством твоим следующим противником будет Кровояд. Найти этого ужасного элементаля можно на нижнем этаже крепости Дарнхольд, возле западных темниц.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Кровояда.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отправляйтесь с докладом к капитану Джекиллу в Восточную башню, что в Предгорьях Хилсбрада.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Приспешник Нептулона',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Кровояд',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (28646,'Вызов Дарнхольда: Инферний','В соответствии с руководством твоим следующим противником будет Инферний. Этого монстра, состоящего из кипящей лавы и бушующего огня, можно найти на нижнем этаже крепости Дарнхольд, возле восточных темниц.','Убейте Инферния.','Отправляйтесь с докладом к капитану Джекиллу в Восточную башню, что в Предгорьях Хилсбрада.','Приспешник Рагнароса','Инферний') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вызов Дарнхольда: Инферний',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В соответствии с руководством твоим следующим противником будет Инферний. Этого монстра, состоящего из кипящей лавы и бушующего огня, можно найти на нижнем этаже крепости Дарнхольд, возле восточных темниц.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Инферния.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отправляйтесь с докладом к капитану Джекиллу в Восточную башню, что в Предгорьях Хилсбрада.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Приспешник Рагнароса',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Инферний',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (28647,'Вызов Дарнхольда: Д-1000','На арене старой крепости Дарнхольд тебя ждет существо, целиком состоящее из чистой ртути. Отрекшиеся дали ему имя Д-1000. Убей Д-1000, и приз твой!','Убейте Д-1000.','Отправляйтесь с докладом к капитану Джекиллу в Восточную башню, что в Предгорьях Хилсбрада.','Синий приспешник','Д-1000') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вызов Дарнхольда: Д-1000',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На арене старой крепости Дарнхольд тебя ждет существо, целиком состоящее из чистой ртути. Отрекшиеся дали ему имя Д-1000. Убей Д-1000, и приз твой!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Д-1000.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отправляйтесь с докладом к капитану Джекиллу в Восточную башню, что в Предгорьях Хилсбрада.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Синий приспешник',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Д-1000',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (28648,'Frak\'s Wild Ride') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Frak\'s Wild Ride',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (28649,'Приятный сюрприз','Мы ворвались сюда, перевернули все вверх дном и направились к тюрьме. Но мы совершенно не ожидали увидеть там такого, $n. Похоже, Авангард не сидел без дела. Вся тюрьма забита узниками из Серебряного Рассвета. К тому времени, как мы прибыли, многие из них были уже мертвы, но некоторые еще дышали.$b$bЯ уже было собирался убить их, но потом решил, что пусть лучше эта честь достанется тебе. В частности, там остался один злющий ворген, убить его – одно удовольствие.','Командор Чумопал из Часовни Багрового Пламени приказал вам отправиться в ближайшее здание тюрьмы и уничтожить лорда Гарфорда, узника из Серебряного Рассвета.','Вернитесь к командору Чумопалу в Часовню Багрового Пламени, что в Чумных землях: Анклав Алого ордена.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приятный сюрприз',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы ворвались сюда, перевернули все вверх дном и направились к тюрьме. Но мы совершенно не ожидали увидеть там такого, $n. Похоже, Авангард не сидел без дела. Вся тюрьма забита узниками из Серебряного Рассвета. К тому времени, как мы прибыли, многие из них были уже мертвы, но некоторые еще дышали.$b$bЯ уже было собирался убить их, но потом решил, что пусть лучше эта честь достанется тебе. В частности, там остался один злющий ворген, убить его – одно удовольствие.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Командор Чумопал из Часовни Багрового Пламени приказал вам отправиться в ближайшее здание тюрьмы и уничтожить лорда Гарфорда, узника из Серебряного Рассвета.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командору Чумопалу в Часовню Багрового Пламени, что в Чумных землях: Анклав Алого ордена.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (28650,'Приятный сюрприз','Мы ворвались сюда, перевернули все вверх дном и направились к тюрьме. Но мы совершенно не ожидали увидеть там такого, $n. Похоже, Авангард не сидел без дела. Вся тюрьма забита узниками из Серебряного Рассвета. К тому времени, как мы прибыли, многие из них были уже мертвы, но некоторые еще дышали.$b$bЯ уже было собирался убить их, но потом решил, что пусть лучше эта честь достанется тебе. В частности, там остался один злющий гоблин, убить его – одно удовольствие.','Командор Чумопал из Часовни Багрового Пламени приказал вам отправиться в ближайшее здание тюрьмы и уничтожить Галли Чвазниха, узника из Серебряного Рассвета.','Вернитесь к командору Чумопалу в Часовню Багрового Пламени, что в Чумных землях: Анклав Алого ордена.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приятный сюрприз',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы ворвались сюда, перевернули все вверх дном и направились к тюрьме. Но мы совершенно не ожидали увидеть там такого, $n. Похоже, Авангард не сидел без дела. Вся тюрьма забита узниками из Серебряного Рассвета. К тому времени, как мы прибыли, многие из них были уже мертвы, но некоторые еще дышали.$b$bЯ уже было собирался убить их, но потом решил, что пусть лучше эта честь достанется тебе. В частности, там остался один злющий гоблин, убить его – одно удовольствие.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Командор Чумопал из Часовни Багрового Пламени приказал вам отправиться в ближайшее здание тюрьмы и уничтожить Галли Чвазниха, узника из Серебряного Рассвета.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командору Чумопалу в Часовню Багрового Пламени, что в Чумных землях: Анклав Алого ордена.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28651,'Новобранец Элрет','Поговорите с новобранцем Элрет в Похоронном Звоне, что в Тирисфальских лесах.','Да хранит тебя Темная Госпожа, $n.','Поговорите с новобранцем Элрет в Похоронном Звоне, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новобранец Элрет',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с новобранцем Элрет в Похоронном Звоне, что в Тирисфальских лесах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да хранит тебя Темная Госпожа, $n.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с новобранцем Элрет в Похоронном Звоне, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (28652,'Смотритель Кайс','У меня для тебя все. Но есть и другие, кому может понадобиться твоя помощь.$b$bВозможно, у смотрителя Кайса найдется задание для тебя. Поговори с ним прямо сейчас.','Поговорите со смотрителем Кайсом в Похоронном Звоне, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Смотритель Кайс',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У меня для тебя все. Но есть и другие, кому может понадобиться твоя помощь.$b$bВозможно, у смотрителя Кайса найдется задание для тебя. Поговори с ним прямо сейчас.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите со смотрителем Кайсом в Похоронном Звоне, что в Тирисфальских лесах.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (28654,'Суть дела','Эх, $gсынок:дочка;, мне бы тоже хотелось походить здесь с тобой, получше осмотреться... Тут есть на что поглазеть! Уж поверь мне на слово.$B$BЯ повидал на своем веку много чудесного и удивительного, но такого еще не видел.$B$BК сожалению, пока я не могу выбрать время для исследования Чертогов Созидания. Нужно сперва разобраться с этими дисками.$B$BКстати, ты, вроде бы, $gлюбознательный юноша:барышня любознательная;... Не хочешь посмотреть, как работают НАСТОЯЩИЕ археологи? Наверняка тебе будет интересно.','Поговорите с Бранном Бронзобородом в Чертогах Созидания.','Ты как раз вовремя, сынок.$B$BПойдем скорее! У нас куча работы!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Суть дела',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эх, $gсынок:дочка;, мне бы тоже хотелось походить здесь с тобой, получше осмотреться... Тут есть на что поглазеть! Уж поверь мне на слово.$B$BЯ повидал на своем веку много чудесного и удивительного, но такого еще не видел.$B$BК сожалению, пока я не могу выбрать время для исследования Чертогов Созидания. Нужно сперва разобраться с этими дисками.$B$BКстати, ты, вроде бы, $gлюбознательный юноша:барышня любознательная;... Не хочешь посмотреть, как работают НАСТОЯЩИЕ археологи? Наверняка тебе будет интересно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Бранном Бронзобородом в Чертогах Созидания.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты как раз вовремя, сынок.$B$BПойдем скорее! У нас куча работы!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (28655,'Гремит-гуляет громовая свадьба','Все готово, $n, можно начинать!$B$BНаверняка культ Сумеречного Молота попробует воспрепятствовать церемонии, чтобы сломить дух и уничтожить клан Громового Молота. Здесь может начаться та еще заварушка!$B$BПоэтому я решил сам провести церемонию, чтобы жених и невеста держались поближе ко мне. Как тебе идейка? Отлично!$B$BПоскольку отец Фанни мертв, а брат у нас уже шафер, она попросила тебя сопроводить ее к алтарю. Великая честь, между прочим! Скажи, когда будешь $gготов:готова;, и мы начнем.','Скажите Грунди Макгреффу, что церемонию можно начинать. Разделайтесь с негодяями из Сумеречного Молота, которые попытаются прервать церемонию!','Поговорите с Курдраном Громовым Молотом из Кирта на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гремит-гуляет громовая свадьба',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Все готово, $n, можно начинать!$B$BНаверняка культ Сумеречного Молота попробует воспрепятствовать церемонии, чтобы сломить дух и уничтожить клан Громового Молота. Здесь может начаться та еще заварушка!$B$BПоэтому я решил сам провести церемонию, чтобы жених и невеста держались поближе ко мне. Как тебе идейка? Отлично!$B$BПоскольку отец Фанни мертв, а брат у нас уже шафер, она попросила тебя сопроводить ее к алтарю. Великая честь, между прочим! Скажи, когда будешь $gготов:готова;, и мы начнем.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Скажите Грунди Макгреффу, что церемонию можно начинать. Разделайтесь с негодяями из Сумеречного Молота, которые попытаются прервать церемонию!',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Курдраном Громовым Молотом из Кирта на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (28656,'Странные жизненные силы','Когда это существо умерло, из его тела высвободилась некая энергия. Она перешла к вам, и теперь вы чувствуете прилив сил.$B$BЖители Зимних Ключей утверждают, что больше всего про местных зверей знает знахарка Мау\'ари, которая живет в Снегоноре. Возможно, ей что-то известно про эту загадочную энергию.','Поговорите со знахаркой Мау\'ари в Зимних Ключах, в Снегоноре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Странные жизненные силы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда это существо умерло, из его тела высвободилась некая энергия. Она перешла к вам, и теперь вы чувствуете прилив сил.$B$BЖители Зимних Ключей утверждают, что больше всего про местных зверей знает знахарка Мау\'ари, которая живет в Снегоноре. Возможно, ей что-то известно про эту загадочную энергию.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите со знахаркой Мау\'ари в Зимних Ключах, в Снегоноре.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (28657,'Гигантская проблема','Стоило нам захватить этот проклятый остров, как в окрестностях тут же обнаружился гигантский эттин, который стал нападать на наши патрули!$B$B$n, договорись с друзьями и подкарауль этого громилу. Нельзя допустить, чтоб такое чудище разгуливало на свободе и сеяло разрушения.$B$BБудь $gосторожен:осторожна;, мне донесли, что он вооружен огромным поленом, которое любит пускать в дело.','Избавьтесь от Проблима, гигантского эттина, бродящего по тропам Тол Барада.','Неужели ты и вправду прикончил его? Даже не верится.','Доложите командиру Заноту в крепости Барадин о выполнении задания.','Ну и зверюга.','Проблим') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гигантская проблема',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Стоило нам захватить этот проклятый остров, как в окрестностях тут же обнаружился гигантский эттин, который стал нападать на наши патрули!$B$B$n, договорись с друзьями и подкарауль этого громилу. Нельзя допустить, чтоб такое чудище разгуливало на свободе и сеяло разрушения.$B$BБудь $gосторожен:осторожна;, мне донесли, что он вооружен огромным поленом, которое любит пускать в дело.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Избавьтесь от Проблима, гигантского эттина, бродящего по тропам Тол Барада.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Неужели ты и вправду прикончил его? Даже не верится.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доложите командиру Заноту в крепости Барадин о выполнении задания.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Ну и зверюга.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Проблим',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (28658,'Припасы на болоте','В подобном месте сложно пополнить припасы, |3-6($c). Мы безуспешно пытались найти что-либо пригодное с тех пор, как попали на этот остров.$B$BК счастью, только что лазутчики доложили, что на болоте к западу от лагеря водится много кроколисков. Их шкуры, несомненно, пригодятся нашим кожевникам. Принеси столько шкур, сколько сможешь.','Вам нужно собрать 8 шкур толбарадских кроколисков. Кроколиски обитают на болоте к западу от крепости Барадин.','Доложите командиру Заноту в крепости Барадин о выполнении задания.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Припасы на болоте',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В подобном месте сложно пополнить припасы, |3-6($c). Мы безуспешно пытались найти что-либо пригодное с тех пор, как попали на этот остров.$B$BК счастью, только что лазутчики доложили, что на болоте к западу от лагеря водится много кроколисков. Их шкуры, несомненно, пригодятся нашим кожевникам. Принеси столько шкур, сколько сможешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вам нужно собрать 8 шкур толбарадских кроколисков. Кроколиски обитают на болоте к западу от крепости Барадин.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доложите командиру Заноту в крепости Барадин о выполнении задания.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (28659,'Окончательная зачистка','Мы стойко сражались, чтобы захватить этот остров, |3-6($r). Нам удалось уничтожить большую часть паршивцев из Альянса, но я все еще чую их мерзкий дух в окрестностях.$b$bПоручаю тебе провести разведку на Шлакозаводе, на Посту Стража и в Железном гарнизоне. Убей всех представителей Альянса, которых обнаружишь.$b$bКак гласит народная мудрость, хороший враг – мертвый враг.','От вас требуется убить 12 пехотинцев Альянса на Тол Бараде. Укрепления Альянса на Тол Бараде расположены на Шлакозаводе, Посту Стража и в Железном гарнизоне.','Доложите командиру Заноту в крепости Барадин о выполнении задания.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Окончательная зачистка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы стойко сражались, чтобы захватить этот остров, |3-6($r). Нам удалось уничтожить большую часть паршивцев из Альянса, но я все еще чую их мерзкий дух в окрестностях.$b$bПоручаю тебе провести разведку на Шлакозаводе, на Посту Стража и в Железном гарнизоне. Убей всех представителей Альянса, которых обнаружишь.$b$bКак гласит народная мудрость, хороший враг – мертвый враг.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','От вас требуется убить 12 пехотинцев Альянса на Тол Бараде. Укрепления Альянса на Тол Бараде расположены на Шлакозаводе, Посту Стража и в Железном гарнизоне.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доложите командиру Заноту в крепости Барадин о выполнении задания.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (28660,'Очищение Проклятых глубин','Твое присутствие воодушевляет нас, $n. Битва за Тол Барад только началась.$B$BК востоку отсюда мы обнаружили темницу, которую следует освободить от нечисти. В ней находится множество призраков, которые томятся там уже долгое время.$b$bУбей столько нечисти, сколько сможешь, и доложи мне о выполненном задании.','Вам поручено убить 9 любых призраков в Проклятых глубинах, расположенных к востоку от крепости Барадин.','Доложите рядовому Гарноту в крепости Барадин о выполнении задания.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Очищение Проклятых глубин',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Твое присутствие воодушевляет нас, $n. Битва за Тол Барад только началась.$B$BК востоку отсюда мы обнаружили темницу, которую следует освободить от нечисти. В ней находится множество призраков, которые томятся там уже долгое время.$b$bУбей столько нечисти, сколько сможешь, и доложи мне о выполненном задании.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вам поручено убить 9 любых призраков в Проклятых глубинах, расположенных к востоку от крепости Барадин.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доложите рядовому Гарноту в крепости Барадин о выполнении задания.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (28661,'Верховный маг в заточении','Мы пытались зачистить тюремный блок в Проклятых глубинах со времен высадки на Тол Бараде. Всякий раз, как мы приближаемся к этой цели, появляется верховный маг, который рушит все наши планы.$B$BСейчас же, когда остров в наших руках, стоит попробовать снова. Направляйся вниз и доставь мне его посох в доказательство выполнения задания.','Убейте верховного мага Галия в Проклятых глубинах к востоку от крепости Барадин и заберите его посох.','Тебе удалось одолеть верховного мага?','Доложите рядовому Гарноту в крепости Барадин о выполнении задания.','Недолго ему осталось владеть этим посохом.','Верховный маг Галий') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Верховный маг в заточении',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы пытались зачистить тюремный блок в Проклятых глубинах со времен высадки на Тол Бараде. Всякий раз, как мы приближаемся к этой цели, появляется верховный маг, который рушит все наши планы.$B$BСейчас же, когда остров в наших руках, стоит попробовать снова. Направляйся вниз и доставь мне его посох в доказательство выполнения задания.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте верховного мага Галия в Проклятых глубинах к востоку от крепости Барадин и заберите его посох.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось одолеть верховного мага?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доложите рядовому Гарноту в крепости Барадин о выполнении задания.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Недолго ему осталось владеть этим посохом.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Верховный маг Галий',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (28662,'Уроки прошлого','Теперь, когда мы закрепились на этом проклятом острове, нужно попытаться установить, что его привело к нынешнему состоянию. Наши воины обнаружили несколько журналов с записями, разбросанных вблизи входа в тюремный блок в Проклятых глубинах к западу отсюда.$B$BЭти журналы представляют особый интерес для наших старейшин. Как можно быстрее отыщи четыре журнала и доставь их в лагерь.$B$BБудь $gосторожен:осторожна;, $n: в той местности бродит много нежити.','Найдите 4 пыльных тюремных журнала в Проклятых глубинах к востоку от крепости Барадин.','Тебе удалось отыскать журналы? Мне доложили, что они находятся как внутри, так и снаружи тюремных камер.','Доложите рядовому Гарноту в крепости Барадин о выполнении задания.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уроки прошлого',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда мы закрепились на этом проклятом острове, нужно попытаться установить, что его привело к нынешнему состоянию. Наши воины обнаружили несколько журналов с записями, разбросанных вблизи входа в тюремный блок в Проклятых глубинах к западу отсюда.$B$BЭти журналы представляют особый интерес для наших старейшин. Как можно быстрее отыщи четыре журнала и доставь их в лагерь.$B$BБудь $gосторожен:осторожна;, $n: в той местности бродит много нежити.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите 4 пыльных тюремных журнала в Проклятых глубинах к востоку от крепости Барадин.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось отыскать журналы? Мне доложили, что они находятся как внутри, так и снаружи тюремных камер.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доложите рядовому Гарноту в крепости Барадин о выполнении задания.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (28663,'Блок Д','Ты уже $gслышал:слышала; о блоке Д, $n? Это один из старых тюремных блоков, находящихся на острове. Дело в том, что его заселили демоны. Мы рассчитывали разместить там пленных из Альянса, захваченных на острове, но при текущем раскладе это невозможно.$B$BЯ хочу, чтобы ты $gпомог:помогла; нам очистить блок от демонов. Отрапортуй мне о выполнении приказа.','Вам поручено уничтожить 10 любых демонов, обитающих в блоке Д, который находится к северо-западу от крепости Барадин.','Доложите военному инструктору Разготу в крепости Барадин о выполнении задания.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Блок Д',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты уже $gслышал:слышала; о блоке Д, $n? Это один из старых тюремных блоков, находящихся на острове. Дело в том, что его заселили демоны. Мы рассчитывали разместить там пленных из Альянса, захваченных на острове, но при текущем раскладе это невозможно.$B$BЯ хочу, чтобы ты $gпомог:помогла; нам очистить блок от демонов. Отрапортуй мне о выполнении приказа.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вам поручено уничтожить 10 любых демонов, обитающих в блоке Д, который находится к северо-западу от крепости Барадин.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доложите военному инструктору Разготу в крепости Барадин о выполнении задания.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (28664,'Сварнос','Ты отлично $gпотрудился:потрудилась; при захвате острова, |3-6($c). Теперь, когда он в наших руках, предстоит подготовить камеры к приему заключенных. Блок Д доставляет нам особенно много проблем в плане зачистки. К сожалению, его заполонили демоны всех мастей.$B$BНам удалось совладать с большинством, но из одной камеры сбежала большая гончая недр, которая теперь бесчинствует в тюремном блоке. Я хочу, чтобы ты $gубил:убила; ее и $gдоставил:доставила; мне ее ошейник.','Расправьтесь со Сварносом в Блоке Д и заберите проклятый ошейник Сварноса. Монстр находится в Блоке Д к северо-западу от крепости Барадин.','С гончей недр покончено?','Доложите военному инструктору Разготу в крепости Барадин о выполнении задания.','Мне никогда не нравился зеленый цвет.','Сварнос') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сварнос',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты отлично $gпотрудился:потрудилась; при захвате острова, |3-6($c). Теперь, когда он в наших руках, предстоит подготовить камеры к приему заключенных. Блок Д доставляет нам особенно много проблем в плане зачистки. К сожалению, его заполонили демоны всех мастей.$B$BНам удалось совладать с большинством, но из одной камеры сбежала большая гончая недр, которая теперь бесчинствует в тюремном блоке. Я хочу, чтобы ты $gубил:убила; ее и $gдоставил:доставила; мне ее ошейник.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Расправьтесь со Сварносом в Блоке Д и заберите проклятый ошейник Сварноса. Монстр находится в Блоке Д к северо-западу от крепости Барадин.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','С гончей недр покончено?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доложите военному инструктору Разготу в крепости Барадин о выполнении задания.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Мне никогда не нравился зеленый цвет.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Сварнос',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (28665,'Проклятые кандалы','Ты уже $gбывал:бывала; в Блоке Д, $n? Всякий раз как мы очищаем этот блок, демоны быстро заселяют его снова. Мы установили, что они возрождаются за счет проклятых кандалов, разбросанных по блоку. Вот тут-то ты нам и пригодишься, $n.$B$BСобери столько кандалов, сколько сможешь, и принеси их мне. Мы их немедленно уничтожим.','Соберите 8 проклятых кандалов в Блоке Д, что находится к северо-западу от крепости Барадин.','Доложите военному инструктору Разготу в крепости Барадин о выполнении задания.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Проклятые кандалы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты уже $gбывал:бывала; в Блоке Д, $n? Всякий раз как мы очищаем этот блок, демоны быстро заселяют его снова. Мы установили, что они возрождаются за счет проклятых кандалов, разбросанных по блоку. Вот тут-то ты нам и пригодишься, $n.$B$BСобери столько кандалов, сколько сможешь, и принеси их мне. Мы их немедленно уничтожим.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 проклятых кандалов в Блоке Д, что находится к северо-западу от крепости Барадин.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доложите военному инструктору Разготу в крепости Барадин о выполнении задания.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (28667,'Приказ вождя: Пылающие степи!','Всем годным к службе членам Орды надлежит явиться к Ариоку в Лагерь Пламени Звезд.$B$BАриок, сын почтенного Эйтригга, нуждается в вашей помощи, чтобы остановить агрессию орков Черной горы, стремящихся захватить близлежащие земли.$B$BПылающие степи находятся за Черной горой к югу от Тлеющего ущелья. Лагерь Пламени Звезд расположен на дальней стороне горы.$B$BСудьба зовет!','Обратитесь к Ариоку в Лагере Пламени Звезд в Пылающих степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приказ вождя: Пылающие степи!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Всем годным к службе членам Орды надлежит явиться к Ариоку в Лагерь Пламени Звезд.$B$BАриок, сын почтенного Эйтригга, нуждается в вашей помощи, чтобы остановить агрессию орков Черной горы, стремящихся захватить близлежащие земли.$B$BПылающие степи находятся за Черной горой к югу от Тлеющего ущелья. Лагерь Пламени Звезд расположен на дальней стороне горы.$B$BСудьба зовет!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обратитесь к Ариоку в Лагере Пламени Звезд в Пылающих степях.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (28668,'Тюремный бунт','Теперь, когда остров находится в наших руках, предстоит тяжкая работа. Нам удалось обнаружить заброшенный тюремный блок к юго-западу отсюда, который нужно проверить, $n.$B$BПо донесениям разведки заключенные, томившиеся в заточении годами, захватили блок. Прими все необходимые меры по зачистке этого места. Доложи мне о результатах операции.','Вам поручено убить 10 любых узников в Яме, расположенной к юго-западу от крепости Барадин.','Доложите штаб-сержанту Лазгару в крепости Барадин о выполнении задания.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тюремный бунт',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда остров находится в наших руках, предстоит тяжкая работа. Нам удалось обнаружить заброшенный тюремный блок к юго-западу отсюда, который нужно проверить, $n.$B$BПо донесениям разведки заключенные, томившиеся в заточении годами, захватили блок. Прими все необходимые меры по зачистке этого места. Доложи мне о результатах операции.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вам поручено убить 10 любых узников в Яме, расположенной к юго-западу от крепости Барадин.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доложите штаб-сержанту Лазгару в крепости Барадин о выполнении задания.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (28669,'Тюремщик','Мы почти расправились с заключенными-бунтовщиками в Яме, однако остается еще одна нерешенная проблема. Тюремщик.$b$bСтраж Сильва – глава бунтовщиков, и узники готовы на все ради него. Стоит убрать его, и мы обуздаем всех остальных. Прикончи его и принеси мне связку ключей, которую он носит с собой. Ключи помогут нам проникнуть в глубину блока и, может быть, отыскать источник водоснабжения.','Вам нужно устранить стража Сильву в Яме и забрать его связку ключей. Яма находится к юго-западу от крепости Барадин.','Страж мертв?','Доложите штаб-сержанту Лазгару в крепости Барадин о выполнении задания.','Пора отправить тюремщика в досрочный отпуск.','Страж Сильва') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тюремщик',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы почти расправились с заключенными-бунтовщиками в Яме, однако остается еще одна нерешенная проблема. Тюремщик.$b$bСтраж Сильва – глава бунтовщиков, и узники готовы на все ради него. Стоит убрать его, и мы обуздаем всех остальных. Прикончи его и принеси мне связку ключей, которую он носит с собой. Ключи помогут нам проникнуть в глубину блока и, может быть, отыскать источник водоснабжения.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вам нужно устранить стража Сильву в Яме и забрать его связку ключей. Яма находится к юго-западу от крепости Барадин.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Страж мертв?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доложите штаб-сержанту Лазгару в крепости Барадин о выполнении задания.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Пора отправить тюремщика в досрочный отпуск.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Страж Сильва',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (28670,'Баланда','Мы испытываем нехватку провизии, $n. Только что поступило донесение, что в тюремном блоке к юго-западу отсюда хранится большое количество тюремного пайка, сохранившегося с прошлых лет. Собери столько еды, сколько сможешь, и доставь ее в лагерь.$B$BИ еще кое-что: тюремный блок кишит заключенными, так что будь $gбдителен:бдительна;.','От вас требуется достать 12 тюремных пайков в Яме, расположенной к юго-западу от крепости Барадин.','Ну, как там с пайками? Мне доложили, что они там повсюду.','Доложите штаб-сержанту Лазгару в крепости Барадин о выполнении задания.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Баланда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы испытываем нехватку провизии, $n. Только что поступило донесение, что в тюремном блоке к юго-западу отсюда хранится большое количество тюремного пайка, сохранившегося с прошлых лет. Собери столько еды, сколько сможешь, и доставь ее в лагерь.$B$BИ еще кое-что: тюремный блок кишит заключенными, так что будь $gбдителен:бдительна;.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','От вас требуется достать 12 тюремных пайков в Яме, расположенной к юго-западу от крепости Барадин.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, как там с пайками? Мне доложили, что они там повсюду.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доложите штаб-сержанту Лазгару в крепости Барадин о выполнении задания.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (28671,'Приказ вождя: Выжженные земли!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приказ вождя: Выжженные земли!',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28672,'Палач на поле боя','У меня заданий столько, что тебе хватило бы на неделю... но ты, кажется, $gлюбитель:любительница; сражений.$b$b<Элрет оценивающе смотрит на вас и кивает.>$b$bДа, ты подойдешь. Отправляйся к палачу Аррену. Выходи из Похоронного Звона на север. Найдешь его сразу за баррикадами.','Отчитайтесь палачу Аррену.','Что у нас тут? Ты $gготов:готова; к бою, юный $c?','Поговорите с палачом Арреном в Похоронном Звоне, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Палач на поле боя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У меня заданий столько, что тебе хватило бы на неделю... но ты, кажется, $gлюбитель:любительница; сражений.$b$b<Элрет оценивающе смотрит на вас и кивает.>$b$bДа, ты подойдешь. Отправляйся к палачу Аррену. Выходи из Похоронного Звона на север. Найдешь его сразу за баррикадами.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отчитайтесь палачу Аррену.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что у нас тут? Ты $gготов:готова; к бою, юный $c?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с палачом Арреном в Похоронном Звоне, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (28673,'Воззвание к героям: Выжженные земли!','Гарнизон Крепости Стражей Пустоты десятилетиями давал отпор набегам Орды. Мы не сдадимся перед лицом врага и сейчас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Воззвание к героям: Выжженные земли!',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Гарнизон Крепости Стражей Пустоты десятилетиями давал отпор набегам Орды. Мы не сдадимся перед лицом врага и сейчас.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (28674,'Деревня Звездопада','Если хочешь сделать доброе дело или просто немного подработать, то есть кое-что интересное.$B$BК северо-западу от Круговзора находится селение ночных эльфов – деревня Звездопада. Недавно там случилось нашествие каких-то жуков, и местные жители не могут справиться с этими тварями. Им нужна помощь.$B$BПара местных гоблинов уже отправилась на борьбу с жуками, но думаю, там найдется работа и для тебя. Поговори с Вундом Ночным Охотником, он сообщит тебе все подробности.','Поговорите с Вундом Ночным Охотником в деревне Звездопада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Деревня Звездопада',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если хочешь сделать доброе дело или просто немного подработать, то есть кое-что интересное.$B$BК северо-западу от Круговзора находится селение ночных эльфов – деревня Звездопада. Недавно там случилось нашествие каких-то жуков, и местные жители не могут справиться с этими тварями. Им нужна помощь.$B$BПара местных гоблинов уже отправилась на борьбу с жуками, но думаю, там найдется работа и для тебя. Поговори с Вундом Ночным Охотником, он сообщит тебе все подробности.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Вундом Ночным Охотником в деревне Звездопада.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (28675,'Воззвание к героям: Болото Печали!','Явитесь к торговому барону Сереблексу в Веслотопи на Болоте Печали.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Воззвание к героям: Болото Печали!',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Явитесь к торговому барону Сереблексу в Веслотопи на Болоте Печали.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (28676,'Экстерминаторы за работой','Эти жуткие невиданные твари захватили нашу берлогу практически за одну ночь. Они заполонили все туннели, вылупляясь из невидимых яиц.$B$BМы не даем им выбраться наружу, но нас слишком мало, чтобы дать им достойный отпор. Нам пришлось нанять гоблинов из Круговзора – они утверждали, что являются мастерами по уничтожению паразитов. Но пока им не удалось справиться с жуками.$B$BЕсли хочешь помочь им, войди в берлогу, что к западу отсюда, и поговори с Ринно Гориштором.','Поговорите с Ринно Гориштором в берлоге Бен\'Таллоу.','Новое пушечное мясо! Отлично!$B$BНадеюсь, тот эльф не утомил тебя до смерти своей болтовней. Ведь нам тут делом надо заниматься – насекомых убивать.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Экстерминаторы за работой',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти жуткие невиданные твари захватили нашу берлогу практически за одну ночь. Они заполонили все туннели, вылупляясь из невидимых яиц.$B$BМы не даем им выбраться наружу, но нас слишком мало, чтобы дать им достойный отпор. Нам пришлось нанять гоблинов из Круговзора – они утверждали, что являются мастерами по уничтожению паразитов. Но пока им не удалось справиться с жуками.$B$BЕсли хочешь помочь им, войди в берлогу, что к западу отсюда, и поговори с Ринно Гориштором.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Ринно Гориштором в берлоге Бен\'Таллоу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Новое пушечное мясо! Отлично!$B$BНадеюсь, тот эльф не утомил тебя до смерти своей болтовней. Ведь нам тут делом надо заниматься – насекомых убивать.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (28677,'Приказ вождя: Болото Печали!','Настоящим повелением всем годным к службе воинам Орды приказано явиться к торговому барону Сереблексу в Веслотопь.$B$BЛюбыми средствами убедите барона продолжить поставки оружия и боеприпасов нашей армии в необходимом объеме!$B$BДля того чтобы попасть на Болото Печали, следуйте по дороге из Пылающих степей на юго-восток, минуя Красногорье. После прибытия на место отыщите барона в его курортной резиденции.$B$BСудьба зовет!','Явитесь к торговому барону Сереблексу в Веслотопи на Болоте Печали.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приказ вождя: Болото Печали!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Настоящим повелением всем годным к службе воинам Орды приказано явиться к торговому барону Сереблексу в Веслотопь.$B$BЛюбыми средствами убедите барона продолжить поставки оружия и боеприпасов нашей армии в необходимом объеме!$B$BДля того чтобы попасть на Болото Печали, следуйте по дороге из Пылающих степей на юго-восток, минуя Красногорье. После прибытия на место отыщите барона в его курортной резиденции.$B$BСудьба зовет!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Явитесь к торговому барону Сереблексу в Веслотопи на Болоте Печали.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (28678,'Капитан П. Харрис','Мыс Потерянной Надежды уже долгое время стоит у нас как кость в горле. Половина кораблей с провиантом для Тол Барада разбивается внизу о скалы.$b$bЧто еще хуже, так это неупокоенные моряки, докучающие нам. Мы пробовали расправиться с ними, да только они приходят все снова и снова. Последняя надежда – убить капитана, которому они подчиняются. Ты найдешь его на корабле, причалившем к берегу.$b$bНадеюсь, ты не очень боишься акул?','Вас просят убить капитана П. Харриса на мысе Потерянной Надежды. Мыс расположен к северо-западу, если идти вдоль береговой линии. Ищите обломки корабля.','Доложите третьему офицеру Кронкару в Хватке Адского Крика о выполнении задания.','Убей капитана, и его подчиненные обратятся в бегство.','Капитан П. Харрис') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Капитан П. Харрис',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мыс Потерянной Надежды уже долгое время стоит у нас как кость в горле. Половина кораблей с провиантом для Тол Барада разбивается внизу о скалы.$b$bЧто еще хуже, так это неупокоенные моряки, докучающие нам. Мы пробовали расправиться с ними, да только они приходят все снова и снова. Последняя надежда – убить капитана, которому они подчиняются. Ты найдешь его на корабле, причалившем к берегу.$b$bНадеюсь, ты не очень боишься акул?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вас просят убить капитана П. Харриса на мысе Потерянной Надежды. Мыс расположен к северо-западу, если идти вдоль береговой линии. Ищите обломки корабля.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доложите третьему офицеру Кронкару в Хватке Адского Крика о выполнении задания.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Убей капитана, и его подчиненные обратятся в бегство.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Капитан П. Харрис',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (28679,'Раздробить косточки','Уже долгое время нас беспокоит нежить с мыса Потерянной Надежды. Всякий раз, как разбивается корабль, ее воинство пополняется новыми душами.$b$bТы не $gмог:могла; бы оказать нам услугу, уничтожив несколько неупокоенных врагов? Знаю, что всех их истребить невозможно, но так ты хоть немного облегчишь нашу задачу.$b$bОстерегайся солдат Альянса. Поступают донесения о том, что они устраивают засады вдоль береговой линии.','Третий офицер Кронкар поручил вам уничтожить 8 моряков-утопленников на мысе Потерянной Надежды. Мыс расположен к северо-западу от лагеря.','Доложите третьему офицеру Кронкару в Хватке Адского Крика о выполнении задания.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Раздробить косточки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Уже долгое время нас беспокоит нежить с мыса Потерянной Надежды. Всякий раз, как разбивается корабль, ее воинство пополняется новыми душами.$b$bТы не $gмог:могла; бы оказать нам услугу, уничтожив несколько неупокоенных врагов? Знаю, что всех их истребить невозможно, но так ты хоть немного облегчишь нашу задачу.$b$bОстерегайся солдат Альянса. Поступают донесения о том, что они устраивают засады вдоль береговой линии.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Третий офицер Кронкар поручил вам уничтожить 8 моряков-утопленников на мысе Потерянной Надежды. Мыс расположен к северо-западу от лагеря.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доложите третьему офицеру Кронкару в Хватке Адского Крика о выполнении задания.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (28680,'Поддержание боевого духа','Наши войска деморализованы, $n. Мы прилагаем все усилия, чтобы поддерживать в солдатах боевой дух, вот только главная составляющая успеха – ром – подходит к концу.$b$bПехотинцы с южного побережья докладывают, что в трюмах кораблей, затонувших у мыса Потерянной Надежды, хранится хороший запас рома. Не $gмог:могла; бы ты проверить, так ли это?$b$bПринеси весь ром, что сможешь найти.','Вас попросили доставить 6 бочонков южноморского рома с кораблей, затонувших у мыса Потерянной Надежды. Мыс расположен севернее на береговой линии.','Ты достал ром? Я бы и сам сходил, да только панически боюсь воды. Не говоря уж о бешеной акуле...','Доложите третьему офицеру Кронкару в Хватке Адского Крика о выполнении задания.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поддержание боевого духа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наши войска деморализованы, $n. Мы прилагаем все усилия, чтобы поддерживать в солдатах боевой дух, вот только главная составляющая успеха – ром – подходит к концу.$b$bПехотинцы с южного побережья докладывают, что в трюмах кораблей, затонувших у мыса Потерянной Надежды, хранится хороший запас рома. Не $gмог:могла; бы ты проверить, так ли это?$b$bПринеси весь ром, что сможешь найти.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вас попросили доставить 6 бочонков южноморского рома с кораблей, затонувших у мыса Потерянной Надежды. Мыс расположен севернее на береговой линии.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты достал ром? Я бы и сам сходил, да только панически боюсь воды. Не говоря уж о бешеной акуле...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доложите третьему офицеру Кронкару в Хватке Адского Крика о выполнении задания.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (28681,'Акула Амбал','Ненавижу акул. И все мои солдаты тоже. Тут-то ты нам и пригодишься, $n.$b$bПоднимись к мысу Потерянной Надежды и убей гигантскую акулу по имени Амбал. Ее не стоит недооценивать, так что лучше прихвати с собой на подмогу парочку друзей.','Вам поручено убить Амбала, гигантскую акулу, плавающую в водах у мыса Потерянной Надежды. Мыс расположен севернее, если идти вдоль береговой линии.','Не может быть! Ты действительно покончил с ней? Значит у нас сегодня акулятина на ужин!','Доложите третьему офицеру Кронкару в Хватке Адского Крика о выполнении задания.','У этой рыбины действительно огромные челюсти.','Амбал') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Акула Амбал',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ненавижу акул. И все мои солдаты тоже. Тут-то ты нам и пригодишься, $n.$b$bПоднимись к мысу Потерянной Надежды и убей гигантскую акулу по имени Амбал. Ее не стоит недооценивать, так что лучше прихвати с собой на подмогу парочку друзей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вам поручено убить Амбала, гигантскую акулу, плавающую в водах у мыса Потерянной Надежды. Мыс расположен севернее, если идти вдоль береговой линии.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Не может быть! Ты действительно покончил с ней? Значит у нас сегодня акулятина на ужин!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доложите третьему офицеру Кронкару в Хватке Адского Крика о выполнении задания.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','У этой рыбины действительно огромные челюсти.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Амбал',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (28682,'Взятие крепости','$gВидел:Видела; крепость в северной части острова, $n? Там обосновался некий Фарсон.$b$bФарсон со своими немногочисленными приспешниками докучают нам с тех пор, как мы пришли в эти места. Мы отправили в разведку небольшой отряд, который установил точное местоположение Фарсона в крепости.$b$bТы поможешь нам покончить с ним?','Вас просят убить начальника крепости Фарсона. Его крепость находится на северной стороне острова.','Доложите командиру Лармашу в Хватке Адского Крика о выполнении задания.','У него преданные подчиненные. Не нужно их недооценивать.','Начальник крепости Фарсон') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Взятие крепости',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$gВидел:Видела; крепость в северной части острова, $n? Там обосновался некий Фарсон.$b$bФарсон со своими немногочисленными приспешниками докучают нам с тех пор, как мы пришли в эти места. Мы отправили в разведку небольшой отряд, который установил точное местоположение Фарсона в крепости.$b$bТы поможешь нам покончить с ним?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вас просят убить начальника крепости Фарсона. Его крепость находится на северной стороне острова.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доложите командиру Лармашу в Хватке Адского Крика о выполнении задания.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','У него преданные подчиненные. Не нужно их недооценивать.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Начальник крепости Фарсон',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (28683,'Очищение леса','Мы неделями пытаемся зацепиться в Мрачном лесу, но он просто кишит пауками. Окажи мне услугу, перебей эту гадость, чтобы мы могли подготовиться к нападению.$b$bБудь $gбдителен:бдительна;, когда доберешься до леса, а то мне тут на неделе доложили, что поблизости орудует Альянс.','Убейте 12 скрытней Мрачного леса. Мрачный лес находится за мостом, к северу отсюда, в центральной части острова.','Доложите третьему офицеру Кронкару в Хватке Адского Крика о выполнении задания.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Очищение леса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы неделями пытаемся зацепиться в Мрачном лесу, но он просто кишит пауками. Окажи мне услугу, перебей эту гадость, чтобы мы могли подготовиться к нападению.$b$bБудь $gбдителен:бдительна;, когда доберешься до леса, а то мне тут на неделе доложили, что поблизости орудует Альянс.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 скрытней Мрачного леса. Мрачный лес находится за мостом, к северу отсюда, в центральной части острова.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доложите третьему офицеру Кронкару в Хватке Адского Крика о выполнении задания.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (28684,'Липкая работа','Непросто было найти припасы на острове, скажу я тебе.$b$bК счастью, к северу отсюда, в Мрачном лесу, нам удалось обнаружить хороший источник шелка. Плохая новость – это то, что шелк производят паучихи-праматери. Достань мне 4 паутинных железы праматерей.$b$bЭтого хватит, чтобы дошить последний комплект рубашек.','Соберите 4 липких паутинных железы праматерей Мрачного леса. Чтобы попасть в лес, находящийся в центральной части острова, пересеките мост к западу от лагеря.','Тебе удалось достать липкие паутинные железы?','Доложите третьему офицеру Кронкару в Хватке Адского Крика о выполнении задания.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Липкая работа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Непросто было найти припасы на острове, скажу я тебе.$b$bК счастью, к северу отсюда, в Мрачном лесу, нам удалось обнаружить хороший источник шелка. Плохая новость – это то, что шелк производят паучихи-праматери. Достань мне 4 паутинных железы праматерей.$b$bЭтого хватит, чтобы дошить последний комплект рубашек.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 4 липких паутинных железы праматерей Мрачного леса. Чтобы попасть в лес, находящийся в центральной части острова, пересеките мост к западу от лагеря.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось достать липкие паутинные железы?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доложите третьему офицеру Кронкару в Хватке Адского Крика о выполнении задания.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (28685,'Забрать все оружие','На этом острове сложно достать боеприпасы. Всякий раз, как на нас нападает Альянс, создается ощущение, что мы сражаемся с ними при помощи камней и палок.$B$BМне доложили, что у начальника крепости Фарсона на северной стороне острова есть винтовки, которые мы могли бы использовать. Ты не $gмог:могла; бы туда наведаться?$b$bБудь $gосторожен:осторожна;, $n, приспешники Фарсона сделают все, чтобы защитить его.','Вам поручили забрать 12 ржавых винтовок из Крепости Фарсона, расположенной в северной части полуострова Тол Барад.','Ты достал ружья?','Доложите третьему командиру Лармашу в Хватке Адского Крика о выполнении задания.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Забрать все оружие',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На этом острове сложно достать боеприпасы. Всякий раз, как на нас нападает Альянс, создается ощущение, что мы сражаемся с ними при помощи камней и палок.$B$BМне доложили, что у начальника крепости Фарсона на северной стороне острова есть винтовки, которые мы могли бы использовать. Ты не $gмог:могла; бы туда наведаться?$b$bБудь $gосторожен:осторожна;, $n, приспешники Фарсона сделают все, чтобы защитить его.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вам поручили забрать 12 ржавых винтовок из Крепости Фарсона, расположенной в северной части полуострова Тол Барад.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты достал ружья?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доложите третьему командиру Лармашу в Хватке Адского Крика о выполнении задания.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (28686,'Неприветливый город','Ты уже $gбывал:бывала; в Растберге, $n? Советую припасти нож за пазухой, если пойдешь в те края.$b$bТамошние жители вроде бы не доставляют хлопот, вот только что-то странное там творится. Мне докладывают о том, что там периодически пропадают наши солдаты. Нам это порядком поднадоело, поэтому тебе следует отправиться в этот вертеп и навести там порядок.$B$BПеребей там столько народу, сколько сможешь, и отчитайся передо мной о проделанной работе.','Командир Лармаш поручил вам расправиться с 14 жителями Растберга. Растберг расположен в правой части острова, к северу от лагеря.','Доложите командиру Лармашу в Хватке Адского Крика о выполнении задания.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Неприветливый город',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты уже $gбывал:бывала; в Растберге, $n? Советую припасти нож за пазухой, если пойдешь в те края.$b$bТамошние жители вроде бы не доставляют хлопот, вот только что-то странное там творится. Мне докладывают о том, что там периодически пропадают наши солдаты. Нам это порядком поднадоело, поэтому тебе следует отправиться в этот вертеп и навести там порядок.$B$BПеребей там столько народу, сколько сможешь, и отчитайся передо мной о проделанной работе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Командир Лармаш поручил вам расправиться с 14 жителями Растберга. Растберг расположен в правой части острова, к северу от лагеря.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доложите командиру Лармашу в Хватке Адского Крика о выполнении задания.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (28687,'Научи человека ловить рыбу... Или красть ее!','Растберг. Это место – одновременно наше проклятье и благословение, $n. Понятия не имею, где эти разбойники научились ловить рыбу, но это и не важно.$B$BОтправляйся к ним в логово и укради столько рыбы, сколько сможешь. Мы питаемся всякими отбросами с тех пор, как вновь заняли этот остров, поэтому было бы неплохо пополнить запасы провизии.$B$BБудь $gосторожен:осторожна;, мне доложили, что в деревне нас может поджидать засада.','Вам нужно украсть 22 растбергских окуня. Рыба сушится на нитях на специальных стойках у причала за деревней. Растберг расположен на северо-востоке острова, к северу от лагеря.','Получилось пробраться туда и украсть рыбешки?','Доложите командиру Лармашу в Хватке Адского Крика о выполнении задания.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Научи человека ловить рыбу... Или красть ее!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Растберг. Это место – одновременно наше проклятье и благословение, $n. Понятия не имею, где эти разбойники научились ловить рыбу, но это и не важно.$B$BОтправляйся к ним в логово и укради столько рыбы, сколько сможешь. Мы питаемся всякими отбросами с тех пор, как вновь заняли этот остров, поэтому было бы неплохо пополнить запасы провизии.$B$BБудь $gосторожен:осторожна;, мне доложили, что в деревне нас может поджидать засада.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вам нужно украсть 22 растбергских окуня. Рыба сушится на нитях на специальных стойках у причала за деревней. Растберг расположен на северо-востоке острова, к северу от лагеря.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Получилось пробраться туда и украсть рыбешки?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доложите командиру Лармашу в Хватке Адского Крика о выполнении задания.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (28688,'Наконец-то прибыло подкрепление от вождя.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Наконец-то прибыло подкрепление от вождя.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28689,'Позабытые','На этом острове погибло много солдат, $n. Наш долг – почтить их память.$b$bОтправляйся на Забытый холм, что к западу отсюда, и освободи души наших братьев по оружию, томящиеся там. Будь $gосторожен:осторожна;, по донесениям в тех местах бесчинствует нежить.','Освободите 6 истерзанных душ на Забытом холме. Душу можно высвободить, дотронувшись до могильного камня. Забытый холм расположен к западу отсюда, за Передовой Неупокоенных.','Да обретут их души вечный покой.','Доложите капитану Пругу в Хватке Адского Крика о завершении задания.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Позабытые',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На этом острове погибло много солдат, $n. Наш долг – почтить их память.$b$bОтправляйся на Забытый холм, что к западу отсюда, и освободи души наших братьев по оружию, томящиеся там. Будь $gосторожен:осторожна;, по донесениям в тех местах бесчинствует нежить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Освободите 6 истерзанных душ на Забытом холме. Душу можно высвободить, дотронувшись до могильного камня. Забытый холм расположен к западу отсюда, за Передовой Неупокоенных.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да обретут их души вечный покой.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доложите капитану Пругу в Хватке Адского Крика о завершении задания.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (28690,'Спасение останков','На Забытый холм покушаются зомби и вурдалаки c тех самых пор, как мы обосновались на этом проклятом острове. Мы многократно пытались очистить его от нежити, но безуспешно.$b$bОдин офицер посоветовал нам собирать кости вурдалаков, чтобы те еженощно не восставали из мертвых. Не подсобишь?','От вас требуется собрать 9 проклятых бедренных костей вурдалаков, населяющих Забытый холм. Это место расположено на западной стороне острова за Передовой Неупокоенных.','Собрал бедренные кости? Ты справишься с этим лучше меня.','Доложите капитану Пругу в Хватке Адского Крика о завершении задания.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спасение останков',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На Забытый холм покушаются зомби и вурдалаки c тех самых пор, как мы обосновались на этом проклятом острове. Мы многократно пытались очистить его от нежити, но безуспешно.$b$bОдин офицер посоветовал нам собирать кости вурдалаков, чтобы те еженощно не восставали из мертвых. Не подсобишь?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','От вас требуется собрать 9 проклятых бедренных костей вурдалаков, населяющих Забытый холм. Это место расположено на западной стороне острова за Передовой Неупокоенных.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Собрал бедренные кости? Ты справишься с этим лучше меня.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доложите капитану Пругу в Хватке Адского Крика о завершении задания.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (28691,'Старший лейтенант Коннор','Я впервые услышал о лейтенанте Конноре, когда был простым новобранцем в Огненной Пропасти. Никто бы не поверил, что он очутится здесь, на Тол Бараде. К сожалению, он все еще бродит по этим проклятым островам, сея смуту в наших войсках.$b$bПоложи конец его страданиям, а заодно и нашим.','Обнаружьте и убейте старшего лейтенанта Коннора на Забытом холме. Это место расположено в западной стороне острова.','Ты выжил! Ты не первый, кто пытался справиться с этим заданием, но первый, кто унес оттуда ноги.','Доложите капитану Пругу в Хватке Адского Крика о завершении задания.','Никто не хочет заканчивать тут свои дни, но жизнь порой складывается помимо нашей воли.','Старший лейтенант Коннор') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Старший лейтенант Коннор',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я впервые услышал о лейтенанте Конноре, когда был простым новобранцем в Огненной Пропасти. Никто бы не поверил, что он очутится здесь, на Тол Бараде. К сожалению, он все еще бродит по этим проклятым островам, сея смуту в наших войсках.$b$bПоложи конец его страданиям, а заодно и нашим.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обнаружьте и убейте старшего лейтенанта Коннора на Забытом холме. Это место расположено в западной стороне острова.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты выжил! Ты не первый, кто пытался справиться с этим заданием, но первый, кто унес оттуда ноги.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доложите капитану Пругу в Хватке Адского Крика о завершении задания.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Никто не хочет заканчивать тут свои дни, но жизнь порой складывается помимо нашей воли.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Старший лейтенант Коннор',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (28692,'Как работают магниты?','На остров сложно доставить полезные запчасти, $n. Мы пытались на месте починить сломанные осадные машины, но у нас закончились необходимые детали.$b$bИз второго полка доложили об искореженных осадных машинах, стоящих на заброшенном поле боя к западу отсюда. Может быть, там остались какие-то пригодные запчасти?$b$bСложно будет отыскать что-то в груде обломков, так что возьми-ка этот намагниченный сборщик металлолома и воспользуйся им.','Вам поручили собрать 7 фрагментов осадных машин. Используйте намагниченный сборщик металлолома на Передовой Неупокоенных, расположенной на западе за вторым мостом.','Ну что, помог ли тебе намагниченный сборщик металлолома?','Доложите капитану Пругу в Хватке Адского Крика о завершении задания.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Как работают магниты?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На остров сложно доставить полезные запчасти, $n. Мы пытались на месте починить сломанные осадные машины, но у нас закончились необходимые детали.$b$bИз второго полка доложили об искореженных осадных машинах, стоящих на заброшенном поле боя к западу отсюда. Может быть, там остались какие-то пригодные запчасти?$b$bСложно будет отыскать что-то в груде обломков, так что возьми-ка этот намагниченный сборщик металлолома и воспользуйся им.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вам поручили собрать 7 фрагментов осадных машин. Используйте намагниченный сборщик металлолома на Передовой Неупокоенных, расположенной на западе за вторым мостом.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, помог ли тебе намагниченный сборщик металлолома?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доложите капитану Пругу в Хватке Адского Крика о завершении задания.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28693,'Завершение работы','Всю неделю мы пытались принести пригодные запчасти с Передовой. И всякий раз, когда мы несли детали в лагерь, на нас нападали неупокоенные солдаты. Ты бы не $gсогласился:согласилась; расчистить наш путь?','От вас требуется уничтожить 5 неупокоенных солдат на Передовой Неупокоенных. Это место расположено на западной стороне острова на подступах к Забытому холму.','Давно было пора расправиться с ними.','Доложите капитану Пругу в Хватке Адского Крика о завершении задания.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Завершение работы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Всю неделю мы пытались принести пригодные запчасти с Передовой. И всякий раз, когда мы несли детали в лагерь, на нас нападали неупокоенные солдаты. Ты бы не $gсогласился:согласилась; расчистить наш путь?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','От вас требуется уничтожить 5 неупокоенных солдат на Передовой Неупокоенных. Это место расположено на западной стороне острова на подступах к Забытому холму.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Давно было пора расправиться с ними.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доложите капитану Пругу в Хватке Адского Крика о завершении задания.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (28694,'Щепки летят!','Ты уже $gбывал:бывала; на Верфи Веллсона, $n? Без особой нужды лучше держаться от нее подальше. К сожалению, именно туда тебе и придется пойти.$b$bВидишь ли, мы испытываем нехватку припасов с тех самых пор, как высадились на острове. На верфи находится много лесоматериалов, но обжившие ее призраки всякий раз мешают нам забрать их оттуда.$b$bТы не $gмог:могла; бы нам помочь?','Рядовой Сарлоск хочет, чтобы вы принесли 15 единиц лесоматериалов с Верфи Веллсона. Доски можно отнять у призраков, обитающих на верфи, или поднять с земли. Верфь находится на берегу к северо-западу отсюда.','Призраки отпугнули тебя?','Доложите рядовому Сарлоску в Хватке Адского Крика о выполнении задания.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Щепки летят!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты уже $gбывал:бывала; на Верфи Веллсона, $n? Без особой нужды лучше держаться от нее подальше. К сожалению, именно туда тебе и придется пойти.$b$bВидишь ли, мы испытываем нехватку припасов с тех самых пор, как высадились на острове. На верфи находится много лесоматериалов, но обжившие ее призраки всякий раз мешают нам забрать их оттуда.$b$bТы не $gмог:могла; бы нам помочь?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Рядовой Сарлоск хочет, чтобы вы принесли 15 единиц лесоматериалов с Верфи Веллсона. Доски можно отнять у призраков, обитающих на верфи, или поднять с земли. Верфь находится на берегу к северо-западу отсюда.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Призраки отпугнули тебя?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доложите рядовому Сарлоску в Хватке Адского Крика о выполнении задания.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (28695,'Разыскивается: начальник верфи Веллсон','Начальник верфи Веллсон докучает нам с тех самых пор, как мы попали на остров. На его верфи находится масса припасов, которые бы нам пригодились... если бы мы до них добрались.$b$bОн бдительно следит за своими подчиненными, что осложняет нашу задачу. Итак, я хочу, чтобы ты $gпокончил:покончила; с Веллсоном. Остерегайся солдат Альянса, бесчинствующих в округе, $n.','Вам предстоит прикончить начальника верфи Веллсона. Верфь расположена к северо-западу отсюда, на западном побережье острова.','Доложите рядовому Сарлоску в Хватке Адского Крика о выполнении задания.','Когда-то великий человек, а нынче падший начальник пристани Веллсон.','Начальник верфи Веллсон') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разыскивается: начальник верфи Веллсон',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Начальник верфи Веллсон докучает нам с тех самых пор, как мы попали на остров. На его верфи находится масса припасов, которые бы нам пригодились... если бы мы до них добрались.$b$bОн бдительно следит за своими подчиненными, что осложняет нашу задачу. Итак, я хочу, чтобы ты $gпокончил:покончила; с Веллсоном. Остерегайся солдат Альянса, бесчинствующих в округе, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вам предстоит прикончить начальника верфи Веллсона. Верфь расположена к северо-западу отсюда, на западном побережье острова.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доложите рядовому Сарлоску в Хватке Адского Крика о выполнении задания.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Когда-то великий человек, а нынче падший начальник пристани Веллсон.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Начальник верфи Веллсон',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (28698,'Пушечное ядро!','Ларго со своими проходимцами воруют наши боеприпасы с тех самых пор, как мы разбили тут лагерь. Это крайне раздражает.$b$bНам донесли, что Ларго складирует пушечные ядра в башнях, стоящих над водой на его Дозорном пункте. Достанешь нам немного ядер?$b$b$n, остерегайся представителей Альянса.','Соберите для рядового Сарлоска 4 груды пушечных ядер, хранящихся на Дозорном пункте Ларго. Он находится к северо-востоку от лагеря.','Доложите рядовому Сарлоску в Хватке Адского Крика о выполнении задания.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пушечное ядро!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ларго со своими проходимцами воруют наши боеприпасы с тех самых пор, как мы разбили тут лагерь. Это крайне раздражает.$b$bНам донесли, что Ларго складирует пушечные ядра в башнях, стоящих над водой на его Дозорном пункте. Достанешь нам немного ядер?$b$b$n, остерегайся представителей Альянса.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите для рядового Сарлоска 4 груды пушечных ядер, хранящихся на Дозорном пункте Ларго. Он находится к северо-востоку от лагеря.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доложите рядовому Сарлоску в Хватке Адского Крика о выполнении задания.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (28700,'Освобождение дозорной башни','Существует единственный способ захватить Дозорный пункт Ларго.$b$bВ последнее время парень окончательно спятил: стоит себе на вершине башни и ждет, когда приплывет воображаемый флот. Так что найти его не составит труда.','Рядовой Сарлоск поручил вам ликвидировать Командира Ларго на Дозорном пункте Ларго. Это место находится к северо-востоку от лагеря.','Доложите рядовому Сарлоску в Хватке Адского Крика о выполнении задания.','Попробуй с ним справиться!','Командир Ларго') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Освобождение дозорной башни',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Существует единственный способ захватить Дозорный пункт Ларго.$b$bВ последнее время парень окончательно спятил: стоит себе на вершине башни и ждет, когда приплывет воображаемый флот. Так что найти его не составит труда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Рядовой Сарлоск поручил вам ликвидировать Командира Ларго на Дозорном пункте Ларго. Это место находится к северо-востоку от лагеря.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доложите рядовому Сарлоску в Хватке Адского Крика о выполнении задания.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Попробуй с ним справиться!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Командир Ларго',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (28701,'В безопасности','К счастью, когда жуки напали на берлогу, там не было друидов. Но мы не можем его вот так просто сдать – это священное место, в нем хранятся многие древние артефакты.$B$BИ хотя я, в целом, доверяю этим гоблинам-истребителям, но... скажем так, кое-что знаю о повадках этого народа. Пожалуйста, собери в берлоге артефакты и принеси мне, пока кто-нибудь не повредил их. Урны с артефактами находятся в небольших альковах, их много по всей берлоге.','Найдите 5 реликвий Звездопада в берлоге Бен\'Таллоу.','Надеюсь, реликвии не пострадали?','Поговорите с Вундом Ночным Охотником в деревне Звездопада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В безопасности',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','К счастью, когда жуки напали на берлогу, там не было друидов. Но мы не можем его вот так просто сдать – это священное место, в нем хранятся многие древние артефакты.$B$BИ хотя я, в целом, доверяю этим гоблинам-истребителям, но... скажем так, кое-что знаю о повадках этого народа. Пожалуйста, собери в берлоге артефакты и принеси мне, пока кто-нибудь не повредил их. Урны с артефактами находятся в небольших альковах, их много по всей берлоге.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите 5 реликвий Звездопада в берлоге Бен\'Таллоу.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Надеюсь, реликвии не пострадали?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Вундом Ночным Охотником в деревне Звездопада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (28702,'Воззвание к героям: мыс Тернистой долины') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Воззвание к героям: мыс Тернистой долины',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28703,'Добро пожаловать в мой курган','Я до сих пор не знаю, откуда взялись эти насекомые. По-видимому, катаклизм потревожил какие-то гнезда глубоко под землей.$B$BНо довольно об этом. Нам нужно уничтожить этих тварей!','Убейте 10 холодных ползунов и 5 холодных землеглотов.','Отлично!$B$BЕсли захочешь поубивать еще насекомых забесплатно, то не стесняйся, заходи!','Поговорите с Ринно Гориштором в берлоге Бен\'Таллоу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Добро пожаловать в мой курган',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я до сих пор не знаю, откуда взялись эти насекомые. По-видимому, катаклизм потревожил какие-то гнезда глубоко под землей.$B$BНо довольно об этом. Нам нужно уничтожить этих тварей!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 холодных ползунов и 5 холодных землеглотов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично!$B$BЕсли захочешь поубивать еще насекомых забесплатно, то не стесняйся, заходи!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Ринно Гориштором в берлоге Бен\'Таллоу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (28704,'Приказ вождя: мыс Тернистой долины','Настоящим повелением всем годным к службе воинам орды приказано явиться к Хамми Кофельнагель, находящейся в Укрытии Кофельнагель. Она нуждается в вашей помощи в борьбе с пиратами и нагами, кишащими в джунглях.$B$BОтправляйтесь на юг в Укрытие Кофельнагель по дороге, ведущей из Северной Тернистой долины, и ищите город к юго-западу от арены Гурубаши.$B$BСудьба зовет!','Добро пожаловать в Укрытие Кофельнагель!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приказ вождя: мыс Тернистой долины',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Настоящим повелением всем годным к службе воинам орды приказано явиться к Хамми Кофельнагель, находящейся в Укрытии Кофельнагель. Она нуждается в вашей помощи в борьбе с пиратами и нагами, кишащими в джунглях.$B$BОтправляйтесь на юг в Укрытие Кофельнагель по дороге, ведущей из Северной Тернистой долины, и ищите город к юго-западу от арены Гурубаши.$B$BСудьба зовет!',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Добро пожаловать в Укрытие Кофельнагель!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (28705,'Приказ вождя: Запределье!','Приготовься к битве. Орда нуждается в твоем вмешательстве.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приказ вождя: Запределье!',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Приготовься к битве. Орда нуждается в твоем вмешательстве.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (28706,'Распыляй!','Мои сестры уже спустились в курган и сейчас пытаются разобраться с насекомыми. Но этих тварей слишком много. По-моему, пора применить газ.$b$bВозьми эти фумигаторы. Но только ничего с ними не делай: пользоваться ими должны только опытные профессионалы. Просто найди моих сестер и отдай фумигаторы им.$B$BРемма должна быть недалеко от входа. Иди вниз по коридору, а когда дойдешь до пандуса, держись правой стороны.','Отнесите коробку с инсектицидными фумигаторами Ремме Гориштор в берлогу Бен\'Таллоу.','Значит, будем применять инсектицид? Ну, похоже, другого выбора у нас нет.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Распыляй!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мои сестры уже спустились в курган и сейчас пытаются разобраться с насекомыми. Но этих тварей слишком много. По-моему, пора применить газ.$b$bВозьми эти фумигаторы. Но только ничего с ними не делай: пользоваться ими должны только опытные профессионалы. Просто найди моих сестер и отдай фумигаторы им.$B$BРемма должна быть недалеко от входа. Иди вниз по коридору, а когда дойдешь до пандуса, держись правой стороны.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите коробку с инсектицидными фумигаторами Ремме Гориштор в берлогу Бен\'Таллоу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Значит, будем применять инсектицид? Ну, похоже, другого выбора у нас нет.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (28707,'Распыли снова!','Сейчас я все сделаю.$B$BТак, следующий фумигатор нужно отдать Марси – она находится чуть дальше. Иди вот по этому коридору, до следующей большой комнаты.','Отнесите коробку с инсектицидными фумигаторами Марси Гориштор в берлогу Бен\'Таллоу.','Фумигаторы? От Ринно? Ну надо же...','Кто бы мог подумать, что сюда заявятся чужаки!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Распыли снова!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сейчас я все сделаю.$B$BТак, следующий фумигатор нужно отдать Марси – она находится чуть дальше. Иди вот по этому коридору, до следующей большой комнаты.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите коробку с инсектицидными фумигаторами Марси Гориштор в берлогу Бен\'Таллоу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Фумигаторы? От Ринно? Ну надо же...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Кто бы мог подумать, что сюда заявятся чужаки!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (28708,'Воззвание к героям: Запределье!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Воззвание к героям: Запределье!',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (28710,'Распыли еще раз!','Кто бы мог подумать, что помощником Ринно окажется |3-6($r)! Я надеялась, что это будет кто-то помощнее... Вечно этот Ринно пытается выехать на нашем горбу.$B$BСейчас я настрою этот фумигатор. А ты иди на север по коридору и найди Сану. Наверно, она заблудилась где-то в последней комнате, так что не забудь осмотреть все боковые ходы.','Отнесите коробку с инсектицидными фумигаторами Сане Гориштор в берлогу Бен\'Таллоу.','Тебя прислал Ринно! И попросил передать... фумигаторы? Фу!','Что ты здесь делаешь?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Распыли еще раз!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кто бы мог подумать, что помощником Ринно окажется |3-6($r)! Я надеялась, что это будет кто-то помощнее... Вечно этот Ринно пытается выехать на нашем горбу.$B$BСейчас я настрою этот фумигатор. А ты иди на север по коридору и найди Сану. Наверно, она заблудилась где-то в последней комнате, так что не забудь осмотреть все боковые ходы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите коробку с инсектицидными фумигаторами Сане Гориштор в берлогу Бен\'Таллоу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебя прислал Ринно! И попросил передать... фумигаторы? Фу!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что ты здесь делаешь?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (28711,'Армии Песни Войны пригодятся такие |3-7(Охотник), как ты.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Армии Песни Войны пригодятся такие |3-7(Охотник), как ты.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (28712,'Королева драконов вступает в бой','Обратитесь к Лирастразе в Круге Жизни на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Королева драконов вступает в бой',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обратитесь к Лирастразе в Круге Жизни на Сумеречном нагорье.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (28713,'Природное равновесие','Привет, $n. Мое имя Илталайн. В Тенистой долине я учу таких, как ты, и забочусь о том, чтобы не нарушалось природное равновесие.$B$BВ этом году весна была очень дождливой, и в результате одни звери чувствуют себя прекрасно, а другие, наоборот, страдают. К сожалению, ночные саблезубы слишком расплодились: если ничего не предпринять, они истребят всю живность в этом лесу.$B$BИди же, |3-6($c), и уменьши численность саблезубов, чтобы в природе восстановилась гармония.','Убейте 6 молодых ночных саблезубов.','Ты хорошо исполняешь свой долг, $n.','Еще многое предстоит сделать, $n. Возвращайся ко мне, как только ты сократишь численность ночных саблезубов.','Поговорите с Илталайном в Тенистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Природное равновесие',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Привет, $n. Мое имя Илталайн. В Тенистой долине я учу таких, как ты, и забочусь о том, чтобы не нарушалось природное равновесие.$B$BВ этом году весна была очень дождливой, и в результате одни звери чувствуют себя прекрасно, а другие, наоборот, страдают. К сожалению, ночные саблезубы слишком расплодились: если ничего не предпринять, они истребят всю живность в этом лесу.$B$BИди же, |3-6($c), и уменьши численность саблезубов, чтобы в природе восстановилась гармония.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 6 молодых ночных саблезубов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты хорошо исполняешь свой долг, $n.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Еще многое предстоит сделать, $n. Возвращайся ко мне, как только ты сократишь численность ночных саблезубов.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Илталайном в Тенистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (28714,'Мох скверны','Похоже, ты знаешь, что делаешь. Значит, я могу дать тебе более важное поручение.$B$BНасколько тебе известно, Тельдрассил был очищен от порчи. Но все-таки там что-то осталось. Звери не успокоились, и местных жителей одолевают разные беды.$B$BИди на запад и разберись с тамошними греллями. Проверь, нет ли у них мха скверны. Это поможет мне понять, откуда здесь берется скверна.','Соберите 6 пучков мха Скверны, отобрав их у греллей, которые находятся к западу от Илталайна.','Вернитесь к Илталайну в Тенистую долину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мох скверны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Похоже, ты знаешь, что делаешь. Значит, я могу дать тебе более важное поручение.$B$BНасколько тебе известно, Тельдрассил был очищен от порчи. Но все-таки там что-то осталось. Звери не успокоились, и местных жителей одолевают разные беды.$B$BИди на запад и разберись с тамошними греллями. Проверь, нет ли у них мха скверны. Это поможет мне понять, откуда здесь берется скверна.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 6 пучков мха Скверны, отобрав их у греллей, которые находятся к западу от Илталайна.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Илталайну в Тенистую долину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (28715,'Демонические воры','Мерзкие грелли! Они снова воруют наши припасы.$B$BЯ почти уверен в том, что они спрятали мои сумки в своем лагере, к западу отсюда. Принеси мне эти сумки, и я с радостью награжу тебя.','Найдите украденные у Мелитара сумки на западе, рядом с греллями.','У меня не будет провианта для покупателей, пока мне не вернут украденное добро. Ну как, удалось?','Поговорите с Мелитаром Оленьим Шлемом в Альдрассиле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Демонические воры',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мерзкие грелли! Они снова воруют наши припасы.$B$BЯ почти уверен в том, что они спрятали мои сумки в своем лагере, к западу отсюда. Принеси мне эти сумки, и я с радостью награжу тебя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите украденные у Мелитара сумки на западе, рядом с греллями.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У меня не будет провианта для покупателей, пока мне не вернут украденное добро. Ну как, удалось?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Мелитаром Оленьим Шлемом в Альдрассиле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (28716,'Воззвание к героям: Сумеречное нагорье!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Воззвание к героям: Сумеречное нагорье!',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (28718,'Где дым, там и вкусное мясо','Слушай, |3-6($c)... ты любишь мясо? Нет, даже не так – ты любишь деньги? $B$BМой троюродный брат сколотил целое состояние, торгуя замороженным мясом. На севере у него коптильня, и он ищет тех, кто готов охотиться на опасных тварей, у которых такое вкусное мясо.$B$BЗа хищников можно выручить хорошие деньги, точно тебе говорю. У меня-то здесь дела – а вот |3-6($r) вроде тебя может неплохо заработать на этом.$B$BБрата зовут Джез. Иди на северо-восток и ориентируйся на дым!','Найдите Джеза Скороцапа в коптильне Скороцапа, что в Зимних Ключах.','Посмотри вокруг – это же самые крупные охотничьи угодья гоблинов во всем Калимдоре! У меня есть лицензия на отстрел и поедание всего, что ходит по снегу отсюда до Круговзора... и, если честно, тут проживают невероятные лакомства!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Где дым, там и вкусное мясо',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слушай, |3-6($c)... ты любишь мясо? Нет, даже не так – ты любишь деньги? $B$BМой троюродный брат сколотил целое состояние, торгуя замороженным мясом. На севере у него коптильня, и он ищет тех, кто готов охотиться на опасных тварей, у которых такое вкусное мясо.$B$BЗа хищников можно выручить хорошие деньги, точно тебе говорю. У меня-то здесь дела – а вот |3-6($r) вроде тебя может неплохо заработать на этом.$B$BБрата зовут Джез. Иди на северо-восток и ориентируйся на дым!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Джеза Скороцапа в коптильне Скороцапа, что в Зимних Ключах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Посмотри вокруг – это же самые крупные охотничьи угодья гоблинов во всем Калимдоре! У меня есть лицензия на отстрел и поедание всего, что ходит по снегу отсюда до Круговзора... и, если честно, тут проживают невероятные лакомства!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (28719,'Мясо с душком','Многие утверждают, что у мяса щербозубов слишком резкий аромат. Я с этим не согласен, но, как говорится, о вкусах не спорят.$B$BА вот у могучих щербозубов – бурых братьев обычных щербозубов – у них мясо мягче, особенно на лапах. И, говорят, рыло считается деликатесом.$B$BПродолжай охотиться, $n, и принеси старому Фрэнсису несколько могучих щербозубов. Они живут к югу отсюда.','Убейте 15 могучих щербозубов.','Поговорите с Фрэнсисом Моркоттом в коптильне Скороцапа, что в Зимних Ключах.','Вкус неплохой.','Фрэнсис Моркотт','Хороший попался медведь.','Фрэнсис Моркотт') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мясо с душком',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Многие утверждают, что у мяса щербозубов слишком резкий аромат. Я с этим не согласен, но, как говорится, о вкусах не спорят.$B$BА вот у могучих щербозубов – бурых братьев обычных щербозубов – у них мясо мягче, особенно на лапах. И, говорят, рыло считается деликатесом.$B$BПродолжай охотиться, $n, и принеси старому Фрэнсису несколько могучих щербозубов. Они живут к югу отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 15 могучих щербозубов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Фрэнсисом Моркоттом в коптильне Скороцапа, что в Зимних Ключах.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Вкус неплохой.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Фрэнсис Моркотт',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Хороший попался медведь.',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Фрэнсис Моркотт',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (28720,'A Find of Significance') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','A Find of Significance',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (28721,'По вражеским тропам','За несколько недель мы послали уже три группы на разведку обстановки в Крепости Фарсона. К сожалению, ни одна из них не принесла никаких сведений.$B$BВ данный момент мы можем только уповать на то, что они живы и просто находятся в заключении. Я хочу, чтобы ты $gотправился:отправилась; в крепость и $gпомог:помогла; в освобождении наших солдат. Это будет непросто, $n, но именно ты в силах нам помочь.','Сопроводите заключенного Крепости Фарсона в безопасное место. Данная крепость расположена на северe острова.','Узник крепости Фарсона сопровожден','Доложите командиру Лармашу в Хватке Адского Крика о выполнении задания.','Кажется, ему нужна помощь.','Узник Крепости Фарсона') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','По вражеским тропам',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','За несколько недель мы послали уже три группы на разведку обстановки в Крепости Фарсона. К сожалению, ни одна из них не принесла никаких сведений.$B$BВ данный момент мы можем только уповать на то, что они живы и просто находятся в заключении. Я хочу, чтобы ты $gотправился:отправилась; в крепость и $gпомог:помогла; в освобождении наших солдат. Это будет непросто, $n, но именно ты в силах нам помочь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сопроводите заключенного Крепости Фарсона в безопасное место. Данная крепость расположена на северe острова.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Узник крепости Фарсона сопровожден',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доложите командиру Лармашу в Хватке Адского Крика о выполнении задания.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Кажется, ему нужна помощь.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Узник Крепости Фарсона',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (28722,'Йетифобия','Все готово, $n!$B$BЯ сказала своей подруге Легакки, что у меня для нее сюрприз. Но мне понадобится твоя помощь.$B$BЯ отдам тебе своего механического йети и предоставлю тебе честь ее удивить. Она сейчас на другом конце Круговзора, рядом с таверной.$B$BПодойди к ней и включи йети... А я буду следить за вами отсюда!','Напугайте Легакки с помощью механического йети Уми.','Она ни о чем не подозревает!','Вернитесь к Уми Румпельшникер в Круговзор, что в Зимних Ключах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Йетифобия',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Все готово, $n!$B$BЯ сказала своей подруге Легакки, что у меня для нее сюрприз. Но мне понадобится твоя помощь.$B$BЯ отдам тебе своего механического йети и предоставлю тебе честь ее удивить. Она сейчас на другом конце Круговзора, рядом с таверной.$B$BПодойди к ней и включи йети... А я буду следить за вами отсюда!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Напугайте Легакки с помощью механического йети Уми.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Она ни о чем не подозревает!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Уми Румпельшникер в Круговзор, что в Зимних Ключах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (28723,'Жрица луны','Поговорите с Дентарией Серебристой Поляной в центре Тенистой долины между двумя водоемами.','Хорошо, что ты здесь. Похоже, процесс обучения идет довольно быстро.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жрица луны',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Дентарией Серебристой Поляной в центре Тенистой долины между двумя водоемами.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо, что ты здесь. Похоже, процесс обучения идет довольно быстро.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (28724,'Противоядие для Иверрона','Нашего друга Иверрона покусали местные пауки и отравили его своим ядом. Я могу поддерживать Иверрона в его нынешнем состоянии, но для приготовления противоядия мне нужна твоя помощь.$B$BПо берегам этих водоемов растут лунные лилии. Они обладают целебными свойствами, и я могу объединить их с другими ингредиентами и сделать противоядие для Иверрона.$B$BПожалуйста, набери этих лилий. В здешних краях их много, можно увидеть даже отсюда.','Соберите 7 лунных лилий.','Это то, что нужно. Спасибо, $n. Ты действуешь очень быстро, и это прекрасно.','Наш дорогой друг чувствует себя не очень хорошо, и даже мои лекарства не помогают. Тебе удалось добыть нужные ингредиенты?','Поговорите с Дентарией Серебристой Поляной между водоемов в Тенистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Противоядие для Иверрона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нашего друга Иверрона покусали местные пауки и отравили его своим ядом. Я могу поддерживать Иверрона в его нынешнем состоянии, но для приготовления противоядия мне нужна твоя помощь.$B$BПо берегам этих водоемов растут лунные лилии. Они обладают целебными свойствами, и я могу объединить их с другими ингредиентами и сделать противоядие для Иверрона.$B$BПожалуйста, набери этих лилий. В здешних краях их много, можно увидеть даже отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 7 лунных лилий.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это то, что нужно. Спасибо, $n. Ты действуешь очень быстро, и это прекрасно.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Наш дорогой друг чувствует себя не очень хорошо, и даже мои лекарства не помогают. Тебе удалось добыть нужные ингредиенты?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Дентарией Серебристой Поляной между водоемов в Тенистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (28725,'Защитница леса','Я хочу поручить тебе более опасное дело. Духи леса сообщили мне нечто очень странное. Тариндрелла, загадочная защитница леса, снова вернулась в Тенистую долину. $B$BА ведь ее присутствия не ощущали здесь со времен благословения Тельдрассила. И если она решила снова прийти сюда, значит, здесь творится что-то неладное.$B$BОтправляйся на север, в Паучье логово, и найди там Тариндреллу. Это опасное место, так что на всякий случай мы приготовим это противоядие.','Найдите дриаду по имени Тариндрелла в Паучьем логове в северной части Тенистой долины.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Защитница леса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я хочу поручить тебе более опасное дело. Духи леса сообщили мне нечто очень странное. Тариндрелла, загадочная защитница леса, снова вернулась в Тенистую долину. $B$BА ведь ее присутствия не ощущали здесь со времен благословения Тельдрассила. И если она решила снова прийти сюда, значит, здесь творится что-то неладное.$B$BОтправляйся на север, в Паучье логово, и найди там Тариндреллу. Это опасное место, так что на всякий случай мы приготовим это противоядие.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите дриаду по имени Тариндрелла в Паучьем логове в северной части Тенистой долины.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28726,'Оскверненные пауки','Я надеялась, что мне никогда не придется возвращаться в Тельдрассил по такому страшному поводу. Думала, эта земля полностью очищена от порчи. Но зло все-таки здесь осталось.$B$BЭти пауки пострадали от порчи гораздо больше, чем другая живность. Они представляют опасность как для твоего народа, так и для всего леса. Мы должны сократить их численность, но еще важнее обнаружить источник скверны.$B$BЯ пойду с тобой и помогу.','Убейте 12 чащобных тенетников.','Порча, от которой страдают эти пауки, засела очень глубоко. И это не магия – нет, они уже родились с ней.$B$BПо-моему, наш следующий шаг очевиден.','Вернитесь к Тариндрелле в Паучье логово в Тенистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оскверненные пауки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я надеялась, что мне никогда не придется возвращаться в Тельдрассил по такому страшному поводу. Думала, эта земля полностью очищена от порчи. Но зло все-таки здесь осталось.$B$BЭти пауки пострадали от порчи гораздо больше, чем другая живность. Они представляют опасность как для твоего народа, так и для всего леса. Мы должны сократить их численность, но еще важнее обнаружить источник скверны.$B$BЯ пойду с тобой и помогу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 чащобных тенетников.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Порча, от которой страдают эти пауки, засела очень глубоко. И это не магия – нет, они уже родились с ней.$B$BПо-моему, наш следующий шаг очевиден.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тариндрелле в Паучье логово в Тенистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (28727,'Зловещее прикосновение','Если у этих пауков от рождения в жилах скверна, значит, источник этой заразы – их мать.$B$BДавай доберемся до северной части пещеры и найдем Гитьис Зловещую. Ответ на наш вопрос находится в ней.','Убейте Гитьис Зловещую в северной части Паучьего логова.','Гитьис и ее потомство заразили этот тотем – тотем фурболгов.$B$BЭто весьма тревожная новость. Это значит, что Кривая Сосна до сих пор представляет опасность для этих лесов. Мы слишком рано забыли об осторожности.','Поговорите с Тариндреллой в Паучьем логове в Тенистой долине.','Гитьис знает, откуда взялась порча в Тенистой долине и в остальных частях Тельдрассила.','Гитьис Зловещая') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зловещее прикосновение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если у этих пауков от рождения в жилах скверна, значит, источник этой заразы – их мать.$B$BДавай доберемся до северной части пещеры и найдем Гитьис Зловещую. Ответ на наш вопрос находится в ней.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Гитьис Зловещую в северной части Паучьего логова.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Гитьис и ее потомство заразили этот тотем – тотем фурболгов.$B$BЭто весьма тревожная новость. Это значит, что Кривая Сосна до сих пор представляет опасность для этих лесов. Мы слишком рано забыли об осторожности.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Тариндреллой в Паучьем логове в Тенистой долине.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Гитьис знает, откуда взялась порча в Тенистой долине и в остальных частях Тельдрассила.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Гитьис Зловещая',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (28728,'Видения будущего','Я пойду по следу Кривой Сосны и найду источник этой скверны. Если в Доланааре ты встретишь Атридаса Медвежью Шкуру, расскажи ему все. Ему прекрасно знакомы все беды этого леса, и он сможет дать тебе дельный совет.$B$BДумаю, мы еще встретимся. Если я обнаружу источник скверны, то, возможно, ты поможешь мне его ликвидировать. А пока что я отведу тебя обратно к Дентарии, и ты продолжишь свое обучение. Спасибо за все, $n.','Поговорите с Дентарией Серебристой Поляной между двумя водоемами в центре Тенистой долины.','Ты снова здесь! Я рада тебя видеть. Похоже, тебе удалось ликвидировать источник порчи в Тенистой долине.$B$BТельдрассил все еще страдает, и ему нужна наша помощь. Но у нас есть немного времени для того, чтобы завершить твое обучение здесь, в Тенистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Видения будущего',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я пойду по следу Кривой Сосны и найду источник этой скверны. Если в Доланааре ты встретишь Атридаса Медвежью Шкуру, расскажи ему все. Ему прекрасно знакомы все беды этого леса, и он сможет дать тебе дельный совет.$B$BДумаю, мы еще встретимся. Если я обнаружу источник скверны, то, возможно, ты поможешь мне его ликвидировать. А пока что я отведу тебя обратно к Дентарии, и ты продолжишь свое обучение. Спасибо за все, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Дентарией Серебристой Поляной между двумя водоемами в центре Тенистой долины.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты снова здесь! Я рада тебя видеть. Похоже, тебе удалось ликвидировать источник порчи в Тенистой долине.$B$BТельдрассил все еще страдает, и ему нужна наша помощь. Но у нас есть немного времени для того, чтобы завершить твое обучение здесь, в Тенистой долине.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (28729,'Телдрассил: венец Азерота','Если ты хочешь закончить обучение здесь, в Тенистой долине, то тебе нужно узнать больше о нашей истории.$B$BПоэтому я прошу тебя выполнить одно задание. Иди на северо-восток, к нашему лунному колодцу. Набери из него воды в этот пузырек. Пока ты будешь там, сможешь увидеть проявления нашей магии и узнать о нашей истории.$B$BКогда закончишь, принеси воду мне, и я скажу, что нужно делать дальше.','Наполните хрустальный фиал водой из лунного колодца в северо-восточной части Тенистой долины.','Наша новейшая история полна жутких, кровавых событий. Нам предстоит еще многое переосмыслить.','Поговорите с Дентарией Серебристой Поляной между водоемов на севере Тенистой долины.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Телдрассил: венец Азерота',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если ты хочешь закончить обучение здесь, в Тенистой долине, то тебе нужно узнать больше о нашей истории.$B$BПоэтому я прошу тебя выполнить одно задание. Иди на северо-восток, к нашему лунному колодцу. Набери из него воды в этот пузырек. Пока ты будешь там, сможешь увидеть проявления нашей магии и узнать о нашей истории.$B$BКогда закончишь, принеси воду мне, и я скажу, что нужно делать дальше.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Наполните хрустальный фиал водой из лунного колодца в северо-восточной части Тенистой долины.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Наша новейшая история полна жутких, кровавых событий. Нам предстоит еще многое переосмыслить.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Дентарией Серебристой Поляной между водоемов на севере Тенистой долины.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (28730,'Драгоценные воды','Тенарон Хватка Бури следит за всем, что происходит в долине. Он сидит на вершине Альдрассила.$B$BЕсли посмотришь на юг, то увидишь помост, который ведет к нему. Поднимись по этому помосту и заверши свое обучение.$B$BМне было приятно познакомиться с тобой, $n. Меня переполняет гордость при мысли о том, что среди молодых ночных эльфов есть такие самоотверженные и полные энергии, как ты. Ты совершишь великие подвиги во славу нашего народа.$B$BДо встречи.','Отдайте наполненный хрустальный фиал Тенарону Хватке Бури на вершине Альдрассила в Тенистой долине.','Значит, тебе уже рассказали первую часть истории о том, что произошло после битвы у Хиджала. Тебе предстоит еще многое узнать. А чтобы выполнить задание, придется пройти по Тельдрассилу и побывать в Дарнасе.','Лунные колодцы наполнены водой из Источника Вечности, древнего сосредоточия магической энергии, навлекшего многочисленные бедствия на наш мир.$B$BДруиды ценят эти колодцы за их чудесные свойства, Часовые почитают их как святилища Элуны, и даже возвращающиеся к нам высокорожденные смотрят на них с какой-то затаенной тоской.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Драгоценные воды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тенарон Хватка Бури следит за всем, что происходит в долине. Он сидит на вершине Альдрассила.$B$BЕсли посмотришь на юг, то увидишь помост, который ведет к нему. Поднимись по этому помосту и заверши свое обучение.$B$BМне было приятно познакомиться с тобой, $n. Меня переполняет гордость при мысли о том, что среди молодых ночных эльфов есть такие самоотверженные и полные энергии, как ты. Ты совершишь великие подвиги во славу нашего народа.$B$BДо встречи.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отдайте наполненный хрустальный фиал Тенарону Хватке Бури на вершине Альдрассила в Тенистой долине.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Значит, тебе уже рассказали первую часть истории о том, что произошло после битвы у Хиджала. Тебе предстоит еще многое узнать. А чтобы выполнить задание, придется пройти по Тельдрассилу и побывать в Дарнасе.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Лунные колодцы наполнены водой из Источника Вечности, древнего сосредоточия магической энергии, навлекшего многочисленные бедствия на наш мир.$B$BДруиды ценят эти колодцы за их чудесные свойства, Часовые почитают их как святилища Элуны, и даже возвращающиеся к нам высокорожденные смотрят на них с какой-то затаенной тоской.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (28731,'Тельдрассил: утраченное знание','Я мог бы поведать тебе еще многое о лунных колодцах и о Тельдрассиле, однако тебе пора в путь. Коритрас Лунный Гнев ждет тебя. Я перелил воду из фиала, принесенного тобой, в этот сосуд, чтобы ты $gотнес:отнесла; его Коритрасу.$b$bТы найдешь Коритраса у лунного колодца в Доланааре. Иди из Тенистой долины по дороге, что на юге от Альдрассила, а когда она свернет на запад, следуй по пути, мощенному булыжниками.$b$bИ советую тебе не сходить с дороги, $n, – в последнее время в лесу появились опасные существа.','Отнесите частично наполненный сосуд Коритрасу Лунному Гневу в Доланаар.','А, вижу, ты от Тенарона. Что ж, нам многое предстоит обсудить и сделать.$B$BОднако прежде чем перейти к практическим задачам, тебе предстоит обратиться к мудрости этого лунного колодца.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тельдрассил: утраченное знание',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я мог бы поведать тебе еще многое о лунных колодцах и о Тельдрассиле, однако тебе пора в путь. Коритрас Лунный Гнев ждет тебя. Я перелил воду из фиала, принесенного тобой, в этот сосуд, чтобы ты $gотнес:отнесла; его Коритрасу.$b$bТы найдешь Коритраса у лунного колодца в Доланааре. Иди из Тенистой долины по дороге, что на юге от Альдрассила, а когда она свернет на запад, следуй по пути, мощенному булыжниками.$b$bИ советую тебе не сходить с дороги, $n, – в последнее время в лесу появились опасные существа.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите частично наполненный сосуд Коритрасу Лунному Гневу в Доланаар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, вижу, ты от Тенарона. Что ж, нам многое предстоит обсудить и сделать.$B$BОднако прежде чем перейти к практическим задачам, тебе предстоит обратиться к мудрости этого лунного колодца.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`endtext_loc8`) VALUES (28732,'Это может значить только одно...','Нас с Разом завербовали Стражи Хиджала, чтобы мы установили обстоятельства возвращения Рагнароса в наш мир. Смею доложить, что Рагнарос действительно вернулся, и он очень зол! Мы также получили доказательства того, что сектанты из культа Сумеречного Молота перемещают элементалей по Восточным королевствам в Пещеры Черной горы.$B$BМы с Разом как раз собирались направиться в то место, чтобы разведать обстановку. У нас в буровой машине как раз найдется местечко для тебя. Залезай внутрь да поедем.','Доберитесь до Пещер Черной горы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Это может значить только одно...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нас с Разом завербовали Стражи Хиджала, чтобы мы установили обстоятельства возвращения Рагнароса в наш мир. Смею доложить, что Рагнарос действительно вернулся, и он очень зол! Мы также получили доказательства того, что сектанты из культа Сумеречного Молота перемещают элементалей по Восточным королевствам в Пещеры Черной горы.$B$BМы с Разом как раз собирались направиться в то место, чтобы разведать обстановку. У нас в буровой машине как раз найдется местечко для тебя. Залезай внутрь да поедем.',`details_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Доберитесь до Пещер Черной горы.',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (28732,'Что же делать, Раза похитили! Как только мы вошли внутрь, на нас накинулась дюжина сектантов вместе с каким-то жирным огром. Я дал стрекача, а Раз попытался отбиться. Мы должны его спасти, Михухоль!') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что же делать, Раза похитили! Как только мы вошли внутрь, на нас накинулась дюжина сектантов вместе с каким-то жирным огром. Я дал стрекача, а Раз попытался отбиться. Мы должны его спасти, Михухоль!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (28733,'Основы ботаники','На помощь! Помогите! Свихнувшаяся нежить атакует мою ферму! Наверняка это дело рук того ненормального надзирателя с Топких полей. Помоги мне отбиться от этих зомби!','Выдержите 1 внушительную волну наступления зомби.','Поговорите с ботаником Брейзи в усадьбе Брейзи, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Основы ботаники',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На помощь! Помогите! Свихнувшаяся нежить атакует мою ферму! Наверняка это дело рук того ненормального надзирателя с Топких полей. Помоги мне отбиться от этих зомби!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выдержите 1 внушительную волну наступления зомби.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с ботаником Брейзи в усадьбе Брейзи, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (28734,'Просьба Мелитара','Тебе нужно поговорить с Мелитаром. Кажется, у него уже были какие-то проблемы с греллями.$B$BЕсли ты поможешь ему, то, возможно, он выделит тебе место для хранения товаров.','Идите в Тенистую долину и поговорите с Мелитаром Оленьим Шлемом.','Тебя прислал Илталайн? Весьма умно с его стороны. Мне в самом деле нужна помощь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Просьба Мелитара',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе нужно поговорить с Мелитаром. Кажется, у него уже были какие-то проблемы с греллями.$B$BЕсли ты поможешь ему, то, возможно, он выделит тебе место для хранения товаров.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Идите в Тенистую долину и поговорите с Мелитаром Оленьим Шлемом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебя прислал Илталайн? Весьма умно с его стороны. Мне в самом деле нужна помощь.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`) VALUES (28735,'В Чертог Испепеления!','Это была засада, $n! Как только мы вошли внутрь, на нас накинулся фантастически жирный огр по имени Ром\'огг Костекрушитель! Раз отважно бросился защищать меня, а я побежал прочь в укрытие. Я видел, как они вначале избили, а потом потянули его, еле дышащего, в место, которое огр назвал "Чертогом Испепеления". Думаю, оно находится в зале за мостом.$B$BМне слишком страшно идти туда. Возьми-ка мой универсальный шлем и попробуй отыскать Раза. Я буду держать с тобой связь через этот шлем.$B$BЕсли найдешь жуткого огра, прикончи его!','Прикончите Ром\'огга Костекрушителя.','<Шлем Вентурона трещит от напряжения.>.$B$BРАЗ! Что же они с ним сотворили?! ОТЫЩИ ЕГО!','Поговорите с Айсом Вентуроном в Пещерах Черной горы на Черной горе.','Ходячий жирный окорок, что похитил Раза.','Ром\'огг Костекрушитель','Найди Раза!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В Чертог Испепеления!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это была засада, $n! Как только мы вошли внутрь, на нас накинулся фантастически жирный огр по имени Ром\'огг Костекрушитель! Раз отважно бросился защищать меня, а я побежал прочь в укрытие. Я видел, как они вначале избили, а потом потянули его, еле дышащего, в место, которое огр назвал "Чертогом Испепеления". Думаю, оно находится в зале за мостом.$B$BМне слишком страшно идти туда. Возьми-ка мой универсальный шлем и попробуй отыскать Раза. Я буду держать с тобой связь через этот шлем.$B$BЕсли найдешь жуткого огра, прикончи его!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Прикончите Ром\'огга Костекрушителя.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Шлем Вентурона трещит от напряжения.>.$B$BРАЗ! Что же они с ним сотворили?! ОТЫЩИ ЕГО!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Айсом Вентуроном в Пещерах Черной горы на Черной горе.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Ходячий жирный окорок, что похитил Раза.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Ром\'огг Костекрушитель',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Найди Раза!',`questturntextwindow_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28736,'Огонь с высот','Недобитки Шнотца укрепились здесь, на Возвышении Творца. Из-за этого всем, кто окажется поблизости, грозит смертельная опасность.$B$BСнарядов у нас тут хватает, но без хорошего наводчика мне приходится палить вслепую.$B$BНу-ка, запрыгивай и помоги мне. Застанем его солдат врасплох!','Запрыгивайте на конфискованное орудие и расстреляйте из него 100 пехотинцев Шнотца.','Противник на Возвышении Творца окончательно не обезврежен, однако с твоей помощью мы нанесли серьезный удар по их силам – и боевому духу.','Обратитесь к бывалому кочевнику у Пропасти Пилигрима.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Огонь с высот',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Недобитки Шнотца укрепились здесь, на Возвышении Творца. Из-за этого всем, кто окажется поблизости, грозит смертельная опасность.$B$BСнарядов у нас тут хватает, но без хорошего наводчика мне приходится палить вслепую.$B$BНу-ка, запрыгивай и помоги мне. Застанем его солдат врасплох!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Запрыгивайте на конфискованное орудие и расстреляйте из него 100 пехотинцев Шнотца.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Противник на Возвышении Творца окончательно не обезврежен, однако с твоей помощью мы нанесли серьезный удар по их силам – и боевому духу.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Обратитесь к бывалому кочевнику у Пропасти Пилигрима.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`) VALUES (28737,'Что это за место?','Убейте глашатая сумрака Корлу','<Шлем Вентурона трещит от напряжения>.$B$BУ нас мало времени. Похоже, что Раз ранен. Если мы вовремя до него доберемся, то существует вероятность, что я смогу снова обратить его в обычного орка!$B$B<Вы чувствуете резкую боль в голове и слышите звон монет.>$B$BИзвини. Я думал подкинуть тебе золотишка за твои старания...','Поговорите с Айсом Вентуроном в Пещерах Черной горы на Черной горе.','Она выглядит зловеще!','Глашатай сумрака Корла','Время на исходе! Разу нужна наша помощь!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Что это за место?',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте глашатая сумрака Корлу',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Шлем Вентурона трещит от напряжения>.$B$BУ нас мало времени. Похоже, что Раз ранен. Если мы вовремя до него доберемся, то существует вероятность, что я смогу снова обратить его в обычного орка!$B$B<Вы чувствуете резкую боль в голове и слышите звон монет.>$B$BИзвини. Я думал подкинуть тебе золотишка за твои старания...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Айсом Вентуроном в Пещерах Черной горы на Черной горе.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Она выглядит зловеще!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Глашатай сумрака Корла',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Время на исходе! Разу нужна наша помощь!',`questturntextwindow_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`) VALUES (28738,'Сумеречная кузня','Прикончите Карша Гнущего Сталь.','Поговорите с Айсом Вентуроном в Пещерах Черной горы на Черной горе.','Похоже, что он действительно гнет сталь руками.','Карш Гнущий Сталь, бронник Сумеречного Молота','Раз где-то рядом. Я его слышу!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сумеречная кузня',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Прикончите Карша Гнущего Сталь.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Айсом Вентуроном в Пещерах Черной горы на Черной горе.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Похоже, что он действительно гнет сталь руками.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Карш Гнущий Сталь, бронник Сумеречного Молота',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Раз где-то рядом. Я его слышу!',`questturntextwindow_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (28739,'Night Elf Class Skill Tracker Quest') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Night Elf Class Skill Tracker Quest',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`) VALUES (28740,'Не верь глазам своим','Убейте Красавицу.','Поговорите с Айсом Вентуроном в Пещерах Черной горы на Черной горе.','Порождение зла!','Красавица','Это сэкономит мне несколько лет жизни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Не верь глазам своим',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Красавицу.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Айсом Вентуроном в Пещерах Черной горы на Черной горе.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Порождение зла!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Красавица',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Это сэкономит мне несколько лет жизни.',`questturntextwindow_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (28740,'<Шлем Вентурона трещит от напряжения>.$B$BХа… Одной заботой меньше, осталось только выбраться из этого места.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Шлем Вентурона трещит от напряжения>.$B$BХа… Одной заботой меньше, осталось только выбраться из этого места.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (28741,'Повелитель Перерожденных Обсидий','Расправьтесь с Повелителем Перерожденных Обсидием.','Бедный Раз. Он был лучшим другом, о котором может мечтать гном. По крайней мере, мы отомстили за его смерть и зачистили эту проклятую пещеру!','Поговорите с Айсом Вентуроном в Пещерах Черной горы на Черной горе.','Когда-то простой смертный, а ныне новоявленный повелитель элементалей.','Повелитель Перерожденных Обсидий') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Повелитель Перерожденных Обсидий',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Расправьтесь с Повелителем Перерожденных Обсидием.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Бедный Раз. Он был лучшим другом, о котором может мечтать гном. По крайней мере, мы отомстили за его смерть и зачистили эту проклятую пещеру!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Айсом Вентуроном в Пещерах Черной горы на Черной горе.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Когда-то простой смертный, а ныне новоявленный повелитель элементалей.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Повелитель Перерожденных Обсидий',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (28742,'Ши-Ротам','А теперь, $gприятель:подруга;, мы будем охотиться на крупную дичь! На севере живет Ши-Ротам, самый крупный ледопард в мире.$B$BЭто большая честь для тебя, ведь это самый опасный зверь, на которого когда-либо ходили охотники... а если когда-нибудь ты увидишь ту кучу денег, которую гурманы предлагают за кусочек мяса Ши-Ротам, у тебя лопнут глаза!$B$BКогда убьешь ее, возвращайся в лагерь. Я не хочу, чтобы кто-то истребил всех ледопардов за один день...','Убейте Ши-Ротам.','Невероятно, дитя. С тобой никто не сравнится! А ведь я просил добыть эту кошку пятерых разных охотников!$B$BНу, двоих мы нашли, когда капитан притащил тушу, но не будем о грустном...','Поговорите с Джезом Скороцапом в Зимних Ключах, в коптильне Скороцапа.','Глава прайда ледопардов Зимних Ключей... и вкуснейший обед!','Ши-Ротам') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ши-Ротам',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А теперь, $gприятель:подруга;, мы будем охотиться на крупную дичь! На севере живет Ши-Ротам, самый крупный ледопард в мире.$B$BЭто большая честь для тебя, ведь это самый опасный зверь, на которого когда-либо ходили охотники... а если когда-нибудь ты увидишь ту кучу денег, которую гурманы предлагают за кусочек мяса Ши-Ротам, у тебя лопнут глаза!$B$BКогда убьешь ее, возвращайся в лагерь. Я не хочу, чтобы кто-то истребил всех ледопардов за один день...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Ши-Ротам.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Невероятно, дитя. С тобой никто не сравнится! А ведь я просил добыть эту кошку пятерых разных охотников!$B$BНу, двоих мы нашли, когда капитан притащил тушу, но не будем о грустном...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Джезом Скороцапом в Зимних Ключах, в коптильне Скороцапа.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Глава прайда ледопардов Зимних Ключей... и вкуснейший обед!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Ши-Ротам',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (28743,'Стрелок хвостовой пушки','Не хочешь чуток поохотиться, $n?$B$BЗалезай! Я лечу. Ты стреляешь!','Сбейте 15 асов Шнотца.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Стрелок хвостовой пушки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не хочешь чуток поохотиться, $n?$B$BЗалезай! Я лечу. Ты стреляешь!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сбейте 15 асов Шнотца.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28744,'Вурдалакам не нравятся мои семена','А ты неплохо справляешься, $n! Просто юный ботаник! Слушай, у меня есть новые семена, которые я хотел бы испытать, называются орехокамни. Используй их, чтобы остановить нежить. Просто бросай их на землю и зомби не смогут пройти дальше. Нежить так глупа!$b$bДавай попытаемся!','Выдержите 2 внушительных волны наступления зомби.','Думаю, это разозлит Штиллеца, и он пришлет "тяжелую артиллерию". Не будем терять времени, друг, за дело!','Поговорите с ботаником Брейзи в усадьбе Брейзи, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вурдалакам не нравятся мои семена',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А ты неплохо справляешься, $n! Просто юный ботаник! Слушай, у меня есть новые семена, которые я хотел бы испытать, называются орехокамни. Используй их, чтобы остановить нежить. Просто бросай их на землю и зомби не смогут пройти дальше. Нежить так глупа!$b$bДавай попытаемся!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выдержите 2 внушительных волны наступления зомби.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Думаю, это разозлит Штиллеца, и он пришлет "тяжелую артиллерию". Не будем терять времени, друг, за дело!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с ботаником Брейзи в усадьбе Брейзи, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (28745,'Крикуны в собственном соку','Убейте 15 крикунов Зимних Ключей.','Джеб Гутри','От этой говорильной штуки у меня ум за разум заходит.','Джеб Гутри') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Крикуны в собственном соку',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 15 крикунов Зимних Ключей.',`objectives_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Джеб Гутри',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','От этой говорильной штуки у меня ум за разум заходит.',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Джеб Гутри',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28746,'Взломанная защита','Ну ладно, приступим, $n!$B$BЗа этой дверью – главная комната, что-то вроде центральной диспетчерской.$B$BСейчас я войду в эту дверь, быстренько деактивирую преобразующий механизм, а потом мы все дружно отправимся домой кушать плюшки. Дела на две минуты.$B$BВсе зависит от уровня подготовки, $gсынок:малышка;. Именно уровень и отличает настоящего археолога от обычного охотника за сокровищами.$B$BК чему поднимать лишний шум и будоражить зверюг? Все можно сделать по-умному... отключить пару приборов... вывести аппаратуру из строя...','Проникните в зал управления титанов.','Так, у меня две новости. Плохая и...$B$B...очень плохая.','Поговорите с Бранном Бронзобородом в Чертоге Огней в Чертогах Созидания.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Взломанная защита',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну ладно, приступим, $n!$B$BЗа этой дверью – главная комната, что-то вроде центральной диспетчерской.$B$BСейчас я войду в эту дверь, быстренько деактивирую преобразующий механизм, а потом мы все дружно отправимся домой кушать плюшки. Дела на две минуты.$B$BВсе зависит от уровня подготовки, $gсынок:малышка;. Именно уровень и отличает настоящего археолога от обычного охотника за сокровищами.$B$BК чему поднимать лишний шум и будоражить зверюг? Все можно сделать по-умному... отключить пару приборов... вывести аппаратуру из строя...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проникните в зал управления титанов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так, у меня две новости. Плохая и...$B$B...очень плохая.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Бранном Бронзобородом в Чертоге Огней в Чертогах Созидания.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28747,'Тыквомбы','$gВидел:Видела; когда-нибудь такое?$b$b<Брейзи вытаскивает тыкву.>$b$bЭто не просто тыква, $gдружок:подружка;. Смотри, ты кладешь ее на землю, подходит зомби и... БУМ! От зомби остается мокрое место. Давай попробуем!','Выдержите 2 внушительных волны наступления зомби.','ТЫ слышишь этот грохот? Наверное, идет сам Штиллец. О Господи, смотри!','Поговорите с ботаником Брейзи в усадьбе Брейзи, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тыквомбы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$gВидел:Видела; когда-нибудь такое?$b$b<Брейзи вытаскивает тыкву.>$b$bЭто не просто тыква, $gдружок:подружка;. Смотри, ты кладешь ее на землю, подходит зомби и... БУМ! От зомби остается мокрое место. Давай попробуем!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выдержите 2 внушительных волны наступления зомби.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','ТЫ слышишь этот грохот? Наверное, идет сам Штиллец. О Господи, смотри!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с ботаником Брейзи в усадьбе Брейзи, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (28748,'Посев мертвецов','Это Штиллец! Он уже почти здесь! Он собирается забрать у нас все, что у нас есть, чтобы бороться с ним! За дело!','Поговорите с ботаником Брейзи в усадьбе Брейзи, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Посев мертвецов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это Штиллец! Он уже почти здесь! Он собирается забрать у нас все, что у нас есть, чтобы бороться с ним! За дело!',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с ботаником Брейзи в усадьбе Брейзи, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (28749,'Битва за Андорал','К нам только что прибыл грифон c известием из Чумных земель. Плохие новости.$b$bАндорал находится в гуще противостояния между Отрекшимися, Альянсом и Плетью. Король Ринн рискнул и поставил во главе своих войск рыцаря смерти. Однако я уверен, что он не откажется от любой помощи.$b$bОн отдельно упомянул о том, что им $gнужен:нужна:c; |3-6($c) Альянса для выполнения специальных заданий. Если ты $gсогласен:согласна;, обратись ко мне снова, чтобы я открыл портал.','Обратитесь к боевому магу Эраллиеру, чтобы тот телепортировал вас в Андорал, что находится в Западных Чумных землях. Затем поговорите с Тассарианом в Андорале.','Поговорите с Тассарианом в Андорале, что в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Битва за Андорал',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','К нам только что прибыл грифон c известием из Чумных земель. Плохие новости.$b$bАндорал находится в гуще противостояния между Отрекшимися, Альянсом и Плетью. Король Ринн рискнул и поставил во главе своих войск рыцаря смерти. Однако я уверен, что он не откажется от любой помощи.$b$bОн отдельно упомянул о том, что им $gнужен:нужна:c; |3-6($c) Альянса для выполнения специальных заданий. Если ты $gсогласен:согласна;, обратись ко мне снова, чтобы я открыл портал.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обратитесь к боевому магу Эраллиеру, чтобы тот телепортировал вас в Андорал, что находится в Западных Чумных землях. Затем поговорите с Тассарианом в Андорале.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Тассарианом в Андорале, что в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (28750,'Битва за Андорал','К нам только что прибыл ветрокрыл с известием из Чумных земель. Плохие новости.$b$bАндорал находится в гуще противостояния между Отрекшимися, Альянсом и Плетью. Похоже, что Сильвана рискнула и поставила во главе своих войск рыцаря смерти Кольтиру Ткача Смерти.$b$bОна отдельно упомянула о том, что им $gнужен:нужна:c; |3-6($c) для выполнения специальных заданий. Если ты $gсогласен:согласна;, обратись ко мне снова, чтобы я открыл портал.','Обратитесь к чародею Арману, чтобы тот телепортировал вас в Андорал, что находится в Западных Чумных землях. Затем поговорите с Кольтирой Ткачом Смерти в Андорале.','Поговорите с Кольтирой Ткачом Смерти в Андорале в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Битва за Андорал',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','К нам только что прибыл ветрокрыл с известием из Чумных земель. Плохие новости.$b$bАндорал находится в гуще противостояния между Отрекшимися, Альянсом и Плетью. Похоже, что Сильвана рискнула и поставила во главе своих войск рыцаря смерти Кольтиру Ткача Смерти.$b$bОна отдельно упомянула о том, что им $gнужен:нужна:c; |3-6($c) для выполнения специальных заданий. Если ты $gсогласен:согласна;, обратись ко мне снова, чтобы я открыл портал.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обратитесь к чародею Арману, чтобы тот телепортировал вас в Андорал, что находится в Западных Чумных землях. Затем поговорите с Кольтирой Ткачом Смерти в Андорале.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Кольтирой Ткачом Смерти в Андорале в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28751,'Уход за садом','Выдержите 2 внушительных волны наступления зомби.','На сегодня мы с ними справились, но я знаю, что завтра они вернутся. Надеюсь, ты будешь поблизости и сможешь мне помочь.','Поговорите с ботаником Брейзи в усадьбе Брейзи, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уход за садом',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выдержите 2 внушительных волны наступления зомби.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','На сегодня мы с ними справились, но я знаю, что завтра они вернутся. Надеюсь, ты будешь поблизости и сможешь мне помочь.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с ботаником Брейзи в усадьбе Брейзи, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (28752,'Непреодолимый натиск','Посмотрим, как долго это будет длиться. Останови как минимум 10 волн наступления зомби и получишь награду.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Непреодолимый натиск',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Посмотрим, как долго это будет длиться. Останови как минимум 10 волн наступления зомби и получишь награду.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28753,'Испорченная система','Вот зараза!$B$BКто-то уже постарался и разворотил всю систему! Теперь с этого пульта никак не добраться до базы данных.$B$BПридется нам делать все через за... э... другим способом. Надеюсь, $gсынок:малышка;, ты со своими замечательными друзьями ничего не имеешь против хорошей драки?$B$BВам надо подняться на самый верхний уровень. Там вас встретят четыре стража. Я смогу утилизировать эти диски, только когда эти стражи... ну, скажем так, будут исключены из системы.','По просьбе Бранна Бронзоборода убейте Изисет, Аммунаэ, Сетеша и Раджа.','Ну, вот и славно.$B$BДавай быстрее заканчивать с этими дисками!','Поговорите с Бранном Бронзобородом в самом верхнем зале Чертогов Созидания.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Испорченная система',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот зараза!$B$BКто-то уже постарался и разворотил всю систему! Теперь с этого пульта никак не добраться до базы данных.$B$BПридется нам делать все через за... э... другим способом. Надеюсь, $gсынок:малышка;, ты со своими замечательными друзьями ничего не имеешь против хорошей драки?$B$BВам надо подняться на самый верхний уровень. Там вас встретят четыре стража. Я смогу утилизировать эти диски, только когда эти стражи... ну, скажем так, будут исключены из системы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По просьбе Бранна Бронзоборода убейте Изисет, Аммунаэ, Сетеша и Раджа.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну, вот и славно.$B$BДавай быстрее заканчивать с этими дисками!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Бранном Бронзобородом в самом верхнем зале Чертогов Созидания.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (28754,'Битва жизни и смерти','Много лет Алекстраза трудилась над подготовкой этого места. Когда Смертокрыла заманят сюда, она воззовет к целительной силе Круга Жизни и одолеет смертоносное чудище.$B$BНеобходимо, чтобы колдовские камни жизни во время боя не подверглись губительным чарам. Внимание Смертокрыла будет занято исключительно королевой драконов; тебя он вряд ли заметит. Прикончи любого из его приспешников, кто покусится на Круг Жизни.$B$BСкажи мне, когда будешь $gготов:готова; к бою.','Помогите Алекстразе в ее попытке одолеть Смертокрыла. Защитите пять колдовских камней жизни в Круге Жизни!','Обратитесь к Калену возле Круга Жизни на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Битва жизни и смерти',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Много лет Алекстраза трудилась над подготовкой этого места. Когда Смертокрыла заманят сюда, она воззовет к целительной силе Круга Жизни и одолеет смертоносное чудище.$B$BНеобходимо, чтобы колдовские камни жизни во время боя не подверглись губительным чарам. Внимание Смертокрыла будет занято исключительно королевой драконов; тебя он вряд ли заметит. Прикончи любого из его приспешников, кто покусится на Круг Жизни.$B$BСкажи мне, когда будешь $gготов:готова; к бою.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Помогите Алекстразе в ее попытке одолеть Смертокрыла. Защитите пять колдовских камней жизни в Круге Жизни!',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Обратитесь к Калену возле Круга Жизни на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28755,'Летописи ордена Серебряной Длани','Знаешь ли ты, кто такие рыцари ордена Серебряной Длани? Они были первыми паладинами Света. Именно они потом образовали орден Серебряного Рассвета и Алый орден. И хотя многие из них сошли с пути истинного, они по-прежнему хранят ценные реликвии рыцарей ордена Серебряной Длани.$B$BВ центральных кварталах Стратхольма под неусыпным взором инструктора Галфорда хранятся летописи ордена Серебряной Длани. Все тома, которые тебе удастся раздобыть, найдут достойное место в воссозданной часовне Последней Надежды.','Разыщите утраченные тома летописей ордена Серебряной Длани в Стратхольме.','Это, несомненно, один из утерянных томов! Тиросс будет несказанно рад, узнав о твоей находке.','Вернитесь к лорду Реймонду Джорджу в часовню Последней Надежды.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Летописи ордена Серебряной Длани',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Знаешь ли ты, кто такие рыцари ордена Серебряной Длани? Они были первыми паладинами Света. Именно они потом образовали орден Серебряного Рассвета и Алый орден. И хотя многие из них сошли с пути истинного, они по-прежнему хранят ценные реликвии рыцарей ордена Серебряной Длани.$B$BВ центральных кварталах Стратхольма под неусыпным взором инструктора Галфорда хранятся летописи ордена Серебряной Длани. Все тома, которые тебе удастся раздобыть, найдут достойное место в воссозданной часовне Последней Надежды.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите утраченные тома летописей ордена Серебряной Длани в Стратхольме.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это, несомненно, один из утерянных томов! Тиросс будет несказанно рад, узнав о твоей находке.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лорду Реймонду Джорджу в часовню Последней Надежды.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28756,'Костяные кадавры','При жизни мы с братьями сражались со многими порождениями Плети, но никто так не переполнял наши души ненавистью, как некроманты. Мало им было поднять наших погибших товарищей из мертвых и натравить на нас – так они еще и создали этих омерзительных костяных големов с тесаками вместо рук!$B$BЭти кадавры порешили многих наших, и нам так и не удалось совладать с ними. Прошу тебя, $n, подними знамя павших. Проберись в склеп Некроситета и покончи с самой крупной и опасной из этих мерзких тварей.','Прикончите Громоклина в склепе Некроситета.','Твои подвиги делают честь защитникам этой священной земли, павшим в бою.','Вернитесь к лорду Реймонду Джорджу в часовню Последней Надежды.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Костяные кадавры',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','При жизни мы с братьями сражались со многими порождениями Плети, но никто так не переполнял наши души ненавистью, как некроманты. Мало им было поднять наших погибших товарищей из мертвых и натравить на нас – так они еще и создали этих омерзительных костяных големов с тесаками вместо рук!$B$BЭти кадавры порешили многих наших, и нам так и не удалось совладать с ними. Прошу тебя, $n, подними знамя павших. Проберись в склеп Некроситета и покончи с самой крупной и опасной из этих мерзких тварей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Прикончите Громоклина в склепе Некроситета.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Твои подвиги делают честь защитникам этой священной земли, павшим в бою.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лорду Реймонду Джорджу в часовню Последней Надежды.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`,`questgivertargetname_loc8`) VALUES (28757,'Дать отпор!','Вернитесь к маршалу Макбрайду в Аббатство Североземья, что в Элвиннском лесу.','Боевой ворг клана Черной горы') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дать отпор!',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к маршалу Макбрайду в Аббатство Североземья, что в Элвиннском лесу.',`completedtext_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Боевой ворг клана Черной горы',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28758,'Битва жизни и смерти','Алекстраза и Смертокрыл кружат в небе над Грим Батолом! План Алекстразы не сработал: королева драконов вне Круга Жизни, который она подготовила. Мы должны помочь ей всем, чем только сможем.$B$BСкорее! Забирайся на гранатового бойца, что позади меня.$B$BНаша задача – найти и уничтожить сумеречных драконов, которые помогают Смертокрылу. В седло, ну же!','Оседлайте гранатового бойца. Уничтожьте 8 сумеречных темных драконов.','Благодаря твоим решительным действиям королева драконов не погибла. Ее доставили в Драконий Покой, где она сейчас восстанавливает силы.$B$BНельзя сказать, что мы проиграли бой. Смертокрыл серьезно ранен. Думаю, он сейчас отправится зализывать раны. Алекстраза выиграла нам время для нанесения удара!','Поговорите с Каленом в Грим Батоле, что на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Битва жизни и смерти',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Алекстраза и Смертокрыл кружат в небе над Грим Батолом! План Алекстразы не сработал: королева драконов вне Круга Жизни, который она подготовила. Мы должны помочь ей всем, чем только сможем.$B$BСкорее! Забирайся на гранатового бойца, что позади меня.$B$BНаша задача – найти и уничтожить сумеречных драконов, которые помогают Смертокрылу. В седло, ну же!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Оседлайте гранатового бойца. Уничтожьте 8 сумеречных темных драконов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Благодаря твоим решительным действиям королева драконов не погибла. Ее доставили в Драконий Покой, где она сейчас восстанавливает силы.$B$BНельзя сказать, что мы проиграли бой. Смертокрыл серьезно ранен. Думаю, он сейчас отправится зализывать раны. Алекстраза выиграла нам время для нанесения удара!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Каленом в Грим Батоле, что на Сумеречном нагорье.',`completedtext_loc8`);
