INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (28760,'Возмездие за Орсис','Великий град Орсис подвергся нападению воздушных орд.$B$BНас захватили в плен – и нам еще повезло.$B$BА многие погибли, погребенные в удушающих песках...$B$BПриказ к наступлению на Орсис отдал Асаад, калиф Ал\'акира... И он должен поплатиться за это жизнью!','Прикончите Асаада.','Да благословят тебя боги. Прими это в знак моей признательности.','Вернитесь к Итешу на Вершину Смерча.','По воле Ал\'акира Асаад отдал приказ разрушить Орсис. Покарай его!','Калиф зефиров Асаад') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возмездие за Орсис',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Великий град Орсис подвергся нападению воздушных орд.$B$BНас захватили в плен – и нам еще повезло.$B$BА многие погибли, погребенные в удушающих песках...$B$BПриказ к наступлению на Орсис отдал Асаад, калиф Ал\'акира... И он должен поплатиться за это жизнью!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Прикончите Асаада.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да благословят тебя боги. Прими это в знак моей признательности.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Итешу на Вершину Смерча.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','По воле Ал\'акира Асаад отдал приказ разрушить Орсис. Покарай его!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Калиф зефиров Асаад',`questgivertargetname_loc8`);
