INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (28768,'Зимние Ключи!','Донова Снегонора – женщина-дворф – друг Древобрюхам.$B$BМы торгуем огненной водой.$B$BТы найдешь ее у источников Ледяного огня – это надо идти на восток через наши пещеры.$B$BОна хочет одолеть фурболгов из племени Зимней Спячки и нуждается в помощи. Может быть, ты сумеешь ей помочь.','Явитесь к Донове Снегоноре у Источников Ледяного огня в Зимних Ключах.','Хвала Свету, ты здесь. Я разузнала тайну свирепых фурболгов из племени Зимней Спячки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зимние Ключи!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Донова Снегонора – женщина-дворф – друг Древобрюхам.$B$BМы торгуем огненной водой.$B$BТы найдешь ее у источников Ледяного огня – это надо идти на восток через наши пещеры.$B$BОна хочет одолеть фурболгов из племени Зимней Спячки и нуждается в помощи. Может быть, ты сумеешь ей помочь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Явитесь к Донове Снегоноре у Источников Ледяного огня в Зимних Ключах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хвала Свету, ты здесь. Я разузнала тайну свирепых фурболгов из племени Зимней Спячки.',`offerrewardtext_loc8`);
