INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (28779,'До дома далече','Думаю, мне удалось сбежать потому, что отсюда, по сути, больше некуда деваться...$B$BЯ застрял на этих платформах, и рано или поздно они меня все равно найдут. Если только...$B$BСлыхал я, что сердце высокородного элементаля дарует его обладателю свойства соответствующей стихии. Стало быть, сердце воздушного элементаля пришлось бы очень кстати, надумай я спуститься на землю.$B$BПринеси мне сердце великого визиря Эртан – с помощью его магии я смогу благополучно приземлиться на побережье Ульдума.','Раздобудьте сердце великого визиря Эртан.','Даже не предлагай мне лететь с тобой на... той штуке, на которой ты сюда заявился...','Вернитесь к Итешу в Вершину Смерча.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','До дома далече',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Думаю, мне удалось сбежать потому, что отсюда, по сути, больше некуда деваться...$B$BЯ застрял на этих платформах, и рано или поздно они меня все равно найдут. Если только...$B$BСлыхал я, что сердце высокородного элементаля дарует его обладателю свойства соответствующей стихии. Стало быть, сердце воздушного элементаля пришлось бы очень кстати, надумай я спуститься на землю.$B$BПринеси мне сердце великого визиря Эртан – с помощью его магии я смогу благополучно приземлиться на побережье Ульдума.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте сердце великого визиря Эртан.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Даже не предлагай мне лететь с тобой на... той штуке, на которой ты сюда заявился...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Итешу в Вершину Смерча.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`questgivertargetname_loc8`) VALUES (28780,'В бой!','Сержант Виллем') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В бой!',`title_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Сержант Виллем',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (28780,'Да, мы и правда в западне. Я опасаюсь снова посылать туда солдат, так как и они могут погибнуть. Мне нужен доброволец, кто-то, кто рискнет своей жизнью!') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, мы и правда в западне. Я опасаюсь снова посылать туда солдат, так как и они могут погибнуть. Мне нужен доброволец, кто-то, кто рискнет своей жизнью!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (28781,'Неплановые цели','Мы были участниками секретной операции, организованной принцем Надуном из Рамкахена. Однако большую часть нашего отряда перебили в результате засады, вследствие чего мы не можем выполнить задание.$B$BЕсли ты согласишься помочь нам, я бы смог выторговать для тебя солидное вознаграждение.$B$BНам было поручено уничтожить любые неплановые цели, потеря которых нанесла бы ощутимый урон военной инфраструктуре противника.$B$BВпереди мы обнаружили генерала Хусама в сопровождении двух капитанов. Ликвидация этих целей станет неоспоримым благом для Рамкахена.','Ликвидируйте генерала Хусама и 2 присягнувших капитанов.','Вернитесь к капитану Хадану в Затерянный город Тол\'вир.','Нужно нанести сокрушительный удар по командованию Неферсета!','Генерал Хусам') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Неплановые цели',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы были участниками секретной операции, организованной принцем Надуном из Рамкахена. Однако большую часть нашего отряда перебили в результате засады, вследствие чего мы не можем выполнить задание.$B$BЕсли ты согласишься помочь нам, я бы смог выторговать для тебя солидное вознаграждение.$B$BНам было поручено уничтожить любые неплановые цели, потеря которых нанесла бы ощутимый урон военной инфраструктуре противника.$B$BВпереди мы обнаружили генерала Хусама в сопровождении двух капитанов. Ликвидация этих целей станет неоспоримым благом для Рамкахена.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Ликвидируйте генерала Хусама и 2 присягнувших капитанов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Хадану в Затерянный город Тол\'вир.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Нужно нанести сокрушительный удар по командованию Неферсета!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Генерал Хусам',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (28782,'Легендарная птица','У местных есть легенда о могучей сове, которая кружит над вершинами гор, словно сама крылатая смерть. Местные назвали ее "Смертокрыл".$B$BНо скоро им сообщили, что это имя уже занято, и поэтому они выбрали другое прозвище, которое также наполняет душу страхом и ужасом.$B$BСмертоух!$B$BСмертоух живет на вершине горы, к юго-западу от нашей коптильни. Заставь это инфернальное уханье умолкнуть... чтобы мы могли съесть эту сову!','Убейте Смертоуха.','Поговорите с Джебом Гутри в Зимних Ключах, в коптильне Скороцапа.','Вперед, за птицей!','Джеб Гутри') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Легендарная птица',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У местных есть легенда о могучей сове, которая кружит над вершинами гор, словно сама крылатая смерть. Местные назвали ее "Смертокрыл".$B$BНо скоро им сообщили, что это имя уже занято, и поэтому они выбрали другое прозвище, которое также наполняет душу страхом и ужасом.$B$BСмертоух!$B$BСмертоух живет на вершине горы, к юго-западу от нашей коптильни. Заставь это инфернальное уханье умолкнуть... чтобы мы могли съесть эту сову!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Смертоуха.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Джебом Гутри в Зимних Ключах, в коптильне Скороцапа.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Вперед, за птицей!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Джеб Гутри',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (28783,'Источник их силы','Перед тем, как наш отряд попал в засаду, нам удалось провести полномасштабную разведку в стане врага.$B$BМы установили, что посланник Смертокрыла Сиамат является источником новоприобретенной силы Неферсета.$B$BВраги заявляют, что они всего лишь восстановили величие прошлых дней, но произошло нечто другое: в их души закралась тьма.$B$BБудучи повелителем одного из четырех ветров, Сиамат обладает гигантской силой. Однако он растерял часть своего могущества вследствие передачи своей мощи Неферсету.$B$BНужно сразить его сейчас, пока Сиамат ослаблен, и положить конец этому безумию.','Сразите Сиамата.','Вернитесь к капитану Хадану в Затерянный город Тол\'вир.','Сиамат питает Неферсет неисчерпаемой силой!','Сиамат, южный ветер') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Источник их силы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Перед тем, как наш отряд попал в засаду, нам удалось провести полномасштабную разведку в стане врага.$B$BМы установили, что посланник Смертокрыла Сиамат является источником новоприобретенной силы Неферсета.$B$BВраги заявляют, что они всего лишь восстановили величие прошлых дней, но произошло нечто другое: в их души закралась тьма.$B$BБудучи повелителем одного из четырех ветров, Сиамат обладает гигантской силой. Однако он растерял часть своего могущества вследствие передачи своей мощи Неферсету.$B$BНужно сразить его сейчас, пока Сиамат ослаблен, и положить конец этому безумию.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сразите Сиамата.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Хадану в Затерянный город Тол\'вир.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Сиамат питает Неферсет неисчерпаемой силой!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Сиамат, южный ветер',`questgivertargetname_loc8`);
