INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questgivertargetname_loc8`) VALUES (28790,'Персональное приглашение','<В вас нарастает незнакомое чувство, наполняя весь ваш разум невиданными образами и странными мыслями.>$B$BУслышь меня, $n.$B$BНаш мир на грани жуткой катастрофы.$B$BВзываю к тебе: окажи нам помощь в этот трудный час.$B$BЯ Крогар.$B$BНайди меня, и я открою тебе твое предназначение.$B$BЖду тебя в Оргриммаре, к северу от Волока.','Предсказатель Крогар просит вас встретиться с ним в Оргриммаре.','Предсказатель Крогар') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Персональное приглашение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<В вас нарастает незнакомое чувство, наполняя весь ваш разум невиданными образами и странными мыслями.>$B$BУслышь меня, $n.$B$BНаш мир на грани жуткой катастрофы.$B$BВзываю к тебе: окажи нам помощь в этот трудный час.$B$BЯ Крогар.$B$BНайди меня, и я открою тебе твое предназначение.$B$BЖду тебя в Оргриммаре, к северу от Волока.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Предсказатель Крогар просит вас встретиться с ним в Оргриммаре.',`objectives_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Предсказатель Крогар',`questgivertargetname_loc8`);
