INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (28805,'Око Бури','Приветствую тебя.$B$BДа, ты $gизвестен:известна; нам под именем $n.$B$BТы $gсовершил:совершила; столько подвигов, что и не сосчитать. Азерот уже в долгу перед тобой, но нынче ему снова требуется помощь великих героев.$B$BА я лишь глашатай его воли. Могучий дух желает говорить с тобой.$B$BЗагляни в Воды предвидения и узри беды, грозящие нашему миру.','Предсказатель Крогар просит вас взглянуть в Воды предвидения.','Теперь, когда тебе открылась истина, где ты предпочтешь служить?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Око Бури',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приветствую тебя.$B$BДа, ты $gизвестен:известна; нам под именем $n.$B$BТы $gсовершил:совершила; столько подвигов, что и не сосчитать. Азерот уже в долгу перед тобой, но нынче ему снова требуется помощь великих героев.$B$BА я лишь глашатай его воли. Могучий дух желает говорить с тобой.$B$BЗагляни в Воды предвидения и узри беды, грозящие нашему миру.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Предсказатель Крогар просит вас взглянуть в Воды предвидения.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь, когда тебе открылась истина, где ты предпочтешь служить?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28806,'Не убойся зла','Надеюсь, теперь ты осознаешь всю полноту силы Света. Он дарует нам надежду, брат, и изгоняет тьму! ДА БЛАГОСЛОВЕН БУДЕТ СВЕТ!','Вернитесь к брату Пакстону, находящемуся позади Аббатства Североземья в Элвиннском лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Не убойся зла',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Надеюсь, теперь ты осознаешь всю полноту силы Света. Он дарует нам надежду, брат, и изгоняет тьму! ДА БЛАГОСЛОВЕН БУДЕТ СВЕТ!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к брату Пакстону, находящемуся позади Аббатства Североземья в Элвиннском лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28807,'Экспертное мнение','<Андуин держит в руках одинаковые медальоны.>$b$bМедальон, который мы нашли на ферме, как две капли воды похож на тот, что в записях Самуэльсона! Это не может быть простым совпадением. Думаю, Самуэльсон в чем-то замешан, но прежде чем обвинять одного из самых доверенных стражей моего отца, нам нужны улики.$b$bДумаю, только один человек может во всем этом разобраться: это Матиас Шоу, начальник ШРУ. Покажи ему эти знаки и узнай, что он о них думает. А я пока вернусь в крепость и постараюсь разыскать Самуэльсона!','Отнесите подозрительные медальоны Матиасу Шоу в штаб ШРУ, что в Штормграде.','Андуин ведет расследование, связанное с Сумеречным Молотом? А разве не предполагалось, что ты будешь ограждать его от проблем?$B$BХм. Дай-ка мне рассмотреть эти медальоны.','Отнесите подозрительные медальоны Матиасу Шоу в штаб ШРУ, что в Штормграде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Экспертное мнение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Андуин держит в руках одинаковые медальоны.>$b$bМедальон, который мы нашли на ферме, как две капли воды похож на тот, что в записях Самуэльсона! Это не может быть простым совпадением. Думаю, Самуэльсон в чем-то замешан, но прежде чем обвинять одного из самых доверенных стражей моего отца, нам нужны улики.$b$bДумаю, только один человек может во всем этом разобраться: это Матиас Шоу, начальник ШРУ. Покажи ему эти знаки и узнай, что он о них думает. А я пока вернусь в крепость и постараюсь разыскать Самуэльсона!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите подозрительные медальоны Матиасу Шоу в штаб ШРУ, что в Штормграде.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Андуин ведет расследование, связанное с Сумеречным Молотом? А разве не предполагалось, что ты будешь ограждать его от проблем?$B$BХм. Дай-ка мне рассмотреть эти медальоны.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите подозрительные медальоны Матиасу Шоу в штаб ШРУ, что в Штормграде.',`completedtext_loc8`);
