INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (28814,'Пастыри и паства','В бумагах описывается визит верховной жрицы Азил в глубины Каменных Недр.$B$BИсходя из изложенного, Азил – высокопоставленный член Сумеречного Совета, а ее кортеж более чем из ста верных последователей готовится провести темный ритуал необыкновенно разрушительной силы.$B$BПохоже, вам стоит воспрепятствовать осуществлению их планов.','Убейте верховную жрицу Азил и 101 верного последователя.','Верховная жрица, говоришь? Да к тому же член Сумеречного Совета?$B$BЧто ж, прекрасная работа! Надеюсь, ты будешь доволен наградой.','Вернитесь к Хранителю земли Изре в Каменные недра.','Больше сотни верных последователей...','Верховная жрица Азил') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пастыри и паства',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В бумагах описывается визит верховной жрицы Азил в глубины Каменных Недр.$B$BИсходя из изложенного, Азил – высокопоставленный член Сумеречного Совета, а ее кортеж более чем из ста верных последователей готовится провести темный ритуал необыкновенно разрушительной силы.$B$BПохоже, вам стоит воспрепятствовать осуществлению их планов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте верховную жрицу Азил и 101 верного последователя.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Верховная жрица, говоришь? Да к тому же член Сумеречного Совета?$B$BЧто ж, прекрасная работа! Надеюсь, ты будешь доволен наградой.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хранителю земли Изре в Каменные недра.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Больше сотни верных последователей...',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Верховная жрица Азил',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (28815,'Документы Сумеречного Молота','Мы выследили агента Сумеречного Молота. Зовут его Миллхаус Манашторм.$B$BЕсть основания полагать, что у него при себе важные бумаги.$B$BОднако мы не можем оставить внутренний периметр Храма Земли без защиты.$B$BРазыщи Манашторма и отбери у него документы.','Раздобудьте документы Сумеречного Молота.','Раздобудьте документы Сумеречного Молота.','Миллхаус Манашторм') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Документы Сумеречного Молота',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы выследили агента Сумеречного Молота. Зовут его Миллхаус Манашторм.$B$BЕсть основания полагать, что у него при себе важные бумаги.$B$BОднако мы не можем оставить внутренний периметр Храма Земли без защиты.$B$BРазыщи Манашторма и отбери у него документы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте документы Сумеречного Молота.',`objectives_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Раздобудьте документы Сумеречного Молота.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Миллхаус Манашторм',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (28816,'В пучину','Служители Земли установили, что водянистый регион Вайш\'ир является источником разрушительной энергии.$b$bСложно сказать, что за опасности таит в себе это место, но любые сведения о нем, что ты сможешь добыть, окажутся чрезвычайно полезными.$b$bВ это самое время Орда посылает в данный регион военную армаду. Для того чтобы попасть на корабль, обратись к командиру Тораку в бухте Острорука.$b$bДа хранят тебя духи, $n.','Явитесь с рапортом к командиру Тораку в бухте Острорука в Дуротаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В пучину',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Служители Земли установили, что водянистый регион Вайш\'ир является источником разрушительной энергии.$b$bСложно сказать, что за опасности таит в себе это место, но любые сведения о нем, что ты сможешь добыть, окажутся чрезвычайно полезными.$b$bВ это самое время Орда посылает в данный регион военную армаду. Для того чтобы попасть на корабль, обратись к командиру Тораку в бухте Острорука.$b$bДа хранят тебя духи, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Явитесь с рапортом к командиру Тораку в бухте Острорука в Дуротаре.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (28824,'Блудный сын','Одно из моих чад покинуло меня, $n.$B$BСын мой остался у Сумеречного Молота, в нижних чертогах Храма Земли – Каменных Недрах.$B$BЯ отправила его братьев освободить несчастного от пут темной магии, с помощью которой его там удерживали... но оказалось, что он не был скован ни магией, ни чем-либо еще.$B$BСпускайся в Каменные Недра и убей Озрука. Нужно вернуть его земле.','Убейте Озрука.','Вернитесь к Теразан в Трон Теразан.','Мой сын…','Озрук') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Блудный сын',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Одно из моих чад покинуло меня, $n.$B$BСын мой остался у Сумеречного Молота, в нижних чертогах Храма Земли – Каменных Недрах.$B$BЯ отправила его братьев освободить несчастного от пут темной магии, с помощью которой его там удерживали... но оказалось, что он не был скован ни магией, ни чем-либо еще.$B$BСпускайся в Каменные Недра и убей Озрука. Нужно вернуть его земле.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Озрука.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Теразан в Трон Теразан.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Мой сын…',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Озрук',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questgivertargetname_loc8`) VALUES (28825,'Персональное приглашение','<В вас нарастает незнакомое чувство, наполняя ваш разум невиданными образами и странными мыслями.>$B$BУслышь меня, $n.$B$BНаш мир на грани жуткой катастрофы.$B$BВзываю к тебе: окажи нам помощь в этот трудный час.$B$BЯ – Нараат.$B$BНайди меня, не медли, и я открою тебе твое предназначение.$B$BЖду тебя у Восточного святилища Земли в Штормграде.','Разыщите Нараата Говорящего с Землей в Штормграде.','Нараат Говорящий с Землей') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Персональное приглашение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<В вас нарастает незнакомое чувство, наполняя ваш разум невиданными образами и странными мыслями.>$B$BУслышь меня, $n.$B$BНаш мир на грани жуткой катастрофы.$B$BВзываю к тебе: окажи нам помощь в этот трудный час.$B$BЯ – Нараат.$B$BНайди меня, не медли, и я открою тебе твое предназначение.$B$BЖду тебя у Восточного святилища Земли в Штормграде.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите Нараата Говорящего с Землей в Штормграде.',`objectives_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Нараат Говорящий с Землей',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (28826,'Око Бури','Приветствую тебя, герой Азерота.$B$B$B$BСреди нас, Служителей Земли, ты $gизвестен:известна; нам под именем $n.$B$BПодвигам и свершениям твоим несть числа. Азерот уже в долгу перед тобой, но нынче ему снова требуется помощь великих героев.$B$BА я лишь глашатай его воли. Могучий дух желает говорить с тобой.$B$BЗагляни в Воды предвидения и узри беды, грозящие нашему миру.','Нараат Говорящий с Землей просит вас взглянуть в Воды предвидения.','Теперь, когда тебе открылась истина, где ты предпочтешь служить?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Око Бури',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приветствую тебя, герой Азерота.$B$B$B$BСреди нас, Служителей Земли, ты $gизвестен:известна; нам под именем $n.$B$BПодвигам и свершениям твоим несть числа. Азерот уже в долгу перед тобой, но нынче ему снова требуется помощь великих героев.$B$BА я лишь глашатай его воли. Могучий дух желает говорить с тобой.$B$BЗагляни в Воды предвидения и узри беды, грозящие нашему миру.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Нараат Говорящий с Землей просит вас взглянуть в Воды предвидения.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь, когда тебе открылась истина, где ты предпочтешь служить?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (28827,'В пучину','Служители Земли установили, что водянистый регион Вайш\'ир является источником разрушительной энергии.$b$bСложно сказать, что за опасности таит в себе это место, но любые сведения о нем, что ты сможешь добыть, окажутся чрезвычайно полезными.$b$bВ это самое время Альянс посылает в данный регион военную армаду. Для того чтобы попасть на корабль, отправляйся в северо-западную часть Штормграда и обратись к вербовщику Бернсу в порту Штормграда.$b$bДа хранят тебя духи, $n.','Поговорите с вербовщиком Бернсом в порту Штормграда.','Все наши боевые корабли сейчас в море, сражаются с Ордой. Тебе придется отправиться на корабле наемников.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В пучину',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Служители Земли установили, что водянистый регион Вайш\'ир является источником разрушительной энергии.$b$bСложно сказать, что за опасности таит в себе это место, но любые сведения о нем, что ты сможешь добыть, окажутся чрезвычайно полезными.$b$bВ это самое время Альянс посылает в данный регион военную армаду. Для того чтобы попасть на корабль, отправляйся в северо-западную часть Штормграда и обратись к вербовщику Бернсу в порту Штормграда.$b$bДа хранят тебя духи, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с вербовщиком Бернсом в порту Штормграда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Все наши боевые корабли сейчас в море, сражаются с Ордой. Тебе придется отправиться на корабле наемников.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (28828,'Яйца – вкусная и полезная пища','У меня не очень тонкий вкус, но даже я ненавижу местных химер. А вот их яйца – это совсем другое дело.$B$BЯйца химер – самая нежная и питательная пища по эту сторону Оргриммара. Они куда вкуснее, чем скучные яйца сов.$B$BЯ куплю все яйца, которые тебе удастся собрать. Иди на северо-восток и ищи их гнезда в снегу.','Соберите 40 яиц хладнокрылых химер.','Замечательные яйца.$B$BОни будут отлично сочетаться с беконом из медведя. Эй, Фрэнсис, у нас медвежатина осталась?','Мм-м...','Вернитесь к Джезу Скороцапу в коптильню Скороцапа, что в Зимних Ключах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Яйца – вкусная и полезная пища',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У меня не очень тонкий вкус, но даже я ненавижу местных химер. А вот их яйца – это совсем другое дело.$B$BЯйца химер – самая нежная и питательная пища по эту сторону Оргриммара. Они куда вкуснее, чем скучные яйца сов.$B$BЯ куплю все яйца, которые тебе удастся собрать. Иди на северо-восток и ищи их гнезда в снегу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 40 яиц хладнокрылых химер.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Замечательные яйца.$B$BОни будут отлично сочетаться с беконом из медведя. Эй, Фрэнсис, у нас медвежатина осталась?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мм-м...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джезу Скороцапу в коптильню Скороцапа, что в Зимних Ключах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (28829,'Рога остры и клювы наши быстры','Спрашиваешь, что со мной стряслось? Так слушай, |3-6($c), и слушай внимательно, ибо повесть моя трагична...$B$BМеня отправили в Совиную чащу на поиски реликвий. Стоило мне дойти сюда, как на меня налетел вихрь из крыльев и когтей.$B$BОни так вопили и клевались, |3-6($c)!$B$BИ вот теперь я, поверженный орк, лежу здесь и мечтаю лишь о мести! Прошу тебя, |3-6($c), если ты дорожишь своей честью, отправляйся в Совиную чащу и помоги мне вернуть мою!','Убейте 12 совухов в Совиной чаще.','Вернитесь к Джадрагу Кромсателю в Совиную чащу, что в Зимних Ключах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рога остры и клювы наши быстры',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Спрашиваешь, что со мной стряслось? Так слушай, |3-6($c), и слушай внимательно, ибо повесть моя трагична...$B$BМеня отправили в Совиную чащу на поиски реликвий. Стоило мне дойти сюда, как на меня налетел вихрь из крыльев и когтей.$B$BОни так вопили и клевались, |3-6($c)!$B$BИ вот теперь я, поверженный орк, лежу здесь и мечтаю лишь о мести! Прошу тебя, |3-6($c), если ты дорожишь своей честью, отправляйся в Совиную чащу и помоги мне вернуть мою!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 совухов в Совиной чаще.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джадрагу Кромсателю в Совиную чащу, что в Зимних Ключах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (28830,'Яблоко от яблони','Мои таинственные покровители дали мне не единственное задание. За выполнением второго поручения я отправился дальше на юг, в теснину Ледяного Шепота. Я был озадачен, выяснив, что мост через теснину развалился надвое и по земле на другую сторону не перебраться.$B$BК тому же молодые отпрыски великанов из племени Ледяного Молота были отрезаны от своих взрослых родителей-силачей. Я подумал, что мне удастся одолеть малюток в бою.$B$BИ был неправ. Пришлось мне постыдно улепетывать.$B$BПроучи этих увальней, $n. Срази их в честном поединке.','Убейте 8 отпрысков великанов из племени Ледяного Молота.','Вернитесь к Джадрагу Кромсателю в Совиную чащу, что в Зимних Ключах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Яблоко от яблони',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мои таинственные покровители дали мне не единственное задание. За выполнением второго поручения я отправился дальше на юг, в теснину Ледяного Шепота. Я был озадачен, выяснив, что мост через теснину развалился надвое и по земле на другую сторону не перебраться.$B$BК тому же молодые отпрыски великанов из племени Ледяного Молота были отрезаны от своих взрослых родителей-силачей. Я подумал, что мне удастся одолеть малюток в бою.$B$BИ был неправ. Пришлось мне постыдно улепетывать.$B$BПроучи этих увальней, $n. Срази их в честном поединке.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 отпрысков великанов из племени Ледяного Молота.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джадрагу Кромсателю в Совиную чащу, что в Зимних Ключах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (28831,'Будь проклят Студиликус','Великаны племени Ледяного Молота не были бы помехой, если бы не этот проклятый Студиликус! Когда случилось землетрясение и мост рухнул, он со своими водными элементалями вытек из-под земли и занял низину в теснине Ледяного Шепота, выдворив оттуда великанов.$B$BБудь ты проклят, Студиликус!$B$BА ты, |3-6($c), окажешь мне большую услугу, если загонишь его обратно под землю. Ты найдешь его к югу отсюда, на дне теснины.','Убейте Студиликуса.','Вернитесь к Джадрагу Кромсателю в Совиную чащу, что в Зимних Ключах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Будь проклят Студиликус',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Великаны племени Ледяного Молота не были бы помехой, если бы не этот проклятый Студиликус! Когда случилось землетрясение и мост рухнул, он со своими водными элементалями вытек из-под земли и занял низину в теснине Ледяного Шепота, выдворив оттуда великанов.$B$BБудь ты проклят, Студиликус!$B$BА ты, |3-6($c), окажешь мне большую услугу, если загонишь его обратно под землю. Ты найдешь его к югу отсюда, на дне теснины.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Студиликуса.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джадрагу Кромсателю в Совиную чащу, что в Зимних Ключах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (28832,'Сумеречный берег','Давай, садись в гидросамолет позади меня и полетим к нагорью.$b$bТам нам надо поговорить с каким-то лейтенантом Фоксом. Я обещал королю, что мы быстро обернемся, так что решил не брать никаких лишних вещей. Например, ремней безопасности. Парашютов. Карт. Стабилизаторов. Шасси.$b$bВсе равно все это не нужно.','Поговорите с лейтенантом Фоксом на Высоком берегу, что в Сумеречном нагорье.','Меньше всего я ожидал увидеть падающими с неба вас двоих. Высокий берег подвергается нападению!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сумеречный берег',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Давай, садись в гидросамолет позади меня и полетим к нагорью.$b$bТам нам надо поговорить с каким-то лейтенантом Фоксом. Я обещал королю, что мы быстро обернемся, так что решил не брать никаких лишних вещей. Например, ремней безопасности. Парашютов. Карт. Стабилизаторов. Шасси.$b$bВсе равно все это не нужно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с лейтенантом Фоксом на Высоком берегу, что в Сумеречном нагорье.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Меньше всего я ожидал увидеть падающими с неба вас двоих. Высокий берег подвергается нападению!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (28833,'Спасение Эрунака','Освободите Эрунака Говорящего с Камнем.','Обратитесь к Эрунаку Говорящему с Камнем в Троне Приливов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спасение Эрунака',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Освободите Эрунака Говорящего с Камнем.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Обратитесь к Эрунаку Говорящему с Камнем в Троне Приливов.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (28833,'Что такое? Ты... ты меня спасаешь?!$B$B<Эрунак улыбается.>$B$BЭто так неожиданно... к этому надо привыкнуть.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что такое? Ты... ты меня спасаешь?!$B$B<Эрунак улыбается.>$B$BЭто так неожиданно... к этому надо привыкнуть.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (28834,'Спасение Эрунака','Освободите Эрунака Говорящего с Камнем.','Обратитесь к Эрунаку Говорящему с Камнем в Троне Приливов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спасение Эрунака',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Освободите Эрунака Говорящего с Камнем.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Обратитесь к Эрунаку Говорящему с Камнем в Троне Приливов.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (28835,'Благословенная свежесть','Ну и жарища у нас в долине!$b$b*Галгар утирает пот со лба.*$b$bБыли бы у меня плоды кактуса, я бы изготовил свой знаменитый кактусовый десерт! Ничто не освежает лучше этого восхитительного лакомства.$b$bЗнаешь что, $n? Принеси-ка мне шесть плодов кактуса, и я изготовлю тебе несколько порций кактусового десерта. Они тебе пригодятся в путешествиях. Плоды кактуса можно собрать со здешних кактусов.','Добудьте 6 плодов кактуса.','Вернитесь к Галгару в Долину Испытаний в Дуротар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Благословенная свежесть',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну и жарища у нас в долине!$b$b*Галгар утирает пот со лба.*$b$bБыли бы у меня плоды кактуса, я бы изготовил свой знаменитый кактусовый десерт! Ничто не освежает лучше этого восхитительного лакомства.$b$bЗнаешь что, $n? Принеси-ка мне шесть плодов кактуса, и я изготовлю тебе несколько порций кактусового десерта. Они тебе пригодятся в путешествиях. Плоды кактуса можно собрать со здешних кактусов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 6 плодов кактуса.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Галгару в Долину Испытаний в Дуротар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertargetname_loc8`) VALUES (28836,'Грехи морской ведьмы','Эта злобная тварь заслужила тысячу смертей!$B$BНо уничтожить ее совсем не просто. Она тут хорошо окопалась со своими гнусными приспешниками. Правда, сейчас она истощена после сражения с Нептулоном.$B$BТак что самое время нанести удар! Другого шанса может и не быть.$B$BУбей ее, $n!','Убейте Леди Наз\'жар на Троне Приливов.','Поговорите с капитаном Тейлором в Троне Приливов.','Леди Наз\'жар') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Грехи морской ведьмы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эта злобная тварь заслужила тысячу смертей!$B$BНо уничтожить ее совсем не просто. Она тут хорошо окопалась со своими гнусными приспешниками. Правда, сейчас она истощена после сражения с Нептулоном.$B$BТак что самое время нанести удар! Другого шанса может и не быть.$B$BУбей ее, $n!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Леди Наз\'жар на Троне Приливов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с капитаном Тейлором в Троне Приливов.',`completedtext_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Леди Наз\'жар',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (28837,'Мутировавшие звери','Нас, синих драконов, выдворили из собственного дома, Мазторила. Самозванец Умбранс одержал верх в минуту нашей уязвимости и оккупировал пещеру.$B$BМазторил – средоточие очень мощной магии, а он не умеет ею пользоваться. Страдает даже местная фауна.$B$BЖивотные в окрестностях преобразились. Прошу тебя об услуге, |3-6($r). Принеси мне мозг некоторых этих зверей: я должна понять, в силах ли я обратить хаотическое колдовство Умбранса.','Раздобудьте 5 образцов мутировавших от магии мозгов животных.','Посмотрим, что я смогу выяснить...','Мазторил принадлежит стае синих драконов. То, что случилось, несправедливо.','Вернитесь к Хале в Берилловый Удел, что в Зимних Ключах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мутировавшие звери',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нас, синих драконов, выдворили из собственного дома, Мазторила. Самозванец Умбранс одержал верх в минуту нашей уязвимости и оккупировал пещеру.$B$BМазторил – средоточие очень мощной магии, а он не умеет ею пользоваться. Страдает даже местная фауна.$B$BЖивотные в окрестностях преобразились. Прошу тебя об услуге, |3-6($r). Принеси мне мозг некоторых этих зверей: я должна понять, в силах ли я обратить хаотическое колдовство Умбранса.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте 5 образцов мутировавших от магии мозгов животных.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Посмотрим, что я смогу выяснить...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мазторил принадлежит стае синих драконов. То, что случилось, несправедливо.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хале в Берилловый Удел, что в Зимних Ключах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (28838,'Защита совухов','Стыдно признаться, но что бы там Умбранс ни сотворил, он не дает мне обратить его колдовство.$B$BОн оказался хитрее, чем я предполагала.$B$BВпрочем, у меня есть запасной план. Я видела, что совухи спокойно входят в Мазторил и возвращаются даже после его захвата Умбрансом. Их древняя магия друидов, должно быть, сильнее колдовства Умбранса. По счастью, я неплохо разбираюсь в их традициях.$B$BОтправляйся на юг в Дун Мандарр. Там ты найдешь сундук с ловушкой для снов.$B$BЭто то, что нам нужно для начала.','Отыщите ловушку снов совухов в Дун Мандарре.','Синяя драконья стая не может потерять еще и Мазторил.','Хале') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Защита совухов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Стыдно признаться, но что бы там Умбранс ни сотворил, он не дает мне обратить его колдовство.$B$BОн оказался хитрее, чем я предполагала.$B$BВпрочем, у меня есть запасной план. Я видела, что совухи спокойно входят в Мазторил и возвращаются даже после его захвата Умбрансом. Их древняя магия друидов, должно быть, сильнее колдовства Умбранса. По счастью, я неплохо разбираюсь в их традициях.$B$BОтправляйся на юг в Дун Мандарр. Там ты найдешь сундук с ловушкой для снов.$B$BЭто то, что нам нужно для начала.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщите ловушку снов совухов в Дун Мандарре.',`objectives_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Синяя драконья стая не может потерять еще и Мазторил.',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Хале',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (28839,'Доисторическая магия','На востоке находятся священные пещеры совухов. В некоторых из них ты найдешь тотемы. Подойди к тотемам и собери их эссенции, сколько сможешь. Ловушка для снов впитает эту эссенцию, и ее можно будет поставить в Мазториле.','Раздобудьте эссенцию тотема когтей, эссенцию тотема жизни и эссенцию лунного тотема.','Тотемы священны для совухов. Они будут яростно их защищать.','Хале','Древняя магия совухов очень сильна. И все же...','Хале') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Доисторическая магия',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На востоке находятся священные пещеры совухов. В некоторых из них ты найдешь тотемы. Подойди к тотемам и собери их эссенции, сколько сможешь. Ловушка для снов впитает эту эссенцию, и ее можно будет поставить в Мазториле.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте эссенцию тотема когтей, эссенцию тотема жизни и эссенцию лунного тотема.',`objectives_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Тотемы священны для совухов. Они будут яростно их защищать.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Хале',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Древняя магия совухов очень сильна. И все же...',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Хале',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (28840,'Зимняя вода','Я сильно постараюсь, чтобы наша затея не провалилась, $n. Неудача привлечет внимание к нашим усилиям и даст Умбрансу возможность укрепить оборону. Нет, у нас будет всего одна попытка.$B$BВ теснине Ледяного Шепота, что на юге, обитают могучие ледяные элементали. Вода в этих элементалях усилит твою ловушку для снов и закрепит наш успех.$B$BРаздобудь эту воду, $n, и возвращайся сюда.','Раздобудьте 7 колб зимней воды из ледяных аватар в Теснине Ледяного Шепота.','С возвращением.','Вернитесь к Хале в Берилловый Удел в Зимних Ключах.','Мы не допустим провала.','Хале') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зимняя вода',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я сильно постараюсь, чтобы наша затея не провалилась, $n. Неудача привлечет внимание к нашим усилиям и даст Умбрансу возможность укрепить оборону. Нет, у нас будет всего одна попытка.$B$BВ теснине Ледяного Шепота, что на юге, обитают могучие ледяные элементали. Вода в этих элементалях усилит твою ловушку для снов и закрепит наш успех.$B$BРаздобудь эту воду, $n, и возвращайся сюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте 7 колб зимней воды из ледяных аватар в Теснине Ледяного Шепота.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','С возвращением.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хале в Берилловый Удел в Зимних Ключах.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Мы не допустим провала.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Хале',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28841,'Чародейская буря','В Мазториле скрыта великая магия, и если она выйдет из-под контроля, то причинит немыслимые беды. Бездумно творя заклинания, Умбранс создал несколько тессерактов – иными словами, порталов, ведущих в иные миры. И прежде чем я вернусь в Мазторил, эти порталы должны быть закрыты.$B$BЛовушка снов заблокирует порталы, дав тебе возможность проникнуть в логово Умбранса. Сначала уничтожь то, что выйдет из тессерактов, затем с помощью ловушки быстро закрой их – пока в этот мир не проникло еще что-нибудь.','С помощью заряженного ловца снов закройте 5 чародейских тессерактов в Мазториле.','Мазторил не скоро возродится... но он возродится.$B$BСиние драконы будут жить!','Вернитесь к Хале в Берилловый Удел, что в Зимних Ключах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чародейская буря',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В Мазториле скрыта великая магия, и если она выйдет из-под контроля, то причинит немыслимые беды. Бездумно творя заклинания, Умбранс создал несколько тессерактов – иными словами, порталов, ведущих в иные миры. И прежде чем я вернусь в Мазторил, эти порталы должны быть закрыты.$B$BЛовушка снов заблокирует порталы, дав тебе возможность проникнуть в логово Умбранса. Сначала уничтожь то, что выйдет из тессерактов, затем с помощью ловушки быстро закрой их – пока в этот мир не проникло еще что-нибудь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','С помощью заряженного ловца снов закройте 5 чародейских тессерактов в Мазториле.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мазторил не скоро возродится... но он возродится.$B$BСиние драконы будут жить!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хале в Берилловый Удел, что в Зимних Ключах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (28842,'Избавление Умбранса','В глубине Мазторила бродит Умбранс. Его время пришло.$B$BК сожалению, я не смогу пойти с тобой. Мне очень хочется проучить эту змею, но магия Мазторила сейчас так сильна, что разорвет меня на части, как только я ступлю на эту землю. Нет, покончить с ним придется тебе.$B$BКогда все сделаешь, воспользуйся этим амулетом. Он вернет тебя к выходу.','Убейте Умбранса Ищущего Духов.','Вернитесь к Хале в Берилловый Удел, что в Зимних Ключах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Избавление Умбранса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В глубине Мазторила бродит Умбранс. Его время пришло.$B$BК сожалению, я не смогу пойти с тобой. Мне очень хочется проучить эту змею, но магия Мазторила сейчас так сильна, что разорвет меня на части, как только я ступлю на эту землю. Нет, покончить с ним придется тебе.$B$BКогда все сделаешь, воспользуйся этим амулетом. Он вернет тебя к выходу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Умбранса Ищущего Духов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хале в Берилловый Удел, что в Зимних Ключах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertargetname_loc8`) VALUES (28843,'Грехи морской ведьмы','Наз\'жар! Это она в ответе за все, что здесь произошло.$B$BОна где-то здесь. И сейчас наверняка обессилена после сражения с Нептулоном.$B$BТак что самое время нанести удар! Другого шанса может и не быть.$B$BЯ останусь здесь и прослежу, чтобы никто не пришел к ней на помощь с этой стороны.$B$BА ты разыщи ее, $n. Разыщи и убей!','По приказу легионера Назгрима убейте Леди Наз\'жар.','Поговорите с легионером Назгримом у Трона Приливов.','Леди Наз\'жар') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Грехи морской ведьмы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наз\'жар! Это она в ответе за все, что здесь произошло.$B$BОна где-то здесь. И сейчас наверняка обессилена после сражения с Нептулоном.$B$BТак что самое время нанести удар! Другого шанса может и не быть.$B$BЯ останусь здесь и прослежу, чтобы никто не пришел к ней на помощь с этой стороны.$B$BА ты разыщи ее, $n. Разыщи и убей!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По приказу легионера Назгрима убейте Леди Наз\'жар.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с легионером Назгримом у Трона Приливов.',`completedtext_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Леди Наз\'жар',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (28843,'Адский Крик обязательно узнает о твоих подвигах, Рунаак.$B$BБез тебя нам пришлось бы туговато.$B$BЛок\'тар огар, друг мой!') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Адский Крик обязательно узнает о твоих подвигах, Рунаак.$B$BБез тебя нам пришлось бы туговато.$B$BЛок\'тар огар, друг мой!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (28844,'Охота на гиен','Смотри, $n!$B$BЯ взял приманку, что ты мне $gпринес:принесла;, и сделал ловушки. Они тебе пригодятся для следующего задания.$B$BДалеко на юге-востоке отсюда живет целая стая опасных кровавых гиен.$B$BЯ нисколечко не сомневаюсь, что даже этих свирепых зверюг можно укротить, приручить и выдрессировать для нашего представления.$B$BТебе нужно поставить ловушку поближе к гиенам, и они непременно в нее попадутся. Ни одна гиена не устоит против такой приманки!$B$BА когда они попадутся, тебе всего-то и нужно, что привести их сюда.$B$BУ тебя все получится! План отработанный. Всегда получается! Ну... то есть почти всегда.','С помощью ловушки для гиен, сделанной Суллой, поймайте 5 кровавых гиен.','Поговорите с Суллой в цирке Суллы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота на гиен',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Смотри, $n!$B$BЯ взял приманку, что ты мне $gпринес:принесла;, и сделал ловушки. Они тебе пригодятся для следующего задания.$B$BДалеко на юге-востоке отсюда живет целая стая опасных кровавых гиен.$B$BЯ нисколечко не сомневаюсь, что даже этих свирепых зверюг можно укротить, приручить и выдрессировать для нашего представления.$B$BТебе нужно поставить ловушку поближе к гиенам, и они непременно в нее попадутся. Ни одна гиена не устоит против такой приманки!$B$BА когда они попадутся, тебе всего-то и нужно, что привести их сюда.$B$BУ тебя все получится! План отработанный. Всегда получается! Ну... то есть почти всегда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','С помощью ловушки для гиен, сделанной Суллой, поймайте 5 кровавых гиен.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Суллой в цирке Суллы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (28845,'Вершина Смерча','Один из наших вождей ополчения захвачен воздушными элементалями.$B$BСейчас они наверняка выпытывают у него сведения.$B$BОтправляйся в Вершину Смерча, где обитают эти мерзкие твари, и разыщи Итеша.$B$BВход в Вершину Смерча нависает над юго-восточным побережьем Ульдума.','Разыщите Итеша в Вершине Смерча.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вершина Смерча',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Один из наших вождей ополчения захвачен воздушными элементалями.$B$BСейчас они наверняка выпытывают у него сведения.$B$BОтправляйся в Вершину Смерча, где обитают эти мерзкие твари, и разыщи Итеша.$B$BВход в Вершину Смерча нависает над юго-восточным побережьем Ульдума.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите Итеша в Вершине Смерча.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (28846,'Repel the Paratroopers Accepted Tracking Event') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Repel the Paratroopers Accepted Tracking Event',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (28847,'По пятам Умбранса','Мы вычислили, где в Зимних Ключах скрывается Умбранс. Там, где я и предполагал.$B$BОн в Мазториле, пещере на юго-западе, которая некогда принадлежала роду синих драконов. Моя мать Хале встретит тебя там. Она расположилась возле входа в пещеру в небольшом лагере с другими беженцами.$B$BСледуй на огонь их костра.','Обратитесь к Хале в Берилловом Уделе, что в Зимних Ключах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','По пятам Умбранса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы вычислили, где в Зимних Ключах скрывается Умбранс. Там, где я и предполагал.$B$BОн в Мазториле, пещере на юго-западе, которая некогда принадлежала роду синих драконов. Моя мать Хале встретит тебя там. Она расположилась возле входа в пещеру в небольшом лагере с другими беженцами.$B$BСледуй на огонь их костра.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обратитесь к Хале в Берилловом Уделе, что в Зимних Ключах.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (28848,'По следу Ищущего Духов','Мне рассказывали про Умбранса, но видеть его не доводилось. По слухам, он собирает магические артефакты, однако с какой целью – неизвестно. $B$BПохоже, стоит сообщить об этом верному союзнику. В Круговзоре, большом городе гоблинов на северо-востоке, живет высший эльф по имени Нимн. Расскажи ему все, что мы узнали сегодня.','Поговорите с Нимном в Зимних Ключах, в Круговзоре.','Умбранс... Понятно. Я предупрежу об этом свой народ.$B$BЕсли ты нам понадобишься, мы тебе сообщим.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','По следу Ищущего Духов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне рассказывали про Умбранса, но видеть его не доводилось. По слухам, он собирает магические артефакты, однако с какой целью – неизвестно. $B$BПохоже, стоит сообщить об этом верному союзнику. В Круговзоре, большом городе гоблинов на северо-востоке, живет высший эльф по имени Нимн. Расскажи ему все, что мы узнали сегодня.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Нимном в Зимних Ключах, в Круговзоре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Умбранс... Понятно. Я предупрежу об этом свой народ.$B$BЕсли ты нам понадобишься, мы тебе сообщим.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (28849,'Сумеречные небеса','Из Оргриммара только что доложили: вождь приказывает нам выступать. Если бы не твоя помощь, мы сейчас были бы к этому совсем не готовы!$B$BПлан таков: сперва отправляется военно-воздушный флот, а сразу следом за ним – военно-морской. Адский Крик летит с воздушными войсками и передал тебе персональное приглашение присоединиться.$B$BВремя не ждет! Отправляйся на южную конечную станцию ракетной дороги в Азшаре и доложи Фризу Штопору. А я подведу дирижабль, и мы тебя подхватим.','Доложите Фризу Штопору на южной конечной станции ракетной дороги в Азшаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сумеречные небеса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Из Оргриммара только что доложили: вождь приказывает нам выступать. Если бы не твоя помощь, мы сейчас были бы к этому совсем не готовы!$B$BПлан таков: сперва отправляется военно-воздушный флот, а сразу следом за ним – военно-морской. Адский Крик летит с воздушными войсками и передал тебе персональное приглашение присоединиться.$B$BВремя не ждет! Отправляйся на южную конечную станцию ракетной дороги в Азшаре и доложи Фризу Штопору. А я подведу дирижабль, и мы тебя подхватим.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доложите Фризу Штопору на южной конечной станции ракетной дороги в Азшаре.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (28850,'На крыше тюрьмы','Не знаю, почему король тратит свое драгоценное время ради спасения его шкуры, но если ты хочешь рискнуть жизнью – твое дело, не стану мешать.$B$BКраули и его люди сидят наверху, строят заговоры против его величества.','Поговорите с лордом Дарием Краули на верхней террасе Каменной тюрьмы Гилнеаса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На крыше тюрьмы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не знаю, почему король тратит свое драгоценное время ради спасения его шкуры, но если ты хочешь рискнуть жизнью – твое дело, не стану мешать.$B$BКраули и его люди сидят наверху, строят заговоры против его величества.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с лордом Дарием Краули на верхней террасе Каменной тюрьмы Гилнеаса.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (28851,'Цирк Суллы','Рад тебя видеть, $gдружище:дружочек;!$B$BМы хорошо потрудились, и теперь можно уже пожинать, так сказать, плоды трудов! Но сперва – генеральная репетиция!$B$BКстати, прежде чем мы начнем... у меня к тебе маленькое, но ответственное поручение.$B$BУ нас тут вышла накладка с одним упрямым пигмеем, и я вдруг подумал... А, может, ты его заменишь?$B$BУ тебя все получится, вот увидишь. Ты – $gприрожденный артист:прирожденная артистка;!$B$BНу что, $gсогласен:согласна;? Тогда ни пуха, ни пера!','Поговорите с Суллой в цирке Суллы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Цирк Суллы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Рад тебя видеть, $gдружище:дружочек;!$B$BМы хорошо потрудились, и теперь можно уже пожинать, так сказать, плоды трудов! Но сперва – генеральная репетиция!$B$BКстати, прежде чем мы начнем... у меня к тебе маленькое, но ответственное поручение.$B$BУ нас тут вышла накладка с одним упрямым пигмеем, и я вдруг подумал... А, может, ты его заменишь?$B$BУ тебя все получится, вот увидишь. Ты – $gприрожденный артист:прирожденная артистка;!$B$BНу что, $gсогласен:согласна;? Тогда ни пуха, ни пера!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Суллой в цирке Суллы.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28852,'Ослабить противника','Наконец-то прибыло подкрепление! Кто бы мог подумать, что сектанты Сумеречного Молота способны дать такой отпор! Кроме того, враг оказался гораздо многочисленнее, чем мы полагали!$B$BНескольких наших драконов пленили внутри главного зала. Прошу тебя, разбей их оковы и освободи их!$B$BОсвободившись, драконы помогут нам выжечь врага из этих залов. Просто взберись на спину красного дракона и укажи ему цель для атаки. Думаю, тебе захочется основательно потрепать силы противника перед тем, как спуститься глубже.','Освободите красного дракона, плененного в Грим Батоле, и воспользуйтесь им, чтобы расправиться с 30 троггами и 15 адептами культа Сумеречного Молота.','Чудесные новости, Дюцепс! Рада, что наши драконы смогли тебе помочь. Благодарю тебя за их спасение из пут сектантов Сумеречного Молота.','Вернитесь к Веластразе, находящейся на входе в Грим Батол.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ослабить противника',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наконец-то прибыло подкрепление! Кто бы мог подумать, что сектанты Сумеречного Молота способны дать такой отпор! Кроме того, враг оказался гораздо многочисленнее, чем мы полагали!$B$BНескольких наших драконов пленили внутри главного зала. Прошу тебя, разбей их оковы и освободи их!$B$BОсвободившись, драконы помогут нам выжечь врага из этих залов. Просто взберись на спину красного дракона и укажи ему цель для атаки. Думаю, тебе захочется основательно потрепать силы противника перед тем, как спуститься глубже.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Освободите красного дракона, плененного в Грим Батоле, и воспользуйтесь им, чтобы расправиться с 30 троггами и 15 адептами культа Сумеречного Молота.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Чудесные новости, Дюцепс! Рада, что наши драконы смогли тебе помочь. Благодарю тебя за их спасение из пут сектантов Сумеречного Молота.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Веластразе, находящейся на входе в Грим Батол.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (28853,'Устранение гонца','Спасибо за то, что $gвызвался:вызвалась; помочь нам справиться с ужасами, терзающими это мрачное место, |3-6($c).$B$BВ недрах Грим Батола сокрыт командный центр всеми военными операциями Чо\'Галла.$B$BОтыщи там Драгха Горячего Мрака. Это гонец Чо\'галла, связующее звено между Грим Батолом и Сумеречным бастионом. Нужно выведать, что за тайны он скрывает.','Убейте Драгха Горячего Мрака и заберите у него послание Чо\'Галлу.','<Тоорану просматривает принесенные вами документы>.$B$BТут все, Даргимн. Сведения о том, как культ разрушает нагорье, имена агентов, их местонахождение и планы. Эта информация просто бесценна.$B$BЯ незамедлительно передам эти сведения другим Служителям Земли. Спасибо тебе, друг.','Отнесите послание предсказателю Тоорану, находящемуся на входе в Грим Батол.','Это глаза и уши Чо\'Галла в Грим Батоле. Нужно выведать его секреты.','Драгх Горячий Мрак') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Устранение гонца',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Спасибо за то, что $gвызвался:вызвалась; помочь нам справиться с ужасами, терзающими это мрачное место, |3-6($c).$B$BВ недрах Грим Батола сокрыт командный центр всеми военными операциями Чо\'Галла.$B$BОтыщи там Драгха Горячего Мрака. Это гонец Чо\'галла, связующее звено между Грим Батолом и Сумеречным бастионом. Нужно выведать, что за тайны он скрывает.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Драгха Горячего Мрака и заберите у него послание Чо\'Галлу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Тоорану просматривает принесенные вами документы>.$B$BТут все, Даргимн. Сведения о том, как культ разрушает нагорье, имена агентов, их местонахождение и планы. Эта информация просто бесценна.$B$BЯ незамедлительно передам эти сведения другим Служителям Земли. Спасибо тебе, друг.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите послание предсказателю Тоорану, находящемуся на входе в Грим Батол.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Это глаза и уши Чо\'Галла в Грим Батоле. Нужно выведать его секреты.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Драгх Горячий Мрак',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (28854,'Конец кошмара','Это ужасное место было кошмаром Алекстразы. В эпоху, которую смертные называют Второй войной, она была закована в кандалы глубоко в недрах земли, в то время как ее потомство было вынуждено служить мучителям из оскверненной демонами Орды.$B$BПусть Алекстраза ныне свободна, но чудовище по имени Эрудакс все еще вредит ее потомству, находящемуся внизу.$B$B<Тело Пламегона напряжено от гнева.>$B$BУничтожь его, |3-6($c). Расправься с ним, чтобы мы наконец-то забыли свои кошмары!','Убейте властителя недр Эрудакса.','Наконец-то.$B$BЯ был готов уничтожить эту гору ради нашей цели.','Вернитесь к Пламегону, находящемуся на входе в Грим Батол.','Он бродит в глубинах Грим Батола, творя свои темные дела.','Властитель недр Эрудакс') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Конец кошмара',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это ужасное место было кошмаром Алекстразы. В эпоху, которую смертные называют Второй войной, она была закована в кандалы глубоко в недрах земли, в то время как ее потомство было вынуждено служить мучителям из оскверненной демонами Орды.$B$BПусть Алекстраза ныне свободна, но чудовище по имени Эрудакс все еще вредит ее потомству, находящемуся внизу.$B$B<Тело Пламегона напряжено от гнева.>$B$BУничтожь его, |3-6($c). Расправься с ним, чтобы мы наконец-то забыли свои кошмары!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте властителя недр Эрудакса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Наконец-то.$B$BЯ был готов уничтожить эту гору ради нашей цели.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Пламегону, находящемуся на входе в Грим Батол.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Он бродит в глубинах Грим Батола, творя свои темные дела.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Властитель недр Эрудакс',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (28855,'Northern Stranglethorn 4.x: PRK - E - Just Hatched FLAG') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Northern Stranglethorn 4.x: PRK - E - Just Hatched FLAG',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (28857,'Выжженные земли: на другом краю света','Гарнизон Крепости Стражей Пустоты десятилетиями давал отпор набегам Орды. Мы не сдадимся перед лицом врага и сейчас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Выжженные земли: на другом краю света',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Гарнизон Крепости Стражей Пустоты десятилетиями давал отпор набегам Орды. Мы не сдадимся перед лицом врага и сейчас.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (28858,'Выжженные земли: на другом краю света','Вот это интересно. Здесь говорится о том, что подданные Орды должны явиться в форт Молота Ужаса и поговорить с Окриллой.$B$BХм! Я даже не знала, что форт Молота Ужаса находится в руках Орды!$B$BДумаю, этой Окрилле нужна помощь в борьбе с ограми и Альянсом. Надо полагать, у нее и так хлопот полон рот с тамошними демонами!$B$BЛучший способ попасть в форт Молота Ужаса – это пересечь Великое море, а затем идти по дороге на юг от Болота Печали.$B$BНу что, возьмешься за это дело?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Выжженные земли: на другом краю света',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот это интересно. Здесь говорится о том, что подданные Орды должны явиться в форт Молота Ужаса и поговорить с Окриллой.$B$BХм! Я даже не знала, что форт Молота Ужаса находится в руках Орды!$B$BДумаю, этой Окрилле нужна помощь в борьбе с ограми и Альянсом. Надо полагать, у нее и так хлопот полон рот с тамошними демонами!$B$BЛучший способ попасть в форт Молота Ужаса – это пересечь Великое море, а затем идти по дороге на юг от Болота Печали.$B$BНу что, возьмешься за это дело?',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (28859,'Дюны Силитуса','Сообщите о своем прибытии призывательнице ветров Гордый Рог в Крепости Кенария, что в Силитусе.','Добро пожаловать в Крепость Кенария, путник.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дюны Силитуса',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сообщите о своем прибытии призывательнице ветров Гордый Рог в Крепости Кенария, что в Силитусе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Добро пожаловать в Крепость Кенария, путник.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28860,'Захлопни Драконью Пасть','Молодчина, так держать! Когда герои вроде тебя берутся за дело, меня исполняет гордость оттого, что я состою в Альянсе.','Отнесите знаки различия Колину Громтару к Громтару, что на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Захлопни Драконью Пасть',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Молодчина, так держать! Когда герои вроде тебя берутся за дело, меня исполняет гордость оттого, что я состою в Альянсе.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите знаки различия Колину Громтару к Громтару, что на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (28861,'Боевой эль','Отправляйтесь в руины Громтара и принесите 10 бочонков эля. И не вздумайте пробовать этот эль – с непривычки он валит с ног с двух глотков!','Ух ты ж, вот это улов!$B$BЭтого мне, пожалуй, хватит... до завтра точно.','Раздобыла чего-нибудь?','Отнесите эль младшему шаману Бланди к Громтару, что на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Боевой эль',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в руины Громтара и принесите 10 бочонков эля. И не вздумайте пробовать этот эль – с непривычки он валит с ног с двух глотков!',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ух ты ж, вот это улов!$B$BЭтого мне, пожалуй, хватит... до завтра точно.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Раздобыла чего-нибудь?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите эль младшему шаману Бланди к Громтару, что на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28862,'Вылазка за продовольствием','Потоки беженцев с фронта все стекаются и стекаются в Громтар, а я есть хочу! В смысле, они хотят... ну, беженцы... голодные, понимаешь.$B$BРаздобудь-ка чего-нибудь пожевать в руинах Громтара! Прочеши руины на юге, востоке и юго-западе – вдруг уцелели какие-нибудь припасы. В особенности дюжие окорока. Обожаю! То есть беженцы любят ветчину.$B$BДа посмотри, не попадется ли там чуток коктейльных сосисок!','Соберите 10 единиц съестных припасов Громового Молота в руинах Громтара.','Чудненько, ты поспела вовремя! Я как раз нагулял зверский аппетит... пока думал, чем же накормить наших горемычных беженцев. Да-да, так и было.','Принесите еду младшему шаману Бланди к Громтару, что на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вылазка за продовольствием',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Потоки беженцев с фронта все стекаются и стекаются в Громтар, а я есть хочу! В смысле, они хотят... ну, беженцы... голодные, понимаешь.$B$BРаздобудь-ка чего-нибудь пожевать в руинах Громтара! Прочеши руины на юге, востоке и юго-западе – вдруг уцелели какие-нибудь припасы. В особенности дюжие окорока. Обожаю! То есть беженцы любят ветчину.$B$BДа посмотри, не попадется ли там чуток коктейльных сосисок!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 единиц съестных припасов Громового Молота в руинах Громтара.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Чудненько, ты поспела вовремя! Я как раз нагулял зверский аппетит... пока думал, чем же накормить наших горемычных беженцев. Да-да, так и было.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите еду младшему шаману Бланди к Громтару, что на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (28863,'Полководец Халтар вернулся','Он снова взялся за свое, $n. Полководец Халтар... гроза графства. Его верхом на драконе видели на юге, среди руин Громтара.$B$BУбей Халтара, $n! Мы отправим передовых бойцов тебе на подмогу, когда ты вступишь в бой.','Убейте полководца Халтара.','Печальная работенка, но сделана на славу. Спасибо, Мысль.','Вернитесь к Кро Макгро к Громтару, что на Сумеречном нагорье.','Он прямо неутомимый вихрь слюнобрызжущей ярости.','Полководец Халтар') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Полководец Халтар вернулся',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Он снова взялся за свое, $n. Полководец Халтар... гроза графства. Его верхом на драконе видели на юге, среди руин Громтара.$B$BУбей Халтара, $n! Мы отправим передовых бойцов тебе на подмогу, когда ты вступишь в бой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте полководца Халтара.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Печальная работенка, но сделана на славу. Спасибо, Мысль.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кро Макгро к Громтару, что на Сумеречном нагорье.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Он прямо неутомимый вихрь слюнобрызжущей ярости.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Полководец Халтар',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28864,'За пивком','Встретьте Молоторука на дороге к юго-востоку от горы Громового Удара и сопроводите караван в Кирт.','Вот и поди угадай... Никогда бы не подумал, что полюблю импортное пиво. Спасибо, Мысль!','Поговорите с Колином Громтаром в Громтаре на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','За пивком',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Встретьте Молоторука на дороге к юго-востоку от горы Громового Удара и сопроводите караван в Кирт.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот и поди угадай... Никогда бы не подумал, что полюблю импортное пиво. Спасибо, Мысль!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Колином Громтаром в Громтаре на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (28865,'Клич предводительницы','Силитус… бесполезный клочок земли. Удивительно, как великий катаклизм не разрушил его до основания!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Клич предводительницы',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Силитус… бесполезный клочок земли. Удивительно, как великий катаклизм не разрушил его до основания!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (28866,'В Каменные Недра','Говоришь, Миллхаус Манашторм и верховная жрица Азил должны встретиться в Каменных Недрах?$B$BЭто, наверное, чертовски важно. Нужно скорее следовать за ними. Нельзя допустить, чтобы Сумеречный Молот проворачивал свои темные делишки прямо у нас под носом.$B$BДоложи это Хранителю земли Изре в Каменных Недрах. Она обосновалась там, чтобы помешать Сумеречному Молоту напасть на Храм Земли, если те все же отважатся.','Обратитесь к Хранителю земли Изре в Каменных Недрах.','Как вовремя прислали подмогу.$B$BМиллхаус Манашторм? Похоже, он нужен нам обоим.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В Каменные Недра',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Говоришь, Миллхаус Манашторм и верховная жрица Азил должны встретиться в Каменных Недрах?$B$BЭто, наверное, чертовски важно. Нужно скорее следовать за ними. Нельзя допустить, чтобы Сумеречный Молот проворачивал свои темные делишки прямо у нас под носом.$B$BДоложи это Хранителю земли Изре в Каменных Недрах. Она обосновалась там, чтобы помешать Сумеречному Молоту напасть на Храм Земли, если те все же отважатся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обратитесь к Хранителю земли Изре в Каменных Недрах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Как вовремя прислали подмогу.$B$BМиллхаус Манашторм? Похоже, он нужен нам обоим.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (28867,'Стражи Пустоты взывают к тебе!','Стражи Пустоты взывают к тебе, |3-6($c)! Интендант Лунгерц направил меня сюда на поиски истинных героев Альянса, способных бороться с гнусными прихвостнями Окриллы из Орды! Помоги нам совладать с Ордой!$B$BЕсли есть на то желание, зайди в портал, открытый передо мной, чтобы попасть в Выжженные земли и поговори там с интендантом.','Силитус… бесполезный клочок земли. Удивительно, как великий катаклизм не разрушил его до основания!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Стражи Пустоты взывают к тебе!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Стражи Пустоты взывают к тебе, |3-6($c)! Интендант Лунгерц направил меня сюда на поиски истинных героев Альянса, способных бороться с гнусными прихвостнями Окриллы из Орды! Помоги нам совладать с Ордой!$B$BЕсли есть на то желание, зайди в портал, открытый передо мной, чтобы попасть в Выжженные земли и поговори там с интендантом.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Силитус… бесполезный клочок земли. Удивительно, как великий катаклизм не разрушил его до основания!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (28868,'Вид снизу','Мы должны помешать строительству, которое идет в этой деревне Мерзлогривов. Если мы позволим им как следует укрепить свои позиции, то потом будет трудно помешать им обосноваться здесь навсегда.$b$bПришло время познакомить этих мерзавцев с точкой зрения гномов! Возьми вот этот сжиматик и с его помощью сожми строителей Мерзлогривов до нашего размера. После этого они не смогут удержать в руках инструменты и строительство заглохнет.','Примените сжиматик к 5 строителям из племени Мерзлогривов в Укрытии Мерзлогривов.','Вернитесь к Снивеку Клинку в Укрытие Мерзлогривов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вид снизу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы должны помешать строительству, которое идет в этой деревне Мерзлогривов. Если мы позволим им как следует укрепить свои позиции, то потом будет трудно помешать им обосноваться здесь навсегда.$b$bПришло время познакомить этих мерзавцев с точкой зрения гномов! Возьми вот этот сжиматик и с его помощью сожми строителей Мерзлогривов до нашего размера. После этого они не смогут удержать в руках инструменты и строительство заглохнет.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Примените сжиматик к 5 строителям из племени Мерзлогривов в Укрытии Мерзлогривов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Снивеку Клинку в Укрытие Мерзлогривов.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (28869,'Камешек','Если ты еще не $gзаметил:заметила;, ты $gпонравился:понравилась; одному очень маленькому элементалю. Если ты постоишь спокойно несколько минут, то наверняка увидишь его.$b$bПохоже, у тебя хорошо получается заводить новых друзей. Это замечательное качество.','Поговорите с Камешком в Дрожащих Вершинах. Если вы некоторое время постоите неподвижно, он выйдет из укрытия и сам подойдет к вам.','<Кажется, Камешек очень рад встретить вас.>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Камешек',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если ты еще не $gзаметил:заметила;, ты $gпонравился:понравилась; одному очень маленькому элементалю. Если ты постоишь спокойно несколько минут, то наверняка увидишь его.$b$bПохоже, у тебя хорошо получается заводить новых друзей. Это замечательное качество.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Камешком в Дрожащих Вершинах. Если вы некоторое время постоите неподвижно, он выйдет из укрытия и сам подойдет к вам.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Кажется, Камешек очень рад встретить вас.>',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (28870,'Возвращение в затерянный город','Нам удалось захватить город Неферсет, но у противника остался еще один оплот.$B$BБлагодаря Сиамату, могущественному джинну южного ветра, жители Неферсета стали гораздо опаснее.$B$BМы только что узнали, что остатки разведотряда принца Надуна пробились ко входу в Затерянный город Тол\'вир.$B$BРазыщи капитана Хадана и узнай у него всю необходимую информацию, чтобы расправиться с Сиаматом и его приверженцами из Неферсета.','Обратитесь к капитану Хадану в Затерянном городе Тол\'вире.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение в затерянный город',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нам удалось захватить город Неферсет, но у противника остался еще один оплот.$B$BБлагодаря Сиамату, могущественному джинну южного ветра, жители Неферсета стали гораздо опаснее.$B$BМы только что узнали, что остатки разведотряда принца Надуна пробились ко входу в Затерянный город Тол\'вир.$B$BРазыщи капитана Хадана и узнай у него всю необходимую информацию, чтобы расправиться с Сиаматом и его приверженцами из Неферсета.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обратитесь к капитану Хадану в Затерянном городе Тол\'вире.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (28871,'Сокрушение Громового Молота','Отправляйтесь в руины Громтара, убейте нескольких передовых бойцов Громового Молота и соберите 8 знаков Громового Молота. Персонажи, у которых есть имена, тоже носят знаки различия.','Отнесите знаки различия Громового Молота Малкару в Кровавое ущелье на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сокрушение Громового Молота',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в руины Громтара, убейте нескольких передовых бойцов Громового Молота и соберите 8 знаков Громового Молота. Персонажи, у которых есть имена, тоже носят знаки различия.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите знаки различия Громового Молота Малкару в Кровавое ущелье на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) VALUES (28871,'Ну, показывай, сколько знаков различия ты набрал, $C.') ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, показывай, сколько знаков различия ты набрал, $C.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (28873,'Еще один голодный рот','<У Гриффа урчит в животе.>$B$BВсе еще зверски голоден. И вот так каждый день: жрать хочу – спасу нет...$B$BСлыхал я, на руинах Громтара остались еще съестные припасы. Это на севере, на другом берегу реки, где сейчас идут бои. Принеси чего-нибудь перекусить, сделай милость.','Соберите 10 единиц съестных припасов Громового Молота в руинах Громтара.','<Грифф жадно набрасывается на гору еды, которой хватило бы паре десятков дюжих молодцев.>$B$BТак-то лучше! Теперь перекантуюсь... пару часиков.','<Грифф жадно облизывает губы.>','Отнесите еду Гриффу в Кровавое ущелье на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Еще один голодный рот',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<У Гриффа урчит в животе.>$B$BВсе еще зверски голоден. И вот так каждый день: жрать хочу – спасу нет...$B$BСлыхал я, на руинах Громтара остались еще съестные припасы. Это на севере, на другом берегу реки, где сейчас идут бои. Принеси чего-нибудь перекусить, сделай милость.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 единиц съестных припасов Громового Молота в руинах Громтара.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Грифф жадно набрасывается на гору еды, которой хватило бы паре десятков дюжих молодцев.>$B$BТак-то лучше! Теперь перекантуюсь... пару часиков.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Грифф жадно облизывает губы.>',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите еду Гриффу в Кровавое ущелье на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (28874,'На крючке','Вернитесь к Харккану в Кровавое ущелье на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На крючке',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Харккану в Кровавое ущелье на Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (28875,'Смерть верховному шаману','Убейте верховного шамана Маккиллигана.','Верховный шаман повержен! Из Громтара, несомненно, пришлют новых сильных бойцов, но сегодня Драконья Пасть празднует победу.','Вернитесь к Гроту Смертельному Выпаду в Кровавое ущелье на Сумеречном нагорье.','Мы не позволим ему и дальше убивать!','Верховный шаман Маккиллиган') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Смерть верховному шаману',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте верховного шамана Маккиллигана.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Верховный шаман повержен! Из Громтара, несомненно, пришлют новых сильных бойцов, но сегодня Драконья Пасть празднует победу.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гроту Смертельному Выпаду в Кровавое ущелье на Сумеречном нагорье.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Мы не позволим ему и дальше убивать!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Верховный шаман Маккиллиган',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (28876,'На заставу Мор\'шан') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На заставу Мор\'шан',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (28877,'Его называют Быстрый Нож. Он убивает гарпий.','К западу отсюда живет один орк. На самой границе территории, изуродованной катаклизмом.$b$bЕго называют Быстрый Нож, $n. Зовут его так потому, что... что... вообще я думаю, что это и есть его имя.$b$b<Котельник пожимает плечами.>$b$bВ общем, он – это машина по уничтожению гарпий. Он убивает гарпий. Он обожает это. Это его жизнь. Иди и посмотри на него! Посмотри, как это делается. Воплоти в жизнь мечту. Может, даже сделаешь на этом карьеру.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Его называют Быстрый Нож. Он убивает гарпий.',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','К западу отсюда живет один орк. На самой границе территории, изуродованной катаклизмом.$b$bЕго называют Быстрый Нож, $n. Зовут его так потому, что... что... вообще я думаю, что это и есть его имя.$b$b<Котельник пожимает плечами.>$b$bВ общем, он – это машина по уничтожению гарпий. Он убивает гарпий. Он обожает это. Это его жизнь. Иди и посмотри на него! Посмотри, как это делается. Воплоти в жизнь мечту. Может, даже сделаешь на этом карьеру.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (28878,'Подарок к Зимнему Покрову') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подарок к Зимнему Покрову',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (28879,'Возвращение в приют','Нам было весело с тобой, $n. Жаль, что ты не можешь стать $gнашим папочкой:нашей мамочкой;, и нам пора возвращаться к попечительнице сирот Арии в Даларан.$B$BМожет быть, ты еще навестишь нас как-нибудь? Нам очень понравилось общаться с малышами Зимних Плавников и с королевой драконов. И никто нам не поверит, что мы видели одного из Великих!$B$BМы будем скучать по тебе, $n. Обещаем, мы будем тебе писать!','Отведите вашего подопечного обратно в приют Даларана, отдав детскую свистульку оракула попечительнице сирот Арии.','Вернитесь к попечительнице сирот Арии в Даларан.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение в приют',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нам было весело с тобой, $n. Жаль, что ты не можешь стать $gнашим папочкой:нашей мамочкой;, и нам пора возвращаться к попечительнице сирот Арии в Даларан.$B$BМожет быть, ты еще навестишь нас как-нибудь? Нам очень понравилось общаться с малышами Зимних Плавников и с королевой драконов. И никто нам не поверит, что мы видели одного из Великих!$B$BМы будем скучать по тебе, $n. Обещаем, мы будем тебе писать!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отведите вашего подопечного обратно в приют Даларана, отдав детскую свистульку оракула попечительнице сирот Арии.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к попечительнице сирот Арии в Даларан.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (28880,'Возвращение в приют','Знаешь, а мы не так уж и плохо провели время вместе, $n. Ты $gпоказал:показала; Кекеку много всяких интересных мест. Кекек нашел новых друзей и сделал много всего такого, что не снилось другим щенкам.$B$BТеперь мы друзья – Кекек, ты, Хеминг Эрнестуэй и щенки Поляны Снегопада. Может быть, ты когда-нибудь принесешь Кекеку книгу про зеленые холмы? А Кекек обещает написать тебе как-нибудь и рассказать, как идут дела. Может быть, Кекек даже не будет больше дразнить длинноязыких детей.$B$BА теперь Кекеку пора возвращаться к попечительнице Арии, в фиолетовый город людей.','Отведите вашего подопечного обратно в приют Даларана, отдав детскую свистульку волчера попечительнице сирот Арии.','Вернитесь к попечительнице сирот Арии в Даларан.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение в приют',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Знаешь, а мы не так уж и плохо провели время вместе, $n. Ты $gпоказал:показала; Кекеку много всяких интересных мест. Кекек нашел новых друзей и сделал много всего такого, что не снилось другим щенкам.$B$BТеперь мы друзья – Кекек, ты, Хеминг Эрнестуэй и щенки Поляны Снегопада. Может быть, ты когда-нибудь принесешь Кекеку книгу про зеленые холмы? А Кекек обещает написать тебе как-нибудь и рассказать, как идут дела. Может быть, Кекек даже не будет больше дразнить длинноязыких детей.$B$BА теперь Кекеку пора возвращаться к попечительнице Арии, в фиолетовый город людей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отведите вашего подопечного обратно в приют Даларана, отдав детскую свистульку волчера попечительнице сирот Арии.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к попечительнице сирот Арии в Даларан.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (28881,'Геолог Ганстен','Отчитайтесь геологу Ганстену в Руинах Южной Луны, что в Танарисе.','Ты прибыл нам на помощь?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Геолог Ганстен',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отчитайтесь геологу Ганстену в Руинах Южной Луны, что в Танарисе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты прибыл нам на помощь?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (28882,'Победа на Тол Бараде','Мы долго сражались, чтобы закрепиться на этом проклятом острове, поэтому не допустим, чтобы Орда вмешалась в наши планы. Контроль над Тол Барадом имеет первостепенное значение для Альянса, $n. Нам нужна твоя помощь! Одержи победу на Тол Бараде и вернись сюда, чтобы сообщить мне эту радостную весть.','Выиграйте битву за Тол Барад и вернитесь к майору Марсдену в Лагерь Барадин на полуостров Тол Барад.','Чем это пахнет? Ах, это запах победы! Твои подвиги на Тол Бараде принесли победу всему Альянсу! Мы не забудем о твоих заслугах.','Победа на Тол Бараде','Вернитесь к майору Марсдену на полуостров Тол Барад.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Победа на Тол Бараде',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы долго сражались, чтобы закрепиться на этом проклятом острове, поэтому не допустим, чтобы Орда вмешалась в наши планы. Контроль над Тол Барадом имеет первостепенное значение для Альянса, $n. Нам нужна твоя помощь! Одержи победу на Тол Бараде и вернись сюда, чтобы сообщить мне эту радостную весть.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выиграйте битву за Тол Барад и вернитесь к майору Марсдену в Лагерь Барадин на полуостров Тол Барад.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Чем это пахнет? Ах, это запах победы! Твои подвиги на Тол Бараде принесли победу всему Альянсу! Мы не забудем о твоих заслугах.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Победа на Тол Бараде',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к майору Марсдену на полуостров Тол Барад.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (28884,'Победа на Тол Бараде','Контроль над Тол Барадом имеет ключевое значение в реализации нашей военной кампании в Восточных королевствах, |3-6($r). Требуется сделать все возможное, чтобы отвадить Альянс от этого острова, поэтому нам нужна твоя помощь. Задействуй любые средства, чтобы разгромить врага на Тол Бараде, а затем явись ко мне с вестью о победе.','Выиграйте битву за Тол Барад и вернитесь к полковнику Карзагу в Хватку Адского Крика на полуостров Тол Барад.','Как я и ожидал, ты явился с радостной вестью! Всякий раз, как мы тесним врага на Тол Бараде, мы приближаем день окончательной победы Орды. Будь уверен, ты получишь заслуженное вознаграждение за свои подвиги.','Победа на Тол Бараде','Вернитесь к полковнику Карзагу на полуостров Тол Барад.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Победа на Тол Бараде',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Контроль над Тол Барадом имеет ключевое значение в реализации нашей военной кампании в Восточных королевствах, |3-6($r). Требуется сделать все возможное, чтобы отвадить Альянс от этого острова, поэтому нам нужна твоя помощь. Задействуй любые средства, чтобы разгромить врага на Тол Бараде, а затем явись ко мне с вестью о победе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выиграйте битву за Тол Барад и вернитесь к полковнику Карзагу в Хватку Адского Крика на полуостров Тол Барад.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Как я и ожидал, ты явился с радостной вестью! Всякий раз, как мы тесним врага на Тол Бараде, мы приближаем день окончательной победы Орды. Будь уверен, ты получишь заслуженное вознаграждение за свои подвиги.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Победа на Тол Бараде',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к полковнику Карзагу на полуостров Тол Барад.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (28885,'Прокатимся с ветерком','Значит, так, $n. Нам надо добраться до портала земли в самом дальнем конце пещеры.$B$BЯ сделал умно – "раздобыл" транспорт. Зачем трудить ноги, когда можно проехаться с ветерком? Надеюсь, твоя религия не запрещает кататься на шахтерских вагонетках?$B$BВ общем, как будешь $gготов:готова;, скажи – и поедем.','Вместе с посвященным Клондацком прокатитесь на вагонетке до конца маршрута.','О, нет! Мое оружие и тотемы!$B$BОни уничтожены!!!','Поговорите с посвященным Клондацком в Элементиевых глубинах, что на Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прокатимся с ветерком',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Значит, так, $n. Нам надо добраться до портала земли в самом дальнем конце пещеры.$B$BЯ сделал умно – "раздобыл" транспорт. Зачем трудить ноги, когда можно проехаться с ветерком? Надеюсь, твоя религия не запрещает кататься на шахтерских вагонетках?$B$BВ общем, как будешь $gготов:готова;, скажи – и поедем.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вместе с посвященным Клондацком прокатитесь на вагонетке до конца маршрута.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, нет! Мое оружие и тотемы!$B$BОни уничтожены!!!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с посвященным Клондацком в Элементиевых глубинах, что на Сумеречном нагорье.',`completedtext_loc8`);
