INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (28889,'Arcane Instructions tracking Quest') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Arcane Instructions tracking Quest',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (28890,'Пустошь','Это Силитус, |3-6($c)... суровый пустынный край. Немногие помнят, что там в древности развернулась война между ночными эльфами и злобной, чужеродной силой. Зло было повержено и заключено в оковы, но мы подозреваем, что сейчас некие силы хотят пробудить этот... невыразимый ужас.$B$BНайди Лайо Звездного Всполоха, одного из наших разведчиков в Силитусе. Ищи его на юго-востоке, куда я отправил его, чтобы исследовать руины деревни Южного Ветра.$B$BПередай ему это письмо, и он доверится тебе.','Доставьте письмо Рабина Лайо Звездному Всполоху, находящемуся у деревни Южного Ветра.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пустошь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это Силитус, |3-6($c)... суровый пустынный край. Немногие помнят, что там в древности развернулась война между ночными эльфами и злобной, чужеродной силой. Зло было повержено и заключено в оковы, но мы подозреваем, что сейчас некие силы хотят пробудить этот... невыразимый ужас.$B$BНайди Лайо Звездного Всполоха, одного из наших разведчиков в Силитусе. Ищи его на юго-востоке, куда я отправил его, чтобы исследовать руины деревни Южного Ветра.$B$BПередай ему это письмо, и он доверится тебе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте письмо Рабина Лайо Звездному Всполоху, находящемуся у деревни Южного Ветра.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (28891,'Духи Южного Ветра','На юго-западе находится очень грустное место – деревня Южного Ветра. Именно с нее мы и начнем, $n.$B$BСудя по всему, некогда она была базой ночных эльфов для военных действий в Силитусе. Ее давным-давно захватили силитиды. Страшно представить, что там творилось в момент захвата...$B$BПо руинам бесцельно бродят духи павших друидов и стражниц. Исследуй эти края и освободи страдающие души, как подобает.','Освободите души 8 истерзанных друидов и 8 истерзанных часовых в деревне Южного Ветра.','Вернитесь к Лайо Звездному Всполоху в деревню Южного Ветра, что в Силитусе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Духи Южного Ветра',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На юго-западе находится очень грустное место – деревня Южного Ветра. Именно с нее мы и начнем, $n.$B$BСудя по всему, некогда она была базой ночных эльфов для военных действий в Силитусе. Ее давным-давно захватили силитиды. Страшно представить, что там творилось в момент захвата...$B$BПо руинам бесцельно бродят духи павших друидов и стражниц. Исследуй эти края и освободи страдающие души, как подобает.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Освободите души 8 истерзанных друидов и 8 истерзанных часовых в деревне Южного Ветра.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лайо Звездному Всполоху в деревню Южного Ветра, что в Силитусе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (28892,'Улей в башне','Пора заняться ульем в деревне Южного Ветра, и мне кажется, я знаю, как это лучше сделать. Я знаю по опыту, что ульи силитидов очень чувствительны к окружающей среде; этим объясняется их нападения при звуках призрачного воя.$b$bСредоточие силы силитидов – башня, та самая, вокруг которой вьются осы. Ступай к этой башне и пробуди весь улей. Доложи обо всем, что удастся узнать, но соблюдай осторожность! Если попадется что-нибудь полезное, неси сюда.','Отыщите покрытый коркой щит силитида.','Вернитесь к Лайо Звездному Всполоху в Силитус.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Улей в башне',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пора заняться ульем в деревне Южного Ветра, и мне кажется, я знаю, как это лучше сделать. Я знаю по опыту, что ульи силитидов очень чувствительны к окружающей среде; этим объясняется их нападения при звуках призрачного воя.$b$bСредоточие силы силитидов – башня, та самая, вокруг которой вьются осы. Ступай к этой башне и пробуди весь улей. Доложи обо всем, что удастся узнать, но соблюдай осторожность! Если попадется что-нибудь полезное, неси сюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщите покрытый коркой щит силитида.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лайо Звездному Всполоху в Силитус.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (28893,'Умбер, архивариус','Если под этим хитиновым покровом найдутся какие-то записи, то Круг Кенария наконец-то сможет заглянуть в прошлое!$b$bОтнеси это моему другу. Его зовут Умбер и он просто гений. Да, тронутый, не без этого, но все равно гений! Умбер имел дело с манускриптами, которые были в куда худшем состоянии. Если есть хотя бы малейший шанс, что эти записи можно восстановить, он это сделает.','Отнесите покрытый коркой щит силитида Умберу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Умбер, архивариус',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если под этим хитиновым покровом найдутся какие-то записи, то Круг Кенария наконец-то сможет заглянуть в прошлое!$b$bОтнеси это моему другу. Его зовут Умбер и он просто гений. Да, тронутый, не без этого, но все равно гений! Умбер имел дело с манускриптами, которые были в куда худшем состоянии. Если есть хотя бы малейший шанс, что эти записи можно восстановить, он это сделает.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите покрытый коркой щит силитида Умберу.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (28894,'Раскрытие древних секретов','В общем, свяжись со мной как можно скорее... если, конечно, хочешь знать, что там внутри. Как только я узнаю это, с удовольствием поделюсь с тобой информацией – разумеется, если там действительно окажется книга.$B$BА пока я свяжусь с самой-большой-медведицей этого медвежьего угла, то есть Рабином. Он, несомненно, пожелает узнать, что за кашу ты тут $Gзаварил:заварила;. Никогда не заставляй мать-медведицу ждать, $n... ну, если только тебе неймется искупаться в меду.$B$BТакое бывает, уж поверь мне.','Поговорите с Рабином Сатурной в Крепости Кенария, что в Силитусе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Раскрытие древних секретов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В общем, свяжись со мной как можно скорее... если, конечно, хочешь знать, что там внутри. Как только я узнаю это, с удовольствием поделюсь с тобой информацией – разумеется, если там действительно окажется книга.$B$BА пока я свяжусь с самой-большой-медведицей этого медвежьего угла, то есть Рабином. Он, несомненно, пожелает узнать, что за кашу ты тут $Gзаварил:заварила;. Никогда не заставляй мать-медведицу ждать, $n... ну, если только тебе неймется искупаться в меду.$B$BТакое бывает, уж поверь мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Рабином Сатурной в Крепости Кенария, что в Силитусе.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (28895,'Осквернители ветра','Даже просто прийти в такое место, как это, было очень глупо с твоей стороны, |3-6($c). Но и от глупца может быть польза.$b$bЯ охраняю тюрьму моего хозяина уже долгие годы. Беспрестанно. Даже мерзкие земные прислужники, которыми кишит это место, принадлежащее ветрам, не могут помешать мне...$b$bЯ презираю их! Я убиваю тех, кто приближается, но я не могу позволить себе тратить время на этих ничтожеств. Если этим займешься ты, я тебя вознагражу...','Убейте 10 пустынных грохотунов.','Вернитесь к верховному лорду Деметриану в Разоренный Сумеречный лагерь, что в Силитусе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Осквернители ветра',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Даже просто прийти в такое место, как это, было очень глупо с твоей стороны, |3-6($c). Но и от глупца может быть польза.$b$bЯ охраняю тюрьму моего хозяина уже долгие годы. Беспрестанно. Даже мерзкие земные прислужники, которыми кишит это место, принадлежащее ветрам, не могут помешать мне...$b$bЯ презираю их! Я убиваю тех, кто приближается, но я не могу позволить себе тратить время на этих ничтожеств. Если этим займешься ты, я тебя вознагражу...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 пустынных грохотунов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному лорду Деметриану в Разоренный Сумеречный лагерь, что в Силитусе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (28896,'Призыв','Здесь изображена встреча посланника киражи с тремя силитидами у костей большого дракона. Над рисунком надпись... мне знаком этот шифр. Я нашла к нему ключ, когда вновь открылись Врата Ан\'Киража.$b$bНо ведь киражи уже давно побеждены... кто же общается с силитидами при помощи этого шифра? Отнеси письмена вызова к костям Граккаронда, это к югу от Крепости Кенария. Воспользуйся ими там и посмотри, кто придет на твой зов. Вряд ли у вас получится дружеская встреча... так что будь $gосторожен:осторожна;.','Воспользуйтесь письменами вызова у костей Граккаронда, чтобы призвать нового хозяина силитидов.','Вернитесь к геологу Ехидной в Крепость Кенария, что в Силитусе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Призыв',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Здесь изображена встреча посланника киражи с тремя силитидами у костей большого дракона. Над рисунком надпись... мне знаком этот шифр. Я нашла к нему ключ, когда вновь открылись Врата Ан\'Киража.$b$bНо ведь киражи уже давно побеждены... кто же общается с силитидами при помощи этого шифра? Отнеси письмена вызова к костям Граккаронда, это к югу от Крепости Кенария. Воспользуйся ими там и посмотри, кто придет на твой зов. Вряд ли у вас получится дружеская встреча... так что будь $gосторожен:осторожна;.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь письменами вызова у костей Граккаронда, чтобы призвать нового хозяина силитидов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к геологу Ехидной в Крепость Кенария, что в Силитусе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (28897,'План Баристолфа','Наши стражники недавно заметили, что сектанты Сумеречного Молота перемещаются ближе к улью Аши. Не собирают ли они втайне силы внутри улья?$b$bНам необходимо разобраться во всем этом до того, как они воплотят в жизнь то, что задумали.$b$bБаристолф, охотник, который стоит напротив меня, охотился в ульях Силитуса уже тогда, когда мы с тобой еще даже не появились на свет. Возможно, он знает, как пробраться в улей Аши незамеченным...','Поговорите с Баристолфом из Зыбучих Песков в Крепости Кенария.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','План Баристолфа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наши стражники недавно заметили, что сектанты Сумеречного Молота перемещаются ближе к улью Аши. Не собирают ли они втайне силы внутри улья?$b$bНам необходимо разобраться во всем этом до того, как они воплотят в жизнь то, что задумали.$b$bБаристолф, охотник, который стоит напротив меня, охотился в ульях Силитуса уже тогда, когда мы с тобой еще даже не появились на свет. Возможно, он знает, как пробраться в улей Аши незамеченным...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Баристолфом из Зыбучих Песков в Крепости Кенария.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (28898,'Выделения и ухищрения','На поверхности улья Аши, что к северу отсюда, я сектантов не видел. Если нам повезет, мы сможем закончить все приготовления, оставшись незамеченными.$b$bУ силитидов есть железа, которая выделяет густую слизь, затвердевающую на воздухе. Они используют ее для строительства ульев, а некоторые – для откладывания яиц.$b$bПринеси мне столько этих желез, чтобы слизи хватило для того, чтобы покрыть ею целиком кого-то вдвое выше тебя. И пока что ни в коем случае не заходи в улей.','Соберите 8 выделительных желез любого силитида из улья Аши.','Вернитесь к Баристолфу из Зыбучих Песков в Крепость Кенария, что в Силитусе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Выделения и ухищрения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На поверхности улья Аши, что к северу отсюда, я сектантов не видел. Если нам повезет, мы сможем закончить все приготовления, оставшись незамеченными.$b$bУ силитидов есть железа, которая выделяет густую слизь, затвердевающую на воздухе. Они используют ее для строительства ульев, а некоторые – для откладывания яиц.$b$bПринеси мне столько этих желез, чтобы слизи хватило для того, чтобы покрыть ею целиком кого-то вдвое выше тебя. И пока что ни в коем случае не заходи в улей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 выделительных желез любого силитида из улья Аши.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Баристолфу из Зыбучих Песков в Крепость Кенария, что в Силитусе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (28899,'Прямое проникновение','Все готово. Бери ящик. Открыв его, ты покроешься слоем слизи силитидов и очутишься в своеобразном временном яйце.$B$BВоспользуйся им, когда окажешься рядом с другими яйцами на поверхности улья Аши, тогда рабочие занесут тебя внутрь, обманув бдительность сумеречных стражей. Яйцо должно треснуть до того, как у тебя внутри закончится воздух.','Воспользуйтесь специальной слизью силитидов вблизи кладки яиц перед ульем Аши, чтобы проникнуть внутрь.','Лучше молчи, чтобы не рисковать… просто слушай.','Баристолф из Зыбучих Песков') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прямое проникновение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Все готово. Бери ящик. Открыв его, ты покроешься слоем слизи силитидов и очутишься в своеобразном временном яйце.$B$BВоспользуйся им, когда окажешься рядом с другими яйцами на поверхности улья Аши, тогда рабочие занесут тебя внутрь, обманув бдительность сумеречных стражей. Яйцо должно треснуть до того, как у тебя внутри закончится воздух.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь специальной слизью силитидов вблизи кладки яиц перед ульем Аши, чтобы проникнуть внутрь.',`objectives_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Лучше молчи, чтобы не рисковать… просто слушай.',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Баристолф из Зыбучих Песков',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (28900,'Загадки улья Сумеречного Молота','Как мы и подозревали... этот улей – тайный командный центр культа Сумеречного Молота. Замаскировав его под улей, им удавалось тайно осуществлять свои планы.$B$BНужно узнать, что они задумали. Осмотри улей, чтобы найти какие-то зацепки, и не забудь перебить там этих безумцев, чтобы им не повадно было строить козни.','Осмотрите улей Аши в поисках следов, проливающих свет на планы Сумеречного Молота, и убейте 10 сектантов культа.','Вернитесь к Баристолфу из Зыбучих Песков в Крепость Кенария, что в Силитусе.','Нет пощады тем, кто стремится уничтожить этот мир.','Баристолф из Зыбучих Песков') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Загадки улья Сумеречного Молота',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как мы и подозревали... этот улей – тайный командный центр культа Сумеречного Молота. Замаскировав его под улей, им удавалось тайно осуществлять свои планы.$B$BНужно узнать, что они задумали. Осмотри улей, чтобы найти какие-то зацепки, и не забудь перебить там этих безумцев, чтобы им не повадно было строить козни.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Осмотрите улей Аши в поисках следов, проливающих свет на планы Сумеречного Молота, и убейте 10 сектантов культа.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Баристолфу из Зыбучих Песков в Крепость Кенария, что в Силитусе.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Нет пощады тем, кто стремится уничтожить этот мир.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Баристолф из Зыбучих Песков',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (28901,'Узники безумия','Эй, ты! Подойди к яйцу! Я тебя еле вижу..$B$BПохоже, что Баристолф улучшил свой маскировочный костюм, перед тем как выдать его тебе... Я до сих пор не могу выбраться из этой штуки. Я разведчик, которого он послал вперед ранее.$B$BНет, нет. Сейчас не время вызволять меня! Ты $gдолжен:должна; помочь остальным! Они сейчас находятся в плену по всему улью... Отыщи и освободи их.$B$BЯ сам себя вызволю из костюма... интересно, сколько еще для этого придется приложить усилий?','Освободите 5 пленников улья Аши.','Вернитесь к командиру Мар\'алиту в Крепость Кенария, что в Силитусе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Узники безумия',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эй, ты! Подойди к яйцу! Я тебя еле вижу..$B$BПохоже, что Баристолф улучшил свой маскировочный костюм, перед тем как выдать его тебе... Я до сих пор не могу выбраться из этой штуки. Я разведчик, которого он послал вперед ранее.$B$BНет, нет. Сейчас не время вызволять меня! Ты $gдолжен:должна; помочь остальным! Они сейчас находятся в плену по всему улью... Отыщи и освободи их.$B$BЯ сам себя вызволю из костюма... интересно, сколько еще для этого придется приложить усилий?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Освободите 5 пленников улья Аши.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру Мар\'алиту в Крепость Кенария, что в Силитусе.',`completedtext_loc8`);
