INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (28934,'Конец Королевской компании','В этом гроссбухе указано множество мест, и ты, $gпарень, должен:подруга, должна; проверить для меня кое-что. Нельзя допустить, чтобы это продолжалось и дальше.$b$bВот запись, которая меня особенно волнует: в ней говорится о месте в Ульдуме, которое находится к востоку от гробницы Хартута, рядом со входом со стороны Танариса. Не нравится мне это. Иди туда и разберись.$b$bДа, если увидишь что-то большое и опасное – брось в него эту бомбу.','Убейте 5 техников химической компании и воспользуйтесь кориевой бомбой Гвоздезуба, чтобы уничтожить повозку с химикатами на заброшенной ферме к востоку от гробницы Хартута, рядом со входом со стороны Танариса. После этого вернитесь к инспектору Кромсу Гвоздезубу в Штормград.','Вернитесь к инспектору Кромсу Гвоздезубу в Торговый квартал Штормграда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Конец Королевской компании',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В этом гроссбухе указано множество мест, и ты, $gпарень, должен:подруга, должна; проверить для меня кое-что. Нельзя допустить, чтобы это продолжалось и дальше.$b$bВот запись, которая меня особенно волнует: в ней говорится о месте в Ульдуме, которое находится к востоку от гробницы Хартута, рядом со входом со стороны Танариса. Не нравится мне это. Иди туда и разберись.$b$bДа, если увидишь что-то большое и опасное – брось в него эту бомбу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 5 техников химической компании и воспользуйтесь кориевой бомбой Гвоздезуба, чтобы уничтожить повозку с химикатами на заброшенной ферме к востоку от гробницы Хартута, рядом со входом со стороны Танариса. После этого вернитесь к инспектору Кромсу Гвоздезубу в Штормград.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к инспектору Кромсу Гвоздезубу в Торговый квартал Штормграда.',`completedtext_loc8`);
