INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (28937,'Хлебные крошки Альянса','Чудовища! Просто чудовища!$B$BНаш корабль зашел в порт к югу от Cтромгарда, но на берегу нас ждала стая странных созданий.$B$BПеред тем как смыться оттуда, я успел обратить внимание на их противные морды и странные булькающие звуки, которые они издавали. Лучше поспеши на помощь моим товарищам, $n!','Поговорите с Леди Гаргой в бухте Фальдира.','TBD') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хлебные крошки Альянса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чудовища! Просто чудовища!$B$BНаш корабль зашел в порт к югу от Cтромгарда, но на берегу нас ждала стая странных созданий.$B$BПеред тем как смыться оттуда, я успел обратить внимание на их противные морды и странные булькающие звуки, которые они издавали. Лучше поспеши на помощь моим товарищам, $n!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Леди Гаргой в бухте Фальдира.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','TBD',`completedtext_loc8`);
