INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (29021,'Самофланж','На панели управления в беспорядке расположены кнопки, рычаги и мигающие лампочки. Судя по маленькому индикатору, устройство работает в оптимальном режиме, а контрольные клапаны 1-3 сейчас открыты. В нижнем правом углу панели управления имеется небольшая замочная скважина.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Самофланж',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','На панели управления в беспорядке расположены кнопки, рычаги и мигающие лампочки. Судя по маленькому индикатору, устройство работает в оптимальном режиме, а контрольные клапаны 1-3 сейчас открыты. В нижнем правом углу панели управления имеется небольшая замочная скважина.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29022,'Самофланж','В настоящий момент открыты три контрольных клапана. Судя по надписям на панели управления, их надо закрыть, прежде чем выключать прибор.','Закройте топливный распределительный клапан, перепускной клапан и главный клапан управления, а потом снова попытайтесь воспользоваться панелью управления.','Лампочки, относящиеся к трем управляющим клапанам, медленно гаснут. Зеленый огонек становится желтым, и теперь можно сдвинуть рычаг, выключающий прибор. Клапаны закрыты, и панель управления можно отключить.','Вернитесь к панели управления в исследовательском центре Торговой Компании, что в Северных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Самофланж',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В настоящий момент открыты три контрольных клапана. Судя по надписям на панели управления, их надо закрыть, прежде чем выключать прибор.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Закройте топливный распределительный клапан, перепускной клапан и главный клапан управления, а потом снова попытайтесь воспользоваться панелью управления.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Лампочки, относящиеся к трем управляющим клапанам, медленно гаснут. Зеленый огонек становится желтым, и теперь можно сдвинуть рычаг, выключающий прибор. Клапаны закрыты, и панель управления можно отключить.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к панели управления в исследовательском центре Торговой Компании, что в Северных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29023,'Самофланж','Прибор выключен, и вы можете открыть панель управления и достать самофланж из терминала. Все бы хорошо, но чтобы отпереть терминал, нужен ключ.','Возьмите у ремонтника Угрелова ключ от терминала.','Повернув ключ в замке, вы открываете панель управления. В верхней части терминала гаснет красная лампочка. Теперь он полностью обесточен.','Лампочки на панели потухли, стрелки всех приборов на нуле, все бездействует.','Вернитесь к панели управления, находящейся в исследовательском центре Торговой Компании в Северных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Самофланж',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прибор выключен, и вы можете открыть панель управления и достать самофланж из терминала. Все бы хорошо, но чтобы отпереть терминал, нужен ключ.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возьмите у ремонтника Угрелова ключ от терминала.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Повернув ключ в замке, вы открываете панель управления. В верхней части терминала гаснет красная лампочка. Теперь он полностью обесточен.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Лампочки на панели потухли, стрелки всех приборов на нуле, все бездействует.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к панели управления, находящейся в исследовательском центре Торговой Компании в Северных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29024,'Самофланж','Под панелью управления оказывается мешанина проводов, ламп и загадочных механических объектов – кажется, большая часть там вообще не нужна. Отодвинув их в сторону и сунув руку поглубже, вы находите самофланж. Одного усилия хватает, чтобы вытащить его из паза.','Это... э... любопытно... да. Для исследования столь сложного механизма понадобится команда опытных инженеров и лаборатория, чтобы досконально изучить механику каждого компонента под надлежащим контролем.$B$BНо где же на все времени наберешься?$B$BДавай-ка запустим эту штуку и посмотрим, что она умеет делать...','Отнесите самофланж Пароклапану в Лагерь Котельника, что в Северных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Самофланж',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Под панелью управления оказывается мешанина проводов, ламп и загадочных механических объектов – кажется, большая часть там вообще не нужна. Отодвинув их в сторону и сунув руку поглубже, вы находите самофланж. Одного усилия хватает, чтобы вытащить его из паза.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это... э... любопытно... да. Для исследования столь сложного механизма понадобится команда опытных инженеров и лаборатория, чтобы досконально изучить механику каждого компонента под надлежащим контролем.$B$BНо где же на все времени наберешься?$B$BДавай-ка запустим эту штуку и посмотрим, что она умеет делать...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите самофланж Пароклапану в Лагерь Котельника, что в Северных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29025,'Починка самофланжа','Так-так, он работает не так, как надо. Кажется, я его сломал.$b$bВпрочем, нет оснований для беспокойства. Окажи мне услугу, сбегай к Браку тут в лагере. Он быстро разберется с этой штуковиной!','Отнесите сломанный самофланж Браку Трубореву в лагерь.','Доставьте сломанный самофланж Браку Трубореву в лагерь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Починка самофланжа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Так-так, он работает не так, как надо. Кажется, я его сломал.$b$bВпрочем, нет оснований для беспокойства. Окажи мне услугу, сбегай к Браку тут в лагере. Он быстро разберется с этой штуковиной!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите сломанный самофланж Браку Трубореву в лагерь.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доставьте сломанный самофланж Браку Трубореву в лагерь.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29026,'Венаки Бенике','Похоже, я тут немного напортачил – один из нагрузочных флюксоров, кажется, попал под спицы дерегуляторного привода. Такое несложно починить. Я знаю одного спеца по поршневым приводам трехкратного расширения, который с радостью займется починкой. Отнеси сломанный самофланж Венаки Бенике, которая живет к югу от заставы Мор\'шан – она его в три счета подлатает. $B$BТебе даже не придется идти пешком! Я как раз хотел протестировать свое новое телепортирующее устройство...','Отнесите разбитый самофланж Венаки Бенике. Обратитесь к Браку, чтобы он телепортировал вас прямо к ней.','Что это? Самофланж, говоришь? Что такое самофланж??$B$BАх... Ты посмотри, как он движется! И совсем не слышно никакого шума при работе этого сложнейшего механизма. Ух ты! Я прямо сгораю от нетерпения починить его и посмотреть, на что эта штука способна, а ты?','Отнесите разбитый и сломанный самофланж Венаки Бенике в Северные Степи. Поговорите с Браком, чтобы телепортироваться прямо к ней.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Венаки Бенике',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Похоже, я тут немного напортачил – один из нагрузочных флюксоров, кажется, попал под спицы дерегуляторного привода. Такое несложно починить. Я знаю одного спеца по поршневым приводам трехкратного расширения, который с радостью займется починкой. Отнеси сломанный самофланж Венаки Бенике, которая живет к югу от заставы Мор\'шан – она его в три счета подлатает. $B$BТебе даже не придется идти пешком! Я как раз хотел протестировать свое новое телепортирующее устройство...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите разбитый самофланж Венаки Бенике. Обратитесь к Браку, чтобы он телепортировал вас прямо к ней.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что это? Самофланж, говоришь? Что такое самофланж??$B$BАх... Ты посмотри, как он движется! И совсем не слышно никакого шума при работе этого сложнейшего механизма. Ух ты! Я прямо сгораю от нетерпения починить его и посмотреть, на что эта штука способна, а ты?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите разбитый и сломанный самофланж Венаки Бенике в Северные Степи. Поговорите с Браком, чтобы телепортироваться прямо к ней.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29027,'Металлические заготовки','Я хочу починить этот самофланж, но для этого мне понадобятся некоторые запчасти. У меня кончились семнадцати с половиной миллиметровые заготовки для деталей, а для такой работы мне их понадобится целая куча.$B$BК сожалению, ближайшее место, где их можно достать, – это ферма Пылающего Клинка к юго-западу отсюда. Это место очень хорошо охраняется, так что будь $gосторожен:осторожна;. Но самофланж стоит того, чтобы ради него пойти на риск. Ищи ведра с инструментами, а когда наберешь достаточно заготовок, возвращайся ко мне.','Соберите 10 металлических заготовок для деталей вокруг фермы Пылающего Клинка, которая находится к юго-западу от вас.','Принесите металлические заготовки Венаки Бенике в Северные Степи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Металлические заготовки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я хочу починить этот самофланж, но для этого мне понадобятся некоторые запчасти. У меня кончились семнадцати с половиной миллиметровые заготовки для деталей, а для такой работы мне их понадобится целая куча.$B$BК сожалению, ближайшее место, где их можно достать, – это ферма Пылающего Клинка к юго-западу отсюда. Это место очень хорошо охраняется, так что будь $gосторожен:осторожна;. Но самофланж стоит того, чтобы ради него пойти на риск. Ищи ведра с инструментами, а когда наберешь достаточно заготовок, возвращайся ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 металлических заготовок для деталей вокруг фермы Пылающего Клинка, которая находится к юго-западу от вас.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите металлические заготовки Венаки Бенике в Северные Степи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29028,'В Джеденар','Члены Совета Теней продолжают осквернять этот некогда прекрасный лес из своей крепости, Джеденара, что возвышается на северо-западе отсюда.$B$BА теперь там пропал один из наших людей. Мы послали в Джеденар разведчика в надежде, что он сможет немного сократить численность Совета Теней одиночными вылазками, но с тех пор от него не поступало ни одного донесениями. $B$BМы боимся, что его постигла печальная участь, хотя все еще остается надежда, что он остался в живых. Прошу тебя, $n, разыщи его!','Найдите Андалара Дольную Тень в Джеденаре.','Найдите Андалара Дольную Тень в Джеденаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В Джеденар',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Члены Совета Теней продолжают осквернять этот некогда прекрасный лес из своей крепости, Джеденара, что возвышается на северо-западе отсюда.$B$BА теперь там пропал один из наших людей. Мы послали в Джеденар разведчика в надежде, что он сможет немного сократить численность Совета Теней одиночными вылазками, но с тех пор от него не поступало ни одного донесениями. $B$BМы боимся, что его постигла печальная участь, хотя все еще остается надежда, что он остался в живых. Прошу тебя, $n, разыщи его!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Андалара Дольную Тень в Джеденаре.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Найдите Андалара Дольную Тень в Джеденаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29029,'Позабытое знание','<Оскверненная вода бурлит и пенится, словно пытаясь очиститься.>$B$BОтнеси эту воду нашему разведчику в Дженедар. Он очистит ее, чтобы потом использовать при нападении на Оплот Теней.','Отнесите наполненную флягу Андалару Дольной Тени.','Отнесите наполненную флягу Андалару Дольной Тени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Позабытое знание',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Оскверненная вода бурлит и пенится, словно пытаясь очиститься.>$B$BОтнеси эту воду нашему разведчику в Дженедар. Он очистит ее, чтобы потом использовать при нападении на Оплот Теней.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите наполненную флягу Андалару Дольной Тени.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите наполненную флягу Андалару Дольной Тени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`) VALUES (29030,'Поклонение огню','Праздник Огненного солнцеворота – время поклонения стихиям. Огонь разжигает страсти в нашей душе. Сколько раз эти страсти приводили к открытой агрессии... Сейчас же, находясь на этой земле, мы направляем свои эмоции так, чтоб выразить почтение стихии огня.$b$bМы поклонимся пламени, как того требуют традиции. Желаешь ли ты присоединиться к нашему чествованию огня, $n?','Поклонитесь большому костру Служителей Земли на Хиджале.','Поклонитесь большому костру Служителей Земли на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поклонение огню',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Праздник Огненного солнцеворота – время поклонения стихиям. Огонь разжигает страсти в нашей душе. Сколько раз эти страсти приводили к открытой агрессии... Сейчас же, находясь на этой земле, мы направляем свои эмоции так, чтоб выразить почтение стихии огня.$b$bМы поклонимся пламени, как того требуют традиции. Желаешь ли ты присоединиться к нашему чествованию огня, $n?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поклонитесь большому костру Служителей Земли на Хиджале.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Поклонитесь большому костру Служителей Земли на горе Хиджал.',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (29030,'Поклонитесь огню на горе Хиджал.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Поклонитесь огню на горе Хиджал.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`) VALUES (29031,'Поклонение огню','Праздник Огненного солнцеворота – время поклонения стихиям. Огонь разжигает страсти в нашей душе. Сколько раз эти страсти приводили к открытой агрессии... Сейчас же, находясь на этой земле, мы направляем свои эмоции так, чтоб выразить почтение стихии огня.$b$bМы поклонимся пламени, как того требуют традиции. Желаешь ли ты присоединиться к нашему чествованию огня, $n?','Поклонитесь большому костру Служителей Земли в Вайш\'ире.','Поклонитесь большому костру Служителей Земли в Вайш\'ире.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поклонение огню',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Праздник Огненного солнцеворота – время поклонения стихиям. Огонь разжигает страсти в нашей душе. Сколько раз эти страсти приводили к открытой агрессии... Сейчас же, находясь на этой земле, мы направляем свои эмоции так, чтоб выразить почтение стихии огня.$b$bМы поклонимся пламени, как того требуют традиции. Желаешь ли ты присоединиться к нашему чествованию огня, $n?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поклонитесь большому костру Служителей Земли в Вайш\'ире.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Поклонитесь большому костру Служителей Земли в Вайш\'ире.',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (29031,'Поклонитесь огню в Вайш\'ире.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Поклонитесь огню в Вайш\'ире.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29032,'Начни тренировки, пока они еще маленькие','Я могу научить тебя ездить на ледопарде Зимних Ключей, но это требует времени и упорства. Чтобы это получилось, и наездник, и ледопард должны иметь серьезную подготовку и глубоко доверять друг другу.$b$bЭто удается лишь тогда, когда детеныши ледопарда знакомятся с будущими наездниками еще в самом юном возрасте. В логовах вокруг Уступа Ледопардов есть детеныши, которые уже достигли подходящего для начала тренировок возраста. Если ты поможешь мне собрать наиболее многообещающих из них, я позволю тебе начать тренировки со своим собственным детенышем ледопарда.','Соберите 8 детенышей ледопарда из логовищ вокруг Уступа Ледопардов.','Возраст этих детенышей самый подходящий для того, чтобы начать тренировки. Некоторых из них вполне можно приучить к наезднику. Как и обещал, я выберу одного из них для тебя. Похоже, вот этому малышу ты нравишься.$B$BА остальных я обучу для того, чтобы потом продать на рынке в Дарнасе.','Детенышей нужно забирать из логовищ, пока они еще достаточно маленькие для того, чтобы привязаться к человеку. Если упустить время, они одичают, и изменить это уже будет невозможно.','Вернитесь к Риверну Холодному Ветру на Уступ Ледопардов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Начни тренировки, пока они еще маленькие',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я могу научить тебя ездить на ледопарде Зимних Ключей, но это требует времени и упорства. Чтобы это получилось, и наездник, и ледопард должны иметь серьезную подготовку и глубоко доверять друг другу.$b$bЭто удается лишь тогда, когда детеныши ледопарда знакомятся с будущими наездниками еще в самом юном возрасте. В логовах вокруг Уступа Ледопардов есть детеныши, которые уже достигли подходящего для начала тренировок возраста. Если ты поможешь мне собрать наиболее многообещающих из них, я позволю тебе начать тренировки со своим собственным детенышем ледопарда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 детенышей ледопарда из логовищ вокруг Уступа Ледопардов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Возраст этих детенышей самый подходящий для того, чтобы начать тренировки. Некоторых из них вполне можно приучить к наезднику. Как и обещал, я выберу одного из них для тебя. Похоже, вот этому малышу ты нравишься.$B$BА остальных я обучу для того, чтобы потом продать на рынке в Дарнасе.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Детенышей нужно забирать из логовищ, пока они еще достаточно маленькие для того, чтобы привязаться к человеку. Если упустить время, они одичают, и изменить это уже будет невозможно.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Риверну Холодному Ветру на Уступ Ледопардов.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (29033,'[PH] Bridle Buy-In') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[PH] Bridle Buy-In',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29034,'Они так быстро растут','Думаю, этот детеныш отлично подойдет тебе.$b$bНо чтобы он вырос сильным и здоровым, тебе следует уделять ему много внимания. Старайся хотя бы раз в день проверить, как он себя чувствует. Не забывай его кормить и заботиться о нем – это лучший способ завоевать его доверие.$b$bПо мере того, как детеныш будет расти, он будет сбрасывать старые усы и отращивать новые, соответствующие его изменившимся размерам. Собирай их. Когда наберется двадцать, приведи детеныша обратно ко мне. И заодно принеси необходимые для седла материалы.','Соберите 20 усов детеныша ледопарда Зимних Ключей, сброшенных вашим подопечным. Принесите усы, 20 кусков рунической ткани, 20 кусков грубой кожи и 80 золотых Риверну Холодному Ветру.','Вернитесь к Риверну Холодному Ветру на Уступ Ледопардов, что в Зимних Ключах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Они так быстро растут',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Думаю, этот детеныш отлично подойдет тебе.$b$bНо чтобы он вырос сильным и здоровым, тебе следует уделять ему много внимания. Старайся хотя бы раз в день проверить, как он себя чувствует. Не забывай его кормить и заботиться о нем – это лучший способ завоевать его доверие.$b$bПо мере того, как детеныш будет расти, он будет сбрасывать старые усы и отращивать новые, соответствующие его изменившимся размерам. Собирай их. Когда наберется двадцать, приведи детеныша обратно ко мне. И заодно принеси необходимые для седла материалы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 20 усов детеныша ледопарда Зимних Ключей, сброшенных вашим подопечным. Принесите усы, 20 кусков рунической ткани, 20 кусков грубой кожи и 80 золотых Риверну Холодному Ветру.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Риверну Холодному Ветру на Уступ Ледопардов, что в Зимних Ключах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29035,'Аппетит детеныша ледопарда','Детеныш ледопарда смотрит на вас и облизывается. Вероятно, малыш голоден, и вам стоит позаботиться о том, чтобы найти для него подходящую пищу.$b$bРиверн Холодный Ветер говорил о том, что своих детенышей ледопарда он кормит мясом медведей-щербозубов. Может быть, и вашему малышу оно придется по вкусу. Медведей-щербозубов можно найти в любой части Зимних Ключей.','Поохотьтесь на любых медведей-щербозубов, добудьте 6 кусков мяса медведя-щербозуба и накормите своего детеныша ледопарда Зимних Ключей.','Ваш детеныш ледопарда выглядит счастливым, довольным и готов уснуть.','Поговорите со своим детенышем ледопарда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Аппетит детеныша ледопарда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Детеныш ледопарда смотрит на вас и облизывается. Вероятно, малыш голоден, и вам стоит позаботиться о том, чтобы найти для него подходящую пищу.$b$bРиверн Холодный Ветер говорил о том, что своих детенышей ледопарда он кормит мясом медведей-щербозубов. Может быть, и вашему малышу оно придется по вкусу. Медведей-щербозубов можно найти в любой части Зимних Ключей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поохотьтесь на любых медведей-щербозубов, добудьте 6 кусков мяса медведя-щербозуба и накормите своего детеныша ледопарда Зимних Ключей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ваш детеныш ледопарда выглядит счастливым, довольным и готов уснуть.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите со своим детенышем ледопарда.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`) VALUES (29036,'Поклонение огню','Праздник Огненного солнцеворота – время поклонения стихиям. Огонь разжигает страсти в нашей душе. Сколько раз эти страсти приводили к открытой агрессии... Сейчас же, находясь на этой земле, мы направляем свои эмоции так, чтоб выразить почтение стихии огня.$b$bМы поклонимся пламени, как того требуют традиции. Желаешь ли ты присоединиться к нашему чествованию огня, $n?','Поклонитесь большому костру Служителей Земли в Подземье.','Поклонитесь большому костру Служителей Земли в Подземье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поклонение огню',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Праздник Огненного солнцеворота – время поклонения стихиям. Огонь разжигает страсти в нашей душе. Сколько раз эти страсти приводили к открытой агрессии... Сейчас же, находясь на этой земле, мы направляем свои эмоции так, чтоб выразить почтение стихии огня.$b$bМы поклонимся пламени, как того требуют традиции. Желаешь ли ты присоединиться к нашему чествованию огня, $n?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поклонитесь большому костру Служителей Земли в Подземье.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Поклонитесь большому костру Служителей Земли в Подземье.',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (29036,'Поклонитесь огню в Подземье.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Поклонитесь огню в Подземье.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29037,'"Взять взаймы" у фурболгов Зимней Спячки','Детеныш ледопарда смотрит на вас так, как будто ждет чего-то. Чего же он может хотеть?$b$bДетеныш облизывается. Наверное, его снова пора кормить! Раз уж вы заменяете ему $gотца:мать;, то вам и заботиться о его пропитании до тех пор, пока он не сможет охотиться сам.$b$bА что если охотиться за вас будет кто-то другой? В обоих лагерях живущих в Зимних Ключах фурболгов Зимней Спячки обычно хранятся большие запасы копченого мяса. Они и не заметят пропажу нескольких кусков, зато ваш подопечный сможет попробовать что-то новенькое.','Соберите 6 кусков копченого мяса в любом из лагерей фурболгов Зимней Спячки и накормите детеныша ледопарда Зимних Ключей.','Теперь детеныш ледопарда выглядит довольным.','Поговорите со своим детенышем ледопарда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','"Взять взаймы" у фурболгов Зимней Спячки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Детеныш ледопарда смотрит на вас так, как будто ждет чего-то. Чего же он может хотеть?$b$bДетеныш облизывается. Наверное, его снова пора кормить! Раз уж вы заменяете ему $gотца:мать;, то вам и заботиться о его пропитании до тех пор, пока он не сможет охотиться сам.$b$bА что если охотиться за вас будет кто-то другой? В обоих лагерях живущих в Зимних Ключах фурболгов Зимней Спячки обычно хранятся большие запасы копченого мяса. Они и не заметят пропажу нескольких кусков, зато ваш подопечный сможет попробовать что-то новенькое.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 6 кусков копченого мяса в любом из лагерей фурболгов Зимней Спячки и накормите детеныша ледопарда Зимних Ключей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь детеныш ледопарда выглядит довольным.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите со своим детенышем ледопарда.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29038,'Практика охоты','Детеныш ледопарда, которого вы держите на руках, игриво трогает вас лапой. Ему будет сложно отточить свои охотничьи навыки без товарища по играм.$B$BМожет быть, стоит взять его поохотиться на полярных зайцев, обитающих в снегах в северной части Зимних Ключей? Отнесите детеныша к сугробам, покрывающим заячьи норы и подождите, пока в нем проснется охотничий инстинкт.','5 раз отнесите детеныша ледопарда к заснеженным норам в северной части Зимних Ключей, чтобы помочь ему научиться охотиться на полярных зайцев.','Детеныш ледопарда выглядит усталым, довольным и несколько более опытным.','Поговорите со своим детенышем ледопарда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Практика охоты',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Детеныш ледопарда, которого вы держите на руках, игриво трогает вас лапой. Ему будет сложно отточить свои охотничьи навыки без товарища по играм.$B$BМожет быть, стоит взять его поохотиться на полярных зайцев, обитающих в снегах в северной части Зимних Ключей? Отнесите детеныша к сугробам, покрывающим заячьи норы и подождите, пока в нем проснется охотничий инстинкт.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','5 раз отнесите детеныша ледопарда к заснеженным норам в северной части Зимних Ключей, чтобы помочь ему научиться охотиться на полярных зайцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Детеныш ледопарда выглядит усталым, довольным и несколько более опытным.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите со своим детенышем ледопарда.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29039,'Практика охоты','Детеныш ледопарда словно просится к вам на руки. Ему будет сложно отточить свои охотничьи навыки без товарища по игре.$B$BМожет быть, стоит взять его поохотиться на полярных зайцев, обитающих в снегах в северной части Зимних Ключей. Отнесите детеныша к сугробам, покрывающим заячьи норы и подождите, пока в нем проснется охотничий инстинкт.','5 раз отнесите детеныша ледопарда к заснеженным норам в северной части Зимних Ключей, чтобы помочь ему научиться охотиться на полярных зайцев.','Поговорите со своим детенышем ледопарда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Практика охоты',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Детеныш ледопарда словно просится к вам на руки. Ему будет сложно отточить свои охотничьи навыки без товарища по игре.$B$BМожет быть, стоит взять его поохотиться на полярных зайцев, обитающих в снегах в северной части Зимних Ключей. Отнесите детеныша к сугробам, покрывающим заячьи норы и подождите, пока в нем проснется охотничий инстинкт.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','5 раз отнесите детеныша ледопарда к заснеженным норам в северной части Зимних Ключей, чтобы помочь ему научиться охотиться на полярных зайцев.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите со своим детенышем ледопарда.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29040,'Первая игрушка детеныша ледопарда','Детеныш ледопарда играет с маленьким клоком меха из шкуры какого-то крупного животного. Несмотря на то, что он, похоже, увлечен этой игрой, вам приходит в голову мысль, что настоящая кошачья игрушка сделала бы его еще более счастливым.$b$bКусочек шкуры йети, несколько перьев лунного совуха – и получится отличная игрушка. Йети можно найти в холмах Ледополоха, что к юго-востоку от Круговзора, а лунные совухи водятся в Сокрытой роще и в Совиной чаще.','Добудьте жесткую шкуру йети у любого из йети с холмов Ледополоха и 5 перьев дикого совуха. Затем сделайте из них игрушку и поиграйте со своим детенышем ледопарда.','Похоже, детеныш ледопарда в восторге от своей новой игрушки. Интересно, на сколько ее хватит…','Поговорите со своим детенышем ледопарда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Первая игрушка детеныша ледопарда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Детеныш ледопарда играет с маленьким клоком меха из шкуры какого-то крупного животного. Несмотря на то, что он, похоже, увлечен этой игрой, вам приходит в голову мысль, что настоящая кошачья игрушка сделала бы его еще более счастливым.$b$bКусочек шкуры йети, несколько перьев лунного совуха – и получится отличная игрушка. Йети можно найти в холмах Ледополоха, что к юго-востоку от Круговзора, а лунные совухи водятся в Сокрытой роще и в Совиной чаще.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте жесткую шкуру йети у любого из йети с холмов Ледополоха и 5 перьев дикого совуха. Затем сделайте из них игрушку и поиграйте со своим детенышем ледопарда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Похоже, детеныш ледопарда в восторге от своей новой игрушки. Интересно, на сколько ее хватит…',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите со своим детенышем ледопарда.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29041,'Добро пожаловать в рай','Уфф!$b$bНадо же, а я думала, что ты – $gодин:одна; из НИХ.$b$bКто ты? $n? Послушай, ведь нам может пригодиться твоя помощь.$b$b<Лаша слушает ваш рассказ о том, что происходит.>$b$bТы что, $gослеп:ослепла;? Весь курорт охвачен огнем! Эти противные маленькие огненные поджигатели носятся тут и там, воспламеняя все, что попадется в их чумазые лапки. Убей их всех, пока мы не начали терпеть убытки!','Убейте 6 огненных поджигателей.','Вернитесь к Лаше Шестерняк на Дымящиеся озера, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Добро пожаловать в рай',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Уфф!$b$bНадо же, а я думала, что ты – $gодин:одна; из НИХ.$b$bКто ты? $n? Послушай, ведь нам может пригодиться твоя помощь.$b$b<Лаша слушает ваш рассказ о том, что происходит.>$b$bТы что, $gослеп:ослепла;? Весь курорт охвачен огнем! Эти противные маленькие огненные поджигатели носятся тут и там, воспламеняя все, что попадется в их чумазые лапки. Убей их всех, пока мы не начали терпеть убытки!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 6 огненных поджигателей.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лаше Шестерняк на Дымящиеся озера, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29042,'Уборка','Почему на нас вообще нападают? Мы никому не причиняем вреда! В любом случае, хорошо, что ты $gоказался:оказалась; здесь.$b$bСлушай, $n, пока я еще не лишилась работы, мне нужно выяснить, кто вредил нам. Раскопай как можно больше информации. Впрочем, сначала ты $gдолжен:должна; продемонстрировать мне, что сможешь влиться в ряды наших сотрудников.$b$bПервое, что мы должны делать, – это содержать курорт в чистоте. Так что иди на пляж и собери пустые банки.','Соберите 8 пустых банок из-под "Каджа-Колы".','Вернитесь к Лаше Шестерняк на Дымящиеся озера, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уборка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Почему на нас вообще нападают? Мы никому не причиняем вреда! В любом случае, хорошо, что ты $gоказался:оказалась; здесь.$b$bСлушай, $n, пока я еще не лишилась работы, мне нужно выяснить, кто вредил нам. Раскопай как можно больше информации. Впрочем, сначала ты $gдолжен:должна; продемонстрировать мне, что сможешь влиться в ряды наших сотрудников.$b$bПервое, что мы должны делать, – это содержать курорт в чистоте. Так что иди на пляж и собери пустые банки.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 пустых банок из-под "Каджа-Колы".',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лаше Шестерняк на Дымящиеся озера, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29043,'Обеденный перерыв','Ты – $gновый ассистент:новая ассистентка;, о $gкотором:которой; говорила Лаша?$b$b<Ботт оглядывает вас с ног до головы, даже не пытаясь скрыть свою неприязнь.>$b$bРазнесешь эти обеды оставшемуся персоналу курорта. Я против того, чтобы сотрудники отлучались на обеденные перерывы. В это время они могут заходить в запрещенные места, предаваться праздношатанию и даже болтать друг с другом. Отвратительные привычки! Проследи, чтобы они съели еду!','Доставьте обеды 5 сотрудникам из персонала курорта.','Вернитесь к заместителю директора курорта Ботту воттакенсу на Дымящиеся озера, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обеденный перерыв',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты – $gновый ассистент:новая ассистентка;, о $gкотором:которой; говорила Лаша?$b$b<Ботт оглядывает вас с ног до головы, даже не пытаясь скрыть свою неприязнь.>$b$bРазнесешь эти обеды оставшемуся персоналу курорта. Я против того, чтобы сотрудники отлучались на обеденные перерывы. В это время они могут заходить в запрещенные места, предаваться праздношатанию и даже болтать друг с другом. Отвратительные привычки! Проследи, чтобы они съели еду!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте обеды 5 сотрудникам из персонала курорта.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к заместителю директора курорта Ботту воттакенсу на Дымящиеся озера, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29044,'Докучливые дети','Существует лишь одна вещь, которую я ненавижу больше солнца и радуги. Это дети. Наши вездесущие гости постоянно берут с собой детей на так называемый "отдых всей семьей"! И вот их шалопаи носятся вокруг, горлопанят и омрачают отдых на моем курорте своим присутствием.$B$B<Заместитель директора Полосатикс с отвращением осматривается по сторонам.>$B$BВозьми-ка эту сертифицированную детскую шлейку и приведи сорванцов обратно на детскую игровую площадку. Дети не должны свободно разгуливать по территории!','Наденьте шлейку на 5 детей.','Вернитесь к заместителю директора курорта Ботту Воттакенсу на Дымящиеся озера, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Докучливые дети',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Существует лишь одна вещь, которую я ненавижу больше солнца и радуги. Это дети. Наши вездесущие гости постоянно берут с собой детей на так называемый "отдых всей семьей"! И вот их шалопаи носятся вокруг, горлопанят и омрачают отдых на моем курорте своим присутствием.$B$B<Заместитель директора Полосатикс с отвращением осматривается по сторонам.>$B$BВозьми-ка эту сертифицированную детскую шлейку и приведи сорванцов обратно на детскую игровую площадку. Дети не должны свободно разгуливать по территории!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Наденьте шлейку на 5 детей.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к заместителю директора курорта Ботту Воттакенсу на Дымящиеся озера, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29045,'По вкусу и королю','Теперь, когда курорт в порядке и снова работает, у меня совсем нет лишнего времени и масса ртов, которые нужно накормить! Я собираюсь готовить крабовое ризотто, но запасы крабового мяса подходят к концу. Поохоться на крабов в озерах и принеси мне мясо.','Добудьте 6 ножек королевского краба.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','По вкусу и королю',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда курорт в порядке и снова работает, у меня совсем нет лишнего времени и масса ртов, которые нужно накормить! Я собираюсь готовить крабовое ризотто, но запасы крабового мяса подходят к концу. Поохоться на крабов в озерах и принеси мне мясо.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 6 ножек королевского краба.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29046,'Испытание шеф-повара: Сталеспин','Королевские крабы, на которых ты $gохотился:охотилась; раньше, и в сравнение не идут с другим ракообразным – Сталеспином. Он не зря носит такое имя, но я в тебя верю, $n. Докажи же мне, что ты – $gдостойный ученик:достойная ученица;, и принеси мне его клешню.','Принесите клешню Сталеспина.','Вернитесь к Гордону Трэмси на Дымящиеся озера, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Испытание шеф-повара: Сталеспин',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Королевские крабы, на которых ты $gохотился:охотилась; раньше, и в сравнение не идут с другим ракообразным – Сталеспином. Он не зря носит такое имя, но я в тебя верю, $n. Докажи же мне, что ты – $gдостойный ученик:достойная ученица;, и принеси мне его клешню.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите клешню Сталеспина.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гордону Трэмси на Дымящиеся озера, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29047,'Испытание шеф-повара: Дивнокрыл','Я слыхал о гигантском мотыльке, который живет на западном побережье озера. Его рога невероятно вкусны. Я планирую приготовить из него незабываемое блюдо. Убей Дивнокрыла и принеси мне его рог.','Принесите рог Дивнокрыла.','Вернитесь к Гордону Трэмси на Дымящиеся озера, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Испытание шеф-повара: Дивнокрыл',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я слыхал о гигантском мотыльке, который живет на западном побережье озера. Его рога невероятно вкусны. Я планирую приготовить из него незабываемое блюдо. Убей Дивнокрыла и принеси мне его рог.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите рог Дивнокрыла.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гордону Трэмси на Дымящиеся озера, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29048,'Испытание шеф-повара: Ворчло','Есть одна рыба... Долгие годы мне не удавалось поймать ее. Она живет на дне самого большого из озер, за ее характер мы прозвали ее Ворчло. Думаю, пришло время уже наконец выловить ее и приготовить! Иди на охоту и возвращайся с добычей. Но будь $gосторожен:осторожна; – она старая и очень злобная.','Принесите глаз Ворчла.','Вернитесь к Гордону Трэмси на Дымящиеся озера, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Испытание шеф-повара: Ворчло',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Есть одна рыба... Долгие годы мне не удавалось поймать ее. Она живет на дне самого большого из озер, за ее характер мы прозвали ее Ворчло. Думаю, пришло время уже наконец выловить ее и приготовить! Иди на охоту и возвращайся с добычей. Но будь $gосторожен:осторожна; – она старая и очень злобная.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите глаз Ворчла.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гордону Трэмси на Дымящиеся озера, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29049,'So Sous Me','TBD','Talk to Auguste Yarmes') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','So Sous Me',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','TBD',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Talk to Auguste Yarmes',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29050,'Нехватка бензина','Так тебе нужна лодка? Что ж, моя малышка вполне могла бы перевезти тебя через озеро. Но проблема в том, что у "Счастливой бадьи" кончился бензин!$b$bВпрочем, в горах, что к югу отсюда, водятся нефтяные слизнюки. Если ты сходишь туда и наполнишь бензобак, ничто не помешает нашей водной прогулке. Что скажешь?','Воспользуйтесь гоблинским бензобаком, чтобы откачать нефть из 8 мертвых нефтяных слизнюков.','Вернитесь к Трипу Шелупуху на Дымящиеся озера, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нехватка бензина',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Так тебе нужна лодка? Что ж, моя малышка вполне могла бы перевезти тебя через озеро. Но проблема в том, что у "Счастливой бадьи" кончился бензин!$b$bВпрочем, в горах, что к югу отсюда, водятся нефтяные слизнюки. Если ты сходишь туда и наполнишь бензобак, ничто не помешает нашей водной прогулке. Что скажешь?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь гоблинским бензобаком, чтобы откачать нефть из 8 мертвых нефтяных слизнюков.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Трипу Шелупуху на Дымящиеся озера, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29051,'Первая игрушка детеныша ледопарда','Детеныш ледопарда играет с маленьким клоком меха из шкуры какого-то крупного животного. Несмотря на то, что он, похоже, увлечен этой игрой, вам приходит в голову мысль, что настоящая кошачья игрушка сделала бы его еще более счастливым.$b$bКусочек шкуры йети, несколько перьев лунного совуха – и получится отличная игрушка. Йети можно найти в холмах Ледополоха, что к юго-востоку от Круговзора, а лунные совухи водятся в Сокрытой роще и в Совиной чаще.','Добудьте жесткую шкуру йети у любого из йети с холмов Ледополоха и 5 перьев дикого совуха. Затем сделайте из них игрушку и поиграйте со своим детенышем ледопарда.','Поговорите со своим детенышем ледопарда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Первая игрушка детеныша ледопарда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Детеныш ледопарда играет с маленьким клоком меха из шкуры какого-то крупного животного. Несмотря на то, что он, похоже, увлечен этой игрой, вам приходит в голову мысль, что настоящая кошачья игрушка сделала бы его еще более счастливым.$b$bКусочек шкуры йети, несколько перьев лунного совуха – и получится отличная игрушка. Йети можно найти в холмах Ледополоха, что к юго-востоку от Круговзора, а лунные совухи водятся в Сокрытой роще и в Совиной чаще.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте жесткую шкуру йети у любого из йети с холмов Ледополоха и 5 перьев дикого совуха. Затем сделайте из них игрушку и поиграйте со своим детенышем ледопарда.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите со своим детенышем ледопарда.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29052,'Аппетит детеныша ледопарда','Детеныш ледопарда смотрит на вас и облизывается. Вероятно, малыш голоден, и вам стоит позаботиться о том, чтобы найти для него подходящую пищу.$b$bРиверн Холодный Ветер говорил о том, что своих детенышей ледопарда он кормит мясом медведей-щербозубов. Может быть, и вашему малышу оно придется по вкусу. Медведей-щербозубов можно найти в любой части Зимних Ключей.','Поохотьтесь на любых медведей-щербозубов, добудьте 6 кусков мяса медведя-щербозуба и накормите своего детеныша ледопарда Зимних Ключей.','Поговорите со своим детенышем ледопарда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Аппетит детеныша ледопарда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Детеныш ледопарда смотрит на вас и облизывается. Вероятно, малыш голоден, и вам стоит позаботиться о том, чтобы найти для него подходящую пищу.$b$bРиверн Холодный Ветер говорил о том, что своих детенышей ледопарда он кормит мясом медведей-щербозубов. Может быть, и вашему малышу оно придется по вкусу. Медведей-щербозубов можно найти в любой части Зимних Ключей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поохотьтесь на любых медведей-щербозубов, добудьте 6 кусков мяса медведя-щербозуба и накормите своего детеныша ледопарда Зимних Ключей.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите со своим детенышем ледопарда.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29053,'"Взять взаймы" у фурболгов Зимней Спячки','Детеныш ледопарда смотрит на вас так, как будто ждет чего-то. Чего же он может хотеть?$b$bДетеныш облизывается. Наверное, его снова пора кормить! Раз уж вы заменяете ему $gотца:мать;, то вам и заботиться о его пропитании до тех пор, пока он не сможет охотиться сам.$b$bА что если охотиться за вас будет кто-то другой? В обоих лагерях живущих в Зимних Ключах фурболгов Зимней Спячки обычно хранятся большие запасы копченого мяса. Они и не заметят пропажу нескольких кусков, зато ваш подопечный сможет попробовать что-то новенькое.','Соберите 6 кусков копченого мяса в любом из лагерей фурболгов Зимней Спячки и накормите детеныша ледопарда Зимних Ключей.','Поговорите со своим детенышем ледопарда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','"Взять взаймы" у фурболгов Зимней Спячки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Детеныш ледопарда смотрит на вас так, как будто ждет чего-то. Чего же он может хотеть?$b$bДетеныш облизывается. Наверное, его снова пора кормить! Раз уж вы заменяете ему $gотца:мать;, то вам и заботиться о его пропитании до тех пор, пока он не сможет охотиться сам.$b$bА что если охотиться за вас будет кто-то другой? В обоих лагерях живущих в Зимних Ключах фурболгов Зимней Спячки обычно хранятся большие запасы копченого мяса. Они и не заметят пропажу нескольких кусков, зато ваш подопечный сможет попробовать что-то новенькое.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 6 кусков копченого мяса в любом из лагерей фурболгов Зимней Спячки и накормите детеныша ледопарда Зимних Ключей.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите со своим детенышем ледопарда.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29054,'Сбросить бомбы-вонючки','Здравствуй, |3-6($c)! Тебе нравится Тыквовин? Ладно, давай перейдем прямо к делу... Подгород. Враги прибегли к помощи ведьм и черной магии в тщетной попытке атаковать наш город. Некоторые считают, что вообще не стоит обращать внимания на детские выходки Орды. Я же думаю, что нужно как следует проучить их!$b$bПоговори с моей сестрой, Гертрудой, и с ее помощью подбрось немного бомб-вонючек в Подгород.','Поговорите с Гертрудой Фэнлоу, затем садитесь на метлу и бросайте бомбы-вонючки на Подгород.','Вернитесь к Гретхен Фэнлоу к вратам Штормграда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сбросить бомбы-вонючки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Здравствуй, |3-6($c)! Тебе нравится Тыквовин? Ладно, давай перейдем прямо к делу... Подгород. Враги прибегли к помощи ведьм и черной магии в тщетной попытке атаковать наш город. Некоторые считают, что вообще не стоит обращать внимания на детские выходки Орды. Я же думаю, что нужно как следует проучить их!$b$bПоговори с моей сестрой, Гертрудой, и с ее помощью подбрось немного бомб-вонючек в Подгород.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Гертрудой Фэнлоу, затем садитесь на метлу и бросайте бомбы-вонючки на Подгород.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гретхен Фэнлоу к вратам Штормграда.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29055,'Плыви, моя лодочка','Ну, вот, мы готовы! Садись в лодку и поплывем!','Совершите поездку по озеру на лодке Трипа.','Вернитесь к Лаше Шестерняк на Дымящиеся озера, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Плыви, моя лодочка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну, вот, мы готовы! Садись в лодку и поплывем!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Совершите поездку по озеру на лодке Трипа.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лаше Шестерняк на Дымящиеся озера, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29056,'Сбор фруктов','Так это ты $gтот самый помощник:та самая помощница; Лаши? Да, она говорила что-то о важном поручении и просила приготовить несколько особенных напитков для наших гостей. И действительно, у меня есть рецепты коктейлей, которые сейчас – последний писк моды в Штормграде и Оргриммаре. Но у меня нет самого главного ингредиента – кокоса! К счастью, вокруг лагеря полно пальм, на которых они растут. Беги туда прямо сейчас и собери немного.','Соберите 8 кокосов','Вернитесь к шеф-повару Гордону Трэмси на Дымящиеся озера, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сбор фруктов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Так это ты $gтот самый помощник:та самая помощница; Лаши? Да, она говорила что-то о важном поручении и просила приготовить несколько особенных напитков для наших гостей. И действительно, у меня есть рецепты коктейлей, которые сейчас – последний писк моды в Штормграде и Оргриммаре. Но у меня нет самого главного ингредиента – кокоса! К счастью, вокруг лагеря полно пальм, на которых они растут. Беги туда прямо сейчас и собери немного.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 кокосов',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к шеф-повару Гордону Трэмси на Дымящиеся озера, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29057,'Огнеклюв','Вот оно как, $n. Я ничуть не удивлена, что за всем этим стоял Ботт. Он мне никогда не нравился. Одни его идиотские усы чего стоили! Настало время ДАТЬ СДАЧИ!$b$bВ горах, что к востоку отсюда, живет Огнеклюв. Он поможет нам справиться с сектантами Сумеречного Молота.$b$bНапади на него и продемонстрируй, что ты – главнее. Когда он ослабнет, садись на него и лети к озерам, чтобы уничтожить наших врагов!','Сражайтесь с Огнеклювом до тех пор, пока он не ослабнет.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Огнеклюв',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот оно как, $n. Я ничуть не удивлена, что за всем этим стоял Ботт. Он мне никогда не нравился. Одни его идиотские усы чего стоили! Настало время ДАТЬ СДАЧИ!$b$bВ горах, что к востоку отсюда, живет Огнеклюв. Он поможет нам справиться с сектантами Сумеречного Молота.$b$bНапади на него и продемонстрируй, что ты – главнее. Когда он ослабнет, садись на него и лети к озерам, чтобы уничтожить наших врагов!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сражайтесь с Огнеклювом до тех пор, пока он не ослабнет.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29058,'Кишки руха','Да, у нас тут полное бедствие! Но клянусь, никто не посмеет уничтожить МОЙ курорт! Особенно этот жалкий червяк Додд Полосатикс. Он мне никогда не нравился, особенно его идиотские усы!!!$b$bПослушай, $n, давай предпримем еще одну безумную попытку избавиться от Сумеречного Молота раз и навсегда. В горах к востоку отсюда живут гигантские рухи, которые могут прекрасно противостоять огню. Из их кишок получатся отличные огнеупорные поводья. 12 будет достаточно.','Добудьте 12 кишок руха.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кишки руха',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Да, у нас тут полное бедствие! Но клянусь, никто не посмеет уничтожить МОЙ курорт! Особенно этот жалкий червяк Додд Полосатикс. Он мне никогда не нравился, особенно его идиотские усы!!!$b$bПослушай, $n, давай предпримем еще одну безумную попытку избавиться от Сумеречного Молота раз и навсегда. В горах к востоку отсюда живут гигантские рухи, которые могут прекрасно противостоять огню. Из их кишок получатся отличные огнеупорные поводья. 12 будет достаточно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 12 кишок руха.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (29059,'Спаси их') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спаси их',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29060,'К вашим услугам','Что ж, тебе вполне удается играть роль сотрудника курорта. Теперь попробуй покрутиться среди наших гостей. Совсем недавно у нас были проблемы из-за оставшихся в живых сектантов Сумеречного Молота, и мы предполагаем, что некоторые из отдыхающих могут сотрудничать с ними.$b$bВозьми эти напитки, отправляйся к гостям и посмотри, не удастся ли тебе обнаружить какие-то улики и распознать сектантов среди отдыхающих. Если тебе удастся развязать им языки, это может помочь. Так что проследи, чтобы каждому из гостей достался напиток по вкусу.','Обслужите 6 отдыхающих и соберите 4 улики против Сумеречного Молота.','Вернитесь к Лаше Шестерняк на Дымящиеся озера, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','К вашим услугам',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что ж, тебе вполне удается играть роль сотрудника курорта. Теперь попробуй покрутиться среди наших гостей. Совсем недавно у нас были проблемы из-за оставшихся в живых сектантов Сумеречного Молота, и мы предполагаем, что некоторые из отдыхающих могут сотрудничать с ними.$b$bВозьми эти напитки, отправляйся к гостям и посмотри, не удастся ли тебе обнаружить какие-то улики и распознать сектантов среди отдыхающих. Если тебе удастся развязать им языки, это может помочь. Так что проследи, чтобы каждому из гостей достался напиток по вкусу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обслужите 6 отдыхающих и соберите 4 улики против Сумеречного Молота.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лаше Шестерняк на Дымящиеся озера, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29062,'Найти сектанта','Похоже, здесь появился сектант культа Сумеречного Молота.$b$b$n, тебе нужно выявить шпиона. Допроси отдыхающих и выдвигай обвинение против любого, кто подходит под описание сектанта Сумеречного Молота!$b$bЗапомни особые приметы:$b$bВЫСОКОГО РОСТА$bГРУБИЯН$BНОСИТ ОДЕЖДУ КРАСНОГО ЦВЕТА$b$bЭто задание не для слабаков – если подозреваемый будет сопротивляться, тебе придется выбить из него информацию.','Допросите отдыхающих, чтобы найти улику против Сумеречного Молота.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Найти сектанта',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Похоже, здесь появился сектант культа Сумеречного Молота.$b$b$n, тебе нужно выявить шпиона. Допроси отдыхающих и выдвигай обвинение против любого, кто подходит под описание сектанта Сумеречного Молота!$b$bЗапомни особые приметы:$b$bВЫСОКОГО РОСТА$bГРУБИЯН$BНОСИТ ОДЕЖДУ КРАСНОГО ЦВЕТА$b$bЭто задание не для слабаков – если подозреваемый будет сопротивляться, тебе придется выбить из него информацию.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Допросите отдыхающих, чтобы найти улику против Сумеречного Молота.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (29063,'Диверсия') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Диверсия',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29064,'Нам нужна лодка','Теперь все понятно! Исследования местности, которые проводились перед архитектурной планировкой, показали, что вся эта область находится под действием энергетической аномалии. Это та же самая энергия, которая подпитывает здешние горячие минеральные озера.$b$bНет никаких сомнений, что Сумеречный Молот пытается обуздать эту энергию, чтобы открыть портал в обитель стихий воды! Если это произойдет, то все наше предприятие – и множество отдыхающих, конечно – просто затонет.$b$b$n, немедленно исследуй этот вопрос! Поговори с Трипом Шелупухом. У него есть лодка, на ней ты сможешь добраться до отмеченного на карте места.','Поговорите с Трипом Шелупухом.','Поговорите с Трипом Шелупухом') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нам нужна лодка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь все понятно! Исследования местности, которые проводились перед архитектурной планировкой, показали, что вся эта область находится под действием энергетической аномалии. Это та же самая энергия, которая подпитывает здешние горячие минеральные озера.$b$bНет никаких сомнений, что Сумеречный Молот пытается обуздать эту энергию, чтобы открыть портал в обитель стихий воды! Если это произойдет, то все наше предприятие – и множество отдыхающих, конечно – просто затонет.$b$b$n, немедленно исследуй этот вопрос! Поговори с Трипом Шелупухом. У него есть лодка, на ней ты сможешь добраться до отмеченного на карте места.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Трипом Шелупухом.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Трипом Шелупухом',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29065,'Прочь отсюда','Проблемам здесь нет конца, $n! Срываются поставки продовольствия, не прекращаются неполадки с водоснабжением, а теперь еще и это! Сложно получить более явный намек, чем огонь. Нас определенно не жаждут здесь видеть!$b$bЧто ж, вернемся к тому, с чего начали. Тот, кто пытается выжить нас из этих мест, расставил повсюду мерзкие тотемы. Если мы их уничтожим, проклятые демоны огня перестанут появляться.$b$bРазрушай все тотемы, какие увидишь, пока все не зашло слишком далеко!','Уничтожьте 6 сумеречных тотемов.','Вернитесь к Лаше Шестерняк на Дымящиеся озера, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прочь отсюда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Проблемам здесь нет конца, $n! Срываются поставки продовольствия, не прекращаются неполадки с водоснабжением, а теперь еще и это! Сложно получить более явный намек, чем огонь. Нас определенно не жаждут здесь видеть!$b$bЧто ж, вернемся к тому, с чего начали. Тот, кто пытается выжить нас из этих мест, расставил повсюду мерзкие тотемы. Если мы их уничтожим, проклятые демоны огня перестанут появляться.$b$bРазрушай все тотемы, какие увидишь, пока все не зашло слишком далеко!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 6 сумеречных тотемов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лаше Шестерняк на Дымящиеся озера, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (29066,'Хорошие новости... и плохие новости','<Чернорог воспользовался силой, которую черпал из останков Тол\'эмбаара, чтобы вырваться из заточения. Но, кажется, инферналы отступают.>$b$b<Мате Коготь будет интересно узнать о том, что здесь произошло. Она ждет тебя в Роще Эссины.>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хорошие новости... и плохие новости',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Чернорог воспользовался силой, которую черпал из останков Тол\'эмбаара, чтобы вырваться из заточения. Но, кажется, инферналы отступают.>$b$b<Мате Коготь будет интересно узнать о том, что здесь произошло. Она ждет тебя в Роще Эссины.>',`details_loc8`);
