INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (29071,'Скорее в Штормград!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Скорее в Штормград!',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29072,'Последний курорт, в буквальном смысле','Нам удалось на время остановить штурм и оставить Ботта без защиты.$b$bТем не менее, несмотря на всю сумятицу, ему удалось призвать Ахти, могущественного повелителя элементалей, с той стороны разлома. Заручившись поддержкой Ахти, Сумеречный Молот легко проникнет в соседние области, попутно унеся тысячи невинных жизней.$b$bЭто уже куда хуже, чем проблемы мои и моего курорта. Мы должны выступить против них немедленно. Тебя я прошу об одном – убей Ахти и спаси всех нас.','Убейте Ахти.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Последний курорт, в буквальном смысле',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нам удалось на время остановить штурм и оставить Ботта без защиты.$b$bТем не менее, несмотря на всю сумятицу, ему удалось призвать Ахти, могущественного повелителя элементалей, с той стороны разлома. Заручившись поддержкой Ахти, Сумеречный Молот легко проникнет в соседние области, попутно унеся тысячи невинных жизней.$b$bЭто уже куда хуже, чем проблемы мои и моего курорта. Мы должны выступить против них немедленно. Тебя я прошу об одном – убей Ахти и спаси всех нас.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Ахти.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (29073,'Скорее в Оргриммар!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Скорее в Оргриммар!',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (29074,'Время праздника','Привет, |3-6($c)! Тыквовин – время празднований и размышлений, хотя многие из нас уже давно забыли, почему это так. В самом деле, некоторые атрибуты празднования, например, Плетеный человек, были утеряны нами когда-то давно. Но теперь, когда Гилнеас присоединился к Альянсу, настало время возродить эту церемонию.$b$bОтправляйся к вратам Штормграда и поговори с Целестиной Урожайной. Она расскажет тебе о церемонии сжигания Плетеного человека подробнее.','Поговорите с Целестиной Урожайной за воротами Штормграда.','Праздник Плетеного человека имеет богатую историю. Приятно, что Альянс отмечает его вновь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Время праздника',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Привет, |3-6($c)! Тыквовин – время празднований и размышлений, хотя многие из нас уже давно забыли, почему это так. В самом деле, некоторые атрибуты празднования, например, Плетеный человек, были утеряны нами когда-то давно. Но теперь, когда Гилнеас присоединился к Альянсу, настало время возродить эту церемонию.$b$bОтправляйся к вратам Штормграда и поговори с Целестиной Урожайной. Она расскажет тебе о церемонии сжигания Плетеного человека подробнее.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Целестиной Урожайной за воротами Штормграда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Праздник Плетеного человека имеет богатую историю. Приятно, что Альянс отмечает его вновь.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29075,'Время обретать','Приветствую тебя, |3-6($c)! Плетеный человек, которого ты видишь, символизирует наш внутренний мир. Опаляющее его пламя – это очищающий огонь.$b$bПо поверьям в нем сгорают все наши беды и невзгоды. Огонь освобождает нас от тягостных дум в преддверии зимы. Приобщись к нашим традициям, |3-6($c).$b$bВозьми ветку из костра и брось ее в Плетеного человека.','Воспользуйтесь большим костром, разоженным перед Плетеным человеком.','Пусть тебя больше не терзают никакие тревоги. Каждый раз, как почувствуешь, что что-то тяготит тебя, вспоминай об Плетеном человеке.','Вернитесь к Целестине Урожайной к вратам Штормграда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Время обретать',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приветствую тебя, |3-6($c)! Плетеный человек, которого ты видишь, символизирует наш внутренний мир. Опаляющее его пламя – это очищающий огонь.$b$bПо поверьям в нем сгорают все наши беды и невзгоды. Огонь освобождает нас от тягостных дум в преддверии зимы. Приобщись к нашим традициям, |3-6($c).$b$bВозьми ветку из костра и брось ее в Плетеного человека.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь большим костром, разоженным перед Плетеным человеком.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Пусть тебя больше не терзают никакие тревоги. Каждый раз, как почувствуешь, что что-то тяготит тебя, вспоминай об Плетеном человеке.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Целестине Урожайной к вратам Штормграда.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29076,'Kevin\'s Test Quest','A testing quest','Just complete it.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Kevin\'s Test Quest',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','A testing quest',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Just complete it.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29077,'Курорт, который построил Ботт','Не могу в это поверить! Ты в самом деле $gсправился:справилась; с Огнеклювом! Прыгай ему на спину, лети к озеру и выбей захватчиков из воды! Убей их всех до единого!','Убейте 50 кипящих водных элементалей и 20 сумеречных призывателей.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Курорт, который построил Ботт',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не могу в это поверить! Ты в самом деле $gсправился:справилась; с Огнеклювом! Прыгай ему на спину, лети к озеру и выбей захватчиков из воды! Убей их всех до единого!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 50 кипящих водных элементалей и 20 сумеречных призывателей.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`,`questgivertargetname_loc8`) VALUES (29078,'Дать отпор!','Еще один рекрут из Альянса, да? Я – маршал Макбрайд, командующий этим гарнизоном. Нечасто мы видим |3-8($r) вроде тебя, но помощь нам не помешает.$b$bТы $gприбыл:прибыла; как раз вовремя. Оркам Черной горы удалось пробраться в Североземье через разлом в горе. Мои солдаты делают все возможное, чтобы выдворить орков отсюда, но, боюсь, преимущество не на нашей стороне.$b$bОтправляйся на северо-запад, в глубь леса, и убей атакующих воргов из клана Черной горы! Помоги моим солдатам!','Вернитесь к маршалу Макбрайду в Аббатство Североземья, что в Элвиннском лесу.','Боевой ворг клана Черной горы') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дать отпор!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Еще один рекрут из Альянса, да? Я – маршал Макбрайд, командующий этим гарнизоном. Нечасто мы видим |3-8($r) вроде тебя, но помощь нам не помешает.$b$bТы $gприбыл:прибыла; как раз вовремя. Оркам Черной горы удалось пробраться в Североземье через разлом в горе. Мои солдаты делают все возможное, чтобы выдворить орков отсюда, но, боюсь, преимущество не на нашей стороне.$b$bОтправляйся на северо-запад, в глубь леса, и убей атакующих воргов из клана Черной горы! Помоги моим солдатам!',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к маршалу Макбрайду в Аббатство Североземья, что в Элвиннском лесу.',`completedtext_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Боевой ворг клана Черной горы',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (29079,'Волки и овцы','Вернитесь к маршалу Макбрайду в Аббатство Североземья, что в Элвиннском лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Волки и овцы',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к маршалу Макбрайду в Аббатство Североземья, что в Элвиннском лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`questgivertargetname_loc8`) VALUES (29080,'В бой!','У меня срочное донесение от сержанта Виллема. Оказывается, орки Черной горы наняли гоблинов-убийц. Они поджидали наш батальон за аббатством. Виллем попросил меня прислать ему настоящего героя. Тебе придется им помочь, $n! $B$BТы найдешь сержанта Виллема к северу от аббатства у командной палатки. Иди же!','Да, мы и правда в западне. Я опасаюсь снова посылать туда солдат, так как и они могут погибнуть. Мне нужен доброволец, кто-то, кто рискнет своей жизнью!','Сержант Виллем') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В бой!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У меня срочное донесение от сержанта Виллема. Оказывается, орки Черной горы наняли гоблинов-убийц. Они поджидали наш батальон за аббатством. Виллем попросил меня прислать ему настоящего героя. Тебе придется им помочь, $n! $B$BТы найдешь сержанта Виллема к северу от аббатства у командной палатки. Иди же!',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, мы и правда в западне. Я опасаюсь снова посылать туда солдат, так как и они могут погибнуть. Мне нужен доброволец, кто-то, кто рискнет своей жизнью!',`offerrewardtext_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Сержант Виллем',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (29081,'Они подослали убийц','Убейте 8 гоблинов-убийц.','Это преподаст им урок! В следующий раз они дважды подумают, прежде чем наниматься к оркам.','Вернитесь к сержанту Виллему, находящемуся позади Аббатства Североземья, что в Элвиннском лесу.','Гоблин-убийца. Подлое маленькое создание!','Гоблин-убийца') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Они подослали убийц',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 гоблинов-убийц.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это преподаст им урок! В следующий раз они дважды подумают, прежде чем наниматься к оркам.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к сержанту Виллему, находящемуся позади Аббатства Североземья, что в Элвиннском лесу.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Гоблин-убийца. Подлое маленькое создание!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Гоблин-убийца',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29082,'Не убойся зла','Надеюсь, теперь ты осознаешь всю полноту силы Света. Он дарует нам надежду, брат, и изгоняет тьму! ДА БЛАГОСЛОВЕН БУДЕТ СВЕТ!','Вернитесь к брату Пакстону, находящемуся позади Аббатства Североземья, что в Элвиннском лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Не убойся зла',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Надеюсь, теперь ты осознаешь всю полноту силы Света. Он дарует нам надежду, брат, и изгоняет тьму! ДА БЛАГОСЛОВЕН БУДЕТ СВЕТ!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к брату Пакстону, находящемуся позади Аббатства Североземья, что в Элвиннском лесу.',`completedtext_loc8`);
