INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (29086,'Конкуренция-шмокуренция','Вернитесь к Пароклапану в лагерь Котельника, что в Северных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Конкуренция-шмокуренция',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Пароклапану в лагерь Котельника, что в Северных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29087,'Исследование грязи','Эй, $n, видишь эти следы? По прошествии прошлой ночи мы обнаружили их по всему лагерю! Ничего не пропало, но в наших вещах явно кто-то рылся. Грязные следы ведут в сторону Нефтяного болота.$b$bКто-то здесь что-то разнюхивал, и мне это совсем не нравится. Не $gмог:могла; бы ты отправиться на Нефтяное болото и что-нибудь выяснить? Может быть, тебе удастся найти другие такие же следы!','Изучите 5 грязных следов на Нефтяном болоте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Исследование грязи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эй, $n, видишь эти следы? По прошествии прошлой ночи мы обнаружили их по всему лагерю! Ничего не пропало, но в наших вещах явно кто-то рылся. Грязные следы ведут в сторону Нефтяного болота.$b$bКто-то здесь что-то разнюхивал, и мне это совсем не нравится. Не $gмог:могла; бы ты отправиться на Нефтяное болото и что-нибудь выяснить? Может быть, тебе удастся найти другие такие же следы!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Изучите 5 грязных следов на Нефтяном болоте.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29088,'Истребление гиен','Послушай, $n, у нас тут настоящая проблема. Гиены к западу от Нефтяного болота так расплодились, что начинают представлять для нас угрозу.$b$bЕсли мне придется провести еще одну ночь под их кошачий концерт, я просто лишусь рассудка! Вернон говорит, что эти гиены возможно даже утащили одну из его свиней. Так больше не может продолжаться.$b$bНе можешь ли ты уменьшить их численность? Их легко найти к западу отсюда.','Убейте 6 зубастых гиен.','Наконец-то! От этих грязных животных вреда куда больше, чем пользы.','Вернитесь к Котельнику в лагерь Котельника, что в Северных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Истребление гиен',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Послушай, $n, у нас тут настоящая проблема. Гиены к западу от Нефтяного болота так расплодились, что начинают представлять для нас угрозу.$b$bЕсли мне придется провести еще одну ночь под их кошачий концерт, я просто лишусь рассудка! Вернон говорит, что эти гиены возможно даже утащили одну из его свиней. Так больше не может продолжаться.$b$bНе можешь ли ты уменьшить их численность? Их легко найти к западу отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 6 зубастых гиен.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Наконец-то! От этих грязных животных вреда куда больше, чем пользы.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Котельнику в лагерь Котельника, что в Северных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29089,'Чудовищный слякоч!','Кем бы ни был тот, кто рыщет по Нефтяному болоту, это точно не человек. А если судить по найденным вами останкам, то это еще и довольно опасное создание.$b$bВы решаете двигаться по следам до самого дна озера и узнать, где же обитает это существо.','Исследуйте обиталище чудовищного слякоча и убейте любого, кто бы оттуда ни появился.','Вернитесь к Котельнику в лагерь Котельника, что в Северных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чудовищный слякоч!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кем бы ни был тот, кто рыщет по Нефтяному болоту, это точно не человек. А если судить по найденным вами останкам, то это еще и довольно опасное создание.$b$bВы решаете двигаться по следам до самого дна озера и узнать, где же обитает это существо.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Исследуйте обиталище чудовищного слякоча и убейте любого, кто бы оттуда ни появился.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Котельнику в лагерь Котельника, что в Северных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29090,'Пылающая угроза','Пока мы боремся с последствиями катаклизма, кто прикрывает наши спины? Пока наши предводители выходят с оружием в руках против Смертокрыла, клан Пылающего Клинка составляет планы, как добиться нашего падения.$b$bОни и сейчас собирают воинов и припасы на ферме, что к юго-западу отсюда. Я не собираюсь становиться их жертвой. Пришло время взять ситуацию в собственные руки.$b$b$n, поможешь мне защитить наши земли? Отправляйся туда и убей их солдат, пока еще не слишком поздно.','Убейте 8 членов клана Пылающего Клинка на ферме, что к юго-западу от вас.','Вернитесь к Брогору в лагерь Венаки Бенике, что в Северных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пылающая угроза',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пока мы боремся с последствиями катаклизма, кто прикрывает наши спины? Пока наши предводители выходят с оружием в руках против Смертокрыла, клан Пылающего Клинка составляет планы, как добиться нашего падения.$b$bОни и сейчас собирают воинов и припасы на ферме, что к юго-западу отсюда. Я не собираюсь становиться их жертвой. Пришло время взять ситуацию в собственные руки.$b$b$n, поможешь мне защитить наши земли? Отправляйся туда и убей их солдат, пока еще не слишком поздно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 членов клана Пылающего Клинка на ферме, что к юго-западу от вас.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Брогору в лагерь Венаки Бенике, что в Северных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (29091,'Освободительное движение') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Освободительное движение',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29092,'Сообщи старейшинам','Эти сведения должны быть переданы всем Служителям Земли. Не знаю, что делать дальше, но это может знать тот, кто тебя послал сюда. Пожалуйста, вернись к нему и узнай, что делать дальше – нельзя сидеть сложа руки!','Отправляйтесь в столицу и поговорите со старейшиной Служителей Земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сообщи старейшинам',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти сведения должны быть переданы всем Служителям Земли. Не знаю, что делать дальше, но это может знать тот, кто тебя послал сюда. Пожалуйста, вернись к нему и узнай, что делать дальше – нельзя сидеть сложа руки!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в столицу и поговорите со старейшиной Служителей Земли.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (29093,'Поездка к пропасти','Один мой друг рассказывал, что один механик из Западного края, который занимается паровыми танками, иногда разрешает прокатиться на чоппере. Так вот этому моему другу тоже как-то дали покататься!$B$BРядом с приютом тоже иногда проезжают люди на чопперах. Они такие громкие и быстрые! Я тоже хочу прокатиться!$B$BМы можем отправиться на Сторожевой холм в Западном крае и проехаться на чоппере? Ну, пожалуйста! Обещаю, что буду хорошо себя вести. А еще мы можем съездить к огромной дыре, оставшейся после изменения мира!','Отправляйтесь на Сторожевой холм в Западном крае, после чего вместе с сиротой совершите экскурсию к Бушующей пропасти на арендованном чоппере.','Поездка на чоппере к Бушующей пропасти','Вернитесь к своему подопечному ребенку-сироте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поездка к пропасти',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Один мой друг рассказывал, что один механик из Западного края, который занимается паровыми танками, иногда разрешает прокатиться на чоппере. Так вот этому моему другу тоже как-то дали покататься!$B$BРядом с приютом тоже иногда проезжают люди на чопперах. Они такие громкие и быстрые! Я тоже хочу прокатиться!$B$BМы можем отправиться на Сторожевой холм в Западном крае и проехаться на чоппере? Ну, пожалуйста! Обещаю, что буду хорошо себя вести. А еще мы можем съездить к огромной дыре, оставшейся после изменения мира!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь на Сторожевой холм в Западном крае, после чего вместе с сиротой совершите экскурсию к Бушующей пропасти на арендованном чоппере.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Поездка на чоппере к Бушующей пропасти',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к своему подопечному ребенку-сироте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29094,'Короткая дорога домой','Похоже, твоя работа здесь закончена, |3-6($c). Теперь лучше отправляйся обратно в Перекресток.$b$bК счастью, прототип моей "Серебряной пули" X-831 уже закончен, и она готова для испытаний. Как насчет того, чтобы оказать мне еще одну услугу? Заодно и прокатишься на ней.$b$bОдин из моих ассистентов будет тебя сопровождать. Тебя ждет чудный, чудный полет. Ракета на платформе за моей спиной. Запрыгивай на нее, когда будешь $gготов:готова;.','Прокатитесь на "Серебряной пуле" X-831.','Я уж думал, тебе конец. Рад узнать, что это не так.','Поговорите с Дарсоком Быстрым Ножом в Северных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Короткая дорога домой',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Похоже, твоя работа здесь закончена, |3-6($c). Теперь лучше отправляйся обратно в Перекресток.$b$bК счастью, прототип моей "Серебряной пули" X-831 уже закончен, и она готова для испытаний. Как насчет того, чтобы оказать мне еще одну услугу? Заодно и прокатишься на ней.$b$bОдин из моих ассистентов будет тебя сопровождать. Тебя ждет чудный, чудный полет. Ракета на платформе за моей спиной. Запрыгивай на нее, когда будешь $gготов:готова;.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Прокатитесь на "Серебряной пуле" X-831.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я уж думал, тебе конец. Рад узнать, что это не так.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Дарсоком Быстрым Ножом в Северных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (29095,'Разговор с Тхорком','Теперь, когда угроза миновала, тебе нужно возвращаться в Перекресток. Тхорк хочет поговорить с тобой.$b$bПрощай, $gдруг:подруга;.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разговор с Тхорком',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда угроза миновала, тебе нужно возвращаться в Перекресток. Тхорк хочет поговорить с тобой.$b$bПрощай, $gдруг:подруга;.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29096,'Сопровождение каравана в Мор\'шан','Рокко Хлыстоног ждет тебя у дороги, которая выходит из Перекрестка в северном направлении. Если ты $gготов:готова; сопровождать караван, сообщи об этом ему.','Поговорите с Рокко Хлыстоногом и отправляйтесь на север, сопровождая караван в Мор\'шан.','Поговорите с Рокко Хлыстоногом и отправляйтесь на север, сопровождая караван в Мор\'шан.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сопровождение каравана в Мор\'шан',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Рокко Хлыстоног ждет тебя у дороги, которая выходит из Перекрестка в северном направлении. Если ты $gготов:готова; сопровождать караван, сообщи об этом ему.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Рокко Хлыстоногом и отправляйтесь на север, сопровождая караван в Мор\'шан.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Рокко Хлыстоногом и отправляйтесь на север, сопровождая караван в Мор\'шан.',`completedtext_loc8`);
