INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (29100,'Дух Бвембы','Предупредите жителей Тернистой долины и найдите посланника Черного Копья.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дух Бвембы',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Предупредите жителей Тернистой долины и найдите посланника Черного Копья.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (29101,'Спасение черепашат','Маленькие черепашата такие милые! Даже несмотря на то, что иногда они кусаются.$b$b<Милуна смотрит на свой забинтованный палец.>$b$bНо у них маленькие ножки и поэтому передвигаются они очень медленно. Как им убежать от всех этих злых существ, атакующих Хиджал!$b$b<Милуна стискивает руки.>$b$bПОЖАЛУЙСТА, спаси их, $n! Собирай маленьких черепашат и бросай их в воду Пепельного озера. И не бойся пинать их, панцири у них крепкие.$b$bЗубы, впрочем, тоже, так что держи свои пальцы подальше от их ртов.','Столкните в воду 5 детей Тортоллы.','Вернитесь к Милуне в Святилище Малорна на горе Хиджал.','Бедные малыши…','Милуна') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спасение черепашат',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Маленькие черепашата такие милые! Даже несмотря на то, что иногда они кусаются.$b$b<Милуна смотрит на свой забинтованный палец.>$b$bНо у них маленькие ножки и поэтому передвигаются они очень медленно. Как им убежать от всех этих злых существ, атакующих Хиджал!$b$b<Милуна стискивает руки.>$b$bПОЖАЛУЙСТА, спаси их, $n! Собирай маленьких черепашат и бросай их в воду Пепельного озера. И не бойся пинать их, панцири у них крепкие.$b$bЗубы, впрочем, тоже, так что держи свои пальцы подальше от их ртов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Столкните в воду 5 детей Тортоллы.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Милуне в Святилище Малорна на горе Хиджал.',`completedtext_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Бедные малыши…',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Милуна',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`) VALUES (29102,'Направляясь в форт Ливингстон','Прежде всего нужно проверить наиболее уязвимое место. Я имею в виду форт Ливингстон.$b$bФорт Ливингстон окружен руинами троллей... это делает его легкой целью.$b$bМожет быть, мы найдем посланника там. Надеюсь, еще не слишком поздно.','Отправляйтесь в форт Ливингстон в Северной Тернистой долине, чтобы найти посланника Черного Копья.','Отправляйтесь в форт Ливингстон в Северной Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Направляясь в форт Ливингстон',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прежде всего нужно проверить наиболее уязвимое место. Я имею в виду форт Ливингстон.$b$bФорт Ливингстон окружен руинами троллей... это делает его легкой целью.$b$bМожет быть, мы найдем посланника там. Надеюсь, еще не слишком поздно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в форт Ливингстон в Северной Тернистой долине, чтобы найти посланника Черного Копья.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Отправляйтесь в форт Ливингстон в Северной Тернистой долине.',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29103,'Змеи и яд','Предупреждение посланника помогло. Мы успели собрать подкрепление для защиты. Но мы думали, что нам нужно будет сражаться с троллями.$b$bА вместо этого нас одолевают змеи!$b$bТакое чувство, что они повсюду. Мы едва держимся, и я боюсь, что будет еще хуже.$b$bПомоги нам. Уничтожь этих змей. И, может быть, твоя подруга-тролль может применить какую-нибудь магию, чтобы вылечить пострадавших от яда?','Убейте тропических гадюк и подведите Бвембу к отравленным искателям приключений, чтобы она вылечила их.','Вернитесь в форт Ливингстон.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Змеи и яд',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Предупреждение посланника помогло. Мы успели собрать подкрепление для защиты. Но мы думали, что нам нужно будет сражаться с троллями.$b$bА вместо этого нас одолевают змеи!$b$bТакое чувство, что они повсюду. Мы едва держимся, и я боюсь, что будет еще хуже.$b$bПомоги нам. Уничтожь этих змей. И, может быть, твоя подруга-тролль может применить какую-нибудь магию, чтобы вылечить пострадавших от яда?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте тропических гадюк и подведите Бвембу к отравленным искателям приключений, чтобы она вылечила их.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь в форт Ливингстон.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29104,'С нами духи','Что-то с этими змеями было не так, $n. В их яде я чувствую следы какого-то черного колдунства.$b$bМы можем воспользоваться костром в центре лагеря, чтобы провести ритуал.$b$bЧто бы ни стояло за нападениями змей, оно все еще контролирует их действия.$b$bЕдинственная проблема заключается в том, $n, что сейчас нахожусь в бестелесной форме, поэтому мне понадобится твоя помощь. Подготовь костер к ритуалу, а я уже займусь всем остальным.','Подготовьте костер в форте Ливингстон к ритуалу Бвембы.','Поговорите с Бвембой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','С нами духи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что-то с этими змеями было не так, $n. В их яде я чувствую следы какого-то черного колдунства.$b$bМы можем воспользоваться костром в центре лагеря, чтобы провести ритуал.$b$bЧто бы ни стояло за нападениями змей, оно все еще контролирует их действия.$b$bЕдинственная проблема заключается в том, $n, что сейчас нахожусь в бестелесной форме, поэтому мне понадобится твоя помощь. Подготовь костер к ритуалу, а я уже займусь всем остальным.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Подготовьте костер в форте Ливингстон к ритуалу Бвембы.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Бвембой.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`) VALUES (29105,'Эрнестуэй точно знает','Только этого нам не хватало. Гурубаши используют змей в своем наступлении. Что ж, хорошо, что мы хотя бы об этом знаем.$b$bГотов биться об заклад, что у охотников из экспедиции Эрнестуэя больше сведений. А если и нет, то уж, наверное, им известно, как справиться со змеями.$b$bОтправляйся туда и расскажи им о том, что ты $gвидел:видела;. Пусть они узнают о том, что тролли используют змей вместо оружия.','Предупредите охотников экспедиции Эрнестуэя в Северной Тернистой долине.','Отправляйтесь в лагерь экспедиции Эрнестуэя.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Эрнестуэй точно знает',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Только этого нам не хватало. Гурубаши используют змей в своем наступлении. Что ж, хорошо, что мы хотя бы об этом знаем.$b$bГотов биться об заклад, что у охотников из экспедиции Эрнестуэя больше сведений. А если и нет, то уж, наверное, им известно, как справиться со змеями.$b$bОтправляйся туда и расскажи им о том, что ты $gвидел:видела;. Пусть они узнают о том, что тролли используют змей вместо оружия.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Предупредите охотников экспедиции Эрнестуэя в Северной Тернистой долине.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Отправляйтесь в лагерь экспедиции Эрнестуэя.',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (29106,'Самый большой алмаз в мире!','Я слышал, что Магни Бронзобород был королем Стальгорна и превратился в огромный алмаз! Это правда? Как это может быть, чтобы вот так взять и превратиться в здоровенный камень? Может, для этого нужно быть королем, поэтому ни у кого раньше это и не получалось?$B$BДавай посмотрим на Магни! Он находится где-то в Старом Стальгорне под Высоким троном.','Посетите короля Магни в Старом Стальгорне.','Вернитесь к своему подопечному ребенку-сироте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Самый большой алмаз в мире!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я слышал, что Магни Бронзобород был королем Стальгорна и превратился в огромный алмаз! Это правда? Как это может быть, чтобы вот так взять и превратиться в здоровенный камень? Может, для этого нужно быть королем, поэтому ни у кого раньше это и не получалось?$B$BДавай посмотрим на Магни! Он находится где-то в Старом Стальгорне под Высоким троном.',`details_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Посетите короля Магни в Старом Стальгорне.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к своему подопечному ребенку-сироте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (29107,'Малфурион вернулся!','Я слышал, что Малфурион Ярость Бури вернулся из Изумрудного Сна. Не знаю, где это, но похоже, что далеко.$B$BВ любом случае, он должен быть рядом с верховной жрицей где-то на верхнем ярусе Храма Луны в Дарнасе. Как думаешь, мы можем с ним встретиться? Ведь это же величайший друид в истории Азерота.','Отведите ребенка-сироту в Храм Луны, что в Дарнасе. Обязательно позовите своего подопечного, если по прибытии его не окажется рядом.','Отведите своего подопечного-сироту к Малфуриону Ярости Бури.','Вернитесь к своему подопечному ребенку-сироте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Малфурион вернулся!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я слышал, что Малфурион Ярость Бури вернулся из Изумрудного Сна. Не знаю, где это, но похоже, что далеко.$B$BВ любом случае, он должен быть рядом с верховной жрицей где-то на верхнем ярусе Храма Луны в Дарнасе. Как думаешь, мы можем с ним встретиться? Ведь это же величайший друид в истории Азерота.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отведите ребенка-сироту в Храм Луны, что в Дарнасе. Обязательно позовите своего подопечного, если по прибытии его не окажется рядом.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Отведите своего подопечного-сироту к Малфуриону Ярости Бури.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к своему подопечному ребенку-сироте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (29108,'Mor\'shan Test Quest') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Mor\'shan Test Quest',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29109,'Сопровождение каравана в Мор\'шан','В Ясеневом лесу продолжается беспощадная битва. Наши войска на заставе Мор\'шан отчаянно нуждаются в припасах и подкреплении.$b$bМы отправили на север караван с большим запасом продовольствия и медикаментов, и мне $gнужен:нужна:c; |3-6($c) вроде тебя, чтобы сопровождать его.$b$bРокко Хлыстоног ждет тебя у дороги, которая выходит из Перекрестка в северном направлении. Сообщи ему, когда будешь $gготов:готова; сопровождать караван.','Поговорите с Рокко Хлыстоногом и отправляйтесь на север, сопровождая караван в Мор\'шан.','Поговорите с Нагалой Хлыстоног у подножия Вершины Багрового Тумана, что в Северных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сопровождение каравана в Мор\'шан',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В Ясеневом лесу продолжается беспощадная битва. Наши войска на заставе Мор\'шан отчаянно нуждаются в припасах и подкреплении.$b$bМы отправили на север караван с большим запасом продовольствия и медикаментов, и мне $gнужен:нужна:c; |3-6($c) вроде тебя, чтобы сопровождать его.$b$bРокко Хлыстоног ждет тебя у дороги, которая выходит из Перекрестка в северном направлении. Сообщи ему, когда будешь $gготов:готова; сопровождать караван.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Рокко Хлыстоногом и отправляйтесь на север, сопровождая караван в Мор\'шан.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Нагалой Хлыстоног у подножия Вершины Багрового Тумана, что в Северных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29110,'Спасение каравана в Мор\'шан','Они напали на караван в самом конце пути и схватили Балгора!$b$bПрипасы из каравана жизненно необходимы нам для победы над Альянсом в Ясеневом лесу. А Балгор... Если с моим дорогим братишкой что-нибудь случится, я своими собственными руками разорву в клочки каждого из Пылающего Клинка.$b$b$n, спаси Балгора и захваченный караван. К северу от нас начинается дорога, иди по ней, пока не доберешься до Вершины Багрового Тумана. И пусть ни один из этих псов Пылающего Клинка не останется в живых.','Спасите Балгора Хлыстонога.','Спасите Балгора Хлыстонога.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спасение каравана в Мор\'шан',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Они напали на караван в самом конце пути и схватили Балгора!$b$bПрипасы из каравана жизненно необходимы нам для победы над Альянсом в Ясеневом лесу. А Балгор... Если с моим дорогим братишкой что-нибудь случится, я своими собственными руками разорву в клочки каждого из Пылающего Клинка.$b$b$n, спаси Балгора и захваченный караван. К северу от нас начинается дорога, иди по ней, пока не доберешься до Вершины Багрового Тумана. И пусть ни один из этих псов Пылающего Клинка не останется в живых.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Спасите Балгора Хлыстонога.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Спасите Балгора Хлыстонога.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29111,'Прибытие каравана в Мор\'шан','Ты $gразворошил:разворошила; гнездо Пылающего Клинка. Наши разведчики докладывают, что они собирают силы для атаки.$b$bТебе нужно довести караван до того, как она начнется. Припасы собраны, кодо восстановили силы. Надеюсь, ты не будешь возражать, если я немного улучшу твое оружие?$b$bЕсли кто-то встанет на твоем пути, стреляй без разговоров.$b$bТоропись! Они уже близко! Сообщи мне, когда будешь $gготов:готова; к отправлению.','Защитите караван, движущийся в Мор\'шан','Поговорите с Кадраком на Заставе Мор\'шан, что в Северных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прибытие каравана в Мор\'шан',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gразворошил:разворошила; гнездо Пылающего Клинка. Наши разведчики докладывают, что они собирают силы для атаки.$b$bТебе нужно довести караван до того, как она начнется. Припасы собраны, кодо восстановили силы. Надеюсь, ты не будешь возражать, если я немного улучшу твое оружие?$b$bЕсли кто-то встанет на твоем пути, стреляй без разговоров.$b$bТоропись! Они уже близко! Сообщи мне, когда будешь $gготов:готова; к отправлению.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Защитите караван, движущийся в Мор\'шан',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Кадраком на Заставе Мор\'шан, что в Северных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29112,'Демоново семя','Послушай, $n, уходить пока еще рано. Мне удалось подслушать, как они обсуждали свои планы во время приготовления к ритуальному жертвоприношению.$b$bОни собираются воспользоваться мощным артефактом, который называют демоновым семенем, чтобы провести массированную атаку против Орды. Они хранят демоново семя в этой пещере и бдительно его охраняют.$b$bЕсли тебе удастся заполучить семя, отнеси его моей сестре Нагале. Она разберется, что с ним делать.','Добудьте демоново семя.','Отнесите демоново семя Нагале Хлыстоног. Ее можно найти у подножия Вершины Багрового Тумана, что в Северных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Демоново семя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Послушай, $n, уходить пока еще рано. Мне удалось подслушать, как они обсуждали свои планы во время приготовления к ритуальному жертвоприношению.$b$bОни собираются воспользоваться мощным артефактом, который называют демоновым семенем, чтобы провести массированную атаку против Орды. Они хранят демоново семя в этой пещере и бдительно его охраняют.$b$bЕсли тебе удастся заполучить семя, отнеси его моей сестре Нагале. Она разберется, что с ним делать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте демоново семя.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите демоново семя Нагале Хлыстоног. Ее можно найти у подножия Вершины Багрового Тумана, что в Северных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (29114,'Охота на охотника','Мы уже долгие дни пытаемся отбиться от змей, $n. Однако змеи – это сущий пустяк по сравнению с тем, что скрывается в джунглях.$b$bНа нас идет охота.$b$bКрупная пантера по имени Маути утаскивает наших людей в чащу.$b$bМы послали Грента Лютомолота, одного из наших лучших охотников, чтобы он поймал этого зверя.$b$bЛютомолот отправился куда-то на восток. Попробуй поискать его там.','Найдите Грента Лютомолота в Северной Тернистой долине.','Тс-с-с…') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота на охотника',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы уже долгие дни пытаемся отбиться от змей, $n. Однако змеи – это сущий пустяк по сравнению с тем, что скрывается в джунглях.$b$bНа нас идет охота.$b$bКрупная пантера по имени Маути утаскивает наших людей в чащу.$b$bМы послали Грента Лютомолота, одного из наших лучших охотников, чтобы он поймал этого зверя.$b$bЛютомолот отправился куда-то на восток. Попробуй поискать его там.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Грента Лютомолота в Северной Тернистой долине.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тс-с-с…',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`) VALUES (29115,'Месть охотника','Я охочусь на нее... она охотится на нас.$b$bЕе зовут Маути. Она умна. Но, убив моего брата, она допустила огромную ошибку. За это она поплатится. Старик Лютомолот напал на ее след.$b$bЯ видел, как она рыщет вблизи от Лагеря Курцена. Если мы будем действовать быстро, мы справимся с ней.$b$bТы $gготов:готова;, $n?','Грент Лютомолот хочет, чтобы вы убили Маути.','Приведите Грента Лютомолота к трупу Маути.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Месть охотника',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я охочусь на нее... она охотится на нас.$b$bЕе зовут Маути. Она умна. Но, убив моего брата, она допустила огромную ошибку. За это она поплатится. Старик Лютомолот напал на ее след.$b$bЯ видел, как она рыщет вблизи от Лагеря Курцена. Если мы будем действовать быстро, мы справимся с ней.$b$bТы $gготов:готова;, $n?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Грент Лютомолот хочет, чтобы вы убили Маути.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Приведите Грента Лютомолота к трупу Маути.',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29116,'Преследовать кошку','Теперь понятно, почему Маути казалась меньше. Настоящая Маути преследовала Грента Лютомолота, но он как опытный охотник всю дорогу пускал сигнальные ракеты, чтобы мы могли отыскать его. Найди Лютомолота, пока еще не слишком поздно!','Узнайте, куда Маути утащила Грента Лютомолота.','Ну вот мы и нашли их… Охотник в пещере. Зверь… с ним что-то не так…','Поговорите с Бвембой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Преследовать кошку',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь понятно, почему Маути казалась меньше. Настоящая Маути преследовала Грента Лютомолота, но он как опытный охотник всю дорогу пускал сигнальные ракеты, чтобы мы могли отыскать его. Найди Лютомолота, пока еще не слишком поздно!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Узнайте, куда Маути утащила Грента Лютомолота.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну вот мы и нашли их… Охотник в пещере. Зверь… с ним что-то не так…',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Бвембой.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (29117,'Давай запустим змея!','Попечительница сирот однажды водила нас погулять, и я видел одного гнома с целой тележкой разных игрушек. У него там были куклы, медные болиды, кожаные мячи и еще воздушные змеи. Мне всегда так хотелось запустить воздушного змея в виде дракона! Попечительница говорила, что я могу купить его на свои деньги – когда накоплю достаточно. Но до этого еще так долго ждать.$b$bТого гнома звали Крэггл Головодерг или что-то вроде этого. Если мы его встретим, можно мы купим у него воздушных змеев и запустим их вместе? Я видел этого гнома возле каналов, у Торгового квартала.','Купите упаковку с двумя воздушными змеями у Крэггла Головодерга в Штормграде и запустите воздушных змеев вместе со своим подопечным ребенком-сиротой. Обязательно позовите сироту, если по прибытии его не окажется рядом.','Запустите воздушных змеев вместе со своим подопечным-сиротой','Вернитесь к своему подопечному ребенку-сироте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Давай запустим змея!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Попечительница сирот однажды водила нас погулять, и я видел одного гнома с целой тележкой разных игрушек. У него там были куклы, медные болиды, кожаные мячи и еще воздушные змеи. Мне всегда так хотелось запустить воздушного змея в виде дракона! Попечительница говорила, что я могу купить его на свои деньги – когда накоплю достаточно. Но до этого еще так долго ждать.$b$bТого гнома звали Крэггл Головодерг или что-то вроде этого. Если мы его встретим, можно мы купим у него воздушных змеев и запустим их вместе? Я видел этого гнома возле каналов, у Торгового квартала.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Купите упаковку с двумя воздушными змеями у Крэггла Головодерга в Штормграде и запустите воздушных змеев вместе со своим подопечным ребенком-сиротой. Обязательно позовите сироту, если по прибытии его не окажется рядом.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Запустите воздушных змеев вместе со своим подопечным-сиротой',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к своему подопечному ребенку-сироте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29118,'Преследовать кошку','Настоящая Маути преследовала Грента Лютомолота, но он как опытный охотник всю дорогу пускал сигнальные ракеты, чтобы мы могли отыскать его. Найди Лютомолота, пока еще не слишком поздно!','Узнайте, куда Маути утащила Грента Лютомолота.','Поговорите с Бвембой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Преследовать кошку',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Настоящая Маути преследовала Грента Лютомолота, но он как опытный охотник всю дорогу пускал сигнальные ракеты, чтобы мы могли отыскать его. Найди Лютомолота, пока еще не слишком поздно!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Узнайте, куда Маути утащила Грента Лютомолота.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Бвембой.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (29119,'Детям – мороженое!','В Штормграде открылся магазин, где продают новое мороженое, совсем не такое, как раньше. Его делают маги! Нет, дело не в том, что оно исчезает, если его не съесть за пятнадцать минут.$B$BОно очень вкусное. Давай попробуем!$B$BМне рассказывали о нем другие ребята, они говорили, что магазин называется "Конус холода" и что он находится где-то рядом с таверной "Печальный отшельник" в Квартале Магов.','Купите мороженое в "Конусе холода" и угостите им своего подопечного-сироту.','Отведите сироту в магазин мороженого.','Вернитесь к своему подопечному ребенку-сироте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Детям – мороженое!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В Штормграде открылся магазин, где продают новое мороженое, совсем не такое, как раньше. Его делают маги! Нет, дело не в том, что оно исчезает, если его не съесть за пятнадцать минут.$B$BОно очень вкусное. Давай попробуем!$B$BМне рассказывали о нем другие ребята, они говорили, что магазин называется "Конус холода" и что он находится где-то рядом с таверной "Печальный отшельник" в Квартале Магов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Купите мороженое в "Конусе холода" и угостите им своего подопечного-сироту.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Отведите сироту в магазин мороженого.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к своему подопечному ребенку-сироте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29120,'Маути','У меня есть ощущение, что с этой пантерой что-то не так, $n. Все это кажется противоестественным. Мне нужно провести некоторые ритуалы. Убей Маути, $n, и после этого мы посмотрим, что удастся выяснить.','Приведите Бвембу к останкам Маути.','Это чудовищное создание – дело рук верховной жрицы Килнары. Не к добру это. Нужно проверить, как там дворф, а затем узнать, не требуется ли еще где-то наша помощь.','Поговорите с Бвембой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Маути',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У меня есть ощущение, что с этой пантерой что-то не так, $n. Все это кажется противоестественным. Мне нужно провести некоторые ритуалы. Убей Маути, $n, и после этого мы посмотрим, что удастся выяснить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Приведите Бвембу к останкам Маути.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это чудовищное создание – дело рук верховной жрицы Килнары. Не к добру это. Нужно проверить, как там дворф, а затем узнать, не требуется ли еще где-то наша помощь.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Бвембой.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29121,'Похорони меня в сапогах...','А... это ты, $n. Маути... Она мертва? Тогда мой брат отомщен. Теперь у меня к тебе лишь одна просьба... Эта мелкая пакость царапает мои босые ноги. Нельзя дворфу отправляться в могилу без обуви.$b$bПожалуйста, похорони меня в сапогах.','Принесите сапоги Грента Лютомолота.','Спасибо тебе, друг.$B$BПапочка?..$B$BЭто… ты?..$B$B$B$B$B…','Вернитесь к Гренту Лютомолоту.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Похорони меня в сапогах...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А... это ты, $n. Маути... Она мертва? Тогда мой брат отомщен. Теперь у меня к тебе лишь одна просьба... Эта мелкая пакость царапает мои босые ноги. Нельзя дворфу отправляться в могилу без обуви.$b$bПожалуйста, похорони меня в сапогах.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите сапоги Грента Лютомолота.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо тебе, друг.$B$BПапочка?..$B$BЭто… ты?..$B$B$B$B$B…',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гренту Лютомолоту.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (29122,'Эхо Немесиса','<В вашей голове словно прекрасная музыка звучит голос Милуны.>$b$bПомнишь эту ужасную огненную черепаху из Огненных Просторов, Немесиса? Он уже мертв (ура!), но его эхо все еще пытается пробиться на гору Хиджал.$b$bОтправляйся к Пепельному озеру и поговори там с моим другом, Тугой. Сообщи Туге, когда будешь $gготов:готова; сразиться с эхом Немесиса, и черепахи сделают так, что он появится в этом мире. И ты сможешь задать ему! Уничтожить его!$b$bВ случае опасности прячься в панцирь Туги.','Поговорите с Тугой, чтобы призвать и убить Немесиса. Чтобы защититься от "Раскаленного неистовства" Немесиса, прячьтесь под панцирь Туги.','Ура! Ты только что сам убедился, что когда за дело берется черепаха…$B$B<Милуна отвлекается на пролетающую бабочку и так и не заканчивает фразу.>','Вернитесь к Милуне в Святилище Малорна на горе Хиджал.','Частицы духа Немесиса все еще странствуют между нашими измерениями.','Немесис') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Эхо Немесиса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<В вашей голове словно прекрасная музыка звучит голос Милуны.>$b$bПомнишь эту ужасную огненную черепаху из Огненных Просторов, Немесиса? Он уже мертв (ура!), но его эхо все еще пытается пробиться на гору Хиджал.$b$bОтправляйся к Пепельному озеру и поговори там с моим другом, Тугой. Сообщи Туге, когда будешь $gготов:готова; сразиться с эхом Немесиса, и черепахи сделают так, что он появится в этом мире. И ты сможешь задать ему! Уничтожить его!$b$bВ случае опасности прячься в панцирь Туги.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Тугой, чтобы призвать и убить Немесиса. Чтобы защититься от "Раскаленного неистовства" Немесиса, прячьтесь под панцирь Туги.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ура! Ты только что сам убедился, что когда за дело берется черепаха…$B$B<Милуна отвлекается на пролетающую бабочку и так и не заканчивает фразу.>',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Милуне в Святилище Малорна на горе Хиджал.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Частицы духа Немесиса все еще странствуют между нашими измерениями.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Немесис',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29123,'Кара, настигающая пламя','Из всех задач, которые стоят перед нами здесь, на Хиджале, самая спешная довольно проста: уничтожить захватчиков. Природа огня такова, что он пожирает все на своем пути. Стоит хоть ненадолго ослабить защиту, и он уничтожит все в мгновение ока.$b$bУбей всех захватчиков, каких увидишь. Каждый побежденный враг дает Хиджалу еще немного времени.','Убейте 6 любых захватчиков с Огненных Просторов в Молодом лесу или в Гнезде Сетрии.','Вернитесь к Мате Коготь в Святилище Малорна, что на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кара, настигающая пламя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Из всех задач, которые стоят перед нами здесь, на Хиджале, самая спешная довольно проста: уничтожить захватчиков. Природа огня такова, что он пожирает все на своем пути. Стоит хоть ненадолго ослабить защиту, и он уничтожит все в мгновение ока.$b$bУбей всех захватчиков, каких увидишь. Каждый побежденный враг дает Хиджалу еще немного времени.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 6 любых захватчиков с Огненных Просторов в Молодом лесу или в Гнезде Сетрии.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мате Коготь в Святилище Малорна, что на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29124,'Известить Лагерь Повстанцев','Эта смерть не должна быть напрасной, $n. Мы узнали, что Килнара стоит за всем, что происходит в округе. В этом нет ничего хорошего.$b$bСтоит заглянуть в Лагерь Повстанцев, что к северу отсюда. Может быть, мой связной там.','Доберитесь до Лагеря Повстанцев.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Известить Лагерь Повстанцев',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эта смерть не должна быть напрасной, $n. Мы узнали, что Килнара стоит за всем, что происходит в округе. В этом нет ничего хорошего.$b$bСтоит заглянуть в Лагерь Повстанцев, что к северу отсюда. Может быть, мой связной там.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доберитесь до Лагеря Повстанцев.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (29125,'Среди деревьев','Призрачные белые олени, в которых заключены частицы духа Малорна, все еще бегают в этих лесах. Малорна больше нет с нами, но частицы его духа могут нам пригодиться.$b$bТы найдешь их к востоку, среди деревьев. Если тебе удастся подойти к оленю достаточно близко, он поделится с тобой своей силой.$b$bДа, и возьми вот это. Позже тебе это понадобится.','Поймайте 3 частицы духа Малорна, подойдя к ним достаточно близко.','Вернитесь к Мате Коготь в Святилище Малорна, что на горе Хиджал.','Уже сейчас я чувствую в тебе силу оленя.','Мата Коготь') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Среди деревьев',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Призрачные белые олени, в которых заключены частицы духа Малорна, все еще бегают в этих лесах. Малорна больше нет с нами, но частицы его духа могут нам пригодиться.$b$bТы найдешь их к востоку, среди деревьев. Если тебе удастся подойти к оленю достаточно близко, он поделится с тобой своей силой.$b$bДа, и возьми вот это. Позже тебе это понадобится.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поймайте 3 частицы духа Малорна, подойдя к ним достаточно близко.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мате Коготь в Святилище Малорна, что на горе Хиджал.',`completedtext_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Уже сейчас я чувствую в тебе силу оленя.',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Мата Коготь',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (29126,'Сила Малорна','<Голос Маты Коготь продолжает.>$b$bПортал, который открылся к востоку от этого места, охраняет могущественный поджигатель по имени Галенж. Чтобы победить его, нам понадобится вся сила Малорна.$b$bПомнишь, посох, который я дала тебе? Воткни его в кучу пепла перед входом в портал. А затем молись, чтобы Малорн пришел тебе на помощь.','Воспользуйтесь посохом стража, чтобы призвать Галенжа, и убейте его.','Галенж Непобедимый побежден. Но это еще не конец.','Вернитесь к Мате Коготь в Святилище Малорна, что на горе Хиджал.','Дождитесь, когда Малорн атакует, а затем нападите на Галенжа.','Галенж Непобедимый') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сила Малорна',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Голос Маты Коготь продолжает.>$b$bПортал, который открылся к востоку от этого места, охраняет могущественный поджигатель по имени Галенж. Чтобы победить его, нам понадобится вся сила Малорна.$b$bПомнишь, посох, который я дала тебе? Воткни его в кучу пепла перед входом в портал. А затем молись, чтобы Малорн пришел тебе на помощь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь посохом стража, чтобы призвать Галенжа, и убейте его.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Галенж Непобедимый побежден. Но это еще не конец.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мате Коготь в Святилище Малорна, что на горе Хиджал.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Дождитесь, когда Малорн атакует, а затем нападите на Галенжа.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Галенж Непобедимый',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29127,'Кара, настигающая пламя','Из всех задач, которые стоят перед нами здесь, на Хиджале, самая спешная довольно проста: уничтожить захватчиков. Природа огня такова, что он пожирает все на своем пути. Стоит хоть ненадолго ослабить защиту, и он уничтожит все в мгновение ока.$b$bУбей всех захватчиков, каких увидишь. Каждый побежденный враг дает Хиджалу еще немного времени.','Убейте 8 любых захватчиков с Огненных Просторов в Молодом лесу или в Гнезде Сетрии.','Вернитесь к Мате Коготь в Святилище Малорна, что на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кара, настигающая пламя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Из всех задач, которые стоят перед нами здесь, на Хиджале, самая спешная довольно проста: уничтожить захватчиков. Природа огня такова, что он пожирает все на своем пути. Стоит хоть ненадолго ослабить защиту, и он уничтожит все в мгновение ока.$b$bУбей всех захватчиков, каких увидишь. Каждый побежденный враг дает Хиджалу еще немного времени.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 любых захватчиков с Огненных Просторов в Молодом лесу или в Гнезде Сетрии.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мате Коготь в Святилище Малорна, что на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29128,'Защитники Хиджала','Нам нужно нанести удар по лагерю противника, расположенному у Гнезда Сетрии. Приспешники Рагнароса используют его в качестве опорного пункта, откуда намереваются проникнуть за пределы Хиджала. Я предоставлю в твое распоряжение небольшой отряд, чтобы разобраться с этой проблемой.$b$bТебе будут помогать специально отобранные элитные бойцы. Отправляйся в Гнездо Сетрии. Бойцы будут ждать тебя там. Положи конец нападениям элементалей.','Убейте 6 огненных чудищ или повелителей пламени.','Отлично сработано, солдат. Даже несмотря на то, что ситуация в Огненных Просторах критическая, мы не должны забывать о благополучии Хиджала.$B$BПоговори с моим братом и завтра, наверняка он сможет выделить для тебя еще один отряд.','Сообщите о своем прибытии генералу Талдрис Закат Луны на Аванпосте Малфуриона, что на Огненной передовой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Защитники Хиджала',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нам нужно нанести удар по лагерю противника, расположенному у Гнезда Сетрии. Приспешники Рагнароса используют его в качестве опорного пункта, откуда намереваются проникнуть за пределы Хиджала. Я предоставлю в твое распоряжение небольшой отряд, чтобы разобраться с этой проблемой.$b$bТебе будут помогать специально отобранные элитные бойцы. Отправляйся в Гнездо Сетрии. Бойцы будут ждать тебя там. Положи конец нападениям элементалей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 6 огненных чудищ или повелителей пламени.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично сработано, солдат. Даже несмотря на то, что ситуация в Огненных Просторах критическая, мы не должны забывать о благополучии Хиджала.$B$BПоговори с моим братом и завтра, наверняка он сможет выделить для тебя еще один отряд.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Сообщите о своем прибытии генералу Талдрис Закат Луны на Аванпосте Малфуриона, что на Огненной передовой.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`questgivertargetname_loc8`,`questturntargetname_loc8`) VALUES (29129,'Легендарная миссия','Анахронос','Анахронос') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Легендарная миссия',`title_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Анахронос',`questgivertargetname_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Анахронос',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (29131,'Защита Лагеря Повстанцев','Мы в беде, $n. Твой друг тролль был здесь и предупреждал нас, но мы и подумать не могли, что наши дела будут так плохи.$b$bМы изо всех сил стараемся выстоять против этих троллей. Но нам пригодится любая помощь.','Сдерживайте нападение на Лагерь Повстанцев в течение трех минут.','Помогите защитить лагерь','Поговорите с лейтенантом Дореном.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Защита Лагеря Повстанцев',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы в беде, $n. Твой друг тролль был здесь и предупреждал нас, но мы и подумать не могли, что наши дела будут так плохи.$b$bМы изо всех сил стараемся выстоять против этих троллей. Но нам пригодится любая помощь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сдерживайте нападение на Лагерь Повстанцев в течение трех минут.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Помогите защитить лагерь',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с лейтенантом Дореном.',`completedtext_loc8`);
