INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (29133,'На раскопки') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На раскопки',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (29134,'Заглянуть в будущее','Слушай меня внимательно, |3-6($c). Несмотря на то что мы только взялись за дело, наше время уже на исходе. Сложно даже представить себе, что нас ждет в случае неудачи.$b$bС помощью могущественных чар от меня скрыли событие из прошлого. Однако я ясно вижу его последствия.$b$bСоберись, $gсмертный:смертная;, и увидь будущее Азерота.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Заглянуть в будущее',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слушай меня внимательно, |3-6($c). Несмотря на то что мы только взялись за дело, наше время уже на исходе. Сложно даже представить себе, что нас ждет в случае неудачи.$b$bС помощью могущественных чар от меня скрыли событие из прошлого. Однако я ясно вижу его последствия.$b$bСоберись, $gсмертный:смертная;, и увидь будущее Азерота.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29135,'Вневременное око','Я понимаю, что тебя мучают вопросы, и должен признать, что я разделяю твои сомнения... хоть это и нетипично для меня и даже тревожно.$b$bПока я пытаюсь найти какие-то следы этого темного дела, ты $gдолжен:должна; помочь мне в создании ока – и чтобы доказать, что ты чего-то стоишь, и чтобы у нас появилось орудие, которое поможет в поисках разгадки.$b$bОтправляйся в мир огня, |3-6($c), и собери там извечные угли. Принеси их мне вместе с песками времени, и я сделаю око.','Отправляйтесь в Огненные Просторы и соберите 25 извечных углей и 3 песка времени.','Ты прекрасно справился с задачей.$B$BА теперь не мешай мне, пока я, используя древнюю магию, буду создавать вневременное око.','Поговорите с Анахроносом в Пещерах Времени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вневременное око',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я понимаю, что тебя мучают вопросы, и должен признать, что я разделяю твои сомнения... хоть это и нетипично для меня и даже тревожно.$b$bПока я пытаюсь найти какие-то следы этого темного дела, ты $gдолжен:должна; помочь мне в создании ока – и чтобы доказать, что ты чего-то стоишь, и чтобы у нас появилось орудие, которое поможет в поисках разгадки.$b$bОтправляйся в мир огня, |3-6($c), и собери там извечные угли. Принеси их мне вместе с песками времени, и я сделаю око.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Огненные Просторы и соберите 25 извечных углей и 3 песка времени.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты прекрасно справился с задачей.$B$BА теперь не мешай мне, пока я, используя древнюю магию, буду создавать вневременное око.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Анахроносом в Пещерах Времени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29137,'Брешь в обороне','Лавовые землерои вылезают из земли у нас в тылу, уничтожают наши укрепления и дают возможность проникнуть за ними элементалям. Их можно найти в любой части передовой к северу отсюда и на Пепельных полях.$b$bСделай так, чтобы они убрались обратно в свои норы.','Убейте 5 лавовых землероев.','Спасибо тебе за помощь. Благодаря ей мы получили время, которое нам было необходимо, чтобы восстановить укрепления. Без тебя нам было бы гораздо тяжелее.','Вернитесь к генералу Талдрис Закат Луны на Аванпост Малфуриона, что на Огненной передовой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Брешь в обороне',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Лавовые землерои вылезают из земли у нас в тылу, уничтожают наши укрепления и дают возможность проникнуть за ними элементалям. Их можно найти в любой части передовой к северу отсюда и на Пепельных полях.$b$bСделай так, чтобы они убрались обратно в свои норы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 5 лавовых землероев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо тебе за помощь. Благодаря ей мы получили время, которое нам было необходимо, чтобы восстановить укрепления. Без тебя нам было бы гораздо тяжелее.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к генералу Талдрис Закат Луны на Аванпост Малфуриона, что на Огненной передовой.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29138,'Пострадавшие от огня','На поле боя остаются наши раненые, а у сражающихся друидов не хватает времени, чтобы помочь им. Прошу тебя, отправляйся на север, к Пепельным полям, и вылечи их раны, хотя бы настолько, чтобы они сами смогли добраться до безопасного места.$b$bЕсли у тебя нет бинтов и ты не знаешь никаких исцеляющих заклинаний, то Райна сделала отличную мазь. Она поставит раненых на ноги.','Исцелите 8 раненых защитников Хиджала.','Я видел, как уже после твоего ухода, с поля боя возвращались раненые. Твоя помощь была очень кстати. Спасибо тебе.','Вернитесь к капитану Железному Лесу на Аванпост Малфуриона на Огненной передовой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пострадавшие от огня',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На поле боя остаются наши раненые, а у сражающихся друидов не хватает времени, чтобы помочь им. Прошу тебя, отправляйся на север, к Пепельным полям, и вылечи их раны, хотя бы настолько, чтобы они сами смогли добраться до безопасного места.$b$bЕсли у тебя нет бинтов и ты не знаешь никаких исцеляющих заклинаний, то Райна сделала отличную мазь. Она поставит раненых на ноги.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Исцелите 8 раненых защитников Хиджала.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я видел, как уже после твоего ухода, с поля боя возвращались раненые. Твоя помощь была очень кстати. Спасибо тебе.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Железному Лесу на Аванпост Малфуриона на Огненной передовой.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29139,'Буйная растительность','Наши солдаты делают все, что в их силах, чтобы отбросить элементалей, но ведь их силы не бесконечны. Нам нужно что-то предпринять, чтобы ослабить эту атаку.$b$bОтправляйся на Пепельные поля, что к северу отсюда, найди подходящие кучки пепла и посади в них вот эти семена. Из них вырастет смертоносная лоза, которая задержит наших врагов. Это хоть как-то поможет.','Посадите 5 семян удавливающей лозы в кучки пепла на Пепельных полях.','Мы выиграем эту битву. Чего мы нам это ни стоило, мы не позволим этим элементалям снова вернуться на Хиджал.','Вернитесь к Райне Песни Пера на Аванпост Малфуриона на Огненной передовой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Буйная растительность',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наши солдаты делают все, что в их силах, чтобы отбросить элементалей, но ведь их силы не бесконечны. Нам нужно что-то предпринять, чтобы ослабить эту атаку.$b$bОтправляйся на Пепельные поля, что к северу отсюда, найди подходящие кучки пепла и посади в них вот эти семена. Из них вырастет смертоносная лоза, которая задержит наших врагов. Это хоть как-то поможет.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Посадите 5 семян удавливающей лозы в кучки пепла на Пепельных полях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мы выиграем эту битву. Чего мы нам это ни стоило, мы не позволим этим элементалям снова вернуться на Хиджал.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Райне Песни Пера на Аванпост Малфуриона на Огненной передовой.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (29140,'Под взглядом повелителя небес','Неправильный выбор. Возьмите задание "Атака стражниц". Эта цепочка более содержательна.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Под взглядом повелителя небес',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Неправильный выбор. Возьмите задание "Атака стражниц". Эта цепочка более содержательна.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29141,'Тяжелое падение','Оплавленные чудища вместе с элементалями бьются против нас на поле боя. Они крушат наши войска. Я хочу, чтобы ты $gостановил:остановила; их.$b$bЭти чудища медлительные и неповоротливые. От их атак несложно уклониться, но если они все же нанесут тебе удар, он будет страшным. Не зевай, |3-6($c).','Убейте 3 оплавленных чудища.','Элементали начнут тебя бояться.','Вернитесь к генералу Талдрис Закат Луны на Аванпост Малфуриона, что на Огненной передовой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тяжелое падение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Оплавленные чудища вместе с элементалями бьются против нас на поле боя. Они крушат наши войска. Я хочу, чтобы ты $gостановил:остановила; их.$b$bЭти чудища медлительные и неповоротливые. От их атак несложно уклониться, но если они все же нанесут тебе удар, он будет страшным. Не зевай, |3-6($c).',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 3 оплавленных чудища.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Элементали начнут тебя бояться.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к генералу Талдрис Закат Луны на Аванпост Малфуриона, что на Огненной передовой.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29142,'Изменники возвращаются','Друиды пламени атакуют нас, $n.$b$bЭти жестокие создания презрели учения Элуны и вместо этого поклоняются Повелителю Огня, Рагнаросу. Они уже полностью подчинились его воле и теперь хотят лишь одного – сжечь нас дотла.$b$bМы должны немедленно отразить их нападение!','Убейте 3 друидов пламени.','Прекрасно. Теперь наши враги будут знать, что нас стоит бояться.','Вернитесь к генералу Талдрис Закат Луны на Аванпост Малфуриона, что на Огненной передовой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Изменники возвращаются',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Друиды пламени атакуют нас, $n.$b$bЭти жестокие создания презрели учения Элуны и вместо этого поклоняются Повелителю Огня, Рагнаросу. Они уже полностью подчинились его воле и теперь хотят лишь одного – сжечь нас дотла.$b$bМы должны немедленно отразить их нападение!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 3 друидов пламени.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно. Теперь наши враги будут знать, что нас стоит бояться.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к генералу Талдрис Закат Луны на Аванпост Малфуриона, что на Огненной передовой.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (29143,'Волшебный огонек','Множество элементалей огня проникает сюда через порталы, открытые в дальней части Пепельных полей. Кто-то должен их закрыть. Нужно лишить противника подкрепления.$B$BНаши огоньки как раз подходят для такой задачи. Я пошлю один из них с тобой. Подведи его к порталу и проследи, что он не погиб, пока дело не сделано.','Вернитесь к Райне Песни Пера на Аванпост Малфуриона на Огненной передовой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Волшебный огонек',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Множество элементалей огня проникает сюда через порталы, открытые в дальней части Пепельных полей. Кто-то должен их закрыть. Нужно лишить противника подкрепления.$B$BНаши огоньки как раз подходят для такой задачи. Я пошлю один из них с тобой. Подведи его к порталу и проследи, что он не погиб, пока дело не сделано.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Райне Песни Пера на Аванпост Малфуриона на Огненной передовой.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (29145,'Открыть врата','Ты немного $gопоздал:опоздала;. Хамуул, Малфурион и некоторые из наших дорогих гостей уже отправились в точку вторжения, что на вершине вон той скалы.$b$bВрата в Огненные Просторы еще не открыты, но ждать осталось недолго. Чем раньше это случится, тем лучше.$b$bВперед! Хамуул ждет тебя.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Открыть врата',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты немного $gопоздал:опоздала;. Хамуул, Малфурион и некоторые из наших дорогих гостей уже отправились в точку вторжения, что на вершине вон той скалы.$b$bВрата в Огненные Просторы еще не открыты, но ждать осталось недолго. Чем раньше это случится, тем лучше.$b$bВперед! Хамуул ждет тебя.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (29146,'Прокатиться на ракете','Отправляйтесь на южную конечную станцию ракетной дороги в Азшаре и садитесь на двухместную транспортную ракету на вершине башни.','Прокатитесь со своим подопечным-сиротой по ракетной дороге.','Вернитесь к своему подопечному орку-сироте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прокатиться на ракете',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь на южную конечную станцию ракетной дороги в Азшаре и садитесь на двухместную транспортную ракету на вершине башни.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Прокатитесь со своим подопечным-сиротой по ракетной дороге.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к своему подопечному орку-сироте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (29146,'Это было классно! Я даже смог поуправлять ракетой! Помнишь, как я нас спас? Когда я вырасту, стану пилотом!') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это было классно! Я даже смог поуправлять ракетой! Помнишь, как я нас спас? Когда я вырасту, стану пилотом!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (29147,'Клич стаи','Сегодня у нас есть возможность предпринять еще одну попытку нападения на одну из главных приспешниц Рагнароса – Миллазор. Однако прежде всего надо заручиться поддержкой.$b$b<Мата Коготь берет в руки большое шелковистое перо.>$b$bВозьми это перо, чтобы пробудить силу Авианы. После чего отправляйся на северо-запад и призови ее стаю.$b$bКогда закончишь, возвращайся ко мне, и мы выступим против Миллазор.','Воспользуйтесь способностью "Клич стаи", чтобы собрать 12 горных певунов, 5 лесных сов и 2 златокрылых ястребов.','Вернитесь к Мате Коготь в Святилище Малорна, что на горе Хиджал.','Мы готовы напасть на Миллазор.','Мата Коготь') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Клич стаи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сегодня у нас есть возможность предпринять еще одну попытку нападения на одну из главных приспешниц Рагнароса – Миллазор. Однако прежде всего надо заручиться поддержкой.$b$b<Мата Коготь берет в руки большое шелковистое перо.>$b$bВозьми это перо, чтобы пробудить силу Авианы. После чего отправляйся на северо-запад и призови ее стаю.$b$bКогда закончишь, возвращайся ко мне, и мы выступим против Миллазор.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь способностью "Клич стаи", чтобы собрать 12 горных певунов, 5 лесных сов и 2 златокрылых ястребов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мате Коготь в Святилище Малорна, что на горе Хиджал.',`completedtext_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Мы готовы напасть на Миллазор.',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Мата Коготь',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (29148,'Крылья в огне','<Голос Маты Коготь продолжает звучать у вас в голове.>$b$bМиллазор – существо пламенной природы, но во многом она такая же, как и другие птицы в этих землях. А раз так, то скорее всего артефакты Авианы по-прежнему имеют над ней силу и могут помочь призвать ее.$b$bТы найдешь Миллазор у огненного портала к западу отсюда. Воспользуйся пером у входа в портал и будь $gготов:готова; к жестокой битве.','Воспользуйтесь пером королевы птиц, чтобы призвать Миллазор, и убейте ее.','Прекрасно!','Вернитесь к Мате Коготь в Святилище Малорна, что на горе Хиджал.','Вымани его из портала и убей!','Миллазор') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Крылья в огне',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Голос Маты Коготь продолжает звучать у вас в голове.>$b$bМиллазор – существо пламенной природы, но во многом она такая же, как и другие птицы в этих землях. А раз так, то скорее всего артефакты Авианы по-прежнему имеют над ней силу и могут помочь призвать ее.$b$bТы найдешь Миллазор у огненного портала к западу отсюда. Воспользуйся пером у входа в портал и будь $gготов:готова; к жестокой битве.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь пером королевы птиц, чтобы призвать Миллазор, и убейте ее.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мате Коготь в Святилище Малорна, что на горе Хиджал.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Вымани его из портала и убей!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Миллазор',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29149,'Кара, настигающая пламя','Из всех задач, которые стоят перед нами здесь, на Хиджале, самая спешная довольно проста: уничтожить захватчиков. Природа огня такова, что он пожирает все на своем пути. Стоит хоть ненадолго ослабить защиту, и он уничтожит все в мгновение ока.$b$bУбей всех захватчиков, каких увидишь. Каждый побежденный враг дает Хиджалу еще немного времени.','Убейте 7 любых захватчиков с Огненных Просторов в Молодом лесу или в Гнезде Сетрии.','Вернитесь к Мате Коготь в Святилище Малорна, что на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кара, настигающая пламя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Из всех задач, которые стоят перед нами здесь, на Хиджале, самая спешная довольно проста: уничтожить захватчиков. Природа огня такова, что он пожирает все на своем пути. Стоит хоть ненадолго ослабить защиту, и он уничтожит все в мгновение ока.$b$bУбей всех захватчиков, каких увидишь. Каждый побежденный враг дает Хиджалу еще немного времени.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 7 любых захватчиков с Огненных Просторов в Молодом лесу или в Гнезде Сетрии.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мате Коготь в Святилище Малорна, что на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29150,'Зомби вуду','Люди... Все они стали зомби, зомби вуду! И это не сулит нам ничего хорошего, $n.$b$bУбей их.$b$bЯ могу спасти зомби в течение нескольких мгновений после того, как они будут убиты. Превратить их обратно в людей, которыми они были раньше.$b$bНо мы должны действовать быстро. Зомби не дремлют.','Спасите 10 жертв нападения зомби с раскопок.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зомби вуду',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Люди... Все они стали зомби, зомби вуду! И это не сулит нам ничего хорошего, $n.$b$bУбей их.$b$bЯ могу спасти зомби в течение нескольких мгновений после того, как они будут убиты. Превратить их обратно в людей, которыми они были раньше.$b$bНо мы должны действовать быстро. Зомби не дремлют.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Спасите 10 жертв нападения зомби с раскопок.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (29151,'Скверный провиант','Некоторые выжившие говорили о еде, $n. Нужно проверить, в каком состоянии их провиант. У меня нехорошие предчувствия.','Занзил… Теперь все начинает проясняться. Если у меня получится разыскать моего связного, мы сможем начать планировать атаку. Пора положить конец этому безумию.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Скверный провиант',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Некоторые выжившие говорили о еде, $n. Нужно проверить, в каком состоянии их провиант. У меня нехорошие предчувствия.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Занзил… Теперь все начинает проясняться. Если у меня получится разыскать моего связного, мы сможем начать планировать атаку. Пора положить конец этому безумию.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (29152,'Связной','Ты не $gпохож:похожа; на зомби...$b$bТролль? Я видел одного, как раз перед атакой... Он предупреждал нас об опасности... Но было уже слишком поздно.$b$bТвой приятель отправился в Пиратскую Бухту, чтобы предупредить их...','Отправляйтесь в Пиратскую Бухту и найдите там связного Бвембы.','Я говорил барону Ревилгазу о зандаларской угрозе…') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Связной',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты не $gпохож:похожа; на зомби...$b$bТролль? Я видел одного, как раз перед атакой... Он предупреждал нас об опасности... Но было уже слишком поздно.$b$bТвой приятель отправился в Пиратскую Бухту, чтобы предупредить их...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Пиратскую Бухту и найдите там связного Бвембы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я говорил барону Ревилгазу о зандаларской угрозе…',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29153,'Интересы Пиратской Бухты','Послушай, $n. Ты очень $gпомог:помогла; нам, но этого недостаточно. Нужно остановить этих безумных троллей или хотя бы не дать им войти в Пиратскую Бухту.$b$bЯ отправлю туда разведчика, чтобы он наблюдал за обстановкой, но я хочу, чтобы ты $gотправился:отправилась; в Зул\'Гуруб и кое-что $gсделал:сделала;.$b$bПо крайней мере $gнашел:нашла; что-нибудь, что помешает троллям проникнуть в Пиратскую Бухту.$b$bСделаешь это – получишь награду.','Найдите артефакт, который мог бы помешать троллям Зул\'Гуруба проникнуть в Пиратскую Бухту.','Вернитесь к барону Ревилгазу в Пиратскую Бухту или к инспектору Бадабуму в Зул\'Гуруб.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Интересы Пиратской Бухты',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Послушай, $n. Ты очень $gпомог:помогла; нам, но этого недостаточно. Нужно остановить этих безумных троллей или хотя бы не дать им войти в Пиратскую Бухту.$b$bЯ отправлю туда разведчика, чтобы он наблюдал за обстановкой, но я хочу, чтобы ты $gотправился:отправилась; в Зул\'Гуруб и кое-что $gсделал:сделала;.$b$bПо крайней мере $gнашел:нашла; что-нибудь, что помешает троллям проникнуть в Пиратскую Бухту.$b$bСделаешь это – получишь награду.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите артефакт, который мог бы помешать троллям Зул\'Гуруба проникнуть в Пиратскую Бухту.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к барону Ревилгазу в Пиратскую Бухту или к инспектору Бадабуму в Зул\'Гуруб.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29154,'Интересы Пиратской Бухты','Меня прислал сюда барон Ревилгаз из Пиратской Бухты, чтобы я убедился, что нашествие троллей остановлено. Или хотя бы остановлено у подходов к Пиратской Бухте.$b$bОт тебя я хочу действий и результата.$b$bОтправляйся туда и убивай.$b$bМне нужно, чтобы ты $gнашел:нашла; нечто, что не даст этим троллям проникнуть в Пиратскую Бухту.$b$bВыполнишь это – можешь быть $gуверен:уверена;, что тебе заплатят.','Найдите артефакт, который мог бы помешать троллям Зул\'Гуруба проникнуть в Пиратскую Бухту.','Вернитесь к барону Ревилгазу в Пиратскую Бухту или к инспектору Бадабуму в Зул\'Гуруб.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Интересы Пиратской Бухты',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Меня прислал сюда барон Ревилгаз из Пиратской Бухты, чтобы я убедился, что нашествие троллей остановлено. Или хотя бы остановлено у подходов к Пиратской Бухте.$b$bОт тебя я хочу действий и результата.$b$bОтправляйся туда и убивай.$b$bМне нужно, чтобы ты $gнашел:нашла; нечто, что не даст этим троллям проникнуть в Пиратскую Бухту.$b$bВыполнишь это – можешь быть $gуверен:уверена;, что тебе заплатят.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите артефакт, который мог бы помешать троллям Зул\'Гуруба проникнуть в Пиратскую Бухту.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к барону Ревилгазу в Пиратскую Бухту или к инспектору Бадабуму в Зул\'Гуруб.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (29155,'Сверкающая награда','Сундук находится в статуе на острове Жанейро, что к северо-западу от Пиратской Бухты, в Тернистой долине.$b$bОтправляйся к статуе и забери свою награду, |3-6($c).','Достаньте сундук с сокровищами из статуи на острове Жанейро.','Вот оно, сокровище!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сверкающая награда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сундук находится в статуе на острове Жанейро, что к северо-западу от Пиратской Бухты, в Тернистой долине.$b$bОтправляйся к статуе и забери свою награду, |3-6($c).',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Достаньте сундук с сокровищами из статуи на острове Жанейро.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот оно, сокровище!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29156,'Вторжение троллей','В порт Штормграда прибыла группа троллей, которые заявляют, что принадлежат к племени Черного Копья. Пока что наши стражники не дают им сойти на берег.$b$bСтражам штормградского порта необходима помощь в изгнании троллей из порта. Обратитесь к командору Шарпу.','Поговорите с командором Шарпом в порту Штормграда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вторжение троллей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В порт Штормграда прибыла группа троллей, которые заявляют, что принадлежат к племени Черного Копья. Пока что наши стражники не дают им сойти на берег.$b$bСтражам штормградского порта необходима помощь в изгнании троллей из порта. Обратитесь к командору Шарпу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с командором Шарпом в порту Штормграда.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29157,'Зандаларская угроза','Тролли племени Зандалар уже идут по Тернистой долине!$b$bЕсли хочешь помочь троллям Черного Копья, поговори с Бвембой в Аллее Духов в Оргриммаре.','Поговорите с Бвембой в Аллее Духов в Оргриммаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зандаларская угроза',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тролли племени Зандалар уже идут по Тернистой долине!$b$bЕсли хочешь помочь троллям Черного Копья, поговори с Бвембой в Аллее Духов в Оргриммаре.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Бвембой в Аллее Духов в Оргриммаре.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (29158,'Зандаларская посланница','Внемли моему зову, |3-6($c)! Тернистая долина нуждается в твоей помощи! Когда-то ты уже $gвыручал:выручала; зандаларских троллей, и мы не забыли об этом. Именно поэтому мы решили обратиться к тебе. Я буду ждать тебя в порту.','Встретьтесь с Бвембой в порту Штормграда.','Зандаларская посланница','Бвемба') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зандаларская посланница',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Внемли моему зову, |3-6($c)! Тернистая долина нуждается в твоей помощи! Когда-то ты уже $gвыручал:выручала; зандаларских троллей, и мы не забыли об этом. Именно поэтому мы решили обратиться к тебе. Я буду ждать тебя в порту.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Встретьтесь с Бвембой в порту Штормграда.',`objectives_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Зандаларская посланница',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Бвемба',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29159,'Огнеарахнофобия','Мы ожесточенно боролись, стараясь закрепиться на этом месте, но наше положение еще очень шатко.$B$BПо донесениям разведчиков окрестные земли кишат огненными пауками. Это порождения злой праматери пауков по имени Бет\'тилак.$B$BПомоги нам удержать позиции – расчисти окрестности от пеплопрядов-ткачей и ползунов-пеплопрядов. Красная Вдова придет в бешенство, увидев гибель своих детей.','Убейте 8 пеплопрядов-ткачей или ползунов-пеплопрядов.','Великолепно! Чем больше пауков мы убьем, тем проще нам будет двигаться дальше.','Вернитесь к Делдрену Темному Листу, который находится у Одинокой башни на Огненной передовой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Огнеарахнофобия',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы ожесточенно боролись, стараясь закрепиться на этом месте, но наше положение еще очень шатко.$B$BПо донесениям разведчиков окрестные земли кишат огненными пауками. Это порождения злой праматери пауков по имени Бет\'тилак.$B$BПомоги нам удержать позиции – расчисти окрестности от пеплопрядов-ткачей и ползунов-пеплопрядов. Красная Вдова придет в бешенство, увидев гибель своих детей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 пеплопрядов-ткачей или ползунов-пеплопрядов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Великолепно! Чем больше пауков мы убьем, тем проще нам будет двигаться дальше.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Делдрену Темному Листу, который находится у Одинокой башни на Огненной передовой.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29160,'Яйцесбор','У нас серьезная проблема. Местные пауки настроены очень агрессивно, и их становится все больше и больше.$B$BНужно как-то ограничить их численность. Гораздо проще уничтожить яйца, которые они откладывают, чем сражаться со взрослыми пауками.$B$BМножество яиц пеплопрядов можно найти среди каменных столпов к северу отсюда. Собери 20 яиц и принеси их мне.','Соберите 20 яиц пеплопрядов вблизи каменных столпов в Кладке Вдовы.','Видимо, пеплопряды-ткачи выхаживают потомство Бет\'тилак.','Вернитесь к Делдрену Темному Листу, который находится у Одинокой башни на Огненной передовой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Яйцесбор',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У нас серьезная проблема. Местные пауки настроены очень агрессивно, и их становится все больше и больше.$B$BНужно как-то ограничить их численность. Гораздо проще уничтожить яйца, которые они откладывают, чем сражаться со взрослыми пауками.$B$BМножество яиц пеплопрядов можно найти среди каменных столпов к северу отсюда. Собери 20 яиц и принеси их мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 20 яиц пеплопрядов вблизи каменных столпов в Кладке Вдовы.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Видимо, пеплопряды-ткачи выхаживают потомство Бет\'тилак.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Делдрену Темному Листу, который находится у Одинокой башни на Огненной передовой.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (29161,'Медвежата на дереве','О, нет! Только мы спасли последнего медвежонка, как опять разгорелся огонь и вновь напугал их!$b$bМожет быть, ты этого не знаешь, но маленькие медвежата такие ласковые и милые.$b$bОтправляйся в Рощу Трелей, это далеко на северо-западе. Забирайся на деревья, хватай драгоценных маленьких медвежат и бросай их – только осторожно! – на тент в центре рощи.$b$b<Милуна отчаянно прижимает вас к груди и начинает рыдать.>$b$bБедные маленькие медвежата! Спаси их, $n!','Забирайтесь на деревья в Роще Трелей, хватайте хиджальских медвежат и бросайте их на тент. Это абсолютно безопасно.','Поговорите с Милуной в Святилище Малорна на горе Хиджал.','Ух ты!','Милуна') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Медвежата на дереве',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','О, нет! Только мы спасли последнего медвежонка, как опять разгорелся огонь и вновь напугал их!$b$bМожет быть, ты этого не знаешь, но маленькие медвежата такие ласковые и милые.$b$bОтправляйся в Рощу Трелей, это далеко на северо-западе. Забирайся на деревья, хватай драгоценных маленьких медвежат и бросай их – только осторожно! – на тент в центре рощи.$b$b<Милуна отчаянно прижимает вас к груди и начинает рыдать.>$b$bБедные маленькие медвежата! Спаси их, $n!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Забирайтесь на деревья в Роще Трелей, хватайте хиджальских медвежат и бросайте их на тент. Это абсолютно безопасно.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Милуной в Святилище Малорна на горе Хиджал.',`completedtext_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Ух ты!',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Милуна',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (29162,'Благословение природы','<В вашей голове звучит голос Милуны и щебетание птичек.>$b$bЯ люблю всех лесных обитателей. Даже пауков, хоть они и не очень-то приятно выглядят. Но пауки из Огненных Просторов не просто уродливы. Они не только гадкие, но и жгучие. Они пришли из других мест.$b$bРазыщи огненный портал в западной части Молодого леса и воспользуйся самоцветом, который я дала тебе раньше, чтобы заставить портал открыться. А когда появится паук, раздави его! Если он не будет слишком огромным, тогда примени какую-нибудь из способностей |3-8($c). Ах, да, и не забудь использовать самоцвет, если почувствуешь на себе действие паучьего яда!','Воспользуйтесь изумрудом Эссины, чтобы призвать и убить Огнеплета.','Вернитесь к Милуне в Святилище Малорна, что на горе Хиджал.','Воспользуйтесь изумрудом, чтобы справиться с его ядом!','Огнеплет') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Благословение природы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<В вашей голове звучит голос Милуны и щебетание птичек.>$b$bЯ люблю всех лесных обитателей. Даже пауков, хоть они и не очень-то приятно выглядят. Но пауки из Огненных Просторов не просто уродливы. Они не только гадкие, но и жгучие. Они пришли из других мест.$b$bРазыщи огненный портал в западной части Молодого леса и воспользуйся самоцветом, который я дала тебе раньше, чтобы заставить портал открыться. А когда появится паук, раздави его! Если он не будет слишком огромным, тогда примени какую-нибудь из способностей |3-8($c). Ах, да, и не забудь использовать самоцвет, если почувствуешь на себе действие паучьего яда!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь изумрудом Эссины, чтобы призвать и убить Огнеплета.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Милуне в Святилище Малорна, что на горе Хиджал.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Воспользуйтесь изумрудом, чтобы справиться с его ядом!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Огнеплет',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29163,'Кара, настигающая пламя','Из всех задач, которые стоят перед нами здесь, на Хиджале, самая спешная довольно проста: уничтожить захватчиков. Природа огня такова, что он пожирает все на своем пути. Стоит хоть ненадолго ослабить защиту, и он уничтожит все в мгновение ока.$b$bУбей всех захватчиков, каких увидишь. Каждый побежденный враг дает Хиджалу еще немного времени.','Убейте 9 любых захватчиков с Огненных Просторов в Молодом лесу или в Гнезде Сетрии.','Вернитесь к Мате Коготь в Святилище Малорна, что на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кара, настигающая пламя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Из всех задач, которые стоят перед нами здесь, на Хиджале, самая спешная довольно проста: уничтожить захватчиков. Природа огня такова, что он пожирает все на своем пути. Стоит хоть ненадолго ослабить защиту, и он уничтожит все в мгновение ока.$b$bУбей всех захватчиков, каких увидишь. Каждый побежденный враг дает Хиджалу еще немного времени.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 9 любых захватчиков с Огненных Просторов в Молодом лесу или в Гнезде Сетрии.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мате Коготь в Святилище Малорна, что на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (29164,'Завыть по-волчьи','У древнего волка, Ло\'гоша, или, если тебе так больше нравится, Голдринна, есть много доступных орудий, но его вой почему-то всегда недооценивают. Мы же воспользуемся этим орудием, чтобы призвать и убить Цветика, который обитает в Огненных Просторах.$b$bУбивай всех огненных существ, которых встретишь в Молодом лесу, а затем воспользуйся клыком волка, стоя над их поверженными телами. Эхо твоего воя разнесется по всему Калимдору.','Воспользуйтесь клыком волка, над телами 10 поверженных захватчиков из Огненных Просторов в Молодом лесу.','Вернитесь к Мате Коготь в Святилище Малорна, что на горе Хиджал.','Завой, как он.','Мата Коготь') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Завыть по-волчьи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У древнего волка, Ло\'гоша, или, если тебе так больше нравится, Голдринна, есть много доступных орудий, но его вой почему-то всегда недооценивают. Мы же воспользуемся этим орудием, чтобы призвать и убить Цветика, который обитает в Огненных Просторах.$b$bУбивай всех огненных существ, которых встретишь в Молодом лесу, а затем воспользуйся клыком волка, стоя над их поверженными телами. Эхо твоего воя разнесется по всему Калимдору.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь клыком волка, над телами 10 поверженных захватчиков из Огненных Просторов в Молодом лесу.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мате Коготь в Святилище Малорна, что на горе Хиджал.',`completedtext_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Завой, как он.',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Мата Коготь',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (29165,'Зов стаи','<Мата Коготь продолжает.>$b$bСамый восточный огненный портал – это обиталище Цветика. Встань перед порталом, издай призывный вой и победи чудовище, которое после этого появится.','Воспользуйтесь клыком волка, чтобы призвать Цветика, и убейте его.','Я слышала твой триумфальный вой, преумноженный эхом.$B$BИ я слышала, как выл Цветик… по совсем другой причине.','Вернитесь к Мате Коготь в Святилище Малорна, что на горе Хиджал.','Пора вывести эту собачку погулять… и УБИТЬ ее.','Цветик') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зов стаи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Мата Коготь продолжает.>$b$bСамый восточный огненный портал – это обиталище Цветика. Встань перед порталом, издай призывный вой и победи чудовище, которое после этого появится.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь клыком волка, чтобы призвать Цветика, и убейте его.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я слышала твой триумфальный вой, преумноженный эхом.$B$BИ я слышала, как выл Цветик… по совсем другой причине.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мате Коготь в Святилище Малорна, что на горе Хиджал.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Пора вывести эту собачку погулять… и УБИТЬ ее.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Цветик',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29166,'Припасы для той стороны','Одна из самых больших опасностей, с которой сталкиваются наши друиды, сражаясь на Огненных Просторах, – это обычное обезвоживание. Наши снабженцы тратят много времени на то, чтобы обеспечить войска водой. Но есть и еще кое-что, что мы можем сделать.$b$bВ зеленых зарослях к востоку можно найти лазоревые корни, которые не пострадали от огня. В этих корнях содержится огромное количество жидкости, которая к тому же может придать сил утомленным воинам.','Соберите 7 лазоревых корней.','Я позабочусь о том, чтобы их упаковали и отправили сейчас же.','Посмотрим... Сколько тебе удалось собрать?','Вернитесь к Мате Коготь в Святилище Малорна, что на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Припасы для той стороны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Одна из самых больших опасностей, с которой сталкиваются наши друиды, сражаясь на Огненных Просторах, – это обычное обезвоживание. Наши снабженцы тратят много времени на то, чтобы обеспечить войска водой. Но есть и еще кое-что, что мы можем сделать.$b$bВ зеленых зарослях к востоку можно найти лазоревые корни, которые не пострадали от огня. В этих корнях содержится огромное количество жидкости, которая к тому же может придать сил утомленным воинам.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 7 лазоревых корней.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я позабочусь о том, чтобы их упаковали и отправили сейчас же.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Посмотрим... Сколько тебе удалось собрать?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мате Коготь в Святилище Малорна, что на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (29167,'Королева банши','Отведите своего подопечного-сироту в Королевский квартал Подгорода к леди Сильване Ветрокрылой. Обязательно позовите своего подопечного, если по прибытии его не окажется рядом.','Встреча с леди Сильваной Ветрокрылой','Вернитесь к своему подопечному орку-сироте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Королева банши',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отведите своего подопечного-сироту в Королевский квартал Подгорода к леди Сильване Ветрокрылой. Обязательно позовите своего подопечного, если по прибытии его не окажется рядом.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Встреча с леди Сильваной Ветрокрылой',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к своему подопечному орку-сироте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (29167,'Она действительно такая грозная, как я и думал! А тот посол чуть с ума не сошел, когда я с ней заговорил!') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Она действительно такая грозная, как я и думал! А тот посол чуть с ума не сошел, когда я с ней заговорил!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (29168,'Второстепенные цели','Тролли Гурубаши собрали самых мощных своих союзников, чтобы возродить Зул\'Гуруб и вернуть в свои руки Тернистую долину.$b$bВозглавляют их Каулема Толкатель, Мор\'Лек Расчленитель и могущественный похититель душ по имени Мортакс.$b$bХоть они и не являются лидерами Зул\'Гуруба, победа над ними поможет предотвратить возрождение Гурубаши.','Убейте Каулему Толкателя, Мор\'Лека Расчленителя и Мортакса Предвестника смерти в Зул\'Гурубе.','Поговорите с Шабалом в Зул\'Гурубе, что в Северной Тернистой долине.','У Джин\'до сильные союзники.','Мортакс Предвестник смерти') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Второстепенные цели',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тролли Гурубаши собрали самых мощных своих союзников, чтобы возродить Зул\'Гуруб и вернуть в свои руки Тернистую долину.$b$bВозглавляют их Каулема Толкатель, Мор\'Лек Расчленитель и могущественный похититель душ по имени Мортакс.$b$bХоть они и не являются лидерами Зул\'Гуруба, победа над ними поможет предотвратить возрождение Гурубаши.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Каулему Толкателя, Мор\'Лека Расчленителя и Мортакса Предвестника смерти в Зул\'Гурубе.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Шабалом в Зул\'Гурубе, что в Северной Тернистой долине.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','У Джин\'до сильные союзники.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Мортакс Предвестник смерти',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (29169,'Там чудовища!','<Мейвики нервно переминается с ноги на ногу.>$b$bПосле падения Хаккара город племени Гурубаши оказался в плачевном состоянии, а большую часть Зул\'Гуруба захватили джунгли. В руинах древнего города теперь обитают опасные монстры.$b$bМы видели, какой силой владеют жрецы Гурубаши. При помощи своих зелий они даже местную растительность смогли обратить против нас. Пожалуйста, избавьте нас от этих чудовищ, пока они не превратились в безумных пособников Джин\'до и его сообщников!','Убейте королеву улья Цветокрылов, Тор-Туна Сновидца и потерявшегося отпрыска Газ\'ранки в Зул\'Гурубе.','Поговорите с Мейвики в Зул\'Гурубе, что в Северной Тернистой долине.','Мы не можем позволить Гурубаши контролировать их!','Королева улья Цветокрылов') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Там чудовища!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Мейвики нервно переминается с ноги на ногу.>$b$bПосле падения Хаккара город племени Гурубаши оказался в плачевном состоянии, а большую часть Зул\'Гуруба захватили джунгли. В руинах древнего города теперь обитают опасные монстры.$b$bМы видели, какой силой владеют жрецы Гурубаши. При помощи своих зелий они даже местную растительность смогли обратить против нас. Пожалуйста, избавьте нас от этих чудовищ, пока они не превратились в безумных пособников Джин\'до и его сообщников!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте королеву улья Цветокрылов, Тор-Туна Сновидца и потерявшегося отпрыска Газ\'ранки в Зул\'Гурубе.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Мейвики в Зул\'Гурубе, что в Северной Тернистой долине.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Мы не можем позволить Гурубаши контролировать их!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Королева улья Цветокрылов',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (29170,'UNUSED REUSE','<Шлем Вентурона гудит от напряжения.>$B$BЧто это за место? Похоже, что они творят с драконом Пустоты нечто ужасное. Энергия, высасываемая из бедного существа, устремляется к той женщине! Нужно прервать ритуал!$B$BУстрани Корлу, чтобы пройти сквозь этот зал!','Убейте глашатая сумрака Корлу','Поговорите с Айсом Вентуроном в Пещерах Черной горы на Черной горе.','Она выглядит зловеще!','Глашатай сумрака Корла','Время на исходе! Разу нужна наша помощь!','Айс Вентурон') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','UNUSED REUSE',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Шлем Вентурона гудит от напряжения.>$B$BЧто это за место? Похоже, что они творят с драконом Пустоты нечто ужасное. Энергия, высасываемая из бедного существа, устремляется к той женщине! Нужно прервать ритуал!$B$BУстрани Корлу, чтобы пройти сквозь этот зал!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте глашатая сумрака Корлу',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Айсом Вентуроном в Пещерах Черной горы на Черной горе.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Она выглядит зловеще!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Глашатай сумрака Корла',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Время на исходе! Разу нужна наша помощь!',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Айс Вентурон',`questturntargetname_loc8`);
