INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (29172,'Там чудовища!','<Умертвительница Т\'ара некоторое время смотрит на вас.>$b$bПосле падения Хаккара город племени Гурубаши оказался в плачевном состоянии, а большую часть Зул\'Гуруба захватили джунгли. В руинах древнего города теперь обитают опасные монстры.$b$bМы видели, какой силой владеют жрецы Гурубаши. При помощи своих зелий они даже местную растительность смогли обратить против нас. Ты считаешь себя $gсильным:сильной;? Уничтожь этих чудовищ, пока они не превратились в безумных пособников Джин\'до!','Убейте королеву улья Цветокрылов, Тор-Туна Сновидца и потерявшегося отпрыска Газ\'ранки в Зул\'Гурубе в героическом режиме.','<Т\'ара полностью обнажает клыки. Может, она так улыбается?>$B$BОчень хорошо.$B$BСегодня ночью мы будем спать спокойно, зная, что Джин\'до и Занзил не смогут натравить на нас этих страшных чудовищ.','Поговорите с умертвительницей Т\'арой в Зул\'Гурубе, что в Северной Тернистой долине.','Мы не можем позволить Гурубаши контролировать их!','Королева улья Цветокрылов') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Там чудовища!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Умертвительница Т\'ара некоторое время смотрит на вас.>$b$bПосле падения Хаккара город племени Гурубаши оказался в плачевном состоянии, а большую часть Зул\'Гуруба захватили джунгли. В руинах древнего города теперь обитают опасные монстры.$b$bМы видели, какой силой владеют жрецы Гурубаши. При помощи своих зелий они даже местную растительность смогли обратить против нас. Ты считаешь себя $gсильным:сильной;? Уничтожь этих чудовищ, пока они не превратились в безумных пособников Джин\'до!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте королеву улья Цветокрылов, Тор-Туна Сновидца и потерявшегося отпрыска Газ\'ранки в Зул\'Гурубе в героическом режиме.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Т\'ара полностью обнажает клыки. Может, она так улыбается?>$B$BОчень хорошо.$B$BСегодня ночью мы будем спать спокойно, зная, что Джин\'до и Занзил не смогут натравить на нас этих страшных чудовищ.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с умертвительницей Т\'арой в Зул\'Гурубе, что в Северной Тернистой долине.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Мы не можем позволить Гурубаши контролировать их!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Королева улья Цветокрылов',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (29173,'Второстепенные цели','Тролли Гурубаши собрали самых мощных своих союзников, чтобы возродить Зул\'Гуруб и вернуть в свои руки Тернистую долину.$b$bВозглавляют их Каулема Толкатель, Мор\'Лек Расчленитель и могущественный похититель душ по имени Мортакс.$b$bХоть они и не являются лидерами Зул\'Гуруба, победа над ними поможет предотвратить возрождение Гурубаши.','Убейте Каулему Толкателя, Мор\'Лека Расчленителя и Мортакса Предвестника смерти в Зул\'Гурубе в героическом режиме.','Империя Джин\'до рушится так же, как этот проклятый город.','Поговорите с умертвительницей Т\'арой в Зул\'Гурубе, что в Северной Тернистой долине.','У Джин\'до сильные союзники.','Мортакс Предвестник смерти') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Второстепенные цели',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тролли Гурубаши собрали самых мощных своих союзников, чтобы возродить Зул\'Гуруб и вернуть в свои руки Тернистую долину.$b$bВозглавляют их Каулема Толкатель, Мор\'Лек Расчленитель и могущественный похититель душ по имени Мортакс.$b$bХоть они и не являются лидерами Зул\'Гуруба, победа над ними поможет предотвратить возрождение Гурубаши.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Каулему Толкателя, Мор\'Лека Расчленителя и Мортакса Предвестника смерти в Зул\'Гурубе в героическом режиме.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Империя Джин\'до рушится так же, как этот проклятый город.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с умертвительницей Т\'арой в Зул\'Гурубе, что в Северной Тернистой долине.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','У Джин\'до сильные союзники.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Мортакс Предвестник смерти',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (29174,'Сломить их дух','Зул\'Гуруб похож на те высокие деревья, которые растут поблизости.$b$bКаким бы мощным ни был ствол и какой бы густой – крона, без простирающихся далеко под землей корней дерево засохнет и рухнет.$b$bСила армии Джин\'до во многом зависит от помощи двух троллей Гурубаши. Стоит перерубить эти "корни", и город падет.','Убейте Габа и шеф-повара племени Гурубаши в Зул\'Гурубе.','Поговорите с Ал\'табимом в Зул\'Гурубе, что в Северной Тернистой долине.','Нужно лишить их снабжения!','Габ, Гроза рыб') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сломить их дух',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Зул\'Гуруб похож на те высокие деревья, которые растут поблизости.$b$bКаким бы мощным ни был ствол и какой бы густой – крона, без простирающихся далеко под землей корней дерево засохнет и рухнет.$b$bСила армии Джин\'до во многом зависит от помощи двух троллей Гурубаши. Стоит перерубить эти "корни", и город падет.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Габа и шеф-повара племени Гурубаши в Зул\'Гурубе.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Ал\'табимом в Зул\'Гурубе, что в Северной Тернистой долине.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Нужно лишить их снабжения!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Габ, Гроза рыб',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (29175,'Сломить их дух','Зул\'Гуруб похож на те высокие деревья, которые растут поблизости.$b$bКаким бы мощным ни был ствол и какой бы густой – крона, без простирающихся далеко под землей корней дерево засохнет и рухнет.$b$bСила армии Джин\'до во многом зависит от помощи двух троллей Гурубаши. Стоит перерубить эти "корни", и город падет.','Убейте Габа и шеф-повара племени Гурубаши в Зул\'Гурубе в героическом режиме.','Великая империя Гурубаши уже слабеет.$B$BТеперь ее окончательное падение – лишь вопрос времени.','Поговорите с умертвительницей Т\'арой в Зул\'Гурубе, что в Северной Тернистой долине.','Нужно лишить их снабжения!','Габ, Гроза рыб') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сломить их дух',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Зул\'Гуруб похож на те высокие деревья, которые растут поблизости.$b$bКаким бы мощным ни был ствол и какой бы густой – крона, без простирающихся далеко под землей корней дерево засохнет и рухнет.$b$bСила армии Джин\'до во многом зависит от помощи двух троллей Гурубаши. Стоит перерубить эти "корни", и город падет.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Габа и шеф-повара племени Гурубаши в Зул\'Гурубе в героическом режиме.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Великая империя Гурубаши уже слабеет.$B$BТеперь ее окончательное падение – лишь вопрос времени.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с умертвительницей Т\'арой в Зул\'Гурубе, что в Северной Тернистой долине.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Нужно лишить их снабжения!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Габ, Гроза рыб',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (29176,'Погибший вождь тауренов','Попечительница сирот Батлвейл говорит, что когда умер Кэрн Кровавое Копыто, Орда лишилась своего "гласа мудрости". Я не знаю, что это такое, но я всегда хотел его увидеть. У некоторых ребят в приюте даже есть отпечаток его копыта!$b$bМожет быть, отведешь меня в Мулгор? Наш воспитатель говорит, что таурены хоронят своих умерших в месте, которое называется Красные скалы, чтобы почтить их память. Давай пойдем туда и поищем Кэрна.','Отведите своего подопечного-сироту на Красные скалы к погребальному костру Кэрна Кровавого Копыта. Обязательно позовите своего подопечного, если по прибытии его не окажется рядом.','Отведите вашего подопечного-сироту на Красные скалы','Вернитесь к своему подопечному орку-сироте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Погибший вождь тауренов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Попечительница сирот Батлвейл говорит, что когда умер Кэрн Кровавое Копыто, Орда лишилась своего "гласа мудрости". Я не знаю, что это такое, но я всегда хотел его увидеть. У некоторых ребят в приюте даже есть отпечаток его копыта!$b$bМожет быть, отведешь меня в Мулгор? Наш воспитатель говорит, что таурены хоронят своих умерших в месте, которое называется Красные скалы, чтобы почтить их память. Давай пойдем туда и поищем Кэрна.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отведите своего подопечного-сироту на Красные скалы к погребальному костру Кэрна Кровавого Копыта. Обязательно позовите своего подопечного, если по прибытии его не окажется рядом.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Отведите вашего подопечного-сироту на Красные скалы',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к своему подопечному орку-сироте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29177,'Бдительность','Сектанты Сумеречного Молота по-прежнему продолжают атаки в этой части Огненных Просторов. Мы не должны допустить поражения нашей армии! Взлетай и уничтожь как можно больше вражеских копейщиков.$b$bИ не забудь предварительно вооружиться огненным копьем.','Вооружитесь огненным копьем Сумеречного Молота и взлетите на одном из защитников Авианы. Убейте 10 сумеречных копейщиков, бросившись на них. Нажимайте кнопку "Взмах", чтобы защитник взмахивал крыльями.','Вернитесь к Фардену Когтекрылу в Инкубатор.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бдительность',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сектанты Сумеречного Молота по-прежнему продолжают атаки в этой части Огненных Просторов. Мы не должны допустить поражения нашей армии! Взлетай и уничтожь как можно больше вражеских копейщиков.$b$bИ не забудь предварительно вооружиться огненным копьем.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вооружитесь огненным копьем Сумеречного Молота и взлетите на одном из защитников Авианы. Убейте 10 сумеречных копейщиков, бросившись на них. Нажимайте кнопку "Взмах", чтобы защитник взмахивал крыльями.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фардену Когтекрылу в Инкубатор.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29178,'Ой, блестяшечки!','Подойди-ка сюда, $Gприятель:лапуля;! Дай старине Жулю посмотреть на твои блестяшечки...$b$bХммм. Да-да, неплохо, но ты можешь добыть больше. Куда больше.$b$b<Жуль наклоняется к вам и шепчет.>$b$bСлавные блестяшечки – они повсюду, $n, только надо знать, где искать! Нынче тебе свезло так свезло – я знаю парня, который поможет тебе найти столько блестяшек, что и не унесешь.$b$bЗайди к моему старому приятелю, Бадду, он болтается близ Зул\'Амана, и покажи ему вот это. Он поймет, что тебя послал старый Жуль, и посвятит тебя в свою затею.','Поговорите с Баддом в Призрачных землях.','Поговорите с Баддом на Холмах Томагавков.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ой, блестяшечки!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Подойди-ка сюда, $Gприятель:лапуля;! Дай старине Жулю посмотреть на твои блестяшечки...$b$bХммм. Да-да, неплохо, но ты можешь добыть больше. Куда больше.$b$b<Жуль наклоняется к вам и шепчет.>$b$bСлавные блестяшечки – они повсюду, $n, только надо знать, где искать! Нынче тебе свезло так свезло – я знаю парня, который поможет тебе найти столько блестяшек, что и не унесешь.$b$bЗайди к моему старому приятелю, Бадду, он болтается близ Зул\'Амана, и покажи ему вот это. Он поймет, что тебя послал старый Жуль, и посвятит тебя в свою затею.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Баддом в Призрачных землях.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Баддом на Холмах Томагавков.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29179,'Враждебные стихии','Элементали продолжают наступать и я не думаю, что в ближайшее время они ослабят свой натиск.$b$bНа Пепельных полях, что к северу отсюда, их много. Сократи их численность.','Убейте 8 пламенных воинов или пламенных покорителей.','Вернитесь к генералу Талдрис Закат Луны на Аванпост Малфуриона, что на Огненной передовой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Враждебные стихии',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Элементали продолжают наступать и я не думаю, что в ближайшее время они ослабят свой натиск.$b$bНа Пепельных полях, что к северу отсюда, их много. Сократи их численность.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 пламенных воинов или пламенных покорителей.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к генералу Талдрис Закат Луны на Аванпост Малфуриона, что на Огненной передовой.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29180,'Все обещаешь и обещаешь','Мои изыскания подтверждают слухи об огромном сокровище, спрятанном в Зул\'Амане. Там для каждого найдется своя гора золота и еще небольшой холмик впридачу! Но сначала ты $gдолжен:должна; поработать, чтобы получить свою долю этого пирога.$b$bНаша первая попытка достать эти сокровища пошла не так гладко, как я надеялся. Фактически, моя карта и те неумехи, которым я ее вручил, пропали без вести. Они отправились за троллем по имени Налоракк.$b$bЗабудь об этих неудачниках, мне нужна карта! Добейся успеха и ты войдешь в историю как тот, кто помог Бадду Недреку раскрыть тайны Зул\'Амана.','Найдите карту Зул\'Амана, принадлежащую Бадду, на террасе верховного шамана Налоракка в Зул\'Амане.','Поговорите с Баддом на Холмах Томагавков.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Все обещаешь и обещаешь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мои изыскания подтверждают слухи об огромном сокровище, спрятанном в Зул\'Амане. Там для каждого найдется своя гора золота и еще небольшой холмик впридачу! Но сначала ты $gдолжен:должна; поработать, чтобы получить свою долю этого пирога.$b$bНаша первая попытка достать эти сокровища пошла не так гладко, как я надеялся. Фактически, моя карта и те неумехи, которым я ее вручил, пропали без вести. Они отправились за троллем по имени Налоракк.$b$bЗабудь об этих неудачниках, мне нужна карта! Добейся успеха и ты войдешь в историю как тот, кто помог Бадду Недреку раскрыть тайны Зул\'Амана.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите карту Зул\'Амана, принадлежащую Бадду, на террасе верховного шамана Налоракка в Зул\'Амане.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Баддом на Холмах Томагавков.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29181,'Друиды-вороны','На горе Хиджал повелитель небес Омнурон и его друиды-вороны оказали нам колоссальную поддержку. Знаю, они предпочитают летать в знакомых местах, но может прийти время, когда мы все же будем нуждаться в их помощи.$b$bЕсли у тебя будет достаточно знаков Древа Жизни, ты сможешь обратиться к Омнурону и попросить его отправить друидов-воронов на передовую. Он бережет своих солдат, но при этом он прекрасно понимает, насколько важна нам сейчас помощь.','Получите 150 знаков Древа Жизни.','Договоритесь о помощи друидов-воронов с повелителем небес Омнуроном в Святилище Авианы, что на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Друиды-вороны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На горе Хиджал повелитель небес Омнурон и его друиды-вороны оказали нам колоссальную поддержку. Знаю, они предпочитают летать в знакомых местах, но может прийти время, когда мы все же будем нуждаться в их помощи.$b$bЕсли у тебя будет достаточно знаков Древа Жизни, ты сможешь обратиться к Омнурону и попросить его отправить друидов-воронов на передовую. Он бережет своих солдат, но при этом он прекрасно понимает, насколько важна нам сейчас помощь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Получите 150 знаков Древа Жизни.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Договоритесь о помощи друидов-воронов с повелителем небес Омнуроном в Святилище Авианы, что на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (29182,'Полет друидов-воронов','В этих небесах действительно очень тяжело летать, но по большей части мы справляемся.$B$BНам может понадобиться твоя поддержка за Горнилом. Я позову тебя, когда ты понадобишься.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Полет друидов-воронов',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','В этих небесах действительно очень тяжело летать, но по большей части мы справляемся.$B$BНам может понадобиться твоя поддержка за Горнилом. Я позову тебя, когда ты понадобишься.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (29183,'Daily Tier 2 Heroic (Nth)') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Daily Tier 2 Heroic (Nth)',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29184,'Крестом на карте обозначена... твоя смерть!','Нет, ну как они могли провалиться? Идиоты! Говорил я им, чтобы были осторожнее, и даже выдал маскировку, чтобы было проще. Ладно, туда им и дорога. Теперь этим делом займешься ты.$B$BЕсли ты добьешься успеха, то я сочту тебя достойным вступить в ряды моей команды, молва о которой скоро прогремит по всему миру. И на меньшее я не согласен.$B$BНам осталось заполнить еще несколько участков на моей карте, и тогда мы сможем начать раскопки...','Отправляйтесь в Зул\'Аман и посетите чертог Халаззи, платформу Джан\'алая и платформу Акил\'зона.','Поговорите с Баддом на Холмах Томагавков.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Крестом на карте обозначена... твоя смерть!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нет, ну как они могли провалиться? Идиоты! Говорил я им, чтобы были осторожнее, и даже выдал маскировку, чтобы было проще. Ладно, туда им и дорога. Теперь этим делом займешься ты.$B$BЕсли ты добьешься успеха, то я сочту тебя достойным вступить в ряды моей команды, молва о которой скоро прогремит по всему миру. И на меньшее я не согласен.$B$BНам осталось заполнить еще несколько участков на моей карте, и тогда мы сможем начать раскопки...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Зул\'Аман и посетите чертог Халаззи, платформу Джан\'алая и платформу Акил\'зона.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Баддом на Холмах Томагавков.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (29185,'Daily Tier 2 Heroic (1st)') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Daily Tier 2 Heroic (1st)',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertargetname_loc8`) VALUES (29186,'Фетиш повелителя проклятий','Этот новый вождь Амани ничего бы из себя не представлял без поддержки опытного знахаря.$b$bНовый союзник вождя – это повелитель проклятий Малакрасс, один из самых грозных знахарей, что были в племени Амани за несколько десятилетий. Без этого так называемого повелителя проклятий Даакара не стал бы отдавать своих троллей племени Зандалар.$b$bУбей повелителя проклятий Малакрасса, принеси мне его фетиш и увидишь, что получишь в награду.','Убейте повелителя проклятий Малакрасса в Зул\'Амане и заберите его фетиш.','Так это и есть фетиш могущественного Малакрасса? Неплохой экземплярчик для моей коллекции, Бойкабаба. А теперь подошла очередь награды...','С повелителем проклятий Малакрассом покончено?','Поговорите со знахарем Т\'ванши в Зул\'Амане.','Повелитель проклятий Малакрасс') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Фетиш повелителя проклятий',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этот новый вождь Амани ничего бы из себя не представлял без поддержки опытного знахаря.$b$bНовый союзник вождя – это повелитель проклятий Малакрасс, один из самых грозных знахарей, что были в племени Амани за несколько десятилетий. Без этого так называемого повелителя проклятий Даакара не стал бы отдавать своих троллей племени Зандалар.$b$bУбей повелителя проклятий Малакрасса, принеси мне его фетиш и увидишь, что получишь в награду.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте повелителя проклятий Малакрасса в Зул\'Амане и заберите его фетиш.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так это и есть фетиш могущественного Малакрасса? Неплохой экземплярчик для моей коллекции, Бойкабаба. А теперь подошла очередь награды...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','С повелителем проклятий Малакрассом покончено?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите со знахарем Т\'ванши в Зул\'Амане.',`completedtext_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Повелитель проклятий Малакрасс',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29187,'Охота за клыками','Эй, $gприятель:подруга;! Ты тут $gновенький:новенькая;? Окажи мне услугу.$b$bБадд тут доделывает свою личину. Говорит, что уже почти закончил. Остался только последний штрих. Ему нужны клыки.$b$bЯ тут порастратил все свои навыки снятия шкур. Только подумаю о клыках троллей, как меня сразу тошнит.$b$bТы уж принеси мне 10 клыков, ладно, $gприятель:подружка;?','Соберите 10 клыков лесных троллей, убивая троллей в Зул\'Амане.','Поговорите с Пригмоном на Холмах Томагавков.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота за клыками',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эй, $gприятель:подруга;! Ты тут $gновенький:новенькая;? Окажи мне услугу.$b$bБадд тут доделывает свою личину. Говорит, что уже почти закончил. Остался только последний штрих. Ему нужны клыки.$b$bЯ тут порастратил все свои навыки снятия шкур. Только подумаю о клыках троллей, как меня сразу тошнит.$b$bТы уж принеси мне 10 клыков, ладно, $gприятель:подружка;?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 клыков лесных троллей, убивая троллей в Зул\'Амане.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Пригмоном на Холмах Томагавков.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29188,'Тролль в стане троллей','Послушай, $gпарень:подруга;, старине Пригмону нужно, чтобы ты $gсделал:сделала; еще кое-что.$b$bМой никчемный кузен Зунгам не может выбраться из Зул\'Амана. Но тем не менее он жив – прошлой ночью я видел в небе его сигнальную ракету!$b$bСтоило бы конечно, бросить его там, чтобы не втягивал меня в свои дела, но он мне должен нехилую сумму денег.$b$bТак что сделай, что можешь, спаси его шкуру и принеси мне должок!','Поговорите с Зунгамом в Зул\'Амане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тролль в стане троллей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Послушай, $gпарень:подруга;, старине Пригмону нужно, чтобы ты $gсделал:сделала; еще кое-что.$b$bМой никчемный кузен Зунгам не может выбраться из Зул\'Амана. Но тем не менее он жив – прошлой ночью я видел в небе его сигнальную ракету!$b$bСтоило бы конечно, бросить его там, чтобы не втягивал меня в свои дела, но он мне должен нехилую сумму денег.$b$bТак что сделай, что можешь, спаси его шкуру и принеси мне должок!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Зунгамом в Зул\'Амане.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29189,'Зловещая паутина','Некоторые из наших разведчиков не вернулись с задания. Мы опасаемся, что они стали жертвами смертельно опасных пауков, которые водятся в этих краях.$b$bНо надежда еще не потеряна. Нередко пауки помещают свои жертвы в коконы, чтобы вернуться к ним позже.$b$bОтправляйся к башням, что к северу отсюда, и поищи коконы с жертвами. Может быть, тебе еще удастся спасти некоторых наших братьев.','Освободите 8 жертв из коконов пеплопряда.','Вернитесь к Делдрену Темному Листу, который находится у Одинокой башни на Огненной передовой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зловещая паутина',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Некоторые из наших разведчиков не вернулись с задания. Мы опасаемся, что они стали жертвами смертельно опасных пауков, которые водятся в этих краях.$b$bНо надежда еще не потеряна. Нередко пауки помещают свои жертвы в коконы, чтобы вернуться к ним позже.$b$bОтправляйся к башням, что к северу отсюда, и поищи коконы с жертвами. Может быть, тебе еще удастся спасти некоторых наших братьев.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Освободите 8 жертв из коконов пеплопряда.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Делдрену Темному Листу, который находится у Одинокой башни на Огненной передовой.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (29190,'Давай запустим змея!','Попечительница сирот однажды водила нас погулять, и я видел одного гоблина с целой тележкой разных игрушек. У него там были куклы, медные болиды, кожаные мячи и еще воздушные змеи. Мне всегда так хотелось запустить воздушного змея в виде дракона! Попечительница говорила, что я могу купить его на свои деньги – когда накоплю достаточно. Но до этого еще так долго ждать.$b$bТого гоблина звали Бухс Забабахс или что-то вроде этого. Если мы его встретим, можно мы купим у него воздушных змеев и запустим их вместе? Я видел этого гоблина у Волока.','Купите упаковку с двумя воздушными змеями у Бухса Забабахса в Волоке, что в Оргриммаре, и запустите воздушных змеев вместе со своим подопечным орком-сиротой. Обязательно позовите сироту, если по прибытии его не окажется рядом.','Запустите воздушных змеев вместе со своим подопечным-сиротой','Вернитесь к своему подопечному орку-сироте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Давай запустим змея!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Попечительница сирот однажды водила нас погулять, и я видел одного гоблина с целой тележкой разных игрушек. У него там были куклы, медные болиды, кожаные мячи и еще воздушные змеи. Мне всегда так хотелось запустить воздушного змея в виде дракона! Попечительница говорила, что я могу купить его на свои деньги – когда накоплю достаточно. Но до этого еще так долго ждать.$b$bТого гоблина звали Бухс Забабахс или что-то вроде этого. Если мы его встретим, можно мы купим у него воздушных змеев и запустим их вместе? Я видел этого гоблина у Волока.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Купите упаковку с двумя воздушными змеями у Бухса Забабахса в Волоке, что в Оргриммаре, и запустите воздушных змеев вместе со своим подопечным орком-сиротой. Обязательно позовите сироту, если по прибытии его не окажется рядом.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Запустите воздушных змеев вместе со своим подопечным-сиротой',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к своему подопечному орку-сироте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (29190,'Спасибо за змея, Рунаак. Каждый раз, когда я буду запускать его, я буду вспоминать, как ты мне его подарил!') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо за змея, Рунаак. Каждый раз, когда я буду запускать его, я буду вспоминать, как ты мне его подарил!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (29191,'Детям – мороженое!','Купите мороженое в "Конусе холода" и угостите им своего подопечного.','Отведите своего подопечного-сироту в магазин мороженого.','Вернитесь к своему подопечному орку-сироте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Детям – мороженое!',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Купите мороженое в "Конусе холода" и угостите им своего подопечного.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Отведите своего подопечного-сироту в магазин мороженого.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к своему подопечному орку-сироте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (29191,'Кажется, я никогда еще не видел, чтобы гоблин готовил еду без помощи этих огромных, громыхающих и дымящих машин. Думаю, многие бы любили гоблинскую еду, если бы они готовили ее по-нормальному… ну или по-магическому!') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Кажется, я никогда еще не видел, чтобы гоблин готовил еду без помощи этих огромных, громыхающих и дымящих машин. Думаю, многие бы любили гоблинскую еду, если бы они готовили ее по-нормальному… ну или по-магическому!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29192,'Стражницы наблюдают','Мы должны действовать крайне осторожно, |3-6($c). Друиды пламени практикуются в применении своей огненной магии за теми колоннами, что к северу от нас.$b$bВозьми одного из них в плен, и мы его допросим. Надо использовать любую возможность выяснить их планы.$b$bОдна из моих стражниц будет сопровождать тебя. Если хочешь остаться $gживым:живой;, делай все, как она говорит.','Сражайтесь с друидом пламени, пока он не ослабнет, а затем заманите его в ловушку темной стражницы.','Вернитесь к Марин Острое Крыло, которая находится у Одинокой башни на Огненной передовой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Стражницы наблюдают',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы должны действовать крайне осторожно, |3-6($c). Друиды пламени практикуются в применении своей огненной магии за теми колоннами, что к северу от нас.$b$bВозьми одного из них в плен, и мы его допросим. Надо использовать любую возможность выяснить их планы.$b$bОдна из моих стражниц будет сопровождать тебя. Если хочешь остаться $gживым:живой;, делай все, как она говорит.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сражайтесь с друидом пламени, пока он не ослабнет, а затем заманите его в ловушку темной стражницы.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Марин Острое Крыло, которая находится у Одинокой башни на Огненной передовой.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29193,'На честном слове','Мы не теряли времени даром, $gсмертный:смертная;.$b$bПока ты $gсражался:сражалась; в царстве огня, мы вместе с моими наблюдателями смогли выяснить, где и, что еще важнее, когда было затуманено наше видение.$b$bМы обнаружили, что далеко на севере, в царстве синих драконов, покров был накинут на Нексус.$b$bЯ настроил вневременное око таким образом, чтобы оно смогло показать, что там произошло.$b$bОтнеси его в Хладарру и найди подходящее для активации ока место.$b$bИди, друг. Не стоит терять времени...','Отнесите вневременное око в Хладарру.','Поговорите с Таресгосой в Хладарре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На честном слове',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы не теряли времени даром, $gсмертный:смертная;.$b$bПока ты $gсражался:сражалась; в царстве огня, мы вместе с моими наблюдателями смогли выяснить, где и, что еще важнее, когда было затуманено наше видение.$b$bМы обнаружили, что далеко на севере, в царстве синих драконов, покров был накинут на Нексус.$b$bЯ настроил вневременное око таким образом, чтобы оно смогло показать, что там произошло.$b$bОтнеси его в Хладарру и найди подходящее для активации ока место.$b$bИди, друг. Не стоит терять времени...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите вневременное око в Хладарру.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Таресгосой в Хладарре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29194,'Как сквозь темное стекло','<Таресгоса слушает ваш рассказ о том, зачем вы пришли в Хладарру.>$b$bТы говоришь правду, |3-6($c). Многое изменилось после смерти Малигоса – и далеко не все в лучшую сторону.$b$bЯ знаю, что это за предмет в твоих руках, и я узнаю магию его создателя Анахроноса. Во всей Хладарре есть всего лишь одно место, где можно воспользоваться вневременным оком, не привлекая к этому внимания.$b$bЕсли ты хочешь добиться успеха, тебе понадобится моя помощь. Я буду ждать тебя в Нексусе. Когда доберешься туда, поговори со мной, и я помогу тебе.','Воспользуйтесь Оком Вечности в Воронке Пустоты Нексуса.$b$bРазыщите Таресгосу в Нексусе, и она проводит вас к Разлому.','Поговорите с Таресгосой у Разлома в Нексусе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Как сквозь темное стекло',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Таресгоса слушает ваш рассказ о том, зачем вы пришли в Хладарру.>$b$bТы говоришь правду, |3-6($c). Многое изменилось после смерти Малигоса – и далеко не все в лучшую сторону.$b$bЯ знаю, что это за предмет в твоих руках, и я узнаю магию его создателя Анахроноса. Во всей Хладарре есть всего лишь одно место, где можно воспользоваться вневременным оком, не привлекая к этому внимания.$b$bЕсли ты хочешь добиться успеха, тебе понадобится моя помощь. Я буду ждать тебя в Нексусе. Когда доберешься туда, поговори со мной, и я помогу тебе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь Оком Вечности в Воронке Пустоты Нексуса.$b$bРазыщите Таресгосу в Нексусе, и она проводит вас к Разлому.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Таресгосой у Разлома в Нексусе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29195,'Огненный ритуал','Кажется, теперь у нас все под контролем. Наш портал в Огненные Просторы вот-вот откроется, и элементали не оказали серьезного сопротивления.$b$bПомоги нашим друидам справиться с оставшимися элементалями. А потом, когда врата будут открыты, мы сможем двигаться дальше.','Сражайтесь с пламенными захватчиками на утесе Нордун, пока портал не будет открыт.','Лиара… жива. Я чувствую, что здесь не обошлось без Фэндрала.','Поговорите с Малфурионом на утесе Нордун, что на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Огненный ритуал',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кажется, теперь у нас все под контролем. Наш портал в Огненные Просторы вот-вот откроется, и элементали не оказали серьезного сопротивления.$b$bПомоги нашим друидам справиться с оставшимися элементалями. А потом, когда врата будут открыты, мы сможем двигаться дальше.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сражайтесь с пламенными захватчиками на утесе Нордун, пока портал не будет открыт.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Лиара… жива. Я чувствую, что здесь не обошлось без Фэндрала.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Малфурионом на утесе Нордун, что на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (29196,'В святилище!','Не стоит сейчас беспокоиться из-за этих так называемых друидов пламени. Мы должны сосредоточиться на ходе нашей операции.$b$bВозвращайся к Мате Коготь в Святилище Малорна. Если Рагнарос ждал нашего прибытия, то наверняка скоро он прикажет начать контратаку.','Что там случилось? Я видела огонь и… впрочем, неважно, расскажешь потом. Сейчас у нас есть более срочные дела.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В святилище!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не стоит сейчас беспокоиться из-за этих так называемых друидов пламени. Мы должны сосредоточиться на ходе нашей операции.$b$bВозвращайся к Мате Коготь в Святилище Малорна. Если Рагнарос ждал нашего прибытия, то наверняка скоро он прикажет начать контратаку.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что там случилось? Я видела огонь и… впрочем, неважно, расскажешь потом. Сейчас у нас есть более срочные дела.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29197,'Захвачены врасплох','Кажется, наш план нападения не сработал. Несколько наших птиц уже вернулись с сообщениями о пожарах в долинах в центре Хиджала.$b$bИ теперь многие из наших друидов не были готовы к такой масштабной атаке и оказались отрезаны. Тизали была у Пепельного озера, некоторые другие остались в Молодом лесу, что к северо-востоку отсюда.$b$bИди, $n! Найди их и помоги им!','Помогите Старокрону, Тизали Вороне, Толо Белому Копыту и Анрену Искателю Теней выбраться из огня.','Вернитесь к Хамуулу Руническому Тотему в Святилище Малорна, что на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Захвачены врасплох',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кажется, наш план нападения не сработал. Несколько наших птиц уже вернулись с сообщениями о пожарах в долинах в центре Хиджала.$b$bИ теперь многие из наших друидов не были готовы к такой масштабной атаке и оказались отрезаны. Тизали была у Пепельного озера, некоторые другие остались в Молодом лесу, что к северо-востоку отсюда.$b$bИди, $n! Найди их и помоги им!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Помогите Старокрону, Тизали Вороне, Толо Белому Копыту и Анрену Искателю Теней выбраться из огня.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хамуулу Руническому Тотему в Святилище Малорна, что на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29199,'Сбор подкрепления','После нашего неудавшегося нападения мы понесли тяжелые потери. Наша вторая попытка должна быть успешной.$b$bПеред тем, как мы начнем вторую атаку, нам нужно собрать подкрепление. Пожалуйста, $n, помоги Мате Коготь собрать достаточное количество ресурсов. А затем мы предпримем вторую и последнюю попытку нападения на Огненные Просторы.','Соберите 20 знаков Древа Жизни.','Превосходно. Я сейчас же пошлю за подкреплением.','Чем раньше мы сможем пройти через портал, тем лучше.','Поговорите с верховным друидом Руническомим Тотемом, который находится в Святилище Малорна на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сбор подкрепления',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','После нашего неудавшегося нападения мы понесли тяжелые потери. Наша вторая попытка должна быть успешной.$b$bПеред тем, как мы начнем вторую атаку, нам нужно собрать подкрепление. Пожалуйста, $n, помоги Мате Коготь собрать достаточное количество ресурсов. А затем мы предпримем вторую и последнюю попытку нападения на Огненные Просторы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 20 знаков Древа Жизни.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Превосходно. Я сейчас же пошлю за подкреплением.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Чем раньше мы сможем пройти через портал, тем лучше.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с верховным друидом Руническомим Тотемом, который находится в Святилище Малорна на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29200,'Лиара','Прежде чем мы уйдем, $n, нужно сделать еще одно дело, для которого нам понадобится твоя помощь.$b$bВ руинах, расположенных к северо-западу отсюда, заметили одного из друидов пламени. Думаю, это тот же самый друид, который напал на нас у портала несколько дней назад. Это отличная возможность узнать, чего же она на самом деле хочет... и, если понадобится, избавиться от нее.$b$bРазыщи ее и сделай то, что нужно. Потом мы сможем вернуться к нашему плану.','Найдите Лиару, друида пламени.','Вернитесь к Мате Коготь в Святилище Малорна, что на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лиара',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прежде чем мы уйдем, $n, нужно сделать еще одно дело, для которого нам понадобится твоя помощь.$b$bВ руинах, расположенных к северо-западу отсюда, заметили одного из друидов пламени. Думаю, это тот же самый друид, который напал на нас у портала несколько дней назад. Это отличная возможность узнать, чего же она на самом деле хочет... и, если понадобится, избавиться от нее.$b$bРазыщи ее и сделай то, что нужно. Потом мы сможем вернуться к нашему плану.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Лиару, друида пламени.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мате Коготь в Святилище Малорна, что на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29201,'Через врата ада','Оплакать Хамуула мы сможем и позже. Увы, он – одна из многих неизбежных жертв этой войны. Но мы не можем задерживать атаку. Мы готовились к ней несколько дней и не можем допустить, чтобы все это было напрасно.$b$bПортал на вершине Утеса Нордун открыт. Войска готовы и ждут только моей команды, чтобы пройти через портал.$b$bВстретимся с той стороны портала. А там мы должны будем защищать нашу цитадель.','Пройдите через портал на вершине утеса Нордун и помогите Малфуриону создать аванпост на Огненной передовой.','Поговорите с Малфурионом Яростью Бури внутри древа-стража на Аванпосте Малфуриона, что на Огненной передовой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Через врата ада',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Оплакать Хамуула мы сможем и позже. Увы, он – одна из многих неизбежных жертв этой войны. Но мы не можем задерживать атаку. Мы готовились к ней несколько дней и не можем допустить, чтобы все это было напрасно.$b$bПортал на вершине Утеса Нордун открыт. Войска готовы и ждут только моей команды, чтобы пройти через портал.$b$bВстретимся с той стороны портала. А там мы должны будем защищать нашу цитадель.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Пройдите через портал на вершине утеса Нордун и помогите Малфуриону создать аванпост на Огненной передовой.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Малфурионом Яростью Бури внутри древа-стража на Аванпосте Малфуриона, что на Огненной передовой.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (29202,'Судьба Рунического Тотема','Прости, что не смогла поговорить с тобой подольше в прошлый раз. То, что произошло с Хамуулом, потрясло меня, мне очень трудно с этим смириться.$b$bЕго тело доставили сюда, когда тебя не было. Он жив, но, как ты можешь себе представить, его ожоги ужасны.$b$bРаны очень серьезны. Неизвестно, выживет ли он.$b$bЯ распорядилась, чтобы им занялись наши самые лучшие лекари. Я хочу, чтобы ты $gпоговорил:поговорила; с Дорда\'эном Ткущим Ночь, если, конечно, я прошу не слишком многого. Ему и его помощникам может потребоваться наша помощь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Судьба Рунического Тотема',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прости, что не смогла поговорить с тобой подольше в прошлый раз. То, что произошло с Хамуулом, потрясло меня, мне очень трудно с этим смириться.$b$bЕго тело доставили сюда, когда тебя не было. Он жив, но, как ты можешь себе представить, его ожоги ужасны.$b$bРаны очень серьезны. Неизвестно, выживет ли он.$b$bЯ распорядилась, чтобы им занялись наши самые лучшие лекари. Я хочу, чтобы ты $gпоговорил:поговорила; с Дорда\'эном Ткущим Ночь, если, конечно, я прошу не слишком многого. Ему и его помощникам может потребоваться наша помощь.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29203,'В глубины','Лиара появилась в Вулканических глубинах. Ее видела группа темных стражниц.$b$bОтправляйся туда немедленно. Я присоединюсь к тебе, как только закончу необходимые приготовления.','Убейте Лиару.','История Лиары трагична. И мне очень больно, что все закончилось таким образом.$B$BНо нужно остановить Оленьего Шлема прежде, чем он перетянет на свою сторону кого-то еще.','Поговорите с Малфурионом Яростью Бури на Аванпосте Малфуриона.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В глубины',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Лиара появилась в Вулканических глубинах. Ее видела группа темных стражниц.$b$bОтправляйся туда немедленно. Я присоединюсь к тебе, как только закончу необходимые приготовления.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Лиару.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','История Лиары трагична. И мне очень больно, что все закончилось таким образом.$B$BНо нужно остановить Оленьего Шлема прежде, чем он перетянет на свою сторону кого-то еще.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Малфурионом Яростью Бури на Аванпосте Малфуриона.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29204,'Атака стражниц','Капитан Сайна Нагоняющая Грозу начинает атаку на Одинокую башню. Если ты отправишься на северо-восток, то найдешь ее у начала подъема на вершину.$b$bЯ предоставил ей довольно большое войско, но все же ее шансы сильно вырастут, если ты тоже займешь ее сторону. Решать тебе, $n.','Если вы хотите помочь стражницам в ее атаке на Одинокую башню, разыщите капитана Сайну Нагоняющую Грозу в северо-восточной части Пепельных полей.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Атака стражниц',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Капитан Сайна Нагоняющая Грозу начинает атаку на Одинокую башню. Если ты отправишься на северо-восток, то найдешь ее у начала подъема на вершину.$b$bЯ предоставил ей довольно большое войско, но все же ее шансы сильно вырастут, если ты тоже займешь ее сторону. Решать тебе, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Если вы хотите помочь стражницам в ее атаке на Одинокую башню, разыщите капитана Сайну Нагоняющую Грозу в северо-восточной части Пепельных полей.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29205,'Одинокая башня','Капитан Сайна Нагоняющая Грозу начинает атаку на Одинокую башню. Если ты отправишься на северо-восток, то найдешь ее у начала подъема на вершину.$b$bОтправляйся туда и сопровождай одного из ее друидов вместе со всеми солдатами, которых она тебе выделит, к башне. Вас будет ждать жаркая битва. Убедись, что друид доживет до ее конца, или они не смогут захватить башню.','Защищайте друида, пытающегося захватить Одинокую башню.','Поговорите с Марин Острое Крыло, которая находится у Одинокой башни на Огненной передовой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Одинокая башня',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Капитан Сайна Нагоняющая Грозу начинает атаку на Одинокую башню. Если ты отправишься на северо-восток, то найдешь ее у начала подъема на вершину.$b$bОтправляйся туда и сопровождай одного из ее друидов вместе со всеми солдатами, которых она тебе выделит, к башне. Вас будет ждать жаркая битва. Убедись, что друид доживет до ее конца, или они не смогут захватить башню.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Защищайте друида, пытающегося захватить Одинокую башню.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Марин Острое Крыло, которая находится у Одинокой башни на Огненной передовой.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29206,'В огонь','Повелитель небес Омнурон и его друиды пытаются пробиться через Горнило, что к северо-западу от нас. Они могут облететь опасные места по воздуху, но им нужен кто-то, кто бы помог установить опорный пункт... Кто-то вроде тебя.$b$bЕсли ты хочешь помочь друидам-воронам, дождись, когда один из призывателей ветров Омнурона начнет двигаться сквозь огонь, займи позицию поближе к нему и защищай его от всего, что может причинить ему вред.','Помогите призывателю ветров пройти через Горнило и уничтожить противников возле входа к Расплавленному потоку.','Приятно видеть, что повелитель небес нашел кого-то столь умелого, хотя и не имеющего крыльев. От нашей способности летать немного толку в таком ограниченному пространстве и среди тепловых воздушных потоков.$B$BПохоже, нам придется вернуться к более традиционной тактике. Ты с нами?','Поговорите с Тизали Вороной в Расплавленном потоке под Огненной передовой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В огонь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Повелитель небес Омнурон и его друиды пытаются пробиться через Горнило, что к северо-западу от нас. Они могут облететь опасные места по воздуху, но им нужен кто-то, кто бы помог установить опорный пункт... Кто-то вроде тебя.$b$bЕсли ты хочешь помочь друидам-воронам, дождись, когда один из призывателей ветров Омнурона начнет двигаться сквозь огонь, займи позицию поближе к нему и защищай его от всего, что может причинить ему вред.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Помогите призывателю ветров пройти через Горнило и уничтожить противников возле входа к Расплавленному потоку.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Приятно видеть, что повелитель небес нашел кого-то столь умелого, хотя и не имеющего крыльев. От нашей способности летать немного толку в таком ограниченному пространстве и среди тепловых воздушных потоков.$B$BПохоже, нам придется вернуться к более традиционной тактике. Ты с нами?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Тизали Вороной в Расплавленном потоке под Огненной передовой.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (29208,'Старые знакомые') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Старые знакомые',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29209,'В огненные глубины','Одна из наших друидов отправился в Вулканические глубины за друидом пламени.$b$bСледуй за ней. Помоги ей.','Поговорите с Терезой Дубокожей в Вулканических глубинах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В огненные глубины',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Одна из наших друидов отправился в Вулканические глубины за друидом пламени.$b$bСледуй за ней. Помоги ей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Терезой Дубокожей в Вулканических глубинах.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29210,'Превозмочь жару','Шалис ушла с одним из наших друидов, чтобы остановить ритуал призыва, который друид огня проводил в Вулканических глубинах, лежащих под нами. Им было приказано уничтожить друида, а тебе предстоит прервать ритуал.$B$BВход в пещеру находится к востоку от Магматических ключей. Зайдя внутрь, ты увидишь 8 синих рун, расположенных по всей пещере. С помощью этих рун можно защититься от огненных созданий. Чтобы прервать ритуал, нужно уничтожить все руны. Поторопись!','Найдите вход в Вулканические глубины и уничтожьте все 8 синих рун внутри пещеры.','Молодец!$B$BОни пытаются проводить подобные ритуалы повсеместно на Огненной передовой, но пока что нам удается срывать их планы. Надеюсь, ты поможешь нам вновь, если нам придется столкнуться с той же проблемой.','Вернитесь к Терезе Дубокожей, находящейся у входа в Вулканические глубины на Огненной передовой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Превозмочь жару',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Шалис ушла с одним из наших друидов, чтобы остановить ритуал призыва, который друид огня проводил в Вулканических глубинах, лежащих под нами. Им было приказано уничтожить друида, а тебе предстоит прервать ритуал.$B$BВход в пещеру находится к востоку от Магматических ключей. Зайдя внутрь, ты увидишь 8 синих рун, расположенных по всей пещере. С помощью этих рун можно защититься от огненных созданий. Чтобы прервать ритуал, нужно уничтожить все руны. Поторопись!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите вход в Вулканические глубины и уничтожьте все 8 синих рун внутри пещеры.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Молодец!$B$BОни пытаются проводить подобные ритуалы повсеместно на Огненной передовой, но пока что нам удается срывать их планы. Надеюсь, ты поможешь нам вновь, если нам придется столкнуться с той же проблемой.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Терезе Дубокожей, находящейся у входа в Вулканические глубины на Огненной передовой.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29211,'Уничтожение солнечного ядра','Мы почти добрались до Фэндрала. Его друиды направляют энергию Огненных Просторов в некий резервуар, который называется солнечным ядром.$b$bЕсли они взорвут его в Азероте, у нас больше не будет дома, куда можно вернуться.$b$bНужно уничтожить солнечное ядро сейчас, пока это еще легко сделать. Ты найдешь его на северо-востоке.','Взорвите солнечное ядро.','Оно уничтожено? Это хорошо. Не думаю, что это надолго остановит Фэндрала, но мы не должны упускать ни единой возможности.','Вернитесь к Марин Острое Крыло, которая находится у Одинокой башни на Огненной передовой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уничтожение солнечного ядра',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы почти добрались до Фэндрала. Его друиды направляют энергию Огненных Просторов в некий резервуар, который называется солнечным ядром.$b$bЕсли они взорвут его в Азероте, у нас больше не будет дома, куда можно вернуться.$b$bНужно уничтожить солнечное ядро сейчас, пока это еще легко сделать. Ты найдешь его на северо-востоке.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Взорвите солнечное ядро.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Оно уничтожено? Это хорошо. Не думаю, что это надолго остановит Фэндрала, но мы не должны упускать ни единой возможности.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Марин Острое Крыло, которая находится у Одинокой башни на Огненной передовой.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29212,'[DEPRECATED] Fire Hawk Down','PH – Shoot down 5 fire hawks.','PH – Shoot down 5 fire hawks.','Вернитесь к Делдрену Темному Листу в Одинокую башню в Огненных Просторах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED] Fire Hawk Down',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','PH – Shoot down 5 fire hawks.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','PH – Shoot down 5 fire hawks.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Делдрену Темному Листу в Одинокую башню в Огненных Просторах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (29213,'Как там охотник?','Дела плохи. Эта пантера находится под воздействием какой-то очень мощной магии. Надо бы проверить, как там охотник.','Проверьте, как там Грент Лютомолот.','Ох… Моя спина… Это ты, брат?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Как там охотник?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Дела плохи. Эта пантера находится под воздействием какой-то очень мощной магии. Надо бы проверить, как там охотник.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проверьте, как там Грент Лютомолот.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ох… Моя спина… Это ты, брат?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29214,'Темные стражницы','Темные стражницы вернулись в Молодой лес. Я знаю, что они очень близко к сердцу принимают тот факт, что Фэндрал больше не содержится под их стражей, поэтому не составит труда привести их в Огненные Просторы сражаться против друидов пламени. Может быть, при этом они помогут и нам.$b$bЕсли у тебя есть достаточное количество знаков Древа Жизни, поговори с капитаном Сайной Нагоняющей Грозу и договорись о помощи.','Получите 150 знаков Древа Жизни.','Договоритесь о помощи темных стражниц с капитаном Сайной Нагоняющей Грозу в Святилище Малорна, что на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Темные стражницы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Темные стражницы вернулись в Молодой лес. Я знаю, что они очень близко к сердцу принимают тот факт, что Фэндрал больше не содержится под их стражей, поэтому не составит труда привести их в Огненные Просторы сражаться против друидов пламени. Может быть, при этом они помогут и нам.$b$bЕсли у тебя есть достаточное количество знаков Древа Жизни, поговори с капитаном Сайной Нагоняющей Грозу и договорись о помощи.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Получите 150 знаков Древа Жизни.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Договоритесь о помощи темных стражниц с капитаном Сайной Нагоняющей Грозу в Святилище Малорна, что на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (29215,'Охота началась','По твоей просьбе темные стражницы присоединились к битве на Огненной передовой. Поговори с капитаном Сайной Нагоняющей Грозу и убедись, что ее умения нашли должное применение.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота началась',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','По твоей просьбе темные стражницы присоединились к битве на Огненной передовой. Поговори с капитаном Сайной Нагоняющей Грозу и убедись, что ее умения нашли должное применение.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (29215,'Приветствую тебя, Джинкху. Приятно снова видеть тебя.$B$BНе беспокойся. У нас все в порядке. Я распорядилась, чтобы некоторые мои стражницы помогли вам в поимке друидов пламени, и разработала планы атаки на Одинокую башню. Когда придет время, возможно, мы будем сражаться вместе.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Приветствую тебя, Джинкху. Приятно снова видеть тебя.$B$BНе беспокойся. У нас все в порядке. Я распорядилась, чтобы некоторые мои стражницы помогли вам в поимке друидов пламени, и разработала планы атаки на Одинокую башню. Когда придет время, возможно, мы будем сражаться вместе.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (29216,'Аванпост Малфуриона','Защитите цитадель в Огненных Просторах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Аванпост Малфуриона',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Защитите цитадель в Огненных Просторах.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29217,'Пленные разведчики','Сразу после нашего прибытия я распорядился, чтобы мои разведчики выяснили побольше о присутствии троллей племени Зандалар в Зул\'Амане. Многие из них сообщили ценную информацию, но четверо так и не вернулись. Если мы не поторопимся, их принесут в жертву!$b$bРазыщи моих разведчиков, $n. Освободи их, прежде чем жрецы принесут их в жертву!','Освободите пленных разведчиков: Хазлека, Баккальзу, Норкани и Кайшу. Их держат в плену верховные жрецы Амани.','Вернитесь к кровавому стражу Хаккузу в Зул\'Аман.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пленные разведчики',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сразу после нашего прибытия я распорядился, чтобы мои разведчики выяснили побольше о присутствии троллей племени Зандалар в Зул\'Амане. Многие из них сообщили ценную информацию, но четверо так и не вернулись. Если мы не поторопимся, их принесут в жертву!$b$bРазыщи моих разведчиков, $n. Освободи их, прежде чем жрецы принесут их в жертву!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Освободите пленных разведчиков: Хазлека, Баккальзу, Норкани и Кайшу. Их держат в плену верховные жрецы Амани.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к кровавому стражу Хаккузу в Зул\'Аман.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (29218,'Знаки Древа Жизни') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Знаки Древа Жизни',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (29219,'Дух Бвембы','Предупредите жителей Тернистой долины и найдите посланника Черного Копья.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дух Бвембы',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Предупредите жителей Тернистой долины и найдите посланника Черного Копья.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`) VALUES (29220,'В Бамбалу','Прежде всего нужно проверить наиболее уязвимое место – Бамбалу.$b$bБамбала располагается в опасной близости от тролльского города Зул\'Гуруба... это делает ее легкой целью.$b$bМожет быть, мы найдем посланника там. Надеюсь, еще не слишком поздно.','Отправляйтесь в Бамбалу, что в Северной Тернистой долине и разыщите посланника Черного Копья.','Отправляйтесь в Бамбалу, что в Северной Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В Бамбалу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прежде всего нужно проверить наиболее уязвимое место – Бамбалу.$b$bБамбала располагается в опасной близости от тролльского города Зул\'Гуруба... это делает ее легкой целью.$b$bМожет быть, мы найдем посланника там. Надеюсь, еще не слишком поздно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Бамбалу, что в Северной Тернистой долине и разыщите посланника Черного Копья.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Отправляйтесь в Бамбалу, что в Северной Тернистой долине.',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29221,'Змеи и яд','Предупреждение помогло.$b$bМы успели собрать много охотников за головами, которые помогут нам в защите. Но охотники за головами... Они не привыкли иметь дело со змеями. Долго мы не продержимся. Такое чувство, что змеи повсюду. И я боюсь, что будет еще хуже.$b$bПомоги нам! Убей змей и попроси Бвембу вылечить пострадавших с помощью магии.','Убейте тропических гадюк и подведите Бвембу к отравленным охотникам за головами, чтобы она вылечила их.','Вернитесь в Бамбалу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Змеи и яд',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Предупреждение помогло.$b$bМы успели собрать много охотников за головами, которые помогут нам в защите. Но охотники за головами... Они не привыкли иметь дело со змеями. Долго мы не продержимся. Такое чувство, что змеи повсюду. И я боюсь, что будет еще хуже.$b$bПомоги нам! Убей змей и попроси Бвембу вылечить пострадавших с помощью магии.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте тропических гадюк и подведите Бвембу к отравленным охотникам за головами, чтобы она вылечила их.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь в Бамбалу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29222,'С нами духи','Что-то с этими змеями было не так, $n. В их яде я чувствую следы какого-то черного колдунства.$b$bМы можем воспользоваться святилищем в центре лагеря, в котором разожжен костер, чтобы провести ритуал.$b$bЧто бы ни стояло за нападениями змей, оно все еще контролирует их действия.$b$bЕдинственная проблема заключается в том, $n, что сейчас нахожусь в бестелесной форме, поэтому мне понадобится твоя помощь. Подготовь костер к ритуалу, а я уже займусь всем остальным.','Подготовьте костер перед змеиным святилищем возле Бамбалы для ритуала Бвембы.','Поговорите с Бвембой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','С нами духи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что-то с этими змеями было не так, $n. В их яде я чувствую следы какого-то черного колдунства.$b$bМы можем воспользоваться святилищем в центре лагеря, в котором разожжен костер, чтобы провести ритуал.$b$bЧто бы ни стояло за нападениями змей, оно все еще контролирует их действия.$b$bЕдинственная проблема заключается в том, $n, что сейчас нахожусь в бестелесной форме, поэтому мне понадобится твоя помощь. Подготовь костер к ритуалу, а я уже займусь всем остальным.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Подготовьте костер перед змеиным святилищем возле Бамбалы для ритуала Бвембы.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Бвембой.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`) VALUES (29223,'Эрнестуэй точно знает','Так значит, Гурубаши используют змей в своем наступлении.$b$bЗнаешь, кто собаку съел на контролировании численности звериной популяции? Охотники из экспедиции Эрнестуэя.$b$bОтправляйся туда и узнай, как они расправляются со змеями.$b$bА если они не знают, то хотя бы предупредишь их. Такое количество змей – это ненормально.','Предупредите охотников экспедиции Эрнестуэя в Северной Тернистой долине.','Отправляйтесь в лагерь экспедиции Эрнестуэя.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Эрнестуэй точно знает',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Так значит, Гурубаши используют змей в своем наступлении.$b$bЗнаешь, кто собаку съел на контролировании численности звериной популяции? Охотники из экспедиции Эрнестуэя.$b$bОтправляйся туда и узнай, как они расправляются со змеями.$b$bА если они не знают, то хотя бы предупредишь их. Такое количество змей – это ненормально.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Предупредите охотников экспедиции Эрнестуэя в Северной Тернистой долине.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Отправляйтесь в лагерь экспедиции Эрнестуэя.',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29224,'[DEPRICATED] NO LONGER USED','Here we are, mortal.$b$bThe rift emits intense energy that will shield the magic of your artifact.$b$bWhen you are ready, I will activate the Eye. Doing so will require all of my focus. You must witness the vision on your own.$b$bHurry now, $c. It is unsafe for us to tarry here.','Gaze into the Timeless Eye.$b$bSpeak to Tarecgosa at the Rift to activate the artifact.','Speak to Tarecgosa at the Rift in The Nexus.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRICATED] NO LONGER USED',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Here we are, mortal.$b$bThe rift emits intense energy that will shield the magic of your artifact.$b$bWhen you are ready, I will activate the Eye. Doing so will require all of my focus. You must witness the vision on your own.$b$bHurry now, $c. It is unsafe for us to tarry here.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Gaze into the Timeless Eye.$b$bSpeak to Tarecgosa at the Rift to activate the artifact.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Speak to Tarecgosa at the Rift in The Nexus.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29225,'Важные сведения','<Таресгоса внимательно слушает ваш рассказ об увиденном.>$b$bЭто невозможно!$b$bДаже Аригос не посмел бы зайти так далеко.$b$bЯ не сомневаюсь в твоей честности, |3-6($c), но ты $gдолжен:должна; понимать, что ты – $gсмертный:смертная;, и тебя легко обмануть.$b$bИ все же Калесгос должен узнать об этих событиях. Ты $gдолжен:должна; как можно скорее отправиться в Нордрассил и разыскать его.$b$bЯ останусь здесь, чтобы никто ничего не заподозрил. Поговори с Калесгосом, но больше – никому ни слова!','Поговорите с Калесгосом в Нордрассиле на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Важные сведения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Таресгоса внимательно слушает ваш рассказ об увиденном.>$b$bЭто невозможно!$b$bДаже Аригос не посмел бы зайти так далеко.$b$bЯ не сомневаюсь в твоей честности, |3-6($c), но ты $gдолжен:должна; понимать, что ты – $gсмертный:смертная;, и тебя легко обмануть.$b$bИ все же Калесгос должен узнать об этих событиях. Ты $gдолжен:должна; как можно скорее отправиться в Нордрассил и разыскать его.$b$bЯ останусь здесь, чтобы никто ничего не заподозрил. Поговори с Калесгосом, но больше – никому ни слова!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Калесгосом в Нордрассиле на горе Хиджал.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (29226,'Охота на охотника','Мы уже долгие дни пытаемся отбиться от змей, $n. Однако змеи – это сущий пустяк по сравнению с тем, что скрывается в джунглях.$b$bНа нас идет охота.$b$bКрупная пантера по имени Маути утаскивает наших людей в чащу.$b$bМы послали Грента Лютомолота, одного из наших лучших охотников, чтобы он поймал этого зверя.$b$bЛютомолот отправился куда-то на восток. Попробуй поискать его там.','Найдите Лютомолота в Северной Тернистой долине.','Тс-с-с…') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота на охотника',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы уже долгие дни пытаемся отбиться от змей, $n. Однако змеи – это сущий пустяк по сравнению с тем, что скрывается в джунглях.$b$bНа нас идет охота.$b$bКрупная пантера по имени Маути утаскивает наших людей в чащу.$b$bМы послали Грента Лютомолота, одного из наших лучших охотников, чтобы он поймал этого зверя.$b$bЛютомолот отправился куда-то на восток. Попробуй поискать его там.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Лютомолота в Северной Тернистой долине.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тс-с-с…',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`) VALUES (29227,'Месть охотника','Я охочусь на нее... она охотится на нас.$b$bЕе зовут Маути. Она умна. Но, убив моего брата, она допустила огромную ошибку. За это она поплатится. Старик Лютомолот напал на ее след.$b$bЯ видел, как она рыщет вблизи от Лагеря Курцена. Если мы будем действовать быстро, мы справимся с ней.$b$bТы $gготов:готова;, $n?','Грент Лютомолот хочет, чтобы вы убили Маути.','Приведите Грента Лютомолота к трупу Маути.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Месть охотника',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я охочусь на нее... она охотится на нас.$b$bЕе зовут Маути. Она умна. Но, убив моего брата, она допустила огромную ошибку. За это она поплатится. Старик Лютомолот напал на ее след.$b$bЯ видел, как она рыщет вблизи от Лагеря Курцена. Если мы будем действовать быстро, мы справимся с ней.$b$bТы $gготов:готова;, $n?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Грент Лютомолот хочет, чтобы вы убили Маути.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Приведите Грента Лютомолота к трупу Маути.',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29228,'Преследовать кошку','Теперь понятно, почему Маути казалась меньше. Настоящая Маути преследовала Грента Лютомолота, но он как опытный охотник всю дорогу пускал сигнальные ракеты, чтобы мы могли отыскать его. Найди Лютомолота, пока еще не слишком поздно!','Узнайте, куда Маути утащила Грента Лютомолота.','Ну вот мы и нашли их… Охотник в пещере. Зверь… с ним что-то не так…','Поговорите с Бвембой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Преследовать кошку',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь понятно, почему Маути казалась меньше. Настоящая Маути преследовала Грента Лютомолота, но он как опытный охотник всю дорогу пускал сигнальные ракеты, чтобы мы могли отыскать его. Найди Лютомолота, пока еще не слишком поздно!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Узнайте, куда Маути утащила Грента Лютомолота.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну вот мы и нашли их… Охотник в пещере. Зверь… с ним что-то не так…',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Бвембой.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29229,'Преследовать кошку','Теперь понятно, почему Маути казалась меньше. Настоящая Маути преследовала Грента Лютомолота, но он как опытный охотник всю дорогу пускал сигнальные ракеты, чтобы мы могли отыскать его. Найди Лютомолота, пока еще не слишком поздно!','Узнайте, куда Маути утащила Грента Лютомолота.','Поговорите с Бвембой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Преследовать кошку',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь понятно, почему Маути казалась меньше. Настоящая Маути преследовала Грента Лютомолота, но он как опытный охотник всю дорогу пускал сигнальные ракеты, чтобы мы могли отыскать его. Найди Лютомолота, пока еще не слишком поздно!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Узнайте, куда Маути утащила Грента Лютомолота.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Бвембой.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29230,'Маути','У меня есть ощущение, что с этой пантерой что-то не так, $n. Все это кажется противоестественным. Мне нужно провести некоторые ритуалы, для которых потребуется ее тело. Убей Маути, $n, и после этого мы посмотрим, что удастся выяснить.','Приведите Бвембу к останкам Маути.','Это чудовищное создание – дело рук верховной жрицы Килнары. Не к добру это. Нужно проверить, как там дворф, а затем узнать, не требуется ли еще где-то наша помощь.','Поговорите с Бвембой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Маути',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У меня есть ощущение, что с этой пантерой что-то не так, $n. Все это кажется противоестественным. Мне нужно провести некоторые ритуалы, для которых потребуется ее тело. Убей Маути, $n, и после этого мы посмотрим, что удастся выяснить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Приведите Бвембу к останкам Маути.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это чудовищное создание – дело рук верховной жрицы Килнары. Не к добру это. Нужно проверить, как там дворф, а затем узнать, не требуется ли еще где-то наша помощь.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Бвембой.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (29231,'Как там охотник?','Дела плохи. Эта пантера находится под воздействием какой-то очень мощной магии. Надо бы проверить, как там охотник.','Проверьте, как там Грент Лютомолот.','Ох… Моя спина… Это ты, брат?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Как там охотник?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Дела плохи. Эта пантера находится под воздействием какой-то очень мощной магии. Надо бы проверить, как там охотник.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проверьте, как там Грент Лютомолот.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ох… Моя спина… Это ты, брат?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29232,'Похорони меня в сапогах...','А... это ты, $n. Маути... Она мертва? Тогда мой брат отомщен. Теперь у меня к тебе лишь одна просьба... Эта мелкая пакость царапает мои босые ноги. Нельзя дворфу отправляться в могилу без обуви.$b$bПожалуйста, похорони меня в сапогах.','Принесите сапоги Грента Лютомолота.','Спасибо тебе, друг.$B$BПапочка?..$B$BЭто… ты?..$B$B$B$B$B…','Вернитесь к Гренту Лютомолоту.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Похорони меня в сапогах...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А... это ты, $n. Маути... Она мертва? Тогда мой брат отомщен. Теперь у меня к тебе лишь одна просьба... Эта мелкая пакость царапает мои босые ноги. Нельзя дворфу отправляться в могилу без обуви.$b$bПожалуйста, похорони меня в сапогах.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите сапоги Грента Лютомолота.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо тебе, друг.$B$BПапочка?..$B$BЭто… ты?..$B$B$B$B$B…',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гренту Лютомолоту.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29233,'Предупредить Гром\'гол','Эта смерть не должна быть напрасной, $n. Мы узнали, что Килнара стоит за всем, что происходит в округе. В этом нет ничего хорошего.$b$bСтоит заглянуть в лагерь Гром\'гол, что к западу отсюда. Может быть, мой связной там.','Отправляйтесь в лагерь Гром\'гол.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Предупредить Гром\'гол',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эта смерть не должна быть напрасной, $n. Мы узнали, что Килнара стоит за всем, что происходит в округе. В этом нет ничего хорошего.$b$bСтоит заглянуть в лагерь Гром\'гол, что к западу отсюда. Может быть, мой связной там.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в лагерь Гром\'гол.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (29235,'Защита Гром\'гола','Надеюсь, тебя не пугают сражения, $n. Твой друг тролль был здесь и предупреждал нас о неистовстве Гурубаши. Никто бы не подумал, что получится такая славная битва.$b$bИди, присоединись к бою и покажи этим троллям Гурубаши, на что способна Орда!','Помогайте защищать лагерь Гром\'гол в течение трех минут.','Помогите защитить лагерь Гром\'гол','Поговорите с командиром Аггро\'гошем.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Защита Гром\'гола',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Надеюсь, тебя не пугают сражения, $n. Твой друг тролль был здесь и предупреждал нас о неистовстве Гурубаши. Никто бы не подумал, что получится такая славная битва.$b$bИди, присоединись к бою и покажи этим троллям Гурубаши, на что способна Орда!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Помогайте защищать лагерь Гром\'гол в течение трех минут.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Помогите защитить лагерь Гром\'гол',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с командиром Аггро\'гошем.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (29236,'В Укрытие Кофельнагель') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В Укрытие Кофельнагель',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29237,'Зомби вуду','Люди... Все они стали зомби, зомби вуду! И это не сулит нам ничего хорошего, $n.$b$bУбей их.$b$bЯ могу спасти зомби в течение нескольких мгновений после того, как они будут убиты. Превратить их обратно в людей, которыми они были раньше.$b$bНо мы должны действовать быстро. Зомби не дремлют.','Спасите 10 выживших из укрытия.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зомби вуду',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Люди... Все они стали зомби, зомби вуду! И это не сулит нам ничего хорошего, $n.$b$bУбей их.$b$bЯ могу спасти зомби в течение нескольких мгновений после того, как они будут убиты. Превратить их обратно в людей, которыми они были раньше.$b$bНо мы должны действовать быстро. Зомби не дремлют.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Спасите 10 выживших из укрытия.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (29238,'Скверный провиант','Некоторые выжившие говорили о еде, $n. Нужно проверить, в каком состоянии их провиант. У меня нехорошие предчувствия.','Проверьте состояние провианта в Укрытии Кольфенагель.','Занзил… Теперь все начинает проясняться. Если у меня получится разыскать моего связного, мы сможем начать планировать атаку. Пора положить конец этому безумию.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Скверный провиант',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Некоторые выжившие говорили о еде, $n. Нужно проверить, в каком состоянии их провиант. У меня нехорошие предчувствия.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проверьте состояние провианта в Укрытии Кольфенагель.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Занзил… Теперь все начинает проясняться. Если у меня получится разыскать моего связного, мы сможем начать планировать атаку. Пора положить конец этому безумию.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (29239,'Ветвь Нордрассила','За время, прошедшее с нашего последнего разговора, многое удалось выяснить.$b$bЯ сам отправлюсь в Нексус и заберу артефакт Анахроноса, но сначала использую его в своих целях. Теперь я тоже стал свидетелем того, что ты уже $gвидел:видела;.$b$bПрежде чем обсудить наши дальнейшие действия, разреши мне выразить тебе свою благодарность за помощь, как здесь, так и в царстве огня.','Заберите ветвь Нордрассила с Янтарной гряды в Борейской тундре.','Теперь ветвь Нордрассила объединена с вневременным оком.$B$BДаже для такого героя, как вы, это прекрасный подарок.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ветвь Нордрассила',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','За время, прошедшее с нашего последнего разговора, многое удалось выяснить.$b$bЯ сам отправлюсь в Нексус и заберу артефакт Анахроноса, но сначала использую его в своих целях. Теперь я тоже стал свидетелем того, что ты уже $gвидел:видела;.$b$bПрежде чем обсудить наши дальнейшие действия, разреши мне выразить тебе свою благодарность за помощь, как здесь, так и в царстве огня.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заберите ветвь Нордрассила с Янтарной гряды в Борейской тундре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь ветвь Нордрассила объединена с вневременным оком.$B$BДаже для такого героя, как вы, это прекрасный подарок.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29240,'Вывести из-под удара','Так вот, возвращаясь к нашему делу...$b$bЯ убежден в том, что видение в Нексусе является иллюзией Смертокрыла, специально предназначенной для того, чтобы разжечь распри среди нас в эти смутные времена.$b$bЕсли мы начнем конфликтовать, разрушитель миров станет лишь сильнее.$b$bНо я должен принять меры предосторожности.$b$bЯ поступлю мудро, если выведу Таресгосу из игры до поры до времени.','Сопроводите Калесгоса в Хладарру.$b$bПоговорите с ним, когда будете готовы.','Она умирает, Ролотомаси.$B$BЯ… я потерял ее.','Поговорите с Калесгосом в Хладарре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вывести из-под удара',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Так вот, возвращаясь к нашему делу...$b$bЯ убежден в том, что видение в Нексусе является иллюзией Смертокрыла, специально предназначенной для того, чтобы разжечь распри среди нас в эти смутные времена.$b$bЕсли мы начнем конфликтовать, разрушитель миров станет лишь сильнее.$b$bНо я должен принять меры предосторожности.$b$bЯ поступлю мудро, если выведу Таресгосу из игры до поры до времени.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сопроводите Калесгоса в Хладарру.$b$bПоговорите с ним, когда будете готовы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Она умирает, Ролотомаси.$B$BЯ… я потерял ее.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Калесгосом в Хладарре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (29241,'Повергнуть Низвергателя','<Умертвительница Залла указывает на виднеющийся вдали храм.>$b$bКогда Джин\'до умер в последний раз, то он, слабый и сломленный, смог набраться сил в мире духов.$b$bУ него всегда была власть над духами. Одного за другим он подчинил их своей воле, и чем больше душ он подчинял себе, тем больше он приближался к тому, чтобы вернуться в этот мир.$b$bИ вот он здесь...$b$bМы должны покончить с Джин\'до! Да пребудут с нами духи.','Убейте Джин\'до Низвергателя Богов в Зул\'Гурубе в героическом режиме.','<Умертвительница Залла прижимает руки к груди.>$B$BВот и все. Проливать кровь своих же братьев – тяжелая задача. Многие годы город Гурубаши видел только смерть.$B$BПусть лучше джунгли захватят Зул\'Гуруб и вытравят запах смерти из этого места.$B$BКровь и честь! Отныне для Сиаме-Куаши ты всегда будешь умертвительницей.','Поговорите с умертвительницей Заллой в Зул\'Гурубе, что в Северной Тернистой долине.','Низвергни его самого.','Джин\'до Низвергатель Богов') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Повергнуть Низвергателя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Умертвительница Залла указывает на виднеющийся вдали храм.>$b$bКогда Джин\'до умер в последний раз, то он, слабый и сломленный, смог набраться сил в мире духов.$b$bУ него всегда была власть над духами. Одного за другим он подчинил их своей воле, и чем больше душ он подчинял себе, тем больше он приближался к тому, чтобы вернуться в этот мир.$b$bИ вот он здесь...$b$bМы должны покончить с Джин\'до! Да пребудут с нами духи.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Джин\'до Низвергателя Богов в Зул\'Гурубе в героическом режиме.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Умертвительница Залла прижимает руки к груди.>$B$BВот и все. Проливать кровь своих же братьев – тяжелая задача. Многие годы город Гурубаши видел только смерть.$B$BПусть лучше джунгли захватят Зул\'Гуруб и вытравят запах смерти из этого места.$B$BКровь и честь! Отныне для Сиаме-Куаши ты всегда будешь умертвительницей.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с умертвительницей Заллой в Зул\'Гурубе, что в Северной Тернистой долине.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Низвергни его самого.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Джин\'до Низвергатель Богов',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (29242,'Цена бесценного','Слушай, $gдруг:подруга;. Я не знаю тебя, ты не знаешь меня. Но раз уж мы оба оказались здесь, передам тебе слова Ревилгаза.$b$bВдруг тебе захочется прогуляться по этим наводненным троллями ужасным джунглям. Вдруг во время этой прогулки, ты наткнешься на пару бесценных артефактов троллей. Вдруг тебе будет не лень принести эти артефакты мне. Возможно, в этом случае я тебя чем-нибудь награжу.$b$bТы и $gсам должен:сама должна; знать, что это для нашего проекта. Нет-нет, что это за проект – тебя волновать не должно.','Исследуйте Тайник Безумия и найдите загадочное украшение Гурубаши.','Что там у тебя?$B$BПридурочный идол в форме змеи? И что мне с ним делать? Разве что дать им кому-нибудь по башке, чтобы ограбить и заполучить что-то более ценное.$B$BЭта штука никому не нужна!<Брини швыряет украшение за спину, оно падает в воду.>$B$BЧто ж, спасибо за "помощь". Держи свою "награду".$B$BДурак.','Поговорите с Брини Болторезом в Зул\'Гурубе, что в Северной Тернистой долине.','Исследуйте Тайник Безумия.','Древний артефакт троллей') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Цена бесценного',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слушай, $gдруг:подруга;. Я не знаю тебя, ты не знаешь меня. Но раз уж мы оба оказались здесь, передам тебе слова Ревилгаза.$b$bВдруг тебе захочется прогуляться по этим наводненным троллями ужасным джунглям. Вдруг во время этой прогулки, ты наткнешься на пару бесценных артефактов троллей. Вдруг тебе будет не лень принести эти артефакты мне. Возможно, в этом случае я тебя чем-нибудь награжу.$b$bТы и $gсам должен:сама должна; знать, что это для нашего проекта. Нет-нет, что это за проект – тебя волновать не должно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Исследуйте Тайник Безумия и найдите загадочное украшение Гурубаши.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что там у тебя?$B$BПридурочный идол в форме змеи? И что мне с ним делать? Разве что дать им кому-нибудь по башке, чтобы ограбить и заполучить что-то более ценное.$B$BЭта штука никому не нужна!<Брини швыряет украшение за спину, оно падает в воду.>$B$BЧто ж, спасибо за "помощь". Держи свою "награду".$B$BДурак.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Брини Болторезом в Зул\'Гурубе, что в Северной Тернистой долине.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Исследуйте Тайник Безумия.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Древний артефакт троллей',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29243,'Удар в сердце','Во Владениях Рагнароса показался один из его воинов пламени. Настало время сражаться. Капитан Сайна просила тебя прибыть туда и помочь.$b$bКогда ты окажешься там, Суховет и остальные уже тоже присоединятся к битве. Быстрее отправляйся на северо-запад и помоги им.','Убейте воина пламени.','Вернитесь к капитану Сайне Нагоняющей Грозу на Аванпост Малфуриона, что на Огненной передовой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Удар в сердце',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Во Владениях Рагнароса показался один из его воинов пламени. Настало время сражаться. Капитан Сайна просила тебя прибыть туда и помочь.$b$bКогда ты окажешься там, Суховет и остальные уже тоже присоединятся к битве. Быстрее отправляйся на северо-запад и помоги им.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте воина пламени.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Сайне Нагоняющей Грозу на Аванпост Малфуриона, что на Огненной передовой.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29244,'Воин пламени','Капитан Сайна потребовала твоего немедленного прибытия во Владения Рагнароса. Там появился один из его воинов пламени, и Сайна думает, что это отличный шанс для нас сразиться с ним.$b$bОтправляйся туда как можно скорее.','Доложите о своем прибытии капитану Сайне Нагоняющей Грозу во Владениях Рагнароса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Воин пламени',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Капитан Сайна потребовала твоего немедленного прибытия во Владения Рагнароса. Там появился один из его воинов пламени, и Сайна думает, что это отличный шанс для нас сразиться с ним.$b$bОтправляйся туда как можно скорее.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доложите о своем прибытии капитану Сайне Нагоняющей Грозу во Владениях Рагнароса.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (29245,'Таинственное семечко','Потрясающе! Это же желудь!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Таинственное семечко',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Потрясающе! Это же желудь!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29246,'Облегчить боль','Верховный друид может выдержать невероятно сильную боль. Мне случалось лечить пострадавших от ожогов, которые почти круглосоточно кричали от боли, хотя их ожоги не были и наполовину такими серьезными, как у Хамуула.$b$bЯ чувствую, что сегодня ему гораздо хуже, чем обычно. К юго-востоку отсюда можно найти больших огненных элементалей. Принеси мне их сердца и я приготовлю из них успокаивающую мазь для нашего пострадавшего.','Соберите 4 охваченных пламенем сердца, убив огнелордов.','Мне нужно немедленно браться за работу и готовить мазь. Эти реагенты теряют свою эффективность с каждой минутой.$B$BСпасибо тебе, Асконий.','В этих сердцах есть как раз то, что нужно Хамуулу, чтобы отдохнуть от боли.','Вернитесь к Дорда\'эну Ткущему Ночь в Святилище Малорна на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Облегчить боль',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Верховный друид может выдержать невероятно сильную боль. Мне случалось лечить пострадавших от ожогов, которые почти круглосоточно кричали от боли, хотя их ожоги не были и наполовину такими серьезными, как у Хамуула.$b$bЯ чувствую, что сегодня ему гораздо хуже, чем обычно. К юго-востоку отсюда можно найти больших огненных элементалей. Принеси мне их сердца и я приготовлю из них успокаивающую мазь для нашего пострадавшего.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 4 охваченных пламенем сердца, убив огнелордов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мне нужно немедленно браться за работу и готовить мазь. Эти реагенты теряют свою эффективность с каждой минутой.$B$BСпасибо тебе, Асконий.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','В этих сердцах есть как раз то, что нужно Хамуулу, чтобы отдохнуть от боли.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дорда\'эну Ткущему Ночь в Святилище Малорна на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29247,'Вылечить раны','Здесь в святилище у нас достаточный запас медикаментов, но не стоит забывать о том, что идет война. И Хамуул – не единственный, кому могут понадобиться бинты.$b$bОгненные чудища, которых много в Гнезде Сетрии, носят огнеупорные повязки. Эти повязки могли бы помочь Хамуулу не хуже любых бинтов. Принеси мне эти повязки, и я использую их, чтобы перебинтовать верховного друида.','Соберите 4 покрытые серой повязки, убив огненных чудищ в Гнезде Сетрии.','Некоторые считают, что сера, которой покрыты эти повязки, имеет целительные свойства. Я не очень в это верю, но я готов вытерпеть этот запах, если есть хоть небольшая вероятность того, что повязки помогут.','Вернитесь к Дорда\'эну Ткущему Ночь в Святилище Малорна на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вылечить раны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Здесь в святилище у нас достаточный запас медикаментов, но не стоит забывать о том, что идет война. И Хамуул – не единственный, кому могут понадобиться бинты.$b$bОгненные чудища, которых много в Гнезде Сетрии, носят огнеупорные повязки. Эти повязки могли бы помочь Хамуулу не хуже любых бинтов. Принеси мне эти повязки, и я использую их, чтобы перебинтовать верховного друида.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 4 покрытые серой повязки, убив огненных чудищ в Гнезде Сетрии.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Некоторые считают, что сера, которой покрыты эти повязки, имеет целительные свойства. Я не очень в это верю, но я готов вытерпеть этот запах, если есть хоть небольшая вероятность того, что повязки помогут.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дорда\'эну Ткущему Ночь в Святилище Малорна на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29248,'Лечение отеков','После таких тяжелых ожогов верховный друид Хамуул страдает от отеков и волдырей, которыми поражены все ткани его тела. Те, кто ухаживает за ним, прикладывают огромные усилия для того, чтобы он мог дышать.$b$bОбычно, чтобы справиться с такими проблемами, мы делаем надрезы на теле, но он так слаб, $n. Сегодня я не могу сделать этого. Мне нужна твоя помощь.$b$bЧешуйки поджигателей могут помочь справиться с отеками, но только в том случае, если их будет много.','Соберите 100 чешуек поджигателей.','Ты собрал чешуйки? Я не могу решиться на то, чтобы сделать надрезы. Но нам нужно как-то бороться с отеками.','Вернитесь к Дорда\'эну Ткущему Ночь в Святилище Малорна на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лечение отеков',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','После таких тяжелых ожогов верховный друид Хамуул страдает от отеков и волдырей, которыми поражены все ткани его тела. Те, кто ухаживает за ним, прикладывают огромные усилия для того, чтобы он мог дышать.$b$bОбычно, чтобы справиться с такими проблемами, мы делаем надрезы на теле, но он так слаб, $n. Сегодня я не могу сделать этого. Мне нужна твоя помощь.$b$bЧешуйки поджигателей могут помочь справиться с отеками, но только в том случае, если их будет много.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 100 чешуек поджигателей.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты собрал чешуйки? Я не могу решиться на то, чтобы сделать надрезы. Но нам нужно как-то бороться с отеками.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дорда\'эну Ткущему Ночь в Святилище Малорна на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (29249,'Время посадки','Кажется, с желудем все нормально.$B$B<Аврилла пожимает плечами.>$B$BХватит терять время. Пора посадить его в землю и посмотреть, что из этого выйдет.$B$BК счастью для тебя, мы захватили с собой немного почвы, которая поможет нам обустроить лагерь.$B$BПочва уложена на кладбище к востоку от нас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Время посадки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кажется, с желудем все нормально.$B$B<Аврилла пожимает плечами.>$B$BХватит терять время. Пора посадить его в землю и посмотреть, что из этого выйдет.$B$BК счастью для тебя, мы захватили с собой немного почвы, которая поможет нам обустроить лагерь.$B$BПочва уложена на кладбище к востоку от нас.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (29250,'Связной','Ты не $gпохож:похожа; на зомби...$b$bТролль? Я видел одного, как раз перед атакой... Он предупреждал нас об опасности... Но было уже слишком поздно.$b$bТвой приятель отправился в Пиратскую Бухту, чтобы предупредить их...','Отправляйтесь в Пиратскую Бухту и найдите там связного Бвембы.','Я говорил барону Ревилгазу о зандаларской угрозе…') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Связной',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты не $gпохож:похожа; на зомби...$b$bТролль? Я видел одного, как раз перед атакой... Он предупреждал нас об опасности... Но было уже слишком поздно.$b$bТвой приятель отправился в Пиратскую Бухту, чтобы предупредить их...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Пиратскую Бухту и найдите там связного Бвембы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я говорил барону Ревилгазу о зандаларской угрозе…',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29251,'Интересы Пиратской Бухты','Послушай, $n. Ты очень $gпомог:помогла; нам, но этого недостаточно. Нужно остановить этих безумных троллей или хотя бы не дать им войти в Пиратскую Бухту.$b$bЯ отправлю туда разведчика, чтобы он наблюдал за обстановкой, но я хочу, чтобы ты $gотправился:отправилась; в Зул\'Гуруб и кое-что $gсделал:сделала;.$b$bПо крайней мере $gнашел:нашла; что-нибудь, что помешает троллям проникнуть в Пиратскую Бухту.$b$bСделаешь это – получишь награду.','Найдите артефакт, который мог бы помешать троллям Зул\'Гуруба проникнуть в Пиратскую Бухту.','Вернитесь к барону Ревилгазу в Пиратскую Бухту или к инспектору Бадабуму в Зул\'Гуруб.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Интересы Пиратской Бухты',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Послушай, $n. Ты очень $gпомог:помогла; нам, но этого недостаточно. Нужно остановить этих безумных троллей или хотя бы не дать им войти в Пиратскую Бухту.$b$bЯ отправлю туда разведчика, чтобы он наблюдал за обстановкой, но я хочу, чтобы ты $gотправился:отправилась; в Зул\'Гуруб и кое-что $gсделал:сделала;.$b$bПо крайней мере $gнашел:нашла; что-нибудь, что помешает троллям проникнуть в Пиратскую Бухту.$b$bСделаешь это – получишь награду.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите артефакт, который мог бы помешать троллям Зул\'Гуруба проникнуть в Пиратскую Бухту.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к барону Ревилгазу в Пиратскую Бухту или к инспектору Бадабуму в Зул\'Гуруб.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29252,'Интересы Пиратской Бухты','Меня прислал сюда барон Ревилгаз из Пиратской Бухты, чтобы я убедился, что нашествие троллей остановлено. Или хотя бы остановлено у подходов к Пиратской Бухте.$b$bОт тебя я хочу действий и результата.$b$bОтправляйся туда и убивай.$b$bМне нужно, чтобы ты $gнашел:нашла; нечто, что не даст этим троллям проникнуть в Пиратскую Бухту.$b$bВыполнишь это – можешь быть $gуверен:уверена;, что тебе заплатят.','Найдите артефакт, который мог бы помешать троллям Зул\'Гуруба проникнуть в Пиратскую Бухту.','Вернитесь к барону Ревилгазу в Пиратскую Бухту или к инспектору Бадабуму в Зул\'Гуруб.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Интересы Пиратской Бухты',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Меня прислал сюда барон Ревилгаз из Пиратской Бухты, чтобы я убедился, что нашествие троллей остановлено. Или хотя бы остановлено у подходов к Пиратской Бухте.$b$bОт тебя я хочу действий и результата.$b$bОтправляйся туда и убивай.$b$bМне нужно, чтобы ты $gнашел:нашла; нечто, что не даст этим троллям проникнуть в Пиратскую Бухту.$b$bВыполнишь это – можешь быть $gуверен:уверена;, что тебе заплатят.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите артефакт, который мог бы помешать троллям Зул\'Гуруба проникнуть в Пиратскую Бухту.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к барону Ревилгазу в Пиратскую Бухту или к инспектору Бадабуму в Зул\'Гуруб.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (29253,'Сверкающая награда','Сундук находится в статуе на острове Жанейро, что к северо-западу от Пиратской Бухты, в Тернистой долине.$b$bОтправляйся к статуе и забери свою награду, |3-6($c).','Достаньте сундук с сокровищами из статуи на острове Жанейро.','Вот оно, сокровище!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сверкающая награда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сундук находится в статуе на острове Жанейро, что к северо-западу от Пиратской Бухты, в Тернистой долине.$b$bОтправляйся к статуе и забери свою награду, |3-6($c).',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Достаньте сундук с сокровищами из статуи на острове Жанейро.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот оно, сокровище!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (29254,'Огненный плеточник','Маленький красный цветок радостно шевелит отростками. Кажется, ты ему нравишься!$B$BМожет быть, Аврилла захочет увидеть, что получилось из желудя.','Отведите багрового плеточника к Аврилле.','Не может быть! Что это за маленькое существо? Говоришь, оно увязалось за тобой?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Огненный плеточник',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Маленький красный цветок радостно шевелит отростками. Кажется, ты ему нравишься!$B$BМожет быть, Аврилла захочет увидеть, что получилось из желудя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отведите багрового плеточника к Аврилле.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Не может быть! Что это за маленькое существо? Говоришь, оно увязалось за тобой?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29255,'Изгарь','На лозе багрового плеточника появились какие-то вздутия. Если ничего не предпринять, его состояние может ухудшиться.$B$BК счастью, пламенные воины и пламенные покорители выделяют изгарь – вязкую субстанцию, которая должна помочь плеточнику.$B$BПеребей несколько отвратительных элементалей огня и достань мне это вещество.','Убивайте пламенных воинов и пламенных покорителей, пока не соберете 5 кусочков изгари.','Да, пахнет оно не очень, но плеточнику должно помочь.','Плеточник растет очень быстро.','Вернитесь к Аврилле на Аванпост Малфуриона на Огненной передовой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Изгарь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На лозе багрового плеточника появились какие-то вздутия. Если ничего не предпринять, его состояние может ухудшиться.$B$BК счастью, пламенные воины и пламенные покорители выделяют изгарь – вязкую субстанцию, которая должна помочь плеточнику.$B$BПеребей несколько отвратительных элементалей огня и достань мне это вещество.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убивайте пламенных воинов и пламенных покорителей, пока не соберете 5 кусочков изгари.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, пахнет оно не очень, но плеточнику должно помочь.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Плеточник растет очень быстро.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аврилле на Аванпост Малфуриона на Огненной передовой.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29256,'[DEPRECATED] Eat Your Heart Out','Hello $n. Checking in on your Fire Lasher?$B$BHe seems quite hungry, but no mixture of fertilizer or plant growth seems to interest him.$B$BSome plants are carnivorous, and I\'d like to test this rather unconventional theory.$B$BWould you retrieve some Lava Burster Hearts for me? The Lava Bursters frequent the fields to the north.','Retrieve 3 Lava Burster Hearts.','Вернитесь к Аврилле на Аванпост Малфуриона, что в Огненных Просторах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED] Eat Your Heart Out',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Hello $n. Checking in on your Fire Lasher?$B$BHe seems quite hungry, but no mixture of fertilizer or plant growth seems to interest him.$B$BSome plants are carnivorous, and I\'d like to test this rather unconventional theory.$B$BWould you retrieve some Lava Burster Hearts for me? The Lava Bursters frequent the fields to the north.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Retrieve 3 Lava Burster Hearts.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аврилле на Аванпост Малфуриона, что в Огненных Просторах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29257,'Украсть магмолии','Мы обнаружили новый вид цветов в Магматических ключах, что к северу отсюда. Это совершенно удивительно – они растут прямо в кипящей лаве!$b$bПожалуйста, сходи туда и собери для меня несколько образцов. Уверена, их детальное изучение поможет разгадать загадку твоего маленького друга.$b$bКстати, о нем – похоже, он очень хочет пойти с тобой. Будем надеяться, он сумеет вести себя прилично.','Соберите 8 магмолий в Магматических ключах к северу.','Превосходно! Чем больше времени я провожу в Огненных Просторах, тем больше убеждаюсь, что тут целая экосистема.','Вернитесь к Аврилле на Аванпост Малфуриона на Огненной передовой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Украсть магмолии',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы обнаружили новый вид цветов в Магматических ключах, что к северу отсюда. Это совершенно удивительно – они растут прямо в кипящей лаве!$b$bПожалуйста, сходи туда и собери для меня несколько образцов. Уверена, их детальное изучение поможет разгадать загадку твоего маленького друга.$b$bКстати, о нем – похоже, он очень хочет пойти с тобой. Будем надеяться, он сумеет вести себя прилично.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 магмолий в Магматических ключах к северу.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Превосходно! Чем больше времени я провожу в Огненных Просторах, тем больше убеждаюсь, что тут целая экосистема.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аврилле на Аванпост Малфуриона на Огненной передовой.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (29258,'Поиски метеорита') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поиски метеорита',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29259,'Прятки','Приятно вновь видеть тебя, $n. Твой плеточник придумал новую игру – прятки!$b$bИ, кажется, ему хочется поиграть с тобой.$b$bДождись, когда он спрячется, а потом ищи его здесь в лагере.$b$bА на случай, если найти его будет слишком сложно, – вот эта специальная дымка укажет направление, в котором нужно искать. Но не говори ему, что это я тебе помогла.','Найдите спрятавшегося огненного плеточника на Аванпосте Малфуриона.','Вернитесь к Аврилле на Аванпост Малфуриона в Огненных Просторах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прятки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приятно вновь видеть тебя, $n. Твой плеточник придумал новую игру – прятки!$b$bИ, кажется, ему хочется поиграть с тобой.$b$bДождись, когда он спрячется, а потом ищи его здесь в лагере.$b$bА на случай, если найти его будет слишком сложно, – вот эта специальная дымка укажет направление, в котором нужно искать. Но не говори ему, что это я тебе помогла.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите спрятавшегося огненного плеточника на Аванпосте Малфуриона.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аврилле на Аванпост Малфуриона в Огненных Просторах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (29261,'Вуду Зул\'Амана','Именно этой таблички и не хватало, чтобы магические формулы заработали, и магия от груды черепов перешла к вам и вашей группе!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вуду Зул\'Амана',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Именно этой таблички и не хватало, чтобы магические формулы заработали, и магия от груды черепов перешла к вам и вашей группе!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (29262,'Вуду Зул\'Гуруба','Именно этой таблички и не хватало, чтобы магические формулы заработали, и магия от кучи черепов перешла к вам и вашей группе!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вуду Зул\'Гуруба',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Именно этой таблички и не хватало, чтобы магические формулы заработали, и магия от кучи черепов перешла к вам и вашей группе!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29263,'Горькая пилюля','Если тебе интересно мое мнение, то я считаю, что нет такой проблемы, которую бы нельзя было решить при помощи бомб. А если с первого раза бомба не решает твою проблему – просто в следующий раз возьми бомбу побольше.$b$bТак вот, у лавовых озер, к северу отсюда, завелся большой червь, который пожирает людей. Чтобы его найти, следи за пузырями на поверхности лавы – это он дышит. Напади на него, а когда он приготовится тебя укусить, положи перед ним бомбу. Затем можешь отойти и полюбоваться фейерверком.$b$bЧто-то я еще хотела тебе сказать... Ах, да! Смотри, чтобы он тебя не сожрал.','Найдите подземного магмачервя по пузырькам от его дыхания. Затем убейте его, заставив проглотить горькую пилюлю.','Что я говорила! Бомбы Рикет решают любую проблему. Нужно лишь подобрать правильный размер.','Вернитесь к Дамеку Цветоброду на Аванпост Малфуриона, что на Огненной передовой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Горькая пилюля',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если тебе интересно мое мнение, то я считаю, что нет такой проблемы, которую бы нельзя было решить при помощи бомб. А если с первого раза бомба не решает твою проблему – просто в следующий раз возьми бомбу побольше.$b$bТак вот, у лавовых озер, к северу отсюда, завелся большой червь, который пожирает людей. Чтобы его найти, следи за пузырями на поверхности лавы – это он дышит. Напади на него, а когда он приготовится тебя укусить, положи перед ним бомбу. Затем можешь отойти и полюбоваться фейерверком.$b$bЧто-то я еще хотела тебе сказать... Ах, да! Смотри, чтобы он тебя не сожрал.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите подземного магмачервя по пузырькам от его дыхания. Затем убейте его, заставив проглотить горькую пилюлю.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что я говорила! Бомбы Рикет решают любую проблему. Нужно лишь подобрать правильный размер.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дамеку Цветоброду на Аванпост Малфуриона, что на Огненной передовой.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29264,'Поджигатели из Расплавленного потока','Поджигатели – самые преданные приспешники Рагнароса. Почти все они обитают в этой пещере и готовятся к новой атаке. Наш опорный пункт неплохо защищен, но нам не нужны никакие внезапные нападения этих червей.$b$bНет, это мы должны нанести первый удар.$b$bУничтожь их, $n.','Убейте 8 поджигателей в Расплавленном потоке.','Вернитесь к Тизали Вороне в Расплавленный поток, что на Огненной передовой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поджигатели из Расплавленного потока',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Поджигатели – самые преданные приспешники Рагнароса. Почти все они обитают в этой пещере и готовятся к новой атаке. Наш опорный пункт неплохо защищен, но нам не нужны никакие внезапные нападения этих червей.$b$bНет, это мы должны нанести первый удар.$b$bУничтожь их, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 поджигателей в Расплавленном потоке.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тизали Вороне в Расплавленный поток, что на Огненной передовой.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29265,'Огненные цветы','Моя подруга-друид, Чолуна, попросила нас собрать образцы растений, которые встретятся нам в Огненных Просторах...$b$b...Не знаю, кому принадлежала идея отправить ученых на передовую.$b$bТак или иначе – тебе же все равно нужно в пещеру, чтобы убить там разных существ. Посматривай заодно и под ноги, ладно?','Соберите 5 чертопоротников.','Я никогда не перестану им удивляться. Может это настоящие цветы, а может просто хрупкие каменные образования, но в любом случае тот факт, что они умудряются расти в таких неблагоприятных условиях, просто поразителен.$B$BНемедленно отправлю эти растения Аврилле для изучения.','Они растут повсюду. Просто будь внимательнее.','Поговорите с Чолуной в северной части Горнила, что на Огненной передовой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Огненные цветы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Моя подруга-друид, Чолуна, попросила нас собрать образцы растений, которые встретятся нам в Огненных Просторах...$b$b...Не знаю, кому принадлежала идея отправить ученых на передовую.$b$bТак или иначе – тебе же все равно нужно в пещеру, чтобы убить там разных существ. Посматривай заодно и под ноги, ладно?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 5 чертопоротников.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я никогда не перестану им удивляться. Может это настоящие цветы, а может просто хрупкие каменные образования, но в любом случае тот факт, что они умудряются расти в таких неблагоприятных условиях, просто поразителен.$B$BНемедленно отправлю эти растения Аврилле для изучения.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Они растут повсюду. Просто будь внимательнее.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Чолуной в северной части Горнила, что на Огненной передовой.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (29266,'DEPRECATED Zul\'Gurub Voodoo (NYI)') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','DEPRECATED Zul\'Gurub Voodoo (NYI)',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (29267,'Все изменится к лучшему','Столько жестокости, столько смертей. Его мать и братья погибли, а теперь и сам этот детеныш пантеры может умереть, если никто не позаботится о нем.$b$bСделайте доброе дело, возьмите малыша под свою опеку.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Все изменится к лучшему',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Столько жестокости, столько смертей. Его мать и братья погибли, а теперь и сам этот детеныш пантеры может умереть, если никто не позаботится о нем.$b$bСделайте доброе дело, возьмите малыша под свою опеку.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (29268,'Все изменится к лучшему','Столько жестокости, столько смертей. Его мать и братья погибли, а теперь и сам этот детеныш пантеры может умереть, если никто не позаботится о нем.$b$bСделайте доброе дело, возьмите малыша под свою опеку.','Позаботьтесь о детеныше пантеры. Ведь в конце концов это вы убили его мать.','Детеныш пантеры смотрит на вас так, как будто хочет сказать: "Ты будешь моим новым папой?"') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Все изменится к лучшему',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Столько жестокости, столько смертей. Его мать и братья погибли, а теперь и сам этот детеныш пантеры может умереть, если никто не позаботится о нем.$b$bСделайте доброе дело, возьмите малыша под свою опеку.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Позаботьтесь о детеныше пантеры. Ведь в конце концов это вы убили его мать.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Детеныш пантеры смотрит на вас так, как будто хочет сказать: "Ты будешь моим новым папой?"',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (29269,'Единое целое','Она пожертвовала собой и защитила меня.$b$bЯ не смогу перенести эту потерю, $n. Я должен обратиться к тебе с серьезной просьбой.$b$bНикогда ни один смертный не был связан с сущностью настоящего дракона, но с твоего разрешения я сделаю исключение.$b$bПожалуйста, раз в ней еще есть жизнь, разреши мне установить связь между тобой и Таресгосой?','Поговорите с Калесгосом и согласитесь на его предложение.','Я так благодарен тебе, Ролотомаси.$B$BЕсли бы тебя не оказалось рядом или ты не согласился помочь мне, я бы потерял Таресгосу.','Поговорите с Калесгосом в Хладарре.','Поговорите с Калесгосом в Хладарре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Единое целое',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Она пожертвовала собой и защитила меня.$b$bЯ не смогу перенести эту потерю, $n. Я должен обратиться к тебе с серьезной просьбой.$b$bНикогда ни один смертный не был связан с сущностью настоящего дракона, но с твоего разрешения я сделаю исключение.$b$bПожалуйста, раз в ней еще есть жизнь, разреши мне установить связь между тобой и Таресгосой?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Калесгосом и согласитесь на его предложение.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я так благодарен тебе, Ролотомаси.$B$BЕсли бы тебя не оказалось рядом или ты не согласился помочь мне, я бы потерял Таресгосу.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Поговорите с Калесгосом в Хладарре.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Калесгосом в Хладарре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29270,'Времени мало','Сейчас Таресгоса связана с тобой, $n, но это временно. Для того, чтобы окончательно связать вас, нужна сила Аспекта.$b$bПреемник Малигоса не будет избран раньше следующего затмения лун Азерота. Но связь с Таресгосой не продлится до этого момента.$b$bК счастью, есть способ выиграть столь необходимое нам время. Существуют могущественные элементы, которые могут помочь продлить действие эффектов ритуала. Некоторых из них можно найти в царстве огня, с которым ты уже $gзнаком:знакома;.$b$bСобери их, |3-6($c), и продли связь с сущностью Таресгосы до затмения.','Соберите 1000 пылающих углей в Огненных Просторах.','Поговорите с Калесгосом в Хладарре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Времени мало',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сейчас Таресгоса связана с тобой, $n, но это временно. Для того, чтобы окончательно связать вас, нужна сила Аспекта.$b$bПреемник Малигоса не будет избран раньше следующего затмения лун Азерота. Но связь с Таресгосой не продлится до этого момента.$b$bК счастью, есть способ выиграть столь необходимое нам время. Существуют могущественные элементы, которые могут помочь продлить действие эффектов ритуала. Некоторых из них можно найти в царстве огня, с которым ты уже $gзнаком:знакома;.$b$bСобери их, |3-6($c), и продли связь с сущностью Таресгосы до затмения.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 1000 пылающих углей в Огненных Просторах.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Калесгосом в Хладарре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29271,'Туда, где погорячее','Теперь у нас все будет в порядке. А твоя помощь нужна в Огненных Просторах. Иди через портал и помоги им.','Поговорите с генералом Талдрис Закат Луны на Аванпосте Малфуриона, что на Огненной передовой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Туда, где погорячее',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь у нас все будет в порядке. А твоя помощь нужна в Огненных Просторах. Иди через портал и помоги им.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с генералом Талдрис Закат Луны на Аванпосте Малфуриона, что на Огненной передовой.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29272,'Очень... Нужна... Вода...','Очень... Нужна... Вода...','Приведите Анрена Искателя Теней ко входу на Огненную передовую.','Поговорите с Толо Белым Копытом в Горниле, что на Огненной передовой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Очень... Нужна... Вода...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Очень... Нужна... Вода...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Приведите Анрена Искателя Теней ко входу на Огненную передовую.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Толо Белым Копытом в Горниле, что на Огненной передовой.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (29272,'Это ты спас Анрена! Моего лучшего друга Анрена.$B$BВ этой пещере мы разделились. Я не знаю, что мне делать без него.$B$BА ты такой находчивый $C. Возможно, потом мы попросим тебя о помощи. Благодаря тебе нам с Анреном больше не угрожает разлука.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это ты спас Анрена! Моего лучшего друга Анрена.$B$BВ этой пещере мы разделились. Я не знаю, что мне делать без него.$B$BА ты такой находчивый $C. Возможно, потом мы попросим тебя о помощи. Благодаря тебе нам с Анреном больше не угрожает разлука.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29273,'Измерение температуры','Огнеястребы, обитающие на Пике Огненного Венца, выдерживают колоссальные температуры. Хотя обычно они парят в небе, иногда можно увидеть, как они плещутся в потоках горячей лавы.$b$bНе так ли, Анрен?$b$bМы хотим узнать, насколько высока температура этой лавы. На Пике Огненного Венца есть три больших озера лавы. Возьми этот термометр и измерь температуру каждого.','Воспользуйтесь термометром Толо, чтобы измерить температуру в трех больших лавовых озерах на Пике Огненного Венца.','Эти результаты позволят нам лучше понять поведение огнеястребов и, что особенно важно, Алисразор, их новой огненной предводительницы.$B$BМы с Толо весьма благодарны тебе за помощь.','Вернитесь к Анрену Искателю Теней на Аванпост Малфуриона, что на Огненной передовой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Измерение температуры',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Огнеястребы, обитающие на Пике Огненного Венца, выдерживают колоссальные температуры. Хотя обычно они парят в небе, иногда можно увидеть, как они плещутся в потоках горячей лавы.$b$bНе так ли, Анрен?$b$bМы хотим узнать, насколько высока температура этой лавы. На Пике Огненного Венца есть три больших озера лавы. Возьми этот термометр и измерь температуру каждого.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь термометром Толо, чтобы измерить температуру в трех больших лавовых озерах на Пике Огненного Венца.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Эти результаты позволят нам лучше понять поведение огнеястребов и, что особенно важно, Алисразор, их новой огненной предводительницы.$B$BМы с Толо весьма благодарны тебе за помощь.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Анрену Искателю Теней на Аванпост Малфуриона, что на Огненной передовой.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29274,'Гончие Шэннокса','На самом большом острове Огненных Просторов наши войска столкнулись с Шэнноксом, поджигателем-охотником. Он и сам по себе грозный противник, но ко всему прочему у него еще есть гончие, которые постоянно нападают на наши войска.$b$bМудрый Толо считает, что было бы неплохо изучить природу этих псов. Я, конечно же, разделяю его мнение.$b$bНескольких гончих Шэннокса можно найти за Расплавленным потоком, под Горнилом. Собери остающийся после них пепел, и мы его изучим.','Соберите 6 небольших кучек пепла гончей.','Любая информация может помочь нам победить Шэннокса.','Вернитесь к Толо Белому Копыту на Аванпост Малфуриона, что на Огненной передовой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гончие Шэннокса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На самом большом острове Огненных Просторов наши войска столкнулись с Шэнноксом, поджигателем-охотником. Он и сам по себе грозный противник, но ко всему прочему у него еще есть гончие, которые постоянно нападают на наши войска.$b$bМудрый Толо считает, что было бы неплохо изучить природу этих псов. Я, конечно же, разделяю его мнение.$b$bНескольких гончих Шэннокса можно найти за Расплавленным потоком, под Горнилом. Собери остающийся после них пепел, и мы его изучим.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 6 небольших кучек пепла гончей.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Любая информация может помочь нам победить Шэннокса.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Толо Белому Копыту на Аванпост Малфуриона, что на Огненной передовой.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29275,'Методы Фэндрала','Друиды пламени... Об этом ордене друидов ни я, ни Толо до последнего времени даже и не слышали. А теперь, возглавляемые Фэндралом Оленьим Шлемом, они ставят под угрозу нашу миссию.$b$bКажется, они хранят часть запасов в Вулканических глубинах, что к северо-востоку отсюда. Возможно, если нам удастся завладеть частью этих предметов, нам удастся справиться с Фэндралом.','Соберите посох, книгу заклинаний, мешочек с реагентами и идол друидов пламени.','Поверь мне, любая добытая нами информация может пригодиться нам, чтобы понять источник сил Фэндрала.','Вернитесь к Толо Белому Копыту на Аванпост Малфуриона, что на Огненной передовой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Методы Фэндрала',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Друиды пламени... Об этом ордене друидов ни я, ни Толо до последнего времени даже и не слышали. А теперь, возглавляемые Фэндралом Оленьим Шлемом, они ставят под угрозу нашу миссию.$b$bКажется, они хранят часть запасов в Вулканических глубинах, что к северо-востоку отсюда. Возможно, если нам удастся завладеть частью этих предметов, нам удастся справиться с Фэндралом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите посох, книгу заклинаний, мешочек с реагентами и идол друидов пламени.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Поверь мне, любая добытая нами информация может пригодиться нам, чтобы понять источник сил Фэндрала.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Толо Белому Копыту на Аванпост Малфуриона, что на Огненной передовой.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29276,'Королева огненных пауков','Кладка Вдовы, что к северо-востоку отсюда, получила свое название в связи с Бет\'тилак, огромной королевой огненных пауков. Ее яд и паутина, которую она плетет, создают постоянную угрозу для наших солдат.$b$bМы думаем, что если мы изучим обитающих здесь, на Огненной передовой, огненных пауков, то полученная информация поможет нам справиться и с Бет\'тилак. Постарайся любым способом добыть образцы их яда и паутинной жидкости, а затем возвращайся к моему другу Анрену.','Соберите 8 образцов огненного яда и 8 образцов обжигающей паутинной жидкости.','Вернитесь к Анрену Искателю Теней на Аванпост Малфуриона, что на Огненной передовой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Королева огненных пауков',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кладка Вдовы, что к северо-востоку отсюда, получила свое название в связи с Бет\'тилак, огромной королевой огненных пауков. Ее яд и паутина, которую она плетет, создают постоянную угрозу для наших солдат.$b$bМы думаем, что если мы изучим обитающих здесь, на Огненной передовой, огненных пауков, то полученная информация поможет нам справиться и с Бет\'тилак. Постарайся любым способом добыть образцы их яда и паутинной жидкости, а затем возвращайся к моему другу Анрену.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 образцов огненного яда и 8 образцов обжигающей паутинной жидкости.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Анрену Искателю Теней на Аванпост Малфуриона, что на Огненной передовой.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (29277,'Druid Tree, Stage 3 Tracking') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Druid Tree, Stage 3 Tracking',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29278,'Живой обсидиан','Ты $gвидел:видела; огненные шары, которые падали с неба? Один из них упал в поля, которые находятся к северу отсюда. Это метеорит из живого обсидиана!$b$bЯ смогу использовать этот материал для создания жаропрочной брони и оружия для наших солдат. Не принесешь мне его?$b$bОтправляйся к Магматическим ключам и прикоснись к магнитному камню. Просто стой там и жди. Когда снова упадут метеориты, собери их, пока они не разбились.','Соберите 10 обсидиановых метеоритов.','Потрясающе! Я могу браться за работу.','Как идут дела? Удалось найти метеориты?','Вернитесь к Дамеку Цветоброду на Аванпост Малфуриона, что на Огненной передовой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Живой обсидиан',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gвидел:видела; огненные шары, которые падали с неба? Один из них упал в поля, которые находятся к северу отсюда. Это метеорит из живого обсидиана!$b$bЯ смогу использовать этот материал для создания жаропрочной брони и оружия для наших солдат. Не принесешь мне его?$b$bОтправляйся к Магматическим ключам и прикоснись к магнитному камню. Просто стой там и жди. Когда снова упадут метеориты, собери их, пока они не разбились.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 обсидиановых метеоритов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Потрясающе! Я могу браться за работу.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как идут дела? Удалось найти метеориты?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дамеку Цветоброду на Аванпост Малфуриона, что на Огненной передовой.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29279,'Наполнение лунного колодца','Мы построили лунный колодец, но пользы от него мало, пока он не наполнен священными водами Источника Вечности.$b$bА когда колодец будет действовать, мы сможем освящать наши запасы продовольствия и обеспечить тебе защиту от огня при помощи благословения.$b$bКогда соберешь достаточное количество знаков, поговори с Матой Коготь в Святилище Малорна. Она поможет тебе организовать транспортировку воды.','Получите 125 знаков Древа Жизни.','Договоритесь о священных водах для лунного колодца с Матой Коготь, которая находится в Святилище Малорна, что на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наполнение лунного колодца',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы построили лунный колодец, но пользы от него мало, пока он не наполнен священными водами Источника Вечности.$b$bА когда колодец будет действовать, мы сможем освящать наши запасы продовольствия и обеспечить тебе защиту от огня при помощи благословения.$b$bКогда соберешь достаточное количество знаков, поговори с Матой Коготь в Святилище Малорна. Она поможет тебе организовать транспортировку воды.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Получите 125 знаков Древа Жизни.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Договоритесь о священных водах для лунного колодца с Матой Коготь, которая находится в Святилище Малорна, что на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (29280,'Питающие воды','Тебе будет приятно узнать, что воды благополучно доставили нам. Теперь, когда лунный колодец полон, а мы находимся под сенью древа-стража, я даже иногда забываю о том, что мы в Огненных Просторах.$B$BЯ перенесла благословение лунного колодца на все эти деревья и кусты. Прежде чем уйти, возьми с собой эти плоды. Они освежают куда больше, чем ты можешь вообразить.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Питающие воды',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебе будет приятно узнать, что воды благополучно доставили нам. Теперь, когда лунный колодец полон, а мы находимся под сенью древа-стража, я даже иногда забываю о том, что мы в Огненных Просторах.$B$BЯ перенесла благословение лунного колодца на все эти деревья и кусты. Прежде чем уйти, возьми с собой эти плоды. Они освежают куда больше, чем ты можешь вообразить.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29281,'Дополнительное оружие','Здешним друидам нечем как следует делать свою работу. Если мы собираемся объединиться, надо обзавестись подходящими игрушками, чтобы было что показать этому Рагнаросу и тем, кто к нему примкнул. У меня есть одна приятельница там, за порталом.$b$bСобери немного этих знаков и иди к Мате Коготь. Там спроси Рикет. Она нужна нам здесь, чтобы показать врагу, чего мы стоим.','Получите 125 знаков Древа Жизни.','Обратитесь к Мате Коготь в Святилище Малорна, что на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дополнительное оружие',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Здешним друидам нечем как следует делать свою работу. Если мы собираемся объединиться, надо обзавестись подходящими игрушками, чтобы было что показать этому Рагнаросу и тем, кто к нему примкнул. У меня есть одна приятельница там, за порталом.$b$bСобери немного этих знаков и иди к Мате Коготь. Там спроси Рикет. Она нужна нам здесь, чтобы показать врагу, чего мы стоим.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Получите 125 знаков Древа Жизни.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Обратитесь к Мате Коготь в Святилище Малорна, что на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (29282,'Отличное вооружение') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отличное вооружение',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (29282,'Привет! Рада снова видеть тебя!$B$BУ меня тут все в порядке! Так приятно было снова встретиться с Дамеком. Никогда не думала, что мне удастся найти общий язык с дворфом, но, оказывается, у нас с ним совершенно одинаковые взгляды на важные вещи.$B$BТак что иди, занимайся своими делами. У нас тут все хорошо. Когда у нас будет что-то готово для тебя, я сразу сообщу!') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Привет! Рада снова видеть тебя!$B$BУ меня тут все в порядке! Так приятно было снова встретиться с Дамеком. Никогда не думала, что мне удастся найти общий язык с дворфом, но, оказывается, у нас с ним совершенно одинаковые взгляды на важные вещи.$B$BТак что иди, занимайся своими делами. У нас тут все хорошо. Когда у нас будет что-то готово для тебя, я сразу сообщу!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29283,'Призыв Древних','Получите 125 знаков Древа Жизни.','Я понимаю. Мы готовы. Мы присоединимся к вам. Встретимся с другой стороны портала.','Приветствую тебя.','Поговорите со Старокроном в Святилище Малорна на Хиджале и заручитесь поддержкой Древних.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Призыв Древних',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Получите 125 знаков Древа Жизни.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я понимаю. Мы готовы. Мы присоединимся к вам. Встретимся с другой стороны портала.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Приветствую тебя.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите со Старокроном в Святилище Малорна на Хиджале и заручитесь поддержкой Древних.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (29284,'Помощь Древних') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Помощь Древних',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (29284,'Ты позвал нас на помощь в правильный момент, $C. Меня беспокоили мысли о том, сможем ли мы выстоять против существ этой стихии, но защита древа-стража оказалась очень надежной.$B$BМы сделаем все, что в наших силах, чтобы помочь тебе. Суховет встретился с твоими союзниками и обсуждает с ними, как загнать в угол подручных Рагнароса. Когда придет время, поговори с ним.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты позвал нас на помощь в правильный момент, $C. Меня беспокоили мысли о том, сможем ли мы выстоять против существ этой стихии, но защита древа-стража оказалась очень надежной.$B$BМы сделаем все, что в наших силах, чтобы помочь тебе. Суховет встретился с твоими союзниками и обсуждает с ними, как загнать в угол подручных Рагнароса. Когда придет время, поговори с ним.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29285,'Затмение','Пришло время выбора нового аспекта, $n.$b$bПраво присутствовать на церемонии имеют только синие драконы, но твоя связь с Таресгосой делает твое присутствие необходимым.$b$bЯ должен просить тебя принять ее облик и проголосовать от ее имени.$b$bНе мешкай. Затмение совсем скоро...','Вместе с Калесгосом отправляйтесь на совет синих драконов.$b$bПоговорите с Калесгосом в Хладарре, когда будете готовы.','Поговорите с Калесгосом в Хладарре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Затмение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пришло время выбора нового аспекта, $n.$b$bПраво присутствовать на церемонии имеют только синие драконы, но твоя связь с Таресгосой делает твое присутствие необходимым.$b$bЯ должен просить тебя принять ее облик и проголосовать от ее имени.$b$bНе мешкай. Затмение совсем скоро...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вместе с Калесгосом отправляйтесь на совет синих драконов.$b$bПоговорите с Калесгосом в Хладарре, когда будете готовы.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Калесгосом в Хладарре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (29286,'Druid Tree, Stage 2 Tracking') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Druid Tree, Stage 2 Tracking',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29287,'Орнитологический интерес','Хоть огнеястребы и являются порождениями огня, в целом они ведут себя примерно так же, как обычные птицы. Поэтому мне и интересно, каково их происхождение.$b$bЯ думаю, мы могли бы попробовать дрессировать их. Может быть, даже одомашнить. И использовать против наших врагов.$b$bВозьми одно из яиц огнеястребов на Пике Огненного Венца. Твоя задача – принести его сюда целым и невредимым. Я позабочусь обо всем остальном.','Заберите с Пика Огненного Венца яйцо огнеястреба.','Отлично! Возвращайся ко мне через день-два, и мы посмотрим, как будут развиваться события.','Тебе удалось раздобыть яйцо?','Вернитесь к Мортису Шелесту Крыла в северную часть Горнила, что на Огненной передовой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Орнитологический интерес',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хоть огнеястребы и являются порождениями огня, в целом они ведут себя примерно так же, как обычные птицы. Поэтому мне и интересно, каково их происхождение.$b$bЯ думаю, мы могли бы попробовать дрессировать их. Может быть, даже одомашнить. И использовать против наших врагов.$b$bВозьми одно из яиц огнеястребов на Пике Огненного Венца. Твоя задача – принести его сюда целым и невредимым. Я позабочусь обо всем остальном.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заберите с Пика Огненного Венца яйцо огнеястреба.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! Возвращайся ко мне через день-два, и мы посмотрим, как будут развиваться события.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось раздобыть яйцо?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мортису Шелесту Крыла в северную часть Горнила, что на Огненной передовой.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29288,'Начнем, пока они еще маленькие','Наши разведчики сообщают, что на пике появилось множество птенцов огнеястребов. Вероятно, они вылупились из яиц совсем недавно. И это очень хорошо, так как в таком возрасте их очень легко приручить.$b$bЗнаю, моя просьба может показаться странной или даже негуманной, но если ты принесешь мне нескольких птенцов, я смогу выдрессировать их, чтобы в дальнейшем они помогали нам в военных действиях.$b$bЧто скажешь?','Соберите 5 птенцов огнеястреба.','Ума не приложу, кем же считать этих созданий. Ведут они себя так же, как и многие птицы, но совершенно ясно, что эти существа имеют огненную природу.$B$BНепонятно, почему Рагнарос и его приспешники не попытались приручить их и натравить на нас...','Вернитесь к Мортису Шелесту Крыла в северную часть Горнила, что на Огненной передовой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Начнем, пока они еще маленькие',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наши разведчики сообщают, что на пике появилось множество птенцов огнеястребов. Вероятно, они вылупились из яиц совсем недавно. И это очень хорошо, так как в таком возрасте их очень легко приручить.$b$bЗнаю, моя просьба может показаться странной или даже негуманной, но если ты принесешь мне нескольких птенцов, я смогу выдрессировать их, чтобы в дальнейшем они помогали нам в военных действиях.$b$bЧто скажешь?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 5 птенцов огнеястреба.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ума не приложу, кем же считать этих созданий. Ведут они себя так же, как и многие птицы, но совершенно ясно, что эти существа имеют огненную природу.$B$BНепонятно, почему Рагнарос и его приспешники не попытались приручить их и натравить на нас...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мортису Шелесту Крыла в северную часть Горнила, что на Огненной передовой.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29289,'Материнский гнев','Неудивительно, что мы вызвали гнев матриарха тем, что забрали птенцов и стали их обучать, преследуя свои собственные интересы. Это совершенно естественно. И даже немного трагично. Если смотреть на ситуацию с этой стороны, то мы – настоящие злодеи.$b$bНо сейчас не время предаваться подобным мыслям. Эти создания – порождения огня, и при первом же удобном случае они бы лишили жизни кого-нибудь из нас. Разгневав матриарха, мы навлекли на себя большую опасность.$b$bПоэтому кто-то должен остудить ее пыл, и, боюсь, ты являешься наиболее подходящей кандидатурой.','Убейте огнеястреба-матриарха.','Вернитесь к Мортису Шелесту Крыла в северную часть Горнила, что на Огненной передовой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Материнский гнев',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Неудивительно, что мы вызвали гнев матриарха тем, что забрали птенцов и стали их обучать, преследуя свои собственные интересы. Это совершенно естественно. И даже немного трагично. Если смотреть на ситуацию с этой стороны, то мы – настоящие злодеи.$b$bНо сейчас не время предаваться подобным мыслям. Эти создания – порождения огня, и при первом же удобном случае они бы лишили жизни кого-нибудь из нас. Разгневав матриарха, мы навлекли на себя большую опасность.$b$bПоэтому кто-то должен остудить ее пыл, и, боюсь, ты являешься наиболее подходящей кандидатурой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте огнеястреба-матриарха.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мортису Шелесту Крыла в северную часть Горнила, что на Огненной передовой.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29290,'Огонь в небе','Ты только посмотри на это! Невероятно! Ему еще и двух дней нет, а он уже полностью вырос. К сожалению, я предполагаю, что их жизненный цикл просто-напросто очень короткий. Поэтому нам нужно использовать имеющееся время максимально эффективно.$b$bЕго обучение прошло отлично. Возьми этого огнеястреба и разбей с его помощью войска врага, собранные у крепости Рагнароса.$b$bНе жалей никого, |3-6($r).','С помощью дрессированного огнеястреба убейте 100 поджигателей, 40 пауков-пеплопрядов и 3 огненных повелителей, обитающих в Огненных Просторах.','Полагаю, атака удалась? Великолепно! Сейчас самое время пробить брешь в защите Рагнароса.','Вернитесь к Мортису Шелесту Крыла в северную часть Горнила, что на Огненной передовой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Огонь в небе',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты только посмотри на это! Невероятно! Ему еще и двух дней нет, а он уже полностью вырос. К сожалению, я предполагаю, что их жизненный цикл просто-напросто очень короткий. Поэтому нам нужно использовать имеющееся время максимально эффективно.$b$bЕго обучение прошло отлично. Возьми этого огнеястреба и разбей с его помощью войска врага, собранные у крепости Рагнароса.$b$bНе жалей никого, |3-6($r).',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','С помощью дрессированного огнеястреба убейте 100 поджигателей, 40 пауков-пеплопрядов и 3 огненных повелителей, обитающих в Огненных Просторах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Полагаю, атака удалась? Великолепно! Сейчас самое время пробить брешь в защите Рагнароса.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мортису Шелесту Крыла в северную часть Горнила, что на Огненной передовой.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (29291,'Прямое парашютирование','Вернитесь к Мортису Шелесту Крыла в северную часть Горнила, что на Огненной передовой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прямое парашютирование',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мортису Шелесту Крыла в северную часть Горнила, что на Огненной передовой.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (29292,'Огнеястреб','Вернитесь к Мортису Шелесту Крыла в северную часть Горнила, что на Огненной передовой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Огнеястреб',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мортису Шелесту Крыла в северную часть Горнила, что на Огненной передовой.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29293,'Опаленные крылья','Многие из наших друидов-воронов отправились на пик, чтобы попытаться собрать несколько яиц огнеястребов, но я опасаюсь, что вероятность успеха невелика. Горячие потоки воздуха, поднимающиеся от земли превращают полеты в очень опасное занятие. Да и сами огнеястребы вряд ли будут настроены доброжелательно.$b$bЯ хочу, чтобы ты $gотправился:отправилась; туда и $gспас:спасла; как можно больше друидов. У меня уже все готово – бинты, лубки, мазь от ожогов, нюхательная соль... все, что нужно, чтобы поставить их на ноги. При условии, что они вернутся живыми. Пожалуйста, торопись, и помоги всем, кому сможешь.','Спасите 5 раненых друидов-воронов на Пике Огненного Венца.','Вернитесь к Арторну Песне Ветра в северную часть Горнила, что на Огненной передовой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Опаленные крылья',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Многие из наших друидов-воронов отправились на пик, чтобы попытаться собрать несколько яиц огнеястребов, но я опасаюсь, что вероятность успеха невелика. Горячие потоки воздуха, поднимающиеся от земли превращают полеты в очень опасное занятие. Да и сами огнеястребы вряд ли будут настроены доброжелательно.$b$bЯ хочу, чтобы ты $gотправился:отправилась; туда и $gспас:спасла; как можно больше друидов. У меня уже все готово – бинты, лубки, мазь от ожогов, нюхательная соль... все, что нужно, чтобы поставить их на ноги. При условии, что они вернутся живыми. Пожалуйста, торопись, и помоги всем, кому сможешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Спасите 5 раненых друидов-воронов на Пике Огненного Венца.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Арторну Песне Ветра в северную часть Горнила, что на Огненной передовой.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29294,'Живые угли','Некоторые из наших разведчиков сообщали, что видели на склонах Пика Огненного Венца языки пламени, казавшиеся живыми.$b$bЕсли сообщения точны, то нам следует немедленно изучить это явление. Мы еще не до конца понимает природу атакующих нас элементалей, так что это может нам очень помочь.','Соберите 6 живых углей.','Вернитесь к Арторну Песне Ветра в северную часть Горнила, что на Огненной передовой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Живые угли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Некоторые из наших разведчиков сообщали, что видели на склонах Пика Огненного Венца языки пламени, казавшиеся живыми.$b$bЕсли сообщения точны, то нам следует немедленно изучить это явление. Мы еще не до конца понимает природу атакующих нас элементалей, так что это может нам очень помочь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 6 живых углей.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Арторну Песне Ветра в северную часть Горнила, что на Огненной передовой.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29295,'Чем больше, тем лучше','Ты что, действительно $gсобрался:собралась; сражаться с чудовищами в этом наряде? Да ты там сгоришь как спичка без моих обсидиановых изделий! Хороших вещей много не бывает!$B$BВ общем так, $gприятель:подруга;, за соответствующую плату я могу изготовить для тебя лучшие доспехи, но для этого мне понадобится сырье – живой обсидиан.$B$BОбсидиановые каратели, которые обитают на Пике Огненного Венца, состоят из чистейшего материала, который мне и нужен. Отправляйся за добычей, а как перебьешь их, возвращайся ко мне с обсидианом.','Отправляйтесь на Пик Огненного Венца и убивайте обсидиановых карателей, пока не соберете 10 частичек живого обсидиана.','Вернитесь к Дамеку Цветоброду на Аванпост Малфуриона, что на Огненной передовой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чем больше, тем лучше',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты что, действительно $gсобрался:собралась; сражаться с чудовищами в этом наряде? Да ты там сгоришь как спичка без моих обсидиановых изделий! Хороших вещей много не бывает!$B$BВ общем так, $gприятель:подруга;, за соответствующую плату я могу изготовить для тебя лучшие доспехи, но для этого мне понадобится сырье – живой обсидиан.$B$BОбсидиановые каратели, которые обитают на Пике Огненного Венца, состоят из чистейшего материала, который мне и нужен. Отправляйся за добычей, а как перебьешь их, возвращайся ко мне с обсидианом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь на Пик Огненного Венца и убивайте обсидиановых карателей, пока не соберете 10 частичек живого обсидиана.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дамеку Цветоброду на Аванпост Малфуриона, что на Огненной передовой.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (29295,'Подойдет. Молодчина, Хитбит.','Принес мне сырье?') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Подойдет. Молодчина, Хитбит.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Принес мне сырье?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29296,'Защита территории','Наше присутствие не нравится огнеястребам. Они начинают вести себя очень враждебно и это уже не просто обычная защита территории. Я боюсь, что если мы ничего не предпримем, то вскоре они нападут на наше дерево и совсем не факт, что мы сможем выдержать удар.$b$bОтправляйся на Пик Огненного Венца и сделай то, что необходимо, чтобы сократить их численность. На данный момент меня куда больше волнует наша, а не их безопасность, так что будь $gрешителен:решительна;.','Убейте 5 огнеястребов.','Вернитесь к Арторну Песне Ветра в северную часть Горнила, что на Огненной передовой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Защита территории',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наше присутствие не нравится огнеястребам. Они начинают вести себя очень враждебно и это уже не просто обычная защита территории. Я боюсь, что если мы ничего не предпримем, то вскоре они нападут на наше дерево и совсем не факт, что мы сможем выдержать удар.$b$bОтправляйся на Пик Огненного Венца и сделай то, что необходимо, чтобы сократить их численность. На данный момент меня куда больше волнует наша, а не их безопасность, так что будь $gрешителен:решительна;.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 5 огнеястребов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Арторну Песне Ветра в северную часть Горнила, что на Огненной передовой.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29297,'Пока, пташка!','Друиды Оленьего Шлема оказывают нам яростное сопротивление в Лагере Возгорания к северо-востоку отсюда.$B$BДруиды парят над нами в форме огненных воронов и наносят удар, когда мы этого меньше всего ожидаем. Хуже всего то, что они держатся на расстоянии, чтобы мы не могли их атаковать!$B$BЕсли бы не Дамек, нам бы пришлось совсем туго. Он одолжил мне свой верный гарпун, который точно попадает в цель даже в местном плотном воздухе.$B$BВозьми-ка этот дворфийский гарпун и сбей с его помощью несколько пташек!','С помощью противоптичьего гарпуна убейте 3 друидов пламени, находящихся в форме огненных воронов.','Эти проклятые птицы мертвы? Вот и славно!','Вернитесь к Дамеку Цветоброду на Аванпост Малфуриона, что на Огненной передовой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пока, пташка!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Друиды Оленьего Шлема оказывают нам яростное сопротивление в Лагере Возгорания к северо-востоку отсюда.$B$BДруиды парят над нами в форме огненных воронов и наносят удар, когда мы этого меньше всего ожидаем. Хуже всего то, что они держатся на расстоянии, чтобы мы не могли их атаковать!$B$BЕсли бы не Дамек, нам бы пришлось совсем туго. Он одолжил мне свой верный гарпун, который точно попадает в цель даже в местном плотном воздухе.$B$BВозьми-ка этот дворфийский гарпун и сбей с его помощью несколько пташек!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','С помощью противоптичьего гарпуна убейте 3 друидов пламени, находящихся в форме огненных воронов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Эти проклятые птицы мертвы? Вот и славно!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дамеку Цветоброду на Аванпост Малфуриона, что на Огненной передовой.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29298,'Покрытый гарью медальон','Медальон украшен резным узором в форме листьев, но все остальные детали либо стерлись со временем, либо уничтожены огнем. Похоже, что медальон принадлежал друидам.$b$bНа Лунной поляне бывает очень много друидов. Если кто-то и может определить место происхождения медальона, то это Рабин Сатурна из Ночной Гавани.','Отнесите покрытый гарью медальон Рабину Сатурне в Ночную Гавань, что на Лунной поляне.','Что это у тебя? Ожерелье? А, нет, медальон…$B$BНе может быть…','Отнесите покрытый гарью медальон Рабину Сатурне в Ночную Гавань, что на Лунной поляне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Покрытый гарью медальон',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Медальон украшен резным узором в форме листьев, но все остальные детали либо стерлись со временем, либо уничтожены огнем. Похоже, что медальон принадлежал друидам.$b$bНа Лунной поляне бывает очень много друидов. Если кто-то и может определить место происхождения медальона, то это Рабин Сатурна из Ночной Гавани.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите покрытый гарью медальон Рабину Сатурне в Ночную Гавань, что на Лунной поляне.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что это у тебя? Ожерелье? А, нет, медальон…$B$BНе может быть…',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите покрытый гарью медальон Рабину Сатурне в Ночную Гавань, что на Лунной поляне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29299,'Некоторые любят погорячее','Мои исследования продвигаются, $n. Если судить по флоре этих мест, то вполне вероятно, что твой плеточник тоже пользуется высокотемпературными жидкостями в качестве источника питания.$b$bЯ бы хотела, чтобы ты $gпомог:помогла; мне провести небольшой эксперимент. В Магматических ключах, что к северу от нас, живут скорпионы-огнеплюи, которые способны создавать огненные лужицы.$b$bОтведи туда своего плеточника и посмотри, как он будет себя вести возле огненных луж, которые создают эти скорпионы.','Отведите своего багрового плеточника к Магматическим ключам, чтобы он попил из 6 огненных луж, созданных скорпионами-огнеплюями.','Сработало? Моя теория верна?','Вернитесь к Аврилле на Аванпост Малфуриона на Огненной передовой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Некоторые любят погорячее',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мои исследования продвигаются, $n. Если судить по флоре этих мест, то вполне вероятно, что твой плеточник тоже пользуется высокотемпературными жидкостями в качестве источника питания.$b$bЯ бы хотела, чтобы ты $gпомог:помогла; мне провести небольшой эксперимент. В Магматических ключах, что к северу от нас, живут скорпионы-огнеплюи, которые способны создавать огненные лужицы.$b$bОтведи туда своего плеточника и посмотри, как он будет себя вести возле огненных луж, которые создают эти скорпионы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отведите своего багрового плеточника к Магматическим ключам, чтобы он попил из 6 огненных луж, созданных скорпионами-огнеплюями.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сработало? Моя теория верна?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аврилле на Аванпост Малфуриона на Огненной передовой.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29302,'Сокрытые тайны','Инициалы стерлись с этого медальона, но я чувствую исходящую от него силу и по ней могу предположить, что владеть им могла только Лиара, друид пламени.$b$bОтойди-ка назад, посмотрим, какие сюрпризы нам готовит этот медальон.','Станьте свидетелями воспоминаний, заключенных в покрытом гарью медальоне.','Поговорите с Рабином Сатурной в Ночной Гавани на Лунной поляне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сокрытые тайны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Инициалы стерлись с этого медальона, но я чувствую исходящую от него силу и по ней могу предположить, что владеть им могла только Лиара, друид пламени.$b$bОтойди-ка назад, посмотрим, какие сюрпризы нам готовит этот медальон.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Станьте свидетелями воспоминаний, заключенных в покрытом гарью медальоне.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Рабином Сатурной в Ночной Гавани на Лунной поляне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29303,'Семья и трагедия','С твоей стороны было очень предусмотрительно принести этот медальон мне, $n. Я отношусь к тем немногим, кто знает, где покоится тело Вальстанна.$b$bТы найдешь его могилу на маленьком кладбище на юго-востоке от Астранаара, что в Ясеневом лесу. Отнеси туда этот медальон. Возможно, тогда он откроет еще больше воспоминаний Лиары.$b$bПрощай, $n, и удачи тебе на твоем пути.','Отнесите покрытый гарью медальон к могиле ночного эльфа недалеко от Астранаара в Ясеневом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Семья и трагедия',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','С твоей стороны было очень предусмотрительно принести этот медальон мне, $n. Я отношусь к тем немногим, кто знает, где покоится тело Вальстанна.$b$bТы найдешь его могилу на маленьком кладбище на юго-востоке от Астранаара, что в Ясеневом лесу. Отнеси туда этот медальон. Возможно, тогда он откроет еще больше воспоминаний Лиары.$b$bПрощай, $n, и удачи тебе на твоем пути.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите покрытый гарью медальон к могиле ночного эльфа недалеко от Астранаара в Ясеневом лесу.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29304,'Псы войны','Наши войска терпят поражение от необузданных чудовищ – огнедышащих гончих.$b$bЭти псы ничего не боятся и не остановятся, пока не утолят свою жажду крови. Наши солдаты едва держатся.$b$bПрисоединись к тем, кто защищает Пепельные поля или Расплавленный поток. Возможно, тебе удастся помочь им.','Убейте 5 огнедышащих гончих или древних огнедышащих гончих.','Вернитесь к генералу Талдрис Закат Луны на Аванпост Малфуриона, что на Огненной передовой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Псы войны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наши войска терпят поражение от необузданных чудовищ – огнедышащих гончих.$b$bЭти псы ничего не боятся и не остановятся, пока не утолят свою жажду крови. Наши солдаты едва держатся.$b$bПрисоединись к тем, кто защищает Пепельные поля или Расплавленный поток. Возможно, тебе удастся помочь им.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 5 огнедышащих гончих или древних огнедышащих гончих.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к генералу Талдрис Закат Луны на Аванпост Малфуриона, что на Огненной передовой.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29305,'Удар в сердце','Во Владениях Рагнароса – окруженных стенами землях к северо-востоку отсюда – показался один из его воинов пламени.$b$bЯ надеялась сразу же отправить тебя, но, боюсь, Суховет и наши солдаты уже начали бой. Тебе нужно торопиться.$b$bСпускайся по скалам прямо здесь и быстрее беги к ним.','Убейте воина пламени.','Прекрасно, Грозоветтер! Это должно надолго задержать их.$B$BЕсли мы будем продолжать в том же духе, то с легкостью доберемся до Рагнароса.','Вернитесь к повелителю небес Омнурону на Аванпост Малфуриона, что на Огненной передовой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Удар в сердце',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Во Владениях Рагнароса – окруженных стенами землях к северо-востоку отсюда – показался один из его воинов пламени.$b$bЯ надеялась сразу же отправить тебя, но, боюсь, Суховет и наши солдаты уже начали бой. Тебе нужно торопиться.$b$bСпускайся по скалам прямо здесь и быстрее беги к ним.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте воина пламени.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно, Грозоветтер! Это должно надолго задержать их.$B$BЕсли мы будем продолжать в том же духе, то с легкостью доберемся до Рагнароса.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к повелителю небес Омнурону на Аванпост Малфуриона, что на Огненной передовой.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29307,'Сердце пламени','Ты – $gпервый смертный, увидевший:первая смертная, увидевшая; драконий совет, $n, и $gзанимающий:занимающая; место среди тех, кто принимает участие в выборе Аспекта.$b$bМое положение наделило меня невероятной силой. Я принял решение укрепить связь между тобой и Таресгосой, даже несмотря на то, что правильнее было бы выбрать ей более... долговечное жилище.$b$bТебе придется в последний раз отправиться в царство огня и принести мне сердце Рагнароса.$b$bПри нашей следующей встрече я смогу достойно отблагодарить тебя за все, что ты $gсделал:сделала;.','Наполните рунический посох Нордрассила 250 тлеющими сущностями и добудьте сердце пламени.','Ты отлично справилась, Имсэ.$B$BПолучи же награду, достойную героя.','Чудесный день для проведения церемонии, не правда ли, Имсэ?','Поговорите с Халлегостой в Штормграде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сердце пламени',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты – $gпервый смертный, увидевший:первая смертная, увидевшая; драконий совет, $n, и $gзанимающий:занимающая; место среди тех, кто принимает участие в выборе Аспекта.$b$bМое положение наделило меня невероятной силой. Я принял решение укрепить связь между тобой и Таресгосой, даже несмотря на то, что правильнее было бы выбрать ей более... долговечное жилище.$b$bТебе придется в последний раз отправиться в царство огня и принести мне сердце Рагнароса.$b$bПри нашей следующей встрече я смогу достойно отблагодарить тебя за все, что ты $gсделал:сделала;.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Наполните рунический посох Нордрассила 250 тлеющими сущностями и добудьте сердце пламени.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты отлично справилась, Имсэ.$B$BПолучи же награду, достойную героя.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Чудесный день для проведения церемонии, не правда ли, Имсэ?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Халлегостой в Штормграде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29308,'Сердце пламени','Ты – $gпервый смертный, увидевший:первая смертная, увидевшая; драконий совет, $n, и $gзанимающий:занимающая; место среди тех, кто принимает участие в выборе Аспекта.$b$bМое положение наделило меня невероятной силой. Я принял решение укрепить связь между тобой и Таресгосой, даже несмотря на то, что правильнее было бы выбрать ей более... долговечное жилище.$b$bТебе придется в последний раз отправиться в царство огня и принести мне сердце Рагнароса.$b$bПри нашей следующей встрече я смогу достойно отблагодарить тебя за все, что ты $gсделал:сделала;.','Усильте рунический посох Нордрассила 250 тлеющими сущностями и добудьте сердце пламени.','Поговорите с Халлегосой в Оргриммаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сердце пламени',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты – $gпервый смертный, увидевший:первая смертная, увидевшая; драконий совет, $n, и $gзанимающий:занимающая; место среди тех, кто принимает участие в выборе Аспекта.$b$bМое положение наделило меня невероятной силой. Я принял решение укрепить связь между тобой и Таресгосой, даже несмотря на то, что правильнее было бы выбрать ей более... долговечное жилище.$b$bТебе придется в последний раз отправиться в царство огня и принести мне сердце Рагнароса.$b$bПри нашей следующей встрече я смогу достойно отблагодарить тебя за все, что ты $gсделал:сделала;.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Усильте рунический посох Нордрассила 250 тлеющими сущностями и добудьте сердце пламени.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Халлегосой в Оргриммаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29309,'Посох легенд','Это честь – познакомиться с тобой, |3-6($r).$b$bВсе существа Азерота, смертные и бессмертные, знают о твоих деяниях.$b$bКогда Калесгос появится здесь, я передам ему сердце Рагнароса. Пусть его сила укрепит твое оружие.$b$bЦеремония скоро начнется. Меня попросили сопровождать тебя, когда ты будешь $gготов:готова;.','Поговорите с Халлегосой.','Поговорите с Халлегосой в Оргриммаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Посох легенд',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это честь – познакомиться с тобой, |3-6($r).$b$bВсе существа Азерота, смертные и бессмертные, знают о твоих деяниях.$b$bКогда Калесгос появится здесь, я передам ему сердце Рагнароса. Пусть его сила укрепит твое оружие.$b$bЦеремония скоро начнется. Меня попросили сопровождать тебя, когда ты будешь $gготов:готова;.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Халлегосой.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Халлегосой в Оргриммаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29310,'Ключевой момент','В тот день, когда Лиара напала на Хамуула, она дожидалась его в руинах на Хиджале, которые находятся к северо-западу от Молодого леса. Она вела себя очень странно – молчаливо смотрела вдаль, уставившись на какую-то точку на горизонте. Видимо, для нее это место имело определенное значение.$b$bВозможно, медальон как-то отреагирует, если отнести его туда.','Отнесите покрытый гарью медальон к небольшому надгробию в Печаль Лиары на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ключевой момент',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В тот день, когда Лиара напала на Хамуула, она дожидалась его в руинах на Хиджале, которые находятся к северо-западу от Молодого леса. Она вела себя очень странно – молчаливо смотрела вдаль, уставившись на какую-то точку на горизонте. Видимо, для нее это место имело определенное значение.$b$bВозможно, медальон как-то отреагирует, если отнести его туда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите покрытый гарью медальон к небольшому надгробию в Печаль Лиары на горе Хиджал.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29312,'Посох легенд','Это честь – познакомиться с тобой, |3-6($r).$b$bВсе существа Азерота, смертные и бессмертные, знают о твоих деяниях.$b$bКогда Калесгос появится здесь, я передам ему сердце Рагнароса. Пусть его сила укрепит твое оружие.$b$bЦеремония скоро начнется. Меня попросили сопровождать тебя, когда ты будешь $gготов:готова;.','Поговорите с Халлегосой.','Твои героические деяния никогда не будут забыты, Имсэ.','Гнев Дракона, вечный покой Таресгосы.','Поговорите с Халлегосой в Штормграде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Посох легенд',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это честь – познакомиться с тобой, |3-6($r).$b$bВсе существа Азерота, смертные и бессмертные, знают о твоих деяниях.$b$bКогда Калесгос появится здесь, я передам ему сердце Рагнароса. Пусть его сила укрепит твое оружие.$b$bЦеремония скоро начнется. Меня попросили сопровождать тебя, когда ты будешь $gготов:готова;.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Халлегосой.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Твои героические деяния никогда не будут забыты, Имсэ.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Гнев Дракона, вечный покой Таресгосы.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Халлегосой в Штормграде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29313,'Секрет превосходного кимчи','Найдите в Дарнасе 8 закопанных кадок кимчи.','Спасибо, Спириткрашер. Сам бы я ни за что не собрал все кадки. Было бы обидно, если бы столько прекрасного кимчи пропало!','Вернитесь к Элегорну в Дарнас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Секрет превосходного кимчи',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите в Дарнасе 8 закопанных кадок кимчи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо, Спириткрашер. Сам бы я ни за что не собрал все кадки. Было бы обидно, если бы столько прекрасного кимчи пропало!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Элегорну в Дарнас.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29314,'Дань уважения предкам','Пища нужна не только живым. В мои обязанности входит приготовление рисовых пирогов, которые мы приносим в дар предкам. Обычно старшая ученица относит пироги в Храм Луны, где освящает их, и потом преподносит предкам. Сегодня ее нет в городе, поэтому не $gмог:могла; бы ты выполнить эту почетную обязанность вместо нее?','Заберите освященные рисовые пироги из Храма Луны.','<Вы раскладываете пироги вокруг алтаря, который начинает источать мягкий свет. Предки смотрят на вас с одобрением, и вы это чувствуете.>','Это то святилище, о котором говорил учитель.','Отнесите освященные рисовые пироги в святилище предков в Дарнасе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дань уважения предкам',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пища нужна не только живым. В мои обязанности входит приготовление рисовых пирогов, которые мы приносим в дар предкам. Обычно старшая ученица относит пироги в Храм Луны, где освящает их, и потом преподносит предкам. Сегодня ее нет в городе, поэтому не $gмог:могла; бы ты выполнить эту почетную обязанность вместо нее?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заберите освященные рисовые пироги из Храма Луны.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Вы раскладываете пироги вокруг алтаря, который начинает источать мягкий свет. Предки смотрят на вас с одобрением, и вы это чувствуете.>',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Это то святилище, о котором говорил учитель.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите освященные рисовые пироги в святилище предков в Дарнасе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29315,'Деликатесные грибы','Некоторые повара жалуются, что в нашем прекрасном Подгороде невозможно достать ингредиенты для особо изысканных блюд.$B$BЖалкие, презренные недоучки! Глаза разуйте – тут растут такие деликатесы, что пальчики оближешь.$B$BВот, например, канализационные грибы! Собери дюжину в Стоках на северо-западе и возвращайся ко мне.','Соберите 12 канализационных грибов. Отнесите их Эвнике Барч в Подгород.','Как же отвратительно они пахнут! Просто смак!','Ну как, набрал канализационных грибов?','Вернитесь к Эвнике Барч в Подгород.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Деликатесные грибы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Некоторые повара жалуются, что в нашем прекрасном Подгороде невозможно достать ингредиенты для особо изысканных блюд.$B$BЖалкие, презренные недоучки! Глаза разуйте – тут растут такие деликатесы, что пальчики оближешь.$B$BВот, например, канализационные грибы! Собери дюжину в Стоках на северо-западе и возвращайся ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 12 канализационных грибов. Отнесите их Эвнике Барч в Подгород.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Как же отвратительно они пахнут! Просто смак!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как, набрал канализационных грибов?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Эвнике Барч в Подгород.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29316,'Азы профессии','Некоторые ингредиенты нужны всем – и простым кухаркам, и шеф-поварам. Один из наиболее важных продуктов в городе – рисовая мука. В каждой семье найдется как минимум одна корзинка риса, в том числе у обитателей Террасы Ремесленников и Террасы Торговцев.$B$BЯ иногда поручаю своим ученикам смолоть рис в муку – во-первых, это отличная практика, а во-вторых, муки никогда не бывает много. Не $gмог:могла; бы ты помочь нам с этим делом?','Помогите обитателям Террасы Ремесленников и Террасы Торговцев смолоть содержимое корзинок в рисовую муку.','Нам приходится много работать, чтобы обеспечивать всех рисовой мукой. Спасибо за помощь, Спириткрашер.','Вернитесь к Элегорну в Дарнас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Азы профессии',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Некоторые ингредиенты нужны всем – и простым кухаркам, и шеф-поварам. Один из наиболее важных продуктов в городе – рисовая мука. В каждой семье найдется как минимум одна корзинка риса, в том числе у обитателей Террасы Ремесленников и Террасы Торговцев.$B$BЯ иногда поручаю своим ученикам смолоть рис в муку – во-первых, это отличная практика, а во-вторых, муки никогда не бывает много. Не $gмог:могла; бы ты помочь нам с этим делом?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Помогите обитателям Террасы Ремесленников и Террасы Торговцев смолоть содержимое корзинок в рисовую муку.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Нам приходится много работать, чтобы обеспечивать всех рисовой мукой. Спасибо за помощь, Спириткрашер.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Элегорну в Дарнас.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (29317,'Выловить голову','Принесите отрубленную голову опытному аптекарю Фаранеллу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Выловить голову',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите отрубленную голову опытному аптекарю Фаранеллу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (29317,'Вот она! Как вам удалось ее найти?$B$BВпрочем, неважно. Мои ученики часами плескались в слизи, а толку никакого. Но зато они нашли целый мешок всяких блестящих штучек… может быть, вам они пригодятся?$B$BСпасибо!','Вы случаем не находили отрубленную голову поганища?..') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот она! Как вам удалось ее найти?$B$BВпрочем, неважно. Мои ученики часами плескались в слизи, а толку никакого. Но зато они нашли целый мешок всяких блестящих штучек… может быть, вам они пригодятся?$B$BСпасибо!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы случаем не находили отрубленную голову поганища?..',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29318,'Ребрышки для часовых','Мой долг – снабжать провизией часовых Дарнаса, пока они несут службу. Это нелегкая задача, но я не жалуюсь – в конце концов, где еще удастся так попрактиковаться в приготовлении пищи. Не хочешь помочь мне с сегодняшним обедом? Ничего сложного: надо просто поджарить вот эти ребрышки на огне и раздать часовым в городе.','Приготовьте сырые ребрышки в печи или на огне, а затем накормите ими 5 дарнасских часовых.','С твоей помощью нам было намного проще накормить всех часовых. Им не пришлось простаивать в очереди за пайком.','Вернитесь к Элегорну в Дарнас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ребрышки для часовых',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мой долг – снабжать провизией часовых Дарнаса, пока они несут службу. Это нелегкая задача, но я не жалуюсь – в конце концов, где еще удастся так попрактиковаться в приготовлении пищи. Не хочешь помочь мне с сегодняшним обедом? Ничего сложного: надо просто поджарить вот эти ребрышки на огне и раздать часовым в городе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Приготовьте сырые ребрышки в печи или на огне, а затем накормите ими 5 дарнасских часовых.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','С твоей помощью нам было намного проще накормить всех часовых. Им не пришлось простаивать в очереди за пайком.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Элегорну в Дарнас.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29320,'Любишь щуку?','Ты же уже $gрыбачил:рыбачила; на озере Ясноводном?$B$BВ нем можно выловить гигантскую щуку-трупоеда. Вот только для этого нужна особая наживка... трупный червь.$B$BПокопайся в могилах во внутреннем дворе. Думаю, там их немало.','Накопайте трупных червей во внутреннем дворе Руин Лордерона и используйте их как наживку для щуки-трупоеда, которую можно выловить в озере Ясноводном к северо-востоку от Подгорода.','Когда пойдешь на рыбалку?','Отнесите щуку Арману Кромвелю в Подгород.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Любишь щуку?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты же уже $gрыбачил:рыбачила; на озере Ясноводном?$B$BВ нем можно выловить гигантскую щуку-трупоеда. Вот только для этого нужна особая наживка... трупный червь.$B$BПокопайся в могилах во внутреннем дворе. Думаю, там их немало.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Накопайте трупных червей во внутреннем дворе Руин Лордерона и используйте их как наживку для щуки-трупоеда, которую можно выловить в озере Ясноводном к северо-востоку от Подгорода.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Когда пойдешь на рыбалку?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите щуку Арману Кромвелю в Подгород.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29321,'Накопать моллюсков','Все мои знакомые обожают моллюсков, но я их на дух не переношу! Ведь они такие вонючие и склизкие, да еще и приходится выкапывать их из жижи. Нет уж, я лучше порыбачу с удочкой.$B$BВот только мне бы хотелось порадовать брата ведром свежих моллюсков. Я бы щедро оплатила твои услуги, если бы ты $gсогласился:согласилась; собрать их для меня.$B$BОтправляйся в деревню Рут\'теран через портал и набери моллюсков на прибрежном мелководье.','Соберите 10 моллюсков Тельдрассила на берегу вблизи деревни Рут\'терран.','Фу, эти моллюски такие отвратительные на вид, но моему брату они точно понравятся. Спасибо, что избавил меня от грязной работы!','Набрал моллюсков?','Вернитесь к Астайе в Дарнас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Накопать моллюсков',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Все мои знакомые обожают моллюсков, но я их на дух не переношу! Ведь они такие вонючие и склизкие, да еще и приходится выкапывать их из жижи. Нет уж, я лучше порыбачу с удочкой.$B$BВот только мне бы хотелось порадовать брата ведром свежих моллюсков. Я бы щедро оплатила твои услуги, если бы ты $gсогласился:согласилась; собрать их для меня.$B$BОтправляйся в деревню Рут\'теран через портал и набери моллюсков на прибрежном мелководье.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 моллюсков Тельдрассила на берегу вблизи деревни Рут\'терран.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Фу, эти моллюски такие отвратительные на вид, но моему брату они точно понравятся. Спасибо, что избавил меня от грязной работы!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Набрал моллюсков?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Астайе в Дарнас.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29322,'Пора слизней','Не всякому рыбаку дано оценить прелесть улова из желобов с бурлящей слизью в Подгороде, но, думаю, тебе по силам наловить извивающихся плесневых слизней. Что скажешь?$B$BМожешь попробовать поймать их на крючок, но учти, они очень изворотливые. Будет лучше, если ты просто нырнешь в слизь и выловишь их руками.$B$BИ не забудь, что они нужны целыми и невредимыми... Никто же не станет есть дохлого слизня! Это была бы такая гадость!','Выловите 10 извивающихся плесневых слизней и отнесите их Арману Кромвелю в Подгород.','Слизни в прекрасном состоянии. Я сейчас же отправлю их Эвнике – пусть начинает готовить. Спасибо!','Непросто их выловить, правда?','Вернитесь к Арману Кромвелю в Подгород.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пора слизней',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не всякому рыбаку дано оценить прелесть улова из желобов с бурлящей слизью в Подгороде, но, думаю, тебе по силам наловить извивающихся плесневых слизней. Что скажешь?$B$BМожешь попробовать поймать их на крючок, но учти, они очень изворотливые. Будет лучше, если ты просто нырнешь в слизь и выловишь их руками.$B$BИ не забудь, что они нужны целыми и невредимыми... Никто же не станет есть дохлого слизня! Это была бы такая гадость!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выловите 10 извивающихся плесневых слизней и отнесите их Арману Кромвелю в Подгород.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Слизни в прекрасном состоянии. Я сейчас же отправлю их Эвнике – пусть начинает готовить. Спасибо!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Непросто их выловить, правда?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Арману Кромвелю в Подгород.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29323,'Запасаемся','Мы израсходовали почти все запасы, пока кормили беженцев и потерявших свой кров. Если сейчас не пополнить запасы, то мы окажемся в опасном положении, если пройдет ураган или случится нападение Орды.$B$BТы $gмог:могла; бы помочь мне наловить озерного сига. Он встречается повсеместно в Дарнасе. В засушенном виде его можно хранить бесконечно долго.','Выудите 5 озерных сигов в Дарнасе.','Прекрасная рыба! Спасибо, Тайнатеней. Я сейчас же отправлю ее сушиться.','Если подключить к работе всех рыбаков, то пополнение запасов не займет много времени.','Вернитесь к Астайе в Дарнас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Запасаемся',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы израсходовали почти все запасы, пока кормили беженцев и потерявших свой кров. Если сейчас не пополнить запасы, то мы окажемся в опасном положении, если пройдет ураган или случится нападение Орды.$B$BТы $gмог:могла; бы помочь мне наловить озерного сига. Он встречается повсеместно в Дарнасе. В засушенном виде его можно хранить бесконечно долго.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выудите 5 озерных сигов в Дарнасе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасная рыба! Спасибо, Тайнатеней. Я сейчас же отправлю ее сушиться.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если подключить к работе всех рыбаков, то пополнение запасов не займет много времени.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Астайе в Дарнас.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29324,'Подвеска сестры','Найдите подвеску Аквинны в форме полумесяца внутри гигантской зубатки. Эту рыбу можно выловить повсеместно в Дарнасе.','Тебе удалось отыскать потерянную подвеску Аквинны? Я выловила не меньше пятидесяти таких рыбин, но так ничего и не нашла.','Вернитесь к Астайе в Дарнас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подвеска сестры',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите подвеску Аквинны в форме полумесяца внутри гигантской зубатки. Эту рыбу можно выловить повсеместно в Дарнасе.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось отыскать потерянную подвеску Аквинны? Я выловила не меньше пятидесяти таких рыбин, но так ничего и не нашла.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Астайе в Дарнас.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29325,'Скользкая закуска','Тебе когда-нибудь доводилось есть мясо осьминога? У него несколько специфический вкус, но я его просто обожаю! А некоторые мои знакомые любят есть осьминога заживо!$B$BЯ сама пока не готова к подобным экспериментам, а вот от свежего мяса не отказалась бы. У меня оно как раз подошло к концу. Не поможешь мне наловить осьминогов? Они водятся на мелководье вблизи деревни Рут\'теран.','Наберите 6 осьминожков на мелководье вблизи деревни Рут\'теран.','Осьминогов не поймать на удочку, так что придется собирать их вручную!','Вернитесь к Астайе в Дарнас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Скользкая закуска',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе когда-нибудь доводилось есть мясо осьминога? У него несколько специфический вкус, но я его просто обожаю! А некоторые мои знакомые любят есть осьминога заживо!$B$BЯ сама пока не готова к подобным экспериментам, а вот от свежего мяса не отказалась бы. У меня оно как раз подошло к концу. Не поможешь мне наловить осьминогов? Они водятся на мелководье вблизи деревни Рут\'теран.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Наберите 6 осьминожков на мелководье вблизи деревни Рут\'теран.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Осьминогов не поймать на удочку, так что придется собирать их вручную!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Астайе в Дарнас.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29326,'Встреча у Нордрассила','Приветствую тебя, |3-6($c). Наши собратья из Служителей Земли очень хорошо отзывались обо всем, что ты $gсделал:сделала; после того, как произошел Катаклизм. Но нам еще очень многое предстоит сделать, если мы хотим, чтобы этот мир оправился от полученных ран.$b$b$gПойдем со мной, друг:Пойдем со мной;. Приготовления к церемонии уже начаты. Я надеюсь, что ритуал, который мы совершим, станет поворотным событием в нашей битве с Сумеречным Молотом.$b$bКогда все будет закончено, ты сможешь всем рассказать о нашей победе.','Поговорите с Траллом под Древом Жизни на горе Хиджал и поприсутствуйте на церемонии Служителей Земли.','Это не конец. Мы не должны терять надежду!','Поговорите с Аггрой под Древом Жизни на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Встреча у Нордрассила',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приветствую тебя, |3-6($c). Наши собратья из Служителей Земли очень хорошо отзывались обо всем, что ты $gсделал:сделала; после того, как произошел Катаклизм. Но нам еще очень многое предстоит сделать, если мы хотим, чтобы этот мир оправился от полученных ран.$b$b$gПойдем со мной, друг:Пойдем со мной;. Приготовления к церемонии уже начаты. Я надеюсь, что ритуал, который мы совершим, станет поворотным событием в нашей битве с Сумеречным Молотом.$b$bКогда все будет закончено, ты сможешь всем рассказать о нашей победе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Траллом под Древом Жизни на горе Хиджал и поприсутствуйте на церемонии Служителей Земли.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это не конец. Мы не должны терять надежду!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Аггрой под Древом Жизни на горе Хиджал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29327,'Власть стихий: сомнение','Я знаю, кого ты ищешь. Но я не уверен, стоит ли тебе преследовать его. Он принял облик вихря. Ветра разрывают на части его тело, превращая его в ошметки плоти, и его разум, оставляя в нем лишь сомнения.$b$bЕсли ты будешь преследовать его, то тебя может постичь та же судьба. Сильный ветер режет не хуже острого ножа.$b$bЯ предупредил тебя. Что же ты будешь делать?','Поговорите с Циклонасом, чтобы пройти к Траллу. Убивайте духов ветра, которые мучают его, до тех пор, пока он не будет освобожден.','Что это за вода?..','Поговорите с Аггрой в Ульдуме.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Власть стихий: сомнение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я знаю, кого ты ищешь. Но я не уверен, стоит ли тебе преследовать его. Он принял облик вихря. Ветра разрывают на части его тело, превращая его в ошметки плоти, и его разум, оставляя в нем лишь сомнения.$b$bЕсли ты будешь преследовать его, то тебя может постичь та же судьба. Сильный ветер режет не хуже острого ножа.$b$bЯ предупредил тебя. Что же ты будешь делать?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Циклонасом, чтобы пройти к Траллу. Убивайте духов ветра, которые мучают его, до тех пор, пока он не будет освобожден.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что это за вода?..',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Аггрой в Ульдуме.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29328,'Власть стихий: желание','Снова повторю, |3-6($c), я не смогу сделать этого без твоей помощи. Я постараюсь унять эту бурю, но тебе придется сражаться с элементалями, которые кружат вокруг нее. Только так мы сможем освободить Го\'эла.','Убивайте волны стремлений и вихри желаний у Обрыва над бездной, пока Тралл не освободится.','Воздух, вода… теперь земля?','Вернитесь к Аггре к Обрыву над бездной, что в Бездонных глубинах в Вайш\'ире.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Власть стихий: желание',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Снова повторю, |3-6($c), я не смогу сделать этого без твоей помощи. Я постараюсь унять эту бурю, но тебе придется сражаться с элементалями, которые кружат вокруг нее. Только так мы сможем освободить Го\'эла.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убивайте волны стремлений и вихри желаний у Обрыва над бездной, пока Тралл не освободится.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Воздух, вода… теперь земля?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аггре к Обрыву над бездной, что в Бездонных глубинах в Вайш\'ире.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29329,'Власть стихий: терпение','С благословением Матери-Скалы я смогу перенести нас туда, где находится Го\'эл.$b$bНо нужно действовать осторожно. Шпионы Сумеречного Молота повсюду. Помоги удержать их, пока я доберусь до Го\'эла!$b$bСообщи мне, когда будешь $gготов:готова;, и я проведу тебя к нему.','Сообщите Аггре, когда будете готовы отправиться на помощь Траллу. Затем уничтожьте стихии терпения и краеугольные камни терпения, удерживающие пленника.','<Аггра сжимает кулаки и смотрит на то место, где еще минуту назад стоял Тралл.>','Поговорите с Аггрой на Незыблемом утесе в Подземье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Власть стихий: терпение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','С благословением Матери-Скалы я смогу перенести нас туда, где находится Го\'эл.$b$bНо нужно действовать осторожно. Шпионы Сумеречного Молота повсюду. Помоги удержать их, пока я доберусь до Го\'эла!$b$bСообщи мне, когда будешь $gготов:готова;, и я проведу тебя к нему.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сообщите Аггре, когда будете готовы отправиться на помощь Траллу. Затем уничтожьте стихии терпения и краеугольные камни терпения, удерживающие пленника.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Аггра сжимает кулаки и смотрит на то место, где еще минуту назад стоял Тралл.>',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Аггрой на Незыблемом утесе в Подземье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29330,'Власть стихий: ярость','Тотемы, $n! Нужно активировать их, иначе Го\'элу конец!$b$bУбивай элементалей рядом с каждым тотемом, которые расставлены по краям этого плато. Когда все четыре тотема будут активированы, у нас должно получиться освободить последнюю частицу души Го\'эла.','Убивайте элементалей возле воздушного тотема Аггры, расположенного в западной части плато, до тех пор, пока он не активируется. Затем проделайте то же самое с водным, земным и огненным тотемами Аггры.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Власть стихий: ярость',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тотемы, $n! Нужно активировать их, иначе Го\'элу конец!$b$bУбивай элементалей рядом с каждым тотемом, которые расставлены по краям этого плато. Когда все четыре тотема будут активированы, у нас должно получиться освободить последнюю частицу души Го\'эла.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убивайте элементалей возле воздушного тотема Аггры, расположенного в западной части плато, до тех пор, пока он не активируется. Затем проделайте то же самое с водным, земным и огненным тотемами Аггры.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (29331,'Власть стихий: обет','Перед тем, как пройти через портал, ведущий на гору Хиджал, Тралл попросил вас следовать за ним. Он хочет, чтобы вы кое-что увидели.','Поговорите с Траллом в Нордрассиле на горе Хиджал.','Благодаря тебе, друг мой, я снова жив! А благодаря объединенным усилиям Круга Кенария и Служителей Земли Древо Жизни поможет восстановить Азерот.$B$BНам еще предстоит расквитаться со Смертокрылом и другими врагами. Я хочу кое-что показать тебе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Власть стихий: обет',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Перед тем, как пройти через портал, ведущий на гору Хиджал, Тралл попросил вас следовать за ним. Он хочет, чтобы вы кое-что увидели.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Траллом в Нордрассиле на горе Хиджал.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Благодаря тебе, друг мой, я снова жив! А благодаря объединенным усилиям Круга Кенария и Служителей Земли Древо Жизни поможет восстановить Азерот.$B$BНам еще предстоит расквитаться со Смертокрылом и другими врагами. Я хочу кое-что показать тебе.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29332,'Вот так лилии!','Какой роскошный букет. Великолепно! Сейчас же начну их отваривать.','Ты собрал достаточно лилий?','Вернитесь к Эвнике Барч в Подгород.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вот так лилии!',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Какой роскошный букет. Великолепно! Сейчас же начну их отваривать.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты собрал достаточно лилий?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Эвнике Барч в Подгород.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29333,'Улитки прытки','Орки-охранники постоянно жалуются на паек, который им выдают в Подгороде. Будто это наша вина, что им не по нраву грибы и гнилые трупы. Думаю, нужно им доказать, что при случае мы умеем готовить деликатесы даже по их вкусу.$B$BСобери-ка для меня немного пресноводных улиток, которые обитают на озере Ясноводном, и я покажу этим оркам, что значит настоящий кулинарный шедевр.','Соберите 8 пресноводных улиток и отнесите их Эвнике Барч в Подгород.','Да ты настоящий пловец! Я сама плаваю, как топор.$B$BВ общем, спасибо за отменных улиток.','Ты уже набрал улиток?','Вернитесь к Эвнике Барч в Подгород.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Улитки прытки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Орки-охранники постоянно жалуются на паек, который им выдают в Подгороде. Будто это наша вина, что им не по нраву грибы и гнилые трупы. Думаю, нужно им доказать, что при случае мы умеем готовить деликатесы даже по их вкусу.$B$BСобери-ка для меня немного пресноводных улиток, которые обитают на озере Ясноводном, и я покажу этим оркам, что значит настоящий кулинарный шедевр.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 пресноводных улиток и отнесите их Эвнике Барч в Подгород.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да ты настоящий пловец! Я сама плаваю, как топор.$B$BВ общем, спасибо за отменных улиток.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты уже набрал улиток?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Эвнике Барч в Подгород.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29334,'Всем тараканам тараканы','Несмотря на бесконечные жалобы кор\'кронских надзирателей на пищу в Подгороде, есть один деликатес, который они готовы пожирать тоннами. Я говорю о пряной похлебке из тараканов, которую делает моя сестра Одри.$B$BЕй постоянно не хватает ингредиентов для приготовления этого блюда. Не хочешь помочь ей со сбором тараканов?$B$BЛовушки для насекомых разбросаны по всему городу. Просто проверь их и отнести содержимое Одри. А дальше уж она сама управится!','Соберите 20 жирных тараканов и отнесите их шеф-повару Одри в Подгород.','Как раз вовремя, а то мои запасы подошли к концу. Спасибо!','Я называю эти ловушки "домиками для тараканов".$B$BОни залезают внутрь, а вот вылезти уже не могут.','Вернитесь к шеф-повару Одри в Подгород.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Всем тараканам тараканы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Несмотря на бесконечные жалобы кор\'кронских надзирателей на пищу в Подгороде, есть один деликатес, который они готовы пожирать тоннами. Я говорю о пряной похлебке из тараканов, которую делает моя сестра Одри.$B$BЕй постоянно не хватает ингредиентов для приготовления этого блюда. Не хочешь помочь ей со сбором тараканов?$B$BЛовушки для насекомых разбросаны по всему городу. Просто проверь их и отнести содержимое Одри. А дальше уж она сама управится!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 20 жирных тараканов и отнесите их шеф-повару Одри в Подгород.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Как раз вовремя, а то мои запасы подошли к концу. Спасибо!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я называю эти ловушки "домиками для тараканов".$B$BОни залезают внутрь, а вот вылезти уже не могут.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к шеф-повару Одри в Подгород.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (29335,'Стремительные ветра','$c, я отказываюсь думать, что мой дорогой Го\'эл навсегда для меня потерян. Частицы его души разбросаны по разным царствам стихий, но если хотя бы одна частица еще существует, мы можем найти его. Мне понадобится твоя помощь.$b$bПоговори со мной, когда будешь $gготов:готова; отправиться на Вершину Смерча. Мы должны будем поговорить с элементалем по имени Циклонас. У него капризный характер, но он видит все в царстве воздуха. Если мой возлюбленный там, Циклонас узнает, что с ним стало.','Поговорите с Циклонасом на Утесе Южного Ветра в Ульдуме.','<Вы чувствуете, как ветер обдувает ваши руки, лицо, оружие и доспехи...>$B$B<Циклонас смотрит на вас.>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Стремительные ветра',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$c, я отказываюсь думать, что мой дорогой Го\'эл навсегда для меня потерян. Частицы его души разбросаны по разным царствам стихий, но если хотя бы одна частица еще существует, мы можем найти его. Мне понадобится твоя помощь.$b$bПоговори со мной, когда будешь $gготов:готова; отправиться на Вершину Смерча. Мы должны будем поговорить с элементалем по имени Циклонас. У него капризный характер, но он видит все в царстве воздуха. Если мой возлюбленный там, Циклонас узнает, что с ним стало.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Циклонасом на Утесе Южного Ветра в Ульдуме.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Вы чувствуете, как ветер обдувает ваши руки, лицо, оружие и доспехи...>$B$B<Циклонас смотрит на вас.>',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29336,'В глубины вод','Го\'эл должен быть в царстве воды... в самой Бездонной пучине! Дрожь пробирает меня при одной мысли о том, что ждет его там.$b$bРазыщи возле Обрыва над бездной элементаля Гидриаса. Он знает Го\'эла и разделяет наши взгляды относительно Рагнароса. Если кто-то и сможет помочь тебе там, то это он.$b$bВстретимся в Вайш\'ире, |3-6($r)...','Поговорите с Гидриасом у Обрыва над бездной, что в Бездонных глубинах в Вайш\'ире.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В глубины вод',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Го\'эл должен быть в царстве воды... в самой Бездонной пучине! Дрожь пробирает меня при одной мысли о том, что ждет его там.$b$bРазыщи возле Обрыва над бездной элементаля Гидриаса. Он знает Го\'эла и разделяет наши взгляды относительно Рагнароса. Если кто-то и сможет помочь тебе там, то это он.$b$bВстретимся в Вайш\'ире, |3-6($r)...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Гидриасом у Обрыва над бездной, что в Бездонных глубинах в Вайш\'ире.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (29337,'В толщу земли','Времени мало! Мой возлюбленный в Подземье. Когда ты будешь $gготов:готова;, я смогу перенести нас туда, и мы поговорим с Теразан Матерью-Скалой.','Я знаю, что вы ищете, смертные. Я решила помочь вам.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В толщу земли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Времени мало! Мой возлюбленный в Подземье. Когда ты будешь $gготов:готова;, я смогу перенести нас туда, и мы поговорим с Теразан Матерью-Скалой.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я знаю, что вы ищете, смертные. Я решила помочь вам.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29338,'Жестокий огонь','Теперь мы должны отправиться в Огненные Просторы. В этом царстве огня Го\'эл с его пламенной душой может стать таким же опасным, как и Рагнарос.$b$bПоговори со мной, когда будешь $gготов:готова;... и пусть нас защитят предки!','Поговорите с Аггрой на Незыблемом утесе в Подземье, чтобы попасть в Огненные Просторы.','Поговорите с Аггрой во Владениях Рагнароса, что в Расплавленном потоке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жестокий огонь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь мы должны отправиться в Огненные Просторы. В этом царстве огня Го\'эл с его пламенной душой может стать таким же опасным, как и Рагнарос.$b$bПоговори со мной, когда будешь $gготов:готова;... и пусть нас защитят предки!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Аггрой на Незыблемом утесе в Подземье, чтобы попасть в Огненные Просторы.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Аггрой во Владениях Рагнароса, что в Расплавленном потоке.',`completedtext_loc8`);
