INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29342,'Зимняя рыбалка','Самая вкусная рыба водится в холодных водах Дун Морога, $n. С этим никто не поспорит! Арктический голец пользуется у жителей Стальгорна особенной популярностью. Я и сам его обожаю.$B$BДумаю, это дар Стальгорна всему миру!$B$BНе хочешь $gсам:сама; наловить гольца? Он облюбовал озеро Хельмово Ложе в восточной части Дун Морога.','Поймайте 5 арктических гольцов в озере Хельмово Ложе, что в Дун Мороге.','Вернитесь к Мрачнуру Каменному Клейму в Заброшенный грот, что в Стальгорне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зимняя рыбалка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Самая вкусная рыба водится в холодных водах Дун Морога, $n. С этим никто не поспорит! Арктический голец пользуется у жителей Стальгорна особенной популярностью. Я и сам его обожаю.$B$BДумаю, это дар Стальгорна всему миру!$B$BНе хочешь $gсам:сама; наловить гольца? Он облюбовал озеро Хельмово Ложе в восточной части Дун Морога.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поймайте 5 арктических гольцов в озере Хельмово Ложе, что в Дун Мороге.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мрачнуру Каменному Клейму в Заброшенный грот, что в Стальгорне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29343,'Легендарная рыба','Думаю, тебе доводилось слышать легенду о старом сталезубе – самой известной и неуловимой рыбе, обитающей в Заброшенном гроте Стальгорна. Долгие годы эта рыбина плодила молодых сталезубов. Только не обольщайся, $n, несмотря на свое название, они так же хитры, как и их прародитель.$B$BДумаю, при достаточном терпении ты $gмог:могла; бы выловить молодого сталезуба. Когда поймаешь рыбу, принеси ее в музей при Библиотеке Стальгорна для всеобщего обозрения.','Поймайте молодого сталезуба в Заброшенном гроте Стальгорна и выставьте его на обозрение над пустой табличкой в Библиотеке.','Вернитесь к Мрачнуру Каменному Клейму в Заброшенный грот, что в Стальгорне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Легендарная рыба',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Думаю, тебе доводилось слышать легенду о старом сталезубе – самой известной и неуловимой рыбе, обитающей в Заброшенном гроте Стальгорна. Долгие годы эта рыбина плодила молодых сталезубов. Только не обольщайся, $n, несмотря на свое название, они так же хитры, как и их прародитель.$B$BДумаю, при достаточном терпении ты $gмог:могла; бы выловить молодого сталезуба. Когда поймаешь рыбу, принеси ее в музей при Библиотеке Стальгорна для всеобщего обозрения.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поймайте молодого сталезуба в Заброшенном гроте Стальгорна и выставьте его на обозрение над пустой табличкой в Библиотеке.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мрачнуру Каменному Клейму в Заброшенный грот, что в Стальгорне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29344,'Рыба для Трескунчика','Поймайте 3 слепые ледоспинки в Заброшенном гроте и накормите ими Трескунчика.','Вернитесь к Мрачнуру Каменному Клейму в Заброшенный грот Стальгорна.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рыба для Трескунчика',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поймайте 3 слепые ледоспинки в Заброшенном гроте и накормите ими Трескунчика.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мрачнуру Каменному Клейму в Заброшенный грот Стальгорна.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29345,'Хищники в пруду','Один преисполненный самых лучших намерений гоблин запустил в наш пруд азшарских змееголовов, и теперь водоем просто кишит ими.$b$bЕсли тебе удастся уменьшить численность этих прожорливых тварей до того, как они уничтожат всех илистых луцианов и блестящих рыбок в Громовом Утесе, я буду тебе очень признателен.','Ках Вестник Туманов из Громового Утеса просит вас выловить 8 азшарских змееголовов из пруда Громового Утеса.','Удалось поймать хоть сколько-нибудь азшарских змееголовов?','Отнесите рыбу Каху Вестнику Туманов в Громовой Утес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хищники в пруду',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Один преисполненный самых лучших намерений гоблин запустил в наш пруд азшарских змееголовов, и теперь водоем просто кишит ими.$b$bЕсли тебе удастся уменьшить численность этих прожорливых тварей до того, как они уничтожат всех илистых луцианов и блестящих рыбок в Громовом Утесе, я буду тебе очень признателен.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Ках Вестник Туманов из Громового Утеса просит вас выловить 8 азшарских змееголовов из пруда Громового Утеса.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось поймать хоть сколько-нибудь азшарских змееголовов?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите рыбу Каху Вестнику Туманов в Громовой Утес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29346,'Дело в кольце','Ко мне приходил один из Отрекшихся с Прудов Видений и что-то говорил про кольцо, которое он уронил в воду, а его затем проглотила слепоглазка.$b$bИли он имел в виду свой палец? Трудно сказать точно – его челюсть еле двигалась, а на орочьем он говорит не лучше меня.$b$bТак или иначе, я думаю, нам стоит попытаться поймать эту слепоглазку, выпотрошить ее и найти то ли его палец, то ли кольцо.$b$bТы не поможешь?','Отправляйтесь на рыбалку на Пруды Видений в Громовом Утесе. Когда поймаете слепоглазку, выпотрошите ее и поищите внутри кольцо.','Не попадалось ли тебе кольцо? Наверняка его проглотила одна из слепоглазок...','Отнесите Пошкену Гравировщику в Громовой Утес его кольцо.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дело в кольце',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ко мне приходил один из Отрекшихся с Прудов Видений и что-то говорил про кольцо, которое он уронил в воду, а его затем проглотила слепоглазка.$b$bИли он имел в виду свой палец? Трудно сказать точно – его челюсть еле двигалась, а на орочьем он говорит не лучше меня.$b$bТак или иначе, я думаю, нам стоит попытаться поймать эту слепоглазку, выпотрошить ее и найти то ли его палец, то ли кольцо.$b$bТы не поможешь?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь на рыбалку на Пруды Видений в Громовом Утесе. Когда поймаете слепоглазку, выпотрошите ее и поищите внутри кольцо.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Не попадалось ли тебе кольцо? Наверняка его проглотила одна из слепоглазок...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите Пошкену Гравировщику в Громовой Утес его кольцо.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29347,'На живца','Если тебе приходилось когда-нибудь ловить раков, ты $gдолжен:должна; знать, что охотнее всего они клюют на живую приманку. И чем этой приманки больше, тем лучше. Не хочешь испытать мою новую наживку? Просто намажься вот этим и прыгай в озеро Хельмово Ложе, что в восточной части Дун Морога.$b$bНаловишь раков – отнеси их моему приятелю, повару Гильму в карьер Гол\'Болар, что к западу от озера. Он эксперт по приготовлению этих членистоногих!','Намажьтесь наживкой Мрачнура, а затем прыгайте в озеро Хельмово Ложе, что в Дун Мороге.','Отнесите раков повару Гильму в карьер Гол\'Болар, что в Дун Мороге.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На живца',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если тебе приходилось когда-нибудь ловить раков, ты $gдолжен:должна; знать, что охотнее всего они клюют на живую приманку. И чем этой приманки больше, тем лучше. Не хочешь испытать мою новую наживку? Просто намажься вот этим и прыгай в озеро Хельмово Ложе, что в восточной части Дун Морога.$b$bНаловишь раков – отнеси их моему приятелю, повару Гильму в карьер Гол\'Болар, что к западу от озера. Он эксперт по приготовлению этих членистоногих!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Намажьтесь наживкой Мрачнура, а затем прыгайте в озеро Хельмово Ложе, что в Дун Мороге.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите раков повару Гильму в карьер Гол\'Болар, что в Дун Мороге.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29348,'Заселить водоем','В пруду Громового Утеса кишмя кишат азшарские змееголовы и они сожрали уже почти всех блестящих рыбок и илистых луцианов.$b$bНаши рыбаки уже вовсю ловят змееголовов, чтобы уменьшить их численность, а ты можешь помочь заселить пруды новыми рыбами.$b$bВылови немного рыбы из озера Каменного Быка. Я буду очень признателен тебе за это.','Поймайте в озере Каменного Быка 2 страстные блестящие рыбки и 2 любвеобильных илистых луцианов и отнесите их Каху Вестнику Туманов.','Вернитесь к Каху Вестнику Туманов в Громовой Утес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Заселить водоем',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В пруду Громового Утеса кишмя кишат азшарские змееголовы и они сожрали уже почти всех блестящих рыбок и илистых луцианов.$b$bНаши рыбаки уже вовсю ловят змееголовов, чтобы уменьшить их численность, а ты можешь помочь заселить пруды новыми рыбами.$b$bВылови немного рыбы из озера Каменного Быка. Я буду очень признателен тебе за это.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поймайте в озере Каменного Быка 2 страстные блестящие рыбки и 2 любвеобильных илистых луцианов и отнесите их Каху Вестнику Туманов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Каху Вестнику Туманов в Громовой Утес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29349,'Деликатесные раки','Один из главных деликатесов Мулгора – раки, которые живут в местных озерах и ручьях. Особенно большой популярностью блюда из этих раков пользуются на свадьбах и на праздниках в честь рождения детей.$b$bНе наловишь ли ты раков для поваров Громового Утеса?$b$bМожно выловить их на удочку из озера Каменного Быка, а можно просто нырнуть и собрать раков со дна.','Ках Вестник Туманов из Громового Утеса просит вас поймать 10 раков из озера Каменного Быка в Мулгоре.','Раки очень вкусны. Много поймал?','Отнесите раков Каху Вестнику Туманов в Громовой Утес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Деликатесные раки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Один из главных деликатесов Мулгора – раки, которые живут в местных озерах и ручьях. Особенно большой популярностью блюда из этих раков пользуются на свадьбах и на праздниках в честь рождения детей.$b$bНе наловишь ли ты раков для поваров Громового Утеса?$b$bМожно выловить их на удочку из озера Каменного Быка, а можно просто нырнуть и собрать раков со дна.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Ках Вестник Туманов из Громового Утеса просит вас поймать 10 раков из озера Каменного Быка в Мулгоре.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Раки очень вкусны. Много поймал?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите раков Каху Вестнику Туманов в Громовой Утес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29350,'Гномский блесн-о-матик','Один из гномских учителей инженерного дела дал мне чертеж отличного устройства, которое поможет мне быстрее ловить рыбу и не давать ей сорваться с крючка. Выглядит оно немного странно, но попробовать хотя бы раз стоит.$b$bДержи, вот чертежи. Тебе понадобятся блесны, их можно купить у моего ассистента внутри здания. Взрыватель можно приобрести у торговца товарами для инженеров в Городе Механиков. А крысоловки можно найти в Подземном поезде.','Возьмите 5 блесен, взрыватель и 3 крысоловки и с помощью чертежей соберите гномский блесн-о-матик.','Ну как там эта новая блесна?','Вернитесь к Мрачнуру Каменному Клейму в Заброшенный грот Стальгорна.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гномский блесн-о-матик',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Один из гномских учителей инженерного дела дал мне чертеж отличного устройства, которое поможет мне быстрее ловить рыбу и не давать ей сорваться с крючка. Выглядит оно немного странно, но попробовать хотя бы раз стоит.$b$bДержи, вот чертежи. Тебе понадобятся блесны, их можно купить у моего ассистента внутри здания. Взрыватель можно приобрести у торговца товарами для инженеров в Городе Механиков. А крысоловки можно найти в Подземном поезде.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возьмите 5 блесен, взрыватель и 3 крысоловки и с помощью чертежей соберите гномский блесн-о-матик.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как там эта новая блесна?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мрачнуру Каменному Клейму в Заброшенный грот Стальгорна.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29351,'Забота о стражниках','Стражники, которые защищают Стальгорн от врагов, каждый день рискуют своими жизнями. Забота об их пропитании лежит на наших плечах. На сегодняшний день их паек включает в себя два любимых блюда дворфов – рулет с потрошками и стальгорнский светлый эль. Не поможешь ли ты мне обеспечить стражников их любимыми продуктами? В таком случае все получат свой паек вовремя, и мы сможем уделить внимание другим задачам.','Раздайте стальгорнский паек 6 стражникам Стальгорна.','Вернитесь к Дерилу Рикнуссуну в "Бронзовый котелок" в Стальгорне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Забота о стражниках',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Стражники, которые защищают Стальгорн от врагов, каждый день рискуют своими жизнями. Забота об их пропитании лежит на наших плечах. На сегодняшний день их паек включает в себя два любимых блюда дворфов – рулет с потрошками и стальгорнский светлый эль. Не поможешь ли ты мне обеспечить стражников их любимыми продуктами? В таком случае все получат свой паек вовремя, и мы сможем уделить внимание другим задачам.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздайте стальгорнский паек 6 стражникам Стальгорна.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дерилу Рикнуссуну в "Бронзовый котелок" в Стальгорне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29352,'Нужны цыплята','О, нет, $n, если мы как можно быстрее не найдем цыплят, произойдет катастрофа... Как же я сварю куриный суп без цыплят? Это просто невозможно!$b$bНо если быстро раздобыть свежих цыплят, я еще успею сварить и суп, и бульон. Поможешь мне? У главного входа в город почти всегда бегает несколько штук. Принеси, скажем, шесть, и мой суп спасен!','Поймайте 6 дунморогских цыплят у входа в Стальгорн.','Вернитесь к Дерилу Рикнуссуну в "Бронзовый котелок" в Стальгорне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нужны цыплята',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','О, нет, $n, если мы как можно быстрее не найдем цыплят, произойдет катастрофа... Как же я сварю куриный суп без цыплят? Это просто невозможно!$b$bНо если быстро раздобыть свежих цыплят, я еще успею сварить и суп, и бульон. Поможешь мне? У главного входа в город почти всегда бегает несколько штук. Принеси, скажем, шесть, и мой суп спасен!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поймайте 6 дунморогских цыплят у входа в Стальгорн.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дерилу Рикнуссуну в "Бронзовый котелок" в Стальгорне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29353,'Рулета с потрошками много не бывает','Рулет с потрошками должен литься рекой. Нет, это, конечно, просто фигура речи, рулеты ведь не текут! Но ты даже представить себе не можешь, что будет, если жителям Стальгорна не хватит потрошков.$b$bЯ как раз занимаюсь приготовлением очередной партии. Мне не хватает пары ингредиентов.$b$bБараньи потроха – именно такие, как мне нужно, – можно купить у Согнара Скалоборода, торговца мясом из Военного квартала. И еще купи пряных трав у любого торговца товарами для кулинарии. А толокно ты сможешь найти в любой таверне или в продуктовых лавках города.','Купите мешок бараньих потрохов, 5 пакетиков пряных трав и 4 мешка толокна.','Вернитесь к Дерилу Рикнуссуну в "Бронзовый котелок" в Стальгорне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рулета с потрошками много не бывает',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Рулет с потрошками должен литься рекой. Нет, это, конечно, просто фигура речи, рулеты ведь не текут! Но ты даже представить себе не можешь, что будет, если жителям Стальгорна не хватит потрошков.$b$bЯ как раз занимаюсь приготовлением очередной партии. Мне не хватает пары ингредиентов.$b$bБараньи потроха – именно такие, как мне нужно, – можно купить у Согнара Скалоборода, торговца мясом из Военного квартала. И еще купи пряных трав у любого торговца товарами для кулинарии. А толокно ты сможешь найти в любой таверне или в продуктовых лавках города.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Купите мешок бараньих потрохов, 5 пакетиков пряных трав и 4 мешка толокна.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дерилу Рикнуссуну в "Бронзовый котелок" в Стальгорне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29354,'Блестящие камешки','Блесна – одна из самых простых, но эффективных рыболовных снастей. Даже самый зеленый новичок с блесной уж что-нибудь да поймает.$b$bА рыбаков в Громовом Утесе в последнее время стало видимо-невидимо. И мои запасы подходят к концу!$b$bМогу ли я попросить тебя об одолжении? Пособирай блестящие камешки у подножия центрального уступа. А потом отнеси их Нахари Заоблачной Охотнице, чтобы она сделала из них блесны.','Соберите 20 блестящих камешков у подножия центрального уступа для Нахари Заоблачной Охотницы.','Какие замечательные камешки! Из них получатся отличные блесны. Спасибо тебе.$B$BПостой… Ках говорил мне, что ты зайдешь и принесешь камешки, и просил передать тебе вот это.','Отнесите камешки Нахари Заоблачной Охотнице в Громовой Утес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Блестящие камешки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Блесна – одна из самых простых, но эффективных рыболовных снастей. Даже самый зеленый новичок с блесной уж что-нибудь да поймает.$b$bА рыбаков в Громовом Утесе в последнее время стало видимо-невидимо. И мои запасы подходят к концу!$b$bМогу ли я попросить тебя об одолжении? Пособирай блестящие камешки у подножия центрального уступа. А потом отнеси их Нахари Заоблачной Охотнице, чтобы она сделала из них блесны.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 20 блестящих камешков у подножия центрального уступа для Нахари Заоблачной Охотницы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Какие замечательные камешки! Из них получатся отличные блесны. Спасибо тебе.$B$BПостой… Ках говорил мне, что ты зайдешь и принесешь камешки, и просил передать тебе вот это.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите камешки Нахари Заоблачной Охотнице в Громовой Утес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29355,'Хлеба с пряностями много не бывает','Ты можешь подумать – ну что особенного в хлебе? – но тем не менее жители Стальгорна с давних пор очень любят хлеб с пряностями. Порой не так-то просто поддерживать его запасы на нужном уровне!$b$bНе хочешь потренироваться в кулинарии и испечь немного хлеба? Заодно и мне поможешь. Все необходимые ингредиенты можно купить у моего брата, Эмруля Рикнуссена. Ты найдешь его внизу.','Приготовьте сами или купите 10 хлебов с пряностями.','Вернитесь к Дерилу Рикнуссуну в "Бронзовый котелок" в Стальгорне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хлеба с пряностями много не бывает',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты можешь подумать – ну что особенного в хлебе? – но тем не менее жители Стальгорна с давних пор очень любят хлеб с пряностями. Порой не так-то просто поддерживать его запасы на нужном уровне!$b$bНе хочешь потренироваться в кулинарии и испечь немного хлеба? Заодно и мне поможешь. Все необходимые ингредиенты можно купить у моего брата, Эмруля Рикнуссена. Ты найдешь его внизу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Приготовьте сами или купите 10 хлебов с пряностями.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дерилу Рикнуссуну в "Бронзовый котелок" в Стальгорне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29356,'Доставка бочонка','Мои запасы стальгорнского светлого эля подходят к концу. К счастью, пивоварня отсюда недалеко и у них всегда найдется несколько бочонков эля для нас.$b$bУ меня сегодня не получится отправиться в Каранос, но, может быть, ты туда сбегаешь и принесешь сюда бочонок? Что скажешь?','Заберите бочонок стальгорнского светлого эля Драгана, который стоит у пивоварни в Караносе, и доставьте его в Стальгорн.','Прекрасно! Я всегда говорю, что Драган – это просто находка! Историк, исследователь, да еще и пиво варит. Есть ли что-то, чего он не умеет?','Вернитесь к Дерилу Рикнуссуну в "Бронзовый котелок" в Стальгорне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Доставка бочонка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мои запасы стальгорнского светлого эля подходят к концу. К счастью, пивоварня отсюда недалеко и у них всегда найдется несколько бочонков эля для нас.$b$bУ меня сегодня не получится отправиться в Каранос, но, может быть, ты туда сбегаешь и принесешь сюда бочонок? Что скажешь?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заберите бочонок стальгорнского светлого эля Драгана, который стоит у пивоварни в Караносе, и доставьте его в Стальгорн.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно! Я всегда говорю, что Драган – это просто находка! Историк, исследователь, да еще и пиво варит. Есть ли что-то, чего он не умеет?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дерилу Рикнуссуну в "Бронзовый котелок" в Стальгорне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29357,'Хлеба с пряностями хоть отбавляй','Разве не удивительно, что такая простая вещь, как хлеб с пряностями, пользуется такой популярностью среди жителей Дарнаса? Его едят каждый день. Когда я не занят чем-то другим, я всегда пеку немного хлеба с пряностями, чтобы не терять навыка.$b$bНе хочешь тоже попробовать? Все необходимые ингредиенты можно купить здесь же в магазине.$b$bСколько бы хлеба мы ни испекли, лишним он не будет. Когда закончишь, принеси свой хлеб сюда. Я поделюсь им с нашими новыми друзьями из Гилнеаса.','Приготовьте сами или купите 10 хлебов с пряностями.','Прекрасный хлеб, Спириткрашер. Надеюсь, выпечка доставляет тебе столько же удовольствия, сколько и мне.','Обожаю аромат свежевыпеченного хлеба, особенно хлеба с пряностями. А ты?','Вернитесь к Элегорну в Дарнас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хлеба с пряностями хоть отбавляй',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Разве не удивительно, что такая простая вещь, как хлеб с пряностями, пользуется такой популярностью среди жителей Дарнаса? Его едят каждый день. Когда я не занят чем-то другим, я всегда пеку немного хлеба с пряностями, чтобы не терять навыка.$b$bНе хочешь тоже попробовать? Все необходимые ингредиенты можно купить здесь же в магазине.$b$bСколько бы хлеба мы ни испекли, лишним он не будет. Когда закончишь, принеси свой хлеб сюда. Я поделюсь им с нашими новыми друзьями из Гилнеаса.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Приготовьте сами или купите 10 хлебов с пряностями.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасный хлеб, Спириткрашер. Надеюсь, выпечка доставляет тебе столько же удовольствия, сколько и мне.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Обожаю аромат свежевыпеченного хлеба, особенно хлеба с пряностями. А ты?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Элегорну в Дарнас.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29358,'Недостаток орехов','Шу\'хало используют кедровые орешки во многих блюдах – добавляют их к мясу, к рыбе, к овощам, даже хлеб с ними пекут и в другую выпечку добавляют.$b$bБлагодаря Матери-Земле САМЫЕ ЛУЧШИЕ кедровые орешки растут на деревьях вот на этих самых плато. Просто подбирай шишки, а затем подержи их над огнем, чтобы они раскрылись.$b$bНе будешь ли ты так $gдобр:добра; собрать немного орешков? Достаточно просто пройтись по округе...','Соберите 30 кедровых орешков, подержав над огнем мулгорские кедровые шишки, затем отнесите их Аске Вестнице Туманов в Громовой Утес.','Как быстро!$B$BЯ прослежу за тем, чтобы эти орешки попали к лучшим поварам и пекарям Громового Утеса.$B$BСпасибо тебе!','Много ли тебе удалось собрать этих прекрасных кедровых орешков?','Вернитесь к Аске Вестнице Туманов в Громовой Утес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Недостаток орехов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Шу\'хало используют кедровые орешки во многих блюдах – добавляют их к мясу, к рыбе, к овощам, даже хлеб с ними пекут и в другую выпечку добавляют.$b$bБлагодаря Матери-Земле САМЫЕ ЛУЧШИЕ кедровые орешки растут на деревьях вот на этих самых плато. Просто подбирай шишки, а затем подержи их над огнем, чтобы они раскрылись.$b$bНе будешь ли ты так $gдобр:добра; собрать немного орешков? Достаточно просто пройтись по округе...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 30 кедровых орешков, подержав над огнем мулгорские кедровые шишки, затем отнесите их Аске Вестнице Туманов в Громовой Утес.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Как быстро!$B$BЯ прослежу за тем, чтобы эти орешки попали к лучшим поварам и пекарям Громового Утеса.$B$BСпасибо тебе!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Много ли тебе удалось собрать этих прекрасных кедровых орешков?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аске Вестнице Туманов в Громовой Утес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29359,'Любимая рыба','Сельдь — самый популярный вид рыбы в Дарнасе. Но не любая сельдь, а только настоящая калдорайская, которая обитает лишь в водах, окружающих Тельдрассил.$B$BЯ стараюсь держать ее про запас, ведь у нее столько различных способов приготовления! Недавно я закончила коптить очередную партию рыбы, так что нужно снова наловить свежей. Не хочешь мне в этом помочь? Калдорайская сельдь водится вблизи деревни Рут\'теран.','Отправляйтесь в деревню Рут\'теран и поймайте 8 калдорайских сельдей.','Спасибо! Что же мне приготовить в этот раз…','Ну что, клюет?','Вернитесь к Астайе в Дарнас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Любимая рыба',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сельдь — самый популярный вид рыбы в Дарнасе. Но не любая сельдь, а только настоящая калдорайская, которая обитает лишь в водах, окружающих Тельдрассил.$B$BЯ стараюсь держать ее про запас, ведь у нее столько различных способов приготовления! Недавно я закончила коптить очередную партию рыбы, так что нужно снова наловить свежей. Не хочешь мне в этом помочь? Калдорайская сельдь водится вблизи деревни Рут\'теран.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в деревню Рут\'теран и поймайте 8 калдорайских сельдей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо! Что же мне приготовить в этот раз…',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, клюет?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Астайе в Дарнас.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29360,'Как насчет того, чтобы добавить мух?','Готовить еду для орков непросто, |3-6($c). Но на этот раз мы будем готовить еду для их потенциальной замены.$b$bНачинать надо с малого – поймать мух. Мухам нравится гниющее мясо. И нам нравится мясо... когда мясные фургоны забрасывают им врагов.$b$bПроверь, не осталось ли в мясных фургонах лишнего мяса. Найдешь мясо – найдешь и мух.$b$bПринеси мне 25 жирных мух, и мы сможем перейти ко второй части нашего кулинарного плана.','Соберите 25 жирных мух с "мяса", лежащего рядом с мясными фургонами. Затем вернитесь к Эвнике Барч в Подгород.','Чудесно! Жирные, неповоротливые, готовые к употреблению. В следующий раз будем ими откармливать наших пауков. А потом пауками попробуем откармливать наших жаб…$B$BТебе не обязательно быть в курсе всех подробностей. Это лишь ступенька на пути к вершинам кулинарного мастерства.','Готова поспорить, что какие-то куски"мяса" там еще вполне съедобны.','Вернитесь к Эвнике Барч в Подгород.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Как насчет того, чтобы добавить мух?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Готовить еду для орков непросто, |3-6($c). Но на этот раз мы будем готовить еду для их потенциальной замены.$b$bНачинать надо с малого – поймать мух. Мухам нравится гниющее мясо. И нам нравится мясо... когда мясные фургоны забрасывают им врагов.$b$bПроверь, не осталось ли в мясных фургонах лишнего мяса. Найдешь мясо – найдешь и мух.$b$bПринеси мне 25 жирных мух, и мы сможем перейти ко второй части нашего кулинарного плана.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 25 жирных мух с "мяса", лежащего рядом с мясными фургонами. Затем вернитесь к Эвнике Барч в Подгород.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Чудесно! Жирные, неповоротливые, готовые к употреблению. В следующий раз будем ими откармливать наших пауков. А потом пауками попробуем откармливать наших жаб…$B$BТебе не обязательно быть в курсе всех подробностей. Это лишь ступенька на пути к вершинам кулинарного мастерства.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Готова поспорить, что какие-то куски"мяса" там еще вполне съедобны.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Эвнике Барч в Подгород.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29362,'"Волшебные" грибочки','Тебе же знакомы Пруды Видений, не правда ли?$b$bВокруг них растут одни грибы... Нет, я говорю не о крепких, больших грибах, которые можно найти повсюду в тех местах, а о маленьких грибочках, которые растут под ними.$b$bОни довольно вкусны, но встречаются редко. Если добавить их к мясу, оно приобретает такой прекрасный вкус, что многие называют блюдо волшебным.$b$bЧто?.. Нет-нет, это совсем не то, о чем ты $gподумал:подумала;. Просто эти грибочки очень вкусные. Вот и все.','Соберите 6 "волшебных" грибочков у Прудов Видений в Громовом Утесе. Отнесите их Аске Вестнице Туманов.','Тебе удалось собрать грибочки?','Вернитесь к Аске Вестнице Туманов в Громовой Утес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','"Волшебные" грибочки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе же знакомы Пруды Видений, не правда ли?$b$bВокруг них растут одни грибы... Нет, я говорю не о крепких, больших грибах, которые можно найти повсюду в тех местах, а о маленьких грибочках, которые растут под ними.$b$bОни довольно вкусны, но встречаются редко. Если добавить их к мясу, оно приобретает такой прекрасный вкус, что многие называют блюдо волшебным.$b$bЧто?.. Нет-нет, это совсем не то, о чем ты $gподумал:подумала;. Просто эти грибочки очень вкусные. Вот и все.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 6 "волшебных" грибочков у Прудов Видений в Громовом Утесе. Отнесите их Аске Вестнице Туманов.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось собрать грибочки?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аске Вестнице Туманов в Громовой Утес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29363,'Мулгорский хлеб с пряностями','Меня часто спрашивают: "Аска, а кто же печет весь этот мулгорский хлеб с пряностями?".$b$bРезонный вопрос! Наш знаменитый изысканный хлеб продается повсюду, в том числе и в очень далеких землях. Его покупают даже наши враги. Настолько он хорош!$b$bА каков ответ?..$b$bПечь хлеб будешь ТЫ. Вот, возьми этот пакетик мулгорских пряностей и преврати с их помощью банальный хлеб с пряностями в МУЛГОРСКИЙ хлеб с пряностями!','Возьмите обычный хлеб с пряностями, мулгорские пряности и приготовьте 5 мулгорских хлебов с пряностями. Обычный хлеб с пряностями вы можете либо купить, либо испечь самостоятельно. Отнесите готовый хлеб Аске Вестнице Туманов в Громовой Утес.','Мулгорский хлеб с пряностями готов?','Вернитесь к Аске Вестнице Туманов в Громовой Утес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мулгорский хлеб с пряностями',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Меня часто спрашивают: "Аска, а кто же печет весь этот мулгорский хлеб с пряностями?".$b$bРезонный вопрос! Наш знаменитый изысканный хлеб продается повсюду, в том числе и в очень далеких землях. Его покупают даже наши враги. Настолько он хорош!$b$bА каков ответ?..$b$bПечь хлеб будешь ТЫ. Вот, возьми этот пакетик мулгорских пряностей и преврати с их помощью банальный хлеб с пряностями в МУЛГОРСКИЙ хлеб с пряностями!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возьмите обычный хлеб с пряностями, мулгорские пряности и приготовьте 5 мулгорских хлебов с пряностями. Обычный хлеб с пряностями вы можете либо купить, либо испечь самостоятельно. Отнесите готовый хлеб Аске Вестнице Туманов в Громовой Утес.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мулгорский хлеб с пряностями готов?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аске Вестнице Туманов в Громовой Утес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29364,'Перемолка зерна','Самый важный продукт в Громовом Утесе – это мука. Вряд ли найдется дом, в котором бы не было муки.$b$bМестные мельницы частенько подвергаются атакам гарпий, гноллов, каких-то безрассудных проходимцев и Мать-Земля знает, кого еще. Поэтому я частенько прошу своих учеников помочь мне перемалывать зерно в муку.$b$bНе хочешь ли помочь и ты?','Помогите жителям Громового Утеса перемолоть зерно в муку.','Вернитесь к Аске Вестнице Туманов в Громовой Утес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Перемолка зерна',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Самый важный продукт в Громовом Утесе – это мука. Вряд ли найдется дом, в котором бы не было муки.$b$bМестные мельницы частенько подвергаются атакам гарпий, гноллов, каких-то безрассудных проходимцев и Мать-Земля знает, кого еще. Поэтому я частенько прошу своих учеников помочь мне перемалывать зерно в муку.$b$bНе хочешь ли помочь и ты?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Помогите жителям Громового Утеса перемолоть зерно в муку.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аске Вестнице Туманов в Громовой Утес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29365,'Самые лучшие продукты','Даже поваренок знает, что для вкусного блюда нужны качественные ингредиенты.$b$bУ меня есть долгосрочные договоренности о поставке продуктов почти со всеми торговцами Громового Утеса, но я хочу посмотреть, как ты справишься с этой задачей – выбрать лучшее из того, что они предлагают.$b$bПожалуйста, обойди их всех и возвращайся с лучшими мясом, рыбой, овощами и травами из местных лавок.','Обойдите торговцев Громового Утеса и принесите Аске Вестнице Туманов самые лучшие мясо, рыбу, овощи и травы.','<Аска рассматривает принесенные вами продукты.>$B$BМмм. Да. Неплохо!$B$BЛучше я бы и сама не смогла выбрать.','Все необходимые продукты у тебя?','Вернитесь к Аске Вестнице Туманов в Громовой Утес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Самые лучшие продукты',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Даже поваренок знает, что для вкусного блюда нужны качественные ингредиенты.$b$bУ меня есть долгосрочные договоренности о поставке продуктов почти со всеми торговцами Громового Утеса, но я хочу посмотреть, как ты справишься с этой задачей – выбрать лучшее из того, что они предлагают.$b$bПожалуйста, обойди их всех и возвращайся с лучшими мясом, рыбой, овощами и травами из местных лавок.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обойдите торговцев Громового Утеса и принесите Аске Вестнице Туманов самые лучшие мясо, рыбу, овощи и травы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Аска рассматривает принесенные вами продукты.>$B$BМмм. Да. Неплохо!$B$BЛучше я бы и сама не смогла выбрать.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Все необходимые продукты у тебя?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аске Вестнице Туманов в Громовой Утес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (29368,'Слежка') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Слежка',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29371,'Время терять','Приветствую, |3-6($c). Раз мы тоже хотим провести церемонию сжигания Плетеного человека, неудивительно, что Орда попытается помешать нашему празднику.$b$bБыло бы благоразумно решить, что мы выше этого, и не обращать внимания на агрессию с их стороны.$b$bЯ восхищаюсь теми, кто способен вести себя так благородно, но ничем не могу им помочь. А вот тем, кто на удар отвечает ударом, я помочь могу. Если это интересует тебя, |3-6($c), то возьми это гасящее вещество и облей им Плетеного человека Орды в Руинах Лордерона.','Отправляйтесь в Руины Лордерона и облейте Плетеного человека гасящим веществом.','Вернитесь к Кире в Штормград.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Время терять',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приветствую, |3-6($c). Раз мы тоже хотим провести церемонию сжигания Плетеного человека, неудивительно, что Орда попытается помешать нашему празднику.$b$bБыло бы благоразумно решить, что мы выше этого, и не обращать внимания на агрессию с их стороны.$b$bЯ восхищаюсь теми, кто способен вести себя так благородно, но ничем не могу им помочь. А вот тем, кто на удар отвечает ударом, я помочь могу. Если это интересует тебя, |3-6($c), то возьми это гасящее вещество и облей им Плетеного человека Орды в Руинах Лордерона.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Руины Лордерона и облейте Плетеного человека гасящим веществом.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кире в Штормград.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29372,'Переполох в захолустье','Шерифа похитили!','Спасите шерифа.','Ты еще не $gнашел:нашла; шерифа?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Переполох в захолустье',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Шерифа похитили!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Спасите шерифа.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Ты еще не $gнашел:нашла; шерифа?',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29373,'Переполох в захолустье','We never paid no heed to Sheriff Blundy, what with his gettin\' all up-in-arms at all times \'bout his "laws" and his "mis-de-meanors." But them dirty ol\' McClintocks, and their cattle-rustlin\' pappy up in Truckshaw ridge done had it up to here with the frequent incarcerations and trials and posse-gatherin\' and dead-or-alive-wantin\', and come this past week they done took the law into their own hands – in the most literal of senses – by haulin\' up and hi-jackin\' the good Sheriff. As you can see, our humble','Спасите шерифа.','Ты еще не $gнашел:нашла; шерифа?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Переполох в захолустье',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','We never paid no heed to Sheriff Blundy, what with his gettin\' all up-in-arms at all times \'bout his "laws" and his "mis-de-meanors." But them dirty ol\' McClintocks, and their cattle-rustlin\' pappy up in Truckshaw ridge done had it up to here with the frequent incarcerations and trials and posse-gatherin\' and dead-or-alive-wantin\', and come this past week they done took the law into their own hands – in the most literal of senses – by haulin\' up and hi-jackin\' the good Sheriff. As you can see, our humble',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Спасите шерифа.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Ты еще не $gнашел:нашла; шерифа?',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29374,'Сбросить бомбы-вонючки','Идиоты-альянсовцы прибегли к помощи ведьм в тщетной попытке атаковать наш город. Что ж, моя сестра всегда говорила мне: "Посмотри на ситуацию с другой стороны".$b$bМы с удовольствием отплатим им той же монетой. Поговори с моей сестрой, она даст тебе метлу для полета над Штормградом. Когда будешь над городом, сбрасывай бомбы-вонючки. Пусть им придется несладко!$b$bМы покажем этим штормградским ведьмам, кто сильнее.','Поговорите с Криной Фэнлоу, затем садитесь на метлу и бросайте бомбы-вонючки на Штормград.','Вернитесь к Кандис Фэнлоу в Руины Лордерона.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сбросить бомбы-вонючки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Идиоты-альянсовцы прибегли к помощи ведьм в тщетной попытке атаковать наш город. Что ж, моя сестра всегда говорила мне: "Посмотри на ситуацию с другой стороны".$b$bМы с удовольствием отплатим им той же монетой. Поговори с моей сестрой, она даст тебе метлу для полета над Штормградом. Когда будешь над городом, сбрасывай бомбы-вонючки. Пусть им придется несладко!$b$bМы покажем этим штормградским ведьмам, кто сильнее.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Криной Фэнлоу, затем садитесь на метлу и бросайте бомбы-вонючки на Штормград.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кандис Фэнлоу в Руины Лордерона.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29375,'Уборка в Подгороде','Здравствуй, |3-6($c)! Тебе нравится Тыквовин? Похоже, что после того, как мы сбросили бомбы-вонючки на Штормград, Альянс решил отплатить нам той же монетой.$b$bК счастью, в нашем распоряжении магия, которая может справиться со всей этой вонью. Воспользуйся чародейским нейтрализатором, чтобы убрать бомбы и вонь.','Воспользуйтесь чародейским нейтрализатором и очистите Подгород от бомб-вонючек.','Сначала я не замечала запаха, но я и не ожидала сильной магии от ведьм Альянса. Однако орки-стражники очень жаловались, так что они-то уж точно оценят твои усилия.','Вернитесь к Кандис Фэнлоу в Руины Лордерона.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уборка в Подгороде',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Здравствуй, |3-6($c)! Тебе нравится Тыквовин? Похоже, что после того, как мы сбросили бомбы-вонючки на Штормград, Альянс решил отплатить нам той же монетой.$b$bК счастью, в нашем распоряжении магия, которая может справиться со всей этой вонью. Воспользуйся чародейским нейтрализатором, чтобы убрать бомбы и вонь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь чародейским нейтрализатором и очистите Подгород от бомб-вонючек.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сначала я не замечала запаха, но я и не ожидала сильной магии от ведьм Альянса. Однако орки-стражники очень жаловались, так что они-то уж точно оценят твои усилия.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кандис Фэнлоу в Руины Лордерона.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29376,'Время созидать','Мы сжигаем Плетеного человека, как знак нашей борьбы с теми, кто выступает против нас. Мы раскрашиваем лица пеплом, что символизирует нашу нескончаемую борьбу с теми, кто хочет поработить нас.$b$bВоспользуйся костром и подожги Плетеного человека. Потом возьми пепел и раскрась им лицо.$b$bПусть все это напомнит нашим врагам о том, что мы никогда не сдадимся.','Воспользуйтесь большим костром, чтобы поджечь Плетеного человека. Потом воспользуйтесь пеплом, который появится на земле возле Плетеного человека.','Пришло время Отрекшихся! Власть Отрекшимся! Сейчас и навсегда!','Вернитесь к зовущей Тьму Янке в Руины Лордерона.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Время созидать',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы сжигаем Плетеного человека, как знак нашей борьбы с теми, кто выступает против нас. Мы раскрашиваем лица пеплом, что символизирует нашу нескончаемую борьбу с теми, кто хочет поработить нас.$b$bВоспользуйся костром и подожги Плетеного человека. Потом возьми пепел и раскрась им лицо.$b$bПусть все это напомнит нашим врагам о том, что мы никогда не сдадимся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь большим костром, чтобы поджечь Плетеного человека. Потом воспользуйтесь пеплом, который появится на земле возле Плетеного человека.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Пришло время Отрекшихся! Власть Отрекшимся! Сейчас и навсегда!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к зовущей Тьму Янке в Руины Лордерона.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29377,'Время разрушать','Приветствую тебя, |3-6($c)! Нет никаких сомнений, что когда мы будем проводить церемонию сожжения Плетеного человека, Альянс попытается испортить нам праздник.$b$bНо у нас есть возможность отплатить им той же монетой. Если хочешь нам помочь, возьми это гасящее вещество и потуши Плетеного человека Альянса, который стоит перед вратами Штормграда.$b$bПотуши их огонь и порадуйся их несчастью, |3-6($c).','Отправляйтесь в Штормград и облейте Плетеного человека гасящим веществом.','Значит, все получилось. Это лишь короткая задержка, но если она испортит им настроение, то, значит, оно того стоило.$B$BЯ рассказала детям о том, что ты сделал, они в восторге. Устроенный тобою беспорядок в стане врага доставил им огромное удовольствие. Ох уж эти маленькие негодники...$B$BОни просили передать тебе вот это. Наслаждайся, Шумныйдру.','Вернитесь к зовущей Тьму Янке в Руины Лордерона.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Время разрушать',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приветствую тебя, |3-6($c)! Нет никаких сомнений, что когда мы будем проводить церемонию сожжения Плетеного человека, Альянс попытается испортить нам праздник.$b$bНо у нас есть возможность отплатить им той же монетой. Если хочешь нам помочь, возьми это гасящее вещество и потуши Плетеного человека Альянса, который стоит перед вратами Штормграда.$b$bПотуши их огонь и порадуйся их несчастью, |3-6($c).',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Штормград и облейте Плетеного человека гасящим веществом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Значит, все получилось. Это лишь короткая задержка, но если она испортит им настроение, то, значит, оно того стоило.$B$BЯ рассказала детям о том, что ты сделал, они в восторге. Устроенный тобою беспорядок в стане врага доставил им огромное удовольствие. Ох уж эти маленькие негодники...$B$BОни просили передать тебе вот это. Наслаждайся, Шумныйдру.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к зовущей Тьму Янке в Руины Лордерона.',`completedtext_loc8`);
